MultiLanguageQuestData['de'][4112] = {title = "Salbe durch Entzauberung", objective = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", description = nil, progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, &lt;Name&gt;. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][4113] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4114] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4115] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4116] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4117] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4118] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4119] = {title = "Verderbter Nachtdrache", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4120] = {title = "Die Kraft der Verderbnis", objective = "Talo Dornhuf im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt.", description = "Als Jäger strebe ich danach, die Stärken nachzuahmen, die ich bei meinen Gegnern sehe. Man kann den Kampf zu seinen Gunsten wenden, indem man einfach seinen Feind gut kennt, <Name>.\n\nAn einem Ort namens Teufelswald, nördlich des Eschentals, wurden die Kreaturen durch dämonische Energien verderbt. Die Bären und Wölfe wurden von ihnen verrückt, allerdings glaube ich, dass sie dadurch auch noch stärker geworden sind.\n\nGeht, <Name>. Reist zum Teufelswald und tretet den Bestien gegenüber. Erfahrt selbst, ob sie wirklich so stark sind, wie ich glaube.", progress = nil, completion = "Nach Euren Beschreibungen klingt es, als würden die Kreaturen eine gedankenlose Wildheit an den Tag legen...\n\nBleibt wachsam, &lt;Name&gt;! Es könnte in Eurem Interesse sein, mehr über diese Verderbnis zu erfahren. Kennt immer Euren Feind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4121] = {title = "Gefährliche Zwickmühle", objective = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die Brennende Steppe und durch den Schwarzfels in die Sengende Schlucht.\n\nEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen.", description = "Glaubt Ihr wirklich, dass Ihr es mit mir als Gefangenem zum vereinbarten Treffpunkt schafft? Habt Ihr wirklich gedacht, Ihr könntet in eine schwer bewachte Festung des Schwarzfelsklans eindringen und völlig unbemerkt ihren wertvollsten Besitz entführen?\n\nMan wird Euch vernichten!", progress = "Ich übernehme diesen dreckigen Verräter, <Name>.", completion = "Eure Heldentaten sollen nicht unbeachtet bleiben, &lt;Name&gt;. Diesen Tribut habt Ihr Euch verdient. Der Kriegsherr wird jetzt mit Euch über die letzte Aufgabe sprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4122] = {title = "Grark Lorkrub", objective = "Begebt Euch in die Brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung des Schwarzfelsklans gesehen worden.\n\nWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Schwarzfels in die Sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nBereitgestellter Gegenstand: \n", description = "Ich habe ihn durch die ganze Sengende Schlucht, durch den Berg und in die Brennende Steppe hinein verfolgt. Der Verräter wurde auf frischer Tat dabei ertappt, wie er den Schwarzfelsorcs wichtige Informationen über die tagtäglichen Vorgänge bei uns lieferte. Ich spreche von Grark Lorkrub.\n\nEr sitzt jetzt in der Brennenden Steppe, sicher unter deren Schutz - glaubt er jedenfalls.\n\nNehmt diese Fesseln, <Name>. Findet Grark, legt ihm die Fesseln an und führt ihn durch den Schwarzfels. Wenn Ihr das tut, ist ein Tribut Euer.", progress = nil, completion = "Seht Ihr denn nicht, welche Macht wir gewinnen, wenn wir uns der Blackrocklegion anschließen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4123] = {title = "Das Herz des Berges", objective = "Bringt das 'Herz des Berges' zu Maxwort Funkelglanz in der Brennenden Steppe.", description = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum unteren Gewölbe der Schwarzfelstiefen durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, &lt;Name&gt;, nehmt dies als Bezahlung an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4124] = {title = "Der vermisste Kurier", objective = "Sprecht mit Ginro Herdfeuer in der Mondfederfeste.", description = "Einer meiner Kollegen, Ginro Herdfeuer, braucht Hilfe und Informationen über den Aufenthaltsort eines Kuriers und der Pakete, die er bei sich hatte. Es ist etwa eine Woche her, dass der Kurier verschwunden ist; unsere eigene Suche hat nichts ergeben und wir wissen nicht, was wir noch tun sollen. Leider musste ich den Kurier für vermisst erklären.\n\nWenn Ihr freie Zeit und Kapazitäten habt, dann sprecht doch bitte mit Ginro. Er sollte irgendwo hier in der Festung sein, vielleicht in seinem Quartier.", progress = nil, completion = "Ich nehme an, Latro hat Euch geschickt. Ich glaube zwar inzwischen, dass es aussichtslos ist, aber ich nehme trotzdem gern jede Hilfe in Anspruch, die Ihr mir geben könnt. Ich muss zugeben... ich werde erleichtert sein, wenn ich diese Sache endlich vergessen kann. Jeden Tag gehe ich in die Wildnis Feralas' hinaus und suche dort nach einem Zeichen von Raschal. Und jeden Abend komme ich heim mit nichts in der Hand als Gnollzähnen und Enttäuschung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4125] = {title = "Der vermisste Kurier", objective = "Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas.", description = "Es ist etwa eine Woche her, seit der Kurier Raschal sich nach Thalanaar aufgemacht hat. Er kennt Feralas gut; er ist schon bei uns, seit General Mondfeder das Expeditionskorps hergeführt hat. Ich weiß, dass er vorhatte, mit einem Ruderboot die Küste entlangzufahren und Feralas im Süden zu durchqueren, um das Lager der Horde zu umgehen.\n\nIch konnte sein Boot nicht finden, aber vielleicht findet Ihr es ja. Vielleicht liegt es irgendwo versteckt...oder vielleicht wurde es auch versenkt. Wie dem auch sei, möglicherweise enthält es einen Hinweis darauf, wo Raschal ist. Wenn Ihr irgendetwas entdeckt, lasst es mich bitte wissen.", progress = nil, completion = "Ihr habt etwas gefunden, das wie ein havariertes Ruderboot aussieht. Durch das etwas schlammige Wasser seht Ihr backbords etliche klaffende Löcher: Das ganze Boot ist fast bis auf sein einfaches hölzernes Grundgerüst zerfetzt. Was auch immer dieses Boot so zugerichtet hat, muss versucht haben, es entzweizubrechen. Steuerbords ist das Boot mit einem kleinen Wappen der Festung Feathermoon bemalt.\n\nIm Matsch am Boden des Bootes seht Ihr etwas metallisch aufblitzen ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4126] = {title = "Hurley Pestatem", objective = "Bringt Ragnar Donnerbräu in Kharanos das verlorene Donnerbräurezept.", description = "Die Dunkeleisenzwerge, angeführt von dem Bösewicht Hurley Pestatem, haben eines der besten Rezepte der Donnerbräus gestohlen, jenes für das Donnerbräu Lagerbier. Diese Schurken! Sie verdienen ein solch edles Gebräu nicht!\n\n<Name>, ich habe eine schwierige Aufgabe für Euch. Geht zu den Schwarzfelstiefen in der Brennenden Steppe, zerstört alle Fässer mit Donnerbräu Lagerbier, die Ihr finden könnt, und bringt unser Donnerbräurezept zurück!\n\nBitte, bringt das Rezept unbedingt zurück, und wenn Ihr dafür die ganzen Schwarzfelstiefen umkrempeln müsstet!", progress = "Habt Ihr das Rezept, <Name>? Ich kann es nicht ertragen, dass diese Dunkeleisenzwerge sich an dem Stammgetränk meiner Familie laben!", completion = "Ihr habt es gefunden! Gut gemacht! Und ich hoffe, dass Ihr diesen Dunkeleisenzwergen und Hurley Pestatem eine ordentliche Abreibung verpasst habt!\n\nDie Donnerbräus stehen Euch jederzeit zu Diensten, &lt;Name&gt;! Ihr seid der Held des Tages!", rewards = "HurtigschlagknüppelGliedmaßenspaltbeilIhr bekommt:\n\nDunkles zwergisches Lagerbier"}
MultiLanguageQuestData['de'][4127] = {title = "Havarie", objective = "Kehrt zur Mondfederfeste zurück und zeigt Ginro Herdfeuer das gefundene Messer.", description = "Als Ihr mit der Hand durch den Matsch fahrt, fühlt Ihr plötzlich den Griff eines Messers unter Euren Fingern. Es sieht gut gepflegt aus und dürfte mit Sicherheit jemandem gehört haben, der auf dem Boot gewesen ist. Vielleicht hat das große Stück des verschwundenen Bootes irgendetwas mit seinem Verschwinden zu tun.\n\nIhr nehmt das Messer an Euch, denn Ginro Herdfeuer in der Mondfederfeste hatte Euch angewiesen, ihm jegliche Hinweise sofort zu bringen. Allerdings werdet Ihr das ungute Gefühl nicht los, dass Ihr in diesem Gewässer nicht allein seid...", progress = "Ah, da seid Ihr ja wieder, <Name>. Ich hoffe, dass Ihr etwas über Raschals Schicksal erfahren habt, so tragisch es auch sein mag.", completion = "Interessant... Ich glaube, das ist Raschals Messer. Ihr sagt, Ihr habt es auf dem Grund des Gewässers zusammen mit seinem Boot entdeckt? Tja, die Entdeckung des Messers allein wird nicht reichen, um Raschals Verschwinden zu erklären. Uns steht jedoch noch eine etwas unkonventionelle Methode zur Verfügung, mit der wir versuchen können, etwas herauszufinden.\n\nHabt Ihr schon mal von Psychometrie gehört?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4128] = {title = "Ragnar Donnerbräu", objective = "Sprecht mit Ragnar Donnerbräu.", description = "Hallo, <Name>. Wie ich hörte, soll Ragnar Donnerbräu außer sich vor Wut sein, dass jemand sein Bier gestohlen hat. Er sucht nach wackeren Abenteurern und ist gewillt, sie reichlich zu entlohnen.\n\nSprecht mit Ragnar, wenn Ihr Interesse habt. Ihr findet ihn in der Brauerei Donnerbräu in Kharanos in Dun Morogh.", progress = nil, completion = "Ich bin in der Tat fuchsteufelswild! Man hat mich beraubt! Eines der Rezepte unserer Familie wurde gestohlen! Wie können sie es wagen! Als hätte ich nicht schon Grund genug, die Dunkeleisenzwerge zu hassen! Aber jetzt, oh... jetzt sind sie dran!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4129] = {title = "Das wieder aufgetauchte Messer", objective = "Bringt Quintis Lebenshand in der Mondfederfeste das gefundene Messer.", description = "Der Hausdruide der Festung, Quintis Lebenshand, verfügt über ein paar... ungewöhnliche Fertigkeiten. Eine davon ist die Psychometrie - die Fähigkeit, durch Berührung eines Objekts etwas über seine Geschichte zu erfahren. Fragt mich nicht, wie er das bewerkstelligt. Es muss etwas mit Magie zu tun haben, wovon ich nichts verstehe und womit ich auch nichts zu tun haben will. Zwei Dinge weiß ich jedoch: Erstens, ich habe gesehen, dass es funktioniert, und zweitens, der Gauner schuldet mir etwas.\n\nQuint lebt in einem kleinen Baumhaus. Bringt ihm das Messer und richtet ihm von mir aus, dass seine Kalimdor-Poker-Schulden bei mir beglichen sind, wenn er seinen Hokuspokus bei dem Messer wirkt.", progress = "Ach nein, also Ginro schickt Euch? Na ja...\n\nPsychometrie zehrt ziemlich an der Psyche... aber meine Verluste beim Kalimdor-Poker auch. Hier in der Festung nennt man mich den 'König der schlechten Karten'. Pech im Spiel... Glück im Umgang mit den Geheimnissen der Natur, könnte man sagen.\n\nWie dem auch sei, natürlich tu ich es. Das könnte genau der Durchbruch sein, den wir brauchen, um etwas über Raschals Schicksal in Erfahrung zu bringen. Wenn Ihr mir das Messer gebt, können wir gleich anfangen.", completion = "Ich danke Euch, &lt;Name&gt;.\n\nPsychometrie ist zwar nicht einmal im weitläufigsten Sinn eine exakte Kunst, doch habe ich mich ihrer manchmal bedient, um in Situationen, in denen andere schon längst aufgegeben haben, Erleuchtung zu finden. Ich glaube, wenn ich sie bei dem Messer anwende, das Ihr gefunden habt, könnte uns das einen Hinweis darauf geben, was aus Raschal geworden ist.\n\nEs wird nur einen Moment dauern, aber es ist eine für den Zaubernden nicht gerade angenehme Angelegenheit. Habt Nachsicht mit mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4130] = {title = "Psychometrie-Sitzung", objective = "Sprecht mit Ginro Herdfeuer in der Mondfederfeste.", description = "Entschuldigt bitte, mir ist immer noch ein bisschen schwummrig. Wie dem auch sei, ich hatte ein paar nützliche Visionen.\n\nRaschal nimmt zwei lederne Rucksäcke aus seinem Boot und geht landeinwärts. Dann jedoch kehrt er zu seinem Boot zurück. Ich sehe Gnollskalps... er ist auf ein paar Gnolle gestoßen - Waldpfoten nennt man sie, glaube ich. Er ist sehr besorgt - fast schon panisch - wegen etwas. Und das so sehr, dass er nicht bemerkt, wie sich Wasserelementare hinter seinem Rücken manifestieren. Hier enden die Visionen.\n\nIch muss mich ausruhen, tut mir leid, <Name>. Erzählt Gin, was ich gesehen habe. Er muss das wissen.", progress = nil, completion = "Vielen Dank, dass Ihr mir von Quints Visionen berichtet habt, &lt;Name&gt;. Ich werde vielleicht ein bisschen großzügiger bei ihm sein, wenn wir uns das nächste Mal zu einem Kartenspiel zusammensetzen.\n\nRaschal kann in einem Kampf seinen Mann stehen und Gnolle sind nichts, was ihm Sorgen bereiten oder gar in Panik versetzen könnte. Vielleicht ist diese neue Information ja hilfreich für Euch und bringt Euch den Durchbruch, den wir so dringend benötigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4131] = {title = "Die Waldpfotengnolle", objective = "Durchsucht die Lager der Waldpfotengnolle im Süden von Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten.", description = "Unsere 'Freunde', die Waldpfoten, mögen Raschal am Ende vielleicht zwar erwischt haben, aber irgendwie habe ich das Gefühl, als hätte sich da etwas anderes ereignet. Wie dem auch sei, es dürfte allerdings der beste Anhaltspunkt sein, um mit der Suche zu beginnen.\n\nIch wünschte nur, ich wüsste genauer, was zu tun ist, aber momentan kann ich lediglich sagen: 'Durchsucht die Lager der Waldpfoten. Macht Euch auf den Weg.' Ich weiß, dass Gnolle Gegenstände, die sie ergattern, behalten und um sie zanken. Vielleicht haben sie ja auch die Rucksäcke gefunden, die Quint erwähnte. Ohne Quints Visionen hätte ich bei früheren Suchaktionen niemals eine direkte Konfrontation mit ihnen gesucht, aber jetzt würde ich sagen: Auf sie mit Gebrüll!", progress = nil, completion = "An einen Baum in der Nähe sind zwei große Lederrucksäcke genagelt. Beide tragen auf der Vorderseite klein die Insignien der Festung Feathermoon...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4132] = {title = "Operation: Tod dem Zornesschmied", objective = "Begebt Euch zu den Schwarzfelstiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Bluthauer zurück, sobald Ihr diese Aufgabe erledigt habt.", description = "Ihr habt bemerkenswerte Arbeit geleistet, <Name>. Jetzt ist es an der Zeit, Euch auf Eure letzte Mission zu schicken.\n\nGeneral Zornesschmied, der für die Koordination der Angriffe auf die 109. Division des KEK und die massive Dezimierung unserer Truppen verantwortliche Dunkeleisenzwerg, muss zur Rechenschaft gezogen werden.\n\nDies wird zweifellos Eure schwerste Mission werden, aber solltet Ihr erfolgreich sein, wird man Euch reich entlohnen.", progress = nil, completion = "Endlich! Der Bösewicht hat seine gerechte Strafe erhalten! Ihr seid ein bemerkenswertes Individuum, &lt;Name&gt;. Tragt dieses Medaillon als Symbol Eures unerschütterlichen Engagements zum Wohle der Horde und des KEK.", rewards = "Ihr bekommt:\n\nMedaillon des Eroberers"}
MultiLanguageQuestData['de'][4133] = {title = "Vivian Lagrave", objective = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath.", description = "Schattenmeisterin Vivian Lagrave benötigt Eure Dienste. Sie lebt im Ödland, im orcischen Außenposten Kargath, wo sie dem Gerücht nachgeht, nach dem die Dunkeleisenzwerge der Schwarzfelstiefen angeblich ein bestimmtes Gebräu herstellen.\n\nSprecht mit Vivian. Sie erwartet Euch.", progress = nil, completion = "Vielen Dank, dass Ihr gekommen seid, &lt;Name&gt;. Dieser Ort entbehrt nicht eines gewissen rauen Charmes, aber es mangelt an den Annehmlichkeiten des Apothekariums.\n\nDoch genug geplaudert. Kommen wir zum Geschäft, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4134] = {title = "Verlorenes Donnerbräurezept", objective = "Bringt Vivian Lagrave in Kargath das verlorene Donnerbräurezept.", description = "Es geht das Gerücht umher, dass der Dunkeleisenzwerg Hurley Pestatem ein Rezept zum Brauen von Bier gestohlen habe. Dieses Bier, das Donnerbräu Lagerbier, soll angeblich jeden, der es trinkt, mit großer Kraft und Mut erfüllen. Wir möchten dieses Getränk gern untersuchen. Vielleicht finden wir ja noch andere Anwendungsgebiete für seine Vorzüge... Anwendungsgebiete, die eher im Einklang mit den Zielen der Verlassenen sind.\n\nDurchforstet die Schwarzfelstiefen, findet Hurley, nehmt das Donnerbräurezept von ihm und bringt es mir.\n\nUnd um ihn zu finden, müsst Ihr ihn möglicherweise locken, indem Ihr sein wertvolles Bier bedroht.", progress = "Habt Ihr das Donnerbräurezept, <Name>?", completion = "Sehr gut. Ich schicke dieses Rezept zu Studienzwecken zum Apothekarium, wo man ihm schon bald seine Geheimnisse entlocken wird. Eines Tages werden die Zwerge der Allianz die Vorzüge dieses Getränks am eigenen Leib zu spüren bekommen!\n\nIch finde das höchst amüsant. Vielleicht hat der Tod Auswirkungen auf den Sinn für Humor ... was meint Ihr?", rewards = "HurtigschlagknüppelGliedmaßenspaltbeilIhr bekommt:\n\nÜberragender HeiltrankGroßer Manatrank"}
MultiLanguageQuestData['de'][4135] = {title = "Die Gewundene Tiefe", objective = "Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der Gewundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen.\n\nBereitgestellter Gegenstand: \n", description = "In den Rucksäcken befinden sich zwei Gegenstände: Der erste ist ein für Thalanaar bestimmtes Paket mit Waren, der zweite eine hastig hingekritzelte Notiz, die an einen unbekannten Empfänger gerichtet ist.\n\nDie Notiz spricht von der Entdeckung heimtückischer käferartiger Kreaturen südlich des Gnoll-Lagers an einem Ort, der Gewundene Tiefe genannt wird. Der Verfasser wollte die Sache persönlich untersuchen, da er dies als ernsthafte Bedrohung für ganz Feralas befand. Die Notiz ist mit 'Raschal von Mondfeder' unterzeichnet.\n\nOffenbar habt Ihr jetzt herausgefunden, wohin Raschal letztlich verschwunden ist.", progress = nil, completion = "Ihr habt eine große Kapsel fremdartigen Ursprungs entdeckt. Die Oberfläche der Kapsel wirkt schleimig, doch an manchen Stellen ragen gehärtete Vorsprünge heraus. Die Kapsel selbst ist hoch und tief genug, dass ein humanoides Wesen leicht darin Platz finden könnte ... und anhand des humanoid anmutenden Umrisses der Gestalt darin, die durch die dünne Haut der Kapsel sichtbar ist, nehmt Ihr an, dass es tatsächlich ein solches Wesen ist, das darin verborgen liegt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4136] = {title = "Ribbly Schraubstutz", objective = "Bringt Yuka Schraubstutz in der Brennenden Steppe Ribblys Kopf.", description = "Mein Bruder Ribbly hat unserer Familie schon immer auf der Tasche gelegen, unser Geld genommen und es für eine Dummheit nach der anderen ausgegeben.\n\nTja, seine letzte Dummheit muss wohl seine bislang schlimmste gewesen sein, denn Baron Revilgaz von Beutebucht hat ein Kopfgeld auf den armen Ribbly ausgesetzt. Ich kann Euch gar nicht sagen, wie glücklich das die Schraubstutzs macht! Endlich ist unser kleiner Ribbly mal etwas wert!\n\nEr versteckt sich jetzt allerdings ganz weit unten in den Schwarzfelstiefen. Sucht ihn doch bitte und bringt ihn zu mir!\n\nUnd falls er nicht mitkommen will, ist das auch kein Problem...bringt mir einfach seinen Kopf.", progress = "Habt Ihr Ribbly mitgebracht? Oder zumindest einen Teil von ihm?", completion = "Aha! Ihr habt ihn gefunden! Und wie mir scheint, wollte mein kleiner Bruder offenbar nicht freiwillig mitkommen. Wie schade. Ich hätte zu gern sein Gesicht gesehen, wenn ich ihm von unserem Plan, ihn Revilgaz auszuliefern, erzählt hätte.\n\nDanke, &lt;Name&gt;. Ihr habt meine Familie sehr glücklich gemacht. Und Ribbly hat nie so friedlich ausgesehen wie jetzt.", rewards = "GrollstiefelBußwerkschiftungStahlschienenrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4141] = {title = "Muigin und Larion", objective = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück.", description = "Seht Ihr Larion da drüben? Es ist SEINE Schuld, dass wir hier sind!\n\nIch hab ihm noch gesagt, dass wir in die falsche Richtung gehen, aber hat er auf mich gehört? Und stellt Euch vor, jetzt spricht er nicht mehr mit mir. Na ja, erlauben wir uns doch ein kleines Späßchen mit ihm, bis er es sich anders überlegt.\n\nSind Euch die seltsamen pflanzenartigen Kreaturen in dieser Gegend hier aufgefallen? Die machen nichts als Ärger, wirklich, aber ich glaube, wenn man sie ordentlich abrichten würde, könnte man sie dazu bringen, Befehlen zu gehorchen.\n\nAls Erstes bräuchte ich allerdings ein paar davon, um sie zu studieren. Meint Ihr, Ihr könntet mir ein paar bringen?", progress = "Larion kann sich auf was gefasst machen, das steht mal fest!", completion = "Ich hoffe, sie haben Euch nicht zu viel Ärger bereitet, &lt;Name&gt;. Ich versuche immer, ihnen aus dem Weg zu gehen - sie sind mir einfach zu wild!\n\nEinmal wollte ich über eine drüberspringen... Da griff sie mich an. Das ist doch kein Benehmen für eine Pflanze!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4142] = {title = "Ein Besuch bei Gregan", objective = "Bringt Gregan Hopfenspei in Feralas eine Blutblüte.", description = "Ich weiß nicht so recht, was ich davon halten soll, <Name>. Die Pflanzen... sie scheinen ein gewisses Maß an Intelligenz zu besitzen.\n\nAllerdings bin ich auf diesem Gebiet kein Experte. Aber ich kenne einen!\n\nGeht nach Nord-Feralas und sucht einen Freund von mir auf, er heißt Gregan Hopfenspei. Er kennt sich mit solchen Dingen bestens aus.\n\nGregan kann uns bestimmt weiterhelfen. Ihr findet ihn draußen in der Wildnis, denn für das Großstadtleben hat er nicht viel übrig.", progress = "Ich lebe hier draußen im Wald... Es ist so friedlich hier.\n\nNa, wenigstens dachte ich das. Ich bekomme hier draußen mehr Besuch als damals, als ich noch in Ironforge wohnte!", completion = "Eine Blutblüte was? Hmmm... Tja, Ihr solltet mir lieber mal erklären, was Ihr vorhabt, dann sage ich Euch, ob ich Euch helfen kann oder nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4143] = {title = "Der Dunst des Bösen", objective = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Krater von Un'Goro.", description = "Um ehrlich zu sein, <Name>, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...\n\nEgal, ich weiß vermutlich, was Muigin benötigt - Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.\n\nIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tieflauerern, Düsterwürmern oder Schlammen, die man dort findet. Viel Glück, <Name>!", progress = "Larion spricht immer noch nicht mit mir! Wie kann man nur so nachtragend sein!", completion = "Ich muss gestehen, dass ich das Zeug nur sehr ungern anfasse, &lt;Name&gt;! Aber wenn Gregan sagt, dass es funktioniert, dann will ich es mal ausprobieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4144] = {title = "Blutblütensprösslinge", objective = "Das ist mein Plan, <Name>: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.\n\nIhr haltet mich vielleicht für rachsüchtig... Und damit liegt Ihr absolut richtig! \n\nDie Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!\n\nUnd nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!", description = nil, progress = "Das ist mein Plan, <Name>: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.\n\nIhr haltet mich vielleicht für rachsüchtig ... Und damit liegt Ihr absolut richtig! \n\nDie Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!\n\nUnd nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!", completion = "Dann mal los, &lt;Name&gt;! Damit werden wir Larions Aufmerksamkeit erringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4145] = {title = "Larion und Muigin", objective = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marschalls Zuflucht.", description = "Seht Ihr Muigin da drüben? Es ist SEINE Schuld, dass wir uns verirrt haben!\n\nIch kannte den richtigen Weg, aber er bestand darauf, eine Abkürzung zu nehmen, und so sind wir hier gelandet!\n\nUnd um die Lage noch zu verschlimmern, schickt er mir jetzt auch noch seine verrückten Pflanzen, um mich zu ärgern. Ich bin so wütend, dass ich bis auf weiteres kein Wort mehr mit ihm reden werde, aber diese Quälgeister sind wirklich unerträglich.\n\nWarum versuchen wir nicht als Erstes, seinen Bestand ein bisschen zu dezimieren? Geht hinaus und jagt einige Blutblüten und kehrt dann zu mir zurück.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Name&gt;, aber ich fürchte, ich habe schlechte Neuigkeiten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4146] = {title = "Treibstoff für die Unkrautvernichtung", objective = "Bringt Larion in Marschalls Zuflucht den ungeladenen Unkrautvernichter und 5 Proben Dunst der Atal'ai.", description = "Ihr habt Glück, <Name>! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet, eines davon ist ein Unkrautvernichter mit kurzer Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.\n\nIhr könnt gern einen meiner Prototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Vernichter benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tieflauerern, Düsterwürmern oder Schlammen.", progress = "Das kann einen echt fertig machen, <Name>. Diese Biester lassen mich einfach nicht in Ruhe!", completion = "Marvon war also nicht da, eh? Na ja, zeigt mir trotzdem, was Ihr da habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4147] = {title = "Marvons Werkstatt", objective = "Reist zu Marvon Nietensuchers Werkstatt in Ratschet.", description = "Ich habe herausgefunden, was Muigin so treibt. Er züchtet da drüben doch tatsächlich diese verdammten Dinger!\n\nIch glaube, die einzige Lösung des Problems besteht darin, mit... nein, nicht mit ihm zu sprechen... Was für ein Blödsinn! Die Lösung ist zurückzuschlagen!\n\nWir brauchen die Hilfe meines Freundes Marvon, der in Ratschet eine Werkstatt hat. Er kann bestimmt irgendein Gerät zusammenbasteln, das uns helfen wird.", progress = nil, completion = "Marvon ist schon eine ganze Weile fort, &lt;Name&gt;. Er wollte nach Tanaris, um dort ein paar der alten Troll-Ruinen zu untersuchen.\n\nAlso, was wolltet Ihr doch noch gleich?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4148] = {title = "Blutblütenvernichter", objective = "Damit der Schrumpfer funktioniert, brauchen wir ein Exemplar der Kreaturen, für die er eingestellt werden soll. Geht zum Krater und holt einen Blutblütensprössling. Dann kann ich ihn so einstellen, dass er bei Muigins kleinen Freunden funktioniert...\n\nWenn der Typ nicht so stur wäre, könnten wir alle schon längst auf dem Heimweg sein. Aber jetzt muss ich ihm erst einmal beweisen, dass mir seine Faxen nicht das Geringste ausmachen!", description = nil, progress = "Damit der Schrumpfer funktioniert, brauchen wir ein Exemplar der Kreaturen, für die er eingestellt werden soll. Geht zum Krater und holt einen Blutblütensprössling. Dann kann ich ihn so einstellen, dass er bei Muigins kleinen Freunden funktioniert...\n\nWenn der Typ nicht so stur wäre, könnten wir alle schon längst auf dem Heimweg sein. Aber jetzt muss ich ihm erst einmal beweisen, dass mir seine Faxen nicht das Geringste ausmachen!", completion = "Sieht aus, als würde es perfekt funktionieren, &lt;Name&gt;. Und nicht vergessen: Benutzt diesen Schrumpfer, sobald Ihr auf einen dieser Plagegeister stoßt!", rewards = "Ihr bekommt:\n\nBlutblütenvernichter"}
MultiLanguageQuestData['de'][4161] = {title = "Rezept der Kaldorei", objective = "Sammelt 7 kleine Spinnenbeine.", description = "Vor langer Zeit nannte man die Nachtelfen 'Kaldorei', was übersetzt 'Kinder der Sterne' bedeutet. Für Euch als <Klasse> ist es besonders wichtig, etwas über die Vergangenheit zu erfahren, also hört gut zu, was ich Euch zu sagen habe, <Name>.\n\nDie Kaldorei waren schon immer stolz auf ihre harmonische Beziehung zur Natur. Das bedeutet, dass wir von der Natur nur nehmen, was notwendig ist, und es in gleichem Maße vergelten. Dieses Gleichgewicht bedeutet uns viel, <Name>.\n\nGeht und sammelt sieben kleine Spinnenbeine - und nicht mehr, und kommt dann zu mir zurück.", progress = "Denkt an das Gleichgewicht, <Name>. Ich möchte, dass Ihr das Leben im Wald verstehen lernt und Einfühlungsvermögen dafür entwickelt.", completion = "Denkt immer an das, was ich Euch heute gezeigt habe, &lt;Name&gt;. Ihr seid Teil des Gleichgewichts, das die Nachtelfen auch in schweren Zeiten aufrechtzuerhalten bestrebt sind.", rewards = "Ihr bekommt:\n\nRezept: Spinnenkebab der KaldoreiSpinnenkebab der Kaldorei"}
MultiLanguageQuestData['de'][4181] = {title = "Gobliningenieurskunst", objective = "Wenn Ihr mehr über die Gobliningenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan.", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Ich erwähne die Ingenieurskunst der Goblins nur, weil ich ein gerechter und unvoreingenommener Lehrer bin. Sie machen gern Dinge, die in die Luft gehen und es ist ihnen dabei meistens egal, ob dabei was im Weg herumsteht - auch wenn sie es selbst sind.\n\nLest dieses Handbuch, <Name>. Wenn Ihr lernen wollt, wie Ihr Euch selbst in die Luft jagt, dann bringt es zu Nixx Sprossfeder nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, &lt;Name&gt;, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, &lt;Name&gt;, und Ihr könnt vielleicht was lernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4182] = {title = "Drachkin-Bedrohung", objective = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen.", description = "Das Leben in der Brennenden Steppe ist voller Konflikte.\n\nSeht Euch nur mal diesen Ort an! Wir wissen nur sehr wenig darüber, was mit diesen Gebäuden geschehen ist, aber wir wissen, dass all das hier irgendwann vor der großen Explosion einmal Teil der Rotkammbergkette war.\n\nAber genug gejammert! Wir haben ein Problem, <Name>. Vielleicht sind Euch die Drachkin am Fuß dieses Bergkamms aufgefallen. Wir brauchen Hilfe, um sie zurückzuschlagen. Tötet so viele, wie Ihr könnt, und kommt dann zu mir zurück. Wenn Ihr erfolgreich seid, können wir uns vielleicht noch über andere Dinge unterhalten.", progress = nil, completion = "Ausgezeichnete Jagd, &lt;Name&gt;. Da wir jetzt wissen, dass Ihr Euch gegenüber den Drachkin behaupten könnt, können wir uns über dringendere Angelegenheiten unterhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4183] = {title = "Die wahren Meister", objective = "Reist nach Seenhain im Rotkammgebirge und händigt Magistrat SolomonHelendis Flusshorns Brief aus.", description = "Bislang nahmen wir an, dass die Schwarzfelsorcs das Ergebnis ihrer primitiven Erziehung seien. Was wir jedoch hier, in ihrem Heimatland, entdeckt haben, erzählt uns eine ganz andere Geschichte.\n\nAngetrieben werden sie zwar tatsächlich von Kampfrausch und Streitlust, aber der schwarze Drachenschwarm ist es, der die Orcs des Schwarzfels beherrscht. Wir vermuten, dass es auch der schwarze Drachenschwarm ist, der ihre Wut und Feindseligkeit schürt.\n\nBringt diesen Brief zu Magistrat Solomon. Er wird wissen, was zu tun ist.\n\n<Helendis gibt Euch einen versiegelten Brief.>", progress = "Seid gegrüßt, <Name>. Sind wir uns schon einmal begegnet? Ihr kommt mir irgendwie bekannt vor.", completion = "&lt;Magistrat Solomon öffnet den versiegelten Brief von Helendis und beginnt zu lesen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4184] = {title = "Die wahren Meister", objective = "Reist nach Sturmwind und tragt Solomons Hilfegesuch dem König Varian Wrynn vor.\n\nDer König residiert in Burg Sturmwind.", description = "Das sind schlimme Neuigkeiten, <Name>. Zu entdecken, dass unsere Todfeinde nicht mehr als Marionetten einer viel größeren Bedrohung sind, ist wahrlich entmutigend. Es ist unmöglich, dass Seenhain einen Angriff durch die Schwarzfelsorcs UND den schwarzen Drachenschwarm überleben könnte. Wenn Seenhain dieser Gefahr anheim fällt, dann fällt bald auch Dunkelhain, und was dann? Goldhain? Auch Sturmwind?\n\nIhr müsst diese Information unbedingt sofort König Varian Wrynn in Sturmwind überbringen! Wenn dies nicht die Unterstützung Sturmwinds rechtfertigt, dann ist alles verloren.", progress = "Was führt Euch zur Burg Stormwind?", completion = "Großdrachen? Unmöglich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4185] = {title = "Die wahren Meister", objective = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", description = "Solomon malt da ein recht düsteres Bild aus. Aber wir können es uns leider nicht leisten, unsere dünn gesäten Truppen aufgrund von reinen Vermutungen nach Seenhain zu schicken. Ich brauche einen Beweis für diese Behauptungen, bevor ich handeln kann.\n\nSprecht mit Lady Prestor, <Name>. Sie ist eine kluge Frau und weiß viel über Großdrachen und Drachkin. Vielleicht kann sie ein bisschen Licht in die Sache bringen.", progress = "<Bolvar betrachtet Euch eindringlich.>", completion = "&lt;Bolvar reibt sein Kinn, als wäre er tief in Gedanken versunken.&gt;\n\nIch respektiere zwar Lady Prestors Haltung, doch glaube ich, dass es für dieses Dilemma eine Lösung gibt, die all unsere Sorgen beseitigen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4186] = {title = "Die wahren Meister", objective = "Händigt Wrynns Erlass an Magistrat Solomon in Seenhain aus.", description = "Ich ernenne Euch hiermit zum kommissarischen Stellvertreter von Sturmwind, <Name>.\n\nKehrt zu Magistrat Solomon in Seenhain zurück und übergebt ihm diesen Erlass.", progress = "Irgendwelche Neuigkeiten von Bolvar?", completion = "Es hätte noch schlimmer kommen können, denke ich...\n\n&lt;Magistrat Solomon betrachtet Euch eingehend.&gt;\n\nEs scheint, als würde Seenhains Schicksal nun allein auf Euren Schultern lasten.\n\n&lt;Ihr bemerkt, dass Magistrat Solomon heftig blinzelt. Er scheint zu weinen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4201] = {title = "Der Liebestrank", objective = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Schwarzfelstiefen.", description = "Oh, wie schmerzhaft doch die Liebe ist! Mein geliebter Gefreiter Rocknot ist immun gegen meinen Charme. Er verschmäht mich! Es ist zum Verrücktwerden!\n\nIhr müsst mir helfen! Wir Sukkuben wissen viel über die Liebe und ich kann einen Trank herstellen, der den eisernen Panzer um Rocknots Herz erweichen könnte. Dazu benötige ich folgende Dinge: das Kraut Gromsblut, Riesensilbervenen von den Klippenriesen Azsharas sowie Wasser aus der Quelle des Golakkakraters in Un'Goro. Ihr könnt das Wasser in diese Phiole füllen.\n\nBitte, <Name>, verhelft einer armen Seele zum Glück!", progress = "Habt Ihr die Zutaten? Die Leere in meinem Herzen verschlingt mich noch!", completion = "Oh, Ihr habt es geschafft! Jetzt kann ich meinen Trank brauen und ihn Rocknot geben. Endlich wird er meinem Charme verfallen!\n\nIch danke Euch, &lt;Name&gt;. Ihr seid ein wahrer Verfechter der Liebe!", rewards = "Nagmaras PeitschengürtelHandfesselmanschettenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4221] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4222] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4223] = {title = "Die wahren Meister", objective = "Sprecht mit Marschall Maxwell in der brennenden Steppe.", description = "<Magistrat Solomon seufzt.>\n\nIhr müsst in die brennende Steppe zurückkehren, <Name>. Als Stellvertreter von Sturmwind erwartet man von Euch, dass Ihr Euch bei Marschall Maxwell meldet. Viel Glück.", progress = nil, completion = "&lt;Marshal Maxwell lacht.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4224] = {title = "Die wahren Meister", objective = "Sprecht mit dem struppigen John.", description = "Was? Ihr dachtet, Ihr wärt der Erste? Wie viele Soldaten müssen wir noch verlieren, bevor Sturmwind handelt?\n\nWir hatten riesige Mengen an Informationen über die Schwarzfelsbedrohung zusammengetragen, doch dann verloren wir unseren befehlshabenden Offizier, Marschall Windsor. Zusammen mit Marschall Windsor gingen auch all unsere wertvollen Informationen verloren.\n\nWas wir brauchen, ist diese Dokumentation. Sprecht mit dem struppigen John, <Name>. Er war mit Windsor zusammen, als sie von einem Stoßtrupp der Schwarzfelsorcs überfallen wurden. Er wurde zuletzt in einer Höhle im Norden gesehen.", progress = "Habt Ihr schon mit John gesprochen?", completion = "Ich hätte Euch warnen können, aber das wäre nur der halbe Spaß gewesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4241] = {title = "Marschall Windsor", objective = "Reist zum Schwarzfels im Nordwesten und dann weiter zu den Schwarzfelstiefen. Findet heraus, was aus Marschall Windsor geworden ist.\n\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt.", description = "Dieser nichtsnutzige Feigling behauptet also, Windsor sei noch am Leben, was?\n\nMacht Euch bereit, Stellvertreter, Ihr werdet ausziehen, um ihn zu suchen. Falls Windsor noch am Leben ist, müsst Ihr ihn zurückholen. Sollte er tot sein, brauche ich einen Beweis dafür.\n\n<Maxwell lacht.>\n\nIch wette, das könnt Ihr langsam schon nicht mehr hören, was?", progress = nil, completion = "Wo ist er? Ich bringe ihn um!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4242] = {title = "Verlorene Hoffnung", objective = "Überbringt Marschall Maxwell bei Morgans Wacht in der Brennenden Steppe die schlechten Neuigkeiten.", description = "Bolvar ist ein Dummkopf. Ich war gerade dabei, ihm seinen kostbaren 'Beweis' zu beschaffen, um ihm diesen in den Hals stopfen zu können.\n\nEr ist ein blinder Blödmann. Selbst wenn der Beweis ihn in die Nase beißt, würde er ihn nicht sehen.\n\nWas meine Informationen angeht, die sind verloren. Unwiderbringlich.\n\nSollte ich Eisenfeind jemals finden und es aus diesem Labyrinth herausschaffen, wird mein erster Halt Sturmwind sein, damit ich diesem Reptil meinen Hammer über den Schädel ziehen kann.\n\nGeht jetzt, <Name>.", progress = nil, completion = "Er ist offensichtlich verrückt geworden.\n\n&lt;Maxwell senkt sorgenvoll den Kopf.&gt;\n\nEs ist bedauerlich, dass ein einst so stolzer und edler Krieger zu solch einem kompletten Schwachkopf mutiert ist. Ich schätze, wir sind in einer Sackgasse...\n\nDennoch muss ich Euch für Eure bisherigen Bemühungen entlohnen, &lt;Name&gt;.", rewards = "KonservatorhelmSchildplattensabatonsScherwindgamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4243] = {title = "Chasing A-Me 01", objective = "Sucht im Krater von Un'Goro nach A-Me 01.", description = "Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Kraters von Un'Goro heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.\n\nSie hat Wahrsagesteine als Augen, so konnte ich alles sehen, was auch sie sah. Den Fungusfels hat sie wohlbehalten erreicht - das ist das Versteck der Affen, gleich nördlich von hier. Und dort habe ich dann den Kontakt zu ihr verloren. Das Letzte, was ich sah, war eines der Alphamännchen, das auf sie zugestürmt kam, um sie zu begrüßen!\n\nKönntet Ihr mir wohl helfen, sie zu finden?", progress = nil, completion = "Als Ihr A-Me 01 eingehend betrachtet, entdeckt Ihr zwei gewaltige Beulen, die Karnas Meisterwerk der Ingenieurskunst verunzieren. Eine Beule befindet sich an der Schulter von A-Me 01, die andere an ihrem Kopf.\n\nDurch ihre Bauteile scheint kein Strom zu fließen, wie Ihr nach weiterer Untersuchung feststellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4244] = {title = "Chasing A-Me 01", objective = "Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Krater von Un'Goro.", description = "Ihr setzt Eure Untersuchungen fort und findet eine Abdeckung, die sich aufschieben lässt. Oberhalb der Verkabelung steht in gut lesbarer Schrift geschrieben: 'Mithrilgehäuse ersetzen und Strom erst ausschalten, dann einschalten.'\n\nEs dauert einen Moment, bis Ihr die Abdeckung wieder angebracht habt, und Ihr fragt Euch, ob es wirklich so einfach ist, A-Me 01 zu reparieren und zurück zu Karna Wirrbart in der Nähe von Marschalls Zuflucht zu bringen.\n\nTja, probieren geht über studieren...", progress = "Die Abdeckung, in die das Mithrilgehäuse gehört, ist immer noch verschlossen. Der Rest von A-Me 01 bleibt reglos.", completion = "Ihr entfernt wieder die Abdeckung im Rücken von A-Me 01 und nehmt das alte Mithrilgehäuse heraus, das offensichtlich durchgebrannt ist. Das neue klickt problemlos an seinen Platz. Vorausgesetzt, das Mithrilgehäuse war die Ursache des Problems, müsst Ihr jetzt nur noch den Schalter auf 'Aus' und dann wieder auf 'Ein' stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4245] = {title = "Chasing A-Me 01", objective = "Begleitet A-Me 01 zu Karna Wirrbart im Krater von Un'Goro.", description = "Nachdem Ihr Euch vergewissert habt, dass Ihr bereit seid, A-Me 01 zu Karna Wirrbart zurückzubringen, knipst Ihr den Schalter auf 'Aus'. Ihr seht Euch nochmals um, um sicherzugehen, dass sich keine Gorillas nähern, und fragt Euch, was wohl geschieht, wenn Ihr den Schalter wieder auf die 'Ein'-Position stellt.\n\nDas ist Eure letzte Chance...wollt Ihr das wirklich tun?", progress = nil, completion = "Oh, Ihr habt es geschafft! Großartig! Ich danke Euch, &lt;Name&gt;.\n\nOh, meine arme A-Me. Diese Beulen, oh nein! Aber mit Geduld und Spucke werden wir sie im Handumdrehen wieder voll funktionsfähig haben.\n\nNochmals danke, &lt;Name&gt;. Ich weiß das wirklich zu schätzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4261] = {title = "Alter Geist", objective = "Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Waldeslied, im Osten des Eschentals.", description = "Der Teufelswald war einst ein friedliches und ruhiges Land... bis die Legion hier eingefallen ist. Die Höllenbestien, Zerstörung, Chaos...\n\nDer Schädel des Gul'dan hat dafür gesorgt, dass hier niemand ungeschoren davonkam. Alles fiel der Verderbnis zum Opfer.\n\nSogar jetzt, da ich ein Geist bin, bin ich immer noch gefangen und muss die Leiden dieses Landes ertragen. Helft mir, den Weg nach Hause zu finden. Bitte, <Name>, sagt mir, dass Ihr einen alten Geist weg von hier führen werdet, dorthin, wo ich endlich ruhen kann.\n\nSobald ich frei sein werde, solltet Ihr Kayneth Stillwind aufsuchen, einen Druiden, der in Waldeslied im Osten lebt.", progress = nil, completion = "Ja, &lt;Name&gt;. Der Teufelswald hat eine Menge durchgemacht. Vielen Dank für Eure Mühen.\n\nEines Tages werden wir den Teufelswald den Klauen der Verderbnis entreißen können. Jede gute Tat trägt dazu bei.", rewards = "AstralnebelcapeMantelung der ziehenden WolkenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4262] = {title = "Übermeister Pyron", objective = "Erschlagt Übermeister Pyron.\n\nIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?", description = "Die letzten fünf meiner Magier, die ausgezogen waren, um sich auf dem Schwarzfels umzusehen, kamen knusprig geröstet zurück, mit einem dauerhaften orangefarbenen Gnomenafro - oder noch schlimmer.\n\n<Jalinda nimmt etwas Asche vom Boden auf und lässt sie vom Wind davontragen.>\n\nEin besonders mieses Individuum, Übermeister Pyron, scheint hier eine Menge Ärger zu verursachen. Dieser Elementar muss vernichtet werden, damit unser Expeditionsteam in die Schwarzfelstiefen reisen kann!\n\nEr bewacht den Eingang am Schwarzfelssteinbruch.", progress = nil, completion = "Incendius? Oje...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4263] = {title = "Incendius!", objective = "Sucht Lord Incendius in den Schwarzfelstiefen und vernichtet ihn!", description = "Seid Ihr sicher, dass Pyron 'Incendius' sagte, als er starb?\n\n<Jalinda schluckt schwer.>\n\nLord Incendius soll angeblich einer von Ragnaros Dienern sein! Oje, oje... was sollen wir jetzt nur tun?\n\nMeint Ihr, Ihr könntet noch eine weitere Mission bewältigen? Ich habe niemand anderen, den ich schicken könnte, <Name>!\n\nWir werden niemals eine Gruppe hineinbringen, solange Incendius Pyron aus der Asche immer wieder neu erstehen lässt.\n\nIhr müsst Lord Incendius suchen und vernichten!", progress = nil, completion = "Oje! Seid Ihr sicher, dass Incendius 'Ragnaros' sagte?\n\n&lt;Jalinda gibt Euch etwas und tätschelt Euer Handgelenk, während sie tief in Gedanken versinkt.&gt;", rewards = "Armschienen des GruftdämonenSonnentuchcapeNachtlauerhandschuheTapfere UmklammerungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4264] = {title = "Eine zusammengeknüllte Notiz", objective = "Soeben seid Ihr auf etwas gestoßen, das Marschall Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung.", description = "Die Notiz ist mit Flecken übersät. Der Text ist kaum noch lesbar, aber Ihr könnt Folgendes erkennen:\n\n... süße Ironie...\n\n... der Sturz der zerbrochenen Allianz...\n\n... ohne General Angerfords Sorgfalt hätten wir das Schema der Verschlüsselung niemals herausgefunden...\n\n... Argelmach hat Windsors Notizen fast entschlüsselt.\n\nUnser Lord wird sich aus den Tiefen erheben und alle zerschmettern, die noch übrig sind...\n\nImperator Dagran Thaurissan", progress = "<Marshal Windsor betrachtet die Notiz in Eurer Hand.>\n\nWas bringt Ihr mir da, <Name>?", completion = "&lt;Marshal Windsor nimmt die Notiz und beginnt zu lesen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4265] = {title = "Flucht aus dem Schwarmbau", objective = "Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.\n\nKehrt zu Ginro Herdfeuer in der Mondfederfeste zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht.", description = "Die Kapsel platzt auf, als Ihr sie berührt, und zum Vorschein kommt ein Nachtelf, der überraschenderweise noch am Leben ist. Er scheint bei guter Gesundheit zu sein, ist jedoch sehr benommen. Als Ihr ihm aus der Kapsel heraushelft, regt sich Leben in ihm.\n\n\"Elune sei Dank! Ihr habt mich gerettet! Ich... Mein Name ist Raschal. Ich erwachte völlig gelähmt in dieser Kapsel, nachdem mich diese Käfer überwältigt hatten. Wurdet Ihr von der Festung geschickt?\"\n\nAnscheinend habt Ihr den vermissten Kurier gefunden!", progress = nil, completion = "Willkommen daheim, &lt;Name&gt;. Raschal hat mich vor kurzem aufgesucht und erzählt, was ihm zugestoßen ist.\n\nIch... nein, die gesamte Festung kann Euch gar nicht genug für Eure großartige Tat danken. Raschal wäre ohne Euer rechtzeitiges Einschreiten jetzt tot und Ihr habt uns geholfen, ohne auch nur den Hauch eines Söldnerlohns dafür zu verlangen. Ihr tragt das Zeichen eines wahren Helden. Wisset, dass Ihr in Ginro Hearthkindle einen Freund fürs Leben gefunden habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4266] = {title = "Der Empfang eines Helden", objective = "Sprecht mit Shandris Mondfeder in der Mondfederfeste.", description = "<Name>, General Shandris Mondfeder möchte unter vier Augen mit Euch sprechen. Sie möchte Euch bestimmt für Eure Dienste zum Wohle der Festung danken, aber ich weiß auch, dass sie außerdem mit Euch über diese Insektenwesen sprechen will, auf die Ihr und Raschal im Süden von Feralas gestoßen seid. Die Berichte, die diese Insekten der Zukk'ash betreffen, sind...mehr als beängstigend.\n\nGeneral Mondfeder wartet im Haupttruppenlager auf Euch.", progress = nil, completion = "&lt;Name&gt;, meinen allerherzlichsten Dank für Eure Hilfe. Eure Tapferkeit angesichts widrigster Umstände verlangt nach einer Belohnung, die tausend Mal größer ist. Ich hoffe dennoch, dass Ihr dies im Namen der gesamten Festung annehmt.\n\nUnd jetzt, wenn Ihr gestattet ... Ich möchte Euch um einen weiteren Gefallen bitten. Angesichts der Entdeckung des Schwarmbaus der Zukk'ash hier in Feralas denke ich, dass Ihr die richtige Wahl für diese Mission seid.", rewards = "Zeremonielle ElfenklingeScheinheilige RuteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4267] = {title = "Aufstieg der Silithiden", objective = "Bringt Raschals Bericht zu Gracina Glaubensmacht in Darnassus.", description = "Ich vertraue Euch eine Kopie des Berichts an, den Raschal über die Plage im Südosten Feralas' angefertigt hat. Der eigentliche Bericht befindet sich in den Akten in Darnassus, aber ich möchte, dass Ihr diese Kopie an eine Vertraute des Protektorats überbringt. Ihr Name lautet Gracina Glaubensmacht. Sie ist eine Priesterin, die im Tempel des Mondes in Darnassus lebt. Sie verfügt über großes Wissen, solche Kreaturen betreffend, und wenn sie diesen Bericht erhalten würde, käme es uns allen sehr zugute.\n\nMacht Euch auf den Weg, und viel Glück, <Name>. Möge Elune über uns alle wachen.", progress = "Willkommen in diesem gesegneten Tempel. Die Festung Feathermoon hat mich über Euer Kommen informiert. Habt Ihr den Bericht, den Shandris Feathermoon Euch gebeten hat mir zu bringen?", completion = "Wir Nachtelfen wissen um den Schrecken, von dem in diesem Bericht die Rede ist. Shandris hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden Feralas schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Die Insekten, auf die Ihr und der Kurier gestoßen seid, sind als Silithiden bekannt. Sie sind die Werkzeuge der größten Bedrohung, der sich die Horde und die Allianz gegenübersehen.\n\nIch bete darum, dass wir die Entschlossenheit besitzen, sie zu besiegen, bevor sie uns vernichten.", rewards = "Handschuhe der SanddüneMarodeurshandlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4281] = {title = "Thalanaar-Lieferung", objective = "Bringt das nicht ausgelieferte Paket zu Falfindel Wegeshut in Thalanaar.", description = "Dieses Paket mit Waren, das Ihr in den Lagern der Waldpfotengnolle gefunden habt, war für den kleinen Streckenposten Thalanaar im Südosten Feralas' bestimmt. Das Paket, ungeachtet des Schicksals des vermissten Kuriers, harrt immer noch der Auslieferung.\n\nIhr untersucht das Paket genauer und entdeckt den Namen 'Falfindel Wegeshut' handschriftlich auf der Verpackung vermerkt. Vielleicht ist er der eigentliche Empfänger des Pakets.", progress = "Willkommen in Thalanaar, <Klasse>. Kann ich Euch irgendwie behilflich sein?", completion = "Elune sei gepriesen, die Lieferung von der Festung Feathermoon ist endlich eingetroffen!\n\nEure Anwesenheit hier sagt mir, dass Raschal, unseren eigentlichen Kurier, wohl ein böses Schicksal ereilt hat. Ich hoffe, dass sich alles zum Guten wenden wird. Ich weiß, dass die Waldpfoten seit kurzem wegen irgendetwas, das sich südlich von ihnen ereignet hat, äußerst aufgebracht sind. Vielleicht ist er dort der Wildnis zum Opfer gefallen. Ich an Eurer Stelle wäre vorsichtig.\n\nNun denn, nochmals danke. Hier ist Eure Entlohnung für die Auslieferung des Pakets.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4282] = {title = "Ein Funken Hoffnung", objective = "Holt Marschall Windsors verlorene Informationen zurück.\n\nMarschall Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden.", description = "<Marschall Windsor wedelt aufgeregt mit der Notiz herum.>\n\nWisst Ihr, was das bedeutet, <Name>?\n\nVielleicht ist doch noch nicht alles verloren! Soweit ich das erkennen kann, wird die Information von zwei Dunkeleisenzwergen verwahrt: General Zornesschmied und dem Golemlord Argelmach. Ich habe das Gefühl, als würden sie die Information nicht einfach so herausrücken, wenn wir sie freundlich darum bitten.\n\nAlso hoffe ich, dass Ihr auf einen Kampf vorbereitet seid.\n\nZieht aus und findet die beiden Bösewichte! Vernichtet sie und bringt mir meine verloren gegangenen Informationen zurück.", progress = "Schon bald wird es mit dieser grandiosen Täuschung ein Ende haben.", completion = "&lt;Marshal Windsor reißt die zwei Schrifttafeln aus Eurer Hand.&gt;\n\nWir müssen hier raus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4283] = {title = "FÜNFZIG! Jawoll!", objective = "Beschafft Euch 50 Medaillons des Schwarzfelsklans.", description = "Ich werde Euch ein kleines Geheimnis verraten, Soldat: Kommt näher.\n\nICH BIN HIER DER EINZIGE, DER NOCH BEI VERSTAND IST!\n\nSeht Euch nur all diese Leute an! Ist es zu fassen, dass sie alle irre sind!? Oh ja, das sind sie! DURCHGEDREHT! WAHNSINNIG!\n\n<Oralius senkt die Stimme.>\n\nDas bleibt aber unter uns: mir, Euch und meinem Kumpel Käpt'n Winky.\n\n<Oralius greift in die Luft und drückt zu.>\n\nWie auch immer...Ich sammle Abzeichen, die gut zu meiner Sammlung Ogerohren passen. Orcs sind der letzte Schrei. Fünfzig. LOS!\n\n<Oralius stößt in ein Horn.>\n\nAB DAMIT!", progress = "<Oralius spricht mit einem ziemlich großen, abgetrennten Ogerohr.>\n\nBrennende Steppe an Zentrale. Zentrale, bitte kommen.", completion = "Ihr habt es geschafft! Und das ist Eure Belohnung: STREICHELT MEINEN BAUCH! LOS DOCH! STREICHELT IHN!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4284] = {title = "Machtkristalle", objective = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marschalls Zuflucht.", description = "Ich bin sicher, Ihr habt sie bemerkt, <Name>. Sie sind überall!\n\nWovon ich rede? Na, von den Kristallen natürlich!\n\nDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht. Ich habe eine Weile mit ihnen herumexperimentiert, aber ich habe noch nichts herausgefunden. Tja, bis jetzt jedenfalls.\n\nAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?", progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, <Name>!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4285] = {title = "Der Nordpylon", objective = "Findet den Standort des nördlichen Kristallpylonen im Krater von Un'Goro.", description = "Wofür die wohl gut sind? Ich muss ständig daran denken!\n\nEs macht mich verrückt, dass all die Gerüchte über die Kristallpylonen wahr sind. Nennt mich leichtgläubig, aber ich glaube gewöhnlich, was mir die Leute erzählen.\n\nWie dem auch sei, ich habe gehört, dass sich einer dieser Kristallpylonen hier ganz in der Nähe befinden soll. Irgendwo im Norden... Sucht ihn doch bitte, <Name>. Ich weiß genau, dass es die Dinger gibt.", progress = nil, completion = "Ich weiß, dass die Geschichten wahr sind, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4286] = {title = "Das gute Zeug", objective = "Beschafft Euch 20 Dunkeleisengürteltaschen.", description = "Käpt'n Winky sagt mir, dass die Dunkeleisenzwerge in den Tiefen das ganze gute Zeug haben. Stimmt's nicht, Winky?\n\n<Oralius versucht, so gut es geht, einen Piraten zu imitieren.>\n\nHARRR, KUMPEL! DAS STIMMT!\n\nDa hört Ihr's. Ihr müsst Euch dorthin begeben und mir etwas von dem guten Zeug besorgen.\n\nGeht da rein und holt es Euch!", progress = "Ich kann jetzt nicht, <Name>. Ich und Winky müssen zu einer Konferenz.", completion = "&lt;Oralius beginnt, in den hoch aufgetürmten Gürteltaschen herumzuwühlen.&gt;\n\nOH, WUNDERBAR!\n\n&lt;Oralius steckt seine lange Nase in den Berg und nimmt einen tiefen Atemzug.&gt;\n\nKÖSTLICH! Seht Euch nur all die schönen Sachen an!\n\nDa, nehmt Euch auch so'n Ding, &lt;Name&gt;. Es sind genug davon da.", rewards = "Ihr bekommt:\n\nEine schmuddelige Gürteltasche"}
MultiLanguageQuestData['de'][4287] = {title = "Der Ostpylon", objective = "Findet den Standort des östlichen Kristallpylonen im Krater von Un'Goro.", description = "Während meines Aufenthaltes hier sind mir seltsame Gerüchte über rätselhafte Pylonen zu Ohren gekommen, die es angeblich draußen in der Wildnis des Kraters geben soll, <Name>. Ich nehme an, sie sind ziemlich groß, mit Kristallen an den Innenseiten.\n\nIch habe zwar noch nie welche gesehen, aber ich komme nicht umhin zu glauben, dass die Gerüchte wahr sind - und dass die Pylonen irgendetwas mit all den Kristallen zu tun haben, die wir gefunden haben.\n\nAlso, warum helft Ihr mir nicht, meine Neugier zu stillen? Angeblich soll es einen im östlichen Teil des Kraters geben. Meint Ihr, Ihr könntet ihn finden?", progress = nil, completion = "Un'Goro ist ein sehr seltsamer Ort, &lt;Name&gt;. Wenn man den Krater betritt, kommt es einem so vor, als wäre man in einer ganz anderen Welt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4288] = {title = "Der Westpylon", objective = "Findet den Standort des westlichen Kristallpylonen.", description = "Meine Experimente haben bis jetzt noch keine positiven Ergebnisse erzielt, <Name>. Ich kann nur hoffen, dass Ihr eine Lösung findet, indem Ihr einen der Pylonen entdeckt, von denen ich gehört habe.\n\nWas, wenn wir bestimmte Farben mit ihnen kombinieren würden... ach, eines nach dem anderen. Zuerst müssen wir sie finden!\n\n<Name>, sucht im westlichen Teil des Kraters. In diesem Gebiet soll sich irgendwo ein Pylon befinden.", progress = nil, completion = "Entlang der Ränder des Kraters gibt es viele verborgene Bereiche. Erkundet die gewundenen Pfade, wenn Ihr nicht mehr wisst, wo Ihr noch suchen sollt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4289] = {title = "Die Affen von Un'Goro", objective = "Bringt Torwa Pfadfinder am Eingang zum Krater von Un'Goro 2 Gorillapelze von Un'Goro, 2 Stampferpelze von Un'Goro und 2 Donnererpelze von Un'Goro.", description = "In diesem Krater gibt es viele seltsame Kreaturen - sie scheinen edler zu sein als ihre Verwandten, die man überall in meinem Heimatland und jenseits davon findet. Ich habe keine Erklärung dafür, aber dieser Ort trägt die Handschrift der Erdenmutter. Immer, wenn ich auf eines ihrer wundervollen Geschöpfe in diesem Krater stoße, erweise ich ihr meine Ehrerbietung.\n\nWenn auch Ihr diese Erleuchtung spüren möchtet, die eine solche Tat begleitet, dann geht nach Norden. Dort findet Ihr große Affen, die die Kraft eines jeden Sterblichen auf eine harte Probe stellen. Bringt mir ihre Pelze...beweist mir Eure Kraft.", progress = "Haben Euch die Kreaturen hier bereits besiegt, <Name>?\n\nLasst Euch doch nicht so leicht entmutigen. Die Un'Goro-Affen aufzuspüren und sie zu besiegen ist keine einfache Aufgabe, auch nicht für einen großen Jäger.", completion = "Ihr habt also Eure Kraft bewiesen und dass Ihr kräftig genug seid, um sogar die großen Affen von Un'Goro zu besiegen - das ist gut. Im Vergleich zu Lar'korwi war das zwar nur eine kleine Herausforderung, aber ich will Euch Euren großen Sieg nicht nehmen.\n\nDiese Pelze werden herrliche Kleidung für meinen Stamm abgeben. Ihr habt mir geholfen und Euch als würdig erwiesen.\n\nBevor Ihr Euch einer anderen Aufgabe annehmt, lasst uns noch der Erdenmutter huldigen und den Geistern der Affen danken, die Ihr getötet habt, damit sie wissen, dass ihr Tod nicht umsonst gewesen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4290] = {title = "Lar'korwis Mahl", objective = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pfadfinder im Krater von Un'Goro zurück.", description = "Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.\n\nLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.\n\nWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.\n\nKommt dann zu mir zurück.", progress = "Hört auf meine Worte, <Name>. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, &lt;Name&gt;. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4291] = {title = "Lar'korwis Fährte", objective = "Bringt Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro 2 Pheromondrüsen eines Ravasaurus.", description = "Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, <Name>. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.\n\nAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasauruseier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.", progress = "Seid vorsichtig, <Name>. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, &lt;Name&gt;. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4292] = {title = "Ein Köder für Lar'korwi", objective = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro.", description = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Nördlich von hier findet Ihr einen kleinen Pfad, der in die Berge hinaufführt. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit der Drüse ein. Wenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.", progress = "Lasst Euch nicht von Furcht überwältigen, <Name>. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!\n\nNehmt das Fleisch, legt es in dem kleinen Tal ab und reibt es dann mit der Drüse ein. Nur so wird der Tod zu Euch kommen.", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, &lt;Name&gt;. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch.", rewards = "EbenenpirschertunikaVorhutgamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4293] = {title = "Eine Schleimprobe...", objective = "Sammelt im Teufelswald Proben von verschiedenen Schleimen. Verwendet dann die Testausrüstung neben Chemiker Brenner in Unterstadt, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Proben aus dem Teufelswald, die Ihr findet, zu Chemiker Brenner.", description = "Der Teufelswald ist ein Wald weit im Norden des Brachlandes, sogar noch weiter weg als das Eschental. Um die dortigen Teiche herum, die durch dämonische Energie gesegnet wurden, befinden sich überall Schlamme. Die Geißel hat mit den Angriffen von Höllenbestien und anderer Dämonenmagie die Gegend stark verwüstet - die Schleime sind angeblich während dieser Angriffe aus der Erde an die Oberfläche gekrochen.\n\nSammelt einige Proben von Teufelswaldschleimen, dann verwenden wir die Testausrüstung hier neben mir, um eine Kontrollgruppe zusammenzustellen, mit der wir die anderen Proben, die Ihr eingesammelt habt, vergleichen können.", progress = "Für unsere Kontrollgruppe brauche ich mindestens fünf verderbte Proben, <Name>. Sammelt weiter Teufelswaldschleimproben, bis Ihr mir das geben könnt, was wir brauchen. Lady Sylvanas hat es verfügt...", completion = "Ah, wunderbar. Diese Proben sind genau richtig. Ich danke für Eure Hilfe.\n\nSobald wir alle Brühschleimerproben zusammenhaben, können wir mehr sagen. Langsam fange ich an zu glauben, dass Lady Sylvanas mit ihrer Ahnung nicht nur Recht hatte, sondern dass diese auch noch mit mehr Einsicht gesegnet war, als sogar sie gedacht hätte. Diese Proben sind sehr interessant. Allein zu sehen, wie sie auf meine Präparate reagiert haben ... hmm, ja, ganz zweifellos müssen wir noch weitere Untersuchungen anstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4294] = {title = "...und eine Menge Schlamm", objective = "Sammelt im Un'Goro Proben von verschiedenen Schleimen. Verwendet dann die Testausrüstung neben Chemiker Brenner in Unterstadt, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Proben aus dem Un'Goro, die Ihr findet, zu Chemiker Brenner.", description = "Habt Ihr schon einmal vom Krater von Un'Goro gehört, <Name>? Er liegt in der Nähe der Tanariswüste und es ist ein großartiger Ort: üppig, von Leben sprühend, voller Kreaturen und Pflanzen.\n\nDorthin müsst Ihr Euch begeben. Ich habe mir sagen lassen, dass der Krater noch völlig unbesudelt und frei von Einflüssen von außen sei. Erst jetzt beginnen Forscher, seine Geheimnisse zu entdecken.\n\nIch würde die dortigen Schleime und Schlamme gern testen. Wenn es stimmt, dass sie nicht verderbt sind, dann würde ich gern wissen, wie sich solche Kreaturen entwickelt haben.", progress = "Ja, <Name>? Wie läuft Eure Suche?", completion = "Einfach erstaunlich, &lt;Name&gt;. Dieser Un'Goro Krater birgt wesentlich mehr Geheimnisse als ich dachte. Ich frage mich, was wir noch alles entdecken werden, wenn wir unsere Tests fortsetzen.\n\nWirklich erstaunlich... seht Euch nur an, wie rein diese Proben sind! Hmm... ich frage mich, was das bedeuten könnte. Es scheint sich bei ihnen um Elementare zu handeln, aber... auch noch um mehr. Sie erinnern mich an... die Alten Götter. Deren Spuren haben wir in ganz Azeroth gefunden und jetzt frage ich mich, ob diese Wesen nicht irgendwie mit ihnen verwandt sind.\n\nWir müssen weitere Tests durchführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4295] = {title = "Rocknots Bier", objective = "Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der <Volk>, den ich letzte Woche erschlagen habe!", description = nil, progress = "Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der <Volk>, den ich letzte Woche erschlagen habe!", completion = "Was ist denn das? Ah! Das riecht wie Dunkeleisenbier! Das Trinken verschleiert meine Sicht, aber ich sehe, dass Ihr, werter Herr, ein echter Freund seid!", rewards = nil}
MultiLanguageQuestData['de'][4296] = {title = "Schrifttafel der Sieben", objective = "Beschafft Euch die Abschrift der Schrifttafel.", description = "Die Legenden der Sieben führten mich in die Brennende Steppe. Sie waren hoch gebildete und mächtige Zwerge, und wenn man über Wissen und Macht verfügt, so ist das der Schlüssel zum Reichtum.\n\nUnd genau das ist es, was ich will. Reichtum!\n\nWenn wir mehr über die Sieben in Erfahrung bringen könnten, würde das uns beide vielleicht reich machen. In den Ruinen von Thaurissan soll sich angeblich die Schrifttafel der Sieben befinden, auf der das Wissen über die alten Zwerge geschrieben steht. Sucht diese Schrifttafel, kopiert den Text und bringt ihn mir. Lasst uns deren Geheimnisse gemeinsam entschlüsseln!", progress = "Habt Ihr die Schriften der Sieben, <Name>? Kennt Ihr jetzt die Geheimnisse dieser Schrifttafel?", completion = "Ah, Ihr habt die Schrifttafel gefunden! Und Eure Abschrift ist erstklassig! Seid Ihr sicher, dass Ihr ein &lt;Klasse&gt; seid und kein Schreiber?\n\nHier, bitte sehr, &lt;Name&gt;. Nehmt hier die Bezahlung, die ich Euch versprochen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4297] = {title = "Essen für das Baby", objective = "Bringt Agnar Tiermeister im Hinterland 5 Silbermähnenpirscherflanken.", description = "Grimmlingflitzer sind Allesfresser - das bedeutet, dass sie sowohl Fleisch als auch Grünzeug fressen. Wenn dieses Junge hier schlüpft, sollten wir vorbereitet sein. Es ist kaum zu glauben, aber diese kleinen Kerlchen ernährt man am besten mit Fleischstücken, roh und saftig. Ich habe nie herausgefunden, warum das so ist, aber es muss wohl etwas mit Elunes Plan für die Elfen zu tun haben... vielleicht waren sie als Beschützer oder so etwas vorgesehen, ich weiß es nicht.\n\nIch kümmere mich vorerst um das Ei. Warum besorgt Ihr nicht ein paar Silbermähnenpirscherflanken, mit denen wir das Junge füttern können, sobald es geschlüpft ist?", progress = "Habt Ihr das Fleisch, <Name>? Euer Kleines hier wird bald schlüpfen. Wenn seine erste Mahlzeit nicht ausreicht, wird er die erste Woche vielleicht nicht überleben, und ich möchte nicht, dass das geschieht.\n\nIch will ehrlich zu Euch sein, <Name>. Ich bin neidisch, weil Ihr so ein Ei habt und ich nicht. Und ich möchte es nicht bereuen, Euch hier ausgeholfen zu haben.", completion = "Das wird reichen, und wenn ich mich nicht irre, wird Euer Kleines bald schlüpfen. Wie ist das so? Ihr wisst schon, bald Vater zu sein? Haha, Ihr habt wohl nicht damit gerechnet, einmal solche Verantwortung übernehmen zu müssen, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4298] = {title = "Elternfreuden", objective = "Sprecht mit Agnar Tiermeister im Hinterland.", description = "He, es war wohl schon weiter, als ich dachte...", progress = nil, completion = "Hier, nehmt das Ei... besser, Ihr habt es in der Hand, damit das Junge gleich eine Bindung zu Euch aufbaut und glaubt, Ihr wärt sein Papa.\n\nGlückwunsch, &lt;Name&gt;. Ihr habt jetzt ein Kind... sozusagen.", rewards = "Ihr bekommt:\n\nGrimmlingflitzerei"}
MultiLanguageQuestData['de'][4300] = {title = "Knochenklingenwaffen", objective = "Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen.", description = "Hmm, jetzt, wo ich darüber nachdenke, könnte es doch etwas geben, das Ihr für die Hand erledigen könntet. Ja, Jes'rimon könnte bestimmt Eure Hilfe brauchen.\n\nIm Krater von Un'Goro gibt es Raptoren mit tödlichen Klauen. Manche dieser Raptoren haben weiße Klauen statt schwarze wie der Tod. Die Mitglieder der Hand haben...Kunden..., denen aus diesen Klauen gefertigte Waffen gefallen. Bringt mir reichlich von diesen weißen Klauen, dann werde ich Euch gut entlohnen. Wenn Ihr das schnell genug tut, dann kann ich Euch vielleicht noch auf andere Weise helfen.", progress = "Meine Kunden sind nicht sehr geduldig, <Name>. Habt Ihr schon irgendwelche Klauen?", completion = "Ah, die sind hervorragend. Danke, &lt;Name&gt;. Und Ihr seid zurück, bevor sie benötigt werden... sehr gut.\n\nVielleicht fertigen wir ja eine Waffe für Euch aus diesen Klauen an. Was meint Ihr?", rewards = "WeißknochenschredderWeißknochenspeerAuf Euch wartet eine dieser Belohnungen:\n\nWeißknochenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4301] = {title = "Der mächtige U'cha", objective = "Bringt U'chas Pelz zu Torwa Pfadfinder am Eingang des Kraters von Un'Goro.", description = "Während Ihr Un'Goro erkundet habt, sind mir ein paar andere Dinge aufgefallen, die einem mächtigen Jäger wie Euch sicher gefallen würden. Zum Beispiel gibt es da einen gewaltigen Affen unter den Gorillas im Norden. Ihr seid schon einmal in dieser Höhle gewesen, aber dieses Mal frage ich mich doch, ob Ihr die Begegnung mit ihm wohl überleben würdet, solltet Ihr meine Aufgabe annehmen.\n\nIch nenne ihn U'cha und er ist einer der größten Söhne der Erdenmutter, da könnt Ihr sicher sein. Besiegt U'cha und bringt mir seinen Pelz. Wenn Euch das gelingt, habt Ihr das Recht darauf, ein großer Jäger genannt zu werden.", progress = "U'cha... was für ein großartiges Tier. Riesig und rot, mit Zähnen so lang wie Dolche. Arme so dick wie Baumstämme und so schnell wie der schnellste Berglöwe, den ich je gesehen habe. Ihr solltet Euch glücklich schätzen, ein solches Objekt für die Prüfung Eures Mutes vorzufinden - mein Volk hat seit Generationen keine derartige Kreatur mehr zu sehen bekommen.", completion = "Gut gemacht, &lt;Name&gt;. Ich bin erfreut. Heute habt Ihr hier Großes geleistet.\n\nU'cha war einer der größten Affen, die ich je gesehen habe. Die Tatsache, dass Ihr seine Kraft bezwungen habt, zeugt von Eurer eigenen Kraft... und Eurem Mut.\n\nDaher ist es nur angemessen, dass ich Euch dies hier als Zeichen meines Respekts überreiche. Ihr habt es Euch verdient.", rewards = "WildtierzerhackerWildtiertöterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4321] = {title = "Die Sache verstehen", objective = "Sprecht demnächst mit J. D. Collie.", description = "Die Information über die Pylonen, die Ihr mir gabt, ist sehr interessant...\n\nGebt mir einen Moment Zeit, um ein paar Berechnungen anzustellen, <Name>. Sprecht mich demnächst noch einmal an, dann sollte ich Euch die Antwort geben können, nach der wir gesucht haben.", progress = nil, completion = "So, &lt;Name&gt;. Das ist echt faszinierend... Ich kann nur hoffen, dass meine Diagramme korrekt sind! Ich habe alles in dieser Anleitung zusammengefasst, die ich Euch überlassen werde.\n\nJetzt sollte ich all Eure Fragen zu den Kristallen beantworten können, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nHandbuch für Kristallpylonen"}
MultiLanguageQuestData['de'][4322] = {title = "Gefängnisausbruch!", objective = "Helft Marschall Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marschall Maxwell zurück, wenn Ihr Erfolg hattet.", description = "Wir müssen hier weg, <Name>. Helft mir, meine Ausrüstung aus dem Vorratsbereich zu holen und meine Freunde zu befreien. Falls wir hier rauskommen, dann müsst Ihr Euch weiter nach Morgans Wacht durchschlagen und mit Marschall Maxwell sprechen. Er wird Euch weitere Anweisungen geben.", progress = nil, completion = "Erstaunlich, &lt;Name&gt;. Einfach erstaunlich. Windsor ist vor nicht einmal fünf Minuten hier durchgestürmt. Er spuckte große Töne, behauptete jedoch, alles mit Beweisen untermauern zu können. Jetzt ist er auf dem Weg nach Stormwind, um Bolvar und... Lady Prestor damit zu konfrontieren.", rewards = "Klinge der AbrechnungGeschickte KampfklingeIhr bekommt:\n\nBarriere der Elemente"}
MultiLanguageQuestData['de'][4324] = {title = "Yuka Schraubstutz", objective = "Sprecht mit Yuka Schraubstutz in der Brennenden Steppe.", description = "Mein Bruder Ribbly war sein ganzes Leben lang zu nichts nütze; aber jetzt, glaube ich, hat er endlich einen gewissen Wert! Aber... wir werden Eure Hilfe brauchen, um aus Ribblys Wert Kapital zu schlagen.\n\nMeine Schwester Yuka hat ihn wochenlang gesucht und endlich in der Brennenden Steppe gefunden. Sie hat mich wissen lassen, dass sie ein paar Helfer brauchen könnte.\n\nAlso, was meint Ihr? Wollt Ihr uns helfen? Falls ja, sprecht mit meiner Schwester. Ihr findet sie im Flammenkamm versteckt, in einer Höhle nordwestlich des Schreckensfelsens.", progress = nil, completion = "Ja, ich suche meinen Bruder. Wir müssen ihn finden und zurückbringen, gesegnet sei sein Herz.\n\nAber wenn wir ihn nicht im Ganzen zurückbringen können... dann reicht auch sein Kopf.", rewards = nil}
MultiLanguageQuestData['de'][4341] = {title = "Kharan Hammermacht", objective = "Begebt Euch in die Schwarzfelstiefen und findet Kharan Hammermacht.\n\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten.", description = "Seid Ihr in den rauchenden Ruinen von Thaurissan gewesen? Seid Ihr dort zufällig einem erbärmlichen Tölpel namens Kharan Hammermacht begegnet? Dem Zwerg, der eigentlich über mein kleines Mädchen wachen sollte?\n\n<Der König schluchzt.>\n\nUnd jetzt ist sie verschwunden, <Name>!\n\nIch habe meine Leute die gesamte Steppe durchkämmen lassen. Doch der einzige Hinweis, den sie über den Verbleib meiner Tochter finden konnten, war, dass sie vielleicht in den Tiefen ist. Möglicherweise ist sie sogar schon tot!\n\nAngeblich wird Kharan dort als Gefangener festgehalten...findet ihn! Ich will Antworten!", progress = nil, completion = "Bitte, lasst es mich erklären.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4342] = {title = "Kharans Geschichte", objective = "Lasst Kharan Hammermacht seine Geschichte erzählen.", description = "Bitte hört mich an, ehe Ihr ein Urteil fällt!", progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Wie Ihr seht, gab es nichts, was ich hätte tun können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4343] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4361] = {title = "Der Überbringer schlechter Botschaften...", objective = "Kehrt nach Eisenschmiede zurück und überbringt König Magni Bronzebart die schlechten Nachrichten.", description = "Ihr müsst König Magni diese Informationen bringen, <Name>. Er wird wissen, was zu tun ist!", progress = nil, completion = "&lt;Wütend schlägt König Magni mit der Faust auf den Tisch.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4362] = {title = "Das Schicksal des Königreichs", objective = "Kehrt in die Schwarzfelstiefen zurück und rettet Prinzessin Moira Bronzebart aus den Fängen des bösen Imperators Dagran Thaurissan.", description = "Es scheint, als habe mein alter Widersacher, Dagran Thaurissan, mich und das ganze Königreich Eisenschmiede in seiner Gewalt.\n\nVielleicht seid Ihr meine letzte Hoffnung, <Name>. Ihr müsst meine Tochter Moira retten!\n\nEs gibt nur einen Weg, wie der Zauber, mit dem Thaurissan Moira belegt hat, wirklich zuverlässig gebrochen werden kann: Ihr müsst ihn töten.\n\nAber, <Name>, meiner Tochter dürft Ihr kein Leid zufügen! Vergesst nicht, dass sie Thaurissans Kontrolle unterliegt! Alles, was sie vielleicht sagt oder tut, geschieht aufgrund von Thaurissans bösem Zauber!", progress = nil, completion = "&lt;Prinzessin Bronzebeard weint bitterlich über den Verlust von Imperator Dagran Thaurissan.&gt;\n\nWarum???", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4363] = {title = "Die Überraschung der Prinzessin", objective = "Kehrt nach Eisenschmiede zurück und sprecht mit König Magni Bronzebart.", description = "Thaurissan war ein großer und ehrenhafter Zwerg. Ihr habt mein Leben zerstört - meines und das meines ungeborenen Kindes!\n\n<Ihr habt den Eindruck, als leide Prinzessin Bronzebart noch immer unter den letzten Auswirkungen des vom Imperator gewirkten Zaubers.>\n\nKehrt nach Eisenschmiede zurück und sagt meinem Vater, dass der Erbe des Königreichs Eisenschmiede ein Dunkeleisenzwerg sein wird.\n\nOb er dies billigt oder nicht, so wird es sein.", progress = nil, completion = "&lt;König Magni Bronzebeard ist sichtlich erschüttert.&gt;\n\nEs scheint, als habe Thaurissan gewonnen - sogar im Tode.\n\nIhr seid entlassen, &lt;Name&gt;. Doch ehe Ihr geht, dürft Ihr Euch Eure Belohnung aus dem königlichen Gewölbe auswählen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMagnis WilleLiedstein von Eisenschmiede\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4381] = {title = "Kristallflicker", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euch oder Eure Verbündeten heilen.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euch oder Eure Verbündeten heilen.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallflicker"}
MultiLanguageQuestData['de'][4382] = {title = "Kristallkraft", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Geist steigern.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Geist steigern.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallkraft"}
MultiLanguageQuestData['de'][4383] = {title = "Kristallbarriere", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und rote Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Schutz vor körperlichem Schaden stärken.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und rote Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Schutz vor körperlichem Schaden stärken.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallbarriere"}
MultiLanguageQuestData['de'][4384] = {title = "Kristallschwächer", objective = "Mithilfe der Pylon-Tafel könnt Ihr rote und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination die Verteidigung eines Gegners schwächen.", description = nil, progress = "Mithilfe der Pylon-Tafel könnt Ihr rote und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination die Verteidigung eines Gegners schwächen.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallschwächer"}
MultiLanguageQuestData['de'][4385] = {title = "Kristallsprengladung", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination eine starke Explosion auslösen, die Euren Feinden Schaden zufügt.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination eine starke Explosion auslösen, die Euren Feinden Schaden zufügt.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallsprengladung"}
MultiLanguageQuestData['de'][4386] = {title = "Kristallspitze", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr blaue und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination einen Schild erschaffen, der Euren Feinden Schaden zufügt.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr blaue und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination einen Schild erschaffen, der Euren Feinden Schaden zufügt.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallspitze"}
MultiLanguageQuestData['de'][4401] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4402] = {title = "Galgars Kaktusapfel Surprise", objective = "Bringt Galgar 6 Kaktusäpfel. Ihr erinnert Euch doch, dass er gesagt hat, man fände sie in der Nähe von Kakteen?", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweiß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, <Name>. Wenn Ihr mir 6 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, &lt;Name&gt;! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu.", rewards = "Ihr bekommt:\n\nKaktusapfel Surprise"}
MultiLanguageQuestData['de'][4403] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4421] = {title = "Die Verderbnis der Jadefeuer", objective = "Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Blauwind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", description = "Nicht viele kommen hierher und suchen das Abenteuer... Die Verderbnis hat sich im Teufelswald überall ausgebreitet und macht vor nichts Halt.\n\nAls Mitglied des Smaragdkreises trachte ich danach, dieses Land zu heilen. Doch es gibt andere, die wünschen, dass es weiter schwärt.\n\nIch spreche von den Jadefeuersatyrn, die sich nordwestlich von hier aufhalten, bei den Ruinen von Constellas. Ihr Anführer ist ein besonders grausamer Satyr namens Xavathras und unter seiner Führung übertragen sie die Krankheit auf alle Wesen, denen sie begegnen.\n\nWir müssen dieses Land, das einst das unsrige war, verteidigen. Besiegt Xavathras und vernichtet seine Diener.", progress = nil, completion = "Den Teufelswald von Xavathras zu befreien, ist nur der erste Schritt auf einem langen Weg. Es wird viel Arbeit vonnöten sein, um den Schaden zu beheben, der hier angerichtet worden ist.\n\nIch spüre, dass hier mehr am Werk ist als nur die Satyrn allein, aber die Wahrheit werden wir wohl erst im Lauf der Zeit herausfinden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4441] = {title = "Gebundene Urtume", objective = "Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", description = "Die Flöte, die Ihr gefunden habt, wurde aus einem Urtumbeschützer geschnitzt, den Treantverbündeten, die schon immer treu über die Nachtelfen gewacht haben.\n\nEs ist den Satyrn gelungen, alles zu verderben, mit dem sie in Kontakt kommen, einschließlich der Urtume, die im Teufelswald lebten. Mithilfe der teuflischen Verderbnis wurde der Geist des Urtums gefangen und gefoltert und nie wieder völlig freigegeben. Der Teufelsbinder, den Ihr gefunden habt, hängt ganz ohne Zweifel damit zusammen.\n\nWir müssen versuchen, die Flöte zu läutern, <Name>. Bringt mir gesegnetes Wasser vom Tempel des Mondes in Darnassus.", progress = "Hoffentlich wird das Wasser den Geist des Urtums freisetzen, sodass er von nun an in Frieden ruhen kann.", completion = "Danke, &lt;Name&gt;. Und jetzt müssen wir hoffen und beten, dass wir den Schaden beheben können, der hier angerichtet worden ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4442] = {title = "Geläutert!", objective = "Sprecht Eridan gleich noch einmal an.", description = "Ich werde jetzt versuchen, die Flöte mit dem Wasser von Elune zu läutern. Wir müssen diesem Leiden ein Ende machen...\n\nMöge Elune meine Hände und mein Herz leiten.\n\nSprecht mich gleich noch einmal an.", progress = nil, completion = "Mit dem gesegneten Wasser konnte ich die Verbindung zwischen der Flöte und dem Geist des Urtums unterbrechen. Aber ich glaube, dass Ihr, wenn Ihr diese Flöte an einem heiligen Ort verwendet, vielleicht die Geister der Urtume beschwören könnt.\n\nIhr könntet es einmal in den Ruinen im südlichen Teil der Ruinen des Eisenwaldes versuchen. Einst bewohnten viele verderbte Treants diese Gegend und es ist möglich, dass sie sich noch immer dort aufhalten, und sei es auch nur in Geistgestalt.", rewards = "Ihr bekommt:\n\nFlöte der Urtume"}
MultiLanguageQuestData['de'][4443] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4444] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4445] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4446] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4447] = {title = "Verderbter Nachtdrache", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4448] = {title = "Verderbter Nachtdrache", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4449] = {title = "Eingesperrt!", objective = "Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der Sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", description = "He! He, Ihr da! Kommt her!\n\nIhr müsst mir dringend helfen. Ich bin vor den Dunkeleisenzwergen abgehauen und hab mich hier drin versteckt, damit se mich nich' sehen. Verdammte Drecksgeologen und ihre Magie! Die müss'n geseh'n haben, wie ich mich versteckt hab, weil als Allernächstes ham se die Tür versperrt. Ham was gesagt von wegen, dass sie zurückkommen und mich holen würden, und dann sind sie verschwunden.\n\nIhr müsst denen zeigen, wer hier der Boss ist! Könnt Ihr das für mich tun? Verpasst den Geologen 'ne Lektion! Ach, und könnt Ihr mir 'n paar Stücke Seidenstoff beschaffen für...für...ach, für nix.", progress = "Ich hab nicht ewig Zeit! Beschafft mir schon diese Stücke Seidenstoff! Äh, Geologen. Ich meine Geologen. Schnappt Euch diese Geologen! Sie verdienen es, meinen... na ja, Euren Zorn zu spüren.", completion = "Oh, toll! Fühlt sich auch klasse an!\n\nWas? Ach ja... die Geologen. Denen habt Ihr's gehörig gezeigt, was? Ich kann Euch gar nich' genug danken, &lt;Name&gt;. So hab ich 'n bisschen Zeit, hier drin alles fertig zu machen... Äh, ich meine natürlich, jetzt muss ich mir erst mal keine Sorgen machen, dass die so schnell wiederkommen. Also, nochma' danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4450] = {title = "Geschäftsbuch aus Tanaris", objective = "Nehmt die Abschrift von Goldstahls Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goldstahl in Tanaris aufsucht.", description = "Ach, wisst Ihr was? Da fällt mir grade was ein.\n\nWo ich doch immer noch hier drin festsitz: Wollt Ihr nich' vielleicht 'n kleinen Job für mich fertig machen, den ich angenommen hab, als ich in Tanaris war? Is' auch ganz einfach... na ja, wenn man nich' grade hier drin sitzt, jedenfalls.\n\nKrinkle Goldstahl in Gadgetzan war scharf auf so'n paar Sachen, die hier in der Sengenden Schlucht und an 'n paar anderen Orten gefunden wurden. Vielleicht könnt Ihr Euch ja die Liste einmal ansehen und ihm den Kram dann bringen?\n\nIch schieb Euch sein Geschäftsbuch unter der Tür durch, wenn Ihr interessiert seid. Bringt es ihm zusammen mit dem Zeug, das er will, nachdem Ihr den ganzen Kram eingesammelt habt.", progress = "Ja, bitte? Was kann ich für Euch tun, <Volk>? Ich bin fürchterlich beschäftigt und viele Kunden warten auf meine Dienste. Vielleicht könnt Ihr Euch ein wenig beeilen? Ich will ja nicht unhöflich sein, aber ich habe einfach keine Zeit - nicht, wenn ich mit all meiner Arbeit fertig werden möchte.", completion = "Oh, wie ich sehe, habt Ihr es für angebracht gehalten, einen Teil der Arbeit zu erledigen, um die ich gebeten hatte. Ausgezeichnet. Und ich dachte schon, Ihr wolltet, dass ich etwas für Euch fertige.\n\nDie sind alle perfekt... und es ist auch alles da. Danke, &lt;Klasse&gt;.\n\nEs kann vermutlich nichts schaden, Euch mit etwas zu belohnen... hmm, was würdet Ihr als nützlich erachten?", rewards = "Aufgeladene BlitzschlagruteGurt des VergeltungsaktsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4451] = {title = "Der Schlüssel zur Freiheit", objective = "Sucht in der Sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel für Rußschlacks Schuppen verwenden kann, den Ihr gefunden habt.", description = "Der kleine Messingschlüssel sieht recht einfach aus. Das Einzige, was ihn von anderen seiner Art unterscheidet, sind einige Worte, die darauf eingeritzt sind:\n\n\"Dunkeleisenplumpsklo - Nicht duplizieren.\"\n\nIhr habt absolut keine Ahnung, was das heißen soll oder wofür der Schlüssel gut ist.", progress = "*hust*\n\nWer is' da? Seht Ihr nich', dass ich beschäftigt bin?", completion = "Da brat mir doch einer... Wie, zum Geier... !? Ihr habt den Schlüssel gefunden! Ich wusste, dass die verdammten Dunkeleisenzwerge ihn versteckt ham, nachdem se mich hier eingesperrt hatten! Vielsten Dank, &lt;Name&gt;. Ihr seid echt Spitze! Na, dann dreht jetzt mal den Schüssel rum und lasst den alten Locheed hier raus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4461] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4462] = {title = "Verderbter Nachtdrache", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4463] = {title = "Buchband des Nachsinnens", objective = "Übergebt mir die Komponenten, sterbliches Geschöpf.\n\nDes Weiteren benötige ich Bezahlung in Gestalt von dreißig Goldstücken für diese Schöpfung.", description = nil, progress = "Übergebt mir die Komponenten, sterbliches Geschöpf.\n\nDes Weiteren benötige ich Bezahlung in Gestalt von dreißig Goldstücken für diese Schöpfung.", completion = "Nehmt den Plunder, Dummkopf. Und verlasst mich, damit ich mich meinen Studien widmen kann!", rewards = "Ihr bekommt:\n\nGeringes Arkanum des Nachsinnens"}
MultiLanguageQuestData['de'][4464] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4465] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4466] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4467] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil}
MultiLanguageQuestData['de'][4481] = {title = "Buchband der Konstitution", objective = "Für jedes Ding auf dieser Welt gilt es, einen Preis zu bezahlen. Und der Preis für den speziellen Gegenstand, den Ihr wünscht, beläuft sich auf dreißig Goldstücke.\n\nSelbstverständlich werde ich den Großteil der Komponenten, die Ihr eingesammelt habt, für mich selbst zurückbehalten. Doch sorgt Euch nicht, Ihr sollt Euren Plunder erhalten.", description = nil, progress = "Für jedes Ding auf dieser Welt gilt es, einen Preis zu bezahlen. Und der Preis für den speziellen Gegenstand, den Ihr wünscht, beläuft sich auf dreißig Goldstücke.\n\nSelbstverständlich werde ich den Großteil der Komponenten, die Ihr eingesammelt habt, für mich selbst zurückbehalten. Doch sorgt Euch nicht, Ihr sollt Euren Plunder erhalten.", completion = "Es ist eine Schande für sein Andenken... dass ein sterbliches Geschöpf wie Ihr seine Lebensaufgabe vollendet!\n\nNehmt Euer Gemisch und hebt Euch hinfort!", rewards = "Ihr bekommt:\n\nGeringes Arkanum der Konstitution"}
MultiLanguageQuestData['de'][4482] = {title = "Buchband der Hartnäckigkeit", objective = "Dreißig Goldstücke, <Volk>. Dreißig Goldstücke und die benötigten Komponenten.", description = nil, progress = "Dreißig Goldstücke, <Volk>. Dreißig Goldstücke und die benötigten Komponenten.", completion = "Es hat Kariel mehrere Eurer Lebensspannen gekostet, den Buchband fertig zu stellen, den Ihr jetzt in der Hand haltet, &lt;Volk&gt;. Und wozu das alles? Damit sein Jünger in der brennenden Steppe stehen und seine Forschungen missbrauchen kann, um ein unendliches Verlangen nach dem Arkanen zu befriedigen ... Verflucht sei diese elende Sucht.\n\nEuer Mangel an Mitgefühl und Eure unstillbare Gier ekeln mich an. Hinfort mit Euch!", rewards = "Ihr bekommt:\n\nGeringes Arkanum der Hartnäckigkeit"}
MultiLanguageQuestData['de'][4483] = {title = "Buchband der Abhärtung", objective = "Wenn es Widerstandsfähigkeit ist, die Ihr wünscht, so benötige ich dreißig Goldstücke.", description = nil, progress = "Wenn es Widerstandsfähigkeit ist, die Ihr wünscht, so benötige ich dreißig Goldstücke.", completion = "Auch andere Buchbände sind in dieser Welt verloren gegangen. Verloren an Orten, die zu betreten Ihr nie wagen würdet. Orte, die Euch beten lassen würden, dass es sie nicht gibt.\n\nIch werde die Energien dieser Komponenten in mich aufsaugen. Und Ihr werdet die überschüssigen Rückstände erhalten...", rewards = "Ihr bekommt:\n\nGeringes Arkanum der Abhärtung"}
MultiLanguageQuestData['de'][4484] = {title = "Buchband der Gier", objective = "Vergeudet meine Zeit nicht, <Volk>. Gebt mir das, was ich benötige. Dreißig Goldstücke und die Komponenten.", description = nil, progress = "Vergeudet meine Zeit nicht, <Volk>. Gebt mir das, was ich benötige. Dreißig Goldstücke und die Komponenten.", completion = "Mein Kopf hämmert... Die Energien der unendlichen Weiten, die unser Universum ausmachen... ARGGH!\n\n&lt;Mathredis scheint große Schmerzen zu haben.&gt;\n\nNehmt, was Ihr wünscht, und geht!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGeringes Arkanum der GierGeringes Arkanum der GierGeringes Arkanum der GierGeringes Arkanum der GierGeringes Arkanum der Gier"}
MultiLanguageQuestData['de'][4485] = {title = "Der Foliant des Adels", objective = "Sprecht mit Duthorian Rall in Sturmwind.", description = "Hallo, <Name>. Wie ich sehe, ist Eure Hingabe weiterhin stark, ebenso wie Euer Glaube.\n\nIch denke, es ist an der Zeit, dass Ihr mit Duthorian Rall in Sturmwind sprecht. Es gibt noch einige Lektionen, die Ihr lernen müsst, und ich spüre, dass Ihr dazu bereit seid.\n\nSucht ihn in der Kathedrale des Lichts auf... und, <Name>, nehmt diese Lektionen ernst! Ihr habt Euren derzeitigen Rang durch harte Arbeit und Demut erreicht, enttäuscht uns jetzt nicht, indem Ihr überheblich werdet.\n\nGehabt Euch wohl.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4486] = {title = "Der Foliant des Adels", objective = "Sprecht mit Duthorian Rall in Sturmwind.", description = "Nee, nee, nee. Jetzt sieh sich nur mal einer den mächtigen Paladin in all seinem Glanz an.\n\nTut mir leid, <Name>, war nicht böse gemeint... Ich werde nur manchmal ein bisschen neidisch, wenn ich sehe, was Ihr für tolle Taten vollbracht habt. Tiza hat gesagt, das sei meine Schwäche, und ich habe ihr geschworen, dass ich daran arbeiten würde. Aber manchmal ist das einfach schwer, wisst Ihr.\n\nAber der Grund, warum ich mit Euch sprechen wollte, war, dass Duthorian Rall in Sturmwind gesagt hat, Ihr solltet ihn in der Kathedrale des Lichts treffen, wenn Ihr bereit seid. Klang ziemlich wichtig. Klang, als sei irgendwas los.", progress = nil, completion = "Ah, Ihr seid zur Kathedrale zurückgekehrt, &lt;Name&gt;. Gut. In letzter Zeit ist viel geschehen und ich würde mich gern Eurer Hilfe versichern, solltet Ihr Euch würdig erweisen.\n\nEs gehen viele verräterische Feinde um. Ich werde Eure Hilfe benötigen, um sie aufzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4487] = {title = "Teufelsross beschwören", objective = "Sprecht mit Strahad Farsan in Ratschet.", description = "Ah, gut, da seid Ihr ja. Ich habe Euch <einen Sukkubus/eine Höllenbestie> hinterhergeschickt, um Eure Aufmerksamkeit zu erregen, aber es scheint, als sei es Euch gelungen herzukommen, ehe <er/sie> Euch gefunden hat. Einerlei.\n\nIn letzter Zeit gab es einiges an Gerede über Eure wachsende Macht - das ist gut für Euch und möglicherweise schlecht für andere. Doch das sind alles Nebensächlichkeiten. Wichtig ist nur, dass ich denke, dass Ihr Euch bewiesen habt und deswegen... hihi... einen gewissen Segen verdient.\n\nOberhalb von Ratschet im Brachland findet Ihr einen Mann namens Strahad. Ich glaube, Eure Wege haben sich bereits gekreuzt.", progress = nil, completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4488] = {title = "Teufelsross beschwören", objective = "Sprecht mit Strahad Farsan in Ratschet.", description = "Ah, <Name>, wie ich sehe, beehrt Ihr uns mit Eurer Anwesenheit. Wie wunderbar!\n\nIch hoffe, Ihr erwartet nicht auch noch, dass wir Euch von Kopf bis Fuß bedienen. Ihr mögt ja vielleicht schnell an Macht gewinnen, doch Ihr seid noch immer ein Kleinkind, was das wahre Wissen und das wahre Verständnis angeht. Wenn Ihr nicht aufpasst, wird die Verderbnis Euch und Euren schwachen Willen überwältigen.\n\nAber ich sollte zum Thema kommen: Strahad möchte mit Euch sprechen. Er wohnt noch immer im Brachland in seinem Turm, der Ratschet überblickt. Ich schlage vor, Ihr säumt nicht zu lange.", progress = nil, completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4489] = {title = "Teufelsross beschwören", objective = "Sprecht mit Strahad Farsan in Ratschet.", description = "Ihr da, <Volk>! Kommt her!\n\nIhr werdet <Name> gerufen, nicht wahr?\n\nDas habe ich mir gedacht. Ich fasse mich kurz: Ihr gewinnt an Macht und das ist nicht unbeobachtet geblieben. Und nun ist die Zeit gekommen, dass Ihr für Eure Anstrengungen belohnt werdet.\n\nBegebt Euch ins Brachland. Oberhalb von Ratschet findet Ihr dort Strahad Farsan - vielleicht erinnert Ihr Euch an ihn? Er möchte mit Euch sprechen. Ich würde nicht säumen.", progress = nil, completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4490] = {title = "Teufelsross beschwören", objective = "Sprecht in Ratschet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört.", description = "Ich möchte Euch eine Belohnung für Eure Geduld und Eure harte Arbeit geben. Doch wisset, dass sich die Fähigkeit, ein Teufelsross zu beschwören, in Zukunft wesentlich schwieriger gestalten wird. Ihr müsst sie Euch verdienen - und es wird nicht leicht sein.\n\nDoch geht nun fürs Erste, nehmt die Macht mit Euch, eine solche Kreatur zu beschwören, und verwendet diese Macht, wie Ihr es für richtig haltet.", progress = nil, completion = "Viel Glück, &lt;Name&gt;. Ich freue mich schon darauf, Euch in der Zukunft wiederzusehen.", rewards = "Ihr erlernt:\n\nTeufelsross\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4491] = {title = "Etwas Hilfe von guten Freunden", objective = "Führt Ringo zu Spraggel Frock in Marschalls Zuflucht.\n\nFalls Ringo ohnmächtig werden sollte, verwendet Spraggels Feldflasche, um ihn zu beleben.", description = "Argh... es ist so heiß...\n\nIch war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Ich muss wohl einen Hitzschlag haben.\n\nBitte, bringt mich zu meiner Freundin Spraggel in Marschalls Zuflucht zurück. Ich glaube, es geht mir noch gut genug, um Euch dorthin zu folgen.\n\nAber ich fühle mich ziemlich schwach. Wenn ich also noch mal in Ohnmacht fallen sollte, dann bespritzt mich einfach mit etwas Wasser aus Spraggles Feldflasche. Das sollte helfen, hoffe ich...", progress = nil, completion = "Ringo ist in keiner besonders guten Verfassung, &lt;Name&gt;, aber ich bin froh, dass ich ihn in einem Stück zurückhabe.\n\nDanke, dass Ihr ihn gefunden habt.", rewards = "Juwelenbesetzte BeinschützerBaumkronengamaschenVulkanhelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4492] = {title = "Verloren!", objective = "Sucht Ringo am Feuersäulengrat.", description = "Ihr müsst mir helfen, <Name>! Mein Freund Ringo ist vor einer Weile aufgebrochen, um den Vulkan südlich von hier zu erforschen, und er ist schon viel zu lange weg. Ich mache mir große Sorgen um ihn.\n\nMeint Ihr, Ihr könnt ihn suchen? Nehmt doch meine Feldflasche mit - wenn Ihr Ringo tatsächlich findet, dann hat er sie bestimmt nötig!", progress = "Wa... Was?", completion = "Oh... Ich bin ja so froh, dass mich jemand gefunden hat...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4493] = {title = "Der Marsch der Silithiden", objective = "Sprecht in Gadgetzan mit Alchemist Stößelbruch.", description = "Es scheint, als sei es die Absicht der Silithiden – nein, ihr ganzer Lebenszweck! –, alles zu verschlingen, was ihnen im Weg steht und was nicht zu ihrer eigenen Ökologie gehört. Nur darauf konzentrieren sie sich und darum stellen sie eine große Gefahr für alles Leben auf Azeroth dar.\n\nBis jetzt haben wir nur die Anfänge gesehen. Ich vermute, dass sie ihre Kraft aus einem Ort tiefer drinnen in Kalimdor beziehen: aus dem Krater von Un'Goro. Geht nach Gadgetzan in der Tanariswüste und sprecht mit Alchemist Stößelbruch. Erzählt ihm von meiner Theorie; er wird uns bestimmt dabei helfen, die Silithiden zu bekämpfen.", progress = nil, completion = "Ja, ich habe vermutet, dass Gracina Euch zu mir geschickt hat. Eure Erfahrung im Kampf gegen diese Biester ist unschätzbar wertvoll - meines Wissens nach hat bisher niemand sonst mit dieser Spezies zu tun gehabt. Was Gracinas Idee betrifft, dass sie aus dem Un'Goro Krater kommen... vielleicht tun sie das tatsächlich. Der Un'Goro ist ein geheimnisvoller und gefährlicher Dschungel westlich von hier. Vielleicht ist er auch der nächste Schritt auf dem Weg herauszufinden, was es mit den Silithiden auf sich hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4494] = {title = "Der Marsch der Silithiden", objective = "Sprecht in Gadgetzan mit Alchemist Stößelbruch.", description = "Es scheint, als sei es die Absicht der Silithiden – nein, ihr ganzer Lebenszweck! –, alles zu verschlingen, was ihnen im Weg steht und was nicht zu ihrer eigenen Ökologie gehört. Nur darauf konzentrieren sie sich und darum stellen sie eine große Gefahr für alles Leben auf Azeroth dar.\n\nBis jetzt haben wir nur die Anfänge gesehen. Ich vermute, dass sie ihre Kraft aus einem Ort tiefer drinnen in Kalimdor beziehen: aus dem Krater von Un'Goro. Geht nach Gadgetzan in der Tanariswüste und sprecht mit Alchemist Stößelbruch. Erzählt ihm von meiner Theorie; er wird uns bestimmt dabei helfen, die Silithiden zu bekämpfen.", progress = nil, completion = "Ja, ich habe vermutet, dass Zilzibin Euch zu mir geschickt hat. Eure Erfahrung im Kampf gegen diese Biester ist unschätzbar wertvoll - meines Wissens nach hat bisher niemand sonst mit dieser Spezies zu tun gehabt. Was Zils Idee betrifft, dass sie aus dem Un'Goro Krater kommen... vielleicht tun sie das tatsächlich. Der Un'Goro ist ein geheimnisvoller und gefährlicher Dschungel westlich von hier. Vielleicht ist er auch der nächste Schritt auf dem Weg herauszufinden, was es mit den Silithiden auf sich hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4495] = {title = "Ein guter Freund", objective = "Sucht Iverron an der Höhle im Norden.", description = "Ich habe einen Freund, Iverron, der mich normalerweise jeden Tag um dieselbe Zeit besucht. Komischerweise ist er heute noch nicht da gewesen - genau genommen ist er sogar schon etliche Stunden über seiner sonstigen Zeit.\n\nIch muss zugeben, ich bin etwas besorgt, <Name>. Iverron verbringt viel Zeit bei der Spinnenhöhle oben im Norden und ich bin sicher, Ihr wisst, wie gefährlich es dort ist - überall Spinnen!\n\nFalls Ihr zufällig dort vorbeikommen solltet, könntet Ihr dann nach ihm Ausschau halten?", progress = nil, completion = "Ich bin ja so froh, dass Ihr mich gefunden habt, &lt;Name&gt;. Woher habt Ihr gewusst, dass ich hier bin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4496] = {title = "Dschungelei", objective = "Bringt eine Gorishiduftdrüse und 5 Erdproben von Un'Goro zu Alchemist Stößelbruch in Gadgetzan.", description = "Meine Forschungen haben ergeben, dass die Silithiden den Bienen ähneln: Wenn man die Königin des Schwarmbaus tötet, dann sollte das den Rest in völliges Chaos stürzen. Ich werde einen Köder brauen, mit dem wir die Königin herauslocken können, und sobald sie draußen ist, streckt Ihr sie nieder.\n\nDoch zuerst brauchen wir einige Reagenzien; wir wollen doch nicht, dass Ihr völlig unvorbereitet im Dschungel umherstolpert. Geht nach Westen, sucht den Schwarmbau der Silithiden im Krater von Un'Goro und beschafft Euch eine Duftdrüse von einem der Viecher. Außerdem brauche ich einige Erdproben aus Un'Goro.", progress = "Eine geeignete Duftdrüse zu finden, könnte einige Zeit in Anspruch nehmen - die Drüse darf nicht beschädigt sein und das wird durch die Art und Weise, wie Ihr sie Euch beschaffen müsst, nicht gerade erleichtert. Was die Erdproben angeht, so denke ich, dass die sich ziemlich leicht finden lassen sollten.\n\nNun, wie dem auch sei - habt Ihr die Gegenstände, die ich brauche, um den Köder herzustellen?", completion = "Die Duftdrüse, ah ja. Die Membran scheint intakt zu sein - ausgezeichnet. Die Erde... ja, die ist genau richtig. Und jetzt sollte ich in der Lage sein, mit meinen besonderen Zutaten all dies zum perfekten Köder zu verarbeiten.\n\nGebt mir einen Moment Zeit, um den Köder herzustellen, &lt;Name&gt;. Sobald er fertig ist, können wir den nächsten Schritt unternehmen, der hoffentlich die Silithiden aufhält, bevor sie Gadgetzan überrennen - und den Rest von Kalimdor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4501] = {title = "Vorsicht, Pterrordax!", objective = "Tötet 10 rasende Pterrordax und sprecht dann mit Spraggel Frock in Marschalls Zuflucht.", description = "Gesucht: Ein fähiger Kämpfer, der sich der Bedrohung durch die Pterrordax im Krater von Un'Goro annimmt. Ihre Zahl wächst ständig und sie werden zu einer Bedrohung für die Reisenden in der Gegend.\n\nDezimiert den Bestand, indem Ihr 10 rasende Pterrordax tötet.\n\nSprecht mit Spraggel Frock, nachdem Ihr die Aufgabe erledigt habt, dann erhaltet Ihr eine Belohnung.", progress = nil, completion = "Ich habe schreckliche Angst vor den Pterrordax hier! Danke, dass Ihr ihre Anzahl reduziert habt, &lt;Name&gt;. Vielleicht fühle ich mich jetzt wieder sicher genug, um mich aus Marshals Zuflucht herauszutrauen.", rewards = "HöhlensteinhandschuheFelsplattenschienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4502] = {title = "Vulkanische Aktivität", objective = "Sammelt 9 Proben der Asche von Un'Goro von den Feuerelementaren am Vulkan im Krater von Un'Goro ein und bringt die Proben zu Liv Ritzelflick in Ratschet.", description = "Als Lehrling von Marvon Nietensucher habe ich unglaublich viel gelernt. Aber er ist jetzt schon sehr lange fort. Daher denke ich, werde ich an ein paar eigenen Experimenten arbeiten.\n\nIch habe kürzlich etwas über den Krater von Un'Goro gelesen und über die eigentümliche Vulkanaktivität, die in der Mitte des Kraters zu erkennen ist. Ich glaube, ich könnte eine Menge lernen, wenn ich nur etwas Asche von den Elementaren dort haben könnte.\n\nWürde es Euch etwas ausmachen, etwas Asche für mich einzusammeln, falls Ihr dort entlangkommen solltet?", progress = "Stimmt es, dass der Vulkan im Un'Goro aktiv ist? Ich bin sicher, ich könnte eine Menge aus der Asche des Vulkans lernen, <Name>.", completion = "Diese Proben sind einfach perfekt für meine Studien! Danke, &lt;Name&gt;! Ich verspreche auch, dass ich Euch als Erstem von meinen Ergebnissen berichten werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4503] = {title = "Sappalots Flieger", objective = "Sammelt 8 eingesponnene Dimetrodonschuppen und 8 eingesponnene Pterrordaxschuppen für Sappalot in Marschalls Zuflucht.", description = "Ich baue einen Flugapparat!\n\nIch bin hier gestrandet und habe leider absolut überhaupt keinen Orientierungssinn. Ich würde ja einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Viecher jagen mir einfach eine höllische Angst ein.\n\nAlso, werdet Ihr mir helfen? Ich muss nur noch die Flügel bauen und ich glaube, dass sich die eingesponnenen Schuppen von Pterrordax und Dimetrodonten perfekt dafür eignen würden. Ich werde mich zwar garantiert nicht mit denen anlegen, aber Ihr seht ziemlich zäh aus. Wollt Ihr es nicht versuchen?", progress = "Jedes berühmte Fahrzeug braucht einen Namen. Ich dachte, ich nenne es... Pwned!", completion = "Ja, diese Schuppen sind perfekt. Mit diesen Schuppen kriege ich meinen Flieger bestimmt in die Luft!\n\nDanke!", rewards = "Sappalots NieselblockerSappalots LaufSappalots MündungswischlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4504] = {title = "Superkleber", objective = "Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan.", description = "Ich bin immer auf der Suche nach neuen Methoden, um schnelles Gold zu verdienen, <Name>. Wenn Ihr mir bei meiner neuesten Idee helft, dann gebe ich Euch ein bisschen was vom Gewinn ab. Na, was sagt Ihr dazu?\n\nDas hab ich mir gedacht!\n\nGeht zu den Teergruben im Norden des Kraters von Un'Goro und beschafft mir etwas Teer. Aber nicht jeden x-beliebigen Teer, versteht Ihr? Ihr müsst den von den Kreaturen nehmen, die an den Teergruben leben. Normaler Teer ist einfach nicht klebrig genug.\n\nDie pflanzenartigen Kreaturen jedoch haben Chlorophyll in ihrer Haut, und wenn man das mit dem Teer mischt, dann wird das superklebrig!", progress = "Und Tran'rek hat es wieder einmal geschafft - dieser Superkleber wird der letzte Schrei!", completion = "Ja, dieser Teer ist genau richtig...\n\nHe, Moment mal, meine Hände! Ich krieg sie nicht mehr auseinander...\n\nVielleicht war das doch keine so gute Idee. Oh, wartet mal! Superklebeteerentferner! Da steckt das wahre Geld drin!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4505] = {title = "Brunnen der Verderbnis", objective = "Beschafft eine Probe verderbten Wassers vom Mondbrunnen der Jadefeuersatyrn und bringt sie zu Winna Hazzard am Blutgiftposten.", description = "Manche Leute sagen vielleicht, ich sei außergewöhnlich grausam... Aber in Wirklichkeit bin ich doch nur von dem Wunsch beseelt zu sehen, wie die Horde einen Vorteil gegenüber der Allianz erringt, und zwar auf jede nur mögliche Weise.\n\nSeit Kurzem interessiere ich mich für einen Mondbrunnen in den Ruinen von Constellas. Er soll südlich von hier liegen und von den Jadefeuersatyrn gepflegt werden. Der Mondbrunnen, der einst ein Symbol der Erneuerung für die unerträglichen Nachtelfen war, ist jetzt verderbt und wird dazu benutzt, neue Satyrn hervorzubringen.\n\nIch habe da eine Idee, <Name>, und ich hätte gern eine Probe von dem Wasser... für meinen kleinen Katzenfreund hier.", progress = "Das ist von äußerster Wichtigkeit. Macht Euch jetzt auf den Weg.", completion = "Wohlan denn. Wir müssen einen Weg finden, diese Verderbnis gegen unsere Feinde einzusetzen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4506] = {title = "Verderbte Säbler", objective = "Bringt Winnas Kätzchen zum verderbten Mondbrunnen, lasst es dort frei und bringt es dann wieder zu Winna zurück.\n\nSobald Ihr wieder bei Winna seid, klickt auf die Katze, um sie Winna zu übergeben.", description = "Dieses verderbte Wasser können wir zu unserem Vorteil verwenden, <Name>. Mit nur einer kleinen Menge Wasser wurde mein Kätzchen doppelt so groß und scheint jetzt irgendwie... stärker als vorher zu sein. Solche Katzen könnten sich noch als nützlich erweisen...\n\nHier, <Name>. Nehmt diesen Katzentransportkorb und lasst das Kätzchen darin neben dem Mondbrunnen in den Ruinen von Constellas frei. Hi, hi... Ich bin mir sicher, das Ergebnis wird Euch gefallen!\n\nBringt mir danach die Katze zurück, dann werde ich mich für Eure Zeit und Mühe erkenntlich zeigen.", progress = "Jetzt sagt mir nicht, dass Ihr nicht dorthin zurückgehen könnt! Geht schon!", completion = "Exzellent!\n\nDen Verlassenen ist jedes Mittel recht, um die Allianz zu zerschmettern! Das verderbte Wasser wird sich in Zukunft sicherlich noch als nützlich für unsere weiteren Bemühungen erweisen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4507] = {title = "Bauer schlägt Dame", objective = "Besiegt die Schwarmkönigin der Gorishi, sobald sie erscheint.\n\nBringt das Gehirn der Schwarmkönigin zu Alchemist Stößelbruch nach Gadgetzan.", description = "Hier ist der Köder. Im Schwarmbau sollte sich ein Kristall befinden. Wir glauben, dass die Silithiden den Kristall als eine Art Einstellungsgerät verwenden, das den ganzen Schwarmbau verbindet. Wo sich dieser Kristall befinden könnte, wollt Ihr wissen? Ich würde vorschlagen, Ihr versucht es in der Brutstätte innerhalb des Schwarmbaus.\n\nWenn Ihr den Köder bei dem Kristall benutzt, sollte das die Königin aufscheuchen, aber geht acht – sie ist wahrscheinlich von mehreren Wachen umgeben. Schaltet die Königin aus und entfernt ihr Gehirn. Ich weiß, das klingt eklig, aber wir müssen es unbedingt untersuchen. Viel Glück, <Name>!", progress = "Es ist von absoluter Wichtigkeit, dass wir das Gehirn der Königin für unsere Forschungen in die Hände bekommen. Das, was wir bisher in Erfahrung bringen konnten, lässt uns glauben, dass die Silithiden möglicherweise von einer bösartigen Intelligenz kontrolliert werden. Ich wage gar nicht daran zu denken, wer oder was etwas so Heimtückisches wie die Silithiden kontrollieren könnte, <Name>.", completion = "Phantastisch, &lt;Name&gt;! Wir haben hier und heute einen sehr bedeutsamen Sieg errungen. Es wird einige Zeit dauern, bis wir vollständig verstehen, was genau wir hier haben; aber wir werden das Beste daraus machen, nur keine Sorge.\n\nWas die Silithiden angeht, so glaube ich kaum, dass wir sie bereits in ihrer Gänze gesehen haben. Diese Lösung war zu sauber, es tut mir Leid, das sagen zu müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4508] = {title = "Die Ruhe vor dem Sturm", objective = "Bringt Stößelbruchs Bericht von Un'Goro zu Gracina Glaubensmacht in Darnassus.", description = "Meine jüngsten Ergebnisse und das Wissen, das wir heute hier gesammelt haben, müssen in die Hände von Leuten gelangen, die etwas damit anfangen können. So einfallsreich wir hier in Gadgetzan auch sein mögen, das hier können wir nicht allein schaffen.\n\nBringt meinen jüngsten Bericht zu Gracina Glaubensmacht nach Darnassus; sie hält sich doch immer noch im Tempel des Mondes auf, oder? Sie hat Freunde, und zwar ziemlich hohe Tiere innerhalb der Allianz; wenn wir die in diese Sache mit hineinziehen können, <Name>, dann haben wir vielleicht eine Chance, dies alles zu überleben.", progress = "Es sind alles Dummköpfe, <Name>! Sie würden niemals über den eigenen Tellerrand schauen, ob es nicht irgendwo eine größere Bedrohung geben könnte - ihr blinder Hass auf die Horde wird noch unser aller Ende bedeuten! Ich weiß nicht, was ich ihnen noch als Beweis für die Silithidenbedrohung liefern soll - ich kann sie doch nicht in einen der Schwarmbauten werfen, damit sie es mit eigenen Augen sehen!\n\nAber entschuldigt ... Ihr habt Neuigkeiten für mich?", completion = "Ich weiß dies zwar wirklich zu schätzen, aber leider bin ich mir nicht sicher, ob es uns irgendetwas bringen wird. Die Allianz ignoriert alle Bedrohungen, die nicht von der Horde ausgehen, und sogar unsere eigenen Anführer hier in Darnassus können sich nicht darauf einigen, was diese Bedrohung eigentlich ist. Narren wie Fandral Staghelm sind der Ansicht, dass die Silithiden längst nicht die Gefahr aus der Vergangenheit darstellen, für die ich sie halte. Seine Unwissenheit wird nur noch von seiner Arroganz übertroffen.\n\nIhr habt die Bedrohung doch selbst gesehen, &lt;Name&gt;. Wir müssen weiterhin alles tun, um die Silithiden zu besiegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4509] = {title = "Die Ruhe vor dem Sturm", objective = "Bringt Stößelbruchs Bericht von Un'Goro zu Zilzibin Tomtom in Orgrimmar.", description = "Meine jüngsten Ergebnisse und das Wissen, das wir heute hier gesammelt haben, müssen in die Hände von Leuten gelangen, die etwas damit anfangen können. So einfallsreich wir hier in Gadgetzan auch sein mögen, das hier können wir nicht allein schaffen.\n\nBringt meinen jüngsten Bericht zu Zilzibin Tomtom nach Orgrimmar; er lebt doch immer noch im oberen Teil der Gasse, oder? Er hat Freunde ziemlich weit oben in der Horde; wenn wir die mit in diese Sache hineinziehen können, <Name>, dann haben wir vielleicht eine Chance, dies alles zu überleben.", progress = "Es sind alles Dummköpfe, <Name>! Sie würden niemals über den eigenen Tellerrand schauen, ob es nicht irgendwo eine größere Bedrohung geben könnte - ihr blinder Hass auf die Allianz wird noch unser aller Ende bedeuten! Ich weiß nicht, was ich ihnen noch alles als Beweis für die Silithidenbedrohung liefern soll - ich kann sie doch nicht in einen der Schwarmbauten werfen, damit sie es mit eigenen Augen sehen!\n\nAber entschuldigt ... Ihr habt Neuigkeiten für mich?", completion = "Ich weiß dies zwar wirklich zu schätzen, aber leider bin ich mir nicht sicher, ob es uns irgendetwas bringen wird. Die Horde ignoriert alle Bedrohungen, die nicht von der Allianz ausgehen. Während Thrall selbst vielleicht sogar handeln würde, wenn ihm die Fakten vorgelegt würden, so wird er doch von allen Seiten mit widersprüchlichem Rat bestürmt. Wenn es nach diesen Narren ginge, dann müssten wir uns pausenlos im Kreis drehen, wenn sie nur der Meinung wären, dass wir der Allianz damit schaden könnten!\n\nIhr habt die Bedrohung doch selbst gesehen, &lt;Name&gt;. Wir müssen weiterhin alles tun, um die Silithiden zu besiegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4510] = {title = "Die Ruhe vor dem Sturm", objective = "Bringt den Bankgutschein zu Idriana in der Bank von Darnassus.", description = "<Name>, Eure Hilfe war wirklich unschätzbar wertvoll. Es wird zweifellos der Moment kommen, an dem ich erneut um Euren Beistand im Kampf gegen die Silithiden bitten muss. Wir müssen erst verarbeiten, was wir im Krater von Un'Goro gelernt haben - ich fürchte, dass meine ursprüngliche Annahme, die Silithiden kämen aus dem Un'Goro, falsch war... dass an einem anderen Ort tatsächlich eine wesentlich stärkere Präsenz existiert.\n\nBringt diese Nachricht zu Idriana in der Bank. Sie wird Euch etwas aus meinem Gewölbe geben, das Ihr als Zeichen meiner Dankbarkeit ansehen sollt. Ich danke Euch für Eure mutige Unterstützung, <Klasse>.", progress = "Elune'adore, <Klasse>. Was kann ich heute für Euch tun?", completion = "Dieser Bankgutschein ermächtigt mich, einen Gegenstand aus Gracina Spiritmights Konto bei uns zu entnehmen und Euch zu übergeben. Es scheint, als seien Glückwünsche angebracht!", rewards = "Sagenumwobene SchiftungScheuende SchienbeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nVergessenheitskugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4511] = {title = "Die Ruhe vor dem Sturm", objective = "Bringt den Bankgutschein zu Karus in der Bank von Orgrimmar.", description = "<Name>, ohne Euch wären wir niemals so weit gekommen. Es wird zweifellos der Moment kommen, an dem ich erneut um Eure Hilfe im Kampf gegen die Silithiden bitten muss. Wir müssen erst verarbeiten, was wir im Krater von Un'Goro gelernt haben - ich fürchte, dass meine ursprüngliche Annahme, die Silithiden kämen aus dem Un'Goro, falsch war... dass an einem anderen Ort tatsächlich eine wesentlich stärkere Präsenz existiert.\n\nBringt diese Nachricht zu Karus in der Bank. Er wird Euch etwas aus meinem Gewölbe geben, das Ihr als Zeichen meiner Dankbarkeit ansehen sollt. Danke für Eure tatkräftige Unterstützung, <Klasse>.", progress = "Zug-zug! Wie kann ich Euch heute helfen, <Klasse>?", completion = "Dieser Bankgutschein ermächtigt mich, einen Gegenstand aus Zilzibin Drumlores Konto bei uns zu entnehmen und Euch zu übergeben. Es scheint, als seien Glückwünsche angebracht!", rewards = "Sagenumwobene SchiftungScheuende SchienbeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nVergessenheitskugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4512] = {title = "Schlamm auf Abwegen", objective = "Bringt 6 mit verfluchtem Schlamm gefüllte Gläser und 6 mit besudeltem Schlamm gefüllte Gläser zu Laris Bummelritzel in Eisenschmiede.", description = "Aber womit ich mich am meisten beschäftigt habe, das sind Schlamme. Ich weiß, das klingt seltsam, aber die sind wirklich überall!\n\nVor Kurzem habe ich einer Dame in Menethil dabei geholfen, ihre Tasche wiederzufinden - ein Schlamm hatte sie gefressen. Ich habe auch gesehen, wie Mitglieder der Königlichen Apothekervereinigung aus Unterstadt Proben von dem Zeug sammelten. Ich möchte wissen, wieso! Wo kommt es her?\n\nIch habe auch gehört, dass es im Teufelswald noch mehr davon geben soll. Ich brauche einige Proben von den Schlammen dort, damit ich meine Forschungen weiter vorantreiben kann. Ich gebe Euch einige Behälter mit; verwendet diese, um eine Probe von den toten Kreaturen einzusammeln.", progress = "Schon einige meiner bisherigen Experimente waren absolut faszinierend. Ich glaube, mit ein bisschen mehr Arbeit kann ich noch genauer herausfinden, was es mit diesen Kreaturen auf sich hat und welchen Zusammenhang es zwischen ihnen und der Entwicklung des Lebens auf Azeroth gibt - falls ein solcher Zusammenhang überhaupt existiert.\n\nEine meiner Haupttheorien - die allerdings nicht auf sonderlich viel Gegenliebe stößt - ist der Gedanke, dass die Brühschlammer und Brühschleimer irgendwie mit der Erschaffung dieses Planeten zusammenhängen ... fast so, als seien sie eine seiner Ausscheidungen.\n\nAber das kann ich nicht beweisen oder widerlegen, solange ich nicht mehr Proben bekomme.", completion = "Ganz erstaunlich, &lt;Name&gt;! Ihr seid nahe genug herangekommen, um eine Probe der verderbten Wesen zu erhalten, und dabei seht Ihr nicht mitgenommener aus als vorher! Danke. Oh, diese Exemplare eignen sich perfekt. Ich kann es kaum erwarten, meine Versuche daran zu beginnen.\n\nWenn ich Recht habe, dann bin ich vielleicht bald einer der größten Wissenschaftler der Forscherliga!\n\nDas wird allen Zwergen beweisen, dass es kein Fehler war, uns Gnomen nach dem Vorfall in Gnomeregan nach Ironforge hineinzulassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4513] = {title = "Schlamm auf Abwegen", objective = "Bringt 10 gefüllte reine Probengläser zu Laris Bummelritzel in Eisenschmiede.\n\nFalls Ihr Probleme habt, fündig zu werden, dann kann Laris Euch vielleicht noch den einen oder anderen Hinweis geben.", description = "Ich brauche noch mehr Proben, <Name>. Aber - und ich weiß nicht so recht, wie ich das ausdrücken soll - es müssen reine Proben sein. Ich weiß, ich weiß. \"Was meint Ihr mit 'rein', Laris?\", fragt Ihr. Ich kann es nicht genau sagen. Ich weiß, dass die hier verderbt sind... genau wie im Teufelswald. Und genau deswegen ist meine Erkenntnis so wichtig. Die Schlamme scheinen sich anzupassen... die Eigenschaften der Gegend anzunehmen, in der sie sich befinden. Ich muss Proben finden, die nicht verunreinigt sind. Aber wo? Wo?!\n\nPah! <Name>, nehmt diese Behälter einfach mit, nur für den Fall, dass Ihr irgendwo welche finden solltet.", progress = "So viel, über das man nachdenken muss. Aber was bedeutet es alles? Und wie wirkt es sich auf die Bevölkerung von Azeroth aus?", completion = "Ihr habt es gefunden? &lt;Name&gt;, Ihr seid ein wahrer Schatz. Eure Hingabe und Eure Hilfe waren einfach fabelhaft und ich kann Euch gar nicht genug danken.\n\nBitte, nehmt dies für Eure Mühen. Es wartet Arbeit auf mich, aber ich bin sicher, dass ich Eure Dienste erneut in Anspruch nehmen werde, wenn Ihr später wiederkommt.\n\nDanke. Vielen herzlichen Dank.", rewards = "DunstschleierstiefelMutige StulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4521] = {title = "Wilde Wächter", objective = "Trull Scheiterbann im Teufelswald möchte, dass Ihr 15 tobende Eulenbestien und 15 struppige Eulenbestien tötet.", description = "Winterquell liegt gleich hinter der Holzschlundfeste, im Nordosten des Teufelswalds. Seid Ihr schon mal dort gewesen?\n\nIch habe gehört, dass es in jener Region nur so von Kreaturen wimmeln soll, die Wildekin genannt werden. Diese Bestien sind dafür bekannt, dass sie Geheimnisse bewachen, und zwar Geheimnisse der Nachtelfen.\n\nWir müssen herausfinden, was in Winterquell verborgen liegt.\n\nIch habe gehört, die struppigen Eulenbestien findet man südlich von der Straße, und außerdem soll es noch so genannte tobende Eulenbestien geben, die im Zentrum von Winterquell zu finden sind. Räumt sie aus dem Weg und verschafft Euch so Zutritt zu dem Gebiet.", progress = nil, completion = "Das sind ausgezeichnete Neuigkeiten, &lt;Name&gt;. Jetzt, wo diese Bestien aus dem Weg geschafft sind, können wir uns weiter nach Winterspring hineinwagen. Seid Ihr bereit für neue Taten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4542] = {title = "Nachricht zum Freiwindposten", objective = "Bringt Klippenbehüter Langhorn am Freiwindposten die dringende Nachricht.", description = "<Tapferer Reisender/Tapfere Reisende>, die Zentauren haben ihre Angriffe in diesem Gebiet verstärkt. Der Freiwindposten muss umgehend über diese erneuten Angriffe informiert werden! Sucht Klippenbehüter Langhorn am Freiwindposten im Südosten auf und gebt ihm diese dringende Nachricht.\n\nDoch seht Euch vor und geht dem hier in der Nähe herumlungernden Grimmtotemklan aus dem Weg... in letzter Zeit benehmen die Leute sich seltsam uns gegenüber.", progress = "Was wollt Ihr, <Klasse>? Eine dringende Botschaft - für mich?", completion = "Noch mehr schlechte Nachrichten! Jetzt sind diese Zentauren zu weit gegangen! Sie haben eine meiner Nachschubkarawanen überfallen und die gesamte Truppe abgeschlachtet. Das ist ungeheuerlich und wird nicht ohne Strafe bleiben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4561] = {title = "Test auf Unreinheiten - Krater von Un'Goro", objective = "Ihr nehmt eine Brühschleimerprobe aus dem Un'Goro Krater und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Brühschleimer seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure geläuterten Un'Goro-Brühschleimerproben sowie einige andere Rückstände enthält.", description = nil, progress = "Ihr nehmt eine Brühschleimerprobe aus dem Un'Goro Krater und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Brühschleimer seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure geläuterten Un'Goro-Brühschleimerproben sowie einige andere Rückstände enthält.", completion = "Ihr hebt die Petrischale mit der Brühschleimerprobe hoch. Der einzige Weg, um herauszufinden, ob die Probe rein genug ist, wird sein, die Schale zu öffnen und deren Inhalt selbst zu untersuchen. Im besten Falle findet Ihr eine Probe, die Chemiker Fuelys Ansprüchen genügt.", rewards = "Ihr bekommt:\n\nGeprüfte Probe von Un'Goro"}
MultiLanguageQuestData['de'][4581] = {title = "Kayneth Stillwind", objective = "Bringt Shindrells Notiz zu Kayneth Stillwind in Waldeslied.", description = "Der Druide Kayneth Stillwind hat sich bei mir gemeldet. Er hätte gern einen Bericht über das, was an unserer Küste und in den Wäldern um Astranaar vorgeht. Er befürchtet, dass eine Verderbnis durch das Eschental zieht... und vielleicht hat er Recht damit.\n\nHier, bringt ihm meinen Bericht. Ihr werdet ihn im Schrein von Waldeslied finden, im Nachtweisenwald im Osten.", progress = "Habt Ihr etwas für mich?", completion = "Ah, Shindrells Bericht! Vielen Dank, &lt;Name&gt;. Shindrell ist, wie eine gute Schildwache sein muss: mutig und aufmerksam. Ich muss das hier lesen; vielleicht finden sich darin Hinweise auf ein Übel, von dem ich fürchte, dass es durch Ashenvale zieht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4601] = {title = "Der Funkelmat 5200!", objective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftig peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt während er hin und her schlingert...", rewards = nil}
MultiLanguageQuestData['de'][4602] = {title = "Der Funkelmat 5200!", objective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt, als er hin und her schlingert...", rewards = nil}
MultiLanguageQuestData['de'][4603] = {title = "Funkelmatastisch", objective = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", description = nil, progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomen-Lösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"}
MultiLanguageQuestData['de'][4604] = {title = "Funkelmatastisch", objective = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", description = nil, progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomen-Lösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"}
MultiLanguageQuestData['de'][4605] = {title = "Der Funkelmat 5200!", objective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"}
MultiLanguageQuestData['de'][4606] = {title = "Der Funkelmat 5200!", objective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"}
MultiLanguageQuestData['de'][4621] = {title = "Segel setzen, Admiral!", objective = "Tötet Flottenmeister Seehorn und Baron Revilgaz aus Beutebucht und kehrt dann zu Flottenmeister Firallon zurück. Er befindet sich auf der Purpurschleier vor der Küste des Schlingendorntals.", description = "Jetz' hört mal zu, <oller Seebär/olle Piratenbraut>... Wegen der Machthaber in Beutebucht könn'n wir Blutsegel nich' hinsegeln, wo wir woll'n, und uns nich' das nehm'n, was wir als Beute ha'm woll'n. Tätet Ihr aber Flottenmeister Seehorn 'n Messer verpass'n, dann würd'n wir nie wieder mit 'nem Schiff aus Beutebucht aneinander geraten tun. Tätet Ihr Baron Revilgaz 'n Messer verpass'n, dann müsst'n wir uns nie wieder denen ihrem Gesetz stellen.\n\nWenn Ihr also 'n Admiral ehrenhalber bei uns werd'n wollt - ja, ADMIRAL hab ich gesagt! - dann verpasst den beiden 'n Messer, wie ich's gesagt hab. Un' jetz' geht, <Jungchen/Mädel>, un' kommt wieder, sobald Ihr's gemacht habt.", progress = nil, completion = "Holla... Admiral &lt;Name&gt;! Ihr seid 'n Pirat nach meinem Geschmack, Jungchen.\n\n's erwärmt mir das Herz, dass ich Euch den Hut hier geben tu. So einen findet Ihr nich' noch mal, nirgendswo nich, und alle, die Euch anseh'n, wer'n sofort wissen, dass Ihr 'n Admiral von der Flotte der Blutsegelbukaniere seid!", rewards = "Ihr bekommt:\n\nBlutsegeladmiralshut"}
MultiLanguageQuestData['de'][4641] = {title = "Euer Platz in der Welt", objective = "Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen.", description = "Endlich seid Ihr alt genug, <Name>... alt genug, um im Namen der Horde zu kämpfen. Um für den Ruhm des Kriegshäuptlings Siege zu erringen.\n\nJa...\n\n<Kaltunk mustert Euch.>\n\nDoch, doch, Ihr eignet Euch.\n\nZweifellos wollt Ihr Euch einen mächtigen Drachen oder einen Dämon suchen und ihn mit bloßen Händen erwürgen, aber vielleicht ist es vernünftiger, wenn Ihr mit etwas weniger... Gefährlichem anfinget.\n\n<Kaltunk lacht.>\n\nMeldet Euch bei Gornek; der sollte Euch eine Aufgabe zuweisen können, die zu einem wie Euch passt, <Klasse>. Ihr findet Gornek im Höhlenbau im Westen.", progress = nil, completion = "Wieder einer von Kaltunks Rekruten, was?\n\nEs ist wirklich schlecht um die Horde bestellt, wenn das das Beste ist, was wir auf die Beine stellen können. Einerlei. Wenn es so weit ist und wir erkennen, dass Ihr bereit seid, das Tal zu verlassen, werdet Ihr ein stolzer Krieger der Horde sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4642] = {title = "Vereinigung von Einflüssen", objective = "Bringt eine Probe verschmolzenem Schlamms zum Chemiker Brenner in Unterstadt.", description = "Hier drin eingeschlossen ist einer von den Schlammen, die Ihr im Teufelswald eingesammelt habt. Bringt das Behältnis zum Krater von Un'Goro und sucht dort einen reinen Schlamm - einer von den Urzeitschlammen wird's tun, denke ich. Sobald Ihr nahe genug heran seid, lasst den Schlamm aus dem Behältnis frei, und dann wollen wir doch mal sehen, was die beiden voneinander halten.\n\nBringt mir nach dem Ende des Experiments eine Probe von dem, was anschließend noch übrig ist. Ich erwarte Euch hier im Apothekarium.", progress = "Wie läuft das Experiment, <Name>? Ich werde weiter die Proben studieren, die Ihr mir beschafft habt - langsam verstehe ich, warum sich Lady Sylvanas so sehr für diese Kreaturen interessiert. Sollten sie wirklich ein Teil der Alten Götter sein, wer weiß, wie wir das zu unserem Vorteil ausnutzen können ...", completion = "Oh, ganz ausgezeichnet, &lt;Name&gt;. Wirklich ganz ausgezeichnet.\n\nWas für eine Geschichte. Wer hätte gedacht, dass die beiden auf diese Weise miteinander interagieren würden... Ich muss mich wohl eingehender mit den Umweltbedingungen auseinander setzen, die diese Veränderungen in den Kreaturen auslösen.\n\nAlso werde ich meine Forschungen jetzt fortsetzen. Vielleicht sehen wir uns bald wieder. Bis dahin wünsche ich Euch alles Gute.", rewards = "Kittel des ChemikersAuf Euch wartet eine dieser Belohnungen:\n\nRing des Chemikers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4661] = {title = "Test für Verderbnis - Teufelswald", objective = "Ihr nehmt eine Brühschlammerprobe aus dem Teufelswald und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Schleim seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure veränderten Teufelswaldschleimproben und einige andere Rückstände enthält.", description = nil, progress = "Ihr nehmt eine Brühschlammerprobe aus dem Teufelswald und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Schleim seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure veränderten Teufelswaldschleimproben und einige andere Rückstände enthält.", completion = "Ihr hebt die Petrischale mit der Brühschleimerprobe hoch. Der einzige Weg, um herauszufinden, ob die Probe rein genug ist, wird sein, die Schale zu öffnen und deren Inhalt selbst zu untersuchen. Im besten Falle findet Ihr eine Probe, die Chemiker Fuelys Ansprüchen genügt.", rewards = "Ihr bekommt:\n\nVerderbte geprüfte Probe"}
MultiLanguageQuestData['de'][4681] = {title = "An Land gespült", objective = "Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde.", description = "Die gestrandete Kreatur ist kein Einzelfall hier in Dunkelküste. Entlang der Ufer und sogar im Wasser gibt es noch mehr davon. Ich möchte, dass Ihr einen weiteren Fall untersucht, von dem wir wissen - da wurde die Kreatur westlich von Auberdine im Meer gesichtet, und zwar in der Nähe eines gesunkenen Schiffes. Kommt mit allem, was Ihr findet und was uns bei unseren Forschungen behilflich sein könnte, zu mir zurück.\n\nAußerdem begegnet Ihr auf Euren Reisen vielleicht auch noch anderen Kreaturen. Falls Ihr etwas entdecken solltet, dann zögert bitte nicht und informiert uns darüber!", progress = "Sobald Ihr die Überreste der Kreatur in den Gewässern westlich von hier untersucht habt, kann ich einen ordentlichen Bericht für den Tempel des Mondes in Darnassus verfassen. Vielleicht sind wir dann etwas näher an der Lösung des Rätsels, warum diese armen Kreaturen sich dazu entschlossen haben, ihr Leben an der Küste von Dunkelküste auszuhauchen.", completion = "Ihr seid mir hier und heute eine große Hilfe gewesen. Jetzt haben wir eine reelle Chance, hinter das Geheimnis zu kommen, warum diese Kreaturen sich an den Ufern von Dunkelküste auf den Strand werfen. Der Gedanke, dass sie vielleicht aus der Gegend um Teldrassil fliehen, ist beunruhigend. Solltet Ihr auf Euren Reisen auf andere, ähnliche Kreaturen treffen, dann lasst es mich bitte wissen. Wir befinden uns mit unserer Forschung noch ganz am Anfang.\n\nBitte, nehmt im Namen des Tempels des Mondes dies als Dank für Eure Bemühungen an. Danke, &lt;Name&gt;!", rewards = "Stiefel des SandsuchersTrockenrankengürtelDoppelgreifarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4701] = {title = "Stellt sie ab", objective = "Begebt Euch zur Schwarzfelsspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.", description = "Zweifellos habt Ihr die Worgs schon gesehen, die die Orcs des Schwarzfels befehligen.\n\nEs ist seltsam... ganz egal, wie viele wir vernichten, es scheinen nie weniger zu werden. Meine Späher haben berichtet, dass die Worgs gezüchtet, trainiert und schließlich von der Schwarzfelsspitze exportiert werden: der Hauptstadt der Schwarzfelsorcs. Ihr müsst Euch zur Schwarzfelsspitze begeben und der Quelle dieser Bedrohung auf den Grund gehen. Ihr auf den Grund gehen... und sie vernichten.\n\nViel Glück, <Name>. Möge Cenarius Euch beschützen...", progress = nil, completion = "Denkt nicht länger über ihr Leiden nach, &lt;Name&gt;. Jene Bestie war verderbt - ein Produkt dunkler Magie. Ihr habt der Allianz einen großen Dienst erwiesen und sollt dafür belohnt werden.", rewards = "AstoriarobenFallenstellerwamsJadeschuppenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4721] = {title = "Wilde Wächter", objective = "Trull Scheiterbann im Teufelswald möchte, dass Ihr in Winterquell 10 Berserkereulenbestien jagt.", description = "Es sind Läufer aus Winterquell zurückgekehrt, die berichten, dass es im Süden von Winterquell eine Reihe kleiner Höhlen gibt. Es scheint, als würden sich im Gebiet um diese Höhlen herum Wildekin aufhalten. Falls sie wirklich irgendetwas Wertvolles bewachen, so ist das der Ort, an dem wir es finden werden, denke ich.\n\nIhr werdet feststellen, dass diese Wildekin eine etwas größere Herausforderung sind als die, mit denen Ihr Euch bisher herumgeschlagen habt, <Name>. Es scheint, als hätte genau das, was diese Kreaturen beschützen wollen, sie in den Wahnsinn getrieben.", progress = nil, completion = "Vor harter Arbeit habe ich großen Respekt, &lt;Name&gt;. Jetzt können wir unsere Pläne mit Winterspring weiter vorantreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4722] = {title = "Gestrandete Meeresschildkröte", objective = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Ihr findet den Kadaver einer Meeresschildkröte, die sich vor einiger Zeit an das Ufer von Dunkelküste an den Strand geworfen hat. Der Kadaver wurde von den Murlocs gefleddert, die um die Überreste der Kreatur herum ihr Lager aufgeschlagen haben. Dennoch scheinen an den Überresten der Kreatur noch einige geeignete Proben zu haften, aus denen Gwennyth Bly'Leggonde aus Auberdine vielleicht noch etwas machen kann.", progress = "Hallo, <Name>... habt Ihr irgendwelche Kreaturen entdeckt, die an Land gespült wurden und von denen Ihr mir berichten wollt?", completion = "Eine weitere Entdeckung, die wir untersuchen können - gut gemacht, &lt;Name&gt;! Diese Überreste werden gründlich untersucht, sobald sie in Darnassus ankommen. Bitte nehmt dieses kleine Honorar an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4723] = {title = "Gestrandete Meereskreatur", objective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Die Überreste eines riesigen Dreschers - viel größer als alles, was Ihr in Dunkelküste zu finden erwartet hättet - liegen gestrandet an der Küste des Nebelrandes. Wie es diese Kreatur hierher verschlagen hat, ist nicht zu sagen - die Murlocs, die sich jetzt an dem Gerippe gütlich tun, sehen viel zu schwach aus, als hätten sie, selbst in großer Anzahl, die Bestie erlegen können. \n\nWährend ein Teil des Kadavers bereits sauber abgenagt wurde, ist doch noch genug davon übrig, um Gwennyth Bly'Leggonde aus Auberdine eine Probe zur Untersuchung bringen zu können.", progress = "Vielleicht werden wir eines schönen Tages einen Weg finden, wie wir verhindern können, dass diese armen Kreaturen ohne jeden Sinn und Zweck ihr Leben an den Ufern von Dunkelküste aushauchen. Doch bis dahin müssen wir unsere Forschungen fortsetzen!\n\nSeid gegrüßt, <Name>... welche Neuigkeiten bringt Ihr?", completion = "Noch eine Entdeckung, gut gemacht, &lt;Name&gt;! Diese Überreste werden gründlich untersucht, sobald sie in Darnassus ankommen. Bitte nehmt dieses kleine Honorar an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4724] = {title = "Die Herrin der Meute", objective = "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte.", description = "Manche sagen, die vom Schwarzfelsklan kontrollierten Worgs seien durch eine übernatürliche Macht erschaffen worden. Andere wiederum sagen, es seien gar keine echten Worgs, sondern eine Art dämonische Hunde, die den Orcs von einem gefallenen Grubenlord überlassen wurden.\n\nDie Wahrheit ist wesentlich weniger weit hergeholt, aber nicht weniger erschreckend. Die Worgs des Schwarzfels stammen von Halycon und ihrem Partner. Halycon ist die gewaltige Höhlenmutter der Worgs. Und ihr Partner? Es hat noch niemand überlebt, der etwas über diesen Partner sagen konnte.\n\nTrefft die Worgs dort, wo es ihnen am meisten wehtut. Vernichtet Halycon...aber, <Name>, seid auf der Hut.", progress = nil, completion = "Tollwütige Welpen? Gizrul der Geifernde? Und Ihr seid noch am Leben, um davon zu berichten?! Unglaublich! Diese Belohnung habt Ihr Euch wohl verdient!", rewards = "AstoriarobenFallenstellerwamsJadeschuppenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4725] = {title = "Gestrandete Meeresschildkröte", objective = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Entlang der Küste liegen weitere Überreste von gestrandeten Meeresschildkröten. Bei diesem speziellen Kadaver ist eine Art Sänfte auf dem Panzer der Schildkröte angebracht. Vielleicht wurde diese Kreatur von unbekannten Wesen an den Strand getrieben, statt sich selbst auf Strand zu setzen, wie sich aus einigen der anderen Überreste schließen ließ. Grauflossenmurlocs haben sich jetzt an den Überresten der Kreatur niedergelassen und fressen das Aas.\n\nIn der Sänfte findet Ihr einen Kasten mit seltsamen Zeichen darauf - vielleicht kann Gwennyth Bly'Leggonde in Auberdine sich einen Reim darauf machen.", progress = "Es ist mir eine Freude, Euch wiederzusehen, <Name>. Zwar machen wir große Fortschritte bei der Lösung des Rätsels, warum so majestätische Meereskreaturen sich selbst an den Ufern von Dunkelküste auf Strand setzen, aber es kommt mir so vor, als würde jede beantwortete Frage zwei neue aufwerfen.\n\nSeid Ihr hier, um uns bei unseren Forschungen behilflich zu sein?", completion = "Ich habe schon von solchen Sänften gehört, wie Ihr sie auf dem Rücken jener Meeresschildkröte gefunden habt. Ich glaube, es handelt sich dabei um Nagasänften, die diese sowohl im Kampf verwenden als auch, um Vorräte an Land zu befördern. Die Zeichen auf dem Kasten, den Ihr gefunden habt, stammen von den Naga - das könnte auch ihr massiertes Eindringen im nördlichsten Teil von Dunkelküste erklären.\n\nIch schicke diesen Kasten nach Darnassus, zusammen mit Euren übrigen Entdeckungen. Das ist für Euch - nochmals danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4726] = {title = "Brutlingessenz", objective = "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe.", description = "Schon seit Wochen studiere ich die Drachkin der Brennenden Steppe und ich glaube, mir ist endlich ein Durchbruch gelungen! Ich habe ein Gerät gebaut - ich habe es Draco-Incarcinatrix 900 getauft -, mit dem ich die Essenz von Großdrachenwelpenbrutlingen einfangen kann!\n\nOder zumindest glaube ich das.\n\nHier, nehmt das Gerät und zappt damit einen Brutling in der Brennenden Steppe. Wenn Ihr den Brutling dann besiegt, während er sich noch unter dem Einfluss des Geräts befindet, dann sollte eigentlich seine Essenz freigesetzt werden.\n\nWenn dem so ist, dann prima! Bringt mir ein paar Proben zurück, damit ich sie studieren kann.", progress = "Habt Ihr die Brutlingessenz, <Name>? Ich kann es kaum erwarten, sie zu studieren.\n\nUnd ganz abgesehen davon, ist mein Kunde nicht gerade jemand, den man gern enttäuscht...", completion = "Es hat geklappt! Ihr habt die Essenz! Gut gemacht, &lt;Name&gt;! Gut gemacht!\n\nDiese Essenz wird für meine Forschungen von unschätzbarem Wert sein. Ich hoffe, dass ich eines Tages herausfinden werde, wie ich lebende Großdrachenwelpen einfangen oder mir zumindest ihre Eier beschaffen kann. Wenn mir dies gelänge, dann würden mich alle Drachenforscher auf der ganzen Welt beneiden!\n\nMein Auftraggeber wäre auch zufrieden - und wie ich schon sagte, ist er jemand, den man besser zufrieden stellen sollte ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4727] = {title = "Gestrandete Meeresschildkröte", objective = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Am Sandstrand im Norden von Dunkelküste liegen die skelettierten Überreste einer Meeresschildkröte. Entweder haben die Grauflossenmurlocs dieses Gerippe nicht gefunden, oder sie haben es zwar gefunden, halten sich aber aus irgendeinem unbekannten Grund davon fern. Wie dem auch sei, es ist genug von der Schildkröte übrig, dass Ihr Gwennyth Bly'Leggonde in Auberdine eine Probe bringen könnt, damit der Tempel des Mondes diese studieren kann.", progress = "Hallo, <Name>, habt Ihr weitere gestrandete Kreaturen gefunden, über die der Tempel des Mondes Bescheid wissen sollte?", completion = "Es ist interessant, dass an der Stelle keine Murlocs waren. Das dürfen wir nicht außer Acht lassen, wenn wir die Überreste dieser Kreatur untersuchen. Ich danke Euch für Eure Bemühungen, &lt;Name&gt;. Im Namen des Tempels des Mondes soll ich Euch dies geben, zur Entschädigung für die von Euch aufgewendete Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4728] = {title = "Gestrandete Meereskreatur", objective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Der Kadaver von etwas, das wie ein riesiger Meeressäuger aussieht, liegt teilweise ausgeweidet am Strand. Eine Schubkarre und verschiedenste Werkzeuge liegen bei der riesigen, gestrandeten Meereskreatur verstreut, ganz so, als habe schon einmal jemand den Versuch unternommen, sie zu untersuchen. Zwar wurde die Bestie bereits von Murlocs zerfleddert, doch es ist noch genug davon übrig, um eine passende Probe für Gwennyth Bly'Leggonde aus Auberdine einzusammeln.", progress = "Seid mir erneut gegrüßt, <Name>! Was führt Euch nach Auberdine zurück? Seid Ihr vielleicht hier, um mir von einer weiteren Entdeckung zu berichten?", completion = "Ah, ich glaube, das, was Ihr da entdeckt habt, wurde früher schon einmal von der Forscherliga untersucht. Die Liga ist hier in Dunkelküste aktiv und ihre Leute haben erzählt, dass sie dabei waren, eine der gestrandeten Kreaturen zu untersuchen, bis sie von den Murlocs vertrieben wurden. Es scheint, als hättet Ihr dort Erfolg gehabt, wo dies bislang keinem von uns vergönnt war. Bitte, nehmt dieses Honorar im Namen des Tempels des Mondes an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4729] = {title = "Kiblers Exotische Tiere", objective = "Begebt Euch zur Schwarzfelsspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler.", description = "Wahrscheinlich fragt Ihr Euch, was ich hier draußen mache. Schaut Euch die Käfige an! Liegt es nicht auf der Hand?\n\nIch liebe Tiere, aber ich bin Händler von Beruf. Ich spüre exotische Tiere für die Reichen und Berühmten auf und dann zähme ich die Bestien, damit sie sich auch wie brave Tiere verhalten.\n\nJetzt fragt Ihr Euch wahrscheinlich, was Ihr für Kibler tun könnt. Die Antwort ist einfach: Nehmt den Bestienkäfig hier und beschafft mir ein paar Worgwelpen. Dafür zähme ich Euch auch einen Worg!", progress = "<Kibler streitet sich gerade mit Toucan Stan.>", completion = "Ihr habt sie gerade noch rechtzeitig erwischt, &lt;Name&gt;. Wenig später, und sie hätten nicht mehr ausgebildet werden können! Gebt mir eine Minute, dann könnt Ihr den kleinen Kerl mit nach Hause nehmen.", rewards = "Ihr bekommt:\n\nWorgtransportkorb"}
MultiLanguageQuestData['de'][4730] = {title = "Gestrandete Meereskreatur", objective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Am Strand liegt der halb aufgefressene Kadaver von etwas, das vielleicht einmal ein riesiger Meeressäuger war. Eine Bande Murlocs, stärker als diejenigen, die näher an Auberdine zu finden sind, haben ihr Lager um die verendete Kreatur herum aufgeschlagen. Es ist noch genug von der Kreatur übrig, um Gwennyth Bly'Leggonde in Auberdine eine passende Probe ihrer Knochen bringen zu können.", progress = "Hallo, <Name>! Seid Ihr hier, um mir von einer weiteren Entdeckung zu berichten?", completion = "Die Knochen, die Ihr da habt, stammen von sanftmütigen Meeressäugern, die, wie wir wissen, die Wasser rund um Teldrassil bewohnen. Es war bisher noch nicht bekannt, dass diese Kreaturen sich selbst gewaltsam auf Strand setzen, so wie wir das von den Dreschern kennen. Warum sollten sie das tun, frage ich mich? Nun ja, vielleicht bringt uns das Studium ihrer Überreste dem Wissen näher, nach dem wir streben.\n\nNochmals danke für Eure Hilfe. Bitte, nehmt dieses Honorar vom Tempel des Mondes an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4731] = {title = "Gestrandete Meeresschildkröte", objective = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Erneut findet Ihr gestrandete Meeresschildkrötenüberreste. Bei diesen Überresten ist eine Art Sänfte auf dem Panzer der Schildkröte festgeschnallt. Vielleicht wurde diese Kreatur von unbekannten Wesen an den Strand getrieben, statt sich selbst auf Strand zu setzen, wie sich aus einigen der anderen Überreste schließen ließ. Mächtige Grauflossenmurlocs haben sich beim Gerippe der Kreatur niedergelassen.\n\nIn der Sänfte findet Ihr einen Kasten mit seltsamen Zeichen darauf - vielleicht kann Gwennyth Bly'Leggonde in Auberdine sich einen Reim darauf machen.", progress = "Hallo, <Name>. Ihr habt für den Tempel des Mondes wirklich ganz hervorragende Arbeit geleistet. Dürfen wir darauf hoffen, dass Ihr Eure Bemühungen auch weiterhin auf unsere Sache konzentrieren werdet?", completion = "Ich habe schon von solchen Sänften gehört, wie Ihr sie auf dem Rücken jener Meeresschildkröte gefunden habt. Ich glaube, es handelt sich dabei um Nagasänften, die diese sowohl im Kampf verwenden als auch, um Vorräte an Land zu befördern. Die Zeichen auf dem Kasten, den Ihr gefunden habt, stammen von den Naga ... könnte die Kreatur, die Ihr entdeckt habt, getötet worden sein, als sie gerade unterwegs nach Süden war... nach Ashenvale vielleicht?\n\nIch werde es nicht versäumen, diesen Kasten zusammen mit Euren übrigen Entdeckungen nach Darnassus zu schicken. Das ist für Euch - nochmals danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4732] = {title = "Gestrandete Meeresschildkröte", objective = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Ihr findet den Kadaver einer Meeresschildkröte, die sich selbst vor einiger Zeit an das Ufer von Dunkelküste auf Strand gesetzt hat. Der Kadaver ist schon fast vollständig von Grauflossenmurlocs abgefressen worden - eben jenen Murlocs, die um die Überreste der Kreatur herum ihr Lager aufgeschlagen haben. Dennoch scheinen an den Überresten der Kreatur noch einige geeignete Proben zu haften, aus denen Gwennyth Bly'Leggonde aus Auberdine vielleicht noch etwas machen kann.", progress = "Seid mir gegrüßt, <Name>... habt Ihr noch weitere Entdeckungen, von denen Ihr dem Tempel des Mondes berichten wollt?", completion = "Ihr habt noch weitere gestrandete Kreaturen gefunden, &lt;Name&gt;? Die Meeresschildkröten tummelten sich für gewöhnlich in den Wassern am Fuße von Nordrassil, bevor er zerstört wurde. Doch seit der Entstehung von Teldrassil sind diese Wesen immer seltener gesichtet worden. Manche beenden ihr Leben hier, wie wir entdeckt haben - aus uns völlig unbekannten Gründen.\n\nMit Eurer Hilfe können wir dem Geheimnis vielleicht auf die Spur kommen. Bitte nehmt dies an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4733] = {title = "Gestrandete Meereskreatur", objective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", description = "Die Überbleibsel dessen, was anscheinend einmal ein riesiger Drescher war, wurden an den steinigen Gestaden des Zwielichtufers angeschwemmt. Der Drescher ist wesentlich größer als alle anderen Drescher, die in diesen Landesteilen gesichtet wurden. Wo immer die Kreatur auch hergekommen sein mag, es scheint nicht so, als sei sie in Dunkelküste heimisch.\n\nObwohl das Wesen schon stellenweise angefressen wurde, ist noch genug davon übrig, um eine passende Probe für Gwennyth Bly'Leggonde in Auberdine einzusammeln.", progress = "Elune sei Dank - Ich freue mich, Euch wiederzusehen, mein lieber <Name>. Der Tempel des Mondes beschäftigt sich weiterhin mit dem seltsamen Phänomen der hier in Dunkelküste gestrandeten Kreaturen. Habt Ihr vielleicht wieder etwas, das uns weiterhelfen könnte?", completion = "Die Ausmaße des Dreschers, von dem Ihr erzählt, lassen sich kaum vorstellen. Selbst die ältesten Drescher in dieser Gegend erreichen nur einen Bruchteil dieser Größe. Zwar war bekannt, dass um Teldrassil herum größere Drescher zu finden waren, doch hat ihre Zahl ständig abgenommen. Ich kann mir nicht helfen, ich frage mich, ob die Kreaturen, die sich selbst hier auf Strand setzen, irgendwie damit zu tun haben.\n\nWir werden die Knochen analysieren, die Ihr uns gebracht habt. Bitte, nehmt dies so lange im Namen des Tempels des Mondes an. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4734] = {title = "Ei-Frosten", objective = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst der Schwarzfelsspitze.", description = "Ich habe hart an einem neuen Gerät gearbeitet, <Name> - dem Eiszilloskop! Es ist so konstruiert, dass es einen Strahl kalter Energie auf das Ei eines schwarzen Großdrachen abgibt und es einfriert! Könnt Ihr das für mich ausprobieren?\n\nIch habe gehört, dass die Großdrachen weit oben auf der Schwarzfelsspitze einen Horst haben, wo sie ihre Eier ausbrüten. Da müsst Ihr hin, um das Eiszilloskop zu testen, und dann müsst Ihr mir sagen, wie es funktioniert hat!\n\nUnd seid unbesorgt. Gefrorene Dracheneier sollten harmlos sein. Bloß bei den ungefrorenen müsst Ihr Euch Sorgen machen!", progress = "<Name>! Habt Ihr das Eiszilloskop getestet?", completion = "Es hat funktioniert? Ausgezeichnet! Ich hab's gewusst!\n\nWährend Ihr weg wart, habe ich an einer neuen Version des Eiszilloskops gearbeitet. Es hat jetzt eine viel größere Reichweite.\n\nHier, Ihr könnt eines davon haben, falls Ihr noch mal zur Blackrockspitze zurückgeht.", rewards = "Ihr bekommt:\n\nEiszilloskop"}
MultiLanguageQuestData['de'][4735] = {title = "Eiersammlung", objective = "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe.", description = "<Name>, ich bin endlich bereit für echte Dracheneier! Hier, nehmt dieses kollektronische Modul. Es ist so konstruiert, dass es ein Drachenei extrahiert und für den Transport vorbereitet. Kehrt zum Horst zurück und verwendet das Modul, um Eier einzusammeln.\n\nAber vergesst nicht, sie vorher einzufrieren, sonst schlüpfen sie vielleicht aus, ehe Ihr sie einsammeln könnt!\n\nWenn Ihr genug Eier habt, dann bringt sie mir.", progress = "Habt Ihr die Eier, <Name>? Mein Kunde hat gehört, dass Ihr sie für mich sammelt, und ist sehr begierig darauf, sie in die Finger zu bekommen!", completion = "Wahnsinn, Ihr habt sie! Das kollektronische Modul hat funktioniert! Ich bin ein Genie!\n\nDanke, &lt;Name&gt;. Mein Kunde wird äußerst erfreut sein, dass er diese Eier bekommt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4736] = {title = "Auf der Suche nach Menara Leerbringer", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "Ah, hallo, <Name>. Ihr macht bei Eurer Ausbildung gute Fortschritte. So gute Fortschritte, um genau zu sein, dass ich finde, Ihr solltet für Eure harte Arbeit belohnt werden - und dafür, dass Euch die arkanen Künste noch nicht verderbt haben.\n\nFalls Ihr Interesse habt, sucht Menara Leerbringer in Ratschet auf. Momentan wohnt sie in Strahad Farsans Turm über der Stadt.\n\nSie ist nicht sehr umgänglich, <Name>, also erwartet keine Lobeshymnen von ihr. Aber wenn Ihr hart arbeitet, dann wird sie sich gut um Euch kümmern.", progress = nil, completion = "Ah, Wilddorn hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, &lt;Name&gt;, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4737] = {title = "Auf der Suche nach Menara Leerbringer", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "Hmpf. Noch immer wollt Ihr mächtiger werden. Ich sage, es ist nur eine Frage der Zeit, ehe die Verderbnis und die Sucht sich Eurer bemächtigen und Ihr ein Sklave dessen werdet, über das Ihr Macht gewinnen wollt.\n\nPah! Ihr seid ein Dummkopf! Die Zeit wird mir Recht geben - nichts anderes, nur die Zeit.\n\nDoch es scheint, dass nicht alle derselben Meinung sind wie Zevrost. Es scheint, als wäre Menara bereit, Instrumente für Euch herzustellen, mit denen Ihr mächtiger werden und Eure Kräfte besser nutzen könnt. Falls Ihr Interesse habt, dann begebt Euch nach Ratschet im Brachland. Sie befindet sich dort über der Stadt.", progress = nil, completion = "Ah, Zevrost hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, &lt;Name&gt;, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4738] = {title = "Auf der Suche nach Menara Leerbringer", objective = "Sprecht im Brachland mit Menara Leerbringer.", description = "Lasst uns eine Sache klarstellen, <Name>: Ich finde nicht, dass Ihr für eine solche Verantwortung schon bereit seid. Ich glaube nicht, dass ein Neuling bei der Erschaffung irgendeines Gegenstands der Macht helfen sollte, und schon gar nicht jemand, der noch so unerfahren ist.\n\nDoch diese Entscheidung liegt nicht bei mir. Diese Entscheidung treffen die maßgeblichen Stellen oder zumindest diejenigen, die Euch eine solche Gabe zukommen lassen wollen.\n\nFalls Ihr mehr darüber wissen wollt, dann schlage ich vor, Ihr sucht Menara Leerbringer in Ratschet auf. Für gewöhnlich hält sie sich in dem Turm über der Hafenstadt auf.", progress = nil, completion = "Ah, Demisette hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, &lt;Name&gt;, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4739] = {title = "Auf der Suche nach Menara Leerbringer", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "<Klasse>! Ja, Ihr!\n\nIhr habt noch nicht alles Handwerkszeug zusammen, aber es ist deutlich, dass Ihr bereit seid - Euch umgibt eine Aura größeren Selbstvertrauens. Ja, das erkenne ich jetzt.\n\nMenara Leerbringer kann Euch ein paar Dinge beibringen, wenn Ihr denkt, dass Ihr bereit seid. Sie unterrichtet jüngere Schüler in den arkanen Künsten. Sie macht denen, die ihre Prüfungen bestehen, sogar Geschenke.\n\nGeht nach Ratschet ins Brachland, wenn Ihr Interesse habt. Sie ist in Strahads Turm über der Stadt.", progress = nil, completion = "Ah, Kaal hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, &lt;Name&gt;, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4740] = {title = "GESUCHT: Gurgelbacke!", objective = "Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.\n\nInformiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod.", description = "Achtung!\n\nEine Belohnung wird ausgesetzt für den Tod des Murlocs \"Gurgelbacke\". Diese üble Bestie ist nachgewiesenermaßen verantwortlich für den Tod mindestens einer Schildwache und wird verdächtigt, den Untergang von mindestens zwei Frachtschiffen in den Gewässern vor Dunkelküste verursacht zu haben!\n\nZuletzt wurde Gurgelbacke an einem Barackenlager der Murlocs südlich von Auberdine gesehen. Es wird angenommen, dass er die Hütten dort verteidigt. Das Kopfgeld kann bei Schildwache Glynda Nal'Shea in Auberdine eingefordert werden.\n\nDer Dorfrat von Auberdine", progress = nil, completion = "Na, sieht ganz so aus, als wolltet Ihr etwas mehr, als Euch nur zu erkundigen! Die Bürger werden erleichtert sein zu hören, dass sie heute Nacht ein bisschen sicherer und tiefer schlafen können.\n\nHeute habt Ihr der Gerechtigkeit für das Volk von Auberdine zum Sieg verholfen, &lt;Name&gt;. Dafür möchte ich Euch dies als passende Belohnung anbieten - für einen echten Helden des Volkes von Auberdine!", rewards = "WaldhainarmschützerSalzgegerbte ArmschienenWellenbrechergurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4741] = {title = "Wilde Wächter", objective = "Trull Scheiterbann im Teufelswald möchte, dass Ihr in Winterquell 13 mondbestrahlte Eulenbestien jagt.", description = "Die Wildekin in den nördlichen Bereichen von Winterquell werden immer aggressiver. Wir müssen unsere Aktivitäten dort fortsetzen.\n\nJagt die mondbestrahlten Eulenbestien von Winterquell und untersucht das Gebiet, das sie bewohnen.\n\nDie Gegend dort ist gefährlich, aber ich weiß, dass Ihr der Aufgabe gewachsen seid. Kehrt zu mir zurück, sobald Ihr 13 der Wildekin getötet habt.", progress = nil, completion = "Ich kann spüren, dass Eure Arbeit Euch Spaß macht. Und ich glaube, wir sind hier etwas auf der Spur.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4742] = {title = "Siegel des Aufstiegs", objective = "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.\n\nVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.", description = "Wie Ihr sehen könnt, befinden sich an dem unverzierten Siegel drei leere Sockel. Jeder dieser Sockel muss mit einem Edelstein gefüllt werden, der die Befehlsgewalt der Führungsspitze darstellt. Und schließlich muss Oberanführer Wyrmthalak, der Meister der unteren Zitadelle, das Siegel in den Flammen des schwarzen Drachenschwarms schmieden.\n\nEines müsst Ihr wissen, sterbliches Wesen: Die Wahrscheinlichkeit, dass einer der drei Generäle der unteren Zitadelle zu einer bestimmten Zeit einen der Edelsteine trägt, ist äußerst gering. Ihr dürft in Eurer Wachsamkeit nicht nachlassen. Bleibt entschlossen!", progress = "Mut und vor allem Geduld Euch, sterbliches Wesen!", completion = "&lt;Vaelans Bild verschwimmt einen Moment lang.&gt;\n\n&lt;Die Teile, die Ihr gesammelt hattet, sind verschwunden.&gt;\n\nDas ungeschmiedete Siegel des Aufstiegs ist jetzt bereit. Es ist Zeit für den letzten Schritt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4743] = {title = "Siegel des Aufstiegs", objective = "Reist zum Drachensumpf in den Düstermarschen. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.\n\nIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!", description = "Nur wenige der schwarzen Drachkin außerhalb der oberen Zitadelle sind in der Lage, das Siegel mit ihrem eigenen Flammenatem zu schmieden. Wyrmthalak ist ein solcher Drachkin, doch sein Wille kann nicht gebrochen werden.\n\nIhr müsst zum Drachensumpf in den Düstermarschen reisen. Dort werdet Ihr einen alten Drachen namens Aschenschwinge finden. Seinen Willen müsst Ihr brechen, <Name>. Brecht seinen Willen und verwendet diese Kugel, sobald er geschwächt ist. Doch Ihr werdet nur wenige Sekunden haben, in denen Ihr seinen Geist kontrollieren und die Flammen anfachen könnt, mit denen das Siegel geschmiedet wird.", progress = "Vergeudet keine Zeit, sterbliches Wesen. Nefarian arbeitet fieberhaft daran, sein Übel über unsere Welt zu bringen.", completion = "Bewegt Euch nicht, während ich die letzte Herbeirufung des Schutzes wirke.\n\n&lt;Vaelans Augen werden zu zwei Flammenkugeln.&gt;\n\nDas Siegel des Aufstiegs ist vollendet...\n\nWisset eines: Ich habe das Artefakt mit mächtigem Zauberschutz magieerfüllt. In Eurer dunkelsten Stunde, wenn Ihr glaubt, dass alles verloren ist, dann wird Euch die Kraft des roten Drachenschwarms zur Verfügung stehen.", rewards = "Ihr bekommt:\n\nSiegel des Aufstiegs"}
MultiLanguageQuestData['de'][4761] = {title = "Thundris Windwirker", objective = "Sprecht mit Thundris Windwirker in Auberdine.", description = "Beim Erkunden des Furbolglagers seid Ihr auf Neuigkeiten gestoßen, über die Ihr Thundris Windwirker informieren solltet. Er fungiert umsichtig als der Älteste von Auberdine und kümmert sich weise und gerecht um die täglichen Angelegenheiten des Dorfs. Bitte setzt ihn von den Dingen, die Ihr bislang über die Furbolgangelegenheit in Erfahrung gebracht habt, in Kenntnis.\n\nIch glaube, er hat bezüglich der Gründe für deren Verderbnis seine eigene Theorie. Vielleicht könnt Ihr zusammen mit ihm einen Plan erarbeiten, mit dem das Gleichgewicht der Natur hier wiederhergestellt werden kann!", progress = nil, completion = "Grüße, &lt;Klasse&gt;. Eure Erkundung der Lage bei den Furbolgs kommt für Auberdine gerade zur rechten Zeit. Wir haben es seit einiger Zeit nicht nur mit Waldbewohnern zu tun, die auf unsere Anwesenheit jetzt ganz offen feindlich reagieren, sondern mit der offensichtlichen Verderbnis des Waldes selbst. Hoffentlich könnt Ihr Auberdine in diesen schwierigen Zeiten helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4762] = {title = "Der Klippenquell", objective = "Geht von Auberdine aus nach Norden zum ersten Wasserfall des Klippenquell und entnehmt aus dem Teich dort eine Probe.\n\nKehrt mit der Probe des Klippenquells zu Thundris Windwirker nach Auberdine zurück.", description = "Der Klippenquell wird immer verderbter. Er mündet in Nebelrand und ich fürchte, dass sich das verunreinigte Wasser bald auf Auberdine auswirken wird. Ich halte die Furbolgs der Schwarzfelle flussaufwärts für den Auslöser der Besudelung, aber ich vermute auch, dass sie nicht die wahre Ursache sind.\n\nNehmt diesen Probenbehälter und begebt Euch zur Mündung des Flusses nördlich von hier. Geht weiter landeinwärts bis zum ersten Wasserfall und entnehmt dem Teich dort eine Probe. Oberhalb davon seht Ihr eine Brücke. Kommt zu mir nach Auberdine zurück, sobald Ihr die Probe habt.", progress = "Die Verschmutzung des Cliffspring ist nur der Anfang einer alarmierenden Entwicklung hier in Dunkelküste. Die Probe, die Ihr mir gabt, wird uns dabei helfen, einen Plan zu entwickeln. Einen Angriffsplan, wie ich so langsam befürchte.", completion = "Es überrascht mich nicht, dass dieses Wasser so schmutzig ist, aber seht nur, wie faulig es geworden ist! Es sieht so aus, als sollte man lieber umgehend etwas unternehmen, nicht wahr, &lt;Name&gt;?\n\nÖstlich von Euch liegt der Teufelswald. Dort ist die eigentliche Quelle dieser Verderbnis, und zwar eine, die ich in der Vergangenheit schon einmal gesehen habe. Ich behaupte, dass diese Probe meine Vermutung bestätigen wird. Vielleicht können wir hier ein Heilmittel entwickeln, aber um es überhaupt versuchen zu können, brauchen wir Unterstützung. Wenn es so weit ist, &lt;Name&gt;, hoffe ich, dass Ihr uns Eure Hilfe nicht verweigern werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4763] = {title = "Die verderbten Schwarzfelle", objective = "Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.\n\nHolt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.\n\nMischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Klippenquell auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.\n\nNehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine.", description = "Wir haben herausgefunden, dass die Satyrn ein Grund für die Verderbnis der Furbolgs sind. Sie sollen ihre Macht durch Talismane ausüben, mit denen sie ihre Magie kanalisieren können. Damit die Furbolgs Aussicht auf Rettung haben, müssen wir den Satyrverderber aus seinem Versteck locken und ihm diesen Talisman abnehmen!\n\nFüllt diese Schale an unserem Mondbrunnen und holt aus dem Lager der Furbolgs im Norden ein paar Proben ihrer Lebensmittel. Mischt alles zusammen und stellt die Schale in die Nähe des Freudenfeuers am Fluss. Sobald die Furbolgs davon essen, werden sie lang genug gesäubert, um den Satyrverderber herauszulocken... Den Ihr dann töten müsst!", progress = "Der Talisman der Verderbnis ist ein unheilvolles Ding, dessen einziger Zweck darin besteht, das Gleichgewicht der Natur zu stören. An dem Tag, an dem Ihr dem Satyr, der die Furbolgs quält, diesen Gegenstand abnehmt und zu mir bringt, damit ich ihn vernichten kann, haben wir einen großen Sieg errungen!", completion = "Der Krieg zur Rückeroberung unseres Waldes von den Mächten der Verderbnis hat zwar gerade erst begonnen, aber heute haben wir eine Schlacht gewonnen! &lt;Name&gt;, das Volk von Auberdine steht tief in Eurer Schuld, die man Euch nur schwerlich vergelten kann. Bitte nehmt dies zusammen mit unserem Dank. Was wir heute hier gelernt haben, kann unsere Freunde, die Furbolgs, vielleicht eines Tages auf Dauer aus den Fesseln der Pein befreien.", rewards = "WildhütergamaschenSturmstoßbeinschützerMondsteinzauberstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4764] = {title = "Doomriggers Schnalle", objective = "Bringt Mayara Wolkenglanz in der Brennenden Steppe Doomriggers Schnalle.", description = "Hoch droben auf der Schwarzfelsspitze gibt es eine Kammer, die einst 'Halle des Glücks' genannt wurde. Dort bewahrten die Dunkeleisenzwerge ihre Relikte, Trophäen und Kunstobjekte auf.\n\nDoch das ist schon lange her. Man sagt, dass die Halle eingestürzt sei und jetzt für... weniger hehre Zwecke genutzt wird. Ich glaube jedoch, dass man dort immer noch so manch altes Zwergenrelikt finden kann.\n\nEines dieser Relikte ist Doomriggers Schnalle, deren Oberfläche so reich mit seltenen Edelsteinen verziert ist, dass angeblich jeder Zwerg bei ihrem Anblick in Verzückung geraten soll.\n\nDiese Schnalle ist Euer Ziel, <Name>.", progress = "Habt Ihr die Schnalle, <Name>? Mein Herr wird Euch dafür reichlich entlohnen.", completion = "Ihr habt sie gefunden! Also waren die Gerüchte wirklich wahr!\n\nIch danke Euch, &lt;Name&gt;. Mein Herr, Graf Remington Ridgewell, wird überglücklich über dieses neue Stück für seine Sammlung sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4765] = {title = "Lieferung an Kronenbrunn", objective = "Bringt Kronenbrunns Kiste zu Graf Remington Kronenbrunn nach Burg Sturmwind in Sturmwind.", description = "Ich habe Doomriggers Schnalle in eine Kiste gepackt, damit sie nach Sturmwind geschickt werden kann. <Name>, Ihr wart wirklich eine große Hilfe - darf ich Euch noch um einen letzten Gefallen bitten?\n\nBringt Graf Remington Kronenbrunn die Kiste. Ihr findet ihn in der Burg von Sturmwind. Ich bin sicher, dass er sich sehr über das freuen wird, was Ihr ihm bringt.", progress = "Man sagte mir, dass ein Bote kommen würde. Einer mit einem Geschenk von der Blackrockspitze.\n\nSeid Ihr das vielleicht?", completion = "Ah, Ihr seid das also! Seid bedankt, &lt;Name&gt;. Und falls Ihr es noch nicht wisst... die Dankbarkeit eines Adligen derer von Ridgewell übertrifft selbst die Großzügigkeit eines Königs.", rewards = "Armschützer des flinken SchlagsTreter des flinken FußesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4766] = {title = "Mayara Wolkenglanz", objective = "Sprecht mit Mayara Wolkenglanz in Morgans Wacht in der Brennenden Steppe.", description = "Eine meiner Agentinnen, Mayara Wolkenglanz, wurde in die Brennende Steppe entsandt, um die in Ruinen liegende Stadt Thaurissan zu erkunden. Diese zerstörte Stadt der Dunkeleisenzwerge könnte sehr wertvolle Objekte bergen... Objekte, die gar trefflich in unser Familienmuseum passen würden.\n\nMayara sagt, dass sie etwas gefunden hätte und nun Hilfe bräuchte, um es zu holen, allerdings befindet es sich nicht in Thaurissan. Stattdessen ist eine Exkursion zur Schwarzfelsspitze nötig.\n\nIch weiß nichts Genaues, aber sprecht doch mit Mayara in der Brennenden Steppe, falls Ihr interessiert seid.", progress = nil, completion = "Ihr kommt aus Stormwind? Wunderbar - ich weiß von einem Kunstobjekt, für das Remington alles geben würde, um es seinem Museum einzuverleiben, aber leider ist es nicht einfach zu beschaffen.\n\nUnd hier kommt Ihr ins Spiel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4767] = {title = "Windreiter", objective = "Bringt Elu am Freiwindposten 10 Eier von Steilhangwyvern.", description = "Mir wurde aufgetragen, weitere Wyvern für die Meisterwindreiter zu rekrutieren. Sie werden immer mehr und ich hoffe, selbst eines Tages ein Windreiter zu werden. Wie dem auch sei, wir können gar nicht genug Wyvern ausbilden, um der Nachfrage gerecht zu werden. Vielleicht könnt Ihr mir helfen, <Name>.\n\nIch möchte, dass Ihr zum Steilhang reist, um dort ein paar Wyverneier zu sammeln. Geht von hier aus nach Nordwesten entlang der Talwände, bis zu einer Rampe, die in das Gebiet des Steilhangs hineinführt. Seid vorsichtig, Wyvern haben einen starken Beschützerinstinkt, was ihre Eier angeht, und schätzen keine Eindringlinge.", progress = "<Name>, habt Ihr die Flügeldracheneier, um die ich gebeten habe? Ich brenne wirklich darauf, so bald wie möglich mit meiner Windreiterausbildung zu beginnen!", completion = "Perfekt! Mit diesen Eiern kann ich hoffentlich die nächste Hürde auf dem Weg zum Windreiter nehmen. Hier habt Ihr ein Zeichen meiner Anerkennung. Möge Eure Jagd immer von Erfolg gekrönt sein, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nSchweres Rüstungsset"}
MultiLanguageQuestData['de'][4768] = {title = "Die Dunkelsteinschrifttafel", objective = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Dunkelsteinschrifttafel.", description = "Die Dunkelsteinschrifttafel enthält die Niederschriften des vor langer Zeit verstorbenen Zwergs Urheld Dunkelstein. Er war ein äußerst fähiger Alchemist, den seine Zeitgenossen für verrückt hielten und der seine Forschungen daher für sich behielt.\n\nEr hielt jedoch alles auf Schrifttafeln fest und ich glaube, dass eine dieser Schrifttafeln auf der Schwarzfelsspitze zu finden ist, in einer Kammer, die einst die 'Halle des Glücks' genannt wurde. Ich weiß nicht, wie man sie heute bezeichnet, denn nur wenige reisen zum Schwarzfels und kehren heil zurück.\n\nFalls Ihr jedoch gewillt seid, Euch den Gefahren dort zu stellen, und mir diese Schrifttafel bringt, erwartet Euch eine große Belohnung.", progress = "Habt Ihr die Schrifttafel gefunden, <Name>? Ich brenne darauf, ihre Geheimnisse zu erfahren.", completion = "Ausgezeichnet. Es wird Tage dauern, bis ich die in diese Schrifttafel eingravierten Formeln erforscht habe, aber ich bin zuversichtlich, dass meine Mühen reichlich Früchte tragen werden.\n\nIch danke Euch, &lt;Name&gt;. Ihr habt uns einen unschätzbaren Dienst erwiesen.", rewards = "Armschützer des flinken SchlagsTreter des flinken FußesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4769] = {title = "Vivian Lagrave und die Dunkelsteinschrifttafel", objective = "Sprecht mit Schattenmagierin Vivian Lagrave.", description = "Vivian Lagrave aus Kargath im Ödland hat sich an mich gewandt. Aufgrund ihrer Studien ist sie davon überzeugt, dass es irgendwo auf der Schwarzfelsspitze eine alte Niederschrift gibt, die nützlich für unsere Forschung sein könnte. Um dies zu bestätigen, benötigt sie jemanden, der diesen Text von der Schwarzfelsspitze holt. Das ist keine leichte Aufgabe.\n\nFalls Ihr interessiert seid, sprecht in Kargath mit Vivian.", progress = nil, completion = "Das stimmt. Ich glaube, dass es auf der Blackrockspitze eine Schrifttafel gibt, die alte alchimistische Rezepte enthält. Ich bin froh, dass Ihr hier seid, denn ich brauche Hilfe, um an diese Schrifttafel zu gelangen.\n\nMacht es Euch bequem, dann erkläre ich es Euch näher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4770] = {title = "Auf der Heimreise", objective = "Begleitet Pao'ka Bergrausch aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Feuermähne.", description = "Bitte helft mir, <Klasse>! Ich verstecke mich jetzt schon eine ganze Weile hier am Steilhang und seit Tagen habe ich kein freundliches Gesicht mehr gesehen. Ich kam hierher, um die Wyvern zu studieren, und bin dabei wohl etwas zu dicht herangekommen. Nachdem ich von einem der Nester verjagt wurde, habe ich mich verlaufen.\n\nIch muss zum Weißgipfelposten zurückkehren! Motega weiß nicht, dass ich vermisst werde, und er wird wütend sein, wenn er hört, dass ich allein zum Steilhang gegangen bin.\n\nDer Weißgipfelposten liegt direkt östlich von hier... bringt mich bitte dorthin!", progress = nil, completion = "Was!? Wenn ich gewusst hätte, dass Pao'ka Swiftmountain in der Gegend des Steilhangs herumschnüffeln wollte, hätte ich ihn an ein Totem gekettet! Sein Vater hat ihm nur ungern gestattet, mich nach Tausend Nadeln zu begleiten. Wir kamen hierher, um die verschiedenen Kreaturen zu studieren, die dieses wunderschöne Land bewohnen.\n\nIch weiß es zu schätzen, dass Ihr Pao'ka geholfen habt. Hoffentlich wiegt dies hier alle Unannehmlichkeiten wieder auf, die Ihr dafür in Kauf genommen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4771] = {title = "Dämmerungstrickfalle", objective = "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Moppelzink zurück.", description = "Ich habe die Dämmerungstrickfalle in den Behälter gelegt, den Ihr uns gebracht habt, denjenigen, in dem sich die Dracheneier befanden. Euer Auftrag besteht darin, sie tief nach Scholomance hineinzubringen.\n\nDer untote Magier Vectus führt ein Team von Gelehrten der Geißel an... legt die Dämmerungstrickfalle in ihre Kammer, genannt der \"Vorführraum\". Sie wird dann mit den dort gefundenen Untoten reagieren und sie mit ein wenig Glück vernichten.\n\nDanach sollte es kein Problem sein, Vectus zu besiegen. Nicht wahr?", progress = nil, completion = "Ihr habt es geschafft! Vectus ist besiegt! Und die Dämmerungstrickfalle... hat sie funktioniert?\n\nHm... vielleicht war mein Gerät nicht der Erfolg, den ich mir erhofft hatte, aber ich bin froh, dass Ihr die Sache trotzdem bewerkstelligen konntet. Gut gemacht, &lt;Name&gt;!\n\nDie Argentumdämmerung und die guten Menschen von Azeroth sind in Eurer Schuld.", rewards = "WindschnitterTanzender SpanIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4781] = {title = "Komponenten für die verzauberte Goldblutrobe", objective = "Bringt Xizk Gutstich im Schlingendorntal einen Goldbarren.", description = "Eure nächste Aufgabe ist so einfach wie die erste, allerdings werdet Ihr jetzt Hilfe benötigen.\n\nIch möchte einen Umhang besticken und benötige dazu Goldfaden, allerdings ist dieses Garn recht schwer zu beschaffen, und nur wenige wissen, wie man es herstellt. Glücklicherweise kennt jemand, der unsere Sache unterstützt, dieses Geheimnis und ist gewillt, uns zu helfen.\n\nBringt Xizk Gutstich in Beutebucht einen Goldbarren. Er ist ein Schneidermeister und wird mit Freuden das Garn für Euch spinnen. Goldbarren könnt Ihr von geschickten Minenarbeitern einschmelzen lassen. Bittet einfach einen Minenarbeiter um Hilfe.", progress = "Goldbarren, ja... ja. Bringt mir einen, dann sehen wir, ob ich nicht ein bisschen Garn für Euch spinnen kann. Bis dahin schlage ich vor, dass Ihr Euch zunächst darauf konzentriert, etwas mächtiger zu werden. Die schwersten Aufgaben liegen immer noch vor Euch. Und glaubt mir... Ihr werdet Euch irgendwann wünschen, besser vorbereitet zu sein, so mächtig Ihr Euch momentan auch fühlen möget.", completion = "Perfekt, &lt;Name&gt;. Ich bin froh, dass Ihr so schnell einen Minenarbeiter gefunden habt, der Euch helfen konnte. Oder habt Ihr das etwa selbst erledigt? Auf jeden Fall habt Ihr Eure Sache gut gemacht. Das hier eignet sich perfekt, um daraus Garn zu machen.\n\nEs wird jedoch eine Weile dauern, um es zu spinnen, daher solltet Ihr später wiederkommen. Um genau zu sein: Ich muss es einer Prinzessin schicken, die wir in einem Turm eingesperrt haben und deren einzige Aufgabe es ist, Goldfäden zu spinnen ... Nein, wirklich. Das ist mein Ernst ... na gut, ich habe geflunkert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4782] = {title = "Komponenten für die verzauberte Goldblutrobe", objective = "Kehrt zu Menara Leerbringer im Brachland zurück.", description = "Kehrt zu Menara zurück und sagt Ihr, dass es eine Weile dauern wird, aber ich werde auf jeden Fall auf sie... und Euch zurückkommen. Sagt Ihr, dass Ihr zunächst noch die restlichen Komponenten zusammentragen müsst - bis dahin sollte ich das Garn fertig haben. Ihr könnt dann wieder herkommen und es mitnehmen.\n\nViel Glück, <Name>. Oh, und grüßt Strahad von mir, wenn Ihr schon mal dort seid. Der alte Zausel... hat doch wirklich kaum einen Steinwurf von Ratschet einen Turm errichtet... verrückt.", progress = nil, completion = "Gut, Ihr seid zurückgekehrt, &lt;Name&gt;. Und wo ist das Garn? Meine Fäden?\n\nAch so, ich verstehe. Da kann man nichts machen. Der Goblin und sein Bruder haben uns bisher noch nie im Stich gelassen - es ist wohl entschuldbar, dass er nicht alles stehen und liegen ließ, um sich sofort an die Arbeit zu machen. Na gut ... es gibt noch andere Dinge, um die wir uns in der Zwischenzeit kümmern können.\n\nSeid Ihr bereit für den nächsten Schritt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4783] = {title = "Komponenten für die verzauberte Goldblutrobe", objective = "Bringt Menara Leerbringer im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein.", description = "Die nächsten Komponenten findet Ihr in Desolace, weit westlich des Brachlandes und sogar des Steinkrallengebirges.\n\nNach der Zerschlagung herrscht dort noch immer das reine Chaos. Sowohl Eure Kraft als auch Eure Schlauheit werden dort auf die Probe gestellt werden - Ihr werdet Euch Kreaturen voller Hass und sogar der Brennenden Legion stellen müssen.\n\nBringt mir etwas Blut von den Satyrn der Zornsäer im Nordosten. Und dann bringt mir noch einen geringen Höllenstein von den geringen Höllenbestien beim Zirkel der Mannoroc.\n\nWir brauchen beides, um daraus eine Robe für Euch zu fertigen.", progress = "Desolace ist nicht gerade ein freundlicher Ort: Naga, Riesen, Satyrn, die Brennende Legion... all das und sich gegenseitig bekämpfende Zentaurenklans machen das Land äußerst gefährlich, wenn Ihr Euch nicht vorseht.\n\nWie ich schon sagte, wird das alles nicht nur Eure Kraft und Schlauheit auf die Probe stellen, sondern auch Eure Geduld. Seid immer auf der Hut in dieser Gegend, <Name>.", completion = "Ausgezeichnet, &lt;Name&gt;. Das ist perfekt. Ich werde jetzt alles vorbereiten, während Ihr Euch auf die Suche nach den beiden letzten Komponenten macht. Seid Ihr bereit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4784] = {title = "Komponenten für die verzauberte Goldblutrobe", objective = "Bringt Menara Leerbringer im Brachland feinen Goldfaden, 2 glimmende Kohlen und einen Seelensplitter.", description = "Ich brauche jetzt nur noch drei Dinge, <Name>, dann kann ich Eure Robe fertig stellen.\n\nZuerst brauche ich das feine Goldgarn, das Xizk für Euch gesponnen hat. Kehrt zu ihm nach Beutebucht zurück und holt es.\n\nAls Zweites brauche ich ein paar glimmende Kohlen von den Feuerelementaren im Arathihochland. Wenn ich mich recht erinnere, leben sie im Westen in der Nähe des Thoradinswalls.\n\nAls Letztes benötige ich dann noch einen von Euch geschaffenen Seelensplitter.\n\nKommt hierher zum Turm zurück, sobald Ihr alle Komponenten habt, dann stelle ich Eure Robe fertig.", progress = "Bald ist es so weit, <Name>. Das verspreche ich Euch. Die Robe wird Euren Ansprüchen mehr als gerecht werden und Euch sicherlich gegenüber Euren Feinden einen großen Vorteil verschaffen.", completion = "Exzellent, &lt;Name&gt;! Alle Komponenten sind da und wir sind bereit.\n\nIhr werdet höchst zufrieden sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4785] = {title = "Feiner Goldfaden", objective = "Bitte sehr, <Name>. Und bitte richtet doch Menara Grüße von uns aus.\n\nWir erwarten große Dinge von Euch. Wenn die Legion in die Knie gezwungen ist, wird man bestimmt Euren Namen rufen und Eure Kraft preisen. Ich kann es kaum erwarten!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeiner Goldfaden"}
MultiLanguageQuestData['de'][4786] = {title = "Die fertiggestellte Robe", objective = "Wartet, bis Menara Leerbringer Eure Robe fertiggestellt hat, und sprecht dann noch einmal mit ihr.", description = "Jetzt schneidere ich die Robe für Euch. Es dauert nur einen Augenblick. Geht nicht zu weit fort, ja?", progress = nil, completion = "Es ist vollbracht, &lt;Name&gt;. Hier, bitte sehr. Tragt sie mit Stolz.\n\nIhr habt hart dafür gearbeitet und ich sehe große Taten in Eurer Zukunft. Denkt daran: Um sich der Verderbnis zu erwehren, die unseren Weg begleitet, bedarf es eines starken Willens und großer, innerer Stärke. Solange Ihr Herr Eures Willens seid, wird Euch großer Erfolg beschieden sein.", rewards = "Ihr bekommt:\n\nVerzauberte Goldblutrobe"}
MultiLanguageQuestData['de'][4787] = {title = "Das uralte Ei", objective = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", description = "Mosh'arus Prophezeiung spricht von einem uralten Ei. Es ist ein Relikt aus einer Zeit, als die Trolle noch über riesige Reiche herrschten, und es hat die Kraft, die Essenz von Hakkar zu binden. Möglicherweise ist es das einzige Mittel, um unsere Welt vor diesem Bösen zu schützen.\n\nBringt mir das uralte Ei, <Name>. Man sagt, dass es tief verborgen in Jintha'Alor im Hinterland liegt, in einer Höhle hinter dem Amphitheater am obersten Punkt der Stadt.", progress = "Habt Ihr das uralte Ei? Ich spüre, wie sich große Mächte regen, und ich fürchte, dass die Zeit knapp wird.", completion = "Ah, Ihr habt das Ei! Ich verneige mich vor Euch, &lt;Name&gt;. An Eure Kraft und Euren Mut wird man sich noch lang erinnern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4788] = {title = "Die letzten Schrifttafeln", objective = "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", description = "Während ich die dritte und vierte Schrifttafel von Mosh'aru überprüfe, müsst ihr die fünfte und sechste finden! Es wird nicht einfach sein, da sie in den Händen der Trolle des Gluthauerstamms auf der Schwarzfelsspitze sind. Die Spitze ist ein dunkler Berg aus Feuer zwischen der Brennenden Steppe und der Sengenden Schlucht.\n\nViel Glück, <Name>. Die Schwarzfelsspitze ist kein Ort für anständige Leute...", progress = "Wart Ihr bei der Spitze, <Name>? Habt Ihr die fünfte und sechste Schrifttafel?", completion = "Unglaublich! Ihr habt sie gefunden! Ihr seid ein wahrer Held, &lt;Name&gt;!\n\nDas ist eine gute Sache, denn ich habe die Schrifttafeln gelesen, die Ihr mir zuvor gebracht habt, und nach dem, was ich herausgefunden habe... tja, da werden wir wohl einen Helden brauchen, der aufhält, was kommt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4801] = {title = "E'ko der Frostsäbler", objective = "In Winterspring da werdeta gegen große Katzens kämpfen müssen, das sin' de Frostsäblers. Diese Biesties sin' unglaublich schnell un' gerissen. Wenn Ihr auch so schnell wie 'n Frostsäbler sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring da werdeta gegen große Katzens kämpfen müssen, das sin' de Frostsäblers. Diese Biesties sin' unglaublich schnell un' gerissen. Wenn Ihr auch so schnell wie 'n Frostsäbler sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujuhagel"}
MultiLanguageQuestData['de'][4802] = {title = "E'ko der Winterfelle", objective = "In Winterspring da werdeta gegen fehlgeleitete Kreaturens kämpfen, das sin' de Winterfellfurbolgse. Weil ihr Anführer das so wollt', ham die unglaubliche Kraft gekriegt. Wenn Ihr auch so stark wie 'n Winterfell sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring da werdeta gegen fehlgeleitete Kreaturens kämpfen, das sin' de Winterfellfurbolgse. Weil ihr Anführer das so wollt', ham die unglaubliche Kraft gekriegt. Wenn Ihr auch so stark wie 'n Winterfell sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujukraft"}
MultiLanguageQuestData['de'][4803] = {title = "E'ko eines Splitterzahns", objective = "In Winterspring, da sin' große Bärens mit extrem dicken Bälgens. Diese Splitterzahnbären kriegen davon so viel Schutz, dasse unheimlich viel Zeugs widerstehen könn'. Wenn Ihr gegen Feuer auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'nem Splitterzahn kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring, da sin' große Bärens mit extrem dicken Bälgens. Diese Splitterzahnbären kriegen davon so viel Schutz, dasse unheimlich viel Zeugs widerstehen könn'. Wenn Ihr gegen Feuer auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'nem Splitterzahn kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujuglut"}
MultiLanguageQuestData['de'][4804] = {title = "E'ko der Eiswindschimären", objective = "In Winterspring, da müssta gegen große fliegende Kreaturens kämpfen, das sin' de Eiswindschimären. Diese Biesties könn' Frostmagie wirken. Wenn Ihr gegen Frost auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'ner Eiswindschimäre kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring, da müssta gegen große fliegende Kreaturens kämpfen, das sin' de Eiswindschimären. Diese Biesties könn' Frostmagie wirken. Wenn Ihr gegen Frost auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'ner Eiswindschimäre kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujukälte"}
MultiLanguageQuestData['de'][4805] = {title = "E'ko der Eisdistelyetis", objective = "In Winterspring, da müssta gegen große Kreaturens kämpfen, das sin' de Eisdistelyetis. Diese Viecher bewegen sich nur langsam, aber se könn' Dank dem dicken Fell 'ne Menge Prügel einstecken. Wenn Ihr auch so gut wie die Angriffen ausweich'n wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring, da müssta gegen große Kreaturens kämpfen, das sin' de Eisdistelyetis. Diese Viecher bewegen sich nur langsam, aber se könn' Dank dem dicken Fell 'ne Menge Prügel einstecken. Wenn Ihr auch so gut wie die Angriffen ausweich'n wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujuflucht"}
MultiLanguageQuestData['de'][4806] = {title = "E'ko der Frosthagelriesen", objective = "In Winterspring habta gegen de großen Eisriesens gekämpft, de Frosthagel. Die verlassen sich auf rohe Gewalt und Kraft. Wenn Ihr auch so stark wie 'n Frosthagelriese sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring habta gegen de großen Eisriesens gekämpft, de Frosthagel. Die verlassen sich auf rohe Gewalt und Kraft. Wenn Ihr auch so stark wie 'n Frosthagelriese sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujumacht"}
MultiLanguageQuestData['de'][4807] = {title = "E'ko der Wildekin", objective = "In Winterspring, da müssta gegen Kreaturens kämpfen, die ham anscheinend angeborene magische Fertigkeitens. Diese Wildekinses könn' echt starke Magie anwenden. Wenn Ihr Euren Intellekt erweitern wollt, dann bringt mir das E'ko von allen denen Eulenbiesters, die Ihr dort findet.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", description = nil, progress = "In Winterspring, da müssta gegen Kreaturens kämpfen, die ham anscheinend angeborene magische Fertigkeitens. Diese Wildekinses könn' echt starke Magie anwenden. Wenn Ihr Euren Intellekt erweitern wollt, dann bringt mir das E'ko von allen denen Eulenbiesters, die Ihr dort findet.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für &lt;Name&gt; 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken.", rewards = "Ihr bekommt:\n\nJujuarglist"}
MultiLanguageQuestData['de'][4808] = {title = "Felnok Stahlfeder", objective = "Gebt Felnok Stahlfeder in der Ewigen Warte in Winterquell Tinkees Brief.", description = "Ich habe noch eine weitere kleine Bitte an Euch.\n\nMeine anfänglichen Studien bezüglich der Essenz, die Ihr gesammelt habt, haben ergeben, dass es wohl möglich ist, die Eier der Großdrachenwelpen einzufrieren und so zu konservieren! Ich möchte diese Theorie überprüfen, aber zuerst benötige ich speziell angefertigte Komponenten der Ingenieurskunst. Mein Kollege Felnok Stahlfeder kann sie herstellen.\n\nHier, bringt Felnok diesen Brief. Darin steht, was ich benötige. Ihr findet Felnok in Winterquell in der Ewigen Warte.", progress = "Ganz schön kalt hier oben! Hoffentlich habt Ihr mir eine Decke mitgebracht!", completion = "Das ist doch keine Decke! Aber was haben wir denn hier? Einen Brief von Tinkee? Ich frage mich, was so wichtig ist, dass sie mir schreibt...\n\nAh, sie befasst sich in der brennenden Steppe mit ihren Studien. Eine gute Idee - das ist ein guter Fundort für Drachkin. Oh, aber seht doch nur! Hier steht, dass sie ein paar Teile für ein Gerät benötigt, das sie bauen möchte. Tja, da bin dann wohl ich gefragt, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4809] = {title = "Hörner der Eiswindschimären", objective = "Beschafft Euch 8 unbeschädigte Hörner.", description = "Ich habe fast alles, was Tinkee benötigt, aber mir fehlt eine wichtige Komponente, und das sind Eiswindschimärenhörner. Die Hörner der Eiswindschimären von Winterquell sind eine konzentrierte Kältequelle, aber man kann nur makellose, unbeschädigte Hörner verwenden! Ich brauche ein paar davon, um Tinkees Auftrag zu erfüllen.\n\nBringt mir unbeschädigte Hörner der Eiswindschimären, dann schnüre ich ein Päckchen für Tinkee zusammen.", progress = "Habt Ihr die Hörner der Eiswindschimären, <Name>?", completion = "Das sind wirklich Prachtexemplare. Sie sind eiskalt! Ich ziehe mir schnell ein Paar Handschuhe an und dann packe ich sie zu den anderen Dingen, die Tinkee braucht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4810] = {title = "Rückkehr zu Tinkee", objective = "Bringt Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe Felnoks Päckchen.", description = "Gut, alles ist bereit und verpackt und transportfertig! Viel Glück auf Eurer Reise und richtet Tinkee aus, dass sie mir was schuldet!", progress = "<Name>! Habt Ihr mit Felnok gesprochen? Habt Ihr die Komponenten, die ich benötige?", completion = "Ihr habt sie! Großartig! Ich mache mich sogleich ans Werk! Tausendmal Dank, &lt;Name&gt;!\n\nIhr wart mir eine so große Hilfe, dass ich Euch bestimmt einmal wieder für noch wichtigere Aufgaben brauchen könnte...", rewards = "BlitzspaltbeilGrabszepterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4811] = {title = "Der rote Kristall", objective = "Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", description = "Im Osten streifen immer mehr feindliche Mondkin umher. Man dachte einst, dass sie sanftmütige, fast mystische Kreaturen wären. Wenn auch viele ihnen weiterhin Ehrfurcht entgegenbringen, zwingt mich die Sicherheit Auberdines, die Sache realistischer zu sehen.\n\nIch habe Berichte erhalten, dass es die Mondkin zu einem großen roten Kristall an der östlichen Bergkette von Dunkelküste zieht. Niemand weiß, was dieser Kristall ist oder ob er wirklich existiert. Ich möchte, dass Ihr ihn dort sucht und mir meldet, was Ihr vorgefunden habt.", progress = nil, completion = "Der Kristall existiert also, &lt;Name&gt;? Faszinierend... Ihr habt Eure Aufgabe gut ausgeführt; das war gute Arbeit!\n\nWas genau ist dieser Kristall? Das ist nur eine einzelne Frage in einem Meer von Fragen. Eine weitere Frage, die sich stellt, ist, warum die Moonkin von diesem Objekt angezogen werden... Ist der Kristall von Natur aus gut oder birgt er einen düsteren Zweck?\n\nIch habe viele weitere Fragen, aber wir werden diesen Kristall näher untersuchen müssen, um einige Antworten zu erhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4812] = {title = "Wenn das Wasser fließt", objective = "Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.", description = "Benutzt diese leere Phiole und füllt hier in Auberdine Mondbrunnenwasser hinein. Solch mächtige Magie sollte einen Hinweis auf die Zusammensetzung des Kristalls liefern. Zu diesem Zweck gießt Ihr etwas Flüssigkeit über den Kristall; alles Weitere sollte sich dann von selbst ergeben.\n\nWenn ich auch nicht erwarte, dass Euch etwas Böses zustoßen könnte, möchte ich dennoch, dass Ihr vorsichtig seid. Über uns im Osten liegt der Teufelswald; falls dieser Kristall mit jenem Ort verbunden ist, wie ich es vermute, könnte sich das als sehr gefährlich erweisen.", progress = "Gegen die Baumkulisse von Dunkelküste wirkt der Kristall sehr fremdartig. Ihr meint, ein sehr leises Summen aus seinem tiefsten Inneren zu vernehmen.", completion = "Ihr habt den mysteriösen Kristall erneut erreicht. Sogleich entfernt Ihr den Verschluss der Röhre mit Mondbrunnenwasser und gießt den Inhalt vorsichtig über dem Kristall aus. Als das Wasser über das Kristallgitter läuft, seht Ihr, wie seine undurchsichtige Oberfläche durchsichtig wird...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4813] = {title = "Die Fragmente im Inneren", objective = "Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", description = "Das Mondbrunnenwasser hat enthüllt, dass im Inneren des Kristalls einige kleine Knochenfragmente sowie ein Teil eines Kieferknochens eingebettet sind. Der Kieferknochen scheint menschlich zu sein, aber um Klarheit darüber zu gewinnen, müsste man den Kristall aufbrechen - eine Leistung, die sogar für die stärkste Magie schier unmöglich erscheint.\n\nDa Ihr die gestellte Aufgabe erfüllt habt, bleibt nur noch, Schildwache Glynda Nal'Shea in Auberdine Bericht zu erstatten.", progress = nil, completion = "Tja, es scheint, dass wir jetzt zwar mehr über den Kristall wissen, dafür aber vor noch mehr unbeantworteten Fragen stehen!\n\nIch werde die Informationen, die Ihr enthüllt habt, zum Rat hier in Auberdine bringen. Vielleicht weiß er, was bezüglich dieses Kristalls zu tun ist. Das heißt, vorausgesetzt, dass es etwas zu tun gibt; vorerst befindet sich die Bedrohung weit genug im Osten, sodass sie für uns keine Gefahr bedeutet.\n\nUnd was Euch angeht, bitte nehmt dies. Seht es als eine Belohnung für gut geleistete Arbeit an, &lt;Name&gt;.", rewards = "ZackenstahlkurzschwertKrummholzdolchEichendrosselstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4821] = {title = "Fremdartiges Ei", objective = "Bringt Hagar Blitzhuf am Freiwindposten das fremdartige Ei.", description = "Es wurde ein Gerücht über ein fremdartiges Ei hier in Tausend Nadeln in Umlauf gebracht. Diejenigen, die dieses Ei gesehen haben, konnten aber nicht nahe genug herankommen, um es ausführlich zu untersuchen. Schlangen bewachen das Ei, als wäre es eines ihrer eigenen.\n\nIch möchte, dass Ihr dieses fremdartige Ei sucht und es mir bringt, damit ich es untersuchen kann. Berichten zufolge soll sich das Ei in einem Schlangenbau befinden, aber es gibt mehrere Schlangenbaue entlang des Fußes der Klippenwand südlich und nordöstlich des Freiwindpostens.", progress = "Ich muss mehr über dieses mysteriöse Ei herausfinden. Wer weiß, was einmal daraus schlüpfen wird.", completion = "Ja, endlich... das mysteriöse Ei wurde mir endlich gebracht. Dann lasst mich mal einen Blick darauf werfen... Was...! Was ist das...?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4822] = {title = "Lecker Eis", objective = "Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Tigules Eiscreme' zu bevorzugen.", description = "EISCREME! Oh, kannst du mir bitte, bitte, bitte, etwas Eiscreme besorgen? Am liebsten mag ich Erdbeere und es gibt einfach kein besseres Erdbeereis als das von Tigule. Das ist mein liebstes Eis auf der ganzen Welt!\n\nFrüher gab es das immer auf der Rennstrecke in der schimmernden Ebene, aber ich habe mal gehört, dass man es jetzt auch in der Stadt kaufen kann. Kriege ich bitte eins? Bitte? Am liebsten Tigules Eiscreme.", progress = "Ich wünschte sie würden mehr als nur Erdbeereis herstellen, aber Gott sei Dank ist Erdbeere meine Lieblingssorte.", completion = "Mmmmmmmmm! Ich liebe Erdbeereis! Wenn Skippi und Gunni eines können, dann ist das Erdbeereis machen!\n\nVielen Dank, &lt;Name&gt; - Das ist die beste Süßigkeit seit langem!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4841] = {title = "Befriedung der Zentauren", objective = "Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Langhorn am Freiwindposten zurück.", description = "<Name>, ich flehe Euch an, diese Zentauren zur Strecke zu bringen. Sie sollen den Zorn unserer Rache spüren. Greift das Zentaurenlager im Norden des Freiwindpostens an! Lasst den Zorn Eure Hand führen!", progress = "Kommt schon, <Name>, ich weiß, dass Ihr Euren Anteil noch nicht erlegt habt. Bringt sie zur Strecke, dann bekommt Ihr eine Belohnung als Zeichen meiner Dankbarkeit.", completion = "Das ist für Euch, &lt;Name&gt;, als Zeichen meiner Dankbarkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4842] = {title = "Sonderbare Quellen", objective = "Befolgt Donova Schneewehs Anweisungen und meldet Euch dann wieder bei ihr.", description = "Also mal ehrlich, es gibt hier in Winterquell zwar keine Vulkane, aber ich glaube, dass es ein paar viel gefährlichere Ursachen für diese heißen Quellen gibt...\n\nTja, Ihr möchtet Euch das bestimmt lieber mit eigenen Augen ansehen. Ihr müsst dazu ganz Winterquell durchqueren und ganz nach Süden reisen. Wenn die Luft irgendwie stickig und schwül wird und sich der Himmel verdunkelt, habt Ihr gefunden, was ich für die Ursache der heißen Quellen halte.\n\nSeht es Euch an. Ich bin sicher, dass Ihr mit einer Menge Fragen zurückkehren werdet.", progress = "Das Wasser der Quellen scheint ein paar höchst eigenartige Eigenschaften zu haben... Ich bin mir immer noch nicht sicher, was das zu bedeuten hat...", completion = "Ja, die Dämonen dort in der flüsternden Schlucht... ich glaube, dass es ihre Anwesenheit ist, die das Land auf diese Weise beeinflusst. Ich werde weiter die hiesigen heißen Quellen beobachten und zusehen, ob ich etwas mehr herausfinden kann.\n\nAn Eurer Stelle würde ich allerdings warten, bis ich ein bisschen stärker wäre, bevor ich mich weiter in die flüsternden Schlucht hineinwagen würde.", rewards = "Ihr bekommt:\n\nTiefenflussumhang"}
MultiLanguageQuestData['de'][4861] = {title = "Wütende Wildekin", objective = "Findet Jaron Steinschleifers ruiniertes Lager samt dessen Vorräten im südlichen Winterquell.", description = "Hallo, <Bursche/Mädchen>! Ein paar blutrünstige Wildekin haben mich aus meinem Lager im südlichen Winterquell vertrieben! Nun, ich schätze, ich bin irgendetwas zu nahe gekommen, das die Wildekin bewachen.\n\nIch hab es gerade noch geschafft, mit heiler Haut davonzukommen, aber ich fürchte, einer meiner Freunde hatte nicht so viel Glück. Würde es Euch wohl etwas ausmachen, Euch der Gefahr durch die Wildekin zu stellen und zum Lager zu gehen? Ich brauche unbedingt meine Vorräte und hätte auch gern das Amulett zurück, das ich gestern an der Ausgrabungsstätte zu Tage gefördert habe.", progress = nil, completion = "Inmitten der zerstörten Habseligkeiten im Lager steht eine schwer beschädigte Kiste...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4862] = {title = "Be-Öh-Es-Eh", objective = "Reist zur Schwarzfelsspitze und sammelt 15 Spitzenspinneneier für Kibler.\n\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.", description = "Ob Ihr es glaubt oder nicht, da draußen gibt es Leute, die gutes Geld selbst für die übelsten der abgerichteten Bestien ausgeben würden!\n\nIch würde ja Bijou zur Spitze schicken, um ein paar dieser Spitzenspinneneier zu sammeln, aber ich habe seit Wochen nichts mehr von ihr gehört. Vielleicht könnt Ihr mir helfen?\n\nIch sag Euch was, <Name>. Geht zur Schwarzfelsspitze und sammelt ein paar Spitzenspinneneier für mich. Bringt sie mir, dann werde ich Euch nicht nur etwas Bargeld geben, sondern auch eines der Viecher für Euch abrichten!", progress = "Sind das da Spinnen-Eier in Eurem Säckel oder freut Ihr Euch einfach nur, mich zu sehen?", completion = "Was für ein Haufen! Ich meine, seht Euch nur all diese Eier an! Die sollten eine ordentliche Menge Gold einbringen.\n\nWie versprochen, hier habt Ihr Euer eigenes kleines Tierchen. Lasst Euch nur nicht beißen!", rewards = "Ihr bekommt:\n\nGlimmernetztransportkorb"}
MultiLanguageQuestData['de'][4863] = {title = "Wütende Wildekin", objective = "Sucht Jaron Steinschleifers zerstörten Wagen.", description = "Ihr seht Euch um und könnt nichts entdecken, was Jaron wohl noch brauchen könnte. Ihr stellt jedoch fest, dass die Kiste, die Ihr fandet, aufgebrochen wurde, als ob es die Wildekin darauf abgesehen hatten...\n\nAls Ihr nach Osten blickt, erkennt Ihr den vagen Umriss eines zurückgelassenen Wagens. Vielleicht findet Ihr Jarons Sachen ja dort. Nachsehen kann nicht schaden.", progress = nil, completion = "Ihr nähert Euch dem Wagen. Es scheint dort nichts weiter für Jaron zu geben. Als Ihr jedoch zu Boden blickt, fallen Euch ein paar Kisten auf, die unbeschädigt aussehen, aber halb im Schnee verborgen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4864] = {title = "Wütende Wildekin", objective = "Klaubt Jarons Ladung aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.\n\nBringt Jaron Steinschleifer in der Lodge in Winterquell dessen Ladung und das blaugefiederte Amulett.", description = "Nachdem Ihr den Inhalt des Kastens inspiziert habt, befindet Ihr, dass Jaron die Werkzeuge und anderen Gegenstände darin sicher gebrauchen könnte. Von dem Amulett fehlt jedoch jede Spur.\n\nDie Wildekin scheinen die Landstriche nördlich und östlich von hier zu bewohnen, also beschließt Ihr, dass Euer nächster Schritt sein wird, die Kreaturen aufzustöbern und das Amulett von ihnen einzufordern.", progress = "Aye... Was gibt's Neues?", completion = "Tja, das hatte ich befürchtet zu hören. Hab ich mir doch gedacht, dass diese wahnsinnigen Bestien meine ganzen Habseligkeiten zerstört haben...\n\nAber Ihr habt meine Werkzeuge gefunden und, was noch wichtiger ist, das Amulett! Ich frage mich, warum die Wildekin diesen Gegenstand so heftigst verteidigt haben... Wie auch immer, ich werde es mir zweimal überlegen, ihnen noch einmal in die Quere zu geraten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4865] = {title = "Wilde Schlange", objective = "Berichtet Motega Feuermähne von Euren Entdeckungen. Zu finden ist er im Weißgipfelposten in Tausend Nadeln.", description = "Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich es nie für möglich gehalten haben. Die Rache kam nach Tausend Nadeln!\n\n<Hagar wischt sich den Schweiß von der Stirn.>\n\n<Name>, Ihr müsst Euch beeilen! Geht sofort los und sucht Motega Feuermähne auf. Ihr findet ihn im Weißgipfelposten nordwestlich des Freiwindpostens, entlang der Straße. Er wird wissen, was zu tun ist!", progress = nil, completion = "Rache! Also ist die Legende von Arikara doch wahr. Das ist in der Tat ein Problem, um das wir uns unverzüglich kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4866] = {title = "Muttermilch", objective = "Ihr findet Mutter Glimmernetz im Herzen der Schwarzfelsspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", description = "Das dürfte eines der stärksten Gifte der Welt sein, <Volk>!\n\nIch habe bei meinen Ausflügen zur Spitze immer wieder gehört, wie die Schwarzfelsorcs davon sprachen, wie tödlich es sei. Sie nennen es 'Muttermilch', benannt nach Mutter Glimmernetz, der großen, grausamen Spinne in der Listspinnerhöhle.\n\nAlso, das müsst Ihr mir besorgen: eine frische Probe dieser Milch, die durch EURE Adern fließt. Mir einfach nur die Giftdrüse zu bringen, wäre nicht genug! Bringt sie dazu, Euch zu vergiften, und kommt dann zu mir zurück!\n\nDann... kann ich Euch melken!\n\n<Reibt sich voller Vorfreude die Hände.>", progress = "<Der struppige John kneift Euch.>", completion = "Das wird das beste Bier aller Zeiten.\n\nHe, was habt Ihr denn gedacht, wofür ich das benutze? Als Gift oder so was???\n\nVerrückte Kinder...", rewards = "Ihr bekommt:\n\nDer immervolle Becher des struppigen John"}
MultiLanguageQuestData['de'][4867] = {title = "Urok Schreckensbote", objective = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", description = "Argh! Das Sprechen fällt schwer!\n\nNehmt diese Notiz! Holt mir mein Mojo.", progress = "Ah! Habt Ihr mein Mojo?", completion = "Aha! Ich kann bereits fühlen, wie meine Macht zu mir zurückkehrt. Und meine Gedanken werden nicht mehr von Uroks Fluch gestört.\n\nDanke, &lt;Name&gt;! Bescheidenheit ist unter meiner Würde, aber ich muss Eure Hilfe anerkennen.\n\nUnd ich wünsche Euch Glück auf Euren Reisen durch Blackrockspitze. Ihr seid ein Narr zu denken, Ihr könntet es bis an die Spitze schaffen, aber Euer Mut steht außer Frage.", rewards = "Ihr bekommt:\n\nPrismatalisman"}
MultiLanguageQuestData['de'][4881] = {title = "Auftragsmordplan", objective = "Warnt Kanati Grauwolke am Weißgipfelposten, dass man vorhat, ihn zu töten.", description = "Der Tauren Kanati Grauwolke war so dreist, in Tausend Nadeln ein Jägerlager aufzuschlagen. Wir müssen ihn töten, damit dieses Jägerlager und alle, die ihm möglicherweise folgen, verschwinden. Wir werden uns dem kleinen Posten südwestlich des Großen Aufzugs nähern.", progress = nil, completion = "Die wollen mich töten? Ich werde ihnen zeigen, wie ein Tauren kämpft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4882] = {title = "Geheimnisse bewahren", objective = "Bringt Trull Scheiterbann beim Blutgiftposten das blaugefiederte Amulett.", description = "Ihr seid Euch unsicher bezüglich der Bedeutung der Halskette, die vom Hals des gerade erschlagenen Wildekin stammt. Sie glüht hell, verblasst und wird wieder hell.\n\nTrull Scheiterbann kann Euch vielleicht mehr darüber sagen, da er über sehr großes Wissen über die Wildekin verfügt. Vielleicht solltet Ihr ihn darüber befragen.", progress = "Meldet Ihr Euch für einen weiteren Auftrag?", completion = "Eine bedeutende Entdeckung?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4883] = {title = "Geheimnisse bewahren", objective = "Bringt Nara Wildmähne das blaugefiederte Amulett.", description = "Auch wenn ich viel über die Eulenbestien weiß, die Ihr in Winterquell erledigt habt, bin ich in der Magie, die sie wirken, nicht wirklich bewandert. Aber ich glaube, dass ich jemanden kenne, der die Kette untersuchen und Euch sagen könnte, was es ist.\n\nNara Wildmähne in Donnerfels ist eine Expertin auf diesem Gebiet; trefft Euch mit ihr. Viel Glück, <Name>.", progress = "Wie kann ich Euch helfen, <Name>?", completion = "Die Energie dieser Halskette, &lt;Name&gt;. Ich glaube, dass sie nur eine Quelle hat.\n\n\n\nDie Wildekin, nun fehlgeleitet und verwirrt, waren einst nicht so. Sie hatten einst einen Zweck und wurden geleitet, um zu dienen. Die Nachtelfengöttin Elune hat diese Kreaturen geschaffen, um ihre hochheiligsten Gebiete zu bewachen.\n\nDiese Tatsache mag nicht sehr wertvoll erscheinen, aber ich dränge Euch, weiter zu forschen.\n\nIhr werdet es irgendwann erfahren. Danke, dass Ihr mir dies gebracht habt, &lt;Name&gt;.", rewards = "GischtarmschienenLeuchtende ArmplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4901] = {title = "Wächter des Altars", objective = "Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Himmelsbern in Rut'theran von Eurem Fund.", description = "Ganz oben auf dem Grat liegt das, was ich für einen Altar der Göttin Elune halte. Soweit ich das sagen kann, müssen wir in jeder Höhle fünf Fackeln anzünden. Dann können wir den eigentlichen Altar erreichen.\n\nIch habe einige der Zauberformeln übersetzt, die in den Stein der alten Ruinen von Kel'Theril geritzt sind. Meiner Meinung nach sind sie der Schlüssel, mit dem man den Altar freigeben kann. Ich brauche Eure Hilfe dabei, alle Fackeln anzuzünden, während ich den Zauber rezitiere.\n\nWenn wir Erfolg haben, könnt Ihr Erelas unseren Fund melden!", progress = nil, completion = "Habt Ihr Ranshalla getroffen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4902] = {title = "Wildekin von Elune", objective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", description = "Das ist faszinierend!\n\nIch habe mich immer gefragt, was die Wahrheit ist... Nun, Ihr müsst dieses Wissen auf alle Fälle teilen! Geht sofort zum Erzdruiden Fandral Hirschhaupt. Ihr werdet ihn in Darnassus im Zirkel des Cenarius antreffen. Erklärt ihm, was passiert ist, genau so wie Ihr es mir erzählt habt. Ich bin sicher, es wird ihn ebenso interessieren!\n\nDas sind wichtige Informationen, <Name>!", progress = nil, completion = "Nur heraus damit, sagt mir, warum Ihr hier seid.\n\nOh, ja? Hmm. Nun ja.\n\nDanke, dass Ihr damit direkt zu mir gekommen seid. Es ist immer am besten, sich direkt an die Spitze zu wenden... Aber... Ja. Die Druiden des Zirkels des Cenarius wissen schon eine ganze Weile von den Wildekin. Dass sie Tiere von Elune und dazu auserwählt sind, die hochheiligsten Orte zu bewachen.\n\nWenn das also auch keine wirklichen Neuigkeiten waren, so muss ich Euch doch für Eure Anstrengungen loben. Hier, nehmt dies... es ist etwas, das mir für eine solche Tat angemessen erscheint.", rewards = "DornenwerferAuf Euch wartet eine dieser Belohnungen:\n\nOpalmedaillon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4903] = {title = "Befehl des Kriegsherrn", objective = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Schwarzfelsdokumente. Kehrt zum Kriegsherrn Bluthauer nach Kargath zurück, sobald Ihr diese Mission erledigt habt.", description = "Auf Befehl von Kriegsherr Bluthauer müssen die nachfolgenden Bewohner der Schwarzfelsspitze eliminiert werden:\n\nDie aufgeblasene Bedrohung, Hochlord Omokk.\n\nDer grausame und erbarmungslose Troll Kriegsmeister Voone.\n\nOberanführer Wyrmthalak, Zuchtmeister der geringen Stadt.\n\nDes Weiteren müsst Ihr alle wichtigen Dokumente zurückbringen, die Ihr möglicherweise findet.\n\nSeid erfolgreich und macht Euch Ehre.\n\nVersagt und seid vergessen.", progress = "<Kriegsherr Goretooth salutiert vor Euch.>", completion = "&lt;Kriegsherr Goretooths mattgrüne Haut wird für einen Augenblick kreideweiß.&gt;", rewards = "Wyrmthalaks FesselnOmokks UmfangbändigerHalycons MaulkorbVosh'gajins StrangVoones ZwingenhandschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4904] = {title = "Endlich frei", objective = "Geleitet Lakota Windweise vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Bernhaut.", description = "Arnak glaubt, dass wir heiraten werden… aber nachdem ich seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte mich. Mein Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er... er tötete meinen Bruder, dann brachte er mich hierher. Mein armer Bruder...\n\n<Name>, würdet Ihr mich wohl vom Düsterwolkengipfel hinab geleiten? Bitte... ich muss zu Thalia zurückkehren! Sie macht sich bestimmt große Sorgen um mich.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Tief im Inneren wusste ich, dass sie ihren Weg zu mir zurückfinden würde. Sie hat mir von Eurem Mut berichtet und wie Ihr bei ihrer Flucht geholfen habt. Diese Gegenstände gehörten ihrem Bruder. Ich weiß, dass sie wollte, dass Ihr sie bekommt.", rewards = "WindweisentuchWindweisensattelgurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4906] = {title = "Weitere Verderbnis", objective = "Eridan Blauwind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Ein weiterer Satyrstützpunkt unter der Leitung des grausamen Xavaric bedroht den Teufelswald im Norden. Die elenden Verräter und Schwindler zehren von der Verderbnis der im Teufelswald heimischen Kreaturen.\n\nXavathras und seine Diener waren nur Teil eines größeren Plans - ein Mondbrunnen sollte verderbt werden und Xavaric sollte dann die Beute bekommen.\n\nDa Xavathras jetzt beseitigt ist, solltet Ihr diese Aufgabe beenden, <Name>. Geht nach Norden und besiegt Xavaric.", progress = nil, completion = "Vielen Dank für Eure Mühen, &lt;Name&gt;. Möge Elune Euch beschützen und auf Eurem weiteren Weg leiten.", rewards = "Ihr bekommt:\n\nArmschienen des Wolkenhauchs"}
MultiLanguageQuestData['de'][4907] = {title = "Tinkee Kesseldampf", objective = "Sprecht mit Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe.", description = "Hallo, <Name>. Erinnert Ihr Euch an Tinkee Kesseldampf? Tja, sie erinnert sich jedenfalls an Euch! Sie schickte mir eine Nachricht, dass ich nach Euch Ausschau halten soll... sie braucht nämlich nochmals Eure Hilfe. Ich glaube, es hat was mit ihren Drachenstudien zu tun.\n\nIhr solltet mit ihr sprechen. Sie ist in der Brennenden Steppe, beim Flammenkamm.", progress = nil, completion = "Felnok hatte Recht! Ich brauche wirklich Hilfe und dieses Mal... wird es wirklich gefährlich werden.\n\nSeid Ihr bereit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4921] = {title = "In der Schlacht vermisst", objective = "Sucht Mankriks Frau und kehrt dann zu ihm in die Siedlung beim Wegekreuz zurück.", description = "Wir wurden getrennt, als wir in einem kleinen Taurenlager gemeinsam kämpften - sie hat drei Borstennacken im Alleingang bezwungen. Aber dann waren sie plötzlich in der Überzahl. Ich lockte ein paar fort, dann sah ich, wie sie von Neuankömmlingen überwältigt wurde. Rasend vor Zorn stellte ich mich meinen Feinden, aber da es derer so viele waren, ging ich schon bald zu Boden.\n\nIch kam im Zelt eines Taurendruiden zu mir, der meine Wunden versorgte - er kam zufällig die Goldstraße entlang, als ich fiel.\n\nBitte, <Klasse>, sucht nach einem Lebenszeichen von meiner Frau.", progress = nil, completion = "Ich verstehe. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4941] = {title = "Etriggs Weisheit", objective = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\n\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.", description = "Rend lebt?\n\nUnmöglich!\n\nEr soll doch schon vor Jahrzehnten getötet worden sein.\n\nBittet Etrigg, seine Weisheit mit Euch zu teilen, <Name>. Niemand kennt den Schwarzfelsklan besser als er, und wenn es wahr ist, was hier geschrieben steht, muss Etrigg davon in Kenntnis gesetzt werden. Niemandem sollte das Recht auf Vergeltung versagt werden.\n\nIhr findet ihn in Orgrimmar.\n\nWenn Ihr mit Etrigg gesprochen habt, beratet Euch mit dem Kriegshäuptling, um von ihm zu erfahren, was er bezüglich dieses Problems zu unternehmen gedenkt.", progress = "Seht Ihr nicht, dass ich nicht gestört werden will?", completion = "&lt;Thrall scheint ob der Nachrichten, die Ihr bringt, bestürzt zu sein.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4961] = {title = "Die Säuberung der Kugel von Orahil", objective = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", description = "Ah, eine Beschwörerkugel - sie muss die Quelle der Besudelung sein. Wir müssen erst den Dämon darin exorzieren, wenn Ihr sie benutzen wollt. Das ist ein Klacks für mich.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, sobald ich ihn freigesetzt habe.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, kehrt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit, <Name>. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", progress = nil, completion = "Sehr schön, &lt;Name&gt;! Diese Lektion wird der Dämon nicht so schnell vergessen. Ihr habt bislang große Stärke und Können gezeigt. Jetzt solltet Ihr wohl mit Eurer gesäuberten Kugel zu Menara zurückkehren, um sie sinnvoll einzusetzen.\n\nViel Glück, &lt;Klasse&gt;. Vielleicht kreuzen sich unsere Wege wieder einmal.", rewards = "Ihr bekommt:\n\nGesäuberte Höllenkugel"}
MultiLanguageQuestData['de'][4962] = {title = "Splitter eines Teufelshundes", objective = "Nehmt den Teufelsrubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Leerbringer im Brachland den eingekerkerten Teufelshundgeist und den Teufelsrubin.", description = "Ihr seid also entschlossen, die Seele eines Teufelshundes zu fangen, gut.\n\nNehmt diesen Rubin - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort eines Teufelshundes habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Rubin zu Menara.", progress = "Ja, <Name>? Wofür habt Ihr Euch entschieden? Was soll es sein? Höllenbestie oder Teufelshund?\n\nEs ist eine persönliche Entscheidung, die Aufschluss über Eure Stärken und Schwächen bietet. Es kommt durchaus vor, dass <Klasse> ihre bestehenden Fähigkeiten intensivieren, statt solche, die ihnen noch fehlen, aufzubauen. Manchmal ist die Taktik, einen Feind einfach kräftemäßig zu überwältigen, ebenso wirkungsvoll, wie danach zu trachten, ein ausgeglichenerer Zauberer zu werden.", completion = "Ah, der Geist eines Teufelshundes. Gut gemacht, &lt;Name&gt;.\n\nWenn ich sowohl den Geist als auch die gesäuberte Kugel habe, werde ich beides miteinander für Euch verbinden... aber erst dann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4963] = {title = "Splitter einer Höllenbestie", objective = "Nehmt den Infussmaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Leerbringer im Brachland den eingekerkerten Höllenbestiengeist und den Infussmaragd.", description = "Ihr seid also entschlossen, die Seele einer Höllenbestie zu fangen, gut.\n\nNehmt diesen Smaragd - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort einer Höllenbestie habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Smaragd zu Menara.", progress = "Ja, <Name>? Wofür habt Ihr Euch entschieden? Was soll es sein? Höllenbestie oder Teufelshund?\n\nEs ist eine persönliche Entscheidung, die Aufschluss über Eure Stärken und Schwächen bietet. Es kommt durchaus vor, dass <Klasse> ihre bestehenden Fähigkeiten intensivieren, statt solche, die ihnen noch fehlen, aufzubauen. Manchmal ist die Taktik, einen Feind einfach kräftemäßig zu überwältigen, ebenso wirkungsvoll, wie danach zu trachten, ein ausgeglichenerer Zauberer zu werden.", completion = "Ah, der Geist einer Höllenbestie. Gut gemacht, &lt;Name&gt;.\n\nWenn ich sowohl den Geist als auch die gesäuberte Kugel habe, werde ich beides miteinander für Euch verbinden... aber erst dann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4964] = {title = "Die fertiggestellte Kugel von Dar'Orahil", objective = "Wartet, bis Menara Leerbringer die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt...Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", progress = nil, completion = "Es ist vollbracht, &lt;Name&gt;. Sagt mir, was Ihr lieber hättet: einen Stab, den Ihr mit beiden Händen führen müsstet, oder eine Kugel, sodass Ihr gleichzeitig noch einen Dolch oder ein Schwert als Waffe führen könnt.\n\nDass Ihr einen Teufelshund besiegt habt, war eine große Leistung. Ich bin mir sicher, dass dieser Gegenstand Euch in derZukunft gute Dienste leisten wird. Übt weiter fleißig Eure Künste, &lt;Name&gt;. Ich brenne darauf, bald mehr von Euren Heldentaten zu hören.", rewards = "Stab von Dar'OrahilAuf Euch wartet eine dieser Belohnungen:\n\nKugel von Dar'Orahil\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4965] = {title = "Wissen der Kugel von Orahil", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "Schön, schön, schön... Es ist eine Freude zu sehen, wie Eure Macht wächst, <Name>. Ich würde sagen, dass Ihr bald bereit seid, im Brachland mit Menara Leerbringer zu sprechen. Falls Ihr noch nie mit ihr gesprochen habt, dann lasst mich Euch sagen, dass ich wohl keinen zweiten Experten wie sie kenne, der so geschickt im Anfertigen von Gegenständen - insbesondere Kugeln - ist, in denen man sogar einen Dämon einkerkern kann, damit er einem einfach und bequem zu Diensten ist.\n\nFalls Ihr interessiert seid, begebt Euch zu Strahads Turm oberhalb von Ratschet im Brachland, dort findet Ihr sie.", progress = nil, completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4966] = {title = "Kanati Grauwolke schützen", objective = "Beschützt Kanati Grauwolke vor den Angriffen der Zentauren.", description = "Es könnte allerdings noch viel mehr Zentauren geben, als ich dachte, deshalb bitte ich Euch, <Name>, zusammen mit mir gegen diese gemeinen Auftragsmörder zu kämpfen.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Name&gt;. Ohne Euch hätte ich sie nicht abhalten können.", rewards = "LeichtfußstiefelLehmfarbene ArmschienenHandschuhe des BleichschreitersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4967] = {title = "Wissen der Kugel von Orahil", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "Immer noch derselbe Dummkopf... und immer noch auf der Suche nach Dingen der Sterblichen. Ja, es mag Euch arrogant erscheinen, wie ich zu Euch spreche. Ihr steht vor mir und ich muss lachen. Ihr seid jämmerlich!\n\nAber was ich denke, zählt nicht. Es zählt nur, was jene denken, die gewillt sind, sich mit Euch abzugeben! Und obwohl ich anderer Ansicht bin, sind jene, die über ein gewisses Maß an Macht gebieten, der Meinung, dass Ihr mehr verdient.\n\nWenn es das ist, wonach Ihr trachtet, solltet Ihr mit Menara Leerbringer im Turm oberhalb von Ratschet sprechen. Ich glaube, Ihr habt sie vor geraumer Zeit schon einmal getroffen.", progress = nil, completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4968] = {title = "Wissen der Kugel von Orahil", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "Hmm, Ihr habt es also bis hierher geschafft... das ist wahrhaft erstaunlich. Ich dachte, die Verderbnis durch die Kanalisierung des Arkanen hätte sich mittlerweile in Eure Seele geschlichen und Euch in den Wahnsinn getrieben. Sollen wir versuchen, Euch noch ein bisschen weiter aufzubauen?\n\nWenn Ihr Eure Fertigkeiten auf die Probe stellen wollt, sprecht mit Menara Leerbringer. Sie ist in Strahads Turm oberhalb von Ratschet zu finden. Sie wird Euch leiten.", progress = nil, completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4969] = {title = "Wissen der Kugel von Orahil", objective = "Sprecht mit Menara Leerbringer im Brachland.", description = "Haha! Das habt Ihr sehr gut gemacht, <Klasse>.\n\nFrüher oder später werden sich selbst Höllenbestien und Schreckenslords vor Euch in den Staub werfen!\n\nAber bis dahin müsst Ihr Euch noch auf die Waffen verlassen, die von Sterblichen geschaffen wurden.\n\nIhr scheint bereit zu sein für ein weiteres solches Werk, und wenn Ihr möchtet, würde Menara Leerbringer mit Euch sprechen! Sie ist in der Nähe von Strahads Turm zu finden, der oberhalb der Hafenstadt Ratschet steht. Geht dorthin, wenn Ihr bereit seid.", progress = nil, completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4970] = {title = "Frostsäblerverpflegung", objective = "Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterquell.", description = "Wenn Ihr Euch beweisen wollt, könnt Ihr eine sehr einfache, aber sehr wichtige Aufgabe erledigen.\n\nSammelt Fleisch von den Schimären und den Splitterzahnbären in diesem Gebiet. Bringt es mir, dann kann ich damit die Frostsäbler füttern, die gerade ausgebildet werden.", progress = "Disziplin und Bestimmtheit sind Eure Ziele. Ich werde Euch häufig bitten, einfache Aufgaben zu erledigen; Ihr müsst sie jeweils erfüllen, so gut es Euch möglich ist.", completion = "Danke, dass Ihr mir geholfen habt, &lt;Name&gt;. Meine Meinung von Euch wächst mit der Zeit.", rewards = nil}
MultiLanguageQuestData['de'][4971] = {title = "Eine Frage der Zeit", objective = "Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\n\nTötet 10 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", description = "Die Zeitlinie in Andorhal wurde durch eine finstere Kraft verfälscht - wahrscheinlich durch die Geißel! Ich kann versuchen, das Verstreichen der Zeit hier in den Griff zu bekommen und den Schaden zu beheben, aber dazu benötige ich Hilfe, damit ich dabei nicht gestört werde.\n\nTemporale Parasiten - Aas, das sich von den Strängen des veränderten Zeitflusses ernährt, sucht jetzt die Silos von Andorhal heim. Man kann sie nur an der blau pulsierenden Verzerrung erkennen. Sie behindern meine Weissagungen. Bitte helft mir, <Name>, indem Ihr diesen Temporalversetzer benutzt, um diese Parasiten auszurotten.", progress = "Temporale Parasiten sind eine Landplage, die immer dann auftritt, wenn sich jemand am Zeitablauf zu schaffen macht. Ich spüre, dass es eine Menge davon gibt, und das beunruhigt mich.\n\nRottet so viele aus, wie Ihr finden könnt. Das wird mir helfen, die sich stetig verschlechternde temporale Lage wieder unter Kontrolle zu bringen. Ich kann es spüren, sobald Ihr Erfolg hattet.", completion = "Es scheint jetzt leichter zu sein, die Zeit wieder zu korrigieren, danke, &lt;Name&gt;. Ihr mögt vielleicht nicht ganz verstehen, welche Konsequenzen ein aus den Fugen geratener Zeitablauf, eine gestörte Zeitlinie, haben kann, aber ich weiß es zu schätzen, dass Ihr versteht, wie dringlich es ist, dem Einhalt zu gebieten, was ich mehr und mehr für eine von der Geißel verursachte Bösartigkeit halte.\n\nEs ist wohl angebracht, dass ich Euch für Eure Hilfe belohne, sterbliches Wesen. Die größten Aufgaben stehen Euch noch bevor und ein kleines Schmuckstück als Belohnung wird Euer Schicksal bestimmt nicht beeinflussen. Eure beständige Unterstützung jedoch ist etwas, das für mich und den Drachenschwarm sehr nützlich sein könnte...", rewards = "OrchideenamiciaGoldverbundgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4972] = {title = "Tempus fugit", objective = "Sucht 5 Uhren von Andorhal, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.", description = "Ihr müsst für mich in die jenseits dieses Raumes liegende Welt gelangen, <Name>. Lasst es mich Euch erklären.\n\nIhr seht, dass dieser Raum hier anders ist als der Rest von Andorhal. Mein Drachenschwarm agiert auf verschiedene Weise und in vielen verschiedenen Zeitlinien. Um den in Andorhal angerichteten Schaden zu beheben, handle ich jetzt von einer anderen Zeitlinie aus, um sie nicht allzu sehr zu kontaminieren. Um diese Arbeit fortzusetzen, benötige ich Zeitobjekte, die aus einer Zeit stammen, bevor die Seuche auftrat. Ihr findet sie in Schließkassetten in den Ruinen der Gebäude, die einst diese stolze Stadt waren.", progress = "Die Zeitobjekte sind einfache Geräte. Es handelt sich hauptsächlich um Uhren, deren Zeiger stehen blieben, als die Seuche das erste Mal über Andorhal hereinbrach.\n\nDie Zeit bleibt niemals stehen und die Uhren, die Ihr mir bringt, kehren mit unfehlbarer Sicherheit immer wieder zu ihrem Ursprungsort zurück... das heißt, solange die Störungen hier andauern.", completion = "Genau das, was ich brauche, &lt;Name&gt;. Danke.\n\nErlaubt mir, Euch hiermit angemessen zu belohnen. Ihr fragt Euch vielleicht jetzt, was Ihr mit einem solchen Gerät anfangen sollt. Vielleicht wisst Ihr nicht einmal, worum es sich dabei genau handelt. Ich kann Euch leider nicht sagen, wann genau es Euch nützlich sein wird. Ihr müsst nur wissen, dass es irgendwann in der Zukunft äußerst nützlich und praktisch sein wird, wenn Ihr es benutzt. Ob Ihr es bis dahin behaltet oder nicht ... das bleibt allein Euch überlassen.", rewards = "Ihr bekommt:\n\nEingestellter Dämpfer"}
MultiLanguageQuestData['de'][4973] = {title = "Tempus fugit", objective = "Sucht 5 Uhren von Andorhal in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", description = "Falls Ihr gewillt seid, mir noch einmal zu helfen, würde ich Eure Unterstützung dankbar annehmen. Ich nehme Euch gern weitere Uhren ab, die Ihr in den Ruinen von Andorhal findet. Sie helfen mir sicherlich dabei, das Gleichgewicht gegen die unbekannte bösartige Kraft zu erhalten, die hier mit der Zeitlinie herumspielt.\n\nIm Austausch für diese Uhren werde ich Euch einen anderen Gegenstand geben, der sich, wie ich vermute, in der Zukunft für Euch als von großem Wert erweisen wird.", progress = "Die Uhren von Andorhal, ähnlich wie die große Uhr in der Ruine des Rathauses, sind sämtlich um drei Uhr stehen geblieben. Genau zu diesem Zeitpunkt hatte die Seuche die Stadt zum ersten Mal mit voller Wucht getroffen, sich ausgebreitet und jegliches Leben darin erstickt.\n\nSo sehr wir alle es auch bedauern, was an diesem Tag geschah, so sehr hat es doch auch den Zeitfluss geprägt, wie Ihr Sterblichen ihn heute empfindet. Der bronzene Drachenschwarm darf nicht nachlassen, die Zeitlinie zu schützen!", completion = "Habt abermals Dank für Eure Unterstützung. Bitte nehmt dieses Geschenk. Ihr mögt zwar immer noch nicht wissen, wann Ihr einen solchen Gegenstand benutzen könnt, aber vielleicht wird Euch irgendwann der Lauf der Zeit enthüllen, was Euch beschieden ist. Man könnte sagen, ich habe gesehen, dass es sich so ereignen wird, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nEingestellter Dämpfer"}
MultiLanguageQuestData['de'][4974] = {title = "Für die Horde!", objective = "Begebt Euch zur Schwarzfelsspitze und tötet den Kriegshäuptling Rend Schwarzfaust. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", description = "Nur weil der schwarze Drachenschwarm hinter ihm steht, wagt Rend es, solche Ansprüche zu stellen.\n\nIhr, <Name>, müsst einen Weg finden, die Hallen des Aufstiegs zu durchqueren. Dahinter findet Ihr den 'Kriegshäuptling' Rend Schwarzfaust. Ihr müsst ihn vernichten... FÜR DIE HORDE!\n\n<Thrall schlägt mit der Faust auf seinen Thron.>\n\nWenn Ihr meine Gemächer das nächste Mal betretet, werdet Ihr seinen Kopf triumphierend in die Höhe halten und ihn Eurem Kriegshäuptling präsentieren. Gelingt Euch das, wird man Euch als Held der Horde ehren.", progress = "<Thrall grunzt.>", completion = "Ihr habt der Streitmacht von Blackrock einen schweren Schlag versetzt, &lt;Name&gt;. Da ihr Kriegshäuptling jetzt tot ist, wird die Blackrocklegion erneut im Sumpf des Chaos versinken.\n\nZu Ehren Euer Heldentaten wird Euch das Volk von Kalimdor belohnen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal der TyranneiAuge der BestieSchwarzfausts Breite\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4975] = {title = "Die fertiggestellte Kugel von Noh'Orahil", objective = "Wartet, bis Menara Leerbringer die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt...Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", progress = nil, completion = "Es ist vollbracht, &lt;Name&gt;. Sagt mir, was Ihr lieber hättet: einen Stab, den Ihr mit beiden Händen führen müsstet, oder eine Kugel, sodass Ihr gleichzeitig noch einen Dolch oder ein Schwert als Waffe führen könnt.\n\nDass Ihr eine Höllenbestie besiegt habt, war eine große Leistung, und diese Belohnung wird Euch gut zupass kommen. Ich wünsche Euch weiterhin viel Erfolg, &lt;Name&gt;.", rewards = "Stab von Noh'OrahilAuf Euch wartet eine dieser Belohnungen:\n\nKugel von Noh'Orahil\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][4976] = {title = "Ablieferung der gesäuberten Kugel", objective = "Bringt die gesäuberte Höllenkugel zu Menara Leerbringer ins Brachland.", description = "Bringt die gesäuberte Kugel zurück zu Menara nach Ratschet, <Name>. Grüßt sie von mir und passt auf Euch auf. Ich hoffe wirklich, dass Ihr der Versuchung und der Verderbnis widerstehen könnt, die Euch auf Eurem Weg sicherlich begleiten werden.\n\nViel Glück.", progress = "Wie läuft die Suche nach Tabetha und der Kugel, <Name>?\n\nTabetha hat sich als mehr als hilfreich erwiesen, wenn es um arkane Dinge geht. Sie wird Euch bestimmt gern helfen, falls es Euch gelingt, sie zu finden.", completion = "Gut gemacht, &lt;Name&gt;. Das dürfte reichen.\n\nJetzt müsst Ihr nur noch entscheiden, welchen Dämon ich in der gesäuberten Kugel einkerkern soll. Entscheidet Euch, dann habt Ihr einen wunderbaren neuen Gegenstand, den Ihr benutzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4981] = {title = "Agentin Bijou", objective = "Begebt Euch zur Schwarzfelsspitze und findet heraus, was aus Bijou geworden ist.", description = "Trau niemals einem Goblin. Darauf läuft es doch hinaus, <Name>.\n\nSie heißt Bijou und ist eine unserer unzuverlässigsten Agentinnen. Ich habe herausgefunden, dass sie für irgendeinen zwielichtigen Tierhändler namens Kibler außerhalb der Brennenden Steppe gearbeitet hat - sie hat uns schlicht und ergreifend hintergangen. Und was noch schlimmer ist, sie hat Gelder der Horde veruntreut, um ihre Machenschaften zu finanzieren.\n\nIch will, dass man sie mir lebend bringt!\n\nZuletzt wurde sie beim Betreten der Schwarzfelsspitze gesehen. Findet sie und bringt sie her.\n\nUnd lasst Euch bloß nicht von ihr umgarnen, <Name>.", progress = nil, completion = "Ich kann Euch nicht belügen, &lt;Volk&gt;. Ich brauchte das Geld! Kibler bezahlt mich sehr, sehr gut - viel besser als es das KEK je könnte.\n\nAber bitte zweifelt nicht an meiner Loyalität! Warum, glaubt Ihr, bin ich wohl hier? Um diesem verrückten Goblin ein paar Eier von exotischen Tieren oder ähnlichen Unfug zu bringen? Nein, nur jemand, der wirklich absolut dämlich ist, würde zur Blackrockspitze kommen, um nach Tieren zu suchen. Tja, ich glaube nicht, dass es allzu viele Leute dieser Art auf der Welt gibt.\n\n\n\nDas würde uns gerade noch fehlen, dass sich solche Leute noch vermehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4982] = {title = "Bijous Habseligkeiten", objective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.", description = "Nachts, wenn dieser Ort hier nur leicht bewacht ist, schleiche ich durch die Stadt, mache mir Notizen und schreibe alles auf, was für das KEK strategisch nützlich sein könnte.\n\nLetzte Nacht ist allerdings etwas fürchterlich schief gegangen. Ich bin über einen Stolperdraht getappt und habe einen Alarm ausgelöst. Also habe ich mein Spionagezeug versteckt und bin auf Tauchstation gegangen! Leider kann ich nicht zurück, um meine Ausrüstung zu holen. Sie haben die Patrouillen verdoppelt und verdreifacht! All diese Informationen sind verloren.\n\nHolt mir meine Habseligkeiten, dann kehre ich freiwillig zum KEK zurück.", progress = "Glück gehabt?", completion = "Ihr habt es geschafft! Sobald Lexlort diese Pläne hat, wird er all die üblen Dinge vergessen, die er mir antun wollte.\n\n&lt;Name&gt;, Ihr seid mein Held!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4983] = {title = "Bijous Aufklärungsbericht", objective = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath.", description = "Bringt Lexlort diesen Bericht. Er wird meinen Namen reinwaschen und dem KEK bestimmt einen strategischen Vorteil gegenüber diesen Orcs verschaffen.\n\nIch soll mit Euch kommen? Dafür habe ich noch viel zu viel zu tun. Geht jetzt, diese Berichte werden gebraucht, je eher, desto besser!", progress = "Wo ist der Goblin???", completion = "Eines muss man ihr lassen, sie hat es wieder einmal geschafft, sich aus einer heiklen Situation herauszulavieren! Diese Berichte werden sich als unschätzbar erweisen, wenn wir es wieder mit den Orcs des Blackrockklans zu tun bekommen.\n\nNatürlich werdet Ihr für Eure harte Arbeit belohnt werden.", rewards = "FreiwindhandschuheSeepostengurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][4984] = {title = "Die Tierwelt leidet auch", objective = "Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Tiefenfurt auf dem Trostlosen Feld in den Westlichen Pestländern zurück.", description = "Allein konnte ich nicht viel tun, um die Geißel zu bezwingen. Aber ich kam dennoch hierher, um zu versuchen, den an der Natur angerichteten Schaden zu lindern. Die Tiere leiden unter der Seuche, die das Land noch immer plagt, und finden weder Gnade noch Frieden. Ich bitte Euch fortzusetzen, was ich hier nicht beenden konnte.\n\nEs gibt für diese leidenden Tiere keine Rettung, nur eine gnädige und sanfte Erlösung. Sucht die kranken Wölfe auf, die sich hier in der Nähe befinden, und tötet sie. Bitte, <Name>, macht ihrem Leiden ein Ende - Ihr würdet damit auch meinen Kummer lindern.", progress = "Die von der Seuche infizierten Wölfe müssen getötet werden, <Name>. Die Krankheit, an der sie leiden, ist unheilbar. Ich habe es versucht... Ich habe es versucht, bis ich mich selbst mit dieser Seuche angesteckt habe.", completion = "Ich... Ich spüre, dass die Seelen der Wölfe, die Ihr getötet habt, jetzt endlich Ruhe finden. Sie - und ich - danken Euch für die gnädige Befreiung.\n\nDie Wölfe sind jedoch nicht die Einzigen, die an diesem verfluchten Ort leiden, &lt;Name&gt;. Bitte, ich benötige noch einmal Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4985] = {title = "Die Tierwelt leidet auch", objective = "Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Tiefenfurt auf dem Trostlosen Feld in den Westlichen Pestländern zurück.", description = "Östlich von hier, etwa da, wo die Östlichen Pestländer beginnen, streiften einst stolze und herrliche Grizzlys durch das Land. Die von der Geißel freigesetzte Seuche hat auch auf diese Wildtiere übergegriffen. Jetzt ziehen sie durchs Land und leiden sehr, während ihre Muskeln steif werden und ihr Fell und Fleisch langsam verrotten.\n\nIch bitte Euch, auch sie von ihrem Elend zu erlösen. Das einzige Heilmittel für sie ist ein schneller Tod, beigebracht durch Eure Hand.", progress = "Ich höre Eure Schritte, <Name>. Meine Sehkraft ist geschwunden, aber ich kann immer noch Dinge in meiner Umgebung spüren. Habt Ihr die kranken Grizzlys von ihrem Elend erlöst?", completion = "Ich weiß, dass die Grizzlys tot sind und ihre Qual ein Ende hat. Ich... Ich habe da noch etwas für Euch. Ich habe es auf diesem... diesem Ast niedergeschrieben, weil ich fühle, dass meine Zeit in diesem Reich zu Ende geht.\n\nJa... Ich habe das Ende erreicht. Habt nochmals Dank... die Kreaturen dieses verfluchten Landes können in Frieden ruhen... und das werde ich jetzt auch.\n\nDer Druide seufzt noch einmal tief auf, dann folgt ein rasselndes Geräusch des Todes. Sein Körper liegt reglos auf dem Boden der Hütte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][4986] = {title = "Glyphenverzierter Eichenast", objective = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe.", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild des Baums von Teldrassil - genau gesagt von Darnassus - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben wohin er zu bringen sei.", progress = "Ich heiße Euch im Namen des Zirkels des Cenarius in dieser Enklave willkommen, <Klasse>. Was können wir für Euch tun?", completion = "Das... ist ziemlich seltsam. Dieser Druide - ein Taurendruide noch dazu - hat Euch eine Menge wertvoller Informationen bezüglich des Ausmaßes der Seuche der Geißel anvertraut. Es überrascht mich, dass ein Tauren einem wie Euch, &lt;Volk&gt;, Informationen überlassen würde, noch dazu freiwillig, wenn es stimmt, was Ihr sagt. Wir können sie aber wirklich gut gebrauchen. Vielleicht sind die Tauren ja doch nicht so weit von Cenarius abgefallen, wie Fandral meint...\n\nÄhm, wie dem auch sei, bitte nehmt dies als Zeichen des Danks des Zirkels des Cenarius.", rewards = "Ihr bekommt:\n\nKirschfarbenes Tuch"}
MultiLanguageQuestData['de'][4987] = {title = "Glyphenverzierter Eichenast", objective = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Donnerfels bringt. Bittet einen der Druiden dort um Hilfe.", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild von Donnerfels in Mulgore - genau gesagt von der Anhöhe der Ältesten - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben, wohin er zu bringen sei.", progress = "Ich heiße Euch im Namen des Zirkels des Cenarius in dieser Enklave willkommen, <Klasse>. Was können wir für Euch tun?", completion = "Das ist von Mulgris, sagt Ihr? Wir haben gehört, dass er danach trachtete, den leidenden Kreaturen der Pestländer zu helfen, aber das ist jetzt doch etwas unerwartet... und ziemlich traurig. Mulgris ist... war ein guter Freund. Ich werde sehr um ihn trauern.\n\nSeine Bemühungen waren Dank Eures Eifers jedoch nicht umsonst. Auf diesem Ast sind sehr viele Lehren über die Seuche festgehalten, die die Geißel über das Land gebracht hat. Wir werden alles eingehend untersuchen. Was Euch betrifft... bitte nehmt dies. Das ist das Mindeste, das wir zum Dank für Eure Mühen tun können.", rewards = "Ihr bekommt:\n\nKirschfarbenes Tuch"}
MultiLanguageQuestData['de'][5001] = {title = "Bijous Habseligkeiten", objective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", description = "Normalerweise gebe ich mich nicht mit Euresgleichen ab, <Volk>, aber mir scheint, ich stecke hier in einer Zwickmühle. Wisst Ihr, meine Mission hier ist für die Horde von allergrößter Wichtigkeit. Die Informationen, die ich hier gesammelt habe, betreffen jedoch auch das Wohlergehen der Allianz. Ihr könnt mir glauben, ich bin wahrlich kein Freund der Allianz, aber die Gefahr durch den Schwarzfelsklan ist größer als nur ein Haufen Orcs.\n\nIhr helft mir, meine Habseligkeiten zu finden, dann helfe ich Euch mit ein paar Informationen aus, die sich für Euresgleichen als nützlich erweisen könnten.\n\nAbgemacht?", progress = "Glück gehabt?", completion = "Da brat mir doch einer... Wo habt Ihr denn das gefunden???", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5002] = {title = "Nachricht an Maxwell", objective = "Begebt Euch in die Brennende Steppe und leitet Bijous Informationen an Marschall Maxwell weiter.", description = "Ich bin ein Goblin, der zu seinem Wort steht, <Volk>. Und jetzt hört gut zu.\n\nDiese Orcs werden vom schwarzen Drachenschwarm vor allem als Packesel und Kanonenfutter missbraucht!\n\nIhr wahrer Anführer ist kein Geringerer als Nefarian, die Brut von Todessschwinge. Ich habe auch den Aufenthaltsort der Untergebenen von Nefarian in diesem Teil der Zitadelle entdeckt.\n\nBringt diese Karte zu Marschall Maxwell in der Brennenden Steppe. Auf ihr ist der Aufenthaltsort dieser Teufelskreaturen eingezeichnet, um es einfacher zu machen.", progress = "Ah, <Name>. Wir haben uns lange nicht gesehen.", completion = "Das passt zu einem großen Teil dessen, was wir bereits wissen. Dennoch ist es interessant und höchst unerfreulich.\n\nDie Markierungen auf dieser Karte werden sich bei der Ausdünnung der Blackrockbedrohung als wertvoll erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5021] = {title = "Besser spät als nie", objective = "Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts.", description = "\"Das Paket muss ausgeliefert werden... sonst bin ich hier gefangen!\"\n\nWie ein Flüstern zieht das Wehklagen einer verängstigten Frau durch das Haus. In einer Ecke im oberen Stockwerk kauert eine weibliche, geisterhafte Gestalt. Sie scheint sich ihrer Umgebung nicht ganz gewahr zu sein und ist sich Eurer nur vage bewusst.\n\n\"Seid Ihr hier, um mein Paket auszuliefern? Bitte, bevor es noch viel schlimmer wird! Ich wollte hier wegreiten. Es sollte immer noch bei meinem Pferd sein... oder komme ich zu spät?\"", progress = nil, completion = "Ein Paket in der Scheune, das Ihr sonst übersehen hättet, fällt Euch nun zwischen Zerfall und Ruin ins Auge. Vielleicht ist es das, worüber der Geist von Janice Felstone gesprochen hat...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5022] = {title = "Besser spät als nie", objective = "Wendet Euch an die königlichen Disponenten von Sturmwind, um etwas über den Aufenthaltsort von Emma Teufelsstein herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus.", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an eine Emma Teufelsstein in Sturmwind adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Emma Teufelsstein überhaupt noch lebt, ist nicht klar. Aber man weiß, dass im Rathaus von Sturmwind Unterlagen über die Bevölkerung der Stadt aufbewahrt werden. Sie werden von den königlichen Disponenten des Volkszählungsbüros von Sturmwind verwaltet.", progress = "Willkommen im Volkszählungsbüro von Stormwind. Wenn Ihr Informationen über unsere Bevölkerung benötigt, dann kann ich Euch helfen.", completion = "Ein Paket für eine Emma Felstone, sagt Ihr? Letzte bekannte Adresse war Stormwind, vor vier Jahren? Tja, lasst mich mal nachsehen...\n\nNach dem, was wir wissen, gab es vor ungefähr vier Jahren eine Emma Felstone in der Stadt. Na ja, ich sollte sagen möglicherweise - diese Volkszählung, auf die ich mich beziehe, liegt fünf Jahre zurück und ich habe keinen Bericht darüber, dass sie die Stadt verlassen hat. Das bedeutet aber nicht, dass sie immer noch hier ist.\n\nWartet einen Moment... dieses Paket könnte nicht vielleicht für die alte Emma sein, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5023] = {title = "Besser spät als nie", objective = "Wendet Euch an die königlichen Vorarbeiter von Unterstadt, um etwas über den Aufenthaltsort von Jeremiah Teufelsstein herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung.", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an einen Jeremiah Teufelsstein aus Lordaeron adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Jeremiah Teufelsstein überhaupt noch lebt, ist nicht klar. Aber man weiß, dass Unterstadt, früher bekannt als Lordaeron, Unterlagen über die Bevölkerung der Stadt aufbewahrt. Sie werden von den königlichen Vorarbeitern des Volkszählungsbüros von Unterstadt verwaltet.", progress = "Seid Ihr hier, weil Ihr die Hilfe des Volkszählungsbüros von Undercity sucht, oder nur, um mich zu fragen, ob jemand, den Ihr kanntet, tot ist? Ich werde das häufig gefragt.", completion = "Ein Paket für einen Jeremiah Felstone, und seine letzte bekannte Adresse war Lordaeron... Ich sollte Euch helfen können.\n\nJeremiah Felstone war vor der Seuche in der Stadt. Tja, ich sollte sagen, der 'ehemalige' Jeremiah Felstone - einige der Verlassenen haben ihren Nachnamen abgelegt, um sich ihrer früheren Identitäten zu entledigen. Dieser Fall ist keine Ausnahme; der ehemalige Jeremiah Felstone ist jetzt unter dem Namen Jeremiah Payson bekannt.\n\nSekunde... ist er nicht der Kakerlakenverkäufer?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5041] = {title = "Vorräte für das Wegekreuz", objective = "Sammelt 5 Vorratskisten des Wegekreuzes in der Höhle der Klingenmähnen.", description = "Was auch immer im Südlichen Brachland geschehen ist, es hat einige der Stacheleberstämme in unsere Richtung getrieben. Insbesondere die vertriebenen Klingenmähnen werden immer verzweifelter und ihre Angriffe werden immer waghalsiger. Allein diese Woche habe ich schon zwei Karawanen verloren!\n\nUnsere Krieger am Wegekreuz warten händeringend auf diese Vorräte und ich habe nicht vor, zuzulassen, dass diese Stacheleber sich dank dieser Missetaten fettfressen können. Findet die vermissten Vorratskisten und bringt sie zu mir. Ich würde die Stacheleberhütten südlich von hier entlang des Flusses durchsuchen.", progress = "Wie läuft Eure Suche nach den Vorräten, <Name>? Ich schätze, die Stacheleber werden unter Eurer Kraft schnell fallen.", completion = "Haha! Danke, &lt;Name&gt;! Das wird uns höchst dienlich sein. Ihr seid ein Segen für Crossroads und die Horde. Wenn ich etwas für Euch tun kann, dann lasst es mich bitte wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5042] = {title = "Agammagans Kraft", objective = "Ich benötige 4 Blutsplitter, wenn Ihr Agammagans Kraft wünscht, <Volk>.\n\nEure Feinde werden vor Eurer Kraft erzittern, wenn Ihr über diesen Segen verfügen würdet. \n\nDie größten Krieger der Grimmhauer sind mit solcher Stärke ausgestattet!", description = nil, progress = "Ich benötige 4 Blutsplitter, wenn Ihr Agammagans Kraft wünscht, <Volk>.\n\nEure Feinde werden vor Eurer Kraft erzittern, wenn Ihr über diesen Segen verfügen würdet. \n\nDie größten Krieger der Grimmhauer sind mit solcher Stärke ausgestattet!", completion = "Wenn nur Quetschzahn frei wäre, um diejenigen zu dezimieren, die ihn betrogen haben! &lt;schnaubt&gt;\n\nIch danke Euch, dass Ihr durch das Sammeln dieser Splitter noch mehr Borstennacken vernichtet habt. Setzt Eure Arbeit bitte weiter fort und ich werde Euch weiterhin helfen. &lt;schnaubt&gt;", rewards = "Ihr erlernt:\n\nAgamaggans Kraft"}
MultiLanguageQuestData['de'][5043] = {title = "Agammagans Beweglichkeit", objective = "Man sagt, dass die größten Späher meines Stammes in ihrer Genauigkeit unübertroffen seien und kein Schurke <schnaubt> ihrer Schnelligkeit im Kampf standhalten könne.\n\nBringt mir 4 Blutsplitter und ich werde Euch noch flinker machen als jeder lebende Stacheleber.", description = nil, progress = "Man sagt, dass die größten Späher meines Stammes in ihrer Genauigkeit unübertroffen seien und kein Schurke <schnaubt> ihrer Schnelligkeit im Kampf standhalten könne.\n\nBringt mir 4 Blutsplitter und ich werde Euch noch flinker machen als jeder lebende Stacheleber.", completion = "Möge Eure Zielgenauigkeit unfehlbar sein und Eure Waffe Euch nie im Stich lassen, &lt;Volk&gt;.\n\nAgammagans Geist ist mit Euch. Kehrt  zu mir zurück, wenn Ihr wünscht. Quetschzahn wird Euch wieder segnen, wenn der große Gott der Eber mich als würdig ansieht.", rewards = "Ihr erlernt:\n\nAgamaggans Beweglichkeit"}
MultiLanguageQuestData['de'][5044] = {title = "Weisheit von Agammagan", objective = "Die Schamanen und Geomanten der Stacheleberstämme <schnaubt> nutzen die Kraft von Agammagan im Kampf und bei ihren Ritualen, <Volk>.\n\nWenn auch Ihr die zusätzliche Macht von Agammagans Segen für Eure Zauber wünscht, dann bringt mir 4 Blutsplitter, und Quetschzahn wird Euch helfen.", description = nil, progress = "Die Schamanen und Geomanten der Stacheleberstämme <schnaubt> nutzen die Kraft von Agammagan im Kampf und bei ihren Ritualen, <Volk>.\n\nWenn auch Ihr die zusätzliche Macht von Agammagans Segen für Eure Zauber wünscht, dann bringt mir 4 Blutsplitter, und Quetschzahn wird Euch helfen.", completion = "Eure Feinde sollten Euch noch mehr fürchten, &lt;Volk&gt;. \n\nErzählt Quetschzahn Geschichten von Eurer Schlauheit im Kampf, wenn wir uns das nächste Mal treffen - sei es in diesem Leben oder im nächsten.", rewards = "Ihr erlernt:\n\nWeisheit von Agamaggan"}
MultiLanguageQuestData['de'][5045] = {title = "Steigerung des Geistes", objective = "Krieger aller Art <schnaubt> benötigen einen starken Geist. Er treibt Euch zu größeren Leistungen, wenn alle Hoffnung verloren ist. Das ist den Grimmhauern nicht <schnaubt> unbekannt. Wir sind ein spiritueller Stamm... wir sind stolzer auf unsere Verbindung zu Agammagan als auf unsere Leistungsfähigkeit <schnaubt> im Kampf.\n\nBringt mir 4 Blutsplitter und ich werde Euch für den Kampf segnen. <schnaubt>", description = nil, progress = "Krieger aller Art <schnaubt> benötigen einen starken Geist. Er treibt Euch zu größeren Leistungen, wenn alle Hoffnung verloren ist. Das ist den Grimmhauern nicht <schnaubt> unbekannt. Wir sind ein spiritueller Stamm... wir sind stolzer auf unsere Verbindung zu Agammagan als auf unsere Leistungsfähigkeit <schnaubt> im Kampf.\n\nBringt mir 4 Blutsplitter und ich werde Euch für den Kampf segnen. <schnaubt>", completion = "Unsere größten Krieger und unsere größten &lt;schnaubt&gt; Schamanen würden Eure Willenskraft beneiden, &lt;Volk&gt;.\n\nErledigt noch mehr dieser Borstennacken, wissend, dass sie Euch nicht stoppen können!", rewards = "Ihr erlernt:\n\nWachsende Willenskraft"}
MultiLanguageQuestData['de'][5046] = {title = "Klingenhaut", objective = "Alle, die <schnaubt> in den Kampf eintreten, benötigen Schutz. Ihre Knochen müssen stark sein. Ihre Haut zäh. <schnaubt> Mein Stamm weiß das auch und um den natürlichen Schutz zu verstärken, den wir durch unsere Stacheln und unsere Haut erhalten, <schnaubt> rufen wir Agammagan an, uns vor Schaden zu schützen, bevor wir in den Krieg ziehen.\n\nBringt mir 4 Blutsplitter <schnaubt> und ich werde Euch den gleichen Schutz gewähren.", description = nil, progress = "Alle, die <schnaubt> in den Kampf eintreten, benötigen Schutz. Ihre Knochen müssen stark sein. Ihre Haut zäh. <schnaubt> Mein Stamm weiß das auch und um den natürlichen Schutz zu verstärken, den wir durch unsere Stacheln und unsere Haut erhalten, <schnaubt> rufen wir Agammagan an, uns vor Schaden zu schützen, bevor wir in den Krieg ziehen.\n\nBringt mir 4 Blutsplitter <schnaubt> und ich werde Euch den gleichen Schutz gewähren.", completion = "Zieht in den Krieg, &lt;Volk&gt;.", rewards = "Ihr erlernt:\n\nKlingenhaut"}
MultiLanguageQuestData['de'][5047] = {title = "Pip Flitzwitz, zu Euren Diensten!", objective = "Sprecht mit Malyfous Düsterhammer in der Ewigen Warte.", description = "Ihr findet Malyfous Düsterhammer in der Ewigen Warte, <Klasse>. Sagt ihm, dass Pip absolut in Ordnung ist und dass der Anzug perfekt funktioniert.\n\nDann gebt ihm dies:\n\n<Pip gibt Euch ein leuchtendes Fleischstück.>\n\nIch riss es aus den Innereien des Viechs während meines 'Urlaubs.'\n\nIch wette Malyfous könnte Euch eine recht genaue Einschätzung dessen geben, was er mit Teilen eines solchen Monsters tun kann!\n\nOh, ich schätze Ihr wisst nicht, wo die Ewige Warte ist, was? Geht nach Winterquell, <Bursche/Mädel>!", progress = "Ja?", completion = "Lebendig? Anzug funktioniert? Und was haben wir denn hier?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5048] = {title = "Emma die Nette", objective = "Sucht die alte Emma in Sturmwind und findet heraus, ob sie tatsächlich Emma Teufelsstein ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Teufelsstein für sie gepackt hat.", description = "Sie ist ein bisschen zänkisch und vielleicht nicht so ganz richtig im Kopf... aber diese Akten deuten darauf hin, dass die alte Emma zu den Informationen passt, die wir über Emma Teufelsstein haben.\n\nVielleicht habt Ihr die alte Emma durch die Stadt streifen sehen... sie redet mit sich selbst, meistens sinnloses Geplapper. Sie tut aber nichts und niemandem weh, also lassen die Leute sie meist gewähren.\n\nAlles in allem würde ich sagen, dass die alte Emma tatsächlich Emma Teufelsstein ist. Ihr könntet sie fragen, ob ihr Nachname Teufelsstein ist.", progress = "Ich würde Euch sagen, dass Ihr von meinem Grundstück verschwinden sollt, aber wie Ihr seht, habe ich keines.", completion = "Mein Name ist tatsächlich Emma Felstone... Ihr seid seit Jahren die erste Person, die mich so nennt. Wer... wer seid Ihr?\n\nIhr sagt, Ihr kennt... meine Schwester?! Ist sie noch am Leben? Wem mache ich etwas vor, natürlich ist sie es nicht. Als in Lordaeron die Seuche ausbrach, musste ich mit dem Schlimmsten rechnen. So viele aus meiner Familie starben... oder Schlimmeres. Hier bin ich nun, die verrückte alte Emma, ganz allein. Was seid Ihr, ein Grabräuber oder so? Sucht Ihr nach Eurem nächsten Opfer?\n\nWas? Ihr habt ein Paket für mich, von meiner Schwester?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5049] = {title = "Der Jammer des Jeremiah", objective = "Sucht Jeremiah Payson in Unterstadt und findet heraus, ob er tatsächlich Jeremiah Teufelsstein ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Teufelsstein für ihn gepackt hat.", description = "Nach den Informationen, die ich finden konnte, ist die Person, die Ihr sucht - und der vorgesehene Empfänger des Pakets -, Jeremiah Payson, der Kakerlakenverkäufer von Unterstadt.\n\nIch war immer der Meinung, dass es einer besonderen Gabe bedarf, um... Kakerlaken zu verkaufen. Zweifellos seid Ihr jetzt auf einer recht epischen Reise, <Klasse>. Ich werde Euch Euren weltverändernden Bestrebungen überlassen. Erlaubt mir aber, ein Teil Eures Meisterwerks zu sein und zu enthüllen, dass er sich in der Nähe der Bank aufhält und unter einem der Gehwege herumkriecht.", progress = "Jedes Mal, wenn jemand auf eine Kakerlake tritt, muss ich weinen. Bitte, bringt mich nicht zum Weinen.", completion = "Ich habe diesen Namen seit Jahren nicht mehr benutzt... aber ja, an einem gewissen Punkt in meinem Leben - vor diesem glorreichen Unleben - war das mein Nachname.\n\nIhr behauptet, meine Schwester gekannt zu haben... oder vielmehr, kürzlich mit meiner Schwester gesprochen zu haben?\n\nDie ist tot.\n\nSeit vier Jahren.\n\nWisst Ihr, wenn meine Knochen nicht bereits so brüchig wären, wäre ich versucht, mir meinen Fuß an Eurem Hinterteil zu brechen. Ihr seid ein echter Aasgeier, eh?\n\n Was? Ihr habt ein Paket für mich, von meiner Schwester?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5050] = {title = "Glücksbringer", objective = "Bringt Janice Teufelsstein in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück.", description = "Es scheint, dass ich bei Euch falsch lag, <Name>, und dafür schulde ich Euch eine Entschuldigung. Meine Schwester hat einige persönliche Dinge geschickt, einschließlich, was witzig genug ist, die Urkunde zum Teufelssteinfeld. Ich denke, ich werde im Moment darauf verzichten, Anspruch darauf geltend zu machen.\n\nWenn der Geist meiner Schwester weiterhin an den Hof gebunden ist und keine Ruhe finden kann, bitte... könntet Ihr dies wohl zu ihr bringen? Es ist die Hälfte eines Glücksbringers, den sie einst hatte. Die andere Hälfte hatte ihr Ehemann.\n\nVielleicht wird sie ihren Frieden finden, wenn sie weiß, dass ich diese Dinge habe.", progress = "John, Liebling... bist du das? Mir ist plötzlich so kalt...", completion = "Ihr gebt den halben Glücksbringer der Erscheinung zurück. Sie sieht erst ihn und dann erwartungsvoll Euch an.\n\n\"Liebling, wo ist deine Hälfte des Glücksbringers? Wir können nur zusammen sein, wenn wir beide Hälften haben. Liebling... kannst du mich sehen?\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5051] = {title = "Zwei Hälften vereint", objective = "Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.\n\nGebt den GlücksbringerJanice Teufelsstein auf dem Teufelssteinfeld in den Westlichen Pestländern.", description = "Der arme Geist plappert weiter:\n\n\"Mir ist so kalt, John. Bring mir deinen Glücksbringer und wir werden vereint sein! Schnell, John, bevor die Seuche uns in grauenhafte Bestien verwandelt! Ich kann dich nicht sehen, John... aber ich weiß, dass du nah bist. Ich fühle dich in meiner Nähe.\"\n\nVielleicht solltet Ihr die zweite Hälfte des Glücksbringers suchen und das Amulett wieder zusammensetzen... es könnte sein, dass der Geist von Janice Teufelsstein genau das sucht.", progress = "John, lass dich nicht von den Ghuls erwischen... lass nicht zu, dass die Ghuls mich erwischen... böse Ghuls... unser Glücksbringer wird uns schützen.", completion = "Ihr übergebt den zusammengesetzten Glücksbringer dem Geist von Janice Felstone. Als sie nach ihm greift, geht fast sofort eine Veränderung mit ihr vor. Ihre Astralgestalt schimmert und sie sieht Euch mit klaren, aber traurigen Augen an.\n\n\"Ihr habt mich befreit ... Ich werde diesen Glücksbringer nicht mehr benötigen. Nehmt ihn bitte und vielleicht wird er Euch den Trost geben, den er mir gegeben hat.\"", rewards = "Ihr bekommt:\n\nGlücksbringer der Teufelssteins"}
MultiLanguageQuestData['de'][5052] = {title = "Blutsplitter von Agamaggan", objective = "Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.\n\nSammelt weitere Blutsplitter, wenn Ihr von ihm mit Agamaggans Macht gesegnet werden möchtet.", description = "Zusammen mit diesen Dornen wirkte sich das Blut <schnaubt> auf andere Aspekte der Erde aus: blutrote Steine gemischt mit anderen Mineralien. Die Borstennacken graben diese Splitter aus und tragen sie als Totems <schnaubt> für Kraft im Kampf und als Totems für ihre Magie. <schnaubt>\n\nIch kenne die Geheimnisse dieser Magie.\n\nBringt Quetschzahn einen dieser Blutsplitter, um zu zeigen, dass Ihr verstanden habt. Bringt Quetschzahn viele dieser Splitter und er wird Euch mit Stachelebermagie segnen - der Magie von Agamaggan! <schnaubt>", progress = "Unsere Stämme finden sich in den dornigen Gegenden des Brachlandes zusammen <schnaubt>, da sie heilige Orte sind, aber keiner ist so heilig wie Razorfen. Agammagans Körper bildet die Gesamtheit des Razorfen <schnaubt>, aber die Hügel sind besonders geschützt, da der Eingang aus seinem großen Maul gefertigt ist! <schnaubt> Er wird die mit Haut und Haar verschlingen, die ihm nicht treu ergeben sind, und ihre Körper ausspucken, nachdem er sie zerkaut hat! <schnaubt>\n\nAgammagan hat seinen Körper zurückgelassen, um uns zu schützen, und er gibt uns von seinem Geist, damit wir ihn schützen können. <schnaubt>", completion = "Ah, Ihr versteht also. &lt;schnaubt&gt; Meine Worte waren in Euren Ohren nicht verloren, &lt;Volk&gt;. Quetschzahn mag eingekerkert sein, aber kein Käfig kann Agammagans Macht stoppen! \n\nDie Berührung des Splitters, das Gefühl... es ist schon lange her, &lt;Volk&gt;.\n\nWisst Ihr, wie es ist? Wenn man seiner Macht beraubt wird?\n\nAber das ist eine andere Geschichte. Ich habe Euch Informationen versprochen. Ich habe Euch Agammagans Macht versprochen. Meine Leute haben Quetschzahn den Rücken zugewandt. Nun lasse ich Euch auf sie los.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5054] = {title = "Ursius von den Splitterzahnbären", objective = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Ursius tötet.", description = "In den schneebedeckten Bergen von Winterquell pirscht sich ein geschickter Jäger an seine Beute an... Ich spreche vom Splitterzahnbären Ursius, einer flinken und schlauen Bestie.\n\nIch schicke Euch nun gegen ihn. Er zieht durch die wogenden Hügel im Nordwesten der Ewigen Warte. Findet und jagt ihn, bevor er Eure Absicht erkennt.\n\nAlle, die bisher gegen Ursius gezogen sind, haben schnell herausgefunden, dass sie die Beute waren und er der Jäger. Also seht Euch vor.", progress = nil, completion = "Das war keine einfache Aufgabe und trotzdem wart Ihr erfolgreich. Aber denkt nicht, Ihr hättet mich so einfach beeindruckt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5055] = {title = "Brumeran von den Eiswindschimären", objective = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Brumeran tötet.", description = "Geschickt und schlau gleitet Brumeran leise über die schneebedeckte Landschaft des südlichen Winterquell. Lasst Euch aber nicht von Ihrem graziösen Auftreten verleiten zu glauben, dass sie harmlos sei. Alle, die ihren Weg kreuzen, bezahlen einen hohen Preis dafür und häufig mit ihrem eigenen Leben.\n\nSucht Brumeran von den Eiswindschimären. Besiegt sie und kehrt dann wieder zu mir zurück.", progress = nil, completion = "Ja. Ihr seid zurückgekehrt. Jetzt glaube ich, dass Ihr von Natur aus ein wahrer Jäger seid. Ihr seid den wildesten Kreaturen gegenübergetreten... und Ihr seid zurückgekehrt. Damit habt Ihr meine Erwartungen übertroffen.\n\nIhr seid nun bereit für meine letzte Bitte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5056] = {title = "Shy-Rotam", objective = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Shy-Rotam besiegt.", description = "Im nördlichen Winterquell sammeln sich große Katzen rund um einen großen Orientierungspunkt, dem Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen Shy-Rotam bekannt. Wenn Ihr die Matriarchin der Frostsäbler besiegen würdet, würde Euch das großen Respekt in den Augen der anderen einbringen, <Volk>.\n\nGeht erneut nach Winterquell und sammelt dort hochheiliges Fleisch von den Frostsäblern. Sucht den Stein von Shy-Rotam und legt das Fleisch dort ab. Wenn Ihr es dort platziert, ruft das Shy-Rotam herbei... und sie wird kochen vor Wut.\n\nWappnet Euch vor ihrem Zorn und besiegt sie.", progress = nil, completion = "Ihr habt sowohl Eure Stärke als auch Eure Entschlusskraft bewiesen. Viele weitere Herausforderungen liegen vor Euch, aber ich habe Euch bereits so viel beigebracht, wie ich konnte.", rewards = "BestienjägerklingeBestienjägerdolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5057] = {title = "Frühere Abenteuer", objective = "Bringt Storm Schattenhufs Gutschein zu Melor Steinhuf in Donnerfels.", description = "Schon bevor Ihr mit mir spracht, <Name>, habe ich von Euren Abenteuern gehört... dass Ihr den unerschütterlichen Willen habt, Euch selbst zu beweisen, und dass Ihr als <Klasse> außerordentliche Fähigkeiten besitzt. Und nun weiß ich, dass diese Dinge wahr sind.\n\nWer wie Ihr herausragt, ist der Anerkennung würdig. Bringt diesen Gutschein zu einem Freund von mir in Donnerfels namens Melor Steinhuf. Ich bin sicher, dass er sich an Euch und das, was Ihr vor so langer Zeit erreicht habt, erinnern wird. Sprecht mit ihm über Eure jüngsten Siege und vergesst nicht, was Ihr heute erreicht habt.", progress = nil, completion = "Wir lernen aus den Erfahrungen unseres Lebens, &lt;Name&gt;. Ich bin sicher, dass Ihr durch die Euren nur stärker und weiser geworden seid. Ihr seid innerlich gewachsen, seitdem wir das letzte Mal miteinander gesprochen haben.\n\nNehmt dies als Erinnerung an die schwierigen Aufgaben, die Ihr als &lt;Klasse&gt; bewältigt habt, &lt;Volk&gt;, und wisset, dass Euch mein Respekt und meine Bewunderung immer sicher sein werden.", rewards = "Ihr bekommt:\n\nJägerinsignienmedaille"}
MultiLanguageQuestData['de'][5058] = {title = "Frau Dalsons Tagebuch", objective = "Ein Tagebuch mit vergilbten Seiten liegt aufgeschlagen da, sodass man den letzten Eintrag lesen kann:\n\n\"Ich weiß nicht, was passieren wird, jetzt, wo Harold sich verwandelt hat. Es hat mich meine ganze Kraft gekostet, ihn zu dem einzigen Ort zu schleppen, den ich finden konnte, in dem er sicher eingesperrt ist und nicht herauskommen kann. Den Schlüssel habe ich bei mir und ich kann nur beten, dass es funktionieren wird...\n\nIch hoffe, ich schaffe es, hier herauszukommen, aber dazu brauche ich Geld. Unsere ganzen Sachen sind alle im Schrank, glaube ich... und jetzt, wo ich darüber nachdenke - trägt Harold den Schlüssel dazu nicht bei sich?\n\nIch muss darüber schlafen. Im Augenblick bin ich todmüde.\"", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5059] = {title = "Weggeschlossen", objective = "Der von Splittern gezeichnete Türrahmen des Plumpsklos sieht aus, als ob wiederholt und unablässig versucht worden wäre, die Tür gewaltsam zu öffnen. Sie ist derzeit von außen fest verschlossen.\n\nAls Ihr an der Tür rüttelt, hört Ihr aus dem Inneren ein kehliges Stöhnen! Was auch immer sich im Inneren befindet, es klingt nicht freundlich.", description = nil, progress = "Der von Splittern gezeichnete Türrahmen des Plumpsklos sieht aus, als ob wiederholt und unablässig versucht worden wäre, die Tür gewaltsam zu öffnen. Sie ist derzeit von außen fest verschlossen.\n\nAls Ihr an der Tür rüttelt, hört Ihr aus dem Inneren ein kehliges Stöhnen! Was auch immer sich im Inneren befindet, es klingt nicht freundlich.", completion = "Mit dem Schlüssel, den Ihr bei dem Skelett der ehemaligen Mrs. Dalson gefunden habt, schließt Ihr die Tür zum Plumpsklo auf. Ein blutdurstiger Ghul, der wer weiß wie lange dort gefangen war, springt aus dem Schuppen.\n\nAls Ihr das markerschütternde Gekreisch des Ghuls hört, mit dem er auf Eure Anwesenheit reagiert, wird Euch klar, dass der einstige Bauer Dalson nicht mehr zu retten ist.", rewards = nil}
MultiLanguageQuestData['de'][5060] = {title = "Weggeschlossen", objective = "Vor Euch steht ein sehr stabiler Schrank, sicher verschlossen mit einem eingebauten Schloss. Die Vorderseite des Schranks ist mit tiefen Kratzern und Riefen übersät. Offensichtlich sind das die Zeichen zahlreicher und gewaltsamer fehlgeschlagener Versuche, die Geheimnisse zu enthüllen, die der Schrank derzeit verbirgt.\n\nWenn Ihr diesen Schrank öffnen wollt, müsst Ihr den Schlüssel finden.", description = nil, progress = "Vor Euch steht ein sehr stabiler Schrank, sicher verschlossen mit einem eingebauten Schloss. Die Vorderseite des Schranks ist mit tiefen Kratzern und Riefen übersät. Offensichtlich sind das die Zeichen zahlreicher und gewaltsamer fehlgeschlagener Versuche, die Geheimnisse zu enthüllen, die der Schrank derzeit verbirgt.\n\nWenn Ihr diesen Schrank öffnen wollt, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel aus den ghulischen Überresten des Bauern Dalson passt perfekt in das Schloss. Die Türen des Schranks schwingen auf und enthüllen verschiedene Gegenstände, die intakt sind und recht wertvoll erscheinen.", rewards = "Ihr bekommt:\n\nBauer Dalsons SchrotflinteEhering der Familie Dalson"}
MultiLanguageQuestData['de'][5061] = {title = "Wassergestalt", objective = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bärenfährte den Anhänger des Seelöwen.", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Mathrengyl Bärenfährte nach Darnassus zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", progress = "Eure Rückkehr nach Darnassus kommt nicht überraschend, doch ich werde einen Beweis dafür benötigen, dass Ihr die Lektionen in Moonglade gelernt habt, bevor ich Euch Eure Wassergestalt lehre.\n\nHabt Ihr den Anhänger des Seelöwen?", completion = "Sehr beeindruckend, &lt;Name&gt;. Ihr seid bereit, Eure Wassergestalt zu erlernen, und ich habe das Vergnügen, sie Euch zu lehren.\n\nAußerdem übergebe ich Euch als Anerkennung Eurer Leistungen während der beiden Prüfungen diesen Gegenstand. Ich hoffe, Ihr werdet ihn als eine wertvolle Ergänzung Eurer Ausrüstung als Beschützer der Natur und Bewahrer des Gleichgewichts ansehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWassergestalt\n\nIhr bekommt:\n\nGürtel des Wassermanns"}
MultiLanguageQuestData['de'][5062] = {title = "Hochheiliges Feuer", objective = "Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Donnerfels.", description = "Arikara ist eine tödliche Kreatur, die schnell beseitigt werden muss. Um sie zur Strecke zu bringen, müsst Ihr das hochheilige Feuer des Lebens anzünden - so wird Arikara beschworen.\n\nGeht nun und holt eine seltene Pflanze, die Brandpulveragave. Wenn Ihr genug Agaven gesammelt habt, sucht den Rat von Magatha Grimmtotem auf der Anhöhe der Ältesten in Donnerfels. Sie ist eine mächtige Schamanin, die die Agavenpflanze verzaubern kann, um ein Pulver zu erzeugen, das das Feuer entzünden kann.\n\nReist in Richtung Osten zum Siedenden Teich und sammelt Brandpulveragaven.", progress = "So, Motega Firemane schickt Nachricht von Arikara... nun, das sind böse Neuigkeiten.\n\n<Magatha sieht sich um.>\n\nArikara ist eine tödliche Kreatur, die nur geboren wurde, um Rache gegen die zu suchen, die ruchlose Taten begangen haben.\n\n<Magatha lächelt.>", completion = "Gut, Ihr habt die benötigte Menge Brandpulveragaven gesammelt. Dieses seltene Kraut, das man nur in Tausend Nadeln findet, wird helfen, das schlafende hochheilige Feuer des Lebens zu erwecken.\n\n&lt;Magatha beginnt, die Brandpulveragaven zu verzaubern.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5063] = {title = "Kappe des Scharlachroten Wissenden", objective = "Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", description = "Eine feinere Kappe werdet Ihr niemals sehen. Aus dem makellosen Balg der Bestie werden unsere Experten den phänomenalsten Hut schaffen, den ein Gaukler jemals zu tragen träumte!\n\nFünfzig Goldstücke zusammen mit den aufgeführten Gegenständen und Euer Kopf wird von der Kappe des Scharlachroten Wissenden geziert:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkankristalle.\n\n*Verzauberter scharlachroter Faden.\n\nMERKT AUF!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKappe des Scharlachroten Wissenden"}
MultiLanguageQuestData['de'][5064] = {title = "Grimmtotemspionage", objective = "Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.", description = "<Name>, Ihr habt uns in der Vergangenheit gut gedient, sodass ich Euch jetzt eine wichtige Mission anvertraue. Der Grimmtotemklan plant etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die Grimmtotem in den vergangenen Wochen besuchten. Wir haben entdeckt, dass diese geheimnisvollen Botschaften im Düsterwolkengipfel in verschiedenen Truhen verwahrt werden.\n\n<Name>, wenn Ihr bei dieser gefährlichen Mission erfolgreich seid, werde ich Euch entsprechend belohnen.", progress = "Habt Ihr entdeckt, was die Grimmtotem vorhaben?", completion = "Großes Geistertotem! Das sind wahrlich schlimme Neuigkeiten. Ich muss für alle nur möglichen Fälle Pläne entwickeln.\n\n&lt;Name&gt;, wie versprochen ist hier Eure Belohnung für Euren mutigen Dienst.", rewards = "WüstenschulternTundrastiefelHandgelenksschützer des dunklen TributsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5065] = {title = "Die verlorenen Schrifttafeln von Mosh'aru", objective = "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.", description = "Der Troll, mit dem Ihr gesprochen habt, hat Euch nicht die Wahrheit gesagt. Die beiden Schrifttafeln, die Ihr für ihn erhalten habt, sprachen davon, die Essenz von Hakkar zu bewahren, aber an dieser Legende ist noch mehr. Ich habe sie lange studiert und herausgefunden, dass es sechs Schrifttafeln von Mosh'aru gibt, nicht zwei! Sechs!\n\nUnd ich fürchte, dass uns die Geheimnisse, die die anderen enthalten, nicht gefallen werden.\n\nSucht die dritte und vierte Schrifttafel von Mosh'aru. Sie befinden sich in den Östlichen Pestländern, im Besitz der Moosschindertrolle. Sucht sie und bringt sie mir.", progress = "Habt Ihr die Schrifttafeln? Ich fürchte, dass ihre Texte eine große Bedrohung für unsere Welt enthüllen werden.", completion = "Ihr habt sie gefunden! Großartig!\n\nIch danke Euch, &lt;Name&gt;. Ich werde diese Texte durchgehen und ihre Bedeutung entschlüsseln.\n\nIhr aber habt eine andere Aufgabe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5066] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges.", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt am Zugwindlager errichtet hat, nördlich des Alteracgebirges!", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5067] = {title = "Gamaschen von Arcana", objective = "Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", description = "Wenn die Herstellung eines solchen Gegenstandes auch noch nie erfolgreich bewerkstelligt wurde, so wird sie doch für möglich erachtet - unter den richtigen Umständen.\n\nSollte der Sucher des Arkanums wünschen, Gamaschen mit immenser Kraft magiezuerfüllen, so muss er Folgendes suchen:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Frostraunens Balsamierungsflüssigkeit.\n\nMERKT AUF!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGamaschen von Arcana"}
MultiLanguageQuestData['de'][5068] = {title = "Brustplatte des Blutdurstes", objective = "Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", description = "Es heißt, dass nur eine einzige Brustplatte des Blutdurstes jemals geschaffen wurde und dass sie für die legendäre Auftragsmörderin Garona gemacht wurde. Ob diese Welt jemals eine weitere sehen wird, ist zu bezweifeln.\n\nWie dem auch sei! Unsere meisterlichen Handwerker können den Gegenstand reproduzieren, wenn die notwendigen Komponenten vorhanden sind:\n\n*Ein makelloser Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Die Haut des Schattens.\n\nMERKT AUF!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrustplatte des Blutdurstes"}
MultiLanguageQuestData['de'][5081] = {title = "Maxwells Mission", objective = "Reist zur Schwarzfelsspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus.", description = "Diese Informationen füllen die Lücken in unseren sonst einwandfreien Geheimdienstdaten über die Schwarzfelsspitze.\n\nDer Angriff muss entscheidend sein, <Name>.\n\nZuerst muss ihr Kriegsmeister, der Troll Voone, vernichtet werden. Ohne seine Kampfpläne werden die Schwarzfelsorcs im Chaos versinken.\n\nDann müsst Ihr den Ogerhochlord Omokk ausschalten. Die feigen Oger des Schwarzfels sind ohne seine Führungskraft machtlos.\n\nSchließlich noch der Oberanführer der Zitadelle: Wyrmthalak. Wenn Wyrmthalak tot ist, ist ihre zentrale Kommandoeinheit ohne Leitung.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Zumindest habt Ihr uns mehr Zeit verschafft - äußerst wertvolle Zeit.", rewards = "Wyrmthalaks FesselnOmokks UmfangbändigerHalycons MaulkorbVosh'gajins StrangVoones ZwingenhandschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5082] = {title = "Bedrohung durch die Winterfelle", objective = "Donova Schneeweh in Winterquell möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", description = "Ich kam nach Winterquell, um die Frostfeuerquellen zu untersuchen. Mir ist aufgefallen, dass das Wasser... merkwürdige Eigenschaften zu haben scheint. Ich konnte die Quelle aber noch nicht entdecken, und um die Wahrheit zu sagen, hatte ich in letzter Zeit durch die Furbolgs der Winterfelle einige Schwierigkeiten.\n\nSie scheinen von den Quellen angezogen zu werden, genau wie ich. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen mich nicht einmal in die Nähe der beiden größeren Quellen, die von hier aus im Norden liegen.\n\nIch würde meine Studien aber gern fortsetzen. Könntet Ihr mir wohl helfen?", progress = nil, completion = "Ich danke Euch vielmals, &lt;Name&gt;! Jetzt kann ich mich hier wieder an die Arbeit machen.\n\nHabt Ihr im Lager der Winterfelle irgendetwas Interessantes gefunden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5083] = {title = "Feuerwasser der Winterfelle", objective = "Bringt das leere Feuerwasserfläschchen zu Donova Schneeweh in Winterquell.", description = "Diese Phiole, die Ihr bei den Winterfellfurbolgs aufgehoben habt, ist leer, aber Ihr könnt im Inneren ein paar Tropfen einer merkwürdigen grünen Flüssigkeit sehen; sie scheint fast zu glühen.\n\nIst es etwas Wichtiges?\n\nDonova Schneeweh könnte Euch wahrscheinlich mehr sagen, da sie nun schon einige Zeit bei den heißen Quellen in Winterquell lagert.", progress = "Was habt Ihr da gefunden?", completion = "Ihr habt dies von den Winterfellfurbolgs?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5084] = {title = "Der Verderbnis erliegen", objective = "Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis.", description = "Diese grünliche Flüssigkeit... sie erinnert mich ein wenig an den Schlamm, den ich bei meiner Reise durch den Teufelswald sah. Und ich habe einige Läufer der Winterfelle gesehen, die die Furbolgs der Holzschlundfeste passierten... Vielleicht haben diese Dinge etwas mit dem Fläschchen zu tun, das Ihr gefunden habt, <Name>.\n\nEs gibt eine große Gruppe Furbolgs direkt hinter der Holzschlundfeste im Teufelswald. Es ist der so genannte Stamm der Totenwaldfelle. Er wurde durch teuflische Energien verderbt und in den Wahnsinn getrieben. Warum seht Ihr Euch dort nicht um und schaut, ob Ihr Beweise für irgendwelche Beziehungen zwischen den Winterfellfurbolgs und den Totenwaldfellen findet?", progress = nil, completion = "Im Kessel blubbert eine faulige, ekelerregend riechende Substanz...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5085] = {title = "Geheimnisvoller Glibber", objective = "Berichtet Donova Schneeweh von Euren Entdeckungen.", description = "Die grünliche Substanz in dem Kessel scheint der zu ähneln, die Ihr in dem Fläschchen gefunden habt. Dieses merkwürdige zähflüssige Zeug könnte genauso verderbt sein wie die Furbolgs, die es geschaffen haben...\n\nFalls die Winterfellfurbolgs es verwenden, bedeutet das, dass sie bald genauso verderbt sein werden wie der Stamm der Totenwaldfelle?\n\nEs wäre das Beste, Donova von Euren Funden zu berichten und ihr eine Probe aus dem Kessel mitzubringen.", progress = "Ich hoffe, Ihr habt etwas gefunden, <Name>. Die Winterfelle werden immer aggressiver!", completion = "Ihr seid sehr einfallsreich, &lt;Name&gt;. Glaubt Ihr, dass die Furbolgs der Winterfelle im Lager der Totenwaldfelle waren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5086] = {title = "Toxinschrecken", objective = "Sammelt 3 Toxinschreckentropfen für Donova Schneeweh in Winterquell.", description = "Ich habe die Probe untersucht, die Ihr mitgebracht habt. Ganz sicher bin ich mir nicht, aber ich glaube doch, dass sie Spuren von toxischen Elementen enthält. Die einzige Möglichkeit, das zu bestätigen, besteht darin, einige Proben als Vergleich zu sammeln.\n\nIch glaube, dass sich die Furbolgs der Totenwaldfelle diese Elemente möglicherweise von anderen verderbten Kreaturen im Teufelswald holen, vor allem von den Elementaren, die im Eisenwald leben und Toxinschrecken genannt werden.\n\nSammelt einige Proben zum Vergleich für mich. Aber seid vorsichtig: Es ist dort sehr gefährlich!", progress = "Ich glaube, wir verstehen so langsam, was hier geschieht, <Name>.", completion = "Ich muss diese Substanz mit der vergleichen, die Ihr in dem Kessel gefunden habt, und dann werden wir sicherlich mehr wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5087] = {title = "Läufer der Winterfelle", objective = "Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.", description = "Sehr interessant, <Name>...\n\nWenn diese toxische Substanz mit dem Wasser aus den heißen Quellen gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die Winterfelle die heißen Quellen wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern.\n\nWir müssen das hier stoppen... den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden. Eine Gruppe von Läufern ist zwischen ihrem Dorf und dem Teufelswald unterwegs. Sucht und besiegt sie und stehlt ihre Lieferung.", progress = "Wir werden ja sehen, was geschieht, wenn die Winterfelle ihr Feuerwasser nicht bekommen!", completion = "&lt;Donova untersucht den Inhalt der Kiste.&gt;\n\nIch frage mich, ob der Verzehr dieser Substanz die Furbolgs aggressiver macht. Sie wirken irgendwie viel größer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5088] = {title = "Arikara", objective = "Erschlagt Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Feuermähne im Weißgipfelposten als Beweis für Eure Tat.", description = "Bringt dieses aufbereitete und geläuterte Brandpulver nach Tausend Nadeln und werft es in das hochheilige Feuer des Lebens. Es befindet sich beim Düsterwolkengipfel auf einer isolierten Nadel, wo sie ihre Toten beerdigen.\n\nDie Verzauberung, die ich in das Brandpulver eingewoben habe, wird Arikara für Euch beschwören, <Name>.\n\nIch fürchte, dass sie Cairne Bluthuf bedrohen könnte; die Lehren der Tauren haben sich zu sehr verändert und möglicherweise ist Arikara darüber erzürnt. Tut schnell etwas, bevor alles verloren ist, <Klasse>!", progress = "Habt Ihr die heimtückische Schlange Arikara erschlagen, <Name>?", completion = "Das ergibt keinen Sinn. Warum sollte Arikara hinter Cairne Bloodhoof her sein? Magatha kann sich nicht irren, sie ist unsere mächtigste Schamanin.\n\n&lt;Motega schüttelt seinen Kopf.&gt;\n\nWie dem auch sei, Eure große Tat für die Horde soll nicht unbemerkt bleiben - wählt bitte einen dieser Gegenstände als Belohnung für Eure Hilfe.", rewards = "SchlägerhammerGiftstachelzauberstabKlinkschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5089] = {title = "General Drakkisaths Befehl", objective = "Bringt den Befehl von General Drakkisath zu Marschall Maxwell in der Brennenden Steppe.", description = "Dem Kadaver der besiegten Schlange entnehmt Ihr etwas, das wie ein Schreiben von einiger Bedeutung aussieht. Es ist ein Brief des Vorgesetzten, General Drakkisath, bezüglich des Protokolls.\n\nEuer Instinkt sagt Euch, dass Ihr ihn zu Marschall Maxwell bringen solltet.", progress = "Was habt Ihr denn da, <Name>?", completion = "Es wird spannend...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5090] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges.", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt am Zugwindlager errichtet hat, nördlich des Alteracgebirges!", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5091] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges.", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt am Zugwindlager errichtet hat, nördlich des Alteracgebirges!", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5092] = {title = "Den Weg räumen", objective = "Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Trauerhügel.\n\nKehrt zu Kommandant Ashlam Ehrenschlag am Zugwindlager, westliche Pestländer, zurück.", description = "Da die westlichen und nördlichen Straßen in die Stadt von Andorhal gut befestigt sind, habe ich vor, über die weniger gut verteidigte östliche Straße anzugreifen. Die Geißel verlässt sich auf den Puffer von Untoten, die Trauerhügel heimsuchen, als erste Verteidigungslinie. Wenn wir nach Andorhal vordringen wollen, müssen wir es über Trauerhügel tun.\n\nEure erste Aufgabe besteht darin, den Weg durch Trauerhügel zu säubern. Dünnt die Masse der Skelette und Ghule aus, die das Gebiet heimsuchen. Meldet Euch wieder bei mir, wenn das erledigt ist!", progress = nil, completion = "Mission erfüllt, &lt;Name&gt;! Das war sehr gut gespielt.\n\nErlaubt mir, Eure bisherige Arbeit mit einigen Münzen aus dem Staatsschatz von Stormwind zu belohnen. Ich empfehle Euch, es für Material auszugeben, das Euch bei der nächsten Mission helfen wird... einer, die Euch in die Ruinen von Andorhal hineinführen wird.\n\nSeid bereit! Seid wachsam!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5093] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5094] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5095] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Hochexekutor Derrington auf. Sein Stützpunkt befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", description = "Ihr Helden dieser Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nZögert nicht lange, ihr Helden! Sucht Hochexekutor Derrington auf! Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen.", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5096] = {title = "Scharlachrote Ablenkung", objective = "Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.\n\nLasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück.", description = "Vor Andorhal müssen wir die Bedrohung durch den anrückenden Scharlachroten Kreuzzug von Herdweiler niederschlagen. Dessen Lager wurde zwischen dem Teufelssteinfeld und Dalsons Tränenfeld aufgeschlagen, wodurch wir gleichzeitig einen Konflikt mit der Geißel und dem Kreuzzug riskieren müssen.\n\nMein Plan ist, sie gegeneinander auszuspielen, indem wir Euch schicken, um das Kommandozelt zu zerstören, das sie errichtet haben. Benutzt dazu die Flaschenflammen aus dieser Kiste mit Brandsätzen. Sobald es vernichtet ist, richtet Ihr dieses Banner der Geißel bei dem Zelt auf. Mit etwas Glück werden sie uns ignorieren und sich auf Rache gegen die Geißel konzentrieren.", progress = "Ein Überraschungsangriff auf die schwache Vorhut des Scharlachroten Kreuzzugs wird uns genügend Zeit verschaffen, um gen Andorhal zu marschieren. Ich erwarte, dass Ihr von Eurem Erfolg berichten wollt!\n\nNachdem dies erfolgreich ausgeführt ist, müssen wir sorgfältig und schnell sein. Wir haben weder das Material noch die Männer, um sowohl die Geißel als auch den Scharlachroten Kreuzzug gleichzeitig zu bekämpfen, wenn sie unserem kleinen Trick nicht glauben.", completion = "Das habt Ihr hervorragend gemacht, &lt;Name&gt;! Euer Angriff auf den Scharlachroten Kreuzzug wird uns Zeit verschaffen. Ich habe einen meiner besten Späher geschickt, um das Lager zu beobachten und sicherzustellen, dass die Kräfte des Kreuzzugs, die zur Verstärkung der Position anrücken, den Köder schlucken.\n\nNachdem sich der Druck auf uns verringert hat, sollten wir dann eine Mission nach Andorhal riskieren können und eine wichtige noch dazu. Ich möchte gern, dass Ihr auch diese ausführt, da Ihr bisher so erfolgreich wart.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5097] = {title = "Turm um Turm", objective = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Ehrenschlag am Zugwindlager, westliche Pestländer, zurück.", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", progress = "Wenn die Türme markiert sind, werden sie zu Zielen der obersten Priorität für unseren Angriff auf Andorhal. Ich vermute, dass die Hauptbedrohung von Andorhal auftauchen wird, wenn wir die Türme neutralisiert haben. Von dem Punkt an gibt es einen offenen Kampf um die Kontrolle der Stadt!\n\nIhr seid zurück, um von Eurem Erfolg zu berichten, ja? Vergesst nicht die Signalfackel, wir müssen die Kontrolle über unser Material bewahren.", completion = "Meine Priester melden, dass unsere Signalsucher extrem starke Signale von allen vier Türmen empfangen! Ich wage zu sagen, dass Ihr eine weitere Mission mit umfassendem und absolutem Erfolg ausgeführt habt! Erneut gut gespielt, &lt;Name&gt;!\n\nMit der Markierung der Türme sind unsere Angriffsvorbereitungen jetzt abgeschlossen. Die Zeit ist gekommen, um den Kampf zur Geißel zu bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5098] = {title = "Turm um Turm", objective = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern, zurück.", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", progress = nil, completion = "Meine Hexenmeister melden, dass unsere Signalsucher extrem starke Signale von allen vier Türmen empfangen! Ihr habt meine Befehle mit dem Geschick und der Präzision eines erfahrenen Veterans ausgeführt. Euer Dienst an der Horde wird einmal mehr aufmerksam notiert, &lt;Name&gt;!\n\nMit der Markierung der Türme sind unsere Angriffsvorbereitungen jetzt abgeschlossen. Die Zeit ist gekommen, um den Kampf zur Geißel zu bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5101] = {title = "Lee's Ultimate Test Quest... of Doom!", objective = "Tötet 6 Schafe für Benny... und dann nehmt die Beine in die Hand und rennt, was das Zeug hält!\n\n\n\n\nWar nur 'n Scherz... was das Rennen angeht.", description = "Pah! Was glaubt Ihr'n, was das is', 'ne Art Test-Quest? Ich wett, dass da sogah Tippfehler drinne sin'!\n\nUn' wenn Ihr denkt, dass mein Quest einfach sein würd, denn irrt Ihr Euch abba gewaltich!\n\nMacht mir ma' zehn Schafe (1933) alle und kommt erst zurück, wenn Ihr's getan habt!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRitterliches Langschwert"}
MultiLanguageQuestData['de'][5102] = {title = "General Drakkisaths Niedergang", objective = "Begebt Euch zur Schwarzfelsspitze und schaltet General Drakkisath aus.", description = "Wir kämpfen an zwei Fronten gegen diese Biester: Von unserer Hauptstadt Sturmwind aus bekämpfen wir sie von innen, und hier, in der Brennenden Steppe, tragen wir den Kampf an ihre Türschwelle. Wir müssen wachsam sein, <Name>. Niemand soll von unserem Zorn verschont werden, da keiner der Unseren verschont wurde, als der Feind bei unseren Heimen und Familien zuschlug.\n\nFindet diesen General Drakkisath und erledigt ihn!\n\nDie Aufgabe ist sicherlich nicht einfach, aber die Belohnungen werden großartig sein.", progress = nil, completion = "Wir werden bestimmt als Nächstes gegen ihre Großdrachenlords ziehen. Gut gemacht, mutiger Soldat der Allianz! Wirklich hervorragend.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal der TyranneiAuge der BestieSchwarzfausts Breite\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5103] = {title = "Heißer, feuriger Tod", objective = "Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!", description = "Das Einzige, was von diesem Menschen übrig geblieben ist, sind einige verkohlte Knochen. Er scheint in Armeslänge dessen gestorben zu sein, hinter dem er her war - ungebrannten Plattenstulpen.\n\nVielleicht solltet Ihr die Stulpen nehmen und aus dem Feuer verschwinden?", progress = nil, completion = "Was zum...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5121] = {title = "Oberhäuptling der Winterfelle", objective = "Donova Schneeweh in Winterquell möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt.", description = "Wir wissen leider immer noch nicht, warum die Furbolgs diese merkwürdige Substanz einnehmen. Aber ich glaube, es wäre das Beste, das zu unterbinden, bevor es ausufert.\n\nDie Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt mich zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Wir werden wohl den Schaden, der bereits angerichtet ist, nicht mehr beheben können, aber ich denke, wenn ihr Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\n\nBegebt Euch nach Osten zum Lager der Winterfelle.", progress = nil, completion = "Vielen herzlichen Dank, &lt;Name&gt;. Ich hoffe zu meinen Studien zurückkehren zu können, ohne Angst, dass ich in einen Hinterhalt gerate. Nehmt dies bitte als Belohnung.", rewards = "KristallbrisenmantelFarnpulswamsWeidenbandhalsbergeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5122] = {title = "Das Medaillon des Glaubens", objective = "Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann.\n\nBitte, <Name>, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme.", description = nil, progress = "Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann.\n\nBitte, <Name>, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme.", completion = "Ihr habt das Medaillon bekommen! Jetzt kann ich die Kapelle verlassen und meine Pflicht erfüllen.\n\nDiese Pflicht besteht darin, die Bestie zu töten, die dabei half, mich und so viele meiner Brüder und Schwestern zu verderben: Baron Rivendare!", rewards = nil}
MultiLanguageQuestData['de'][5123] = {title = "Das letzte Stück", objective = "Bringt das kunstlos geschriebene Logbuch zu Donova Schneeweh in Winterquell.", description = "Das Logbuch, das Ihr bei dem Oberhäuptling gefunden habt, scheint recht ausführlich zu sein, aber nachdem Ihr einige Seiten durchgesehen habt, stellt Ihr fest, dass Ihr den Text nicht lesen könnt. Die Zeichen sind so kunstlos und schlecht geformt, dass Ihr nicht sicher seid, ob überhaupt jemand sie lesen kann.\n\nAber vielleicht kann Donova Euch sagen, was sie bedeuten...", progress = "Was habt Ihr da, <Name>?", completion = "Ich frage mich, was das alles bedeutet... Ich kann mir keinen Reim darauf machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5124] = {title = "Feurige Plattenstulpen", objective = "Bringt Malyfous Düsterhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.", description = "Beim Barte Thaurissans!\n\nWo habt Ihr sie gefunden?\n\nNoch wichtiger: Seid Ihr bereit, Euch von ihnen zu trennen? Natürlich würde ich solch eine noble Geste belohnen.\n\nIch sag Euch was, <Name>. Wenn Ihr mir diese ungebrannten Stulpen gebt, werde ich Euch beibringen, wie Ihr selbst welche herstellen könnt. Ihr müsst nur die Teile für mich besorgen, damit ich das genaue Rezept benutzen kann.\n\nAbgemacht?\n\nHier ist die Liste dessen, was ich benötige. Ich werde das nicht-verzauberte Thorium selbst übernehmen, da Ihr ja die Stulpen liefert.", progress = "Zeit ist Geld, <Name>, und ich habe von beidem nicht viel.", completion = "Wie versprochen, &lt;Name&gt;, hier ist Euer Rezept! Ich werde Euch für Eure harte Arbeit und Hingabe außerdem noch etwas extra geben. Was sollte ich sonst mit dem Zeug hier tun...", rewards = "Ihr bekommt:\n\nPläne: Feurige PlattenstulpenFeurige Plattenstulpen"}
MultiLanguageQuestData['de'][5125] = {title = "Aurius' Abrechnung", objective = "<Name>, ich sterbe... aber meine Seele ist gerettet. Dafür schulde ich Euch mehr, als man mit Worten ausdrücken kann. Bitte, nehmt dies... und kämpft weiter so mutig, <Klasse>!", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWille des MärtyrersBlut des Märtyrers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5126] = {title = "Lorax' Geschichte", objective = "Sprecht mit Lorax. Hört, was er zu sagen hat.", description = "Der Satyr wandert auf und ab und spricht mit sich selbst. Möchtet Ihr ihn ansprechen?", progress = "...", completion = "&lt;Lorax lacht.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5127] = {title = "Die Dämonenschmiede", objective = "Begebt Euch zur Schwarzfelsspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\n\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\n\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterquell.", description = "Lorax macht Geschäfte, aber er akzeptiert sie nicht von unbedeutenden Sterblichen.\n\nEinen Handel kann ich aber mit Euch machen... nehmt diese Pike, sie ist mit mächtigen Fel-Energien getränkt. Wenn Ihr Goraluk Hammerbruch findet, erschlagt ihn und treibt diese Pike durch sein sterbendes Herz. Er hat seine Seele verschachert und daher werde ich seine Seele bekommen. Bringt die Pike und die Brustplatte zurück, die der Dieb gestohlen hat, und ich werde Euch das beibringen, was er lernen sollte.", progress = "Seid nicht versucht...", completion = "Unseren Pakt habt Ihr nicht gebrochen. Die Seele nahm ich. Die Belohnung werde ich geben.", rewards = "Ihr bekommt:\n\nPläne: Dämonengeschmiedete BrustplatteElixier des DämonentötensDämonengeküsster Sack"}
MultiLanguageQuestData['de'][5128] = {title = "Worte des Oberhäuptlings", objective = "Bringt das kunstlos geschriebene Logbuch zu Kelek Himmelshüter im südlichen Teil des Teufelswalds.", description = "Die Winterfelle sind für mich keine Bedrohung mehr, aber wenn Ihr immer noch herausfinden möchtet, was die Furbolgs dazu brachte, dieses merkwürdige Feuerwasser herzustellen und zu konsumieren, solltet Ihr Kelek Himmelshüter aufsuchen.\n\nEr gehört zu einer Gruppe, die als Smaragdkreis bekannt ist, Druiden, die sich ihrer Arbeit im Teufelswald widmen und das Land von der Verderbnis heilen.\n\nKelek hat viel Erfahrung mit den Furbolgs im Teufelswald und kann Euch vielleicht mehr über das Logbuch sagen.\n\nNochmals danke, <Name>.", progress = "Der Smaragdkreis ist allen freundlich gesinnt, <Volk>. Was kann ich für Euch tun?", completion = "Ja, wenn Ihr es mich eine Weile untersuchen lasst, kann ich es für Euch vielleicht übersetzen.\n\n&lt;Kelek blättert durch die Seiten.&gt;\n\nWenn ich es ganz durchgesehen habe, werde ich Euch eine Nachricht schicken.\n\nDanke, dass Ihr dies mit mir teilt, &lt;Name&gt;. Man weiß sehr wenig über die Winterfellfurbolgs.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStärke des OberhäuptlingsMacht des Oberhäuptlings\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5141] = {title = "Drachenlederverarbeitung", objective = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5142] = {title = "Klein-Pamela", objective = "Sucht in Darroheim nach Pamela Rotpfad.", description = "So viele von uns sind im Kampf von Darroheim gefallen. So viele starben... und noch Schlimmeres.\n\nAls die Schlacht begann, versteckte ich meine Nichte Pamela, und ich weiß nicht, was mit ihr geschehen ist. Ich bin nur ein wandernder Geist, aber mein Herz möchte dennoch Pamelas Schicksal kennen.\n\nBitte, <Klasse>. Könnt Ihr nach Darroheim gehen und nach ihr suchen? Es liegt im Osten, hinter Gahrrons Trauerfeld.", progress = nil, completion = "Hallo. Ich bin Pamela, und wie heißt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5143] = {title = "Stammeslederverarbeitung", objective = "Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Jägermond in Feralas.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5144] = {title = "Elementarlederverarbeitung", objective = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Gerber in die Sengende Schlucht.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Elementarlederverarbeitung ist, was ich kann und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", progress = "Für die Herstellung dieser Art von lederner Rüstung bedarf es der Geduld und der Hingabe. Wenn Ihr Euch einmal auf die Elemente eingelassen habt, gibt es kein Zurück mehr. Bringt mir einen Beweis Eures Wertes und wir werden beginnen.", completion = "Ihr habt Eure Entscheidung getroffen und die Elemente akzeptieren Euch. Wenn ich meine Unterweisung beendet habe, werdet Ihr die Willenskraft haben, die feinsten Ledergewänder zu fertigen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nElementarlederverarbeitung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5145] = {title = "Drachenlederverarbeitung", objective = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Drachenaug im Ödland.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe, und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDrachenlederverarbeitung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5146] = {title = "Elementarlederverarbeitung", objective = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhuf in den Arathibergen.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Elementarlederverarbeitung ist, was ich kann und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", progress = "Für die Herstellung dieser Art von lederner Rüstung bedarf es der Geduld und der Hingabe. Wenn Ihr Euch einmal auf die Elemente eingelassen habt, gibt es kein Zurück mehr. Bringt mir einen Beweis Eures Wertes und wir werden beginnen.", completion = "Ihr habt Eure Entscheidung getroffen und die Elemente akzeptieren Euch. Wenn ich meine Unterweisung beendet habe, werdet Ihr die Willenskraft haben, die feinsten Ledergewänder zu fertigen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nElementarlederverarbeitung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5147] = {title = "GESUCHT: Arnak Grimmtotem", objective = "Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Langhorn im Freiwindposten.", description = "Gesucht: Arnak Grimmtotem\n\nArnak der Ausgestoßene wird wegen ruchloser Verbrechen des Mordes und der Entführung gesucht. Ansehnliche Belohnungen winken dem, der mutig genug ist, diesen Verbrecher der Gerechtigkeit zuzuführen.\n\nArnak wurde zuletzt auf den Klippen in der Nähe des Düsterwolkengipfels gesehen. Zeigt dem Klippenbehüter Langhorn im Freiwindposten den Beweis Eurer Tat, um die Belohnung zu beanspruchen.", progress = "Habt Ihr Neuigkeiten über diesen mordlustigen Arnak Grimmtotem?", completion = "Ha! Na, das sind doch ausgezeichnete Neuigkeiten! Ich dachte langsam, er würde nie der Gerechtigkeit zugeführt werden!\n\nHier, bitte schön, &lt;Name&gt;... und vielen Dank. Die Neuigkeiten von Arnaks widerlichen Taten brachten mein Blut zum Sieden!", rewards = "Gamaschen des EbenenwächtersRüstung der inneren KraftIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5148] = {title = "Stammeslederverarbeitung", objective = "Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5149] = {title = "Pamelas Puppe", objective = "Sucht Pamelas Puppe.", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", progress = "Habt Ihr meine Puppe gefunden?", completion = "Ihr habt sie gefunden! Ihr habt meine Puppe gefunden! Oh, danke!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5150] = {title = "Dadanga ist hungrig!", objective = "Dadanga sieht zu Euch auf, während Ihr auf sie zu geht. Sie scheint auf etwas zu hoffen...\n\nSie hat wahrscheinlich Hunger!\n\nIm Krater muss irgendetwas wachsen, was die perfekte Leckerei für einen riesigen Pflanzenfresser ist. Dadanga ist ein großes Mädchen; was immer Ihr ihr bringt... es muss viel davon sein!", description = nil, progress = "Dadanga sieht zu Euch auf, während Ihr auf sie zu geht. Sie scheint auf etwas zu hoffen...\n\nSie hat wahrscheinlich Hunger!\n\nIm Krater muss irgendetwas wachsen, was die perfekte Leckerei für einen riesigen Pflanzenfresser ist. Dadanga ist ein großes Mädchen; was immer Ihr ihr bringt... es muss viel davon sein!", completion = "Als Ihr die Triebe vor sie hinlegt, scheint Dadanga erfreut zu sein.\n\nSie stubst ein kleines, braun eingepacktes Paket in Eure Richtung, quasi als Austausch für den Leckerbissen!", rewards = "Ihr bekommt:\n\nKleines, braun eingepacktes Päckchen"}
MultiLanguageQuestData['de'][5151] = {title = "Hyperkondensator-Dingsda", objective = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Lagerputzer zurück.", description = "Ich bin der einzige Überlebende des Angriffs der Zentauren auf unsere Karawane! Ein rarer, aber mächtiger Panther bewacht mein bestes Dingsda, das um seinen Hals geschlungen ist. Ha! Sogar die Zentauren erzittern in Anwesenheit dieser wilden Bestie!\n\nHier ist der Schlüssel zu dem Käfig. Sie haben alles dorthin gebracht, ihn aber in Ruhe gelassen. Erledigt diese Bestie, bringt meinen Hyperkondensator zurück und ich werde Euch belohnen.\n\nDie Überfallene Karawane befindet sich nördlich von hier.", progress = "Habt Ihr meinen Hyperkondensator?", completion = "Mein Hyperkondensator! Damit werde ich einige Zeit beschäftigt sein, bis ich herausgefunden habe, was er macht...", rewards = "Ihr bekommt:\n\nRing der Erfinderliga"}
MultiLanguageQuestData['de'][5152] = {title = "Tante Marlene", objective = "Sprecht mit Marlene, südlich der Ruinen von Andorhal.", description = "Oh, ich bin ja so einsam. Wo ist meine Familie? Tante Marlene hat mir gesagt, ich soll hier bleiben, aber dann ist sie weggegangen und nicht wiedergekommen! Und mein Papa... habt Ihr ihn gesehen?\n\nVielleicht weiß Tante Marlene, wo er ist. Sie lebt in der Nähe von Andorhal, in einem Haus im Süden. Ich glaub, es war auf einem Hügel... sie sagt, es wäre auf einem Hügel.\n\nBitte, <Name>. Wir sind doch jetzt Freunde! Könnt Ihr für mich mit meiner Tante sprechen?", progress = nil, completion = "Ihr habt Pamela gesehen? Wie geht es ihr? Ist sie am Leben?? Oh nein! Die arme Pamela! Sie war so jung und so ein fröhliches Kind...\n\nSie weiß nicht, was mit ihrem Vater geschehen ist, nicht wahr? Mit meinem Bruder Joseph...\n\nNein... sie könnte nicht verstehen, was mit Joseph geschehen ist. Und selbst wenn sie es könnte, ich habe nicht das Herz, es ihr zu sagen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5153] = {title = "Ein seltsamer Historiker", objective = "Bringt Josephs Ehering zu Chromie.", description = "Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das geht nicht. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster. Oh, er ist verloren!\n\nAber vielleicht können wir sein Schicksal ändern.\n\nDurchsucht die Gräber draußen nach Josephs Denkmal. Sein Körper ist nicht dort, da er vor Jahren zertrampelt und zerschmettert wurde, aber unter dem Denkmal liegt sein Ehering. Bringt den Ring zu Chromie...das ist eine merkwürdige Gnomin mit sehr merkwürdigen Kräften.\n\nChromie hält sich in dem zerstörten Gasthaus im nordwestlichen Teil von Andorhal auf.", progress = "Ihr habt einen guten Zeitpunkt für Euren Besuch gewählt. Ihr seid nicht zufälligerweise aus der Zukunft, oder?", completion = "Was ist das? Ein Ehering? Lasst mich mal sehen...\n\nAh! Dieser Ring steckte einst an der Hand eines großen Mannes, aber in der Vergangenheit dieses Mannes geschah eine große Tragödie.\n\nSeid Ihr hier, um ihm zu helfen? Für ihn ist jetzt alles zu spät... aber vielleicht können wir ihm in der Vergangenheit helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5154] = {title = "Die Annalen von Darroheim", objective = "Bringt die 'Annalen von Darroheim' zu Chromie in Andorhal.", description = "Um Joseph Rotpfad zu retten, müssen wir zuerst seine Vergangenheit enthüllen. Wir können sie den 'Annalen von Darroheim' entnehmen, einem Buch, das im Rathaus von Andorhal aufbewahrt wird.\n\nBringt mir dieses Buch. Wir können etwas über Josephs Schicksal erfahren...und es mit etwas Glück...ändern!", progress = "Habt Ihr das Buch gefunden, <Name>?", completion = "Sehr schön, Ihr habt es gefunden!\n\nHabt Ihr es gelesen? Wird Joseph Redpath erwähnt? Falls er erwähnt wird, dann können wir ihn vielleicht retten!\n\nAh. Die 'Annalen von Darrowshire' erzählen eine sehr beunruhigende Geschichte. Darin heißt es, dass Joseph Redpath während des Kampfes verderbt wurde und sich in die Ränge der Geißel eingereiht hat! Dann verriet er die Verteidiger von Darrowshire.\n\nDas ist ein übles Schicksal. Wir sollten versuchen, dieses Schicksal zu ändern, so das möglich ist, meint Ihr nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5155] = {title = "Streitmacht von Jaedenar", objective = "Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mooshuf im Teufelswald zurückkehrt.", description = "Wenn ich Euch in dieser Angelegenheit vertrauen soll, müsst Ihr Euch zuerst als vertrauenswürdig erweisen.\n\nIch muss sicher sein, dass Ihr ein Feind des Schattenrates seid - seine Mitglieder sind für viele böse Taten nah und fern verantwortlich.\n\nReist tiefer in den Teufelswald hinein. Im Westen werdet Ihr einen Pfad sehen, der nach Jaedenar führt. Dort schmiedet der Rat Pläne zusammen mit der Brennenden Legion.\n\nBetretet die Tiefen eines der von ihnen bewohnten verderbten Grabhügel und macht sie nieder. Kehrt zu mir zurück, wenn Ihr dies erledigt habt. Dann weiß ich, dass Ihr uns wirklich helfen wollt.", progress = nil, completion = "Gut, &lt;Name&gt;! Wenn ihre Anzahl abgenommen hat, können wir sie weiter bedrängen.\n\nWie war Euer erster Eindruck ihrer Macht? Waren sie so stark, wie ich dachte? Stärker? Oder vielleicht waren sie überhaupt keine Herausforderung für Euch... Das wäre nun wirklich eine Überraschung!\n\nWir können die Einzelheiten Eurer Taten später erörtern. Jetzt müssen wir uns auf andere Dinge konzentrieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5156] = {title = "Die Verderbnis überprüfen", objective = "Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr den Narbengrund erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Wasser gefüllt sind, kehrt zu Taronn Rotfeder im Teufelswald zurück.", description = "Im Norden, entlang der östlichen Straße im so genannten Narbengrund, liegt ein Bereich, wo im letzten großen Krieg Höllenbestien herbeigerufen wurden; die Krater zernarben immer noch das Land, so wie die Höllenbestien selbst.\n\nIch möchte gern zwei Dinge wissen. Erstens, durchstreifen immer noch entropische Elementare das Gebiet? Und zweitens, sind die Krater immer noch mit dem verderbten, stinkenden Wasser gefüllt, das sich dort vor Jahren gesammelt hat? Würdet Ihr das für mich überprüfen, <Name>? Seid aber vorsichtig, die Höllenbestien zerstören alles, was ihren Weg kreuzt.", progress = nil, completion = "Schön, dass Ihr am Leben seid, &lt;Name&gt;. Nicht schön ist, dass das Wasser immer noch existiert. Ich hatte gehofft, zumindest eine reine Wasserquelle hier im Teufelswald zu finden. Es sieht so aus, als wäre meine Suche fehlgeschlagen. Gäbe es sie, wäre der Prozess der Heilung des Landes wesentlich vereinfacht worden.\n\nIch werde mich also damit befassen müssen, die Waldkreaturen zu retten, die ich retten kann. Gleichzeitig vernichte ich die, die so verderbt wurden, dass sie nicht nur für sich selbst, sondern auch für Reisende, die durch diesen einst so mächtigen Wald ziehen, eine Gefahr sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5157] = {title = "Verderbtes Wasser sammeln", objective = "Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mooshuf im Teufelswald zurückkehrt.", description = "Tief in Jaedenar liegt die Schattenfeste - die Hauptfestung der Verderbnis und des Bösen.\n\nDer Schattenrat verfügt über Schutzzauber in Form von Kohlenpfannen, die seinen Unterschlupf umgeben. Wenn ich durch Wahrsagen noch weitere Informationen über unseren Feind herausfinden soll, müssen diese Kohlenpfannen gelöscht werden. Dann sollte ich den Rat ausspionieren und herausfinden können, wer ihn anführt.\n\nBitte, nehmt diese Feldflasche und füllt sie am Mondbrunnen im Zentrum von Jaedenar, wenn Euch dies möglich ist. Kommt dann zu mir zurück.", progress = "Wenn wir Wasser vom Mondbrunnen haben, werden wir es läutern und dazu verwenden, die Kohlenpfannen des Schutzes in der Schattenfeste zu löschen. Das würde mir ausreichend Zeit geben, um noch tiefer in die Kammern hineinzusehen und zu erkennen, wer diesen ... Kult tatsächlich anführt.\n\nIch bete, dass die Erdenmutter mit uns ist.", completion = "Das dürfte reichen, &lt;Name&gt;.\n\nJetzt müssen wir das Wasser nur noch läutern lassen, bevor wir es auf die Kohlenpfannen anwenden. Das sollte nicht schwierig sein - es ist nur eine kleine Reise dafür erforderlich.\n\nHoffentlich können wir das schnell erledigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5158] = {title = "Spirituelle Hilfe suchen", objective = "Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Wasserdeuter.", description = "Bringt das verderbte Wasser ins Brachland, <Name>. Südlich von Ratschet, versteckt entlang des Ufers, hält sich eine alte Freundin von mir auf, eine Schamanin namens Islen Wasserdeuter. Sie ist eine mächtige Schamanin, die uns helfen wird. Ihre Verbindung zu den Geistern des Wassers war immer stark. Dass unsere Aufgabe edel ist, sollte ausreichen, um sie und die Geister des Wassers dazu zu bringen, bei dieser Aufgabe zu helfen.\n\nIhr dürftet sie in einem kleinen Lager direkt am Wasser finden. Ach ja, <Name>, ignoriert die Piraten...sie sind nur eine Plage und keine Bedrohung für Euch.", progress = "Ich spüre, dass Ihr nicht nur ein einfacher Reisender seid, der den Weg nach Ratchet sucht. Kommt, setzt Euch und ruht Euch in unserem Lager aus. Sprecht mit mir, wenn Ihr bereit seid.", completion = "Ah, Ihr müsst das Wasser aus diesem Mondbrunnen säubern lassen. Es erscheint edel genug, die Kräfte der Bosheit im Teufelswald stoppen zu wollen, aber die Entscheidung liegt nicht bei mir, ob dieses Wasser geläutert wird. Ich werde die Geister des Wassers fragen - es wird an ihnen liegen zu entscheiden, ob der Grund gerecht ist.\n\nGebt mir einen Augenblick und ich werde ihnen von Eurer Bitte berichten. Ich hoffe, dass sie Eurem Anliegen genauso wohlwollend gegenüberstehen wie ich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5159] = {title = "Gesäubertes Wasser wird zum Teufelswald gebracht", objective = "Bringt das geläuterte Mondbrunnenwasser zu Greta Mooshuf im Teufelswald.", description = "Dankt den Geistern, <Name>. Sie sind diejenigen, die Euch zu Hilfe kamen, nicht ich.\n\nIch gebe Euch nun dieses geläuterte Wasser. Richtet Greta bitte meine Grüße und meine besten Wünsche aus. Sie kämpft mit etwas viel Größerem als die meisten von uns... wie sie sicherlich bald herausfinden wird.\n\nDer Schattenrat ist keine Kraft, die man unterschätzen sollte, <Name>. Vergesst das nicht.\n\nGeht jetzt. Nehmt das Wasser und kehrt zu Greta zurück.", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt, <Name>. Gut. Habt Ihr Islen im Brachland gefunden? Oder müssen wir einen anderen Weg finden, unsere Ziele zu erreichen?", completion = "Das sollte mehr als genug Wasser für unsere Zwecke sein.\n\nIch freue mich zu hören, dass Islen uns helfen konnte. Ihre Kraft mit den Wassergeistern war immer stark. Außerdem ist sie weise und es kommt selten vor, dass die Geister ihre Absichten nicht gutheißen. Die Tatsache, dass beide unsere Aufgabe abgesegnet haben, gibt mir die Hoffnung, dass wir auf dem rechten Weg sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5160] = {title = "Die oberste Beschützerin", objective = "Begebt Euch nach Winterquell und sucht Haleh. Gebt ihr Awbees Schuppe.", description = "Reist nach Kalimdor, <Volk>. Unser Schwarm ist in der frostigen Landschaft von Winterquell zu Hause. Wenn Ihr Winterquell erreicht habt, sucht die Höhlen von Mazthoril.\n\nAuf den eisigen Böden von Mazthoril werdet ihr Kobaltrunen finden. Haltet eine meiner Schuppen in der Hand und stellt Euch auf eine Rune. Ihr werdet dann zu Haleh transportiert, unserer obersten Beschützerin.\n\nGebt ihr die Schuppe, damit sie weissagen kann, was ich hier an diesem verlorenen Ort gesehen und gefühlt habe.", progress = "Es ist schön, Euch zu sehen, <Name>.", completion = "Die Aspekte bestehen darauf, dass wir uns aus den Angelegenheiten der Sterblichen heraushalten. In dieser Welt ist das aber nicht immer möglich - besonders, wenn einer der Unseren solche Erlasse verächtlich missachtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5161] = {title = "Der Zorn des blauen Drachenschwarms", objective = "Sprecht mit Haleh, wenn Ihr weitermachen wollt.", description = "Wir verstehen, was die verfluchte Brut von Todesschwinge zu tun versucht, und wir wissen, dass das unterbunden werden muss.\n\nDurch den Schutz, den der Schwarzfels Nefarian bietet, wird es für uns immer schwieriger zu intervenieren.\n\nWir können aber Euch, sterbliches Wesen, ermächtigen - solltet Ihr Euch dafür entscheiden.\n\nDer Weg, der vor Euch liegt, ist voller Gefahren. Ihr müsst Euch entscheiden, ob Ihr unsere Hilfe annehmt. Denkt darüber nach und sprecht erneut mit mir, wenn Ihr eine Entscheidung getroffen habt.", progress = nil, completion = "So soll es geschehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5162] = {title = "Der Zorn des blauen Drachenschwarms", objective = "Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal.", description = "Das Arkane kontrolliere ich und das Arkane wird Euch zu Eurem nächsten Ziel senden.\n\nWenn Ihr bereit seid, wird die Reise beginnen. Ihr werdet Euch zu den Pestländern begeben und mit Jeziba sprechen.\n\nEr ist ein Sterblicher, so weise wie die Uralten und so geduldig wie die unbewegliche Erde. Sucht ihn in Andorhal.", progress = nil, completion = "Ich bin Jeziba, vielen bekannt als der Bildhauer. Was ich forme, sind aber keine Statuen, sondern Helden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5163] = {title = "Sind wir endlich da, Yeti?", objective = "Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:\n\nLegacki in der Ewigen Warte (Winterquell)\nSprinkel in Gadgetzan (Tanaris)\nQuixxil in Marschalls Zuflucht (Krater von Un'Goro)\n\nWenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.", description = "Es ist alles bereit, <Name>!\n\nAlso, ich habe meinen Freunden bereits eine Nachricht geschickt und ihnen gesagt, dass ich eine Überraschung für sie habe. Und hier kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Ihr müsst sie überraschen, indem Ihr jeden meiner Freunde aufsucht, den Yeti einschaltet und zu ihnen schickt.\n\nNachdem Ihr ihn Legacki in der Ewigen Warte, Sprinkel in Gadgetzan und Quixxil in Marschalls Zuflucht gezeigt habt, kehrt zurück und berichtet mir, was geschehen ist!\n\nBitte bringt mir meinen Yeti dann wieder zurück.", progress = "Ich kann es gar nicht erwarten zu hören, wie meine Freunde reagieren!\n\nDas werden sie niemals erwarten!", completion = "Ha! Die werden es sich jetzt zweimal überlegen, bevor sie sich wieder über meine Ideen lustig machen!\n\nIch danke Euch für Eure Hilfe, &lt;Name&gt;. Ohne Euch hätte ich nicht so viel Spaß haben können!", rewards = "Ihr bekommt:\n\nMechanischer Yeti"}
MultiLanguageQuestData['de'][5164] = {title = "Verzeichnis der Abtrünnigen", objective = "Lest das 'Verzeichnis der Abtrünnigen'.", description = "Haleh hätte kein feineres Instrument der Gerechtigkeit wählen können. Lest das 'Verzeichnis der Abtrünnigen' und werdet erleuchtet.\n\nFalls Ihr durchhaltet... falls Ihr tut, was von Euch verlangt wurde... falls Ihr überlebt... werdet Ihr ein Held sein.", progress = nil, completion = "Hunderte und Hunderte von Seiten voller Textfetzen und Symbole bilden den Großteil dieses Buches.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5165] = {title = "Übergießen der Flammen des Schutzes", objective = "Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser und kehrt danach zu Greta Mooshuf im Smaragdrefugium zurück.", description = "Jetzt müsst Ihr nach Jaedenar zurückkehren. Die Kohlenpfannen sind wahrscheinlich über die ganze Schattenfeste verteilt. Übergießt jede ihrer Flammen, und der Schutz, den der Rat eingerichtet hat, wird zumindest für eine kurze Zeit erlöschen. Ich werde warten, dass dies geschieht. Wenn es so weit ist, werde ich einen tiefen Blick in die Feste werfen und versuchen herauszufinden, wer der Kopf dieser Bestie ist. Dann, und nur dann, werden wir sehen, ob wir sie direkt angreifen.", progress = nil, completion = "Ich konnte Euch durch meine Zauber sehen, als die Flamme der letzten Kohlenpfanne erstarb. Gut gemacht, &lt;Name&gt;.\n\nIch habe einige Dinge in Erfahrung gebracht, bevor die Hexenmeister des Schattenrates ihre Zauber erneut wirken konnten. Hoffentlich wird es ausreichen.\n\nNun denn, ruht Euch aus. Ich werde Euch dann berichten, was ich erfahren habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5166] = {title = "Brustplatte des chromatischen Drachenschwarms", objective = "Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischen Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n10 ausgefranste Monstrositätenstickereien.", description = "Das Schmieden einer mächtigen Brustplatte zum Schutz gegen die unerbittlichen Angriffe des chromatischen Drachenschwarms ist eigentlich recht ironisch.\n\nDie Schuppen der Bestien, die wir bekämpfen, müssen an einen makellosen Knochenpanzer eines alten chromatischen Drachen oder Großdrachen genäht werden. Derzeit ist nicht bekannt, ob es überhaupt welche gibt, und wir sollten hoffen, dass es niemals welche geben wird.\n\nUnd dann ist da noch die vielleicht schwierigste aller Komponenten: das Blut von Helden.\n\nDer Bildhauer muss diese Kreation dann schmieden.", progress = "Ihr habt weise gewählt, <Volk>.", completion = "Habt Ihr noch immer nicht verstanden? Die Reise war das Ziel. Könnt Ihr nicht die Narben des Kampfes fühlen? Den Schmerz, den Ihr ertragen habt?\n\nDa Ihr die Tortur überlebt habt, seid Ihr nun ein mächtigeres Wesen. Viel mächtiger. Diese Brustplatte ist nur ein Spiegelbild Eurer eigenen angeborenen Fähigkeiten.", rewards = "Ihr bekommt:\n\nBrustplatte des chromatischen Drachenschwarms"}
MultiLanguageQuestData['de'][5167] = {title = "Beinplatten des chromatischen Widersetzers", objective = "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n5 Häute des Schattens.", description = "Der Knochenpanzer eines erwachsenen chromatischen Drachen wird benötigt, um die Grundlage der Gamaschen zu fertigen. Glänzende chromatische Schuppen werden dann auf das Grundgerüst aufgebracht und im Blut der Helden verzaubert. Schließlich muss noch die geschmeidige Haut des Schattens auf die inneren Schienbeinschützer aufgebracht werden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Beinschützer des chromatischen WidersetzersBeinplatten des chromatischen WidersetzersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5168] = {title = "Helden von Darroheim", objective = "Bringt Davils Buchband und Rotpfads Schild zu Carlin Rotpfad.", description = "Die Helden von Darroheim haben einen Platz in meinem Herzen und das Buch, das Ihr mir gebracht habt, die 'Annalen von Darroheim', erzählt ihre Geschichten.\n\nEs berichtet von dem Paladin Davil Lichterschein und davon, wie der Kreuzzug seinen Buchband zum Rathaus von Herdweiler brachte.\n\nEinige Passagen handeln auch von meinem Bruder, Hauptmann Rotpfad. Nach seinem Verrat wurde sein Schild zerschmettert und weggeworfen und liegt nun am unwahrscheinlichsten aller Orte - in der Nähe von Gahrrons Trauerfeld.\n\nSammelt diese Relikte, <Name>. Denn Verhängnis und Tragik umgeben sie.", progress = "Habt Ihr die Relikte, <Name>?", completion = "Ihr habt den Buchband und den Schild!\n\nIhre Geschichte ist mit der Geschichte von Darrowshire verbunden und irgendwie weiß ich, dass das Schicksal sie wieder zusammenführen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5181] = {title = "Bösewichte von Darroheim", objective = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Rotpfad in der Kapelle des Hoffnungsvollen Lichts.", description = "Die 'Annalen von Darroheim' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghulfürst Horgus der Verheerer von Kräften der Allianz während der Schlacht vernichtet wurde. Seine Leiche wurde in einen See geworfen, nordwestlich von Corins Kreuzung, und sein Schädel ist noch dort.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert wurde zertrümmert und ging verloren. Es liegt auf dem Grund der Schlucht westlich von Corins Kreuzung.\n\nBringt diese Gegenstände zurück, <Name>. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", progress = "Habt Ihr den Schädel und das Schwert gefunden, <Name>?", completion = "Ihr habt sie gefunden! Gut gemacht, &lt;Name&gt;! Diese Relikte enthalten eine Macht, die ich nicht ganz verstehe, eine Macht, die Ihr eines Tages beherrschen werdet.\n\nSie wecken aber auch dunkle Erinnerungen in meinen Gedanken, Erinnerungen an Tod und Verrat und an die letzte Nacht von Darrowshire...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5201] = {title = "Eindringlinge der Winterfelle", objective = "Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt.", description = "Meine Anwesenheit bleibt den Meisten verborgen, <Name>. Es gibt aber eine Störung, die hier in Winterquell fest verankert zu sein scheint: die Winterfellfurbolgs.\n\nObwohl ich die Furbolgs nie direkt angegriffen habe, scheinen sie wahnsinnig zu sein, alles, was in ihrem Weg steht, scheint sie zu ängstigen. Ich habe beobachtet, wie sie zahllose Kreaturen erschlagen haben, die das Pech hatten, einfach zur falschen Zeit am falschen Ort zu sein.\n\nIch bin ihrer Einmischungen müde... helft mir bitte, indem Ihr sie bekämpft. Erschlagt die Furbolgs und haltet sie vom Frostsäblerfelsen fern.", progress = nil, completion = "Ich bin erleichtert zu hören, dass wir uns zumindest für kurze Zeit über die Eindringlinge der Winterfelle keine Sorgen machen müssen.\n\nIhr beginnt Beharrlichkeit zu zeigen, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][5202] = {title = "Ein merkwürdiger roter Schlüssel", objective = "Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird.", description = "Der kleine rote Schlüssel scheint aus einem Knochenmaterial gemacht zu sein. Er liegt schwer in Eurer Hand, wirkt aber trotzdem sehr zerbrechlich. Warum sollte ein Mitglied des Schattenrats solch ein Ding haben? Vielleicht gibt es etwas in Jaedenar, was dieser merkwürdige Schlüssel aufschließen kann.", progress = "Ich beginne mich zu fragen, ob ich diesem Käfig jemals entkommen werde.\n\nEs ist nur eine Frage der Zeit, bevor sie mich irgendeinem der Dämonen opfern, die sie anbeten. Diese Monster!", completion = "Der Schlüssel, Ihr habt ihn gefunden! Bitte, gebt ihn mir, damit ich endlich entkommen kann!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5203] = {title = "Rettung aus Jaedenar", objective = "Bringt Arko'narin dorthin, wo Lichtschmied und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Mondsichel im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist.", description = "Aber so sehr es mich auch schmerzt, es gibt eine Sache, die zuerst erledigt werden muss. Ich muss Treys Schwert Lichtschmied finden und aus der Schattenfeste entkommen, um meinen Vorgesetzten zu berichten, was hier geschieht. Könntet Ihr mir helfen, <Name>?\n\nUnsere Ausrüstung ist nicht weit von hier und Ihr habt bereits bewiesen, dass Ihr den Weg an die Spitze überleben könnt.\n\nNachdem wir entkommen sind, werde ich nach Darnassus gehen, und Euch würde ich bitten, meine Freundin Jessir in der Nähe der Grenze zum Eschental aufzusuchen. Sie sollte sich eigentlich im Lager des Smaragdkreises hier in der Nähe mit uns treffen.\n\nWas sagt Ihr dazu, <Name>? Würdet Ihr mir nochmals helfen?", progress = nil, completion = "Ihr wart es, der Arko bei der Flucht geholfen hat? Ich bin ja so froh, dass Ihr mich gefunden habt. Sie kam vor nicht allzu langer Zeit auf ihrem Weg nach Darnassus hier vorbei. Sie hatte Lightforge im Schlepptau und nahm sich nicht einmal die Zeit, um mit den Druiden zu sprechen, um sich heilen zu lassen. Sie sagte, es wäre viel zu dringend.\n\nAber sie berichtete mir von Eurer Begegnung mit dem Geist von Trey. Was für ein schreckliches Schicksal für einen Ritter der Silberhand. Sie zeigte es nicht, aber ich weiß, dass der Gedanke, einen ihrer engsten Freund zu verlieren, sie im Inneren zerreißt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5204] = {title = "Vergeltung des Lichts", objective = "Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lichtschmied sucht.", description = "Sie möchte so tun, als ob es ihr gut ginge. Sie möchte gern, dass ich denke, sie sei stark genug, um mit alledem selbst fertigzuwerden, aber ich weiß es besser. Treys Tod und zu hören, welche Folter er erdulden musste, wird sie lange Zeit verfolgen und es gibt nichts, was wir tun können, um das zu stoppen. Aber wir können ihr ein wenig Frieden geben!\n\n<Name>, kehrt zur Schattenfeste zurück, tötet Treys Folterer und sucht seine Überreste. Es gibt keinen Grund, dass wir nicht all diese Dinge zu Ende bringen können, während Arko'narin auf ihre eigene Art trauert.", progress = "Ihr untersucht den Körper und es gibt keinen Zweifel, dass dies die Überreste des Ritters der Silberhand, Trey Lightforge, sind. Einen Moment lang denkt Ihr an Arko'narin und fragt Euch, ob Euch jemals in Eurem Leben jemand so viel bedeutet hat, wie dieser Mann der gefangenen Nachtelfin bedeutete, der Ihr kürzlich bei der Flucht aus der Schattenfeste geholfen habt.\n\nNachdem Ihr in einem weiteren Augenblick Eure Gedanken gesammelt habt, wisst Ihr, dass Ihr die Überreste des Paladins nicht zu Jessir zurückbringen könnt, ohne zuvor seinen Folterknecht zu töten.", completion = "Ihr sammelt die Überreste des Paladins so sorgfältig wie möglich ein und erinnert Euch daran, dass zumindest sein Geist von jeglichem Schmerz oder Leiden erlöst wurde, das über ihn gebracht worden war.", rewards = "Ihr bekommt:\n\nÜberreste von Trey Lichtschmied"}
MultiLanguageQuestData['de'][5206] = {title = "Marodeure von Darroheim", objective = "Bringt 5 widerhallende Schädel und den Mystikerkristall zu Carlin Rotpfad in den östlichen Pestländern.", description = "Chromie sagte, dass die von Euch gesammelten Relikte Reagenzien für einen mächtigen Zauber seien und dass noch eines fehle: Schädel von Angehörigen der Geißel, die an der Schlacht von Darroheim teilnahmen.\n\nNehmt diesen Kristall und jagt um ihrer Schädel willen Champions der Geißel. Der Kristall ist verzaubert: Wenn ein Held an der Schlacht teilnahm, dann wird er, wenn Ihr ihn über dessen Schädel haltet, widerhallen. Bringt mir diese widerhallenden Schädel.\n\nGeht, <Name>. Ihr könnt Champions der Geißel im Giftigen Tal im Norden und im Fungustal im Westen finden.", progress = "Habt Ihr die Schädel? Chromie sagte, sie wären äußerst wichtig für ihren Zauber, und dieser Zauber gäbe uns die Chance, Darrowshire zu retten.", completion = "Ihr habt sie gefunden! Großartig!\n\nWenn ich auch nicht genau weiß, inwiefern sie uns helfen werden, so spüre ich doch ihre Macht und fühle es in meinen Knochen, dass sie irgendwie mit meinem Heimatdorf Darrowshire verbunden sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5210] = {title = "Bruder Carlin", objective = "Bringt die erweiterten 'Annalen von Darroheim' zu Carlin Rotpfad in den Östlichen Pestländern.", description = "Die 'Annalen von Darroheim' haben mithilfe meiner Magie an ihrem Ende Seiten hinzugewonnen, und nun erstreckt sich die Geschichte auch über den Kampf hinaus. Eine der zusätzlichen Passagen berichtet von einem anderen Rotpfad, Carlin, der Josephs Verrat überlebt hat. Carlin befindet sich jetzt in den Pestländern im Osten, bei der Kapelle des Hoffnungsvollen Lichts.\n\nNehmt das Buch und sprecht mit ihm.", progress = "Ihr kommt aus dem Westen? Wie ergeht es dem Rest von Lordaeron? Ich weiß, dass Andorhal verloren ist, aber hat die Geißel schon Tirisfal erreicht?", completion = "Was ist mit diesem Buch? 'Die Annalen von Darrowshire'? Das war mein Heim vor dem Krieg... mein Heim vor der Schlacht, die es zerstörte! Warum habt Ihr mir dieses Buch gebracht?\n\nAber seht doch nur hier! Am Ende sind Seiten, die Geschichten von den Tagen nach der Schlacht erzählen! Hier ist eine Passage über mich! Und eine über meinen Bruder Joseph! Ist dieses Buch echt?\n\nWir müssen die Wahrheit erfahren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5211] = {title = "Verteidiger von Darroheim", objective = "Befreit 15 Geister von Darroheim und kehrt dann zu Carlin Rotpfad zurück.", description = "Viele der Verteidiger fielen in der Schlacht von Darroheim. Und viele ziehen erneut umher als grässliche Diener der Geißel! Sucht diese armen Seelen und beendet ihr Elend!\n\nJagt Menschenfresserghule, jammernde Ghule und kranke Schinder. Viele dieser Scheusale waren einst gute Leute aus Darroheim und die Zerstörung ihrer Formen wird ihre Seelen befreien.\n\nIhr werdet sie im Pestwald und bei Corins Kreuzung finden, ebenso wie in anderen Geißelfestungen in den Östlichen Pestländern.", progress = "Die armen Verteidiger von Darrowshire rufen in meinen Träumen nach mir, <Name>. Ihr müsst sie befreien!", completion = "Es ist gut zu hören, dass Ihr die gequälten Seelen meiner Brüder gefunden und befreit habt. Mein Herz wird weniger weinen, da es weiß, dass zumindest einige der Verteidiger von Darrowshire nicht mehr länger in der widerlichen Dienerschaft der Geißel gefangen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5212] = {title = "Das Fleisch lügt nicht", objective = "Sammelt 10 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Moppelzink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", description = "Die Apotheker der Verlassenen sind nicht die einzigen Wesen auf dieser Welt, die in den Wissenschaften bewandert sind.\n\nIch erforsche die Seuche schon seit Jahren, <Volk>. Wir dachten zuerst, dass die Stärke der Seuche langsam schwand, aber was ich hier in den Pestländern entdeckt habe, ist alarmierend. Die Kraft der Seuche scheint zu wachsen!\n\nIch muss mehr Tests durchführen! Die mächtigste Quelle der Seuche ist das besudelte Fleisch der vor Kurzem Infizierten. Begebt Euch nach Stratholme und bringt mir Proben, <Name>.", progress = "Manche behaupten, dass ich mir zu viele Sorgen mache - ihnen sage ich: 'Ihr macht euch nicht genug Sorgen!'", completion = "Etwas hat sich in der chemischen Struktur der aktiven Wirkstoffe der Seuche verändert. Es sind mehr Daten erforderlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5213] = {title = "Der aktive Wirkstoff", objective = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Moppelzink zurück.", description = "Ihr müsst tiefer nach Stratholme vordringen, <Name>.\n\nHinter den ersten Toren werdet Ihr die Ziggurats finden. Wir wissen, dass die Geißel große Macht aus diesen Gebäuden zieht. Durchsucht die Ziggurats und kehrt mit den Informationen zurück, die Ihr aufspürt.", progress = "Wir stehen kurz davor herauszufinden, was dieser neue aktive Wirkstoff der Seuche sein kann!", completion = "Erstaunlich! Es wird Monate dauern, das zu sezieren und zu analysieren. Die Argentumdämmerung dankt Euch für Eure Bemühungen, &lt;Name&gt;.\n\nMit unserem Segen, dürft ihr nun zwischen diesem Siegel der Dämmerung und dieser Rune der Dämmerung wählen. Ihr könnt diese Insignien anstelle einer Anstecknadel der Argentumdämmerung benutzen, um in unserem Namen Geißelsteine zu sammeln. Sprecht mich im Falle eines Verlusts einfach an und ich werde Euch einen Ersatz beschaffen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegel der DämmerungRune der Dämmerung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5214] = {title = "Der große Ezra Grimm", objective = "Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", description = "Schrecklich... was mit Ezra geschehen ist. Wisst Ihr, die Stadt wurde geplündert und Ezra wollte seine wertvollen Dinge nicht zurücklassen. Das Letzte, woran ich mich erinnere, ist, dass er sagte: 'Ich verbrenne lieber alles, bevor ich zulasse, dass sie irgendwas in ihre verdammten, schmutzigen Pfoten kriegen!'\n\nIch rauche ja auch ganz gern mal eine Zigarre, aber ich bin kein Idiot. Ich habe Ezra und sein reizendes Geschäft an dem Tag verlassen. Ich nehme an, dass er in den Flammen unterging, aber wenn es eine Chance gibt, dass auch nur ein Kasten seines berühmten Tabaks noch intakt ist...\n\nWas sagt Ihr dazu, <Name>? Sucht Ihr einen Kasten für den alten Smokey?", progress = "Ich halte das nicht aus, <Name>! Ihr müsst mir helfen! Ich sterbe!", completion = "Oh süße, süße Zigarre, wie ich dich vermisst habe...", rewards = "Ihr bekommt:\n\nSmokeys Feuerzeug"}
MultiLanguageQuestData['de'][5215] = {title = "Die Geißelkessel", objective = "Sprecht mit der Hohepriesterin MacDonnell an der Zugwindspitze in den Westlichen Pestländern.", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier hier im Westen und vier weitere versteckt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Hohepriesterin MacDonnell, wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", progress = nil, completion = "Möge die Macht des Lichts in diesen dunklen Zeiten auf Euch scheinen, &lt;Klasse&gt;. Ich bin erfreut, als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel zu dienen.\n\nUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel sicherstellen, die es in den Westlichen Pestländern gibt.\n\nMacht Euch bereit, oh Held, ein glorreicher Kampf gegen die niederträchtige Geißel steht Euch bevor!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5216] = {title = "Ziel: Teufelssteinfeld", objective = "Geht zum Teufelssteinfeld in den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Von den vier Kesseln, die sich hier im Westen befinden, ist derjenige, der sich auf dem Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Wir glauben, dass er einen Schlüssel hat, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel, den Ihr dem Kessellord Gallenschlund abgenommen habt, passt perfekt zu der Zugangsklappe. Ein fauliger Geruch entweicht der geöffneten Klappe, während eine unbekannte Mischung aus konzentrierten Substanzen im Kessel umherwirbelt.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5217] = {title = "Rückkehr zum Zugwindlager", objective = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer.", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftiges Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell am Zugwindlager zurückzukehren, um die Mission abzuschließen.", progress = "Willkommen in der relativen Sicherheit der Chillwindspitze, <Name>. Welche Fortschritte könnt Ihr bezüglich der Kessel berichten?", completion = "Gut gemacht &lt;Name&gt;... Alchimist Arbington sollte in der Lage zu sein, dies umgehend zu analysieren und ein Gegenmittel zu entwickeln, das wir dann in den Kessel geben. Wenn wir genug davon in die Luft pumpen können, sind wir vielleicht in der Lage, alle hier präsenten Mitglieder der Geißel zu schwächen.\n\nDiese Aktion wird sich ohne Zweifel über längere Zeit hinziehen; wir müssen der Mischung in diesen Kesseln ständig unsere Reagenzien hinzufügen. Wenn wir das aufrechterhalten können, werden wir einen großen Vorteil über die Geißel haben, wenn die Zeit für den Kampf gekommen ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5218] = {title = "Der Kessel des Teufelssteinfelds", objective = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", description = nil, progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen.", rewards = nil}
MultiLanguageQuestData['de'][5219] = {title = "Ziel: Dalsons Tränenfeld", objective = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Tja, wir werden heute keine Tränen vergießen, wenn wir der Geißel in die Quere kommen und sie an ihren eigenen Dämpfen ersticken lassen!\n\nBegebt Euch zu Dalsons Tränenfeld, ziemlich genau nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr an den Kessel gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der makabre Schlüssel des Kessellords gleitet problemlos in ein Schlüsselloch und verschwindet dann, wodurch Ihr permanenten Zugriff darauf habt. Kunstlose, zähflüssige Sekrete pulsieren durch die geschwungenen Röhren im Unterbau des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5220] = {title = "Rückkehr zum Zugwindlager", objective = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer.", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell am Zugwindlager zurückzukehren, um die Mission abzuschließen.", progress = "Wir wissen, dass sich in jedem Kessel ein anderes Gemisch von Reagenzien befindet, mit denen das Seuchen verursachende Toxin erzeugt wird. Dementsprechend müssen wir auch ein Gegenmittel entwickeln, das für jeden Kessel einzigartig ist. Eure Probe von Dalsons Tränenfeld wird der Schlüssel sein, um den einzigartigen Reagenzienbedarf für diesen Kessel zu bestimmen.", completion = "Ah, darin ist mehr als genug für die Untersuchungen. Gut gemacht, &lt;Name&gt;!\n\nJetzt liegt der nächste Schritt bei uns. Wir werden eine Liste von Reagenzien erstellen, die in Kombination mit dem, was sich bereits in dem Kessel befindet, als Gegenmittel wirken.\n\nWir können dies allerdings nur umsetzen, indem die Reagenzien direkt in den Kessel gegeben werden. Alchimist Arbington dürfte weitere Informationen darüber haben, also sprecht so bald wie möglich mit ihm.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5221] = {title = "Der Kessel von Dalsons Tränenfeld", objective = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", description = nil, progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen.", rewards = nil}
MultiLanguageQuestData['de'][5222] = {title = "Ziel: Das Trostlose Feld", objective = "Begebt Euch zum Trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das Trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des Trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, <Name>!", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords entriegelt die Zugangsklappe zu diesem Kessel und verschwindet dann, ähnlich wie die anderen Schlüssel für die vorherigen beiden Kessel, um die Ihr Euch gekümmert habt. Eine faulig riechende Substanz brodelt heftig unter der Plattform des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5223] = {title = "Rückkehr zum Zugwindlager", objective = "Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer.", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell am Zugwindlager zurückzukehren, um die Mission abzuschließen.", progress = "Wenn wir erst die Probe vom Kessel des trostlosen Felds analysiert haben, wird sie uns einen dritten Weg bieten, um die Geißel mit einem verheerenden Gegenmittel zu schlagen!", completion = "Wieder habt Ihr eine Mission hervorragend durchgeführt, &lt;Name&gt;! Damit stehen uns drei Kessel zur Verfügung, die wir gegen die Geißel einsetzen können. Wenn die nekromantische Herrschaft von Kel'Thuzad über diese Länder nicht so stark wäre, wie sie es derzeit ist, würde ich sagen, dass Ihr sie ganz erledigt habt.\n\nAlchimist Arbington wird einen Bericht darüber anfertigen, was dieser Kessel - genau wie jeder andere von uns veränderte Kessel - benötigt, um unser Gegenmittel gegen die Seuche einzusetzen. Damit ist die Zeit gekommen, den letzten Kessel im Westen unter unseren Einfluss zu bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5224] = {title = "Der Kessel des trostlosen Felds", objective = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", description = nil, progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen.", rewards = nil}
MultiLanguageQuestData['de'][5225] = {title = "Ziel: Gahrrons Trauerfeld", objective = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, <Name>.\n\nGahrrons Trauerfeld liegt von unserer Position hier aus im Nordosten, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Möge das Licht Euch bei dieser gefährlichen Mission schützen, <Klasse>.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords Rachseele löst sich auf, als er das Schloss der Zugangsklappe im Fundament der Kesselplattform berührt. Im Inneren erklingt ein leicht rasselndes Geräusch. Als die Zugangsklappe aufschwingt, enthüllt sie weitere zähflüssige Toxine im System des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5226] = {title = "Rückkehr zum Zugwindlager", objective = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer.", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell am Zugwindlager zurückzukehren, um die Mission abzuschließen.", progress = "Gahrrons Trauerfeld beherbergt den letzten Kessel hier im Westen, zu dem wir Zugang brauchen. Wenn wir eine Probe der Seuche haben, die er ausspeit, können wir unsere Reagenzien durch vier separate Gefäße in die Umgebung entlassen. Die Geißel wird es schwer haben, um uns von allen vieren fern zu halten, selbst mit der Kraft von Kel'Thuzad hinter sich.", completion = "Herzlichen Glückwunsch, &lt;Name&gt;, Ihr habt den letzten Kessel für uns entriegelt! Alchimist Arbington wird bald wissen, welche Reagenzien für die Mischung dieses Kessels erforderlich sind.\n\nWas Euch angeht, so bin ich sicher, dass Kommandant Valorfist Euch persönlich für die Hilfe, die Ihr uns habt angedeihen lassen, danken will. Ohne Euch wäre unser Kampf gegen die Geißel nahezu unmöglich gewesen. Danke, oh Held!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5227] = {title = "Der Kessel von Gahrrons Trauerfeld", objective = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", description = nil, progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen.", rewards = nil}
MultiLanguageQuestData['de'][5228] = {title = "Die Geißelkessel", objective = "Sprecht mit der Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier im Westen und vier weitere verschanzt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Schattenpriesterin Vandis wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", progress = nil, completion = "Aus den Schatten, Bruder &lt;Volk&gt;, entbiete ich meine Grüße. Ich werde als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel dienen.\n\nUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel hier in den Westlichen Pestländern sicherstellen.\n\nDie Zeit ist gekommen, dass Ihr den Sturm gegen die Geißel anführt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5229] = {title = "Ziel: Teufelssteinfeld", objective = "Geht zum Teufelssteinfeld in den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Von den vier Kesseln, die sich in den Westlichen Pestländern befinden, ist derjenige, der sich im Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, direkt östlich von hier und nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Er hat einen Schlüssel bei sich, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel, den Ihr dem Kessellord Gallenschlund abgenommen habt, passt perfekt zu der Zugangsklappe, verschwindet aber, nachdem Ihr ihn benutzt habt. Ihr habt aber so ein Gefühl, dass Ihr den Zugang jetzt auch ohne einen Schlüssel öffnen könnt. Ein fauliger Geruch entweicht der geöffneten Klappe, während eine unbekannte Mischung aus konzentrierten Substanzen im Kessel umherwirbelt.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5230] = {title = "Rückkehr zum Bollwerk", objective = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftigen Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Willkommen in der relativen Sicherheit des Bollwerks, <Name>. Welche Fortschritte könnt Ihr bezüglich der Kessel berichten?", completion = "Gut gemacht &lt;Name&gt; - Apotheker Dithers sollte in der Lage sein, dies umgehend zu analysieren und ein Gegenmittel zu entwickeln, das wir dann in den Kessel geben. Wenn wir genug davon in die Luft pumpen können, sind wir vielleicht in der Lage, alle hier präsenten Mitglieder der Geißel zu schwächen.\n\nDiese Aktion wird sich ohne Zweifel über längere Zeit hinziehen; wir müssen der Mischung in diesen Kesseln ständig unsere Reagenzien hinzufügen. Wenn wir das aufrechterhalten können, werden wir einen großen Vorteil gegenüber der Geißel haben, wenn die Zeit für den Kampf gekommen ist!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMachtwort: Seelenstärke\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5231] = {title = "Ziel: Dalsons Tränenfeld", objective = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Heute werden keine Tränen vergossen, <Klasse>; wir müssen bei diesem Kessel zuschlagen und Zugang zu ihm erlangen!\n\nBegebt Euch zu Dalsons Tränenfeld, fast direkt nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr ans Innere des Kessels gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Skelettschlüssel des Kessellords gleitet problemlos in ein Schlüsselloch und verschwindet dann, wodurch Ihr permanenten Zugriff darauf habt. Kunstlose, zähflüssige Sekrete pulsieren durch die geschwungenen Röhren im Unterbau des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5232] = {title = "Rückkehr zum Bollwerk", objective = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Wir wissen, dass sich in jedem Kessel ein anderes Gemisch von Reagenzien befindet, mit denen das Seuchen verursachende Toxin erzeugt wird. Dementsprechend müssen wir auch ein Gegenmittel entwickeln, das für jeden Kessel einzigartig ist. Eure Probe von Dalsons Tränenfeld wird der Schlüssel sein, um den einzigartigen Reagenzienbedarf für diesen Kessel zu bestimmen.", completion = "Ah, darin ist mehr als genug für die Untersuchungen. Gut gemacht, &lt;Name&gt;!\n\nJetzt liegt der nächste Schritt bei uns. Wir werden eine Liste von Reagenzien erstellen, die in Kombination mit dem, was sich bereits in dem Kessel befindet, als Gegenmittel wirken.\n\nWir können dies allerdings nur umsetzen, indem die Reagenzien direkt in den Kessel gegeben werden. Apotheker Dithers dürfte weitere Informationen darüber haben, also sprecht mit ihm, sobald es Euch beliebt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMachtwort: Seelenstärke\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5233] = {title = "Ziel: Das Trostlose Feld", objective = "Begebt Euch zum Trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das Trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des Trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, <Name>!", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords entriegelt die Zugangsklappe zu diesem Kessel und verschwindet dann, ähnlich wie die anderen Schlüssel für die vorherigen Kessel, um die Ihr Euch gekümmert habt. Eine faulig riechende Substanz brodelt heftig unter der Plattform des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5234] = {title = "Rückkehr zum Bollwerk", objective = "Bringt die gefüllte Flasche: Das Trostlose Feld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Wenn wir erst die Probe vom Kessel des trostlosen Felds analysiert haben, wird sie uns einen dritten Weg bieten, um die Geißel mit einem verheerenden Gegenmittel zu schlagen!", completion = "Wieder habt Ihr eine Mission hervorragend durchgeführt, &lt;Name&gt;! Damit stehen uns drei Kessel zur Verfügung, die wir gegen die Geißel einsetzen können. Wenn die nekromantische Herrschaft von Kel'Thuzad über diese Länder nicht so stark wäre, wie sie es derzeit ist, würde ich sagen, dass Ihr sie ganz erledigt habt.\n\nApotheker Dithers wird einen Bericht darüber anfertigen, was dieser Kessel - genau wie jeder andere von uns veränderte Kessel - benötigt, um unser Gegenmittel gegen die Seuche einzusetzen. Damit ist die Zeit gekommen, den letzten Kessel im Westen unter unseren Einfluss zu bringen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMachtwort: Seelenstärke\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5235] = {title = "Ziel: Gahrrons Trauerfeld", objective = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, <Name>.\n\nGahrrons Trauerfeld liegt weit im Osten vom Bollwerk aus gesehen, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Mögen die Schatten Euch für diese gefährliche Mission in Sicherheit hüllen, <Klasse>.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords Rachseele löst sich auf, als er das Schloss der Zugangsklappe im Fundament der Kesselplattform berührt. Im Inneren erklingt ein leicht rasselndes Geräusch. Als die Zugangsklappe aufschwingt, enthüllt sie weitere zähflüssige Toxine im System des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5236] = {title = "Rückkehr zum Bollwerk", objective = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Gahrrons Tränenfeld beherbergt den letzten Kessel, zu dem wir hier im Westen Zugang brauchen. Wenn wir eine Probe der Seuche von diesem Kessel haben, können wir unsere Reagenzien durch vier separate Gefäße in die Umgebung entlassen. Die Geißel wird es schwer haben, um uns von allen vieren fern zu halten, selbst mit der Kraft von Kel'Thuzad hinter sich.", completion = "Herzlichen Glückwunsch, &lt;Name&gt;, Ihr habt den letzten Kessel für uns entriegelt! Apotheker Dithers wird bald wissen, welche Reagenzien für die Mischung dieses Kessels erforderlich sind.\n\nWas Euch angeht, so bin ich sicher, dass Hochexekutor Derrington Euch persönlich für die Hilfe, die Ihr uns habt angedeihen lassen, danken will. Ohne Euch wäre unser Kampf gegen die Geißel nahezu unmöglich gewesen. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMachtwort: Seelenstärke\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5237] = {title = "Mission erfüllt!", objective = "<Name>, Eure erfolgreiche Umarbeitung der Kessel ist ein überwältigender Sieg für uns!\n\n\n\nAlle, die sich hier in meinem Umfeld befinden, mögen Folgendes hören: Für Dienste am Königreich Stormwind und der Allianz, die über die gebotenen Pflichten hinausgingen - trotz wenig Erfolg versprechender Chancen und im Angesicht unglaublicher Gefahren, möchte ich <Name> dies geben und ihn unserer unvergänglichen Dankbarkeit als wahren Helden der Allianz versichern. Danke, sage ich!", description = nil, progress = nil, completion = nil, rewards = "Beherztes KurzschwertTapferes KurzschwertIhr bekommt:\n\nHeldenhafte Belobigungsmedaille"}
MultiLanguageQuestData['de'][5238] = {title = "Mission erfüllt!", objective = "<Name>, Eure erfolgreiche Umarbeitung der Kessel ist ein überwältigender Sieg für uns!\n\n\n\nAlle, die sich hier in meinem Umfeld befinden, mögen Folgendes hören: Für Dienste an den Verlassenen und an der Horde, die weit über die erwarteten Pflichten hinausgingen - trotz wenig Erfolg versprechender Chancen und im Angesicht unglaublicher Gefahren, möchte ich <Name> dies geben und ihn unserer unvergänglichen Dankbarkeit als wahren Helden der Horde versichern. Hussah!", description = nil, progress = nil, completion = nil, rewards = "Beherztes KurzschwertTapferes KurzschwertIhr bekommt:\n\nHeldenhafte Belobigungsmedaille"}
MultiLanguageQuestData['de'][5241] = {title = "Onkel Carlin", objective = "Sucht Carlin Rotpfad.", description = "Manchmal kann ich nachts meinen Onkel Carlin weinen hören. Es klingt, als ob er weit weg wäre, im Osten.\n\nIch hoffe, dass er nicht um mich weint! <Name>, werdet Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht?\n\nWenn Ihr ihn findet, sagt ihm, dass ich auf ihn warte und die Geschichte hören möchte, die er immer erzählt hat... die über die Hasen und die Marmelade! Die Geschichte ist so lustig!", progress = nil, completion = "Ihr habt Pamela gesehen? Sie lebt?\n\nSie ist tot? Nein! Oh, Pamela! Warum leidet dein Geist nur immer noch in dieser Welt... Warum bist du umgekommen, während das Schicksal mich am Leben erhält? Ich würde sofort mit dir tauschen und durch das tote Darrowshire wandern, als Geisterscheinung und allein!\n\nAch, aber diese Neuigkeiten können das Schicksal nicht ändern. Ich danke Euch, &lt;Name&gt;. Jetzt brennt meine Pflicht, meine Pflicht zur Rache, so heiß wie noch nie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5242] = {title = "Der endgültige Schlag", objective = "Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mooshuf im Teufelswald.", description = "Leider scheint die einzige Möglichkeit, diese Bedrohung für den Teufelswald zu stoppen, ein Frontalangriff zu sein. Es gibt keine anderen Wege in die Schattenfeste und ich habe keine Möglichkeit, Euch ins Innere zu teleportieren. Der gerade Weg hinab in die Tiefe ist der einzige Weg... und ich weiß auch, wen Ihr aufsuchen solltet. Sein Name ist Fel'dan...Schattenlord Fel'dan. Er ist der Sterbliche, der dort unten die Macht hat... er ist der Kopf der Schlange. Tötet ihn und seine beiden Sukkubus-Diener und kehrt zu mir zurück. Fel'dan ist derjenige, der Pakte mit der Legion schließt. Er muss aufgehalten werden.", progress = "Ohne Fel'dan werden die Mitglieder des Schattenrates hoffentlich ihr Ziel aus den Augen verlieren und untereinander zu streiten beginnen. Sie werden um die Macht kämpfen und Reichtümer für zukünftige Pläne anhäufen. Das wird eine günstige Zeit sein, um sie und ihre Dämonensklaven zu vernichten.", completion = "Gelobt sei die Erdenmutter, &lt;Name&gt;! Danke! Das ist wirklich ein großer Tag!\n\nDer Schattenrat wird es nach diesem Schlag gegen seine Hierarchie schwer haben, wieder in demselben Maße Macht zu erlangen wie zuvor. Heute habt Ihr etwas Großes geleistet!", rewards = "BrandholzschärpeVerseuchte LederhandschuheGedrehter SchmiedegurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5243] = {title = "Häuser der Heiligen", objective = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Weihwasser von Stratholme. Kehrt zu Leonidas Bartholomäus dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", description = "Ich sehe meinen Untod als eine Krankheit an, <Volk>. Eine Krankheit, die einfach nur eine Behandlung erfordert; sie ist aber auch ein großer Segen für die Argentumdämmerung. Wie kann man die Heiden der Geißel besser schlagen als durch den Untod?\n\nIch werde von meinen Kollegen wegen der Opfer, die ich dargebracht habe, geachtet, aber das Lob bedeutet mir nichts.\n\nWenn Ihr daran interessiert seid, der Argentumdämmerung zu helfen, kann ich Euch einen Auftrag anbieten.\n\nBegebt Euch nach Stratholme und holt unsere Reserven an heiligem Wasser. Durchsucht die Vorratskisten.", progress = "Seid vorsichtig, vermutlich haben nicht alle Vorratskisten die Zerstörung der Stadt überstanden. Die Geißel wagt es zwar nicht, das Wasser zu berühren, aber das heilige Wasser wird sicherlich keine Verseuchung durch Gezücht verhindern.", completion = "Gut gemacht, &lt;Volk&gt;. Ihr habt bewiesen, dass Ihr, auch wenn Ihr anderen gegenüber tolerant seid, vor nichts Halt machen werdet, um die Diener von Kel'Thuzad zu vernichten.", rewards = "Krone des reuigen SündersAuf Euch wartet eine dieser Belohnungen:\n\nBand des reuigen Sünders\n\nIhr bekommt außerdem:\n\nÜberragender HeiltrankGroßer Manatrank"}
MultiLanguageQuestData['de'][5244] = {title = "Die Ruinen von Kel'Theril", objective = "Sprecht mit Jaron Steinschleifer in Sternfall.", description = "Die Geschichte hinter Kel'Theril ist die eines verfluchten Volkes, gebunden an den Ort, an dem es ein unglückliches Ritual versuchte...\n\nDie Hochgeborenen, die Ihr dort finden werdet, stahlen einst ein hochheiliges Artefakt in dem Glauben, dass sie seine Macht für sich selbst nutzen und so noch mächtiger werden könnten. Durch ihre Bemühungen zerbrach das Relikt in einer gewaltigen Explosion, bei der die Teile unter das Eis des Sees getrieben wurden...\n\nSprecht mit Jaron Steinschleifer, wenn Ihr mehr erfahren möchtet; er hat das Gebiet vor Kurzem besucht und kann Euch mehr berichten.", progress = nil, completion = "Nun ja, sicher, ich kann Euch mehr über Kel'Theril berichten. Wohlgemerkt, ich bin kein Historiker, aber ich kann Euch erzählen, was ich dort sah...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5245] = {title = "Die gequälten Seelen von Kel'Theril", objective = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Himmelsrufer in den Östlichen Pestländern.", description = "Die Geister der Hochgeborenen sind erbärmliche Kreaturen, das ist mal sicher. Sie suchen immer noch nach Teilen dessen, was sie für immer nach Kel'Theril verdammte - das gestohlene Relikt.\n\nWenn Ihr so daran interessiert seid, nehmt meine Hacke und geht nach Süden zum See. Seht, ob Ihr die Teile des Relikts aus dem Eis holen könnt.\n\nWas Ihr da finden werdet, darüber kann ich Euch nichts sagen, aber ich kenne jemanden, der es vielleicht kann... Aurora Himmelsrufer; sie lebt beim Nordpassturm im nördlichen Teil der Östlichen Pestländer.", progress = "Warum kommt Ihr hierher?", completion = "Über die Vergangenheit der Hochelfen möchte ich nicht gern sprechen, &lt;Name&gt;. Bitte, es schmerzt mich, an all das zu denken, was geschehen ist... Und es gibt keine Möglichkeit, die Dinge wieder in Ordnung zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5246] = {title = "Fragmente der Vergangenheit", objective = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Himmelsrufer beim Nordpassturm in den Östlichen Pestländern.", description = "Ich wusste nicht, dass... Vergebt mir meine harten Worte, <Klasse>.\n\nÜber die Fehler meiner Vorfahren möchte ich mich nicht auslassen, aber wenn Eure Bitte wirklich echt ist, dann werde ich Euch helfen.\n\n<Aurora untersucht die Fragmente.>\n\nIch glaube, dass dies der Kristall von Zin-Malor ist, ein Artefakt, das starke arkane Kräfte fesseln und kontrollieren kann. Es hätte für das Gute genutzt werden können, aber die bösen Absichten derjenigen, die es stahlen, ließen es zersplittern.\n\nBegebt Euch zum Tempel von Zin-Malor in Azshara - ich kann nur hoffen, dass das Buch noch dort ist.", progress = "Nur mit Hilfe der Seiten der hochheiligen Schriften kann ich erkennen, ob ich Euch helfen kann oder nicht...", completion = "Die Seiten wurden seit vielen, vielen Jahren nicht mehr berührt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5247] = {title = "Fragmente der Vergangenheit", objective = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Himmelsrufer beim Nordpassturm in den Östlichen Pestländern.", description = "Ich kann Euch helfen, wenn Ihr das Artefakt wirklich wiederherstellen wollt.\n\nUm die Teile wieder zusammenzufügen und zu versiegeln, werde ich Gegenstände mit starken magischen Eigenschaften benötigen. Einen verzauberten Thoriumbarren und fünf Kristallflicker...Ihr werdet außerdem etwas Wasser von einem seltsam anmutenden Ort holen müssen...Sucht den Düsterteich entlang der Eldrethgasse in Düsterbruch in Feralas auf und füllt dort diese Phiole.\n\nWährend Ihr unterwegs seid, werde ich versuchen, diesen Seiten das Wissen zu entnehmen, das ich benötige, um den Schaden zu reparieren, der an dem Relikt verursacht wurde.", progress = "Das Relikt muss in die Hände der absolut Vertrauenswürdigsten gelegt werden. Es darf nicht wieder gestohlen werden...", completion = "Mit diesen Elementen kann ich die Fragmente zusammenfügen... hoffentlich zu dem, was sie einst waren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5248] = {title = "Gequält von der Vergangenheit", objective = "Bringt den Kristall von Zin-Malor zum Kel'Therilsee in Winterquell und sucht einen Geist eines Hochgeborenen, der mit Euch sprechen will.", description = "<Name>, ich weine ob dessen, was in der Vergangenheit geschehen ist. Wie dieser Kristall wurden auch die Elfen als Volk zerschmettert. Ich weiß nicht, ob die Teile jemals wieder zu einem vereinigt werden können, aber meine Trauer wurde dadurch gelindert, dass ich Euch bei dieser kleinen Aufgabe helfen konnte. \n\nWir dürfen die Vergangenheit nicht vergessen, <Name>...\n\nBringt bitte den Kristall von Zin-Malor zurück zum Kel'Therilsee. Ihr müsst einen Geist eines Hochgeborenen finden, der erkennt, was für ein Fehler vor so langer Zeit begangen wurde. Zeigt dem Geist, dass wir die Dinge wieder in Ordnung gebracht haben.", progress = "Verrrrrrflucht... Fürrrr immmmerrrr...", completion = "Bitteeeeee, lasssssst miiiiiiiiich...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5249] = {title = "Nach Winterquell!", objective = "Sucht Sternfall in Winterquell und sprecht mit Wynd Nachtjagd.", description = "In Winterquell, nördlich von hier, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nBei der vielen Arbeit, die hier im Teufelswald meiner harrt, hatte ich keine Gelegenheit, nach Winterquell zu reisen. Aber es gibt keinen Grund, warum Ihr es nicht tun solltet!\n\nWährend Ihr dort seid, sucht doch nach Wynd Nachtjagd. Er verbringt den Großteil seiner Zeit in Sternfall und er weiß viel über die Gegend.", progress = nil, completion = "Ein Freund von Ivy Leafrunner? Ich freue mich, Euch kennen zu lernen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5250] = {title = "Sternfall", objective = "Sucht die Siedlung Sternfall in Winterquell und sprecht mit Wynd Nachtjagd.", description = "In Winterquell, nördlich des Teufelswaldes, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nMeine Studien hier beschäftigen mich so sehr, dass ich seit einiger Zeit keine Gelegenheit mehr hatte, nach Winterquell zu reisen. Aber es gibt keinen Grund, warum Ihr nicht dorthin reisen und die Ruinen erforschen solltet.\n\nWährend Ihr dort seid, sucht doch nach Wynd Nachtjagd. Er verbringt den Großteil seiner Zeit in Sternfall und er weiß viel über die Gegend.\n\nSagt ihm, dass Ihr einer meiner Schüler seid...", progress = nil, completion = "Ein Schüler von Daryn Lightwind? Ich freue mich, Euch kennen zu lernen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5251] = {title = "Der Archivar", objective = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", description = "Alles, was zum Extremen getrieben wird, ist für unsere Welt gefährlich, <Name>. Nehmt zum Beispiel den Scharlachroten Kreuzzug. Glaubt Ihr, dass der blinde Fanatismus seiner Anhänger etwas Gutem dient? Wie viele Unschuldige haben sie im Namen des Lichts vernichtet?\n\nGotteslästerer, alle zusammen!\n\nEiner interessiert mich aber besonders, der Archivar Galford von Stratholme: ein Mann, der über die wertvollsten Dokumente des Kreuzzugs wacht. Vernichtet ihn und verbrennt seine Archive! Wenn Ihr erfolgreich seid, kehrt zu mir zurück und Ihr werdet belohnt.", progress = nil, completion = "Phantastisch, &lt;Name&gt;! Über Jahre hinweg gesammelte Informationen, verloren! Der Scharlachrote Kreuzzug wird diesen Schlag in den folgenden Wochen sicherlich spüren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5252] = {title = "Reuevolle Hochgeborene", objective = "Sprecht mit Wynd Nachtjagd in Sternfall und fragt nach dem richtigen Ort für den Kristall von Zin-Malor.", description = "Der... der Kristall...\n\nDie Hochgeborenen hier sssind durch ihr eigenessss Elend verwirrrrt...\n\nIch bin betrrrrübt, aber ich erkenne den Fehlerrr dessen, wassss vor so langer Zeit geschah. Obwohl esss keine Möglichkeit giiibt, die Vergangenheit zu ändern, habe ich nun Friiiieden gefunnnnden, da ich weiß, dass Ihr den Kristall von Zin-Malor wiederbeschafft habt...\n\nIiihr müsssssst ihn zurückbringennnn...\n\nEr muuussss zurückgebracht werrrdennnn.", progress = "Es ist eine Weile her, seit Ihr weggegangen seid, <Name>. Wie ist es Euch ergangen?", completion = "Ist das... für was ich es halte?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5253] = {title = "Der Kristall von Zin-Malor", objective = "Überbringt dem Erzdruiden Fandral Hirschhaupt in Darnassus den Kristall von Zin-Malor.", description = "Recht eindrucksvoll, <Name>.\n\nDer Kristall von Zin-Malor kann niemals in den Tempel zurückgebracht werden, der, wie Ihr wisst, nur noch eine Ruine ist. Aber ich finde, dass Eure Bemühung, das Böse der Vergangenheit ungeschehen zu machen, nicht ohne Belohnung bleiben soll.\n\nSucht den Erzdruiden Fandral Hirschhaupt in Darnassus auf und bringt ihm den Kristall, <Name>. Er sollte sich in den Händen derer befinden, die seine Macht nicht missbrauchen werden. Wie es aussieht, sind von den stärksten Magieanwendern nur eine Hand voll in der Lage, solch eine Macht zu kontrollieren.", progress = "Ja, <Volk>?", completion = "Ich habe von dem Kristall von Zin-Malor gehört; der Benutzer des Kristalls wird unglaublicher arkaner Macht fähig, aber nur, wenn er wirklich würdig ist. Ich bin beeindruckt, dass Ihr nicht nur den Kristall wiederbeschafft habt, sondern auch Eure eigenen Grenzen erkannt und nicht versucht habt, den Kristall selbst zu benutzen.\n\nDanke, dass Ihr ihn mir gebracht habt, &lt;Name&gt;. Wir werden ihn sicher aufbewahren, und mögen die verfluchten Geister, die den zerbrochenen Kristall einst bewachten, endlich ihren Frieden finden.", rewards = "Türkise SchärpePflugholzschiftungSmaragdnebelstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5261] = {title = "Eagan Pelzschneider", objective = "Sprecht mit Eagan Pelzschneider.", description = "Eagan Pelzschneider sucht nach jemandem, der für ihn erkrankte Wölfe jagt. Das ist gut, da wir hier im Nordhaintal in letzter Zeit sehr viele erkrankte Wölfe gesehen haben.\n\nWenn Ihr interessiert seid, dann sprecht mit Eagan. Ihr findet ihn neben der Abtei, auf der linken Seite.", progress = nil, completion = "Das ist wahr. Ich suche nach jemandem, der für mich Wölfe jagt! Seid Ihr diese Person?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5262] = {title = "Die Wahrheit zeigt sich mit Macht", objective = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.", description = "Ihr versucht, Eure Gedanken zu sammeln, während sich der Staub in der Kammer wieder setzt. Ihr geht in Gedanken die Ereignisse durch, die sich gerade ereignet haben, und könnt dennoch die Schwere der Situation nicht verstehen.\n\nDer Oberste Kreuzfahrer des Scharlachroten Kreuzzugs ein Dämon? Und nicht nur irgendein Dämon, sondern der Bruder von Varimathras, Erzlord von Unterstadt?\n\nIhr verstaut den abgetrennten Kopf des Schreckenslords sorgfältig in Eurem Rucksack. Natürlich würde Euch niemand diese Geschichte ohne Beweise glauben.\n\nFürst Nicholas Zverenhoff muss sofort davon erfahren!", progress = "Was habt Ihr denn da, <Name>?", completion = "Was bedeutet das für den Kreuzzug? Könnte es wirklich sein, dass seine Mitglieder sich unter der Kontrolle dieses Dämons befanden? Und unwissentlich als Bauern für ein größeres Übel dienten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5263] = {title = "Übertroffen", objective = "Zieht nach Stratholme und vernichtet Baron Totenschwur. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", description = "Ihr zeigt eine natürliche Begabung für die Kunst der Zerstörung und Ihr folgt Befehlen. Es ist selten, dass beides zusammentrifft. In mir keimt immer mehr der Gedanke, dass Ihr ein hervorragendes Mittel göttlicher Gerechtigkeit darstellen könntet.\n\n<Zverenhoff verschränkt seine Hände vor seinem Gesicht.>\n\nDer Laufbursche von Kel'Thuzad regiert über Stratholme. Beweist mir, dass Ihr ein Held seid - mein Held. Vernichtet Baron Totenschwur und kehrt mit seinem Kopf zu mir zurück.", progress = "Der Baron hat mehr Menschen getötet, als Ihr wahrscheinlich in Eurem Leben gesehen habt.", completion = "Es ist viele Jahre her, dass ich einen Helden in unsere Ränge eingeführt habe. Ihr seid der Erste, dem seit Jahren eine Audienz bei Lord Maxwell gewährt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5264] = {title = "Lord Maxwell Tyrosus", objective = "Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche.", description = "Ich werde Euch eine große Ehre zuteilwerden lassen, <Name>.\n\nLord Maxwell wünscht, Euch für Euren Dienst an der Argentumdämmerung zu belohnen!\n\nEs ist Jahre her, seitdem Maxwell das letzte Mal einem Außenstehenden eine Audienz gewährt hat.", progress = nil, completion = "Ihr seid ein würdiger Verbündeter, &lt;Name&gt;. Ihr sollt die Belohnung für Eure standhafte Hingabe ernten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5265] = {title = "Der Argentumtresor", objective = "Öffnet den Argentumtresor und nehmt Euch Eure Belohnung.", description = "Über viele Jahre hinweg blieb der Argentumtresor verschlossen. Niemand war würdig genug, hineinzugreifen und die Macht der Argentumdämmerung herauszunehmen - bis heute.\n\nder Argentumtresor ist nun für Euch geöffnet, <Name>.", progress = nil, completion = "Boah...", rewards = "ArgentumverteidigerArgentumrächerArgentumkreuzfahrerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5281] = {title = "Die ruhelosen Seelen", objective = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.", description = "Da gibt es diejenigen, die tragisch beim Fall von Stratholme starben. Viele nahmen sich das Leben, entschieden sich dafür, sich lieber selbst in die Myriaden Flammen der glimmenden Stadt zu stürzen, statt einer der Geißel zu werden.\n\nNun ziehen sie als ruhelose Geister durch die Straßen von Stratholme.\n\nWir müssen ihnen helfen, <Name>!\n\nIch habe einen Partner namens Egan, der wunderbare Arbeit mit Geistern und Seelen geleistet hat. Sucht ihn auf. Er streift durch die Östlichen Pestländer, in der Nähe von Stratholme, und testet seine Neuheiten.", progress = nil, completion = "Alen hat also endlich jemanden gefunden, der mutig genug ist, hmm?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5282] = {title = "Die ruhelosen Seelen", objective = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\n\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.", description = "Ich ziehe meine Macht - meinen Willen, weiter zu leben und zu atmen - aus dem ganzen Hass, den ich der Geißel entgegenbringe, und allem, was sie getan hat. Ich bin aber trotzdem kein Eiferer. Es gibt die, wie die Mitglieder des Scharlachroten Kreuzzugs, die die unschuldigen Untoten eher vernichten würden, als ihnen auch nur ein wenig Mitleid entgegenzubringen.\n\nDas bringt mich zu dem hier: meinem Blaster. Er wird die gequälten Seelen von Stratholme erlösen.\n\nWendet ihn auf die Geisterscheinungen an, die die geplünderten Straßen durchstreifen. Befreit ihre Seelen.", progress = nil, completion = "&lt;Egan wischt eine Träne weg.&gt;\n\nHabt Ihr meine Mutter gesehen, &lt;Name&gt;? Habt Ihr sie befreit?\n\nIhr seid ein leuchtendes Beispiel des Anstands.", rewards = "Ihr bekommt:\n\nTestament der Hoffnung"}
MultiLanguageQuestData['de'][5283] = {title = "Die Kunst des Rüstungsschmiedes", objective = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", description = "Tja, Ihr habt 'ne kluge Entscheidung getroffen.\n\nWir haben nix füreinander übrig, ich und der alte Ironus hier. Dieser nichtsnutzige Spielzeughersteller weiß, wer die wahren Handwerker hier sind.\n\nDie wirklich großen Kriege werden mit 'ner guten Verteidigung gewonnen. Wenn's losgeht, wird Euch kein Angriff helfen.\n\nAlso dann, ran an die Arbeit! Ihr müsst mir nur zeigen, dass Ihr über Talent verfügt. Danach reiß ich alle Unreinheiten, die noch in Euch sind, raus und mach einen Rüstungsschmied aus Euch. Ihr wisst doch, wie man verschnörkeltes Mithril herstellt, nicht wahr?", progress = "Ah, es geht nichts über eine gute Schmiedebräune. Am Schürzenstreifen kann man erkennen, wer 'ne wirklich gute Bräune hat.", completion = "So, &lt;Name&gt;. Danach gibt es keinen Weg zurück. Es ist noch nicht zu spät, Spielzeugmacher, äh, Waffenschmied zu werden.\n\nIch denke, dass Ihr die richtige Entscheidung trefft.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRüstungsschmied\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5284] = {title = "Der Weg des Waffenschmieds...", objective = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", description = "Als Waffenschmied werdet Ihr feststellen, dass sehr häufig Helden und Abenteurer der Ausrüstung wegen zu Euch kommen werden. Wenn die viele Arbeit manchmal auch unerträglich sein kann, macht der Wohlstand aber doch die Rückenschmerzen und die Aschenlunge wett.\n\nOh ja, <Name>, Waffenschmiede sind die mit dem ganzen Gold!\n\nWenn Ihr unseren Rängen beitreten wollt, müsst Ihr mir zeigen, dass Ihr mir ein Silberstück oder zwei machen könnt - ich meine, zeigt mir, dass Ihr habt, was man braucht, wenn Menschen Waffen überragender Qualität benötigen. An die Arbeit!", progress = "<Ironus ist damit beschäftigt, goldene Münzen zu ordentlichen kleinen Häufchen zu stapeln.>", completion = "Das wurde auch Zeit! Ich hab Kunden, die warten.\n\nGebt mir die Dinger und hört mir zu. Ihr werdet den ersten Schritt in Eurer Karriere als Waffenschmied machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWaffenschmied\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5301] = {title = "Die Kunst des Rüstungsschmiedes", objective = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", description = "Zufriedenheit. Das bekomme ich von Hammer und Amboss. Einen stolzen Krieger der Horde zu sehen, der von meinem Stahl geschützt ist, erinnert mich daran, was es heißt, am Leben zu sein. Das ist eine Sucht, die ich niemals ablegen werde, <Name>.\n\nIch kann Euch diese Zufriedenheit nicht garantieren, Euch nur auf den Weg dazu bringen. Wie bei allen Bestrebungen des Lebens ist auch der Weg des Rüstungsschmieds eine Reise.\n\nWenn Ihr einer der wenigen Erwählten sein wollt, müsst Ihr nur fragen und ich werde Euch ausbilden, aber zuerst müsst Ihr eine Aufgabe erledigen.", progress = "Ich werde den Stahl schlagen, bis mir selbst der Atem genommen wird.", completion = "Dies ist der letzte Schritt, bevor Ihr Eure neue Karriere als Rüstungsschmied beginnen könnt, &lt;Name&gt;. Solltet Ihr Euch dazu entscheiden abzuspringen, ist jetzt Eure letzte Gelegenheit dazu. Anderenfalls bereitet Euch auf ein Leben voller Ruhm und Glorie vor.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRüstungsschmied\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5302] = {title = "Der Weg des Waffenschmieds...", objective = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", description = "Eines Tages werde ich einen legendären Hammer erschaffen. Einen Hammer, der eines Kriegshäuptlings würdig ist!\n\nDas ist mein Lebenswerk, <Name>. Meine Leidenschaft. Ich erkenne, dass Ihr das Potenzial habt, zu uns zu gehören, einer von uns zu sein - ein Waffenschmied. Ich bin derjenige, der Euch helfen kann, dieses Potenzial nutzbar zu machen.\n\nAlles, was Ihr dafür erledigen müsst, ist eine einfache Aufgabe. Einfach für jemanden von Eurer außergewöhnlichen Fertigkeit.", progress = "Für den Ruhm der Horde!", completion = "Dies ist der letzte Schritt, bevor Ihr Eure neue Karriere als Waffenschmied beginnen könnt, &lt;Name&gt;. Solltet Ihr Euch dazu entscheiden abzuspringen, ist jetzt Eure letzte Gelegenheit dazu. Anderenfalls bereitet Euch darauf vor, vom Wissen verzehrt zu werden!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWaffenschmied\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5305] = {title = "Süße Beschaulichkeit", objective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch mit dem Wissen ausstatten, wie man einen verzauberten Kampfhammer herstellt!", progress = "Seine Schürze! Wo ist sie?", completion = "Mögt Ihr so manchen Schädel einschlagen, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nPläne: Verzauberter Kampfhammer"}
MultiLanguageQuestData['de'][5306] = {title = "Schlangenstein der Schattenjägerin", objective = "Begebt Euch zur Schwarzfelsspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", description = "Lasst Euch von ihrer Schönheit nicht narren, <Klasse>. Die Schattenjägerin Vosh'gajin ist todbringend und wahnsinnig.\n\n<Kilram zeigt auf die Narbe in seinem Gesicht.>\n\nJa, die habe ich von ihr - eine Liebkosung, wie sie es nannte.\n\nJetzt endlich ist die Zeit der Rache gekommen.\n\nIhr könnt Vosh'gajin in der Schwarzfelsspitze finden. Erschlagt sie und kehrt mit ihrem Schlangenstein zu mir zurück. Erledigt das und ich werde Euch das Geheimnis des Schmiedens der Dämmerungsschneide beibringen!", progress = "Die Legende besagt, dass Vosh'gajins Schlangenstein eine Axt mit einer einzigen Anwendung 1000 Jahre lang messerscharf machen würde!", completion = "Ihr seid Euch also sicher, dass Ihr dies wollt? Ein Axtschmied werden? Denkt daran, die Türen zu Schwertschmied und Hammerschmied werden Euch dann für immer verschlossen sein.", rewards = "Ihr bekommt:\n\nPläne: Dämmerungsschneide"}
MultiLanguageQuestData['de'][5307] = {title = "Verderbnis", objective = "Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Geißelbann zurück.", description = "Wenn ich mit Euch kurz angebunden bin, dann gibt es einen Grund dafür. Die Pläne für die Erschaffung der großen Klinge, der Verderbnis, wurden von der schwarzen Wache gestohlen: den Skeletteliteeinheiten von Baron Totenschwur.\n\nJa, Baron Totenschwur von Stratholme.\n\nDer Schwertschmied der schwarzen Wache bewacht diese Pläne nun mit seinem...Untod.\n\nErschlagt ihn, kehrt mit einem Beweis für diese Tat zurück und ich werde Euch das Wissen schenken, mit dem Ihr einen Loderflammenrapier herstellen könnt.", progress = "Habt Ihr vergessen, welche Aufgabe Euch aufgetragen wurde, <Name>?", completion = "Ihr seid Euch also sicher, dass Ihr dies wollt? Ein Schwertschmied werden? Denkt daran, die Türen zu Hammerschmied und Axtschmied werden Euch dann für immer verschlossen sein.", rewards = "Ihr bekommt:\n\nPläne: Loderflammenrapier"}
MultiLanguageQuestData['de'][5321] = {title = "Der Schläfer ist erwacht", objective = "Begleitet Kerlonian Schattenspiel zu Liladris Mondbach in Maestras Posten im Eschental.", description = "Ich war auf dem Weg zu Maestras Posten, um mich mit Liladris Mondbach zu treffen, als ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum aufgewacht bin, bin ich ständig so müde...\n\n<gähnt>\n\nKönntet Ihr mir den Weg zeigen? Ich weiß, dass Maestras Posten südlich von hier ist, entlang der Straße im Eschental. Es kann gefährlich werden, daher hoffe ich, dass Ihr einige Freunde habt, die sich uns anschließen werden.\n\nAußerdem könnte ich einschlafen. Wenn Ihr mich also einmal aufwecken müsst, dann benutzt dazu bitte mein Horn. Ihr findet es in der Truhe hier.", progress = "Ist Kerlonian angekommen?", completion = "Oh, ich bin ja so froh, dass Kerlonian es geschafft hat! Und ich bin sicher, dass ich ihn hier irgendwo süß und fest schlafend antreffen werde, nicht wahr?\n\nDanke, dass Ihr ihm den Weg gezeigt habt, &lt;Name&gt;.", rewards = "Gewehr der EulensichtStahlkappenschildAuf Euch wartet eine dieser Belohnungen:\n\nJadefingerbaton\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5341] = {title = "Das Familienvermögen der Barovs", objective = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.", description = "In Scholomance liegt das Familienvermögen der Barovs. Ich, Alexi Barov, bin einer der beiden letzten verbliebenen Erben des Hauses Barov. Mein Bruder Weldon ist der andere.\n\nWeldon, der jämmerliche Feigling, floh während des Krieges und hielt so an seiner wertlosen Existenz als Mensch fest.\n\nJetzt sucht er nach den Besitzurkunden, damit er das Vermögen für sich beanspruchen kann. Holt die Besitzurkunden, bevor mein Bruder es tut, und ich werde Euch reicher machen, als Ihr je zu träumen gewagt habt.", progress = "Neigt Euer Haupt in meiner Anwesenheit, <Volk>. Schließlich gehöre ich zum Adel und Ihr seid ein dummer Bauerntölpel.", completion = "Gut gemacht, &lt;Volk&gt;. Jetzt muss ich mir mein Erbe sichern...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5342] = {title = "Der letzte Barov", objective = "Begebt Euch zum Zugwindlager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.\n\nSeid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt.", description = "Da mein Bruder noch am Leben ist, wird es möglicherweise einen Disput darüber geben, wer der Hauptbegünstigte des Familienvermögens ist. Das darf nicht sein.\n\nEin niederer Gossenstreuner wie Ihr hat ja wohl nichts gegen einen kleinen kaltblütigen Mord einzuwenden, hoffe ich.\n\nEs ist eine einfache Aufgabe und ich erwarte, dass Ihr sie erfüllt... das heißt, falls Ihr Eure Belohnung erhalten wollt.\n\nWeldon sitzt unter dem Schutz der Allianz im Zugwindlager im Osten. Erschlagt ihn, bringt seinen Kopf zurück.\n\n<Alexi gähnt.>\n\nUnd jetzt fort mit Euch.", progress = "Sichert mir mein Vermögen und Ihr erhaltet einen Anteil an der Beute.", completion = "Großartig! Jetzt habe ich allein die Macht und das Vermögen des Hauses Barov!\n\n&lt;Alexi wirft Euch einen großen Beutel zu.&gt;\n\nUnd behaltet den Rest, dreckiges Tier!", rewards = "Ihr bekommt:\n\nBedienstetenglöckchen der Barovs"}
MultiLanguageQuestData['de'][5343] = {title = "Das Familienvermögen der Barovs", objective = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", description = "Mein lieber Bruder Alexi. Was für ein Narr war ich doch, sein Leben zu verschonen. Ich sah dem Feind ins Gesicht, einem der Untoten, und ließ ihn am Leben.\n\n<Weldon spuckt aus.>\n\nUnd jetzt sucht er nach MEINEM Erbe. Das darf einfach nicht sein.\n\nSucht die Besitzurkunden meiner Familie, bevor sie diesem niederträchtigen Bastard in seine knochigen Hände fallen, und ich werde Euch mit großem Reichtum belohnen. Sie liegen irgendwo in den Ruinen der Scholomance. Beeilt Euch!", progress = "Sichert mir meine Zukunft und ich werde die Eure sichern.", completion = "Es gibt nur noch eine weitere Aufgabe, die Ihr für mich erledigen müsst, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5344] = {title = "Der letzte Barov", objective = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.\n\nSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.", description = "Da die Besitzurkunden beschafft sind, bleibt nur noch eine Sache zu tun. Alexi muss getötet werden. Wenn er tot ist, brauche ich nicht mehr zu fürchten, dass eine skrupellose Bande von Söldnern meinen Kopf haben will.\n\nDie Aufgabe ist einfach. Alexi versteckt sich unter dem Schutz der Horde - beim Bollwerk.\n\nNein, ich erwarte nicht, dass Ihr einfach nur hingeht und ihn tötet, ich will seinen Kopf! Wie Ihr ihn bekommt...tja, dieser Part ist Euch überlassen. Ein derartiges Verhalten ist einem von meiner edlen Erziehung nicht würdig..", progress = "Ihr wollt Eure Bezahlung, was?", completion = "Das ist ein glorreicher Tag! Endlich wurde der Schandfleck des Hauses Barov eliminiert und mein Vermögen gesichert!\n\nNehmt dies und geht mir aus den Augen... Wurm.", rewards = "Ihr bekommt:\n\nBedienstetenglöckchen der Barovs"}
MultiLanguageQuestData['de'][5361] = {title = "Stammbaum", objective = "Bringt den Bericht von Klippenbehüter Langhorn zu Nataka Langhorn am Geistwandlerposten in Desolace.", description = "Mein Bruder Nataka ist beim Geistwandlerposten drüben in Desolace stationiert. Also, worum ich Euch bitten möchte, ist... könntet Ihr ihm diesen Bericht von mir geben? Ein Jahr ist vergangen, seit ich ihm das letzte Mal schrieb, und es gab seitdem ungewöhnliche Zentaurenaktivitäten, über die er informiert werden sollte.\n\nReist zum Steinkrallengebirge nördlich des Wegekreuzes und dann westlich zum Verbrannten Tal. Begebt Euch von dort aus südlich nach Desolace; dort findet Ihr eine Straße, die gen Süden zum Geistwandlerposten führt.", progress = "Welche Neuigkeiten habt Ihr, <Klasse>? Ah - eine Nachricht von meinem Bruder, sagt Ihr? Nun dann, gebt den Bericht her!", completion = "Ich weiß nicht, in welcher Beziehung Ihr zu meinem Bruder steht, aber es sieht so aus, als würde er Euch vertrauen, &lt;Klasse&gt;.\n\nIch bin Nataka Longhorn und möchte Euch im Geistwandlerposten willkommen heißen. Wir können Leute wie Euch hier gut brauchen, &lt;Klasse&gt;! Sprecht mit anderen, vielleicht braucht man hier Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5381] = {title = "Hand von Iruxos", objective = "Holt den Dämonenkasten aus der Festung Donneraxt und kehrt damit zu Taiga Klugmähne nach Schattenflucht zurück.", description = "Die Brennende Klinge ist im Besitz des Dämonenkastens. Darin liegt die mächtige Hand von Iruxos. Die Anhänger der Brennenden Klinge verwenden sie, um dämonische Portale beim Zirkel der Mannoroc zu öffnen. Wir müssen die Flut der Dämonen stoppen, die in unsere Welt eindringt, <Name>!\n\nWendet diese Dämonenhacke auf den roten Kristall in der Festung Donneraxt an, um Zugang zu dem Dämonenkasten zu erlangen.", progress = "<Name>, habt Ihr den Dämonenkasten?", completion = "Ah, der Dämonenkasten. Gebt ihn mir, &lt;Klasse&gt;, und ich werde ihn öffnen... und Euch damit die Hand von Iruxos offenbaren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5382] = {title = "Doktor Theolen Krastinov, der Schlächter", objective = "Sucht Doktor Theolen Krastinov in Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Krastinov ist für den Tod von Tausenden verantwortlich. Er muss bestraft werden, die Gerechtigkeit muss ihren Lauf nehmen.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, <Name>.", progress = "Der Schlächter muss aufgehalten werden!", completion = "Ich fühle, wie mein Geist heilt, &lt;Name&gt;. Ihr habt meinem Ehemann und mir einen großen Dienst erwiesen, aber ich bin sicher, dass es noch mehr zu tun gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5383] = {title = "Krastinovs Tasche der Schrecken", objective = "Bringt die Tasche der Schrecken zu Eva Sarkhoff in Darrowehr.\n\nBereitgestellter Gegenstand: \n", description = "Ihr öffnet die Tasche und entdeckt darin verschiedene Folterinstrumente. Unter dem Zubehör fällt Euch ein merkwürdiges Objekt ins Auge. Eine Phiole mit Blut - noch immer warm.\n\nIhr denkt, dass die Sarkhoffs an Eurer Entdeckung interessiert sein könnten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5384] = {title = "Kirtonos der Herold", objective = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\n\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.", description = "Das ist es, <Name>.\n\n<Eva zeigt auf die Phiole in der Tasche.>\n\nDas Blut von Unschuldigen. Das reinste Blut... damit wird Krastinovs Meister besänftigt.\n\nMit diesem Blut kann Kirtonos beschworen werden. Mit diesem Blut muss Kirtonos auch vernichtet werden.\n\nBringt dieses Blut auf die Veranda. Legt es auf die Kohlenpfanne. Kirtonos wird kommen - er kann nicht widerstehen. Wenn er erscheint, entfesselt die Wut und den Zorn von Tausenden unschuldigen Toten über ihm.\n\nWenn Ihr erfolgreich seid, werdet Ihr mehr verdienen als nur unsere Dankbarkeit.", progress = "Seid vorsichtig, Kirtonos ist ein erfahrener Kämpfer.", completion = "Mit dem Tod von Kirtonos wird ein Kapitel in der schrecklichen Geschichte der Scholomance geschlossen. Aber es gibt noch mehr zu tun. Andere hier sind sich jetzt Eurer mutigen Taten bewusst. Nehmt das, &lt;Name&gt;. Es ist ein Stück unserer eigenen Essenz. Sie ermöglicht Euch, mit den anderen verlorenen Seelen von Caer Darrow zu kommunizieren.", rewards = "Mirahs LiedAuf Euch wartet eine dieser Belohnungen:\n\nPenelopes Rose\n\nIhr bekommt außerdem:\n\nSpektrale Essenz"}
MultiLanguageQuestData['de'][5385] = {title = "Die Überreste von Trey Lichtschmied", objective = "Bringt die Überreste von Trey Lichtschmied zu Jessir Mondsichel im Teufelswald.", description = "Ihr hebt den Sack vorsichtig auf und macht Euch auf den Rückweg zu Jessir Mondsichel an der Grenze des Teufelswaldes und des Eschentals. Hoffentlich wird dem Paladin der ihm zustehende Respekt erwiesen, wenn Ihr seine Überreste seinen Freunden übergeben habt.", progress = "Wie lief es in Jaedenar, <Name>?", completion = "Ihr habt es geschafft! Gelobt sei Elune und welche Mächte auch immer Ihr anbetet, &lt;Name&gt;. Ihr habt heute etwas Ehrenwertes und Großmütiges getan. Ich bin sicher, dass Arko'narin erfreut sein wird, dass Ihr Euch nicht nur die Zeit genommen habt, sie zu retten, sondern auch die Kreatur zu erledigen, die einen ihrer besten Freunde gefoltert hat.\n\nIch wünschte, ich könnte mehr für Euch tun, aber bitte, nehmt dies.", rewards = "Klinge des GezeitenwappensFährtenleserjagdklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5386] = {title = "Der Fang des Tages", objective = "Sprecht mit Jinar'Zillen in Schattenflucht und bringt Nataka Langhorn dann 2 Blutbauchfische.", description = "Der Geruch von gekochtem Fisch ist hier im Geistwandlerposten schon längst verschwunden. Die Trolle von Schattenflucht sind die Besten, wenn es um das Fangen von Fischen geht... aber leider habe ich aufgrund all der Zentaurenaktivitäten nicht genug Zeit, um eine Reise zu den Trollen zu unternehmen. Hm...\n\nTut mir einen Gefallen und reist nach Schattenflucht. Sprecht mit dem dortigen Angler Jinar'Zillen und bringt mir mein Leibgericht, Blutbauchfisch. Die Straße südlich von hier bringt Euch nach Westen zu dem Trolldorf.", progress = "Mein Huf prickelt und mir läuft das Wasser im Mund zusammen, wenn ich an gebratenen Blutbauchfisch denke... Habt Ihr welchen dabei?", completion = "Ihr seid ein Retter, &lt;Name&gt;! Diese Blutbauchfische sehen fast gut genug aus, um sie roh zu essen.\n\n\n\nHier, bitteschön. Wählt einen dieser Gegenstände als Bezahlung für diese Fische aus.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMithrilerzDickes LederMagiestoff\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5401] = {title = "Anstecknadel der Argentumdämmerung", objective = "Alle, die für die Argentumdämmerung das Böse bekämpfen, müssen unsere Anstecknadel tragen. Wenn Ihr eine solche tragt, erhaltet Ihr das Recht, Belohnungen in Anspruch zu nehmen, die unsere Rüstmeister anzubieten haben.\n\nWährend Ihr die Nadel tragt, könnt Ihr Euch Geißelsteine von erschlagenen Mitgliedern der Geißel holen; das sind Insignien, die sie manchmal besitzen. Beschafft Euch diese Insignien und bringt sie mir. Für alle, die Ihr abgebt, erhaltet Ihr unsere Marke des Heldentums - die Ehrenmarke der Argentumdämmerung.\n\nErfüllt Euer Schicksal, <Klasse>... stürzt Euch noch heute in den Kampf!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAnstecknadel der Argentumdämmerung"}
MultiLanguageQuestData['de'][5402] = {title = "Geißelsteine des Dieners", objective = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", description = nil, progress = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nDie Marken dienen zwei Zwecken. Erstens können sie verwendet werden, um Euren Stand innerhalb der Argentumdämmerung zu fördern; das könnte Euch zu Möglichkeiten und Belohnungen verhelfen, die unseren geehrten und geachteten Verbündeten vorbehalten sind. Zweitens könnt Ihr sie, zusammen mit Münzen, an unsere Rüstmeister weitergeben, als Bezahlung für einige der kostspieligeren Gegenstände der Dämmerung.\n\nWozu Ihr Euch auch entscheidet, wisset, dass Ihr Euch Eure Anstecknadel verdient. Gut gemacht!", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5403] = {title = "Geißelsteine des Eindringlings", objective = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", description = nil, progress = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nJede Ehrenmarke, die an einen würdigen Empfänger vergeben wird, ist ein Zeichen, dass sich das Schicksal gegen die Geißel wendet. Da mehr und mehr Helden die Geißel in ihren eigenen Ländern bekämpfen, wird die Argentumdämmerung sicherlich in erster Reihe stehen, wenn die Zeit kommt, Krieg über das ultimative Böse der Geißel zu bringen. Ich hoffe, dass der Mut, den Ihr gezeigt habt, um Eure Marke zu erlangen, auch dann den Sieg davontragen wird!", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5404] = {title = "Geißelsteine des Verderbers", objective = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, <Name>... mit solch mächtigen Wesen ist nicht zu spaßen.", description = nil, progress = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, <Name> ... mit solch mächtigen Wesen ist nicht zu spaßen.", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!\n\nFür die Dämmerung, mein Bruder.", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5405] = {title = "Anstecknadel der Argentumdämmerung", objective = "Alle, die für die Argentumdämmerung das Böse bekämpfen, müssen unsere Anstecknadel tragen. Wenn Ihr eine solche tragt, erhaltet Ihr das Recht, Belohnungen in Anspruch zu nehmen, die unsere Rüstmeister anzubieten haben.\n\nWährend Ihr die Nadel tragt, könnt Ihr Euch Geißelsteine von erschlagenen Mitgliedern der Geißel holen; das sind Insignien, die sie manchmal besitzen. Beschafft Euch diese Insignien und bringt sie mir. Für alle, die Ihr abgebt, erhaltet Ihr unsere Marke des Heldentums - die Ehrenmarke der Argentumdämmerung.\n\nErfüllt Euer Schicksal, <Klasse>... stürzt Euch noch heute in den Kampf!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAnstecknadel der Argentumdämmerung"}
MultiLanguageQuestData['de'][5406] = {title = "Geißelsteine des Verderbers", objective = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, <Name>... mit solch mächtigen Wesen ist nicht zu spaßen.", description = nil, progress = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, <Name> ... mit solch mächtigen Wesen ist nicht zu spaßen.", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!\n\nFür die Dämmerung, mein Bruder.", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
