MultiLanguageQuestData['de'][5408] = {title = "Geißelsteine des Dieners", objective = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", description = nil, progress = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nDie Marken dienen zwei Zwecken. Erstens können sie verwendet werden, um Euren Stand innerhalb der Argentumdämmerung zu fördern; das könnte Euch zu Möglichkeiten und Belohnungen verhelfen, die unseren geehrten und geachteten Verbündeten vorbehalten sind. Zweitens könnt Ihr sie, zusammen mit Münzen, an unsere Rüstmeister weitergeben, als Bezahlung für einige der kostspieligeren Gegenstände der Dämmerung.\n\nWozu Ihr Euch auch entscheidet, wisset, dass Ihr Euch Eure Anstecknadel verdient. Gut gemacht!", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5421] = {title = "Fisch im Eimer", objective = "Jinar'Zillen möchte, dass Ihr 5 Schalentiere aus den Fallen rund um Schattenflucht holt.", description = "Ich belohne jeden, der mein Leben 'n bisschen einfacher macht... ich mag's, mich so wenig wie möglich anzustrengen, Mann!\n\nUnterhalb des Stegs hier in Schattenflucht hab' ich 'ne Menge Schalentierfallen. Wenn du so nett wärst, mir die Arbeit abzunehmen und mir meine Schalentiere einsammelst, dann belohne ich dich mit etwas, das du brauchst... wenn du verstehst was ich meine, Mann?", progress = "Ich werde jeden belohnen, der mein Leben ein bisschen einfacher macht... Ich genieße es, so wenig wie möglich zu tun, Mann!\n\nUnter den Docks hier in Shadowprey habe ich viele Schalentierfallen. Wenn Ihr so freundlich wärt, meine Arbeit zu tun und meine Schalentiere einzusammeln, dann werde ich Euch mit etwas belohnen, das Ihr wollt... Ihr wisst schon, was ich meine, eh? Für jeweils fünf Schalentiere, die Ihr mir bringt, gebe ich Euch einen feinen Blutbauchfisch!", completion = "Echt toll, nichts ist besser als getane Arbeit, vor allem, wenn sie jemand anderes getan hat... eh?", rewards = "Ihr bekommt:\n\nBlutbauchfisch"}
MultiLanguageQuestData['de'][5441] = {title = "Faule Peons", objective = "Benutzt den Großknechttotschläger an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Großknechttotschläger zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, <Volk>. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nVerdammte faule Peons...", progress = "Verdammter fauler B...\n\n Huch? Habt Ihr meinen Totschläger? Habt Ihr Peons dabei erwischt, wie sie bei der Arbeit schliefen?!", completion = "Gut, gut. Vielleicht werden sie es sich in Zukunft zweimal überlegen, bevor sie wieder nachlässig werden! Ich danke Euch für Eure Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5461] = {title = "Der Mensch Ras Frostraunen", objective = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduk zurück.", description = "Die Untoten fürchten das Leben genauso sehr wie die Lebenden den Tod fürchten. Es ist nicht ungewöhnlich, dass ein denkender Untoter alle Überreste seines vorherigen Lebens vollständig zerstört, nachdem er zum Untoten wurde.\n\nLeider benötigen wir, um ein Artefakt zu erschaffen, das Ras Frostraunen wieder in einen Sterblichen zurückverwandeln kann, ein Andenken aus seinen Jahren unter den Lebenden.\n\nIhr müsst Euch zur zerstörten Stadt von Stromgarde begeben, Frostraunens Heim, und nach solch einem Gegenstand suchen. Möge das Glück mit Euch sein, <Name>.", progress = "Ein Andenken der Erinnerung ist ein seltener Fund, <Name>.", completion = "Ich hatte bezweifelt, dass solch ein Gegendstand existieren könnte. Das eröffnet uns definitiv eine unglaubliche Gelegenheit - eine, die wir nicht vergeuden dürfen.\n\nMacht Euch fertig, &lt;Name&gt;, denn das, worum ich Euch bitten werde, wird Euch in die Tiefen der Hölle führen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5462] = {title = "Der Sterbende Ras Frostraunen", objective = "Reist zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern und sucht Leonidas Bartholomäus den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.", description = "Das Andenken muss auf besudeltem Boden korrekt eingestellt werden.\n\nMan erzählt sich, dass Stratholme der Ort sei, an dem Frostraunen dem Lichkönig erlag. Auf diesem blutigen Boden gab er sein Leben - frei und mit einem Motiv -, um einer der Unsterbenden zu werden.\n\nDieser Ort muss gefunden werden.\n\nEs gibt einen untoten Dissidenten der Geißel, der durch die Bansheekönigin befreit wurde, aber der Sache der Argentumdämmerung gegenüber loyal ist. Sucht ihn: Leonidas Bartholomäus der Geachtete. Er könnte mehr wissen. Sucht die Kapelle des Hoffnungsvollen Lichts auf, <Name>.", progress = "Stellt keine Fragen, auf die Ihr keine Antworten wollt.", completion = "&lt;Leonid sieht sich das Andenken an.&gt;\n\nEuer Problem weckt Erinnerungen, von denen ich gehofft hatte, dass sie nie wieder an die Oberfläche kommen würden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5463] = {title = "Menethils Geschenk", objective = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.", description = "Ich sah zu, wie der Mensch Ras Frostraunen seine unsterbliche Seele dem Lichkönig verpfändete. Er setzte den Dolch an seiner eigenen Kehle an und durchschnitt sie mit einem Lächeln von einem Ohr zum anderen. Sein Körper brach in den Grenzen des Pentagramms zusammen. Der Lichkönig stand über dem gefallenen Magier, und mit einer einzigen Bewegung wurde Ras Frostraunen der Lich geboren.\n\n<Leonidas blickt zu Boden und sieht Euch dann an.>\n\nJa, <Volk>, ich erinnere mich. Was Ihr sucht, hat einen Namen - Menethils Geschenk: Der vom Lichkönig gesegnete Boden - heiliger Boden für die Geißel.", progress = "Der Bereich um Menethils Geschenk herum ist außergewöhnlich kalt.", completion = "Ihr platziert das Andenken auf dem besudelten Boden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5464] = {title = "Menethils Geschenk", objective = "Bringt das seelengebundene Andenken zu Leonidas Bartholomäus in den Östlichen Pestländern.", description = "Die Seele des Gefallenen hängt sich an das, was sein ehemaliges Leben repräsentiert, und verwandelt den Gegenstand in ein seelengebundenes Andenken. Ihr hebt den Gegenstand auf und verstaut ihn in Eurem Rucksack.", progress = "<Leonid erschauert.>", completion = "Wie die Seele an dem Andenken hing, so soll sie an der physischen Gestalt von Ras Frostraunen hängen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5465] = {title = "Seelengebundenes Andenken", objective = "Kehrt zu Magistrat Marduk in Darrowehr zurück. Zeigt ihm das seelengebundene Andenken.", description = "Kehrt mit dem Andenken zu Marduk zurück, <Name>. Er wird Euch über die Anwendung instruieren.", progress = "Habt Ihr das Unmögliche getan?", completion = "Ich war sicher, dass Ihr mir als ein weiterer unglückseliger Geist Gesellschaft leisten würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5466] = {title = "Der Lich Ras Frostraunen", objective = "Sucht Ras Frostraunen in Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduk.", description = "Es verbleibt noch eine Aufgabe, <Name>. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber.\n\nBenutzt die Macht des Andenkens gegen die Bestie - seid unerbittlich in Euren Taten! Haltet den Schlägen stand, mit denen das um sich schlagende Biest Euch sicherlich eindecken wird. Gebt dem Schmerz nicht nach!\n\nWenn das Ritual abgeschlossen ist, wird Ras wieder ein Sterblicher sein. An diesem Punkt muss er getötet werden. Schlagt ihn nieder und nehmt Euch seinen menschlichen Kopf.", progress = "Ihr tragt die Bürde von Zehntausenden ruheloser Seelen, <Name>.", completion = "Zehntausende Seele schreien wie eine auf, &lt;Name&gt;! Ihr habt der Geißel und ihren Meistern einen tödlichen Schlag versetzt.", rewards = "Kriegsklinge von DarrowehrFroststachelKrone von DarrowehrIhr bekommt:\n\nStarkwache von Darroheim"}
MultiLanguageQuestData['de'][5481] = {title = "Gordos Aufgabe", objective = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Friedhof von Brill.", description = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.\n\nWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland auf den Friedhof von Brill.", progress = "Wo ist diese nutzlose Monstrosität? Entweder habt Ihr, was ich benötige, oder Ihr verschwindet besser von hier und sucht es.", completion = "Was ist denn das? Düsterkraut?! Ich brauche kein Düsterkraut! Diese hirnlose Fleischmasse pflückt da draußen Gänseblümchen und bringt Gott weiß wie viele Tölpel wie Euch dazu, das Gleiche zu tun. Das sollte keine Beleidigung sein.\n\nNun denn, Ihr seid jetzt hier und das ist das einzig Wichtige. Da ich keine Zeit darauf verschwenden werde, dieser Monstrosität alles noch mal zu erklären, wie wäre es, wenn Ihr das sammelt, was ich wirklich benötige ... Verdammniskraut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5482] = {title = "Verdammniskraut", objective = "Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.", description = "Ihr seht also die Zwickmühle, in der ich mich befinde, <Name>. Dieses Ding da draußen sammelt die falschen Kräuter! Ich werde Euch dafür belohnen, wenn Ihr sammelt, was ich wirklich benötige. Bringt mir genug Verdammniskraut und ich werde Euch eine angemessene Belohnung geben.\n\nSoweit mir bekannt ist, verseucht es gern die Flora in der Nähe des Massengrabs, nördlich des Friedhofes von Brill. Beeilt Euch und hütet Euch vor den Gnollen in dem Gebiet.", progress = "Hoffentlich ist das wichtig... Ich gehe davon aus, dass Ihr das benötigte Verdammniskraut habt?", completion = "Ah, mein Verdammniskraut. Exzellent!\n\n&lt;Jungapotheker Holland reibt gierig seine Hände aneinander.&gt;\n\nDas passt perfekt. Ihr habt mir, äh, der Fürstin heute einen großen Dienst erwiesen, &lt;Name&gt;. Wie versprochen ist hier die Belohnung, die Ihr verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5501] = {title = "Knochenjäger", objective = "Bringt Bibbly F'utzbuckel bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.", description = "Wir sitzen hier auf einer Goldmine, das sage ich Euch – einer Goldmine! Kodoknochen werden die Welt für immer verändern... Ich habe Kunden, die daraus Möbel, Musikinstrumente und sogar Sprengpulver herstellen.\n\nEine Karawane kommt hier vorbei, die meine Kodoknochen mitnimmt und sie dann in Schattenflucht verkauft. Wenn Ihr zum Kodofriedhof südlich von hier gehen und mir zehn Kodoknochen bringen könntet, würde ich Euch dafür etwas anderes geben. Ist das ein Geschäft?", progress = "Habt Ihr die Knochen? Die Karawane wird jeden Moment hier sein. Ich benötige nur noch zehn weitere Kodoknochen, um den Gipfel meiner Karriere zu erreichen. Den Gipfel meiner Karriere, sage ich Euch!", completion = "Ah, prima! Meine Knochen!\n\nIch kann es kaum abwarten, dass die Jungs zuhause mein Gesicht auf dem Titel von Goblin'preneur sehen. Ich werde der reichste Goblin auf der Welt sein... und mein Sportlehrer hat immer gesagt, aus mir würde nie was werden.", rewards = "Ihr bekommt:\n\nKodoknochenhalskette"}
MultiLanguageQuestData['de'][5502] = {title = "Tageseltern der Horde", objective = "Kauft einen Schaumstoffschwertständer bei Blax Flaschenzünder in Orgrimmars Gasse. Bringt anschließend Euren Schützling in das Waisenhaus von Orgrimmar zurück, indem Ihr die Pfeife des Orcwaisenkindes an Waisenmatrone Schlachterbe in der Gasse übergebt.", description = "Ihr wart die ganze Zeit so gut zu mir, <Name>. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön.\n\nIch wünschte, all die anderen Waisenkinder hätten das Glück, die ganzen Sachen zu sehen, die wir gesehen haben. Meint Ihr, wir finden Blax Flaschenzünder wieder und bekommen einen Schaumstoffschwertständer von ihm? Ich glaube, er schiebt noch immer seinen Karren durch die Hauptstraße in der Gasse. Dann könnten alle im Waisenhaus auch ihren Spaß haben!\n\nDanach wird es aber Zeit, nach Hause zurückzukehren.", progress = "Es ist schön, Euch wiederzusehen, <Name>. Habt Ihr die Euch auferlegten Pflichten, für die Ihr Euch während der Kinderwoche freiwillig gemeldet habt, sorgfältig erfüllt?", completion = "Mögen die Geister Euch segnen, &lt;Name&gt;. Ihr habt für Grunz mehr getan, als es jemand anderem je in den Sinn käme. Vielen Dank - Ihr seid der Inbegriff eines Helden der Horde.\n\nEuer Geschenk wird den Waisenkindern sehr gefallen. Es kommt schließlich nicht sehr oft vor, dass sie ein neues Spielzeug bekommen.\n\nGrunz hatte so viel Spaß mit Euch, &lt;Name&gt;. Er hat mich gebeten Euch eines seiner Lieblingstierchen zu geben, damit Ihr Euch stets an ihn erinnert.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchweinehalsbandRattenkäfigSchildkrötenkisteSchneckenhausMagisches LeckerliGriesgrams Bestechungsgeld\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSignal to Despawn Orphan (H)\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5503] = {title = "Anstecknadel der Argentumdämmerung", objective = "Alle, die für die Argentumdämmerung das Böse bekämpfen, müssen unsere Anstecknadel tragen. Wenn Ihr eine solche tragt, erhaltet Ihr das Recht, Belohnungen in Anspruch zu nehmen, die unsere Rüstmeister anzubieten haben.\n\nWährend Ihr die Nadel tragt, könnt Ihr Euch Geißelsteine von erschlagenen Mitgliedern der Geißel holen; das sind Insignien, die sie manchmal besitzen. Beschafft Euch diese Insignien und bringt sie mir. Für alle, die Ihr abgebt, erhaltet Ihr unsere Marke des Heldentums - die Ehrenmarke der Argentumdämmerung.\n\nErfüllt Euer Schicksal, <Klasse>... stürzt Euch noch heute in den Kampf!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAnstecknadel der Argentumdämmerung"}
MultiLanguageQuestData['de'][5504] = {title = "Mäntel der Dämmerung", objective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, <Name>. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr Euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", progress = "Ah, edler <Klasse>!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, &lt;Name&gt;. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5505] = {title = "Der Schlüssel zur Scholomance", objective = "Tja, da ist er, <Name>, der fertige Skelettschlüssel. Ich bin eigentlich absolut sicher, dass dieser Schlüssel Euch Zutritt zur Scholomance verschaffen wird. Es gibt aber nur eine Möglichkeit, um absolut sicher zu sein, dass er wirklich funktioniert. Verschwendet keine Zeit darauf, es auszuprobieren, sage ich.\n\nViel Glück. Möget Ihr auch weiterhin Licht in die Dunkelheit bringen!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSkelettschlüssel"}
MultiLanguageQuestData['de'][5507] = {title = "Mäntel der Dämmerung", objective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den Westlichen Pestländern.", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, <Name>. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", progress = "Ah, edler <Klasse>!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, &lt;Name&gt;. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5508] = {title = "Geißelsteine des Verderbers", objective = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Zwecke sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, <Name>... mit solch mächtigen Wesen ist nicht zu spaßen.", description = nil, progress = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Zwecke sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, <Name>... mit solch mächtigen Wesen ist nicht zu spaßen.", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!\n\nFür die Dämmerung, mein Bruder.", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5509] = {title = "Geißelsteine des Eindringlings", objective = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", description = nil, progress = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nJede Ehrenmarke, die an einen würdigen Empfänger vergeben wird, ist ein Zeichen, dass sich das Schicksal gegen die Geißel wendet. Da mehr und mehr Helden die Geißel in ihren eigenen Ländern bekämpfen, wird die Argentumdämmerung sicherlich in erster Reihe stehen, wenn die Zeit kommt, Krieg über das ultimative Böse der Geißel zu bringen. Ich hoffe, dass der Mut, den Ihr gezeigt habt, um Eure Marke zu erlangen, auch dann den Sieg davontragen wird!", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5510] = {title = "Geißelsteine des Dieners", objective = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", description = nil, progress = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", completion = "Glückwunsch, &lt;Name&gt;... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nDie Marken dienen zwei Zwecken. Erstens können sie verwendet werden, um Euren Stand innerhalb der Argentumdämmerung zu fördern; das könnte Euch zu Möglichkeiten und Belohnungen verhelfen, die unseren geehrten und geachteten Verbündeten vorbehalten sind. Zweitens könnt Ihr sie, zusammen mit Münzen, an unsere Rüstmeister weitergeben, als Bezahlung für einige der kostspieligeren Gegenstände der Dämmerung.\n\nWozu Ihr Euch auch entscheidet, wisset, dass Ihr Euch Eure Anstecknadel verdient. Gut gemacht!", rewards = "Ihr bekommt:\n\nEhrenmarke der Argentumdämmerung"}
MultiLanguageQuestData['de'][5511] = {title = "Der Schlüssel zur Scholomance", objective = "Tja, da ist er, <Name>, der fertige Skelettschlüssel. Ich bin eigentlich absolut sicher, dass dieser Schlüssel Euch Zutritt zur Scholomance verschaffen wird. Es gibt aber nur eine Möglichkeit, um absolut sicher zu sein, dass er wirklich funktioniert. Verschwendet keine Zeit darauf, es auszuprobieren, sage ich.\n\nViel Glück. Mögen Eure Siege Euch auch weiterhin Ruhm und Macht bringen, während Ihr die Scholomance in Schutt und Asche legt!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSkelettschlüssel"}
MultiLanguageQuestData['de'][5513] = {title = "Mäntel der Dämmerung", objective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, <Name>. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", progress = "Ah, edler <Klasse>!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, &lt;Name&gt;. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5514] = {title = "Sold reimt sich auf...", objective = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goldstahl in Gadgetzan.", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goldstahl. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Apotheker, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", progress = "Ja, ich weiß, wer Ihr seid, und ich weiß, warum Ihr hier seid. Dithers hat mich benachrichtigt, bevor Ihr gekommen seid. Lasst uns zum Geschäft kommen, ja?\n\nIch habe eine Form, die Ihr für den Skelettschlüssel verwenden könnt, aber sie wird Euch teuer kommen - fünfzehn Goldstücke im Voraus, keine Verhandlungen. Ich werde die Skelettfragmente für Euch in die Form packen und ich werde Euch auch beibringen, wie der Schaft des Schlüssels ohne jegliche Kenntnisse der Schmiedekunst zu schmieden ist... alles kostenlos.\n\nWer sagt da noch, dass Söldner keine billigen Angebote machen würden!", completion = "Dithers sagte, dass Ihr die Sachen liefern würdet, und das habt Ihr auch getan! Ein Handel ist ein Handel; dann werde ich jetzt mal die Fragmente für Euch in die Form packen.\n\nHat Dithers sie bereits mit Magie erfüllt? Hervorragend... anderenfalls wäre es für Euch ein langer Weg zurück zum Bollwerk gewesen.", rewards = nil}
MultiLanguageQuestData['de'][5515] = {title = "Krastinovs Tasche der Schrecken", objective = "Sucht nach Jandice Barov in Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", description = "Ein großes Gewicht wurde von unseren Herzen genommen, <Name>, aber Eure Aufgabe ist noch nicht vollendet. Krastinovs Meister, Kirtonos, lebt immer noch.\n\nBevor Ihr aber Kirtonos gegenübertretet, müsst Ihr Euch zuerst eine Methode besorgen, mit der Ihr ihn beschwören könnt.\n\nEs heißt, dass Jandice Barov das Blut Unschuldiger von Krastinov zu Kirtonos bringt.\n\nSucht sie in den versunkenen Katakomben der Scholomance und streckt sie nieder. Bringt alle Hinweise zurück, die Ihr findet.", progress = "<Eva verschwimmt immer wieder mal mehr, mal weniger.>", completion = "Die Tasche der Schrecken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5517] = {title = "Der Chromatische Mantel der Dämmerung", objective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", description = "<Bruder/Schwester> <Name> -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", progress = "Seid gegrüßt, mächtiger <Klasse>!  Habt Ihr die Ehrenmarken, um die ich bat? Wenn ihr mir die Marken übergebt, werde ich Euch Euren eigenen Chromatischen Mantel der Dämmerung aushändigen.", completion = "Sehr beeindruckend, &lt;Name&gt; - der Chromatische Mantel der Dämmerung gehört nun Euch!\n\n Solange die Argentumdämmerung Euch gegenüber \"Ehrfürchtig\" eingestellt ist, habt Ihr jederzeit die Möglichkeit weitere Chromatische Mäntel zu erwerben. Ab sofort könnt Ihr sie bei jedem Rüstmeister der Dämmerung erwerben.", rewards = "Ihr bekommt:\n\nChromatischer Mantel der Dämmerung"}
MultiLanguageQuestData['de'][5518] = {title = "Der Ogeranzug der Gordok", objective = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Zwingschraub. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", description = "Wenn Ihr versuchen wollt gegen den König dieser Bruchbude zu kämpfen - und ich denke, dass Ihr genau das vorhabt - dann müsst Ihr erstmal an Hauptmann Krombruch vorbei. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen.\n\nEs stellt sich nur die Frage, wie? Nun, ich bin hier schon eine ganze Weile und ich denke, dass ich Euch einen Ogeranzug anfertigen kann, der ausreicht, um diese Kerle zu täuschen. Das einzige Problem wird seine Stabilität sein - zehn Minuten sind das Maximum. Besorgt mir alles was ich brauche und Ihr bekommt einen Ogeranzug. Ich warte hier solange...", progress = "Von allen Zutaten die ich für die Herstellung des Anzugs brauche, ist das Ogergerbemittel sicherlich am schwersten zu beschaffen; doch eine Etage höher sollte noch etwas zu finden sein. Ok, ist schwer zu sagen, wenn einen diese Gefangenenkugel hier festhält...\n\nNa egal, bringt mir die benötigten Sachen und ich mache Euch einen so guten Ogeranzug, das Captain Kromcrush Euch für einen seiner Oger hält.", completion = "Das sollte gehen. Ein Schnitt hier, eine Stich da... - das wird ein richtiges Meisterwerk!  &lt;Ein breites Grinsen zeichnet sich im Gesicht des Goblins ab.&gt;\n\nHier, damit seid Ihr vorbereitet. Denkt daran - der Ogeranzug ist alles andere als haltbar. Nachdem Ihr ihn angezogen habt, bleiben Euch zehn Minuten bevor er auseinanderfällt und dann ist's aus mit der Täuschung! Benutzt ihn erst kurz bevor Ihr Kromcrush begegnet. Und nicht vergessen... Er wird zwar denken das IHR einer seiner Oger seid, doch schützt er nicht Eure Gruppenmitglieder!", rewards = "Ihr bekommt:\n\nOgeranzug der Gordok"}
MultiLanguageQuestData['de'][5519] = {title = "Der Ogeranzug der Gordok", objective = "Ihr braucht einen weiteren Ogeranzug, richtig?  Da ich wohl so schnell nirgendwo hingehe - bringt mir einfach die gleichen Sachen, um die ich Euch zuvor gebeten habe und ich fertige Euch einen weiteren Ogeranzug an.", description = nil, progress = "Ihr braucht einen weiteren Ogeranzug, richtig?  Da ich wohl so schnell nirgendwo hingehe - bringt mir einfach die gleichen Sachen, um die ich Euch zuvor gebeten habe und ich fertige Euch einen weiteren Ogeranzug an.", completion = "Bitte sehr, &lt;Name&gt; - Zieht dieses Ding an und Ihr habt zehn Minuten Zeit, um zu tun, was immer Ihr wollt. Alles gute!\n\nOh, und falls Ihr einen Schlüssel findet der mich hier herausholen könnte,  LASST ES MICH VERDAMMT NOCHMAL WISSEN!!!", rewards = "Ihr bekommt:\n\nOgeranzug der Gordok"}
MultiLanguageQuestData['de'][5521] = {title = "Der Chromatische Mantel der Dämmerung", objective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den Westlichen Pestländern.", description = "<Bruder/Schwester> <Name> -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nChromatischer Mantel der Dämmerung"}
MultiLanguageQuestData['de'][5522] = {title = "Leonidas Bartholomäus", objective = "Bringt die gefrorenen Eier zu Leonidas Bartholomäus in den Östlichen Pestländern.", description = "Ich habe eine Botschaft von meinem Meister Vectus erhalten. Na ja, die Botschaft war nicht wirklich von Vectus... sie war von jemandem namens Leonidas Bartholomäus. Ich kenne Leonidas nicht, aber er kannte meinen Meister, und niemand kennt meinen Meister, außer er lässt es zu.\n\nLeonidas sagt, dass Vectus die Dracheneier will. Er möchte, dass Ihr sie ihm zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern bringt.\n\nDas tut weh! Warum Ihr? Vertraut Vectus mir nicht? Ach, egal... nehmt einfach die Eier und berichtet Leonidas, dass ich getan habe, was unser Meister befahl.", progress = "Ihr seid also derjenige, der an der Blackrockspitze Böses im Schilde führt, ja? Habt Ihr, worum ich gebeten habe?", completion = "Ah, sehr gut. Ihr kennt die böse Macht nicht, für die Ihr gearbeitet habt, aber nun werdet Ihr die Wahrheit erfahren. Und fürchtet Euch nicht - ich bin kein Diener dieses Meisters. Ich bin Leonid Barthalomew, bekannt als 'der Geachtete' bei meinen Brüdern der Argentumdämmerung.\n\nIch habe Tinkee mit einer List dazu gebracht, Euch und die Dracheneier zu mir zu schicken. Und es ist gut, dass mein Trick erfolgreich war, denn wenn diese Eier das geplante Ziel erreicht hätten, wäre eine große Macht in die Hände des Feindes gefallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5524] = {title = "Der Chromatische Mantel der Dämmerung", objective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", description = "<Bruder/Schwester> <Name> -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nChromatischer Mantel der Dämmerung"}
MultiLanguageQuestData['de'][5525] = {title = "Befreit Knot!", objective = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", description = nil, progress = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", completion = "Vielen Dank, dass Ihr mich befreit habt! Ihr seid meine Nummer eins.\n\n Ich hab's doch gewusst, dass ich mein Leben nicht als Ogerhappen beende!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5526] = {title = "Die Splitter der Teufelsranke", objective = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Reliquiar der Reinheit, um darin den Splitter sicher zu versiegeln, und bringt das versiegelte Reliquiar zu Rabine Saturna in Nachthafen auf der Mondlichtung.", description = "Euer Wissen über Eldre'Thalas – Düsterbruch – in Feralas wird nun gebraucht, <Name>. Im Ostteil der zerstörten Stadt erstreckt sich das Herrschaftsgebiet von Alzzin dem Wildformer. Begebt Euch mit der gebotenen Eile und Tapferkeit dorthin.\n\nDie verderbte Frucht des Gedeihens, die Teufelsranke, sollte sich in Alzzins Nähe befinden. Versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen, wenn er fällt. Versiegelt diese in dem Reliquiar und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", progress = "Mit dem versiegelten Reliquiar der Reinheit in unserem Besitz, wird es uns nicht nur möglich sein, eine verderbte Gefahr aus dieser Welt zu bannen. Stattdessen können wir sie sogar in Ruhe studieren. Vielleicht entdecken wir mit der Zeit neue Wege, um die Besudelung der Verderbnis zu bekämpfen, welche Azeroth seit jeher bedroht.\n\nIch bin sicher, dass Milli es so gewollt hätte...", completion = "Es ist vollbracht, &lt;Klasse&gt;. Der Zirkel des Cenarius steht in Eurer Schuld. Der Krieg ist noch lange nicht zu Ende, doch mit Eurer Hilfe haben wir eine große Schlacht gegen die Mächte gewonnen, die uns die Verdammnis bringen wollen.\n\nBitte akzeptiert dies als Zeichen unserer ewigen Dankbarkeit. Wisset &lt;Name&gt;, dass der Zirkel des Cenarius Euch für diese Tat als einen Helden willkommen heißt. Habt dank.", rewards = "Millis SchildAuf Euch wartet eine dieser Belohnungen:\n\nMillis Lexikon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5527] = {title = "Ein Reliquiar der Reinheit", objective = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nachthafen auf der Mondlichtung zurück.", description = "Zuerst müssen wir einen Behälter finden, in dem eine sehr stark verderbte Substanz transportiert werden kann, ohne das der Träger Nebenwirkungen davonträgt. Meines Wissens nach, gibt es nur einen Gegenstand der geeignet ist, darin etwas so abscheuliches wie eine Teufelsranke aufzubewahren: ein Reliquiar der Reinheit.\n\nTief in der Einöde von Silithus befinden sich die Überreste des Nachtelfenpostens Südwind. Vor vielen, vielen Jahren gab es dort ein Reliquiar. Wenn wir Erfolg haben wollen, müsst Ihr die Ruinen durchsuchen, in der Hoffnung dort ein Reliquiar der Reinheit zu finden.", progress = "Ein Requiliar der Reinheit ist schon für sich alleine ein Artefakt. Nur wenige wurden je hergestellt und von fast allen sagt man, dass sie im Laufe der Zeit verloren gingen.\n\n Ich muss gestehen, dass ich nun schon eine ganze Weile von dem Requiliar beim Südwindposten wusste. Ehrlich gesagt, mit den aufkommenden Unruhen in Silithus, dachte ich unser Geheimnis als das zu beIassen, was es ist - ein Geheimnis. Wenn zuviel bekannt würde, täte dies nur die Aufmerksamkeit des Feindes erregen.\n\nLeider ist die Zeit der Selbstgefälligkeit jetzt vorbei, insbesondere was die Situation in Eldre'Thalas angeht. Wir müssen handeln!", completion = "Ihr seid in der Tat so einfallsreich wie man sich erzählt. Der Zirkel des Cenarius ist gesegnet, Euch auf unserer Seite zu haben.\n\nMit dem Reliquiar in unseren Händen, empfinde ich das erste mal Erleichterung. Es fällt mir jetzt leichter darum zu bitten, dass Ihr Euch nicht nur einen bösartigen Dämonen gegenüber stellt, sondern Ihr sollt vielmehr noch, einen gefährlichen Gegenstand bergen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5528] = {title = "Der Gordokgeschmackstest", objective = "Ihr jetzt de' Big Boss hier. Also kriegen freie Kostproben meiner besseren Gebräue! Diese Tränke werden Euch verstärken UND Euch Schädel weghauen! Das ist da' guta Zeug, Chef... Ihr versuchen und dann Kreeg glauben!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGrüner GordokgrogKreegs Hauwegstarkbier"}
MultiLanguageQuestData['de'][5529] = {title = "Verseuchte Jungtiere", objective = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts zurück.", description = "Die Argentumdämmerung hat kürzlich erfahren, dass die Geißel ihren eigenen verseuchten Drachenschwarm erschafft! Wir müssen sie stoppen - wenn die Geißel eine Großdrachenstreitmacht auf die Beine stellt, wird sie unbehelligt ganz Azeroth verwüsten!\n\nIhre Totenbeschwörer züchten verseuchte Großdrachen in Scholomance, in der Mitte des Darromersees.\n\nBegebt Euch zur Scholomance und tötet so viele Jungtiere wie nur möglich...bevor sie größer werden können!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Es wird lange dauern, bis sie ein weiteres Gelege von Großdrachen züchten können.\n\n... Zumindest hoffe ich das!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5531] = {title = "Betina Moppelzink", objective = "Bringt die gefrorenen Eier zu Betina Moppelzink.", description = "Die Eier, die Ihr gebracht habt, sollten in Experimenten der Geißel verwendet werden, um einen verseuchten Drachenschwarm zu erschaffen. Diese gefrorenen schwarzen Dracheneier wären für ihre Studien unersetzlich gewesen und hätten ihren Zeitplan sicherlich beschleunigt.\n\nNun ist es an der Zeit, dass wir ihre Forschung beenden.\n\nBringt die gefrorenen Eier zu Betina Moppelzink da draußen. Sie ist in Wissenschaft und Alchemie sehr bewandert und hat eine Waffe hergestellt, die wir gegen die Geißel einsetzen können. Mit Eurer Hilfe werden wir ihnen einen schweren Schlag versetzen.", progress = "Hallo, <Name>! Ich habe gehört, Ihr seid mit einigen Dracheneiern hier? Na, dann lasst sie uns mal ansehen!", completion = "Da sind sie ja! Und in einem so hübschen Behälter. Die perfekte Größe!\n\nWir werden diese Eier an einem sicheren Ort aufbewahren, damit wir sie später untersuchen können, aber jetzt benötigen wir das Ding, in dem Ihr sie hergebracht habt.\n\nIch habe ein Gerät mit einer sehr speziellen Verwendung gebaut: Es dient dazu, die untoten Gelehrten von Scholomance zu vernichten. Sie studieren Großdrachen in ihren Bemühungen, einen verseuchten Drachenschwarm zu schaffen, und wir müssen ihre Fortschritte stoppen.\n\nIch nenne das Gerät Dämmerungstrickfalle, weil ... na ja, ich nicht sicher bin, ob es funktioniert!\n\nWürdet Ihr es für uns herausfinden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5533] = {title = "Scholomance", objective = "Sprecht mit Alchemist Arbington an der Zugwindspitze, westliche Pestländer.", description = "Auf der Insel Darrowehr liegt die Scholomance - ein elendes Zentrum der Totenbeschwörung und des Bösen der Geißel. Unser Feind lebt im Inneren und führt unaussprechliche Taten der Verderbtheit an nichts ahnenden Opfern aus... zumindest vermuten wir das. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nAlchemist Arbington weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert bewiesen und nun vertraue ich Euch diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", progress = nil, completion = "Grüße, &lt;Klasse&gt;. Ich habe einen Großteil meiner Studien der Scholomance gewidmet und glaube, dass ich eine Möglichkeit kenne, wie Ihr einen Schlüssel erlangen könnt, der Euch nach Belieben durch die Vordertür bringt.\n\nIch kann mir nur vorstellen, welch schreckliche Dinge im Inneren zu sehen sein werden, &lt;Name&gt;. Ich weiß nicht, wie Ihr heroischen Typen das manchmal ertragt ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5534] = {title = "Kim'jaels 'fehlende' Ausrüstung", objective = "Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jael in Azshara.", description = "Was?! Was?!\n\nDas war nicht gut genug für Euch? Wisst Ihr, wie teuer diese Sprengstoffe sind? Die kosten... ach, egal. Ihr wollt also echtes Geld machen, ja? Na dann... so läuft das im Geschäftsleben: Ihr beweist, dass Ihr ein wertvoller Angestellter seid und dann werdet Ihr entsprechend belohnt, nachdem Ihr schön brav durchgehalten habt.\n\nFalls Ihr also ein \"wertvoller\" Angestellter seid, dann begebt Euch zu den Ruinen von Eldarath und bringt mir irgendeine Rune, nach der diese Blutelfen gesucht haben. Anscheinend befindet sie sich im Besitz der Naga.", progress = "Also, <Name>? Wo ist die Rune? Ihr seid doch ein guter Angestellter, nicht wahr? Ihr seid doch hier, um zu helfen?\n\nZwingt mich nicht, noch mal zu überdenken, ob ich Euch das zahle, was wir vereinbart haben. Was? Oh, wir haben gar nichts vereinbart? Na toll ... dann lasst Euch Zeit ... wisset nur, dass es wesentlich weniger sein wird, wenn Ihr lange braucht.", completion = "Haha! Großartig!\n\nIch werde bestimmt herausfinden, wofür das ist und warum Magus Rimtori - die Kuh, die mich angeheuert hat - es haben wollte. Ha! Jetzt habe ich Euch, ihr stinkenden Blutelfen! Kim'jael! Ha! Denen werde ich zeigen, wer hier die Ratten sind!\n\nDas war prima, &lt;Name&gt;. Heißen Dank. Hier, nehmt diese Münze und verschwindet ... ich muss mich an die Arbeit machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5535] = {title = "Spirituelle Unruhe", objective = "Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.", description = "Vor langer Zeit gehörten die Hochgeborenen zu den mächtigsten Schülern des Arkanen, die die Nachtelfen je hervorgebracht hatten. Die Verderbnis, die mit solchen Studien einhergeht, brachte großes Unglück über die Gesellschaft der Nachtelfen und wirkte sich in großem Umfang auf Azeroth aus... wie Ihr sicherlich wisst.\n\nIch habe den Schildwachen versprochen, dass ich die Geister aus ihren sterblichen Banden befreie, wenn ich sie finde. Wenn Ihr dasselbe tun würdet, kann ich Euch sicherlich belohnen.\n\nDie Geister spuken im Schattensangschrein, von hier aus im Nordosten.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Danke für Eure Hilfe. Die Geister haben ihren Frieden und die Bedrohungen, die ihr Verlangen nach dem Arkanen angezogen hat, wurden dezimiert.\n\nIch bin sicher, dass beide Seiten des Konflikts, der Azeroth verheert, sehen werden, dass Ihr über solchen Dingen steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5536] = {title = "Ein Land voller Hass", objective = "Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zum Eschental zurück.", description = "Die Satyrn, entstellte und böse Aspekte der Nachtelfen, infizieren jetzt die hochheiligen Länder, die einst von Cenarius bereist wurden. Ich kann nicht für die Nachtelfen sprechen, wenn es um die ganzen Gräueltaten geht, die diese dämonischen Kreaturen begangen haben, aber ich habe der Erdenmutter einen Eid geschworen, den Elfen zu helfen, das Land von solch einer Plage zu befreien.\n\nIch bin sicher, dass Ihr Euch beweisen würdet, wenn Ihr mir bei der Reinigung helfen würdet.\n\nNordöstlich von hier könnt Ihr den Haldarrklan finden. Kehrt zu mir zurück, nachdem Ihr Euch gegen ihre Stärke bewiesen habt.", progress = "Wie läuft Eure Schlacht gegen die Satyrn, <Klasse>?\n\nSind sie so stark, wie Ihr dachtet? Stärker? Oder vielleicht waren sie nichts angesichts Eurer eigenen Macht?", completion = "Gut gemacht, &lt;Klasse&gt;. Ich sehe, dass Ihr nicht nur geschickt, sondern auch schlau seid. Solche Kreaturen zu besiegen ist ein Zeugnis Eurer Loyalität zu den Geschöpfen der Erdenmutter, auch wenn Ihr sie nicht als Eure Gottheit anerkennt. Man findet sie in allen Dingen auf diesem Planeten und darüber hinaus. Ihre Augen, eines dunkel und eines hell, ziehen über den Himmel und blicken immer auf uns herab.\n\nBitte, nehmt diesen kleinen Stapel Münzen als Wertschätzung dessen, was Ihr getan habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5537] = {title = "Skelettfragmente", objective = "Bringt 15 Skelettfragmente zu Alchemist Arbington an der Zugwindspitze in den Westlichen Pestländern.", description = "Um in die Scholomance zu gelangen, benötigt ihr einen Dietrich. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, <Name>. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", progress = "So morbid es vielleicht klingt, aber wir werden einen guten Vorrat geeigneter Skelettfragmente benötigen, um die äußere Schicht des Schlüssels herzustellen. Man nennt so etwas nicht umsonst Skelettschlüssel, wisst Ihr.", completion = "Das wird funktionieren, &lt;Name&gt;! Jetzt bin ich dran... ich werde sie mit einem geeigneten Härter tränken, wodurch sie den starken Schmiedeprozess überstehen werden, den sie schließlich durchlaufen müssen.\n\nDer nächste Schritt wird sein, eine geeignete Form für den Schlüssel zu bekommen. Ich kenne einen Goblin-Schmied in Tanaris, der in der Vergangenheit Formen für ähnlich makabre Dinge hergestellt hat. Er arbeitet für den üblichen Auftraggeber der Goblins - den höchsten Bieter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5538] = {title = "Sold reimt sich auf...", objective = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goldstahl in Gadgetzan.", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goldstahl. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Alchemist, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", progress = "Ja, ich weiß, wer Ihr seid, und ich weiß, warum Ihr hier seid. Arbington hat mich benachrichtigt, bevor Ihr gekommen seid. Lasst uns zum Geschäft kommen, ja?\n\nIch habe eine Form, die Ihr für den Skelettschlüssel verwenden könnt, aber sie wird Euch teuer kommen - fünfzehn Goldstücke im Voraus, keine Verhandlungen. Ich werde die Skelettfragmente für Euch in die Form packen und ich werde Euch auch beibringen, wie der Schaft des Schlüssels ohne jegliche Kenntnisse der Schmiedekunst zu schmieden ist... alles kostenlos.\n\nWer sagt da noch, dass Söldner keine billigen Angebote machen würden!", completion = "Arbington sagte, dass Ihr die Sachen liefern würdet, und das habt Ihr auch getan! Ein Handel ist ein Handel; dann werde ich jetzt mal die Fragmente für Euch in die Form packen.\n\nHat Arbington sie bereits mit Magie erfüllt? Hervorragend... anderenfalls wäre es für Euch ein langer Weg zurück zur Chillwindspitze gewesen.", rewards = nil}
MultiLanguageQuestData['de'][5541] = {title = "Munition für Schlingerschuss", objective = "Bringt Schlingerschuss' Munition zu Hegnar Schlingerschuss in Dun Morogh.", description = "Hegnar Schlingerschuss verkauft Gewehre an der Straße nach Ambossar. Scharfschützen und Mörsertrupps verbringen viel Zeit damit, in der Nähe seines Geschäfts zu üben, und er braucht ständig neue Munition.\n\nAber... die letzte Munitionskiste, die ich ihm geschickt habe, ist unterwegs verloren gegangen. Mein Kurier sagte, er lagerte nahe des Graufelsbaus, als Wendigos ihn davonjagten... und der Dummkopf hat Schlingerschuss' Munition zurückgelassen!\n\n<Name>, könnt Ihr diese Munition beschaffen und zu Schlingerschuss bringen? Er wartet darauf und ihm gehen bestimmt bald die Vorräte aus.", progress = "Ich hoffe, Ihr seid nicht wegen Munition hier, denn ich habe fast keine mehr!", completion = "Wunderbar, mehr Munition! Die Lieferung vom alten Loslor ist endlich da! Na ja, die Munition mag etwas verspätet ankommen, aber wie schon mein Großvater mir immer gesagt hat: Besser spät als nie!\n\nVielen herzlichen Dank, &lt;Name&gt;. Ich habe bereits Käufer, die begierig auf dieses Zeug warten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5542] = {title = "Dämonenhunde", objective = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Wenn Ihr hier bleiben wollt, bitte ich Euch nur, Euren Unterhalt zu verdienen. Wir haben hier viele Plagegeister, denen etwas 'Disziplin' gut tun würde.\n\nIhr könnt mit den Seuchenhunden und den kleinen Seuchenhunden beginnen.\n\nViel kann ich Euch im Gegenzug nicht anbieten, aber ein warmes Mahl und ein wenig Konversation wäre Euch garantiert, wenn Ihr erfolgreich seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Kommt. Ruht Euch aus. Lasst uns essen und von längst vergangenen Tagen sprechen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5543] = {title = "Blutgefärbter Himmel", objective = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", description = "Wehe jenen, die töricht genug sind, in die Pestländer zu wandern. Alle Arten der Verderbtheit bewohnen diese Wälder - von den fanatischen Anhängern des Scharlachroten Kreuzzugs, die jeden töten, der nicht das Zeichen der Kreuzzügler trägt, bis hin zur mordlustigen Geißel, die ihre Anzahl vergrößern will, indem sie ihre Ränge mit Untoten füllt.\n\nSogar die Tierwelt wurde in wilde, menschenfressende Bestien verwandelt. Ich bitte Euch, die zu vernichten, die vom Firmament aus zuschlagen: die Seuchenfledermäuse.", progress = nil, completion = "Ihr seid ein leuchtendes Beispiel des Anstands, &lt;Volk&gt;! Es ist lange her, dass ich das Blut von Helden in meinen Adern gefühlt habe. Eure Taten der Tapferkeit sind wahrlich erhebend!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5544] = {title = "Aassammlung", objective = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", description = "Meine Essensvorräte gehen zur Neige, <Volk>. Ich schäme mich zuzugeben, dass ich möglicherweise nicht genug Nahrung habe, um sie mit Euch zu teilen.\n\nKönnt Ihr einem alten Mann bei einer einfachen Aufgabe helfen? Hier in der Umgebung sind Aaswürmer die einzigen Tiere, die von den Verheerungen der Seuche unbeeinflusst blieben. Wenn sie auch ziemlich langweilig schmecken, kann das Fleisch der Würmer doch leicht monatelang aufbewahrt werden. Ich werde einige hundert Pfund benötigen, um meine Vorräte für den kommenden Winter aufzustocken!", progress = "Ihr werdet Euch an den Geschmack gewöhnen, <Volk>.", completion = "Möge das Licht über Euch wachen! Gesegnet seid Ihr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5545] = {title = "Ein Bündel Probleme", objective = "Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", description = "Ich habe hier ein echtes Problem. Ich habe einen Liefertermin für eine Bestellung Holz und mir läuft die Zeit davon. Die Wölfe und Bären nördlich von hier haben meine Arbeiter von den Holzbündeln verjagt, die sie bereits gefällt hatten.\n\nIch habe bereits mit Stellvertreter Rainer darüber gesprochen, dass die Tiere entfernt werden müssen, aber ich brauche jemanden, der das Holz für mich holt. Wenn Ihr acht Holzbündel für mich holen würdet, könnte ich den Termin vielleicht noch einhalten.", progress = "Der Termin kommt immer näher, <Klasse>. Beeilt Euch bitte und holt diese Holzbündel.", completion = "Exzellent! Dank Euch sollte ich die Bestellung rechtzeitig zusammenstellen können. Um Euch meine Dankbarkeit zu zeigen, würde ich Euch gern ein paar Münzen als Entschädigung für Eure Mühen anbieten.\n\nVielen Dank und lebt wohl.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5561] = {title = "Kodozusammentrieb", objective = "Bringt 3 gezähmte Kodos sowie den Kodokombobulator zu Smeed Schraubenbuddel bei Schraubenbuddels Lager.", description = "Bibbly glaubt, dass er der einzige Goblin in Desolace sei, der weiß, wie man Geld macht. Tja, die einzige Karawane, die mutig genug ist, diese Gebiete zu bereisen, verlässt sich auf mich. Nachdem ich gelernt habe, wie man alternde Kodos mit meinem Kodokombobulator verjüngt und kontrolliert, sind die Karawanenbesitzer Cork und Rigger mit mir eine Partnerschaft eingegangen.\n\nNehmt den Kombobulator und wendet ihn auf jeden beliebigen alten oder alternden Kodo an; er wird das Biest in einen gezähmten Kodo verwandeln und es zwingen, Euch zu folgen. Wenn Ihr einen Kodo gezähmt habt, bringt ihn zu mir her.", progress = "Die Karawane wird bald hier sein; habt Ihr die fünf gezähmten Kodos, um die ich gebeten hatte?", completion = "&lt;Smeed Scrabblescrew beginnt zu zählen.&gt;\n\nDrei, vier und fünf... hervorragend, ich habe um fünf gezähmte Kodos gebeten und ich habe fünf gezähmte Kodos bekommen... Ich werde reich sein... ja, sehr reich. Ich würde zu gern den Ausdruck auf Bibblys grünem Gesicht sehen, wenn er von meinem Erfolg hört!", rewards = "Stiefel eines KodoviehdiebsZänkerschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5581] = {title = "Portale der Legion", objective = "Verbannt 6 Portale beim Zirkel der Mannoroc und kehrt dann zu Felgur Zweischneid zum Geistwandlerposten zurück.", description = "Seht - die Hand von Iruxos.\n\nIch habe sie selbst einem der Anführer der Brennenden Klinge abgenommen.\n\nIhr müsst sie besitzen, wenn die Dämonenportale beim Zirkel der Mannoroc gebannt werden sollen... und genau darum bitte ich Euch nun.\n\nDie Bedrohung durch die Dämonen steigt stetig und wir müssen diese Portale schließen, um die Flut der Dämonen, die in diese Welt eindringen, zu stoppen.", progress = "Habt Ihr die Dämonenportale in Mannorocs Koven verbannt?", completion = "Ich muss Euch loben, &lt;Name&gt;. Eure Bemühungen haben beim Kampf gegen die dämonische Bedrohung sehr geholfen, und ganz Azeroth ist jetzt sicherer.", rewards = "BindungsstabArmschiene der PortaleSchiftung der VersiegelungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5582] = {title = "Gesunde Großdrachenschuppe", objective = "Bringt die gesunde Großdrachenschuppe zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Dies ist eine Schuppe von einem verseuchten Großdrachen-Jungtier. Aber im Gegensatz zu den anderen pockennarbigen, eiternden Schuppen an dem kleinen Biest ist diese rare Schuppe gesund und unbeschädigt.\n\nBetina Moppelzink wird eine Probe davon für Forschungen haben wollen.", progress = "<Name>, habt Ihr mir etwas zu zeigen?", completion = "Exzellent! Das wird für meine ständigen Studien der Machenschaften der Geißel unschätzbar sein. Vielen Dank, &lt;Name&gt;, und falls Ihr noch mehr von diesen Schuppen findet, bringt sie mir bitte!", rewards = nil}
MultiLanguageQuestData['de'][5601] = {title = "Schwester Pamela", objective = "Sucht Pamela Rotpfad in Darroheim.", description = "Ich bin während des großen Krieges aus Lordaeron geflohen und hatte das Glück, entkommen zu können, bevor die Geißel durch meine Heimat fegte und sie zu einem verseuchten Alptraum machte! Ich hatte Glück, aber meine Familie nicht. Ich fürchte, dass sie während der Schlacht von Darroheim getötet wurden.\n\nDarroheim ist ein Dorf in den Östlichen Königreichen, eingebettet in die südlichen Hügel dessen, was heutzutage Östliche Pestländer genannt wird. Würdet Ihr Euch dorthin begeben und nach meiner Familie suchen? Ich vermisse sie so sehr, besonders meine kleine Schwester Pamela.\n\nBitte, sucht sie für mich!", progress = nil, completion = "Wo ist meine Schwester Jessica? Sie ist vor langer Zeit fortgegangen, als ich noch ein kleines Mädchen war. Sie weinte so sehr, als sie fort ging. Ich weiß nicht, warum sie geweint hat! Vielleicht ist sie hingefallen und hat sich ihren Zeh gestoßen.\n\nAls Jessica hier war, haben wir immer gespielt und getanzt und hübsche Blumen rund um das Haus gepflückt. Und manchmal haben wir uns versteckt, wenn wir gesehen haben, dass Papa kam. Dann sind wir aus dem Versteck gekommen und haben ihn überrascht!\n\nKomm zurück, Jessica! Wenn du zurückkommst, dann kommt Papa vielleicht auch und wir können wieder zusammen spielen ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5621] = {title = "Gewänder des Mondes", objective = "Sucht die Schildwache Shaya und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morgenglanz in Dolanaar zurück.", description = "Ich brauche Eure Hilfe, <Name>. Ich kann hier nicht weg, denn ich muss hier die anderen Schüler unterweisen, doch Ihr könntet einer unserer verwundeten Schildwachen direkt südlich von Dolanaar helfen. Sie wurde beim Patrouillieren der Stadt verletzt und benötigt unsere Hilfe. Ihr Name ist Shaya.\n\nWenn Ihr sie findet, heilt ihre Wunden, und stärkt dann ihren Körper mit Euren Zaubern. Das wird sie zumindest etwas länger vor Schaden bewahren, wenn es wieder hart auf hart kommt. Kehrt zu mir zurück, nachdem Ihr Eure Pflicht gegenüber Elune erfüllt habt.", progress = nil, completion = "Ihr habt Eure Sache gut gemacht und Elune gedient. Dafür danke ich Euch.\n\nBitte, nehmt diese Robe als ein Zeichen meiner Dankbarkeit. Sie bedeutet, dass Ihr Euch einen Platz in unserem Orden verdient habt. Wenn Ihr wollt, tragt sie mit Stolz, doch wie auch immer Ihr Euch entscheidet - wir werden Euch immer als einen der unsrigen anerkennen.\n\nGeht mit Elune, &lt;Name&gt;, und danke.", rewards = "Ihr bekommt:\n\nMondroben von Elune"}
MultiLanguageQuestData['de'][5622] = {title = "Elune geneigt", objective = "Sprecht mit Laurna Morgenglanz in Teldrassil.", description = "<Name>, sobald Eure Aufgaben hier im Laubschattental abgeschlossen sind, müsst Ihr nach Dolanaar reisen. Dort werdet Ihr Laurna Morgenglanz finden. Sie wird Euch weiter in den Dingen Elunes unterweisen und bei ihr werdet Ihr Euch Eure ersten Gewänder verdienen, die Eure Position als <Priester/Priesterin> von Elune kennzeichnen.\n\nSeid vorsichtig und möget Ihr auf Euren Reisen beschützt werden.", progress = nil, completion = "Ich freue mich, dass Shanda Euch zu mir geschickt hat, &lt;Name&gt;. Junge &lt;Klasse&gt; die Wege von Elune zu lehren, macht mir große Freude.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5623] = {title = "Dem Licht geneigt", objective = "Sprecht mit der Priesterin Josetta im Wald von Elwynn.", description = "Ich grüße Euch, <junger Priester/junge Priesterin>. Die Zeit ist gekommen, mehr über unsere Religion zu lernen. Nachdem Ihr Eure Aufgaben hier in Nordhain abgeschlossen habt, sucht bitte Priesterin Josetta in Goldhain auf. Sie kann Euch noch mehr beibringen und hat gehört, dass Ihr in den Wegen des Lichts gut voranschreitet. Sie freut sich darauf, Euch weiter unterrichten zu können.", progress = nil, completion = "Schön, dass Ihr angekommen seid, &lt;Name&gt;. Wir haben viel über Eure Zukunft und Euren Pfad im Licht zu bereden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5624] = {title = "Gewänder des Lichts", objective = "Sucht die Wache Roberts und heilt seine Wunden mithilfe von 'Blitzheilung'.", description = "Normalerweise stelle ich den Gefolgsleuten des Lichts eine kleine Herausforderung, um ihre Fertigkeiten zu prüfen. Ich möchte sehen, ob sie es wert sind, ihre ersten Roben zu tragen - sie sind ein Zeichen, dass die Kirche <den Priester/die Priesterin> nach außen hin trägt und unterstützt.\n\nDoch hier ist die Situation etwas anders. Einer der Bürger von Goldhain sah eine verletzte Wache nahe dem See östlich von hier. Er heißt Roberts. Sucht ihn, heilt ihn, stärkt seinen Körper und kehrt hierher zurück. Wenn Ihr das für mich tun könnt, dann werde ich Eure Prüfung als bestanden ansehen.", progress = "Wie Ihr vielleicht schon erfahren habt, ist unsere Heilmagie lebenswichtig für das Überleben unseres Volkes in diesen harten Zeiten... insbesondere für Abenteurer und Helden, die zu Waffen und Magie greifen, um die verschiedensten Gefahren zu bekämpfen.\n\nIhr tätet gut daran, Euch immer der Wichtigkeit dieser Fertigkeit zu erinnern. Dies, zusammen mit 'Seelenstärke', sorgt dafür, dass Eure Kameraden im Kampf wesentlich fähiger sein werden, denn sie können dann eine größere Anzahl Treffer aushalten.\n\nLasst keinen abschätzig über die Macht Eurer Magie reden.", completion = "Ausgezeichnet, &lt;Name&gt;. Mit einer weiteren gesunden Wache, die dort draußen die Stadt unterstützt, werden wir viel sicherer sein. Ich freue mich zu sehen, dass Ihr bereits lernt, Eure Fähigkeiten weise einzusetzen. Wenn Ihr irgendwann einmal glaubt, für eine weitere Ausbildung bereit zu sein, dann kommt bitte zu mir zurück. Doch fürs Erste nehmt diese Robe hier. Andere werden dann wissen, dass Ihr unserem Orden angehört. Wenn Ihr sie nicht tragen wollt, ist auch das in Ordnung. Später wird es weitere Prüfungen geben und diese Robe ist dafür nicht erforderlich.", rewards = "Ihr bekommt:\n\nFraterroben des Lichts"}
MultiLanguageQuestData['de'][5625] = {title = "Gewänder des Lichts", objective = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", description = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen. Doch um ehrlich zu sein, gibt es wichtigere Dinge, um die ich mich kümmern muss. Bürger von Kharanos kamen gerade hierher und erzählten mir von einem verletzten Gebirgsjäger direkt außerhalb der Stadt im Süden - sein Name ist Dolf.\n\nWenn Ihr Dolf heilt und ihm 'Seelenstärke' gebt, werde ich das als erfolgreiche Prüfung ansehen. Wie klingt das?", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr tragt das Licht in Euch, so viel ist klar.\n\nHier, nehmt diese Robe. Sie dient als Zeichen Eurer Rolle innerhalb der Kirche und wird den Leuten dabei helfen, Euch als &lt;Klasse&gt; zu erkennen - tragt sie, wann immer Ihr möchtet.\n\nIhr werdet Euch später weiteren Prüfungen unterziehen müssen. Tut, was Ihr könnt, um etwas über Eure Fähigkeiten und Eure Möglichkeiten zu erfahren. Versucht Euch einmal allein an ein oder zwei Kämpfen und dann mit anderen Reisenden zusammen.\n\nUnd keine Sorge ... in Euch steckt sehr viel Macht.", rewards = "Ihr bekommt:\n\nFraterroben des Lichts"}
MultiLanguageQuestData['de'][5626] = {title = "Dem Licht geneigt", objective = "Sprecht mit Maxan Anvol in Dun Morogh.", description = "He! <Name>! Habt Ihr einen Moment Zeit?\n\nIhr seid dem Licht jetzt lange genug gefolgt, um den Weg zu Maxan Anvol in Kharanos zu finden. Er wird Euch mehr über den Weg beibringen, dem Ihr folgt, und wenn Ihr Euch als würdig erweist, wird er Euch Eure ersten Roben geben, die Eure Position als <Priester/Priesterin> kennzeichnen.\n\nAlso dann mal los! Sobald Ihr hier fertig seid, geht durch den Tunnel - er wird auf Euch warten.", progress = nil, completion = "Ach, Branstock hat Euch also geschickt? Gut, gut! Er hat Recht, es ist Zeit, dass Ihr einen größeren Schritt ins Licht tut. Es wird Euren Charakter formen und Euch stärker machen... und das ist, was Ihr mehr als alles andere braucht: Kraft des Körpers... Kraft des Willens.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5627] = {title = "Sterne von Elune", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5628] = {title = "Heimkehr", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Ah, ja, hallo, <Name>? Ich freue mich, dass Ihr auf ein kurzes Gespräch hereinschaut. Ihr seid weit fort von zu Hause, und das in so jungen Jahren - ich bewundere einen solchen Ehrgeiz. Ich wünschte, ich hätte den Mut gehabt, durch die Welt zu reisen, als ich noch jünger war.\n\nEine Priesterin Eures Ordens war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie sagt, Ihr müsstet dringend in den Tempel des Mondes in Darnassus zurückkehren und mit Priesterin Alathea sprechen - es hatte etwas mit Eurer Ausbildung zu tun. Ich würde nicht zu lange trödeln, wenn es irgendwie geht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5629] = {title = "Heimkehr", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Hallo, <Name>. Ich weiß, dass Ihr damit beschäftigt wart, unserem Volk zu helfen, aber Ihr müsst Euch auch Zeit für Euch selbst nehmen. Die Priesterin Alathea hat jemanden hergeschickt, um nach Euch zu suchen. Es scheint, dass Ihr die Aufmerksamkeit unserer Ältesten erregt habt, und sie sind der Meinung, dass Ihr für größere Dinge bereit seid. Begebt Euch zum Tempel des Mondes in Darnassus und sucht dort nach Alathea. Sie wird Euch erwarten. Viel Glück, und möge Elune mit Euch sein.", progress = nil, completion = "Wunderbar, Ihr seid zurückgekehrt, &lt;Name&gt;. Es erfreut Tyrande und mich immer, wenn diejenigen, die wir ausgebildet haben, in die Welt hinausziehen und sicher zu uns zurückkehren. Wie ist es Euch ergangen? Segnet Elune Eure Reisen immer noch? Vielleicht könnt Ihr mir mehr über Eure Reisen berichten, wenn wir über die Angelegenheiten gesprochen haben, die vor uns liegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5630] = {title = "Heimkehr", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Hallo, <Bursche/Mädel>. Es ist gut zu sehen, dass Ihr entfernte Länder weit und breit bereist. Ich will Euch nicht beleidigen, aber viele Eurer Art vertragen das kalte Klima normalerweise nicht gut. Schön zu sehen, dass Ihr aus härterem Holz geschnitzt seid.\n\nVor nicht allzu langer Zeit war eine Eurer Priesterinnen hier und hat nach Euch gesucht - sie sagte so etwas in dem Sinne, dass Ihr eine Priesterin Alathea im Tempel des Mondes in Darnassus aufsuchen solltet. Sagte, es wäre wichtig und Ihr solltet Euch bald dorthin begeben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5631] = {title = "Heimkehr", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Eine Priesterin hat kürzlich unsere Hallen besucht und Euch gesucht, <Volk>. Sie sagte, sie hätte den Auftrag, Euch zu finden, und dass Ihr so bald wie möglich zum Tempel des Mondes in Darnassus zurückkehren solltet. Wenn Ihr ankommt, sucht Priesterin Alathea auf - sie wird Euch mehr berichten.\n\nDas Licht sei mit Euch, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5632] = {title = "Heimkehr", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Oh, aber ja, natürlich. Hallo, <Name>. Eine Botin von Eurem Orden war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie erwähnte, dass in Darnassus etwas Wichtiges geschieht und dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Wenn Ihr dort ankommt, sprecht mit Priesterin Alathea. Ich glaube, es hat etwas damit zu tun, dass Ihr so gute Fortschritte beim Verständnis unserer Bräuche macht.\n\nWie gesagt, kehrt nach Darnassus zurück, sobald Ihr könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5633] = {title = "Heimkehr", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Seid gegrüßt, <Bursche/Mädel>. Es ist schön, Euch hier in unseren großen Hallen zu sehen. Ein Segen sei mit Euch und Eurer Art.\n\nWährend Ihr durch unsere Länder gereist seid, kam eine Priesterin Eures Tempels her, die nach Euch suchte. Sie sagte, dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Es tut mir leid, dass ich Euch nicht mehr berichten kann, aber es klang wichtig. Wenn Ihr zum Tempel kommt, sprecht mit Priesterin Alathea.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5634] = {title = "Verzweifeltes Gebet", objective = "Ihr habt dem Licht einen großen Dienst erwiesen, indem Ihr ein leuchtendes Beispiel für diejenigen wurdet, die durch dieses gefährliche Land und in die Ferne reisen. Bitte, nehmt diese Lektion als Dank für all das an, was Ihr getan habt.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5635] = {title = "Verzweifeltes Gebet", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Ihr habt die Aufmerksamkeit unserer Vorgesetzten erregt, <Name>. Sie bitten, dass Ihr so bald wie möglich zur Kathedrale des Lichts in Sturmwind reist. Anscheinend sind sie der Meinung, dass Ihr Euch bereits würdig erwiesen habt und bereit seid, Eure Ausbildung weiterzuführen. Wenn Ihr dort anlangt, sucht nach der Hohepriesterin Laurena. Sie kann Euch weitere Anweisungen geben. Viel Glück, und möge das Licht mit Euch sein.", progress = nil, completion = "Schön, dass Ihr angekommen seid, &lt;Name&gt;. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5636] = {title = "Verzweifeltes Gebet", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Elune segne Euch, <Volk>. Ich hoffe, dass Euer Licht Euch findet und Euch heute gut schützt.\n\nEiner Eurer Priester war vor nicht allzu langer Zeit hier und suchte nach Euch. Er erwähnte, dass Ihr sobald wie möglich zur Kathedrale des Lichts zurückkehren und mit der Hohepriesterin Laurena sprechen sollt. Es scheint, als hättet Ihr Euch wacker geschlagen, dass Ihr eine solche Aufmerksamkeit erlangt. Ich würde hier nicht allzu viel Zeit verbringen - Eure Leute brauchen Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5637] = {title = "Verzweifeltes Gebet", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Die Zeit ist für Euch gekommen, nach Sturmwind zu gehen, <Name>. Die Hohepriesterin Laurena in der Kathedrale des Lichts möchte mit Euch sprechen. Es muss etwas sehr Gutes oder sehr Schlechtes sein, wenn die Hohepriesterin Euch persönlich dort sehen will, aber ich denke, dass Ihr selbst nur Gutes getan habt und dass es eine gute Sache ist, dass sie mit Euch sprechen möchte.\n\nVerschwendet hier aber nicht allzu viel Zeit. Ich an Eurer Stelle würde mich umgehend auf den Weg machen.", progress = nil, completion = "Schön, dass Ihr angekommen seid, &lt;Name&gt;. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5638] = {title = "Verzweifeltes Gebet", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Vor kurzer Zeit kam einer Eurer Priester her und suchte nach Euch, <Volk>. Er sagte, dass ich Euch zur Kathedrale des Lichts schicken solle, wenn ich Euch sehen würde. Er sagte, es sei sehr wichtig, aber ich an Eurer Stelle würde mir trotzdem nicht allzu viele Sorgen machen. Seine Haltung erschien positiv...als ob es gute Neuigkeiten wären. Auf jeden Fall solltet Ihr Euch beeilen, wenn Ihr meine Meinung wissen wollt.\n\nElune sei mit Euch, <Volk>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5639] = {title = "Verzweifeltes Gebet", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Ihr werdet in Sturmwind gebraucht, <Name>! Die Hohepriesterin dort, Laurena, sagt, es sei an der Zeit für Euch zu beweisen, dass Ihr der nächsten Stufe Eurer Ausbildung würdig seid. Verschwendet nicht zu viel Zeit auf dem Weg dorthin. Ihr könnt sie in der Kathedrale des Lichts im Zentrum der Stadt finden. Überbringt Ihr meine Wünsche und beweist, wie würdig Ihr eines solchen Rufes seid. Das Licht sei mit Euch, <Name>.", progress = nil, completion = "Schön, dass Ihr angekommen seid, &lt;Name&gt;. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern.", rewards = nil}
MultiLanguageQuestData['de'][5640] = {title = "Verzweifeltes Gebet", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Gepriesen seien Elune und Euer Licht, <Name>.\n\nZurzeit erlernen viele unseres Ordens Fähigkeiten, die ihren Glauben an Elune widerspiegeln. Wenn ich mich nicht irre, gilt das Gleiche auch für Euren Orden.\n\nWenn Eure Angelegenheiten in Darnassus abgeschlossen sind, solltet Ihr eine Eurer Hohepriesterinnen zur weiteren Ausbildung aufsuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5641] = {title = "Furchtlos", objective = "Aus Euch könnte ein großartiger <Klasse> werden, <Name>. Leistet weiter so gute Arbeit!\n\nIhr habt bereits bewiesen, dass Ihr bereit für die Schlacht seid. Vielleicht ist es an der Zeit, Euch ein wenig mehr beizubringen.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nFurchtzauberschutz"}
MultiLanguageQuestData['de'][5642] = {title = "Schattenwache", objective = "Sprecht mit Ur'kyo in Orgrimmar.", description = "In Orgrimmar geht etwas Wichtiges vor, <Name>.\n\nNormalerweise sind die Boten, die hier durchkommen und nach Trollpriestern suchen, recht umgänglich. Dieses Mal schienen sie jedoch in großer Eile zu sein. Trödelt nicht zu lange in Donnerfels herum. Ich würde so schnell wie möglich zum Tal der Geister zurückkehren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5643] = {title = "Schattenwache", objective = "Sprecht mit Ur'kyo in Orgrimmar.", description = "Wie viele unserer eigenen Priester werdet Ihr von Eurem Stamm durch die Initiationsriten geführt. Diese Riten lehren Priester häufig besondere Fähigkeiten, die wichtig für ihr Überleben sind. Ich spüre, dass die Zeit jetzt an Euch ist, jetzt, in diesem Augenblick. Ihr müsst zum Tal der Geister in Orgrimmar zurückkehren und mit Ur'kyo sprechen. Was er Euch lehrt, kann für die Zukunft sehr wichtig sein.", progress = nil, completion = "Einer der wichtigsten Initiationsriten für einen &lt;Klasse&gt; unseres Glaubens liegt vor uns, &lt;Name&gt;. Ich werde Euch mehr erklären... Ihr seid dazu bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5644] = {title = "Verschlingende Seuche", objective = "Sprecht mit Aelthalyste in Unterstadt.", description = "Ah, ein wundervoller Tag für Euch, <Name>. Aufgrund der Lektionen, die Ihr gelernt habt, kann ich sehen, dass die Zeit gekommen ist, Euch zu Aelthalyste zurückzuschicken. Es gibt Dinge, die nur sie Euch beibringen kann, und auch das nur, wenn Ihr Euch als würdig erweist.\n\nIch werde die Überraschung für Euch nicht verderben, aber ich erinnere mich daran, wie es war, als ich ein junger Priester war und etwas über die wahre Macht lernte...die göttliche Macht. Ja, das waren noch Zeiten.\n\nKehrt zu Aelthalyste nach Unterstadt zurück, <Name>. Sie erwartet Euch im Kriegsviertel.", progress = nil, completion = "Gut, Ihr seid zurückgekehrt, und das nicht einen Moment zu spät. Wir haben große Dinge zu erörtern, &lt;Name&gt;. Eure Fähigkeiten werden stärker und wir müssen sicherstellen, dass Ihr bereit seid.", rewards = "Ihr erlernt:\n\nVerschlingende Seuche\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5645] = {title = "Furchtlos", objective = "Sprecht mit Hohepriester Rohan in Eisenschmiede.", description = "<Name>, Euer Hohepriester Rohan erwartet Euch zu einer Audienz in Eisenschmiede. Beeilt Euch, Eure nächste Prüfung rückt schnell näher. Auch wenn ich wünschte, dass ich Zeuge der besonderen Riten Eures Volkes sein könnte, ist mein Platz doch hier. Aber möge das Licht während Eurer Reisen mit Euch sein. Rohan sollte sich noch im Mystikerviertel befinden, wenn Ihr die Stadt erreicht. Er wird Euch erwarten.", progress = nil, completion = "Es ist schön, dass Ihr gekommen seid, &lt;Name&gt;. Unser Volk ist stolz und stark und es wird Zeit, dass Ihr nicht nur lernt, selbst stolz und stark zu sein, sondern auch, solche Gefühle und Vertrauen in anderen zu wecken. Seid Ihr bereit, Bursche?", rewards = "Ihr erlernt:\n\nFurchtzauberschutz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5646] = {title = "Verschlingende Seuche", objective = "Sprecht mit Aelthalyste in Unterstadt.", description = "Aelthalyste bezeugt unserem Volk großen Respekt, indem sie unsere Leute zur weiteren Ausbildung zu mir schickt, und nun tue ich dasselbe für ihren Stamm.\n\nKehrt nach Unterstadt zurück, <Name>. Dort, im Kriegsviertel, wartet sie auf Euch und ist bereit, Euch mehr über Euer Volk und seine Wege zu lehren. Begebt Euch dorthin und zögert nicht lange.", progress = nil, completion = "Gut, Ihr seid zurückgekehrt, und das nicht einen Moment zu spät. Wir haben große Dinge zu erörtern, &lt;Name&gt;. Eure Fähigkeiten werden stärker und wir müssen sicherstellen, dass Ihr bereit seid.", rewards = "Ihr erlernt:\n\nVerschlingende Seuche\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5647] = {title = "Furchtlos", objective = "Sprecht mit Hohepriester Rohan in Eisenschmiede.", description = "Euer Volk ist sehr stark, <Name>. Wir sind stolz darauf, Euch Verbündete nennen zu können. Mit jedem Sonnenuntergang nähert Ihr und Eure Art Euch nicht nur Euren wahren Wurzeln, sondern seid auch immer sicherer, dass Ihr in sehr vielen Belangen auf dem richtigen Weg seid. Das muss Euch ein so wunderbares Gefühl geben.\n\nErst vor Kurzem erhielten wir eine Nachricht aus Eisenschmiede. Sie besagte, dass Ihr dorthin zurückkehren und mit dem Hohepriester Rohan im Mystikerviertel sprechen sollt. Ich würde ihn nicht warten lassen. Möge Elune Eure Reisen leiten.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nFurchtzauberschutz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5648] = {title = "Gewänder der Spiritualität", objective = "Findet die Grunzerin Kor'ja und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", description = "Ihr seid bereit für Eure erste Prüfung, <Name>. Südlich von Klingenhügel, direkt vor der Stadt, wurde eine Grunzerin verletzt, als sie einige von Prachtmeers alten Truppen bekämpfte. Es geht ihr nicht allzu gut und es wäre wirklich gut, wenn einer unserer Art ihr helfen könnte. Sucht sie - ihr Name ist Kor'ja -, heilt ihre Wunden und gebt ihr den Segen unserer Vorfahren.\n\nWenn Ihr das tut, sehe ich das als ausreichenden Beweis dafür an, dass Ihr bereit seid, unseren Pfad weiter zu beschreiten.", progress = nil, completion = "Gut, Kor'ja lebt also und zieht los, um unsere Stadt gegen diese bösartigen Menschen zu verteidigen. Ich wünsche mir oft, mich an die Schlachten vergangener Tage zurückzuerinnern; als Macht noch im Kampf gezeigt wurde und es oftmals der Weise war, der diejenigen vernichtete, die sich nur auf ihre Stärke verließen.\n\nIhr habt Eure Sache meiner Meinung nach gut gemacht, &lt;Name&gt;. Nehmt jetzt diese Robe. Ob sie hilft oder ob sie Euch egal ist, Ihr habt sie Euch jedenfalls verdient, und ich bin stolz, Euch Bruder zu nennen.", rewards = "Ihr bekommt:\n\nJujuverhexungsroben"}
MultiLanguageQuestData['de'][5649] = {title = "Der Spiritualität geneigt", objective = "Sprecht mit Tai'jin in Durotar.", description = "Ja, Mann. Unser Volk hat sich der Horde angeschlossen, weil sie gut für uns ist. Die da sind loyal und lehren uns viel über Dinge wie Ehre. Aber unsere alten Gewohnheiten sterben nur langsam. Die Orcs mögen nicht alle unsere Traditionen billigen, aber das bedeutet nicht, dass wir einige davon nicht im Geheimen ausüben können.\n\nIhr wisst das, und darum schicke ich Euch zu Tai'jin in Klingenhügel. Sie wird Euch mehr über unsere Geschichte lehren. Sie wird Euch in den Wegen unseres Stammes unterrichten. Geht zu ihr, wenn Ihr bereit seid.", progress = nil, completion = "Ahhh... Ihr seid also endlich zu Tai'jin gekommen. Das ist gut.\n\nIhr wisst bereits, dass wir nicht der gleiche Stamm sind, der sich einst der Horde angeschlossen hat. Wir sind jetzt viel stärker. Wir sind stärker, weil wir uns anpassen - das hat uns die Horde gelehrt. Wir besiegen unsere Feinde nicht mehr, um durch sie dann an Kraft zu gewinnen; jetzt gewinnen wir an Kraft und besiegen dann unsere Feinde.\n\nDer Unterschied mag fein sein, aber Ihr werdet es lernen. Ihr werdet es sehen. Der Stamm zählt auf Euch, dass Ihr solche Dinge lernt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5650] = {title = "Gewänder der Dunkelheit", objective = "Findet die Todeswache Kel und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryll in Brill zurück.", description = "Unsere Macht beziehen wir aus der Dunkelheit und dem Schatten, <Name>, doch das ist nicht Eure einzige Rolle. Ihr habt erkannt, dass es von Vorteil ist, sich in der Heilkunst auszukennen. Das ist weise. Doch bevor Ihr die Dunkelheit kennen lernen könnt, müsst Ihr erst das Licht kennen. Und daher habe ich eine Prüfung für Euch.\n\nNördlich des Friedhofs befindet sich eine verwundete Todeswache - Todeswache Kel. Er hat uns seit geraumer Zeit vor Gnollen beschützt und braucht Heilung. Doch Ihr müsst auch seinen Körper stärken, bevor er seinen Dienst wieder aufnehmen kann. Tut beides mit Euren Zaubern und kehrt dann zu mir zurück.", progress = nil, completion = "Ihr habt meine Prüfung mit Leichtigkeit bestanden. Gut.\n\nBald werdet Ihr bereit sein, mehr Verantwortung zu übernehmen, und dieser Weg wird Euch zu dunkleren Kräften führen... Kräfte, die kein &lt;Klasse&gt; eines anderen Volkes besitzt.\n\nNehmt diese Robe als Symbol Eures Standes. Ihr habt sie Euch verdient. Wenn Ihr sie nicht tragen wollt, dann sei es so, Ihr könnt damit tun, was Ihr wollt. Ich und andere wie wir werden Euch immer Anerkennung dafür zollen, was Ihr in unseren Reihen erreicht habt.", rewards = "Ihr bekommt:\n\nOpferroben des Akolythen"}
MultiLanguageQuestData['de'][5651] = {title = "Der Dunkelheit geneigt", objective = "Sprecht mit dem Dunklen Kleriker Beryll in Tirisfal.", description = "Es gibt viele Lektionen, die die Verlassenen durch Erfahrung gelernt haben... Dinge, die einige Völker allenfalls erahnen können. Und obwohl unser Weg in Dunkelheit liegt, werdet Ihr feststellen, dass sehr viele Dinge sowohl vom Licht als auch von der Dunkelheit abhängen. Eure Lektionen sollen Euch lehren, beides zu nutzen... mit Umsicht. Aber beachtet meine Worte: vergesst nie, wir wurden in die Verderbnis gezwungen und der Fäulnis überlassen wie ein Stück Aas. Die Dunkelheit ist unser Heim.\n\nSucht den Dunklen Kleriker Beryll in Brill auf, wenn Ihr bereit seid, mehr zu erfahren.", progress = nil, completion = "Endlich seid Ihr da. Euer Glaube allein wird Euch nicht helfen, die Aufgaben zu bewältigen, die vor Euch liegen. Etwas Dringlichkeit und ein wenig Ehrgeiz helfen auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5652] = {title = "Verhexung der Schwäche", objective = "Ihr tätet gut daran, diese Lektion zu beachten. Die Verhexung der Schwäche wird Euch im Kampf von großem Nutzen sein. Später werde ich Prüfungen für Euch bereithalten, mit Hilfe derer Ihr Euch weiterentwickeln und Euren Wert für den Stamm beweisen könnt.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5654] = {title = "Verhexung der Schwäche", objective = "Sprecht mit Ur'kyo in Orgrimmar.", description = "Es ist an der Zeit, Euch mit Ur'kyo zu treffen, <Name>. Er befindet sich im Tal der Geister in der Stadt der Orcs. Geht dorthin und sprecht mit ihm. Es ist an der Zeit, dass Ihr mehr über die alten Wege unserer Art lernt. Es wird Zeit, dass Ihr in den Kreis eingeführt und zu einem wahren Priester unseres Stammes gemacht werdet.", progress = nil, completion = "Ah, gut, da seid Ihr ja. Wir können Eure Ausbildung in den alten Wegen beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5655] = {title = "Verhexung der Schwäche", objective = "Sprecht mit Ur'kyo in Orgrimmar.Ich wurde hergeschickt, um sicherzustellen, dass Ihr Euch nicht zu sehr von der Heimat entfernt, <Name>. Sie haben mich geschickt, um sicherzustellen, dass Ihr nach Hause zurückkehrt, da Ur'kyo, der größte unserer Priester, mit Euch zu sprechen wünscht. Begebt Euch dorthin. Begebt Euch zum Tal der Geister in der Stadt der Orcs und sprecht mit Ur'kyo. Er wartet auf Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich wurde hergeschickt, um sicherzustellen, dass Ihr Euch nicht zu sehr von der Heimat entfernt, <Name>. Sie haben mich geschickt, um sicherzustellen, dass Ihr nach Hause zurückkehrt, da Ur'kyo, der größte unserer Priester, mit Euch zu sprechen wünscht. Begebt Euch dorthin. Begebt Euch zum Tal der Geister in der Stadt der Orcs und sprecht mit Ur'kyo. Er wartet auf Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5656] = {title = "Verhexung der Schwäche", objective = "Sprecht mit Ur'kyo in Orgrimmar.", description = "Es erwärmt immer mein nicht sterbendes Herz, Priester aus allen Kulturen zu sehen, die durch die Welt ziehen. Zu wissen, dass Macht existiert, die nicht arkan und sehr wohl in unserer Reichweite ist. Daher ist es mir eine Ehre, Euch nach Hause zu schicken, <Name>.\n\nUr'kyo, Euer großer Priester in Orgrimmar, bittet um Eure Anwesenheit. Ihr findet ihn im Tal der Geister.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5657] = {title = "Verhexung der Schwäche", objective = "Sprecht mit Ur'kyo in Orgrimmar.", description = "Nach Hause. Kehrt nach Hause zurück, <Volk>.\n\nEuer spiritueller Anführer Ur'kyo bittet Euch, zu ihm zurückzukehren und mit ihm über den Weg zu sprechen, den Ihr geht.\n\nBegebt Euch zum Tal der Geister in der großen Hordenstadt Orgrimmar. Dort werde Ihr ihn finden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5658] = {title = "Berührung der Schwäche", objective = "Ah, junger <Klasse>, ich bin froh, dass Ihr hierher zurückgekehrt seid. Ich würde Euch gerne eine Lektion lehren, die Ihr besser nicht vergessen solltet. Seid Ihr bereit?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5660] = {title = "Berührung der Schwäche", objective = "Sprecht mit Aelthalyste in Unterstadt.", description = "Ihr seid weit weg von zu Hause, <Klasse>. Ihr werdet dort gebraucht, dort, in Eurer Stadt unter dem Boden. Eure Meisterin, diejenige, die Ihr Aelthalyste nennt, braucht Euch dort. Genau wie bei meinem Stamm gibt es dort Dinge, die Ihr nur von ihr lernen könnt. Bleibt nicht zu lange hier. Ihr solltet Euch zum Kriegsviertel begeben, so schnell ein Zeppelin Euch tragen kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5661] = {title = "Berührung der Schwäche", objective = "Sprecht mit Aelthalyste in Unterstadt.", description = "Ihr seid weit weg von zu Hause, hier im Dorf der Bluthufe, <Name>. Ich wurde hierher geschickt, um Priester meines eigenen Stammes zu finden und sie zurückzuschicken, um mit unseren Anführern zu sprechen, aber das bedeutet nicht, dass ich Euch nicht auch helfen kann.\n\nIch habe gehört, dass der Geist Eurer führenden Priesterin möchte, dass alle Verlassenen zu ihr kommen - es gibt Dinge, die Ihr lernen müsst.\n\nTrefft Euch mit Aelthalyste im Kriegsviertel, in Eurer Stadt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5662] = {title = "Berührung der Schwäche", objective = "Sprecht mit Aelthalyste in Unterstadt.", description = "Mein Respekt gilt Euch und Eurer Art, <Name>. Normalerweise lehre ich nur die meines eigenen Stammes. Eure Lektionen kommen von Aelthalyste in der Stadt, die einst Lordaeron genannt wurde.\n\nIhr solltet zur ihr zurückkehren, wenn Ihr die Fähigkeiten erlernen wollt, die Euch von anderen Glaubensrichtungen abgrenzen.\n\nBegebt Euch ins Kriegsviertel in Unterstadt und sucht dort nach Eurer Meisterin.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5663] = {title = "Berührung der Schwäche", objective = "Sprecht mit Aelthalyste in Unterstadt.", description = "Aelthalyste schickte eine Nachricht an alle ihre Priester. Wir sollen die Jüngeren unseres Ordens für die weitere Ausbildung nach Unterstadt schicken. Wenn Ihr Euch wahrlich zu unseren Gläubigen zählt, dann solltet Ihr auch dorthin zurückkehren.\n\nIhr könnt Aelthalyste im Kriegsviertel in Unterstadt finden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5672] = {title = "Elunes Anmut", objective = "Indem Ihr Euch Elune und unserem Volk widmet, habt Ihr einen Status erreicht, den nicht alle von uns erlangen können. Es ist Tradition, dass Euch nun noch größere Fähigkeiten für Eure Hingabe gelehrt werden sollen. Nehmt Ihr an?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5673] = {title = "Elunes Anmut", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Ihr wisst, dass Ihr jederzeit zu jedem unserer Lehrer Zugang habt, <Name>, aber es gibt einige Dinge, die wir nicht an Euch weitergeben können. Eines dieser Dinge sind die Lehren der Göttin Elune. Sie verleiht ihren Getreuen spezielle Fähigkeiten, und wenn ich mich nicht irre, ist es an der Zeit, dass Ihr nach Hause zu Eurem Tempel des Mondes zurückkehrt, um geprüft zu werden.\n\nKehrt dorthin zurück, wenn Ihr könnt, und sprecht mit der Priesterin Alathea.", progress = nil, completion = "Elune segne Euch für Eure schnelle Rückkehr zu uns. Dies ist eine bedeutende Zeit für Eure Ausbildung und eine Zeit, die unser gesamter Orden sehr ernst nimmt. Wenn Ihr Euch von Eurer Reise hierher erholt habt, dann lasst es mich wissen. Wir können dann die Fortführung Eurer Ausbildung erörtern und die Frage, wohin Euch Euer Weg als Nächstes führen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5674] = {title = "Elunes Anmut", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Ein wunderbarer Tag ist gekommen, <Name>. Ihr habt das Alter erreicht, in dem unsere <Priester/Priesterinnen> in Fähigkeiten ausgebildet werden, die nur die Nachtelfen kennen. Aber es ist nicht an mir, Euch auszubilden. Ihr müsst zum Tempel des Mondes zurückkehren und mit der Priesterin Alathea sprechen, sobald Ihr Eure Angelegenheiten hier abgeschlossen habt. Sie wird Euch prüfen, um sicher zu sein, dass Ihr bereit seid, und erst dann wird sie Euch Elunes Anmut lehren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5675] = {title = "Elunes Anmut", objective = "Sprecht mit der Priesterin Alathea in Darnassus.", description = "Die Zeit verrinnt, <Bursche/Mädel>. Es ist an der Zeit, dass Ihr nach Darnassus heimkehrt. Die Priesterin Alathea ließ uns wissen, dass Ihr dorthin zur Ausbildung zurückkehren sollt. Es scheint, als wärt Ihr bereit, getestet zu werden, so wie jene, die dem Licht dienen. Ihr solltet Euch dorthin begeben, sobald Ihr könnt. Alatheas Nachricht besagte, dass sie im Tempel des Mondes auf Euch wartet. Viel Glück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5676] = {title = "Arkane Rückkopplung", objective = "Wir waren gezwungen, einige Magien zu lernen, um uns vor dem zu schützen, was üblicherweise unser stärkster Feind genannt wird: dem Arkanen.\n\nIch würde Euch einen Zauber beibringen, um Euch und Euren Kameraden bei der Verteidigung gegen diejenigen zu helfen, die diese Macht einsetzen.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5677] = {title = "Arkane Rückkopplung", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "So gern ich Euch auch unsere eigenen speziellen Lehren des Lichts zeigen würde, so ist dies doch nicht an uns. Ihr müsst zurück nach Sturmwind, zu Eurer eigenen Art, <Name>... zumindest vorerst. Glaubt mir, es war nicht böse gemeint. Wenn Ihr zur Hohepriesterin Laurena in die Kathedrale des Lichts zurückkehrt, werdet Ihr verstehen, worüber ich spreche... Die Zeit ist für Euer Volk gekommen, Euch auf die Zukunft vorzubereiten, Euch von den anderen abzuheben, die einem ähnlichen Weg folgen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5678] = {title = "Arkane Rückkopplung", objective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", description = "Es ist an der Zeit für Euch, nach Sturmwind zurückzukehren. Eure Vorgesetzten dort haben Euch zur Ausbildung zurückgerufen. Und obwohl mich das ein wenig verstört, so sind Euer Volk und meines doch Verbündete und ich würde niemals Verrat an diesem Bündnis begehen.\n\nIch möchte Euch gegenüber offen sein...Mein Argwohn jeglicher arkanen Magie gegenüber, möge sie nun göttlich inspiriert sein oder nicht, ist immer noch stark in mir.\n\nIhr werdet verstehen, wovon ich spreche, wenn Ihr zu Eurer Kathedrale des Lichts zurückkehrt. Sprecht mit der Hohepriesterin Laurena, wenn Ihr dort ankommt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5679] = {title = "Verschlingende Seuche", objective = "Ich würde Euch 'Verschlingende Seuche' beibringen, wenn Ihr Euch bereit dazu fühlt, <Name>. Dieser Spruch ist nicht gerade von kleiner Macht und wird Euch in den kommenden Schlachten helfen. Übt damit - es wird später Prüfungen dazu geben.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nVerschlingende Seuche"}
MultiLanguageQuestData['de'][5680] = {title = "Schattenwache", objective = "Eure Riten werden bald kommen. Fürs Erste lehre ich Euch einen Zauber, der Euch von großem Nutzen sein wird, wenn Ihr mit Euren Feinden kämpft.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][5713] = {title = "Ein Schuss, ein Treffer", objective = "Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten im Eschental.", description = "Ich war mit einer wichtigen Nachricht auf dem Weg nach Lor'danel, als ich von dem Furbolg Marosh und seinen Fährtenlesern angegriffen wurde. Während des Angriffs wurde ich vergiftet, wodurch ich kaum noch stehen konnte. Ich kann ein Gegengift herstellen, aber es wird eine Zeit dauern, bis es bereit ist.\n\nIch möchte Euch bitten, mich zu verteidigen, bis ich das Gegengift anwenden kann. Ich werde Euch, so gut es geht, mit meinem Bogen helfen.\n\nFalls wir überleben, kann ich meine Botschaft nach Lor'danel überbringen, während Ihr mit Onaeya bei Maestras Posten sprecht, um sie von diesem Vorfall zu unterrichten.", progress = nil, completion = "Ihr bringt sehr willkommene Neuigkeiten, &lt;Klasse&gt;. Es ist gut zu hören, dass Aynasha lebt, und ich danke Euch dafür. Ich hoffe, dass Ihr eine Belohnung für Eure edlen Bemühungen annehmt. Möge Elune über Euch wachen und Euren Weg erleuchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5721] = {title = "Die Schlacht um Darroheim", objective = "Legt das Reliktbündel auf den Marktplatz von Darroheim.\n\nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.\n\nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.\n\nBesiegt Rotpfad den Verderbten.\n\nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.", description = "Nun, <Name>, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim, und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", progress = nil, completion = "Der Kampf ist vorüber! Ich habe meinen Vater zu mir flüstern hören. Er hat alle Geister verjagt und sagt, dass er nach Hause käme! Ich bin so froh!\n\nEr sagte außerdem, dass ich Euch willkommen heißen sollte, wenn Ihr zu uns nach Hause kommt, daher habe ich Euch etwas Tee zubereitet!\n\nIch hoffe, Ihr mögt ihn mit viel Zucker!", rewards = "Ihr bekommt:\n\nTee mit Zucker"}
MultiLanguageQuestData['de'][5722] = {title = "Die Suche nach dem verloren gegangenen Ranzen", objective = "Sucht im Flammenschlund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.", description = "Die Troggs sind nicht das Einzige, das Magatha im Flammenschlund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird...und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.\n\nBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.\n\nBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar.", progress = nil, completion = "Der Körper scheint von Keulen oder Fäusten übelst zugerichtet worden zu sein, jedoch ist der Großteil der Kleidung und Ausrüstung offenbar noch vorhanden. Die Troggs scheren sich anscheinend nicht besonders um materielle Dinge.\n\nIhr beginnt, den Körper nach etwas Interessantem zu durchsuchen, das Magatha helfen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5723] = {title = "Die Kraft des Feindes wird auf die Probe gestellt", objective = "Sucht in Orgrimmar nach dem Flammenschlund, tötet dann 8 Flammenschlundtroggs und 8 Schamanen der Flammenschlundtroggs und kehrt anschließend zu Rahauro in Donnerfels zurück.", description = "Unter der Stadt Orgrimmar haben stämmige Kreaturen, als Troggs bekannt, damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte Magatha Frieden mit diesen Kreaturen schließen wollen, doch die Troggs stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des Taurenvolks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte Horde.\n\nSie bittet Euch, der Gefahr durch die Troggs ein Ende zu machen, bevor sie die Horde von unten überwältigen. Geht zum Flammenschlund und vernichtet sie alle.", progress = nil, completion = "Ich freue mich, dass Ihr Magathas Auftrag so ernst genommen habt. Ich danke Euch, &lt;Name&gt;. Den Troggs wird es jetzt bestimmt schwerer fallen, an die Oberfläche zu gelangen, denn ihre Zahl wurde beträchtlich reduziert.\n\nVielleicht können wir uns in der Zukunft etwas Zeit nehmen und herausfinden, woher diese Kreaturen kamen und was sie eigentlich wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5724] = {title = "Wiederbeschaffung des verloren gegangenen Ranzens", objective = "Bringt den Grimmtotemranzen zu Rahauro nach Donnerfels.", description = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.\n\nIhr befreit den Ranzen aus seinem Klammergriff und verstaut ihn bei Eurer eigenen Ausrüstung, dann bereitet Ihr Euch darauf vor, die Tunnel zu verlassen und zu Rahauro in Donnerfels zurückzukehren.", progress = "Habt Ihr irgendwas gefunden, <Name>? Jeder Hinweis darauf, warum einer ihrer Klanangehörigen unnötig sterben musste, wäre hilfreich.", completion = "Ausgezeichnet, &lt;Name&gt;. Danke.\n\nMagatha sagte mir, dass Ihr dies hier bekommen sollt, wenn Eure Suche nach ihrem Klanangehörigen erfolgreich war. Bitte, nehmt das als Dank.", rewards = "Federleichte ArmschienenSavannenarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5725] = {title = "Die Macht zu Zerstören...", objective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Unterstadt.", description = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die... weniger Visionen haben.\n\nEine Sekte des Schattenrates, die sich die Sengende Klinge nennt und sich in den Höhlen unterhalb Orgrimmars versteckt, ist ein Musterbeispiel dafür. Die Fürstin sagte mir, dass Mitglieder der Sengenden Klinge in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien... und sie möchte sich diese Bücher von ihnen 'borgen'. Ihr werdet sie ihr beschaffen.", progress = "Ich muss mich noch um Hunderte anderer Dinge kümmern, <Klasse>. Habt Ihr die Bücher?", completion = "Gut, &lt;Klasse&gt;. Ihr habt der dunklen Fürstin gut gedient. Mit Eurer unablässigen Beharrlichkeit und Eurem Ehrgeiz habt Ihr viel für die Untertanen der Fürstin geleistet. Besucht mich irgendwann einmal wieder. Vielleicht habe ich dann ja neue Aufgaben für Euch, die der dunklen Fürstin bei ihren Versuchen, den Lichkönig zu stürzen und die Geißel endgültig zu befreien, helfen könnten.", rewards = "Garstige BeinkleiderGamaschen des SumpfgräbersGargoylegamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5726] = {title = "Verborgene Feinde", objective = "Bringt ein Insigne des Leutnants zu Thrall nach Orgrimmar.", description = "Eines werde ich in meinen Reihen auf keinen Fall dulden, <Name>: Verräter. Ich wäre allerdings töricht, würde ich meine Trümpfe einfach so ausspielen. Die Geschwüre der Verderbnis in unserem Land würden nicht tief genug herausgeschnitten und die Infektion würde sich noch verschlimmern.\n\nAber Ihr, ein junger Abenteurer, könntet dorthin gehen, wo es meinen Agenten nicht möglich ist... könntet die Wahrheit ans Licht bringen... herausfinden, wer wirklich hinter dieser Bestie steckt.\n\nWenn Ihr mutig genug seid, geht zur Knochenhöhle östlich von Orgrimmar, besorgt mir das Insigne eines Offiziers der Brennenden Klinge dort und kehrt zu mir zurück.", progress = "Habt Ihr die Insignie schon, <Name>?\n\nSie wäre ein wichtiges Hilfsmittel, damit Ihr dort eindringen könnt, wo ich die größte Gefahr für die Horde vermute und damit wir in unserer neuen Heimat endlich Frieden finden.\n\nIhr werdet sehen, wie komplex das Netz sein kann, das Menschen und Orcs gemeinsam weben können, wenn sie von Gier und Machthunger angetrieben werden. All die geheimen Pläne, die Verderbnis, all das wird dann klar werden. Ihr werdet Euch in der Mitte eines Krieges wiederfinden, von dem Ihr gar nicht wusstet, dass er überhaupt existiert.", completion = "Gut, &lt;Name&gt;! Die Geister seien gepriesen. Vielleicht seid Ihr derjenige, der mich endlich von meinen größten Sorgen befreien kann! Wer hätte gedacht, dass jemand, der so jung und doch so mutig ist, sich erheben und unsere Sache verfechten würde? Ihr erinnert mich an mich selbst, als ich noch jünger war. Ich werde dafür sorgen, dass Ihr den gerechten Lohn für Eure Mühen bekommt, falls wir den aufziehenden Sturm überleben.\n\nWeitere Lobeshymnen heben wir uns für später auf. Bis jetzt habt Ihr nicht viel geleistet im Vergleich zu dem, was Euch noch erwartet... aber es ist ein guter Anfang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5727] = {title = "Verborgene Feinde", objective = "Bringt Neeru Feuerklinge das Insigne des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Brennenden Klinge seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", description = "Und jetzt lasst uns sehen, ob das Insigne, das Ihr gefunden habt, der Mühe wert ist.\n\nIn der Stadt gibt es einen Hexenmeister, der seiner Meinung nach mein Vertrauen genießt. Er weiß allerdings nicht, dass ich gewahr bin, wem er wirklich die Treue hält. Tatsächlich ist er der Anführer der Brennenden Klinge. Aber stürzt Euch jetzt nicht übereilt in einen Kampf mit ihm. Er könnte nützlich sein und wir werden ihn gegen unsere Feinde einsetzen.\n\nBringt dieses Insigne zu ihm in die Kluft der Schatten hier in Orgrimmar. Sprecht mit ihm, seht, ob er Euch für einen der Ihren hält, und kommt dann zu mir zurück.", progress = "Also, <Klasse>? Hat er uns unsere Finte abgenommen oder ist die Sache doch schlimmer, als ich zuerst angenommen habe?\n\nWenn wir uns für Neeru als nützlich erweisen, wird uns das die Unterwanderung des Schattenrates erleichtern. Wir werden an eine Menge Informationen herankommen, die wir nutzen können, um all jene auszurotten, die das zu zerstören versuchen, was wir in Durotar aufgebaut haben.", completion = "Exzellent! Sehr eindrucksvoll, &lt;Klasse&gt;!\n\nWas Euch heute gelungen ist, ist nur der erste Schritt zur Legung eines noch größeren Fundaments - eines Fundaments, auf dem wir die endgültige Zerstörung des Schattenrates aufbauen.\n\nErzählt mir alles, was er gesagt hat... und lasst auch nicht ein einziges Wort aus, denn es könnte wichtiger sein, als Ihr glaubt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5728] = {title = "Verborgene Feinde", objective = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", description = "Hmmm, Anführer der Sengenden Klinge... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr... Bazzalan, und der andere, den Neeru erwähnte... Was war er doch gleich, ein Hexenmeister? Sie müssen vernichtet werden.\n\nKehrt zur Kluft der Schatten zurück und begebt Euch in den Flammenschlund, <Name>. Findet diese beiden Anführer der Sengenden Klinge und tötet sie. Aber seid vorsichtig, damit Neeru nicht erfährt, wer das getan hat. Er muss Euch auch weiterhin für <seinen Kampfgenossen/seine Kampfgenossin> halten.", progress = nil, completion = "Schön, dass Ihr zurück seid, &lt;Name&gt;. Ein paar derer, die mir immer noch treu ergeben sind, haben mich sofort davon unterrichtet, dass die Höhlen unter Orgrimmar in Aufruhr sind, nachdem die Anführer vernichtet wurden. Berichten zufolge soll Neeru ziemlich beunruhigt sein. Es scheint, als hätten wir seiner Rüstung eine Delle verpasst. Ich kann sagen, dass ich doch recht zufrieden bin ... auch mit einem kleinen Sieg wie diesem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5729] = {title = "Verborgene Feinde", objective = "Sprecht mit Neeru Feuerklinge in Orgrimmar.", description = "Ich glaube, unser nächster Schritt sollte sein, Euch in Neerus Nähe unterzubringen. Falls er wirklich so beunruhigt ist, wie die Berichte vermuten lassen, könnten wir zwei Fliegen mit einer Klappe schlagen. Erstens könntet Ihr mehr über den Rat oder zumindest die Sengende Klinge in Erfahrung bringen, und zweitens könnte er Euch möglicherweise genug vertrauen, um Euch zu bitten, ihm zu helfen. Vielleicht wird er Euch für jemanden halten, der die Lücken füllt, die der Tod der Anführer gerissen hat.\n\nKehrt zur Kluft zurück und sprecht noch einmal mit ihm, aber haltet Euch bedeckt.", progress = nil, completion = "Was ist? Oh, Ihr seid es, &lt;Klasse&gt;... Verzeiht mir. Ich bin so wütend wie ein tollwütiger Kodobulle... aber daran bin ich wahrscheinlich selbst schuld. Ich habe Reisende zum Ragefireabgrund geschickt und hätte doch wissen müssen, dass sich daraus Probleme ergeben könnten. Es scheint, als hätten ein paar von Thralls Weltverbesserern Bazzalan und Jergosh überrumpelt und erschlagen. Ein äußerst ungünstiger Zeitpunkt, aber daran ist jetzt nichts mehr zu ändern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5730] = {title = "Verborgene Feinde", objective = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt.", description = "Ihr seid einer meiner Offiziere! Macht Euch bereit, <Klasse>. Ich werde Euch bald benötigen.\n\nDie Zeit, die ich für die Sengende Klinge aufgebracht hatte, war jetzt vielleicht reine Zeitverschwendung, aber das bedeutet nicht, dass die restlichen Pläne des Schattenrates darunter leiden müssen. Ich werde tun, was ich kann, um den Schaden hier im Flammenschlund zu begrenzen. In der Zwischenzeit sollen meine Agenten im Brachland und im Eschental mit der Arbeit an unserem neuesten Geheimplan beginnen. Kommt bald zu mir zurück.", progress = nil, completion = "Ashenvale? Hmm, ich hatte nichts von der Anwesenheit des Rates oder der Burning Blade in Ashenvale gewusst. Meine Spione werden das untersuchen, &lt;Name&gt;. Das habt Ihr gut gemacht.\n\nJetzt ruht Euch erst einmal aus und beschäftigt Euch mit anderen Aufgaben. Ich werde Euch bald wieder benötigen.\n\nLok-Tar Ogar!", rewards = "Axt von OrgrimmarKris von OrgrimmarStab von OrgrimmarHammer von OrgrimmarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5741] = {title = "Szepter des Lichts", objective = "Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.", description = "Die Anhänger der Brennenden Klinge in der Festung Donneraxt im Osten sollen Gerüchten zufolge das Szepter des Lichts von den Naga beschafft haben. Die Legenden besagen, dass das Szepter dazu fähig ist, ganze Städte unter den Ozeanen verschwinden zu lassen. Wir dürfen nicht zulassen, dass die Brennende Klinge solche Macht besitzt.\n\nUm das zu verhindern, müsst Ihr selbst das Szepter bergen! Es ist im Besitz eines Sehers der Brennenden Klinge, der das Szepter in einem der Wachtürme der Feste Donneraxt studiert.", progress = "Habt Ihr das Szepter des Lichts?", completion = "Das geheimnisvolle Szepter des Lichts! Dass Ihr es beschafft habt, hat eine große Bedrohung von der Welt abgewendet. Gut gemacht, &lt;Klasse&gt;, gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5742] = {title = "Erlösung", objective = "Hört Euch an, was Tirion Fordring zu sagen hat.", description = "Ihr habt sehr hart gearbeitet. Ruht Eure müden Knochen aus und erlaubt mir, mich korrekt vorzustellen.", progress = "Bitte setzt Euch und hört meine Geschichte.", completion = "Fordring zu erlösen wird sehr schwierig sein. Seid Ihr bereit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5761] = {title = "Vernichtung der Bestie", objective = "Begebt Euch in den Flammenschlund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Feuerklinge nach Orgrimmar.", description = "Die vorrangige Aufgabe, die mir unser großer Kriegshäuptling übertragen hat, ist die Vernichtung der Kreaturen, die dafür verantwortlich sind, dass sich der dämonische Einfluss in der großen Stadt unseres Herrschers einnisten konnte. Die Kultisten der Brennenden Klinge sind eine Gefahr, aber es gibt auch noch andere. Die Anhänger der Sengenden Klinge zum Beispiel, die sich im Flammenschlund niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der Horde auf ihre Seite zu ziehen.\n\nUm sie aufzuhalten, muss ihr Anführer beseitigt werden - eine Teufelswache namens Taragaman der Hungerleider.\n\nTötet ihn, und sein Herz wird Thrall beschwichtigen, dessen bin ich mir sicher.", progress = "Habt Ihr die Bestie getötet? Er ist mit Sicherheit der Anführer der Searingblade im Ragefireabgrund.", completion = "Ha! Ihr habt es geschafft! Thrall wird hocherfreut sein.\n\nIch werde dafür sorgen, dass das Herz in die richtigen Hände kommt.\n\nJetzt allerdings solltet Ihr erst einmal Euren Sieg feiern. Ich werde indes Thrall von Eurem Erfolg berichten.\n\nVielen Dank für Eure Hilfe, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5762] = {title = "Hemet Nesingwary Jr.", objective = "Bringt Kravels Kiste zu Hemet Nesingwary Jr. ins Schlingendorntal.", description = "Ich habe hier eine Sendung für einen alten Kunden von mir, Hemet Nesingwary Jr., ein Zwerg. Die Sendung war wochenlang unterwegs und Hemet ist schon längst wieder weg. Er sagte, dass er ins Schlingendorntal gehen wolle, um die Bestien dort zu jagen, aber er ließ mir etwas Geld da und wollte, dass ich ihm seine Sendung schicke, sobald es mir möglich sei. \n\nJunior ist ein reicher Zwerg und man sollte sich mit den Reichen ruhig gut stellen, findet Ihr nicht auch? Also... könntet Ihr die Sendung für mich zustellen?\n\nWie ich hörte, hat er im Schlingendorntal nördlich von Grom'gol ein Lager aufgeschlagen.", progress = "Ist das da Wüstenstaub an Eurem Kragen?\n\nHm... wenn mich meine Nase nicht täuscht, würde ich sagen, das ist gar kein Wüstenstaub, sondern Wüstensalz! Ihr wart in der schimmernden Ebene, stimmt's?", completion = "Großartig, meine Sendung von Koalbeard! Danke, &lt;Name&gt;. Diese Kiste enthält Munition eines ganz besonderen Kalibers, die uns im Dschungel sehr nützen wird!\n\nHier habt Ihr das Geld und sagt mir noch, wie geht's denn dem grantigen alten Kravel so? Führt bestimmt immer noch nichts Gutes im Schilde, möchte ich wetten ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5763] = {title = "Jagd im Schlingendorntal", objective = "Bringt Roons Kodohorn zu Hemet Nesingwary Jr. ins Schlingendorntal.", description = "Vor langer Zeit kam ein Zwerg in dieses Land. Sein Name war Hemet, und er kam, um große Wildtiere zu jagen. Sein Geschick mit Flinten war außergewöhnlich, und wir haben viele Tage zusammen auf der Jagd verbracht. Sogar die Feindschaft zwischen unseren Völkern war vergessen.\n\nAls er ins Schlingendorntal ging, schwor ich, ihn irgendwann einmal wieder willkommen zu heißen. Er ist jetzt zum Jagen in ferne Länder gegangen, aber sein Sohn hat seinen Platz eingenommen.\n\nBringt Hemet Jr. dieses Kodohorn als Geschenk. Ihr findet ihn im Schlingendorntal, nördlich des Basislagers von Grom'gol.", progress = "Setzt Euch, <Klasse>. Ihr werdet schon bald wieder in den Dschungel zurückmüssen.", completion = "Ah, dieses Horn gehört einem Tauren, Roon Wildmane. Wir hatten sehr viel Spaß, als wir zusammen die Wildtiere von Desolace jagten. Roon lädt mich also ein, ja?\n\nWir stecken zwar momentan bis zum Hals im Dschungel, aber trotzdem danke, &lt;Name&gt;. Vielleicht führt mich meine nächste Expedition ja wieder nach Desolace, dem Land der Zentauren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5781] = {title = "Von vergessenen Erinnerungen", objective = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", description = "Wenn Ihr Taelan helfen wollt, zurückzubekommen, was er verloren hat, müsst Ihr Gegenstände aus seiner Vergangenheit zusammentragen.\n\nDer Erste dieser Gegenstände ist ein Spielzeug, das ich ihm zu seinem 7. Geburtstag schenkte. Es war sein wertvollster Besitz. Ein winziger Kriegshammer, die exakte Kopie meines eigenen.\n\nAls man mich wegen Verrats verbannte, erzählte ihm seine Mutter, dass ich gestorben sei. Man brachte ihn zu meinem angeblichen Grab beim Tiefgewölbe, wo er den Hammer zusammen mit seiner Erinnerung an mich begrub - für immer.\n\nIhr müsst Euch zum Tiefgewölbe begeben und Taelans Hammer holen.", progress = "Er muss erlöst werden.", completion = "&lt;Tirion blinzelt, um seine Tränen zurückzuhalten.&gt;\n\nEs war Schicksal, dass wir uns begegneten, &lt;Name&gt;. Ihr wart so gut zu mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5801] = {title = "Feuersäulen geschmiedet", objective = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.\n\nBringt den unvollendeten Dietrich dann zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Krater von Un'Goro liegt der Feuersäulengrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Arbington sprechen.", progress = "Habt Ihr den Schaft des Skelettschlüssels fertig gestellt? Es tut mir Leid, dass Ihr das Meiste zum Kauf der Form beisteuern musstet, aber wir müssen alle unseren Beitrag leisten, um der Geißel Herr zu werden. Wenn Ihr mir den unvollendeten Schlüssel gebt, seid Ihr für den letzten Gegenstand bereit, der benötigt wird, um die Herstellung des Schlüssels abzuschließen.\n\nEs wird nicht gerade einfach werden, aber die ganze Arbeit, die Ihr bis jetzt zur Vorbereitung eines Angriffs auf Andorhal geleistet habt, wird sich schließlich auszahlen. Ihr werdet schon sehen.", completion = "Da haben wir aber einen ziemlich teuren Skelettschlüssel, was, &lt;Name&gt;? Er ist jedoch noch nicht fertig. Jetzt wird es Zeit, uns näher mit unserem Werk zu befassen. Dazu werdet Ihr Euch dem Schlimmsten aller Feinde stellen müssen, mit denen wir auf dem Weg nach Andorhal zu tun hatten ... dem ruchlosen Wesen, das in der Ruine der Stadt die Fäden zieht.\n\nIch spreche von Araj dem Beschwörer ... das ist ein Lich und eines der mächtigsten Wesen aus den Reihen der Geißel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5802] = {title = "Feuersäulen geschmiedet", objective = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.\n\nBringt den unvollendeten Dietrich zu Apotheker Zitters im Bollwerk in den Westlichen Pestländern.", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Krater von Un'Goro liegt der Feuersäulengrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Zitters sprechen.", progress = "Habt Ihr den Schaft des Skelettschlüssels fertig gestellt? Es tut mir wirklich Leid, dass Ihr das Meiste zum Kauf der Form beisteuern musstet, aber wir müssen alle unseren Beitrag leisten, um der Geißel Herr zu werden. Wenn Ihr mir den unvollendeten Schlüssel gebt, seid Ihr für den letzten Gegenstand bereit, der benötigt wird, um die Herstellung des Schlüssels abzuschließen.\n\nEs wird nicht gerade einfach werden, aber die ganze Arbeit, die Ihr bis jetzt zur Vorbereitung eines Angriffs auf Andorhal geleistet habt, wird sich schließlich auszahlen. Ihr werdet schon sehen.", completion = "Da haben wir aber einen ziemlich teuren Skelettschlüssel, was, &lt;Name&gt;? Er ist jedoch noch nicht fertig. Jetzt wird es Zeit, uns näher mit unserem Werk zu befassen. Dazu werdet Ihr Euch dem Schlimmsten aller Feinde stellen müssen, mit denen wir auf dem Weg nach Andorhal zu tun hatten ... dem Wesen, das in der Ruine der Stadt die Fäden zieht.\n\nIch spreche von Araj dem Beschwörer ... das ist ein Lich und eines der mächtigsten Wesen aus den Reihen der Geißel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5803] = {title = "Arajs Skarabäus", objective = "Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, <Name>!", progress = "Ihr seid so weit gekommen, <Name>... jetzt steht nur noch die Zerstörung der körperlichen Gestalt von Araj dem Beschwörer zwischen uns und der Fertigstellung des Schlüssels. Ihr müsst Arajs Skarabäus unter allen Umständen an Euch bringen und mir geben - ich werde daraus dann den Kopf des Schlüssels fertigen.", completion = "Ja, perfekt! Ich... ich bin wieder einmal absolut überwältigt, wie heldenhaft Ihr doch seid. Es ist kaum vorstellbar, wie weit zu gehen Ihr bereit seid, um einen Sieg über die Mächte der Finsternis zu erringen.\n\nErlaubt mir jetzt bitte, auch einen kleinen Beitrag dazu zu leisten. Ich habe eine spezielle Tinktur vorbereitet, mit der ich den Skarabäus als Kopf am Schlüssel befestigen kann. Das wird den Schlüssel mit der Kraft erfüllen, die zum Öffnen der verschlossenen Tür in der Scholomance benötigt wird.\n\nAlso dann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5804] = {title = "Arajs Skarabäus", objective = "Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Zitters im Bollwerk, in den Westlichen Pestländern.", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, <Name>!", progress = "Ihr seid so weit gekommen, <Name>... jetzt steht nur noch die Zerstörung der körperlichen Gestalt von Araj dem Beschwörer zwischen uns und der Fertigstellung des Schlüssels. Ihr müsst Arajs Skarabäus an Euch bringen, komme was da wolle, und mir geben - ich werde daraus dann den Kopf des Schlüssels fertigen.", completion = "Ja, perfekt! Ich... ich bin wieder einmal absolut überwältigt, wie geschickt und mutig Ihr doch seid. Es ist kaum vorstellbar, wie weit zu gehen Ihr bereit seid, um einen Sieg zu erringen.\n\nErlaubt mir jetzt bitte, auch einen kleinen Beitrag dazu zu leisten. Ich habe eine spezielle Tinktur vorbereitet, mit der ich den Skarabäus als Kopf am Schlüssel befestigen kann. Das wird den Schlüssel mit der Kraft erfüllen, die zum Öffnen der verschlossenen Tür in der Scholomance benötigt wird.\n\nDas wird nicht lange dauern...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5805] = {title = "Willkommen!", objective = "Bringt Merissa Stillbrunn in Goldhain den Goldhaingeschenkgutschein.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Merissa Stillbrunn in Goldhain einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, &lt;Name&gt;! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][5821] = {title = "Leibwache zu mieten", objective = "Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten.", description = "Unter normalen Umständen würden Rigger und ich unseren Kodo an den Kolkarzentauren vorbeiführen. Aber ab und zu sind Kriegstrommeln der Zentauren zu hören, und dann machen wir sofort Halt. Es ist nicht gut fürs Geschäft, tot zu sein!\n\nIch sag Euch was, <Klasse>, wenn Ihr uns heil am Dorf der Kolkar vorbeibringt, soll es Euer Schaden nicht sein.\n\nEs ist nur eine kurze Strecke und Ihr müsst lediglich dafür sorgen, dass die Karawane intakt bleibt, dann könnt Ihr Euch Eure Belohnung bei Smeed Schraubenbuddel abholen. Ihr findet ihn ein Stück weiter die Straße runter. Wir haben geschäftlich miteinander zu tun.", progress = nil, completion = "Wisst Ihr, es scheint mir nicht besonders lukrativ zu sein, jemanden wie Euch dafür zu bezahlen, Gizeltons Karawane zu beschützen. &lt;Klasse&gt;, wenn ich ein bisschen größer wäre, könnte ich einen Nebenjob annehmen und mit der größten Schusswaffe in der Hand auf Kodos reiten. Und dann würde ich den vermaledeiten Zentauren echt mal zeigen, wer hier der Boss ist.", rewards = "Ihr bekommt:\n\nRing des Händlers"}
MultiLanguageQuestData['de'][5841] = {title = "Willkommen!", objective = "Bringt Yori Bruchhelm in Kharanos den Geschenkgutschein von Kharanos.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Yori Bruchhelm in Kharanos einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", progress = "Hallo! <Name> ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, &lt;Name&gt;! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][5842] = {title = "Willkommen!", objective = "Bringt Orenthil Wisperwind in Dolanaar den Geschenkgutschein von Dolanaar.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Orenthil Wisperwind in Dolanaar einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, &lt;Name&gt;! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][5843] = {title = "Willkommen!", objective = "Bringt Magga am Klingenhügel den Geschenkgutschein des Klingenhügels.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Magga in Klingenhügel einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", progress = "Hallo! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, &lt;Name&gt;! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][5844] = {title = "Willkommen!", objective = "Bringt Vorn Himmelsdeuter im Dorf der Bluthufe den Geschenkgutschein der Bluthufe.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Vorn Himmelsdeuter im Dorf der Bluthufe einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, &lt;Name&gt;! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][5845] = {title = "Von verlorener Ehre", objective = "Reist ins Nordtal im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", description = "Der Orden der Silbernen Hand wurde gar sehr geschwächt, als Uther sein gewaltsames Ende fand.\n\nDer Junge hat durchgehalten, solange er konnte. Er wurde bis zum vom Krieg zerrissenen Weiler Nordtal zurückgetrieben, und dort stellte er sich zu seinem letzten Kampf.\n\nWar noch irgendjemand aus dem Orden am Leben, fragte er sich - und spielte das überhaupt noch eine Rolle?\n\nMit diesem Gedanken im Kopf schmetterte Taelan die Standarte des Ordens zu Boden und entsagte allem, was er gelernt hatte. Auf dem blutgetränkten Boden des Nordtals ließ er seine Ehre zurück.\n\nIhr müsst ins Nordtal reisen und das Symbol der verlorenen Ehre finden.", progress = "Mein Glaube wird Euch leiten, <Name>. Das Licht kennt keine Grenzen.", completion = "Sie ist noch genauso prachtvoll - sogar in diesem zerlumpten Zustand - wie an dem Tag, als ich sie sah und meinen Treueid darauf schwor.\n\nSeine Erlösung naht, und mit ihr vielleicht auch meine...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5846] = {title = "Von Liebe und Familie", objective = "Begebt Euch zur Insel Darrowehr im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.", description = "Als Taelan noch ein Kind war, unternahmen wir mit der Familie oft Ausflüge nach Darrowehr. Bei unserem letzten Besuch malte eine Künstlerin namens Renfray ein Porträt von uns, wie wir am Strand posierten. Das ist die schönste Erinnerung, die ich an Taelan und Karandra habe. Denn es war just dieser Moment, wo ich meine Frau und meinen Sohn in den Armen hielt, dass ich eine Liebe und Verbundenheit mit meiner Familie spürte, die ich seitdem nie wieder erlebt habe.\n\nFalls dieses Gemälde noch existiert, müsst Ihr es finden.\n\nBegebt Euch zur in Trümmern liegenden Insel Darrowehr und seht nach, ob das Gemälde der Künstlerin noch da ist.", progress = nil, completion = "Wie konnte ich das nur vergessen? Viele der Geister auf dieser Insel sind dazu verdammt, ihre letzte glückliche Erinnerung vor ihrem tragischen Ende noch einmal zu durchleben.\n\nIch bin ebenfalls verdammt, aber auf andere Weise als sie - ich bin einer der wenigen, die sich an alles erinnern ...\n\nVielleicht ist das, worum Ihr mich batet, der Grund, warum ich in diesen Ruinen spuke. Vielleicht es das, was mich befreien kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5847] = {title = "Willkommen!", objective = "Bringt Claire Weidner in Brill den Geschenkgutschein von Brill.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Claire Weidner in Brill einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, &lt;Name&gt;! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][5848] = {title = "Von Liebe und Familie", objective = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\n\nBringt das Gemälde zu Tirion Fordring.", description = "Das Gemälde... Es hing jahrelang an der Wand meiner Werkstatt - in der Kaserne des Ordens.\n\nNachdem Tirions Prüfung vorüber war, wusste ich, dass ich das Gemälde nicht mehr dort für alle sichtbar hängen lassen konnte. So versteckte ich es an einem Ort, an dem es niemand vermuten würde.\n\nGeht nach Stratholme und begebt Euch tief in die heutige Scharlachrote Bastion. Sucht dort nach einem Gemälde, auf dem unsere Zwillingsmonde abgebildet sind. Kratzt die Farbe weg, bis mein Meisterwerk zum Vorschein kommt, 'Von Liebe und Familie'.\n\nMöge das Licht Eure Taten leiten.", progress = "Das Gemälde, <Name>. Habt Ihr das Gemälde?", completion = "&lt;Tirion bricht beinahe zusammen, als er das Gemälde sieht.&gt;\n\n&lt;Er beginnt hemmungslos zu weinen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5861] = {title = "Myranda suchen", objective = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.", description = "Ihr habt alles getan, um das ich Euch bislang bat, <Name>. Jetzt fehlt nur noch ein Schritt auf Eurem Weg zur Erlösung.\n\nIhr müsst die gesammelten Gegenstände Taelan aushändigen. Leider werden Euch Taelan und seine Scharlachroten Kreuzzügler angreifen, sobald sie Euer ansichtig werden.\n\nEs gibt nur eine Möglichkeit, meine Nachricht zu übermitteln, und zwar durch Täuschung.\n\nIm Süden findet Ihr Uthers Grabmal. Myranda, eine alte und getreue Vertraute von mir, lebt jetzt dort - geht zu ihr. Zeigt ihr die Gegenstände, dann wird sie Euch helfen.", progress = "Ich wusste, dass dieser Tag kommen würde.", completion = "Ich war Tirions engste Beraterin, als er noch Lord von Mardenholde war. Ich habe mich offen gegen das Urteil des Ordens der Silberhand ausgesprochen und wurde wegen meiner Unverschämtheit verbannt.\n\nEr hat in seinem Leben viel Herzeleid und viele Enttäuschungen erlitten, &lt;Volk&gt;. Seid Ihr bereit, das den Fordrings angetane Unrecht wieder gut zu machen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5862] = {title = "Scharlachrote Täuschung", objective = "Sprecht mit Myranda, um die Scharlachrote Illusion zu erhalten. Begebt Euch nach Herdweiler, während Ihr unter dem Einfluss der Scharlachroten Illusion steht, und übergebt dem Hochlord Taelan FordringTirions Geschenk.\n\nHerdweiler liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.", description = "Ich bin eine Illusionistin, wie Ihr das nennen würdet. Ich könnte zwar eine Illusion erschaffen, die es Euch ermöglichen würde, Herdweiler zu betreten, aber seid gewarnt, meine Kräfte haben Grenzen.\n\nSolltet Ihr Euch zu weit aus diesem Land entfernen, lassen die Effekte dieser Illusion nach. Der Zauber selbst bedarf Unmengen an Konzentration und Kraft meinerseits, und deshalb kann ich den Effekt nur für kurze Zeit aufrechterhalten.\n\nKommt wieder zu mir, wenn Ihr bereit seid.", progress = "Seid Ihr die Verstärkung von Tyrs Hand?", completion = "Was ist das, Soldat?\n\n&lt;Taelan öffnet den Kasten und beginnt, dessen Inhalt zu untersuchen.&gt;\n\nDas... das kann nicht wahr sein. Aber all das, was Ihr mir gezeigt habt...\n\n&lt;Taelan fällt auf die Knie, sein Herz schlägt schneller. Die Wut der Äonen wird über diese Stadt kommen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5863] = {title = "Das Truppenlager der Dünenbrecher", objective = "Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", description = "Erst kürzlich ist eine große Gruppe nomadischer Oger in Tanaris eingetroffen. Südlich von hier haben sie einen großen Bereich der Wüste in Besitz genommen und ein Truppenlager aufgeschlagen. Mehrere kleinere Gruppen durchstreifen momentan die Wüste, einige davon sind in die alten Trollruinen eingedrungen.\n\nDas Truppenlager der Dünenbrecher muss zerstört werden! Wir dürfen nicht zulassen, dass diese Oger zu einer Streitmacht heranwachsen.\n\nDer Anführer der Gruppe heißt Gor'marok der Verheerer. Ich bin mir sicher, dass es den Anfang vom Ende für die Oger bedeuten würde, wenn man ihnen den Anführer nimmt.", progress = nil, completion = "Ich bin ja so froh, dass Ihr das für mich tun konntet, &lt;Name&gt;! Ich danke Euch für Eure Hilfe!", rewards = "BleichsaathandschuheGepolsterte HolzmantelungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5881] = {title = "Hinzurufen der Reserve", objective = "Maggran möchte, dass Ihr Grish Fernläufer am Großen Aufzug im Brachland einen Brief zustellt.", description = "Die Horde kümmert sich gut um ihre Truppen... seit dem großen Krieg ging es uns hier in Kalimdor sehr gut.\n\nIhr müsst mir einen Gefallen tun. Ich lasse einen Jungen namens Grish Fernläufer den Großen Aufzug im Südlichen Brachland bewachen. Gebt ihm diesen Brief, er wird ihn wissen lassen, dass ich einen Ersatzmann angefordert habe, um ihn von seinem Dienst zu entbinden, damit er seine Familie besuchen kann. Er bat mich vor einer Weile darum und wird sich über diese Nachricht freuen.", progress = "Ihr habt Nachricht von Maggran Earthbinder?", completion = "Dies sind großartige Neuigkeiten. Ich sitze schon viel zu lang hier herum und bewache diesen Holzblock. Jetzt kann ich endlich etwas Zeit mit meiner Familie verbringen... Jippie!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5882] = {title = "Salbe durch Jagd", objective = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, &lt;Name&gt;! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5883] = {title = "Salbe durch Bergbau", objective = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5884] = {title = "Salbe durch Sammlung", objective = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, &lt;Volk&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5885] = {title = "Salbe durch Kürschnerei", objective = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5886] = {title = "Salbe durch Entzauberung", objective = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", description = nil, progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, &lt;Name&gt;. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5887] = {title = "Salbe durch Jagd", objective = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, &lt;Name&gt;! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5888] = {title = "Salbe durch Bergbau", objective = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5889] = {title = "Salbe durch Sammlung", objective = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, &lt;Volk&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5890] = {title = "Salbe durch Kürschnerei", objective = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5891] = {title = "Salbe durch Entzauberung", objective = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", description = nil, progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, &lt;Name&gt;. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"}
MultiLanguageQuestData['de'][5892] = {title = "Vorräte der Eisenschachtmine", objective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Allianz in Dun Baldar.", description = "Bevor die Schlacht begann, lagerten wir Vorräte für Dun Baldar in der Eisenschachtmine. Die Troggs, die dort hausten, waren kein Problem solange wir Ersatztruppen hatten, die die Mine bewachen konnten, aber da wir nun gegen die Horde kämpfen, können wir sie nicht mehr kontrollieren.\n\nWir brauchen die Vorräte in der Eisenschachtmine, <Name>. Betretet die Mine und bring mir eine Ladung.", progress = "Habt Ihr die Vorräte, <Name>? Wir können nicht genug davon haben!", completion = "Danke, &lt;Name&gt;! Ich werde sie einem guten Zweck zuführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5893] = {title = "Vorräte der Eisbeißermine", objective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf.", description = "Die Eisbeißermine im Norden war einst ein idealer Ort, um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den Sturmlanzen nun härter werden, haben wir nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die Allianz oder an Untergrundvölker...\n\nAber wir benötigen dennoch unsere Vorräte, <Name>! Geht zu der Eisbeißermine und bringt mir eine Ladung. Seid wachsam, was unsere Feinde anbelangt, die Übermacht in der Schlacht kann sich an jenem Ort schnell ändern...", progress = "Wart Ihr in der Coldtooth-Mine, <Name>? Habt Ihr die Vorräte nach denen ich fragte?", completion = "Ah, Ihr habt Sie bekommen. Gute Arbeit, &lt;Name&gt;! Die Vorräte sind schon etwas moderig, nachdem sie so lange in der Mine lagerten. Ich denke, sie werden uns dennoch sehr weiterhelfen.\n\nVielen Dank, &lt;Name&gt;. Eure Anstrengungen sind lebenswichtig für die Versorgung unserer Streitkräfte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5901] = {title = "Eine Plage komme über Euch", objective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.", description = "Also, um Schmerz und Unfrieden über den Scharlachroten Kreuzzug zu bringen, möchte ich ihnen ihr wertvolles Sägewerk wegnehmen. Ich bin mir sicher, der Verlust einer solchen Ressource wird ihnen ziemlichen Schaden in Bezug auf Verteidigung und Wiederaufbau der Stadt für ihre Zwecke zufügen. Werdet Ihr mir helfen, <Name>?\n\nFangt an, indem Ihr diesen Krug zum Pestwald in den Östlichen Pestländern bringt. Füllt ihn mit den Termiten, die Ihr in ihren Hügeln überall im Wald findet. Kommt wieder, wenn Ihr eine ausreichende Menge habt.", progress = "Habt Ihr die Termiten schon, <Name>? Ich bin sicher, dass es für jemanden, der so schlau ist wie Ihr, <Klasse>, ganz einfach ist.\n\nSobald wir genug davon haben, sorgen wir dafür, dass niemand dieses Sägewerk je wieder verwenden kann!", completion = "Die sind prima, &lt;Name&gt;. Danke.\n\nWenn Ihr bereit seid, können wir uns dem nächsten Schritt zuwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5902] = {title = "Eine Plage komme über Euch", objective = "Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den Westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen.\n\nBereitgestellter Gegenstand: \n", description = "Da wir jetzt jede Menge Termiten haben, bringt dieses stahlverstärkte Fass zum Sägewerk des Nordkamms südlich von Herdweiler. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes, irgendwo weit oben, vielleicht auf eine Kiste oder so was.\n\nNachdem Ihr es geöffnet habt, sollte sich der Rest von selbst erledigen. Kommt einfach hierher zurück und ich werde Euch dafür belohnen, dass Ihr mir geholfen habt.", progress = nil, completion = "Die Termiten werden offensichtlich unruhig, als Ihr das Fass auf die Kiste stellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5903] = {title = "Eine Plage komme über Euch", objective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Nathaniel Dumah im Zugwindlager in den Westlichen Pestländern zurück.", description = "Ich habe bereits viele Male versucht, den Scharlachroten Kreuzzug allein mit Gewalt auszulöschen, doch ohne Erfolg. Daher habe ich mich entschlossen, ihnen das Leben schwer zu machen.\n\nWenn Ihr bereit seid zu helfen, möchte ich, dass Ihr dieses Sägewerk mit der übelsten Termitenart verseucht, die je gefunden wurde.\n\nIm Pestwald, nahe dem einst großen Stratholme, gibt es eine Spezies, die die Seuche und auch die Geißel überlebt hat. Sucht ihre Hügel und füllt diesen Krug mit ihnen, damit wir sie darauf vorbereiten können, auf den Kreuzzug losgelassen zu werden.", progress = "Habt Ihr die Termitenhügel gefunden, <Name>? Ich habe gehört, es gibt sie überall im Pestwald.", completion = "Die sind prima, &lt;Name&gt;. Danke. Schaut sie Euch nur an... so viele von ihnen, alle auf einem Haufen. Ich habe schon beinahe Mitleid mit dem Kreuzzug, aber es war ja schließlich niemals ihre Mühle, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5904] = {title = "Eine Plage komme über Euch", objective = "Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den Westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen.\n\nBereitgestellter Gegenstand: \n", description = "Da wir jetzt die Termiten haben, bringt dieses stahlverstärkte Fass zum Sägewerk des Nordkamms südlich von Herdweiler. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes. Findet einen geeigneten Ort, vielleicht eine Kiste, und öffnet es dann. Die Termiten dürften dann ihre Arbeit tun und die Mühle für den Kreuzzug unbrauchbar machen.", progress = nil, completion = "Die Termiten werden offensichtlich unruhig, als Ihr das Fass auf die Kiste stellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5921] = {title = "Mondlichtung", objective = "Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen.", description = "Alle Druiden sind in den hochheiligen Landen der Mondlichtung willkommen, ungeachtet der derzeitigen Spannungen im Zirkel des Cenarius zwischen dem Erzdruiden Hirschhaupt und dem Bewahrer Remulos, dem Wächter der Mondlichtung. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr das Wissen der Mondlichtung oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr zur Mondlichtung reisen und mit Dendrite Sternenschauer in Nachthafen über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", progress = nil, completion = "Und so beginnt es, Vater Cenarius. Und so beginnt es.\n\nDendrite macht eine schnelle, unsichtbare Geste in die Luft über ihm. Eine leichte Aura der Macht fällt über ihn.\n\nDie erste Perspektive der Natur, die Ihr Euch aneignen müsst, ist die des Bären. Ich werde Euch auf den Weg bringen, um diesen Aspekt des Druidenlebens zu verstehen, aber Ihr müsst ihn Euch zu Eigen machen und pflegen - von nun an und für immer!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5922] = {title = "Mondlichtung", objective = "Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen.", description = "Alle Druiden sind in den hochheiligen Landen der Mondlichtung willkommen, Tauren wie Nachtelfen. Bewahrer Remulos - der Wächter der Mondlichtung - wacht über alle Druiden, die hier ihren Winterschlaf halten. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr das Wissen der Mondlichtung oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr zur Mondlichtung reisen und mit Dendrite Sternenschauer in Nachthafen über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", progress = nil, completion = "Und so beginnt es, Vater Cenarius. Und so beginnt es.\"\n\nDendrite macht eine schnelle, unsichtbare Geste in die Luft über ihm. Eine leichte Aura der Macht fällt über ihn.\n\n\"Die erste Perspektive der Natur, die Ihr Euch aneignen müsst, ist die des Bären. Ich werde Euch auf den Weg bringen, um diesen Aspekt des Druidenlebens zu verstehen, aber Ihr müsst ihn Euch zu Eigen machen und pflegen - von nun an und für immer!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5923] = {title = "Dem Ruf folgen", objective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5924] = {title = "Dem Ruf folgen", objective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5925] = {title = "Dem Ruf folgen", objective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5926] = {title = "Dem Ruf folgen", objective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5927] = {title = "Dem Ruf folgen", objective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5928] = {title = "Dem Ruf folgen", objective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5929] = {title = "Großer Bärengeist", objective = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.", description = "Im nordwestlichen Teil der Mondlichtung liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nachthafen zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5930] = {title = "Großer Bärengeist", objective = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.", description = "Im nordwestlichen Teil der Mondlichtung liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nachthafen zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5931] = {title = "Zurück nach Darnassus", objective = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius.", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Mathrengyl Bärenfährte bewegt sich wirklich im Einklang mit der Natur, selbst wenn er gefährlich nahe der Orte ist, an denen das Gleichgewicht zusammengebrochen ist. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir verlassen uns heute auf seine Weisheit und seine Macht, um unseren Absichten Antrieb zu verleihen. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5932] = {title = "Zurück nach Donnerfels", objective = "Kehrt nach Donnerfels zurück und sprecht mit Turak Runentotem auf der Anhöhe der Ältesten.", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Auch wenn die Tauren auf den Wegen des Cenarius als jung angesehen werden, wandelt Turak Runentotem doch mit großem Gleichgewicht in Gegenwart der Natur. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir &lt;Volk&gt; hören solchen Geistern genau zu und wir alle profitieren von deren Absichten. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5941] = {title = "Rückkehr zu Chromie", objective = "Bringt das Reliktbündel zu Chromie nach Andorhal.", description = "Ihr habt viele Relikte der Schlacht von Darroheim gesammelt. Jedes Mal, wenn Ihr mit weiteren zurückgekehrt seid, sehnte sich mein Herz nach meinem Dorf... sehnte es sich danach, es vor seinem Schicksal zu bewahren.\n\nIch weiß, dass das nicht sein kann, aber Chromie, diese seltsame Gnomin in Andorhal, behauptet, es wäre möglich. Sie sagt, dass Ihr Darroheim retten könnt!\n\nSie hat mich gebeten, die Relikte zu sammeln und sie von Euch zu ihr bringen zu lassen. Sie sagte, dass sie Euch im zerstörten Gasthaus von Andorhal erwartet.", progress = "Ich stand in Kontakt mit Eurem Freund Carlin. Er leidet sehr unter dem Untergang seines Dorfes, doch er spricht sehr gut von Euch und weiß, dass Ihr die Dinge richten könnt.\n\nOh, ich fürchte ich schweife vom Thema ab... <Name>, habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ach ja, da sind sie ja. Gemeinsam weben sie einen mächtigen Zauber, einen, der die Geister von Darrowshire wiedererwecken wird.\n\nMit diesem Zauber und etwas Glück können wir Joseph Redpath retten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5942] = {title = "Versteckte Schätze", objective = "Bringt Josephs Schlüssel zu Josephs Truhe.", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, <Name>. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", progress = "Diese Truhe ist alt und rußverschmiert.", completion = "Der Schlüssel passt in das Schloss, und die Truhe öffnet sich...", rewards = "Ihr bekommt:\n\nRing des SchutzesErzlichttalismanMagierbannspross"}
MultiLanguageQuestData['de'][5943] = {title = "Gizeltons Karawane", objective = "Geleitet Gizeltons Karawane am Zirkel der Mannoroc vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten.", description = "Ihr seht fähig aus, <Volk>. Vielleicht wollt Ihr Euch etwas Geld verdienen? Cork und ich haben mit dieser Karawane angefangen, um einen Haufen Geld zu scheffeln. Doch wir hatten keine Ahnung von den Gefahren, die das schnelle Geld mit sich bringen würde!\n\nDa vor uns liegt der Zirkel der Mannoroc...normalerweise ignorieren die Dämonen uns, aber dieses Mal verängstigt irgendetwas die Kodos. Ich werde Euch dafür bezahlen, wenn Ihr die Karawane auf dem Weg am Zirkel der Mannoroc vorbei beschützt. Sobald wir sicher daran vorbei sind, könnt Ihr Euch Eure Belohnung bei unserem Geschäftspartner Smeed in Schraubenbuddels Lager abholen.", progress = nil, completion = "Ich bin mir nicht sicher, ob es zu ihrem Erfolg beiträgt, Euch so viel Geld für den Schutz von Gizeltons Karawane zu bezahlen. Cork und Rigger verdienen gerade mal ein Goldstück pro Woche, doch solange sie schön meine Kodos bezahlen, kann es mir eigentlich egal sein, wie sie ihre Geschäfte machen.", rewards = "MinischrotflinteKodobränderBeschlagener RingschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][5944] = {title = "In den Träumen", objective = "Geleitet Taelan Fordring aus Herdweiler hinaus.", description = "Über so lange Zeit war ich eine Marionette des Obersten Kreuzfahrers. Welchen Grund gab es, gegen das anzukämpfen, was aus dem Scharlachroten Kreuzzug geworden ist? Es ist Jahrzehnte her, doch die Erinnerungen an meinen Vater - diese kostbaren Erinnerungen - waren es, die mich am Leben erhielten.\n\nIch habe Träume, <Fremder/Fremde>. In diesen Träumen ist mein Vater bei mir. Er steht stolz an meiner Seite, während ich in den Orden aufgenommen werde. Wir bekämpfen Legionen der Geißel, Seite an Seite. Wir bringen der Allianz und Lordaeron Ehre.\n\nIch möchte nicht mehr träumen.\n\nBringt mich zu ihm.", progress = nil, completion = "Der Tod meines Sohnes durch die Hand dieser Monster wird nicht ungestraft bleiben. Findet Trost in dem Wissen, dass der Orden wiedergeboren wurde.\n\nIch nehme jetzt meinen Platz als Hochlord des neuen Orden der Silberhand ein.\n\nNehmt diese Besitztümer aus meiner Vergangenheit ... sie sind alles, was ich Euch für all das anbieten kann, was Ihr getan habt. Bitte, nehmt sie als ein Zeichen meiner Dankbarkeit. Sie haben mir all die Jahre gut gedient.\n\nAuf dass wir uns in besseren Zeiten wiedersehen und uns lang vergangener Tage, hart erkämpfter Schlachten und verblasster Träume erinnern.", rewards = "Verschnörkelte AdamantbrustplatteSchimmernder PlatinkriegshammerTuch der VerbannungAuf Euch wartet eine dieser Belohnungen:\n\nMal von FordringFordrings Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][5961] = {title = "Der Champion der Bansheekönigin", objective = "Sprecht mit Nathanos Pestrufer in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte.", description = "Es freut mich sehr, dass sich die Kampferprobten unserer Sache anschließen. Unsere Schar gewinnt mit jedem Tag an Größe und Stärke. Vielleicht seid Ihr bereit, Euren Mut auf die Probe zu stellen, <Klasse>?\n\nZu den ersten meiner Helden gehörte Nathanos, der heute Pestrufer genannt wird. In unseren Reihen gibt es kaum einen mit mehr Entschlossenheit oder Eifer.\n\nSucht in den Östlichen Pestländern nach ihm. Er wohnt in Marris Siedlung; ab und an streift er durch die dezimierten Ödländer und tötet jeden Abschaum der Geißel und der Allianz, den er aufspüren kann.", progress = nil, completion = "Gewiss hält Euch die Dunkle Fürstin nicht für würdig, ihren Champion zu treffen. Seid Ihr hier, um meine Hunde zu füttern, ja? Einen anderen Grund für diese Unterbrechung kann es nicht geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][5981] = {title = "Tobende Riesen", objective = "Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt.", description = "Vor rund 4.000 Jahren rettete Tyrande Wisperwind die Frostsäblerkönigin aus den Händen tobender Riesen. Seither sind die Frostsäbler Verbündete der Nachtelfen.\n\nDoch die Riesen, die einst eine Gefahr für die Frostsäbler waren, gibt es noch immer, und das nicht allzu weit von hier entfernt. Man nennt sie Frosthagelriesen und sie haben das große Tal südlich von hier für sich beansprucht.\n\nBeweist Eure Treue zu den Frostsäblern. Tötet diese Riesen im Namen der Frostsäblerkönigin Shy-Rotam!", progress = nil, completion = "Exzellent, &lt;Name&gt;. Eure Entschlossenheit blieb nicht unbemerkt.", rewards = nil}
MultiLanguageQuestData['de'][6001] = {title = "Körper und Herz", objective = "Benutzt den Mondstaub des Cenarius mit dem Mondkinstein von Auberdine, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Mathrengyl Bärenfährte in Darnassus, wenn Ihr fertig seid.", description = "Unmittelbar östlich von Auberdine liegen viele Mondkinhöhlen. In der Auberdine am nächsten gelegenen Höhle befindet sich ein Mondkinstein. Mondklaue, der Verteidiger des Steins, stellt sich Euch nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Mondstaub des Cenarius zu benutzen, <Name>... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", progress = nil, completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, &lt;Name&gt;. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein &lt;Klasse&gt; der Klaue zu sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBärengestalt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6002] = {title = "Körper und Herz", objective = "Benutzt den Lunarstaub des Cenarius mit dem Mondkinstein zwischen Mulgore und dem Brachland, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Turak Runentotem in Donnerfels, wenn Ihr fertig seid.", description = "Im Land westlich von Taurajo im Brachland - kurz bevor es in Mulgore übergeht - liegt ein Mondkinstein. Mondkin sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich Euch, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Lunarstaub des Cenarius zu benutzen, <Name>... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", progress = nil, completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, &lt;Name&gt;. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein &lt;Klasse&gt; der Klaue zu sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBärengestalt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6004] = {title = "Offene Rechnungen", objective = "Tötet 2 Scharlachrote Sanitäter, 2 Scharlachrote Jäger, 2 Scharlachrote Magier und 2 Scharlachrote Ritter, bevor Ihr zu Kirsta Grubenschatten in den Westlichen Pestländern zurückkehrt.", description = "Ich wurde als Späher ausgeschickt, um etwas Schaden anzurichten und die Kraft von Herdweilers Verteidigung auszukundschaften. Einige Leute der Allianz sind der Meinung, die kleine Stadt habe mehr als nur eine historische Bedeutung. Meine Aufgabe ist es nicht, diese Bedeutung in Frage zu stellen, aber dennoch sollte ich mich in meiner Verfassung erst erholen, bevor ich weitermache.\n\nWenn Ihr wollt, zahle ich Euch ein hübsches Sümmchen für Eure Hilfe. Fangt südlich von hier in dem Lager an, das sie in der Nähe des kleinen Bollwerks aufgeschlagen haben. Wenn Ihr stark genug seid, könnt Ihr mir vielleicht bei meinem vordringlichen Ziel helfen.", progress = "Wie läuft es, <Name>? Sind sie stärker, als Ihr dachtet? Ich hoffe nicht. Wenn ich das hier durchziehen soll, dann erfordert das eine ganze Menge mehr Kraft als das, was ich bisher von Euch verlangt habe.", completion = "Gut gemacht, &lt;Name&gt;. Ich bin erstaunt, dass Ihr so schnell mit ihnen fertig geworden seid. Danke.\n\nIch habe noch niemanden getroffen, der den Scharlachroten Kreuzzug und dessen Methoden gutgeheißen hätte. Ich glaube so sehr wie jeder andere in Stormwind an das Licht, sie aber haben bewiesen, dass sie nur alle töten wollen, die nicht treu zu ihrer Bewegung stehen ... selbst Unschuldige.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6021] = {title = "Zaeldarr der Ausgestoßene", objective = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des Hoffnungsvollen Lichts.", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.\n\nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen aus der Grube unten. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Westen.\n\nGeht dorthin und schaltet Zaeldarr aus, <Name>. Ich habe seine Schandtaten satt!", progress = "Habt Ihr das Versteck gefunden, <Name>? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6022] = {title = "Töten zu einem bestimmten Zweck", objective = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", description = "Ihr tötet zu einem bestimmten Zweck, solange Ihr in meiner Siedlung seid.\n\nEure erste Aufgabe ist es, meine Hunde zu füttern.\n\nNehmt diesen Mörser nebst Stößel und begebt Euch zu Corins Kreuzung. Dort angekommen findet Ihr Mitglieder der Geißel, die Ihr töten könnt, in recht großer Anzahl.. Aus ihren frischen Kadavern benötige ich lebendige Fäulnis. Nehmt diese lebendige Fäulnis, zermahlt sie im Mörser und lasst sie ruhen, bis sie gerinnt. Bringt die geronnene Fäulnis hierher.\n\nUnd bedenkt, Schwachkopf, dass lebendige Fäulnis der Untoten nicht lange 'lebendig' bleibt. Ihr müsst sie schnell töten!", progress = "Weint Ihr etwa? Wenn Euch das zu 'anstrengend' ist, oh 'Held', dann rate ich Euch, kehrt zur Dunklen Fürstin zurück und erzählt ihr von der schrecklichen Behandlung, die Euch auf meinem Bauernhof zuteil wurde.\n\nUnd jetzt geht mir aus den Augen!", completion = "Enttäuschend. Ich hatte gehofft, ich würde stattdessen Euch an meine Hunde verfüttern können.\n\n&lt;Nathanos seufzt.&gt;\n\nNa, wenigstens haben sie etwas zu fressen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6023] = {title = "Offene Rechnungen", objective = "Besiegt Jägerin Radley und Dragoner Durgen, bevor Ihr zu Kirsta Grubenschatten in den Westlichen Pestländern zurückkehrt.", description = "Meine wahre Mission bestand darin, die äußeren Kräfte des Scharlachroten Kreuzzugs zu schwächen und dann Herdweiler zu infiltrieren, damit ich ihre Zahl abschätzen kann. In meiner Verfassung kann ich das immer noch nicht allein, vielleicht dürfte ich Euch ja erneut um Eure Unterstützung bitten, <Name>? Bevor ich entdeckt wurde, konnte ich die Informationen sammeln, dass der Kreuzzug zwei wichtige Mitglieder hat, die das Rückgrat ihrer Streitkräfte außerhalb der Stadt bilden: Jägerin Radley und Dragoner Durgen. Tötet sie, das bringt uns schon weiter. Sie müssten am Pass von Herdweiler außerhalb der Stadtgrenze sein.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt mir mehr geholfen als ich hoffen durfte. Die Luft hier scheint mir die Willenskraft auszusaugen. Ich bin müde und spüre, dass es sich nicht bessern wird, solange ich hier bin.\n\nIch habe wirklich keine Ahnung, wie ich nach Hearthglen hineingelangen und melden soll, wie stark die Präsenz des Scharlachroten Kreuzzugs dort ist.\n\nAber das ist ein anderes Thema. Bevor Ihr geht, hier, nehmt dies... als Bezahlung für Eure Hilfe. Nochmals danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6024] = {title = "Hameyas Bitte", objective = "Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", description = "Tötet mich. Bevor es zu spät ist.\n\nIch bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Geschwister und ich verdorbenes Fleisch... und wir veränderten uns. Wir sind infiziert.\n\nIch spüre bereits die Worte des Lichs, der mich bedrängt, dass ich nach Zul'Mashar gehen und noch mehr von meinem Volk infizieren soll. Ich kann nicht widerstehen, daher verfasste ich diese Schriftrolle, ehe es um meine Willenskraft geschehen ist.\n\nIch habe hinter dieser Gruft eine Truhe neben einem Wagen in der Erde vergraben, aber nur mein Schlüssel kann sie öffnen. Ich habe den Schlüssel. Wenn Ihr meinen Schatz möchtet, sucht mich.\n\nTötet mich. Bevor es zu spät ist.", progress = "Die hier vergrabene Truhe ist fest verschlossen.", completion = "Hameyas Truhe wurde geöffnet!!!", rewards = "Ihr bekommt:\n\nHameyas TöterHameyas Umhang"}
MultiLanguageQuestData['de'][6025] = {title = "Offene Rechnungen", objective = "Geht nach Herdweiler, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Grubenschatten in den Westlichen Pestländern zurück.", description = "Was? Wirklich? Ihr möchtet noch mehr wissen? Aber Ihr habt bereits so viel für mich getan, <Name>. Ich kann Euch unmöglich darum bitten, an meiner statt nach Herdweiler zu gehen.\n\nSeid Ihr sicher, <Name>? Herdweiler ist viel gefährlicher als der Pass - ich kann Euch weder Schutz noch Informationen geben, was Ihr da vorfinden könntet.\n\nAlso, wenn Ihr wirklich bereit seid, mir zu helfen, dann geht in die Stadt und sucht eine erhöhte Stelle, von der aus Ihr einen guten Überblick habt. Dort könnt Ihr ihre Zahl abschätzen und mir dann Bericht erstatten. Aber seid vorsichtig...", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Danke!\n\nIch kehre zu Elling zurück... Ich meine nach Stormwind, so schnell ich kann. Hier, nehmt diese Münze, das ist das Mindeste, was ich für Euch tun kann. Ihr macht Eurem Volk Ehre, &lt;Name&gt;. Habt Dank, und viel Glück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6026] = {title = "Das ist viel verlangt", objective = "Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.\n\nFür diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden.", description = "Diese Leute von der Argentumdämmerung haben den alten Smokey beauftragt, ein paar Abrissarbeiten für sie durchzuführen. Smokeys Mama hat keinen Trottel großgezogen. Wenn bares Gold auf den Tisch gelegt wird, ist Smokey stets zu Diensten. Das ist mein Motto!\n\nIch wäre bereit, den Profit mit Euch zu teilen, wenn Ihr mir ein wenig zuarbeiten wollt. Das ist der Plan: Ich geh rüber in den Pestwald und kennzeichne die Gebäude, die abgerissen werden müssen. Ihr sammelt die Komponenten für die Bomben. Wir treffen uns hier wieder, wenn Ihr alles habt. Abgemacht?", progress = "Vertraut dem alten Smokey, <Volk>. Es wird sich lohnen. Die Leute von der Argentumdämmerung machen kein Gewese, was Bezahlung angeht.", completion = "Ich bezahle Euch eine Hälfte gleich und die andere, wenn die Aufgabe erledigt ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6027] = {title = "Buch der Uralten", objective = "Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.", description = "<Name>, ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf der Insel Ranazjar nordwestlich von hier in die Hand der Schlangenstatue. Dadurch wird jener gerufen, der das 'Buch der Uralten' beschützt. Dieses Buch birgt die Geheimnisse der Naga. Geheimnisse, die seit Jahrhunderten gewahrt werden. Bringt mir dieses Buch, dann werden wir mehr über unsere schuppigen Widersacher erfahren!", progress = "Ah, <Name>! Schön, Euch zu wiederzusehen. Habt Ihr das 'Buch der Uralten'?", completion = "Das lange verschollene 'Buch der Uralten'! Ich werde dafür sorgen, dass der Hohe Rat dieses Buch bekommt. Ihr habt heute Großes vollbracht, und dafür muss man Euch danken... wie man einem Helden dankt!", rewards = "SeidenbandmanschettenRundgeschliffene MetallschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6028] = {title = "Der Bericht der Ewigen Warte", objective = "Bringt den Bericht der Ewigen Warte zu Argentumoffizier Reinherz im Zugwindlager in den Westlichen Pestländern.", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung der Ewigen Warte. Ich muss Argentumoffizier Reinherz im Zugwindlager einen Fortschrittsbericht zukommen lassen. Das ist weit entfernt von hier am südlichen Rand der Westlichen Pestländer.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meiner Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihr zu bekommen!", progress = "Seid gegrüßt, <Klasse>. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Chillwind-Lager seid. Vielleicht habe ich auch ein bisschen Arbeit für Euch...", completion = "Gregor ist außerordentlich findig. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6029] = {title = "Der Bericht der Ewigen Warte", objective = "Bringt den Bericht der Ewigen Warte zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern.", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung der Ewigen Warte. Ich muss Argentumoffizier Garush beim Bollwerk einen Fortschrittsbericht zukommen lassen; das ist weit entfernt von hier am westlichen Rand der Westlichen Pestländer, östlich von Tirisfal.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meinem Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihm zu bekommen!", progress = "Seid gegrüßt, <Klasse>. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Bollwerk seid. Ich könnte Euch auch die Möglichkeit bieten, für eine Sache zu kämpfen, für die es sich zu kämpfen lohnt!", completion = "Gregor ist außerordentlich findig für einen Menschen. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6030] = {title = "Fürst Nicholas Zverenhoff", objective = "Bringt das Buch 'Studien über das Geistsprechen' zu Fürst Nicholas Zverenhoff in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ein einsiedlerisches Medium namens Umbranse, das in dieser Gegend ansässig ist, hat der Argentumdämmerung ein literarisches Meistwerk geschenkt... es handelt sich vermutlich um die größte Sammlung mündlicher Überlieferungen, die je zu Papier gebracht wurde.\n\nFürst Nicholas Zverenhoff, einer der angesehensten Anführer der Dämmerung, ist ein brillanter Sprachwissenschaftler. Könntet Ihr ihm das für mich bringen - natürlich gegen eine Belohnung? Bei der Kapelle des Hoffnungsvollen Lichts, tief im östlichen Teil der Östlichen Pestländer - da hält er sich gerade auf.", progress = "Möge das Licht Euch in diesen gefährlichen Zeiten leiten, <Klasse>. Was führt Euch zu diesem Fanal der Hoffnung inmitten von Dunkelheit und Verzweiflung?", completion = "Das... ist ein ganz besonderes Buch, das Ihr mir da gebracht habt. Ich würde Euch gern sagen, dass 'besonders' in diesem Fall 'einzigartig und höchstwahrscheinlich lehrreich' bedeutet, doch das wird man sehen.\n\n\"Ooooooh?\" Wer sich so etwas ausdenkt, kann doch nicht bei klarem Verstand sein?\n\nAber ich habe von diesem Umbranse gehört, von dem Gregor sprach, daher ist das hier nicht ganz wertlos. Ich tue mein Bestes, es zu entziffern. Und was Euch angeht... bitte nehmt dies... mit freundlichen Grüßen der Argentumdämmerung. Da Ihr schon mal hier seid, vielleicht könnt Ihr uns noch bei anderen Dingen unterstützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6031] = {title = "Runenstoff", objective = "Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste.", description = "Wir in der Holzschlundfeste sind eigentlich ganz zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für das Geschäft.\n\nEs ist noch nicht lange her, da kam eine Nachtelfenfreundin, die einen Runenumhang trug, auf die Holzschlundfeste. Runenstoff ist bei uns selten, aber der Umhang war so edel, dass mein Volk jetzt von mir verlangt, mehr Runenstoffkleidung zu fertigen.\n\nWerdet Ihr mir Runenstoff bringen? Wenn Ihr mir ausreichend beschafft, gebe ich Euch etwas im Tausch dafür.", progress = "Habt Ihr den Runenstoff? Mein Volk ist ganz gierig nach weiteren Kleidungsstücken aus Runenstoff!", completion = "Ah, Ihr habt den Stoff. Was für ein herrliches Material!\n\nDanke, &lt;Name&gt;. Ihr seid ein wahrer Freund. Bitte nehmt dies als Gegenleistung.", rewards = "SchattenhautschiftungStahlfelsstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6032] = {title = "Hochheiliger Stoff", objective = "Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste.", description = "Die Einwohner der Holzschlundfeste mögen das Gefühl von Runenstoff auf der Haut, aber er ist nichts Hochheiliges für uns. Mondstoff dagegen ist hochheilig.\n\nBringt mir einen kleinen Vorrat dieses heiligen Stoffs und ich lehre Euch eine geheime Schneidertechnik.", progress = "Habt Ihr den Mondstoff dabei, <Name>?", completion = "Ah, sehr gut. Dieser Mondstoff wird für Gewänder benutzt, die für unser Volk hochheilig sind. Danke, &lt;Name&gt;. Jetzt werde ich Euch ausbilden.", rewards = "Ihr erlernt:\n\nMondstoffstiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMondstoffstiefel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6041] = {title = "When Smokey Sings, I Get Violent", objective = "Reist in den Pestwald, nordwestlich der Kapelle des Hoffnungsvollen Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.\n\nWenn Ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.\n\nÜbrigens, Smokeys spezielles Präparat ist recht...instabil.", description = "Während Ihr die Vorräte gesammelt habt, habe ich einige meiner Leute die Geißelbauwerke kennzeichnen lassen, die wir abreißen müssen.\n\nSo ist der Plan: Ich gebe Euch zehn Stecken meines speziellen Präparats. Ihr bringt sie rüber in den Pestwald und platziert sie in den Geißelbauwerken, die für die Sprengung markiert wurden.\n\n<Smokey schnippt mit den Fingern.>\n\nBing! So einfach ist das.", progress = nil, completion = "Ihr seid viel dunkler als ich in Erinnerung habe. Der Look steht Euch nicht schlecht, ein Look, der sagt: 'Ich wurde von einer hochexplosiven Bombe angesengt.'\n\n&lt;Smokey lacht.&gt;\n\nNa, egal! Hier ist Euer Anteil an der Beute. Ich habe noch eine Kleinigkeit dazu gelegt, die die Verbrennungen lindert.", rewards = "Smokeys SprengstoffschleuderSmokeys FeuerspuckerIhr bekommt:\n\nFeuchtes HandtuchSmokeys Tuch"}
MultiLanguageQuestData['de'][6042] = {title = "Die kleinen Ärgernisse des Un-Lebens", objective = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr fertig seid.", description = "Man kann keine zwei Schritte von diesem Hof runter, ohne auf eine dieser grässlichen Fledermäuse zu stoßen. Ich möchte die Hunde ausführen und die Geißel abschlachten können, ohne dass mich diese elenden, schmutzigen Fledermäuse behelligen. Ich habe Wichtigeres mit meiner Zeit anzufangen, als tagein, tagaus sinnlos Fledermäuse zu töten. Ihr allerdings nicht.\n\nWas? Eure Ausbildung? Das ist Eure Ausbildung! Jetzt geht mir aus den Augen und kommt erst zurück, wenn Ihr eine ordentliche Menge dieser geflügelten Dämonen getötet habt! Enttäuscht mich nicht.", progress = nil, completion = "Unglaublich, was ein wenig Zorn und Wut doch bewirken können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6061] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", description = "Für uns als Tauren ist es wichtig, dass wir den Traditionen unserer Vorfahren folgen und gegen mächtige Kreaturen kämpfen. Wenn wir diese Kreaturen bezwingen, können wir ihre Geister aufnehmen und näher bei der Erdenmutter sein.\n\nAuf dieselbe Weise hilft es uns, eins mit der Natur zu werden, wenn wir ein Tier zähmen, damit es an unserer Seite kämpft. Ihr werdet auch irgendwann lernen, ein Tier Eurer Wahl zu zähmen. Aber alles erfordert Übung und Ihr müsst noch viel lernen. Nehmt als erstes diese Zähmrute. Ihr müsst einen ausgewachsenen Ebenenschreiter zähmen.", progress = "Übt Eure Fertigkeiten, <Name>. Zähmt den ausgewachsenen Ebenenschreiter.", completion = "Die Erdenmutter hat mir Zeichen geschickt. Ihr habt Eure Sache gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6062] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", description = "Es ist eine bewundernswerte Fertigkeit, wenn man über die Natur gebietet. Als Jäger müsst Ihr lernen, wie man Macht und Kraft benutzt, die jeder Kreatur Eurer Wahl innewohnt.\n\nEs ist nicht einfach, Kontrolle über ein Tier zu erlangen. Ihr müsst diese Aufgabe mit großer Entschlossenheit verfolgen.\n\nAls erste Aufgabe nehmt diese Zähmrute und zähmt damit einen scheckigen Terroreber. Ihr findet sie in der Nähe von Klingenhügel. Übt Eure Fertigkeiten im Kampf mit dem Eber an Eurer Seite und kommt dann zu mir zurück.", progress = "Viel Glück, junger <Klasse>.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Ich glaube, Ihr seid bereit für die nächste Aufgabe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6063] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", description = "Als Jäger dürft Ihr niemals die Verantwortung vergessen, die Ihr tragt. Die Natur ist eine Kraft, die sich nicht Euren Wünschen beugt. Man muss sie respektieren und anerkennen als etwas Stärkeres als die eigene Existenz.\n\n<Name>, Ihr müsst beweisen, dass Ihr das verstanden habt, bevor Ihr die Fähigkeit erwerben könnt, Euch ein Tier als Gefährten zu zähmen.\n\nEure erste Aufgabe ist es, diese Zähmrute zu nehmen. Mit ihr könnt Ihr einen Waldweberlauerer zähmen. Zähmt ihn und übt Eure Fertigkeiten als Jäger.", progress = "Ihr werdet lernen, <Name>, und eines Tages ein großer <Klasse> sein.", completion = "Exzellent, &lt;Name&gt;! Ihr lernt wirklich sehr schnell.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6064] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.", description = "Hallo, <Bursche/Mädchen>! Ihr wollt also wissen, wie Ihr ein eigenes Tier bekommen könnt?\n\nGut, dann lasst uns anfangen. Wenn es um das Jagen geht, dann ist nichts wichtiger als Eure Ausrüstung, aber wir können ein andermal über meinen neuen Schrapnell-Blaster sprechen. Konzentrieren wir uns vorerst auf etwas, das Euch gewiss interessiert: ein Tier!\n\nAm besten lernt Ihr, wenn Ihr verschiedene Kreaturen als Gefährten ausprobiert und herausfindet, welche Ihr mögt. Sucht also einen großen Klippeneber und benutzt dann diese Zähmrute, um ihn zu zähmen.", progress = "Keine Bange, Bursche! Ihr könnt ein paar ausprobieren, ehe Ihr Euch für eines entscheiden müsst.", completion = "Ich weiß, ich weiß, Ihr fragt Euch, was als nächstes kommt, was?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6065] = {title = "Der Weg des Jägers", objective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6066] = {title = "Der Weg des Jägers", objective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6067] = {title = "Der Weg des Jägers", objective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6068] = {title = "Der Weg des Jägers", objective = "Sprecht mit Thotar in Klingenhügel in Durotar.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube auch, Ihr seid bereit...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6069] = {title = "Der Weg des Jägers", objective = "Sprecht mit Thotar in Klingenhügel in Durotar.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube, Ihr seid bereit für die Ausbildung...", rewards = nil}
MultiLanguageQuestData['de'][6070] = {title = "Der Weg des Jägers", objective = "Sprecht mit Thotar in Klingenhügel in Durotar.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6071] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, es ist an der Zeit, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6072] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6073] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, es ist an der Zeit, Euch auszubilden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6074] = {title = "Der Weg des Jägers", objective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6075] = {title = "Der Weg des Jägers", objective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube, es ist an der Zeit, dass Ihr ausgebildet werdet...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6076] = {title = "Der Weg des Jägers", objective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, &lt;Klasse&gt;, es ist Zeit...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6081] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Ormak Grimmschlag in Orgrimmar.", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es auszubilden.\n\nReist nach Orgrimmar. Dort müsst Ihr mit Ormak Grimmschlag sprechen, einem unserer angesehensten Jäger. Er wird Euch die Fähigkeit verleihen, Euer neues Tier auszubilden. Ihr findet ihn im Tal der Ehre.\n\nViel Glück, <Name>.", progress = nil, completion = "Ein junger &lt;Klasse&gt; seid Ihr, ich verstehe. Ja, ich gewähre Euch die Fertigkeiten, die Ihr braucht, um Euer neues Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt, &lt;Klasse&gt;. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", rewards = "Ihr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6082] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", description = "Die letzte Kreatur, die Ihr zähmen müsst, wird dasselbe mit Euch versuchen: der gepanzerte Skorpid. Er schlägt schnell und selbstbewusst zu. Eine solche Macht zu kontrollieren ist Euer Schicksal als Jäger.\n\nWenn Ihr zurückkehrt verleihe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird Euren Befehlen gehorchen. Unter Eurer Kontrolle wird Euer Tier an Eurer Seite Erfahrung sammeln. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", progress = "Konntet Ihr den Skorpid zähmen?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, &lt;Name&gt;. Es ist Zeit, dass Ihr das Gelernte anwendet und Euch ein eigenes Tier wählt.\n\nHier, bitte schön, &lt;Name&gt;. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6083] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", description = "Der Vorteil, den Euch ein Tier gegen Eure Rivalen bietet, wird zur Kenntnis genommen, <Name>! Wenn Ihr Kontrolle über eine andere Kreatur erlangt, erhöht Ihr Eure eigene Kraft. Euer Tier muss sozusagen Euer verlängerter Arm werden.\n\nDie nächste Aufgabe führt Euch vom Land weg. Ihr findet die nächste Kreatur in den Gewässern vor der Küste. Sucht jenseits von Sen'jin nahe den Echoinseln. Sucht nach einem lebhaften Krebs, der Brandungskriecher genannt wird. Benutzt die Zähmrute, um ihn zu zähmen und übt dann Eure Fertigkeiten.", progress = "Ihr müsst üben, damit Ihr die Fertigkeiten erlangt, die Ihr braucht, um Euer Tier wirksam zu kontrollieren. Habt Ihr schon einen Brandungskriecher gezähmt?", completion = "Ihr lernt schnell, &lt;Name&gt;. Das habt Ihr gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6084] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildherz in Kharanos zurück.", description = "Diese Klippeneber sind recht bullig. Vielleicht möchtet Ihr etwas mit ein wenig mehr Grazie? Na gut, da hab ich genau das Richtige. Südlich und östlich von hier findet Ihr große weiße Katzen, die man Schneeleoparden nennt. Genau wie bei einem elegant geschnitzten Gewehr verbirgt sich hinter dem wunderschönen Äußeren ein kräftiger Kämpfer, der extremen Schaden zufügen kann. Ihr werdet feststellen, dass sie wesentlich agiler und schneller als Euer gezähmter Eber sind.\n\nNehmt diese Zähmrute und findet heraus, wie Euch der Schneeleopard gefällt.", progress = "Was haltet Ihr von dem Schneeleoparden, <Name>?", completion = "Wenn ich glaube, dass Ihr genug gelernt habt, gewähre ich Euch die Fähigkeit, jedes Tier zu wählen, das Euch gefällt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6085] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.", description = "Vielleicht hättet Ihr gern eine Kreatur, die etwas mehr besitzt als nur rohe Kraft? Der Eisklauenbär ist ein ausgezeichneter Gefährte für einen angehenden Jäger wie Euch und östlich von Kharanos zu finden. Hier ist die Zähmrute. Probiert dieses Geschöpf als Euer Tier aus und findet heraus, wie es Euch gefällt!\n\nWenn Ihr zurückkehrt, gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man sie ganz nach Belieben ruft und wegschickt.", progress = "Habt Ihr den Eisklauenbären schon gezähmt?", completion = "Hier, bitte schön, &lt;Name&gt;. Ich geb Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken.\n\nSucht Euch ein gutes, treues Tier und genießt die Jagd!", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6086] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Belia Donnerstein in Eisenschmiede.", description = "<Name>, Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr müsst die Fertigkeiten erlangen, es auszubilden.\n\nReist nach Eisenschmiede und sucht die Halle der Waffen. Dort müsst Ihr mit Belia Donnerstein sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Macht, Euer neues Tier auszubilden, also macht Euch auf den Weg, <Bursche/Mädchen>.\n\nBelia ist recht umgänglich, Ihr findet gewiss ihre Zustimmung. Viel Glück, <Name>.", progress = nil, completion = "Ein neuer Rekrut, hm? Ich sehe, Ihr seid auf dem Weg, ein großer &lt;Klasse&gt; zu werden.\n\nJa, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nVergesst nicht, Euer neues Tier wird Euch stets zu Diensten sein, wenn Ihr es respektiert und gut behandelt. Dann wird Euer Tier Euer treuester Freund.", rewards = "Ihr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6087] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", description = "Ihr besitzt einen feurigen Geist, Jäger, und brennt schon auf Eure nächste Herausforderung.\n\nAls nächste Aufgabe müsst Ihr einen Wolf, der als Präriepirscher bekannt ist, zum Gefährten gewinnen. Diese Kreatur ist flink und furchtlos. Wenn Ihr diese Bestie als Euer Tier wollt, müsst Ihr diese Eigenschaften ebenfalls erlangen.\n\nIm Kampf werdet Ihr lernen, wie Ihr und Euer Tier ein Team werdet. Letztendlich müsst Ihr wie ein Wesen handeln, Muskel an Muskel.\n\nHier habt Ihr die Zähmrute, <Name>. Zähmt einen Präriepirscher und übt Eure Fertigkeiten.", progress = "Habt Ihr schon einen Präriepirscher gefunden?", completion = "Ja... Die Erdenmutter glaubt, Ihr seid bereit für die nächste Lektion.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6088] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", description = "Die letzte Aufgabe, die ich für Euch habe, verlangt von Euch, dass Ihr eine Kreatur zähmt, die den Himmel bewohnt. Der Sturzflieger ist ein schwieriger Gegner, aber als Euer Verbündeter gibt er Euch seine scharfen Angriffe und seine bedrohliche Präsenz.\n\nWenn Ihr zurückkehrt gebe ich Euch durch den Willen der Erdenmutter die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", progress = "Ihr werdet bald bereit sein, <Name>.", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, &lt;Name&gt;. Möge der Segen der Erdenmutter Euch bei der Wahl Eures Tiers leiten.\n\nHier, bitte schön, &lt;Name&gt;. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz und ehrt die Erdenmutter.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6089] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels.", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Donnerfels. Dort müsst Ihr mit Holt Donnerhorn sprechen, einem unserer angesehensten Jäger. Wenn er Euch für würdig befindet, gibt er Euch die Fähigkeit, Euer neues Tier auszubilden.\n\nHolt hat die mächtigsten und gefürchtetsten Bestien von Azeroth bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der Erdenmutter ist stark. Ihr könnt viel von ihm lernen. Viel Glück, <Name>.", progress = nil, completion = "Ein junger &lt;Klasse&gt; seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt. Möge die Erdenmutter Euch auf Eurem Weg geleiten. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", rewards = "Ihr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6101] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", description = "Auf die Vielfalt der Natur kann man sich verlassen, <Name>. Sie ist insofern vorhersehbar, dass sie niemals gleich bleibt. Sie ist in konstantem Wandel.\n\nDie Aufgaben, die ich Euch gebe, werden Euch helfen, die enormen Unterschiede der Kreaturen zu erkennen, die Ihr als Eure Gefährten wählen könnt.\n\nNehmt diese Zähmrute und zähmt damit einen der pirschenden Nachtsäbler, die im Süden zu finden sind. Übt Eure Fertigkeiten als Jäger. Dann werdet Ihr die Übereinstimmungen und Unterschiede der Natur begreifen.", progress = "Es liegt in der Natur jedes Nachtelfen, dass er das Gleichgewicht zwischen der Natur und sich selbst begreift.", completion = "Ich sehe, dass Ihr entschlossen seid und verstanden habt, was ich Euch gelehrt habe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6102] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", description = "Ihr habt zwei Kreaturen gezähmt, die am Boden leben, jetzt müsst Ihr eine zähmen, die am Himmel dahinzieht. Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen, die man westlich von hier findet. Übt Eure Fertigkeiten mit dieser mächtigen Eule an Eurer Seite.\n\nWenn Ihr zurückkehrt gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", progress = "Ich bin stolz auf Eure Leistungen, <Name>. Habt Ihr die letzte Aufgabe vollendet, die ich Euch gab?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, &lt;Name&gt;. Lasst mich Euch noch einen Rat geben: Seid umsichtig, wenn Ihr Euer erstes Tier wählt. Soll es eine Kreatur des Landes, des Wassers oder des Himmels sein? Was auch immer, Euer Tier wird zweifellos eine ganze Weile bei Euch sein.\n\nHier, bitte schön, &lt;Name&gt;. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6103] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Darnassus. Dort müsst Ihr mit Jocaste sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Fähigkeit, Euer neues Tier auszubilden, also sputet Euch.\n\nJocaste mag einen strengen Eindruck machen, freut sich aber stets, wenn sie den Aufstieg eines neuen Jägers verfolgen kann. Behandelt sie mit Respekt, dann wird sie Euch ebenso begegnen. Viel Glück, <Name>.", progress = nil, completion = "Ein angehender &lt;Klasse&gt; seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nDenkt daran, &lt;Name&gt;, respektiert stets das Gleichgewicht und lebt in Ehrfurcht vor der Natur ringsum. Geht jetzt. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", rewards = "Ihr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6121] = {title = "Neue Lektionen", objective = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, <Name>. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist zur Mondlichtung und sprecht mit Dendrite Sternenschauer. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", progress = nil, completion = "Seid gegrüßt, junger &lt;Klasse&gt;, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. In Auberdine traten vermehrt Fälle von Tiervergiftungen auf und die Dorfbewohner konnten sie nicht heilen. Aus diesem Grund bat ein Repräsentant Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6122] = {title = "Die eigentliche Ursache", objective = "Benutzt das leere Gefäß bei den Klippenquellfällen und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.\n\nBringt die gefüllte Probe der Klippenquellfälle zu Alanndarian Nachtweise nach Auberdine in Dunkelküste.", description = "Die Klippenquellfälle in Dunkelküste dienen als wichtigste Trinkwasserquelle in der Region. Ich fürchte, jetzt ist es die primäre Ursache des Gifts, das der dortigen Fauna schadet, besonders dem Wild. Holt mit diesem Gefäß etwas Wasser vom Höhleneingang, aber seid vorsichtig, inzwischen hausen gefährliche Naga in einer Höhle bei den Wasserfällen.\n\nWenn Ihr es gefüllt habt, bringt es zu Alanndarian Nachtweise in Auberdine. Sie bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihr dieses Übels annehmen.", progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden? Das ist wunderbar! Wir haben hier eine echte Krisensituation, was das Wild angeht, und sind dankbar für jedwede Hilfe.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden ...", completion = "Bei Elune, dieses Wasser ist widerwärtig! Kein Wunder, dass das Wild krank ist.\n\nEtwas verunreinigt das Wasser und damit Dunkelküstes gesamten Wasservorrat. Man hat überall in der Gegend krankes Wild gesehen, nicht nur am Fluss. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6123] = {title = "Das Heilmittel sammeln", objective = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nachtweise in Auberdine, damit sie eine Heilsalbe machen kann.", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für das Wild anrühre. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn wir Pech haben und Ihr keiner seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nUnd der besseren Wirksamkeit wegen brauche ich etwas Lunarfungus. Es ist recht leicht, Lunarfungusblüten zu finden. In den Höhlen östlich von hier gedeihen sie reichlich. Mondkin, die neuerdings recht gereizt sind, hausen in diesen Höhlen, also seid vorsichtig.", progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Das Wild wird von allein ganz bestimmt nicht wieder gesund, daher sollten wir uns besser beeilen!", completion = "Das ist gut, &lt;Name&gt;, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6124] = {title = "Heilung der Kranken", objective = "Benutzt die heilende Tiersalbe bei 10 kränklichen Rehen in ganz Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass kränkliche Rehe südlich des Klippenquells, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo das Eschental beginnt, aufgetaucht ist.", description = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, <Name>. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um Dunkelküste wimmelt es von krankem Wild. Heilt es mit der Salbe von seinem Übel.\n\nDendrite Sternenschauer bei der Mondlichtung wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius Auberdines Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", progress = nil, completion = "Ihr habt bei der Heilung des kranken Wilds von Dunkelküste wahre Wunder gewirkt. Es war das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. In Darnassus gibt es welche, die die Bedrohung ernst nehmen... und es gibt welche, die ignorieren die zunehmenden Zeichen... Ich hoffe, Ihr werdet nicht die Augen vor dem Offensichtlichen verschließen, &lt;Name&gt;.\n\nWie auch immer, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.", rewards = "Ihr bekommt:\n\nSchleierstaubmedizinbeutel"}
MultiLanguageQuestData['de'][6125] = {title = "Macht über Gift", objective = "Kehrt zu Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus zurück.", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Mathrengyl Bärenfährte in Darnassus zurückkehren, <Name>. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", progress = nil, completion = "Willkommen - ich verfolge Eure Fortschritte in dieser Lektion seit Eurem Aufbruch und muss gestehen, ich war überrascht, als ich von der Situation in Auberdine erfuhr. Dies erfordert weitere Untersuchungen, da die Freisetzung solcher Gifte in die Umwelt das Gleichgewicht empfindlich stört.\n\nIhr habt Euch unter großem Druck wacker gehalten. Dafür finde ich keine bessere Möglichkeit, als Euch mit permanenter Macht über Gift zu belohnen. Verwendet sie weise, &lt;Name&gt;... verwendet sie weise.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6126] = {title = "Neue Lektionen", objective = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, <Name>. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um...und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist zur Mondlichtung und sprecht mit Dendrite Sternenschauer. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", progress = nil, completion = "Seid gegrüßt, junger &lt;Klasse&gt;, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. Bei Crossroads im Brachland traten vermehrt Fälle von Tiervergiftungen auf, die nicht unter Kontrolle zu bringen sind. Jemand dort bat Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6127] = {title = "Die eigentliche Ursache", objective = "Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.\n\nBringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runentotem beim Wegekreuz im Brachland.", description = "Der Glutnebelgipfel nordwestlich des Wegekreuzes ist höchstwahrscheinlich die Quelle, von wo aus sich das Gift verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen. Dieses Wasser wurde vermutlich durch Dämonen anbetende Kultisten der Brennenden Klinge verunreinigt.\n\nEntnehmt dem Teich auf der Spitze des Gipfels mit diesem Behältnis eine Probe. Wenn es gefüllt ist, bringt es zu Tonga Runentotem beim Wegekreuz. Er bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihm dieses Übels annehmen.", progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden, ja? Das ist ein Glück für uns! Unsere Bemühungen, den kranken Gazellen im nördlichen Brachland Gleichgewicht zu bringen, haben nichts genutzt. Wir sind für jede Hilfe dankbar.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden...", completion = "Bei meinen Vorfahren, dieses Wasser ist widerwärtig! Kein Wunder, dass die Gazellen krank sind.\n\nEtwas verunreinigt das Wasser und zerstört damit langsam das Ökosystem im nördlichen Brachland. Überall nördlich der Ost-West-Straße wurden kranke Gazellen gesehen. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6128] = {title = "Das Heilmittel sammeln", objective = "Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runentotem beim Wegekreuz, damit er eine Heilsalbe machen kann.", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für die Gazellen herstelle. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn Ihr nicht mit dieser Kunst vertraut seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nDer Wirksamkeit wegen brauche ich zuletzt Kodohörner – Splitter und Bruchstücke reichen aber nicht aus. Kodos, mit denen Ihr fertigwerdet, streifen durch den nördlichen Teil des Brachlands. Erlegt welche zum Wohle des Gleichgewichts, <Name>, und bringt mir die Hörner.", progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Die Gazellen werden von allein ganz bestimmt nicht wieder gesund, daher sollten wir nicht zaudern im Bemühen, sie zu retten!", completion = "Das ist gut, &lt;Name&gt;, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6129] = {title = "Heilung der Kranken", objective = "Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße beim Wegekreuz gesehen.", description = "Ich konnte genügend Salbe für zehn heilende Dosen machen, <Name>. Ich arbeite weiter mit den hiesigen Behörden zusammen und versuche, mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um das Nördliche Brachland wimmelt es von kranken Gazellen. Heilt sie mit der Salbe von ihrem Übel.\n\nDendrite Sternenschauer bei der Mondlichtung wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius unseren Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", progress = nil, completion = "Ihr habt bei der Heilung der kranken Gazellen des Brachlands wahre Wunder gewirkt. Sie waren das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. Ihr &lt;Volk&gt; brennt darauf, die Wege des Cenarius zu verstehen. Ihr habt, wie Eure Ältesten in Thunder Bluff, den Beweis angetreten, dass die Notwendigkeit des Gleichgewichts künstliche Barrieren zwischen den Völkern überwindet.\n\n&lt;Name&gt;, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.", rewards = "Ihr bekommt:\n\nSchleierstaubmedizinbeutel"}
MultiLanguageQuestData['de'][6130] = {title = "Macht über Gift", objective = "Kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück.", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Turak Runentotem in Donnerfels zurückkehren, <Name>. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", progress = nil, completion = "Willkommen - ich verfolge Eure Fortschritte in dieser Lektion seit Eurem Aufbruch und muss gestehen, ich war überrascht, als ich von der Situation in Crossroads erfuhr. Dies erfordert weitere Untersuchungen, da die Freisetzung solcher Gifte in die Umwelt das Gleichgewicht empfindlich stört.\n\nIhr habt Euch unter großem Druck wacker gehalten. Dafür finde ich keine bessere Möglichkeit, als Euch mit permanenter Macht über Gift zu belohnen. Verwendet sie weise, &lt;Name&gt;... verwendet sie weise.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6131] = {title = "Verbündeter der Holzschlundfeste", objective = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 5 Krieger der Totenwaldfelle, 5 Pfadfinder der Totenwaldfelle und 5 Gärtner der Totenwaldfelle besiegt.", description = "Die Einwohner der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Furbolgs der Holzschlundfeste auch kaum jemandem.\n\nSeid Ihr daran interessiert, Euch zu beweisen? Treibt den verderbten Stamm der Totenwaldfelle vom Teufelswald zurück, dann betrachten wir Euch eines Tages vielleicht als Verbündeten. Ihr findet den ersten Stamm der Totenwaldfelle - Krieger, Pfadfinder und Gärtner - westlich von hier.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6132] = {title = "Holt mich hier raus!", objective = "Eskortiert Melizza Brummsumms und sprecht anschließend mit Hornizz Brummsumms beim Kodofriedhdof Desolace.", description = "Holt mich hier raus!\n\nIch kam ins Tal der Speere, um mit den Maraudines zu sprechen. Ich dachte, ich könnte Geschäfte mit ihnen machen... aber sie reden einfach nicht mit mir! Ich glaube, sie möchten mich eher verspeisen!\n\nHolt mich hier raus, mein Bruder Hornizz wird es Euch reich vergelten! Er ist in unserem Lager neben dem Kodofriedhdof im Osten.\n\nBeeilen wir uns, <Name>. Es ist keine zwei Minuten her, da hörte ich einige Zentauren sagen, dass sie Holz für ihren Kochtopf sammeln möchten...", progress = nil, completion = "Meine Schwester Melizza sagte, dass Ihr kommen würdet. Danke, dass Ihr sie aus dieser misslichen Lage befreit habt. Vermutlich steckt sie leider schon wieder in einer neuen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6133] = {title = "Das Ersuchen des Waldläuferlords", objective = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.", description = "Die Hochelfen der Jagdhütte von Quel'Lithien haben etwas, das mir gehört, <Klasse>: Ein Dokument, das mein Leben als Sterblicher schildert.\n\nBevor Ihr fragt, Ihr seid wahrscheinlich nicht befugt, derlei Informationen zu bekommen. Macht einfach, was ich Euch sage, Wurm: Holt den Lebenslauf zurück.\n\nUnd, Schwachkopf, richtet so viel Not und Elend an, wie Ihr könnt. Lasst sie leiden...", progress = "Lasst mich nicht warten, <Klasse>.", completion = "Ich gehe davon aus, dass Ihr den Lebenslauf nicht gelesen habt. Nicht einmal Ihr würdet etwas so Idiotisches machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6134] = {title = "Geisterplasmasuche", objective = "Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brummsumms in Desolace.", description = "Im Südosten liegt ein Tal, das Tal der Knochen, das von den Geistern der Magram heimgesucht wird. Klingt gruselig, nicht wahr? Stellt Euch mal vor, wie sich die Magram erst gruseln müssen! Wenn wir Geisterenergie an jenem Ort einfangen könnten, wäre das den Zentauren sicher einiges wert.\n\nHier, nehmt diese Kiste mit Geistermagneten. Wenn Ihr einen zwischen den beiden großen Skeletten im Tal aufstellt, den toten Goliaths, dann werden sich Geister materialisieren und dorthin gehen. Nehmt Abstand, schaltet die Geister aus und holt Euch ihr Geisterplasma - das verkaufen wir den Magram.", progress = "Wo ist mein Geisterplasma, <Name>?", completion = "Da ist es! Sieht aus, als hättet Ihr auch etwas davon abbekommen. Irgendwie schleimig, hm?\n\nJedenfalls vielen Dank für Eure Mühe, &lt;Name&gt;. Dieses Zeug ist ein Vermögen wert... wenn ich die Zentauren überzeugen kann, dass es echt ist!", rewards = "KondorarmschienenRundschild des AnkergriffsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6135] = {title = "Dämmerschwinge, oh, wie ich Euch hasse...", objective = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Pestrufer.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.", description = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid.\n\nIhr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid. Ja... ja, Schwachkopf, vielleicht seid Ihr wirklich für anspruchsvollere Missionen bereit.\n\nDämmerschwinge, der Albinofledermausdämon, streift nördlich von hier durch das Land. Spürt ihn auf und besiegt ihn. Kehrt mit einem Büschel seines weißen Fells zu mir zurück und Ihr sollt eine Belohnung erhalten.", progress = "Ich würde Euch nicht raten, dass Ihr Euch dieser Herausforderung allein stellt, <Klasse>.", completion = "Gut gemacht, Schwachkopf. Ich fertige aus diesem Fell etwas an, das Ihr brauchen könnt.", rewards = "DämmerschwingenhandschuheDämmerschwingenmantelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6136] = {title = "Der Korpulente", objective = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Pestrufer zurück, sobald Ihr diese Mission erledigt habt.", description = "Hinter der Kapelle des Hoffnungsvollen Lichts, dem Lager der Argentumdämmerung, und westlich vom Nordtal, findet Ihr die wohlbeleibte Madenbestie Blutschlinger.\n\nIch habe ganze Regimenter an dieses Monster verloren. Sein Leibesumfang ist gewaltig! Und je mehr er frisst, um so größer wird er...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr der Sieger wärt. Man weiß, dass Blutschlinger schon andere verschlungen hat, die töricht genug waren, ihn anzugreifen.", progress = nil, completion = "Macht weiter so und ich muss Euch vom Schwachkopf zum Hirnamputierten erster Klasse befördern.", rewards = "GiftspeierSchädelsteinhammerSarahs WegweiserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6141] = {title = "Bruder Anton", objective = "Sprecht mit Bruder Anton in Desolace.", description = "Bruder Anton, mein Waffenbruder, hörte Gerüchte über einen Angriff der Untoten im fernen Kalimdor, in einem Land, das Desolace genannt wird. Anton buchte sofort eine Überfahrt dorthin, um die Bedrohung durch die Untoten zu lokalisieren und zu beseitigen!\n\nEr sucht Leute mit viel Tapferkeit und Entschlossenheit, die ihm dabei helfen. Wenn Ihr aufrichtigen Herzens seid, dann sprecht mit Anton. Er befindet sich in Desolace in einer Stadt der Allianz namens Nijelspitze.", progress = nil, completion = "Ich habe Kunde erhalten, dass Unterstützung von Osten kommt. Stammen diese Gerüchte vielleicht von Euch? Seid Ihr hierher gekommen, um dem Scharlachroten Bruder bei seinem Kreuzzug zu helfen?\n\nWenn ja, dann hört gut zu...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6142] = {title = "Muschelköder", objective = "Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Schattenflucht.", description = "Ihr seht wahrlich aus wie ein Angler, <Klasse>! Ich angle zu gern - schon mein Leben lang. Als Köder eignet sich das Fleisch der weichschaligen Muschel am besten. Die Fische können ihm einfach nicht widerstehen. Wisst Ihr, was ich meine?\n\nOben im Norden findet Ihr ein Schiffswrack vor der Küste. In der Gegend wimmelt es von weichschaligen Muscheln. Wenn Ihr mir 10 Teile Fleisch der weichschaligen Muschel bringt, werde ich Euch etwas dafür geben.", progress = "Ich kann es kaum erwarten, mit etwas frischem Fleisch der weichschaligen Muschel angeln zu gehen. Habt Ihr mir die 10 Teile gebracht, die ich brauche?", completion = "Perfekt, Mann, genau das hat mir der Hexendoktor gegen meine Kopfschmerzen verschrieben. Er sagt: 'Mai'Lahii - geh angeln. Dann geht es dir besser.'\n\nAlso, mir geht es jetzt schon besser, danke, Mann!", rewards = "PardochandschutzSchleichtatzengurtStahlstrebengürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6143] = {title = "Andere Fische zu grillen", objective = "Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Schattenflucht.", description = "Vielleicht habt Ihr es ja gehört, vielleicht auch nicht... meine Besatzung und ich waren vor der Insel Ranazjar fischen, nördlich des Schiffswracks vor der Küste im Norden. Wir haben immer dort gefischt, jetzt suche ich nur eine Möglichkeit, wie ich meine gefallenen Kameraden rächen kann.\n\nDie Naga haben uns eines Morgens angegriffen und alle außer mir getötet.\n\nDie Schuld lastet mir schwer auf der Seele, <Klasse>; ihr müsst losziehen und diese Naga für mich grillen. Ich werde Euch für die Mühe belohnen. Meint Ihr, Ihr könnt mir behilflich sein?", progress = nil, completion = "So süß die Neuigkeit ist, dass die Naga ausgelöscht wurden, mein Herz ist immer noch schwer. Ich werde den Rest meines Lebens danach trachten, sie alle auszurotten.\n\nHier, wie versprochen Eure Belohnung. Eine Kleinigkeit im Vergleich zu der Genugtuung, dass die Naga für ihre abscheuliche Untat an meiner Mannschaft büßen mussten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6144] = {title = "Der Befehl", objective = "Reist nach Unterstadt und sprecht mit Bragor Blutfaust.", description = "Der Befehl ist gekommen, <Klasse>. Bragor Blutfaust selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission nach Unterstadt schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort nach Unterstadt und erstattet Bragor Blutfaust Bericht. Macht mir keine Schande, <Klasse>!", progress = nil, completion = "Der oberste Kreuzzügler sitzt wohlbehalten in der Scharlachroten Bastion, während seine Streitkräfte in unser Land einfallen, unsere Gebäude und Denkmäler entweihen und unser Volk ermorden.\n\nDie Dunkle Fürstin hat befohlen, dass ich mich ein für alle Mal um dieses Insekt kümmere. Ihr sollt zum Instrument der Abrechnung mit den Verlassenen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6145] = {title = "Der Purpurrote Kurier", objective = "Kehrt in die Östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des Obersten Kreuzfahrers.\n\nBringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen.", description = "So wie niemand ohne den Kopf überleben kann, kann der Kopf nicht ohne den Körper überleben. Die Verteidigungsanlagen des Scharlachroten Kreuzzugs in Stratholme sind fast unüberwindbar. Stattdessen müssen wir den Körper unter dem Kopf abschneiden.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale nach Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, <Volk>! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", progress = "Wenn Euch das gelingt, habt Ihr Euch fast meinen Respekt verdient, <Klasse>.", completion = "&lt;Nathanos lacht.&gt;\n\nExzellent! Endlich! Eine Gelegenheit, das Scharlachrote Orakel zu vernichten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6146] = {title = "Nathanos' List", objective = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des Obersten Kreuzfahrers.", description = "Ich habe diesen Befehl etwas modifiziert. Sollte unsere kleine List wirken, wird das Scharlachrote Orakel schutzlos sein und wir schlagen zu!\n\nPasst jetzt genau auf, <Klasse>. Ihr werdet diesen Befehl dem Kreuzzüglerlord Valdelmar überbringen.\n\nWie? Ihr drückt ihm das Ding in die Hand, Schwachkopf.\n\nBringt den Befehl und diesen faulen Apfel nach Tyrs Hand. Wenn Ihr in der Stadt seid, dann esst den Apfel. Ihr werdet Euch in etwas verwandeln, das für Menschen...verträglicher ist. Nehmt den Befehl und übergebt ihn dem Kreuzzüglerlord Valdelmar.", progress = "Das ist nicht akzeptabel, Soldat!", completion = "Wo seid Ihr gewesen? Wir dachten schon, die Geißel hätte Euch erwischt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6147] = {title = "Kehrt zu Nathanos zurück.", objective = "Kehrt mit der neuen Information zu Nathanos Pestrufer zurück.", description = "Der oberste Kreuzzügler bringt eine ungewöhnliche Bitte vor. Hrm, wie dem auch sei... was er verlangt, soll geschehen. Kehrt zur Scharlachroten Bastion zurück und lasst ihn wissen, dass das Orakel sich bald auf den Weg machen wird.\n\nWir werden alle Vorsichtsmaßnahmen treffen, damit sie es unbeschadet nach Stratholme schafft.", progress = nil, completion = "Diese Narren! Meine Täuschung ist nicht aufgefallen! Macht Euch bereit, &lt;Klasse&gt;. Wir müssen mit kalter List zuschlagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6148] = {title = "Das scharlachrote Orakel Demetria", objective = "Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr erfolgreich wart.", description = "Demetria ist die oberste Beraterin des Obersten Kreuzfahrers. Ihrer 'überirdischen' Sinne wegen nennt man sie das Orakel. Sie hat den Kreuzzug erfolgreich zu mehreren Siegen gegen die Geißel geführt.\n\nWir konnten sie zwar mit dieser List herauslocken, aber wenn sie wirklich eine übersinnliche Begabung besitzt, wird sie zweifellos mit Ärger rechnen. Ihr werdet für diesen 'Ärger' sorgen.\n\nSpürt das Orakel auf und beendet ihre Existenz. Sie müssten in diesem Moment von Tyrs Hand aufbrechen. Macht mich stolz, Wurm.", progress = nil, completion = "Von diesem Schlag werden sie sich jahrelang nicht erholen! Gut gemacht, &lt;Name&gt;! Ihr habt Euch nicht nur meinen Respekt verdient, sondern auch diese Belohnung.", rewards = "BlutholzbogenSturmwüterHochheiliger BeschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6161] = {title = "Nehmt Rackmores Schatz!", objective = "Sucht Rackmores Silberschlüssel. Sucht Rackmores goldenen Schlüssel. Sucht und öffnet Rackmores Truhe.", description = "Aus Rackmores Logbuch geht hervor, dass sein Schiff zur Mondfederfeste segelte, als es von seefahrenden Kreaturen angegriffen wurde. Er versteckte seine Truhe auf der Insel Ranazjar, damit sein Schatz dem Feind nicht in die Hände fallen sollte.\n\nZwei Schlüssel, ein silberner und ein goldener, sind erforderlich, um die Truhe zu öffnen. Diese Schlüssel gingen verloren, doch wenn Schlüssel und Truhe gefunden werden, winkt ein Schatz!", progress = "Diese Truhe ist sicher verschlossen.", completion = "Die Truhe geht auf und gibt Rackmores Schatz preis!", rewards = "Ihr bekommt:\n\nKäpt'n Rackmores SteuerruderKäpt'n Rackmores Pinne"}
MultiLanguageQuestData['de'][6162] = {title = "Eines Ehemanns letzter Kampf", objective = "Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.", description = "Mein Gatte reiste unserem Klan zu Ehren durch den Teufelswald und kämpfte gegen den Schattenrat und andere verderbte Monstrositäten!\n\nAls er dem Tod viele Male entronnen war, erhielt ich einen Brief von ihm, in dem stand, dass ein Druide ihn um Beistand gegen einen großen beschmutzten Furbolg namens Oberanführer Ror gebeten hatte - man hörte nie wieder etwas von ihnen.\n\nIch möchte die Klauenhand dieses Ror, <Name>. Er soll dafür büßen, dass er mich zur Witwe gemacht hat! Ich glaube, die Kreatur ist im Süden... nahe der Grenze des Eschentals.", progress = "Habt Ihr den Kopf der Bestie schon, <Name>? Sie wird für ihre Verbrechen büßen. Mir ist egal, ob sie verderbt oder nur wütend ist, weil sie in diesem garstigen Wald hausen muss. Kein Furbolg, der solche Verbrechen an meiner Familie begeht, darf überleben!", completion = "Ihr macht mir Ehre, indem Ihr zu Eurem Wort steht. Mein Mann fiel im Kampf - er wäre stolz darauf gewesen. Aber ich könnte keine Ruhe finden, wenn ich nicht wüsste, dass die Kreatur, die mich zu meinem Witwendasein verdammte, nicht für ihre Tat bezahlt hätte.\n\nNochmals danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6163] = {title = "Ramstein", objective = "Reist nach Stratholme und tötet Ramstein den Verschlinger. Bringt seinen Kopf als Souvenir zu Nathanos.", description = "Ich war überwältigt. Ich stand in dieser Siedlung... und blieb standhaft bei der Verteidigung von Lordaeron. Der Hof und alles darauf wurde von einer gigantischen Welle der Geißel belagert.\n\nDer Dreck. Der Schmutz. Er stand über mir und die Eingeweide hingen ihm aus einem klaffenden Loch in der Brust.\n\nIch erwachte als Geißel. Lange Zeit war ich hilflos. Meine Gedanken waren mit denen des Lichkönigs verschmolzen.\n\nSie kam zu mir... irgendwo, irgendwie wusste ich es. Frei.\n\nDoch jetzt muss ich meine Rache haben - Rache an dem, der mir das Leben genommen hat. Vernichtet ihn.", progress = "Als Sylvanas mich befreit hatte, jagte ich die Bestie monatelang durch diese Wüste. Er floh ins sichere Stratholme. Der Bastard...", completion = "Ich frage mich... hat es um Gnade gewinselt? Wusste es überhaupt, was Gnade ist?\n\n&lt;Nathanos spuckt aus.&gt;\n\nIch werde den Kopf dieser Bestie an meine Wand hängen.\n\nIhr habt Euch einen Platz unter meinen Helden verdient, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKönigliches Siegel von AlexisElementarkreis\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6164] = {title = "Augustus' Quittungsbuch", objective = "Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal.", description = "Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, &lt;Name&gt;! Toll! Wahnsinnig gut, sage ich Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6181] = {title = "Eine eilige Nachricht", objective = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Thor, unseren Greifenmeister. Er ist unten am Hügel; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Stormwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6182] = {title = "Der Erste und Letzte", objective = "Sprecht mit Meister Mathias Shaw in der Altstadt von Sturmwind. Er wohnt in der Kaserne.", description = "Nathanos Marris war der erste und letzte Waldläuferlord der Menschen. Ein Schüler von Sylvanas Windläufer, die heute Bansheekönigin der Verlassenen ist.\n\nWir dachten, Nathanos sei fünf Jahre zuvor bei der Verteidigung von Lordaeron in der Schlacht gefallen. Sein Leichnam wurde zwar nie gefunden, aber man ging davon aus, dass er es nicht aus den Östlichen Pestländern hinaus geschafft hatte.\n\nMathias Shaw hat sein Verschwinden untersucht und könnte neue Informationen haben. Meldet Euch sofort bei ihm. Er lebt in der Altstadt, in der Kaserne.", progress = nil, completion = "Nach einigen Berichten über ungewöhnliche Aktivität der Verlassenen in den östlichen Pestländern wurden Agenten von SI:7 zu Ermittlungen hingeschickt. Die Resultate dieser Ermittlungen sind beunruhigend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6183] = {title = "Ehret die Toten", objective = "Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt.", description = "Fünf meiner besten Agenten wurden dem Fall Marris zugeteilt. Einer kam zurück und starb drei Tage später im Schlaf.\n\nDie wenigen Informationen, die wir aus ihm herausbekamen, waren unverständliches Gestammel. Wir haben zwei Worte verstanden: 'Nathanos' und 'Pestrufer'.\n\nIch habe nicht genügend Leute, um die Ermittlungen fortzusetzen, und Rabenholdt ist uns nicht behilflich. Wir müssen der Sache auf den Grund gehen, und wenn es nur ist, damit wir den Familien der Verstorbenen Trost spenden können. Werdet Ihr helfen?", progress = nil, completion = "&lt;Mathias nickt.&gt;\n\nIch war gewiss, dass Bolvar mir ehrenhafte Männer und Frauen schicken würde - die treuesten Soldaten der Allianz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6184] = {title = "Flint Schattenmoor", objective = "Reist zum Zugwindlager in den westlichen Pestländern und trefft Euren Kontaktmann Flint Schattenmoor.", description = "Die einzige Information, die wir bislang haben, ist die, dass Nathanos Marris von diesem Pestrufer ermordet worden sein könnte. Wir gehen davon aus, dass Pestrufer derselbe Teufel ist, der meine Agenten beseitigt hat.\n\nFlint Schattenmoor, ein weiterer Agent des SI:7, ist im Lager der Allianz an der Zugwindspitze in den Westlichen Pestländern stationiert. Sucht ihn auf. Er wird Euch in die aktuelle Situation in den Pestländern einweihen und Euch einen Auftrag erteilen.\n\nViel Glück, <Name>.", progress = nil, completion = "Eure erste Mission ist kurz und knapp, &lt;Name&gt;. Ihr geht rein, ihr geht raus. Aufklären...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6185] = {title = "Die Östlichen Pestländer", objective = "Sucht in den östlichen Pestländern nach Hinweisen auf den 'Pestrufer' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Schattenmoor am Zugwindlager.", description = "Wie gesagt, Eure erste Mission ist eine Aufklärungsmission. Nichts Kompliziertes, <Name>. Ihr müsst in die Östlichen Pestländer reisen und nach Hinweisen auf diesen Pestrufer suchen.\n\nHaltet nach Informationen über unsere vermissten Agenten Ausschau. Wir müssen davon ausgehen, dass sie tot sind, und wenn sie tot sind, muss es Leichen geben...irgendwo.\n\n<Flint schluckt schwer.>\n\nAlle SI:7-Agenten tragen diese Insignien.\n\n<Flint zeigt Euch seine SI:7-Insignien.>\n\nBringt alle zu mir zurück, die Ihr finden könnt.", progress = "G... Glück gehabt???", completion = "Rutger. Fredo. Turyen. Alle... tot...\n\n&lt;Flint umklammert die Insignien.&gt;\n\nWo waren sie? Habt Ihr weitere Informationen über diesen Dreckskerl, diesen Blightcaller, gefunden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6186] = {title = "Der Pestrufer kommt", objective = "Kehrt nach Sturmwind zurück und informiert König Varian Wrynn über das Schicksal von Nathanos Marris.", description = "<Flints Gesicht wird schlagartig leichenblass.>\n\nNa... Nathanos ist das gewesen? Nathanos ist der Pestrufer?\n\nWarum? Er war... war so edel – ein Waldläuferlord, den alle geachtet haben. Der einzige Mensch, der je bei den Hochelfen ausgebildet wurde. Der soll jetzt ein ruchloser Agent der Verlassenen sein?\n\nIch... Ich bin untröstlich, dass ich das von Euch verlangen muss, <Name>, aber König Wrynn muss unverzüglich über diese Wendung der Ereignisse informiert werden. Bitte kehrt nach Sturmwind zurück und überbringt diese Nachricht.", progress = nil, completion = "Nein. Es... NEIN! Wie? Ein Agent der Verlassenen? Der HELD der Bansheekönigin???\n\n&lt;Hochlord Bolvar Fordragon sackt geknickt in sich zusammen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6187] = {title = "Ordnung muss wiederhergestellt werden", objective = "Stellt eine Armee auf und reist zu den Östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Pestrufer und jeden Abschaum der Horde, der ihn beschützen mag.\n\nBewahrt einen klaren Kopf, <Name>. Die Horde wird den Waldläuferlord mit dem Leben verteidigen.", description = "Wisst Ihr, wie viele Waldläuferlords es auf dieser Welt gibt? Wie viele menschliche Waldläuferlords jemals existiert haben?\n\nNathanos' Errungenschaften waren beispiellos. Er war ein taktisches Genie und führte die Allianz in einem Jahrzehnt der Konflikte zu vielen Siegen.\n\nUnd jetzt... der Held der Verlassenen.\n\nNein. Das darf nicht sein. Die Ordnung muss wiederhergestellt werden.\n\nVersammelt eine Armee, <Name>. Kehrt mit Eurer Armee in die Pestländer zurück und vernichtet den Pestrufer.\n\nIch wünsche Euch Glück, <Name>. Das werdet Ihr für diesen Kampf wahrlich brauchen.", progress = nil, completion = "Das ist eine Tragödie. Ich glaube... Ich glaube, unsere Art ist verflucht, &lt;Name&gt;. Wir sind verflucht, unsere größten Krieger zu verlieren, unsere edelsten Helden, unsere begabtesten Gelehrten.\n\nWir stehen in Eurer Schuld und ich versichere Euch, &lt;Name&gt;, dass Nathanos Marris auf Euch herablächeln wird, wo immer er jetzt sein mag.", rewards = "BlutholzbogenSturmwüterHochheiliger BeschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6221] = {title = "Totenwaldfelle des Nordens", objective = "Nafien möchte, dass Ihr 5 Höhlenbehüter der Totenwaldfelle, 5 Rächer der Totenwaldfelle und 5 Schamanen der Totenwaldfelle besiegt.", description = "Direkt südwestlich von hier liegt ein Furbolglager der Totenwaldfelle. Ich bin nicht sicher, was sie vorhaben, aber ich würde dem gern einen Riegel vorschieben, ehe es zum Problem wird.\n\nDer Stamm der Totenwaldfelle ist böse, aber die Verderbnis ist es, die ihre Hirne verseucht. Ihre Feindseligkeit ist keine angeborene Eigenschaft, doch da kann man nichts machen. Aus diesem Grund stimmt es mich zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss.\n\nBitte, <Name>, tut, was getan werden muss, aber erspart mir die Einzelheiten. Sie beunruhigen mich zu sehr.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6241] = {title = "Aktivität der Winterfelle", objective = "Salfa möchte, dass Ihr 6 Totemiker der Winterfelle, 6 Höhlenbehüter der Winterfelle und 6 Pfadfinder der Winterfelle erledigt.", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, <Name>. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber wenn möglich andere Furbolgstämme.\n\nIn letzter Zeit ist mir aufgefallen, dass der Winterfellstamm uns gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.\n\nWenn Ihr ihre Anzahl reduzieren könntet, würde uns das sehr helfen, <Name>.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6261] = {title = "Dungar Trinkfest", objective = "Bringt Osrics Kiste zu Dungar Trinkfest dem Greifenmeister.", description = "<Name>, ich habe alles, worum Lewis gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Thor in Westfall gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Lewis. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Westfall ohne neue Ausrüstung sind!", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Westfall, eh? Seid Ihr schon mal in Westfall gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6281] = {title = "Weiter nach Sturmwind", objective = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Lewis' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Quartiermeister Lewis? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Die Späherkuppe ist weit entfernt in einem Land, das Stormwind fast vergessen hat.\n\nIch danke Euch, &lt;Name&gt;. Hier habt Ihr etwas Geld für Eure Reisespesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6282] = {title = "Harpyien drohen", objective = "Maggran Erdbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", description = "Tauren sind die stolzen Beschützer dieser Länder. Zweifellos könnt Ihr erraten, warum mich die Anzahl der Harpyien hier im Steinkrallengebirge so beunruhigt.\n\nDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in Kalimdor. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen.\n\nIhr müsst die Harpyien für mich dezimieren, <Name>!", progress = nil, completion = "Das sind wirklich ganz ausgezeichnete Nachrichten! Erzählt mir noch einmal, wie Ihr in den kalten Herzen dieser schändlichen Harpyien Furcht gesät habt. Die Blutfurien haben einen schweren Schlag erlitten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6283] = {title = "Blutfuriengeschlecht", objective = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", description = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!\n\nFür diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.\n\nGeht zurück zum Verbrannten Tal, dort findet Ihr sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein, aber die Belohnung ist groß.", progress = "Die Zerfetzerin der Blutfurien ist ein garstiges Geschöpf! Ihr findet sie bestimmt entlang der westlichen Hügelkette im verbrannten Tal.\n\nDie Blutfurien werden ohne sie hilflos sein... gewiss können wir sie für alle Zeiten loswerden!", completion = "Ich spüre bereits, wie die Wut von mir weicht. Was soll ich mit meiner Zeit anfangen? Das Wissen, dass das Böse um mein Land schleicht, hielt meine Gedanken wach, doch nun sind sie verstummt. Vielleicht ist das ja gut so... vielleicht kann ich mich jetzt auf das Gute konzentrieren, was alle Tauren tun sollten.\n\nBitte nehmt das als Belohnung für Eure Mühe an.", rewards = "KreischergürtelGrimmlingumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6284] = {title = "Arachnophobie", objective = "Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.", description = "Warnung: Betretet den Sishircanyon westlich von hier auf eigene Gefahr.\n\nBesseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem eingesponnenen Unterschlupf erkoren.\n\nMaggran Erdbinder in Sonnenfels hat ein Kopfgeld auf Besseleth ausgesetzt. Tötet sie und bringt einen Beweis Eurer Tat zu Maggran. Dort werdet Ihr eine Belohnung erhalten, wenn Ihr der achtbeinigen Gefahr ein Ende gemacht habt.", progress = "Besseleth ist ein ruchloses Raubtier... Ich fürchte um alle, die nachts auf dem Weberpass reisen. Dann nämlich lauern sie und ihre Kinder arglosen Reisenden auf. Ich selbst wurde schon Opfer ihres tödlichen Fangzahns, der eine Elle lang ist, aber zum Glück konnte ich sie abwehren und mich in Sicherheit bringen. Ich würde alles dafür geben, wenn dieses Monster vernichtet würde.", completion = "Gute Jagd, &lt;Name&gt;! Besseleth ist ein altes Raubtier in dieser Gegend... Ich werde sie nicht vermissen. Nehmt diese Belohnung als Zeichen dafür, dass Ihr der Held des Waldes seid.\n\n\n\nVielleicht werden jetzt viele nach Sonnenfels kommen und sich nicht mehr vor dem fürchten müssen, was in der Dunkelheit lauert.", rewards = "TonsteinkurzschwertKlare KristallruteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6285] = {title = "Zurück zu Lewis", objective = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.", description = "Der Greifenmeister in Westfall heißt Thor. Falls Ihr schon mit ihm gesprochen habt, dann könnt Ihr einen meiner Greifen zu ihm bringen.\n\nDas hier sollte man unbedingt wissen: Greifen sind stets so ausgebildet, dass sie in ihre Hauptstadt fliegen, aber sie bringen Euch nur zu einem außerörtlichen Greifenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nIhr seid bereits bei Thor gewesen, sprecht daher einfach wieder mit mir, wenn Ihr bereit seid, einen Greifen nach Westfall zu nehmen. Dort könnt Ihr Osrics Kiste bei Rüstmeister Lewis abliefern.", progress = "Ihr seid aus Stormwind zurück? Hat Osric die Rüstungen geschickt?", completion = "Großartig, Ihr habt die Rüstungen! Wir verteilen sie unverzüglich an alle, die sie brauchen.\n\nDanke, &lt;Name&gt;. Ihr wart uns mit Euren Bemühungen eine große Hilfe. Jetzt, da Euch Greife nicht mehr fremd sind, kommt Ihr hoffentlich öfter und helft den Bewohnern der Späherkuppe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6301] = {title = "Zyklus der Wiedergeburt", objective = "Tammra Windfeld in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", description = "Industrielle Gier und ständige Kriege haben die Länder des Steinkrallengebirges verwüstet. Nur der Segen der Erdenmutter kann solch eine Verletzung heilen.\n\n<Name>, Ihr müsst für mich ein spezielles Samenkorn suchen, Gaeasamenkorn. Man findet diese Samenkörner nur hier im Steinkrallengebirge, nördlich von Sonnenfels am Mirkfallonsee, in der Nähe des Ufers.\n\nWenn Ihr mir die Samenkörner bringt, werde ich sie auf magische Weise mit schamanistischer Macht erfüllen, um ihr Wachstum zu beschleunigen.", progress = "Die ständige Zerstörung durch den Krieg und alle, die mit Holz Profit machen möchten, bekümmert mich zutiefst. Um den Zyklus der Wiedergeburt zu unterstützen und die Länder wieder zu bewalden, benötige ich Gaeasamenkörner. Habt Ihr sie, <Klasse>?", completion = "Ah, &lt;Name&gt;, Ihr habt die Gaeasamenkörner. Schaut zu und seht, wie der Segen der Erdenmutter sogar diese kleinen Samenkörner des Lebens blühen und gedeihen lassen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6321] = {title = "Nachschub für Brill", objective = "Bringt Morris' Anforderungsliste zu Fledermausführerin Anette.", description = "Exekutor Zygand bat mich, eine Inventur unserer Ausrüstung hier in Brill durchzuführen. Da die Geißel und Schlimmeres in den Wäldern lauert, möchte er nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen.\n\nIch habe festgestellt, dass wir im Großen und Ganzen gut bestückt sind, aber wir brauchen mehr Waffen als Ersatz für die, die wir auf dem Feld verloren haben.\n\nHier eine Anforderungsliste der benötigten Dinge für den Waffenhändler Gordon Wendheim in Unterstadt. Bringt die Anforderungsliste zur Fledermausführerin Anette und sprecht mit ihr über den Transport nach Unterstadt.", progress = "Ihr scheint in einer offiziellen Angelegenheit hier zu sein...", completion = "Ah, eine Anforderungsliste für Vorräte. Die solltet Ihr wohl in die Undercity bringen. Und zwar rasch, denn das Grabmal darf nicht unterversorgt sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6322] = {title = "Michael Garrett", objective = "Bringt Gordons Kiste zu Michael Garrett.", description = "Ich habe den Nachschub für Brill in diese Kiste getan. Wenn Ihr Brill schon besucht und mit der Fledermausmeisterin gesprochen habt, könnt Ihr auf einer Fledermaus zu ihr reiten.\n\nSprecht mit Michael Garrett, dem Fledermausmeister von Unterstadt. Er kann Euch eine Fledermaus nach Brill zur Verfügung stellen.", progress = "Wenn Ihr weite Strecken reisen müsst, dann ist eine Fledermaus das ideale Transportmittel.", completion = "Diese Kiste muss zum Grabmal im Silberwald? Nichts leichter als das, unsere Fledermäuse fliegen täglich dorthin.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6323] = {title = "Flug nach Unterstadt", objective = "Bucht einen Fledermausritt zur Unterstadt bei Fledermausführerin Anette und bringt dann Morris' Anforderungsliste zu Gordon Wendheim in Unterstadt.", description = "Eine meiner Fledermäuse kann Euch nach Unterstadt bringen. Normalerweise kosten diese Flüge eine geringe Gebühr, aber der Flug nach Unterstadt ist für <einen tapferen Streiter/eine hübsche Dame> wie Euch kostenlos, <Volk>. Sprecht mich wieder an, wenn Ihr bereit seid, damit wir Euren Transport arrangieren können.\n\nIhr findet Gordon Wendheim im Handwerksviertel von Unterstadt. In diesem Viertel landet auch meine Fledermaus.", progress = "Ich halte meine Waffen in einem Top-Zustand. Sie sind gereinigt und einsatzbereit.", completion = "Eine Anforderungsliste vom Grabmal? Wohlan denn. Es ist eine Ehre, denen zu dienen, die unserer Dunklen Fürstin dienen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6324] = {title = "Rückkehr zu Morris", objective = "Bucht einen Fledermausritt nach Brill bei Fledermausmeister Michael Garrett und bringt dann Gordons Kiste zu Todeswache Morris in Brill.", description = "Der Fledermausmeister in Brill ist Fledermausführerin Anette. Wenn Ihr schon bei ihr gewesen seid, dann gebe ich Euch eine Fledermaus, damit Ihr zu ihr fliegen könnt.\n\nUnsere Fledermäuse fliegen stets nach Unterstadt, aber um zu entlegeneren Orten zu reisen, muss ihr Reiter zuerst die Gegend besuchen und mit dem dortigen Fledermausmeister sprechen.\n\nIhr habt Anette in Brill getroffen, daher könnt Ihr jetzt mit Fledermäusen dorthin fliegen. Sprecht wieder mit mir, wenn Ihr bereit seid.", progress = "<Name>, Ihr kehrt zurück. Habt Ihr unseren Nachschub aus Undercity?", completion = "Gute Arbeit, &lt;Name&gt;. Diese Waffen gewährleisten, dass unsere Todeswachen nicht unvorbereitet überrascht werden.\n\nIhr habt der Dunklen Fürstin einen wertvollen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6341] = {title = "Auf nach Darnassus", objective = "Sprecht mit Fidelio, um einen Flug nach Darnassus zu erstehen, und bringt dann die Rezeptsammlung von Dolanaar zu Schwester Aquinne in Darnassus.", description = "Alle in Dolanaar sind so stolz auf Schwester Aquinne. Ich bin sicher, sie wird sich sehr freuen, dieses aufmerksame Geschenk von Nyoma zu erhalten.\n\nWenn Ihr bereit seid, nach Darnassus zu reisen, sprecht einfach wieder mit mir und für ein paar Münzen könnt Ihr einen Hippogryphen mieten, der Euch dorthin bringt. Man sagte mir, Schwester Aquinne genießt die Abgeschiedenheit eines kleinen Platzes südlich vom Hippogryphenmeister in Darnassus. Sucht dort nach ihr, wenn Ihr angekommen seid.", progress = "Wie kann ich Euch helfen? Benötigt Ihr ein Transportmittel?", completion = "Ah, Ihr möchtet, dass dies nach Auberdine gebracht wird? Nun gut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6342] = {title = "Ein unerwartetes Geschenk", objective = "Bringt Schwester Aquinnes Notiz zu Leora, der Hippogryphenmeisterin in Darnassus.", description = "Das ist wundervoll! Genau das Richtige, um mich während meiner Studien im Tempel des Mondes an mein Zuhause zu erinnern. Ich werde eins der Rezepte heute Abend ausprobieren. Ich kann es kaum abwarten!\n\nWürdet Ihr diese kurze Dankesnachricht zu Nyoma zurückbringen? Ihr könnt einen Hippogryphen zurück nach Dolanaar mieten. Besucht einfach unsere Hippogryphenmeisterin, Leora, wenn Ihr zum Abflug bereit seid. Sie wird Euch mit einem Rückflug nach Dolanaar helfen.", progress = "Kommt Ihr aus Teldrassil? Erzählt mir, wie angelt es sich dort?", completion = "Ein Päckchen von Nessa? Danke, &lt;Name&gt;! Sie sagte mir, sie würde mir Exemplare der Fische schicken, die in der Nähe von Rut'theran gefangen werden. Sie glaubt, die könnten sich von den hiesigen Fischen unterscheiden...\n\nHerrje! Der Kieferknochen ist fast doppelt so groß wie beim gleichen Fisch hier. Und diese Schuppen sind so groß wie eine geballte Faust! Erstaunlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6343] = {title = "Rückkehr zu Nyoma", objective = "Sprecht mit Leora, um einen Hippogryphen zu mieten, der Euch nach Dolanaar zurückbringt. Sobald Ihr in Dolanaar angekommen seid, bringt Schwester Aquinnes Nachricht zu Nyoma.", description = "Euch einen Flug zurück nach Dolanaar zu besorgen, wird einfach sein. Da Ihr Fidelio in Dolanaar bereits kennt, könnt Ihr ohne Probleme dorthin zurückfliegen.\n\nImmer wenn Ihr in einer neuen Stadt ankommt, solltet Ihr daran denken, mit dem Flugmeister zu sprechen, damit Ihr zu und von diesem neuen Ort fliegen könnt.\n\nSprecht mit mir, wenn Ihr bereit seid, einen Hippogryphen für den Rückflug nach Dolanaar zu mieten.", progress = "<Name>, Ihr seid aus Auberdine zurück? Habt Ihr mit Laird gesprochen?", completion = "Das ist sehr interessant. Die Fische hier sind riesig, aber ich hätte nicht gedacht, dass der Unterschied der Arten zwischen hier und dem Festland so groß ist. Dafür muss es einen Grund geben...\n\nIch danke Euch, &lt;Name&gt;. Ich werde die Nachrichten, die Ihr gebracht habt, mit den Dorfbewohnern besprechen. Vielleicht finden wir eines Tages die Ursache dieser Kuriosität. Doch bis dahin wollen wir nutzen, was sie uns beschert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6344] = {title = "Andenken an Zuhause", objective = "Bringt die Rezeptsammlung von Dolanaar zu Fidelio in Dolanaar.", description = "Eine Freundin von mir, Schwester Aquinne, ist in der Ausbildung zur Mondpriesterin in Darnassus. Sie hat Dolanaar letztes Jahr verlassen, um im Tempel zu lernen. Laut ihren Briefen geht es ihr gut und sie lernt viel, aber sie vermisst ihr Zuhause und ihre alten Freunde. Ich habe ein Buch mit ihren Lieblingsrezepten aus Dolanaar zusammengestellt.\n\nWenn Ihr die Zeit findet, könntet Ihr es ihr nach Darnassus bringen? Ihr könnt einen Hippogryphen von Fidelio mieten. Er befindet sich in der Mitte der Stadt, gegenüber vom Gasthaus.", progress = "Wie kann ich Euch helfen?", completion = "Ja, ich brauche einen Kurier, der ein Päckchen nach Dunkelküste bringt. Werdet Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6361] = {title = "Ein Bündel Bälge", objective = "Bringt das Bündel Bälge zu Windreitermeister Tak im Dorf der Bluthufe.", description = "Ich habe ein Bündel Bälge von Tieren Mulgores und muss es nach Donnerfels bringen. Dort fertigt Ahanu, ein Kollege, Lederwaren aus diesen Häuten an.\n\nBringt Ihr ihm die Bälge für mich?\n\nDer schnellste Weg nach Donnerfels ist auf dem Rücken eines Windreiters. Bringt das Bündel Bälge zu Tak, unserem Windreitermeister am Wegekreuz, und sprecht mit ihm über den Transport nach Donnerfels.", progress = "Seid Ihr wegen eines Windreiters hier? Habt Ihr etwas zu transportieren?", completion = "Wenn Ihr diese Bälge nach Donnerfels bringen müsst, dann seid Ihr hier goldrichtig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6362] = {title = "Flug nach Donnerfels", objective = "Bucht einen Windreiter nach Donnerfels bei Windreitermeister Tak und bringt dann das Bündel Bälge zu Ahanu in Donnerfels.", description = "Für ein kleines Entgelt gebe ich Euch einen Windreiter nach Donnerfels. Es gibt kein schnelleres Transportmittel in die Stadt!\n\nSollte das akzeptabel sein, sprecht wieder mit mir, wenn Ihr abreisefertig seid.\n\nWenn Ihr diese Bälge zu Ahanu bringen wollt, ich schätze, er ist in Hewas Waffenkammer am Fundament des Windreiterturms in Donnerfels. Und genau dort werdet Ihr landen!", progress = "Ihr habt Staub auf den Schultern, der aus dem Brachland sein muss. Habt Ihr mit meinem Freund Jahan gesprochen?", completion = "Ah, ein neues Bündel Bälge. Ich werde mich sofort damit an die Arbeit machen!\n\nDanke, Bruder. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr ein paar Münzen für eure Zeit und Reisekosten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6363] = {title = "Tal der Windreitermeister", objective = "Bringt Ahanus Lederwaren zu Tal in Donnerfels.", description = "Ich habe Lederwaren für Varg zum Verkauf im Dorf der Bluthufe vorbereitet. Würdet Ihr sie ihm bringen?\n\nWenn Ihr schon im Dorf der Bluthufe gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem unserer Windreiter zu ihm zurück.\n\nBringt die Lederwaren zu Tal, unserem Windreitermeister in Donnerfels, und sprecht mit ihm über den Transport zum Dorf der Bluthufe.", progress = "Seid gegrüßt, <Klasse>. Was kann ich für Euch tun?", completion = "Ihr müsst das nach Crossroads bringen, hm? Das ist kein Problem. Wenn Ihr schon einmal dort gewesen seid und mit Devrak gesprochen habt, dann könnt Ihr einen meiner Windreiter zurück zu ihm nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6364] = {title = "Rückkehr zu Varg", objective = "Bucht einen Windreiter zum Dorf der Bluthufe bei Windreitermeister Tak und bringt dann Ahanus Lederwaren zu Varg Windraunen.", description = "Um zu einer Stadt zu fliegen, müsst Ihr schon einmal dort gewesen sein und mit dem Windreitermeister dieser Stadt gesprochen haben. Ihr seid beim Dorf der Bluthufe gewesen und habt mit dem Windreitermeister Tak gesprochen, daher könnt Ihr gegen ein geringes Entgelt von hier mit einem unserer Windreiter zu ihm fliegen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid. Im Dorf der Bluthufe könnt Ihr die Lederwaren zu Varg Windraunen bringen.", progress = "<Name>, Ihr seid aus Thunder Bluff zurück? Habt Ihr die Bälge zu Ahanu gebracht?", completion = "Ahanu schickt mir fertige Produkte? Sehr gut. In Crossroads wimmelt es gerade von Jägern und Abenteurern und die Geschäfte gehen blendend. Ich bin sicher, ich kann diese Waren im Handumdrehen an den Mann bringen.\n\nVielen Dank für all Eure Bemühungen, &lt;Name&gt;. Ich stehe in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6365] = {title = "Fleisch für Orgrimmar", objective = "Bringt Grimtaks Fleisch zu Burok in Klingenhügel.", description = "Ich habe hier ausgewählte Fleischstücke, die ich einer Freundin schicken möchte. Ihr Name ist Gryshka, sie ist die Gastwirtin in Orgrimmar. Würdet Ihr das Fleisch für mich abliefern?\n\nDas schnellste Transportmittel nach Orgrimmar ist ein Windreiter. Bringt das Fleisch zu Windreitermeister Burok in Klingenhügel und sprecht mit ihm über den Transport nach Orgrimmar.", progress = "Ihr wollt schnell irgendwohin? Tja, dann sprecht Ihr mit dem richtigen <Volk>!", completion = "Ihr müsst dieses Fleisch nach Orgrimmar bringen? Das ist kein Problem. Für ein bescheidenes Sümmchen kann mein Windreiter Euch hinbringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6381] = {title = "Neues Leben", objective = "Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und bringt Tammra in Sonnenfels dann die restlichen verzauberten Gaeasamenkörner zurück.", description = "Wie Ihr sehen könnt, <Klasse>, ist der Zyklus des Lebens eine mächtige Sache, auch wenn das Land Schmerzen leidet. Jetzt müssen wir unseren Teil leisten, um ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im Verbrannten Tal. Aber seid wachsam, denn Harpyien und Feuerelementare verseuchen das vernarbte Land noch immer.\n\nNehmt diese verzauberten Gaeasamenkörner und pflanzt sie in fruchtbare Erdhügel, <Name>. Der Zyklus des Lebens muss weitergehen!", progress = "Diese Samenkörner, die Ihr pflanzt, sind stark, widersetzen sich der Verderbnis und schaffen neuen Platz für anderes Leben. Sie werden wachsen und wachsen, zuerst die Verderbnis verhindern und das vernarbte Land heilen, und dann werden sie eines Tages das Steinkrallengebirge wieder zu einem üppigen Wald machen.\n\nHabt Ihr alle Gaeasamenkörner gepflanzt?", completion = "Das ist ein großer Sieg für das Land. Mit der Zeit werden auch andere Dinge geschehen: Die Venture Company wird die Kreissägen und Äxte zusammenpacken, die wütenden Feuergeister werden sich beruhigen und die Harpyien werden vom Land vertrieben.\n\nErst dann, &lt;Name&gt;, wird das Steinkrallengebirge wirklich Frieden finden.\n\nIhr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Nehmt einen dieser Gegenstände als Dank für das neue Leben, das Ihr heute hier geschaffen habt.", rewards = "Stiefel des WindsuchersSandspitzenhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6382] = {title = "Die Jagd im Eschental", objective = "Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental.", description = "Eure Kraft beeindruckt mich, <Klasse>. Die Entschlossenheit, mit der Ihr Euch der Jagd zuwendet, erfüllt mich mit der Gewissheit, dass Ihr Euch größerem Wild... und größeren Herausforderungen zuwenden könnt.\n\nDer Wald des Eschentals ist eine große, ungezähmte Wildnis, der die Horde ihren Willen aufzuzwingen trachtet, sowohl politisch wie auch spirituell. Wenn Ihr Euch in einem unerforschten Land beweisen wollt, dann sucht die Führung von Senani Donnerherz im Splitterholzposten. Der Außenposten liegt nördlich des Pfads, der aus dem Brachland führt.", progress = nil, completion = "Willkommen an der neuen Grenze, &lt;Name&gt;. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, &lt;Klasse&gt;, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6383] = {title = "Die Jagd im Eschental", objective = "Es gibt drei legendäre Kreaturen, die die Jagd in Ashenvale bilden. Ihr könnt sie suchen und Euch mit ihrer List und Kraft messen. Dabei werdet Ihr hoffentlich auch etwas über Euch selbst lernen. Die Kreaturen sind: der Bär Ursangus, die Nachtsäblerkatze Schattumbra und der Hippogryph Scharfkralle.\n\nDie Kreaturen der Jagd in Ashenvale sind mächtig; möglicherweise benötigt Ihr Unterstützung, um sie zu bezwingen. Wenn Ihr sie besiegt habt, dann bringt mir Beweise Eurer Tat.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6384] = {title = "Flug nach Orgrimmar", objective = "Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Burok und bringt dann Grimtaks Fleisch zu Gryshka in Orgrimmar.", description = "Für eine Handvoll Münzen lasse ich Euch mit einem Windreiter nach Orgrimmar bringen. Wenn Ihr dort eintrefft, bringt Grimtaks Fleisch zu Gryshka. Ihr Gasthaus liegt im Tal der Stärke.\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", progress = "Irgendwas riecht lecker! Ihr habt nicht zufällig rohes Fleisch bei Euch, oder?", completion = "Wie wundervoll! Das ist bestes Filet! Es ist von Zargh, richtig? Dieser &lt;Volk&gt; versteht es, das Herz einer Dame zu betören...\n\nOh, ich kann es kaum erwarten, das zuzubereiten. Aber nicht zu viel! Fleisch serviert man am besten selten, findet Ihr nicht auch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6385] = {title = "Doras der Windreitermeister", objective = "Bringt Gryshkas Brief zu Doras in Orgrimmar.", description = "Ich habe Grimtak einen Dankesbrief geschrieben. Könnt Ihr ihn für mich zustellen? Wenn Ihr schon beim Klingenhügel gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem Windreiter dorthin zurück fliegen.\n\nBringt meinen Brief zu Doras, dem Windreitermeister von Orgrimmar und sprecht mit ihm über den Transport nach Klingenhügel.", progress = "Braucht Ihr einen meiner Windreiter?", completion = "Ihr müsst das nach Crossroads im Brachland bringen? Ja, ich kann Euch dorthin bringen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6386] = {title = "Kehrt nach Klingenhügel zurück", objective = "Bucht einen Windreiter zum Klingenhügel bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Grimtak in Klingenhügel.", description = "Meine Windreiter wurden ausgebildet, an viele verschiedene Orte zu fliegen, wenn Ihr schon an diesem Ort gewesen seid und mit dem Windreitermeister dort gesprochen habt.\n\nIhr seid in Klingenhügel gewesen und habt mit dem Windreitermeister Burok gesprochen, daher könnt Ihr jetzt direkt zu ihm fliegen. Wenn Ihr in Klingenhügel seid, könnt Ihr Gryshkas Brief zu Grimtak bringen.\n\nSprecht wieder mit mir, wenn Ihr bereit zum Aufbruch seid.", progress = "Seid Ihr von Orgrimmar zurück? Hat Gryshka das Fleisch geschmeckt, das ich ihr geschickt habe?", completion = "Ha! Natürlich hat es ihr geschmeckt! Nichts macht die Wangen einer Dame so rot wie ein großes, saftiges Steak!\n\nDanke, &lt;Name&gt;. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr etwas Geld für Eure Mühe, und seid nicht überrascht, wenn ich Euch zu meiner Hochzeit einlade!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6387] = {title = "Ehrenlehrlinge", objective = "Bringt Gremlocks Liste zu Brolan Windbart in Kharanos.", description = "Ich sehe viele junge Zwerge vor meiner Tür, die begierig sind, die Kochkunst zu erlernen. Und wenn ein Koch eines mehr als alles andere braucht, dann ist das ein Beil!\n\nIch habe eine Liste von Kochlehrlingen mit vorzüglichen Abschlussprüfungen, die sich ein Ehrenbeil verdient haben. Bringt meine Liste zu Golnir Geröllzeh in Eisenschmiede. Er wird die Beile bereitstellen.\n\nDas schnellste Transportmittel nach Eisenschmiede ist ein Greif, also bringt die Liste Brolan Windbart, unserem Greifenmeister, und sprecht mit ihm über den Transport nach Eisenschmiede.", progress = "Habt Ihr schon so bald die Nase voll von Thelsamar? Seid Ihr bereit, in eine andere Stadt abzureisen?", completion = "Ihr müsst das nach Ironforge bringen, hm? Für ein geringes Entgelt setze ich Euch auf den Rücken eines meiner Greife, der Euch dorthin bringt. Na, was sagt Ihr dazu?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6388] = {title = "Gryth Thurden", objective = "Bringt die Ehrenbeile zu Gryth Thurden in Eisenschmiede.", description = "Hier sind die Ehrenbeile für Gremlocks Schüler. Wenn Ihr schon in Kharanos gewesen seid, dann solltet Ihr mit einem Greifen dorthin zurückfliegen!\n\nBringt die Beile zu unserem Greifenmeister Gryth Thurden und sprecht mit ihm über die Rückreise nach Kharanos.", progress = "Ihr seht aus, als müsstet Ihr irgendwohin. Braucht Ihr einen meiner Greifen?", completion = "Ihr müsst das nach Thelsamar bringen, hm? Das wird gar kein Problem sein. Wenn Ihr schon in Thelsamar gewesen seid und mit Thorgrum Borrelson gesprochen habt, dann könnt Ihr einen meiner Greifen zurück zu ihm nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6389] = {title = "Eine Plage komme über Euch", objective = "Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestlandtermiten zu Nathaniel Dumah im Zugwindlager in den Westlichen Pestländern zurück.", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", progress = "Habt Ihr es geschafft, <Name>? Habt Ihr die Termiten freigelassen? Das Licht stehe uns bei, wenn der Scharlachrote Kreuzzug sowohl das Werk wie auch Hearthglen halten könnte. Beides hätte nicht gelingen sollen. Sie beuten lediglich die Opfer des letzten Kriegs aus und sollten erlegt werden wie tollwütige Tiere!", completion = "Haha! Danke, &lt;Name&gt;! Ihr habt es geschafft! Meines Vaters Geist findet jetzt Ruhe und ich kann in Frieden leben.\n\nNochmals danke. Wenn ich etwas für Euch tun kann, so sagt es bitte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6390] = {title = "Eine Plage komme über Euch", objective = "Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück.", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", progress = "Habt Ihr es geschafft, <Name>? Habt Ihr die Termiten im Sägewerk freigelassen?\n\nEs war schlimm genug, dass meine Familie Arbeit und Leben verlor, aber dann mit anzusehen, wie der Ort, wo ich meine Kindheit verbrachte, von diesen widerwärtigen sogenannten heiligen Männern übernommen wurde ... bäh!!!", completion = "Danke, &lt;Name&gt;. Hier, nehmt diese Münze. Leider habe ich nicht mehr, aber freut Euch wenigstens darüber, dass Ihr die Bemühungen des Scharlachroten Kreuzzugs durchkreuzt habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6391] = {title = "Flug nach Eisenschmiede", objective = "Bucht einen Greifen nach Eisenschmiede von Greifenmeister Brolan Windbart, dann bringt Gremlocks Liste zu Golnir Geröllzeh in Eisenschmiede.", description = "Für nur ein paar Münzen bringt Euch einer meiner Greifen nach Eisenschmiede. Bringt dann Gremlocks Liste zu Golnir Geröllzeh. Ihr findet ihn in der Tiefenbergbaugilde. Sie liegt im Distrikt der Großen Schmiede von Eisenschmiede, und genau dort setzt Euch mein Greif ab!\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", progress = "Womit kann ich Euch dienen, werter Herr?", completion = "Ah, die neueste Liste von Brocks Meisterschülern. Ich habe schon ein paar Ehrenhacken bereit. Ich muss nur noch die Namen der Studenten eingravieren...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6392] = {title = "Rückkehr zu Gremlock", objective = "Bucht einen Greifen nach Kharanos bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Gremlock Pilsnor in Kharanos.", description = "Für ein geringes Entgelt könnt Ihr einen Greifenritt nach Kharanos buchen... wenn Ihr schon einmal dort gewesen seid. Greifen fliegen nur zu Orten, an denen Ihr schon einmal gewesen seid, sprecht also mit jedem Greifenmeister, den Ihr seht, dann könnt Ihr später direkt zu ihm fliegen.\n\nIhr seid schon bei Brolan, dem Greifenmeister von Kharanos, gewesen, daher könnt Ihr jetzt zu ihm zurückkehren. Wenn Ihr in Kharanos seid, könnt Ihr Gremlock Pilsnor die Beile bringen.\n\nSprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", progress = "Ah, <Name>. Ihr seid aus Ironforge zurück.", completion = "Ihr habt die Hacken. Großartig! Ich werde sie meinen Bergbaustudenten bringen. Sie können es sicher kaum erwarten, sich damit auf die Erzvorkommen von Loch Modan zu stürzen.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Ich stehe in Eurer Schuld, hoffe jedoch, dieses Geld wird wenigstens Eure Reisekosten decken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6393] = {title = "Krieg der Elementare", objective = "Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.", description = "Das Tribunal der Gezeiten hat mich geschickt, um den Feuerelementaren hier im Steinkrallengebirge den Krieg zu erklären. Neptulon der Gezeitenjäger, der Lord aller Wasserelementare hier, hat ein persönliches Interesse daran, dass unsere feurigen Vettern ausgelöscht werden.\n\n<Name>, Ihr könnt mir helfen, die Gunst des Tribunals zu erringen, indem Ihr die Feuerelementare im Verbrannten Tal vernichtet. Wenn Feuerelementare zerstört werden, hinterlassen sie Pyrophore. Bringt sie mir, dann werde ich Euch belohnen.", progress = "Das Tribunal der Gezeiten wird ungeduldig. Es will diesen Krieg beenden, der seit Äonen durch alle Dimensionen wütet. Meine Brüder brennen darauf, dass man ihnen endlich den ruhmreichen Sieg über die verhassten Feuerelementare meldet. Habt Ihr die Pyrophore, die ich benötige?", completion = "Die Wassergeister in mir prickeln vor Aufregung. &lt;Name&gt;, durch Euren Einsatz kann ich dem Tribunal der Gezeiten nun einen glorreichen Sieg vermelden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6394] = {title = "Thazz'rils Hacke", objective = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", description = "<Name>, Ihr seid <ein/eine:r> <Volk>, auf <den/die:r> man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Brennenden Klinge, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", progress = "Habt Ihr den Koven der Burning Blade betreten, <Name>? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, &lt;Name&gt;. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6395] = {title = "Marlas letzter Wunsch", objective = "Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novizin Elreth zurück.", description = "Meine Freundin Marla Fipps lebte vor der Seuche mit ihrem Mann Samuel zusammen, doch als die Seuche kam, erlag Samuel ihr und lief zur Geißel über.\n\nMarla wurde der Untod erspart, doch sie starb durch die Hand ihres jetzt hirnlosen Mannes. Aber ihre Liebe war so stark, dass sie sterbend den letzten Wunsch äußerte, zusammen mit ihrem geliebten Samuel begraben zu werden.\n\nSamuel Fipps streift durch ein verwüstetes Lager nordöstlich von Todesend. Besiegt ihn und erfüllt Marlas Wunsch: Begrabt ihn in ihrem Grab in der ersten Reihe unseres Friedhofs.", progress = "Wir müssen unsere Toten achten, <Name>. Darin unterscheiden wir uns von der Geißel...", completion = "Ihr habt heute eine gute Tat vollbracht, &lt;Name&gt;. Der Kampf gegen die Geißel geht zwar weiter, aber hoffen wir, dass Marla und Samuel gemeinsam Frieden in ihrer letzten Ruhestätte finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6401] = {title = "Kaya lebt", objective = "Teilt Tammra Windfeld, die in Sonnenfels lebt, die gute Nachricht mit.", description = "Teilt Tammra Windfeld, Kayas Tante, die in Sonnenfels lebt, die gute Nachricht mit! Kaya lebt! Wir hatten sie nach dem brutalen Angriff auf unser Dorf schon verloren geglaubt. Folgt dem Pfad nach Westen, um nach Sonnenfels zu gelangen.", progress = nil, completion = "Dem Himmel sei Dank, meine Nichte Kaya lebt! Das sind wahrlich gute Neuigkeiten. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6402] = {title = "Treffen in Sturmwind", objective = "Reist nach Sturmwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marschall Windsor über Eure Ankunft informiert.", description = "Ihr sollt Euch an den Toren von Sturmwind mit Windsor treffen.\n\nWas Windsor Euch eröffnen wird, wird das gesamte Königreich in den Grundfesten erschüttern!\n\nVersucht aber nicht, allein dorthin zu gehen, <Name>. Ihr müsst eine ganze Armee zusammenscharen! Versammelt Eure Mitstreiter. Zu den Waffen!", progress = nil, completion = "Bevor wir beginnen, bitte ich Euch, dass Ihr zuerst eine Armee zusammenzieht. Wir haben es hier schließlich mit einem Drachen zu tun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6403] = {title = "Die große Maskerade", objective = "Folgt Reginald Windsor durch Sturmwind. Schützt ihn vor Gefahren!", description = "Das war vielleicht ein Abenteuer. Ich schulde Euch großen Dank. Vielleicht, wenn alles gesagt und getan ist...\n\nWie Ihr zweifellos schon bemerkt haben werdet, sind Lady Prestor und Onyxia ein und dieselbe Person. Sie ist die Brut von Todesschwinge, Zwillingsschwester des Tyrannen der Spitze, Nefarian.\n\nViel zu lange schon hat sie ihren gierigen Blick auf unser Königreich gerichtet. Sogar der Hochlord steht schon unter dem Bann ihrer Zaubertricks - eine Marionette. Heute wird damit Schluss gemacht... Der Bann wird gebrochen.\n\nSorgt Euch nicht, denn gemeinsam werden wir siegen!\n\nSeid Ihr bereit?", progress = "Ich... Ich... Ich war machtlos.", completion = "&lt;Bolvar hält das zertrümmerte Medaillon in den Händen.&gt;\n\nDie Magie darin muss wieder entfacht werden. Das Großdrachenauge muss eingestellt werden.\n\nWindsors Opfer hat unser Königreich befreit, aber die Bedrohung durch Onyxia und ihresgleichen besteht immer noch.\n\nDieses Medaillon hielt meinen Geist und meinen Körper gefangen. Es ließ mich jedoch auch in Onyxias Geist blicken - zeigte mir ihre Geheimnisse. Die Visionen sind zwar jetzt etwas verschwommen, aber an manche Dinge erinnere ich mich doch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6421] = {title = "Steinschlagklamm", objective = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.", description = "Irgendetwas stimmt hier im Steinkrallengebirge nicht. Spürt Ihr die Spannung, die in der Luft liegt, <Name>?\n\nSüdlich von hier liegt eine tiefe Höhle in der Steinschlagklamm. Die Kobolde dort schürfen wie wild nach einem seltenen Kristall, dem so genannten Resonit. Ich möchte, dass Ihr mir ein paar Erzproben bringt, damit ich herausfinden kann, was in dieser Höhle vor sich geht. Ich hätte auch gern, dass Ihr die Tiefen dieser Höhle untersucht.\n\nGeht nun, <Klasse>, es ist von größter Bedeutung, dass ich in Erfahrung bringe, welche Bösartigkeiten unter diesen Bergen lauern.", progress = "Was habt Ihr in der Steinschlagklamm in Erfahrung bringen können? Ich erinnere mich an eine Legende, die irgendwas mit Resonit zu tun hatte... Ich komme nur nicht darauf. Vielleicht wird es etwas Licht auf ihre verschlagenen Absichten werfen, wenn wir erst wissen, was auf dem Grund der Höhle liegt.", completion = "Ah... ja! Das ist es. Die Resonitkristalle enthalten eine Spur Erdmagie. Die Kobolde müssen sehr tief gegraben haben, um einen Irdenen zu finden.\n\nDen Legenden nach sind die Irdenen Kreaturen, die von den Titanen geschaffen wurden. Sie erschufen das Land, auf dem wir heute stehen. Das ist wahrlich eine Bedrohung, die wir nicht ignorieren dürfen.\n\n&lt;Mor'rogal schüttelt seinen Kopf.&gt;\n\nVielleicht kann ich diese Erzproben verzaubern, um sie gegen die üblen Pläne der Kobolde zu verwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6441] = {title = "Satyrhörner", objective = "Sammelt für Pixel im Splitterholzposten 16 Satyrhörner.", description = "He! Ich bin auf der Durchreise nach Ratschet, habe das ganze Eschental durchquert und mich entschlossen, hier im Splitterholzposten Rast zu machen. Ich suche immer nach guten Gelegenheiten und es scheint mir, dass in Ratschet zurzeit Satyrhörner sehr gefragt sind.\n\nNachdem ich mich hier ein bisschen umgehört habe, glaube ich, dass die Satyrn in der Nachtflucht, Satyrnaar und Xavian genau die Art Hörner besitzen, die ich suche. Ich kann mich mit diesen Satyrn nicht messen... aber Ihr!\n\nIch sag Euch was: Wenn Ihr mir die Hörner bringt, soll es Euer Schaden nicht sein.", progress = "Ich hoffe, Ihr könnt mir bald ein paar dieser Hörner besorgen, <Name>. Ich muss in Kürze nach Ratchet zurück!", completion = "Die sind perfekt, &lt;Name&gt;! Danke, dass Ihr mir geholfen habt!\n\nOh, und das hier ist für Eure Mühen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6442] = {title = "Die Naga am Zoramstrand", objective = "Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.", description = "Entlang der Küste hier lauert das Böse, <Volk>.\n\nSie ist die Ruhestätte der untergegangenen Stadt Zoram, die vor langer Zeit zerstört wurde und im Meer versank. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Die Gründe sind jedoch auch nicht weiter wichtig. Wir müssen das Land verteidigen, um das wir so hart gekämpft haben.\n\nBringt mir 20 ihrer Köpfe! Treibt die Naga in die Tiefen zurück!", progress = "Die Naga werden immer mehr, <Name>. Bitte erledigt diese Aufgabe für mich.", completion = "Wir könnten mehr Eures Schlags hier brauchen, &lt;Name&gt;. Danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6461] = {title = "Blutfresser", objective = "Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.", description = "Wir Trolle hier am Malaka'jin haben von dem Land profitiert. Das Steinkrallengebirge bietet reiche Jagdgründe, von denen wir leben können.\n\nIn letzter Zeit jedoch scheinen wir die falschen Gäste angezogen zu haben... Die Spinnen in diesen Bergen haben nachts unsere Lager überfallen, um uns unsere Jagdbeute zu stehlen.\n\nWenn Ihr uns helfen könntet, diese schrecklichen Bestien zu töten, würden wir hier am Malaka'jin zutiefst in Eurer Schuld stehen. Die Spinnen sind überall im Steinkrallengebirge - geht einfach von hier aus nach Norden, dann werdet Ihr sehen, was ich meine.", progress = nil, completion = "Toll! Gute Neuigkeiten: Vielleicht haben wir heute Nacht ein paar ungebetene Tafelgäste weniger.\n\nVielen Dank, &lt;Name&gt;. Wir stehen für immer in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6462] = {title = "Trollglücksbringer", objective = "Bringt Mitsuwa bei Höllschreis Wacht 8 Trollglücksbringer.", description = "Meine Leute waren mit vielen hochheiligen Trollglücksbringern im Gepäck unterwegs, aber dann wurden sie von Distelfellfurbolgs angegriffen und getötet, bevor sie Zoram'gar erreichen konnten! Diese elenden Furbolgs!\n\nIch vermisse meine getöteten Brüder und Schwestern, aber wir werden uns im Jenseits wiedersehen. Die Trollglücksbringer haben in dieser Welt jedoch hohen Wert. Es ist eine Schande, dass sie jetzt in den Händen der Furbolgs sind!\n\n<Name>, Ihr müsst diese Glücksbringer zurückholen! Sie befinden sich in Kisten in der Höhle, einer Höhle der Distelfelle am Ende des Lagers der Distelfelle nördlich von Astranaar.", progress = "Habt Ihr die Glücksbringer gefunden, <Name>? Jede Sekunde, die die Furbolgs im Besitz dieser heiligen Gegenstände sind, bringt mein Blut mehr zum Kochen!", completion = "Ihr habt sie gefunden! Danke! Danke, &lt;Name&gt;! Ihr wisst ja gar nicht, welch großen Dienst Ihr mir erwiesen habt.\n\nEin Troll ohne Glücksbringer ist wie ein Orc ohne Kampfnarben...\n\nWertlos.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6481] = {title = "Der Irdene erhebt sich", objective = "Öffnet den Resonitbehälter mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.", description = "Ihr habt eine dunkle Bedrohung für das Land entdeckt, <Klasse>. Der Resonitbehälter, den Ihr in der Höhle gefunden habt, birgt einen schlummernden Irdenen namens Goggeroc.\n\nIch habe die Mixtur der Resonitkristalle, die Ihr gesammelt habt, mithilfe meiner Schamanenkräfte verändert. Nehmt den verzauberten Resonitkristall und zerschmettert den Resonitbehälter, in dem sich der Irdene befindet.\n\nWenn Goggeroc erwacht, wird er noch geschwächt sein... erschlagt ihn, <Name>!", progress = "Ich fürchte, dass das ganze Steinkrallengebirge verloren ist, wenn wir diese Bedrohung nicht umgehend beseitigen. Die Macht eines Irdenen ist ohnegleichen. Wenn Goggeroc erwacht, wird er nach seinem langen Schlummer noch geschwächt sein. Das ist die Gelegenheit, die Ihr ergreifen müsst...Geht jetzt, <Name>!", completion = "Das sind gute Neuigkeiten, &lt;Klasse&gt;! Ich fürchte mich vor dem, was ein Irdener in Kalimdor anrichten könnte.\n\nGoggeroc zu töten war eine Tat, die eines Helden würdig ist. Das habt Ihr gut gemacht. Die Bewohner des Steinkrallengebirges und Kalimdors stehen in Eurer Schuld, &lt;Klasse&gt;.\n\nNehmt dies als Belohnung, oh Ehrwürdiger.", rewards = "Handgelenksschützer der WolfsmähneEulenbarts ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6482] = {title = "Freiheit für Ruul", objective = "Begleitet Ruul und sprecht dann mit Yama Schneehuf im Splitterholzposten.", description = "Huch? Wer seid Ihr?\n\n<Name>? Ihr seid kein Furbolg. Sie sind verflucht! Sie haben mich für einen Bären gehalten und mich eingefangen. Jetzt lassen sie mich verhungern! Meine Kraft schwindet...\n\nHelft mir zu entkommen, dann sprecht mit meiner Schwester Yama im Splitterholzposten im Osten.\n\n<Name>! Ich muss entkommen!", progress = nil, completion = "Ihr habt meinen Bruder gefunden! Er wurde vom Distelfellstamm gefangen? Das ist ja schrecklich, denn viele Furbolgs sind zwar edle Kreaturen, aber die Distelfelle sind verderbt.\n\nVielen Dank, dass Ihr meinen Bruder gerettet habt, &lt;Name&gt;. Ich wage gar nicht darüber nachzudenken, wie sie den armen Ruul wohl behandelt haben. Er wird nach diesem Martyrium bestimmt eine ganze Weile schlafen ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6501] = {title = "Das Großdrachenauge", objective = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert.", description = "Ich habe leider nicht mehr als ein Fragment des zertrümmerten Medaillons zu bieten.\n\nIhr müsst einen anderen aus dem Geblüt der Großdrachen finden, der bereit ist, Euch zu helfen, einen neuen Schlüssel zu schmieden. Sobald Ihr diesen Schlüssel habt, müsst Ihr zum Drachensumpf in den Düstermarschen reisen. Dort findet Ihr ihr Lager, <Name>.\n\nWo Ihr weitere Klans finden könnt, die gewillt wären, Euch zu helfen? Das weiß ich leider nicht...Es soll angeblich welche geben. Einige sollen sogar unter uns leben und arbeiten, getarnt als Angehörige der humanoiden Völker. Ich wünsche Euch Glück.", progress = "Ich spüre eine Aura des Bösen, die von Euch ausgeht, <Volk>. Was könntet Ihr besitzen, das eine solche Aura ausstrahlt?", completion = "Ich hätte es wissen müssen... ein Stück der schwarzen Großdrachenbrutmutter Onyxia. Wie widerlich...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6502] = {title = "Drachenfeueramulett", objective = "Ihr müsst das Blut des schwarzen Drachenhelden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Schwarzfelsspitze.", description = "Das ist ein Stück des Großdrachen. Eine Schuppe - verzaubert und transformiert. Als Ganzes hätte sie Zugang zum Hort der Bestie verschafft. Zertrümmert ist sie nutzlos.\n\nEs ist möglich, den Gegenstand zu reparieren, aber dazu wäre das Blut eines schwarzen Großdrachenhelden erforderlich. Es gibt einen... Er ist bekannt als General Drakkisath, Herrscher über die Drachenbrutarmeen von Nefarian. Vielleicht habt Ihr schon von ihm gehört?\n\nBringt mir sein Blut, <Volk>, dann verzaubere ich das Fragment in etwas, das Euch Zugang zu Onyxias Hort verschaffen wird.", progress = "Der Fluss der Zeit hält niemals an oder wird auch nur um etwas langsamer, <Volk>. Mein Leben dauert ewig, Eures jedoch nicht. Vergeudet die Zeit nicht, die Euch noch bleibt...", completion = "Dieses Amulett gewährt Euch den Zugang, auf den Ihr aus seid. Onyxias Hort befindet sich in den Marschen von Dustwallow. Solange Ihr das Amulett habt, können ihre Zauberschütze Euch nicht am Eintreten hindern.\n\nDer blaue Drachenschwarm wünscht Euch Glück, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nDrachenfeueramulett"}
MultiLanguageQuestData['de'][6503] = {title = "Die Kundschafter des Eschentals", objective = "Tötet 9 Kundschafter des Eschentals.", description = "Verdammte Elfen! Die wusst'n genau, wo sie zuschlag'n mussten!\n\nDas war'n diese Kundschafter... Ich hab' ja versucht, sie zu warnen, dass wir bespitzelt werd'n, aber es wollte ja keiner auf mich hör'n. Und jetzt steh'n wir da: eingepfercht wie die Hühner!\n\nIs aber nie zu spät für Rache, Mann! Bringt sie zur Strecke und lasst sie zahlen für das, was sie uns angetan haben!", progress = nil, completion = "Sehr gut, &lt;Name&gt;. Eure Jagdkünste sind beeindruckend...\n\nDer Verlust dieser Kundschafter wird helfen, die Allianz ihrer Augen zu berauben, und wenn sie keine Informationen mehr bekommt, wird sie wohl kaum weiter angreifen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6504] = {title = "Die verlorenen Seiten", objective = "Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen. Bringt die Seiten zu Gurda Zornnarbe in der Nähe des Splitterholzpostens zurück.", description = "Ich habe gerade diesen Schredder in Ratschet abgeholt und war auf dem Heimweg ins Holzfällerlager des Kriegshymnenklans, in dem ich eigentlich Dienst verrichten sollte. Man hat mir eine Anleitung zur Bedienung des Schredders mitgegeben, aber auf dem Rückweg hat ein starker Windstoß sie mir aus den Händen geweht. Die Seiten sind überallhin geflogen und mir blieb nur noch der Einband.\n\nDie Seiten könnten mittlerweile überall sein, nehme ich an...aber ich weiß nicht, wie ich den Schredder ohne sie benutzen soll! Würdet Ihr sie für mich suchen?", progress = "Hoffentlich findet Ihr die Seiten bald, <Name>! Ich muss wirklich wieder zurück an die Arbeit!", completion = "Lesen ist nicht gerade meine Stärke... aber jetzt kann ich endlich wieder zurück an die Arbeit! Danke, &lt;Name&gt;!", rewards = "SchredderbedienungshandschuheÖlige HandlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6521] = {title = "Eine unheilige Allianz", objective = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.", description = "Malcin behauptet, dass er sich abseits der Hügel der Klingenhauer aufhalte. Dieser Botschafter muss getötet werden - seine Mission für den Lichkönig muss fehlschlagen.\n\nSeine Anwesenheit dort erklärt vieles von dem, was wir über diese Gegend herausgefunden haben - einige der Stacheleber sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Das muss in der Tat ein Anzeichen dafür sein, dass sie irgendeine Übereinkunft getroffen haben.\n\nSucht Malcin und tötet ihn, <Name>. Kommt zurück, wenn Ihr das erledigt habt.", progress = "Habt Ihr den Botschafter gefunden, <Name>? Ist er tot?\n\nWir können es uns nicht leisten, dass die Geißel in Kalimdor Fuß fasst. Sie ist bereits schon gefährlich genug für unsere eigenen Grenzen, ein Zweifrontenkrieg wäre zu gefährlich.\n\nDas einzig Positive an den Ereignissen, von denen Ihr mir erzähltet, ist, dass die Greisin nicht verderbt zu sein scheint. Sie muss tief in ihrem Herzen wissen, dass die Geißel große Macht bringen kann, dass das Brachland jedoch nicht wirklich ihr gehören würde, wenn sie sich auf den Handel einließe.", completion = "Gut. Gut gemacht, &lt;Klasse&gt;.\n\nDa Malcin jetzt tot ist, wissen wir zumindest, dass der Vormarsch der Geißel aufgehalten wird. Die Dunkle Fürstin dankt Euch für Eure Bemühungen und möchte Euch zur Belohnung ein Geschenk machen.\n\nWir wissen zwar nicht, wie groß der Einfluss der Geißel in den Hügeln ist, aber wir werden bestimmt schon bald einiges über ihre Pläne herausfinden.", rewards = "SchädelbrecherNagelspeierZelotenrobeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6522] = {title = "Eine unheilige Allianz", objective = "Bringt die kleine Rolle zu Bragor Blutfaust im Königsviertel von Unterstadt.", description = "Mylady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf Weiteres abseits der Hügel der Klingenhauer aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", progress = "Worüber wollt Ihr mit mir sprechen, <Name>? Es muss wohl wichtig für Euch sein, wenn Ihr mich ständig belästigt.", completion = "Ich erkenne die Insignien auf dieser Rolle, &lt;Name&gt;. Ihr habt dies bei der Greisin gefunden, die über den Kral von Razorfen herrscht? Interessant.\n\nDie Geißel scheint sich also offenbar nicht mit einem Kontinent zufrieden zu geben. Dieser Botschafter Malcin - der diese Notiz geschrieben hat - ist einer der von der Geißel verseucht wurde. Er war ein menschlicher Diplomat des Königreichs Lordaeron, bevor sich alles ... verändert hat.\n\nFalls die Geißel versucht, in Kalimdor Fuß zu fassen, liegt es an uns zu handeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6523] = {title = "Schützt Kaya", objective = "Begleitet Kaya Flachhuf zum Camp Aparaje und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.", description = "Habt Dank für meine Rettung! Wir müssen schnell fort von hier, ehe man bemerkt, dass ich frei bin. Bitte begleitet mich zum Camp Aparaje. Von dort aus kenne ich den Weg.\n\nMein Vater Makaba Flachhuf wird unbedingt wissen wollen, dass ich in Sicherheit bin.", progress = nil, completion = "Kaya lebt! Ich habe Euch für ihre Rettung zu danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6541] = {title = "Meldung bei Kadrak", objective = "Meldet Euch im Wachturm im Nördlichen Brachlands bei Kadrak.", description = "Seid Ihr jemals im Norden des Eschentals gewesen? Die Horde hat dort vor Kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Eschentalkampagne und kann Euch weitere Befehle geben.", progress = nil, completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6542] = {title = "Meldung bei Kadrak", objective = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", description = "Seid Ihr jemals im Eschental nördlich von hier gewesen? Die Horde hat dort vor Kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Eschentalkampagne und kann Euch weitere Befehle geben.", progress = nil, completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6543] = {title = "Die Berichte des Kriegshymnenklans", objective = "Öffnet die gebündelten Berichte. Bringt die Berichte des Kriegshymnenklans dem Späher des Kriegshymnenklans, dem Läufer des Kriegshymnenklans und der Vorhut des Kriegshymnenklans. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands.", description = "Ich habe kürzlich ein paar Späher ins Eschental entsandt und brauche jetzt einen Kurier, der ihnen neue Befehle übermittelt und mir einen Bericht über deren Entdeckungen bringt.\n\nEuer erster Halt sollte der Außenposten von Zoram'gar an der Küste Richtung Westen sein. Dort solltet Ihr den ersten Läufer finden. Ihr müsst weiterhin beim Splitterholzposten im Norden und an der Straße nach Osten, die nach Azshara führt, Halt machen. Dort findet Ihr einen Späher und eine Vorhut.\n\nErstattet allen Bericht und lasst Euch von ihnen über ihre Entdeckungen informieren.", progress = "Beeilt Euch, <Name>. Sie müssen die Berichte erhalten, es ist wichtig.", completion = "Wie ich sehe, kann ich auf Euch zählen. Diese Neuigkeiten sind unerlässlich für unsere Pläne, unsere Position in Ashenvale zu festigen. Jetzt können wir unseren nächsten Schritt planen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6544] = {title = "Toreks Angriff", objective = "Eskortiert Torek bei seinem Angriff auf den Außenposten der Silberschwingen und Duriel Mondfeuer. Erstattet dann Ertog Zornhauer im Splitterholzposten Bericht.", description = "He! <Klasse>! Kommt mal her!\n\nMeine Räuber und ich wollten gerade den Außenposten der Silberschwingen im Westen angreifen. Unser Ziel ist die dortige Anführerin, Duriel Mondfeuer. Späher berichten, dass der Außenposten durch Schildwachen und Krieger stark verteidigt wird. Das wird ein ruhmreicher Kampf!\n\nWollt Ihr an dem Ruhm teilhaben und uns helfen, <Name>? Falls ja, könnt Ihr meinem Vorgesetzten Ertog Zornhauer im Splitterholzposten später davon berichten.\n\nWas meint Ihr? Seid Ihr dabei?", progress = nil, completion = "Toreks Angriff war also erfolgreich! Gut gemacht, &lt;Name&gt;. Nachtelfen sind angemessene Feinde. Ein bisschen mager zwar, aber stark und wild! Die Schlacht war bestimmt eine Augenweide...\n\nUnd ich hoffe, Ihr habt Euch ein paar Narben verdient!", rewards = "Polierter WanderstabSchichtmetallentersäbelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6545] = {title = "Aktualisierter Bericht des Läufers des Kriegshymnenklans", objective = "Ihr bringt mir also meine Befehle? Es ist immer wieder schön, einen neuen Rekruten mit Temperament und starkem Willen kennen zu lernen.\n\nIhr solltet besser schnell lernen, wenn Ihr hier am Leben bleiben wollt. Die Gefahr durch die Naga wächst, <Name>. Ich habe alles beobachtet und mich, seit ich hier in diesem Außenposten eintraf, gegen mehrere Angriffe verteidigen müssen.\n\nWenn Ihr Euch entschließen wollt, uns bei unseren Bemühungen beizustehen, sprecht mit einem der anderen hier im Außenposten.", description = nil, progress = "Ihr bringt mir also meine Befehle? Es ist immer wieder schön, einen neuen Rekruten mit Temperament und starkem Willen kennen zu lernen.\n\nIhr solltet besser schnell lernen, wenn Ihr hier am Leben bleiben wollt. Die Gefahr durch die Naga wächst, <Name>. Ich habe alles beobachtet und mich, seit ich hier in diesem Außenposten eintraf, gegen mehrere Angriffe verteidigen müssen.\n\nWenn Ihr Euch entschließen wollt, uns bei unseren Bemühungen beizustehen, sprecht mit einem der anderen hier im Außenposten.", completion = "So, mein neuer Bericht wird Kadrak alles erklären. Ihr müsst dies so schnell wie möglich zu ihm zurückbringen.", rewards = "Ihr bekommt:\n\nAktualisierter Bericht des Läufers des Kriegshymnenklans"}
MultiLanguageQuestData['de'][6546] = {title = "Aktualisierter Bericht der Vorhut des Kriegshymnenklans", objective = "Auf diesem Weg lauern viele Gefahren, <Name>. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.\n\nWir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.\n\nEs ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können... seid auf das gefasst, was vor Euch liegt, <Name>.", description = nil, progress = "Auf diesem Weg lauern viele Gefahren, <Name>. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.\n\nWir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.\n\nEs ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können ... seid auf das gefasst, was vor Euch liegt, <Name>.", completion = "Bringt Kadrak meinen neuen Bericht. Schnellstens, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAktualisierter Bericht der Vorhut des Kriegshymnenklans"}
MultiLanguageQuestData['de'][6547] = {title = "Aktualisierter Bericht des Spähers des Kriegshymnenklans", objective = "Haltet die Augen offen, <Volk>. Oftmals verstecken sich Elfen in den Schatten...\n\nWir müssen immer wachsam sein. Wir haben sehr hart daran gearbeitet, dieses Land zu erobern, und die Elfen suchen nur nach einer Gelegenheit, es uns abzunehmen.\n\nIch nehme an, Ihr habt neue Befehle von Kadrak für mich?", description = nil, progress = "Haltet die Augen offen, <Volk>. Oftmals verstecken sich Elfen in den Schatten...\n\nWir müssen immer wachsam sein. Wir haben sehr hart daran gearbeitet, dieses Land zu erobern, und die Elfen suchen nur nach einer Gelegenheit, es uns abzunehmen.\n\nIch nehme an, Ihr habt neue Befehle von Kadrak für mich?", completion = "Berichtet Kadrak, wie erfolgreich wir die Nachtelfen hier aufgehalten haben. Unsere Pläne laufen gut.", rewards = "Ihr bekommt:\n\nAktualisierter Bericht des Spähers des Kriegshymnenklans"}
MultiLanguageQuestData['de'][6548] = {title = "Rächt mein Dorf", objective = "Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.", description = "Der Grimmtotemklan hat mein Dorf überfallen und fast alle getötet. Ich habe so viele ich konnte niedergestreckt, bin aber nur um Haaresbreite lebend entkommen.\n\nJetzt wünsche ich mir nichts mehr, als noch mehr von ihnen tot zu sehen, <Name>. Ihr findet sie gleich westlich von hier.", progress = "Habt Ihr sie schon getötet?", completion = "Ich danke Euch, &lt;Name&gt;... aber ich werde niemals vergessen, was die Grimmtotem meinem Dorf angetan haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6561] = {title = "Schurkerei in der Tiefschwarzen Grotte", objective = "Bringt den Kopf von Zwielichtfürst Kelris zu Bashana Runentotem in Donnerfels.", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten des Schattenhammers haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Bashana in Donnerfels seinen Kopf, <Name>.", progress = "Möge die Erdenmutter mit Euch sein, <Name>.\n\nUnser Ziel sollte Friede auf der Erde sein und unter denen, die sie bewohnen. Sie hat große Pläne mit der Natur und wir alle müssen unsere Rolle in diesem Plan spielen.", completion = "Kelris hat sich der Argentumdämmerung eine ganze Weile entzogen.\n\nEine Zeit lang galt er sogar als tot oder vermisst.\n\nIndem Ihr seinem Regime ein Ende gemacht habt, habt Ihr die Leben vieler Unschuldiger gerettet, &lt;Name&gt;.\n\nGelobt sei die Erdenmutter! Jemanden einem Diener eines Alten Gottes zu opfern, um persönlich davon zu profitieren, ist mehr als verachtenswert!\n\nHeute habt Ihr etwas Großes geleistet! Kelris war eine Kreatur des Bösen und trachtete danach, die Welt wieder in eine Zeit des Chaos zu stürzen, indem er einem der alten Götter huldigte. Danke, &lt;Name&gt;.", rewards = "GrabsteinszepterArktischer RundschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6562] = {title = "Ärger in der Tiefe", objective = "Sprecht im Eschental mit Je'neu Sancrea.", description = "Je'neu Sancrea braucht Hilfe. Er wartet am Eingang zur Tiefschwarzen Grotte im Eschental. Der Nachtelfenwald liegt im Norden des Steinkrallengebirges. Ihr erreicht ihn, indem Ihr über die Scherwindklippe oder nördlich durchs Brachland reist. Der Zoramstrand liegt weit im Westen des Waldes. Seid vorsichtig, <Name>. Dort gibt es Mächte, denen Eure Anwesenheit nicht gefallen wird.", progress = nil, completion = "Tsunaman schickt Euch? Ausgezeichnet. Dann haben wir einiges zu besprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6563] = {title = "Die Essenz von Aku'mai", objective = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea im Eschental.", description = "Im Eingangsbereich des Tunnels der Tiefschwarzen Grotte findet man überall an den Höhlenwänden große Saphiransammlungen. Kürzlich ist aufgefallen, dass die Naga diese Kristalle abbauen. Bis wir herausgefunden haben, warum sie das tun, sollten wir die Naga einstweilen davon abhalten. Die Kristalle besitzen große Elementarkraft und wenn sie unangemessen eingesetzt werden, könnte man daraus eine mächtige arkane Komponente herstellen.\n\nWerdet Ihr mir helfen, <Name>? Die Tiefschwarze Grotte liegt am Zoramstrand nördlich unseres Außenpostens.", progress = "Wie läuft Eure Suche nach den Kristallen, <Name>? Habt Ihr die Naga beim Abbau der Steine gesehen? Ich bete zu meinen Vorfahren, dass wir den Grund dafür herausfinden, warum sie diese Dinge sammeln.", completion = "Gut gemacht, &lt;Name&gt;. Das sind die Kristalle, von denen ich sprach. Faszinierend...\n\nIch kann die Macht in ihnen spüren. Die Geister des Wassers hängen an ihnen. Was immer die Naga mit ihnen vorhatten... tja, seien wir nur froh, dass sie nicht mehr in ihren Händen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6564] = {title = "Treue zu den Alten Göttern", objective = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea im Eschental.", description = "Die zerknitterte Notiz trägt eine kaum leserliche Handschrift:\n\n\"Ja, sagt allen Priesterinnen, dass sie mir die Kristalle bringen sollen. Die Wasserelementare sind stark in ihnen und sie werden unseren Aquamanten bei ihren Beschwörungen ungemein dienlich sein.\n\nIndem wir die Kraft dieser Kristalle beherrschen, beschwichtigen wir Aku'mai. Eines Tages werden wir genug Macht haben, um Aku'mai zu uns zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren! Eine Ära, in der die Alten Götter herrschen!\"", progress = "Ja, <Name>? Was ist Euer Begehr? Ich muss noch so viel über die Kristalle lernen, die die Naga zusammentragen.", completion = "Das ist in der Tat interessant. Ich bin froh, dass Ihr mich davon in Kenntnis gesetzt habt.\n\nJetzt können wir unseren Problemen auch einen Namen geben... Lorgus Jett.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6565] = {title = "Treue zu den Alten Göttern", objective = "Tötet Lorgus Jett.", description = "Dieser Anhänger des Schattenhammerklans darf seinen Plan nicht in die Tat umsetzen. Die Schattenhammerkultisten verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, <Name>. Ich kann mich leider nicht selbst darum kümmern... ich bin zu schwach.\n\nGeht zur Tiefschwarzen Grotte, findet ihn und tötet ihn. Kehrt hierher zu mir zurück.", progress = nil, completion = "Sehr gut! Danke, &lt;Name&gt;. Wir mögen zwar die Twilight-Hammer nicht vollständig aufgehalten haben, aber zumindest habt Ihr einen weiteren ihrer Pläne durchkreuzt, die Alten Götter wieder mächtig zu machen.\n\nWer weiß, welche Pläne sie sonst noch verfolgen mochten, aber wir können vorerst beruhigt sein.", rewards = "Kastanienbrauner MantelAuf Euch wartet eine dieser Belohnungen:\n\nBand der Faust\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6566] = {title = "Was der Wind erzählt", objective = "Hört Thrall zu.", description = "Schön, Euch wiederzusehen, <Name>. Der Wind führt Kunde aus den Östlichen Königreichen mit sich.\n\nSetzt Euch und lauscht.", progress = "Geduld, <Name>. Passt gut auf!", completion = "Seid Ihr bereit, diese Aufgabe anzunehmen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6567] = {title = "Der Champion der Horde", objective = "Sucht in Schattenflucht in Desolace nach Rokaro.", description = "Rexxar, einer meiner treuesten Helden, hat einen Weg in den Hort des Drachen gefunden. Leider ist er mit unserer Expedition in die Scherbenwelt aufgebrochen.\n\nEr hat jedoch zuvor seinem Freund Rokaro in Schattenflucht die Einzelheiten mitgeteilt. Sucht nach ihm!", progress = nil, completion = "Es gibt nur einen Weg in den Hort des Großdrachen, &lt;Volk&gt;.\n\nWisst Ihr, nur die Stärksten des schwarzen Drachenschwarms dürfen den Hort der Brutmutter betreten. Es müssen viele Prüfungen überwunden werden und der Schlüssel, mit dem man hineingelangt, wurde von General Drakkisath persönlich zeremoniell verzaubert!\n\nDa Ihr nicht zu den schwarzen Großdrachen gehört, werdet Ihr wohl auf einige Schwierigkeiten stoßen, wenn Ihr Einlass verlangt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6568] = {title = "Meisterin der Illusionen", objective = "Überbringt Myranda der Vettel in den Westlichen Pestländern Rokaros Brief.", description = "Illusion und Täuschung. So werdet Ihr es schaffen, den schwarzen Drachenschwarm zu überlisten und zu erlangen, was Ihr sucht.\n\nAuch wenn ich Euch in der Kunst der Täuschung unterrichten könnte, werdet Ihr die Hilfe eines Meistern benötigen.\n\nIch kenne jemanden, der Euch dabei helfen kann. In den Westlichen Pestländern findet Ihr Myranda die Vettel, eine Meisterin der Illusionen aus Lordaeron. Sie hat uns in der Vergangenheit bereits geholfen. Wenn Ihr sie davon überzeugen könnt, dass Eure Sache es wert ist, wird sie Euch vielleicht unterstützen.\n\nBringt diese Nachricht zu ihr.", progress = "In diesem Teil Lordaerons sieht man nur selten einen aus der Horde. Was habt Ihr für Myranda?", completion = "&lt;Myranda hält die Notiz, schweigt eine Weile, dann lächelt sie.&gt;\n\nWie geht es ihm? Rexxar, meine ich. Oh, bitte, schaut nicht so überrascht drein. Der Brief besteht absichtlich nur aus einem leeren Blatt. Er trägt die Absichten und Gedanken des Schreibers. Angesichts des Inhalts ist es kein Wunder, dass Rexxar so verfahren ist. Stellt Euch vor, man hätte Euch gefangen oder getötet und diese Informationen entdeckt!\n\nAch, wie dem auch sei! Myranda wird Euch helfen, &lt;Volk&gt;. Ich schulde dem Kriegshäuptling noch einen oder zwei Gefallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6569] = {title = "Oculus-Illusionen", objective = "Reist zur Schwarzfelsspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Ihr möchtet also einer vom schwarzen Drachenschwarm werden, was, <Volk>?\n\nDie Erschaffung einer Illusion, wie Ihr sie wünscht, ist eine Kleinigkeit, aber die für den Zauber erforderlichen Komponenten sind ziemlich schwierig zu beschaffen. Der Kriegshäuptling hat Euch mit dieser Mission betraut, also muss Myranda wohl annehmen, dass Ihr fähig dazu seid.\n\nReist zur oberen Zitadelle der Schwarzfelsspitze und tötet genug Mitglieder der schwarzen Drachenbrut, um eine Eurer Taschen mit deren Augen zu füllen.\n\nKehrt zu Myranda zurück, wenn Ihr genügend von dem Reagenz gesammelt habt.", progress = "Die Augen derer, die wir verkörpern möchten, sind die wichtigste Zutat für jede Illusion, <Name>.", completion = "Lasst Myranda mal sehen, &lt;Volk&gt;.\n\nAh ja, ausgezeichnet.\n\nAus diesen Reagenzien wird Myranda ein Medaillon für Euch fertigen, mit dem Ihr eine Illusion erzeugen könnt, die den Torhüter des schwarzen Drachenschwarms täuschen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6570] = {title = "Aschenschwinge", objective = "Reist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge.\n\nBereitgestellter Gegenstand: \n", description = "Ich habe dieses Medaillon mit der Magie versehen, die notwendig ist, um eine Illusion zu erschaffen und sie innerhalb der Einfriedung des Höhlenbaus von Aschenschwinge aufrechtzuerhalten.\n\nAschenschwinge ist ein uralter Drache, ein alter Torwächter Nefarians, der die schwere Bürde auf seinen Schultern trägt, jene der Drachenbrut auf die Probe zu stellen, die in den Rang einer Elitewache Onyxias aufsteigen wollen.\n\nReist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr dort seid, legt Ihr das Amulett an und folgt Eurem Schicksal, wo immer es Euch auch hinführen mag!", progress = nil, completion = "Haben wir nur noch so wenige Soldaten, dass Nefarian mir schon Welpen schickt? Du wirst meine Prüfungen nie bestehen, Brutling.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6571] = {title = "Nachschub des Kriegshymnenklans", objective = "Tragt den Nachschub des Kriegshymnenklans zusammen: Sägeblätter des Kriegshymnenklans, ein Holzfällerseil, Öl des Kriegshymnenklans und die Axtlieferung des Kriegshymnenklans für Locke Okarr im Splitterholzposten.", description = "Uns hier im Holzfällerlager des Kriegshymnenklans gehen langsam einige Dinge aus!\n\nUnsere Lieferung Sägeblätter liegt bei Pixel im Splitterholzposten. Jemand muss auch nach Beutebucht reisen, um eine Kiste mit Äxten bei Werftmeister Lozgil abzuholen.\n\nBei unserer Öl- und Seillieferung sieht es jedoch schon schwieriger aus. Die Furbolgs haben die Seile geraubt und die Satyrn haben das Öl abgefangen und nutzen es jetzt für abscheuliche Rituale in der Nachtflucht, Satyrnaar und Xavian!\n\nIch komme in große Schwierigkeiten, wenn ich die Sachen nicht bald ausliefere... könnt Ihr mir helfen?", progress = "Hoffentlich kommt Ihr mit dem Nachschub durch!", completion = "Exzellent, &lt;Name&gt;. Ihr habt mir eine Menge Arbeit erspart!\n\nAber glaubt nicht, dass ich mich nicht erkenntlich zeige!", rewards = "Schärpe des KriegshymnenklansStiefel des KriegshymnenklansStulpen des KriegshymnenklansIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6581] = {title = "Sägeblätter des Kriegshymnenklans", objective = "Direkt aus Ratchet, die Warsongsägeblätter! Jau, die hab ich hier...\n\nAber womit wollt Ihr das bezahlen? Ihr könnt sie nicht einfach so mitnehmen, wisst Ihr! Meine Zeit ist kostbar!\n\nWas ich wirklich brauche, ist eine gute Schusswaffe, die ich auf meine Reisen mitnehmen kann. Ein Mädchen muss sich doch schließlich verteidigen können, wisst Ihr? Es gibt da eine Schusswaffe, die mir wirklich gefällt, und ich bin mir sicher, dass ein Ingenieur kein Problem hätte, so eine anzufertigen.\n\nWenn Ihr mir also eine dieser tödlichen Donnerbüchsen bringen würdet, gebe ich Euch die Sägeblattlieferung. Abgemacht?", description = nil, progress = "Direkt aus Ratchet, die Warsongsägeblätter! Jau, die hab ich hier...\n\nAber womit wollt Ihr das bezahlen? Ihr könnt sie nicht einfach so mitnehmen, wisst Ihr! Meine Zeit ist kostbar!\n\nWas ich wirklich brauche, ist eine gute Schusswaffe, die ich auf meine Reisen mitnehmen kann. Ein Mädchen muss sich doch schließlich verteidigen können, wisst Ihr? Es gibt da eine Schusswaffe, die mir wirklich gefällt, und ich bin mir sicher, dass ein Ingenieur kein Problem hätte, so eine anzufertigen.\n\nWenn Ihr mir also eine dieser tödlichen Donnerbüchsen bringen würdet, gebe ich Euch die Sägeblattlieferung. Abgemacht?", completion = "Das ist perfekt - genau das, was ich wollte! Und hier habt Ihr die Lieferung.", rewards = "Ihr bekommt:\n\nSägeblätter des Kriegshymnenklans"}
MultiLanguageQuestData['de'][6582] = {title = "Die Prüfung der Schädel, Seher", objective = "Ihr müsst Seher, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.\n\nIhr wisst, dass Seher in Winterquell zu finden ist.", description = "Wir sind Kinder von Todesschwinge, Welpe. Wir müssen die Herrschaft über die niederen Aspekte durchsetzen.\n\nWenn Ihr wirklich eines Aufstiegs würdig seid, werden die Geringeren des Drachenschwarms vor Euch niedersinken.\n\nFindet deren Champions und vernichtet sie im Namen unseres Vaters!\n\nBegebt Euch nach Winterquell und spürt den mächtigen Blaudrachen Seher auf. Zerschmettert ihn und alle anderen des blauen Drachenschwarms, die sich Euch in den Weg stellen. Entreißt ihm seinen Schädel und bringt ihn mir.", progress = "<Aschenschwinge faucht.>", completion = "Eine von etlichen Prüfungen überssstanden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6583] = {title = "Die Prüfung der Schädel, Somnus", objective = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück.", description = "Genau wie unser Vater die Aspekte zerschmettert, müssen wir danach trachten, Chaos und Zerstörung unter ihren Kindern anzurichten.\n\nIhr müsst Eure Leistungsfähigkeit im Kampf gegen die schlaflosen Träumer auf die Probe stellen: die Kinder des Gründrachenschwarms.\n\nBegebt Euch zu den Sümpfen des Elends und spürt Somnus auf, den Drachenchampion des Gründrachenschwarms. Lasst Eurem Hass freien Lauf und bezwingt das Insekt...Kommt mit seinem Schädel zu mir zurück...", progress = "Kommt erst wieder, wenn Ihr im Blut unserer Feinde gebadet und Euch an ihrem Leiden gelabt habt.", completion = "Eine weitere bestanden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6584] = {title = "Die Prüfung der Schädel, Chronalis", objective = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge.", description = "Die Zeitbehüter, Kinder Nozdormusss - Lord der Jahrhunderte...\n\nEs sind derer drei, die die Höhlen der Zeit bewachen, aber nur einer, an dem der schwarze Drachenschwarm interessiert ist: Chronalisss, der Zeitverschieber, bevorzugter Drachling Nozdormusss.\n\nBesssiegt diesssen Champion, denn das wäre ein Schlag, der sssogar den stoischen Sand der Zzzeit erschüttern würde. Kehrt mit seinem Schädel zu mir zzzurück.", progress = "Ironischerweissse ist hier die Zzzeit entscheidend, Welpe.", completion = "Der am meisssten Verhasssssste fehlt Euch noch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6585] = {title = "Die Prüfung der Schädel, Axtroz", objective = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück.", description = "Es war in den Bergen von Grim Batol, wo unser Vater gegen die vereinte Macht der Aspekte wütete. Die feige Tat der Verräterin Alexstrasza verschaffte den übrigen Aspekten genug Zeit, um dem Zorn des Vaters zu entkommen.\n\nWasss für ein schändlicher Akt...\n\nDer rote Drachenschwarm bewacht heute Grim Batol und ihr Leutnant Axtroz muss vernichtet werden. Bringt mir Axtroz' Schädel. Für den Vater, Welpe!", progress = "Veränderungen... Ich spüre sie schon in Euch, Welpe. Besteht diese Prüfung, dann wartet nur noch eine Zeremonie auf Euch.", completion = "Ich habe mich in Eurem Engagement getäuscht, Welpe. Ihr wart beharrlich, habt unsere Feinde bezwungen und unserem Klan Ehre gemacht.\n\nJetzt muss ich die Schädel für Euren Aufstieg vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6601] = {title = "Aufstieg...", objective = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Schwarzfelsspitze nicht funktioniert. Vielleicht solltet Ihr Rokaro aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist.", description = "Ein Medaillon, aus den Schädeln Eurer Feinde gefertigt. Ihr kennt dieses Medaillon, nicht wahr? Zweifellos habt Ihr gesehen, wie Eure Ältesten es trugen.\n\nNehmt es, Welpe. Begebt Euch zur Spitze zurück und zeigt es General Drakkisath. Der General wird das Medaillon mit der letzten Verzauberung versehen und das Schmuckstück auf Euren Geist abstimmen.\n\nIhr werdet das fertige Medaillon als Ehrenabzeichen tragen, als Symbol für Euren Aufstieg in unsere am höchsten geschätzten Reihen: Wächter der Brutmutter.\n\nGeht!", progress = "Keine Panik, <Name>!", completion = "Das ist reines Drachengeschwätz, &lt;Name&gt; - viel heiße Luft und keine greifbaren Informationen. Was soll man von ihnen auch anderes erwarten als aufgeblasenes, aggressives Verhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6602] = {title = "Blut des schwarzen Großdrachenhelden", objective = "Begebt Euch zur Schwarzfelsspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rokaro.", description = "Ihr werdet dem General einen Besuch abstatten, jawohl, aber nicht als einer des schwarzen Drachenschwarms.\n\nWisst Ihr, Zeremonie ist für den schwarzen Drachenschwarm nur ein anderer Begriff für Aderlass.\n\nDas ruhende Amulett benötigt nur das Blut des Generals, um wieder aktiv zu sein. Das ist einer ihrer primitiven, ausfallsicheren Mechanismen.\n\nKehrt zur Schwarzfelsspitze zurück und vernichtet Drakkisath. Bringt sein Blut hierher zurück, dann aktiviere ich den Schlüssel zu Onyxias Hort.", progress = "Man darf Drakkisath nicht unterschätzen, <Name>. Er hat den Tod von Tausenden auf dem Gewissen.", completion = "&lt;Rexxar grinst.&gt;\n\nDie Geschichte Eurer Heldentaten wird man sich noch jahrelang erzählen, &lt;Name&gt;. Das Drachenfeueramulett ist der Schlüssel zu Onyxias Hort. Sammelt Eure Streitmacht und erobert ihn im Namen der Horde!", rewards = "Ihr bekommt:\n\nDrachenfeueramulett"}
MultiLanguageQuestData['de'][6603] = {title = "Probleme in Winterquell!", objective = "Findet Donova Schneeweh bei den Thermalquellen in Winterquell.", description = "In Winterquell gibt es Probleme!\n\nSicher, ich habe einige Zeit da draußen in der Wildnis zugebracht und weiß um diese Dinge... Es macht mich immer ganz stolz, das zu sagen. Für mich waren die Stunden, die ich dort draußen in den Hügeln verbrachte, etwas ganz Besonderes. Es hilft einem, blitzschnelle Reflexe zu entwickeln, einen kühlen Kopf und ein wachsames Auge zu bewahren...\n\nMan braucht Urteilsvermögen, Grips und Reife, um die Wildnis so schätzen zu können, wie ich es tue.\n\nAlso, worüber wollte ich eigentlich sprechen?\n\nAch ja, Probleme. Sprecht mit Donova Schneeweh bei den Thermalquellen. Sie wird Euch mehr sagen können.", progress = nil, completion = "Hallo, Ihr da! Meggi hat Euch also schon von den Problemen erzählt, auf die ich hier gestoßen bin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6604] = {title = "Wütende Wildekin", objective = "Sprecht mit Jaron Steinschleifer in Sternfall.", description = "Ist Euch das verlassene Lager südlich von hier aufgefallen? Es scheint, als wären die Wildekin verrückt geworden und haben so gut wie alles zerstört, was sie finden konnten!\n\nIch hab Gerüchte gehört, wonach einer der Überlebenden des Angriffs sich in Sternfall aufhalten soll, das liegt westlich von hier. Ich bin neugierig, was wohl geschehen sein mag...Ihr nicht auch?", progress = nil, completion = "Aye, was kann ich für Euch tun?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6605] = {title = "Eine seltsame Person", objective = "Sprecht im Teufelswald mit Winna Hazzard.", description = "Ich bin gerade erst vom Teufelswald zurückgekehrt, <Name>. Unterwegs habe ich im Blutgiftposten Halt gemacht und eine wirklich eigenartige Bekanntschaft gemacht... Sie schien ganz besessen von einer Sache gewesen zu sein, und ich könnte Euch wohl erzählen, um was es sich handelt, aber ich denke, das sollte sie Euch selbst erklären.\n\nGeht zum Blutgiftposten im Westen des Teufelswalds und fragt nach Winna Hazzard, falls Ihr Interesse habt.\n\nWer weiß, vielleicht braucht sie ja Eure Hilfe...", progress = nil, completion = "Ah, &lt;Klasse&gt;. Also gibt es wohl doch noch Hoffnung. Seid Ihr hier, um mir zu helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6606] = {title = "Ein bisschen Glück", objective = "Sprecht in der Ewigen Warte mit Hexendoktorin Mau'ari.Ein bisschen Glück kann man immer gebrauchen, nicht wahr? Ein kleiner Vorteil ist alles, was man braucht, um eine günstige Wendung herbeizuführen...\n\nIch habe vor einiger Zeit eine ziemlich exzentrische Hexendoktorin kennen gelernt. Sie fertigte einen Glücksbringer für mich... nicht gerade billig. Aber ich sage Euch, er war es auch wert!\n\nMöchtet Ihr vielleicht selbst gern einen haben? Sucht Hexendoktorin Mau'ari in der Ewigen Warte auf. Meinen bekommt Ihr nämlich nicht!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ein bisschen Glück kann man immer gebrauchen, nicht wahr? Ein kleiner Vorteil ist alles, was man braucht, um eine günstige Wendung herbeizuführen...\n\nIch habe vor einiger Zeit eine ziemlich exzentrische Hexendoktorin kennen gelernt. Sie fertigte einen Glücksbringer für mich... nicht gerade billig. Aber ich sage Euch, er war es auch wert!\n\nMöchtet Ihr vielleicht selbst gern einen haben? Sucht Hexendoktorin Mau'ari in der Ewigen Warte auf. Meinen bekommt Ihr nämlich nicht!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6607] = {title = "Nat Pagle, Extremangler", objective = "Nat Pagle möchte, dass Ihr folgende Fische fangt:\n\nNebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.\n\nEinen Sar'therisbarsch vom Sar'therisstrand in Desolace.\n\nFeralas-Ahi aus dem Verdantis in Feralas.\n\nBlauwimpel von der Ungezähmten Küste im Schlingendorntal.\n\nKehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!", description = "Ich kann nicht behaupten, dass ich gern angele. Ich glaub, ich mach das jetzt seit gut 20 oder 30 Jahren.\n\nEs gibt wohl viele Gründe, die einen dazu treiben, etwas zu tun.\n\nIch will damit jetzt nicht sagen, dass Ihr 30 Jahre lang angeln oder jeden einzelnen Fisch im Meer fangen müsst, um ein Meisterangler zu werden. Man muss einfach nur entschlossen sein - entschlossen genug, um stundenlang auf dem Hintern zu sitzen und nichts zu tun.\n\nIch sag Euch was: Fangt mir ein paar seltene Fische, dann bring ich Euch das eine oder andere bei. Hier habt Ihr eine Liste:", progress = "Na, hat heute schon einer angebissen?", completion = "Also das nenn ich einen tollen Fang!\n\nKommt hier rüber, dann zeig ich Euch, wie man die Leinen auswirft.", rewards = "Ihr bekommt:\n\nNats Glücksangel"}
MultiLanguageQuestData['de'][6608] = {title = "Ihr zu gut", objective = "Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht.", description = "Lumak können <Name> nix mehr beibringen. Ihr zu gut! Finden Freund von Lumak, Nat Pagle. Er sein Mensch, aber nix Futter! Ist Freund von Lumak! Nat Euch zeigen, wie besserer angeln.\n\nIhr finden Nat in den Düstermarschen, Süden von Thermoro-odersoähnlich. Nat bestimmt angeln. Ihr jetzt gehen!", progress = nil, completion = "Klar, Ihr müsst ein Freund von Lumak sein.\n\nAngeln? Ich kann Euch alles übers Angeln erzählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6609] = {title = "Ich hab nix mehr!", objective = "Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!", description = "Ich bin ein Zwerg, zum Donnerwetter nochmal, <Jungchen/junge Dame>! Ich hab mit Angeln nichts am Hut! Ich meine, seht mich doch mal an! Ich bestehe praktisch aus Stein.\n\nIch hab nichts mehr - Ihr habt mich ausgelaugt. Ich hab Euch alles beigebracht, was ich weiß, flipflop!\n\nKapiert Ihr's nicht? Ah, gut. Ich hab in Kalimdor einen alten Freund, der Euch weiterhelfen kann. Heißt Nat Pagle, guter Junge. Findet ihn auf den Inseln südlich von Theramore. Jetzt verfatzt Euch!", progress = nil, completion = "Ich hab auf meiner Insel immer Platz für Besucher... Würde ich sagen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6610] = {title = "Muschelette Surprise", objective = "Dirge Schnetzelhack möchte, dass Ihr folgende Dinge besorgt:\n\n10 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.\n\n10 Stück scharfes Muschelfleisch. Das findet Ihr natürlich in Muscheln!\n\n20 Stück feiner alter Cheddar. Begebt Euch zu einer Käserei!\n\nSammelt all diese Gegenstände und kehrt dann zu Dirge zurück.", description = "Schon mal von einem Muschelette gehört? Natürlich nicht! Das ist mein neuestes kulinarisches Meisterwerk. Oh, <Name>, mir läuft das Wasser im Mund zusammen, wenn ich nur an ein Muschelette denke.\n\nLeider habe ich nichts mehr hier, um eins zu machen! Wie wär's mit einem Handel? Ihr besorgt die Zutaten für ein Muschelette und ich bring Euch die Feinheiten der exotischen Küche bei und leg' sogar noch ein paar Muschelettes drauf! Abgemacht?\n\nUnd das brauche ich dafür:", progress = "Meine Gelüste bringen mich noch mal um! Schnell, <Name>, bevor ich den Kitt aus den Fenstern futtere.", completion = "Freut Euch auf ein ganz besonderes Vergnügen, &lt;Name&gt;. Seht zu und lernt!", rewards = "Ihr erlernt:\n\nMuschelette Magnifique\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMuschelette Magnifique\n\nIhr bekommt außerdem:\n\nMuschelette Surprise"}
MultiLanguageQuestData['de'][6611] = {title = "Ab mit Euch nach Gadgetzan!", objective = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere.", description = "Erwartet Ihr etwa, dass Zamja Euch noch irgendwas beibringt? Ihr kennt schon alle von Zamjas Küchentricks und verlangt immer noch nach mehr!\n\nZamja kann nicht helfen. <Fetter/Fette:r> <Volk> muss nach Gadgetzan gehen. Dort findet Ihr einen kleinen Goblin namens Dirge - er wird Euch helfen, Dickerchen.\n\nWenn Ihr dann ein richtiger Sternekoch seid, kommt Ihr zurück und gebt Zamja Unterricht, okay? Und jetzt geht!", progress = nil, completion = "&lt;Dirge spuckt ein paar Fetzen der Ledersandale aus.&gt;\n\nPfui...\n\n&lt;Dirge hustet laut.&gt;\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6612] = {title = "Ich kenne einen Typen...", objective = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere.", description = "Das seh ich doch an Eurem Kochlöffel, dass Ihr wisst, was Ihr tut. Leider kann ich Euch nichts beibringen.\n\nGlück für Euch, ich kenn da einen Typen. Er ist ein Goblin und wahrscheinlich der beste Koch von ganz Kalimdor.\n\nHajo, und jetzt die schlechte Nachricht, <Jungchen/Mädel> - Ihr müsst nach Kalimdor reisen. Geht nach Gadgetzan und sucht nach Dirge Schnetzelhack. Er wird's Euch beibiegen.", progress = nil, completion = "&lt;Dirge spuckt Leder aus.&gt;\n\nPfft...\n\n&lt;Dirge hustet laut.&gt;\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6621] = {title = "König der Fäulnisklauen", objective = "Platziert Senanis Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Senani in der Silberwindzuflucht.", description = "Meine Forschungen haben sich bezahlt gemacht.\n\nIch glaube, dass eine Machtdemonstration die Angriffslust der Furbolgs verringern wird.\n\nNehmt dieses Banner, geht ein paar Schritte in Richtung Nordosten und platziert es auf ihrem Totemhügel. Sie werden versuchen, das Banner zu zerstören, aber Ihr müsst Eure Stellung halten, bis Häuptling Murgut auftaucht, um das Gesicht seines Stammes zu wahren. Bringt mir das Totem, das er trägt.\n\nVersammelt Eure Verbündeten, <Name>. Dies ist keine Aufgabe, die <ein einzelner/eine einzelne:c> <Klasse> bewältigen kann.", progress = "Habt Ihr Häuptling Murgut besiegt, <Name>? Habt Ihr das Fäulnisklauentotem?", completion = "Gute Arbeit, &lt;Name&gt;. Indem wir die Fäulnisklauen herausgefordert und ihren Anführer besiegt haben, haben wir ihnen eine nachdrückliche Warnung erteilt:\n\nMan darf die Horde nicht unterschätzen.\n\nIch glaube, dass uns dieser Stamm für lange Zeit keine Scherereien mehr machen wird.", rewards = "LandgardentunikaKobaltblaue BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][6622] = {title = "Triage", objective = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Horde.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die Leichtverletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nVerbände werden gestellt.\n\nViel Glück, Doktor.", progress = nil, completion = "Doktor &lt;Name&gt;, willkommen bei den Traumachirurgen der Horde.", rewards = "Ihr bekommt:\n\nSchwerer RunenstoffverbandTrauma-Zertifikat der Horde"}
MultiLanguageQuestData['de'][6623] = {title = "Traumachirurg der Horde", objective = "Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt.", description = "Doktor <Name>, nehme ich an. Es ist mir eine Freude, Euch wiederzusehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Doktor Gregory Victor, Chefarzt der Traumachirurgen der Horde, hat Euch persönlich angefordert, damit Ihr Euch ihm in Hammerfall anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gregory Victor studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen!", progress = nil, completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6624] = {title = "Triage", objective = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Allianz.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die Leichtverletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nViel Glück, Doktor.", progress = nil, completion = "Doktor &lt;Name&gt;, willkommen bei den Traumachirurgen der Allianz.", rewards = "Ihr bekommt:\n\nSchwerer RunenstoffverbandTrauma-Zertifikat der Allianz"}
MultiLanguageQuestData['de'][6625] = {title = "Traumachirurg der Allianz", objective = "Reist nach Theramore in die Düstermarschen und sprecht mit Doktor Gustav van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt.", description = "Doktor <Name>, nehme ich an. Es ist mir eine Freude, Euch zu sehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Gustav van Howzen, Chefarzt der Traumachirurgen der Allianz, hat Euch persönlich angefordert, damit Ihr Euch ihm in Theramore anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gustav van Howzen studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen, Doktor!", progress = nil, completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6626] = {title = "Ein Hort des Bösen", objective = "Tötet 8 Schlachtwachen der Klingenhauer, 8 Dornenwirker der Klingenhauer und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Mondsang nahe dem Eingang zu den Hügeln der Klingenhauer zurück.", description = "Die Verlassenen geben ihre... Krankheit... nicht weiter, soweit ich das sehe. Dieser Diplomat scheint Untote als Möchtegernanhänger zu betrachten. Ich glaube langsam, dass er der Geißel angehört.\n\nUm ihn mache ich mir allerdings momentan keine Gedanken, sondern um die wachsende Schar um ihn herum. Tag für Tag kriechen sie aus den Schatten und betteln ihn nahezu um mehr Macht an.\n\nIch bin nicht stark genug, um sie allein zu bekämpfen, <Name>. Was meint Ihr? Hättet Ihr Lust, auf die Jagd zu gehen?", progress = "Wie läuft die Jagd, <Name>? Wenn ich nur dieses kleine Beispiel der Macht dieses Diplomaten hier sehe, zweifle ich nicht mehr daran, dass die Geißel eine der größten Bedrohungen ist, die die Welt je gesehen hat.", completion = "Danke, &lt;Name&gt;! Die Arbeit, die Ihr geleistet habt, wird eine große Hilfe sein, da bin ich mir sicher.\n\nIch werde meine Studien über diesen Diplomaten und den Rest der Stacheleber hier fortsetzen. Wenn Ihr auf größere Abenteuer aus seid, würde ich ein paar Freunde zusammentrommeln und in die Höhle da drüben gehen, die wie ein riesiges Ebermaul aussieht. Ich bin sicher, dass Ihr dort drinnen noch auf viel größere Herausforderungen stoßen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6627] = {title = "Test der Lehre", objective = "Beantwortet Braug Dämmergeists Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid.", description = "Ihr habt mir das Buch gebracht, und jetzt ist es an der Zeit für Eure Befragung. Seid Ihr bereit?\n\nZeit spielt keine Rolle, <Klasse>, also fühlt Euch nicht unter Druck gesetzt. Ihr könnt Euch mit der Antwort so viel Zeit lassen, wie Ihr möchtet.", progress = "Das Leben ist voller Fragen, <Klasse>. Ihr werdet sie niemals alle beantworten können, aber mit der Zeit und durch Studien werdet Ihr Euch bestimmt weiteres Wissen aneignen.", completion = "Gut gemacht, &lt;Klasse&gt;. Ihr habt den Text studiert, wie ich Euch gebeten habe, und jetzt habt Ihr eine weitere unserer Prüfungen bestanden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6628] = {title = "Test der Lehre", objective = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Unterstadt sein, wenn Ihr bereit seid.", description = "Die Zeit ist also wieder einmal gegen uns. Für einen Studenten der Lehre habt Ihr große Hartnäckigkeit bewiesen, indem Ihr meine Aufgabe erledigt habt.\n\nUnd deshalb werde ich Euch eine Frage anbieten. Wenn Ihr bereit seid, sprecht mich wieder an, und lasst Euch so viel Zeit, wie Ihr braucht, <Name> - es besteht keine Notwendigkeit, schnell zu antworten.", progress = "Es gibt nur eine Regel, die Ihr meiner Meinung nach kennen solltet, wenn Ihr in dieser Welt überleben wollt: Je mehr Ihr wisst, desto mehr werdet Ihr sehen.\n\nWenn Ihr studiert, wenn Ihr beobachtet, beginnt Ihr Dinge in der Welt zu sehen, die kein anderer <Volk> sehen kann.", completion = "Gut gemacht, &lt;Name&gt;. Ich hatte meine Zweifel, ob Ihr den Text studieren würdet, den ich Euch gebeten habe zu holen, aber Ihr habt richtig geantwortet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6629] = {title = "Tötet Grundig Finsterwolke", objective = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.", description = "<Name>, Ihr habt gute Arbeit geleistet, indem Ihr Grimmtotem tötetet. Grundig Finsterwolke und seine persönliche Schlägerbande sind bei weitem die Schlimmsten von allen, wenn Ihr Euch traut. Er war einer derjenigen, die den brutalen Angriff auf mein Dorf anführten.\n\nIhr findet ihn im Grimmtotemposten ein Stück weiter den Weg nach Westen hinauf. Tötet ihn, dann werde ich Euch immer dankbar sein.", progress = "Habt Ihr Grundig Finsterwolke und seine persönliche Schlägerbande getötet?", completion = "Grundig Finsterwolke ist tot! &lt;Name&gt;, ich werde immer für das dankbar sein, was Ihr heute hier geleistet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6641] = {title = "Vorsha die Peitscherin", objective = "Bezwingt Vorsha die Peitscherin.", description = "Vorsha die Peitscherin... die satanische Hydra, die die Meere durchstreift...\n\nSie hat unseren Außenposten angegriffen, völlig ohne Grund, und dabei alles verheert, was auf ihrem Weg lag.\n\nAber ich bin bereit, <Name>. Ich bin bereit, die Hydra zu besiegen und den Angriffen auf Zoram'gar ein Ende zu setzen.\n\nDie Naga verehren die tückische Natur dieser Bestie mit einer Kohlenpfanne, die auf einer Insel gleich vor der Küste immer am Brennen gehalten wird. Ich denke, dass Vorsha erzürnt auftauchen wird, wenn wir sie löschen.\n\nWir werden jedoch Hilfe brauchen, also solltet Ihr ein paar starke Verbündete mitbringen.", progress = nil, completion = "Ich habe schon viele Nagaangriffe miterlebt, seit ich hier bin. Es beruhigt mich, dass Vorsha nicht mehr ihr Unwesen treibt.\n\nWir stehen in Eurer Schuld, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nHornring"}
MultiLanguageQuestData['de'][6642] = {title = "Gunst der Bruderschaft, Dunkeleisenerz", objective = "Dunkeleisen, das in der Tiefe zwar reichlich vorkommt, ist innerhalb der Bruderschaft dennoch ein hoch geschätztes Gut. Für die hochheiligen Waffen und Ausrüstungen von Ragnaros wird bevorzugt Dunkeleisen verwendet.\n\nFür 10 Stück Dunkeleisenerz, die Ihr anbietet, steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Dunkeleisen, das in der Tiefe zwar reichlich vorkommt, ist innerhalb der Bruderschaft dennoch ein hoch geschätztes Gut. Für die hochheiligen Waffen und Ausrüstungen von Ragnaros wird bevorzugt Dunkeleisen verwendet.\n\nFür 10 Stück Dunkeleisenerz, die Ihr anbietet, steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil}
MultiLanguageQuestData['de'][6643] = {title = "Gunst der Bruderschaft, Feuerkern", objective = "Wehe denen, die im Geschmolzenen Kern das Schicksal herausfordern. Der Tod kommt schnell - die Strafe erfolgt ohne Gnade.\n\nViele Anhänger der Bruderschaft sind auf der Suche nach Feuerkernen gefallen.\n\nBietet einen Feuerkern an, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Wehe denen, die im Geschmolzenen Kern das Schicksal herausfordern. Der Tod kommt schnell - die Strafe erfolgt ohne Gnade.\n\nViele Anhänger der Bruderschaft sind auf der Suche nach Feuerkernen gefallen.\n\nBietet einen Feuerkern an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil}
MultiLanguageQuestData['de'][6644] = {title = "Gunst der Bruderschaft, Lavakern", objective = "Die Thoriumbruderschaft versteht Eure Notlage, <Volk>. Deshalb haben wir Lokthos zu einem Handel ermächtigt.\n\nBietet 4 Lavakerne an, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Die Thoriumbruderschaft versteht Eure Notlage, <Volk>. Deshalb haben wir Lokthos zu einem Handel ermächtigt.\n\nBietet 4 Lavakerne an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil}
MultiLanguageQuestData['de'][6645] = {title = "Gunst der Bruderschaft, Kernleder", objective = "Für viele der hochheiligen Rezepte ist die Haut von Ragnaros' Lieblingstieren erforderlich.\n\nBietet 4 Kernhäute an, die Ihr den glimmenden Kadavern der Kernhunde des geschmolzenen Kerns abgezogen habt, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Für viele der hochheiligen Rezepte ist die Haut von Ragnaros' Lieblingstieren erforderlich.\n\nBietet 4 Kernhäute an, die Ihr den glimmenden Kadavern der Kernhunde des geschmolzenen Kerns abgezogen habt, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil}
MultiLanguageQuestData['de'][6646] = {title = "Gunst der Bruderschaft, Blut des Berges", objective = "Die Tränen des Feuerlords sind wahrlich ein seltener Fund.\n\nBietet 1 Blut des Berges an, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Die Tränen des Feuerlords sind wahrlich ein seltener Fund.\n\nBietet 1 Blut des Berges an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil}
MultiLanguageQuestData['de'][6661] = {title = "Tiefenbahn-Ratten-Razzia", objective = "Fangt mithilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty.", description = "Haltet ein, Taugenichts. Arrrr... Sucht Ihr Arbeit? Wir ha'm hier ein echtes Rattenproblem und nicht genügend Leute auf dem Hüttendeck.\n\nWas sagt Ihr? Ihr müsst nur diese Rattenfängerflöte nehmen und dem Ungeziefer ein Liedchen vorspielen. Die folgen Euch dann bis ans Ende der Welt!\n\nFangt mir fünf von den kleinen Mistviechern und bringt sie mir. Ich brauch sie lebendig.\n\nArrrrr...", progress = "Harrr... Deckschrubber, was dauert das so lange?", completion = "Die sind ausgezeichnet, Kumpel. Mein Bruder braucht sie quietschlebendig und zappelig, sonst verderben sie... Ihr wollt doch wohl keinen verdorbenen Rattenkebab probieren, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6662] = {title = "Mein Bruder Nipsy...", objective = "Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Sturmwind.", description = "Mein Bruder Nipsy hat 'n Rattengeschäft auf der anderen Seite der Tiefenbahn. Ihr müsst die Kiste mit Ratten hier zu ihm bringen, bevor sie schlecht werden. Zackig!\n\nIhr seid doch wohl schon mal mit 'ner Bahn gefahren, oder? Ganz einfach. Steigt einfach ein, wenn sie kommt, und genießt die Fahrt. Und haltet Eure Arme und Beine während der Fahrt drinnen, wenn Ihr keine Holzgräten haben wollt.", progress = "<Nipsy steckt seinen Zeigefinger in eines der Luftlöcher des Kartons.>\n\nQuietschlebendig und zappelig... und genau zur richtigen Zeit!", completion = "Armer Monty. Seit dem Gnomeregan-Vorfall ist er ein anderer Mensch. Der Junge hat in seinem ganzen Leben noch kein Meer gesehen, ganz zu schweigen von irgendwelchen Piraten.\n\n&lt;Nipsy seufzt.&gt;\n\nZumindest sorgt er dafür, dass es immer Nachschub an quirligen Viechern gibt.", rewards = "Ihr bekommt:\n\nUntergrundrattenkebab"}
MultiLanguageQuestData['de'][6681] = {title = "Das Anwesen, Rabenholdt", objective = "Bringt das Siegel von Rabenholdt zu Fahrad im Rabenholdtanwesen, das versteckt in den Hügeln des Hügellands liegt.\n\nUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.", description = "<Name>,\n\nRabenholdt interessiert sich für Euch, junger Dieb. Wir haben Euch beobachtet. Euer Stil ist ein bisschen unbeholfen, aber daran können wir arbeiten.\n\nWenn Ihr bereit seid, eine Karriere als Schüler von Meister Rabenholdt in Angriff zu nehmen und Mitglied der Auftragsmörderliga zu werden, müsst Ihr nur das Siegel von Rabenholdt (diesem Brief beigefügt) zum Rabenholdtanwesen bringen.\n\nEure erste Aufgabe ist es, das Anwesen zu finden, das versteckt in den Hügeln des Hügellands liegt, um Eure Schlauheit zu demonstrieren.\n\nHochachtungsvoll,\n\nFahrad", progress = "Habt Ihr Milton getroffen?\n\n<Fahrad lacht.>", completion = "Äußerst exzellent, junger Dieb.\n\nIhr seht etwas mitgenommen aus, aber das wird schon wieder.\n\nEine lange Reise erwartet Euch - lang und profitabel. Seid Ihr bereit, Euer Schicksal unter den Meistern von Ravenholdt zu schmieden?\n\nSprecht mit den Wachen da draußen. Sie werden Euch einweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6701] = {title = "Syndikatsembleme", objective = "Wir liegen schon seit Jahren mit dem Syndikat im Clinch. Was denen an Fertigkeit mangelt, machen sie durch ihre große Zahl wett. Es ist unmöglich, sie schnell genug zu töten, um auch nur den geringsten Rückgang ihrer Population feststellen zu können!\n\nWir haben herausgefunden, dass die beste Möglichkeit, ihrer großen Zahl Herr zu werden, darin besteht, ihnen die Embleme zu stehlen. Hat man einem das Emblem gestohlen, 'kümmern' sie sich intern um das mit Schande bedeckte Mitglied.\n\nRaubt Ihnen die Taschen aus und bringt die Embleme mir oder einer der anderen Wachen.\n\nBeginnt in Durnholde südlich von hier.", description = nil, progress = "Wir liegen schon seit Jahren mit dem Syndikat im Clinch. Was denen an Fertigkeit mangelt, machen sie durch ihre große Zahl wett. Es ist unmöglich, sie schnell genug zu töten, um auch nur den geringsten Rückgang ihrer Population feststellen zu können!\n\nWir haben herausgefunden, dass die beste Möglichkeit, ihrer großen Zahl Herr zu werden, darin besteht, ihnen die Embleme zu stehlen. Hat man einem das Emblem gestohlen, 'kümmern' sie sich intern um das mit Schande bedeckte Mitglied.\n\nRaubt Ihnen die Taschen aus und bringt die Embleme mir oder einer der anderen Wachen.\n\nBeginnt in Durnholde südlich von hier.", completion = "He, gute Arbeit! Macht so weiter, dann hören die anderen Schurken vielleicht auf, Euch zu bespucken.", rewards = nil}
MultiLanguageQuestData['de'][6721] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6722] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6741] = {title = "Mehr Beute!", objective = "Wenn Ihr gegen den Feind kämpft, sammelt die Stücke seiner Rüstung und bringt sie mir. Ich werde diese Stücke nutzen, um Rüstungen für unsere eigenen Truppen herzustellen!", description = nil, progress = "Wenn Ihr gegen den Feind kämpft, sammelt die Stücke seiner Rüstung und bringt sie mir. Ich werde diese Stücke nutzen, um Rüstungen für unsere eigenen Truppen herzustellen!", completion = "Und wieder muss ich euch danken, &lt;Name&gt;.  Ihr macht der Horde alle Ehre...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung"}
MultiLanguageQuestData['de'][6761] = {title = "Die neue Grenze", objective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus.", description = "Ich habe meinen Stellvertreter Mathrengyl Bärenfährte beauftragt, sich um die Bitte um Unterstützung der Mondlichtung zu kümmern. Sprecht mit ihm über diese Angelegenheit - NICHT mit mir.\n\nLasst mich Euch einen... gut gemeinten... Rat geben. ICH habe uns aus der Dunkelheit geführt - NICHT der Zirkel des Cenarius auf der Mondlichtung -, als für unser Volk alles verloren war. Teldrassil gibt uns allen neues Leben! Sie wollen Euch anderes glauben machen, und ihre Propaganda zu glauben, wäre reine Blauäugigkeit.\n\nIch werde es Euch überlassen, ob Ihr ein Narr sein wollt oder nicht.", progress = nil, completion = "Vielen Dank, dass Ihr gekommen seid, &lt;Klasse&gt;. Ich entschuldige mich für das Missverständnis... es gibt viel Misstrauen zwischen dem Erzdruiden hier und dem Bewahrer Remulos in Moonglade. Jeder verdächtigt den anderen der Schikane und die Tatsache, dass die merkwürdige Verderbnis von Teldrassil auch weiterhin nicht nachlässt, ist hier immer noch ein Thema. Das trägt wenig dazu bei, das Misstrauen zu lindern.\n\nTrotzdem bleibt unsere Pflicht gegenüber dem Zirkel des Cenarius bestehen... auch wenn diejenigen, die ihn leiten, untereinander uneins sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6762] = {title = "Rabine Saturna", objective = "Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung. Die Mondlichtung liegt zwischen dem Teufelswald und Winterquell, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos bei der Mondlichtung Unterstützung bei der Erforschung des riesigen Ödlands weit im Westen von Tanaris... und noch weiter im Westen von Un'Goro. Ihr solltet ihn in Nachthafen finden, dem Hauptort der Mondlichtung.\n\nEure Arbeit wird zwar zweifellos sehr vorteilhaft für uns sein, dennoch rate ich Euch, Vorsicht walten zu lassen. Es gibt Spannungen zwischen Darnassus und der Mondlichtung... Spannungen, die im Laufe der Zeit wachsen könnten.", progress = nil, completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Ich weiß außerdem, dass der Erzdruide von Darnassus sein Missfallen darüber ausgedrückt hat, dass Ihr uns unterstützt. Seid versichert, dass es zum Guten ist und dass Ihr gegen alle schlechten Auswirkungen gefeit seid, deren Ziel Ihr sein mögt.\n\nIhr seid hier unter Freunden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6781] = {title = "Mehr Rüstungsfetzen", objective = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann helft den Kriegsbemühungen und bringt mir diese Stücke!", description = nil, progress = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann helft den Kriegsbemühungen und bringt mir diese Stücke!", completion = "Das sind ein paar recht gute Stücke, &lt;Name&gt;. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung"}
MultiLanguageQuestData['de'][6801] = {title = "Lokholar der Eislord", objective = "Ich komme aus Thunder Bluff, <Volk>. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.\n\nDoch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.\n\nDer Sieg ist uns sicher, wenn der Lord der Elementare auf die Stormpike-Armee losgelassen wird.", description = nil, progress = "Ich komme aus Thunder Bluff, <Volk>. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.\n\nDoch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.\n\nDer Sieg ist uns sicher, wenn der Lord der Elementare auf die Stormpike-Armee losgelassen wird.", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord diesen Hunden von den Stormpikeden ganzen Zorn des Frostwolfklans vor Augen führen!", rewards = nil}
MultiLanguageQuestData['de'][6804] = {title = "Vergiftetes Wasser", objective = "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der Östlichen Pestländer an. Bringt 12 disharmonische Armschienen sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara.", description = "Eine Truppe von Elementarspähern wurde in die Östlichen Pestländer von Lordaeron entsandt und die Krankheit dieses Orts verdrehte und infizierte sie. Die Wasserlords können diese Beleidigung unserer Reinheit nicht dulden!\n\nNehmt diese Phiole. Darin befindet sich ein Quäntchen eines Aspekts von Neptulon. Wenn das auf die verseuchten Elementare angewendet wird, bekämpft es das Gift in ihren Körpern und heilt sie! Ihr innerer Konflikt wird sie allerdings in den lodernden Wahnsinn treiben.\n\nBesiegt die disharmonischen Wogen und bringt mir ihre Armschienen der Bindung.", progress = "Habt Ihr die Armschienen?", completion = "Ihr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Die verderbten Elementare, die Ihr geheilt habt, waren ein Frevel für alle Gewässer. Unsere Kraft liegt in unserer Reinheit und wenn wir unseren Krieg mit den anderen gewinnen wollen, müssen wir stark bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6805] = {title = "Stürmer und Rumpler", objective = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.", description = "Wir, die Elementare des Wassers, führen Krieg mit den Wesen der niederen Elemente. Wenn Ihr in diesem Konflikt wirklich unser Verbündeter seid, dann beweist mir Eure Überzeugung!\n\nWeit im Süden, im Wüstenland Silithus, treiben sich die Diener der Luft und Erde in einer Felsenecke herum, die Kristalltal genannt wird. Sie schützen Gegenstände der Macht vor kleineren Wesen und Sterblichen, und obwohl ich nicht weiß, warum sie das tun, will ich ihre Bemühungen zunichtemachen.\n\nBegebt Euch zum Kristalltal in Silithus und besiegt unsere Feinde. Kehrt danach zu mir zurück.", progress = "Feigheit ist keine Sache, die wir begrüßen, <Klasse>. Begebt Euch nach Silithus und beweist Euren Mut.", completion = "Euer Mut ist bewiesen, ebenso wie Euer Wert für uns. Vielleicht habe ich in der Zukunft Aufgaben für Euch, die sich eher eines geschätzten Verbündeten der Wasserlords ziemen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6821] = {title = "Auge des Glutsehers", objective = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.", description = "Ihr habt mir gezeigt, dass Ihr unsere Feinde besiegen und Missionen ausführen könnt, um die Sache der Wasserlords weiter voranzutreiben. Aber bisher seid Ihr nur niederen Feinden gegenübergetreten... wenn Ihr gegen einen mächtigen Feind geschickt werdet, könnt Ihr dann siegen?\n\nDas ist Eure neue Aufgabe.\n\nHoch droben auf der Schwarzfelsspitze haben die Orcs einen Diener des Feuers gefangen genommen, die Feuerwache Glutseher. Sucht den Ort seiner Gefangenschaft, erschlagt seine Häscher und erschlagt dann den Glutseher. Bringt mir sein Auge. Das wird mir Euren Wert zeigen.", progress = "Habt Ihr das Auge, <Klasse>? Seid Ihr stark genug, die Blackrockspitze zu betreten?", completion = "Ah, Ihr habt also die Kraft. Und Ihr habt auch die benötigte Schlauheit, denn die Blackrockspitze erfordert mehr als rohe Gewalt.\n\nIn der Tat, &lt;Name&gt;, Ihr könntet Euch für uns noch als geschätzter Verbündeter erweisen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6822] = {title = "Der Geschmolzene Kern", objective = "Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück.", description = "<Name>, vielleicht ist es jetzt an der Zeit, Euch einem echten Test zu unterziehen. Seid Ihr bereit?\n\nAm Fuß der Schwarzfelstiefen befindet sich ein Durchgang zum Geschmolzenen Kern. Er ist eine Festung unseres Feindes, in der Hand des mächtigsten Dieners des Feuers in dieser Welt.\n\nBegebt Euch zum Geschmolzenen Kern, <Name>. Zeigt mir, dass Ihr über die Kraft und den Willen verfügt, das zu besiegen, was Ihr dort finden werdet.\n\nUnd wenn Ihr Verbündete in Eurem Volk habt, dann versammelt sie. Nichts Geringeres als eine Armee kann hoffen, den Geschmolzenen Kern zu betreten und zu überleben.", progress = nil, completion = "Ihr habt getan, was die meisten Eurer Art für unmöglich halten würden. Ihr seid den Wesen des geschmolzenen Kerns gegenübergetreten und habt triumphiert!\n\nFür eine so kleine Kreatur habt Ihr großes Potenzial gezeigt.\n\nEines Tages erreichen wir möglicherweise ein echtes Bündnis zwischen Eurer Art und den Wasserlords.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6823] = {title = "Agent von Hydraxis", objective = "Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara.", description = "Wenn Ihr wirklich ein Bündnis mit uns wünscht, dann schlage ich vor, dass Ihr Krieg gegen unsere Feinde führt, die Diener von Luft und Erde und Feuer. Jede Niederlage, die Ihr ihnen beibringt, wird ihren Stand hier schwächen und Eure Verbindung zu unserer Sache weiter untermauern.\n\nVor Euch liegen lange und harte Schlachten, doch wenn Ihr diese übersteht, so winken Euch Ruhm und Ehre.", progress = nil, completion = "Die Kunde Eurer Heldentaten gegen unsere Feinde hallt in der Kammer der Wasserlords wider, &lt;Name&gt;. Einige waren der Meinung, dass Eure Gestalt zu klein und zerbrechlich sei, um in unserem Krieg zu kämpfen, aber Ihr habt viel gewonnen. Ihr habt Euch unter uns Respekt verdient, ein unglaubliches Kunststück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6824] = {title = "Hände des Feindes", objective = "Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara.", description = "<Name>, Euer Dienst ist für uns von großem Wert, und daher zögern wir, Euch auf diese letzte Mission zu schicken, denn wir wollen einen solch nützlichen Agenten nicht verlieren.\n\nAber der Erfolg würde unsere Kriegsbemühungen ungeheuer voranbringen und... das wird als ausreichend erachtet, Euer Leben zu riskieren.\n\nWir wollen, dass diese Hauptmänner im Geschmolzenen Kern vernichtet werden: Lucifron, Sulfuron, Gehennas und Shazzrah. Tötet sie und bringt mir ihre Hände!\n\nDiese Aufgabe wird Euer ganzes Können erfordern, <Name>, aber wenn Ihr erfolgreich seid, dann wird den Feuerlords ein schrecklicher Schlag versetzt.", progress = "Habt Ihr Lucifron und die anderen besiegt, <Name>? Habt Ihr die Hände des Feindes?", completion = "Ihr habt die Hände! Die besiegten Feuer-Captains! Ich hätte es nicht für möglich gehalten, wenn ich Euch nicht kennen würde und wüsste, wozu Ihr fähig seid.\n\n&lt;Name&gt;, Eure Heldentaten sind ohne Zahl, aber die Kunde von dieser letzten Heldentat wird unter den Wasserlords Wellen schlagen. Euer Name könnte eines Tages eine Legende unter uns sein.\n\nSprecht wieder mit mir, &lt;Name&gt;. Ich habe möglicherweise noch eine weitere Aufgabe ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6825] = {title = "Ruf der Lüfte - Guses Luftflotte", objective = "Wir müssen die neue Flotte von Kriegsreitern vorbereiten, <Volk>! Meine Reiter sind bereit, einen Schlag auf dem zentralen Schlachtfeld zu landen, aber zuerst muss ich ihnen den Mund wässrig machen - sie auf den Angriff vorbereiten.\n\nIch benötige ausreichend Soldatenfleisch der Allianz, um eine Flotte zu ernähren! Hunderte Pfund! Ihr könnt das doch sicherlich übernehmen, nicht wahr? Geht schon!", description = nil, progress = "Wir müssen die neue Flotte von Kriegsreitern vorbereiten, <Volk>! Meine Reiter sind bereit, einen Schlag auf dem zentralen Schlachtfeld zu landen, aber zuerst muss ich ihnen den Mund wässrig machen - sie auf den Angriff vorbereiten.\n\nIch benötige ausreichend Soldatenfleisch der Allianz, um eine Flotte zu ernähren! Hunderte Pfund! Ihr könnt das doch sicherlich übernehmen, nicht wahr? Geht schon!", completion = "Die Flotte ernährt sich von ihrem Fleisch. Sie verzehrt den Feind.\n\nDer Flug steht unmittelbar bevor!", rewards = nil}
MultiLanguageQuestData['de'][6826] = {title = "Ruf der Lüfte - Jeztors Luftflotte", objective = "Ihr habt hart gearbeitet, <Name>, aber wir haben gerade erst begonnen!\n\nMeine Kriegsreiter müssen das Fleisch ihrer Ziele schmecken. Damit wird ein chirurgischer Schlag gegen unsere Feinde sichergestellt!\n\nMeine Flotte ist die zweitmächtigste in unserem Luftkommando. Daher wird sie beim mächtigsten unserer Gegner zuschlagen. Und dafür benötigt sie das Fleisch der Lieutenants der Allianz.\n\nSputet Euch!", description = nil, progress = "Ihr habt hart gearbeitet, <Name>, aber wir haben gerade erst begonnen!\n\nMeine Kriegsreiter müssen das Fleisch ihrer Ziele schmecken. Damit wird ein chirurgischer Schlag gegen unsere Feinde sichergestellt!\n\nMeine Flotte ist die zweitmächtigste in unserem Luftkommando. Daher wird sie beim mächtigsten unserer Gegner zuschlagen. Und dafür benötigt sie das Fleisch der Lieutenants der Allianz.\n\nSputet Euch!", completion = "Mehr! Mehr! Bringt mehr, denn sie müssen bald bereit sein!", rewards = nil}
MultiLanguageQuestData['de'][6827] = {title = "Ruf der Lüfte - Mulvericks Luftflotte", objective = "Ich war tagelang in einem Höllenloch der Zwerge eingesperrt. Und das schreit geradezu nach Rache!\n\nWir müssen alles sorgfältig planen.\n\nZuerst benötigen meine Kriegsreiter Ziele, auf die sie sich konzentrieren können - Ziele von hoher Priorität. Ich muss das Fleisch der Kommandanten der Allianz an sie verfüttern. Leider haben sich diese kleinen Mistkerle tief hinter den feindlichen Linien verschanzt! Diese Arbeit ist wahrlich wie geschaffen für Euch.", description = nil, progress = "Ich war tagelang in einem Höllenloch der Zwerge eingesperrt. Und das schreit geradezu nach Rache!\n\nWir müssen alles sorgfältig planen.\n\nZuerst benötigen meine Kriegsreiter Ziele, auf die sie sich konzentrieren können - Ziele von hoher Priorität. Ich muss das Fleisch der Kommandanten der Allianz an sie verfüttern. Leider haben sich diese kleinen Mistkerle tief hinter den feindlichen Linien verschanzt! Diese Arbeit ist wahrlich wie geschaffen für Euch.", completion = "Nicht genug! Solch eine Arbeit würde ich von einem Initianden erwarten, aber von Euch, &lt;Name&gt;? Kommt schon! LASST KNACKEN! Es wird mehr Fleisch benötigt!", rewards = nil}
MultiLanguageQuestData['de'][6844] = {title = "Umber, Archivar", objective = "Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nachthafen auf der Mondlichtung.", description = "Hier gibt es immer noch viel zu tun, aber ich denke, es ist wichtig, dies zur Analyse zum Zirkel zurückzubringen. Vertraut mir - es wird immer noch Arbeit geben, wenn das alles erledigt ist. Wenn sich in diesem klebrigen Chitin ein Tagebuch befindet, hätte der Zirkel endlich ein Fenster zur Vergangenheit geöffnet!\n\nBringt dies zum Archivar des Zirkels in Nachthafen. Sein Name ist Umber und er ist brillant. Er ist etwas eigenartig, sicher, aber trotzdem brillant! Umber hat schon Folianten gerettet, die in wesentlich schlechterem Zustand waren als dieser hier. Wenn dieser gerettet werden kann, dann schafft er es.", progress = "Oh, hallo! Hrmm...\n\nLasst mich ehrlich zu Euch sein... Ihr riecht ein wenig streng. Abgestanden, könnte man sagen. Aber ich möchte Eure Person nicht angreifen. Ich sage nur... in Zukunft solltet Ihr Euch ein wenig frisch machen, wenn Ihr vom Schlachtfeld kommt. Damit könnte der erste Eindruck wesentlich positiver ausfallen!\n\nAber egal... was kann ich für Euch tun?", completion = "Heiliger Bimbam! Was habt Ihr denn da? Ich würde sagen, es hat die Form eines Buches... Ich werde versuchen, die Schale darum aufzubrechen.\n\nLayo hat Euch aus Silithus zu mir geschickt? Ich habe nur ein paar geflüsterte Gerüchte gehört - die ja wohl nicht unbedingt geflüstert sind, wenn man's genau nimmt - über die Schrecken, die dort draußen vor sich gehen. Verbindet das mit meiner Abneigung gegen alles Käferähnliche und Ihr habt ein Rezept, damit ich hier bei diesen Büchern bleibe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6845] = {title = "Enthüllung von Geheimnissen der Vergangenheit", objective = "Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung.", description = "Tja, Ihr solltet möglichst bald wieder zu mir kommen... falls Ihr wissen wollt, was sich hier drinnen befand. Sobald ich herausfinde, was es ist, und falls es in der Tat ein Buch ist, werde ich diese Informationen gern mit Euch teilen.\n\nIn der Zwischenzeit solltet Ihr Euch an die Höhlenmutter dieses kleinen Bärenlagers wenden, Rabine. Es ist bestimmt für alle interessant zu wissen, was für verrückte Dinge Ihr so erlebt habt. Lasst die Höhlenmutter niemals warten, <Name>... zumindest nicht, wenn Ihr nicht in Honig getaucht werden wollt.\n\nDas ist schon passiert, glaubt mir.", progress = nil, completion = "Ah, &lt;Name&gt;... ich hatte gehofft, dass Ihr vorbeikommen würdet. Es ist schön, Euch gesund und munter zu sehen.\n\nIch hatte Nachricht erhalten, dass Ihr vom Schlachtfeld herkommen würdet, und ich wollte persönlich die Dankbarkeit des Zirkels des Cenarius für die Unterstützung zum Ausdruck bringen, die Ihr uns bisher angedeihen ließet. Zweifellos gibt es noch weitere Geheimnisse über die Silithus zu enthüllen. Eure Lieferung an Umber sollte sich als sehr interessant erweisen, wenn sie erst enthüllt ist. Nehmt dies bitte als Zeichen unserer kontinuierlichen Wertschätzung für Eure Hilfe.\n\nDanke, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des lebenden SteinsLeuchtender Kristallring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6846] = {title = "Der Angriff soll beginnen!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6847] = {title = "Meister Rysons Allsehendes Auge", objective = "Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, <Klasse>. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6848] = {title = "Meister Rysons Allsehendes Auge", objective = "Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, <Klasse>. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6861] = {title = "Zinnzischelix's tragbare Schreddereinheit", objective = "Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, <Volk>, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Sturmlanzen aufgefallen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZinnzischelixs tragbare Schreddereinheit"}
MultiLanguageQuestData['de'][6862] = {title = "Zinnzischelix's tragbare Schreddereinheit", objective = "Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, <Volk>, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Frostwölfe aufgefallen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZinnzischelixs tragbare Schreddereinheit"}
MultiLanguageQuestData['de'][6881] = {title = "Ivus der Waldfürst", objective = "Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.\n\nDer Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.\n\nDie Soldaten der Frostwolf tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, <Name>!", description = nil, progress = "Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.\n\nDer Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.\n\nDie Soldaten der Frostwolf tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, <Name>!", completion = "Gut gemacht, &lt;Name&gt;. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldfürsten herbeizurufen.", rewards = nil}
MultiLanguageQuestData['de'][6901] = {title = "Startet den Angriff!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][6921] = {title = "Inmitten der Ruinen", objective = "Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", description = "Die Anhänger des Schattenhammers sind in die Mondschreinruinen der Tiefschwarzen Grotte eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.\n\n<Name>, geht in die Tiefschwarze Grotte und findet den Tiefenstein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Tiefenkern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", progress = "Konntet Ihr den Fathom-Kern finden? Ohne ihn haben wir keine Ahnung, was genau die Twilight-Hammer da unten vorhaben.", completion = "Genau das brauche ich! Ein Fathom-Kern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Twilight-Hammer da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann -, meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6922] = {title = "Baron Aquanis", objective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea in der Tiefschwarzen Grotte.", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgt hat. In der Kugel schwappt faulig aussehendes Wasser herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring.", progress = "Ach, hallo, <Name>. Ich habe gerade in den Wellen der See gelesen, wie ich es immer tue. Was führt Euch in den Außenposten?", completion = "Das... das ist ein wichtiger Fund, &lt;Name&gt;.\n\nIhr habt dies von Baron Aquanis aus Blackfathom, sagt Ihr? Man hatte Baron Aquanis schon lange im Verdacht, eine verderbte Elementarkraft zu sein. Diese Kugel wird zeigen, was genau ihn verdorben hat. Es würde mich nicht im Geringsten überraschen, wenn es sich dabei um die Twilight-Hammer handelt. Aber unsere Studien werden auch aufzeigen, wie sie das getan haben.\n\nIhr habt das Richtige getan, indem Ihr dies zu mir brachtet. Bitte, nehmt dies zusammen mit den wärmsten Empfehlungen des Irdenen Rings.", rewards = "GesetzlosensäbelAuf Euch wartet eine dieser Belohnungen:\n\nHexenfinger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][6941] = {title = "Ruf der Lüfte - Vipores Luftflotte", objective = "Die Eliteeinheiten der Horde, die die Linien bewachen, müssen erledigt werden! Ich vertraue Euch die Aufgabe an, diese Herde von Wilden auszudünnen. Kehrt mit den Medaillen ihrer Offiziere und Legionäre zu mir zurück. Wenn ich das Gefühl habe, dass ausreichend Gesindel erledigt wurde, werde ich den Luftschlag anordnen.", description = nil, progress = "Die Eliteeinheiten der Horde, die die Linien bewachen, müssen erledigt werden! Ich vertraue Euch die Aufgabe an, diese Herde von Wilden auszudünnen. Kehrt mit den Medaillen ihrer Offiziere und Legionäre zu mir zurück. Wenn ich das Gefühl habe, dass ausreichend Gesindel erledigt wurde, werde ich den Luftschlag anordnen.", completion = "Der Klan wird bald bereit sein. Setzt Eure Bemühungen fort!", rewards = nil}
MultiLanguageQuestData['de'][6942] = {title = "Ruf der Lüfte - Slidores Luftflotte", objective = "Meine Greifen sind bereit, an den Frontlinien zuzuschlagen, können den Angriff aber erst vornehmen, wenn die Linien ausgedünnt sind.\n\nDie Krieger der Horde, die mit dem Halten der Frontlinien betraut sind, tragen stolz Verdienstmedaillen an ihrer Brust. Reißt diese Medaillen von ihren verfaulten Körpern und bringt sie mir.\n\nWenn die Frontlinie ausreichend ausgedünnt wurde, werde ich den Luftschlag anordnen! Tod von oben!", description = nil, progress = "Meine Greifen sind bereit, an den Frontlinien zuzuschlagen, können den Angriff aber erst vornehmen, wenn die Linien ausgedünnt sind.\n\nDie Krieger der Horde, die mit dem Halten der Frontlinien betraut sind, tragen stolz Verdienstmedaillen an ihrer Brust. Reißt diese Medaillen von ihren verfaulten Körpern und bringt sie mir.\n\nWenn die Frontlinie ausreichend ausgedünnt wurde, werde ich den Luftschlag anordnen! Tod von oben!", completion = "Immer her damit, Soldat! Die Aerie-Greifen werden im Handumdrehen bereit sein zuzuschlagen!", rewards = nil}
MultiLanguageQuestData['de'][6943] = {title = "Ruf der Lüfte - Ichmans Luftflotte", objective = "Ihr Mut ist auf einem Tiefpunkt, Soldat. Nach unserem letzten fehlgeschlagenen Luftschlag gegen die Horde wollten sie nicht mehr fliegen! Es liegt an Euch, ihre Moral wieder aufzubauen.\n\nKehrt zum Schlachtfeld zurück und schlagt im Herzen des Befehlsstabs der Horde zu. Erledigt ihre Kommandanten und Wächter. Kehrt mit so vielen ihrer Medaillen zu mir zurück, wie Ihr in Eurem Beutel unterbringen könnt! Ich verspreche Euch, wenn meine Greifen die Beute sehen und das Blut unserer Feinde riechen, werden sie wieder fliegen! Geht jetzt!", description = nil, progress = "Ihr Mut ist auf einem Tiefpunkt, Soldat. Nach unserem letzten fehlgeschlagenen Luftschlag gegen die Horde wollten sie nicht mehr fliegen! Es liegt an Euch, ihre Moral wieder aufzubauen.\n\nKehrt zum Schlachtfeld zurück und schlagt im Herzen des Befehlsstabs der Horde zu. Erledigt ihre Kommandanten und Wächter. Kehrt mit so vielen ihrer Medaillen zu mir zurück, wie Ihr in Eurem Beutel unterbringen könnt! Ich verspreche Euch, wenn meine Greifen die Beute sehen und das Blut unserer Feinde riechen, werden sie wieder fliegen! Geht jetzt!", completion = "Seht Ihr es? Schaut sie Euch an! Sie rappeln sich wieder auf... Bald wird Ichmans Klan erneut im Herzen des Tales zuschlagen! Stormpike wird den Himmel beherrschen!", rewards = nil}
MultiLanguageQuestData['de'][6961] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich wünsche ein wunderbares Winterhauchfest! Vergesst nicht, Altvater Winter zu begrüßen! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... ''Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\n Wenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6962] = {title = "Leckereien für Altvater Winter", objective = "Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Orgrimmar.", description = "He, könnt Ihr Altvater Winter einen Gefallen tun, ähm, <Kleiner/Kleines>?\n\nIch will ja nicht überflüssigerweise über mich selbst in der dritten Person sprechen, aber Altvater Winter arbeitet schon den ganzen Tag hier und könnte selbst eine kleine Leckerei brauchen. Ein paar Lebkuchen und etwas eiskalte Milch, um sie runterzuspülen, wären genau das Richtige. Glaubt Ihr, Ihr könntet dem Altvater eine Freude machen und das für mich besorgen?", progress = "Durch diese ganze Rederei über Leckereien bin ich langsam schon selbst ganz wild darauf. Mmmm... Lebkuchen und Milch...", completion = "Ihr seid ein wahrer Helfer für den alten Altvater Winter, &lt;Name&gt;. Ich wünsche Euch ein wunderbares Winterhauchfest.\n\nHier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe.", rewards = "Ihr bekommt:\n\nKokelwälder Geschenkpackung"}
MultiLanguageQuestData['de'][6963] = {title = "Gestohlene Winterhauchleckereien", objective = "Sucht den Ermittler von Kokelwälder, der in den verschneiten Regionen des Vorgebirges des Hügellands vermisst wird.", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhandengekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, das an das Vorgebirge des Hügellands angrenzt und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", progress = nil, completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Orgrimmar. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6964] = {title = "Der Anlass für die Feiertage", objective = "Sprecht mit Sagorne Gratläufer im Tal der Weisheit von Orgrimmar über das Winterhauchfest.", description = "Gaben, Leckereien, Geschenke, pah!\n\nDiese Goblins beschmutzen die wahre Bedeutung dieser Feiertage - des Winterhauchfests. Dies ist eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die Altvater Winter gebracht hat, und das ist NICHT der Wichtigtuer da drüben in dem roten Aufzug!\n\nFalls Ihr erfahren wollt, worum es bei dem Fest wirklich geht, dann fragt Sagorne Gratläufer. Es dürfte ihn bestimmt überraschen, dass sich jemand für Geschichte statt für Geschenke interessiert.", progress = nil, completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Tauren eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende dieser Feiertage der Erneuerung zur verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Furmund diese Veränderung bitter aufstößt. Er und andere Tauren wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6981] = {title = "Der leuchtende Splitter", objective = "Begebt Euch nach Ratschet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.\n\nLiefert dann den Splitter ab, wie Ihr angewiesen wurdet.", description = "Der Splitter ist von einem glänzenden Grün, und obwohl er massiv ist, scheint etwas wie Rauch knapp unterhalb der Oberfläche herumzuwirbeln. Ihr fühlt den Zwang, in die Tiefen des Kristalls zu schauen, aber gleichzeitig fühlt Ihr auch, dass etwas sehr Beunruhigendes von ihm ausgeht.\n\nVielleicht solltet Ihr in Ratschet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", progress = "Hallo, <Volk>. Was kann ich für Euch tun?", completion = "Oh... So etwas habe ich noch nie gesehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6982] = {title = "Vorräte der Eisbeißermine", objective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Allianz in Dun Baldar.", description = "Die Eisbeißermine ist ein Vorratslager für die Horde. Ich vertrage das Essen nicht, das sie ihren Truppen reichen und der Zustand ihrer Waffen und Rüstungen ist grauenhaft! Aber... in Zeiten wie diesen, in denen Vorräte so wichtig sind, können wir wirklich alles verwenden, was sie haben. \n\nBetretet die Eisbeißermine und bringt mir ihre Vorräte. Dies sollte der Allianz helfen sich weiterhin gut im Kampf zu bewähren und die Soldaten der Horde schwächen.\n\nViel Erfolg, <Name>. Die Mine ist im entfernten Süden, tief im Territorium der Horde.", progress = "Habt Ihr die Coldtooth-Mine im Gebiet der Horde betreten, <Name>? Habt Ihr die Vorräte?", completion = "Ihr habt sie! Gut gemacht, &lt;Name&gt;! Ich werde dann mal durch die Vorräte durchgehen und sehen was wir für unsere Truppen gebrauchen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][6983] = {title = "So was Gemeines...", objective = "Sucht die gestohlenen Leckereien und befreit Metzen das Rentier, nachdem Ihr den monströsen Griesgram besiegt habt. Er verbirgt sich nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", description = "Eine Kreatur namens \"Der monströse Griesgram\" hat unsere Lieferung mit Leckereien gestohlen, <Name>. Seid aber vorsichtig! Er ist bösartig und befiehlt über ein paar dieser kleinen grünen Gnome!\n\nIhr werdet Hilfe brauchen, wenn Ihr ihm gegenübertretet. Ich habe gehört, dass er unsere Leckereien und Metzen, unser geliebtes Rentier, in die Eisfellhöhle im Vorgebirge des Hügellandes gebracht hat. Findet die Leckereien, <Name>, und bringt sie zurück nach Orgrimmar, bevor das Fest ruiniert ist und all die Kinder enttäuscht werden!", progress = "<Name> - unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt es gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nKokelwälder verehrt Euch dafür und natürlich tun das auch all die Kinder!", rewards = "Ihr bekommt:\n\nGestohlenes GeschenkGestohlenes Geschenk"}
MultiLanguageQuestData['de'][6984] = {title = "Ein Dankeschön von Kokelwälder!", objective = "Sprecht mit Altvater Winter in Orgrimmar.", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, <Name>. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost... dank Euch natürlich!", progress = nil, completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", rewards = "Ihr bekommt:\n\nKokelwälder Spezialgeschenk"}
MultiLanguageQuestData['de'][6985] = {title = "Vorräte der Eisenschachtmine", objective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Horde in die Burg Frostwolf.", description = "Die Zwerge der Sturmlanzen benutzen die Eisenschachtmine als ein Vorratslager. Ich möchte, dass Ihr diese Mine überfallt und mir ihre Vorräte bringt. Dies sollte die Bemühungen der Sturmlanzen im Alteractal behindern und uns mit der nötigen Ausrüstung versorgen!\n\nSeid vorsichtig, <Name>. Die Eisenschachtmine liegt tief im Territorium der Allianz, und die Kontrolle über die Mine ändert sich so oft wie neuer Schnee in Alterac fällt.", progress = "Wart Ihr in der Irondeep-Mine, <Name>? Habt Ihr die Vorräte geplündert?", completion = "Ihr habt Sie! Gute Arbeit, &lt;Name&gt;! Hoffentlich habt Ihr unterwegs noch ein paar Zwerge getroffen und ihr Blut im Namen der Frostwolf vergossen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7001] = {title = "Verwaiste Ställe", objective = "Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.", description = "Der Krieg hier im Tal hat viele Opfer gefordert. Unsere Streitkräfte müssen dringend wieder aufgebaut werden!\n\nWenn wir es schaffen unsere Ställe wieder zu füllen, können unsere glorreichen Wolfsreiter wieder in die Schlacht reiten.\n\nNehmt diesen Maulkorb und begebt Euch in die nahegelegenen Wälder. Sucht in der Umgebung nach herumstreifenden Frostwölfen und fangt sie mit dem Maulkorb ein. Wenn Ihr einen Wolf gezähmt habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen.\n\nSobald wir wieder über ausreichend Wölfe verfügen, werden die Wolfsreiter ihre Frontpatrouillen fortsetzen.", progress = "Ohne Eure Hilfe, hätten die Frostwolfreiter keine Reittiere um in die Schlacht zu ziehen. Ihr erweist uns einen großen Dienst!", completion = "Ich kann nur hoffen das andere die mit dem Sammeln von Widderbälgern beauftragt wurden, ebenso motiviert sind wie Ihr, &lt;Name&gt;.\n\nBei diesem Arbeitstempo, werden die Ställe in wenigen Stunden wieder voll sein!", rewards = nil}
MultiLanguageQuestData['de'][7002] = {title = "Widderledernes Zaumzeug", objective = "Während einige unserer Soldaten damit beschäftigt sind, Wölfe für den Stallmeister einzufangen, müssen andere für die einfachsten Sachen sorgen, die man beim Reiten braucht. Ich meine Geschirre, klar?\n\nIhr müsst die einheimischen Widder jagen. Genau die Widder, die die Stormpike-Kavallerie als Reittiere benutzt.\n\nTötet sie und bringt mir ihre Häute. Sobald wir genug Häute gesammelt haben, können wir daraus Geschirre für unsere Reiter machen. Die Frostwolfreiter werden wieder reiten!", description = nil, progress = "Während einige unserer Soldaten damit beschäftigt sind, Wölfe für den Stallmeister einzufangen, müssen andere für die einfachsten Sachen sorgen, die man beim Reiten braucht. Ich meine Geschirre, klar?\n\nIhr müsst die einheimischen Widder jagen. Genau die Widder, die die Stormpike-Kavallerie als Reittiere benutzt.\n\nTötet sie und bringt mir ihre Häute. Sobald wir genug Häute gesammelt haben, können wir daraus Geschirre für unsere Reiter machen. Die Frostwolfreiter werden wieder reiten!", completion = "Gut gemacht, Soldat. Ich werde Euch benachrichtigen, sobald wir genug Bälger eingelagert haben.\n\nWeiter so!", rewards = nil}
MultiLanguageQuestData['de'][7003] = {title = "Geschrumpfte Riesen", objective = "Benutzt Zorbins Ultraschrumpfer um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin von Schiller 15 Schrumpfüberreste von diesen Riesen. Ihr findet ihn bei den Docks, an der Vergessenen Küste in Feralas.", description = "Ich muss etwas gegen die Riesen unternehmen, wenn ich hier draußen bleibe! Sie sind sicherlich nicht gut fürs Geschäft, oder nicht?\n\nIch habe mich an einer Variante von Gnomischen Schrumpfstrahlen versucht, benutze jetzt aber überlegene GOBLIN Technologien für die Herstellung! Im Zuge von Bemühungen, Unannehmlichkeiten wie meinen Tod beispielsweise zu vermeiden, möchte ich Euch bitten es einmal an diesen Riesen in Feralas zu testen. Ihr solltet nach dem Prozess Schrumpfüberreste auf ihnen finden, bringt mir bitte etwas davon!", progress = "Schrumpf-Überreste, versichere Ich Euch, sind eine wertvolle Handelsware, was das Ingenieurswesen angeht! Nunja, es ist insofern schon wertvoll, als dass es mir hilft den Schrumpfer zu kontrollieren, sodass er nicht beim Benutzen explodiert.\n\nOh, natürlich meine ich andere Schrumpfer als den, den ich Euch gab. Natürlich ist es ein anderer!", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh,... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultra-Schrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, &lt;Name&gt;. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!", rewards = "Ihr bekommt:\n\nZorbins Megaschnitzler"}
MultiLanguageQuestData['de'][7021] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Orgrimmar befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7022] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", description = "Ich wünsche ein wunderbares Winterhauchfest! Vergesst nicht, Altvater Winter zu begrüßen! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7023] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Eisenschmiede befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien vonKokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7024] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Orgrimmar befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7025] = {title = "Leckereien für Altvater Winter", objective = "Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Eisenschmiede.", description = "He, könnt Ihr Altvater Winter einen Gefallen tun, ähm, <Kleiner/Kleines>?\n\nIch will ja nicht überflüssigerweise über mich selbst in der dritten Person sprechen, aber Altvater Winter arbeitet schon den ganzen Tag hier und könnte selbst eine kleine Leckerei brauchen. Ein paar Lebkuchen und etwas eiskalte Milch, um sie runterzuspülen, wären genau das Richtige. Glaubt Ihr, Ihr könntet dem Altvater eine Freunde machen und das für mich besorgen?", progress = "Durch diese ganze Rederei über Leckereien bin ich langsam selbst schon ganz wild darauf. Mmmm... Lebkuchen und Milch...", completion = "Ihr seid ein wahrer Helfer für den alten Altvater Winter, &lt;Name&gt;. Ich wünsche Euch ein wunderbares Winterhauchfest.\n\nHier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe.", rewards = "Ihr bekommt:\n\nKokelwälder Geschenkpackung"}
MultiLanguageQuestData['de'][7026] = {title = "Widderzaumzeug", objective = "Die Stormpikegarde kann sich nicht ohne Sättel in die Schlacht stürzen! Wir brauchen Geschirre für unsere Reittiere, schließlich sind wir keine Wilden!\n\nWir könnten zwar einfach die Widder jagen, die in der Nähe unserer Basis herumstreifen, aber das wäre idiotisch. Wenn wir aus ihrem Leder die Geschirre machen, dann haben wir keine Reittiere mehr.\n\nIhr müsst zur Basis des Feindes vorrücken und dort die Frostwölfe töten, die sie als Reittiere benutzen. Bringt mir ihre Häute, damit wir daraus die Geschirre für unsere Kavallerie fertigen können. Geht!", description = nil, progress = "Die Stormpikegarde kann sich nicht ohne Sättel in die Schlacht stürzen! Wir brauchen Geschirre für unsere Reittiere, schließlich sind wir keine Wilden!\n\nWir könnten zwar einfach die Widder jagen, die in der Nähe unserer Basis herumstreifen, aber das wäre idiotisch. Wenn wir aus ihrem Leder die Geschirre machen, dann haben wir keine Reittiere mehr.\n\nIhr müsst zur Basis des Feindes vorrücken und dort die Frostwölfe töten, die sie als Reittiere benutzen. Bringt mir ihre Häute, damit wir daraus die Geschirre für unsere Kavallerie fertigen können. Geht!", completion = "Gut gemacht, Soldat. Ich werde Euch benachrichtigen, sobald wir genug Bälger eingelagert haben.\n\nWeiter so!", rewards = nil}
MultiLanguageQuestData['de'][7027] = {title = "Verwaiste Ställe", objective = "Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Zähmungshalsband der Sturmlanzen um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.", description = "Seht Euch nur unsere Ställe an, <Name>! Völlig leer! Die Sturmlanzengarde hat keine Widder mehr, die sie reiten könnte, die Kavallerie ist praktisch nicht mehr existent.\n\nIhr müsst uns helfen, Soldat. Nehmt dieses Zähmungshalsband und begebt Euch in die Wildnis dieses Tals. Sucht in der Umgebung nach herumstreifenden Alteracwiddern und fangt sie mit dem Zähmungshalsband ein. Wenn Ihr einen Widder eingefangen habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen. Sobald wir wieder über ausreichend Widder verfügen, werde ich den Kommandanten der Widderreiter informieren.\n\nMit Eurer Hilfe wird die Kavallerie neu entstehen!", progress = "Ohne Eure Hilfe hätten die Stormpike Widderreiter jetzt keine Reittiere, um in die Schlacht zu ziehen. Ihr habt uns einen großen Dienst erwiesen!", completion = "Nicht mehr lange und die Ställe sind wieder voll! Macht weiter so!", rewards = nil}
MultiLanguageQuestData['de'][7028] = {title = "Dunkles Böses", objective = "Sammelt 15 theradrische Kristallschnitzereien für Trista in Desolace.", description = "Die Kristallhöhlen von Terramok liegen im Westen, tief in Maraudon... Das ist ein uralter Ort mit einer langen Geschichte. Und ich will einiges davon in die Hände bekommen, <Klasse>. Relikte der Alten Götter liegen hinter den riesigen Türen verborgen.\n\nWenn Ihr bereit seid, dem dunklen Bösen zu trotzen, das sich in Maraudon findet, wird es Euer Schade bestimmt nicht sein. Sammelt die theradrischen Kristallschnitzereien ein, die Ihr aufstöbern könnt, und bringt sie mir.\n\nSobald ich die Schnitzereien habe, kann ich sie... studieren. Diese Mächte haben schon zu lange geruht...", progress = "Stellt keine Fragen!\n\nIhr wisst, was ich will.", completion = "Ha ha ha! Ich wusste, Ihr würdet zurückkehren.\n\n&lt;Willow murmelt vor sich hin.&gt;\n\n... So leicht zu überzeugen.\n\n... Würde alles tun, solange der Preis stimmt. Hi, hi, hi…", rewards = "Roben des ScharfsinnsRüstringhelmUnerbittliche KetteSchulterstücke des SteinkolossesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7029] = {title = "Schlangenzunges Verderbnis", objective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Vark Schlachtnarbe in Schattenflucht zurück.", description = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, <Name>. Füllt sie am orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, <Name>...", completion = "Danke, dass Ihr das zurückgebracht habt, &lt;Name&gt;. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an.", rewards = "AstkrallenstulpenWeisenblattgurtAuf Euch wartet eine dieser Belohnungen:\n\nRing der Waldsaat\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7041] = {title = "Schlangenzunges Verderbnis", objective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Talendria an der Nijelspitze zurück.", description = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, <Name>. Füllt sie am verderbten orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, <Name>...", completion = "Danke, dass Ihr das zurückgebracht habt, &lt;Name&gt;. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an.", rewards = "AstkrallenstulpenWeisenblattgurtAuf Euch wartet eine dieser Belohnungen:\n\nRing der Waldsaat\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7042] = {title = "Gestohlene Winterhauchleckereien", objective = "Sucht den Ermittler von Kokelwälder, der in den verschneiten Regionen des Vorgebirges des Hügellands vermisst wird.", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen - von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhandengekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, das an das Vorgebirge des Hügellands angrenzt und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", progress = nil, completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Ironforge. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7043] = {title = "So was Gemeines...", objective = "Sucht die gestohlenen Leckereien und befreit Metzen das Rentier, nachdem Ihr den monströsen Griesgram besiegt habt. Er verbirgt sich nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", description = "Eine Kreatur namens \"Der monströse Griesgram\" hat unsere Lieferung mit Leckereien gestohlen, <Name>. Seid aber vorsichtig! Er ist bösartig und befiehlt über ein paar dieser kleinen grünen Gnome!\n\nIhr werdet Hilfe brauchen, wenn Ihr ihm gegenübertretet. Ich habe gehört, dass er unsere Leckereien und Metzen, unser geliebtes Rentier, in die Eisfellhöhle im Vorgebirge des Hügellandes gebracht hat. Findet die Leckereien, <Name>, und bringt sie zurück, bevor das Fest ruiniert ist und all die Kinder von Sturmwind enttäuscht werden!", progress = "<Name> - unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt es gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nKokelwälder verehrt Euch dafür und natürlich auch all die Kinder!", rewards = "Ihr bekommt:\n\nGestohlenes GeschenkGestohlenes Geschenk"}
MultiLanguageQuestData['de'][7044] = {title = "Legenden von Maraudon", objective = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\n\nFindet einen Weg, um mit Celebras zu sprechen.", description = "Ein dunkler Satyr namens Lord Schlangenzunge hat sein Böses in diesen verschlungenen Höhlen verbreitet und die Gedanken aller im Inneren vergiftet. Er residiert noch jenseits der lila Kristalle.\n\nSchlangenzunge hat des Weiteren ein lebendes Symbol seiner Verderbnis namens Noxxion geschaffen, das sich hinter den orangefarbenen Kristallen befindet. Zusammen haben sie die beiden Teile des Szepters meines Bruders gestohlen. Celebras, mein Bruder... wandert blind im Inneren umher, verflucht durch die Verderbnis.\n\nIhr müsst ihm helfen! Findet die Stücke und sprecht mit meinem Bruder...irgendwie.", progress = "Ich bin aus einem Alptraum erwacht, der niemals enden wollte...", completion = "Da Ihr nun die beiden Teile meines Szepters zurückgeholt habt, hoffe ich, dass Maraudon eines Tages von der Vyle-Verderbnis befreit ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7045] = {title = "Ein Dankeschön von Kokelwälder!", objective = "Sprecht mit Altvater Winter in Eisenschmiede.", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, <Name>. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost... dank Euch natürlich!", progress = nil, completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", rewards = "Ihr bekommt:\n\nKokelwälder Spezialgeschenk"}
MultiLanguageQuestData['de'][7046] = {title = "Das Szepter von Celebras", objective = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\n\nSprecht mit ihm, nachdem das Ritual vollendet ist.", description = "Mein Szepter war einst eine Quelle der Hoffnung für mich. Es gewährte mir einst die Macht über diese Höhlen. Ich hatte gehofft, dem Geist meines Onkels Frieden bringen zu können...\n\nDamit die beiden Teile wieder eins werden können, benötige ich Eure Hilfe bei der Durchführung des Rituals. Folgt mir bitte und hört auf meine Anweisungen, während ich die Energie kanalisiere, die erforderlich ist, um den Griff wieder mit dem Diamanten zu vereinigen.\n\nZusammen werden wir das Szepter von Celebras wieder erschaffen!", progress = nil, completion = "Bitte nehmt dies und wisset, dass die Macht, die Euch zugeteilt wurde, nur genutzt werden darf, um Gutes zu tun. Setzt Eure Reise durch diese Höhlen fort, und vielleicht werdet Ihr die Überreste meines Onkels finden. Große Gefahren liegen vor Euch, &lt;Name&gt;.\n\nSprecht erneut mit mir, falls es nötig ist.", rewards = "Ihr bekommt:\n\nSzepter von Celebras"}
MultiLanguageQuestData['de'][7061] = {title = "Das Winterhauchfest", objective = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Baine Bluthuf in Donnerfels.", description = "Hier - wenn Ihr daran interessiert seid, mehr über das Winterhauchfest zu erfahren, dann lest dieses Buch. Ich glaube zwar, dass unser Verständnis der Legende zutreffend ist, aber als jemand, der Legenden studiert, weiß ich durchaus eine Sammlung aller Informationen in einer einzelnen Quelle zu schätzen.\n\nWenn Ihr fertig seid, bringt das Buch zu Baine Bluthuf in Donnerfels. Ich weiß mit Bestimmtheit, dass es ihm nicht gleichgültig ist, wenn auch andere sich für die Lehre unseres Volkes interessieren.", progress = "Ich heiße Euch in Mulgore und unserem bescheidenen Gemeinwesen Thunder Bluff willkommen. Ich interessiere mich immer für Leute, die Interesse für die Belange des Königreichs und seine Lehre zeigen. Steht Ihr aus diesem Grund vor mir?", completion = "Die Legenden und die Lehre, die das Winterhauchfest umgeben, sind im Lauf der Jahre bei den Leuten in den Hintergrund gerückt. Ja, ich weiß, dass die Goblins aus recht eigennützigen Motiven dazu beitragen, die Feiertage wiederzubeleben, aber die Tatsache, dass sich unser Volk zumindest auf eine Art damit beschäftigt, hilft, diese Lehre am Leben zu erhalten.\n\nEuer Wunsch, hinter das Materielle zu sehen und mehr über unsere Vergangenheit zu erfahren, ist ein bewundernswerter Zug, &lt;Klasse&gt;. Ich verbeuge mich vor Eurer Weisheit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7062] = {title = "Der Anlass für die Feiertage", objective = "Sprecht mit dem Historiker Karnik in der Forscherliga von Eisenschmiede über das Winterhauchfest.", description = "Gaben, Leckereien, Geschenke, pah!\n\nDiese Goblins beschmutzen die wahre Bedeutung dieser Feiertage - des Winterhauchfests. Dies ist eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die Altvater Winter gebracht hat, und das ist NICHT der Wichtigtuer da drüben in dem roten Aufzug!\n\nFalls Ihr erfahren wollt, worum es bei dem Fest wirklich geht, dann befragt den Historiker Karnik in der Forscherliga. Es dürfte ihn bestimmt überraschen, dass sich jemand für Geschichte statt für Geschenke interessiert.", progress = nil, completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Zwerge eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende von Altvater Winter zu einer verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Goli diese Veränderung bitter aufstößt. Er und andere Zwerge wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7063] = {title = "Das Winterhauchfest", objective = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, dann bringt es zu Muradin Bronzebart nach Eisenschmiede.", description = "Hier - wenn Ihr daran interessiert seid, mehr über das Winterhauchfest zu erfahren, dann lest dieses Buch. Ich glaube zwar, dass unser Verständnis der Legende zutreffend ist, aber als Gelehrter, der Legenden studiert, weiß ich durchaus eine Sammlung aller Informationen in einer einzelnen Quelle zu schätzen.\n\nWenn Ihr fertig seid, dann bringt das Buch zu Muradin Bronzebart. Ich weiß mit Bestimmtheit, dass es ihn sehr interessieren wird, wenn auch andere Interesse für die alten Legenden an den Tag legen.", progress = "Ich heiße Euch im Königreich Ironforge willkommen. Ich interessiere mich immer für Leute, die Interesse für die Belange des Königreichs und seine Lehre zeigen. Steht Ihr aus diesem Grund vor mir?", completion = "Die Legenden und die Lehre, die das Winterhauchfest umgeben, sind im Lauf der Jahre bei den Leuten in den Hintergrund gerückt. Mir ist durchaus bewusst, dass die Goblins, wenn auch aus recht eigennützigen Motiven, dazu beitragen, die Feiertage wiederzubeleben, aber die Tatsache, dass sich unsere Bevölkerung zumindest auf eine gewisse Art mit dieser Lehre beschäftigt, hilft, sie lebendig zu erhalten.\n\nEuer Wunsch, hinter das Materielle zu sehen und mehr über unsere Vergangenheit zu erfahren, ist ein bewundernswerter Zug, &lt;Klasse&gt;. Ich verneige mich vor Eurem gelehrten Wesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7064] = {title = "Verderbnis von Erde und Samenkorn", objective = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Schattenflucht in Desolace zurück.", description = "Tief in Maraudon lebt eine böse Kreatur des Chaos - Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den Alten Göttern verwandt ist. Vor langer Zeit gingen sie und Zaetar, der erstgeborene Sohn von Cenarius, eine Beziehung ein. Aus ihrer gemeinsamen Zeit entsprangen Wesen, die unter den Menschen von Kalimdor als Zentauren bekannt wurden. Diese undankbaren Kreaturen töteten Zaetar und bewachen nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", progress = nil, completion = "Das sind wirklich ganz wunderbare Nachrichten, &lt;Name&gt;! Danke!\n\nIch werde mit Marandis sprechen und um sein Wissen zum Thema Zaetars Überreste bitten, aber zumindest habt Ihr die schwierigste der Aufgaben bereits bewältigt.\n\nMir wurde gesagt, dass ich diejenigen belohnen darf, die uns geholfen haben, wenn wir bei unserer Mission erfolgreich sein sollten. Als Geschenk unseres Volkes habe ich diese Gegenstände erhalten - wählt einen davon.", rewards = "HauklingeRute der WiederauferstehungZiel des tiefgrünen BewahrersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7065] = {title = "Verderbnis von Erde und Samenkorn", objective = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.", description = "In den Tiefen von Maraudon lebt eine Kreatur des Chaos und des Bösen, <Name>. Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den Alten Göttern verwandt ist. Vor langer Zeit stattete Zaetar, der erstgeborene Sohn von Cenarius, ihr einen Besuch ab. Die Nachkommen ihrer...Beziehung sind jene Kreaturen, die unter dem Namen Zentauren bekannt sind. Diese undankbaren Kreaturen töteten Zaetar und Theradras bewacht nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", progress = nil, completion = "Das sind wirklich ganz wunderbare Nachrichten, &lt;Name&gt;! Danke!\n\nEs beunruhigt mich zwar, dass Ihr die Überreste von Zaetar nicht zurückbringen konntet, aber wer bin ich, dass ich den Willen des Erstgeborenen von Cenarius in Frage stelle? Vielleicht wird der Wille der Zentauren nun brechen und ihr Blutdurst versiegen - wir können es nur hoffen.\n\nFür den Fall, dass unsere Mission von Erfolg gekrönt sein sollte, habe ich diese Gegenstände erhalten, um jene zu belohnen, die uns halfen. Ihr dürft einen dieser Gegenstände als Zeichen der Dankbarkeit wählen.", rewards = "HauklingeRute der WiederauferstehungZiel des tiefgrünen BewahrersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7066] = {title = "Samenkorn des Lebens", objective = "Sucht Remulos bei der Mondlichtung auf und gebt ihm das Samenkorn des Lebens.", description = "Diese missratenen Zentauren - meine Söhne und Töchter - brauchen ihren Vater.\n\nSeht Euch um - dieser Ort hallt wider von Hoffnung und all jenem, was mein Vater Cenarius predigt. All das entsprang aus mir! Und ich kann ihnen das nicht nehmen... nicht einmal ob ihrer Verbrechen gegen mich.\n\nEines jedoch möchte ich von Euch erbitten, damit mein Bruder Ruhe findet. Nehmt dies... es ist das erste Samenkorn, das aus dem Leben entstand, das meine Überreste nährten. Sagt ihm, dass mein Geist hier bleibt und dass ich weiterlebe. Er wird es sicherlich verstehen.", progress = "Euch haftet der Geruch der Verderbnis an, <Name>... wie so vielen Abenteurern in diesen Tagen. Aber etwas an Euch ist anders. Gibt es etwas, über das Ihr mit mir sprechen wollt? Ihr seid von einer Aura umgeben, die vertraut scheint, aber ich kann sie nicht einordnen.\n\nBitte, ich flehe Euch an, sagt mir, warum Ihr mich sehen wolltet.", completion = "Mein Bruder hat also endlich seinen Frieden gefunden? Ich bin stolz, dass ich diesen Tag erleben darf. In seiner ganzen Arroganz und seiner Wut dachte ich wahrlich, er wäre für uns verloren, aber dieses... dieses Symbol seines Opfers beweist eindeutig, dass er nicht verloren ist - er wurde nur neu geboren. Er nimmt seinen Platz in der Natur ein, wie es seine Pflicht war.\n\nIch danke Euch, &lt;Name&gt;. Indem Ihr mir dies brachtet, habt Ihr mir ein wenig Hoffnung geschenkt, die ich schon für vergeblich hielt. Dieses Samenkorn wird für die Menschen in diesem vom Krieg zerrissenen Land eines Tages wichtig sein... Das kann ich spüren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7067] = {title = "Die Anweisungen des Pariahs", objective = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace.", description = "Obwohl ich als Ketzer verbannt wurde, bleibe ich meinem Glauben treu - das allein treibt mich voran. Aber damit mein Schicksal sich erfüllt, benötige ich die Hilfe eines Außenstehenden... jemanden, der keinem Zentaurenstamm angehört.\n\nFür diese Aufgabe muss jemand die heiligen Hallen von Maraudon betreten - das ist ein Tempel, den mein Volk schützt, und nur die Gläubigsten dürfen ihn betreten.\n\nWenn Ihr einwilligt, mir zu helfen, dann müsst Ihr nur nicken. Ich werde Euch ein Pergament mit meinen Anweisungen geben. Lest es durch und denkt über meine Worte nach.", progress = "Wie habt Ihr Euch entschieden, <Name>? Könntet Ihr mir helfen? Werdet Ihr Euren Fuß auf heiligen Boden setzen, um mir zu helfen, einen großen Zentaurenstamm zu schmieden!?", completion = "Das ist es, &lt;Volk&gt;! Das ist es! Jetzt kann ich die große Aufgabe der Vereinigung der Stämme angehen. Seid bedankt.\n\nNehmt bitte dies für Eure Bemühungen. Ich hoffe, dass über unserem nächsten Treffen ein glücklicherer Stern stehen wird.", rewards = "Ihr bekommt:\n\nMal der Auserwählten"}
MultiLanguageQuestData['de'][7068] = {title = "Schattensplitter", objective = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar.", description = "Man findet starke Magie am heiligen Ort der Zentauren... dem heiligen Ort von Maraudon. Die Desolace-Stämme der Zentauren schützen diesen Ort mit ihrem Leben, aber sie können uns nicht davon abhalten, das zu nehmen, was wir brauchen.\n\nBegebt Euch zu diesem Maraudon-Ort und sucht nach den Felskreaturen, die aus Schattenstein bestehen. Bringt mir die lila Kristalle und Uthel'nay wird Euch Eure Mühe vergelten.\n\nDer Ort ist gefährlich, daher solltet Ihr einige Freunde mitnehmen.", progress = "Habt Ihr die Kristalle schon gefunden? Rituale der Macht, Zauber von großer Kraft - diese Schattensplitter könnten bei allen Arten arkaner Magie hilfreich sein.", completion = "Ah, diese sind perfekt für meine Magie. Hier, nehmt eines dieser Schmuckstücke und macht Euch auf den Weg... ich habe hier viel zu tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchattensplitteranhänger des EifersVorwarnender Schattensplitteranhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7070] = {title = "Schattensplitter", objective = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Düstermarschen.", description = "Ich habe kürzlich begonnen, verschiedene Kristalle und ihre arkanen Eigenschaften zu testen. Lady Prachtmeer hat mir die Erlaubnis erteilt, Reisende, die nach Desolace ziehen, zu bitten, einen Ort zu suchen, der Maraudon genannt wird. In dem zerfallenen Tempel dort gibt es große Elementare, die aus lila Steinen bestehen. Ich habe sie Schattensplitter getauft.\n\nFalls Ihr beschließt, diese Richtung einzuschlagen, und dort einige dieser Kristalle findet, wäre ich sehr dankbar. Ich würde Euch sogar ein Schmuckstück daraus herstellen, wenn Ihr dies wünscht.", progress = "Habt Ihr die Reise schon unternommen? Ich weiß, dass es recht gefährlich ist, aber wenn Ihr Erfolg habt, soll es Euer Schaden nicht sein.", completion = "Die sind perfekt, &lt;Name&gt;. Es sind bereits andere Abenteurer von dort zurückgekehrt, und dadurch konnte ich dies herstellen... bitte, nehmt eines der Stücke für Eure harte Arbeit. Und ich danke Euch nochmals, dass Ihr mir weitere Proben für meine Studien besorgt habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchattensplitteranhänger des EifersVorwarnender Schattensplitteranhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7081] = {title = "Die Friedhöfe im Alteractal", objective = "Erobert einen Friedhof und kehrt zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", description = "Die Friedhöfe im Alteractal sind äußerst wertvolle Gebiete. Beide Seiten, die Horde und die Allianz, kämpfen verbissen um diese geheiligten Stätten. <Name>, seid Ihr bereit die Kämpfe zu unterstützen?\n\nIch möchte, dass Ihr einen gegnerischen Friedhof besetzt. Sucht einen Friedhof mit einem Banner der Horde in seiner Mitte und reißt es heraus! Wenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es schaffen, den Friedhof für einige Minuten zu halten, werden unsere Verstärkungstruppen eintreffen, um Euch bei der Verteidigung zu unterstützen.", progress = "<Name>, Ihr habt noch keinen Friedhof erobert. Kommt zu mir zurück, wenn Ihr Erfolg hattet.", completion = "Gute Arbeit! Friedhöfe sind lebenswichtig für unseren Einfluß im Alteractal. Mit jedem Friedhof den Ihr erobert, helft Ihr der Allianz dabei, ihre Herrschaft im Tal zu sichern. \n\nGeht nun, &lt;Name&gt;.  Zieht wieder in die Schlacht, und falls Ihr einen von der Horde besetzten Friedhof seht... Ihr wißt ja was zu tun ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7082] = {title = "Die Friedhöfe von Alterac", objective = "Erobert einen Friedhof und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück.", description = "Die Frontlinien in diesem Tal sind in ständiger Bewegung. Die Gebietsgrenzen bewegen sich hin und her, während wir unseren Feinden in tödlichen Schlachten gegenüber treten. Doch um die Friedhöfe, <Name>, wird am grimmigsten gekämpft.\n\nIch möchte, dass Ihr einen von der Allianz besetzten Friedhof angreift! Sucht einen Friedhof mit einem Banner der Allianz in seiner Mitte und reißt es aus dem Boden.\n\nWenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es außerdem schaffen, den Friedhof für einige Minuten zu halten, wird dieser uns gehören und unsere Truppen werden kommen, um Euch bei der Verteidigung dieser wichtigen Position zu unterstützen.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Mit jedem weiteren Friedhof den wir kontrollieren, wandern die Geister unserer Feinde mehr und mehr verloren und ziellos herum.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7101] = {title = "Türme und Bunker", objective = "Erobert einen gegnerischen Turm und kehrt anschließend zu Korporal Teeka Murrblut im Alteracgebirge zurück.", description = "Die Türme und Bunker in diesem Tal sind wichtige Stellungen und daher müssen wir sie möglichst alle erobern und halten! Genug geredet... Erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Banner der Allianz. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Banner der Horde wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Allianz es zurückgewinnt, gehört es uns!", progress = nil, completion = "Ich habe von Eurer erfolgreichen Mission gehört! So gefällt mir das...\n\nunsere Truppen nun ungehindert die feindlichen Stellungen stürmen. Bald werden diese Schwächlinge einsehen das, dass Alteractal kein Ort für sie ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7102] = {title = "Türme und Bunker", objective = "Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", description = "Die Türme und Bunker in diesem Tal sind Schlüsselverteidigungspositionen und daher sollten wir so viele wie möglich davon unter Kontrolle halten! Geht und erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Banner der Horde. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Banner der Allianz wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Horde es zurückgewinnt, gehört es uns!", progress = nil, completion = "Ich habe eine Feldnachricht erhalten, nach der Ihr dabei geholfen habt ein feindliches Banner zu sichern. Gute Arbeit, &lt;Name&gt;! Nach der Vernichtung der feindlichen Schützen können wir weiter ins Feindesland vordringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7121] = {title = "Der Rüstmeister", objective = "Sprecht mit dem Rüstmeister der Sturmlanzen.", description = "<Name>, unser Rüstmeister hat mich angewiesen, die neuen Rekruten direkt zu ihm zu schicken. Er benötigt dringend Vorräte aus Kisten, die in den Minen von Alterac eingelagert sind und aller Wahrscheinlichkeit nach wird er Euch entsenden, um sie zu beschaffen.\n\nFolgt einfach der Straße. Ihr findet den Rüstmeister im Westen.", progress = nil, completion = "Ah, endlich sind frische Truppen eingetroffen, &lt;Name&gt;. Mit etwas Glück könnt Ihr hier schnell was erleben und an Erfahrung gewinnen!\n\nSprecht noch einmal mit mir! Ich habe da ein paar Aufgaben, die ich gerne mit Euch besprechen würde....", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7122] = {title = "Eine Mine erobern", objective = "Erobert eine Mine, die die Sturmlanzen noch nicht kontrollieren, und kehrt dann zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", description = "In den Minen des Alteractals ist noch weit mehr zu finden als bloßes Erz. Sowohl die Frostwölfe, als auch die Sturmlanzen, haben große Mengen ihrer Ausrüstung in der Eisenschacht- und der Eisbeißermine untergebracht... was eigentlich keine schlechte Idee ist, solange wir die Kontrolle über sie behalten!\n\nBesetzt eine Mine und kehrt zu mir zurück! Um eine Mine zu erobern, betretet eine vom Feind kontrollierte Mine und tötet den dortigen Anführer. Nachdem Ihr das getan habt, gehört die Mine uns und wir werden Truppen zu ihrem Schutz entsenden!", progress = nil, completion = "Ihr habt es geschafft! Gut gemacht, &lt;Name&gt;!\n\nWenn wir erstmal eine Mine kontrollieren und dort Truppen stationiert haben, wird es viel einfacher die dortige Ausrüstung und Mineralien einzusammeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7123] = {title = "Sprecht mit unserem Rüstmeister", objective = "Sprecht mit dem Rüstmeister der Frostwölfe.", description = "<Name>, der Rüstmeister der Frostwölfe sucht nach Lehrlingen für Aufgaben, die in die Minen des Tals von Alterac führen. Sprecht mit ihm; er wird Euch mehr berichten.\n\nFolgt der Straße westlich in den Bunker, dann nehmt den westlichen Ausgang und Ihr findet unseren Rüstmeister.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;! Es ist immer wieder eine Freude, einen &lt;Klasse&gt; wie Euch zu treffen, der bereit ist, seinen Beitrag für die Horde zu leisten. Sprecht also noch einmal mit mir. Ich habe äußerst wichtige Aufgaben für Euch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7124] = {title = "Eine Mine erobern", objective = "Erobert eine Mine und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück.", description = "So wie Kämpfe im Gebiet des Alteractals wüten, so wüten sie auch durch die Eisbeißer- und Eisenschachtminen. Beide bedeuten enorme Ressourcen an Mineralien und beide werden als Lager genutzt; daher ist es kein Wunder, dass sie so heiß begehrt sind!\n\nHelft uns in der Schlacht, <Name>! Erobert für die Horde eine Mine! Begebt Euch zu einer Mine, die noch nicht von uns kontrolliert wird und tötet den dortigen Anführer! Sobald Ihr das geschafft habt, schicken wir Truppen aus, um die Mine zu bewachen!", progress = nil, completion = "Ihr habt eine Mine erobert! Jetzt wo unsere Krieger die Mine vor Angriffen beschützen, wird es uns viel leichter fallen dort Mineralien abzubauen und die dort eingelagerten Vorräte zu bergen.\n\nHervorragende Arbeit, &lt;Name&gt;. Diese Tat ist ein großer Gewinn für unsere Kriegsanstrengungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7141] = {title = "Die Schlacht um Alterac", objective = "Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Steinhauer im Alteracgebirge zurück.", description = "Die Forscherliga glaubt, dass es im Alteractal einige Artefakte von Interesse gibt. Allerdings werden uns die Orcs des Frostwolfklans wohl kaum danach forschen lassen. Wir können es der Horde jedoch nicht erlauben, unseren Forschungsbemühungen im Weg zu stehen! Vernichtet den General der Frostwölfe, Drek'Thar. Mit seinem Tod werden die Orcs ihren Vorteil verlieren.\n\nDrek'Thar hält sich in der Burg Frostwolf auf, im Süden des Alteractals. Bezwingt ihn und kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Jetzt wo die Horde sich mit den Tod Ihres Generals eine blutige Nase geholt hat, haben wir die Atempause, die wir für unsere Forschungsarbeiten brauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7142] = {title = "Die Schlacht ums Alteractal", objective = "Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Sturmlanze. Kehrt anschließend zu Voggah Todesgriff im Alteracgebirge zurück.", description = "Die Sturmlanzenzwerge und ihre Verbündeten sind in das Alteractal eingefallen und wir müssen sie vertreiben! Um die Schlacht ums Alteractal gewinnen zu können, müssen wir ihren General töten, Vanndar Sturmlanze!\n\nIhr werdet Vanndar in Dun Baldar, im Norden des Alteractals finden.\n\nTötet ihn, <Name>, und kehrt dann zu mir zurück.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Die Stormpikes haben ihre närrische Invasion bereits verloren.\n\nHah! Das Einzige was sie bisher erreicht haben, ist ihr toter General!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7161] = {title = "Flaggenjagd", objective = "Begebt Euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt im Alteractal und findet das Banner der Frostwölfe. Bringt anschließend Kriegsmeister Laggrond das Banner.", description = "Seid gegrüßt, <Klasse>. Es scheint eine Ewigkeit her, seit wir zuletzt dem Ruf des Krieges gefolgt sind. Die alten Gefühle erwachen nur langsam. Doch sind sie erst einmal erwacht, beginnt das Blut erneut zu kochen. Die Kampfeslust kehrt zurück...\n\nAlle Neuankömmlinge im Tal müssen sich zuerst dem Ritus des Kampfes unterziehen.\n\nTief in der nahegelegenen Höhle der Wildpfoten findet Ihr ein Banner der Frostwölfe. Zieht los und holt es für uns zurück. Bringt es zu mir und ich gewähre Euch das Abzeichen eines Initianden der Frostwölfe.", progress = "Wacht auf! Wacht endlich auf, <Name>! Dies ist kein Traum. Ihr befindet euch tatsächlich inmitten einer tobenden Schlacht!", completion = "Das brennende Gefühl in Euch ist Eure Seele, die langsam erwacht! Euer Geist hat den Ruf zu den Waffen akzeptiert!\n\nIhr gehört nun zu den Frostwolf, &lt;Name&gt;. Ich gratuliere.\n\nTragt dieses Abzeichen immer bei Euch. Mit der Zeit werdet Ihr in den Rängen der Frostwolf aufsteigen und ich werde Euer Abzeichen gegen andere, ranghöhere Abzeichen eintauschen.\n\nVielleicht wird man Euch eines Tages, innerhalb des Frostwolfklans mit Ehrfurcht begegnen. Sollte dieser Tag jemals kommen, werdet Ihr möglicherweise sogar das Auge der Führung erhalten.", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwölfe Rang 1Schrittweise zum Sieg"}
MultiLanguageQuestData['de'][7162] = {title = "Flaggenjagd", objective = "Begebt Euch in die Eisschwingenhöhle südwestlich von Dun Baldar im Alteractal und findet das Banner der Sturmlanzen. Bringt anschließend Leutnant Haggerdin im Alteracgebirge das Banner.", description = "Ihr seid genau zur rechten Zeit eingetroffen, <Klasse>. Diese Wilden der Frostwölfe wollen einfach nicht aufgeben! Wir müssen ihnen die Macht der Sturmlanzen vor Augen führen! Am Ende müssen sie sich unserer Überlegenheit beugen.\n\nDoch bevor Ihr Euch auf das Schlachtfeld begebt, solltet Ihr den Reihen der Sturmlanzen beitreten.\n\nSüdwestlich von Dun Baldar befinden sich die Eisschwingenhöhlen. Tief in ihrem Inneren werdet Ihr ein Banner der Sturmlanzen finden. Begebt Euch dorthin und holt das Banner zurück. Bringt es anschließend zu mir und ich werde Euch mit dem Abzeichen eines Initianden der Sturmlanzen auszeichnen.", progress = "Hütet Euch vor den Harpyien in der Gegend, <Klasse>. Die werden nicht zögern Euch die Kehle herauszureissen!", completion = "Nehmt dieses Abzeichen und tragt es mit Stolz, &lt;Name&gt;. Mit der Zeit werdet Ihr in den Rängen der Stormpikegarde aufsteigen. Kehrt dann zu mir zurück und ich werde Euer Abzeichen gegen andere, ranghöhere Abzeichen eintauschen.\n\nVielleicht werdet Ihr eines Tages zu einer Legende dieses Schlachtfeldes heranwachsen. Sollte dieser Tag jemals kommen, wird man Euch mit Sicherheit das Auge der Führung verleihen.", rewards = "Ihr bekommt:\n\nAbzeichen der Sturmlanzen Rang 1Frostwölfe abserviert"}
MultiLanguageQuestData['de'][7163] = {title = "Aufstieg und Anerkennung", objective = "<Kriegsmeister Laggrond salutiert vor Euch.>\n\nJetzt ist eure Zeit gekommen, <Name>. Ihr habt viel für den Frostwolfklan getan und habt Euch dabei nicht nur als ein Soldat der Frostwolf, sondern auch als Freund bewiesen. \n\nGut gemacht! Zeigt mir Euer Abzeichen!", description = nil, progress = "<Kriegsmeister Laggrond salutiert vor Euch.>\n\nJetzt ist eure Zeit gekommen, <Name>. Ihr habt viel für den Frostwolfklan getan und habt Euch dabei nicht nur als ein Soldat der Frostwolf, sondern auch als Freund bewiesen. \n\nGut gemacht! Zeigt mir Euer Abzeichen!", completion = "Dieses neue Abzeichen zeigt Euren Rang bei den Frostwolf. Tragt es immer bei Euch\n\nUnd &lt;Klasse&gt;... Sterbt mit Ehre.", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwölfe Rang 2"}
MultiLanguageQuestData['de'][7164] = {title = "Ehre innerhalb des Klans", objective = "Es ist gut, Euch wiederzusehen, <Klasse>. Ich hatte nicht erwartet, dass Ihr zurückkehren würdet. Ihr habt Euch als tapferer und ehrbarer Soldat der Frostwolf erwiesen.\n\nWieder ist eure Zeit gekommen, <Name>. Ihr hab einen neuen Rang verdient und damit auch ein neues Abzeichen, das diesen Aufstieg anzeigt.\n\nZeigt mir euer Abzeichen!", description = nil, progress = "Es ist gut, Euch wiederzusehen, <Klasse>. Ich hatte nicht erwartet, dass Ihr zurückkehren würdet. Ihr habt Euch als tapferer und ehrbarer Soldat der Frostwolf erwiesen.\n\nWieder ist eure Zeit gekommen, <Name>. Ihr hab einen neuen Rang verdient und damit auch ein neues Abzeichen, das diesen Aufstieg anzeigt.\n\nZeigt mir euer Abzeichen!", completion = "&lt;Kriegsmeister Laggrond salutiert.&gt;\n\nGeht, &lt;Name&gt;! Setzt Eure Verteidigung der Frostwolf fort. Dieser Krieg muss gewonnen werden! Für Drek'Thar! Für den Kriegshäuptling!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwölfe Rang 3"}
MultiLanguageQuestData['de'][7165] = {title = "Verdiente Ehrerbietung", objective = "So viele Gefallene. Blut tränkt die Felder. Aber... Ihr lebt... Ihr habt durchgehalten. Ihr habt unsere Armee zu vielen Siegen geführt. Dafür, Soldat, habt Ihr einen neuen Rang verdient..\n\nZeigt mir euer Abzeichen!", description = nil, progress = "So viele Gefallene. Blut tränkt die Felder. Aber... Ihr lebt... Ihr habt durchgehalten. Ihr habt unsere Armee zu vielen Siegen geführt. Dafür, Soldat, habt Ihr einen neuen Rang verdient..\n\nZeigt mir euer Abzeichen!", completion = "&lt;Kriegsmeister Laggrond Brüllt.&gt;\n\nSie haben schon angefangen, Geschichten über Eure Taten zu erzählen, Soldat. Die Stormpikes zittern vor Angst, wenn man euren Namen ausspricht. Weiter so!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwölfe Rang 4"}
MultiLanguageQuestData['de'][7166] = {title = "Legendäre Helden", objective = "Ihr strahlt Macht und Befehlsgewalt aus, <Klasse>. Erhaben in den Augen der Frostwolf - der Feind duckt sich, wenn Euer Name genannt wird.\n\nErhebt Euch, Held der Frostwolf. Erhebt Euch und lasst Euch ehren!\n\nZeigt mir euer Abzeichen!", description = nil, progress = "Ihr strahlt Macht und Befehlsgewalt aus, <Klasse>. Erhaben in den Augen der Frostwolf - der Feind duckt sich, wenn Euer Name genannt wird.\n\nErhebt Euch, Held der Frostwolf. Erhebt Euch und lasst Euch ehren!\n\nZeigt mir euer Abzeichen!", completion = "Schon bald wird das ganze Schlachtfeld unter eurem wachsamen Auge liegen. Die Führung über das Tal und seine Truppen wird Euer sein!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwölfe Rang 5"}
MultiLanguageQuestData['de'][7167] = {title = "Das Auge der Führung", objective = "Drek'Thar singt Euch zu Ehren Heldenweisen und in ganz Kalimdor erzählt man sich von Euren Heldentaten. Der Kriegshäuptling blickt stolz auf Euch herab - Eure unerschütterliche Verteidigung unseres Klans hat ihn tief berührt.\n\nIhr habt Euch das Auge der Führung redlich verdient.\n\nPräsentiert Eure Abzeichen, Kommandant <Name>.", description = nil, progress = "Drek'Thar singt Euch zu Ehren Heldenweisen und in ganz Kalimdor erzählt man sich von Euren Heldentaten. Der Kriegshäuptling blickt stolz auf Euch herab - Eure unerschütterliche Verteidigung unseres Klans hat ihn tief berührt.\n\nIhr habt Euch das Auge der Führung redlich verdient.\n\nPräsentiert Eure Abzeichen, Kommandant <Name>.", completion = "Sammelt die Kraft dieser Auszeichnung. Lasst unsere Feinde Eure Worte hören. Die Macht der Horde ist und bleibt unantastbar!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwölfe Rang 6"}
MultiLanguageQuestData['de'][7168] = {title = "Aufstieg und Anerkennung", objective = "Die Meisten leben nicht lange genug um sich aus ihrer eigenen Mittelmäßigkeit zu erheben. Ihr habt euch als ein mustergültiger Soldat erwiesen, <Klasse>. Die Zeit ist da!\n\nPräsentiert Euer Abzeichen!", description = nil, progress = "Die Meisten leben nicht lange genug um sich aus ihrer eigenen Mittelmäßigkeit zu erheben. Ihr habt euch als ein mustergültiger Soldat erwiesen, <Klasse>. Die Zeit ist da!\n\nPräsentiert Euer Abzeichen!", completion = "Lasst unsere Feinde sehen, dass ein angesehener Soldat sie besiegt hat! Kämpft für den Ruhm der Stormpike!", rewards = "Ihr bekommt:\n\nAbzeichen der Sturmlanzen Rang 2"}
MultiLanguageQuestData['de'][7169] = {title = "Ehre innerhalb der Garde", objective = "Die ganze Basis spricht von Euren Taten auf dem Feld der Ehre! Ihr habt dem Feind schwere Treffer zugefügt und ihre Moral zerschmettert! Dafür habt Ihr einen Ehrenplatz unter den Stormpike verdient\n\nPräsentiert Euer Abzeichen!", description = nil, progress = "Die ganze Basis spricht von Euren Taten auf dem Feld der Ehre! Ihr habt dem Feind schwere Treffer zugefügt und ihre Moral zerschmettert! Dafür habt Ihr einen Ehrenplatz unter den Stormpike verdient\n\nPräsentiert Euer Abzeichen!", completion = "Der König hat von Euren Heldentaten an der Frontlinie gehört, &lt;Klasse&gt;. Macht weiter so in Eurer wackeren Verteidigung der Stormpikegarde!", rewards = "Ihr bekommt:\n\nAbzeichen der Sturmlanzen Rang 3"}
MultiLanguageQuestData['de'][7170] = {title = "Verdiente Ehrerbietung", objective = "Ich muss es wissen, <Name>. Wenn Ihr dem Feind direkt ins Auge blickt, seht Ihr dort Furcht? Ducken sie sich in Eurer Gegenwart? Ihnen muss klar sein, dass sie verloren sind!\n\nIhr habt Euch die Ehrerbietung der Garde verdient. Präsentiert Euer Abzeichen!", description = nil, progress = "Ich muss es wissen, <Name>. Wenn Ihr dem Feind direkt ins Auge blickt, seht Ihr dort Furcht? Ducken sie sich in Eurer Gegenwart? Ihnen muss klar sein, dass sie verloren sind!\n\nIhr habt Euch die Ehrerbietung der Garde verdient. Präsentiert Euer Abzeichen!", completion = "Als wir uns zum ersten Mal trafen hätte ich nie geahnt, dass ein werdender Held vor mir steht. Weiter so, Soldat!", rewards = "Ihr bekommt:\n\nAbzeichen der Sturmlanzen Rang 4"}
MultiLanguageQuestData['de'][7171] = {title = "Legendäre Helden", objective = "Vor mir steht ein erhabener Held der Allianz.\n\n<Lieutenant Haggerdin salutiert.>\n\nWenige haben solch einen Rang unter den Stormpike verdient. Ich habe gesehen wie der Feind vor Euch fiel. Ich habe ihre Entschlossenheit wanken sehen in Eurer Gegenwart. Wenn Ihr Euch ins Kampfgetümmel stürzt, seid ihr ein leuchtendes Fanal der Hoffnung für unsere Streitkräfte!\n\nPräsentiert Euer Abzeichen!", description = nil, progress = "Vor mir steht ein erhabener Held der Allianz.\n\n<Lieutenant Haggerdin salutiert.>\n\nWenige haben solch einen Rang unter den Stormpike verdient. Ich habe gesehen wie der Feind vor Euch fiel. Ich habe ihre Entschlossenheit wanken sehen in Eurer Gegenwart. Wenn Ihr Euch ins Kampfgetümmel stürzt, seid ihr ein leuchtendes Fanal der Hoffnung für unsere Streitkräfte!\n\nPräsentiert Euer Abzeichen!", completion = "Sicherlich werdet Ihr es sein, der das Auge der Führung trägt!", rewards = "Ihr bekommt:\n\nAbzeichen der Sturmlanzen Rang 5"}
MultiLanguageQuestData['de'][7172] = {title = "Das Auge der Führung", objective = "Lasst sie Eure Stimme hören, Kommandant <Name>! Lasst Sie wissen was Angst bedeutet. Zeigt dem Gegner, über welche Macht die Sturmlanzen in ihren Reihen verfügen!\n\nPräsentiert Euer Abzeichen.", description = nil, progress = "Lasst sie Eure Stimme hören, Kommandant <Name>! Lasst Sie wissen was Angst bedeutet. Zeigt dem Gegner, über welche Macht die Sturmlanzen in ihren Reihen verfügen!\n\nPräsentiert Euer Abzeichen.", completion = "Ihr seid der Richtige, um unsere Truppen zum Sieg zu führen, Kommandant! Die Soldaten stehen nun unter Eurem Kommando. Sie werden Euren direkten Befehlen Folge leisten. Führt sie an... Vernichtet die Frostwölfe.", rewards = "Ihr bekommt:\n\nAbzeichen der Sturmlanzen Rang 6"}
MultiLanguageQuestData['de'][7181] = {title = "Die Legende von Korrak", objective = "Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.\n\nSolltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Kriegsmeister Laggrond im Alteracgebirge zurück.", description = "Die angreifenden Sturmlanzen sind nicht die einzige Bedrohung in dieser Region, Soldat. Der Krieg in diesem Tal tobt an zwei Fronten. Den kannibalistischen Winteraxtrollen dürstet es ebenso nach Macht.\n\nAngeführt werden sie von Korrak dem Blutrünstigen - einem grausamen und verschlagenen Biest.\n\nEin Streich gegen Korrak könnte sich als vernichtender Schlag für den Winteraxklan erweisen. Tötet diesen Bastard und Ihr werdet entlohnt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "EisstachelspeerBlutsucherZauberstab der beißenden KälteIhr bekommt:\n\nRune des Rückrufs"}
MultiLanguageQuestData['de'][7201] = {title = "Das letzte Element", objective = "Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat.", description = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, <Name>.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.", progress = "<Sie reibt sich die Hände.>\n\nZeigt sie mir!", completion = "Großartig! Ich werde das sofort mit einem Kurier nach Undercity schicken lassen.\n\nUnd was Euch angeht: Hier ist die versprochene Bezahlung. Behaltet den Rest, dreckige Bestie!", rewards = "Ihr bekommt:\n\nLagraves Siegel"}
MultiLanguageQuestData['de'][7202] = {title = "Korrak der Blutrünstige", objective = "Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.\n\nSolltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Leutnant Haggerdin im Alteracgebirge zurück.", description = "Die eingeborenen Winteraxtrolle dieser Region sind unbarmherzige Wilde, die nichts lieber täten, als unsere Knochen in einer ihrer widerlichen Mahlzeiten zu sehen.\n\nWir müssen ihnen unsere Macht vor Augen führen!\n\nWir konnten einige Schriftstücke aus ihren Höhlen entwenden, die Aufzeichnungen über ihre Führungshierarchie enthalten. Diese Schriftstücke lassen vermuten, dass ihr Anführer, Korrak der Blutrünstige, sich solange versteckt hält, bis er einen Grund hat sich zu zeigen.\n\nDer Tod Korraks, würde den Tod des Winteraxklans bedeuten! Tötet ihn und kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "EisstachelspeerBlutsucherZauberstab der beißenden KälteIhr bekommt:\n\nRune des Rückrufs"}
MultiLanguageQuestData['de'][7221] = {title = "Sprecht mit Ausgrabungsleiter Steinhauer", objective = "Sprecht mit Ausgrabungsleiter Steinhauer in der Garnison von Dun Baldar.Ah, <Name>, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Sturmlanzen können jeden, der sich freiwillig mustern lässt, gebrauchen!\n\nSprecht mit Ausgrabungsleiter Steinhauer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Dun Baldar Garnison.\n\nUnd haltet ein Auge offen während Ihr durch Dun Baldar geht. Für <einen hart arbeitenden/eine hart arbeitende:c> <Klasse> gibt es viel zu tun, sofern Ihr nicht davor zurückscheut Euch die Hände schmutzig zu machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, <Name>, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Sturmlanzen können jeden, der sich freiwillig mustern lässt, gebrauchen!\n\nSprecht mit Ausgrabungsleiter Steinhauer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Dun Baldar Garnison.\n\nUnd haltet ein Auge offen während Ihr durch Dun Baldar geht. Für <einen hart arbeitenden/eine hart arbeitende:c> <Klasse> gibt es viel zu tun, sofern Ihr nicht davor zurückscheut Euch die Hände schmutzig zu machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7222] = {title = "Sprecht mit Voggah Todesgriff", objective = "Sprecht mit Voggah in Burg Frostwolf.Ah, <ein/eine:c> <Klasse>! Wir sind alle hoch erfreut, Euch hier in Alterac anzutreffen, <Name>. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!\n\nSprecht mit Voggah Todesgriff. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!\n\nIhr findet Voggah in Burg Frostwolf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, <ein/eine:c> <Klasse>! Wir sind alle hoch erfreut, Euch hier in Alterac anzutreffen, <Name>. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!\n\nSprecht mit Voggah Todesgriff. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!\n\nIhr findet Voggah in Burg Frostwolf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7223] = {title = "Rüstungsfetzen", objective = "Bringt Murgot Tiefenschmied in Dun Baldar 20 Rüstungsfetzen.", description = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Eisenschmiede bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann unterstützt unsere Kriegsbemühungen und bringt mir diese Stücke!", progress = "Habt ihr mir Rüstungsfetzen mitgebracht, <Name>?", completion = "Das sind ein paar recht gute Stücke, &lt;Name&gt;. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7224] = {title = "Beutezug im Feindesland", objective = "Bringt 20 Rüstungsfetzen zu Schmied Regzar im Dorf der Frostwölfe.", description = "Wenn Ihr gegen den Feind kämpft, sammelt die Fetzen seiner Rüstungen ein und bringt sie zu mir. Aus den Fetzen werde ich neue Rüstungen für unsere eigenen Truppen herstellen!", progress = "Wie läuft die Jagd, <Name>.  Habt Ihr irgendwelche Rüstungsfetzen für mich?", completion = "Die werden ihren Zweck erfüllen. Ich werde sie einschmelzen und reparieren und niemand wird je merken, dass sie von diesen feigen Stormpikes stammen!\n\nDanke, &lt;Name&gt;. Und lasst mich Eure Rüstung aufbessern...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7241] = {title = "Die Verteidigung der Frostwölfe", objective = "Reist ins Alteractal, das sich im gleichnamigen Gebirge befindet. Sucht dort außerhalb des Tunneleingangs Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwölfe. Das Alteractal findet Ihr nördlich von Tarrens Mühle am Fuß des Alteracgebirges.", description = "In der Ferne kann man den Klang der Kriegstrommeln vernehmen, <Klasse>. Die ehrlose Sturmlanzengarde aus Eisenschmiede greift den Klan Eures Kriegshäuptlings an.\n\nIhr seid kampfgestählt, das verrät mir Euer Auftreten. Es scheint, dass Ihr wahrlich bereit seid, der Sache des Frostwolfklans zu dienen.\n\nEs liegt nun an Euch, den nächsten Schritt in Eurer Entwicklung zu gehen.\n\nNördlich von Tarrens Mühle, im Alteracgebirge, befindet sich der Zugang zum Alteractal. Betretet das Tal und sucht Kriegsmeister Laggrond auf. Beeilung <Klasse>, die Schlacht hat bereits begonnen!", progress = nil, completion = "Um ein Soldat der Frostwolf zu werden, muss man sich erst beweisen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7261] = {title = "Die hoheitliche Anordnung", objective = "Reist ins Alteractal im Vorgebirge des Hügellands. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.\n\nFür den Ruhm von Bronzebart!", description = "Wir kämpfen eine blutige Schlacht in den Tälern von Alterac. Der barbarische Frostwolfklan fordert die Sturmlanzen zum Kampf heraus! Sie müssen im Namen unseres König Magni Bronzebart ausgelöscht werden! Die Eroberung und Säuberung dieses Landes ist eine herrschende und territoriale Notwendigkeit für das Königreich von Eisenschmiede.\n\nLeider wachsen gute Soldaten nicht auf Bäumen! Meldet Euch bei Leutnant Haggerdin im Alteractal, um Euren ehrenvollen Pflichten bei den Sturmlanzen nachzukommen.", progress = nil, completion = "An die Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7281] = {title = "Bruderliebe", objective = "Begebt Euch ins Gebiet der Sturmlanzen und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.", description = "Welch tragische Fügung... Mein Bruder steht mir auf dem Schlachtfeld gegenüber: Er ist einer der Kommandanten der Sturmlanzen.\n\nVon allen vier Kommandanten stellt er zweifellos die größte Gefahr dar. Falls man ihn tötet, würde die Bansheekönigin ihn vielleicht wiedererwecken, so wie sie es mit mir getan hat - und ihm die Irrtümer seines bisherigen Handelns vor Augen führen...\n\nTief im feindlichen Gebiet werdet Ihr meinen Bruder finden. Tötet ihn und bringt ihn zu mir zurück. Ich vertraue darauf, dass Ihr diese Mission erfolgreich zu Ende bringt, Soldat. \n\nUnd Soldat... geht nicht alleine.", progress = nil, completion = "Eure Heldentat wird nicht unbemerkt bleiben, &lt;Name&gt;.\n\n Ich darf keine Zeit verlieren, wenn er gerettet werden soll. Sylvanas muss kontaktiert werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7282] = {title = "Bruderliebe", objective = "Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.", description = "Er muss aus seinem Elend befreit werden, Soldat! Mein Bruder weiß nicht mehr, was er tut. Er ist nur noch eine willenlose Marionette der grausamen Bansheekönigin.\n\nBegebt Euch, über das Feld des Kampfes, in die Tiefen des Gebiets der Frostwölfe. Findet meinen Bruder und zerstört, was von ihm übrig ist. Seine Qualen sollen endlich ein Ende haben.", progress = nil, completion = "Ihr habt doch daran gedacht den Leichnam zu verbrennen, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7301] = {title = "Gefallene Himmelsstürmer", objective = "Begebt Euch ins Frostwolfterritorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt.", description = "Wir konnten sie gefangennehmen, <Volk>. Ich rede von ihren Schwadronskommandanten. Es war eine wilde Himmelsschlacht, doch letztendlich haben wir sie geschlagen! Sie fielen wie Steine vom Himmel! Leider hat es auch viele unserer besten Piloten erwischt, als Sie die Burg Frostwolf angriffen. Ihr müsst herausfinden was aus ihnen geworden ist.\n\nDurchkämmt das Gebiet der Westturmstellung und Burg Frostwolf. Dort wurden Sie das letzte Mal gesehen. Und geht gründlich vor!", progress = nil, completion = "Unglaublich! Ihr habt Sie doch befreit oder? Oder??? Nun gut, immerhin kennen wir jetzt ihren Aufenthaltsort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7302] = {title = "Gefallene Himmelsstürmer", objective = "Findet heraus, was aus Schwadronskommandantin Guse, Schwadronskommandantin Jeztor und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück.", description = "Unsere Luftunterstützung musste einen schweren Schlag hinnehmen, <Name>. Sämtliche Schwadronskommandanten wurden über feindlichem Gebiet abgeschossen. Ihr müsst herausfinden, was aus ihnen geworden ist, sodass wir einen Rettungsversuch unternehmen können!\n\nGuse wurde das letzte Mal gesehen, als sie über den Eisschwingenbunker hinwegflog. Jetzors Reittier wurde zuletzt am Sägewerk der Sturmlanzen gesichtet. Mulverick... dieser waghalsige Narr, stürzte in der Nähe des Nordbunkers von Dun Baldar ab.\n\nDas sind alle Informationen, die ich habe. Schwärmt aus und durchsucht das Gebiet gründlich!", progress = nil, completion = "Gut gemacht! Eure Informationen sind von umschätzbarem Wert für unsere Sache.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7321] = {title = "Milde Schildkrötensuppe", objective = "Bringt 10 Stücke Schildkrötenfleisch zu Christoph Jeffkott in Tarrens Mühle.", description = "Wer sagt denn, dass Untote keine Ahnung vom Kochen haben? Nehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von den Toten zurückgekehrt sind, nur um eine Schüssel voll davon zu kosten.\n\nDa wir gerade davon sprechen: In letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis zum Lordameresee gereist, um Schnappkiefer zu jagen, aber meine Arbeit hier beschäftigt mich mittlerweile einfach zu sehr.\n\nWenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern bringt, dann werd ich Euch in das Geheimnis meines Rezepts einweihen!", progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Meine milde Schildkrötensuppe wird Euch in einer kalten Nacht warm halten... falls es Euch überhaupt interessiert.", rewards = "Ihr bekommt:\n\nRezept: Milde SchildkrötensuppeMilde Schildkrötensuppe"}
MultiLanguageQuestData['de'][7341] = {title = "Ein gerechter Handel", objective = "Seid gegrüßt, <Volk>. Ich bin Kolark, Kopfgeldjäger aus Thunder Bluff. Ich habe viele Teile der Welt bereist und so manches erlebt. \n\nAuf meinen Reisen über die südlichen Meere entdeckte ich diese wunderbaren Thoriumpfeile. Zwar besitze ich einen endlosen Vorrat dieser Pfeile, aber dafür keine einzige Patrone mehr. Bah, kein Tauren mit Selbstachtung würde sich je dabei erwischen lassen, wie er einen dieser dürren Bögen benutzt. Die Pfeile sind nutzlos!\n\nIch schlage Euch einen Handel vor: Einen eins zu eins Tausch von Thoriumpatronen gegen meine Thoriumpfeile. Sind wir im Geschäft?", description = nil, progress = "Seid gegrüßt, <Volk>. Ich bin Kolark, Kopfgeldjäger aus Thunder Bluff. Ich habe viele Teile der Welt bereist und so manches erlebt. \n\nAuf meinen Reisen über die südlichen Meere entdeckte ich diese wunderbaren Thoriumpfeile. Zwar besitze ich einen endlosen Vorrat dieser Pfeile, aber dafür keine einzige Patrone mehr. Bah, kein Tauren mit Selbstachtung würde sich je dabei erwischen lassen, wie er einen dieser dürren Bögen benutzt. Die Pfeile sind nutzlos!\n\nIch schlage Euch einen Handel vor: Einen eins zu eins Tausch von Thoriumpatronen gegen meine Thoriumpfeile. Sind wir im Geschäft?", completion = "Excellent! Ich bin ein Tauren, der sein Wort hält, &lt;Volk&gt;. Die Pfeile gehören Euch.", rewards = "Ihr bekommt:\n\nThoriumpfeile"}
MultiLanguageQuestData['de'][7342] = {title = "Pfeile sind was für Memmen", objective = "Habt Ihr schon einmal so einen verdammten Mist erlebt?! Die letzte Munitionslieferung aus Kharanos ist völlig verbockt worden. Alles was wir jetzt noch an Munition haben, sind diese schwachen, nutzlosen Pfeile! Was zur Hölle soll ich mit 500.000 Thoriumpfeilen anfangen?\n\nIch sag dir was, Kind. Wenn du es schaffst mir Thoriumpatronen zu bringen, gebe ich dir im Austausch dafür Thoriumpfeile. Sind wir im Geschäft?", description = nil, progress = "Habt Ihr schon einmal so einen verdammten Mist erlebt?! Die letzte Munitionslieferung aus Kharanos ist völlig verbockt worden. Alles was wir jetzt noch an Munition haben, sind diese schwachen, nutzlosen Pfeile! Was zur Hölle soll ich mit 500.000 Thoriumpfeilen anfangen?\n\nIch sag dir was, Kind. Wenn du es schaffst mir Thoriumpatronen zu bringen, gebe ich dir im Austausch dafür Thoriumpfeile. Sind wir im Geschäft?", completion = "Abmachung ist Abmachung! Die Pfeile gehören Euch.", rewards = "Ihr bekommt:\n\nThoriumpfeile"}
MultiLanguageQuestData['de'][7367] = {title = "Die Gefahr bannen", objective = "Findet den Sprengmeister der Frostwölfe und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Sturmlanzen zurück.", description = "Die Frostwölfe haben ihre Frontlinien und Basen allesamt vermint, <Klasse>. Achtet darauf wohin Ihr tretet, wenn Ihr in feindliches Territorium eindringt.\n\nWenn wir dem Feind einen entscheidenden Schlag versetzten wollen, müsst Ihr seine Quelle für Sprengwaffen zum Versiegen bringen - Ich rede vom feindlichen Sprengmeister! Tötet ihn und wir können alle Minen sicher entschärfen. Solange er ausfällt, fallen auch seine Minen aus.\n\nVermutlich befindet er sich in einem Turm, nahe der Eisblutgarnison. Viel Glück, Soldat!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7368] = {title = "Die Gefahr bannen", objective = "Findet den Sprengmeister der Sturmlanzen und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Frostwölfe zurück.", description = "Ich weiß alles über Landminen. Immerhin habe ich alle Minen an unseren Frontlinien selbst verlegt.\n\nWenn Ihr das Minenfeld der Sturmlanzen unschädlich machen wollt, braucht Ihr nur eines zu tun - Tötet den feindlichen Sprengmeister! Zweifellos versteckt sich der feige Zwerg im ersten Turm, auf dem Feld des Kampfes. Schaltet ihn aus und die Landminen werden nicht zurückkommen, nachdem sie von Euch entschärft wurden.\n\nFalls Ihr es schaffen solltet den Sprengmeister zu töten, kommt zu mir zurück und lasst es mich wissen. Keine gute Tat soll unbelohnt bleiben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7383] = {title = "Teldrassil: Die Bürde der Kaldorei", objective = "Füllt die Amethystphiole.", description = "Ihr müsst nun den Mondbrunnen unter den Ästen des Orakelbaums im fernen Nordwesten aufsuchen. Er ist der erste und mächtigste unserer Brunnen und es heißt von seinem Wasser, es enthalte die Essenz von Elunes Macht.\n\nEntnehmt eine Phiole des Wassers und kehrt zu mir zurück. Ich werde euch an der Weggabelung vor Darnassus treffen, wenn Eure Aufgabe vollendet ist.", progress = "Die Druiden, unter Mitwirkung des Orakelbaums und des Erzdruiden, haben sich sorgsam um die Hege Teldrassils gekümmert. Wir haben jetzt zwar eine neue Heimat, doch unsere Unsterblichkeit haben wir noch nicht wiedererlangt.", completion = "In der Nähe des Orakelbaums... kann man fast spüren, wie die Weisheit Gestalt annimmt. Lasst mich mit der Geschichte fortfahren...\n\nTeldrassil wuchs und gedieh, und der Erzdruide wandte sich an die Großdrachen, um deren Segen zu erhalten, den sie in längst vergangenen Zeiten über Nordrassil verbreitet hatten. Nozdormu jedoch, der Lord der Zeit, weigerte sich, seinen Segen zu spenden und tadelte den Druiden wegen seiner Arroganz. Einig mit Nozdormu widersetzte sich auch Alexstrasza Staghelm und ohne ihren Segen entartete Teldrassil und wuchs auf unvorhersehbare Weise...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7385] = {title = "Eine Gallone Blut", objective = "Wenn Ihr Euch nützlich machen wollt, spendet mir große Mengen Feindesblut. Ich wäre hocherfreut, Gallonen von Blut entgegen zu nehmen, <Name>.", description = nil, progress = "Wenn Ihr Euch nützlich machen wollt, spendet mir große Mengen Feindesblut. Ich wäre hocherfreut, Gallonen von Blut entgegen zu nehmen, <Name>.", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord erscheinen und diesen Hunden von den Stormpike den ganzen Zorn des Frostwolfklans vor Augen führen!", rewards = nil}
MultiLanguageQuestData['de'][7386] = {title = "Haufenweise Kristalle", objective = "Es gibt hier Zeiten, in denen Ihr Tage oder sogar Wochen auf den Schlachtfeldern zubringt. Vielleicht könnt Ihr während dieser Zeit nach größeren Gruppen von Frostwolf Sturmkristallen Ausschau halten.\n\nDer Zirkel wäre hocherfreut über derartige Spenden, <Name>.", description = nil, progress = "Es gibt hier Zeiten, in denen Ihr Tage oder sogar Wochen auf den Schlachtfeldern zubringt. Vielleicht könnt Ihr während dieser Zeit nach größeren Gruppen von Frostwolf Sturmkristallen Ausschau halten.\n\nDer Zirkel wäre hocherfreut über derartige Spenden, <Name>.", completion = "Gut gemacht, &lt;Name&gt;. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldfürsten herbeizurufen.", rewards = nil}
MultiLanguageQuestData['de'][7429] = {title = "Befreit Knot!", objective = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", description = nil, progress = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", completion = "Vielen Dank, dass Ihr mich befreit habt! Ihr seid meine Nummer eins.\n\n Ich hab's doch gewusst, dass ich mein Leben nicht als Ogerhappen beende!", rewards = nil}
MultiLanguageQuestData['de'][7441] = {title = "Pusillin und der Älteste Azj'Tordin", objective = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\n\nKehrt mit dem Buch zu Az'Tordin, beim Larisspavillon in Feralas, zurück.", description = "Ich habe nur einen Moment nicht aufgepasst, Fremder. In meiner Eile, dem Griff des gefallenen Prinzen zu entkommen, wurde ich ausgeraubt. Ein besonders widerlicher Dämon, namens Pusillin, stahl mir mein Buch der Zauberformeln und den Schlüssel zu den einstmals großen Hallen von Eldre'Thalas.\n\nMein Interesse am Schlüssel ist verloschen als ich meine Unsterblichkeit gegen die Freiheit eingetauscht habe. Doch ich benötige unbedingt mein Buch der Zauberformeln.\n\nFindet den Dämon Pusillin und bringt mir mein Buch.\n\nSucht Pusillin im Wucherborkenviertel von Düsterbruch.", progress = "Ich bereue nichts, Fremder. Die Königin ist schon lange tot. Die Arbeiten der Shen'dralar sind seit langem durch Prinz Tortheldrins Wahnsinn zerstört worden. Ich suche nur noch die Freiheit... Flucht...", completion = "Ihr habt es gefunden! Ich verfluche diesen verdammten Dämonen. Leider sind meine Vorräte fast aufgebraucht. Doch sucht Euch nur etwas von meinen Sachen aus.", rewards = "SprinterschwertFlotte StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7461] = {title = "Der innere Wahnsinn", objective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", description = "Habt Ihr genug gehört? Seid Ihr <ein Mann/eine Frau> der Tat?\n\nDieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Habt Ihr das erst einmal geschafft, könnt Ihr Immol'thar vernichten. Die Macht des Prinzen wird stark geschwächt sein, greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer.", progress = "Seid wachsam Abenteurer. Der Prinz ist... überzeugend.", completion = "Ihr seid ein Held, wir sind Euch zu ewigen Dank verpflichtet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7462] = {title = "Der Schatz der Shen'dralar", objective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "KnochenzermalmerHinterwaldhelmSeggenstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][7463] = {title = "Arkane Erfrischung", objective = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz zum Wissenshüter Lydros im Athenaeum zurück.", description = "<Ein/Eine:r> <Volk> und dazu noch <Magier/Magierin>! Wie wunderbar. Ich habe jemanden wie Euch schon seit... wie lange ist es nun schon her?... 500 Jahren nicht mehr gesehen!\n\nIch habe da etwas, das Euren Durst zu löschen vermag, doch zuerst müsst Ihr etwas für mich erledigen.\n\n<Lydros kichert.>\n\nEs gibt eine Anomalie in Eldre'Thalas. Ein Wasserelementar hat sich im östlichen Flügel niedergelassen. Seine Anwesenheit muss unbedingt katalogisiert werden!\n\nReist nach Düsterbruch in das Wucherborkenviertel und sammelt etwas von der elementaren Essenz der Hydrobrut. Bringt Sie anschließend zu mir zurück und ich werde Euch einen äußerst nützlichen Zauberspruch beibringen.", progress = "Ja bitte? Kennen wir uns?", completion = "Wundervoll!...Wer wart Ihr doch gleich nochmal? Ach, ist auch egal. Hmm... Ihr seid ein &lt;Klasse&gt;, also werdet Ihr das hier vielleicht nützlich finden.", rewards = "Ihr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7481] = {title = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Telmius Traumsucher. Meldet Euch anschließend bei dem Weisen Korolusk in Camp Mojache.", description = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Telmius Traumsucher der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", progress = nil, completion = "Eine Schande... eine Tragödie. Die Artefakte sind verloren, sagt Ihr? Keine Spur von ihnen, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7482] = {title = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Telmius Traumsucher. Meldet Euch anschließend bei der Gelehrten Runendorn in der Mondfederfeste.", description = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Telmius Traumsucher der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", progress = nil, completion = "Eine Schande... eine Tragödie. Die Artefakte sind verloren, sagt Ihr? Keine Spur von ihnen, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7483] = {title = "Buchband der Schnelligkeit", objective = "Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2-mal das Blut von Helden, zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten.", description = "Meister Traumsucher verlor den Buchband der Schnelligkeit im Ostflügel. Mit dem Buchband kann ein Zauber der geringen Hast auf Eure Ausrüstung gewirkt werden. Ein einfacher Trick...\n\nWie auch immer... Falls Ihr Interesse habt, bringt mir den Buchband und einige grundlegende Reagenzien.\n\nHrm... Ich glaube man benötigt das Blut von Helden, einen makellosen schwarzen Diamanten und große glänzende Splitter. Ich mag mich natürlich Irren...\n\n<Lydros zuckt mit den Achseln.>", progress = "Was gibt es? Seht Ihr nicht, dass ich arbeite!", completion = "&lt;Lydros gähnt.&gt;\n\nWie versprochen, das Arkanum der Schnelligkeit. Verbraucht nicht gleich alles auf einmal.\n\n&lt;Lydros kichert.&gt;", rewards = "Ihr bekommt:\n\nArkanum der Schnelligkeit"}
MultiLanguageQuestData['de'][7484] = {title = "Buchband des Fokus", objective = "Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2-mal Schattenhaut, zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten.", description = "Dieser Buchband erweckte die Neugierde eines jungen Familiars, welcher einem der Hüter gehörte. Das arme Ding wurde nur ein paar Wochen alt\n\nDiejenigen unter Euch, die sich mit Magie beschäftigen, dürften dieser Gegenstand interessieren.\n\nDas Buchband des Fokus ging in diesem Flügel verloren. Ich kann nur annehmen, dass einer der Geister der Hochgeborenen es in Besitz genommen hat.\n\nBringt mir den Buchband, zusammen mit einen makellosen schwarzen Diamanten, einigen großen glänzenden Splittern und etwas Schattenhaut, und ich werde das Arkanum herbeizaubern.", progress = "Ihr nun wieder? Was könntet Ihr jetzt schon wieder wollen?", completion = "Achtet darauf, Euch während der Verzauberung nicht selbst weh zu tun, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nArkanum des Fokus"}
MultiLanguageQuestData['de'][7485] = {title = "Buchband des Schutzes", objective = "Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten.", description = "Als er von dem Verlust dieses Buchbands hörte, weinte er wie ein kleines Kind. Wohlgemerkt, Ich selbst habe schon über derartige Verluste getrauert - und kein Verlust wiegt mehr, als der Verlust von Wissen und Geschichte- aber wegen diesem Haufen nutzloser Zauberformeln? Lächerlich! Mir scheint, der Prinz hat ihm wohl einen Gefallen getan, als er ihm das Fleisch von den Knochen riss.\n\nBringt mir den Buchband, zusammen mit einen makellosen schwarzen Diamanten, einigen großen glänzenden Splittern und eine ausgefranste Monstrositätenstickerei, und ich werde das Arkanum wiederherstellen.\n\nAch ja, sucht im Nordflügel.", progress = "Meine Geduld, verhindert euer Leiden.", completion = "Ja, ja... Beruhigt Euch wieder. Wie versprochen, ist hier Euer Arkanum.", rewards = "Ihr bekommt:\n\nArkanum des Schutzes"}
MultiLanguageQuestData['de'][7486] = {title = "Die Belohnung eines Helden", objective = "Nehmt Eure Belohnung aus Hydraxis' Kasten.", description = "<Name>, Euer Dienst für die Kriegsherrn hat alles übertroffen, was wir je von den Einwohnern dieser Welt erwartet haben.\n\nWir kennen zwar nicht die Vorstellung Eures Volkes, von Dankbarkeit oder wie Ihr gute Arbeit bei Euch belohnt, aber in diesem Fall...ist eine Belohnung mehr als angebracht.\n\nUnter der Brandung an der südlichen Basis der Insel, findet Ihr einen Kasten. In diesem werdet Ihr Eure... Belohnung finden.\n\nGeht, <Name>. Nehmt Euch Eure Belohnung.", progress = nil, completion = "Hydraxis Stimme erklingt von der Wasseroberfläche aus...\n\n\"Wählt was am besten zu Euch passt, &lt;Name&gt;. Möge es Euch vor den Feinden des Wasserlords schützen.\"", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMeeresbriseGezeitenschleife\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7487] = {title = "Abstimmung mit dem Kern", objective = "Begebt Euch zum Portal in den Schwarzfelstiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter am Schwarzfels zurück.", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, <Volk>. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Schwarzfels führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Schwarzfelstiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7488] = {title = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Latronicus Mondspeer in der Mondfederfeste in Feralas.", description = "Die Magierin Lethtendris, eine bösartige Blutelfe, deren Brutalität nur durch ihre pervertiere Hingabe zur Magie in den Schatten gestellt wird, ist nach Düsterbruch geflüchtet. Sie hat eine Apparatur entwickelt, ein Netz, um die magischen Energien dieses Ortes einzufangen und wir fürchten, dass wenn Sie niemand aufhält, sie der Welt einen unwiderruflichen Schaden zufügen wird!\n\nStoppt Sie, <Name>. Findet Sie und nehmt das Netz an Euch. Am ehesten werdet Ihr sie nahe den Satyrn, im Wucherborkenviertel von Düsterbruch, finden. Bringt das Netz anschließend zu mir und ich werde versuchen, dessen Kräfte wieder der Wildnis zurückzugeben...", progress = "Habt Ihr das Netz, <Name>?  Seine konzentrierten magischen Energien müssen wieder freigelassen werden!", completion = "Ihr habt also das Netz!  Hervorragende Arbeit, &lt;Name&gt;!  Lethtendris ist, genau wie viele andere ihrer Art, blind für die Gefahren, die der Missbrauch von Magie unserer Welt hinzufügen kann. Sie alle halten sich für Meister der Magie und dabei bemerken sie nicht, wie sie zum Sklaven ihrer eigenen Hingabe werden. Ihr Tod erfüllt mich mit Trauer, aber er war notwendig.\n\nDanke,  &lt;Name&gt;. Ich werde die Energien des Netzes sicher über ein größeres Gebiet freilassen und es anschließend zerstören, um den weiteren Missbrauch seiner Kräfte zu verhindern.", rewards = "Ihr bekommt:\n\nLehrenspinner"}
MultiLanguageQuestData['de'][7489] = {title = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Talo Dornhuf im Camp Mojache in Feralas.", description = "Die Blutelfe Lethtendris hat ihre Grenzen überschritten. So versessen war sie darauf magische Macht zu erlangen, das sie ihre Brüder verraten und eine teuflische Apparatur gebaut hat, ein Netz welches in der Lage ist, die verdorbenen magischen Energien von Düsterbruch einzufangen. Selbst jetzt sammelt sie diese Energien und plant, sie gegen ihre Feinde einzusetzen. \n\nLethtendris muss aufgehalten werden. Sucht sie im Wucherborkenviertel von Düsterbruch, besiegt sie und bringt anschließend ihr Netz zu mir. So kann es vielleicht wieder in die Hände einiger Blutelfen übergeben werden, die dieses Artefakt mit klarem Verstand untersuchen können.", progress = "<Name>, habt Ihr Lethtendris' Netz?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Dieses Netz enthält in seinem Inneren einen riesigen Vorrat der Magie von Düsterbruch, und ich fürchte um den Schaden, der von jemanden so unverantwortlichen wie Lethtendris angerichtet werden könnte. Ihr Tod erfüllt mich mit Trauer, aber ich weiß, dass sie sich solange sie am Leben war nie freiwillig von ihrem Netz getrennt hätte.\n\nVielen Dank, &lt;Name&gt;. Ich werde das Netz an einige weitaus verantwortungsbewusstere Schüler der Magie übergeben. Sie werden die neuen Wächter seiner Magie sein.", rewards = "Ihr bekommt:\n\nLehrenspinner"}
MultiLanguageQuestData['de'][7490] = {title = "Sieg für die Horde", objective = "Bringt Onyxias Kopf zu Garrosh in Orgrimmar.", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und präsentiert ihn Eurem Kriegshäuptling.", progress = "<Thralls stoische Mine verschwindet für den Bruchteil einer Sekunde, als er den riesigen Kopf von Onyxia erblickt. Beinahe hätte er den mächtigen Doomhammer gezogen.>", completion = "Dies ist ein großartiger Sieg für die Horde, &lt;Name&gt;. So viele male habt Ihr Euren Kriegshäuptling geehrt. Nun ist es an der Zeit, dass der Kriegshäuptling Euch seine Ehre erweist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7491] = {title = "Für alle sichtbar", objective = "Sucht Oberanführer Runthak im Tal der Stärke auf.", description = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.\n\n<Der Kriegshäuptling salutiert euch.>\n\nLasst Euer Publikum nicht warten, großer Held.", progress = nil, completion = "Wählt Eure Belohnung und lasst die Feierlichkeiten anlässlich Eures großen Sieges beginnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalisman mit OnyxiablutDrachentötersignetZahn Onyxias\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7492] = {title = "Camp Mojache", objective = "Sprecht mit Talo Dornhuf in Camp Mojache, in Feralas.", description = "Talo Dornhuf, ein Taurenältester in Feralas, hat uns um Hilfe gebeten. Er hat nur wenige Einzelheiten verraten, doch wie es scheint sucht er nach Agenten für eine Angelegenheit, die sowohl heikel als auch dringend ist.\n\nDient der Horde, <Name>. Begebt Euch ins Camp Mojache in Feralas und sprecht mit Talo.", progress = nil, completion = "Ah, es ist freut mich einen &lt;Klasse&gt; zu sehen, der meinem Ruf gefolgt ist. Ich benötige Eure Dienste, &lt;Name&gt; und ich befürchte, Sie werden euch auf einen gefährlichen Pfad führen... \n\nEinen Pfad nach Düsterbruch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7493] = {title = "Die Reise beginnt erst", objective = "Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.\n\nBitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.\n\n Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMuster: Onyxiaschuppenumhang"}
MultiLanguageQuestData['de'][7494] = {title = "Die Mondfederfeste", objective = "Sprecht mit Latronicus Mondspeer in der Mondfederfeste in Feralas.", description = "<Name>! Man braucht Euch in Feralas!\n\nEine abtrünnige Magierin, Lethtendris, ist in die uralten Elfenruinen von Eldre'thalas, vielen bekannt als Düsterbruch, geflohen. Es wird angenommen, dass sie einen gefährlichen Gegenstand voller magischer Energien bei sich trägt, der dringend wiederbeschafft werden muss.\n\nLatronicus Mondspeer hat Agenten angefordert, die in Düsterbruch eindringen und den Gegenstand von Lethtendris zurückholen sollen.\n\nDient der Allianz! Sucht Latronicus in der Mondfederfeste in Feralas auf.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Ich bin erfreut Euch hier zu sehen. Nur schade, dass unser Treffen unter diesen Umständen stattfindet\n\nHört mir genau zu, ich habe eine Aufgabe von größter Wichtigkeit für Euch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7495] = {title = "Sieg für die Allianz", objective = "Bringt Onyxias Kopf zu König Varian Wrynn in Sturmwind.", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und präsentiert ihn dem König Varian Wrynn.", progress = "Bei Uthers Bart!", completion = "Für so viele Jahre habe ich unter ihrem Bann gestanden. Endlich wurde Gerechtigkeit geübt und die Ehre von Stormwind wieder hergestellt! Heute werden wir diesen glorreichen Sieg feiern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7496] = {title = "Gute Zeiten feiern", objective = "Sucht Major Mattingly im Tal der Helden auf.", description = "Sucht Major Mattingly im Tal der Helden auf, <Name>. Er erwartet Euch bereits...", progress = nil, completion = "Nur wenige wurden bisher mit einer solchen Zeremonie geehrt, &lt;Name&gt;. Bitte wählt Eure Belohnung aus, damit wir mit den Feierlichkeiten beginnen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalisman mit OnyxiablutDrachentötersignetZahn Onyxias\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7497] = {title = "Die Reise beginnt erst", objective = "Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.\n\nBitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.\n\n Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMuster: Onyxiaschuppenumhang"}
MultiLanguageQuestData['de'][7498] = {title = "Garona: Eine Studie über Heimlichkeit und Verrat", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7499] = {title = "Kodex der Verteidigung", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7500] = {title = "Das Arkanistenkochbuch", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7501] = {title = "Vom Licht und wie man es schwingt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7502] = {title = "Schatten einspannen", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7503] = {title = "Das größte Volk von Jägern", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7504] = {title = "Heiliger Fleischklops: Was das Licht Dir nicht erzählt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7505] = {title = "Frostschock und Du", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7506] = {title = "Der Smaragdgrüne Traum", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Ihr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"}
MultiLanguageQuestData['de'][7507] = {title = "Nostro's Compendium", objective = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum.", description = "Ihr habt etwas von größter Wichtigkeit entdeckt. Dieses Buch ist anders, als alle anderen die Ihr bisher gesehen habt.\n\nEs scheint, als hätte jemand oder etwas es geschafft, das Siegel des Athenaeums aufzubrechen. Der Text in seinem Inneren ist beschädigt und schwer lesbar.", progress = "Ah, eines unserer wertvollsten Kompendien. Dieses eine wurde schon seit einer Ewigkeit vermisst.", completion = "Auf dem Schwarzmarkt hättet Ihr für dieses Buch eine ganz schöne Menge Gold erhalten, &lt;Name&gt;. Insbesondere mit dem gebrochenen Schutzsiegel. Ein jeder mit einer ausreichenden Intelligenz, um das gesammelte Wissen auf diesen heiligen Seiten zu lesen, wäre so in der Lage, die Geheimnisse des Drachentötens zu erlernen.\n\nVielleicht wäre eine großzügige Belohnung angebracht... Nun ja, eine Belohnung, die enorme Anstrengungen erfordert, um Sie zu erhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7508] = {title = "The Forging of Quel'Serrar", objective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", description = "If you wish to take on this task, present Lydros with the dull blade.", progress = "Sehr gut, lasst uns beginnen...", completion = "Solltet Ihr es schaffen in den Hort des Drachen einzudringen, die Klinge unter ihrem feurigen Atem zu erhitzen und sie in ihrem Blut zu härten, werde ich die Klinge für Euch binden.", rewards = nil}
MultiLanguageQuestData['de'][7509] = {title = "The Forging of Quel'Serrar", objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", progress = "Eines Tages wird vielleicht wieder jemand die Prismatische Klinge führen.", completion = "&lt;Lydros murmelt etwas Unverständliches.&gt;\n\nWie versprochen &lt;Klasse&gt;, die Klinge von Quel'Serrar.", rewards = "Ihr bekommt:\n\nQuel'Serrar"}
MultiLanguageQuestData['de'][7541] = {title = "Dienst an der Horde", objective = "Unsere Gelehrten werden einige Zeit brauchen, um den Anhänger, den Ihr uns gebracht habt, zu studieren. Allerdings möchte ich Euch für Euren Dienst an der Horde eine kleine Belohnung geben.\n\nDanke, <Name>.  Eure Taten ehren Euch und uns.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing der TreueEinbaums Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7562] = {title = "Mor'zul Blutbringer", objective = "Sprecht mit Mor'zul Blutbringer beim Altar der Stürme in der Brennenden Steppe.", description = "<Name>, Eure Studien der dunklen Künste sind sehr eingehend. Euer Einfluss auf die Kräfte der jenseitigen Welt ist sehr stark geworden... ich denke, Ihr seid nun bereit eines der berüchtigten Schreckensrösser an Euch zu binden.\n\nDas Ritual zum Beschwören eines dieser Biester erfordert große Macht und Ressourcen, doch wenn Ihr solch ein episches Reittier beherrschen wollt, sprecht mit Meister Mor'zul Blutbringer. Er hat sein Lager nahe des Altars der Stürme in der Brennenden Steppe aufgeschlagen.\n\nGeht, <Name>. Diese Aufgabe wird sehr gefährlich werden, aber ein Hexenmeister von Eurer Statur sollte sich nicht vor Gefahr fürchten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr wie ich gekommen, um hier am Altar der Stürme zu studieren? Vielleicht um seine Energien für einen geheimen Zweck zu nutzen...\n\nOder seid Ihr vielleicht sogar hier, um mit mir zu sprechen? Ja, ich denke das seid Ihr.\n\nIhr wollt also ein Schreckensross beherrschen? Diese Aufgabe ist nicht einfach. Das wird Euch eine nicht unerhebliche Menge an Blut kosten... und natürlich auch an Gold. Doch ein Schreckensross aus Xoroth ist einen solchen Aufwand mehr als wert. Also wenn Ihr interessiert seid, hört zu...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7563] = {title = "Kochendes Blut", objective = "Mor'zul Blutbringer in der Brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt.", description = "Die Schreckensrösser existieren auf einer uns fremden Welt, in der feurigen Ebene von Xoroth. Um eines dieser einzigartigen Tiere an Euch zu binden, werdet Ihr mächtige Glyphen beschwören müssen. Ich werde für Euch die erforderlichen Glyphen auf einem Pergament niederschreiben, doch dafür brauche ich eine ganz spezielle Tinte.\n\nIm weit entfernten Winterquell lebt eine besondere Eulenart. Einst waren es normale Tiere, doch die dämonische Macht der Flüsternden Schlucht trieb sie in den Wahnsinn. Übrig blieben nur Blutrünstige Bestien.\n\nEs ist ihr Blut, das ich zum Zeichnen der Glyphen benötige. Bringt mir etwas davon und ich kann Euch weiterhelfen.", progress = "Habt Ihr die tobenden Eulenbestien gefunden, <Name>? Die Magie dieser Kreaturen ist sehr stark und konzentriert sich besonders im Blut dieser verzerrten Wesen.", completion = "Ausgezeichnet! Ich werde das Blut mit Tinte abmischen und es für die Schriftrolle verwenden, die ich Euch versprochen habe. Vielleicht werde ich ein wenig davon für mich zurückbehalten, denn wie ich hörte, ist der Geschmack des Blutes sehr belebend...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7564] = {title = "Wildaug", objective = "Bringt den Behälter mit Blut zu Gorzeeki Wildaug beim Altar der Stürme in der brennenden Steppe.", description = "Mein Assistent Gorzeeki ist ein recht bewanderter Alchemist. Er sollte in der Lage sein die Tinte herzustellen, die ich für die Herstellung der Schriftrolle benötige. Ich habe das von Euch mitgebrachte Blut destilliert. Nehmt es und bringt es zu Gorzeeki, damit er mit seiner Arbeit beginnen kann.", progress = "Habt Ihr etwas für mich? Ist es zufällig eine große, saftige Spinne? Nicht oder? Oder vielleicht eine Kakerlake? Ich hoffe, sie ist noch am Leben... ich mag es, auf ihnen herumzukauen, wenn sie noch leben...", completion = "Oh, Blut. Bestimmt von Meister Mor'zul. Er liebt das Zeug und mag es, wenn man es literweise vergießt. Ich hingegen bevorzuge es, wenn es noch durch die Venen eines kleinen Nagetiers jagt. Auf die Art bleibt es warm... bis man es braucht.\n\nDieses Blut ist von großer Macht erfüllt. Mor'zul stellt wohl wieder eine Schriftrolle zur Beschwörung eines Schreckensrosses her. Wie aufregend!\n\nFalls das wahr ist und Ihr das Ritual durchführt, dann... werdet Ihr noch einiges mehr als Blut brauchen, mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7581] = {title = "Das Fundament des Gefängnisses", objective = "Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der Faulenden Narbe zurück.", description = "Ihr müsst ein geeignetes Fundament für das Gefängnis der Verdammniswache finden.\n\nDas Blut der Wildhufsatyrn, die in Düsterbruch hausen, sollte dem Genüge tun. Das geronnene Blut wird die Splitter von Hederine zusammenhalten und das Kristallgefängnis mit Energie versorgen.", progress = "Allein das Blut der Wildhufsatyrn wird ausreichend sein.", completion = "Ah, welch' exzellente Ausbeute. Das Blut wird die magische Verteidigung der Verdammniswache  unterdrücken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7582] = {title = "Die Gefängnishülle", objective = "Reist in die Flüsternde Schlucht in Winterquell und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der Faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt.", description = "Die Dämonen von Hederine, die das Vorgebirge des Berges Hyjal bevölkern, sondern mächtige Gifte ab, die mit der Zeit hart und somit zu einem kompakten Anti-Magiekristall werden. Diese Kristalle sind auch als Tränen der Hederine bekannt.\n\nNicht einmal die gewaltige Macht einer Verdammniswache könnte die Wände eines Gefängnisses durchbrechen, die aus diesem Material errichtet wurden.\n\nReist in die Flüsternde Schlucht in Winterquell und holt Euch die Tränen.", progress = "Die Dämonen von Hederine werden Euch ihre wertvollen Steine nicht kampflos überlassen, <Name>.", completion = "Ich muss das Blut der Wildhufe lediglich mit diesen Kristallen vereinen, dann sollte das Gefängnis bereit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7583] = {title = "Unterdrückung", objective = "Wagt Euch in die Faulende Narbe heraus und macht einen Verdammniswachenkommandanten ausfindig.\n\nWendet das leuchtende Kristallgefängnis auf den Verdammniswachenkommandanten an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.\n\nSolltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der Faulenden Narbe.", description = "Das Gefängnis ist bereit. Jetzt kommen wir zum schwierigsten Teil des Unterfangens.\n\nIhr müsst mithilfe des Kristallgefängnisses einen Verdammniswachenkommandanten in der Faulenden Narbe finden und fangen.\n\nSeid gewarnt! Verdammniswachen sind gerissene und tödliche Gegner, die Euch sofort zu zerstören versuchen werden, sobald Ihr mit dem Ritual der Gefangenschaft beginnt. Euer Gegner wird bei seinem Versuch der Gefangenschaft zu entgehen nichts unversucht lassen.\n\nEr wird sich nur auf Euch konzentrieren, <Name>. Ich muss Euch deshalb zu der Begleitung von einigen Gefährten raten, die fähig genug sind, um Euch am Leben zu erhalten!", progress = "Hm? Nun?", completion = "Ihr habt meine Anweisungen befolgt. Das Wissen von der Beschwörung und Kontrolle des Biests kann nun endlich an Euch weitergegeben werden.", rewards = "Ihr erlernt:\n\nVerdammniswache beschwören\n\nIhr bekommt außerdem:\n\nFoliant der Opferung"}
MultiLanguageQuestData['de'][7601] = {title = "Nibys Anweisungen", objective = "Sprecht mit Impsy im Teufelswald.", description = "Wenn ich Euch das Geheimnis der Beschwörung eines Höllenbestiendieners lehren soll, so müsst Ihr Kroshius zerstören und mir den Höllenbestienkern seiner brennenden Überreste bringen. Wie auch immer, es ist nicht so einfach wie es klingt. Kroshius hat zwar alles, ist aber vollständig ausgebrannt. Ihr müsst seinen Körper wieder entzünden und ihn wieder von dem Schutthaufen auferstehen lassen. Allerdings braucht Ihr dafür ein paar Komponenten von anderen Dämonenwesen.\n\nImpsy, mein Wichtel, soll Euch auf alles weitere vorbereiten.", progress = nil, completion = "Junge, Junge, jetzt geht's los.", rewards = nil}
MultiLanguageQuestData['de'][7602] = {title = "Reine Teufelsessenz", objective = "Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\n\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den Verwüsteten Landen bergen die Teufelsessenz ihrer Region.\n\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.", description = "Ihr werdet für die Wiederbelebung von Kroshius Teufelsfeuer benötigen. Ich kann zwar Teufelsfeuer machen, brauche dazu aber ein paar Komponenten.\n\nIhr müsst mir reine Teufelsessenz aus drei bestimmten Gebieten der Welt bringen.\n\nDen ersten Essenztyp findet Ihr bei den Satyrn der Legashi von Azshara; den zweiten Typ bei den Legionären von Jaedenar in Jaedenar und den dritten bei den Wachposten der Teufelswache in den Verwüsteten Landen.\n\nBringt mir jeweils eine Essenz pro Typ, dann werde ich das Teufelsfeuer entfachen, mit dem Ihr Kroshius wieder auferstehen lassen könnt.", progress = "Sagt es keinem, aber Niby ist bescheuert.", completion = "Gebt mir einen Moment, damit ich die drei Essenzen kombinieren und somit das Teufelsfeuer entfachen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7603] = {title = "Kroshius Höllenbestienkern", objective = "Sucht im Narbengrund im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\n\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.", description = "Kroshius liegt zusammengefallen im Narbengrund, Richtung Nordosten. Verwendet dieses Teufelsfeuer auf seinen Überresten, es sollte die gefallene Höllenbestie wieder erwecken.\n\nIch bin überzeugt, dass er Euch und Euren Begleiter genau dann umbringen wird.\n\nSolltet Ihr Kroshius dennoch auf wundersame Weise töten können, dann nehmt den Höllenbestienkern und bringt ihn zu Niby.", progress = "Habt Ihr Euch verlaufen?", completion = "Geschäft ist Geschäft! Schnell, nehmt dies und schreibt dies nieder. Ich habe keine Zeit! Meine größte Beschwörung steht noch bevor!", rewards = "Ihr erlernt:\n\nHöllenbestie beschwören\n\nIhr bekommt außerdem:\n\nSplitter der grünen Flamme"}
MultiLanguageQuestData['de'][7604] = {title = "Ein verbindlicher Vertrag", objective = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Düsterfeilsch, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.", description = "<Der Unterzeichner/Die Unterzeichnerin> erklärt hiermit, dass es sich bei dem Sulfuronblock, der an die Thoriumbruderschaft (TB Ltd.) geliefert wird, um ein Original und nicht um eine Nachbildung handelt. <Der Unterzeichner/Die Unterzeichnerin> erkennt ebenso an, dass jeglicher Schaden, der <ihm/ihr> in Folge des Versuchs Sulfuras herzustellen, zu schmieden, verkaufen oder zu essen widerfahren könnte, nicht in der Verantwortung oder Verschuldung von TB Ltd. liegt.\n\nMit Unterzeichnung dieses Vertrags, wird allen darin aufgelisteten Bedingungen zugestimmt.\n\n_________________\n\nUnterschrift", progress = "Wie steht's mit unserer Abmachung?", completion = "Es war ein Vergnügen mit Euch Geschäfte zu machen, &lt;Name&gt;!\n\nIch wünsche Euch im Namen von TB Ltd. viel Glück bei Eurer Suche nach Sulfuras!", rewards = "Ihr bekommt:\n\nPläne: Sulfuronhammer"}
MultiLanguageQuestData['de'][7621] = {title = "Eine Warnung", objective = "<Klasse>, Ihr seid dabei eine entscheidene Reihe von Ereignissen zu durchleben, die alle Eure Fähigkeiten auf die Probe stellen sollen.\n\nIch schlage vor, dass Ihr Euch erst einmal anhört, was ich zu erzählen habe.\n\nLasst Euch gewarnt sein, Ihr müsst diese Aufgabe alleine lösen. Es ist ratsam, dass Eure Verbündeten Abstand halten. Die Einmischung anderer wird eine harte Bestrafung zur Folge haben.\n\nDas Schicksal hat Euch, Euch alleine, hierher geführt. Kämpft mit Ehre. Macht Euch das Licht zu Nutze.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][7622] = {title = "Die Waage von Licht und Schatten", objective = "Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Himmelsfeuer, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.\n\nKonsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden.", description = "Ihr müsst tun was ich nicht konnte: Rettet die Arbeiter, die während ihrer Flucht von Stratholme niedergemäht wurden.\n\nSie werden dem Licht entgegen laufen, sorgt für ihr Überleben. Sollten zu viele von ihnen fallen, wird unsere Existenz auch weiterhin verdammt sein - und Ihr werdet versagt haben.\n\nAlle von Euch gelernten Fähigkeiten, Gebete und Zauber werden auf die Probe gestellt werden. Möge das Licht Euch beschützen, <Name>.", progress = "Werdet Eurem Schicksal gerecht, <Name>.", completion = "Eure Hartnäckigkeit und Euer Mut sind verblüffend, &lt;Klasse&gt;. Ihr habt Euch das Recht den Splitter von Nordrassil tragen zu dürfen verdient. Es gilt nur noch eines zu tun: erlangt das Auge der Schatten wieder. Durchstreift die Welt danach.", rewards = "Ihr bekommt:\n\nSplitter von Nordrassil"}
MultiLanguageQuestData['de'][7623] = {title = "Lord Schattenfluch", objective = "Erwerbt schattenhafte Tränke von Gorzeeki Wildaug beim Altar der Stürme in der Brennenden Steppe.\n\nBenutzt die Tränke um durch Jaedenar im Teufelswald zu reisen und sprecht mit Lord Schattenfluch in der Schattenfeste.", description = "Mor'zul sagte mir, dass Ihr ein Portal nach Xoroth öffnen möchtet. Für eine solche Aufgabe werdet Ihr xorothianischen Sternstaub benötigen und der ist nur schwer in Azeroth zu finden!\n\nAber es gibt jemanden, der welchen besitzen sollte: Lord Schattenfluch in Jaedenar, dem Sitz des Schattenrats! Sprecht mit ihm und vielleicht wird er Euch etwas Sternenstaub überlassen.\n\nDoch wenn Ihr nach Jaedenar wollt, solltet Ihr Euch mit dem gleichen Aroma des Bösen, das den Schattenrat umgibt, tarnen. Dazu werdet Ihr einige meiner schattenhaften Tränke brauchen und die sind nicht umsonst...", progress = nil, completion = "Meine Geduld umspannt Jahrtausende, &lt;Klasse&gt;. Aber glaubt nicht das ich Euch mehr als einen kurzen Augenblick meiner Zeit widmen werde...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7624] = {title = "Ulathek der Verräter", objective = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Schattenfluch in Jaedenar.", description = "Ihr wollt meine Gunst erlangen? Dann tötet für mich.\n\nMein Diener Ulathek treibt ein erbärmliches Spiel, während er wie ein elender Wurm vor mir kriecht, konspiriert er heimlich mit Lord Hel'nurath von Xoroth. Hel'nurath trachtet danach meine Macht an sich zu reißen und Ulathek ist sein Spion...\n\nBeweist mir, dass Ihr mir und nicht meinem Rivalen dient. Stellt Ulathek in seinem Quartier, der Schattenfeste im Osten. Macht ihm klar, dass ich sein kleines Geheimnis kenne und seht wie die Angst von ihm Besitz ergreift. Bringt mir anschließend das Herz des Verräters!", progress = "Ich schmecke bereits Ulatheks Herz. So süss ist das Herz des Verräters...", completion = "Herrlich! Nach einer Woche des Verfaulens, wird dieses Herz eine saftige Gaumenfreude sein! Vielleicht lasse ich mir noch Ulatheks Kopf bringen und platziere ihn vor mich, während ich esse...\n\nIhr habt mir einen großen Dienst erwiesen, &lt;Klasse&gt; und meine Achtung vor Euch ist gestiegen, wenn auch nur unwesentlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7625] = {title = "Xorothianischer Sternenstaub", objective = "Erwerbt xorothianischen Sternenstaub von Ur'dan tief im Inneren der Schattenfeste in Jaedenar im Teufelswald. Bringt es anschließend Gorzeeki Wildaug in der Brennenden Steppe.", description = "Ihr kommt also zu mir, weil Ihr xorothianischen Sternenstaub sucht? Ihr möchtet ein Portal nach Xoroth, dem Herrschaftsgebiet meines Rivalen Hel'nurath öffnen? Vielleicht plant Ihr sogar eines seiner geliebten Schreckensrösser zu stehlen?\n\nNun gut. Mein Diener Ur'dan hat einen Vorrat an Sternenstaub. Ihr könnt es von ihm bekommen... wenn ihr den Preis bezahlen könnt.", progress = "Wahrt Ihr schon in Jaedenar, <Name>? Habt Ihr den Sternenstaub von Lord Banehollow bekommen?", completion = "Ihr habt ihn! Ich kann kaum glauben, dass Ihr ihn bekommen habt! Wie habt Ihr das geschafft? Seid Ihr einen Handel mit dem Schreckenslord eingegangen oder habt Ihr ihm ein Vermögen für den Sternenstaub angeboten? Vielleicht sogar beides?\n\nMor'zul wird seine Tinte schon bald haben und kann dann die Glyphenschriftrolle herstellen, mit deren Hilfe Ihr ein Portal nach Xoroth öffnen könnt, um eines der gefürchteten Schreckensrösser hindurch zu locken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7626] = {title = "Die Glocke von Dethmoora", objective = "Bringt 2 Elixiere der Schattenmacht zu Gorzeeki Wildaug in die Brennende Steppe.", description = "Um einen mächtigen Beschwörungskreis herzustellen, benötigt man eine Glocke von Dethmoora, benannt nach dem uralten Hexenmeister Dethmoora Finsteraugen. Richtig abgestimmt mit dem Rad und der Kerze, speichern diese Gegenstände riesige Mengen arkaner Macht.\n\nMein Assistent Gorzeeki kann eine solche Glocke herstellen, allerdings benötigt er dafür einen großen Vorrat an Elixieren der Schattenmacht. Besorgt Euch die Elixiere von einem Alchemisten und bringt sie Gorzeeki.", progress = "Habt Ihr die Elixiere, <Name>? Mor'zul sagte mir, dass Ihr eine Glocke von Dethmoora benötigt, doch um sie herzustellen bedarf es vieler Schattenenergien.", completion = "Sehr gut! Ich hoffe, Ihr hattet keine allzu großen Schwierigkeiten bei der Beschaffung der Elixiere. Manchmal sind Alchimisten sehr knauserig, wenn es um ihre Kreationen geht...\n\nIch werde die Glocke jetzt herstellen und sie aufbewahren, bis Ihr für das Ritual bereit seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7627] = {title = "Das Rad des Schwarzen Marsches", objective = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildaug in die Brennende Steppe.", description = "Ein Rad des Schwarzen Marsches enthält und kontrolliert die gefährlichen Energien, welche für das Ritual des mächtigen Beschwörungskreises benötigt werden. Um das Rad zu konstruieren, benötigt Gozeeki große glänzende Splitter von einem Verzauberer und Dunkeleisen von einem Meisterbergmann.\n\nBeschafft diese Gegenstände und bringt sie meinem Assistenten.", progress = "Es ist nicht leicht, ein Rad des Schwarzen Marsches herzustellen und es bedarf einer Vielzahl an Materialien. Habt Ihr alles bekommen?", completion = "Wie ich sehe, habt Ihr alles! Ich hörte, dass Dunkeleisenerz nur in den Blackrocktiefen zu finden ist, und ich bin mir sicher, dass es nicht viel einfacher war, an diese Splitter zu gelangen. Die Hingabe, mit der ihr &lt;Klasse&gt; Eurer Tätigkeit nachgeht, beeindruckt mich immer wieder. Ihr solltet Eure Energien lieber in die Kunst des Käferfangens investieren, oh... einen solchen Schmaus würdet Ihr lieben!\n\nEntschuldigt, ich schweife vom Thema ab. Ich werde das Rad jetzt herstellen und es aufbewahren, bis Ihr für das Ritual bereit seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7628] = {title = "Die Altarkerze des Jüngsten Gerichts", objective = "Bringt 3 Schuppen eines schwarzen Drachen zu Gorzeeki Wildaug in der Brennenden Steppe.", description = "Eine Altarkerze des Jüngsten Gerichts speichert Feuer in ihrem Inneren und schleudert es auf jeden, der versucht, Euer Ritual zu unterbrechen. Wenn Ihr das Ritual des mächtigen Beschwörungskreises aufbaut und die Kerze angezündet ist, wird sie jeden Dämon, der sich Euch in den Weg stellt, mit ihrer Flamme verbrennen.\n\nDieses spezielle Feuer einzufangen ist nicht einfach und erfordert die Essenz aus der Schuppe eines schwarzen Drachen. Beschafft Euch die Drachenschuppen und bringt sie zu Gorzeeki Wildaug.", progress = "Habt Ihr die Drachenschuppen dabei, <Name>? Ich möchte die Arbeiten an der Kerze nicht ohne sie beginnen... es könnte sonst passieren, dass ich versehentlich das ganze Lager in die Luft jage.", completion = "Ah, sehr gut. Ich brauche die Schuppen, um das Feuer der Kerze einzufangen. Da ich sie nun habe, kann ich die Kerze jetzt herstellen und aufbewahren, bis Ihr für das Ritual des mächtigen Beschwörungskreises bereit seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7629] = {title = "Wichtellieferung", objective = "Bringt den Wichtel im Glas in das Alchemielabor in Scholomance. Bringt das Glas nach der Herstellung des Pergaments zurück zu Gorzeeki Wildaug.", description = "Es gibt noch eine Sache die für Mor'zuls Pergament erledigt werden muss. Ich benötige Papier, welches mit xorothianischem Sternenstaub versetzt ist. Leider kann ich diese Prozedur hier nicht durchführen, da mir die Ausrüstung dafür fehlt!\n\nIch kenne aber ein Alchemielabor mit der nötigen Ausstattung. Es befindet sich in Scholomance, auf der Insel Darrowehr in den Pestländern.\n\nIch kann diese Reise nicht selber machen, aber nehmt dieses Gefäß. Im Inneren befindet sich ein äußerst intelligenter Wichtel. Lasst ihn frei, wenn Ihr im Alchemielabor angekommen seid und er wird die Prozedur mit dem Sternenstaub für Euch vornehmen.", progress = "Habt Ihr die Scholomance schon besucht, <Name>? Hat der Wichtel das Pergament mit dem Sternenstaub versetzt?", completion = "Herrvorragend! J'eevee konnte das Pergament also herstellen. Wie war Euer kleiner Ausflug nach Scholomance? Nettes Plätzchen, nicht wahr? Und diese leckeren Käfer dort... ich hörte sie sind deliziös!\n\nGut gemacht, &lt;Name&gt; und danke, dass Ihr mir mein Gefäß zurückgebracht habt. Ich habe es schon seid einer Ewigkeit... und es ist unverkäuflich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7630] = {title = "Arkanit", objective = "Bringt 1 Arkanitbarren zu Gorzeeki in der Brennenden Steppe.", description = "Nachdem die Glocke, das Rad und die Kerze jetzt fertiggestellt sind, muss sie jemand auf das Ritual vorbereiten. Ich besitze einen Wichtel, der die Vorbereitungen genau kennt... Ihr braucht nur noch ein Behältnis, um ihn zu transportieren.\n\nIch kann Euch ein solches Behältnis verkaufen, aber um es herzustellen brauche ich Arkanit. Habt Ihr welches? Falls nicht, solltet Ihr einen Alchemisten finden, der es für Euch herstellen kann.\n\nKommt zu mir zurück, wenn Ihr das Arkanit habt, dann verkaufe ich Euch den Wichtel im Glas!", progress = "Habt Ihr das Arkanit, <Name>? Sobald Ihr es habt, kann ich Euch ein neues Glas für J'eevee den Wichtel bauen.", completion = "Ihr habt es! Schön gemacht! Jetzt kann ich den Leitstein herstellen. Wenn Ihr schließlich für das Ritual und die Erstellung des mächtigen Beschwörungskreises bereit seid, werdet Ihr einen Leitstein wollen, um ein Fehlschlagen des Rituals verhindern zu können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7631] = {title = "Schreckensross von Xoroth", objective = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch.\n\nBereitgestellter Gegenstand: \n", description = "Alle Vorbereitungen sind getroffen. Als erstes müsst Ihr das Ritual des mächtigen Beschwörungskreises vollziehen. Anschließend benutzt die xorothianischen Glyphen um ein Portal nach Xoroth zu öffnen.\n\nIch habe Euch die Anweisungen für das Ritual auf eine Schriftrolle geschrieben. Studiert sie sorgfältig, denn wenn Ihr Erfolg haben wollt, müsst Ihr jeden Schritt exakt nach Anleitung durchführen.\n\nIch wünsche Euch viel Erfolg, <Name>. Und mögen die Seelen Eurer Feinde, den Weg in Euren Seelensteinbeutel finden.", progress = nil, completion = "Ihr habt den Geist des xorothianischen Schreckensrosses bezwungen. Obwohl Ihr den Hass in seinen Augen pulsieren seht, wisst Ihr, dass die Seele der Bestie nun Euch gehört...\n\nLeise flüstert es dunkle Magie in Euren Verstand und Ihr beginnt zu verstehen, wie man ein Schreckensross beschwört.", rewards = "Ihr erlernt:\n\nSchreckensross\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][7632] = {title = "Das uralte Blatt", objective = "Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, <Name>; die Welt ist groß.", description = "Die Epidermis des Blatts leuchtet hellgrün. Die Oberfläche ist extrem runzelig und weist etliche Adern und Falten auf.\n\nMan könnte vermuten, dass dieses Blatt von etwas sehr Altem und Mächtigem stammt.\n\nVielleicht solltet Ihr den ursprünglichen Besitzer dieses Blatts ausfindig machen?", progress = "<Vartrus stöhnt.>", completion = "Natürlich erkenne ich meine eigenen Blätter wieder. Schaut Euch das hier an! Es ist in perfektem Zustand.\n\nWie gut, dass Ihr es zurückgebracht habt, &lt;Klasse&gt;.\n\nVielleicht könnt Ihr uns ja noch einen Dienst erweisen und wir Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7633] = {title = "Eine Einführung", objective = "Euer Eifer und Eure Rechtschaffenheit wurden zur Kenntnis genommen, <Klasse>.\n\nWir sind die Uralten, Beschützer dieses einst bedeutenden Waldes. Unsere körperlichen Formen wurden vor 10.000 Jahren zerstört, als Archimonde und die Brennende Legion gegen Hyjal aufmarschierten. Dennoch, unsere Geister blieben unversehrt.\n\nWir haben Aufgaben zu vergeben. Werden diese erfüllt, so werden sie Euch die Geheimnisse der Uralten preisgeben.\n\nWisset, solltet Ihr diese Aufgaben vollenden, so kehrt lediglich zu diesem Felsen zurück und wir werden Euren Ruf erhören.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][7634] = {title = "Uraltes in Sehnen eingewickeltes Laminablatt", objective = "Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachen gebeten. Kehrt zu Hastat im Teufelswald zurück, solltet Ihr diese Sehne finden.", description = "Seid gegrüßt, <Klasse>. Ich bin Hastat, das Urtum der Lehren. Ich bewahre seit Ewigkeiten verlorenes Wissen.\n\nRichtig gebunden kann eines meiner Blätter als Köcher dienen, dergleichen wurde seit 10.000 Jahren nicht mehr gesehen. Ein Köcher, der - wenn er von einem Bogen der Uralten begleitet wird - ungeahnte Kräfte verleihen könnte.\n\nKehrt mit der Sehne eines ausgewachsenen, blauen Drachen hierher zurück und der Köcher möge Euer sein.", progress = "Abermals willkommen, junger <Klasse>.", completion = "Mögen meine Blätter Eure Pfeile vor Schaden schützen. Mögen Eure Pfeile genau treffen. Mögen die Feinde unserer Welt niedergestreckt werden.", rewards = "Ihr bekommt:\n\nUraltes in Sehnen eingewickeltes Laminablatt"}
MultiLanguageQuestData['de'][7635] = {title = "Die passende Sehne", objective = "Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachen gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück.", description = "Vartrus wird Euch womöglich den Holzstab für die Erstellung eines Bogens der Uralten geben. Allerdings kann nur ich die benötigte Sehne verzaubern, die den Bogen vervollständigt.\n\nEs ist eine einfache Aufgabe, mickriges Geschöpf. Tötet einen ausgewachsenen, schwarzen Drachen und entfernt eine Sehne von seinen Knochen. Bringt mir diese Sehne und ich werde das Material in eine fast unzerstörbare Bogensehne verzaubern.", progress = "Ich bin mir sicher, dass Euch das Auffinden und Töten eines schwarzen Drachens nicht leicht fallen wird, <Name>. Verschwendet meine Zeit nicht mit nutzlosem Gerede.", completion = "Das war wohl ein ganz garstiger Drache. Die Sehne stinkt nach Bösen.\n\nGebt mir einen Moment Zeit, damit ich das Fleisch von dem Schmutz säubern  und die passenden Zauber anwenden kann.", rewards = "Ihr bekommt:\n\nVerzauberte Schwarzdrachensehne"}
MultiLanguageQuestData['de'][7636] = {title = "Holzstab der Uralten", objective = "Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:\n\nSimone die Verführerin.\n\nKlinfran der Wahnsinnige.\n\nSolenor der Schlächter.\n\nArtorius der Verhängnisvolle.\n\nVernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.\n\nHaltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.\n\nIhr MÜSST diese Aufgabe eigenständig erledigen.", description = "Agenten der Brennenden Legion sind noch immer in unserer Welt aktiv, <Klasse>. Diese Agenten verderben alles, was ihnen unterkommt. Die Natur welkt und siecht in ihrer Gegenwart dahin.\n\nIhr müsst diese dämonischen Verderber aufspüren und zerstören, <Name>. Seid gewarnt, Ihr müsst sie selbst angreifen, andernfalls werden sie fliehen. Solange Ihr alleine seid, werden sie versuchen Euch zu zerstören. Ihr müsst sie bekämpfen und ihren Hochmut zu ihrem Verderben werden lassen.\n\nIch gewähre Euch ein Stück meiner Rinde, mögen die Inschriften Euch zu Eurem Ziel führen.", progress = "Lasst Euch nicht von ihren Verkleidungen täuschen!", completion = "Ihr habt uns einen großen Dienst erwiesen, &lt;Name&gt;! Nehmt diesen Holzstab und kombiniert ihn mit der Bogensehen, zu deren Fertigung Stoma fähig ist. Zusammen ergibt sich daraus eine vorzügliche Waffe.", rewards = "Ihr bekommt:\n\nAntiker runenverzierter Stab"}
MultiLanguageQuestData['de'][7637] = {title = "Ein Opfer darbieten", objective = "Reist nach Eisenschmiede und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen.", description = "Um Euch auf diese Aufgabe vorzubereiten, müsst Ihr Eure Opferbereitschaft und Euer Urteilsvermögen beweisen... die Betonung liegt hier besonders auf 'opfern'.\n\nIhr benötigt Hohepriester Rohans Weihrauchschwenker für die kommende Aufgabe. Und obwohl Ihr damit gutes bewirken werdet, müsst Ihr etwas zum Ausgleich hergeben.\n\nBegebt Euch nach Eisenschmiede und sprecht dort mit dem Hohepriester. Nehmt reichlich Münzen mit, um ihm den Verlust seines Weihrauchschwenker zu vergelten und um Euren Opferwillen zu zeigen.\n\nGeht nun, <Name>, denn Zeit ist hier ein wichtiger Faktor.", progress = "Seid gegrüßt, nobler <Klasse>! Ich habe meinen Weihrauchschwenker mit dem allerbesten Weihrauch vorbereitet und ihn für Euch dreifach gesegnet. Eure Spende wird uns hier in Ironforge nicht nur helfen einen neuen Schwenker herzustellen, sondern uns auch dabei helfen, die sinkenden Nahrungsvorräte für unsere Armen wieder aufzufüllen.", completion = "Seid gesegnet, werter &lt;Klasse&gt;. Eure Spende ist weit höher als es nötig gewesen wäre. Euer Opfer kompensiert nicht nur unseren Verlust, es hilft uns auch dabei den Armen und Bedürftigen hier in Ironforge zu helfen.\n\nNun lasst uns sicherstellen, dass ich den Schwenker auch ausreichend für Eure zukünftigen Bedürfnisse vorbereitet habe.", rewards = nil}
MultiLanguageQuestData['de'][7638] = {title = "Lord Grayson Schattenbruch", objective = "Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind.", description = "<Name>, der Zeitpunkt ist nun gekommen, an dem Ihr lernen werdet, was Ihr tun müsst, um etwas zu bekommen, auf das Ihr bestimmt schon lange gewartet habt... Euer eigenes Streitross. Sprecht mit Lord Grayson Schattenbruch, hier im Kathedralenviertel von Sturmwind. Er wird Euch nicht nur in die Geheimnisse des treuesten Begleiters eines Paladins einweihen, sondern er wird Euch auch durch die Prüfungen führen, die Ihr absolvieren werdet, um Euer eigenes Streitross zu erhalten.\n\nIch wünsche Euch viel Glück mit dieser Prüfung. Für das Licht, <nobler Bruder/noble Schwester>!", progress = nil, completion = "Ich bin froh Euch zu sehen, &lt;Name&gt;. Ich weiß das Ihr lange auf eine Nachricht gewartet habt, wie Ihr an Euer Streitross gelangt und nun ist die Zeit gekommen.\n\nIhr werdet die verschiedensten Prüfungen absolvieren müssen, doch am allermeisten sollt Ihr Euren Willen beweisen, über all den Hindernissen zu stehen, die Euch in Zukunft erwarten werden. Doch diese Prüfungen sind nicht theoretischer oder theologischer Natur. Ihr werdet Euren zukünftigen Begleiter aus den Fängen des Bösen befreien, das Ihr schon so lange bekämpft.\n\n Gebt Acht, Eure Zeit ist nun gekommen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7639] = {title = "Lass Gerechtigkeit walten", objective = "Bringt den Weihrauchschwenker zu Lord Grayson Schattenbruch in Sturmwind zurück.", description = "Nehmt diesen Weihrauchschwenker mit meinem Segen. Ich selbst habe ihn schon für dutzende Exzorzismen benutzt. Er wird Euch, bei den vor Euch liegenden Aufgaben, gut dienen.\n\nKehrt nun zu Lord Grayson Schattenbruch in Sturmwind zurück, <Name>. Ihr müsst Eure Suche mit seiner Hilfe fortsetzen.", progress = "Willkommen zurück, <Name>. Habt ihr den Weihrauchschwenker erhalten?", completion = "Ja, das wird gehen. Während der vor Euch liegenden Prüfungen werdet Ihr mehr als einmal Eure Opferbereitschaft beweisen müssen. Ich bin froh das Ihr dazu bereit seid. Opferbereitschaft ist eine der grundlegensten Eigenschaften die man besitzen muss, um den Pflichten eines Paladins nachkommen zu können... ich denke, was das betrifft, muss ich Euch keine Lektion mehr erteilen. Am Ende, ist dieser Weihrauchschwenker das Werkzeug, mit dem Ihr Gerechtigkeit walten lassen werdet, unter all den gequälten Seelen, in den für uns verlorenen Ländereien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7640] = {title = "Der Exorzismus des Schreckenstals", objective = "Vertreibt mithilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind zurück.", description = "Ich habe ein wenig von der verdorbenen Erde des Schreckenstals, aus den Östlichen Pestländern, in den Weihrauchschwenker getan. Benutzt den Schwenker, um Gebiete die von spiritueller Unruhe und Störungen befallen sind, ausfindig zu machen. Haltet nach grünen Auren Ausschau, die die Erde durchziehen, während sich die materielle Welt unter den Qualen der Spirituellen Ebene verzerrt. Benutzt dort den Weihrauchschwenker, um die Geister des Bösen zu vertreiben.\n\nHabt Ihr erst einmal genug Gerechtigkeit unter den Geistern walten lassen, seid Ihr bereit für Euren weiteren Weg.", progress = "Es ist schön Euch wiederzusehen, <Name>. Habt Ihr Eure Aufgabe im Schreckenstal abgeschlossen?", completion = "Gut gemacht, &lt;Name&gt;. Denen, die in der Dunkelheit leben, die Gerechtigkeit des Lichts zu bringen, ist eine Aufgabe der wir uns mit Leib uns Seele verschrieben haben. Durch Euer Opfer in Ironforge und durch das Richten der Geister im Schreckenstal, habt Ihr genau dies getan.\n\nDer nächste Schritt erfordert sowohl Aufopferung, als auch das Wirken von Gerechtigkeit. Ihr werdet losziehen um den Geist eines gefallenen Streitrosses zu erlösen, welches nun dem Todesritter Schattensichel dient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7641] = {title = "Grimand Elmores Werk", objective = "Sprecht mit Grimand Elmore im Zwergendistrikt von Sturmwind.", description = "Ohne ein angemessenes Pferdegeschirr, ist das Streitross eines Paladins nichts weiter als ein Packesel. Das Pferdegeschirr für Euer Streitross sollte aus den bestmöglichem Material gefertigt sein und in Eurem speziellen Fall muss es auch noch mit der spirituellen Ebene abgestimmt werden.\n\nAber zuerst einmal muss Euer Pferdegeschirr gefertigt werden. Im Zwergendistrikt lebt einer der besten Schmiede unserer Zeit, Grimand Elmore. Seine Arbeit wird zwar nicht gerade billig sein, aber seine Qualität ist genau das, was wir suchen. Sprecht mit ihm.", progress = nil, completion = "Hallo da, Kumpel - Lord Shadowbreaker hat mich von Eurer Ankuft informiert und das Ihr mich sehen wollt. Ich werde Euch das Pferdegeschirr anfertigen. Aber um eines klarzustellen, es wird weder einfach noch billig sein.\n\nIch werde nur das eine sagen, und Grayson wird mir zustimmen... Nirgendwo in ganz Azeroth werdet Ihr ein besseres Pferdegeschirr finden, als hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7642] = {title = "Fünf Dinge", objective = "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Arthas' Tränen, 5 Phiolen Weihwasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Sturmwind.", description = "Ich benötige vier Dinge für das Pferdegeschirr - Runenstoff für das Innenfutter, Arkanitbarren für die Panzerung, Arthas' Tränen für den spirituellen Einklang und Weihwasser aus Stratholme zur spirituellen Stärkung. Nun, genau genommen braucht Ihr noch eine fünfte Sache... Gold, um mich zu bezahlen. Die Bezahlung umfasst alle anfallenden Arbeiten sowie einen handgemachten Sattel und Steigbügel.\n\nWenn Ihr alles gebracht habt, kann ich Euer Pferdegeschirr fertigstellen. Bis Ihr alle Sachen beisammen habt, werde ich schon einmal einige der Arbeiten für Euch erledigen können.", progress = "Ah, <Name>. Ich kann Euer Pferdegeschirr erst fertigstellen, wenn Ihr mir die Sachen bringt um die ich Euch gebeten habe. Habt Ihr alles beisammen?", completion = "Das... nun, es ist alles was ich brauche. Ihr seid ein ganz schön einfallsreicher &lt;Klasse&gt;, oder?\n\nOk, dann machen wir mal Euer Pferdegeschirr fertig.", rewards = nil}
MultiLanguageQuestData['de'][7643] = {title = "Der uralte Pferdegeist", objective = "Beschafft spezielles Pferdefutter, mit dem man ein Geisterpferd füttern kann. Merideth Carlson in Süderstade scheint dafür eine recht gute Quelle zu sein.\n\nReist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen.", description = "Euer Pferdegeschirr braucht eine ganz spezielle Form von Segnung durch einem geeigneten Geist. In Düsterbruch findet Ihr einen solchen Geist, den uralten Pferdegeist. Er ist im Besitz eines verdorbenen Treants namens Tendris Wucherborke. Richtet dieses verdorbene Biest, <Name>.\n\nDoch wisset eines - Freiheit ist nicht alles. Ihr müsst den Geist erst beschwichtigen, wenn Ihr seinen Segen wollt. Dafür werdet Ihr ein spezielles Pferdefutter benötigen. Reist zuerst nach Süderstade und sprecht mit Merideth Carlson über diese Sache... und bereitet Euch auf weitere Opfer vor.", progress = "Der uralte Pferdegeist sieht Euch erwartungsvoll an, es scheint als wollte er etwas von Euch.", completion = "Der uralte Pferdegeist akzeptiert das von Euch angebotene mit Mana angereichertes Pferdefutter. Nachdem es etwas von dem Futter gegessen hat, scheint es auf Euer Pferdegeschirr zu blicken, als wolle es, dass Ihr es ihm anlegt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7644] = {title = "Gesegnetes Arkanitpferdegeschirr", objective = "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Schattenbruch in das Kathedralenviertel von Sturmwind zurück.", description = "Während Ihr dem uralten Pferdegeist das Pferdegeschirr anlegt, beginnt dieses langsam zu leuchten. Die Luft ist erfüllt von diesem heiligen Moment. Urplötzlich verschwindet das Pferdegeschirr und erscheint wieder in Eurem Rucksack.\n\nEs scheint so, als wäre das Pferdegeschirr wahrhaftig gesegnet. Entsprechend Lord Schattenbruchs Anweisungen müsst Ihr nun mit ihm nach Sturmwind zurückkehren.", progress = "<Name>, Ihr seid zurück! Seid Ihr mit Meridith Carlson und Tendris Wucherborke zurechtgekommen? Ehrlich gesagt weiß ich nicht, wer von den beiden die größere Gefahr darstellt.", completion = "Ihr seid weit gekommen, mein Freund. Das Pferdegeschirr ist nun bereit für die letzte Aufgabe.\n\nSattelt das Streitross mit dem Pferdegeschirr, nachdem Ihr die Aufgabe der Erlösen abgeschlossen habt. Doch zuvor habt Ihr noch einen großen Kampf zu bestehen. Eure Zeit ist gekommen - Huzzah!\n\nEs muss noch ein letzter Gegenstand gefertigt werden, bevor wir anfangen können, &lt;Name&gt;. Hoffentlich verfügt Ihr noch über soviele Mittel wie damals, als ich Euer Pferdegeschirr gefertigt habe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7645] = {title = "Mit Manna angereichertes Pferdefutter", objective = "Treibt 20 angereicherte Mannakekse - die ausschlaggebende Zutat für die Herstellung von mit Manna angereichertem Pferdefutter - für Merideth Carlson aus Süderstade im Vorgebirge des Hügellands auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt.\n\nZusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen.", description = "Die Silberne Hand hielt mich für VERRÜCKT, als ich erzählte, dass ich spezielles Pferdefutter für spirituelle Pferde herstellen könnte. ALLE dachten, ich sei verrückt! Nun, der Tag meiner Revanche ist gekommen!\n\nIch werde herstellen, was Ihr braucht, PALADIN... sogenannter HELD... allerdings wird es Euch einiges kosten. Ich brauche für diese Mischung spezielle Kekse - angereicherte Mannakekse, die nur von der Argentumdämmerung verkauft werden. Außerdem fordere ich - ja, ich FORDERE - Gold als Entschädigung für mein erlittenes Elend!\n\nBringt mir das Opfer, zu dem Ihr so oft aufruft, PALADIN.", progress = "Habe ich Euch jetzt vom Gegenteil überzeugt, ja? Sie hatten alle Unrecht! ICH WAR SCHON DIE GANZE ZEIT IM RECHT!!!", completion = "JA, JETZT... wartet... Ihr gebt mir auch das Gold? Zwar wart es nicht Ihr, die mich eine Verrückte nannten… oder genauer gesagt eine komplett durchgeknallte Spinnerin… dennoch bin ich erstaunt, dass Ihr dazu bereit seid, Opfer für Fehler aufzubringen, an denen Ihr selbst keine Schuld tragt.?\n\nIch... ich habe Euch falsch eingeschätzt. Solltet Ihr noch mehr Pferdefutter benötigen, so kommt zu mir. Ich werde es Euch umsonst geben. Danke... großmütiger &lt;Klasse&gt;.\n\nIch werde das Geld trotzdem behalten - ich bin nicht so verblödet, als dass ich ein Vermögen aufgeben würde.", rewards = "Ihr bekommt:\n\nMit Manna angereichertes Pferdefutter"}
MultiLanguageQuestData['de'][7646] = {title = "Das Orakel der Anrufung", objective = "Bringt Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.", description = "Als nächstes müssen wir ein Orakel der Anrufung erschaffen - Damit wird Eure Prüfung beginnen, an dessen Ende Ihr das gefallene Streitross erlösen werdet. Euer Orakel ist schon beinahe vollständig. Der von Euch im Schreckenstal eingesetzte Weihrauchschwenker wird als Katalysator für das Orakel dienen und ich werde Euch ein passendes Gehäuse für das Gerät anfertigen.\n\nDie letzten noch benötigten Komponenten sind zwei Diamanten. Sie müssen von reinster Qualität sein und gleichermaßen gut ihren Zweck erfüllen - ein azerotischer und ein schwarzer Diamant. Zusammen werden diese beiden das Leuchtfeuer sein, mit dessen Hilfe das Orakel die Schatten zerschneiden wird.", progress = "Ihr seid schon sehr weit gekommen, <Name>. Der letze Akt einer weltlichen Opferung, wird der Beginn eines Euerer größten Leistungen sein. Ich kann es im innersten meiner Seele spüren!", completion = "Dies sind fantastische Exemplare, &lt;Name&gt; - Die letzten Teile habe ich angebracht. Zu guter Letzt, ist Eure Zeit gekommen!\n\n In den Tiefen des großen Ossuariums von Scholomance liegen die Überreste vieler Wesen. Unter ihnen befindet sich ein einst nobles Streitross. Die gequälte Seele dieses Streitrosses dient nun dem Todesritter Schattensichel. Ihm werdet Ihr Euch stellen müssen, und es ist sein Ross dem Ihr Gerechtigkeit wiederfahren lassen werdet. Nur Ihr, &lt;Name&gt; könnt diese Seele erlösen und es aus den Qualen seiner Knechtschaft befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7647] = {title = "Gerechtigkeit und Erlösung", objective = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des Großen Ossuariums in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das Besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses.\n\nGebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück.", description = "Nehmt diese Tasche – in ihr befinden sich alle Gegenstände, die Ihr für Eure Aufgabe brauchen werdet.\n\nBenutzt das Orakel der Anrufung im Herzen des Kellergewölbes des Großen Ossuariums, um die verfluchten Geister zu rufen, über deren Schicksal gerichtet werden muss. Benutzt Eure Richturteile während dieser Prüfung weise – sie werden weit wirksamer sein, als Ihr es Euch vorstellen könnt. Nach diesen Geistern wird der Todesritter erscheinen. Besiegt ihn und fordert die verlorene Seele des Streitrosses. Nur dann werdet Ihr in der Lage sein, es zu erlösen und Eurem neuen Reittier Euer Zaumzeug anlegen zu können!\n\nViel Glück!", progress = "Der Geist des gefallenen Streitrosses blickt Euch voller Trauer an. Traurige, ja fast leere Augen blicken Euch an, als sei jede Hoffnung verloren.", completion = "Ein Lebensfunke erstrahlt in den Augen des armen Tieres als Ihr ihm seine verlorene Seele zurückgebt. Ihr fühlt die plötzliche Präsenz heiliger Energien um Euch und legt Ihm das Pferdegeschirr an. Das Streitross schnüffelt neugierig an Eurer Hand und die Bürden der Vergangenheit scheinen von ihm gewichen zu sein. Ihr fühlt, dass Ihr dieses Pferd jederzeit herbeirufen könnt, solltet Ihr seine Hilfe brauchen.\n\nIhr habt Euer episches Streitross erhalten, &lt;Klasse&gt;. Gratulation!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7648] = {title = "Grimands feinste Arbeit", objective = "Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind.", description = "<Grimand wischt sich Schweiß von seinen Brauen und strahlt stolz.>\n\nDa wären wir, <mein Freund/meine Freundin>. Dies ist eine meiner besten Arbeiten - so gut wie das Pferdegeschirr, das ich persönlich für Lord Schattenbruch gefertigt habe, als dieser sich für sein eigenes Streitross aufmachte. Ich danke Euch für Euer Vertrauen in mein Können.\n\nGrayson wird diese Arbeit zweifellos auch sehen wollen. Bringt Euer Pferdegeschirr zu ihm und richtet ihm meinen Dank für die ehrenvollen Geschäfte mit ihm aus.", progress = "Ihr kommt gut voran, <Name>. Sobald Euer Pferdegeschirr fertiggestellt ist, werdet Ihr die nächste Aufgabe angehen können.", completion = "Das ist die beeindruckendste Arbeit, die ich je gesehen habe. Es scheint, dass Grimands handwerkliches Können mit dem Alter immer besser wird. Es ist eine beachtliche Leistung, wenn man bedenkt, dass seine Arbeiten bereits zu den besten zählten, als er damals mein Pferdegeschirr anfertigte.\n\nObwohl dieses Geschirr auch eine schöne Bereicherung für jedes normale Pferd darstellen würde, geben wir uns nicht mit derartig alltäglichen Geschöpfen ab. Ihr müsst dieses Geschirr auf entsprechende Weise segnen lassen, auf dass es würdig genug ist, um einem &lt;Klasse&gt;-Streitross angelegt zu werden. Bis dahin werde ich es für Euch aufbewahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7649] = {title = "Verzauberter Thoriumplattenpanzer: Band I", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n&lt; Lydros reißt eine Seite aus dem Buch&gt; \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept.", rewards = "Ihr bekommt:\n\nPläne: Verzauberte Thoriumbrustplatte"}
MultiLanguageQuestData['de'][7650] = {title = "Verzauberter Thoriumplattenpanzer: Band II", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n&lt; Lydros reißt eine Seite aus dem Buch&gt; \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept.", rewards = "Ihr bekommt:\n\nPläne: Verzauberte Thoriumgamaschen"}
MultiLanguageQuestData['de'][7651] = {title = "Verzauberter Thoriumplattenpanzer: Band III", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n&lt; Lydros reißt eine Seite aus dem Buch&gt; \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept.", rewards = "Ihr bekommt:\n\nPläne: Verzauberter Thoriumhelm"}
MultiLanguageQuestData['de'][7652] = {title = "Ein Sonderangebot", objective = "Okay, Junge, ich habe da ein heißes Angebot für dich.\n\n Ich habe hier einige Pläne zur Herstellung von imperialen Plattenrüstungen, die ich gerne loswerden möchte. Das einzige, was ich als Gegenleistung verlange, sind einige Thoriumbarren. Klingt doch gut, oder?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][7653] = {title = "Imperialer Plattengürtel", objective = "Das macht 20 Thoriumbarren für die Pläne des Plattengürtels, Junge.", description = nil, progress = "Das macht 20 Thoriumbarren für die Pläne des Plattengürtels, Junge.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperialer Plattengürtel"}
MultiLanguageQuestData['de'][7654] = {title = "Imperiale Plattenstiefel", objective = "Thoriumbarren, Junge. Genau 40! Heulst du gleich? Soll ich dich in den Arm nehmen?\n\n<Malyfous lacht lauthals.>", description = nil, progress = "Thoriumbarren, Junge. Genau 40! Heulst du gleich? Soll ich dich in den Arm nehmen?\n\n<Malyfous lacht lauthals.>", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperiale Plattenstiefel"}
MultiLanguageQuestData['de'][7655] = {title = "Imperiale Plattenarmschienen", objective = "Du willst die Pläne für die Armschienen? Das ganze kostet dich nur 20 Thoriumbarren.", description = nil, progress = "Du willst die Pläne für die Armschienen? Das ganze kostet dich nur 20 Thoriumbarren.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperiale Plattenarmschienen"}
MultiLanguageQuestData['de'][7656] = {title = "Imperiale Plattenrüstung", objective = "Junge, für die Pläne der Plattenrüstung krieg' ich 60 Thoriumbarren. \n\nJetzt geht das wieder los. Gleich rennst du wohl wieder zu deinen ach so mächtigen Göttern und jammerst! Stell dich nicht so an, Weichei! Niemand hat behauptet, dass das Leben fair wäre!", description = nil, progress = "Junge, für die Pläne der Plattenrüstung krieg' ich 60 Thoriumbarren. \n\nJetzt geht das wieder los. Gleich rennst du wohl wieder zu deinen ach so mächtigen Göttern und jammerst! Stell dich nicht so an, Weichei! Niemand hat behauptet, dass das Leben fair wäre!", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperiale Plattenrüstung"}
MultiLanguageQuestData['de'][7657] = {title = "Imperialer Plattenhelm", objective = "Gib mir einfach 50 Thoriumbarren und die Pläne für den Helm gehören dir.", description = nil, progress = "Gib mir einfach 50 Thoriumbarren und die Pläne für den Helm gehören dir.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperialer Plattenhelm"}
MultiLanguageQuestData['de'][7658] = {title = "Imperiale Plattengamaschen", objective = "Reich mir einfach 60 Thoriumbarren 'rüber und die Pläne für die Gamaschen gehören dir. \n\n Ja, ja ich bin dein Ruin. Diese Geschichten muss ich mir jedes mal anhören. Also spar dir den Mist, Weichei.", description = nil, progress = "Reich mir einfach 60 Thoriumbarren 'rüber und die Pläne für die Gamaschen gehören dir. \n\n Ja, ja ich bin dein Ruin. Diese Geschichten muss ich mir jedes mal anhören. Also spar dir den Mist, Weichei.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperiale Plattengamaschen"}
MultiLanguageQuestData['de'][7659] = {title = "Imperiale Plattenschultern", objective = "Du willst die Pläne für die Plattenschultern? Das macht 20 Thoriumbarren.", description = nil, progress = "Du willst die Pläne für die Plattenschultern? Das macht 20 Thoriumbarren.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und &lt;Name&gt;... spar' dir diesen abfälligen Blick!", rewards = "Ihr bekommt:\n\nPläne: Imperiale Plattenschultern"}
