MultiLanguageQuestData['de'][7664] = {title = "Austausch Eures elfenbeinfarbigen Raptors", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchneller blauer RaptorSchneller olivfarbener RaptorSchneller orangefarbener Raptor"}
MultiLanguageQuestData['de'][7665] = {title = "Austausch Eures roten Raptors", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchneller blauer RaptorSchneller olivfarbener RaptorSchneller orangefarbener Raptor"}
MultiLanguageQuestData['de'][7666] = {title = "Erneut im Großen Ossuarium", objective = "Wart Ihr schon zurück in Scholomance, <Name>? Ihr habt bereits teuer für die Verwendung des Orakels der Anrufung bezahlt - vielleicht möchtet Ihr ja noch ein weiteres mit Euch nehmen. Ihr wäret damit in der Lage, Euch den Gefahren des großen Ossuariums erneut zu stellen.\n\nFür alle Fälle, hier habt Ihr es. Ihr habt es Euch redlich verdient.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nOrakel der Anrufung"}
MultiLanguageQuestData['de'][7667] = {title = "Materielle Unterstützung", objective = "Wenn Ihr Sagorne Gratläufer im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothischen und einen makellosen schwarzen Diamanten.", description = "<Name>, es gibt da eine dringliche Angelegenheit und ich hoffe, dass Ihr mir dabei helfen könnt... im materiellen und geistigen Sinne. Lasst mich bitte erklären.\n\nTief in Scholomance in Lordaeron gibt es ein Gewölbe, das das Große Ossuarium genannt wird. Ich muss eine Vorrichtung fertigstellen, die die Schatten dieses entsetzlichen Raums durchbohren kann. Um zu beenden, womit ich begonnen habe, brauche ich zwei Diamanten: einen azerothischen und einen makellosen schwarzen Diamanten. Dies sind keine gewöhnlichen Objekte, ich weiß - aber ich verfüge nun einmal nicht selbst über die entsprechenden Mittel.\n\nKönntet Ihr mir jeweils einen von beiden beschaffen?", progress = "Es ist mir unangenehm, um materielle Unterstützung zu bitten, aber mein Orakel der Anrufung - die Vorrichtung, die ich fertigzustellen hoffe - benötigt jeweils einen von beiden. Wenn Ihr mir nicht helfen könnt, kann ich das natürlich verstehen.", completion = "Eure Großzügigkeit ist unbeschreiblich, &lt;Name&gt;. Ich danke Euch für Eure Güte.\n\nIch kann mein Orakel der Anrufung nun vollenden und sollte jetzt auch ohne weitere Diamanten mehr davon herstellen können... vielleicht interessiert es Euch ja, mir bei dessen Anwendung behilflich zu sein? Ich versichere Euch, es handelt sich dabei um eine wirklich wichtige Aufgabe... eine, die wenn sie unerledigt bleibt, auf der spirituellen Ebene eine riesige Katastrophe verursachen könnte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7668] = {title = "Die Bedrohung durch Schattensichel", objective = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des Großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar.", description = "Der Todesritter Schattensichel herrscht über das Große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen... Er muss gestoppt werden! Dabei kommt das Orakel der Anrufung, bei dessen Herstellung Ihr behilflich wart, zum Einsatz.\n\nSetzt das Orakel inmitten des Kellergewölbes des Großen Ossuariums ein, um Schattensichels Geistergefolge herbeizurufen. Besiegt die Geister und der Todesritter selbst wird erscheinen. <Name>, bringt mir seinen Kopf! Lediglich seine Niederlage wird den Schaden, den er der spirituellen Ebene zugefügt hat, wieder umkehren können!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm der latenten Macht"}
MultiLanguageQuestData['de'][7669] = {title = "Erneut im großen Ossuarium", objective = "Wart Ihr schon zurück in Scholomance, <Name>? Ihr habt bereits teuer für die Verwendung des Orakels der Anrufung bezahlt - vielleicht möchtet Ihr ja noch ein weiteres mit Euch nehmen. Ihr wäret damit in der Lage, Euch den Gefahren des großen Ossuariums erneut zu stellen.\n\nFür alle Fälle, hier habt Ihr es. Ihr habt es Euch redlich verdient.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nOrakel der Anrufung"}
MultiLanguageQuestData['de'][7670] = {title = "Lord Grayson Schattenbruch", objective = "Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind.", description = "<Name>, der Zeitpunkt ist nun gekommen, an dem Ihr lernen werdet, was Ihr tun müsst, um etwas zu bekommen, auf das Ihr bestimmt schon lange gewartet habt... Euer eigenes Streitross. Sprecht mit Lord Grayson Schattenbruch, im Kathedralenviertel von Sturmwind. Er wird Euch nicht nur in die Geheimnisse des treuesten Begleiters eines Paladins einweihen, sondern er wird Euch auch durch die Prüfungen führen, die Ihr absolvieren werdet, um Euer eigenes Streitross zu erhalten.\n\nIch wünsche Euch viel Glück mit dieser Prüfung. Für das Licht, <nobler Bruder/noble Schwester>!", progress = nil, completion = "Ich bin froh Euch zu sehen, &lt;Name&gt;. Ich weiß das Ihr lange auf eine Nachricht gewartet habt, wie Ihr an Euer Streitross gelangt und nun ist die Zeit gekommen.\n\nIhr werdet die verschiedensten Prüfungen absolvieren müssen, doch am allermeisten sollt Ihr Euren Willen beweisen, über all den Hindernissen zu stehen, die Euch in Zukunft erwarten werden. Doch diese Prüfungen sind nicht theoretischer oder theologischer Natur. Ihr werdet Euren zukünftigen Begleiter aus den Fängen des Bösen befreien, das Ihr schon so lange bekämpft.\n\n Gebt Acht, Eure Zeit ist nun gekommen!", rewards = "Ihr bekommt:\n\n"}
