MultiLanguageQuestData['de'][7807] = {title = "Spendet Wolle", objective = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung der Verbannten von Gnomeregan einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung der Verbannten von Gnomeregan einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7808] = {title = "Spendet Seide", objective = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7809] = {title = "Spendet Magiestoff", objective = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit bei den Verbannten von Gnomeregan nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit bei den Verbannten von Gnomeregan nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7810] = {title = "Meister der Arena", objective = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Störtebrecher.\n\nBereitgestellter Gegenstand: \n", description = "Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.", progress = nil, completion = "Aye, mein' Jung. Ein son' Schmuckstück is nich genuch, um Euch zum Meister der Arena zu machen! Jetz' is es an der Zeit Euch richtig zu beweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7811] = {title = "Spendet Runenstoff", objective = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", description = nil, progress = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten nicht unbeachtet bleiben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7812] = {title = "Noch mehr Runenstoff", objective = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber der Verbannten von Gnomeregan erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", description = nil, progress = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber der Verbannten von Gnomeregan erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "&lt;Name&gt; - ohne Helden, die sich wie Ihr für uns Gnome einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!", rewards = nil}
MultiLanguageQuestData['de'][7813] = {title = "Spendet Wolle", objective = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Undercity einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Undercity einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7814] = {title = "Spendet Seide", objective = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7815] = {title = "Schnappkiefer, Alter!", objective = "Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Salzwasserschnappkiefer tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", description = "Lass dich ja nicht von ihren großen Augen täuschen, Alter! Die Schnappkiefer da sind ne Bedrohung. Ich kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern mir meinen Köder klaut.\n\nTut mir und den Bruchhauern einen Gefallen und bringt sie um, Alter.\n\nBringt sie alle um!", progress = "Na, und wie läufts mit der Jagd?", completion = "Mensch Alter! Ich kann dir nicht genug danken! Hoffentlich ist diese Angelrute hier gut genug als Belohnung.", rewards = "Ihr bekommt:\n\nNat Pagles Extremangler FC-5000"}
MultiLanguageQuestData['de'][7816] = {title = "Gammerita, Alter!", objective = "Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt.\n\nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.", description = "Yo! Da is ne Schildkröte da draußen, die nicht wie die anderen is'. Das is' die Gammerita, Anführerin der Salzwasserschnappkiefer, 'ne richtig fiese Diebin!\n\nAlter, die hat mir meinen besten Köder geklaut. Einfach so abgebissen, hatse den! Seitdem beißen die Fisch nichmehr so an wie vorher.\n\nFinde Gammerita und hol' mir den Köder aus ihrem Bauch.", progress = "Haste ihn gefunden?", completion = "ALTER! Das ist fantastisch! Mit meinem besten Köder und ohne die Schnappkiefern da, kommen die Fische sicher in Scharen zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][7817] = {title = "Spendet Magiestoff", objective = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Undercity nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Undercity nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
