MultiLanguageQuestData['de'][8191] = {title = "Prophetische Aura", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Ihr bekommt:\n\nProphetische Aura"}
MultiLanguageQuestData['de'][8192] = {title = "Liebkosung des Animisten", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Ihr bekommt:\n\nLiebkosung des Animisten"}
MultiLanguageQuestData['de'][8193] = {title = "Die große Beute", objective = "Heute zwischen 14 Uhr und 16 Uhr findet der Wettbewerb statt, der den besten Angler unter uns ermitteln wird! Seid die ERSTE PERSON, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringt und Ihr werdet der neue Meisterangler sein!\n\nFalls Ihr nicht als Erster hier sein solltet, wird Euch mein Lehrling hier mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", description = nil, progress = "Heute zwischen 14 Uhr und 16 Uhr findet der Wettbewerb statt, der den besten Angler unter uns ermitteln wird! Seid die ERSTE PERSON, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringt und Ihr werdet der neue Meisterangler sein!\n\nFalls Ihr nicht als Erster hier sein solltet, wird Euch mein Lehrling hier mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr den Titel des Meisteranglers erwerben wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nArkanitangelruteAngelhaken des AnglermeistersSchreckenspiratenringStiefel der BuchtExtremgetestete Eterniumangelschnur\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8194] = {title = "Anglerlehrling", objective = "Wir haben zwar schon einen Gewinner ermittelt, aber ich kaufe Euch dennoch Eure restlichen Leckerfische ab. Ich zahl' Euch einen angemessenen Preis, na, was sagt Ihr!", description = nil, progress = "Wir haben zwar schon einen Gewinner ermittelt, aber ich kaufe Euch dennoch Eure restlichen Leckerfische ab. Ich zahl' Euch einen angemessenen Preis, na, was sagt Ihr!", completion = "Also für mich steht der Handel, wenn Ihr damit einverstanden seid!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8195] = {title = "Münzen der Razzashi, Hakkari und zulianische Münzen", objective = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", description = nil, progress = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", completion = "Ausgezeichnet - dieses Set Münzen ist eine feine Zugabe für unsere wachsende Sammlung... eine, die wir bei der Verteidigung unseres Stammes gegen die Auferstehung des Blutgottes einsetzen werden. Ihr habt Euch diese Ehrenmünze verdient, &lt;Name&gt;, genauso wie den Dank unseres Stammes!", rewards = "Ihr bekommt:\n\nEhrenmünze der Zandalari"}
MultiLanguageQuestData['de'][8196] = {title = "Essenzmangos", objective = "Die extrem wirksamen Essenzmangos wachsen auf vielen Inseln der südlichen Meere. Eine einzelne Mango erfrischt denjenigen, der davon isst, körperlich wie auch geistig. Solltet Ihr noch nie eine gekostet haben, dann erweist Ihr Euch damit keinen Dienst!\n\nHier auf der Insel verfügen wir über einen ausreichend großen Vorrat, um Euch ein paar davon im Austausch gegen eine zandalarianische Ehrenmünze geben zu können. Sprecht mit Vinchaxa, wenn Ihr wissen wollt, wie Ihr an Ehrenmünzen gelangt; ansonsten, lasst uns gleich Geschäfte machen!", description = nil, progress = "Die extrem wirksamen Essenzmangos wachsen auf vielen Inseln der südlichen Meere. Eine einzelne Mango erfrischt denjenigen, der davon isst, körperlich wie auch geistig. Solltet Ihr noch nie eine gekostet haben, dann erweist Ihr Euch damit keinen Dienst!\n\nHier auf der Insel verfügen wir über einen ausreichend großen Vorrat, um Euch ein paar davon im Austausch gegen eine zandalarianische Ehrenmünze geben zu können. Sprecht mit Vinchaxa, wenn Ihr wissen wollt, wie Ihr an Ehrenmünzen gelangt; ansonsten, lasst uns gleich Geschäfte machen!", completion = "Ein fairer Tausch, mein Freund. Bitte genießt die köstlichen Früchte der südlichen Meere, Ihr habt den Segen des Stammes.", rewards = "Ihr bekommt:\n\nEssenzmango"}
MultiLanguageQuestData['de'][8201] = {title = "Die Schädelsammlung", objective = "Reiht die Köpfe der 5 Kanalisierer auf der heiligen Kordel aneinander. Bringt dann die Trollschädelsammlung zu Exzhal auf der Insel Yojamba.", description = "Es ist wahr. Hakkar hat sich in Zul'Gurub eingenistet und badet in den Kräften unserer Götter. Von ihm kontrollierte Priester haben damit begonnen, die Energien unserer heiligsten Gottheiten auf den Seelenschinder zu kanalisieren. Seine Macht wird schon bald die aller Wesen in Azeroth übersteigen. Er muss aufgehalten werden!\n\nHier, nehmt diese heilige Kordel. Findet die Priester, die es wagen die Energien unserer Götter zu kanalisieren, und reiht ihre Köpfe auf dieser Kordel aneinander.\n\nKehrt anschließend zu mir zurück.", progress = "Habt Ihr die Schädelsammlung, <Name>? Wir müssen um jeden Preis verhindern, dass Hakkars Macht weiter wächst!", completion = "Ihr habt die Schädel! Euer Mut hat verhindert, dass Hakkar die Macht unserer Götter an sich reißt und ihn so geschwächt!\n\n&lt;Name&gt;, Euer Handeln ist wahrlich heldenhaft. Mögen die Schädel dieser Verräter noch lange nachdem ihr Blut erkaltet ist, um Eure Gnade flehen.", rewards = "Gürtel mit SchrumpfköpfenGürtel mit SchrumpelköpfenGürtel mit konservierten KöpfenGürtel mit winzigen KöpfenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8221] = {title = "Besonderer Fisch - Kiefers Engelfisch", objective = "*Surrr* *Klick*\n\nIch suche besondere Fische, um sie für Fischereimeister Blaukieme zu katalogisieren. Bringt mir einen Fisch der Art Kiefers Engelfisch, dann werde ich Euch diese feine Belohnung zuteilwerden lassen.\n\n*Zzzap* *Bzzzz*", description = nil, progress = "*Surrr* *Klick*\n\nIch suche besondere Fische, um sie für Fischereimeister Blaukieme zu katalogisieren. Bringt mir einen Fisch der Art Kiefers Engelfisch, dann werde ich Euch diese feine Belohnung zuteilwerden lassen.\n\n*Zzzap* *Bzzzz*", completion = "*Surrr*\n\nIdentifizierung und Katalogisierung von Kiefers Engelfisch abgeschlossen.\n\nEure Belohnung ist nun erhältlich.\n\n*PLIIING-PLIIING**Bzzzz*", rewards = "Ihr bekommt:\n\nGlücksangelhut"}
MultiLanguageQuestData['de'][8222] = {title = "Leuchtendes Skorpidblut", objective = "In all der Zeit, in der ich nun mit dem Jahrmarkt reise, habe ich viel über unsere Kunden gelernt. Eine Kostprobe meiner Weisheit gefällig? Kunden lieben alles, was leuchtet. Es ist völlig egal was! Ihr könntet ein abgebrochenes Stuhlbein nehmen und es zum Leuchten bringen und schon würde jedes Kind von egal wieweit her kommen, nur um darauf einen Blick werfen zu können!\n\nTja <Name>, ich brauche also leuchtendes Skorpidblut. Bei den Skorpiden in Silithus, in den verwüsteten Landen oder der brennenden Steppe solltet Ihr fündig werden.", description = nil, progress = "In all der Zeit, in der ich nun mit dem Jahrmarkt reise, habe ich viel über unsere Kunden gelernt. Eine Kostprobe meiner Weisheit gefällig? Kunden lieben alles, was leuchtet. Es ist völlig egal was! Ihr könntet ein abgebrochenes Stuhlbein nehmen und es zum Leuchten bringen und schon würde jedes Kind von egal wieweit her kommen, nur um darauf einen Blick werfen zu können!\n\nTja <Name>, ich brauche also leuchtendes Skorpidblut. Bei den Skorpiden in Silithus, in den verwüsteten Landen oder der brennenden Steppe solltet Ihr fündig werden.", completion = "Großartig! Habt vielen Dank! Aus dem Blut werde ich eine eine exzellente Farbe mischen und damit den billigsten Tand in pures Gold verwandeln!\n\nNehmt diese Lose, &lt;Name&gt;, danke für Eure Dienste.", rewards = "Ihr bekommt:\n\nZerfleddertes Gewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][8223] = {title = "Mehr leuchtendes Skorpidblut", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZerfleddertes Gewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][8224] = {title = "Besonderer Fisch - Dezianischer Königinnenfisch", objective = "*Surrr* *Klick*\n\nIch suche besondere Fische, um sie für Fischereimeister Blaukieme zu katalogisieren. Bringt mir einen dezianischen Königinnenfisch, dann werde ich ich Euch diese feine Belohnung zuteil werden lassen.\n\n*Zzzap* *Bzzzz*", description = nil, progress = "*Surrr* *Klick*\n\nIch suche besondere Fische, um sie für Fischereimeister Blaukieme zu katalogisieren. Bringt mir einen dezianischen Königinnenfisch, dann werde ich ich Euch diese feine Belohnung zuteil werden lassen.\n\n*Zzzap* *Bzzzz*", completion = "*Surrr*\n\nIdentifizierung und Katalogisierung des dezianischen Königinnenfisches abgeschlossen. \n\nEure Belohnung ist nun erhältlich.\n\n*PLIIING-PLIIING**Bzzzz*", rewards = "Ihr bekommt:\n\nExtremgetestete Eterniumangelschnur"}
MultiLanguageQuestData['de'][8225] = {title = "Besonderer Fisch - Braunells blaugestreifter Flitzerfisch", objective = "*Surrr* *PLIIING*\n\nIch suche besondere Fische, um sie für Fischereimeister Bluegill zu katalogisieren. Bringt mir einen von diesen Braunells blaugestreiften Flitzerfischen und ich werde Euch eine feine Belohnung zuteil werden lassen. \n\n*KLING**Bzzzz*", description = nil, progress = "*Surrr* *PLIIING*\n\nIch suche besondere Fische, um sie für Fischereimeister Bluegill zu katalogisieren. Bringt mir einen von diesen Braunells blaugestreiften Flitzerfischen und ich werde Euch eine feine Belohnung zuteil werden lassen. \n\n*KLING**Bzzzz*", completion = "*Surrr*\n\nIdentifizierung und Katalogisierung von Braunells blaugestreiften Flitzerfisch abgeschlossen. \n\nEure Belohnung ist nun erhältlich.\n\n*PLIIING-PLIIING**Bzzzz*", rewards = "Ihr bekommt:\n\nNat Pagles Extremanglerstiefel"}
MultiLanguageQuestData['de'][8227] = {title = "Nats Maßband", objective = "Bringt Nats Maßband zu Nat Pagle in den Düstermarschen zurück.", description = "Inmitten von zerbrochenen Angelruten und anderen Geräten, liegt ein zusammengerolltes, seidenes Maßband. An dem Band hängt ein Schild mit der Aufschrift:\n\n\"Nat Pagle, die Düstermarschen.\"", progress = "Hallo da, Kleiner. Zum Angeln hergekommen?", completion = "Was, Ihr habt mein Lieblingsmaßband gefunden! Ich liebe dieses Band! Ich habe einige der größten Fische, die ich jemals gefangen habe, damit gemessen...\n\nAllerdings habe ich es in Zul'Gurub verloren... Ihr wart in Zul'Gurub? Habt Ihr den sagenumwobenen Gahz'ranka gesehen?\n\nUnd... wollt Ihr ihn fangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8228] = {title = "Könnte ich einen Flugzettel für den Angelwettbewerb bekommen?", objective = "Es wird diesen Sonntag einen Angelwettbewerb in Booty Bay geben! Hier sind die Regeln für den Wettbewerb, falls Ihr daran teilnehmen möchtet!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAngelwettbewerb!"}
MultiLanguageQuestData['de'][8229] = {title = "Könnte ich einen Flugzettel für den Angelwettbewerb bekommen?", objective = "Es wird einen Angelwettbewerb in Booty Bay geben, diesen Sonntag! Hier sind die Regeln für Euch!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAngelwettbewerb!"}
MultiLanguageQuestData['de'][8231] = {title = "Wellenjagd", objective = "Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", description = "Der Wellenhauer ist ein amphibisches Wildtier, das nur hier in Azshara vorkommt. Er ist gewandt und zäh.\n\nDie robusten, reflektierenden Schuppen eines Wellenhauers spiegeln die Stärke des Jägers wider.\n\nSpürt Wellenhauer entlang der Küste Azsharas auf, jagt sie und bringt mir ihre Schuppen.", progress = "Seid Ihr erfolgreich gewesen?", completion = "Die Wellenhauer sind nicht einfach zu bezwingen, vor allem nicht in ihrer natürlichen Umgebung, dem Wasser.\n\nIhr habt bewiesen, dass Ihr bereit für die Jagd auf noch tödlichere Beute seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8232] = {title = "Der grüne Drache", objective = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", description = "Ich entsende Euch nun auf eine gefährliche Jagd. Es gilt den grünen Drachen, Morphaz, zu bezwingen und mir seinen Zahn zu bringen. Morphaz haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nWenn Ihr ihn besiegen möchtet, solltet Ihr nicht alleine gehen. Dieser Drache ist der Feind von vielen - sucht nach anderen, die ihn ebenfalls zu vernichten suchen.\n\nDer Zahn des Drachen steht für die Macht, den ein Jäger in der Gesellschaft anderer findet. Bringt ihn zu mir und Ihr werdet viel gelernt haben.", progress = "Ich sehe Weisheit in Euren Augen, <Name>. Ist Eure Jagd beendet?", completion = "Ihr habt die alten Wege erlernt, &lt;Name&gt;, dafür belohne ich Euch mit einem Geschenk, das aus meinen Zeiten als &lt;Klasse&gt; stammt.", rewards = "JagdspeerAuf Euch wartet eine dieser Belohnungen:\n\nAuge eines TeufelssauriersZahn eines Teufelssauriers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8233] = {title = "Ein simples Anliegen", objective = "Sprecht mit Lord Jorach Rabenholdt im Rabenholdtanwesen.", description = "Lord Jorach Rabenholdt hat nach Euch rufen lassen. Die Angelegenheit ist geheim und ich kann auch nicht mehr dazu sagen.\n\nDas Rabenholdtanwesen liegt im Vorgebirge des Hügellands - haltet nach einem Pfad im Gebirge nordwestlich von Burg Durnholde Ausschau.", progress = nil, completion = "Willkommen, willkommen, willkommen! Bitte, &lt;Name&gt;, setzt Euch doch und besprecht ein simples Anliegen mit mir.\n\nSeht Ihr, &lt;Name&gt;, ich habe erst kürzlich etwas verloren, was sehr kostbar für mich war. Um es direkt zu sagen, ich möchte es unter allen Umständen zurückhaben. Natürlich gibt es eine Belohnung für Euch, darum müsst Ihr Euch nicht sorgen! Oh ja, es ist etwas sehr Schönes.\n\nNun was sagt Ihr, &lt;Name&gt;... seid Ihr interessiert an einem kleinen Abenteuer?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8234] = {title = "Die versiegelte azurblaue Tasche", objective = "Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist.", description = "Eins nach dem anderen. Ich habe eine kleine blaue Tasche verloren, deren Inhalt von privater Natur ist.\n\nWie dem auch sei, versucht erst gar nicht den Dieben nachzustellen, denn sie sind bereits tot. Wir wissen jedoch, dass diese Narren die Tasche nicht öffnen konnten. Sie verkauften sie also an einen Schamanen der Holzschlundfeste in Azshara als heiliges Relikt. Raffiniert.\n\nIch möchte, dass Ihr nach Azshara reist und die Tasche von dem Schamanen durch Geschick... oder mittels Kraft wiedererlangt. Ich glaube mit ersterer Methode dürftet Ihr mehr Glück haben. Habt Ihr sie, bringt sie zu Erzmagier Xylem in Azshara.", progress = "Kenne ich Euch?", completion = "Ah, Ihr habt die Tasche von Lord Ravenholdt. Warum habt Ihr das nicht gleich gesagt, Junge?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8235] = {title = "Verschlüsselte Fragmente", objective = "Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente.", description = "Lord Rabenholdt bittet uns beide um einen Gefallen. Er wünscht die Verzauberung von dieser Tasche zu entfernen.\n\nUnglücklicherweise hat man mir meine Abhandlungen über die Bannung von Zaubern vor Kurzem entwendet, nur um von Wilden zerstört zu werden. Die Überreste sind jedoch noch immer von Wert für mich.\n\nWenn Ihr mir genug verschlüsselte Fragmente bringen könnt, kann ich die Abhandlungen wiederherstellen. Am besten tötet Ihr dafür die Wildtiere Azsharas, da diese Kreaturen die Tendenz besitzen, alles aufzusammeln, was sie so finden können.", progress = "Habt Ihr genügend Fragmente gefunden, damit ich meinen Teil des Auftrages erfüllen kann?", completion = "Ihr seht aus, als hättet Ihr sogar einige der besseren Fragmente aufgelesen. Vielleicht seid Ihr doch nicht ganz so nutzlos, wie ich zuerst dachte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8236] = {title = "Der azurblaue Schlüssel", objective = "Bringt den azurblauen Schlüssel zu Lord Jorach Rabenholdt.", description = "Es wird einige Zeit dauern, die Fragmente zu entschlüsseln und den Zauber zu bannen. Sobald ich mein Werk vollendet habe, werde ich die Tasche Lord Rabenholdt persönlich übergeben.\n\nAllerdings gibt es da noch das Problem mit dem Schlüssel, von dem gesagt wird, er befände sich im Besitz von Morphaz, einem grünen Drachen. Er haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nVersammelt Eure getreusten Freunde und begebt Euch zu seinem Hort. Lord Rabenholdt erwartet Euch mit dem Schlüssel.", progress = "Die Tasche, die Erzmagier Xylem sandte, ist bereits angekommen. Habt Ihr den Schlüssel finden können?", completion = "Der Schlüssel! Und ich dachte schon, er sei für immer verloren. Bitte nehmt ein verzaubertes Gewand aus meinem Lager - sie sind nur für Schurken von außergewöhnlichem Talent und enormer Loyalität bestimmt. Es sollte schon gezeigt werden, dass Ihr, &lt;Name&gt; niemand seid, den man unterschätzen sollte!", rewards = "NachtsaugertuchEbenholzmaskeLeisetreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8237] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][8238] = {title = "Münzen der Gurubashi, Blutfratzen und Bleichborken", objective = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", description = nil, progress = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", completion = "Ausgezeichnet - dieses Set Münzen ist eine feine Zugabe für unsere wachsende Sammlung... eine, die wir bei der Verteidigung unseres Stammes gegen die Auferstehung des Blutgottes einsetzen werden. Ihr habt Euch diese Ehrenmünze verdient, &lt;Name&gt;, genauso wie den Dank unseres Stammes!", rewards = "Ihr bekommt:\n\nEhrenmünze der Zandalari"}
MultiLanguageQuestData['de'][8239] = {title = "Münzen der Sandwüter, Schädelspalter und Blutskalpe", objective = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im Tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", description = nil, progress = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im Tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", completion = "Ausgezeichnet - dieses Set Münzen ist eine feine Zugabe für unsere wachsende Sammlung... eine, die wir bei der Verteidigung unseres Stammes gegen die Auferstehung des Blutgottes einsetzen werden. Ihr habt Euch diese Ehrenmünze verdient, &lt;Name&gt;, genauso wie den Dank unseres Stammes!", rewards = "Ihr bekommt:\n\nEhrenmünze der Zandalari"}
MultiLanguageQuestData['de'][8240] = {title = "Ein Schmuckstück für Zanza", objective = "Zerstört jedes Schmuckstück der Hakkari, das Ihr in Zul'Gurub findet, am Altar von Zanza auf der Insel Yojamba. Sprecht ganz in der Nähe mit Vinchaxa, sobald Ihr dies getan habt.", description = "Die Zerstörung der zahlreichen Schmuckstücke der Hakkari ist für uns von großer Bedeutung. Wir heißen sogar Außenseiter in unserem Stamm willkommen, um uns dabei in eigener Sache zu helfen!\n\nBringt, was auch immer für ein Schmuckstück ihr in Zul'Gurub finden solltet, zum Altar von Zanza und zerstört es. Ich werde Euch nur für dieses eine Mal eine zusätzliche Ehrenmünze unseres Stammes geben; dies liegt hoch über dem, was Ihr normalerweise erhalten würdet.\n\nWerdet selbst Zeuge des Segens von Zanza!", progress = "Habt Ihr das Schmuckstück am Altar von Zanza zerstört? Erledigt dies und Ihr werdet von Zanza zweifach gesegnet!", completion = "Ausgezeichnet... jedes Schmuckstück, das wir den Dienern des Blutgotts entreißen, bringt uns alle deren endgültiger Zerstörung einen Schritt näher. Ihr ehrt die Zandalarianer und Euch selbst mit Euren edlen Taten.\n\nVergesst nicht, &lt;Name&gt;, Ihr könnt die Schmuckstücke, die Ihr in Zul'Gurub findet, jederzeit am Altar zerstören. Ihr werdet Euch dadurch jedesmal Anerkennung und eine Ehrenmünze verdienen! Denkt einfach nur an einen freien Platz in Eurem Inventar, wenn Ihr noch keines der Stücke haben solltet.", rewards = "Ihr bekommt:\n\nEhrenmünze der Zandalari"}
MultiLanguageQuestData['de'][8241] = {title = "Nachschub an feurigem Fluxus: Eisen", objective = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Eisenbarren.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", description = nil, progress = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Eisenbarren.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", completion = "Es ist immer genug Platz für einen weiteren feurigen Fluxus, Junge. Immer her damit... bis ich Euch sage, dass es genug ist.", rewards = nil}
MultiLanguageQuestData['de'][8242] = {title = "Nachschub an feurigem Fluxus: Schweres Leder", objective = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Schweres Leder.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", description = nil, progress = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Schweres Leder.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", completion = "Es ist immer genug Platz für einen weiteren feurigen Fluxus, Junge. Immer her damit... bis ich Euch sage, dass es genug ist.", rewards = nil}
MultiLanguageQuestData['de'][8243] = {title = "Zanzas wirksame Tränke", objective = "Mit Eurem verbesserten Ruf innerhalb unseres Stammes, bekommt Ihr auch Zugang zu einigen unserer wirksamsten Tränke. Nehmt Euch in Acht... diese Gebräue sind stark im Mojo - gesegnet von Zanza und für Abenteurer jeglicher Herkunft gemacht!\n\nIch lasse Euch einen aus den drei Tränken, die ich anbiete, auswählen; im Gegenzug verlange ich eine zandalarianische Ehrenmünze. Seid Euch im Klaren, dass nur jeweils die Effekte eines Tranks zu einer beliebigen Zeit durch Euren Geist jagen können.\n\nLasst mich wissen, wenn Ihr zum Tauschhandel bereit seid!", description = nil, progress = "Mit Eurem verbesserten Ruf innerhalb unseres Stammes, bekommt Ihr auch Zugang zu einigen unserer wirksamsten Tränke. Nehmt Euch in Acht... diese Gebräue sind stark im Mojo - gesegnet von Zanza und für Abenteurer jeglicher Herkunft gemacht!\n\nIch lasse Euch einen aus den drei Tränken, die ich anbiete, auswählen; im Gegenzug verlange ich eine zandalarianische Ehrenmünze. Seid Euch im Klaren, dass nur jeweils die Effekte eines Tranks zu einer beliebigen Zeit durch Euren Geist jagen können.\n\nLasst mich wissen, wenn Ihr zum Tauschhandel bereit seid!", completion = "Ein fairer Handel, mein Freund... erfreut Euch am Segen Zanzas mit unseren besten Wünschen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZanzas GlanzZanzas GeistZanzas Schnelligkeit"}
MultiLanguageQuestData['de'][8246] = {title = "Das Siegel der Zandalari", objective = "Für jemanden, der bei den Zandalar so angesehen ist wie Ihr <Name>, habe ich etwas sehr Besonderes. Direkt aus unserer Heimat in den südlichen Meeren... die Siegel der Zandalar! Diese Siegel werden zum Aufwerten eines beliebigen Schultergegenstands, den Ihr besitzt, verwendet. Solltet Ihr nach Macht, Mojo oder Gelassenheit suchen - dann habe ich genau das, was Ihr braucht!\n\nIch gebe Euch ein Siegel Eurer Wahl im Austausch gegen fünfzehn zandalarianische Ehrenmünzen. Sobald Ihr die Münzen habt, können wir Geschäfte machen!", description = nil, progress = "Für jemanden, der bei den Zandalar so angesehen ist wie Ihr <Name>, habe ich etwas sehr Besonderes. Direkt aus unserer Heimat in den südlichen Meeren... die Siegel der Zandalar! Diese Siegel werden zum Aufwerten eines beliebigen Schultergegenstands, den Ihr besitzt, verwendet. Solltet Ihr nach Macht, Mojo oder Gelassenheit suchen - dann habe ich genau das, was Ihr braucht!\n\nIch gebe Euch ein Siegel Eurer Wahl im Austausch gegen fünfzehn zandalarianische Ehrenmünzen. Sobald Ihr die Münzen habt, können wir Geschäfte machen!", completion = "Ein fairer Handel, mein Freund... bitte nehmt unser Siegel mit dem Segen unseres Stammes!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZandalarisiegel der MachtZandalarisiegel des MojoZandalarisiegel der inneren Ruhe"}
MultiLanguageQuestData['de'][8249] = {title = "Plunderkisten benötigt", objective = "Meine Schurken müssen ihre Fertigkeiten im Schlossknacken noch verbessern und ich brauche dafür noch Schlösser mit entsprechendem Schwierigkeitsgrad - das Zeug, das Zan für uns herstellt, taugt lediglich für totale Anfänger.\n\nIch sag' Euch was, wenn Ihr mir 5 schwere Plunderkisten besorgt, dann gebe ich Euch dafür die feinsten Wurfmesser, die in Schurkenkreisen bekannt sind.\n\nIhr könnt die Kisten öffnen und durchstöbern, aber lasst wenigstens ein paar Münzen übrig... auch ein <Klasse>, der sich in Ausbildung befindet, braucht etwas Motivation.", description = nil, progress = "Meine Schurken müssen ihre Fertigkeiten im Schlossknacken noch verbessern und ich brauche dafür noch Schlösser mit entsprechendem Schwierigkeitsgrad - das Zeug, das Zan für uns herstellt, taugt lediglich für totale Anfänger.\n\nIch sag' Euch was, wenn Ihr mir 5 schwere Plunderkisten besorgt, dann gebe ich Euch dafür die feinsten Wurfmesser, die in Schurkenkreisen bekannt sind.\n\nIhr könnt die Kisten öffnen und durchstöbern, aber lasst wenigstens ein paar Münzen übrig... auch ein <Klasse>, der sich in Ausbildung befindet, braucht etwas Motivation.", completion = "Mögen diese Messer einen Platz in jemandes Herz einnehmen.\n\nIm wahrsten Sinne des Wortes.", rewards = "Ihr bekommt:\n\nDüsterstahlwurfmesser"}
MultiLanguageQuestData['de'][8250] = {title = "Geschick der Magier", objective = "Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem.", description = "Erzmagier Xylem hat seit kurzer Zeit begonnen sich umzuhören... nach jemanden mit Eurer Erfahrung.\n\nFalls Ihr ihn aufsuchen möchtet, dann könnt Ihr ihn in Azshara antreffen. Sein Turm steht hoch über den Klippen und der einzige Weg, der dort hinaufführt, ist ein Teleportationszauber, der von seinem arroganten Diener, Sanath Lim-yo, gewirkt wird.\n\nSanath kampiert unterhalb des Turms. Um ihn zu finden, müsst Ihr zu der Stelle reisen, an der sich Azsharas Hauptstraße beim Eingang zu den Ruinen von Eldarath gabelt. Geht von dort aus direkt nach Norden bis Ihr zu den Klippen kommt.", progress = nil, completion = "&lt;Sanath grinst Euch höhnisch an.&gt;\n\nErzmagier Xylem wartet auf Euer Eintreffen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Azshara-Turm teleportieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8251] = {title = "Magischer Staub", objective = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.", description = "Die Blutelfen in Azshara haben eine Methode entwickelt, um magische Gegenstände, die sie erhalten, zu Staub zu pulverisieren. Dieser glitzernde Staub, der so produziert wird, gleicht nicht jenem, der sich durch eine übliche Entzauberung herstellen lässt.\n\nIch habe bereits meinen Lehrling entsendet, um durch Handel diesen Staub zu erlangen, doch er wurde ohne Umschweife grausam ermordet. Dafür müssen sie bezahlen.\n\nDie Zeiten der Konversation sind vorbei, <Name>. Sucht nach den Blutelfen entlang der Klippen von Azshara und wendet \"überzeugendere\" Mittel an, um an den glitzernden Staub zu kommen.", progress = "Habt Ihr den Staub?", completion = "Gut gemacht, &lt;Name&gt;! Ich finde es doch immer wieder beeindruckend, wie überzeugend eine Salve arkaner Geschosse sein kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8252] = {title = "Die Koralle der Sirenen", objective = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.", description = "Seht Euch nur um. Die Ruinen und Strände sind buchstäblich von den Grollflossen überrannt worden. Unlängst haben sie sich soweit mit dem Land vertraut gemacht, dass sie die seltensten und wertvollsten Elemente entdeckt haben, die in Azshara heimisch sind.\n\nGenau genommen spreche ich von der verzauberten Koralle - sie werden aus mir unerfindlichen Gründen davon angezogen. In der Bucht gibt es nur noch sehr wenige Exemplare, die für meine Forschungen jedoch unverzichtbar sind. Ich brauche Euch, um mir verzauberte Korallen von den Sirenen der Grollflossen zu beschaffen.", progress = "Die Sirenen der Grollflossen sind überraschend starke <Klasse>. Nicht so bewandt wie Ihr, hoffe ich doch?", completion = "Das ist eine hervorragende Korallenprobe, &lt;Name&gt;. Euer Geschick ist äußert präzise und tödlich.\n\nGlaubt nur nicht, dass Eure Bemühungen unbemerkt geblieben sind. Vielleicht seid Ihr bereit, für einen wahren Test Eurer Fähigkeiten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8253] = {title = "Vernichtet Morphaz", objective = "Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", description = "Es gibt einen grünen Drachen, tief im Versunkenen Tempel von Atal'Hakkar, der sich Morphaz nennt.\n\nVor Jahren überwältigte er mich aus einem kühnen Hinterhalt heraus und verschlang meinen Lehrling mit Haut und Haaren. Der Verlust eines Lehrlings ist mir zwar nicht unbekannt, allerdings trug dieser einen arkanen Splitter von unübertroffener Größe und Qualität.\n\nBitte versammelt Eure mächtigsten Verbündeten und dringt in die Tiefen des Tempels vor. Zerstört Morphaz und entreißt ihm den arkanen Splitter aus seinem Magen.", progress = "Habt Ihr meinen alten Feind besiegt?", completion = "Unglaublich. Der Splitter ist sogar noch mächtiger geworden. Er scheint über all die Jahre die Energie des Drachen absorbiert zu haben.\n\nEs gibt nichts mehr worum ich Euch nun bitten könnte. Meine Fähigkeit das Arkane zu wirken ist mit der Rückkehr dieses Splitters komplett wiederhergestellt. Meine erste Kreation sei die Eure, &lt;Name&gt;, und Ihr müsst lediglich wählen...", rewards = "GletscherstachelAuf Euch wartet eine dieser Belohnungen:\n\nArkankristallanhängerFeuerrubin\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8254] = {title = "Cenarische Hilfe", objective = "Sucht Ogtinc in Azshara auf.", description = "Es ist der Weg des Göttlichen, mit dem denen geholfen wird, die in Not sind. Das \"wie\" ist unbedeutend -- allein das \"warum\" zählt.\n\nDer Zirkel des Cenarius ist in derartigen Nöten. Sprecht mit Ogtinc, um ihnen in ihrer Notlage auszuhelfen. Er wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath in Azshara.", progress = nil, completion = "Eure Ankunft stellt eine große Erleichterung für mich dar. Es gibt viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8255] = {title = "Renner für einen höheren Zweck", objective = "Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", description = "Die in Azshara lebenden Mooshufrenner sind prachtvolle Tiere, die ursprünglich aus dem Teufelswald stammen. Sie sind von Natur aus resistent gegen Krankheiten und Gifte und blieben so vor der Verderbnis in diesem Gebiet verschont. In ihrer ganzen Weisheit haben sie schlicht beschlossen, den Teufelswald zu verlassen.\n\nEs schmerzt mich von ganzem Herzen, dass ich Euch bitten muss, diese majestätischen Lebewesen für mich zu jagen. Sammelt vier Rennerdrüsen als erste Zutat für ein regenerierendes Mittel - ein Mittel, mit dem wir den Teufelswald heilen möchten.", progress = "Ihr seid zurück. Wart Ihr erfolgreich?", completion = "Es ist der Weg des Göttlichen, der Euch zu und geführt hat, &lt;Name&gt;. Eure Überzeugungen interferieren nicht mit den Aufgaben, die der Herstellung des Mittels dienen.\n\nSeht Ihr, der Renner ist dem Zirkel des Cenarius heilig und das Töten aus egal welchem Grund, wie wichtig er auch sein mag, schwächt dessen Geist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8256] = {title = "Sekret des Untodes", objective = "Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", description = "Für dieses regenerierende Mittel braucht Ihr ein simples Rezept: ein Teil Gift, zwei Teile Heilmittel. Ihr habt bereits einen Teil des Heilmittels beschafft, nun müsst Ihr das Gift sammeln.\n\nMächtige Untote, wie die verweilenden Hochgeborenen, welche die Ruinen von Eldarath durchstreifen, sind dermaßen vom Bösen durchdrungen, dass es sich manchmal als eine Art dickflüssige, grünliche Flüssigkeit manifestiert. Unter den Lebenden ist diese Substanz als Sekret des Untodes bekannt.\n\nDie Wirksamkeit dieses widerwärtigen Elements ist derart mächtig, dass es genügen wird, wenn Ihr mir eine einfache Dosis des Sekrets bringt.", progress = "Wir müssen das Sekret schnellstmöglich beschaffen. Habt Ihr es gefunden?", completion = "Ich nicht sagen, dass ich erfreut bin diese scheußliche Substanz zu erhalten, aber es ist wohl ein notwendigs Übel. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8257] = {title = "Morphaz' Blut", objective = "Tötet Morphaz im Versunkenen Tempel von Atal'Hakkar und bringt Greta Mooshuf im Teufelswald sein Blut. Der Eingang zum Versunkenen Tempel liegt in den Sümpfen des Elends.", description = "Jetzt zum letzten Teil, dem zweiten Heilmittel.\n\nDer grüne Drache Morphaz ist dafür bekannt, gegen alle Formen von Krankheit und Gift immun zu sein - viele Druiden erlitten den Tod, um uns diese Nachricht zu übermitteln. Es gibt keine Zweifel, dass sein Blut die für uns nötige Wirkung hat.\n\nEin Kurier des Zirkels des Cenarius wird die von Euch bereits beschafften Zutaten übernehmen, während Ihr nach der letzten sucht. Versammelt Eure Verbündeten und sucht den Unterschlupf des Drachen im Versunkenen Tempel von Atal'Hakkar auf. Bringt sein Blut anschließend zu Greta Mooshuf im Teufelswald.", progress = "Habt Ihr das Blut von Morphaz?", completion = "Ihr habt Morphaz besiegt und uns sein Blut gebracht... ich kann diese gute Nachricht kaum fassen!\n\nWir werden sofort mit der Verarbeitung der Zutaten beginnen und die Tiere und Bäume des Teufelswalds endlich heilen. Es wird sicherlich ein ganzes Leben lang dauern, das hier Geschehene rückgängig zu machen, aber dank Eurer Hilfe verfügen wir nun über die entsprechenden Mittel.", rewards = "Stab des LeidensAuf Euch wartet eine dieser Belohnungen:\n\nGesegnete GebetsperlenReif der Hoffnung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8258] = {title = "Die Bedrohung durch Schattensichel", objective = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des Großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar.", description = "Der Todesritter Schattensichel herrscht über das Große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen... Er muss gestoppt werden! Dabei kommt das Orakel der Anrufung, bei dessen Herstellung Ihr behilflich wart, zum Einsatz.\n\nSetzt das Orakel inmitten des Kellergewölbes des Großen Ossuariums ein, um Schattensichels Geistergefolge herbeizurufen. Besiegt die Geister und der Todesritter selbst wird erscheinen. <Name>, bringt mir seinen Kopf! Lediglich seine Niederlage wird den Schaden, den er der spirituellen Ebene zugefügt hat, wieder umkehren können!", progress = "Die Zeit drängt, <Name> - habt Ihr der Bedrohung durch den Todesritter Schattensichel erfolgreich Einhalt gebieten können?", completion = "Das ist ein Sieg, den es auszukosten gilt, &lt;Name&gt;! Der Untergang Schattensichels sollte den schwachen Halt, der die spirituelle Ebene zusammenhält, wieder herstellen.\n\nIhr habt die an Euch gestellten Anforderungen bei weitem übertroffen, obwohl Ihr nichts von einer Belohnung oder Entschädigung gewusst habt. Ihr seid wahrhaftig ein ehrenhafter &lt;Klasse&gt;, mein Freund.\n\nIch weiß, dass der Erhalt der spirituellen Ebene Lohn genug sein sollte, aber bitte - akzeptiert dieses bescheidene Geschenk als meinen persönlichen Dank.", rewards = "Ihr bekommt:\n\nHelm des Himmelszorns"}
MultiLanguageQuestData['de'][8259] = {title = "Eine angemessenere Belohnung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm des Himmelszorns"}
