MultiLanguageQuestData['de'][8261] = {title = "Standardüberlebenspaket von Arathor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStandardüberlebenspaket von Arathor"}
MultiLanguageQuestData['de'][8262] = {title = "Verbessertes Überlebenspaket von Arathor", objective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, <Name>. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb des Arathibecken verwendet werden können.\n\nBewährt Ihr Euch noch weiter im Arathibecken, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVerbessertes Überlebenspaket von Arathor"}
MultiLanguageQuestData['de'][8263] = {title = "Basisüberlebenspaket der Entweihten", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBasisüberlebenspaket der Entweihten"}
MultiLanguageQuestData['de'][8264] = {title = "Standardüberlebenspaket der Entweihten", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStandardüberlebenspaket der Entweihten"}
MultiLanguageQuestData['de'][8265] = {title = "Verbessertes Überlebenspaket der Entweihten", objective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, <Name>. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb des Arathibecken verwendet werden können.\n\nBewährt Ihr Euch noch weiter im Arathibecken, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn Ihr unser Wohlwollen erlangt habt, sowie Verbände, wenn Ihr Euch unseren Respekt verdient habt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVerbessertes Überlebenspaket der Entweihten"}
MultiLanguageQuestData['de'][8266] = {title = "Aufopferungsabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8268] = {title = "Aufopferungsabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8271] = {title = "Held der Sturmlanzen", objective = "Als ein Held der Stormpike, dürft Ihr Euch eines dieser erst kürzlich geplün… äh, wiederentdeckten Schätze, aussuchen.", description = nil, progress = nil, completion = nil, rewards = "EisstachelspeerBlutsucherZauberstab der beißenden KälteKaltgeschmiedeter HammerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8272] = {title = "Held der Frostwölfe", objective = "Was ist das für ein Gefühl, <Name>? Wie fühlt es sich an, die Linien des Feindes zu zerschmettern und jeglichen Widerstand auszulöschen? Es ist ein gutes Gefühl, nicht wahr?\n\nFür Eure Heldentat habt Ihr eine große Belohnung verdient.", description = nil, progress = nil, completion = nil, rewards = "EisstachelspeerBlutsucherZauberstab der beißenden KälteKaltgeschmiedeter HammerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8273] = {title = "Orans Dankbarkeit", objective = "Ach das ist ja interessant! Ihr sagt, Ihr habt diese Schrifttafel auf einer kleinen, unbewohnten Insel nahe der Aussichtsklippen im Hinterland gefunden, <Klasse>? Wirklich äußerst interessant. \n\nIch danke Euch für Eure Bemühungen in dieser Angelegenheit. Unsere dunkle Fürstin wird mit dieser Entdeckung sehr zufrieden sein. Erlaubt mir, Euch angemessen zu belohnen.", description = nil, progress = nil, completion = nil, rewards = "Antiquierte AdligentunikaReservistenkappe UnterstadtsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8274] = {title = "Test Kill Quest", objective = "Kill 5 Murlocs and come back to the test character.", description = "Könnt Ihr etwas Zeit erübrigen? Tötet ein paar Murlocs für mich, dann gebe ich Euch was Hübsches!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][8275] = {title = "Die Rückeroberung von Silithus", objective = "Sprecht mit Windruferin Prachthorn auf Burg Cenarius in Silithus.", description = "Ihr Helden der Allianz, horcht auf! Die Bedrohung durch die Silithiden blieb zu lange unbeachtet. Ohne einen wirklichen Gegner, der sie bekämpft, haben sie sich die ganze Zeit über auf eine großangelegte Invasion vorbereitet.\n\nDer Zirkel des Cenarius sammelt seine Streitkräfte in Silithus, um diesen verachtungswürdigen Kreaturen den Krieg zu erklären. Alle kampftauglichen Abenteurer werden hiermit aufgerufen, sich uns anzuschließen!\n\nWartet nicht, bis es zu spät ist! Helft uns bei der Verteidigung von Azeroth! Meldet Euch für genauere Informationen bei Windruferin Prachthorn auf Burg Cenarius.", progress = nil, completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, &lt;Klasse&gt;. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8276] = {title = "Die Rückeroberung von Silithus", objective = "Sprecht mit Windruferin Prachthorn auf Burg Cenarius in Silithus.", description = "Ihr Helden der Horde, horcht auf! Es gibt eine Bedrohung dort draußen, die wir zu lange ignoriert haben. Erderschütterungen in der Nähe von Silithidennestern, verursacht durch massive Wanderungen dieser Biester, haben unsere Aufmerksamkeit erregt. Es scheintn als bereiten sie ihre weitere Expansion vor.\n\nDer Zirkel des Cenarius sammelt seine Streitkräfte in Silithus, um diesen Silithiden den Krieg zu erklären, bevor es zu spät ist. Niemals wieder sollen diese Biester unsere Ländereien entweihen!\n\nAlle kampftauglichen Abenteurer sollten sich umgehend bei Windruferin Prachthorn auf Burg Cenarius melden. Mögen die Silithiden endgültig besiegt werden!", progress = nil, completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, &lt;Klasse&gt;. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8277] = {title = "Tödliches Wüstengift", objective = "Beetix Wankelhupf von der Burg Cenarius in Silithus möchte, dass Ihr 8 Stachel von Steinpanzerskorpiden und 8 Giftzähne von Sandhuschern für sie sammelt. Kehrt zu ihr zurück, sobald Ihr diese Aufgabe erfüllt habt.", description = "Beetix Wankelhupf ist Euch zu Diensten! Mein Cousin Noggle hat es sich zum Lebensinhalt gemacht, seltene Kräuter für die Alchemisten der Burg Cenarius zu sammeln. Oder hatte es zumindest, egal. Er kam von seinem letzten Ausflug mit einer starken Vergiftung zurück.\n\nIch habe es geschafft die Wirkung des Gifts zu verlangsamen, aber um es vollständig neutralisieren zu können, benötige ich Giftproben von was auch immer ihn gestochen haben mag.\n\nNoggle kam aus dem Norden, daher verwette ich mein letztes Hemd darauf, dass es Steinpanzerskorpide oder Sandhuscher waren. Bringt mir ein paar Stachel und Giftzähne und ich werde versuchen ein Gegengift für ihn zu erstellen.", progress = "Habt Ihr alle Proben zusammengesammelt? Wir können Noggle jede Minute verlieren!", completion = "Lasst uns die Daumen drücken! Hoffen wir, dass Noggle damit gerettet werden kann!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8278] = {title = "Noggles letzte Hoffnung", objective = "Beetix Wankelhupf von der Burg Cenarius in Silithus möchte, dass Ihr je 3 Stachel von Steinpanzerzangen und Steinpanzerschindern sowie 3 Felspirschergiftzähne für sie sammelt.", description = "Verflucht! Das Gegengift hat nicht gewirkt. Noggle muss von einer der stärkeren Kreaturen im fernen Süden gestochen worden sein.\n\nIch werde Euch brauchen, um dorthin zu gehen und mir noch mehr Proben zu besorgen, <Name>. Das Gute dabei - da ihr Gift stärker ist, werde ich nicht so viele brauchen. Der Haken ist allerdings, dass in der südlichen Gegend mehrere Arten giftiger Kreaturen herumfleuchen und Ihr daher verschiedene Proben besorgen müsst.", progress = "Das ist Eure letzte Chance, um Noggle zu retten! Beeilt Euch!", completion = "Ja! Es scheint zu wirken, Noggle kommt wieder zu sich. Wir sind Euch was schuldig!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErheblicher HeiltrankErheblicher Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8279] = {title = "Das Zwielichtlexikon", objective = "Bringt Ortell dem Einsiedler in Silithus die drei Kapitel des Zwielichtlexikons.", description = "Der Schattenhammer ist nicht gerade zimperlich mit denen, die seine Reihen verlassen wollen. Sie jagen mich bis heute, als sei ich ein wildes Tier. Unnötig zu erwähnen, dass ihre Feinde meine Freunde sind!\n\nUm diese Schrifttafel zu entschlüsseln, benötige ich das Kodebuch, welches ihre Schreiber benutzt haben, um geheime Nachrichten zu dekodieren: Das Zwielichtlexikon. Es ist dermaßen wertvoll, dass sie es in drei Kapitel aufgeteilt haben, welche an drei unterschiedlichen Orten aufbewahrt werden! Die Offiziere, denen die Teile des Lexikons anvertraut wurden, sind als Bewahrer des Schattenhammers bekannt. Sucht in den Lagern des Schattenhammers nach ihnen.", progress = "Wer ist da? Oh, Ihr seid es! Habt Ihr schon alle Kapitel des Lexikons gefunden?", completion = "Ja! Dies sind alle Teile des Buchs! Fangen wir also an, &lt;Name&gt;.\n\nErsetzt jedes dritte Wort, mit den Worten aus dem zweiten Kapitel… dann ersetzt die verbliebenen Worte, mit denen aus dem ersten Kapitel… Moment, war das nicht umgekehrt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8280] = {title = "Sicherung der Versorgungslinien", objective = "Windruferin Prachthorn auf Burg Cenarius in Silithus möchte, dass Ihr 15 Baggerschläger tötet.", description = "Burg Cenarius ist von außerordentlicher strategischer Bedeutung. Ich bin davon überzeugt, dass unser Sieg über die Silithiden feststeht, solange wir sie halten können. Natürlich unter der Bedingung, dass wir die Versorgung mit Nachschubgütern aufrechterhalten können.\n\nDie Sandwürmer in dieser Gegend stellen für unsere Nachschubkarawanen eine noch größere Gefahr dar als die Silithiden selbst. Erst heute Morgen verloren wir eine ganze Morgenkornlieferung an eine Gruppe Baggerschläger. Ich brauche Eure Hilfe, um die Bestände dieser Baggerschläger auszudünnen und um sicherzustellen, dass unsere Karawanen vor weiteren Überfällen sicher sind.", progress = nil, completion = "Ich bin Euch sehr dankbar. Eure Bemühungen, Burg Cenarius und seine Garnison zur schützen, zeugt von wahrer Tapferkeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8281] = {title = "Verstärkte Sicherheit", objective = "Windruferin Prachthorn auf Burg Cenarius in Silithus möchte, dass Ihr 20 Baggerbrecher tötet.", description = "Eure bisherigen Leistungen sind makellos, <Name>. Dennoch, sind unsere Versorgungslinien noch lange nicht sicher. In Abwesenheit der Baggerschläger, werden ihre südlichen Artgenossen nach Norden drängen, um ihren Platz einzunehmen.\n\nIhr werdet eine ganze Reihe Baggerbrecher töten müssen, um diese Biester von unseren Versorgungslinien fernzuhalten.", progress = nil, completion = "Beeindruckend! Ihr habt Euch wahrhaftig als wertvoller Verbündeter in der Kriegsvorbereitung gegen die Silithiden erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8282] = {title = "Noggles verlorener Ranzen", objective = "Spürt Noggles Ranzen im südlichen Gebirge von Silithus auf und bringt ihn zu ihm, auf Burg Cenarius, zurück.", description = "Wo bin ich? Wo is' meine Tasche? *Keuch* Ich muss sie verloren haben, als ich vor Totenstachel, dem Riesenskorpid, geflohen bin. Bei meiner überstürzten Flucht bin ich geradewegs in ein Nest von Steinpanzerschindern gerannt.\n\nIn dem Ranzen, den ich bei mir trug, befanden sich allerlei seltene Reagenzien. Beetix und ich werden ohne sie nicht die Tränke herstellen können, die von der Burg Cenarius benötigt werden. Ich bin noch zu schwach, um wieder aufzustehen, aber ich kann es für Euch lohnend machen, wenn Ihr mir meine Reagenzien zurückbringt.\n\nIch bin Totenstachel nahe dem südlichen Gebirgszug über den Weg gelaufen, hinter Bronzebarts Lager.", progress = "Habt Ihr meine Tasche noch immer nicht gefunden? Nun, ich sollte zumindest froh sein, dass das Gift zu wirken aufgehört hat.", completion = "Ja! Ihr habt meinen Ranzen zurückgebracht. Sogar all meine seltenen Reagenzien sind noch da! Ich werde für lange Zeit in Eurer Schuld stehen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElixier des MungosElixier der Weisen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8283] = {title = "GESUCHT: Totenstachel, Terror der Wüste", objective = "Bringt Totenstachels Zange zu Vish Kozus, Hauptmann der Wache.", description = "Man sagt, dass sich der grausame Skorpid Totenstachel nahe des südlichen Gebirgszuges wegen erhöhter Silithidenaktivität zurückgezogen hat. Dies stellt eine große Bedrohung für Patrouillen und Expeditionen in der südlichen Gegend dar. Wer sich an dessen Vernichtung beteiligt, soll reichlich belohnt werden. Fragt bei Hauptmann Vish Kozus, ganz oben auf dem Wachturm der Burg Cenarius, wegen der Belohnung nach.", progress = "Ich brauche die Zange der Kreatur als Beweis für Eure Heldentat. Keine Zange, keine Belohnung.", completion = "Ausgezeichnet! Mit dem Tod Totenstachels steht uns der südliche Gebirgszug als strategischer Pfad zum Umgehen der Silithidschwärme wieder offen. Man schätzt Eure Leistung hier sehr.", rewards = "SandschreitermalSchwarzer KristalldolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8284] = {title = "Das Geheimnis des Zwielichts", objective = "Geologin Lerchenbann auf Burg Cenarius in Silithus möchte, dass Ihr ihr 8 Schrifttafelfragmente des Schattenhammerklans bringt.", description = "Einst existierte nordwestlich von hier ein florierender Außenposten des Schattenhammers. Wenn Ihr heutzutage in diese Gegend reist, werdet Ihr dort nur Schwärme von Elementaren antreffen. Verrottete Holzpfosten und alte Zelttuchfetzen sind das Einzige, was noch auf den Standort des Lagers hinweist.\n\nVor einiger Zeit fand ich dort die Fragmente einer Tontafel, allerdings nicht genug Teile, um sie zu irgendetwas Brauchbarem zusammenzusetzen. Bringt mir die fehlenden Fragmente der Schrifttafel. Vielleicht können wir so etwas Licht in die Sache bringen und herausfinden, was die Anhänger des Schattenhammers in Silithus gesucht haben.", progress = "Das verwüstete Lager werdet Ihr nordwestlich von hier finden. Kommt zu mir zurück, wenn Ihr alle Fragmente gefunden habt.", completion = "Wie ich es mir gedacht habe. Ich kann zwar einige der Worte auf den Schrifttafeln entziffern, jedoch scheinen sie keiner Logik zu folgen oder irgendeine Bedeutung zu haben. Das ist nicht unbedingt ungewöhnlich, da viele Sekten der Twilight-Hammer dafür bekannt sind, ihre Texte zu verschlüsseln. Wir müssen jemanden finden, der sich besser mit solchen Sachen auskennt als wir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8285] = {title = "Der Deserteur", objective = "Bringt die wiederhergestellte Schrifttafel zu Ortell dem Einsiedler in Silithus.", description = "Es gibt Gerüchte über ein Mitglied des Schattenhammers, das aus seiner Sekte desertiert ist und nun als Einsiedler in den Bergen südöstlich vom Südwindposten lebt. Sein Name ist Ortell. Vielleicht könnt Ihr ihn davon überzeugen, Euch bei der Entschlüsselung der Schrifttafel behilflich zu sein.\n\nNehmt die wiederhergestellte Schrifttafel mit Euch und sucht Ortell auf.", progress = "Ihr! Wer seid Ihr? Wie habt Ihr mich gefunden? Man hat Euch doch nicht verfolgt, oder? Sprecht!", completion = "Ah, wie ich sehe, wisst Ihr einiges über meine alte Sekte. Ihr seid ein Verbündeter des Zirkels des Cenarius, richtig?\n\nIch wette, Ihr sucht nach Informationen, die Ihr gegen die Twilight-Hammer einsetzen könnt. Kommt näher, vielleicht können wir uns gegenseitig behilflich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8286] = {title = "Was uns morgen erwartet", objective = "Reist zu den Höhlen der Zeit in Tanaris und findet Anachronos, Nachkomme Nozdormus.", description = "Der Tod umarmte mich bereits als er erschien und seine Macht auf mich anwandte. Er ließ seinen Atem nur einmal über meinen versehrten Körper streichen und wartete daraufhin geduldig bis die Zeit meine Wunden geheilt hatte.\n\n\"Wenn es sein muss, wirst du für immer existieren\", sagte er, und mit diesen Worten sollte ich auf ewige Zeiten als Wächter gebunden sein.\n\nWerft jetzt einen Blick auf die Wüste. Der zweite Krieg steht uns bevor. Ihr müsst nach der Ruhestätte des Bronzeschwarms suchen. Reist zu den Höhlen der Zeit und seht nach, ob der Meister zurückgekehrt ist. Ich muss mir dessen sicher sein, bevor ich weiter vorgehe.", progress = "Ist Anachronos zurückgekehrt?", completion = "Es ist, wie es sein sollte! Der Eine hat sich erhoben und meine Wache neigt sich dem Ende zu…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8287] = {title = "Ein teuflischer Plan", objective = "Bringt Kommandant Mar'alith die entschlüsselte Abschrift der Schrifttafel.", description = "So, das sollte es gewesen sein... ziemlich wertvolle Informationen, muss ich sagen! Ich habe beobachtet, wie die Truppen des Zirkels des Cenarius in Silithus eingetroffen sind. Ich nehme an, sie planen den Schattenhammerklan aus Silithus zu vertreiben, nicht wahr? Diese Informationen sollten dabei hilfreich sein.\n\nBringt die Entschlüsselte Abschrift der Schrifttafel zu ihrem Anführer, Kommandant Mar'alith. Schon bald wird der Klan des Schattenhammers vernichtet sein und ich bin endgültig vor ihrem Zugriff sicher.", progress = "Was habt Ihr mir mitgebracht, <Name>?", completion = "Das sind in der Tat sehr interessante Informationen, die Ihr mir da gebracht habt, &lt;Name&gt;. Dies bringt etwas Licht in die Präsenz der Twilight-Hammer in Silithus und wird uns mit Sicherheit den Kampf gegen sie erleichtern. Eure Bemühungen sollen nicht unbelohnt bleiben, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8288] = {title = "Nur einer kann sich erheben", objective = "Bringt Brutwächter Dreschbringers Kopf zu Baristolth der Sandstürme in die Burg Cenarius in Silithus.", description = "Wir dürfen keine Zeit mehr verschwenden! Es gilt einen Helden zu finden! Die Aufgabe, die ich Euch stellen werde, würde normalerweise eine Armee erfordern, aber nur einer aus diesem Haufen von Möchtegernhelden wird sich erheben und die Bürde und Verantwortung eines Verbündeten der Brut tragen.\n\nIm Hort des Herrschers des Schwarzfels befindet sich eine äußerst grausame Bestie. Der Brutwächter Dreschbringer bewacht die Hallen des Zwists und blockiert den Weg, der in Nefarians inneres Sanktum führt. Schlachtet dieses abartige Unwesen nieder und bringt mir seinen Kopf. Seid Ihr erfolgreich, erwartet Euch die nächste Aufgabe.", progress = "Ihr müsst Euch das Wohlwollen von Nozdormus Brut verdienen.", completion = "Habt Ihr Euch als Erster in tausend Jahren das Wohlwollen des Bronzeschwarms verdient?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8290] = {title = "Besiegt die Eindringlinge!", objective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> <Klasse>. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, <Name> und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8291] = {title = "Besiegt die Eindringlinge!", objective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> <Klasse>. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, <Name> und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8294] = {title = "Bezwingt die Eindringlinge der Silberschwingen", objective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, <Volk>. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück <Name>, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8295] = {title = "Bezwingt die Eindringlinge der Silberschwingen", objective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, <Volk>. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück <Name>, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8297] = {title = "Die Ressourcen des Arathibeckens", objective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, <Name>. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8299] = {title = "Zerschlagt die Versorgungslinien Arathors", objective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, <Name>. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8301] = {title = "Der Pfad des Gerechten", objective = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.", description = "Die Brut Nozdormus misstraut den niederen Völkern für gewöhnlich. Ihr habt mir zwar bewiesen, dass Ihr das Zeug zu einem Helden habt, es ist jedoch an der Zeit, dies auch meinem Meister zu zeigen.\n\nDer Ashischwarm, Zoraschwarm, Regalschwarm: Sie alle schwärmen rege aus und sind eine Bedrohung für unsere Existenz. Vernichtet Silithiden dieser Schwärme und nehmt Euch Fragmente ihrer Knochenpanzer. Kommt zu mir zurück, wenn Ihr vom Tragen erschöpft sein solltet, auf dass ich Euch in Eurer Entschlossenheit stärke.", progress = "In ihrem Misstrauen gegenüber den sterblichen Völkern ist viel Geschichte verwurzelt; dies ist jedoch eine Geschichte, dessen Verkünden man besser der Brut überlässt, wenn es an der Zeit dafür ist.", completion = "Ihr seid nicht allein, Held. Ich werde Euch nun dazu befähigen, andere zu ernennen, die Euch bei Eurer Aufgabe behilflich sein können. Wenn Ihr der Held Eures Volkes sein sollt, dann braucht Ihr bei Euren Aufgaben und Pflichten Unterstützung.", rewards = "Ihr bekommt:\n\nVertreter Nozdormus"}
MultiLanguageQuestData['de'][8302] = {title = "Die Hand der Gerechtigkeit", objective = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.", description = "Wählt Eure Abgesandten weise aus, Sterblicher. Jedes Mal, wenn Ihr nach Erfüllung Eurer Aufgabe zurückkehrt, dürft Ihr einen neuen Abgesandten auswählen.\n\nDas soll heißen, dass ich noch mehr der Knochenpanzerfragmente benötige. Verschwendet keine Zeit!", progress = "Eines Tages wird vielleicht die gesamte Burg Cenarius unter Eurer Führung stehen.", completion = "Gut gemacht, Held. Ich werde Euch nun dazu befähigen einen weiteren Agenten Nozdormus zu ernennen.", rewards = "Ihr bekommt:\n\nVertreter Nozdormus"}
MultiLanguageQuestData['de'][8303] = {title = "Anachronos", objective = "Sucht nach Anachronos bei den Höhlen der Zeit in Tanaris.\n\nBereitgestellter Gegenstand: \n", description = "Es ist an der Zeit, <Name>.\n\nIch muss mich dafür entschuldigen, so viel vor Euch geheim zu halten. Die Feinde sind überall, selbst unter uns. Bitte, lest aus diesem Folianten und lernt. Nutzt das Wissen, das ich Euch preisgebe, und sucht nach unserem Meister.", progress = nil, completion = "Ihr seid die Hoffnung Kalimdors, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][8304] = {title = "Liebste Natalia", objective = "Befragt Frankal und Rutgar in Bronzebarts Lager über den Aufenthaltsort von Natalia Mar'alith.", description = "Meine geliebte Natalia ist verschwunden.\n\nUm die Wahrheit zu sagen, sie hat sich schon Wochen vor ihrem Verschwinden äußerst seltsam benommen. Ich habe sie mehr als einmal dabei erwischt, wie sie zu sich selber sprach, obwohl niemand in der Nähe war. Doch sie behauptete felsenfest, dass mit ihr alles in Ordnung sei und sie ihre Forschungen unbedingt fortsetzen müsste.\n\nDas letzte Mal hatte man sie gesehen, wie sie nach Süden, in Richtung Bronzebarts Lager verschwand.\n\nLeider stehen mir zu wenige Soldaten für weitere Nachforschungen zur Verfügung, <Name>. Ich brauche Eure Hilfe, um die Zwerge in Bronzebarts Lager nach ihrem Verbleib zu befragen.", progress = nil, completion = "&lt;Kommandant Mar'alith senkt nachdenklich den Kopf&gt;\n\nOb sie noch am Leben ist oder nicht, ich muss tun, was getan werden muss. Wir müssen sie finden. Leider binden mich meine Pflichten an diesen Außenposten. Kann ich ein weiteres Mal mit Eurer Hilfe rechen, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8305] = {title = "Lang Vergessenes", objective = "Sucht die Kristallträne in Silithus und blickt in ihr Innerstes.", description = "In der südlichen Wüste von Silithus, nahe der heiligen Barriere, findet Ihr eine einzelne Kristallträne. Sie ist ein Mahnmal für all die Verluste, die wir während des Krieges der Sandstürme erlitten haben. Sucht die Träne auf und blickt in ihr Innerstes, um Erleuchtung zu erfahren.", progress = nil, completion = "In der Nähe des Kristalls empfindet Ihr große Trauer. Dieses Gefühl ist so stark, dass Ihr glaubt, jeden Moment das Bewusstsein zu verlieren und an den Folgen der Trauer zu sterben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8306] = {title = "Der Schlund des Wahnsinns", objective = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet.\n\nSprecht noch einmal mit den Zwergen in Bronzebarts Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch.\n\nUnd <Name>, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\"", description = "Ihr müsst für mich in den Bau des Regalschwarms eindringen und herausfinden, was aus meiner liebsten Natalia geworden ist, <Name>. Es ist dort sehr gefährlich. Sprecht noch einmal mit den Zwergen, bevor Ihr Euch in den Schlund des Wahnsinns stürzt. Sie sollten Euch einige Tipps geben können, wie Ihr mit den Silithiden fertigwerdet, die den Schwarmbau bewohnen.\n\nUnd <Name>, sollten die Gerüchte stimmen und sie dem Wahnsinn anheim gefallen sein... dann tut, was Ihr tun müsst.", progress = "Natalia?", completion = "&lt;Kommandant Mar'alith umklammert voller Zorn seine Waffe.&gt;\n\nC'Thun? WAS hat das alles zu bedeuten? Wer ist C'Thun? Wie kann dieser Teufel meine geliebte Natalia in dieses Monster verwandeln, von dem Ihr mir berichtet habt?", rewards = "Ihr bekommt:\n\nVerderbter Schwarzholzstab"}
MultiLanguageQuestData['de'][8307] = {title = "Wüstenrezept", objective = "Haltet beim Lager des Schattenhammers westlich von Burg Cenarius nach Informationen zum Zubereiten von Sandwurmfleisch Ausschau.", description = "Sich an das Leben in der Wüste anzupassen ist alles andere als leicht. Ich vermisse nicht nur die Vögel und Bäume Auberdines, nein, diese ausgedörrte Gegend schränkt uns auch sehr in der Wahl unserer Nahrung ein. Ich versuche mehr über die Kräuter der Wüste zu lernen, aber es gibt nicht so viele.\n\nIch habe gesehen, dass Gruppen aus dem Lager des Schattenhammers westlich von hier Sandwürmer jagten. Sandwurmfleisch ist aber so bitter, ich kann mir einfach nicht vorstellen, wie sie es schmackhaft machen. Haltet Eure Augen offen, wenn Ihr zu ihrem Lager geht und lasst mich wissen, falls Ihr etwas von ihnen erfahrt.", progress = nil, completion = "Dieses Buch enthält einige der gängigen und sogar ein paar ungewöhnliche Rezepte. Nach kurzem Durchblättern des Buches entdeckt Ihr ein Rezept, das Sandwurmfleisch enthält.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8308] = {title = "Der verlorene Brief von Brann Bronzebart", objective = "Liefert Brann Bronzebarts verlorenen Brief in Bronzebarts Lager im südlichen Silithus ab.", description = "An den Finder dieses Briefs,\n\nwenn Ihr dies lest, bin ich wahrscheinlich bereits tot oder werde es in Kürze sein. Die meisten meiner Männer sind schon tot.\n\nIch habe Informationen über einen Titanen entdeckt, über eine große Schlacht zwischen ihm und einem Alten Gott. Ja, ein verdammter Alter Gott. Wir haben einen uralten Tunnel nach Ahn'Qiraj entdeckt, dem ich jetzt folge.\n\nBringt diesen Brief in mein altes Lager. Kümmert Euch bitte um meinen Affen und gebt ihm ausreichend Wasser, Nahrung und die eine oder andere Umarmung.\n\n- Brann Bronzebart, Extremforscher\n\nP.S. Achtet auf die verrückten nachtelfischen Anbeter des alten Gottes.", progress = "Bei den Göttern.", completion = "Nun, jetzt wird mir einiges klar. Solltet Ihr jemals einen Weg nach Ahn'Qiraj finden, haltet Ausschau nach dem guten Brann. Ich befürchte, ohne seinen Affen ist er hilflos.", rewards = "Ihr bekommt:\n\nBranns zuverlässige Hacke"}
MultiLanguageQuestData['de'][8309] = {title = "Glyphenjagd", objective = "Benutzt das Abschriftenset für Geologen, um ein Abpausbild des glyphenverzierten Kristalls des Regalschwarms anzufertigen.", description = "Nach unseren ersten Streifzügen in die Schwarmbauten und dem darauf folgenden Wahnsinn der Herrin Mar'alith, haben die drei Schwarmbauten damit begonnen hunderte von Insektenkriegern auszuspucken. Die erhöhte Aktivität könnte mit den Glyphen in Zusammenhang stehen, die diese merkwürdigen Kristalle in den drei Bauten der Schwärme bedecken.\n\nWir müssen unbedingt Abpausbilder von diesen Glyphen anfertigen. Mithilfe der Abpausbilder gelingt es uns vielleicht, hinter das Geheimnis dieses Wahnsinns zu kommen.\n\nHier <Name>, nehmt dieses Abschriftenset und begebt Euch in den Bau des Regalschwarms im Osten. Das ist das letzte Abpausbild, das ich brauche.", progress = "Wenn ihr ein durchgeknalltes Nachtelfenmädel in einem der Schwarmbauten antrefft, tut uns einen Gefallen und verpasst ihr nen' Tritt in den Hintern!", completion = "Ich werde nicht schlau aus diesen Glyphen. So etwas habe ich in meinem ganzen Leben noch nicht gesehen! Ich hoffe Frankals Forschungen können etwas Licht in das Dunkle dieser Misere bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8310] = {title = "Knackt den Kode", objective = "Erhaltet ein intaktes Silithidengehirn des Regalschwarms von einem beliebigen Silithiden im Bau des Regalschwarms.", description = "Ich denke, ich kann ein Elixier entwickeln, welches uns die Entschlüsselung der Glyphen und der Sprachen der Silithiden und Qiraji sehr erleichtern wird.\n\nWas ich dafür brauche? Gut, dass Ihr fragt! Ich benötige Gehirne!\n\nNormalerweise bräuchte ich Gehirne von jeder Silithidenart, die die Baue bewohnen. Ein mutiger Abenteurer hat mir bereits zwei Proben gebracht... Er ist aber nie aus dem Bau des Regalschwarms zurückgekehrt.\n\nBringt mir ein Silithidengehirn aus dem Bau des Regalschwarms... und passt auf, dass Ihr nicht so endet wie er!", progress = "Geht und spielt mit dem Affen, Junge! Ich habe keine Zeit für Belanglosigkeiten.", completion = "Fantastisch! Geht nicht zu weit weg, Junge. Vielleicht haben wir noch die eine oder andere Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8311] = {title = "Schlotternachtssüßigkeiten für Jesper!", objective = "Sprecht mit den Gastwirten in Sturmwind, Eisenschmiede und Darnassus sowie mit Talvash del Kissel in Eisenschmiede. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.\n\nKehrt zu Jesper außerhalb von Sturmwind mit einem Marzipan aus Darnassus, einer Kaugummikugel aus Gnomeregan, Nugat aus Sturmwind und einem Pfefferminzbonbon aus Eisenschmiede zurück.", description = "Ich darf nicht zum Süßigkeitensammeln gehen. Nach Todesschwinges Angriff habe ich schon Glück, dass die Waisenmatrone Nachtigall mich so weit hinaus lässt.\n\nWenn Ihr für mich loszieht, dann werde ich Euch Eure gesammelten Süßigkeiten gegen welche eintauschen, die ich bereits hier habe!\n\nAlle Gastwirte in den größeren Städten verteilen während der Schlotternächte Süßigkeiten - sprecht mit ihnen und führt ihnen vor, nach was sie Euch fragen! In Eisenschmiede verteilt auch ein kleiner Gnom namens Talvash Süßes. Sobald Ihr die Süßigkeiten habt, kommt hierher zu mir zurück!", progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][8312] = {title = "Schlotternachtssüßigkeiten für Spuks!", objective = "Sprecht mit den Gastwirten in Orgrimmar, Unterstadt und Donnerfels sowie mit Kali Remik im Tal der Geister in Orgrimmar. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.\n\nKehrt zu Spuks in den Ruinen von Lordaeron mit einem Marzipan aus Donnerfels, einer Kaugummikugel der Dunkelspeere, Nugat aus Orgrimmar und einem Pfefferminzbonbon aus Unterstadt zurück.", description = "Ich würde gerne während der Schlotternächte zum Süßigkeitensammeln gehen, aber ich kann nicht, weil die Matrone mich nicht lässt. Wenn Ihr für mich loszieht, dann werde ich Euch Eure gesammelten Süßigkeiten gegen welche eintauschen, die ich bereits hier habe! Ich glaube Ihr werdet sie mögen - sie verwandeln Euch entweder in etwas Lustiges oder Gruseliges!\n\nAlle Gastwirte in den größeren Städten verteilen während der Schlotternächte Süßigkeiten - sprecht mit ihnen und führt ihnen vor, nach was sie Euch fragen! In Orgrimmar verteilt auch ein Troll namens Kali Remik Süßes. Sobald Ihr die Süßigkeiten habt, kommt hierher zu mir zurück!", progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][8313] = {title = "Geteiltes Wissen", objective = "Bringt die ausgerissene Rezeptseite zu Calandrath ins Gasthaus der Burg Cenarius.", description = "Das Rezept für die Zubereitung von Sandwürmern ist zwar lesbar, enthält aber Hinweise auf Kräuter und Gewürze, von denen Ihr noch nie gehört habt. Calandrath weiß vielleicht mehr über die Pflanzen, die in der Wüste wachsen, damit das Rezept einen Sinn ergibt.", progress = "Habt Ihr etwas über das Rezept erfahren können? Ich hoffe, Ihr behaltet dieses Wissen nicht für Euch selbst!", completion = "Na dann sehen wir mal...\n\nDas sieht recht verständlich aus. Sie haben ihre eigenen Bezeichnungen für einige der Kräuter, aber das dürfte nicht weiter schwer zu entschlüsseln sein. Schaut, ich zeige es Euch!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeräucherte Wüstenknödel\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8314] = {title = "Des Rätsels Lösung", objective = "Bringt das glyphenverzierte Kristallprisma zu Geologin Lerchenbann auf Burg Cenarius in Silithus.", description = "Wir stehen kurz vor einem Durchbruch, <Name>. Dank der von Euch beschafften Abpausbilder ist es mir gelungen, die Glyphen auf diesem Kristallprisma nachzubilden. Es sieht so aus, als würden sie den Qiraji und anderen unbekannten Wesen dazu dienen, mit den Silithiden zu kommunizieren.\n\nLeider ist das alles, was ich aus diesen Glyphen herauskriegen konnte. Wir müssen eine Möglichkeit finden, wie wir die in den Kristallen versteckten Botschaften freilegen können.\n\nNehmt dieses glyphenverzierte Kristallprisma und bringt es Geologin Lerchenbann auf Burg Cenarius. Sie müsste uns weiterhelfen können.", progress = "Das kann doch nicht... was habt Ihr da, <Name>?", completion = "Der Grund, warum die Zwerge die Glyphen nicht entschlüsseln konnten ist ganz einfach, es gibt nichts zum Entschlüsseln! Die äußere Schicht des Prismas muss exakt nach den Markierungen innerhalb des Kristalls ausgerichtet werden, damit eine Nachricht übertragen werden kann. Clever...\n\nDiese Daten zu übersetzen dürfte nicht schwer sein, doch zuerst müssen wir den Kode entschlüsseln. Was das betrifft, habe ich nur einen einzigen Anhaltspunkt auf der Oberfläche des Prismas gefunden. Vorausgesetzt, dass das Abpausbild vollständig ist, gibt es nur eine Möglichkeit... und die ist beinahe aussichtslos.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8315] = {title = "Die Anrufung", objective = "Geologin Lerchenbann auf Burg Cenarius in Silithus möchte, dass Ihr ihr den Kristallentriegelungsmechanismus vom Abgesandten der Qiraji beschafft.\n\nNehmt die Glyphen der Anrufung, begebt Euch zu den Knochen von Grakkarond südlich von Burg Cenarius und zeichnet sie dort in den Sand. Sollte der Abgesandte der Qiraji erscheinen, tötet ihn und nehmt den Kristallentriegelungsmechanismus an Euch. Kehrt anschließend zu Geologin Lerchenbann zurück.\n\nFür diese Aufgabe werdet Ihr eine kleine Armee benötigen, <Name>!", description = "Die Glyphen zeigen einen Abgesandten der Qiraji, wie er sich mit drei Silithiden vor den Knochen eines großen Drachen trifft. Über den Glyphen steht, soweit ich dass beurteilen kann, eine Art Kode. Es könnte gut sein, dass dieser Kode der Schlüssel zur Beschwörung des Abgesandten ist.\n\nIch werde eine Kopie des Glyphenkodes anfertigen, den Ihr vor den Knochen von Grakkarond in den Sand schreiben müsst. Wenn ich Recht habe, werden die Oberanführer in dem Glauben dort auftauchen, dass neue Informationen zur Übertragung bereit stehen. Streckt sie nieder und konfrontiert den Abgesandten. Er besitzt den Schlüssel für die Kristalle...", progress = "Nutz die Gunst der Stunde und schlagt zu!", completion = "&lt;Name&gt;, ich halte 20.000 Jahre alte Geschichte in meinen Händen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8316] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenbeinplattenKristallverkrustete Schienbeinschützer"}
MultiLanguageQuestData['de'][8317] = {title = "Küchengehilfe", objective = "Calandrath von der Burg Cenarius braucht 10 geräucherte Wüstenknödel.", description = "Das Rezept kommt gelegen. Ich mache mich besser an die Arbeit, damit ich ein paar geräucherte Wüstenknödel für heute bereit habe. Ich könnte dabei etwas Hilfe gebrauchen, Ihr werdet dafür auch belohnt werden.", progress = "Wie steht's mit den Knödeln?", completion = "Ausgezeichnet! Ihr seid meine Rettung! Diese Knödel sind sogar richtig gut. Ich hätte von den Twilight-Hammer eigentlich nicht so etwas Schmackhaftes erwartet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8318] = {title = "Geheime Nachrichten", objective = "Bringt Bor Wildmähne auf Burg Cenarius 10 verschlüsselte Schattenhammertexte.", description = "Einige Schattenhammerkultisten tragen mit Kauderwelsch beschriftete Papiere bei sich. Ich möchte, dass Ihr mir ein paar dieser Texte bringt, <Klasse>.\n\nIch habe zwar keine Möglichkeit, dieses Geschreibsel zu verstehen, doch das ist nicht der springende Punkt! Mithilfe dieser Papiere tauschen die verschiedenen Gruppierungen des Kults untereinander geheime Nachrichten aus. Mit jeder Nachricht, die wir aus dem Verkehr ziehen, stören wir ihre Kommunikation untereinander!", progress = "Habt Ihr die Texte?", completion = "Exzellent! Ich werde diese Texte gut verstauen, vielleicht erweisen sie sich später noch als nützlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8319] = {title = "Verschlüsselte Schattenhammertexte", objective = "Bringt mir weitere Texte. Es dauert nicht mehr lange, und wir haben die Twilight-Hammer aus Silithus vertrieben.", description = nil, progress = "Bringt mir weitere Texte. Es dauert nicht mehr lange, und wir haben die Twilight-Hammer aus Silithus vertrieben.", completion = "Hervorragende Arbeit! Ich werde ein gutes Wort für Euch einlegen.", rewards = nil}
MultiLanguageQuestData['de'][8320] = {title = "Geolords des Schattenhammers", objective = "Tötet 10 Zwielichtgeolords und kehrt anschließend zu Huum Wildmähne auf Burg Cenarius zurück.", description = "Der Schattenhammer, ein dämonischer Kult, der sich den Kräften der Zerstörung verschrieben hat, errichtet seit längerem Lager in Silithus und hält dort Tag und Nacht bizarre Rituale ab. Bisher wissen wir noch nichts über ihre Pläne, allerdings vermuten wir, dass sie in irgendeiner Verbindung zu den pulsierenden roten Kristallen stehen, die man überall in der Wüste findet.\n\nAuch wenn wir ihrem Geheimnis früher oder später auf die Spur kommen werden, so müssen wir uns zunächst auf die unmittelbare Bedrohung konzentrieren. Sucht ihre Lager im Westen auf und haltet nach Zwielichtgeolords Ausschau. Sie sind die Köpfe dieser Schlangen; genau dort müssen wir zuschlagen!", progress = nil, completion = "Ihr habt Eure Aufgabe mit Bravour erledigt, &lt;Name&gt;! Der Verlust ihrer Geolords wird dem Kult der Twilight einen schweren Schlag versetzen. Ich hoffe nur, dass wir dadurch die Durchführung ihrer Pläne etwas verzögert haben…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8321] = {title = "Vyral der Üble", objective = "Tötet Vyral den Üblen und erhaltet Vyrals Siegelring.", description = "Wir konnten eine weitere Operationsbasis des Schattenhammers ausfindig machen. Es ist eine gut versteckte Höhle in der nordöstlichen Ecke von Silithus, bekannt als die Kavernen des Schattenhammers. Der örtliche Anführer des Kultes, Vyral der Üble, residiert dort. Er ist Euer nächstes Ziel. Besiegt ihn und bringt mir seinen Siegelring.\n\nDie Kavernen des Schattenhammers beherbergen furchterregende Schrecken, also passt auf Euch auf! Ich wünsche Euch alles gute, <Name>.", progress = "<Name>, konntet Ihr Vyral den Üblen besiegen? Habt Ihr seinen Siegelring?", completion = "Ihr habt es getan! Vyral ist tot! Das kann für die Vorhaben der Twilight-Hammer in Silithus nur den Untergang bedeuten. Sicher treiben sich noch mehr von ihnen herum, doch von dem heutigen Rückschlag, den Ihr dem Kult erteilt habt, werden sie sich nicht wieder so schnell erholen können.", rewards = "WüstenwindstulpenAuf Euch wartet eine dieser Belohnungen:\n\nSonnenprismaanhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8322] = {title = "Faule Eier", objective = "Werft die faulen Eier in die großen Braufässchen im Gasthaus von Süderstade.", description = "Die Menschen von Süderstade lieben ihr Bier und deshalb schätzen sie das Bier, das im Gasthaus von Süderstade serviert wird, auch besonders. Wir können von dem Chaos während der Schlotternächte profitieren und ihre letzte Ladung Bier für Wochen - wenn nicht sogar Monate, verderben!\n\nNehmt diese faulen Eier und werft sie in die großen Braufässchen im Gasthaus von Süderstade. Allein Eure Anwesenheit wird für Unruhe sorgen, Ihr solltet Euch also zu verteidigen wissen!\n\nWenn Ihr Süderstade dieses unvergessliche Geschmackserlebnis überbracht habt, kommt hierher zu mir aufs Fest zurück!", progress = "Der Kessel ist voller Bier.", completion = "Nachdem Ihr Euch erfolgreich bis ins Gasthaus durchgeschlagen habt, werft Ihr jetzt die Eier in den großen Kessel. Ihr riecht bereits, wie der faulige Gestank die Luft verpestet...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8323] = {title = "Wahrer Glauben", objective = "Ortell der Einsiedler möchte, dass Ihr ihm 10 verschlüsselte Schattenhammertexte beschafft.", description = "Jetzt, da sich das Zwielichtlexikon in meinem Besitz befindet, möchte ich Euch um einen kleinen Gefallen bitten.\n\nMeine ehemalige Organisation verschickt in regelmäßigen Abständen eine verschlüsselte Postille.\n\nSollten sie bei ihrer Suche nach mir irgendwelche Fortschritte machen, wird dies mit Sicherheit im 'Wahren Glauben' bekannt gegeben werden.\n\nAbgesehen davon, dass diese Information von großer Bedeutung für mich ist, dürfte die Postille noch weitere, für Euch interessante Informationen enthalten, die ich mit Freuden teilen werde. Bringt mir einfach alle verschlüsselten Texte, die Ihr bei den Mitgliedern des Schattenhammers findet.", progress = "Konntet Ihr schon einige verschlüsselte Teste ergattern? Ich kann es kaum erwarten, die aktuelle Ausgabe des 'Wahren Glaubens' zu lesen.", completion = "Hervorragend! Ich werde die Texte schnellstmöglich entschlüsseln. Sollte ich irgendetwas, dass für Euch von Interesse sein könnte finden, werde ich Euch irgendwie eine Nachricht zukommen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8324] = {title = "Fester Glauben", objective = "Konntet Ihr noch mehr verschlüsselte Texte finden? Die Entschlüsselung wird noch eininge Zeit brauchen, also bringt mir ruhig einen großen Stapel Texte.", description = nil, progress = "Konntet Ihr noch mehr verschlüsselte Texte finden? Die Entschlüsselung wird noch eininge Zeit brauchen, also bringt mir ruhig einen großen Stapel Texte.", completion = "Hervorragend! Ich kann es kaum erwarten, sie zu lesen. Hört nicht auf und bringt mir auch weiterhin alle verschlüsselten Texte, die Ihr findet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8325] = {title = "Rückeroberung der Insel der Sonnenwanderer", objective = "Tötet 6 Manawyrms; sie halten sich rund um die brennenden Kristalle auf, die man nahe des Turms und des Vorbaus findet.", description = "Je früher Ihr mit Eurer Ausbildung anfangt, <Name>, umso besser für uns alle. Wir können uns keine Fehler erlauben, also hört gut zu.\n\nDie brennenden Kristalle - die grünen, schwebenden Objekte westlich des Sonnenturms hier - wurden lange Zeit als Energiequelle für die Experimente der Insel verwendet. Die Manawyrms waren ihre Wächter, aber der Einmarsch der Geißel in Quel'Thalas hat sie auf Grund unserer mangelnden magischen Kontrolle über sie fehlgeleitet.\n\nUns bleibt keine andere Wahl, als sie für die Wiedereroberung der Insel in ihrer Zahl zu reduzieren. Kehrt nach Beendigung Eurer Arbeit zu mir zurück.", progress = nil, completion = "Ihr habt Eure erste Aufgabe erfolgreich gemeistert; lasst mich Euch dafür danken. Ein derartiger Erfolgt bestärkt mich in meinem Glauben, dass Ihr Euch besser anstellen werdet als diese jungen Blutelfen, die sich nicht an die Vorgaben ihrer Meister halten. Weitere Leistungen wie diese werden belohnt werden - nicht nur mit Wissen, sondern auch mit greifbaren Belohnungen.\n\nDennoch, Eure Arbeit hier ist noch nicht getan. Es gibt noch viel zu lernen, mein Kind...", rewards = "Grüne KettenstiefelWyrmschärpeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8326] = {title = "Bedauerliche Maßnahmen", objective = "Sammelt 8 Luchshalsbänder von erlegten Bachtatzenluchsen und Bachtatzenjungen ein. Kehrt zu Magistrix Erona auf der Insel der Sonnenwanderer zurück, sobald Ihr Eure Aufgabe erfüllt habt.", description = "Eure Bemühungen haben uns etwas erkennen lassen, von dem ich hoffte, es wäre nicht wahr. Die unkontrollierte Macht der brennenden Kristalle hat einen viel größeren Teil des natürlichen Gleichgewichts der Insel durcheinander gebracht als ich vermutet habe. Wir müssen jetzt leider bedauerliche Maßnahmen ergreifen, um die Kontrolle wiederzuerlangen.\n\nDie Luchse aus der Umgebung sind dem Einfluss der Kristalle erlegen und müssen bekämpft werden. Bringt mir ihre Halsbänder, <Name>. Noch kann ich vielleicht einen Magieschutz anfertigen, der manche wieder dem Einfluss entziehen kann.", progress = "Es bereitet mir keine Freude, Euch um die Vernichtung dieser Kreaturen zu bitten. Wir haben in der Vergangenheit stets in Harmonie mit den Geschöpfen des Waldes gelebt, aber heute ist es anders. Der Grundsatz der Sin'dorei lautet Überleben; vergesst das nie.", completion = "Der Turm und die unmittelbare Umgebung sollten jetzt einigermaßen sicher sein, zumindest vorerst. Dank Euch haben wir an Sicherheit gewonnen, aber es gilt die Kontrolle über die ganze Insel wiederzuerlangen, wenn wir hier auf Dauer überleben wollen. Es wird weitaus mehr verlangen, als Manawyrms und Luchse auszulöschen.\n\nNehmt dies, &lt;Name&gt; - es wird Euch bei Euren künftigen Taten sicherlich von Nutzen sein.", rewards = "Armschienen der MorgensonneLuchshauthandschuheGrüne KettenwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8327] = {title = "Berichterstattung an Lanthan Perilon", objective = "Sprecht mit Lanthan Perilon auf der Insel der Sonnenwanderer. Er steht in der Nähe des Pfads, der vom Sonnenturm Richtung Westen verläuft.", description = "Erstattet meinem Assistenten Lanthan Perilon Bericht. Er wird Euch sagen, was es als Nächstes zu tun gilt. Während wir hier am Sonnenturm weiterhin über die brennenden Kristalle walten, werdet Ihr Euch auf eine dringendere Angelegenheit bezüglich der Akademie von Falthrien konzentrieren. Lanthan wird Euch alles erklären, wenn Ihr mit ihm sprecht.\n\nGeht einfach von hier aus gen Westen entlang des Pfads, Ihr solltet ihn in der Nähe antreffen.\n\nViel Glück, <Name> - jeglicher Erfolg soll belohnt werden.", progress = nil, completion = "Magistrix Erona sagte mir bereits, dass Ihr schon bald hier sein würdet, &lt;Name&gt;. Es steht sehr schlecht um die Akademie von Falthrien, das große schwebende Gebäude mit den kunstvollen Türmchen, das westlich von uns liegt. Ihr werdet den Rückeroberungsversuch gegen einen Getriebenen anführen - einen Blutelfen, der ihrer erbärmlichen Gier auf ewig verfallen ist.\n\nIch hoffe Ihr seid bereit. Dies wird Euch nicht nur einiges über Gefahren lehren, sondern auch etwas über das Schicksal, das Euch ereilt, wenn Ihr Eure Existenz leugnet.", rewards = nil}
MultiLanguageQuestData['de'][8328] = {title = "Ausbildung zum Magier", objective = "Sprecht mit Julia Sonnensturm - der Magierlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Magier hier auf der Insel der Sonnenwanderer ist Julia Sonnensturm. Sprecht mit Julia, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nJulia - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", progress = nil, completion = "Ah, &lt;Name&gt; - Ihr gehört wohl zu den neuen Magiern hier auf der Insel, ja? Nun, Ihr seid hier richtig. Wenn es die Arkanbeherrschung ist, nach der Ihr sucht, dann kann ich Euch dieses Wissen vermitteln - solange Ihr über die erforderlichen Mittel verfügt, um die Ausbildungskosten zu tragen und solange Ihr Euch auf das konzentrieren könnt, was ich Euch lehre.\n\nLasst uns anfangen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8329] = {title = "Ausbildung zum Krieger", objective = "Sprecht mit Delios - dem Kriegerlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Krieger hier auf der Insel der Sonnenwanderer ist Delios. Sprecht mit ihm, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, habt also ein paar Münzen bei Euch.\n\nDelios - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms auf der unteren Ebene anzutreffen.", progress = nil, completion = "Willkommen beim Sonnenturm, junger &lt;Klasse&gt;! Die Lehre der Waffen und der Kampfkünste beginnt hier und jetzt - ich verlange von meinen Schülern lediglich die Begleichung der aufkommenden Ausbildungskosten und ein Maß an Aufmerksamkeit, dass ihrem Streben als &lt;Klasse&gt; gerecht wird. Ich biete eine umfassende Ausbildung an und mag es nicht, wenn ich mich unnötig wiederholen muss.\n\nNa dann, lasst uns beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8330] = {title = "Solanians Habe", objective = "Sammelt Brunnenbehüter Solanians Seherkugel, seine Rolle der Geißelmagie und sein Tagebuch ein. Ihr findet die Gegenstände auf der Insel der Sonnenwanderer bei dem Tümpel, dem Brunnen und bei einem der brennenden Kristalle. Bringt sie zu dem Brunnenbehüter oben im Sonnenturm auf der Insel der Sonnenwanderer, sobald Ihr alle gefunden habt.", description = "Bei dem Chaos hier beim Sonnenturm, habe ich es nicht geschafft, all mein Hab und Gut zusammenzusammeln, das ich an verschiedenen Plätzen auf der Insel gelassen habe. Ich muss hier beim Sonnenbrunnen weiterhin Wache halten, aber könntet Ihr vielleicht meine Sachen an meiner Stelle suchen gehen?\n\nIch brauche meine Seherkugel, meine Rolle der Geißelmagie und mein Tagebuch. Nutzt diesen Ranzen für zusätzliches Gepäck, da die Dinge etwas sperrig sind. Bringt sie zu mir zurück und ich gebe Euch dafür etwas im Austausch - für Eure Mühe, versteht Ihr? Den Ranzen könnt Ihr dann auch behalten!", progress = "Habt Ihr meine Sachen finden können? Sobald wir unsere Herrschaft über die Insel der Sonnenwanderer wiedererlangt haben, werde ich sie für meine Arbeit benötigen. Vorerst muss ich noch über den Sonnenbrunnen wachen... oder was davon übrig ist.", completion = "Gut gemacht - ich wusste, dass Ihr für diese Aufgabe geeignet sein würdet. Sobald wir uns auf der Insel wieder frei bewegen können, werde ich meine Sachen gut einsetzen.\n\nWie ich schon sagte, Ihr könnt den Ranzen behalten. Außerdem könnte auch dieses Rüstungsteil von Nutzen für Euch sein. Betrachtet es als großzügige Entlohnung für eine einfache Pflichterfüllung!", rewards = "Handschuhe des BrunnenbehütersKordel des SonnenturmsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8331] = {title = "Aurel Goldblatt", objective = "Sprecht mit Aurel Goldblatt auf Burg Cenarius.", description = "<Name>, wir hatten angenommen, dass wir die Operationen des Schattenhammerklans in Silithus verlangsamt haben... bedauerlicherweise lagen wir falsch. Durch verschiedene Unternehmungen gegen den Kult, haben wir herausgefunden, dass eine noch viel dunklere Macht hinter dem Schattenhammerklan steht, der sogenannte Abyssische Rat. Er kontrolliert den Kult über die arkanen Windsteine, die in den Lagern der Schattenhammerkultisten postiert sind. Daher, <Name>, werdet Ihr als nächstes gegen den abyssischen Rat ins Feld ziehen.\n\nSprecht mit Aurel Goldblatt im östlichen Teil von Burg Cenarius. Für unseren nächsten Schachzug werden wir ihre Hilfe benötigen.", progress = nil, completion = "Guten Tag, &lt;Name&gt;. Mir wurde gesagt, dass Ihr Euch mit dem abyssischen Rat messen wollt? Wenn dem so ist, hört mir genau zu…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8332] = {title = "Fürsten des Rates", objective = "Bringt Aurel Goldblatt auf Burg Cenarius 1 großen glänzenden Splitter und 3 Abyssische Wappen.", description = "Wir glauben, es sollte möglich sein, mithilfe eines der Windsteine einen der Fürsten des Abyssischen Rates in eine Falle zu locken. Um das zu bewerkstelligen, werdet Ihr den Rat mit einem der Windsteine kontaktieren müssen. Dann gilt es, Euer Gegenüber davon zu überzeugen, dass Ihr ein Offizier mittleren Ranges des Schattenhammers seid.\n\nFür Euren Täuschungsversuch werden wir auf jeden Fall die Nachbildung eines Standesmedaillons des Schattenhammers benötigen. Ich kann ein solches Medaillon anfertigen, allerdings brauche ich dafür einen großen glänzenden Splitter und das Wappen eines abyssischen Templers.\n\nBringt mir diese Komponenten und ich fertige Euch das Medaillon an.", progress = "Ah, <Name>, habt Ihr den Splitter und die Wappen? Nur mit diesen Komponenten kann ich Euch das Standesmedallion eines Twilightkultisten anfertigen.", completion = "Ah, sehr gut. Das Medallion ist fast fertiggestellt. Wartet kurz, während ich Eure Komponenten in das Medallion einarbeite…\n\nDas hätten wir. Hier ist das Medallion, &lt;Name&gt;.\n\nIhr müsst das Medallion tragen, wenn Ihr einen der Windsteine der Twilight-Hammer aktiviert. Solange Ihr das Medallion und den restlichen Twilightzierat tragt, wird Euch der abyssische Rat für einen ihrer niederen Kultisten halten.", rewards = "Ihr bekommt:\n\nStandesmedaillon eines Schattenhammerkultisten"}
MultiLanguageQuestData['de'][8333] = {title = "Das Standesmedaillon", objective = "Falls Ihr ein weiteres Standesmedaillon eines Twilightkultisten braucht, helfe ich Euch gerne weiter. In jedem Fall benötige ich jedoch einen weiteren glänzenden Splitter und einige abyssische Wappen…", description = nil, progress = "Falls Ihr ein weiteres Standesmedaillon eines Twilightkultisten braucht, helfe ich Euch gerne weiter. In jedem Fall benötige ich jedoch einen weiteren glänzenden Splitter und einige abyssische Wappen…", completion = "Hier, nehmt es, &lt;Name&gt;. Ein weiteres Standesmedaillon der Twilight. Nutzt es weise, und alles Gute für Euren Kampf gegen den abyssischen Rat!", rewards = "Ihr bekommt:\n\nStandesmedaillon eines Schattenhammerkultisten"}
MultiLanguageQuestData['de'][8334] = {title = "Aggressivität", objective = "Tötet 7 Borklinge und 7 wilde Borklinge. Kehrt dann zu Lanthan Perilon auf der Insel der Sonnenwanderer zurück.", description = "Bevor ich Euch zur Akademie aussende, möchte ich, dass Ihr Euch um eine andere Aufgabe kümmert, die es sofort zu erledigen gilt. Einst halfen uns die Borklinge, die Pflanzenwelt der Insel der Sonnenwanderer zu erhalten, aber jetzt sind uns diese Bestien außer Kontrolle geraten. Helft uns so schnell wie möglich bei ihrer Vernichtung, aber seid gewarnt - der Verlust ihrer Kontrolle hat sie äußerst aggressiv werden lassen. Es ist diese Angriffslust, die uns zwingt, diese einst friedlichen Untergebenen zu zerschlagen.\n\nEs bereitet mir keine Freude, Euch um diesen Gefallen zu bitten, aber es geht nun mal ums Überleben. Ich werde später trauern.", progress = nil, completion = "Der Tod der Borklinge macht mich zwar nicht glücklicher, aber es beweist mir, dass Ihr für die wichtigste Aufgabe hier auf der Insel der Sonnenwanderer bereit seid. Nehmt dies und setzt es mit Bedacht ein; Ihr werdet gute Waffen und einen scharfen Verstand für Euren nächsten Auftrag brauchen. Es liegt an Euch, ob wir die Kontrolle über die Insel erfolgreich wiedererlangen.", rewards = "Schwert des SonnenwanderersDolch des SonnenwanderersAxt des SonnenwanderersStab des SonnenwanderersStreitkolben des SonnenwanderersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8335] = {title = "Felendren der Verbannte", objective = "Tötet 8 Arkangespenster, 2 besudelte Arkangespenster und Felendren den Verbannten. Ihr findet sie in der Akademie von Falthrien. Bringt Felendrens Kopf zu Lanthan Perilon auf der Insel der Sonnenwanderer.", description = "Einer unserer Verräter haust oben in der Akademie von Falthrien.\n\nFelendren ist sein Name. Er wurde aus dem Reich der Blutelfen verbannt, da er die Warnungen unserer Lehrer und Ältesten missachtet hat. Er ist der Schlimmste unserer Art, da er nur nach der Befriedigung seines unstillbaren Magieverlangens strebt. Er hat sich der Kontrolle verweigert und ist nur noch ein Schatten seines einstigen Selbsts - ein Getriebener - und er stellt eine Bedrohung für den Sonnenturm dar.\n\nVernichtet ihn und die Gespenster, die er sich als Diener zu Nutzen macht.", progress = "Lasst Euch gewarnt sein - Felendren der Verbannte ist nur das Anzeichen eines viel größeren Problems. Sein Untergang wird lediglich unsere momentanen Schwierigkeiten lösen. Allen Blutelfen könnte das gleiche Schicksal wie ihn ereilen, sollten wir unserem Verlangen gänzlich erliegen.", completion = "Felendrens Kopf... Ihr verdient Lob, &lt;Name&gt;. Wo andere, wie Felendren, versagt haben, habt Ihr Euch erfolgreich gezeigt. Vielleicht seid Ihr wirklich bereit, ein gleichgestelltes Mitglied der Blutelfen zu werden.\n\nEuer Erfolg hier beweist, dass Ihr vor den größeren Bedrohungen Immersangs gefeit seid... und glaubt mir, es gibt genug davon.", rewards = "Bogen des SonnenwanderersSchild des SonnenwanderersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8336] = {title = "Für eine Handvoll Fragmente", objective = "Sammelt 6 Arkanspäne und bringt sie zu Arkanist Ithanas auf der Insel der Sonnenwanderer. Derartige Fragmente findet man bei allen Mana benutzenden Kreaturen auf der Insel.", description = "Es ist eine Schande, dass wir die Kontrolle über so viele Kreaturen hier auf der Insel verloren haben. Es war einst ein ruhiger Ort der Studien und Forschungsarbeiten. Jetzt können wir uns nur noch hüten, damit wir von unseren eigenen Kreationen nicht angegriffen werden!\n\nIch biete Euch einen magischen Segen an, wenn Ihr für mich etwas einsammelt. Bringt mir eine Handvoll Arkanspäne von den Mana benutzenden Kreaturen der Insel der Sonnenwanderer und ich wirke einen Zauber auf Euch, welcher Eure weiteren Abenteuer immens erleichtern wird.", progress = "Einst waren uns viele der Lebewesen auf dieser Insel friedlich gesinnt, unsere Magie hielt sie in einem permanenten Zustand der Kontrolle. Doch mit der Zerstörung des Sonnenbrunnens durch die Geißel verloren wir auch unsere Kontrolle über sie. Die Arkanspäne sind das letzte Überbleibsel unserer damaligen Beherrschungsmagie, und als solche können sie uns vielleicht bei der Erschaffung eines neuen Artefakts helfen, mit dessen Macht wir die Kontrolle zurückerlangen werden.\n\nNoch wichtiger, mithilfe der Fragmente könnten wir herausfinden, unter welchem Fluch diese Insel wirklich leidet...", completion = "Großartig, die werden ihren Zweck erfüllen! Ursprünglich habe ich diesen abgelegenen Ort aufgesucht, um in aller Ruhe nachzudenken und zu erforschen, unter welchem Fluch die Insel der Sonnenwanderer leidet. Eine der Möglichkeiten, die ich in Betracht zog, war das Sammeln der Arkanspäne von den Wildtieren auf der Insel. Mit ihnen wollte ich experimentieren, um eine mögliche Ursache zu entdecken.\n\nWie auch immer, ich werde mich weiter auf meine Forschungen konzentrieren. Erlaubt mir, diesen Zauber auf Euch zu wirken. Ich denke, Ihr werdet ihn sehr nützlich finden!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSeelenstärke der Sin'dorei\n\nIhr bekommt:\n\nUmhang des Tageslichts"}
MultiLanguageQuestData['de'][8338] = {title = "Besudelter Arkanspan", objective = "Bringt den besudelten Arkanspan zu Arkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer.", description = "Das Fragment kristallisierten Manas, das Ihr bei dem Körper des besudelten Arkangespensts gefunden habt, ist äußerst sonderbar. Es ist anders als die Fragmente, die Ihr vielleicht sonst gesehen habt. Es sieht so dunkel und unheimlich wie das Gespenst, von dem Ihr es habt, aus. Hält man es in der Hand, spürt man bereits etwas unnatürlich Bedrohliches.\n\nArkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer könnte für das Fragment vielleicht Verwendung finden.", progress = "Ich entnehme Eurer Haltung, dass es um etwas Dringliches geht. Kann ich Euch irgendwie behilflich sein?", completion = "Das ist... äußerst interessant. Mit interessant meine ich beunruhigender als alles andere.\n\nUnser Bestreben nach der Zerstörung des Sonnenbrunnens wieder die Kontrolle über diese Insel zu erlangen, war eine Herausforderung. Ich vermute, welch Übel auch immer der Grund für diese Verderbnis der Insel ist, dass das Fragment uns weitere Auskünfte über dessen Ursprung geben kann.\n\nEs war weise von Euch, damit zu mir zu kommen, &lt;Name&gt;. Nehmt dies als Vergütung für Eure Mühen. Ich danke Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8341] = {title = "Lords des Rates", objective = "Bringt Aurel Goldblatt auf Burg Cenarius 5 große glänzende Splitter und 3 abyssische Siegel.", description = "Ein Lord des Abyssischen Rates kann nur durch einen großen Windstein herbeigerufen werden und nur den höchstdekorierten Ratsmitgliedern des Schattenhammers ist es erlaubt mit den Lords in Kontakt zu treten. Doch... ich habe einen Weg gefunden, um Eure Verkleidung anzupassen und somit die abyssischen Fürsten zu täuschen!\n\nDazu benötigen wir einen Herrschaftsring, welcher nur von den höchsten Mitgliedern des Kultus getragen wird. Ich kann Euch einen Ring anfertigen, wenn Ihr mir einige große glänzende Splitter und ein paar abyssische Siegel bringt.", progress = "Habt Ihr die Splitter und Wappen, <Name>? Ich brauche sie, um den Herrschaftsring anzufertigen.", completion = "Habt Dank. Gebt mir einen Moment Zeit, um den Ring zu vollenden…\n\nSo, das sollte es gewesen sein. Denkt daran, den Ring, das Standesmedallion und den restlichen Twilightzierat anzulegen, bevor Ihr einen der großen Windsteine aktiviert. Wenn Ihr alles richtig gemacht habt, werden die Mitglieder des abyssischen Rates Euch für einen ihrer Gefolgsleute halten. Anschließend sollte es Euch gelingen, einen von ihnen in die Falle zu locken!", rewards = "Ihr bekommt:\n\nHerrschaftsring eines Schattenhammerkultisten"}
MultiLanguageQuestData['de'][8342] = {title = "Herrschaftsring des Schattenhammerklans", objective = "<Name>, wenn Ihr Euch noch einmal um den Hohen Abyssischen Rat bemühen möchtet, dann werdet Ihr einen weiteren Herrschaftsring des Schattenhammerklans benötigen. Bringt mir mehr Splitter und Siegel und ich fertige Euch einen weiteren an.", description = nil, progress = "<Name>, wenn Ihr Euch noch einmal um den Hohen Abyssischen Rat bemühen möchtet, dann werdet Ihr einen weiteren Herrschaftsring des Schattenhammerklans benötigen. Bringt mir mehr Splitter und Siegel und ich fertige Euch einen weiteren an.", completion = "Ah, ich sehe, dass Eure Überzeugungen stark sind. Nicht viele werden diesem Rat von Unmenschen gegenüberstehen!\n\nHier ist Euer Ring, &lt;Name&gt;. Möge Euer Wille und Euer Glück beständig sein.", rewards = "Ihr bekommt:\n\nHerrschaftsring eines Schattenhammerkultisten"}
MultiLanguageQuestData['de'][8343] = {title = "Goldblatts Entdeckung", objective = "Sprecht mit Aurel Goldblatt auf Burg Cenarius.", description = "<Name>, Aurel Goldblatt glaubt einen Weg gefunden zu haben, eines der führenden Mitglieder des Abyssischen Rates zu beschwören und zu besiegen. Diese Aufgabe wird äußerst gefährlich werden und Ihr genießt den größten Respekt innerhalb des Zirkels des Cenarius. Daher glauben wir, dass wenn es jemanden gibt, der diese schwere Prüfung meistern kann, dann seid Ihr es.\n\nMöge Euch das Schicksal gnädig sein, <Name>! Sprecht mit Aurel, wenn Ihr bereit seid.", progress = nil, completion = "Was Huum sagt, entspricht der Wahrheit. Ich denke, ich weiß, wie ich einen der Lords des abyssischen Rates beschwören kann! Ich werde es Euch erklären, hört genau zu…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8344] = {title = "Schlüssel zur Macht", objective = "Bring 4 Essenzen eines Gespenstes und 1 Essenz eines besudelten Gespenstes zu Beschwörer Teli'Larien beim Sonnenturm auf der Insel der Sonnenwanderer.", description = "Erhört meine Worte, Kind - diese Insel ist von einem Makel behaftet, der mächtiger als die Überbleibsel der Geißel ist.\n\nIch glaube, dass auf der Insel eine wirklich dämonische Präsenz vorherrscht.\n\nWestlich von hier liegen die Türme der Akademie von Falthrien. Die Arkangespenster, die dort hausen, sind der Schlüssel zu der dämonischen Machtquelle. Bringt mir Essenzen von besudelten und unbesudelten Gespenstern.\n\nIm Austausch für Euren Gehorsam, werde ich Euch lehren, wie man einen Wichtel als Begleiter beschwören kann - Euren ersten von vielen als Hexenmeister.", progress = "Die Essenzen der Gespenster werden mir als Grundlage für meine Experimente dienen. Es ist, wie in Eurem Leben als Hexenmeister auch, wichtig, vom dem zu lernen, was wir in der Welt finden... bevor wir es nach unserem Willen formen. Da Dämonen eine der mächtigsten Machtquellen darstellen, stellt eine derartige Präsenz auf der Insel einen wahren Segen dar.\n\nNun... einen Segen für uns Hexenmeister.", completion = "Gut gemacht! Ja, diese Essenzen sollten für den Beginn meiner Experimente ausreichen. Ich habe so ein Gefühl, als würde diese besudelte Essenz der Schlüssel sein... der Schlüssel, den ich erwähnte.\n\nEs ist äußerst ratsam für einen jungen Hexenmeister, die Anweisungen seines Meisters zu befolgen. Wie versprochen, die Belohnung für Euren Gehorsam und die meisterliche Erfüllung Eurer Aufgabe - das Wissen zur Beschwörung und Bindung Eures eigenen Wichtels.\n\nSetzt ihn weise ein &lt;Name&gt;.", rewards = "Ihr erlernt:\n\nWichtel beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Wichtel beschwören' lehren\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8345] = {title = "Der Schrein von Dath'Remar", objective = "Lest die Tafel am Schrein von Dath'Remar und kehrt anschließend zu Brunnenbehüter Solanian beim Sonnenturm auf der Insel der Sonnenwanderer zurück.", description = "Tag für Tag stehe ich hier, beobachte, warte. Man hat mich beschuldigt, zu tief in unserer Vergangenheit zu graben, während mein Blick zum Horizont gerichtet ist. Ich glaube jedoch fest daran, dass jeder Besucher dieser Insel diejenigen ehren sollte, die alles dafür geopfert haben, damit andere fortfahren können.\n\nDath'Remar Sonnenwanderer war unser erster König. Er führte uns durch den Mahlstrom von Kalimdor hierher.\n\nSucht seinen Schrein im Westen auf und kehrt erst dann zu mir zurück, wenn Ihr die dort angebrachte Tafel zu seiner Ehre gelesen habt.", progress = nil, completion = "Ah, &lt;Name&gt; - Danke, dass Ihr mir von Euren Beobachtungen beim Schrein von Dath'Remar erzählt habt. Euer Forscherdrang hat uns und Euch heute ausgezeichnete Dienste geleistet. Ich bin sicher, er wird Euch nicht nur hier, sondern in ganz Azeroth von Nutzen sein.\n\nWas Eure merkwürdigen Empfindungen beim Schrein angeht, ich denke, dass sich dort ein Teil der Verderbnis eingenistet hat, die die gesamte Insel der Sonnenwanderer bedroht. Wir werden die Sache im Auge behalten; danke, dass Ihr uns alarmiert habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8346] = {title = "Unstillbarer Durst", objective = "Verwendet die Fähigkeit 'Arkaner Strom' auf einen Manawyrm und kehrt anschließend zu Arkanist Helion zurück.", description = "Wenn es eine Lektion von Eurer Zeit auf der Insel der Sonnenwanderer gibt, die Ihr niemals vergessen dürft, dann ist es diese: Verliert unter keinen Umständen die Kontrolle über Euer Verlangen nach Magie. Dieser Durst ist unstillbar, <Name>. Verwendet den arkanen Strom, um das, was Ihr absorbiert, zu kontrollieren und in der von Euch gewünschten Form wieder freizulassen. Begeht Ihr dabei einen Fehler, werdet Ihr zu einem Getriebenen... hoffnungslos abhängig und dem Wahnsinn verfallen.\n\nSucht nach einem Manawyrm und fokussiert Euren Manadurst auf ihn. Lernt, Eure Macht zu kontrollieren. Kehrt zu mir zurück, wenn Ihr einen arkanen Strom entfesselt habt - und das zufriedenstellend.", progress = nil, completion = "Ihr habt Euch heute bewiesen, &lt;Name&gt;. Eurer Wille zu lernen zeigt, dass Ihr Euch sehr wohl gegenüber dem endlosen Verlangen, welches jeden Blutelfen beherrscht, durchsetzen könnt.\n\nRuht Euch nicht auf Euren Lorbeeren aus, sondern versucht zu meistern, was Ihr gelernt habt. Nur durch Tatendrang können wir als Volk überleben.\n\nNehmt dies - es wird Euch von Nutzen sein. Geht nun und macht unserem Volk noch einmal Ehre.", rewards = "Grüne KettenstulpenArmschienen der LebhaftigkeitHosen des WanderersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8347] = {title = "Unterstützung für die Kundschafter", objective = "Sprecht mit Kundschafterin Alarion nahe der Brücke, die in den Süden der Insel der Sonnenwanderer führt.", description = "Magistrix Erona möchte, dass Ihr Euch nach Silbermond begebt, um die dortigen Bestrebungen zur Wiedereroberung zu unterstützen... allerdings gilt es vorher noch, etwas bei der Akademie von Falthrien zu erledigen. Ihr habt uns nicht enttäuscht, <Name>.\n\nAuf Eurem Weg zum Falkenplatz südlich von hier solltet Ihr mit Kundschafterin Alarion sprechen. Sie ist nicht weit der Brücke.\n\nDie Kundschafter kümmern sich um den Warenverkehr zwischen hier und dem Landesinneren der Insel, und da Ihr Eure Tatkräftigkeit eindrucksvoll unter Beweis gestellt habt, denke ich, dass sie Eure Hilfe sicherlich sehr begrüßen werden.", progress = nil, completion = "Oh, hallo &lt;Klasse&gt;! Ich hörte schon, dass einer von Magistrix Eronas findigen Blutelfen sich auf den Weg hierher gemacht hat, um uns Kundschaftern ein wenig zur Hand zu gehen. Etwas Hilfe kommt uns sehr gelegen, insbesondere von jemand so tatkräftigem wie Euch.\n\nSeid Ihr bereit, ein oder zwei Botengänge für uns zu erledigen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8348] = {title = "Siegel der Fürsten", objective = "Bringt Bor Wildmähne auf Burg Cenarius das abyssische Siegel.", description = "Huum hat mir erzählt, dass Ihr herausbekommen habt, wie man einen der abyssischen Fürsten herbeiruft? Eine beeindruckende Leistung, muss ich sagen.\n\nWisst Ihr, was noch beeindruckender wäre? Wenn Ihr es fertig bringt, eines dieser Dinger zu erledigen. Das sollte einen bleibenden Eindruck bei ihren Gefolgsleuten hinterlassen, wenn Ihr wisst, was ich meine. Bringt mir das Siegel des Besiegten, als Beweis Eurer Tat.", progress = "Wie lief es mit dem abyssischen Fürsten? War er ein harter Brocken?", completion = "Seit Ihr Burg Cenarius betreten habt, war mir klar, dass Ihr ein mächtiger &lt;Klasse&gt; seid. Macht weiter so!", rewards = "Ihr bekommt:\n\nBeutesack"}
MultiLanguageQuestData['de'][8349] = {title = "Bor Wildmähne", objective = "Sprecht mit Bor Wildmähne auf Burg Cenarius.", description = "Nun, da Ihr ein Medaillon habt und in der Lage seid, einen abyssischen Fürsten herbeizurufen, sprecht mit Bor Wildmähne. Er wird Euch mit einer Aufgabe, die sich gegen den Abyssischen Rat richtet, beauftragen.\n\nViel Glück, <Name>. Falls Ihr weitere Medaillons braucht, kehrt zu mir zurück.", progress = nil, completion = "Es freut mich, Euch wiederzusehen, &lt;Klasse&gt;! Gut, wie ich sehe, habt Ihr Euch eine Medallion anfertigen lassen. Für Eure nächste Aufgabe werdet Ihr sie brauchen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8350] = {title = "Erfolgreiche Lieferung", objective = "Bringt Eronas Päckchen zu Gastwirtin Delaniel im Gasthaus beim Falkenplatz im Immersangwald.", description = "Der Tod eines weiteren Kundschafters ist eine wahre Tragödie, aber es ist ein Risiko, das wir alle in Kauf nehmen, wenn wir einen Auftrag annehmen. Magistrix Erona beim Sonnenturm möchte, dass dieses Päckchen schnellstmöglich zum Gasthaus beim Falkenplatz geliefert wird.\n\nWir haben nur noch wenige Leute und niemand könnte jetzt für uns einspringen.\n\nIch möchte Euch nichts vormachen, Ihr habt selbst gesehen, wie gefährlich die Straße zum Falkenplatz sein kann, sobald man vom Dämmerweg abkommt. Fühlt Ihr Euch bereit für diese Aufgabe, <Name>?", progress = "Willkommen in meinem bescheidenen Gasthaus, <Klasse>. Ich nehme an, Ihr habt etwas für mich?", completion = "Vielen Dank, ich weiß Eure prompte Lieferung sehr zu schätzen.\n\nWo Ihr schon mal da seid, könnt Ihr es Euch auch gleich gemütlich machen. Ich habe einige Ruhesteine im Angebot, falls Ihr noch keinen erworben habt. Mit diesem Stein könnt Ihr Euch einmal alle halbe Stunde in ein Gasthaus zurückteleportieren. Macht Euch keine Sorgen, wenn Ihr Euren Ruhestein mal verlieren solltet. Kehrt einfach zu einem Gastwirt Eurer Wahl zurück und er wird Euch mit Freuden einen neuen Stein zur Verfügung stellen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErfrischendes QuellwasserGlänzender roter Apfel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8351] = {title = "Bor möchte Euch sprechen", objective = "Sprecht mit Bor Wildmähne auf Burg Cenarius.", description = "Nun, da Ihr Euch als ein führendes Mitglied des Schattenhammerklans ausgeben könnt, bin ich sicher, dass Bor Wildmähne gerne mit Euch sprechen möchte. Am besten sucht Ihr ihn gleich auf... und bereitet Euch auf eine sehr schwierige Aufgabe vor...", progress = nil, completion = "Ja, es stimmt, &lt;Name&gt;. Vor uns liegt eine sehr schwere Aufgabe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8352] = {title = "Szepter des Rates", objective = "Bringt Bor Wildmähne auf Burg Cenarius ein abyssisches Szepter.", description = "Huum und ich haben gerade über Euch gesprochen. Er erzählte mir, dass Ihr schon beinahe bereit seid, einem der abyssischen Lords entgegenzutreten!\n\nIch muss Euch warnen, das ist ein sehr gefährliches Unterfangen! Nehmt lieber Verstärkung mit, und ich meine nicht bloß ein bis zwei Eurer Freunde! Ich spreche von einer erfahrenen, kampfgestählten Truppe, die weiß, worauf sie sich einlässt. Sollten Eure Freunde aus dem gleichen Holz geschnitzt sein wie Ihr, besteht sogar eine reelle Chance, dass Ihr den Sieg davontragen werdet.\n\nFalls Ihr siegt, bringt mir wie immer einen Beweis und ich werde Euch eine wahrhaft mächtige Belohnung zuteilwerden lassen.", progress = "Und, wie ist es gelaufen? Ich würde beinahe alles tun, um meinen Posten nur für einen Moment verlassen zu können, um selbst eines dieser Dinger zu erlegen!", completion = "Ihr… Ihr habt es tatsächlich geschafft! Geschafft, &lt;Name&gt;! Dies ist die größte Truhe die wir finden konnten, und ich habe sie mit den besten Sachen gefüllt, die wir finden konnten.", rewards = "Ihr bekommt:\n\nBeutetruhe"}
MultiLanguageQuestData['de'][8353] = {title = "Hühnchengegacker für ein Pfefferminzbonbon", objective = "Spielt Gastwirt Feuerbräu ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Eisenschmiede geben!", description = "Ah, wir gehen also Süßigkeitensammeln für ein Kind? Ich dachte mir schon, dass Ihr etwas zu alt seid, um für Süßes loszuziehen...\n\nNa ja, für meine Leckerei - ein Pfefferminzbonbon aus Eisenschmiede - müsst Ihr... wie ein Hühnchen gackern! Ja, Hühnchen lieben Pfefferminzbonbons... nun ja, OK, vielleicht LIEBEN sie sie nicht... aber ich gebe Euch trotzdem kein Pfefferminzbonbon, wenn Ihr nicht wie ein Hühnchen für mich gackert!\n\nSo <Klasse>, seid Ihr dazu bereit oder nicht?! Verdient Euch Eure Süßigkeit!", progress = "Ich warte...", completion = "Was für ein Spaß! Nicht schlecht, &lt;Name&gt;! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", rewards = "Ihr bekommt:\n\nPfefferminzbonbon aus Eisenschmiede"}
MultiLanguageQuestData['de'][8354] = {title = "Hühnchengegacker für ein Pfefferminzbonbon", objective = "Spielt Gastwirt Norman ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Unterstadt geben!", description = "Ah, wir gehen also Süßigkeitensammeln für ein Kind? Ich dachte mir schon, dass Ihr etwas zu alt seid, um für Süßes loszuziehen...\n\nNaja, für meine Leckerei - ein Pfefferminzbonbon aus Unterstadt - müsst Ihr... wie ein Hühnchen gackern! Ja, Hühnchen lieben Pfefferminzbonbons... nun ja, OK, vielleicht LIEBEN sie sie nicht... aber ich gebe Euch trotzdem kein Pfefferminzbonbon, wenn Ihr nicht wie ein Hühnchen für mich gackert!\n\nSo <Klasse>, seid Ihr dazu bereit oder nicht?! Verdient Euch Eure Süßigkeit!", progress = "Ich warte...", completion = "Was für ein Spaß! Nicht schlecht, &lt;Name&gt;! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", rewards = "Ihr bekommt:\n\nPfefferminzbonbon aus Unterstadt"}
MultiLanguageQuestData['de'][8355] = {title = "Kaugummikugelexpress", objective = "Ahmt für Talvash del Kissel einen Zug nach und er wird Euch dafür eine Kaugummikugel aus Gnomeregan geben!", description = "Ah, Süßes oder Saures! Hurra!\n\nNun, auch wenn Ihr etwas Ehrenhaftes tut und Süßigkeiten für ein Kind sammelt, so kann ich Euch doch nicht so einfach davonkommen lassen. Ich hätte da eine leckere Kaugummikugel aus Gnomeregan für das Kind... wenn Ihr mir einen Zug vorführt! Haha, ja, das wär's! Der Preis für diese Kaugummikugel ist das Imitieren eines Zuges!\n\nTschugga-tschugga, <Klasse>!", progress = "Nun, legt los...", completion = "Huu-huu! Klasse, &lt;Name&gt;! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", rewards = "Ihr bekommt:\n\nKaugummikugel aus Gnomeregan"}
MultiLanguageQuestData['de'][8356] = {title = "Muskelspiel für Nugat", objective = "Ihr müsst vor Gastwirtin Allison angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Sturmwind gibt!", description = "Das ist ein... interessantes Kostüm, welches Ihr da tragt. Auch wenn Ihr nett seid und einem Kind dieses Jahr beim Süßigkeitensammeln helft, so fürchte ich doch, dass ich Euch um eine kleine Vorstellung bitten muss!\n\nMal sehen... Ihr seht in diesem... Kostüm stark und muskulös aus... jetzt gebt doch mal ein bisschen an! Ja, lasst Eure Muskeln für mich spielen, <starker Mann/starke Frau>!\n\nWenn ich Euch angeben sehe, und auch nur dann, werde ich Euch etwas von dem leckeren Nugat aus Sturmwind geben. Es ist eine großartige Schlotternachtssüßigkeit.", progress = "Wenn Ihr nicht mit Euren Muskeln angeben wollt, gibt es nichts Süßes, <Name>...", completion = "Ihr seid wirklich stark, haha! Gut gemacht, danke für die tolle Schau. Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nNugat aus Sturmwind"}
MultiLanguageQuestData['de'][8357] = {title = "Tanzen für Marzipan", objective = "Tanzt für Gastwirtin Saelienne und Ihr werdet im Gegenzug etwas von dem Marzipan aus Darnassus bekommen!", description = "Auch wenn Ihr einem Kind beim Süßigkeitensammeln helft, so müsst Ihr mir noch immer etwas für Eure Belohnung vorführen! Man kann nicht so einfach mit der Tradition brechen, nicht wahr... ?\n\nIch denke, dass ein Stück Marzipan heute eine ordentliche Tanzvorstellung wert ist! Ja genau, zeigt mal, was Ihr so drauf habt! Tanzt für mich und ich werde Euch etwas von dem leckeren Marzipan geben!", progress = "Ihr wisst doch wie man tanzt, oder? Rechter Fuß nach innen... dann nach außen... rechter Fuß nach innen... shake it Baby...", completion = "Ihr seid ganz schön tanzwütig, &lt;Name&gt;!\n\nHier ist die Süßigkeit für Eure tolle Leistung. Gruselige Schlotternächte und sagt dem kranken Kindchen alles Gute von mir! Hoffentlich wird es bald wieder gesund.", rewards = "Ihr bekommt:\n\nMarzipan aus Darnassus"}
MultiLanguageQuestData['de'][8358] = {title = "Kaugummikugelexpress", objective = "Ahmt für Kali Remik einen Zug nach und sie wird Euch dafür eine Kaugummikugel der Dunkelspeere geben!", description = "Ah, Süßes oder Saures! Ja genau, Mann!\n\nNun, auch wenn Ihr etwas Ehrenhaftes tut und Süßigkeiten für ein Kind sammelt, so kann ich Euch doch nicht so einfach davonkommen lassen. Ich hätte da eine leckere Kaugummikugel der Dunkelspeere für das Kind... wenn Ihr mir einen Zug vorführt! Haha, ja, das wär's! Der Preis für diese Kaugummikugel ist das Imitieren eines Zuges!\n\nTschugga-tschugga, <Klasse>!", progress = "Nun, legt los...", completion = "Huu-huu! Klasse, &lt;Name&gt;! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", rewards = "Ihr bekommt:\n\nKaugummikugel der Dunkelspeere"}
MultiLanguageQuestData['de'][8359] = {title = "Muskelspiel für Nugat", objective = "Ihr müsst vor Gastwirtin Gryshka angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Orgrimmar gibt!", description = "Das ist ein... interessantes Kostüm, welches Ihr da tragt. Auch wenn Ihr nett seid und einem Kind dieses Jahr beim Süßigkeitensammeln helft, so fürchte ich doch, dass ich Euch um eine kleine Vorstellung bitten muss!\n\nMal sehen... Ihr seht in diesem... Kostüm stark und muskulös aus... jetzt gebt doch mal ein bisschen an! Ja, lasst Eure Muskeln für mich spielen, <starker Mann/starke Frau>!\n\nWenn ich Euch angeben sehe, und auch nur dann, werde ich Euch etwas von dem leckeren Nugat aus Orgrimmar geben. Es ist eine großartige Schlotternachtssüßigkeit.", progress = "Wenn Ihr nicht mit Euren Muskeln angeben wollt, gibt es nichts Süßes, <Name>...", completion = "Ihr seid wirklich stark, haha! Gut gemacht, danke für die tolle Schau. Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nNugat aus Orgrimmar"}
MultiLanguageQuestData['de'][8360] = {title = "Tanzen für Marzipan", objective = "Tanzt für Gastwirtin Pala und Ihr werdet im Gegenzug etwas von dem Marzipan aus Donnerfels bekommen!", description = "Auch wenn Ihr einem Kind beim Süßigkeitensammeln helft, so müsst Ihr mir noch immer etwas für Eure Belohnung vorführen! Man kann nicht so einfach mit der Tradition brechen, nicht wahr... ?\n\nIch denke, dass ein Stück Marzipan heute eine ordentliche Tanzvorstellung wert ist! Ja genau, zeigt mal, was Ihr so drauf habt! Tanzt für mich und ich werde Euch etwas von dem leckeren Marzipan geben!", progress = "Ihr wisst doch wie man tanzt, oder? Rechter Fuß nach innen... dann nach außen... rechter Fuß nach innen... shake it Baby...", completion = "Ihr seid ganz schön tanzwütig, &lt;Name&gt;!\n\nHier ist die Süßigkeit für Eure tolle Leistung. Gruselige Schlotternächte und sagt dem kranken Kindchen alles Gute von mir! Hoffentlich wird es bald wieder gesund.", rewards = "Ihr bekommt:\n\nMarzipan aus Donnerfels"}
MultiLanguageQuestData['de'][8361] = {title = "Abyssische Kontakte", objective = "Bor Wildmähne auf Burg Cenarius in Silithus möchte, dass Ihr einen abyssischen Templer vernichtet und ihm dessen abyssisches Wappen als Beweis für Eure Tat bringt.", description = "Wir haben Kultisten des Schattenhammers dabei beobachtet, wie sie mithilfe bizarrer Rituale mächtige Elementarfürsten beschworen haben. Noch wissen wir nicht, ob das die Wesen sind, die die Kultisten verehren, oder ob diese Wesen nur Botschafter einer weit größeren Macht sind. Eines wissen wir jedoch mit Sicherheit: von diesen Elementaren erhält der Kult seine Befehle.\n\nIch möchte, dass Ihr versucht, mit einem abyssischen Templer Kontakt aufzunehmen. Wenn Ihr das getan habt, verpasst ihm eine ordentliche Tracht Prügel! Nichts stürzt eine Organisation so sehr ins Chaos, wie eine Unterbrechung der Befehlskette. Oh, und vergesst nicht, mir einen Beweis für Euren Erfolg zu bringen!", progress = "Habt Ihr Eure Aufgabe vollendet?", completion = "Hah! Ihr habt es geschafft, &lt;Name&gt;! Schon bald werden die Twilight-Hammer besiegt sein!", rewards = "Ihr bekommt:\n\nBeutetasche"}
MultiLanguageQuestData['de'][8362] = {title = "Abyssische Wappen", objective = "Ihr habt Eure Fähigkeiten im Kampf mehrfach bewiesen, <Name>. Wir müssen den Druck auf die Twilight-Hammer weiter aufrecht erhalten. Zieht los und bekämpft weitere abyssische Templer. Eure Mühen sollen nicht umsonst sein, und ich werde Euch mit einigen der Sachen entlohnen, die Huum und ich in der Schlacht erbeutet haben.", description = nil, progress = "Ihr habt Eure Fähigkeiten im Kampf mehrfach bewiesen, <Name>. Wir müssen den Druck auf die Twilight-Hammer weiter aufrecht erhalten. Zieht los und bekämpft weitere abyssische Templer. Eure Mühen sollen nicht umsonst sein, und ich werde Euch mit einigen der Sachen entlohnen, die Huum und ich in der Schlacht erbeutet haben.", completion = "Ihr habt Euch hervorragend geschlagen! Und wieder einige Templer weniger, um die ich mir Sorgen machen muss.\n\nDas ist für Euch, &lt;Name&gt;. Ich hoffe, dass Ihr einiges davon gebrauchen könnt.", rewards = "Ihr bekommt:\n\nBeutetasche"}
MultiLanguageQuestData['de'][8363] = {title = "Abyssische Siegel", objective = "Ihr habt bewiesen, dass Ihr mehr als fähig seid, es mit einem abyssischen Fürsten aufzunehmen, <Name>. Ich fördere gerne jemanden, der sich als so tapfer erweist. Bringt mir mehr Siegelringe und ich werde Euch reichlich belohnen.", description = nil, progress = "Ihr habt bewiesen, dass Ihr mehr als fähig seid, es mit einem abyssischen Fürsten aufzunehmen, <Name>. Ich fördere gerne jemanden, der sich als so tapfer erweist. Bringt mir mehr Siegelringe und ich werde Euch reichlich belohnen.", completion = "Sehr gut, &lt;Name&gt;! Der Sieg über diese Fürsten, wird die Schattenhammerkultisten eine ganze Weile beschäftigen. Hier ist, wie versprochen, Eure Belohnung. Das sind einige der wertvolleren Gegenstände, die Huum und ich gefunden haben.", rewards = "Ihr bekommt:\n\nBeutesack"}
MultiLanguageQuestData['de'][8364] = {title = "Abyssische Szepter", objective = "Ihr habt all meine Erwartungen bei weitem übertroffen, <Name>. Ihr habt Euch Gegnern gestellt, bei denen Huum und ich lange und gründlichst über einen Angriff nachdenken würden. Das Beste, was ich in dieser Sache wohl tun kann, ist, Eure Bemühungen im Kampf gegen die Twilight-Hammer und ihre Oberanführer auch weiterhin zu belohnen. Bringt mir noch mehr abyssische Szepter und ich werde mein Bestes tun, um Euch gebührend zu entlohnen.", description = nil, progress = "Ihr habt all meine Erwartungen bei weitem übertroffen, <Name>. Ihr habt Euch Gegnern gestellt, bei denen Huum und ich lange und gründlichst über einen Angriff nachdenken würden. Das Beste, was ich in dieser Sache wohl tun kann, ist, Eure Bemühungen im Kampf gegen die Twilight-Hammer und ihre Oberanführer auch weiterhin zu belohnen. Bringt mir noch mehr abyssische Szepter und ich werde mein Bestes tun, um Euch gebührend zu entlohnen.", completion = "Ich habe gewusst, dass Ihr es schaffen würdet, &lt;Name&gt;!  Hier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\nBeutetruhe"}
MultiLanguageQuestData['de'][8365] = {title = "Piratenhüte Ahoy!", objective = "Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin beim Dampfdruckpier in Tanaris.", description = "Ihr seid die Hilfe, die das Kartell entsandt hat? Ach, ich denke, Ihr werdet reichen. Hört mir genau zu, <Klasse>. Wie Ihr wisst, bin ich die Lieferantin für modische Kleidung, die in den höchsten Kreisen der Gesellschaft Azeroths gefragt ist. Könige und Königinnen, Kriegshäuptlinge und... naja wie auch immer die Horde ihre Königinnen bezeichnet, all jene tragen, was ich als modisch deklariere. Und ich verdiene mir an ihnen eine goldene Nase, was natürlich das Beste am Ganzen ist.\n\nAlso hierfür benötige ich Eure Hilfe. Lauft hinunter zur Mast- und Schotbucht und beschafft mir einen Stapel Piratenhüte, koste es was es wolle. Glaubt Ihr, Ihr schafft das, hmm?", progress = "Habt Ihr alle 20 Hüte? Ich glaube Euch kein Wort, zeigt sie her. Ich hoffe für Euch, dass sie noch sauber und ganz sind!", completion = "Oh, Ihr seid ein Schatz, auch wenn Ihr etwas länger gebraucht habt, als ich es gewohnt bin. Diese Lieferung wird mir so einiges an Geld einbringen, sobald ich diese Hüte richtig gesäubert und individuell gestaltet habe. Hier habt Ihr etwas für Eure Mühen, Ihr habt Eure Aufgabe mit Bravour erledigt. Ich empfehle Euch allerdings, etwas von dem Geld für ein Bad auszugeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8366] = {title = "Gaunerei und Erpressung im Südmeer", objective = "Sicherheitschef Bilgenritzel beim Dampfdruckpier in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten.", description = "Argh! Sie verlangen das Unmögliche von mir!\n\nDas Dampfdruckkartell möchte, dass ich den Südmeerpiraten eine Lektion erteile. Ich kann doch aber nicht an zwei Orten gleichzeitig sein; Ich muss hierbleiben, um zumindest hier alles ruhig zu halten.\n\nSeit neuestem hält nicht mal mehr das Schutzgeld, dass das Kartell regelmäßig auszahlt, die Piraten auf. Daher möchte ich Euch zeitweilig abordnen, mal dort runter zu gehen und denen Saures zu geben.\n\nIhr findet die Piraten in der Mast- und Schotbucht, die hier gleich in der Nähe gen Süden ist. Besten Dank, <Name>, ich schulde Euch was!", progress = nil, completion = "&lt;Name&gt;! Ihr seid der Mann!!!\n\nIch bin mir sicher, dass das Kartell mir jetzt wieder freundlicher gestimmt sein wird, nun da Ihr mir mit dem Südmeerabschaum geholfen habt. Lasst mal sehen, womit könnte ich Euch belohnen? Und wenn ich Euch ein paar Münzen gäbe, damit Ihr Euch hier etwas aussucht? Na, seid Ihr damit einverstanden?", rewards = "SüdmeertopfhelmSüdmeermojostiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8367] = {title = "Große Ehre", objective = "Bringt ein Ehrenabzeichen jedes Schlachtfelds zu einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath.", description = "Der Horde in einer der größten Schlachten gegen die Allianz zu dienen, ist das Ausschlaggebende für große Ehre! Die Wenigen jedoch, die der Horde auf ALL unseren aktiven Schlachtfeldern gedient haben, sind unsere wahren, großen Kämpfer. Unsere Gegner sollen besiegt werden, aber nicht mittels vereinzelter Gefechte, sondern durch einen gut koordinierten Krieg.\n\nGeht und schmettert die Allianz an allen Fronten nieder! Für Ehre! Für die Horde!", progress = "Arathi ist noch immer mit dem Blut großer Krieger getränkt und das Klirren von aufeinandertreffendem Stahl schallt durch das Alteractal. Verschwendet nicht meine Zeit, solange Ihr mir keine Neuigkeiten von der Front bringt!", completion = "Euer Unterfangen war nicht einfach, aber Euer Mut und Eure Stärke haben Euch nicht verlassen. Trennt Euch von alten Siegesabzeichen, &lt;Klasse&gt;. Keiner soll sie als Beweis Eure Taten benötigen. Nehmt Haltung an, &lt;Name&gt;. Heute werdet Ihr mit dem Stolz eines Helden erfüllt sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8368] = {title = "Schlacht der Kriegshymnenschlucht", objective = "Bringt 3 Ehrenabzeichen des Kriegshymnenklans zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, <Name>! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, <Name>?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8369] = {title = "Die Invasoren des Alteractals", objective = "Bringt 3 Ehrenabzeichen des Alteractals zu einem der Kriegshetzer der Horde, außerhalb der Schlachtfelder.", description = "Hört mir genau zu, <Name>. Egal, was auch immer Ihr über die noch immer tobende Schlacht im Alteractal gehört habt, etwas davon ist wahr: Es war die Expeditionsarmee der Sturmlanzen, die diesen Konflikt durch die Besetzung des Territoriums der Frostwölfe entfachte. Der Tag, an dem wir es der Allianz erlauben, Gebiete der Horde zu erobern, ohne militärisch zurückzuschlagen, wird der Tag sein, an dem ich meine Axt an den Nagel hänge, um den Rest meines Lebens in Schande zu verbringen. Geht jetzt und schlagt die Invasoren zurück!", progress = "Habt Ihr Neuigkeiten aus dem Lande der Frostwolf? Wie läuft die Schlacht im Alteractal?", completion = "Durch die Verteidigung unserer Ländereien im Alteractal habt Ihr Euren Mut bewiesen! Ich werde meinen Vorgesetzten von Euren Bemühungen berichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +3\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8370] = {title = "Eroberung des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\nIn der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. <Name>, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrechtzuerhalten!", progress = "Habt Ihr Neuigkeiten aus dem Arathibecken, <Name>?", completion = "Die Sicherung unserer Ressourcen im Arathibecken ist eine lebenswichtige Aufgabe! Ihr habt sie gut gemeistert, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8371] = {title = "Gemeinsames Bestreben", objective = "Bringt ein Ehrenabzeichen jedes Schlachtfelds zu einem Brigadegeneral der Allianz in einer der Hauptstädte, Dalaran oder Shattrath.", description = "Wir kämpfen nicht mehr in vereinzelten Schlachten gegen die Horde, <Junge/Mädel>.\n\nDer gesamte Sieg an einer Front bedeutet der Horde die Ressourcen abzusprechen, die sie ansonsten in einer anderen Schlacht gegen uns verwenden würden. Ebenso könnte das Aufgeben in was auch immer für einer Schlacht unserem Gegner andernorts in der Welt einen Vorteil verschaffen.\n\nDie Allianz benötigt mehr Kämpfer mit diesem globalen Verständnis... wirklich bewährte Veteranen! <Name>, kommt zu mir zurück, wenn Ihr Euch gegen die Horde auf all unseren aktiven Schlachtfeldern bewährt habt.", progress = "Wie geht's voran, Bursche?", completion = "Ihr habt nicht enttäuscht, &lt;Name&gt;! Was Ihr gelernt habt, geht über unbedeutende Medaillen und Auszeichnungen hinaus. Was Ihr gelernt habt, erlangt man nur durch Erfahrung und Abhärtung auf dem Schlachtfeld.\n\nIhr habt Euch gut geschlagen, &lt;Klasse&gt;. Ihr seid ein wahrer Held der Allianz!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8372] = {title = "Kampf um die Kriegshymnenschlucht", objective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silberschwingen sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Vorhut des Kriegshymnenklans. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, das Eschental gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Vorhut des Kriegshymnenklans, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt viel für die Allianz geleistet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8373] = {title = "Die Kraft der Pinie", objective = "Verwendet einen Stinkbombenreiniger, um alle Stinkbomben der Verlassenen zu vernichten, die hier in Süderstade losgelassen wurden. Kehrt zu Unteroffizier Hartman in Süderstade zurück, wenn Ihr fertig seid.", description = "Was ich während der Schlotternächte am meisten hasse, sind die Stinkbomben, die die Verlassenen hier inmitten von Süderstade loslassen. Wer hätte gedacht, dass eine Gedenkfeier zur Freilassung mit einer so stinkigen Sache einhergehen würde?\n\nVerwendet diesen Stinkbombenreiniger während der Schlotternächte, um die scheußlichen Stinkbomben, die die Horde womöglich hier in der Stadt loslässt, zu vernichten. Er bekämpft, dank der Kraft von Pinien, schreckliche Gerüche.\n\nHelft mit Süderstade sauber zu halten und ich werde Euch dafür ein paar Schlotternachtssüßigkeiten geben, die Ihr sicherlich mögen werdet. Abgemacht?", progress = nil, completion = "Ah, es riecht schon fast wieder gut hier. Fast.\n\nIch danke Euch, &lt;Name&gt;. Süderstade kommt vielleicht ein weiteres Mal über die Schlotternächte hinweg. Hier sind Eure Süßigkeiten, gern geschehen! Solltet Ihr noch mehr Süßigkeiten benötigen, dann könnte Euch eventuell eine Gnomin namens Katrina Schimmerstern in Eisenschmiede noch mehr verkaufen; ich glaube, dass sie sich nur während der Schlotternächte dort aufhält.", rewards = "Ihr bekommt:\n\nKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][8374] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8375] = {title = "Vergesst das Alteractal nicht!", objective = "Bringt 3 Ehrenabzeichen des Alteractals zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Ihr liegt vollkommen richtig, <Name>. Die Horde verkündet die Wahrheit, mit ihrer Behauptung, das Alteractal gehöre zum Territorium der Frostwölfe. Die Sturmlanzen kamen, auf der Suche nach Erzvorkommen und Relikten, mit friedlichen Absichten in das Tal. Die Frostwölfe jedoch, reagierten auf die Anwesenheit der Sturmlanzen mit einer, in der Allianz, bis dato unbekannten Brutalität und Aggressivität.\n\nNiemals dürfen wir all die Zwerge vergessen, die während des folgenden feigen und unangekündigten Angriffs zu Tode kamen. Geht nun, <Name>, und tragt Euren Teil zur Schlacht im Alteractal bei. Für die Allianz!", progress = "Habt Ihr Neuigkeiten, <Name>?", completion = "Ihr habt Euren Beitrag geleistet, &lt;Name&gt;! Die Allianz wird den barbarischen Ausschreitungen der Horde nicht tatenlos gegenüber stehen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +3\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8376] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese... diese Prophezeiung jemals wahr werden...\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenbeinplattenKristallüberzogene Schienbeinschützer"}
MultiLanguageQuestData['de'][8377] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenbeinschützerWüstenpirscherstulpen"}
MultiLanguageQuestData['de'][8378] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistengamaschenDünenpirscherstiefel"}
MultiLanguageQuestData['de'][8379] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenhoseWüstenblumenhandschuhe"}
MultiLanguageQuestData['de'][8380] = {title = "Kriegsausrüstung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenbeinschützerÖdniswandlerstulpen"}
MultiLanguageQuestData['de'][8381] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenhoseSandwurmhauthandschuhe"}
MultiLanguageQuestData['de'][8382] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistengamaschenSandsturmstiefel"}
MultiLanguageQuestData['de'][8383] = {title = "Vergesst das Alteractal nicht!", objective = "Die Schlacht im Alteractal tobt noch immer, <Name>! Habt Ihr schon Euren Teil zum Sieg beigetragen, <Name>?", description = nil, progress = "Die Schlacht im Alteractal tobt noch immer, <Name>! Habt Ihr schon Euren Teil zum Sieg beigetragen, <Name>?", completion = "Wieder einmal ehrt Ihr die Allianz, &lt;Name&gt;! Wenn wir so weiter machen, wird es nicht mehr lange dauern, bis die Horde vernichtet ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +3"}
MultiLanguageQuestData['de'][8384] = {title = "Inbesitznahme des Arathibeckens", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][8385] = {title = "Gemeinsames Bestreben", objective = "Ah, <Name>. Ich hoffe Ihr gebt Eure Erfahrung auch noch auf weiteren Schlachtfeldern weiter. Viele unserer Jungens und Mädels sehen mit Ehrfurcht zu erfahrenen Veteranen wie Euch auf.", description = nil, progress = "Ah, <Name>. Ich hoffe Ihr gebt Eure Erfahrung auch noch auf weiteren Schlachtfeldern weiter. Viele unserer Jungens und Mädels sehen mit Ehrfurcht zu erfahrenen Veteranen wie Euch auf.", completion = "Ihr werdet Eurem Ruf gerecht, &lt;Name&gt;. Ohne Kämpfer wie Euch, würde die Allianz keine Chance gegen die barbarischen Streitkräfte der Horde haben.", rewards = nil}
MultiLanguageQuestData['de'][8386] = {title = "Kampf um die Kriegshymnenschlucht", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][8387] = {title = "Die Invasoren des Alteractals", objective = "Die Schlacht im Alteractal tobt noch immer, <Name>! Ihr müsst schnellstmöglich in das Alteractal zurückkehren und die Invasoren aus dem Gebiet der Frostwolf vertreiben.", description = nil, progress = "Die Schlacht im Alteractal tobt noch immer, <Name>! Ihr müsst schnellstmöglich in das Alteractal zurückkehren und die Invasoren aus dem Gebiet der Frostwolf vertreiben.", completion = "Gute Arbeit, &lt;Name&gt;! Ihr könnt stolz auf Euch sein. Die Invasoren der Allianz müssen aus dem Alteractal getrieben werden, koste es, was es wolle!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +3"}
MultiLanguageQuestData['de'][8388] = {title = "Große Ehre", objective = "Viele mutige Kämpfer sehen zu Euch auf, <Name>. Ihr seid auch weiterhin ein Vorbild für alle, die sich in den Schlachten gegen die Allianz schlagen. Welche Neuigkeiten bringt Ihr mir von Euren Reisen?", description = nil, progress = "Viele mutige Kämpfer sehen zu Euch auf, <Name>. Ihr seid auch weiterhin ein Vorbild für alle, die sich in den Schlachten gegen die Allianz schlagen. Welche Neuigkeiten bringt Ihr mir von Euren Reisen?", completion = "Ihr ehrt die Horde auch weiterhin, &lt;Name&gt;. Ich freue mich zu sehen, dass Ihr nicht nachgebt.", rewards = nil}
MultiLanguageQuestData['de'][8389] = {title = "Schlacht der Kriegshymnenschlucht", objective = "Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", description = nil, progress = "Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", completion = "Gut gemacht, &lt;Klasse&gt;! Ihr habt der Horde geholfen ihr Eigentumsrecht an der Warsongschlucht zu sichern!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
MultiLanguageQuestData['de'][8390] = {title = "Eroberung des Arathibeckens", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
MultiLanguageQuestData['de'][8391] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
MultiLanguageQuestData['de'][8392] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
MultiLanguageQuestData['de'][8393] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8394] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8395] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8396] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8397] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
MultiLanguageQuestData['de'][8398] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
MultiLanguageQuestData['de'][8399] = {title = "Kampf um die Kriegshymnenschlucht", objective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silberschwingen sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Vorhut des Kriegshymnenklans. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, das Eschental gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Vorhut des Kriegshymnenklans, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8400] = {title = "Kampf um die Kriegshymnenschlucht", objective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silberschwingen sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Vorhut des Kriegshymnenklans. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, das Eschental gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Vorhut des Kriegshymnenklans, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt viel für die Allianz geleistet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1\n\nIhr bekommt:\n\n"}
