MultiLanguageQuestData['de'][8404] = {title = "Kampf um die Kriegshymnenschlucht", objective = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", description = nil, progress = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +1"}
