MultiLanguageQuestData['de'][8642] = {title = "Urahne Silberader", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
