MultiLanguageQuestData['de'][8823] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Orgrimmar sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Orgrimmar nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Orgrimmar sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Orgrimmar nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil}
MultiLanguageQuestData['de'][8824] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Darkspearstamm sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Darkspearstamm sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil}
MultiLanguageQuestData['de'][8825] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Thunder Bluff sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Thunder Bluff nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Thunder Bluff sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Thunder Bluff nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil}
MultiLanguageQuestData['de'][8826] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Undercity sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Undercity nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Undercity sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Undercity nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil}
MultiLanguageQuestData['de'][8827] = {title = "Winters Geschenke", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", description = "Ich habe gehört, dass Altvater Winter mit großzügiger Unterstützung von Kokelwälder für jeden Geschenke unter den Weihnachtsbaum von Eisenschmiede gelegt hat. Wie gerne würde ich mich auf dem Weg machen, doch leider muss ich mich noch um den PX-238 Winterwundervolt kümmern.\n\nIhr solltet dort auf jeden Fall mal vorbeischauen. Ich bin mir sicher, dass Altvater Winter auch einige Geschenke für Euch mitgebracht hat.", progress = nil, completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebling &lt;Name&gt; vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über eines der fantastischen Produkte von Kokelwälder freuen würden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8828] = {title = "Winters Geschenke", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich habe gehört, dass Altvater Winter mit großzügiger Unterstützung von Kokelwälder für jeden Geschenke unter den Weihnachtsbaum von Orgrimmar gelegt hat. Wie gerne würde ich mich auf dem Weg machen, doch leider muss ich mich noch um den PX-238 Winterwundervolt kümmern.\n\nIhr solltet dort auf jeden Fall mal vorbeischauen. Ich bin mir sicher, dass Altvater Winter auch einige Geschenke für Euch mitgebracht hat.", progress = nil, completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebsten vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über einige der fantastischen Produkte von Kokelwälder freuen würden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8829] = {title = "Die ultimative Täuschung", objective = "Bringt 1 Schattenhaut, 3 ausgefranste Monstrositätenstickereien und 1 Robe eines Schattenhammerkultisten zu Aurel Goldblatt auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz XI, um diese Aufgabe abschließen zu können.", description = "Die Anhänger des Schattenhammers operieren in zahllosen geheimen und gut getarnten Gruppen. Während der Kult unsere Welt durch zahllose Aktionen plagt, werden alle Operationen an einem uns immer noch unbekannten Ort geplant.\n\nWir sind zu der Erkenntnis gelangt, dass die Steine, mit denen die Kultisten des Schattenhammers ihre Anführer beschwören, in beide Richtungen funktionieren. Um einen der Steine ohne Gefahr benutzen zu können, werden wir versuchen, die Robe eines Abgesandten des Schattenhammers bis ins kleinste Detail nachzubilden.\n\nBeschafft die dafür benötigten Materialien und bringt sie zu Aurel Goldblatt, <Name>.", progress = "Ihr habt etwas für mich?", completion = "Ja, ich denke, das sollte ausreichen! Ich werde die Robe in den Farben eines Abgesandten der Twilight anfertigen. Ich bete zu Elune, dass meine Fertigkeiten ausreichen werden, um unsere Gegner ein weiteres Mal zu täuschen.\n\nAber macht Euch darüber keine Sorgen. Ihre habt Euren Teil der Aufgabe erfüllt und ich werde Euch dafür entsprechend entlohnen. Ihr seid ein loyaler und würdiger Verbündeter, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nMal von Remulos"}
MultiLanguageQuestData['de'][8830] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Darnassus ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Darnassus würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Darnassus ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Darnassus würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil}
