MultiLanguageQuestData['de'][8917] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Schattenkunst zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.", progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, <Name>?", completion = "Ja, Mux sollte damit hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen.", rewards = "Ihr bekommt:\n\nArmschienen der Finsternis"}
MultiLanguageQuestData['de'][8918] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.", progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, <Name>?", completion = "Ja, der alte Goblin sollte mit diesem Blut hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen.", rewards = "Ihr bekommt:\n\nBindungen der fünf Donner"}
