MultiLanguageQuestData['de'][8942] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar eine Kordel der Elemente und ein Paar Stulpen der Elemente.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen.", rewards = "Ihr bekommt:\n\nKordel der fünf DonnerStulpen der fünf Donner"}
MultiLanguageQuestData['de'][8943] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel der Furcht und ein Paar Wickeltücher der Furcht.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen.", rewards = "Ihr bekommt:\n\nGürtel des TodesnebelsWickeltücher des Todesnebels"}
MultiLanguageQuestData['de'][8944] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel der Ehre und ein Paar Stulpen der Ehre.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGürtel des HeldentumsStulpen des Heldentums"}
MultiLanguageQuestData['de'][8945] = {title = "Die letzte Bitte eines toten Mannes", objective = "Geht nach Stratholme und befreit Ysida Harmon aus den Fängen von Baron Totenschwur.", description = "Ich werde Euch mit den Informationen, nach denen Ihr verlangt, versorgen, <Name>. Aber jetzt gibt es Wichtigeres zu tun.\n\nMeine geliebte Frau wird von Totenschwurs Abschaum gefangen gehalten.\n\nIch war immer dagegen, dass sie sich dem närrischen Kreuzzug der Argentumdämmerung anschließt, aber jetzt ist es zu spät für Schuldgefühle. Ihr müsst das vollbringen, wozu ich nicht fähig war. Ihr müsst Ysida aus den Fängen des Barons befreien!", progress = nil, completion = "Ich danke Euch dafür, dass Ihr mich gerettet habt... Ich habe um mein Leben gefürchtet. Bitte akkzeptiert dies als ein kleines Zeichen meiner Dankbarkeit.\n\nAnthion ist... Nein... Er kann nicht...", rewards = "Ihr bekommt:\n\nYsidas Ranzen"}
MultiLanguageQuestData['de'][8946] = {title = "Lebensbeweis", objective = "Bringt Anthion Harmon in den Östlichen Pestländern Ysidas Medaillon.", description = "Ein wahrhaft grausames Schicksal. Welche Ironie, dass mein Liebster bei dem Versuch mich zu retten ums Leben gekommen ist. Und dennoch behauptet Ihr, mit ihm sprechen zu können.\n\nBringt ihm dieses Medaillon als Beweis dafür, dass es mir gut geht. Er darf nicht länger in dieser Welt verweilen, mein Herz könnte seinen Schmerz nicht verkraften.\n\nLebet wohl, <Name>, ich stehe auf ewig in Eurer Schuld.", progress = "Ysida... Ist sie am Leben?", completion = "Dieses Medaillon... Ihr habt sie gefunden! Jetzt kann ich endlich in Frieden ruhen.\n\nIch werde nun all Eure Fragen beantworten, &lt;Name&gt;. Aber stellt sie schnell, meine Zeit in dieser Welt läuft ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8947] = {title = "Anthions merkwürdige Anforderung", objective = "Bringt Anthion Harmon in den Östlichen Pestländern 3 Dunkeleisenbarren, 20 verzaubertes Leder, 3 Mondstoff und 4 geschmeidige unverwüstliche Bälge.", description = "Wir waren uns der Wichtigkeit von Valthalaks Amulett nicht bewusst, also wurde es zusammen mit der restlichen Beute aufgeteilt. Das erste Stück bekam ein Zwerg namens Theldren. Ich habe versucht, es mir von ihm zurückzuholen und er hätte mich fast zu Tode geprügelt. Ihr werdet ihm sein Stück gewaltsam entreißen müssen.\n\nDas Letzte, was ich über ihn hörte, ist, dass er ein Gladiator für die Dunkeleisenzwerge geworden ist. Ihn zum offenen Kampf zu bewegen, dürfte sich jedoch schwierig gestalten.\n\nBringt mir die folgenden Materialien, Ihr werdet sie brauchen.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe, <Name>?", completion = "Exzellent. Ich werde diese Dinge in etwas umwandeln, dass für uns von größerem Nutzen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8948] = {title = "Anthions alter Freund", objective = "Bringt Falrin Rankenweber in der Bibliothek von Düsterbruch das unvervollständigte Banner der Provokation.", description = "Theldren würde sich niemals freiwillig einem ehrenhaften Kampf stellen. Deshalb habe ich dieses Banner mit seinem Familienwappen hergestellt.\n\nMit der richtigen Verzauberung belegt, sollte es für ihn eine Provokation darstellen, die er nicht ignorieren kann.\n\nEin alter Kollege von mir namens Falrin weiß, was zu tun ist. Er versteht sich darauf... Leute zu verärgern. Ihr findet ihn in der Bibliothek von Düsterbruch.", progress = "Sprecht, Fremder, seht Ihr nicht, dass ich beschäftigt bin?", completion = "Anthion schickt Euch, sagt Ihr? Ich dachte, er wäre tot. Allerdings habe ich in meinem Leben schon weit seltsamere Dinge gehört.\n\nNun denn, was soll ich für Euch mit diesem Banner anstellen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8949] = {title = "Falrins Rachefeldzug", objective = "Nehmt den Ogern in der Schwarzfelsspitze oder in Düsterbruch 25 Ogerkriegsperlen ab und bringt sie zu Falrin Rankenweber im Athenaeum, der Bibliothek von Düsterbruch.", description = "Ja, ich bin fürwahr mit der Verzauberung vertraut, die Ihr benötigt, <Klasse>. Aber alles hat seinen Preis, selbst wenn Euch ein alter Freund schickt.\n\nIch hasse und verabscheue meine barbarischen Ogernachbarn von ganzem Herzen. Und nicht nur die, ich hasse die Anhänger von Omokk genauso sehr, wie ich die Anhänger von König Gordok verabscheue.\n\nIch will, dass Ihr sie tötet, und zwar Unmengen von ihnen! Bringt mir die Perlen, die sie um den Hals tragen, als Beweis für Eure Taten. Solltet Ihr dies für mich tun, können wir uns weiter über den Gefallen unterhalten, den Ihr von mir verlangt.", progress = "Habt Ihr die Gefallen erledigt, um den ich Euch gebeten habe, <Name>?", completion = "Hmmm... Verwunderlicherweise fühle ich mich keinen Deut besser, jetzt da mein Bruder durch die Hände dieser Rohlinge gefallen ist.\n\nNun, Ihr habt dennoch Euren Teil der Abmachung eingehalten. Ich werde sehen, wie ich Euch helfen kann.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPerlen der OgermachtPerlen des Ogermojo\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8950] = {title = "Die Verzauberung des Aufhetzers", objective = "Bringt Falrin Rankenweber in Düsterbruch 1 Essenz eines spöttischen Geisterwesens, 4 Dunkelrunen und 8 große glänzende Splitter.", description = "Es wäre mir ein Leichtes, das Banner mit der von Euch benötigten Verzauberung zu belegen, <Name>. Bedauerlicherweise verfüge ich allerdings nicht über die benötigten Materialien, da diese Art der Verzauberung nicht hoch im Kurs steht.\n\nIch werde die Essenz von einem der Eldrethgeisterwesen, die diese Hallen durchstreifen, einige Dunkelrunen aus Scholomance und ein paar große glänzende Splitter benötigen. Bringt mir diese Materialien und ich werde die Verzauberung für Euch vornehmen.", progress = "Habt Ihr die von mir benötigten Materialien zusammengesammelt, <Name>?", completion = "Ja, damit sollte es funktionieren. Wenn ich fertig bin, wird keine Kraft in Azeroth Euer Opfer davon abhalten können, Eure Herausforderung anzunehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8951] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel des ungezähmten HerzensKilt des ungezähmten HerzensSchiftung des ungezähmten Herzens"}
MultiLanguageQuestData['de'][8952] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der TierherrschaftHose der TierherrschaftMantel der Tierherrschaft"}
MultiLanguageQuestData['de'][8953] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Magisters, Gamaschen des Magisters und einem Mantel des Magisters zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der ZauberkünsteGamaschen der ZauberkünsteMantel der Zauberkünste"}
MultiLanguageQuestData['de'][8954] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Lichts, Beinplatten des Lichts, und einer Schiftung des Lichts zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der SeelenschmiedeBeinplatten der SeelenschmiedeSchiftung der Seelenschmiede"}
MultiLanguageQuestData['de'][8955] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Sandalen des Gläubigen, einem Rock des Gläubigen und einem Mantel des Gläubigen zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSandalen des TugendhaftenRock des TugendhaftenMantel des Tugendhaften"}
MultiLanguageQuestData['de'][8956] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel der Schattenkunst, einer Hose der Schattenkunst und einer Schiftung der Schattenkunst zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", progress = "Ihr seid zurück, <Name>. Ihr müsst mir unbedingt berichten, was Ihr herausgefunden habt. Aber zuerst zu Eurer Belohnung.", completion = "Ich kann einfach nicht glauben, dass all unsere Leben nur wegen dieses dummen Amuletts verwirkt sind. Seid Ihr sicher, dass Anthion Bodley erwähnte?\n\nNun, Ihr habt ganze Arbeit geleistet, also jetzt zu Eurer Belohnung.", rewards = "Ihr bekommt:\n\nStiefel der FinsternisHose der FinsternisSchiftung der Finsternis"}
MultiLanguageQuestData['de'][8957] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und Schulterstücken der Elemente zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der fünf DonnerKilt der fünf DonnerSchulterstücke der fünf Donner"}
MultiLanguageQuestData['de'][8958] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSandalen des TodesnebelsGamaschen des TodesnebelsMantel des Todesnebels"}
MultiLanguageQuestData['de'][8959] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", progress = "Ihr seid zurück, <Name>. Ihr müsst mir unbedingt berichten, was Ihr herausgefunden habt. Aber zuerst zu Eurer Belohnung.", completion = "Ich kann einfach nicht glauben, dass all unsere Leben nur wegen dieses dummen Amuletts verwirkt sind. Seid Ihr sicher, dass Anthion Bodley erwähnte?\n\nNun, Ihr habt ganze Arbeit geleistet, also jetzt zu Eurer Belohnung.", rewards = "Ihr bekommt:\n\nStiefel des HeldentumsBeinplatten des HeldentumsSchiftung des Heldentums"}
MultiLanguageQuestData['de'][8960] = {title = "Bodleys trauriges Schicksal", objective = "Reist zum Schwarzfels und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Schwarzfelsspitze zu finden.", description = "Wir müssen also die restlichen Stücke des Amuletts wiederbeschaffen? Bodley zu finden, könnte sich als schwierig erweisen. Er begab sich zurück in den Schwarzfels, um die Schwarzfelsspitze zu betreten, und kam nie zurück.\n\nIch würde Euch raten, den Geisterdetektor des Goblins mitzunehmen, denn ich befürchte, ihm könnte etwas Schlimmes zugestoßen sein.", progress = nil, completion = "Ich bin ja so froh, dass Ihr mich sehen könnt. Endlich habe ich jemanden, mit dem ich reden kann!\n\nWerdet Ihr uns helfen, &lt;Name&gt;? Uns dabei helfen, das wiedergutzumachen, was wir verbrochen haben? Sollte es stimmen, dass Ihr bereits das obere Stück von Lord Valthalaks Amulett besitzt, dann kann ich Euch dabei behilflich sein, die anderen Stücke zu finden, sie wieder zusammenzufügen und dieser Angelegenheit ein Ende zu bereiten.\n\nAch ja, mein Name ist Bodley. Schön, Euch kennen zu lernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8961] = {title = "Die drei Könige der Flammen", objective = "Bringt Bodley im Schwarzfels Incendius' Pyrophor, Glutsehers Glut, die Asche des Fürsten und ein geheiligtes Räuchergefäß.", description = "Um Lord Valthalak zu beschwören, müssen wir zunächst die anderen beiden Drittel des Amuletts beschaffen. Und dafür brauchen wir wiederum ein Räuchergefäß und einige ganz spezielle Kohlen, die darin verbrannt werden müssen.\n\nEs gibt drei hochrangige Feuerelementare, von denen wir diese Kohlen bekommen können: Lord Incendius in den Schwarzfelstiefen, Feuerwache Glutseher in der Schwarzfelsspitze und der Fürst der Asche in Silithus. Sammelt die Kohlen aus ihren Überresten auf und kehrt dann mitsamt eines geheiligten Räuchergefäßes zu mir zurück. Ihr könnt das Räuchergefäß von der Argentumdämmerung kaufen, wenn sie Euch wohlwollend gesinnt ist.", progress = "Wir waren Narren, diesen letzten Auftrag anzunehmen. Er sollte unser aller Untergang sein. Wenn wir bloß nicht versehentlich Lord Valthalaks Seele gestohlen hätten, die in dem Amulett verwahrt war. Wären einige von uns nicht so gierig gewesen, das Amulett unter sich aufzuteilen, wäre ich jetzt noch am Leben und könnte irgendwo sitzen und ein kühles Bier trinken oder vielleicht sogar mit einem meiner Kinder spielen.\n\n<Name>, lasst die Habsucht der Unehrenhaften nicht auch Euch ins Verderben reißen.", completion = "Ich bin beeindruckt, &lt;Klasse&gt;, aber wir haben keine Zeit zu verlieren. Ich werde Euch nun Euren nächsten Auftrag geben, da ich noch einige weitere Komponenten benötige, bevor wir fortfahren können.\n\nSprecht erneut mit mir, wenn Ihr bereit sein, Euch den nächsten vor Euch liegenden Herausforderungen zu stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8962] = {title = "Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Ich werde die Essenz der Überreste in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in Kriegsmeister Voones Kammer in Tazz'Alaor in der unteren Blackrockspitze begeben und mittels des Räuchergefäßes den korrupierten Geist meines ehemaligen Kameraden, Mor Grayhoof, beschwören. Er wird nicht ruhen können, bis er von seinem Stück des Amuletts befreit wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8963] = {title = "Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels ein Relikt von Sternenhauch.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Ich werde die Essenz des Relikts in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in den Schrein von Eldretharr im Ostflügel von Düsterbruch begeben und mittels des Räuchergefäßes den korrumpierten Geist meiner ehemaligen Kameradin, Isalien, beschwören. Ihre Seele wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments korrupiert und ihr Geist wird keine Ruhe finden, bevor Ihr es an Euch nehmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8964] = {title = "Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um die Geister meiner verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den Östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Gute Arbeit, &lt;Name&gt;. Ich werde die Essenz des Schwertes in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch zum Purpurthron in der scharlachroten Bastion in Stratholme begeben und das Räuchergefäß benutzen, um die Geister meiner ehemaligen Verbündeten, Jarien und Sothos, zu beschwören. Ihre Seelen wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments sicherlich noch weiterhin korrupiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8965] = {title = "Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unserem Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Gute Arbeit, &lt;Name&gt;. Ich werde die Essenz der Asche in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in die Kammer von Ras Frostraunen in Scholomance begeben und das Räuchergefäß benutzen, um den Geist meines ehemaligen Verbündeten, Kormok, zu beschwören. Seine Seele wurde durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments nur noch mehr korrupiert und er wird nicht ruhen können, bevor Ihr es ihm gewaltsam entreißt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8966] = {title = "Das linke Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrupierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht, fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangengenommen und gefoltert worden war. Später schlichen sich Spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", progress = "Es ist vollbracht? Ihr habt das linke Stück von Lord Valthalaks Amulett und dem Geist von meinem alten Kameraden, Mor Grayhoof, zu seiner ewigen Ruhe verholfen?", completion = "Ihr habt eine gute Tat vollbracht, &lt;Name&gt;. Ein Geist ruht nun in Frieden, aber es gibt noch viel zu tun, bevor wir dies durchgestanden haben.\n\nBedauerlicherweise ist mir nicht bekannt, wo derjenige starb, der das rechte Stück des Amuletts in seinem Besitz hatte. Aber keine Sorge, zu meinen Lebzeiten verstand ich mich ein wenig auf die Kunst der Wahrsagerei. Ich habe eine weitere Aufgabe für Euch, die es uns erlauben sollte, das letzte Stück aufzuspüren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8967] = {title = "Das linke Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", progress = "Habt Ihr etwa schon Isaliens Geist zur ewigen Ruhe gebettet und das linke Stück von Lord Valthalaks Amulett wiederbeschafft, <Name>?", completion = "Ich danke Euch, &lt;Name&gt;, dafür, dass Ihr Isaliens Geist zur ewigen Ruhe gebettet habt. Vielleicht wird sie jetzt den Frieden ihrer Göttin erfahren. Aber wir haben immer noch eine Menge Arbeit vor uns, wenn wir uns aus dieser Misere befreien wollen.\n\nBedauerlicherweise ist mir nicht bekannt, wo derjenige starb, der das rechte Stück des Amuletts in seinem Besitz hatte. Aber keine Sorge, zu meinen Lebzeiten verstand ich mich ein wenig auf die Kunst der Wahrsagerei. Ich habe eine weitere Aufgabe für Euch, die es uns erlauben sollte, das letzte Stück aufzuspüren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8968] = {title = "Das linke Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das linke Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom obersten Kreuzzügler Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", progress = "Heißt das etwa, dass Ihr bereits die Geister dieser beiden Narren erlöst und das linke Stück von Lord Valthalaks Amulett wiederbeschafft habt, <Klasse>?", completion = "Selbst wenn ich sie zu ihren Lebzeiten nicht mochte, ist es vermutlich das Beste, dass Ihr die Geister der Beiden endlich erlöst habt. Wie dem auch sei, wir haben das, wonach wir gesucht haben, und das ist schließlich die Hauptsache!\n\nBedauerlicherweise ist mir nicht bekannt, wo derjenige starb, der das rechte Stück des Amuletts in seinem Besitz hatte. Aber keine Sorge, zu meinen Lebzeiten verstand ich mich ein wenig auf die Kunst der Wahrsagerei. Ich habe eine weitere Aufgabe für Euch, die es uns erlauben sollte, das letzte Stück aufzuspüren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8969] = {title = "Das linke Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Jetzt, wo wir alles beisammen haben was wir benötigen, wird es Zeit uns darüber zu unterhalten, wen Ihr beschwören werdet.\n\nKormok war ganz okay, für einen Oger, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", progress = "Ich gratuliere Euch, <Name>, solltet Ihr mit dem linken Stück von Lord Valthalaks Amulett zurückgekehrt sein. Wenn Ihr es allerdings noch nicht habt, solltet Ihr Euch beeilen. Wir haben keine Zeit zu verlieren!", completion = "Gute Arbeit, &lt;Name&gt;! Kormok war gar kein so schlechter Kerl, für einen Oger, jedenfalls nicht zu seinen Lebzeiten. Ich hoffe, sein Geist findet den Frieden, den er verdient. Aber es gibt noch mehr für uns zu tun.\n\nBedauerlicherweise ist mir nicht bekannt, wo derjenige starb, der das rechte Stück des Amuletts in seinem Besitz hatte. Aber keine Sorge, zu meinen Lebzeiten verstand ich mich ein wenig auf die Kunst der Wahrsagerei. Ich habe eine weitere Aufgabe für Euch, die es uns erlauben sollte, das letzte Stück aufzuspüren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8970] = {title = "Ich sehe die Insel Alcaz in Eurer Zukunft", objective = "Bringt Bodley im Schwarzfels 20 Einheiten Bluttang von den Naga der Strashaz.", description = "Wie ich schon sagte, <Klasse>, zu meinen Lebzeiten spielte ich mit dem Gedanken, ein Wahrsager zu werden. Aber damit kann man bei Weitem nicht so viel Profit machen, wie Ihr vielleicht denken würdet. Die Wahrsagerei kann nämlich ganz schön gefährlich sein und die Reagenzen sind selten und teuer. Aber ich weiß genug, um den Fundort des letzten Amulettstücks zu erahnen, und somit auch den Geist meines ehemaligen Kameraden.\n\nUnd deshalb benötige ich Eure Hilfe, <Name>. Ihr müsst zur Insel Alcaz vor der Küste der Düstermarschen reisen und Bluttang von den Naga der Strashaz, die dort leben, zusammensammeln.", progress = "Bluttang, <Name>, davon brauche ich einen großen Haufen, um meine Wahrsagermagie wirken zu können. Ihr werdet vermutlich ein paar Kameraden mit zur Insel Alcaz nehmen müssen, um den Bluttang einzusammeln. Diese Strashaz sind ziemlich fiese Gesellen!", completion = "Ehrlich gesagt bin ich überrascht, dass Ihr in einem Stück zurückgekehrt seid, &lt;Name&gt;. Aber die Insel Alcaz ist momentan vermutlich Eure geringste Sorge.\n\nLasst mir jetzt ein wenig Zeit, man kann nicht einfach mit den Fingern schnippen und zuverlässige Resultate von der Wahrsagerei erwarten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRutengangtrance\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][8971] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGeschenkesammlung von Sturmwind"}
