MultiLanguageQuestData['de'][8976] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGeschenkesammlung von Eisenschmiede"}
MultiLanguageQuestData['de'][8977] = {title = "Rückkehr zu Deliana", objective = "Bringt Deliana in Eisenschmiede den extradimensionalen Geisterdetektor.", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, <Name>. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", progress = "Ihr seid zurück?", completion = "Exzellent! Gut gemacht, &lt;Name&gt;. Ich bin mir zwar nicht sicher, ob ich der Handwerkskunst des Goblins vertrauen kann, aber mir bleibt keine andere Wahl.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8978] = {title = "Rückkehr zu Mokvar", objective = "Kehrt mit dem extradimensionalen Geisterdetektor zu Mokvar in Orgrimmar zurück.", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, <Name>. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", progress = "Ihr habt den Apparat?", completion = "Ihr seid mit dem Apparat zurückgekehrt! Eure Hingabe beeindruckt mich, &lt;Name&gt;. Ausgezeichnete Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8979] = {title = "Fenstads Visionen", objective = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Apothekerin Zinge im Apothekarium von Unterstadt.", description = "Ich denke, ich bin dem Grund für das merkwürdige Verhalten auf die Spur gekommen. Habt Ihr den Duft bemerkt, der in letzter Zeit den Gestank der Kanalisation überlagert? Das neue Duftwasser und Parfüm, das gerade so angesagt ist?\n\nUnsere Gedanken werden durch die Wirkung übelster Alchemie vernebelt.\n\nEs gibt nur einen Weg, um ganz sicher zu sein: Bringt meiner Freundin Apothekerin Zinge einen Flakon von dem Parfüm und dem Duftwasser. Die Königliche Apothekervereinigung wird die Wahrheit ans Licht bringen.\n\nIch werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", progress = "Womit kann ich Euch zu Diensten sein?", completion = "Wieder eine von Fenstads fixen Ideen, wie ich sehe. Glaubt er denn tatsächlich, die Königliche Apothekervereinigung hätte nichts Besseres zu tun, als seine lächerlichen Ermittlungen zu unterstützen?\n\nNun ja, lassen wir ihm noch einmal seinen Willen.", rewards = nil}
MultiLanguageQuestData['de'][8980] = {title = "Zinges Einschätzung", objective = "Kehrt zu Fenstad Argyle außerhalb der Bank von Unterstadt zurück.", description = "Das ist in der Tat unerwartet. Es sieht ganz so aus, als ob Fenstad doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in Gedanken beinflussenden Tränken Verwendung finden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig. Es handelt sich hierbei um Alchemiekünste, die nur den Erfahrensten vorbehalten sind, so wie die Mitglieder der Königlichen Apothekervereinigung.", progress = nil, completion = "Ich hatte also Recht. Wir dürfen keine Zeit verlieren. Wir müssen die Quelle dieser verdorbenen Gerüche ausfindig machen.\n\nHier, nehmt dies als Entschädigung für das Duftwasser und Parfüm, das Ihr gekauft habt.", rewards = "Ihr bekommt:\n\nSchokoladenschachtelHandvoll RosenblütenLiebesrakete"}
MultiLanguageQuestData['de'][8981] = {title = "Geschenkübergabe", objective = "Seid Ihr gekommen, um Eurem liebsten Anführer ein Geschenk der Liebe und Verehrung darzubringen?", description = nil, progress = "Seid Ihr gekommen, um Eurem liebsten Anführer ein Geschenk der Liebe und Verehrung darzubringen?", completion = "Wunderbar! Wunderbar! Ich werde es zu den anderen Geschenken auf den Haufen legen.\n\nIch habe niemals so viele erwartet! \n\nNun, lasst mich mal ein weiteres hinzuzählen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandvoll RosenblütenSilberschaftpfeilLiebesrakete\n\nDer folgende Zauber wird auf euch gewirkt:\n\nValentinstag, Geschenk gegeben\n\nIhr bekommt außerdem:\n\nSchokoladenschachtel"}
MultiLanguageQuestData['de'][8982] = {title = "Verfolgung der Spur", objective = "Sprecht mit Gastwirt Norman in Unterstadt.", description = "Wir müssen unbedingt herausfinden, wer der Lieferant ist. Ich habe Apothekerin Katrina erst kürzlich dabei beobachtet, wie sie einen Parfümflakon in ihrem Bündel verstaute. Sie sagte mir, dass sie es von Norman, dem Gastwirt, erworben hat.", progress = nil, completion = "Oh ja, ich habe das Parfüm und Duftwasser erst seit kurzem auf Lager. Ich weiß allerdings nicht, wie lange ich es noch in den Regalen haben werde. Alle sind völlig verrückt danach.\n\nMir ist es völlig schleierhaft, was die Leute daran finden.", rewards = nil}
MultiLanguageQuestData['de'][8983] = {title = "Verfolgung der Spur", objective = "Sprecht mit Mara Rennick bei der Schneiderei im Magieviertel von Unterstadt.", description = "Ist etwas nicht in Ordnung mit meiner Ware? Nun, ich habe noch nie so viele Leute gesehen, die so sehr nach einer Sache verlangt haben.\n\nIch habe meine Bestände von einer Händlerin namens Mara Rennick. Sie ist neu in der Stadt.\n\nSie erwähnte, dass sie noch einige Waren beim Schneider im Magieviertel abzuliefern hätte.", progress = nil, completion = "Ich befürchte, dass ich meine gesamten Vorräte an Parfüm und Duftwasser an Norman, den Gastwirt, verkauft habe. Möchtet Ihr welche, solltet Ihr mit ihm sprechen - gesetzten Falls er hat noch etwas davon übrig.\n\nLasst Euch aber nicht zu viel Zeit damit. Ich bin mir sicher, dass Ihr das Duftwasser unwiderstehlich finden werdet.", rewards = nil}
MultiLanguageQuestData['de'][8984] = {title = "Lüftung des Geheimnisses", objective = "Findet Apotheker Staffron Lerent hinter dem Rabenholdtanwesen im Vorgebirge des Hügellands.", description = "Hört mal, die Taten eines abtrünnigen Apothekers sind nicht mein Problem. Sollte er tatsächlich unsere Sache untergraben, werde ich die Erste sein, die Euch die richtige Richtung weist.\n\nSollte er unschuldig sein, wird er nichts zu verbergen haben, oder?\n\nIch habe meine Ware beim Apotheker Staffron Lerent erworben. Er arbeitet im Vorgebirge des Hügellands, irgendwo hinter dem Rabenholdtanwesen. Ehrlich gesagt, kam er mir etwas komisch vor.", progress = nil, completion = "Ja, ich habe diese Düfte hergestellt. Sie duften wunderbar, nicht war? Unwiderstehlich.\n\nSobald die Krieger von Allianz und Horde gleichermaßen von Gefühlen der Liebe hingerissen sind, werden sie dem Aufstieg des Schattenrates machtlos gegenüber stehen.\n\nSie werden geschwächt und unvorbereitet sein. Da sie um ihre Liebsten besorgt sind, werden sie die Kontrolle verlieren.\n\nDie Lösung war so einfach. Warum bin ich nicht schon eher darauf gekommen? Die Schwäche aller liegt im Herzen. Es gibt nichts, was Ihr tun könntet, um das Unvermeidbare aufzuhalten.", rewards = nil}
MultiLanguageQuestData['de'][8985] = {title = "Mehr Komponenten von großer Wichtigkeit", objective = "Bringt Bodley in der Schwarzfelsspitze ein Relikt von Sternenhauch.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir wissen, wo mein ehemaliger Kamerad zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Ich werde die Essenz des Relikts in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in den Schrein von Eldretharr im Ostflügel von Düsterbruch begeben und mittels des Räuchergefäßes den korrupierten Geist meiner ehemaligen Kameradin, Isalien, beschwören.  Ihre Seele wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments korrupiert und ihr Geist wird keine Ruhe finden, bevor Ihr es an Euch nehmt.\n\nIch hatte übrigens noch etwas Bluttang von Eurem Ausflug zur Insel Alcaz übrig und habe einige Tränke für Euch gebraut. Sucht Euch was aus!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBluttangelixier des AusweichensBluttangelixier des Widerstands\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8986] = {title = "Mehr Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Ich werde die Essenz der Überreste in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in Kriegsmeister Voones Kammer in Tazz'Alaor in der unteren Schwarzfelsspitze begeben und mittels des Räuchergefäßes den korrupierten Geist meines ehemaligen Kameraden, Mor Grauhuf, beschwören. Er wird nicht ruhen können, bis er von seinem Stück des Amuletts befreit wird.\n\nIch hatte übrigens noch etwas Bluttang von Eurem Ausflug zur Insel Alcaz übrig und habe einige Tränke für Euch gebraut. Sucht Euch was aus!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBluttangelixier des AusweichensBluttangelixier des Widerstands\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8987] = {title = "Mehr Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBluttangelixier des AusweichensBluttangelixier des Widerstands\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8988] = {title = "Mehr Komponenten von großer Wichtigkeit", objective = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", description = "Hört mir gut zu, <Klasse>. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unsererm Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, <Klasse>?", completion = "Gute Arbeit, &lt;Name&gt;. Ich werde die Essenz der Asche in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in die Kammer von Ras Frostraunen in Scholomance begeben und das Räuchergefäß benutzen, um die Geister meines ehemaligen Verbündeten, Kormok, zu beschwören. Seine Seele wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments nur noch weiterhin korrupiert und er wird nicht ruhen können, bevor Ihr es ihm gewaltsam entreißt.\n\nIch hatte übrigens noch etwas Bluttang von Eurem Ausflug zur Insel Alcaz übrig und habe einige Tränke für Euch gebraut. Sucht Euch was aus!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBluttangelixier des AusweichensBluttangelixier des Widerstands\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][8989] = {title = "Das rechte Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrupierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht, fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangengenommen und gefoltert worden war. Später schlichen sich Spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", progress = "Es ist vollbracht? Ihr habt das rechte Stück von Lord Valthalaks Amulett gefunden, das Amulett wieder zusammengesetzt und dem Geist von meinem alten Kameraden, Mor Grauhuf, zu seiner ewigen Ruhe verholfen?", completion = "Ich danke Euch, &lt;Name&gt;, dafür, dass Mor Grauhufs Geist nun in Frieden ruht. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8990] = {title = "Das rechte Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", progress = "Habt Ihr etwa schon Isaliens Geist zur ewigen Ruhe gebettet und das rechte Stück von Lord Valthalaks Amuletts wiederbeschafft, <Name>? Denkt daran, Lord Valthalaks Amulett wieder zusammenzusetzen, bevor Ihr es mir gebt.", completion = "Ich danke Euch, &lt;Name&gt;, dafür, dass Ihr Isaliens Geist zur ewigen Ruhe gebettet habt. Vielleicht wird sie jetzt den Frieden ihrer Göttin erfahren. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8991] = {title = "Das rechte Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das rechte Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom obersten Kreuzzügler Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", progress = "Heißt das etwa, dass Ihr bereits die Geister dieser beiden Narren erlöst und die Stücke von Lord Valthalaks Amulett wieder zusammengesetzt habt, <Klasse>?", completion = "Selbst wenn ich sie zu ihren Lebzeiten nicht mochte, ist es vermutlich das Beste, dass Ihr die Geister der Beiden endlich erlöst habt. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8992] = {title = "Das rechte Stück von Lord Valthalaks Amulett", objective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", description = "Jetzt, wo wir alles beisammen haben, was wir benötigen, wird es Zeit uns darüber zu unterhalten, wen Ihr als nächstes beschwören werdet.\n\nKormok war ganz okay, für einen Oger, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", progress = "Ich gratuliere Euch, <Name>, solltet Ihr mit dem wieder zusammengesetzten Amulett zurückgekehrt sein. Wenn Ihr es allerdings noch nicht habt, solltet Ihr Euch beeilen. Wir haben keine Zeit zu verlieren!", completion = "Gute Arbeit, &lt;Name&gt;! Kormok war gar kein so schlechter Kerl, für einen Oger, jedenfalls nicht zu seinen Lebzeiten. Ich hoffe, sein Geist findet den Frieden, den er verdient. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8993] = {title = "Geschenkübergabe", objective = "Seid Ihr gekommen, um Eurem liebsten Anführer ein Geschenk der Liebe und Verehrung darzubringen?", description = nil, progress = "Seid Ihr gekommen, um Eurem liebsten Anführer ein Geschenk der Liebe und Verehrung darzubringen?", completion = "Wunderbar! Wunderbar! Ich werde es zu den anderen Geschenken auf den Haufen legen.\n\nIch habe niemals so viele erwartet! \n\nNun, lasst mich mal ein weiteres hinzuzählen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandvoll RosenblütenSilberschaftpfeilLiebesrakete\n\nDer folgende Zauber wird auf euch gewirkt:\n\nValentinstag, Geschenk gegeben\n\nIhr bekommt außerdem:\n\nSchokoladenschachtel"}
MultiLanguageQuestData['de'][8994] = {title = "Letzte Vorbereitungen", objective = "Bringt Bodley im Schwarzfels 40 Schwarzfelsarmschienen und ein Fläschchen der obersten Macht.", description = "Wir sind nun beinah bereit, <Klasse>. Ich brauche nur noch einige weitere Komponenten, um das Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen.\n\nFür den Anfang würde ich Euch darum bitten, Euch in die Schwarzfelsspitze zu begeben und die dort heimischen Orcs zu töten. Ihre Armschienen enthalten Metallspuren, die ich benötigen werde. Da diese Armschienen nur Spuren des Metalls enthalten, werde ich eine Menge von ihnen benötigen. Um den Abstimmungsprozess abzuschließen, brauche ich weiterhin noch ein Fläschchen der obersten Macht.\n\nViel Glück, <Name>!", progress = "Wir haben viel durchgestanden, <Name>, und ich wollte Euch nur sagen, dass ich Euch sehr dankbar bin, egal, was auch geschehen mag. Ihr habt Euch in Lebensgefahr begeben, um den überlebenden Mitgliedern unseres Söldnerbundes zu helfen. In meinen Augen seid Ihr jetzt einer von uns, ein Mitglied des Bundes der verhüllten Klinge.", completion = "Das wär's dann. Ich werde das Metall aus den Armschienen extrahieren und es in das Räuchergefäß geben. Dann wird es darauf abgestimmt sein, Lord Valthalak herbeizurufen, und Ihr könnt ihm endlich sein Seelenamulett wiedergeben.\n\nIhr habt einen weiten Weg zurückgelegt, &lt;Name&gt;, gebt jetzt nicht auf, wo das Ende in Sicht ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8995] = {title = "Mea Culpa, Lord Valthalak", objective = "Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen.", description = "Die nötigen Vorbereitungen sind nun getroffen, <Name>.\n\nZu seinen Lebzeiten bewohnte Lord Valthalak die Kammer, in der sich nun die Bestie aufhält. Geht dorthin und benutzt dann das Räuchergefäß der Beschwörung, um Lord Valthalak herbeizurufen. Es wird ihn wiederbeleben, also werdet Ihr ihn erneut töten müssen. Es wäre sinnvoll, zuerst die Bestie zu erledigen. Bringt außerdem genug Kameraden mit, um Euch durch den oberen Teil der Schwarzfelsspitze zu kämpfen.\n\nBenutzt, sobald Ihr ihn ausgeschaltet habt, das Amulett bei seiner Leiche. Nachdem seine Seele wieder vollständig ist, wird er es vermutlich zurückverlangen.\n\nViel Glück!", progress = "<Klasse>, Ihr wagt es, meine Ruhe zu stören?!", completion = "Ihr könnt Euch glücklich schätzen, dass Ihr nicht selbst der Gruppe angehört, die mir einst dieses Amulett stahl.\n\nIch werde mir jetzt das zurückholen, was mir gehört, Sterblicher! Gebt mir das Amulett!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8996] = {title = "Rückkehr zu Bodley", objective = "Bringt das Räuchergefäß der Beschwörung zurück zu Bodley im Schwarzfels.", description = "Ich werde Euch Eure Unverschämtheit dieses eine Mal vergeben, <Klasse>, da Ihr heute eine noble Tat vollbracht habt. Ihr habt mich wieder mit dem Rest meiner gestohlenen Seele vereint. Obgleich Eurer offensichtlich schwachen Natur, <Volk>, habt Ihr den Mut bewiesen, über den jene, die es wagten mich zu bestehlen, nicht verfügten und vermutlich niemals werden.\n\nKehret schnell zu ihnen zurück, bevor ich es mir anders überlege und Euch dort niederstrecke, wo Ihr steht. Kehret zurück und richtet ihnen aus, dass sie vor mir sicher sind... Momentan zumindest.", progress = "<Name>, Ihr seid lebendig zurückgekehrt! Dann ist ja wenigstens einer von uns noch am leben.\n\nIhr müsst mir unbedingt die ganze Geschichte erzählen!", completion = "Das hat er alles gesagt? Unglaublich, ich kann es kaum glauben, dass er die spektralen Assassine und Pirscher zurückrufen wird, auch wenn er ja dennoch andeutete, dass diese Sache noch ein Nachspiel haben könnte.\n\nHeute ist ein großartiger Tag, &lt;Name&gt;! Ihr habt das vollbracht, zu dem nur wenige fähig sind, und habt zumindest einen Teil unserer vergangenen Sünden gesühnt.\n\nIch danke Euch! Als Zeichen meiner Dankbarkeit werde ich Euch dies hier geben. Ihr könnt es benutzen, um an den verfluchten Orten, die Ihr bereits besucht habt, Geister zu beschwören. Und sogar noch an ein paar anderen Orten!", rewards = "Ihr bekommt:\n\nRäuchergefäß der AnrufungHandbuch: Räuchergefäß der Anrufung"}
MultiLanguageQuestData['de'][8997] = {title = "Zurück zum Anfang", objective = "Sprecht mit Deliana am Hohen Sitz von Eisenschmiede.", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Schwarzfelsspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Deliana in Eisenschmiede zurück und erzählt ihr, was vorgefallen ist.", progress = nil, completion = "Ich bin sehr glücklich darüber, dass Ihr heil zu mir zurückgekehrt seid, &lt;Name&gt;. Ihr seht zwar ein wenig mitgenommen aus, aber es scheint Euch gut zu gehen.\n\nErzählt mir alles, was vorgefallen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8998] = {title = "Zurück zum Anfang", objective = "Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar.", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Schwarzfelsspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Mokvar in Orgrimmar zurück und erzählt ihm, was vorgefallen ist.", progress = nil, completion = "Ich freue mich zu sehen, dass Ihr überlebt habt, &lt;Name&gt;. Ihr seht gut aus, und auch etwas erfahrener.\n\nErzählt mir, was vorgefallen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][8999] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Deliana Eure Gugel des Wildherzens und Eure Weste des Wildherzens.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGugel des ungezähmten HerzensWeste des ungezähmten Herzens"}
MultiLanguageQuestData['de'][9000] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Deliana Eure Bestienjägerkappe und Eure Bestienjägertunika.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKappe der TierherrschaftTunika der Tierherrschaft"}
