MultiLanguageQuestData['de'][9008] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Bestienjägerkappe und Eure Bestienjägertunika.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", progress = "Seid Ihr bereit, mir Eure Teile der Bestienjägerrüstung im Austausch gegen die neue Kappe der Tierherrschaft und die neue Tunika der Tierherrschaft zu geben?", completion = "Ich werde Euch wahrlich vermissen, &lt;Name&gt;. Ich stehe tief in Eurer Schuld, eine Schuld, die ich vermutlich niemals begleichen werden kann.\n\nGenießt Eure neue Kopf- und Brustrüstung. Möge sie Euch für lange Zeit beschützen und Euch dabei helfen, noch größere Ehren zu erlangen.", rewards = "Ihr bekommt:\n\nKappe der TierherrschaftTunika der Tierherrschaft"}
MultiLanguageQuestData['de'][9009] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Krone des Gläubigen und Eure Robe des Gläubigen.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone des TugendhaftenRobe des Tugendhaften"}
MultiLanguageQuestData['de'][9010] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Kappe der Schattenkunst und Eure Tunika der Schattenkunst.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKappe der FinsternisTunika der Finsternis"}
MultiLanguageQuestData['de'][9011] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Helmkappe der Elemente und Eure Weste der Elemente.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelmkappe der fünf DonnerWeste der fünf Donner"}
MultiLanguageQuestData['de'][9012] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Maske der Furcht und Eure Robe der Furcht.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMaske des TodesnebelsRobe des Todesnebels"}
MultiLanguageQuestData['de'][9013] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Euren Helm der Ehre und Eure Brustplatte der Ehre.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Ihr habt durch Eure Taten die Sünden unserer Vergangenheit gesühnt.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm des HeldentumsBrustplatte des Heldentums"}
MultiLanguageQuestData['de'][9014] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Krone des Magisters und Eure Roben des Magisters.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone der ZauberkünsteRoben der Zauberkünste"}
MultiLanguageQuestData['de'][9015] = {title = "Die Herausforderung", objective = "Reist zum Ring des Gesetzes der Schwarzfelstiefen und errichtet das Banner der Provokation in dessen Mitte, während Ihr von Oberrichter Grimmstein verurteilt werdet. Tötet Theldren und seine Gladiatoren und kehrt dann mit dem ersten Stück von Lord Valthalaks Amulett zu Anthion Harmon in den Östlichen Pestländern zurück.", description = "Hört mir gut zu, <Name>. Damit das Banner die gewünschte Wirkung erzielen kann, werdet Ihr Euch in den Ring des Gesetzes der Schwarzfelstiefen begeben müssen. Lasst Euch von Oberrichter Grimmstein verurteilen und errichtet das Banner als Zeichen der Herausforderung.\n\nEuer Opfer wird sich nicht zurückhalten können und sich, von dem Wunsch Euch zu bekämpfen beseelt, in den Kampf stürzen. Kehrt zu Anthion zurück, sobald Ihr das habt, wonach es Euch begehrt.", progress = "Ihr seid zurück, <Name>!", completion = "Ihr habt einen Teil des Amuletts wiederbeschafft, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9016] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel des ungezähmten HerzensKilt des ungezähmten HerzensSchiftung des ungezähmten Herzens"}
MultiLanguageQuestData['de'][9017] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", progress = "Ihr seid zurückgekehrt und ich kann Euch ansehen, dass Ihr mir viel zu berichten habt, <Name>. Aber zuerst zu Eurer Belohnung.", completion = "Dieser Fluch lastet nur wegen des Amuletts auf uns. Lord Valthalak ist scheinbar äußerst nachtragend.\n\nWir werden uns bemühen, auch die anderen Stücke zu finden - vorzugsweise bevor ich einen verfrühten Tod sterbe. Aber jetzt zu Eurer Belohnung.", rewards = "Ihr bekommt:\n\nStiefel der TierherrschaftHose der TierherrschaftMantel der Tierherrschaft"}
MultiLanguageQuestData['de'][9018] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Magisters, Gamaschen des Magisters und einem Mantel des Magisters zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der ZauberkünsteGamaschen der ZauberkünsteMantel der Zauberkünste"}
MultiLanguageQuestData['de'][9019] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Sandalen des Gläubigen, einem Rock des Gläubigen und einem Mantel des Gläubigen zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", progress = "Ihr seid zurückgekehrt und ich kann Euch ansehen, dass Ihr mir viel zu berichten habt, <Name>. Aber zuerst zu Eurer Belohnung.", completion = "Dieser Fluch lastet nur wegen des Amuletts auf uns. Lord Valthalak ist scheinbar äußerst nachtragend.\n\nWir werden uns bemühen, auch die anderen Stücke zu finden - vorzugsweise bevor ich einen verfrühten Tod sterbe. Aber jetzt zu Eurer Belohnung.", rewards = "Ihr bekommt:\n\nSandalen des TugendhaftenRock des TugendhaftenMantel des Tugendhaften"}
MultiLanguageQuestData['de'][9020] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel der Schattenkunst, einer Hose der Schattenkunst und einer Schiftung der Schattenkunst zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der FinsternisHose der FinsternisSchiftung der Finsternis"}
MultiLanguageQuestData['de'][9021] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSandalen des TodesnebelsGamaschen des TodesnebelsMantel des Todesnebels"}
MultiLanguageQuestData['de'][9022] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel des HeldentumsBeinplatten des HeldentumsSchiftung des Heldentums"}
MultiLanguageQuestData['de'][9023] = {title = "Das perfekte Gift", objective = "Dirk Donnerholz in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt.", description = "Mein Bruder und ich sind im Rabenholdtanwesen für den Giftbedarf zuständig.\n\nLord Rabenholdt hat mich damit beauftragt, eine neue und extrem effektive Giftmischung zusammenzustellen, die aus den Giftbeuteln der Bewohner von Zul'Gurub und den Ruinen von Ahn'Qiraj gewonnen werden kann.\n\nEs gibt in diesen verfluchten Ruinen zwei ganz besonders giftige Bestien, die vielleicht genau das haben, wonach wir suchen, <Klasse>. Bringt mir einen Giftbeutel der Bestien Kurinnaxx und Venoxis und wir wären Euch ewig dankbar.", progress = "Alleine packt Ihr das nicht, <Name>. Ihr werdet Kameraden mitbringen müssen.", completion = "Ravenholdt dankt Euch, Held! Sucht Euch was aus!", rewards = "Fahrads selbstladende RepetierarmbrustSchicksalsbringerDonnerholzschüreisenRabenholdtschnitzlerMesserritzels MesserSimones Hammer der KultivierungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9024] = {title = "Aristans Verdacht", objective = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Morgan Pestle im Handelsdistrikt von Sturmwind.", description = "Ich hab's! Habt Ihr den neuen Duft in den Straßen aufgeschnappt? Das neue Duftwasser und Parfüm, das gerade so angesagt ist? Unsere Wachen würden ihre Pflichten nicht so einfach vernachlässigen.\n\nZumindest nicht, solange ihre Sinne nicht von fauler Alchemie vernebelt wurden.\n\nEs gibt nur einen Weg, um ganz sicher zu sein - bringt Morgan Pestle einen Flakon von dem Parfüm und dem Duftwasser, und klärt ihn über meinen Verdacht auf. Ich werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", progress = "Kann ich Euch irgendwie behilflich sein?", completion = "Ich verstehe Aristans Bedenken, aber ich glaube wirklich, dass er überreagiert. Lasst die jungen Männer und Frauen doch einfach machen, was sie möchten. Ich denke Aristan hat vergessen, was es bedeutet, jung und verliebt zu sein.\n\nEs wäre allerdings besser, wenn Ihr ihm das nicht sagen würdet. Soll er denken, was er will.", rewards = nil}
MultiLanguageQuestData['de'][9025] = {title = "Morgans Entdeckung", objective = "Kehrt zu Aristan Mottar zurück, er befindet sich vor der Bank im Handelsdistrikt von Sturmwind.", description = "Nun... es sieht ganz so aus, als ob Aristan doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in Liebestränken und Gedanken verwirrenden Gebräuen verwendet werden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig.", progress = nil, completion = "Obwohl ich Derartiges bereits vermutet habe, ist es dennoch beunruhigend, dass mein Verdacht sich jetzt bestätigt hat. Wir müssen unseren nächsten Schritt mit Bedacht planen.\n\nHier, nehmt dies als Entschädigung für das Duftwasser und Parfüm, das Ihr gekauft habt.", rewards = "Ihr bekommt:\n\nSchokoladenschachtelHandvoll RosenblütenLiebesrakete"}
MultiLanguageQuestData['de'][9026] = {title = "Verfolgung der Spur", objective = "Sprecht mit Gastwirtin Allison im Gasthaus 'Die güldene Rose' im Handelsdistrikt von Sturmwind.", description = "Wir müssen der Ursache auf den Grund gehen. Ich habe viel mehr Leute als sonst - einschließlich Wachen - im Gasthaus 'Die güldene Rose' ein- und ausgehen sehen. Sprecht mit Allison, sollte sie verkaufen, so kann sie Euch zu der Herkunft der Ware Auskunft geben.", progress = nil, completion = "Oh ja, ich habe das Parfüm und Duftwasser erst seit kurzem auf Lager. Allerdings verkauft es sich so gut, dass ich nicht weiß, wie lange ich es noch in den Regalen haben werde.\n\nEhrlich gesagt, ich finde es etwas langweilig. Jeder duftet gleich? Es riecht gut, aber, naja.", rewards = nil}
MultiLanguageQuestData['de'][9027] = {title = "Verfolgung der Spur", objective = "Sprecht mit Evert Sorisam bei 'Das feinste Band' entlang der Kanäle Sturmwinds.", description = "Irgendwas mit dem Duftwasser? Das ist möglich. Ich habe noch nie gesehen, dass eine Ware so begehrt war wie diese.\n\nHört mal, sollte es etwas damit auf sich haben, dann möchte ich es auch wissen. Ich habe meine Lieferung von einem Händler namens Evert Sorisam. Er ist neu in der Stadt.\n\nEr erwähnte, dass er einige Waren hätte, die er bei 'Das feinste Band' abliefern müsse.", progress = nil, completion = "Ja, natürlich. Diese Düfte sind die gefragtesten Waren dieser Saison. Ihr seid bereits die fünfte oder sechste Person, die innerhalb einer Stunde nach Auskunft darüber verlangt.\n\nIch befürchte, dass meine Vorräte bereits alle ausverkauft sind. Möchtet Ihr welche, solltet Ihr mit Allison sprechen, die Gastwirtin von 'Die güldene Rose'.\n\nLasst Euch aber nicht zu viel Zeit damit. Ich bin mir sicher, dass Ihr das Duftwasser unwiderstehlich finden werdet.", rewards = nil}
MultiLanguageQuestData['de'][9028] = {title = "Lüftung des Geheimnisses", objective = "Findet Apotheker Staffron Lerent hinter dem Rabenholdtanwesen im Vorgebirge des Hügellands.Was? Verrat? Nein, nein. Ich versichere Euch, dass meine Absichten in jeder Hinsicht harmlos sind.\n\nIst es denn so falsch, denen helfen zu wollen, die dieses leidvolle Ritual des Umwerbens zu erleichtern wünschen? Kommt schon, das ist doch kein Verbrechen.\n\nIch werde Euch beweisen, dass ich keine schlechten Absichten hege, indem ich Euch meine Quelle verrate.\n\nDie Lieferung wurde mir von einem Staffron Lerent zugestellt, so eine Art Apotheker. Ich habe nie mit ihm gesprochen.\n\nUnser Goblinmittelsmann meinte, dass er im Vorgebirge des Hügellands gearbeitet hätte, irgendwo hinter dem unheimlichen Rabenholdtanwesen. Ich wünsche Euch viel Glück bei der Suche nach ihm.", description = "Was? Verrat? Nein, nein. Ich versichere Euch, dass meine Absichten in jeder Hinsicht harmlos sind.\n\nIst es denn so falsch, denen helfen zu wollen, die dieses leidvolle Ritual des Umwerbens zu erleichtern wünschen? Kommt schon, das ist doch kein Verbrechen.\n\nIch werde Euch beweisen, dass ich keine schlechten Absichten hege, indem ich Euch meine Quelle verrate.\n\nDie Lieferung wurde mir von einem Staffron Lerent zugestellt, so eine Art Apotheker. Ich habe nie mit ihm gesprochen.\n\nUnser Goblinmittelsmann meinte, dass er im Vorgebirge des Hügellands gearbeitet hätte, irgendwo hinter dem unheimlichen Rabenholdtanwesen. Ich wünsche Euch viel Glück bei der Suche nach ihm.", progress = nil, completion = "Ja, ich habe diese Düfte hergestellt. Sie duften wunderbar, nicht war? Unwiderstehlich.\n\nSobald die Krieger von Allianz und Horde gleichermaßen von Gefühlen der Liebe hingerissen sind, werden sie dem Aufstieg des Schattenrates machtlos gegenüber stehen.\n\nSie werden geschwächt und unvorbereitet sein. Da sie um ihre Liebsten besorgt sind, werden sie die Kontrolle verlieren.\n\nDie Lösung war so einfach. Warum bin ich nicht schon eher darauf gekommen? Die Schwäche aller liegt im Herzen. Es gibt nichts, was Ihr tun könntet, um das Unvermeidbare aufzuhalten.", rewards = nil}
MultiLanguageQuestData['de'][9029] = {title = "Ein blubbernder Kessel", objective = "Ein angenehmer Duft geht von dem Kessel auf.Auf Euch wartet eine dieser Belohnungen:\n\n", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlauer AbendanzugLila AbendanzugRoter AbendanzugReizendes blaues KleidReizendes lila KleidReizendes rotes Kleid"}
MultiLanguageQuestData['de'][9030] = {title = "Anthions Abschiedsworte", objective = "Sprecht mit Deliana in Eisenschmiede.\n\nBereitgestellter Gegenstand: \n", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9032] = {title = "Bodleys trauriges Schicksal", objective = "Reist zum Schwarzfels und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Schwarzfelsspitze zu finden.", description = "Das Amulett enthielt Lord Valthalaks Seele? Dann ist es nicht weiter verwunderlich, dass es mit einem solch machtvollen Fluch belegt war.\n\nBodley aufzufinden, könnte sich allerdings schwierig gestalten. Als ich das letzte Mal von ihm hörte, wollte er in die Schwarzfelsspitze zurückkehren. Seitdem hat niemand jemals wieder etwas von ihm gehört.\n\nSucht ihn in der Schwarzfelsspitze, aber ich befürchte, dass er bereits tot ist. Ich würde Euch empfehlen, den Apparat des Goblins mitzunehmen.", progress = nil, completion = "Ich bin ja so froh, dass Ihr mich sehen könnt. Endlich habe ich jemanden, mit dem ich reden kann!\n\nWerdet Ihr uns helfen, &lt;Name&gt;? Uns dabei helfen, das wiedergutzumachen, was wir verbrochen haben? Sollte es stimmen, dass Ihr bereits das obere Stück von Lord Valthalaks Amulett besitzt, dann kann ich Euch dabei behilflich sein, die anderen Stücke zu finden, sie wieder zusammenzufügen und dieser Angelegenheit ein Ende zu bereiten.\n\nAch ja, mein Name ist Bodley. Schön, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9033] = {title = "Echo des Krieges", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte, dass Ihr 5 lebende Monstrositäten, 5 Steinhautgargoyles, 8 Hauptmänner der Todesritter und 3 Giftpirscher tötet.", description = "Fünf Jahre sind seit dem letzten Krieg vergangen...\n\nZehntausende mussten dabei ihr Leben lassen - und für was? Die Bedrohung wurde niemals gänzlich ausgelöscht.\n\nJetzt verbreitet der Lichkönig erneut Angst und Schrecken... sein getreuer Jünger, Kel'Thuzad, zieht seine Truppen für einen weiteren Angriff auf unser Land zusammen.\n\nWir werden es nicht zulassen! Beweist Euer Engagement. Zeigt, dass Ihr gewillt seid, Leib und Leben zu riskieren, um diesen Wahnsinn aufzuhalten! Die vereinigte Macht der Argentumdämmerung und des Kreuzzugs wird Euch mit allen Mitteln zur Seite stehen.\n\nGeht nach Naxxramas und zerstört die Geißel...", progress = nil, completion = "Ihr habt ausgezeichnete Arbeit geleistet! Ihr werdet mittels der Dienste der Männer und Frauen bei der Kapelle entlohnt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9034] = {title = "Brustplatte des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Brustplatte des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", progress = "Naxxramas ist das Heim uralten Bösens, <Name>.", completion = "Lehrt ihnen noch einmal das Fürchten, &lt;Klasse&gt;. Lasst keine Gnade walten.", rewards = "Ihr bekommt:\n\nBrustplatte des Schreckenspanzers"}
MultiLanguageQuestData['de'][9035] = {title = "Hinterhalt am Straßenrand", objective = "Sprecht mit Lehrling Meledor im Immersangwald entlang der Straße, die südlich von Silbermond wegführt.", description = "He, Ihr da! Ihr müsst mir helfen, bitte!\n\nIch und ein anderer Lehrling wurden von den Getriebenen angegriffen! In ihrem wahnsinnigen Hunger nach Magie haben sie alles mitgenommen, was sie in ihre Hände bekamen: Manakristalle, Zauberstäbe, Zauberbücher... alles!\n\nMeledor ist ihnen nachgejagt, ich musste zurückbleiben und auf die wenigen Dinge aufpassen, die sie nicht gestohlen haben. Geht weiter die Straße entlang und seht nach, ob Ihr ihm behilflich sein könnt.", progress = nil, completion = "Sie sind jetzt weg. Hab' ihnen mit einem gut platzierten Feuerball eine Heidenangst eingejagt! Unglücklicherweise haben sie unsere wertvollen Güter in den Fluss geworfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9036] = {title = "Beinplatten des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinplatten des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinplatten, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", progress = "Denkt an jene, die vor Euch versagt haben, <Name>.", completion = "Zermalmt sie unter Euren Füßen.", rewards = "Ihr bekommt:\n\nBeinplatten des Schreckenspanzers"}
MultiLanguageQuestData['de'][9037] = {title = "Helm des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Helm des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihter Helm, 15 kampfzerschlissene Plattenstücke, 5 Arkanitbarren und 1 Nexuskristall.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm des Schreckenspanzers"}
MultiLanguageQuestData['de'][9038] = {title = "Schulterstücke des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Schulterstücke des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Schulterstücke, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchulterstücke des Schreckenspanzers"}
MultiLanguageQuestData['de'][9039] = {title = "Sabatons des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Sabatons des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Sabatons, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", progress = "Unterschätzt niemals ein gutes Paar Stiefel. Besonders, wenn sie von Korfax angefertigt wurden!", completion = "Ich habe Mograine im letzten Krieg dabei beobachtet, wie er die stinkenden Schädel der lebenden Toten mit genau diesen Stiefel gespalten hat.", rewards = "Ihr bekommt:\n\nSabatons des Schreckenspanzers"}
MultiLanguageQuestData['de'][9040] = {title = "Stulpen des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Stulpen des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Stulpen, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", progress = "Diese Stulpen sind für das Tragen einer edlen Waffe geschaffen.", completion = "Möge sich Euer Griff um den Hals Kel'Thuzads festigen.\n\n&lt;Korfax macht eine reißende Bewegung mit seinen Händen.&gt;", rewards = "Ihr bekommt:\n\nStulpen des Schreckenspanzers"}
MultiLanguageQuestData['de'][9041] = {title = "Taillenschutz des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Taillenschutz des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Taillenschutz, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", progress = "Der Gürtel steht für Modebewusstsein und schützende Ausrüstung zugleich.", completion = "Verwendet ihn als Schlinge für Eure Gegner... und tragt ihn gut sichtbar beim Besuch Eurer Goblindisko. Ihr werdet das Tagesgespräch der Stadt sein!", rewards = "Ihr bekommt:\n\nTaillenschutz des Schreckenspanzers"}
MultiLanguageQuestData['de'][9042] = {title = "Armschienen des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Armschienen des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 1 Nexuskristall.", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", progress = "Die Handgelenke sind die zweitverletzlichste Stelle des Körpers... oder ist es die vierte?", completion = "Denkt daran, die Handgelenke sind die fünftverletzlichste Stelle des Körpers! Schützt Eure Handgelenke und sie werden ganz sicher Eure Ellbogen schützen - vielleicht.", rewards = "Ihr bekommt:\n\nArmschienen des Schreckenspanzers"}
MultiLanguageQuestData['de'][9043] = {title = "Tunika der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTunika der Erlösung"}
MultiLanguageQuestData['de'][9044] = {title = "Beinschützer der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", progress = "Ihr werdet keine Beinschützer finden, die besser zu einem gesegneten Kämpfer passen.", completion = "Diese Beinschützer bewahren das Gleichgewicht zwischen dem Kampf mit der Waffe und mit Magie.", rewards = "Ihr bekommt:\n\nBeinschützer der Erlösung"}
MultiLanguageQuestData['de'][9045] = {title = "Kopfstück der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Kopfstück der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Plattenstücke, 5 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", progress = "<Eligor sieht zu Euch auf und wendet sich dann wieder seinem Gespräch zu.>", completion = "&lt;Eligor zeigt auf seinen Kopf.&gt;\n\nBehaltet Euren Schutz stets auf, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nKopfstück der Erlösung"}
MultiLanguageQuestData['de'][9046] = {title = "Schiftung der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Schiftung der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Schiftung, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 2 Nexuskristalle.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchiftung der Erlösung"}
MultiLanguageQuestData['de'][9047] = {title = "Stiefel der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Stiefel der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Stiefel, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der Erlösung"}
MultiLanguageQuestData['de'][9048] = {title = "Handschützer der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandschützer der Erlösung"}
MultiLanguageQuestData['de'][9049] = {title = "Gurt der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGurt der Erlösung"}
MultiLanguageQuestData['de'][9050] = {title = "Handgelenksschützer der Erlösung", objective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandgelenksschützer der Erlösung"}
MultiLanguageQuestData['de'][9051] = {title = "Giftexperiment", objective = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken und kehrt danach zu Torwa Pfadfinder im Krater von Un'Goro zurück.", description = "Das Gift, das Ihr mir geholfen habt zu entwickeln, ist für einen bestimmten Zweck gedacht. Die mächtigen Teufelssaurier des Kraters erschweren mir die Jagd und das Überleben. Selbst wenn ich über die nötige Stärke verfügen würde, einen Teufelssaurier zu erlegen, würde einfach nur ein anderer sein Territorium beanspruchen.\n\nNehmt diesen vergifteten Widerhaken und stecht ihn tief in einen lebenden Teufelssaurier. Das Gift sollte ihn ruhigstellen, aber ich bin mir nicht sicher, wie lange es dauern wird, bis es wirkt...", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Ihr seid tapfer und weise.\n\nSagt mir, wie hat der Teufelssaurier auf das Gift reagiert?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9052] = {title = "Blutblütengift", objective = "Sammelt 8 Blutkappenpilze und 8 Gorishistachel und kehrt zu Torwa Pfadfinder im Krater von Un'Goro zurück.", description = "Ich würde Euch darum bitten, mir dabei behilflich zu sein, ein spezielles Gift zu entwickeln, um eine der mächtigsten Kreaturen des Kraters ruhigzustellen. Es ist nicht tödlich und nur <ein/eine:c> <Klasse> mit scharfen Augen kann die nötigen Zutaten dafür erspähen.\n\nDie Blutkappenpilze wachsen in den Blutblütensprösslingen, die überall im Krater anzufinden sind. Gorishistachel könnt Ihr von den Insekten erhalten, die in der und um die Wuchernde Narbe herum heimisch sind. Sie befindet sich im südlichen Teil des Kraters.", progress = "Hattet Ihr Erfolg?", completion = "Endlich habe ich die nötigen Zutaten!\n\nZusammen mit der Un'Goro-Erde, die ich schon selbst gesammelt habe, sollte sich das Gift nun einfach herstellen lassen...", rewards = "Ihr bekommt:\n\nErheblicher Heiltrank"}
MultiLanguageQuestData['de'][9053] = {title = "Eine bessere Zutat", objective = "Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des Versunkenen Tempels und kehrt zu Torwa Pfadfinder zurück.", description = "Genau wie ich befürchtet hatte - das Gift ist einfach zu schwach für eine solch mächtige Kreatur.\n\nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal'Hakkar begeben müssen. Enträtselt dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Habt Ihr die Fäulnisranke?", completion = "Endlich werde ich ein wirksames Gift herstellen können. Ich will es Euch nicht erneut auferlegen, die Kreatur damit zu vergiften, da ich schon zu tief in Eurer Schuld stehe.\n\nSeid Euch meines Danks und meines Respekts gewiss. Mögen Eure Reisen immer gut verlaufen, &lt;Name&gt;.", rewards = "Umarmung des WaldesErgrauter PelzMondschattenstockMondschattenstabUmarmung des DickichtsErgraute HautIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9054] = {title = "Tunika des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTunika des Gruftpirschers"}
MultiLanguageQuestData['de'][9055] = {title = "Beinschützer des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeinschützer des Gruftpirschers"}
MultiLanguageQuestData['de'][9056] = {title = "Kopfstück des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Kopfstück des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", description = "Ich habe eine Verwendung für den Panzer des Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, <Klasse>?", completion = "Ihr verwandelt Euch in eine furchterregende Kreatur, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nKopfstück des Gruftpirschers"}
MultiLanguageQuestData['de'][9057] = {title = "Schiftung des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Schiftung des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Schiftung, 12 kampfzerschlissene Kettenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchiftung des Gruftpirschers"}
MultiLanguageQuestData['de'][9058] = {title = "Stiefel des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Stiefel des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Stiefel, 12 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel des Gruftpirschers"}
MultiLanguageQuestData['de'][9059] = {title = "Handschützer des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandschützer des Gruftpirschers"}
MultiLanguageQuestData['de'][9060] = {title = "Gurt des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, <Klasse>?", completion = "Ein Gurt, der eines Königs würdig wäre! Angefertigt für Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGurt des Gruftpirschers"}
MultiLanguageQuestData['de'][9061] = {title = "Handgelenksschützer des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, <Klasse>?", completion = "Der Handgelenksschutz ist fertig. Viel Spaß damit!", rewards = "Ihr bekommt:\n\nHandgelenksschützer des Gruftpirschers"}
MultiLanguageQuestData['de'][9062] = {title = "Aufgeweichte Seiten", objective = "Lehrling Meledor im Immersangwald möchte, dass Ihr im Gewässer unterhalb der nahegelegenen Brücke sucht und ihm Antheols Foliant der Elementarmagie bringt.", description = "Diese verdammten Getriebenen können recht schnell rennen, wenn sich ihnen einer entgegenstellt. Nun, das soll uns nun erstmal egal sein. Ich muss den Foliant der Elementarmagie meines Instrukteurs finden.\n\nIch bin mir ganz sicher, dass ich gesehen habe, wie ihn einer dieser Feiglinge in den Fluss geworfen hat, aber ich kann ihn einfach nicht ausfindig machen. Ich könnte noch ein Paar Augen gebrauchen. Solltet Ihr ihn finden, lasse ich auch ein paar Münzen springen.", progress = "Kein Glück? Na dann, sucht weiter. Das Buch ist überaus wichtig, <Klasse>.", completion = "Das Buch ist völlig aufgeweicht. Instrukteur Antheol wird alles andere als erfreut sein.\n\nHier, nehmt das Geld. Ich habe eine Idee.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9063] = {title = "Torwa Pfadfinder", objective = "Sprecht im Krater von Un'Goro mit Torwa Pfadfinder.", description = "Ein Jäger namens Torwa Pfadfinder hat die Hilfe eines Druiden angefordert. Er sagte, dass nur einer von uns über den nötigen Respekt für die Natur und die Fähigkeiten verfügen würde, um ihm zu helfen.\n\nEs gibt einen Pfad, der den Krater von Un'Goro und die Tanariswüste verbindet. Ihr werdet Torwa nahe dem Punkt finden, an dem der Pfad in den Krater hineinführt.", progress = nil, completion = "Ihr seid weit gereist, um mich zu treffen, &lt;Klasse&gt;, und Ihr kommt genau zur rechten Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9064] = {title = "Die Sache ausbaden", objective = "Bringt Antheols Foliant der Elementarmagie zu Instrukteur Antheol beim Stillwispertümpel im Immersangwald.", description = "Antheol wird aus der Haut fahren, wenn er erfährt, dass sein Buch ruiniert ist. Ich würde Euch gerne etwas vorschlagen; keine Sorge, es wird die Mühe wert sein.\n\nBringt ihm das Buch und erzählt ihm nichts über den Vorfall. Sollte er Euch fragen, so sagt ihm einfach, dass Ihr das Buch in eine Pfütze habt fallenlassen. Ihr seid kein direkter Untergebener von ihm, also kann er nicht viel ausrichten.\n\nAntheol hält seine Vorlesungen beim Stillwispertümpel, südöstlich von Silbermond. Ihr werdet uns diesen Gefallen doch tun, oder? Ich werde Euch auch reichlich dafür belohnen!", progress = "Warum unterbrecht Ihr meine Vorlesung, <Klasse>?", completion = "Ihr sagt, dass Euch diese zwei unfähigen Narren bestochen haben, damit Ihr mich anlügt? Es war richtig von Euch, zu mir zu kommen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9065] = {title = "Pattymack-Spezial", objective = "Stell sicher, dass du den Turm zerstörst!", description = "He du, reiß diesen Turm nieder!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nErfrischendes QuellwasserSchwacher Heiltrank"}
MultiLanguageQuestData['de'][9066] = {title = "Disziplin muss sein", objective = "Wendet Antheols Disziplinarsstab bei seinen zwei Schülern an: Lehrling Ralen und Lehrling Meledor. Kehrt anschließend mit dem Stab zu Antheol beim Stillwispertümpel im Immersangwald zurück.", description = "Ich hoffe, dass Ihr heute eine wichtige Lektion gelernt habt, <Name>. Vertraut niemandem, der für Euch lügen soll.\n\nIch möchte, dass Ihr jetzt zu meinen zwei dusseligen Schülern geht und sie mit diesem Stab angemessen bestraft. Meine Magie verrät mir, dass Ihr sie an der Straße gen Westen auf der anderen Seite der Todesschneise finden werdet.\n\nKommt anschließend zu mir zurück. Ich werde Euch eine kleine Belohnung für Eure Mühe geben.", progress = "Habt Ihr meine Anweisungen befolgt, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Keine Sorge, sie werden nicht auf Dauer in dieser Gestalt ausharren müssen. Allerdings geht es mit ihrer Lehre erst dann weiter, wenn sie es sich verdient haben.", rewards = "Ihr bekommt:\n\nBeutel des Magisters"}
MultiLanguageQuestData['de'][9067] = {title = "Die Feier ist nie zu Ende", objective = "Besorgt eine Flasche Bester Sonnentropfen, Bachtatzenhäppchen und ein Feuerwerksbündel und bringt alles zu Lord Saltheril in Saltherils Hafen im Immersangwald.", description = "Ich liebe es Feste zu feiern... mein bescheidener Beitrag, die Herrlichkeit von Quel'Thalas zu würdigen!\n\nAllerdings befinde ich mich in einer misslichen Lage... ich brauche Euch, um mir mehr Festvorräte zu besorgen.\n\nBringt mir eine Flasche Bester Sonnentropfen von Kellermeister Sonnentropfen in Silbermond und köstliche Bachtatzenhäppchen von Zalene Morgenlicht bei der Zuflucht der Weltenwanderer. Und wenn Ihr schon einmal dabei seid, könnt Ihr auch gleich meine Feuerwerkslieferung bei Halis Morgenwandler im Dörfchen Morgenluft abholen.\n\nBeeilt Euch!", progress = "Habe ich Euch nicht gerade losgeschickt, um mehr Festvorräte zu beschaffen? Oh, also man kann wirklich nicht von mir erwarten, dass ich mich an jedes Gesicht erinnere, nicht wahr? Ich treffe so viele... interessante Leute.\n\nWas ist Euer Anliegen?", completion = "Ihr seid in der Tat ein aufgeweckter junger Mann, nicht wahr?\n\nDiese Waren erscheinen mir dem Zwecke angemessen. Für Eure Mühen habt Ihr Euch eine angemessene Entschädigung verdient und vielleicht ein kleines Trinkgeld.\n\nOh, das hätte ich beinahe vergessen! Hier ist eine Einladung zu meinem Fest. Und, &lt;Klasse&gt;, wenn Ihr das nächste Mal mein Anwesen betretet, stellt sicher, dass Ihr ein wenig, sagen wir... festlicher gekleidet seid.", rewards = "Ihr bekommt:\n\nEinladung zu Saltherils Hafenfeier"}
MultiLanguageQuestData['de'][9068] = {title = "Tunika des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTunika des Erdspalters"}
MultiLanguageQuestData['de'][9069] = {title = "Beinschützer des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeinschützer des Erdspalters"}
MultiLanguageQuestData['de'][9070] = {title = "Kopfstück des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Kopfstück des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKopfstück des Erdspalters"}
