MultiLanguageQuestData['de'][9073] = {title = "Handschützer des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandschützer des Erdspalters"}
MultiLanguageQuestData['de'][9074] = {title = "Gurt des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGurt des Erdspalters"}
MultiLanguageQuestData['de'][9075] = {title = "Handgelenksschützer des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandgelenksschützer des Erdspalters"}
MultiLanguageQuestData['de'][9076] = {title = "Getriebener Rädelsführer", objective = "Bringt Aldarons Kopf zu Velendris Weißflor nahe des Ankerplatzes der Sonnensegel im Immersangwald.", description = "Die Getriebenen sind so auf den Verzehr von fauler Magie konzentriert, sie haben nicht einmal gemerkt, dass wir den Großteil unserer Waffen wieder an uns gebracht haben. Wir können uns allerdings nicht auf ihren Zustand der Benommenheit verlassen. Es ist an der Zeit für einen ausschlaggebenden Angriff. Lasst uns anhand ihres Anführers Aldaron ein Exempel statuieren. Er wurde im obersten Teil des Gebäudes beim Ankerplatz gesichtet. Bringt mir seinen Kopf, ich werde Euch entsprechend entlohnen.", progress = "Nun, habt Ihr seinen Kopf? Verschwendet nicht meine Zeit, <Name>.", completion = "Ihr habt ihn also doch noch bezwungen! Meine Männer hatten ihn natürlich schon geschwächt.\n\nDas war ein Scherz, &lt;Klasse&gt;. Ihr habt Euch gut geschlagen. Wenn Ihr weiterhin eine weiße Weste behaltet, werdet Ihr Euch noch einen Namen machen.", rewards = "Armschienen der SonnensegelBindungen des KüstenfischersSeidengelenkbänderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9077] = {title = "Brustplatte der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Brustplatte der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Lederstücke, 2 Arkanitbarren und 6 geschmeidige unverwüstliche Bälge.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrustplatte der Knochensense"}
MultiLanguageQuestData['de'][9078] = {title = "Beinplatten der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinplatten der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinplatten, 20 kampfzerschlissene Lederstücke, 1 Arkanitbarren, 8 geschmeidige unverwüstliche Bälge und 100 Goldstücke.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeinplatten der Knochensense"}
MultiLanguageQuestData['de'][9079] = {title = "Helm der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Helm der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Helm, 15 kampfzerschlissene Lederstücke, 8 geschmeidige unverwüstliche Bälge. 1 Nexuskristall und 75 Goldstücke.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm der Knochensense"}
MultiLanguageQuestData['de'][9080] = {title = "Schulterstücke der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Schulterstücke der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Schulterstücke, 12 kampfzerschlissene Lederstücke, 5 geschmeidige unverwüstliche Bälge, 1 Nexuskristall und 50 Goldstücke.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchulterstücke der Knochensense"}
MultiLanguageQuestData['de'][9081] = {title = "Sabatons der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Sabatons der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Sabatons, 12 kampfzerschlissene Lederstücke, 3 geschmeidige unverwüstliche Bälge, 2 Nexuskristalle und 25 Goldstücke.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSabatons der Knochensense"}
MultiLanguageQuestData['de'][9082] = {title = "Stulpen der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Stulpen der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Stulpen, 8 kampfzerschlissene Lederstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStulpen der Knochensense"}
MultiLanguageQuestData['de'][9083] = {title = "Taillenschutz der Knochensense", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Taillenschutz der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Taillenschutz, 8 kampfzerschlissene Lederstücke, 5 geschmeidige unverwüstliche Bälge, 1 Nexuskristall und 15 Goldstücke.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTaillenschutz der Knochensense"}
MultiLanguageQuestData['de'][9084] = {title = "Armschienen der Knochensense", objective = "Rohan der Assassine bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Armschienen der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Lederstücke, 1 Arkanitbarren, 2 geschmeidige unverwüstliche Bälge und 10 Goldstücke.", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.", progress = "Wie soll ich, ohne die von mir benötigten Gegenstände, Eurer Meinung nach irgendetwas zu Stande bekommen?", completion = "Die Armschienen sind fertig, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nArmschienen der Knochensense"}
MultiLanguageQuestData['de'][9085] = {title = "Schatten der Verdammnis", objective = "Geht zu einem Beschwörungskreis und tötet einen Schatten der Verdammnis. Kehrt dann zu Kommandant Thomas Helleran bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern zurück.", description = "Nachdem Ihr die Verteidigung der Beschwörungskreise der Geißel ausgeschaltet habt, müsst Ihr den Akolythen, die sie beschützen, gegenübertreten.\n\nIn Wirklichkeit handelt es sich hier keineswegs um richtige Wesen, sondern um Schatten, die zu den beängstigendsten Kreaturen des Lichkönigs zählen. Sie können mithilfe der nekrotischen Runen, die sie bei sich tragen, Gestalt annehmen und dann mit Magie oder dem Einsatz von Waffen zerstört werden.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Sind die Schatten erstmal zerstört, können wir wieder darauf hoffen, den Lichkönig zu besiegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"}
MultiLanguageQuestData['de'][9086] = {title = "Tunika des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Lederstücke, 6 geschmeidige unverwüstliche Bälge und 2 Nexuskristalle.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTunika des Traumwandlers"}
MultiLanguageQuestData['de'][9087] = {title = "Beinschützer des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Lederstücke, 8 geschmeidige unverwüstliche Bälge und 1 Nexuskristall.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeinschützer des Traumwandlers"}
MultiLanguageQuestData['de'][9088] = {title = "Kopfstück des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Kopfstück des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Lederstücke, 6 geschmeidige unverwüstliche Bälge und 2 Nexuskristalle.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKopfstück des Traumwandlers"}
MultiLanguageQuestData['de'][9089] = {title = "Schiftung des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Schiftung des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Schiftung, 12 kampfzerschlissene Lederstücke, 5 geschmeidige unverwüstliche Bälge und 1 Nexuskristall.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchiftung des Traumwandlers"}
