MultiLanguageQuestData['de'][9091] = {title = "Handschützer des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Lederstücke, 5 geschmeidige unverwüstliche Bälge und 1 Nexuskristall.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandschützer des Traumwandlers"}
MultiLanguageQuestData['de'][9092] = {title = "Gurt des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Lederstücke, 3 Einheiten Mondstoff und 2 geschmeidige unverwüstliche Bälge.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGurt des Traumwandlers"}
MultiLanguageQuestData['de'][9093] = {title = "Handgelenksschützer des Traumwandlers", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Lederstücke, 1 Arkankristall und 2 geschmeidige unverwüstliche Bälge.", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandgelenksschützer des Traumwandlers"}
MultiLanguageQuestData['de'][9094] = {title = "Handschuhe der Argentumdämmerung", objective = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", description = nil, progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen.", rewards = "Stulpen des UntotenschlachtensHandlappen des UntotenschlachtensHandschützer des UntotenschlachtensHandschuhe der Untotenbekämpfung"}
MultiLanguageQuestData['de'][9095] = {title = "Frostfeuerrobe", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Frostfeuerrobe anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für mich die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.", progress = "Mit den erforderlichen Materialien und Reagenzien bin ich in der Lage, die mythische Frostfeuerrüstung wieder herzustellen.", completion = "Vergesst nicht, dass unkontrollierte Macht genauso zerstörerisch wie ungenutzte Macht ist, &lt;Klasse&gt;. Lasst Vorsicht walten, wenn Ihr Frostfeuer tragt.", rewards = "Ihr bekommt:\n\nFrostfeuerrobe"}
MultiLanguageQuestData['de'][9096] = {title = "Frostfeuergamaschen", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuergamaschen anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Gamaschen, 20 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für mich die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.", progress = "Mit den erforderlichen Materialien und Reagenzien bin ich in der Lage, die mythische Frostfeuerrüstung wieder herzustellen.", completion = "Vergesst nicht, dass unkontrollierte Macht genauso zerstörerisch wie ungenutzte Macht ist, &lt;Klasse&gt;. Lasst Vorsicht walten, wenn Ihr Frostfeuer tragt.", rewards = "Ihr bekommt:\n\nFrostfeuergamaschen"}
MultiLanguageQuestData['de'][9097] = {title = "Frostfeuerreif", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Frostfeuerreif anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihten Reif, 15 kampfzerschlissene Stoffstücke, 3 Einheiten Mondstoff und 3 Nexuskristalle.", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für mich die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.", progress = "Mit den erforderlichen Materialien und Reagenzien bin ich in der Lage, die mythische Frostfeuerrüstung wieder herzustellen.", completion = "Vergesst nicht, dass unkontrollierte Macht genauso zerstörerisch wie ungenutzte Macht ist, &lt;Klasse&gt;. Lasst Vorsicht walten, wenn Ihr Frostfeuer tragt.", rewards = "Ihr bekommt:\n\nFrostfeuerreif"}
MultiLanguageQuestData['de'][9098] = {title = "Frostfeuerschulterpolster", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuerschulterpolster anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Schulterpolster, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für mich die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFrostfeuerschulterpolster"}
