MultiLanguageQuestData['de'][9113] = {title = "Reif des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Reif des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Reif, 15 kampfzerschlissene Stoffstücke, 3 Einheiten Mondstoff und 3 Nexuskristalle.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nReif des Glaubens"}
MultiLanguageQuestData['de'][9114] = {title = "Schulterpolster des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Schulterpolster des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Schulterpolster, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nSchulterpolster des Glaubens"}
MultiLanguageQuestData['de'][9115] = {title = "Sandalen des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Sandalen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Sandalen, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nSandalen des Glaubens"}
MultiLanguageQuestData['de'][9116] = {title = "Handschuhe des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschuhe des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschuhe, 8 kampfzerschlissene Stoffstücke und 4 Einheiten Mondstoff.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nHandschuhe des Glaubens"}
MultiLanguageQuestData['de'][9117] = {title = "Gürtel des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gürtel des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gürtel, 8 kampfzerschlissene Stoffstücke, 2 Arkankristalle und 2 Einheiten Mondstoff.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGürtel des Glaubens"}
MultiLanguageQuestData['de'][9118] = {title = "Bindungen des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Bindungen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nBindungen des Glaubens"}
MultiLanguageQuestData['de'][9119] = {title = "Zwischenfall beim Sanktum des Westens", objective = "Sprecht mit Leybewahrerin Velania beim Sanktum des Westens im Immersangwald.", description = "Da Ihr schon mal hier seid, <Name>, habe ich eine Bitte an Euch. Leybewahrerin Velanias Lehrling kam vorhin vorbei und bat um Unterstützung. Beim Sanktum des Westens kam es offenbar zu einem Zwischenfall. Ich bin gerade zu sehr mit der... Unterhaltung... unserer Zwergengäste beschäftigt. Vielleicht könnt Ihr ja aushelfen. Ihr findet das Sanktum des Westens südwestlich von hier.", progress = nil, completion = "Seht Euch um. Hier stimmt so einiges nicht.\n\nBeim Sanktum des Westens kam es zu einem schweren Zwischenfall. Lasst uns alles Erdenkliche tun, um Schlimmeres zu verhindern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9120] = {title = "Der Niedergang Kel'Thuzads", objective = "Bringt Kel'Thuzads Phylakterium zu der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des Hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", progress = "HEILIGES LICHT! Was ist denn in Euch gefahren, Junge?", completion = "Ich hätte mir nie erträumt, dass ich das eines Tages mal zu Gesicht bekommen sollte...\n\n&lt;Vater Montoy scheint lüstern zu geifern.&gt;\n\nOh ja, Ihr sollt entlohnt werden, mein Junge. Reichlich entlohnt. Gebt es mir. Jetzt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal des HeldenMal des Helden\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9121] = {title = "Die Zitadelle des Schreckens - Naxxramas", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 Arkankristalle, 2 Nexuskristalle, 1 rechtschaffene Kugel und 60 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem wohlwollend sein.", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von arkaner Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Da es an Eurer Hingabe für die Ziele der Argentumdämmerung noch etwas mangelt, <Name>, wird der Preis hoch sein. Es steht Euch frei, abzulehnen und noch einmal für einen günstigeren Preis wiederzukehren, sobald Euer Ruf respektvoll oder ehrfürchtig ist.", progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, &lt;Name&gt;. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Tarnung"}
MultiLanguageQuestData['de'][9122] = {title = "Die Zitadelle des Schreckens - Naxxramas", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 2 Arkankristalle, 1 Nexuskristall und 30 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem respektvoll sein.", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung bewundernswert ist, sind wir gewillt, einige dieser Kosten für Euch zu übernehmen.", progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, &lt;Name&gt;. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Tarnung"}
MultiLanguageQuestData['de'][9123] = {title = "Die Zitadelle des Schreckens - Naxxramas", objective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.", progress = nil, completion = "Ihr werdet ein leichtes Prickeln verspüren, &lt;Name&gt;. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", rewards = nil}
MultiLanguageQuestData['de'][9124] = {title = "Was man für Gruftpirscherrüstung braucht...", objective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Teile einer Gruftbestie.", description = "Würdet Ihr Euch gerne eine dieser glänzenden Münzen verdienen?\n\n<Leopold hält ein Insigne des Kreuzzugs in die Höhe.>\n\nIch habe ein kleines Problem, bei dem Ihr mir vielleicht behilflich sein könntet, <Name>. Seht Ihr, ich fertige Gruftpirscherrüstung für diejenigen an, die dämlich genug sind, um sich nach Naxxramas zu wagen. Zwar versorgen sie mich mit den wichtigsten Bestandteilen für die Rüstung versorgen, mir gehen aber ständig die Teile von Gruftbestien aus. Bringt mir einen Schwung dieser Teile und ich werde Euch dafür mit einem Insigne bezahlen - einlösbar bei dem Rüstmeister.", progress = "Wie geht es mit der Jagd voran?", completion = "Ah, die werden sich gut eignen, &lt;Name&gt;. Vergesst nicht, ich nehme jederzeit noch mehr Teile entgegen. Für jede Ladung, die Ihr mir bringt, belohne ich Euch mit einem Insigne.", rewards = "Ihr bekommt:\n\nInsigne des Kreuzzugs"}
MultiLanguageQuestData['de'][9125] = {title = "Teile einer Gruftbestie", objective = "Ihr habt mit dem ersten Schwung vorbildliche Arbeit geleistet, <Name>. Solltet Ihr noch mehr Teile haben, nehme ich sie Euch jetzt ab. Für jede abgelieferte Ladung werde ich Euch mit einer Insignie belohnen.", description = nil, progress = "Ihr habt mit dem ersten Schwung vorbildliche Arbeit geleistet, <Name>. Solltet Ihr noch mehr Teile haben, nehme ich sie Euch jetzt ab. Für jede abgelieferte Ladung werde ich Euch mit einer Insignie belohnen.", completion = "Ausgezeichnet, &lt;Name&gt;! Hierfür wird man mit Sicherheit gute Verwendung finden.", rewards = "Ihr bekommt:\n\nInsigne des Kreuzzugs"}
MultiLanguageQuestData['de'][9126] = {title = "Knochensensenjagd", objective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Knochenfragmente.", description = "Don Julios Muster für die Rüstung der Knochensense benötigt Knochenfragmente - ein Menge Knochenfragmente. Diejenigen, die verrückt genug sind, um sich nach Naxxramas zu wagen, versorgen mich bereits mit den wichtigsten Bestandteilen für die Rüstung. Allerdings halte ich stets nach weiteren Knochenfragmenten Ausschau.\n\nWas denkt Ihr? Würdet Ihr Euch gerne die Hände schmutzig machen und dabei ein paar Anhänger der Geißel vernichten? Hierbei kommt jeder gut davon.", progress = "Ich kann Euch die Richtung zu Orten weisen, die von Skeletten heimgesucht werden, <Klasse>.", completion = "Ihr seid schnell, &lt;Name&gt;. Schnell wie der Wind... Sagt mal, habe ich Euch schon von meiner Zeit in dem Barbershop-Quartett erzählt?\n\nErinnert mich das nächste Mal daran, Euch davon zu berichten.", rewards = "Ihr bekommt:\n\nInsigne des Kreuzzugs"}
MultiLanguageQuestData['de'][9127] = {title = "Knochenfragmente", objective = "Ein Mann meines Berufsstandes kann niemals zu viele Knochenfragmente besitzen, <Name>. Kommt zu mir, wann immer Ihr einen Überschuss an Fragmenten habt, ich tausche sie dann gegen eine weitere Insignie ein.", description = nil, progress = "Ein Mann meines Berufsstandes kann niemals zu viele Knochenfragmente besitzen, <Name>. Kommt zu mir, wann immer Ihr einen Überschuss an Fragmenten habt, ich tausche sie dann gegen eine weitere Insignie ein.", completion = "Mein Traum von einer Karriere als professioneller Tänzer in der Disko von Gadgetzan wird sich schon bald verwirklichen! Gute Arbeit, weiter so, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nInsigne des Kreuzzugs"}
MultiLanguageQuestData['de'][9128] = {title = "Die Elementargleichung", objective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Kerne der Elemente.", description = "Seid gegrüßt, Abenteurer! Hättet Ihr Interesse an Arbeit? Wer für mich arbeitet, wird mit Insignien bezahlt. Diese Insignien können beim Rüstmeister für mächtige Gegenstände eingetauscht werden.\n\nEure Aufgabe besteht darin, mir so viele Kerne der Elemente zu bringen, wie Ihr tragen könnt. Je mehr, umso besser!\n\nIhr findet sie bei Elementaren verschiedenster Form und Größe, wie es sie überall in unserer Welt gibt.", progress = "Ich kann Euch lediglich die Richtung weisen, <Name>.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Hier, wie versprochen Euer Insigne. Vergesst nicht, wo das hier herkommt, gibt es noch mehr...", rewards = "Ihr bekommt:\n\nInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9129] = {title = "Kern der Elemente", objective = "Glaubt mir, ich verwende diese Kerne zum Anfertigen von Frostfeuerrüstungen. Es ist die Rüstung, die von Magiern getragen wird, die in Naxxramas kämpfen. Ohne Euch und Euresgleichen, würden wir diesen Krieg höchstwahrscheinlich verlieren.\n\nBringt Ihr mir auch weiterhin mehr Kerne, so werde ich Euch dafür wieder mit Insignien entlohnen.", description = nil, progress = "Glaubt mir, ich verwende diese Kerne zum Anfertigen von Frostfeuerrüstungen. Es ist die Rüstung, die von Magiern getragen wird, die in Naxxramas kämpfen. Ohne Euch und Euresgleichen, würden wir diesen Krieg höchstwahrscheinlich verlieren.\n\nBringt Ihr mir auch weiterhin mehr Kerne, so werde ich Euch dafür wieder mit Insignien entlohnen.", completion = "Ihr erweist uns einen großen Dienst, &lt;Name&gt;. Gut gemacht!", rewards = "Ihr bekommt:\n\nInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9130] = {title = "Waren von Silbermond", objective = "Bringt Sathiels Frachtbrief zu Himmelsmeister Morgenhell in Morgenluft.", description = "Ah, <ein Freiwilliger/eine Freiwillige>! Uns gehen hier langsam die Vorräte aus, aber Silbermond hat uns Unterstützung in Form von Hilfsgütern zugesichert. Hier kommt Ihr ins Spiel.\n\nBringt diesen Frachtbrief zu Himmelsmeister Morgenhell. Er wird Euch weiter Auskunft darüber geben, wie Ihr am besten nach Silbermond gelangt.", progress = "Ja, was gibt's?", completion = "Sathiel möchte, dass Ihr nach Silbermond geht und ihre Waren zurückbringt, was? Kein Problem, ich kann Euch schnell dorthin bringen... gegen eine kleine Gebühr, versteht sich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9131] = {title = "Bindung des Schreckenspanzers", objective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Dunkeleisenfragmente.", description = "Habt Ihr jemals Schreckenspanzerrüstung zu Gesicht bekommen, <Klasse>? Nein, natürlich nicht. Ihr seid immer noch ein <Junge/Mädchen> – ein Dreikäsehoch eben. Ich muss Euch sagen, es ist herrlich.\n\nIhr fragt Euch wahrscheinlich, was all das mit Euch zu tun haben soll, richtig? Hört gut zu, <Anfänger/Anfängerin>: Ich brauche Dunkeleisenfragmente und bin bereit zu zahlen, um an so viele Stücke wie möglich zu kommen.\n\nIch benötige die Fragmente für das Zusammensetzen der Schreckenspanzer für unsere Helden. Bringt mir Fragmente, dann werdet Ihr bezahlt.", progress = "<Korfax faucht Euch an.>\n\nWas wollt Ihr? Eine Wegbeschreibung? Wenn es weiter nichts ist...", completion = "Das sollte genügen, zumindest vorläufig. Solltet Ihr mehr haben... Ihr wisst, wo Ihr mich finden könnt.", rewards = "Ihr bekommt:\n\nInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9132] = {title = "Dunkeleisenfragmente", objective = "Ich gebe Euch für jede Ladung Dunkeleisenfragmente ein Insigne - je mehr, umso besser. Geht mir jetzt aus den Augen, bevor ich Euch noch zweiteile!", description = nil, progress = "Ich gebe Euch für jede Ladung Dunkeleisenfragmente ein Insigne - je mehr, umso besser. Geht mir jetzt aus den Augen, bevor ich Euch noch zweiteile!", completion = "Das ist alles, was Ihr mir gebracht habt? Vielleicht habt Ihr mich das erste Mal ja nicht richtig verstanden. Ich brauche MEHR!", rewards = "Ihr bekommt:\n\nInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9133] = {title = "Fliegt nach Silbermond", objective = "Erwerbt einen Flug nach Silbermond und bringt Sathiels Frachtbrief zu Sathren Morgenblau in Silbermond.", description = "<Klasse>, ich könnte Euch für eine ganz geringe Summe auf dem Rücken einer dieser herrlichen Kreaturen rasch durch die Lüfte fliegend an Euer Ziel bringen lassen. Es ist auch viel sicherer, als wenn Ihr zu Fuß gehen würdet, das könnt Ihr mir glauben!\n\nSucht Sathren Morgenblau auf, sobald Ihr in Silbermond angekommen seid.\n\nWendet Euch wieder an mich, wenn Ihr bereit sein solltet, durch die Lüfte zu reisen.", progress = "Das ist eine ganz schön lange Liste, die Ihr da habt, mein Freund. Lasst mich mal sehen.", completion = "Was soll das? Sie möchte all das!?\n\nHabt Ihr wenigstens jemanden bei Euch, der Euch beim Rücktransport behilflich ist?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9134] = {title = "Himmelsmeisterin Abendlicht", objective = "Bringt Sathiels Waren zu Himmelsmeisterin Abendlicht am Hirtentor direkt außerhalb von Silbermond.", description = "Naja, sieht nicht so aus, als hättet Ihr einen Karren oder ein Lasttier dabei, also gebe ich Euch besser nur das, was Ihr auch wirklich tragen könnt. Wenn Ihr bereits mit Himmelsmeister Morgenhell in Morgenluft gesprochen habt, dann solltet Ihr das hier so schnell wie möglich zu Sathiel bringen, indem Ihr dorthin zurückfliegt.\n\nBringt Himmelsmeisterin Abendlicht diese Waren zur Endkontrolle. Ihr findet sie am Hirtentor direkt außerhalb von Silbermond.", progress = "Wow, dieses Warenpaket sieht aber mächtig schwer aus! Möchtet Ihr all das auf eins meiner Prachtstücke laden?", completion = "Zurück nach Morgenluft in den Immersangwald, ja? Alles klar, ich kann Euch schnell an Euer Ziel bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9135] = {title = "Zurück zu Sathiel", objective = "Erwerbt einen Flug zurück nach Morgenluft im Immersangwald und liefert Sathiels Waren bei Sathiel ab.", description = "Sieht aus, als ob alles klar geht.\n\nSo, die Frage ist, habt Ihr schon mit meinem Kollegen, Himmelsmeister Morgenglanz, gesprochen? Wenn ja, dann zahlt Ihr ganz einfach die kleine Gebühr und fliegt rasch zurück.\n\nLasst mich wissen, wenn Ihr bereit seid.", progress = "<Klasse>, schon zurück? Das kann aber unmöglich alles sein, was auf der Liste stand!", completion = "Hmmm, wenn er gesagt hat, dass der Rest schnell über den Landweg nachgeliefert wird, dann will ich ihn mal beim Wort nehmen. In der kurzen Zeit, in der wir zusammen gearbeitet haben, hat er es noch immer geschafft, die Waren pünktlich zu liefern.\n\nIch danke Euch, &lt;Name&gt;. Hier, nehmt diese Münzen... sie haben schon den ganzen Tag in meiner Tasche geklimpert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9136] = {title = "Wildpflanzen", objective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Wildwedel.", description = "Ich fertige für die mutigen Helden, die sich nach Naxxramas begeben, eine spezielle Rüstung an - die Rüstung des Traumwandlers. Sie versorgen mich zwar schon mit den meisten Materialien, die ich dafür benötige, aber ich halte dennoch nach jenen Ausschau, die in der Lage sind, mir Wildwedel aus dem Pflanzenreich unserer Welt zu besorgen.\n\nIhr denkt vielleicht, dass diese Aufgabe unter Eurer Würde ist, aber ohne diese Wedel kann die Rüstung nun mal nicht hergestellt werden.\n\nIch bin außerdem in der einzigartigen Lage, Euch mit einem Insigne Eurer Wahl zu bezahlen, da mich die Argentumdämmerung und der Kreuzzug mit den entsprechenden Mitteln unterstützen.", progress = "Ich bin mit dem Pflanzenreich unserer Welt sehr vertraut. Braucht Ihr Richtungsangaben?", completion = "Ich bin Euch sehr verbunden, &lt;Name&gt;.\n\n\n\nBitte denkt daran, dass ich jederzeit Wedel entgegennehme.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9137] = {title = "Wildwedel", objective = "Für jeden Bündel Wildwedel, den Ihr bei mir abliefert, werde ich Euch mit einer von Euch gewählten Insignie, die der Dämmerung oder die des Kreuzzugs, bezahlen.\n\nDie Insignien können beim Rüstmeister für vielerlei Belohnungen eingetauscht werden.", description = nil, progress = "Für jeden Bündel Wildwedel, den Ihr bei mir abliefert, werde ich Euch mit einer von Euch gewählten Insignie, die der Dämmerung oder die des Kreuzzugs, bezahlen.\n\nDie Insignien können beim Rüstmeister für vielerlei Belohnungen eingetauscht werden.", completion = "Danke, &lt;Name&gt;. Eure Arbeit ist für den Erfolg unseres Feldzugs gegen die Geißel unerlässlich.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne der DämmerungInsigne des Kreuzzugs\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9138] = {title = "Sonnenkuppe", objective = "Tötet 10 nerubische Wachen und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", description = "Wir sind hier eingekesselt, <Klasse>! Die anderen Dörfer wurden alle von der Geißel überrannt!\n\nIhr müsst umgehend nach Nordosten, in das Dorf Sonnenkuppe reisen und Euch dort den nerubischen Truppen der Geißel stellen. Es ist unmöglich sie zu verfehlen - sie sehen aus wie riesige Spinnen.\n\nWir dürfen keine Zeit verlieren! Quel'Thalas muss zurückerobert werden!", progress = nil, completion = "Hervorragend! Aber es muss noch mehr getan werden, bevor die Geißel vollständig von Quel'Thalas vertrieben ist!\n\nHier, diese Münzen sind für Euch... Es ist zwar nicht viel, aber Ihr habt es Euch verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9139] = {title = "Goldnebel", objective = "Besiegt 6 Geister der Quel'dorei und 4 Gespenster der Quel'dorei in Goldnebel. Kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", description = "Wir haben unseren ersten Sieg errungen, doch es warten noch zwei weitere Dörfer auf ihre Befreiung!\n\nDas Dorf Goldnebel ist unser nächstes Ziel. Es liegt im Nordwesten und wurde von den Geistern der Hochelfen besetzt, die dort einst lebten. Grauenerregend, ich weiß, allerdings scheint dies eine der bevorzugten Taktiken zu sein, derer sich die Geißel bedient.\n\nZieht los und besiegt diese Geister und Gespenster, <Klasse>. Folgt der westlichen Straße, die aus Tristessa hinaus führt und Ihr werdet das Dorf finden.", progress = "In all der Zeit, in der ich hier nun stationiert bin, habe ich viel über das Bekämpfen der Geißel gelernt. Man kann sie zurückschlagen, doch es muss in kleinen Schritten erfolgen. Die grauenhafte Tatsache, dass sie unsere Gefallenen wiederbeleben und sie in die Reihen ihrer Armeen aufnehmen, macht es zwingend notwendig, in diesem Kampf keine Fehler zu begehen.\n\nNun, wie läuft es in Goldnebel?", completion = "Euer Erfolg in Goldnebel bringt uns wieder einen Schritt näher an die vollständige Rückeroberung unserer Ländereien. Doch lasst Euch nicht täuschen, &lt;Klasse&gt;, diese Schlacht ist noch lange nicht geschlagen.\n\nHier, diese Belohnung habt Ihr Euch mehr als verdient. Sie wird sich als nützlich erweisen, sobald Ihr nach Windläuferdorf aufbrecht.", rewards = "Ihr bekommt:\n\nSpezialgebräu aus GoldnebelDoppelbogen von Quel'Thalas"}
MultiLanguageQuestData['de'][9140] = {title = "Windläuferdorf", objective = "Sammelt 6 geisterhafte Substanzen und 4 Gargoylefragmente und bringt sie zu Arkanist Vandril in Tristessa in den Geisterlanden.", description = "<Name>, der entscheidende Kampf um die Dörfer der Geisterlande steht kurz bevor. Windläuferdorf im Südwesten wurde von einer großen Armee aus den besten Sturmtruppen der Geißel, Schemengeister und Gargoyles überrannt. Ihr werdet als Speerspitze unserer Offensive fungieren und die Zahl ihrer Kämpfer dezimieren.\n\nDie Magister vom Sanktum der Sonne haben uns einen besonderen Auftrag erteilt; sie würden gerne die Überreste der Geißel studieren, um neue Wege zur Bekämpfung dieser Plage zu finden.\n\nGute Jagd!", progress = "<Klasse>, wurde das Windläuferdorf befreit? Diese verdammten Magister des Sanktums der Sonne fordern ständig von mir, dass ich ihnen endlich Überreste der Geißel gebe, die Ihr gerade für mich sammeln sollt.\n\nMacht Euch deshalb aber keine Sorgen! Nehmt Euch alle Zeit, die Ihr braucht, um diesen Auftrag sicher zu Ende zu führen. Ich kümmere mich derweil um die Magister.", completion = "Ihr habt es geschafft, &lt;Name&gt;. Ihr habt drei Dörfer aus der Umklammerung der Geißel befreit! Nun können wir uns voll und ganz auf die Bekämpfung der Geißel in der Todesschneise und südlich bei der Todesfestung konzentrieren.\n\nSucht Euch eine dieser Belohnungen aus. Ich hoffe, Ihr bleibt noch ein Weilchen. Wir können Eure Hilfe auch weiterhin gut gebrauchen!", rewards = "Dolch des ArkanistenGeflickte PanzergamaschenGepolsterte LaufschuheZauberstab des ArkanistenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9141] = {title = "Sie nennen mich \"den Schleifer\"", objective = "Einsatzkommandant Metz bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte eine Ehrenmarke der Argentumdämmerung.", description = "Ihr wollt eine Verfügung? Ihr erwartet von mir, Euch eine heißbegehrte Arbeitsanweisung einfach so auszuhändigen? Ich glaube nicht, Knirps. Handwerker aus der ganzen Welt bewerben sich um Aufträge hier an der Front.\n\nWenn Ihr eine Arbeitsanweisung wollt, zeigt mir, dass Ihr gewillt seit, für die Sache zu bluten! Bringt mir eine Ehrenmarke, dann können wir darüber reden.\n\nUnd es gibt nur einen Weg, so eine Marke in Eure schmutzigen kleinen Pfoten zu bekommen - geht kämpfen.", progress = "<Einsatzkommandant Metz kaut auf seiner Zigarre.>\n\nWas gibt's? Ich bin ein vielbeschäftigter Mann.", completion = "In Ordnung, so funktioniert's: Für jede Ehrenmarke, die Ihr abgebt, gebe ich Euch eine Verfügung. Ihr führt die Anweisung auf dieser Verfügung aus und liefert die Waren an Rottenkommandant Stonebruiser. Kapiert? Dann raus mit Euch.", rewards = "Ihr bekommt:\n\nVersiegelte Handwerksverfügung"}
MultiLanguageQuestData['de'][9142] = {title = "Handwerksverfügung", objective = "Ihr wisst wie's geht, Kind. Für eine Ehrenmarke bekommt Ihr eine Handwerksverfügung.", description = nil, progress = "Ihr wisst wie's geht, Kind. Für eine Ehrenmarke bekommt Ihr eine Handwerksverfügung.", completion = "Ihr habt's verdient, Anfänger. Beschwert Euch also nicht. Erfüllt Euren Auftrag oder lasst es bleiben.", rewards = "Ihr bekommt:\n\nVersiegelte Handwerksverfügung"}
MultiLanguageQuestData['de'][9143] = {title = "Maßnahmen gegen Zeb'Sora", objective = "Sammelt 6 Trollohren von Zeb'Sora und bringt sie zu Waldläuferin Valanna in den Geisterlanden.", description = "Unser Leutnant hier hat uns einfach angreifen lassen, ohne sich vorher ein Bild über die taktische Lage zu machen. Die Trolle lauerten bereits jenseits des Sees auf uns. Durch seine Unfähigkeit wurden wir einfach dahingemetzelt! Hoffentlich hörst du auch zu, Tomathren? Dämlicher Idiot!\n\nWerdet Ihr uns helfen, <Klasse>? Diese Trolle sind immer noch dort draußen. Ich werde hier bei unserem Leutnant bleiben - ich glaube, er hat seinen Verstand verloren.\n\nGeht nach Zeb'Sora im Osten auf der andere Seite des Sees. Ich will Rache! Bringt mir ihre Ohren, damit ich mir eine nette Halskette anfertigen kann!", progress = "Habt Ihr die Trollohren?\n\nWisst Ihr, wenn wir ab und an mal etwas Unterstützung aus Tristessa erhalten würden, wäre die ganze Misere hier so nie passiert. Ich bin wirklich froh über Euer Kommen.", completion = "Ich schätze Eure Bemühungen, &lt;Klasse&gt;! Habt Dank. Wenigstens können wir jetzt sagen, dass diese ganze Expedition und die vielen Opfer nicht vergebens gewesen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9144] = {title = "Verschollen in den Geisterlanden", objective = "Folgt der Straße, die von Morgenluft aus nach Süden führt, und haltet Ausschau nach Kurier Morgenwandler, wenn Ihr die Geisterlande erreicht.", description = "Mein Neffe wurde vor einigen Tagen in die Geisterlande entsandt. Er hat nicht von seinem Auftrag gesprochen, nur, dass es sich um etwas extrem Geheimes handelt.\n\nEr kehrte nie zurück, und ich befürchte das Schlimmste, <Klasse>. Ein vermisster Bote mag den hartherzigen Magistern von Silbermond nicht viel bedeuten, aber er ist wie ein Sohn für mich. Ich bitte Euch, <Name>, sucht nach ihm.", progress = nil, completion = "Helft mir, Fremder. Ich muss... Tristessa... erreichen... Ich darf nicht versagen.\n\n&lt;Der Blick des Blutelfen entschwindet ins Leere, und er versinkt wieder in Bewusstlosigkeit.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9145] = {title = "Hilfe für Waldläuferin Valanna!", objective = "Findet Waldläuferin Valanna und Leutnant Tomathren am Ufer des Elrendarsees nahe Sonnenkuppe in den Geisterlanden.", description = "<Klasse>, ich kann hier nicht einfach rumsitzen und auf eine Audienz mit dem Hochexekutor oder der Dame Auriferous warten! Diese Angelegenheit duldet keinen Aufschub!\n\nWir hatten den Auftrag, uns um die Waldschattentrolle von Zeb'Sora im Nordosten jenseits des Elrendarsees zu kümmern. Doch unser Leutnant hat den Angriff falsch geplant und wir haben hohe Verluste erlitten. Kurz nach der Attacke ist er dann zusammengebrochen. Waldläuferin Valanna hat mich hierher und Waldläuferin Salissa in die Enklave der Weltenwanderer entsandt, um Verstärkung anzufordern.\n\nIhr müsst unsere Einheit finden, <Klasse>! Valanna ist schwer verletzt und der Leutnant ist nur noch ein plapperndes Mündel.", progress = nil, completion = "Es ist gut zu hören, dass Lethvalin sich in Sicherheit bringen konnte, und dass er Euch um Hilfe gebeten hat, anstatt einfach nur abzuwarten.\n\nHoffentlich konnte sich Waldläuferin Salissa zur Enklave der Weltenwanderer durchschlagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9146] = {title = "Meldung bei Hauptmann Helios", objective = "Sprecht mit Hauptmann Helios bei der Enklave der Weltenwanderer am südlichen Ufer des Elrendarseese in den Geisterlanden.", description = "Ihr müsst mir einen letzten Gefallen tun, <Klasse>. Für den Fall, dass Waldläuferin Salissa es nicht bis zur Enklave der Weltenwanderer am südlichen Ausläufer des Sees geschafft hat, möchte ich, dass Ihr dorthin reist und Hilfe holt.\n\nMeldet Euch einfach bei Hauptmann Helios und lasst ihn wissen, was hier geschehen ist. Sicherlich wird er uns schnellstmöglich Hilfe schicken.", progress = nil, completion = "Das sind in der Tat schlechte Nachrichten - Ich habe Tomathrens Führungsqualitäten völlig überschätzt. Ich werde sofort einen Kampftrupp entsenden, um ihn und Valanna sicher zurückzubringen.\n\nUnglücklicherweise haben wir nichts mehr von Waldläuferin Salissa gehört, ich befürchte das Schlimmste.\n\nIhr habt den Weltenwanderern heute einen wertvollen Dienst erwiesen, &lt;Klasse&gt;. Bitte nehmt dies als Zeichen unserer Wertschätzung.", rewards = "Tunika des WeltenwanderersHandschuhe des TrollantreibersSchild des WeltenwanderersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9147] = {title = "Der sterbende Kurier", objective = "Apothekerin Thedra im Immersangwald möchte, dass Ihr ihr 4 verseuchte Blutproben von Tieren aus den Geisterlanden bringt.", description = "Was steht Ihr hier herum? Seht Ihr nicht, dass Ihr Euch um diesen Jungen sofort kümmert müsst? Wie es aussieht, hat die Seuche seinen Körper jetzt gänzlich befallen. In wenigen Minuten kann nicht einmal eine Apothekermeisterin wie ich ihn noch retten.\n\nDas Blut der Tiere südlich des Flusses ist bereits verseucht. Geht über die Brücke und jagt dort die befallenen Biester. Bringt mir genügend verseuchte Blutproben und ich werde daraus ein Serum gewinnen, das diesen Blutelfen retten kann. Beeilt Euch!", progress = "Und? Habt Ihr, was ich benötige? Beeilt Euch oder mit dem hübschen <Volk> ist es gleich aus!", completion = "Gerade noch rechtzeitig, &lt;Name&gt;! Ich war drauf und dran für unseren Freund hier ein schönes Loch auszuheben.\n\nMein Trank scheint zu wirken; er kommt wieder zu sich.\n\nHey, ich glaube er will Euch etwas sagen. Warum versucht Ihr nicht mal mit ihm zu sprechen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9148] = {title = "Zustellung nach Tristessa", objective = "Bringt den Brief aus Silbermond zu Arkanist Vandril in Tristessa in den Geisterlanden.", description = "Ich... ich bin zu schwach... ich kann nicht mehr weiter. Ich trage eine finstere Warnung vom Lordregenten Theron bei mir, einen Brief, um genau zu sein. Ihr müsst ihn für mich überbringen.\n\nBringt ihn zu Arkanist Vandril in Tristessa. Die Stadt liegt weiter im Süden entlang dieser Straße. Geht dorthin... und findet Vandril...", progress = "Ihr habt den Brief?", completion = "Endlich! Wir haben schon seit Wochen auf eine Antwort vom Lordregenten gewartet! Lasst mich mal sehen...\n\n&lt;Vandril beginnt den Brief zu lesen.&gt;\n\nWas soll das? Eine finstere Präsenz? Er spürt eine finstere Präsenz in den Geisterlanden?! Im Ernst, das hätte ich ihm auch sagen können!\n\nIst das die Nachricht, auf die wir gewartet haben?", rewards = "Wickeltücher des KuriersSpäherarmschienen von TristessaBronzene PanzerarmschienenIhr bekommt:\n\nKuriertasche"}
MultiLanguageQuestData['de'][9149] = {title = "Die verseuchte Küste", objective = "Bringt 6 verseuchte Murlocrückgrate zu Apotheker Renzithen in Tristessa in den Geisterlanden.", description = "Um ein Heilmittel gegen die Seuche finden zu können, müssen wir verstehen, wie sie sich auf verschiedene Kreaturen auswirkt: von den komplexesten Lebensformen bis hin zu niedrigen Untergattungen.\n\nIch kam hierher, um die Murlocs zu untersuchen, da sie, wie wir, ihren freien Willen auch im Untotendasein erhalten haben. Was ist an diesen einfachen Biestern nur so besonders? Ich muss es herausfinden, <Name>!\n\nReist nach Nordwesten und bringt mir ihre Rückgrate, damit ich die Ablagerungen der Seuche in ihrem Knochenmark studieren kann. Wer weiß was für Geheimnisse diese kleinen Knochen in sich bergen?", progress = "Habt Ihr die Exemplare, um die ich Euch gebeten habe, <Name>?", completion = "Ausgezeichnet! Diese Rückgrate sind für meine Untersuchungen von unschätzbarem Wert! Sollte ich ein Heilmittel gegen die Seuche finden und meinem Namen dadurch Ruhm verleihen, werde ich nicht vergessen, Euch zu erwähnen!\n\nBis dahin, nehmt dies als Belohnung. Ihr könntet davon Gebrauch machen, solltet Ihr noch einmal zur Küste gehen.", rewards = "Ihr bekommt:\n\nSchwimmtempotrankRenzithens verstaubter Umhang"}
MultiLanguageQuestData['de'][9150] = {title = "Reise zum vergessenen Sanktum", objective = "Magister Darenis möchte, dass Ihr zum Sanktum des Mondes westlich von Tristessa reist und dort 8 kristallisierte Manaessenzen von den dort hausenden Arkanverschlingern und Manaschleichern erlangt.", description = "Glaubt Ihr das, <Name>? Momentan gibt es ein funktionstüchtiges arkanes Sanktum, das südöstlich von hier im Einsatz ist, das Sanktum der Sonne. Alle Magister, die sich für wichtig halten, möchten an dessen Unterhaltung beteiligt sein.\n\nDas Sanktum des Mondes im Westen haben natürlich alle vergessen. Es ist nicht mehr viel davon übrig und seine Energien haben merkwürdige Kreaturen erweckt.\n\nIch bin niemand, der gute Ressourcen einfach so verkommen lässt! Geht zum Sanktum des Mondes und versucht kristallisierte Essenzen von den Kreaturen dort zu erlangen.", progress = "Habt Ihr die Essenzen, <Name>?", completion = "Sie sind in einem bemerkenswert guten Zustand, &lt;Name&gt;. Ich bin mit Eurer Arbeit sehr zufrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9151] = {title = "Das Sanktum der Sonne", objective = "Sprecht mit Magister Idonis im Sanktum der Sonne in den Geisterlanden.", description = "Ihr habt Eure Loyalität gegenüber Tristessa bewiesen und uns geholfen, gegen die Geißel zu kämpfen. Einige unserer mächtigsten Magister sind aus Silbermond gekommen, um uns dabei zu helfen, den Feind vor seiner eigenen Schwelle zu bekämpfen.\n\nSie haben das arkane Sanktum im Süden wiedererrichtet und die Geißel aus der umliegenden Gegend vertrieben. Sie planen einen Angriff auf die Todesfestung, Dar'kahns Stützpunkt. Ihr solltet sie unterstützen, <Name>. Ich bin mir sicher, dass <ein erfahrener/eine erfahrene:c> <Klasse> wie Ihr hier eine echte Hilfe wäre.", progress = nil, completion = "Darenis schickt Euch? Gut, ich schätze, wir können Euch im Kampf gegen Dar'khans Streitmächte brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9152] = {title = "Tombers Vorräte", objective = "Erlangt Rathis Tombers Vorräte und kehrt zu ihm in Tristessa in den Geisterlanden zurück.", description = "Wie soll ich die Kriegsvorbereitungen mit Vorräten unterstützen, wenn ich sie nicht mal sicher hierher bringen kann? Man hat mir Geleitschutz versprochen, der niemals kam. Ich musste dann auch noch einen meiner Karren zurücklassen, als ich von einer Bande Ghule im Westen angegriffen wurde!\n\nWollt Ihr mir vielleicht helfen, damit ich mein Geschäft auch eröffnen kann? Geht die westliche Straße, die aus der Ortschaft führt, runter und am Friedhof vorbei. Auf der anderen Seite der Todesschneise liegt eine Verzweigung. Der Hügel, auf dem ich meinen Karren lassen musste, liegt kurz dahinter.", progress = "Sobald ich den Rest meiner Vorräte habe, kann ich mein Geschäft aufnehmen. Die Streitkräfte werden nicht weit kommen, wenn sie nicht das erhalten, womit sie regelmäßig ihren Handel treiben.\n\nKriegsgebiete können so florierend für das Geschäft sein, findet Ihr nicht auch, <Klasse>? So, habt Ihr Euch einen Weg durch all die Ghuls zu meinem Karren bahnen können?", completion = "Dank der restlichen Vorräte hier, kann ich jetzt endlich mit meinem Geschäft loslegen. Ich bin mir sicher, dass der Hochexekutor erfreut sein wird, sobald er hört, dass der Krieg gegen Dar'Khan und die Geißel beginnen kann.\n\nNatürlich gibt es da auch noch Eure Belohnung. Nun gut, &lt;Klasse&gt;, hier ist die von mir erwähnte Münze. Solltet Ihr irgendwelche Handwerkswaren benötigen, schaut einfach vorbei.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9153] = {title = "Bedrohliche Schatten", objective = "Benutzt Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die Truppen der Geißel, die sie umgeben, besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Die schwebenden Nekropolen der Geißel setzen die Territorien der Horde genauso unter Druck wie die der Allianz. Tanaris, die Verwüsteten Lande, Winterquell und die Brennende Steppe erzittern unter den Schatten der fliegenden Festungen.\n\nNur durch unser gemeinsames Handeln können wir sie zurückschlagen.\n\nJede Nekropole wird durch magische Zirkel unterstützt, die sich in der Nähe befinden und um die sich ein Schwarm untoter Kreaturen versammelt. Wir haben herausgefunden, dass wir die Verteidigung rund um die Zirkel zerstören können, indem wir die geistlosen Horden vernichten.", progress = "Es wird einige Zeit dauern, bis wir diese Bedrohung überwunden haben. Wie ist es Euch ergangen, <Name>?", completion = "Ihr habt Euch sehr gut geschlagen, &lt;Name&gt;. Die vielen Niederlagen werden letztlich den Fall des Lichkönigs und seiner Diener herbeiführen.\n\nRuht Euch etwas aus und erholt Euch. Schon bald müsst Ihr jedoch wieder an die Front zurückkehren, damit wir unsere gerade gewonnene Stellung nicht wieder verlieren.\n\nUm Euch bei Euren Kämpfen zu unterstützen, werden wir Euch einen unserer speziellen Gegenstände zur Verfügung stellen, sobald Ihr uns mehr nekrotische Runen bringt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"}
MultiLanguageQuestData['de'][9154] = {title = "Kapelle des Hoffnungsvollen Lichts", objective = "Bringt den Ruf zu den Waffen zum Bewahrer der Schriften in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Die Geißel ist in größerer Anzahl zurückgekehrt, als wir es jemals zuvor gesehen haben. Dies müssen die Machenschaften des Lichkönigs sein! Deshalb rekrutiert die Argentumdämmerung alle Männer und Frauen, die fähig und bereit sind, unsere Länder zu verteidigen.\n\nFalls Ihr unserer Sache dienen wollt, dann bringt dieses Dokument zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "Ihr seid also gekommen, unserem Orden beizutreten?", completion = "Die Argentumdämmerung hat um Hilfe gebeten, und Ihr seid unserem Ruf gefolgt. Wir haben keine Zeit, Euch angemessen auszubilden, aber wir glauben an Eure Fähigkeiten und daran, dass Ihr gemeinsam mit uns die Geißel zurückdrängen werdet.", rewards = nil}
MultiLanguageQuestData['de'][9155] = {title = "Entlang der Todesschneise", objective = "Tötet 10 hungrige Auferstandene und 10 gegeißelte Kannibalen in der Todesschneise. Kehrt anschließend zu Todespirscher Rathiel in Tristessa zurück, um Eure Belohnung zu erhalten.", description = "Da Ihr es bis hierher geschafft habt, habt Ihr bestimmt schon mal von der Todesschneise gehört und dass selbst jetzt, Jahre nachdem Arthas sie während seines Feldzuges nach Silbermond erschaffen hat, die geistlosen Kreaturen der Geißel noch immer auf ihrem Pfad wandeln.\n\nMacht Euch nützlich und dünnt die Anzahl der Geißel innerhalb der Schneise etwas aus. Falls Ihr Euch als fähig erweist, lege ich ein gutes Wort für Euch ein.", progress = nil, completion = "Nicht schlecht, &lt;Name&gt;. Macht weiter so! Leute wie Euch können wir immer gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9156] = {title = "Gesucht: Faulbein und Luzran", objective = "Sucht in den Geisterlanden nach Faulbein und Luzran. Bringt ihre Köpfe zu Todespirscher Rathiel in Tristessa, um eine Belohnung zu erhalten.", description = "Hiermit ist ein Kopfgeld auf die Monstrositäten Faulbein und Luzran ausgesetzt. Diese abscheulichen Kreaturen von Dar'Khan sind sehr gefährlich, und wurden in der Nähe der Heulenden und Blutenden Ziggurats auf Patrouille gesehen. Personen, welche die Belohnung einfordern wollen, müssen die Köpfe der Monstrositäten als Beweis zu Todespirscher Rathiel bringen.", progress = "Ihr habt etwas, das Ihr mir zeigen wollt, <Name>?", completion = "Aha! Luzran und Faulbein! Jetzt seht ihr nicht mehr so gefährlich aus, was? Aber immer noch genau so hässlich!\n\nNehmt dies als Belohung, &lt;Name&gt;. Ihr habt es Euch verdient.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegel des HerbeirufersTöterband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9157] = {title = "Vergessene Rituale", objective = "Bringt 8 Wellenfrontmedaillons zu Geranis Weißflor in den Geisterlanden.", description = "Jedes Jahr haben wir, die Einwohner von Sonnenkuppe, an einem Ritual teilgenommen, um die verschiedenen Aspekte der Natur unter unserer Kontrolle zu halten. Die Herrschaft über das Wasser wurde symbolisiert durch die Beschwörung und Versklavung eines Wasserelementars namens Aquantion. Aber es gelang ihm, unsere Magie gegen uns zu wenden, seine Fesseln abzuwerfen und stattdessen uns zu versklaven!\n\nWährend des Rituals trugen wir wellenförmige Medaillons. Sucht sie auf dem Grund des Sees, wir benötigen sie, um die Geister meiner Kameraden zu befreien!", progress = "Konntet Ihr die Medaillons beschaffen, <Name>? Die Ertrunkenen suchen immer noch diesen See heim!", completion = "Mit Hilfe dieser Halsketten werden wir Aquantion erneut beschwören. Der rebellische Elementar wird bezahlen und unser Tod wird gerächt werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9158] = {title = "Überträger der Seuche", objective = "Weltenwanderin Sedina in der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr 10 Geisterklauenluchse erschlagt.", description = "Eure Anwesenheit in den Geisterlanden zeugt von großem Mut, <Name>. Hier gibt es so viel zu erledigen und nur wenige mutige Seelen, die uns zur Seite stehen.\n\nIch habe eine undankbare Aufgabe für Euch, sofern Ihr geneigt seid, unserer Sache zu dienen. Die gesamte Fauna wurde von der Seuche befallen und wir müssen ihre weitere Ausbreitung stoppen. Jagt die Geisterklauenluchse nördlich und südlich von hier und kehrt zu mir zurück, nachdem Ihr eine ausreichende Zahl erlegt habt.", progress = nil, completion = "Ihr habt Euch bewährt, &lt;Name&gt;. Es ist von größter Wichtigkeit, dass die Seuche nicht auch noch die gesunde Fauna des Immersangwalds befällt. Ich habe noch weitere Aufgaben für Euch, sofern Ihr noch auf der Suche nach Arbeit seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9159] = {title = "Gebietet der Seuche Einhalt", objective = "Weltenwanderin Sedina in der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr 8 Spindelweberlauerer und 10 Vampirnebelfledermäuse erschlagt.", description = "Ihr habt Euch als würdiger Verbündeter erwiesen, <Name>. Ihr müsst mit Eurer Aufgabe fortfahren und weitere verseuchte Wildtiere erlegen. Dieses Mal werdet Ihr Euch die etwas gefährlicheren Exemplare vornehmen. Jagt Spindelweberlauerer westlich der Todesschneise und Vampirnebelfledermäuse direkt südlich von hier. Kehrt anschließend zu mir zurück.", progress = nil, completion = "Ihr habt Eure Aufgabe sehr ernst genommen und daher möchte ich Euch entsprechend belohnen. Wir brauchen mehr Verbündete mit Eurer Hingabe und Tapferkeit, &lt;Name&gt;!", rewards = "Schärpe des WaldläufersGürtel des WeltenwanderersVerrosteter KettengurtIhr bekommt:\n\nÜberlebensmesser"}
MultiLanguageQuestData['de'][9160] = {title = "Untersucht An'daroth", objective = "Untersucht das Gebiet um An'daroth, tötet 12 Spione der Schildwache und kehrt anschließend zu Dame Auriferous in Tristessa in den Geisterlanden zurück.", description = "<Klasse>, wir haben einige Schwierigkeiten mit einer Gruppe von Nachtelfen, die erst kürzlich eine der naheliegenden Inseln besetzt hat. Sie haben ein kleines Lager an dem alten hochelfischen Leyliniennexus, An'daroth, im Nordwesten aufgeschlagen. Es gibt einen kleinen schlammigen Pfad, der hinter der Todesschneise dorthin führt.\n\nIch würde vorschlagen, dass Ihr uns helft, indem Ihr Euch dorthin begebt und herausfindet, was sie vorhaben. Tötet bei der Gelegenheit so viele dieser eingebildeten Nachtelfen, wie Ihr könnt.", progress = nil, completion = "Es ist enttäuschend, dass es keine offensichtlichen Hinweise auf die Pläne der Nachtelfen bei An'daroth gab. Wie auch immer, diese Bäume, welche aussahen wie kleine magisch gewachsene Bäume mit Energiekugeln auf ihrer Spitze, sind äußerst interessant. Es scheint mir, als müssten wir die Art unserer Informationsbeschaffung ein wenig direkter gestalten.\n\nHier, nehmt diese Münze und die Tränke. Vermutlich werdet Ihr sie noch brauchen, bevor wir diese Angelegenheit mit den Nachtelfen geklärt haben.", rewards = "Ihr bekommt:\n\nGeringer Heiltrank"}
MultiLanguageQuestData['de'][9161] = {title = "Schatten des Verräters", objective = "Begebt Euch in die Geisterlande zum Morgensternturm und sucht nach möglichen Hinweisen auf Dar'Khans Vergangenheit.", description = "Man sagt, Dar'Khan Drathir sei von den Toten wiederauferstanden, um über die Armeen der Geißel in den Geisterlanden zu herrschen. Schon vor langer Zeit hatte sich Dar'Khan mit der Geißel eingelassen... damals war er noch ein lebender, atmender Elf. Er verbrachte viel Zeit in den Gemäuern des Morgensternturms, nordöstlich von hier. Dort verbarg er sich viele Nächte lang, ersann finstere Machenschaften gegen sein eigenes Volk.\n\n<Name>, durchsucht den Turm nach weiteren Informationen. Vielleicht hatte er seine Pläne niedergeschrieben, oder er führte ein Tagebuch. Wer weiß schon, wo nützliche Hinweise auf Ihre Entdeckung warten.", progress = nil, completion = "Ihr blättert durch die ersten Einträge des uralten Buchs und kommt zu dem Schluss, dass es einst der Person gehörte, die heute als Dar'khan Drathir bekannt ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9162] = {title = "Die Vergangenheit erwacht", objective = "Kehrt mit Dar'Khans Tagebuch zu Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", description = "Als Ihr durch die Einträge des Tagebuchs blättert, bekommt Ihr das unbestimmte Gefühl, beobachtet zu werden.\n\nDas Geschriebene beunruhigt Euch. Dar'Khans Seele scheint erfüllt von Hass und Verachtung für sein eigenes Volk. Das ganze Ausmaß seiner Machenschaften und Intrigen wird auf diesen Seiten ausführlich beschrieben.\n\nEiniges davon wird Vynna sicherlich sehr nützlich finden.", progress = "Sagt mir, <Name>, was habt Ihr herausgefunden?", completion = "Diese Information ist für uns von hohem Wert, &lt;Name&gt;. Wir alle wussten von Dar'Khans Plänen, die Macht des Sonnenbrunnens für die Geißel zu stehlen, doch vieles auf diesen Seiten ist völlig neu für uns. Magister Kaendris beim Sanktum der Sonne wird sich sicherlich sehr dafür interessieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9163] = {title = "In besetztem Gebiet", objective = "Stehlt die Nachtelfenpläne: An'daroth, Nachtelfenpläne: An'owyn und Nachtelfenpläne: Auskundschaften der Sin'dorei und kehrt anschließend in die Geisterlande zu Dame Auriferous in Tristessa zurück.", description = "Nun, die direkten Maßnahmen, für die wir uns letztlich entschieden haben, um herauszubekommen, was diese verdammten Nachtelfen vorhaben, sehen grob zusammengefasst folgenden Ablauf vor: Landet auf ihrer Insel und nehmt alles mit, das für uns von Interesse sein könnte.\n\nIch möchte, dass Ihr die Straße nach Westen in Richtung der Insel Shalandis nehmt. Sie liegt recht nah an der Küste. Nehmt dort sämtliche Pläne mit, die sie möglicherweise auf der Insel oder auf ihrem Schiff verstaut haben.", progress = "Was machen unsere Bemühungen, die Nachtelfenverschwörung auf der Insel Shalandis aufzudecken, <Klasse>?", completion = "Äußerst beunruhigend! Die Pläne zeigen die Streitkräfte der Nachtelfen bei An'daroth, von denen wir bereits wussten, doch gibt es wohl eine weitere Gruppe bei An'owyn, einem eher abgelegenen Leyliniennexus im Südosten.\n\nEs existiert noch ein dritter Nexus im Osten, An'telas, der nicht weiter erwähnt wird. Ich habe da ein ganz mieses Gefühl bei der Sache, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9164] = {title = "Gefangene der Todesfestung", objective = "Nehmt Renzithens Regenerationsgebräu und begebt Euch zur Todesfestung. Befreit dort Lehrling Varnis, Apothekerin Enith und Waldläufer Vedoran. Kehrt danach zu Arkanistin Janeda beim Sanktum der Sonne zurück, um Eure Belohnung zu erhalten.", description = "Ah, ja. Eine meiner gelungensten Kreationen. Dieses Gebräu wirkt jeglichen Betäubungseffekten entgegen, die durch alchemistische Mittel verursacht werden.\n\nEs kann zu Nebeneffekten wie Verwirrung und Übelkeit kommen, in wenigen Fällen führt es zu zeitweiser Blindheit. Doch wenn Ihr mich fragt, ist dies alles immer noch besser, als das, was die Geißel den Gefangenen in der Todesfeste antun wird.\n\nViel Glück, <mutiger/mutige:c> <Klasse>. Ihr werdet es brauchen.", progress = "Was wurde aus den Gefangenen der Todesfestung? Seid Ihr schon dort gewesen?", completion = "Hervorragende Arbeit, &lt;Name&gt;. Ohne Eure Hilfe, hätten diese Gefangenen ihren Verstand und ihre Seele an die Geißel verloren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9165] = {title = "Verfügung des freien Geleits", objective = "Bringt die unterschriebene Verfügung des freien Geleits zu Einsatzkommandant Metz an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ohne die Hilfe von Euch Abenteurern, hätte meine Karawane es niemals geschafft! Die Geißelsoldaten, die uns im Unterholz aufgelauert haben, wollten wohl nicht, dass wir hier in einem Stück eintreffen.\n\n<Wache Didier wischt sich den Schweiß von der Stirn.>\n\nJetzt werden wir erst einmal hier warten, bis Feldmarschall Kammerer eintrifft. Er wird Eure Verfügung für freies Geleit unterzeichnen, die Ihr dann zu Einsatzkommandant Metz an der Kapelle des Hoffnungsvollen Lichts bringen könnt.\n\nUnd <Name>, achtet in der Gegenwart von Kammerer auf Eure Worte. Er ist ein Mensch der Sorte 'Ich reiße Euch den Kopf ab und breche Euch sämtliche Knochen'... mit dem Unterschied, dass er es auch wirklich tut...Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne der DämmerungInsigne des Kreuzzugs"}
MultiLanguageQuestData['de'][9166] = {title = "Bringt die Pläne nach An'telas", objective = "Bringt die Nachtelfenpläne zu Magister Sylastor bei An'telas in den Geisterlanden.", description = "Bringt die Nachtelfenpläne für mich nach An'telas. Es liegt östlich von hier, auf dem südlichen Hang des Sonnenhügels, nordöstlich vom Sanktum der Sonne.\n\nMagister Sylastor führt dort diverse Experimente mit den Energien des Leyliniennexus durch, um potentielle Verwendungsmöglichkeiten im Kampf gegen die Geißel zu finden. Zeigt ihm die Pläne, möglicherweise kann er etwas Licht in die Sache bringen und herausfinden, was die Nachtelfen vorhaben.", progress = "Gut, dass Ihr hier seid!", completion = "Es war schrecklich! Nachtelfen! Sie haben einen Mondkristall beschworen und irgendeine Niedertracht geplant. Glücklicherweise konnte ich mich davonschleichen und einige unserer Späher und Zauberer aus dem nahegelegenen Sanktum der Sonne zur Hilfe holen. Es gelang uns, die meisten von ihnen zu töten. Die anderen sind daraufhin losgezogen, um die Überlebenden zu jagen!\n\nIch bin so froh, dass Ihr gekommen seid; man hat mich hier nur mit einigen wenigen Spähern zur Verteidigung zurückgelassen!\n\nGebt mir einen Moment, um diese Pläne zu lesen, möglicherweise finde ich heraus, worauf es die Nachtelfen abgesehen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9167] = {title = "Der Tod des Verräters", objective = "Begebt Euch in die Todesfestung und tötet Dar'Khan Drathir. Bringt anschließend Dar'Khans Kopf zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden.", description = "Alles, was wir in den Geisterlanden getan haben, hatte nur ein Ziel, die Rückeroberung all dessen, was rechtmäßig unser ist! Schon zu lange hielt die Geißel diese Region in ihrem Würgegriff.\n\nDie Zeit der Abrechnung ist gekommen, <Name>. Dank Eurer Unterstützung und der Hilfe unserer Verbündeten, den Verlassenen, wird die Rache unser sein!\n\nDerjenige, welcher danach trachtete, die Macht des Sonnenbrunnens an sich zu reißen, muss sterben. Begebt Euch zur Todesfestung, der Festung der Geißel südlich der Todesschneise. Bringt mir Dar'Khans Kopf und Eure Taten werden in die Geschichte eingehen!", progress = "Ist es getan? Wurde Dar'Khan vernichtet?", completion = "Am heutigen Tage habt Ihr der Geißel in dieser Region einen tödlichen Schlag versetzt.\n\nNach dem Tod des schändlichen Verräters ist die Rückeroberung unserer Länder nur noch eine Frage der Zeit. Schon bald werden wir zu altem Ruhm und Glanz zurückgefunden haben!", rewards = "Stab der SonneLangbogen des WeltenwanderersKlinge der DämmerungKriegsklinge der Sin'doreiIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9168] = {title = "Im Herzen der Todesfestung", objective = "Zerstört 8 Augen von Dar'Khan und meldet Euch anschließend bei Magister Idonis am Sanktum der Sonne in den Geisterlanden.", description = "Tief in Inneren der Todesfestung führt der Feind magische Experimente zur Erschaffung stärkerer, tödlicherer spektraler Soldaten durch. Diese verabscheuungswürdigen Wesen sind perfekte Tötungsmaschinen, erschaffen von Dar'Khan selbst und verstärkt durch die dunklen Magien der Todesfestung.\n\nBegebt Euch zum Turm der Verdammten im Inneren der Todesfestung und zerstört sie alle, <Name>. Wir dürfen es nicht zulassen, dass die Armee des Feindes immer stärker wird, während wir immer noch um die Aufrechterhaltung eines Brückenkopfes in den Geisterlanden kämpfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9169] = {title = "Die Abschaltung von An'owyn", objective = "Beschafft die Kristallkontrollkugel und benutzt sie, um die nachtelfischen Mondkristalle bei An'owyn zu deaktivieren. Kehrt anschließend zu Magister Sylastor in An'telas in den Geisterlanden zurück.", description = "Die Mondkristalle sind nichts anderes als Seherartefakte - sie wollen uns ausspionieren! Ich weiß, dass An'daroth dafür nicht genügend Energie liefert, doch An'owyn, direkt im Süden, verfügt über genügend Reserven!\n\nDurch die Pläne habe ich einen ungefähren Eindruck darüber gewonnen, wie diese Mondkristalle funktionieren und wir sollten in der Lage sein, sie zu deaktivieren. Allerdings sind sie gesichert, um eine ungewollte Abschaltung zu verhindern. Begebt Euch daher nach An'owyn, beschafft Euch die Kontrollkugel von einem der Nachtelfen und benutzt sie mit den Mondkristallen, um die Durchführung ihrer Pläne zu verhindern!\n\nBeeilt Euch, <Klasse>!", progress = nil, completion = "Ich bin erleichtert, &lt;Klasse&gt;! Seid versichert, dass wir ohne Eure Hilfe bei der Abschaltung der Seherkristalle in einer noch viel schwierigeren Lage wären, als wir es sowieso schon sind! Man stelle sich nur vor, umgeben von Feinden und einer von ihnen besäße die Fähigkeit, uns auf Schritt und Tritt zu beobachten!\n\nDank Euch müssen wir uns darüber keine Sorgen mehr machen! Ich habe hier zufällig noch einige Gegenstände herumliegen, für die ich keine weitere Verwendung mehr habe; sicherlich werdet Ihr davon etwas gebrauchen können. Hier, nehmt das als Belohnung.\n\nNochmals vielen Dank, &lt;Name&gt;!", rewards = "Sylastors UmhangSchuppenhemd von An'telasAuf Euch wartet eine dieser Belohnungen:\n\nWahrsagerkugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9170] = {title = "Dar'Khans Gefolgschaft", objective = "Magister Idonis möchte, dass Ihr Euch zur Todesfestung begebt und Masophet den Schwarzen, Jurion den Betrüger, Borgoth den Blutvergießer und Mirdoran den Gefallenen tötet. Kehrt nach Abschluss Eurer Aufgabe zum Sanktum der Sonne in den Geisterlanden zurück und berichtet ihm.", description = "Der verhasste Verräter, Dar'Khan, hat innerhalb der Geißel große Macht erlangt. Seine Gefolgschaft steht an der Spitze gigantischer Heere, die gegen unsere schwindenden Streitkräfte zu Felde ziehen.\n\nMasophet der Schwarze, Jurion der Betrüger, Borgoth der Blutvergießer, Mirdoran der Gefallene. Merkt Euch diese Namen, denn in den Geisterlanden sind diese Männer einzig Dar'Khan gegenüber verantwortlich. Tötet sie und ihre seelenlosen Armeen werden im Chaos versinken.", progress = nil, completion = "Schon bald werden Dar'Khans Armeen fallen. Die Geißel wird nicht gegen die vereinte Macht der Sin'dorei und der Verlassenen bestehen können.", rewards = "Neugeschmiedetes Wappen der Quel'doreiZauberstab des LeybewahrersGeisterklauengamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9171] = {title = "Knusperkost", objective = "Sammelt 5 knusprige Spinnenbeine ein und kehrt zu Meisterkoch Mouldier in Tristessa in den Geisterlanden zurück.", description = "Das ist unerhört! Ich habe hier keinerlei Zutaten! Mylady hat mich von Silbermond hierher bestellt. Ihr steht schließlich eine Küche zu, wie es sich für ihren Stand geziemt. Nicht? Ich komme der Bitte also nach, aber finde mich hier ohne Vorräte wieder. Ihr müsst für mich losziehen, <Klasse>, und mir frische Beute bringen, damit ich etwas zubereiten kann.\n\nDame Auriferous liebt besonders knusprige Gerichte. Südwestlich, auf der anderen Seite der Todesschneise, gibt es zahlreiche Spindelweberlauerer. Ekelhaft, ich weiß, aber wir müssen nun mal damit zurechtkommen.", progress = "Ich glaube ich kann den Magen der Dame sogar von hier aus knurren hören! Da Ihr hier seid und mich sprechen wollt, gehe ich davon aus, dass Ihr mir meine Zutaten bringt?", completion = "Sehr schön, das dürfte den Zweck erfüllen. Nein, erzählt mir nicht, wie die Dinger rumgekrabbelt sind, ich will es nicht wissen! Ich werde etwas Magie verwenden, dann werden diese Beinchen schon schmackhaft. Ein paar Gewürze, eine Messerspitze Kräuter und natürlich ein paar arkane Zutaten - et voila, ein passendes Mahl für eine Königin... oder in diesem Fall, eine Dame.\n\nEure Dienste waren zufriedenstellend, &lt;Klasse&gt;. Hier, nehmt dieses Rezept und ein paar Portionen.", rewards = "Ihr bekommt:\n\nKnusperspinne SurpriseRezept: Knusperspinne Surprise"}
MultiLanguageQuestData['de'][9172] = {title = "Bericht an Magister Kaendris", objective = "Bringt Dar'Khans Tagebuch zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden.", description = "Die Magister beim Sanktum der Sonne machen große Fortschritte bei ihrer Suche nach den Schwächen der Geißel, nicht zuletzt durch die Hilfe der Verlassenen. Magister Kaendris wird wissen, was mit diesen Informationen zu tun ist.\n\nDas Sanktum der Sonne liegt südwestlich von hier. Ihr müsst Euch beeilen, <Name>. Dar'Khan ist ein geschickter Gegner und er beobachtet jeden einzelnen unserer Schritte.", progress = "Ihr wünscht mit mir zu sprechen?", completion = "Dieses Buch... das ist unmöglich! Es ist Dar'Khans eigene Handschrift. Irgendwo in diesem Buch muss es einen Hinweis geben, der uns eine Schwäche des Gegners aufzeigt.\n\nIhr habt gut daran getan, uns aufzusuchen, &lt;Name&gt;. Indem sie diese Angelegenheit in unsere fähigen Hände gaben, haben die Weltenwanderer ihre Weitsicht bewiesen. Diese Rüstung sollte Euch helfen, unsere Sache weiterzuführen.", rewards = "Rote SeidenbeinkleiderSchwarzes LederwamsSchuppengamaschen von TristessaIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9173] = {title = "Rückeroberung des Windläuferturms", objective = "Besiegt 8 Akolythen der Todesfestung und 10 gefallene Waldläufer, dann kehrt zu Hochexekutor Mavren nach Tristessa in den Geisterlanden zurück.", description = "<Klasse>, Ich möchte, dass Ihr den Windläuferturm zurückerobert!\n\nDabei handelt es sich um eine Sache der Ehre. Der Windläuferturm ist die ursprüngliche Residenz von Fürstin Sylvanas Windläufer, Königin der Verlassenen und ehemalige Waldläufergenerälin der Elfen. Aber jetzt wurde der Turm von der Geißel überrannt.\n\nFolgt der Straße nach Süden, bis Ihr zu einer Abzweigung kommt. Wendet Euch dort nach rechts und geht weiter nach Südwesten, wenn Ihr die Todesschneise überquert habt. Dann könnt ihr den Ort nicht verfehlen.", progress = nil, completion = "Ich bin sicher, Lady Sylvanas wird über unsere Fortschritte in dieser Sache erfreut sein.\n\nHier, nehmt dies als Bezahlung für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9174] = {title = "Aquantion bezwingen", objective = "Geranis Weißflor möchte, dass Ihr auf den Grund des Sees östlich von Sonnenkuppe taucht und das Bündel mit Medaillons auf den Altar der Gezeitenbeherrschung legt. Beschwört und besiegt den Elementar Aquantion und kehrt zu Geranis zurück.", description = "Dieser eigenwillige Elementar hat viele Leben auf dem Gewissen. Indem er die unwürdigen Murlocs dazu brachte, unsere Rituale zu sabotieren, wendete er unsere Magie gegen uns.\n\nZeigt ihm, dass unser Durst nach Rache noch nicht gestillt ist! Nehmt diese Medaillons und legt sie auf den Altar der Gezeitenbeherrschung am Grund des Sees. Aquantion wird Eurem Ruf sofort folgen!\n\nSeid auf der Hut, <Volk>! Ohne die Kontrolle durch unsere Magie wird sein Zorn ungezügelt sein. Zerstört Aquantion, damit wir ruhen können!", progress = "Wurde Aquantion schon zerstört?", completion = "Ihr habt unseren Tod gerächt und Aquantions Macht über unsere Seelen gebrochen. Endlich können wir ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9175] = {title = "Die Halskette der Fürstin", objective = "Bringt die Halskette der Fürstin zu Hochexekutor Mavren nach Tristessa in den Geisterlanden.", description = "Diese Halskette funkelt, ein bemerkenswertes Schmuckstück, das nicht der Schwermut der Geisterlande zu unterliegen scheint. Auf Grund der Inschrift und des Ortes, an dem Ihr sie gefunden habt, muss es sich dabei um Eigentum von Fürstin Sylvanas Windläufer selbst handeln!\n\nVielleicht wäre es am besten, sie zuerst zu Hochexekutor Mavren nach Tristessa zu bringen? Er scheint der höchstrangige Verlassene in der Gegend zu sein und weiß sicher, was zu tun ist.", progress = "Was habt Ihr da, <Name>?", completion = "Ihr sagt, Ihr fandet dies bei einem Schergen der Geißel am Windläuferturm, und dass es eine Inschrift gibt? Lasst mich sehen!\n\nHier, nehmt dies für Eure gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9176] = {title = "Die Zwillingsziggurats", objective = "Reist zur Blutenden und zur Heulenden Ziggurat und bergt den Stein des Lichts und den Stein der Flamme. Kehrt anschließend zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden zurück.", description = "Glaubt man den Einträgen in seinem Tagebuch, versprach Dar'Khan der Geißel zwei mächtige elfische Artefakte: Den Stein des Lichts und den Stein der Flamme. Beide waren durchdrungen von den magischen Energien des Sonnenbrunnens und verfügten über mächtige Schutzkräfte gegen die Geißel.\n\nMan plante, die Kristalle zu den heutigen Standorten der Heulenden und der Blutenden Ziggurat, inmitten der Todesschneise, zu transportieren. Falls sie dort noch immer aufbewahrt werden, müssen wir sie unbedingt an uns bringen. Ihre Kräfte wären im Kampf gegen die Geißel von großem Nutzen.", progress = "Habt Ihr die Kristalle schon geborgen?", completion = "Die Geschichten sind also wahr! Der Stein des Lichts und der Stein der Flamme existieren tatsächlich! Wir werden ihre Macht nutzen, um wirkungsvolle Waffen gegen Dar'Khan zu schmieden.\n\nWenn Ihr die in diesen Artefakten schlummernden Energien zum richtigen Zeitpunkt freisetzt, werden sie Dar'Khan vernichten. Einst wollte er uns diese Macht nehmen, doch jetzt wird sie sein Untergang sein!", rewards = "Klinge des SonnenbrunnensAuf Euch wartet eine dieser Belohnungen:\n\nKugel des Sonnenbrunnens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9177] = {title = "Reise nach Unterstadt", objective = "Bringt die Halskette der Fürstin zu Fürstin Sylvanas Windläufer im Königsviertel von Unterstadt.", description = "Wie außergewöhnlich! Es scheint sich um ein Geschenk für Fürstin Sylvanas Windläufer zu handeln, von ihrer Schwester, Alleria!\n\nIhr müsst es sofort zu ihr nach Unterstadt bringen! Die Fürstin residiert im Königsviertel.\n\nUm dorthin zu kommen, benutzt die Translokationskugel im Inneren Sanktum des Sonnenzornturms in Silbermond für den Übergang nach Unterstadt, dann nehmt den Fahrstuhl, um die eigentliche Stadt zu betreten. Schaut auf Eure Karten, wenn Ihr Probleme habt, das Königsviertel zu finden.", progress = "Und Ihr seid?\n\nWas habt Ihr da? Diese Halskette sieht vertraut aus. Gebt sie her!", completion = "&lt;Sylvanas nimmt Euch die Halskette aus der Hand.&gt;\n\nUnmöglich! Nach so langer Zeit dachte ich, sie sei für immer verloren!\n\n&lt;Die Lady scheint sich langsam wieder ihrer Umgebung gewahr zu werden und gewinnt Ihre Fassung zurück.&gt;\n\nIhr dachtet, dies würde mich erheitern? Denkt Ihr, ich sehne mich nach der Zeit, bevor ich Königin der Verlassenen war? Es bedeutet mir nichts, Alleria Windläufer ist seit langem tot!\n\n&lt;Sie lässt das Amulett auf den Boden fallen.&gt;\n\nGeht mir aus den Augen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9178] = {title = "Handwerksverfügung - Verdichteter Gewichtsstein", objective = "Bringt 120 verdichtete Gewichtssteine und die Handwerksverfügung für die verdichteten Gewichtssteine zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-091:\n\n120 verdichtete Gewichtssteine.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Jawohl, die werden sich für die schonungslosen Waffen der Infanterie noch als nützlich erweisen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9179] = {title = "Handwerksverfügung - Imperiale Plattenrüstung", objective = "Bringt 3 imperiale Plattenrüstungen und die Handwerksverfügung für die imperialen Plattenrüstungen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-428:\n\n3 imperiale Plattenrüstungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9180] = {title = "Reise nach Unterstadt", objective = "Bringt die Halskette der Fürstin zu Fürstin Sylvanas Windläufer im Königsviertel von Unterstadt.", description = "Wie außergewöhnlich! Es scheint sich um ein Geschenk für Fürstin Sylvanas Windläufer zu handeln, von ihrer Schwester, Alleria!\n\nIhr müsst es sofort zu ihr nach Unterstadt bringen! Die Fürstin residiert im Königsviertel.\n\nUm dorthin zu kommen, benutzt die Translokationskugel im Inneren Sanktum des Sonnenzornturms in Silbermond für den Übergang nach Unterstadt, dann nehmt den Fahrstuhl, um die eigentliche Stadt zu betreten. Schaut auf Eure Karten, wenn Ihr Probleme habt, das Königsviertel zu finden.", progress = "Und Ihr seid?\n\nWas habt Ihr da? Diese Halskette sieht vertraut aus. Gebt sie her!", completion = "&lt;Sylvanas nimmt Euch die Halskette aus der Hand.&gt;\n\nUnmöglich! Nach so langer Zeit dachte ich, sie sei für immer verloren!\n\n&lt;Die Lady scheint sich langsam wieder ihrer Umgebung gewahr zu werden und gewinnt Ihre Fassung zurück.&gt;\n\nIhr dachtet, dies würde mich erheitern? Denkt Ihr, ich sehne mich nach der Zeit, bevor ich Königin der Verlassenen war? Es bedeutet mir nichts, Alleria Windläufer ist seit langem tot!\n\n&lt;Sie lässt das Amulett auf den Boden fallen.&gt;\n\nGeht mir aus den Augen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9181] = {title = "Handwerksverfügung - Vulkanischer Hammer", objective = "Bringt 3 vulkanische Hämmer und die Handwerksverfügung für die vulkanischen Hämmer zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-697:\n\n3 vulkanische Hämmer.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die sollten sich gut für die verdichteten Gewichtssteine eignen, die wir hier auf Lager haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9182] = {title = "Handwerksverfügung - Gewaltige Thoriumstreitaxt", objective = "Bringt 3 gewaltige Thoriumstreitäxte und die Handwerksverfügung für die gewaltigen Thoriumstreitäxte zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-6020:\n\n3 gewaltige Thoriumstreitäxte.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die sind nicht halb so groß, wie ich es erwartet habe. Wie auch immer, Geschäft ist Geschäft.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9183] = {title = "Handwerksverfügung - Strahlender Reif", objective = "Bringt 3 strahlende Reifen und die Handwerksverfügung für die strahlenden Reifen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-80:\n\n3 strahlende Reifen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Ich kann es nicht fassen, dass Metz ernsthaft erwartet, dass unsere Truppen diesen minderwertigen Mist tragen, um sich gegen die eisigen Angriffe der Geißel zu verteidigen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9184] = {title = "Handwerksverfügung - Tückisches Lederstirnband", objective = "Bringt 10 tückische Lederstirnbänder und die Handwerksverfügung für die tückischen Lederstirnbänder zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-971:\n\n10 tückische Lederstirnbänder.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Ganz schön tückisch, diese Dinger...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9185] = {title = "Handwerksverfügung - Unverwüstliches Rüstungsset", objective = "Bringt 25 unverwüstliche Rüstungssets und die Handwerksverfügung für die unverwüstlichen Rüstungssets zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-448:\n\n25 unverwüstliche Rüstungssets.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Unverwüstliche Rüstungssets sind vielseitig einsetzbar, &lt;Name&gt;. Sie taugen nicht nur als zusätzliche Rüstungsschicht, sondern geben auch hervorragende Teekannenwärmer ab.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9186] = {title = "Handwerksverfügung - Tückischer Ledergürtel", objective = "Bringt 9 tückische Ledergürtel und die Handwerksverfügung für die tückischen Ledergürtel zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-736:\n\n9 tückische Ledergürtel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9187] = {title = "Handwerksverfügung - Runenverzierte Lederhose", objective = "Bringt 4 runenverzierte Lederhosen und die Handwerksverfügung für die runenverzierten Lederhosen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-8485:\n\n4 runenverzierte Lederhosen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die Druiden werden den Aufwand zu Schätzen wissen, welcher zur Herstellung dieser Hosen notwendig war. Vielen Dank, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9188] = {title = "Handwerksverfügung - Hellstoffhose", objective = "Bringt 6 Hellstoffhosen und die Handwerksverfügung für die Hellstoffhosen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-95:\n\n6 Hellstoffhosen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Bei allen guten Geistern, diese Dinger blenden mich ja fast schon! Verrückt, oder?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9189] = {title = "Lieferung an das Grabmal", objective = "Bringt die versiegelten Befehle der Sin'dorei zu Berater Sorrelon beim Grabmal in Silberwald.", description = "Ihr habt das Herz der Fürstin gerührt, obwohl es nicht mehr schlägt.\n\nIch habe Anweisungen, die zum Grabmal nach Silberwald gebracht werden müssen. Berater Sorrelon repräsentiert uns und berät dort die Verlassenen.\n\nDie kürzeste Route, wenn man von ihren fliegenden Fledermäusen absieht, ist es, Unterstadt zu verlassen und die Straße nach Süden zu nehmen. Es gibt Wegweiser, also sollte es nicht zu schwer sein, den Ort zu finden. Aber nehmt Euch in Acht, das Grabmal selbst ist eine zerfallene Gruft.\n\nDiese Verlassenen sind schon merkwürdige Kreaturen.", progress = "Seid gegrüßt, Bruder. Welche Neuigkeiten bringt Ihr?", completion = "Wie ich sehe, setzt Botschafter Sonnenleid große Hoffnungen auf Euren Aufstieg in den Rängen der Sin'dorei. Die Angelegenheit mit Lady Sylvanas war allerdings unangenehm. Macht Euch nichts daraus, &lt;Name&gt;, es war richtig von Euch, die Halskette zurückzubringen. Sie hätte Euch dankbar sein sollen, aber so ist das nun mal mit dem Adel.\n\nSolange Ihr hier seid und falls Ihr Euch entschließt, Aufträge für die Verlassenen zu übernehmen, zeigt bitte Euer bestes Benehmen. Ihr wollt doch unser neues Bündnis mit der Horde nicht gefährden, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9190] = {title = "Handwerksverfügung - Runenstoffstiefel", objective = "Bringt 8 Runenstoffstiefel und die Handwerksverfügung für die Runenstoffstiefel zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-635:\n\n8 Runenstoffstiefel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Bei Bronzebeards Bart! Ihr habt mir tatsächlich Runenstoffstiefel gebracht... Schätze, ich habe diese Wette verloren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9191] = {title = "Handwerksverfügung - Runenstofftasche", objective = "Bringt 8 Runenstofftaschen und die Handwerksverfügung für die Runenstofftaschen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-9999:\n\n8 Runenstofftaschen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Heiliger Schnürsenkel! Ist es das, was ich denke? Unsere Soldaten beschweren sich immer wieder über den Mangel an Taschen, um ihre ganze Ausrüstung zu verstauen. Einer hat sogar seine Feldrationen in seinen Backen verstaut... verdammter Nager.\n\nDas wird die Gemüter bestimmt abkühlen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9192] = {title = "Ärger in den Grubenlichtminen", objective = "Tötet 8 Gnolle der Schwarzpfoten, 6 Strauchdiebe der Schwarzpfoten und 4 Schamanen der Schwarzpfoten. Kehrt anschließend zu Todespirscher Maltendis in Tristessa in den Geisterlanden zurück.", description = "Die Grubenlichtminen im Südwesten wurden von einem Gnollklan, der sich die Schwarzpfoten nennt, überrannt. Ich muss Euch sicherlich nicht daran erinnern, wie wichtig diese Minen in strategischer Hinsicht für unseren fortwährenden Schlachtzug in den Geisterlanden sind!\n\nNehmt die Straße, die nach Süden führt, und haltet Euch rechts an der Wegzweigung. Kurz nach dem Ziggurat zur Rechten kommt ein kurzer Trampelpfad Richtung Westen. Folgt ihm.\n\nWir brauchen das Erz!", progress = nil, completion = "Da habt Ihr mal ordentlich Blut fließen lassen, &lt;Klasse&gt;. Die Minenarbeiter können jetzt wieder an die Arbeit. Sie sind sicher enttäuscht, dass ihre Pause jetzt vorbei ist, aber wir brauchen nun mal mehr Erz, um Rüstungen und Waffen herzustellen.\n\nHier, nehmt dies als Lohn für Eure pflichtbewusste Tat. Lasst Rüstung und Waffen reparieren und trinkt einen auf mich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9193] = {title = "Untersucht die Amanikatakomben", objective = "Untersucht die Amanikatakomben und verbrennt 10 mumifizierte Trollüberreste. Kehrt anschließend zu Beraterin Valwyn in Tristessa in den Geisterlanden zurück.", description = "<Klasse>, wir haben aus zuverlässigen Quellen erfahren, dass die Trolle, die in den Amanikatakomben innerhalb des Sonnenhügels begraben wurden, wieder von den Toten auferstanden sind. Dame Auriferous möchte, dass Ihr die Katakomben untersucht und dass Ihr alle leblosen Überreste, die Ihr dort auffindet, verbrennt. Die Auferstehung weiterer Kreaturen soll dadurch verhindert werden.\n\nIhr kommt am schnellsten dorthin, wenn Ihr Richtung Norden reist und dann die erste Abzweigung nach rechts nehmt. Somit gelangt Ihr auf die Nordseite des Hügels, seht Richtung Süden nach dem Eingang.", progress = "Das ist eine äußerst makabere und würdelose Angelegenheit, <Klasse>. Ich kann Euch doch vertrauen, dass Ihr diesen Auftrag zur vollsten Zufriedenheit von Mylady erfüllt?", completion = "Abscheulich, aber glaubt mir, es war notwendig. Ihr habt uns einen großen Dienst mit Euren Nachforschungen erwiesen, &lt;Klasse&gt;. Bitte, nehmt dies als Zeichen unserer Großzügigkeit und Anerkennung an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9194] = {title = "Handwerksverfügung - Runenstoffrobe", objective = "Bringt 8 Runenstoffroben und die Handwerksverfügung für die Runenstoffroben zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-7229:\n\n8 Runenstoffroben.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Das war doch völlig unnötig! Nein wirklich, wer hat sich das denn einfallen lassen? Keiner von uns wird ernsthaft beim Sturm auf Naxxramas eine Robe tragen wollen. Was hat Metz sich bloß dabei gedacht?\n\n&lt;Rottenkommandant Stonebruiser seufzt.&gt;\n\nBah, nur wieder eine weitere Ladung unnützes Zeug, das ich an die Front schaffen muss.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9195] = {title = "Handwerksverfügung - Goblinpioniersprengladung", objective = "Bringt 20 Goblinpioniersprengladungen und die Handwerksverfügung für die Goblinpioniersprengladungen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-11:\n\n20 Goblinpioniersprengladungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9196] = {title = "Handwerksverfügung - Thoriumgranate", objective = "Bringt 20 Thoriumgranaten und die Handwerksverfügung für die Thoriumgranaten zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-7:\n\n20 Thoriumgranaten.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die Herstellung dieser Dinger muss ganz schön kostspielig gewesen sein. Hab ich Recht, &lt;Name&gt;?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9197] = {title = "Handwerksverfügung - Gnomenkampfhuhn", objective = "Bringt 4 Gnomenkampfhühner und die Handwerksverfügung für die Gnomenkampfhühner zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-0:\n\n4 Gnomenkampfhühner.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9198] = {title = "Handwerksverfügung - Thoriumröhre", objective = "Bringt 14 Thoriumröhren und die Handwerksverfügung für die Thoriumröhren zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-558:\n\n14 Thoriumröhren.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Thoriumröhren? Wow, danke.\n\n&lt;Rottenkommandant Stonebruiser wirft den Stapel Thoriumröhren auf einen der vielen Schrotthaufen.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9199] = {title = "Trolljuju", objective = "Sammelt 8 Trolljuju und bringt sie zu Todespirscher Maltendis in Tristessa in den Geisterlanden.", description = "Die Körper der Trolle, die in den Amanikatakomben begraben wurden, sind wieder von den Toten auferstanden! Ich möchte, dass Ihr dorthin geht und mir einen Beweis für ihren endgültigen Tod bringt. Manche dieser Trollmumien, sowie ihre lebendigen Artgenossen, tragen Juju bei sich. Es handelt sich dabei um leuchtende Objekte, denen eine unbekannte Macht innewohnt. Wahrscheinlich ist es das, was sie am Leben erhält!\n\nDie Katakomben liegen im Sonnenhügel, direkt Richtung Osten. Man sagte mir, dass der einfachste Weg hinein an der Nordwand des Hügels liegt. Seht Euch dort um, <Klasse>!", progress = "Ich muss Euch wohl nicht erst sagen, dass wir uns diesen Ärger mit den von den Toten auferstandenen Trollen hier bei uns kaum leisten können! Wir haben schon genug Probleme mit der Todesfestung im Süden!", completion = "Mumien, die von den Trollpriestern wiedererweckt werden... clever! Die Waldschattentrolle wollen ihre Reihen wohl mit Hilfe nekromantischer Mittel verstärken. Ich wette, dass diese Orakel das Juju bei ihrem Wiedererweckungsritual verwendet haben.\n\nIhr habt Eure Pflicht wieder einmal so erfüllt, wie es sich für einen &lt;Klasse&gt; mit mehr und mehr Ansehen geziemt. Nehmt diesen Lohn als Dank.", rewards = "Faulende HandlappenHandschuhe des TotengräbersMaltendis' HandschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9200] = {title = "Handwerksverfügung - Erheblicher Manatrank", objective = "Bringt 10 erhebliche Manatränke und die Handwerksverfügung für die erheblichen Manatränke zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-473:\n\n10 erhebliche Manatränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die Nützlichkeit hiervon steht wohl außer Frage.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9201] = {title = "Handwerksverfügung - Großer Arkanschutztrank", objective = "Bringt 15 große Arkanschutztränke und die Handwerksverfügung für die großen Arkanschutztränke zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-1420:\n\n15 große Arkanschutztränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "&lt;Rottenkommandant Stonebruiser öffnet einen der großen Arkanschutztränke und nimmt einen kräftigen Schluck.&gt;\n\nWooohooo! Das geht richtig ab, Baby! Aber richtig!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9202] = {title = "Handwerksverfügung - Erheblicher Heiltrank", objective = "Bringt 20 erhebliche Heiltränke und die Handwerksverfügung für die erheblichen Heiltränke zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-169110:\n\n20 erhebliche Heiltränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Wisst Ihr wie die hier von den Truppen an der Front genannt werden? Priester in der Flasche...\n\n&lt;Rottenkommandant Stonebruiser singt.&gt;\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWas glotzt Ihr so Junge? Der Titel war hier monatelang auf Platz Eins!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9203] = {title = "Handwerksverfügung - Trank der Versteinerung", objective = "Bringt 1 Trank der Versteinerung und die Handwerksverfügung für den Trank der Versteinerung zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-90:\n\n1 Trank der Versteinerung.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9204] = {title = "Handwerksverfügung - Steinschuppenaal", objective = "Bringt 40 Steinschuppenaale und die Handwerksverfügung für die Steinschuppenaale zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-5:\n\n40 Steinschuppenaale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Hier hättet hierfür eine andere Verwendung gehabt, nicht wahr? Nun ja, dem Ganzen nachzuweinen hilft auch nicht mehr, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9205] = {title = "Handwerksverfügung - Panzerfisch", objective = "Bringt 30 Panzerfische und die Handwerksverfügung für die Panzerfische zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-12:\n\n30 Panzerfische.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Ihr wisst wirklich nicht, wofür man die hier braucht?\n\n&lt;Rottenkommandant Stonebruiser lacht.&gt;\n\nAls ob ich Euch das verraten würde!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9206] = {title = "Handwerksverfügung - Zitteraal", objective = "Bringt 30 Zitteraale und die Handwerksverfügung für die Zitteraale zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-9:\n\n30 Zitteraale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Aus denen macht man die besten Aalröllchen in der ganzen Welt. Richtig gehört - IN DER GANZEN WELT.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des KreuzzugsInsigne der Dämmerung"}
MultiLanguageQuestData['de'][9207] = {title = "Grubenlichterzproben", objective = "Sammelt 6 Einheiten Grubenlichterz und bringt sie zu Magister Quallestis beim Sanktum der Sonne in den Geisterlanden.", description = "Ich wurde vom Sanktum der Sonne hierher geschickt, um ein paar Erzproben zu sammeln, aber die Gnolle haben diesen Ort überrannt! Mein Kopf wird noch auf dem Präsentierteller landen, wenn ich diese Proben nicht bald zum Magister bringe. Vielleicht könnt Ihr mir helfen, <Klasse>?\n\nIhr findet das Erz in den Zinn- und Kupfervorkommen, aber auch die Gnolle tragen es mit sich herum. Sobald Ihr genug habt, bringt Ihr es zu Magister Quallestis beim Sanktum der Sonne, direkt östlich von hier. Überquert die Todesschneise, das Sanktum liegt genau südlich vom Sonnenhügel.", progress = "Wie kann ich Euch helfen, <Klasse>?", completion = "Mein Lehrling konnte sich nicht selbst um diese Angelegenheit kümmern? Ich werde noch ein Wörtchen mit ihr zu reden haben, sobald sie wieder da ist, Gnolle hin oder her. Außerdem, warum ist sie nicht mit Euch zurückgekommen?\n\n&lt;Der Magister seufzt.&gt;\n\nSie ist eine schwierige Persönlichkeit und ihre Ausbildung wird mir noch helle Freude bereiten. Danke, dass Ihr mir diese Proben gebracht habt, &lt;Klasse&gt;. Wir hoffen ein paar spezielle Eigenschaften darin zu entdecken, die uns im Kampf gegen die Geißel von Nutzen sein können.\n\nBitte nehmt diesen Lohn als Zeichen meiner Wertschätzung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9208] = {title = "Der Greuelwächter - Arkanum des Schutzes", objective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Schutzes.", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGreuelwächter"}
MultiLanguageQuestData['de'][9209] = {title = "Der Greuelwächter - Arkanum der Schnelligkeit", objective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum der Schnelligkeit.", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGreuelwächter"}
MultiLanguageQuestData['de'][9210] = {title = "Der Greuelwächter - Arkanum des Fokus", objective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Fokus.", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", progress = "Habt Ihr das Arkanum?", completion = "Die wertlose Magie in diesen Verzauberungen verstärkt meinen Ärger. Mein Zorn gibt mir Stärke.\n\nBringt mir mehr davon und Ihr werdet einen weiteren Greuelwächter erhalten.", rewards = "Ihr bekommt:\n\nGreuelwächter"}
MultiLanguageQuestData['de'][9211] = {title = "Der Eiswächter", objective = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", description = "Ah, der Eiswächter. Es ist ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Eiswächter verleiht jenen, die gegen Kreaturen von Frost und Eis kämpfen, erhöhten Schutz vor deren Angriffen.\n\nWie bei allem anderen auch, das vom Zornwirker hergestellt wird, so hat auch dieses Stück seinen Preis - einen Preis, der nicht diskutiert werden kann, wie viel Ihr Euch auch beklagen mögt. Interesse?", progress = "Wäre es nicht für diese Argentumwachen, so wärt Ihr bereits ein Fleck auf diesem Boden.", completion = "&lt;Mataus steckt das Gold in seine Taschen.&gt;\n\nViel Spaß mit den Reparaturkoten, &lt;Volk&gt;. Naxxramas geht recht 'lieblos' mit Außenstehenden um.", rewards = "Ihr bekommt:\n\nEiswächter"}
MultiLanguageQuestData['de'][9212] = {title = "Flucht aus den Katakomben", objective = "Begleitet Waldläuferin Lilatha zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", description = "Sehe ich so verängstigt aus, wie ich mich fühle? Diese Trolle haben mich aus dem Hinterhalt überfallen und in diesem Käfig gefangen gehalten. Ich glaube, sie wollen mich opfern! Helft mir von hier zu fliehen!\n\nDas Schloss des Käfigs ist nicht allzu kompliziert... Ich kann es von dieser Seite nur nicht erreichen. Befreit mich und geleitet mich zurück zur Enklave der Weltenwanderer. Ich bin mir sicher, dass Hauptmann Helios Euch dafür entlohnen wird, außerdem wäre ich Euch für immer dankbar!", progress = nil, completion = "Ihr seid ein ziemlicher Held, &lt;Klasse&gt;, sie da lebend herausbekommen zu haben. Ich denke wir müssen einen Gegenschlag planen, um diese Katakomben auszuräuchern. Als wenn wir nicht schon genug Ärger mit den lebenden Trollen hätten!\n\nIhr habt heute außerordentlich gute Arbeit geleistet, Ihr verdient eine Belohnung. Sucht Euch etwas aus.", rewards = "TrollkickerTrollkickerTrollkickerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9213] = {title = "Der Schattenwächter", objective = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", description = "Das Machwerk eines Genies! Wie beim Eiswächter, ist es auch beim Schattenwächter ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Schattenwächter wird Euch genauso wie der Eiswächter einen guten Batzen Geld kosten.\n\n<Mataus streckt seine Hand aus und reibt seine Finger aneinander.>\n\nInteresse?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchattenwächter"}
MultiLanguageQuestData['de'][9214] = {title = "Das Arsenal der Waldschattentrolle", objective = "Sammelt 3 Kopfjägeräxte, 3 Schattenzauberstreitkolben, 3 Klauen eines Pantherlords und 3 Verhexerstäbe. Bringt sie zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", description = "<Klasse>, ich möchte, dass Ihr so viele Waldschattentrolle wie möglich erledigt. Wir müssen ihre Reihen so weit wie möglich ausdünnen, bevor wir uns der Todesfestung zuwenden können. Und wenn Ihr schon mal dabei seid, sollten wir gleich zwei Fliegen mit einer Klappe schlagen! Bringt einfach sämtliche Waffen mit, die Ihr bei den Trollen findet. Es wäre eine Verschwendung sie zusammen mit den Trollen verrotten zu lassen und wir könnten sie im Kampf gegen die Geißel einsetzen.\n\nErledigt ihre Lager im Osten und Süden bei Zeb'Tela und Zeb'Nowa.", progress = "Habt Ihr die Waffen beschafft? Sobald wir die Reihen der Waldschattentrolle dezimiert haben, können wir uns wieder dem Kampf gegen die Geißel widmen.", completion = "Ich werde umgehend einige Waldläufer entsenden, um den Schaden, den Ihr unter den Waldschattentrollen angerichtet habt, zu begutachten. Wenn die von Euch mitgebrachte Waffensammlung auch nur ansatzweise den Erfolg Eures Angriffs gegen die Trolle widerspiegelt, sollten wir mit den Überlebenden leichtes Spiel haben. Das wird uns einen baldigen Angriff auf die Geißel ermöglichen.\n\nHier, nehmt diese Münze als Zeichen meiner Dankbarkeit, das schafft wieder etwas Platz in meinem Geldbeutel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9215] = {title = "Bringt mir Kel'gashs Kopf!", objective = "Bringt den Kopf von Kel'gash dem Boshaften zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", description = "GESUCHT: Bringt den Kopf von Kel'gash dem Boshaften, Häuptling der Waldschattentrolle, zu Hauptmann Helios. Die Wahl der Mittel steht frei. Kel'gash soll sich irgendwo im Süden, in Zeb'Nowa, herumtreiben.\n\n\n\nBELOHNUNG: Ja, aber nicht im Voraus!", progress = "Was ist das für ein widerlicher Gestank?", completion = "Ah, Kel'gashs Kopf ist der Quell dieses wundervollen Aromas. Ihr habt offensichtlich ganze Arbeit geleistet, &lt;Klasse&gt;!\n\nDer Tod ihres Anführers hat die Waldschattentrolle ins Chaos gestürzt. Berücksichtigt man jetzt noch Eure letzten Einsätze zur Dezimierung ihrer Anzahl, denke ich, dass jetzt der Zeitpunkt für unsere Gegenoffensive gekommen ist, um sie ein für alle Mal zu vernichten.\n\nIhr habt meinen Dank, &lt;Name&gt;. Kann ich Euch vielleicht für einen dieser Gegenstände begeistern?", rewards = "Gut ausgearbeiteter LangbogenGut geschmiedetes SchwertGut ausgearbeiteter StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9216] = {title = "Faulende Herzen", objective = "Bringt 10 faulende Herzen zu Magistrix Aminel in Tristessa.", description = "Ich habe gehört, dass die Amanitrolle die Herzen ihrer Feinde essen, um deren Stärke zu stehlen. Sie könnten etwas im Schilde führen, <Name>. Bereitet man sie richtig auf, kann man aus den Herzen der Untoten mächtige Elixiere gewinnen.\n\nJagt die Zombies in der Todesschneise und bringt mir ihre Herzen. Ich werde Euch die Art von Verstärkung zeigen, die wir Euren körperlichen Fähigkeiten im Kampf gegen die Untoten verleihen können.", progress = "Habt Ihr die Zombieherzen, nach denen ich verlangt habe, <Name>?", completion = "Nehmt dieses Gebräu, &lt;Name&gt;. Sobald Ihr es getrunken habt, erfährt Eure körperliche Stärke im Kampf gegen die Geißel einen Schub. Wenn Ihr noch mehr von dieser Probe brauchen solltet, bringt mir mehr Herzen.", rewards = "Ihr bekommt:\n\nGebräu des Geißelbanns"}
MultiLanguageQuestData['de'][9217] = {title = "Mehr faulende Herzen", objective = "Habt Ihr mir noch mehr Zombieherzen gebracht? Ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt, <Name>.", description = nil, progress = "Habt Ihr mir noch mehr Zombieherzen gebracht? Ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt, <Name>.", completion = "Dies wird Euch mit mehr Stärke im Kampf gegen die Geißel versorgen. Bringt mir mehr Herzen, falls Ihr welche findet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGebräu des Geißelbanns"}
MultiLanguageQuestData['de'][9218] = {title = "Wirbelknochenstaub", objective = "Bringt 10 Einheiten Wirbelknochenstaub zu Magistrix Aminel in Tristessa.", description = "Die dunklen Energien, welche durch die Körper reanimierter Skelette fließen, reichern sich hauptsächlich in ihrer Wirbelsäule an. Ich habe eine Methode entdeckt, dank der man diese Energie in einen Trank mischen kann, der unsere magischen Fähigkeiten im Kampf gegen die Untoten verstärkt.\n\nBringt mir ein paar Einheiten Wirbelknochenstaub und ich werde Euch gerne eine Probe von dem Trank abgeben. Ihr könnt zahlreiche Skelette in der Todesschneise finden, westlich von hier.", progress = "Habt Ihr die Proben, nach denen ich verlangt habe, <Name>?", completion = "Hier, für Euch, &lt;Name&gt;. Ihr werdet den Unterschied sofort spüren!\n\nIhr könnt mir jeder Zeit mehr Wirbelknochenstaub bringen, ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt. Nebenwirkungen? Naja, Eure Stimme klingt ein bisschen höher, aber das sind lediglich die Rückstände des Staubs die verrückt spielen.", rewards = "Ihr bekommt:\n\nMacht des Geißelbanns"}
MultiLanguageQuestData['de'][9219] = {title = "Mehr Wirbelknochenstaub", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMacht des Geißelbanns"}
MultiLanguageQuestData['de'][9220] = {title = "Krieg gegen die Todesfestung", objective = "Tötet in der Todesfestung 5 Augen von Dar'khan, 6 nerubische Zenturio und 6 Wehklagende und kehrt anschließend zu Magister Idonis beim Sanktum der Sonne in den Geisterlanden zurück.", description = "Wenn Ihr unserer Sache dienen wollt, gibt es keinen besseren Ort und keinen idealeren Zeitpunkt, als das Hier und Jetzt.\n\nMit dem Wiederaufbau des Sanktums der Sonne haben wir das Banner des Widerstandes im Angesicht der Thronfeste unseres Feindes gehisst, kurz vor den Toren der Todesfestung.\n\nGeht und tötet die Horden der Untoten, die diesen finsteren Hort der Geißel bewohnen.", progress = nil, completion = "Die Geißel hat unsere Rache vernommen, &lt;Name&gt;. Nicht mehr lange und ihre verfluchte Zitadelle wird in Trümmern liegen.\n\nJetzt, da sie geschwächt sind, ist es an der Zeit, strategisch günstige Ziele anzugreifen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9221] = {title = "Überragende Kampfausrüstung - Freund der Dämmerung", objective = "Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Verimondes letzter AuswegGeweihter LederhelmGamaschen des SeuchenjägersAuf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVorratstasche"}
MultiLanguageQuestData['de'][9222] = {title = "Epische Kampfausrüstung - Freund der Dämmerung", objective = "Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Der LäutererArmschienen der HoffnungArmschienen der TäuschungAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungMedaillon der DämmerungTalisman der Überlegenheit"}
MultiLanguageQuestData['de'][9223] = {title = "Überragende Kampfausrüstung - Wohlwollen der Dämmerung", objective = "Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem ziemlich unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Verimondes letzter AuswegGeweihter LederhelmGamaschen des SeuchenjägersAuf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVorratstasche"}
MultiLanguageQuestData['de'][9224] = {title = "Epische Kampfausrüstung - Wohlwollen der Dämmerung", objective = "Für 75 Insignien der Dämmerung und 75 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem extrem unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Der LäutererArmschienen der HoffnungArmschienen der TäuschungAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungMedaillon der DämmerungTalisman der Überlegenheit"}
MultiLanguageQuestData['de'][9225] = {title = "Epische Kampfausrüstung - Respekt der Dämmerung", objective = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen respektvollen Ruf genießt, muss für epische Gegenstände noch immer einen sehr hohen Preis bezahlen. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Der LäutererArmschienen der HoffnungArmschienen der TäuschungAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungMedaillon der DämmerungTalisman der Überlegenheit"}
MultiLanguageQuestData['de'][9226] = {title = "Überragende Kampfausrüstung - Respekt der Dämmerung", objective = "Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen respektvollen Ruf genießt, kann Gegenstände zu einem recht angemessenem Preis erwerben. Ich würde Euch zu einem Geschäft raten!", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, &lt;Name&gt;. Es war ein Vergnügen mit Euch Geschäfte zu machen.", rewards = "Verimondes letzter AuswegGeweihter LederhelmGamaschen des SeuchenjägersAuf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVorratstasche"}
MultiLanguageQuestData['de'][9227] = {title = "Überragende Kampfausrüstung - Ehrfurcht der Dämmerung", objective = "Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen einen Preisnachlass. Ich würde Euch zu einem Geschäft raten!", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, &lt;Name&gt;. Es war ein Vergnügen mit Euch Geschäfte zu machen.", rewards = "Verimondes letzter AuswegGeweihter LederhelmGamaschen des SeuchenjägersAuf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVorratstasche"}
MultiLanguageQuestData['de'][9228] = {title = "Epische Kampfausrüstung - Ehrfurcht der Dämmerung", objective = "Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass. Ich würde Euch zu einem Geschäft raten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Der LäutererArmschienen der HoffnungArmschienen der TäuschungAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungMedaillon der DämmerungTalisman der Überlegenheit"}
MultiLanguageQuestData['de'][9229] = {title = "Ramaladnis Schicksal", objective = "Betretet Naxxramas und bringt Ramaladnis Schicksal in Erfahrung.", description = "Ramaladni war ein Krieger der Bruderschaft; er war ein Schüler von Hochlord Mograine bevor die Dämmerung überhaupt existierte! Als ihn die Nachricht von Mograines Tod erreichte, wurde er von Wut und Hass überwältigt.\n\nVersteht bitte, <Name>, wenn Wut und der Drang nach Vergeltung von jemandem Besitz ergreifen, hört er auf, ein Mensch zu sein, und wird stattdessen zur Verkörperung der Emotionen, die ihn beherrschen. Und so geschah es, dass Ramaladni, beseelt vom Geist der Vergeltung, Naxxramas betrat um Rache zu üben... und niemals zurückkehrte.\n\nBetretet Naxxramas und findet heraus, was mit Ramaladni geschah.", progress = "Gibt es Neuigkeiten über Ramaladni?", completion = "Es ist sein Ring! Aber er ist zerstört. Ihr habt keine weiteren Hinweise auf Ramaladni gefunden?\n\n&lt;Korfax verzieht das Gesicht.&gt;\n\nDas verheißt nichts Gutes für Ramaladni. Der Ring jedoch ... er könnte noch nützlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9230] = {title = "Ramaladnis eisiger Griff", objective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt.", description = "Den Ring wiederherzustellen, scheint eine ziemliche Herausforderung zu sein, <Name>. Seht ihr, er wurde hergestellt aus Runen, die sich in Bauwerken der Geißel finden - in Bauwerken wie Naxxramas. Es könnten noch weitere Materialien gebraucht werden, aber Eure Hauptsorge sollte es sein, diese gefrorenen Runen zu beschaffen. Ich kann dem Ring seinen alten Glanz zurückgeben, wenn ihr mir bringt, was ich dazu benötige.", progress = "Gefrorene Runen findet man wahrscheinlich in Naxxramas.", completion = "Ramaladni selbst könnte es nicht besser gemacht haben! Hier ist der Ring, wie versprochen.", rewards = "Ihr bekommt:\n\nRamaladnis eisiger Griff"}
MultiLanguageQuestData['de'][9232] = {title = "Das Einzige, das ich kann...", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.", description = "Ihr haltet Euch für einen Helden der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?\n\n<Wilhelm seufzt.>\n\nPah, was für eine Wahl habe ich denn? Ihr seid das Beste, das ich zur Verfügung habe; warum sollte ich Euch nicht helfen?\n\nOmarion hat mir einen Plan hinterlassen. Es ist das Einzige, das ich kann... Ich kann ein paar Varianten dieser Hosen herstellen, Ihr müsst mich nur mit den Materialien versorgen.", progress = "Ihr habt nicht zufällig Omarion getroffen?", completion = "&lt;Wilhelm wischt sich den Schweiß von der Stirn.&gt;\n\nDas war ein hartes Stück Arbeit! Ich hoffe, die Hose gefällt Euch, &lt;Klasse&gt;. Zumindest werdet ihr jetzt in einer sauberen Hose sterben.", rewards = "EisfluchgamaschenGletschergamaschenPolargamaschenEisschuppengamaschen"}
MultiLanguageQuestData['de'][9233] = {title = "Omarions Leitfaden", objective = "Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Wilhelm,\n\nsolltet Ihr das hier lesen, bin ich bereits tot - endlich. Ihr sollt wissen, dass meine letzten Gedanken vor dem Tod Euch und Eurer Unfähigkeit als Handwerker galten. Unglücklicherweise besitzt der Überbringer dieses Leitfadens noch weniger Geschick als Ihr.\n\nZu dem Buch: Es beinhaltet meine letzten Anleitungen. Fertigt dem Überbringer dieses Leitfadens an, was immer dieser wünschen mag. Ich bin mir sicher, dass Ihr ein saftiges Honorar für Eure Dienste verlangen werdet, denn im Grunde seid Ihr nun mal ein Gauner.\n\nVerachtungsvoll,\n\nOmarion", progress = "Ist es das, was ich denke?\n\n<Wilhelm scheint begierig zu sein.>", completion = "Hey, der muss ja nicht ganz dicht gewesen sein, als er das geschrieben hat! Omarion und ich - wir waren die dicksten Freunde!\n\nEgal, dies hier eröffnet mit Sicherheit ein paar neue Möglichkeiten, &lt;Name&gt;. Ich kann jetzt mehr Gegenstände anfertigen - natürlich gegen eine kleine Gebühr und Kosten für das Material.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nOmarions Geheimnisse"}
MultiLanguageQuestData['de'][9234] = {title = "Eisfluchstulpen", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisfluchstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisfluchstulpen"}
MultiLanguageQuestData['de'][9235] = {title = "Eisflucharmschienen", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisflucharmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisflucharmschienen"}
MultiLanguageQuestData['de'][9236] = {title = "Eisfluchbrustplatte", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 16 Thoriumbarren, 2 Arkanitbarren, 4 Essenzen des Wassers und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisfluchbrustplatte herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisfluchbrustplatte"}
