MultiLanguageQuestData['de'][9238] = {title = "Gletscherhandschutz", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 2 Runenstoffballen, 2 Essenzen des Wassers, 2 Einheiten Eisenweberseide und 200 Gold.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, einen Gletscherhandschutz herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGletscherhandschutz"}
MultiLanguageQuestData['de'][9239] = {title = "Gletscherhandschuhe", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 4 Runenstoffballen, 4 Essenzen des Wassers, 2 Einheiten Eisenweberseide und 200 Gold.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Gletscherhandschuhe herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGletscherhandschuhe"}
MultiLanguageQuestData['de'][9240] = {title = "Gletscherweste", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 8 gefrorene Runen, 8 Runenstoffballen, 6 Essenzen des Wassers, 4 Einheiten Eisenweberseide und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, eine Gletscherweste herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGletscherweste"}
MultiLanguageQuestData['de'][9241] = {title = "Polararmschienen", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 12 Einheiten verzaubertes Leder, 3 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Polararmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPolararmschienen"}
