MultiLanguageQuestData['de'][9243] = {title = "Polartunika", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 16 Einheiten verzaubertes Leder, 5 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, eine Polartunika herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPolartunika"}
MultiLanguageQuestData['de'][9244] = {title = "Eisschuppenarmschienen", objective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisschuppenarmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisschuppenarmschienen"}
MultiLanguageQuestData['de'][9245] = {title = "Eisschuppenstulpen", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisschuppenstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisschuppenstulpen"}
MultiLanguageQuestData['de'][9246] = {title = "Eisschuppenbrustplatte", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 8 gefrorene Runen, 24 schwere Skorpidschuppen, 7 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisschuppenbrustplatte herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisschuppenbrustplatte"}
MultiLanguageQuestData['de'][9247] = {title = "Der Ruf des Bewahrers", objective = "Bringt den Brief vom Bewahrer der Schriften zu ihm, in die Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "<Name>,\n\nIn der Vergangenheit habt Ihr die Interessen der Argentumdämmerung nach bestem Gewissen und Können gewahrt. In einer Zeit der größten Not, ertönt wieder einmal der Ruf zu den Waffen.\n\n<Name>, solltet Ihr uns unterstützen wollen, meldet Euch bitte bei dem Bewahrer der Schriften an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "Ah, <Name>, es ist schön Euch zu sehen.", completion = "Schon dadurch, dass Ihr unseren Ruf beantwortet habt, stehen wir in Eurer Schuld, &lt;Name&gt;. Die Argentumdämmerung ist sich sicher, dass Euer leuchtendes Beispiel auch den anderen Kämpfern gezeigt hat, wie man die Geißel zurückwirft!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9248] = {title = "Eine bescheidene Darbringung", objective = "Aurel Goldblatt auf Burg Cenarius in Silithus möchte, dass Ihr ihr 1 abyssisches Szepter bringt. Euer Ruf bei dem Zirkel des Cenarius muss außerdem wohlwollend sein.", description = "Ishnu-alah, <Volk>. Bringt mir den Beweis für den Tod eines Lords des Abyssischen Rates und ich werde Euch mit einem Gegenstand entlohnen, der Euch bei Euren Kämpfen gegen die Qiraji von großem Nutzen sein wird.", progress = "Fandu-dath-belore? Oh, verzeiht, <Name>. Ich habe Euch nicht erkannt. Habt Ihr das Szepter?", completion = "Ande'thoras-ethil. In meiner Muttersprache bedeutet das so viel wie 'Mögen sich Eure Schwierigkeiten verringern'.\n\nTragt das Band mit Stolz und gebt auf Euch Acht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBand des Cenarius"}
MultiLanguageQuestData['de'][9249] = {title = "40 Lose - Bauplan: Dampfpanzersteuerung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBauplan: Dampfpanzersteuerung"}
MultiLanguageQuestData['de'][9250] = {title = "Grundstab von Atiesh", objective = "Findet jemanden, der Euch dabei hilft, die letzten beiden Teile des Stabs zu finden und das Böse daraus zu vertreiben.", description = "Mit dem Grundstab ist bereits der wichtigste Teil von Atiesh vervollständigt worden. Es fehlen lediglich noch Stabkopf und -fuß. Außerdem gibt es noch ein kleineres Problem bezüglich des Stabs und seiner Rolle hinsichtlich Sargeras' Lenkung zum Bösen.\n\nFindet jemanden, der Euch beim Aufspüren der noch fehlenden Teile und beim Austreiben alles Verderbten aus dem Hohestab zur Seite steht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9251] = {title = "Atiesh, der korrumpierte Hohestab", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte den Stabkopf und -fuß von Atiesh.", description = "Ihr fragt Euch, warum Ihr noch immer am Leben seid? Schließlich haltet Ihr einen Gegenstand in Euren Händen, der vom Bösen erfüllt ist. Die Antwort ist nicht eindeutig, <Name>. Ich tue nur, was ich tun muss.\n\nKel'Thuzad sitzt auf seinem Thron hoch oben in Naxxramas, konspiriert... Er sucht was Ihr besitzt und besitzt was Ihr sucht.\n\nWas den Stabfuß angeht, er wurde von dem Zwerg, Brann Bronzebart, gehalten, als er Ahn'Qiraj betrat. Er hat Ahn'Qiraj zwar verlassen, den Stabfuß von Atiesh jedoch zurückgelassen.\n\nSolltet Ihr beim Wiedererlangen der Stücke Erfolg haben, kehrt mit ihnen zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9252] = {title = "Die Verteidigung von Morgenluft", objective = "Tötet 4 Moderknochenmarodeure und 4 dunkle Gespenster. Kehrt anschließend zu Waldläuferin Sareyn in Morgenluft im Immersangwald zurück.", description = "Die Zahl der Angriffe durch Truppen der Geißel hat merklich zugenommen, <Name>. Unsere Verteidigung hält gerade noch so stand und Verstärkung aus Silbermond ist nicht in Sicht. Reicht uns eine helfende Hand und unterstützt uns bei der Verteidigung des Dorfes. Zieht aus und erledigt einige der Untoten, die durch die Todesschneise wandeln.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Es ist eine undankbare Aufgabe, der wir hier nachgehen, doch Eure heutige Mithilfe hat sie ein wenig einfacher gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9253] = {title = "Runenwächter Deryan", objective = "Sprecht mit Runenwächter Deryan im Immersangwald nahe der Grenze zu den Geisterlanden.", description = "Die zunehmenden Angriffe der Geißel lassen mich vermuten, dass einer der schützenden Runensteine an der Grenze zu den Geisterlanden eine Fehlfunktion erlitten hat.\n\nWir nutzten diese uralten Runensteine, um uns vor den Untoten zu beschützen. Die meisten wurden jedoch zerstört oder gingen nach dem Angriff auf den Sonnenbrunnen verloren.\n\nFolgt der Straße nach Süden, in Richtung der Geisterlande, und sucht auf der westlichen Seite nach einem kleinen Pfad. Ihr findet Runenwächter Deryan bei einem der nahegelegenen Runensteine; er wird wissen, ob etwas schief gelaufen ist.", progress = nil, completion = "Jemand aus Morgenluft muss Euch zu mir geschickt haben. Ich wusste doch, dass es nur eine Frage der Zeit war, bevor Hilfe eintrifft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9254] = {title = "Der eigensinnige Lehrling", objective = "Sprecht mit Lehrling Mirveda beim Sanktum des Ostens im Immersangwald.", description = "Vielen Dank für Eure Hilfe, <Name>. Während ich versuchen werde, hier wieder für Ordnung zu sorgen, möchte ich Euch um einen Gefallen bitten. Eine meiner ehemaligen Lehrlinge hat sich aufgemacht, um sehr gefährlichen Untersuchungen nachzugehen. Sie reiste zum Sanktum des Ostens, inmitten der Todesschneise.\n\nIch sorge mich um ihr Wohlergehen. Bitte versucht sie zu finden und bringt sie wieder zur Vernunft.", progress = nil, completion = "Es rührt mich, dass meine ehemalige Mentorin nach mir sehen lässt. Es ist nur traurig, dass sie seit langer Zeit kein Vertrauen mehr in meine Arbeit hat.\n\nIhr verschwendet Eure Zeit, Ihr könnt mich nicht überreden zu ihr zurückzugehen. Entweder helft Ihr mir mit meinen Untersuchungen hier oder Ihr geht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9255] = {title = "Forschungsnotizen", objective = "Bringt die Forschungsnotizen zu Magistrix Landra Morgenwandler in Morgenluft im Immersangwald.", description = "Wie entmutigend meine Forschungsergebnisse auch sein mögen, so enthalten sie doch wertvolle Informationen. Ein Magister muss sich meine Arbeit ansehen, bevor wir ernsthaft etwas unternehmen. Bitte, nehmt diese Notizen zu Magistrix Landra Morgenwandler in Morgenluft, westlich von hier.", progress = "Habt Ihr etwas für mich?", completion = "Diese Notizen... es ist schockierend. Wenn das stimmt, dann ist der Schaden, den das Land entlang der Todesschneise erlitten hat, nicht wiedergutzumachen.\n\nIch werde dem Großmagister sofort Bescheid sagen. Ein weiterer Grund für unser Volk, dieser Welt zu entfliehen und sein wahres Schicksal in der Scherbenwelt zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9256] = {title = "Morgenluft", objective = "Sprecht mit Waldläufer Degolien in Morgenluft im Immersangwald.", description = "Ich habe noch eine Aufgabe für Euch, <Name>. Waldläufer Degolien wurde nach Morgenluft entsandt, um mehr über einen Angriff getriebener Blutelfen auf eine nahegelegene Werft herauszufinden. Er hat um Verstärkung gebeten, die wir ihm leider noch nicht geben können. Sucht ihn auf und unterstützt ihn so gut Ihr könnt.\n\nIhr kommt nach Morgenluft, indem Ihr der Straße folgt, die vom Falkenplatz hinaus Richtung Süden führt. Viel Glück, <Name>.", progress = nil, completion = "Danke, dass Ihr gekommen seid, &lt;Name&gt;. Es steht um einiges schlechter, als wir angenommen hatten. Die Getriebenen haben den Ankerplatz der Sonnensegel bereits gänzlich eingenommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9257] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"}
MultiLanguageQuestData['de'][9258] = {title = "Der Versengte Hain", objective = "Findet Larianna Flusswind nahe des Versengten Hains, südwestlich des Immersangwalds.", description = "Ein fauler Moder der Verderbnis, welcher die Erde durchzieht, geht der Ausbreitung der Geißel voraus. Daher haben wir schützende Runensteine entlang der Grenze zu den Geisterlanden erbaut, die das Land gegen diese Seuche beschützen sollen.\n\nDer westlichste Runenstein wurde während eines Angriffs der Geißel zerstört, was uns dazu zwang, das umgebende Gebiet vollständig niederzubrennen, um die weitere Ausbreitung der Verderbnis aufzuhalten.\n\nMeine Schwester, Larianna Flusswind, bewacht den Versengten Hain. Geht und findet sie; möglicherweise hat sie Arbeit für Euch.", progress = nil, completion = "Ah, mein Bruder hat Euch geschickt. Es gibt da etwas, wobei ich Eure Hilfe gebrauchen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9259] = {title = "Verrat am Blutsegel", objective = "Revilgaz, dieser räudige Hund, hat allen ehemaligen Blutsegelbukanieren Begnadigung angeboten, die bereit sind, sich gegen ihren Käpt'n zu wenden! Diese Ratte will von mir, dass ich meine alten Kumpels umlege, und ihm die Kopftücher als Beweis bringe.\n\nDas bringe ich nicht übers Herz, und ich will auch nicht, dass Ihr es tut. Bringt mir etwas Seidenstoff und rote Farbe, dann kann ich brauchbare Fälschungen herstellen. Ich werde dem Baron sagen, dass Ihr die Seiten gewechselt habt, aber seid gewarnt: Die Blutsegler werden das nicht gut finden!", description = nil, progress = "Revilgaz, dieser räudige Hund, hat allen ehemaligen Blutsegelbukanieren Begnadigung angeboten, die bereit sind, sich gegen ihren Käpt'n zu wenden! Diese Ratte will von mir, dass ich meine alten Kumpels umlege, und ihm die Kopftücher als Beweis bringe.\n\nDas bringe ich nicht übers Herz, und ich will auch nicht, dass Ihr es tut. Bringt mir etwas Seidenstoff und rote Farbe, dann kann ich brauchbare Fälschungen herstellen. Ich werde dem Baron sagen, dass Ihr die Seiten gewechselt habt, aber seid gewarnt: Die Blutsegler werden das nicht gut finden!", completion = "Lasst uns eine Schweigeminute einlegen, um unseren gefallenen Kameraden zu gedenken.\n\n&lt;Der Verräter der Blutsegelbukaniere grinst Euch an und zwinkert.&gt;\n\nEin Verräter zu sein ist eine Sache, aber die eigenen Leute kaltzumachen - das wäre einfach verachtenswert, jawohl!", rewards = nil}
MultiLanguageQuestData['de'][9260] = {title = "Erforscht die Geißel von Sturmwind", objective = "Beschafft Euch drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Sturmwind und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Sturmwind gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9261] = {title = "Erforscht die Geißel von Eisenschmiede", objective = "Beschafft Euch drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Eisenschmiede und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Eisenschmiede gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9262] = {title = "Erforscht die Geißel von Darnassus", objective = "Beschafft Euch drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Darnassus und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Darnassus gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr bereits Nachforschungen angestellt? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9263] = {title = "Erforscht die Geißel von Orgrimmar", objective = "Beschafft Euch drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Orgrimmar und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Orgrimmar gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"}
