MultiLanguageQuestData['de'][9265] = {title = "Erforscht die Geißel von Unterstadt", objective = "Beschafft Euch drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Unterstadt und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Unterstadt gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9266] = {title = "Wiedergutmachung", objective = "Ihr müsst uns oder unseren Freunden etwas ziemlich Übles angetan haben, <Name>. Jedenfalls biete ich Euch einen Weg an, Euren guten Ruf wiederherzustellen.\n\nWie Ihr wisst, ist es ziemlich kalt in Winterquell. Da so viele von uns Goblins aus anderen Städten kommen, könnten wir etwas Hilfe gebrauchen, uns warm zu halten. Bringt mir etwas Runenstoff und Kohle, und Ich werde ein gutes Wort für Euch einlegen. Aber seid gewarnt, unsere Feinde werden es nicht gern sehen, wenn Ihr uns helft.", description = nil, progress = "Ihr müsst uns oder unseren Freunden etwas ziemlich Übles angetan haben, <Name>. Jedenfalls biete ich Euch einen Weg an, Euren guten Ruf wiederherzustellen.\n\nWie Ihr wisst, ist es ziemlich kalt in Winterquell. Da so viele von uns Goblins aus anderen Städten kommen, könnten wir etwas Hilfe gebrauchen, uns warm zu halten. Bringt mir etwas Runenstoff und Kohle, und Ich werde ein gutes Wort für Euch einlegen. Aber seid gewarnt, unsere Feinde werden es nicht gern sehen, wenn Ihr uns helft.", completion = "Habt Dank, &lt;Name&gt;. Ihr seid auf einem guten Weg, Euch in unserer schönen Stadt zu rehabilitieren.", rewards = nil}
MultiLanguageQuestData['de'][9267] = {title = "Heilen alter Wunden", objective = "Überlegt es Euch lieber zweimal, bevor Ihr Ratschet betretet, <Name>! Die Kunde von Euren schlechten Taten hat sich bereits verbreitet.\n\nIhr habt jedoch Glück, soeben ist ein Schiff eingetroffen, das viele Verwundete aus einem Kampf mit den Blutsegelbukanieren transportiert. Dies ist Eure letzte Chance, zu beweisen, dass Ihr kein totaler Schuft seid. Helft uns, indem Ihr uns Leinenstoff für Verbände und leere Phiolen für Tränke bringt.", description = nil, progress = "Überlegt es Euch lieber zweimal, bevor Ihr Ratschet betretet, <Name>! Die Kunde von Euren schlechten Taten hat sich bereits verbreitet.\n\nIhr habt jedoch Glück, soeben ist ein Schiff eingetroffen, das viele Verwundete aus einem Kampf mit den Blutsegelbukanieren transportiert. Dies ist Eure letzte Chance, zu beweisen, dass Ihr kein totaler Schuft seid. Helft uns, indem Ihr uns Leinenstoff für Verbände und leere Phiolen für Tränke bringt.", completion = "Ich bin froh, dass Ihr Eure Fehler eingesehen habt, &lt;Name&gt;. Sorgt weiter für Nachschub; so leicht werden wir Eure Taten nicht vergessen!", rewards = nil}
MultiLanguageQuestData['de'][9268] = {title = "Krieg zur See", objective = "Ihr wollt also wieder Freunde werden mit den Goblins von Tanaris, <Name>? Wir benötigen Rohstoffe für Segel und Kanonen, um unsere alten Feinde, die Blutsegelbukaniere, zu bekämpfen. Bringt mir Magiestoff und starken Fluxus, und wir werden darüber nachdenken, Eure Untaten zu vergeben.", description = nil, progress = "Ihr wollt also wieder Freunde werden mit den Goblins von Tanaris, <Name>? Wir benötigen Rohstoffe für Segel und Kanonen, um unsere alten Feinde, die Blutsegelbukaniere, zu bekämpfen. Bringt mir Magiestoff und starken Fluxus, und wir werden darüber nachdenken, Eure Untaten zu vergeben.", completion = "Sorgt weiter für Nachschub, &lt;Name&gt;. Wir Goblins vergessen nicht so schnell!", rewards = nil}
MultiLanguageQuestData['de'][9269] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"}
MultiLanguageQuestData['de'][9270] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"}
MultiLanguageQuestData['de'][9271] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"}
MultiLanguageQuestData['de'][9272] = {title = "Kleider machen Seebären", objective = "Harrr... wenn Ihr scharf 'drauf seid, Euch an der Gesellschaft von uns erfahrenen Seebären zu erfreuen, dann zieht Euch auch besser an wie ein richtiger Lump! Hier, streift 'n passenden Fetz'n über, bevor ich Euch kielholen lasse.\n\nEuch steht das Zeug sicher besser als es Rotauge Ben, dem alten Seebär, je gepasst hat. Hab' ihn bei 'nem höllischen Sturm auf See verloren.\n\nTragt's mit Stolz, Kumpel!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUniform der Bukaniere"}
MultiLanguageQuestData['de'][9273] = {title = "iCoke-Gewinngutschein einlösen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisbärenhalsband"}
MultiLanguageQuestData['de'][9274] = {title = "Geister der Ertrunkenen", objective = "Waldläufer Krenn'an aus der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr beim nahegelegenen See 8 rachsüchtige Erscheinungen und 8 ruhelose Erscheinungen tötet.", description = "Der See im Norden wird seit langer Zeit von den Geistern meiner Ahnen heimgesucht, <Name>. Die armen Seelen waren Opfer eines tragischen Unfalls, bei dem etliche von ihnen am Grund des Sees ertranken.\n\nDie Ursache dieser Geschehnisse ist längst in Vergessenheit geraten, aber ihre quälenden Schreie erinnern noch heute an ihren Fluch.\n\nFalls Ihr dazu bereit seid, möchte ich, dass Ihr zum See geht und ihrem Leiden ein Ende bereitet, <Name>. Ich wäre Euch dankbar dafür, und sie auch, da bin ich sicher.", progress = nil, completion = "Ich bin dankbar für Eure Hilfe, &lt;Name&gt;. Es schmerzt mich, die Geister meiner Ahnen in diesem jämmerlichen Zustand zu sehen. Mögen sie in Frieden ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9275] = {title = "In der Würze liegt der Tod", objective = "Vergiftet die Trollnahrungsvorräte in den Lagern von Zeb'Nowa. Kehrt anschließend zu Apotheker Venustus bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", description = "Ich wurde von den Weltenwanderern angeheuert, um ihnen bei der Lösung ihres Trollproblems behilflich zu sein. Ich denke, dass ich die Antwort auf ihr Problem parat habe.\n\nIch verfüge über eine Reihe hochwirksamer Gifte. Trolle sind lebende Wesen wie Ihr und ich, und müssen daher regelmäßig Nahrung zu sich nehmen. Wenn wir also etwas Gift unter ihr Essen mischen... nun, das Resultat dürfte sehr unterhaltsam sein!\n\nSicherlich möchtet Ihr uns zur Hand gehen, um uns die Waldschattentrolle südlich von hier, in Zeb'Nowa, vom Hals zu schaffen? Das Lager erstreckt sich über die ganze nördliche und südliche Seite der Straße nach Zul'Aman.", progress = nil, completion = "Ah, hervorragend! Ich wusste es, ein &lt;Volk&gt; war die richtige Wahl, um das Gift hinreichend zu verteilen. Mit etwas Glück werden die Waldschattentrolle schön fett, bevor sie durch die Wirkung des Gifts in den Nether eingehen. Damit dürften die Weltenwanderer ihre Ruhe haben und ich kann endlich meine wohlverdiente Heimreise nach Tristessa antreten.\n\nEs war mir eine Freude mit Euch zu Arbeiten, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9276] = {title = "Angriff auf Zeb'Tela", objective = "Tötet 8 Schattenzauberer der Waldschattentrolle und 8 Kopfjäger der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", description = "Unsere Ressourcen hier sind recht begrenzt, <Klasse>, daher ist Eure Hilfe für uns unverzichtbar. Ich wurde vom Hauptmann damit beauftragt, die regelmäßigen Störangriffe auf die Lager der Waldschattentrolle zu überwachen. Wir versuchen die Trolle so lange zu beschäftigen, bis wir genug Kräfte für eine vernichtende Offensive zusammenziehen können, um sie endgültig auszulöschen.\n\nBis dahin benötigen wir jeden Freiwilligen, der uns dabei helfen kann, die Anzahl der Waldschattentrolle zu reduzieren.\n\nDenkt Ihr, Ihr könntet nach Osten in Richtung Zeb'Tela reisen und ihnen ein wenig Schaden zufügen?", progress = nil, completion = "Gut, sehr gut! Das habt Ihr hervorragend gemeistert! Dann wollen wir doch mal sehen, ob Ihr auch der nächsten Herausforderung gewachsen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9277] = {title = "Angriff auf Zeb'Nowa", objective = "Tötet 10 Pantherlords der Waldschattentrolle und 10 Verhexer der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", description = "Es ist Zeit für eine größere Herausforderung. Zeb'Nowa, südlich von hier, beherbergt die mächtigsten Waldschattentrolle. In unserem Bestreben, die Anzahl der Trolle so klein wie möglich zu halten, erteile ich Euch den Auftrag, dorthin zu gehen und alle Euch zur Verfügung stehenden Mittel einzusetzen, um den Trollen so viel wie möglich zuzusetzen.\n\nKann ich auf Euch zählen, <Name>? Seid Ihr bereit für die Trolljagd?", progress = nil, completion = "Unglaublich! Ihr solltet Euch unbedingt mit unserem Hauptmann über einen Beitritt in die Reihen der Weltenwanderer unterhalten.\n\nNun gut, &lt;Name&gt;, Ihr habt uns die dringende Atempause zum Sammeln unserer Streitkräfte verschafft. Genau genommen scheinen unserer letzten Zählung nach nur wenige Trolle übrig zu sein! Vielleicht können wir uns nun mit den Streitkräften Tristessas vereinen, um gemeinsam die Todesfestung anzugreifen, anstatt unsere Zeit weiter mit den hiesigen Trollen zu verschwenden.\n\nIch denke, Ihr habt Euch eine kleine Belohnung verdient. Greift zu!", rewards = "WachpostenarmreifGeschmeidiger BaumwollarmreifArmschienen des WeltenwanderersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9278] = {title = "Willkommen!", objective = "Bringt den Geschenkgutschein der Azurwacht zu Jaeleil in der Azurwacht.", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Jaeleil in der Azurwacht einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][9279] = {title = "Ihr habt überlebt!", objective = "Sprecht mit Proenitus bei der Absturzstelle im Am'mental.", description = "Kümmert Euch nicht um meine Wunden, <Bruder/Schwester>. Es ist ein Wunder, dass überhaupt jemand von uns überlebt hat!\n\nIch dachte schon, Ihr wärt nicht durchgekommen; Ihr wurdet seit Wochen vermisst!\n\nEs ist etwas passiert und die Exodar ist abgestürzt. Viele ließen ihr Leben.\n\nEs ist ein Segen, dass Ihr noch unter uns weilt, <Name>! Mit Euch an unserer Seite werden wir bald wieder in Sicherheit sein! Proenitus hat mich beauftragt, Euch zu ihm zu schicken, sobald Ihr erwacht seid. Er wartet außerhalb des Schiffes, südwestlich am Fuße des Hügels auf Euch.", progress = nil, completion = "&lt;Name&gt;, bei meiner ewigen Seele, es ist gut, Euch zu sehen! Ich weiß nicht, warum die Exodar abgestürzt ist. Nur diejenigen von uns, die in diesem Teil des Schiffs waren, sind noch am Leben.\n\nUns bleibt nicht viel Zeit, wenn wir so viele wie möglich retten wollen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9280] = {title = "Wiederaufladen der Heilkristalle", objective = "Beschafft Euch 6 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental.", description = "Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!\n\nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.\n\nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.", progress = "<Name>, habt Ihr schon das benötigte Mottenblut für die Heilkristalle? Überlebende sind über das gesamte Tal verstreut und die Zeit drängt!", completion = "Wie bedauernswert, dass diese Kreaturen sterben mussten, damit wir überleben können - wahlloses Töten entspricht nicht dem Weg der &lt;Volk&gt;. Wie auch immer, das von Euch gesammelte Blut wird unsere Heilkristalle wieder aufladen, somit war ihr Opfer nicht umsonst.", rewards = "Ausgebesserter LedergürtelAbgenutzte SchuheLeicht verrostete ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9281] = {title = "Den Weg frei machen", objective = "Lehrling Vor'el von Andiliens Grund in den Geisterlanden möchte, dass Ihr 10 Große Spindelweber und 10 Geisterklauenverheerer tötet.", description = "Magister Kaendris hat mich entsandt, um die Gegend von aggressiven Wildtieren zu säubern. Sobald die Gegend sicher ist, wollen die Magister hier einen Außenposten gegen die Geißel errichten.\n\nWenn Ich als Lehrling eines gelernt habe, dann ist das, Verantwortung zu delegieren, besonders bei solch lebensgefährlichen Unternehmungen!\n\nWenn Ihr Interesse habt, werde ich Euch gut dafür bezahlen, die Großen Spindelweber und Geisterklauenverheerer westlich und südlich von hier aus dem Weg zu räumen.", progress = nil, completion = "Vielen Dank für Eure Unterstützung, &lt;Name&gt;. Mir schaudert bei dem Gedanken, mich so nahe bei der Todesfestung in den Wald zu wagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9282] = {title = "Die Enklave der Weltenwanderer", objective = "Magister Kaendris beim Sanktum der Sonne möchte, dass Ihr mit Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden sprecht.", description = "Die Magister und die Weltenwanderer mögen nicht immer einer Meinung sein, <Name>, doch wenn es um Dar'Khan geht, stimmen alle überein, dass wir gemeinsam einen Weg finden müssen, um ihn und seine Legionen zu besiegen.\n\nWaldläuferin Vynna, in der Enklave der Weltenwanderer im Nordosten, ist auf einige wichtige Informationen über unseren Feind gestoßen. Sucht sie auf und seht, ob sie Eure Hilfe benötigt.", progress = nil, completion = "Kaendris hat Euch geschickt? Möglicherweise habe ich eine Aufgabe für Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9283] = {title = "Rettet die Überlebenden!", objective = "Wendet Eure Gabe der Naaru an, um einen der Überlebenden der Draenei zu heilen, die über das ganze Am'mental verstreut sind. Kehrt dann zu Zalduun bei der Absturzstelle im Am'mental zurück.", description = "Jetzt haben wir wieder genügend Heilkristalle, aber sie sind nicht der einzige Weg, wie wir den Verletzten helfen können. Alle Draenei können die Gabe der Naaru einsetzen, um zu heilen. Ihr müsst den Überlebenden des Absturzes mit dieser Gabe helfen.\n\nDie meisten Überlebenden findet Ihr im Westen und Nordwesten, aber der Absturz hat uns alle im gesamten Tal verstreut.\n\nDie Überlebenden haben sehr unter der Strahlung der Energiekristalle gelitten, daher solltet Ihr sie an dem roten Schein, der sie umgibt, erkennen können.\n\nIhr müsst uns helfen, sie zu retten, <Name>!", progress = nil, completion = "Dem Licht sei Dank! Ihr habt getan, was nur ein wahrer Held vollbringen kann, &lt;Name&gt;! Jeder &lt;Volk&gt;, den Ihr gerettet habt, verdankt Eurer Selbstlosigkeit sein Leben!\n\nBitte, nehmt diesen Vorratsbeutel. Ihr könnt ihn sicher besser gebrauchen als ich.", rewards = "Ihr bekommt:\n\nLeerer Vorratsbeutel der Draenei"}
MultiLanguageQuestData['de'][9284] = {title = "Aldor Faction Test", objective = "Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9285] = {title = "Consortium Faction Test", objective = "Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9286] = {title = "Scryers Faction Test", objective = "Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9287] = {title = "Ausbildung zum Paladin", objective = "Es erfüllt mich mit Stolz, dass Ihr mit mir sprechen möchtet. Früher war ich für die Ausbildung junger Paladine, die unserem Orden beitreten wollten, verantwortlich. Eine Pflicht und ein Privileg, das ich fraglos noch einmal auf mich nehme. Man spricht von Euch als jemand, der Gutes im Namen des Lichts tun möchte. Es wäre eine Ehre für mich, wenn ich Euch die ersten Schritte auf dem Weg eines Paladins lehren dürfte.\n\nSollen wir beginnen?", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9288] = {title = "Ausbildung zum Jäger", objective = "Ich bin froh, dass Ihr zu mir gekommen seid. Ich bin schon eine ganze Weile für die Ausbildung junger <Klasse> verantwortlich, eine Aufgabe, die ich auch in dieser neuen Welt noch weiter erfüllen möchte. Ich beobachte Euch bereits seit geraumer Zeit und es wäre eine Ehre für mich, wenn ich Euch die Künste des Jägers lehren dürfte.\n\nSollen wir beginnen?", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9289] = {title = "Ausbildung zum Krieger", objective = "Es ist gut, dass Ihr meine Weisung ersucht. Ich habe seit Jahrhunderten junge Draeneikrieger ausgebildet, also werde ich Euch schon auf die eine oder andere Weise auf den richtigen Weg eines Kriegers verhelfen können. Ich sehe eine Zukunft als mächtiger Krieger für Euch voraus, aber nur, wenn Ihr auch wirklich beherzigt, was ich Euch beibringe.\n\nSeid Ihr bereit, junger Krieger?", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9290] = {title = "Ausbildung zum Magier", objective = "Es ehrt mich, dass Ihr mich wegen meines Wissens aufsucht. Es gibt viel zu tun, wenn sich Eure magischen Fähigkeiten gänzlich entfalten sollen.\n\nSeit mehr als hundert Jahren lehre ich die Künste der arkanen Magie, Frost- und Feuerzauber. Auch auf dieser Welt kann ich ihre Macht spüren. Möchtet Ihr, dass ich Euch an meinen Kenntnissen teilhaben lasse?", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9291] = {title = "Ausbildung zum Priester", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9292] = {title = "Gesprungener nekrotischer Kristall", objective = "Bringt den gesprungenen nekrotischen Kristall zu Leutnant Orrin außerhalb der Tore von Sturmwind.", description = "Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.", progress = "Ja, was gibt's?", completion = "Hm, Ihr habt das beim Körper einer der Monstrositäten gefunden?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Stormwind errichten wollten. Es ist gut, dass sie damit erfolglos waren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"}
MultiLanguageQuestData['de'][9293] = {title = "Was getan werden muss...", objective = "Sammelt 10 Peitscherproben ein und bringt sie zu Botanikerin Taerix bei der Absturzstelle im Am'mental.", description = "Der nahegelegene See wurde von einem Energiekristall des Schiffs verseucht. Zahlreiche Pflanzen und Tiere des Am'mentals sind deswegen mutiert.\n\nIch habe bereits eine Theorie aufgestellt, wie man den See heilen kann, allerdings brauche ich Proben von mutierten Wurzelpeitschern für eine Auswertung. Man findet sie im Westen der Am'menfelder.\n\nWerdet Ihr mir helfen, <Klasse>?", progress = "Der Zustand aller Proben muss einwandfrei sein, damit wir eine Chance haben, den See zu entseuchen.\n\nUns bleibt nicht viel Zeit, <Klasse>!", completion = "Genau das habe ich gebraucht. Danke, &lt;Klasse&gt;!\n\nWährend Ihr unterwegs wart, habe ich bereits meine Ausrüstung aufgebaut, um die Proben auswerten zu können. Ich sollte lediglich ein paar Augenblicke benötigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9294] = {title = "Die Heilung des Sees", objective = "Verwendet den Neutralisierungswirkstoff bei dem strahlenden Energiekristall und kehrt anschließend zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück.", description = "Dem Licht sei Dank, ich glaube es wird funktionieren! Ich habe einen Wirkstoff, den Ihr beim Silberwellensee im Süden einsetzen müsst. Er wird den Effekt des strahlenden Energiekristalls des Schiffs, der hier heruntergestürzt ist, neutralisieren.\n\nSchwimmt raus auf den See und verwendet dort den Neutralisierungswirkstoff. Keine Sorge, Ihr werdet der Strahlung nicht lange genug ausgesetzt sein, um verseucht zu werden.", progress = nil, completion = "Euren Schilderungen zufolge hat der Neutralisierungswirkstoff funktioniert! Ich wünschte nur, ich wüsste, wie lange er anhält. Wir müssen den Energiekristall gänzlich aus dem See entfernen.\n\nDanke, &lt;Name&gt;! Ich werde Tedon bitten, den Neutralisierungswirkstoff sofort an einem der gefangenen Tiere auszuprobieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9295] = {title = "Brief von der Front", objective = "Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9296] = {title = "reuse", objective = "Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.", description = "Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9297] = {title = "reuse", objective = "Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.", description = "Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9298] = {title = "reuse", objective = "Deliver the Dim Necrotic Stone to SOMEONE.", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9299] = {title = "Notiz von der Front", objective = "Bringt die verblichene Notiz zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9300] = {title = "Nachricht von der Front", objective = "Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9301] = {title = "Umschlag von der Front", objective = "Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9302] = {title = "Schreiben von der Front", objective = "Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9303] = {title = "Immunisierung", objective = "Wendet den Immunisierungskristall auf 6 Nisteleulkin an. Kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am'mental zurück.", description = "Zhanaa braucht unsere Hilfe, um Teile aus der Exodar zu bergen. Taerix hat eine Immunisierungsmethode vorbereitet, mit der die Nisteleulkins behandelt werden können. Sie bewohnen die Gegend, in der die meisten Teile gefunden werden können.\n\nNähert Euch den noch nicht verseuchten Biestern und wendet den Kristall auf sie an. Die anderen müsst Ihr leider umbringen. Ihr findet sie im Nisteldickicht und bei den Nistelhügeln im Südosten.", progress = "Je mehr wir tun können, um den Nistelwald aufzuräumen, desto schneller kann Zhanaa zurück an die Arbeit.", completion = "Da jetzt viele der Eulkin immunisiert wurden, können wir uns auf unseren Aufbruch von hier konzentrieren, ohne die gesamte Eulkinpopulation ausrotten zu müssen.\n\nHier, sucht Euch etwas aus. Ihr habt eine so wunderbare Arbeit geleistet, Ihr verdient eine Belohnung!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElixier der schwachen VerteidigungElixier der Löwenstärke\n\nIhr bekommt außerdem:\n\nSchwacher Heiltrank"}
MultiLanguageQuestData['de'][9304] = {title = "Dokument von der Front", objective = "Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9305] = {title = "Ersatzteile", objective = "Beschafft 4 Emitterersatzteile und kehrt anschließend zu Technikerin Zhanaa bei der Absturzstelle im Am'mental zurück.", description = "Wir konnten einen beschädigten holografischen Emitter nach dem Absturz bergen. Sollten wir ihn reparieren können, besteht die Möglichkeit, dass wir noch andere Überlebende außerhalb des Am'mentals finden.\n\nVon dem Schiff hätte man einige Apparaturen sichern können, die geeignete Ersatzteile geliefert hätten, aber die heimischen Eulkin haben sie verschleppt, bevor wir sie überhaupt erreichen konnten.\n\n<Name>, Ihr müsst ins Nisteldickicht und in die Nistelhügel im Süden gehen und die Ersatzteile zurückholen!", progress = "Ich bin mir sicher, dass wir den Emitter mit den Ersatzteilen reparieren können! Mit etwas Glück, werden wir da draußen noch andere finden, mit denen wir uns in Verbindung setzen können.", completion = "Lasst mich mal sehen.\n\nJa, ich denke, das wird gehen; gute Arbeit, &lt;Name&gt;! Der Emitter ist ziemlich komplex und deshalb kann die Reparatur ein Weilchen dauern. Ich sage Euch Bescheid, sobald ich fertig bin.\n\nSchaut in der Zwischenzeit bei Verteidiger Aldar vorbei und fragt ihn, ob er Euch brauchen kann.", rewards = "Verschrammte KettengamaschenRaue LedergamaschenHandgenähte HoseIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9308] = {title = "<DEPRECATED>Blood Elf Remains?", objective = "Bringt das Blutelfenamulett zu Verteidiger Aldar bei der Absturzstelle im Am'mental.", description = "Ihr vermutet, dass der tote Blutelf, dessen Überreste Ihr hier auf dem Boden liegend gefunden habt, den Sin'dorei angehörte. Wie es aussieht, fiel er den wilden Klauen von mehreren mutierten Eulkin im Dickicht zum Opfer.\n\nBeim Durchsuchen des Leichnams entdeckt Ihr ein Amulett, das an einer Kette um seinen Hals hängt. Vielleicht ist es für Verteidiger Aldar von Interesse?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9309] = {title = "Der vermisste Späher", objective = "Sprecht mit Tolaan im Schattenkamm im Am'mental.", description = "Verschiedene Quellen konnten uns nun bestätigen, dass beim Schattenkamm ungewöhnliche Dinge vor sich gehen.\n\nDas ist äußerst beunruhigend, denn wir dachten, dass die bisherigen Aufklärungsmissionen gründlich genug gewesen wären. Einer meiner Späher hat sich noch nicht zurückgemeldet.\n\n<Klasse>, Ihr müsst für mich Richtung Südwesten gehen, zur anderen Uferseite des Silberwellensees, und Tolaan finden. Findet heraus, was ihn aufgehalten hat.", progress = nil, completion = "Hilfe... Blutelfen! Ein... ein Hinterhalt. Ich habe... nicht mehr lange...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9310] = {title = "Schwacher nekrotischer Kristall", objective = "Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Unterstadt.", description = "Ihr findet beim Körper der toten Kreatur einen Kristall, der schwache nekrotische Energie ausstrahlt.", progress = "Kann ich Euch irgendwie weiterhelfen?", completion = "Ihr sagt, dass Ihr das bei einer der Kreaturen gefunden habt, die die Stadt angreifen?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Undercity errichten wollten. Wir müssen zukünftig sehr vorsichtig sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"}
MultiLanguageQuestData['de'][9311] = {title = "Blutelfenspionage", objective = "Tötet Gutachterin Kandress und informiert anschließend Verteidiger Aldar bei der Absturzstelle im Am'mental über die Ereignisse.", description = "Ich habe einen Plan. Wir müssen ihren Anführer umbringen. Vielleicht ziehen sie sich ohne ihren Meister zurück, um sich neu zu formieren. Wir müssen Zeit schinden, damit wir die Reparaturen abschließen können.\n\nVerteidiger Aldar muss davon erfahren. Tötet die Gutachterin und kehrt dann zu ihm zurück, um ihn zu erzählen, was wir herausgefunden haben.", progress = nil, completion = "Danke, dass Ihr Euch um die Gutachterin gekümmert habt. Sie war ganz sicher ihre Anführerin. Ich versichere Euch, dass wir uns um den restlichen Haufen, der sich eventuell noch hier in der Nähe aufhält, kümmern werden.\n\nBitte, nehmt eine dieser Waffen als Zeichen unserer Dankbarkeit.", rewards = "Bastardschwert der ExodarDolch der ExodarSchlägel der ExodarKurzschwert der ExodarArmbrust der ExodarStab der ExodarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9312] = {title = "Der Emitter", objective = "Sprecht mit Technikerin Zhanaa bei der Absturzstelle im Am'mental.", description = "<Name>, während Ihr den Schattenkamm erkundet habt, hat Zhanaa weiter am holografischen Emitter gearbeitet. Vielleicht solltet Ihr mit ihr sprechen.", progress = nil, completion = "Ja, ja! Ich glaube, ich habe den Emitter reparieren können! Hier, ich muss lediglich den letzten Kristall aktivieren und das sollte es gewesen sein.\n\nSeht, &lt;Name&gt;, der Emitter. Er scheint zu funktionieren... es erscheint jemand!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9313] = {title = "Reise zur Azurwacht", objective = "Sprecht mit Techniker Dyvuun bei der Azurwacht auf der Azurmythosinsel.", description = "Soweit so gut, <Name>, Ihr müsst allerdings sofort zur Azurwacht reisen und mit Dyvuun sprechen!\n\nEs gibt einen Pfad, der westlich von dieser winzigen Insel führt. Folgt ihm und überquert den Kristallfluss, um auf den größeren Teil der Insel zu gelangen. Wenn Ihr dem Pfad noch weiter folgt, solltet Ihr die Azurwacht finden.\n\nVielleicht könnt Ihr sie ja überzeugen, uns etwas Hilfe und Vorräte zukommen zu lassen. Wir kommen nach, sobald wir können.\n\nIch danke Euch, ohne Euch hätten wir das nicht geschafft!", progress = nil, completion = "Ah, es ist gut, Euch wiederzusehen! Ich bin froh, dass wir beide unsere Emitter reparieren konnten, sonst hätten wir uns wohl nie gefunden. Sorgt Euch nicht, wir werden natürlich Hilfe und Vorräte ins Am'mental schicken.\n\nDa wir gerade von Hilfe sprechen... jetzt wo Ihr hier seid, könnt Ihr Euch ja mal umsehen und Euch bei den anderen vorstellen. Ich weiß, dass es jede Menge zu tun gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9314] = {title = "Nachricht von der Azurwacht", objective = "Sprecht mit Versorgerin Chellan bei der Azurwacht auf der Azurmythosinsel.", description = "<Klasse>! Ein paar dieser mutierten Biester haben mich angesprungen und jetzt ist mein Bein verletzt.\n\nNachdem wir von Zhanaa gehört hatten, wurde ich von der Azurwacht auf eine Spähmission geschickt. Könntet Ihr vielleicht an meiner statt mit Versorgerin Chellan sprechen? Sie muss wissen, wie viele Leute sie in der Azurwacht erwarten soll. Ihr müsst lediglich den Kristallfluss hier überqueren und dem Pfad bis zur Azurwacht folgen.\n\nVergesst nicht, nach einer Unterkunft zu fragen, wenn Ihr dort seid.", progress = nil, completion = "Oh, Ihr müsst einer der Überlebenden sein, von denen wir gehört haben!\n\nIch bin froh, dass Ihr gekommen seid. Keine Sorge, wir schicken jemanden los, der sich Aeuns verletztes Bein ansehen wird.\n\nIch will unbedingt alles über Eure aufregende Überlebensgeschichte hören! Wenn Ihr bis hierhergekommen seid, müsst Ihr sehr tapfer sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGlänzender KleinfischErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9315] = {title = "Anok'suten", objective = "Tötet Anok'suten und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", description = "Kommt näher, ich... ich sterbe.\n\nMan entsandte mich hierher, um... um die Neruber zu besiegen, doch Vandril konnte nicht ahnen, dass sie... sie eine Anführerin haben.\n\n<Der sterbende Blutelf spuckt etwas Blut.>\n\nIhr müsst Anok'suten finden und... und töten. Sie wandert in der Umgebung von... Sonnenkuppe umher.", progress = nil, completion = "Ich muss mich für die schlechte Aufklärung entschuldigen, &lt;Klasse&gt;. Hätte ich vorher etwas von der Existenz dieser Anok'suten gewusst, hätte ich Euch natürlich umgehend davon in Kenntnis gesetzt.\n\nUnsere Kräfte sind einfach zu weit verteilt und manche Dinge schlüpfen uns unter diesen Umständen einfach durchs Netz.", rewards = "StachVandrils abgelegte HoseVerstärkte OfenhandschuheBundhose von TristessaIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9316] = {title = "Wilde Goblins", objective = "Brianna Schneider auf der Designerinsel möchte, dass Ihr ihr 10 Goblinzähne bringt.", description = "<Brianna schaut Euch prüfend an.>\n\nIhr wollt also ein paar Goblins töten, was? Nun, wenn Ihr dazu bereit seid, könnt Ihr mit den Wilden in der Nähe anfangen. Bringt mir ihre Zähne als Beweis Eurer Taten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n12-pfündiger Hummer"}
MultiLanguageQuestData['de'][9317] = {title = "Geweihte Wetzsteine", objective = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", description = nil, progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, &lt;Name&gt;. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise.", rewards = "Ihr bekommt:\n\nGeweihter Wetzstein"}
MultiLanguageQuestData['de'][9318] = {title = "Gesegnetes Zauberöl", objective = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", description = nil, progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt.", rewards = "Ihr bekommt:\n\nGesegnetes Zauberöl"}
MultiLanguageQuestData['de'][9319] = {title = "Licht im Dunkeln", objective = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.", description = "Wir sind nicht die Einzigen, die dieses Fest feiern, <Name>. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.\n\nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Schwarzfelsspitze selbst. Ich erwarte Eure Rückkehr.", progress = "Habt Ihr Euch im Dunkeln zurechtgefunden?", completion = "Euer Wesen erstrahlt mit der Energie der Flammen, die Ihr gefunden habt, &lt;Name&gt;. Das Feuer, mit dem Ihr in Berührung gekommen seid,  ist mächtig. Mit dem richtigen Wissen, kann man sich diese Macht zu Nutzen machen...\n\n\n\nAh! Soweit so gut. Ich hoffe dies wird Euren Weg erleuchten, wohin immer Ihr auch gehen mögt.", rewards = "Ihr bekommt:\n\nEingefangene FlammeBrandblüte"}
MultiLanguageQuestData['de'][9320] = {title = "Erstklassiger Manatrank", objective = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", description = nil, progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, &lt;Name&gt;. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten.", rewards = "Ihr bekommt:\n\nErstklassiger ManatrankErheblicher Manatrank"}
MultiLanguageQuestData['de'][9321] = {title = "Erstklassiger Heiltrank", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nErstklassiger HeiltrankErheblicher Heiltrank"}
MultiLanguageQuestData['de'][9322] = {title = "Glühende Feuer in Kalimdor", objective = "Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Krater von Un'Goro und Winterquell auf. Kehrt dann zum Flammenbewahrer zurück.", description = "Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise - wie wäre es mit einem Ausflug?\n\nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterquell, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Krater von Un'Goro entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.", progress = nil, completion = "Euer Geist erstrahlt mit der Wärme der Feuer Kalimdors. Ist die Hitze nicht anregend?\n\nWenn die Macht von Euch schwindet, könnte Euch dies hier vielleicht dabei helfen, das Ganze wieder aufleben zu lassen.", rewards = "Ihr bekommt:\n\nAschenarmschienenBrandblüte"}
MultiLanguageQuestData['de'][9323] = {title = "Glühende Feuer in den Östlichen Königreichen", objective = "Reist zu den Lagern des Sonnenwendfests in den Verwüsteten Landen, den Östlichen Pestländern, dem Hinterland und der Sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.", description = "Das Fest der Flamme ist im ganzen Land verbreitet, <Klasse>. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.\n\nEines befindet sich genau nördlich von der Schwarzfelsspitze. Die anderen liegen tief im Innern der Östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den Verwüsteten Landen.\n\nKehrt anschließend zu mir zurück.", progress = nil, completion = "Ah, da seid Ihr also. Etwas erschöpfter, ein wenig schmutziger, aber erleuchtet! Die Wärme berührt und vereint uns alle während dieser Zeit. Euer Wesen erstrahlt mit der Macht der Feuer, die Ihr berührt habt.\n\nAh, ich vermute, dass Erleuchtung heutzutage wohl eher als eine armselige Belohnung für eine Aufgabe wie diese angesehen wird. Nehmt dies hier, bitte, und genießt das Fest.", rewards = "Ihr bekommt:\n\nMantelung des SonnenwendfestsBrandblüte"}
MultiLanguageQuestData['de'][9324] = {title = "Raubt die Flamme von Orgrimmar", objective = "Bringt die Flamme von Orgrimmar zum Meister der Lehren.", description = "Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Was ist das? Sollte ich mich nicht täuschen, so wurde diese Flamme aus dem Herzen Orgrimmars entwendet! Die sengende Hitze spiegelt die kämpferischen Herzen der Orcs und Trolle wider. Was für ein Gewinn für unsere Sammlung! Wie mutig Ihr doch seid - sich in den Bau des Feindes einzuschleichen, um die heilige Flamme zu erlangen!\n\nIch frage mich, welch' Mächte sich in den anderen Städten versteckt halten...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9325] = {title = "Raubt die Flamme von Donnerfels", objective = "Bringt die Flamme von Donnerfels zum Meister der Lehren.", description = "Die Flamme, die dem Schamanen von Donnerfels entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Sollte mich meine Vermutung nicht täuschen, so wurde diese Flamme aus Donnerfels entwendet! Die Macht der Geister ist deutlich hörbar! Ihr seid ganz schön gerissen, &lt;Name&gt;. Nehmt dies als gerechte Anerkennung Eures Könnens. Hm, hätten wir doch auch alle vier Flammen von den anderen Städten...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9326] = {title = "Raubt die Flamme von Unterstadt", objective = "Bringt die Flamme von Unterstadt zum Meister der Lehren.", description = "Die Flamme, die aus den Ruinen über Unterstadt entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Hm... was für ein seltsames Feuer! Es flackert schwach, ist fast nur noch ein Glühen, aber die Hitze ist stark. Ihr sagt, dass Ihr es aus Unterstadt entwendet habt? Faszinierend. Wer weiß, was wir mit den Flammen aller vier Städte erreichen könnten?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9327] = {title = "Die Verlassenen", objective = "Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.", description = "Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.\n\nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.", progress = nil, completion = "Ich weiß, wir Verlassenen mögen in Euren Augen monströs erscheinen, aber ich versichere Euch, wir sind für Euer Volk keine Bedrohung. Wir sind hier, weil wir einen gemeinsamen Feind haben: Dar'Khan den Verräter! Er ist zurückgekehrt und befehligt die Geißel von der Todesfestung im Süden aus.\n\nUnsere Anführerin, Lady Sylvanas Windläufer, stammt aus dieser Gegend, und war früher ein Elf. Sie hatte schon mit Dar'Khan zu tun und möchte ihn genauso gern tot sehen wie Eurer Volk.\n\nWir werden ihn zusammen besiegen, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9328] = {title = "Held der Sin'dorei", objective = "Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond.", description = "Dies ist der Beginn eines neuen Zeitalters für unser Volk, <Name>. Wir werden unser Land zurückerobern und unseren Bund mit Sylvanas und ihren Verbündeten festigen.\n\nBringt den Kopf des Verräters nach Silbermond, zu Lor'themar Theron, dem Lordregenten Silbermond. Er wird begierig sein, die Neuigkeit zu erfahren.", progress = "Ihr wünscht eine Audienz bei mir, <Klasse>? Ich kann mich nicht an eine Verabredung erinnern.", completion = "Nun, das ist ein Gesicht, das ich noch nicht so früh hier erwartet hätte.\n\nDas sind ziemlich gute Neuigkeiten, &lt;Name&gt;, in mehr Hinsichten, wie Ihr Euch denken könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9329] = {title = "Die Verlassenen", objective = "Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.", description = "Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.\n\nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.", progress = nil, completion = "Die Verlassenen sind hier, weil wir und die Blutelfen einen gemeinsamen Feind haben: Dar'Khan! Er ist zurückgekehrt und befehligt die Geißel von der Todesfestung im Süden aus.\n\nLady Sylvanas Windläufer, die ursprünglich aus dieser Gegend hier stammt, hatte schon früher mit Dar'Khan zu tun und möchte ihn tot sehen!\n\nWir werden Ihn besiegen, &lt;Name&gt;, und Ihr werdet uns dabei helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9330] = {title = "Raubt die Flamme von Sturmwind", objective = "Bringt die Flamme von Sturmwind zum Geschichtenerzähler.", description = "Die Flamme, die aus dem Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Also dieses hell leuchtende Feuer... Ihr sagt es kommt aus Stormwind? Bemerkenswert! Das muss ein ziemliches Abenteuer gewesen sein! Ich werde Euch dafür natürlich entlohnen. Solltet Ihr etwas Ähnliches finden, kommt bitte sofort zu mir.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9331] = {title = "Raubt die Flamme von Eisenschmiede", objective = "Bringt die Flamme von Eisenschmiede zum Geschichtenerzähler.", description = "Die Flamme, die aus dem Zentrum von Eisenschmiede entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Diese kraftvolle Flamme muss aus den Hallen von Ironforge stammen; sie ist so unerschütterlich wie die Zwege selbst. Gute Beute, &lt;Name&gt;. Hätte ich nur die Flammen der anderen Städte... naja, macht Euch nichts draus. Hier ist Euer Lohn.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9332] = {title = "Raubt die Flamme von Darnassus", objective = "Bringt die Flamme von Darnassus zum Geschichtenerzähler.", description = "Die Flamme, die von der Küste Teldrassils entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Dieses Feuer ist mit uraltem Kummer erfüllt, &lt;Name&gt;. Ihr habt es aus dem Herzen Teldrassils, ja? Unglaublich! Hier, als Anerkennung für Euer Können. Kehrt zu mir zurück, falls Ihr etwas Ähnliches finden solltet - ich könnte Verwendung dafür haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9333] = {title = "Handschuhe der Argentumdämmerung", objective = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", description = nil, progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen.", rewards = "Stulpen des UntotenschlachtensHandlappen des UntotenschlachtensHandschützer des UntotenschlachtensHandschuhe der Untotenbekämpfung"}
MultiLanguageQuestData['de'][9334] = {title = "Gesegnetes Zauberöl", objective = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", description = nil, progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt.", rewards = "Ihr bekommt:\n\nGesegnetes Zauberöl"}
MultiLanguageQuestData['de'][9335] = {title = "Geweihte Wetzsteine", objective = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", description = nil, progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, &lt;Name&gt;. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise.", rewards = "Ihr bekommt:\n\nGeweihter Wetzstein"}
MultiLanguageQuestData['de'][9336] = {title = "Erstklassiger Heiltrank", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nErstklassiger HeiltrankErheblicher Heiltrank"}
MultiLanguageQuestData['de'][9337] = {title = "Erstklassiger Manatrank", objective = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", description = nil, progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, &lt;Name&gt;. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten.", rewards = "Ihr bekommt:\n\nErstklassiger ManatrankErheblicher Manatrank"}
MultiLanguageQuestData['de'][9338] = {title = "Treue zum Zirkel des Cenarius", objective = "Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.\n\nBringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken.", description = nil, progress = "Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.\n\nBringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken.", completion = "Ihr ehrt uns, &lt;Name&gt;. Eure fortgesetzten Anstrengungen helfen uns, alle Hindernisse zu überwinden.", rewards = nil}
MultiLanguageQuestData['de'][9339] = {title = "Der Lohn des Diebes", objective = "Bringt die Flamme von Sturmwind zu (NAME).Die Flamme, die aus dem unmittelbaren Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", progress = nil, completion = "Ihr habt Euch heute bewiesen, &lt;Name&gt;.\n\nIch habe zwar nicht viel, das ich Euch geben könnte, aber bitte nehmt diese Krone, eine passende Belohnung für einen Eroberer. Möge sie Euren Weg erleuchten.", rewards = "Ihr bekommt:\n\nKrone des Sonnenwendfests"}
MultiLanguageQuestData['de'][9340] = {title = "Die Große Kluft", objective = "Waldläuferhauptmann Venn'ren in der Falkenwacht möchte, dass Ihr 8 Steinsichelwelpen und 3 Steinsichelalphas bei der Großen Kluft östlich der Falkenwacht erlegt.", description = "Wir stehen kurz davor, vollständig von den Streitkräften der Allianz eingekesselt zu werden. Mit dem ständigen Zustrom von Sin'doreiflüchtlingen aus Azeroth, müssen wir einen Weg finden, der vor den neugierigen Blicken des Feindes sicher ist.\n\nIch habe darüber etwas nachgedacht und bin kürzlich zu einer Lösung gekommen. Wir werden eine sichere Passage durch die Große Kluft etablieren.\n\nJa, auch wenn es dort nur so von tödlichen Felsklauen wimmelt, sind sie doch nichts weiter als bloße Tiere, denen wir beibringen können, uns zu fürchten. Ich möchte, dass Ihr loszieht und eine größere Anzahl dieser Biester erlegt. Zeigen wir ihnen, was Angst ist!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Das sollte die Felsklauen lehren, sich von uns fernzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9341] = {title = "Wappenrock der Argentumdämmerung", objective = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", description = nil, progress = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen.", rewards = "Ihr bekommt:\n\nWappenrock der Argentumdämmerung"}
MultiLanguageQuestData['de'][9343] = {title = "Wappenrock der Argentumdämmerung", objective = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", description = nil, progress = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen.", rewards = "Ihr bekommt:\n\nWappenrock der Argentumdämmerung"}
MultiLanguageQuestData['de'][9345] = {title = "Herstellung der Salbe", objective = "Grelag im Rückenbrecherposten möchte, dass Ihr ihm 12 Höllenwirbelkräuter für seine Salbe bringt.", description = "Als ich gerade Zeth'Gor erkennen konnte, wurde ich von einer Patrouille der Legion entdeckt. Ich rannte los in der Hoffnung, dass ich mich in einem der Türme in der Ferne verstecken kann, aber einer ihrer Teufelshunde hat mich eingeholt und mich fast zerfleischt!\n\nIch konnte entkommen, aber mein Bein ist in einem sehr schlechten Zustand. Steingardist Ambelan hat mich gefunden und hierher gebracht.\nJetzt muss ich einen Weg finden, um mein Bein zu versorgen. Wirbelkraut wächst in und um das Tal der Knochen im Norden herum. Eine Salbe daraus wird den Schmerz lange genug betäuben, dass ich weiterreisen kann.", progress = "Habt Ihr die Pflanzen gefunden?", completion = "Die sollten Ihren Zweck erfüllen. Ich werde die Salbe fertigstellen und mein Bein schienen, bevor ich nach Thrallmar aufbreche. Wieso glaube ich genau zu wissen, was mir Scharfseherin Regulkut erzählen wird, wenn sie mich so sieht?\n\n&lt;Grelag seufzt halbherzig.&gt;\n\nVielen Dank für Eure Hilfe, &lt;Name&gt;. Ich habe noch einige von den Höllenwirbelkräutern übrig. Nehmt sie mit, wenn Ihr sie braucht. Wer weiß, wofür sie noch gut sind?", rewards = "Ihr bekommt:\n\nHöllenwirbelkraut"}
MultiLanguageQuestData['de'][9349] = {title = "Felshetzereier sammeln", objective = "Bringt 12 Felshetzereier zu Legassi bei der Zeppelinabsturzstelle auf der Höllenfeuerhalbinsel.", description = "Ich bin am verhungern!\n\nIst das nicht ironisch? Ein verhungernder Koch?\n\n<Legassi lacht halbherzig und tippt auf ein gefaltetes Pergament in seiner Tasche.>\n\nLaut dieser Touristenkarte, der wir gefolgt waren, bevor wir so hinterhältig niedergeschossen wurden, gibt es im Südwesten eine Gegend, nahe bei den Wäldern von Terokkar. Sie wird der Messerdornpfad genannt und angeblich soll es dort von leckeren Felshetzereiern nur so wimmeln!\n\nIch könnte ein tolles Festmahl daraus zaubern, wenn nur jemand mutig genug wäre, dorthin zu gehen und ein paar zu sammeln!", progress = "Habt Ihr die Eier schon?\n\n<Legassis Magen knurrt vor Vorfreude.>", completion = "Für ausgezeichnete Küche braucht man ausgezeichnete Zutaten. Und diese Eier sehen großartig aus!\n\nIch habe gerade meine Pfanne geputzt, Ihr seid also herzlich eingeladen, mir bei einem Mahl Gesellschaft zu leisten.", rewards = "Ihr bekommt:\n\nFelshetzeromelett"}
MultiLanguageQuestData['de'][9351] = {title = "Wilde Leerwandler", objective = "Bringt 10 kondensierte Leerwandleressenzen zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle.", description = "Auch wenn ich den Rahmen des Zeppelins repariert bekomme, muss ich einen Ersatztreibstoff finden! Ich habe kein Benzin mehr, und es gibt weit und breit keine Tankstelle!\n\nSüdlich von hier liegt eine Gegend namens Sphärenfelder. Dort wimmelt es nur so von wilden und unkontrollierten Leerwandlern, aber für mich sind sie eher wandelnde Batterien.\n\nWenn Ihr mir genug von Ihrer Essenz bringt, kann ich damit den Motor des Zeppelins zum Laufen bekommen. Ich wette fünf Gold, dass ich dann sogar einen niedrigeren Verbrauch habe!", progress = "Konntet Ihr die Essenzen besorgen?", completion = "Perfekt! Ich glaube sogar, dass das so gut funktionieren wird, dass ich den Motor umbauen muss, damit ich alle Vorteile dieses Kraftstoffs nutzen kann! Falls - ich meine natürlich - wenn wir hier wegkommen, muss ich allen in Area 52 meine Entwürfe zeigen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nUhr des HypnotiseursGlücksbringer des Eifers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9352] = {title = "Darnassische Eindringlinge", objective = "Reist zum Sanktum des Westens südwestlich vom Falkenplatz und vernichtet jegliche Eindringlinge, die Ihr dort findet. Berichtet anschließend Leybewahrerin Velania.", description = "Abgesehen von der konstanten Bedrohung durch die Getriebenen, befasse ich mich auch mit den zahlreichen Berichten über angebliche Nachtelfensichtungen.\n\nObwohl viele dieser Sichtungen frei erfunden sind, gibt es doch einen Vorfall, der weiterer Untersuchungen bedarf. Das Sanktum des Westens, eine unserer primären Energiequellen, hatte eine massive Fehlfunktion und Gerüchte, eine darnassische Sabotageaktion sei der Grund dafür, machen die Runde.\n\nBegebt Euch dorthin und kümmert Euch um jeden, der verdächtig aussieht. Meldet Euch bei Leybewahrerin Velania, sie überwacht das Sanktum.", progress = nil, completion = "Nachtelfen? Hier? Diese Ratten!\n\nGlaubt Ihr, es besteht irgendeine Verbindung zu der Fehlfunktion in meinem Sanktum? Falls Ihr irgendwelche Informationen habt, bringt Ihr sie besser umgehend zu Hauptmann Sonnenmal!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9353] = {title = "iCoke-Geschenkgutschein einlösen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSommerliche Geschenkkiste"}
MultiLanguageQuestData['de'][9355] = {title = "Eine Aufgabe für einen intelligenten Helden", objective = "Tötet 15 plündernde Krustenbohrer und kehrt dann zu Großknecht Biggums in der Ehrenfeste zurück.", description = "Gut, <Klasse>. Nun, da die Verstärkung anrückt, können wir endlich wieder ein mehr oder weniger normales Leben führen.\n\nEines unserer ersten Ziele ist die Wiederaufnahme des Transports von Männern und Waren auf der Straße nach Südwesten, aber dazu müssen wir sie erst von den Krustenbohrern zurückfordern, die diese Gegend in Beschlag genommen haben.\n\nWenn Ihr uns bei dieser Aufgabe helfen würdet, wären die Söhne Euch sehr dankbar. Gebt auf die aufgewühlte Erde Acht, die sie hinterlassen!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wir sollten uns aber nicht zu früh freuen. Ich bin mir sicher, dass wir diese Würmer nicht zum letzten Mal gesehen haben. Wenn sie ihre hässlichen Köpfe wieder in diese Gegend strecken sollten, werden die Söhne sie schon erwarten!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAdeptenbandMachterfüllte Kette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9356] = {title = "So weich wie Butter", objective = "Bringt 12 fleischige Bussardflügel zu Legassi bei der Zeppelinabsturzstelle.", description = "Quack sagt immer, er fliegt \"so weich wie Butter\". Ich glaube eher, sein Kopf ist so \"weich wie Butter\"!\n\nSchaut Euch nur die Trümmer da drüben an. Er nennt das eine \"harte\" Landung.\n\nKlar, wir wurden beschossen, und ich würde es ihm ja auch nachsehen, wenn er nicht immer so mit seinen Flugkünsten angeben würde!\n\nIch glaube, ich koche ihm ein paar Flügel, um ihm einmal einen Wink mit dem Zaunpfahl zu geben. Im Osten, im Tal der Knochen, findet Ihr Knochenhäuterbussarde. Ihre Flügel sind fleischig, dick und perfekt für meine Zwecke.", progress = "Ich kann es kaum erwarten, seinen Gesichtsausdruck zu sehen, wenn er reinhaut! Seit dem Absturz beschwert er sich, dass ich nur ans Essen denke. Nun, jemand muss uns schließlich ernähren, während er am Zeppelin herumschraubt!", completion = "Felshetzereier... Bämm!\n\nHölleneberspeck... Bämm!\n\nBussardflügel... Bämm! Bämm!\n\nWas für ein großartiges Essen. Ihr solltet wirklich mal probieren.", rewards = "Ihr bekommt:\n\nBussardbissenRezept: Bussardbissen"}
MultiLanguageQuestData['de'][9357] = {title = "Meldet Euch bei Aeldon Sonnenmal", objective = "Meldet Euch bei Aeldon Sonnenmal beim inneren Elfentor im Immersangwald.Wenn Ihr nach Arbeit sucht, dann sprecht mit Hauptmann Sonnenmal beim inneren Elfentor, geht einfach durch die Türen hinter mir.\n\nLasst mich jetzt in Ruhe, ich muss diesen Halunken verhören.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Wenn Ihr nach Arbeit sucht, dann sprecht mit Hauptmann Sonnenmal beim inneren Elfentor, geht einfach durch die Türen hinter mir.\n\nLasst mich jetzt in Ruhe, ich muss diesen Halunken verhören.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9358] = {title = "Waldläuferin Sareyn", objective = "Meldet Euch bei Waldläuferin Sareyn außerhalb von Morgenluft im Immersangwald.", description = "Betrachtet die Sicherheit dieses Orts nicht als selbstverständlich. Wir werden von der Geißel im Osten und von den Getriebenen im Westen belagert.\n\nWaldläuferin Sareyn sichert unsere Grenzen vor den Untoten, die uns von der Todesschneise her bedrängen. Folgt der Straße in Richtung Osten und erkundigt Euch, ob sie Unterstützung braucht.", progress = nil, completion = "Ihr seid hier, um zu helfen? Warum habt Ihr das nicht gleich gesagt? Wir können jede helfende Hand gebrauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9359] = {title = "Zuflucht der Weltenwanderer", objective = "Meldet Euch bei Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald.", description = "Ihr habt uns geholfen die Getriebenen wieder unter Kontrolle zu bekommen und dies war von unschätzbarem Wert. Die Weltenwanderer könnten jemanden wie Euch in ihrem Kampf gegen die Amanitrolle gebrauchen.\n\nHaltet nach der Zuflucht der Weltenwanderer nordöstlich von hier Ausschau, sprecht mit Leutnant Dämmerflucht und erkundigt Euch, ob sie Unterstützung braucht.", progress = nil, completion = "Ihr seid hier, um zu helfen? Ausgezeichnet!\n\nDer Kampf gegen die Amanitrolle hat uns sehr in Anspruch genommen und fähige Kämpfer wie Ihr sind stets willkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9360] = {title = "Angriff der Amani", objective = "Bringt die Invasionspläne der Amani zu Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.", description = "Ihr versteht zwar die Sprache dieser Schlachtpläne nicht, aber Ihr könnt klar eine Karte mit den eingetragenen Positionen der Zuflucht der Weltenwanderer und von Morgenluft ausmachen.\n\nAm besten informiert Ihr Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer darüber.", progress = "Was wollt Ihr mir zeigen?", completion = "Die Trolle haben uns hier festgehalten, während sie einen Angriff auf Morgenluft planten. Wir hatten nichts dergleichen erwartet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9361] = {title = "Hölleneber, die etwas andere Delikatesse", objective = "Legassi bei der Zeppelinabsturzstelle möchte, dass Ihr 8 Stück geläutertes Hölleneberfleisch sammelt. Um das Fleisch zu reinigen, schüttet die Läuterungsmischung über das besudelte Hölleneberfleisch, das Ihr von den Höllenebern gesammelt habt.", description = "Diese Eier sind wundervoll, aber was haltet Ihr davon, wenn wir noch einen Zahn zulegen?\n\nEine Scheibe Speck würde unser Mahl erst richtig abrunden, und ich weiß ganz genau, wo man sie herbekommen könnte.\n\nDieser Ort wimmelt nur so von Höllenebern. Natürlich kann hier niemand das Fleisch überprüfen und weichklopfen, aber wir haben Glück!\n\n<Legassi kramt in seinem Beutel und holt eine Flasche hervor.>\n\nDies wurde zwar nicht gemacht, um es mit Schweinefleisch zu benutzen, aber Improvisation ist alles!", progress = "Habt Ihr das Hölleneberfleisch erfolgreich geläutert?", completion = "Hmmm...\n\nEs sieht essbar aus, wenn man es richtig würzt. Erzählt Quack aber nicht, woraus sein Frühstück besteht, ja?", rewards = "Ihr bekommt:\n\nHölleneberspeck"}
MultiLanguageQuestData['de'][9362] = {title = "Kriegsherr Krellian", objective = "Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara.", description = "Die Zeit drängt, <Name>! Meine Orakelsprüche haben eine mächtige Quelle der Magie offenbart. Ich kann den Turm nicht verlassen und bitte Euch deshalb, diese bösartige Kreatur, die im Besitz dieses Artefakts ist, zu töten.\n\nDer erbärmliche Schwachkopf ist bekannt als Kriegsherr Krellian und versteckt sich hinter seinen Wachen im Tempel von Zin-Malor. Verbrennt ihn zu Asche und nehmt die prismatische Muschel, die er so begehrt, an Euch.", progress = "Es ist keine Zeit zu verlieren! Habt Ihr die Muschel?", completion = "Mh, diese Muschel wird wahrlich von einer seltsamen Aura umgeben. Es scheint geradezu angebracht, dass Eure Belohnung für die Wiederbeschaffung zum Teil daraus besteht, diese magischen Fähigkeiten zu testen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9363] = {title = "Warnt Morgenluft", objective = "Reist nach Morgenluft im Immersangwald und sprecht mit Waldläufer Degolien.", description = "Geht nach Morgenluft und klärt Waldläufer Degolien über die Pläne der Amani auf. Morgenluft muss sich auch nach dem Tod von Zul'marosh noch auf einen Angriff der Trolle vorbereiten. Sagt Degolien, dass ich ihm so schnell wie möglich Verstärkung schicken werde.", progress = nil, completion = "Die Informationen, die Ihr mir gebracht habt, sind von entscheidender Bedeutung, &lt;Name&gt;. Jetzt, da wir über die Pläne der Trolle Bescheid wissen, können wir uns auf einen Angriff vorbereiten.\n\nSie werden uns nicht ahnungslos überrumpeln.", rewards = "Geschwärzter KettengurtWeste des WaldläufersSatingefütterte StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9364] = {title = "Gespaltene Magie", objective = "Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück.", description = "Meine Untersuchungen haben den einzigartigen Zweck für die prismatische Muschel enthüllt.\n\nGreift die Grollflossen von Azshara mit Verwandlungszaubern an und tragt dabei diese Muschel bei Euch. Wenn Ihr einen Moment wartet, wird die chaotische Aura der Muschel dafür sorgen, dass sie sich für eine kurze Zeit in mehrere kleinere Versionen aufspalten. Tötet diese Kopien so schnell wie möglich, und deren gespaltene Essenzen werden in der Muschel gesammelt.\n\nKehrt zu mir zurück, sobald die Muschel gefüllt ist.", progress = "Habt Ihr die Magie eingesammelt?", completion = "Wunderbar! Prächtig!\n\nNun sind wir in der Lage, diese Magie zu einem neuen Zauber zu formen. Seht!", rewards = "Ihr erlernt:\n\nVerwandlung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9365] = {title = "Der Lohn des Diebes", objective = "Bringt die Flamme von Sturmwind zu (NAME).Die Flamme, die aus dem unmittelbaren Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", progress = nil, completion = "Ihr habt Euch heute bewiesen, &lt;Name&gt;.\n\nIch habe zwar nicht viel, das ich Euch geben könnte, aber bitte nehmt diese Krone, eine passende Belohnung für einen Eroberer. Möge sie Euren Weg erleuchten.", rewards = "Ihr bekommt:\n\nKrone des Sonnenwendfests"}
MultiLanguageQuestData['de'][9366] = {title = "Die Suche nach Teufelsblut", objective = "Ryathen der Düstere an der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 6 Teufelsblutproben von den Terrorbestien bringt, die bei den Teichen von Aggonar umherstreifen.", description = "Nordöstlich von hier liegen die Teiche von Aggonar. Vor langer Zeit waren sie ein Heiligtum der Draenei, doch fielen sie der Verderbnis anheim, als das Blut des Dämonen Aggonar in die heiligen Wasser vergossen wurde.\n\nObwohl es alt und verwässert ist, ist das Blut noch immer von einer enormen Macht erfüllt. Angetrieben durch die puren dämonischen Energien des ursprünglichen Blutes, durchstreifen Terrorbestien dieses Gebiet. Vernichtet sie und sammelt so viel von dem Teufelsblut ein, wie Ihr tragen könnt. Ich werde Euch fürstlich belohnen.", progress = "Das Teufelsblut... habt Ihr es bekommen, <Name>?", completion = "Die in den Proben gespeicherten Energien sind unfassbar stark, &lt;Name&gt;. Nun müssen wir nur noch sicherstellen, dass wir auch in Zukunft freien Zugriff auf das Teufelsblut haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9367] = {title = "Das Fest des Feuers", objective = "Wärmt Euch an den Freudenfeuern in Sturmwind, Eisenschmiede und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte.", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", progress = nil, completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", rewards = "Ihr bekommt:\n\nBrandblüteFeuriges Festgebräu"}
MultiLanguageQuestData['de'][9368] = {title = "Das Fest des Feuers", objective = "Wärmt Euch an den Freudenfeuern in Orgrimmar, Donnerfels und Unterstadt. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte.", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", progress = "Brennen alle Feuer?", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", rewards = "Ihr bekommt:\n\nBrandblüteFeuriges Festgebräu"}
MultiLanguageQuestData['de'][9369] = {title = "Wiederaufladen der Heilkristalle", objective = "Beschafft Euch 6 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental.", description = "Wir sind die Draenei. Unser Schiff ist hier abgestürzt und es gibt etliche Verwundete. Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!\n\nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.\n\nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.", progress = "Habt Ihr schon das benötigte Mottenblut für die Heilkristalle? Überlebende sind über das gesamte Tal verstreut und die Zeit drängt!", completion = "Wie bedauernswert, dass diese Kreaturen sterben mussten, damit wir überleben können - wahlloses Töten entspricht nicht dem Weg der Draenei. Wie auch immer, das von Euch gesammelte Blut wird unsere Heilkristalle wieder aufladen, somit war ihr Opfer nicht umsonst.", rewards = "Ausgebesserter LedergürtelAbgenutzte SchuheLeicht verrostete ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9370] = {title = "Stoppt das Säuberungsritual", objective = "Platziert den Signalstein bei den Teichen von Aggonar am Altar von Aggonar und besiegt alle Anachoreten der Draenei, die auf Eure Signal reagieren. Kehrt anschließend mit dem Signalstein zu Ryathen dem Düsteren bei der Falkenwacht zurück.", description = "Unsere Späher haben kürzlich einen Paladin der Draenei in der Nähe der Teiche von Aggonar aufgegriffen. Wir nehmen an, dass er vorhatte, an einem Säuberungsritual zur Reinigung der Teiche teilzunehmen. Natürlich müssen wir das Vorhaben der Draenei stoppen, oder unsere Teufelsblutquelle wird für immer versiegen.\n\nEr hatte diesen Signalstein bei sich. Offensichtlich hatte er den Auftrag, einen sicheren Ort zu markieren, an dem ein Priester - sie selbst nennen sich 'Anachoret' - in aller Sicherheit ein Säuberungsritual durchführen kann. Nehmt den Stein und platziert ihn am Altar von Aggonar und bereitet einen Hinterhalt für die eintreffenden Draenei vor.\n\nIch schlage vor, dass Ihr besser ein oder zwei Freunde mit Euch bringt.", progress = "Ihr seid zurückgekehrt, <Name>. Habt Ihr dem Aberwitz der Draenei ein Ende gesetzt?", completion = "Das wird diese heiligen Fanatiker lehren, sich um ihren eigenen Kram zu kümmern.", rewards = "Umhang des verlorenen AnachoretenAuf Euch wartet eine dieser Belohnungen:\n\nMedaillon der TeufelsmachtTeufelsblutband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9371] = {title = "Botanikerin Taerix", objective = "Sprecht mit Botanikerin Taerix bei der Absturzstelle im Am'mental.", description = "<Name>, Botanikerin Taerix braucht Eure Hilfe. Bitte, sucht sie bei ihren Lehrlingen außerhalb der Westseite des Schiffes auf.", progress = nil, completion = "Oh, welch Glück, dass Ihr hier seid! Wir haben Einiges zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9372] = {title = "Dämonische Verderbnis", objective = "Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel möchte, dass Ihr 6 Blutproben eines Höllenebers von bulligen Höllenebern sammelt.", description = "Willkommen im Posten des Cenarius, <Klasse>. Wir bekommen hier draußen nicht oft Besuch, daher freue ich mich ganz besonders über Eure Anwesenheit. Meine Arbeit mit den Lebewesen dieser trostlosen Umgebung macht es oft erforderlich, alleine in die abgelegensten Winkel zu reisen.\n\nDie Expedition des Cenarius hat mich mit dem Studium einiger der gefährlichsten Tiere der Scherbenwelt beauftragt, und dabei habe ich eine verblüffende Entdeckung gemacht. Obwohl viele Kreaturen bereits massive Veränderungen durchgemacht haben, scheint die Verderbnis noch immer neue Mutationen hervorzurufen. Ich habe mit dem Sammeln von Blutproben begonnen, um diese Veränderungen zu dokumentieren, und dabei ist mir jede Hilfe recht.", progress = "Habt Ihr die Blutproben bekommen?", completion = "Gute Arbeit, &lt;Name&gt;. Diese Blutproben werden mir bei meinen Forschungen, und der Expedition bei ihren Studien der Scherbenwelt und ihrer Lebewesen, sehr dienlich sein.\n\nWenn ich den Grund für die fortschreitende Veränderung der Tiere herausfinden könnte, könnte ich vielleicht ein Gegengift herstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9373] = {title = "Fehlender Schriftverkehr", objective = "Bringt den zerfressenen Lederkoffer zu Thiah Rotmähne in der Nähe der Ruinen von Sha'naar im westlichen Teil der Höllenfeuerhalbinsel.", description = "Bei der Untersuchung des ramponierten Lederkoffers stellt Ihr fest, dass die Beschädigung des Behälters von der ätzenden Flüssigkeit im Verdauungstrakt des Wurms herrühren muss. Das Leder scheint einst kunstvoll verarbeitet gewesen zu sein, aber die Verzierungen sind nicht mehr deutlich sichtbar.\n\nDas Einzige, was noch zu erkennen ist, ist ein abgenutztes Symbol des Zirkels des Cenarius. Da Ihr nichts über den Inhalt wisst, haltet Ihr es für das Beste, den Koffer zu einem Mitglied des Zirkels zu bringen.", progress = "Guten Tag, <Klasse>. Was bringt Euch in mein Lager?", completion = "Danke, dass Ihr mir dies hier gebracht habt, &lt;Klasse&gt;. Ich habe mich schon gewundert, warum ich so lange nichts mehr von der Expedition gehört habe. Ich frage mich, wie lange diese Nachricht schon unterwegs ist und was wohl aus ihrem Überbringer geworden ist.\n\nHier habt Ihr etwas Geld für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9374] = {title = "Arelions Tagebuch", objective = "Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Teichen von Aggonar reist und Arelions Tagebuch sucht.", description = "Mein Mann Arelion war seit unserer Ankunft in der Scherbenwelt von den Teichen von Aggonar fasziniert. Er verbrachte fast seine gesamte Zeit mit dem Studium der heimischen Schleimarten!\n\nVor einigen Tagen verschwand er spurlos. Man sagte mir, dass er tot sei und dass ich nichts mehr für ihn tun könnte.\n\nDoch was ich noch zu tun vermag, ist sicherzustellen, dass seine Forschungen nicht mit ihm gestorben sind. Begebt Euch zu den Teichen im Nordosten und haltet nach den Seiten seines Tagebuchs Ausschau. Er bewahrte sie immer in einem braunen Wanderknappsack auf.", progress = "Hattet Ihr Glück, <Name>? Die Teiche von Aggonar liegen nördlich der Höllenfeuerzitadelle.", completion = "Das Tagebuch meines Ehemanns... hat nicht das Geringste mit seinen Forschungen zu tun!\n\nWie konnte ich nur so blind sein? \"Die magischen Eigenschaften dämonisch beeinflusster Schleimformen\", beinahe hätte ich es geglaubt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9375] = {title = "Der Weg zur Falkenwacht", objective = "Beschützt die verwundete Blutelfenpilgerin auf Ihrem Weg zur Falkenwacht und sprecht dann mit Taleris Morgenblick.", description = "<Auf dem geschundenen Gesicht der Blutelfe zeichnet sich bei Eurem Anblick Erleichterung ab.>\n\nBitte, <Klasse>, holt mich aus diesem Käfig heraus! Ich bin der Gruppe aus Thrallmar, trotz Martik Tor'seldoris Warnungen, vorausgereist.\n\nSchreckliche Kreaturen lauerten mir auf. Ich glaube, es waren diese Felshetzer, von denen er immer sprach. Zunächst gelang es mir ihnen zu entkommen, doch das war erst der Anfang meiner Schwierigkeiten.\n\nIch verband gerade meine Wunden, als mich die Vogelmenschen fanden und zurück in ihre Höhle schleiften, wo sie mich in diesen Käfig sperrten! Ich muss unbedingt zur Falkenwacht!", progress = "Was braucht Ihr, <Klasse>?", completion = "&lt;Taleris ruft einige der Blutelfen aus dem Außenposten herbei.&gt;\n\nSchafft sie herein und versorgt ihre Wunden!\n\n&lt;Taleris wendet sich wieder Euch zu.&gt;\n\nSie kann sich glücklich schätzen, dass Ihr sie noch rechtzeitig gefunden habt, &lt;Klasse&gt;. Viel länger hätte sie dort draußen alleine nicht überlebt.\n\nKonntet Ihr verstehen, was sie gesagt hat?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9376] = {title = "Die Pflicht eines Pilgers", objective = "Die verletzte Blutelfpilgerin wurde von giftigen Stachelklauenfelshetzern angegriffen, als sie die Staubstachelschlucht erkunden wollte. Findet ihr Lager und haltet nach dem vermissten Beutel Ausschau.", description = "Diese verletzte Pilgerin schreit irgendwas von einem Beutel.\n\nHabt Ihr einen Beutel in der Nähe gesehen, als Ihr sie gefunden habt? Hmm...\n\nIhre Angreifer müssen sich damit aus dem Staub gemacht haben, als sie sie vertrieben hat. Die Stachelklauenfelshetzer aus der Schlucht im Süden sind bekannt dafür, dass sie einsame Reisende angreifen.\n\nWenn sie sich nicht beruhigt, kann ich ihre Wunden nicht behandeln. Ihre Sturheit könnte sie das Leben kosten.\n\nGeht zur Staubstachelschlucht und haltet nach ihrem Lager Ausschau. Ich möchte wetten, dass sie ihn da verloren hat.", progress = "Die Sache sieht nicht gut aus. So schafft sie es nie wieder auf die Straße. Habt Ihr den Beutel gefunden?", completion = "Vielen Dank, dass Ihr dies zurückgebracht habt, &lt;Name&gt;. Ich weiß nicht, was der verletzten Pilgerin an diesem Beutel so wichtig ist, aber sie lässt keinen an sich heran, bis sie ihn wieder hat.", rewards = "Segmentierte BrustplatteBeinschützer des SonnenwanderersBedeckung des PilgersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9377] = {title = "Hunger nach Macht", objective = "Beschafft eine potente Leerwandleressenz von den unkontrollierten Leerwandlern und kehrt anschließend zu Taleris Morgenblick in der Falkenwacht zurück.", description = "Falkenwacht ist ein stark besuchter Zwischenstopp für alle Pilger auf ihrer langen Reise in die Scherbenwelt. Obwohl wir einer der ersten Außenposten auf dem Weg in die Scherbenwelt sind, erreichen uns viele der Pilger in einem Zustand totaler Erschöpfung, ausgemergelt durch ihre Abhängigkeit.\n\nIn einer Welt wie dieser, versuchen die meisten von ihnen nun ihre Abhängigkeit von der Magie unter Kontrolle zu halten. Essen und Trinken helfen fürs Erste, <Klasse>, doch der Durst nach magischen Energien ist ihr stärkstes Verlangen. Die Überreste von Leerwandlern aus der Scherbenwelt sind eine mächtige Energiequelle, allerdings gibt es nicht viele davon, man findet sie lediglich bei den Sphärenfeldern.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9380] = {title = "Die Hatz nach mehr", objective = "Beschafft 6 unversehrte Sphärenhundkadaver und bringt sie zu Ausgrabungsleiter Murantus in der Ehrenfeste.", description = "Ich sage Euch, sollte ich noch einen Brief von Eisenschmiede bekommen...\n\nHabt Ihr jemals versucht, jemandem etwas zu erklären, der nicht zuhört, <Klasse>? Ich habe den Jungs in Eisenschmiede das von ihnen angeforderte Sphärenhundexemplar geschickt. Jetzt waren sie so frech und haben mir zurückgeschrieben, dass sie ein ganzes \"Rudel\" dieser Viecher möchten! Ein Rudel!\n\nIch habe ihnen also zu erklären versucht, dass Sphärenhunde Einzelgänger sind, aber es schert sie nicht. Ich bin es leid zu diskutieren. In der Gegend östlich der Festung findet Ihr sie. Beschafft sechs der besten und bringt sie hierher zurück?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9381] = {title = "Treffsichere Pfeile", objective = "Sammelt 8 Schwanzfedern eines Knochenhäuters von den Knochenhäutergeiern und bringt sie Falknerin Drenna Flusswind in der Falkenwacht.", description = "Mit dem Zustrom von Pilgern und dem Vordringen der Allianz, war die Falkenwacht in letzter Zeit ein sehr geschäftiger Ort. In meiner freien Zeit stelle ich normalerweise Pfeile für die Waldläufer her. Leider habe ich schon lange keine Zeit mehr dazu gehabt, die für die Pfeilherstellung notwendigen Federn zu beschaffen.\n\nEs wäre mir ein paar Münzen wert, wenn Ihr die Schwanzfedern von Knochenhäutern für mich einsammeln würdet. In der Vergangenheit habe ich diese Geier oft über den Knochen verendeter Kreaturen, nördlich der Falkenwacht, ausfindig gemacht.", progress = "Habt Ihr alle Federn beisammen?", completion = "Die sollten ihren Zweck erfüllen. Ich hatte schon befürchtet, dass den Waldläufern bald die Pfeile ausgehen, doch nun muss ich mir darüber erstmal keine Sorgen mehr machen. Vielen Dank für Eure Hilfe, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9383] = {title = "Ein gewagter Plan", objective = "Wendet den geweihten Kristall auf einen verwundeten unkontrollierten Leerwandler an. Kehrt anschließend zu Elsaana beim Tempel von Telhamat zurück.", description = "Die Blutelfen verkörpern den völlig unverantwortlichen Umgang mit den Mächten der Magie, <Klasse>. Sie kontrollieren die Magie nicht, nein, vielmehr sind sie ihre Sklaven und sie werden niemanden zwischen ihre Abhängigkeit und die magischen Energien kommen lassen, nach denen es ihnen dürstet. Die Blutelfen nutzen die Energien der Scherbenweltleerwandler, um ihre dämonische Magie zu wirken.\n\nIch habe einen Kristall mit einem Zauber aufgeladen, der es uns ermöglichen wird, einen Leerwandler zu neutralisieren und das magische Band zwischen ihm und dieser Welt zu zerschneiden. Ich habe die Leerwandler hauptsächlich in den Sphärenfeldern und südöstlich der Höllenfeuerzitadelle gesehen.", progress = "Habt Ihr die Magie des Kristalls gegen einen unkontrollierten Leerwandler eingesetzt?", completion = "Ihr habt Euch bewährt, &lt;Name&gt;. Es scheint, als würde der Verwahrungskristall fürs Erste standhalten, allerdings weiß niemand wie lange. Wir werden ihn im Auge behalten und in der Zwischenzeit noch mehr Kristalle vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9385] = {title = "Tobende Felshetzer", objective = "Tötet 10 Stachelklauenfelshetzer und kehrt anschließend zu Gremni Langbart auf der Höllenfeuerhalbinsel zurück.", description = "Also schickt uns die Ehrenfeste hierher, um mit den Arakkoa fertigzuwerden, und wir bauen unser Lager auf und denken uns hey, schön hier. Wir hatten ja keine Ahnung, dass wir so nahe bei den Stachelklauenfelshetzern sind.\n\nSie sind erbarmungslose Raubtiere und haben jegliche Arbeit unsererseits zunichtegemacht. Wenn Ihr Euch darum kümmert, würde ich Euch bezahlen. Habt Ihr Lust?", progress = "Macht Ihr Fortschritte im Kampf gegen die Felshetzer?", completion = "Gut gemacht, &lt;Name&gt;. Das wird den Biestern zeigen, wer hier der Boss ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9386] = {title = "Licht im Dunkeln", objective = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer.", description = "Ihr seid ziemlich eifrig, oder? Solltet Ihr Euch noch einmal in die Tiefen wagen, so bin ich gerne bereit, Euch dafür zu belohnen.\n\nSucht die Freudenfeuer in Stratholme, Scholomance, dem Düsterbruch und den Hallen der Schwarzfelsspitze auf. Ich erwarte Eure Rückkehr, <Name>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][9387] = {title = "Die Quelle der Verderbtheit", objective = "Reist zu den Ruinen von Sha'naar auf der Höllenfeuerhalbinsel und besorgt 5 dämonische Essenzen von den Zuchtmeistern der Illidari. Kehrt zu Apotheker Azethen in der Falkenwacht zurück, wenn Ihr die Aufgabe erfüllt habt.", description = "Unverderbte Draenei, wie dieser unglückliche Geselle hier, sind begabte Helden des Lichts. Welche Verderbtheit hat wohl ihr großartiges Volk dazu gebracht, sich zu Zerschlagenen und Verirrten zurückzuentwickeln?\n\nMir ist eine Theorie zu Ohren gekommen, die besagt, dass die Mutation von teuflischen Energien ausgelöst wurde. Ich würde diese Theorie gerne überprüfen.\n\nNordwestlich von hier findet Ihr die Ruinen von Sha'naar. Dort befinden sich einige einfache Zerschlagene unter dem Befehl der Zuchtmeister der Illidari. Bringt mir die dämonischen Essenzen der Zuchtmeister, damit ich sie an diesem Draenei ausprobieren kann.", progress = "Habt Ihr die Proben bekommen?", completion = "Ihr wart mir eine große Hilfe, &lt;Name&gt;. Nun wollen wir sehen, was wir von unserem blauen Freund lernen können.", rewards = "Klinge des gefallenen VerteidigersAuf Euch wartet eine dieser Belohnungen:\n\nZerrissener HalsreifRing des ermordeten Anachoreten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9388] = {title = "Lodernde Flammen in Kalimdor", objective = "Sucht die Freudenfeuer im Eschental, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer.", description = "Heute lodern zahlreiche Flammen in der Welt, <Name>. Die Feuer, die am schwierigsten zu unterhalten sind, leuchten grün; werden sie nicht ständig beaufsichtigt, brennen sie nicht lange. Versichert Euch für unseren Flammenbewahrer, dass die Smaragdfeuer in Kalimdor auch weiterhin lodern, eh?\n\nIhr findet sie in der Nähe von Ratschet im Brachland, unweit der Meistergleve in Dunkelküste, im Wald des Eschentals bei der Brücke nahe des Außenpostens der Silberschwingen und entlang der Hauptstraße im Steinkrallengebirge, in der Nähe der Straße, die zur Scherwindklippe führt.", progress = nil, completion = "Ahhh, sie brennen also noch. Das freut mich; es wäre nicht gut, wenn die Feuer vorzeitig erlöschen würden. Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt dies mit meinem Segen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes Smorc\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9389] = {title = "Lodernde Flammen in den Östlichen Königreichen", objective = "Sucht die Freudenfeuer im Vorgebirge des Hügellands, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer.", description = "Die Feuer des Sonnenwendfests lassen das Land traditionsgemäß im Licht unzähliger Flammen erstrahlen. Manche behaupten, dass die grünen Flammen die besten seien, da sie so schwierig zu unterhalten sind und eine solch ungewöhnliche Farbgebung haben.\n\nVersichert Euch für unseren Flammenbewahrer, dass die Feuer in den Östlichen Königreichen auch weiterhin lodern. Ihr findet sie in der Nähe von Dun Modr im Sumpfland, unweit von Lohenscheit im Silberwald, bei den Klippen zum Leuchtturm in Westfall und nahe dem zerstörten Turm im Vorgebirge des Hügellands.", progress = nil, completion = "Ihr seid also wieder da und habt die Smaragdflammen dieser Welt gesehen. Was sagt Ihr, mh? Ein mit Sicherheit seltener und wunderschöner Anblick. Natürlich weiß ich, dass eine handfeste Belohnung mehr Anklang findet... also bitte, nehmt dies für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes Smorc\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9390] = {title = "Die Suche nach Sedai", objective = "Anachoret Obadei möchte, dass Ihr östlich von hier auf der Höllenfeuerhalbinsel nach seinem Bruder Sedai Ausschau haltet.", description = "Hört mein Leid, <Klasse>. Mein Bruder Sedai ist schon vor längerer Zeit losgezogen, um den Orcs beim Posten der Mag'har eine Botschaft zu übermitteln. Als ein unverbesserlicher Idealist war er der Meinung, dass der Zeitpunkt nun gekommen sei, unsere Differenzen beizulegen und einen Friedensvertrag mit ihnen auszuhandeln.\n\nEr wird jetzt schon seit Tagen vermisst und ich befürchte das Schlimmste.\n\nWürdet Ihr für mich nach ihm Ausschau halten, damit ich endlich wieder Ruhe finde? Sedai müsste sich irgendwo in der östlichen Umgebung aufhalten.", progress = nil, completion = "Ihr habt den Leichnam eines jungen Paladins der Draenei gefunden. Es scheint, als hätte ihn jemand hinterrücks erschlagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9391] = {title = "Den Weg kennzeichnen", objective = "Waldläuferhauptmann Venn'ren an der Falkenwacht möchte, dass Ihr auf der Höllenfeuerhalbinsel die Große Kluft aufsucht und dort das südliche Leuchtsignal, westliche Leuchtsignal und das zentrale Leuchtsignal entzündet. Kehrt anschließend mit der brennenden Fackel zu ihm zurück.", description = "Nachdem die Felsklauenpopulation ausgedünnt ist, müssen wir die sichere Passage nur noch für unsere Pilger kenntlich machen. Nehmt diese Fackel und begebt Euch erneut in die Große Kluft. Sucht dort die drei Leuchtsignale, die den Verlauf des Pfads im Osten kennzeichnen.\n\nEntzündet die drei Signale und kehrt anschließend zu mir zurück. Doch seid gewarnt, das Entzünden eines Leuchtsignals zieht unweigerlich die Felsklauen aus der Umgebung an.", progress = "Habt ihr getan, worum ich Euch gebeten habe, <Name>?", completion = "Obwohl die große Kluft noch immer ein gefährlicher Ort ist, gibt sie einen brauchbaren Pfad für unsere Pilger ab.\n\nEin derartiger Akt der Verzweiflung ist unvermeidlich, solange die Allianz weiterhin sämtliche ein- und ausgehenden Straßen zur Falkenwacht beobachtet.", rewards = "Stulpen des LichtjüngersHandschuhe des FlammengebietersGürtel des PilgersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9392] = {title = "Ausbildung zum Schurken", objective = "Sprecht mit Pfadpirscher Avokor - dem Schurkenlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Schurken hier auf der Insel der Sonnenwanderer ist Pfadpirscher Avokor. Sprecht mit Avokor, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nAvokor - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", progress = nil, completion = "Die Schatten haben mir Euren Namen zugeflüstert, &lt;Name&gt;. Man sagt, dass Ihr nach jemandem sucht, der erfahren ist und Euch zeigt, wo's lang geht - jemandem wie mich. Ich bin durchaus gewillt, ja, aber es wird Euch jedes Mal etwas kosten, wenn ich Euch etwas beibringe. Ich werde Euch alles lehren, was es als &lt;Klasse&gt; zu beherrschen gilt.\n\nSolltet Ihr jedoch einmal auf frischer Tat ertappt werden, dann hat diese Unterhaltung nie stattgefunden, verstanden? Geht jetzt los und zeigt mir, was Ihr drauf habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9393] = {title = "Ausbildung zum Jäger", objective = "Sprecht mit Waldläuferin Sallina - der Jägerlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Jäger hier auf der Insel der Sonnenwanderer ist Waldläuferin Sallina. Sprecht mit Sallina, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nSallina - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", progress = nil, completion = "&lt;Name&gt;, sind Eure Augen so scharf wie die eines Falken, Eure Bewegungen so geschickt wie die eines Affen oder seid Ihr etwa so flink wie ein Gepard? Auf mich trifft all das zu und mit der richtigen Ausbildung vielleicht auch auf Euch. Ein &lt;Klasse&gt; zeichnet sich dadurch aus, dass er die Kreaturen dieser Welt zu beherrschen vermag, er seine Waffen treffsicher zu führen weiß und er in Situationen überlebt, die für andere den Tod bedeuten.\n\nIch werde Euch unterweisen, wenn Ihr auch wirklich dazu gewillt seid. Allerdings hat dies seinen Preis. Sollen wir beginnen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9394] = {title = "Wo ist Wyllithen?", objective = "Findet Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald.", description = "Der Nachtschimmergrundbewahrer ist verschwunden! Jemand muss vergessen haben, ihm zu sagen, dass er den Ort verlassen sollte, als der Magister und alle anderen es taten. Ich weiß, dass er sich noch irgendwo hier auf dem Grund aufhält, aber ich getraue mich nicht, selbst nach ihm zu sehen, da sich hier so viele magische Kreaturen herumtreiben.\n\nKönnt Ihr ihn für mich finden, <Klasse>? Bitte seht nach, ob er in Ordnung ist.", progress = nil, completion = "Wer seid Ihr? Ihr seid keiner von den Lehrlingen des Magisters, das steht fest!\n\nMan hat Euch sicherlich hierher geschickt, um mir dabei zu helfen, wieder Ordnung in dieses Chaos zu bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9395] = {title = "Saltherils Hafen", objective = "Sprecht mit Lord Saltheril in Saltherils Hafen im Immersangwald.", description = "Ich schwöre, dass ich jemandem einen Feuerball verpasse, wenn Lord Saltheril mir auch nur noch eine Lieferanfrage für seine endlosen Feste schickt. Sehe ich verdammt nochmal wie ein Festtagsplaner aus?! Unter uns gesagt, dieser Verrückte und seine Bande von Speichelleckern scheinen bis heute zu verdrängen, dass wir unter ständiger Belagerung stehen!\n\nEinige von uns sind doch tatsächlich mit, äh, ich weiß nicht... der verdammten Verteidigung unseres Königreichs, Quel'Thalas, beschäftigt?! Würdet Ihr mir einen Gefallen tun, <Klasse>? Seid doch so gut und reist für mich nach Saltherils Hafen und seht zu, dass er endlich Ruhe gibt! Es ist gleich die Straße runter, Richtung Westen.", progress = nil, completion = "Ah, Magistrix Morgenwandler hat zu guter Letzt doch noch auf meine simple Anfrage reagiert. Beizeiten werde ich Ihr Benehmen mit dem Lordregenten erörtern. Sie ist eine recht ungehobelte Person!\n\nNichts, worüber Ihr Euch Sorgen machen müsstet. Nun, wo Ihr schon mal hier seid, besteht vielleicht die Möglichkeit, dass ich endlich meine Vorräte für das Fest bekomme, auf die ich schon so lange warte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9396] = {title = "Die Magie der Arakkoa", objective = "Bringt 4 Rollen der Haal'eshi zu Arkanist Calesthris Morgenstern bei der Falkenwacht auf der Höllenfeuerhalbinsel.", description = "Die Scherbenwelt birgt viele Geheimnisse, <Name>. Es ist nur noch eine Frage der Zeit, bis wir sie alle enträtselt haben.\n\nDas Volk der halb Vogel, halb menschlichen Arakkoa verfügt über uraltes arkanes Wissen, welches sich als sehr nützlich für unsere Erforschung dieser Welt erweisen würde. Reist nach Süden zum Haal'eshbau. Nehmt alle magischen Rollen an Euch, die Ihr bei den Haal'eshi finden könnt und bringt sie mir.", progress = "Habt Ihr die Schriftrollen, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Die Geheimnisse der Scherbenwelt werden sich nicht lange vor uns verstecken können.\n\nEs ist unser Schicksal, die Meister dieser Welt zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9397] = {title = "Kommt ein Vogel geflogen", objective = "Reist zum Haal'eshbau auf der Höllenfeuerhalbinsel und durchsucht die Kalirinester nach einem jungen Kaliriweibchen. Benutzt den leeren Vogelkäfig, um es zu fangen, und kehrt anschließend zu Falknerin Drenna Flusswind in der Falkenwacht zurück.", description = "Die Arakkoa der Haal'eshi haben eine wunderschöne Vogelart, den Kaliri, domestiziert.\n\nMir ist es gelungen, ein junges Kalirimännchen einzufangen, und sie scheinen zähmbar zu sein. Die weiblichen Exemplare sind deutlich seltener, aber wenn es mir gelänge, eines davon zu ergattern, sollte ich in der Lage sein, sie selbst zu züchten. Es muss jedoch ein junges Weibchen sein, fast noch ein Küken. Ein alter Wildvogel würde die Gefangenschaft nicht lange überleben.\n\nNehmt diesen Käfig und reist nach Süden zum Haal'eshbau. Sucht nach Eiern, die kurz vor dem Schlüpfen stehen. Wenn Ihr mir ein junges Weibchen zurückbringt, werde ich Euch fürstlich belohnen.", progress = "Ihr seid zurück. Habt Ihr mir ein Kaliriweibchen mitgebracht?", completion = "Ihr habt es geschafft! Ihr habt ein junges Weibchen gefangen!\n\nSie ist wundervoll. Vielen, vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9398] = {title = "Tödliche Raubtiere", objective = "Späher Vanura im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr 8 Steinsichelwelpen und 4 Steinsichelalpha tötet.", description = "Die Zerschlagenen in der Scherbenwelt haben unendlich viel Grausamkeit ertragen müssen. Kein Wunder, dass sie sofort nach der Öffnung des Dunklen Portals scharenweise in der Hoffnung, diesem Land entfliehen zu können, dorthin gepilgert sind.\n\nZum Pech für unsere verwirrten Brüder und Schwestern sind sie für die Felsklauen, die in der Großen Kluft leben, eine leichte Beute. Geht dort hin und vernichtet einige der Felsklauen, damit unseresgleichen eine Chance hat.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Es ist immer schlimm, wenn Töten die einzige Möglichkeit ist, die bleibt, sogar wenn es sich um so gefährliche Biester wie die Steinsichelklauen handelt.\n\nIhr habt meinen Dank, dass Ihr diese grausame Aufgabe erledigt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9399] = {title = "Die Grausamkeit der Zuchtmeister", objective = "Reist zu den Ruinen von Sha'naar und erschlagt 4 Zuchtmeister der Illidari. Kehrt anschließend zu Ikan zum Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück.", description = "Sicherlich glaubt auch Ihr, dass die meisten Zerschlagenen bösartig sind, nicht wahr? In Wahrheit mangelt es vielen nur an geistiger Führung.\n\nIch war ebenfalls verloren, bevor ich die Omenai getroffen habe.\n\nUnser Verstand litt sehr unter der dämonischen Magie der Orcs. Man kann uns leicht in die Irre führen und ausnutzen.\n\nDämonen, die mit Illidan verbündet sind, überfallen täglich die Höllenfeuerhalbinsel und verschleppen unseresgleichen als Sklaven. Doch mit den Omenai kam die Hoffnung. Reist zu den Ruinen von Sha'naar, südwestlich von hier, und tötet die Zuchtmeister der Illidari, damit mein Volk endlich wieder frei ist!", progress = nil, completion = "Ihr habt es geschafft! Wir stehen tief in Eurer Schuld, &lt;Name&gt;. Seht Euch nur all die Ankömmlinge des Lumpenpacks an.\n\nUnter meiner geistigen Führung werden sie alles über die alten Traditionen lernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9400] = {title = "Der Assassine", objective = "Nazgrel möchte, dass Ihr zu der Straße nördlich der Höllenfeuerzitadelle reist und nach einem Assassinen namens Krun Rückenbrecher Ausschau haltet.", description = "<Name>, wir haben erst kürzlich einen Plan zur Ermordung unseres Gesandten in der Falkenwacht aufgedeckt. Spione der Höllenfeuerzitadelle haben von unseren Plänen, eine Expedition zur Wacht auszusenden, erfahren und einen Hinterhalt vorbereitet.\n\nUnsere Späher berichteten mir, dass ein Assassine namens Krun Rückenbrecher auf der Straße nördlich der Zitadelle in Stellung gegangen ist. Begebt Euch dorthin und tötet diesen Assassinen. Macht den Höllenorcs klar, dass man mit uns keine Spielchen treibt.", progress = nil, completion = "Der Leichnam stimmt mit der Beschreibung von Krun Rückenbrecher, dem Assassinen der Höllenfeuerzitadelle, überein. Als Ihr den noch warmen Körper umdreht, erblickt Ihr eine Steinaxt, die in seinem Rücken steckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9401] = {title = "Eine seltsame Waffe", objective = "Bringt die schwere Steinaxt zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Ihr zieht die Steinaxt aus dem toten Körper, um sie eingehender zu untersuchen. Irgendetwas an der Verarbeitung der Axt ist ungewöhnlich.\n\nSie scheint orcischen Ursprungs zu sein und dennoch besteht sie aus einem Material, das Ihr noch nie zuvor gesehen habt. Nazgrel wäre bestimmt daran interessiert, die Axt weiter zu untersuchen.", progress = "Sagt mir, ist der Assassine tot?", completion = "Er wurde mit dieser Waffe getötet? Das ist unmöglich!\n\nHaben wir... haben wir sie tatsächlich gefunden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9402] = {title = "Fangt!", objective = "Taucht auf den Grund des Stillwispertümpels und holt die Azurphiole für Instrukteur Antheol.", description = "So... Ihr seid <Name>, oder? Fühlt Euch nicht geschmeichelt, ich kenne Euren Namen, einer meiner Schüler ist bei Euch herumscharwenzelt und plappert ununterbrochen.\n\nHmm... wenn Ihr <ihn/sie> beeindrucken möchtet, warum helft Ihr mir dann nicht aus? Auf dem Grund des Stillwispertümpels hinter mir liegt eine Azurphiole. Taucht in die Tiefe, schnappt sie Euch und bringt sie zu mir.", progress = "Wie ist das Wasser?", completion = "Oh, gut gemacht... ich sagte Ihr sollt in den Tümpel springen und Ihr habt es getan. Ich kann mir gut vorstellen, was Ihr tun würdet, wenn einer Eurer Freunde Euch um etwas bitten würde.\n\nWollt Ihr für Eure Mühe belohnt werden, dann ist es das: macht keinen Finger krumm, bevor Ihr nicht wisst, was dabei für Euch herausspringt. Der Geist des Magiers ist seine stärkste Waffe. Vergesst das nicht und versucht Euren ein wenig mehr anzustrengen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9403] = {title = "Das reinste Wasser", objective = "Instrukteur Antheol möchte, dass Ihr die Azurphiole bei den Elrendarfällen auffüllt.", description = "Jetzt, da Ihr eine kleine Lektion gelernt habt, bitte ich Euch etwas Handfesteres an. Es betrifft Eure Fähigkeiten der Selbstverteidigung. Ihr solltet natürlich nur im äußersten Notfall von Nahkampftechniken Gebrauch machen, aber deshalb sollte man trotzdem nicht unvorbereitet sein.\n\nIch kann Euch bei der Herstellung eines Stabs helfen, der einem Magier Eures Ranges gerecht wird. Nehmt die Phiole, die Ihr für mich besorgt habt, und füllt sie bei den Elrendarfällen auf. Folgt einfach dem Fluss südöstlich von hier.", progress = "Nur das Wasser von den Elrendarfällen hat die erforderliche Reinheit für den Gebrauch von Magie. Habt Ihr es?", completion = "Mal sehen, was Ihr mir gebracht habt...\n\n&lt;Er hält die Phiole gegen das Licht und studiert sie genau.&gt;\n\nJa, das sollte es sein. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9404] = {title = "Noch lebendig", objective = "Tötet die Immersangwaldbehüter bis Ihr einen lebendigen Zweig für Instrukteur Antheol findet.", description = "Ihr habt vielleicht die wandelnden Bäume nahe der Elrendarfälle bemerkt. Als Behüter der Natur sind sie mit urzeitlicher Magie erfüllt, die wir mithilfe des reinem Wassers, das Ihr mir gebracht habt, umformen und für unsere Zwecke verwenden können.\n\nUnglücklicherweise sind die Waldbehüter knorrige und verdrehte Kreaturen, so dass Ihr womöglich erst einige töten müsst, bevor Ihr einen brauchbaren Zweig findet.", progress = "Habt Ihr den lebendigen Zweig? Schnell, gebt ihn mir!", completion = "Ihr seid meiner Bitte nachgekommen, &lt;Name&gt;. Ihr könnt Eure Belohnung jetzt entgegennehmen.", rewards = "LeystabAuf Euch wartet eine dieser Belohnungen:\n\nLeykugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9405] = {title = "Das Anliegen des Kriegshäuptlings", objective = "Bringt die schwere Steinaxt zu Scharfseherin Regulkut in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Wie Ihr wisst, steht der Kriegshäuptling aus ganzer Kraft hinter dieser Expedition und das aus gutem Grund. Dies ist unsere Heimatwelt. Hier liegen unsere Wurzeln.\n\nDiese Reise hat für Orcs und Blutelfen gänzlich unterschiedliche Bedeutung. Für sie ist es die Suche nach dem gelobten Land. Für uns ist es die Rückkehr in unsere lange verlorene Heimat.\n\nWer auch immer diese Axt gefertigt hat, ist mit den alten Traditionen vertraut. Wir müssen Kontakt zu ihnen aufnehmen. Diese Angelegenheit ist zu wichtig, als dass wir reguläre Methoden des Aufspürens verwenden. Zeigt Scharfseherin Regulkut die Waffe; sie wird wissen, was zu tun ist.", progress = "Sagt mir, wonach Ihr sucht, damit ich Euch bei der Suche unterstützen kann.", completion = "Ich verstehe Nazgrels Anliegen, &lt;Klasse&gt;. Sagt nichts weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9406] = {title = "Die Mag'har", objective = "Bringt den Brief von den Mag'har zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Diese Neuigkeiten, die Ihr von jenseits des Dunklen Portals bringt... Ihr wollt mir ernsthaft Glauben machen, dass der Sohn Durotans über die jenseitigen Länder geherrscht hat? Frei von dämonischem Einfluss? Und nun sind seine Leute in diese Welt zurückgekehrt?\n\nUm Euretwillen hoffe ich, dass das nicht irgendein perfider Witz sein soll, <Klasse>. Es ist schwer zu beschreiben, was dies für mein Volk bedeutet. Ich werde umgehend eine Botschaft nach Nagrand schicken! Höllschrei muss davon erfahren.\n\nBringt diesen Brief zu Eurem Anführer in Thrallmar. Sagt ihm, die Mag'har heißen Euch willkommen!", progress = "Was habt Ihr für uns, <Name>?", completion = "Seid Ihr sicher? Wahre Orcs, hier auf der Höllenfeuerhalbinsel! Das sind große Neuigkeiten, &lt;Name&gt;.\n\nDer Kriegshäuptling muss umgehend davon in Kenntnis gesetzt werden.", rewards = "Zeremonielle RobenGamaschen der DonnerschmiedeStammeshalsbergeGrollhufbalgmaskeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9407] = {title = "Durch das Dunkle Portal", objective = "Reist durch das Dunkle Portal und meldet Euch bei Generalleutnant Orion. Er erwartet Euch auf der anderen Seite - in der Scherbenwelt.", description = "Viele Jahre stand das Dunkle Portal still... vergessen. Aber nun ist es nicht mehr still.\n\nNachdem der Angriff der Dämonen aufgehalten wurde, haben unsere Truppen das Portal durchschritten und sich den Dämonen auf ihrem eigenen Gebiet gestellt!\n\nNun sind wir in einem wilden Krieg gefangen, und einige sind der Meinung, dass wir ihn nicht gewinnen können. Es ist also unsere Pflicht und unser grausames Vergnügen, unsere Feinde in der Scherbenwelt zu bekämpfen und unseren Sieg zu sichern, <Name>.\n\nWenn Ihr uns helfen wollt, meldet Euch unverzüglich bei Generalleutnant Orion. Er erwartet Euch in der Scherbenwelt...", progress = nil, completion = "Unser Expeditionskorps kam ohne Probleme durch das Portal und hat ein neues Lager namens Thrallmar errichtet. Aber wie Ihr sehen könnt ist die Brennende Legion eingefallen und hat uns von unseren Brüdern abgeschnitten. Die Dämonen sind eindeutig darauf aus, das Dunkle Portal einzunehmen und uns daran zu hindern, Verstärkung aus Azeroth zu holen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9408] = {title = "Vergessene Helden", objective = "Sprecht mit Truppenkommandant Danath Trollbann in der Ehrenfeste.Auch wenn es mich traurig macht, dass wir so viele Soldaten bei dem Versuch, das Portal zu durchbrechen, verloren haben, erfüllt es mich doch mit Stolz, dass das ursprüngliche Expeditionskorps noch am Leben ist.\n\nIch kann es kaum glauben, aber dort stehen sie - ein Zeichen für die Entschlossenheit der Allianz.\n\nIn dieser Festung steht einer unserer großartigsten Helden: Danath Trollbann! Geht zu ihm, <Klasse>. Er hat schon all unsere Soldaten getroffen und mit ihnen gesprochen. Er möchte Euch sicher kennenlernen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Auch wenn es mich traurig macht, dass wir so viele Soldaten bei dem Versuch, das Portal zu durchbrechen, verloren haben, erfüllt es mich doch mit Stolz, dass das ursprüngliche Expeditionskorps noch am Leben ist.\n\nIch kann es kaum glauben, aber dort stehen sie - ein Zeichen für die Entschlossenheit der Allianz.\n\nIn dieser Festung steht einer unserer großartigsten Helden: Danath Trollbann! Geht zu ihm, <Klasse>. Er hat schon all unsere Soldaten getroffen und mit ihnen gesprochen. Er möchte Euch sicher kennenlernen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9409] = {title = "Eilige Lieferung!", objective = "Bringt die Phiolensammlung zu Zalduun bei der Absturzstelle im Am'mental.", description = "Da Ihr jetzt alles besorgt habt, was zum Wiederaufladen der Heilkristalle benötigt wird, müsst Ihr die Phiolen zu unserem Priester Zalduun bringen. Er kümmert sich um die Verwundeten innerhalb der zentralen Kammer des Schiffes.", progress = "Hallo, <Klasse>. Was habt Ihr da? Ist das für mich?", completion = "Gute Arbeit! Das wird die erschöpften Heilkristalle wieder aufladen.\n\nDa Ihr nun schon einmal hier seid... ich hätte da noch eine Aufgabe für Euch, solltet Ihr gewillt sein?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9410] = {title = "Spirituelle Führung", objective = "Verwendet das Wolfstotem an dem Ort, wo Ihr Krun Rückenbrechers Leichnam gefunden habt und folgt dem Ahnengeistwolf.", description = "Selbst die Sinne unserer besten Spürwölfe können sich irren, <Name>. Die Geister jedoch, haben eine andere Sicht auf diese Welt. Das Wesen, welches Ihr beschwören werdet, wird die von Euch gesuchte Person ausfindig machen, denn es spürt nicht dem Geruch des Gesuchten hinterher sondern seiner Essenz.\n\nGeht jetzt, <Klasse>, nehmt dieses Totem mit Euch und benutzt es an dem Ort, wo Ihr die Steinaxt gefunden habt.", progress = "Ihr könnt froh sein, dass Ihr noch lebt.", completion = "Wer seid Ihr, dass Ihr hier so einfach unangekündigt umherwandert? Ich habe meine Männer nur zurückgehalten, weil Ryga die Anwesenheit der Geister in Eurer Nähe verspürte.\n\nIhr könnt frei sprechen, doch wählt Eure Worte mit Bedacht. Wir vertrauen normalerweise keinen Fremden, die hier so nah bei der Zitadelle umherstreifen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9415] = {title = "Meldung bei Marschall Himmelswand", objective = "Sprecht mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", description = "Gehört Ihr zu Marschall Himmelswands neuen Rekruten? Natürlich.\n\nAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?\n\nLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.", progress = nil, completion = "Die Allianz braucht jeden tauglichen Rekrut, den sie bekommen kann. Die Horde hat ständig Verstärkung vom nördlichen Kontinent bekommen, wir mussten kämpfen, um überhaupt standzuhalten.\n\nLasst Euch die Lage von mir schildern.", rewards = nil}
MultiLanguageQuestData['de'][9416] = {title = "Meldung bei General Kirika", objective = "Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", description = "Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.\n\nDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.\n\nLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.", progress = nil, completion = "Es ist gut, dass Ihr hier seid, aber wir haben keine Zeit für überflüssige Worte. Was Ihr braucht, sind Anweisungen, und dann müsst Ihr losziehen.\n\nHört gut zu.", rewards = nil}
MultiLanguageQuestData['de'][9417] = {title = "Die Arakkoabedrohung", objective = "Gremni Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Windspäher der Haal'eshi und 6 Krallenwachen der Haal'eshi tötet.", description = "Die Arakkoa sind hochintelligente Wesen... genauso gerissen wie Gnome. Nur, dass sie über ein aggressives Gemüt und ein Händchen für Magie verfügen.\n\nIn letzter Zeit haben sie häufiger Patrouillen der Ehrenfeste überfallen, was auch der Grund für unsere Anwesenheit hier ist. Wisst Ihr, Mirren und ich sind weltbekannte Scharfschützen, ja, das sind wir! Allerdings sind wir eher auf Federvieh und Wildtiere spezialisiert... nicht auf diese Blitze schleudernden Vogelmenschen.\n\nWas sagt Ihr, greift Ihr uns in dieser Sache etwas unter die Arme? Ihr findet den Haal'eshbau im Südosten.", progress = nil, completion = "Fantastische Arbeit, &lt;Name&gt;! Ich ernenne Euch hiermit zum Langbart ehrenhalber.\n\nBleibt noch ein Weilchen und trinkt etwas mit uns!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9418] = {title = "Avruus Kugel", objective = "Bringt Avruus Kugel zum Altar der Haal'eshi südöstlich des Haal'eshbaus auf der Höllenfeuerhalbinsel und gebt sie Aeranas, sobald er frei ist.", description = "<Als Ihr die Kugel näher an Euer Ohr haltet, hört Ihr, wie Euch eine Stimme anspricht.>\n\nIhr seid kein Arakkoa, wie ich spüre. Deswegen werde ich versuchen, Euch einen Handel für meine Freiheit vorzuschlagen. Mein Name ist Aeranas. Ich regierte einst über die östlichen Winde. Der Magier der Haal'eshi, Avruu, hat mich in dieser Kugel eingefangen.\n\nSucht den Altar der Arakkoa, mit dessen Hilfe sie mich versklavt haben. Er ist südöstlich vom Bau der Arakkoa versteckt. Nähert Euch ihm mit der Kugel und gebt sie mir, sobald ich frei bin. Als Ausgleich für meine Freiheit werde ich Euch einen mächtigen Schatz geben!", progress = "Endlich habe ich meine Freiheit wieder!", completion = "Mit dieser Kugel erlange ich meine Freiheit wieder. Nehmt Eure Belohung, Sterblicher, auf dass meine Schuld bezahlt sei.", rewards = "Umhang des WindsprechersAuf Euch wartet eine dieser Belohnungen:\n\nSiegelring von AeranasAnhänger des Windtänzers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9419] = {title = "Durchkämmen der Wüste", objective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", description = "Wir hatten vor Kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.\n\nWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.\n\nWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.", progress = "Seid da draußen auf der Hut und beeilt Euch besser. Wir haben keine Zeit zu verlieren.", completion = "Dem Licht sei Dank, Eure Suche war erfolgreich.\n\nHätten wir nur eher damit begonnen, dann wären wir jetzt nicht in einer so verzweifelten Notlage. Wir müssen verhindern, dass die Schätze der Wüste in die Hände der Horde fallen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErheblicher HeiltrankErheblicher Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9420] = {title = "Feinste Daunen", objective = "Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 8 Kalirifedern von den Kaliris im Haal'eshbau bringt.", description = "Die Arakkoa das Haal'eshbaus südlich von hier züchten eine besonders prächtige Art von Vögeln, namens Kaliri. Ihre Federn würden mir in den Handelsposten Azeroths einen ganz schönen Batzen Gold einbringen. Denkt nur an all das viele Bier, das ich mir leisten könnte!\n\nIch sag Euch was, bringt mir eine Ladung Kalirifedern und ich gebe Euch meinen Hut. Was sagt Ihr dazu? So einen Hut wie diesen hier, werdet Ihr nirgendwo sonst finden! Sind wir im Geschäft?", progress = "Habt Ihr die Kalirifedern, <Klasse>?", completion = "Ihr habt Euren Teil der Abmachung erfüllt. Ich schätze, Geschäft ist Geschäft!\n\nHier, mein Freund. Passt gut auf ihn auf.", rewards = "Ihr bekommt:\n\nMirrens alkoholischer Hut"}
MultiLanguageQuestData['de'][9421] = {title = "Ausbildung zum Schamanen", objective = "Ich bin Firmanvaar und mich aufzusuchen war weise von Euch. Ich bin dazu berufen, Schamanen den richtigen Weg zu weisen, besonders denen, die wie Ihr noch unerfahren sind.\n\nDer Schamanismus wird von uns <Volk> gerade erst wiederentdeckt, <Name>. Ihr seid wahrhaft mutig, dieser Lehre zu folgen, denn unter Unseresgleichen wird sie mit Argwohn betrachtet.\n\nIch bin hier, solltet Ihr meine Unterweisung wünschen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9422] = {title = "Durchkämmen der Wüste", objective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", description = "Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.\n\nDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.\n\nWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe, Ihr werdet uns unterstützen.", progress = "Hütet Euch vor den Gefahren der Wüste, <Name>. Die Allianz könnte hinter jeder Düne lauern und jeder Schritt könnte somit Euer letzter sein.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Diese Ressourcen kommen sofort zum Rest der Vorräte. Jedes Bisschen trägt zu unserem Sieg und zur Schwächung unserer Feinde bei.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErheblicher HeiltrankErheblicher Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9423] = {title = "Rückkehr zu Obadei", objective = "Kehrt zu Anachoret Obadei beim Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück und berichtet ihm von Sedais Tod.", description = "Jetzt, da sich Sedais Tod bestätigt hat, liegt es an Euch, Obadei die traurige Nachricht zu überbringen.", progress = nil, completion = "Sedai, mein geliebter Bruder... \n\nDiese feigen Orcs! Er war unbewaffnet, wie konnten sie nur?\n\nLasst mich alleine, &lt;Name&gt;. Ich danke Euch für Eure Hilfe, doch ich brauche jetzt etwas Zeit für mich selbst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9424] = {title = "Makurus Rache", objective = "Makuru im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 10 Ahnenperlen der Mag'har bringt.", description = "Sedai war für Makuru wie ein Bruder. Ich schulde ihm mein Leben und noch weit mehr! Sie sagen, Makuru sei verrückt, doch wenn die Omenai nach seinem Tod nichts tun wollen, dann sind sie die wahren Verrückten!\n\nMakuru kann in dieser Welt nicht viel sein Eigen nennen, aber ich werde Euch mit Freuden meinen einzigen Besitz überlassen, wenn Ihr Sedai rächt. \n\nIch habe die braunen Orcgrunzer schon mal gesehen, oben in den Bergen, im Nordosten. Sie hassen uns! Sie haben unser Mitleid nicht verdient! Geht und rächt Sedais Tod. Bringt mir ihre Ahnenperlen als Beweis!", progress = "Habt Ihr Sedai in Makurus Namen gerächt?", completion = "Ja... Rache! Ihr wart gut.\n\nNehmt dies, es war ein Geschenk von Sedai. Wenn Makuru es behält, stimmt es ihn nur traurig.", rewards = "Sedais KlingeAuf Euch wartet eine dieser Belohnungen:\n\nSedais HalsketteSedais Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9425] = {title = "Bericht an Tarrens Mühle", objective = "Reist nach Tarrens Mühle im Vorgebirge des Hügellands und sprecht mit Beraterin Morgenabend.", description = "Ah, gut Euch hier zu sehen, <Klasse>! Ich habe eine Aufgabe, die wie für Euch gemacht ist.\n\nAls neue Mitglieder der Horde müssen wir dafür sorgen, dass wir sie bei ihren Unternehmungen unterstützen und bei ihren Problemen helfen. Dann werden sie uns auch bereitwilliger bei unseren helfen.\n\nReist zum Dorf der Verlassenen, Tarrens Mühle, im Vorgebirge des Hügellands im Südwesten. Meldet Euch bei Beraterin Morgenabend, wenn Ihr da seid.", progress = nil, completion = "Sieh an, sieh an! Noch einer meiner Brüder um einzuspringen. Gut! Unsere Freunde von den Verlassenen brauchen sehr viel Hilfe, &lt;Klasse&gt;. Fragt herum, wo Ihr Euch nützlich machen könnt.\n\nIch weiß, dass Ihr sie nach bestem Wissen und Gewissen unterstützen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9426] = {title = "Die Teiche von Aggonar", objective = "Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar geht und 6 Teufelsblutschrecken und 6 mörderische Faulschleime tötet.", description = "Seit den Tagen, in denen wir dieses Land Draenor nannten, hat sich viel geändert. Teile des Landes wurden durch die Verderbtheit der Dämonen für immer verwandelt.\n\nDazu gehören die Teiche von Aggonar. Einst befanden sich an diesem Ort die heiligen Quellen unseres Volkes. Das Blut des Dämonen Aggonar hat die Essenz des geheiligten Wassers verschmutzt. Dieses teuflische Blut hat verderbte Kreaturen vorgebracht, die ausgelöscht werden müssen, wenn wir die Teiche jemals zurückfordern möchten. Reist von hier aus nach Osten und tötet die Teufelsblutelementare und den Schleim, der sich in den Teichen herumtreibt.", progress = nil, completion = "Ja, ich fühle, wie die teuflische Präsenz in den Teichen abnimmt.\n\nIhr habt gute Arbeit geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9427] = {title = "Reinigung des Wassers", objective = "Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar reist und die Reinigungsphiole bei Aggonars Leiche benutzt. Kehrt zu ihm zurück, wenn Ihr das Wasser von Aggonars Essenz befreit habt.", description = "Ich muss euch bitten, das, was wir angefangen haben, zu Ende zu bringen. Jetzt, da der teuflische Einfluss nachgelassen hat, müsst Ihr diese Reinigungsphiole nehmen und sie auf den Ursprung der Verderbnis schütten, Aggonars Leiche.\n\nIhr könnt die Knochen des Dämonen am nördlichen Ende der Teiche finden. Aber seid vorsichtig, seine Essenz ist immer noch nicht ganz aus dieser Welt verschwunden.", progress = "Ich seid zurück, <Name>. Ist das Wasser gereinigt?", completion = "Die Essenz von Aggonar lebte in seinem verderbten Nachkommen Aggonis weiter. Dank Eures Erfolgs gegen den Dämon können wir nun beginnen, die Teiche zu ihrer ursprünglichen Reinheit zurückzuführen.\n\nIhr habt unseren Dank, &lt;Name&gt;. Eure Arbeit hat einen tiefen Eindruck in dieser Welt hinterlassen.", rewards = "DämonentöterhandgelenksschützerAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger von TelhamatAmaans Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9428] = {title = "Bericht an den Splitterholzposten", objective = "Reist zum Splitterholzposten im Eschental und sprecht mit Berater Sonnenschwur.", description = "<Die Botschafterin senkt die Stimme und beugt sich zu Euch.>\n\nEuer Ruf eilt Euch voraus, <Name>. Ich möchte, dass Ihr zum Splitterholzposten im Eschental reist. Zu Fuß gelangt man am einfachsten durch Durotar, das Brachland und dann an der Weggabelung nach Norden dorthin.\n\nWenn Ihr dort angekommen seid, sprecht mit Berater Sonnenschwur. Reist vorsichtig, das Eschental kann sehr gefährlich sein!", progress = nil, completion = "Die Botschafterin hat uns bereits informiert, wir haben Euch schon erwartet.\n\nSie möchte, dass Ihr hier so viel tut, wie Ihr nur könnt, um uns zu helfen. Sie sprach davon, unsere Freundschaft zum Rest der Horde zu festigen.\n\nFragt herum - weiter hinten im Posten gibt es Einige, die Eure Hilfe benötigen. Ich habe auch gehört, dass es einen weiteren Außenposten der Horde, den Außenposten von Zoram'gar, an der Küste ganz im Westen gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9429] = {title = "Reist nach Dunkelhain", objective = "Reist nach Dunkelhain im Dämmerwald und sprecht mit Anachoret Delan.", description = "Mir wurde gesagt, dass es einen Dorn in der Seite des Königreichs von Sturmwind gibt, Dämmerwald genannt. Dieser Ort ist erfüllt vom bösen und niederträchtigen Gestank des Untodes.\n\nDa wir versuchen, so gut wie möglich zu helfen, möchte ich, dass Ihr nach Südosten zu der größeren Menschensiedlung Dunkelhain reist. Anachoret Delan wird dort auf Eure Ankunft warten.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Ich hoffe, Eure Reise hierher war angenehm.\n\nDie armen Seelen hier werden von allen Seiten von den Kreaturen der Nacht bedroht. Wir wünschen daher, dass Ihr ihnen so viel Hilfe wie möglich dabei zukommen lasst, die Dunkelheit zurückzudrängen.\n\nSeht Euch im Dorf um und lernt seine Einwohner kennen. Bitte, &lt;Name&gt;, helft ihnen, wo immer Ihr könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9430] = {title = "Relikte von Sha'naar", objective = "Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Ruinen von Sha'naar reist und 10 Relikte von Sha'naar einsammelt.", description = "Wie ich es Euch bereits sagte, ich brauche mein Augenlicht nicht, um zu sehen, was andere nicht zu erkennen vermögen. Ich werde nicht verurteilen, was Ihr in Makurus Namen getan habt, dennoch denke ich, Ihr solltet über das, was Euch Eure Augen zeigen, hinausblicken.\n\nReist zu den Ruinen von Sha'naar im Südwesten und sammelt so viele Relikte ein, wie Ihr finden könnt. Wenn es das Schicksal so will, werdet Ihr finden, was wir brauchen.\n\nDie Bedeutung meiner Bitte mag Euch im Moment unklar sein, doch habt vertrauen, <Name>. Der Geduldige wird erleuchtet werden.", progress = "Habt Ihr die Relikte aus Sha'naar bei Euch, <Name>?", completion = "Das Glück hat Euch gesegnet. Genau wie ich es erhofft hatte, habt Ihr ein ganz besonderes Relikt zwischen all den anderen gefunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9431] = {title = "Eine andere Lösung", objective = "Sammelt 2 Handvoll reinigende Erde von den donnernden Felskloppern und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten.", description = "Was hat es zu heißen, wenn ein Sin'dorei auf dem Gipfel einer vom Wind gepeitschten Plattform in Tausend Nadeln steht anstatt in den Hallen von Silbermond?\n\nGanz einfach. Meine Brüder wollen mich nicht mehr haben. Jede Abschrift meiner Abhandlung über die natürliche Heilung unserer Abhängigkeit wurde verbrannt.\n\nIch kann meine Forschungen hier sicher fortsetzen, aber ich habe keine Reagenzien. Wenn Ihr bereit wärt, etwas reinigende Erde von den donnernden Felskloppern am westlichen Ende der Nadeln zu besorgen und zu meinem Verbündeten beim Weißgipfelposten zu bringen, wäre ich Euch sehr dankbar.", progress = "Magistrix Elosais Nachricht ist ein wenig rätselhaft, aber ich glaube, ich verstehe, was sie von mir will. Wenn Ihr die Erde habt, von der sie spricht, dann kann ich sie in das Gefäß füllen, das Ihr für das Wasser des Mondbrunnens braucht.", completion = "Was? Sie hat nichts von dem Mondbrunnen gesagt? Aber sie wusste doch die ganze Zeit, dass sie das Wasser brauchen würde? Ich weiß, das Ganze ist etwas verrückt, aber ich bin niemand, der einen Kunden wegscheucht, vor allem nicht, wenn es mein einziger ist.\n\nZugegeben, sich in eine Elfensiedlung einzuschleichen und das Wasser aus ihrem Mondbrunnen zu stehlen ist nicht unbedingt das Klügste, was ich je für einen Kunden getan habe, aber ihr Gold ist so gut wie jedes andere!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9432] = {title = "Reist nach Astranaar", objective = "Reist nach Astranaar im Eschental und sprecht mit Verteidigerin Palanaar.", description = "Ich bin froh, dass Ihr helfen wollt. Es gibt in der Tat etwas, was Ihr tun könnt.\n\nAls Teil unseres Bündnisses mit der Allianz möchte ich, dass Ihr zur Elfenstadt Astranaar reist. Sie befindet sich im Eschental, einem großen Wald südlich von Dunkelküste auf dem Kontinent Kalimdor.\n\nBitte sprecht mit Verteidigerin Palanaar, wenn Ihr angekommen seid, und fragt nach, ob es etwas gibt, bei dem Ihr den Bewohnern behilflich sein könnt.", progress = nil, completion = "Es ist immer schön, ein halbbekanntes Gesicht zu sehen. Ihr müsst &lt;Name&gt; sein. Abgesandte Valustraa hat mir gesagt, dass ich Euch erwarten soll.\n\nDie Einwohner des Eschentals brauchen Eure Hilfe, &lt;Klasse&gt;. Sprecht mit den Leuten in Astranaar und schaut, wo Ihr sie unterstützen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9433] = {title = "Ein Bad im Mondbrunnen", objective = "Benutzt die Bedienungseinheit für Robotron in der Nähe der versteckten Steuerungskonsole in einer kleinen Gruppe von Büschen am Rand der Nadel, die sich am dichtesten an Thalanaar befindet, und übernehmt die Steuerung des Robotron 3000. Steuert den Roboter zum westlichen Ende von Tausend Nadeln zum Allianzaußenposten von Thalanaar. Benutzt den Roboter, um eine Probe Mondbrunnenwasser zu besorgen und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten.", description = "Schaut mich nicht so an! Ich habe nicht behauptet, dass ich Euch mit einer Kelle und einer Flasche zum Mondbrunnen von Thalanaar schicke!\n\nIch habe ein wenig an einem Produkt, das ich für einen Kunden transportiert habe, äh... herumexperimentiert. Ehrlich gesagt habe ich bereits eine tragbare Steuerungskonsole für den Robotron in der Nähe von Thalanaar aufgestellt. Ihr müsst diese Steuerungseinheit mitnehmen und in der Nähe meiner versteckten Konsole benutzen.\n\nWenn mein Kunde je erfährt, dass ich den Robotron auch nur aus der Verpackung genommen habe, hängt er mich an den Ohren auf!", progress = "Habt Ihr die Aufgabe schon erfüllt?", completion = "Das lief besser, als ich erwartet habe! Ein weiterer Erfolg für den guten alten Erfindergeist der Goblins!\n\nDas einzige Problem ist, dass er voller Staub ist! Ich werde Ewigkeiten brauchen, um ihn zu reinigen und in seine Kiste zurück zu packen.\n\nAber Zeit ist das Einzige, von dem ich mehr als genug habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9434] = {title = "Das Tonikum testen", objective = "Bringt die Kiste mit Reagenzien zu Magistrix Elosai im Freiwindposten.", description = "<Wizlo nimmt dem Roboter die Wasserprobe ab und legt sie zusammen mit der Felskloppererde und verschiedenen anderen Dingen in eine Kiste.>\n\nSo, das ist alles auf Magistrix Elosais Liste. Sagt ihr, dass es mir eine Ehre war, mit ihr zusammen zu arbeiten, und dass ich ihr viel Glück bei ihren Forschungen wünsche.", progress = "Konnten Wizlo und Ihr die Reagenzien sammeln?", completion = "Ausgezeichnet, wie es aussieht, ist alles da. Jetzt muss ich nur noch alles zusammenmischen und es ausprobieren. Wenn das Tonikum die Wirkung hat, die es laut meinen Forschungen haben sollte, habe ich vielleicht einen Weg entdeckt, die Magiesucht meines Volkes zu lindern.\n\nIhr werdet gleich Zeuge eines historischen Augenblicks werden, &lt;Name&gt;. Ohne Eure Hilfe wäre dies niemals möglich gewesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9435] = {title = "Vermisste Kristalle", objective = "Besorgt die Lieferung seltener Kristalle von den Verlassenen und bringt sie zu Huraan in Süderstade zurück.", description = "Wenn man etwas mit Sicherheit über das Hügelland sagen kann, dann, dass es auserkoren wurde, um unter dem Schatten des Krieges zu leben. Sogar etwas so Harmloses wie eine Wagenladung Steine kann als Ziel dienen.\n\nNormalerweise ist der Verlust von Baumaterial kein allzu großes Problem, aber bei der letzten Lieferung aus dem Azurschacht war eine Kiste mit seltenen Kristallen dabei, die ich sehr gerne untersucht hätte. Plünderer der Verlassenen haben den Wagen abgefangen und ihn nach Nordosten zu einem Turm gebracht, den sie wiederaufbauen wollen. Wir müssen diese Kristalle zurückholen, <Klasse>!", progress = "Konntet Ihr die Kristalle von den Verlassenen zurückholen?", completion = "Dem Licht sei Dank! Laut dem Brief des Vorarbeiters scheint diese Kiste mit Kristallen die einzigen bekannten Proben der Mine zu enthalten. Wenn wir sie verloren hätten, &lt;Name&gt;, hätten wir vielleicht nie etwas Ähnliches zu Gesicht bekommen.\n\nIch kann Euch nicht genug für Eure Hilfe danken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9436] = {title = "Erkenntnisse über die Blutskalpe", objective = "Nemeth Falkenauge im Basislager von Grom'gol möchte, dass Ihr ihm ein Totem der Blutskalpe von einem Schamanen der Blutskalpe bringt.", description = "Das trifft sich gut, <Klasse>. Auf meinen Reisen habe ich die Kampftechniken der verschiedenen Trollstämme untersucht und eine Entwicklung erkannt. Die Blutskalpe in den Ruinen von Tkashi und Bal'lal im Norden benutzen die gleichen Taktiken wie die Amani in den nördlichen Wäldern.\n\nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben, und sie haben sie benutzt, um der mächtigste Stamm in der Gegend zu werden. Sie könnte der Kern einer Waffe gegen die Amani sein, aber ich muss noch mehr darüber herausfinden.", progress = "Enttäuscht mich nicht, <Name>. Wenn wir die Magie der Blutskalpe für unsere Zwecke einsetzen können, kann mein Volk vielleicht die Amanibedrohung auslöschen.", completion = "Gut gemacht. Nun, das ist interessant...\n\nDie Sprache auf dem Totem wird ein Troll niemals erlernen können, aber uns ist sie wohlbekannt. Sie macht den Träger des Totems zu einem Verbündeten eines Wasserelementar namens Naias und erkennt ihn als würdig an, seine Macht zu verwenden.\n\nDas kommt sehr unerwartet, aber es ist nicht verheerend, &lt;Name&gt;. Mit Eurer Hilfe möchte ich der Sache noch weiter auf den Grund gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9437] = {title = "Der Untergang der Morgenbö", objective = "Balandar Sternenlicht in Brackenwall möchte, dass Ihr die Fracht der Morgenbö wiederholt und den Ersten Maat Ithania von den Streitkräften von Theramore in der Nordwacht befreit.", description = "Die Oger hier sind für nichts außer dreckige Witze, bitteres Bier und Wettkämpfe im Köpfe-aneinander-Schlagen zu gebrauchen. Als mein Schiff, die Morgenbö, untergegangen ist, haben sich diese Hunde von Theramore mit meiner Ladung und dem letzten überlebenden Crewmitglied aus dem Staub gemacht. Ich habe mich auf der Suche nach Hilfe hierher begeben, aber diese nichtsnutzigen Oger haben mich nur dumm angeschaut, als ich ihnen erzählt habe, was passiert ist.\n\nIch könnte die Hilfe eines zuverlässigen Helden brauchen, um die Überreste meiner Ladung und Ithania aus der Nordwacht zu retten. Der Turm befindet sich im Nordosten.", progress = "Habt Ihr Ithania befreit und meine Fracht von diesen glorifizierten Freibeutern zurückgeholt?", completion = "Gut gemacht, &lt;Name&gt;! Sobald Ithania Zeit hatte, sich auszuruhen, und meine Vorbereitungen abgeschlossen sind, werden wir aus diesem sumpfigen Ödland hier wieder in die Zivilisation aufbrechen.", rewards = "Handgelenksschützer des BogenschützenSumpfgasstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9438] = {title = "Bote für Thrall", objective = "Reist nach Orgrimmar und übergebt ThrallNazgrels Brief.", description = "Seitdem wir das erste Mal die Scherbenwelt betreten haben, hat der Kriegshäuptling auf diese Nachricht gehofft. Nun seid Ihr es, der die Ehre hat, ihm persönlich die Botschaft der Mag'har zu übermitteln.\n\nVerliert keine Zeit, <Name>. Nehmt diesen Brief, er enthält mein persönliches Siegel. Es gibt nichts, was Thrall mehr erfreuen wird, als die Botschaft, die Ihr bei Euch tragt.", progress = "Ihr bringt Kunde aus der Scherbenwelt, <Klasse>? Sodann, sprecht!", completion = "&lt;Thralls Augen werden immer größer, als er Nazgrels Brief liest.&gt;\n\nMein Volk... wir müssen sie erreichen. Wir müssen Nagrand so schnell wie möglich erreichen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9439] = {title = "Unabgeholtes Gepäck", objective = "Holt den Beutel des Beraters und das Rapier des Beraters aus der Festung Angor und kehrt dann zu Berater Sarophas in Kargath zurück.", description = "Das ist Kargath? Oh je. Ich habe eine... nun, eine Art Siedlung erwartet, ein Zeichen von Zivilisation inmitten der Wildnis.\n\nDas muss ein Fehler sein, diese Hütte voller ungehobelter, ungewaschener, dümmlich grinsender Wilder kann nicht das Hauptquartier des Expeditionskorps sein. Diese flegelhaften Barbaren haben es gewagt, mich auszulachen, als ich ihnen erzählt habe, wie die Dunkeleisenzwerge mich überfallen haben und dann in der Festung Angor verschwunden sind. Ich kann darauf zählen, dass Ihr mir meinen Besitz und meine Würde zurückbringt, oder?", progress = "Um Sonnenwanderers Willen, starrt mich nicht so an! Es ist schon schwer genug für mich, dass ich hier in meiner verschmutzten Kleidung ausharren muss! Nach allem, was ich durchgemacht habe, ist das Letzte, was ich brauchen kann, angestarrt zu werden. Habt Ihr meinen Besitz aus diesem Loch in der Erde, dass die Dunkeleisenzwerge eine Festung nennen, geholt?", completion = "Ihr bewirkt Wunder, &lt;Name&gt;! Ich kann Euch sagen, dass ich noch nie in meinem Leben so begierig darauf war, mich umzuziehen.\n\nUnd mein Rapier! Ich habe mich ohne meine Klinge richtig nackt gefühlt.\n\nIhr müsst für Eure Mühen belobigt und belohnt werden! Keiner kann behaupten, dass Sarophas die kleinen Leute, die ihm auf seinem Weg geholfen haben, je vergessen hätte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9440] = {title = "Kleine Häppchen", objective = "Verfüttert die teuflischen Häppchen an die gefangenen Tiere der Verirrten. Bringt die Überbleibsel zu Cersei Abendsänger in Steinard in den Sümpfen des Elends.", description = "Ich baue gerade eine Waffe gegen die Draenei und Ihr werdet mir dabei helfen!\n\nDie Verirrten sind die zurückgebliebenen Vettern der Draenei und ich habe ein paar Experimente mit ihnen durchgeführt. Ihr müsst nur ein paar teuflische Häppchen zu ihrem Vieh bringen. Wenn sie die Tiere dann schlachten und essen werden sie verflucht sein! Das wird es dem spießigen Anachoreten Avuun im Sicheren Hafen zeigen!\n\nGeht nun und beeilt Euch! Ihr findet die Verirrten und ihre eingesperrten Tiere im Nordosten in der Zuflucht der Verirrten.", progress = "Habt Ihr den gefangenen Tieren alle Häppchen gefüttert? Wartet! Ihr habt doch diesem dummen Menschen, den sie im Käfig halten keines gegeben, oder?\n\nOh, gut! Das wäre nur Verschwendung gewesen!", completion = "Oh, ausgezeichnet! Ich kann es kaum erwarten, die Ergebnisse dieser letzten Fuhre zu sehen!\n\nNun, Ihr habt fabelhafte Arbeit geleistet, Liebchen. Ich wünschte, ich könnte Euch für die Unterhaltung, die Ihr mir bereitet habt, mehr geben, aber Ihr wisst ja, wie es ist. Hier in den Sümpfen kann man nicht viel Geld machen.\n\nIch bin mir sicher, es war Euch den Spaß trotzdem wert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9441] = {title = "Entsandt zu den Mag'har", objective = "Kehrt zu Gorkan Blutfaust beim Posten der Mag'har auf der Höllenfeuerhalbinsel zurück und bietet ihm im Namen Thralls Eure Dienste an.", description = "Nachdem Ihr mir diese Botschaft überbracht habt, würde ich umgehend in die Scherbenwelt aufbrechen. Leider machen wichtige Angelegenheiten meine Anwesenheit in Durotar erforderlich.\n\nIch werde den Mag'har umgehend einen würdigen Tribut als Zeichen unserer Freundschaft zukommen lassen. Des Weiteren entsende ich meine fähigsten Diplomaten. All das wird Vorbereitungen und Zeit kosten... wir benötigen jemanden, der uns schon heute vor den Mag'har würdig vertreten kann.\n\nIch setzte mein gesamtes Vertrauen in Euch, <Name>. Reist zum Posten der Mag'har auf der Höllenfeuerhalbinsel und bietet ihnen Eure Dienste im Namen unseres gesamten Volkes an. Enttäuscht mich nicht, <Name>. Zu viel hängt davon ab.", progress = nil, completion = "Es bedeutet uns sehr viel, dass Ihr uns in diesen schwierigen Zeiten Eure helfende Hand reicht. Niemals werden wir Euch, noch denjenigen vergessen, der Euch hierher entsandt hat.\n\nEuch gebührt unser Dank.", rewards = "Zeremonielle RobenGamaschen der DonnerschmiedeStammeshalsbergeGrollhufbalgmaskeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9442] = {title = "Eine erschöpfende Krankheit", objective = "Erdruferin Ryga beim Posten der Mag'har auf der Höllenfeuerhalbinsel möchte, dass Ihr 1 Trockenkappe aus einer Höhle in der großen Kluft besorgt.", description = "Es ist schön, dass Ihr uns helfen wollt, <Name>. Unsere Grunzer haben verdorbenes Wasser getrunken und sind krank geworden. Leider fehlt mir eine Zutat für eine Heilsalbe. Ich benötige einen seltenen Pilz namens Trockenkappe.\n\nUnser wichtigster Befehl ist, unseren Aufenthaltsort geheim zu halten, weswegen ich nicht riskieren kann, bei der Suche danach entdeckt zu werden. Der einzige Ort, an dem man auf der Höllenfeuerhalbinsel Trockenkappen finden kann, ist eine Höhle in der Nähe der Großen Kluft, südlich von hier.\n\nSeid äußerst vorsichtig, wenn Ihr Euch entschließen solltet, danach zu suchen.", progress = "Habt Ihr den Pilz schon besorgt, <Name>?", completion = "Grokan hat viel Gutes über Euch gesagt. Wie sich herausstellt, war alles wahr.\n\nVielen Dank für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9443] = {title = "Das sogenannte Mal des Lichtbringers", objective = "Nehmt das Mal des Lichtbringers an Euch und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den Westlichen Pestländern zurück.", description = "Einst war ich ein Schüler von Uther Lichtbringer, dem Gründervater der Ritter der Silbernen Hand. Ich sah sein Versagen bei der Ausbildung von Prinz Arthas. Es führte zu der Zerstörung meines Heimatlandes, Quel'Thalas, und ich gebe Uther die alleinige Schuld daran! Und nun ruht er in einem Grabmal, das zu seinen Ehren erbaut wurde - wie liebenswert.\n\nMeine Quellen berichteten mir, dass diese Scharlachroten Narren eines seiner 'heiligen' Relikte in der Spitze ihres Wachturms, nahe den Toren Herdweilers aufbewahren.\n\nBegebt Euch in die Westlichen Pestländer und bringt es mir.", progress = "Wenn Ihr das Mal an Euch gebracht habt, werden wir es ein wenig verändern; es verbessern.", completion = "Der erste Schritt ist vollbracht. Gebt mir das Mal des Lichtbringers und ich werde es in etwas Passenderes verwandeln.\n\nDann wird die Rache endlich mein sein, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9444] = {title = "Entweiht Uthers Grabmal", objective = "Entweiht Uthers Grabmal und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den Westlichen Pestländern zurück.", description = "So, dass ist viel besser. Ich habe ihm etwas dämonische Magie hinzugefügt.\n\nNun müsst Ihr es zu seiner Ruhestätte in den Westlichen Pestländern bringen. Benutzt das verderbte heilige Symbol in der Gegenwart von Uthers Statue, um sein Grabmal zu entweihen! Geht nahe heran, sonst kann die Magie ihre Wirkung nicht entfalten.\n\nDas Grabmal befindet sich südöstlich von den Ruinen Andorhals. Kehrt zu mir zurück, wenn Euer Werk vollbracht ist.\n\nBeeilt Euch, <Klasse>!", progress = "Ist es vollbracht? Uthers Grabmal, wurde es entweiht?", completion = "Er vergibt mir? Er VERGIBT MIR?!!!\n\nIch schere mich nicht um das Geschwätz des alten Geistes - es war allein seine Schuld! Alles, was Quel'Thalas erdulden musste, war das Resultat seiner Inkompetenz!\n\nEs ist wohl offensichtlich, dass der Akt der Entweihung fehlschlug. Geht mir aus den Augen! Ich muss alles nochmal überdenken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9446] = {title = "Das Grab des Lichtbringers", objective = "Begleitet Anachoret Truuen zu Uthers Grabmal in den westlichen Pestländern. Sprecht danach mit Hohepriesterin MacDonnell im Zugwindlager in den westlichen Pestländern.", description = "Jetzt, da Ihr das Mal des Lichtbringers zurückgeholt habt, müssen wir es nur noch zu Uthers Grabmal bringen.\n\nWollt Ihr mich dorthin begleiten? Es ist nicht weit und ich würde Eure Gesellschaft genießen. Danach könnt Ihr hierher zurückkehren und der Hohepriesterin MacDonnell von Eurer Erfahrung berichten.\n\nWas haltet Ihr davon, <Name>?", progress = nil, completion = "Der Lichtbringer ist Euch erschienen? Das ist erstaunlich! Und das alles habt Ihr durch Eure selbstlose Hilfe für den Anachoreten erreicht!\n\nWenn nur die Hälfte der Geschichten wahr ist, war Uther ein großartiger Mann. Und genau wie er seid auch Ihr ein wahrer Held für alle guten Leute in Azeroth, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9447] = {title = "Salbe verabreichen", objective = "Erdruferin Ryga möchte, dass Ihr die Heilsalbe 10 entkräfteten Grunzern beim Posten der Mag'har auf der Höllenfeuerhalbinsel verabreicht.", description = "Ich habe mit den Kräutern, die Ihr mir gebracht habt, eine Salbe zubereitet, die die Stärke der Grunzer wiederherstellen sollte. Nehmt sie und verabreicht sie allen entkräfteten Grunzern an, die Ihr hier in der Nähe seht.", progress = "Ihr seid zurück, <Name>. Habt Ihr Eure Aufgabe erledigt?", completion = "Mögen die Geister Euch segnen, &lt;Name&gt;. die Mag'har stehen in Eurer Schuld.", rewards = "Streitkolben des ErdenrufersTotemikerstabWolfsreiterdolchBogen der Mag'harAuf Euch wartet eine dieser Belohnungen:\n\nAusbalancierter Steindolch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9448] = {title = "Mitleid mit den Verfluchten", objective = "Tötet 3 Verfluchte der Verirrten und kehrt dann zu Anachoret Avuun im Sicheren Hafen in den Sümpfen des Elends zurück.", description = "Diese Blutelfenhexe, Cersei Abendsänger, hat die Verirrten verflucht! Ich weiß es einfach! Ich weiß nicht wie und warum, aber die Folgen sind verheerend. Viele der Verirrten wurden noch weiter verderbt und mit noch teuflischeren Energien verflucht!\n\n<Klasse>, könnt Ihr tief in Eurem Inneren etwas Mitleid für diese armen Kreaturen aufbringen? Sie sollten ihr Leben nicht in einem so furchtbaren Zustand verbringen.\n\nIhr findet die verfluchten Verirrten in der Zuflucht der Verirrten, den Pfad hinunter nach Osten.", progress = nil, completion = "Es ist also getan. Ich danke Euch, dass Ihr ein Herz gezeigt habt. Nachdem Cersei ihnen verderbtes Essen gegeben hat, gab es keinen anderen Weg.\n\nNun ruhen sie in Frieden. Hoffentlich zeigen meine Studien an den anderen Früchte, damit sie gerettet werden können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9449] = {title = "Ruf der Erde", objective = "Sprecht mit dem Geist des Tals beim Heiligen Hain im Am'mental.", description = "Die Zeit ist gekommen, <Name>. Euer Körper und Euer Geist sind an einem Punkt angelangt, an dem Ihr direkt mit den elementaren Geistern Azeroths kommunizieren müsst.\n\nLasst Euch jedoch gewarnt sein. Ich spüre, dass unser ungewöhnliches Betreten dieser Welt und dessen unglückliche Nebenwirkungen die Erdgeister erzürnt und zu einem Ungleichgewicht der Elemente geführt haben.\n\nWollt Ihr Euer Erdtotem erschaffen, so müsst Ihr zuerst mit dem Geist des Tals sprechen. Ihr findet ihn im Heiligen Hain, der sich an die Hügel im Nordwesten schmiegt.", progress = nil, completion = "Es ist sehr kühn von Euch, meinen Rat zu ersuchen, nach all dem, was Eure Leute diesen Inseln angetan haben, Fremder! Dennoch, Euer Mut spricht für sich, also werde ich Teile meines Wissens preisgeben.\n\nDie Erde unter Euren Füßen ist die Grundlage aller Dinge. Der Himmel, das Wasser, sogar große Feuer - alle lasten auf ihren Schultern. Während die anderen oft in wilden Stürmen toben, hält die Erde geduldig aus. Sie verleiht Eurem Innern Stärke und Kraft.\n\nJetzt werdet Ihr Euch beweisen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9450] = {title = "Ruf der Erde", objective = "Tötet 4 ruhelose Erdgeister und kehrt zum Geist des Tals beim Heiligen Hain im Am'mental zurück.", description = "Das Gleichgewicht der Elemente wurde durch das gewaltsame Eindringen der Draenei ins Tal gestört. Euer Absturz hat die Erdgeister erzürnt und gegen die anderen Elemente gewendet. Ihr werdet sehen, dass man die Elemente nur dann verstehen kann, wenn diese in Einklang sind.\n\nFolglich müsst Ihr das Gleichgewicht wieder herstellen. Im Hain hinter mir findet Ihr ruhelose Erdgeister, die gegen die anderen drei Elemente aufbegehren. Helft uns, stellt den Einklang wieder her.", progress = "Das Gleichgewicht der Elemente scheint noch immer gestört, <Name>.", completion = "Ihr habt Euch gut geschlagen, &lt;Klasse&gt;. Indem Ihr die Zahl der ruhelosen Geister reduziert habt, habt Ihr geholfen, das Gleichgewicht der Elemente wiederherzustellen, das Eure Leute unbeabsichtigterweise zerstört hatten.\n\nDas Gleichgewicht muss immer gewahrt bleiben. Auf Eurem Lebensweg als &lt;Klasse&gt;, dürft Ihr diese Lehre nie vergessen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9451] = {title = "Ruf der Erde", objective = "Bringt den Erdkristall zu Firmanvaar bei der Absturzstelle im Am'mental.", description = "Ich werde Euch jetzt einen Teil meines physischen Wesens geben, damit Ihr Euer Erdtotem erschaffen könnt. Bringt es zu dem, der Euch hierher gesandt hat. Ihr und ich werden von nun an auf Lebzeiten miteinander verbunden sein.\n\nDie Kräfte der Erde werden Euch in Eurem Leben fortwährend zur Verfügung stehen. Wenn Eure Knochen am Ende Eurer Tage wieder zu uns zurückkehren, schließt sich der Kreislauf wieder.\n\nSetzt Eure Macht weise ein.", progress = "Zusammen werden die Zerschlagenen und die <Volk> ein tieferes Verständnis für die Mysterien der Elemente wiedererlangen.\n\nSeid Ihr mit der für die Herstellung Eures Erdtotems notwendigen Komponente zurückgekehrt?", completion = "Ausgezeichnet, &lt;Name&gt;. Indem Ihr das Gleichgewicht der Elemente im Hain wieder hergestellt habt, habt Ihr auch für einen Einklang zwischen den Erdelementen dieser Welt und den &lt;Volk&gt; gesorgt. Möglicherweise zeigen diejenigen unter uns, die unseren Weg ablehnen, nun mehr Verständnis?\n\nIch werde ein Totem für Euch erschaffen, das mit den Elementen der Erde verbunden ist. Mit dessen Hilfe werdet Ihr die Kräfte der Erde auf Euren Wunsch herbeirufen können. Mit mehr Weisheit, werden sich Euch auch noch mehr Geheimnisse der Erde erschließen.\n\nHier, nehmt Euer Totem, &lt;Klasse&gt;.", rewards = "Ihr bekommt außerdem:\n\nErdtotem"}
MultiLanguageQuestData['de'][9452] = {title = "Schnapper - sehr, sehr lecker!", objective = "Verwendet das Fischernetz der Draenei, um 10 Schnapper zu fangen. Bringt die Fische und das Netz anschließend zu Diktynna auf der Azurmythosinsel zurück.", description = "Ich habe festgestellt, dass es in diesen Gewässern von Schnappern nur so wimmelt. Das ist ein sehr, sehr leckerer Fisch.\n\nMit einem Fischernetz kann ich genug fangen, um dutzende von Draenei satt zu bekommen! Unglücklicherweise wurde ich erst kürzlich von einer Kreatur angegriffen, die man Murloc nennt, als ich im Fluss fischte. Ich wurde dabei verletzt und kann deshalb meine Arbeit nicht mehr verrichten. Ich brauche Hilfe!\n\nIhr müsst dieses Fischernetz lediglich in der Nähe von Schnapperschwärmen, die man im Kristalfluss östlich von hier findet, auswerfen.\n\nWas sagt Ihr? Vergesst aber nicht, das Netz nach getaner Arbeit wieder zurückzubringen.", progress = "Nehmt Euch vor den Murlocs in Acht: seltsame und extrem lästige kleine Kreaturen.", completion = "Ich hoffe Ihr hattet nicht zu viele Scherereien wegen der Murlocs, &lt;Name&gt;. Ich bin Euch sehr dankbar für alles, was Ihr getan habt.\n\nSoll ich Euch vielleicht das Angeln beibringen? Ich kann Euch sogar eine Angelrute und ein glänzendes Schmuckstück geben.", rewards = "Ihr bekommt:\n\nAngelruteGlänzendes Schmuckstück"}
MultiLanguageQuestData['de'][9453] = {title = "Findet Acteon!", objective = "Bringt die Ladung Schnapper zu Acteon bei der Azurwacht.", description = "Ihr habt das wunderbar gemacht, <Name>. Unsere Leute werden Euch für diesen Fang sehr dankbar sein. Ach ja, könntet Ihr diese Ladung Schnapper vielleicht zu Acteon bei der Azurwacht bringen?\n\nEr dürfte leicht zu finden sein, da er diese Lieferung bereits erwartet.", progress = "Was haltet Ihr von meiner Rüstung? Habe sie selbst hergestellt! Sie unterscheidet sich zwar etwas von den traditionellen Rüstungen, die wir normalerweise tragen, ist aber sehr bequem.", completion = "Arme Diktynna... der Murloc hat ihr wohl einen ziemlichen Schrecken eingejagt.\n\n&lt;Acteon seufzt.&gt;\n\nHoffentlich heilen ihre Verletzungen bald...\n\nIhr haltet also nach Arbeit Ausschau, nun, davon gibt es bei der Azurwacht jede Menge!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9454] = {title = "Die große Mondweidenjagd", objective = "Acteon bei der Azurwacht möchte, dass Ihr ihm 6 Mondweidenhirschlenden bringt.", description = "Ihr macht Euch hier einen Namen, <Name>. Warum versucht Ihr Euch nicht mal im Jagen?\n\nAuf Draenor würden unsere besten Jäger Tiere jagen, die den Mondweidenhirschen dieser Gegend sehr ähneln und den Namen Talbuk tragen.\n\nWenn Ihr denkt, Ihr seid 'Draenei' genug, dann zieht durch die Wildnis rund um die Azurwacht und tötet ausreichend Mondweidenhirsche und -böcke, um Eure Taschen mit ihrem Fleisch zu füllen.\n\nDie Hirsche grasen südlich der Azurwacht, die Böcke im Norden. Gebt auf ihre Hörner Acht!", progress = "Die Bälge der Hirsche taugen nichts, dafür ist ihr Fleisch köstlich zart.", completion = "Gut gemacht, &lt;Name&gt;, gut gemacht!\n\nHier, während Ihr fort wart, habe ich ein paar der Lenden, die Ihr mir gebracht habt, zubereitet. Vielleicht wollt Ihr ja auch das Rezept haben?", rewards = "Ihr bekommt:\n\nGeröstete MondweidenlendenRezept: Geröstete Mondweidenlenden"}
MultiLanguageQuestData['de'][9455] = {title = "Seltsame Funde", objective = "Bringt den schwach leuchtenden Kristall zu Exarch Menelaous bei der Azurwacht.", description = "Der Kristall, den Ihr beim Körper des Nachtpirscherjungen gefunden habt, scheint ein Teil der Exodar zu sein. Vielleicht ist dies eine Erklärung für das ungewöhnliche Aufkommen und Verhalten einiger Tiere dieser Gegend.\n\nBringt den Kristall zurück zur Azurwacht. Der Exarch wird sicherlich von dieser Entdeckung erfahren wollen.", progress = "Was habt Ihr gefunden? Wo?", completion = "Wie konnte solch ein Ding nur im Magen eines Nachtpirschers enden? Könnten die Trümmer des Absturzes noch mehr Kreaturen verseucht haben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9456] = {title = "Nachtpirscherjagd", objective = "Exarch Menelaous bei der Azurwacht möchte, dass Ihr 8 infizierte Nachtpirscherjungen tötet.", description = "Ich werde nicht versuchen, irgendwelche Ausreden für das, was Ihr gefunden habt, zu finden. Es ist ganz klar unsere Schuld. Uns wurde von zertrümmerten Kristallfragmenten im östlich gelegenen Fluss berichtet, aber wir hatten beschlossen, diese Implikationen zu ignorieren. Wir können jetzt entweder auf dieser Insel herumsitzen und diese Tragödie beweinen, oder etwas tun, um eine Ausbreitung zu vermeiden.\n\nWenn Ihr es ertragen könnt, möchte ich, dass Ihr zurück in die Wildnis geht und so viele der infizierten Nachtpirscherjungen tötet, wie Ihr finden könnt.", progress = nil, completion = "Ich hoffe nur, dass es nicht schon zu spät ist...", rewards = "Verstärkte PanzerstiefelArmschienen des JägersmannsLeicht abgenutzte ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9457] = {title = "Ein ungewöhnlicher Patron", objective = "Benutzt Naias' Gabe in der Nähe des Altars von Naias, um den Wasserelementar Naias zu rufen. Besiegt ihn und kehrt dann zu Nemeth Falkenauge im Basislager von Grom'gol mit dem Herz von Naias zurück.", description = "Naias ist also das Genie hinter den Blutskalpen und ihrer fremdartigen Magie? Ich muss zugeben, dass ich nie gedacht hätte, dass meine Nachforschungen dort enden würden, aber unsere Erkenntnisse könnten sich vielleicht trotzdem als hilfreich herausstellen.\n\nVor der Küste im Nordwesten befindet sich eine kleine Insel, die von geringen Wasserelementaren bewohnt wird. Es gibt dort eine grobe Steinplatte, die den Trollen vielleicht als Altar dienen könnte. Bringt das Totem, das Ihr gefunden habt, zu diesem Altar. Vielleicht können wir diesen Naias ja hervorlocken und seine Macht in eine angenehmere Form bringen.", progress = "Was gibt es Neues von Naias, <Name>?", completion = "Ich kann die rohe Macht in diesem Edelstein fühlen, &lt;Name&gt;. Ich werde ihn nach Silbermond schicken, damit unsere Magister ihn weiter untersuchen können, aber ich bin mir sicher, dass er uns im weiteren Kampf gegen die Amani dienlich sein kann.\n\nEure Hilfe bei der Besorgung dieses Steins war unbezahlbar. Ich werde dafür sorgen, dass die Weltenwanderer den Namen des Helden, der diesen Fund möglich gemacht hat, erfahren.", rewards = "Klinge der exotischen MagieSchiftung der Rohen KraftDschungelläuferstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9460] = {title = "Mit vereinten Kräften", objective = "Keltus Dunkellaub möchte, dass Ihr das spitzenverzierte Taschentuch von der Anführerin der Schildwachen stehlt und zu ihm bringt.", description = "Keltus Dunkellaub meldet sich zum Dienst!\n\nOh... wer seid Ihr eigentlich? Wenn Ihr wegen meinem Bericht hier seid, dann müsst Ihr mir zuerst helfen.\n\nIch habe vor, die Spione der Schildwache anzugreifen, möchte meine treue Tuschel aber als Vorhut vorausschicken. Sie braucht lediglich eine Fährte, die sie auf sie hetzt.\n\nJemand von Eurem Können kann sich doch sicherlich hineinschleichen und etwas von der Anführerin der Schildwachen stehlen?", progress = "Seid Ihr an etwas herangekommen?", completion = "Ausgezeichnet! Solch ein persönlicher Gegenstand hinterlässt eine starke Fährte der Eindringlinge - genug, um Tuschel zu ihnen zu führen...", rewards = "Ihr bekommt:\n\nStapel mit Berichten"}
MultiLanguageQuestData['de'][9461] = {title = "Ruf des Feuers", objective = "Geht zu Prophet Velen in der Halle des Lichts in der Exodar.", description = "Ihr sollt wissen, dass der Prophet nach Euch gefragt hat, da er von Euren Erfolgen in Euren Prüfungen erfahren hat. Die Erschaffung Eures Feuertotems muss warten, bis Ihr mit ihm gesprochen habt.\n\nDies ist eine seltene Ehre; geht sofort zur Exodar, um so schnell wie möglich mit ihm zu sprechen!", progress = nil, completion = "Hallo, &lt;Name&gt;, ich habe Euch erwartet. Heute scheint Euer Tag zu sein, nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9462] = {title = "Ruf des Feuers", objective = "Geht zu Tuluun in der Azurwacht auf der Azurmythosinsel.", description = "<Name>! Es ist an der Zeit, dass Ihr weitere Ausbildung im Weg der Geister erhaltet. Ihr solltet mit Tuluun, dem Schamanen in der Azurwacht, sprechen. Er kann Euch in dem Verständnis und der Beherrschung der Macht des Feuers unterweisen.", progress = nil, completion = "Hallo, &lt;Name&gt;, ich habe Euch erwartet. Ich hoffe, Ihr seid bereit, Eure Ausbildung fortzusetzen. Die nächste Aufgabe wird schwierig werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9463] = {title = "Medizinische Notwendigkeit", objective = "Anachoret Fateema bei der Azurwacht möchte, dass Ihr für sie 8 Lauerwurzranken sammelt.", description = "Ich habe herausgefunden, dass die Ranken der Pflanzenkreaturen, den sogenannten Peitschern, auf dieser Insel eine regenerierende Eigenschaft besitzen. Wenn man die Ranken richtig verarbeitet, kann man aus ihnen eine hochwirksame Heilsalbe herstellen. Durch die vielen verletzten Draenei, die ständig in der Azurwacht eintreffen, sind unsere Vorräte an Heilmitteln beinahe erschöpft.\n\nUnser besonderer Gast wurde erst gestern schwer verletzt und bewusstlos am Kristallfluss gefunden. Bringt mir die Wurzeln und wir können sie möglicherweise retten.\n\nHaltet südlich und östlich von hier nach den Lauerwurzkreaturen Ausschau, <Klasse>. Ihr dürft keine Zeit verlieren!", progress = "Ich fürchte, ihr Zustand verschlimmert sich zusehends.", completion = "Lasst uns hoffen, dass diese Salbe ihren Lebenswillen neu belebt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9464] = {title = "Ruf des Feuers", objective = "Sprecht mit Glutos beim Glutgrund auf der Azurmythosinsel.", description = "Ihr sollt noch einmal auf die Probe gestellt werden. Diesmal ist es das chaotische Element des Feuers, das Ihr verstehen müsst, wenn Ihr ein Totem erstellen wollt, um dessen Energien zu nutzen.\n\nIm Nordosten entlang der Küste gibt es einen heiligen Ort des Feuers, den Glutgrund. Inmitten der verbrannten Bäume wacht Glutos, ein besonders mächtiger und weiser Feuerelementar. Mit ihm müsst Ihr sprechen.\n\nGeht jetzt zu ihm, mögen die Elementargeister von Azeroth mit Euch sein.", progress = nil, completion = "Sehe ich richtig, dass das Funkeln in Euren Augen Euren Wunsch heranzuwachsen und zu verstehen widerspiegelt? Gut!\n\nTuluun hat Euch hierher geschickt, da er erkannt hat, dass Ihr fähig seid zu lernen und uns bei einem Problem zu helfen, das durch den Absturz der Exodar verursacht wurde.\n\nWir werden sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9465] = {title = "Ruf des Feuers", objective = "Erlangt die Ritualfackel wieder und bringt sie zu Glutos beim Glutgrund auf der Azurmythosinsel.", description = "Einer meiner Brüder, Hauteur, ist verrückt geworden! Zweifellos ist der Absturz Eures Schiffs daran schuld. Er verlangt jetzt, dass ihn die heimischen Eulenbestien verehren.\n\nDas kann nicht so weitergehen! Keiner von uns würde jemals einen Gott verkörpern! Ihr müsst das Gleichgewicht wieder herstellen.\n\nAls Erstes müsst Ihr ihre Ritualfackel finden, welche in Besitz der wahnsinnigen Wildekin innerhalb der Tannenruhfeste im Westen ist.\n\nBringt mir diese Fackel.", progress = "Habt Ihr die Fackel?", completion = "Seht Ihr? Das Feuer geht niemals aus. Das ist das Werk Hauteurs. Es ist das Symbol seines Hochmuts. Flammen sollen verzehren, was sie selbst brennen lässt und dann sterben, um ein andermal wieder entfacht zu werden.\n\nIch würde Euch ja beim Löschen der Fackel helfen, aber sie muss noch brennen, damit Ihr Euch Hauteur stellen könnt. Lassen wir sie noch ein wenig länger am Leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9466] = {title = "Gesucht: Schwarzkralle die Wilde", objective = "Bringt Schwarzkralles Klauen zu Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.", description = "Auf Anweisung des Waldläuferhauptmanns wird hiermit eine Belohnung auf die Erlegung der teuflischen Felsklauenmatriarchin, bekannt als Schwarzkralle die Wilde, ausgesetzt.\n\nSchwarzkralle wurde zuletzt in einer Höhle in der Großen Kluft gesichtet. Zum Erhalt der Belohnung müssen die Klauen der Kreatur vorgezeigt werden.", progress = "Gibt es Neuigkeiten über Schwarzkralle?", completion = "Ihr seid ein tapferer &lt;Klasse&gt;, &lt;Name&gt;. Diese Bestie hat viele meiner besten Jäger das Leben gekostet.\n\nNehmt die Belohnung, Ihr habt sie Euch redlich verdient.", rewards = "Sonnenwanderers StulpenVenn'rens StiefelFeine SchärpeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9467] = {title = "Ruf des Feuers", objective = "Besorgt Euch Hauteurs Asche und bringt sie zusammen mit der Ritualfackel zu Glutos beim Glutgrund auf der Azurmythosinsel. Vergesst nicht, dass Ihr die Kugel der Rückkehr verwenden könnt, um zu Glutos zurückzukehren, sobald Ihr die Asche habt.", description = "Den Eulenbestien vom Mondschwingenbau auf der Silbermythosinsel, weit im Südwesten, wurde weisgemacht, dass Hauteur ein Gott sei, den es zu huldigen gilt. In Wirklichkeit ist er ein abtrünniger Elementar, den man von seinem Leid erlösen muss. Diese Fackel ist der Schlüssel zu seinem Niedergang.\n\nHauteur verlangt von den Eulenbestien die regelmäßige Entzündung eines Feuers zu seinen Ehren. Sobald Ihr es entfacht, wird er kommen. Tötet ihn und bringt mir seine Asche. Verwendet die Kugel in Eurer Tasche und ich werde Euch hierher zu mir zurückbringen.", progress = "Sprecht erst wieder mit mir, wenn Ihr Hauteurs Asche habt.", completion = "Ihr habt heute eine besonders wichtige Lektion gelernt. Es ist die Geschichte vom Ende und vom Neuanfang.\n\nAls wir uns das erste Mal unterhielten, sagte ich Euch, dass das Feuer nicht nur Zerstörung verkörpert, sondern auch die erneuernde Kraft der Elemente. Durch Euer Handeln habt Ihr Hauteur zerstört und gleichzeitig gerettet, auf das er aus seiner Asche wiedergeboren wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9468] = {title = "Ruf des Feuers", objective = "Bringt Hauteurs Asche zu Tuluun in der Azurwacht auf der Azurmythosinsel.", description = "Ihr habt heute bei dem Versuch, Eure Bindung zum Feuer zu verstehen, etwas Großartiges geleistet. Vergesst nicht, dass Ihr ihm stets den gebührenden Respekt erweisen sollt, um Euch nicht selbst daran zu verbrennen.\n\nIch habe einen Teil von Hauteurs Asche für Euch aufgehoben. Verwendet ihn, wenn Ihr Euer Feuertotem erstellt und vergesst nichts von dem, was Ihr auf Eurem Weg hierher gelernt habt.\n\nKehrt jetzt zu Tuluun zurück.", progress = "Ihr scheint Euch an ein paar Ecken versengt zu haben. Wie erging es Euch bei der Zusammenkunft mit der Flamme, <Klasse>?", completion = "Ihr habt das reinigende Feuer der Zerstörung erfahren und seid erneuert worden, &lt;Name&gt;. Dies ist nichts im Gegensatz zu dem Elend, das die &lt;Volk&gt; derzeit erleiden. Ihr habt Hauteur vor sich selbst gerettet und somit Eure Bindung zu dem Element des Feuers in dieser Welt gesichert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9469] = {title = "Federbarts Unterstützung", objective = "Geht zu Federbarts Hütte und stattet dem Zwerg dort einen Besuch ab. Solltet Ihr ihn nicht dort antreffen, so sucht nach Hinweisen auf seinen Verbleib.", description = "Sollte ich endlich eine Audienz bei Falstad Wildhammer gewährt bekommen, hoffe ich einen der besten Fürsprecher der Wildhammerzwerge an meiner Seite zu haben, <Name>.\n\nFederbart genießt bei seinen Leuten hohes Ansehen, sei es wegen seiner legendären Ausbildungsmethoden für Greifen oder wegen seiner Weisheit. Wenn jemand Falstad Wildhammer überzeugen kann, dann er.\n\nIch würde ihn ja gerne selbst aufsuchen, allerdings darf ich den Nistgipfel nicht verlassen, solange ich meine Audienz erwarte. Sucht Federbart bei seiner Wohnstätte im Süden auf und fragt ihn, ob er an meiner Seite aussagen möchte.", progress = nil, completion = "Federbarts Tagebuch weist relativ viele neue Einträge auf. Ihr blättert durch die letzten paar Seiten und beginnt nach Hinweisen über seinen Verbleib zu suchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9470] = {title = "Eine Geste des guten Willens", objective = "Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr Hexendoktor Mai'jin und seine Spinne Tcha'kaz tötet.", description = "Das zerklüftete Gebiet des Hinterlands ist nicht nur das Zuhause der Zwerge des Wildhammerklans und ihrer Greifen, sondern auch einiger Waldtrollstämme.\n\nDie Trolle betrachten die Wildhämmer als Besatzer ihres Heimatlands und lassen keine Gelegenheit aus, um die Zwerge zu belästigen, indem sie die Greifennester angreifen. Ein Weg uns in den Augen der Wildhämmer zu beweisen ist, diese Angriffe zum Ende zu bringen, indem wir einen Anführer der Bleichborken, Hexendoktor Mai'jin, töten. Er befindet sich in einer Höhle in Bogens Kante, westlich von Shadra'Alor.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Wildhämmer werden sich sehr darüber freuen, dass sie den Bleichborken nicht alleine gegenübertreten müssen. Wenn sie sehen, dass die Allianz ein verlässlicher Partner im Schutz der Greifen ist, gehen sie vielleicht eher auf unser Angebot ein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9471] = {title = "Die Raubtiere zur Beute machen", objective = "Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr 10 räudige Silbermähnen und 5 Silbermähnenwölfe tötet.", description = "Die Wildhammerzwerge sind die Begleiter, Hüter und Ausbilder der Greifen. Die Greifen haben genügend Feinde, vor allem unter den Stämmen der Waldtrolle.\n\nManchmal stammt die Gefahr aber auch von natürlichen Feinden, wie zum Beispiel den Wölfen. Ein einzelnes Tier ist kein erstzunehmender Gegner für einen Greifen, aber in letzter Zeit werden die Greifen immer häufiger von Rudeln angegriffen, da ihre natürliche Beute knapp wird. Die Wölfe auszulöschen könnte wesentlich zur Sicherheit der Greifen beitragen und uns bei den Wildhämmern sehr beliebt machen.", progress = nil, completion = "&lt;Botschafter Rualeth nickt, als Ihr ihm Euren Bericht übergebt.&gt;\n\nIhr habt gute Arbeit geleistet. Das Auslöschen der Silbermähnen wird von den Wildhämmern nicht unbemerkt bleiben. Wenn ich mich mit ihren Anführern treffe, werden Eure Taten sicher ein gutes Licht auf die Allianz werfen. Bitte nehmt diese Bezahlung als kleines Zeichen meiner Dankbarkeit an, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9472] = {title = "Arelions Geliebte", objective = "Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr Viera Sonnenwisper aus der Siedlung herauslockt und Carindas Rolle der Vergeltung auf sie anwendet.", description = "Bei all den wichtigen Dingen, die er zu tun hatte, fand Arelion immer noch genug Zeit seine Geliebte zu besuchen!\n\nJetzt wird mir alles klar. Viera Sonnenwisper, dieses widerwärtige Frauenzimmer... wir werden Ihr beibringen, sich niemals in die Angelegenheiten einer Magistrix einzumischen.\n\nNehmt diese Schriftrolle und findet Viera. Sucht einen Weg, sie vom Dorf wegzulocken und benutzt die Schriftrolle.\n\nArelion erwähnte, dass sie einem bestimmten Wein, der von den Druiden des Cenarius angebaut wird, nicht widerstehen kann. Vielleicht findet Ihr ein wenig davon bei der Zuflucht des Cenarius in den Zangarmarschen westlich von hier.", progress = nil, completion = "Hervorragend! Diese hinterhältige Göre wird sich mit niemandes Ehemann mehr davonschleichen.\n\nHier habt Ihr eine Kleinigkeit für Eure Mühen. Ich vertraue darauf, dass diese Angelegenheit unter uns bleibt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nCarindas Ehering"}
MultiLanguageQuestData['de'][9473] = {title = "Eine alternative Alternative", objective = "Daedal bei der Azurwacht möchte, dass Ihr für ihn 5 Azurlöwenmäulchen sammelt.", description = "Der Zustand des Mädchens ist bereits zu kritisch, als dass einfache Salben sie noch retten könnten. Es gibt möglicherweise noch einen anderen Weg...\n\nDer Wald von Azurmythos birgt viele Geheimnisse, eines davon ist eine seltene Pflanze, das Azurlöwenmäulchen, die viele als Allheilmittel ansehen.\n\nSie ist leicht zu entdecken, da sich ihr Aussehen sehr stark von allen anderen Pflanzen unterscheidet und sie ausschließlich im Schatten der Azurkiefer wächst. Beeilt Euch!\n\nUnd <Name>, nehmt Euch vor den Drescherwurzkreaturen in Acht! Sie ernähren sich von den Azurlöwenmäulchen.", progress = "Verschwendet keine Zeit, Junge.", completion = "Seht, wie die Pflanze ihre wundersame Wirkung entfaltet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9474] = {title = "Das Mal des Lichtbringers", objective = "Besorgt das Mal des Lichtbringers und kehrt dann zu Anachoret Truuen im Zugwindlager in den Westlichen Pestländern zurück.", description = "In der kurzen Zeit, die ich in Azeroth verbracht habe, habe ich viele seiner Helden studiert. Einer von ihnen, Uther Lichtbringer, hebt sich von allen anderen ab. Nachdem er viele Jahre ein Held war, wurde er am Ende von seinem viel versprechendsten Schüler, Arthas, verraten.\n\nZu seiner Ehre würde ich gerne etwas, das er verloren hat, zu seinem Grabmal bringen. Man sagt, dass der Scharlachrote Kreuzzug eines seiner heiligen Relikte oben in dem Wachturm in der Nähe von Herdweiler aufbewahrt.\n\nBitte, <Klasse>, geht und holt es zurück.", progress = "Das Mal des Lichtbringers ist ein mächtiges Symbol für Uthers Glaube an das Licht.", completion = "Vielen Dank, &lt;Klasse&gt;! Dass Ihr dieses heilige Symbol zurückgebracht habt, bedeutet mir und allen anderen, die die Erinnerung an Uther Lichtbringer in Ehren halten, sehr viel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9475] = {title = "Wiedererlangen der Eier", objective = "Erlangt 5 Greifeneier und bringt sie zu Botschafter Rualeth beim Nistgipfel.", description = "Die Begutachtung der Überreste lässt vermuten, dass es sich bei dem zerschmetterten Skelett um Federbart handeln muss. Eine der skelettierten Hände umklammert fest ein zerfetztes und schmutziges Stück Papier. Ihr zieht es vorsichtig heraus und rollt es auf. Zum Vorschein kommt eine handgezeichnete Karte und ein paar eilig hingekritzelte Notizen.\n\nDie Karte scheint eine Skizze von Shadra'Alor und seinen drei Tempeln zu sein. Mehrere 'X' auf der Zeichnung markieren vermutlich die Lage gestohlener Eier. Ihr packt die Karte ein und plant, sie an einem sicheren Ort genauer zu untersuchen.", progress = "Euer Gesichtsausdruck verrät, dass Ihr Überbringer schlechter Nachrichten seid. Was habt Ihr herausgefunden?", completion = "&lt;Ihr überreicht dem Botschafter die Eier und berichtet von den Entdeckungen bei Federbarts Hütte und Shadra'Alor.&gt;\n\nDie Bleichborken haben Federbart getötet?\n\n&lt;Auf Rualeths Gesicht legt sich ein Ausdruck des Grauens, als Ihr ihm vom Tod des Zwergs und den Auswirkungen auf seine Mission erzählt.&gt;\n\nIch kann verstehen, warum er sich auf die Suche nach den Eiern machen wollte, aber ich wünschte, er hätte noch jemanden mit sich genommen. Sein Tod wird Falstad Wildhammer zweifellos erzürnen, einen Vergeltungsschlag gegen die Trolle zur Folge haben und meine Audienz nun endgültig aufschieben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9476] = {title = "Suche nach Federbart", objective = "Reist nach Shadra'Alor und sucht nach Spuren von Federbart.", description = "Die jüngsten Einträge in Federbarts Tagebuch beschreiben seine Sorge bezüglich der immer häufigeren Überfälle von Bleichborkentrollen auf die Greifen im Wildhammergebiet und die sich mehrenden Diebstähle von Eiern. Die Untersuchung der kleineren Bleichborkensiedlungen brachte keine Informationen zu Tage.\n\nDer letzte Eintrag handelt von Federbarts Verdacht, dass ein Hexendoktor der Bleichborken, namens Mai'jin, hinter all den Raubzügen steckt. Am Ende des Eintrags, steht mit hastig geschriebenen Worten, dass der Zwerg die Absicht hat, nach Shadra'Alor zu gehen und nach den Eiern zu suchen.", progress = nil, completion = "Auf dem Altar liegen Skelettknochen, die von einem männlichen Zwerg zu stammen scheinen. Eine Identifikation ist zwar nicht mehr möglich, aber Ihr beschließt, die Überreste nach Hinweisen zu untersuchen, die auf Federbart verweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9483] = {title = "Die feinen Freuden im Leben", objective = "Nur weil wir auf dieser Pilgerfahrt sind, heißt das noch lange nicht, dass wir alle Freuden im Leben aufgeben müssen. Ich hatte schon seit Ewigkeiten keinen guten Wein mehr.\n\nIch könnte im wahrsten Sinne des Wortes für einen gute Flasche Cenarischer Geistertropfen töten!\n\nIch weiß, ich weiß, wie unpassend von mir, ein Nachtelfengebräu zu genießen.", description = nil, progress = "Nur weil wir auf dieser Pilgerfahrt sind, heißt das noch lange nicht, dass wir alle Freuden im Leben aufgeben müssen. Ich hatte schon seit Ewigkeiten keinen guten Wein mehr.\n\nIch könnte im wahrsten Sinne des Wortes für einen gute Flasche Cenarischer Geistertropfen töten!\n\nIch weiß, ich weiß, wie unpassend von mir, ein Nachtelfengebräu zu genießen.", completion = "Vielleicht werden wir ja doch noch Freunde. Folgt mir! Wir wollen schließlich nicht mit den anderen teilen müssen, oder?", rewards = nil}
MultiLanguageQuestData['de'][9484] = {title = "Die Zähmung der Bestie", objective = "Verwendet die Zähmerrute, um einen wahnsinnigen Drachenfalken zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", description = "Ihr habt zweifellos schon Tiere für Euren Schutz und für Euren Lebensunterhalt getötet, jedoch seid Ihr erst jetzt bereit, Euch mit ihnen anzufreunden und sie zu zähmen, um von ihrer Stärke Gebrauch zu machen. Ich kann Euch darin ausbilden.\n\nNehmt diese magische Zähmerrute, sie wird ein wildes Tier vorübergehend an Euch binden und an Eurer Seite kämpfen lassen. Beginnt mit einem wahnsinnigen Drachenfalken, ein recht gefügiger Vogel, den man außerhalb der Zuflucht der Weltenwanderer findet. Kehrt anschließend zu mir zurück.", progress = "Konntet Ihr den Drachenfalken gefügig machen?", completion = "Ihr habt zahlreiche Kratzer und Bisse von dem Drachenfalken in Kauf genommen, dies steht für Eure Hartnäckigkeit. Seid Ihr stark genug, um noch mehr zu lernen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9485] = {title = "Die Zähmung der Bestie", objective = "Verwendet die Zähmerrute, um eine Nebelfledermaus zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", description = "Ihr habt Euch gut geschlagen, <Name>. Euer Verständnis für die Wildnis wird rasch größer.\n\nDie Nebelfledermaus ist ein listiger Jäger, sie vereint die Schnelligkeit des Drachenfalken und die Wildheit einer Bachtatze. Man findet die Nebelfledermäuse direkt über dem Elrendar im Süden, wo sie unglücklichen Reisenden auflauern, die in den Geisterlanden umherwandern.\n\nVerwendet diese letzte Zähmerrute, um eine Nebelfledermaus zu bändigen. Kehrt anschließend zu mir zurück.", progress = "Konntet Ihr die Nebelfledermaus gefügig machen?", completion = "Seht Ihr &lt;Name&gt;, ich kann Euch nichts Neues mehr lehren. Ihr wisst bereits, wie man die einst gejagten Kreaturen zähmen kann, jetzt müsst Ihr Euch nur noch einen Verbündeten der Natur aussuchen, der zu Euch passt.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9486] = {title = "Die Zähmung der Bestie", objective = "Verwendet die Zähmerrute, um eine alte Bachtatze zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", description = "Die alte Bachtatze ist ein gründlicher und geschickter Jäger. Wenn man sie zähmen möchte, sieht sie einen sofort als Beute. Lasst Euch nicht von Eurem Vorhaben abbringen.\n\nVerwendet die Zähmerrute, um diese große Katze gefügig zu machen und an ihrer Seite zu jagen. Man findet sie überall im Immersangwald, manche sogar ganz nahe bei der Jagdhütte. Kehrt zu mir zurück, wenn Ihr genug gelernt habt.", progress = "Habt Ihr an der Seite der Bachtatze gejagt?", completion = "Ihr habt Stärke und Durchhaltevermögen bewiesen. Euch erwartet nur noch ein letzter Test, bevor Ihr das Zähmen ohne Magie beherrscht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9487] = {title = "Arkanhäscher", objective = "Arkanist Vandril möchte, dass Ihr 10 Arkantrümmer für ihn sammelt.", description = "Arkanhäscher sind magische Kunstwesen mit roher Kraft. Sie sind dick gepanzert und können schwere Schläge austeilen. Eure Zauberkraft gewährt Euch jedoch den Vorteil, ihre Abwehr umgehen und Treffer von ihnen vermeiden zu können, <Name>.\n\nReist zum Morgensternturm und sprengt die Arkanhäscher in Stücke! Bei ihren Überresten findet Ihr kristallisierte Fragmente magischer Energie. Sammelt diese und bringt sie zu mir. Den Morgensternturm findet Ihr im Osten, jenseits des Sees.", progress = "Ihr seid den Rohlingen nicht zu Nahe gekommen, hoffe ich?", completion = "Welche Verschwendung, Magie zu nutzen um Wesen von körperlicher Gewalt zu erschaffen. Ich dachte immer, das wäre der Grund, warum wir uns mit den niederen Völkern verbündet hätten.\n\nEs war gut von Euch, sie zu zerstören. Nun können wir ihre Überreste für angemessenere Zwecke verwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9488] = {title = "Eine einfache Robe", objective = "Arkanist Vandril möchte, dass Ihr ihm 15 Leinenstoff und eine Seidendrüse der Spindelweber bringt.", description = "Die Arkantrümmer, die Ihr gesammelt habt, sind gut geeignet.\n\nGeeignet wofür, möchtet Ihr wissen? Um eine prächtige <Klasse>robe für Euch herzustellen!\n\nAlles, was wir jetzt noch benötigen, ist etwas Leinenstoff und eine Seidendrüse der Spindelweber. Die Seidendrüse bekommt Ihr von einer Spindelweberspinne, vorzugsweise nachdem Ihr diese getötet habt.", progress = "Die Robe kann ohne die notwendigen Materialien nicht fertiggestellt werden, aber das ist Euch sicherlich bekannt.", completion = "Die Details der Herstellung von magischen Roben brauchen Euch nicht zu interessieren, &lt;Name&gt;, Ihr müsst nur Wissen, was Ihr mir zu bringen habt.\n\nUm ehrlich zu sein, Ihr habt mir genug für mehrere Roben gebracht. Der Profit, den ich damit machen kann, sollte ausreichen, um die Herstellungskosten Eurer Robe zu decken, und mir selbst noch etwas Nettes zu kaufen. Habt Dank!", rewards = "Ihr bekommt:\n\nManagewirkte Robe"}
MultiLanguageQuestData['de'][9489] = {title = "Ordnung in der Schneise", objective = "Wirkt das Machtwort: Seelenstärke auf 6 Waldläufer von Immersang in der Todesschneise.", description = "<Name>, gut, dass Ihr hier seid. Die Geißel überfällt unsere Stadt mit so unendlichem Hass, dass ich befürchten muss, dass die Moral unserer Wache langsam dahinschwindet.\n\nEilt zu der Todesschneise südlich der Stadt, wo Jaela und ihre Waldläufer bereitstehen. Erfüllt sie mit Eurem Segen mit der Macht des Lichts.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRoben von Silbermond"}
MultiLanguageQuestData['de'][9490] = {title = "Die Felsklauenmatriarchin", objective = "Besorgt Schwarzkralles Klauen von Schwarzkralle der Wilden in der Großen Kluft und bringt sie zu Ikan beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.", description = "Felsklauen sind bösartige, hinterhältige und grausame Kreaturen. Aber die normalen sind noch harmlose Schoßtierchen im Vergleich zu ihrer Matriarchin, Schwarzkralle der Wilden.\n\nMein Cousin wurde von ihr gefressen. Das war kein schöner Anblick. Ich habe an diesem Tag geschworen, dass Schwarzkralle dafür bezahlen wird. Bringt mir einen Beweis für den Tod dieses Monsters, und ich werde Euch meine Ersparnisse dafür geben. Einverstanden?\n\nIhr findet das Biest in einer Höhle in der Großen Kluft. Viel Erfolg!", progress = "Habt Ihr schon einen Beweis für Schwarzkralles Tod, <Name>?", completion = "Ja, an diese scharfen Krallen erinnere ich mich genau!\n\nNehmt diese Belohnung, &lt;Name&gt;. Ihr habt eine gefährliche Aufgabe erledigt. Ihr habt Euch jedes einzelne Stück hiervon verdient.", rewards = "Stulpen des VerteidigersStiefel des ErdenrufersÖdniswandlerschärpeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9491] = {title = "Gier", objective = "Eralan in Tristessa möchte, dass Ihr ihr einen gekörnten Goldring aus den Amanikatakomben bringt.", description = "Ein reicher, und wenn ich sage 'reich', meine ich 'stinkreicher' Händler kam gestern hier vorbei und erzählte etwas über einen Ring von 'immenser archäologischer Bedeutung', der in einer der zahllosen Grabtruhen in den Amanikatakomben eingeschlossen ist. Wenn er nicht über den Ring sprach, dann darüber, wie viel er dafür bezahlen würde.\n\nIch könnte Euch Diebeswerkzeug vorstrecken, und wenn es Euch gelingt, mir den Ring zu bringen, zahle ich Euch so viel, dass ihr zehn Ringe für Euch selbst kaufen könnt!", progress = "Bitte sagt mir, dass Ihr den Ring gefunden habt. Es kann nicht mehr lange dauern, bis der Händler einen eigenen Schurken findet.", completion = "Ist das der Ring? Sieht nicht sehr eindrucksvoll aus, aber Ihr wisst, was man über elfischen Tand sagt...\n\nEure Bezahlung habe ich nicht vergessen. Ich habe nichts dagegen, wenn Ihr das Geld gleich hier wieder ausgebt, Schwester!", rewards = "Ihr bekommt:\n\nPrallvoller Sack mit Silber"}
MultiLanguageQuestData['de'][9492] = {title = "Das Schicksal wenden", objective = "Bringt Kriegshäuptling Kargaths Faust zu Truppenkommandant Danath Trollbann in der Ehrenfeste.", description = "Die weiterhin bestehende orcische Bedrohung ist eine der traurigen Wahrheiten der Scherbenwelt. Es gab eine Zeit, in der wir Söhne des Lothars glaubten, dass wir die Sicherheit der Ehrenfeste mit unserem Blut erkauft haben, aber es sollte keinen Frieden geben.\n\nDie Söhne werden sich keinem Orc fügen - ob er nun grün, braun oder eben rot sein mag - wir werden sie besiegen oder bei dem Versuch sterben. Wenn wir eine Chance auf den Sieg haben wollen, müssen wir sie in der Höllenfeuerzitadelle bekämpfen. Bringt mir die Waffe ihres selbsternannten Kriegshäuptlings Kargath Messerfaust, und ich werde Euch reich belohnen.", progress = "Seid Ihr mit den Überresten von Kriegshäuptling Messerfaust zurück?", completion = "Gut gemacht, &lt;Name&gt;. Mit Eurem Sieg in der Höllenfeuerzitadelle haben wir den Orcs großen Schaden zugefügt.\n\nIhr müsst mit Feldkommandeur Romus über das weitere Vorgehen und das Ziel, die Orcs weiter in der Defensive zu halten, sprechen. Jetzt, da wir Verstärkung haben, können wir die Ehrenfeste viel leichter verteidigen.", rewards = "Mantel der BelebungNethekurses Rute der QualenAuf Euch wartet eine dieser Belohnungen:\n\nNalikos RacheMedaillon des tapferen Wächters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9493] = {title = "Der Stolz der Höllenhorde", objective = "Feldkommandeur Romus in der Ehrenfeste möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.", description = "Wir wissen herzlich wenig über die Höllenhorde in der Höllenfeuerzitadelle, und die Informationen, die wir haben, wurden teuer mit Blut bezahlt.\n\nDie Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust sind ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.\n\nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.", progress = nil, completion = "Das sind großartige Nachrichten, &lt;Name&gt;. Mit diesen Fortschritten bei der Höllenfeuerzitadelle können wir es vielleicht sogar wagen, die Höllenhorde auch in anderen Orten der Halbinsel und der ganzen Scherbenwelt zu bekämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9494] = {title = "Teufelsglut", objective = "Magus Zabraxis in der Ehrenfeste möchte, dass Ihr ihr ein Stück Teufelsglut bringt.", description = "Die altmodischen Akademiker Azeroths haben sich schon viel zu lange in ihren Türmen versteckt. Jetzt ist es an mir, ihnen zu zeigen, was hochmoderne Forschung bedeutet! Sie haben Angst, mit dem Feuer zu spielen, und genau das werde ich tun! Das heißt, sobald ich dieses Feuer in die Finger bekomme.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle vollbringt der Großhexenmeister Nethekurse unerreichte magische Meisterleistungen, die von der Macht einer ungewöhnlichen Kohlenpfanne noch verstärkt werden. Benutzt dieses Gefäß, um ein Stück Teufelsglut zu fangen, und bringt es zu mir, <Name>.", progress = "<Magus Zabraxis schaut zu Amythiel Nebelgänger hinüber und senkt ihre Stimme.>\n\nHabt Ihr die, ähm, Glut?", completion = "Gut gemacht! Ich maße mir nicht an, Nethekurses Meisterwerke nachahmen zu können, aber wir wären dumm, wenn wir die Macht der Teufelsglut außer Acht lassen würden.\n\nEs gibt jedoch einige, die meine Art der Forschung verbieten wollen, deshalb muss ich meine Entdeckungen geheim halten. Bitte erzählt niemandem davon, &lt;Name&gt;.", rewards = "Unerschrockene HandschützerGravierter RunengürtelSpäherschulterklappen der ExpeditionHandschuhe der BewahrungStiefel des KuratIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9495] = {title = "Der Wille des Kriegshäuptlings", objective = "Bringt Kriegshäuptling Kargaths Faust zu Nazgrel in Thrallmar.", description = "Es ist nicht einfach, das orcische Volk von seinen verderbten Blutsverwandten zu befreien, <Name>. Kriegshäuptling Thrall hat schon zu viele orcische Helden durch die Hand des Schicksals fallen sehen. Und nun scheint es, als ob auch Kargath Messerfaust ihm zum Opfer gefallen ist.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle hat Kargath sich selbst den Titel Kriegshäuptling der Höllenhorde gegeben. Er und seine Armee von irren und blutdurstigen Höllenorcs werden nicht ruhen, bis Thrallmar in Trümmern liegt. Kriegshäuptling Thrall hat befohlen, Kargath und seine Streitkräfte koste es was es wolle zu vernichten.", progress = "Habt Ihr einen Beweis für den Sieg über Kargath Messerfaust?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. In seiner Jugend war Kargath Messerfaust ein vortrefflicher Krieger, ein Held und ein gutes Beispiel für sein Volk.\n\nSein Tod ist für uns alle schmerzhaft, jedoch besonders für Kriegshäuptling Thrall. Was auch immer in seinen letzten Tagen mit ihm geschehen sein mag, wir dürfen nie den Orc vergessen, der Kargath einst war, genauso wenig wie die Lektion, die uns sein Fall sein sollte.\n\nFür Eure Dienste für die Horde werdet Ihr mit einer dieser Waffen belohnt, &lt;Name&gt;.", rewards = "Rute der finsteren SchattenVikarsumhangAuf Euch wartet eine dieser Belohnungen:\n\nBand des EroberersStümmelfausts Halsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9496] = {title = "Der Stolz der Höllenhorde", objective = "Schattenjäger Ty'jin in Thrallmar möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.", description = "Von Oberanführer Stümmelfaust mal abgesehen, <Name>, ist mit der Höllenhorde nicht zu spaßen.\n\nSoweit wir wissen, sind die Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.\n\nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Jetzt, da die Legionäre gefallen sind, wird es einfacher, der Höllenhorde auf dem Schlachtfeld zu begegnen, auch wenn sie immer noch ein ernstzunehmender Gegner ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9497] = {title = "Emblem der Höllenhorde", objective = "Tötet Kriegshetzer O'mrogg und besorgt Euch das Banner der Höllenhorde. Kehrt danach zu Oberanführer Hun Stümmelfaust in Thrallmar zurück.", description = "Als der Kriegshäuptling von der so genannten Höllenhorde hörte, wurde er sowohl wütend als auch sehr traurig. Wie Rend und seine Hochstapler damals wird auch diese falsche Horde fallen, und ihr Banner wird als Zeichen für die Macht unseres Kriegshäuptlings von den Zinnen der Feste Grommasch wehen.\n\nEs liegt an Euch, in dieser Angelegenheit den Willen des Kriegshäuptlings auszuführen, <Name>. Es wird nicht einfach werden, denn das Banner wird von einem Champion der Höllenhorde, bekannt als Kriegshetzer O'mrogg, bewacht. Er wird sich das Banner nicht ohne Kampf nehmen lassen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Fußlappen des KuratKnochenbeschlagener GurtHandschuhe der BewahrungSchiftung der lauernden SchattenSchmettergriffIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9498] = {title = "Falkenwacht", objective = "Meldet Euch bei Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.", description = "Mein Volk hat die Falkenwacht erst kürzlich als Operationsbasis im Südwesten der Höllenfeuerhalbinsel, hinter der Höllenfeuerzitadelle, fertiggestellt. Man wird Euch dort als Verbündeten willkommen heißen, <Name>.\n\nWenn Ihr also auf der Suche nach Arbeit seid, reist dorthin und sagt Waldläuferhauptmann Venn'ren, dass ich Euch geschickt habe. Er wird Euch sicherlich eine Aufgabe zuweisen können, die Eurer Fähigkeiten würdig ist.", progress = nil, completion = "Willkommen in der Falkenwacht, &lt;Volk&gt;. Alle Verbündeten der Horde sind hier willkommen, insbesondere all jene, mit einer Empfehlung von Martik.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9499] = {title = "Falkenwacht", objective = "Reist zur Falkenwacht im Südwesten der Höllenfeuerhalbinsel und meldet Euch bei Waldläuferhauptmann Venn'ren.", description = "Was macht Ihr denn noch hier, <Name>? Habt Ihr nicht gehört, dass wir einen anständigen Außenposten der Sin'dorei auf der Höllenfeuerhalbinsel errichtet haben?\n\nIhr wärt doch sicher viel lieber bei den Blutelfen als bei all diesem... Gestank hier. Ihr findet die Falkenwacht im Südosten, hinter der Höllenfeuerzitadelle. Meldet Euch bei Waldläuferhauptmann Venn'ren, er wird sich um Euch kümmern.\n\nDie Straße dorthin ist sehr gefährlich und wird von den Spähern der Allianz überwacht. Reist lieber in Begleitung. Am besten mit Blutelfen.", progress = nil, completion = "Willkommen in der Falkenwacht, Bruder. Viele andere Blutelfen haben es leider nicht geschafft, heil hier anzukommen.\n\nEs ist eine Schande. Unsere Arbeit in der Scherbenwelt hat doch gerade erst begonnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9500] = {title = "Ruf des Wassers", objective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Weissager Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9501] = {title = "Ruf des Wassers", objective = "Sprecht mit Aqueous im Versteckten Riff bei der Blutmythosinsel.\n\nBereitgestellter Gegenstand: \n", description = "Ein mächtiger Wasserelementar namens Aqueous hat nach Euch verlangt. Anscheinend ist das Element des Wassers auf der Blutmythosinsel aus dem Gleichgewicht geraten, was bei der unnatürlichen Vorliebe der Blutelfen nicht wirklich verwunderlich ist.\n\nIhr findet Aqueous in einem versteckten Riff unter den Wogen vor der Küste im Norden der Blutmythosinsel.\n\nNehmt diesen Trank, er wird Euch auf Eurem Weg zu Aqueous behilflich sein, sobald Ihr in der Nähe des Riffs im Wasser seid.", progress = nil, completion = "Fürchtet Euch nicht, &lt;Name&gt;. Wir werden hier mit Hilfe unserer Gedanken miteinander kommunizieren.\n\nIch bin Weissager Nobundo dankbar, dass er Euch zu mir gesandt hat. Etwas verunreinigt das Wasser auf und um die Blutmythosinsel herum. Nicht einmal einem Blinden würde der Effekt entgehen, den diese Störung auf die Kreaturen hat.\n\nIhr und ich werden zusammen gegen diese Verderbnis vorgehen, bevor sie sich noch weiter ausbreitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9502] = {title = "Ruf des Wassers", objective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?", progress = nil, completion = "So treffen wir uns wieder. Ich habe Eure Fortschritte aus der Ferne beobachtet, &lt;Klasse&gt;, ich bin sehr zufrieden.\n\nEs ist jetzt an der Zeit, dass Ihr mit dem Element des Wassers vertraut werdet. Ihr sollt die Geheimnisse des Wassers erlernen und Euch diesem Wissen widmen, um es mit der Zeit auch beherrschen zu können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9503] = {title = "Ruf des Wassers", objective = "Sammelt 6 besudelte Essenzen ein und bringt sie zu Aqueous im Versteckten Riff bei der Blutmythosinsel.", description = "In Verbindung mit den anderen Elementen ist Wasser der Quell und die Grundlage allen Lebens. Alle Kreaturen sind darauf angewiesen. Allerdings bringt das Wasser durch die Verunreinigung jetzt auch den Tod.\n\nWir müssen das Ausmaß des Schadens erfassen. Im Südwesten liegt ein derart verderbtes Gewässer, welches mittlerweile als besudelter Teich bekannt ist. Geht dorthin und besorgt Euch besudelte Essenzen von den dort lebenden Wassergeistern.", progress = "Habt Ihr die besudelten Essenzen meiner bedauernswerten Schwestern bereits eingesammelt, <Name>?", completion = "Ich danke Euch, &lt;Klasse&gt;. Dies sollte für meine Untersuchung der Verunreinigung ausreichen. Schon bald werden wir wissen, auf welche Weise wir vorgehen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9504] = {title = "Ruf des Wassers", objective = "Füllt den leeren Botabeutel und kehrt anschließend zu Aqueous im Versteckten Riff bei der Blutmythosinsel zurück.", description = "Es ist schlimmer als ich befürchtet hatte. Die Verunreinigung ist hartnäckig und könnte, wenn man nicht rechtzeitig handelt, ungehindert in die Ströme des Meeres fließen und sich somit in ganz Azeroth ausbreiten!\n\nWir brauchen eine Probe reinsten Wassers, um diesem Übel entgegenzuwirken. Auf der nicht verunreinigten Seite dieser Insel, im Südwesten, befinden sich Ruinen. Geht dorthin, wo die Naga der Hasspranken hausen, und entwendet eine Probe aus ihrem Brunnen.\n\nNehmt diesen Botabeutel, um die Probe zu transportieren. Beeilt Euch, <Name>!", progress = "Habt Ihr das reine Wasser von den Ruinen?", completion = "Wasser schwindet schnell, vereinigt man aber genug davon, bildet es eine unaufhaltsame Kraft. Es spült Erde und Feuer hinfort und bahnt sich auch durch die Luft seinen Weg.\n\nWir sind diese unaufhaltsame Kraft, &lt;Name&gt;, nicht diejenigen, die die Blutmythosinsel vergiftet haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9505] = {title = "Die Prophezeiung von Velen", objective = "Daedal möchte, dass Ihr nach Süden reist und die Personen aufsucht, von denen das verletzte Wesen gesprochen hat.", description = "Der Prophet sprach von diesem Tag, da auf dieser Insel, in dieser Welt, sich uns unsere Verbündeten offenbaren würden.\n\n\"Man wird uns auf die Probe stellen. Wir werden für die Sünden unserer Vorväter bezahlen...\"\n\nDamals blieb mir der Sinn seiner Worte verborgen; doch in dem Moment, als ich dieses Wesen erblickte, wurde mir die Bedeutung seiner Prophezeiung gewahr. Selbst an diesem Ort verspüre ich noch die schleichende Verderbnis unseres Volkes.\n\nBegebt Euch nach Süden, dort wo wir sie gefunden haben. Findet Ihresgleichen und berichtet ihnen von unserem Volk.", progress = nil, completion = "Ihr sagt, dass Ihr eines unserer Besatzungsmitglieder gefunden habt und dass sie schwer verletzt ist? Ich werde umgehend ein Mitglied meiner Besatzung in Euer Dorf entsenden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9506] = {title = "Ein kleiner Anfang", objective = "Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr den von der Venture Co. gestohlenen nautischen Kompass und die nautische Karte wiederbeschafft.", description = "Ich bin Admiral Odesyus vom Marinekommando der Allianz. Eine Plage der besonderen Art zwang uns dazu, an der Küste Eurer Insel vor Anker zu gehen. Es beschämt mich das sagen zu müssen, doch ein paar Goblins haben es irgendwie geschafft, sich als blinde Passagiere in den Frachträumen unserer beiden Schiffe zu verstecken.\n\nLetzte Nacht, als der Großteil der Schiffsmannschaften in den Kojen lag, schlugen sie zu!\n\nSie stahlen unsere Navigationsinstrumente und sprangen von Bord!\n\nAnschließend verschwanden sie im Dickicht, östlich von hier. Werdet Ihr uns bei der Suche nach den Instrumenten behilflich sein? Es wäre eine großzügige Geste von Euch.", progress = "Hattet Ihr Erfolg, Fremder?", completion = "Ihr seid verdammt einfallsreich! Jetzt, da wir unsere Navigationsinstrumente zurückerhalten haben, sollte es leicht sein, herauszufinden, wie weit wir vom Kurs abgekommen sind.\n\nAber wartet, was ist das? Da ist etwas in der Karte eingerollt. Lasst mich mal sehen...\n\nDas sind Befehle von Mogul Raztunk der Venture Company. Laut diesen Plänen sind sie hier, um die Insel ihrer Kristalle zu berauben und unsere Schiffe zu kapern, wenn sie fertig sind!\n\nBei Bronzebarts buschiger Braue! Deswegen haben sie uns an Land gezwungen? Wie konnten sie von unseren Plänen erfahren?\n\nDas riecht nach einem Verräter...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9508] = {title = "Ruf des Wassers", objective = "Bringt Tel'athions Kopf zu Aqueous im Versteckten Riff bei der Blutmythosinsel zurück.", description = "Ich habe den Ursprung der Verunreinigung gefunden. Es ist das Nebenprodukt eines wahnsinnigen Experiments und Ihr werdet dem Ganzen ein Ende bereiten!\n\nSüdwestlich des Besudelten Teichs liegt ein kleines Lager, wo Ihr auf das 'Experiment' von Tel'athion dem Unreinen stoßen werdet. An diesem Ort erzeugt er den Unrat und lässt ihn in die Gewässer der Insel sickern.\n\nVerwendet das reine Wasser aus dem Eschental, um seine Fässer zu zerstören. Das wird ihn sicherlich aus seinem Versteck locken.\n\nWir werden das alles ein für alle Mal beenden!", progress = "Wart Ihr erfolgreich?", completion = "Wir haben es geschafft! Der Katastrophe wurde vorgebeugt und Ihr habt die Erholung der Gewässer von der Blutmythosinsel in Gang gesetzt. Mit der Zeit wird sich das Wasser, in Verbindung mit den anderen Elementen, wieder von selbst heilen.\n\nEs ist wirklich traurig, die Blutelfen sehen einfach nicht, wie sie sich durch die Zerstörung ihrer Umgebung  langsam selbst vernichten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9509] = {title = "Ruf des Wassers", objective = "Nehmt das Fläschchen mit reinstem Wasser zu Scharfseher Nobundo innerhalb der Exodar auf der Azurmythosinsel.", description = "Ich habe etwas von dem Wasser aus dem Eschental beiseite gelegt, jedoch nicht, weil ich an Euren Fähigkeiten, die Situation in den Griff zu bekommen, gezweifelt habe. Im Gegenteil, ich wusste, dass Ihr Erfolg haben würdet. Ich wollte lediglich sicherstellen, dass Ihr etwas Besonderes habt, das Ihr zurück zu Nobundo bringen könnt.\n\nHier, <Name>, nehmt dieses Fläschchen mit reinstem Wasser. Die Erstellung eines mächtigen Wassertotems ist Euch dadurch gewiss.\n\nScharfseher Nobundo erwartet Eure Rückkehr bei der Exodar.", progress = "Die Elemente haben mir von großen Taten erzählt, die Ihr vollbracht habt. Kommt, sprecht mit mir.", completion = "Ihr habt eine Weisheit an den Tag gelegt, die Eurem Alter vorauseilt, &lt;Name&gt;. Ich kann spüren, dass das Element des Wassers mit Euch zufrieden ist. Es ist eine Ehre für mich, wenn ich das reine Wasser, das Ihr mir gebracht habt, in Euer neues Wassertotem einfließen lassen kann.\n\nVergesst niemals die Lehren des Wassers und Ihr werdet das Element mit der Zeit noch besser verstehen und zu meistern lernen.", rewards = "Ihr erlernt:\n\nTotem des heilenden Flusses\n\nIhr bekommt außerdem:\n\nWassertotem"}
MultiLanguageQuestData['de'][9511] = {title = "Kargaths Schlachtpläne", objective = "Die Dokumente, die Ihr bei Kargath gefunden habt, enthalten genaue Pläne für einen großen Angriff auf die Ehrenfeste.", description = "Die Dokumente, die Ihr bei Kargath gefunden habt, enthalten genaue Pläne für einen großen Angriff auf die Ehrenfeste.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9512] = {title = "Kräckas Jumboeintopf", objective = "\"Kräcka\" Aschebäscha bei Odesyus' Ankerplatz möchte, dass Ihr ihm 6 Stücke Raubkriecherfleisch bringt.", description = "Der Admiral hat wohl Recht, Ihr seid ziemlich clever. Könnt Ihr Kräcka vielleicht aushelfen?\n\nWenn ich der Mannschaft noch einmal Hühnchen vorsetze, werden'se mich sicher kielholen.\n\nHab' gesehen, dass es an der Küste nur so von Kriechern wimmelt! Bringt mir Kriecherfleisch und ich steh' für immer in Eurer Schuld.\n\nHelft Ihr 'nem ehemaligen Piraten aus der Patsche?", progress = "Arrr... Jarr... beim Klabautermann... Eh, 'tschuldigung Junge, ich muss mal wieder 'n bisschen Pirat spielen, bevor ich's ganz vergesse...", completion = "Erste Sahne, Fremder. Das wird helfen, die Moral der Mannschaft wieder mächtig aufzumöbeln.", rewards = "Ihr bekommt:\n\nKräckas Jumboeintopf"}
MultiLanguageQuestData['de'][9513] = {title = "Die Rückeroberung der Ruinen", objective = "Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr 5 Myrmidonen der Hasspranken, 5 Naga der Hasspranken und 5 Sirenen der Hasspranken tötet.", description = "Während einige glauben, dass unsere momentane Lage das Resultat einer langen Kette von unglücklichen Ereignissen ist, glaube ich vielmehr, dass wir aus einem bestimmten Grund hier sind. Die unsichtbare Hand des Schicksals hat uns an diesen Ort verschlagen. Die Gründe dafür werden sich uns im Laufe der Zeit offenbaren.\n\nIm Westen liegt eine uralte Stadt der Nachtelfen, heute sind es nur noch von Naga besetzte Ruinen. Ich wäre nachlässig, würde ich tatenlos zusehen, wie die Naga weiterhin das Land meiner Vorfahren mit ihrer Anwesenheit beflecken.\n\nIhr habt Eure Fähigkeiten als <Klasse> unter Beweis gestellt. Nun ehrt mein Volk und reinigt diese Ruinen von seinen unrechtmäßigen Einwohnern.", progress = nil, completion = "Gelobt sei Elune! Mögen die ruhelosen Geister endlich Frieden finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9514] = {title = "Runenbesetzte Schrifttafel", objective = "Bringt die runenbesetzte Schrifttafel zu Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel.", description = "Es gelingt Euch nicht, die Symbole auf der Schrifttafel zu entziffern. Vielleicht ist die Priesterin in der Lage, die mysteriösen Runen zu entschlüsseln.", progress = "Ihr habt etwas entdeckt?", completion = "Ich kann diese Runen leider nicht entziffern, doch ich kenne jemanden, der dies zu tun vermag...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9515] = {title = "Kriegsherr Sriss'tiz", objective = "Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr Kriegsherr Sriss'tiz tötet.", description = "Eine Nagainvasion wäre ein Desaster, <Name>. Ich habe gesehen, was diese Naga anrichten können und ich werde es nicht zulassen, dass sie weiter über unschuldige Wesen herfallen. Ich nehme an, dass dieser Kriegsherr Sriss'tiz sich in einer Höhle versteckt - möglicherweise irgendwo an der Küste im Westen.\n\nMacht Kriegsherr Sriss'tiz ausfindig und beendet seine Herrschaft für immer!", progress = nil, completion = "Nach dem Tod von Kriegsherr Sriss'tiz dürfte die Gefahr einer Nagainvasion fürs Erste gebannt sein...\n\nIch muss gestehen, es war falsch von mir, so schlecht über Euch zu denken, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr weit entfernt seid vom Abschaum, der sich Archimonde nannte. Bitte nehmt dieses Geschenk der Nachtelfen als ein Zeichen der Freundschaft entgegen.", rewards = "NagaschuppenstiefelKampfbewährte KlingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9516] = {title = "Zerstört die Legion", objective = "Tötet 15 Dämonen auf dem Dämonenhügel, dem Dämonensturz und dem Dämonenstieg.", description = "Ich werde Ihre Existenz in dieser Welt nicht tolerieren! Die Brennende Legion hat unser Volk fast ausgerottet, und wir mussten ein neues Zuhause in einer neuen Welt suchen. Dann kamen sie erneut. Und wir haben uns zurückgezogen, immer und immer wieder.\n\nNie wieder!\n\nIm Süden gibt es noch ein Überbleibsel der Legion, in den Regionen, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind. Sie sind von dieser Macht, die einst in Eure Welt eingedrungen ist, übriggeblieben.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt, bevor es zu spät ist!", progress = nil, completion = "Ihr habt meinen Respekt und meinen Dank, &lt;Klasse&gt;. Vielleicht können wir hier ein neues Zuhause errichten, ohne ein weiteres Mal die Brennende Legion fürchten zu müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9517] = {title = "Eine schändliche Verschwendung", objective = "Sammelt 5 Stück verdorbenes Satyrnaarholz.", description = "Willkommen in Waldeslied, <Klasse>. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.\n\nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.", progress = "<Das Urtum knarrt, als es sich zu Euch umdreht>\n\nArchitekt Nemos sagte, Ihr brächtet Holz, das Ihr aus dem Lager der Roder und dem verdorbenen Satyrnaar errettet habt.", completion = "Holz, das mit den rohen Klingen der Orcs gefällt wurde, ist genauso verzogen, als wäre es extremen Witterungsbedingungen ausgesetzt worden. Nichts Vernünftiges lässt sich daraus erbauen, doch ich werde es reinigen und Architekt Nemos zurückgeben, auf dass er und seine Mannen es benutzen können. So wird die Tragödie doch ein gutes Ende haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9518] = {title = "Agenten der Zerstörung", objective = "Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.", description = "Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!\n\nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, <Name>, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!\n\nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!", progress = nil, completion = "Endlich haben wir ein Zeichen gesetzt, das die Orcs nicht ignorieren können. Jeder Vorarbeiter oder Großknecht, der einen Fuß in das Lager setzt, um Gorthak zu ersetzen, wird meinen Zorn zu spüren bekommen!\n\nWir müssen unseren Vorteil ausnutzen, &lt;Name&gt;, und nicht ruhen, bevor das Holzfällerlager des Kriegshymnenklans nichts mehr als eine weit entfernte Erinnerung ist und junge Bäume ihre Wurzeln in diesen Boden schlagen.", rewards = "SternwisperschiftungWaldschutzwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9519] = {title = "Elunes Kelch", objective = "Bringt Elunes Kelch in Euren Besitz.", description = "Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.\n\nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, <Name>.", progress = "Könnt Ihr ihn fühlen, <Name>, den Hauch von Verderbnis im Wind? Wenn wir nichts tun, wird er noch stärker werden. Deshalb suche ich Elunes Kelch. Konntet Ihr ihn finden?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Es schlummert eine deutliche Macht in ihm, die nicht einmal die Verderbnis der Satyrn trüben kann. Seht Ihr, wie er immer noch glänzt, nach all den Jahren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9520] = {title = "Teuflische Pläne", objective = "Bringt die teuflischen Pläne zu Verteidiger Vedaar im Holzfällerlager des Kriegshymnenklans im Eschental.", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise in der Allgemeinsprache verfasst wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend befehligen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf Waldeslied im Norden, wo gerade eine neue Draeneisiedlung errichtet wird.\n\nVielleicht ist Verteidiger Vedaar im Holzfällerlager des Kriegshymnenklans daran interessiert?", progress = "Was habt Ihr da, werter Herr?", completion = "Bei den sieben Kristallen von Ata'mal, das kann nicht sein! Sie planen uns hier in Waldeslied anzugreifen?!\n\nNicht solange ich hier wache!\n\n&lt;Verteidiger Vedaar zerknüllt die Pläne mit dem Dämonengekritzel in seiner Faust.&gt;\n\nNein. Das werden wir nicht zulassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9521] = {title = "Bericht von der Nordfront", objective = "Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.", description = "Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, <Name>. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.\n\nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?", progress = "Was habt Ihr da, <Klasse>?", completion = "Vielen Dank für diesen Bericht, &lt;Name&gt;. Nach dem, was Schildwache Luciel schreibt, scheint es, als wären unsere schlimmsten Befürchtungen wahr geworden. Mit jedem Fortschritt, den wir machen, scheint die Horde umso entschlossener, so viel Schaden wie möglich anzurichten.\n\nWir können es uns nicht leisten, klein beizugeben. Das Schicksal des Landes unserer Vorfahren liegt im Gleichgewicht der Natur. Wenn wir mehr von Eurer Sorte an der Front hätten, könnten wir sicher triumphieren. Werdet Ihr Euch unserem Kampf anschließen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9522] = {title = "Nie wieder!", objective = "Erhaltet Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", description = "<Name>, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Ihr müsst losziehen und ihre Anführer erschlagen. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals der Horde für Grom Höllschrei.\n\nBringt mir ihre Waffen.", progress = nil, completion = "Nie wieder wird uns die Brennende Legion hier bedrohen! Ihr habt uns vor einem Kampf gerettet, den wir sicher verloren hätten, &lt;Klasse&gt;.\n\nIch schulde Euch meinen persönlichen und den Dank der Hand von Argus. Es ehrt mich, Euch auf unserer Seite zu haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand von ArgasSiegel von ArgasSignet von Argas\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9523] = {title = "Marmor, Stein und Eisen bricht, aber uralte Nachtelfenrelikte nicht...", objective = "Archäologe Adamant Eisenherz bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm 8 uralte Relikte bringt.", description = "Die Priesterin sagte mir, dass die Ruinen im Westen die Überreste einer Nachtelfenkultur sind. Das erinnerte mich wiederum an etwas, was mein Paps immer über Nachtelfenruinen zu sagen pflegte: \"Kleiner, wenn du Nachtelfenruinen siehst, dann sind bestimmt auch Nachtelfenrelikte in der Nähe.\"\n\nWas für ein Zwerg wäre ich wohl, wenn ich nicht die erste Person anstellen würde, die mir über den Weg läuft, um für mich nach Nachtelfenrelikten zu graben? Los jetzt!", progress = "Kommt nicht ohne uralte Relikte zurück.", completion = "Mein Paps wäre stolz! Sein Junge hat bei den ersten Nachtelfenruinen, auf die er gestoßen ist, das große Los gezogen... dank Eurer Hilfe natürlich. Ja, macht Euch keine Sorgen, ich werde Euch nicht von der Entdeckung ausschließen. Euer Name ist &lt;Name&gt;, stimmt's? In Eisenschmiede werden alle von Euch hören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9524] = {title = "Gefangene der Zitadelle", objective = "Rettet Hauptmann Alina aus der Höllenfeuerzitadelle, bevor sie hingerichtet wird.\n\nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten.", description = "Allianztruppen, hier?! Hört mir genau zu, <Klasse>.\n\nKargath hat viele unserer Kämpfer gefangen genommen. Unter ihnen ist auch Hauptmann Alina, einer unserer wichtigsten Offiziere. Rettet sie, bevor sie hingerichtet wird.\n\nMacht Euch um mich keine Sorgen, ich komme hier schon heraus, lasst mich nur etwas Luft schnappen.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Eigentlich hatte ich nicht mehr mit dem Eintreffen einer Rettungstruppe gerechnet.\n\nIch werde die überlebenden Gefangenen versammeln und sie zur Ehrenfeste zurückführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9525] = {title = "Gefangene der Zitadelle", objective = "Rettet Hauptmann Knochenbrecher aus der Höllenfeuerzitadelle, bevor er hingerichtet wird.\n\nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten.", description = "Ich hatte Glück und konnte Kargaths Verlies entkommen, <Name>. Die Hinrichtung der meisten Gefangenen wurde bereits angesetzt, unter ihnen befindet sich einer unserer wichtigsten Offiziere.\n\nHauptmann Knochenbrechers Tod wäre für uns ein schwerer Schlag. Tut alles in Eurer Macht stehende, um ihn vor seinem Schicksal zu bewahren. Ich bin zu schwach, um weiter zu machen...", progress = nil, completion = "Ihr habt meinen Tag gerettet, &lt;Klasse&gt;. Wenn ich sterbe, dann auf dem Schlachtfeld... bedeckt von dem Blut meiner Feinde, werde ich sie mit mir in den Abgrund reißen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9526] = {title = "Die Rückeroberung des Dämonenhügels", objective = "Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.", description = "Kleines Wesen. Im Süden gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.\n\nWürdet Ihr etwas tun, um dabei zu helfen, das Land zurückzuerobern?\n\nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.", progress = nil, completion = "Gut. Auch wenn es vielleicht lange Zeit dauern mag, bis aus den Setzlingen Uralte werden, werden sie uns dann im Kampf gegen die Dämonen am Dämonenhügel helfen können.\n\nGeht in Frieden, kleiner Bruder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9527] = {title = "Was noch bleibt", objective = "Cowlen auf der Azurmythosinsel möchte, dass Ihr ihm die Überreste von Cowlens Familie bringt.", description = "Wir lebten viele Jahre in Frieden mit den Kreaturen dieser Insel. Ihr könnt Euch vorstellen, wie überrascht ich war, als sie den Strand stürmten und uns angriffen.\n\nIch habe mich mit Händen und Füßen gewehrt, wurde aber sofort überwältigt. Als ich auf Grund der zahlreichen Schläge in Ohnmacht fiel, betete ich, dass meine Familie nicht leiden muss.\n\nIch erwachte und alles war ruhig. Der Sand war rot, vor Blut getränkt - mit ihrem Blut. Man hatte sie vollständig verschlungen.\n\nIch sehne mich nicht nach Rache, <Name>. Ich wünsche mir nur, dass man mir ihre Überreste bringt, damit ich sie ordnungsgemäß bestatten kann.", progress = "Meine Frau hieß Thalrisa und meine Tochter Magwin.", completion = "Ich danke Euch, &lt;Name&gt;. Ihre Geister können nun in Frieden ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9528] = {title = "Ein Hilferuf", objective = "Begleitet Magwin über die Insel zu ihrem Zuhause.", description = "Meine Familie wurde vor einigen Wochen von den Murlocs und Eulkin dieser Insel überfallen. Ich schaffte es zu fliehen, aber ich glaube, dass mein Vater und meine Mutter getötet wurden. Ich weiß nicht, was ich jetzt tun soll, aber ich muss versuchen, zurück zu meinem Zuhause zu gehen - oder was davon übrig ist... Könnt Ihr mich durch den Wald begleiten?", progress = "Seid gegrüßt, <Name>.", completion = "&lt;Freudentränen strömen über Cowlens Gesicht.&gt;\n\nWie kann ich Euch dafür jemals genug danken, &lt;Name&gt;? Bitte, nehmt dieses Erbstück. Es symbolisiert die heiligen Bande der Freundschaft sowie das Vertrauen und die Verbundenheit zwischen den Nachtelfen. Ihr seid wie ein Bruder für mich - vom heutigen Tag bis in alle Ewigkeit...", rewards = "Ihr bekommt:\n\nCowlens Armschienen der Blutsverwandtschaft"}
MultiLanguageQuestData['de'][9529] = {title = "Der Stein", objective = "Beschafft Euch einen Leerstein von der Todesschneise.", description = "Ich bin mir sicher, dass Euer Wichtel sich als nützlicher und manchmal auch unterhaltsamer Begleiter bewiesen hat. Es ist jetzt an der Zeit, dass Ihr einen mächtigeren Dämonen zu beherrschen lernt: den Leerwandler.\n\nReist bis zu dem Punkt der Todesschneise, an dem sie vom Elrendar gekreuzt wird. Macht direkt südlich vom Fluss einen der blauen glühenden Steine ausfindig und nehmt ihn. Euer Weg wird sich Euch dort offenbaren.", progress = nil, completion = "Als Ihr in den Stein blickt, scheint sich Eure Sicht zu verklären...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9530] = {title = "Einen Plan aus Hecken", objective = "Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm einen ausgehöhlten Stamm und 5 Laubhaufen bringt.", description = "Ich habe eine ganze Zeit nun darüber gegrübelt, aber es stellt sich als wahr heraus.\n\nEs gibt einen Verräter unter uns.\n\nDie Pläne, die von den Goblins zurückgelassen wurden, bestätigen diesen Komplott. Da ich nicht weiß, wer es sein könnte, benötige ich Eure Hilfe, um den Verräter auszumachen. Keinem aus meiner Mannschaft kann vertraut werden.\n\nFür ein gelungenes Unterfangen benötige ich einen ausgehöhlten Stamm und Laub. Sucht in der Nähe der Holzarbeiter nördlich von uns nach dem Baumstamm. Das Laub müsst Ihr selbst auftreiben. Durchforstet den Wald.", progress = "Ich liebe es, wenn ein Plan aufgeht...", completion = "Ich muss Euch warnen: Das, was ich als Nächstes von Euch verlangen werde, ist sehr gefährlich. Ich würde es Euch nicht verdenken, wenn Ihr mir dabei lieber nicht aushelfen wollt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9531] = {title = "Laubangriff", objective = "Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr das Treffen beobachtet, das Geezle und der Verräter gemeinsam ausgemacht haben.\n\nKehrt zu ihm zurück, wenn Ihr ihm die Identität des Verräters mitteilen könnt.", description = "Der Verräter wird sich den Plänen zufolge mit dem Anführer der Goblins, Geezle, bei einer Bucht auf der westlichen Insel treffen. Ihr müsst zu diesem Treffen gehen, <Name>.\n\nErinnert Ihr Euch an den Stamm und das Laub? Ihr müsst Euch damit verkleiden! Es ist die perfekte Tarnung.\n\nGeht zur Bucht und haltet nach einer Nagaflagge Ausschau. Seht Ihr die Flagge, so wurde ein Treffen arrangiert. Legt die Verkleidung an, wenn Ihr die Flagge seht, und wartet. Der Verräter wird sich früher oder später zeigen. Lasst das Treffen enden und kehrt anschließend mit der Identität des Schufts zu mir zurück.", progress = "Der Verräter wird noch bereuen, dass er sich mit dem Marinekommando der Allianz angelegt hat!", completion = "Ich kann es nicht glauben! Der Gnom war es, die ganze Zeit über... Ich hätte es wissen sollen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9532] = {title = "Findet Keltus Dunkellaub", objective = "Macht Keltus Dunkellaub ausfindig.", description = "<Name>, einer unserer Späher nimmt seine Pflichten ein wenig zu ernst. Er bewacht unsere Feinde ohne Unterlass, erstattet uns aber keine Berichte darüber.\n\nIhr müsst diesen Spion, Keltus Dunkellaub, finden und überzeugen, damit er seinen Bericht aushändigt und so schnell wie möglich zu mir zurückkommt. Ihr findet ihn weit im Südwesten, wo der Elrendar sich teilt und um Goldnebel herum fließt. Er beobachtet die Nachtelfen von An'daroth und hält sich sicher in ihrer Nähe auf.", progress = nil, completion = "Ich hoffe Ihr könnt sehen, dass ich verdeckt arbeite... zumindest hatte ich das.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9533] = {title = "Eine helfende Hand", objective = "Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.\n\nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.", description = "Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.\n\nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, <Name>, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er bat mich, <jeden Mann, der/jede Frau> die; Interesse hat, zu ihm zu schicken.", progress = nil, completion = "Es ist schön, einen Neuankömmling hier in Waldeslied begrüßen zu dürfen.\n\nVerteidigerin Palanaar sendet so viel Hilfe, wie sie aufbringen kann, und jede helfende Hand ist willkommen.\n\nSchaut Euch um, &lt;Klasse&gt;. Es ist vielleicht noch nicht viel, aber mit der Zeit und der Hilfe unserer Nachtelfenverbündeten werden wir eine Siedlung errichten, die es wert ist, Zuhause genannt zu werden. Es gibt hier viel zu tun, und für jede Hilfe, die Ihr uns leisten könnt, sind wir sehr dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9534] = {title = "Zerstört die Legion", objective = "Tötet 15 Dämonen auf dem Dämonenhügel, dem Dämonensturz und dem Dämonenstieg und kehrt dann zu Valusha am Splitterholzposten im Eschental zurück.", description = "Die Überreste der Brennenden Legion sind uns schon viel zu lang ein Dorn im Auge!\n\nDas hat jetzt ein Ende!\n\nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt, und erlangt Ruhm für Euch selbst und für die Horde!", progress = nil, completion = "So ist es schon besser! Nichts ist so gut, wie unsere Welt von einem Dämonen zu befreien. Und sie sind würdige Gegner, nicht so wie die schwachen Völker der Allianz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9535] = {title = "Teuflische Pläne", objective = "Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten.\n\nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.", progress = "Was habt Ihr da, Bruder?", completion = "Schreckenslords! Sie planen uns hier am Splitterholzposten anzugreifen?!\n\nNicht solange ich noch am Leben bin!\n\n&lt;Valusha zerknüllt die Pläne mit dem Dämonengekritzel in ihrer Faust.&gt;\n\nNein. Wir werden das nicht zulassen. Sie sind ein Schandfleck in unserer Welt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9536] = {title = "Nie wieder!", objective = "Erhaltet Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", description = "<Name>, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet! Geht und erschlagt diese Schreckenslords! Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz.\n\nKehrt mit ihren Waffen als Beweis Eurer Taten zu mir zurück.", progress = nil, completion = "Nie wieder wird die Brennende Legion die Orcs oder ein anderes Volk der Horde versklaven! Ihr habt tapfer gekämpft, &lt;Klasse&gt;!\n\nDas wahre Herz der Horde schlägt in Euch! Ihr bringt uns sehr viel Ehre!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand von ArgasSiegel von ArgasSignet von Argas\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9537] = {title = "Keine Gnade mit dem Gnom", objective = "Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr die Mitteilung des Verräters von Ingenieur \"Funks\" Oberschleif an Euch bringt.", description = "Wir müssen uns Funks vornehmen!\n\nGeht zum Strand und sucht nach diesem betrügerischen Gnom. Quetscht so viele Informationen wie möglich aus ihm heraus!\n\nWer weiß, wie viele andere ebenfalls ein faules Spiel treiben, wenn schon ein hochrangiger Beamter der Allianz solch verräterische Taten begangen hat?\n\nUnd <Name>, wendet Gewalt an, wenn es nicht anders geht...", progress = "Habt Ihr den elenden Lügner gefunden?", completion = "Unglaublich! Das gehörte alles zu ihrem perfiden Plan!\n\nIhr müsst diese Informationen dem König und Euren eigenen Anführern zukommen lassen. Die Folgen sind erschütternd.", rewards = "Klinge des SeefahrersAschebäschas FleischklopferDer PanzerknackerArmbrust des AlbatrosDer LehrstockIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9538] = {title = "Erlernen der Sprache", objective = "Lest die Übersetzungsfibel der Tannenruhfeste, die Aurren Euch gegeben hat. Kommuniziert anschließend mit dem Totem von Akida bei der Azurwacht.", description = "Ich glaube, ich hab's, <Name>!\n\n<Aurren zeigt auf das Totem.>\n\nAlles, was wir über die Sprache der Furbolgs der Tannenruhfeste wissen müssen, ist auf ihren Totems verzeichnet. Wenn wir den grundlegenden Aufbau der Symbole verstehen, können wir die Totems studieren und somit lernen, mit den Furbolgs zu kommunizieren.\n\nIch habe das Grundmuster der Symbole auf dieses Pergament gezeichnet. Studiert es und untersucht dann das Totem. Es sollte Euch zu dem nächsten Sprachtotem führen.\n\nSprecht mit Arugoo, wenn Ihr als gelehrter <Volk> zurückkehrt!", progress = "Ihr könnt ein dunkles Brummen hören, das von dem Totem ausgeht.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort A-K-I-D-A formen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9539] = {title = "Totem von Coo", objective = "Findet das Totem von Coo, indem Ihr den Hinweisen folgt.", description = "Ihr beginnt das Totem zu entschlüsseln, die komplizierten Begriffe lassen sich kaum aussprechen. Langsam formen sich Worte in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Geht auf dem nahegelegenen Hügel nach oben, Richtung Nordosten.", progress = nil, completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort C-O-O formen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9540] = {title = "Totem von Tikti", objective = "Findet das Totem von Tikti, indem Ihr den Hinweisen folgt.", description = "Ihr beginnt das Totem zu entschlüsseln, die Begriffe lassen sich bereits etwas leichter aussprechen. Worte formen sich in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Überquert den Kristallfluss Richtung Osten. Vielleicht liegt Euer Ziel ja auf der anderen Uferseite des Flusses.", progress = nil, completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort T-I-K-T-I formen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9541] = {title = "Totem von Yor", objective = "Findet das Totem von Yor, indem Ihr den Hinweisen folgt.", description = "Die Symbole des Totems scheinen sich viel schneller entschlüsseln zu lassen. Die Begriffe ergeben rasch einen Sinn. Ihr seid ziemlich sicher, dass das Totem Euch auf etwas den Fluss herab im Süden verweist. Etwas muss auf dem Grund des Flusses selbst liegen.", progress = nil, completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort Y-O-R formen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9542] = {title = "Totem von Vark", objective = "Findet das Totem von Vark, indem Ihr den Hinweisen folgt.", description = "Die Symbole auf dem Totem lassen sich jetzt ganz einfach lesen. Es ist, als wäre die Beschriftung auf dem Totem von Yor in Eurer Muttersprache verfasst worden.\n\nDie Hinweise deuten auf einen anderen Furbolgbau im Westen hin. Ihr entschlüsselt meisterhaft die Sprache auf dem Totem und wisst, dass Euer Ziel das Dorf der Sichelklauen ist. Yor wird Euch dorthin führen, falls Ihr Euch dennoch verlaufen solltet, wisst Ihr, dass Ihr die alte Elfenstraße im Wald nehmen könnt, die Richtung Westen zu Eurem Ziel führt.", progress = nil, completion = "Beim Lesen des Totems formen Eure Lippen das Wort V-A-R-K. Ihr versteht die Bedeutung, sie lautet Gerechtigkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9543] = {title = "Sühne", objective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.", description = "Unsere Vergangenheit mit den Orcs ist gezeichnet von andauernden Konflikten, <Name>. Einst hätten sie uns im Blutrausch beinahe vollständig ausgelöscht und selbst als der dämonische Einfluss von ihnen wich, haben wir uns weiter von den Orcs fern gehalten.\n\nTrotz dieser Vergangenheit... das Letzte, was Sedai gewollt hätte, wäre Rache und Blutvergießen. Sprecht mit unserem Ältesten, Amaan dem Weisen. Ihm wird es gelingen, Licht in diese Ereignisse zu bringen.", progress = nil, completion = "Wie kann ich Euch behilflich sein, &lt;Name&gt;? Ihr klingt, als hättet Ihr Sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9544] = {title = "Die Prophezeiung von Akida", objective = "Befreit 8 gefangene Furbolgs der Tannenruhfeste aus den Käfigen im Dorf der Sichelklauen. Kehrt anschließend zu Arugoo der Tannenruhfeste bei der Azurwacht zurück.", description = "Die Abbildungen auf dem Totem stellen einen Krieg zwischen dem Furbolgstamm der Tannenruhfeste und dem der Sichelklauen dar. Die Motive zeigen Gräueltaten, die die Sichelklauen den Furbolgs der Tannenruhfeste angetan haben.\n\nInmitten des Chaos wird eine Prophezeiung offenbart: Ein Held wird kommen - in seinen Adern fließt kein Furbolgblut - er wird den Stamm der Tannenruhfeste erretten.\n\nTötet die Furbolgs der Sichelklauen im Dorf der Sichelklauen für ihre Schlüssel. Verwendet diese Schlüssel, um gefangene Furbolgs der Tannenruhfeste zu befreien. Sobald Ihr alle befreit habt, kehrt zu Arugoo der Tannenruhfeste zurück.", progress = nil, completion = "[Furbolg] Die Prophezeiung sprach von jemandem, der sich erheben und uns aus dem gewaltsamen Griff der Sichelklauen befreien würde; dass die Geister selbst die Ankunft dieses Helden verkünden würden.\n\nJetzt seid Ihr gekommen.\n\nIch beuge mich vor Euch in Demut, Großartiger.", rewards = "Abwehr der TannenruhfesteArugoos Armbrust der ZerstörungStachel der TannenruhfesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9545] = {title = "Das Relikt des Sehers", objective = "Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr Sedais Leichnam erneut aufsucht, um dort das Relikt des Sehers zu benutzen. Kehrt nach Abschluss der Aufgabe zu ihm zurück.", description = "Die Störrischen unter uns verschließen ihren Geist und glauben an die eine Wahrheit. Der Weise jedoch, hat ein offenes Ohr für die Existenz unterschiedlicher Möglichkeiten, die letztlich zur Gegenwart führen, oder von ihr ausgehen.\n\nBringt dieses Relikt zu dem Ort, an dem Ihr Sedai gefunden habt. Seht nicht mit Euren Augen, <Name>, sondern mit Eurem Verstand.", progress = "Habt Ihr eine Vision gehabt, <Name>?", completion = "Tief in meinem Innersten hoffe ich, dass Eure Vision Euch neue Einblicke auf die Ereignisse, die zu Sedais Tod geführt haben, gewährt hat. Das Relikt zeigte Euch eine mögliche Reihe von Ereignissen, die zur Gegenwart führten. Die Wahrheit mag irgendwo dazwischen liegen, doch wir werden es nie mit Sicherheit erfahren.\n\nHättet Ihr mit Eurem jetzigen Wissen anders gehandelt?\n\nWer kann schon sagen, ob unser Konflikt mit den Orcs ewig währen wird? Doch am wichtigsten ist es, immer für alle Möglichkeiten offen zu sein.", rewards = "Kettenhelm des VerteidigersGamaschen von TelhamatWeste der OmenaiIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9546] = {title = "Einlösung eines Versprechens", objective = "Arugoo der Tannenruhfeste hat Euch gebeten, 8 gefangene Furbolgs der Tannenruhfeste aus Käfigen im Dorf der Sichelklauen zu befreien.", description = "Die Prophezeiung sprach von jemanden, der sich erheben würde und uns aus dem eisernen Griff der Sichelklauen befreien würde - die Geister selbst sollten das Erscheinen dieses Helden ankündigen.\n\nJetzt seid Ihr gekommen.\n\nIch verbeuge mich in Demut vor Euch, oh Einzigartiger. Ich flehe Euch an, rettet unsere Jüngsten. Sie wurden von den Sichelklauen entführt, nachdem man unsere Verteidigung lahmgelegt hat. Ihr findet sie in Käfigen im Dorf der Sichelklauen im Südwesten. Die Furbolgs der Sichelklauen tragen die Schlüssel für die Käfige bei sich. Streckt sie nieder und entwendet die Schlüssel. Befreit meinesgleichen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Panzergürtel des SilberwaldsArmschienen aus abgeworfenem FellNeu gewebte HoseIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9547] = {title = "Ruf der Luft", objective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.<Name>, Weissager Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Name>, Weissager Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9548] = {title = "Gestohlene Ausrüstung", objective = "Bringt Kloppers Ausrüstung zurück zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.", description = "Schhh! Sprecht leise und lenkt keine Aufmerksamkeit auf mich.\n\nWenn die Murlocs meiner Anwesenheit gewahr werden, ist es mit dem Experiment vorbei! Ich war schon sehr nahe daran, meine Arbeit zu gefährden.\n\nAls ich gestern am Herumkramen war, muss einer von ihnen zu nahe gekommen sein und mein Lager entdeckt haben. Ich kam noch rechtzeitig, um zwei von ihnen eine meiner Ausrüstungskisten fortschleppen zu sehen! Sie muss in einer ihrer Siedlungen hier zu finden sein, aber ich kann es nicht riskieren, meine Deckung aufzugeben. Wollt Ihr mir vielleicht helfen?", progress = "Konntet Ihr meine Ausrüstung finden?", completion = "Das ist fantastisch! Der Diebstahl meiner Ausrüstung hat mir zu noch mehr Einsicht in das Verhalten der Murlocs verholfen, als ich womöglich mittels wochenlanger Beobachtungen hätte gewinnen können!\n\nIch weiß schon, was ich in meinen Bericht schreiben werde.\n\n'Beim Aufeinandertreffen mit Erzeugnissen einer technologisch höher gestellten Kultur, zeigten die Murlocs der Schwarzschlammküste nicht die sonst typische Neugier wie humanoide Entwicklungskulturen.'\n\nDas ist großartig! Die Herren in Eisenschmiede werden es lieben! Ich kann Euch nicht genug danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9549] = {title = "Schwarzschlammartefakte", objective = "Bringt 3 kunstlose Murlocgötzen und 6 kunstlose Murlocmesser zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.", description = "Meine Beobachtungen und Aufzeichnungen über die Murlocs der Schwarzschlammküste sind recht aufschlussreich, <Name>, aber ich habe gerade erst damit angefangen. Ich habe vor, mit Gegenständen, die auf primitivste Weise von den Murlocs der Schwarzschlammküste hergestellt wurden, nach Eisenschmiede zurückzukehren.\n\nDas Problem ist allerdings, dass die Murlocs diese Gegenstände stets bei sich tragen. Ich könnte es nicht ertragen, wenn meine Hände mit ihrem Blut befleckt wären. Wollt Ihr mir vielleicht dabei helfen, Götzen von den Sehern der Schwarzschlammküste und kunstlosen Messer von den Kriegern und Küstenschlägern der Schwarzschlammküste einzusammeln? Ich werde Euch auch nicht fragen, wie Ihr sie Euch beschafft habt.", progress = "Habt Ihr die Gegenstände, die ich nach Eisenschmiede bringen möchte?", completion = "Verblüffend, einfach verblüffend! Diese Stücke sind perfekt, &lt;Name&gt;. Ich kann sie mir bereits unter Glas im Museum von Eisenschmiede vorstellen. Der Text für die Vitrine schreibt sich in meinem Kopf gewissermaßen von selbst!\n\nEure Hilfe war für den Fortgang meiner Studien von unschätzbarem Wert. Wie schreibt sich Euer Name doch gleich? Ich werde dafür sorgen, dass Ihr in meinem Bericht als Mitautor auftaucht.\n\nEiner der Burschen auf dem Schiff gab mir diese 'Schatzkarte', um seine Spielschulden bei mir zu begleichen, allerdings ist Mythologie keines meiner Fachgebiete. Abergläubiges Pack, diese Seefahrer.", rewards = "Ihr bekommt:\n\nVerwitterte Schatzkarte"}
MultiLanguageQuestData['de'][9550] = {title = "Wohin führt die Karte?", objective = "Macht den auf der Karte beschriebenen Pavillon ausfindig und sucht, auf was der Verfasser der Karte hinweisen wollte.", description = "Die nicht gerade sorgfältig gezeichnete Karte verrät zwar nichts über ihren Verfasser, scheint aber mit zittrigen Händen angefertigt worden zu sein. Krakelige Linien und Symbole beschreiben einen kleinen Pavillon mit eingestürzten Säulen. Er befindet sich im Westen eines Turms, der teilweise unter Wasser steht.\n\nGlaubt man der Karte, so liegen diese Ruinen an der östlichen Küste der Insel. Es ist Euch ein Rätsel, was Ihr dort vorfinden werdet, es scheint für die Erstellung dieser Karte jedoch wichtig genug gewesen zu sein.", progress = "Vielleicht bezieht sich die Karte ja auf dieses alte Tagebuch.", completion = "Nachdem Ihr Euch das Buch sorgfältig angesehen habt, kommt Ihr zu dem Schluss, dass es sich um ein Tagebuch handelt. Die Eintragungen auf den Seiten weisen eine elegante Handschrift auf, die sich von der auf der Karte unterscheidet. Zahlreiche Texte sind durch hinzugefügte Beschriftungen und Zeichnungen im Stil der Karte unleserlich geworden.\n\nDurch das Geschreibsel des Kartenverfassers, in dem er von Trinkgelagen während des Landgangs faselt, sind die eigentlichen Eintragungen fast nicht mehr auszumachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9551] = {title = "Ruf der Luft", objective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", description = "<Name>, Scharfseher Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.", progress = nil, completion = "Schließlich kommen wir zu dem letzten der vier großen Elemente, der Luft. Glaubt Ihr weise genug zu sein, um fortzufahren, &lt;Name&gt;?", rewards = nil}
MultiLanguageQuestData['de'][9552] = {title = "Ruf der Luft", objective = "Sprecht mit Velaada beim Wildwindgipfel auf der Azurmythosinsel.", description = "Der mächtige Geist der Luft verlangt nach Euch, <Name>, es ist an der Zeit, diesem Ruf zu folgen.\n\nIch möchte, dass Ihr den Wildwindpfad im Norden hinaufwandert, dem Berg zugewandt, an dem die Exodar zerschellt ist. Auf seinem Gipfel werdet Ihr eine Höhle finden und darin eine meiner am besten ausgebildeten Schülerinnen, Velaada.\n\nBitte, hört auf ihre Weisheit und befolgt ihren Rat. Wenn Ihr zurückkehrt, werdet Ihr ein größeres Verständnis für das Element der Luft haben.", progress = nil, completion = "Der Wind hat mir Euer Kommen zugeflüstert, &lt;Klasse&gt;.\n\nWeissager Nobundo achtet Euch sehr - ich auch, nachdem ich von Euren Taten gehört habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9553] = {title = "Ruf der Luft", objective = "Sprecht mit Susurrus beim Wildwindgipfel auf der Azurmythosinsel.", description = "Die Luft scheint flüchtig zu sein, sie ist jedoch eine alles bedeckende und durchdringende Kraft, die uns umgibt.\n\nAuch wenn Ihr sie nicht sehen könnt, so bestehen die Felsen dieser Höhle doch hauptsächlich aus Luft, das Wasser der Ozeane ist mit ihr gesättigt und ohne sie könnte kein Feuer bestehen. Lasst dies die Elemente niemals hören!\n\nDerjenige, den ihr wegen dieses Wissens wirklich zu sprechen wünscht, ist ganz in der Nähe. Am nördlichen Ende der Felsklippe erwartet Euch Susurrus. Mit seiner Hilfe werdet Ihr verstehen lernen.", progress = nil, completion = "Ich habe Eure Ankunft erwartet, &lt;Klasse&gt;. Ihr sucht nach Weisheit und etwas anderem, das spüre ich.\n\nAlso gut, lasst uns beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9554] = {title = "Ruf der Luft", objective = "Kehrt mit dem Luftwirbel zu Scharfseher Nobundo bei der Exodar auf der Azurmythosinsel zurück.", description = "Während meine Brüder und Schwestern der anderen Elemente die Erfüllung verschiedenster Aufgaben von Euch verlangten, werde ich keine weiteren Anforderungen an Euch stellen. Ich glaube, dass Ihr genug geleistet habt, um für eine 'Wiedergutmachung' für den Unfall, den der Absturz Eures Schiffs verursacht hat, zu sorgen. Ich kann sehen, dass Ihr bereits über die Erfahrenheit verfügt, die Ihr für einen weisen Umgang mit dem Element der Luft benötigt.\n\nNehmt diesen Teil meiner Selbst zurück zu Scharfseher Nobundo, damit er Euch bei der Erstellung Eures Totems helfen kann. Sobald Ihr bereit seid, werde ich Euch zurück zur Exodar fliegen.", progress = "Schon zurück? Euer Haar sieht zerzaust aus.\n\n<Nobundo grinst wissend.>", completion = "Ich bin stolz auf Euch, &lt;Name&gt;. Ihr habt dort durchgehalten, wo andere aufgegeben haben. Während all dem habt Ihr ein größeres Verständnis für die Elemente und Euch selbst gewonnen. Denkt immer an das, was Ihr gelernt habt, und Ihr werdet im Leben von diesen Weisheiten profitieren.\n\nGebt mir jetzt bitte den Luftwirbel von Susurrus, damit ich ihn in Euer Lufttotem einbinden kann. Wie die anderen Totems auch, wird es Euch als Fokus und Erinnerung an Eure Bindung mit den Elementen dienen.", rewards = "Ihr bekommt:\n\nLufttotem"}
MultiLanguageQuestData['de'][9555] = {title = "Ruf des Feuers", objective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar.", description = "Es freut mich, dass Ihr den schwierigen Pfad des Schamanen gewählt habt. Nur wenige entscheiden sich für diesen Weg, aber ich spüre, dass es für unsere Zukunft von großer Bedeutung sein wird, die Macht des Schamanismus von den Zerschlagenen zu erlernen.\n\nMan nennt sie so, aber einst waren auch sie Draenei. Teuflische Magie hat sie verwandelt und deshalb können sie sich nicht auf die Macht des Lichts berufen. Einige missbilligen sie und den Schamanismus, den sie lehren, aber sie sind nicht bösartig.\n\nIch möchte, dass Ihr mit Scharfseher Nobundo sprecht. Er ist der weiseste Schamane, den ich kenne, er wird Euch viel beibringen können.", progress = nil, completion = "Seid gegrüßt. Es ist stets ermutigend, einen &lt;Volk&gt; zu treffen, der sich dem Weg des Schamanismus eröffnet. Es gibt leider nur wenige.\n\nIhr habt nun gelernt, das Feuer nicht nach seinem Äußeren zu beurteilen, genauso, wie Ihr mein Äußeres nicht beurteilen solltet.\n\nIhr seid hier, weil Ihr bereit seid, Euer Feuertotem zu erschaffen.", rewards = "Ihr erlernt:\n\nTotem der Verbrennung\n\nIhr bekommt außerdem:\n\nFeuertotem"}
MultiLanguageQuestData['de'][9556] = {title = "Dem Sieger...", objective = "Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Sturmwind oder in Unterstadt, falls Eure Seite in den östlichen Pestländern erfolgreich war.", description = "Ihr habt zweifellos lange und hart um die Verteidigung der Türme gekämpft, <Volk>. Wir würden Euch gerne etwas im Gegenzug für Euren tapferen Einsatz geben, allerdings müsst Ihr uns zuerst beweisen, dass Ihr die Gewichtigkeit dieser hier stattgefundenen Tragödien auch versteht.\n\nLauft durch Stratholme und sucht nach einer Phiole mit dem heiligen Wasser. Sobald Ihr sie gefunden habt, reist zum Magierviertel in Sturmwind oder nach Unterstadt... Dort werdet Ihr, insofern Ihr in diesen Landen siegreich wart, auf meinen Kollegen treffen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9557] = {title = "Entziffern des Buchs", objective = "Bringt das alte Tagebuch zu Anachoret Paetheus bei der Blutwacht.", description = "Da Ihr über keinerlei Mittel verfügt, die es Euch ermöglichen würden, den Inhalt des Buchs zu entschlüsseln, versucht Ihr Euch jemanden ins Gedächtnis zu rufen, der Euch dabei helfen könnte, die ursprünglichen Eintragungen zwischen dem Gekritzel des Kartenverfassers herauszulesen.\n\nIhr erinnert Euch an Anachoret Paetheus' Sammlung verschiedenster Artefakte, die die Draenei während ihrer Reisen entdeckten. Vielleicht können Euch ja seine erfahrenen Augen bei der Entzifferung des Buchs weiterhelfen.", progress = "Möge das Licht bei all Euren Bemühungen mit Euch sein, <Klasse>. Was habt Ihr da?", completion = "Hmm... das ist äußerst faszinierend. Ja, ich sollte in der Lage sein, die eigentlichen Einträge des Schreibers in diesem Buch entziffern zu können.\n\nIch verfüge über die benötigten Mittel hier. Es sollte nur einen Augenblick dauern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9558] = {title = "Die Langbarts", objective = "Sucht nach Gremni Langbart nordwestlich des Haal'eshbaus, weit im Westen der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Vor nicht allzu langer Zeit hatten wir einige Probleme mit Arakkoabanditen. Sie haben viele unserer Versorgungskarawanen überfallen, weswegen ich ein paar Zwerge angeheuert habe, die sich um sie kümmern sollten.\n\nEs waren Brüder, wobei Gremni Langbart der Älteste von ihnen war. Sie sind losgezogen und nie zurückgekehrt.\n\nIch mache mir ein wenig Sorgen um sie, versteht Ihr? Diese verrückten Zwerge haben mehr Bier als Essen oder Munition eingepackt! Könntet Ihr vielleicht einmal nach ihnen sehen?\n\nDas Versteck der Arakkoa, der Haal'eshbau, befindet sich von hier aus weit im Westen, hinter der großen Kluft. Sie haben nordwestlich von dort ein Lager aufgeschlagen, im Süden der Staubstachelschlucht.", progress = nil, completion = "Wie habt Ihr uns gefunden, &lt;Klasse&gt;? Egal, Ihr seid sicher hier, um uns zu helfen. Dann mal an die Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9559] = {title = "Tannenruhfeste", objective = "Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.", description = "Auserwählter, Ihr müsst nach Norden zur Heimstätte meiner Leute reisen - zur Tannenruhfeste. Dort werdet Ihr auf Eure schrecklichste Herausforderung treffen.\n\nGeht jetzt, der Oberhäuptling der Tannenruhfeste erwartet Euch.", progress = nil, completion = "Jahrhunderte lang lebten wir in verhältnismäßigem Frieden mit den Kreaturen des Landes. Vor einigen Monaten begann Kurz, dunkle Vorzeichen zu sehen. Der Frieden, den wir so lange genossen hatten, schien in Gefahr. Keiner konnte die Ausmaße dieser Katastrophe erahnen!\n\nUnd so kam es, dass die Götter unser Land straften und sowohl Feinde als auch Freunde gegen uns richteten. Aber es gab da noch etwas... inmitten des Chaos sollte sich ein Held erheben: ein Held, in dessen Adern nicht das Blut der Tannenruh fließt. Der Auserwählte würde uns vor der Zerstörung erretten.\n\nDer prophezeite Held wart Ihr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9560] = {title = "Biester aus der Apokalypse!", objective = "Moordo bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr ihm 8 Felshetzerbälge bringt.", description = "Mein Bruder und ich waren im östlich gelegenen Wald beim Jagen, als wir von seltsamen, insektenartigen Biestern angegriffen wurden. Solch fremdartige Geschöpfe hatten wir zuvor noch nie auf der Azurmythosinsel gesehen! Könnten es die Vorboten der angekündigten Apokalypse sein? Der Weltuntergang, den IHR verhindern sollt?\n\nSolltet Ihr wirklich der auserwählte Held sein, so werdet Ihr die Biester der Apokalypse bezwingen... und mir ihre Bälge bringen. Ich kann Euch aus diesem Material eine mächtige Rüstung anfertigen!\n\nSucht Richtung Osten nach ihnen, abseits der Straße.", progress = "Es sind hässliche kleine Kreaturen. Sogar der blinde Behüter könnte sie sehen... und er ist blind.", completion = "Nicht nur, dass die Prophezeiung wahr ist, nein, diese Rüstung ist ebenso erstaunlich! Eine Rüstung für einen Helden! Ich werde sie Euch für einen besonders günstigen Preis verkaufen, Fellloser.\n\nDas war ein Scherz... das erste Teil gibt's umsonst.", rewards = "Tunika aus FelshetzerchitinGamaschen aus FelshetzerbalgDicker FelshetzergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9561] = {title = "Nolkais Worte", objective = "Findet den in Nolkais Tagebuch beschriebenen Ort und sucht nach seinen seit langem vergrabenen Besitztümern.", description = "Ich bin mit der Entschlüsselung jetzt fertig, <Name>.\n\n<Anachoret Paetheus zeigt auf einen Textabschnitt am Ende seiner Abschrift.>\n\n'Der Feind ist ganz nah. Wir haben alle Überlebenden zusammengerufen und uns mit ihnen zu dem östlich gelegenen Tempel geflüchtet. Es ist der letzte Ort auf dieser Insel, den wir noch halten können. Unter den Überlebenden hat sich der Glaube verbreitet, dass dies unsere endgültige Zuflucht sein wird. Ich habe Vorkehrungen getroffen und meine verbliebene Habe im Boden des Tempels vergraben. Ich hoffe, dass sie jemand finden und somit erfahren wird, was hier geschehen ist.'", progress = nil, completion = "Gras und Gestrüpp bedecken eine unnatürliche Wölbung am Boden.\n\nNach nur kurzem Graben entdeckt Ihr einen alten Kasten. Es muss sich dabei um den, der in Nolkais Tagebuch beschrieben ist, handeln.", rewards = "Ihr bekommt:\n\nNolkais Kasten"}
MultiLanguageQuestData['de'][9562] = {title = "Murlocs... Warum hier? Warum jetzt?", objective = "Gurf bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr 5 Säcke mit Tannenruhgetreide wiedererlangt.", description = "Es herrschen dunkle Zeiten, <Auserwählter/Auserwählte>. Sogar die Murlocs trampeln uns auf den Füßen herum - im wahrsten Sinne des Wortes. Unglücklicherweise wurde nicht nur mein Stolz verletzt.\n\nUnser Verhältnis zu den Schlickflossenmurlocs war zwar schon immer recht bescheiden, jedoch hätten wir uns niemals vorstellen können, dass sie uns angreifen und von unseren Essensvorräten stehlen würden! Reist Richtung Westen zur Schlickerküste und bringt uns unsere gestohlenen Vorräte wieder!\n\nUnd solltet Ihr einen dunkelhäutigen Murloc mit einem Stück weißen Fell zwischen den Schwimmhäuten sehen...", progress = "Ein Murloc hat mir in den Hintern getreten und mich angespuckt... und das am helllichten Tag!", completion = "Mmmmm... köstliches Getreide... Parkat wird sich freuen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9563] = {title = "Mirrens Vertrauen erlangen", objective = "Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 1 Nethergarde Bitter bringt. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Ehrenfeste.", description = "Ihr wollt also unser Vertrauen erlangen? In diesen Zeiten vertraue ich nicht vielen Leuten.\n\nVor kurzer Zeit haben wir einen der unseren an die Arakkoa verloren. Das hat mich etwas nervös gemacht.\n\nIch sag' Euch was, wenn Ihr Eure Loyalität gegenüber der Ehrenfeste beweisen könnt und... mir einen Krug Nethergarde Bitter bringt... ja, das klingt so weit ganz gut... dann biete ich Euch einen Handel an.\n\nBernie in der Burg Nethergarde hat das Bitter auf Lager.", progress = "Probleme, das Bitter zu finden? Der gute alte Bernie in der Burg Nethergarde sollte Fässer davon auf Lager haben.\n\nEs sei denn, seine Vorräte sind ausgegangen... das wäre fatal!", completion = "Oh ja! Ihr scheint ganz in Ordnung zu sein, &lt;Volk&gt;. Ich denke, ich kann Euch vertrauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9564] = {title = "Gurfs Würde", objective = "Bringt Gurfs Würde zu Gurf bei der Tannenruhfeste auf der Azurmythosinsel.", description = "Nehmt dem Murloc das Stück Fell, das Gurf bei seiner Auseinandersetzung mit den Biestern \"verloren\" hat, ab und bringt es anschließend zu Gurf zurück. Lasst ihn sogleich wissen, dass der entsetzliche Murgurgula vernichtet wurde.", progress = "Ist das etwa das, was ich vermute?", completion = "&lt;Gurf spuckt auf den Fellfetzen und versucht ihn auf die kahle Stelle auf seinem Hintern anzubringen.&gt;\n\nDas muss vorerst halten! Ich hoffe, dass einer der Schamanen den Schaden wieder beheben kann.", rewards = "Fellbesetzte RobeWilde GamaschenSchwere KettengamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9565] = {title = "Sucht in der Tannenruhfeste", objective = "Sucht in der Tannenruhfeste nach Hinweisen.", description = "Als Oberhäuptling gilt meine erste Sorge der Ursache, die hinter der Verderbnis innerhalb der Tannenruhfeste steckt.\n\nWarum haben uns die Wildekin - einst unsere Verbündeten - angegriffen? Warum haben sie die Tannenruhfeste besetzt?\n\nVielleicht finden wir im Innern der Feste ja eine Antwort. Sucht in der Tannenruhfeste nach dem Quell der Verderbnis.", progress = nil, completion = "Der Blutkristall verstrahlt eine kränkliche Aura, die in das Wasser im Keller sickert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9566] = {title = "Blutkristalle", objective = "Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.", description = "Außerhalb des Wassers sieht der Kristall wie ein Teil der Exodar aus. Allerdings scheint mit diesem Kristall etwas nicht zu stimmen, denn er ist blutrot und löst sich sehr schnell im Wasser des Kellers auf.\n\nDas könnte das ungewöhnlich aggressive Verhalten der Kreaturen auf der Azurmythosinsel erklären. Kehrt mit diesen Informationen zum Oberhäuptling der Tannenruhfeste zurück.", progress = nil, completion = "Von den Blutkristallen, wie Ihr sie gesehen habt, wurden von meinen Spähern noch viele weitere im Norden gesichtet.\n\nIch danke Euch für die Hilfe, muss Euch nun aber bitten zu gehen, weil ich mich noch mit den Ältesten beraten muss. Ich werde nach Euch rufen lassen, sobald ich mit den anderen Ältesten des Dorfes gesprochen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9567] = {title = "Kenne deinen Feind", objective = "Findet das Monument der Nazzivus in Nazzivian und beschafft Euch eine Glyphe vom Monument der Nazzivus. Kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück, sobald Ihr die Glyphe habt.", description = "Es tut gut, neue Gesichter hier bei der Blutwacht zu sehen, <Klasse>. Die Blutelfen stellen zwar die derzeit größte Bedrohung für uns dar, jedoch gibt es noch andere finstere Kreaturen, die die Blutmythosinsel zu ihrem Zuhause gemacht haben.\n\nDie Satyrn der Nazzivus beunruhigen uns besonders. Es sind üble, dämonische Kreaturen, die dunkle Magien beherrschen und sich an der Verderbnis nähren, die der Absturz der Exodar verursacht hat.\n\nWir müssen sie in Schach halten, aber bevor wir handeln, gilt es noch etwas mehr über sie in Erfahrung zu bringen. Geht nach Nazzivian im Westen und versucht so viel wie möglich von ihrem grotesken Monument zu lernen.", progress = "Habt Ihr schon etwas Wissenswertes von den Satyrn der Nazzivus erlangt?", completion = "Gut gemacht, &lt;Name&gt;. Mal sehen, was ich von dieser Glyphe in Erfahrung bringen kann. Dann können wir unseren nächsten Schritt planen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9568] = {title = "In der Offensive", objective = "Verteidigerin Aalesia bei der Blutwacht möchte, dass Ihr 10 Satyrn der Nazzivus, 5 Schurken der Nazzivus und 5 Teufelsanbeter der Nazzivus tötet.", description = "Es ist schlimmer, als ich dachte, <Name>. Wir Draenei wissen nur zu gut, was passiert, wenn man seine Seele an die Brennende Legion im Austausch für das Versprechen von Macht und Unsterblichkeit verkauft.\n\nDie Satyrn auf dieser Insel, die Nazzivus, sind Abkömmlinge der ersten abartigen Kreatur, die sich mit der Legion verbündet hatte. Ich fürchte, dass sie einen Weg finden werden, um die Kraft der Kristalle von der Exodar gegen uns zu verwenden.\n\nIhr habt gesehen, was sie diesem Land angetan haben. Stellt Euch nur vor, was sie in den Händen der Satyrn anrichten könnten. Geht Richtung Südwesten nach Nazzivian und startet unsere Offensive!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9569] = {title = "Die Bedrohung bekämpfen", objective = "Tötet 5 Schattenpirscher von Axxarien, 5 Höllenrufer von Axxarien und Zevrax. Sammelt außerdem 5 verderbte Kristalle ein und kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück.", description = "Jetzt, da wir bei den Satyrn Eindruck hinterlassen haben, müssen wir ihnen zu verstehen geben, dass wir Übeltäter der Brennenden Legion hier nicht dulden.\n\nDie Draenei sind schon viel zu lange im Schatten der Legion und ihrer Diener geflohen, <Name>. Wo immer sie uns auch fanden, sie zeigten niemals Gnade.\n\nWir dürfen es nicht zulassen, dass die Satyrn den Absturz der Exodar ausnutzen und die verderbten Kristalle als Waffe einsetzen. Geht nach Axxarien im Norden, dem Sitz ihres Anführers. Tötet ihn und nehmt die verderbten Kristalle, die er angesammelt hat, an Euch!", progress = "<Verteidigerin Aalesia scheint eher durch Euch hindurch, als Euch anzusehen, sie ist voll und ganz mit den Satyrn beschäftigt.>\n\nSeid Ihr schon gegen den Anführer der Satyrn vorgegangen?", completion = "Ohne ihren Anführer und die entwendeten Kristalle können wir die Satyrn bedenkenlos in Schach halten. Nur das Licht weiß, wie viele dieser erbärmlichen Kreaturen da draußen noch lauern.\n\nHerold Mikolaas und ich sind Euch für Eure Hilfe sehr dankbar. Ihr habt uns geholfen, eine noch größere Bedrohung durch die Satyrn abzuwenden. Euer Einsatz wird alle daran erinnern, dass Wachsamkeit der Schlüssel zum Erfolg ist, wenn es darum geht, gegen die Legion und ihre Diener vorzugehen.", rewards = "Armbrust des JägersmannsLichtfunkeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9570] = {title = "Kurken lauert", objective = "Kurz der Weise bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Kurken tötet und dass Ihr ihm Kurkens Balg bringt.", description = "Nachdem der Kristallsturm nachgelassen hatte, erschien eine mythische Bestie in unserem Dorf. Das Untier, Kurken, das von den einfallenden Wildekin hierher gebracht wurde, legte alles in Trümmer. Zahlreiche Furbolgs der Tannenruhfeste wurden bei der Verteidigung unseres Landes von der Bestie getötet. Beim Versuch, das Untier zu bezwingen, ließen viele weitere ihr Leben.\n\nIn meinen Visionen sah ich jemanden, der Kurken besiegte. Diese Person müsst Ihr sein, <Name>. Es kann nur einen geben. Betretet die Tannenruhfeste und tötet Kurken. Bringt mir seinen Balg als Beweis für Eure Tat.", progress = "<Kurz schnaubt Euch an.>", completion = "Der Held ist erfolgreich zurückgekehrt!\n\nDie Prophezeiung hat sich fast vollständig bewahrheitet. Jetzt zu dem Balg...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9571] = {title = "Kurkens Balg", objective = "Bringt Kurkens Balg zu Moordo bei der Tannenruhfeste.", description = "Bringt Kurkens Balg zu Moordo, auf der anderen Seite des Dorfes. Er wird daraus ein Rüstungsteil Eurer Wahl anfertigen.", progress = "Hallo, Held!", completion = "Das ist die stärkste Rüstung, die ich jemals angefertigt habe! Nutzt sie weise, &lt;Name&gt;.", rewards = "Wams aus Kurkens BalgKurkenstocksIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9572] = {title = "Die Bollwerke schwächen", objective = "Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Schnell, wir haben nicht viel Zeit. Thrallmars Existenz steht auf Messers Schneide!\n\nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!\n\nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Caza'rez gegenüber von mir!", progress = "<Name>, richtig? Stok'ton hat mir gesagt, dass ich auf Euren Bericht warten soll.\n\nBringt Ihr gute Nachrichten?", completion = "Das ist ein guter Anfang. Ohne diese drei sollten die Truppen verwirrt sein. Und solange ihre Artillerie außer Gefecht ist, haben wir bessere Chancen, näher vorzurücken, um die Zitadelle einzunehmen.\n\nAber es gehört mehr dazu, als man glaubt, ich fühle es. Deswegen habe ich einen weiteren Auftrag für Euch.\n\nFürs Erste jedoch habt Ihr Eure Arbeit gut gemacht. Sucht euch etwas aus Thrallmars Waffenkammer aus.", rewards = "Jadeschulterstücke des KriegersHandschützer der PräzisionStiefel des sicheren SchrittsMantelung der MagiemachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9573] = {title = "Häuptling Oomooroo", objective = "Der Jüngling Tannenruh bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Häuptling Oomooroo und 9 wahnsinnige Wildekin tötet.", description = "Ich bin der Jüngling Tannenruh, Erbe des Vermächtnisses von Tannenruh. Wie Ihr sehen könnt, haben meine Verteidiger eine Todesfalle für die irren Wildekin aufgestellt, die von der Tannenruhfeste aus angreifen. Wir können sie zwar hier draußen abwehren, allerdings hat es noch keiner meiner Verteidiger geschafft, in die Feste vorzudringen. Wenn es Euch gelingen sollte, dort hinein zu gelangen und ihren Anführer zu töten, würde uns das vielleicht eine Gelegenheit zum Angriff verschaffen!\n\nFindet Häuptling Oomooroo und vernichtet ihn. Tötet auch alle wahnsinnigen Wildekin, die Euch im Innern der Feste in die Quere kommen.", progress = nil, completion = "Das könnte die Gelegenheit sein, auf die wir so lange gewartet haben! Ich werde sofort angreifen lassen! Der Stamm der Tannenruhfeste dankt Euch für Euren Einsatz, &lt;Name&gt;!", rewards = "Verstärkte HandgelenksschützerStabiler LedergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9574] = {title = "Opfer der Verderbnis", objective = "Bringt 6 Stücke kristallisierte Rinde zu Morae bei der Blutwacht.", description = "Unsere Ankunft hat die Blutmythosinsel für alle Zeit verändert. Der Absturz der Exodar hat Trümmer über die gesamte Insel verstreut und ich glaube, dass sich dies langsam negativ auf die Natur hier auswirkt.\n\nIch muss mir alles erst genauer ansehen, bevor ich meine Schlussfolgerung bestätigen kann. Die Kristalle scheinen die Bäume als erstes beeinträchtigt zu haben, also müssten die Treants am ehesten die Symptome aufweisen. Wenn Ihr mir Proben von der Rinde verderbter Treants bringen würdet, könnte ich mich weiter in meine Studien vertiefen.", progress = "Konntet Ihr die Proben bekommen, die ich benötige?", completion = "Ich habe jetzt mehr als genug für meine Untersuchungen. Ich danke Euch, &lt;Name&gt;. Solltet Ihr noch etwas anderes auftreiben können, das beweist, dass die Kristalle die einheimischen Kreaturen der Blutmythosinsel beeinträchtigen, so lasst es mich sofort wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9575] = {title = "Die Bollwerke schwächen", objective = "Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Schnell, wir haben nicht viel Zeit. Die Existenz der Ehrenfeste steht auf Messers Schneide!\n\nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!\n\nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Gunny gegenüber von mir!", progress = "<Name>, richtig? Chadwick hat mir gesagt, dass ich auf Euren Bericht warten soll.\n\nWAS macht Ihr hier?! Habt Ihr Eure Aufgabe erledigt? Seid Ihr denn ein kompletter Vollidiot? Ich könnte mich übergeben!\n\nJetzt schwingt Euren nutzlosen Hintern zu diesem Bollwerk und tut, was Euch aufgetragen wurde! Habt Ihr mich gehört?!", completion = "Wisst Ihr, was ich noch mehr hasse, als mich zu irren? Gold bei einer Wette zu verlieren, dass Ihr es nicht schafft, Schätzchen.\n\nAusgezeichnet! Ohne diese drei sollten die Truppen verwirrt sein. Und solange ihre Artillerie außer Gefecht ist, haben wir bessere Chancen, näher vorzurücken, um die Zitadelle einzunehmen.\n\nIch habe jedoch das Gefühl, dass da noch mehr dahinter steckt. Deswegen habe ich einen weiteren Auftrag für Euch. Hier, sucht Euch etwas aus der Waffenkammer aus!", rewards = "Jadeschulterstücke des KriegersHandschützer der PräzisionStiefel des sicheren SchrittsMantelung der MagiemachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9576] = {title = "Schandflosses Anhänger", objective = "Bringt den roten Kristallanhänger zu Morae bei der Blutwacht.", description = "Ihr untersucht den sehr simpel angefertigten Anhänger und stellt fest, dass der Kristall ganz sachte pulsiert. Er leuchtet ein wenig, aber Ihr spürt auch, dass irgendetwas Unnatürliches davon ausgeht.\n\nIhr seid Euch zwar nicht sicher, was Schandflosse zur Anfertigung dieses Anhängers getrieben hat, aber der Fund scheint zu wichtig, als dass er ignoriert werden könnte. Ihr solltet ihn jemandem bei der Blutwacht zeigen.", progress = "Was habt Ihr da bei Euch?", completion = "Das ist äußerst verwunderlich, &lt;Klasse&gt;. Ich glaube nicht, dass wir jemals einen Murloc gesehen haben, der Schmuck trägt.\n\nBetrachtet man den verderblichen Einfluss, den die Kristallsplitter ganz offensichtlich haben, so muss der Murloc, der diesen Anhänger getragen hat, davon überzeugt gewesen sein, dass er ihm eine Art Macht über seine Artgenossen verleihen würde. Es würde mich nicht verwundern, wenn er in kürzester Zeit stärker als seine Murlocgefährten geworden ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9577] = {title = "DAILY TEST QUEST (PVP)", objective = "Sprecht mit <QUESTGIVER> in <AREA>.Sucht<QUESTGIVER> in <LOCATION>. Sie/Er hat eine schwierige Aufgabe für Euch.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Sucht<QUESTGIVER> in <LOCATION>. Sie/Er hat eine schwierige Aufgabe für Euch.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9578] = {title = "Suche nach Galaen", objective = "Sucht nach Moraes Mann Galaen.", description = "Denkt Ihr oft an Eure Familie, <Name>? An Bord der Exodar befanden sich einige Familien, aber ich habe nur von sehr wenigen gehört, die sich nach dem Absturz wiedergefunden haben.\n\nIch suche zum Beispiel nach Spuren von meinem Mann, Galaen. Er war Techniker im Kryokern. Die Trümmer davon wurden im Westen gefunden, allerdings wimmelt es dort nur so von Blutelfen!\n\nIch muss wissen, was Galaen zugestoßen ist! Selbst die Nachricht von seinem Tod wäre noch besser als diese Ungewissheit. Mein Mann trägt den gleichen Anhänger wie ich; sie waren ein Geschenk meiner Schwester.", progress = nil, completion = "Der Leichnam trägt die für einen Techniker der Exodar übliche Kleidung, aber der von Morae beschriebene Anhänger fehlt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9579] = {title = "Galaens Schicksal", objective = "Bringt Galaens Amulett zu Morae bei der Blutwacht.", description = "Die Informationen von Morae ermöglichen es Euch nicht, den Leichnam eindeutig als den von Galaen zu identifizieren, allerdings scheint man die Kleidung bei der Suche nach Kostbarkeiten zerrissen zu haben.\n\nDie Blutelfen der Umgebung hätten bei den Wrackteilen jeglichen Gegenstand von Wert an sich genommen, einschließlich das mit Juwelen besetzte Amulett von Galaen.\n\nAuch wenn Moraes Mann den Absturz nicht überlebt hat, so wird sie mit Sicherheit dankbar sein, wenn Ihr das Amulett von den Blutelfen wiedererlangt.", progress = "<Morae sieht Euch voller Hoffnung an.>\n\nSeid Ihr bei Eurer Suche auf Spuren von Galaen gestoßen?", completion = "&lt;Ihr berichtet Morae von Eurem Fund in den Trümmern des Kryokerns.&gt;\n\nAlso... er ist...\n\nIch denke, dass ich es bereits wusste, wollte es aber einfach nicht glauben. Es sind zwar nicht die Neuigkeiten, die ich mir erhofft hatte, aber ich bin Euch für das Auffinden von Galaen zutiefst dankbar.", rewards = "Stiefel des KryokernaufsehersStiefel des TechnikersLeichte MaschenstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9580] = {title = "Bärdarfsgüter", objective = "Bringt 8 Flanken eines alten Braunbären zu Fährtenleser Lyceon bei der Blutwacht.", description = "Seit Ihr auf der Blutmythosinsel seid, habt Ihr sicherlich nur wenig gesehen, dass sich nicht auf Grund unserer Ankunft verändert hat. Meine Ausbildung und Erfahrung haben mich gelehrt, dass sogar die Erzeugnisse einer derartigen Umgebung noch von Nutzen sein können.\n\nMit so wenigen Ressourcen müssen wir uns auf unseren Einfallsreichtum verlassen, um versorgt zu sein. Ich habe unsere Läden mit Fleisch ausgestattet, das von Bären stammt, die auf dieser Insel umherstreifen. Wenn man es richtig zubereitet, kann es bedenkenlos verzehrt werden. Solltet Ihr da draußen unterwegs sein, so helft uns doch bitte unsere Vorräte aufzufüllen.", progress = "Wie verläuft Eure Jagd, <Name>?", completion = "Mit diesen Vorräten werden wir fürs Erste versorgt sein und die Zubereitung für den späteren Verzehr wird mich sicherlich ein Weilchen beschäftigen. Ich danke Euch für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9581] = {title = "Von den Kristallen lernen", objective = "Benutzt die Kristallspitzhacke, um eine Kristallprobe der Absturzstelle von einem Kristall der Absturzstelle zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", description = "Willkommen bei der Blutwacht, <Klasse>. Meine hauptsächliche Sorge gilt der Verteidigung des Außenpostens, aber unsere Anführer bei der Exodar haben mir auch zahlreiche andere Pflichten überantwortet.\n\nDas Problem ist nur, dass es eigentlich zu unsicher ist, eine große Anzahl von Forschern auszusenden, wenn die Insel so gefährlich ist. Ich brauche jemanden, der für mich eine Reihe von Kristallproben von verschiedenen Stellen der Insel einsammelt.\n\nDie erste Probe muss von den von Felshetzern besetzten Schiffstrümmern kommen, die südlich des Dorfs und auf der anderen Seite der Brücke liegen.", progress = "Konntet Ihr die erste Kristallprobe bekommen?", completion = "Dieser Kristallsplitter wird unseren Forschern als Vergleichsgrundlage für Proben von anderen Teilen der Insel dienen, da er aus einem weniger verseuchten Gebiet der Blutmythosinsel stammt.\n\nIch werde die Probe erst losschicken können, wenn ich ein vollständiges Probenset habe, aber der Anfang ist getan. Wenn Ihr mir helfen möchtet, die anderen Proben einzusammeln, werde ich Euch für Eure Mühe natürlich belohnen.", rewards = "Kristallgesprenkelte HoseSplitterbedeckte GamaschenKristallbesetzte BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9582] = {title = "Die Stärke des Einen", objective = "Öffnet den Felshetzerkäfig und tötet den darin befindlichen Todesfelshetzer. Kehrt dann zu Ruada in der Azurwacht auf der Azurmythosinsel zurück.", description = "Als das Schiff abstürzte, wurde unsere Menagerie an den nordöstlichen Stränden dieser Insel zerstreut. Mir wurde ein Schlüssel für den Käfig eines besonders gefährlichen Exemplars anvertraut, dem Todesfelshetzer. Die Kreatur ist zwar nur leicht gepanzert, widersteht aber fast jeglicher Magie. Man muss sie mit der einfachen Kraft des Schwerts erlegen.\n\nNehmt diesen Schlüssel und befreit den Felshetzer aus seinem Gefängnis und von seiner Qual. Wir können es nicht zulassen, dass er aus dem Käfig ausbricht und der Umwelt hier noch weiteren Schaden zufügt.", progress = "Habt Ihr das Biest bezwungen?", completion = "&lt;Ruada nickt ernst.&gt;\n\nSo sei es denn.\n\nIhr seid nun bereit für Eure nächste Lektion, &lt;Name&gt;, aber Ihr werdet sie nicht von mir erhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9583] = {title = "Omar's Test Quest", objective = "Bringt Omar Stoff.", description = "Eine ehrbare Person gibt mir Stoff.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEroberungspunkte"}
MultiLanguageQuestData['de'][9584] = {title = "Die zweite Probe", objective = "Benutzt die Kristallspitzhacke, um eine Veränderte Kristallprobe von einem veränderten Blutmythoskristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", description = "Da wir nun einen Kristall als Vergleichsgrundlage haben, benötigen wir jetzt Proben von gefährlicheren Gegenden der Insel, um das Set zu vervollständigen, das ich zur Exodar senden möchte.\n\nDie nächste Probe muss von den Kristallen kommen, die von den Blutelfen in der Umgebung des Messerwinkels, nordwestlich der Blutwacht, kontrolliert werden. Berichten zufolge verändern und ernten sie die Kristalle, um sie in einer Art magischer Apparatur zu verwenden. Versucht einen Kristall zu finden, der noch nicht in eines dieser Geräte eingebaut wurde, und entnehmt eine Probe davon.", progress = "Habt Ihr die zweite Kristallprobe?", completion = "&lt;Herold Mikolaas untersucht den Kristallsplitter.&gt;\n\nDieser Splitter unterscheidet sich stark von der ersten Probe.\n\n&lt;Herold Mikolaas hält den Kristall ins Licht.&gt;\n\nSeht Ihr, wie das Licht darin pulsiert? Das ist bedenklich. Ich werde in meinem Bericht vermerken, dass die Blutelfen diesen Kristall verändert zu haben scheinen. Ich danke Euch für Eure erneute Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9585] = {title = "Die letzte Probe", objective = "Benutzt die Kristallspitzhacke, um eine Axxarienkristallprobe von einem Axxarienkristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", description = "Ich benötige nur noch eine letzte Probe, bevor ich das Set mit den Kristallen zur Exodar schicken kann, <Name>. Die letzte Probe muss von der Feste der Satyrn im Nordwesten, Axxarien, kommen.\n\nIch weiß nicht genau, was mir diese Probe aufzeigen wird, aber ich bin mir sicher, dass sie Spuren der Verderbnis enthalten wird. Achtet darauf, dass Ihr eine Probe von den Kristallen entnehmt, die wie die aussehen, von denen Ihr zuvor Proben entnommen habt, ansonsten können unsere Forscher keine korrekten Vergleiche mehr anstellen.", progress = "Habt Ihr die letzte Probe für mein Set?", completion = "&lt;Herold Mikolaas nimmt den letzten Kristall von Euch entgegen.&gt;\n\nDamit ist das Set vollständig. Ich muss nur noch alles verpacken und zur Exodar senden.\n\n&lt;Der Herold scheint erleichtert, dass die Sache erledigt ist.&gt;\n\nVersteht mich nicht falsch, &lt;Name&gt;, ich bin mir sicher, dass die Forschungsarbeit wertvoll ist, aber wir haben es hier draußen noch mit zahlreichen anderen Problemen zu tun, die dringend sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9586] = {title = "Helft Tavara", objective = "Guvan bei der Azurwacht möchte, dass Ihr Tavara findet und ihre Wunden heilt.", description = "Tavara, eine unserer Kräuterkundigen, ist bei ihrer Suche nach Kräutern viel zu weit gegangen. Ich befürchte sie wurde verletzt und braucht Hilfe, aber unglücklicherweise kann ich mich nicht selbst auf die Suche nach ihr begeben.\n\nBitte findet und heilt sie, wenn nötig, <Klasse>. Sie verließ die Azurwacht in Richtung Osten und machte sich auf den Weg zu einigen heißen Quellen.", progress = nil, completion = "Danke, dass Ihr Tavara geholfen habt. Die meisten anderen sind mit dem Land hier nicht vertraut und geraten dort in Schwierigkeiten, wo sie es am wenigsten erwarten.\n\nEs wäre eine Ehre für mich, wenn Ihr diese Roben tragen würdet. Sie zeichnen Euch als Beschützer der Azurwacht und als gläubigen Anhänger des Lichts aus.", rewards = "Ihr bekommt:\n\nRoben der Azurwacht"}
MultiLanguageQuestData['de'][9587] = {title = "Düstere Neuigkeiten", objective = "Bringt den unheilvollen Brief zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles \"I\" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.\n\nSicherlich würde Truppenkommandant Danath Trollbann in der Ehrenfeste gerne einen Blick auf den Brief werfen.", progress = "Was habt Ihr denn da, mein Sohn?", completion = "Unterzeichnet von Illidan, sagt Ihr?! Gebt mir das mal.\n\n&lt;Der Kommandant liest den Brief, liest ihn erneut und denkt einen Moment nach, bevor er fortfährt.&gt;\n\nDie von Euch überbrachten Neuigkeiten sind ohne Zweifel unheilvoll. Wir müssen unsere Vorhaben gegen die Höllenfeuerzitadelle und diesen Blutkessel unbedingt beschleunigen. Da Ihr bewiesen habt, dass Ihr mit dieser Aufgabe fertigwerden könnt, möchte ich, dass Ihr diese Pläne umsetzt.\n\nGunny wird Euch Euren nächsten Auftrag erteilen, allerdings wird dieser wohl wesentlich tödlicher als Euer erster sein.\n\nMöge das Licht mit Euch sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9588] = {title = "Düstere Neuigkeiten", objective = "Bringt den unheilvollen Brief zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles \"I\" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.\n\nSicherlich würde Nazgrel in Thrallmar gerne einen Blick auf den Brief werfen!", progress = "Was ist das für ein Brief, den Ihr da bei Euch tragt, <Klasse>?", completion = "Unterzeichnet von Illidan, sagt Ihr?! Gebt mir das mal.\n\n&lt;Nazgrel liest den Brief, liest ihn erneut und denkt einen Moment nach, bevor er fortfährt.&gt;\n\nDie von Euch überbrachten Neuigkeiten sind ohne Zweifel unheilvoll. Wir müssen unsere Vorhaben gegen die Höllenfeuerzitadelle und diesen Blutkessel unbedingt beschleunigen. Da Ihr bewiesen habt, dass Ihr mit dieser Aufgabe fertigwerden könnt, möchte ich, dass Ihr diese Pläne umsetzt.\n\nZenturio Caza'rez wird Euch Euren nächsten Auftrag erteilen, allerdings wird dieser wohl wesentlich tödlicher als Euer erster sein.\n\nLok'tar Ogar, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9589] = {title = "Blut bedeutet Leben", objective = "Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Ich bin mir sicher, dass dieser Brief hier für einigen Aufruhr sorgen wird. Wir glauben, etwas gegen die Erschaffung immer neuer Höllenorcs unternehmen zu können, wenn wir nur mehr über ihren Entstehungsprozess in Erfahrung bringen. Es ist schon schlimm genug, dass wir im Osten gegen die Brennende Legion kämpfen müssen.\n\nHeute ist also Euer Glückstag, <mein Bester/meine Beste>! Ihr bekommt die Chance auf einen Spaziergang im Blutkessel, wie manche den Innenhof der Höllenfeuerzitadelle nennen. Klingt verdammt heiß!\n\nZieht los, tötet ein paar Höllenorcs und bringt Proben ihres Blutes mit zurück.\n\nFühlt Ihr Euch der Aufgabe gewachsen?", progress = "Habt Ihr das Blut Herzchen? Wird wohl ziemlich wichtig sein, wenn wir Euch darum gebeten haben, versteht Ihr?", completion = "Ist ja schon beinahe beängstigend! Von diesem Moment an, Gefreiter &lt;Name&gt;, seid Ihr mein absoluter Liebling auf diesen erbärmlichen Überresten dieses erbärmlichen Planeten!\n\nIch bin mir fast sicher, dass die verdammten Eierköpfe sich vor Freude fast in die Hose machen werden, wenn ich ihnen das Blut für ihre Forschungen überlasse. Wer weiß, vielleicht finden wir ja eine neue Waffe im Kampf gegen diese verdammten Höllenorcs.", rewards = "Brustplatte der VergeltungSchuppenbeinlinge der ZerstörungMondkinkopfputzGamaschen des TodestunnlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9590] = {title = "Blut bedeutet Leben", objective = "Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Zenturio Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Dieser Brief beunruhigt mich zutiefst, und das nicht nur, weil er vom Verräter persönlich verfasst wurde. Wenn wir sie besiegen wollen, ist es von größter Wichtigkeit, herauszufinden, wie sie diese neuen Höllenorcs erschaffen! Schlimm genug, dass wir die Brennende Legion bei unserer östlichen Flanke bekämpfen müssen, jetzt auch noch eine Höllenorcarmee im Westen!\n\nEs liegt jetzt an Euch, den so genannten Blutkessel im Inneren der Höllenfeuerzitadelle zu infiltrieren. Bringt einige Blutproben von den dortigen Höllenorcs mit.", progress = "Seid Ihr sicher, dass Ihr ausreichend Blut gesammelt habt?", completion = "Eure Fähigkeiten haben mich sehr beeindruckt, &lt;Name&gt;. Nicht einmal, sondern gleich zweimal habt Ihr die Höllenfeuerzitadelle für uns infiltriert und alles getan, was wir Euch aufgetragen hatten.\n\nIch werde mich persönlich darum kümmern, dass dieses Blut in die Hände fähiger Forscher gelangt. Wer weiß, vielleicht können wir den Prozess ja sogar umkehren?", rewards = "Brustplatte der VergeltungSchuppenbeinlinge der ZerstörungMondkinkopfputzGamaschen des TodestunnlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9591] = {title = "Die Zähmung der Bestie", objective = "Benutzt das Zähmertotem, um einen Stachelkriecher zu bändigen. Kehrt nach gelungenem Unterfangen zu Jägerin Kella Nachtbogen zurück.", description = "Das Erste und Einzige, was <ein/eine:c> <Klasse> am Anfang lernt, ist das Töten. Ihr scheint nun für den nächsten Schritt bereit zu sein.\n\nDie Furbolgs der Tannenruhfeste haben uns beigebracht, wie man Wildtiere zähmt, ohne monatelang zu studieren. Sie können ein Totem in der Gestalt eines Tiers formen, was sie für kurze Zeit mit einer Kreatur dieser Art verbindet.\n\nLektion Nummer Eins: Ihr nehmt dieses Totem und wendet es auf einen Stachelkriecher an. Ihr findet dergleichen an der westlichen Küste der Insel.", progress = "Konntet Ihr Euch die Magie des Totems zu Nutze machen und einen Stachelkriecher zähmen? Angriffslustige, kleine Biester!", completion = "Ihr habt mit Sicherheit gemerkt, wie unangenehm der Kriecher während des Zähmungsversuchs war. Bis zu dem Augenblick, in dem sie verstanden haben, dass Ihr sie nicht in einen Kochtopf werfen wollt, sehen sie in Euch einfach nur einen Feind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9592] = {title = "Die Zähmung der Bestie", objective = "Benutzt das Zähmertotem, um einen großen Grünschreiter zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.", description = "Der Kriecher war zweifellos widerborstig, aber der Grünschreiter wird Eure Beharrlichkeit mit Sicherheit auf eine noch härtere Probe stellen. Stärkere Verbündete benötigen mehr Entschlossenheit.\n\nNehmt dieses Zähmertotem und bändigt damit einen großen Grünschreiter. Ihr findet diese Kreaturen im Norden der Azurmythosinsel.", progress = "Der Grünschreiter ist ein mächtiger Vogel. Er wird oft von Jägern unterschätzt, was schreckliche Folgen haben kann.", completion = "Na, hat der Grünschreiter Euch also nicht die Augen ausgepickt.\n\n&lt;Kella sieht für einen Moment weg.&gt;\n\nNatürlich habe ich das auch nicht vermutet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9593] = {title = "Die Zähmung der Bestie", objective = "Benutzt das Zähmertotem, um einen Nachtpirscher zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.", description = "Während der Zähmung des Grünschreiters sind Euch sicherlich die großen Katzen, die man Nachtpirscher nennt, aufgefallen. Es sind rasche und tödliche Jäger... und Verbündete.\n\nNehmt dieses Zähmertotem und bändigt damit einen Nachtpirscher. Geht mit dem Nachtpirscher auf die Jagd und schützt ihn vor Angreifern. Kehrt anschließend zu mir zurück.", progress = "Der Nachtpirscher ist im Grunde genommen eine große Katze mit messerscharfen Klauen und einem großen Appetit auf Fleisch...", completion = "Ich muss sagen, &lt;Name&gt;, Ihr habt weitaus schneller gelernt, als ich zuerst habe glauben wollen. Es sieht so aus, als würden wir das letzte Zähmertotem nicht benötigen. Ehrlich gesagt, ich weiß nicht einmal genau, was es ist. Eine Art Echse mit Flügeln und einem langen Schwanz. Ach, naja, vielleicht ein andermal.\n\nEs ist an der Zeit, dass Ihr eine wilde Kreatur auch ohne die Hilfe eines Totems zähmen könnt. Viel Glück!", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9594] = {title = "Zeichen der Legion", objective = "Tötet 8 Satyrn der Nazzivus und 8 Teufelsanbeter der Nazzivus. Bringt anschließend Tzeraks Panzerplatte zu Verteidigerin Aalesia bei der Blutwacht.", description = "Das Rüstungsstück wurde aus einem tiefschwarzen Metall geschmiedet, das Licht zu absorbieren scheint. Es wirkt zwar nicht verzaubert, allerdings kommt es Euch alles andere als normal vor.\n\nSolch eine Rüstung wird nur von einer bestimmten Macht verwendet - der Brennenden Legion. Die Gegenwart der Legion kann nur bedeuten, dass sie vorhaben, die Satyrn der Insel gegen die Draenei aufzuhetzen.\n\nGeht gegen die einheimischen Satyrn vor und zeigt dieses Rüstungsstück Verteidigerin Aalesia bei der Blutwacht.", progress = "Ja, <Klasse>? Was habt Ihr da?", completion = "Es war richtig, dass Ihr damit zu mir gekommen seid, &lt;Name&gt;. Es handelt sich hierbei zweifellos um ein Rüstungsstück einer Teufelswache.\n\nDann ist es also, wie ich es befürchtet hatte. Die Satyrn der Nazzivus nehmen erneut Verbindung zur Brennenden Legion auf. Wenn wir sie nicht aufhalten, werden uns die Satyrn und ihre dämonischen Verbündeten überrennen. Ich werde Herold Mikolaas sofort davon in Kenntnis setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9595] = {title = "Kontrolle", objective = "Vernichtet die Murlocs der Schlickerküste, um einen Magiergeist der Quel'dorei zu rufen, und vernichtet ihn. Sprecht dann mit Bati in der Halle des Lichts in der Exodar.", description = "Ihr habt Euch entschieden, als <Klasse> durchs Leben zu gehen, also müsst Ihr jetzt Kontrolle erlernen. Ungezügelte Magie ist fähig, Seelen zu verderben und Welten zu zerstören.\n\nUm all das noch besser verstehen zu können, müsst Ihr einem Wesen gegenüber treten, das der eigens ausgeübten Magie erlegen ist. Reist zu den Stränden an der nordwestlichen Küste der Azurmythosinsel und setzt Eure Magie ein, um ein paar üble Murlocs zu vernichten. Euer Magiegebrauch wird wahrscheinlich die böse Macht hervorlocken, die sich dort herumtreibt - ein Magiergeist der Quel'dorei. Vernichtet ihn.\n\nWenn Ihr fertig seid. macht Euch auf die Suche nach Bati in der Halle des Lichts der Exodar.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "LeystabAuf Euch wartet eine dieser Belohnungen:\n\nLeykugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9598] = {title = "Erlösung", objective = "Lest das Buch der Offenbarung und sprecht mit Jol.", description = "Ich bin dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und unser Volk vor den Bedrohungen verteidigen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", progress = "Willkommen zurück, <Name>.", completion = "Willkommen zurück, &lt;Name&gt;. Ich hoffe, Ihr habt die Zeit genutzt und das Buch gelesen.\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9600] = {title = "Erlösung", objective = "Jol möchte, dass Ihr einen jungen Schamanen der Furbolgs mit dem Symbol des Lebens wieder zum Leben erweckt und dass Ihr anschließend wieder zu ihr zurückkehrt.", description = "Es wird Eure Aufgabe sein, <Name>, unseren neuen Verbündeten, den Furbolgs der Tannenruhfeste, zu helfen.\n\nEinige der jüngeren Schamanen der Tannenruhfeste sind in ein Lager der Sichelklauen gestolpert und wurden allesamt getötet. Nehmt dieses Symbol des Lebens und erweckt einen der Schamanen wieder zum Leben.\n\nDie Enklave der Sichelklauen liegt östlich der Straße, direkt nachdem man die Brücke überquert, die die Azurmythosinsel und die Blutmythosinsel verbindet. Sprecht mit mir, wenn Ihr diese Aufgabe erfüllt habt.", progress = nil, completion = "Sorgt Euch nicht um die Verwirrung derer, denen Ihr geholfen habt. Es ist nicht ungewöhnlich, dass diejenigen, die erst kürzlich wieder in die Welt der Lebenden gebracht wurden, etwas desorientiert sind. Stellt Euch nur einmal den Schock vor, den sie bei der Begegnung mit seltsamen Wesen erlitten haben.\n\nDer junge Schamane ist gesegnet, da er diese harte Lektion dank Euch überlebt hat. Es ist mehr als angebracht, dass Ihr Euch dieser Macht von nun an jederzeit bedienen könnt.", rewards = "Ihr erlernt:\n\nErlösung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9601] = {title = "Zum Bollwerk", objective = "Sprecht mit Mehlar Dämmerklinge beim Bollwerk.", description = "Der Blutritter Mehlar Dämmerklinge hat ein Treffen mit Euch gefordert, <Name>. Ihr findet Mehlar beim Bollwerk, das den Übergang zwischen Tirisfal und den Westlichen Pestländern schützt.\n\nEr ist nicht gerade für seine Geduld bekannt. Ihr solltet ihn also nicht warten lassen.", progress = nil, completion = "Ahh... wie es scheint ist die zeit gekommen.\n\n&lt;Mehlar nickt wissend.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9602] = {title = "Unheilvolle Mitteilung", objective = "Bringt die Mitteilung des Verräters zu Exarch Menelaous bei der Azurwacht.", description = "Ihr müsst Euren Leuten diese Informationen überbringen, <Name>. Auch wenn Euer mutiger Einsatz die Pläne von Kael'thas und seinem dunklen Meister sicherlich ins Stocken gebracht hat, werden mit Sicherheit auch weiterhin Angriffe verübt werden.\n\nNehmt die Mitteilung des Verräters zu Euren Anführern. Sie müssen es mit ihren eigenen Augen sehen. Vielleicht verstehen sie einiges von dem Geschriebenen besser.", progress = "Ihr seid zurück!", completion = "&lt;Exarch Menelaous nimmt die Mitteilung von Euch entgegen und beginnt sie zu lesen.&gt;\n\nVerdammt... verdammt sie alle in den Nether. Sie hatten einen Spion, der sie über all unsere Aktivitäten informiert hat! Und seit wann?\n\nIch werde sofort Velen informieren!\n\nIhr habt uns einen großen Dienst erwiesen, &lt;Name&gt;. Haltet die Augen offen, ich werde mich an Euch wenden, sobald der Prophet mir mitgeteilt hat, was es zu tun gilt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9603] = {title = "Betten, Verbände und noch viel mehr", objective = "Bringt Chellans Liste zu Zaldaan, dem Hippogryphenmeister bei der Azurwacht.", description = "Willkommen bei der Azurwacht, <Klasse>. Bitte entschuldigt die Unordnung, die hier überall herrscht. Man betrachtet die einfachsten Dinge oft als selbstverständlich, wie zum Beispiel ein komplett eingerichtetes und ausgestattetes Gasthaus... bis man selbst ein neues aus dem Nichts errichten muss.\n\nWir konnten dieses Wrackteil bergen und für das Gebäude verwenden, allerdings ist dieses Gasthaus lediglich ein besseres Zelt, ohne die entsprechende Einrichtung und die Notvorräte. Nurguni bei der Exodar hat uns angeboten, ein paar Vorräte mit den im Moment am dringendsten benötigten Dingen zusammenzustellen. Ich brauche jedoch jemanden, der ihm diese Liste hier bringt.", progress = "Guten Tag, <Name>. Interessiert Ihr Euch für einen Hippogryphenflug?", completion = "Ihr müsst also zu der Exodar?\n\nDas ist ein ganz schön weiter Weg, aber keine Sorge, ich weiß schon, wie Ihr auf dem schnellsten Weg an Euer Ziel kommt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9604] = {title = "Auf dem Rücken eines Hippogryphen", objective = "Erwerbt bei Zaldaan einen Hippogryphenritt zur Exodar. Bringt Chellans Liste nach der Landung zu Nurguni im Sitz der Naaru der Exodar.", description = "Ihr könnt einen meiner Hippogryphen gegen ein kleines Entgelt mieten, um zur Exodar zu fliegen.\n\nEinen Hippogryphen zu nehmen, ist eine schnellere und, was noch wichtiger ist, sichere Reisemöglichkeit für jemanden, der eine wichtige Nachricht zu überbringen hat. Wenn Ihr Euch für einen Hippogryphenritt entschieden habt, sprecht einfach nochmal mit mir und ich kümmere mich um den Rest.", progress = "Seid gegrüßt, Freund. Ihr seht aus, als hättet Ihr einen langen Weg hinter Euch. Wie kann ich Euch helfen?", completion = "Ah, Ihr habt also Tophers Liste gebracht. Ausgezeichnet! Ich hatte gehofft, dass ich sie heute erhalten würde. Lasst mal sehen, was er braucht.\n\n&lt;Nurguni überfliegt die Liste und beginnt verschiedene Gegenstände in eine Kiste zu packen.&gt;\n\nDas sind fast alle Dinge, die er aufgelistet hat. Die Teile für die Betten sind einfach zu groß, um auf einem Hippogryphen transportiert werden zu können. Ich werde dafür sorgen, dass sie mit einem Wagen nachgeliefert werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9605] = {title = "Hippogryphenmeister Stephanos", objective = "Geht zu Stephanos am Sitz der Naaru in der Exodar und erwerbt einen Hippogryphenritt zurück zur Azurwacht.", description = "Hier ist die Kiste, <Name>. Es sollte genug sein, damit Chellan das Gasthaus fertigstellen und eröffnen kann. Richtet ihr bitte aus, dass sie bei steigendem Bedarf jederzeit weitere Vorräte anfordern kann. Die Azurwacht braucht unbedingt einen Ort, an dem Verwundete versorgt und Reisende empfangen werden können.\n\nSucht Stephanos auf, wenn Ihr zur Azurwacht zurück möchtet, er hält sich am Sitz der Naaru in der Exodar auf.", progress = "Wohin wollt Ihr, <Klasse>?", completion = "Ihr wollt also mit dieser Kiste zurück zur Blutwacht? Kein Problem, &lt;Klasse&gt;. Sagt einfach Bescheid, wenn's losgehen soll.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9606] = {title = "Zurück zu Versorgerin Chellan", objective = "Sprecht mit Stephanos und erwerbt einen Hippogryphenritt zurück zur Azurwacht. Bringt Nurgunis Vorräte nach Eurer Ankunft zu Versorgerin Chellan.", description = "Wenn ich mich recht erinnere, dann ist Zaldaan der Hippogryphenmeister bei der Azurwachtwacht. Falls Ihr schon einmal mit ihm gesprochen habt, könnt Ihr einen meiner Hippogryphen zurück zu ihm nehmen.\n\nIhr solltet Euch etwas Wichtiges merken: Hippogryphen werden stets so ausgebildet, dass sie zu ihrer Hauptstadt zurückfliegen, sie bringen Euch aber nur zu einem entlegenen Hippogryphenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nDa Ihr mit einem von Zaldaans Hippogryphen hier angekommen seid, könnt Ihr diese Route auch wieder zurück zur Azurwacht nehmen und die Vorräte bei der Versorgerin abliefern.", progress = "Willkommen zurück, <Name>. Konnte Nurguni Euch alle Vorräte mitgeben, die auf der Liste standen?", completion = "&lt;Ihr überreicht Topher die Kiste und erklärt ihm, dass Nurguni dafür sorgt, dass die größeren Gegenstände mit einem Wagen nachgeliefert werden.&gt;\n\nGroßartig! Ich werde jetzt endlich ein paar Lagerstätten und eine Versorgungsstation einrichten können. Hier wird man sich in Zukunft um Verwundete und mögliche weitere Überlebende kümmern können.\n\nIch weiß gar nicht, wie ich Euch für Eure Hilfe danken kann, &lt;Name&gt;. Die Anerkennung von mir und den Verteidigern der Blutwacht ist Euch sicher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9607] = {title = "Im Herzen des Hasses", objective = "Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "<Klasse>, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus! Und ich meine heute noch Prinzesschen!\n\nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt. Das sagt schon alles!\n\nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.\n\nGeht hinein, untersucht das gesamte Areal und meldet Euch dann beim Truppenkommandant!", progress = nil, completion = "SIE HABEN EINEN GRUBENLORD?!\n\n&lt;Der Truppenkommandant bemerkt die starrenden Gesichter der anderen und senkt seine Stimme.&gt;\n\nDas ist es. Sie müssen das Blut dieses Grubenlords verwenden, um neue Höllenorcs, die aus irgendeinem Grund nicht zur Brennenden Legion gehören, zu erschaffen. Und wenn sie das mit den braunen Mag'har können, schaffen sie das auch mit grünen! Bei all den Orcs, die durch das Dunkle Portal kommen, sind das alles andere als gute Nachrichten!\n\nWir müssen sie ins Herz ihrer Militärmacht treffen, und zwar bald!", rewards = "Perfekt ausbalanciertes CapeAuf Euch wartet eine dieser Belohnungen:\n\nPurpurroter Anhänger der KlarsichtHeiliges Band der Heilung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9608] = {title = "Im Herzen des Hasses", objective = "Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "<Klasse>, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus!\n\nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt, also muss es sehr wichtig sein.\n\nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.\n\nGeht hinein, untersucht das gesamte Areal und meldet Euch dann bei Nazgrel, Thralls Berater.", progress = nil, completion = "SIE HABEN EINEN GRUBENLORD?!\n\n&lt;Nazgrel bemerkt die starrenden Gesichter der anderen und senkt seine Stimme.&gt;\n\nDas ist es. Sie müssen das Blut dieses Grubenlords verwenden, um neue Höllenorcs, die aus irgendeinem Grund nicht zur Brennenden Legion gehören, zu erschaffen. Und wenn sie das mit den braunen Mag'har können, schaffen sie das auch mit uns!\n\nWir müssen sie ins Herz ihrer Militärmacht treffen, und zwar bald!", rewards = "Perfekt ausbalanciertes CapeAuf Euch wartet eine dieser Belohnungen:\n\nPurpurroter Anhänger der KlarsichtHeiliges Band der Heilung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9609] = {title = "Helft Behüter Biggs", objective = "Sucht Behüter Biggs in den Sümpfen des Elends.", description = "Magtoor hat mir gesagt, dass in der Nähe ein Behüter gestrandet ist. Offensichtlich wurde die Karawane, die er von Dunkelhain ab begleitet hat, von Verirrten angegriffen. Wie es aussieht ist er der einzige Überlebende.\n\nEr ist irgendwo im Süden. Bitte, <Klasse>, helft ihm.", progress = nil, completion = "Was? Ein Draenei vom sicheren Hafen hat Euch geschickt? Wie merkwürdig.\n\nNun, ich bin niemand, der Hilfe ablehnt. Vielen Dank, dass Ihr gekommen seid, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9610] = {title = "Tränenteich", objective = "Besorgt 5 Artefakte der Atal'ai und bringt sie zu Holaaru im Sicheren Hafen in den Sümpfen des Elends.", description = "Ich interessiere mich für die Geschichte von Azeroth und frage mich, ob Ihr mir helfen möchtet.\n\nIn der Nähe im Sumpf gibt es einen Platz von historischer Bedeutung, zu dem ich Euch gerne schicken möchte. Der Tränenteich liegt im Südosten. Man sagt, dass sich an seinem Ufer und in seinen Tiefen vergrabene Artefakte der Zivilisation der Atal'aitrolle befänden.\n\nAber seid vorsichtig, der Teich wird von Somnus, einem uralten grünen Drachen, und seinen Drachlingen sowie fleischfressenden Fischen bewacht!", progress = "Ich freue mich schon darauf, die Artefakte, die Ihr sammeln werdet, zu untersuchen. Ich möchte herausfinden, was mit der einst so großartigen Zivilisation geschehen ist.", completion = "Ich danke Euch, &lt;Klasse&gt;. Ich werde eine ganze Weile mit der Untersuchung dieser Artefakte beschäftigt sein. Wie sonst können wir Zerschlagenen und Draenei uns einfügen, wenn wir nichts von der Geschichte unserer Welt kennen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9612] = {title = "Herzlichen Dank!", objective = "Sprecht mit Exarch Menelaous bei der Azurwacht.", description = "Ihr habt mein Leben gerettet, <Name>! Ich danke Euch von ganzem Herzen! Wärt Ihr nicht gewesen, hätte mich diese Bestie in Fetzen gerissen.\n\nWenn Ihr den Exarch bei der Azurwacht seht, erzählt ihm von Eurer Tat. Ich bin mir sicher, dass er diese Neuigkeit mit Freuden aufnehmen wird!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wirklich sehr, sehr gut! Ihr erweist Euch langsam als besonderer &lt;Volk&gt; - Ihr seid den anderen Euren Alters einen Schritt voraus. Nehmt dies als Belohnung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9616] = {title = "Banditen!", objective = "Nehmt das Blutelfendokument zu Exarch Menelaous bei der Azurwacht.", description = "Es scheint sich um ein Kopfgeldverzeichnis zu handeln. Ihr könnt die Sprache der Blutelfen zwar nicht verstehen, aber Ihr bemerkt ein Bild, das einen toten Draenei darstellt, einen grinsenden Blutelfen, der sich über dessen Körper beugt, und ein Symbol, das Eurer Meinung nach für eine Art Währung der Blutelfen steht.\n\nSie haben es auf die Draenei abgesehen! Ihr müsst den Exarch darüber informieren.", progress = "Ja? Ich bin wirklich sehr beschäftigt, <Name>.", completion = "Beim bartlosen, quadratischen Schädel von O'ros! Gut, dass Ihr das zu mir gebracht habt, &lt;Name&gt;. Diese Blutelfen haben es... nun ja, auf Blut abgesehen. Velen wird davon sofort in Kenntnis gesetzt werden! Nehmt dies als Anerkennung.", rewards = "Kampferprobte StulpenKampferprobte HandschuheKampferprobte HandschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9617] = {title = "Sucht die Weltenwanderer auf", objective = "Sprecht mit Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.", description = "Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer hat nach einer Audienz mit allen fähigen Jägern verlangt. Es würde Euch zugutekommen, wenn Ihr sie aufsuchen würdet, <Name>. Sie ist ein Stern der Erleuchtung für unsereins.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.", progress = nil, completion = "&lt;Name&gt;, es ist gut, dass Ihr gekommen seid. Unsere Liste mit Verbündeten schrumpft immer mehr. Selbst denjenigen, die die gleichen Ziele verfolgen, kann man nicht wirklich trauen. Daher wenden wir Waldläufer uns der Natur für Hilfe zu.\n\nDie Verbündeten des Waldes kennen keinen Verrat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9618] = {title = "Überbringen der Berichte", objective = "Bringt Keltus Dunkellaubs Berichte zu Zelanis in Silbermond.", description = "Eure Geschicklichkeit war äußerst beeindruckend. Es besteht kein Zweifel, ich kann Euch die Überbringung dieser Berichte an Zelanis anvertrauen.", progress = "Konntet Ihr Keltus ausfindig machen?", completion = "All diese Berichte sind von Keltus? Er hatte jede Menge zu tun, so viel steht fest.\n\nKariel ist ein Schurke unter den Schurken - er hält sich nur selten genau an Anweisungen und reißt gewisse Dinge oft an sich! Denkt jetzt nichts Falsches, er ist einer meiner verlässlichsten Spione und ohne ihn, wären wir arm dran.\n\nIhr habt heute eine beispielhafte Leistung vollbracht. Bitte nehmt diese Klinge und führt sie in den Rücken unserer Feinde.", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"}
MultiLanguageQuestData['de'][9619] = {title = "Beschwörungsrune", objective = "Verwendet den Leerstein, um einen Leerwandler in Goldnebel zu beschwören. Bezwingt ihn und kehrt zu Talionia in Silbermond zurück.", description = "Der Leerstein offenbart Euch eine Vision von einem mehrstöckigen Gebäude, das von geisterhaften Figuren behaust wird. Die Szene wird schärfer und verschwimmt dann wieder, andere Gebäude kommen ins Bild, es scheint sich um den Ort Goldnebel zu handeln.\n\nHausdächer und Baumwipfel schwirren plötzlich vorbei, sie verraten Euch den Weg nach Goldnebel, der den Elrendar entlang nach Westen führt.\n\nVerwendet den Leerstein, sobald Ihr dort angekommen seid, nahe der Beschwörungsrune auf dem Hauptgebäude und bezwingt den heraufbeschworenen Leerwandler. Erst dann könnt Ihr zu Eurem Lehrer zurückkehren.", progress = "Seid Ihr dem vom Leerstein aufgezeigten Weg gefolgt?", completion = "Ich bin beeindruckt, dass Ihr hier seid, &lt;Name&gt;. Viele Lehrlinge sind am Leerwandler gescheitert, oder sogar schon am Leerstein selbst.\n\nDer Leerwandler steht nun unter Eurem Befehl. Setzt Euren neuen Begleiter weise ein.", rewards = "Ihr erlernt:\n\nLeerwandler beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Leerwandler beschwören' lehren\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9620] = {title = "Das vermisste Vermessungsteam", objective = "Herold Mikolaas möchte, dass Ihr das Vermessungsteam findet, das er zu den Ruinen von Loreth'Aran entsendet hatte, und dass Ihr dem Team so gut es geht zur Seite steht.", description = "Als wir uns hier bei der Blutwacht langsam eingerichtet hatten, schickte ich Vermessungsteams aus, die zuverlässigere Karten der Insel erstellen sollten. Meistens kamen sie wieder unversehrt mit den von uns benötigten Angaben zurück, aber das Team, das ich nach Osten zu den Ruinen entsendet hatte, wird noch immer vermisst.\n\nIch mache mir Sorgen um sie, aber leider kann ich niemanden entbehren, um ein weiteres Team nach ihnen suchen zu lassen. Findet sie, <Name>, und helft ihnen soweit es geht, damit sie mit ihren gesammelten Informationen wieder zurückkehren können.", progress = nil, completion = "Auf dem Boden liegen überall die Körper der &lt;Volk&gt;, die dem Vermessungsteam angehörten - von Waffen der Naga durchbohrt. Ihr seht die verstreuten Überreste ihrer Vorräte und Vermessungsausrüstung, aber ihre Datenkristalle befinden sich nicht darunter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9621] = {title = "Gesandter zur Horde", objective = "Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.", description = "Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?\n\nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.\n\nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, <Name>. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.", progress = "Ah, ein Besucher aus Quel'Thalas! Welche Neuigkeiten bringt Ihr?", completion = "Dann ist es also geschehen. Der gemeine Verräter hat bekommen, was er verdient hat.\n\nIhr habt das selbst getan? Eine beeindruckende Tat, die beweist, dass Euer Volk immer noch würdig ist, &lt;Name&gt;.\n\nWie ich sehe hat Lor'themar weitere Nachrichten, die seine Beziehungen zu Thrall deutlich verbessern werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9622] = {title = "Warnt vor der Gefahr", objective = "Sprecht mit Exarch Menelaous bei der Azurwacht.", description = "Die Feste ist jetzt wieder sicher und schon bald werden sich meine Leute auf den Weg zurück zu ihrem Ahnenstammsitz machen. Die Prophezeiung wurde Wirklichkeit und für die Furbolgs der Tannenruhfeste beginnt eine neue Ära des Wohlstands.\n\nIch befürchte allerdings, dass die Dunkelheit für Eure eigenen Leute eine Bedrohung darstellt. Es gibt noch immer unbeantwortete Fragen - ungesehene Visionen aus der Prophezeiung.\n\nKehrt zu Euren Anführern zurück und erzählt ihnen von all dem, was Ihr hier erlebt habt.\n\nSolltet Ihr jemals die Hilfe der Tannenruhfeste benötigen, lasst es uns einfach wissen.", progress = nil, completion = "Visionen sagt Ihr? Interessant... und diese Prophezeiung hat sich also bewahrheitet?\n\nIhr sagt jedoch, dass man den Kraftkern der Exodar gesehen hat? O'ros erschien auch in der Vision? Was kann das nur bedeuten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9623] = {title = "Reifer werden", objective = "Exarch Menelaous bei der Azurwacht hat Euch gebeten, die Befehle des Exarchen zu Torallius dem Herdentreiber, der außerhalb der Exodar steht, zu bringen.", description = "Ihr habt in der Wildnis unserer neuen Heimat überlebt und Euch als etwas Besonderes unter den anderen hervorgetan. Ich glaube, dass Ihr nun reif genug seid, um die zu unterstützen, die an der Front der Blutmythosinsel kämpfen. Die Hand von Argus könnte <einen/eine> wie Euch gebrauchen.\n\nMeldet Euch bei Torallius dem Herdentreiber. Ihr findet ihn außerhalb der Exodar bei dem Elekk. Gebt ihm diese Befehle, damit er Euch neue Aufträge auf der Blutmythosinsel erteilen kann.", progress = "<Torallius rückt seine Augenklappe zurecht und sieht Euch an.>\n\nHaben wir der Hand von Argus nichts Besseres anzubieten?", completion = "&lt;Torallius seufzt.&gt;\n\nNun gut, lasst mich einen Blick auf diese Befehle werfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9624] = {title = "Lieblingsleckerli", objective = "Aonar bei Kessels Wegelager möchte, dass Ihr ihm 10 Sandbirnen bringt.", description = "Ich habe eine wundervolle Entdeckung gemacht, <Klasse>. In den noch unberührten Gebieten dieser Insel wächst eine außergewöhnliche Frucht, die Sandbirne genannt wird. Man findet sie am Boden nahe der Bäume.\n\nIch habe sie zum Kuchenbacken verwendet, aber wenn ich nicht Acht gebe, kommen die Elekk angelaufen und stehlen mir das Obst. Ich hatte genug eingesammelt, um mit den Tieren teilen zu können, aber mein Vorrat ist aufgebraucht und nun herrscht wieder großes Verlangen nach Kuchen. Würdet Ihr mir mit dem Sammeln der Früchte helfen, damit ich eine weitere Charge Kuchen backen kann? Ich werde teilen, ich verspreche es!", progress = "Man findet die Sandbirnen immer seltener, was natürlich weniger Kuchen und somit weniger Leckerli für die Elekk hier bedeutet. Konntet Ihr die benötigten Früchte auftreiben?", completion = "War das Auffinden der Früchte schwierig? Ich brauche mit jedem Mal länger.\n\nIch werde allmählich ganz damit aufhören müssen, da ich keine Zeit mehr dafür habe. Danke für das Sammeln der Birnen, &lt;Name&gt;. Jetzt kann ich zumindest noch ein oder zwei Kuchen backen, bevor die Saison vorüber ist.", rewards = "Weste des LandarbeitersLederpanzer des ElekkführersPanzerrüstung des ElekkreitersIhr bekommt:\n\nSandbirnenkuchen"}
MultiLanguageQuestData['de'][9625] = {title = "Elekk sind starker Tobak", objective = "Sprecht mit Vorkhan dem Elekktreiber auf der Blutmythosinsel.", description = "Ist er verrückt geworden? Wie kann er von mir erwarten, dass ich einen meiner wertvollen Lieblinge einem namenlosen <Jüngling/jungen Ding> wie Euch überlasse!\n\nLasst Euch etwas gesagt sein, Kindchen: Ihr werdet es nie zu einem von der Hand von Argus bringen! Ihr habt nicht das Zeug dazu!\n\nIch glaube, dieses Mal muss ich ihm seinen Willen lassen. Sprecht mit Vorkhan bei Kessels Wegelager auf der Blutmythosinsel. Folgt einfach der Straße von hier aus nach Norden und geht einfach nach Norden weiter, wenn sie abzweigt.", progress = nil, completion = "Naja, zumindest habt Ihr's bis hierher geschafft! Jetzt schicken wir Euch lieber an die Arbeit, bevor Ihr noch zertrampelt werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9626] = {title = "Ein Treffen mit dem Kriegshäuptling", objective = "Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zum Kriegshäuptling nach Orgrimmar, Hauptstadt von Durotar, bringt.", description = "Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Krallen und Zähnen gekämpft, damit Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.\n\nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zum Kriegshäuptling in Orgrimmar. Als Anführer der Horde hat er das letzte Wort bei der Entscheidung über die Bitte Eures Volkes.\n\nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.", progress = "Ihr seid zurück, um mich zu sehen, <Volk>? Sprecht und beeilt Euch. Ich habe keine Zeit für die Förmlichkeiten Eures Volks.", completion = "&lt;Thrall beginnt, den Brief zu lesen.&gt;\n\nSylvanas ist sehr hartnäckig. Sie hat also einen von Silbermonds Helden geschickt... und was ändert das?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9627] = {title = "Treue gegenüber der Horde", objective = "Kehrt nach Silbermond zurück und erstattet Lor'themar Theron Bericht.", description = "Euer Volk litt unter dem großen Verrat der Allianz. Ihr habt darnassische Angriffe zurückgeschlagen und Spione aus Eisenschmiede ausgeschaltet. Nun gelang es Euch, vor den Toren Eurer Heimat, einen der mächtigsten Anführer der Geißel zu vernichten. Euer Wert steht außer Frage.\n\nEs ist offensichtlich, dass wir einander brauchen. Kehrt zu Lor'themar zurück. Berichtet ihm, dass ich seine Botschaft laut und deutlich vernommen habe.\n\n<Der Kriegshäuptling zerknüllt den Brief in seiner Hand.>\n\nWillkommen in der Horde!", progress = nil, completion = "Eure Taten waren den Zielen unseres Volkes sehr dienlich. Nicht nur, dass Thrall nun davon überzeugt ist, dass wir uns dem Feind gegenüber behaupten können, nein, er glaubt außerdem, über uns und unsere Verbundenheit mit der Scherbenwelt, Kontakt zu den Überlebenden seines Volkes aufnehmen zu können.\n\nNicht gerade die Wahrheit, aber auch keine Lüge.\n\nBereitet Euch auf große Veränderungen vor, &lt;Name&gt;. Wir sind nun offiziell ein Teil der Horde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9628] = {title = "Bergung der Daten", objective = "Erlangt den Vermessungsdatenkristall von den Hasspranken nahe der toten Kartografen wieder und bringt ihn zu Herold Mikolaas bei der Blutwacht.", description = "Es ist zu spät, um den Kartografen beim Abschluss ihrer Mission zu helfen, aber es scheint, als hätten sie die Angaben gesammelt, nach denen Herold Mikolaas gefragt hat. Der Kristall, der ihre Vermessungsdaten beinhaltet, befand sich nicht unter ihren durchwühlten Habseligkeiten, also muss er den Naga der Hasspranken in die Hände gefallen sein.\n\nIhr wisst, dass Herold Mikolaas sehr betrübt über den Verlust des Teams sein wird, aber auch, dass er die Vermessungsdaten gerne retten würde.", progress = "Konntet Ihr herausfinden, was das Vermessungsteam von seiner Rückkehr abgehalten hat?", completion = "&lt;Ihr erzählt Herold Mikolaas vom Schicksal des Vermessungsteams. Er nimmt den Kristall von Euch entgegen, aber schweigt für einen langen Augenblick.&gt;\n\nEs waren gute Männer, &lt;Name&gt;, sie wussten, dass ihre Mission gefährlich sein würde. Ich bin Euch dankbar für das Auffinden des Teams und die Wiederbeschaffung des Kristalls.\n\n\n\nWir haben bereits zu viele unserer Männer verloren, dabei hat unsere Mission gerade erst begonnen.", rewards = "Ihr bekommt:\n\nMantel des Feldmessers"}
MultiLanguageQuestData['de'][9629] = {title = "Kurz geschnappt", objective = "Morae bei der Blutwacht möchte, dass Ihr 6 Späher der Schwarzschlammküste mit einem Murlocsender 'markiert'.", description = "Die Murlocs der Schwarzschlammküste an der südwestlichen Küste sind merkwürdige Kreaturen. Oft verhalten sie sich nach keinem richtigen Verhaltensmuster und manchmal legen sie ein erstaunliches Organisationsgeschick an den Tag.\n\nIch verfolge ein paar Theorien, die belegen könnten, wie sie das zustande bringen. Bis vor Kurzem konnte ich das Ganze jedoch noch nicht untersuchen. Ich habe eine Methode entwickelt, die es mir ermöglichen wird, die für mich interessanten Murlocs im Auge zu behalten, ohne ihnen dadurch längerfristig zu schaden oder ihr natürliches Verhalten zu stören. Wenn Ihr mir bei der Anbringung der Sender behilflich sein wollt, werde ich Euch gerne für Eure Unterstützung bezahlen.", progress = "Hat der Apparat funktioniert? Habt Ihr die Murlocs für meine Untersuchungen markiert?", completion = "Gut gemacht, &lt;Name&gt;. Ich hatte befürchtet, dass der Sender beim Markieren beschädigt werden könnte, aber scheinbar ist ja alles wie geplant verlaufen.", rewards = "Handschuhe des GelehrtenHandschuhe des ForschersSchützende FeldhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9630] = {title = "Medivhs Tagebuch", objective = "Erzmagier Alturus am Gebirgspass der Totenwinde möchte, dass Ihr nach Karazhan geht und mit Wravien sprecht.", description = "Euer Name spricht sich herum, <Name>. Ihr habt es nach Karazhan und wieder heraus geschafft - das ist mehr, als die meisten Sterblichen von sich behaupten können.\n\nIhr müsst mir einen ganz besonderen Gefallen tun. Im Rahmen unserer Forschungen hat das Violette Auge versucht, an Medivhs Tagebuch zu kommen.\n\nUnglücklicherweise kam keiner der Agenten, die wir hineingeschickt haben, wieder heraus. Wravien war der letzte, den wir geschickt haben. Sucht ihn und erkundigt Euch, ob es neue Anhaltspunkte zu diesem Tagebuch gibt.", progress = nil, completion = "Welch unermesslicher Wert an Informationen... Ich könnte Jahre hier verbringen! Ich bin sicher, Dalaran wird das verstehen...", rewards = nil}
MultiLanguageQuestData['de'][9631] = {title = "Hilfe unter Kollegen", objective = "Bringt das verkohlte Knochenfragment zu Kalynna Lathred in Area 52 im Nethersturm.", description = "Es gibt da ein kleines Detail, das ich vergessen habe. Die Überreste von Medivhs Essenz in diesem kleinen Knochenfragment ist völlig ohne Leben, genauso wie Arcanagos'.\n\nEs gibt jedoch einen Weg, sie wieder zum Leben zu erwecken. Und ich weiß auch genau, wer uns dabei helfen kann.\n\nReist nach Area 52 in Nethersturm und zeigt Kalynna Lathred das Knochenfragment. Sie wird wissen, was damit zu tun ist.", progress = "Alturus hat Euch geschickt. Die Sterne haben von Eurer Ankunft gesprochen.", completion = "Alturus möchte einen ganzen Drachen von den Toten zurückholen? Keine leichte Aufgabe.\n\nLasst uns darüber reden, wie wir uns gegenseitig unterstützen können, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9632] = {title = "Neue Verbündete", objective = "Bringt das Vorstellungsschreiben zu Jägerin Kella Nachtbogen auf die Azurmythosinsel.", description = "Herold Mikolaas hat bei der Sicherung der Blutwacht äußerst löbliche Arbeit geleistet, <Klasse>, allerdings sind unsere Feinde zahlreich und unsere Ressourcen gering.\n\nUnsere Gegner kennen unsere Schwäche nur zu gut, aber sie haben dabei nicht an Eure Verbindung zu den Streitkräften der Allianz gedacht. Ich habe ein Vorstellungsschreiben für Auberdine vorbereitet, der nächstgelegenen Siedlung der Allianz, in dem ich ihnen eine Zusammenarbeit beim Kampf gegen unsere Feinde vorschlage. Nehmt das Schreiben an Euch und sucht Jägerin Kella Nachtbogen auf, sie befindet sich in der Nähe der Docks westlich der Exodar.", progress = "Seid gegrüßt, <Klasse>. Was habt Ihr da?", completion = "Ich kann Euch helfen, nach Auberdine zu kommen. Glücklicherweise ist es nur eine kurze Fahrt mit dem Schiff von hier!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9633] = {title = "Der Weg nach Auberdine", objective = "Nehmt das Schiff in der Nähe von Jägerin Kella Nachtbogen nach Auberdine. Bringt das Vorstellungsschreiben zu Thundris Windwirker, sobald Ihr in Auberdine angekommen seid.", description = "Wenn Ihr am Dock wartet, werdet Ihr das Schiff sehen, das aus Auberdine von der Dunkelküste hier ankommt. Sobald alle Passagiere von Bord gegangen sind, könnt Ihr einsteigen.\n\nDas Schiff wird nach einer kurzen Fahrt in Auberdine anlegen und Ihr werdet Euer Schreiben überbringen können.\n\nAm besten bringt Ihr es zu Thundris Windwirker, er ist ein alter Freund von mir und genießt überall hohes Ansehen.", progress = "Willkommen in Auberdine. Was bringt Euch zur Dunkelküste?", completion = "&lt;Thundris nimmt das Schreiben von Euch entgegen, liest es und nickt.&gt;\n\nDie Inseln der &lt;Volk&gt;, die Azurmythosinsel und die Blutmythosinsel, wurden vor langer Zeit von meinen Leuten bewohnt. Einige der Bedrohungen, denen sich Anachoret Paetheus und seine Brüder und Schwestern jetzt stellen müssen, sind alte Feinde der Nachtelfen.\n\nIch bin mir sicher, dass man unseren neuen Verbündeten hier in Auberdine alles zur Verfügung stellen möchte, das benötigt wird. Sobald ich mit den Bewohnern der Stadt und den Schildwachen gesprochen habe, werde ich Paetheus benachrichtigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9634] = {title = "Raubtiere aus einer anderen Welt", objective = "Tötet 10 junge Blutfelshetzer und kehrt danach zu Vorkhan dem Elekktreiber bei Kessels Wegelager auf der Blutmythosinsel zurück.", description = "Eine Sache, die wir auf unseren Reisen gelernt haben, ist, dass man bei der Einführung von Wildtieren aus einer anderen Welt besonders vorsichtig sein muss. Als die Exodar abstürzte, hatte sie Exemplare verschiedenster Tierarten aus der Scherbenwelt an Bord, einschließlich eines insektenartigen Raubtiers, dem Felshetzer.\n\nBei dem Absturz starben einige der Tiere, aber viele andere überlebten und suchten in der Wildnis das Weite. Wenn wir sie nicht in Schach halten, werden sie hier auf den Inseln das natürliche Gleichgewicht von Jägern und Gejagten stören.\n\nIhr findet die Hetzer westlich von Kessels Wegelager, in der Nähe der Küste.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Der Felshetzerbestand wird zwar nur für einige Zeit begrenzt bleiben, aber es ist ein guter Anfang.", rewards = "Alter ElekktreiberZweisteinschlaghammerKlinge des ElekkführersGroßbastardschwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9635] = {title = "Der schockdrosselnde Partikelextraktor!", objective = "Bringt 15 Dampfpumpenteile zu Mack Dyver in Zabra'jin in den Zangarmarschen.", description = "Das Sumpfgas ist wirklich erstaunlich und kann sehr nützlich sein, Mann! Aber zuerst müsst Ihr in der Lage sein, es aufzusaugen, und dazu, mein Freund, braucht Ihr einen schockdrosselnden Partikelextraktor.\n\nNun, ich könnte Euch einfach die Baupläne geben, aber erst will ich etwas dafür haben. Wie wär's mit ein paar Ersatzteilen? Als ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der kaputten Dampfpumpe im Todesmoor herum, ganz im Nordosten.\n\nIch habe gehört, dass die siechenden Riesen die Teile überall in dem ausgetrockneten See verteilt haben.", progress = "Habt Ihr die Teile schon? Ich bin hier mit Tauchen beschäftigt.", completion = "Schön! Wenn wir jetzt noch einen Kaugummi, eine Wäscheklammer, Schrumpfschlauch und etwas klebriges Geschenkband hätten, könnten wir wirklich etwas daraus machen!\n\nOk, ok, ich glaube, Ihr habt Euch das verdient, &lt;Name&gt;. Viel Spaß damit!", rewards = "Ihr bekommt:\n\nBauplan: Schockdrosselnder Partikelextraktor"}
MultiLanguageQuestData['de'][9636] = {title = "Der schockdrosselnde Partikelextraktor!", objective = "Bringt 15 Dampfpumpenteile zu K. Lee Kleinkram in Telredor in den Zangarmarschen.", description = "Habt Ihr das Sumpfgas gesehen? Ist es nicht einfach klasse?\n\nMan braucht jedoch einen schockdrosselnden Partikelextraktor, um es aufzusaugen. Ich könnte Euch die Pläne dafür geben, aber zuerst brauche ich ganz dringend ein paar Ersatzteile, um ein paar Sachen hier zu reparieren.\n\nAls ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der Dampfpumpe im Todesmoor im Nordosten herum. Ich glaube, die siechenden Riesen haben die Pumpe kaputtgemacht.\n\nWollen wir uns gegenseitig helfen?", progress = "Habt Ihr die Teile schon? Ich muss die Kompressionsspule reparieren, bevor Anachoret Ahuurn mir im Nacken sitzt!", completion = "Klasse! Und mal ehrlich, welcher Ingenieur hat je genug Ersatzteile zur Hand? Hey, vielleicht könnte ich ja ein paar von den übrigen Teilen verkaufen und mir etwas von Tigule und Forors Erdbeereiscreme holen?! Ich liebe Erdbeeren! Denkt Ihr, man bekommt die hier irgendwo?\n\nOk, ok, Ich glaube, Ihr habt Euch das verdient, &lt;Name&gt;. Viel Spaß damit!", rewards = "Ihr bekommt:\n\nBauplan: Schockdrosselnder Partikelextraktor"}
MultiLanguageQuestData['de'][9637] = {title = "Kalynnas Bitte", objective = "Kalynna Lathred möchte, dass Ihr den Dämmerfolianten vom Großhexenmeister Nethekurse in den Zerschmetterten Hallen der Höllenfeuerzitadelle und das Buch der vergessenen Namen von Dunkelwirker Syth in den Sethekkhallen in Auchindoun besorgt.\n\nIhr müsst diese Quest auf dem Schwierigkeitsgrad 'Heroisch' abschließen.", description = "Ich habe die Kirin Tor verlassen, weil ich nach Wissen strebte, das von meinem Orden verboten wurde. Es ist mehr als ironisch, dass ich nun gebeten werde, sie mit genau diesem Wissen zu unterstützen.\n\nWenn ich Euch diesen Gefallen tun soll, dann müsst Ihr erst etwas für mich tun. Beschafft mir die beiden Folianten, nach denen ich schon so lange suche.\n\nDer erste heißt Dämmerfoliant und gehört dem orcischen Hexenmeister Nethekurse. Der zweite ist als Buch der vergessenen Namen bekannt und gehört einem Arakkoa namens Dunkelwirker Syth.", progress = "Habt Ihr die Folianten, die ich suche, <Name>?", completion = "Ausgezeichnet, &lt;Name&gt;. Ich versuche schon seit sehr langer Zeit, an diese Bücher heranzukommen. Welch Glück, dass wir uns gegenseitig helfen konnten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9638] = {title = "In guten Händen", objective = "Sprecht mit Gradav in der Bibliothek des Wächters in Karazhan.", description = "Hätte ich nach diesem Tagebuch suchen sollen? Das kann nicht sein... Ich erinnere mich nicht daran...\n\nAber natürlich! Ihr meint Gradav. Er war auf der Suche nach dem Buch, als ich hierher kam. Er hat es bestimmt schon gefunden, warum fragt Ihr ihn nicht einmal?\n\nIch würde Euch ja helfen... aber diese Bücher sind einfach so... interessant!", progress = nil, completion = "Seht Ihr nicht, dass ich hier beschäftig bin? Was wollt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9639] = {title = "Kamsis", objective = "Sprecht mit Kamsis in der Bibliothek des Wächters in Karazhan.", description = "Tagebuch? Welches Tagebuch? Ihr meint sicher Kamsis!\n\nGeht und fragt sie danach. Ich kann mein Projekt jetzt nicht allein lassen, sonst geht meine ganze Arbeit verloren!", progress = nil, completion = "Dieses Tagebuch von dem Ihr sprecht... Ich wurde hierher geschickt, um danach zu suchen, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9640] = {title = "Arans Schemen", objective = "Beschafft Medivhs Tagebuch und kehrt zu Kamsis in der Bibliothek des Wächters in Karazhan zurück.", description = "Lasst mich kurz nachdenken. Das Violette Auge... Medivhs Tagebuch... Oh ja, jetzt erinnere ich mich.\n\nIch glaube, ich hatte das Tagebuch, nach dem Ihr sucht, bevor ich anfing, diese Schriftrollen zu lesen...\n\nAran... genau, Aran hat mich darum gebeten. Und das auch noch so nett. Ich musste es ihm einfach geben. Schließlich ist er Medivhs Vater, wusstet Ihr das?", progress = "Wart Ihr nicht auf der Suche nach einem Tagebuch oder so?", completion = "Habt Ihr gefunden, was Ihr gesucht habt?  Ihr habt doch etwas gesucht, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9641] = {title = "Bestrahlte Kristallsplitter", objective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr ihm 10 bestrahlte Kristallsplitter bringt.", description = "Der Absturz der Exodar hat auf der Blutmythosinsel überall Stücke schädlicher Kristalle verstreut, die das Wasser und den Rest des Landes verderben.\n\nWir haben sogar schon Stücke der Kristalle im Fleisch von Tieren gefunden, die uns normalerweise als Nahrungsquelle dienen. Ich habe einen Weg gefunden, wie man die Splitter reinigen und somit in zweckmäßige Kristalle verwandeln kann. Wenn Ihr mir genug Splitter besorgt, werde ich Euch einen vollständigen Kristall im Tausch dafür geben. Bislang konnte ich die Splitter in den Körpern von Bären, Felshetzern, Faltern und Treants finden, die den verderbten Teil der Insel bewohnen.", progress = "Konntet Ihr Kristallsplitter von den Kreaturen der Blutmythosinsel einsammeln?", completion = "Gut gemacht. Diese Splitter werden als Rohmaterial für weitere Stärkungskristalle dienen.\n\nIhr könnt Euch einen der drei Typen aussuchen, die ich herstellen kann. Ich finde sie alle recht nützlich, je nachdem auf welche Beute man es abgesehen hat.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKristall der VitalitätKristall der EinsichtKristall der Wildheit\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9642] = {title = "Mehr bestrahlte Kristallsplitter", objective = "Solltet Ihr noch über mehr bestrahlte Kristallsplitter verfügen, tausche ich sie gerne gegen einen weiteren meiner Kristalle ein.", description = nil, progress = "Solltet Ihr noch über mehr bestrahlte Kristallsplitter verfügen, tausche ich sie gerne gegen einen weiteren meiner Kristalle ein.", completion = "Sehr schön, hier sind meine Kristalle, &lt;Name&gt;. Verwendet sie weise.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKristall der VitalitätKristall der EinsichtKristall der Wildheit"}
MultiLanguageQuestData['de'][9643] = {title = "Würgeranken", objective = "Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr ihm 6 dornige Würgeranken bringt.", description = "Ein guter Förster findet für jede der vorhandenen Ressourcen eine Verwendung, <Klasse>. Auch die skurrilsten Kreaturen besitzen Eigenschaften, die wir zu unserem Vorteil nutzen können.\n\nDa die Blutwacht ständig von den Sonnenfalken angegriffen wird, suchen wir nach einer Vielzahl natürlicher Verteidigungsmechanismen, die auch als Fallen dienen können. Die dornigen Ranken der Peitscher eignen sich perfekt für den Bau von Fallen, die meiner Vorstellung entsprechen. Die Kombination von scharfen Dornen und tödlichem Gift wird unachtsame Angreifer ausschalten. Bringt mir Ranken von mutierten Würgern, damit ich mit der Arbeit beginnen kann.", progress = "Habt Ihr die Würgeranken bekommen?", completion = "Das scheint mir stabil genug für meine Konstruktion. Danke für die Hilfe, &lt;Name&gt;. Eure Unterstützung bei der Verteidigung der Blutwacht wird nicht vergessen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9644] = {title = "Schrecken der Nacht", objective = "Geht zur Terrasse des Meisters in Karazhan und berührt die geschwärzte Urne, um den Schrecken der Nacht zu rufen. Entzieht dem Körper des Schreckens die schwache arkane Essenz und bringt sie zu Erzmagier Alturus.", description = "Ihr habt Euren Teil der Abmachung eingehalten. Ich werde Eure Essenz nun an die des getöteten blauen Drachen binden.\n\nAuf der Terrasse des Meisters steht eine Urne. Solltet Ihr sie berühren, wird die freigesetzte Energie die verkohlten Überreste von Arcanagos wieder zum Leben erwecken. Besiegt die Kreatur und entzieht ihr sofort ihre Essenz! Ihr werdet sie zu Alturus bringen müssen.\n\nWenn Ihr scheitert, sagen die Sterne voraus, werdet Ihr ein großes Unheil auf die Himmel loslassen.\n\nEin Unheil namens Schrecken der Nacht!", progress = "Welche Neuigkeiten bringt Ihr, <Name>?", completion = "Das ist erstaunlich! Ihr habt nicht nur Medivhs Tagebuch zurückgebracht, sondern auch noch einen Teil seiner Essenz!\n\nSo schwach sie auch sein mag, sie wird uns wertvolle Informationen über Medivh liefern können. Wir werden Euch das nicht vergessen, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStattlicher AmethystNimmermüder beruhigender AmethystZeitloser Amethyst\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9645] = {title = "Die Terrasse des Meisters", objective = "Geht zur Terrasse des Meisters in Karazhan und lest Medivhs Tagebuch.", description = "Tagebuch? Welches Tagebuch?\n\nOh, richtig. Dieses Tagebuch! Das Violette Auge hat mich deswegen hierher geschickt. Ich erinnere mich.\n\n<Kamsis zeigt auf eine Seite im Tagebuch>\n\nDies ist die Seite, an der Alturus interessiert ist. Wusstet Ihr, dass andere Leute Tagebücher benutzen, um ihre Erinnerungen aufzuzeichnen, während Medivhs Tagebuch genau seine Erinnerungen sind?\n\nProbiert es aus. Geht zur Terrasse des Meisters und lest die Seite. Ihr werdet sehen, was ich meine. Wenn Ihr schon da seid, könnt Ihr auch gleich Alturus Bericht erstatten. Ich fürchte, ich bin hier noch eine Weile beschäftigt.", progress = "Ihr seid zurück! Was für Nachrichten bringt Ihr?", completion = "Es ist eine Schande, dass die Agenten, die wir geschickt haben, Karazhans Magie unterlegen sind. Zumindest konntet Ihr beschaffen, wonach sie suchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9646] = {title = "GESUCHT: Todespranke", objective = "Bringt Todesprankes Tatze zu Herold Mikolaas bei der Blutwacht.", description = "Auf Anweisung von Herold Mikolaas: Man wird demjenigen ein Kopfgeld von 18 Silber auszahlen, der den Beweis für den Tod des räuberischen Bären Todespranke erbringen kann.\n\nTodespranke wird als besonders gefährlich eingestuft und ist für den Tod eines Vermessungsteams an der Küste im Nordwesten der Blutwacht verantwortlich. Reisende werden angehalten, diese Gegend zu meiden.", progress = "Wie kann ich Euch helfen, <Klasse>?", completion = "Gut gemacht. Von dem, was ich gehört habe, war es wohl kein leichter Kampf. Ihr habt Euch Eure Belohnung mehr als verdient, &lt;Name&gt;.", rewards = "Rundschild des FriedensbewahrersAuf Euch wartet eine dieser Belohnungen:\n\nVerzierte Kristallkugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9647] = {title = "Ausmerzen der Falter", objective = "Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr 10 königsblaue Falter tötet.", description = "Als wir den Faltern das erste Mal auf der Insel begegneten, zeigten sie nur wenige Anzeichen von Mutation. Als sich die Verderbnis immer weiter ausbreitete, wurden die Motten und andere Arten jedoch immer mehr verseucht.\n\nEs ist jetzt sogar soweit gekommen, dass sie fast alles, mit dem sie in Berührung kommen, beschädigen. Der Schaden wird von den Kristallsplittern, die beim Absturz der Exodar zerbrochen wurden, noch verstärkt. Uns bleibt keine andere Wahl, aber wir müssen die Motten, die das Land nördlich der Blutwacht behausen, ausmerzen.", progress = nil, completion = "Es gilt jetzt, eine längerfristige Lösung zu finden, um die Arten wieder in ihren Urzustand zurückzuführen. Momentan ist das zeitweilige Ausmerzen ihres Bestandes jedoch die beste Methode. Danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Umgürtelung aus WebschilfReich geschmückter GürtelSegmentierter GurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9648] = {title = "Pilzsammlung von Maatparm", objective = "Maatparm bei der Blutwacht möchte 1 Wasserstinkmorchel, 1 Blutpilz, 1 ruinösen Birkensporling und 1 Teufelszapfenfungus.", description = "Habt Ihr gewusst, dass das Sammeln von Pilzen gefährlicher als der Verzehr von Pilzen ist? Pilzsammler begeben sich ins Unbekannte - dazu kommen noch die Gefahren, die in der Wildnis lauern!\n\nWas wäre das Leben ohne ein paar Wagnisse? Ich benötige Pilze für meine Sammlung. In dieser unerforschten Natur werdet Ihr vier Arten finden: Wasserstinkmorchel, Blutpilz, ruinöser Birkensporling und Teufelszapfenfungus. Sie sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel. Bringt sie mir.", progress = "Vergesst nicht, die von mir benötigten Pilze sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel.", completion = "Nun, ich hatte Euch gewarnt - oder etwa nicht? Ich hoffe diese kleine Bezahlung wird Euch für Eure Unannehmlichkeiten etwas entschädigen können. Kehrt zu mir zurück, sobald Ihr Euch ein wenig erholt habt, dann habe ich vielleicht noch eine Aufgabe für Euch - mit Pilzen natürlich!", rewards = "Maatparms fungusgefütterte ManschettenMaatparms fungusgefütterte BänderMaatparms fungusgefütterte ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9649] = {title = "Yseras Tränen", objective = "Maatparm bei der Blutwacht möchte 2 Yseras Tränen.", description = "Gut, Euch wieder zu sehen, <Name>! Ihr wart bei meiner letzten Aufgabe sehr tüchtig. Seid Ihr vielleicht an einer weiteren interessiert?\n\nIm Nordosten liegt die Insel Drachenfels, sie beheimatet eine sehr seltene Pilzart, die unter dem Namen Yseras Träne bekannt ist - benannt nach den grünen Drachlingen, die auf dieser Insel hausen. Ich brauche nicht viele von diesen Pilzen, möchte Euch aber dennoch warnen, denn die Bewohner dieser Insel mögen keine Besucher. Gebt auf Eure Schritte Acht.", progress = "Schon wieder zurück?", completion = "Ich hoffe diese Aufgabe hat nicht zu viel von Euch abverlangt, &lt;Name&gt;. Ihr habt erneut bewiesen, dass Ihr ein fähiger und aufmerksamer &lt;Volk&gt; seid. Habt meinen Dank und natürlich eine kleine Abfindung.", rewards = "Maatparms fungusgefütterte TunikaMaatparms fungusgefütterte WesteMaatparms fungusgefütterte HalsbergeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9663] = {title = "Der Korsallauf", objective = "Kessel bei Kessels Wegelager möchte, dass Ihr den Oberhäuptling der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz vor der unmittelbar bevorstehenden Blutelfeninvasion warnt. Ihr habt 15 Minuten. Kehrt anschließend zu Kessel zurück. Denkt daran, dass Elekks wasserscheu sind!", description = "Ihr kommt gerade richtig, <Name>. Die Aktivitäten der Blutelfen haben sich in der letzten Woche fast verdoppelt. Unsere Agenten haben uns mitgeteilt, dass die Blutelfen, die sich selbst Sonnenfalken nennen, einen baldigen Angriff auf die Azurmythosinsel planen. Ihr müsst unseren Verbündeten und Landsmännern eine Warnung zukommen lassen.\n\nWarnt den Oberhäuptling bei der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz.\n\nDie Zeit drängt, deshalb werde ich Euch meinen Elekk zur Verfügung stellen. Beeilt Euch!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Dies war ein Test Eurer Fähigkeiten, aber Ihr habt mit wehenden Fahnen bestanden. Um ein Soldat der Hand von Argus zu werden, gilt es viele dieser Tests zu bestehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKessels Elekk abbrechen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9664] = {title = "Mehr Befestigungen", objective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den Östlichen Pestländern. Kehrt anschließend zum Abgesandten Weißbart bei der Kapelle des Hoffnungsvollen Lichts zurück.", description = "Willkommen in den Pestländern, <Name>. Wie Ihr wisst, behaupten sich die Verlassenen und ihre Verbündeten entgegen all unserer Anstrengungen in den von hier aus westlich gelegenen Ländern. Die Kommandanten der Allianz haben beschlossen, dass hier im Osten neue Befestigungen errichtet werden sollen, um die Schlinge um unseren Feind noch etwas enger zu schnüren.\n\nLange seit den Tagen Lordaerons verlassene und herrenlose Türme müssen für diesen Zweck erobert und wieder aufgebaut werden. Diese Länder hier sind gefährlich, wir brauchen Eure Hilfe.", progress = nil, completion = "Sehr gut, &lt;Name&gt;. Es ist äußerst wichtig, dass wir diese Türme halten. Wir müssen sie vor zukünftigen Angriffen schützen und brauchen noch so lange Eure Hilfe, bis Verstärkung zur Sicherung dieses Gebiets eintrifft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9665] = {title = "Verstärkung der Verteidigung", objective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den Östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des Hoffnungsvollen Lichts zurück.", description = "Agenten der Verlassenen sind hinter das Vorhaben der Allianz gekommen. Sie wollen neue Stützpunkte bei verlassenen Türmen hier in den Östlichen Pestländern einrichten.\n\nWir dürfen auf keinen Fall zulassen, dass sie sich an unserer östlichen Grenze dauerhaft festsetzen, wir müssen den Einfall der Allianz abwehren. Wir beabsichtigen sie aus jeglichen Türmen, die sie bereits besetzt haben, zu vertreiben. Dann gilt es diese Türme zu verteidigen und weitere Eroberungsversuche abzuwehren.", progress = nil, completion = "Das sind gute Neuigkeiten, &lt;Name&gt;. Bis wir die Kräfte der Allianz gänzlich vertrieben haben, wird es hier in den Pestländern dauerhaft zu Kämpfen kommen.\n\nIch hoffe, dass Ihr uns bis zu diesem Tag auch noch weiterhin unterstützt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9666] = {title = "Machtdemonstration", objective = "Kessel bei Kessels Wegelager auf der Blutmythosinsel möchte, dass Ihr Lord Xiz bei der Hassprankenzuflucht tötet und das Banner der Draenei durch seinen Körper stoßt.", description = "Habt Ihr die Schlangenwesen gesehen? Die, die sich selbst Naga nennen?\n\n<Kessel spuckt.>\n\nSie haben es vor drei Nächten gewagt, im Schutze der Dunkelheit bis zu diesem Lager vorzudringen. Denkt nur an die Dreistigkeit dieser primitiven Biester!\n\nIhr müsst ihrem Anführer eine Botschaft überbringen, <Name>. Im Nordosten liegt die Hassprankenzuflucht, der Sitz von Lord Xiz. Findet ihn, tötet ihn an Ort und Stelle und treibt diesen Banner durch seinen Körper.\n\nLasst sie vor Furcht erschaudern, wann immer sie diese Standarte sehen!", progress = nil, completion = "Es tut mir leid, dass Ihr das tun musstet, &lt;Name&gt;. Rohe Gewalt entspricht nicht der Natur der &lt;Volk&gt;, aber manchmal ist sie der einzige Weg.\n\nUnglücklicherweise gehört dies zum Leben und man versteht es oft erst dann, wenn es zu spät ist. Genau wie mit den Orcs, die unsere Brüder und Schwestern abschlachteten.\n\nEin Mitglied der Hand von Argus zu werden, ist ein Prozess der Wiedergeburt. Mit der Geburt kommt bekanntlich auch der Schmerz...", rewards = "Kessels SattelgurtwickelKessels schweißbefleckte ElekkleineKessels stabiler ReitbügelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9667] = {title = "Rettet die Prinzessin der Tannenruhfeste", objective = "Befreit die Prinzessin der Tannenruhfeste aus ihrem Käfig und sprecht anschließend mit Botschafter Olorg der Tannenruhfeste bei der Blutwacht.\n\nIhr müsst den Oberhäuptling der Sichelklauen töten, um an den Schlüssel für den Käfig zu gelangen.", description = "Helft mir, <Name>! Die Sichelklauen haben mich gefangen genommen und wollen mich ihren üblen Göttern opfern!\n\nDer Oberhäuptling der Sichelklauen ist in Besitz der Schlüssel für den Käfig. Damit er auftaucht, müsst Ihr die bösartigen Furbolgs der Sichelklauen töten, die in der Enklave hausen. Sie liegt zwei Lager weiter im Westen. Wenn Ihr genug von ihnen niedergestreckt habt, wird er kommen, um sich zu rächen! Tötet ihn, sobald er sich zeigt, und nehmt die Schlüssel an Euch!\n\nMein Vater wird Euch reichlich entlohnen, wenn Ihr es schafft mich zu rettet!", progress = nil, completion = "Ihr habt erneut bewiesen, dass Ihr all dem entsprecht, was in der Prophezeiung vorhergesagt wurde. Ihr habt den ewigen Dank des Oberhäuptlings, &lt;Name&gt; - und Ihr habt die Wahl zwischen diesen Relikten der Tannenruhfeste...", rewards = "Schocker der TannenruhfesteDas MordsdingIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9668] = {title = "Erstattet Exarch Admetius Bericht", objective = "Sprecht mit Exarch Admetius bei der Blutwacht.", description = "Ein Soldat der Hand von Argus ist vielerlei: gehorsam, mutig, intelligent und vor allem ehrenhaft. Vielleicht verfügt Ihr schon jetzt über einige dieser Züge, <Klasse>.\n\nErstattet Exarch Admetius bei der Blutwacht Bericht, wenn Ihr der Hand noch immer beitreten möchtet. Er und seine Untergebenen werden Euch weiter auf dem Weg zum Draeneisoldaten ausbilden.\n\nUnd vergesst dies nicht, <Name>: Ehrenhafte Personen handeln nicht immer ehrenhaft. Manchmal ist es ihnen nicht möglich.\n\nIhr findet die Blutwacht ganz einfach diese Straße entlang, in Richtung Norden.", progress = nil, completion = "Ich hatte es bereits im Gefühl, dass Ihr es bis hierher schaffen würdet, &lt;Klasse&gt;. Wenn Ihr noch weiter kommen möchtet, bin ich gerne bereit Euch zu unterrichten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9669] = {title = "Forschungsreise in den Tod", objective = "Tötet 8 Mythosspinner, 8 Mythosfänger und ihre Anführerin Zarakh. Kehrt anschließend zu Achelus bei der Blutwacht zurück.", description = "Vor etwa einer Woche war ich mit meinem Forschungsteam auf einem Erkundungstrip im Westen der Blutmythosinsel, als wir plötzlich von blutdurstigen Spinnen angegriffen wurden. Die Auswirkungen der Kristallverseuchung waren unverkennbar, da diese Spinnen extrem groß und aggressiv waren.\n\nIch schaffte es zu fliehen, aber mein Team hatte nicht so viel Glück. Wir dürfen nicht zulassen, dass andere das gleiche Schicksal ereilt. Geht nach Westen zum Goldweberpass und vernichtet die Spinnen und ihre Matriarchin Zarakh.", progress = nil, completion = "Unglaublich! Konntet Ihr andere Überlebende finden?\n\n&lt;Achelus senkt seine Stimme zu einem Flüstern.&gt;\n\nIch möchte ehrlich mit Euch sein, &lt;Name&gt;, niemand sonst wollte diesen Auftrag annehmen. Ihr seid sehr mutig, &lt;Klasse&gt;...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9670] = {title = "Sie leben! Vielleicht...", objective = "Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.", description = "Es war ein blutiges Gemetzel, <Name>. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.\n\nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!\n\nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?\n\nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!", progress = nil, completion = "Ihr habt mehr als die Hälfte des Teams befreit! Der Exarch und die anderen bei der Blutwacht werden mit Sicherheit von Eurer heldenhaften Tat erfahren. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGiftseidenbedeckung"}
MultiLanguageQuestData['de'][9671] = {title = "Dringende Nachricht", objective = "Seid Ihr <Name>? Es wurde auch Zeit! Ich war gerade dabei, die Suche nach Euch aufzugeben!\n\nBeim Briefkasten wartet eine dringende Nachricht auf Euch. Die Person, die sie mir übergeben hatte, war ein Admiral der Menschen von der Azurmythosinsel. Admiral Odesy-irgendwas... der Name ist mir entfallen. Er sagte, Ihr würdet wissen, wer er sei.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9672] = {title = "Das Vermächtnis des Blutfluchs", objective = "Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.", description = "Getreuer Freund,\n\nmeine Hand zittert beim Schreiben dieses Briefs. Ich hoffe, dass er Euch rechtzeitig erreicht.\n\nLetzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.\n\nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich von Eurer Basis liegt, suchen?\n\nGruß,\n\nAdmiral Odesyus", progress = nil, completion = "Habt Ihr von dem Blutfluch gehört, Landratte? Nein, natürlich nicht. Der Blutfluch ist das, was all diese Schiffe hat sinken lassen. Der verderbte, entweihte Teil des Wassers hier wird Riff des Blutfluchs genannt - ein Teil der Welt, den Ihr niemals sehen möchtet. Ich bin hier selbst seit 20 Jahren.\n\nSkorbut, so ein Quatsch! Ich starb an diesen Wilden Ufern als Drachenfutter... Ah, das ist wieder eine andere Geschichte, für ein anderes Mal. Jetzt müssen wir den armen Seelen helfen, die hier im Riff gefangen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9673] = {title = "Wildtierausbildung", objective = "Sprecht mit Halthenis in Silbermond.", description = "Nachdem Ihr nun alles über die Zähmung eines Tieres wisst, ist es an der Zeit, sich mit den Feinheiten der Pflege und Ausbildung Eures Begleiters vertraut zu machen. Sucht dazu Halthenis den Tierausbilder von Silbermond auf, er wird Euch alles Nötige beibringen.\n\nEr respektiert meine Schüler in höchstem Maße, solange Ihr Euch ihm gegenüber genauso respektvoll verhaltet. Enttäuscht mich also nicht.", progress = nil, completion = "Ihr habt also schon einiges gelernt, nicht wahr?\n\n&lt;Halthenis begutachtet Euch eingehend.&gt;\n\nMit Euren neu erlernten Fähigkeiten werdet Ihr der Stadt und unserer großen Sache gut dienen. Gebt mir einen Moment Zeit, um Euch zu zeigen, wie Ihr Euer Tier ausbildet und wie man ihm einige interessante Tricks, wie das Ausweiden Eurer Feinde, beibringen kann. Danach könnt Ihr Eures Weges gehen.", rewards = "Ihr bekommt außerdem:\n\nBogen der Weltenwanderer"}
MultiLanguageQuestData['de'][9674] = {title = "Die Naga des Blutfluchs", objective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 10 Naga des Blutfluchs tötet.", description = "Man sagt, dass dieses Land am lautesten geschrien hat, als die Welt geteilt wurde. Hier fielen tausende von Nachtelfen und an ihrer Stelle erhoben sich fürchterliche Kreaturen des Hasses - die Naga.\n\nIhrer wahnsinnigen Königin, Azshara, gehorsam ergeben, würden sie alles und jeden zerstören, der sich durch ihre Gewässer wagt. Es würde noch für tausende von Jahren so bleiben - bis zum heutigen Tag.\n\nZuerst gilt es die Naga des Blutfluchs aus dem Riff zu entfernen.", progress = "Es sind garstige Kreaturen...", completion = "Ein guter Anfang, aber es gibt noch viel mehr zu tun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9675] = {title = "Wildtierausbildung", objective = "Sprecht mit Ganaar bei der Händlertreppe der Exodar.", description = "Oh, da wäre noch etwas! Ihr solltet mit Ganaar bei der Exodar sprechen. Er wird Euch das letzte bisschen Wissen bezüglich der Pflege und Ausbildung Eures Begleiters lehren.\n\nIhr findet ihn in der südwestlichen Ecke der Händlertreppe.", progress = nil, completion = "Zu wissen, wie man seinen Begleiter füttert und wiederbelebt, ist nicht nur ein zusätzlicher \"Leckerbissen\", wie Euer letzter Lehrer so gelinde sagte - es ist viel mehr. Mit der richtigen Ausbildung kann sich Euer Begleiter auf eine Weise verbessern, wie er es nie von alleine getan hätte.\n\nIch habe bereits viel von den Furbolgs gelernt, also gebt Acht und ich werde dieses Wissen an Euch weitergeben.", rewards = "Ihr bekommt außerdem:\n\nSilberne Armbrust"}
MultiLanguageQuestData['de'][9676] = {title = "Ausbildung zum Paladin", objective = "Sprecht mit Jesthenis Sonnensturm - dem Paladinlehrer - im Sonnenturm auf der Insel der Sonnenwanderer.", description = "Mit dem Voranschreiten in Eurer Klasse, möchtet Ihr sicherlich von der Ausbildung profitieren, die Euch der Lehrer für Eure Klasse anbieten kann. Jesthenis Sonnensturm ist der Lehrer für junge Paladine hier auf der Insel der Sonnenwanderer. Sprecht mit Jesthenis und seht, welche Ausbildung er Euch anbieten kann. Es wird Euch etwas kosten, bringt also ein wenig Geld mit Euch.\n\nEuer Lehrer - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - befindet sich im unteren Teil des Sonnenturms.", progress = nil, completion = "Ich sehe Eure vor Stolz geschwollene Brust. Ihr glaubt Euch schon als einer der Blutritter.\n\nMit der Zeit werdet Ihr Euch einen Platz in unseren Reihen verdienen. Als Erstes müsst Ihr jedoch den Umgang und das Meistern des mächtigen Lichts erlernen. Verbessert Eure Waffenfertigkeit und erweist Euch als würdig.\n\nIhr müsst gut vorbereitet sein, um den Spott, die Angst und den Abscheu derer ertragen zu können, die Ihr zu beschützen geschworen habt. So ergeht es denjenigen, die nicht verstehen, welchen Preis es für die große Macht zu zahlen gilt, die sie beschützt. Geht mit erhobenem Haupt und gezückter Klinge voran, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9677] = {title = "Aufforderung des Ritterfürsten Heldenblut", objective = "Sprecht mit Ritterfürst Heldenblut beim Platz der Weltenwanderer in Silbermond.", description = "<Name>, Ihr habt Euch in Eurer frühen Ausbildung bereits selbst übertroffen und von den anderen, die Blutritter werden möchten, hervorgehoben. Ihr seid reif für die nächste Ausbildungsphase und dazu kommt, dass Ritterfürst Heldenblut höchstpersönlich nach Euch verlangt hat.\n\nIch zweifle nicht daran, dass Ritterfürst Heldenblut Eure Fähigkeiten und Eure Ausbildung einer Prüfung unterziehen möchte. Ihr findet ihn beim Hauptsitz der Blutritter in Silbermond beim Platz der Weltenwanderer. Alles Gute, <Name>.", progress = nil, completion = "Willkommen, junger Initiand. Dass Ihr meiner Aufforderung so rasch nachgekommen seid, verheißt Gutes.\n\nLasst uns auf Belanglosigkeiten verzichten, sie passen besser zu Höflingen und ihresgleichen.\n\nEure schnellen Fortschritte haben meine Aufmerksamkeit auf sich gezogen, &lt;Name&gt;. Wir werden sehen, ob Ihr Eure Lehrstunden wirklich zu Herzen genommen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9678] = {title = "Die erste Prüfung", objective = "Reist zu der Insel, die Euch Ritterfürst Heldenblut beschrieben hat, sucht die Höhle und entzündet die Kohlepfanne. Kehrt, nachdem Ihr die erste Prüfung bestanden habt, zu Ritterfürst Heldenblut in Silbermond zurück.", description = "Ihr habt viel über das Kämpfen und Vergießen von Blut gelernt, Initiand, doch in unserem Orden geht es um viel mehr.\n\nDie Beherrschung des Lichts erfordert einen klaren Geist und enorme Willenskraft.\n\nOhne diese Eigenschaften seid Ihr nicht mehr wert als ein räudiger Streuner.\n\nAn den nordöstlichen Ausläufern der Geisterlande gibt es eine Insel, die Insel des Martyriums, auf der wir diese Eigenschaften formen. Versteckt in einer kleinen Höhle, steht eine Kohlepfanne. Kniet vor ihr, entzündet sie und konzentriert Euch auf das, was Ihr vor Euren Augen seht.", progress = nil, completion = "Ich denke ich weiß, was Euch gerade durch den Kopf geht.\n\nJa, ich entsandte Stillstreich, um Euch zu töten.\n\nNehmt es mir nicht übel, &lt;Name&gt;; es war eine notwendige Prüfung. Die Blutritter sind eine Ordensgemeinschaft, ja, doch müssen wir sicherstellen, dass unsere Brüder und Schwestern stets wachsam und vorbereitet sind. War Stillstreichs Tod tatsächlich notwendig, um Euch diese Lektion zu erteilen?\n\nJa, denn dies ist ein ebenso wichtiger Bestandteil Eurer Ausbildung wie das Schwerttraining.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9680] = {title = "Die Vergangenheit aufwühlen", objective = "Erzmagier Alturus möchte, dass Ihr zu den Bergen südlich von Karazhan im Gebirgspass der Totenwinde geht und ein verkohltes Knochenfragment besorgt.", description = "Kamsis hatte Recht! Diese Information ist äußerst wichtig. \n\nWenn Medivh seine eigene Essenz in die Magie, die er benutzt hat, um den Drachen zu besiegen, hineingewebt hat, dann ist es ziemlich wahrscheinlich, dass wir einen schwachen Rest dieser Essenz aus den Überresten des Drachen gewinnen können. Welch großartige Erkenntnisse mögen wohl unter der Asche des Gebirgspass der Totenwinde liegen, die nur darauf warten, entdeckt zu werden.\n\nGeht zu den Bergen südlich von Karazhan und bringt mir ein Knochenfragment deutlich drachischen Ursprungs.", progress = "Habt Ihr das Knochenfragment, das ich brauche, <Name>?", completion = "Ausgezeichnet! Auch wenn es klein ist, strotzt es nur so vor Energie, ich fühle es!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9681] = {title = "Eine Studie der Macht", objective = "Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.", description = "Haltet mich nicht für übermäßig grausam, <Name>. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.\n\nMeine Worte sind nicht als Grabesrede gedacht, <Name>. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.\n\nEure Ausbildung in der Kunst des Ordens hat gerade erst begonnen. Angesichts Kael'thas' Verrat und des Verlusts unserer Energiequelle, müsst Ihr neue Wege zur Beherrschung des Lichts erlernen. Sucht Magister Astalor Blutschwur auf.", progress = nil, completion = "Willkommen, junger &lt;Klasse&gt;.\n\nAls der Orden gegründet wurde, machte uns Kael'thas einen gefangenen Naaru zum Geschenk. Dieses Wesen besteht aus genau dem Licht, das wir beherrschen. Mithilfe unserer überragenden magischen Fähigkeiten lernten wir, wie man es kontrolliert und unterwirft, damit sich die Blutritter seiner Energie bedienen können.\n\nDoch Kael'thas wurde von seiner eigenen Machtgier übermannt und verbündete sich mit unseren Feinden. Seine niederträchtigen Anhänger griffen uns an, nahmen den Naaru und schnitten uns von der Energiequelle ab. Unser Orden erlebt dunkle Zeiten, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9682] = {title = "Die Hoffnungslosen...", objective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 4 Seelen des Blutfluchs zu ihm bringt.", description = "An einem Vorsprung des Riffs, noch tiefer im Wasser als die Naga des Blutfluchs, werdet Ihr die Hoffnungslosen finden: Reisende des Blutfluchs, Geister derer, die vom Blutfluch heimgesucht wurden.\n\nEs ist bedauerlich, was ich jetzt von Euch verlangen werde... aber sie müssen vernichtet und ihre Hüllen des Blutfluchs zu mir gebracht werden.\n\nIhre Seelen müssen erlöst werden. Kehrt zu mir zurück, wenn Ihr dergleichen getan habt und ich werde Euch eine letzte Aufgabe stellen.", progress = "Trauert ihrem Niedergang nicht nach, <Name>.", completion = "Ihr habt den Hoffnungslosen einen großen Dienst erwiesen, &lt;Name&gt;. Es gilt jedoch noch eine letzte Aufgabe zu erledigen: Tötet den Anführer des Blutfluchs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9683] = {title = "Beendigung des Blutfluchs", objective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr die Statue der Königin Azshara zerstört und Atoph des Blutfluchs tötet.", description = "Im Süden findet Ihr die Insel des Blutfluchs. Oben auf der Insel befindet sich ein Schrein, der der von den Naga geliebten Königin, Azshara, gewidmet wurde. Zerstört die Statue - verbrennt das Abbild! Dies wird mit Sicherheit den Zorn von Anführer Atoph des Blutfluchs erwecken.\n\nTötet Atoph und kehrt zu mir zurück!", progress = "Ihr müsst Atoph hervorlocken!", completion = "Ihr habt es geschafft! Hunderte von Seelen sind Euch für alles, was Ihr getan habt, dankbar.\n\nGestattet mir, Euch etwas zu überreichen...", rewards = "Ihr bekommt:\n\nRad der verlorenen Hoffnung"}
MultiLanguageQuestData['de'][9684] = {title = "Die Beherrschung des Lichts", objective = "Wendet das schimmernde Gefäß auf die Magister der Blutelfen an, um es zu füllen und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück.", description = "Nehmt dieses Gefäß, <Name>. Durch die Erweckung seiner Verzauberung werdet Ihr in der Lage sein, die letzten Überreste des Lichts, das diese Magister umgibt, für Euch zu nutzen. Sie pflegten einst den gefangenen Naaru und tragen noch immer einen Teil von dessen Energie in sich.\n\nSorgt Euch nicht um die Magister, <Name>. Ich kümmere mich um ihr Wohlergehen. Lord Solanar hat mir versichert, dass Lady Liadrin selbst jetzt auf der Suche nach einer neuen Energiequelle ist.", progress = "Habt Ihr schon mit Magister Astalor Blutschwur gesprochen?", completion = "Gut gemacht, &lt;Name&gt;. Die vom Licht gewährten Kräfte sind niemals auf 'natürlichem' Wege zu den Blutrittern gekommen, aber wir sind nicht so willensschwach, um unseren Weg von der Natur diktieren zu lassen.\n\nUnsere Beherrschung des Arkanen hat uns einen Pfad durch diese rauen Zeiten eröffnet. Die Kräfte fließen nicht mehr frei in diesen Hallen, doch sie sind da, für die hartnäckigen und willensstarken. Nur wenige sind heutzutage mutig genug, oder verfügen über die Begabung, sie zu meistern, aber ich weiß, dass Ihr den Orden nicht enttäuschen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9685] = {title = "Die Erlösung der Toten", objective = "Bringt das gefüllte schimmernde Gefäß zum Gasthaus von Silbermond und verwendet seine Magie, um Sangrias Stillstreich wiederzubeleben.", description = "Während Ihr das Gefäß vorbereitet habt, habe ich eine Gruppe von Initianden entsandt, um Sangrias Stillstreich zu bergen. Ihr findet ihn, zusammen mit einem Ordensdiener, auf der obersten Etage des Gasthauses von Silbermond. Begebt Euch ohne Verzögerung dorthin und entfesselt die magischen Kräfte des Gefäßes, um ihn ins Leben zurückzuholen.\n\nDie Zeit drängt, <Name>. Sollte er zu lange tot sein, können ihn nicht einmal mehr die Mächte des Lichts retten. Kehrt nach Stillstreichs Wiederbelebung zu mir zurück.", progress = nil, completion = "Willkommen zurück, Initiand. Jetzt, da Ihr die volle Wahrheit über die Quelle unserer Macht kennt und nachdem Ihr Euer Geschick bei dessen Anwendung unter Beweis gestellt habt, gewähre ich Euch die Fähigkeit, die Toten auf dem Schlachtfeld wiederzubeleben.\n\nWenn Ihr dem Orden gegenüber treu bleibt und Ihr die Ausbildung weiter so beflissen fortsetzt, werdet Ihr nur noch mächtiger werden.", rewards = "Ihr erlernt:\n\nErlösung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9686] = {title = "Die zweite Prüfung", objective = "Besteht die zweite Prüfung und besiegt Champion Rachblut, Champion Lichtrend, Champion Schnellklinge und Champion Sonnensturm im Pavillon in der Nähe von Meister Kelerun Blutpein.", description = "Ihr steht kurz davor, innerhalb des Ordens den Status eines Adepten zu erhalten, <Name>. Zunächst werdet Ihr jedoch beweisen müssen, dass Ihr für eine solche Ehre schon bereit seid, indem Ihr eine weitere Prüfung absolviert.\n\nDie zweite Prüfung unterscheidet sich vor allem dadurch von der Ersten, dass Euch keine unliebsamen Überraschungen mehr erwarten. Die vor Euch liegende Aufgabe ist einfach; Ihr müsst Euch gegen die vier besten Champions der Blutritter im Kampf beweisen.\n\nSobald Ihr die Herausforderung annehmt, erscheint in der Mitte des Pavillons ein Kristall. Berührt ihn, um mit Eurer Prüfung zu beginnen und entfernt Euch niemals zu weit von dem Gebäude.\n\nSeid Ihr bereit?", progress = "Ein Blutritter würde eher sterben, als sich seinem Feind zu unterwerfen. Vergesst das nie, <Name>.", completion = "Hervorragend, &lt;Name&gt;! Ihr habt Eure Fähigkeiten unter Beweis gestellt und seid würdig, in den Stand eines Adepten, eines vollwertigen Mitglieds der Blutritter, erhoben zu werden. Bevor die tatsächliche Zeremonie stattfinden kann, warten allerdings noch einige Aufgaben auf Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9687] = {title = "Wiederherstellung der Heiligkeit", objective = "Prinz Toreth auf der Insel Drachenfels möchte, dass Ihr 8 Drachenknochen wiedererlangt.", description = "Es ist noch nicht lange her, da kamen die einst so friedlichen Eulkin der Umgebung an die Ufer dieser Insel. Sie kamen einer nach dem anderen, um die Knochen der gefallenen Drachen zu stehlen. Ich weiß nicht, was die Kreaturen in diese Verzweiflung getrieben hat oder warum sie die Knochen der Dahingeschiedenen wollen. Allerdings ruhen die Geister der Brut seit dieser Schändung nicht mehr.\n\nGen Westen, über die Purpurbrandung hinweg, liegt der Rachfederkamm. Reist zu den Siedlungen der Eulkin und nehmt die gestohlenen Drachenknochen wieder an Euch.", progress = "Die Kriege der Drachen sind seit langem vorüber. Was noch bleibt, sind die Knochen und die aufgewühlten Überbleibsel von Yseras Brut.", completion = "Ein Ritual? Die Eulkin haben seit tausenden von Jahren mit dem Land in Einklang gelebt. Derartiges ist nicht normal!\n\nWie bedauerlich...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9688] = {title = "Im Traum", objective = "Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr 5 Viridianwelpen und 5 Viridianbrutlinge tötet.", description = "Die Welpen, die Ihr auf dieser Insel seht, sind die ruhelosen Geister des grünen Drachenschwarms. Sie sind wie ich an das Land gebunden, außerstande ihre letzte Ruhestätte im Traum zu erreichen.\n\nDie Wiederbeschaffung der Knochen von den Gefallenen hat sie zwar etwas beruhigt, aber Ihr müsst noch mehr unternehmen.\n\nZerstört ihre astralen Erscheinungen. Ich kann diesen Ort erst verlassen, wenn es geschehen ist. Sie müssen erlöst werden!", progress = nil, completion = "Wie verwerflich Eure Aufgabe auch war, es musste einfach getan werden. Jetzt müsst Ihr in das Angesicht des Bösen sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9689] = {title = "Messerrachen", objective = "Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr Messerrachen tötet.", description = "Während der Angriffe wurden viele des schwarzen Drachenschwarms getötet. Einer von ihnen, ein Offizier von Todesschwinge selbst, sucht noch immer diesen Ort heim. Blickt Ihr in den Himmel, so könnt Ihr sein spektrales Antlitz durch die Lüfte kreisen sehen. Sein Hass ist so groß, dass er sogar den Tod übersteht.\n\nNehmt die Knochen, die Ihr bereits für mich eingesammelt habt, zu der Spitze des Berges dieser Insel und platziert sie im ewig brennenden Scheiterhaufen. Dieses Signal sollte Messerrachen herabschweben lassen. Sobald er da ist, tötet sein untotes Abbild.", progress = nil, completion = "Wie lange war es noch? Tausend Jahre? Zehntausend Jahre vielleicht? Ihr habt mir und der Erinnerung meiner Leute einen großen Dienst erwiesen, &lt;Name&gt;. Bitte, nehmt diesen mächtigen Gegenstand als Zeichen der Anerkennung von Loreth'Aran an - für Eure ehrenvollen Taten.", rewards = "Robe des DrachentötersWeste des DrachentötersTunika des DrachentötersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9690] = {title = "Die zweite Prüfung", objective = "Meldet Euch bei Meister Kelerun Blutpein.", description = "Initiand <Name>, Ihr habt hart an Euch gearbeitet, um die Macht des Lichts zu beherrschen, über die wir Dank unserer Magister verfügen. Ihr wisst nun von der Quelle unserer Fähigkeiten und alles über die Pflichten eines Blutritters.\n\nDer Zeitpunkt ist nahe, da Ihr Euch der zweiten Prüfung unterziehen werdet und Ihr um den Rang eines Adepten der Blutritter kämpfen müsst. Die Prüfung findet unter der Aufsicht von Meister Kelerun Blutpein im nördlichen Teil von Silbermond statt. Reist durch die Ruinen von Silbermond nach Norden und nehmt den östlichen Pfad, der kurz vor der Brücke abzweigt, die zur Insel der Sonnenwanderer führt.", progress = nil, completion = "Sobald Ihr bereit seid, werde ich Euch mehr über die bevorstehende Prüfung erzählen. Trefft Eure Vorbereitungen und wenn Ihr beginnen möchtet, sprecht erneut mit mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9691] = {title = "Rückkehr nach Silbermond", objective = "Kehrt zu Ritterfürst Heldenblut nach Silbermond zurück.", description = "Kehrt umgehend nach Silbermond zurück und berichtet Ritterfürst Heldenblut. Eure Ankunft sollte ihm alles Notwendige über den Ausgang der Prüfung mitteilen.\n\nEr wird Euch Eure weiteren Aufgaben auf dem Weg zum Adepten erläutern. Ihr könnt stolz auf Euch sein, <Name>. Viele versuchen sich an dieser Prüfung, doch nur die Wenigsten kehren zurück, um von ihrem Erfolg zu berichten.", progress = nil, completion = "Ich habe immer daran geglaubt, dass Ihr diese Prüfung bestehen würdet, &lt;Name&gt;. Eure verbleibenden Pflichten sind größtenteils zeremonieller Natur und doch sind sie nicht weniger gefährlich, als der Versuch, mit bloßen Fäusten gegen einen unserer Champions zu bestehen. Hört genau hin, was Ihr als Nächstes tun müsst, um Euren neuen Rang zu erlangen.", rewards = "Ihr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9692] = {title = "Der Pfad des Adepten", objective = "Bringt Ritterfürst Heldenblut in Silbermond einen verderbten Koredelstein, eine Kiste mit blutgeschmiedeten Blöcken, etwas Blut des Hasserfüllten und ein Insigne der Blutritter.", description = "Bevor ein frischgebackener Adept in die Ränge der Blutritter aufgenommen wird, muss er die Materialien beschaffen, die zum Schmieden der besonderen Waffe des Ordens benötigt werden: dem blutgehärteten Ranseur.\n\nIhr müsst Euch außerdem das Recht verdienen, das Insigne unseres Ordens zu tragen. Bei der Gründung des Ordens wurde eine begrenzte Zahl dieser Insignien geschmiedet und verteilt, jeder Adept erbt sein Insigne von einem Veteran. Euer Insigne erhaltet Ihr von einem gefallenen Ritter, der einen Angriff auf die Todesfestung anführte.\n\nIch habe Notizen vorbereitet, die Euch helfen sollen.", progress = "Habt Ihr getan, was Euch aufgetragen wurde?", completion = "Sehr gut, &lt;Name&gt;. Es ist alles da. Nun muss nur noch die Waffe geschmiedet werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9693] = {title = "Was Argus für mich bedeutet", objective = "Exarch Admetius bei der Blutwacht wies Euch an, mit Verteidiger Boros zu sprechen.", description = "Was bedeutet Argus für Euch, <Name>? Viele Draenei erinnern sich wahrscheinlich nicht mehr an unseren Heimatplaneten oder kennen ihn überhaupt nicht. Dort trennten wir uns von den Man'ari: unseren verdorbenen dämonischen Abbildern, die von Sargeras 'bedacht' wurden. Sie selbst nennen sich die Eredar.\n\nEredar... dieses Wort hatte einst eine Bedeutung.\n\n<Admetius scheint das Wort förmlich zu schmecken.>\n\nWiderlich.\n\nLasst uns nicht noch mehr Zeit verschwenden. Sucht nach Verteidiger Boros, damit Ihr mit Eurer Ausbildung beginnen könnt.", progress = nil, completion = "Ah, &lt;Name&gt;... ich habe bereits von Euch gehört. Ihr seid also derjenige, der den Korsallauf in unter 15 Minuten gemacht hat. Ts, wahrscheinlich nicht.\n\nSeid Ihr bereit, etwas Blut im Namen des Lichts zu vergießen? Für Velen? Für Argus?\n\n\n\nGut, gut, ich halte mich jetzt besser zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9694] = {title = "Blutwacht", objective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr 10 Spione der Sonnenfalken tötet.", description = "Wie Ihr wisst, ist die Blutwacht einer von zwei Vorposten, die der Hand von Argus als Operationsbasen dienen. Ihr wart bereits bei der anderen Basis, der Azurwacht; die Dinge laufen auf der Blutmythosinsel etwas anders. Als wir hier zu Beginn ankamen, war das Land genauso wunderschön und unberührt wie auf der Azurmythosinsel. Wir nannten es sogar Silberbrise, doch nun breitet sich die Seuche über das Land aus. Was noch schlimmer ist, die Blutelfen, die wir auf der Exodar bekämpften, haben den Absturz überlebt. Somit kommen wir zu Eurem ersten Auftrag: Reist nach Nordwesten zum Messerwinkel und vernichtet alle Blutelfen, die Euch über den Weg laufen.", progress = nil, completion = "Ihr seid zurück - in einem Stück!\n\nIch habe gute Neuigkeiten, &lt;Name&gt;. Wir haben neue Informationen zum wahrscheinlichen Aufenthaltsort weiterer Überlebender erhalten. Eine neue Absturzstelle wurde entdeckt! Sobald ich mich eingehender damit befasst habe, werde ich mich an Euch wenden.", rewards = "Faust von ArgusKlinge von ArgusKreuzfeuer der Hand von ArgusIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9695] = {title = "Die Anweisung des Sonnenkönigs", objective = "Bringt die Anweisung des Sonnenkönigs zu Verteidiger Boros bei der Blutwacht.", description = "Dieses Dokument sieht wichtig aus. Leider wurde es in Thalassisch verfasst; eine Sprache, derer Ihr nicht mächtig seid.\n\nVielleicht weiß Verteidiger Boros, wie man weiter vorgehen könnte.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9696] = {title = "Übersetzungen...", objective = "Bringt das Schreiben der Sonnenfalken zur Vernehmungsbeauftragten Elysia bei der Blutwacht.", description = "Unsere hochrangigste Vernehmungsbeauftragte Elysia spricht fließend Thalassisch. Bringt ihr dieses Dokument, mal sehen, was sie dazu zu sagen hat.", progress = "Ich habe hier etwas viel zu tun, Agent <Name>. Ich hoffe Euer Anliegen ist wichtig.", completion = "&lt;Elysia liest das Dokument.&gt;\n\nWenn wirklich stimmt, was hier steht, dann haben die Blutelfen ein Portal zur Scherbenwelt geöffnet! Das würde auch ihre schier endlose Zahl erklären...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9697] = {title = "Behüterin Leesa'oh", objective = "Sprecht mit Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen.", description = "Es müssen wichtige Forschungen bezüglich der Ökologie der hiesigen Lebewesen betrieben werden, besonders bei den Sporlingen und den Sumpflords der Marschen. Und vertraut mir, wenn Ihr Euch einmal mit diesem Thema befasst habt, werdet Ihr die Arbeit faszinierend finden.\n\nSucht Behüterin Leesa'oh im Wachposten des Cenarius im westlichen Teil der südlichen Marschen. Folgt dem Pfad nach Westen, dann werdet Ihr sie sicher finden. Sie ist manchmal etwas... übereifrig..., aber lasst Euch davon nicht abschrecken.\n\nOh, und hütet Euch vor ihrer Katze.", progress = nil, completion = "Oh, gut... endlich Unterstützung! Es gibt einfach so viel zu tun, und ich muss hierbleiben, um alles zu organisieren.\n\nIch hoffe Ihr seid bereit, Euch die Hände schmutzig zu machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9698] = {title = "Audienz beim Propheten", objective = "Bringt das übersetzte Schreiben der Sonnenfalken zum Propheten Velen bei der Exodar.", description = "Ihr müsst das übersetzte Dokument Velen persönlich überbringen, <Name>. Ich vertraue diesem verstörten Boten nicht.\n\nErklärt dem Propheten, dass die Blutelfen Verstärkung aus der Scherbenwelt erhalten und dass sie einen Spion unter den Draenei bei der Exodar haben. Velen hält sich in der Halle des Lichts in der Exodar auf.\n\nBeeilt Euch!", progress = "<Velen lächelt.>\n\nSeid gegrüßt, <Name>. Ich habe Euch erwartet.", completion = "&lt;Velen beginnt das Dokument zu lesen.&gt;\n\nInteressant... dies erklärt in der Tat einiges.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9699] = {title = "Was ist wahr?", objective = "Bringt Velens Anordnungen zu Verteidiger Boros bei der Blutwacht.", description = "Ich danke Euch für die rasche Zustellung, <Name>. Ihr erweist Euch schließlich als einer der besseren Agenten der Hand.\n\nWenn wir bloß wüssten, wem sie auf der Blutmythosinsel Bericht erstattet haben und noch wichtiger, wo dieses Sonnenportal ist... Sie scheinen es streng zu bewachen - wo immer es auch sein mag.\n\nWärt Ihr an einer Erkundungsmission interessiert?\n\nWenn ja, dann bringt diese Anordnungen zu Verteidiger Boros. Er wird Euch Euren nächsten Auftrag erteilen.", progress = "Ja?", completion = "Es ist ein guter Plan, aber auch ein gefährlicher. Ich bin mir jedoch sicher, dass alles gut verlaufen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9700] = {title = "Licht ins Dunkel bringen", objective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr die Lage des Sonnenportals ausfindig macht und 5 Anomalien der Leere tötet.", description = "Velen erklärt, dass falls die Blutelfen Verbindungen zwischen der Insel und der Scherbenwelt hergestellt haben, Überreste oder Anomalien rund um die geöffneten Portale zurückgelassen wurden. Ihr müsst die Insel nach Gebieten absuchen, in denen diese Anomalien vorkommen.\n\nSeid gewarnt, <Name>, manche dieser Anomalien sind Kreaturen aus der Leere selbst. Solltet Ihr auf Anomalien der Leere treffen, tötet sie! Erstattet mir Bericht, sobald Ihr neue Informationen ausfindig gemacht habt. Beginnt mit Eurer Suche im Norden, nahe der Warpgondel.", progress = nil, completion = "Wie viele sagtet Ihr doch gleich, habt Ihr bei der Warpgondel gesichtet? Wie oft haben sie nur dieses Sonnenportal geöffnet? Das sind sehr schlechte Neuigkeiten...\n\nTja, Ihr habt Euch nun alles von mir angeeignet, was ich Euch lehren kann, &lt;Name&gt;. Kuros wird nach Euch rufen lassen, wenn es an der Zeit ist.", rewards = "Weichbesohlte Schuhe des VerteidigersLedermokassins des VerteidigersStampfer des VerteidigersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9701] = {title = "Sporlinge beobachten", objective = "Untersucht das Pilzgeflecht in den Zangarmarschen und berichtet danach Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen von Euren Beobachtungen.", description = "Wir müssen alles über die Sporlinge von Sporeggar und ihre Beziehung zu den anderen Lebewesen in der Umgebung in Erfahrung bringen. Eine Möglichkeit dazu ist die, die ich anwende: passives Beobachten und ihr Verhalten notieren.\n\nIch möchte, dass Ihr für mich nach Westen in das Pilzgeflecht geht. Untersucht die gesamte Gegend dort und berichtet mir dann davon.", progress = "Schon wieder zurück? Eure Beobachtungen der Sporlinge von Sporeggar sind unverzichtbar für meine Forschungen. Ich hoffe, Ihr seid nicht der Typ, der Dinge gerne überstürzt. Zeigt etwas Geduld und stellt sicher, dass Ihr die gesamte Gegend des Pilzgeflechts untersucht habt, bevor Ihr zu mir zurückkommt.", completion = "Was?! Die Sumpflords des Quaggkamms ESSEN die Sporenkapseln die Sporlinge? Das ist nicht gut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9702] = {title = "Eine Frage der Fressgier", objective = "Sammelt 10 Stück liegengelassene Nahrung und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", description = "Ich habe mich schon gefragt, warum die Sumpflords die Straße überqueren, um in das Pilzgeflecht zu gelangen - sie müssen aus irgendeinem Grund am verhungern sein. Das darf nicht sein!\n\nIch meine, normalerweise würde ich mich nicht einmischen, aber wenn sie weiterhin alle Kapseln essen, werden sie die Sporlinge ausrotten!\n\nHier ist mein Plan: Ich bleibe hier und Ihr geht zum Quaggkamm im Osten und seht Euch nach nahrungstechnischen Gründen um, warum sie die Sporlinge überfallen.", progress = "Stellt sicher, dass Ihr alle Beweise sorgfältig zusammentragt, <Klasse>! Wir fügen hier die Teile eines riesigen Puzzles zusammen. Ein Fehler von Euch könnte zu falschen Schlussfolgerungen führen.\n\nWo stünden wir dann mit unserem Verständnis für die Zangarmarschen?", completion = "Das habt Ihr gefunden? Das ist komisch. Diese vertrockneten Pilzüberreste sind ungewöhnlich und kommen mir irgendwie bekannt vor.\n\nIch muss kurz darüber nachdenken. Geht nicht weg!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9703] = {title = "Der Kryokern", objective = "Verteidiger Kuros bei der Blutwacht möchte, dass Ihr 12 Kisten mit Heilvorräten sichert.", description = "Wir haben noch andere, die nach Spuren suchen, die zu den Sonnenportalen führen, <Name>. Ihr müsst Euch jetzt auf Euren bevorstehenden Einsatz konzentrieren.\n\nBoros erhielt Berichte über eine neue Absturzstelle. Wir haben herausgefunden, dass es sich bei dieser Absturzstelle eigentlich um den Kryokern der Exodar handelt. Eine Transportkammer, in der genau solche Kapseln untergebracht sind wie die, aus denen wir Draenei im Am'mental gekrochen sind.\n\nIn diesem Bereich werden auch Heilvorräte aufbewahrt. Geht zum Kryokern genau westlich der Blutwacht. Sucht nach Vorräten und nach Überlebenden.", progress = "Waren die Informationen korrekt?", completion = "Nur Blutelfen? Keine Überlebenden? Das ist beunruhigend. Ich brauche etwas Zeit zum Nachdenken, &lt;Name&gt;. Vielleicht haben Aesom oder Boros einen Auftrag für Euch.", rewards = "Zerkracher des VerteidigersBrieföffner des VerteidigersWanderstecken des VerteidigersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9704] = {title = "Von den Getriebenen getötet", objective = "Geht nach Süden zu den Ruinen von Silbermond und haltet nach der getöteten Kundschafterin beim Dämmerweg Ausschau.", description = "Es ist ein hartes Stück Arbeit, ein Kundschafter zwischen der Insel der Sonnenwanderer und dem Falkenplatz zu sein. Knappe Zeitvorgaben, lange Arbeitszeiten und noch schlimmer... die Getriebenen!\n\nDie Straße im Süden führt durch die Ruinen von Silbermond... ein Ort, an dem es nur so von Getriebenen wimmelt, die darauf warten, Euch für ein paar Manakristalle töten zu können. Ich glaube, dieses Schicksal hat unsere letzte Kundschafterin ereilt. Wir hatten sie mit einem von Eronas Päckchen entsandt.\n\nWie ich sehe, brennt Ihr bereits darauf, Euch beweisen zu können. Reist zum Dämmerweg und sucht nach Spuren unserer Kundschafterin.", progress = nil, completion = "Die Habseligkeiten der Kundschafterin wurden mit Ausnahme eines Pakets allesamt entwendet. Es scheint der Beschreibung zu entsprechen, die Euch Alarion von Eronas Päckchen gegeben hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9705] = {title = "Bergung des Päckchens", objective = "Kehrt mit Eronas Päckchen zu Kundschafterin Alarion zurück.", description = "Ihr nehmt das Päckchen und stellt noch einmal sicher, dass es wirklich von Magistrix Erona stammt. Alarion würde es sicherlich gerne entgegennehmen.", progress = "Was habt Ihr gefunden, <Name>?", completion = "Beim Sonnenbrunnen! Es ist der dritte Kundschafter, den wir diesen Monat verloren haben.\n\nIch weiß Euren Mut zu schätzen, den Ihr bei Eurer Reise zum Dämmerweg bewiesen habt. Die Wachen müssen diese verdammten Getriebenen besser im Auge behalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9706] = {title = "Galaens Tagebuch - Das Schicksal von Verteidiger Saruan", objective = "Bringt Galaens Tagebuch zu Verteidiger Kuros bei der Blutwacht.", description = "Eure Hände zittern beim Aufheben des Buchs. Kuros muss von dieser Tragödie erfahren. Bringt ihm das Tagebuch.", progress = "Was habt Ihr da, <Name>? Ist das ein Tagebuch?", completion = "&lt;Kuros erbleicht beim Lesen des Tagebuchs und Tränen strömen seine Wangen herab.&gt;\n\nSaruan war mein Meister... mein Lehrer... mein Mentor... Ich nahm seinen Platz im Dreigestirn erst vor Kurzem ein - nachdem wir die Suche nach ihm aufgegeben hatten.\n\n&lt;Kuros' Gesichtsausdruck schlägt in Zorn über.&gt;\n\nMatis...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9707] = {title = "Das Schmieden der Waffe", objective = "Bringt die Kiste mit Rohmaterialien zu Bemarrin in Silbermond.", description = "Wieder habt Ihr Euch als würdig erwiesen, ein Mitglied des Ordens zu sein. Mit großer Freude verleihe ich Euch den Rang des Adepten, <Name>. Prinz Kael'thas selbst wäre stolz auf Euch.\n\nEs ist eine Ehre für uns alle, an Eurer Seite auf dem Schlachtfeld zu kämpfen. Verhaltet Euch weiterhin vorbildlich, zeigt keine Gnade oder Schwäche, verteidigt unermüdlich Euer Volk und Eure Brüder und verfeinert Eure Beherrschung des Lichts.\n\nNun holt Euch die Waffe, die Eurem neuen Rang angemessen ist.", progress = "Ich gratuliere Euch, <Name>. Den Rang des Adepten zu erreichen ist keine leichte Sache, glaubt mir. Ich habe viele Leute dieses Gebäude betreten sehen, und nur wenige halten lange genug durch, um mit diesen Rohmaterialien zu mir zu kommen.", completion = "Sieht aus, als hättet Ihr alles, was ich brauche. Ans Werk!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9708] = {title = "Bekannter Pilz", objective = "Sammelt 15 Pilzproben und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", description = "Ja, das ist es! Ich wusste doch, dass ich diesen Pilzstamm schon woanders in den Marschen gesehen habe!\n\nIm Norden gibt es einen Ort, der Prügelsumpf genannt wird. Komischer Name für einen Sumpf, wenn Ihr mich fragt, aber ich bin noch nie dort gewesen. Ich brauche Proben von diesen Pilzen um meine Theorie zu unterstützen.\n\nAber seid vorsichtig, <Klasse>. Ich habe gehört, dass die Oger in dieser Gegend einmarschiert sind. Ihr müsst also die Proben von ihnen besorgen. Könnte das der Grund sein, warum die Sumpflords dort nicht mehr ihre Nahrung suchen?", progress = "Habt Ihr die Proben schon?", completion = "Die Proben stimmen definitiv überein. Und die Anwesenheit der Oger und was sie dort tun erklärt alles. Jetzt verstehe ich, warum der Ort Prügelsumpf genannt wird.\n\nWir müssen etwas an dieser Situation ändern, aber was? Wir können nicht einfach alle Oger auslöschen, sie haben genauso viel Recht hier zu leben, wie alle anderen Lebewesen in den Marschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9709] = {title = "Die Pilze zurückstehlen", objective = "Sammelt 10 Kisten Pilze und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", description = "<Klasse>, ich habe eine Idee. Ich möchte, dass Ihr Euch wieder nach Norden aufmacht, aber dieses Mal in das Herz des Ogergebiets!\n\nNordwestlich des Prügelsumpfs gibt es einen Ort, der Festung der Ango'rosh genannt wird. Er befindet sich auf einer Insel jenseits einer großen Pilzbrücke. Dort lagern sie bestimmt die geernteten Pilze. Ihr könnt sie sicher überall finden, wahrscheinlich haben die Oger selbst sie sogar in den Taschen!\n\nBringt mir genügend davon, und ich werde versuchen, die Sumpflords mit einer neuen Nahrungsquelle zu versorgen.", progress = "Habt Ihr schon alle Pilze, um einen neuen Garten für die Sumpflords anzulegen?", completion = "Sie sind perfekt! Oh danke, &lt;Klasse&gt;!\n\nIhr wart so darauf bedacht, das natürliche Gefüge nicht aus dem Gleichgewicht zu bringen, und wir haben in so kurzer Zeit so viele Informationen sammeln können!\n\nJetzt wollen wir mal schauen, ob unser kleiner Plan, eine neue Nahrungsquelle für die Sumpflords zu schaffen, funktioniert.", rewards = "ZangarschulterklappenHelm der natürlichen ReinheitGürtel des MarschenüberlebenskünstlersLeesa'ohs GelenkbänderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9710] = {title = "Der blutgehärtete Ranseur", objective = "Wartet, während Bemarrin Eure Waffe schmiedet.", description = "Es ist alles vorbereitet, <Name>. Bald werdet Ihr eine Waffe haben, die Eurem neuen Status angemessen ist.", progress = nil, completion = "Hier ist die Waffe, &lt;Name&gt;. Nutzt sie im Dienst für Silbermond und Euren Orden.", rewards = "Ihr bekommt:\n\nBlutgehärteter Ranseur"}
MultiLanguageQuestData['de'][9711] = {title = "Matis der Grausame", objective = "Verteidiger Kuros bei der Blutwacht möchte, dass Ihr Matis den Grausamen gefangen nehmt.", description = "Matis wird Gerechtigkeit widerfahren, <Name>. Ich möchte, dass Ihr derjenige seid, der ihn findet und ihn zum Dreigestirn zurückbringt.\n\nDurchkämmt die Insel nach diesem Mörder. Solltet Ihr ihn finden, verwendet diese Leuchtpistole. Sobald mein Suchtrupp das Signal sieht, wird man herbeieilen und Euch bei der Gefangennahme von Matis helfen. Kommt anschließend zu mir zurück.", progress = nil, completion = "Das Dreigestirn hat beschlossen, Matis sofort zu verurteilen. Ihr habt heute einen Erzverbrecher der Gerechtigkeit überführt, junger &lt;Volk&gt;.\n\nIhr habt für zwei von dreien außerordentliche Arbeit geleistet, lediglich Aesom fehlt.", rewards = "Wollwäsche des VerteidigersLederbeinschützer des VerteidigersEisenbeinschützer des VerteidigersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9712] = {title = "Das thalassische Schlachtross", objective = "Sprecht mit Ritterfürst Heldenblut, um zu erfahren, wie Ihr Euer thalassisches Schlachtross beschwören könnt.Ihr habt Euch im Dienste des Ordens ausgezeichnet, <Name>. Die Euch durch Magister Astalor und seiner Brüder gewährten Fähigkeiten, die Energien des Lichts zu beherrschen und Eurem Willen nach einzusetzen, und Euer offensichtliches Talent darin, machen Euch alle Ehre. Ihr wurdet für würdig befunden, Euer Wissen noch zu erweitern.\n\nMit dem Licht unter Eurer Kontrolle seid Ihr in der Lage, ein furchterregendes Schlachtross herbeizurufen; ein treues Reittier an Eurer Seite.\n\nDient auch weiterhin so voller Eifer und Ehre, <Name>, und Ihr werdet belohnt werden.Ihr erlernt:\n\n", description = "Ihr habt Euch im Dienste des Ordens ausgezeichnet, <Name>. Die Euch durch Magister Astalor und seiner Brüder gewährten Fähigkeiten, die Energien des Lichts zu beherrschen und Eurem Willen nach einzusetzen, und Euer offensichtliches Talent darin, machen Euch alle Ehre. Ihr wurdet für würdig befunden, Euer Wissen noch zu erweitern.\n\nMit dem Licht unter Eurer Kontrolle seid Ihr in der Lage, ein furchterregendes Schlachtross herbeizurufen; ein treues Reittier an Eurer Seite.\n\nDient auch weiterhin so voller Eifer und Ehre, <Name>, und Ihr werdet belohnt werden.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nSchlachtross beschwören"}
MultiLanguageQuestData['de'][9714] = {title = "Bringt mir ein weiteres Gebüsch!", objective = "Wir können immer noch mehr Bluthibiskus von den Schlurfern, Sumpfriesen und Tiefenfledermäusen im Echsenkessel gebrauchen. Bringt sie mir in Bündeln zu je fünf, und ich werde Euch sehr dankbar sein.", description = nil, progress = "Wir können immer noch mehr Bluthibiskus von den Schlurfern, Sumpfriesen und Tiefenfledermäusen im Echsenkessel gebrauchen. Bringt sie mir in Bündeln zu je fünf, und ich werde Euch sehr dankbar sein.", completion = "Das ist schon mal sehr gut, aber wir können immer noch mehr davon gebrauchen. Vielleicht geht Ihr ja bald mal wieder in den Tiefensumpf?", rewards = nil}
MultiLanguageQuestData['de'][9715] = {title = "Bringt mir ein Gebüsch!", objective = "Sammelt 5 Stück Bluthibiskus und bringt sie zu Gzhun'tt in Sporeggar in den Zangarmarschen.", description = "Wir müssen unsere Vorräte an Bluthibiskus aufstocken, die wir für viele Zwecke brauchen. Früher gab es hier dicke Büsche davon, aber seitdem der Wasserspiegel der Marschen gesunken ist, findet man ihn nur noch im Tiefensumpf und im Echsenkessel, unter dem Schlangensee.\n\nMan sagt, er sei eine Delikatesse für die Schlurfer, Sumpfriesen und die Tiefenfledermaus. Wenn Ihr uns also helfen wollt, müsst Ihr die Blumen von ihnen besorgen.", progress = "Habt Ihr den Hibiskus, um den ich Euch gebeten habe?", completion = "Das ist schon mal sehr gut, aber wir können immer noch mehr davon gebrauchen. Vielleicht geht Ihr ja bald mal wieder in den Tiefensumpf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9716] = {title = "Anomalie am Umbrafennsee", objective = "Untersucht den Grund für die sinkenden Wasserspiegel am Umbrafennsee. Kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", description = "Wir kamen in die Scherbenwelt mit der Erwartung, hier kleine Ansammlungen von Leben zu finden. Doch was wir hier in den Zangarmarschen entdeckt haben, ist eine üppige Landschaft mit einem gedeihenden Ökosystem.\n\nUnsere ursprüngliche Einschätzung der Gegend war dennoch trügerisch. Die Wasserstände der Seen und Marschen sind seit unseren ersten Messungen stetig gesunken.\n\nDies könnte verheerende Auswirkungen auf die Flora und Fauna der Gegend haben. Geht zum Umbrafennsee südwestlich von hier und seht Euch nach möglichen Gründen für das Sinken des Wasserspiegels um.", progress = nil, completion = "Die Naga stecken dahinter! Aber warum? Euren Schilderungen zufolge sind die Dampfpumpen für das Sinken der Wasserspiegel in den Marschen verantwortlich.\n\nEgal - dies erklärt Ihre offensichtliche Feindlichkeit uns gegenüber. Lasst uns keine Zeit verschwenden, Ihr müsst eine weitere Aufgabe für uns erledigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9717] = {title = "Los geht's!", objective = "Besorgt einen Tiefensporenfarn und bringt ihn zu T'shu in Sporeggar in den Zangarmarschen.", description = "Auch wenn wir ein friedliebendes Volk sind, befinden wir uns im Krieg mit den Fungusgiganten, ob uns das gefällt oder nicht. Und es gibt ein Sprichwort bei den Sporlingen, das besagt, dass im Krieg und im Pilz alles erlaubt ist!\n\nEiner der Anführer der Fungusgiganten, Hungarfenn, pflegt seit Jahrtausenden mit Hingabe eine sehr besondere Pflanze, bekannt als die Tiefenspore. Er würde daran zerbrechen, wenn dieser Pflanze etwas zustoßen würde.\n\nReist zum Tiefensumpf im Echsenkessel und stehlt einen Dorn von ihr. Vertraut mir, er wird es bemerken.", progress = "Der Tiefensumpf ist ein sehr gefährlicher Ort. Wenn Ihr Euch scheut, dorthin zu gehen, würde ich Euch nicht als Feigling bezeichnen. Ich wäre allerdings auch alles andere als zufrieden, wenn Ihr mir nicht das brächtet, worum ich gebeten habe.", completion = "&lt;Der Sporling macht ein Geräusch, das fern an ein prustendes Lachen erinnert.&gt;\n\nPerfekt! Die Moral der Fungusgiganten wird sicher ein Rekordtief erreichen, wenn sie sehen, was Ihr getan habt.\n\nEntweder das oder sie werden so erzürnt sein, dass sie uns bald wieder angreifen.\n\n&lt;T'shu zuckt mit den Schultern.&gt;", rewards = "Ihr bekommt:\n\nUnvergänglicher Tiefensporenfarn"}
MultiLanguageQuestData['de'][9718] = {title = "Der Flug der Krähe", objective = "Ysiel Windsänger möchte, dass Ihr das Sturmkrähenamulett benutzt, um die größeren Seen in den Zangarmarschen zu erkunden.", description = "Wir müssen genau herausfinden, wie weit reichend die Aktivität der Naga wirklich ist und entsprechend reagieren.\n\nJedes Wasservorkommen in den Zangarmarschen zu untersuchen wäre ein sehr zeitaufwändiges Unterfangen. Wenn Ihr mir gestattet, werde ich meine Magie benutzen, um Euch in eine Gestalt zu verwandeln, die Euch das Erkunden der Marschen leichter machen wird.\n\nHaltet dieses Amulett über den Balkon in meiner Nähe, wenn Ihr bereit seid. Ich werde Euch zurück in die Sicherheit führen, wenn wir fertig sind.", progress = "Seid gegrüßt, <Name>.", completion = "Es ist so, wie ich dachte. Die Naga haben Pumpstationen an allen größeren Seen in den Zangarmarschen errichtet.\n\nWenn die Marschen weiter existieren sollen, müssen sie aufgehalten werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9719] = {title = "Tötet die Mutter", objective = "Bringt das Gehirn der Schattenmutter zu Khn'nix in Sporeggar in den Zangarmarschen.", description = "Geschichtlich gesehen waren die Marschenläufer die größte Gefahr für mein Volk. Jetzt, da wir mit den Problemen mit den Fungusgiganten zu kämpfen haben, können wir uns keinen weiteren Angriff unserer alten Feinde erlauben.\n\nIhr habt Euch als fähig erwiesen, <Klasse>. Meint Ihr, Ihr könntet zum Tiefensumpf im Echsenkessel reisen und die große Mutter der Marschenläufer, die als Schattenmutter bekannt ist, auslöschen?!\n\nBringt mir ihr Gehirn als Beweis.", progress = "Ihr seid zurück. Heißt das die Schattenmutter ist nicht mehr?", completion = "Die Schattenmutter ist tot! Normalerweise schwelge ich ja nicht in solchen Gemetzeln, aber der Schmerz, den die große Mutter und ihre Brut über Jahrhunderte über mein Volk gebracht haben, ist unaussprechlich.\n\nEs ist schade, dass nun einer ihrer Nachkömmlinge sich verwandeln wird, um ihren Platz einzunehmen, aber das wird Zeit benötigen. So haben wir eine kleine Atempause, und müssen uns eine Zeitlang nicht vor den Marschenläufern fürchten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMit Essenz erfüllter PilzMit Macht erfüllter Pilz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9720] = {title = "Das Gleichgewicht muss erhalten bleiben", objective = "Ysiel Windsänger möchte, dass Ihr die Eisenrankensamenkörner benutzt, um die Dampfpumpensteuerungen am Schlangensee, Umbrafennsee, Sumpflichtsee und der Lagune zu zerstören. Kehrt danach mit den übrigen Samen zu ihr in die Zuflucht des Cenarius in den Zangarmarschen zurück.", description = "Ich kann nicht verstehen, warum die Naga ihren eigenen Lebensraum entwässern wollen. Ich weiß aber sicher, dass wir sie aufhalten müssen.\n\nDiese Samen tragen die Wut der Erde in sich. Bringt sie zu den Dampfpumpen, die von den Naga betrieben werden, und benutzt sie bei den Steuerungen.\n\nDie Ranken, die aus den Samen wachsen, werden so dick wie Euer Arm und so stark wie Eisen sein, <Name>. Stellt das Gleichgewicht wieder her, das die Naga zerstört haben.", progress = "Schon fertig, <Klasse>?", completion = "Es ist also vollbracht. Die Marschen sind vorerst gerettet.\n\nGlaubt aber nicht, dass wir zum letzten Mal von den Naga gehört haben. Wir müssen unseren Feind im Auge behalten, während wir unsere Mission in der Scherbenwelt fortsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9721] = {title = "Aufforderung von Lord Solanar", objective = "Sprecht mit Lord Solanar Blutzorn in Silbermond.", description = "Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lord Solanar Blutzorn, Lady Liadrins rechte Hand und verdienter Held, Eure Gegenwart.\n\nDas ist eine seltene Ehre, <Name>. Normalerweise überlässt Lord Solanar mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint er ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, <Name>.", progress = nil, completion = "Wir werden den Grund Eures Besuchs noch früh genug besprechen. Doch zunächst muss ich feststellen, dass mich Eure bisherigen Leistungen und Euer Geschick in der Beherrschung des Lichts sehr beeindruckt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9722] = {title = "Der Pfad des Meisters", objective = "Sprecht nochmals mit Lord Solanar Blutzorn, um seine angebotene Unterstützung für Eure Aufnahme zu akzeptieren.", description = "Innerhalb meines Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.\n\nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.\n\nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.", progress = nil, completion = "Dass Ihr Euch entschlossen habt, mein Angebot zu akzeptieren, spricht für Euch, &lt;Name&gt;. Ich wünsche Euch viel Glück, bei den von mir festzulegenden Prüfungen, doch bin ich zuversichtlich, dass Ihr sie alle meistern werdet.\n\nIch werde Euch die Aufgaben in der Reihenfolge ihrer Schwierigkeit, von der Leichtesten bis zur Schwersten, erteilen. Wir können beginnen, sobald Ihr bereit seid.", rewards = nil}
MultiLanguageQuestData['de'][9723] = {title = "Eine Geste der Hingabe", objective = "Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lord Solanar Blutzorn in Silbermond.", description = "Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, <Name>. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.\n\nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.", progress = "Habt Ihr die von Magister Astalor benötigten Materialien bei Euch?", completion = "Hervorragend. Es sieht so aus, als sei alles da.\n\nKeine Sorge, im Laufe Eurer nächsten Aufgabe habt Ihr noch oft genug die Möglichkeit, von Eurer Waffe Gebrauch zu machen, versprochen!\n\nIch werde einen Initianden losschicken, um alles zu Magister Astalor zu bringen. Es wäre Verschwendung, Euch mit einem solch trivialen Botengang zu betrauen, wenn wesentlich wichtigere Dinge auf ihre Erledigung warten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9724] = {title = "Warnung an den Zirkel des Cenarius", objective = "Sprecht mit Amythiel Nebelgänger beim Posten des Cenarius auf der Höllenfeuerhalbinsel.", description = "Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.\n\nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.", progress = nil, completion = "Das sind schlimme Nachrichten, die Ihr mir über die Naga in den Zangarmarschen bringt. Es war sehr klug von Ysiel, uns darüber zu informieren. Sie hat nicht vergessen, dass die Expedition nicht ohne die Unterstützung des Zirkels existieren kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9725] = {title = "Eine Demonstration Eurer Loyalität", objective = "Lord Solanar Blutzorn in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.", description = "Wir Blutritter haben geschworen, Quel'Thalas zu verteidigen, <Name>. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.\n\nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den Östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.", progress = nil, completion = "Ihr habt Loyalität gegenüber Eurer Heimat und Eure Aufopferungsbereitschaft für die Ziele des Ordens bewiesen, &lt;Name&gt;. Ich habe noch eine letzte Aufgabe für Euch, bevor Ihr den Titel eines Meisters für Euch beanspruchen dürft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9726] = {title = "Jetzt, da wir Freunde sind...", objective = "Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück.", description = "Die Naga in der Enklave der Blutschuppen im Nordosten haben angefangen, unsere Leute umzubringen. Das können wir nicht tolerieren, <Klasse>!\n\nWir schlagen vor, dass Ihr ihnen als Beweis für unsere Freundschaft eine Lektion erteilt.", progress = "Habt Ihr den Naga schon einen Besuch abgestattet?", completion = "&lt;Gzhun'tt nickt Euch zu.&gt;\n\nWir sind sehr erfreut, dass Ihr unsere Freundschaft bestätigt habt, &lt;Name&gt;. Vielleicht denken die heidnischen Naga in Zukunft zweimal darüber nach, bevor sie uns belästigen, wenn wir so einen starken Verbündeten haben.", rewards = "Stab der WildnisHammer der SporlingePike des ÜberlebenskünstlersClaymore der ZangarmarschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9727] = {title = "Jetzt, da wir immer noch Freunde sind...", objective = "Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück.", description = "Berichten zufolge töten die Naga bei der Enklave der Blutschuppen immer noch unsere Leute. Ich dachte, Ihr hättet Euch darum gekümmert, <Klasse>!\n\nIch schlage vor, dass Ihr ihnen als Beweis für unsere andauernde Freundschaft eine Lektion erteilt.", progress = "Habt Ihr den Naga schon einen Besuch abgestattet?", completion = "&lt;Gzhun'tt nickt Euch zu.&gt;\n\nWir sind sehr erfreut, dass Ihr unsere Freundschaft erneut bestätigt habt, &lt;Name&gt;. Sicherlich werden die sinnlosen Angriffe auf unser Volk jetzt, da Ihr unseren Standpunkt mehrfach klar gemacht habt, aufhören.", rewards = nil}
MultiLanguageQuestData['de'][9728] = {title = "Ein herzliches Willkommen", objective = "Bringt 30 Nagaklauen zu Aufseher Hamuht in der Zuflucht des Cenarius.", description = "Während die Druiden der Expedition damit beschäftigt waren die Pflanzen und Seen hier zu untersuchen, habe ich es zu meiner Aufgabe gemacht, mich mit den Feinden in dieser Umgebung auseinanderzusetzen.\n\nVom ersten Moment an, als wir die Zangarmarschen betreten haben, haben die Naga uns ohne Vorwarnung angegriffen. Wir haben unser Bestes getan, um sie fern zu halten, aber unsere Mittel sind begrenzt.\n\nIch möchte, dass Ihr zu den verschiedenen Lagern der Naga in den Zangarmarschen geht und ihnen zeigt, dass man sich besser nicht mit uns anlegt. Bringt mir ihre Klauen als Beweis Eurer Siege.", progress = "Schön Euch wieder zu sehen, <Name>. Wie läuft die Jagd nach den Naga?", completion = "Gut gemacht, &lt;Name&gt;. Beruhigt Eurer schlechtes Gewissen, falls Ihr eines haben solltet. Diese Naga sind böse Kreaturen - noch viel böser als die in Azeroth.", rewards = "Ihr bekommt:\n\nFlüchtiger Heiltrank"}
MultiLanguageQuestData['de'][9729] = {title = "Fhwoor zerschmettern!", objective = "Begleitet Fwoohr in das Gebiet bei der Dampfpumpe am Sumpflichtsee, um die Lade von Ssslith zu holen. Bringt Fhwoor und die Lade sicher zurück und meldet Euch bei Gzhun'tt in Sporeggar in den Zangarmarschen.", description = "Kleine Naga machen Fhwoor wütend! Sporlinge gute Freunde von Fhwoor, darum Fhwoor holt Lade von Naga.\n\nWir gehen in nahes Nagadorf. Du helfen?", progress = nil, completion = "Fhwoor ist ein guter Riese. Wir haben ihn vor einer Weile vor den Naga gerettet und seitdem ist er hier und hilft uns.\n\nWir können nur hoffen, dass die Naga den Hinweis verstehen. Wenn wir in der Lage sind, uns in ihr Dorf einzuschleichen und ihren wertvollsten Besitz zu rauben, können wir noch viel Schlimmeres tun. Vielleicht gehen sie jetzt zurück in ihren Kessel und lassen uns in Ruhe.", rewards = "Zerkracher von SporeggarKeilaxt der MarschenSporlingklaueIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9730] = {title = "Anführer der Dunkelkämme", objective = "Tötet Rajah Haghazed bei der Lagune und kehrt danach zu Aufseher Hamuht bei der Expedition des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.", description = "Hiermit wird von der Expedition des Cenarius ein Kopfgeld auf Rajah Haghazed, Anführer der Dunkelkämme, ausgesetzt. Haghazed wurde zuletzt von den Spähern des Cenarius südlich der Lagune gesichtet, mitten im Süden der Zangarmarschen.\n\nDie Dunkelkämme werden mit einer Reihe von Angriffen auf die Expedition des Cenarius in Verbindung gebracht, und ihr Anführer gilt als sehr gefährlich.\n\nDas Kopfgeld kann bei Aufseher Hamuht eingefordert werden.", progress = nil, completion = "Ich mochte schon die Naga in Azeroth nicht, aber die hier mag ich noch viel weniger. Es ist eine Schande, dass unsere Mission nicht friedvoll verlaufen konnte, aber Ihr werdet mich niemals auch nur eine Träne für einen Naga vergießen sehen.\n\nHier ist Eure Belohnung, &lt;Name&gt;.", rewards = "Mantelung der ExpeditionFeste cenarische UmgürtelungSchnelle cenarische StiefelBequeme cenarische LaufschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9731] = {title = "Kanalisationspläne", objective = "Durchsucht den Grund des Schlangensees nach einem Ablauf. Kehrt mit Neuigkeiten über Eure Entdeckung zu Ysiel Windsänger in der Zuflucht des Cenarius zurück.", description = "Die Pläne, die Ihr bekommen habt, zeigen ein unterirdisches System von Rohren und Pumpen, die die Seen in der Umgebung mit dem Schlangensee verbinden.\n\nWenn die Pläne korrekt sind, muss es einen riesigen Ablauf am Grund des Schlangensees geben. Bestätigt dies und bringt die Neuigkeiten zur Zuflucht des Cenarius.", progress = "Welche Neuigkeiten bringt Ihr, <Name>?", completion = "Die Naga haben den Schlangensee in einen riesigen Wasserablauf für den Rest der Zangarmarschen verwandelt. Was haben sie wohl vor?\n\nEs war eine kluge Entscheidung, uns diese Neuigkeiten mitzuteilen, &lt;Name&gt;. Wir werden eine Gruppe losschicken, um den Ablauf, den Ihr gefunden habt, zu untersuchen. Bis dahin habe ich eine andere Aufgabe für Euch.", rewards = "Behüterumhang der WachsamkeitAuf Euch wartet eine dieser Belohnungen:\n\nZauberband der ExpeditionAnhänger der MarschenAufseherring der Präzision\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9732] = {title = "Rückkehr in die Marschen", objective = "Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", description = "Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.\n\nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.", progress = nil, completion = "Euer Anblick ist mir sehr willkommen, &lt;Name&gt;. Die Lage in der Zuflucht des Cenarius hat sich verschlechtert, seit Ihr fortgegangen seid.", rewards = "Schiftung des MarschenschreitersStulpen des WindrufersExpeditionsstiefel des CenariusIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9733] = {title = "Warnung an den Zirkel des Cenarius", objective = "Sprecht mit Mahuram Starkhuf in Thrallmar auf der Höllenfeuerhalbinsel.Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.\n\nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.\n\nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9734] = {title = "Rückkehr in die Marschen", objective = "Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.\n\nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.\n\nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Schiftung des MarschenschreitersStulpen des WindrufersExpeditionsstiefel des CenariusIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9735] = {title = "Wahre Meister des Lichts", objective = "Bringt Lord Solanar Blutzorn in Silbermond eine Phiole Weihwasser von Tyrs Hand.", description = "Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten das Licht auf eine Art zu nutzen und zu formen, wie es die sogenannten anderen 'Paladine' nie verstehen werden. Das hält sie jedoch nicht davon ab, uns dafür zu ächten, wie wir das wahre Potenzial des Lichts entfesseln.\n\nWir müssen ihnen klar machen, dass man mit unseresgleichen keine Spielchen spielt. Was ich mir vorgestellt habe, ist keine schnelle Angelegenheit und auch nicht einfach, doch wenn Ihr Euch dieser Aufgabe verpflichtet, wird es Euer erstes Ziel sein, den Bibliotheksflügel der Abtei von Tyrs Hand zu infiltrieren und eine Phiole heiligen Wassers von Tyrs Hand an Euch zu bringen.", progress = "Habt Ihr das Wasser bekommen?", completion = "Hmm... das ist eine recht kleine Menge, doch wenn wir vorsichtig vorgehen, sollte es ausreichen. Seht Ihr, der Scharlachrote Kreuzzug behauptet von sich noch immer, dem Licht zu dienen. Ich nehme an, dass sie das auch auf eine recht verdrehte Art und Weise noch immer tun, und genau diesen Umstand möchte ich ausnutzen.\n\nIhr fehlgeleiteter Eifer hat selbst den Segen dieses Wassers korrumpiert und das macht es ideal für meine Zwecke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9736] = {title = "Wahre Meister des Lichts", objective = "Bringt Lord Solanar Blutzorn in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten.", description = "Jetzt, da wir das Wasser haben, benötigen wir eine Reihe von Zutaten in genau abgestimmten Mengen. Einige dieser Substanzen sind äußerst selten und wertvoll, <Name>, doch ich habe Quellen für zwei von ihnen ausfindig gemacht.\n\nIhr solltet einige arkane Katalysatoren bei Zalle, dem Reagenzienverkäufer in einem der Geschäfte auf dem Platz nahe der Todesschneise, bekommen. Darlia, die Giftlieferantin nahe den Schurkenausbildern in der Mördergasse, sollte über einen Vorrat an krepuskularem Pulver verfügen.\n\nUm meine Mixtur zu vervollständigen, benötige ich außerdem noch einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.", progress = "Habt Ihr die von mir benötigten Zutaten bekommen?", completion = "Jetzt, wo wir über alle Zutaten verfügen, kann ich die Mixtur vorbereiten.\n\n&lt;Ein Lächeln breitet sich langsam über Lord Solanars Gesicht aus.&gt;\n\nAlles entwickelt sich perfekt, &lt;Name&gt;. Sobald ich hier fertig bin, werde ich Euch unseren letzten Schritt ausführlich erläutern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9737] = {title = "Wahre Meister des Lichts", objective = "Verwendet die Löschmischung in der Nähe der ewigen Flamme in der Alonsuskapelle, um den Schutz des Lichts zu brechen. Seid bereit, jeden zu töten, der versucht, die Kapelle zu verteidigen.", description = "Der einzig wahre Weg, das Licht zu nutzen, ist der unsrige, <Name>. Um denen, die sich schändlicherweise 'Paladine' nennen, die Torheit ihrer Tradition zu verdeutlichen, habe ich vor, ihnen eine unmissverständliche Nachricht zukommen zu lassen.\n\nDie Alonsuskapelle, der Ort, an dem der Orden der Silbernen Hand seinen Anfang nahm, scheint gegen die Zerstörung in Stratholme immun zu sein. Die ewige Flamme der Kapelle gewährt ihr den Schutz des Lichts, doch wenn Ihr sie mit der Löschmischung erstickt, ist es aus mit dem Schutz. Die Kapelle wird brennen und die Welt wird unsere Vorherrschaft über das Licht anerkennen müssen.", progress = "Habt Ihr meine Anweisungen befolgt und die Botschaft überbracht? Die falschen Paladine dieser Welt sollten wissen, dass ihre Zeit auf dieser Welt vorbei ist.", completion = "Gut gemacht, &lt;Name&gt;. Alle, die sich uns widersetzen, würden gut daran tun, die von Euch überbrachte Warnung zu beherzigen. Vom niedersten Fußsoldaten bis zum mächtigsten Helden sollten unsere Feinde nun verstanden haben, dass sie in Gefahr sind.\n\nIhr habt Euren Platz unter den Meistern redlich verdient. Eure Aufopferung und Euer Heldenmut sind ein leuchtendes Vorbild für alle Blutritter. Als ein Symbol Eures neuen Ranges, gewähre ich Euch die Fähigkeit, ein thalassisches Kriegsross zu beschwören und zu beherrschen.", rewards = "Ihr erlernt:\n\nThalassisches Streitross beschwören\n\nIhr bekommt außerdem:\n\nWappenrock der Blutritter"}
MultiLanguageQuestData['de'][9738] = {title = "Bei der Arbeit verschollen", objective = "Findet heraus, was mit Erdbinder Rayge, Naturalist Biss, Jäter Gründaum und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang im Echsenkessel in den Zangarmarschen zurück.", description = "Ihr müsst mir helfen! Wir wurden von Ysiel hierher geschickt, um das Geheimnis der Dampfpumpen zu erkunden und herauszufinden, warum mit ihrer Hilfe das Wasser aus den Marschen gepumpt wird. Aber meine Freunde haben sich von mir getrennt und sind einfach ohne mich weitergegangen.\n\nDie vier können manchmal solche Dummköpfe sein! Aber ich mag sie trotzdem.\n\nDeshalb müsst Ihr mir helfen herauszufinden, was aus ihnen geworden ist, denn ich befürchte das Schlimmste. Sucht sie in den Sklavenunterkünften und im Tiefensumpf.\n\nVielen Dank, <Klasse>.", progress = "Habt Ihr schon herausgefunden, was mit meinen Freunden passiert ist?", completion = "Ich bin froh, dass einige meiner Freunde noch am Leben sind, aber es bricht mir das Herz zu hören, was den anderen widerfahren ist. &lt;seufz&gt;\n\nImmerhin starben sie bei etwas, was sie mehr als alles andere im Leben liebten. Ich bin Euch auf ewig dankbar für Eure Hilfe, &lt;Name&gt;.\n\nBitte nehmt einen dieser Gegenstände als Zeichen meiner Dankbarkeit.", rewards = "Dunkler Umhang der MarschenGoldrankenwickeltücherAuf Euch wartet eine dieser Belohnungen:\n\nCenarischer Ring des Zauberwirkens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9739] = {title = "Die Misere der Sporlinge", objective = "Fahssn im Pilzgeflecht möchte, dass Ihr 10 reife Sporenbeutel sammelt.", description = "Ihr da! Ihr müsst uns helfen!\n\nDie Sumpflords fressen all unsere Sporenbeutel! Ihr müsst etwas tun, sonst verlieren wir unsere Jungen!\n\nDie Sporenbeutel sind zu Anfang ganz groß und werden dann kleiner, wenn die Luft darin verbraucht ist. Haltet nach den kleinen, reifen Sporenbeuteln Ausschau und rettet so viele Ihr nur könnt!", progress = "Die Sporenbeutel! Habt Ihr sie?", completion = "Ihr habt es geschafft! Ihr habt den Dank meines Volkes.\n\nIch hoffe Ihr versteht... daraus entstehen unsere Jungen. Wir können diese Biester sie nicht einfach fressen lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9740] = {title = "Das Sonnentor", objective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr das Sonnentor zerstört.", description = "Dank Euch und Eurer Bemühungen konnten meine Späher das Sonnentor ausfindig machen. Die Elfen sorgen dafür, dass der Standort des Portals stets mobil bleibt und jederzeit verändert werden kann. Deshalb war die Stelle, die Ihr untersucht habt, auch verlassen.\n\nDie Stärke eines solchen Systems ist ebenfalls seine größte Schwäche. Das Sonnentor wird von Portalaufsehern aufrechterhalten. Wenn es uns gelingt, die Aufseher auszuschalten, werden wir das Portal zerstören können. Der momentane Standort des Sonnentors liegt westlich von hier, südlich der Vektorspule. Findet und zerstört es!", progress = nil, completion = "Fabelhaft! Wir haben ihre Versorgungszufuhr durchtrennt. Jetzt müssen wir sie nur noch kaltmachen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9741] = {title = "Geschöpfe aus der Leere", objective = "Tötet 12 Geschöpfe der Leere und erstattet Verteidiger Aesom bei der Blutwacht Bericht.", description = "Aesom hat meine Truppe vor ein paar Tagen auf eine Erkundungsmission geschickt, um nach dem Sonnentor zu suchen. Natürlich haben wir es gefunden...\n\n<Loryi zeigt auf Jorli.>\n\nWas auch immer die Elfen durch dieses Portal transportieren, es sorgt dafür, dass Energien der Leere freigesetzt werden. Die Gegend füllt sich mit Geschöpfen der Leere. \n\nWir müssen sie vernichten, bevor sie sich in Anomalien der Leere verwandeln. Ihr findet die Geschöpfe südwestlich von hier, nahe des Sonnentors. Tötet sie und erstattet Aesom Bericht, sobald Eure Arbeit getan ist.", progress = nil, completion = "Dort herrscht ein ganz schönes Durcheinander, was? Gute Arbeit, &lt;Name&gt;. Ich werde ein paar Anachoreten entsenden, die Loryi und Jorli helfen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9742] = {title = "Noch ein paar Sporensäcke", objective = "Habt Ihr noch mehr Sporensäcke gerettet, <Volk>?", description = nil, progress = "Habt Ihr noch mehr Sporensäcke gerettet, <Volk>?", completion = "Ja! Ihr habt noch mehr Sporensäcke gerettet.\n\nIhr seid anders als die anderen von außerhalb. Ich werde mein Volk von Euren Taten erzählen!\n\n&lt;Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Freundlich' erlangt habt.&gt;", rewards = nil}
MultiLanguageQuestData['de'][9743] = {title = "Natürliche Feinde", objective = "Bringt 6 Sumpflordranken zu Fahssn im Pilzgeflecht in den Zangarmarschen.", description = "Wir Sporlinge kamen noch nie gut mit den Sumpflords aus. In der Vergangenheit haben wir sie mit Speeren und Steinen erfolgreich fernhalten können. Aber in der letzten Zeit scheinen sie aggressiver geworden zu sein... oder verzweifelter. Sie haben keine Angst vor uns oder unseren Waffen.\n\nIhr seid viel Furcht einflößender und besser bewaffnet als wir. Wenn Ihr die Sumpflords für uns bekämpfen könntet, stünden wir für immer in Eurer Schuld! Bringt mir ihre Ranken, damit ich weiß, wie viele Ihr getötet habt.", progress = "Wie geht es mit dem Töten der Sumpflords voran? Zeigt diesen Wüstlingen, dass sie besser nicht in Sporlingsgebiet kommen sollen!", completion = "Ihr seid heil zurück! Ich werde den anderen Sporlingen von Euch erzählen! &lt;Name&gt;, der Riesentöter!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9744] = {title = "Mehr Ranken!", objective = "Ihr habt viele Riesen getötet, aber es sind immer noch viele übrig. Und sie greifen immer noch unsere Sporenbeutel an!", description = nil, progress = "Ihr habt viele Riesen getötet, aber es sind immer noch viele übrig. Und sie greifen immer noch unsere Sporenbeutel an!", completion = "Unglaublich! Es würde hunderte von Sporlingen brauchen um so viele Riesen zu töten wie Ihr. Ich werde ganz bestimmt allen von Euren Heldentaten erzählen!\n\n&lt;Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Freundlich' erlangt habt.&gt;", rewards = nil}
MultiLanguageQuestData['de'][9746] = {title = "Grenze der Erschöpfung", objective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr 10 Pyromanten der Sonnenfalken und 10 Verteidiger der Sonnenfalken tötet.", description = "Der Sieg ist zum Greifen nah, <Name>. Jetzt, da wir das Sonnentor entdeckt haben, wird es nicht lange dauern, bis ihre Versorgungszufuhr total unterbrochen ist. Es ist an der Zeit ihre Zahl auszudünnen.\n\nIm Westen könnt Ihr zahlreiche Lager der Sonnenfalken finden. Die Pyromanten und Verteidiger der Sonnenfalken belagern den größten Teil der Gegend. Findet sie, tötet sie und kehrt zu mir zurück.", progress = nil, completion = "Dies wird ihre Verteidigung ganz sicher geschwächt haben. Ab sofort werden sie es sich zweimal überlegen, bevor sie uns kopflos überfallen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9747] = {title = "Der Umbrafennstamm", objective = "Ikeyen in der Zuflucht des Cenarius möchte, dass Ihr nach Umbrafenn reist und Kataru, 8 Seher von Umbrafenn, 6 Hexendoktoren von Umbrafenn und 6 Orakel von Umbrafenn tötet.", description = "Die Naga sind furchtbar, ja. Aber noch schlimmer sind die verräterischen Stämme der Zerschlagenen und der Verirrten, die ihnen geholfen haben!\n\nDie schlimmsten von allen sind die Verirrten des Umbrafennstamms. Sie benutzen dunkle Magie, um andere zu fangen und zu versklaven. Sie sind besonders grausam zu entflohenen Sklaven und würden mir die Kehle durchschneiden, wenn ich die Zuflucht auch nur für einen Tag verlassen würde.\n\nReist nach Umbrafenn im Süden und tötet sie und ihren Anführer, Kataru. Bis dahin werde ich jeden Tag um mein Leben bangen.", progress = nil, completion = "Danke, &lt;Name&gt;. Endlich werde ich nachts ruhig schlafen können. Wäre ich nicht so alt und schwach, würde ich mich selbst mit meinen Feinden auseinandersetzen.\n\nNehmt dieses Gold. Es ist nicht viel, aber Eure Freundlichkeit darf nicht unbelohnt bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9748] = {title = "Trinkt nicht das Wasser", objective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr den Wasserprobenbehälter verwendet, um eine Wasserprobe der Blutmythosinsel zu entnehmen.", description = "Unser Schamane bekundet, dass die Wasserelemente durch die Verschmutzung der Wasserquelle sehr stark aus dem Gleichgewicht geraten sind. Wir wissen, dass der Kraftkern der Exodar im westlich gelegenen Berg liegt. Offenbar entweicht von dort eine flüchtige Substanz in die Wasserzufuhr! Ihr müsst für mich mehr Informationen sammeln.\n\n<Aesom deutet auf einen Behälter und nickt.>\n\nNehmt diesen Behälter und folgt dem Strand Richtung Norden bis Ihr auf den Punkt trefft, an dem die Flüsse der Blutmythosinsel in das Meer fließen. Entnehmt an dieser Stelle eine Probe und kehrt zu mir zurück.", progress = "Trinkt nicht das Wasser, <Name>!", completion = "Wie ich vermutet habe, ist das Wasser von der Verseuchung durch die austretende Kernflüssigkeit rot geworden.\n\nIch hoffe, dass Ihr nicht in dem verseuchten Wasser geschwommen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9749] = {title = "Sie leben! Vielleicht...", objective = "Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.", description = "Es war ein blutiges Gemetzel, <Name>. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.\n\nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!\n\nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?\n\nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9750] = {title = "UNUSED Urgent Delivery", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][9751] = {title = "Das Vermächtnis des Blutfluchs", objective = "Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.", description = "Letzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.\n\nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich der Blutwacht liegt, suchen?", progress = nil, completion = "Habt Ihr von dem Blutfluch gehört, Landratte? Nein, natürlich nicht. Der Blutfluch ist das, was all diese Schiffe hat sinken lassen. Der verderbte, entweihte Teil des Wassers hier wird Riff des Blutfluchs genannt - ein Teil der Welt, den Ihr niemals sehen möchtet. Ich bin hier selbst seit 20 Jahren.\n\nSkorbut, so ein Quatsch! Ich starb an diesen wilden Ufern als Drachenfutter... Ah, das ist wieder eine andere Geschichte, für ein anderes Mal. Jetzt müssen wir den armen Seelen helfen, die hier im Riff gefangen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9752] = {title = "Flucht aus Umbrafenn", objective = "Begleitet Kayra Langmähne zur Zuflucht des Cenarius in den Zangarmarschen. Gebt Ysiel Windsänger Bescheid, sobald Ihr diese Aufgabe erledigt habt.", description = "Ihr müsst mir helfen hier rauszukommen!\n\nIch habe in der Nähe Kräuter gesammelt, als ein paar dieser Wilden mich entführten. Ich habe versucht mich loszureißen, aber es waren zu viele.\n\nHelft mir zurück zur Zuflucht des Cenarius und weg von diesen grausamen Schuften und ihrer bösen Magie zu gelangen!", progress = nil, completion = "Ihr habt einen meiner Druiden gerettet. Das könnten wir Euch niemals zurückzahlen, &lt;Name&gt;.\n\nIhr habt meinen Dank sowie den Dank der Expedition.", rewards = "Gamaschen des ForschersAufseherhammerAuf Euch wartet eine dieser Belohnungen:\n\nMedaillon des Bewahrers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9753] = {title = "Was wir wissen...", objective = "Sprecht mit Exarch Admetius bei der Blutwacht.", description = "Wir haben in den vergangenen Tagen viel über unsere Feinde gelernt. Die Blutelfen werden von einer gewissen Sironas angeführt und haben vor, uns zu zerstören. Letztendlich wollen sie noch O'ros versklaven und wieder die Kontrolle über die Exodar gewinnen.\n\nDem Licht sei Dank, konnten wir ihre Versorgungszufuhr abschneiden, indem wir das Sonnentor zerstörten. Sie verwenden jedoch die Verunreinigung der Vektorspule, um das Land zu vergiften, und nutzen somit dessen mutagene Eigenschaften zu ihrem Vorteil.\n\nAdmetius hat auf Grund dieser Informationen einen Plan ausgeklügelt. Geht zu ihm.", progress = nil, completion = "Ich brauche Eure Hilfe, &lt;Name&gt;. Es ist mein Plan, die gesamte Armee der Sonnenfalken zu stürzen. Zuvor gilt es jedoch ein paar grundlegende Informationen zu sammeln.\n\nWir müssen die Schwäche ihrer Verteidigung ausmachen. Unglücklicherweise ist es uns bis jetzt noch nicht gelungen, nahe genug an die Vektorspule heranzukommen und ihre Verteidigung auszukundschaften. Wenn wir den Gefangenen zum Sprechen bringen könnten, würden wir womöglich die Informationen bekommen, die wir brauchen, um durch ihre Verteidigung zu brechen und die Vektorspule zu zerstören.\n\nIhr habt richtig gehört, ich will das verdammte Ding in die Luft jagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9756] = {title = "Was wir nicht wissen...", objective = "Sprecht mit einem gefangenen Agenten der Sonnenfalken bei der Blutwacht und eignet Euch Informationen der Sonnenfalken an. Kehrt zu Exarch Admetius zurück, sobald Ihr Eure Aufgabe erfüllt habt.", description = "Unsere Vernehmungsversuche sind kläglich gescheitert, <Name>. Folter kommt - natürlich - nicht in Frage. Was wir brauchen, ist <ein/eine:r> <Volk>, <der/die:r> an ihn herankommen kann.\n\nIch kann einen Zauber auf Euch wirken, der Euch wie <einen Blutelfen/eine Blutelfe> aussehen lässt und Eure Sprache anpasst. Mit dieser List werden wir vielleicht die benötigten Informationen von dem gefangenen Agenten bekommen.\n\nIch möchte, dass Ihr Euch mithilfe dieser Verkleidung das Wissen des Gefangenen erschleicht.\n\nUnd <Name>, verlasst die Blutwacht nicht, solange Ihr verkleidet seid, da sonst der Zauber aufgehoben wird.", progress = "Kehrt erst wieder zurück, wenn Ihr erfolgreich gewesen seid!", completion = "A-ha! Gut gemacht, &lt;Name&gt;. Wirklich sehr gut gemacht. Seid Ihr bereit der Blutelfenbedrohung unserer Insel nun endlich ein Ende zu bereiten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9757] = {title = "Sucht Jägerin Kella Nachtbogen auf", objective = "Sprecht mit Jägerin Kella Nachtbogen nahe Valaars Steg.", description = "Jägerin Kella Nachtbogen hat um eine Audienz mit allen qualifizierten Jägern gebeten. Sie lehrt das Zähmen von wilden Tieren, etwas, das Ihr vor allem anderen zum jetzigen Zeitpunkt Eurer Ausbildung lernen solltet.\n\nIhr findet Kella in der Nähe von Valaars Steg, den Docks westlich der Exodar.", progress = nil, completion = "Lasst uns sofort mit der Ausbildung beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9758] = {title = "Rückkehr zu Arkanist Vandril", objective = "Kehrt zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", description = "Nun, <mein Freund/meine Freundin>, wenn Ihr so nett wärt, zu Arkanist Vandril zurückzukehren? Ich weiß, er ist begierig, Euch auf Eure erste Mission hier in den Geisterlanden zu senden.\n\nWir zählen auf Euch, <Name>. Enttäuscht uns nicht.", progress = nil, completion = "Ah, gut, da seid Ihr ja. Und gerade zur rechten Zeit, es gibt viel zu tun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9759] = {title = "Ihre Welt enden lassen", objective = "Folgt und beschützt Demolierer Legoso, während er versucht, die Vektorspule zu zerstören und tötet Sironas. Kehrt zu Exarch Admetius bei der Blutwacht zurück, sobald Ihr Eure Aufgabe erfüllt habt.", description = "Nehmt diesen Auftrag nicht an, wenn Euch etwas an Eurem Leben liegt. Seht Ihr den gigantischen Kraftkern, der aus der Seite des Bergs dort drüben hervorragt? Wer auch immer diese Last auf sich nehmen möchte, muss sich seinen Weg durch den Berg kämpfen und eine Armee der Sonnenfalken abwehren, um mich zu beschützen, während ich die Zerstörung des Kerns vorbereite. Sironas der Eredar ist auch irgendwo dort oben.\n\nIch werde Euch nicht weniger schätzen, wenn Ihr jetzt einfach geht, <Name>.\n\nVielleicht seid Ihr aber genau die Person, die die Vektorspule zerstören und Sironas zu Fall bringen kann. Seid Ihr es?", progress = nil, completion = "Ihr habt die ganze Blutmythosinsel und Azurmythosinsel gerettet, das Leben der &lt;Volk&gt; in Azeroth gesichert, &lt;Name&gt;! Dafür wird man Euch niemals genug danken können, keine Belohnung, nichts ist groß genug, um Euch unsere Anerkennung zu zeigen.\n\nLeider blieben noch so viele auf Draenor zurück, die dieses historische Ereignis nicht miterleben können. Ihr müsst Euren Weg zurückfinden. Findet Euren Weg zur Scherbenwelt, Held von Argus. Bringt Eure Leute nach Hause. Nach Hause in das Land, das Ihr gerettet habt. Nach Azeroth...", rewards = "Streitkolben der HandKlinge der HandArmbrust der HandStab der HandIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9760] = {title = "Verteidigers Ruh'", objective = "Sprecht mit Verteidigerin Corin bei Verteidigers Ruh' auf der Blutmythosinsel.", description = "Ich würde Euch nicht bitten, die Vektorspule und Sironas im Alleingang zu vernichten, <Name>, dennoch glaube ich, dass Ihr uns helfen könnt, den Weg für andere abzusichern, die solch einen gefährlichen Auftrag auf sich nehmen werden.\n\nNehmt die Straße, die nördlich aus der Blutwacht führt, und folgt dem Verlauf bis Ihr auf die Weggabelung stoßt. Biegt auf die linke Straße ab und geht solange weiter bis Ihr zu Verteidigers Ruh' kommt - es liegt leicht westlich von der Straße selbst. Corin wird dort auf Euch warten.", progress = nil, completion = "Vielleicht verhelft Ihr unserem Volk ja zu einem neuen Zeitalter des Wohlstands und des Friedens.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9761] = {title = "Den Weg frei machen", objective = "Verteidigerin Corin bei Verteidigers Ruh' möchte, dass Ihr 8 Saboteure der Sonnenfalken und 8 Agenten der Sonnenfalken tötet.", description = "Nur die wirklich Kampferprobten, Edelmütigen und Furchtlosen werden sich Legosos Auftrag stellen. Der Exarch wird keinen Agenten der Hand damit beauftragen, die Vektorspule zu zerstören und Sironas zu stürzen. Er lehnt es ab, Draenei in ihren Tod zu schicken - genau darum geht es bei diesem Auftrag: Selbstmord...\n\n<Corin seufzt.>\n\nIch bin dafür verantwortlich, die Verteidigung der Sonnenfalken zu schwächen. Eure Aufgabe besteht darin, Sonnenfalken nahe der Vektorspule zu töten und somit den Weg für unseren Helden frei zu machen - wer immer es auch sein mag.", progress = nil, completion = "Hoffentlich meldet sich bald ein Held, bevor sie Verstärkung anfordern können, um die gerade von Euch abgesicherte Gegend zu bewachen.", rewards = "Seidenhandlappen des FaltersHandschuhe aus FelshetzerbalgCorins HandschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9762] = {title = "Die ungeschriebene Prophezeiung", objective = "Diese Inseln werden für Tausende ein Zuhause sein. Die meisten werden ihr gesamtes Leben hier verbringen. Ihr könntet das auch, aber es ist nicht, was Ihr wollt, oder <Name>?\n\n\n\nIhr werdet in Eurem Leben noch viele großartige Taten vollbringen. Ihr müsst Euer Schicksal umarmen und es willkommen heißen!\n\nBevor Ihr geht, möchte ich Euch noch zwei Geschenke überreichen: Dieser Wappenrock wird nur von denen getragen, die den höchsten Respekt der Hand von Argus genießen; und nur die Weisesten besitzen diesen Siegelring. Tragt beides mit Stolz, <Name>.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegelring der HandSiegelring der Hand\n\nIhr bekommt außerdem:\n\nWappenrock der Hand"}
MultiLanguageQuestData['de'][9763] = {title = "Das Versteck des Kriegsherren", objective = "Behüterin Jhang möchte, dass Ihr Kriegsherr Kalithresh im Echsenkessel findet und tötet.", description = "Es hat Vorteile, sich heimlich am Eingang zum Versteck des Feindes zu verstecken.\n\nVor ein paar Stunden sah ich eine Gruppe von Naga durch den steinernen Torbogen am zweiten Tunnel von links gehen. Ich bin in ihrer Sprache nicht sehr bewandert, aber ein Wort habe ich sehr deutlich verstanden: Kalithresh.\n\nDas muss der Eingang zu den Dampfkammern sein, von denen aus Kriegsherr Kalithresh seine Truppen befehligt. Ihr müsst ihn finden und aufhalten! Ich bin leider zu schwach, um Euch dabei helfen zu können.", progress = nil, completion = "Unser größter Feind in der Gegend ist endlich tot. Ihr habt der Expedition einen sehr großen Gefallen getan, &lt;Name&gt;.\n\nWir stehen auf ewig in Eurer Schuld.", rewards = "MyrmidonenkopfputzKappe des ErdwächtersHelm der KlaueKopfband des WasserbeschwörersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9764] = {title = "Befehle von Lady Vashj", objective = "Bringt die Befehle von Lady Vashj zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Dieser Brief enthält genaue Anweisungen für die Naga des Echsenkessels, die die Dampfpumpen bedienen. Er enthält eine Warnung vor der Ankunft von Druiden des Cenarius in dem Gebiet und die Anweisung, sie unverzüglich zu töten. Die Geschwindigkeit, mit der das Wasser aus den Seen in den Echsenkessel abgepumpt wird, soll verdoppelt werden. Die Befehle tragen das Siegel der berüchtigten Lady Vashj.\n\nDieser Brief dürfte die Druiden der Expedition des Cenarius sehr interessieren. Bringt ihn zur Leiterin der Expedition, Ysiel Windsänger.", progress = "Was habt Ihr da, <Name>?", completion = "Vashj!\n\nDamit haben wir nicht gerechnet. Unsere kleinen Siege gegen die Naga hier und da sind also bedeutungslos.\n\nWenn Lady Vashj darin verwickelt ist, dann sind viel stärkere Mächte am Werk, als wir es sind.\n\nEs war eine gute Entscheidung, den Brief zu uns zu bringen, &lt;Name&gt;. Nun müssen wir uns auf einen Krieg vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9765] = {title = "Kriegsvorbereitungen", objective = "Besorgt die Waffen des Echsenkessels von den Naga im Echsenkessel und kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", description = "Die Expedition des Cenarius fing einst als friedliches Projekt an, doch nun stehen wir am Rande eines ausgewachsenen Kriegs gegen die Naga.\n\nUnter uns sind einige, die zwar gerne kämpfen würden, aber nur sehr schlecht ausgerüstet sind. Bringt mir die Waffen der Naga, damit wir sie zu Gleven und Pfeilspitzen umschmelzen können.\n\nNur Waffen aus hochwertigem Material können für uns nützlich sein, <Name>. Ihr werdet die der Naga im Echsenkessel stehlen müssen.", progress = "Habt Ihr die Waffen, die ich benötige, schon besorgt, <Name>?", completion = "Sie eignen sich perfekt, &lt;Name&gt;. Bringt mir alle Waffen, die Ihr nur finden könnt. Unser Bedarf ist groß und unsere Mittel sind wenige.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9766] = {title = "Waffen des Echsenkessels", objective = "Wir werden den eigenen Stahl der Naga in Waffen gegen sie umschmieden. Bringt mir alle Waffen, die Ihr aus dem Echsenkessel besorgen könnt.", description = nil, progress = "Wir werden den eigenen Stahl der Naga in Waffen gegen sie umschmieden. Bringt mir alle Waffen, die Ihr aus dem Echsenkessel besorgen könnt.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Naga werden schon lernen, dass sie uns nicht unterschätzen sollten!", rewards = nil}
MultiLanguageQuestData['de'][9767] = {title = "Den Feind kennen", objective = "Besorgt ein Zauberbuch des Echsenkessels von den Naga im Echsenkessel und bringt es zu Ashyen in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Um einen Feind zu besiegen braucht man weit mehr als eine Überzahl an Männern oder Kraft. Oft hängt der Sieg davon ab, ob man die Schwächen des Feindes oder seine typischen Vorgehensweisen kennt.\n\nWir wissen zwar viel über die Naga, aber ihre Magie bleibt uns immer noch fremd.\n\nIch habe vor, mich mit der Hydromantie der Naga des Echsenkessels auseinanderzusetzen. Bringt mir eines ihrer Zauberbücher, damit ich mehr darüber erfahren kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9769] = {title = "Mode kann man nicht erklären", objective = "Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Magasha im Sumpfrattenposten.", description = "<Magasha kichert still in sich hinein.>\n\nIch wette, wenn sie wüssten, dass sie Insektenteile anhaben, wäre der Trend schnell vorbei.\n\nZuerst haben wir angefangen, die Insekten in der Umgebung zu töten, weil sie bei den Bauarbeiten im Weg waren. Eines Tages kam ein geschäftstüchtiger Händler hierher, blieb über Nacht und plötzlich fing er an alle Insektenflügel, die er bekommen konnte, aufzukaufen!\n\nSagte, er mache Kleidung daraus. Ich bleib lieber bei meiner Rüstung, danke. Aber wenn Ihr die Flügel der Glühwürmchenarten in der Umgebung sammelt, kaufe ich sie Euch gerne ab.", progress = "Was ist los? Hat Euch jemand die Flügel gestutzt?\n\n<Magasha kichert über ihren Witz.>", completion = "Die sind fein, &lt;Name&gt;. Hier ist Eure Bezahlung.\n\n\n\nNe, nicht mein Fall, aber ich hab ja auch keine Ahnung von Mode.\n\n\n\nEs ist das Geld, was zählt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9770] = {title = "Bedrohliche Marschenfänge", objective = "Reavij im Sumpfrattenposten möchte, dass Ihr 10 Marschfangreißer tötet.", description = "Manchmal wünschte ich, Denjai hätte uns einen Schamanen mitgeschickt oder uns wenigstens ein Totem gegeben, um die Marschfangreißer fernzuhalten.\n\nEs wimmelt hier nur so von diesem Ungeziefer! Das ist doch nicht gerecht. Sollte nicht irgendwas diese widerlichen Käfer auffressen?\n\nWir haben alle schon abwechselnd Kammerjäger gespielt. Ihr seid genau zur richtigen Zeit gekommen, <Name>. Glückwunsch! Und jetzt geht los und wischt ein paar Marschfänge auf!", progress = nil, completion = "Schon satt?\n\n&lt;Reavij lacht.&gt;\n\nEs gibt einen Grund warum unsere Besucher nicht lange bleiben.\n\nWenn ich eine Wahl hätte, würde ich einen angenehmeren Ort für den Posten auswählen. Aber ich ziehe die Marschfänge immer noch Denjais Launen vor!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9771] = {title = "Auf der Suche nach Späher Jyoba", objective = "Sucht Späher Jyoba im Todesmoor in den Zangarmarschen.", description = "Jetzt, da Ihr mit dem Gelände vertraut seid, würde ich Euch gerne bei einer anderen Sache um Hilfe bitten. Das Todesmoor, so nennen wir das Gebiet im Nordwesten, ist ein schauriger Ort. Niemand hat dort je ein Lebewesen gesehen, aber es war auch nie jemand lange dort.\n\nSpäher Jyoba hat sich freiwillig gemeldet, um das Gebiet zu untersuchen und von seinen Beobachtungen zu berichten. Er hat den Posten vor drei Tagen verlassen und ist noch nicht zurückgekehrt. Er würde nie so lange wegbleiben ohne einen Bericht zu schicken. Könntet Ihr nach ihm suchen, <Name>?", progress = nil, completion = "Diese in Mitleidenschaft gezogene Leiche passt genau zu Zurais Beschreibung. Was auch immer den Späher getötet haben mag, muss ihn überrascht haben, da er seine Waffen nicht gezogen hatte und Tintenflecken auf dem Boden zu sehen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9772] = {title = "Jyobas Bericht", objective = "Besorgt Späher Jyobas Bericht von den siechenden Riesen und kehrt dann zu Zurai im Sumpfrattenposten zurück.", description = "Fetzen von welkem Pilz befinden sich überall auf dem Körper von Späher Jyoba. Was auch immer ihn getötet hat muss aus demselben siechenden Pilz bestehen wie die riesigen welkenden Pilze des Todesmoors. Vielleicht hat ihn einer der siechenden Riesen überrascht, als er gerade seinen Bericht schreiben wollte.\n\nOhne den Text des Berichts ist es fast unmöglich herauszufinden, was der Späher entdeckt hat. Wenn der Bericht gefunden werden könnte, sollte er unbedingt zu Zurai gebracht werden.", progress = "Ihr seid zurück, aber Jyoba ist nicht bei Euch. Was ist mit ihm passiert?", completion = "&lt;Zurai nimmt den Bericht von Euch und schaut ihn sich an.&gt;\n\nViele von diesen Informationen sind uns bereits bekannt. Alles in dieser Gegend scheint ausgetrocknet oder am verwelken zu sein, aber hier steht etwas neues.\n\nEr sagt, die Fungusgiganten sind von dem Wassermangel wahnsinnig geworden. Eurer Beschreibung nach muss es einer von ihnen gewesen sein, der ihn umgebracht hat.\n\nIch werde meinen Männer anweisen, die Gegend zu meiden. Wir können uns keine weiteren Verluste erlauben.", rewards = "Bänder des SumpfschreitersVerfinsterte ArmschienenGürtel des SumpfschreitersUmhang des TiefenmoorsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9773] = {title = "Keine Pilze mehr!", objective = "Bringt 8 Aalfilets von Umbrafennaalen zu Magasha im Sumpfrattenposten.", description = "Pilzsuppe, Pilzeintopf, Pilzsoße!\n\nPilze, Pilze, Pilze! Was anderes bekommt man hier nicht zu essen. Wenn man sagt, dass man Hunger hat, drückt der Koch einem eine Axt in die Hand und sagt: Schlag Dir Dein Abendessen selbst!\n\nNun, ich habe Pilze satt. Ich habe Fische in den Seen hier gesehen. Klar, sie sehen aus, als würden sie sich wehren, aber sie müssen einfach besser schmecken als Pilze!\n\nWie viel würde es mich kosten Euch zu beauftragen, mir mein erstes anständiges Abendessen seit Wochen zu bringen?", progress = "Bitte sagt mir nicht, dass Ihr mit leeren Händen zurückgekommen seid, <Name>.", completion = "Endlich, eine Abwechslung zu den Pilzen! Wenn Ihr nicht nach Fisch riechen würdet, würde ich Euch umarmen.\n\nWollen wir mal schauen, wie neidisch die anderen werden, wenn sie meinen gebratenen Fisch riechen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9774] = {title = "Dicke Hydraschuppen", objective = "Bringt 12 dicke Hydraschuppen zu Zurai im Sumpfrattenposten.", description = "Es war sehr klug von Reavij Lederrüstung mitzubringen. Der Sumpf wird meine Panzerrüstung innerhalb von kurzer Zeit wertlos machen.\n\nIch habe schon so weit ich konnte nach und nach alle Schuppen ausgetauscht. Die Hydras in dem Marschen haben dicke, schützende Schuppen, die der Feuchtigkeit ihrer Heimat optimal standhalten.\n\nGeeignete Schuppen zu finden ist allerdings ziemlich langwierig. Oftmals sind sie zu kaputt, zu abgenutzt oder zu dünn um sie als Rüstung zu verwenden. Bringt mir ein paar geeignete Schuppen von den Hydras in den größeren Seen.", progress = "Ich sehe, dass Ihr grinst. Ja, meine Rüstung wird etwas merkwürdig aussehen, bis ich das ganze alte Metall ersetzt habe, aber besser so als ungeschützt.", completion = "Danke, &lt;Name&gt;. Jedes noch so kleine bisschen hilft.\n\nEs ist immer noch viel zu tun, aber mal ehrlich, was soll ich sonst zwischen den Patrouillen machen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9775] = {title = "Bericht an Schattenjäger Denjai", objective = "Bringt Zurais Bericht zu Schattenjäger Denjai in Zabra'jin in den Zangarmarschen.", description = "Schattenjäger Denjai erwartet sicher einen Bericht über meine Fortschritte bei der Errichtung unseres Außenpostens. Ich habe eine Zusammenfassung unserer bisherigen Errungenschaften vorbereitet, aber seit wir Späher Jyoba verloren haben, kann ich keinen Boten entbehren, um den Bericht zu Denjais Posten Zabra'jin im Westen zu bringen.\n\nWenn Ihr in die Richtung geht, könntet Ihr ihm den Bericht vielleicht von mir geben? Schattenjäger Denjai kann auf den ersten Blick etwas einschüchternd wirken, aber wenn Ihr Euch an ihn gewöhnt habt, ist er kein übler Kerl.", progress = "Ihr seht nicht aus wie einer meiner Männer. Was wollt Ihr, <Volk>?", completion = "Warum habt Ihr nicht gleich gesagt, dass Ihr einen Bericht von Zurai habt? Ich warte schon auf Nachricht von ihm.\n\nIch habe ihn nach Osten geschickt, damit er dort einen Posten baut, nicht um auf den Händen zu sitzen. Wollen wir mal sehen, was er zu sagen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9776] = {title = "Die Oreborzuflucht", objective = "Sprecht mit Ikuti in der Oreborzuflucht in den Zangarmarschen.", description = "Wie Ihr sicher wisst, sind viele Einwohner von Telredor Flüchtlinge aus dem Krieg, der die Draenei dezimiert hat. Es ist mein Ziel, Telredor als sicheren Hafen für all unsere Verbündeten in diesem Kampf zu gewinnen. Es gibt einige, die sich uns gerne anschließen möchten, aber spüren, dass sie noch nicht bereit sind.\n\nWir schulden ihnen jede Hilfe, die wir ihnen bieten können, <Name>. Eine Gruppe von Zerschlagenen unter der Führung von Ikuti hat in den Ruinen eines alten Tempels nordwestlich vom Schlangensee Zuflucht gefunden. Sucht sie und reicht ihnen Eure Hand in Freundschaft.", progress = nil, completion = "Wenn Anachoret Ahuurn Euch als Freund betrachtet, kann ich Euch vielleicht vertrauen. Bitte vergebt mir meinen Argwohn, &lt;Volk&gt;, doch oft rettet nur dieser mein Volk vor dem Tod. Seid in unserer Zuflucht willkommen. Vielleicht wird so unser gegenseitiges Vertrauen wachsen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9777] = {title = "Fulgorsporen", objective = "Bringt 6 Fulgorsporen zu Ruam in Telredor.", description = "Es gibt nur wenig Brennbares in diesem Sumpf, <Volk>, daher müssen wir auf andere Mittel zugreifen, um Telredor zu erleuchten. Viele Tiere und Pflanzen in den Marschen strahlen ein schwaches Leuchten aus.\n\nEs ist schwierig und grausam die leuchtenden Tiere einzusperren, deshalb haben wir uns einen Pilz als Lichtquelle gesucht.\n\nWir bauen die Fulgorpilze hier an, aber ab und zu benötigen wir auch neue Pflanzen. Die kleinen grünen Pilze wachsen an den größeren in der Nähe von Telredor.", progress = "So wie es aussieht brauchen wir sehr bald neue Sporen.", completion = "Diese Sporen sind sehr gut und sollten uns für einen Weile reichen. Vielen Dank für Eure Hilfe bei der Aufstockung unserer Vorräte, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9778] = {title = "Aufseher Hamuht", objective = "Meldet Euch bei Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Sprecht auf jeden Fall noch mit Aufseher Hamuht, bevor Ihr die Zuflucht des Cenarius verlasst. Er ist für die Sicherheit der Expedition verantwortlich.\n\nEr würde mir nie verzeihen, wenn ich einen erfahrenen Abenteurer wie Euch nicht zu ihm schicken würde.", progress = nil, completion = "Ysiel hat Euch geschickt? Natürlich habe ich für jemanden wie Euch Verwendung! Wir können immer ein paar Muskeln brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9779] = {title = "Abfangen der Nachricht", objective = "Tötet die Elfen der Sonnenfalken, bis Ihr das Schreiben der Sonnenfalken findet, und bringt es zu Verteidiger Boros bei der Blutwacht.", description = "Schön, Euch wiederzusehen, <Name>. Ich hätte da eine heikle Aufgabe, die es zu lösen gilt.\n\nUnsere Agenten, die die Sonnenfalken ausspionieren, haben berichtet, dass Soldaten der Sonnenfalken ein ungewöhnliches Dokument untersucht haben.\n\nUnglücklicherweise konnten wir keine Kopie dieses Schreibens für uns selbst beschaffen. Ihr müsst für mich vor Ort gehen und das Dokument an Euch bringen. Ich bin mir sicher, dass Euch ein Sonnenfalke die von uns gesuchten Informationen geben wird, wenn Ihr genug Druck anwendet. Ich überlasse den Einsatz von Gewalt voll und ganz Eurem Ermessen.", progress = "Schon zurück? Konntet Ihr das Schreiben finden?", completion = "&lt;Verteidiger Boros betrachtet das Dokument.&gt;\n\nDas ist Thalassisch. Glücklicherweise kenne ich eine Person, die es übersetzen kann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9780] = {title = "Aalfilets von Umbrafenn", objective = "Bringt 8 Aalfilets zu Noraani in Telredor.", description = "Schön, ein neues Gesicht hier zu sehen. Als Haalrun und ich nach Telredor kamen, waren wir die ersten von außerhalb, aber das scheint schon eine Ewigkeit her zu sein.\n\nTrotzdem heißen wir Neuankömmlinge immer willkommen und versuchen dafür zu sorgen, dass alle genug zu essen haben. Wir werden die Freundlichkeit der Anachoreten von Telredor niemals vergelten können, aber wir können ihrem Beispiel folgen und ebenso freundlich zu anderen sein.\n\nWenn Ihr helfen möchtet, dann fangt ein paar der Fische, die sich in den Seen in der Gegend tummeln. Sie heißen Umbrafennaale und sind Hauptbestandteil unserer Nahrung.", progress = "Habt Ihr schon Fische für unsere Vorräte besorgt?", completion = "Danke für Eure Hilfe, &lt;Name&gt;. Euer Großmut wird nicht vergessen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9781] = {title = "Zu viele Mäuler zu stopfen", objective = "Tötet 10 Morasthydras und kehrt zu Haalrun in Telredor zurück.", description = "Auf meiner letzten Jagd habe ich gesehen, dass eine Gruppe von Trollen im Begriff ist, einen neuen Außenposten zu bauen. Ohne Zweifel haben sie auch angefangen, hier zu jagen.\n\nWenn sie einen dauerhaften Standort hier errichten, wird es einen erbitterten Kampf um Nahrung geben. Wir können sie nicht direkt angreifen, ohne sie zu provozieren. Aber wir können unsere natürlichen Wettbewerber im Nahrungskampf reduzieren.\n\nJede Morasthydra, die Ihr erlegt, bedeutet drei Mäuler weniger, die gestopft werden müssen!", progress = nil, completion = "Gut gemacht. Das sollte den Bedarf an Nahrung in der Gegend für die nahe Zukunft etwas mindern, auch wenn wir immer noch nach neuen Nahrungsquellen suchen sollten.. Fisch und Pilze reichen aus, aber etwas Abwechslung sollte nicht unterschätzt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9782] = {title = "Das Todesmoor", objective = "Bringt eine Erdprobe vom Todesmoor zu Verteidiger Idaar in Telredor.", description = "Ich lebe nun seit einiger Zeit bei den Anachoreten von Telredor, <Name>, und inzwischen kenne ich die Marschen ganz gut. In letzter Zeit habe ich eine erschreckende Veränderung des Landes im Nordosten bemerkt.\n\nFast alles Leben dort hat begonnen zu welken und zu sterben, und das scheinbar ohne Grund. Ich habe ein paar Vermutungen, was dort vorgehen könnte, aber sie sind nur sehr vage. Wenn Ihr mir eine Bodenprobe dieser Gegend bringen könntet, dann könnte ich diesem Rätsel vielleicht auf den Grund kommen.", progress = "Konntet Ihr eine Probe der Erde des Todesmoors bekommen?", completion = "Hmm... der Boden ist nicht ausgelaugt, das kann also nicht der Grund für das Problem sein, wie ich zuerst vermutet habe. Wo liegt die Verbindung? Warum stirbt alles so plötzlich?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9783] = {title = "Eine unnatürliche Dürre", objective = "Verteidiger Idaar in Telredor möchte, dass Ihr 12 siechende Riesen tötet.", description = "Die Erdprobe, die Ihr mir gebracht habt, ist fast ausgetrocknet, <Name>. Wenn schon der Boden seine Feuchtigkeit verliert, müssen die Lebewesen im Todesmoor furchtbar leiden.\n\nIch habe gesehen, was passiert, wenn die Fungusgiganten der Gegend anfangen zu welken und zu sterben. Der Schmerz macht sie wahnsinnig und bringt sie dazu, alles in ihrer Nähe anzugreifen.\n\nDiese Lebewesen haben nicht die leiseste Ahnung, was mit ihnen geschieht. Sie zu retten liegt außerhalb unserer Macht. Das Einzige, was wir tun können, ist ihr Leiden zu beenden.", progress = nil, completion = "Danke für Eure Hilfe bei dieser schweren Aufgabe, &lt;Name&gt;. Unsere Arbeit im Todesmoor ist noch nicht beendet, aber nun können wir uns darauf konzentrieren, das Gleichgewicht in der Gegend wiederherzustellen.", rewards = "Sattelgurt des VerteidigersArmschienen des FennschreitersBänder des ForschersMantelung des ForschersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9784] = {title = "Pflanzenteile identifizieren", objective = "Ich könnte noch mehr Pflanzenteile brauchen. Jetzt, da die Seen ihr Wasser verlieren, befürchte ich, dass die fremden Arten zunehmen werden. Ich brauche aber mehr Beweise, um meine Theorie zu untermauern.", description = nil, progress = "Ich könnte noch mehr Pflanzenteile brauchen. Jetzt, da die Seen ihr Wasser verlieren, befürchte ich, dass die fremden Arten zunehmen werden. Ich brauche aber mehr Beweise, um meine Theorie zu untermauern.", completion = "Ausgezeichnet. Wenn Ihr noch mehr Pflanzenteile findet, bringt sie zu mir.\n\n&lt;Diese Quest kann wiederholt werden, bis Ihr den Ruf Wohlwollend' erlangt habt.&gt;", rewards = "Ihr bekommt:\n\nPaket mit unbekannten Pflanzen"}
MultiLanguageQuestData['de'][9785] = {title = "Der Segen der Uralten", objective = "Windruferin Schwarzhuf möchte, dass Ihr mit den Urtumen Ashyen und Keleth in der Zuflucht des Cenarius sprecht und um ihren Segen bittet.", description = "Ihr habt Euch das Vertrauen der Expedition des Cenarius verdient, <Name>. Es ist an der Zeit, dass Ihr Euch mit den Urtumen unterhaltet, die sich unserer Sache angeschlossen haben, Ashyen und Keleth, und um ihren Segen bittet.\n\nDas Zeichen eines Urtums zu tragen bedeutet große Macht. Je höher Euer Ansehen bei uns steigt, umso wertvoller wird dieser Gefallen werden.\n\nGeht, <Name>, und bittet die Urtume um ihren Segen.", progress = nil, completion = "Ihr seid zurück. Habt Ihr den Segen der Uralten erhalten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9786] = {title = "Die Ruinen von Boha'mu", objective = "Anachoret Ahuurn in Telredor möchte, dass Ihr die Ruinen von Boha'mu erforscht.", description = "Bevor mein Volk von den Orcs dezimiert wurde, diente Telredor als Zuflucht für die Anachoreten und Spiritualisten der Draenei. Ein kleiner Orden von Anachoreten und Verteidigern pflegte ein paar Schreine in dieser Region.\n\nWährend des Krieges verloren wir den Kontakt zu den Anachoreten, die für diese Schreine zuständig waren, besonders zu denen im Tempel von Boha'mu im Südwesten. Ich habe gehört, dass ein Stamm von Verirrten sich in dieser Gegend niedergelassen hat und vielleicht sogar in den Ruinen lebt. Geht zu den Ruinen von Boha'mu und berichtet mir, was Ihr dort findet.", progress = nil, completion = "Die Verirrten des Wildfennstamms haben sich also in den Ruinen eingenistet? Das ist verblüffend. Sie müssen sich an Ihr Erbe erinnern und die Wichtigkeit dieses Ortes erkennen können. Wir müssen mehr darüber erfahren, &lt;Name&gt;. Vielleicht ist in diesem Tempel der Schlüssel zur Erlösung der Verirrten und zur Wiedervereinigung der verschiedenen Arten der Draenei versteckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9787] = {title = "Götzen des Wildfennstamms", objective = "Sammelt 6 Wildfenngötzen und kehrt dann zu Anachoret Ahuurn in Telredor zurück.", description = "Aus Eurem Bericht über die Ruinen von Boha'mu hörte ich heraus, dass dieser Stamm der Verirrten zur Verehrung von Tiergeistern zurückgekehrt ist. Bevor wir auf sie zugehen können, müssen wir mehr über ihren Glauben in Erfahrung bringen.\n\nKehrt zurück nach Wildfenn und sammelt heimlich ein paar ihrer Götzen, damit ich sie untersuchen kann. Versucht jedoch, sie nicht wütend zu machen, sonst haben wir vielleicht keine Chance mehr, Kontakt mit ihnen aufzunehmen.", progress = "Habt Ihr die Götzen?", completion = "Diese sollten mehr als ausreichen, &lt;Name&gt;. Sie scheinen auf Vögel fixiert zu sein, was merkwürdig ist, da es in den Zangarmarschen keine einheimischen Vogelarten gibt. Was könnte das wohl bedeuten?\n\nSind sie vielleicht auf die Arakkoa getroffen? Für ein schamanistisches Volk mögen sie vielleicht wie der Inbegriff eines mächtigen Vogelgeists wirken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9788] = {title = "Ein feuchter, düsterer Ort", objective = "Sucht nach Ikeyens Habseligkeiten in einer Höhle südlich von Umbrafenn. Bringt sie zurück zu Ikeyen in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Bald nachdem ich dem Umbrafennstamm entkommen war, habe ich mich in einer Höhle südlich des Dorfs verkrochen. Ich hatte ja keine Ahnung, dass die Tiere der Marschen und die Sporenmänner sich um die Höhle stritten!\n\nIch musste sehr plötzlich von dort fliehen und eine Kiste mit meinem weltlichen Besitz zurücklassen.\n\nEs grenzte schon an Ironie, dass ich mit meinem ganzen Hab und Gut aus Umbrafenn entkommen konnte, nur um es so bald darauf wieder zu verlieren. Wenn Ihr mir meine Sachen wiederbringen könntet, würde ich Euch etwas aus meinem persönlichen Besitz schenken. Seid Ihr einverstanden, <Name>?", progress = "Habt Ihr meine Habseligkeiten gefunden, <Name>? Die Höhle ist nicht weit von Umbrafenn entfernt, nahe an der Grenze zu Nagrand.", completion = "Meine Sachen! Sie sind alle da!\n\nIch danke Euch, &lt;Name&gt;. Wie versprochen dürft Ihr Euch etwas von den Dingen aussuchen. Ich habe nicht viel anzubieten, aber mein Volk hat schon immer das Wenige, was wir hatten, geteilt.", rewards = "Ikeyens SchulterstückeMatschverkrustete StiefelIkeyens StiefelRüstung der ZufluchtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9789] = {title = "Beherrschen der Grollhufjagd", objective = "Erlegt 12 Grollhufe und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück, um Euch zu beweisen.", description = "Ihr möchtet Euch einen Platz in der Safari verdienen? Dann beweist Euch erst einmal.\n\nMir ist es völlig schnuppe, was Ihr schon alles für Kreaturen erlegt habt, bevor Ihr nicht jagt, was wir jagen, seid Ihr in meinen Augen <kein Jäger/keine Jägerin>. Die Grollhufe wären ein guter Anfang, sofern Ihr <Manns genug/mutig genug> seid.\n\nIch bin mir sicher, dass ich sie in der direkten Umgebung der Safari und in der Nähe im Süden gesehen habe.", progress = nil, completion = "Ein akzeptabler Start. Doch das war erst der Anfang.\n\nDie harmloseren Grollhufe beweisen noch gar nichts. Versuchen wir es doch mal mit einer größeren Herausforderung für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9790] = {title = "Lichtdurchlässige Flügel", objective = "Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Haalrun in Telredor.", description = "An so einem abgeschiedenen Ort zu leben hat uns gelehrt, einen Nutzen aus allen verfügbaren Dingen zu ziehen. Dabei muss man natürlich lernen zu vergessen, woher einige der Materialien stammen.\n\nIch habe herausgefunden, dass die Flügel der Umbraglimmstecher, die hier in der Gegend leben, sehr gut als Regenschutz dienen. Sie sind stabil, dünn und biegsam.\n\n<Haalrun kichert.>\n\nIch sehe Euren Gesichtsausruck. Wie ich sagte, man muss sich erst an die Idee gewöhnen. Wenn Ihr in der Gegend herumstreicht, könnt Ihr mir dann vielleicht ein paar solcher Flügel mitbringen?", progress = "Habt Ihr schon ein paar lichtdurchlässige Flügel sammeln können?", completion = "Habt Dank, &lt;Name&gt;.\n\n\n\nZumindest müsst Ihr sie nicht säubern. Das ist der schlimmste Teil der Arbeit, aber wenn ich damit fertig bin, werdet Ihr niemals erkennen, dass sie mal zu einem riesigen Insekt gehört haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9791] = {title = "Bedrohliche Marschenfänge", objective = "Tötet 10 Marschenfangreißer und kehrt dann zu Noraani in Telredor zurück.", description = "Während der Kriege der Orcs gegen mein Volk haben die Nahrungssammler Telredor aus Angst, angegriffen oder gefangen zu werden, kaum verlassen. Nun gehen sie häufiger hinaus, aber die Marschen sind nicht weniger gefährlich.\n\nEs scheint, als wären die Marschenfänge in letzter Zeit aggressiver geworden. Ich weiß nicht, ob das an der erhöhten Konkurrenz für ihre gewöhnliche Nahrung liegt, aber sie greifen regelmäßig unsere Nahrungssucher an. Vielleicht würden sie uns in Ruhe lassen, wenn wir ihren Bestand um Telredor herum etwas dezimieren könnten.", progress = nil, completion = "Danke für Eure Hilfe bei der Auslöschung einiger Marschenfangreißer, &lt;Name&gt;. Wenn sie über Intelligenz verfügen würden, würden sie vielleicht erkennen, dass es am Besten ist, zu leben und leben zu lassen.\n\n\n\nGroße, überwucherte Käfer mit Intelligenz. Ich frage mich, wie das wohl wäre...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9792] = {title = "Eine Botschaft für Telaar", objective = "Sprecht mit Aufseher Moi'bff in Telaar in Nagrand.", description = "Ihr habt Euch in unseren Geschäften als vertrauenswürdig erwiesen, <Name>, und das in Zeiten, in denen das Vertrauen meines Volkes nur schwer zu gewinnen ist.\n\nEine große Gruppe meiner Brüder und Schwestern hat sich in der alten Draeneistadt Telaar in Nagrand im Süden niedergelassen. Um nach Telaar zu gelangen, müsst Ihr der Straße Richtung Süden nach Nagrand folgen und dann nach Südosten gehen, bis Ihr an die Klippen östlich des Oshu'guns gelangt.\n\nJeder, der uns so sehr geholfen hat wie Ihr, ist dort willkommen.\n\nSucht Aufseher Moi'bff Jill und sagt ihm, dass Ihr mein Vertrauen erlangt habt.", progress = nil, completion = "Ikuti ist wie ein Bruder für mich. Seine Freunde sind auch meine Freunde. Ihr seid hier willkommen, &lt;Name&gt;, und Ihr habt unseren Dank für die Hilfe, die Ihr meinem Volk geleistet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9793] = {title = "Das Schicksal von Tuurem", objective = "Bringt Verteidiger Idaars Brief zu Andarl in Allerias Feste in den Wäldern von Terokkar.", description = "Prophet Velens Suche nach Verbündeten hat die Draenei in der Scherbenwelt ermutigt, selbst eine Suche zu beginnen. Der Krieg meines Volks mit der Legion hat uns vielleicht aus unseren Städten und Tempeln vertrieben, aber er konnte nicht alle Spuren unserer Zivilisation verwischen.\n\nTuurem, mein früheres Zuhause in den Wäldern von Terokkar, war eine der Städte, die von den Orcs überrannt wurden. Ich habe schon viel zu lange nichts mehr von dort gehört. Bringt diesen Brief zu Andarl in Allerias Feste in Terokkar und schaut, was Ihr herausfinden könnt.", progress = "Wie kann ich Euch helfen?", completion = "Hmm... Ich kann mich erinnern, dass unsere Späher von den Ruinen einer Draeneisiedlung in den nördlichen Ausläufern des Waldes berichtet haben. Ich weiß jedoch selbst nicht viel über die Ruinen, aber Ihr könnt gerne mit unseren Spähern sprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9794] = {title = "Keine Zeit für Neugier", objective = "Bringt Timothys Brief zu Kialon in Sylvanaar im Schergrat.", description = "<Name>, ich muss Euch um einen Gefallen bitten. Normalerweise würde ich das ja nicht tun, aber ich habe beide Hände bereits mehr als voll.\n\nIch habe einen Verbündeten namens Kialon in Sylvanaar im Schergrat im Norden. Er erwartet, dass ich mich in naher Zukunft bei ihm melde, obwohl ich fürchte, dass ihm nicht gefallen wird, was ich zu sagen habe.\n\nWenn Ihr ihm meine Antwort bringen könntet, wäre ich Euch sehr dankbar. Ich muss jedoch darauf bestehen, und das ist sehr wichtig, dass Ihr den Brief nicht lest. Er ist nur für Kialons Augen bestimmt.", progress = "<Kialon schaut Euch misstrauisch an.>\n\nIch kenne Euch nicht, <Volk>. Was wollt Ihr von mir?", completion = "Ihr bringt mir also Timothys Antwort?\n\n&lt;Kialon hält einen Moment inne, um den Brief zu lesen, und fängt an zu lachen.&gt;\n\nEr hat alles unter Kontrolle, sagt er, braucht keine Hilfe. Ich hätte es wissen müssen!\n\nManche Leute ändern sich nie. Schaut, er hat sich sogar die Zeit genommen, meine Rechtschreibfehler zu korrigieren.\n\n&lt;Kialon seufzt halbherzig.&gt;\n\nIch hätte ihm den Brief nicht schicken sollen. Ich habe es vergessen. Der Spezialist hat die Situation immer unter Kontrolle. Immer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9795] = {title = "Die Ogerbedrohung", objective = "Reist zur Donnerfeste im Schergrat und sprecht mit Nekthar.", description = "Als ob die Naga und ihre Verbündeten nicht schon genug wären, scheinen nun auch die Oger sich weiter in den Marschen auszubreiten. Sie haben schon weite Teile des Nordwestens erobert, und der Puffer zwischen uns und ihnen wird immer kleiner.\n\nFür jeden, den wir umbringen, sind gleich mehrere neue zur Stelle. Ich weiß nicht, wie lange wir Zabra'jin halten können, wenn sie sich entschließen uns anzugreifen. Geht nach Norden in die Berge zum orcischen Stützpunkt in der Donnerfeste und berichtet Nekthar von unserer Bedrängnis. Jede Hilfe, die er uns zur Verfügung stellen kann, ist äußerst willkommen.", progress = nil, completion = "Denjai braucht Hilfe? Ich würde ihm gerne ein paar Leute schicken, aber wir sind hier selbst nur sehr dünn besiedelt. Wir haben hier oben unsere eigenen Probleme mit den Ogern.\n\nSobald ich kann werde ich ihm alle Informationen, die wir über diesen Ogerstamm und ihre Taktiken haben, zukommen lassen. Wenn er lang genug durchhält können wir die Grobiane vielleicht von zwei Seiten aus angreifen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9796] = {title = "Nachricht aus den Zangarmarschen", objective = "Sprecht mit Mokasa in der Steinbrecherfeste in den Wäldern von Terokkar.", description = "Schattenjäger Denjai ist nicht der einzige, der auf einen Bericht von mir wartet. Mokasa in der Steinbrecherfeste in Terokkar brennt darauf, von unseren Fortschritten zu hören, besonders seit die meisten ihrer Boten hier auf ihren Reisen vorbeikommen.\n\nSie hat mich gebeten, ihr Bescheid zu geben, sobald der Sumpfrattenposten fertig ist. Wenn Ihr nichts dagegen habt, wäre ich Euch sehr dankbar, wenn Ihr ihr die Nachricht überbringen könntet. Wir haben zwar soweit schon alles aufgebaut, aber es gibt noch viel zu tun.\n\nUm zur Steinbrecherfeste zu gelangen, müsst Ihr der Straße nach Süden in Richtung Zangarmarschen folgen und Euch durch die Wälder von Terokkar an Tuurem vorbei begeben.", progress = nil, completion = "Es wurde auch langsam Zeit, dass der Außenposten fertig wird. Wir haben schon viel zu viele Boten an die Vorhut der Allianz verloren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9797] = {title = "Verstärkung für Garadar", objective = "Sprecht mit Hauptmann Kroghan in Garadar in Nagrand.", description = "<Immer noch nach Atem ringend bedeutet der Bote Euch, Euch hinzusetzen.>\n\nSie werden vielleicht nicht überleben, <Volk>! Geht so schnell Euch Eure Beine tragen können nach Garadar.\n\n<Als Reaktion auf Euren fragenden Gesichtsausdruck führt der Bote näher aus.>\n\nDas Zuhause der Mag'har liegt im Süden, in Nagrand. Wir haben ein paar Leute dort, aber es sind nur wenige, und unsere Verbündeten der Mag'har werden von allen Seiten von Feinden angegriffen. Sucht dort unseren Kommandanten, Hauptmann Kroghan, und helft ihm, wo Ihr nur könnt! Garadar darf nicht fallen!", progress = nil, completion = "&lt;Auch wenn er sich Mühe gibt, es zu verheimlichen, macht sich Erleichterung auf Kroghans Gesicht breit.&gt;\n\nEs wurde auch langsam Zeit, dass Ihr kommt! Sicher, Ihr seid keine Armee, &lt;Volk&gt;, aber hier ist ein jeder willkommen, der Kraft genug besitzt, eine Waffe zu führen oder einen Zauber zu wirken. Die Bevölkerung Garadars ist ein Teil der Horde und stolz, sein Blut für ihre Verteidigung vergießen zu dürfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9798] = {title = "Blutelfenpläne", objective = "Bringt die Blutelfenpläne zu Verteidiger Aldar bei der Absturzstelle im Am'mental.", description = "Diese Pläne sehen wichtig aus. Ihr solltet sie Verteidiger Aldar bei der Absturzstelle zeigen.", progress = "Was habt Ihr denn da?", completion = "Hier, lasst mich einen Blick auf diese Pläne werfen.\n\nDie Blutelfen sind uns hierher gefolgt? Sie sind durch und durch bösartig und sollten ganz und gar ausgelöscht werden!\n\n&lt;Der Verteidiger braucht einen Moment, um sich wieder zu fassen.&gt;\n\nEntschuldigung, ich hätte mich beherrschen sollen. Wir stehen für die Entdeckung dieser Informationen in Eurer Schuld, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9799] = {title = "Botanische Hilfsarbeit", objective = "Sammelt 3 verderbte Blumen und kehrt zu Lehrling Vishael bei der Absturzstelle im Am'mental zurück.", description = "Die Am'menfelder im Westen sind das wichtigste Vermehrungsgebiet der einheimischen Peitscherpopulation. Botanikerin Taerix befürchtet, dass sich die Peitscher auf Grund des verseuchten Grundwasserspiegels nicht mehr fortpflanzen können, nachdem wir den See gereinigt haben.\n\nGeht zu den Am'menfeldern und pflückt dort ein paar der verderbten Blumen für mich, damit ich sie untersuchen und sehen kann, was es zu tun gilt. Ihr solltet sie an ihren ungewöhnlichen roten Blüten erkennen.", progress = "Hallo, <Klasse>. Habt Ihr die Blumen?", completion = "Das sieht mir nach ein paar guten Exemplaren aus. Danke für Eure kleine Hilfsarbeit. Sobald ich Zeit zum Untersuchen der Blumen habe, sollte ich bestimmen können, was es zur Wiederherstellung der Felder bedarf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9800] = {title = "Eine seltene Bohne", objective = "Bringt 8 verdaute Caracolibohnen zu Elementarist Lo'ap am Thron der Elemente.", description = "Ihr seid zu schlecht ausgerüstet um den rastlosen Elementaren Nagrands gegenüber zu treten. Bevor Ihr dem Irdenen Ring helfen könnt, müsst Ihr erst Euch selbst helfen.\n\nIm Westen findet Ihr Kothaufen von den Wildtieren Nagrands. Ihr müsst den Dung nach den verdauten Überresten der Caracolibohne durchsuchen. Aus dieser Bohne kann ich eine Tablette herstellen, die Euch im Kampf gegen die ruhelosen Naturgewalten helfen wird.\n\nKehrt zu mir zurück, wenn Ihr mindestens zwei Fäuste voller Caracolibohnen gesammelt habt... Ogerfäuste!", progress = "<Elementarist Lo'ap ballt seine Hände zu Fäusten und schüttelt den Kopf.>\n\nOgerfäuste...", completion = "Bitte wascht Euch nicht in den heiligen Wassern des Throns.\n\n&lt;Elementarist Lo'ap reicht Euch eine fertige Caracolitablette.&gt;\n\nLegt sie unter Eure Zunge und lasst sie sich auflösen. Einmal aufgelöst werdet Ihr Wasser wie Luft atmen können.", rewards = "Ihr bekommt:\n\nNagrandkirsche"}
MultiLanguageQuestData['de'][9801] = {title = "Die Reagenzien sammeln", objective = "Anachoret Ahuurn in Telredor möchte, dass Ihr ihm 4 Sporensegleraugen und 4 Fennschreitertentakel bringt.", description = "Ich habe das Gefühl, dass diese Verirrten nicht so gut auf einen Draenei zu sprechen sein werden, aber vielleicht auf einen Arakkoa. Ich kann einen Zaubertrank herstellen, der Euch für kurze Zeit in einen Arakkoa verwandeln kann. Dazu benötige ich ein paar Reagenzien, die man nur sehr schlecht lagern kann, da man sie sofort nach dem Sammeln weiterverarbeiten muss.\n\nIhr werdet mir ein paar Sporensegleraugen und einige Fennschreitertentakel bringen müssen. Beide Arten leben in der Wildnis um Telredor herum.", progress = "Habt Ihr die Reagenzien schon?", completion = "Diese Reagenzien eignen sich sehr gut. Bitte gebt mir einen Moment Zeit, um den Trank zu mischen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9802] = {title = "Pflanzen der Zangarmarschen", objective = "Bringt 10 unbekannte Pflanzenteile zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Die Seen der Zangarmarschen werden langsam entwässert. Wir wissen nicht warum, aber viele Pflanzenarten drohen auszusterben.\n\nAls Katalogisiererin der Expedition ist es meine Aufgabe, diese Pflanzen zu identifizieren und zu verstehen, was mit ihnen geschieht.\n\nWenn Ihr helfen wollt, bringt mir unbekannte Pflanzenteile. Wenn Ihr kräuterkundig seid, könnt Ihr sie direkt vom Boden pflücken, aber auch die einheimischen Wesen des Sumpfs tragen Pflanzenteile bei sich.", progress = "Habt Ihr ein paar Pflanzenteile gefunden, <Name>?", completion = "Das Abnehmen der natürlichen Arten ist ein Grund zur Sorge. Die Zunahme der eingewanderten Arten könnte mit der neuerlichen Störung des Ökosystems zusammenhängen. Ich habe jedoch noch zu wenig Anhaltspunkte, um Genaueres zu sagen.\n\n&lt;Lauranna macht ein paar Notizen in ein Buch, als sie die Pflanzenteile untersucht.&gt;\n\nNehmt ein paar davon, &lt;Name&gt;. Sie könnten vielleicht nützlich für Euch sein.\n\nBringt mir alle weiteren Pflanzenteile, die Ihr finden könnt. Ich werde sie in meiner Statistik auflisten.", rewards = "Ihr bekommt:\n\nPaket mit unbekannten Pflanzen"}
MultiLanguageQuestData['de'][9803] = {title = "Botschaft für den Wildfennstamm", objective = "Trinkt Ahuurns Elixier in den Ruinen von Boha'mu. Sprecht mit dem Ältesten Kuruti in der Form eines Arakkoas.", description = "Es ist an der Zeit, dem Wildfennstamm die Hand zu reichen und sie zu lehren, dass das Licht sie nicht aufgegeben hat. Nehmt den Trank, den ich vorbereitet habe, und tragt ihn zu den Ruinen von Boha'mu.\n\nSobald Ihr bei den Ruinen angekommen seid, trinkt den Trank um Euch in einen der Vogelgeister zu verwandeln. Sprecht mit dem Ältesten Kuruti und lasst ihn wissen, dass die Draenei bereit sind, sein Volk als verloren geglaubte Brüder und Schwestern zu empfangen.", progress = "Habt Ihr schon mit dem Ältesten von Wildfenn gesprochen?", completion = "Sie haben abgelehnt? Natürlich steht es ihnen frei, selbst zu wählen, aber ihre Entscheidung überrascht mich. Ich habe gedacht, dass alle Draenei, also auch die Zerschlagenen und Verirrten, sich daran erinnern würden, dass wir alle ein Volk sind.\n\nIch schätze er hat recht damit, dass es töricht war zu versuchen, sie hereinzulegen, aber trotzdem, konnte er denn nicht sehen, dass wir in freundlicher Absicht gehandelt haben?", rewards = "Mystikerhandlappen von WildfennBestienmeisterhalsberge von WildfennChampionstiefel von WildfennSchleichergürtel von WildfennIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9804] = {title = "Aufgebrachte Geister des Himmelsweisensees", objective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 8 Seegeister tötet.", description = "Die Unruhen in den Gezeiten der Gewässer von Nagrand hat die Wassergeister des Himmelsweisensees sehr aufgebracht. Sie haben im Gegenzug damit begonnen, Verwüstungen entlang der Wasserwege anzurichten.\n\nWatoosun des Wassers ist uns in einer Vision erschienen und hat uns erlaubt, das Problem zu lösen, solange wir auch die Ursache dafür beheben...\n\nWir werden uns um die Ursache kümmern, doch zuerst müssen wir die direkten Bedrohungen für den Thron beseitigen. Zerstört die aufgebrachten Seegeister und kehrt dann zu mir zurück.", progress = nil, completion = "&lt;Elementarist Lo'ap kniet im Wasser und betet.&gt;\n\nDer Irdene Ring ist nicht stolz auf das, was geschehen ist. Wir tun das, was wir müssen, um das Land zu heilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9805] = {title = "Segen des Incineratus", objective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr die große Hütte, die westliche Hütte, die südliche Hütte und die östliche Hütte in Schilftanz zerstört.\n\nBringt das beseelte Feuer zurück zu Elementarist Lo'ap, wenn Ihr fertig seid.", description = "Die erbärmlichen Verirrten, einst verbannt in die Sümpfe der Zangarmarschen, versuchen nun, ihren Dreck auch in andere Teile der Welt zu tragen.\n\nIch habe mich an die weisen Furien gewandt und ihren Segen erhalten. Um die Ursache zu beseitigen, müssen wir die Elemente auf sie hetzen!\n\nIch gebe Euch beseeltes Feuer, entzündet an der feurigen Essenz von Incineratus selbst. Reist nach Schilftanz, südöstlich von hier, und entzündet die Hütten mit dem Feuer! Lasst sie die Wut der Elemente spüren!", progress = "Es beschämt mich, dass mein eigenes Volk die Gewässer in Nagrand beeinflussen möchte, um ein Marschland zu erschaffen.", completion = "Eure Bemühungen haben die Ausbreitung der Verschmutzung eingedämmt, aber nun sind neue Probleme aufgetaucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9806] = {title = "Fruchtbare Sporen", objective = "Sammelt 6 fruchtbare Sporen von den Sporenseglern und den Marschenläufern der Zangarmarschen und kehrt danach zu Gshaff in Sporeggar zurück.", description = "Wenn sie zwischen den Langstielpilzen hindurchwandern, sammeln sich allerlei fruchtbare Sporen an den Gliedmaßen der Sporensegler und Marschenläufer.\n\nWie Ihr sehen könnt, ist unser Volk sehr klein, also haben wir nur wenige Möglichkeiten, diese Sporen zu sammeln. Haltet nach Sporenseglern und Marschenläufern Ausschau und sammelt die fruchtbaren Sporen. Ganz Sporeggar stünde tief in Eurer Schuld.", progress = "Ihr seid zurück, <Name>. Habt Ihr die fruchtbaren Sporen bekommen?", completion = "Diese Sporen sind perfekt, &lt;Name&gt;! Die Langstielpilze sind für den Wiederaufbau unseres Dorfs unerlässlich. Und seit den Angriffen der Sumpflords, die wir erdulden mussten, sind unsere Vorräte knapp!", rewards = "Ihr bekommt:\n\nGlühkappe"}
MultiLanguageQuestData['de'][9807] = {title = "Noch mehr fruchtbare Sporen", objective = "Wir können immer noch mehr fruchtbare Sporen gebrauchen, <Volk>. Langstielpilze sind unglaublich nützlich. Wir können sehr viel mit ihnen anstellen, wenn wir sie anbauen.", description = nil, progress = "Wir können immer noch mehr fruchtbare Sporen gebrauchen, <Volk>. Langstielpilze sind unglaublich nützlich. Wir können sehr viel mit ihnen anstellen, wenn wir sie anbauen.", completion = "Eure Hilfe wird sehr geschätzt, &lt;Name&gt;. Ihr werdet uns doch weiterhin helfen, oder?", rewards = "Ihr bekommt:\n\nGlühkappe"}
MultiLanguageQuestData['de'][9808] = {title = "Glühkappenpilze", objective = "Bringt 10 Glühkappen zu Msshi'fn in Sporeggar in den Zangarmarschen.", description = "Ich habe gesehen, dass Ihr glänzende runde Metallstücke benutzt, um sie gegen Dinge einzutauschen, die Ihr haben möchtet. Wir benutzen glänzende runde Pilze als Zahlungsmittel.\n\nDie Glühkappenpilze wachsen überall in den Marschen, man muss nur wissen, wie man sie richtig sammelt ohne sie zu zerstören. Ich werde Euch beibringen, wie man das tut, wenn Ihr mir versprecht, ein paar für unsere Vorräte zu sammeln. Einverstanden, <Name>?", progress = "Habt Ihr ein paar Glühkappen gefunden, <Name>? Sie wachsen fast überall in den Marschen.\n\nIhr könnt sie schon von weitem leuchten sehen, wenn Ihr genau hinschaut.", completion = "Die können wir prima bei den anderen Sporlingen gegen Essen und Vorräte eintauschen. Sporeggar dankt Euch, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9809] = {title = "Noch mehr Glühkappen", objective = "Wenn Ihr noch mehr Glühkappen habt, nehme ich sie Euch gerne ab. Unser Dorf kann sie immer gut gebrauchen.", description = nil, progress = "Wenn Ihr noch mehr Glühkappen habt, nehme ich sie Euch gerne ab. Unser Dorf kann sie immer gut gebrauchen.", completion = "Habt Dank, &lt;Name&gt;. Als Ältester von Sporeggar ist es meine Aufgabe dafür zu sorgen, dass mein Volk genügend Vorräte hat. Ihr erleichtert mir diese Aufgabe ungemein.", rewards = nil}
MultiLanguageQuestData['de'][9810] = {title = "Der verschmutzte Geist", objective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr Watoosuns verschmutzte Essenz und 8 Seewoger tötet.", description = "Watoosun konnte zwar den Seuchengestank loswerden, aber gleichzeitig erschuf er eine irrsinnige Geisteressenz. Eine Geisteressenz, die aus der übelsten Verderbnis entstanden ist, die es je unter Elementaren gegeben hat!\n\nIhr könnt diesen verschmutzten Sumpfgeist südwestlich von hier, tief im Sonnenwindsee, finden.\n\nSucht und vernichtet Watoosuns verschmutzte Essenz sowie jeglichen verseuchten Nachfahren, den sie erschaffen haben möge.", progress = nil, completion = "Die Elemente haben Euren Sieg besungen, als Ihr die verschmutzte Essens getötet habt. Der Irdene Ring dankt Euch und möchte, dass Ihr Euch eine Belohnung aussucht.", rewards = "Übergroße OgerhalsbergeAusgebesserte Schulterstücke der Ango'roshSeelenfressergugel der Ango'roshIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9811] = {title = "Freund der Sin'dorei", objective = "Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond.", description = "Dies ist der Beginn eines neuen Zeitalters in der Geschichte der Blutelfen <Name>. Ihr habt geholfen, den Bund zwischen unserem und Eurem Volk zu festigen, <Volk>.\n\nBringt den Kopf des Verräters nach Silbermond zum Lordregenten Lor'themar Theron. Er wird begierig sein, die Neuigkeit zu erfahren.", progress = "Ihr wünscht eine Audienz bei mir, <Klasse>? Ich kann mich nicht an eine Verabredung erinnern.", completion = "Ihr habt Dar'Khan also getötet, &lt;Volk&gt;? Beeindruckend. Ich habe das Gefühl, dass unsere und Eure Leute bald gute Freunde sein werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9812] = {title = "Gesandter zur Horde", objective = "Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.", description = "Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?\n\nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.\n\nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, <Name>. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.", progress = "Mir wurde gesagt, dass ich einen Besucher aus Quel'Thalas erwarten soll. Ehrlich gesagt hatte ich einen Blutelfen erwartet.\n\nWelche Neuigkeiten bringt Ihr?", completion = "Dann ist es also geschehen. Der gemeine Verräter hat bekommen, was er verdient hat.\n\nIhr habt den Blutelfen und der Horde einen großen Dienst erwiesen. Dar'Khan war Thralls Entschuldigung, um den Blutelfen den Eintritt in unser Bündnis zu verweigern. Jetzt habt Ihr den Weg für eine neue Horde bereitet, &lt;Name&gt;.\n\nWie ich sehe hat Lor'themar weitere Nachrichten, die seine Beziehungen zu Thrall deutlich verbessern werden. Ausgezeichnet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9813] = {title = "Ein Treffen mit dem Kriegshäuptling", objective = "Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zum Kriegshäuptling nach Orgrimmar, Hauptstadt von Durotar, bringt.", description = "Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Krallen und Zähnen gekämpft, damit Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.\n\nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zum Kriegshäuptling in Orgrimmar. Als Anführer der Horde hat er das letzte Wort bei der Entscheidung über die Bitte der Sin'dorei.\n\nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.", progress = "Ja, <Klasse>?", completion = "&lt;Thrall beginnt, den Brief zu lesen.&gt;\n\nDie Blutelfen haben sich also endlich ihres kleinen Problems entledigt. Dass Eure Hilfe und ein gesamtes Regiment der Verlassenen dafür nötig war, spielt ja keine Rolle.\n\n&lt;Thrall bricht in Gelächter aus.&gt;\n\nIch nehme an, dass wir das hier nicht aufhalten können. Schließlich brauchen wir sie genauso sehr, wie sie uns brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9814] = {title = "Berstkappenpilze, Mann!", objective = "Bringt Hexendoktor Tor'gash 6 Berstkappen.", description = "Mögt Ihr Pilze, Mann? Es gibt einen ganz mächtigen hier in den Zangarmarschen, wächst gleich in der Nähe von Zabra'jin.\n\nIhr müsst aber vorsichtig sein, Mann. Man nennt sie aus gutem Grund Berstkappenpilze. Wenn man ohne entsprechende Vorsichtsmaßnahmen zu nahe an sie herangeht, geht ihnen der Hut hoch! Puff! Und dann steht man in einer Wolke von giftigen Sporen.\n\nIch habe sie benutzt, um die Zukunft vorauszusagen, aber jetzt sind sie fast alle.", progress = "Habt Ihr die Pilze, Mann?", completion = "Die sind klasse, Mann!\n\nIch sag' Euch was. Weil Ihr so nett wart und mir mit den Pilzen geholfen habt, dürft Ihr beim Spaß dabeisein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9815] = {title = "Schlammtauchen", objective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 5 schlammbesudelte Kerne besorgt.", description = "Die am schwersten betroffenen Wasserelementare befinden sich im Halaanibecken, südwestlich von hier unterhalb der verlassenen Stadt Halaa. Während einige der verzweifelten Elementare ohne Folgen für die Umwelt zerstört werden können, müssen die Überreste der Schlammkreaturen nach ihrer Zerstörung entfernt werden.\n\nDie Schlammkreaturen hinterlassen nämlich verseuchte Leichenteile, die der Umwelt schaden können, wenn man sie liegen lässt.\n\nVernichtet diese Schlammkreaturen und bringt mir ihre schlammbesudelten Kerne.", progress = "Lasst keinen verseuchten Schlamm zurück!", completion = "Der Irdene Ring dankt Euch, &lt;Name&gt;. Auch die Elemente sind Euch dankbar. Eure wiederholten Bemühungen, unsere Welt zu reinigen, werden sehr geschätzt und sicher nicht vergessen.", rewards = "Lo'aps Tunika des SchlammtauchensLo'aps Polster des SchlammtauchensSchlammbesudelte GaloschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9816] = {title = "Habt Ihr so was schon mal gesehen?", objective = "Bringt den Murlockäfig nach Dolchfenn und stellt ihn auf den flachen Stein in der Nähe des Dorfs.", description = "In diesen Marschen fehlt was, Mann! Keine Murlocs hier.\n\nKeine Sorge, Mann, ich habe eine Lösung für dieses Problem. Seht Ihr Gargel und Gurgel da drüben? Ich habe vor, den Verirrten ein paar Murlocs zu schenken!\n\nBringt diesen Käfig nach Dolchfenn und lasst sie bei der Ansammlung von Hütten im Nordosten frei. Nun gut, ich möchte Euch nicht Gargel und Gurgel auf den Hals jagen, aber ich gebe Euch einen Käfig mit jungen bunten Murlocs. Setzt den Käfig einfach auf den flachen Stein, den Ihr dort finden werdet, und öffnet die Tür!", progress = nil, completion = "Ausgezeichnete Arbeit, Mann! Ich hoffe, sie hatten Spaß damit!", rewards = "Fußschützer des FennschreitersWickeltücher des HexendoktorsDolchfenn PanzerrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9817] = {title = "Anführerin der Blutschuppen", objective = "Tötet Rajis Fyashe am Schlangensee und kehrt dann zu Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.", description = "Hiermit setzt die Expedition des Cenarius ein Kopfgeld auf Rajis Fyashe, Anführerin der Blutschuppennagas, aus. Die Nagazauberin wurde zuletzt am Schlangensee gesehen, im Nordwesten der Zangarmarschen.\n\nDie Blutschuppen sind als extrem gefährlich einzustufen, und ihre Anführerin sollte mit äußerster Vorsicht behandelt werden.\n\nDas Kopfgeld kann bei Aufseher Hamuht in der Zuflucht des Cenarius eingefordert werden.", progress = nil, completion = "Ich wette, die Blutschuppen überlegen es sich nun zweimal, bevor sie unsere Späher nochmals angreifen. Nehmt dies als Belohnung, &lt;Name&gt;. Ihr habt es Euch verdient.", rewards = "Schuhwerk der ExpeditionHandschuhe der TreffsicherheitGürtel des MondkinWildnisschulterpolsterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9818] = {title = "Im Untergrund", objective = "Kommuniziert mit Gordawg.", description = "Etwas schändet den Untergrund. Es schlägt den Boden, als wollte es ihn bestrafen.\n\n*Rums*\n\n<Untrag schlägt sich mit der Faust auf die Brust.>\n\nSo klingt das hunderttausendmal. Endlos. Die Erde taumelt. Sie ruft nach uns.\n\nGordawg spricht mit mir. Gordawg weiß, dass etwas die Elementare hervortreibt. Etwas unter der Erde.\n\nGeht jetzt und sprecht mit Gordawg. Nein, hört ihm zu, sprecht nicht. Hört Gordawg an...", progress = nil, completion = "&lt;Gordawg scheint Euch zuzunicken.&gt;\n\nSetzt Euch.", rewards = nil}
MultiLanguageQuestData['de'][9819] = {title = "Die gequälte Erde", objective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 10 gequälte Erdgeister tötet.", description = "Bestraft den Thronräuber. Ihr werdet ihn finden. Folgt Pfad aus Erde. Zuerst bringt gequälte Erdgeister zur Ruhe. Müssen wieder schlafen.\n\n<Gordawg schlägt mit seiner Faust auf den Boden und schleudert faulig riechende Erde nach oben.>\n\nMüssen schlafen!\n\n<Gordawg zeigt nach Südosten.>\n\nSucht Geister in Nähe von Bergen. Nähe von Hügeln. Nähe von Erde.\n\nBringt zur Ruhe.\n\nTelaaribecken... Südosten.", progress = "Schlafen sie?", completion = "&lt;Gordawg nickt zufrieden.&gt;\n\nGut. Geister schlafen jetzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9820] = {title = "GESUCHT: Boss Grog'ak", objective = "Bringt Boss Grog'aks Kopf zu Schattenjäger Denjai in Zabra'jin.", description = "Gesucht - Tot oder lebendig: Boss Grog'ak, Vorarbeiter der Ango'rosh Pilzsammeloperation.\n\nDiese grobschlächtigen, axtschwingenden Dummköpfe sind für das Fällen von Pilzen nördlich des Dorfs verantwortlich. Wenn er nicht aufgehalten wird, werden er und seine Leute einen Pfad bis zu den Mauern von Zabra'jin schlagen!\n\nWer Boss Grog'aks Kopf zu Schattenjäger Denjai bringt, soll reich belohnt werden.", progress = "Was habt Ihr da, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Die Anwesenheit dieser Oger so nah an unserem Außenposten hat mich ein wenig beunruhigt. Es scheint, als kämen sie seit einiger Zeit die Berge im Norden herunter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9821] = {title = "Verdammnis schmecken", objective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr ihm 10 Kerne eines wütenden Zermalmers bringt.", description = "<Gordawg nimmt einen Stein und fängt an darauf herumzukauen.>\n\nGordawg schmeckt. Gordawg weiß wo diese Erde war.\n\n<Gordawg hebt eines seiner massiven Beine und stampft auf den Boden.>\n\nSchaut. Schaut Nagrand an.\n\n<Gordawg zeigt auf seinen Fußabdruck. Im Abdruck seht Ihr eine perfekte geologische Karte von Nagrand, auf der alle Stellen markiert sind, an denen die Elementare, die Ihr für Gordawg zerstören sollt, sich aufhalten.>\n\nZERSTÖRT SIE! Bringt Gordawg die Stücke zum Essen.\n\nNehmt die Karte.", progress = "Gordawg isst den Stein. Gordawg findet den Thronräuber. Bringt Stein!", completion = "&lt;Gordawg spuckt den gekauten Stein aus, woraufhin ein Steinschauer auf Euch herabrieselt.&gt;\n\nGift. Diese Felsen sind nicht Nagrand. Diese Felsen sind vergiftet. Ihr zerstört Giftfels. Ihr findet Thronräuber.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9822] = {title = "Drohender Angriff", objective = "Bringt die Angriffspläne der Ango'rosh zu Schattenjäger Denjai in Zabra'jin.", description = "Die Position der Pilzsammeloperation der Oger kann kein Zufall sein. Ich werde den Verdacht einfach nicht los, dass sie einen Angriff auf Zabra'jin planen.\n\nIch muss das genau wissen, <Name>. Die Oger haben einen weiteren Außenposten im Nordwesten beim Grund der Ango'rosh. Wenn sie tatsächlich vorhaben uns anzugreifen, dann werden wir dort sicher Beweise für ihre Pläne finden. Geht dorthin, <Name>, und durchsucht das Lager. Bringt mir alles, was auch nur im Geringsten verdächtig sein könnte!", progress = "Habt Ihr einen Beweis für die Pläne der Oger gefunden?", completion = "&lt;Schattenjäger Denjai untersucht die Pläne.&gt;\n\nIch wusste es! Der Gestank eines Ogers hat immer etwas Bedrohliches an sich. Jetzt, da wir einen Beweis für ihren Plan haben, müssen wir ihnen zuvorkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9823] = {title = "Sie oder wir", objective = "Tötet Oberanführer Schmetterfaust, 10 Raufer der Ango'rosh, 10 Seelenfresser der Ango'rosh und meldet Euch dann bei Schattenjäger Denjai in Zabra'jin zurück.", description = "Um die Bedrohung, die von den Ango'rosh ausgeht, zu beenden, müssen wir ihren Oberanführer Schmetterfaust töten. Aber wir werden sogar noch viel mehr tun. Wir werden mit dem Oberanführer und seinem Gefolge ein Zeichen setzen.\n\nGeht zur Festung der Ango'rosh und kümmert Euch um unsere Feinde. Die Feste befindet sich in einer Höhle auf einer kleinen Insel nordwestlich von Zabra'jin. Dort werdet Ihr eine Brücke, die aus einem umgefallenen Pilz besteht, finden.\n\nZeigt kein Erbarmen, <Name>. Sie würden sicher keinen von uns verschonen.", progress = nil, completion = "Unser Sieg über die Ango'rosh muss gefeiert werden, &lt;Name&gt;. Ich frage mich, wie lange es wohl dauert, bis diese Grobiane einen neuen, blutrünstigen Anführer gefunden haben.\n\nGanz gleich, wir werden auf sie vorbereitet sein!", rewards = "Ihr bekommt:\n\nHauptmann Kroshs SchmetterhelmPurpurbull Energietrank"}
MultiLanguageQuestData['de'][9824] = {title = "Arkane Störungen", objective = "Benutzt den violetten Aufzeichnungskristall in der Nähe von unterirdischen Wasserquellen im Keller des Meisters und kehrt zu Erzmagier Alturus außerhalb von Karazhan zurück.", description = "Ich versuche, eine Aufzeichnung von Karazhans Energie zu erstellen... für ein privates Projekt natürlich. Unglücklicherweise empfange ich hier oben einfach nichts. Wenn ich in die Nähe einer unterirdischen Wasserquelle gelangen könnte, könnten meine Kristalle die Signale viel leichter empfangen.\n\nIch habe sowohl von einem unterirdischen Teich als auch von einem Brunnen in einem Keller unter uns gehört. Dieser ganze Ort ist jedoch voll von Geistern, und sich dort hinzuwagen wäre für jemanden in meinem Alter viel zu gefährlich. Was sagt Ihr? Werdet Ihr einem alten Mann helfen und das Aufzeichnen für mich übernehmen?", progress = "Die Aufzeichnungen, <Name>. Habt Ihr sie beendet?", completion = "Diese Aufzeichnungen verheißen nichts Gutes, &lt;Name&gt;. Karazhan sollte alle möglichen arkane Ströme ausstrahlen... stattdessen herrscht dort nun ein riesiges Energievakuum. Keine Signale. Nichts. Außer einem sehr schwachen dämonischen Echo.\n\nDas sind schlechte Nachrichten, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9825] = {title = "Rastlose Aktivität", objective = "Bringt 10 geisterhafte Essenzen zu Erzmagier Alturus außerhalb von Karazhan.", description = "Wie Ihr sicher bemerkt habt, wimmelt es außerhalb von Karazhan nur so von Geistwesen. Der Grund ihrer Existenz ist unbekannt, und Unbekanntes mag ich gar nicht leiden!\n\nBringt mir ihre geisterhafte Essenz, damit ich ihre Beschaffenheit untersuchen kann. Karazhan hat viele Geheimnisse, <Name>. Und ich werde sie alle lüften.", progress = "Habt Ihr die Essenzen, die ich benötige, besorgt, <Klasse>?", completion = "Faszinierend. Ich werde die Essenzen untersuchen, &lt;Name&gt;. Ich danke Euch für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9826] = {title = "Dalarankontaktpersonen", objective = "Bringt Alturus' Bericht zu Erzmagier Cedric am Rande des Dalarankraters.", description = "Diese Zeichen bedeuten nichts Gutes für uns, <Name>. Ich hatte es noch nie so mit Geheimhaltung, deshalb erzähle ich Euch ein wenig über meine Organisation, das Violette Auge.\n\nWir sind Agenten der Kirin Tor, dem Magierrat von Dalaran. Wir wurden beauftragt, Karazhan und Medivh im Auge zu behalten, für den Fall, dass die Dinge aus dem Ruder laufen.\n\nWas sie auch taten... sehr bald nachdem Medivh verschwunden war.\n\nIn diesem Bericht stehen meine genauen Ergebnisse. Bringt ihn zu Erzmagier Cedric, er ist auch vom Violetten Auge. Ihr findet ihn am Rande des Dalarankraters.", progress = "Ihr wisst vom Violetten Auge? Ihr kommt mir nicht bekannt vor.", completion = "Alturus hat Euch diese Information anvertraut? Der alte Narr.\n\nIch schätze, der Schaden ist schon angerichtet, dann können wir Euch genauso gut für uns nutzen. Ich nehme an, Ihr werdet kooperieren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9827] = {title = "Siechendes Basidium", objective = "Bringt das siechende Basidium zu Ruam in Telredor in den Zangarmarschen.", description = "Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.\n\nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt, etwas mehr darüber erzählen.", progress = "Was habt Ihr da, <Name>?", completion = "Das sieht aus wie das Basidium eines Sumpflords, aber ich habe noch nie zuvor eines in einem solchen Zustand gesehen. Ich habe gehört, dass die Riesen im Todesmoor angefangen haben dahin zu siechen, aber es ist schon viel weiter fortgeschritten, als ich befürchtet habe.\n\nDas Todesmoor war einst ein See wie die anderen in den Marschen, und er diente als Nährgrund für die Riesen. Jetzt, da sich das Wasser zurückzieht, scheint es, als könnten sich die Riesen nicht länger vermehren. Wenn das so weitergeht, sterben die Riesen noch aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9828] = {title = "Siechendes Basidium", objective = "Bringt das siechende Basidium zu Reavij im Sumpfrattenposten in den Zangarmarschen.", description = "Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.\n\nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt etwas mehr darüber erzählen.", progress = "Was habt Ihr da, <Name>?", completion = "Das sieht aus wie das Basidium eines Sumpflords, aber ich habe noch nie zuvor eines in einem solchen Zustand gesehen. Ich habe gehört, dass die Riesen im Todesmoor angefangen haben dahin zu siechen, aber es ist schon viel weiter fortgeschritten, als ich befürchtet habe.\n\nDas Todesmoor war einst ein See wie kein anderer in den Marschen, und er diente als Nährgrund für die Riesen. Jetzt, da sich das Wasser zurückzieht, scheint es, als könnten sich die Riesen nicht länger vermehren. Wenn das so weitergeht, sterben die Riesen noch aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9829] = {title = "Khadgar", objective = "Bringt Alturus' Bericht zu Khadgar in Shattrath in den Wäldern von Terokkar.", description = "Alturus' Bericht ist beunruhigend. Wir dachten, es sei ein schlechtes Zeichen, als Karazhan sich von der Umwelt abgeschottet hat. Wir hatten dort Agenten, von denen wir nie wieder gehört haben. Und nun diese... dämonische Strömung. Wir müssen das untersuchen.\n\nDie Einzigen, die Karazhan wieder öffnen könnten, hielt man für tot: Khadgar und Medivh.\n\nWährend wir hoffen, das Letzterer tatsächlich tot ist, haben wir kürzlich in Erfahrung gebracht, dass sein Lehrling, Khadgar, gesund und munter an einem Ort namens Shattrath lebt. Findet ihn und gebt ihm Alturus' Bericht.", progress = nil, completion = "Das Violette Auge? Was Ihr nicht sagt.\n\nZeigt mir den Bericht, von dem Ihr sprecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9830] = {title = "Blutergift", objective = "Bringt 6 Einheiten Sumpflichtblutergift zu Puluu in der Oreborzuflucht.", description = "Wenn ich mich mit den Draenei unterhalte, habe ich immer den Eindruck, dass sie das Gefühl haben, aus ihrer natürlichen Umgebung herausgerissen zu sein. Viele scheinen meine Brüder und Schwestern, die Zerschlagenen, zu bedauern, weil sie glauben, dass wir etwas verloren haben.\n\nWir Zerschlagenen haben vielleicht unsere Verbindung zum Licht verloren, aber unsere Erfahrung hat uns enger an das Land gebunden.\n\nMein Volk erkennt Möglichkeiten, die den Draenei verschlossen bleiben. Nehmt zum Beispiel das Gift der Sumpflichtbluter, die im Süden und Westen leben. Es ist vielseitig einsetzbar, ob für die Jagd oder zur Heilung.", progress = "Ich hoffe, ich kann die Vorzüge des Fennblutergifts Anachoret Ahuurn und den anderen in Telredor zeigen. Aber dafür werde ich meine Vorräte verdoppeln müssen.", completion = "Vielen Dank für das Gift, &lt;Name&gt;. Jetzt kann ich es den anderen vorführen ohne meine eigenen Vorräte anfassen zu müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9831] = {title = "Nach Karazhan", objective = "Khadgar möchte, dass Ihr das Schattenlabyrinth von Auchindoun betretet und das erste Schlüsselfragment aus einem versteckten arkanen Behälter besorgt.", description = "Die Neuigkeiten in diesem Bericht beunruhigen mich sehr, <Name>. Es wird jedoch schwierig, sich Zugang zu Karazhan zu beschaffen.\n\nAls klar wurde, dass ich hier gestrandet bin, habe ich den Schlüssel in drei Teile zerbrochen.\n\nIch habe die Schlüsselfragmente in verzauberte Behälter gelegt, und diese dann an damals sicheren Plätzen versteckt.\n\nWegen der dunklen Veränderungen, die die Scherbenwelt durchmachen musste, sind sie heute allerdings alles andere als sicher. Das erste Fragment ist in einem Teil von Auchindoun versteckt, der nun vom Schattenrat beherrscht wird. Bringt mir dieses Fragment zurück.", progress = "Habt Ihr das Fragment besorgt, <Klasse>? Ihr solltet dabei besser keine Zeit verschwenden.", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ich war mir nicht sicher, ob Ihr Erfolg haben würdet.\n\nDie Behälter sind mit einem mächtigen Zauber belegt, der sie vor unwürdigen Augen beschützt. Ich bin froh, dass sie Euch nicht täuschen konnten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9832] = {title = "Das zweite und das dritte Fragment", objective = "Besorgt das zweite Schlüsselfragment aus einem arkanen Behälter im Echsenkessel und das dritte Schlüsselfragment aus einem arkanen Behälter in der Festung der Stürme. Kehrt dann zu Khadgar in Shattrath zurück.", description = "Ich habe das zweite Fragment am Boden des Schlangensees versteckt, noch lange bevor er so hieß. Der gigantische Ablauf, der dort installiert wurde, nachdem die Naga den Ort in Beschlag genommen hatten, hat den Behälter wahrscheinlich in die Tiefen des Echsenkessels gesogen.\n\nDas dritte Fragment wird eine besonders große Herausforderung werden, da ich es in der Festung der Stürme gelassen habe, als die Naaru dort noch herrschten. Kael'thas regiert dort jetzt, und das Zimmer, in dem sich das Fragment befindet, ist jetzt ein Gefängnis.\n\nBringt mir diese beiden Fragmente, <Name>. Von Eurem Erfolg hängt viel ab.", progress = "Wie kommt Ihr mit der Suche nach den Schlüsselfragmenten voran, <Name>?", completion = "Ihr habt die Fragmente. Ich bin sehr beeindruckt, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr es wert seid, den Schlüssel zu Karazhan zu besitzen.\n\nBleibt nur noch ein kleines Problem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9833] = {title = "Nachrichtenwege", objective = "Puluu in der Oreborzuflucht möchte, dass Ihr 12 Marschenfangschlitzer tötet.", description = "Einer der Gründe, warum uns Ikuti in die Zangarmarschen geführt hat, ist der Versuch, die Kommunikation zwischen den Draenei und Telaar, der Heimatstadt der Kurenai in Nagrand, zu verbessern. Damit die Boten schnell zwischen Telaar und Telredor hin- und herreisen können, müssen die Straßen sicher gemacht werden.\n\nAuf unserem Weg hierher wurden wir oft von Marschenfangschlitzern angegriffen. Wir konnten sie zwar abwehren, aber für einen einzelnen Boten wären sie eine besondere Bedrohung. Ihre Reihen etwas zu lichten würde viel zur Sicherheit unserer Boten beitragen.", progress = nil, completion = "Das sind wundervolle Nachrichten. Der Weg ist zwar immer noch nicht sicher, aber unsere Boten sind schlau und erfinderisch.", rewards = "Verhexte MarschenfangklingeWuchtiger MarschenfangschlitzerMarschenfangklingenaxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9834] = {title = "Natürliche Rüstung", objective = "Bringt 8 Fennklauenbälge zu Maktu in der Oreborzuflucht.", description = "Maktu kann einen Draenei über Meilen hinweg an seiner schimmernden Rüstung erkennen, sogar in diesem düsteren Sumpf!\n\nMaktu will sie auslachen, aber dann erinnert er sich, dass sie nett zu den Kurenai waren, und will ihnen beibringen, wie Kurenai Rüstung herstellen.\n\nDie dunklen, schuppigen Bälge der Fennklauen ergeben die beste Rüstung, die Maktu je getragen hat. Wenn <Name> Maktu ein paar dieser Bälge von den Fennklauenhauern tief im Schlangensee bringen kann, teilt er gerne seine Rüstung mit <Name>.", progress = "Hat <Name> die Bälge für Maktu?", completion = "Das sind gute Bälge, findet Maktu. Sie werden sehr gute Rüstung geben.\n\nWer weiß? Vielleicht sind es genug, damit Maktu ein paar Rüstungen für die Draenei machen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9835] = {title = "Vordringen der Ango'rosh", objective = "Tötet 10 Oger der Ango'rosh und 5 Schamanen der Ango'rosh und kehrt dann zu Ikuti in der Oreborzuflucht zurück.", description = "Die kleine Gruppe von Zerschlagenen, die Ihr dort seht, sind Gesandte einer Siedlung in Nagrand. Die Kurenai, wie wir uns selbst nennen, sind Zerschlagene, die sich gerne mit den Draenei wiedervereinen möchten.\n\nMeine Gruppe ist hierhergekommen, um die Bande zwischen den Kurenai und den Draenei in Telredor zu stärken.\n\nWenn es nach den Ogern der Ango'rosh geht, wird dieser Tempel nicht mehr lange stehen. Sie haben die hohen Pilze des Prügelsumpfs vollständig gerodet und kommen immer näher an unsere Zuflucht heran. Wenn Ihr <ein Freund/eineFreundin> unseres Volkes sein möchtet, dann helft uns, diesen Feind zu besiegen.", progress = nil, completion = "Für den Moment ist die Bedrohung durch die Ango'rosh gebannt, aber ich bin mir sicher, dass sie nicht so leicht aufgeben werden. Ich habe vieles von meinem früheren Leben als Draenei vergessen, aber die Hartnäckigkeit der Oger hat sich in mein Gedächtnis eingebrannt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9836] = {title = "Die Berührung des Meisters", objective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.", progress = "Wer seid Ihr und was wollt Ihr?", completion = "Ich erkenne diesen Schlüssel. Das ist Khadgars Schlüssel... ich habe ihn ihm natürlich noch nicht gegeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9837] = {title = "Rückkehr zu Khadgar", objective = "Kehrt zu Khadgar in Shattrath zurück und zeigt ihm den Schlüssel des Meisters.", description = "Ich scheine mich an zukünftige Ereignisse, die mit Euch und diesem Schlüssel zu tun haben, zu erinnern.\n\n<Medivh schaut Euch an, als hätte er einen Geist gesehen.>\n\nEuch stehen harte Zeiten bevor, <Name>. Wollen wir hoffen, dass Euch Eure Stärke nicht im Stich lassen wird.\n\nDen Schlüssel werde ich Khadgar geben, wenn er zu mir geschickt wird. Ich könnte mir keinen besseren Lehrling vorstellen.\n\nMeiner Meinung nach solltet Ihr einen eigenen Schlüssel bekommen.\n\n<Medivh fasst in seine Robe und reicht Euch seinen eigenen Schlüssel.>\n\nNun zieht weiter. Und viel Glück, <Klasse>.", progress = nil, completion = "Sein eigener Schlüssel? Das ist unglaublich!\n\nIch spüre keine Störungen in unserer Zeitlinie, also nehme ich an, dass dies von vorneherein so bestimmt war. Jetzt gibt es kein Zurück mehr, &lt;Name&gt;. Der Schlüssel gehört Euch und nur Euch.", rewards = "Ihr bekommt:\n\nDer Schlüssel des Meisters"}
MultiLanguageQuestData['de'][9838] = {title = "Das Violette Auge", objective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan.", description = "Ihr wurdet mit einer großen Verantwortung betraut, <Name>. Wenn man den Zeichen, die das Violette Auge beobachtet hat, trauen kann, müsst Ihr ihnen helfen.\n\nTrotz all meiner Unstimmigkeiten mit Cedric halte ich die Arbeit von Männern wie Alturus immer noch für sehr wichtig. Achtet jedoch darauf, dass sie Euch nicht ausnutzen. Denkt immer daran, dass der Schlüssel an Euch gebunden ist, nicht an sie. Aber wenn die Bedrohung in Karazhan wirklich echt ist, dann sind sie am besten dafür geeignet, Euch darauf vorzubereiten. Kehrt zurück zu Alturus und helft ihm, wo immer Ihr könnt.", progress = nil, completion = "Ich schicke Euch, um einen Bericht abzuliefern, und Ihr kommt mit einem Schlüssel zurück? Es muss mehr an Euch sein, als man mit dem bloßen Auge erkennen kann, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9839] = {title = "Oberanführer Schmetterfaust", objective = "Ikuti möchte, dass Ihr Oberanführer Schmetterfaust und 10 Raufer der Ango'rosh tötet. Kehrt zur Oreborzuflucht zurück, wenn Ihr die Aufgabe erfüllt habt.", description = "Das Herzstück jedes Ogerstamms ist sein Anführer. Ohne Anführer werden die Ango'rosh sich zurückziehen und unter sich auskämpfen, wer der nächste Anführer wird.\n\nObwohl wir die Oger überall verstreut in dieser Gegend gesichtet haben, ist die Festung der Ango'rosh im Nordwesten ihre eigentliche Machtbasis. Sie liegt in einer Höhle auf einer kleinen Insel, die nur durch einen umgestürzten Pilz mit den Marschen verbunden ist.\n\nGeht dort hin und besiegt Oberanführer Schmetterfaust. Das sollte uns eine wohlverdiente Ruhepause geben.", progress = "Seid Ihr fertig? Habt Ihr Oberanführer Schmetterfaust besiegt?", completion = "Endlich! Vielen Dank für die Hilfe bei der Sicherung unserer Stellung hier in der Oreborzuflucht. Ich werde den Kurenai in Telaar in Nagrand von Euren Taten berichten. Es werden sich noch viele Gelegenheiten bieten, in denen unsere Völker zusammenarbeiten können.", rewards = "Kuriersumhang von TelaarArmschienen der MarschenAuf Euch wartet eine dieser Belohnungen:\n\nLeuchtendes Kristallinsigne\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9840] = {title = "Einschätzung der Situation", objective = "Findet Koren in Karazhan.", description = "Jetzt, da wir - oder besser Ihr - einen Weg zurück in Medivhs' Turm gefunden haben, müssen wir als Erstes herausfinden, wie die Situation im Inneren aussieht.\n\nEine unserer Agentinnen hat es geschafft, sich in Karazhan einzuschleusen und hielt ihre Beobachtungen in verschlüsselten Aufzeichnungen fest. Unglücklicherweise wurden wir über ihren Tod informiert, kurz bevor Karazhan geschlossen wurde. Koren, der Schmied von Karazhan, wird von uns bezahlt. Auch wenn er kein Mitglied des Violetten Auges ist, wird er uns sicher helfen können, Keannas Aufzeichnungen zu finden. Sucht ihn innerhalb von Karazhan.", progress = nil, completion = "&lt;Koren sieht Euch unsicher an.&gt;\n\nIch weiß nichts von diesem Violetten Auge, von dem Ihr da redet. Ich bin ein Schmied, sonst nichts.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9841] = {title = "Tückische Mücken", objective = "Tötet 8 Sumpflichtbluter und kehrt dann zu Gambarinka in Zabra'jin zurück.", description = "Ich kann mit diesem infernalen Gesumme nicht arbeiten! Könnt Ihr es hören?\n\nIch bekomme es nicht mehr aus meinem Kopf! Ich weiß genau, wer dieses Geräusch verursacht, Sumpflichtbluter! Das Geräusch kommt immer vom Süden und vom Westen des Dorfs her.\n\nSie sind zu groß, um sie mit einer Fliegenklappe zu erschlagen, sie unter dem Fuß zu zerquetschen oder fortzuwedeln. Der einzige Weg dieses fürchterliche Dröhnen zu beenden ist sie zu töten. Mir ist ganz egal, wie Ihr es tut, <Name>, aber bringt sie zum Schweigen!", progress = nil, completion = "Dachte ich es mir, Ich kann den Unterschied schon deutlich hören. Dank Euch werde ich endlich wieder arbeiten können. Falls Ihr jemals Handwerkswaren benötigen solltet, denkt an den alten Gambarinka!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9842] = {title = "Die schärfsten Klingen", objective = "Bringt 10 Marschenfangschlitzerklingen zu Gambarinka in Zabra'jin.", description = "Das feuchte Klima der Marschen hat meine metallenen Werkzeuge stark in Mitleidenschaft gezogen. Das macht die Holzarbeiten schwerer als sonst, weshalb ich nun ganz auf Metallklingen verzichte.\n\nEs hat sich herausgestellt, dass die Marschenfangschlitzer im Süden und im Westen über Klingen verfügen, die schärfer sind als jede Metallklinge, die ich je besessen habe. Sie rosten auch nicht und nutzen sich nicht ab. Es ist nur ein wenig schwer, sie an einem Griff zu befestigen, aber ich glaube, ich habe dieses Problem bereits gelöst. Ich wäre Euch für jede Klinge, die Ihr mitbringen könnt, sehr dankbar.", progress = "Habt Ihr ein paar Marschenfangklingen auftreiben können?", completion = "Die sollten mir für eine Weile genügen! Ich glaube, ein paar andere sind schon darauf aufmerksam geworden. Ich hatte schon ein paar Angebote, mir die Klingen abzukaufen. Sie nebenbei zu verkaufen könnte vielleicht ein einträglicheres Geschäft als meine herkömmlichen Waren bieten.", rewards = "Verhexte MarschenfangklingeWuchtiger MarschenfangschlitzerMarschenfangklingenaxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9843] = {title = "Keannas Aufzeichnungen", objective = "Durchsucht die Gästezimmer in Karazhan nach Keannas Aufzeichnungen und bringt sie zu Erzmagier Alturus außerhalb von Karazhan.", description = "Wen sucht Ihr noch gleich? Keanna?\n\nIch habe einst jemanden mit diesem Namen getroffen. Sie wohnte oben in den Gästezimmern. Das hätte ich nicht verraten dürfen, oder?\n\nSagtet Ihr, Ihr gehört zum Violetten Auge? Nein, davon habe ich noch nie gehört.\n\nIch muss jetzt zurück an die Arbeit, wenn es Euch nichts ausmacht.\n\n<Koren scheint Euch schon vergessen zu haben.>", progress = "Keannas Aufzeichnungen... habt Ihr sie gefunden?", completion = "Ihr habt die Aufzeichnungen gefunden. Ich hoffe, dass die Information, die wir brauchen, auch hier drin stehen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9844] = {title = "Eine dämonische Präsenz", objective = "Erzmagier Alturus möchte, dass Ihr die dämonische Präsenz an der Turmspitze von Karazhan zerstört.", description = "Keannas letzte Einträge bestätigen unseren Verdacht, dass sich eine dämonische Präsenz in Karazhan befindet.\n\nSie hat die Ankunft eines Agenten der Brennenden Legion entdeckt, der sich in der Nähe der Turmspitze aufhalten soll.\n\nIhr Eintrag endet hier.\n\nKarazhan ist ein sehr wichtiger Ort, <Klasse>. Es ist ein Portal in den Nether, ein Leuchtfeuer, das in andere Welten scheint. Wenn es in falsche Hände gerät, sind die Folgen unvorstellbar. Das Eindringen der Dämonen muss unbedingt aufgehalten werden. Und außer Euch, <Name>, hat niemand einen Schlüssel.", progress = "Ich scheue mich zu fragen, <Name>, aber wie sieht es mit der Situation in Karazhan aus?", completion = "Ihr habt es geschafft! Ja, die Aufzeichnungen normalisieren sich wieder!\n\nDas müssen wir Cedric berichten. Er wird von unseren Errungenschaften sehr beeindruckt sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9845] = {title = "Anglerunglück", objective = "Tötet 10 Fennklauenhauer und kehrt dann zu Zurjaya in Zabra'jin zurück.", description = "Welch Erleichterung, dass ich endlich an einem Ort mit Wasser angekommen bin! Ich hatte schon Angst, dass es keine anständigen Fischgründe hier in der Scherbenwelt gibt.\n\nJetzt bin ich doch froh, dass ich meine Angelausrüstung mitgenommen habe. Und das Fischen läuft soweit auch ganz gut, wenn da nicht diese nichtsnutzigen Fennklauenhauer im Schlangensee wären.\n\nSie verscheuchen mir nicht nur die Fische, sondern sind auch noch frech genug, mir die Köder direkt vom Haken zu stehlen! Ich verbringe mehr Zeit damit, neue Köder anzubringen, als tatsächlich etwas zu fangen!", progress = nil, completion = "Ich kann es gar nicht erwarten endlich wieder angeln zu gehen. Jetzt werde ich endlich mit echten Fischen in meinem Eimer ins Dorf zurückkehren können, und Gambarinka wird sich nicht mehr über mich lustig machen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9846] = {title = "Geister der Wildfenn", objective = "Bringt 10 Schutztotems von Wildfenn zu Seherin Janidi in Zabra'jin.", description = "Der mächtigste Stamm der Verirrten in den Marschen, der Wildfennstamm, soll eine mächtige Medizin besitzen. Vielleicht ist an solchen Gerüchten nichts Wahres dran, aber ich muss allem nachgehen, was mir dabei helfen kann, die Geister dieser Welt zu lenken.\n\nFindet die Mystiker, Jäger und Druiden von Wildfenn, <Name>, und nehmt Euch ihre Totems. Alles, was ich wissen muss, werde ich aus den Schnitzereien erfahren können.", progress = "Habt Ihr die Totems schon gesammelt?", completion = "Hmm... Es scheint, als wäre die eine Hälfte mit Bildern von Schlangegeister, die andere mit Bildern von Vogelgeistern verziert. Kein Dunkelspeertroll mit Selbstachtung würde jemals Vögel verehren. Ihre Geister sind schwach, launisch und besser bei den Schamanen der Amani aufgehoben.\n\nAber die Schlange, &lt;Name&gt;, die Schlange hat beträchtliche Kräfte und ist daher der Geist, dem ich meine Studien widmen werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9847] = {title = "Ein verbündeter Geist?", objective = "Bringt das Wildfenntotem an den Fuß der Treppe in den Ruinen von Boha'mu und verankert es im Boden. Berichtet Seherin Janidi in Zabra'jin von Euren Beobachtungen.", description = "Wir müssen herausfinden, welche Kräfte dieser Schlangengeist von Wildfenn besitzt und ob wir sie für unsere Zwecke einsetzen können. Stellt Euch nur vor, was ich alles tun könnte, wenn ich über einen Geist der Scherbenwelt befehligen könnte!\n\nNehmt dieses Totem und begebt Euch an den Fuß der Treppe zu den Ruinen von Boha'mu. Verankert das Totem dort in der Erde, den Rest wird es selbst erledigen. Der Geist dürfte nicht wissen, wer das Totem benutzt hat, bis er sich manifestiert hat.", progress = "Konntet Ihr den Geist von Wildfenn rufen?", completion = "&lt;Ihr berichtet Seherin Janidi, was passiert ist, als Ihr das Totem benutzt habt.&gt;\n\nDer Geist hat euch angegriffen? Er muss diesen Verirrten wohl mehr zugetan sein, als ich dachte. Es gibt keine Möglichkeit, ihn mir gefügig zu machen, ohne immensen Aufwand zu betreiben. Ich muss mich wohl nach einer anderen Quelle der Macht in dieser elenden Welt umsehen.", rewards = "Tuch des SchlangengeistsArmschienen der MarschenAuf Euch wartet eine dieser Belohnungen:\n\nUraltes Kristallinsigne\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9848] = {title = "Geheimnisse des Dolchfennstamms", objective = "Bringt das Gifthandbuch von Dolchfenn und eine Giftphiole von Dolchfenn zu Timothy Daniels in der Oreborzuflucht.", description = "Käfer, Käfer, Käfer! Die Marschen sind voll davon, und meine Gefährten hier scheinen ganz besessen von ihnen zu sein.\n\nNun, ich habe genug von Käfern! Etwas viel Aufregenderes hat mein Interesse geweckt. Im Westen gibt es ein Dorf der Verirrten, das Dolchfenn genannt wird.\n\nDer gesamte Stamm besteht aus hochbegabten Auftragsmördern. Ich habe gesehen, wie sie ein bestimmtes hochwirksames Gift mischen und verwenden. Ich würde liebend gerne mehr darüber erfahren, aber dazu bräuchte ich eine Abschrift des Rezepts und eine Phiole mit einer Probe des Gifts.", progress = "War Eure Suche in Dolchfenn nach den Informationen, die ich zur Lösung des Gifträtsels benötige, erfolgreich?", completion = "&lt;Timothy blättert das Handbuch durch.&gt;\n\nSie benutzen Zottelkappe als Grundlage für das Gift? Nein, das kann nicht richtig sein. Zottelkappe ist nicht giftig.\n\nZottelkappe in ein Gift zu mischen ist so sinnvoll, wie einem Schurken zwei Streitkolben in die Hand zu drücken. Sicher, man kann das zwar tun, aber das entspricht nicht dem Wesen Eurer Berufung! Ich kann das einfach nicht verstehen...\n\n&lt;Timothy räuspert sich.&gt;\n\nNun ja, danke dass Ihr mir das hier besorgt habt. Ich werde das Gift ausprobieren, sobald die Zeit es mir erlaubt.", rewards = "Ihr bekommt:\n\nTims zuverlässiger HelmPurpurbull Energietrank"}
MultiLanguageQuestData['de'][9849] = {title = "Die Maskerade durchschauen", objective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 30 Diener von Gurok tötet.", description = "<Gordawg bricht einen ebenholzfarbenen Fels von seinem Rücken ab.>\n\nIch gewähre Euch ein Stück Wut der Erde. Nehmt Gordawgs Fels und werft ihn auf den Giftfels. Zerschlagt ihre Hüllen um die Wahrheit zu erfahren. Vernichtet die Diener des Thronräubers und kehrt mit dem Namen zu Gordawg zurück.\n\nIhr findet die zerschlagenen Elemente am Ende der Welt. Südwesten.", progress = "Gordawg will den Stein zurück.", completion = "GUROK! Gurok hat die Elemente verraten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9850] = {title = "Beherrschen der Grollhufjagd", objective = "Tötet 12 Grollhufbullen und sprecht anschließend mit Hemet Nesingwary bei Nesingwarys Safari in Nagrand, um Euer Jagdgeschick zu beweisen.", description = "Ihr habt mir gezeigt, dass Ihr in der Lage seid, die harmlosen Exemplare der Grollhufe zu erlegen. Doch viel gefährlicher sind die Bullen.\n\nErledigt zwölf von denen. Dann könnt Ihr Euch vor mir mit Eurem Jagdgeschick brüsten.\n\nIhr findet sie überall im Westen und Süden der mittleren Regionen Nagrands.", progress = nil, completion = "Beeindruckend, sehr beeindruckend.\n\nIhr habt Potential, Jungspund. Ich werde Euch die Möglichkeit geben, richtig viel Spaß zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9851] = {title = "Beherrschen der Grollhufjagd", objective = "Erlangt das Horn von Banthar und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück.", description = "Das Grollhufweibchen Banthar ist der meistgefürchtete und am schwersten zu fassende Grollhuf der gesamten Scherbenwelt. Sie ist außerdem das Exemplar mit dem längsten Fell ihrer Gattung.\n\nMan sagt, sie treibt sich auf den Geisterfeldern in der Nähe des Oshu'gun herum.\n\nBringt mir ihr Horn, um mir endgültig Euer Können in den Jagdkünsten zu beweisen.", progress = "Ein warmes Feuer und eine Frau an Eurer Seite könnt Ihr daheim finden. Hier jagen wir ernsthaft oder sterben bei dem Versuch.", completion = "Ihr habt es tatsächlich geschafft! Ihr habt Banthar erlegt! Ich habe niemals an Euch gezweifelt, &lt;Name&gt;.\n\nHier, ich denke, das habt Ihr Euch redlich verdient.", rewards = "GrollhufhelmGrollhufhandschuheGrollhufhandgelenksschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9852] = {title = "Die ultimative Beute", objective = "Bringt das Herz von Zahna zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand.", description = "Die Königin aller Tiere in Nagrand ist Zahna. Sie ist ein riesiger Elekk von der Sorte, wie Ihr sie woanders nie zu sehen bekommen werdet!\n\nIhr tut gut daran, Euch bei dem Namen zu erschrecken. Bach'lor, Aaskralle und Banthar sind nichts im Vergleich zu ihr. Man sagt, dass sie sich auf einer riesigen Klippe weit im Südwesten in der Nähe des Oshu'gun aufhält. Bringt mir ihr Herz, wenn Ihr Euch traut.\n\nWollt Ihr mir einen Brief für Eure Familie dalassen, falls Ihr, was sehr wahrscheinlich ist, nicht zurückkommt?", progress = "Es ist keine Schande zuzugeben, dass Ihr nicht den Mumm habt, eines der mächtigsten Tiere die dieses Land zu bieten hat, zu erlegen, <Name>.", completion = "&lt;Name&gt;! Ihr bringt das Herz dieses alten Zwergs zum Springen.\n\nIhr habt Euch nun bewiesen und seid in die Eliteränge aufgestiegen! Andere sind voller Angst geflüchtet, sind gestorben oder wurden unter den Füßen des Tieres zerquetscht. Ihr habt Euren Verstand, Eure List und Eure Entschlossenheit genutzt, um zu beweisen, dass Ihr die Jagd beherrscht.\n\nNehmt dies und seid gewiss, dass Ihr jederzeit zur Jagd an meiner Seite willkommen seid.", rewards = "Hemets ElekkjagdgewehrNesingwarys SafaristabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9853] = {title = "Gurok der Thronräuber", objective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr Gurok den Thronräuber zerstört und Guroks irdenen Kopf besorgt.", description = "Gurok muss gerufen werden. Ihr ruft Gurok und Ihr vernichtet.\n\nIhr müsst zum Totschlägerhügel im Nordwesten gehen und suchen, wo Oger Gurok verehren. Ihr setzt Ogerschädel von Totschläger auf Guroks irdenes Brandmal. Nur dann kommt Gurok. Sieben Schädel.\n\nWenn Ihr lebt, dann bringt Guroks irdenen Kopf zu Gordawg. Gordawg zerschmettert Kopf.\n\n<Gordawg beißt die Zähne so fest zusammen, dass der Boden unter Euren Füßen bebt.>", progress = "Gordawg isst Gurokpulver.", completion = "&lt;Gordawg beißt fest in Guroks irdenen Kopf und bringt die Steinformation fast zum Bröckeln.&gt;\n\nGuroks Herrschaft ist zu Ende. Die Erdelementare sind frei. Schlafen alle. Gewinner bekommt Preis!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nIrdenes Mal der MachtIrdenes Mal der GesundheitIrdenes Mal der Vernichtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9854] = {title = "Beherrschen der Windrocjagd", objective = "Tötet 12 Windrocs und kehrt dann zu Fitz bei Nesingwarys Safari in Nagrand zurück.", description = "Lebt Ihr genauso für die Jagd wie ich, <Klasse>? Sucht Ihr die Ruhe, die Euch überkommt, wenn Ihr Euch an Eure Beute heranpirscht? Wisst Ihr, was es bedeutet, die letzten Herzschläge der erlegten Beute zu ehren? Ich werde Euch helfen, dies zu erreichen.\n\nNagrand ist ein blühendes Land, voller Leben inmitten dieser zerschlagenen Welt. Erlegt ein paar Windrocs und dann unterhalten wir uns weiter.\n\nIhr könnt sie an vielen Orten um unser Lager herum finden.", progress = nil, completion = "Jeder Tag ist ein Geschenk. Macht das Beste daraus. Denn schon morgen werden wir uns schneller fortbewegen als heute. Wir werden unsere Arme weiter ausbreiten und uns anstrengen, um das zu erzielen, von dem wir heute Nacht noch träumen, auch wenn wir es vielleicht nie erreichen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9855] = {title = "Beherrschen der Windrocjagd", objective = "Tötet 12 gefräßige Windrocs und kehrt dann zu Fitz bei Nesingwarys Safari in Nagrand zurück.", description = "Ihr müsst immer im Training bleiben, wenn Ihr eines Tages die mächtigste Beute überhaupt erlegen möchtet! Jetzt seid Ihr noch nicht dafür bereit, aber ich werde Euch auf den richtigen Weg bringen.\n\nEs gibt noch eine tödlichere Art von Windrocs. Messt Euch an den gefräßigen Windrocs! Ihr findet sie im Herzen von Nagrand, im Süden und im Südwesten.", progress = nil, completion = "Ihr habt Eure Fähigkeiten erneut unter Beweis gestellt, &lt;Klasse&gt;. Jetzt müsst Ihr Euch mit der wildesten Sorte von Windrocs messen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9856] = {title = "Beherrschen der Windrocjagd", objective = "Bringt das Auge von Aaskralle zu Fitz bei Nesingwarys Safari in Nagrand.", description = "Ihr seid bereit, <Klasse>. Bereit Euch der Mutter aller Windrocs zu stellen, Aaskralle! Nachdem Ihr so viele ihrer Kinder getötet habt, gebietet die Ehre, dass ihr eine Chance auf Rache gewährt wird. Ihr findet sie bei den großen Windrocs weit im Westen.\n\nWenn Ihr überleben solltet, bringt mir ihr Auge.", progress = "Habt Ihr Euch Aaskralle schon gestellt?", completion = "Ihr Auge sieht aus, als wäre es noch am Leben. Denkt Ihr, sie kann immer noch in Eure Seele schauen?\n\n&lt;Name&gt;, Ihr könnt Euch zu den Elitesafarijägern zählen. Und Ihr seid auf dem besten Weg, die entscheidende Beute dieses Landes zu jagen, Zahna!\n\nIhr habt Euch das hier verdient. Möge es Euch gute Dienste leisten.", rewards = "WindrocschienbeinschützerWindrocstiefelWindroctuchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9857] = {title = "Beherrschen der Talbukjagd", objective = "Tötet 12 Talbukhirsche und kehrt dann zu Harold Fährten bei Nesingwarys Safari in Nagrand zurück.", description = "Ich habe heute keine Lust zu jagen. Könnt Ihr das für mich übernehmen?\n\nIch habe Hemet gesagt, dass ich mich um ein paar von den Talbuks kümmern würde, die hier überall herumlaufen. Die Böcke sind besonders gut zu jagen. Ihr könnt sie in kleinen Gruppen unter den Bäumen in der Nähe finden.\n\nDenkt Ihr, Ihr könntet das für mich tun?", progress = nil, completion = "Das ist schon eine tolle Geschichte...&lt;hust&gt;...wie Ihr all die Hirsche erlegt habt, &lt;Klasse&gt;. Aber das könnt Ihr sicher noch besser. Ich habe da etwas anderes für Euch im Auge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9858] = {title = "Beherrschen der Talbukjagd", objective = "Erlegt 12 Talbukdornzehrer und kehrt dann zu Harold Fährten bei Nesingwarys Safari in Nagrand zurück.", description = "Diese verdammte Schramme macht mir echt zu schaffen. Also, habt Ihr Lust, nochmals...<hust>...für mich einzuspringen?\n\nDieses Mal werdet Ihr ein paar Dornzehrer erlegen. Sie sind härter und gerissener als die Hirsche, also seid auf der Hut. Sucht sie...<hust>..unter den Bäumen in den mittleren Gebieten Nagrands im Süden und Westen.\n\nAuf, geht los und...<hust>.. zeigt Hemet aus welchem Holz Ihr geschnitzt seid. Mir wird es schon gut gehen.", progress = nil, completion = "&lt;hust&gt;, &lt;hust&gt;... &lt;Name&gt;! Ihr habt es geschafft. Jetzt gibt es... ...nur noch eine Sache......zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9859] = {title = "Beherrschen der Talbukjagd", objective = "Besorgt den Huf von Bach'lor und bringt ihn zu Harold Fährten bei Nesingwarys Safari in Nagrand.", description = "<Schlimmer Husten.>\n\nMacht Euch keine Sorgen um...<hust>... mich. Mir geht es gut. Es ist nur ein...<hust>... Kratzer.\n\nDennoch müsst Ihr...<hust>... nochmal für mich...<hust>... einspringen.\n\nIhr müsst den großen Bach'lor, König der Hirsche...<hust>... finden.\n\nBringt mir einen seiner Hufe...<hust>, <hust>... als Beweis.\n\nEr führt seine Herde...<hust>... weit im Westen von Nagrand.", progress = "<Harold schaut geschwächt zu Euch hoch und ringt sich ein Lächeln ab.>\n\nHabt Ihr...<hust>... den Huf?", completion = "Wow! Ihr habt es geschafft! Das ist tatsächlich Bach'lors Huf!\n\nÄhm, wie es aussieht fühle ich mich schon viel besser. Hier, lasst mich Euch etwas zur Feier Eures Jägerkönnens schenken!", rewards = "TalbukspornTalbukdolchTalbukcapeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9860] = {title = "Neue Anweisungen", objective = "Sprecht mit Erzmagier Cedric am Rande des Dalarankraters.", description = "Kehrt sofort zu Cedric zurück, <Name>. Die Unterstützung, die Ihr dem Violetten Auge geleistet habt, wird nicht unbelohnt bleiben.\n\nHaltet von uns und unserer Organisation was Ihr wollt, <Klasse>, aber in der Gunst der Erzmagier von Dalaran zu stehen ist nichts, was Ihr je bereuen werdet.", progress = nil, completion = "Alturus hat mir erzählt, was passiert ist, &lt;Name&gt;. Wir sind jedoch noch nicht am Ende angelangt. Solange Karazhan für die Außenwelt verschlossen ist, ist es nur eine Frage der Zeit, bis die Legion ihre Angriffe erneuert, während wir nur tatenlos zusehen können.\n\nEs sei denn natürlich, Ihr nehmt die Verantwortung, die Euch das Schicksal auferlegt hat, an.\n\n\n\nWas sagt Ihr, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\nViolettes Abzeichen"}
MultiLanguageQuestData['de'][9861] = {title = "Der heulende Wind", objective = "Sucht beim Thron der Elemente nach jemandem, der Kalimag sprechen kann und zeigt der Person den heulenden Wind.", description = "Die formlose Elementarluftgestalt spricht in einer Sprache zu Euch, die Ihr nicht versteht. Ihr glaubt, dass es die Sprache der Elemente ist, Kalimag. Vielleicht kann Euch jemand beim Thron der Elemente mit dieser ungewöhnlichen Entdeckung weiterhelfen.", progress = "Gebt es her, schnell!", completion = "Es ist ein Notruf, &lt;Volk&gt;. Eine Macht versucht die Elemente zu untergraben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9862] = {title = "Bösewichte der Finsterblut", objective = "Elementarist Morgh beim Thron der Elemente in Nagrand möchte, dass Ihr 5 Verderber der Finsterblut tötet.", description = "Der Finsterblutstamm fängt die Luftgeister ein und quält sie! Die Finsterblut gehören zu meinem Volk. Sie sind ein Stamm von Zerschlagenen, der dem bösen Musel'ek, dem Sumpflord des Echsenkessels, dient.\n\nDer Luftgeist sagt, dass die Verderber der Finsterblut andere Luftgeister fangen und sie benutzen, um Chaos in den Reihen der Elemente zu säen. Wie es aussieht haben die Finsterblut vor Kurzem ein Orcdorf im Südwesten namens Sonnenwind geplündert und benutzen nun mächtige Elementarmagie, um den See aufzuwühlen. Sucht die Verderber und vernichtet sie!", progress = nil, completion = "Ihr habt gesehen, wie sie die Elemente kontrollieren? Der Wind beugt sich ihrem Willen?\n\n&lt;Morgh versinkt für einen Moment in Gedanken.&gt;\n\nDas ist sehr beunruhigend, &lt;Name&gt;. Ich muss mich mit den anderen beraten.\n\nVielen Dank für Eure Mühen, &lt;Name&gt;. Vielleicht solltet Ihr in Euer Dorf zurückkehren und Euch umhören, ob es weitere Informationen über die Finsterblut und ihre schändlichen Ziele gibt.", rewards = "Schiftung des RingsStulpen des RichtersKordel des RingsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9863] = {title = "Abscheulicher Götzendienst", objective = "Scharfseher Kurkush in Garadar in Nagrand möchte, dass Ihr ihm 10 Finsterblutgötzen bringt.", description = "Ohne Führung sind wir von allen Seiten angreifbar! Die niederträchtigen Finsterblut hätten keinen besseren Zeitpunkt auswählen können, um uns anzugreifen.\n\nIn den letzten Tagen mussten wir nicht weniger als fünf Angriffe von den Zerschlagenen ertragen! Sie haben sich sogar unserer Siedlung in dieser Gegend, des Sonnenwindpostens, bemächtigt.\n\nWir müssen zurückschlagen und ihnen zeigen, das wir ganz und gar nicht machtlos sind. Erschlagt die widerlichen Götzendiener und bringt mir ihre abscheulichen Götzen! Möge der Blitz sie treffen!", progress = "Tut es für uns, weil wir es nicht für uns selbst tun können.", completion = "Ihr habt den Söhnen des Blitzschlags neue Hoffnung gegeben, &lt;Name&gt;. Wenn unser Anführer uns schon nicht beschützt, vielleicht können es andere tun - so wie Ihr.", rewards = "Schuppengamaschen des KriegszauberersRächerbrustplatte der FinsterblutMelias irisierende KroneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9864] = {title = "Der verschollene Kampftrupp", objective = "Sucht den verschollenen Kriegstrupp von Garadar.", description = "Nach dem letzten Angriff der Finsterblut hat eine Gruppe von Jünglingen sich aufgemacht, um uns zu rächen. Wir haben versucht sie aufzuhalten, aber ihre Wut hat sie blind werden lassen. Es ist nun eine Woche vergangen seit wir sie das letzte Mal gesehen haben.\n\nBitte, <Volk>, Ihr müsst sie finden! Sie sind doch gerade erst erwachsen geworden. Wie können sie erwarten, diese Wilden besiegen zu können?\n\nSie haben die Straße nach Westen aus der Stadt genommen. Folgt dieser Straße und haltet nach Lebenszeichen unserer Jünglinge Ausschau.\n\nUnd <Name>, haltet Euch von Halaa fern, wenn Euch Euer Leben lieb ist. Dort ist Kriegsgebiet.", progress = nil, completion = "Ich habe Geschichten über unser Volk gehört. Sie sagen, dass wir einst Krieger waren...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9865] = {title = "Chroniken eines Kriegers", objective = "Tötet 20 Strauchdiebe der Finsterblut und 10 Räuber der Finsterblut.", description = "Ich kenne Euch nicht, Fremder, aber ich muss Euch um Hilfe bitten. Ich schäme mich dafür, aber ich bin nur ein einziger Orc.\n\nIn mir kochen Emotionen hoch, die ich vorher nie gekannt habe. Ich.. Ich will Rache. Blut für Blut. Kennt Euer Volk dieses Gefühl? Ich möchte meine Axt nehmen und meine Feinde in Stücke schlagen. Meine Waffe schwingen, bis meine Arme nicht mehr können und erschlaffen.\n\nDer Sonnenwindposten ist gleich südlich von dieser Prozession hier. Dort werdet Ihr unsere Feinde finden. Tötet sie... Tötet sie alle...", progress = nil, completion = "&lt;Saurfang dreht sich zu Euch um.&gt;\n\nRieche ich da etwa Blut? Ich bedauere es sehr, dass ich Euch nicht helfen konnte. Wie stolz Ihr auf Euch sein müsst. Meine Brust hebt sich allein von dem Wissen, was Ihr getan habt.\n\nGibt es noch mehr wie euch? Gibt es noch mehr Helden dort, wo Ihr herkommt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9866] = {title = "Weiter...", objective = "Bringt die Nachricht zu Scharfseher Corhuk in Garadar.", description = "Würdet Ihr mir eine letzte Ehre erweisen, <Name>? Ich möchte nicht nach Garadar zurück. Ich glaube, dass mein Schicksal woanders liegt, dass ich einst höheren Zielen folgen werde.\n\nBitte geht zu Scharfseher Corhuk und sagt ihm, dass ich nicht zurückkehren werde. Dass ich nicht zurückkehren kann. Ich muss weiterziehen... Er wird es verstehen.", progress = nil, completion = "&lt;Weissager Corhuk starrt gedankenverloren auf den Boden. Er nickt zustimmend.&gt;\n\n&lt;Weissager Corhuk wischt sich eine Träne aus dem Gesicht.&gt;\n\nDer Sohn ist der Vater... Mögen die Geister gnädig zu denen sein, die ihm im Weg stehen.", rewards = "Pantalons des WaldbehütersSchutz des DonnerbringersHandschuhe des Schmugglers"}
MultiLanguageQuestData['de'][9867] = {title = "Anführer der Finsterblut...", objective = "Bringt Ortor von Finsterbluts Kopf zu Weissager Margadesh in Garadar in Nagrand.", description = "Wir haben in den letzten Wochen viele Freunde verloren.\n\nSchon seit Jahrzehnten kämpfen wir gegen die Oger aus Nagrand, aber nun ist eine neue Bedrohung aufgetaucht. Der Finsterblutstamm der Zerschlagenen hat unser Fischerdorf im Südwesten, den Sonnenwindposten, angegriffen und alle Orcs, die dort lebten, getötet oder vertrieben.\n\nDie anderen sind der Meinung, dass man sie einfach wahllos töten sollte. Ich bin jedoch davon überzeugt, dass man ihren Anführer töten muss. Ich weiß zwar nicht, wer ihr Anführer ist, aber ich schätze, Ihr werdet es merken, wenn Ihr ihn seht.", progress = "Bringt mir den Kopf ihres Anführers, <Name>.", completion = "Das ist also das Gesicht unseres Feindes? Ich werde den Kopf aufspießen lassen und außerhalb von Garadar aufstellen. Sollten sie je wagen, uns nochmals anzugreifen, werden sie den Folgen ihres Handelns in die Augen sehen müssen.", rewards = "Achtziggliedriger SilbergurtOfenhandschuhe der FinsterblutRächerbeinplatten der FinsterblutIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9868] = {title = "Das Totem von Kar'dash", objective = "Begleitet den festgehaltenen Mag'har aus dem Sonnenwindposten hinaus. Sprecht mit Garrosh in Garadar, wenn Ihr erfolgreich wart.", description = "Habt Dank, Fremder. Wenn Ihr nicht gewesen wärt, hätten sie mich sicherlich getötet.\n\nIch wurde vor drei Nächten von diesen Finsterblut bei einem Nachtangriff auf Garadar entführt. Was ich seitdem herausgefunden habe, wird wahrscheinlich die ganze Scherbenwelt in ihren Grundfesten erschüttern: diese Finsterlinge versuchen, das Totem von Kar'dash wiederzuerlangen! Wir können nicht zulassen, dass das Totem in die Hände der Finsterblut fällt!\n\nIhr müsst mir helfen zu fliehen. Und Fremder, falls ich es nicht bis Garadar schaffe, müsst Ihr Garrosh erzählen, was hier passiert ist...", progress = nil, completion = "Was macht das schon? Die Großmutter liegt im Sterben. Das Leben ist nicht lebenswert...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9869] = {title = "Der Thron der Elemente", objective = "Elementarist Ioki möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.", description = "Grüße, <Volk>. Ich bin Ioki, Elementarist des Irdenen Rings. Ich bin nach Telaar gekommen, um die Kurenai über den Status der Elemente zu informieren.\n\nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Telaar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.", progress = nil, completion = "Ah, danke für diese Nachricht. Hättet ihr vielleicht etwas dagegen, dem Irdenen Ring zu helfen? Die Elemente sind sehr aufgewühlt, wir können alle Hilfe, die wir bekommen können, brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9870] = {title = "Der Thron der Elemente", objective = "Elementarist Yal'hah möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.", description = "Grüße, <Volk>. Ich bin Yal'hah, Elementarist des Irdenen Rings. Ich bin nach Garadar gekommen, um die Mag'har über den Status der Elemente zu informieren.\n\nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Garadar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.", progress = nil, completion = "Ah, danke für diese Nachricht. Hättet ihr vielleicht etwas dagegen, dem Irdenen Ring zu helfen? Die Elemente sind sehr aufgewühlt, wir können alle Hilfe, die wir bekommen können, brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9871] = {title = "Eindringlinge der Finsterblut", objective = "Bringt die Invasionspläne der Finsterblut zu Arechron nach Telaar in Nagrand.", description = "Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Telaar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Arechron in Telaar.", progress = "Was gibt's?", completion = "&lt;Arechron schlägt mit der einen Hand in die andere.&gt;\n\nOrtor... Dieser verräterische Dreckskerl!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9872] = {title = "Eindringlinge der Finsterblut", objective = "Bringt die Invasionspläne der Finsterblut zu Garrosh.", description = "Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Garadar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Garrosh in Garadar.", progress = "Was gibt es?", completion = "&lt;Garrosh zerknüllt die Karte und wirft sie ins Feuer.&gt;\n\nWas soll ich damit? Sie greifen uns schon seit Wochen an. Das ist nichts neues.\n\nVersteht Ihr nicht? Wir sind geliefert... Großmutter Geyah liegt im Sterben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9873] = {title = "Mein alter Freund Ortor...", objective = "Arechron in Telaar in Nagrand möchte, dass Ihr Ortor von Finsterblut tötet.", description = "Diese Angriffpläne wurden von jemandem geschrieben, den ich einst kannte. Ortor von Finsterblut, ein adliger Zerschlagener, bewandert in der Beherrschung der Elemente, der nun den dummen, stinkenden Lakai für Sumpffürst Musel'ek spielt.\n\nDie Pläne besagen, dass sie ein Orcdorf nordwestlich von hier, das als Sonnenwindposten bekannt ist, eingenommen haben.\n\nReist zum Sonnenwindposten und erlöst die Welt von Ortor von Finsterblut. Es geschieht zum Wohl aller...", progress = nil, completion = "Tausend tote Orcs sagt Ihr? Was könnte wohl der Auslöser für solch ein unverfrorenes Vordringen in Orcgebiet sein? Es ist gut, dass er tot ist, aber da steckt mehr dahinter, als ein Tentakel fühlen kann.", rewards = "Achtziggliedriger SilbergurtOfenhandschuhe der FinsterblutRächerbeinplatten der FinsterblutIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9874] = {title = "Die Ausbreitung eindämmen", objective = "Otonbu der Weise in Telaar in Nagrand möchte, dass Ihr die Fackel des flüssigen Feuers benutzt, um 10 Leichen von Bewohnern von Sonnenwind zu zerstören. Bringt die Fackel des flüssigen Feuers zurück, wenn Ihr fertig seid.", description = "Ich habe gerade von einer Katastrophe mit epischen Ausmaßen erfahren, <Name>. Die niederträchtigen Finsterblut haben das Orcdorf Sonnenwind nordwestlich von hier eingenommen und seine Einwohner getötet. Was das Ganze noch verschlimmert ist, dass sie begonnen haben, die Leichen in den Sonnenwindsee zu werfen. Wenn die Leichen dort verrotten, wird unsere Hauptwasserquelle in dieser Gegend verseucht werden.\n\nEs ist eine grauenvolle Aufgabe, die ich Euch übertrage, aber sie muss erledigt werden. Nehmt diese verzauberte Fackel und kehrt zum Sonnenwindposten zurück. Verbrennt alle verrottenden Orcleichen...", progress = "Die Orcs werden nicht verstehen, warum wir das tun, aber es muss getan werden. Für das Wohl der Orcs sowie der Zerschlagenen.", completion = "&lt;Otonbu seufzt.&gt;\n\nDas macht uns jegliche Hoffnung auf Frieden mit den Orcs für weitere zehn Jahre zunichte. Zumindest werden wir diese zehn Jahre noch erleben, was wir vielleicht nicht hätten, wenn die Leichen im See verrottet wären.", rewards = "Schuppengamaschen des KriegszauberersRächerbrustplatte der FinsterblutMelias irisierende KroneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9875] = {title = "Nicht katalogisierte Gattung", objective = "Bringt die nicht katalogisierte Gattung zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Lauranna muss diese besondere Pflanze übersehen haben. Ihr seid Euch sicher, dass Ihr eine Gattung gefunden habt, die noch nicht in Laurannas Buch katalogisiert ist. Ihr solltet sie ihr am besten zeigen, um zu sehen, was sie davon hält.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet?", completion = "Eine neue Gattung! Seid Ihr sicher?\n\n&lt;Lauranna blättert die Notizen und Diagramme durch.&gt;\n\nToll gemacht, &lt;Name&gt;. Wir werden sie unserer Liste hinzufügen. Was haltet Ihr von \"Violettblättriges Kollimium\"? Ich finde, das ist ein klangvoller Name.", rewards = nil}
MultiLanguageQuestData['de'][9876] = {title = "Fehlgeschlagene Operation", objective = "Ysiel Windsänger möchte, dass Ihr am Eingang des Echsenkessels in den Zangarmarschen nach Lebenszeichen der Druiden der Expedition des Cenarius Ausschau haltet.", description = "Ich habe eine kleine Gruppe von Druiden losgeschickt, um den Ablauf, den Ihr im Schlangensee gefunden habt, zu untersuchen. Eigentlich hätten sie kurz darauf zurückkommen müssen. Nun ja, sie sind nicht zurückgekehrt.\n\nIhr zählt zu unseren stärksten Verbündeten. Bitte sucht sie und findet heraus, was ihnen zugestoßen ist.", progress = nil, completion = "Cenarius sein Dank, dass Ihr hier seid. Wegen meiner Verletzungen konnte ich nicht nach draußen zurück, um Hilfe zu holen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9877] = {title = "Ein Regenerationsgebräu", objective = "Sprecht mit Apotheker Renzithen in Tristessa.", description = "Der Kampf gegen die Geißel verläuft nicht ohne Opfer. Viele fallen jeden Tag, doch einige erwartet ein noch schlimmeres Schicksal.\n\nOft nimmt sie Gefangene. Der Tod wäre dem, was sie in der Todesfestung erwartet, vorzuziehen. Sie werden verhört und gefoltert, während sie unter dem Einfluss eines schrecklichen, willensbrechenden Giftes stehen.\n\nApotheker Renzithen in Tristessa hat ein Gegenmittel entwickelt; geht zu ihm und holt das Regenerationsgebräu.", progress = nil, completion = "Janeda schickt Euch, um die Gefangenen der Todesfestung zu retten? Sie muss eine hohe Meinung von Euch haben, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9878] = {title = "Die Lösung des Problems", objective = "Poli'lukluk der Weisere in Telaar in Nagrand möchte, dass Ihr 10 Strauchdiebe der Finsterblut und 5 Räuber der Finsterblut tötet.", description = "Das Auftauchen der Finsterblut in Nagrand hatte einen sehr negativen Einfluss auf unsere Umwelt. Die Elemente sind aufgebracht, was wiederum die Wildtiere stört. Und noch viel schlimmer: die Zerstörung des Sonnenwindpostens hat die Feindschaft der Orcs gegen mein Volk neu entflammt.\n\nDie Kurenai sind zwar ein ganz anderer Stamm als die Finsterblut, aber für einen Orc ist ein Zerschlagener ein Zerschlagener.\n\nWir müssen versuchen, dieses Dilemma zu lösen. Reist nach Nordwesten zum Sonnenwindposten und erledigt das Finsterblutproblem.", progress = nil, completion = "Ich glaube kaum, dass die Orcs verstehen oder zu schätzen wissen, was Ihr da getan habt, aber Eure Tat war gut für Nagrand. Vielen Dank, Problemlöser...", rewards = "Pantalons des grünen BlutesÄtzende TasterBedeckung des DunkelschamanenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9879] = {title = "Das Totem von Kar'dash", objective = "Begleitet den gefangenen Kurenai aus dem Sonnenwindposten. Sprecht mit Arechron in Telaar, wenn Ihr erfolgreich wart.", description = "Ich wäre schon tot, wenn Ihr nicht vorbeigekommen wärt, Fremder. Sie haben schon so viele Kurenai auf der Suche nach einem verschollenen Relikt getötet.\n\nSie suchen das Totem von Kar'dash. Ich kann nicht verstehen, warum sie glauben, dass wir etwas über dieses Totem wüssten. Ist ein Totem nicht eine typisch orcische Gerätschaft?\n\nArechron muss davon erfahren. Vielleicht weiß er, warum die Finsterblut Kurenai verschleppen und foltern, um Informationen über ein orcisches Relikt zu erfahren.\n\nLasst uns gehen bevor noch mehr kommen.", progress = nil, completion = "Ja, ich weiß von dem Totem... aber es gehört noch viel mehr zu dieser Geschichte. Ich darf Euch jedoch nichts darüber erzählen. Nur Auserwählte haben Zugang zu solchem Wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9880] = {title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGunst der Ehrenfeste\n\nIhr bekommt:\n\nGunst der Ehrenfeste"}
MultiLanguageQuestData['de'][9881] = {title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGunst von Thrallmar\n\nIhr bekommt:\n\nGunst von Thrallmar"}
MultiLanguageQuestData['de'][9882] = {title = "Von Dieben stehlen", objective = "Besorgt 10 Kristallfragmente von Oshu'gun und bringt sie zu Gezhe am Aerissteg in Nagrand.", description = "Nexusprinz Haramad hat uns verboten mit der Arbeit im Oshu'gun loszulegen, weil er einen bestimmten mächtigen Naaru nicht verärgern will. Das hält natürlich unsere ganze Operation auf.\n\nIch glaube aber, dass ich ein Hintertürchen gefunden habe.\n\nSeht Ihr, wir sind nicht die einzigen Astralen, die von diesem riesigen Diamanten angelockt werden. Ein Dieb namens Gava'xi hat eine Gruppe von Schurken in den Oshu'gun geführt, und sie haben begonnen, große Teile aus dem Kristall herauszuschlagen.\n\nEure Aufgabe, <Volk>, ist es, dorthin zu gehen und unsere rechtmäßiges Eigentum zurückzufordern.", progress = "Habt Ihr die Kristallfragmente bekommen, <Name>?", completion = "Ich bin beeindruckt. Die meisten sind in ausgezeichnetem Zustand.\n\nIch werde bei unserem Volk ein gutes Wort für Euch einlegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9883] = {title = "Noch mehr Kristallfragmente", objective = "Ihr habt noch mehr Kristallfragmente? Nehmt aber bitte keine, die noch mit dem Berg verbunden sind. Wir wollen keinen Ärger mit den Naaru.", description = nil, progress = "Ihr habt noch mehr Kristallfragmente? Nehmt aber bitte keine, die noch mit dem Berg verbunden sind. Wir wollen keinen Ärger mit den Naaru.", completion = "Bringt mir ruhig weiter Kristalle, &lt;Name&gt;. Wir können nicht zulassen, dass diese Diebe unser Eigentum stehlen.\n\nAuch wenn es eigentlich noch gar nicht unseres ist. Theoretisch natürlich.", rewards = nil}
MultiLanguageQuestData['de'][9884] = {title = "Mitgliedervorteil", objective = "Das Konsortium ist dafür bekannt, dass es sich gut um seine Freunde kümmert. Zu Beginn jeden Monats werde ich Euch ein paar Edelsteine als Bezahlung für Eure Dienste geben.\n\nDie Qualität der Steine hängt davon ab, wie treu ergeben Ihr uns wart. Lasst uns also hoffen, dass Ihr das Richtige tut und bei uns bleibt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUnmarkierte Tasche voller Edelsteine"}
MultiLanguageQuestData['de'][9885] = {title = "Mitgliedervorteil", objective = "Schön, Euch wiederzusehen, <Name>. Ich habe Eure Edelsteine für diesen Monat fertig.\n\nIch habe Euch ein paar mehr dazugetan, damit Ihr wisst wie froh wir sind, Euch bei uns zu haben.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAusgebeulter Sack voller Edelsteine"}
MultiLanguageQuestData['de'][9886] = {title = "Mitgliedervorteil", objective = "Das Konsortium ist dafür bekannt, dass es sich gut um seine Freunde kümmert. Zu Beginn jeden Monats werde ich Euch ein paar Edelsteine als Bezahlung für Eure Dienste geben.\n\nDie Qualität der Steine hängt davon ab, wie treu ergeben Ihr uns wart. Lasst uns also hoffen, dass Ihr das Richtige tut und bei uns bleibt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMit Edelsteinen gefüllter Umschlag"}
MultiLanguageQuestData['de'][9887] = {title = "Mitgliedervorteil", objective = "Ah, <Name>! Was macht so ein wichtiger Bursche wie Ihr an so einen dreckigen Ort wie diesem?\n\nNatürlich habe ich Eure Edelsteine. Nur das Beste für unseren Lieblingsuntoter.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTasche voller erstklassiger Edelsteine"}
MultiLanguageQuestData['de'][9888] = {title = "Der unfähige Anführer", objective = "Jorin Totauge möchte, dass Ihr Kilrath sucht und mit ihm sprecht.", description = "Ich bin dem sicheren Tode entronnen, habe einen feigen Angriff bei Nacht von den Felsfäusten auf mein Dorf überlebt.\n\nAber ich frage Euch, Fremder, wozu?\n\n<Jorin zeigt auf Garrosh.>\n\nEr hat uns jegliche Unterstützung verweigert. Oger toben durch meine Stadt und er sitzt nur da und heult den Mond an. Was ist aus uns geworden? Was wird aus uns werden?\n\nIch habe einen Späher, Kilrath, zum Dorf, den jetzigen Ruinen des Blutenden Auges, geschickt. Könnt Ihr ihn bitte suchen und unterstützen? Er versteckt sich an der Grenze zwischen Nagrand und Terokkar.", progress = nil, completion = "&lt;Kilrath flüstert.&gt;\n\nDiese Oger sind extrem sonderbar. Und auch extrem dumm. Schaut nur, wie der fette den, äh, weniger fetten zum Tanzen zwingt. Es ist faszinierend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9889] = {title = "Nicht den Fetten töten!", objective = "Kilrath in den Wäldern von Terokkar möchte, dass Ihr 10 Eindringlinge der Felsfäuste tötet und Unkor den Rücksichtslosen so lange schlagt, bis er redet.", description = "Ich beobachte diese Kreaturen nun schon seit Tagen. Der Fette sagt, dass er auf etwas wartet. Worauf bleibt jedoch ein Geheimnis.\n\nIch habe einen Plan, aber er erfordert ein wenig Brutalität von Eurer Seite. Ihr werdet einige seiner Untertanen töten müssen und ihn dann fast tot schlagen. Wenn Ihr das tut, bin ich sicher, dass er uns alles erzählen wird, was wir wissen wollen.", progress = "Ich gebe auf! Ich gebe auf!", completion = "Lasst mich leben und ich sage Euch alles, was Ihr wissen wollt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9890] = {title = "Erfolg!", objective = "Teilt Kilrath in den Wäldern von Terokkar die Informationen, die Ihr aus dem Oger geprügelt habt, mit.", description = "Seit vielen Jahren hatten die Felsfäuste die Herrschaft über alle Oger der Scherbenwelt. Die Oger waren unter Krol vereint und zufrieden mit den Ländereien, die sie erhalten hatten. In den letzten Monaten haben wir jedoch viele Oger an einen Klan namens Totschläger verloren. Die Totschläger haben den größten Teil unseres Landes in Nagrand in Beschlag genommen und viele unserer Leute getötet.\n\nWir hatten keine andere Wahl als dieses Dorf einzunehmen. Wir werden ausgerottet...\n\nKrol ist verschollen und die Felsfäuste sind in Aufruhr. Lantresor von der Klinge hat in seiner Abwesenheit die Führung übernommen.", progress = nil, completion = "Ganz ruhig, &lt;Name&gt;. Ich bin nur ein kleiner Schurke. Ich habe keine Ahnung, was ich mit solch einer Information anfangen soll.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9891] = {title = "Weil Kilrath ein Feigling ist", objective = "Erzählt Jorin Totauge in Garadar in Nagrand, was Ihr aus Unkor herausprügeln konntet.", description = "Erzählt Jorin in Garadar, was Ihr gehört habt. Ich bin mir sicher, dass er nicht erfreut sein wird zu hören, dass unser Dorf zerstört und viele unserer Leute getötet wurden, weil die Oger mehr Platz brauchen.\n\nMögen die Ahnen über Euch wachen... Ich werde mich in den Büschen verstecken, falls Ihr mich noch braucht.", progress = nil, completion = "Sie denken also, dass sie uns Orcs nach Lust und Laune vertreiben und abschlachten können, was? Ich bin mir sicher, dass das nichts damit zu tun hat, dass unser Anführer ein unfähiger Jammerlappen ist... Wenn er doch nur einen Bruchteil der Leidenschaft seines Vaters geerbt hätte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9892] = {title = "Noch mehr Obsidiankriegsperlen", objective = "Habt Ihr noch mehr Kriegsperlen? Ihr findet genügend Oger weit im Norden, an der Grenze zu den Zangarmarschen.", description = nil, progress = "Habt Ihr noch mehr Kriegsperlen? Ihr findet genügend Oger weit im Norden, an der Grenze zu den Zangarmarschen.", completion = "Wir werden gut an diesen Perlen verdienen, &lt;Name&gt;. Ich werde Khoraazi ganz sicher von Eurer Arbeit hier erzählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9893] = {title = "Obsidiankriegsperlen", objective = "Bringt 10 Obsidiankriegsperlen zu Gezhe beim Aerissteg in Nagrand.", description = "Während wir hier darauf warten, dass wir endlich am Oshu'gun graben können, verlieren wir so viel Gewinn, <Name>.\n\nZum Glück habe ich eine andere Einkommensquelle entdeckt. Die Oger von Nagrand tragen Kriegsperlen aus Obsidian, ein Gestein, das in vielen anderen Welten sehr wertvoll ist.\n\nZerid musste sich aus Sicherheitsgründen bereits mit diesen Rohlingen auseinandersetzen. Betrachtet die Kriegsperlen also als kleinen Bonus. Oder noch besser, betrachtet sie gar nicht und bringt sie mir einfach.", progress = "Wie führen die Oger sich auf, <Name>? Harte Nuss, was?", completion = "Ausgezeichnet. Das wird uns über Wasser halten bis die Sha'tar fertig sind mit was immer sie auch im Oshu'gun tun mögen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9894] = {title = "Schützt die Behüter", objective = "Tötet Lord Klaq und kehrt danach zu Windruferin Schwarzhuf in der Zuflucht des Cenarius zurück.", description = "Während Eurer Reisen habt Ihr vielleicht ein paar der Behüter der Expedition getroffen. Sie kümmern sich hauptsächlich um die Feldstudien, das heißt die Dokumentation der einzigartigen Bewohner der Marschen, das Sammeln von Proben und die Kontaktaufnahme mit den vernunftbegabten Arten.\n\nDie Sicherheit der Behüter ist von äußerster Wichtigkeit, <Klasse>. Wir mussten die Behüter, die sich aufgemacht haben, um die Funggorhöhle zu erkunden, wegen Angriffen von Sumpfmonstern zurückrufen. Aufseher Hamuht ist der Meinung, dass wir ihren Angriffen ein schnelles Ende machen könnten, wenn wir ihren Anführer, Lord Klaq, töten.", progress = nil, completion = "Ihr habt meinen Dank, &lt;Name&gt;, und den der Behüter. Sie werden sich freuen zu hören, dass sie ihre Arbeit im Süden nun ohne Angst vor weiteren Angriffen fortsetzen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9895] = {title = "Aus dem Gleichgewicht geraten", objective = "Sucht und vernichtet Sumpfschläger und kehrt dann zu Lethyn Mondfeuer in der Zuflucht des Cenarius zurück.", description = "Habt Ihr die Umgebung genau betrachtet, <Name>? Dies ist eine dahinsiechende Landschaft, die verzweifelt versucht ihr Gleichgewicht zu halten und den Kampf verliert.\n\nWenn man weiß, worauf man achten muss, kann man die Symptome deutlich erkennen. Einige Vertreter bestimmter Gattungen überholen ihre Artgenossen, was das Wachstum angeht, bereits und werden aggressiv.\n\nEin gutes Beispiel für so ein unkontrolliertes Wachstum ist der Marschenläufer Sumpfschläger. Wenn ihr ihn selbst sehen wollt, müsst Ihr nur zu den Wasserwegen südlich der Zuflucht gehen.\n\nAber haltet Euch bereit, Euch zu verteidigen. Diese Kreatur kennt kein Erbarmen.", progress = nil, completion = "Jetzt, da Ihr die Anzeichen der Unausgeglichenheit mit eigenen Augen gesehen habt, achtet bei Euren weiteren Reisen darauf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9896] = {title = "Schwarzsichels Fluch", objective = "Bringt Schwarzsichels Stachel zu Ausgrabungsleiter Conall in Telredor.", description = "Bei Khaz'goroths brennendem Nabel, ist das heiß hier! Ich kann es der ersten Gruppe nicht verübeln, dass sie abgereist sind, aber wisst Ihr, es war nicht die Hitze, die sie verjagt hat. Nein, es war Schwarzsichel, auch wenn sie das natürlich nicht zugeben möchten.\n\nSie hatten ihr Lager südlich von den leuchtenden Draeneitürmen im Westen aufgeschlagen, gleich nördlich von Wildfenn, als die riesige Wespe aus dem Nichts auftauchte und sie angriff! Ich kann es kaum erwarten, ihre Gesichter zu sehen, wenn ich den Stachel des Biests nach Eisenschmiede bringe!", progress = "Habt Ihr den Stachel bekommen können? Denkt daran, wenn er beschädigt ist, ist er wertlos für mich!", completion = "Ich kann Euch gar nicht genug danken, Kumpel. Ich werde es genießen...", rewards = "SchwarzsichelschulternGurt der TapferkeitSchwarzsichelhandschuheMarschenfangstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9897] = {title = "Ich bin gerettet!", objective = "Gebt Harold Fährten bei Nesingwarys Safari in Nagrand das Bündel mit Tierhäuten.", description = "Es macht mir nichts aus zu teilen. Ich bin nur froh, dass ich vor diesem Widerling Diebus sicher bin! Und ich habe Tonnen von Tierhäuten in den Zangarmarschen gesammelt, es ist also überhaupt kein Problem!", progress = "Es ist sehr...<hust>...nett von Kristen, dass sie ihre Tierhäute teilt, meint Ihr nicht?", completion = "Nun, ich konnte nicht wissen, ob Ihr Kristen helfen konntet oder nicht. Aber wenn sie Euch eines ihrer Bündel mit Tierhäuten gegeben hat, müsst Ihr wohl in Ordnung sein.\n\nHier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9898] = {title = "Respekt erlangen", objective = "Bringt Schwarzsichels Stachel zu Reavij im Sumpfrattenposten.", description = "Magasha ist die wildeste Trollfrau im Sumpf, aber sie respektiert nur mächtige Jäger.\n\nIch hab schon versucht, mich ihr zu beweisen, aber die einzige Bestie, mit der mir das gelingen könnte, ist mindestens eine Nummer zu groß für mich. Wärt Ihr vielleicht so nett, mir zu helfen? Es gibt da eine riesige Sumpfwespe namens Schwarzsichel, die sich in der Gegend südlich der leuchtenden Draeneitürme im Westen herumtreibt. Wenn Ihr mir ihren Stachel bringen könnt, gibt Magasha mir vielleicht eine Chance, mich ihren Jägern anzuschließen.\n\nIch weiß, das ist nicht ganz ehrlich, aber ich verspreche Euch, dass ich von ihr lernen und Euch beide stolz machen werde.", progress = "Ich werde Glück haben - ich fühle es.", completion = "Fantastisch! Ich werde Euch nie vergessen, dass ihr mir geholfen habt, ihr Herz zu gewinnen. Ihr sollt der Ehrengast auf unserer Hochzeit sein!", rewards = "SchwarzsichelschulternGurt der TapferkeitSchwarzsichelhandschuheMarschenfangstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9899] = {title = "Unerledigte Arbeit", objective = "Magasha im Sumpfrattenposten möchte, dass Ihr Sporenschwinge tötet.", description = "Jemand muss Reavij zur Vernunft bringen! Er vernachlässigt seine Pflichten und verschwendet stattdessen all seine Energie darauf, meine Aufmerksamkeit zu erlangen. Ich habe versucht, ihn zu ignorieren und ihm gesagt, dass er damit aufhören soll. Aber nichts scheint zu helfen.\n\nBis er es endlich sein lässt, muss ich ständig hinter ihm aufräumen. Er hätte sich eigentlich um Sporenschwinge kümmern sollen, aber das Monster ist immer noch wohlauf. Wenn Ihr Zeit habt, könntet Ihr vielleicht in den westlichen Teil des Todesmoors gehen und den Segler töten? Ich kümmere mich in der Zwischenzeit um Reavij.", progress = "Ich kann ihn einfach nicht davon abbringen. Ich fürchte, ich muss Schattenjäger Denjai bitten, ihn zurück nach Zabra'jin zu schicken.", completion = "Wenigstens einer hier erfüllt seine Pflicht. Vielen Dank, dass Ihr Euch um diese Angelegenheit gekümmert habt, &lt;Name&gt;. Ich muss einmal mit Zurai über Reavij sprechen. Seine Tagträumereien müssen langsam ein Ende haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRolle der Beweglichkeit VIRolle der Intelligenz VIRolle des Schutzes VIRolle der Willenskraft VIRolle der Ausdauer VIRolle der Stärke VI\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9900] = {title = "Gava'xi", objective = "Tötet Gava'xi in der Nähe des Oshu'gun und kehrt dann zu Zerid beim Aerissteg in Nagrand zurück.", description = "Die Anwesenheit von astralen Schurken in dieser Gegend mag Gezhe, der in allem eine Möglichkeit sieht, vielleicht erheitern, aber sie sind eine wirkliche Bedrohung für die Sicherheit unserer Unternehmung.\n\nIhr Anführer, Gava'xi, ist ein gefährlicher Krimineller, und ich habe es zu meinem höchsten Anliegen gemacht, ihn zur Strecke zu bringen.\n\nWenn Ihr Euch nützlich machen wollt, dann zieht los und kümmert euch um Gava'xi. Ich werde mich darum kümmern, dass Ihr angemessen entlohnt werdet.", progress = "Ihr seid zurück, <Volk>. Ist Gava'xi tot?", completion = "Dank Euch müssen wir uns nun nicht mehr vor Gava'xi fürchten. Wollen wir uns nun um eure Belohnung kümmern.", rewards = "Zerids alte MusketeAstrale SchärpeAuf Euch wartet eine dieser Belohnungen:\n\nRelikt von Oshu'gun\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9901] = {title = "Offene Rechnungen", objective = "Ausgrabungsleiter Conall in Telredor möchte, dass Ihr Sporenschwinge tötet.", description = "Die erste Expedition, die die Liga losgeschickt hatte, berichtete von einem riesigen Sporensegler namens Sporenschwinge. Sie mussten sehr hastig aufbrechen, deshalb hatten sie keine Gelegenheit, das Tier umzubringen. Deshalb dachte ich mir, ich erledige das für sie.\n\nIn ihrem Bericht stand, dass die Kreatur sich im westlichen Teil des Todesmoors aufhält. Ich glaube Verteidiger Idaar erwähnte einmal, dass es sich nordöstlich von Telredor befindet.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich glaube, wir beide lassen ein ganzes Team von Ausgrabungsleitern neben uns blass aussehen. Wenn ich zurück in Eisenschmiede bin, werde ich mir meine Einsatzorte sicher selbst aussuchen dürfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRolle der Stärke VRolle der Willenskraft VRolle der Ausdauer VRolle der Intelligenz VRolle der Beweglichkeit VRolle des Schutzes V\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9902] = {title = "Der Schrecken des Sumpflichtsees", objective = "Tötet Terrorklaue und kehrt dann zu Puluu in der Oreborzuflucht zurück.", description = "Meine Reisen durch das Gebiet der Naga haben mir einen Eindruck vermittelt, wie schlimm es meinen unglücklichen Brüdern und Schwestern gehen muss. Am Sumpflichtsee im Südwesten habe ich beobachtet, welch tödliches Spiel einer der besonders bösartigen Zuchtmeister treibt. Er jagt seine Sklaven ins Wasser, wenn er weiß, dass Terrorklaue, ein riesiger Sumpfstrok, Hunger hat.\n\nDie Folgen brauche ich nicht weiter erläutern. Wir sind zu wenige, um die Naga direkt anzugreifen, aber wir können ihnen den Spaß verderben, indem wir ihr Haustier umbringen.", progress = nil, completion = "Habt Dank, &lt;Name&gt;. Vielleicht werden diese Marschen mit der Hilfe der Draenei eines Tages frei von Naga sein. Ich kann mir gar nicht vorstellen, wie schlimm es sein muss, ihnen dienen zu müssen.\n\nEr spricht nicht oft darüber, aber Maktu war einst ihr Sklave.", rewards = "Furchtloser GurtGrimmige MantelungStiefel des SumpfläufersTerrorstoffmantelungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9903] = {title = "Der Größte von allen", objective = "Tötet Mragesh und kehrt dann zu Zurjaya in Zabra'jin zurück.", description = "Ihr seid zwar mit den meisten der kleineren Hydras fertiggeworden, aber ich glaube kaum, dass Mragesh von Eurer Vorstellung beeindruckt war. Er ist eine gerissene, grausame Bestie und hat schon so manchen Angler auf dem Gewissen.\n\nIch habe mir vorgenommen, die Letzte zu sein, die er je belästigt. Er soll sich tief im Schlangensee im Nordosten verstecken. Er ist schon Geschichte, aber das weiß er noch nicht.", progress = nil, completion = "Ich bin mir sicher, der alte Knabe hat das Ende seiner Tage schon vorausgesehen. Bei all diesen Neuankömmlingen musste die alte Rangfolge sich einfach ändern. Es ist nur recht, dass sein Geist nun zu Ruhe kommen kann.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElixier des AdeptenElixier des Ansturms\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9904] = {title = "Jagd auf Terrorklaue", objective = "Tötet Terrorklaue und kehrt dann zu Zurjaya in Zabra'jin zurück.", description = "Ich habe jeden erdenklichen Fisch in den Marschen gefangen, aber einer ist mir bisher entkommen. Sicher habe ich auch Aale und Morastflossenfrenzys gefangen. Aber als ich das letzte Mal am Sumpflichtsee war, hat einer angebissen, meine Schnur zerrissen und ist abgehauen.\n\nTerrorklaue wird er genannt, und ich werde nicht ruhen, bis er tot ist. Er ist zu groß um ihn mit einer Angel zu fangen, also müssen wir ihn wohl auf die altmodische Art umbringen.", progress = nil, completion = "Endlich! Wahrscheinlich hat jeder Angler eine Geschichte über \"den, der mir entkommen ist\". Aber ich habe noch keinen Fisch getroffen, den man nicht auf die ein oder andere Art bezwingen konnte.", rewards = "Furchtloser GurtGrimmige MantelungStiefel des SumpfläufersTerrorstoffmantelungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9905] = {title = "Maktus Rache", objective = "Sucht und tötet Mragesh und kehrt dann zu Maktu in der Oreborzuflucht zurück.", description = "Als Maktu letztes Mal auf Hydrajagd am Schlangensee war, wurde er von größter Hydra, die er jemals gesehen hat, angegriffen. Maktu hat nach seinem Speer gegriffen, aber es war schon zu spät. Er konnte gerade noch entkommen, bevor er zu Hydrafutter wurde.\n\nWer weiß? Vielleicht hat Maktu nächstes Mal nicht mehr so viel Glück. Maktu will, dass es kein nächstes Mal gibt. Werdet Ihr Maktu helfen, sich an Mragesh zu rächen?", progress = nil, completion = "&lt;Maktu nickt anerkennend.&gt;\n\nMaktu ist dankbar für Eure Hilfe. Maktus Stolz ist befriedigt. Er wird nicht mehr so unvorsichtig sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElixier des AdeptenElixier des Ansturms\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9906] = {title = "Sag's mit Fäusten", objective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 8 Zermalmer der Felsfäuste und 8 Mystiker der Felsfäuste tötet.", description = "Oger interessieren sich nur für das Eine: Macht. Wenn wir ihnen gegenüber Schwäche zeigen, werden sie sich das zum Vorteil machen und uns ausrotten.\n\nGarrosh ist vielleicht bereit dazu, die Hände in den Schoß zu legen und diese Hunde unser Land übernehmen zu lassen, aber ich bin es nicht! Ich möchte, dass Ihr den Totschlägern eine Nachricht zukommen lasst, die sie verstehen: Gewalt.\n\nReist zu den Ruinen der Brennenden Klinge südöstlich von hier und zeigt ihnen die Macht der Mag'har.\n\nUnd <Name>, schaut bei den anderen vorbei, bevor Ihr geht.", progress = nil, completion = "Unser Auftrag ist noch nicht zu Ende. Es gibt noch andere, die einer Lektion bedürfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9907] = {title = "Ein kühner Angriff", objective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 10 Krieger der Felsfäuste und 10 Magier der Felsfäuste tötet.", description = "Direkt im Westen von hier findet Ihr das Halaanibecken. Im Becken befinden sich die Zwillingsschluchten von Nagrand: Nordwind und Südwind. Die Schocktruppen der Felsfäuste benutzen die Schluchten, um ihre Ogerhorte zu verstecken.\n\nIch möchte, dass Ihr diese Truppen aufspürt und sie alle im Namen der Mag'har tötet.", progress = nil, completion = "Wenn dies das Blut in ihren Adern nicht zum Gefrieren bringt, dann wird es nichts schaffen. Ihr habt den Mag'har zu Gerechtigkeit verholfen, &lt;Name&gt;. Und für Gerechtigkeit zahlen die Mag'har gut.", rewards = "Stab der vier goldenen MünzenArmschienen des KampfklerikersBollwerk des KönigsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9910] = {title = "Standarten", objective = "Mystiker Elkay'gan in Garadar in Nagrand möchte, dass Ihr eine Schlachtstandarte der Mag'har am ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge aufstellt. Bringt die übrigen Schlachtstandarten zurück, wenn Ihr fertig seid.", description = "Wenn Ihr in die Ruinen der Brennenden Klinge reist, habe ich eine Aufgabe für Euch. Stellt diese Schlachtstandarten der Mag'har an drei verschiedenen Orten in der Ogersiedlung auf. Vorzugsweise Orte, an denen man sie gut sehen kann. Haltet nach den großen lodernden Scheiterhaufen in den oberen Bereichen Ausschau. Stellt eine Standarte neben dem ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge auf.\n\nDie Standarten werden einen bleibenden Eindruck bei den Ogern hinterlassen, die die Schlacht verpasst haben.", progress = "Ehrfurcht aus Angst! Das ist so gut wie jeder andere Grund.", completion = "Vielleicht wollt Ihr noch eine andere Aufgabe? Eine etwas heiklere?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9911] = {title = "Der Graf der Marschen", objective = "Bringt \"Graf\" Ungulas Beißwerkzeug zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen.", description = "Dieses blutige Beißwerkzeug stammt von einem unglaublich großen Insekt. Der Netherrochen, zu dem es gehörte, war der größte, der je in den Zangarmarschen gesichtet wurde. Wenn man den Zustand der Beißwerkzeuge betrachtet, muss der Graf seine Nahrung von Aas auf frisches Fleisch umgestellt haben.\n\nDie Expedition des Cenarius wäre an einem solchen Objekt sicher sehr interessiert. Behüterin Leesa'oh hat ein kleines Lager im Westen des Quaggkamms.", progress = "<Die Behüterin blinzelt ein paar Mal überrascht.>\n\nWoher habt Ihr dieses... Ding?", completion = "Seid Ihr sicher, dass es echt ist? Ich meine, ich wusste schon, dass es riesige Kreaturen in den Marschen gibt, aber es gibt einen Unterschied zwischen riesigen Kreaturen und RIESIGEN Kreaturen.\n\nDa fällt mir ein, dass die Sporlinge einmal etwas von einem furchterregenden Netherrochen erzählt haben, der sie vor den Angriffen der Sumpflords bedroht hatte.\n\nWas ist, wenn diese Geschichten wahr sind? Oh je. Ich hebe das hier mal lieber auf. Die Expedition wird sicher davon erfahren wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9912] = {title = "Die Expedition des Cenarius", objective = "Sprecht mit Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Die Hauptexpedition des Zirkels des Cenarius in der Scherbenwelt ist als Expedition des Cenarius bekannt. Sie fing als kleines Projekt unter der direkten Kontrolle des Zirkels an, aber inzwischen ist sie zu einer großen und ziemlich unabhängigen Organisation herangewachsen.\n\nDie Anführerin der Expedition, Ysiel Windsänger, hat uns gebeten, Freiwillige zur Zuflucht des Cenarius in den östlichen Zangarmarschen zu schicken. Nehmt den Pfad nach Westen und Ihr werdet direkt dorthin gelangen.", progress = nil, completion = "Willkommen in der Zuflucht des Cenarius, &lt;Name&gt;. Ich hoffe, Ihr könnt uns bei unserer Aufgabe behilflich sein. Wir haben viel Arbeit vor uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9913] = {title = "Das Konsortium braucht Euch!", objective = "Meldet Euch bei Gezhe beim Aerissteg in Nagrand.", description = "Meine Organisation, das Konsortium, sucht nach talentierten Personen, wie Ihr es seid. Ihr werdet kaum ehrlichere und härter arbeitende Astrale als uns in dieser Gegend hier finden.\n\nAlles, was wir Verlangen ist Loyalität, Einsatz und ein vernünftiges Maß an moralischer Flexibilität. Wenn Ihr Interesse habt, sprecht mit Gezhe, unserem Anführer hier. Ihr findet ihn beim Aerissteg, nördlich des Oshu'guns.", progress = nil, completion = "Seid Ihr bereit für ein wenig Arbeit, &lt;Volk&gt;? Ich habe die perfekte Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9914] = {title = "Ein ganzer Kopf voll Elfenbein", objective = "Sammelt 3 Paar Elfenbeinstoßzähne und kehrt dann zu Shadrek beim Aerissteg in Nagrand zurück.", description = "Elfenbein ist ein heißbegehrtes Material. Ich habe Kunden von weither, die Schlange stehen, um es zu kaufen. Ich würde mich überreden lassen, meinen Gewinn mit Euch zu teilen.\n\nDie Stoßzähne der wilden Elekk in Nagrand haben genau die Qualität, die ich brauche. Bleibt jedoch von den Bullen fern, ihre Stoßzähne sind zu minderwertig.\n\nOh, und keine Sorge, das ist keine Wilderei, ich habe ein Abkommen mit den Orcs und den Draenei.\n\nAlso, sind wir uns einig?", progress = "Ich brauche Elfenbein, keine Entschuldigungen. Wir können natürlich Euren Anteil am Gewinn neu verhandeln. Ich glaube aber kaum, dass Ihr mit dem Ergebnis zufrieden sein werdet.", completion = "Ich habe keine Sekunde an Euch gezweifelt, mein Freund. Die meisten hiervon sehen gut aus. Ein bisschen dreckig und verkratzt vielleicht. Aber ich denke, sie sind den Preis, den wir vereinbart hatten, wert.\n\nIch hoffe, das wir auch in Zukunft ins Geschäft kommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9915] = {title = "Noch mehr Elfenbein", objective = "Ich habe immer noch Bedarf an Elfenbeinstoßzähnen von den wilden Elekk in Nagrand. Unglücklicherweise kann ich es mir nicht mehr leisten, Euch dafür zu bezahlen. Wenn Ihr mir aber trotzdem weiter Stoßzähne bringt, werdet Ihr Euch beim Konsortium sehr beliebt machen.", description = nil, progress = "Ich habe immer noch Bedarf an Elfenbeinstoßzähnen von den wilden Elekk in Nagrand. Unglücklicherweise kann ich es mir nicht mehr leisten, Euch dafür zu bezahlen. Wenn Ihr mir aber trotzdem weiter Stoßzähne bringt, werdet Ihr Euch beim Konsortium sehr beliebt machen.", completion = "Ausgezeichnet, noch mehr hochwertige Stoßzähne. Auch wenn ein paar davon etwas schäbig aussehen.\n\nIhr habt den Dank des Konsortiums, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][9916] = {title = "Vorratskisten des Blutenden Auges", objective = "Mystiker Elkay'gan in Garadar in Nagrand möchte, dass Ihr 10 Vorratskisten des Blutenden Auges wiederbesorgt.", description = "Die Totschläger haben die Vorräte, die sie aus unserem Dorf gestohlen haben, zu den Zwillingsschluchten von Nagrand gebracht, die sich westlich von hier im Halaanibecken befinden.\n\nWenn ihr Euch dort aufhalten solltet, haltet Ausschau nach den Vorratskisten. Wenn wir sie zurückbekommen könnten, würde das die Last, die die Matronen von Garadar zu tragen haben, erheblich mindern.", progress = "Vielleicht können unserer Kinder eines Tages ohne Hunger leben.", completion = "Die meisten unserer Besitztümer wurden bei Angriffen zerstört oder gestohlen. Ich kann euch nicht viel bieten, aber hier sind ein paar Dinge, die Ihr vielleicht als nützlich empfinden könntet.", rewards = "Feurer des OgerantreibersSchuhe des OgerschlägersAuf Euch wartet eine dieser Belohnungen:\n\nAbzeichen des Ogerraufers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9917] = {title = "Kann ich meinen Augen trauen?", objective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr die Pläne der Felsfäuste besorgt.", description = "Kann ich meinen Augen trauen? Ist das da drüben tatsächlich eine Jagdgesellschaft von Ogern? Was treiben Oger denn so weit von Ihrem Hügel entfernt? Mir gefällt das gar nicht, <Fremder/Fremde>. Zuerst die Finsterblut und jetzt die Oger. Wir haben einfach nicht genug Leute, um mit all diesen Gefahren fertigzuwerden.\n\nKönntet Ihr die Ogersiedlung im Osten untersuchen? Ihr Lager ist etwa 200 Schritte östlich von hier. Wenn Ihr die Jäger der Felsfäuste seht, seid Ihr richtig. Tötet sie um an ihre Pläne zu kommen!", progress = "Habt Ihr Neuigkeiten erfahren?", completion = "&lt;Bintook liest die Pläne.&gt;\n\nBEIM LICHT! Diese Handschrift ist grauenvoll! So wie ich das sehe, planen sie \"die blauen Häute zu essen und in ihr Dorf zu bringen\" oder einen Blaubeerkuchen zu backen. Es könnte wirklich beides heißen. Wir müssen der Sache auf den Grund gehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9918] = {title = "Nicht solange ich hier wache!", objective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Brocken sprecht. Kehrt zu Jägerin Bintook zurück, wenn Ihr die geforderten Informationen gesammelt habt.", description = "Die Schlachtpläne wurden von einem Leutnant der Oger geschrieben. Sein Name ist entweder Trocken oder Brocken.\n\n<Bintook dreht das Pergament und legt den Kopf schief.>\n\nEs könnte auch Billy sein.\n\nWie auch immer, ich denke, Ihr solltet dorthin zurückgehen und ein paar Takte mit Billy oder Trocken oder Brocken oder was weiß ich reden! Versucht diplomatisch zu sein. Wenn das nichts nützt, dann setzt eben etwas Muskelkraft ein.", progress = nil, completion = "Oh je, das war nur eine kleine Jagdgesellschaft? Ihr müsst Mo'mor erzählen, was Ihr herausgefunden habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9919] = {title = "Sporeggar", objective = "Geht nach Sporeggar, nördlich vom Pilzgeflecht in den Zangarmarschen, und bringt die geborgenen Sporensäcke zu Msshi'fn.", description = "Ihr seid <ein sehr netter/eine sehr nette:r> <Volk>, <Name>. Nicht wie die anderen, die ich getroffen habe.\n\nIhr solltet den Rest meines Volkes kennenlernen, sie wären Euch für Eure Hilfe sehr dankbar. Bringt diese Sporenbeutel zu meinem Anführer, Msshi'fn. Ihr findet ihn in Sporeggar, nördlich von hier.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet, <Name>?", completion = "Ihr habt uns geholfen, die nächste Generation Sporlinge zu sichern, &lt;Volk&gt;. Das können wir Euch nur mit einem Willkommen in unserer Stadt vergelten. Bleibt doch ein wenig und lernt die anderen Sporlinge kennen. Sie werden viele Fragen an Euch haben, ich hoffe, das macht Euch nichts aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9920] = {title = "Mo'mor der Brecher", objective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Mo'mor dem Brecher redet.", description = "Ihr müsst sofort zu Mo'mor! Ihr könnt ihn in der Mitte von Telaar finden, beim Springbrunnen. Erzählt ihm genau, was der Oger Euch gesagt hat!", progress = nil, completion = "&lt;Mo'mor schaut verdutzt drein.&gt;\n\nEin neuer Ogerstamm drängt die Felsfäuste immer weiter nach Süden? Das klingt beunruhigend. Wir müssen mit der Situation in der Nähe unseres Zuhauses fertig werden...", rewards = nil}
MultiLanguageQuestData['de'][9921] = {title = "Die Ruinen der Brennenden Klinge", objective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr 8 Zermalmer der Felsfäuste und 8 Mystiker der Felsfäuste tötet.", description = "Die Jagdgesellschaften der Oger sind Vorboten für einen Angriff. Wir müssen sie schlagen, bevor sie eine Chance haben, genug Leute zu sammeln, um unsere Stadt einzunehmen.\n\nIhr werdet Euch wohl Eure Hände schmutzig machen müssen, <Volk>.\n\nDie größte Ansammlung von Felsfäusten in dieser Gegend befindet sich in den Ruinen der Brennenden Klinge, direkt im Osten von Telaar, an der Grenze zu Terokkar. Geht dort hin und zeigt den Felsfäusten, dass Telaar sich niemals ihrem Willen beugen wird!", progress = "Wir haben Telaar erst vor kurzem wiedergewonnen. Wir werden es nicht aufgeben!", completion = "Ausgezeichnet. Konntet Ihr diesen Lantresor, der in dem Brief dieses Dummkopfs erwähnt wurde, ausfindig machen?\n\nEgal, wir müssen weitermachen. Ich habe Berichte über weitere Ogeraktivitäten erhalten, um die sich sofort jemand kümmern muss!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9922] = {title = "Die Zwillingsschluchten von Nagrand", objective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr 10 Krieger der Felsfäuste und 10 Magier der Felsfäuste tötet.", description = "Ihr habt eine gute Arbeit geleistet, <Name>. Seid Ihr bereit für noch mehr davon?\n\nIch habe Berichte über eine große Ansammlung von Felsfäusten in den zwei Schluchten von Nagrand, nordwestlich von hier im Halaanibecken.\n\nBegebt Euch zu den Schluchten und werdet mit den übrig gebliebenen Felsfäusten fertig.", progress = nil, completion = "Ausgezeichnete Arbeit! Ich stelle im Augenblick Nachforschungen über den Totschlägerstamm an, den der Leutnant der Felsfäuste erwähnt hat. Jetzt müssen die Aufgaben, die Ihr erledigt habt, getestet werden.", rewards = "Stab der vier goldenen MünzenArmschienen des KampfklerikersBollwerk des KönigsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9923] = {title = "HILFE!", objective = "Findet den Schlüssel der Felsfäuste und befreit Corki. Sprecht mit Arechron in Telaar, wenn Ihr Erfolg hattet.", description = "HILFE! Sie werden mich fressen! Ich weiß es!\n\nFindet den Schlüssel, einer dieser Oger muss ihn haben.\n\nWenn Ihr mir hier raushelft, wird mein Vater Euch fürstlich entlohnen! Er ist der Anführer von Telaar, Arechron.", progress = nil, completion = "Es tut mir wirklich sehr leid, &lt;Volk&gt;. Er gerät immer in Schwierigkeiten. Manchmal wünschte ich, ich könnte Ihn anleinen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9924] = {title = "Corki wird schon wieder vermisst!", objective = "Arechron in Telaar bittet Euch, Corki zu suchen und zu befreien.", description = "<Arechron seufzt.>\n\nDas ist mir so peinlich. Erinnert Ihr Euch noch an meinen Sohn Corki? Ihr habt ihn vor Kurzem aus den Ruinen der Brennenden Klinge gerettet. Nun ja, seine Neugier hat ihn mal wieder gepackt. Er sagte, er wolle die Felsfaustbedrohung für Onkel Mo'mor untersuchen, und ist zu den Ogerhügeln im Halaanibecken gerannt, nördlich von hier.\n\nKönntet Ihr ihn vielleicht für mich ausfindig machen? Ich wäre Euch ewig dankbar.", progress = "Habt Ihr ihn gefunden?", completion = "Ich bin Euch so dankbar, &lt;Name&gt;. Seine Mutter wird sich in Zukunft um ihn kümmern.", rewards = "Stiefel des ExpertenZauberstab der GlückseligkeitAuf Euch wartet eine dieser Belohnungen:\n\nVereinigender Glücksbringer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9925] = {title = "Eine Frage der Sicherheit", objective = "Zerid beim Aerissteg in Nagrand möchte, dass Ihr 8 Ausgeburten der Leere in der Nähe des Oshu'gun tötet.", description = "Gezhe hat beschlossen, unsere Operation so nahe wie möglich am Oshu'gun zu postieren, ohne dabei einen Gedanken an die Sicherheit der Gruppe zu verschwenden. Warum? Weil er eine Erhöhung unserer Produktivität um zehn Prozent vorausgesehen hat, wenn er uns hier anstatt in den Bergen im Süden ansiedelt.\n\nUngeachtet der durchgedrehten Ausgeburten der Leere, die sich gerade mal 10 Fuß von uns weg aufhalten. Aber das ist das Problem des Sicherheitsoffiziers, nicht Gezhes.\n\nTötet ein paar dieser Ausgeburten für mich, und ich gebe Euch ein Zehntel meines Sicherheitsetats. Freut Euch nicht zu früh, viel Geld steht mir nicht zur Verfügung.", progress = nil, completion = "Ihr zaubert ein Lächeln auf mein Gesicht, &lt;Name&gt;. Zumindest würdet Ihr das, wenn ich noch ein Gesicht hätte.\n\nWenn Ihr so weiter macht werden wir noch beste Freunde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9927] = {title = "Erbarmungslose Gerissenheit", objective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge möchte, dass Ihr 10 Ogerbanner der Totschläger in die Körper von Bewohnern von Kil'sorge in der Festung Kil'sorge rammt.\n\nBringt unbenutzte Ogerbanner der Totschläger zu ihm zurück.", description = "<Lantresor reicht Euch einen Stapel Banner.>\n\nDies sind die Ogerbanner der Totschläger, die ich kürzlich erworben habe.\n\nIch möchte, dass Ihr zur Festung Kil'sorge reist und so viele wie möglich von diesem Abschaum von Kil'sorge tötet, wie Ihr nur könnt. Rammt ein Totschlägerbanner durch das Herz jedes gefallen Soldaten von Kil'sorge. Kehrt zu mir zurück wenn Ihr diese und die beiden anderen Aufgaben, die zu meinem Plan gehören, erledigt habt.", progress = "<Lantresor schaut Euch entgeistert an.>\n\nSchon fertig?", completion = "Könnt Ihr Euch vorstellen, wie verwirrt sie darüber sein werden, &lt;Volk&gt;? Das wird wundervoll.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9928] = {title = "Waffen zur Täuschung", objective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge Nagrand möchte, dass Ihr 10 Waffen von Kil'sorge besorgt.", description = "Wenn mein Plan gelingen soll, müsst Ihr ein paar Waffen von Kil'sorge in der Festung Kil'sorge stehlen.\n\nDurchsucht die Festung nach Kisten mit Waffen von Kil'sorge. Bringt mir alle, die Ihr finden könnt.\n\nDie Festung Kil'sorge liegt im Süden, etwas westlich von den Ruinen der Brennenden Klinge.", progress = "Wir werden einen nie dagewesenen Hass zwischen den beiden Klans säen!", completion = "Ausgezeichnet! Unser nächstes Ziel sind die Ruinen des Lachenden Schädels.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9931] = {title = "Sich für den Gefallen revanchieren", objective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr 10 Banner von Kil'sorge in die Leichen der Totschlägeroger in den Ruinen des Lachenden Schädels rammt.\n\nBringt unbenutzte Banner von Kil'sorge zu ihm zurück.", description = "Nun müsst Ihr den Wunsch nach Krieg in den fetten, nutzlosen Köpfen der Totschläger wecken. Im Nordwesten, bei den Bergen, findet Ihr die Ruinen des Lachenden Schädels.\n\n<Lantresor zeigt auf die Kiste mit den Waffen, die Ihr ihm gebracht habt.>\n\nErkennt Ihr diese Banner? Es sind Banner von Kil'sorge. Ich möchte, dass Ihr einen Stapel Banner von Kil'sorge nehmt und sie in die Leichen der Totschlägeroger rammt. Denkt daran, Ihr findet sie im Nordwesten.", progress = "Könnt Ihr vorhersehen, was als nächstes geschieht?", completion = "Der Plan ist perfekt, &lt;Name&gt;. Ich sehe jetzt schon die Früchte unserer Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9932] = {title = "Beweismaterial", objective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr die feuchte Wolldecke am lodernden Scheiterhaufen der Totschläger im Hof des Lachenden Schädels benutzt, um Signale an seine Oger zu senden.", description = "Euer Angriff auf die Festung Kil'sorge hat uns eine ganz besondere Möglichkeit eröffnet. Wir haben genügend Leichen, um es so aussehen zu lassen, als hätte eine große Schlacht stattgefunden.\n\nReist zu den Ruinen des Lachenden Schädels und sucht den Hof des Lachenden Schädels. Dort solltet Ihr einen brennenden Scheiterhaufen finden. Vergewissert Euch, dass die Gegend sicher ist, und benutzt diese Decke, um Rauchzeichen zu senden. Wenn meine Oger den Rauch sehen, werden sie sich einschleichen und die Leichen der toten Soldaten von Kil'sorge dort platzieren.\n\nDas sollte unser letzter Streich sein.", progress = "Wisst Ihr nun, warum Ihr nie einen Krieg gegen mich gewinnen würdet?", completion = "Ich muss zugeben, dass ich mich seit Jahrzehnten nicht mehr so lebendig gefühlt habe. Ihr habt gute Arbeit geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9933] = {title = "Nachricht für Telaar", objective = "Bringt das Friedensangebot der Brennenden Klinge zu Arechron nach Telaar in Nagrand.", description = "<Lantresor zeigt auf eine unbeschriftete Kiste.>\n\nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.\n\nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.\n\n<Lantresor verneigt sich.>", progress = "Frieden sagt Ihr?", completion = "Bitte, &lt;Name&gt;, nehmt Euch von diesem Friedensangebot was immer Ihr möchtet. Schließlich wäre dies ohne Eure Hilfe niemals möglich gewesen.", rewards = "Lantresors KriegsklingeAnhängergurt der Brennenden KlingeAuf Euch wartet eine dieser Belohnungen:\n\nKultistenband der Brennenden Klinge\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9934] = {title = "Nachricht für Garadar", objective = "Bringt das Friedensangebot der Brennenden Klinge zu Garrosh in Garadar.", description = "<Lantresor zeigt auf eine unbeschriftete Kiste.>\n\nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.\n\nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.\n\n<Lantresor verneigt sich.>", progress = "<Garrosh scheint von dem Angebot unbeeindruckt zu sein.>", completion = "&lt;Garrosh tritt die Kiste um.&gt;\n\nIhr verschwendet Eure Zeit, &lt;Volk&gt;. Nehmt Euch aus der Kiste was immer Ihr wollt. Weder ich noch Garadar haben für diesen unnützen Tand Verwendung.", rewards = "Lantresors KriegsklingeAnhängergurt der Brennenden KlingeAuf Euch wartet eine dieser Belohnungen:\n\nKultistenband der Brennenden Klinge\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9935] = {title = "Gesucht: Giselda die Alte", objective = "Tötet Giselda die Alte und 10 beliebige Agenten von Kil'sorge. Kehrt danach zu Aufseher Bullrok in Garadar zurück.", description = "Gesucht: Tot oder lebendig\n\nGiselda die Alte von Kil'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.\n\nAufenthaltsort in der Festung Kil'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.\n\nEine hohe Belohnung in Gold wird von Aufseher Bullrok in Garadar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.", progress = nil, completion = "Die Alte ist tot! Das sind wundervolle Nachrichten, &lt;Name&gt;. Hier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9936] = {title = "Gesucht: Giselda die Alte", objective = "Tötet Giselda die Alte und 10 beliebige Agenten von Kil'sorge. Kehrt danach zu Aufseher Moi'bff Jill in Telaar zurück.", description = "Gesucht: Tot oder lebendig\n\nGiselda die Alte von Kil'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.\n\nAufenthaltsort in der Festung Kil'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.\n\nEine hohe Belohnung in Gold wird von Aufseher Moi'bff Jill in Telaar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.", progress = nil, completion = "Die Alte ist tot! Das sind wundervolle Nachrichten, &lt;Name&gt;. Hier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9937] = {title = "Gesucht: Durn der Nimmersatte", objective = "Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Bullrok, wenn Ihr diese Aufgabe erledigt habt.", description = "Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, <Name>. Seid Ihr nun bereit für die Geißel der Geisterfelder?\n\nDurn der Nimmersatte regiert über das Gebiet beim Oshu'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.", progress = nil, completion = "Durns tödlicher Griff wurde gelöst! Nagrand schaut Dank Euch auf eine bessere Zukunft, Held. Gut gemacht!", rewards = "KristallkhopeshZehrender KnochenknüppelAzurlichtklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9938] = {title = "Gesucht: Durn der Nimmersatte", objective = "Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Moi'bff Jill, wenn Ihr diese Aufgabe erledigt habt.", description = "Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, <Name>. Seid Ihr nun bereit für die Geißel der Geisterfelder?\n\nDurn der Nimmersatte regiert über das Gebiet beim Oshu'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.", progress = nil, completion = "Durns tödlicher Griff wurde gelöst! Nagrand schaut Dank Euch auf eine bessere Zukunft, Held. Gut gemacht!", rewards = "KristallkhopeshZehrender KnochenknüppelAzurlichtklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9939] = {title = "Gesucht: Zorbo der Berater", objective = "Tötet Zorbo den Berater, 5 Schamanen der Totschläger und 5 Häscher der Totschläger. Meldet Euch bei Aufseher Bullrok, wenn Ihr die Aufgabe erledigt habt.", description = "Gesucht: tot oder lebendig\n\nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Garadar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Orcs getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.\n\nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.\n\nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Bullrok in Garadar ausbezahlt.", progress = nil, completion = "Dies ist ein großer Sieg für die Bewohner von Garadar! Gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9940] = {title = "Gesucht: Zorbo der Berater", objective = "Tötet Zorbo den Berater, 5 Schamanen der Totschläger und 5 Häscher der Totschläger. Meldet Euch bei Aufseher Moi'bff Jill, wenn Ihr die Aufgabe erledigt habt.", description = "Gesucht: tot oder lebendig\n\nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Telaar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Zerschlagene getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.\n\nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.\n\nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Moi'bff Jill in Telaar ausbezahlt.", progress = nil, completion = "Dies ist ein großer Sieg für die Bewohner von Telaar! Gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9944] = {title = "Verschollene mag'harische Prozession", objective = "Sucht nach der verschollenen mag'harischen Prozession.", description = "Großmutter sagt, dass wir durchhalten und unserem Volk dienen müssen. Sie sagt, dass wir Garrosh als Beispiel dienen müssen, zeigen, dass das Leben weitergeht.\n\nIch muss mich um so viele Dinge hier kümmern, besonders seit Großmutter krank ist. Würdet Ihr den Mag'har eine Gefallen tun, indem Ihr einer ihrer Matronen helft?\n\nVor ein paar Tagen haben wir einen Begräbniszug zum Ahnengrund geschickt, der noch nicht zurückgekehrt ist. Würdet Ihr nach ihnen suchen? Sie haben die westliche Straße aus Garadar hinaus genommen. Folgt ihr und meidet Halaa.", progress = nil, completion = "Dreißig Orcs, &lt;Volk&gt;! Von diesen dreißig sind nur noch Ungriz und ich übrig. Wir haben den jungen Orc, Saurfang, halb tot in der Nähe von Sonnenwind gefunden. Offensichtlich ist er aus einem anderen Grund hier...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9945] = {title = "Krieg den Totschlägern", objective = "Ältester Yorley bei der mag'harischen Prozession in Nagrand möchte, dass Ihr 8 Schläger der Totschläger und 8 Hexenmeister der Totschläger tötet.", description = "Wir waren auf dem Weg zum Ahnengrund, als wir in einen Hinterhalt der Totschläger geraten sind. Sie kamen von allen Seiten, haben viele der Wächter der Prozession getötet und auch viele andere. Sie haben sogar die Überreste des Ältesten im Wagen geschändet.\n\nUnd warum? Um uns zu erniedrigen und ihre Macht zu beweisen. Nicht einmal die Felsfäuste hätten sich zu so etwas herabgelassen.\n\nIch habe mich dem spirituellen Weg verschrieben, <Name>, aber auch ich kenne Grenzen. Sucht die Angreifer im Totschlägerhügel im Nordwesten und vernichtet sie!", progress = nil, completion = "Das ist ein guter Anfang, aber ihr Anführer muss getötet werden, damit Eure Taten auch langfristige Erfolge erzielen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9946] = {title = "Cho'war der Plünderer", objective = "Ältester Yorley bei der mag'harischen Prozession in Nagrand möchte, dass Ihr Cho'war den Plünderer tötet und Cho'wars Kopf besorgt.", description = "Habt Ihr je einen Ogerkönig gesehen, <Volk>? Nur wenige haben es überlebt und können davon erzählen. Unglücklicherweise haben wir es genau jetzt mit einem zu tun.\n\nDer Anführer dieser Barbaren ist ein Oger namens Cho'war. Gerüchten zufolge soll er die Gronn aus den Höhlen vertrieben haben. Danach hat sich Cho'war selbst zum König ernannt und die Ogerklans, die unter den Gronn gedient haben, aufgelöst. So entstanden die Totschläger.\n\nSucht tief in den Höhlen des Totschlägerhügels nach Cho'war. Tötet ihn und bringt mir seinen Kopf.", progress = "Er ist sicher sehr schwer bewacht.", completion = "Diesen Kopf stellen wir an dem Toren von Garadar auf, damit alle ihn sehen können. Die Oger werden es sich zweimal überlegen, bevor sie heilige Rituale der Mag'har stören.", rewards = "Bedeckung des OgertötersAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger des OgertötersBand des Ogertöters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9948] = {title = "Findet die Überlebenden", objective = "Ältester Ungriz bei der mag'harischen Prozession in Nagrand möchte, dass Ihr 5 gefangene Mag'har befreit.", description = "Wenn ich etwas über Oger weiß, dann dass sie Ihr Essen frisch mögen. Das bedeutet, dass die Mag'har, die sie gefangen haben, wahrscheinlich am Leben gehalten werden, bis sie verspeist werden sollen. Ich weiß, das ist ein grausamer Gedanke, aber wir müssen das zu unserem Vorteil ausnutzen.\n\nGeht zum Totschlägerhügel und sucht nach gefangenen Mag'har. Wenn Ihr Gefangene gefunden habt, holt Euch die Schlüssel von den Totschlägern in der Nähe.\n\nTötet die Oger, um an die Schlüssel zu gelangen, und befreit die Gefangenen.", progress = nil, completion = "Ihr habt geschafft, was keiner für möglich hielt und unsere vermissten Brüder und Schwestern zurückgebracht. Für die Mag'har seid Ihr ein Held, &lt;Name&gt;. Alle werden Euren Namen kennen und wissen, was Ihr für uns getan habt.", rewards = "Handfesseln der ErinnerungVerteidigerumhang der TotschlägerAuf Euch wartet eine dieser Belohnungen:\n\nTöterband der Totschläger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9951] = {title = "Es beobachtet Euch!", objective = "Tötet Naphthal'ar und kehrt dann zu Aufseher Baumlas im Cenariusdickicht in den Wäldern von Terokkar zurück.", description = "Schnell, versteckt Euch! Naphthal'ars Auge beobachtet Euch... uns alle!\n\nIch traue mich nicht, auf die Spitze des Turms zu gehen, um mit ihm zu sprechen, aber Ihr... Ihr seht aus, als könntet Ihr die richtigen Worte finden. Aber seid vorsichtig, es mag keine Witze und kann Dummköpfe nicht leiden.\n\nÜberredet es, auf eine Tasse Tee hinunterzukommen. Aber bitte sorgt dafür, dass es mich nicht mehr anstarrt!", progress = "Wir hätten sie nie zum Abendessen einladen sollen, so viel ist sicher!\n\nOder wir hätten zumindest auf ein paar Gänge vor dem Dessert, dass sie uns mitgebracht haben, bestehen sollen!", completion = "Es ist besser so. Wenn es keine zivilisierte Einladung annehmen kann, dann ist es das auch nicht wert.\n\n&lt;Aufseher Baumlas schaut Euch kurz verwirrt an.&gt;\n\nWer seid Ihr und was wollt Ihr hier? Ihr müsst von hier verschwinden, bevor es zu spät ist!", rewards = "Verrückter Umhang des CenariusBänder des VersonnenenKlinge des WahnsinnigenAuf Euch wartet eine dieser Belohnungen:\n\nGlücksreif des NarrenHalsreif des Wahnsinnigen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9954] = {title = "Corkis Lösegeld", objective = "Arechron möchte, dass Ihr Corki auf dem Totschlägerhügel findet.", description = "<Arechron zeigt Euch einen rußverschmierten Brief.>\n\nIch habe gerade diesen Brief erhalten. Er ist von einem Ogerstamm, die sich selbst Totschläger nennen. Sie herrschen über die nordwestlichen Gebiete von Nagrand. Hier steht, dass sie Corki in ihrer Gewalt haben, und sie drohen ihn aufzufressen, wenn wir nicht kooperieren. Nunja, Corki ist ein Dummkopf, aber er gehört zur Familie. Würdet Ihr ihn retten, <Name>?\n\nIch nehme an, dass er in einem Käfig auf dem Totschlägerhügel eingesperrt ist. Dort solltet Ihr zuerst nachsehen.", progress = nil, completion = "Diesmal haben sie mich gut eingesperrt, &lt;Name&gt;. Der König der Totschläger, Cho'war, hat den Schlüssel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9955] = {title = "Cho'war der Plünderer", objective = "Corki möchte, dass Ihr Cho'wars Schlüssel besorgt, um ihn aus dem Käfig zu befreien. Kehrt zu Arechron in Telaar zurück, falls Ihr Erfolg haben solltet.", description = "Sie nennen ihn Cho'war den Plünderer, <Name>. Er ist der Oger, der die Gronn, die über die Oger geherrscht hatten, vertrieben hat. Ihr könnt mir ruhig glauben, dass er mächtig ist!\n\nDer Chef hat gesagt, dass Cho'war in der großen Höhle wohnt - wo immer das auch sein mag... Besorgt diesen Schlüssel und holt mich hier raus! Wenn wir das hier überleben, wird mein Vater Euch sicher reich belohnen! Geht zu ihm sobald ich frei bin.", progress = nil, completion = "Danke, &lt;Name&gt;. Ich habe Corki zu den Nachtelfen im Schergrat geschickt. Hoffentlich gelingt es ihnen, ihn vom Ärger fern zu halten.\n\nWegen der Belohnung...", rewards = "Bedeckung des OgertötersAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger des OgertötersBand des Ogertöters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9956] = {title = "Die Überfallene Karawane", objective = "Jägerin Kima in Telaar in Nagrand möchte, dass Ihr 10 Vorratskisten von Telaar wiederbesorgt.", description = "Ich war bei einer Karawane dabei, die Vorräte zur Oreborzuflucht in den Zangarmarschen bringen sollte. An der Grenze zu den Marschen wurden wir jedoch von einer hinterlistigen Truppe von Totschlägerogern überfallen. Sie haben die anderen getötet und mich sowie all unsere Vorräte beschlagnahmt.\n\nZum Glück haben sie vergessen, meinen Käfig zu verriegeln. Als sie eingeschlafen waren, bin ich geflohen.\n\nEs ist zwar zu spät für meine Kameraden, aber wir könnten die gestohlenen Vorräte wirklich gebrauchen. Den Totschlägerhügel findet Ihr in den nordwestlichen Bergen von Nagrand.", progress = "Ich komme mir so dumm vor. Archerons Sohn, Corki, hat mich gefragt, was los ist, und ich habe es ihm gesagt. Jetzt ist er schon wieder verschwunden!", completion = "Erstaunlich! Wie habt Ihr es geschafft, all das alleine zurückzutragen?", rewards = "Handfesseln der ErinnerungVerteidigerumhang der TotschlägerAuf Euch wartet eine dieser Belohnungen:\n\nTöterband der Totschläger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9957] = {title = "Was ist los mit dem Cenariusdickicht?", objective = "Sprecht mit einem der Druiden beim Cenariusdickicht in den Wäldern von Terokkar.", description = "Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts in den Wäldern von Terokkar gehört.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Es gibt viele Wege dorthin, aber der kürzeste führt den Weg nach Süden entlang. Biegt die Straße nach Osten von Shattrath ab, wenn Ihr im Wald seid.", progress = nil, completion = "Ich bin froh, dass die Zuflucht Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9960] = {title = "Was ist los mit dem Cenariusdickicht?", objective = "Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.", description = "Hey Ihr da, <Klasse>! Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.", progress = nil, completion = "Ich bin froh, dass die Steinbrecherfeste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9961] = {title = "Was ist los mit dem Cenariusdickicht?", objective = "Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.", description = "<Klasse>, ich habe eine eilige Aufgabe für Euch. Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört. Das ist sehr merkwürdig, da sie sich normalerweise alle paar Tage bei uns melden.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.", progress = nil, completion = "Ich bin froh, dass Allerias Feste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9962] = {title = "Der Ring des Blutes: Schmetterzehe", objective = "Besiegt Schmetterzehe. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", description = "Seid Ihr bereit für den ersten Kampf? Wenn Ihr soweit seid, gebt mir Bescheid und ich bringe die Dinge ins Rollen. Ihr müsst nur im Ring des Blutes auf Euren ersten Gegner warten.\n\nEuer erster Herausforderer wird Schmetterzehe sein, ein grausamer Grollhuf.\n\nViel Glück! Ich hoffe, Ihr habt ein paar Freunde mitgebracht.\n\nUnd denkt daran, der Kampf ist erst zu Ende, wenn Ihr oder Euer Gegner mit dem Gesicht nach unten auf dem Boden liegt.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Hm, nicht schlecht. Gar nicht schlecht... Ihr habt Potenzial, Kleiner. Hier habt Ihr etwas Gold für Eure Taschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9967] = {title = "Der Ring des Blutes: Die Blaumänner", objective = "Besiegt die Zwillinge der Finsterblut, die sich selbst die Blaumänner nennen. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", description = "Im nächsten Kampf werdet Ihr auf gleich zwei Gegner treffen, Zwillinge um genau zu sein. Sie nennen sich selbst die \"Blaumänner\".\n\nEs ist noch nicht zu spät, um zu kneifen, <Name>. Ich könnte das verstehen.\n\nAber wenn Ihr bereit seid für ein wenig Action, tretet in den Ring des Blutes und wartet auf die Zwillinge der Finsterblut.\n\nDer Letzte, der noch steht, hat gewonnen!", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Ich gebe zu, dass ich nicht geglaubt habe, dass Ihr eine Chance hättet, &lt;Name&gt;! Das war beeindruckend! Wie wär's mit einem weiteren Kampf? Gurgthock hat den perfekten Gegner für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9968] = {title = "Fremde Energien", objective = "Sammelt 4 Teromottenproben und 4 Proben einer bösartigen Teromotte. Kehrt dann zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar zurück.", description = "Etwas Merkwürdiges hat die Teromotten des Dickichts verändert.\n\nWo einst eine Vielfalt von Arten herrschte, sind jetzt nur noch die Teromotten übrig. Und während sie früher friedlich waren, sind sie jetzt sehr aufgeregt und greifen alles an, was ihnen zu nahe kommt.\n\nIch muss die bösartigen mit den normalen Motten vergleichen. Bringt mir ein paar Exemplare von beiden Sorten. Die gewöhnlichen Teromotten findet Ihr im Süden und im Norden.\n\nIch bin mir sicher, dass dies mit dem Tod der Druiden zusammenhängt.", progress = "Habt Ihr meine Proben?", completion = "Merkwürdig. Die Proben der bösartigen Teromotten enthalten etwas, das sich wie reines Mana anfühlt.\n\nWie es scheint hinterließ das, was all die Tode verursacht hat, ein starkes Energiefeld. Aber aus irgendeinem Grund hat es die Teromotten nicht umgebracht, sondern nur aufgewühlt.\n\nEs scheint, als wäre diese merkwürdige Energie ein Nebenprodukt dessen, was das Gebüsch angegriffen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9970] = {title = "Der Ring des Blutes: Rokdar der Zerklüftete", objective = "Besiegt Rokdar den Zerklüfteten. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", description = "Das wird ein harter Kampf, <Name>. Habt Ihr vielleicht ein paar Freunde, die Euch helfen können? Den Ogern ist es gelungen, einen Riesen namens Rokdar aus dem Schergrat hierher zu bringen! Glaubt mir, Ihr werdet ein paar Freunde brauchen, er scheint unbesiegbar zu sein! Er ist hart wie Stein - im wahrsten Sinne des Wortes!\n\nWenn Ihr immer noch gegen ihn antreten möchtet, tretet in den Ring des Blutes und er wird kommen.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Ihr habt die Oger zum Schwitzen gebracht, Kleiner. Diesmal bekommt Ihr noch etwas dazu. Benutzt nicht alles auf einmal!\n\nSeid Ihr bereit für einen weiteren Kampf? Gurgthock setzt die ganze Bank auf Euch!", rewards = "Ihr bekommt:\n\nErstklassiger HeiltrankErstklassiger Manatrank"}
MultiLanguageQuestData['de'][9971] = {title = "Hinweise im Dickicht", objective = "Untersucht das merkwürdige Objekt neben der Leiche eines Zerschlagenen um herauszufinden, was hinter der Tragödie beim Cenariusdickicht steckt. Kehrt dann zu Erdbinder Tavgren außerhalb des Dickichts in den Wäldern von Terokkar zurück.", description = "Ich habe keine Ahnung, was all die Druiden hier getötet hat. Ich war ein paar Tage unterwegs, um die Knochenwüste im Süden zu untersuchen.\n\nBitte, Ihr müsst mir helfen herauszufinden, was hinter dieser furchtbaren Tragödie steckt. Geht zum Dickicht und haltet nach einem Hinweis Ausschau, der uns weiterhelfen könnte. Als ich kurz dort war, hätte ich schwören können, dass ich einen toten Zerschlagenen und ein merkwürdiges Ding neben ihm gesehen habe.\n\nUnd habt keine Angst vor Baumlas - er ist vielleicht durch die Geschehnisse verrückt geworden, aber ich glaube, er ist harmlos.", progress = nil, completion = "Ich hatte also Recht. Die Leiche eines Zerschlagenen? Und Ihr sagt, dass da tatsächlich ein komisches Objekt auf dem Boden neben ihm war?\n\nDas macht keinen Sinn. Was würde einer von ihnen denn hier wollen? Und was war das für ein Ding, das er dabei hatte?\n\nHat es vielleicht all die Tode verursacht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9972] = {title = "Der Ring des Blutes: Skra'gath", objective = "Besiegt Skra'gath. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", description = "Ihr bringt sie ja reihenweise um, <Kleiner/Kleine>! Dieses Mal haben sie einen Profi für den Kampf. Sie sagen er sei ein Leerenfürst oder so was... Sie wollen Euch auf keinen Fall gegen ihren Champion kämpfen lassen. Habt Ihr gehört wie Mogor, das Fallobst, Euch angekläfft hat? Die Wetten stehen astronomisch hoch!\n\nSteigt in den Ring und haut ihn um!", progress = nil, completion = "KLEINER! KLEINER IHR HABT ES GESCHAFFT! Als nächstes kommt der große Kampf! Die Meisterschaft!\n\nOk, locker bleiben. Wir wollen ja nicht, dass die Oger erfahren, dass hier was im Busch ist. Schließlich bekomme ich ja auch meinen Anteil daran.", rewards = "Ihr bekommt:\n\nErstklassiger HeiltrankErstklassiger ManatrankSchwerer Netherstoffverband"}
MultiLanguageQuestData['de'][9973] = {title = "Der Ring des Blutes: Champion der Totschläger", objective = "Besiegt den Champion der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener, um Eure Belohnung zu erhalten.", description = "Sie mussten den Champion aus den Gladiatorengruben im Schergrat einschiffen. Dort hat er mit den Bergriesen trainiert - mit gleich dreien auf einmal!\n\nWenn Ihr gegen ihn gewinnt, seid Ihr der neue Champion. Glaubt Ihr, Ihr habt eine Chance? Könnt Ihr das schaffen? Sagt mir nur Bescheid, dann setze ich mein Haus auf Euch.\n\nJetzt steigt in den Ring und gewinnt!", progress = nil, completion = "Oh je, Mogor hat sein Kampfrecht als Held der Totschläger eingefordert. Ihr müsst gegen ihn kämpfen!\n\nNiemand hat je behauptet, dass die Totschläger gute Verlierer... äh... Oger wären.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9977] = {title = "Der Ring des Blutes: Die letzte Herausforderung", objective = "Besiegt Mogor, Held der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", description = "<Gurgthock zählt seinen riesigen Berg Gold.>\n\nIhr habt viel Geld eingebracht, <Kleiner/Kleine>. Wenn Ihr Mogor besiegt, verspreche ich, dass es sich für euch lohnen wird. Die ganzen Schmerzen, die Ihr im Ring des Blutes aushalten musstet, werden sich bezahlt machen.\n\nJetzt geht da rein und zeigt diesen Ogern, was in Euch steckt!", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Gurgthock hat doch gesagt, dass es sich bezahlt machen wird, Kleiner. Sucht Euch was aus!", rewards = "Mogors KeulensegenBaton des KampfmagiersStab der BestienGewetzte Axt der LeereZeremonielle Blutklinge der TotschlägerZornesemblem der Mag'hariIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][9978] = {title = "Mit allen Mitteln", objective = "Findet Empoor. Er hält sich auf der Straße zwischen Tuurem und Shattrath in den Wäldern von Terokkar auf. Bringt ihn dazu, Euch zu erzählen, was Ihr wissen wollt.", description = "Ich bin mir nicht sicher, was das zu bedeuten hat, aber ich weiß, wie wir an weitere Hinweise kommen können.\n\nEmpoor ist ein Händler der Zerschlagenen, der mit allen Arten von Waren und Informationen handelt. Wenn wir ihn zum Reden bringen könnten, bin ich mir sicher, dass er etwas Interessantes zu sagen hätte.\n\nEr reist auf der Straße zwischen Tuurem und Shattrath hin und her. Seid aber vorsichtig, er hat einen Leibwächter.", progress = nil, completion = "Gut, gut... Ich sage Euch, was ich weiß, aber viel ist das nicht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9979] = {title = "Windhändler Lathrai", objective = "Sprecht mit Windhändler Lathrai in der Nähe der Taverne Weltenend im unteren Viertel in Shattrath.", description = "Ich wurde gebeten, ein paar Kästen mit Waren bei einem Astralen in Shattrath abzuholen und auszuliefern.\n\nAls ich ihn das letzte Mal gesehen habe, stand er außerhalb der Taverne Weltenend im Unteren Viertel. Sein Name ist Windhändler Lathrai, mehr weiß ich nicht!\n\nWenn Ihr mehr wissen wollt, dann fragt ihn selbst!", progress = nil, completion = "Ja? Wie kann ich Euch diesmal helfen, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9982] = {title = "Er nannte sich Altruis...", objective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", progress = nil, completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9983] = {title = "Er nannte sich Altruis...", objective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", progress = nil, completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9984] = {title = "Der Herr der versteckten Stadt", objective = "Bringt Luangas Befehle zu Andarl in Allerias Feste in den Wäldern von Terokkar.", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Deirom gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Thander erwähnt hat, dass Andarl die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9985] = {title = "Der Herr der versteckten Stadt", objective = "Bringt Luangas Befehle zu Kurgatok in der Steinbrecherfeste in den Wäldern von Terokkar.", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Dugar gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Rokag erwähnt hat, dass Kurgatok die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9986] = {title = "Die Arakkoa hindern", objective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Thander in Allerias Feste zurück.", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErstklassiger HeiltrankErstklassiger Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9987] = {title = "Die Arakkoa hindern", objective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Rokag in der Steinbrecherfeste zurück.", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErstklassiger HeiltrankErstklassiger Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][9988] = {title = "Der beste Freund eines Gecken", objective = "Bringt 30 Arakkoafedern zu Ros'eleth in Allerias Feste.", description = "Lasst Euch von Thander und seinem Gefolge nicht täuschen. Sie sehen vielleicht aus wie eine Gruppe von Furcht einflößenden Kriegern, aber sie sind nichts als eine Bande von Gecken!\n\nUnd sie lassen sich in der Öffentlichkeit nicht ohne ihre Hüte sehen. Das sind ganz schicke Teile aus Filz und Fell, mit den ausgefallensten Federn, die Ihr je gesehen habt.\n\nDie begehrtesten Federn stammen natürlich von den Arakkoa, und mein Vorrat geht langsam zur Neige. Ich würde Euch bezahlen, wenn Ihr sie für mich sammelt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArakkoajagdvorräte"}
MultiLanguageQuestData['de'][9989] = {title = "Fremde Geister", objective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", description = "Als ich in die Scherbenwelt kam und meine Ohren den Stimmen seiner Geister geöffnet habe, war ich erstaunt, was ich zu hören bekam. Nach einiger Zeit fand ich auch heraus, welche Geister ich nicht hören konnte.\n\nTrotz all meiner Versuche habe ich niemals mit den Geistern der Arakkoaahnen Kontakt aufnehmen können. Ihre Magie unterscheidet sich grundlegend von unserer, aber ich bin mir nicht sicher, ob ihre Geister außerhalb meiner Reichweite liegen.\n\nBringt mir die Federn vieler Arakkoa. Vielleicht kann ein Zeichen ihres Volks die nötige Verbindung herstellen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArakkoajagdvorräte"}
MultiLanguageQuestData['de'][9990] = {title = "Untersuchung von Tuurem", objective = "Findet den versiegelten Kasten und bringt ihn zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar.", description = "Wisst Ihr, jetzt, da Ihr es sagt, erinnere ich mich daran, dass ich Empoor vor etwa einem Monat mehrere Kästen mit merkwürdigen und fremdartigen Bauteilen verkauft habe. Ich weiß nicht, wozu sie gut sind, aber ich weiß, dass sie nach Tuurem geliefert werden sollten.\n\nVielleicht sind dort ja noch ein paar Kästen davon?", progress = "Welche Neuigkeiten bringt Ihr, <Name>?", completion = "Astrale? Waren nach Tuurem? Fremdartige Bauteile? Und ein Blutelf, der den letzten Kasten zum Posten der Feuerschwingen bringen wollte?\n\nWas soll das alles bedeuten?! Was hat das mit dem Schicksal der Druiden im Cenariusdickicht zu tun?\n\nIch glaube, wir sollten einmal einen Blick in den Kasten werfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9991] = {title = "Inspektion des Lagers", objective = "Lehnt Euch zurück und genießt Euren Flug. Sprecht mit Altruis wenn die Besichtigung abgeschlossen ist.", description = "Wenn Ihr meine Augen sein wollt, müsst Ihr sehr sorgfältig sein. Nethrandamus wird Euch durch die Lager der Legion führen, aber Ihr müsst alles, was Ihr seht, katalogisieren. Selbst das kleinste Detail, und wenn Euch noch so unwichtig erscheint, kann für unsere Zwecke hilfreich sein.\n\nZuerst möchte ich, dass Ihr notiert, welchen Aufbau das Lager hat und wie seine Verteidigungsmaßnahmen aussehen.\n\nNethrandamus ist bereit, wenn Ihr es seid, <Name>. Habt keine Angst, er wird Euch beschützen.", progress = "Noch nie auf einem Netherdrachen geflogen, was?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Jetzt haben wir einen Ausgangspunkt um unseren Gegenangriff zu planen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9992] = {title = "Olembasamen", objective = "Sammelt 30 Olembasamenkörner und kehrt dann zu Ros'eleth in Allerias Feste zurück.", description = "Sind die Bäume des Waldes nicht wunderschön? Ich habe mich schon oft gefragt, ob sie wohl auch in Azeroth wachsen würden.\n\nIch scheue mich jedoch davor, Keimlinge zurückzuschicken. Es ist ein anstrengender Weg und sie sind viel schwieriger zu transportieren als ein Sack mit Samen. Die Samenkörner wachsen in harten Zapfen, die von den Ästen der Bäume fallen, wenn sie reif sind.\n\nWenn Ihr auf Euren Reisen ein paar dieser Zapfen findet, könntet Ihr mir dann ein paar Samenkörner bringen?", progress = "Ich habe eine Samenkornsammlung angefangen, aber ich werde Hilfe brauchen, bis ich genügend zusammen habe, um sie nach Sturmwind zu schicken.", completion = "Vielen Dank für diese Samenkörner. Ich habe schon fast genügend zusammen, um eine erste Ladung zurückzuschicken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9993] = {title = "Olembaöl", objective = "Bringt 30 Olembasamenkörner zu Rakoria in der Steinbrecherfeste.", description = "Die öligen Samen der Olembabäume könnten sich als sehr wertvoll erweisen. Ich würde gern eine größere Menge davon sammeln und schauen, was ich daraus machen kann.\n\nStellt Euch nur vor, da steht ein ganzer Wald mit Bäumen, die so viele Samen produzieren, die alle ungenutzt bleiben. Mir ist egal, ob ich nur Salatöl, Waffenöl oder Lampenöl daraus herstellen kann, ich werde ihre Verschwendung nicht dulden!\n\nBringt mir alle Samen, die Ihr von den Olembazapfen sammeln könnt. Sie liegen hier überall.", progress = "Habt Ihr ein paar Samenkörner für mich?", completion = "Das ist ein guter Anfang, aber wir werden noch mehr davon brauchen, wenn wir eine angemessene Menge Öl herstellen wollen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9994] = {title = "Was ist das?", objective = "Bringt den Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar.", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n<Name>, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste im Südosten bringen. Vielleicht hat sie ja eine Ahnung, was das ist.", progress = "Ihr seht besorgt aus. Was ist los, <Klasse>?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.\n\nJa, wie ich befürchtet habe. Ich glaube, das sind Bombenteile. Unsere Augen und Ohren in Shattrath haben uns informiert, dass einige Astrale verbotene Waren aus anderen Dimensionen, mit denen sie in Kontakt stehen, einführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9995] = {title = "Was ist das?", objective = "Bringt den Kasten mit Ersatzteilen zu Tooki in der Steinbrecherfeste in den Wäldern von Terokkar.", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n<Name>, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Tooki in die Steinbrecherfeste im Südosten bringen. Vielleicht hat er ja eine Ahnung, was das ist.", progress = "Ihr seht besorgt aus. Was ist los, <Klasse>?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9996] = {title = "Angriff auf den Posten der Feuerschwingen", objective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Leutnant Meridian bei Allerias Posten in den Wäldern von Terokkar zurück.", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Norden und kümmert Euch darum!", progress = nil, completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9997] = {title = "Angriff auf den Posten der Feuerschwingen", objective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar zurück.", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Nordosten und kümmert Euch darum!", progress = "Berichtet. Was bringt Ihr Neues vom Posten der Feuerschwingen?", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9998] = {title = "Widerspenstige Nachbarn", objective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Theloria Dämmermantel bei Allerias Posten.", description = "Thander ist über die Ankunft der Höllenorcs bei den Ruinen vor Kurzem sowohl überrascht als auch besorgt. Sie haben keine Zeit verschwendet und sofort begonnen, Befestigungsanlagen zu bauen und die Gebäude zu reparieren.\n\nDie Bauarbeiten laufen Tag und Nacht, <Name>. Ich habe ein paar meiner zuverlässigsten Agenten losgeschickt, um die Situation zu überwachen, aber wir können uns keine Verzögerungen leisten. Geht gegen ihre Arbeiter vor und sucht dann nach Theloria Dämmermantel bei Allerias Posten nördlich der Ruinen der Knochenmalmer. Sie wird Euch weitere Anweisungen geben.", progress = nil, completion = "&lt;Die Hochelfe nickt.&gt;\n\nEs ist ein guter Anfang, aber Bertelm hatte Recht, Euch zu mir zu schicken. Ich habe eine Entdeckung gemacht, die die Anwesenheit der Höllenorcs hier erklären könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][9999] = {title = "Spiel auf Zeit", objective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr 2 Legionäre der Teufelswache, 3 Ingenieure der Mo'arg und 8 Tüftler der Gan'arg tötet.", description = "Solange die Transporter noch stehen, ist nichts, was wir gegen die Konstruktionslager unternehmen, von Dauer. Wir müssen einen Weg finden, die Gebäude der Legion zu zerstören.\n\nIch brauche Zeit, um einen Angriffsplan auszuarbeiten. Wenn Ihr die Ingenieure und Tüftler eine Weile beschäftigen könntet, würde das ihre Fortschritte verlangsamen, und ich hätte die Zeit, die ich benötige.", progress = nil, completion = "Wie ich es mir dachte. Es gibt keinen normalen Weg, Teufelsstahl zu zerstören. Es ist aber noch nicht alles verloren...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10000] = {title = "Unangenehme Gesellschaft", objective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Schattenpirscher Kaide.", description = "Unsere Streitkräfte in Thrallmar dachten, sie hätten die Höllenorcs der Höllenfeuerzitadelle unter Kontrolle, aber die Neuankömmlinge in den Ruinen im Osten sagen etwas anderes.\n\nWir können ihnen nicht erlauben, hier Fuß zu fassen. Rokag hat Schattenpirscher Kaide zu den Ruinen geschickt, um sie zu beobachten, aber wir müssen sie aufhalten, bevor sie es sich zu bequem machen.\n\nGeht zu den Ruinen, dezimiert ihre Peons und haltet bei den Bäumen im Norden nach Kaide Ausschau. Er wird Euch sagen, wo Ihr danach hingehen sollt.", progress = "Ich wollte gerade einen Bericht zu Rokag schicken und einen Angriff vorschlagen, aber wie ich sehe ist das nicht mehr nötig.", completion = "Um die Höllenorcs aufzuhalten müssen wir schon mehr tun, als ihre Arbeiter zu töten. Ich habe eine Entdeckung gemacht, die vielleicht erklären kann, warum sie hier sind, und die mich in meiner Überzeugung bestätigt, dass wir schnell handeln müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10001] = {title = "Der Meisterplaner", objective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners besorgt.", description = "Alle Konstruktionslager haben einen Meisterplaner. Der Meisterplaner bestimmt, welche Gebäude im Konstruktionslager vorhanden sein müssen, und wie sie platziert werden. Zudem werden diese Informationen auf Blaupausen festgehalten, die der Planer bei sich trägt.\n\nWir brauchen die Blaupausen des Meisterplaners. Mit solch detaillierten Informationen könnten wir einen meiner Bekannten dazu bewegen, uns etwas Unterstützung zu schicken.\n\nSucht den Meisterplaner der Mo'arg und stehlt seine Blaupausen. Er wird sich hinter den Konstruktionen aufhalten.", progress = "Bleibt auf jeden Fall von den Vorarbeitern fern. Sie dürfen nichts von Eurer Anwesenheit mitbekommen. Die Folgen könnten verheerend sein!", completion = "Mein Bekannter kennt hoffentlich einen Weg, die Lager zu zerstören. Er war schließlich mal ein Ingenieur der Legion...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10002] = {title = "Vermittler der Feuerschwingen", objective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Theloria Dämmermantel zurück.", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", progress = nil, completion = "&lt;Theloria nickt Euch zu.&gt;\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10003] = {title = "Vermittler der Feuerschwingen", objective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Schattenpirscher Kaide zurück.", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", progress = nil, completion = "&lt;Kaide nickt Euch zu.&gt;\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.\n\nWenn die Zeit gekommen ist, werde ich Rokag von unseren Fortschritten berichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10004] = {title = "Geduld und Verständnis", objective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal'salabim in Shattrath bringt und ihn überredet, euch zu helfen.", description = "Nehmt die Blaupausen und reist nach Shattrath in den Wäldern von Terokkar. Wenn Ihr in Shattrath seid, geht ins Untere Viertel sucht nach einem Mo'arg namens Sal'salabim. Er ist wahrscheinlich an der Bar und ertränkt seine Sorgen.\n\nDa fällt mir ein, dass Ihr ihn wahrscheinlich überreden müsst, uns zu helfen. Versucht ihm viel Geduld und Verständnis entgegenzubringen. Wenn das nichts hilft, dann versucht es mit Gewalt.", progress = "<Sal'salabim kratzt sich am Kopf.>\n\n[Dämonisch] Ik il romath sardon.", completion = "Beruhigt Euch, Schätzchen, Sal'salabim wird helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10005] = {title = "Erdbinder Tavgren Bescheid sagen", objective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", description = "<Name>, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", progress = nil, completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", rewards = "Beinplatten des CenariusdickichtsHelm des CenariusdickichtsReif des CenariusdickichtsWams des CenariusdickichtsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10006] = {title = "Erdbinder Tavgren Bescheid sagen", objective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", description = "<Name>, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", progress = nil, completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", rewards = "Beinplatten des CenariusdickichtsHelm des CenariusdickichtsReif des CenariusdickichtsWams des CenariusdickichtsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10007] = {title = "Die Reihen lichten", objective = "Tötet 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer und kehrt dann zu Theloria Dämmermantel zurück.", description = "So wie ich Thander und Bertelm kenne, werden sie nicht dulden, dass eine feindliche Macht so ein großes Lager direkt vor unserer Haustüre errichtet. Aber sie zu bitten, ein paar Leute ihrer Garnison zu schicken, um das Lager anzugreifen, steht auch nicht zur Debatte. Wir wären dann viel zu leicht angreifbar.\n\nWir müssen uns also selbst darum kümmern, die Bedrohung durch die Bauarbeiten der Höllenorcs zu verringern. Tötet alle von ihnen, die Ihr könnt, und ich sehe mich solange nach Verstärkung um.", progress = nil, completion = "Langsam sehen die Dinge besser aus. Wenn wir die Höllenorcs daran hindern können, ihre Kumpel hier zu unterstützen, können wir den Posten unter Kontrolle halten.", rewards = "Massiver EichenlangbogenTotauges KnarreZauberstab der dunklen WeissagungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10008] = {title = "Was in Terokkar geschieht, bleibt in Terokkar", objective = "Schattenpirscher Kaide möchte, dass Ihr 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer tötet.", description = "Wenn Thrallmar erfährt, dass sie es nicht geschafft haben, die Höllenorcs unter Kontrolle zu halten, werden wir hier bald viel Gesellschaft haben. Ehrlich gesagt bin ich mir nicht sicher, ob ich so viel Aufmerksamkeit möchte, deswegen behalten wir dieses kleine Problem für uns, verstanden?\n\nWenn wir den Höllenorcs genug Verluste beibringen können, besteht die Möglichkeit, dass niemand außerhalb der Steinbrecherfeste von ihrer Anwesenheit erfährt.\n\nMarschiert da rein, schwingt Eure Waffe, wedelt mit der Hand - oder was auch immer Ihr tut - und tötet die Höllenorcs!", progress = "Bitte sagt mir, dass ich nicht den Falschen auf diese Mission geschickt habe...", completion = "Ich weiß, dass Ihr schon weit gereist seid, &lt;Name&gt;, aber manche Geschichten sollten das Land niemals verlassen, haben wir uns verstanden?", rewards = "Massiver EichenlangbogenTotauges KnarreZauberstab der dunklen WeissagungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10009] = {title = "Ein paar Schädel spalten", objective = "Sal'salabim in Shattrath möchte, dass Ihr Raliqs Schulden, Kusch'kuschs Schulden und Floons Schulden eintreibt.", description = "<Sal'salabim lacht.>\n\nDas Sal'salabims Entwurf.\n\n<Sal'salabim zeigt auf die Architektur und die Anordnungen auf den Blaupausen.>\n\nSchaut Türme an. Dämonenjäger kann nicht sehen, oder? Armer, armer Altruis. Er weinen wenn er Augen hätte, oder?\n\nJa, Sal'salabim helfen, aber erst Ihr helfen Sal'salabim.\n\n<Sal'salabim gibt Euch einen Ordner.>\n\nDiese Wesen schulden Sal'salabim Gold. Viel Gold. Gehen für Sal'salabim eintreiben. Sie werden nicht einfach rausrücken Sal'salabims Gold. Müssen kämpfen, aber Ihr stark. Ihr besiegen Sal'salabim!", progress = "Ihr ja nicht kommen zurück ohne Sal'salabims Gold!", completion = "Nun, Geschäft sein Geschäft, aber wenn Sal'salabim Euch sagen, Ihr nicht böse werden, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10010] = {title = "So einfach ist das?", objective = "Sal'salabim in Shattrath möchte, dass Ihr zu Altruis dem Leider im westlichen Nagrand zurückkehrt.", description = "<Sal'salabim zeigt auf die Blaupause.>\n\nSeht Ihr, wo Teufelskanonen sind?\n\n<Sal'salabim zeichnet einen Pfeil, der einen Richtungswechsel anzeigt.>\n\nIhr dreht Teufelskanone um und richtet sie auf Gebäude.\n\nWartet! Nicht durchdrehen! Ihr wisst etwas nicht. Vorarbeiter haben Schlüssel, um Kanonen zu drehen. Ihr braucht erst Schlüssel! Einer von jedem Vorarbeiter!\n\nNicht so leicht, was?\n\nBringt Information zurück zu Altruis.", progress = nil, completion = "Natürlich! Wir werden sie mit ihren eigenen Waffen schlagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10011] = {title = "Konstruktionslager: zerstört", objective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr das Konstruktionslager: Hass und das Konstruktionslager: Furcht zerstört.", description = "Sammelt Euren Mut, <Name>. Ihr werdet ihn brauchen, wenn Ihr einem Vorarbeiter gegenübersteht.\n\nSobald Ihr bereit seid, sucht und tötet die Vorarbeiter in jedem Lager. Nehmt ihre Schlüssel und benutzt sie, um die Kanonen umzudrehen. Schießt damit auf die Lager. Kehrt zu mir zurück, wenn die Lager zerstört sind.", progress = "Schon fertig?", completion = "Wir haben gesiegt! Das Vorrücken der Legion wurde gebremst!\n\nIch biete Euch eine Auswahl an Belohnungen für Eure heldenhaften Taten!", rewards = "Brustplatte des KriegshetzersMetallisches Stirnband von Simm'onzGamaschen des nicht endenwollenden AngriffsTunika des BehütersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10012] = {title = "Höllenorcpläne", objective = "Bringt die Höllenorcpläne zu Bertelm in Allerias Feste in den Wäldern von Terokkar.", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Bertelm mehr über dieses merkwürdige Bündnis. Ihr beschließt, zu Allerias Feste zurückzukehren und ihm die Pläne zu zeigen.", progress = "Was habt Ihr da, <Name>?", completion = "&lt;Bertelm nimmt die Pläne und schaut sie an.&gt;\n\nWenn Ihr mir diese Pläne nicht gebracht hättet, hätte ich behauptet, dass Ihr irre seid, aber hier steht es ganz deutlich. Die Höllenorcs sind nicht nur hier, um den Blutelfen zu dienen, sie haben sogar den Auftrag, uns abzulenken.\n\nDiese Pläne werfen mehr Fragen auf, als sie beantworten, aber nun können wir uns besser vorstellen, womit wir es hier zu tun haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10013] = {title = "Eine ungesehene Hand", objective = "Bringt die Höllenorcpläne zu Rokag in der Steinbrecherfeste in den Wäldern von Terokkar.", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Rokag mehr über dieses merkwürdige Bündnis. Ihr beschließt, zur Steinbrecherfeste zurückzukehren und ihm die Pläne zu zeigen.", progress = "Was habt Ihr da, <Name>?", completion = "&lt;Rokag nimmt die Pläne und schaut sie an.&gt;\n\nKaide hatte also Recht! Diese Höllenorcs führen etwas im Schilde. Ich hätte jedoch nie gedacht, dass sie mit den Blutelfen zusammenarbeiten.\n\nLaut diesen Plänen sollen die Höllenorcs uns beschäftigen... aber warum? Das sind beunruhigende Nachrichten, &lt;Name&gt;. Gut, dass Ihr mir die Pläne gleich gebracht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10014] = {title = "Das Projekt des Postens der Feuerschwingen", objective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Meridian in Allerias Posten in den Wäldern von Terokkar.", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen Allerias Feste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10015] = {title = "Das Projekt des Postens der Feuerschwingen", objective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar.", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen die Steinbrecherfeste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10016] = {title = "Waldworgschwänze", objective = "Bertelm in Allerias Feste möchte, dass Ihr ihm 12 Waldworgschwänze bringt. Die Schwänze können von Waldworgs oder Waldworgalphas stammen.", description = "Seid Ihr auf Euren Reisen den Waldworgs begegnet? Ich hatte die Gelegenheit, sie zu beobachten, als ich einige der nördlichen Regionen des Waldes kartografiert habe. Ich würde Euch nicht empfehlen, zu nahe an sie heranzugehen, es sei denn, Ihr seid bereit für einen Kampf.\n\nSie haben keine Angst und scheuen vor nichts zurück, um ihr Territorium zu verteidigen.\n\nEs ist nicht verwunderlich, dass diese Kreaturen solch wundervolle Schwänze haben. Ich habe versucht, ein paar von ihnen zu sammeln, um einen neuen Mantel zu schneidern, aber die Worgs entkommen meinen Fallen dauernd. Wollt Ihr mir helfen?", progress = "Wie ich sehe habt Ihr die Gefahren des Waldes überlebt. Habt Ihr ein paar Schwänze für meinen Umhang?", completion = "Ah, gut gemacht, Freund. Sie sind noch feiner, als ich gedacht habe. Sie werden sicher einen schönen Umhang abgeben.\n\n&lt;Bertelm schaut zum Gasthaus hinüber.&gt;\n\nJa, das wird ein schöner Umhang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10017] = {title = "Schwindende Vorräte", objective = "Bringt 8 Schreckensgiftbeutel zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Immer mehr Flüchtlinge kommen Tag für Tag durch die Tore von Shattrath. Viele sind so schwer verwundet, dass es an ein Wunder grenzt, dass sie es überhaupt hierher geschafft haben.\n\nAls Heiler der Aldor kann ich die meisten gewöhnlichen Wunden verarzten. Vergiftete Wunden sind jedoch problematischer, da mir langsam die Vorräte an Gegengift ausgehen.\n\nBringt mir ein paar Schreckensgiftbeutel von den Schreckensspinnen hier in der Gegend, damit ich mehr davon herstellen kann. Ihr findet eine Gruppe von diesen Spinnen im Südosten von Terokkar.", progress = "Habt Ihr die Giftbeutel, <Name>? Diese Flüchtlinge können nicht mehr lange warten.", completion = "Ihr habt meinen Dank, &lt;Name&gt;. Die Aldor werden von Euren Taten erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10018] = {title = "Gewänder des Wolfgeistes", objective = "Bringt 12 Waldworgpelze zu Malukaz in der Steinbrecherfeste.", description = "Vor Generationen, als die Orcs die Wälder von Terokkar noch ihr Zuhause nannten, spielte der Wolfgeist eine große Rolle in ihrem Leben. Als die Orcs fortgingen, brauchten sie den Wolfgeist nicht mehr und haben ihn zurückgelassen.\n\nMit der Zeit wurde der Geist einsam und verließ die Wälder ebenfalls.\n\nIch glaube, dass ich den Wolfgeist zu seinem ursprünglichen Heim zurückbringen kann, wie auch wir Orcs zurückgekehrt sind. Das Ritual erfordert, dass ich ein Gewand aus den Pelzen der Wölfe der Wälder schneidere, um den Wolfgeist zu seinem Zuhause zurück zu geleiten.", progress = "Konntet Ihr alle Pelze, die ich benötige, finden?", completion = "Die Pelze sind perfekt, &lt;Name&gt;! Ich hätte keine besseren bekommen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10019] = {title = "Mehr Giftbeutel", objective = "Viele Flüchtlinge brauchen immer noch Heilung für ihre vergifteten Wunden. Habt Ihr mir noch mehr Giftbeutel gebracht, <Name>?", description = nil, progress = "Viele Flüchtlinge brauchen immer noch Heilung für ihre vergifteten Wunden. Habt Ihr mir noch mehr Giftbeutel gebracht, <Name>?", completion = "Ihr habt meinen Dank, &lt;Name&gt;. Die Naaru haben diese unglücklichen Seelen unter ihren Schutz gestellt. Es wäre sehr schade, wenn sie es bis Shattrath geschafft hätten, um dort an ihren Wunden zu verenden.", rewards = nil}
MultiLanguageQuestData['de'][10020] = {title = "Ein Heilmittel für Zahlia", objective = "Bringt Steinstarrers Blut zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Die Frau rechts von mir hat eine schwere Kopfverletzung erlitten. Sie hat zwar überlebt, aber ihr Augenlicht verloren.\n\nEin traditionelles Heilmittel meines Volkes verlangt das Blut eines sehr alten Basilisken.\n\nUnglücklicherweise leben die Basilisken von Terokkar wegen der Wilderei verschiedener Lager in der Regel nicht sehr lange.\n\nEs gibt jedoch einen Basilisken, dessen Name ich schon als Kind kannte. Er ist als Steinstarrer bekannt und soll östlich von hier leben, in der Nähe der Landesgrenze.\n\nBringt mir sein Blut, damit Zahlia wieder sehen kann.", progress = "Habt Ihr das Blut bekommen, <Name>? Ohne das Blut wird Zahlia ihrem Sohn nie wieder in die Augen schauen können.", completion = "Vielen Dank, &lt;Name&gt;. Sich um die Notleidenden zu kümmern ist eine schwierige Aufgabe, aber sie wird auf ihre ganz eigene Weise belohnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10021] = {title = "Das Licht wiederherstellen", objective = "Ishanah möchte, dass Ihr zum Arakkoaaußenposten östlich von Shattrath geht. Benutzt die gesegnete Phiole, um den östlichen Altar, den westlichen Altar und den nördlichen Altar zu reinigen.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Vor langer Zeit war ein Großteil dieses Gebiets von den Draenei bewohnt. Wir, die Aldor, hatten den Auftrag, unsere heiligen Stätten und Altäre zu beschützen. Doch seitdem wurden viele davon zerstört oder von unseren Feinden eingenommen.\n\nÖstlich von hier gibt es einen Außenposten der Arakkoa. Sie haben ihn mit voller Absicht auf dem Gebiet errichtet, auf dem drei unserer heiligen Altäre stehen. Die Arakkoa haben ihre üble Magie benutzt, um die ureigene Macht unserer Schreine zu verändern und zu schänden.\n\nBringt dies zum Arakkoaaußenposten und reinigt die drei Altäre.", progress = nil, completion = "Ihr habt meinen Dank, &lt;Name&gt;. Wir sind die Hüter des Lichts und können unsere Pflichten nicht vernachlässigen. Nicht einmal in den schwersten Zeiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Cast Blessed Vial Cleanup DND\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10022] = {title = "Der schwer zu fassende Eisenkiefer", objective = "Bringt Eisenkiefers Pelz zu Bertelm in Allerias Feste.", description = "Jetzt, da ich das Fell habe, das ich für mein Gewand benötige, dachte ich, dass der Pelz eines ganz bestimmten Wolfs eine schöne Kapuze für meinen Umhang abgeben würde. Stellt Euch nur vor, wie es wäre, Euren Feind im Pelz des gerissensten Raubtiers der Wälder zu sehen!\n\nIch habe bisher vergeblich versucht, Eisenkiefer zu fangen. Ich habe versucht ihn in die Enge zu treiben, ihn zu überlisten und ihn zu locken. Nichts hat geklappt.\n\nEr streunt in den nordöstlichen Gebieten des Waldes herum, und ich würde Euch angemessen belohnen, wenn Ihr schafft, was mir nie gelang.", progress = "Hat der alte Eisenkiefer Euch übers Ohr gehauen? Oder konntet Ihr den alten Gesellen überlisten?", completion = "Ich verneige mich vor Eurem Geschick, &lt;Name&gt;. Ihr habt Euch als herausragender Jäger bewiesen.\n\nIch werde Eure Hilfe bei der Herstellung dieses Umhangs nie vergessen. Er ist ein einzigartiges Gewand, das ich voller Stolz tragen werde.", rewards = "Helm der wölfischen ListHaube des WolfsjägersHelm der wölfischen AnmutHelm der wölfischen WildheitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10023] = {title = "Patriarch Eisenkiefer", objective = "Bringt Eisenkiefers Pelz zu Malukaz in der Steinbrecherfeste.", description = "Ihr habt gute Arbeit beim Sammeln der ersten Pelze geleistet.\n\nDas letzte Stück der Gewandung erfordert einen ganz besonderen Pelz. Es gibt einen bestimmten Wolf, der alt und gerissen ist, und sich dadurch den Rang des Patriarchen unter den Wölfen des Waldes verdient hat. Er ist unter ihnen als Eisenkiefer, der mächtige Jäger, bekannt.\n\nIn meinen Visionen habe ich ihn im Nordosten der Wälder umherstreifen sehen. Sein Pelz in meiner Gewandung wird sicher den Pfad des Wolfgeistes erhellen.\n\nBeklagt Eisenkiefer nicht. Er wird die ihm gebührende Ehre erhalten.", progress = "Der Geist wartet, <Name>. Habt Ihr den Pelz des Patriarchen?", completion = "Der Pelz ist noch vortrefflicher, als ich erhofft hatte! Das ist ein gutes Zeichen, &lt;Name&gt;, und die Geister werden Euch wegen Eurem Beitrag zu dieser Zeremonie wohl gesonnen sein.\n\nIch habe Euch aus dem übrigen Pelz einen Helm gemacht, &lt;Name&gt;. Er zeichnet Euch als mächtigen Jäger und Verbündeter des großen Wolfgeists der Wälder von Terokkar aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10024] = {title = "Voren'thals Visionen", objective = "Bringt 8 Augen eines Dunstschuppenbasilisken zu Arkanistin Adyria in Shattrath.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Unser Anführer, Voren'thal der Seher, war einst ein enger Vertrauter von Kael'thas. Seine prophetischen Visionen habe ihn gewarnt, dass Kaels Weg in der Zerstörung unseres Volkes enden würde.\n\nNormalerweise sind diese Visionen nur sehr vage und ungenau, aber unsere Alchemisten haben ein Elixier entwickelt, mit dessen Hilfe seine Visionen deutlicher werden. Unglücklicherweise erfordert das Elixier eine sehr seltene Zutat: Basiliskenaugen. Normalerweise bekomme ich sie von diesem aufgeblasenen Astralen, aber er hat mich enttäuscht.\n\nMacht Euch auf die Suche nach den Dunstschuppenbasilisken im gebirgigen Terokkar und bringt mir ihre Augen.", progress = "Habt Ihr die Basiliskenaugen für Voren'thals Elixier?", completion = "Sie sind in tadellosem Zustand, &lt;Name&gt;. Macht weiter so, und die Seher werden bald zu Euren Freunden zählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10025] = {title = "Mehr Basiliskenaugen", objective = "Um auch nur eine kleine Dosis von Voren'thals Elixier herzustellen, braucht man sehr viele Basiliskenaugen. Wenn Ihr mir mehr davon bringt, gewinnt Ihr sicher das Wohlwollen der Seher.", description = nil, progress = "Um auch nur eine kleine Dosis von Voren'thals Elixier herzustellen, braucht man sehr viele Basiliskenaugen. Wenn Ihr mir mehr davon bringt, gewinnt Ihr sicher das Wohlwollen der Seher.", completion = "Ich danke Euch, &lt;Name&gt;. Voren'thals Visionen können vielleicht eines Tages das Schicksal unseres Volks entscheiden. Wir tun gut daran, dafür zu sorgen, dass seine Visionen so klar wie möglich sind.", rewards = nil}
MultiLanguageQuestData['de'][10026] = {title = "Magische Störungen", objective = "Andarl in Allerias Feste möchte, dass Ihr 10 Sphärenjäger tötet.", description = "Es ist mir ein wenig peinlich, aber mir ist hier in den Wäldern von Terokkar etwas widerfahren, was mir seit meinen Lehrjahren nicht mehr passiert ist.\n\nManchmal scheitern meine Zauber, obwohl ich genau weiß, dass ich alles richtig gemacht habe. Ich bin fast wahnsinnig geworden, als das zum ersten Mal passiert ist.\n\nIch glaube, ich habe den Grund dafür gefunden. Die Wälder sind voller Wesen, die Sphärenjäger genannt werden. Das sind dämonische Kreaturen mit einem Hang zur Magie und zur Störung magischer Ströme. Der beste Weg, um mit ihnen fertigzuwerden, ist, sie einfach zu töten.", progress = nil, completion = "&lt;Andarl wischt sich die Stirn mit dem Ärmel seiner Robe ab.&gt;\n\nZum Glück. Ich habe schon befürchtet, dass die Biester die restlichen Waldbewohner vertrieben haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10027] = {title = "Magische Störungen", objective = "Tötet 10 Sphärenjäger und kehrt dann zu Kurgatok in der Steinbrecherfeste zurück.", description = "Es gibt nichts Ärgerlicheres, als einen Zauber vorzubereiten, und dann von einer unsichtbaren Macht unterbrochen zu werden. Nach dem vierten Mal wusste ich, dass es kein Zufall sein konnte, und habe Keb'ezil losgeschickt, um die Ursache herauszufinden.\n\nIch garantiere Euch, dass Ihr nie einen Wichtel treffen werdet, der widerspenstiger ist als Keb.\n\nWie auch immer, er konnte die Quelle des Problems finden, eine verteufelte Kreatur namens Sphärenjäger. Sie haben die Angewohnheit, überall, wo sie auftauchen, die magischen Energien zu stören. Ich habe genug von ihren Störungen.", progress = nil, completion = "Keb'ezil ist sehr erleichtert, dass Ihr Euch um das kleine Problem gekümmert habt, nicht wahr Keb?\n\n&lt;Der Wichtel ignoriert seinen Meister und scheint beleidigt zu sein.&gt;\n\nIhr müsst ihm seine schlechten Manieren nachsehen. Ihr wisst ja, wie Dämonen sind...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10028] = {title = "Gefäße der Macht", objective = "Bringt 8 Draeneigefäße zu Ros'eleth in Allerias Feste.", description = "Zwischen den Ruinen von Tuurem gibt es einige Gefäße mit roher, magischer Energie. Wir können von Glück sagen, dass die Zerschlagenen, die in der Stadt eingefallen sind, keine Ahnung von dieser Machtquelle mitten unter ihnen haben, aber wir dürfen nicht hoffen, dass das so bleibt.\n\nMithilfe dieser Gefäße und ihrer Macht können die verstreuten Überlebenden meines Volkes der Verlockung der dämonischen Magie widerstehen. Jeder Quel'dorei, den wir vor dem Wahnsinn unseres Prinzen retten können, ist einer mehr, der uns beim Wiederaufbau unseres verlorenen Ruhms helfen kann. Bringt mir die Gefäße, <Klasse>.", progress = "Konntet Ihr ein paar unbeschädigte Gefäße finden?", completion = "Ich hoffe, dass dies nicht die einzigen Gefäße in der Stadt sind. Es ist ein guter Anfang, aber ich schätze, wir werden noch viel mehr davon brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10029] = {title = "Die Geister rufen", objective = "Anachoret Lyteera möchte, dass Ihr ihren Gehilfen Soolaveen bei der Flüchtlingskarawane in der Knochenwüste der Wälder von Terokkar findet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.\n\nBereitgestellter Gegenstand: \n", description = "Die Geister der Toten in der Knochenwüste rufen nach mir! Sie leiden!\n\n<Klasse>, Ihr müsst zur Knochenwüste im Süden reisen und meinen Gehilfen Soolaveen bei der Flüchtlingskarawane aufsuchen. Er muss es auch spüren und wird Eure Hilfe dabei brauchen, die Geister dort zur Ruhe zu bringen.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht noch einholen. Ich weiß, dass sie in Norden der Knochenwüste Rast machen wollten, bevor sie weiter Richtung Süden nach Auchindoun ziehen wollten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10030] = {title = "Die Knochen zurückholen", objective = "Sammelt 10 ruhelose Knochen und bringt sie zu Ramdor dem Wahnsinnigen bei der westlichen Seite des Rings der Beobachtung in Auchindoun, das sich in der Mitte der Knochenwüste in den Wäldern von Terokkar befindet.", description = "Die Knochen der Draenei, die bei der Explosion von Auchindoun gestorben sind, sind überall in der Knochenwüste verstreut. Viele ihrer Geister sind daher ruhelos und können nicht ins nächste Leben übertreten.\n\n<Name>, Ihr müsst mir helfen, ihre Knochen wieder zu besorgen und sie zu ihrer letzten Ruhestätte zu bringen. Nur dann werden sie Frieden finden und den Segen des Lichts erlangen.\n\nSammelt die ruhelosen Knochen mit größter Vorsicht und bringt sie zu Ramdor dem Wahnsinnigen in Auchindoun in der Mitte der Knochenwüste. Trotz seines Namens wird er wissen, wie er sich um sie zu kümmern hat.", progress = "Was ist das? Wer seid Ihr?", completion = "Super, genau das, was ich brauche... noch mehr Knochen.\n\n&lt;Ramdor seufzt.&gt;\n\nJa, ja, ich werde mich darum kümmern, dass die Gebeine dieser ehrenwerten Vorfahren ein anständiges Begräbnis bekommen, keine Sorge.\n\nWenn Ihr den Toten wirklich helfen wollt, habe ich noch eine andere Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10031] = {title = "Den Verirrten den Weg zeigen", objective = "Tötet 10 verirrte Geister und 10 Skelette eines Zerschlagenen und kehrt dann zu Anachoret Soolaveen bei der Flüchtlingskarawane in der Knochenwüste in den Wäldern von Terokkar zurück.", description = "Viele Geister der Draenei wurden von der Explosion in Auchindoun verderbt und wandeln nun voller Pein in der Wüste.\n\n<Name>, ich flehe Euch an, gebt ihnen ihren Seelenfrieden wieder. Vernichtet die verirrten Geister und die Skelette der Zerschlagenen, die die Knochenwüste hinter den Mauern Auchindouns heimsuchen.\n\nWas? Ihr denkt, es wäre besser, sie in blinder Wut umherstreifen zu lassen?\n\nKehrt danach zu Anachoret Soolaveen bei der Flüchtlingskarawane zurück und berichtet ihm, was Ihr erreicht habt.", progress = nil, completion = "Ihr habt getan, was nötig war. Auch wenn es mich traurig macht, dass die Geister meiner Vorfahren zu schrecklichen Untoten verwandelt wurden, hat Euer Handeln sie endlich zur Ruhe gebracht.\n\nVielen Dank, dass Ihr sie befreit habt, &lt;Name&gt;. Bitte nehmt dieses bescheidene Zeichen meiner Hochachtung für Euch und Eure Selbstlosigkeit an.", rewards = "Gurt des reuigen SündersHandschuhe des JenseitsFlinke Stiefel des FlüchtlingsBand des LeidensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10032] = {title = "Artefakte von Tuurem", objective = "Sammelt 6 Artefakte von Tuurem von den Strauchdieben von Tuurem und den Jägern von Tuurem und bringt sie zu Rakoria in der Steinbrecherfeste.", description = "Ist Euch das Verhalten der Verirrten in Tuurem aufgefallen? Sie streifen in den Ruinen umher und suchen nach allen Überbleibseln der Draenei, die sie in die Finger bekommen können.\n\nIhre zerschlagenen Meister wissen es besser. Sie haben ihr früheres Leben abgestreift und sind zu etwas ganz anderem geworden.\n\nIch glaube, wir können die Gier der Verirrten ausnutzen und alte Draeneirelikte von ihnen sammeln. Warum sollten wir unser Leben im Kampf gegen die Zerschlagenen riskieren, wenn wir unsere Ziele weise auswählen können?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10033] = {title = "Aufruf: Tötet die Knochenpeitscher!", objective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar.", description = "Es wurde ein Kopfgeld auf die Knochenpeitscher der Knochenwüste ausgesetzt. Als Überträger der Pest müssen sie von nun an vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nMeldet Euch bei Taela Immerlauf, um Eure Belohnung einzufordern.", progress = nil, completion = "Ja, ich bin mir sicher, dass Ihr all die Knochenpeitscher getötet habt. Ist ja auch klar, weil der Hauptmann auf dem Anschlag einen Beweis gefordert hat.\n\n&lt;Taela schaut Euch sarkastisch an.&gt;\n\nIch nehme Euch beim Wort. Ich bin mir nicht sicher, wen ich so geärgert habe, dass ich zu diesem Dienst verdonnert wurde, aber vielen Dank für Eure Mühe für die Allianz. Hier habt Ihr eine Entschädigung für Euren Aufwand.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10034] = {title = "Aufruf: Tötet die Knochenpeitscher!", objective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar.", description = "Die Knochenpeitscher der Knochenwüste haben Mawg gebissen und ihn krank gemacht. Jetzt möchte er, dass sie alle vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nKehrt zu Mawg Grimmschlag zurück, wenn Ihr die Aufgabe erledigt habt, und er wird Euch gut belohnen.", progress = nil, completion = "Ihr müsst viele von diesen Knochenpeitschern getötet haben! Gut, ich hasse sie! Seit mich einer von ihnen gebissen hat, habe ich dauernd Ohnmachtsanfälle.\n\nWisst Ihr, wie peinlich das ist? Hier, nehmt dies als Dank, dass Ihr meine Rache vollstreckt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10035] = {title = "Torgos!", objective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar zurück.", description = "In der Knochenwüste gibt es ein Wesen, das so bösartig, so widerlich und so Furcht einflößend ist, dass nur die besten Jäger es wagen, ihm aufzulauern.\n\nIch spreche von Torgos, dem König der Knochenpeitscher, der sich beim Rhazeversteck am westlichen Ende der Weiten herumtreibt.\n\nUnglücklicherweise haben die Arakkoa eine Vogelscheuche aufgestellt, die als 'Torgos' Fluch' bekannt ist und ihn von dort fernhält. Ich wette, dass er trotzdem herauskommen würde, wenn Ihr den Leichnam seines Weibchens Trachela am Fuß dieser Vogelscheuche platziert. Ihr findet sie beim Aashügel im nördlichen Teil der Wüste.\n\nBringt mir eine Schwanzfeder von Torgos.", progress = "Habt Ihr die Feder? Muss ich Euch für Eure waghalsige Kühnheit belohnen?", completion = "Ich bin beeindruckt, &lt;Klasse&gt;. Torgos war eines der hartgesottensten Wesen, das ich auf dieser Seite von Nagrand kenne.\n\nNun, ich denke, Ihr habt Euch etwas aus dem Schatz von Allerias Feste verdient. Sucht Euch etwas aus!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTerokkarschrifttafel der PräzisionTerokkarschrifttafel des Elans\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10036] = {title = "Torgos!", objective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", description = "Ich will Torgos, den König der Knochenpeitscher tot sehen!\n\nVor nicht allzu langer Zeit, als ich beim Rhazeversteck am westlichen Ende der Wüste auf Jagd war, fiel dieses Tier mich an.\n\n<Mawg tippt seine Augenklappe an.>\n\nEr hat mir mein Auge genommen, und nun will ich sein Leben dafür! Bringt mir eine seiner Schwanzfedern als Beweis und ich werde Euch gebührlich belohnen.\n\nIhr werdet den Leichnam seines Weibchens Trachela brauchen, um ihn hervorzulocken, da er Todesangst vor der alten Vogelscheuche der Arakkoa hat, die als Torgos' Fluch bekannt ist.\n\nIhr findet sie beim Aashügel im Norden der Wüste.", progress = "Habt Ihr ihn getötet? Ist Torgos tot?\n\nHabt Ihr den Beweis?", completion = "Ich danke Euch, &lt;Name&gt;. Ihr habt meine Rache ausgeübt, und wie versprochen werde ich Euch belohnen.\n\nSucht Euch hiervon etwas aus und benutzt es weise!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTerokkarschrifttafel der PräzisionTerokkarschrifttafel des Elans\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10037] = {title = "Ich würd' lieber angeln", objective = "Bringt 8 makellose Schimmerschuppenaale zu Seth in Shattrath.", description = "Da wir gerade von Seen sprechen, da gibt es einen See im Nordosten, an dem man richtig toll angeln kann. Früher bin ich da immer mit meinen Freunden hin, aber meine Mutter erlaubt es mir nicht mehr.\n\nSie sagt, es sei zu gefährlich, aber ich habe da oben noch nichts außer ein paar Spinnen gesehen. Als ob Spinnen einem irgendwas anhaben könnten...\n\nIch mochte am liebsten die Aale von da oben. Wenn Ihr zum See hoch geht, könntet Ihr mir dann ein paar dieser Aale bringen? Sie sind störrisch, aber wenn man sie einmal gebändigt hat, kann man sie ganz leicht mitnehmen.", progress = "<Seth zieht Euch am Mantel.>\n\nHabt Ihr die Aale? Hä? Hä?", completion = "Danke! Ich kann mich nicht erinnern, wann ich das letzte Mal Aal gegessen habe.\n\nWie soll ich sie bloß kochen?", rewards = "Ihr bekommt:\n\nSeths Grafitangelrute"}
MultiLanguageQuestData['de'][10038] = {title = "Sprecht mit Gefreiter Wöch", objective = "Sprecht mit Gefreiter Wöch in der Nähe des nördlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", description = "Ich habe gerade einen Bericht von einem unserer Späher in der Nähe von Grangol'var erhalten. Er sagt, dass eine schattenhafte Truppe in die Ruinen dort eingezogen ist.\n\n<Name>, ich möchte, dass Ihr mit Gefreiter Wöch sprecht und schaut, wie Ihr ihm dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht nach Westen an der Steinbrecherfeste vorbei. Sein letzter Bericht besagt, dass er sich in der Nähe des nördlichen Eingangs zum Dorf befindet.", progress = nil, completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Allerias Feste geschickt!\n\nBürokratie!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10039] = {title = "Sprecht mit Späherin Neftis", objective = "Sprecht mit Späherin Neftis in der Nähe des südlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", description = "Ich wurde informiert, dass eine unserer Späherinnen in der Nähe von Grangol'var zurzeit eine schattenhafte Truppe beobachtet, die vor Kurzem dorthin gezogen ist.\n\n<Name>, ich möchte, dass Ihr mit Späherin Neftis sprecht und schaut, wie Ihr ihr dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht von hier aus nach Süden und dann nach Westen, um den Norden der Knochenwüste herum. Ihr letzter Bericht besagt, dass sie sich in der Nähe des südlichen Eingangs zum Dorf befindet.", progress = nil, completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Steinbrecherfeste geschickt!\n\nBlutelfen und ihre Bürokratie!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10040] = {title = "Wer sind sie?", objective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Gefreiter Wöch in Grangol'var in den Wäldern von Terokkar zurück.", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", progress = "Habt Ihr schon mit ihnen gesprochen? Was hatten sie zu sagen?", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10041] = {title = "Wer sind sie?", objective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Späherin Neftis in Grangol'var in den Wäldern von Terokkar zurück.", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", progress = nil, completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10042] = {title = "Tötet den Schattenrat!", objective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Leutnant Kieshammer in Allerias Feste in den Wäldern von Terokkar zurück.", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n<Name>, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Leutnant Kieshammer in Allerias Feste.\n\nViel Glück, <Klasse>.", progress = nil, completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Wöch zu helfen. Das letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n&lt;Name&gt;, als Anerkennung für Eure Taten in Grangol'var erlaube ich Euch hiermit, Euch eine dieser wundervollen Belohungen auszusuchen.", rewards = "Besonders scharfe KlingeStachelzerstörerUnbesiegbarer StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10043] = {title = "Tötet den Schattenrat!", objective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n<Name>, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Beraterin Faila in der Steinbrecherfeste.\n\nViel Glück, <Klasse>!", progress = nil, completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Neftis zu helfen. Das letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n&lt;Name&gt;, Ihr habt Euch etwas Nettes verdient. Sucht Euch etwas aus.", rewards = "Besonders scharfe KlingeStachelzerstörerUnbesiegbarer StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10044] = {title = "Ein Besuch bei der Großmutter", objective = "Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat.", description = "Die Großmutter hat mich gebeten, Euch aufzusuchen und Euch eine Nachricht zu überbringen. Sie möchte unverzüglich mit Euch sprechen.\n\nMein Wille mag vielleicht gebrochen sein, aber macht besser keinen Fehler, <Name>. Wenn Ihr die Großmutter verärgert, werde ich Euch mit aller Kraft, die noch in mir steckt, bestrafen. Ihr findet sie in der Haupthalle.\n\n<Garrosh zeigt auf das große Gebäude im Norden.>\n\nHört Euch an, was sie zu sagen hat, und tut, was sie Euch aufträgt.", progress = "Bitte setzt Euch, mein Kind.", completion = "Wir müssen zuerst Euren Geist erweitern, damit Ihr mit den Ahnen sprechen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10045] = {title = "Zutaten sammeln", objective = "Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt.", description = "Mutter Kashur möchte mit Euch sprechen, <Name>. Bevor Ihr das könnt, müsst Ihr jedoch ein paar Kräuter sammeln, um einen Trank zuzubereiten, der Euren Geist erweitert, damit Ihr mit den Geistern sprechen könnt.\n\nIhr müsst Olembawurzeln aus Terokkar, Marschenbeeren aus den Zangarmarschen, Telaarifarn aus Nagrand und Drachenwirbel aus dem Schergrat sammeln. Ich habe die Anleitung zum Anbau dieser Kräuter auf dieses Pergament geschrieben. Kehrt zu mir zurück, wenn Ihr die Zutaten beisammen habt.", progress = "Hallo, Kind.", completion = "Ihr seid sehr geschickt, &lt;Name&gt;. Unsere besten Kräutersammler hätten doppelt so lange gebraucht, um die Kräuter zu sammeln.\n\n\n\nHabt keine Angst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10046] = {title = "Durch das Dunkle Portal", objective = "Reist durch das Dunkle Portal und sprecht mit Nazgrel in Thrallmar.Vor zwei Wochen haben unsere Späher beobachtet, wie eine schwer bewaffnete Streitmacht der Allianz unter dem Kommando von Feldkommandeur Romus aus der Burg Nethergarde aufgebrochen ist. Mit so vielen Soldaten, Vorräten und einem so erfahrenen Kommandanten können sie nur ein Ziel haben: die Scherbenwelt.\n\nDer Kriegshäuptling hat eine Vorhut durch das Portal geschickt, aber wenn die Allianz glaubt, dass so viele Truppen von Nöten sind, sollten vielleicht auch wir Verstärkung schicken.\n\nReist durch das Dunkle Portal und meldet Euch bei Nazgrel in Thrallmar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Vor zwei Wochen haben unsere Späher beobachtet, wie eine schwer bewaffnete Streitmacht der Allianz unter dem Kommando von Feldkommandeur Romus aus der Burg Nethergarde aufgebrochen ist. Mit so vielen Soldaten, Vorräten und einem so erfahrenen Kommandanten können sie nur ein Ziel haben: die Scherbenwelt.\n\nDer Kriegshäuptling hat eine Vorhut durch das Portal geschickt, aber wenn die Allianz glaubt, dass so viele Truppen von Nöten sind, sollten vielleicht auch wir Verstärkung schicken.\n\nReist durch das Dunkle Portal und meldet Euch bei Nazgrel in Thrallmar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10047] = {title = "Der Pfad des Ruhms", objective = "Reinigt 8 zertrampelte Skelette auf dem Pfad des Ruhms mit dem Weihwasser der Draenei und kehrt dann zu Warpseher Kryv in der Ehrenfeste zurück.", description = "Sie haben sie den Pfad des Ruhms genannt, eine Straße, die vom Herzen ihrer grausamen Festung zum Dunklen Portal führt, befestigt mit den Knochen meines Volks.\n\nEs war ihnen nicht genug, uns wie Tiere zu jagen, unsere Städte zu zerstören und die Überlebenden zu quälen. Nein, sie mussten auch noch unsere Knochen als Pflastersteine verwenden, und meinen Brüdern und Schwestern ein anständiges Begräbnis unter dem Licht verweigern.\n\nDiese gequälten Seelen wandeln immer noch durch diese Lande und schreien nach Erlösung. Ich bitte Euch, <Name>, helft mir, sie beizusetzen.", progress = "Die Schreie scheinen irgendwie... schwächer geworden zu sein. Möge das Licht dafür sorgen, dass es nicht nur Wunschdenken ist.", completion = "Ihr habt meinen aufrichtigen Dank für Eure Mühen, &lt;Name&gt;. Wenn auch noch viel zu tun ist, macht es mich froh, dass einige nun ihren wohlverdienten Frieden gefunden haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10050] = {title = "Unerschütterliche Seelen", objective = "Ehrenwache Wesilow möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter beim Expeditionsrüstlager tötet.", description = "Am Ende unserer Invasion wurde das Rüstlager im Süden von den heimtückischen Todesrittern der Horde angegriffen. Diese bösartigen Schemen haben die Verteidiger des Rüstlagers verflucht und ihre Seelen zwischen dem Reich der Lebenden und dem der Toten gefangen.\n\nDiese ehrwürdigen Seelen müssen befreit werden! Ich bitte Euch, <Name>, beendet das Leid meiner Kameraden, denn ich bringe es nicht selbst übers Herz, sie zu töten.", progress = nil, completion = "Die Söhne sind Euch für Eure Mühen dankbar, auch wenn nur wenige über das Rüstlager sprechen möchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10051] = {title = "Ausbruch aus dem Posten der Feuerschwingen!", objective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Hauptmann Auric Sonnenjäger in Allerias Feste in den Wäldern von Terokkar.", description = "Was für ein Glück, dass Ihr hier seid!\n\n<Klasse>, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit von Allerias Feste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", progress = nil, completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist. Garstige Blutelfen!\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Allerias Feste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", rewards = "Axt von TerokkarHeilerstab des WaldesBlutdurstiges MesserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10052] = {title = "Ausbruch aus dem Posten der Feuerschwingen!", objective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terkkokar.", description = "Was für ein Glück, dass Ihr hier seid!\n\n<Klasse>, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit der Steinbrecherfeste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", progress = nil, completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist.\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Die Steinbrecherfeste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", rewards = "Axt von TerokkarHeilerstab des WaldesBlutdurstiges MesserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10055] = {title = "Nichts verkommen lassen!", objective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Dumphry in der Ehrenfeste.", description = "Verstärkung ist gut, aber ich sehe nicht, dass sie irgendwelche Karren mit Barren oder Holz durch die Gegend ziehen.\n\nSchaut Euch um, Freund. Die Bäume sind knapp und die Minen voller Legionsabschaum.\n\nMir gehen die Vorräte aus. Ich versuche schon, sie, wo ich kann, zu ersetzen. Aber so langsam müssen wir anfangen, alles, was wir bekommen können, wiederzuverwenden.\n\nAm südlichen Ende des Pfads des Ruhms steht ein Haufen alter Belagerungsmaschinen 'rum. Ein paar der Teile kann man immer noch verwenden. Habt Ihr Lust, mir bei einer kleinen Wiederverwertungsaktion zu helfen?", progress = "Habt Ihr ein wenig wiederverwertbares Material unter all dem Staub, der Asche und der Kohle finden können?", completion = "Das hier ist in einem besseren Zustand, als ich befürchtet habe. Sicher, es wird eine Weile dauern bis der ganze Rost und Zunder entfernt ist, aber ich kann mich nicht beklagen.", rewards = "Geisterhafter KopfputzBrustschutz des KampfsuchersBeschlagener Helm des LegionärsSchienbeinschützer des MagistratsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10057] = {title = "Suche nach den Anführern", objective = "Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Ehrenwache Wesilow im Turm nordwestlich der Ehrenfeste zurück.", description = "Trotz Eurer Bemühungen haben wir immer noch Probleme am Expeditionsrüstlager. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.\n\nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?\n\nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.", progress = nil, completion = "Wir können nur hoffen, dass die Geister der Fußsoldaten mit dem Verschwinden der Geister ihrer Offiziere zur Ruhe kommen. Ich danke Euch ein weiteres Mal für Eure Hilfe, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDraenethystkranzKette des VollstreckersFein gefertigte Kette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10058] = {title = "Ein altes Geschenk", objective = "Besorgt die Geheimnisse des Lichts und bringt das Buch zu Vater Malgor Devidicus in der Ehrenfeste zurück.", description = "<Der Blick des Priesters wandert langsam von seiner Tasse zu Euch.>\n\nHabt Ihr nichts Besseres zu tun, als einen Mann von seiner Tasse fernzuhalten?\n\nAch, was soll's. Ich bin der Meinung, dass Neuankömmlinge ein gutes Zeichen sind. Was würde Turalyon davon halten?\n\nIch erinnere mich noch an den Tag unserer Abreise, als ich ihm die Geheimnisse des Lichts gab. Während des Feldzugs und den folgenden Jahren hat er nicht einen einzigen Tag vergessen, seinen Mannen einen Abschnitt daraus vorzulesen.\n\nAls er uns wieder verließ, gab er mir das Buch zurück, damit ich bis zu seiner Rückkehr darauf aufpasse, aber ich Dummkopf dachte, es sei in meinem Quartier in der Waffenkammer sicher...", progress = "Ich dachte, ich hätte Euch gesagt, dass Ihr mich nicht stören sollt. Was gibt's?", completion = "Ist es das? Kaum zu glauben, dass es die Schlacht überlebt hat. Die Gegebenheiten in den Ruinen waren nicht gerade gut für das Buch, aber ich bin dennoch froh, dass ich es wiederhabe.\n\nEs ist das einzige Zeichen, das ich von Turalyon habe.\n\n&lt;Vater Devidicus scheint mit den Tränen zu kämpfen.&gt;\n\nWenn man so lange Zeit Seite an Seite gekämpft hat, steht man sich noch näher als die eigene Familie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10061] = {title = "Die Unerschütterlichen", objective = "Grelag möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberhexer und 5 unerschütterliche Ritter am Expeditionsrüstlager südlich der Ehrenfeste tötet.", description = "Als die Höllenorcs der Knochenmalmer das Expeditionsrüstlager angegriffen haben, fiel unsere Garnison sehr schnell. Es war eine kurze, blutige und grausame Schlacht. Es gab keine Überlebenden.\n\nObwohl wir die Toten begraben und uns an den Höllenorcs gerächt haben, spuken die Geister der Gefallenen immer noch in den Ruinen. Seit kurzem habe ich Visionen, in denen diese Geister zu einer Gefahr für Thrallmar werden.\n\nEs gibt nur einen Weg, um die Geister zur Ruhe zu bringen - Ihr müsst sie im Kampf besiegen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10063] = {title = "Forscherliga, für Gnome geeignet?", objective = "Zieht los und sucht nach Klopper Knacksklug, der sich in einem alten Schildkrötenpanzer an der Küste nördlich der Blutwacht eingerichtet hat.", description = "Kindermädchen! Glaubt Ihr das?\n\nSie haben mich von einer viel versprechenden Grabung abgezogen und mit Odesyus' Expedition losgeschickt, um das Kindermädchen für diesen kleinen Gnom zu spielen!\n\nIch habe noch nie von einem Gnom gehört, der Ausgrabungsleiter werden wollte, Ihr etwa?\n\nAnscheinend nehmen wir jetzt auch Gnome und dieser ist wohl besonders von Murlocs fasziniert!\n\nNun gut, er ist losgezogen und hat sich in einem alten Schildkrötenpanzer an der nördlichen Küste der Insel eingerichtet. Geht und seht selbst, wenn Ihr mir nicht glaubt!", progress = nil, completion = "Dachte ich's mir doch! Dieser mürrische alte Zwerg sollte mir eigentlich beim Transport meiner Ausrüstung und dem Sammeln von Daten helfen, aber stattdessen sitzt er nur in dem komischen Draeneidorf herum und betrinkt sich sinnlos.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10064] = {title = "Sprecht zu der Hand", objective = "Erstattet Späherin Jorli bei Verteidigers Ruh' Bericht.", description = "Die Hand von Argus hat bei Verteidigers Ruh' einen Vorposten eingerichtet, allerdings sind sie dort den Blutelfen und auch der Wildnis zahlenmäßig weit unterlegen. Ihrem Posten droht ohne Verstärkung bald der Fall und somit würden wir die Ereignisse bei der Vektorspule nicht länger im Auge behalten können.\n\nErstattet Späherin Jorli bei Verteidigers Ruh' im Nordwesten Bericht und bietet ihr Eure Hilfe an, <Name>.", progress = nil, completion = "Ich habe gehofft, dass die Blutwacht uns Verstärkung schicken würde, sobald man dort weiß, mit wem wir es hier zu tun haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10065] = {title = "Eine Schneise schlagen", objective = "Tötet 10 wütende Felshetzer und kehrt zu Späherin Jorli bei Verteidigers Ruh' zurück.", description = "Während unserer Mission, die Sonnenfalken und ihr Portal auszukundschaften, wurde ich ernsthaft verletzt. Späherin Loryi konnte glücklicherweise die Blutung stillen und sucht gerade nach einem Weg, um mich zur Blutwacht zu bringen.\n\nUnser Problem liegt allerdings darin, dass wir unsere Stellung hier verlassen müssen, um eine sichere Rückkehr garantieren zu können.\n\nSobald wir diesen sicheren Grund verlassen, werden uns Felshetzer anfallen. Wenn Ihr ein paar der wütenden Felshetzer aus dem Weg räumen könntet, würden wir höchstwahrscheinlich sicher an unser Ziel gelangen.", progress = nil, completion = "Es sieht da draußen schon etwas besser aus, ich bin mir jedoch noch immer nicht sicher, ob es besser wäre, hier auf medizinische Versorgung zu warten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10066] = {title = "Alles im Griff", objective = "Tötet 8 mutierte Greifer und meldet Euch bei Verteidigerin Corin bei Verteidigers Ruh'.", description = "Wir wagen es nicht, unseren Posten zu verlassen oder uns zu weit von Verteidigers Ruh' zu entfernen, <Volk>. Die mutierten Kreaturen, die sich in der unmittelbaren Nähe der Vektorspule aufhielten, wurden schwerwiegend von der Energie beeinflusst, die den Kristallen entweicht.\n\nDie mutierten Greifer scheinen bis zu einem gewissen Grad Empfindungen entwickelt zu haben. Sie haben gelernt, tückische Fallen zu erschaffen, aufzustellen und zu verbergen, damit sich selbst die umsichtigsten Kämpfer darin verfangen.\n\nWir werden niemals gegen die Sonnenfalken vorgehen können, wenn wir ständig auf unsere Schritte Acht geben müssen. Packt das Problem bei der Wurzel, <Name>.", progress = "Konntet Ihr ein paar mutierte Greifer ausmerzen?", completion = "Gut gemacht, &lt;Name&gt;. Ohne die Tücken der Greifer, wird es jetzt wesentlich einfacher sein, Verstärkung von der Blutwacht zu erhalten oder Angriffe gegen die Sonnenfalken zu starten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10067] = {title = "Besudelte Wassergeister", objective = "Tötet 6 besudelte Wassergeister und kehrt zu Verteidigerin Corin bei Verteidigers Ruh' zurück.", description = "Die meisten der Kreaturen, die von der Energie der Kristalle berührt wurden, wurden auf die gleiche Art verdorben: seltsame Male auf ihrer Haut, aggressiveres Verhalten und kleine Kristallsplitter in ihren Körpern. Wie dem auch sei, die besudelten Wassergeister der Blutmythosinsel scheinen sich vollständig in Kristall zu verwandeln.\n\nIch habe bis jetzt noch nichts gesehen, was derart auf die Kristalle reagiert hat. Als wir den Besudelten Teich untersucht haben, haben sie sich als besonders gefährlich herausgestellt. Wir müssen sie loswerden, bevor die Sonnenfalken sie als neue Energiequelle missbrauchen können.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Es ist besonders wichtig, dass wir keine Möglichkeit außer Acht lassen, die den Sonnenfalken weiterhin ihre Existenz sichern könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10068] = {title = "Frostnova", objective = "Erreicht Stufe 3 und erlernt Frostnova. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt Frostnova 2-mal.", description = "Je stärker Ihr werdet, desto mehr entwickelt sich Eure Verbindung zum Arkanen und Ihr findet Zugang zu neuen Zaubern.\n\n\n\nMacht Euch auf, um noch stärker zu werden. Und wenn Ihr etwas Neues gelernt habt, kommt Ihr zurück, um es mir zu demonstrieren.", progress = nil, completion = "Ah, wie schön, ein &lt;Klasse&gt;. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10069] = {title = "Die Wege des Lichts", objective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Wirkt 'Siegel des Befehls' auf Euch selbst, sucht eine Trainingsattrappe auf und trefft sie.", description = "Es ist an der Zeit, Eure erste Lektion in den Wegen des Lichts zu lernen, <Name>. Durch das Schlagen von Schlachten, werdet Ihr dem Licht näher kommen und Ihr werdet neue Fähigkeiten erlernen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Kehrt dann zu mir zurück, demonstriert sie mir und wir werden Eure Ausbildung fortsetzen.", progress = "Habt Ihr Eure neuen Fertigkeiten geübt?", completion = "Ah, wie schön, ein &lt;Klasse&gt;. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10070] = {title = "Zuverlässiger Schuss", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe vor dem Sonnenturm und übt daran fünfmal 'Zuverlässiger Schuss'.", description = "Und nun ist es an der Zeit für Eure erste Lektion.\n\nSobald Ihr mehr Erfahrung gesammelt habt, werdet Ihr neue Techniken entdecken.\n\nGeht, sammelt mehr Erfahrung und erlernt Eure erste neue Fähigkeit. Wenn Ihr das getan habt, sucht eine der Trainingsattrappen draußen auf und probiert sie daran aus.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr könnt auf Euren Fortschritt stolz sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10071] = {title = "Ausweiden", objective = "Erreicht Stufe 3 und erlernt das Ausweiden. Macht dann eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt Ausweiden 3-mal.", description = "Je stärker Ihr werdet, desto mehr Tricks werdet Ihr herausfinden können.\n\nEine der ersten Techniken, die Ihr lernen werdet, ist wahrscheinlich das Ausweiden des Gegners, nachdem Ihr schon ein paar erste Treffer gelandet habt.\n\nSorgt dafür, dass Ihr etwas Erfahrung sammeln könnt, lernt diese Technik und dann übt sie weiter an einer der Trainingsattrappen da draußen.", progress = nil, completion = "Ah, wie schön, ein &lt;Klasse&gt;. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10072] = {title = "Das richtige Wort", objective = "Erreicht Stufe 3, um das Schattenwort: Schmerz zu erlernen. Wirkt es dann 5-mal auf die Trainingsattrappen in der Nähe.", description = "Je mehr Fertigkeiten Ihr erlangt, desto größer wird die Auswahl der Euch zur Verfügung stehenden Kräfte.\n\nIch möchte, dass Ihr loszieht, noch mehr Erfahrung sammelt und einen neuen Zauber entdeckt. Wenn Euch dies gelungen ist, kommt zurück und beweist mir Euer neues Wissen.", progress = nil, completion = "Ah, wie schön, ein &lt;Klasse&gt;. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10073] = {title = "Verderbnis", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt daran fünfmal das Wirken von 'Verderbnis'.", description = "Mittlerweile habt Ihr die Gerüchte über unsereins, die Hexenmeister, gehört. Schenkt ihnen keine Beachtung; es sind diejenigen, die neidisch auf unsere furchteinflößende Macht sind, die solche Lügen verbreiten.\n\nWenn Ihr Erfahrungen sammelt, werdet Ihr die Mysterien entschlüsseln, die es Euch erlauben, die Teufelsenergien zu kontrollieren.\n\nGeht, setzt Euren Weg fort, bis Ihr eine neue Technik entdeckt habt. Ich möchte, dass Ihr diesen neuen Zauber an den Trainingsattrappen vor dem Sonnenturm ausprobiert.", progress = "Habt Ihr den Feuerbrand gemeistert?", completion = "Ah, wie schön, eine &lt;Klasse&gt;. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10074] = {title = "Kristallpulver von Oshu'gun", objective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiterin Amereldine in Halaa.", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, das Ihr bei den Rüstmeistern eintauschen könnt.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, &lt;Name&gt;. Das wird uns in unserem Kampf gegen den Abschaum der Allianz helfen, der sich hier in der Scherbenwelt breitgemacht hat.", rewards = "Ihr bekommt:\n\nForschermarke von Halaa"}
MultiLanguageQuestData['de'][10075] = {title = "Kristallpulver von Oshu'gun", objective = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", description = nil, progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", completion = "Ich nehme immer gerne Kristallpulverspenden an, &lt;Name&gt;. Ihr werdet für jedes Bündel, das Ihr mir bringt, entlohnt werden.", rewards = "Ihr bekommt:\n\nForschermarke von Halaa"}
MultiLanguageQuestData['de'][10076] = {title = "Kristallpulver von Oshu'gun", objective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiter Kartos in Halaa.", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, &lt;Name&gt;. Das wird uns in unserem Kampf gegen den Abschaum der Horde helfen, der sich hier in der Scherbenwelt breitgemacht hat.", rewards = "Ihr bekommt:\n\nForschermarke von Halaa"}
MultiLanguageQuestData['de'][10077] = {title = "Kristallpulver von Oshu'gun", objective = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", description = nil, progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", completion = "Ich danke Euch für Euren Beitrag, &lt;Name&gt;. Wenn Ihr noch mehr finden solltet, wisst Ihr, wo Ihr sie hinbringen könnt.", rewards = "Ihr bekommt:\n\nForschermarke von Halaa"}
MultiLanguageQuestData['de'][10078] = {title = "Die Unerwünschten zerstören", objective = "Zündet die Klingenwerfer der Horde mit der flammenden Fackel am Pfad des Ruhms an. Kehrt dann mit der flammenden Fackel zu Dumphry in der Ehrenfeste zurück.", description = "Jetzt, da unsere Bergungsaktion ins Rollen gekommen ist, ist es an der Zeit, die zweite Phase unseres Plans einzuläuten.\n\nAm Pfad des Ruhms hat die Horde immer noch ihre alten Klingenwerfer postiert. Lasst Euch von Ihrem Alter nicht täuschen, <Name>, sie sind immer noch sehr gefährlich. So sehr wir auch versuchen, alles zurückzuerobern, was wir können, können wir nicht erwarten, dass die Horde ihre Waffen einfach so abbaut.\n\nNehmt diese Fackel und zündet ihre übriggebliebene Belagerungsausrüstung an. Ich werde die Sicherheit der Ehrenfeste nicht dem Zufall überlassen.", progress = "Ihr scheint guter Laune zu sein. Haben die brennenden Belagerungsmaschinen der Horde Euch erheitert?", completion = "Das nenne ich Einsatz!\n\nIch bin froh, dass wir endlich Unterstützung erhalten haben, aber ich bin nicht so sicher, ob sie die richtige Einstellung gegenüber der Horde haben. Dort, wo ich herkomme, ist jeder, der eine Waffe auf Euch richtet, ein Feind und muss vernichtet werden.", rewards = "Genähte Beinkleider des WanderersNaturgenähter KiltHelm der VerwandtschaftSchuppenmalbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10079] = {title = "Bringt diese Mine zum Beben!", objective = "Tötet 12 Pioniere der Gan'arg und kehrt dann zu Großknecht Biggums zurück.", description = "Die Mine wurde von diesem Gan'argpack überrannt!\n\nSie haben nicht nur meine Arbeiter aus den Tunneln getrieben, sondern hämmern auch noch Tag und Nacht darin herum! Und jetzt sitzt mir auch noch Danath im Rücken! Sagt, er würde mir meine Bierration streichen, wenn ich mich nicht bald darum kümmere!\n\nKeiner der Minenarbeiter will dort hineingehen, und die Wächter sind zu sehr damit beschäftigt, sich vollaufen zu lassen.\n\nIch flehe Euch an, <Name>, helft mir! Danath mag mir meinen Stolz nehmen, aber niemals mein Bier!", progress = nil, completion = "Bei Bronzebarts bronzenem... Bart, Ihr habt es geschafft! Ihr seid ein Held, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10081] = {title = "Mutter Kashur treffen", objective = "Großmutter Geyah möchte, dass Ihr mit Mutter Kashur sprecht.", description = "Erschreckt Euch nicht über das, was Ihr sehen werdet, wenn die Wirkung eintritt. Diese Geister sind überall um uns herum - immer. Der Trank erlaubt Euch nur, sie zu verstehen und zu sehen. Ihr werdet seine Wirkung brauchen, wenn Ihr mit Mutter Kashur sprecht.\n\nIhr findet sie ein gutes Stück im Südwesten beim Ahnengrund.", progress = nil, completion = "Der Trank, den Ihr zu Euch genommen habt, hat keine echte Wirkung. Ihr könnt einen Geist nur sehen, wenn er es zulässt. Der Trank ist nur ein Symbol Eures Glaubens und Eurer Hingabe. Es war ein Test. Und Ihr habt ihn bestanden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10082] = {title = "Die aufgebrachten Ahnen", objective = "Mutter Kashur möchte, dass Ihr 8 aufgebrachte Orcgeister tötet.", description = "Seht Ihr, wie sie unter uns wandeln? Der Ahnengrund ist normalerweise sehr ruhig und friedlich.\n\nIn letzter Zeit haben sich die Geister der Ahnen jedoch erhoben und sind sehr aufgebracht. Etwas muss sie sehr stören. Wir müssen herausfinden, was das sein könnte, aber zuerst müssen wir die direkte Bedrohung beseitigen.\n\nDie Geister, die Ihr hier seht, sind nicht wirklich unsere Ahnen, sondern ein Abbild ihrer gegenwärtigen Lage. Ihr müsst die aufgebrachten Orcgeister zerstören. Tut dies und kehrt dann zu mir zurück.", progress = nil, completion = "Es ergibt keinen Sinn. Sie erheben sich weiter. Es muss etwas Heimtückischeres dahinter stecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10085] = {title = "Ein Besuch bei den Ahnen", objective = "Mutter Kashur im Ahnengrund in Nagrand möchte, dass Ihr den Sonnenwindposten, die Ruinen des Lachenden Schädels, Garadar und die Ruinen des Blutenden Auges besucht.", description = "Ich brauche Euch, um zu den Dörfern unserer Ahnen zu reisen, <Name>. Geht zu jedem einzelnen und schaut, ob unsere Vorfahren noch da sind.\n\nGeht zum Sonnenwindposten im Norden, zu den Ruinen des Lachenden Schädels ganz im Norden bei den Bergen, besucht Garadar im Nordosten und zuletzt die Ruinen des Blutenden Auges an der Grenze zwischen Nagrand und den Wäldern von Terokkar im Osten.\n\nBerichtet mir, sobald Ihr die Ahnen in ihrem Zuhause beobachtet habt.", progress = nil, completion = "Das ist sehr beunruhigend. Ihr sagt keiner der Ahnen war in seinem Dorf? Sie gehen alle nach Süden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10086] = {title = "Ich arbeite... für die Horde!", objective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Megzeg Knaxknöchel in Thrallmar.", description = "Könnt Ihr das fassen? Diese Orcs haben mich angeheuert, um ihre beschädigten Befestigungsanlagen abzustützen und Sprengstoff herzustellen. Ist das nicht ein Traumjob? Nur zu schade, dass uns die Materialien ausgehen, aber ein gewitzter Goblin wie ich weiß sich immer zu helfen!\n\nKönntet Ihr mich dabei unterstützen? Ich benötige ein wenig gebrauchtes Holz und Metall von den zerstörten Belagerungsmaschinen entlang des Pfads des Ruhmes. Geht dorthin und sammelt, aber gebt auf diese rothäutigen Orcs Acht!\n\nWenn Ihr fertig seid, kommt zurück und holt Euch eine fette Belohnung ab!", progress = "Wie geht es mit der Sammelaktion voran? Habt Ihr etwas Wiederverwertbares finden können?", completion = "Die Materialien sind ausgezeichnet! Vielleicht ein wenig verbogen oder angesengt, aber ich habe mich noch nie von minderwertigem Material aufhalten lassen, wenn es darum ging, Präzisionssprengstoff herzustellen!\n\nDanke, &lt;Name&gt;. Ihr habt wirklich ein Händchen exquisiten Müll!", rewards = "Geisterhafter KopfputzBrustschutz des KampfsuchersBeschlagener Helm des LegionärsSchienbeinschützer des MagistratsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10087] = {title = "Zündet es an... für die Horde!", objective = "Zündet die östliche und die westliche Kanone der Allianz mit der flammenden Fackel an und kehrt danach zu Megzeg Knaxknöchel in Thrallmar zurück.", description = "Ich bin ein glücklicher, glücklicher Goblin! Ich darf hier Sprengstoff und Killermaschinen herstellen in der Gewissheit, dass sie sofort bei wichtigen Missionen eingesetzt werden!\n\nWo wir gerade von Missionen sprechen, ich habe einen Befehl aus Thrallmar erhalten: Verbrennt die Kanonen der Allianz entlang des Pfads des Ruhms... die Kanonen, die gefährlich auf die Befestigungsanlagen der Horde gerichtet sind. Nehmt diese Fackel und begebt Euch zu jeder Kanone. Zündet die Fackel an und bestaunt den Funkenflug!", progress = "Ich habe nach Zeichen von brennenden Kanonen Ausschau gehalten - Rauchschwaden oder den Schreien brennender Höllenorcs...\n\nHattet Ihr Erfolg mit Eurem Auftrag?", completion = "Dachte ich's mir doch! Ich konnte die Zerstörung von hier aus zwar nicht richtig sehen, aber ich kann sie mir redlich vorstellen! Ausgezeichnet!\n\nGut gemacht, &lt;Name&gt;. Das oberste Kommando von Thrallmar wird sich freuen, von Eurem Erfolg zu hören!", rewards = "Genähte Beinkleider des WanderersNaturgenähter KiltHelm der VerwandtschaftSchuppenmalbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10091] = {title = "Seeleninstrumente", objective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath.", description = "Pah! Sie haben mich gefoltert und versucht, etwas über die Verteidigungsanlagen von Shattrath aus mir herauszuquetschen.\n\nIch habe mich geweigert - da haben sie die anderen Spione an Höllenschlund verfüttert, und ich sollte der Nächste sein. Aber ich habe ihnen nichts verraten!\n\nSie sind wahnsinnig! Sie sind versessen darauf, dämonische Mächte zu beschwören, die sie auf gar keinen Fall kontrollieren können!\n\nSie benutzen besondere Seeleninstrumente, um ihre Seelensplitter herzustellen und ihre Beschwörungen noch mächtiger zu machen. Ihr müsst ihnen diese Instrumente stehlen!\n\nIch würde Euch ja begleiten, aber ich muss nach Shattrath zurück um der Spionagemeisterin des Unteren Viertels zu berichten.", progress = "Ja? Was kann ich für Euch tun, <Klasse>?", completion = "To'gun hat mir bereits seinen Bericht abgeliefert. Er hätte Euch unterstützen sollen!\n\nIch habe ihn zurückgeschickt, um Grik'tha zu helfen. Ich finde, die beiden sind ein schönes Paar.\n\nDies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Ich finde, sie sehen gefährlich aus. Vielleicht können die Seher sie brauchen?\n\nHier, nehmt einen davon als Belohnung für Euren Kampf gegen den Schattenrat im Labyrinth.", rewards = "Eiserne Armschützer der Sha'tariArmschienen der AuchenaiHandgelenksschützer der SpionagemeisterinWickeltücher von ShattrathIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10093] = {title = "Der Tempel von Telhamat", objective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat im Westen der Höllenfeuerhalbinsel.", description = "Zum Glück ist der Pfad des Ruhms nicht das einzige Zeichen meines Volks in diesen Ländereien. Im Westen befinden sich immer noch ein paar unserer geheiligten Stätten, auch wenn einige von ihnen überrannt wurden.\n\nWährend Velen sich auf seine Reise nach Azeroth vorbereitete, haben diejenigen von uns, die hier bleiben sollten, versucht, sich wieder in unseren heiligen Orten niederzulassen.\n\nIm westlichen Teil der Höllenfeuerhalbinsel könnt Ihr beim Tempel von Telhamat eine kleine Gruppe von Draenei finden, die von Amaan dem Weisen angeführt werden. Ich bin mir sicher, dass er Euch gerne kennenlernen würde.", progress = nil, completion = "Ah, Ihr habt also Seher Kryv getroffen. Er ist ein weiser und begabter Mann, und seine Freunde sind auch meine Freunde.\n\nMacht es Euch gemütlich und stellt Euch den anderen vor, die diesen Tempel ihr Zuhause nennen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10094] = {title = "Der Kodex des Blutes", objective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", description = "Es ist nun zwei Jahre her, dass die Beschwörung des Schattenrats dieses einst großartige Mausoleum explodieren und die Knochenwüste entstehen lies.\n\nJetzt befinden sie sich im Krieg mit einer unglaublich mächtigen Kraft im Inneren.\n\n<Name>, Ihr müsst in das Schattenlabyrinth eindringen und herausfinden, wogegen sie kämpfen und ob es eine Gefahr für uns sein könnte. Unserer Spione haben berichtet, dass sie ein verbotenes Buch mit unheiligen Beschwörungen verwenden, bekannt als der Kodex des Blutes.\n\nSucht in ihm nach Antworten.", progress = nil, completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig falsch!\n\nIhr lest weiter, aber was Ihr lest scheint unglaublich zu sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10095] = {title = "In das Herz des Labyrinths", objective = "Vernichtet Murmur und informiert danach Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath über die Geschehnisse im Schattenlabyrinth.", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren! Es hat die Explosion von Auchindoun verursacht und die Knochenwüste erschaffen.\n\nJetzt nur noch als Murmur bekannt, droht es, den Schattenrat zu überrennen und zu entkommen!\n\nNun, da der Großmeister und der Rest der Führung tot sind, seid Ihr die einzige Hoffnung der Scherbenwelt im Kampf gegen dieses Monster!\n\n<Name>, tief in Eurem Herzen wisst Ihr, dass Ihr und Eure Freunde nicht versagen dürfen!", progress = nil, completion = "Murmur ist fast ausgebrochen?! Sie haben das Biest zwei Jahre sicher im Inneren verwahrt... Ich frage mich, was sie wohl falsch gemacht haben, dass sie nach all der Zeit die Kontrolle darüber verlieren.\n\nWas auch immer es sein mag, &lt;Name&gt;, Ihr habt uns alle gerettet! Mir wird schwindelig, wenn ich daran denke, was Shattrath und dem Rest der Scherbenwelt zugestoßen wäre, wenn das Ding sich hätte befreien können!\n\nIch bin so froh, dass Ihr die Sache in die Hand genommen und die Bedrohung durch den Schattenrat in Auchindoun beseitigt habt. Wie können wir Euch je dafür belohnen?", rewards = "Eiserne Schienbeinschützer der Sha'tariStiefel der AuchenaiStiefel der SpionagemeisterinStofftreter von ShattrathIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10096] = {title = "Rettung der Sporloks", objective = "Tötet 10 Marschengräber und 10 Marschenlauerer und kehrt dann zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen zurück.", description = "Ikeyen hat mir erzählt, was ihm in diesen Höhlen widerfahren ist, und ich finde es einfach nur schrecklich!\n\nWisst Ihr, vielleicht sollten wir diesen armen Sporloks helfen. Ikeyen sagt, dass sie dort in der Funggorhöhle leben, aber die Marschenbestien sind kürzlich dort eingefallen.\n\nWarum geht Ihr nicht dort hin und schaut, dass Ihr ein paar von diesen Marschenbestien erlegt? Die Höhle ist ganz nah im Südwesten.", progress = nil, completion = "Gut! Diese Marschenbiester haben kein Recht, das Zuhause der Sporloks zu überfallen!\n\nEs wäre besser, wenn diese Tiere lernen würden, in Harmonie zu leben, aber wenn das nicht geht, müssen wir uns eben um die Situation kümmern!\n\nHier, bitte nehmt etwas hiervon als Dank für Eure Hilfe.", rewards = "Tapferer Helm des ZirkelsBeutegamaschen der ExpeditionHemd der WiedergeburtKapuze des SpähersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10097] = {title = "Bruder gegen Bruder", objective = "Tötet Dunkelwirker Syth in den Sethekkhallen und befreit Lakka. Kehrt zu Isfar außerhalb der Sethekkhallen zurück, wenn Ihr die Aufgabe abgeschlossen habt.", description = "Die Sethekk haben Skettis mit Fanfaren verlassen, als Auchindoun explodiert ist. Das war sicher ein Vorbote für die Ankunft unseres Meisters.\n\nMein Bruder, Syth, war einer ihrer Anführer und hat uns gesagt, dass es unsere Pflicht wäre, in die Tempelruinen zu gehen und unserem Gott zu begegnen.\n\nNachdem wir unser Lager in den Ruinen aufgeschlagen und sie die Sethekkhallen getauft hatten, kamen mir Zweifel an den Fähigkeiten meines Bruders und seines Verbündeten Ikiss.\n\nNach einiger Zeit hat mich Syth aus den Hallen geworfen und mir verboten, meine Schwester Lakka mitzunehmen. Helft Ihr mir, sie zu retten?", progress = nil, completion = "Ich kann Euch nicht genug danken, &lt;Name&gt;. Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Wenn ich nach Skettis komme, werde ich die Todesriten für ihn vollziehen. Vielleicht kann sein Geist zur Ruhe kommen, wenn er für die Irreführung unseres Volkes gebüßt hat.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nProphetenhalsring der SethekkOrakelfokus der SethekkHalsband des KlauenlordsMal des Rabenwächters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10098] = {title = "Terokks Erbe", objective = "Bringt Terokks Maske, Terokks Federkiel und die Sage von Terokk zu Isfar außerhalb der Sethekkhallen.", description = "Mein Volk verehrt einen uralten Helden namens Terokk. Arakkoaküken erfreuen sich an den Geschichten über seine Taten und den Beschreibungen seines prächtigen Federkleids.\n\nEr lebte für hunderte von Jahren unter meinem Volk, doch eines Tages verschwand er urplötzlich, und ließ nur seine Maske, seinen Speer und seine Schriften zurück.\n\nDiese Relikte werden von den Arakkoa hoch verehrt, und es brach ihnen das Herz, als die Sethekk die Gegenstände bei ihrem Aufbruch aus Skettis verschleppten.\n\nIch habe alles, was ich über den Verbleib der Schriftrollen in den Hallen weiß, niedergeschrieben.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinen Volk zurückgebe.\n\nVielen Dank für Eure Hilfe dabei, &lt;Name&gt;. Ihr habt keine Ahnung, welch großartige Tat Ihr heute geleistet habt.", rewards = "Terokks FederkielTerokks MaskeAuf Euch wartet eine dieser Belohnungen:\n\nDie Sage von Terokk\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10099] = {title = "Das Genie", objective = "Sucht und tötet Z'kral in den Minen unter der Ehrenfeste und meldet Euch dann bei Großknecht Biggums zurück.", description = "Diese verfluchten Gan'arg wuseln immer noch in die Mine! Für jeden, den wir umbringen, scheinen zwei oder drei weitere aufzutauchen!\n\nIrgendwas in den Tiefen der Mine muss diese Menge steuern. Ihr scheint das letzte Mal ganz gut klargekommen zu sein, und das Licht weiß, dass Ihr <der/die> Einzige seid, <der/die> mutig genug ist, wieder in die Mine zu gehen. Findet heraus, wer für dieses Ärgernis verantwortlich ist und bestraft ihn dafür!", progress = "Ich traue mich fast nicht zu fragen. Euch aus der Mine herauskommen zu sehen kann nur zwei Dinge bedeuten: entweder habt Ihr diesen Bastard umgebracht oder Ihr habt keine Lust mehr. Nun, welches von beiden ist es?", completion = "Ich bin froh, dass Ihr Euch um, um... wie sagtet Ihr hieß er noch gleich? Z'kral?\n\nEurer Beschreibung nach war es wohl mehr ein es als ein er. Nun ja, was zählt ist, dass es tot ist.", rewards = "Schärpe des GroßknechtsSchwerer Gürtel des MinenarbeitersSchützer des MinenarbeitersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10101] = {title = "Wenn Geister sprechen", objective = "Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K'ure in Oshu'gun.", description = "Oshu'gun, der diamantene Berg, war einst ein heiliger Ort meines Volkes. Dort versammelten sich die Klans jedes Jahr, um das Frühlingsfest zu feiern. Dort kommunizierten unsere Schamanen mit unseren altehrwürdigen Vorfahren. Er bildete das Zentrum unserer Kultur - bis die Schatten uns übernahmen. Als die Klans zu einer Horde wurden, verstummten die Geister von Oshu'gun. Unsere Vorfahren haben sich von uns abgewendet.\n\nDoch nun werden sie in ihrer Ruhe gestört. Reist nach Oshu'gun und findet heraus, was die Geister beunruhigt.", progress = nil, completion = "&lt;Eine sanfte, melodische Stimme erklingt in Eurem Kopf.&gt;\n\nIch bin K'ure von den Naaru, &lt;Name&gt;. Ihr steht hier im Herzen meines alten Schiffs.\n\nOshu'gun, wie die Orcs es genannt haben, ist das Schiff, mit dem die Draenei zuerst auf diese Welt gekommen sind. Obwohl wir schon vor hunderten von Jahren hier vom Himmel gefallen und abgestürzt sind, sind meine Energien immer noch in diesen Trümmern gefangen. Leider bin ich der Grund für die Schmerzen der Orcgeister.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10102] = {title = "Ein gelüftetes Geheimnis", objective = "Sprecht mit A'dal in Shattrath.", description = "Als meine Energien sich über die Jahrhunderte nach und nach verflüchtigten, nahm eine Leere meinen Platz ein und verschlang die Seelen in der Nähe. Hilflos musste ich zusehen, wie ganze Generationen von Orcseelen in den Wirbel hineingezogen wurden. Vor Kurzem bemächtigten meine Feinde sich des Wirbels und benutzten ihn, um zahllose Leerdiener in ihre Brennende Legion zu rufen.\n\nNun liegt der Schlüssel zur Beendigung dieses Kreislaufs und der Befreiung der Orcgeister bei einem anderen Naaru, A'dal. Ich konnte seine Essenz in der uralten Stadt Shattrath in den Wäldern von Terokkar fühlen.", progress = nil, completion = "&lt;Ihr seid der Meinung, dass das Wesen Euch, wenn es das könnte, zunicken würde.&gt;\n\nNatürlich... Wir haben nach der Essenz eines Naaru gesucht. K'ure liegt seit Jahrhunderten im Sterben, und die Leere hat ihn schon fast ganz erfüllt. Wir haben seine Anwesenheit nicht spüren können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10103] = {title = "Bericht an Zurai", objective = "Meldet Euch bei Zurai im Sumpfrattenposten in den Zangarmarschen.", description = "Mit der Ankunft von Feldkommandeur Romus und seinen Streitmächten sind die Allianz und ihre Draeneifreunde mutiger geworden. Sie wandeln alle alten Draeneiruinen von hier bis Shattrath in Heerlager um.\n\nAls Antwort darauf haben die Trolle einen neuen Außenposten im östlichen Teil der Zangarmarschen errichtet, südlich des Todesmoors. Sie nennen ihn Sumpfrattenposten. Ich bin froh, dass sie sich in einer solchen Umgebung ihren Humor bewahrt haben. Ich wollte jedenfalls nicht mit ihnen tauschen.\n\nDer Kommandeur des Posten hat mich gebeten, ihm alle Mann zu schicken, die ich entbehren kann.", progress = nil, completion = "Um ehrlich zu sein hatte ich mehr Leute erwartet, aber Ihr müsst reichen. Willkommen im Sumpfrattenposten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10104] = {title = "Sorgen um Tuurem", objective = "Sprecht mit Andarl in Allerias Feste in den Wäldern von Terokkar.", description = "Die Gerüchte über Tuurem sind beunruhigend. Manche sagen, die Ruinen der Stadt laufen vor verrückten Zerschlagenen und Verirrten über, während gierige Artefaktjäger Draeneirelikte stehlen.\n\nEs ist schwer zu sagen, welche wahr und welche falsch sind, aber es liegt in unserer Verantwortung, die Ruinen so gut es geht zu schützen. Sucht Andarl in Allerias Feste in den Wäldern von Terokkar. Er ist eine Art Forscher für magische Relikte. Er weiß wahrscheinlich besser als alle anderen Bescheid, was dort vor sich geht.", progress = nil, completion = "Ich fühle mich geschmeichelt, dass Euer Freund von den Zerschlagenen mich für einen Gelehrten für Relikte seines Volkes hält, aber um ehrlich zu sein habe ich seit meiner Ankunft nicht viel Gelegenheit gehabt, sie zu studieren. Das war sicherlich meine Absicht, aber als ich hier ankam musste ich feststellen, dass es andere Dinge gibt, um die ich mich dringend kümmern muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10105] = {title = "Nachrichten für Rakoria", objective = "Sprecht mit Rakoria in der Steinbrecherfeste in den Wäldern von Terokkar.", description = "Jetzt, da der Sumpfrattenposten fertig ist, haben wir nicht mehr so viel Kontrolle über die Wege, die in die Marschen und aus ihnen heraus führen. Unsere Anwesenheit in den Wäldern von Terokkar ist nun viel unsicherer. Trotzdem wartet Rakoria in der Steinbrecherfeste auf Nachrichten über unsere Fortschritte hier.\n\nSie ist sehr schlau und tüchtig, <Name>, aber seid vorsichtig, wenn Ihr in ihrer Nähe seid. Sie hat viele Waren, die sie nur zu gerne auf den Weg schicken würde, aber glaubt nicht, dass sie nur unser Bestes im Sinn hat. Rakoria geht dorthin, wo sie den besten Gewinn machen kann.", progress = nil, completion = "Ich hatte gehofft, seine Leute würden den Außenposten früher fertigstellen, aber sein Geld kostet es ja schließlich nicht. Immerhin geht es voran.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10106] = {title = "Höllenfeuerbefestigungen", objective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, <Name>, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", progress = "<Name>, kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gut gemacht, &lt;Name&gt;. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", rewards = "Ihr bekommt:\n\nAbzeichen der Ehrenfeste"}
MultiLanguageQuestData['de'][10107] = {title = "Diplomatische Maßnahmen", objective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", description = "Kilrath hat Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Südosten, nahe der Grenze zu Terokkar. Viel Erfolg, <Name>!\n\nSeid auf der Hut, er ist ein Klingenmeister...", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10108] = {title = "Diplomatische Maßnahmen", objective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", description = "Die Agenten der Jägerin haben Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Osten. Viel Erfolg, <Name>!\n\nSeid auf der Hut, er ist ein Klingenmeister...", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10109] = {title = "Ich muss sie haben!", objective = "Wazdaz gegenüber der Klanwacht im Süden von Nagrand möchte, dass Ihr ihm 3 Einheiten Luftelementargas bringt.", description = "Könnt Ihr sie sehen?? Bei Gazlows wundervollem Mundgeruch, ich muss diese Eier haben! Ihr seht aus wie jemand, den man gebrauchen kann.\n\nIch sag Euch was, <Volk>, wenn Ihr ein paar Dinge für mich sammelt, damit ich meinen Spring-o-Mat 4000 zum Laufen bekomme, werde ich Euch einen Schlüssel geben, mit dem auch Ihr die Maschine bedienen könnt! Was man mit einem Spring-o-Mat 4000 machen kann? Wohl eher was man damit nicht machen kann...\n\nIch brauche Luftelementargas von den Luftelementaren in Nagrand. Sie sind überall, fragt mich also nicht, wo Ihr sie finden könnt!", progress = "Habt Ihr das Gas?", completion = "Ausgezeichnet! Nur ein paar kleine Einstellungen und dieses Ding ist so gut wie neu. Oh richtig, Euer Schlüssel! Bitte sehr.\n\nDer Spring-o-mat hat übrigens noch ein paar Macken, die ich noch reparieren muss. Äh, seid einfach vorsichtig damit.", rewards = "Ihr bekommt:\n\nSchlüssel für Spring-o-Mat 4000"}
MultiLanguageQuestData['de'][10110] = {title = "Höllenfeuerbefestigungen", objective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", progress = "Kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gute Arbeit, &lt;Name&gt;. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", rewards = "Ihr bekommt:\n\nAbzeichen von Thrallmar"}
MultiLanguageQuestData['de'][10111] = {title = "Bringt mir das Ei!", objective = "Wazdaz in Nagrand möchte, das Ihr den Spring-o-Mat 4000 benutzt, um in das Nest in dem nahe gelegenen Baum zu springen und das geheimnisvolle Ei zu stehlen.", description = "Jetzt, da Ihr initiiert wurdet, möchte ich, dass Ihr mir dieses Ei bringt! Benutzt den Spring-o-Mat und versucht, das Nest genau in der Mitte zu treffen. Aber seid vorsichtig! Schlechte Sprünge können in körperlichen Schäden oder dauerhaften schweren Wunden resultieren.", progress = "Habe ich meine Vorliebe für Eier erwähnt?", completion = "Nun, es ist kein Ei... Aber Hühnchen mag ich auch! Ich beiße mich einfach durch diese riesige Klaue durch! Danke!", rewards = "Schutz des ZauberwerfersGewebter Umhang des NomadenAparter grüner PonchoIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10112] = {title = "Ein persönlicher Gefallen", objective = "Holt 5 von Lathrais gestohlenen Waren zurück und bringt sie zu Windhändler Lathrai bei der Taverne Weltenend im Unteren Viertel in Shattrath.", description = "Hmmm? Eine Kiste sagt Ihr? Oder waren es mehrere? Wisst Ihr aus welchem Material sie war?\n\nUnd wie heißt der Händler? Empoor? Und Ihr seid Euch sicher, dass er ein Zerschlagener ist? Ich mache nicht viele Geschäfte mit ihresgleichen.\n\nVielleicht hilft es meinem Gedächtnis ein wenig auf die Sprünge, wenn Ihr mir einen Gefallen tut.\n\nDie Arakkoa der Skith - diese primitiven Zauberer - haben neulich eine große Schiffladung meiner magischen Waren gestohlen. Ich will alles zurückhaben!\n\nIhr könnt das Skithversteck südlich von Shattrath finden.", progress = "Hmm, wird mein Gedächtnis schon besser?", completion = "Ja, ich glaube, es wird alles deutlicher.\n\nUnd ich glaube, dass Euer Eifer in dieser Angelegenheit mit mehr als nur den Informationen, die Ihr sucht, belohnt werden sollte.", rewards = "Konsortiumcape der SchnelligkeitWünschelrute der ArakkoaAuf Euch wartet eine dieser Belohnungen:\n\nBand des NexuswandlersAstraler Heilungsanhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10113] = {title = "Nesingwarys Safari", objective = "\"Die Flinte\" Jones möchte, dass Ihr mit Hemet Nesingwary in Nesingwarys Safari am nordöstlichen Rand von Nagrand sprecht.", description = "\"Geht und sucht ein paar Vorräte\", hat er gesagt. Ich bin fast fünfzehn Mal getötet worden, bevor ich diesen Ort hier überhaupt gefunden habe! Diese Zerschlagenen sind vielleicht nicht das gastfreundlichste Volk, das ich kenne, aber immerhin haben sie nicht versucht, mir die Haut von den Knochen zu ziehen!\n\nWie auch immer, ich gehe nicht zurück. Meine Tage als Großwildjäger sind vorbei. Wenn ihr zufällig nach Nordosten Richtung Zangarmarschen geht und bei Nesingwarys Safari vorbeikommt, sagt dort Bescheid, dass \"die Flinte\" gekündigt hat.\n\nHey, vielleicht könnt Ihr ja meinen Platz einnehmen! Viel Glück, <Fremder/Fremde>.", progress = nil, completion = "Ich schätze, wir müssen einen Ersatz für den Wasserträger finden. Nun, Ihr seht aus wie ein kräftiger &lt;Klasse&gt;. Interesse an einem Job? Oder kommt Ihr wegen der Jagd?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10114] = {title = "Nesingwarys Safari", objective = "Ohlorn Fernreiser möchte, dass Ihr mit Shado 'Fitz' Fernreiser in Nesingwarys Safari in Nagrand sprecht.", description = "Diese Orcs haben noch nie zuvor einen Tauren gesehen, könnt Ihr das glauben? Wenn Hauptmann Kroghan nicht wäre, würden sie mich wahrscheinlich in diesem Moment zum Abendessen verschlingen!\n\nAber wo sind meine Manieren? Ich bin Ohlorn Fernreiser, herausragender Jäger! Ich gehöre zu Nesingwarys Expedition, die sich von Azeroth aus auf die Jagd nach Großwild hierher begeben hat. Wenn Ihr Euch für die Jagd interessiert, solltet Ihr meine Truppe in Nesingwarys Safari östlich von hier an den Grenzen zu den Zangarmarschen besuchen.", progress = nil, completion = "Ich bin erleichtert zu hören, dass er in Sicherheit ist. Seid Ihr hier, um an der Jagd teilzunehmen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10115] = {title = "Dolchfennkrise", objective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn.", description = "Die Kurenai und die Draenei sind nicht immer der gleichen Meinung, besonders nicht, wenn es um die Verirrten geht. Wir helfen den Verirrten, die sich an uns wenden, gerne, aber wir werden sie niemals verfolgen. Manche Draenei sind andererseits überzeugt davon, dass sie alle 'erlöst' werden müssen.\n\nEs gibt jedoch Zeiten, in denen sogar die Verirrten zu weit gehen, wie zum Beispiel der Dolchfennstamm. In ihrem Dorf im Westen hantieren sie mit Giften herum, lügen und betrügen, was für uns sehr unnatürlich ist.\n\nWir müssen dem ein Ende bereiten, bevor der bösartige Dolchfennstamm seinen Einfluss noch weiter ausbreiten kann.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Keiner ist der Meinung, dass es noch Erlösung für den Dolchfennstamm gegeben hätte, aber ich glaube nicht, dass die Draenei in dieser Situation schnell genug gehandelt hätten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10116] = {title = "Gesucht: Häuptling Mummaki", objective = "Bringt Häuptling Mummakis Totem zu Ikuti in der Oreborzuflucht.", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamms der Verirrten, wegen seiner brutalen Angriffe auf die Oreborzuflucht.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Kurenai und Draenei auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn westlich der Oreborzuflucht zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Ikuti eingefordert werden.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Bemerkenswert! Es gab schon einige vor Euch, die das Kopfgeld gewinnen wollten, aber keiner von ihnen ist je zurückgekehrt. Es ist nicht schwer sich auszumalen, was ihnen wohl zugestoßen ist.\n\nIch bin sehr erleichtert, dass wir in Zukunft nichts mehr von Mummaki und seinem Gesindel zu befürchten haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10117] = {title = "Gesucht: Häuptling Mummaki", objective = "Bringt Häuptling Mummakis Totem zu Schattenjäger Denjai.", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamm der Verirrten, wegen seiner brutalen Angriffe auf Zabra'jin und seine Einwohner.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Späher und Boten auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn nordwestlich von Zabra'jin zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Schattenjäger Denjai eingefordert werden.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Ihr habt meinen Dank, &lt;Name&gt;. Ich hatte mir schon überlegt, einen Teil der Garnison dorthin zu schicken und Mummaki selbst zu erledigen. Welche Folgen das jedoch für Zabra'jin gehabt hätte, ist schwer zu sagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10118] = {title = "Nachricht für Dolchfenn", objective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn und kehrt dann zu Schattenjäger Denjai in Zabra'jin zurück.", description = "Von allen Stämmen der Verirrten in den Zangarmarschen ist der Dolchfennstamm der gerissenste und aggressivste. Er ist sehr gut organisiert und macht keinen Hehl daraus, dass er gerne die Kontrolle über alle Verirrten in den Marschen hätte.\n\nIhren Angriffen sind schon viele meiner Späher und Boten zum Opfer gefallen. Ich kann es mir nicht leisten, noch mehr Männer zu verlieren.\n\nWenn wir nicht bald handeln, werden sie die komplette Kontrolle über alle Straßen erlangen und Zabra'jin einkesseln.", progress = nil, completion = "Ich glaube, Ihr habt ihnen eine ziemlich deutliche Botschaft zukommen lassen. Vielleicht haben meine Männer nun nicht mehr so viel Angst vor dem Dolchfennstamm. Oder sie schämen sich zumindest für ihren Mangel an Mut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10119] = {title = "Durch das Dunkle Portal", objective = "Reist durch das Dunkle Portal und sucht Kommandant Duron. Er wartet auf der anderen Seite auf Eure Ankunft - in der Scherbenwelt.", description = "Zwanzig Jahre lang war es ruhig um das Dunkle Portal – es wurde zu einem Symbol längst vergangener Zeiten.\n\n<Reldorn sieht sich um.>\n\nIch habe nicht geglaubt, dass ich den heutigen Tag erleben würde, aber hier stehen wir nun und schauen tief in den Abgrund.\n\nAuf der anderen Seite des Portals sind wir in einem grausamen Krieg gefangen – ein Krieg, den wir nicht ohne Hilfe gewinnen können. Ihr müsst durch das Dunkle Portal reisen und unseren Truppen helfen, <Klasse>.\n\nMeldet Euch umgehend bei Kommandant Duron. Er erwartet Euch in der Scherbenwelt...", progress = nil, completion = "Willkommen in der Scherbenwelt, &lt;Name&gt; -- willkommen im Alptraum! Auch wenn das erste Expeditionskorps es unbeschadet hierher geschafft hat, versucht die Legion nun, das Portal zurückzuerobern und unsere Verstärkung daran zu hindern, es zu durchschreiten.\n\nIch würde Euch gerne hier einsetzen, aber unsere Truppen und die Soldaten der Horde können die Kolonnen der Legion, die diese Plattform erobern wollen, selbst zurückhalten.\n\nIhr müsst dorthin gehen, wo Ihr am meisten gebraucht werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10120] = {title = "Ankunft in der Scherbenwelt", objective = "Generalleutnant Orion beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Orions Bericht zu Vlagga Freyfeder bringt.", description = "Mit der Unterstützung der Allianz können meine Leute die Verteidigung hier aufrechterhalten, aber Ihr müsst dringend meinen Bericht zu General Krakork in Thrallmar bringen. Mit seiner Hilfe können wir diese Dämonen zurück in den Abgrund drängen, aus dem sie gekommen sind! Sprecht mit Vlagga Freyfeder auf der Anhöhe hinter uns. Sie wird Euch schnell auf den Weg dorthin bringen.", progress = "Ich habe gesehen, wie Ihr mit Orion gesprochen habt - es muss eine wichtige Angelegenheit sein...", completion = "Ihr seid also Orions neuer Bote? Ich hoffe, es ergeht Euch besser als dem letzten, den er geschickt hat, &lt;Klasse&gt;. Mit der vorrückenden Legion schafft Ihr es niemals zu Fuß nach Thrallmar. Sagt Bescheid und mein treuer Flügeldrache wird Euch sicher dorthin bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10121] = {title = "Die Brennende Legion ausrotten", objective = "Sprecht mit Unteroffizier Schädelbrecher bei der Versorgungskarawane außerhalb von Thrallmar im Osten.", description = "Auch wenn dieses Land voller neuer, unbekannter Feinde ist, ist die Brennende Legion immer noch die größte Bedrohung für unsere Expedition. Einer meiner vertrauenswürdigsten Krieger, Unteroffizier Schädelbrecher, hat die Taktiken der Legion untersucht und versucht, das wahre Ziel der Legion in diesem Land herauszufinden. Ihr findet ihn bei der Versorgungskarawane außerhalb des südlichen Walls.\n\nUnd <Name>, hütet Euch vor der Legion. Ihre Bösartigkeit darf nicht unterschätzt werden.", progress = nil, completion = "Ihr habt sicher auf Eurem Flug vom Dunklen Portal die Krieger der Legion überall in der Landschaft gesehen. Auch wenn wir sie in der Schlacht am Berg Hyjal vor etwa 5 Jahren besiegt haben, haben diese verfluchten Dämonen immer noch nicht genug. Wenn sie auf eine Herausforderung aus sind, wird die Horde ihnen entsprechend antworten!\n\nWir Orcs haben mit der Legion mehr als nur eine Rechnung zu begleichen! Was ist mit Euch, &lt;Name&gt;? Soll ich Euch von unserem Feind erzählen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10122] = {title = "Die Erstreckung der Zitadelle", objective = "Durchsucht das nördlichste Lager entlang des Südlichen Bollwerks nach einer Spur von Gefreiter Imarion.Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Späher, Gefreiter Imarion, losgeschickt, um ihre Vorgehensweise zu erkunden, aber er ist noch nicht mit seinem Bericht zurückgekehrt.\n\nImarion sollte sich auf das nördlichste Lager entlang des Südlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet ihn, <Name>. Ohne seinen Bericht sitzen wir hier hilflos herum.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Späher, Gefreiter Imarion, losgeschickt, um ihre Vorgehensweise zu erkunden, aber er ist noch nicht mit seinem Bericht zurückgekehrt.\n\nImarion sollte sich auf das nördlichste Lager entlang des Südlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet ihn, <Name>. Ohne seinen Bericht sitzen wir hier hilflos herum.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10123] = {title = "Teufelsfunkenklamm", objective = "Unteroffizier Schädelbrecher bei der Versorgungskarawane östlich von Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords in der Teufelsfunkenklamm östlich von hier postiert. Sie sind für diese höllischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", progress = nil, completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", rewards = "FurorschlächterGellender DolchStab der ZwillingsweltenAgamaggans KielFeindesmarterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10124] = {title = "Vorposten: Häschersturz", objective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.", description = "Eure Fähigkeiten in der Schlacht sind dem Oberkommando aufgefallen, <Klasse>. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der herstehenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!", progress = nil, completion = "Ihr habt also die Teufelsfunkenklamm aufgeräumt, was? Gut zu hören - wir brauchen Soldaten wie Euch, die sich kopfüber in die Schlacht stürzen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlagge setzen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10125] = {title = "Mission: Die Kommunikation unterbrechen", objective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr To'archs Sprengstoff benutzt, um den Sender der Legion: Bosheit, Sender der Legion: Zorn, Sender der Legion: Hass und Sender der Legion: Furcht zu zerstören.", description = "Direkt im Osten liegt die Front der Legion. Die Front dient der Brennenden Legion als mobile Kommandobasis. Ihr könnt die Sender der Legion aus der Erde herausragen sehen. Mit ihrer Hilfe kommuniziert die Legion mit ihren Konstruktionslagern in der ganzen Scherbenwelt. Sie dienen ebenfalls als Schutzeinrichtung zur Verschlüsselung sämtlicher Übertragungen, sodass eine magische Überwachung nicht mehr möglich ist.\n\nIch möchte, dass Ihr diesen Sprengstoff nehmt und die Sender damit zerstört. Zerstört sie alle, <Name>! Sie sind von Süden nach Norden an der Grenze der Front der Legion aufgereiht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10127] = {title = "Mission: Das Band zerreißen", objective = "Vorpostenkommandant To'arch am Häschersturz auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi'aziv tötet.", description = "Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, östlich von dieser Basis, zu vernichten.\n\nBeide Seiten der Front sind nach dem selben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.\n\nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10129] = {title = "Mission: Tore Murketh und Shaadraz", objective = "Sprecht mit Schwadronskommandant Brack, bombardiert Tor Murketh und Tor Shaadrez und kehrt dann zu Vorpostenkommandant To'arch im Häschersturz zurück.", description = "Wir haben die beiden Haupttransporter, mit denen die Brennende Legion ihre Verstärkung herbeiholt, ausgemacht: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie beide in Stücke sprengt!\n\nHier sind die Bomben, die Ihr dafür benötigt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht mit Schwadronskommandant Brack - er wird Euch einen Wyvern zur Verfügung stellen.", progress = "Wenn Ihr beim ersten Versuch verfehlt, startet einen neuen...", completion = "Das wird sie um Wochen zurückwerfen! Fantastische Arbeit, &lt;Name&gt;. Die Legion hätte sicher nie mit so starkem Widerstand gerechnet.", rewards = "Harnisch des tobenden GeistsHelm der unendlichen VisionenKampfvernarbte GamaschenBrustplatte des ProtektoratsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10130] = {title = "Die westliche Flanke", objective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Leutnant Amadi im westlichen Wachturm der Ehrenfeste.", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um die Ehrenfeste in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Die Ehrenfeste kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10132] = {title = "Eine kolossale Bedrohung", objective = "Tötet 5 tobende Kolosse und kehrt dann zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", description = "Seht Ihr diesen riesigen roten Kristall im Norden? Er ist vor Kurzem vom Himmel gefallen und hat dabei ein großes Erdbeben ausgelöst.\n\nAls wir hierher kamen, um den Grund für den Aufruhr zu erforschen, haben wir all die Kolosse hier gesehen, die zuvor noch nicht da waren.\n\nEs ist eindeutig etwas faul an dem Kristall und den Energien, die er ausstrahlt, aber ich habe keine Zeit dafür. Ich muss mich zuerst um diese Bergriesen kümmern.\n\nIch möchte, dass Ihr zum Himmelssturzgrat geht und Euch um sie kümmert.", progress = nil, completion = "Gute Arbeit.\n\nWenn Ihr mich fragt, müssen wir einfach genug von diesen Kolossen töten, dann brauchen wir uns nicht mehr um diese merkwürdigen Kristall in der Mitte kümmern.\n\nHier, nehmt eines hiervon als Belohnung der Expedition des Cenarius.", rewards = "ExpeditionsrepetierarmbrustZauberstab des ÜberlebenskünstlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10134] = {title = "Hinweise des purpurnen Kristalls", objective = "Bringt den Purpurkristallsplitter zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel.", description = "Als der Koloss Eurem Angriff zum Opfer fällt, bemerkt Ihr, dass er ein rotes Kristallfragment in der Hand hält.\n\nIn der Hand des Riesen schien es sehr klein und unauffällig, aber für Euch ist das Stück sehr schwer zu tragen. Es sieht sehr verdächtig nach einem Stück des riesigen roten Kristalls in der Mitte des Grats aus.\n\nDies ist ganz sicher ein Hinweis auf die merkwürdigen Dinge, die hier geschehen. Ihr seid Euch sicher, dass die Druiden beim Posten des Cenarius im Süden den Splitter sehen wollen.", progress = "Das ist ein ganz schön großer Kristall, den Ihr da habt. Habt Ihr ihn von den Kolossen im Grat?\n\nLasst mich ihn anschauen.", completion = "Hm, für mich sieht es einfach wie ein großer Klumpen ungeschliffenen Kristalls aus.\n\nZugegeben, ich fühle eine kranke, böse Aura, die von ihm ausgeht, aber das ist nicht gerade mein Spezialgebiet. Ich bin nur hier, um die Bedrohung durch die Bergriesen aufzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10136] = {title = "Grausame Pläne", objective = "Tötet Arazzius den Grausamen und kehrt danach zu Nazgrel in Thrallmar zurück.", description = "Magister Blutfalke hat endlich den Schriftwechsel der Legion, den Ihr gefunden habt, entziffert. Wie es aussieht, handelt es sich dabei um Angriffspläne, die von einem Leutnant des Hochlords Kazzak geschickt wurden - Arazzius der Grausame. Offensichtlich hat Arazzius den Befehl über die Bodentruppen auf der Höllenfeuerhalbinsel. Es ist an der Zeit, dass wir seinen Befehl beenden, <Name>. Vernichtet ihn mit größter Vorsicht.\n\nBegebt Euch zu den Teichen von Aggonar und setzt dem so genannten 'Legionslord' ein Ende. Heute fordert die Horde die Höllenfeuerhalbinsel zurück. Die Legion möge verdammt sein.", progress = nil, completion = "Alle kommenden Generation werden diesen Tag bejubeln, &lt;Name&gt;. Sie werden von Eurem Heldenmut singen. Ich wünschte, Thrall wäre hier, um diesen Sieg mit uns zu feiern. Die Legion liegt am Boden, und die Höllenfeuerhalbinsel gehört wieder der Horde! Vielleicht besteht doch noch Hoffnung für diese verwüstete Welt und unser Volk auf ihr.\n\nLok'tar ogar!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVergeltung der IllidariMesserfausts BreiteKöniglicher Wachschutz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10140] = {title = "Reise zur Ehrenfeste", objective = "Fliegt zur Ehrenfeste und übergebt Marschall IsildorDurons Bericht.", description = "Wenn Ihr bereit seid, werde ich Euch einen Flug direkt zur Ehrenfeste besorgen.\n\nSprecht dort mit Marschall Isildor und gebt ihm Durons Bericht. Er wird sich freuen, einen weiteren Rekrut aus der Heimat zu sehen, und ich bin mir sicher, dass die Informationen in diesem Bericht sehr wichtig sind!", progress = "Dem Licht sei Dank, dass Ihr heil hier angekommen seid. Die Ehrenfeste benötigt alle erfahrenen Krieger, die sie bekommen kann.", completion = "Unsere Expedition zu dieser verlassenen, zerschlagenen Welt wäre fast zum Stillstand gekommen, &lt;Name&gt;. Wir haben mehr Widerstand erfahren, als wir dachten.\n\nAls ob die Brennende Legion nicht schon schlimm genug wäre, gibt es in diesen Ländern Schrecken, die wir noch nie zuvor gesehen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10141] = {title = "Wiedergeburt der Brennenden Legion", objective = "Sprecht mit Unteroffizier Altumus bei der Östlichen Versorgungskarawane außerhalb der Ehrenfeste im Osten.", description = "Als die Brennende Legion in Azeroth eingefallen ist, war sie hier in der Scherbenwelt nicht untätig. Wir haben ihre Bewegungen über die Jahre verfolgt, aber ihre letzte Tat, <Klasse>, ist schlimmer als alles, was wir je gesehen haben.\n\nSprecht mit Unteroffizier Altumus in der Nähe der Östlichen Versorgungskarawane. Er hat die Eindringlinge beobachtet und weiß vielleicht mehr über ihre Pläne.\n\nSeid schnell und passt auf, <Name> - die Brennende Legion darf auf keinen Fall unterschätzt werden.", progress = nil, completion = "Truppenkommandant Danath hat meine Anfrage nach Verstärkung wohl etwas falsch verstanden. Ihr seht zwar fähig aus, aber... ich habe um ein komplettes Bataillon gebeten!\n\nWisst Ihr, wir haben da ein kleines Dämonenproblem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10142] = {title = "Der Pfad der Pein", objective = "Unteroffizier Altumus bei der Östlichen Versorgungskarawane östlich der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords am Pfad der Pein östlich von hier postiert. Sie sind für diese teuflischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", progress = "Die Ehrenfeste ist sicher, solange die Bogenschützen unsere Himmel schützen.", completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", rewards = "FurorschlächterGellender DolchStab der ZwillingsweltenAgamaggans KielFeindesmarterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10143] = {title = "Expeditionsposten", objective = "Meldet euch bei Vorpostenkommandant Königstein im Expeditionsposten.", description = "Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, <Klasse>. Sie wollen Euch an die Front zu Rohamus' Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 400 Schritte nach Osten, durch das Tal der Knochen, bis Ihr auf einen zerstörten Teufelshäscher stoßt. Ihr findet den Expeditionsposten dort, wo einst ein Lager der Legion war. Wenn Ihr angekommen seid, meldet Euch bei Vorpostenkommandant Königstein.\n\nUnd jetzt weggetreten!", progress = nil, completion = "Schön, Euch kennenzulernen, Soldat.\n\nGenug gequatscht... nun hört zu - Ich habe eine wichtige Mission für Euch und ich möchte, dass Ihr sie erfüllt... und überlebt!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlagge setzen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10144] = {title = "Die Verstärkung abschneiden", objective = "Besiegt die Feinde um Portal Grimh und Portal Kaalez herum, um dämonische Runensteine zu sammeln.\n\nBenutzt Königsteins Zünder in Portal Grimh und Portal Kaalez.\n\nKehrt danach mit dem Zünder zu Vorpostenkommandant Königstein zurück.", description = "Direkt im Nordosten liegt die Front der Legion. Entlang der Front befinden sich die infernalen Portale, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören, <Name>!\n\nNehmt diesen Zünder. Er wurde in Area 52 hergestellt und benutzt die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Grimh und Portal Kaalez und haltet nach dämonischen Runensteinen Ausschau. Wenn Ihr genug Steine beisammen habt, benutzt den Zünder, um die Steine in den Portalen zu sprengen... und dann genießt das Feuerwerk!\n\nGeht, <Name>, und kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Ich wünschte, ich hätte die Feuer sehen können. Dieser Sprengstoff hat mächtig Dampf!", completion = "Gut gemacht, &lt;Name&gt;. Die Zerstörung der Portale wird den Nachschub an Verstärkung für die Legion für eine Weile bremsen!\n\nAber noch können wir uns nicht ausruhen...", rewards = "Reisehut der SchattenkrempeArkanberingte TunikaFeuervernarbte BrustplatteSchinderhautgamaschenGroßhelm des EindringlingsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10145] = {title = "Mission: Sever the Tie UNUSED", objective = "Vorpostenkommandant Wa'ppun beim Expeditionsposten auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Yalqiz tötet.", description = "Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, östlich von dieser Basis, zu vernichten.\n\nBeide Seiten der Front sind nach dem selben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.\n\nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10146] = {title = "Mission: Tor Murketh und Tor Shaadraz", objective = "Sprecht mit Schwadronskommandant Dabir'ee, bombardiert Tor Murketh und Tor Shaadraz und kehrt dann zu Vorpostenkommandant Wa'ppun am Expeditionsposten zurück.", description = "Westlich des Dunklen Portals befinden sich zwei riesige Transporter: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie in Stücke sprengt!\n\nHier sind die Bomben, die Ihr benutzen sollt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht nun mit Schwadronskommandant Dabir'ee - er wird Euch einen Greifen zur Verfügung stellen und Euch losschicken.", progress = "Dies ist ein wichtiger Auftrag, <Name>. Ich würde ihn nicht an irgendjemanden vergeben.", completion = "Das wird sie um Wochen zurückwerfen, kein Zweifel! Ihr habt mir gerade ungewöhnlich gute Laune verschafft, &lt;Name&gt;!", rewards = "Harnisch des tobenden GeistsHelm der unendlichen VisionenKampfvernarbte GamaschenBrustplatte des ProtektoratsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10150] = {title = "Die Erstreckung der Zitadelle", objective = "Durchsucht das nördlichste Lager entlang des Nördlichen Bollwerks nach einer Spur von Späherin Makha.Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Spurenleser, Späherin Makha, losgeschickt, um ihre Vorgehensweise zu erkunden, aber sie ist noch nicht mit ihrem Bericht zurückgekehrt.\n\nMakha sollte sich auf das nördlichste Lager entlang des Nördlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet sie, <Name>. Ohne ihren Bericht sitzen wir hier hilflos herum.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Spurenleser, Späherin Makha, losgeschickt, um ihre Vorgehensweise zu erkunden, aber sie ist noch nicht mit ihrem Bericht zurückgekehrt.\n\nMakha sollte sich auf das nördlichste Lager entlang des Nördlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet sie, <Name>. Ohne ihren Bericht sitzen wir hier hilflos herum.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10152] = {title = "Die westliche Flanke", objective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth'Gor.", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um Thrallmar in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Thrallmar kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10159] = {title = "Haltet den Dornnebelhügel sauber!", objective = "Tötet 8 Dornenfangfelshetzer und 8 Dornenfanggiftspucker und kehrt dann zu Mahuram Starkhuf im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", description = "Wir kämpfen schon die ganze Zeit, um den Pass durch den Dornnebelhügel von den Verheerern freizuhalten. Es wäre schlecht, wenn wir ganz von der Zuflucht in den Zangarmarschen abgeschnitten wären.\n\nWir möchten die Tiere nicht vertreiben, aber wir haben kaum einen andere Wahl, sie werden Reisenden in dieser Gegend gegenüber immer aggressiver.\n\nLöscht ein paar von den Felshetzern aus, wenn Ihr könnt.", progress = "Wie läuft es mit der Bereinigung des Dornnebelhügels?", completion = "Jetzt, da die Verheerer fort sind, können die Reisenden der Zuflucht des Cenarius in den Zangarmarschen wieder sicher vorankommen.\n\nDie Expedition des Cenarius ist Euch etwas schuldig, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10160] = {title = "Den Feind kennen", objective = "Sprecht mit Leutnant Amadi im alten Wachturm im Westen der Ehrenfeste.", description = "Es gibt Gerüchte, dass eine neue Brut von Orcs aufkommt. Größer, bösartiger und listiger als die Rüpel, mit denen wir uns sonst herumschlagen müssen. Wenn diese Gerüchte wahr sind, müssen unsere Streitkräfte, die ohnehin schon überansprucht sind, sich bis über ihre Grenzen hinaus belasten.\n\nIch habe meinen Leutnant, Amadi, damit betraut, die Sache zu untersuchen. Wenn Ihr uns in dieser dunklen Stunde beistehen wollt, dann meldet Euch bei ihr. Sie befindet sich in dem zerbrochenen Turm im Westen der Feste.\n\nUnd <Name>, seid vorsichtig da draußen. Ihr stürzt Euch in eine neue, gefährliche Welt.", progress = nil, completion = "&lt;Leutnant Amadi nickt.&gt;\n\nGut, wir können jede Hilfe gebrauchen. Die zunehmende Orcbevölkerung am südlichen Bollwerk bereitet mir Kopfschmerzen. Ich habe einen Späher losgeschickt, um sie zu erkunden, aber er ist noch nicht zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10161] = {title = "Im Notfall...", objective = "Sammelt 30 Zeppelintrümmer und bringt sie zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle.", description = "Bei einem Notfall ist es die Aufgabe des Piloten, einen kühlen Kopf zu bewahren, besonders, wenn die einzigen Befehle, die der Kopilot befolgt, die seines Magens sind.\n\nDie gute Nachricht ist, dass wir nicht tagelang darauf warten müssen, dass uns Ersatzteile geliefert werden. Die schlechte Nachricht ist, dass die Ersatzteile überall von hier bis zum Tal der Knochen im Osten verstreut sind.\n\nDie andere schlechte Nachricht? Die Ersatzteile sind nicht so leicht ersetzbar. Sie, äh, sind bei unserem schnellen Abgang abgefallen. Könntet Ihr mir vielleicht helfen, genügend davon wieder vom Boden aufzusammeln?", progress = "Habt Ihr genügend Teile gefunden? Wenn nicht muss ich die Bratpfanne verwenden, mit der Legassi die ganze Zeit herumwedelt. Dann muss ich den Zeppelin in die \"Fliegende Bratpfanne\" umbenennen.", completion = "Einige davon sind in einem ziemlich schlechten Zustand, aber ich sollte damit zurechtkommen. Es braucht nur ein wenig kreative Ingenieurskunst und es wird sicher klappen!", rewards = "Flintlockes PilotenhoseAerodynamische SchuppenwesteLenkbarer AbsturzhelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10162] = {title = "Mission: Die Abyssische Untiefe", objective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet.", description = "Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?\n\nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Wyvern und zerstört das verdammte Ding!\n\nHier sind die Bomben. Sprecht mit Schwadronskommandant Brack wenn Ihr zum Abflug bereit seid.", progress = "Zeigt Ihnen, dass nicht einmal die Himmel sicher sind!", completion = "Ihr fliegt, als hättet Ihr Euer Leben lang nichts anderes getan, &lt;Name&gt;. Hervorragende Vorstellung! Und nicht einmal ein kleiner Kratzer an den Flügeldrachenzerstörern!", rewards = "Flüsternde TunikaArkanberingte SchienbeinschützerSchienbeinschützer des HimmelsfeuersSchädelkappe des VeteranenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10163] = {title = "Mission: Die Abyssische Untiefe", objective = "Schwadronskommandant Greifgar im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet.", description = "Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?\n\nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Greifen und zerstört das verdammte Ding!\n\nHier sind Eure Bomben. Sprecht mit Greifnerin Heulwind wenn Ihr zum Abflug bereit seid.", progress = "Zeigt Ihnen, dass nicht einmal die Himmel sicher sind!", completion = "Ihr fliegt, als hättet Ihr Euer Leben lang nichts anderes getan, &lt;Name&gt;. Hervorragende Vorstellung! Und nicht einmal ein kleiner Kratzer an den Greifenzerstörern!", rewards = "Flüsternde TunikaArkanberingte SchienbeinschützerSchienbeinschützer des HimmelsfeuersSchädelkappe des VeteranenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10164] = {title = "Alles wird gut", objective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.", description = "Ihr habt ein ganz schönes Abenteuer hinter Euch, <Name>. Und das noch bevor Ihr überhaupt einen Fuß in den Auchenaikrypta gesetzt habt.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden oder Teil eines der bösartigen Experimente in der Nekromantie von Exarch Maladaar. Während Levixus durch Eure Hand gestorben ist, lebt Maladaar immer noch weiter und quält die Geister in der Krypta.\n\nWorum ich Euch bitte ist ganz einfach. Geht in die Auchenaikrypta und tötet Exarch Maladaar, damit die gefangenen Geister endlich Frieden finden können.", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Die Geister sind frei!\n\nAuch wenn ich keinen weltlichen Körper habe, kann ich Euch trotzdem mit Gegenständen aus der Geisterwelt belohnen. Benutzt sie mit Vorsicht, da diese Gegenstände oft unberechenbar sind und Ihrem Träger großen Schaden zufügen können.", rewards = "Schutz des ExarchenFährtenleserhalsberge der AuchenaiMönchstunika der AuchenaiAnachoretenrobe der AuchenaiIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10165] = {title = "Die Konkurrenz untergraben", objective = "Nexusprinz Haramad außerhalb der Managruft möchte, dass Ihr Nexusprinz Shaffar tötet und ihm Shaffars Bandagen bringt.", description = "Dieser Shaffar ist ganz schön gerissen, das muss man ihm lassen... Er hat es geschafft, das Konsortium fern zu halten, während er in aller Seelenruhe diese Gruft all ihrer Schätze beraubt. Ich glaube nicht, dass diese Dummköpfe es tatsächlich schaffen, durch seine Verteidigung zu brechen, deshalb mache ich Euch einen Vorschlag, <Volk>.\n\nDringt in die Managruft ein und tötet den Nexusprinzen Shaffar. Bringt mir seine Körperbandagen als Beweis Eurer Tat, und ich werde Euch fürstlich belohnen.", progress = "Ich teile nicht gerne.", completion = "Und wieder ein Konkurrent weniger... Ihr leistet gute Arbeit für ein Wesen aus Fleisch und Blut, &lt;Volk&gt;. Sucht mich auf, wenn Ihr je im Nethersturm sein solltet. Ich wohne auf der Sturmsäule.", rewards = "Plattenbeinschützer des KonsortiumsHaramads Gamaschen der dritten MünzeHaramads gekettelte PantalonsHaramads BeinwickelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10166] = {title = "Weißborkes Erinnerung", objective = "Larianna Flusswind möchte, dass Ihr Weißborkes Anhänger beim Runenstein im versengten Hain vergrabt.", description = "Dieser Anhänger bringt Erinnerungen an eine andere Zeit zurück. Eine bessere Zeit.\n\nLeider sind Erinnerungen das Letzte, was ich jetzt gebrauchen kann.\n\nIch möchte, dass Ihr dies beim Runenstein im Versengten Hain vergrabt. Dort habe ich den Treantältesten zum ersten Mal getroffen. Bettet die Erinnerung an meinen alten Freund in Frieden.", progress = "Ihr seid zurück, <Name>. Habt Ihr denn noch nicht genug getan?", completion = "Ich gehöre dieser Welt nicht länger an und muss mich geschlagen geben. Das Land hat sich auf ewig verändert, und nichts wird mehr sein wie früher.\n\nLasst den Anhänger hier bei mir, &lt;Name&gt;. Eines Tages vielleicht, wenn die Elfen schon lange nicht mehr sind, wird ein Baum an genau diesem Ort wachsen - in einem versengten Wald und zwischen toten Treants.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10167] = {title = "Auchindoun...", objective = "Reist zur Auchenaikrypta in der Knochenwüste der Wälder von Terokkar und tötet Exarch Maladaar um den Geist von D'ore zu befreien.", description = "Tief in der Auchenaikrypta befindet sich ein Grab: ein Grab, dass keinesgleichen in den Zerschlagenen Weiten findet. Aus diesem Grab, dem ersten Grab, wurde das riesige Mausoleum von Auchindoun geboren.\n\nIhr müsst zu der Auchenaikrypta reisen und dieses Grab finden. Tötet den Grabwächter und befreit den Geist, der darin gefangen ist. Der Geist ist der Schlüssel...", progress = nil, completion = "Die Erinnerung ist sehr lebendig, &lt;Name&gt;. Meine Energien wurden bei dem Aufprall vollkommen ausgelaugt. Ich war nichts als ein kleiner Fleck von Leerenergien, als Prophet Velen und seine Draeneifreunde meine Überreste geborgen und hierher gebracht haben. Nach einer Zeremonie wurde meine geschwächte Form hier in diesem Sarkophag zur Ruhe gebettet. Ich habe mich nun für fast tausend Jahre regeneriert. Der Kreis ist fast geschlossen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10168] = {title = "Was die Seele sieht", objective = "Sucht einen Seelenspiegel in der Auchenaikrypta und benutzt ihn, um einen getrübten Geist eines uralten Orcahnen von Nagrand zu rufen. Zerstört 15 getrübte Geister, damit die Ahnen in Frieden ruhen können.\n\nKehrt zu Mutter Kashur im Ahnengrund zurück, wenn Ihr fertig seid.", description = "Seit mehreren Jahrhunderten verbinden sich die Geister von Auchindoun nun mit meiner getrübten Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf meinen geschwächten Zustand zurückzuführen.\n\nUnglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der Naaru - ohne die Leere kann das Licht nicht existieren.\n\nEure einzige Möglichkeit besteht darin, die Geister von Nagrand zu vernichten, bevor sie sich in Wesen der Leere verwandeln. Benutzt die Seelenspiegel, die sich überall in der Krypta befinden, um sie zu befreien...", progress = "<Mutter Kashur ist sichtlich aufgebracht.>\n\nDiese Naaru sind weiser als alle Lebewesen in dieser Welt.", completion = "Ihr habt eine lange und gefährliche Reise hinter Euch und Leben und Gesundheit für die Sicherheit der Mag'har und den Frieden unserer Ahnen aufs Spiel gesetzt. Ich bin Euch dafür dankbarer, als tausend Worte sagen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10169] = {title = "In Würde verlieren", objective = "Magister Falris in Shattrath möchte, dass Ihr die Phiole mit Beruhigungsserum zur Terrasse des Lichts bringt und sie in den Kochtopf von Haronems Regiment schüttet.", description = "Die Aldor haben sich heute das Wohlwollen der Sha'tar verdient. Als ob das etwas Überraschendes wäre!\n\nSchaut nur, wie sie nur ein paar Fuß von A'dal entfernt mit ihrer tollen Beinarbeit angeben. Könnten sie sich wohl noch mehr bemühen, sich bei den Naaru einzuschmeicheln?\n\nHerold Haronems Schützen sind so engagiert, dass sie sogar ihren eigenen Kochtopf mitbringen, um keine langen Pausen zum Mittagessen machen müssen. Das kann nicht ohne Strafe vonstatten gehen, <Name>.\n\nIch möchte, dass Ihr diese Phiole in ihr Essen kippt. Die Folgen sollten... sehr amüsant sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10170] = {title = "Rückkehr zur Großmutter", objective = "Kehrt nach Garadar zurück und sprecht mit Großmutter Geyah.", description = "Kehrt zu Großmutter Geyah in Garadar zurück und berichtet ihr von Eurem Sieg, <Name>. Das wird den Mag'har sicher neuen Mut geben. Vielleicht erwacht sogar der junge Höllschrei aus seiner Melancholie.", progress = nil, completion = "Ich möchte, dass Ihr diese Nachrichten persönlich zu Garrosh bringt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10171] = {title = "Der untröstliche Häuptling", objective = "Großmutter Geyah in Garadar möchte, dass Ihr mit Garrosh sprecht.", description = "Ihr habt so viel für die Mag'har getan, <Name>. Alle wissen von Euren Taten, auch Garrosh. Geht nun zu ihm und erzählt ihm von eurem letzten Erfolg. Sagt ihm, was Ihr für ihn und sein Volk getan habt. Eure Worte werden ihn sicher trösten.", progress = nil, completion = "Alle sind stolz. Stolz dass unser Volk einen weiteren Winter überleben wird. Aber danach? Was ist danach?\n\nVielleicht solltet Ihr diesen Klan anführen, &lt;Name&gt;. Vielleicht ist es mir dann vergönnt zu sterben, wenn die Großmutter dahinscheidet. Vergönnt, die Schande meines Familiennamens auszulöschen. Ich sehne mich nach diesem Frieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10172] = {title = "Es gibt keine Hoffnung", objective = "Sprecht mit Großmutter Geyah und erzählt ihr, was Garrosh Euch gesagt hat.", description = "Ihr seid <ein ehrenwerter/eine ehrenwerte:r> <Volk>, <Name>. Ihr habt viel für die Mag'har getan. Niemand könnte Eure Dienste für mein Volk je leugnen. Dennoch ist die Zeit der Mag'har abgelaufen. Ihr habt mir mehr als alles andere gezeigt, dass ich nicht in der Lage bin, diese Leute anzuführen. Zu stark ist der Fluch meines Blutes. Ich werde nicht... ich kann nicht der nächste Höllschrei sein, der die Orcs in die Verdammnis führt.\n\nBitte, <Name>, kehrt zur Großmutter zurück und erklärt ihr, was ich Euch gesagt habe. Ich schäme mich zu sehr, um zu ihr zu gehen... ihr in die Augen zu schauen.", progress = nil, completion = "&lt;Tränen strömen über Großmutter Geyahs Gesicht.&gt;\n\nGeht zu Eurem Kriegshäuptling. Sagt ihm, dass ich ihn hier erwarte...", rewards = "Ritualistenhörner der Mag'hariSpähertunika der Mag'hariJägergamaschen der Mag'hariMag'harische Beinplatten des KriegsherrenIhr bekommt:\n\nHeldeninsigne der Mag'hari"}
MultiLanguageQuestData['de'][10173] = {title = "Der Stab des Erzmagiers", objective = "Besorgt Erzmagier Vargoths Stab von Ekkorash der Inquisitorin und bringt ihn zu Ravandwyr in Area 52. Um Ekkorash aus ihrem Versteck hervorzulocken, streut das Beschwörungspulver auf die Kohlenpfanne in der Mitte der Ruinen.", description = "Erlaubt, dass ich mich vorstelle, <Klasse>.\n\nMein Name ist Ravandwyr, Lehrling des Erzmagiers Vargoth.\n\nMein Meister ist... nennen wir es indisponiert. Ich bin hier in einer Angelegenheit von höchster Wichtigkeit.\n\nDie Ruinen von Arklon südöstlich der Stadt sind eine Brutstätte für die Aktivitäten der Brennenden Legion. Was sie mit den Ruinen vorhaben interessiert weder mich noch meinen Meister. Aber ihre Anführerin, Ekkorash, hat den Stab meines Meisters.\n\nMit diesem Beschwörungspulver könnt Ihr die Dämonin aus ihrem Versteck locken. Streut es über die Kohlenpfanne in der Mitte der Ruinen.", progress = "Ich werde nicht ruhen, bis Erzmagier Vargoth seinen Stab zurück hat. Konntet Ihr ihn den Klauen des Dämonen entreißen?", completion = "Ah, Ihr habt es also geschafft den Stab zurückzuholen. Beeindruckend, &lt;Name&gt;. Vielleicht seid Ihr genau der &lt;Klasse&gt;, den ich suche.\n\nOh ja, Eure Belohnung...\n\n\n\nIhr habt sicherlich mehr erwartet, aber das kommt schon noch mit der Zeit. Fürs Erste soll die Möglichkeit Eure Belohnung sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10174] = {title = "Der Fluch des Violetten Turms", objective = "Benutzt Erzmagier Vargoths Stab um Kontakt mit Erzmagier Vargoth aufzunehmen.\n\nFalls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz.\n\nBereitgestellter Gegenstand: \n", description = "Jetzt könnt Ihr mithilfe des Stabs Kontakt zu dem Erzmagier aufnehmen.\n\nEr lebt im Violetten Turm, auf einer Insel im Süden. Der verfluchte Turm ist sowohl eine Zuflucht als auch ein Gefängnis für ihn. Mitglieder und Verbündete der Kirin Tor können weder hinein noch hinaus, weswegen ich meinen Meister nicht sehen kann.\n\nDer Stab kann die Verteidigung des Turms durchbrechen, jedoch nur, wenn er von jemandem, der nicht zu den Kirin Tor gehört, aktiviert wird.\n\nNehmt den Stab und benutzt ihn, um ein Abbild des Erzmagiers zu erschaffen. Sagt ihm, was passiert ist und beweist ihm, dass ich ihn nicht ganz enttäuscht habe.", progress = nil, completion = "&lt;Erzmagier Vargoth betrachtet Euch, als Ihr ihm Ravandwyrs Nachricht übermittelt.&gt;\n\nRavandwyr hat alles, was ein Meister sich von einem Lehrling wünschen kann. Als ich ihm den Stab gab und ihm befohlen habe, zu fliehen, habe ich gehofft, dass er ihn benutzen würde, um jemanden zu finden, der mich nach dem Abzug von Kael'thas Truppen aus dem Turm befreien kann. Seitdem habe ich viel über den Fluch herausgefunden.\n\nEr kann gebrochen werden, aber dazu brauche ich Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10175] = {title = "Thrall, Sohn Durotans", objective = "Reist nach Orgrimmar und überbringt Thrall Geyahs Nachricht.", description = "Kehrt in Eure Welt zurück, <Name>. Sucht meinen Enkelsohn und sagt ihm, dass sein Blut hier ist - in dieser zerschlagenen Welt.\n\nSagt ihm, dass das Erbe seines Vaters weiterlebt.\n\nSagt ihm alles...", progress = nil, completion = "&lt;Thralls Stimme wird dumpf wie ein fernes Donnergrollen.&gt;\n\nIch... Ich habe eine Großmutter? Sie ist am Leben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10176] = {title = "Ar'kelos der Wächter", objective = "Betretet den Violetten Turm in der Mitte von Kirin'Var und besiegt Ar'kelos. Sprecht danach mit Erzmagier Vargoth.", description = "Jetzt, da Ihr alle Gegenstände, die ich benötige, um Kael'thas Fluch zu brechen, gesammelt habt, gibt es nur noch Eines zu tun. Als Kael'thas den Turm versiegelt hat, hat er einen arkanen Golem, der als Ar'kelos bekannt ist, auf dem Grund des Turms platziert.\n\nIhr müsst Ar'kelos besiegen, damit ich innerhalb des Turms wieder meine Magie wirken kann.\n\nWenn Ihr den Violetten Turm betretet, wird der Fluch Euch treffen.\n\nSobald Ihr Ar'kelos besiegt habt, steigt den Turm hinauf und unterstützt mich bei den Vorbereitungen für das Ritual.", progress = "Endlich treffen wir uns.", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ohne das Dämpferfeld wird es viel leichter für mich, die Magie vorzubereiten, mit der ich den Fluch des Turms endlich aufheben kann.", rewards = "Umhang des tapferen VerteidigersSzepter der VerjüngungAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger des KampfmagiersKern von Ar'kelos\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10177] = {title = "Ärger in Auchindoun", objective = "Meldet Euch bei Feldkommandeur Mahfuun beim Eingang zum Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", progress = nil, completion = "Es wird langsam Zeit, dass Ihr kommt.\n\nMehlisah hat schon vor Tagen gesagt, dass sie Hilfe schicken würde. Und wir kämpfen hier schließlich schon eine ganze Weile!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10178] = {title = "Findet Spion To'gun", objective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", description = "To'gun, dieser Narr! Wir können hier kaum die Angriffe zurückhalten und er geht wieder hinein um Informationen zu sammeln und die anderen Spione zu retten!\n\nIch weiß nicht, ob ich ihn umarmen oder töten soll!\n\nDer Schattenrat muss uns mithilfe von Magie ausfindig gemacht haben, denn all unsere Spionen mussten hastig von dort fliehen. Die meisten von uns haben es nicht geschafft.\n\nBitte, wenn Ihr mutig genug seid, um das Schattenlabyrinth zu betreten, könntet Ihr dann nach To'gun Ausschau halten? Er ist schon eine ganze Weile fort, und ich befürchte das Schlimmste.", progress = nil, completion = "Was? Grik'tha hat Euch nach mir geschickt?\n\nIch weiß nicht, ob ich mich geehrt fühlen oder sie eine Närrin schimpfen soll!\n\nKönntet Ihr mir vielleicht aus diesem Käfig raushelfen? Es ist ein bisschen eng hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10179] = {title = "Der Hüter von Kirin'Var", objective = "Sprecht mit Hüter Dierwert in Kirin'Var im Nethersturm.Als klar wurde, dass unsere Expedition ohne Hoffnung auf Rückkehr nach Azeroth in der Scherbenwelt gefangen war, reisten die Kirin Tor zu den Ebenen von Farahlon und erbauten Kirin'Var. Ich habe die Verwaltung des Dorfs Hüter Dierwert übertragen, aber als Kael'thas und seine Streitkräfte mich hier im Violetten Turm einsperrten, ist mein Kontakt zu ihm abgebrochen.\n\nSucht ihn in Kirin'Var und helft ihm, wo Ihr nur könnt, <Name>. Ich bin sicher, dass er seit dem Angriff alle Hände voll zu tun hat.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Als klar wurde, dass unsere Expedition ohne Hoffnung auf Rückkehr nach Azeroth in der Scherbenwelt gefangen war, reisten die Kirin Tor zu den Ebenen von Farahlon und erbauten Kirin'Var. Ich habe die Verwaltung des Dorfs Hüter Dierwert übertragen, aber als Kael'thas und seine Streitkräfte mich hier im Violetten Turm einsperrten, ist mein Kontakt zu ihm abgebrochen.\n\nSucht ihn in Kirin'Var und helft ihm, wo Ihr nur könnt, <Name>. Ich bin sicher, dass er seit dem Angriff alle Hände voll zu tun hat.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10180] = {title = "Kann es einfach nicht lassen", objective = "Sprecht mit Isfar in den Sethekkhallen in Auchindoun.", description = "Ich habe versucht, Isfar davon zu überzeugen, hier in den sicheren Mauern von Shattrath zu bleiben, aber er wollte nicht auf mich hören. Stattdessen hat er sich entschlossen, wieder auf eigene Faust nach Auchindoun zu gehen.\n\nEr hatte zwar das Glück, den Sethekkhallen einmal zu entkommen, aber wenn sie ihn erwischen wird es kein zweites Mal geben.\n\nIch bewundere seine Entschlossenheit, seine Schwester zu befreien, aber ohne Hilfe wird er es nicht schaffen.\n\nFindet Isfar und sprecht mit ihm, <Name>. Wenn Ihr ihn nicht davon überzeugen könnt, zurückzukommen, könntet Ihr ihm dann vielleicht helfen Lakka zu retten?", progress = nil, completion = "Ich hätte wissen sollen, dass er nach mir schicken würde. Er hat versucht mir auszureden, in die Sethekkhallen zurückzukehren, aber ich könnte nicht damit leben, wenn Lakka etwas zustoßen würde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10182] = {title = "Kampfmagier Dathric", objective = "Sucht die Wohnung von Kampfmagier Dathric in der Zaubergasse und bringt die Klinge zurück in sein Waffenregal. Sprecht danach mit Hüter Dierwert in Kirin'Var.", description = "Das Schwert ist von außergewöhnlicher Qualität, fein geschmiedet und perfekt für einen Kampfmagier ausbalanciert. Auf dem Knauf der Waffe sind das Siegel der Kirin Tor und der Name \"Dathric\" eingraviert.\n\nWährend Ihr die Waffe in den Händen hin und her dreht, bemerkt Ihr, dass etwas mit dem Schwert nicht stimmt. Es fühlt sich an, als wäre es zwischen zwei Welten hin- und hergerissen. Könnte dies der Gegenstand sein, der Kampfmagier Dathrics Geist an diese Welt bindet?\n\nVielleicht zerbricht das Band, wenn Ihr es an seinen angestammten Platz zurückbringt, und befreit Dathrics Geist endgültig.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich kann keine Rastlosigkeit mehr in Dathrics Geist spüren. Ich würde viel dafür geben, wenn ich noch einmal mit ihm sprechen könnte, aber es ist schon gut genug, dass er nun in Frieden ruht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10183] = {title = "Auf nach Area 52", objective = "Bringt die Notizen des Netheorologen zu Raketenchef Doppeldecker in Area 52 im Nethersturm.", description = "Ich studiere hier draußen den Nether - die astralen Strömungen und so weiter. Dies ist ein idealer Platz, weit weg von den Lichtern und dem Getöse der Stadt. Wenn ich diesen Schrott doch nur am Laufen halten könnte!\n\nHey, wisst Ihr, wenn Ihr nach Arbeit sucht, solltet Ihr nach Area 52 gehen! Das liegt gleich den Pfad hoch und bei der Weggabelung rechts.\n\nWarum bringt Ihr nicht einfach meine neusten Forschungsnotizen zu Raketenchef Doppeldecker? Ich bin sicher, er hat genug Arbeit für Euch, wegen des Raketenschiffs X-52 und so.", progress = "Stress, Stress. Keine Zeit verschwenden! Es gibt ein Raketenschiff, das gebaut werden will!\n\nWas wollt Ihr?", completion = "Oh, Kupfernickel hat sich also endlich entschlossen, seine Entdeckungen zu berichten, was? Faule Wissenschaftler!\n\nWas ist das?\n\n&lt;Der Chef blättert ein paar Mal durch die Notizen mit einem deutlich skeptischen Gesichtsausdruck.&gt;\n\nEr sagt, dass die gewaltigen Netherenergien, die durch den Nethersturm fließen, alles in nur ein paar Monaten in Stücke reißen werden.\n\nDas ist ungünstig - jetzt müssen wir den Zeitplan für das Raketenschiff etwas straffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10184] = {title = "Bösartige Überbleibsel", objective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr 20 abtrünnige Geister auf dem Ratsplatz tötet.", description = "Die meisten Geister im Dorf sind nicht mehr als blasse Überbleibsel der Magier der Kirin Tor, die sie einst waren. Sie erinnern sich nicht mehr an ihr früheres Ich und streunen blind vor Wut um die Ruinen herum.\n\nDas war jedoch nicht immer so. Direkt nach dem Angriff waren die Geister zwar rastlos, aber nicht bösartig. Mit der Zeit sind sie jedoch immer aggressiver geworden. Ich traue mich nicht, in den südlichen Teil des Dorfs zu gehen, denn sie machen nicht einmal vor mir Halt. Beruhigt sie und lasst uns hoffen, dass Ihr Ärger dann verfliegt.", progress = nil, completion = "&lt;Hüter Dierwert schüttelt langsam den Kopf.&gt;\n\nSie haben das nicht verdient, aber es ist das Beste, was wir tun können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10185] = {title = "Schlimmer als der Tod", objective = "Tötet 10 Magiertöter und 10 Manasucher und kehrt zu Hüter Dierwert in Kirin'Var zurück.", description = "Nachdem die Blutelfen Kirin'Var dem Erdboden gleichgemacht hatten, haben sie mit dem Bau eines großen Gebäudes im Nordwesten begonnen. Ohne die Kräfte des Erzmagiers können wir nicht genau sagen, was dort vor sich geht.\n\nEines ist jedoch klar. Die Anwesenheit der Blutelfen hat eine Flut von gefräßigen Manaelementaren entfesselt. Sie scheinen von den Ruinen der Zaubergasse angelockt zu werden und verursachen noch weitere Zerstörung... Wir können das nicht weiter zulassen.", progress = nil, completion = "&lt;Der Hüter sieht bestürzt aus.&gt;\n\nIch kann die nächste Welle schon über den Horizont kommen sehen. Sie auszumerzen hilft vielleicht für den Moment, aber wir brauchen langfristige Maßnahmen.", rewards = "Mantelung des GeisterbindersManadurchdrungene HandgelenksschützerStulpen des SpiritualistenFarahlitbesetzte StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10186] = {title = "Ihr seid eingestellt!", objective = "Sammelt 10 Astrallithiummatrixkristalle und kehrt dann zu Raketenchef Doppeldecker in Area 52 im Nethersturm zurück.", description = "Lasst mich der Erste sein, der Euch an Bord willkommen heißt, Juniortechniker dritten Grades <Name>!\n\nWir bauen hier draußen mein Meisterwerk - die X-52 Netherrakete!\n\nDoch zuerst müssen wir alle Teile und den Treibstoff für sie besorgen. Und da kommt Ihr ins Spiel.\n\nZuerst brauche ich Kristalle, VIELE Kristalle, für die astrallithische Antriebsmatrix. Die Draenei hatten so viele, dass sie ihnen schon zu den Ohren herauswuchsen!\n\nBegebt Euch also zu den Ruinen von Enkaat und sammelt ein paar für mich! Und kümmert Euch nicht um die Draeneigeister.", progress = "Sieht es etwa aus, als wäre die X-52 Netherrakete bereit zum Abflug? Durchquere ich den wirbelnden Nether im meinen bequemen Kommandostuhl? Entdecke ich fremde neue Welten? Suche nach neuen Technologien und Geschäftsgelegenheiten? Dringe in Galaxien vor, die nie ein Goblin zuvor gesehen hat?\n\nNein!\n\nAlso hoffe ich, dass Ihr die Kristalle habt, nach denen ich Euch geschickt habe.", completion = "Pah! Die sehen aber grob aus. Vielleicht können wir sie in einer tertiären Antriebsmehrfachkammer einsetzen?\n\nTrotzdem gute Arbeit, Juniortechniker dritten Grades! Ihr werdet es sicher bald zum zweiten Grad schaffen.", rewards = "Schultern des Juniortechnikers dritten GradesHandschuhe des Juniortechnikers dritten GradesArmschienen des Juniortechnikers dritten GradesSchutzbrille des Juniortechnikers dritten GradesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10187] = {title = "Eine Nachricht für den Erzmagier", objective = "Sprecht mit Erzmagier Vargoth im Violetten Turm im Nethersturm.Auch wenn es hier sehr ungemütlich ist, muntert es uns ein wenig auf, dass der Erzmagier die Misere des Dorfs nicht vergessen hat.\n\n<Der Hüter schaut zum Turm hinauf.>\n\nEs ist lächerlich, oder? Manchmal scheint es, als trenne uns nur eine Wand aus einfachem Stein. Wie leicht vergisst man die Wand aus Magie.\n\nWenn Ihr so nett wärt, erklimmt den Turm und sagt Erzmagier Vargoth, dass wir Fortschritte im Dorf machen und bald einen Weg finden werden, um die Manakreaturen fernzuhalten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Auch wenn es hier sehr ungemütlich ist, muntert es uns ein wenig auf, dass der Erzmagier die Misere des Dorfs nicht vergessen hat.\n\n<Der Hüter schaut zum Turm hinauf.>\n\nEs ist lächerlich, oder? Manchmal scheint es, als trenne uns nur eine Wand aus einfachem Stein. Wie leicht vergisst man die Wand aus Magie.\n\nWenn Ihr so nett wärt, erklimmt den Turm und sagt Erzmagier Vargoth, dass wir Fortschritte im Dorf machen und bald einen Weg finden werden, um die Manakreaturen fernzuhalten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10188] = {title = "Das Siegel von Krasus", objective = "Holt Euch das Siegel von Krasus von Zauberbinderin Maryana in der Manaschmiede Coruu, nordwestlich vom Violetten Turm.", description = "Bevor wir uns vor so vielen Jahren von Azeroth aus aufmachten, haben die Kirin Tor unserer Expedition ein mächtiges Artefakt anvertraut, das Siegel von Krasus. Es hat uns im Kampf gegen die Orcs große Dienste erwiesen und könnte eine wichtige Rolle beim Brechen des Zaubers, der mich gefangen hält, spielen.\n\nAls Kael'thas mich jedoch meiner Besitztümer beraubt hat, gab er das Siegel an Zauberbinderin Maryana, die mit der Garnison zurückblieb. Hätte er gewusst, was er in seinem Besitz hatte, hätte er es nicht so einfach weggegeben.", progress = "Wenn ich vom Fluch des Turmes frei sein will, muss ich das Siegel haben.", completion = "Ah, es ist so wundervoll, wie ich es in Erinnerung hatte. Könnt Ihr die Macht, die davon ausgeht, spüren?\n\nNatürlich ist noch viel mehr zu tun, aber Ihr habt meinen tiefsten Dank dafür, dass Ihr mir das Siegel zurückgebracht habt.", rewards = "Gesellengürtel von Kirin'VarSpähergürtel von Kirin'VarHelm des KampfmagiersVerteidigerbeinlinge von Kirin'VarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10189] = {title = "Manaschmiede B'naar", objective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr zum Rand der Manaschmiede B'naar geht und die Stammrolle von B'naar von Hauptmann Arathyn besorgt.\n\nDas Abschließen von Aufgaben für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Vielleicht sind Euch Kaels Manaschmieden auf dem Weg hierher aufgefallen. Das sind diese großen violetten Gebäude, die Energie aus dem Himmel saugen.\n\nWir wurden von den Sha'tar hierher geschickt, um sie zu erkunden. Ihr könnt uns dabei helfen, indem Ihr eine Stammrolle von dort besorgt. Wenn wir eine Vorstellung davon hätten, wer dort als was arbeitet, wäre uns über alle Maßen geholfen.\n\nWir glauben, dass Hauptmann Arathyn, der eine Ballistentruppe direkt außerhalb der Manaschmiede B'naar leitet, eine solche Rolle besitzen könnte. Holt sie für uns.", progress = "Habt Ihr bekommen, worum ich Euch gebeten habe, <Name>?", completion = "Ausgezeichnet! Mit dieser Stammrolle können wir bessere Entscheidungen treffen, wenn wir die Anhänger Kaels bei den Manaschmieden angreifen.\n\nEigentlich schade, ich mochte es irgendwie, seine Lakaien wahllos zu töten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10190] = {title = "Batterien aufladen", objective = "Benutzt den Batterieladeblaster bei genügend Phasenjägern, um den Batterieladestatus auf 10 zu bringen. Bringt die Batterie danach zu Bot-Spezialistin Alley in den Ruinen von Enkaat im Nethersturm zurück.", description = "Ich habe die wichtige Aufgabe, die Maschinerie in diesen Ruinen zu sammeln, aber ich habe ein paar Probleme damit, alle meine Bots am Laufen zu halten.\n\nDie Phasenjäger - diese wurmähnlichen Dinger - stecken voller Energie! Man kann sie überall finden, wie sie aus dem Nether herausströmen.\n\nFüllt die Batterie mit diesem Ladeblaster, indem Ihr ihn bei einem Phasenjäger benutzt, wenn er sehr schwach ist, und ihm dann die restliche Energie entzieht.", progress = "Habt Ihr die Batterie schon aufgeladen?", completion = "He, passt auf, auf wen Ihr mit dem Ding zeigt! Ihr habt es auf \"töten\" gestellt!!!\n\nGut, es sieht so aus, als hättet Ihr die Batterie genügend aufgeladen. Ich baue sie gleich in Nr. V ein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10191] = {title = "Nummer V lebt!", objective = "Begleitet Maxx E. Million Nr. V durch die Ruinen von Enkaat und wieder in Sicherheit. Sprecht dann mit Bot-Spezialistin Alley außerhalb der Ruinen von Enkaat im Nethersturm.", description = "Grüße, <Volk>. Ich bin aufgeladen und voll einsatzfähig!\n\nIn den Ruinen gibt es ein paar zerbrechliche Draeneimaschinen, die ich wieder beschaffen muss. Ich habe sehr edle Servos in den Stellgliedern meiner Handgelenke und bin mit den neusten verbrennungspneumatischen Beulensaugern ausgestattet. Die Maschinen mit der nötigen Sorgfalt zu behandeln ist also kein Problem für mich.\n\nLeider werden die Geister, die in den Ruinen spuken, mich sehr wahrscheinlich angreifen, daher brauche ich Euch und Eure Freunde als Beschützer.", progress = "So schnell schon zurück?\n\nIst mit Maxx E. Million Nr. V alles in Ordnung?!", completion = "Ihr habt es geschafft! Ihr habt es geschafft! Ich könnte Euch küssen!\n\nOh verdammt... der Maxx E. Million Nr. V hat schon wieder keine Batterie mehr. Naja, er hat seine Arbeit erledigt, und das ist das Wichtigste.\n\nRaketenchef Doppeldecker wird sich freuen, wenn er diese Draeneimaschinen in der X-52 Netherrakete einbauen kann! Das bedeutet eine Beförderung für mich! Ich bin so glücklich, ich muss Euch einfach belohnen!\n\nHier, sucht Euch etwas davon aus.", rewards = "Alleys DoppelbogenAusgegrabener Zauberstab von EnkaatIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10192] = {title = "Krasus' Kompendium", objective = "Holt Euch Krasus' Kompendium - Kapitel 1, Krasus' Kompendium - Kapitel 2 und Krasus' Kompendium - Kapitel 3 vom Ratsplatz von Kirin'Var.", description = "Die Kirin Tor haben unserer Expedition einen weiteren Gegenstand aus Krasus' Besitz mitgegeben. Es handelt sich dabei um sein Zauberbuch, das Krasus' Kompendium genannt wird. Da es alle Zauber enthält, die Krasus beherrschte, war es uns eine unersetzliche Hilfe im Krieg.\n\nBevor Kael'thas und seine Truppen Kirin'Var besetzt haben, wurde mir das Buch von einem rebellischen Schüler, der begierig darauf war, die Nekromantie zu erlernen, gestohlen. Der Lehrling und seine Anhänger haben sich aufgeteilt und das Buch heimlich studiert, wobei sie sich in ihren Häusern im Süden der Stadt eingeschlossen haben.", progress = "Habt Ihr das Buch besorgt, <Name>?", completion = "&lt;Das Abbild von Erzmagier Vargoth scheint das Kompendium zu begutachten.&gt;\n\nEs ist ein wenig mitgenommen, aber wenn man bedenkt, was es durchmachen musste, ist es ein Wunder, dass es überhaupt überlebt hat. Bewahrt es auf, &lt;Name&gt;. Ohne das Buch haben wir kaum eine Chance, den Schutzschild des Turms zu durchbrechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10193] = {title = "Hochrangige Ziele", objective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr in die Manaschmiede B'naar geht und 2 Warpmeister des Sonnenzorns, 6 Warpingenieure des Sonnenzorns und 8 Geologen des Sonnenzorns tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Von den Informationen aus der Stammrolle wissen wir nun, dass die geistigen Führer der Manaschmieden die Warpmeister und Warpingenieure sind. Sie überwachen die Gewinnung der so genannten \"Warpenergie\" in den Manaschmieden und kümmern sich um ihre Lieferung an entfernte Orte über ein unterirdisches Rohrsystem.\n\nDie einzigen weiteren Spezialisten in dieser Gegend sind die Geologen. Alle anderen sind entweder Teil des Militärs oder Magister - beide sehr leicht zu ersetzen.\n\nGeht dort hinein und tötet Kaels Spezialisten. Das wird ihn am meisten treffen.", progress = nil, completion = "Ich seid ein zuverlässiger Bursche. &lt;Name&gt;. Wenn es etwas gibt, das ich noch mehr mag, als Kaels Schoßhunde zu töten, dann ist es, wenn das jemand anderes für mich erledigt.\n\nSo habe ich weniger Blut auf meinen Klamotten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10194] = {title = "Heimlicher Flug", objective = "Sprecht mit Veronia außerhalb von Area 52 und fliegt zur Manaschmiede Coruu.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Während Ihr weg wart, haben meine Männer eine weitere Manaschmiede entdeckt. Sie befindet sich östlich von hier und ist als Manaschmiede Coruu bekannt.\n\nZwei meiner besten Spione haben einen geheimen Landeplatz außerhalb der Manaschmiede eingerichtet. Ihr sollt ihnen helfen, Kaels Truppen zu unterwandern und so viele Informationen wie möglich zu sammeln.\n\nSprecht mit Veronia außerhalb der Stadtmauer. Sie hat einen Windreiter vorbereitet, der Euch zur Manaschmiede Coruu bringen wird. Wenn Ihr dort seid, meldet Euch bei Caledis Morgenhell. Er wird Euch mit Eurer Mission vertraut machen.", progress = nil, completion = "Euren Flug zu organisieren war nicht gerade billig. Ich hoffe, ihr habt das Zeug zu diesem Auftrag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10196] = {title = "Mehr Arakkoafedern", objective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", description = "Ich habe erste Erfolge darin, die Arakkoageister näher zu mir zu locken, aber sie sind immer noch sehr schüchtern. Vielleicht trauen sie sich näher, wenn ich meine Verkleidung verbessere.\n\nDazu benötige ich jedoch mehr Arakkoafedern wie die, die Ihr mir bereits gebracht habt. Wenn Ihr noch ein paar Federn bekommen könntet, würde ich sie Euch gerne abnehmen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArakkoajagdvorräte"}
MultiLanguageQuestData['de'][10197] = {title = "Eine überzeugende Verkleidung", objective = "Bringt ein Set Arkanistenroben des Sonnenzorns, ein Paar Forscherhandschuhe des Sonnenzorns und ein Gardistenmedaillon des Sonnenzorns zu Caledis Morgenhell bei der Manaschmiede Coruu im Nethersturm.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Die Reihen von Kaels Armee zu unterwandern wird keine leichte Aufgabe. Mit meinen geringen Künsten der Illusion könnte ich einen von uns wie einen Anhänger Kaels aussehen lassen, aber es gibt einige Details in ihrer Uniform, die ich nicht nachbilden kann.\n\nBringt mir ein Set ihrer Roben, ein Paar ihrer Handschuhe und ein Gardistenmedaillon des Sonnenzorns. Das wird die Ergebnisse meiner Magie überzeugender machen. Sie tragen alle das gleiche, also solltet Ihr keine Probleme haben, diese Gegenstände zu finden.", progress = "Habt Ihr die Kleidungsstücke, um die ich Euch gebeten habe?", completion = "Ausgezeichnet! Wenn ich mit Euch fertig bin, werdet Ihr Euch unbemerkt unter die Ränge des Sonnenzorns mischen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10198] = {title = "Informationen sammeln", objective = "Benutzt die Sonnenzornverkleidung, geht in die Manaschmiede Coruu und belauscht das Gespräch zwischen Sonnenzornkommandant Morgenschmied und Arkanist Ardonis.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Ich habe aus den Teilen, die Ihr mir besorgt habt, eine Uniform hergestellt. Sie ist magisch verbessert, um die Illusion perfekt zu machen.\n\nWir haben beobachtet, wie Kommandant Morgenschmied vor ein paar Minuten hineingegangen ist, um Arkanist Ardonis zu treffen. Er hatte sein gesamtes Gefolge an Wachen bei sich, daher ist das, was sie zu besprechen haben, sicher von größter Wichtigkeit. Versucht, etwas darüber herauszufinden.\n\nAch, das hätte ich fast vergessen. Haltet Euch von den arkanen Golems fern, die in der Manaschmiede patrouillieren. Sie werden Eure Illusion mühelos durchschauen.", progress = "Wir geht es mit der Bespitzelung voran, <Name>? Ihr solltet Euch lieber beeilen. Ich werde hier schon ganz kribbelig.", completion = "Die Manaschmiede Duro ist in Schwierigkeiten? Ich bin mir sicher, dass Thalodien sich über diese Neuigkeiten freuen wird. Lasst uns zunächst diese Aufgabe hier fertigstellen.", rewards = "Gürtel des WeisenMorgenhellarmschienenSchienbeinschützer der BlutwacheArmbrust des SpionagemeistersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10199] = {title = "Der kleine Extrakick", objective = "Besorgt 5 Netherrochenstachel und bringt sie zu Stiefels in Area 52 im Nethersturm.", description = "So, nun fehlt mir noch die eine Zutat, die meinem Gebräu den entscheidenden kleinen Kick geben sollte, den wir brauchen.\n\nDer Stich der Netherrochen, die sich in der Nähe der Schieferhautschinder herumtreiben, ist ganz schön heftig. Bringt mir ein paar ihrer Stachel, damit ich das Gift aus ihnen gewinnen kann.\n\nIch bin mir sicher, dass die Ergebnisse explosiv sind!", progress = "Wenn ich das Gift von genügend vielen Netherrochenstacheln extrahieren kann, bekommen wir vielleicht den explosivsten Kraftstoff, der gemischt wurde!", completion = "Wow! Ok, jetzt stimmt die Sache.\n\nLasst mich nur schnell die Boshaftigkeit aus diesen kleinen Schönheiten quetschen. Das sollte ein Raketentreibstoff werden, der alle von den Socken haut!\n\nHier, lasst mich das Schieferöl und das Stachelgift mischen, und dann schauen wir mal, was passiert...", rewards = "Schulterstücke der AbendruhMixologenhandschuheDoks GürtelStiefels' StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10200] = {title = "Rückkehr zu Thalodien", objective = "Kehrt zu Spionagemeister Thalodien in Area 52 im Nethersturm zurück.", description = "Es wäre besser, wenn diese Information so schnell wie möglich zu Thalodien gelangen würde. Ich bleibe hier und verwische unsere Spuren.\n\nEs wäre alles andere als gut, wenn Kael'thas herausfinden würde, was wir hier getan haben. Geheime Informationen sind immer am besten, wenn der Feind nicht weiß, dass man sie hat.", progress = nil, completion = "Ihr überrascht mich immer wieder, &lt;Name&gt;. Das war beeindruckende Spionagearbeit, die Ihr da in der Manaschmiede Coruu geleistet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10201] = {title = "Der Moment der Wahrheit", objective = "Geht zu Grek und bittet ihn, das Öl an seiner Waffe auszuprobieren. Bringt das Ergebnis zu Rakoria, wenn er fertig ist.", description = "Das Öl ist endlich für einen ersten Test bereit. Es scheint dickflüssig genug zu sein, um als hochwertiges Waffenöl zu dienen.\n\nDer einzige Weg, dies herauszufinden ist, einen Profi zu fragen. Seht Ihr Grek da drüben bei den Fahndungsanschlägen? Ich weiß, er ist nicht gerade ein Poet, aber mit Waffen kennt sich der Orc aus!\n\nBringt ihm eine Probe des Öl und bittet ihn, es an seiner Waffe auszuprobieren. Wenn er das getan hat, berichtet mir von seiner Meinung.", progress = nil, completion = "&lt;Ihr berichtet Rakoria die Testergebnisse und sie fängt an, schallend zu lachen.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHervorragendes ManaölHervorragendes Zauberöl\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10202] = {title = "Ein Abtrünniger", objective = "Geht zur Manaschmiede Ara und sprecht mit Magister Theledorn.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Wir wurden vor Kurzem von einem Magister des Sonnenzorns kontaktiert, der uns beitreten möchte und schwört, dass er uns Informationen geben kann, die wir dringend benötigen. Wir haben uns mit unseren Informanten in Verbindung gesetzt, um zu überprüfen, ob es sich bei ihm um einen Doppelagenten handeln könnte, und er scheint sauber zu sein.\n\nEr befindet sich in der Manaschmiede Ara, was die Kommunikation etwas erschwert. Geht zu ihm und hört Euch an, was er zu sagen hat. Wenn er nur halb so hilfreich ist, wie er behauptet, können wir ihn sicher gut einsetzen.", progress = nil, completion = "Es ist an der Zeit, dass Ihr auftaucht. Ich habe mich schon gefragt, ob die Seher überhaupt interessiert sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10203] = {title = "Unschätzbare Ausrüstung beamen", objective = "Benutzt den ultrastarken Dekonsolidierungsstrahler, um den Hyperdreh-Grab-o-Matik, die servopneumatische Baggerklaue, den multispektralen Geländeabtaster und den großen Wagen voller Sprengstoff zurück nach Area 52 zu beamen. Meldet Euch dann beim leitenden Ingenieur Zischeldruck beim östlichen Ende des Risses in Area 52 im Nethersturm.", description = "Habt Ihr den Riss gesehen, der mitten durch Area 52 verläuft? Wir waren das! <Grinsen>\n\nIm Riss befinden sich allerlei Schätze für die X-52 Netherrakete! Das einzige Problem ist nur, dass wir nicht genug Ausrüstung haben.\n\nBis die Brennende Legion dort aufgetaucht ist, führten wir eine Operation in den Ruinen von Arklon aus. Ich möchte, dass Ihr diesen ultrastarken Dekonsolidierungsstrahler zu den Ruinen bringt. Benutzt ihn, um unsere Ausrüstung zum leitenden Ingenieur Zischeldruck im Riss zu beamen.\n\nJuniortechniker dritten Grades <Name>, dies ist Eure Chance auf eine Beförderung. Vergeigt sie nicht!", progress = "Ist es nicht schön hier? Und jeden Tag finden wir etwas Neues und Exotisches.\n\nWas für ein Glück, dass wir fast das Dorf zerstört haben, als wir hier gegraben haben.", completion = "Ihr müsst derjenige sein, der uns die ganze Ausrüstung von den Ruinen hergebeamt hat! Ein Hoch auf Euch!\n\nIch habe die Ausrüstung bereits an unsere Grabungsorte weiterverteilt. Jetzt können wir unsere Ausgrabungen im großen Stil überall auf der Insel durchführen! Die Netherrakete wird in null Komma nichts fertig werden!\n\nHmm, merkwürdig. Wartet mal, habt Ihr gesagt, Ihr habt uns vier Dinge zurück geschickt? Ich habe nur drei bekommen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10204] = {title = "Blutjuwelenkristalle", objective = "Magistrix Larynna möchte, dass Ihr zur Manaschmiede B'naar geht und einen Blutjuwelensplitter von einem Magister des Sonnenzorns besorgt. Benutzt den Splitter in der Nähe von größeren Blutjuwelenkristallen und kehrt zu ihr in Area 52 zurück.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Kaels Magister haben den Gebrauch von Manakristallen so weit perfektioniert, dass sie innerhalb von Sekunden große Mengen von Energie aufnehmen können.\n\nDas tun sie, indem sie kleinere Kristallsplitter von Blutjuwelen an größeren und vollen Kristallen aufladen.\n\nGeht zur Manaschmiede B'naar und besorgt einen dieser Splitter von einem Magister des Sonnenzorns und benutzt ihn, um Energie von einem größeren Kristall aufzunehmen.\n\nKehrt zu mir zurück, damit ich die Wirkung der Aura untersuchen kann. Keine Sorge, Nebenwirkungen sollten nur temporär sein.", progress = nil, completion = "Hmmm... wie ich erwartet habe.\n\nSolch rohen Energien ausgesetzt zu sein erhöht unsere angeborene Sucht nach Magie gewaltig.\n\nIch bin nicht überrascht, dass Kael mit seinen Taten ungestraft davon kommt, wenn seine Angestellten praktisch die ganze Zeit betrunken sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10205] = {title = "Sphärenräuber Nesaad", objective = "Tötet Sphärenräuber Nesaad und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück.", description = "Sphärenräuber Nesaad muss erledigt werden! Ich habe keine Ahnung, wie er meinen Angriff überleben konnte, aber er darf seine Taten dort auf keinen Fall fortführen.\n\nGeht zurück und vernichtet Nesaad. Er hat ein kleines Lager des Astraleums im südwestlichen Teil des Hügels.\n\nVersagt nicht, wie ich es tat, <Name>.", progress = "Ist es vorbei? Ist Sphärenräuber Nesaad tot?", completion = "Ich bin erleichtert zu hören, dass dieser Abschaum endlich vernichtet wurde. Ihr macht Eure Arbeit gut, &lt;Name&gt;... darf ich so vermessen sein, Euch beim Namen zu nennen?\n\nWenn Ihr möchtet, habe ich eine weitere Aufgabe für Euch. Eine, die besonders wichtig ist. Jemand mit so offensichtlichen Talenten wie Ihr wird sie sicher leicht bewältigen können.", rewards = "Armschienen der ZaxxisStiefel der ZaxxisHandschuhe der ZaxxisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10206] = {title = "Wählt Eure Rolle", objective = "Sammelt 10 Stück Astraltechnologie und bringt sie zu Papa Mauschel in Area 52 im Nethersturm.", description = "Diese astralen Hampelmänner sind genauso opportunistisch wie wir, das muss man ihnen lassen. Aber niemand, und ich meine NIEMAND, wagt sich auf das Gebiet von B.U.M.M.!\n\nDer Hügel im Süden gehört uns!\n\nWenn wir die X-52 Netherrakete fertigstellen wollen, brauchen wir alle neuen Technologien, die wir in die Finger bekommen können. Und da die Astralen von uns stehlen, ist es nur gerecht, wenn wir es ihnen mit gleicher Münze heimzahlen.\n\nWarum geht Ihr nicht zum Hügel und schaut, ob Ihr ihnen etwas von ihrer Technologie vor der Nase wegschnappen könnt.", progress = "So schnell schon zurück? Nehmt mich besser nicht auf den Arm, <Klasse>.\n\nDer Erfolg des X-52-Projekts hängt davon ab, dass wir das Zeug so schnell wie möglich bekommen!", completion = "Hehe, astrale Deppen!\n\nDanke, dass Ihr uns die Teile gebracht habt, &lt;Klasse&gt;. Ich wette, wir können diese Babys gleich in die Rakete einbauen. Ich frage mich, was sie wohl bewirken? Wird sicher lustig, es herauszufinden!\n\nHm, lasst mich mal schauen ob ich noch ein wenig Wechselgeld für Euch in der Hosentasche habe.", rewards = "Papas ArmbindenMechtechschulternAuf Euch wartet eine dieser Belohnungen:\n\nFamilienerbstück der Mauschels\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10207] = {title = "Forward Base: Reaver's Fall REUSE", objective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, <Klasse>. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der hervorragenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, <Klasse>. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der hervorragenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10208] = {title = "Die Verstärkung abschneiden", objective = "Besiegt die Feinde um Portal Xilus und Portal Kruul herum, um dämonische Runensteine zu sammeln.\n\nBenutzt To'archs Zünder in Portal Xilus und Portal Kruul.\n\nKehrt danach mit To'archs Zünder zu To'arch im Häschersturz auf der Höllenfeuerhalbinsel zurück.", description = "Direkt im Osten liegt die Front der Legion. Entlang der Front befinden sich die höllischen Portale und Tore, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören!\n\nNehmt diese Zünder. Sie wurden in Area 52 hergestellt und benutzten die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Xilus und Portal Kruul und haltet nach dämonischen Runensteinen Ausschau. Benutzt den Zünder, um die vier Steine in den Portalen zu sprengen, sobald Ihr genug Steine beisammen habt... und dann genießt das Feuerwerk! Kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Die Legion ist bestimmt nicht auf unsere Überraschung gefasst, was, <Name>?", completion = "Gut gemacht! Ich konnte die Explosionen fast bis hierher spüren!\n\nJetzt haben wir noch eine weitere Bombenmission für Euch...", rewards = "Reisehut der SchattenkrempeArkanberingte TunikaFeuervernarbte BrustplatteSchinderhautgamaschenGroßhelm des EindringlingsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10209] = {title = "Beschwörer Kanthins Preis", objective = "Besiegt Beschwörer Kanthin in der Manaschmiede Duro auf der Insel nördlich des Sonnenzornpostens und holt den Stein des Gletscharius zurück.", description = "Als nächstes müssen wir meinen Vertrauten, Gletscharius, aus den Händen des Blutelfenbeschwörers, der ihn gefangen hält, befreien. Beschwörer Kanthin war einst einer der erfahrensten Magister in der Streitmacht, die Kael'thas losgeschickt hat, um Kirin'Var auszulöschen. Es ist ganz normal, dass er meinen Vertrauten als Trophäe haben will.\n\nIch bin mir sicher, dass Kanthin, dumm wie er ist, versucht hat, Gletscharius zu seinem Diener zu machen. Ich habe herausgefunden, dass Kanthin sich jetzt in der Manaschmiede Duro aufhält, falls dies Euch etwas sagt.", progress = "Habt Ihr den Stein von Gletscharius bekommen?", completion = "&lt;Ihr wisst nicht, ob es nur eine Verzerrung ist, aber der Erzmagier scheint zu lächeln.&gt;\n\nJetzt, da ich all meine Besitztümer zurück habe, habe ich alles, um Kael'thas' Magie zu durchbrechen. Ich werde den Zauber gleich wirken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10210] = {title = "A'dal", objective = "Sprecht mit A'dal, Anführer der Sha'tar in der Mitte der Terrasse des Lichts.", description = "Willkommen in Shattrath, <Klasse>. Dies ist vielleicht der einzige Ort in der Scherbenwelt, in der Ihr so etwas wie Sicherheit empfinden könnt.\n\nEine Gruppe von Naaru, die als Sha'tar bekannt sind, hat die Dämonen von hier fortgejagt.\n\nWenn Ihr noch nie einen Naaru gesehen habt, solltet Ihr A'dal auf der Terrasse des Lichts besuchen. Der Anführer der Sha'tar ist der ehrfurchtgebietendste Anblick, den ich je gesehen habe. Ganz anders, als alles andere in diesem öden Land.", progress = nil, completion = "&lt;Das Licht, das Eure Sinne erfüllt hat, als Ihr Euch A'dal nähertet, wird noch stärker, als Ihr ihn ansprecht. Melodische Klänge ertönen in Eurem Kopf.\n\nIhr seid hier sicher.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10211] = {title = "Stadt des Lichts", objective = "Folgt Khadgars Diener und hört Euch an, was er zu erzählen hat. Kehrt nach dieser Aufgabe zu Khadgar zurück.", description = "Belästigt A'dal nicht mit Euren unbedeutenden Fragen, <Klasse>. Er ist vielleicht das mächtigste Wesen, das Ihr je zu Gesicht bekommen werdet.\n\nIhr kommt mir nicht bekannt vor. Ich nehme an, Ihr wollt etwas über die Stadt erfahren?\n\nIhr müsst schon entschuldigen, dass ich selbst keine Führungen mache, aber ich muss einige Pläne mit A'dal besprechen. Vielleicht wärt Ihr ja mit einem herbeigerufenen Diener an meiner statt zufrieden? Ausgezeichnet!", progress = "Die Geschichten der Lebewesen sind kurz, <Name>. Die Geschichten der Städte dauern Jahre.", completion = "Ich hoffe, Ihr habt etwas über Shattrath erfahren, &lt;Name&gt;. Lasst es einfach auf Euch wirken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10212] = {title = "Held der Mag'har", objective = "Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück.", description = "Ich muss erst alles in Ordnung bringen, bevor ich gehe. Kehrt zur Großmutter zurück und sagt ihr, dass ihr Enkelsohn kommt.", progress = nil, completion = "Ihr seid wirklich der Held der Mag'har, &lt;Name&gt;. Wärt Ihr nicht gewesen, wären wir sicher von den Ogern und Zerschlagenen überrannt worden.\n\nWir sind ein armes Volk, aber wir haben dennoch einige mächtige Artefakte. Bitte, ich bestehe darauf, dass Ihr Euch eines aus unserem Kasten nehmt.", rewards = "Ritualistenhörner der Mag'hariSpähertunika der Mag'hariJägergamaschen der Mag'hariMag'harische Beinplatten des KriegsherrenIhr bekommt:\n\nHeldeninsigne der Mag'hari"}
MultiLanguageQuestData['de'][10213] = {title = "Untersuchung der Absturzstelle", objective = "Durchsucht die Absturzstelle nach Überlebenden.", description = "Als ich verwundet in der Wüste lag, habe ich gesehen, wie ein goblinscher Zeppelin abgestürzt ist. Er kam im Nordwesten runter, hinter dem Expeditionsrüstlager.\n\nDer Zeppelin hat gebrannt. Schreiende, brennende Goblins fielen wie Bomben vom Himmel. Ich hatte natürlich sehr große Schmerzen und viel Blut verloren. Vielleicht habe ich mir das alles auch nur eingebildet.\n\nWenn Ihr irgendwelche Überlebenden finden solltet, bietet ihnen eine Zuflucht hier im Rückenbrecherposten an.", progress = nil, completion = "Wir wurden von der Brennenden Legion abgeschossen, obwohl wir eine Friedensflagge geschwenkt haben. Wer hätte ahnen können, dass die Brennende Legion so gemein ist?\n\nWir können leider nicht mit Euch zum Rückenbrecherposten kommen. Wir müssen den Zeppelin reparieren und dann weiterziehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10214] = {title = "Bringt diese Mine zum Beben!", objective = "Tötet 15 Pioniere der Gan'arg und kehrt dann zu Großknecht Razelcraz zurück.", description = "Die Mine wurde von diesem Gan'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.\n\nWenn wir dieses Gan'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Kupfer und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10216] = {title = "Sicherheit geht vor", objective = "Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.\n\nWenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammer und aktiviert ihn.", description = "Shaffars Astrale haben uns ganz aus der Managruft ausgeschlossen. Zum Glück habe ich einen Plan. Auch wenn wir nicht durch die Eingangstür können, bin ich mir sicher, dass es innen viele Transporter gibt.\n\nIch möchte, dass Ihr zuerst den Weg für meine Gruppe freiräumt und dann einen der Transporter aktiviert, damit wir hineinteleportieren können.\n\nAktiviert den Transporter in der Kammer genau vor Shaffars Kammern, wenn Ihr den Weg freigemacht habt. Keine Sorge, ich werde Euch dafür entlohnen...", progress = "Dieses Gerät hat über ein Dutzend Knöpfe, von denen Euch keiner bekannt vorkommt.", completion = "&lt;Ihr schließt die Augen und drückt einen Knopf.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10218] = {title = "Jemandes Arbeit zahlt sich aus", objective = "Begleitet Kryoingenieur Sha'heen sicher durch die Managruft, damit er die Astralmaterie aus Shaffars Astralsammlern entnehmen kann.\n\nMeldet Euch bei Nexusprinz Haramad außerhalb der Managruft beim Lager des Konsortiums, wenn Ihr erfolgreich wart.", description = "Wen habt Ihr erwartet?! Dieser Idiot Morphalius wurde entpriorisiert. Jetzt bin ich hier, um sein Chaos aufzuräumen. Alles, was ich von Euch will, ist, dass Ihr mir den Rücken freihaltet, während ich Shaffars Astralsammler durchgehe und ihnen alles entnehme, was sie gesammelt haben. Wenn ich meinen Auftrag erfolgreich abschließe, wird Haramad selbst Euch belohnen!\n\nWas sagt Ihr? Begleitet mich durch die Managruft und sammelt ein paar unglaubliche Schätze! Die meiste Arbeit habt Ihr ohnehin schon erledigt! Hinter uns ist nichts mehr am Leben, oder?", progress = nil, completion = "Da dies Morphalius' Idee war, habe ich ihm seinen alten Job zurückgegeben. Gut gemacht, kleines Fleischwesen. Wirklich gut!\n\nDenkt daran, wenn Ihr je auf der Suche nach Arbeit und im Nethersturm seid, sucht mich auf der Sturmsäule auf.", rewards = "Metallschienbeinschützer der FleischbestieKonsortiummantelung der PhasenKryohandschuheWickeltuch des KonsortiumprinzenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10220] = {title = "Bringt sie zum Zuhören", objective = "Mordiba möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 8 unerschütterliche Krieger und 6 unerschütterliche Zauberhexer beim Expeditionsrüstlager westlich des Rückenbrecherpostens tötet.", description = "Ich wurde hierher geschickt, Kontakt zu den unerschütterlichen Geistern herzustellen. Diese einst stolzen Soldaten der Allianz wurden vor langer Zeit besiegt, und nun spuken ihre Geister in den Ruinen im Westen.\n\nWenn sie sich uns anschließen würden, hätten wir einen mächtigen Verbündeten. Stellt Euch nur vor, eine Armee von untoten Kriegern, die sich unserem Feind entgegenstellt. Aber diese Untoten sind blind vor Hass und wollen sich meinen Vorschlag nicht anhören.\n\nVielleicht kann man sie zwingen, sich uns anzuschließen.", progress = nil, completion = "Die Unerschütterlichen haben die Macht der Horde gespürt. Vielleicht haben sie jetzt ja Lust, sich meinen Vorschlag anzuhören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10221] = {title = "Dr. Bumm!", objective = "Tötet Dr. Bumm und kehrt dann mit den guten Nachrichten zu dem leitenden Ingenieur Zischeldruck in Area 52 im Nethersturm zurück.", description = "<Name>, mein früherer Schützling, Sparky Überschub, hat sich geweigert, während seiner Arbeit hier seinen Helm zu tragen und hat sich in den berüchtigten Dr. Bumm verwandelt!\n\nEr hat sich mit einem Großteil unserer Pionierausrüstung nach Nordosten aufgemacht! Seitdem sind er und seine Bummbots eine große Bedrohung für Area 52!\n\nIch möchte, dass Ihr zu seinem Lager außerhalb der Stadt geht und ihm ein Ende macht! Benutzt diese Bummbomben um ihn auszulöschen.\n\nUnd passt auf, dass Ihr ihm oder seinen Bummbots nicht zu nahe kommt!", progress = "Habt Ihr uns vor den Verwüstungen durch Dr. Bumm gerettet? Ich verspreche Euch, dass es diesmal keine explodierenden Wagen gibt, auch wenn das wirklich spaßig war!\n\nWir sollten das wirklich öfter tun!", completion = "Ich werde Sparky immer vermissen. &lt;Schnief&gt; Aber jetzt, da wir wissen, dass Dr. Bumm uns nicht mehr tyrannisieren kann, werden wir alle besser schlafen.\n\nLasst Euch das ein Lehre sein. Kommt hier nicht ohne Netherhelm runter!\n\nNun, wie kann ich Euch dafür belohnen?", rewards = "NetherwesteNethergamaschenSparkys liegengelassener HelmNetherwachenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10222] = {title = "Die Garnison des Sonnenzornpostens", objective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr 10 Bogenschützen des Sonnenzorns tötet.", description = "Nachdem Prinz Kael'thas' Streitkräfte das Dorf zerstört und den Erzmagier im Turm eingesperrt hatten, haben sie sich zum Sonnenzornposten im Nordosten zurückgezogen. Die gleichen Männer, die unser Dorf zerstört und unsere Freunde getötet haben, stoßen nun auf ihren 'unglaublichen Sieg' an, während wir unsere Gefallenen nicht rächen können.\n\nWir dürfen diese Verbrechen nicht ungestraft lassen! Seid unser Instrument der Rache, <Name>. Geht zum Sonnenzornposten und fordert das Leben der Verantwortlichen für dieses Verbrechen ein!", progress = nil, completion = "Was Ihr getan habt, kann die Gefallenen nicht zurückbringen, aber vielleicht kann es ihre Geister beruhigen. Obwohl ehrlich gesagt kein Blut der Welt meinen Zorn über Kael'thas Taten stillen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10223] = {title = "Nieder mit Daellis", objective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr Meister Daellis Morgenschlag tötet.", description = "Den Blutelf, der den Angriff geführt hat, werde ich nie vergessen. Er trug einen Wappenrock mit einem Ding, was ich noch nie zuvor gesehen habe, über einer roten Rüstung.\n\nEr war wild und erbarmungslos, und kämpfte an der Front, wo man kaum einen anderen Blutelfenoffizier je zu Gesicht bekommt. Er war an diesem Tag für den Tod vieler Kirin Tor verantwortlich, aber er blieb nicht lange im Sonnenzornposten. Kael'thas hat ihn zur Manaschmiede Duro beordert, um bei ihrem Versuch, das Gebiet zu kontrollieren, zu helfen. Findet ihn, <Name>, und bringt seinen Bogen für immer zum Schweigen.", progress = nil, completion = "&lt;Ihr seid Euch nicht sicher, aber es sieht so aus, als würde Hüter Dierwert gleich anfangen zu weinen.&gt;\n\nEndlich ist es geschafft. Wenn ich könnte, würde ich meine Existenz selbst auslöschen, aber die Wahrheit ist, dass ich nicht loslassen kann. Für die Leute im Dorf ist es schwer, aber zumindest ehrlich. Ich schätze, das ist der Preis, den wir dafür bezahlen müssen, dass wir uns so sehr an diesen Ort gebunden haben.", rewards = "Morgenschlags UmhangHandgelenksschützer des NachtpirschersAuf Euch wartet eine dieser Belohnungen:\n\nSiegel des Violetten TurmsKraft des Violetten Turms\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10224] = {title = "Essenzen für die Motoren", objective = "Sammelt 7 Essenzen eines Managespensts und bringt sie zu Chefingenieur Trep bei Area 52 im Nethersturm.", description = "Als Chefingenieur der X-52 ist es meine Pflicht dafür zu sorgen, dass die Hauptmotoren der Netherrakete tiptop in Schuss sind.\n\nUnglücklicherweise habe ich sie noch nicht gebaut.\n\n<Klasse>, ich bin hier in einer Notlage! Ich habe fast alle Teile. Ich brauche nur noch einen Antriebskern.\n\nZum Glück bin ich der Meinung, dass wir die Essenz der Managespenster in der Nähe nutzen können, um die Motoren zu überbrücken.\n\nIhr findet die Managespenster überall bei diesen komischen leuchtenden Gräben im Norden der Insel. Außer hier in Area 52 natürlich.", progress = "Habt Ihr schon alle Essenzen?", completion = "Wow, das sind viele Essenzen!\n\nGut, schauen wir mal, was passiert, wenn ich sie mit den Astrallithiummatrixkristallen mische.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10225] = {title = "Meldung beim Chefingenieur", objective = "Bringt die Astrallithiummatrixkristalle zu Chefingenieur Trep in Area 52 im Nethersturm.", description = "<Name>! Ich möchte, dass Ihr all diese Astrallithiumkristalle zu Chefingenieur Trep, meinem, äh, Ingenieurschef bringt.\n\nEr sollte wissen, was mit ihnen zu tun ist. Und wenn er es nicht weiß, dann sorgt dafür, dass er es herausfindet.", progress = "Äh, hallo. Ich bin hier ein wenig beschäftigt. Was habt Ihr da?", completion = "Oh, Astrallithiummatrixkristalle! Ja, die klingen wichtig.\n\nLasst sie uns dort drüben hinstellen und ich kümmere mich gleich um sie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10226] = {title = "Elementarenergieextraktor", objective = "Extrahiert 5 Einheiten Elementarenergie und bringt sie zu Chefingenieur Trep in Area 52 im Nethersturm.", description = "Verdammt, das hat nicht geklappt.\n\nOk, ich habe eine andere Idee. Ich habe Xyrol einen Elementarenergieextraktor herstellen lassen. Ich weiß nicht genau, was man mit dieser Energie anfangen kann, aber ich werde schon einen Verwendungszweck für sie finden.\n\nDie zerrissenen Rumpler und Sphärenentartungen auf dem Felsvorsprung der Schwindenden Weite im Süden haben genau das, was wir für die Motoren brauchen!\n\nDer Extraktor wird ihre Energie in eine feste Form bringen, die Ihr aufsammeln könnt, nachdem Ihr sie besiegt habt.", progress = "Habt Ihr die Energie von diesen Elementaren schon? Oh, keine Hektik oder so. Hängt ja nur mein Leben und meine Karriere davon ab.", completion = "Das ist besser! Gut, ich glaube, jetzt sind wir im Geschäft.\n\nLasst mich dieses Zeug nur kurz in das Zau-ba-Ding hier tun, und ich bin sicher, dass es gleich einen voll funktionsfähigen Phasenantriebskern ausspuckt.\n\nOh, he, ich sollte Euch vielleicht dafür belohnen, dass Ihr meine Haut gerettet habt. Hehe.", rewards = "Treps SchulterschutzStrapazierfähige IngenieursstiefelIngenieurshandschuhe von Area 52Gürtel des ChefingenieursIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10227] = {title = "Ich sehe tote Draenei", objective = "Sprecht mit Ramdor dem Wahnsinnigen auf dem Knochenhaufen außerhalb der Auchenaikrypta.", description = "Ich sehe tote Draenei. Sie sind überall.\n\nPah, niemand glaubt mir, weil ich ein Kind bin. Nichtmal meine Mama glaubt mir.\n\n<Ha'lei zeigt auf Ramdor.>\n\nEr glaubt mir. Er sieht sie auch. Und er regt sich darüber auf!\n\nIrgendwie ist es lustig. Ich sehe Geister und die Leute lächeln mich nur an und tätscheln mir den Kopf, um mich zu beruhigen. Ramdor sieht Geister und sie halten ihn für verrückt. Ich hoffe echt, dass ich nie erwachsen werde!\n\nVielleicht solltet Ihr erst mit Ramdor reden, bevor Ihr da hinein geht. Er war einst ein Totenpriester.", progress = nil, completion = "Das Kind hat Recht. Ich war einst ein \"Totenpriester\".\n\n&lt;Ramdor zuckt zusammen.&gt;\n\nWas für ein abstoßender Titel. Innen findet Ihr die Überbleibsel meines Ordens. Sie sind natürlich alle verrückt! Wahnsinnig! Ich denke, ich habe mich sehr hervorgehoben, da ich der letzte von ihnen mit gesundem Menschenverstand war. Natürlich wurde ich wegen meines Glaubens exkommuniziert.\n\nWas, sagtet Ihr, glaube ich noch gleich?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10228] = {title = "Ezekiel", objective = "Sprecht mit Ezekiel von Shattrath in Shattrath.", description = "Ich bin der Meinung, dass die Toten, um die wir uns seit den letzten 500 Jahren gekümmert haben, in Ruhe gelassen werden sollten. Aber Maladaar hat andere Pläne. Er hat sich in die Krypta des Gedenkens zurückgezogen, um seine Experimente zu beginnen... Nekromantie.\n\nIch hoffe, Ihr hattet nicht vor, dorthin zu gehen... nicht bevor Ihr mir geholfen habt, diese verdammten Geister loszuwerden. Ich weiß, wo sie ihre Schätze aufbewahren, <Volk>. Jetzt habe ich Eure Aufmerksamkeit, was?\n\nBringt mir das Buch der Toten, das sich im Besitz des Aldors Ezekiel von Shattrath befindet.", progress = nil, completion = "Buch der Toten? Nie davon gehört... Worum geht es überhaupt? Wer hat Euch geschickt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10229] = {title = "Den Folianten entziffern", objective = "Bringt den geheimnisvollen Folianten zu Althen dem Historiker im Rückenbrecherposten.", description = "Dieser Foliant scheint eine Art Geschichtsbuch zu sein, das in einer Geheimschrift der Allianz geschrieben wurde. Althen der Historiker im Rückenbrecherposten hat die Unerschütterlichen eine Zeit lang studiert. Vielleicht kann er die Geheimschrift der Allianz entziffern und das Buch lesen.", progress = "Was ist das? Ein Buch von einem unerschütterlichen Geist? Wie merkwürdig. Lasst es mich anschauen, vielleicht kann ich mehr über die Geschichte der Unerschütterlichen erfahren.", completion = "Ich habe mein ganzes Unleben lang alte Geschichte studiert, doch nie zuvor etwas wie dieses Buch gesehen. Er erzählt die gesamte Geschichte des Rüstlagers, sogar die Ereignisse nach seiner Zerstörung.\n\nDie Unerschütterlichen haben ihre Geschichte aufgeschrieben, sogar nach ihrem Tod in der Schlacht. Mit diesem Buch können wir die Unerschütterlichen verstehen und sie sicher davon überzeugen, sich uns anzuschließen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10230] = {title = "Das Kampfhorn", objective = "Besorgt Euch das Kampfhorn der Unerschütterlichen von Feldkommandant Thalvos und bringt es zu Althen dem Historiker im Rückenbrecherposten.", description = "Vielleicht haben wir uns ganz falsch an diese \"Unerschütterlichen\" herangewagt.\n\nDieser Foliant sagt, dass das Expeditionsrüstlager der Allianz vor langer Zeit von den Orcs und den Todesrittern zerstört wurde. Die Unerschütterlichen wurden dort als rachedurstige Geister in einer ewigen Schlacht gegen die Klans der Höllenorcs gefangen.\n\nSie denken nur an Rache. Wir müssen ihnen die Chance geben, ihre meist verhassten Feinde zu besiegen. Kehrt noch einmal in die Ruinen des Rüstlagers zurück und sucht Feldkommandant Thalvos. Er trägt ein Kampfhorn, das die Unerschütterlichen rufen kann. Bringt es mir.", progress = "Wir müssen den Unerschütterlichen bald helfen. Wenn wir sie davon überzeugen können, sich uns anzuschließen, hat die Horde einen starken Verbündeten.", completion = "Gut gemacht, &lt;Name&gt;. Dieses alte Horn wird uns helfen, die Unerschütterlich zu rufen.\n\nNatürlich nur, wenn sie es möchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10231] = {title = "Welches Buch? Ich sehe kein Buch.", objective = "Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben.", description = "Ramdor? Hmm, mal überlegen... Ramdor... Oh ja, der Totenpriester. Was will er denn mit dem Buch? Nun, es ist gleichgültig. Ja, ich habe Euch angelogen und nein, ich habe das Buch nicht. Nicht mehr zumindest. Es wurde gestohlen. Wahrscheinlich von einem dieser widerlichen Flüchtlinge.\n\nIm Übrigen existiert Auchindoun nicht mehr. Wir haben keine Verwendung mehr für das Buch. Wenn Ihr es findet, könnt Ihr es behalten.\n\nWie schon gesagt, ich habe ein paar dieser Grobiane letzte Woche um die Terrasse herumschleichen sehen. Fangt mit Eurer Suche bei ihnen an. Wahrscheinlich spielen sie irgendwo im Armenviertel Würfelspiele.", progress = "Was willsu?", completion = "Ok, Ok! Tut uns nicht weh. Wir hatten das Buch, aber wir haben es verkauft...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10232] = {title = "Legion in Trümmern", objective = "Tötet 5 Schicksalsschmiede der Mo'arg und 15 Ingenieure der Gan'arg. Kehrt danach zu Papa Mauschel in Area 52 im Nethersturm zurück.", description = "Die Brennende Legion ist auf unserem Grund im Trümmerfeld, den Pfad hinunter und über die Brücke nach Osten, einmarschiert!\n\nDas könnte ein großes Problem für uns sein! Die Legion in den Ruinen von Arklon und jetzt auch noch hier! Langsam sieht es für uns und das Raketenprojekt hier in Area 52 schlecht aus!\n\n<Name>, ich möchte, dass Ihr dorthin geht und mit den Dämonen fertigwerdet! Ich würde es ja tun, aber ich bin kein Kämpfer.\n\nJa, das riecht nach Ärger, ich fühle es.", progress = nil, completion = "Nun, das sind gute und schlechte Nachrichten zugleich. Wir haben ihnen einen Schlag versetzt, aber ich weiß nicht, wie es weitergehen soll, wenn die Brennende Legion überall im Nethersturm frei herumrennt - und näher kommt.\n\nIch habe das Gefühl, dass wir einen Gang hochschalten müssen. Ich hoffe, Ihr könnt uns dabei helfen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10233] = {title = "Den Sonnenzornposten anzünden", objective = "Benutzt eine flammende Fackel, zerstört 4 Sonnenzornballisten und 4 Sonnenzornzelte und kehrt dann zu Zaubererleutnant Morran in Kirin'Var zurück.", description = "Die Garnison des Sonnenzornpostens auszulöschen ist nicht genug, um die Blutelfen davon abzuhalten, ihn erneut zu beziehen. Kael'thas Anhänger sind eifrig und hartnäckig. Sobald im Sonnenzorn noch ein Stein auf dem anderen steht, ist dies praktisch eine Einladung für sie, zurückzukehren.\n\nNein, der Posten muss völlig zerstört werden. Sorgt dafür, dass ihre Zelte und Artillerie zu Asche zerfallen!\n\n<Der Geist ballt die Fäuste.>\n\nStehlt die Fackeln von den Flammenbewahrern des Sonnenzorns um Eure Aufgabe zu erfüllen, <Name>.", progress = nil, completion = "&lt;Zauberhexerleutnant Morran nickt grimmig.&gt;\n\nDie Kirin Tor heißen Zerstörung im Allgemeinen nicht gut, aber um unseren Feind zu vernichten überwinden wir jeden Skrupel. Sogar im Tod.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10234] = {title = "Der Müll eines Dämons", objective = "Sammelt 10 Teile eines Teufelshäschers und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Ihr seht aus, als wärt Ihr <ein fähiger junger Mann/eine fähige junge Frau>! Ich habe mich gefragt, ob Ihr mir vielleicht zur Hand gehen könntet.\n\nIm Osten befindet sich das Trümmerfeld, auf dem die Brennende Legion Einzug gehalten hat. Es ist voller Teufelshäscherteile. Dort liegen auch ein paar kleinere Teile herum, um die sie sich nicht zu scheren scheinen.\n\nIch möchte, dass Ihr dorthin geht, und mir ein paar dieser kleineren Teile eines Teufelshäschers besorgt!", progress = "Habt Ihr die Teile schon? Wir haben nur wenig Zeit, da die Legion überall gleichzeitig in unser Gebiet vorrückt.", completion = "Ich denke, die müssen reichen. Wenn wir sie nur fortjagen könnten!\n\nHe, da fällt mir etwas ein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10235] = {title = "Verdammnisklaue die Krallen stutzen", objective = "Besorgt Euch Verdammnisklaues Hand und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Wisst Ihr, was sie entmutigen würde? Wenn wir ihren Anführer erlegen!\n\nWie ich gehört habe, klappt das immer. Und wenn sie sehen, dass so <ein knallharter/eine knallharte:c> <Klasse> wie Ihr ihren Anführer erledigt, dann ziehen sie sicher den Schwanz ein und rennen weg!\n\nGeht dorthin zurück und erlegt den Großen, den sie Verdammnisklaue nennen. Ich habe gehört, dass er sich im östlichen Teil den Trümmerfelds unter dem Rohr aufhält.\n\nBringt mir seine Klaue! Vielleicht können wir sie brauchen.", progress = "Schon mit Verdammnisklaue abgerechnet?", completion = "Er, äh... er hat was gesagt? SIE WOLLEN AREA 52 ANGREIFEN?\n\nOh, das ist nicht gut... nicht gut!", rewards = "ReißzahnklaueGestohlene astrale KlingeMamas LebensversicherungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10236] = {title = "Die Scherbenwelt ist doof!", objective = "Großknecht Razelcraz möchte, dass Ihr ihm 6 Schredderteile besorgt. Kehrt danach zu ihm bei der Mine nordwestlich von Thrallmar zurück.", description = "Ich kann es kaum fassen, dass ich Beutebucht verlassen habe, um in die Scherbenwelt zu kommen. Mein Vetter Quack Lufthans hat mir versprochen, dass ich hier ein Vermögen machen würde, aber stattdessen ist er in seinem Zeppelin auf und davon und hat mich hier zurückgelassen. Nun versuche ich, mir einen sehr bescheidenen Lebensunterhalt mit der Mine zu verdienen.\n\nAber wie soll ich denn überleben, wenn ich dauernd von Höllenebern und Dämonen und Höllenorcs angegriffen werde? Mein Schredder hier ist gestern kaputt gegangen und die Höllenorcs haben meine Ersatzteile gestohlen. Sie haben die Teile in die Große Kluft im Südwesten gebracht und vielleicht dort fallenlassen.", progress = "Habt Ihr schon ein paar Ersatzteile für meinen Schredder gefunden? Ich möchte ihn wirklich gerne reparieren, damit ich mich weiter dem Bergbau in der Mine widmen kann. Irgendwie muss ich ja ein wenig Geld verdienen. Und wenn ich davon nur eine Fahrkarte nach Beutebucht kaufe. Ohne Rückfahrt!", completion = "Hurra, Ihr habt ein paar Teile gefunden! Jetzt kann ich meinen Schredder hoffentlich wieder zum Laufen bringen. Wenn ich genug Geld verdiene, kann ich vielleicht wieder zurück nach Beutebucht.\n\nIch hoffe, dass mein Vetter Quack Lufthans mit seinem blöden Zeppelin abstürzt. Ich kann es nicht fassen, dass er mich so hinterhältig in die Scherbenwelt gelockt hat.", rewards = "Ihr bekommt:\n\nTeufelseisenerz"}
MultiLanguageQuestData['de'][10237] = {title = "Warnt Area 52!", objective = "Überbringt Raketenchef Doppeldecker in Area 52 in Nethersturm die schlechten Nachrichten.", description = "<Name>, Ihr müsst so schnell wie möglich nach Area 52 zurückkehren! Beeilt Euch!\n\nSagt dem Raketenchef, dass die Brennende Legion hinter uns her ist!", progress = nil, completion = "Ha, Ihr macht Witze, oder? Die Brennende Legion gibt uns die Schuld daran?\n\nAber IHR wart das!\n\nOh, ich habe Kopfschmerzen, die so groß wie diese Rakete sind! Ok, ok, wir müssen uns einen anderen Plan einfallen lassen.\n\nWenn die Brennende Legion denkt, dass sie hierher kommen, unser Dorf zerstören und meinen Traum von einer Reise durch den wirbelnden Nether ruinieren kann, dann hat sie sich aber getäuscht.\n\nUnd ich kenne genau den richtigen Goblin, der uns dabei helfen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10238] = {title = "Wie man Goblins zubereitet", objective = "Rettet Manni, Moh und Jakk aus den Lagern der Höllenorcs und bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar zurück.", description = "Warum sollten die Höllenorcs denn meine Schredderteile stehlen wollen? Ich hasse sie so. Sie schleichen sich einfach in mein Lager hier und klauen immer meine Sachen. Vor ein paar Tagen haben sie drei meiner Peons gestohlen! Jetzt sind alle anderen Peons abgehauen, weil sie Angst hatten, von den Höllenorcs gefressen zu werden.\n\nIch kann meine Mine ohne Peons nicht betreiben. Wenn Ihr meine gestohlenen Peons retten könntet, kommen die anderen vielleicht auch wieder zurück. Die Höllenorcs haben ihre Lager entlang des Walls im Südwesten.", progress = "Habt Ihr meine Arbeiter schon gerettet? Bitte beeilt Euch, ich fürchte, dass sie gefressen werden, und sie schmecken wahrscheinlich nicht so gut. Wenn sie richtig schrecklich schmecken, werden die Höllenorcs vielleicht richtig böse auf mich.", completion = "Vielen Dank, dass Ihr meine Peons gerettet habt. Vielleicht kann ich sie jetzt dazu bringen, meinen Schredder mit den Teilen, die Ihr gefunden habt, zu reparieren. Dann kann ich wieder etwas Geld verdienen und aus der Scherbenwelt abhauen. Ich kann es kaum abwarten, wieder in Beutebucht zu sein.", rewards = "Ihr bekommt:\n\nPeonschlaftrank"}
MultiLanguageQuestData['de'][10239] = {title = "Mögliche Energiequelle", objective = "Zaubererleutnant Morran in Kirin'Var möchte, dass Ihr ihm 10 Energieisolationswürfel von den Blutelfen der Manaschmiede Coruu bringt.", description = "Wir sind nicht die Einzigen, die unter dem Zufluss von Manakreaturen leiden. Auch die Blutelfen sind darüber besorgt, ich weiß jedoch nicht, warum.\n\nWas immer sie da drüben tun mögen, sie scheinen nicht damit aufzuhören. Stattdessen erfinden sie immer neue Methoden, um sie zu töten. Die wirksamste davon beinhaltet eine magische Verteidigung, die von einer Art konzentrierter Energie gespeist wird.\n\nSammelt einige dieser Energiequellen und bringt sie mir. Scheut Euch nicht, die Blutelfen zu töten, wenn sich eine Gelegenheit ergeben sollte.", progress = "Konntet Ihr ein paar ihrer Energiequellen sammeln?", completion = "&lt;Morran dreht einen der Würfel vorsichtig in der Hand.&gt;\n\nIch glaube nicht, dass ich je zuvor so etwas gesehen habe. Es steckt sicher eine Menge Energie darin, aber es ist rohe Energie. Wir müssen vorsichtig damit sein, aber ich glaube, dass wir einen Weg finden können, wie man sie zur Abwehr der Manakreaturen einsetzen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10240] = {title = "Eine Verteidigung errichten", objective = "Benutzt das Gerät zur Aktivierung von Runen bei der östlichen Rune, der nordöstlichen Rune und der westlichen Rune. Die Runen befinden sich entlang der Verteidigung der Zaubergasse und des Ratsplatz von Kirin'Var. Kehrt zu Zaubererleutnant Morran zurück, wenn Ihr die Aufgabe erfüllt habt.", description = "Wir sind dabei, eine Verteidigung um das Dorf herum zu errichten, die mit der Energiequelle der Blutelfen gespeist wird. Ich kann nicht garantieren, dass sie funktionieren wird, aber wir müssen es versuchen.\n\nWenn nicht werden die Manakreaturen weiterhin die Geister der gefallenen Kirin Tor verspeisen.\n\nBenutzt dieses Gerät bei den kleinen Runen um die Verteidigung des Dorfes herum, um die Energie dort freizusetzen. Wenn ich das Feld korrekt gewebt habe, sollten wir die Wirkung bemerken, sobald Ihr das Gerät bei jedem Punkt benutzt habt.", progress = "Habt Ihr alle Runen aktiviert? Ich bin so gespannt, ob wir die Methode der Blutelfen hier verbessern können. Was einer von Kael'thas Leuten tun kann, kann ein Kirin Tor noch besser!", completion = "Ausgezeichnete Arbeit. Drückt die Daumen, &lt;Name&gt;. Ich werde das Schild jetzt aktivieren.", rewards = "Berührung der HarmoniePurpurrote PanzerarmschienenVerteidigerschienbeinschützer von Kirin'VarStiefel des WohltätigenDer folgende Zauber wird auf euch gewirkt:\n\nArkane Explosion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10241] = {title = "Ablenkung in der Manaschmiede B'naar", objective = "Tötet 8 Magister des Sonnenzorns und 8 Blutwärter des Sonnenzorns und kehrt dann zu Exarch Orelis in Area 52 zurück.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Ruf bei den Sehern.", description = "Wir wurden von Sha'tar hierher geschickt, um die Manaschmieden, die Kael'thas' Armee hier betreibt, zu untersuchen. Aber die Seher drohen damit, ihre Spionagearbeiten nicht durchzuführen, wenn wir sie nicht militärisch unterstützen.\n\nWir können uns nicht erlauben, dass diese Mission wegen politischen Differenzen den Bach hinunter geht, daher haben wir uns einverstanden erklärt, die Verteidigung der Manaschmiede zu schwächen, damit die Seher ihre Arbeit verrichten können.\n\nBeweist Eure Loyalität gegenüber den Aldor und tötet die Magister und Blutwärter des Sonnenzorns, die die Manaschmiede B'naar bewachen.", progress = "Habt ihr Eure Aufgabe erfüllt, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Seher haben dank Eures Ablenkungsmanövers wichtige Informationen sammeln können. Vielleicht teilen sie sie dieses Mal tatsächlich mit uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10242] = {title = "Der Rückenbrecherposten", objective = "Apothekerin Zelana beim Häschersturz möchte, dass Ihr mit Schwadronskommandant Brack sprecht, um auf einem Wyvern zum Rückenbrecherposten zu fliegen. Bringt die Blutprobe des Blutenden Auges zu Apotheker Albreck im Rückenbrecherposten.", description = "<Name>, meine Ausrüstung hier ist leider nicht für alle Tests, die ich durchführen möchte, geeignet. Mein Kollege Apotheker Albreck im Rückenbrecherposten verfügt jedoch über alle Hilfsmittel, die man dazu braucht.\n\nIch habe eine Blutprobe des Blutenden Auges, die mir ein Agent aus Thrallmar besorgt hat. Bringt diese Probe zu Albreck und erlaubt ihm, sie zu untersuchen.\n\nSprecht mit Schwadronskommandant Brack, um zum Rückenbrecherposten zu kommen. Er befindet sich in der Nähe der Wyvern im Süden.", progress = "Willkommen im Rückenbrecherposten. Wie kann ich Euch dienen?", completion = "Ein Bluttest also? Es wird mir ein Vergnügen sein. Ich arbeite immer gerne mit Blut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10243] = {title = "Die Technologie der Naaru", objective = "Geht in die Manaschmiede B'naar und sucht die Steuerkonsole von B'naar.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Die Seher haben eine Stammrolle der Manaschmiede B'naar in die Hände bekommen und sind nun dabei, gezielt nach Anschlagsopfern zu suchen.\n\nSie haben jedoch eine kleine Information übersehen, die an den Rand der Schriftrolle gekritzelt wurde. Es scheint eine Art Passwort oder Code zu sein, wie sie für den Zugang zu von den Naaru erschaffenen Technologien wie der Exodar oder der Festung der Stürme benutzt werden.\n\nGeht in die Manaschmiede und haltet nach einer Steuerungskonsole Ausschau. Schreibt die Anzeige so gut es geht auf dieser Rolle ab. Wir müssen unseren Verdacht über die Herkunft von Kaels Technologie erhärten.", progress = "Die Symbole sehen fremdartig und unlesbar aus.", completion = "Ihr öffnet die Rolle und bereitet Euch vor, die merkwürdigen Symbole abzuschreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10244] = {title = "Liesmich", objective = "Bringt die Bauanleitung für Teufelshäscher zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Ihr zerbrecht das Siegel des ziemlich großen Folianten und könnt nicht verstehen, was dort geschrieben steht. Es schein die Sprache der Dämonen zu sein.\n\nIhr könnt jedoch die Bilder erkennen, die ihre eigene Geschichte erzählen.\n\nEs handelt sich eindeutig um eine Bauanleitung für Teufelshäscher, und Ihr wisst ganz sicher, dass Mama Mauschel sich das gerne anschauen würde.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10245] = {title = "Steuerungsabschrift von B'naar", objective = "Bringt die Steuerungsabschrift von B'naar zu Anachoret Karja in Area 52 im Nethersturm.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Ihr versucht die Formen abzuschreiben, als sie an Euren Augen vorbeiziehen. Die Ergebnisse sind nicht gerade genau, aber sie sollten genügen, um den Verdacht der Aldor zu bestätigen.", progress = "Wollen wir mal schauen, was Ihr da habt, <Name>.", completion = "Gut gemacht, &lt;Name&gt;. Gebt mir ein paar Augenblicke, um die Abschrift zu lesen.\n\nIhr habt den Dank der Priesterschaft, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10246] = {title = "Angriff auf Manaschmiede Coruu", objective = "Reist zur Manaschmiede Coruu und tötet 8 Arkanisten des Sonnenzorns und 5 Forscher des Sonnenzorns. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Euer Erfolg in der Manaschmiede B'naar war sehr bemerkenswert. Ich bin sicher, dass Anachoret Karja Euch bitten wird, Eure Leistung als Nächstes in der Manaschmiede Coruu zu wiederholen.\n\nWir haben erfahren, dass ein besonders wichtiges Regiment von Arkanisten und Forschern des Sonnenzorns dort stationiert wurde. Wir würden sie gerne angreifen. Wenn es Euch gelingt, wird das ein vernichtender Schlag für die Streitkräfte unseres Feindes sein.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Mit Eurem Einsatz schaffen wir es sicher, den Feind zu besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10247] = {title = "Dr. h. c. tüft. Vomisa", objective = "Sprecht mit Dr. h. c. tüft. Vomisa in den Versuchsgründen im Nethersturm.", description = "Am Rand des Dorfes im Osten befinden sich die Versuchsgründe. Unser Spitzenobertüftler, Doktor Vomisa, hat hier ein wenig mit einer Kombination aus Teufelshäschertechnologie, Astraltechnologie und natürlich Goblintechnologie herumgespielt.\n\nDas verdanken wir nicht zuletzt Euren Sammelbemühungen, Juniortechniker dritten Grades <Name>!\n\nSucht ihn auf! Ich bin mir sicher, dass er einen Weg weiß, wie Area 52 gerettet werden kann.\n\nUnd weil er Euch sicher als Versuchskaninchen einsetzen möchte, würde ich an Eurer Stelle lieber ein paar Freunde mitbringen. Nur für den Fall.", progress = nil, completion = "Wie es scheint, haben wir großes Glück, junger Mann.\n\nIch habe gerade neulich meine neuste Erfindung, den Schrotthäscher X6000, fertig stellen können!\n\nUnd Ihr habt die Ehre, mir dabei zu helfen, ihn zu testen. Dann können wir ihn zur Verteidigung von Area 52 einsetzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10248] = {title = "Du, der Roboter", objective = "Aktiviert die Steuerung für Schrotthäscher X6000 und testet seine Fähigkeiten aus. Gebt Dr. h. c. tüft. Vomisa bei den Versuchsgründen im Nethersturm danach Eure Rückmeldung.", description = "Dr. h. c. tüft. Vomisa zu Euren Diensten. Hier, nehmt diese Steuerung. Ich möchte, dass Ihr sie aktiviert und meinen neu erfundenen Schrotthäscher X6000 mal ausprobiert.\n\nBleibt in der Nähe! Die Steuerung ist an meine Konsole hier gebunden, wenn Ihr zu weit weggeht, wird der Roboter aufhören zu funktionieren.\n\nProbiert alles aus... Ich schaue zu und stelle dann die Servos gemäß Eures Testlaufs ein.", progress = "Was meint Ihr? Muss noch ein wenig optimiert werden, was?", completion = "Nun, mein Junge, das war aber aufregend! Und meiner Meinung nach hat der Schrotthäscher X6000 trotz seines Grünschnabelpiloten gut funktioniert.\n\nHehe, seid nicht beleidigt, ich mache nur Witze. Schließlich habt Ihr gerade Area 52 und die X-52 Netherrakete vor dem sicheren Untergang bewahrt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10249] = {title = "Zurück zum Chef!", objective = "Meldet Euch sofort bei Raketenchef Doppeldecker in Area 52 im Nethersturm!", description = "Ich bin mir sicher, dass der Raketenchef ein oder zwei Takte mit Euch reden möchte!\n\nAn Eurer Stelle würde ich mich gleich nach Area 52 aufmachen und mit ihm sprechen!", progress = nil, completion = "&lt;Name&gt;! Oder sollte ich sagen Juniortechniker ersten Grades &lt;Name&gt;?! Ach, wem mache ich etwas vor. Einen Grad zu überspringen ist keine angemessene Belohnung für das, was Ihr getan habt. Ich ernenne Euch zu meinem Ersten Offizier!\n\nIhr habt uns alle gerettet, und noch viel wichtiger, die X-52 Netherrakete! Ich könnte Euch küssen... aber das tue ich nicht.\n\nLasst mich Euch stattdessen die Dankbarkeit von Area 52 zeigen. Wählt etwas aus!", rewards = "Pilotengamaschen X-52Technikerhelm X-52Verteidigerhose von Area 52Ihr bekommt:\n\nRaketenhelm X-52"}
MultiLanguageQuestData['de'][10250] = {title = "Blutige Rache", objective = "Stoßt am alten Belagerungsturm der Allianz in das Kampfhorn der Unerschütterlichen. Tötet Urtrak und kehrt danach zu Althen dem Historiker im Rückenbrecherposten zurück.", description = "Im Osten befindet sich ein alter Belagerungsturm der Allianz. Jetzt suchen Plünderer dort nach alten Nägeln und Alteisen. Vor langer Zeit haben bei diesem Turm viele Krieger der Allianz ihr Leben gelassen. Ihr Banner wurde von einem widerlichen Orckommandanten namens Urtrak gestohlen.\n\nStoßt bei diesem Belagerungsturm in das Kampfhorn der Unerschütterlichen, um Urtraks Aufmerksamkeit zu erregen. Vielleicht ruft es auch Krieger herbei, die vor langer Zeit in der Schlacht gestorben sind.", progress = "Habt Ihr schon in das Horn gestoßen? Wir müssen es bald tun. Wer weiß, wann Thrallmar die Unterstützung der Unerschütterlichen braucht.", completion = "Ich bin froh, dass die Unerschütterlichen Euch im Kampf unterstützt haben. Ich dachte mir schon, dass sie dem Ruf ihres Schlachthorns folgen würden, aber ich war mir nicht sicher. Vielleicht haben wir ihnen jetzt die Rache ermöglicht, die sie so sehr begehrten.\n\nIhr habt Urtrak getötet. Diesen Sieg müssen wir Kommandant Hogarth im Expeditionsrüstlager der Allianz melden. Er wird verstehen, welche Gefahren Ihr für ihn auf Euch genommen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10251] = {title = "Der große Plan des Meisters?", objective = "Sucht Nitrin den Gelehrten im verlassenen Rüstlager in Nagrand.", description = "Gestern Abend haben uns ein paar Draenei einen Besuch abgestattet. Sie haben irgendwie erfahren, dass wir das Buch in unserem Besitz haben und uns das großzügige Angebot gemacht, es uns abzunehmen.\n\nWir haben sie nicht gefragt, was sie mit dem Buch wollen, aber der Jüngere sprach die ganze Zeit vom \"großen Plan des Meisters\", was immer das zu bedeuten hat.\n\nIch stelle keine Fragen, wenn es ums Geld geht. Sie haben uns viel Gold geboten und wir haben ihnen das Buch gegeben.\n\nEr sagte, er lebe in Nagrand, im alten verlassenen Rüstlager nördlich von Telaar.", progress = nil, completion = "Die Zeichen waren deutlich, aber ich war blind.\n\nDer eiserne Griff der Legion wird von Tag zu Tag stärker. Sogar hier...\n\nIch wusste es... wusste, dass mein Junge mit den Dämonen kommunizierte... Sie haben ihm Macht angeboten und ihm dann einen Vorgeschmack dieser Macht gegeben. Mehr war nicht nötig...\n\nDas Buch ist fort. Levixus hat es genommen... Nur ich und sein dunkler Meister kennen seine Pläne.\n\nFremder, ich weiß nicht, ob Ihr jemals im Leben das Richtige getan habt, aber Ihr müsst eines wissen: der Junge muss aufgehalten werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10252] = {title = "Vision der Toten", objective = "Nitrin im verlassenen Rüstlager in Nagrand möchte, dass Ihr ihm 1 Augapfel eines Berggronns, 1 fehlerloser Schnabel eines großen Windrocs und 1 Tran eines gealterten Grollhufs bringt.", description = "Es hat schon begonnen. Levixus steht auf den Ruinen von Auchindoun und liest aus dem Buch der Toten. Er ruft die Toten beim Namen und unterwirft die gequälten Seelen durch ein dämonisches Ritual seinem Willen. Wenn er kann, wird er ganz Auchindoun erwecken!\n\nAber... Ihr müsst Euch erst vorbereiten. Ihr könnt nicht mit etwas kämpfen, dass Ihr nicht seht.\n\n<Nitrin reicht Euch ein Pergament.>\n\nBringt mir die Gegenstände, die ich für die Tinktur benötige. Sie wird Euren Geist erweitern und Euch ermöglichen, die Geisterwelt zu sehen.", progress = "Levixus' Armee wächst mit jeder weiteren Sekunde in ihrer Größe und Stärke. Ihr müsst Euch beeilen.", completion = "Fremder... ich war nicht ganz aufrichtig zu Euch. Wenn Ihr diesen Trank zu Euch nehmt, werdet Ihr die Welt der Geister für alle Zeit sehen können. Diese Tinktur ist Teil des Initiierungsrituals für alle Totenpriester von Auchindoun. Viele werden wahnsinnig, wenn der Effekt eintritt. Die Toten sehen zu können ist... schockierend.\n\n&lt;Nitrin hält Euch den Trank an die Lippen.&gt;\n\nWollt Ihr es tun?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10253] = {title = "Levixus der Seelenrufer", objective = "Vernichtet Levixus und nehmt Euch das Buch der Toten aus seinem Besitz.\n\nBringt das Buch der Toten zu Ramdor dem Wahnsinnigen außerhalb der Auchenaikrypta am Eingang zu Auchindoun.\n\nIhr hattet eine Vereinbarung, erinnert Ihr Euch?", description = "Geht jetzt, <Name>. Ihr könnt Levixus auf den höchsten Ruinen von Auchindoun finden. Nähert Euch vom Süden der Knochenwüste. Er befindet sich mitten in einem Sturm von Seelen...\n\nVernichtet ihn und nehmt ihm das Buch der Toten ab. Wenn Ihr das verfluchte Buch in Eurem Besitz habt, dann zerstört es! Zerstört es, damit eine solche Grausamkeit nie wieder geschehen kann.", progress = "Wer seid Ihr und was wollt Ihr? Oh... IHR seid es.", completion = "Wenn der alte Draenei Euch aufgetragen hat, das Buch zu zerstören, warum habt Ihr es dann nicht getan?\n\n&lt;Ramdor starrt Euch an.&gt; Ach, was soll's. Ihr seid vielleicht gierig, aber ehrlich.\n\nIch allerdings... Ich habe gelogen, um an das Buch zu kommen. Ich habe nicht die leiseste Ahnung, wo diese armen, verirrten Seelen ihren Schatz aufbewahren, und wenn ich es wüsste, würde ich es Euch nicht sagen. Aber ich habe trotzdem etwas für Euch. Ihr habt heute etwas Gutes getan. Vielleicht sogar etwas Großartiges... Ihr solltet belohnt werden.\n\nÜbrigens, willkommen im Club.\n\n&lt;Ramdor zeigt auf die Geister.&gt;", rewards = "Bedeckung des rechtschaffenen ZornsSchienbeinschützer des ErdenbrechersGamaschen der dritten MünzeHandschuhe der ReueIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10254] = {title = "Truppenkommandant Danath", objective = "Marschall Isildor möchte, dass Ihr Euch bei Truppenkommandant Danath Trollbann in der Ehrenfeste meldet.", description = "<Marschall Isildor spuckt in den Staub.>\n\nNun, es ist an der Zeit, dass Ihr Euch Euren Sold verdient. Meldet Euch sofort bei Truppenkommandant Trollbann in der Feste. Er und seine Berater werden sich sicher freuen, Euch zu sehen.\n\n<Marschall Isildor salutiert teilnahmslos.>\n\nFür die Allianz!", progress = nil, completion = "Ich bin froh, dass Ihr hier seid, Bruder. Ich bin Danath Trollbann - Anführer der Söhne des Lothar und Truppenkommandant dieser Feste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10255] = {title = "Das Gegengift testen", objective = "Probiert das cenarische Gegengift an einem bulligen Hölleneber aus und beobachtet die Folgen. Sobald Ihr die Ergebnisse des Experiments habt, kehrt zu Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", description = "Ich glaube, in dem Blut ist etwas, das wir als Grundlage für ein Gegengift verwenden können. Schaut mich nicht an, als hätte ich den Verstand verloren!\n\nDas ist in der Natur ganz normal. Oft kann das Heilmittel aus dem Gift selbst gewonnen werden. Und genau das habe ich vor.\n\nWenn wir die Eber von dem dämonischen Einfluss befreien können, verlieren sie hoffentlich ihre Aggressivität und können uns zeigen, wie wir auch den andern Arten helfen können.", progress = "Habt Ihr die Ergebnisse des Experiments, <Name>?", completion = "&lt;Thiah Rotmähne macht große Augen, als Ihr die Ergebnisse des Experiments beschreibt.&gt;\n\nWie konnte das nur geschehen? Ich bin mir sicher, dass ich das Gegengift richtig hergestellt habe!\n\nIch habe gesehen, wie es mit Spinnen- und Schlangengiften funktioniert hat, warum kehrt sich die Wirkung hier nicht um? Vielleicht ist das eine der vielen Besonderheiten der Scherbenwelt, &lt;Name&gt;. Ich leite diese Information am Besten an meine Kameraden weiter.", rewards = "Stab des cenarischen NaturalistenWut des SchreckensebersHölleneberklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10256] = {title = "Den Schlüsselmeister finden", objective = "Sucht Apex und besorgt Euch Apex' Kristallfokus. Kehrt dann zum Violetten Turm zurück und benutzt Apex' Kristallfokus in der Nähe von Erzmagier Vargoths Kugel um herauszufinden, wer den Schlüssel zum Fluch des Turms hat.", description = "Wenn ich zurückblicke, hätte ich eigentlich wissen müssen, dass Kael'thas' Magie so widerstandsfähig ist. Er war schon immer ein talentierter Magier, aber nie zuvor habe ich etwas so Mächtiges gesehen, wie die Magie, die er beim Angriff auf den Turm gewirkt hat.\n\nDer Schutzschild verhindert, dass ich die Macht, die er aufrechterhält, ausspionieren kann, aber Ihr könnt das trotzdem.\n\nIhr werdet jedoch einen Fokus brauchen. Apex, ein Riese, der Kristalle mit sich herumträgt, streift auf den Weiten westlich der Manaschmiede Duro umher. Einer seiner Kristalle würde einen ausgezeichneten Fokus abgeben.", progress = "Was habt Ihr gesehen?", completion = "&lt;Ihr beschreibt, was Ihr gesehen habt.&gt;\n\nKommandant Sarannis sagt Ihr? Hmm...\n\nSie ist eine von Kael'thas Beratern, aber ganz sicher keine Magierin. Ich kenne sie von dem Angriff auf Kirin'Var. Ich glaube, Ihr habt Recht, &lt;Name&gt;. Sie mag den Fluch vielleicht nicht selbst aufrechterhalten, aber sie hat den Schlüssel zum Schild.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10257] = {title = "Den Schlüsselstein erobern", objective = "Reist zur Botanika der Festung der Stürme und besorgt Euch den Schlüsselstein von Kommandantin Sarannis. Bringt ihn danach zu Erzmagier Vargoth im Violetten Turm.", description = "Es überrascht mich nicht, dass Kael'thas den Schlüssel zu diesem Schutzschild in die Hände von jemandem wie Kommandantin Sarannis gegeben hat. Prinz Kael'thas mag vielleicht vieles sein, aber sicher kein Narr.\n\nUm diesen Fluch ein für alle Mal zu brechen, müsst Ihr in die Festung der Stürme gehen und den Schlüsselstein besorgen.\n\nWenn der Schlüsselstein zerstört ist, werde ich meine Freiheit wiedererlangen.", progress = "Habt Ihr den Schlüsselstein?", completion = "&lt;Die Augen des Erzmagiers leuchten auf, als Ihr ihm den Schlüsselstein gebt.&gt;\n\nErstaunlich! Nach dem, was ich von Farahlons Schicksal erblickt habe, bin ich mir nicht sicher, ob ich hinaus will, aber es ist immerhin besser, als für den Rest meiner Tage hier eingesperrt zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10258] = {title = "Die Gefallenen ehren", objective = "Meldet Euch bei Hogarth, dem Kommandanten des Expeditionsrüstlagers.", description = "Hogarth, der Kommandant des Rüstlagers, befindet sich im östlichen Turm. Ihr müsst ihm von Eurem Sieg über Urtrak berichten. Vielleicht ist er dann freundlich? Natürlich könnte er auch versuchen, Eure Seele zu fressen. Bei Geistern wie diesen weiß man nie.\n\nDie Unerschütterlichen sind uns immer noch feindlich gesonnen und werden versuchen zu töten, wenn sie können. Seid vorsichtig, <Name>.", progress = nil, completion = "Wir haben die Schlacht vor so langer Zeit gegen die Höllenorcs verloren. Ihr habt uns unsere Ehre zurückgegeben, indem Ihr Urtrak getötet habt.\n\nNehmt Euch eine unserer Waffen. Wenn Ihr gegen unseren verhassten Feind in den Kampf zieht, benutzt diese Waffe, und die unter uns, die frei vom Fluch sind, werden Euch zur Hilfe kommen.\n\nBevor Ihr geht möchten einige, die vor Jahren beim Belagerungsturm gefallen sind, Euch für die Zerstörung unseres Feindes Ehre erweisen.", rewards = "Klinge des UnerschütterlichenRute des UnerschütterlichenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10259] = {title = "In die Bresche springen", objective = "Tötet 6 einfallende Teufelswachen und kehrt dann zum Argentumabgesandten Stolzbrunn zurück.", description = "Die Kämpfe bei dem Portal nehmen kein Ende! Die Argentumdämmerung kämpft in einer verzweifelten Schlacht - sollten wir verlieren, wird das Feuer der Dämonen niemals erlöschen.\n\nHelft uns, <Name>. Zieht in den Kampf und helft unseren Brüdern und Schwestern. Helft ihnen, sich gegen die Welle der Dunkelheit zu erheben! Die Argentumdämmerung - und die Welt - brauchen Euch!", progress = nil, completion = "Danke, &lt;Name&gt;. In den Wirren der Schlacht leuchten Helden wie Sterne in der Dunkelheit. Euer Licht erstrahlt hell und klar!", rewards = "Ihr bekommt:\n\nWappenrock des Beschützers"}
MultiLanguageQuestData['de'][10260] = {title = "Netheorologe Kupfernickel", objective = "Sprecht mit Netheorologe Kupfernickel bei der Brücke, die vom Nethersturm zum Schergrat führt.Ihr müsst über die Hauptbrücke vom Schergrat in den Nethersturm gekommen sein. Habt Ihr dort Netheorologe Kupfernickel mit seiner verrückten Ausrüstung gesehen?\n\nMerkwürdig, ich erwarte einen Bericht von ihm, und er ist schon lange überfällig. Wahrscheinlich hat er es vergessen. Ihr kennt ja diese \"Wissenschaftler\".\n\nGeht zurück zur Brücke und nagelt ihn fest. Lasst Euch nicht mit Entschuldigungen abspeisen, bringt mir einfach seinen Bericht.\n\nDanke!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr müsst über die Hauptbrücke vom Schergrat in den Nethersturm gekommen sein. Habt Ihr dort Netheorologe Kupfernickel mit seiner verrückten Ausrüstung gesehen?\n\nMerkwürdig, ich erwarte einen Bericht von ihm, und er ist schon lange überfällig. Wahrscheinlich hat er es vergessen. Ihr kennt ja diese \"Wissenschaftler\".\n\nGeht zurück zur Brücke und nagelt ihn fest. Lasst Euch nicht mit Entschuldigungen abspeisen, bringt mir einfach seinen Bericht.\n\nDanke!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10261] = {title = "Gesucht: Vernichterservo!", objective = "Besorgt einen Vernichterservo und bringt ihn zu Papa Mauschel in Area 52 im Nethersturm.", description = "GESUCHT: 1 Vernichterservo, um den kaputten in meinem langhalsigen Spektrumanalysator zu ersetzen.\n\nIhr und Eure Freunde sollten bei den Blutelfen in der Manaschmiede B'naar im Westen nachschauen, ob sie ein paar Ersatzteile haben. Wie es scheint, haben sie dort ein paar Arkanvernichter.\n\nBitte bringt den Servo in unbeschadetem Zustand zu Papa Mauschel in Area 52.", progress = "Ich hoffe, Ihr kommt wegen meiner Suchanzeige!", completion = "Juhuu! Wisst Ihr, wie schwer man an diese Dinge herankommt? Es ist ja nicht so, als ob ich hier draußen täglich eine Teilelieferung bekommen würde.\n\nWisst Ihr was? Als Belohnung lasse ich Euch etwas aus meiner Kramkiste nehmen. Es ist sicher etwas darin, was Ihr brauchen könnt. Wenn nicht, verkauft es einfach weiter.\n\nIn Ordnung, lasst mich das Euch abnehmen und in meinen langhalsigen Spektrumanalysator einbauen, bevor der alte Servo noch explodiert!", rewards = "Roter SpitzhutExotische StachelschulternVerlorene Brustplatte des EhrfürchtigenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10262] = {title = "Ein Hügel voll Astraler", objective = "Sammelt 10 Insignien der Zaxxis und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück.", description = "Es gibt noch etwas anders, bei dem ich Eure Hilfe brauche.\n\nEine Gruppe von Astralen, die als Zaxxis bekannt sind, haben ihre Verbindungen zum Konsortium abgebrochen um ihre eigenen Geschäfte zu machen. Sie machen sogar Geschäfte mit den Blutelfen! Das können wir nicht hinnehmen!\n\nIch habe ihre Gruppe bei dem Hügel im Süden unterwandert, aber als ich ihren Anführer ausgeschaltet hatte, musste ich zurück in die Sicherheit von Area 52 fliehen.\n\n<Klasse>, geht dorthin und bringt mir ihre Insignien. Natürlich tragen nicht alle Insignien, weil sie Feiglinge sind.", progress = "Ist es vollbracht? Habt Ihr den Abschaum der Zaxxis vom Angesicht der Scherbenwelt ausgerottet und mir ihre Insignien gebracht?", completion = "Diese Insignien sind ein guter Anfang.\n\nUnglücklicherweise haben meine anderen Agenten bei den Zaxxis berichtet, dass Sphärenräuber Nesaad immer noch am Leben ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10263] = {title = "Dem Konsortium helfen", objective = "Sprecht mit Netherpirscher Khay'ji in Area 52 im Nethersturm.", description = "Die Naaru von Shattrath haben versucht, dem Konsortium beizubringen, die Dinge auf ihre Weise zu sehen.\n\nDas Glück wollte, dass die Geschäftsbeziehungen zwischen den Astralen und den Blutelfen im Nethersturm sich in letzter Zeit drastisch verschlechtert haben.\n\nIm Dorf gibt es einen Mitarbeiter des Konsortiums namens Khay'ji, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen Astralen hatte. Als Mitglied der Aldor möchte ich Euch bitten, ihm zu helfen, wo Ihr nur könnt.", progress = nil, completion = "Hallo, &lt;Volk&gt;.\n\nIhr habt nicht zufällig Zeit für einen Wiederbesorgungsauftrag von ziemlicher Wichtigkeit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10264] = {title = "Dem Konsortium helfen", objective = "Sprecht mit Netherpirscher Khay'ji in Area 52 im Nethersturm.", description = "Die Naaru von Shattrath haben versucht, dem Konsortium beizubringen, die Dinge auf ihre Weise zu sehen.\n\nDas Glück wollte, dass die Geschäftsbeziehungen zwischen den Astralen und den Blutelfen im Nethersturm sich in letzter Zeit drastisch verschlechtert haben.\n\nIm Dorf gibt es einen Mitarbeiter des Konsortiums namens Khay'ji, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen Astralen hatte. Als Mitglied der Seher möchte ich Euch bitten, ihm zu helfen, wo Ihr nur könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10265] = {title = "Kristallsammlung des Konsortiums", objective = "Besorgt ein Kristallartefakt von Arklon und bringt es zu Netherpirscher Khay'ji in Area 52 im Nethersturm.", description = "Unser Anführer, Nexusprinz Haramad, hat mich gebeten, ein Kristallartefakt aus den Ruinen von Arklon im Südosten zu besorgen.\n\nEs sind alte Draeneiruinen. Zum Pech für mich und die Goblins hier hat die Brennende Legion beschlossen, selbst danach zu graben.\n\nWenn Ihr mir weiterhin helfen wollt, nehmt dem Schreckenslord namens Pentatharon das Kristallartefakt ab.", progress = "Ich habe den Eindruck, dass der Prinz nach einem ganz bestimmten Kristall sucht, aber ich bin mir nicht sicher, welcher das ist.\n\nHabt ihr dem Schreckenslord schon seinen abgenommen?", completion = "Lasst mich ihn mal ansehen.\n\nHmm, er scheint nicht besonders zu sein. Ich bezweifle, dass er das ist, obwohl Eure Beschreibung der Vorgehensweisen der Legion in den Ruinen den Anschein erweckt, dass auch sie nach etwas ganz Bestimmten suchen.\n\nWollen wir hoffen, dass es nicht der Kristall ist, den der Nexusprinz so unbedingt haben will.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10266] = {title = "Bitte um Unterstützung", objective = "Sucht Gahruj und bietet ihm Eure Hilfe an. Er befindet sich im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Während Ihr in den Ruinen von Arklon wart, habe ich eine Bitte um Unterstützung von einem unserer Mitarbeiter im Feld erhalten. Wie es scheint hat das Konsortium einige Probleme damit, Waren von den Blutelfen zurückzufordern, die sie nicht bezahlen wollen.\n\nBitte begebt Euch von Area 52 aus nach Osten und überquert die Brücke zur nächsten Insel. Ihr findet meinen Gefährten Gahruj im Mittelreichposten in der Biokuppel Mittelreich.", progress = nil, completion = "Ja, es ist wahr. Die Blutelfen weigern sich auch dieses Mal, die Waren, die ihnen schon geliefert wurden, zu bezahlen.\n\nDa Netherpirscher Khay'ji Euch geschickt hat, hoffe ich, dass Ihr mir bei dieser Angelegenheit helfen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10267] = {title = "Rechtmäßiger Besitz", objective = "Sammelt 10 Kästen mit Vermessungsausrüstung und bringt sie zu Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Unsere Geschäftsbeziehungen mit den Blutelfen scheinen zu Ende zu sein. Vor ein paar Wochen wurde ihnen bei der Manaschmiede Duro eine große Ladung mit Vermessungsausrüstung geliefert. Sie haben sich geweigert, dafür zu bezahlen.\n\n<Name>, ich möchte, dass Ihr den Blutelfen in der Manaschmiede Duro im Osten einen Besuch abstattet. Sie scheinen ein paar Probleme mit angreifenden Manakreaturen zu haben, also nutzt aus, dass sie beschäftigt sind.\n\nMir ist egal, was mit ihnen passiert, aber ich hätte meinen rechtmäßigen Besitz gerne zurück.", progress = "Habt Ihr die Vermessungsausrüstung, um die uns die Blutelfen betrogen haben?", completion = "Nun, ich bin froh, dass wir dieses kleine Geschäft abgeschlossen haben. Ich kann mich nicht erinnern, dass das Konsortium je Geschäfte mit solch flegelhaften und unseriösen Wesen gemacht hätte.\n\nIhr scheint jedoch vertrauenswürdig zu sein, &lt;Name&gt;. Vielleicht wollt Ihr mir ja noch einen Gefallen tun?", rewards = "Hut des MittelreichsGamaschen der BiokuppelSchuhwerk von DuroIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10268] = {title = "Eine Audienz beim Prinzen", objective = "Bringt die Vermessungsausrüstung zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm.", description = "Nexusprinz Haramad hat mir zu verstehen gegeben, dass er seinen Besitz unverzüglich und persönlich zurückerhalten möchte. Ich wäre Euch sehr dankbar, wenn Ihr ihm die Waren an meiner statt zurückbringen könntet.\n\nEine Audienz beim Nexusprinzen ist eine große Ehre, und ich bin mir sicher, dass er sehr gerne etwas über Eure Abenteuer im Nethersturm erfahren würde.\n\nSucht ihn in seiner Kammer oben in der Sturmsäule im Norden auf. Er ist oft nur als holografisches Bild anwesend, dass Ihr ansprechen könnt.", progress = "Tretet näher.", completion = "Ich heiße Euch in der Sturmsäule willkommen, &lt;Klasse&gt;. Bitte genießt die Gastfreundschaft des Konsortiums.\n\nDie Ausrüstung könnt Ihr irgendwo abstellen. Ich nehme an, dass Ihr sie schon sehr bald wieder mitnehmen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10269] = {title = "Triangulationspunkt Eins", objective = "Benutzt das Triangulationsgerät, um den Weg zum ersten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Händler Hazzin beim Wachposten des Protektorats auf der Insel der Manaschmiede Ultris im Nethersturm.", description = "Da ist noch ein anderer Grund, warum ich die Vermessungsausrüstung zurückhaben wollte. Es gibt da einen Kristall aus einer alten Draeneilegende, der mir sehr wichtig ist.\n\nMan sagt, dass der Kristall seinem Träger gottgleiche Macht verleiht! Aber es besteht die Gefahr, dass jemand anderes ihn ausgräbt, nämlich die Brennende Legion.\n\n<Name>, nehmt die Ausrüstung und benutzt sie, um den ersten Triangulationspunkt zu finden. Wir wissen, dass er sich irgendwo östlich der Manaschmiede Ultris befinden muss.\n\nMeldet Euch danach bei meinem Agenten, Händler Hazzin, auf der Insel der Manaschmiede Ultris.", progress = "Hallo, Reisender. Seid Ihr zu Hazzin gekommen, weil Ihr meine Waren begehrt?", completion = "&lt;Händler Hazzin senkt seine Stimme zu einem Flüstern.&gt;\n\nAh, ich weiß von Eurem Auftrag. Er ist für Nexusprinz Haramad äußerst wichtig.\n\nJetzt, da wir die Position des ersten Triangulationspunktes herausgefunden haben, müssen wir schnell den zweiten suchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10270] = {title = "Ein nicht-so-bescheidenes Angebot", objective = "Besorgt Euch die Teleporterenergiezelle und bringt sie zur Astralteleportplattform im Sternensturz östlich der Manaschmiede Ultris. Aktiviert die Plattform und bringt die Teleporterenergiezelle zum Bild von Windhändler Marid, damit er sie einbauen kann.", description = "Aus Eurem Gesicht kann ich lesen, dass Ihr <ein/eine:r> <Volk> mit Sinn fürs Geschäft seid.\n\nIch habe mir einen Ruf als Händler für exotische und teure Waren erarbeitet, und bin gerade dabei, ein neues Unternehmen zu starten.\n\nIch könnte einen fähigen Unterhändler brauchen, um die Waren vom Sternensturz weiterzuleiten.\n\nZuerst müsst Ihr eine Teleporterplattform wieder aufladen. Im Zugangsschacht Zeon auf der südlichen Seite der Manaschmiede Ultris findet Ihr eine Ersatzenergiezelle. Das Protektorat befindet sich zurzeit dort, deshalb könnt Ihr einfach ihren Signalgebern zu Eurem Ziel folgen.", progress = "Seid Ihr bereit über das Geschäft zu reden, <Name>?", completion = "Diese Energiezelle sollte für unsere Zwecke ausreichen. Sobald das Geld zu fließen beginnt, werden wir ihn noch weiter verbessern.\n\nDoch genug davon. Jeder mit Diskussionen verschwendete Augenblick bedeutet verlorenen Gewinn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10271] = {title = "Zur Sache", objective = "Ladet den Essenzsammler auf, indem Ihr ihn bei Netherdrachen und Nethergroßdrachen auf dem Sternensturz anwendet, und kehrt dann zu der Gegend um die Astralteleportplattform zurück.", description = "Wir Ihr sicher gesehen habt, wimmelt es in dieser Gegend von Netherdrachen aller Altersstufen. Alle Netherdrachen, die jungen wie die alten, verfügen über eine Essenz, die bei K... - ähh, meinem Kunden sehr begehrt ist.\n\nDie Meisten sind nicht bereit, dafür ihr Leben aufs Spiel zu setzen, deswegen haben wir die Gegend hier ganz für uns alleine. Ihr könnt damit anfangen, die Essenz von allen Drachen hier zu sammeln, aber es ist von größter Notwendigkeit, dass wir sofort einen steten Nachschub aufbauen. Kehrt zu mir zurück, wenn Ihr eine erste Ladung zusammen habt.", progress = "Ich bin sicher, dass Ihr viele Fragen habt. Ihr werdet rechtzeitig alle Antworten erhalten.", completion = "Man stelle sich nur vor, dass dieser erbärmliche Astrale diese Essenzen wie Süßigkeiten an die Blutelfen verkaufen wollte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10272] = {title = "Ein viel versprechender Anfang", objective = "Sammelt 15 Netherdrachkineier und kehrt dann zu Tyri und Jorad im Sternensturz zurück.", description = "Wir sind hierhergekommen, um den Gerüchten über eine merkwürdige Drachenbrut, die vielleicht die Nachkommen von Todesschwinge selbst sein könnten, nachzugehen. Ganz offensichtlich handelt es sich nicht um gewöhnliche schwarze Drachen.\n\nWenn wir eine Gelegenheit hätten, ihre Eier zu untersuchen, könnten wir sicher mehr über sie herausfinden. Ihr Hass auf meinesgleichen sitzt so tief, dass ich nicht nahe genug herangehen kann, um die Eier selbst zu sammeln. Werdet Ihr mir helfen?", progress = "Konntet Ihr die Eier sammeln?", completion = "Die sollten ihren Zweck erfüllen, &lt;Name&gt;. Vielen Dank, dass Ihr uns geholfen habt.\n\nBevor wir weitermachen können gibt es jedoch noch etwas anders, worüber wir sprechen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10273] = {title = "Störende Ablenkung", objective = "Sprecht mit Windhändler Marid und lockt ihn von seinem Handelsposten fort. Vernichtet ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück.", description = "Euer früherer Arbeitgeber, Windhändler Marid, muss davon Wind bekommen haben, dass Ihr nun uns helft. Mithilfe meiner Projektion habe ich gesehen, wie seine Netherpirscher in die Gegend eingedrungen sind, um uns zu suchen.\n\nBis jetzt konnten wir ihnen entkommen, aber wir müssen uns mit Marid auseinandersetzen, bevor das Problem noch größer wird.\n\nWenn Ihr den richtigen Eindruck von Marid hattet, dann würde er alles tun, um den Nachschub seines Produkts zu sichern. Kehrt zu ihm zurück und sagt ihm, dass Ihr bereit seid, einen Handel einzugehen. Lockt ihn fort und tötet ihn.", progress = "Dieser Marid ist ein Dummkopf, oder sollte ich besser sagen war ein Dummkopf?", completion = "Jetzt, da dieser lästige Astrale beseitigt ist, können wir uns darauf konzentrieren, die Netherdrachen besser verstehen zu lernen. Ich konnte die Eier untersuchen und habe dabei einiges herausgefunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10274] = {title = "Den Sternensturz sichern", objective = "Benutzt die Herausforderung des blauen Drachenschwarms um Veraku am südlichen Ende des Sternensturzes zu provozieren. Besiegt ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück.", description = "Die Netherdrachen verfügen über dasselbe wilde Temperament wie ihre Vorfahren, die schwarzen Drachen. Etwas an ihnen ist jedoch vollkommen anders. Sie schlüpfen schnell und werden schnell reif, indem sie die fremdartigen Energien, die ihre Art zur Zerstörung Draenors getrieben hat, nutzen.\n\nEs gibt so Vieles, was ich noch über sie in Erfahrung bringen muss, aber ich glaube, dass die Mächte für meinen eigenen Schwarm von Vorteil sein könnten. Wenn wir den Anführer dieser Drachen, Veraku, als Zeichen unserer Dominanz vernichten könnten, könnten wir den Rest vielleicht so einschüchtern, dass sie sich uns unterwerfen.", progress = "Habt Ihr Veraku schon herausgefordert und getötet?", completion = "Gut gemacht, &lt;Name&gt;. Wirklich gut gemacht. Die Netherdrachkin werden zu Anfang keinen blauen Drachen in ihren Reihen akzeptieren, aber wenn ich meine Autorität beweise, werden sie sich fügen. Zerschlagen, isoliert und ohne Führung sind sie leichte Beute für bösartige Mächte. Wir müssen daher regelmäßig ein Auge auf sie werfen.", rewards = "Schimmernde AzurstiefelDrachenkronenschulterklappenGoldgliedrige ArmschienenBläuliche StahlstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10275] = {title = "Triangulationspunkt Zwei", objective = "Benutzt das Triangulationsgerät, um den Weg zum zweiten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Windhändler Tuluman auf Tulumans Landeplatz auf der anderen Seite der Brücke zu der Insel der Manaschmiede Ara im Nethersturm.", description = "Ich habe das Triangulationsgerät mit den Informationen des ersten Punkts neu eingestellt. Ihr könnt es genauso wie beim ersten Mal benutzen, um den zweiten Punkt zu bestimmen.\n\nAlles, was ich Euch sagen kann, ist, dass der zweite Punkt sich weit im Westen befindet.\n\nWenn Ihr ihn gefunden habt, sprecht mit Windhändler Tuluman, ein weiterer Agent des Nexusprinzen. Er steht als Waffenhändler getarnt in einem kleinen Handelsposten neben der Brücke, die zur Insel, auf der sich die Manaschmiede Ara befindet, führt.", progress = "Wollt Ihr kaufen oder verkaufen?", completion = "Sehr gut, in der Tat. Der Nexusprinz wird zufrieden sein.\n\nJetzt haben wir den zweiten Punkt, der uns den dritten und damit die Umgebung, in der sich der Kristall befindet, verraten wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10276] = {title = "Das volle Dreieck", objective = "Besorgt Euch den Kristall von Ata'mal und bringt ihn zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm.", description = "Mit den Daten vom ersten und zweiten Punkt kann ich sicher sagen, dass der Kristall sich auf den Ruinen von Farahlon im Nordosten befindet.\n\nUnglücklicherweise sagen die Daten, dass der Kristall sich bewegt, was bedeutet, dass er bereits gefunden wurde. Wahrscheinlich von der Brennenden Legion!\n\nFalls das tatsächlich so ist, empfehle ich Euch, ein paar Freunde mitzunehmen.\n\nTötet den Dämon, der den Kristall hat, und bringt ihn zu Nexusprinz Haramad.", progress = "Willkommen zurück, Freund. Wie geht es mit der Suche nach dem Kristall voran?", completion = "In meinen wildesten Träumen habe ich nicht gedacht, dass Ihr den Kristall tatsächlich beschaffen könnt!\n\nUnd Ihr gebt mir ihn sogar! Habt Ihr eine Ahnung, wie mächtig er ist?\n\nEure Selbstlosigkeit ist sehr inspirierend und unvergleichlich, &lt;Name&gt;! Ihr habt mir viel zum Nachdenken gegeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10277] = {title = "Die Höhlen der Zeit", objective = "Andormu in den Höhlen der Zeit möchte, dass Ihr der Bewahrerin der Zeit durch die Höhle folgt.", description = "Grüße, <Name>. Bitte folgt der Bewahrerin. Sie wird ein wenig... Licht in die Angelegenheit bringen.", progress = "Kehrt nicht zurück, bevor Ihr nicht wenigstens einen groben Eindruck davon bekommen habt, was hier vor sich geht.", completion = "Hoffentlich habt Ihr nun einen besseren Eindruck davon, was von Euch erwartet wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10278] = {title = "Sphärenrisse", objective = "Benutzt den instabilen Sphärenrissgenerator in den Sphärenfeldern. Sammelt 3 Einheiten Sphärennether von instabilen Leerwandlern und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück.", description = "Ich bin lange auf der Suche nach der Wahrheit der Leere durch die Scherbenwelt gereist. Jetzt bin ich alt und schwach. Ich sehe merkwürdige Dinge und bin nicht mehr ich selbst. Vielleicht wollt Ihr mir helfen?\n\nIch muss die Geheimnisse der Leerwandler aufdecken. Westlich des Expeditionsrüstlagers befindet sich ein Ort namens Sphärenfelder. Zeit und Raum sind dort sehr schwach, da die Felder nahe beim Abgrund liegen. Geht dorthin und benutzt den instabilen Sphärenrissgenerator. Er wird einen Sphärenriss erzeugen. Ihr müsst den Sphärennether von den Kreaturen, die durch ihn herauskommen, sammeln.", progress = "Habt Ihr meinen Apparat schon ausprobiert? Ich glaube, dass mein instabiler Sphärenrissgenerator so nahe am Abgrund funktionieren sollte.", completion = "Unglaublich. Ihr habt die Leere selbst berührt! &lt;Name&gt;, Ihr habt mein Lebenswerk gerettet. Aber es gibt noch mehr, was getan werden muss, und Ihr könnt mir helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10279] = {title = "Zum Hort des Meisters", objective = "Sprecht mit Andormu in den Höhlen der Zeit.", description = "Ah, <Name>. Wir haben Euch erwartet. Bitte erlaubt, dass einer meiner Brüder Euch zum Meister fliegt. Er wartet unten auf Euch...", progress = nil, completion = "Wir müssen uns auf die vor uns liegende Schlacht vorbereiten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10280] = {title = "Sonderlieferung nach Shattrath", objective = "Bringt den Kristall von Ata'mal zu A'dal auf der Terrasse des Lichts in Shattrath.", description = "Ich bin ein Astraler, der sein Wort hält, <Name>. Ihr habt mich wirklich inspiriert.\n\nIch werde Euch den Kristall von Ata'mal geben, damit Ihr ihn den Naaru überreicht. Da Euer Heldenmut dies möglich gemacht hat, soll Euch die Ehre zuteilwerden, ihn zu übergeben.\n\nIhr könnt meinen persönlichen Teleporter benutzen, um direkt nach Shattrath zu gelangen. Tretet einfach hindurch und er wird Euch dorthin bringen.\n\nGebt den Kristall dem Naaru namens A'dal auf der Terrasse des Lichts.", progress = "<Das musikalische Klingen der Naarusprache erfüllt Euren Geist.>\n\nIch spüre, dass Ihr einen Gegenstand von großer Macht bei Euch tragt, <Volk>. Was bringt Ihr mir?", completion = "Ihr habt mir den Gesang der Geister zurückgebracht! Prophet Velen hat den Kristall von Ata'mal zur Sicherheit bei seinem Volk zurückgelassen, bevor er auf seine schicksalsträchtige Mission zur Exodar ging.\n\nMerkwürdig, dass er nicht vorhergesehen hat, dass er in die Hände der Brennenden Legion fallen würde, wenn auch nur für kurze Zeit.\n\nOder vielleicht hat er das ja? Es könnte sein, dass er all dies vorhergesehen hat, und ihn dort ließ, damit Ihr ihn mir bringen könnt.\n\nIch spüre, dass dies die Wahrheit ist. Ihr seid ein großer Held unseres Volkes, &lt;Name&gt;.", rewards = "Hose der NaaruGamaschen von ShattrathA'dals BrustplatteDer folgende Zauber wird auf euch gewirkt:\n\nSegen von A'dal\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10281] = {title = "Formelle Vorstellung", objective = "Sucht Tyri am nördlichen Ende des Sternensturzes und sprecht mit ihr.", description = "Grüße, <Name>. Keine Angst, dies ist nur eine Projektion meiner gegenwärtigen Form. Es ist die einzige Möglichkeit, wie mein Gefährte und ich Wache halten können, ohne uns selbst zu offenbaren.\n\nDer Astrale, der Euch angesprochen hat, Marid, ist nur ein Schwindler, der sich als anständiger Händler ausgibt. Überlegt Euch daher, ob Ihr nicht lieber mit mir zusammenarbeiten wollt. Mein Ziel ist es, mehr über die ungewöhnlichen Drachkin des Sternensturzes herauszufinden. Trefft mich am nördlichen Ende des Sturzes, damit wir über die Details sprechen können.", progress = nil, completion = "Mein Name ist Tyrygosa von Malygos' Brut, aber nennt mich einfach Tyri. Mein Begleiter ist der Paladin Jorad Knüpp.\n\nDie Kunde von den merkwürdigen Drachkin hier verbreitet sich schnell, und ich fürchte, dass sehr viele kommen werden, um sie auszubeuten, bevor sie überhaupt ihre wahre Natur erkannt haben. Wir hoffen, dass wir mit Eurer Hilfe diese Kreaturen kennenlernen können, bevor andere von ihnen erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10282] = {title = "Das Alte Hügelland", objective = "Andormu in den Höhlen der Zeit bittet Euch, ins Alte Hügelland zu reisen und mit Erozion zu sprechen.", description = "Im Westen findet Ihr die Pfade der Zeit in das Hügelland der Vergangenheit - vor 7 Jahren um genau zu sein.\n\nDie Streitmächte kämpfen gegen den Kriegshäuptling der Horde, Thrall, um ihn davon abzuhalten, aus der Burg Durnholde zu fliehen.\n\nWenn es Thrall nicht gelingt zu fliehen, wird die Welt, wie Ihr sie jetzt kennt, aufhören zu existieren.\n\nRuft eine Gruppe von Abenteurern zusammen und reist auf dem Pfad der Zeit ins Alte Hügelland. Zwei unserer Agenten warten dort auf Euch.\n\nSprecht mit Erozion auf der anderen Seite.", progress = nil, completion = "Unsere schlimmsten Befürchtungen könnten bald wahr werden. Hinter dieser Störung der Zeitlinien steht ein neuer Drachenschwarm, der als die Ewigen bekannt ist. Wir wissen nicht, woher sie kommen und warum sie die Pfade der Zeit zerstören.\n\nIn dieser Zeitfalte haben sie Taretha Foxton, die Tochter von Tammis Foxton, der rechten Hand von Aedelas Schwarzmoor, Herrscher von Durnholde und Aufseher aller Internierungslager in Azeroth, gekidnappt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10283] = {title = "Tarethas Ablenkungsmanöver", objective = "Reist zur Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.\n\nSprecht mit Thrall im Kellergefängnis der Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.", description = "Taretha spielte eine entscheidende Rolle bei Thralls Überleben und Erziehung und prägte Thralls Leben maßgeblich.\n\nEs war Taretha, die die Wachen von Durnholde ablenkte, damit Thrall entkommen konnte.\n\nJetzt haben die Ewigen Taretha gefangen und halten sie in Tarrens Mühle fest. Ohne unsere Einmischung wird das Ablenkungsmanöver niemals stattfinden. Ihr müsst den Brandsatz, den ich Euch gegeben habe, nehmen und die Internierungsbaracken in Durnholde anzünden. Wenn Ihr das erledigt habt, sprecht mit dem jungen Thrall im Kellergefängnis der Burg.", progress = "Wer seid Ihr?", completion = "Ihr seid Freunde von Taretha? Das ist also ihr neuer Plan? Nun gut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10284] = {title = "Flucht aus Durnholde", objective = "Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.\n\nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.", description = "Ihr schaut mich an und seht nur einen Jungen, aber tief in meinem Herz und meiner Seele halte ich meine Träume versteckt. Ich habe Pläne für mein Volk, Fremder. Eines Tages werden sie ihre Unterdrücker überwältigen und in Einheit auferstehen. Sie werden ihre Fesseln abwerfen und aus diesem Aufstand soll die orcische Horde entstehen.\n\nIch verspreche Euch, Fremder, dass ich Euch suchen werde, wenn wir heil hier herauskommen und ich die Möglichkeiten habe, Eure selbstlose Tat zu belohnen... Ich werde Euch finden.\n\n<Thrall nickt.>\n\nWir fliehen, wenn Ihr bereit seid.", progress = "<Erozion nickt.>", completion = "Ihr habt eine großartig Aufgabe erledigt, &lt;Name&gt;. Nun müssen die Erinnerungen des jungen Kriegshäuptlings an diese Ereignisse wieder so verändert werden, wie sie einst waren... Andormu erwartet Euch im Hort des Meisters.", rewards = "Mantelung des KriegshäuptlingsBerührung des SturmsSüderstader SchuheVerteidigergurt von Tarrens MühleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10285] = {title = "Rückkehr zu Andormu", objective = "Kehrt zu dem jungen Andormu in den Höhlen der Zeit in Tanaris zurück.", description = "Diese Zeitachse wurde wiederhergestellt und der Angriff des ewigen Drachenschwarms auf das Hügelland vorerst abgewendet.\n\nKehrt sofort zu Andormu zurück. Er wartet im Hort des Meisters auf Eure Ankunft.", progress = nil, completion = "Bitte nehmt ein Geschenk des Bronzeschwarzms an. Diese Gegenstände werden Euch auf Euren Reisen durch die Zeit unterstützen.", rewards = "Mantelung des KriegshäuptlingsBerührung des SturmsSüderstader SchuheVerteidigergurt von Tarrens MühleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10286] = {title = "Arelions Geheimnis", objective = "Magistrix Carinda möchte, dass Ihr Magister Aledis befragt. Aledis wurde zuletzt auf einer Reise von der Falkenwacht zu den Zangarmarschen gesehen.", description = "Arelions Tagebuch enthält überhaupt keine wissenschaftlichen Studien. Er beschreibt seine Eskapaden mit einer jungen Blutelfe! Wie konnte ich nur so dumm sein?\n\nUnglücklicherweise nennt das Tagebuch den Namen des Flittchens nicht. Aledis, ein Kollege von Arelion, war sein bester Freund und Vertrauter. Befragt ihn und findet heraus, mit wem er eine Affäre hatte.\n\nIch habe gesehen, wie Aledis sich vor Kurzem aus der Falkenwacht in Richtung Zangarmarschen aufgemacht hat. Folgt der Straße nach Norden aus dem Dorf heraus. Sie biegt nach einer Weile nach Westen in Richtung Zangarmarschen ab.", progress = nil, completion = "Ich werde reden, &lt;Klasse&gt;. Nehmt die Waffe runter, ich will nicht noch mehr Ärger haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10287] = {title = "Die enttarnte Geliebte", objective = "Kehrt zu Magistrix Carinda in die Falkenwacht auf der Höllenfeuerhalbinsel zurück.", description = "Ich bin Arelions Freund, aber ich werde für ihn nicht die Prügel meines Lebens einstecken. Seine Geliebte ist Viera Sonnenwisper.\n\nSagt das seinem Drachen von Ehefrau. Was will sie schon dagegen tun?", progress = nil, completion = "Viera Sonnenwisper? Diese widerliche kleine Göre.\n\nIch werde ihr zeigen, dass man mit mir keine Spielchen treibt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10288] = {title = "Ankunft in der Scherbenwelt", objective = "Kommandant Duron beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Durons Bericht zu Flugmeister Amish Wildhammer bringt.", description = "Ich möchte, dass Ihr mit Amish Wildhammer sprecht. Ihr findet ihn etwa 30 Schritt südlich von hier. Nehmt den ersten Flug zur Ehrenfeste. Wenn Ihr dort angekommen seid, werdet Ihr von Marschall Isildor begrüßt werden. Gebt ihm diese Empfehlung, in der ich notiert habe, wo Ihr meiner Meinung nach am hilfreichsten sein könntet.\n\nIch habe Euch einen Befehl erteilt, Soldat, nun fort mit Euch! Und auch wenn Ihr darauf brennt, uns im Kampf gegen den Feind hier zu unterstützen, dürft Ihr keine Zeit verschwenden. Die Ehrenfeste braucht Euch sogar noch mehr als wir.", progress = "Ich habe gehört, wie Ihr mit Duron gesprochen habt. Ihr müsst einen wichtigen Auftrag haben!", completion = "Berichte für die Ehrenfeste? Kein Problem, einer meiner Greifen wird Euch schnell und sicher dorthin bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10289] = {title = "Reise nach Thrallmar", objective = "Nehmt Vlagga Freyfeders Windreiter nach Thrallmar. Bringt Orions Bericht zu General Krakork.", description = "Wenn Ihr bereit seid, rufe ich einen Flügeldrachen, der Euch nach Thrallmar bringt. Wenn Ihr angekommen seid, bringt Orions Bericht zu General Krakork.\n\nLok'tar ogar, <Name> - Viel Glück.", progress = "Ein Bericht von Orion? Gebt ihn mir, schnell!\n\n<Stirnrunzelnd überfliegt General Krakork den zerknitterten Brief.>\n\nVerdammt, es ist genau so, wie wir es befürchtet haben. Orion und seine Krieger können jeden Moment überrannt werden!", completion = "Ich werde alle Truppen, die ich entbehren kann, zu Orion beim Dunklen Portal schicken. Die Legion wird den Schlachtruf der Horde nicht so bald vergessen! Ihr, &lt;Name&gt;, habt Thrallmar heute einen großen Dienst erwiesen. Ich glaube, Ihr könnt uns hier eine große Hilfe sein. Natürlich nur, wenn Ihr klug genug seid, um zu überleben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10290] = {title = "Auf der Suche nach Farahlit", objective = "Sammelt 4 Stück Rohfarahlit und kehrt dann zu Zuben Elgenubi in der Sturmsäule zurück.", description = "Im Nordosten gibt es eine Region, die Netherstein genannt wird. Früher war sie unter einem fruchtbaren und grünen Land verborgen. Die neu gefundenen Kristallformationen haben uns ein Mineral gezeigt, das wir zur Ehre der früheren Identität des Landes Farahlit genannt haben.\n\nDie kleine Menge Farahlit, die wir bis jetzt abgebaut haben, erfreut sich jetzt schon großer Beliebtheit bei unseren Kunden. Das hochwertigste Mineral stammt jedoch nicht von den Ablagerungen, sondern von den Riesen, die um den Netherstein herum leben. Ich biete Euch einen Teil des Gewinns an, wenn Ihr mir helft, hochwertiges Farahlit zu besorgen.", progress = "Ich bin mir bewusst, dass das Sammeln von Farahlit sehr gefährlich ist, aber die Möglichkeiten sind gewaltig. Ein Händler, der nicht bereit ist, Risiken auf sich zu nehmen, kann seine Türen gleich schließen und sich den Ärger ersparen.", completion = "Ah ja, genau die Qualität, die ich mir erhofft habe. Wenn wir genügend Nachschub von den Riesen bekommen, brauchen wir die Kristalle nicht mehr abbauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10291] = {title = "Bericht an Nazgrel", objective = "General Krakork in Thrallmar möchte, dass Ihr mit Nazgrel sprecht.", description = "Auch wenn unsere Krieger keine ebenbürtigen Gegner haben, ist unsere Stellung in diesem Ödland immer noch angreifbar. Meldet Euch bei Nazgrel in der Kaserne. Er braucht gute Agenten... wie Euch. Wenn wir unsere Stellung hier nicht halten können, sind wir für niemanden eine Hilfe! Geht jetzt.", progress = nil, completion = "Wir haben schon viele tapfere Krieger an dieses verfluchte Land verloren. Ich habe kein Interesse daran, noch mehr ungeprüfte Rekruten in das Massaker zu schicken.\n\n&lt;Nazgrel schaut Euch durch seine zottige Wolfsmaske streng an.&gt;\n\nAber wenn General Krakork Euch zu mir geschickt hat, muss an Euch ja etwas dran sein. Was sagt Ihr also, &lt;Name&gt;? Werdet Ihr dem Kriegshäuptling mit Ehre dienen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10292] = {title = "Mehr Energie!", objective = "Zuben Elgenubi möchte, dass Ihr 8 Schusswaffen der Legion besorgt und sie zur Sturmsäule bringt.", description = "Ein wertvolles Gut in kleinen Häppchen zu sammeln hat das malerische Flair eines Familienunternehmens, aber auf dem heutigen Markt ist es einfach nicht konkurrenzfähig.\n\nNein, wir brauchen einen Weg, Farahlit in Massenproduktion zu beschaffen! Dann wäre der Hauptanteil des Marktes unser!\n\nIch habe eine Idee, aber sie erfordert eine mächtige, konzentrierte Energiequelle. Solch eine Energiequelle kann man nur an einem Ort finden. Geht zu den Lagern der Legion nördlich von hier und besorgt Euch ein paar ihrer Schusswaffen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10293] = {title = "Die Kristallader anzapfen", objective = "Zuben Elgenubi in der Sturmsäule möchte, dass Ihr einen Farahlitkern besorgt.", description = "Jetzt, da wir ein solides Grundprodukt haben, benötigen wir etwas von höherer Qualität. Das Farahlit, das wir bisher gesammelt haben, ist zwar ganz nett, aber es gibt noch besseres da draußen.\n\nWir müssen eine Probe direkt von Felsnarbe, dem Patriarchen der Riesen von Farahlon, besorgen! Ihr solltet ihn bei den anderen Riesen in der Gegend um den Nethersteine herum finden können. Aus seinem Rücken ragen große Farahlitstücke heraus; genau was wir brauchen. Tötet den Riesen und sammelt einen Farahlitkern von ihm.", progress = "Ihr seid immer noch am Leben, was bedeutet, dass Ihr entweder den Kern besorgt oder Eure Meinung geändert habt. Was davon stimmt?", completion = "Gut gemacht! Ich kann kaum abwarten, es auszuprobieren.", rewards = "Umhang verwobener EnergieAuf Euch wartet eine dieser Belohnungen:\n\nHimmlischer JuwelenringLeuchtrankenkette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10294] = {title = "Der Leerengrat", objective = "Geht zum Leerengrat und tötet die Kreaturen, die Ihr dort findet. Sammelt 40 Seelensplitter des Leerengrats und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück.", description = "Wir müssen meinen Sphärenrissgenerator verbessern. Ihr müsst ihn zum Leerengrat bringen. Geht von hier aus nach Osten, um die verdorbene Festung Zeth'Gor herum. Im Osten hinter Zeth'Gor befindet sich ein kleiner Pass durch die Berge. Hinter diesem Pass findet Ihr den Leerengrat, einen schrecklichen Ort direkt am Abgrund.\n\nIhr müsst die Wandler, die Ihr dort findet, töten und mir Splitter ihrer Seele bringen. Mit ihrer Macht werden wir den Sphärenrissgenerator verbessern und ein Portal in die jenseitige Dimension öffnen, das nicht mehr geschlossen werden kann.", progress = "Habt Ihr es schon getan? Habt Ihr die Splitter?", completion = "Ausgezeichnet. Der verbesserte Sphärenrissgenerator ist fast fertig. Es gibt nur noch einen letzten Bestandteil, den wir brauchen. Bald können wir einen stabilen Sphärenriss öffnen, den wir in den kommenden Jahren untersuchen können.\n\nWer weiß, welche fremdartigen Kreaturen durch ihn hindurchkommen werden? Stellt Euch nur vor, &lt;Name&gt;, die Macht, die ein solches Wissen mit sich brächte, wäre unermesslich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10295] = {title = "Aus dem Abgrund", objective = "Tötet Galaxis und sammelt seinen Seelensplitter. Bringt den Splitter zu Ogath dem Verrückten im Rückenbrecherposten.", description = "Mein Sphärenrissgenerator ist fertig. Ihr könnt damit jetzt einen wahren Prinzen der Leere rufen, eine Kreatur, deren Seelensplitter uns deutlich mehr darüber verraten wird, was dahinter liegt.\n\nGeht nach Süden in den Leerengrat und benutzt meinen Sphärenrissgenerator in der Nähe der Steine der Leere. Haltet nach einer Gruppe von Kristallen am Ende des Abgrunds Ausschau. Ein riesiger Sphärenriss wird sich auftun, aus dem dann sicher der Baron der Leere Galaxis entsteigen wird.\n\nZerstört diese Kreatur und bringt mir seinen Seelensplitter.", progress = "Habt Ihr den Baron der Leere Galaxis schon vernichtet?", completion = "Ihr habt mein Lebenswerk gerettet, &lt;Name&gt;.\n\nSie haben mich wahnsinnig genannt, mich ausgelacht und gedacht, meine Besessenheit auf den Leerengrat und die Sphärenfelder hätte mich krank gemacht. Mit diesem Seelensplitter kann ich das Geheimnis der Leerwandler lüften. Ich werde die Macht über den Abgrund beherrschen!", rewards = "Rute des LeerrufersAbyssisches TuchAuf Euch wartet eine dieser Belohnungen:\n\nRing der Verbannung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10296] = {title = "Der Schwarze Morast", objective = "Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa'at.", description = "Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.\n\nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa'at.", progress = nil, completion = "Wenn die Orcs nie nach Azeroth gelangen, wird die Allianz sich nie formieren. Schließlich wird ein Bürgerkrieg ausbrechen, der die menschlichen Königreiche noch weiter schwächen wird.\n\nLetzten Endes wird die Brennende Legion in Azeroth einmarschieren, und da es keine Verteidiger gibt, das Land völlig zerstören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10297] = {title = "Die Öffnung des Dunklen Portals", objective = "Sa'at im Schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat.\n\nKehrt zu Sa'at zurück, wenn Ihr erfolgreich wart.", description = "Hinter diesem Pfad der Zeit, im Herzen des Schwarzen Morasts, arbeitet Medivh verbissen an der Öffnung des Dunklen Portals.\n\nÜberall im Morast werden sich Zeitlöcher öffnen, aus denen die Ewigen herausströmen werden mit dem Ziel, Medivhs Schilde und schließlich auch Medivh selbst zu vernichten.\n\nTötet die Lords des Zeitlochs und ihre Anführer, bis Medivh erfolgreich war.", progress = "Ihr dürft das Chronosignal nur einmal pro Zeitfalte benutzen.", completion = "Ihr habt Eure Arbeit gut gemacht, &lt;Name&gt;. Das Kind, Andormu, möchte erneut mit Euch sprechen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des WächtersBewahrerring der FrömmigkeitEdelstein der ZeitkrümmungAndormus Träne\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10298] = {title = "Held des Schwarms", objective = "Kehrt zum Kind, Andormu, in den Höhlen der Zeit in Tanaris zurück.", description = "Kehrt zum Kind, Andormu, zurück, <Name>. Er erwartet Euch außerhalb dieser Zeitfalte im Hort des Meisters.\n\nIch höre Flügelschlagen. Die Wächter der Sande interessieren sich für Eure Fähigkeiten. Vielleicht möchten auch sie mit Euch sprechen.", progress = nil, completion = "Ihr habt die Gegenwart und die Zukunft dieser Welt ein weiteres Mal gerettet, &lt;Name&gt;. Bitte nehmt diese Gegenstände als Belohnung für Eure Erfolge.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des WächtersBewahrerring der FrömmigkeitEdelstein der ZeitkrümmungAndormus Träne\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10299] = {title = "Manaschmiede B'naar abschalten", objective = "Anachoret Karja möchte, dass Ihr in die Manaschmiede B'naar geht und einen Zugangskristall von Vorarbeiter Theredis besorgt. Benutzt ihn bei der Steuerkonsole von B'naar, um sie abzuschalten und meldet Euch danach bei Anachoret Karja zurück.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wir können die Manaschmieden nicht mit Gewalt abschalten, da wir sonst eine Explosion auslösen könnten, die die Scherbenwelt bis in den Kern erschüttern würde.\n\nLaut Eurer Abschrift gibt es einen Notschalter, der die Technologie dauerhaft abschaltet - ein Sicherheitsmechanismus, der bei der Technologie der Naaru Standard ist.\n\nFür diesen Vorgang braucht Ihr einen Kristall, der Euch die Kommunikation mit der Konsole ermöglicht. Dieser Zugangskristall befindet sich unseren Informationen zufolge im Besitz eines Vorarbeiters namens Theredis.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, <Name>?", completion = "Das Licht ist Euch wohl gesonnen, &lt;Name&gt;. Wir haben alle für Euren Erfolg gebetet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10300] = {title = "Den Stab wiederherstellen", objective = "Besorgt 4 fehlerlose Kristallsplitter von den Geistern in den Ruinen von Enkaat und bringt sie zu Ravandwyr in Area 52.", description = "<Ravandwyr untersucht den Stab und bemerkt, dass das Kopfstück fehlt.>\n\nDas ist einfach barbarisch! Ekkorash muss das kristallene Kopfstück abgenommen haben, um es mit einem anderen Schmuckstück zu verwenden, und hat gar nicht gemerkt, dass es zum Rest des Stabs dazugehört!\n\nSolange er nicht komplett ist, ist die Macht des Stabs stark verringert. Ich könnte ihn jedoch mit einem geeigneten Draeneikristall reparieren. Ich habe gehört, wie die Goblins von den Kristallen der Geister in den Ruinen von Enkaat im Norden gesprochen haben.", progress = "Habt Ihr schon ein paar geeignete Kristalle für ein neues Kopfstück des Stabs gefunden?", completion = "&lt;Ravandwyr untersucht die Kristalle genau und wählt dann einen aus.&gt;\n\nDieser Kristall sollte funktionieren. Ich werde den Sockel des Stabs umformen, damit das neue Kopfstück passt.\n\nErzmagier Vargoth wird enttäuscht sein, wenn er ihn sieht, aber ich bin bereit, die Enttäuschung meines Meisters in Kauf zu nehmen, wenn er nur endlich wieder frei ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10301] = {title = "Das Kompendium öffnen", objective = "Besorgt Euch das heliotrope Oculus von Zauberhäscherin Marathelle im Sonnenzornposten.", description = "Auch wenn ich froh bin, dass ich das meiste von Krasus' Kompendium zurück habe, ist es ohne das heliotrope Oculus nutzlos. Seht Ihr, Krasus war sich der unermesslichen Macht des Buchs bewusst und hat Vorkehrungen getroffen, damit es vor gierigen Blicken geschützt bleibt.\n\nNur ein Magier mit großem Wissen kann dem Kompendium mithilfe des Oculus' seine Geheimnisse entlocken.\n\nWährend Kael'thas' Angriff hat einer seiner Leutnants, Zauberhäscherin Marathelle, das Octulus aus dem Turm gestohlen und es zum Sonnenzornposten gebracht. Sie hält es sicher für ein hübsches kleines Schmuckstück.", progress = "Habt Ihr das Oculus besorgt?", completion = "Ausgezeichnet, &lt;Name&gt;. Jetzt haben wir fast alles, was wir benötigen, um Kael'thas' Magie zu durchbrechen.\n\nUnd wenn die Blutelfen unter dem Verlust ihres Kommandanten hier leiden, dann umso besser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10302] = {title = "Unberechenbare Mutanten", objective = "Tötet 8 unberechenbare Mutanten und kehrt dann zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück.", description = "Die verstrahlten Kraftkerne der Exodar haben der Umwelt hier verheerenden Schaden zugefügt. Die deutlichste Auswirkung ist das Auftauchen merkwürdiger Kreaturen, die anscheinend in ihrer Nähe wie Pilze aus dem Boden schießen.\n\nVielleicht gibt es etwas, was wir für sie tun können, aber im Augenblick sind sie einfach zu viele für uns.\n\nIch möchte, dass Ihr losgeht und ihre Zahl reduziert. Vielleicht fällt mir danach eine andere Lösung ein.", progress = "Ich arbeite an einer Lösung, die für die merkwürdigen Kreaturen große Wirkung haben sollte. Ich brauche nur mehr Zeit.", completion = "Ihr seid fertig? Das sind gute Nachrichten. Hoffentlich finden wir einen Weg, bei dem wir diese mutierten Kreaturen nicht töten müssen.\n\nIch glaube, ich habe einen Plan entwickelt, der uns eine alternative Lösungsmöglichkeit für unser Problem bietet, aber ich werde Eure Hilfe brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10303] = {title = "Die Blutelfen", objective = "Tötet 10 Blutelfenspäher und kehrt dann zu Tolaan im Schattenkamm im Am'mental zurück.", description = "Ihr müsst... die Bedrohung durch die Blutelfen... auslöschen. Findet heraus... was sie... vorhaben!\n\nSie sind auf dem... Kamm hinter mir.", progress = nil, completion = "Diese Blutelfen wollen uns alle töten. Wie können wir sie davon abhalten?", rewards = "Verwitterte PanzertunikaVerwitterte LederwesteVerwitterte StoffrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10304] = {title = "Verteidiger Aldar", objective = "Sprecht mit Verteidiger Aldar bei der Absturzstelle im Am'mental.", description = "Mit Eurer Hilfe konnten wir schneller, als wir gehofft hatten, eine Lösung für unser Problem finden.\n\nIch habe keine weitere Arbeit für Euch, meine Lehrlinge schaffen den Rest alleine.\n\nIhr solltet mit Verteidiger Aldar auf der anderen Seite des Schiffs sprechen.", progress = nil, completion = "&lt;Name&gt;, richtig? Ich habe viel Gutes über Euch und die Arbeit, die Ihr in der kurzen Zeit, in der Ihr hier wart, geleistet habt, gehört.\n\nWir sind auf Eure Hilfe angewiesen, um die Dinge wieder zu normalisieren. Ich bin mir sicher, dass auch Zhanaa da drüben Eure Hilfe brauchen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10305] = {title = "Bannzauberin Belmara", objective = "Sucht die Wohnung von Bannzauberin Belmara in der Zaubergasse und bringt das Buch zurück auf seinen Platz im Bücherregal. Sprecht danach mit Hüter Dierwert in Kirin'Var.", description = "Dieser abgenutzte, dicke Foliant ist kein Zauberbuch, wie Ihr es vielleicht von einem Magier der Kirin Tor erwartet hättet. Die Seiten dieses Bandes sind voll von handgeschriebenen Geschichten mit bunten Zeichnungen.\n\nDer Foliant scheint viel älter zu sein, als seine Besitzerin und stammt vielleicht aus ihrem Familienerbe. Möglicherweise war das starke Band zu diesem Buch das, was Belmaras Geist an die Ruinen von Kirin'Var gefesselt hat. Wenn Ihr es auf seinen rechten Platz im Bücherregal zurückbringt, kommt ihr Geist vielleicht zur Ruhe.", progress = "Was habt Ihr gefunden, <Name>?", completion = "Ja, ich habe davon gehört, dass Bannzauberin Belmara ein altes Buch mit Geschichten hatte, aber ich wusste nicht, dass sie es mit in die Scherbenwelt gebracht hatte. Ich bin mir sicher, dass ihr Geist nun, da Ihr es gefunden und zurückgebracht habt, ruhen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10306] = {title = "Beschwörer Luminrath", objective = "Sucht die Wohnung von Beschwörer Luminrath in der Zaubergasse und bringt den Mantel zurück in seine Kommode. Sprecht danach mit Hüter Dierwert in Kirin'Var.", description = "Der Mantel, der ohne Zweifel von Hochelfen geschneidert wurde, ist sogar für die Verhältnisse der Kirin Tor reich verziert. Die Symbole und Zeichen ergeben für Euch keinen Sinn, aber sie scheinen die Kleidung eindeutig mit Magie zu verstärken.\n\nVielleicht bindet dieser Gegenstand seinen früheren Besitzer an diese Existenzebene. Wenn das so ist, würde die Verbindung des Geistes mit dieser Welt vielleicht zerbrechen, wenn Ihr den Mantel zurück in die Kommode in Beschwörer Luminraths Wohnung bringt.", progress = nil, completion = "Wir haben immer Scherze darüber gemacht, dass Luminrath zu allem diesen Mantel tragen würde. Für ihn passte Rot genauso gut zu Weiß wie zu Schwarz, Violett, Blau, Gelb, Orange und Grün. Er hätte niemals zwei Tage hintereinander die selbe Robe getragen, aber der Mantel war immer dabei...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10307] = {title = "Cohlien Frostwirker", objective = "Sucht die Wohnung von Cohlien Frostwirker in der Zaubergasse und bringt die Kappe zurück in seine Schließkiste. Sprecht danach mit Hüter Dierwert in Kirin'Var.", description = "Während Ihr die Kappe betrachtet, fragt Ihr Euch, ob ein Magier der Kirin Tor überhaupt so einen Hut besitzen würde. Der Zustand der Kappe lässt darauf schließen, dass der Gnom das Haus nie ohne sie verlassen hätte.\n\nIhr probiert den Hut kurz auf und bemerkt keine magischen Eigenschaften außer einem schwachen Zwang zu tanzen.\n\nVielleicht bindet dieser geschätzte Besitz den Geist des toten Magiers an das Dorf. Wenn Ihr die Kappe zurück in die Schließkiste in Cohliens Wohnung legen würdet, könntet Ihr den Geist des Magiers vielleicht befreien.", progress = nil, completion = "&lt;Der Hüter lächelt, als Ihr Cohliens Name erwähnt.&gt;\n\nIhr habt absolut Recht mit der Kappe. Er trug sie die ganze Zeit und lies sie nicht aus den Augen.\n\nEin paar Mal hat sich einer seiner Kollegen die Kappe \"ausgeliehen\" und sie zum Scherz versteckt. Ich brauche nicht zu erwähnen, dass die Androhung eines Frostblitzes von Cohlien ihn schnell zum Umdenken bewegt hat.\n\nIch werde den kleinen Cohlien vermissen. Er war sehr beliebt bei den Elfendamen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10308] = {title = "Noch ein Hügel voller Astraler", objective = "Das Konsortium ist sehr daran interessiert, alle Rebellen der Zaxxis beim Hügel im Süden auszulöschen.\n\n<Klasse>, wenn Ihr Euch bei uns noch beliebter machen wollt, dann geht zurück und besorgt noch mehr ihrer Insignien.", description = nil, progress = "Das Konsortium ist sehr daran interessiert, alle Rebellen der Zaxxis beim Hügel im Süden auszulöschen.\n\n<Klasse>, wenn Ihr Euch bei uns noch beliebter machen wollt, dann geht zurück und besorgt noch mehr ihrer Insignien.", completion = "Verräter, alle!\n\nGute Arbeit, &lt;Klasse&gt;! Wenn Ihr nochmals dort hinunter gehen solltet, bin ich immer noch auf der Suche nach weiteren Insignien für meine Sammlung.", rewards = nil}
MultiLanguageQuestData['de'][10309] = {title = "Teufelshäscher mit Herz", objective = "Besorgt das Herz des Teufelshäschers und bringt es zu N. D. Mieskamp beim Hügel im Nethersturm.", description = "Seht Ihr den kaputten Teufelshäscher im Süden? Ist er nicht schön?\n\nIch möchte sein Herz!\n\nWas? Natürlich hat er ein Herz... wer hat denn keins?\n\n<N.D. sieht für einen kurzen Moment beleidigt aus.>\n\nGeht dort hinüber, öffnet ihn und bringt mir, was ich möchte, dann bekommt Ihr auch einen schönen Finderlohn.\n\nOh, und ich würde an Eurer Stelle ein oder zwei Freunde mitnehmen. Diese Astralen der Zaxxis sind eine ziemlich verschlagene Truppe!\n\nNehmt diesen Teufelsschocker, um seinem Herz einen Stromimpuls zu geben, wenn Ihr bereit seid, loszulegen.", progress = "Meine Augen müssen von der ganzen Netherstrahlung hier schlechter werden. Habt Ihr schon das Herz des Teufelshäschers?", completion = "Wow, schaut Euch das an... ein schlagendes Teufelshäscherherz! Nun, es schlägt nicht wirklich, aber Ihr wisst schon, was ich meine.\n\nIch kann es kaum abwarten, dieses Ding zu benutzen. Oder ich verkaufe es. Ich kenne ein paar Depp... äh Kunden, die daran interessiert sein könnten.\n\nHier, Ihr habt Euch die Belohnung verdient!", rewards = "HügelkampfgamaschenAugenklappe des SphärenräubersZusammengeflickte BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10310] = {title = "Sabotage am Warptor!", objective = "Begleitet Drijya zum Warptor beim Invasionspunkt: Zerstörer und sorgt für seine Sicherheit, während er das Tor sabotiert. Sprecht danach mit Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Jetzt, da die Brennende Legion sich auf dem Trümmerfeld der Teufelshäscher in der Nähe befindet, müssen wir alles tun, um den Zuwachs der Dämonen in dieser Gegend aufzuhalten.\n\nSie haben ein Warptor im Süden in einer Gegend, die sie bezeichnenderweise Invasionspunkt: Zerstörer genannt haben.\n\nIch möchte, dass Ihr mit mir dorthin geht und mich beschützt, während ich das Tor sabotiere.\n\nGeht danach zum Mittelreichposten in der Biokuppel Mittelreich im Norden und meldet Gahruj unseren Erfolg.\n\nWir werden ein oder zwei Freunde von Euch für diesen Auftrag brauchen.", progress = nil, completion = "Das sind ausgezeichnete Neuigkeiten, mein Freund!\n\nIhr und Drijya haben uns einen großen Dienst erweisen. Jetzt, da das Warptor außer Gefecht ist, können die Dämonen in der Nähe keine Verstärkung mehr holen.\n\nBitte erlaubt mir, Euch in der Art des Konsortiums zu belohnen.", rewards = "Konsortiumroben des KampferfahrenenAugenklappe des NethersturmsGamaschen des MittelreichsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10311] = {title = "Drijya braucht Eure Hilfe", objective = "Sprecht mit Drijya in der Nähe des Invasionspunkts: Zerstörer im Nethersturm.", description = "<Klasse>, schön ein hilfreiches Gesicht hier zu sehen.\n\nDie Brennende Legion bei dem Teufelshäscherhügel hier in der Nähe wird immer mutiger, und ich mache mir Sorgen um unsere Sicherheit. Die Dämonen erhalten immer mehr Verstärkung aus dem Invasionspunkt: Zerstörer im Süden.\n\nMein Gefährte, Drijya, hat sich dorthin aufgemacht, um die Gegend zu erkunden und zu schauen, ob er etwas gegen die Warptore der Legion ausrichten kann.\n\nBitte findet ihn und helft ihm, wo Ihr könnt.", progress = nil, completion = "Ich hoffe, dass Gahruj Euch hierher geschickt hat, um mir bei meinem Auftrag zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10312] = {title = "Die Annalen von Kirin'Var", objective = "Besorgt die Annalen von Kirin'Var aus dem Rathaus von Kirin'Var und bringt es zu Hüter Dierwert.", description = "Die Geister zum Schweigen zu bringen hat leider nichts an Ihrer Aggressivität geändert. Die bösartigen Geister, die Ihr vernichtet habt, tauchen nun wieder in den Straßen des Dorfs auf.\n\nWir müssen herausfinden, was dahinter steckt. Die Zerstörung Kirin'Vars war nur der Anfang, sonst hätten sich die Geister schon längst beruhigt.\n\nIm Rathaus im Süden von Kirin'Var gibt es ein Stadtregister, in dem alle Einwohner eingetragen sind. Ich habe gehört, dass Kampfmagier Dathric es zuletzt hatte. Vielleicht trägt sein Geist es noch mit sich herum.", progress = "Konntet Ihr das Stadtregister finden?", completion = "&lt;Hüter Dierwert nimmt Euch das Buch ab und blättert es durch.&gt;\n\nHmm...\n\nSieht aus, als hätte ich Recht gehabt. Es scheint ein Muster zu geben.\n\nDie aggressivsten und gefährlichsten Geister stimmen mit den mächtigsten und hochrangigsten Kirin Tor, die in dem Dorf gelebt haben, überein. Dagegen scheint man die Dorfleute und Händler übersehen zu haben. Was könnte das bedeuten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10313] = {title = "Warpenergien messen", objective = "Exarch Orelis in Area 52 möchte, dass Ihr die Warpmesskugel zur Manaschmiede B'naar bringt und sie in der Nähe der vier Rohrleitungen benutzt.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eurer Ehre bei den Sehern.", description = "Wenn uns unser Instinkt nicht täuscht und diese Manaschmieden die Technologie der Festung der Stürme nutzen, könnte die ganze Scherbenwelt in großer Gefahr schweben.\n\nDie Energieauflademechanismen der Festung der Stürme waren niemals dafür gedacht, sie so nahe an bewohntem Land zu benutzen. Die Warpenergien könnten dieses Land zerstören, sogar wenn sie durch Kaels' Rohrleitungen fließen.\n\nBringt diese Kugel zur Manaschmiede B'naar. Sie ist so eingestellt, dass sie die Warpenergien messen kann. Benutzt sie an der Stelle, an der die Rohrleitungen in die Erde führen.", progress = "Habt Ihr die Messungen, um die ich Euch gebeten habe, durchgeführt, <Name>?", completion = "Das sind schlimme Nachrichten, &lt;Name&gt;. Die Warpenergien, die aus den Rohren herausströmen, sind gefährlich hoch.\n\nWir müssen einen Weg finden, um die Manaschmieden abzuschalten, oder der kleine Rest, der noch von der Scherbenwelt übrig ist, wird in tausend Stücke gesprengt.", rewards = "Energieerfüllter HelmWarpgeschützte HalsbergeAxt des WiderhallsHandschuhe des WarpwirkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10314] = {title = "Ein hartnäckiger Verdacht", objective = "Sammelt 10 abscheuliche Überreste von den wahnsinnigen Geistern auf dem Kapellenhof in Kirin'Var und bringt sie zu Hüter Dierwert.", description = "Das merkwürdige magische Gerät ähnelt nichts, was Ihr je zuvor gesehen habt. Es wurde mit Sicherheit nicht von Blutelfen hergestellt.\n\nAls Ihr bemerkt, dass die Geister sich näher an das Haus bewegen, stellt Ihr fest, dass die Kugel stärker zu leuchten beginnt, und wieder schwächer wird, als die Geister sich entfernen. Es steht außer Frage, dass sie mit der Beeinflussung der Geister in Verbindung steht.\n\nWie sie jedoch funktioniert, bleibt ein Geheimnis. Vielleicht kann Hüter Dierwert sich ja einen Reim darauf machen, wenn Ihr ihm die Überreste einiger Geister und Eure Beobachtungen zuteilwerden lasst.", progress = "Was habt Ihr herausgefunden, <Name>?", completion = "&lt;Hüter Dierwert untersucht die Überreste.&gt;\n\nDas Gerät, das Ihr beschreibt, klingt nach einem nekromantischen Fokus... Ich hätte wissen sollen, dass dieser bösartige Lehrling sich dazu herablassen würde. Ich dachte, seine Ausbildung würde ihn daran hindern, so weit zu gehen, aber ich schätze, ich habe mich getäuscht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10315] = {title = "Die Nethermanten neutralisieren", objective = "Tötet 15 Nethermanten des Sonnenzorns und kehrt dann zu Netherpirscher Oazul auf Tulumans Landeplatz im Nethersturm zurück.", description = "Die Blutelfen sind Dummköpfe! Ich bin froh, dass unsere Handelsbeziehungen mit ihnen auseinander gebrochen sind. Auf all meinen Reisen durch den Kosmos habe ich nie so selbstsüchtige Wesen gesehen!\n\nSie zerstören weiterhin unser Land mit ihren Manaschmieden. Wollen wir mal schauen, ob wir ihnen bei der Manaschmiede Ara jenseits der Brücke Einhalt gebieten können.\n\nDie Nethermanten kanalisieren die Energie der Blutjuwelen, um den Energiefluss zu stabilisieren. Geht dort hin und löscht sie aus!", progress = nil, completion = "Alles, was wir tun, um sie von ihren Taten in den Manaschmieden abzuhalten, ist gut.\n\nMan kann offenbar nicht vernünftig mit ihnen reden. Und was auch immer ihre Anführer vorhaben, sie müssen verrückt sein.\n\nAls Belohnung für Eure treuen Dienste für die Ziele des Konsortiums möchte ich Euch in Eurer Landeswährung bezahlen, wenn Ihr nichts dagegen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10316] = {title = "Auf der Suche nach Beweisen", objective = "Durchsucht die Häuser auf dem Kapellenhof von Kirin'Var nach Hinweisen darauf, wer sich hinter der Beeinflussung der Geister verbirgt.", description = "Wer auch immer hinter den Veränderungen der Geister stehen mag, hat seine Ziele mit Bedacht ausgewählt, und darauf geachtet, dass er zuerst die mächtigsten Magier erwischt. Aber warum? Die Magie, die eingesetzt wird, um die Geister der getöteten Kirin Tor zu beeinflussen, muss sehr mächtig sein.\n\nWarum würde ein mächtiger Magier all diese Mühen auf sich nehmen? Ich bin versucht zu glauben, dass dies ein weiterer teuflischer Plan von Kael'thas ist, um hier weiteres Unheil anzurichten. Wenn es hier in der Nähe Blutelfen gibt, verstecken sie sich bestimmt in den Häusern hinter der überdachten Brücke.", progress = nil, completion = "Eine leuchtende Kugel liegt auf einem quadratischen Podest. Auf den ersten Blick scheint sie ein Behältnis für magische Energie zu sein, aber welche Art von Energie und zu welchem Zweck?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10317] = {title = "Den Großknecht erledigen", objective = "Vernichtet Großknecht Sonnenend in der Trelleummine, die sich unter der Manaschmiede Ara im Nethersturm befindet.", description = "Die Blutelfen nennen die Mine unter der Manaschmiede Ara Trelleummine. Seit sie die Mine unter der Manaschmiede Ultris verloren haben, ist sie der einzige Ort, von dem sie den Nachschub zum Betrieb ihrer Schmieden bekommen.\n\nIch brauche nicht zu erwähnen, dass es ein großer Vorteil für uns wäre, wenn wir ihre Bergbauaktivitäten dort verhindern könnten. Vielleicht könnten wir sogar dort einfallen und die Mine für uns selbst nutzen?\n\nWie auch immer, ich möchte, dass Ihr Euch um Großknecht Sonnenend kümmert. Die Mine befindet sich am hinteren Ende der Insel links von uns.", progress = nil, completion = "&lt;Der Großknecht flüstert.&gt;\n\nSeid Ihr hier um mich zu töten? Hmm. Nun, ich glaube, die Astralen wissen nicht alles, was?\n\nIch bin nicht der, den Ihr sucht, glaubt mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10318] = {title = "Den Übermeister erledigen", objective = "Tötet Übermeister Grindgarr. Kehrt dann zu Windhändler Tuluman auf Tulumans Landeplatz im Nethersturm.", description = "Ich war früher hier der Großknecht. Aber jetzt, da ich degradiert wurde, geht mir auf, dass unsere ganze Pilgerreise von Quel'Thalas in die Scherbenwelt eine einzige Lüge war!\n\nEine Lüge, die von Kael'thas eingefädelt wurde, um seine Streitkräfte hier im Nethersturm zu stärken.\n\nIch habe versucht, meine Brüder davon zu überzeugen, dass wir fortgehen sollten, besonders wegen der Brennenden Legion, aber sie sind alle zu stur.\n\nKönnt Ihr mir einen Gefallen tun? Tötet Übermeister Grindgarr. Kehrt dann zu Eurem Astralen zurück und sagt ihm, dass ich kein Feind mehr bin.", progress = nil, completion = "Ein Übermeister der Verdammniswache? Das ist merkwürdig! Was macht denn die Brennende Legion dort?\n\nHm, einige der Blutelfen werden also abtrünnig. Wir werden das im Hinterkopf behalten, falls wir uns je entschließen sollten, den Ort mit Gewalt einzunehmen. Zumindest sind das ein paar gute Nachrichten, oder?\n\nBitte, &lt;Name&gt;, nehmt dieses Zeichen meiner Dankbarkeit.", rewards = "Handschuhe des NetherpirschersLandungsstiefelÜbermeisterschulternAuf Euch wartet eine dieser Belohnungen:\n\nBand des Windhändlers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10319] = {title = "Das Phylakterium entwenden", objective = "Holt Naberius' Phylakterium vom Kapellenhof in Kirin'Var und bringt es zu Hüter Dierwert.", description = "Ich glaube, es wird Zeit für eine Erklärung. Ihr habt einen der Lehrlinge des Erzmagiers getroffen, Ravandwyr. Es gab jedoch noch einen weiteren mit dem Namen Naberius.\n\nEr war ein sehr fleißiger Schüler, hegte aber großes Interesse an der Nekromantie. Als Kael'thas mit seinen Streitmächten auftauchte, nutzte Naberius die Gelegenheit, um den Erzmagier zu verraten und die geheimen Verteidigungsmechanismen des Turms preiszugeben.\n\nJetzt, so scheint es, ist er zu einem Lich geworden. Wenn wir ihn aufhalten wollen, müssen wir uns sein Phylakterium besorgen. So wie ich ihn kenne, hat er es sicher irgendwo in seinem Gebiet sicher vergraben.", progress = "Wir müssen erst Naberius' Phylakterium beschaffen, bevor wir ihn angreifen können. Er ist sonst unverwundbar!", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Der Besitz des Phylakteriums ist der Schlüssel zu unserem Sieg. Wenn Ihr gegen Naberius in die Schlacht zieht, werde ich es zerstören und ihn so für Eure Angriffe verwundbar machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10320] = {title = "Vernichtet Naberius!", objective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr Naberius auf dem Kapellenhof des Dorfes besiegt.", description = "Erzmagier Vargoth hat die Gefahr in Naberius' Interesse an der Nekromantie erkannt, aber ich bin mir sicher, dass er niemals geglaubt hätte, dass sein Lehrling den Kirin Tor so viel Schaden zufügen würde.\n\nIhr müsst ihn besiegen, <Name>, sonst wird er weiterhin die Geister unserer gefallenen Brüder versklaven, sie ihrer Ruhe berauben und das letzte bisschen, was noch von Kirin'Var übrig ist, zerstören.\n\nOhne sein Phylakterium kann er mit den vereinten Kräften von zwei oder drei Kämpfern vernichtet werden, aber wer weiß, was seine Magie mehr Gegnern gegenüber anrichten könnte?", progress = nil, completion = "Der Sieg über Naberius ist ein große Leistung, &lt;Name&gt;. Ich kann mir nicht helfen, aber ich glaube, wir hätten eine Chance gegen Kael'thas' Streitkräfte gehabt, wenn der Lehrling auf der richtigen Seite gestanden hätte.", rewards = "Lehrlingsroben der Kirin TorBrustplatte der LebenswächterinHelmkappe des BoshaftenBeinschützer des forschen VerteidigersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10321] = {title = "Manaschmiede Coruu abschalten", objective = "Reist zur Manaschmiede Coruu, östlich von Area 52, und besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Manaschmiede abzuschalten, und kehrt dann zu Anachoret Karja zurück.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Euer Erfolg in B'naar hat und sehr große Hoffnung gemacht, <Name>.\n\nWir haben unsere Entdeckungen den Sehern mitgeteilt, und sie haben uns im Gegenzug mehr Informationen über die übrigen Manaschmieden gegeben.\n\nEs stehen immer noch drei weitere Manaschmieden, die von der Armee des Sonnenzorns kontrolliert werden.\n\nDie Manaschmiede Coruu findet Ihr im Osten. Vorarbeiterin Seylanna ist dort im Besitz des Zugangskristalls. Besorgt ihn und schaltet damit die Steuerungskonsole ab.\n\nWir zählen auf Euch, <Name>.", progress = "Habt Ihr Eure Aufgabe schon erledigt, <Name>?", completion = "Ausgezeichnete Arbeit. Jetzt sind nur noch zwei Manaschmieden aktiv.\n\nBald wird Kael'thas von seiner Hauptenergiequelle abgeschnitten sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10322] = {title = "Manaschmiede Duro abschalten", objective = "Anachoret Karja möchte, dass Ihr zur Manaschmiede Duro geht und den Zugangskristall von Vorarbeiter Athanel besorgt. Benutzt ihn, um die Steuerungskonsole von Duro abzuschalten.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wir haben Neuigkeiten von einer der Manaschmieden, die noch in Betrieb sind, erhalten. Die Armee des Sonnenzorns ist im Begriff, die Kontrolle über die Manaschmiede Duro zu verlieren.\n\nWegen ihrer erhöhten Energieproduktion werden ganze Schwärme von Manakreaturen von ihr angelockt - die Manaschmiede versinkt im Chaos.\n\nEine Explosion von Duro könnte eine Kettenreaktion auslösen, die die ganze Scherbenwelt in Gefahr bringen würde. Vorarbeiter Athanel ist im Besitz des Zugangskristalls, mit dem Ihr die Manaschmiede abschalten könnt.", progress = "Habt Ihr Eure Aufgabe schon erledigt, <Name>?", completion = "Ihr seid von den Naaru gesegnet, &lt;Name&gt;. Euer Einsatz für die Sache wird nicht unbemerkt oder unbelohnt bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10323] = {title = "Manaschmiede Ara abschalten", objective = "Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Nur noch eine Manaschmiede hält die Festung der Stürme in Betrieb. Nachdem wir die Manaschmiede Ara abgeschaltet haben, muss sich Kael mit seinen gespeicherten Energien zufrieden geben.\n\nReist zur Manaschmiede Ara im Nordwesten und gebt Kael den Rest, indem Ihr sie abschaltet.\n\nDer letzte Zugangskristall befindet sich im Besitz von Vorarbeiter Azarad. Seid jedoch vorsichtig; wir erwarten heftigen Widerstand in Kaels letzter funktionierender Schmiede. Ihr werdet wahrscheinlich die Unterstützung einiger Freunde brauchen.", progress = "Habt Ihr die Aufgabe, die ich Euch gegeben habe, schon erledigt, <Name>?", completion = "Die Brennende Legion? Verbündet mit Kael'thas Sonnenwanderer?\n\nDas sind erschütternde Nachrichten. Das erklärt vieles, was wir hier und in Schattenmond beobachtet haben.\n\nWir müssen Shattrath sofort informieren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKarjas MedaillonSiegel des Vorarbeiters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10324] = {title = "Die große Mondweidenjagd", objective = "Bringt 6 Bälge eines Mondweidenbocks zu Acteon in der Azurwacht.", description = "Gut gemacht, <Name>! Gut gemacht!\n\nJetzt, da Ihr Euch die Hörner an den Mondweidenhirschen abgestoßen habt, ist es an der Zeit, dass Ihr Euch einer würdigeren Beute zuwendet. Lasst Euch von der Gelassenheit der Mondweidenböcke nicht täuschen, wenn sie sich provoziert fühlen, sind sie ein gefährlicher Gegner.\n\nIhr findet die Böcke nördlich von hier. Weidmannsheil.", progress = "Die Bälge der Böcke sind grob und stark und halten das Fleisch zäh. Es ist kaum essbar, aber wir können es für andere Zwecke einsetzen.", completion = "Wunderbar! Ihr entwickelt Euch zu einem beachtlichen Jäger, &lt;Name&gt;.\n\nWürdet Ihr mir gerne ähnlich sehen? Nun, hier ist Eure Chance! Während Ihr auf der Jagd wart, habe ich diese Gegenstände aus den Bälgen, die ich hier noch herumliegen hatte, gefertigt.", rewards = "MondweidenlederstiefelMondweidenfellumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10325] = {title = "Male von Kil'jaeden", objective = "Bringt 10 Male von Kil'jaeden zu Adyen dem Lichtwächter in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wie Ihr vielleicht wisst, <Name>, sind die Aldor die Hüter des Lichts und die Diener der Naaru.\n\nUns direkt gegenüber stehen die Agenten der Brennenden Legion - Dämonen, die die Welten zerstören und die Unschuldigen verderben wollen.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, bringt mir die Insignien der niederrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Uns ist ein Versteck des Schattenrats in der Knochenwüste bekannt. Die Lager der Legion findet Ihr in Nagrand und dem Schergrat.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, <Name>?", completion = "Sich den Dämonen der Brennenden Legion und den wahnsinnigen Kultisten, die sie verehren, zu stellen ist keine geringe Tat, &lt;Name&gt;. Ihr habt viel Hingabe und Mut bewiesen. Macht so weiter, und Euer Ruf bei den Aldor wird weiter steigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10326] = {title = "Mehr Male von Kil'jaeden", objective = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", description = nil, progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", completion = "Beweist Euch weiterhin als würdig, &lt;Name&gt;. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden.", rewards = nil}
MultiLanguageQuestData['de'][10327] = {title = "Einzelne Male von Kil'jaeden", objective = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", description = nil, progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Beweist Euch weiterhin als würdig, &lt;Name&gt;. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden.", rewards = nil}
MultiLanguageQuestData['de'][10328] = {title = "Anweisungen des Sonnenzorns", objective = "Reist zur Manaschmiede Duro und beschafft die Truppenbefehle des Sonnenzorns und die Arkanbefehle des Sonnenzorns von den Einheiten des Sonnenzorns, die dort postiert sind. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Etwas an diesen Manaschmieden bereitet mir Kopfzerbrechen, <Name>. Die Naarutechnologie ist sehr fortschrittlich; Kael'thas hätte Jahre brauchen müssen, um sie auch nur im Ansatz zu verstehen.\n\nDas Sammeln von Informationen zu diesem Thema ist sehr schwierig, da Kaels Armee sehr diszipliniert ist und jegliche schriftliche Kommunikation sofort vernichtet.\n\nWir haben gehört, dass die Manaschmiede Duro von Manakreaturen angegriffen wird. Vielleicht haben die Verteidiger ihre Anweisungen noch nicht zerstört. Besorgt sie Euch und bringt sie zu mir.", progress = "Hattet Ihr Glück mit den Anweisungen der Manaschmiede Duro?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Wollen wir mal schauen, was uns diese Anweisungen verraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10329] = {title = "Manaschmiede B'naar abschalten", objective = "Geht zurück zur Manaschmiede B'naar und besorgt Euch den Zugangskristall von Vorarbeiter Theredis. Benutzt ihn bei der Steuerkonsole von B'naar um sie abzuschalten und meldet Euch danach bei Spionagemeister Thalodien zurück.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Während Ihr fort wart, hatte ich eine freundliche Diskussion mit den Aldor. Die Manaschmieden bestehen aus der Naarutechnologie der Festung der Stürme. Offensichtlich gibt es bei dieser Technologie Mechanismen, die ein dauerhaftes Abschalten im Notfall ermöglichen.\n\nAlles, was wir brauchen, um diesen Vorgang einzuleiten, ist ein Zugangskristall zur Steuerungskonsole. Der praktischen Stammrolle, die Ihr uns gebracht habt, nach, befinden sich die Kristalle im Besitz eines Typen namens Vorarbeiter Theredis. Besorgt ihn und schaut, was Ihr tun könnt.", progress = "Hat der Plan funktioniert? Ehrlich gesagt habe ich fast befürchtet, dass Ihr in die Luft gejagt werdet.", completion = "Natürlich hat es funktioniert! Ich bin Spionagemeister, meine Informationen sind immer genau.\n\nWie auch immer, da wartet ein brandneuer und spannender Auftrag auf Euch. Wollt Ihr davon hören? Natürlich wollt Ihr das.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10330] = {title = "Manaschmiede Coruu abschalten", objective = "Besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Steuerkonsole der Manaschmiede abzuschalten und meldet Euch dann bei Caledis Morgenhell.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Thalodien hat uns von Eurem Erfolg beim Abschalten der Manaschmiede B'naar erzählt. Er erwartet, dass Ihr Eure Leistung hier wiederholt und hat uns gebeten, ein Auge darauf zu haben, wer einen Kristall benutzt, um Zugang zu der Konsole im Inneren zu erhalten. Vorarbeiterin Seylanna hat den Zugangskristall, da sind wir uns sicher.\n\nGeht hinein und vollendet das Werk. Es besteht kein Grund zur Heimlichkeit mehr. Besorgt Euch den Kristall, schaltet die Konsole ab, tötet alle Techniker, die Euch daran hindern wollen, und macht Euch dann aus dem Staub.\n\nBeeilt Euch, Kaels Spürhunde kommen uns sicher bald auf die Schliche.", progress = "Habt Ihr Eure Aufgabe schon erledigt, <Name>?", completion = "Wir haben den Aufruhr gehört und wollten gerade gehen. Ich bin froh, dass Ihr nicht allzu viel Prügel einstecken musstet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10331] = {title = "Unverzichtbare Werkzeuge", objective = "Besorgt den Schmiedehammer von den Lehrlingen von Kirin'Var und bringt ihn zurück zu Lehrling Andrethan in Kirin'Var.", description = "Ihr habt hier nicht zufällig einen schweren Schmiedehammer herumliegen sehen, oder? Ich habe ihn hierher mitgenommen, um ein paar Hufeisen für das Pferd des alten Amorlin fertig zu stellen, aber ich kann ihn nicht finden.\n\nIch habe die ganze Scheune mindestens ein dutzend Mal abgesucht, aber ohne Erfolg. Vielleicht hat einer der anderen Lehrlinge ihn gefunden und ihn zurück zur Schmiede gebracht? Könntet Ihr für mich dorthin gehen und danach suchen? Sie befindet sich südöstlich des Turms auf dem Ratsplatz.", progress = "Hattet Ihr Glück bei der Suche nach meinem Hammer?", completion = "Dem Himmel sei Dank! Jetzt kann ich zurück an die Arbeit. Ich weiß, dass Ihr denkt, dass ich verrückt bin, so weit von einer richtigen Schmiede an meinem Gesellenstück zu arbeiten, aber ich darf nicht riskieren, dass die anderen Lehrlinge meine Entwürfe stehlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10332] = {title = "Meisterschmied Rhonsus", objective = "Lehrling Andrethan in Kirin'Var möchte, dass Ihr den Geist von Rhonsus, dem Meisterschmied des Dorfes, vernichtet.", description = "Endlich ist mein Gesellenstück fertig! Ich kann es kaum abwarten, es Meister Rhonsus zu zeigen.\n\n<Der Lehrling schaut Euch an, als Ihr ihm erzählt, was passiert ist, als Ihr den Hammer zurückholen wolltet.>\n\nSie haben Euch angegriffen? Alle? Beim Licht, sie sind verrückt geworden!\n\nWas sollen wir tun, <Name>? Es schmerzt mich, das zu sagen, aber vielleicht müssen wir Meister Rhonsus umbringen. Dann wäre ich der einzige Schmied in Kirin'Var, aber ich denke, dass meine Ausbildung ausreicht, um die Bedürfnisse des Dorfs zu befriedigen.", progress = nil, completion = "Meister Rhonsus hat mir alles beigebracht, was ich über mein Handwerk wissen muss. Ich werde seine Erinnerung in Ehren halten, indem ich den Leuten von Kirin'Var mit meinem Geschick diene.", rewards = "Hammer des MeisterschmiedsFein gefertigte SchuppengamaschenAndrethans MeisterwerkVerstärkter TopfhelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10333] = {title = "Helft Mama Mauschel", objective = "Sprecht mit Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", description = "Sagt mal, <Name>, ich habe mich gefragt, ob Ihr mir noch einen Gefallen tun könntet.\n\nMeine Partnerin da draußen im Feld könnte sicher etwas Hilfe gebrauchen. Könnt Ihr ihr vielleicht helfen?\n\nIch bin sicher, dass Mama Mauschel dafür sehr dankbar wäre. Kümmert Euch nicht um ihre scharfe Zunge.\n\nSie bemüht sich um unsere Interessen im Osten. Ihr findet sie in der Biokuppel Mittelreich beim Mittelreichposten.", progress = nil, completion = "Was? Er hat mich seine \"Partnerin\" genannt? Ich bin seine Frau!\n\nUnd er sagt, ich hätte eine scharfe Zunge. Oh, wenn ich zurück nach Area 52 komme, werde ich ihm die großen grünen Ohren langziehen!\n\nAber ich bin froh, dass Ihr hier seid. Mit einer Sache hatte er Recht; ich kann ganz sicher Eure Hilfe brauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10334] = {title = "Braucht mehr Kuhglocke", objective = "Sucht Bessy in den Feldern nordöstlich des Kapellenhügels von Kirin'Var im Nethersturm.", description = "Wo, oh, wo ist meine Bessy? Nach dem Angriff habe ich die Felder und den Kapellenhof nach Ihr abgesucht, aber ich konnte sie nicht finden!\n\nAlles, was ich von ihr noch habe, ist diese alte Kuhglocke. Normalerweise kommt sie gleich gerannt, wenn sie sie hört, aber vielleicht können diese alten Hände sie nicht stark genug läuten.\n\nIch leihe Euch Bessys Glocke, wenn Ihr hinaus auf die Felder geht und sie so fest Ihr nur könnt läutet. Vielleicht wartet Bessy einfach nur auf ein wenig mehr Kuhglocke.", progress = "<Die Kuh schaut Euch misstrauisch an, bleibt aber stehen.>", completion = "&lt;Als Ihr die Glocke aus Eurer Tasche holt, läutet Ihr sie ein paar Mal und zeigt sie Bessy, die sie zu erkennen scheint. Die Kuh lässt zu, dass Ihr ihr die Glocke um den Hals hängt und schaut Euch erwartungsvoll an.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10335] = {title = "Die Ruinen beobachten", objective = "Platziert die drei Vermessungsmarkierungen und kehrt dann zu Zephirion in der Sturmsäule im Nethersturm zurück.", description = "Ich muss in die Ruinen von Farahlon gehen, um meine Ausgrabungen zu beginnen! Das Problem ist, dass dieser Ort von Dämonen heimgesucht wird.\n\nVielleicht könntet Ihr schon einmal ein wenig Vorarbeit für mich leisten?\n\nEs gibt drei Orte in den Ruinen im Nordosten, an dem Ihr für mich Vermessungsmarkierungen aufstellen sollt. Jede befindet sich in der Nähe eines Draeneibanners.\n\nKehrt zu mir zurück, wenn Ihr alle drei Markierungen erfolgreich aufgestellt habt.", progress = "Das ging aber schnell. Ihr müsst sehr effektiv arbeiten, wenn Ihr alle drei Markierungen schon aufgestellt habt.", completion = "Ihr wollt mir keinen Bären in die Bandagen binden, oder? Das sind ausgezeichnete Nachrichten!\n\nJetzt, da Ihr die Routinearbeiten für die Vermessung für mich ausgeführt habt, kann ich mein Team in die Ruinen führen und schauen, was wir bergen können.\n\nIhr habt meinen Dank, &lt;Klasse&gt;.", rewards = "Astrale HandschuheZephirions GürtelBrustschutz der SturmsäuleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10336] = {title = "Diener von Culuthas", objective = "Tötet 10 Hunde von Culuthas und 5 Augen von Culuthas", description = "Vor ein paar Wochen hat die Brennende Legion in den Ruinen von Farahlon Einzug gehalten und damit all unsere Pläne, die Artefakte dort auszugraben, zunichtegemacht.\n\nDann habe ich heute erfahren, dass einer ihrer Schreckenslords, Culuthas, aus irgendeinem Grund alle anderen Mitglieder der Brennenden Legion dort getötet hat. Seitdem ruft er Dämonen, die ihm dienen.\n\n<Klasse>, ich möchte, dass Ihr zu den Ruinen im Nordosten geht und die Dämonen vernichtet!", progress = nil, completion = "Wirklich ausgezeichnete Arbeit.\n\nJetzt, da die Dämonen von Culuthas tot sind, kann Zephirion mit seinem Ausgrabungsteam sicher in die Ruinen von Farahlon zurückkehren.\n\nNehmt dies als Zeichen meiner Dankbarkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10337] = {title = "Almabtrieb", objective = "Begleitet Bessy sicher zu ihrem Besitzer Thadell zurück.", description = "Als Ihr merkt, dass Bessy Euch immer noch anstarrt, deutet Ihr nach Westen, zu dem Ort, an dem Thadell sich befindet. Ihr erwischt Euch selbst dabei, wie Ihr der Kuh versprecht, sie auf ihrem Nachhauseweg zu beschützen. Als Ihr Euren Satz beendet habt, wird Euch klar, dass die Kuh gar nicht verstehen kann, was Ihr sagt.\n\nMit einem Schulterzucken bereitet Ihr Euch darauf vor, das Rindvieh zu Thadell zurückzubegleiten.", progress = "Habt Ihr meine Bessy gefunden?", completion = "Bessy, bist Du das?\n\n&lt;Der Bauer dreht sich zu Euch um.&gt;\n\nVielen Dank, dass Ihr mir meine Bessy zurückgebracht habt, &lt;Name&gt;. Ich könnte ohne sie nicht leben!", rewards = "Stiefel des KuhhirtensReithandschuhe des KuhstupserGravierte Gürtelschnalle des RinderzüchtersThadells ArmschienenUnübertreffliche ViehruteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10338] = {title = "Manaschmiede Duro abschalten", objective = "Kehrt zur Manaschmiede Duro zurück und besorgt Euch den Zugangskristall von Vorarbeiter Athanel. Benutzt ihn, um die Steuerkonsole von Duro abzuschalten, und meldet Euch danach bei Spionagemeister Thalodien.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Die Manaschmiede Duro wird also angegriffen und die Streitkräfte des Sonnenzorns haben die Kontrolle verloren? Was für ein Dilemma! Wenn Duro fällt, fällt die Festung der Stürme. Der einzige Nachteil ist... wenn die Festung der Stürme zerstört wird, wird die Explosion wahrscheinlich die kläglichen Überreste dieses verlassenen Landes mit sich reißen.\n\nKael'thas Tod ist gut. Jedermanns Tod ist... nicht so gut, glaube ich. Es schmerzt mich, Euch darum zu bitten, aber geht zur Manaschmiede Duro und schaltet sie ab, bevor sie in Flammen aufgeht. Vorarbeiter Athanel hat den Zugangskristall.", progress = "Habt Ihr die Konsole abgeschaltet? Ihr solltet Euch beeilen, bevor ich meine Meinung dazu ändere.", completion = "Jetzt habt Ihr schon drei Manaschmieden abgeschaltet, &lt;Name&gt;. Kael'thas muss sich gerade furchtbar über Euch aufregen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10339] = {title = "Das Astraleum", objective = "Kommandant Ameer möchte, dass Ihr 5 Auftragsmörder des Astraleums, 5 Stoßtruppsoldaten des Astraleums, 2 Forscher des Astraleums und Hauptmann Zovax tötet und dann den Transponder des Astraleums Zeta aktiviert.", description = "Direkt südlich von hier findet Ihr den Stützpunkt des Astraleums. Das Astraleum bereitet sich dort auf irgendetwas vor... Vielleicht einen Angriff auf Ultris.\n\nWir können jedoch nichts dem Zufall überlassen, <Klasse>. Durchbrecht ihre Verteidigung und zerstört ihr Trainingslager.\n\nSobald Ihr ihre Soldaten und Hauptmann Zovax vernichtet habt, sucht den Transponder des Astraleums Zeta und benutzt ihn, um mit mir Kontakt aufzunehmen. Dann werdet Ihr Eure neuen Befehle erhalten.", progress = "Gut gemacht, Fleischling...", completion = "Wir müssen alle Daten, die sie in diesem Gebiet aufbewahren, sammeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10340] = {title = "Trümmerposten", objective = "Vorpostenkommandant Königstein möchte, dass Ihr mit Schwadronskommandant Dabir'ee sprecht, auf einem Greifen zum Trümmerposten fliegt und Euch bei Runetog Wildhammer meldet.", description = "<Name>, Ihr habt gute Arbeit hier an der Front geleistet und großes Talent mit den gepanzerten Greifen bewiesen... Ich glaube, ich habe eine weitere Aufgabe für Euch.\n\nStartpunkt für Eure neue Mission ist der Trümmerposten, eine Angriffsbasis der Wildhämmer auf einer schwebenden Insel in der Nähe des Portals. Es ist etwas anstrengend dort, aber Ihr habt starke Nerven. Ihr packt das schon.\n\nSprecht mit Schwadronskommandant Dabir'ee und lasst Euch von ihm zum Trümmerposten schicken. Meldet Euch dann bei Greifenmeister Runetog Wildhammer.", progress = nil, completion = "Ha ha! Ein frischer &lt;Volk&gt; vom Festland! Nun, keine Sorge - der Trümmerposten kann Euch vielleicht etwas seekrank machen, aber er treibt nicht weit weg!\n\nUnd bisher hat er sich nur einmal auf den Kopf gedreht... oder zweimal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10341] = {title = "Tretet sie, solange sie am Boden liegen", objective = "Tötet 8 Beschwörer des Sonnenzorns, 6 Jadgschützen des Sonnenzorns und 4 Zenturios des Sonnenzorns. Kehrt zu Magistrix Larynna in Area 52 zurück, wenn Ihr die Aufgabe erledigt habt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Das sind günstige Nachrichten, die Ihr bringt, <Name>. Ihr könnt nicht nur ungehindert in die Manaschmiede Duro reinspazieren, es eröffnet sich auch noch eine großartige Gelegenheit, Kaels Armee einen Schlag zu versetzen.\n\nNutzt den Angriff der Manakreaturen und vernichtet alle Nachzügler des Sonnenzorns, die Euch in die Arme laufen.\n\nIch habe keinen besonderen Spaß daran, mein eigenes Volk abzuschlachten, wie Tahlodien, aber diesen taktischen Vorteil dürfen wir nicht ungenutzt vorübergehen lassen.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Kaels Armee wird sich nicht so leicht von diesem Schlag erholen.", rewards = "Klinge des SonnenzornsSchlägel des WarpmeistersJuwelenbesetzte HellebardeBeschwörerstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10342] = {title = "Schieferhautschiefer", objective = "Sammelt 5 Stück Schieferhautschiefer und bringt sie zu Stiefels in Area 52 im Nethersturm.", description = "Ich verdiene gut daran, den Trunkenbolden hier Getränke zu verkaufen. Aber ich will mehr!\n\nDer Raketenchef sagt mir immer, dass er den Raketentreibstoff, den er braucht, um die X-52 abheben zu lassen, nicht verbessern kann.\n\nWir können dieses kleine Problem für ihn lösen.\n\nZuerst muss ich das Öl aus dem Schiefer der hiesigen Schieferhautschinder pressen. Daraus mache ich einen konzentrierten, wenn auch leicht entzündlichen, Grundstoff für die Mischung, die mir vorschwebt.\n\nSucht die Schinder und ihren Schiefer! Sie sind überall bei den violetten Felsen.", progress = "Habt Ihr schon genug Schiefer? Ich brauche eine ganze Menge, wenn ich genug Öl für den Raketentreibstoff der X-52 herstellen will.", completion = "Ok! Zutat Nummer eins erledigt.\n\nWenn Ihr noch Lust habt, besorgen wir jetzt etwas, das dem Schieferöl den kleinen Extrakick gibt, um die Rakete in den wirbelnden Nether zu katapultieren... oder in Stücke zu sprengen, was immer zuerst geschehen mag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10343] = {title = "Die unendliche Invasion", objective = "Sucht die von Manakreaturen heimgesuchte Gegend in Kirin'Var nach einem Manabombenfragment ab und bringt sie zu Zaubererleutnant Morran.", description = "Kael'thas Angriff auf Kirin'Var begann mit einem donnernden Geräusch und einem hellen Lichtblitz im Offiziersquartier im Nordwesten. Die Zerstörung war dort am größten. Nach dem Rückzug der Blutelfen geschah etwas Merkwürdiges.\n\nWesen aus reinem Mana begannen, von überall her in das Dorf zu strömen. Bis jetzt versuchen wir, sie so gut es geht im Zaum zu halten, aber ich hoffe, dass wir den Ansturm komplett abwehren können, wenn wir mehr über die Waffe in Erfahrung bringen, die Kael'thas benutzt hat.", progress = "Habt Ihr die Überreste der Waffe, die Kael'thas gegen das Dorf eingesetzt habt, gefunden?", completion = "Eine Manabombe?\n\n&lt;Morran dreht das Fragment in den Händen.&gt;\n\nEs ist unglaublich! Sogar die hellsten Köpfe in Dalaran hätte eine Waffe wie diese nicht entwerfen können. Das schiere Ausmaß der Explosion muss einen Riss im Nether geöffnet und diesen Kreaturen einen Zugang zu unserem Land verschafft haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10344] = {title = "Schwadronskommandant Greifgar", objective = "Sprecht mit Schwadronskommandant Greifgar im Trümmerposten.", description = "Schwadronskommandant Greifgar hat die Leitung über die Wildhämmer hier. Wenn Ihr zum ersten Mal im Trümmerposten seid, solltet Ihr Euch bei ihm melden.\n\nIhr findet ihn in den Überresten des Turms da drüben.", progress = nil, completion = "Ihr habt mit Runetog gesprochen? Er ist ein guter Zwerg, hält seine Greifen gut in Schuss und immer kampfbereit.\n\nIch bin Greifgar, Kommandant des Trümmerpostens. Ich weiß, es ist nicht gerade hübsch hier, aber dieser Felsklotz ist ein wichtiger Stützpunkt für Operationen auf der Höllenfeuerhalbinsel. Man kann hier rund um die Uhr Greifen ein- und ausfliegen sehen.\n\nEinen Rat? Hier ist einer: haltet Eure Ausrüstung bereit, Euren Magen leer und Eure Augen am Horizont... wenn der Trümmerposten anfängt auseinanderzufallen, haltet Euch an etwas fest, was nicht wegfliegen kann!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10345] = {title = "Fleisch geworden", objective = "Benutzt den Anzünder des Protektorats um 12 siechende Leichen zu zerstören. Bringt den Anzünder des Protektorats zu Agent Araxes außerhalb des Zugangsschachts Zeon zurück, wenn Ihr erfolgreich wart.", description = "Seht Ihr diese Leichen, <Volk>? Arconus ist für diese Massaker verantwortlich. Er hat sie ausgesaugt, sodass nur noch eine Fleischhülle übrig geblieben ist. Aber lasst Euch von den Körpern nicht täuschen! In diesen Leichen liegen Fleischbestien, die nur darauf warten, ahnungslose Dummköpfe, die sich zu nahe heranwagen, anzufallen.\n\nIch habe meine Befehle. Ich muss hierbleiben, bis meine Verstärkung eintrifft. Das bedeutet aber nicht, dass Ihr nicht meinen Anzünder nehmen und die siechenden Leichen, die überall in den Minen herumliegen, zerstören könnt. So oder so muss diese Aufgabe erledigt werden.", progress = "Konntet Ihr Sechs-Uhr finden?", completion = "Ihr habt meine Bandagen gerettet, &lt;Name&gt;. Dass Protektorat wird erfahren, was Ihr heute getan habt, Freund.", rewards = "Fleischtreibers StulpenGürtelbund des ProtektoratsArmschienen des VerwüstersStiefel des NexusaufsehersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10346] = {title = "Rückkehr zur Abyssischen Untiefe", objective = "Greifnerin Heulwind im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen zerstört.", description = "<Name>, Ihr habt Euch als fähiger Greifenreiter bewiesen. Wir könnten Euch für weitere Einsätze bei der Abyssischen Untiefe brauchen. Was sagt Ihr, <Klasse>? Wollt Ihr noch ein paar Flugstunden sammeln?", progress = "In der abyssischen Untiefe sind immer noch genügend ziele, <Name>. Schnappt Euch einen Greifen, wenn Ihr für eine weitere Runde bereit seid.", completion = "Wie ist es gelaufen? Ihr seid ja in guter Verfassung... Ist sie gut genug für einen weiteren Flug?", rewards = nil}
MultiLanguageQuestData['de'][10347] = {title = "Rückkehr zur Abyssischen Untiefe", objective = "Schwadronskommandant Brack im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen zerstört.", description = "<Name>, seid Ihr bereit für einen weiteren Flug zu Abyssischen Untiefe? Ich fürchte, dass uns die Dämonen der Legion von Norden her angreifen werden, wenn wir sie nicht weiter unter Druck setzen und zulassen, dass sie Ihre Festung verstärken.\n\nWas sagt Ihr, <Name>? Habt Ihr Lust, Euch erneut auf einen Windreiter zu schwingen und zur Abyssischen Untiefe zu fliegen?", progress = "Die Legion darf sich auf der abyssischen Untiefe nicht in Sicherheit wiegen! Wir müssen immer und immer wieder zuschlagen!", completion = "Die anderen Windreiterführer halten sehr viel von Euch, &lt;Name&gt;. Ihr habt in der abyssischen Untiefe ganz schön aufgeräumt. Macht weiter so!", rewards = nil}
MultiLanguageQuestData['de'][10348] = {title = "Neue Möglichkeiten", objective = "Sammelt 15 Elfenbeinglocken und kehrt dann zu Mehrdad im Mittelreichposten zurück.", description = "Ich habe gehört, dass eine Gruppe von 'Druiden' aus Azeroth sich für die Wirkung unserer Biokuppeltechnologie interessiert.\n\nDie Expedition des Cenarius ist sehr begierig darauf, Zugang zu den Pflanzen in den Kuppeln zu erlangen, besonders zu der einen, die sie Elfenbeinglocke nennen, und die für ihre heilenden Kräfte bekannt ist. Sie wächst in der Biokuppel Mittelreich in kleinen Büschen um größere Pflanzen herum.\n\nIch teile den Gewinn mit Euch, wenn Ihr mir ein paar der Kräuter für meine erste Lieferung sammelt.", progress = "Konntet Ihr die Pflanzen sammeln?", completion = "Interessante Wahl, oder? Die heilende Wirkung der Pflanze muss überragend sein. Ich bekomme eine Menge Geld für eine Blume, die eine der unspektakulärsten der Kuppeln ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10349] = {title = "Die Erdbinderin", objective = "Bringt den Purpurkristallsplitter zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel.", description = "Ihr solltet dieses Kristallstück zur Erdbinderin bringen. Sie ist wie Ihr... immer muss sie einem Geheimnis auf die Spur kommen und darüber nachgrübeln.\n\nWenn Ihr mich fragt, denkt sie zu viel.\n\nGebt ihr den Kristall und ich bin sicher, dass sie Euch beim Versuch herauszufinden, was im Grat vor sich geht, in ganz schöne Schwierigkeiten bringen wird.", progress = "Ist das ein Stück des riesigen Kristallsplitters oben auf dem Himmelssturzgrat?", completion = "Oh, ausgezeichnet!\n\nIch habe die ganze Zeit gehofft, an ein Stück davon zu kommen, aber Tola'thion kommt nicht in die Gänge. Er sollte mir eigentlich helfen herauszufinden, was im Himmelssturzgrat vor sich geht. Stattdessen schickt er nur arme Tölpel wie Euch - nichts für ungut - dort hoch auf die Schlachtbank.\n\nWenn Ihr mir den Kristall gebt, kann ich vielleicht herausfinden, in welcher Verbindung er zu den Kolossen steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10350] = {title = "Behomat", objective = "Sprecht mit Behomat bei der Händlertreppe in der Exodar.", description = "Ihr habt viele harte Lektionen in unserer Zeit zusammen von mir gelernt, doch nun ist es an der Zeit, dass ich Euch in weisere Hände übergebe.\n\nBehomat, der mich ausbildete, als ich noch grün wie Gras hinter den Ohren war, wird Euer neuer Lehrer sein. Ich habe ihm gesagt, dass ich Euch zu ihm schicken werde, er erwartet Euch also.\n\nIhr findet ihn in der Mitte der Terrasse der Krieger, am höchsten Punkt der Händlertreppe der Exodar.", progress = nil, completion = "Ah, Ihr seid also endlich gekommen. Ich bin Behomat und werde Euch in den Künsten eines Kriegers unterweisen. Ruada hat mir von Eurer Prüfung gegen den Felshetzer erzählt und ich bin sehr beeindruckt. Ich habe ein Geschenk für Euch.\n\nWir konnten nur wenig aus den Trümmern der Exodar retten, und das verteilen wir nur an die Würdigsten. Bitte nehmt Euch eine Waffe, die Eurem Kampfstil entspricht, und führt sie mit dem Wissen, dass Ihr sie verdient habt.\n\nWo wir gerade von Kampfstilen sprechen - es ist Zeit, dass Ihr etwas Neues lernt.", rewards = "SöldnergroßschwertSöldnerschlagSchwert des SöldnersSöldnerstilettDer folgende Zauber wird auf euch gewirkt:\n\nWeg der Verteidigung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10351] = {title = "Natürliche Heilmittel", objective = "Benutzt den Samen der Wiederbelebung beim Zirkel des Erdbinders, um das Land um den Kristall herum zu heilen. Kehrt dann zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel mit Euren Beobachtungen zurück.", description = "Es müssen die bösen Strahlungen von dem riesigen roten Kristall sein, die die Bergriesen herbeirufen und sie wahnsinnig machen.\n\nEr ist zu groß, um ihn weg zu bringen, und unsere Fertigkeiten reichen nicht aus, um ihn zu zerstören, aber mir ist ein Weg eingefallen, wie wir seine Macht bezwingen können.\n\nIch habe einen Zirkel beim nordwestlichen Ende des Kristalls auf dem Grat beschworen. Bringt diesen Samen dorthin und setzt seine Macht ein, um das Land durch die natürlichen Kräfte des Regens, des Wachstums und der Insekten zu heilen.\n\nSeid vorsichtig, <Name>. Ich spüre, dass hier eine außenstehende Macht am Werk ist... und sie ist nicht natürlich!", progress = "Hat es funktioniert? Was habt Ihr beobachtet? Habt Ihr herausgefunden, was im Himmelssturzgrat passiert ist?", completion = "Goliathon? Pathaleon der Kalkulator?\n\nKAEL'THAS!?\n\nPrinz Kael'thas hat seine Hand im Spiel?!\n\n&lt;Die Erdbinderin schäumt vor Wut.&gt;\n\nWas er getan hat ist Wahnsinn! Riesige Kristalle vom Himmel zu werfen und das Land zu dezimieren kann nur die Arbeit eines Verrückten sein!\n\nIch verspreche Euch, dass der Zirkel des Cenarius nun, da wir wissen was zu tun ist, jegliche weitere Versuche von Illidan und seinen Streitmächten, so etwas noch einmal zu tun, von uns vereitelt werden.\n\nWir stehen tief in Eurer Schuld, &lt;Name&gt;.", rewards = "Goldene cenarische SchienbeinschützerTiefgrüne HandlappenGrünbesetzte KnöchelwickelMantelung des ZerstörersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10352] = {title = "Spendet Wolle", objective = "Wir nehmen zurzeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Darnassus einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Wir nehmen zurzeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Darnassus einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10353] = {title = "Arconus der Unersättliche", objective = "Agent Sechs-Uhr beim Zugangsschacht Zeon im Nethersturm möchte, dass Ihr Arconus den Unersättlichen tötet und dann zu Kommandant Ameer im Wachposten des Protektorats im Nethersturm zurückkehrt.", description = "Araxes und ich wurden vor zwei Tagen nach Ultris geschickt. Unser Auftrag: findet und vernichtet den Leerenfürsten Arconus. Wir haben ihn bis zu seiner Mine verfolgt und herausgefunden, dass er sich von den Energien der Kreaturen in dieser Gegend ernährt.\n\nEs brach ein Feuerwechsel aus, bei dem Araxes und ich getrennt wurden. Jetzt bin ich hier gefangen und schwer verletzt. Unser Auftrag ist dahin!\n\nWenn Ihr Arconus erledigen könntet, wäre die oberste Führung Euch sehr dankbar. Wenn Ihr den Auftrag annehmt, werde ich Euch eine Reflexion meiner selbst als Wächter mitschicken.", progress = nil, completion = "Und Sechs-Uhr? Hat er es geschafft?\n\nWollen wir verdammt noch mal hoffen. Ich konnte keine Verstärkung zu ihnen schicken... Das Astraleum hat nun die ganze Gegend in Beschlag genommen.\n\nEntschuldigt, fast hätte ich Eure Belohnung vergessen.", rewards = "Tunika des ProtektoratsassassinenFleischtreibers KopfstückPlattengürtel des SternrufersGamaschen des NetherfahrersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10354] = {title = "Spendet Seide", objective = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10355] = {title = "Siechendes Fleisch", objective = "Sammelt 5 Proben einer verdurstenden Hydra und 5 Proben eines siechenden Sumpflords und bringt sie zu Ruam in Telredor.", description = "Wir müssen herausfinden, wie weit der Schaden reicht. Das Basidium, das Ihr mir gebracht habt, stammt von einem Sumpfriesen. Ihre größeren, zäheren Vettern, die Sumpflords, sollten der Degenerierung, die die Riesen befallen hat, gegenüber unempfindlicher sein.\n\nEs wäre auch schön zu wissen, inwiefern die Veränderungen die anderen Kreaturen des Todesmoors betroffen haben.\n\nKehrt zum Todesmoor zurück und schaut, ob Ihr Proben von den Sumpflords und Hydras in der Gegend sammeln könnt.", progress = "Konntet Ihr die Proben sammeln?", completion = "&lt;Ruam betrachtet die Proben und sieht besorgt aus.&gt;\n\nEs ist so, wie ich es befürchtet habe, &lt;Name&gt;. Die Austrocknung der Umwelt macht den Kreaturen, die außerhalb eines Sumpfgebiets nie überleben würden, sehr zu schaffen. Wir müssen die Umgebung weiterhin überwachen und die Expedition des Cenarius fragen, ob es etwas gibt, was wir tun können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10356] = {title = "Spendet Magiestoff", objective = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10357] = {title = "Spendet Runenstoff", objective = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", description = nil, progress = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten bei den Anführern auf der Exodar nicht unbeachtet bleiben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10358] = {title = "Noch mehr Runenstoff", objective = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", description = nil, progress = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "&lt;Name&gt; - ohne Helden, die sich wie Ihr einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!", rewards = nil}
MultiLanguageQuestData['de'][10359] = {title = "Spendet Wolle", objective = "Wir nehmen zurzeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Silbermond einbringen.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Wir nehmen zurzeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Silbermond einbringen.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10360] = {title = "Spendet Seide", objective = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in Silbermond mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in Silbermond mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10361] = {title = "Spendet Magiestoff", objective = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Silbermond nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Silbermond nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10362] = {title = "Spendet Runenstoff", objective = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", description = nil, progress = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten in Silbermond nicht unbeachtet bleiben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10363] = {title = "Noch mehr Runenstoff", objective = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Silbermond erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", description = nil, progress = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Silbermond erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "&lt;Name&gt; - ohne Helden, die sich wie Ihr einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!", rewards = nil}
MultiLanguageQuestData['de'][10364] = {title = "Caedmos", objective = "Sprecht mit Caedmos in der Halle des Lichts der Exodar.Ihr seid in kurzer Zeit sehr weit gekommen, <Name>. Schneller, als ich erwartet oder gehofft hätte. Es ist an der Zeit, dass Ihr Eure Ausbildung unter der Anleitung meines Meisters, Caedmos, fortsetzt.\n\nIch habe ihm gesagt, dass er Euch in der Exodar erwarten soll. Ihr findet ihn im Sanktum der Anachoreten in der Nähe des Eingangs zur Halle des Lichts.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr seid in kurzer Zeit sehr weit gekommen, <Name>. Schneller, als ich erwartet oder gehofft hätte. Es ist an der Zeit, dass Ihr Eure Ausbildung unter der Anleitung meines Meisters, Caedmos, fortsetzt.\n\nIch habe ihm gesagt, dass er Euch in der Exodar erwarten soll. Ihr findet ihn im Sanktum der Anachoreten in der Nähe des Eingangs zur Halle des Lichts.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10365] = {title = "Manaschmiede Ara abschalten", objective = "Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Ihr habt Eure Arbeit besser erledigt, als wir dachten. Die Manaschmiede Ara ist die letzte von Kaels Schmieden, die noch in Betrieb ist. Ihr findet sie nordwestlich von hier, aber Ihr müsst wahrscheinlich um sie herumgehen, um dorthin zu gelangen. Wir möchten, dass Ihr sie abschaltet.\n\nDer letzte Zugangskristall befindet sich im Besitz von Vorarbeiter Azarad. Seid jedoch vorsichtig; wir erwarten heftigen Widerstand in Kaels letzter funktionierender Schmiede. Ihr werdet wahrscheinlich die Unterstützung einiger Freunde brauchen.\n\nHmm... Azarad. Was ein komischer Name für einen Sin'dorei.", progress = "Habt Ihr die Aufgabe, die ich Euch gegeben habe, schon erledigt, <Name>?", completion = "Die Brennende Legion? Unter einer Decke mit Kael? Daran wird Voren'thal sicher seine Freude haben.\n\nDenkt ihr, dass Tausende von Pilgern von Azeroth hierher kommen, um sich mit der Brennenden Legion zu verbünden? Ich glaube kaum!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des ManasturmsThalodiens Glücksbringer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10366] = {title = "Jol", objective = "Sprecht mit Jol im Sanktum der Verteidiger in der Exodar.", description = "Der Pfad des Lichts und der Reinheit ist steinig, <Name>. Sogar ich habe manchmal Probleme, ihm zu folgen.\n\nIhr solltet meine Meisterin, Jol, in der Exodar aufsuchen. Sie hat mich zu Beginn meiner Reise ausgebildet. Ich bin mir sicher, dass sie in Euch ihren neuen Lieblingsschüler finden wird.\n\nIhr findet Jol in der Halle des Lichts in der Exodar beim Sanktum der Verteidiger, einem Raum, der von einem pulsierenden Lichtschein umgeben ist.", progress = nil, completion = "&lt;Name&gt;, ich habe Euch erwartet.\n\nTullas hat Lobeshymnen auf Euch gesungen, und ich bin sehr begierig darauf, Euch im Weg des Lichts zu unterweisen. Sucht mich auf, wenn Ihr bereit seid, Eure Fähigkeiten und Eure Macht verstehen zu lernen, und ich werde Euch geleiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10367] = {title = "Ein Verräter unter uns", objective = "Naladu in den Ruinen von Sha'naar möchte, dass Ihr den Schlüssel von Sha'naar aus einer Hütte in der Nähe besorgt.", description = "Wo immer ihr einen Stamm von versklavten Zerschlagenen seht, könnt Ihr auch einen Verräter finden. Ein verachtungswürdiges Wesen, das seine Brüder für das Versprechen von Macht verkauft hat.\n\nOben an der Treppe in der Mitte der Ruinen könnt Ihr eine Hütte finden. Das ist die Hütte des Verräters.\n\nEr ist im Augenblick nicht dort, Ihr könnt Euch also hineinschleichen, wenn Ihr Geduld habt. Innen findet Ihr einen Kasten mit einem Schlüssel darin. Dieser Schlüssel passt zu den Ketten, die die Ältesten des Lumpenpacks gefangen halten. Bringt ihn mir.\n\nSeid jedoch vorsichtig, Arzeth der Erbarmungslose treibt sich in der Nähe herum.", progress = "Habt Ihr den Schlüssel schon, <Name>?", completion = "Ich danke Euch, &lt;Name&gt;. Dank Eurer Hilfe wird mein Volk bald frei sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10368] = {title = "Die Ältesten des Lumpenpacks", objective = "Befreit Morod den Windtreiber, Akoru den Feuerrufer und Aylaan den Wasserrufer aus den Ruinen von Sha'naar. Kehrt zu Naladu zurück, wenn Ihr diese Aufgabe erledigt habt.", description = "Der Geist des Lumpenpacks ist gebrochen, weil sich unsere Ältesten in Gefangenschaft befinden. Nehmt diesen Schlüssel und befreit sie.\n\nEs sind Morod der Windtreiber, Akoru der Feuerrufer und Aylaan der Wasserrufer. Sobald sie frei sind, werden die Geister zum Stamm des Lumpenpacks zurückkehren.", progress = "Sagt mir, <Name>. Sind die Ältesten des Lumpenpacks schon frei?", completion = "Ich kann es fühlen, &lt;Name&gt;! Die Geister kehren zu uns zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10369] = {title = "Arzeths Untergang", objective = "Benutzt den Ältestenstab des Lumpenpacks gegen Arzeth den Erbarmungslosen und tötet ihn, nachdem er seine Macht verloren hat. Kehrt danach zu Naladu in den Ruinen von Sha'naar zurück.", description = "Ja, die Elementargeister sind zu uns zurückgekehrt! Wir sind nicht mehr so stark wie einst, aber auch geringe Magie kann in den richtigen Händen weit reichen.\n\nArzeth wurde von seinem dunklen Herrn große Macht verliehen. Nehmt diesen Stab. Er war einst ein großartiges Symbol unseres Volkes. Setzt ihn gegen Arzeth ein, und seine Macht wird für kurze Zeit verschwinden. Besiegt ihn, damit mein Volk endlich frei sein kann!", progress = "Ist es vollbracht, <Name>? Ist Arzeth tot?", completion = "Es ist wahr, &lt;Name&gt;. Ich war einst Naladu, der Bewahrer der Erde.\n\nIch war es, der die anderen Mitglieder des Lumpenpacks für leere Versprechungen von Macht verkauft hat. Ihr könnt mich nun verachten, wenn Ihr wollt. Wichtig ist, dass mein Stamm nun wieder frei ist und die Geister zu uns zurückgekehrt sind.\n\nIch werde mich dem Rest des Stammes nicht anschließen, aber nun kann ich in Frieden sterben. Mögen die Geister der Erde unter meinen Brüdern einen neuen Diener finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10370] = {title = "Nazgrels Befehl", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10371] = {title = "Yorus Gerstenbräu", objective = "Sprecht mit Yorus Gerstenbräu im Gasthaus Seenhain im Rotkammgebirge.", description = "Ein Zwergenkrieger namens Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet.\n\nEr wartet im Gasthaus von Seenhain, im sogenannten Rotkammgebirge in den Östlichen Königreichen. Es wird eine lange Reise, aber sie lohnt sich, wenn Ihr Euch selbst testen wollt, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10372] = {title = "Eine diskrete Anfrage", objective = "Sprecht mit Eralan in Tristessa.", description = "Eralan, eine Verbündete von mir in Tristessa, hat angefragt, ob ihr jemand bei einem eiligen Auftrag helfen könnte.\n\nIch weiß nicht, was sie vorhat, denn ich stelle keine Fragen, aber Ihr habt Euch mehr als fähig erwiesen. Ich möchte, dass Ihr nach Tristessa in den Geisterlanden reist, und mit Eralan sprecht.\n\nSie mag vielleicht ein wenig ruppig sein, aber man kann ihr vertrauen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10373] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges.", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt am Zugwindlager errichtet hat, nördlich des Alteracgebirges!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10374] = {title = "Der Ruf zu den Waffen: Die Pestländer!", objective = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!", progress = nil, completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10375] = {title = "Obsidiankriegsperlen", objective = nil, description = "Ihr habt Euch meinem Volk gegenüber als würdig erwiesen, <Name>. Jetzt ist es an der Zeit, uns zu beweisen, dass Ihr bereit seid, uns jederzeit beizustehen, auch gegen unserer ärgsten Feind.\n\nDie Oger der Scherbenwelt sind", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10376] = {title = "Symbol der Hoffnung", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10377] = {title = "Keine Angst", objective = "Ihr erlernt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nFurchtzauberschutz"}
MultiLanguageQuestData['de'][10378] = {title = "Magie verzehren", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10379] = {title = "Berührung der Schwäche", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10380] = {title = "Ein dunkler Pakt", objective = "Kaylaan bei Tulumans Landeplatz in Nethersturm möchte, dass Ihr 6 Warptüftler der Gan'arg, 3 Töchter des Schicksals und 3 Warpmeister der Mo'arg tötet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wir waren so blind, dass wir nicht gesehen haben, dass unsere beiden größten Feinde sich verbündet haben, <Name>.\n\nIch wäre nicht überrascht, wenn die Seher uns diese Information absichtlich vorenthalten hätten, aber wir müssen uns nun der Wirklichkeit stellen. Die Brennende Legion und Kael'thas Sonnenzornarmee dienen unter dem gleichen Banner.\n\nDie Dämonen sind der einzige Grund, aus dem Kael'thas je in der Lage war, die Technologie der Festung der Stürme nutzen zu können. Ich muss Euch auf Orelis' Befehl hin bitten, sie zu zerstören.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, <Name>?", completion = "Es ist also vollbracht. Wir kommen im Auftrag unserer Herren hierher, jagen und töten sie. Es gibt kein Pardon.\n\nManchmal gibt das einem zu denken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10381] = {title = "Nie mehr Aldor", objective = "Meldet Euch bei Exarch Orelis in Area 52.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Meine Mission hier ist zu Ende. Ich habe getan, was Orelis mir befohlen hat - nie habe ich ihn enttäuscht.\n\nNie wieder. Ich sehe ein großes Gemetzel voraus - einen Kreuzzug werden sie es nennen - das auf das neue Bündnis zwischen Kael'thas und der Brennenden Legion folgen wird.\n\nZuerst werden sie unsere heiligste Stadt dem Feind übergeben und uns dann bitten, im Kampf gegen ihren Feind zu sterben. Geht zurück zu Orelis und sagt ihm, dass die Naaru von nun an ihre Kämpfe alleine austragen können.", progress = nil, completion = "Die schlechten Nachrichten, die Ihr mir bringt, erfüllen mein Herz mit Traurigkeit. Zwei unserer tödlichsten Feinde schließen sich zusammen und einer der teuersten Söhne Shattraths hat seinen Glauben verloren.", rewards = "Leichte Weste des VerteidigersGurt des verlorenen VerteidigersKaylaans SchiftungZeremonielle Wickeltücher der AldorIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10382] = {title = "Geht zur Front", objective = "Nehmt einen Greifen zum Ehrenposten und sprecht mit Feldmarschall Brock.", description = "Nun, <Name>, ich hoffe, Ihr seid für die nächste Phase unserer Operation bereit. Die Legion schläft nicht - und wir auch nicht! Nehmt einen Greifen und fliegt zum Ehrenposten, einem kleinen Lager in der Nähe der Front der Legion.\n\nSprecht mit Feldmarschall Brock. Er wird bei Eurer Ankunft Anweisungen für Euch bereithalten. Oh, und sagt diesem teiggesichtigen Schildschmuser einen Gruß von mir.", progress = nil, completion = "Das trifft sich gut, &lt;Klasse&gt;. Ich bin froh, dass dieser brummige alte Zwerg es endlich auf die Reihe bekommen hat, uns ein wenig Hilfe zu schicken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10383] = {title = "Dies ist ein Brotkrumen!", objective = "Sprecht mit Jonathan LeCraft über die Kaninchen.Hallo. Ihr solltet mehr über diese Kaninchen herausfinden.", description = "Hallo. Ihr solltet mehr über diese Kaninchen herausfinden.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10384] = {title = "Daten der Astralen", objective = "Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr die Datenzelle des Astraleums besorgt.", description = "Seht Euch um, Fleischling. Ganz in der Nähe des Transponders sollte sich eine Datenzelle des Astraleums befinden. Sucht sie, öffnet sie und entnehmt den Inhalt.\n\nBringt sie dann sofort zu diesem Transponder zurück!", progress = "Habt Ihr die Datenzelle sichergestellt?", completion = "&lt;Ihr haltet die Datenzelle so, dass Ameer die Pläne lesen kann.&gt;\n\nNichts... Verdammt! Sie sind klug, aber nicht so klug wie Ameer!\n\nWorum ich Euch nun bitte, wird etwas gefährlich werden. Ich kann verstehen, wenn Ihr nicht weitermachen wollt, Fleischling.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10385] = {title = "Hirnschadengefahr = hoch", objective = "Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr 15 Melderdaten des Astraleums besorgt.", description = "Sie benutzen Melder, um die Informationen im Stützpunkt zu verteilen.\n\nEs gibt nur einem Weg, wie Ihr die Melder sehen und ihre Informationen extrahieren könnt. Unglücklicherweise könntet Ihr dadurch einen irreparablen Hirnschaden erlangen.\n\nWenn Ihr immer noch interessiert seid, müsst Ihr einige der Anhänger des Astraleums hier erschlagen und ihre Essenz nehmen. Wenn Ihr eine Essenz habt, trinkt sie. Mit ihrer Hilfe werdet Ihr für kurze Zeit in der Lage sein, die Melder des Astraleums zu sehen. Die Zeit reicht aus, um einen Melder zu zerstören und seine Informationen zu extrahieren.", progress = "Habt Ihr die Melderdaten schon besorgt?", completion = "Der Existenzgrund des Protektorats ist nun vollkommen bestätigt.\n\nDas Astraleum ist nicht hier, um Dimensius zu jagen! Sie sind hier, um Leere zu werden!\n\nSie manipulieren die Leerenergien bei dieser Manaschmiede um ihre eigenen Energien an eine Kreatur namens Dunkelpirscher zu binden.\n\nSie benutzen sicherlich einen Protobeschleuniger um die Umwandlung zu vervollständigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10386] = {title = "Der Teufelshäschertöter", objective = "Sprecht mit Oberanführer Hun Stümmelfaust.Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine \"Missionen\".\n\nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine \"Missionen\".\n\nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10387] = {title = "Der Teufelshäschertöter", objective = "Sprecht mit Oberanführer Hun Stümmelfaust.Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine \"Missionen\".\n\nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine \"Missionen\".\n\nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10388] = {title = "Rückkehr nach Thrallmar", objective = "Kehrt nach Thrallmar zurück und sprecht mit Nazgrel.", description = "Ich hoffe, Ihr hattet einen guten Flug, mein Freund. Während Ihr fort wart, ist ein Bote angekommen. Wie es aussieht, hat Nazgrel einen neuen Auftrag für Euch. Am besten geht Ihr nach Thrallmar zurück und sucht ihn auf. Ich habe das Gefühl, dass die Legion gerade erst warm geworden ist.", progress = nil, completion = "Ah, &lt;Name&gt;, Ihr kommt genau zur rechten Zeit. Unsere Späher haben herausgefunden, dass es sich bei den Ansammlungen der Legion auf dem Grat hinter uns tatsächlich um 'Konstruktionslager' handelt. Dort stellen die Dämonen ihre infernalen Teufelshäscher her. Wenn wir schnell gegen sie vorgehen, können wir vielleicht ihre Produktion aufhalten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10389] = {title = "Das Leid und die Dunkelheit", objective = "Magister Blutfalke möchte, dass Ihr 10 Terrorbestien bei den Teichen von Aggonar tötet.", description = "Grüße, <Name>. Ich habe den Schriftwechsel der Legion entziffert und ihre strategischen Pläne für die Halbinsel aufgedeckt. Offensichtlich sammelt sich in der Nähe der Teiche von Aggonar im Westen eine große Gruppe von teuflischen Terrorbestien. Das dürfen wir nicht ohne Kampf zulassen. Ihr müsst Euch dorthin begeben und ihre verfluchten Reihen ausdünnen.", progress = "Nun, <Klasse>? Habt Ihr die Terrorbestien besiegt?", completion = "Bravo, &lt;Name&gt;. Ich wusste, dass Ihr Erfolg haben werdet! Das Ende der Legion rückt immer näher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10390] = {title = "Konstruktionslager: Mageddon", objective = "Nazgrel in Thrallmar möchte, dass Ihr das Konstruktionslager: Mageddon angreift, 10 Diener der Gan'arg tötet und mit Schmiedebestie Sägeklinges Kopf zurückkehrt.", description = "<Name>, wir haben guten Grund zu vermuten, dass das Konstruktionslager, das sich am östlichsten befindet, noch nicht fertig ist. Die Gan'argsklaven der Legion arbeiten rund um die Uhr, um die Einrichtung zum Laufen zu bringen. Das können wir nicht zulassen.\n\nBegebt Euch nach Osten zum Konstruktionslager: Mageddon und tötet 10 Gan'arg. Bringt mir den Kopf ihres Meisters, Schmiedebestie Sägeklinge! So werden wir die Teufelshäscherproduktion der Legion zum Erliegen bringen!", progress = "Beeilt Euch, <Klasse>. Wir müssen das Konstruktionslager: Mageddon vernichten, bevor die Dämonen mit dem Bau fertig sind!", completion = "Gut gemacht, &lt;Klasse&gt;. Ein Konstruktionslager weniger, um das wir uns sorgen müssen. Die Legion wird eine Weile brauchen, um die Einrichtung wieder zum Laufen zu bringen. Ihr habt uns das beschafft, was uns im Augenblick am meisten fehlt: Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10391] = {title = "Kanonen des Zorns", objective = "Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Nazgrel in Thrallmar zurück.", description = "Es gibt eine weitere Produktionsstätte. Das Konstruktionslager: Zorn liegt direkt im Nordosten von Thrallmar. Die Dämonen haben eine Reihe von Teufelskanonen am Grat entlang aufgestellt - und sie zielen direkt auf uns! Ihr müsst in das Lager eindringen und diese Kanonen außer Gefecht setzen.\n\n<Name>, Ihr müsst sichergehen, dass Ihr alle zerstört - sonst kann die Legion nichts daran hindern, uns mit den Feuern der Hölle zu versengen!", progress = nil, completion = "Ich wusste, dass Ihr Biss habt, &lt;Name&gt;, aber dieses Mal habt Ihr Euch selbst übertroffen! Wir haben die Explosionen dieser verfluchten Kanonen bis hierher gehört! Das müsste der Legion beweisen, dass sie die Söhne Durotars nicht unterschätzen sollten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10392] = {title = "Die Schwelle zum Abgrund", objective = "Tötet Arix'Amal und nehmt Euch den Torschlüssel der Brennenden Legion. Benutzt den Schlüssel bei der Rune der Bosheit und kehrt danach zu Nazgrel in Thrallmar zurück.", description = "Ihr ehrt uns, <Name>. Aber nun müssen wir zuschlagen, bevor die Legion sich erholt! Nördlich von Thrallmar liegt der Invasionspunkt: Vernichter. Dort befindet sich ein Warpportal, durch das die Legion ihre Verstärkung bezieht.\n\nIhr müsst dieses Portal überlasten - und es zurück in den Abgrund schicken, aus dem es gekommen ist. Den Aktivierungsschlüssel trägt vermutlich der Kommandant des Punkts, Kriegshetzer Arix'Amal, bei sich. Tötet ihn. Benutzt dann den Schlüssel bei dem Portal und tut, was getan werden muss. Möge der Segen des Kriegshäuptlings auf Euch ruhen.", progress = "Beeilt Euch, <Name>. Mit jeder Sekunde, in der das Warpportal offen steht, betritt ein weiterer Dämon diese Welt.", completion = "Gelobt seien die Ahnen, Ihr habt es geschafft, &lt;Name&gt;! Die Legion hat eine schreckliche Niederlage einstecken müssen. Thrallmar ist wieder sicher. Ach, wenn ich doch nur hundert Krieger mit Eurem Herz und Eurem Verstand hätte, dann wäre dieses zerschlagene Land schon längst gezähmt. Ich salutiere vor Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10393] = {title = "Boshafte Pläne", objective = "Bringt den Schriftwechsel der Legion zu Magister Blutfalke in Thrallmar.", description = "Der Text auf dem Brief ist in dunklem, unentzifferbarem Gekrakel geschrieben. Je mehr Ihr sie anstarrt, desto mehr Symbole scheinen sich vor Euren Augen zu drehen und zu leuchten. Es gibt nur einen in Thrallmar, der so eine bösartige Schrift entziffern kann - der Blutelfenmagister Blutfalke.", progress = "Ich habe nicht viel Zeit, <Klasse>. Womit wollt Ihr mich belästigen?", completion = "Es war ganz richtig von Euch, mir dies zu bringen. Es könnte sich um einen Befehl zur Herstellung von zusätzlichen Teufelshäschern handeln - oder um neue Angriffspläne! Es wird etwas dauern, bis ich es entziffert habe. Lasst mich alleine. Ich lasse Euch rufen, wenn ich Genaueres weiß.\n\n&lt;Magister Blutfalke nickt Euch zu, als Ihr Euch abwendet.&gt;\n\nIhr seid sehr gescheit, &lt;Name&gt;. Ich werde Eure Fortschritte mit Interesse verfolgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10394] = {title = "Unterbrechung beim Konstruktionslager: Mageddon", objective = "Tötet 10 Diener der Gan'arg und Schmiedebestie Sägeklinge im Konstruktionslager: Mageddon und kehrt danach zu Feldmarschall Brock beim Ehrenposten zurück.", description = "Passt genau auf, <Name>. Wir haben die Lager der Legion, die entlang des Grats vor uns liegen, überwacht. Wir haben guten Grund zur Annahme, dass die Dämonen in diesen so genannten 'Konstruktionslagern' ihre verdammten Teufelshäscher herstellen.\n\nIhr könnt das am nächsten gelegene Ziel, das Konstruktionslager: Mageddon von hier aus im Westen sehen. Unsere Geheimagenten melden, dass es sich immer noch im Bau befindet. Wenn Ihr die Gan'argdiener und ihren Meister, Schmiedebestie Sägeklinge, tötet, können wir der Teufelshäscherproduktion der Legion ein schnelles Ende machen!", progress = "Sagt mir nicht, dass Ihr kalte Füße bekommen habt, <Klasse>! Wenn sie die Bauarbeiten im Konstruktionslager abschließen, müsst Ihr Euch um mehr als nur die Teufelshäscher Gedanken machen. An die Arbeit!", completion = "Nun, ich muss zugeben, ich bin beeindruckt, &lt;Name&gt;. Ich hätte nicht gedacht, dass Ihr den Schneid für diese Mission habt. Wirklich gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10395] = {title = "Der dunkle Schriftwechsel", objective = "Bringt den Schriftwechsel zu Warpseher Kryv in der Haupthalle der Ehrenfeste.", description = "Der Text auf dem Brief ist in dunklem, unentzifferbarem Gekrakel geschrieben. Je mehr Ihr sie anstarrt, desto mehr Symbole scheinen sich vor Euren Augen zu drehen und zu leuchten. Es gibt nur einen in der Ehrenfeste, der so eine bösartige Schrift entziffern kann - der Draeneimystiker Kryv.\n\nBringt den Schriftwechsel der Brennenden Legion zu Warpseher Kryv im Kriegsraum der Ehrenfeste.", progress = "Was ist los, <Klasse>? Ich spüre, dass Ihr etwas gefunden habt, dass von Verdammnis kündet.", completion = "Welch glücklicher Zufall, dass Ihr diesen Schriftwechsel abgefangen habt, &lt;Name&gt;. Ich werde zwar etwas Zeit brauchen, bis ich ihn entziffert habe, aber ich kann den Hass und die Eile, die in dieser Schriftrolle stecken, deutlich spüren. Ich habe das Gefühl, dass die wahren Pläne der Legion in dieser Welt sich bald offenbaren werden...\n\nGebt mir einen Moment Zeit, um die Schrift zu entziffern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10396] = {title = "Der Feind meines Feindes...", objective = "Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Feldmarschall Brock beim Ehrenposten zurück.", description = "Jetzt müssen wir uns auf unser zweites Ziel konzentrieren, das Konstruktionslager: Zorn. Es liegt direkt westlich von Mageddon. Das Problem ist, dass die Dämonen eine Reihe von Teufelskanonen direkt auf den Außenposten der Horde in Thrallmar gerichtet haben! Ich kann es zwar kaum fassen, aber wir müssen der Horde helfen, um unsere Linien beim Dunklen Portal aufrechtzuerhalten. Wir können es uns nicht erlauben, Thrallmar fallen zu lassen. Ihr müsst alle Kanonen zerstören, bevor die Legion unsere Verbündeten in die Luft jagt!", progress = "Die Legion könnte die Horde jederzeit unter Beschuss nehmen, <Name>! Ihr müsst diese verdammten Kanonen zerstören!", completion = "Eines muss ich Euch lassen, &lt;Name&gt;, Ihr seid ein geborener Kämpfer! Diese Tölpel der Horde werden vielleicht nie erfahren, wie knapp sie ihrem Ende entronnen sind. Es erfordert sehr viel Rückgrat, um dem Unheil im Namen seiner eigenen Feinde entgegenzutreten. Genau diese Ehre und dieses Pflichtgefühl machen die Allianz aus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10397] = {title = "Invasionspunkt: Vernichter", objective = "Tötet Arix'Amal. Nehmt den Torschlüssel der Brennenden Legion und benutzt ihn bei der Rune der Bosheit.", description = "Wir haben die letzte Basis der Legion auf dem Grat ausgemacht. Der Invasionspunkt: Vernichter liegt nordwestlich des Konstruktionslagers: Zorn. Dort befindet sich ein Warpportal, mit dessen Hilfe die Legion Verstärkung herbeiholt!\n\nIhr müsst an dieses Portal herankommen und verhindern, dass noch mehr Dämonen dadurch in unsere Welt kommen. Der Oberanführer des Punkts, Kriegshetzer Arix'Amal, hat den Aktivierungsschlüssel für das Portal. Nehmt ihn ihm ab und schaltet dieses verdammte Tor ab!", progress = "Habt Ihr das Warpportal schon geschlossen, <Name>? Während Ihr hier herumtrödelt kommen immer mehr Dämonen in die Scherbenwelt!", completion = "Gute Arbeit! Das sollte die Zahl der Dämonen, die uns auf die Pelle rücken, dramatisch verringern. Ich kann Euch nicht genug für Eure Hilfe danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10399] = {title = "Das Herz der Dunkelheit", objective = "Tötet 10 Terrorbestien bei den Teichen von Aggonar und kehrt dann zu Warpseher Kryv in der Haupthalle der Ehrenfeste zurück.", description = "Es ist genau so, wie ich befürchtet habe. Der Dämon, den Ihr unlängst getötet habt, Arix'Amal, stand im Dienst des heimlichen Legionslords Arazzius des Grausamen. Wie es scheint hat dieser Bösewicht eine neue Streitmacht von höllischen Terrorbestien in der Nähe der Teiche von Aggonar aufgestellt.\n\nIhr müsst Euch dorthin begeben und die Terrorbestien vernichten, bevor sie uns angreifen können. Aber seid vorsichtig, Freund. Die Teiche von Aggonar liegen in einem gemarterten, giftigen Tal. Ihr findet die verfluchten Teiche nordwestlich von hier, hinter der Höllenfeuerzitadelle.\n\nDas Licht sei mit Euch, <Name>.", progress = nil, completion = "Ich habe diesen großartigen Sieg vorausgesehen, &lt;Name&gt;. Die gesegneten Naaru schenken Euch an diesem Tag ihr Lächeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10400] = {title = "Oberanführer", objective = "Tötet Arazzius den Grausamen bei den Teichen von Aggonar und kehrt danach zu Truppenkommandant Danath Trollbann in der Ehrenfeste zurück.", description = "Der ehrwürdige Warpseher hat mir von Euren waghalsigen Abenteuern erzählt, <Name>. Er sprach auch von dem neuen Feind, den Ihr entdeckt habt. Dieser Arazzius der Grausame ist der mächtigste und bösartigste Feind, dem die Söhne Lothars sich je stellen mussten.\n\nWerdet Ihr uns zur Seite stehen, <Name>? Werdet Ihr diesem Legionslord gegenübertreten und ihn der Gerechtigkeit des Lichts übergeben? Wenn ja, dann begebt Euch zu den Teichen von Aggonar. Wenn Ihr ihn nicht findet, wird seine Bosheit sicher Euch finden.", progress = nil, completion = "Dem Licht sei Dank, ich wusste, dass Ihr es schafft! Arazzius und seine Diener sind Geschichte! Bald wird die Legion nach Hause flüchten und diese geschundene Welt wird wieder sicher sein. Und dann, wenn endlich Gerechtigkeit herrscht, können auch wir nach Hause gehen. \n\nVielen Dank, &lt;Name&gt;. Die Allianz und die Söhne Lothars feiern Euch heute!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVergeltung der IllidariMesserfausts BreiteKöniglicher Wachschutz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10403] = {title = "Naladu", objective = "Sucht Naladu in den Ruinen von Sha'naar.", description = "Vielleicht ist noch nicht alle Hoffnung für das Lumpenpack verloren. Ich bin einer der vier Ältesten, die diesen Stamm leiteten, bevor wir von den Illidari versklavt wurden. Ich dachte, dass die anderen tot seien, aber dann habe ich erfahren, dass zumindest zwei weitere noch am leben sind - angekettet und machtlos, so wie ich.\n\nIch habe Naladu noch nicht finden können und befürchte das Schlimmste. Oben in den Ruinen gibt es noch mehr Hütten, vielleicht könntet Ihr dort nach ihm suchen. Es wäre ein großes Glück für unseren Stamm, wenn alle Ältesten am Leben wären.", progress = nil, completion = "Ihr seid gekommen, um meinem Stamm zu helfen, &lt;Volk&gt;? Wie ungewöhnlich. Es gibt nicht viele, die sich um das Schicksal der Zerschlagenen in diesem Land scheren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10404] = {title = "Gegen die Legion", objective = "Exarch Orelis in Area 52 möchte, dass Ihr zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna geht und 12 Feuerfäuste der Gan'arg, 6 Konstruktionsherren der Gan'arg und 6 Zornschaffer tötet.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wir haben erfahren, dass die Brennende Legion Kael'thas mit technologischem Wissen unterstützt hat, und so die Bedrohung, die von ihm ausgeht, noch um ein Vielfaches vergrößert hat.\n\nDa die Legion in der Gegend so zahlreich vertreten ist, können wir den größten Schaden nur durch einen gezielten Angriff auf die Konstruktionsbasen im Norden erreichen.\n\nGeht zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna und zerstört unsere Feinde. Möge das Licht Eure Klinge führen, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10405] = {title = "S-A-B-O-T-A-G-E", objective = "Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr eine vorbereitete Bandage des Astraleums besorgt.", description = "Wir müssen die Maschinen zerstören, die diese abnormalen Dunkelpirscher hervorbringen. Ihren Protobeschleuniger anzugreifen ist sinnlos, da es sich um eine astrale Erfindung handelt. Wir müssen stattdessen die Rohre der Manaschmiede, die sie als Energieleitung verwenden, zerstören.\n\nIch habe fast alles, was ich brauche, um ein Gerät herzustellen, das die Energieleitung überlasten kann. Ich brauche nur noch die Bandagen eines Archon oder Oberanführers, der sich bald verwandeln wird, um das Gerät einzustellen.", progress = "Habt Ihr die Bandage besorgt?", completion = "Ausgezeichnet! Jetzt kann ich das Gerät einstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10406] = {title = "Die Nachricht überbringen", objective = "Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Demolierer des Protektorats zur Energieleitung der Manaschmiede Ultris begleitet und ihn beschützt, während er die Leitung sabotiert.", description = "Ich schicke einen meiner Demolierer los, um das Störgerät zu platzieren. Sorgt nur dafür, dass ihm kein Leid geschieht, während er den Störer aufstellt.\n\nBeschützt ihn! Er wird sich nicht wehren, wenn er von Feinden angegriffen wird, da er nur ein holografisches Bild ist, aber auch das kann zerstört werden!\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Er muss Erfolg haben!", completion = "Dank Euch sind ihre Pläne gescheitert! Jetzt bleibt nur noch Eines übrig... Salhadaar.", rewards = "Stiefel der druidischen MachtHandlappen des AufwieglersKopfschutz des ProtektoratsWarpfadenwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10407] = {title = "Socrethars Schatten", objective = "Anachoret Karja in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Der berüchtigte Eredar, Socrethar, führt die Brennende Legion im Nethersturm an. Allein seinen Namen zu nennen lässt die meisten Draenei erzittern. Er erteilt seine Befehle von einer Insel im Nordwesten aus, die nur seine vertrauenswürdigsten Leutnants betreten können.\n\nUm dorthin zu gelangen, müsst Ihr einen Teleportationsstein besorgen, was nicht einfach wird. Die erste Hälfte des Steins befindet sich im Besitz von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit. Die zweite Hälfte hat der Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna.", progress = "Habt Ihr Socrethars Teleportationsstein schon besorgt, <Name>?", completion = "Eure Aufopferung für unsere Sache ist beispielhaft, &lt;Name&gt;. Jetzt, da wir Socrethars Teleportationsstein in unserem Besitz haben, gibt es nur noch Eines zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10408] = {title = "Nexuskönig Salhadaar", objective = "Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Störer des Protektorats benutzt, um Salhadaar Kraftfelder zu senken und Nexuskönig Salhadaar zu vernichten.", description = "Ich habe einen weiteren Störer in meinem Besitz. Einer, der in der Lage ist, die drei Energieleitungen, die Salhadaar umgeben, zu zerstören. Wenn die Energieleitungen einmal vernichtet sind, werden sich Salhadaars schützende Kraftschilde senken. Für diese Tat wird er Euch mit einer Wildheit angreifen, die Ihr noch nie zuvor gesehen habt, <Name>.\n\nWenn Ihr bereit seid, die Welt von Salhadaar zu befreien, gebe ich Euch den Störer.", progress = "Ist... Ist er wirklich tot? Vernichtet?", completion = "Seit tausend Jahren, vielleicht mehr, führt Salhadaar nun seinen Kreuzzug, bei dem er alles vernichtet, was ihm im Weg steht. Ich kann kaum glauben, dass wir ihn nun zum letzten Mal gesehen haben... Ihr habt uns einen großen Dienst erwiesen, &lt;Name&gt;, und dafür sollt Ihr belohnt werden.", rewards = "Der Brennende KreuzzüglerFleischlingssimulationsstabAmeers ImpulstaserAmeers RichturteilDoppelklingendolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10409] = {title = "Todesstoß für die Legion", objective = "Hohepriesterin Ishanah möchte, dass Ihr zum Transporter der Legion am nordwestlichsten Ende des Nethersturms geht und Euch zu Socrethars Sitz teleportiert. Wenn Ihr dort seid, besiegt Socrethar.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wenn man mit mächtigen Eredar zu tun hat, sind große Armeen meist nutzlos. Ihre verderbte Macht über die sterblichen Seelen ist so stark, dass nur die mit einem starken Willen ihnen gegenübertreten können.\n\nBringt diesen Stein zum Invasionspunkt: Oberanführer zwischen der Konstruktionsbasis: Vergessenheit und der Konstruktionsbasis: Gehenna und nehmt Eure engsten und stärksten Freunde mit. Orelis und Karja erwarten Euch bei Socrethars Sitz. Ich werde Adyen mit ihnen losschicken.\n\nMöge das Licht sich heute behaupten, <Name>. Möge Socrethars Ende nahen.", progress = nil, completion = "Es ist vollbracht, &lt;Name&gt;. Socrethar wurde vernichtet.\n\nIch und die anderen werden uns von unseren Wunden erholen, &lt;Name&gt;. Der Zorn der Magie Socrethars war jedoch zu viel für den jungen Kaylaan. Nicht einmal meine stärksten Gebete konnten ihn wiederbeleben.\n\nEs ist unendlich schade, dass jemand, der so jung ist, in der Schlacht sterben musste. Am Ende war jedoch sein Wille stark genug, um sich von der Verderbtheit der Legion zu erholen. Dies soll uns ein Trost sein.", rewards = "Schuhe der HohepriesterinGesäuberte TeufelsschulterstückeStulpen des erlösten VerteidigersGurt des LichtwächtersAuf Euch wartet eine dieser Belohnungen:\n\nKaylaans Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10410] = {title = "Ishanahs Hilfe", objective = "Bringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des endlosen Lichts auf der Aldorhöhe in Shattrath.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Die Zeit ist gekommen, da Ihr Euch Socrethar stellen müsst, <Name>. Einem Eredar entgegen zu treten ist eine Aufgabe, die keiner von uns auf die leichte Schulter nimmt. Schon ein kleiner Fehler kann uns das Leben kosten, wenn wir unvorbereitet sind.\n\nBringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des Endlosen Lichts in Shattrath. Sie wird entscheiden, wie mit der Situation umzugehen ist.", progress = "Was bereitet Euch Kummer, Kind?", completion = "Socrethar... Ich erinnere mich an den Namen. Er war einst ein berühmter Krieger des Lichts. Sein einziger Fehler war sein Stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10411] = {title = "Elektroschock!", objective = "Forscher Navuud im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 30 Leerenabschaumkugeln und 30 Sickerschlickkugeln zerstört.", description = "Um die zerstörte Manaschmiede herum findet Ihr die Überbleibsel von Dimensius' Taten. Sickernder Schlick verschmutzt die Teiche um Ultris herum. Direkt unter diesen Teichen, wo sich nun der Stützpunkt des Astraleums befindet, findet Ihr noch mehr Müll in Form von Leerenabschaum.\n\nDer beste Weg, ihn zu entsorgen, ist, den Schleim mithilfe von Elektroschocks in Kugeln zu verwandeln. Benutzt dieses Elixier, um Eure Angriffe unter Strom zu setzen. Die Entladung, die dabei entsteht, löst den Schleim in seine Urform auf. Zerstört die Kugeln!", progress = "Sowohl der Schlamm als auch der Abschaum sind extrem giftig. Wenn wir uns nicht um sie kümmern, verwandeln sie sich in erstarrte Schrecken der Leere!", completion = "Ich hoffe, es ist nicht zu spät. Habt Ihr irgendwelchen abnormal großen Schleim in der Gegend, zu der es den Leerabschaum zieht, gesehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10412] = {title = "Siegel der Feuerschwingen", objective = "Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel der Feuerschwingen bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Es ist kein Geheimnis, dass Kael'thas Sonnenwanderer uns als große Bedrohung sieht. Nüchtern betrachtet gibt es nicht viele Sin'dorei, die frisch aus Silbermond kommen und bereit sind, sich der Gesellschaft, die Kael'thas unterhält, anzuschließen.\n\nEs ist auch kein Geheimnis, dass es sich hier nicht nur um Wortgefechte handelt. Die Seher und die vielen Armeen, die Kael'thas dienen, haben und werden sich angreifen, sobald sie sich begegnen. Der einzige Weg, wie Ihr beweisen könnt, dass Ihr auf unserer Seite steht, ist, sich dem Kampf anzuschließen, <Name>.\n\nKaels niederrangige Anhänger tragen Siegel der Feuerschwingen bei sich, die ihren Rang anzeigen. Bringt sie mir.", progress = "Los, <Name>. Sprecht.", completion = "Gut gemacht, &lt;Name&gt;. Vielleicht stellt Ihr Euch doch noch als nützlich heraus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10413] = {title = "Die Schrecken der Verschmutzung", objective = "Bringt die Phiole mit Leerenschreckensschlamm zu Forscher Navuud im Wachposten des Protektorakts im Nethersturm.", description = "Ihr befüllt vorsichtig eine Phiole mit dem Schlamm des gefallenen Leerenschreckens.\n\nForscher Navuud im Wachposten des Protektorats wäre an einem solchen Fund sicher interessiert. Bringt ihn sofort zu ihm!", progress = "Hm, Ihr seht dreckig aus... Was ist geschehen?", completion = "WAS!? Ihr habt gegen einen Schrecken der Leere gekämpft? Und überlebt?! Unglaublich!\n\nDiese Probe ist ihr Gewicht in Gold wert. Ein Fund wie dieser verlangt eine Belohnung.", rewards = "Umhang des RutengängersAuf Euch wartet eine dieser Belohnungen:\n\nRing des ProtektoratsassassinenSchmuckstück des Sterntöters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10414] = {title = "Einzelne Siegel der Feuerschwingen", objective = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!", description = nil, progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Ja... Kaels Leute schwinden, während wir wachsen.\n\n&lt;Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.&gt;", rewards = nil}
MultiLanguageQuestData['de'][10415] = {title = "Mehr Siegel der Feuerschwingen", objective = "Was habt Ihr in letzter Zeit für uns getan, <Name>? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", description = nil, progress = "Was habt Ihr in letzter Zeit für uns getan, <Name>? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", completion = "Ausgezeichnet! Alle, die sich uns in den Weg stellen, werden vernichtet!\n\n&lt;Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.&gt;", rewards = nil}
MultiLanguageQuestData['de'][10416] = {title = "Bündelung der Macht", objective = "Voren'thal der Seher in Shattrath möchte, dass Ihr einen arkanen Folianten besorgt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Arkane Folianten sind keine gewöhnlichen Bücher, die sich mit arkanen Themen befassen. Ihnen wohnt eine wesenhafte Macht inne - eine Macht, die ich in eine einzelne arkane Rune bündeln kann.\n\nSolltet Ihr auf Euren Reisen einen arkanen Folianten finden, werde ich Euch eine solche Rune geben. Nur die mächtigsten magiebegabten Wesen tragen die Bücher, die ich brauche, bei sich. In der Scherbenwelt sind das meistens Kaels Blutelfen, aber Ihr wärt überrascht, wo solche Bücher des Öfteren auftauchen.", progress = "Habt Ihr schon einen arkanen Folianten besorgt, <Name>?", completion = "Wie versprochen, &lt;Name&gt;. Die Gesamtheit der ureigenen Macht des Buches, gepackt in eine einzelne Rune.", rewards = "Ihr bekommt:\n\nArkane Rune"}
MultiLanguageQuestData['de'][10417] = {title = "Führt eine Diagnose durch!", objective = "Beschafft die Diagnoseergebnisse und bringt sie zu Mehrdad im Mittelreichposten.", description = "Wo auch immer das Konsortium Einzug hält, bringen wir unsere Biokuppeltechnologie mit. Diese Technologie erlaubt uns, in einer kontrollierten und lebenserhaltenden Atmosphäre zu arbeiten, da wir uns meist in feindlichen Gebieten befinden.\n\nDie bösartigen Bedingungen und Kreaturen des Nethersturms haben begonnen, die Ausrüstung, die unsere Biokuppeln aufrechterhält, zu zerstören, besonders den Generator im Osten. Ich habe einen Diagnoselauf dort begonnen, damit ich hoffentlich herausfinden kann, was gegen den Schaden getan werden kann. Könntet Ihr die Resultate dort abholen und zu mir bringen?", progress = "Habt Ihr die Diagnoseergebnisse?", completion = "&lt;Mehrdad nickt und betrachtet die Diagnoseergebnisse.&gt;\n\nDas ist beunruhigend. Der Schaden ist größer, als ich befürchtet habe. Ich kann mir aus der Sturmsäule einige Werkzeuge schicken lassen, um Reparaturen durchzuführen, aber das ist sinnlos, wenn wir nicht einmal wissen, was den Schaden verursacht hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10418] = {title = "Die Saboteure ausschalten", objective = "Mehrdad beim Mittelreichposten möchte, dass Ihr 8 Stachelschuppenkrokilisken tötet.", description = "Als ich das Gebiet nach Hinweisen auf den Schaden unserer Ausrüstung abgesucht habe, habe ich Teile der Schildgeneratoren auf dem Grund des kleinen Sees im Norden gesehen. Ich bin mir nicht sicher, warum die Krokilisken sich für unsere Ausrüstung interessieren, aber wir müssen dieses Problem beseitigen.\n\nDas Konsortium ist sich in dieser Sache einig. Wenn es zu einer Entscheidung zwischen der Ausrüstung und Krokilisken kommt, müssen die Tiere gehen. Ich werde Euch angemessen belohnen, wenn Ihr Euch darum kümmert.", progress = nil, completion = "Das Gebiet sieht schon aufgeräumter aus. Die Kuppeln sind sehr hilfreich, aber ein großer Nachteil ist der unkontrollierte Wuchs, den sie an manchen Orten begünstigen, der die einheimischen Arten schneller wachsen und sich schneller vermehren lässt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10419] = {title = "Arkane Folianten", objective = "Habt Ihr noch mehr arkane Folianten besorgt, <Name>?", description = nil, progress = "Habt Ihr noch mehr arkane Folianten besorgt, <Name>?", completion = "Die Macht in diesem Folianten ist enorm. Und doch kann er von jemandem mit klarem Verstand in eine einzelne Rune verwandelt werden.", rewards = "Ihr bekommt:\n\nArkane Rune"}
MultiLanguageQuestData['de'][10420] = {title = "Ein reinigendes Licht", objective = "Bringt eine Ladung teuflische Waffen zu Ishanah in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Dieser Tempel ist eine der heiligsten Stätten der ganzen Scherbenwelt. Die Macht des Lichts ist hier so stark, dass es weltliche Gegenstände sogar von der schlimmsten teuflischen Verderbnis befreien kann.\n\nFalls Ihr bei Euren Kämpfen mit den dämonischen Feinden teuflische Waffen finden solltet, bringt sie zu mir. Dann werde ich Euch die reinigende Kraft des Lichts beweisen.", progress = "Habt Ihr schon ein paar teuflische Waffen besorgt?", completion = "Schaut zu, wie die verderbten Materialien sich auflösen. Schaut zu, wie sich Metall in Staub verwandelt.\n\nDas Licht reinigt alles, und nur die reinsten Überreste bleiben.", rewards = "Ihr bekommt:\n\nHeiliger Staub"}
MultiLanguageQuestData['de'][10421] = {title = "Teuflische Waffen", objective = "Habt Ihr in letzter Zeit ein paar teuflische Waffen gefunden? Lasst das Licht seine Wirkung tun, <Name>. Erlaubt diesen verderbten Dingen nicht, in dieser Welt zu verweilen.", description = nil, progress = "Habt Ihr in letzter Zeit ein paar teuflische Waffen gefunden? Lasst das Licht seine Wirkung tun, <Name>. Erlaubt diesen verderbten Dingen nicht, in dieser Welt zu verweilen.", completion = "Die teuflischen Materialien wurden aus dieser Welt entfernt. Nur das Licht bleibt.", rewards = "Ihr bekommt:\n\nHeiliger Staub"}
MultiLanguageQuestData['de'][10422] = {title = "Hauptmann Tyralius", objective = "Fleischtreiber Viridius im Wachposten des Protektorats im Nethersturm möchte, dass Ihr Hauptmann Tyralius findet und befreit.", description = "Hauptmann Tyralius hat eine Truppe von Soldaten vor 10 Tagen in Richtung des Stützpunkts des Astraleums geführt. Seitdem haben wir nichts von ihm oder seinen Leuten gehört.\n\nEs ist sehr wahrscheinlich, dass sie überfallen und getötet wurden, aber ich bekomme ein merkwürdiges Signal auf meinen Instrumenten.\n\nIch glaube, es ist ein Notsignal, aber diese Dinge haben sich schon öfter geirrt. Wenn Tyralius noch am Leben ist, halten sie ihn in einem Ihrer Gefängnisse fest. Ihr müsst das Gefängnis finden und es mit einem Schlüssel, den Ihr wahrscheinlich bei einem Wärter finden könnt, öffnen.", progress = nil, completion = "Danke, &lt;Name&gt;. Tyralius hat schwere Wunden erlitten, aber wir denken, dass er es schaffen wird.\n\nEr hat ganze Felder voller Gefängnisse erwähnt, die so ähnlich sind wie das, aus dem Ihr ihn errettet habt. Gefängnisse voller Kreaturen aus dem ganzen Universum!\n\nWir werden uns bei Euch melden, wenn wir entschließen sollten, sie zu öffnen. Das Konsortium hat schon angemeldet, dass sie planen, ein paar Teams dorthin zu schicken. Sie arbeiten bereits an einer Technologie, mit der sie die Schlösser des Astraleums aufbrechen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10423] = {title = "Zur Sturmsäule", objective = "Sprecht mit Ghabar in der Sturmsäule im Nethersturm.", description = "Meisteringenieur Ghabar möchte sicher die Ergebnisse der Diagnose erfahren. Sie zeigen uns wenigstens, dass wir die Funktionalität der Kuppelgeneratoren genau im Auge behalten müssen. Wenn die Felder immer instabiler werden, können wir ihre Auswirkungen auch immer schwerer kontrollieren. Das könnte ein Desaster für unsere Expedition und alles, was sich in den Kuppeln befindet, bedeuten.\n\nIhr findet Ghabar in der Sturmsäule. Folgt einfach der Straße nördlich dieser Biokuppel und überquert die Brücke. Sie führt Euch direkt zum Aufzug unten in der Säule.", progress = nil, completion = "&lt;Ihr stellt Euch vor und meldet die Ergebnisse von Mehrdads Diagnose bei der Biokuppel Mittelreich.&gt;\n\nMehrdad ist nur ein einfacher Techniker, aber er hat ein gutes Auge fürs Detail. Wenn seine Beobachtungen richtig sind, müssen wir auch bei den restlichen Kuppelgeneratoren so schnell wie möglich Diagnosen durchführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10424] = {title = "Diagnose: kritisch", objective = "Benutzt das Diagnosegerät in der Nähe des Generators der Biokuppel Sutheron und bringt die Diagnoseergebnisse zu Ghabar in der Sturmsäule zurück.", description = "Wenn Mehrdads Ergebnisse richtig sind - und ich habe keinen Grund daran zu zweifeln - könnte der Rest der Kuppeln in Gefahr sein.\n\nIch glaube jedoch, dass Mehrdad nicht den richtigen Grund für die Defekte gefunden hat. Tiere können die Generatoren bisweilen schon beschädigen, aber niemals so schwer.\n\nUm sicher zu gehen, möchte ich, dass Ihr ein paar Diagnoseläufe bei dem Hauptkuppelgenerator der Sturmsäule am östlichen Rand in der Biokuppel Sutheron durchführt.", progress = "Habt Ihr die Diagnoseergebnisse?", completion = "Diese Ergebnisse entsprechen denen von Mehrdad genau, aber warum? Der einzige Grund, den ich mir vorstellen kann, ist, dass etwas von der Ausrüstung der Kuppelgeneratoren kaputtgegangen ist oder fehlt. Das würde dazu führen, dass die Kuppeln stark geschwächt werden und aus dem Gleichgewicht geraten, so wie es in der Diagnose deutlich wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10425] = {title = "Ausbruch aus dem Stützpunkt", objective = "Begleitet den gefangenen Vorposten des Protektorats zurück zum Wachposten des Protektorats im Nethersturm.", description = "K'aresh sei Dank! Er hätte mich in Stücke gerissen!\n\nIch bin ein Soldat des Protektorats, Fleischling. Meine Truppe wurde vor etwa 10 Tagen auf eine Aufklärungsmission geschickt. Als wir uns über die oberen Regionen dieser Insel bewegten, wurden wir von einer Gruppe des Astraleums überfallen. Zumindest denke ich, dass es das Astraleum war. Sie hatten die gleichen Energiefarben, aber ihre Bandagen sahen irgendwie leer aus.\n\nSie haben nur Tyralius verschont. Ich glaube, sie haben ihn in ein Gefängnis eingesperrt.\n\nIch muss zurück zum Wachposten des Protektorats! Könnt Ihr mich dorthin begleiten?", progress = nil, completion = "&lt;Kommandant Ameer scheint zufrieden zu sein.&gt;\n\nGut gemacht, Fleischling! Dieser Soldat ist vielleicht der Schlüssel zur Vereitelung aller Pläne des Astraleums.", rewards = "Sattelgurt des RutengängersWilde BänderSchiftung des ProtektoratsPlattenstampfer des SternrufersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10426] = {title = "Flora der Biokuppel", objective = "Benutzt den Energiefeldmodulator bei den Farahlonpeitschern. Beobachtet die Ergebnisse und meldet Euch bei Aurine Mondflamm in der Sturmsäule zurück, wenn Ihr 10 Tests durchgeführt habt.", description = "Schaut Euch nur um, <Klasse>! Ist es nicht erstaunlich? Natürlich ist diese unglaubliche Fülle von Leben ein Nebenprodukt der Kuppeln der Astralen, aber stellt Euch nur vor, was diese Technologie in den Händen der Expedition bedeuten könnte.\n\nIch bereite mich darauf vor, mit den Astralen zu verhandeln, um Zugang zu ihrer Technologie zu bekommen, aber ich wüsste zuvor gerne genauer, welche Auswirkungen sie auf das pflanzliche Leben hat.\n\nIch habe ein Gerät gebaut, mit dem ich die Energien auf die Peitscher in dieser Gegend richten kann. Wärt Ihr so nett und würdet es für mich ausprobieren und mir die Ergebnisse mitteilen?", progress = "Habt Ihr schon versucht, die Energie der Kuppel zu fokussieren?", completion = "Oh je! Die Energie der Kuppel zu bündeln hat zur Folge, dass die Kreaturen bis zu dem Punkt wachsen, an dem sich eine große Aggressivität entwickelt. Wenn wir die Möglichkeit bekommen, diese Technologie einzusetzen, müssen wir sie auf jeden Fall richtig einstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10427] = {title = "Fauna der Biokuppel", objective = "Markiert 12 Talbuks für Aurine Mondflamm in der Sturmsäule. Ihr könnt mit dem Talbukmarkierer sowohl Talbukböcke als auch Talbukkühe markieren.", description = "Eure Arbeit bei den Peitschern stellte sich als erstaunliche Information heraus, aber ich frage mich, ob das auch für die Tiere gilt.\n\nIch fürchte jedoch, dass es schwieriger wird, Informationen über die Talbuks zu sammeln, als über die Peitscher.\n\nMit diesem Markierungsgerät könnt Ihr einen geschwächten Talbuk schlafen legen und ihn mit einer Markierung versehen, mit deren Hilfe ich das Tier während seiner Wachstumsphase verfolgen kann. Der Mechanismus des Markierungsgeräts funktioniert erst, wenn der Talbuk schon sehr erschöpft ist.", progress = "Konntet Ihr ausreichend viele Talbuks markieren?", completion = "Ausgezeichnete Arbeit. Ich werde die, die Ihr markiert habt, genau im Auge behalten, um zu beobachten, ob sie genauso schnell wie die anderen Lebensformen in der Kuppel wachsen.\n\nMit der richtigen Überwachung könnten wir diese Technologie benutzen, um die zerstörten Gegenden in der Scherbenwelt und Azeroth wiederzubeleben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10428] = {title = "Der vermisste Fischer", objective = "Sucht Cowlen bei den südöstlichen Docks der Silbermythosinsel vor der Küste der Azurmythosinsel.", description = "Von fiebrigen Träumen geplagt sprach unser verletzter Gast von einem Fischer, Cowlen, der auf der Silbermythosinsel im Südwesten vor der Küste der Azurmythosinsel, in Schwierigkeiten war.\n\nNach all den Geschehnissen hier hatte keiner die Gelegenheit, nachzuschauen, aber ich mache mir doch ein paar Sorgen. Vielleicht könnt Ihr etwas tun, <Name>?", progress = nil, completion = "Meine Familie... Was habe ich getan... Was hätte ich tun sollen?\n\nWarum werde ich so bestraft?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10429] = {title = "Wenn die Natur zu weit geht", objective = "Aurine Mondflamm in der Sturmsäule möchte, dass Ihr ihr ein titanisches Hydraherz bringt.", description = "Die Technologie der Kuppeln ist so mächtig! Sicher gibt es Grenzen, die wir nicht zu überschreiten wagen, <Name>.\n\nWesen, die zu schnell oder zu groß wachsen, können genauso schlimm sein wie eine unfruchtbare Landschaft.\n\nIch habe Gerüchte gehört, dass sich genau so eine Kreatur im Teich im Osten herumtreibt. Die Händler der Astralen wollen die übergroße Hydra aus Spaß erlegen, aber ich habe etwas anderes mit dem Riesen vor. Bringt mir das Herz dieser Kreatur, damit ich es untersuchen kann.", progress = "Habt Ihr eine Probe von der monströsen Hydra?", completion = "&lt;Aurine nimmt das Herz an sich.&gt;\n\nSogar für eine Kreatur von dieser Größe ist das Herz viel zu groß. Es musste sich sehr anstrengen, um mit dem riesigen Körper Schritt halten zu können. Ich habe keine Zweifel, dass sie nach der Hälfte ihrer normalen Lebenserwartung gestorben wäre.\n\nTrotz dieser Risiken bin ich entschlossen, die Astralen davon zu überzeugen, ihre Technologie mit anderen zu teilen. Es ist zu viel versprechend, als dass wir jetzt aufgeben sollten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10430] = {title = "Den Prototyp testen", objective = "Bringt das Testreparaturgerät zu Tashar in der Biokuppel Fernfeld im Nethersturm.", description = "Ich habe an einem tragbaren Reparatursatz für den Generator gearbeitet, der in den kälteren Regionen, in denen das Konsortium Geschäfte macht, funktioniert. Zugegeben, er war nicht für den Nethersturm entwickelt worden, aber wir sollten trotzdem keine Probleme damit haben.\n\nIch habe bereits einen Test mit einem meiner besten Techniker bei der Biokuppel Fernfeld hinter dem Netherstein im Nordosten vereinbart. Bringt diesen Prototypen zu Tashar. Er wird wissen, was damit zu tun ist. Wenn er funktioniert können wir ihn benutzen, um die Schildgeneratoren bei den größeren Kuppeln zu verstärken.", progress = "Sieht aus, als hättet Ihr den Prototypen. Hat Ghabar Euch geschickt?", completion = "Er sieht ein wenig merkwürdig aus. Ghabar hatte sicher nicht den Nethersturm im Hinterkopf, als er ihn entwickelt hat.\n\nSchaut nicht so überrascht drein, &lt;Name&gt;. Der Nethersturm ist harmlos im Vergleich zu einigen Orten, an denen ich gearbeitet habe. Doch eine kaputte Kuppel ist immer ein Grund zur Sorge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10431] = {title = "Hilfe von außen", objective = "Geht zu Tulumans Landeplatz, nördlich von Area 52, und sprecht mit Kaylaan.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Die Befehle des Sonnenzorns bestätigen den Verdacht, dass Kael'thas bei dem Bau und dem Betrieb der Manaschmieden Hilfe von außen bekommen hat. Wer dahinter steckt, ist immer noch ein Geheimnis, doch wir können es wahrscheinlich in der Manaschmiede Ara herausfinden.\n\nIch habe eine Gruppe meiner Leute losgeschickt, um die Gegend zu erkunden. Geht zu Tulumans Landeplatz nördlich von hier und sprecht mit Kaylaan. Hört Euch an, was er in der Manaschmiede Ara gefunden hat. Findet heraus, wer die Armee des Sonnenzorns unterstützt, und kümmert Euch um sie.", progress = nil, completion = "Seid Ihr die ganze Hilfe, die Orelis schickt? Er muss eine hohe Meinung von Euch haben.\n\nLasst es uns hinter uns bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10432] = {title = "Eindeutige Beweise", objective = "Besorgt Euch 8 Befehle von Kael'thas von den Dämonen bei der Manaschmiede Ara und bringt sie zu Spionagemeister Thalodien in Area 52.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Wie Ihr sicher bemerkt habt, laufen in der Manaschmiede Ara überall Diener der Brennenden Legion herum. Kael'thas ist einen Bund mit der Brennenden Legion eingegangen. Er muss gehört haben, dass Illidan dem Wahnsinn verfallen ist, und den Meister gewechselt haben.\n\nWenn die Seher dafür einen stichhaltigen Beweis hätten, wäre das ein deutlicher politischer Vorteil für sie. Ich weiß genau, dass die Streitkräfte der Legion bei der Manaschmiede hier Befehle haben, die Kaels Siegel tragen.\n\nBesorgt diese Befehle und bringt sie zu Thalodien.", progress = "Nun? Was hatte Theledorn zu sagen?", completion = "Das ist eine große Sache, &lt;Name&gt;. Sehr groß!\n\nVoren'thal möchte sicher so früh wie möglich davon erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10433] = {title = "Den Schein wahren", objective = "Bringt 10 Reißzahnpelze zu Shauly Pore im Mittelreichposten.", description = "Die Astralen sind sehr klug und aufmerksam, daher ist es kein Zufall, dass ich hier als einfacher Fellhändler auftrete. Tatsächlich wurde ich von Area 52 hierher geschickt, um die Technologie, die die Astralen in ihren Biokuppeln einsetzen, zu bewerten.\n\nIch würde gerne Eure Hilfe in Anspruch nehmen, <Klasse>. Wir wurden darum gebeten, wo es nur geht andere Völker als Goblins als Spione einzusetzen.\n\nIch möchte, dass Ihr mir als Jäger verkleidet ein paar Reißzahnpelze bringt. Ihr findet die Luchse überall bei der Biokuppel Mittelreich.", progress = "<Shauly hebt die Stimme, um die Aufmerksamkeit der Astralen in der Nähe zu erregen.>\n\nHabt Ihr ein paar Pelze für mich?", completion = "&lt;Shauly gibt vor, die Pelze zu bewundern.&gt;\n\nSie sind wundervoll, wirklich wundervoll! Ich werde Euch den besten Preis dafür bezahlen! Was kosten mich Eure Dienste?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10434] = {title = "Das dynamische Duo", objective = "Sprecht mit Audi der Nadel auf der Sturmsäule im Nethersturm.", description = "Ausgezeichnete Arbeit.\n\n<Shauly zwinkert Euch zu.>\n\nIch glaube, sie kaufen es uns ab. Wenn ich Euch jetzt zu meinen Verbündeten in der Sturmsäule schicke, werden sie nicht misstrauisch werden.\n\nHaltet nach Aktion Jaxon und Audi der Nadel Ausschau. Sie werden Euch alles sagen, was Ihr wissen müsst. Sagt ihnen, dass Shauly Euch geschickt hat.", progress = nil, completion = "&lt;Ihr stellt Euch vor und sagt, dass Shauly Euch geschickt hat.&gt;\n\nAh, ja, wir haben jemanden erwartet, der uns dabei hilft, äh -- ein paar, mh, Güter zu transportieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10435] = {title = "Die Waren zurückholen", objective = "Audi die Nadel bei der Sturmsäule möchte, dass Ihr 10 Kuppelgeneratorsegmente besorgt.", description = "<Audi sieht sich um und senkt die Stimme.>\n\nIch bin sicher, dass Shauly Euch ein wenig von unserer Arbeit hier erzählt hat. Als Jaxon und ich draußen im Feld auf der Jagd waren, haben wir Teile von den Generatoren der Biokuppeln der Astralen gesammelt und sie in den Nestern unserer Beute, den Raptoren bei der Biokuppel Fernfeld, versteckt.\n\nDas ist eine abgelegene Gegend nordöstlich der Sturmsäule, in der Nähe des Nethersteins. Ich nehme nicht an, dass Ihr dort auf viele Astrale treffen werdet, aber würdet Ihr uns helfen, die Kuppelgeneratorenteile zu sammeln?", progress = "Habt Ihr alles gesammelt?", completion = "Ausgezeichnete Arbeit! Der schwierigste Teil unseres Projekts ist damit erledigt. Jetzt müssen wir nur noch einen Weg finden, diese hier zurück zu Area 52 zu bringen und auch das Interesse der Expedition des Cenarius zu wecken. Es sollte hier genug geben, um unsere eigenen Interessen zu decken und noch ein wenig Gewinn zu machen.", rewards = "Audis bestickte StiefelAgentengürtel von B.U.M.M.Schulterstücke des JenseitsArmschienen des AußenagentenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10436] = {title = "Freie Bahn!", objective = "Tashar bei der Biokuppel Fernfeld möchte, dass Ihr 12 Sichelzahnraptoren tötet.", description = "Bevor wir den Test beginnen können, müssen wir sicherstellen, dass das Gebiet frei von allem ist, was uns dabei stören könnte. In unserem Fall sind das diese zu groß geratenen Echsen.\n\n<Tashar zeigt auf die Sichelzahnraptoren.>\n\nEs ist nicht voraussehbar, was passiert, wenn einer von ihnen auf die Idee kommt, genüsslich in den Generator zu beißen, während er gerade auflädt. Ich habe in all den Jahren als Techniker schon viele merkwürdige Dinge gesehen, darunter auch ein paar Mutationen, die einst ganz normale Tiere waren.", progress = "Habt Ihr das Testgelände bereinigt?", completion = "Gut gemacht. Wie es aussieht, ist alles in Ordnung. Wir können anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10437] = {title = "Anleitung zur Zerstörung", objective = "Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 8 Fragmente von Dimensius besorgt.", description = "Auf der Manaschmiede Ultris befindet sich der Riss im Nether, durch den Dimensius, der Leerenfürst, gekommen ist. Dieser Riss bildet eine Verbindung zwischen Dimensius und der Leere und macht ihn unverwundbar. Wenn es uns gelingt, diese Energieleitung, mit der Dimensius sich aus dieser Existenzebene zurückziehen kann, zu verschließen, können wir sie und Dimensius vernichten.\n\nDazu müsst Ihr zunächst Fragmente von Dimensius von den Leerkreaturen, die für ihn die Drecksarbeit erledigen, sammeln.", progress = "Habt Ihr genügend Fragmente gesammelt?", completion = "Ausgezeichnet. Mit diesen Fragmenten können wir die Bombe einstellen, die die Leerenergieversorgung auf der Manaschmiede Ultris zerstören kann. Dann wird Dimensius' Verbindung zur Leere unterbrochen und er kann sich nicht mehr verteidigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10438] = {title = "Auf netherischen Schwingen", objective = "Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr den Phasenstörer bei der Leerenleitung auf der Manaschmiede Ultris benutzt. Sendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten. Die Entladungen des Phasenstörers werden automatisch das Ziel treffen, solange Ihr nahe genug seid, um ihn zu benutzen.\n\nKehrt zu Professor Dabiri zurück, wenn Ihr erfolgreich wart!", description = "Hier ist es, <Name>. Nehmt den Phasenstörer und steigt auf! Der Netherdrachen des Protektorats wird Euch nahe genug an Ultris heranfliegen, damit Ihr den Störer auf die Leerleitung werfen könnt.\n\nSendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten!\n\nWenn Ihr bereit seid, sprecht mit dem Netherdrachen und er wird mit Euch in die Lüfte steigen.\n\nWenn Ihr das Ziel verfehlt, müsst Ihr mehr Bomben von mir besorgen, bevor Ihr weitermachen könnt.", progress = "Habt Ihr das Ziel getroffen?", completion = "Es ist Zeit zuzuschlagen! Nun, da der Riss fort ist, kann Dimensius mit Kraft und Magie angegriffen werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10439] = {title = "Dimensius der alles Verschlingende", objective = "Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr mit Hauptmann Saeed sprecht, seiner Armee zur Manaschmiede Ultris folgt und Dimensius den alles Verschlingenden tötet!", description = "Eure mutigen Taten haben Ameer zum handeln bewegt! Er hat Hauptmann Saeed und die Rächer Aufstellung nehmen lassen!\n\nJetzt müssen wir nur noch Dimensius vernichten.\n\nWenn Ihr bereit seid, lasse ich Saeed rufen. Wenn er nicht gerade einen anderen Auftrag ausführt, wartet er östlich von hier auf Eure Befehle.\n\nLasst ihn wissen, wenn Ihr bereit seid zu kämpfen, damit er seine Truppen in Bewegung setzen kann.\n\nViel Glück, Fleischling! Wir jagen Dimensius schon seit tausend Jahren!", progress = "Was gibt es Neues vom Fürst der Leere?", completion = "Seit tausend Jahren kennen wir nur noch Krieg. Wir haben unser Volk gegen die Angriffe der Leerwesen und der Astralen verteidigt.\n\nJetzt ist einer unserer schlimmsten Feinde gefallen - endlich.\n\nIch überbringe Euch den Dank von Milliarden von Astralen, Fleischling.", rewards = "Reif des SternrufersTunika des LeerenkämpfersPlattenbeinschützer des SternrufersAuf Euch wartet eine dieser Belohnungen:\n\nDabiris Mysterium\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10440] = {title = "Erfolg!", objective = "Kehrt zur Sturmsäule zurück und sprecht mit Ghabar im Nethersturm.", description = "Der Test war ein großer Erfolg! Wir können das Gerät benutzen, um die Kuppeln zu reparieren.\n\nBerichtet in der Sturmsäule von den Testergebnissen und lasst Ghabar wissen, dass ich ein Muster in den Schäden an den Schildgeneratoren entdeckt habe. Wichtige Teile der Generatoreinheiten sind an verschiedenen Orten verschwunden. Das ist kein Zufall, <Name>, kein technischer Fehler. Wir werden bestohlen.", progress = nil, completion = "Ich setzte meine Techniker sofort auf die Reparaturen an.\n\nTashars Vermutung, dass es sich um Sabotage handelt, macht mir jedoch Sorgen. Ich kann mir nicht vorstellen, dass jemand waghalsig genug wäre, unsere Technologie zu stehlen. Zumindest niemand, der weiß, wozu wir fähig sind. Vielleicht ist es an der Zeit, die Sturmsäule abzuriegeln.", rewards = "Gamaschen der konzentrierten MachtSchulterstücke der NexuswacheGoldbeschlagene ManschettenAuf Euch wartet eine dieser Belohnungen:\n\nHimmlische Eingebung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10441] = {title = "Die Waren unters Volk bringen.", objective = "Sprecht mit Aurine Mondflamm unten in der Sturmsäule im Nethersturm.<Audi senkt die Stimme wieder.>\n\nJetzt, da wir die Waren haben, werde ich die meisten davon nach Area 52 schicken. Wir haben hier mehr, als wir für einen Generator brauchen, was uns eine perfekte Geschäftsmöglichkeit eröffnet.\n\nIch habe gesehen, dass die Vertreterin der Expedition des Cenarius verhandeln will. Ich möchte, dass Ihr sie wissen lasst, dass wir ihr das, was sie sucht, zu einem günstigen Preis geben können. Es gibt kein Grund für sie, sich weiter mit diesen betrügerischen Astralen herumzuschlagen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Audi senkt die Stimme wieder.>\n\nJetzt, da wir die Waren haben, werde ich die meisten davon nach Area 52 schicken. Wir haben hier mehr, als wir für einen Generator brauchen, was uns eine perfekte Geschäftsmöglichkeit eröffnet.\n\nIch habe gesehen, dass die Vertreterin der Expedition des Cenarius verhandeln will. Ich möchte, dass Ihr sie wissen lasst, dass wir ihr das, was sie sucht, zu einem günstigen Preis geben können. Es gibt kein Grund für sie, sich weiter mit diesen betrügerischen Astralen herumzuschlagen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10442] = {title = "Dem Posten des Cenarius helfen", objective = "Falknerin Drenna Flusswind möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet.", description = "<Klasse>, es gibt hier eine Tauren namens Thiah Rotmähne, die uns ständig um Hilfe anfleht. Sie gehört zur Expedition des Cenarius, die einen kleinen Posten im Westen, auf der südlichen Seite der Straße in Richtung Zangarmarschen, errichtet hat.\n\nWenn Ihr beim Dornnebelhügel angekommen seid, seid Ihr zu weit gegangen.\n\nKönntet Ihr vielleicht dort hingehen und nachschauen, was sie braucht? Ich möchte Waldläuferhauptmann Venn'ren nicht mit solchen Kleinigkeiten belästigen.", progress = nil, completion = "Oh, gut, Ihr müsst die Hilfe sein, die ich vor Wochen von der Falkenwacht angefordert habe.\n\nNun, jetzt seid Ihr hier und es gibt viel zu tun. Ich habe genau das Richtige für Euch für den Anfang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10443] = {title = "Dem Posten des Cenarius helfen", objective = "Amaan der Weise möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet.", description = "Der Zirkel des Cenarius hat eine Expedition in die Scherbenwelt geschickt. So weit ich verstanden haben, sind sie hier, um zu untersuchen, was passiert ist, und wenn möglich die Schäden rückgängig zu machen.\n\nSie haben einen kleinen Posten im Westen, auf der südlichen Seite der Straße in Richtung Zangarmarschen, errichtet.\n\nWenn Ihr den Dornnebelhügel erreicht, seid Ihr zu weit gegangen.\n\nKönnt Ihr vielleicht dort hingehen und schauen, wie Ihr ihnen helfen könnt? Sprecht mit Thiah Rotmähne. Sie hat uns um Hilfe gebeten.", progress = nil, completion = "Oh, gut, Ihr müsst die Hilfe sein, die ich vor Wochen vom Tempel von Telhamat angefordert habe.\n\nIch bin froh, dass Ihr hier seid; es gibt viel zu tun. Ich habe genau das Richtige für Euch für den Anfang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10444] = {title = "Meldung bei Allerias Posten", objective = "Jenai Sternwisper möchte, dass Ihr Euch bei Leutnant Meridian in Allerias Posten in den Wäldern von Terokkar meldet.", description = "Das erfordert sofortiges Handeln!\n\nWir haben jemanden da draußen, der sich noch näher am Posten der Feuerschwingen befindet. Ich möchte, dass Ihr mit ihm sprecht. Er weiß sicher besser, was wir als Nächstes tun sollten.\n\nMeldet Euch bei Leutnant Meridian bei Allerias Posten und setzt ihn von der Lage in Kenntnis. Ihr findet den Posten im Nordosten am südlichen Ufer des Flusses, direkt südlich vom Posten der Feuerschwingen.\n\nBeeilt Euch, <Name>!", progress = nil, completion = "Bombenteile. Dann war mein Verdacht also berechtigt. Ich hätte mir gewünscht, dass ich falsch liege.\n\nOk, wir haben also eine grausame Aufgabe vor uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10445] = {title = "Die Phiolen der Ewigkeit", objective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole von Lady Vashj im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.\n\nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.", progress = "Ich verlange Unmögliches von Euch, und doch erwarte ich, dass es Euch gelingt. Es hängt viel davon ab.", completion = "Sogar in diesem kleinen Rest des Wassers aus dem Brunnen der Ewigkeit schlummert unglaubliche Macht.\n\nIch kann ganz deutlich jeden Moment in der Zeit, der mit dem Berg Hyjal in Verbindung steht, sehen... die Erschaffung des zweiten Brunnens der Ewigkeit, Illidans Gefangennahme, die Verzauberung des Weltenbaums und... ja! Die Schlacht um den Berg Hyjal.\n\nWir müssen uns beeilen, die Linien der Zeit sind noch nicht in Sicherheit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10446] = {title = "Der finale Code", objective = "Leutnant Meridian möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar zurück.", description = "Sie bauen eine zweite Manabombe im Hof! Meine Agenten berichten, dass Sharth Voldoun, der Zuständige des Projekts im Posten der Feuerschwingen, den finalen Code der Bombe haben muss.\n\n<Name>, Ihr müsst dorthin zurückkehren und den letzten Code von ihm besorgen. Er hält sich auf der Spitze der höchsten Säule auf.\n\nBringt den finalen Code zu der Manabombe, an der sie im mittleren Hof arbeiten, und gebt ihn ein.\n\nNur dann können wir sicher sein, dass Allerias Feste gerettet ist.", progress = nil, completion = "IHR HABT ES GESCHAFFT! IHR HABT ALLERIAS FESTE GERETTET!!\n\nJetzt, da ihre Streitkräfte dezimiert sind, ihr Anführer tot und die Manabombe zerstört ist, können wir alle etwas aufatmen.\n\nNie zuvor habe ich solche Selbstlosigkeit, solchen Heldenmut gesehen! Bitte, nehmt dies in unser aller Namen an!", rewards = "Brustplatte des SphärenjägersBlutfeuergamaschenUralte Kapuze von TerokkarSchneide der UnabwendbarkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10447] = {title = "Der finale Code", objective = "Unteroffizier Chawni möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Tooki in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", description = "Sie bauen eine zweite Manabombe im Hof! Meine Agenten berichten, dass Sharth Voldoun, der Zuständige des Projekts im Posten der Feuerschwingen, den finalen Code der Bombe haben muss.\n\n<Name>, Ihr müsst dorthin zurückkehren und den letzten Code von ihm besorgen. Er hält sich auf der Spitze der höchsten Säule auf.\n\nBringt den finalen Code zu der Manabombe, an der sie im mittleren Hof arbeiten, und gebt ihn ein.\n\nNur dann können wir sicher sein, dass die Steinbrecherfeste gerettet ist.", progress = nil, completion = "IHR HABT ES GESCHAFFT! IHR HABT DIE STEINBRECHERFESTE GERETTET!!\n\nJetzt, da ihre Streitkräfte dezimiert sind, ihr Anführer tot und die Manabombe zerstört ist, können wir alle etwas aufatmen.\n\nNie zuvor habe ich solche Selbstlosigkeit, solchen Heldenmut gesehen! Bitte, nehmt dies in unser aller Namen an!", rewards = "Brustplatte des SphärenjägersBlutfeuergamaschenUralte Kapuze von TerokkarSchneide der UnabwendbarkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10448] = {title = "Meldung beim Steinbrecherlager", objective = "Tooki möchte, dass Ihr Euch bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar meldet.", description = "Das erfordert sofortiges Handeln!\n\nWir haben jemanden da draußen, der sich noch näher am Posten der Feuerschwingen befindet. Ich möchte, dass Ihr mit ihr sprecht. Sie weiß sicher besser, was wir als Nächstes tun sollten.\n\nMeldet Euch bei Unteroffizier Chawni im Steinbrecherlager und setzt sie von der Lage in Kenntnis.\n\nNehmt die Straße nach Norden aus der Feste heraus. Ab der Mitte von Tuurem müsst Ihr der Straße nach Osten folgen. Ihr findet das Lager am Ufer des Flusses, der direkt südwestlich des Postens der Feuerschwingen liegt.\n\nBeeilt Euch, <Name>!", progress = nil, completion = "Bombenteile. Dann war mein Verdacht also berechtigt. Ich hätte mir gewünscht, dass ich falsch liege.\n\nOk, wir haben also eine grausame Aufgabe vor uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10449] = {title = "Apothekerin Zelana", objective = "Vurtok Axtbrecher in Thrallmar möchte, dass Ihr die Blutprobe eines Knochenmalmers zu Apothekerin Zelana im Häschersturz bringt.", description = "Apothekerin Zelana hat Untersuchungen bezüglich der Kreaturen auf der Höllenfeuerhalbinsel angestellt und ist sehr an einer Probe des Blutes interessiert, das Ihr für mich gesammelt habt. Mit ein wenig Glück wird sie herausfinden können, was die Haut dieser durchgedrehten Knochenmalmer rot werden ließ!\n\nZelana befindet sich im Häschersturz, südöstlich von Thrallmar. Folgt der Straße nach Osten. Wenn Ihr einen kaputten, grünlich leuchtenden Haufen Metall seht, seid Ihr angekommen. Sie hat ihr Lager hinter den Wyvern aufgeschlagen.", progress = "Es ist mir eine Ehre, der Horde dienen zu können. Wie kann ich Euch helfen?", completion = "Ah ja. Das Blut des Knochenmalmerklans. Ich interessiere mich sehr für diese Orcs... sie sind zwar immer noch die verkommenen Feinde unserer Vergangenheit, aber ihre Stärke und Macht ist größer, als ich gedacht habe...\n\nNun, wollen wir beginnen, oder?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlagge setzen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10450] = {title = "Blut der Knochenmalmer", objective = "Bringt 12 Phiolen mit Knochenmalmerblut zu Vurtok Axtbrecher in Thrallmar.", description = "Knochenmalmer! Sie sollen alle sterben! Der Anblick ihrer roten Haut und ihrer Verkommenheit bringt mein Blut zum kochen!\n\nIch habe einen Auftrag für Euch, <Name>. Tötet die Orcs der Knochenmalmer und sammelt ihr bösartiges Blut. Es gibt eine Apothekerin, die vielleicht herausfinden kann, wie diese Orcs der Verderbnis der Dämonen anheim fallen konnten, eine Verderbnis, derer wir uns vor so kurzer Zeit erst entledigen konnten.\n\nDie Knochenmalmer streunen in der Nähe der zerstörten Kriegsmaschinerien entlang des Pfads der Ehre im Süden herum. Kehrt zu mir zurück, wenn Euer Auftrag erfüllt ist.", progress = "Habt Ihr Euch den Knochenmalmern gestellt, <Name>? Ich hoffe, dass Ihr ihr Blut in rauen Mengen vergossen habt.", completion = "Hah! Ihr habt also die Knochenmalmer, unsere verkommenen Vettern getroffen. Gut gemacht, &lt;Name&gt;. Ich bedauere nur, dass nicht mehr von ihnen ihr Leben lassen und ihr Blut vergießen konnten, um meinen Zorn zu besänftigen.", rewards = "Schlitzmesser des HöllenfeuersRute der VerwüstungEisensternrepetierarmbrustRundschild des ErdrutschesAdamantitviereckschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10451] = {title = "Flucht aus der Zisterne der Echsennarbe", objective = "Begleitet Erdheilerin Wilda aus der Zisterne der Echsennarbe hinaus und sucht dann Erdheiler Torlok beim Altar der Verdammnis am westlichen Rang der Hand von Gul'dan auf.", description = "Der Erdenmutter sei Dank! Ich habe mich vor ein paar Tagen von den anderen getrennt. Ich wollte der Quelle der Veränderung des Wassers, die wir spüren, auf den Grund gehen. Meine Suche führte mich zur Echsennarbe, wo ich herausgefunden habe, dass die Naga die Wasservorräte des Schattenmondtals verderben!\n\nUnglücklichweise hat man mich entdeckt und gefangen genommen. Nicht auszudenken, welch grausame Dinge sie mit mir vorhatten!\n\nWir müssen hier weg. Helft mir zu fliehen und sucht dann Torlok beim Altar der Verdammnis auf.", progress = nil, completion = "Gelobt sei die Erdenmutter! Ich bin mir sicher, dass Wilda nach Hause finden wird. Bitte nehmt dies als Zeichen unserer Wertschätzung.", rewards = "Schmetterarmschienen des ErdheilersUmkehrungsfäuste des ErdheilersPurpurschiftung des ErdheilersPlattenstiefel des ErdheilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10452] = {title = "DON'T USE [PH] Fel Orc 1", objective = "[PH Fel Orc 1.[PH Fel Orc 1.", description = "[PH Fel Orc 1.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10453] = {title = "DON'T USE [PH] Fel Orc bread", objective = "[PH Fel Orc bread[PH Fel Orc bread", description = "[PH Fel Orc bread", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10455] = {title = "Die nahende Wildnis", objective = "Erlegt 12 Hainpirscherluchse.", description = "Wir haben den Lebenden Hain sehr schnell zum Wachsen gebracht, aber nun haben wir die Kontrolle über die Luchse verloren.\n\nEinst war ihre Population gleichmäßig, aber nun kommen die Hainpirscherluchse immer näher an Sylvanaar heran. In letzter Zeit gab es schon einige unerfreuliche Zwischenfälle.\n\nIch nehme an, dass die Arakkoa vom Lashhversteck dahinter stecken, aber zunächst sind die Luchse selbst unser Problem.\n\nIch wäre Euch sehr dankbar, wenn Ihr uns dabei helfen würdet, mit dieser Lage fertigzuwerden.", progress = nil, completion = "Das ging schnell. Seid Ihr sicher, dass Ihr so viele getötet habt, wie es nötig war?\n\nGut, dann könnt Ihr uns bei einer weiteren Angelegenheit helfen, wenn Ihr möchtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10456] = {title = "Marodierende Wölfe", objective = "Beschafft Euch 4 Schwänze eines Terrorwolfs der Donnerfürsten.", description = "Die abscheulichen Völker der Horde haben eine alte Siedlung im Osten eingenommen. Sie haben ein großes Rudel von Terrorwölfen mitgebracht, die sie gerne als Reittiere und Wachhunde einsetzen.\n\nDiese \"Wachhunde\" haben jedoch begonnen, hinter der Brücke, die uns voneinander trennt, Schaden anzurichten. Sie belästigen unsere Feendrachen, die für die Bestäubung unseres Waldes unersetzlich sind.\n\nNehmt den östlichen Ausgang, um die Brücke über der Blutschlägerklamm, die zum Zackengrat im Osten führt, zu überqueren, und bringt mir ihre Schwänze!", progress = "Ich kann nicht deutlich genug sagen, dass diese Terrorwölfe der Donnerfürsten erledigt werden müssen. Ihre bloße Anwesenheit stört das Gleichgewicht des lebenden Hains und all unsere Arbeit hier.", completion = "Gut. Ich werde schauen, ob ich aus diesen Schwänzen etwas Nützliches machen kann.\n\nDie Horde wird ohne Zweifel einen Weg finden, Ihr Wolfsrudel wieder zu vergrößern, aber nun können wir etwas freier durchatmen.\n\n&lt;Name&gt;, wenn Ihr dazu bereit seid, habe ich eine letzte Bitte an Euch, um Sylvanaar und den lebenden Hain zu verteidigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10457] = {title = "Die Eigenen schützen", objective = "Benutzt Rinas Zweig bei 5 Hainsetzlingen, um Verteidigung für den Lebenden Hain herbeizurufen.", description = "Trotz der guten Arbeit, die Ihr geleistet habt, bin ich immer noch der Meinung, dass der Lebende Hain mehr Schutz braucht.\n\nBitte, nehmt diesen kleinen Zweig. Ich habe ihn mit der Macht der Natur verstärkt. Wenn er bei den Setzlingen, die ich im Hain gepflanzt habe, eingesetzt wird, ruft er einen Sturm herbei, der sie schnell zu großen Treantverteidigern heranwachsen lässt.\n\nDiese Treants sind für die Verteidigung des Waldes unverzichtbar, besonders, wenn man nicht für immer in Sylvanaar leben möchte.", progress = "Wie geht es mit der Verstärkung der Verteidigung des lebenden Hains voran?\n\nSolange wir nicht wissen, was die Arakkoa im Lashhversteck vorhaben und die Horde sich auf der anderen Seite der Klamm befindet, habe ich Angst, dass wir unser neues Heim und unsere Arbeit nicht mehr verteidigen können, wenn wir nicht bald handeln.", completion = "Nun, da Ihr die Verteidigung des Hains verstärkt habt, fühle ich mich viel sicherer.\n\nIhr habt Euch mehr als nur unseren Dank und unsere Wertschätzung verdient.\n\nMir fällt gerade ein, dass es da noch etwas gibt, bei dem ich Eure Hilfe brauchen könnte.", rewards = "Handschuhe von SylvanaarSchulterpolster des Lebenden HainsBeschützerstiefelArmbinden der SchildwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10458] = {title = "Wütende Geister des Feuers und der Erde", objective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 8 Erdenseelen und 8 Feuerseelen einzufangen.", description = "Wir müssen versuchen, die Dinge zu ändern. Wir müssen mit den Elementen dieser Gegend kommunizieren und schauen, ob wir etwas tun können!\n\nIch gebe Euch das Totem der Geister, <Volk>. Wenn Ihr einen wütenden Elementargeist in der Nähe des Totems umbringt, wird es die Seele des Elementars aufnehmen. Ihr müsst viele Seelen mithilfe des Totems einfangen, bevor Ihr zu mir zurückkehrt.\n\nSammelt zuerst die Seelen der Geister des Feuers und der Geister der Erde. Kehrt zu mir zurück, wenn das Totem voll ist.", progress = "Ich fürchte, dass es keine Hoffnung für dieses Land gibt.", completion = "Wenn alle Elementarseelen dieser Gegend in diesem Totem eingefangen sind, werden wir mit ihnen reden und herausfinden, ob wir etwas für das Schattenmondtal tun können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10459] = {title = "Von der Expedition des Cenarius verehrt", objective = "Ysiel Windsänger bei der Zuflucht des Cenarius möchte, dass Euch einen respektvollen Ruf bei der Expedition des Cenarius verdient.", description = "Eure Erfolge sind uns aufgefallen, <Name>. Was Ihr für uns getan habt geht weit über das, was wir von Verbündeten erwarten, hinaus.\n\nIch habe eine besondere Bitte an Euch, aber zunächst muss ich Eure Hingabe testen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10460] = {title = "Das Versprechen des Verteidigers", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10461] = {title = "Das Versprechen des Bewahrers", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10462] = {title = "Das Versprechen des Helden", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10463] = {title = "Das Versprechen des Weisen", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10464] = {title = "Das Gelöbnis des Weisen", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt Euer Versprechen gegeben, <Klasse>. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", progress = "Ihr leistet uns weiterhin gute Dienste, <Name>.", completion = "Ihr habt Euch als würdig erwiesen, &lt;Volk&gt;. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus ist nicht so leicht zu erlangen.", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10465] = {title = "Das Gelöbnis des Bewahrers", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt Euer Versprechen gegeben, <Klasse>. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", progress = "Ihr leistet uns weiterhin gute Dienste, <Name>.", completion = "Ihr habt Euch als würdig erwiesen, &lt;Volk&gt;. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus ist nicht so leicht zu erlangen.", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10466] = {title = "Das Gelöbnis des Helden", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt Euer Versprechen gegeben, <Klasse>. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", progress = "Ihr leistet uns weiterhin gute Dienste, <Name>.", completion = "Ihr habt Euch als würdig erwiesen, &lt;Volk&gt;. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus ist nicht so leicht zu erlangen.", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10467] = {title = "Das Gelöbnis des Verteidigers", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt Euer Versprechen gegeben, <Klasse>. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", progress = "Ihr leistet uns weiterhin gute Dienste, <Name>.", completion = "Ihr habt Euch als würdig erwiesen, &lt;Volk&gt;. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus erlangt man nicht so schnell.", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10468] = {title = "Der Schwur des Weisen", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, <Name>. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10469] = {title = "Der Schwur des Bewahrers", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, <Name>. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10470] = {title = "Der Schwur des Helden", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, <Name>. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10471] = {title = "Der Schwur des Verteidigers", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, <Name>. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", rewards = "Ihr bekommt:\n\nBand der Ewigkeit"}
MultiLanguageQuestData['de'][10472] = {title = "Das Bündnis des Weisen", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, <Name>.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", progress = "Möge die Zeit immer mit Euch sein, <Name>.", completion = "Ihr gehört zur Zeit, &lt;Name&gt;. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", rewards = "Ihr bekommt:\n\nBand des ewigen Weisen"}
MultiLanguageQuestData['de'][10473] = {title = "Das Bündnis des Bewahrers", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, <Name>.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", progress = "Möge die Zeit immer mit Euch sein, <Name>.", completion = "Ihr gehört zur Zeit, &lt;Name&gt;. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", rewards = "Ihr bekommt:\n\nBand des ewigen Bewahrers"}
MultiLanguageQuestData['de'][10474] = {title = "Das Bündnis des Helden", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, <Name>.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", progress = "Möge die Zeit immer mit Euch sein, <Name>.", completion = "Ihr gehört zur Zeit, &lt;Name&gt;. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", rewards = "Ihr bekommt:\n\nBand des ewigen Champions"}
MultiLanguageQuestData['de'][10475] = {title = "Das Bündnis des Verteidigers", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, <Name>.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand des ewigen Verteidigers"}
MultiLanguageQuestData['de'][10476] = {title = "Grimmige Feinde", objective = "Aufseher Moi'bff Jill in Telaar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt.", description = "Wenn Ihr Eure Treue uns gegenüber beweisen wollt, dann gibt es keinen besseren Weg, als unsere Feinde zu bekämpfen.\n\nUnter diesen Feinden gibt es keinen, der so stark und so wild ist, wie die Oger. Bringt mir die Kriegsperlen, die sie um den Hals tragen, als Beweis für ihr Ableben. Wenn Ihr das tut, lasse ich die anderen von Eurem Heldenmut wissen.", progress = "Nun, <Name>? Könnt Ihr nur Reden schwingen, oder habt Ihr mir etwas vorzuweisen?", completion = "Ihr beweist Euch allmählich als wertvoller Verbündeter und Kämpfer. Macht weiter so!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10477] = {title = "Mehr Kriegsperlen", objective = "Habt Ihr noch mehr Obsidiankriegsperlen dabei, <Name>?", description = nil, progress = "Habt Ihr noch mehr Obsidiankriegsperlen dabei, <Name>?", completion = "Ihr beweist Euch weiterhin als wertvoll, &lt;Name&gt;. Möge Eure Stärke nie versagen.", rewards = nil}
MultiLanguageQuestData['de'][10478] = {title = "Mehr Kriegsperlen!", objective = "Habt Ihr noch mehr Obsidiankriegsperlen besorgt, <Name>?", description = nil, progress = "Habt Ihr noch mehr Obsidiankriegsperlen besorgt, <Name>?", completion = "Ihr beweist uns auch weiterhin Eure Stärke und Ehre, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][10479] = {title = "Stärke beweisen", objective = "Aufseher Bullrok in Garadar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt.", description = "Auch wenn wir ein friedvolles Leben suchen, haben wir doch viele Feinde.\n\nUnter diesen Feinden gibt es keinen, der so viel rohe Macht besitzt, wie die Oger. Wenn Ihr uns Euren Heldenmut beweisen wollt, bringt mir die Kriegsperlen, die sie um den Hals tragen. Wenn Ihr das tut, lasse ich die anderen von Euren Taten wissen.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet, <Name>?", completion = "Ihr seid wirklich ein starker Verbündeter, &lt;Name&gt;. Den Ogern der Scherbenwelt Auge in Auge gegenüberzutreten ist nichts, was jeder einfach so tun kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10480] = {title = "Wütende Geister des Wassers", objective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 5 Wasserseelen einzufangen.", description = "Die Naga der Illidari in dieser Gegend haben die Kontrolle über die einzige reine Wasserversorgung im Schattenmondtal an sich gerissen.\n\nDirekt nördlich von hier findet Ihr das Nest der Naga, die Echsennarbe. Um die Echsennarbe herum findet Ihr Ansammlungen von tosendem Wasser, die ihre Qual ins Land hinausschreien. Bei diesen Ansammlungen streifen die wütenden Geister des Wassers umher.\n\nReist zur Echsennarbe und benutzt das Totem der Geister, um ihre Wasserseelen einzufangen. Die größte Ansammlung dieser Geister findet Ihr in der Nähe der Zisterne der Echsennarbe.", progress = "Wo auch immer Ihr die Naga findet, könnt Ihr sicher auch die gequälten Wassergeister finden.", completion = "Und zurück bleibt nichts als Luft, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10481] = {title = "Wütende Geister der Luft", objective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 10 Luftseelen einzufangen.", description = "Begebt Euch nach Südosten, Held. Wenn Ihr große blaue Kristalle aus dem Boden herausragen seht, habt Ihr Euer Ziel erreicht. Dort, auf den Netherschwingenfeldern, werdet Ihr die wütenden Geister der Luft finden. Sie streifen rings um die Felder auf den Klippen und um die Berge herum umher.\n\nZerstört ihre gequälten Körper und fangt ihre Seelen im Totem der Geister ein. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Bald werden wir mit den Geistern sprechen.", completion = "Erlaubt mir, dass ich Euch für diese wagemutige Tat belohne, Held.\n\nJetzt müssen wir uns an die Arbeit machen! Bitte tretet zurück, damit ich das Totem aufstellen und die Seelen freilassen kann.", rewards = "Handschutz der LeereSattelgurt des TiermannesStiefel des HimmelsteilersSchulterstücke des HimmelsteilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10482] = {title = "Plünderer der Höllenorcs", objective = "Tötet 20 Orcs der Knochenmalmer und kehrt danach zu Amadi in der Ehrenfeste zurück.", description = "Plünderer, Orcs des Knochenmalmerklans, treiben sich bei den zerstörten Kriegsmaschinerien am Pfad des Ruhmes herum. Wir müssen davon ausgehen, dass diese Höllenorcs Teile der Maschinen für ihre Meister in der Höllenfeuerzitadelle sammeln. Wir müssen sie aufhalten!\n\nSucht im Norden nach den Knochenmalmern, <Name>. Sucht sie und tötet sie! Aber seid vorsichtig. Auch wenn diese Orcs einem niederrangigeren Höllenklan angehören, sind sie doch genauso stark wie alle Orcs, die wir bisher getroffen haben.", progress = nil, completion = "Sehr gut. Ich bin mir sicher, dass ihr Verlust in der Höllenfeuerzitadelle bemerkt wird. Auch wenn diese dunkle Bastion uns überschattet und unüberwindlich scheint, können wir mit stolzen Taten wie Eurer sicher einen Weg finden, sie zu besiegen!", rewards = "Schlitzmesser des HöllenfeuersRute der VerwüstungEisensternrepetierarmbrustRundschild des ErdrutschesAdamantitviereckschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10483] = {title = "Schwarze Magie", objective = "Leutnant Amadi in der Ehrenfeste möchte, dass Ihr einen verfluchten Talisman zu Korporal Eisengrat im Expeditionsposten bringt.", description = "<Name>, in unseren Schlachten mit den Höllenorcs des Blutenden Auges haben wir Schmuckstücke mit magischen Kräften bei ihnen gefunden. Diese Orcs haben die Insignien der gefallenen Soldaten der Ehrenfeste gesammelt und verfluchte Talismane aus ihnen gemacht. Wir befürchten, dass die schwarze Magie des Blutenden Auges unsere Insignien in böse Amulette verwandelt haben, die sie gegen uns einsetzen können!\n\nSucht einen solchen Talisman bei den Orcs des Blutenden Auges in Zeth'Gor im Osten. Bringt ihn zu Korporal Eisengrat beim Expeditionsposten nordöstlich von Zeth'Gor.", progress = "Bringt Ihr Neues von der Ehrenfeste, <Name>? Das ist gut. Unseren Vorgehen gegen die Dämonen und Höllenorcs gehen so langsam die fähigen Kämpfer aus!", completion = "Ah, Ihr habt ein Insigne von den Orcs des Blutenden Auges ergattert? Gut! Es ist eine Schande, dass sie unsere Symbole gegen uns verwenden und sich über unsere Kameraden, die im Kampf gegen diese rothäutigen Bestien gefallen sind, lustig machen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlagge setzen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10484] = {title = "Verfluchte Talismane", objective = "Bringt 12 verfluchte Talismane zu Korporal Eisengrat am Expeditionsposten.", description = "<Name>, wir können nicht zulassen, dass die Orcs des Blutenden Auges diese verfluchten Talismane besitzen! Ihr müsst sie für uns beschaffen, damit wir sie zerstören können und so die gefallenen Soldaten, denen sie gehörten, für ihr Opfer ehren.\n\nGeht nach Zeth'Gor, der verfluchten Behausung des Blutenden Auges, und führt Eure grausame Aufgabe durch... Kehrt zu mir zurück, wenn Ihr die Talismane gesammelt habt.", progress = "Habt Ihr die Talismane, <Name>? Es schmerzt mich zu wissen, dass diese verdammten Orcs die Insignien unserer Soldaten besitzen...", completion = "Danke, &lt;Name&gt;. Mein Herz ist voller Trauer, wenn ich diese Talismane betrachte. Sie unterstreichen die zahlreichen Verluste, die wir in der Ehrenfeste gegen die Höllenorcs hinnehmen mussten. Aber es freut mich zu sehen, dass Ihr Erfolg gegen sie hattet. Wenn wir genügend von ihnen töten können, treten wir vielleicht als Sieger aus diesem Krieg hervor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10485] = {title = "Kriegsherr des Blutenden Auges", objective = "Bringt Kriegsherr Morkhs zerschmetterte Rüstung zu Korporal Eisengrat im Expeditionsposten.", description = "Ihr habt große Stärke und großes Geschick bewiesen, denn Ihr habt Euch in den Kampf in Zeth'Gor gestürzt und überlebt! Nun wollen wir hoffen, dass das Glück Euch weiterhin hold ist, denn ich muss Euch eine düstere Aufgabe auftragen...\n\nIn der Kaserne von Zeth'Gor sitzt Kriegsherr Morkh und befehligt seine Truppen gegen uns. Seine Taktiken sind genauso schlau wie grausam und ich muss zugeben, dass seine Erfolge bei uns tiefe Wunden geschlagen haben. Deshalb möchte ich Euch bitten, Morkh aus dem Weg zu räumen. Bringt mir seine Rüstung, damit wir sie meinen Soldaten zeigen und ihnen Mut machen können!", progress = "Habt Ihr Morkhs zerschmetterte Rüstung? Habt Ihr Euch wieder todesmutig nach Zeth'Gor begeben?", completion = "Ihr habt es geschafft! Morkh ist tot! Jetzt haben wir eine Chance im Kampf gegen die Bestien der Höllenorcs!\n\nVielen Dank, &lt;Name&gt;. Eure Hilfe in diesem Krieg ist unermesslich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10486] = {title = "Die nahende Wildnis", objective = "Tötet 12 Messerschwingenblutvergießer.", description = "Die Donnerfürsten waren einst ein stolzer Orcklan. Doch dann wurden sie durch Mannoroths Blut in Höllenorcs verwandelt.\n\nVor Kurzem haben wir diesen Orcstützpunkt von den Ogern, die sich in der Klamm unter uns breitgemacht haben, zurückgefordert. Nachdem die Donnerfürsten verschwunden waren, hatten sie hier Einzug gehalten.\n\nWir möchten diesen Ort behalten und Euch gerne bitten, uns dabei zu helfen.\n\nIm Zackengrat im Süden und Westen findet Ihr Blutvergießer, die sich zu einer wahren Seuche entwickeln. Sie fressen und vermehren sich unaufhörlich.\n\nTötet sie und kehrt dann zu mir zurück.", progress = nil, completion = "Das ging schnell. Seid Ihr sicher, dass Ihr so viele getötet habt, wie nötig war?\n\nGut. Es gibt noch eine weitere Aufgabe, bei der wir Eure Hilfe benötigen. Eine weitaus wichtigere.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10487] = {title = "Drachenstaub", objective = "Beschafft Euch 4 Einheiten Feendrachenstaub.", description = "Vor kurzem hat die Allianz im Westen Einzug gehalten und mit Hilfe ihrer Elfenmagie ein Dorf und einen Hain praktisch aus dem Nichts entstehen lassen. Wir müssen ihre Verteidigung so schwach wie möglich halten, damit sie nicht auch noch ein Rückgrat entwickeln!\n\nIch habe einen Plan, mit dem wir dies und noch mehr erreichen können. Ich möchte, dass Ihr die Brücke nach Südwesten, die über die Blutschlägerklamm in den lebenden Hain führt, überquert.\n\nGreift ihre Siechdrachenverteidigung im lebenden Hain an und bringt mir etwas von dem magischen Staub, der sich manchmal auf ihren Flügeln befindet.", progress = "Es sieht aus, als hätte die Allianz vor, uns überallhin zu folgen. Wir wollen ihnen beweisen, dass ihre Anwesenheit uns keineswegs einschüchtert.\n\nHabt Ihr besorgt, worum ich Euch gebeten habe?", completion = "Ihr habt nicht nur ihre Verteidigung geschwächt. Mit dem Staub werden wir dazu noch unsere eigene Verteidigung gegen die Allianz stärken können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10488] = {title = "Die Eigenen schützen", objective = "Wendet Gor'dreks Salbe an 5 Terrorwölfen der Donnerfürsten an.", description = "Ich habe aus dem magischen Staub, den Ihr gesammelt habt, eine Salbe hergestellt, die uns bei unserer Verteidigung helfen wird.\n\nAls wir hierher kamen, haben wir ein wundervolles Rudel Terrorwölfe mitgebracht. Sie sind die perfekte Kombination aus Reittier, Wachhund und Freund, aber der Abschaum der Allianz hat begonnen, sie im Zackengrat zu jagen.\n\n<Name>, ich möchte, dass Ihr diese Salbe nehmt und sie an unseren Terrorwolffreunden anwendet. Das wird der Allianz eine böse Überraschung bescheren, wenn sie das nächste Mal auf die Jagd geht.\n\nSeid Euch jedoch bewusst, dass einige der Wölfe das vielleicht nicht leiden mögen und Euch angreifen werden.", progress = "Wie geht es mit der Verstärkung unserer Terrorwolfverteidigung voran?", completion = "Nun, da Ihr die Wölfe und unsere Verteidigung gestärkt habt, können wir uns wieder einigen tödlicheren Angelegenheiten, wie zum Beispiel den Ogern, zuwenden.\n\nIhr habt uns hier gut geholfen. Wenn Ihr Euch entscheidet zu bleiben, könnten wir auch weiterhin die Dienste von jemandem, der so fähig ist wie Ihr, brauchen.\n\nWie auch immer Ihr Euch entscheiden mögt, Ihr habt meinen Respekt und meine Wertschätzung sicher.", rewards = "Armbinden der DonnerfürstenHandschuhe des TerrorwolfführersGor'dreks SchulterstückeWolfslefzenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10489] = {title = "Einen uralten Baum fällen", objective = "Besorgt Starkast Tiefenwurz' Stumpf.", description = "GESUCHT!\n\nStarkast Tiefenwurz, Urtum des Krieges und Hauptverteidiger des Lebenden Hains südlich von Sylvanaar.\n\nIhr findet ihn, indem Ihr nach Westen geht und die Brücke über der Blutschlägerklamm überquert.\n\nBringt seinen abgeschlagenen Stumpf zu Tor'chunk Zweiklaue.", progress = "Was habt Ihr da? Ihr seid aber stark!", completion = "Starkast Tiefwurz' Stumpf! Habt Ihr ihn selbst gefällt?\n\nSicher habt Ihr das. Wisst Ihr, ein starker &lt;Klasse&gt; wie Ihr es seid, ist genau die Hilfe, nach der Rexxar und ich gesucht haben. Besonders bei den ständigen Problemen, die wir mit den Ogern haben, könnten wir Euch brauchen. Setzt Euch mit mir in Verbindung, wenn Ihr Interesse habt.\n\nNun, dieser Stumpf ist ein stichhaltiger Beweis. Ihr seid hier, um das Kopfgeld einzustreichen, nicht um mit mir zu plaudern. Wohlan, sucht Euch etwas aus.", rewards = "Gamaschen der dunklen TatenHarnisch der BärenstärkeWildhornhelmStiefel des UrtumtötersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10490] = {title = "Ruf des Wassers", objective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt.\n\nIhr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIch nehme an, Ihr wisst noch, wie Ihr mit dem Boot von Auberdine an der Dunkelküste in Kalimdor aus zurück zur Exodar kommt? Und Ihr wisst noch, dass Ihr ihn in der Kristallhalle in der Exodar findet, ja?", progress = nil, completion = "So treffen wir uns wieder. Ich habe Eure Fortschritte aus der Ferne beobachtet, Schamane, ich bin sehr zufrieden.\n\nEs ist jetzt an der Zeit, dass Ihr mit dem Element des Wassers vertraut werdet. Ihr sollt die Geheimnisse des Wassers erlernen und Euch diesem Wissen widmen, um es mit der Zeit auch beherrschen zu können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10491] = {title = "Ruf der Luft", objective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", description = "<Name>, Scharfseher Nobundo hat erneut nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.\n\nNehmt das Boot von Auberdine an der Dunkelküste in Kalimdor aus. Überquert das Verhüllte Meer und sucht den Weissager in der Kristallhalle der Exodar auf der Azurmythosinsel auf.", progress = nil, completion = "Schließlich kommen wir zu dem letzten der vier großen Elemente, der Luft. Glaubt Ihr weise genug zu sein, um fortzufahren, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10492] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Deliana in Eisenschmiede.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBindungen der fünf Donner"}
MultiLanguageQuestData['de'][10493] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Lichts zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArmschienen der Seelenschmiede"}
MultiLanguageQuestData['de'][10494] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Eisenschmiede eine Kordel der Elemente und ein Paar Stulpen der Elemente.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKordel der fünf DonnerStulpen der fünf Donner"}
MultiLanguageQuestData['de'][10495] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel des Lichts und ein Paar Stulpen des Lichts.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGürtel der SeelenschmiedeStulpen der Seelenschmiede"}
MultiLanguageQuestData['de'][10496] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und einem Paar Schulterstücke der Elemente zu Deliana in Eisenschmiede zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der fünf DonnerKilt der fünf DonnerSchulterstücke der fünf Donner"}
MultiLanguageQuestData['de'][10497] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Lichts, ein Paar Beinplatten des Lichts und einer Schiftung des Lichts zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel der SeelenschmiedeBeinplatten der SeelenschmiedeSchiftung der Seelenschmiede"}
MultiLanguageQuestData['de'][10498] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Deliana Eure Helmkappe der Elemente und Eure Weste der Elemente.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelmkappe der fünf DonnerWeste der fünf Donner"}
MultiLanguageQuestData['de'][10499] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Euren Helm des Lichts und Eure Brustplatte des Lichts.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm der SeelenschmiedeBrustplatte der Seelenschmiede"}
MultiLanguageQuestData['de'][10500] = {title = "Die Horde braucht Euch!", objective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.Hallo, schön dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Hallo, schön dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10501] = {title = "Die Allianz braucht Euch!", objective = "Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede.Hallo, schön dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Schneefall. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Hallo, schön dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Schneefall. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10502] = {title = "Die Oger der Blutschläger", objective = "Tötet 30 Oger der Blutschläger im Außenposten der Blutschläger.", description = "Es gibt eine Bedrohung für Sylvanaar, die weitaus tödlicher ist, als die Horde in der Donnerfeste.\n\nIch spreche von den einheimischen Ogern in diesen Bergen. Im Süden und Osten, unten in der Klamm, lebt der Stamm der Blutschläger. Sie sind zwar nicht der einzige Stamm, der uns bedroht, aber sie sind am nächsten.\n\nIch möchte, dass Ihr nach Süden durch den Lebenden Hain hindurch geht und dann den Pfad nach Osten nehmt, der zu ihrem Außenposten führt. Tötet so viele Oger der Blutschläger im Außenposten der Blutschläger, wie Ihr nur könnt.", progress = nil, completion = "Das ist ein guter Anfang, um Sylvanaar und den Hain zu schützen.\n\nJetzt, da die Oger nicht mehr ganz so zahlreich sind, überlegen die Blutschläger es sich sicher zweimal, bevor sie uns hier angreifen.\n\nWenn das doch nur der einzige Ogerstamm wäre, mit dem wir Probleme hätten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10503] = {title = "Die Speerspießerbedrohung", objective = "Tötet 30 Oger der Speerspießer und 10 Raptoren der Speerspießer in der Wehr der Speerspießer und im Grund der Speerspießer.", description = "Es gibt eine Bedrohung für die Donnerfeste, die weitaus tödlicher ist, als die Allianz in Sylvanaar.\n\nIch spreche von den einheimischen Ogern in diesen Bergen. Im Westen, unten in der Klamm, lebt der Stamm der Speerspießer. Sie sind zwar nicht der einzige Stamm, der uns bedroht, aber sie sind am nächsten und die, die wir besiegen mussten, um diesen Ort hier beziehen zu können.\n\nIch möchte, dass Ihr nach Norden durch den Zackengrat hindurch geht und dann den Pfad nach unten nehmt, der in ihre Festung führt. Tötet so viele Oger der Speerspießer und ihre Raptoren in der Wehr der Speerspießer und im Grund der Speerspießer, wie Ihr nur könnt.", progress = nil, completion = "Das ist ein guter Anfang, um unsere Position hier gegen die Oger zu verteidigen.\n\nJetzt, da die Oger nicht mehr ganz so zahlreich sind, überlegen die Speerspießer es sich sicher zweimal, bevor sie versuchen, die Donnerfeste zurück zu erobern.\n\nWenn das doch nur der einzige Ogerstamm wäre, mit dem wir Probleme hätten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10504] = {title = "Die Oger der Speerspießer", objective = "Tötet 30 Oger der Speerspießer in der Wehr der Speerspießer und dem Grund der Speerspießer.", description = "Nördlich des Blutschlägerstamms liegt eine noch gefährlichere Bedrohung: die Wehr der Speerspießer.\n\nDie Oger der Speerspießer sind die stärksten in den Bergen und stehen in der Gunst des Gronn namens Gruul der Drachenschlächter und seiner sieben Söhne.\n\nJetzt, da Ihr den Blutschlägern eine Abreibung verpasst habt, ist es an der Zeit, sich ihren Rivalen zuzuwenden.\n\nGeht vom Außenposten der Blutschläger aus nach Norden durch die Klamm, bis Ihr die Wehr der Speerspießer und den Grund der Speerspießer erreicht. Tötet so viele Oger der Speerspießer, wie Ihr nur könnt.", progress = nil, completion = "Eure Taten gegen die Blutschläger und Speerspießer sind ein großer Schritt nach vorne für die Sicherung der Zukunft Sylvanaars. Als wir hier ankamen, fanden wir diesen Flecken Land unbewohnt. Wir haben kein Interesse daran, uns noch weiter auszubreiten, aber wir werden auch nicht dulden, dass man uns vertreibt.\n\nDa Ihr uns gute Dienste geleistet habt, möchte ich Euch mit der Wertschätzung der Allianz belohnen.", rewards = "Bezwingergürtel der OgerAgile GebirgsarmschienenVerteidigerschultern von SylvanaarKommandant Himmelsschattens HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10505] = {title = "Die Oger der Blutschläger", objective = "Tötet 30 Oger der Blutschläger im Außenposten der Blutschläger.", description = "Südlich des Speerspießerstamms liegt noch eine weitere Bedrohung: der Außenposten der Blutschläger.\n\nDie Oger der Blutschläger sind nicht die stärksten in den Bergen. Da sie nicht in der Gunst des Gronn namens Gruul der Drachenschlächter stehen, kommen sie nur an zweiter Stelle.\n\nJetzt, da Ihr den Speerspießern eine Abreibung verpasst habt, ist es an der Zeit, sich ihren Rivalen zuzuwenden.\n\nGeht von der Wehr der Speerspießer aus nach Süden durch die Klamm, bis Ihr den Außenposten der Blutschläger erreicht. Tötet so viele Oger der Blutschläger, wie Ihr nur könnt.", progress = nil, completion = "Eure Taten gegen die Blutschläger und Speerspießer sind ein großer Schritt nach vorne für die Sicherung der Zukunft der Donnerfeste. Wir werden nicht dulden, dass sich jemand unserem Schicksal in den Weg stellt.\n\nDa Ihr uns gute Dienste geleistet habt, möchte ich Euch mit der Wertschätzung der Horde belohnen.", rewards = "Rote Hände des DonnerfürstenTor'chunks FußbedeckungUnverwüstliche GebirgsarmschienenPrügelgürtel der OgerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10506] = {title = "Eine düstere Lage", objective = "Streut Rinas Schwächungspulver auf 5 Terrorwölfe der Blutschläger im Außenposten der Blutschläger in der Blutschlägerklamm.", description = "Jetzt, da ihr Wolfsrudel dezimiert wurde, ist die Horde auf der Suche nach Ersatz. Unglücklicherweise können sie den gleich in der Nähe finden.\n\nDie Oger der Blutschläger in der Klamm im Osten unter uns halten sich selbst ein Rudel als Wachhunde. Ich war nicht sehr froh darüber, Euch loszuschicken, um die Wölfe der Donnerfürsten zu töten. Lasst uns dieses Mal etwas anderes versuchen.\n\nIch habe ein magisches Pulver aus dem Staub, der von den Flügeln unserer Feendrachen fällt, hergestellt. Streut es auf die Terrorwölfe der Blutschläger, damit sie für die Horde nicht länger interessant sind.", progress = "Hattet Ihr Glück da draußen? Ich weiß, dass es wegen der Oger der Blutschläger sehr gefährlich ist, aber wenn wir es vermeiden können, die Tiere zu töten, bin ich sehr froh.", completion = "Ich bin froh zu hören, dass es geklappt hat. Je weniger Wesen der Natur sterben müssen, desto besser.\n\nIch muss sagen, dass ich Euch nach all dem, was Ihr für uns getan habt, ins Herz geschlossen habe.\n\nGebt auf Euch Acht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10507] = {title = "Der Wendepunkt", objective = "Benutzt Socrethars Teleportationsstein beim Invasionspunkt: Oberanführer im Norden der Konstruktionsbasis: Vergessenheit, um Eure Gruppe zu Socrethars Sitz zu bringen. Wenn Ihr dort seid, benutzt Voren'thals Präsenz, um Socrethar zu besiegen.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Das ist die Gelegenheit, auf die wir gewartet haben, <Name>. Wir können vor unserem Volk nicht nur belegen, was Kael'thas wirklich vorhat, sondern auch unsere Stärke beweisen, indem wir seine neuen Meister besiegen.\n\nMeine schlechte Gesundheit hindert mich leider daran, Euch selbst zu helfen, aber ich biete Euch einen Gegenstand an, mit dem ich meine Kräfte über den Kontinent hinweg ausüben kann.", progress = "Ist es vollbracht, <Name>?", completion = "Ihr verfügt über unglaubliche Kraft, &lt;Name&gt;. Die Seher können sich glücklich schätzen, Euch als Verbündeten zu haben.\n\nWenn sich die Nachricht von Kaels neuem Bündnis verbreitet, werden mehr Leute die Sache wie wir sehen. Die Tatsache, dass wir einen solch entscheidenden Sieg über Kael'thas errungen haben, bringt uns in eine äußerst günstige Lage.\n\nIch werde Eure Taten nicht vergessen.", rewards = "Socrethars GurtNetherdurchsetzte SchulterstückeSchienbeinschützer der ZaubermachtStulpen des BezwingersZauberstab des SehersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10508] = {title = "Ein Geschenk für Voren'thal", objective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Ich möchte Euch nicht mit leeren Händen zu Voren'thal zurückschicken. Jemanden unbeeindruckt zu lassen ist nicht mein Stil.\n\nUm Zugang zu Socrethars Sitz im Norden zu erlangen, müsst Ihr einen seiner Teleporter benutzen. Dazu braucht Ihr einen Teleportationsstein. Die erste Hälfte des Steins befindet sich im Besitz von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit. Die zweite Hälfte hat der Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna.\n\nBesorgt Euch den Stein, dann wird Voren'thal über alle Maßen beeindruckt sein.", progress = "Habt Ihr Socrethars Teleportationsstein schon besorgt, <Name>?", completion = "Ihr erstaunt mich immer wieder, &lt;Name&gt;! Gut, dass Ihr auf unserer Seite steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10509] = {title = "Für Ruhm bestimmt", objective = "Bringt Socrethars Teleportationsstein zu Voren'thal dem Seher auf der Sehertreppe in Shattrath.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Jetzt kann ich Euch ruhigen Gewissens nach Shattrath zurückschicken. Ihr habt Beweise dafür gefunden, dass Kael'thas sich mit der Brennenden Legion verbündet hat. Außerdem habt Ihr den Schlüssel zur Hintertür des Oberanführers erlangt.\n\nGebt jedoch Acht, dass sich Voren'thal nicht vor lauter Aufregung überschlägt - der alte Mann wird langsam etwas gebrechlich, wenn Ihr versteht, was ich meine. Ihr findet ihn in der Bibliothek der Seher auf der Sehertreppe.", progress = nil, completion = "Ihr habt keine Ahnung, was das für die Seher bedeutet, &lt;Name&gt;. Ihr müsst mich entschuldigen, während ich nach Atem ringe und die Situation einschätze.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10510] = {title = "In die Draenethystmine", objective = "Sammelt 5 Kristalle der Draenethystmine.", description = "Schön jemanden zu sehen, der uns hier helfen will!\n\nBorgrim und ich gehören zur Forscherliga. Wir sind hier, um so viel von diesen Bergen zu lernen, wie wir nur können. Wir haben schon allerlei Geschichten darüber gehört. Ich kann es kaum abwarten, mich hier niederzulassen und mit der Arbeit zu beginnen.\n\nEine Sache hat meine besondere Aufmerksamkeit erregt. Die Nachtelfen erzählen von einem Ort in der Klamm im Osten, der als Draenethystmine bekannt ist. Sie liegt am südlichen Ende des Außenpostens der Blutschläger. Ich hätte gerne ein paar der Kristalle, die dort wachsen.", progress = "Ist das nicht aufregend? Nach dem ganzen Dreck und den Insekten in Silithus ist dieser Ort hier ein wahres Paradies!", completion = "Ooh, so wie sie aussehen, handelt es sich hierbei um ganz tolle Exemplare! Ich kann es kaum abwarten, sie mit meinen Untersuchungsgeräten genau unter die Lupe zu nehmen!\n\nVielen Dank!", rewards = "Mantelung des HöhlenforschersHandschuhe des MinenarbeitersAllwetterarmschützerStiefel des ForschersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10511] = {title = "Merkwürdiges Gebräu", objective = "Sammelt 11 Einheiten von Blutschlägers Hauweggebräu.", description = "Wenn ich diesen Urlaub richtig beginnen will, brauche ich mehr gutes Gebräu. Leider haben diese Elfen keine Ahnung von der hohen Kunst des Gärens.\n\nIch habe gehört, dass die Oger der Blutschläger in der Klamm ganze Mengen davon auf Lager haben. Das will ich gerne versuchen.\n\nTut Ihr mir einen Gefallen? Geht nach Süden durch den Lebenden Hain und dann den Abstieg im Osten hinunter zum Außenposten der Blutschläger und besorgt mir ein wenig davon. Ich habe gehört, dass sie große Fässer davon herumliegen haben. Ihre Braumeister schenken es an all die anderen Oger aus.", progress = "Ziemlich trocken hier. Wie soll ich denn meinen Urlaub ohne etwas zu Trinken genießen?", completion = "Was riecht hier so? Oh nein, bitte sagt mir nicht, dass dies das Ogergebräu ist?\n\nIch habe fast schon Angst, es zu probieren. Ach zur Hölle, was soll's? Hoch die Tassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10512] = {title = "Die Speerspießer abfüllen", objective = "Versucht, mit Blutschlägers Hauweggebräu 5 Oger der Speerspießer betrunken zu machen.", description = "Ich nehme keinen weiteren Schluck von diesem übel riechenden Gesöff! Aber mir kommt da eine Idee.\n\n<Borgrims Augen beginnen zu funkeln.>\n\nDas ist der Plan. Wir wissen, dass die Blutschläger praktisch von dieser Brühe leben. Aber ich frage mich, was wohl ihre Feinde, die Speerspießer, davon halten.\n\n<Name>, ich möchte, dass Ihr den Rest dieses Gesöffs nehmt und schaut, ob wir die Oger der Speerspießer damit betrunken machen können. Ihr findet sie nördlich vom Außenposten der Blutschläger in der Klamm.", progress = "Wie sieht es aus? Sind die Speerspießer so anspruchslos wie die Blutschläger oder sind sie auch fast dabei umgekommen wie ich?", completion = "Ah, hahaha! Das habe ich mir gedacht. Oger trinken wahrscheinlich alles.\n\nWas für ein dummer Haufen!\n\nAuch wenn ich mein Gebräu nicht bekommen habe, habt Ihr mir doch einen guten Start in den Urlaub bereitet.\n\nIch sage Euch was... wir haben hier allen möglichen Kram, den wir nicht wirklich brauchen. Kann ich Euch etwas davon anbieten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10513] = {title = "Oronok Herzeleid", objective = "Sucht Oronok Herzeleid auf dem zerschlagenen Vorsprung nördlich der Zisterne der Echsennarbe.", description = "Ich weiß nicht, wie wir an den Zauberspruch, den die Geister erwähnt haben, herankommen sollen, <Name>. Um die Wahrheit zu sagen, habe ich nicht einmal eine Ahnung, wo man so eine Suche beginnen könnte.\n\n<Torlok starrt gedankenverloren in die Ferne.>\n\nHmm... Das ist zwar ein Schuss ins Blaue, aber es ist vielleicht unsere einzige Chance. Es gibt einen Orc, den ich schon des Öfteren in dieser Gegend gesehen habe. Ich habe einmal kurz mit ihm gesprochen. Er ist ein Einsiedler, der angeblich in der Zisterne der Echsennarbe im Nordosten lebt. Findet diesen Orc namens Oronok Herzeleid.\n\nWie gesagt, es ist ein Schuss ins Blaue.", progress = nil, completion = "Litanei der Verdammnis? Nie davon gehört. Hört auf meinen Rat und lasst die Toten ruhen.\n\nAber wenn Ihr schon hier seid, könnt Ihr mir ja gleich bei ein paar Dingen helfen. Was meint Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10514] = {title = "Ich war schon vieles...", objective = "Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr 10 Schattenmondknollen aus den Zerschlagenen Weiten besorgt.\n\nBringt Oronoks Eberpfeife zu ihm zurück, wenn Ihr fertig seid.", description = "Ich war schon vieles, Fremder, aber was ich einst war, ist nicht von Belang. Es zählt nur, was ich jetzt bin, und jetzt bin ich ein Bauer.\n\nIch benutze trainierte Hölleneber, um Knollen in der harten Erde der Zerschlagenen Weiten aufzuspüren. In letzter Zeit greifen jedoch Felshetzer aus einem Gelege im Nordosten meine Tiere an und halten mich vom Sammeln der Knollen ab.\n\nWürdet Ihr für mich in der Gegend nördlich von hier ein paar Knollen sammeln? Benutzt diese Pfeife, wenn Ihr auf einem Schattenmondknollenhügel steht. Einer der Eber wird herbeieilen, und die Knolle ausgraben.", progress = "Holt mir diese Knollen!", completion = "Ihr sagt, da waren viel mehr Felshetzer, als Ihr erwartet habt? Sieht aus, als wäre es an der Zeit, die Situation etwas zu entschärfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nOronoks Knolle der HeilungOronoks Knolle der BeweglichkeitOronoks Knolle der StärkeOronoks Knolle der Zaubermacht\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10515] = {title = "Eine Lektion gelernt", objective = "Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr 10 Eier eines gefräßigen Schinders in den zerschlagenen Weiten zerstört.", description = "Wir müssen diesen Felshetzern zeigen, was es heißt, Oronoks Geschäften in die Quere zu kommen!\n\nIch möchte, dass Ihr in die Zerschlagenen Weiten zurückkehrt und jedes Felshetzerei zerstört, das Ihr finden könnt. Sie befinden sich sicher tief im Felshetzergebiet. Seid also wachsam.", progress = nil, completion = "Das wird den verdammten, bösartigen Tieren zeigen, dass man meine Eber nicht töten sollte! Gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10516] = {title = "Die Gefangenschaft der Verteidigerin", objective = "Holt Verteidigerin Vuuleens Klinge und Verteidigerin Vuuleens Schild zurück.", description = "Ich weiß, es klingt merkwürdig, aber ich möchte wirklich in diesem Käfig bleiben. Er gibt mir die perfekte Gelegenheit, um das zu tun, weswegen ich hier bin: Informationen über die Oger der Speerspießer sammeln.\n\nIch kann hier zwar jederzeit raus, aber mein Schwert und meinen Schild hätte ich gerne wieder zurück.\n\nZwei ihrer Anführer haben sich meine Sachen unter den Nagel gerissen. Droggam hat mein Schwert und Mugdorg meinen Schild.\n\nWenn Ihr es für nötig haltet, besorgt Euch das Gebräu der Blutschläger aus ihrem Außenposten im Süden, um die Unterstützung der beiden außer Gefecht zu setzen, aber gebt auf ihre nüchternen Wachen Acht, die nichts trinken werden!", progress = "<Klasse>, habt Ihr mein Schwert und meinen Schild?\n\nIch kann zwar jederzeit hier raus, aber es wäre mir sehr peinlich, wenn ich ohne meine Ausrüstung nach Sylvanaar zurückkehren müsste.", completion = "Ich stehe tief in Eurer Schuld, denn Ihr habt mir meine Ehre wiedergegeben. Aber unsere Arbeit hier ist noch nicht vorüber.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10517] = {title = "Eure Zeit ist gekommen, Gorr'Dim...", objective = "Tötet Gorr'Dim, den Anführer der Oger in der Wehr der Speerspießer.", description = "Der Anführer der Wehr der Speerspießer ist Gorr'Dim.\n\nEr ist auf keinen Fall zu unterschätzen. Seine Gerissenheit hat die Speerspießer zu den Lieblingen von Gruul dem Drachenschlächter und dem vorherrschenden Klan in den Bergen gemacht. Gorr'Dim hat auf Schritt und Tritt seine private Eskorte dabei, darunter auch Verteidiger, die schwören mussten, niemals auch nur einen Tropfen des Gebräus der Blutschläger anzurühren.\n\nFür die Sicherheit Sylvanaars und all der friedliebenden Wesen der Berge bitte ich Euch, zur Wehr zurückzukehren und ihn zur Strecke zu bringen.", progress = nil, completion = "Sehr gut. Ihr seid ein sehr gewitzter &lt;Klasse&gt;, so viel ist sicher.\n\nIch frage mich, ob Ihr wohl noch eine Sache für mich und Sylvanaar tun könntet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10518] = {title = "Das Banner aufstellen", objective = "Benutzt das Banner der Speerspießer auf dem Nordschlägerturm, um Gurn Grubnosh anzulocken, und beschafft Euch das Banner der Speerspießer sowie Gurn Grubnoshs Helm.", description = "Ich möchte, dass Ihr das Banner der Speerspießer von einem ihrer Champions stehlt und es nach Süden zum Außenposten der Blutschläger bringt. Stellt es auf dem Nordschlägerturm auf.\n\nDas wird die Blutschläger erzürnen. Sie werden Euch ohne mit der Wimper zu zucken angreifen. Aber es wird auch ihren Hass auf die Speerspießer schüren und sie von Sylvanaar ablenken.\n\nIhr habt Eure Aufgabe erfüllt, wenn Ihr Gurn Grubnoshs Helm in den Händen haltet. Bringt ihn nach Sylvanaar.\n\n<Name>, das wird nicht einfach. Nehmt ein oder zwei Freunde mit.", progress = "Was führt Euch zu mir? Es gibt doch nicht etwa Ärger mit den Blutschlägern?", completion = "Gurn Grubnoshs Helm und ein Banner der Speerspießer?\n\nEin ziemlich gewitzter Plan von der Verteidigerin und Euch.\n\nWenn die Blutschläger weiter mit den Speerspießern beschäftigt sind, nimmt uns das viel von dem Druck, unter dem wir hier in letzter Zeit leiden.\n\nBitte, &lt;Name&gt;, nehmt dieses bescheidene Geschenk von Sylvanaar an.", rewards = "Elitezauberrüstung von SylvanaarKniehosen des OgerassassinenGurns gehörnter HelmChampionschultern von SylvanaarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10519] = {title = "Die Litanei der Verdammnis - Wahrheit und Geschichte", objective = "Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr Euch seine Geschichte anhört. Sprecht mit Oronok, um ihm zusagen, dass er mit der Geschichte beginnen kann.", description = "<Oronok nimmt Haltung an und richtet sich zu seiner vollen Größe auf.>\n\nIch musste sichergehen, <Name>. Und dazu musste ich Euch erst prüfen. Bitte verzeiht meine kleine Maskerade. Ich bin so sehr ein Bauer, wie Ihr ein Teufelseber seid, nämlich gar nicht.\n\nWenn Ihr die Litanei der Verdammnis beschaffen wollt, müsst Ihr mir erst zuhören. Wenn Ihr bereit seid, lasst es mich wissen, und ich werde Euch die Geschichte erzählen.", progress = "Habt Geduld und hört zu, <Name>.", completion = "Versteht Ihr, was getan werden muss? Findet die Söhne Oronoks. Findet meine Jungs...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10520] = {title = "Erzdruide Hirschhaupt helfen", objective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Hirschhaupt an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10521] = {title = "Grom'tor, Sohn von Oronok", objective = "Sucht Grom'tor, Sohn von Oronok in der Echsennarbe im Schattenmondtal.", description = "Mein Erstgeborener, Grom'tor, hat sich aufgemacht, um die Echsennarbe zu durchsuchen. Sie befindet sich direkt südwestlich von hier.\n\nEr ist der Krieger der Familie, jähzornig und blutdurstig... Das hat er von seiner Mutter. Sucht um die Echsennarbe herum nach ihm. Wenn Ihr irgendwo Nagaleichen liegen seht, ist Grom'tor sicher in der Nähe.\n\nWenn Ihr ihn findet, dann sagt ihm dies: \"Wir vergießen Blut für eine gerechte Sache\". Dann wird er wissen, dass Ihr ein Freund Herzeleids seid und Euch nicht vorschnell töten.", progress = nil, completion = "&lt;Grom'tor grunzt.&gt;\n\nGut dass Ihr hier seid. Diese Made hat gerade geplaudert. Jetzt haben wir sie!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10522] = {title = "Die Litanei der Verdammnis - Grom'tors Angriff", objective = "Grom'tor, Sohn von Oronok, in der Echsennarbe im Schattenmondtal möchte, dass Ihr den ersten Teil der Litanei der Verdammnis besorgt.", description = "Dieser Nagaabschaum ist schon der sechste, den ich heute befragt habe. Wegen der schicken Rüstung dachte ich, dass er sicher etwas weiß. Die anderen waren völlig nutzlos.\n\n<Grom'tor zeigt auf die Nagaleichen um sich herum.>\n\nIch musste ihn nur einmal schlagen, da hat er mir schon alles erzählt.\n\nDer erste Teil der Litanei befindet sich in einer Nagatruhe in der Echsennarbe oder der Zisterne der Echsennarbe im Osten. Er sagt, dass die Naga die Schlüssel haben. Tötet sie, nehmt ihre Schlüssel und benutzt sie, um die Truhen der Echsennarbe zu öffnen. Kehrt zu mir zurück, wenn Ihr die Litanei gefunden habt.", progress = "Hattet Ihr Glück?", completion = "Das müsst Ihr sofort zurück zu Vater bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10523] = {title = "Die Litanei der Verdammnis - Erster Teil", objective = "Bringt Grom'tors Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal.", description = "<Grom'tor wickelt die Dokumente ein und legt sie in eine Schließkassette.>\n\nBringt diese Kassette zu meinem Vater. Er erwartet Eure Rückkehr bei seinem Hof im Nordosten.\n\nSagt ihm, dass ich bald nach Hause kommen werde. Sobald ich meinen Spaß hier hatte...", progress = "Hattet Ihr Erfolg?", completion = "Wenn die Litanei der Verdammnis wieder zusammengefügt ist, werden wir diesen Fluch beenden!", rewards = "Grom'tors blutiger VerbandGrom'tors Freund sein Vetter seine TunikaOronoks alte ArmschienenAuf Euch wartet eine dieser Belohnungen:\n\nGrom'tors Anhänger der Eroberung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10524] = {title = "Artefakte der Donnerfürsten", objective = "Beschafft Euch die Trommel der Donnerfürsten, den Pfeil der Donnerfürsten und die Schrifttafel der Donnerfürsten.", description = "Das Artefakt verfügt über Markierungen, die es als Kunstwerk der Orcs der Donnerfürsten identifizieren. Diese Orcs lebten einst in der Donnerfeste, bevor sie zu Höllenorcs wurden.\n\nEine Zeitlang wohnten die Oger der Speerspießer in der Feste, bis die Horde sie von dort vertrieben hat.\n\nIhr habt schon von weiteren Artefakten gehört, die vermisst werden. Ihr wisst, dass sich unter den Objekten, nach denen gesucht wird, eine Trommel, ein Pfeil und eine Schrifttafel befinden.\n\nDurchsucht die Wehr der Speerspießer nach ihnen und bringt sie zu Rokgah Blutgriff.", progress = "Kenne ich Euch?", completion = "Ich kann meinen Augen nicht trauen! Wenn das ein Scherz sein soll, ziehe ich Euch die Haut vom Leibe, &lt;Klasse&gt;!\n\nSchnell, lasst mich diese unschätzbaren Artefakte untersuchen, bevor Ihr sie noch mit Euren zwei linken Händen zerbrecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10525] = {title = "Wegweisende Visionen", objective = "Benutzt das feurige Seelenfragment, um Euren Geist in eine wegweisende Vision zu versetzen, wodurch Ihr den Aufenthaltsort des letzten Artefakts der Donnerfürsten erfahren solltet.", description = "<Dummer/Dumme:r> <Volk>. Ihr hättet fast die Trommel zerstört!\n\nIch habe so hart daran gearbeitet und bis jetzt stand ich immer mit leeren Händen da. Wenigstens hattet Ihr Erfolg, wo alle anderen versagt haben.\n\nJetzt, da wir diese vier Artefakte des Klans haben, ist es an der Zeit, eine Vision herbeizurufen, die Euch zu dem letzten Artefakt, nach dem ich suche, führen wird.\n\nNehmt dieses feurige Fragment meiner Seele. Damit könnt Ihr Euren Körper in eine Flamme verwandeln und Euren Geist in eine wegweisende Vision versetzen, die Euch den Aufenthaltsort des letzten Relikts der Donnerfürsten zeigen wird.", progress = "Was habt Ihr gesehen? Sagt es mir! Ich muss wissen, wo es ist!", completion = "In der Draenethystmine? Die Blutschläger müssen es von dem Speerspießern gestohlen haben.\n\nPah! Das ist zu weit weg... zu tief im Blutschlägergebiet, als dass ich dorthin reisen könnte.\n\nAber Ihr! Ihr kennt den Weg. Ihr sollt an meiner statt dorthin gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10526] = {title = "Die Donnerlanze", objective = "Beschafft Euch die Donnerlanze.", description = "Wenn die Vision, die ich Euch gewährt habe, wahr ist, dann müsst Ihr hinunter in das südliche Ende der Blutschlägerklamm reisen. Dort findet Ihr die Draenethystmine.\n\nReist bis ans Ende der Mine und beschafft die Donnerlanze. Beachtet nichts anderes! Ich interessiere mich nicht für die Kristalle in der Mine.\n\nSobald Ihr den Speer habt, bringt ihn zu mir zurück.\n\nUnd <Name>, seid vorsichtig damit... Ich mag mir gar nicht ausmalen, was Euch zustoßen wird, wenn Ihr ihn zerbrecht.", progress = "Ihr könnt sicher nicht verstehen, wie wichtig diese Artefakte sind.\n\nWenn ich alle fünf beisammen habe, werde ich ein Ritual durchführen, das unser Besitzrecht an der Donnerfeste durch die Besänftigung der toten Geister festigen wird.\n\nVersteht Ihr nun, was daran so wichtig ist? Versteht Ihr nun, warum ich keine Zeit für Geplänkel habe?", completion = "Ich bin beeindruckt. Könnt Ihr Euch überhaupt vorstellen, wie viele zuvor bei dem Versuch, die Relikte zu bergen, gestorben sind?\n\nWir können uns glücklich schätzen, dass Ihr hier mit uns zusammenarbeitet, &lt;Name&gt;. Auch wenn Ihr etwas langsam seid.\n\nErlaubt mir, Eure Aufopferung für unsere Sache zu belohnen. Wählt, aber wählt weise. Wenn Ihr fertig seid, werde ich die Geister der Donnerfeste besänftigen.", rewards = "Zauberstab der AhnenSkalpell der DonnerfürstenLangdolch des schleichenden TodesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10527] = {title = "Ar'tor, Sohn von Oronok", objective = "Findet Ar'tor, Sohn von Oronok, bei der Stätte der Illidari im Schattenmondtal.", description = "Mein jüngster Sohn, Ar'tor, hat sich bei der Stätte der Illidari auf die Suche begeben. Sie befindet sich weit im Südwesten, zwischen der Feste der Legion und der Burg Wildhammer.\n\nAuch wenn Ar'tor ein ausgezeichneter Jäger und Fährtenleser ist, befürchte ich, dass er sich dieses Mal übernommen hat. Die Stätte der Illidari ist eine Prüfungsstätte für Illidans Dämonen. Diese Dämonen haben die Brennende Legion verlassen, um sich dem Verräter anzuschließen!\n\nReist zur Stätte der Illidari und findet Ar'tor, <Name>!", progress = nil, completion = "Ar'tors Körper hängt leblos in der Luft. Ihr wisst nicht, wie lange er schon tot ist, aber Euch überkommt große Traurigkeit für Oronok.\n\nVielleicht solltet Ihr versuchen, seine Leiche zu seinem Vater zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10528] = {title = "Dämonische Kristallgefängnisse", objective = "Sucht und tötet Schmerzensmeisterin Gabrissa in der Stätte der Illidari und kehrt mit dem kristallenen Schlüssel zum Leichnam von Ar'tor, Sohn von Oronok, zurück.", description = "Eurer Einschätzung nach wird Ar'tors Körper von der Energie der Kristalle, die um die Rune herum schweben, in der Luft gehalten. Ihr versucht alles, was Ihr könnt, aber Ar'tor lässt sich nicht bewegen.\n\nEuch fällt auf, dass die Kristalle im unteren Teil eine Vertiefung aufweisen, vielleicht für einen Schlüssel. Neben den Kristallen scheinen Sukkuben regelmäßig eine Art Ritual durchzuführen.\n\nDurchsucht die Stätte der Illidari nach ihrer Anführerin. Vielleicht hat sie den Schlüssel zu Ar'tors Befreiung.", progress = "Ar'tor schwebt leblos vor Euch.", completion = "Ihr steckt den Schlüssel in die Öffnungen im unteren Teil jedes dämonischen Kristalls.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10529] = {title = "Der Pfad des Jägers", objective = "Sprecht mit Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer im Immersangwald.Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, <Name>. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, <Name>. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10530] = {title = "Der Pfad des Jägers", objective = "Sprecht mit Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer im Immersangwald.Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, <Name>. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, <Name>. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10531] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede und den Hof und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.", description = "<Name>, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpositionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpositionen gelungen ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10532] = {title = "Zerschlagt die Versorgungslinien Arathors", objective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, <Name>. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpunkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10534] = {title = "Heimkehr", objective = "Caedmos in der Exodar wünscht Euch zu sehen.Ah, <ein/eine:c> <Klasse>...\n\nJa, vor Kurzem war ein Priester Eures Ordens hier, <Name>. Er hat mir gesagt, dass es an der Zeit für Euch ist, zur Exodar zurückzukehren und Caedmos zu treffen. Es klang, als wäre es ziemlich dringend. Lasst Euch also nicht allzu viel Zeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, <ein/eine:c> <Klasse>...\n\nJa, vor Kurzem war ein Priester Eures Ordens hier, <Name>. Er hat mir gesagt, dass es an der Zeit für Euch ist, zur Exodar zurückzukehren und Caedmos zu treffen. Es klang, als wäre es ziemlich dringend. Lasst Euch also nicht allzu viel Zeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10535] = {title = "Die Ressourcen des Arathibeckens", objective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, <Name>. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10537] = {title = "Lohn'goron, Bogen des Herzeleid", objective = "Der Geist von Ar'tor bei der Stätte der Illidari im Schattenmondtal möchte, dass Ihr Lohn'goron, den Bogen des Herzeleid, von den Dämonen in der Gegend beschafft.", description = "Es ist ein Zeichen, <Name>. Nicht einmal der Tod kann mich aufhalten. Einen Teil der Litanei der Verdammnis zu beschaffen ist mein Schicksal. Mit Eurer Hilfe werde ich es erfüllen.\n\nBevor wir uns auf diese Reise begeben, brauche ich meinen Langbogen, Lohn'goron. Er ist ein Familienerbstück, das seit Generationen von Herzeleid zu Herzeleid weitergegeben wurde.\n\nMeine Instinkte sagen mir, dass einer der Dämonen ihn von meiner Leiche gestohlen hat. Tötet die Dämonen hier, bis Ihr meinen Bogen habt.", progress = "Fürchtet Euch nicht, Held. Wenn die Zeit gekommen ist, werde ich Euch helfen...", completion = "Der Name bedeutet in meiner Sprache 'Heldenruh'. Und auch jetzt, in einer Gegend, in der all unsere Helden gestorben sind, bewahrheitet er sich.\n\nUnd doch scheint einer sich immer wieder zu erheben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10538] = {title = "Kochendes Blut", objective = "Benutzt den Verfluchten Kessel, um das Blut des Blutenden Auges in gekochtes Blut zu verwandeln. Bringt danach 12 Einheiten gekochtes Blut zu Apotheker Albreck im Rückenbrecherposten.", description = "Das letzte Experiment war kein kompletter Fehlschlag. Ich habe ein wenig von dem Blut, das Ihr mir gebracht habt, aufgehoben. Jetzt, da es abgekocht ist, sollte es frei von allen Flüchen sein, mit denen die Hexen des Blutenden Auges das Blut ihres Volkes belegt haben.\n\nIch brauche jedoch noch mehr Blut für meine Untersuchungen. Begebt Euch nach Zeth'Gor und sammelt dort das Blut der Orcs. Kocht es danach in ihrem verfluchten Kessel und bringt es mir.", progress = "Habt Ihr das gekochte Blut, <Name>? Ich würde es furchtbar gerne ohne Unterbrechungen untersuchen können...", completion = "Sehr gut. Jetzt kann ich meine Tests viel leichter durchführen...\n\nVielen Dank, &lt;Name&gt;. Eure Begabungen sind beachtlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10539] = {title = "Heimkehr", objective = "Caedmos in der Exodar wünscht Euch zu sehen.Ah, <ein/eine:c> <Klasse>...\n\nJa, vor Kurzem war ein Priester Eures Ordens hier, <Name>. Er hat mir gesagt, dass es an der Zeit für Euch ist, zur Exodar zurückzukehren und Caedmos zu treffen. Es klang, als wäre es ziemlich dringend. Lasst Euch also nicht allzu viel Zeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, <ein/eine:c> <Klasse>...\n\nJa, vor Kurzem war ein Priester Eures Ordens hier, <Name>. Er hat mir gesagt, dass es an der Zeit für Euch ist, zur Exodar zurückzukehren und Caedmos zu treffen. Es klang, als wäre es ziemlich dringend. Lasst Euch also nicht allzu viel Zeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10540] = {title = "Die Litanei der Verdammnis - Ar'tors Angriff", objective = "Der Geist von Ar'tor bei der Stätte der Illidari im Schattenmondtal möchte, dass Ihr den zweiten Teil der Litanei der Verdammnis von Veneratus dem Vielgesichtigen besorgt.\n\nKreaturen, die vom Geistjäger angegriffen werden oder Schaden erleiden, gewähren Euch keine Beute oder Erfahrung.", description = "Endlich sind wir bereit. Ich werde Euch einen Teil meines Geistes verleihen, Held. Er wird Euch den Weg weisen und Euch im Kampf gegen das Böse unterstützen.\n\nDann müsst Ihr von hier aus nach Süden an die Rückseite der Stätte der Illidari reisen. Versteckt im Astralraum befindet sich eine bösartige Kreatur namens Veneratus der Vielgesichtige. Mein Geistjäger wird ihn hervorlocken, wenn er in der Nähe ist.\n\nVernichtet Veneratus und nehmt ihm den zweiten Teil der Litanei der Verdammnis ab.", progress = "Die Litanei muss gefunden werden!", completion = "&lt;Ar'tors Silhouette wird unscharf und wieder schärfer.&gt;\n\nEs scheint, als wäre meine Zeit bald zu Ende, Held.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10541] = {title = "Die Litanei der Verdammnis - Zweiter Teil", objective = "Bringt Ar'tors Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal.", description = "Ich danke Euch, Held. Ohne Euch wäre mein Geist auf ewig an diesem verfluchten Ort gefangen.\n\n<Ar'tor reicht Euch eine spektrale Schließkassette.>\n\nNehmt sie und bringt sie zu meinem Vater beim Hof im Nordosten, über der Zisterne der Echsennarbe... darin befinden sich Lohn'goron und der zweite Teil der Litanei.\n\nEr wird sehr traurig über meinen Tod sein. Versprecht mir, dass Ihr ihm versichert, dass ich als freie Seele gestorben bin. Sagt ihm, dass ich die Jagdgründe sehe und dass sie wundervoll sind. Sagt ihm, dass ich dort auf ihn warte...", progress = "<Eine einzelne Träne läuft über Oronoks Wange.>", completion = "&lt;Oronok wischt sich die Träne aus dem Auge und lächelt Euch an.&gt;\n\nDanke. Ich verspreche Euch, Held, dass ein ehrenhaftes Lied über Euch erklingen wird.", rewards = "Geisterhaftes KopfbandEvas BandOronoks alte GamaschenHerzeleids FamilientunikaHerzeleids UmhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10542] = {title = "Die ham meine Pfeife und mein Gesöff geklaut!", objective = "Beschafft Euch T'chalis Wasserpfeife und 10 Einheiten von Blutschlägers Hauweggebräu zurück.", description = "T'chali war immer ein gediegener Troll. Ich kam hierher, um den Blutschlägern beizubringen, wie man Bier braut. Aber dann ham die Blutschläger mich hier begraben und lassen mich hier verrotten!\n\nDas Schlimmste ist, dass die meine Wasserpfeife geklaut ham!\n\nWollt Ihr T'chali also helfen? Bringt mir meine Wasserpfeife zurück! T'chali glaubt, dass die Oger, die sie gestohlen ham, nach Südwesten bei der Mine drüben abgehauen sind.\n\nUnd wenn Ihr schon da seid, nehmt noch etwas von meinem Gebräu mit!", progress = "He, habt Ihr meine Wasserpfeife und das Gebräu schon?", completion = "Ja, genau davon hat T'chali geredet! Ist sich nicht ganz sicher, was die Oger da reingetan ham. Die Pfeife riecht nicht nach T'chalis Tabak.\n\nEgal, T'chali ist glücklich. Sogar so glücklich, dass er Euch um einen weiteren Gefallen bitten will.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10543] = {title = "Grimnok und Korgaah, ich komm' Euch holen!", objective = "Tötet Grimnok Schlachttaufe und Korgaah.", description = "T'chali hat auf seine Rache gewartet!\n\nAn dem Tag, an dem sie T'chali begraben und zum Sterben hier gelassen ham, hat Grimnok Schlachttaufe der Blutschläger sie angeführt. Und am nächsten Tag kam Korgaah nach Süden, um zu Plündern und T'chali gegen den Kopf zu treten.\n\nIch will die beiden tot sehen! Ihr findet Grimnok auf dem Südschlägerturm im Außenposten der Blutschläger. Korgaah befindet sich auf einem Gebäude am nördlichen Ende der Wehr der Speerspießer. Korgaah hat nüchterne Freunde bei sich. Ihr werdet also vielleicht das Gebräu brauchen, um ihn von ihnen wegzulocken.", progress = nil, completion = "T'chali ist zufrieden, dass Korgaah und Grimnok Schlachttaufe jetzt auch die Radieschen von unten anschauen.\n\nAber T'chalis Rachedurst ist noch nicht gestillt. Ihr müsst noch etwas anders machen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10544] = {title = "Verflucht seien Eure beiden Klans!", objective = "Benutzt den heimtückischen mächtigen Fetisch, um 5 Gebäude in der Wehr der Speerspießer und 2 Gebäude im Außenposten der Blutschläger zu verfluchen.", description = "T'chali hat beschlossen, dass er Rache an allen Ogern will!\n\nT'chali war in seinem Leben ein mächtiger Hexendoktor. Wenn Ihr in mein Grab fasst, findet Ihr dort einen verdammt mächtigen Fetisch.\n\nNehmt den Fetisch und ruft seine Magie, um die Gebäude der Wehr der Speerspießer und des Außenpostens der Blutschläger zu verfluchen. Der Voodoo wird einen bösen Geist rufen, den Ihr vernichten müsst. Das wird wiederum das Haus verfluchen.\n\nAber Vorsicht! Wenn Ihr versucht, ein Haus zu verfluchen, das bereits verflucht ist, ruft Ihr damit einen weiteren bösen Geist!", progress = "T'chali will nicht mehr sprechen, bis <Name> den Fetisch benutzt hat, um die Häuser der Speerspießer und der Blutschläger zu verfluchen!", completion = "Hahaha, Rache ist süss!\n\nAber T'chali sieht, dass Ihr nun, da meine Rache verübt wurde, gerne weiterziehen wollt. Ich versteh' schon, Kumpel... lassen wir das Leben den Lebenden.\n\nIch sag' Euch was, T'chali hat hier immer noch ein paar Sahnestückchen in seinem Grab. Sucht Euch aus, was Euch am besten gefällt!", rewards = "Perlen des HexendoktorsT'chalis KiltGürtel des VerhexersEntweiherhandschützer der OgerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10545] = {title = "Saufgelage der Speerspießer", objective = "Macht mit Blutschlägers Hauweggebräu 5 Oger der Speerspießer betrunken.", description = "Wie T'chali schon gesagt hat, hat er seinen Freunden von den Blutschlägern dabei geholfen, Ihr Gebräu zu brauen. Aber T'chali hat ihnen nicht gesagt, warum.\n\nDie Blutschläger stecken ziemlich in der Klemme. Da die Speerspießer drohen, sie zu zermalmen, brauchten die Blutschläger eine neue Waffe, um sie im Kampf zu unterstützen.\n\nDa kam T'chali auf eine tolle Idee. Warum nicht das perfekte Getränk brauen, das einen selbst stärkt und die Feinde schwächt? Der Haken ist nur, dass T'chali nicht weiß, ob es geklappt hat.\n\nBringt dieses Gebräu also zur Wehr der Speerspießer und schaut, ob es funktioniert!", progress = "Sagt es T'chali... hat das Gebräu funktioniert? Haben die Speerspießer es gemocht?", completion = "Das sind gute Nachrichten! Das Gebräu wird bei der nächsten Aufgabe, die T'chali für Euch hat, nützlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10546] = {title = "Borak, Sohn von Oronok", objective = "Sucht Borak, Sohn von Oronok, in der Nähe der Stätte der Mondfinsternis im Schattenmondtal.", description = "Während Ar'tor auf der Jagd war und Grom'tor kämpfte, verbrachte Borak seine Zeit mit Lernen. Dann nahm er eine Stelle als Gelehrter an und ist nach Draenor aufgebrochen. Vor ein paar Jahren kam er als ganz neuer Orc zurück.\n\nSeine erhöhte Aufmerksamkeit und Geistesschärfe haben ihn zu einem schweigsamen Meuchelmörder gemacht.\n\nJetzt, da er ein Orc mit Selbstvertrauen und Macht ist, hat er sich aufgemacht, um das bestgehütete Teil der Litanei zu beschaffen.\n\nSucht Borak. Er versteckt sich in der Nähe der Stätte der Mondfinsternis, weit im Süden. Er liegt im Schatten der Brücke auf der Lauer.", progress = nil, completion = "&lt;Borak ist für einen Moment still.&gt;\n\nIch beobachte diese Blutelfen schon seit Wochen und versuche herauszufinden, wo sie den dritten Teil der Litanei der Verdammnis aufbewahren.\n\nSo weit habe ich jedoch keine brauchbaren Hinweise sammeln könne. Ich weiß nur, dass Illidan einmal am Tag einen Entsandten vom Schwarzen Tempel herschickt.\n\nDieser Entsandte ist unantastbar. Ich habe ihn eine Woche lang überwacht und nach einem Weg gesucht, ihn von seiner Leibwache zu trennen. Die Leibwache verlässt jedoch unglücklicherweise nie seine Seite.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10547] = {title = "Von Distelköpfen und Eiern...", objective = "Borak, Sohn von Oronok, bei der Brücke nördlich der Stätte der Mondfinsternis möchte, dass Ihr ein verfaultes Arakkoaei besorgt und es zu Tobias dem Faulfraß in Shattrath, nordwestlich der Wälder von Terokkar, bringt.", description = "Wenn es mir nicht aufgefallen wäre, hätte ich aufgegeben. Er ist ein Distelabhängiger. Zuerst habe ich es nicht verstanden, aber die Zeichen sind alle da...\n\nWenn wir an ein paar Blutdisteln herankämen, wären wir im Geschäft.\n\nAuf meinen Reisen habe ich in Shattrath einen zwielichtigen Zerschlagenen namens Tobias getroffen.\n\nTobias verdient sein Geld damit, den Blutelfen im Austausch gegen verfaulte Arakkoaeier Blutdisteln zu geben.\n\nDirekt westlich von hier befinden sich Ruinen der Arakkoa. Durchsucht sie nach einem Ei und begebt Euch dann in das Untere Viertel von Shattrath. Dort findet Ihr Tobias.", progress = "<Tobias hebt eine Augenbraue.>\n\nBlutdistel? Nie davon gehört... Seid Ihr ein Friedensbewahrer? Ihr wisst, dass Ihr mir sagen müsst, wenn Ihr einer seid... Ich habe schließlich Rechte!", completion = "Ihr habt ein verfaultes Arakkoaei? Nun, warum habt Ihr das denn nicht gleich gesagt? Ich denke, wir sind im Geschäft.\n\n&lt;Tobias lächelt und entblößt dabei eine Reihe verfaulter und vergilbter Zähne.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10548] = {title = "Die traurige Wahrheit", objective = "Eralan in Tristessa möchte, dass Ihr den Schrumpfkopf des Archäologen aus einer der Truhen in Zeb'Tela oder Zeb'Nowa besorgt.", description = "Erinnert Ihr Euch daran, dass ich von einem fetten Händler sprach, der auf der Suche nach diesem Ring war? Wie es aussieht, hat er seinen Sohn, der Archäologe ist, danach geschickt. Es scheint jedoch kein allzu gutes Ende genommen zu haben. Mit nicht allzu gut meine ich, dass sie ihn getötet und einen Schrumpfkopf aus ihm gemacht haben.\n\nDas klingt jetzt vielleicht eiskalt, berechnend und unheimlich gefühllos, aber er ist bereit, eine stolze Summe für den Kopf seines Sohns hinzublättern. Klingt nach der perfekten Aufgabe für Euch!\n\nGeht nach Osten, bis Ihr die Trollruinen von Zeb'Tela und Zeb'Nowa erreicht. Er müsste sich dort in einer der Truhen befinden.", progress = "Wie geht die kopflose Suche voran?", completion = "Oh, wow. Das ist nicht gerade hübsch. Ich bin mir sicher, dass der Händler ihn mehr schätzen wird, als ich.\n\nAls Bezahlung hat der Händler angeboten, Euch eine meiner Spezialwaren zu kaufen. Also sucht Euch etwas aus, Süsse!", rewards = "LaubklingendolchGeisterklauentunikaIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10550] = {title = "Ein Bündel von Blutdisteln", objective = "Bringt das Blutdistelbündel zurück zu Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal.", description = "Ich habe nicht gelogen. Das Ei war unglaublich. Woher hattet Ihr es?\n\nNun, falls Ihr jemals mehr Blutdisteln brauchen solltet, wisst Ihr ja, wo Ihr mich findet und was ich benötige.\n\nDa habt Ihr ein Bündel von dem Zeug. Bringt es zurück zu Eurem Auftraggeber.", progress = "Habt Ihr die Blutdisteln?", completion = "Jetzt müssen wir die Falle stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10551] = {title = "Loyalität gegenüber den Aldor", objective = "Seid Ihr Euch Eurer Wahl sicher, <Name>? Die Aldor heißen Euch gerne als Verbündeten willkommen, aber die Seher werden Euch Eure Entscheidung nicht so leicht vergeben.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10552] = {title = "Loyalität gegenüber den Sehern", objective = "Seid Ihr Euch Eurer Wahl sicher, <Name>? Die Seher heißen Euch gerne als Verbündeten willkommen, aber die Aldor werden Euch Eure Entscheidung nicht so leicht vergeben.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10553] = {title = "Voren'thal der Seher", objective = "Sprecht mit Voren'thal dem Seher in der Bibliothek der Seher bei der Sehertreppe in Shattrath.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Jetzt, da Ihr Euch für eine Seite entschieden habt, <Name>, solltet Ihr den Anführer der Seher kennenlernen.\n\nIhr findet Voren'thal den Seher in der Bibliothek der Seher auf der Sehertreppe.\n\nSchaut nach, ob Ihr ihn unterstützen könnt. Er wird sich über Eure Entscheidung, den Sehern beizustehen, sehr freuen.", progress = nil, completion = "Khadgar hat einen neuen Rekruten geschickt? Dann wollen wir Euch mal beschäftigen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10554] = {title = "Ishanah", objective = "Sprecht mit Ishanah im Schrein des unendlichen Lichts auf der Aldorhöhe in Shattrath.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Jetzt, da Ihr Euch für eine Seite entschieden habt, <Name>, solltet Ihr die Anführer der Aldor kennenlernen. Ihr findet Hohepriesterin Ishanah im Schrein des unendlichen Lichts.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich bin froh, dass Ihr Euch entschieden habt, unserer Sache beizustehen. Möge das Licht Euch stets beschützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10555] = {title = "Fauler Zauber", objective = "Sammelt 18 ausgezupfte Federn der Lashh'an.", description = "Die Magie der Arakkoa der Lashh'an ist unnatürlich. Sie reißen sich ganze Hände voll - oder Klauen voll - ihrer eigenen Federn als Reagenz heraus!\n\nFür mich klingt das nicht gerade nach guter Magie. Ich bin hierhergekommen, um mehr über ihre Zauber zu erfahren, aber näher heranzugehen ist einfach eine Nummer zu groß für mich.\n\nIhr könntet es jedoch schaffen. Wirkt einen ihrer Zauber auf Euch selbst und kehrt dann zu mir zurück. Ihr müsst eines ihrer Zauberbücher finden, das sich hoch oben in den Bäumen des Lashhverstecks befindet.\n\nUnd falls Euch nicht irgendwo am Körper versteckte Federn wachsen, müsst Ihr ein paar davon sammeln.", progress = "Die groben Piktogramme in dem uralten Folianten weisen darauf hin, dass eine große Menge von Federn der Lashh'an benötigt wird, um die Sprüche in dem Buch zu wirken.", completion = "Ihr blättert die Seiten voll gekritzelter Notizen in der dünnen Schrift der Arakkoa der Lashh'an durch und findet ein Piktogramm, das die Kreise der Macht, die Ihr im Lashhversteck gesehen habt, darstellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10556] = {title = "Gekritzel", objective = "Benutzt die Handvoll Federn im Zauberzirkel der Lashh'an.", description = "Die Piktogramme deuten darauf hin, dass für das Wirken der Zauber in den Zirkeln der Macht im Lashhversteck Federn benutzt werden.\n\nVerwirrende Bilder scheinen einen Arakkoa zu zeigen, der vom Geist eines Kaliri eingehüllt wird.", progress = "Das ist so aufregend! Ich kann es kaum abwarten, die Wirkung des Zaubers zu untersuchen!", completion = "Ich weiß nicht, was ich sagen soll. Dieser Zauber ist sehr merkwürdig. Es handelt sich nicht um eine einfache Beschwörung oder Verzauberung, sondern eher um eine Art Vereinigungs- oder Kommunikationszauber.\n\nIch weiß nicht, was ich davon halten soll, &lt;Name&gt;. Ich muss noch ein wenig darüber nachdenken.\n\nAber trotzdem vielen Dank für Eure Hilfe! Ich bin sicher, dass ich früher oder später dahinter komme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10557] = {title = "Testflug: Das Zephyriumkapazitorium", objective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium.", description = "Ich habe ein sagenhaftes Gerät erfunden: das Zephyriumkapazitorium. Ich bin mir sicher, dass es einwandfrei funktionieren wird, aber... habt Ihr Lust, es für mich zu testen?\n\nEs gibt auch genügend Gefahrenzulage!\n\nSprecht mit Rally, meinem Zwilling da drüben. Viel Glück, <Name>. Kommt nach dem Experiment zu mir zurück. Oder.. falls das wegen erlittener Verletzungen nicht möglich ist, schickt einen nahen Verwandten, um Eure Bezahlung abzuholen.", progress = "Keine Angst! Es ist für die Wissenschaft, und Wissenschaft ist Krieg!", completion = "Wow, Ihr habt es geschafft! Und kein einziger blauer Fleck oder offener Knochenbruch! Seht Ihr, ich habe Euch doch gesagt, dass alles funktionieren wird!\n\nHier ist Eure Bezahlung, &lt;Name&gt;. Ich habe die Arztkosten gleich dazu gerechnet, aber da Ihr sie nicht gebraucht habt, seht es einfach als kleinen Bonus an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10558] = {title = "Respektvoller Ruf in der Ehrenfeste", objective = "Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr Euch einen respektvollen Ruf in der Ehrenfeste verschafft, indem Ihr die Höllenorcs in den Zerschmetterten Hallen der Höllenfeuerzitadelle tötet.", description = "Ihr habt Euch für unsere Sache als hilfreich erwiesen, <Name>. Jemand wie Ihr hat das Zeug, ein großer Anführer zu werden.\n\nKämpft auch weiterhin gegen unsere Feinde in den Zerschmetterten Hallen und verdient Euch die Achtung meiner Männer. Wenn Ihr meine Erwartungen erfüllt, werde ich Euch großartigere Aufträge geben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10559] = {title = "Respektvoller Ruf in Thrallmar", objective = "Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr Euch einen respektvollen Ruf in Thrallmar verschafft, indem Ihr die Höllenorcs in den Zerschmetterten Hallen der Höllenfeuerzitadelle tötet.", description = "Ihr habt Euch immer und immer wieder als würdig erwiesen, <Klasse>. Und doch warten noch mehr Prüfungen auf Euch.\n\nKämpft weiter gegen die Höllenhorde in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Dann wird Euer Name bald allen Freunden Thrallmars im ganzen Land bekannt sein!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10560] = {title = "Respektvoller Ruf bei den Sha'tar", objective = "A'dal in Shattrath möchte, dass Ihr Euch einen respektvollen Ruf bei den Sha'tar verschafft, indem Ihr Kael'thas Streitkräfte in der Festung der Stürme tötet.", description = "<Die beruhigenden melodischen Töne, die von A'dal ausgehen, werden leiser und dunkler.>\n\n<Euch wird das große Naarugebäude, das als Festung der Stürme bekannt ist, gezeigt. Jetzt wird es von Kael'thas Streitmächten bewohnt und seine Macht wird zu bösartigen Zielen eingesetzt. A'dal verspricht Euch größere Aufgaben, wenn Ihr Euren Teil in der Festung der Stürme beigetragen habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10561] = {title = "Respektvoller Ruf bei den Hütern der Zeit", objective = "Andormu in den Höhlen der Zeit in Tanaris möchte, dass Ihr Euch einen respektvollen Ruf bei den Hütern der Zeit verdient, indem Ihr weiterhin die Ereignisse im Alten Hügelland und dem Schwarzen Morast in den Höhlen der Zeit verteidigt.", description = "Ihr habt Euch bewiesen, <Volk>. Jedoch ist die Zeitlinie immer noch nicht sicher.\n\nWir brauchen Helden; und Ihr könntet einer davon sein.\n\nBeschützt die Geschehnisse der Vergangenheit auch weiterhin gegen Eindringlinge. Dann werdet Ihr die Achtung bekommen, die Euch zusteht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10562] = {title = "Belagert!", objective = "Schwadronskommandant Nuainn außerhalb der Wildhammerfeste möchte, dass Ihr 10 angreifende Höllenbestien tötet.", description = "Ihr müsst weiterhin wachsam bleiben, <Volk>. Wir stehen unter ständigem Angriff der Brennenden Legion.\n\nDie Dämonen lassen von ihrem Lager in der Feste der Legion aus ständig neue Höllenbestien auf uns herabregnen. Und sobald wir sie getötet haben, schlagen neue Meteoriten ein und eine neue Angriffswelle geht los.\n\nMeine Männer sind erschöpft und ausgelaugt. Ich weiß nicht, wie lange sie das noch durchhalten. Bitte, <Name>, helft uns bei der Verteidigung. Nehmt Euren Platz in der Linie ein und haltet den Vormarsch der Höllenbestien auf!", progress = nil, completion = "Danke, dass Ihr meine Männer unterstützt habt, &lt;Name&gt;. Mit Eurer Hilfe und der Hilfe anderer, können wir vielleicht noch länger durchhalten. Unglücklicherweise ist Durchhalten leider nicht genug. Wir müssen zum Angriff übergehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10563] = {title = "Zur Feste der Legion", objective = "Begebt Euch zur Feste der Legion und findet das Kommunikationsgerät der Legion. Benutzt die Verkleidung, während Ihr in der Nähe des Kommunikationsgeräts steht, um mehr über die Pläne der Legion herauszufinden. Kehrt danach zu Schwadronskommandant Nuainn in der Wildhammerfeste zurück.", description = "Die Feste der Legion ist fast uneinnehmbar. Und um ganz ehrlich zu sein kann ich keine Streitkräfte für einen Angriff entbehren. Unsere Hoffnungen ruhen auf Euch, <Name>.\n\nDie wenigen Informationen, die wir sammeln konnten, weisen darauf hin, dass die Legion die Höllenbestien in der Feste lagert und vorbereitet. Ich möchte, dass Ihr die Feste in der Verkleidung, die ich Euch geben werde, nach detaillierten Informationen über die Pläne der Legion durchsucht. Wir können nur hoffen, dass Ihr die Gespräche zwischen ihren Kommandanten abfangen oder belauschen könnt. Viel Glück, <Name>.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Schwadronskommandant Nuainn hört sich Euren Bericht an und wird mit jedem Satz nervöser.&gt;\n\nIhr sagt also, dass sie genügend Höllenbestien haben, um die Angriffe noch zu verstärken? Wenn wir sie nicht aufhalten, bevor sie die nächste Phase ihres Plans umsetzen können, ist die Wildhammerfeste verloren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10564] = {title = "Jagt die Höllenbestien in die Luft!", objective = "Zündet die Teufelsbombe, während Ihr auf der grünen Glyphe in der Feste der Legion steht. Meldet Euch bei Schwadronskommandant Nuainn in der Wildhammerfeste zurück, wenn Ihr Euren Auftrag erledigt habt.", description = "Das Gerät, das wir zusammengebaut haben, würde keinen Schönheitspreis gewinnen, aber es sollte die Höllenbestien in der Feste der Legion zerstören können. Danach zu urteilen, was der Kraftkern des Teufelshäschers bei dem Fauligen Teich angerichtet hat, muss darin eine gehörige Explosionskraft stecken.\n\nWenn Ihr das Gerät in der Mitte der grünen Glyphe in der Feste platzieret, solltet Ihr alle Höllenbestien erwischen können.", progress = "Habt Ihr einen Weg gefunden, um den Vorrat an Höllenbestien der Legion zu zerstören?", completion = "Gut gemacht, &lt;Name&gt;! Ich wünschte, ich könnte behaupten, dass die Legion nach einem Rückschlag wie diesem aufgeben wird, aber das würdet Ihr mir ohnehin nicht glauben. Die Todesschmiede, von der Ihr erfahren habt, wird unser nächstes Ziel sein.", rewards = "SterndeuterkiltKopfputz des MondwappensPurpurrote PanzerhalsbergeBlutgeschmiedeter WächterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10565] = {title = "Die Steine der Vekh'nir", objective = "Sammelt einen Kristall der Vekh'nir und benutzt ihn beim Zauberzirkel der Vekh'nir, um ihn aufzuladen.", description = "Die Arakkoa der Vekh'nir sind uns schon seit vielen Jahren ein Dorn im Auge. Sie praktizieren eine merkwürdige Religion, die sie in ständiger Betriebsamkeit hält. Sie tragen nun diese Kristalle bei sich, die sie für irgendwelche dunklen Zwecke einsetzen.\n\nIch kenne mich ein wenig mit ihren Ritualen aus. Sie bringen die Kristalle zu ihren Zauberzirkeln, um sie dort aufzuladen. Wir im Dorf wüssten gerne mehr darüber. Lauert ein paar der Arakkoa auf, bis Ihr einen Kristall findet. Ladet ihn danach auf und bringt ihn zu mir zurück.", progress = "Die Arakkoa der Vekh'nir waren viele Jahre lang gütige Wesen., doch nun hat sie etwas aufgehetzt.", completion = "Ah, schaut nur, wie er leuchtet! Ich muss ihn sofort ausprobieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10566] = {title = "Probieren geht über Studieren", objective = "Probiert jeden von Dertroks Zauberstäben an einem Ogersklaven der Arakkoa aus. Ihr benötigt einen energieerfüllten Kristall der Vekh'nir für jeden Stab, den Ihr benutzen wollt.", description = "Ich habe vier Zauberstäbe hergestellt, die die Macht der Arakkoakristalle verstärken sollten. Bringt diese Stäbe zu Trogmas Besitz und probiert sie an den Ogersklaven aus.\n\nIhr benötigt einen energieerfüllten Kristall von den Arakkoa in der Gegend, um die Stäbe zu benutzen.\n\nKommt zu mir zurück, sobald Ihr herausgefunden habt, welcher Stab am besten funktioniert.", progress = "Ich warte gespannt auf Eure Ergebnisse, <Name>.", completion = "Diese Informationen werden uns sehr viel weiterhelfen, &lt;Name&gt;. Ich werde den Zauberstab noch verbessern und schauen, ob wir ihn auch für weitere Zwecke einsetzen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10567] = {title = "Die Herstellung des Anhängers", objective = "Sammelt 6 Klauen der Ruuan'ok und benutzt sie bei dem Orakelkreis der Ruuan'ok, um einen Herold des Raben herbeizurufen. Tötet ihn, um den Anhänger des Herolds an Euch zu bringen.", description = "Unter den Arakkoa des Ruuanwaldes nehmen die Herolde des Raben innerhalb der Brut eine besondere Stellung ein, da sie die Boten ihres Gottes sind.\n\nDie Arakkoa glauben, dass die Herolde vom Himmel aus, wo sie den Lehren des Raben lauschen, über sie wachen und hinabsteigen, um sein Wort zu verbreiten.\n\nDie Herolde haben einen starken Einfluss auf die Seelen der Arakkoa. Sie benutzen magische Anhänger, die wir benötigen.\n\nLockt einen der Herolde herbei, indem Ihr seine Brut tötet und ihre Klauen abtrennt. Legt die Klauen auf den Altar, um seine Aufmerksamkeit zu erregen.", progress = "Sobald der Herold bemerkt, dass Ihr seine Brut angreift, wird er sicher schnell reagieren.", completion = "Ihr habt ihn!\n\nMit diesem Anhänger werde ich dafür sorgen können, dass Ihr die Sprache der Arakkoa aus Grishnath versteht.\n\nHiermit werden wir die Arakkoa und das Wesen des Raben besser verstehen lernen. Ich brauche dazu Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10568] = {title = "Schrifttafeln von Baa'ri", objective = "Anachoret Ceyla beim Altar der Sha'tar möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Vor vielen Jahren schuf der gefürchtete Orchexenmeister Gul'dan den Vulkan, der sich in der Mitte von Schattenmond befindet. Die Draeneistadt Baa'ri wurde mitsamt seiner Einwohner und vielen wichtigen religiösen Artefakten unter der Lava begraben.\n\nDie verräterischen Zerschlagenen der Aschenzungen wurden von Illidan beauftragt, in dieser Gegend Ausgrabungen durchzuführen. Wir müssen diese Chance nutzen, um an die Schrifttafeln von Baa'ri zu kommen. Dieser alte Text soll angeblich die Geheimnisse des Tempels von Karabor, der heute als Schwarzer Tempel bekannt ist, enthalten.", progress = "Habt Ihr die Schrifttafeln schon gefunden, <Name>?", completion = "Die Schrifttafeln von Baa'ri! Ja, die werden uns sehr wichtige Informationen liefern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10569] = {title = "Das Wrack der Sketh'lon", objective = "Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Greifenreiter Kieran.", description = "Unsere Späher haben uns erschütternde Berichte aus den zerstörten Arakkoalagern in der Gegend geliefert.\n\nDie Geister der mächtigen Arakkoamagier verfügen über nie geahnte Kräfte! Sie scheinen sich zu formieren, als ob sie etwas planten, aber wir wissen nur sehr wenig darüber. Wir können uns nicht leisten, die Augen davor zu verschließen!\n\nReist nach Norden zum Wrack der Sketh'lon, nordwestlich der Todesschmiede, und sucht nach Anzeichen für ihre Beweggründe.", progress = "Was habt Ihr entdeckt?", completion = "&lt;Kieran wirft einen kurzen Blick auf die Tagebuchseiten.&gt;\n\nVieles davon ist unleserlich, aber ich kann hier und da ein paar Worte verstehen. Es geht um eine fehlgeschlagene Vorbereitung eines Zaubers, Opfer und eine sich verschlechternde Situation. Hier steht auch irgendetwas Merkwürdiges über einen 'Deserteur'.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10570] = {title = "Einen Distelsüchtigen fangen", objective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr Sturmgrimms Schriftwechsel beschafft.", description = "<Borak nimmt Euch das Blutdistelbündel ab und riecht daran.>\n\nStechend...\n\nJetzt nehmt das Bündel und legt es am anderen Ende dieser Brücke ab. Wenn der Entsandte seine tägliche Runde macht, wird er gar nicht anders können, als es aufzuheben - ohne seine Leibwache. Wisst Ihr, Blutelfen verachten Blutdistelabhängige. Wenn einer seiner Gefährten das je herausfinden würde...\n\nIhr müsst nur daliegen und abwarten, bis er seine Leibwache fortschickt. Wenn er alleine ist, schlagt zu! Tötet ihn und nehmt Euch den Schriftwechsel.", progress = "Beeilt Euch, Junge!", completion = "&lt;Borak nimmt den Schriftwechsel und beginnt zu lesen.&gt;\n\nGerissene Hunde! Dies ist eine Anordnung von Illidan, die besagt, wo die Litanei der Verdammnis als nächstes versteckt werden soll. Offensichtlich ändern sie den Aufenthaltsort ständig. Aber wir wissen leider nicht, wo es sich im Augenblick befindet... Wenn wir diesen Brief doch nur abliefern könnten, jetzt, da wir wissen, wo sie es dann verstecken werden.\n\nWie schade, dass das Siegel nun zerbrochen und der Brief damit nutzlos ist.\n\nHmm... Es sei denn...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10571] = {title = "Oronu der Älteste", objective = "Anachoret Ceyla beim Altar der Sha'tar möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Laut den Schrifttafeln wurde in Baa'ri ein Artefakt, das als Medaillon von Karabor bekannt ist, aufbewahrt. Nur die höchstrangigen Draeneipriester durften es tragen, da es uneingeschränkten Zugang zum Tempel von Karabor bot.\n\nWir müssen herausfinden, ob die Aschenzungen das Medaillon schon gefunden haben. Seine Macht wäre uns eine große Hilfe im Kampf gegen Illidan.\n\nAkamas Leutnant in Baa'ri, Oronu der Älteste, erhält täglich schriftliche Befehle von Akama. Besorgt sie Euch und bringt sie mir.", progress = "Gibt es schon Neuigkeiten, <Name>? Wir haben nicht viel Zeit.", completion = "Akamas Handschrift. Es ist wirklich sehr traurig, was aus jemandem werden konnte, der so weise und beliebt war wie er.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10572] = {title = "Die Bombe bauen", objective = "Besorgt Euch einen Teufelshäscherkraftkern und eine Teufelshäscherrüstungsplatte und bringt sie zu Schwadronskommandant Nuainn in der Wildhammerfeste.", description = "Wir können der Legion nicht erlauben, die Wildhammerfeste auf ihrem Marsch zum Schwarzen Tempel zu zertrampeln.\n\nEs gibt nur einen Weg, um sie aufzuhalten, <Name>. Ihr müsst einen Sprengkörper herstellen, der groß genug ist, um den gesamten Vorrat an Höllenbestien in der Feste der Legion zu zerstören.\n\nAm Fauligen Teich in der Nähe der Feste der Legion gibt es viele alte Teufelshäscherkraftkerne, die Ihr als Grundlage für Euer Gerät verwenden könnt. Durchsucht die anderen Trümmer in der Nähe der Feste nach einer Rüstungsplatte, aus der wir ein Gehäuse bauen können.", progress = "<Ihr reicht dem Schwadronskommandanten die Materialien.>", completion = "&lt;Der Schwadronskommandant setzt den Kraftkern in die Rüstplatten und versiegelt nickend das Gerät.&gt;\n\nDas sollte klappen. Und es sollte auch eine ziemlich große Explosion von sich geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10573] = {title = "Die Todesschmiede", objective = "Meldet Euch bei Sturmrufer Ewan Wildschwinge im Turm der Todesschmiede.", description = "Von Euren Entdeckungen in der Feste der Legion konnten wir erfahren, dass die Verbündeten der Legion vom Schattenrat Höllenbestien in der Todesschmiede herstellen. Ich habe einen kleinen Spähertrupp geschickt, um die Gegend zu überwachen, aber leider können sie nicht alle anstehenden Aufgaben erfüllen.\n\nWenn wir die Todesschmiede weiter arbeiten lassen, werden sie den Vorrat an Höllenbestien, den Ihr vernichtet habt, im Handumdrehen wieder aufgestockt haben.\n\nIch möchte, dass Ihr Euch mit Sturmrufer Ewan Wildschwinge unterhaltet. Ihr findet ihn im Turm der Todesschmiede, der die Schmiede überblickt, nordwestlich von hier.", progress = nil, completion = "&lt;Der Zwerg nickt.&gt;\n\nVerstärkung ist gut. Wir haben bisher grundlegende Informationen über die Pläne des Schattenrats hier gesammelt, aber ich wäre sehr froh, wenn wir endlich gegen sie vorgehen könnten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10574] = {title = "Die Verderber der Aschenzungen", objective = "Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Anachoret Ceyla beim Altar der Sha'tar im Schattenmondtal zurück.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Laut Akamas Brief wurden vier Teile des Medaillons ausgegraben und den Verderbern der Aschenzungen übergeben. Diese gefürchteten Zerschlagenen waren einst mächtige Schamanen, die nun die Elemente schänden, die sie einst verehrten.\n\nHaalum, der Verderber der Luft, befindet sich am Netherschwingenpass. Eykenen und Uylaru, die Verderber der Erde und des Feuers, wurden zuletzt bei den Teufelsgruben in der Nähe der Hand des Gul'dan gesehen. Lakaan, der Verderber des Wassers, soll sich in der Nähe der Echsennarbe aufhalten.\n\nFindet sie und besorgt Euch die Medaillonfragmente von ihnen.", progress = "Habt Ihr die vier Fragmente des Medaillons, <Name>?", completion = "Ja! Die vier Fragmente des Medaillons. Und nun setzt sie zusammen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10575] = {title = "Der Kerker des Wächters", objective = "Anachoret Ceyla möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru befragt, um Akamas Aufenthaltsort herauszufinden.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Seher.", description = "Die Fragmente, die Ihr besorgt habt, sind nur eine Hälfte des Amuletts. Der Anführer der Aschenzungen, Akama, muss die andere Hälfte haben.\n\nIch wage es fast nicht, Euch darum zu bitten, da Akama sowohl böse als auch gerissen ist.\n\nEr und die Todeshörigen der Aschenzungen, die bösartigsten und grausamsten der Zerschlagenen, sollen irgendwo im Kerker des Wächters eine Folterkammer betreiben.\n\nIch möchte, dass Ihr dieses gefürchtete Gefängnis findet und Akamas Aufenthaltsort bestimmt. Sein Stellvertreter vor Ort ist ein Zerschlagener namens Sanoru. Befragt ihn, wenn Ihr müsst.", progress = nil, completion = "Wir haben Euch erwartet, &lt;Name&gt;. Akama sagte, dass Ihr früher oder später kommen würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10576] = {title = "Unterwürfigkeit in Schattenmond", objective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr 6 Teile der Rüstung der Mondfinsternis besorgt.", description = "<Borak mustert Euch.>\n\nEs wird schwierig, aber ich glaube, es könnte klappen.\n\nIch kann Euch als einen von Illidans Blutelfen verkleiden, <Name>. Aber zuerst benötige ich dazu einige Teile ihrer Rüstung. Sie muss unbedingt sauber sein. Keine Blutflecken! Wir wollen schließlich keinen Verdacht erwecken.\n\nBringt mir die Ausrüstung und ich kümmere mich um den Rest der Verkleidung.\n\nSobald die Verkleidung fertig ist, werdet Ihr dem Großkommandanten die Nachricht überbringen - persönlich!", progress = "Das ist viel zu kompliziert, <Volk>. Ihr würdet es nicht verstehen.", completion = "Gut gemacht, &lt;Name&gt;. Ich hoffe, Ihr seid ein guter Schauspieler. Der nächste Schritt erfordert etwas Theatralik!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10577] = {title = "Was Illidan will, soll Illidan bekommen...", objective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr Großkommandant Ruusk in der Stätte der Mondfinsternis Illidans Nachricht überbringt.", description = "Nehmt diese Verkleidung und begebt Euch zur Stätte der Mondfinsternis. Wenn Ihr dort seid, benutzt die Verkleidung, um Euch zu tarnen. Die Blutelfen der Mondfinsternis werden Eure Verkleidung nicht durchschauen können. Daher habt Ihr freie Bahn, bis Ihr zu Großkommandant Ruusk gelangt.\n\nSobald Ihr Ruusk gefunden habt, sagt ihm Bescheid, wo das Wort als Nächstes versteckt werden soll. Ihr müsst schauspielern, was das Zeug hält, <Name>. Gebt vor, ein Untergebener zu sein, der eine Nachricht seines Fürsten überbringt. Das sollte funktionieren.\n\nAber gebt auf die Drachenfalken Acht. Sie können Eure Verkleidung durchschauen.", progress = nil, completion = "Jetzt müsst Ihr nur noch die Litanei besorgen. Einfach, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10578] = {title = "Die Litanei der Verdammnis - Boraks Angriff", objective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr den dritten Teil der Litanei der Verdammnis von Ruul dem Verfinsterer besorgt.\n\nFür diesen Auftrag werdet Ihr eine Gruppe benötigen.", description = "Zuluhed wird diesen Teil der Litanei niemals bekommen. Ihr werdet Ruul dem Verfinsterer und seinem Transportgut auflauern, bevor er eine Chance hat, es abzuliefern.\n\nDie Festung des Drachenmals liegt direkt östlich von hier, jenseits der Netherschwingenfelder. Ihr findet Ruul irgendwo zwischen der Feste des Drachenmals und dem Sanktum der Sterne. Schlagt schnell und hart zu! Und seid vorsichtig, <Name>. Ruul scheint eine harte Nuss zu sein.\n\nBringt die Litanei zu mir zurück, wenn Ihr erfolgreich wart.", progress = "Ihr müsst schnell handeln!", completion = "Endlich! Das Fragment der Litanei gehört uns!\n\n&lt;Borak verstaut das Fragment in einer Schließkassette.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10579] = {title = "Die Litanei der Verdammnis - Dritter Teil", objective = "Bringt Boraks Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal.", description = "Bringt diese Kassette zu meinem Vater. Er wohnt immer noch bei Oronoks Hof weit im Norden, über der Zisterne der Echsennarbe. Wenn alle drei Teile zusammengefügt sind, wird die alte Litanei auf ein Neues bekannt sein.\n\nViel Glück, <Name>. Sagt meinem Vater, dass ich bald nach Hause komme.", progress = "<Name>!", completion = "Sobald alle drei Teile der Litanei zusammengefügt sind, wird es wieder bekannt.\n\nDieses Dokument zu besorgen war zweifellos eine große Herausforderung. Für einen solchen Heldenmut müsst Ihr belohnt werden.", rewards = "Schiftung des HerzeleidSchuhe aus TeufelseberbalgUmbras HalsbandAr'tors fester GriffBoraks Gürtel der TapferkeitDie Hände des SchicksalsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10580] = {title = "Wo sind diese verdammten Gnome hin?", objective = "Sucht im südlichen Teil des Zackengrats im Schergrat nach Hinweisen auf den Verbleib von Toshley und seinen Gnomenfreunden.", description = "Trotz all der guten Dinge, die wir hier getan haben, fühle ich mich wegen einer Sache schlecht: Wir haben Toshley und seine Gnomenfreunde vertrieben.\n\nWir hatten keine andere Wahl; sie haben mit all ihrer Technologie und ihren Experimenten unsere Bemühungen im Hain zunichtegemacht.\n\nIch wäre Euch sehr dankbar, wenn Ihr herausfinden könntet, was aus ihnen geworden ist. Unseren letzten Informationen zufolge sind sie nach Osten über die Brücke gegangen. Ich bin mir sicher, dass sie dann nach Süden von der Donnerfeste weg gezogen sind.\n\nHaltet im südlichen Zackengrat nach Spuren von ihnen Ausschau.", progress = nil, completion = "SYLVANAAR? KOMMANDANT HIMMELSSCHATTEN?\n\nKEIN DATENBANKEINTRAG!\n\nTRETET ZURÜCK, BEVOR ICH MICH GEZWUNGEN SEHE, EUCH MIT LAUTEN GERÄUSCHEN ZU QUÄLEN!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10581] = {title = "Folget den Brotkrumen", objective = "Folgt der Spur aus Ersatzteilen den Weg hinauf zum Messergrat und sprecht mit Toshley in Toshleys Station im Schergrat.", description = "HIERMIT WARNE ICH EUCH, DASS IHR AUF DEM GRAT NICHTS FINDEN WERDET.\n\nFOLGT AUF KEINEN FALL DEN ERSATZTEILEN, DIE ZU TOSHLEYS STATION FÜHREN! IHR WERDET DORT WEDER TOSHLEY NOCH EINEN ANDEREN GNOM VORFINDEN!", progress = nil, completion = "In Ordnung, wollt Ihr Euch nützlich machen? Gut, ich habe genau die richtige Aufgabe, mit der Ihr Euch beweisen könnt.\n\nIch glaube, Ihr werdet sie mögen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10582] = {title = "Diener des Schattenrats", objective = "Sturmrufer Ewan Wildschwinge beim Turm der Todesschmiede möchte, dass Ihr 10 Wächter der Todesschmiede und 5 Beschwörer der Todesschmiede tötet.", description = "<Ewan hört Eure Erzählung der Ereignisse in der Feste der Legion an und nickt.>\n\nJetzt geben unsere Beobachtungen einen Sinn. Wir haben gesehen, wie sie Höllenbestien zur Feste der Legion geschafft haben, aber mehr konnten wir nicht herausfinden.\n\nDer Schattenrat hat die Todesschmiede besser versiegelt als ein Fass Donnerbräu! Als erstes müsst Ihr ein paar Köpfe einschlagen, damit Ihr dort eindringen könnt. Fangt damit an, die Mitglieder des Schattenrats, die den Eingang zur Todesschmiede bewachen, zu vernichten!", progress = nil, completion = "Ich wünschte, ich hätte mit Euch gehen können! Ich brenne schon die ganze Zeit darauf, meinen Hammer benutzen zu können, aber mein Auftrag ist es, zu beobachten, nicht zu töten.\n\nJetzt, da Ihr ein Loch in ihre Verteidigung geschlagen habt, lasst uns die Produktion in der Todesschmiede zum Stillstand bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10583] = {title = "Flanis' Schicksal", objective = "Sturmrufer Ewan Wildschwinge beim Turm der Todesschmiede möchte, dass Ihr die Todesschmiede nach Flanis Flinkschwinge absucht und Flanis' Beutel zurückholt.", description = "Schwadronskommandant Nuainn hat ursprünglich drei von uns hierher geschickt, um die Todesschmiede zu beobachten und Informationen zu sammeln. Flanis Flinkschwinge hat sich freiwillig gemeldet, um sich in die Todesschmiede einzuschleichen, aber wir haben schon seit Tagen nichts mehr von ihm gehört.\n\nIch fürchte das Schlimmste, <Name>. Flanis ist ein guter Späher, aber wir haben keine Ahnung, ob ihm die Sache über den Kopf gewachsen ist. Durchsucht die Todesschmiede nach ihm und beschafft sämtliche Informationen oder Gegenstände, die er gesammelt haben könnte.", progress = "Habt Ihr ein Zeichen von Flanis in der Todesschmiede finden können?", completion = "&lt;Ewan schüttelt den Kopf und nimmt Euch den Beutel ab.&gt;\n\nIch glaube nicht, dass Flanis sich im Klaren darüber war, wie schwer die Todesschmiede bewacht ist. Jetzt, da wir wissen, was tatsächlich dort vor sich geht, mache ich ihnen keinen Vorwurf. Ich wünschte nur, dass Flanis es gewusst hätte, als er dort hinein gegangen ist.\n\nIch kann nur hoffen, dass irgendetwas in diesem Beutel uns dabei helfen kann, die Todesschmiede ein für allemal auszuschalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10584] = {title = "Ein paar Stromwandler besorgen", objective = "Verwendet den protovoltaischen Magnetsammler, um 5 Elektromentare einzufangen.", description = "Diese dummen Oger am Außenposten der Speerspießer im Norden haben unsere Stromwandler gestohlen! Und Ihr werdet sie mir zurückbringen, oder so in der Art.\n\nDie Oger haben sie sicher mit ihren groben, ungeschickten Händen kaputt gemacht. Ich möchte, dass Ihr die in ihnen gespeicherte Energie freisetzt und das so entstehende Elektromentar mit diesem protovoltaischen Magnetsammler einfangt.\n\nEs wird sicher sauer auf Euch sein, Ihr müsst es also 'töten', während es im Magnetfeld gefangen ist.", progress = "Diese Forschungsreihe mit den Elektromentaren ist faszinierend! Stellt Euch nur vor... Eine intelligente Kreatur, die wir nach Belieben erschaffen können und die all unseren Anweisungen folgt!\n\nWas kann da schon schiefgehen?", completion = "Ausgezeichnet! Mit der ganzen Energie, die Ihr gesammelt habt, werden wir die Maschinerien für eine Weile am Laufen halten können.\n\nDas Zephyriumkapazitorium ist ein echter Schluckspecht, wenn es um den Energieverbrauch geht!\n\nIch hoffe, mit den Elektromentaren fertig zu werden war nicht allzu schwierig. Ich habe noch eine andere Aufgabe für Euch. Ich fürchte, sie wird etwas schwerer werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10585] = {title = "Die Beschwörungskammer", objective = "Besorgt Euch eine Elementarsteuerung von einem Schmied der Todesschmiede oder einem Tüftler der Todesschmiede. Benutzt sie, um das Ritual in der Beschwörungskammer zu unterbrechen. Meldet Euch danach bei Sturmrufer Ewan Wildschwinge im Turm der Todesschmiede zurück.", description = "Um mit der Konstruktion der Höllenbestien so schnell nachzukommen, muss der Schattenrat einen Bereich bestimmt haben, an dem die verderbten Elemente, die den Höllenbestien als Seele dienen, beschworen werden.\n\nDie Kammer der Beschwörung liegt wahrscheinlich unter der Erde in der Nähe eines Teichs mit fauligem Wasser oder Lava. Sucht die Beschwörungskammer in der Todesschmiede und unterbrecht ihr Beschwörungsritual! Vielleicht tragen die Mo'arg, die bei der Produktion der Höllenbestien teilhaben, ja ein Instrument dabei, mit dem Ihr die Magie der Beschwörer unterbrechen könnt.", progress = "Wir können nicht zulassen, dass sie weiter produzieren. Habt Ihr dem Beschwörungsritual ein Ende gesetzt?", completion = "Gut gemacht, &lt;Name&gt;. Die Beschwörung des Schattenrats zu unterbrechen bringt uns einen Schritt näher an die Abschaltung der Todesschmiede.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10586] = {title = "Nieder mit dem Kriegshetzer!", objective = "Besiegt Kriegshetzer Razuun, beschafft Razuuns Befehle und meldet Euch bei Schwadronskommandant Nuainn in der Wildhammerfeste.", description = "Wir haben große Fortschritte gegen die Operationen des Schattenrats bei der Todesschmiede erzielt. Wenn wir jedoch wirklich siegen wollen, müssen wir den Aufseher der Legion dort vernichten.\n\nIch habe unter den Gegenständen in Flanis Beutel einen Schlüssel gefunden. Ich bin mir sicher, dass er sich bei der Suche nach Kriegshetzer Razuun, den Ihr in der Feste der Legion beobachtet habt, als nützlich erweisen wird.\n\nNachdem Ihr Kriegshetzer Razuun aufgespürt und erschlagen habt, meldet Euch gleich bei Schwadronskommandant Nuainn. Er wird sofort davon erfahren wollen!", progress = "Bringt Ihr Neuigkeiten aus der Todesschmiede?", completion = "&lt;Ihr erstattet dem Schwadronskommandanten Bericht und übergebt die gefundenen Befehle.&gt;\n\nKriegshetzer Razuun zu besiegen sollte eigentlich das Ende unserer Probleme mit der Legion bedeuten, aber in diesen Befehlen steht deutlich mehr, als ich befürchtet hatte. Ich glaube, wir haben noch viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10587] = {title = "Ausbildungsgelände von Karabor", objective = "Exarch Onaala beim Altar der Sha'tar möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, südöstlich des Altars der Sha'tar, beschafft.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Unsere Späher haben uns von einem massiven Zufluss von Blutelfenrekruten des Sonnenzorns in den Ruinen von Karabor berichtet. Normalerweise würden wir darin eine rein militärische Bedrohung sehen, doch wir glauben, dass hier noch mehr im Argen liegt.\n\nDie Beschreibungen ihrer Kleidung und ihres Kampfstils klingen verdächtig nach Illidan selbst. Ich will mich nicht ohne handfeste Beweise beunruhigen, daher möchte ich Euch bitten, dorthin zu gehen und mir ihre Waffen zu bringen. Dann werden wir sehen, ob meine Befürchtungen unbegründet sind oder nicht.", progress = "Habt Ihr die Aufgabe, die ich Euch gegeben habe, schon erledigt, <Name>?", completion = "Wollen wir uns diese Waffen einmal genauer ansehen, &lt;Name&gt;. Hmmm... das ist ziemlich beunruhigend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10588] = {title = "Die Litanei der Verdammnis", objective = "Benutzt die Litanei der Verdammnis am Altar der Verdammnis um Cyrukh den Feuerlord zu rufen.\n\nVernichtet Cyrukh den Feuerlord und sprecht danach mit Erdheiler Torlok, der sich ebenfalls am Altar der Verdammnis befindet.", description = "Wie oft wurde dieser Zauber in der Geschichte unserer Welten benutzt? Seine zerstörerische Macht ist mit Sicherheit einzigartig.\n\nIhr müsst die Litanei nun, da sie vollständig ist, zum Altar der Verdammnis bringen, wo Gul'dans Erinnerung steht, und daraus lesen.\n\nSobald die Worte gesprochen werden, werdet Ihr die Erinnerungen, die in das Land eingebrannt wurden, sehen. Bleibt standhaft und erwartet die Ankunft Cyrukhs.\n\nIhr müsst siegen, <Name>. Dieses Land kann einer weiteren Zerschlagung nicht standhalten.", progress = "Ist es vollbracht?", completion = "&lt;Erdheiler Torlok nimmt Euch die Litanei der Verdammnis ab.&gt;\n\nIhr habt getan, worum Euch die Elemente gebeten haben. Dafür sind wir sehr dankbar. Ihr werdet belohnt werden, doch der Ärger lauert noch immer auf uns. Die Geister des Feuers sind in Aufruhr. Es wurde eine Forderung vorgebracht. Ein weiterer kennt die Litanei der Verdammnis.\n\nIch weiß, das klingt sehr kryptisch, aber das ist alles, was die Geister mir mitgeteilt haben. Das und dieses Symbol...\n\n&lt;Erdheiler Torlok dreht sich um und zeigt gen Himmel.&gt;\n\nWas könnte das wohl bedeuten?", rewards = "Oronoks uraltes SzepterStab des ErlösersHerzeleids Axt des KampfesGrom'tors AngriffLohn'goron, Bogen des HerzeleidBoraks MahnungIhr bekommt:\n\nAmulett des Herzeleid"}
MultiLanguageQuestData['de'][10589] = {title = "Zugang erlangen", objective = "Bringt eine Teleportersteuerung der Legion zu Schwadronskommandant Nuainn in der Wildhammerfeste. Bekanntlich tragen die Waffenschmiede der Mo'arg in der Feste der Legion diese Geräte bei sich.", description = "Laut Razuuns Befehlen wird der riesige Stützpunkt der Höllenbestien Invasionspunkt: Katastrophe genannt und befindet sich in den nördlichen Bergen. Die einzige Weise, auf die man dorthin gelangen kann, ist ein Teleporter, der sich in der Feste der Legion befindet.\n\nAusgewählte Mitglieder der Legion tragen Geräte bei sich, mit denen sie die Teleporter aktivieren können. Ihr müsst Euch eines dieser Geräte besorgen, um Zugang zu dem Teleporter zu erlangen. Tötet alle Dämonen, wenn Ihr es müsst, aber kommt auf keinen Fall mit leeren Händen zurück.", progress = "Wir müssen einen Weg finden, um diese Höllenbestien zu vernichten, <Name>. Wir sind schon weit gekommen, aber ein Fehlschlag würde uns alles kosten.", completion = "Lasst mich schauen, ob ich herausfinden kann, wie das funktioniert...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10590] = {title = "Beweist Euren Hass!", objective = "Mehlar Dämmerklinge beim Bollwerk möchte, dass Ihr ihm 20 Geißelsteine des Dieners bringt.", description = "Es ist an der Zeit, dass Ihr Euch an Vergangenes erinnert, das nicht vergessen werden sollte... das Abschlachten unseres Volkes durch Arthas und seine Armeen der Geißel.\n\nRache an der Geißel ist der einzige Weg, Euren Schmerz zu lindern. Es ist bedauerlich, dass sie keine Angst und keinen Schmerz empfinden können. Nur ihre Vernichtung kann Euch einen Hauch von Genugtuung bringen.\n\nSprecht mit Argentumoffizier Garush, um mehr über die Geißelsteine zu erfahren und wie man sie bekommt. Ich werde viele davon als Beweis für Euren Einsatz brauchen, bevor ich erneut mit Euch spreche.", progress = "Hat die Geißel Eure Waffe bereits zu spüren bekommen?", completion = "Sehr gut, &lt;Name&gt;. Vielleicht genießt Ihr doch den süßen Geschmack der Rache.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10592] = {title = "Die Weisheit der Bansheekönigin", objective = "Bringt die Geißelsteinfragmente zu Fürstin Sylvanas Windläufer in Unterstadt.", description = "Die Geißelsteine sind schwach, wenn sie aus dem knochigen Griff, der sie einst umfasste, gerissen werden. Sie zerbröseln und zerbrechen schon, wenn ich sie einfach nur in der Hand halte.\n\n<Mehlar zerdrückt die Geißelsteine mit bloßer Hand.>\n\nBringt diese Fragmente zur Bansheekönigin Sylvanas Windläufer. Ihr Thron befindet sich in Unterstadt. Sie hütet das Geheimnis, wie man diese Überreste in eine Waffe gegen die Geißel verwandelt.", progress = "Habt Ihr etwas für mich, <Volk>?", completion = "Diese Steine tragen einen Hauch der Verderbnis an sich, an den ich mich nicht erinnern möchte und den ich doch nicht vergessen kann. Dass Ihr sie zu mir bringt stellt meine Geduld auf eine harte Probe.\n\nUnd doch ist offensichtlich, dass Euer Herz sich nach derselben Rache sehnt wie meines, und ich werde Euch helfen, sie zu bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10593] = {title = "Das uralte Böse", objective = "Lüftet die Geheimnisse des Versunkenen Tempels und befreit Atal'alarion. Tötet ihn und schneidet die Fäulnisranke aus seinem Fleisch. Kehrt danach zu Mehlar beim Bollwerk zurück.", description = "Wenn Ihr diese Steine in eine Waffe gegen die Geißel verwandeln wollt, müsst Ihr etwas ebenso Bösartiges besorgen, um sie zu verstärken.\n\nTief im Versunkenen Tempel in den Sümpfen des Elends schlummert eine uralte böse Präsenz. Befreit diese Kreatur und vernichtet sie. Bringt einen kleinen Teil ihres Körpers zu Mehlar Dämmerklinge. Meine Wachen werden ihm die Geißelsteinfragmente zukommen lassen.", progress = "Da Ihr noch am Leben seid, nehme ich an, dass Fürstin Sylvanas Euch Weisheit anstatt des Todes geschenkt hat.", completion = "Die Bansheekönigin hat Euch einen guten Rat gegeben. Genau das brauchen wir, um die Fragmente zusammen zu fügen.\n\n&lt;Mehlar beobachtet, wie die Ranke sich durch die Fragmente schlängelt und sie verbindet.&gt;\n\nSchaut! Ich nenne es Geißelbann. Doch gebt Acht, wenn Ihr es benutzt, denn es dient Euch gegen seinen Willen.", rewards = "Ihr bekommt:\n\nGeißelbann"}
MultiLanguageQuestData['de'][10594] = {title = "Die Klangfrequenz messen", objective = "Ordnet die oszillierenden Schwingungsmesser so an, dass Ihr, wenn Ihr in ihrer Mitte steht, von fünf sich überlappenden Schwingungsfeldern berührt werdet.", description = "Bringt diese Messgeräte zum Singenden Bergrücken. Wenn Ihr sie in einem Muster auf dem Boden auslegt, werden sich überlappende Felder erzeugt, die die Schwingungsweite der Kristalle messen. Es funktioniert aber nur, wenn Ihr in ihrer Mitte steht und von allen fünf Schwingungsfeldern berührt werdet.\n\nEure Messgeräte funktionieren auch mit den Messgeräten, die andere vor Euch dort abgelegt haben.\n\nOh, und es kann sein, dass dabei ein Riss entsteht. Ich habe jedoch keine Ahnung, was dadurch in unsere Welt gelangen könnte, aber macht Euch auf das Schlimmste gefasst.", progress = "Nun, habt Ihr die Messungen der singenden Kristalle, um die ich Euch gebeten habe?", completion = "Oh, das ist außergewöhnlich! Ich hatte ja keine Ahnung... Es ist fast so, als wären die Kristalle lebendig!\n\nIch frage mich, ob eine Art symbiotische Beziehung zwischen ihnen und den Netherdrachen besteht.\n\nVielen Dank, vielen Dank! Ihr müsst etwas aus meiner Kuriositätensammlung nehmen, das ich nichtmal im Tode anziehen würde!\n\nAn Euch könnte etwas davon jedoch gut aussehen.", rewards = "Metros SchlankmacherhoseSchartwinkels VersuchsharnischSchlecht gewählter PapphutEhemaliger ModegürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10595] = {title = "Belagert!", objective = "Blutwache Gulmok außerhalb von Schattenmond möchte, dass Ihr 10 angreifende Höllenbestien tötet.", description = "<Gulmok schaut zum Himmel auf.>\n\nUnsere Späher schlagen sich wacker, aber die Höllenbestien greifen immer wieder an.\n\nVon ihrer Basis in der Feste der Legion im Südwesten aus bombardieren sie uns gnadenlos. Sogar die Elitewachen der Kor'kron können sie nicht ewig aufhalten.\n\nIch rekrutiere jedes fähige Individuum, damit es seinen Teil zur Verteidigung Schattenmonds beiträgt. Das ist kein Spiel, <Klasse>. Das Überleben des Dorfes ist in Gefahr. Tut Eure Pflicht gegenüber der Horde und schließt Euch dem Kampf an!", progress = nil, completion = "Ich bin beeindruckt, dass Ihr dieses Gemetzel überlebt habt. Ihr seid vielleicht genau die Person, die wir für einen gefährlichen Auftrag brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10596] = {title = "Zur Feste der Legion", objective = "Begebt Euch zur Feste der Legion, findet ein Kommunikationsgerät der Legion und benutzt es, um mehr über die Pläne der Legion herauszufinden, während Ihr verkleidet seid. Kehrt danach zu Blutwache Gulmok in Schattenmond zurück.", description = "Die Feste der Legion ist Euer Ziel. Ihr werdet keine Verstärkung erhalten, daher ist ein Frontalangriff unmöglich.\n\nDie wenigen Informationen, die wir sammeln konnten, weisen darauf hin, dass die Legion die Höllenbestien in der Feste lagert und vorbereitet. Ich möchte, dass Ihr die Feste in der Verkleidung, die ich Euch geben werde, nach detaillierten Informationen über die Pläne der Legion durchsucht.\n\nWir können nur hoffen, dass Ihr die Gespräche zwischen ihren Kommandanten abfangen oder belauschen könnt.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Blutwache Gulmok hört sich Euren Bericht an und wird mit jedem Satz nervöser.&gt;\n\nWas meint Ihr mit sie wollen ihre Angriffe noch verstärken? Das können wir nicht zulassen. Kehrt dorthin zurück und kümmert Euch darum, solange in Schattenmond noch ein Stein auf dem anderen steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10597] = {title = "Die Bombe bauen", objective = "Besorgt Euch einen Teufelshäscherkraftkern und eine Teufelshäscherrüstungsplatte und bringt sie zu Blutwache Gulmok in Schattenmond.", description = "Wir können der Legion nicht erlauben, uns auf ihrem Marsch zum Schwarzen Tempel zu zertrampeln.\n\nFindet einen Weg, um die Höllenbestien, die sie gegen uns einsetzen wollen, zu vernichten. Das ist keine Bitte, <Name>, sondern ein Befehl.\n\nAm Fauligen Teich in der Nähe der Feste der Legion gibt es viele alte Teufelshäscherkraftkerne, die Ihr als Grundlage für eine Art Teufelsbombe verwenden könnt. Durchsucht die anderen Trümmer in der Nähe der Feste nach Rüstungsplatten. Daraus sollte man eine Bombe basteln können, die so stark ist, dass sie diese Höllenbestien vernichten und die Feste zum Beben bringen wird!", progress = "<Ihr reicht Gulmok die Materialien.>", completion = "&lt;Gulmok platziert den Kraftkern in dem Gehäuse und versiegelt es.&gt;\n\nDas sollte funktionieren. Ich möchte nicht in der Feste sein, wenn das Ding hochgeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10598] = {title = "Jagt die Höllenbestien in die Luft!", objective = "Zündet die Teufelsbombe, während Ihr auf der grünen Glyphe in der Feste der Legion steht. Meldet Euch bei Blutwache Gulmok in Schattenmond zurück, wenn Ihr Euren Auftrag erledigt habt.", description = "Das Gerät, das wir zusammengebaut haben, würde keinen Schönheitspreis gewinnen, aber es sollte die Höllenbestien in der Feste der Legion zerstören können. Danach zu urteilen, was der Kraftkern des Teufelshäschers bei dem Fauligen Teich angerichtet hat, muss darin eine gehörige Explosionskraft stecken.\n\nWenn Ihr das Gerät in der Mitte der grünen Glyphe in der Feste platzieret, solltet Ihr alle Höllenbestien erwischen können.", progress = "Habt Ihr einen Weg gefunden, um den Vorrat an Höllenbestien der Legion zu zerstören?", completion = "&lt;Gulmok nickt grimmig.&gt;\n\nWir haben keine Zeit zu feiern, &lt;Name&gt;. Noch sind wir nicht aus der Schusslinie. Ich habe neue Befehle für Euch.", rewards = "SterndeuterkiltKopfputz des MondwappensPurpurrote PanzerhalsbergeBlutgeschmiedeter WächterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10599] = {title = "Die Todesschmiede", objective = "Meldet Euch bei Späher Zagran in der Schlackenwacht.", description = "Während Ihr Euch um die Höllenbestien bei der Feste der Legion gekümmert habt, bin ich Euren Bericht durchgegangen. Wir haben keinen Grund zu glauben, dass die Legion bezüglich der Geschehnisse in der Todesschmiede gelogen hat. Sie stellen dort wirklich Höllenbestien am Fließband her. Daher habe ich eine Gruppe von Spähern dorthin geschickt, um die Schmiede zu beobachten.\n\nWenn wir dem Treiben der Todesschmiede kein Ende setzen, werden sie die Schar an Höllenbestien, die Ihr in der Feste der Legion vernichtet habt, im Handumdrehen wieder aufgestockt haben.\n\nMeldet Euch bei Späher Zagran in der Schlackenwacht im Südosten, die die Todesschmiede überblickt.", progress = nil, completion = "&lt;Der Orc nickt.&gt;\n\nVerstärkung ist gut. Wir haben zwar schon grundlegende Informationen darüber gesammelt, was der Schattenrat dort drin vor hat, doch es ist Zeit zuzuschlagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10600] = {title = "Diener des Schattenrats", objective = "Späher Zagran in der Schlackenwacht möchte, dass Ihr 10 Wächter der Todesschmiede und 5 Beschwörer der Todesschmiede tötet.", description = "<Zagran hört Eure Erzählung der Ereignisse in der Feste der Legion an und nickt.>\n\nJetzt geben unsere Beobachtungen einen Sinn. Wir haben gesehen, wie sie Höllenbestien zur Feste der Legion geschafft haben, aber mehr konnten wir nicht herausfinden.\n\nDer Schattenrat hat die Todesschmiede ziemlich gut abgeriegelt. Sieht aus, als müsstet Ihr Euch den Weg hinein mit Gewalt freiräumen. Fangt damit an, die Mitglieder des Schattenrats, die den Eingang zur Todesschmiede bewachen, zu vernichten!", progress = nil, completion = "Ich wäre ja selbst dorthin gegangen und hätte ein paar Schädel zertrümmert, aber ich habe strengste Anweisungen, mich nicht auf einen direkten Kampf mit dem Feind einzulassen.\n\n&lt;Der Späher grummelt und imitiert Blutwache Gulmoks Stimme.&gt;\n\nLasst uns die Produktion in der Schmiede zum Stillstand bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10601] = {title = "Kagroshs Schicksal", objective = "Späher Zagran in der Schlackenwacht möchte, dass Ihr die Todesschmiede nach Kagrosh absucht und Kagroshs Beutel zurückholt.", description = "Ursprünglich waren wir hier zu dritt. Unglücklicherweise musste Kagrosh unbedingt den Helden spielen.\n\nEr ist in die Todesschmiede gegangen. Seitdem haben wir nichts mehr von ihm gehört.\n\nAller Wahrscheinlichkeit nach ist der Dummkopf in seinen sicheren Tod gezogen. Die Mitglieder des Schattenrats sind nicht dumm und Kagrosh ist nicht gerade ein Ausbund an Subtilität, wenn Ihr versteht, was ich meine. Haltet in der Todesschmiede Ausschau nach ihm und beschafft sämtliche Informationen oder Gegenstände, die er gesammelt haben könnte.", progress = "Habt Ihr ein Zeichen von Kagrosh in der Todesschmiede finden können?", completion = "&lt;Zagran schüttelt den Kopf und nimmt Euch den Beutel ab.&gt;\n\nIch habe Euch doch gesagt, dass er ein Dummkopf ist. Ich hoffe, dass in diesem Beutel irgendetwas ist, die Zeit, die Ihr mit der Suche nach ihm verbracht habt, rechtfertigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10602] = {title = "Die Beschwörungskammer", objective = "Besorgt Euch eine Elementarsteuerung von einem Schmied der Todesschmiede oder einem Tüftler der Todesschmiede. Benutzt sie, um das Ritual in der Beschwörungskammer zu unterbrechen. Meldet Euch danach bei Späher Zagran in der Schlackenwacht zurück.", description = "Um mit der Konstruktion der Höllenbestien so schnell nachzukommen, muss der Schattenrat einen Bereich bestimmt haben, an dem die verderbten Elemente, die den Höllenbestien als Seele dienen, beschworen werden.\n\nDie Beschwörungskammer liegt wahrscheinlich unter der Erde in der Nähe eines Teichs mit fauligem Wasser oder Lava. Sucht die Beschwörungskammer in der Todesschmiede und unterbrecht ihr Beschwörungsritual! Vielleicht tragen die Mo'arg, die bei der Produktion der Höllenbestien teilhaben, ja ein Instrument dabei, mit dem Ihr die Magie der Beschwörer unterbrechen könnt.", progress = "Wir können nicht zulassen, dass sie weiter produzieren. Habt Ihr dem Beschwörungsritual ein Ende gesetzt?", completion = "Gut. Wir machen Fortschritte. Das bringt uns einen Schritt näher an die Abschaltung diese Monstrosität. Bald können wir sicher nach Schattenmond zurückreisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10603] = {title = "Nieder mit dem Kriegshetzer!", objective = "Besiegt Kriegshetzer Razuun, beschafft Razuuns Befehle und meldet Euch bei Blutwache Gulmok in Schattenmond.", description = "Wir haben große Fortschritte gegen den Schattenrat bei der Todesschmiede erzielt, doch nun ist es an der Zeit, die Sache zu Ende zu bringen.\n\nIch habe unter den Gegenständen in Kagroshs Beutel einen Schlüssel gefunden. Wenigstens hat er das noch hinbekommen, bevor sie ihn erwischt haben.\n\nDer Schlüssel sollte Euch dabei helfen, Kriegshetzer Razuun, den Ihr in der Feste der Legion beobachtet habt, ausfindig zu machen.\n\nNachdem Ihr Kriegshetzer Razuun aufgespürt und erschlagen habt, meldet Euch gleich bei Blutwache Gulmok. Wir dürfen ihn nicht warten lassen.", progress = "Bringt Ihr Neuigkeiten aus der Todesschmiede?", completion = "&lt;Ihr erstattet der Blutwache Bericht und übergebt die gefundenen Befehle.&gt;\n\nGute Arbeit, &lt;Name&gt;, aber denkt nicht, dass Ihr dafür einen Orden verliehen bekommt. Die Nachtelfen mögen vielleicht ihre hübschen kleinen Uniformen dekorieren. Echte Krieger teilen jedoch ihre Geschichten von der Schlacht bei einem kühlen Krug Bier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10604] = {title = "Zugang erlangen", objective = "Bringt eine Teleportersteuerung der Legion zu Blutwache Gulmok in Schattenmond. Bekanntlich tragen die Waffenschmiede der Mo'arg in der Feste der Legion diese Geräte bei sich.", description = "Laut Razuuns Befehlen wird der riesige Stützpunkt der Höllenbestien Invasionspunkt: Katastrophe genannt und befindet sich in den nördlichen Bergen. Die einzige Weise, auf die man dorthin gelangen kann, ist ein Teleporter, der sich in der Feste der Legion befindet.\n\nAusgewählte Mitglieder der Legion tragen Geräte bei sich, mit denen sie die Teleporter aktivieren können. Ihr müsst Euch eines dieser Geräte besorgen, um Zugang zu dem Teleporter zu erlangen. Tötet alle Dämonen, wenn Ihr es müsst, aber kommt auf keinen Fall mit leeren Händen zurück. Verschwendet keine Zeit; der Feind ist schon gefährlich nahe.", progress = "Die Anwesenheit der Legion in unserer Mitte ist nicht akzeptabel! Wir müssen einen Weg finden, damit fertig zu werden, bevor sie ihre Angriffe erneuern können.", completion = "Endlich haben wir ein Mittel, mit dem wir die Legion aus Schattenmond vertreiben können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10605] = {title = "Carendin ruft", objective = "Sprecht mit Carendin Halgar in Unterstadt.", description = "Ihr habt einen hungrigen Ausdruck in den Augen, <Name>. Vielleicht ist es an der Zeit, dass Ihr Eure Ausbildung fortsetzt.\n\nReist nach Unterstadt und sprecht mit Carendin Halgar. Der alte Knochenhaufen hat ein oder zwei Tricks auf Lager, die Euch interessieren dürften.", progress = nil, completion = "Ah, noch ein hungriger Initiand. Wunderbar!\n\nIhr wärt kein richtiger Hexenmeister, wenn es Euch nicht nach Rache dürstete, oder, Mädel? Dann mal los.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10606] = {title = "Die Kunst der Teufelshäscherwartung", objective = "Tötet Doktor Gutrick und beschafft Euch den Schlüssel des Doktors. Benutzt den Schlüssel, um die Geldkassette des Doktors zu öffnen und 'Die Kunst der Teufelshäscherwartung' daraus zu entnehmen. Bringt das Buch zu Plexi beim Invasionspunkt: Katastrophe.", description = "Der beste Weg, um die Vorräte der Legion zu zerstören, ist, ihre eigenen Waffen gegen sie zu verwenden. Ich habe eine Anlage gebaut, mit deren Hilfe Ihr eine dieser Schildwachen der Teufelshäscher dort unten steuern könnt.\n\nEs gibt jedoch noch einige Dinge, die ich zuerst herausfinden muss. Dafür benötige ich das Handbuch, das Doktor Gutrick in einer Truhe am Ende der Rampe verschlossen hält. Wahrscheinlich rückt er den Schlüssel dazu nicht ohne Kampf heraus. Bringt mir das Teufelshäscherhandbuch und ich erledige den Rest!", progress = "Habt Ihr das Handbuch?", completion = "Ah, genau was wir brauchen. Die Legion ist zwar nicht für Ihre Meisterwerke der Weltliteratur bekannt, aber es sollte seinen Zweck erfüllen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10607] = {title = "Das Flüstern des Rabengottes", objective = "Tötet die Arakkoa der Grishna, um für 2 Minuten den Zauber 'Rabensprache verstehen' zu erhalten. Hört Euch die Prophezeiungen aller vier Schreine an, solange der Zauber aktiv ist.", description = "In Grishnath können die Arakkoa mithilfe der Totems, die die Orakel des Raben aufgestellt haben, die Worte des Raben hören. Leider sind wir der Sprache der Arakkoa nicht mächtig.\n\nMit dem Anhänger des Herolds können wir sie verstehen. Ihr könnt die Seele der Arakkoa aufnehmen und so ihrer Sprache mächtig werden. Begebt Euch zu den Totems, während ihr mit dem Geist der Arakkoa erfüllt seid, und hört Euch ihre Nachricht an.\n\nFindet es für uns heraus, <Name>.", progress = nil, completion = "Das ist wirklich beunruhigend. Die Arakkoa waren lange ein friedliebendes Volk. Dieser Rabenkult ist nichts als eine Versammlung von Außenseitern und Verrückten.\n\nAber wir können nicht leugnen, dass ihre Macht wächst. Vielleicht steckt hinter diesem Raben mehr, als wir vermuten.", rewards = "GespensterstoffbindungenBehagliche LederstiefelSchiftung der SintflutWeißknöchelstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10608] = {title = "Kristallklar", objective = "Tötet 10 Kristallfelsklauen.", description = "Diese verdammten Felsklauen halten mich von meinen Forschungen unten im Singenden Bergrücken ab! Sie graben bei den Kristallen und ruinieren so all meine Hoffnungen, die Harmonien der singenden Kristalle zu untersuchen.\n\nIhr seht aus, als könntet Ihr mir dabei helfen. Begebt Euch nach Süden und rottet diese Kristallfelsklauen aus!", progress = "Habt Ihr die Kristallfelsklauen im singenden Bergrücken schon vernichtet? Sonst kann ich mit meinen Untersuchungen nicht beginnen.", completion = "Ein Glück, dass ich sie los bin! Verdammte Biester!\n\nWenn Ihr sicher seid, dass Ihr diese Nervensägen ausgelöscht habt, habe ich ein kleines Forschungsprojekt für Euch. Ihr werdet es sicher mögen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10609] = {title = "Was war zuerst da, der Drache oder das Ei?", objective = "Beschafft Euch 3 Essenzen eines Protonetherdrachen, 3 Essenzen eines heranwachsenden Netherdrachen und 3 Essenzen eines ausgewachsenen Netherdrachen.", description = "Ich habe einige Experimente zur Verwendungsweise der Drachenessenzen im Rahmen meiner Arbeit als Arzt durchgeführt. Ich bin mir sicher, dass diese Essenz ein Allheilmittel für Unmengen von Krankheiten sein kann!\n\nJetzt brauche ich nur noch jemanden, der für mich nach Süden zum Singenden Bergrücken geht und mir ein wenig davon besorgt.\n\nHabt Ihr Lust, meinen temporalen Phasenstrahler zu benutzen, um den Netherwelpen, die aus den Netherdracheneiern schlüpfen, ihre Essenz zu entziehen?\n\nIch muss Euch jedoch warnen: es handelt sich hierbei um ziemlich heikle und zeitverändernde Technologie. Ich habe keine Ahnung, in was sich die Netherwelpen verwandeln könnten.", progress = "Habt Ihr sie? Habt Ihr die Drachenessenzen, die ich so dringend brauche, um meine Experimente weiter zu führen?\n\nWusstet Ihr, dass diese Nethergroßdracheneier einmal Schwarzdracheneier waren? Es ist wahr! Aber als Draenor in tausend Stücke gesprengt wurde, wurden die Eier von dem herumwirbelnden Nether mutiert.", completion = "Ihr habt ja keine Ahnung, wie wichtig diese Experimente sein werden. Vielen Dank!\n\nEs wird aufregend werden, sich mit diesen Essenzen zu befassen. Ich bin besonders gespannt, ob der Nether, der die schwarzen Dracheneier zu Netherdracheneiern verwandelt hat vielleicht ein besonderer Segen für meine Studien ist.\n\nDa fällt mir gerade ein, dass Ihr die erste Person sein solltet, die die Vorzüge meines kleinen Gebräus genießen sollte. Hier, nehmt diese Proben und benutzt sie, wenn Ihr sie braucht.", rewards = "Fizits Mantelung der DrachenjagdPräzise Handschuhe des EifersVererbter DrachengurtKuckucks TreterIhr bekommt:\n\nHeilessenz eines Netherdrachen"}
MultiLanguageQuestData['de'][10611] = {title = "Die Kunst der Teufelshäscherwartung", objective = "Tötet Doktor Maleficus und beschafft Euch den Schlüssel des Doktors. Benutzt den Schlüssel, um die Geldkassette des Doktors zu öffnen und 'Die Kunst der Teufelshäscherwartung' daraus zu entnehmen. Bringt das Buch zu Nakansi beim Invasionspunkt: Katastrophe.", description = "Der beste Weg, um die Vorräte der Legion zu zerstören, ist, ihre eigenen Waffen gegen sie zu verwenden. Ich habe eine Anlage gebaut, mit deren Hilfe Ihr eine dieser Schildwachen der Teufelshäscher dort unten steuern könnt.\n\nEs gibt jedoch noch einige Dinge, die ich zuerst herausfinden muss. Dafür benötige ich das Handbuch, das Doktor Maleficus in einer Truhe am Ende der Rampe verschlossen hält. Wahrscheinlich rückt er den Schlüssel dazu nicht ohne Kampf heraus. Bringt mir das Teufelshäscherhandbuch und ich erledige den Rest!", progress = "Habt Ihr das Handbuch?", completion = "Das enthält alle nötigen Informationen. Nur noch ein paar Handgriffe, und Ihr habt in null Komma nichts die Kontrolle über einen Teufelshäscher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10612] = {title = "Teufelshäscherdrift", objective = "Benutzt die Teufelshäscherfernsteuerung, um eine Schildwache der Teufelshäscher zu steuern. Zerstört 60 todesgeschmiedete Höllenbestien bevor Euer Teufelshäscher versagt. Meldet Euch danach bei Plexi am Invasionspunkt: Katastrophe.", description = "<Plexi blättert das Handbuch durch.>\n\nNun, hier steht alles drin, was wir brauchen, aber es gibt ein Problem. Teufelshäscher sind nicht wirklich dafür konstruiert, ferngesteuert zu werden.\n\nWir können einen davon so umbauen, dass es für kurze Zeit funktioniert, aber wir müssen schnell arbeiten. Sonst kann keiner die Folgen absehen. Es würde mich auch nicht wundern, wenn Euer kleines Kunststück mit dem Teufelshäscher die Aufmerksamkeit der Lakaien der Legion auf sich ziehen würde. Passt gut auf Euch auf. Und was immer Ihr tut, vergesst nicht, so viele wie möglich zu zerstören!", progress = "Ihr seid zurück. Ich gehe also davon aus, dass Ihr Euren Auftrag erledigt habt. Was habt Ihr zu berichten?", completion = "Erstaunlich! Ihr habt geschafft, was keiner der Greifenreiter der Wildhammerfeste bewerkstelligen konnte! Ihr habt den Vormarsch der Brennenden Legion aufgehalten und uns vor der Vernichtung durch diese schrecklichen Höllenbestien gerettet. Ihr habt unseren tiefsten Dank für Eure Dienste, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10613] = {title = "Teufelshäscherdrift", objective = "Benutzt die Teufelshäscherfernsteuerung, um eine Schildwache der Teufelshäscher zu steuern. Zerstört 60 todesgeschmiedete Höllenbestien bevor Euer Teufelshäscher versagt. Meldet Euch danach bei Nakansi am Invasionspunkt: Katastrophe.", description = "<Nakansi blättert das Handbuch durch.>\n\nHier sind alle Informationen gesammelt, aber seid gewarnt. Diese Dinger wurden nicht gebaut, um ferngesteuert zu werden.\n\nWir können einen davon so umbauen, dass es für kurze Zeit funktioniert, aber wir müssen schnell arbeiten. Sonst kann keiner die Folgen absehen. Es würde mich auch nicht wundern, wenn Euer kleines Kunststück mit dem Teufelshäscher die Aufmerksamkeit des Legionsabschaums auf sich ziehen würde. Passt auf Euch auf, aber denkt daran, dass die Mission und die Sicherheit Schattenmonds vorgehen!", progress = "Ihr seid zurück. Ich gehe also davon aus, dass Ihr Euren Auftrag erledigt habt. Was habt Ihr zu berichten?", completion = "Ich gebe zu, &lt;Name&gt;, ich bin von Euren Errungenschaften beeindruckt. Jetzt, da die Legion nicht länger die Mittel hat, uns in Schattenmond anzugreifen, können wir uns anderen Fronten zuwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10614] = {title = "Das Flüstern im Wind", objective = "Sprecht mit Leoroxx im Dorf der Mok'Nathal im Schergrat.", description = "Ich habe in der gesamten Scherbenwelt Gerüchten über die Mok'Nathal nachgejagt und nichts als weitere Gerüchte und Geschichten gefunden. Aber nun haben wir vielleicht tatsächlich ihr Zuhause ausfindig gemacht.\n\nNun, da dieser Moment endlich da ist, fühle ich mich sehr unwohl. Dieses Unwohlsein hat mich während meiner Suche Nacht für Nacht wach gehalten. Werden sie mich annehmen?\n\nIch... kenne den Namen ihres Anführers: Leoroxx. Sucht nach ihm. Seid meine Augen.", progress = nil, completion = "Was führt Euch in unser Dorf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10615] = {title = "Der Ruuanwald", objective = "Sprecht mit Timeon im Ewigen Hain im Ruuanwald des Schergrats.", description = "Die Informationen, die ich mit Eurer Hilfe über das Wesen der Arakkoa sammeln konnte, sind auch noch für jemand anders von Interesse.\n\nWir wurden von ein paar Mitgliedern der Expedition des Cenarius aufgesucht, die sich ebenfalls Sorgen um die Pläne der Arakkoa hier im Schergrat machen.\n\nIhr solltet Timeon aufsuchen. Er befindet sich im Ewigen Hain im Ruuanwald. Folgt einfach von hier aus der Straße nach Westen und geht dann an der Weggabelung im Messergrat nach Norden. Wendet Euch nach Westen, wo die Wege in der Messerschlucht sich teilen.", progress = nil, completion = "Ah, ja, Dertrok. Wir haben kurz über die Arakkoa gesprochen. Ich muss allerdings zugeben, dass unsere... Interessen was sie betrifft deutlich auseinander gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10617] = {title = "Seidenflügelkokons", objective = "Besorgt 8 Seidenflügelkokons von Seidenflügellarven.\n\nTötet die Larven schnell, da sie sich sonst in Seidenflügel verwandeln und ihre Kokons zerstören.", description = "Die Seide der Kokons der Seidenflügel wird hier im Dorf für alle möglichen Zwecke eingesetzt. Wir können nie zu viele davon besorgen und haben.\n\nSobald sie beginnen sich zu verwandeln ist es schwer, die Kokons der Larven zu ernten.\n\nUnsere Krieger sind mit den Angriffen auf unser Dorf beschäftigt. Wenn Ihr sie für uns sammeln könntet, wäre das uns eine große Hilfe.", progress = "Für die Ernte braucht man eine schnelle und ruhige Hand. Ich hoffe, Ihr habt Erfolg.", completion = "Diese Kokons sind von guter Qualität. Wie ich sehe, habt Ihr die Ernte im Griff.\n\nWir haben versucht, unsere eigenen Seidenflügellarven zu züchten, aber leider produzieren die kleineren nicht genug Seide, um unseren Bedarf zu decken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10618] = {title = "Die weichsten Flügel", objective = "Beschafft Euch 12 schillernde Flügel.", description = "Seidenflügellarven zu jagen ist eine schwierige Aufgabe für unsere jungen Jäger. Aber auch wenn sie es nicht schaffen, die Kokons der Larven zu ernten, können wir noch die Flügel der geschlüpften Seidenflügel nutzen.\n\nIn der Tat sind die Flügel vielseitiger einsetzbar als die Kokons. Wir können nie zu viele davon haben.\n\nWenn Ihr da draußen seid, wäre es mir eine große Hilfe, wenn Ihr mir noch ein paar davon bringen würdet.", progress = "Die Flügel sind sehr zerbrechlich, können aber in vielen unserer Kunstgegenstände als Dekoration dienen.", completion = "Vielen Dank, &lt;Name&gt;. Wir werden sie schon früher benutzen, als ihr Euch vorstellen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10619] = {title = "Die Aschenzungen", objective = "Verteidiger Aluumen möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Der Aschenzungenstamm wird von allen Zerschlagenen gefürchtet. Er besteht aus den bösartigsten und blutrünstigsten Gestalten, die von Akama persönlich ausgewählt wurden. Sie sind so wild und rücksichtslos wie jeder Naga, Dämon oder Blutelf in Illidans Armee. Eine große Anzahl von ihnen wurde in den Ruinen von Baa'ri südwestlich von hier stationiert. Begebt Euch dorthin und dezimiert ihre Zahl, bevor sie die Gelegenheit haben, uns anzugreifen.", progress = nil, completion = "Ehre den Naaru, &lt;Name&gt;. Ihr habt den Willen des Lichts ausgeführt und Illidans Anhänger vernichtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10620] = {title = "Gratwirbelbedrohung", objective = "Tötet 10 Gratwirbelpirscher.", description = "Wir wurden angeheuert, um Toshley zu helfen, als er in die Scherbenwelt gezogen ist. Und seitdem sind wir hier auf Achse.\n\nEs sieht jedoch so aus, als hätten wir endlich ein paar Wurzeln geschlagen. All die verrückten Wissenschaftler und Ingenieure hier haben ihre Projekte am Laufen und wir Raunacken sind hier, um sie dabei zu beschützen.\n\nZurzeit könnten wir wirklich jemanden brauchen, der nach Norden in den Messergrat oder nach Osten zur Schuppenflügelbank geht und ihn von den Pirschern befreit. Das sind heimtückische Spinnen, die bei den Felsvorsprüngen leben und nichts ahnende Passanten anspringen.", progress = nil, completion = "Ziemlich gut für einen Grünschnabel. Es scheint, als gäbe es eine kleine Gruppe von Eierköpfen, die unbedingt die Astralen und ihre Technologie im Norden 'beobachten' möchten. Sie werden sich riesig freuen, dass Ihr ihnen den Weg freigeräumt habt.\n\nHier, nehmt ein paar hiervon. Wir haben nicht viele, aber vielleicht können sie Euch in der Zukunft nützlich sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDestillierte PirschersichtVerstohlenheit des Pirschers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10621] = {title = "Splitter des Illidaribanns", objective = "Bringt den Splitter des Illidaribanns zu Ordinn Donnerfaust in der Wildhammerfeste.", description = "Der Splitter scheint von einer größeren Waffe zu stammen. Ein bedrohliches Leuchten geht von den kantigen Runen, die in das Metall geätzt wurden, aus.\n\nEuch ist nicht klar, welche Aufgabe die Waffe hatte, aber sie ist nur schwer zu verkennen. Die meisten Mo'arg in der Feste der Legion scheinen Bruchstücke des Metalls, das Ihr in den Händen haltet, zu bearbeiten. Vielleicht kann einer der Waffenschmiede in der Wildhammerfeste Euch mehr darüber erzählen.", progress = "Was habt Ihr da?", completion = "&lt;Ordinn nimmt Euch den Splitter der Waffe ab.&gt;\n\nSo etwas habe schon seit langer Zeit nicht mehr gesehen. Die Waffe wurde aus einem sehr seltenen Erz geschmiedet, aber es handelt sich dabei nicht um eine gewöhnliche Klinge, &lt;Name&gt;. Sie ist mit einer Magie erfüllt, die Dämonen töten soll. Wenn Ihr sie von der Legion habt, muss sie eine Art 'Geheimwaffe' sein, die sie gegen Illidan einsetzen wollen. Welch erstaunlicher Fund!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10622] = {title = "Ein Beweis der Treue", objective = "Tötet Zandras im Kerker des Wächters im Schattenmondtal und kehrt danach zu Sanoru zurück.", description = "Akama hat Eure Fortschritte sehr genau verfolgt, <Name>.\n\nDie Aschenzungen, die Ihr in den Ruinen von Baa'ri erschlagen habt, zählen zu den bösartigsten Zerschlagenen unter uns. Akama selbst hat sie ausgewählt, um die Fassade gegenüber unseren Meistern der Illidari aufrechtzuerhalten. Doch die Todeshörigen wissen über Akamas eigentliche Pläne Bescheid.\n\nDoch eins nach dem anderen. Wir müssen wissen, dass Ihr nicht mit Illidan unter einer Decke steckt. Ein Satyr namens Zandras überwacht uns in Illidans Auftrag von den Zinnen der Gefängnismauer aus. Tötet ihn als Beweis Eurer Treue.", progress = "Habt ihr getan, worum ich Euch gebeten habe, <Name>? Vertrauen ist in dieser Gegend Mangelware.", completion = "Sehr gut, &lt;Name&gt;. Eure Gesinnung steht nun außer Frage. Ihr dürft jetzt zu Akama.", rewards = nil}
MultiLanguageQuestData['de'][10623] = {title = "Splitter des Illidaribanns", objective = "Bringt den Splitter des Illidaribanns zu Grokom Totauge in Schattenmond.", description = "Der Splitter scheint von einer größeren Waffe zu stammen. Ein bedrohliches Leuchten geht von den kantigen Runen, die in das Metall geätzt wurden, aus.\n\nEuch ist nicht klar, welche Aufgabe die Waffe hatte, aber sie ist nur schwer zu verkennen. Die meisten Mo'arg in der Feste der Legion scheinen Bruchstücke des Metalls, das Ihr in den Händen haltet, zu bearbeiten. Vielleicht kann einer der Waffenschmiede in Schattenmond Euch mehr darüber erzählen.", progress = "Was habt Ihr da?", completion = "&lt;Grokom nimmt Euch den Splitter der Waffe ab.&gt;\n\nSo etwas habe schon seit langer Zeit nicht mehr gesehen. Die Waffe wurde aus einem sehr seltenen Erz geschmiedet, aber es handelt sich dabei nicht um eine gewöhnliche Klinge, &lt;Name&gt;.\n\nDiese Runen erfüllen die Klinge mit der Macht, Dämonen zu vernichten. Wenn die Legion ihre eigenen Truppen mit Dämonen zerstörenden Waffen ausrüstet, muss ihr Hass auf Illidan unendlich groß sein. Das könnten wir zu unserem Vorteil ausnutzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10624] = {title = "Eine Spukgeschichte", objective = "Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr ihr 15 Einheiten ewig brennende Asche bringt.", description = "Habt Ihr diesen eiskalten Hauch gespürt? Als ob Euch jemand die Hand auf die Schulter legte? Euer Verstand spielt Euch keine Streiche, <Volk>. Das Land wird heimgesucht. Geister streifen durch die Weiten und sind bis in alle Ewigkeit hier gefangen.\n\nWollt Ihr sie gerne sehen? Seid Ihr Euch sicher? Solche Dinge können ein Wesen verändern - und zwar nicht zum Besseren.\n\nNun gut, dann müsst Ihr mir etwas von der ewig brennenden Asche bringen, die Ihr in der Nähe der Teufelslavabecken im westlichen Schattenmondtal finden könnt. Überall in der Nähe der grünen Lava...", progress = "Was meint Ihr? Ich werde natürlich etwas aus der Asche herstellen.", completion = "Eure Welt wird sich bald ändern, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10625] = {title = "Geisterbrille", objective = "Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr 12 Zeloten des Schattenmondklans tötet.", description = "Ich nenne sie 'Geisterbrille'. Ganz schön gewitzt, was? Wenn Ihr diese Brille aufzieht, könnt Ihr die Geister des Schattenmondtals sehen. \n\nBevor ich sie Euch gebe, müsst Ihr mir jedoch versprechen, uns dabei zu helfen, die Geister im Dorf zu dezimieren.\n\nNehmt die Brille und vernichtet alle Geister, die Ihr in Schattenmond herumspuken seht. Hoffentlich bewegt das die übrigen Geister, woanders hin zu gehen.", progress = "Wenn Ihr Eure Brille verliert, kann ich Euch eine neue herstellen.", completion = "Blutschatten? T... Teron Blutschatten? Aber... Wie?\n\nWie kann Blutschatten denn hier sein? Das ist nicht möglich!\n\nDie Legende von Teron Blutschatten lässt sogar die Verlassenen vor Angst erzittern. Nach dem, was man hört, war Blutschatten ein Hexenmeister Gul'dans und sehr mächtig. Als Blutschatten von Orgrim Schicksalshammer erschlagen wurde, nahm Gul'dan die Seele des gefallenen Hexenmeisters und pflanzte sie in die zerschlagene Hülle eines gefallenen Ritters von Sturmwind. Und so wurde der erste Todesritter der Horde geboren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10626] = {title = "Beschafft die Waffen", objective = "Ordinn Donnerfaust in der Wildhammerfeste möchte, dass Ihr ihm Makazradons Gleve und Morgrorons Gleve bringt.", description = "Wenn ich mehr von diesem Material hätte, könnte ich eine Waffe schmieden, die für Euch geeignet ist.\n\nDie beiden Grubenlords in der Feste der Legion, Makazradon und Morgroron, besitzen bereits diese antidämonischen Waffen. Wir wissen nicht, wie viele davon die Legion herstellen möchte, aber wenn wir diese beiden Prototypen in die Finger bekommen, haben wir sicher genug Material für unser eigenes Projekt.\n\n<Ordinn grinst.>\n\nEs liegt ein wenig Befriedigung darin, die eigenen 'Geheimwaffen' der Legion gegen sie zu verwenden, findet Ihr nicht?", progress = "Habt Ihr die Prototypen?", completion = "Sie sind perfekt. Jetzt wollen wir sie ein eine etwas praktischere Form bringen.", rewards = "Fußlappen des AschenläufersSchultern des AzurschlagsSattelgurt des finsteren JägersAngesengte UnterarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10627] = {title = "Beschafft die Waffen", objective = "Grokom Totauge im Schattenmondtal möchte, dass Ihr ihm Makazradons Gleve und Morgrorons Gleve bringt.", description = "Wenn ich mehr von diesem Material hätte, könnte ich eine Waffe schmieden, die für Euch geeignet ist.\n\nDie beiden Grubenlords in der Feste der Legion, Makazradon und Morgroron, besitzen bereits diese antidämonischen Waffen. Wenn wir an diese beiden Waffen kommen könnten, hätten wir genug Material, um Eure und noch einige weitere herstellen zu können.\n\nIch kann es kaum abwarten, mit diesen Waffen in die Schlacht gegen den Feind zu ziehen. Das wird die Dämonen lehren, mit antidämonischer Magie herum zu spielen.", progress = "Habt Ihr die Prototypen?", completion = "Sie sind perfekt. Jetzt wollen wir sie ein eine etwas praktischere Form bringen.", rewards = "Fußlappen des AschenläufersSchultern des AzurschlagsSattelgurt des finsteren JägersAngesengte UnterarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10628] = {title = "Akama", objective = "Sprecht mit Akama in der verborgenen Kammer im Kerker des Wächters.", description = "Ihr habt bewiesen, auf welcher Seite Ihr steht. Ich werde Euch das Versteck unseres Anführers verraten.\n\nFolgt den Gewölben hinter uns. Zu Eurer Rechten werdet Ihr einen unterirdischen Durchgang finden, der von stehendem Wasser verdeckt ist.\n\nIch muss Euch warnen, <Name>. Ihr dürft niemandem von dem, was Ihr sehen werdet, erzählen.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Wir haben viel zu besprechen.\n\nIch hoffe, Euer Wesen ist aufgeschlossen. Nicht viele Leute verstehen meine Entscheidungen. Nur meine engsten Mitarbeiter wissen von den bösen Omen, die ich sehe, und den Zeichen, auf die ich warte.\n\nAls ich mich mit Illidan zusammenschloss, geschah dies, weil ich vorausgesehen hatte, dass mein Volk sonst vernichtet würde. Ich habe geduldig auf die anderen Zeichen und Visionen gewartet... Velens Auszug... die Öffnung des dunklen Portals... und nun... Eure Ankunft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10629] = {title = "Drecksarbeit", objective = "Benutzt die Teufelshundepfeife, um einen teuflischen Wachhund zu rufen. Führt den teuflischen Wachhund Gassi und tötet ein paar Hölleneber. Durchsucht dann die Haufen des teuflischen Wachhunds nach den Schlüsseln. Wenn Ihr die Schlüssel gefunden habt, bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar.", description = "Endlich habe ich meinen Schredder zum Laufen bekommen. Aber wie es scheint, habe ich die Schlüssel verloren. Ich halte ein Rudel Teufelshunde, die mein Lager bewachen. Sie machen ihre Sache nicht sehr gut und beißen mich gerne. Sie mögen auch gerne glänzende Dinge. Sie mögen sogar sehr gerne glänzende Dinge. Daher fürchte ich, dass einer der Teufelshunde meine Schredderschlüssel gefressen hat. Ich bezahle Euch, wenn Ihr mit meinem Teufelshund Gassi geht. Tötet ein paar Hölleneber und lasst ihn davon fressen. Wenn er fertig ist, wird er sein Geschäft machen. Durchsucht danach die Haufen nach den Schlüsseln.", progress = "Konntet Ihr meine Schlüssel finden? Ich bin mir sicher, dass einer der Hunde ihn gefressen hat. Wahrscheinlich ist es der, den ich Euch mitgegeben habe. Wahrscheinlich.", completion = "Ihr riecht ja fürchterlich! Aber Ihr habt meine Schlüssel gefunden. Vielen herzlichen Dank! Jetzt kann ich meinen Schredder in Betrieb nehmen und ein wenig Gold verdienen. Bald werde ich das Geld zusammen haben, um die Scherbenwelt zu verlassen. Ich weiß nicht, warum Ihr hier bleiben wollt. Ich hasse diesen Ort. Wärt Ihr nicht viel lieber wieder in Beutebucht?\n\nVielleicht um ein wenig zu Angeln?", rewards = "Ihr bekommt:\n\nEZ-Thro-Dynamit II"}
MultiLanguageQuestData['de'][10630] = {title = "Unter Thrallmar", objective = "Tötet Urga'zz und kehrt dann zu Großknecht Razelcraz in der Mine nordwestlich von Thrallmar zurück.", description = "Ich bin fast wieder im Geschäft. Das Problem ist nur, dass diese Gan'arg sich in meiner Mine herumtreiben. Ich kann meine Peons dort nicht hineinschicken. Und auch wenn ich den Schredder repariert habe, möchte ich nicht riskieren, dass er im Kampf schon wieder kaputt geht. Der Anführer der Gan'arg haust tief unten in der Mine. Wenn Ihr ihn tötet, hauen die anderen Gan'arg vielleicht ab. Dann könnte ich endlich Geld verdienen und von hier weggehen.", progress = "Ist er schon tot? Ich habe viel zu viel Angst, um hinzuschauen.", completion = "Diese Gan'arg werden sich jetzt sicher verziehen. Und in einer Woche bin ich wieder in Beutebucht. Ich kann es kaum abwarten, endlich wieder angeln gehen zu können. Es war ein Fehler in die Scherbenwelt zu kommen. Wenn Ihr meinen Rat hören wollt, macht Euch schleunigst auf den Weg zurück nach wo Ihr herkommt. Verbringt ein wenig Zeit im Schlingendorntal! Oder wenn Ihr mehr auf Abenteuer aus seid im Krater von Un'Goro. Hauptsache nicht hier.", rewards = "TrümmersteinhackeUnterwelthelmAuf Euch wartet eine dieser Belohnungen:\n\nLaterne des Tiefenkerns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10632] = {title = "Zähne zeigen", objective = "Beschafft Euch 5 besonders scharfe Dolchrachenzähne.", description = "Es ist sehr nett von Euch, dass Ihr Toshley und den Wissenschaftlern hier helft. Ich kann mir jedoch nicht den Luxus erlauben, mich meinen 'persönlichen' Interessen hinzugeben.\n\nWenn Ihr hier etwas Besonderes sein wollt, dann tut, was ich sage. Ich brauche Waffen.\n\nUnsere Gewehre sind zwar im Fernkampf ganz nützlich, aber wenn uns diese Insekten zu nahe kommen, brauchen wir mächtige Nahkampfwaffen zur Verteidigung.\n\nDie Zähne der Dolchrachenschmetterschwänze im Messergrat im Norden geben tolle Vibroklingen ab. Treibt ein paar davon für mich auf!", progress = "Wie geht es mit dem Sammeln der Zähne voran?\n\nIch bin davon überzeugt, dass Ihr Eure Arbeit für uns gut machen werdet. Und während Ihr das tut, werden wir diesen Außenposten hier sichern.", completion = "Gute Arbeit, Junge. Der Schmerz ist gerechtfertigt, wenn auch nur einem meiner Soldaten durch Eure Bemühungen das Leben gerettet wird.\n\nIch bin der Meinung, dass auch Ihr von Eurem Blut und Euren Tränen profitieren solltet. Wir werden bald neue Waffen bekommen. Warum nehmt Ihr daher nicht einfach eine von meinen?", rewards = "VibromesserVibrodolchVibroschwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10633] = {title = "Teron Blutschatten - Geschichte und Mythos", objective = "Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.\n\nWenn Ihr Eure Geisterbrille verlieren solltet, kann Euch Hildagard ein neues Paar herstellen.\n\nBereitgestellter Gegenstand: \n", description = "Es gibt unzählige Geschichten über das Leben von Teron Blutschatten, aber manche sind eben nur Geschichten. Wir wissen nicht, was mit Blutschatten passiert ist, nachdem er nach Draenor zurückgekehrt war.\n\nMit Sicherheit wissen wir nur, dass er schon einmal gestorben ist.\n\nIch habe gehört, wie die Späher von einem alten Orcgeist sprachen, der beim Altar der Schatten haust. Er befindet sich weit im Südosten, hinter den Netherschwingenfeldern und jenseits des Netherschwingenpasses. Nehmt diese Geisterbrille und sucht diesen Orc. Er weiß sicher mehr über Blutschatten.", progress = nil, completion = "Blutschatten? Diesen Namen habe ich schon seit ewigen Zeiten nicht mehr gehört!\n\nNach dem Zweiten Krieg kehrte Blutschatten mit seinen Todesrittern hierher zurück. Als er nicht mit der Schrecklichkeit seiner neuen Form zurechtkam und ohne die Hilfe seines geliebten Anführers, Gul'dan, hilflos war, nahm Blutschatten sich das Leben.\n\nIch weiß nichts davon, dass er nun als Geist in diesen Weiten herumwandeln soll. Aber vielleicht kann ich das mit Eurer Hilfe herausfinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10634] = {title = "Hellsicht: Blutschattens Rüstung", objective = "Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Rüstung besorgt.", description = "Zu Lebzeiten war Blutschatten ein Scheusal, doch im Tod wurde sein Schrecken erst richtig entfesselt.\n\nIm Südosten findet Ihr die Netherschwingenscherbe. Einst war sie ein Teil des Festlands von Schattenmond, doch nun ist sie eine schwebende Insel.\n\nVhel'kur, der Nachkomme von Todesschwinge, nannte sie einst sein Zuhause, doch nun ist sie sein Grab. Er fliegt in endlosen Kreisen über der Insel, brodelnd vor Zorn über seine Niederlage gegen Blutschatten.\n\nWenn Ihr Blutschattens Rüstung beschaffen wollt, müsst Ihr Vhel'kur besiegen.", progress = "Fliegt zur Netherschwingenscherbe und beschafft die Rüstung.", completion = "Ich muss alle Gegenstände besitzen, bevor ich Blutschattens Schicksal mit Hellsicht herausfinden kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10635] = {title = "Hellsicht: Blutschattens Umhang", objective = "Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Umhang besorgt.", description = "Er beging so manche Grausamkeit, aber keine war so kaltblütig wie das Abschlachten der Kleriker von Karabor.\n\nNachdem Gul'dans Horde die Draenei von Karabor besiegt hatte, wurden die überlebenden Kleriker verschleppt. Man sagte ihnen, dass sie als Kriegsgefangene in die Höllenfeuerzitadelle gebracht würden.\n\nDoch Blutschatten, der damals noch kein Todesritter war, brachte jeden einzelnen auf grausamste Weise um. Nun streichen sie voller Rachedurst vor dem Schwarzen Tempel umher.\n\nDie Kleriker von Karabor haben Blutschattens Umhang.", progress = "Ihr müsst die Geisterbrille benutzen, um die Geister von Schattenmond sehen zu können.", completion = "Wenn ich alle drei Gegenstände in meinem Besitz habe, kann ich mit Hellsicht versuchen, den Aufenthaltsort von Blutschatten zu bestimmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10636] = {title = "Hellsicht: Blutschattens Schlagstock", objective = "Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Schlagstock besorgt.", description = "Einer nach dem anderen kniete vor ihm nieder und brachte ihm seine Ehrerbietung dar. Blutschatten hob seine Sichel und schlug ihnen die Köpfe ab. Kurz nach diesem Massaker nahm er sich selbst das Leben.\n\nDoch er tat es nicht etwa aus Reue! Nein, Blutschatten wollte Unsterblichkeit! Von den Leichen der gefallenen Todesrittern erhoben sich die Geistritter von Karabor.\n\nJetzt reiten sie auf den Straßen um die Hand von Gul'dan herum und warten auf die Rückkehr ihres Meisters. Sie haben Blutschattens Schlagstock. Holt ihn Euch...", progress = "Ihr müsst die Geisterbrille benutzen, um die Geister von Schattenmond sehen zu können.", completion = "Nur mit allen drei Gegenständen zusammen kann ich die versuchen, die Geheimnisse, die Ihr zu lüften wünscht, hell zu sehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10637] = {title = "Eine notwendige Ablenkung", objective = "Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Die Waffen sind echt, wie wir befürchtet haben. Illidan bildet in den Ruinen von Karabor Dämonenjäger aus. Das müssen wir verhindern.\n\nLasst Euch nicht von dem Namen täuschen, <Name>. Sie werden ihre Macht genauso oft gegen uns einsetzen, wie gegen Dämonen.\n\nIhre Hexenmeister beschwören und unterwerfen Dämonen im Rahmen der Ausbildung der Initiierten. Ein Grubenlord namens Azaloth hat sich in der Ausbildung als zu mächtig erwiesen und wird nun unter Verschluss gehalten. Findet einen Weg, ihn frei zu lassen und auf seine Kerkermeister zu hetzen. Das sollte uns die nötige Zeit verschaffen.", progress = nil, completion = "Wollen wir hoffen, dass diese Ablenkung uns die Zeit verschafft, die wir brauchen, um alles herauszufinden, was wir über die Ausbildungsgelände von Karabor wissen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10638] = {title = "NOT A QUEST", objective = "Sucht <NAME> im <DISTRICT> von Silbermond auf.Besucht Euren Lehrer in Silbermond.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Besucht Euren Lehrer in Silbermond.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10639] = {title = "Ich bin Teron Blutschatten...", objective = "Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.\n\nWenn Ihr erfolgreich wart, meldet Euch bei Chefapothekerin Hildagard in Schattenmond.", description = "Jetzt, da wir Blutschattens Gegenstände beisammen haben, fehlt nur noch ein letztes Teil im Puzzle: ein Wirt.\n\n<Die Lippen des uralten Schattenmondgeistes verziehen sich zu einem bösartigen Grinsen.>\n\nIhr habt doch nicht etwa das Märchen geglaubt, das ich Euch aufgetischt habe? Der Altar der Schatten ist mein Gefängnis. Ohne Eure Hilfe wäre ich bis in alle Ewigkeit hier gefangen geblieben. Jetzt werde ich Euren Körper übernehmen und Ihr werdet die, die mich gefangen haben, vernichten und das Band für immer zerreißen. Wenn Ihr ablehnt, sind wir beide bis ans Ende der Zeit hier gefangen.\n\nTeron Blutschatten wird frei sein!", progress = nil, completion = "Was habt Ihr getan? DUMMKOPF!\n\nIhr müsst dieses Unrecht wieder gutmachen. Schließlich war es Euer Fehler. Nehmt einen dieser Helme. Sie sind mit der Macht der ewig brennenden Asche, die Ihr mir gebracht habt, erfüllt. Viel wichtiger ist jedoch, dass Ihr damit die Geister Schattenmonds sehen könnt, auch Teron Blutschatten.\n\nWenn Ihr ihn jemals findet, vernichtet ihn.", rewards = "Beschwörerhelm des zweiten GesichtsOberanführerhelm des zweiten GesichtsPirscherhelm des zweiten GesichtsSchamanenhelm des zweiten GesichtsVerstohlenheitshelm des zweiten GesichtsDruidenhelm des zweiten Gesichts"}
MultiLanguageQuestData['de'][10640] = {title = "Altruis", objective = "Reist in den Westen Nagrands und sucht Altruis den Leider.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "In diesen Zeiten hört man nur noch selten von solchen, die den Weg des Dämonenjägers eingeschlagen haben. Und noch seltener findet man einen Dämonenjäger, der nicht im Bund mit Illidan steht.\n\nGerüchten zufolge soll ein solches Wesen hier in der Scherbenwelt leben. Es gibt einen Namen, der bei der Legion in Nagrand noch mehr gefürchtet sein soll, als eine ganze Armee von Verteidigern der Aldor, und das ist der Name Altruis.\n\nGeht in den Westen Nagrands und sucht ihn. Vielleicht ist er bereit, etwas mehr über diese neuen Ausbildungsgelände für Dämonenjäger zu erzählen.", progress = nil, completion = "Ihr habt einen langen Weg hinter Euch, Fremder. Ich bin überrascht, dass derjenige, der Euch zu mir geschickt hat, von mir gehört hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10641] = {title = "Gegen die Legion", objective = "Altruis der Leidende möchte, dass Ihr das frisch gezapfte Blut einer Zornpriesterin der Konstruktionsbasis: Gehenna im Nethersturm besorgt. Schüttet es auf den Boden und tötet den Avatar von Sathal. Kehrt zu Altruis dem Leider zurück, wenn Ihr fertig seid.", description = "Die Brennende Legion hat immer und immer wieder bewiesen, wie leicht sie sterbliche Seelen verderben kann. Wenn ich Euch mit dem Wissen, nach dem Ihr strebt, ausstatten soll, muss ich erst Eure Gesinnung überprüfen.\n\nEine Dämonin namens Sathal schafft es schon eine ganze Weile, mir dank ihrer körperlosen Form zu entwischen.\n\nSie überwacht die Zornpriesterinnen, die ihren Willen in der Konstruktionsbasis: Gehenna ausführen. Tötet eine ihrer Dienerinnen und vergießt ihr Blut auf dem Boden. Diese Beleidigung sollte Sathal dazu bringen, sich für eine Zeitlang zu materialisieren. Tötet sie, solange Ihr die Möglichkeit dazu habt.", progress = nil, completion = "Ihr habt beweisen, dass Ihr nicht von der Berührung der Legion verderbt wurde. Der Feind meines Feindes ist mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10642] = {title = "Spiritus ex machina", objective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr ihm 15 Proben ewig brennende Asche bringt.", description = "Ich fürchte, dass diese Zwerge nicht verstehen, worauf sie da gebaut haben. Diese Gegend war einst der Ahnengrund der Schattenmondorcs. Ich spreche von Geistern, <Volk>.\n\nFast zwanzig Jahre lang ruhten sie unter der Wildhammerfeste, doch vor Kurzem hat etwas sie aufgerührt.\n\nReist jenseits der Tore von Wildhammer und untersucht die Becken und Flüsse der Teufelslava überall in dieser Gegend. In der Nähe der Lava findet Ihr ewig brennende Asche. Bringt mir diese Asche, damit ich etwas daraus herstellen kann, das uns helfen wird.", progress = "Ja, es besteht eine Dualität... Ich kann es fühlen.", completion = "&lt;Zorus beginnt damit, etwas aus den Aschenproben herzustellen.&gt;\n\nEs ist vollbracht. Seht her, eine Geisterbrille!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10643] = {title = "Herolde des Schattenmondklans", objective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 12 Herolde des Schattenmondklans tötet.", description = "Seid Euch im Klaren, dass Zorus keinen Humor hat.\n\nGenug geredet. Zieht die Geisterbrille auf, damit Ihr die Orcgeister des Schattenmondklans, die sich in dieser Feste herumtreiben, sehen könnt. Habt keine Angst. Eigentlich sind wir die Eindringlinge hier. Dennoch müssen sie zerstört werden, denn ihre Zeit ist schon lange vorüber.\n\nZerstört die Herolde des Schattenmondklans, die in der Wildhammerfeste spuken, und kehrt dann zu mir zurück.", progress = "Wenn Ihr Eure Brille verliert, kann ich Euch eine neue herstellen.", completion = "Ihr sagt, Ihr habt die Geister zu Euch flüstern hören? Und sie sprachen über Teron Blutschatten?\n\n&lt;Zorus schaudert.&gt;\n\nJa... Ich kenne Teron Blutschatten. Oder besser gesagt kannte ihn. Er ist schon vor langer Zeit gestorben. Wovon können diese Geister wohl gesprochen haben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10644] = {title = "Teron Blutschatten - Geschichte und Mythos", objective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.\n\nWenn Ihr Eure Geisterbrille verlieren solltet, kann Euch Zorus der Richter eine neue herstellen.\n\nBereitgestellter Gegenstand: \n", description = "Es gibt unzählige Geschichten über das Leben von Teron Blutschatten, aber manche sind eben nur Geschichten. Wir wissen nicht, was mit Blutschatten passiert ist, nachdem er nach Draenor zurückgekehrt war.\n\nMit Sicherheit wissen wir nur, dass er schon einmal gestorben ist.\n\nIch habe gehört, wie die Späher von einem alten Orcgeist sprachen, der beim Altar der Schatten haust. Er befindet sich weit im Osten, hinter den Netherschwingenfeldern und jenseits des Netherschwingenpasses. Nehmt diese Geisterbrille und sucht diesen Orc. Er weiß sicher mehr über Blutschatten.", progress = nil, completion = "Blutschatten? Diesen Namen habe ich schon seit ewigen Zeiten nicht mehr gehört!\n\nNach dem Zweiten Krieg kehrte Blutschatten mit seinen Todesrittern hierher zurück. Als er nicht mit der Schrecklichkeit seiner neuen Form zurechtkam und ohne die Hilfe seines geliebten Anführers, Gul'dan, hilflos war, nahm Blutschatten sich das Leben.\n\nIch weiß nichts davon, dass er nun als Geist in diesen Weiten herumwandeln soll. Aber vielleicht kann ich das mit Eurer Hilfe herausfinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10645] = {title = "Ich bin Teron Blutschatten...", objective = "Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.\n\nWenn Ihr erfolgreich wart, meldet Euch bei Zorus dem Richter in der Wildhammerfeste.", description = "Jetzt, da wir Blutschattens Gegenstände beisammen haben, fehlt nur noch ein letztes Teil im Puzzle: ein Wirt.\n\n<Die Lippen des uralten Schattenmondgeistes verziehen sich zu einem bösartigen Grinsen.>\n\nIhr habt doch nicht etwa das Märchen geglaubt, das ich Euch aufgetischt habe? Der Altar der Schatten ist mein Gefängnis. Ohne Eure Hilfe wäre ich bis in alle Ewigkeit hier gefangen geblieben. Jetzt werde ich Euren Körper übernehmen und Ihr werdet die, die mich gefangen haben, vernichten und das Band für immer zerreißen. Wenn Ihr ablehnt, sind wir beide bis ans Ende der Zeit hier gefangen.\n\nTeron Blutschatten wird frei sein!", progress = nil, completion = "Was habt Ihr getan? DUMMKOPF!\n\nIhr müsst dieses Unrecht wieder gutmachen. Schließlich war es Euer Fehler. Nehmt einen dieser Helme. Sie sind mit der Macht der ewig brennenden Asche, die Ihr mir gebracht habt, erfüllt. Viel wichtiger ist jedoch, dass Ihr damit die Geister Schattenmonds sehen könnt, auch Teron Blutschatten.\n\nWenn Ihr ihn jemals findet, vernichtet ihn.", rewards = "Beschwörerhelm des zweiten GesichtsOberanführerhelm des zweiten GesichtsPirscherhelm des zweiten GesichtsSchamanenhelm des zweiten GesichtsVerstohlenheitshelm des zweiten GesichtsDruidenhelm des zweiten Gesichts"}
MultiLanguageQuestData['de'][10646] = {title = "Illidans Schüler", objective = "Hört Euch Altruis' Geschichte an.", description = "Ihr habt bewiesen, dass Ihr guter Gesinnung seid, <Name>. Bitte verzeiht mein Misstrauen, aber in dieser Welt sind die Dinge nicht so, wie sie scheinen.\n\nWenn Ihr bereit seid, werde ich Euch von Varedis erzählen.", progress = "Varedis ist mächtig. Dennoch gibt es einen Weg, wie er besiegt werden kann.", completion = "Jetzt kennt Ihr die Geschichte. Bleibt nur noch eine Sache zu erledigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10647] = {title = "Gesucht: Uvuros, Geißel von Schattenmond", objective = "Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Sardon Treuschnitt in Schattenmond im Schattenmondtal.", description = "Gesucht - TOT:\n\nUvuros, Geißel des Schattenmondtals.\n\nAuf Befehl des Oberanführers Or'barokh ist die Teufelsbestie zu töten, wenn sie angetroffen wird. Ferner ist die Mähne als Beweis von dem toten Leib abzutrennen. Bringt die feurige Mähne der Bestie zu Kriegsrufer Sardon Treuschnitt, wenn Ihr erfolgreich wart.\n\nUvuros wurde zuletzt bei der Hand von Gul'dan im Herzen des Schattenmondtals, östlich von Schattenmond, gesehen.", progress = "Wollt Ihr die Belohnung kassieren, Mann?", completion = "Ihr seid echt der Brüller, was? Gut gemacht! Und Ihr kriegt auch Eure Belohnung. Is' doch Ehrensache...", rewards = "Handschuhe aus Uvuros' BalgStiefel aus Uvuros' BalgSattelgurt aus Uvuros' BalgUvuros' PlattenschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10648] = {title = "Gesucht: Uvuros, Geißel von Schattenmond", objective = "Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Bierschnut in der Wildhammerfeste im Schattenmondtal.", description = "Gesucht- TOT:\n\nUvuros, Geißel des Schattenmondtals.\n\nAuf Befehl von Than Yoregar ist die Teufelsbestie zu töten, wenn sie angetroffen wird. Ferner ist die Mähne als Beweis von dem toten Leib abzutrennen. Bringt die feurige Mähne der Bestie zu Kriegsrufer Bierschnut, wenn Ihr erfolgreich wart.\n\nUvuros wurde zuletzt bei der Hand von Gul'dan im Herzen des Schattenmondtals, nordöstlich der Wildhammerfeste, gesehen.", progress = "Ich hoffe, Ihr habt etwas Großartiges getan, Bursche. Ansonsten macht Euch vom Acker!", completion = "Hier ist Eure Belohnung. Gebt nicht alles auf einmal aus!", rewards = "Handschuhe aus Uvuros' BalgStiefel aus Uvuros' BalgSattelgurt aus Uvuros' BalgUvuros' PlattenschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10649] = {title = "Das Buch der teuflischen Namen", objective = "Reist in das Schattenlabyrinth von Auchindoun und besorgt das Buch der teuflischen Namen von Schwarzherz dem Hetzer. Kehrt danach zu Altruis in Nagrand zurück.", description = "Ich finde es gut, dass Ihr vorhabt, Varedis und seine Anhänger aufzuhalten, aber Ihr habt keine Chance gegen ihn. Es sei denn, Ihr findet das Artefakt, das ihm seine Macht verliehen hat.\n\nDas Buch der teuflischen Namen soll sich im Besitz von Schwarzherz dem Hetzer befinden, der sich im Schattenlabyrinth von Auchindoun aufhält. Eure einzige Hoffnung, Varedis besiegen zu können, ruht auf diesem Buch.", progress = "Habt Ihr das Buch besorgt, <Name>?", completion = "Ich konnte die Macht des Buches schon über Meilen hinweg spüren. Die Versuchung, es einfach zu behalten ist... sehr groß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10650] = {title = "Rückkehr zu den Aldor", objective = "Sprecht mit Exarch Onaala beim Altar der Sha'tar im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Dieses Buch... könnte meine Macht verzehnfachen... nein! Es würde meine Seele verderben, ich weiß es genau. Bringt es zurück zu denen, die Euch geschickt haben, <Name>.\n\nIhr habt nun die Mittel, um Varedis aufzuhalten. Wartet, bis er sich mithilfe der Metamorphose in seiner dämonischen Form manifestiert. Genau in diesem Moment müsst Ihr das Buch in seiner Anwesenheit verbrennen. Nur so könnt Ihr ihn seiner Macht berauben.", progress = nil, completion = "Ihr bringt diese Abscheulichkeit eines Buches an einen heiligen Ort? Ich hoffe, dass Ihr dafür eine gute Erklärung habt, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10651] = {title = "Varedis muss aufgehalten werden", objective = "Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Exarch Onaala zurück.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Wir müssen dieses abscheuliche Artefakt zerstören, jedoch nicht, bevor wir damit Varedis seiner Mächte beraubt haben.\n\nDas Ausbildungsgelände der Ruinen von Karabor muss für alle Zeiten geschlossen werden. Dazu müsst Ihr nicht nur Varedis töten, sondern auch seine drei Nachtelfenmeister, die ihn unterstützen: Alandien, Theras und Netharel.\n\nStellt eine geeignete Truppe zusammen und kehrt zu den Ruinen von Karabor zurück. Befolgt Altruis' Anweisungen, um Varedis zu besiegen. Ich hoffe für uns alle, dass sie funktionieren.", progress = "Habt Ihr vollendet, worum ich Euch gebeten habe, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Euer Sieg über Varedis ist ein entscheidender Schritt in unserem Krieg gegen Illidan.\n\nIhr habt Euch nicht nur den Aldor, sondern gegenüber der gesamten Scherbenwelt als würdig erwiesen. Bitte gestattet mir, die Überreste dieses schrecklichen Buchs zu vernichten.", rewards = "Halsberge von KaraborBeinschützer des SonnenzornsBeschwörerklingeWildruferTöteraxtZeremonieller KrisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10652] = {title = "Hinter feindlichen Linien", objective = "Sprecht mit Veronia, wenn Ihr bereit seid, zur Manaschmiede Coruu aufzubrechen. Meldet Euch dort bei Caledis Morgenhell.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Es wurden alle Vorkehrungen getroffen, um Euch zum Versteck der Spione zu bringen. Sucht mich einfach auf, wenn Ihr bereit seid, und wir werden Euch auf den Weg schicken.", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Bemüht Euch, unsere Position nicht zu verraten.\n\nWenn Kaels Spießgesellen uns entdecken, leben wir nicht mehr lange.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10653] = {title = "Male des Sargeras", objective = "Bringt 10 Male des Sargeras zu Adyen dem Lichtwächter in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Die hochrangigsten Mitglieder der Legion findet Ihr im Nethersturm und im Schattenmondtal.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, <Name>?", completion = "Sich den Dämonen der Brennenden Legion und den wahnsinnigen Kultisten, die sie verehren, zu stellen ist keine geringe Tat, &lt;Name&gt;. Ihr habt viel Hingabe und Mut bewiesen. Macht so weiter, und Euer Ruf bei den Aldor wird weiter steigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10654] = {title = "Mehr Male des Sargeras", objective = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", description = nil, progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", completion = "Beweist Euch weiterhin als würdig, &lt;Name&gt;. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden.", rewards = nil}
MultiLanguageQuestData['de'][10655] = {title = "Einzelne Male des Sargeras", objective = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", description = nil, progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Ihr beweist Euch weiterhin als würdig, &lt;Name&gt;. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden.", rewards = nil}
MultiLanguageQuestData['de'][10656] = {title = "Siegel des Sonnenzorns", objective = "Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Ihr wisst vielleicht, dass die Seher mit Kael'thas Armeen im Krieg stehen. Kael betrachtet uns als Bedrohung für seinen Einfluss über die Blutelfen und hat immer wieder versucht, uns zu vernichten.\n\nWenn Ihr uns in der Schlacht gegen Kael'thas helfen wollt, gibt es viele Ziele, die Ihr angreifen könnt. Kaels hochrangigste Soldaten tragen die Siegel des Sonnenzorns, der ihren Rang angibt. Ihr findet sie überall im Nethersturm und im Schattenmondtal.", progress = "Los, <Name>. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ihr habt beeindruckende Arbeit geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10657] = {title = "Lasst sie abblitzen!", objective = "Benutzt die repolarisierte Magnetsphäre, um 25 Blitzschläge von Schuppenflügelschlangen abzufangen. Beschafft darüber hinaus 5 Blitzschlagdrüsen eines Schuppenflügels.", description = "Wir sind nicht gerade sparsam mit dem Zephyriumkapazitorium umgegangen. Aber wie es scheint verfügen die Schlangen der Schuppenflügelbank im Osten über einen Blitzschlagatem und Blitzschlagdrüsen, die wir uns zu Nutze machen können.\n\nIch habe den Magnetsammler repolarisiert, sodass er die Blitzschläge absorbieren kann. Begebt Euch dorthin, schaltet es an und besorgt uns ein wenig billige Energie!", progress = "Der Trick dabei ist, die repolarisierte Magnetsphäre rechtzeitig abzuschalten, bevor Ihr gegrillt werdet.\n\nNatürlich müsst Ihr Euch dabei gut überlegen, wie vielen Schlangen Ihr gleichzeitig gegenübersteht.\n\nWo wir gerade davon sprechen, habt Ihr die Sphäre schon aufgeladen?", completion = "Jippieh, es hat geklappt! Ich war mir da ehrlich gesagt nicht so sicher... Ich habe eine Wahrscheinlichkeit von 23,72 Prozent berechnet, dass Ihr beim dritten Treffer implodiert.\n\n&lt;Toshley grinst unschuldig.&gt;\n\nJetzt wissen wir also, dass die Sphäre funktioniert. Es sollte also keine weiteren Probleme geben, den nötigen Saft für unser Zephyriumkapazitorium zu beschaffen. Natürlich nur, wenn ich noch mehr Freiwillige finde, die für mich dort hinaus gehen und sich brutzeln lassen.\n\nAber Ihr habt den Pionier für unsere Bemühungen gespielt und verdient eine Belohnung!", rewards = "Energieerfüllte GelenkbänderAufgeladene StiefelSchuppenflügelhandschuheMuskelstärkender GürtelIhr bekommt:\n\nReine Energie"}
MultiLanguageQuestData['de'][10658] = {title = "Mehr Siegel des Sonnenzorns", objective = "Was habt Ihr in letzter Zeit für uns getan, <Name>? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", description = nil, progress = "Was habt Ihr in letzter Zeit für uns getan, <Name>? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", completion = "Ausgezeichnet! Das wird Kael'thas zeigen, dass unsere Macht nicht zu unterschätzen ist.", rewards = nil}
MultiLanguageQuestData['de'][10659] = {title = "Einzelne Siegel des Sonnenzorns", objective = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!", description = nil, progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Kaels Armee wird bald fallen.", rewards = nil}
MultiLanguageQuestData['de'][10660] = {title = "Welch merkwürdige Wesen...", objective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt.", description = "Ich möchte mehr über die merkwürdigen Reptilien, die bei den Lavaströmen des Schattenmondtals umherstreifen, erfahren. Ich habe noch nie zuvor Tiere gesehen, die der sengenden Hitze geschmolzener Lava widerstehen konnten!\n\nAußerhalb von Schattenmond, wo der Boden aufgerissen ist und die Lava durch die Risse tritt, findet Ihr die Teufelsfeuerdimetrodonten. Tötet sie und bringt mir ihre Milzen. Mit ihrer Hilfe kann ich eine erste Analyse ihres Feuerwiderstands durchführen.\n\nBeginnt Eure Suche im Südosten.", progress = "Milzen! Ich brauche Milzen!", completion = "&lt;Forscher Tiorus nimmt die Milzen an sich und beginnt seine Untersuchung.&gt;\n\nDas dürfte eine Weile dauern. Nehmt dies als Bezahlung für Eure harte Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10661] = {title = "Demilziös!", objective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt.", description = "Habt Ihr jemals von Essen gehört, dass sich selbst kocht und für immer warm bleibt? Das wäre traumhaft!\n\nAber vielleicht muss es kein Traum bleiben! Außerhalb der Feste, in der Nähe der Lavabecken und Lavaströme, gibt es Kreaturen, die in der glühenden Hitze gedeihen. Man nennt sie Teufelsfeuerdimetrodonten.\n\nDie Zwerge hier haben mir gesagt, dass sie die leckersten Milzen aller Zeiten haben. Und das Beste ist, dass sie schon vorgekocht sind! Bringt mir ein paar dieser Milzen! Ich werde Euch gut bezahlen.\n\nBeginnt direkt östlich von hier mit Eurer Suche.", progress = "Milzen! Ich brauche Milzen!", completion = "&lt;Gnomus reißt die Milzen hungrig an sich.&gt;\n\nHier ist die versprochene Bezahlung. Ich rufe Euch, wenn ich noch mehr Milzen brauche.\n\nSo lecker... Ich würde fast meinen 'demilziös'!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10662] = {title = "Der Wanderschmied", objective = "Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar.", description = "<Ordinn betrachtet seinen Versuch, das Metall zu schmieden, und schüttelt den Kopf.>\n\nMeine Fertigkeiten reichen dazu nicht aus, aber das soll nicht heißen, dass die Waffe für Euch nicht neu geschmiedet werden kann.\n\nEin talentierter Schmied namens David Wayne begleitete die Söhne Lothars nach Draenor, doch er beschloss, die Expedition zu verlassen. Heute lebt er in einem kleinen Lager auf einer Halbinsel östlich des Postens der Feuerschwingen in den Wäldern von Terokkar. Bringt diese Barren zu ihm und schaut, ob Ihr ihm beim Schmieden der Waffe helfen könnt.", progress = "Was führt Euch hierher, <Klasse>? Ich bekomme nicht viel Besuch.", completion = "Ordinn hat Euch damit zu mir geschickt?\n\n&lt;Der Schmied untersucht die Barren.&gt;\n\nEr hatte Recht. Der Großteil der Magie ist verschwunden, aber ich kann noch immer Spuren davon in dem Metall spüren. Mit ein wenig Arbeit und ein paar 'ausgefallenen' Materialien kann ich Euch ein mächtiges antidämonisches Schwert aus diesem Metall schmieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10663] = {title = "Der Wanderschmied", objective = "Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar.", description = "<Der Orc betrachtet seinen Versuch, das Metall zu schmieden, und schüttelt den Kopf.>\n\nMeine Fertigkeiten reichen dazu nicht aus, aber das soll nicht heißen, dass die Waffe für Euch nicht neu geschmiedet werden kann.\n\nEin talentierter Schmied namens David Wayne begleitete die Söhne Lothars nach Draenor, doch er beschloss, die Expedition zu verlassen. Heute lebt er in einem kleinen Lager auf einer Halbinsel östlich des Postens der Feuerschwingen in den Wäldern von Terokkar. Bringt diese Barren zu ihm und schaut, ob er Euch beim Schmieden der Waffe helfen kann.", progress = "Was führt Euch hierher, <Klasse>? Ich bekomme nicht viel Besuch.", completion = "Ordinn hat Euch damit zu mir geschickt?\n\n&lt;Der Schmied untersucht die Barren.&gt;\n\nEr hatte Recht. Der Großteil der Magie ist verschwunden, aber ich kann noch immer Spuren davon in dem Metall spüren. Mit ein wenig Arbeit und ein paar 'ausgefallenen' Materialien kann ich Euch ein mächtiges antidämonisches Schwert aus diesem Metall schmieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10664] = {title = "Zusätzliche Materialien", objective = "David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm einen Adamantitrahmen, 4 Stück schweres Knotenhautleder und ein Dämonenschutztotem bringt.", description = "Das Metall, das Ihr mir gebracht habt, reicht zwar weitestgehend aus, um die Klinge des Schwerts zu schmieden, aber ich benötige noch viele andere Dinge, um die übrigen Teile der Waffe herzustellen.\n\nWollen wir mal schauen... Mir fehlen ein Adamantitrahmen, ein wenig schweres Knotenhautleder und ein Dämonenschutztotem. Geübte Kunsthandwerker sollten die ersten beiden Materialien herstellen können. Das dritte bekommt Ihr nur bei dem Reagenzienverkäufer Fantei im Unteren Viertel in Shattrath. Er hält sich bei den anderen Händlern auf.", progress = "Habt Ihr die Materialien?", completion = "&lt;Der Schmied nimmt Euch die Materialien ab und nickt zufrieden.&gt;\n\nDie werden reichen. Der Rest der Materialien, die ich benötige, wird jedoch nicht so leicht zu bekommen sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10665] = {title = "Frisch von der Mechanar", objective = "David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm eine überladene Manazelle bringt.", description = "Um das Metall, das Ihr mir gebracht habt, zu bearbeiten, brauche ich große Hitze - viel mehr, als eine normale Schmiede herstellen kann.\n\nIch werde eine zusätzliche Hitzequelle für die Schmiede brauchen. Nur wenige Dinge in der Scherbenwelt können diese Art von Wärmeenergie liefern.\n\nIn der Mechanar der Festung der Stürme werden Manazellen, in denen eine unglaubliche Menge an Energie gespeichert ist, hergestellt. Sucht eine überladene Manazelle in den Stapeln um Mechanolord Kapazitus herum und bringt sie zu mir.", progress = "Konntet Ihr eine Manazelle aus der Mechanar schmuggeln?", completion = "Sie ist sogar noch mächtiger, als ich erwartet habe! Mit so viel Energie könnte ich ein Dutzend Klingen schmieden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10666] = {title = "Encyclopaedia Daemonica", objective = "Beschafft die Encyclopaedia Daemonica von Großmeister Vorpil und bringt sie zu David Wayne in Waynes Zuflucht.", description = "Um die Verzauberungen auf der Klinge wiederherzustellen, müssen mehrere Zaubersprüche auf Dämonisch gesprochen werden.\n\nDas habe ich während meiner Ausbildung leider nicht gelernt, aber es führt kein Weg daran vorbei. Es gibt ein Buch, das Encyclopaedia Daemonica genannt wird. Darin könnte ich die meisten Worte, die ich brauche, finden. Leider ist das Buch im Besitz eines mächtigen Hexenmeisters des Schattenrats.\n\nTief im Schattenlabyrinth von Auchindoun wird es von Großmeister Vorpil bewacht. Tut, was immer Ihr tun müsst, um das Buch zu besorgen und bringt es zu mir.", progress = "Habt Ihr das Buch besorgt?", completion = "&lt;David blättert die Seiten des Buchs durch und schaudert.&gt;\n\nDas ist nichts, mit dem man spielen sollte, &lt;Name&gt;. Sobald die Waffe fertig ist, werde ich es zerstören. Es gibt schon genug dämonische Macht in dieser Welt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10667] = {title = "Unterweltlehm", objective = "Beschafft Euch ein Gefäß mit Unterweltlehm von Wasserbeschwörerin Thespia und bringt es zu David Wayne in Waynes Zuflucht.", description = "Der Rahmen, den Ihr mir gebracht habt, wird nicht ausreichen, um geschmolzenes Metall ohne zusätzliche Verstärkung zu halten. Der Rahmen kann mit einer seltenen Art von Erde abgekühlt und verdichtet werden, die ihm eine unnatürliche Stärke verleiht.\n\nDiese Erde ist als Unterweltlehm bekannt und gilt bei den Nagas als äußerst wertvoll. Nur wenige von ihnen besitzen etwas davon und ich kenne nur eine Naga in der Scherbenwelt, die sie benutzt: Wasserbeschwörerin Thespia, die in der Dampfkammer des Echsenkessels lebt.", progress = "Habt Ihr den Unterweltlehm bekommen?", completion = "Das sollte funktionieren. Ich hatte zwar auf etwas mehr gehofft, aber um ehrlich zu sein können wir uns glücklich schätzen, hier draußen überhaupt etwas davon in die Finger bekommen zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10668] = {title = "Gegen die Illidari", objective = "Altruis der Leidende möchte, dass Ihr Lothros in der Stätte der Illidari im Schattenmondtal tötet.", description = "Ich habe immer noch Respekt vor Illidan. Ohne ihn hätte ich nie meinen Pfad gefunden.\n\nDoch er ist nicht mehr der, der er einst war. Seine Seele wurde von Macht verderbt, sein Geist durch seine Niederlagen zerrissen. Ich habe geschworen, das, was aus ihm geworden ist, zu vernichten. Seine Schoßtierchen, die Illidari, sind genauso abscheulich wie die Dämonen der Brennenden Legion.\n\nAuch wenn sich sein Griff um die Scherbenwelt lockert, hat er immer noch weit reichenden Einfluss. Beweist mir, dass Ihr nicht auf seiner Seite steht, und tötet seinen Leutnant Lothros bei der Stätte der Illidari im Schattenmondtal.", progress = nil, completion = "Ihr gehört also nicht zu Illidan. Ihr seid einen Schritt näher daran, mein volles Vertrauen zu erlangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10669] = {title = "Gegen jede Chance", objective = "Altruis der Leidende möchte, dass Ihr den magieerfüllten Silberspeer bei der Portalsicherung in der Nähe des Sumpflichtsees in den Zangarmarschen verwendet, um Xeleth zu wecken. Kehrt zu Altruis zurück, wenn Ihr den Dämon erlegt habt.", description = "Einige Dämonen schwören nur sich selbst die Treue. Ein wahrer Dämonenjäger sucht und vernichtet jedoch seine Beute ungeachtet ihrer Zugehörigkeit.\n\nDer Dämon Xeleth, ein Abtrünniger der Legion, wurde einst von den primitiven Sumpfkreaturen der Zangarmarschen als Gott verehrt. Als Draenor fast zerstört wurde, zog er sich in einen tiefen Schlaf unter dem Sumpflichtsee zurück. Findet das Portal beim See und steckt diesen Speer in den Boden.\n\nXeleth wird davon erwachen. Tötet ihn und beweist, dass Ihr ein Feind aller Dämonen seid.", progress = "Ihr seid zurück. Ist Xeleth tot?", completion = "Gut gemacht, &lt;Name&gt;. Er konnte sich also immer noch an den Tag erinnern, an dem ich den Speer in seinen Körper rammte? Das ist schon so lange her...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10670] = {title = "Träne der Erdenmutter", objective = "Besorgt die Träne der Erdenmutter von Kriegshetzer O'mrogg und bringt sie zu David Wayne in Waynes Zuflucht.", description = "Die Verzauberungen des Schwerts müssen mit einem mächtigen Fokus gebunden werden, wie zum Beispiel einem Edelstein. Nur wenige Steine können eine so starke Magie in sich aufnehmen, ohne zu zerbersten, doch ich kenne einen.\n\nDer Edelstein, den wir brauchen, wird Träne der Erdenmutter genannt. Er ist ein mächtiges Artefakt, das sich in den Händen seiner Schöpfer, der Oger, befindet. Kriegshetzer O'mrogg, der den Stein im Augenblick besitzt, hat viele mächtige Verbündete in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Seid also vorsichtig, wenn Ihr die Träne besorgt, <Name>.", progress = "Konntet Ihr den Edelstein O'mroggs Klauen entreißen?", completion = "&lt;David Wayne hält den Edelstein gegen das Licht und bewundert ihn.&gt;\n\nEr ist absolut makellos und genau das, was wir brauchen. Ein fehlerhafter Edelstein würde den Träger der Waffe in Gefahr bringen und die Magie gegen ihn richten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10671] = {title = "Ein Pfund Geschnetzeltes", objective = "Beschafft Euch 5 Einheiten astralisiertes Fleisch.", description = "<Name>, ich habe noch eine andere Aufgabe für Euch. Einer der Eierköpfe möchte die bösartigen Fleischbestien untersuchen, die sich bei Razaans Landeplatz nördlich des Messergrats aufhalten.\n\nGenauer gesagt wollen sie das Fleisch der Fleischbestien dort untersuchen.\n\n<Dina verzieht angewidert das Gesicht.>\n\nAber sie wollen sich die Hände natürlich nicht schmutzig machen. Und sie wollen nur das astralisierte Fleisch, das sicher nicht alle haben.\n\nMeiner Meinung nach kann man als Bettler nicht wählerisch sein, aber was sollen wir schon machen?", progress = "Habt Ihr mein Geschnetzeltes schon? Wie, das findet Ihr nicht lustig?", completion = "Das sollte genügen. Es stinkt fürchterlich, oder?\n\nIch hoffe, dass es Eure Mühen wert war... Ich bin nur froh, dass ich das Zeug nicht selber sammeln musste!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10672] = {title = "Das ergibt echt keinen Sinn...", objective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr zu dem Lavastrom in der Nähe der Ruinen von Baa'ri reist und die Arkanosteuereinheit benutzt, um einen Arkanoskorp zu steuern. Schwimmt mit dem Arkanoskorp durch die Lava und markiert 8 große Teufelsfeuerdimetrodonten.", description = "Wir müssen diese Wesen weiter untersuchen.\n\nWeit im Osten, in der Nähe des riesigen Lavastroms unter den Ruinen von Baa'ri, könnt Ihr Arkanosteuereinheiten finden. Diese Steuerungen wurden von einem Genie namens Gnomus hergestellt. Ihr einziger Zweck ist, Lava mithilfe eines mechanischen Skorpions zu erforschen.\n\nEr hat schon vor langer Zeit den Verstand verloren. Jetzt interessiert er sich nur dafür, das heißeste Essen in der Geschichte der Gnomheit zu futtern.\n\n<Tiorus rollt mit den Augen.>\n\nIch möchte, dass Ihr die Steuereinheit benutzt, um die Dimetrodonten des Lavastroms für unsere weiteren Studien zu markieren.", progress = nil, completion = "Wir haben keine Zeit zu verschwenden. Ich habe die markierten Dimetrodons beobachtet und herausgefunden, dass sie alle einem riesigen, nein, GIGANTISCHEN Dimetrodon namens Teufelsbuckel dem Großen unterstellt sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10673] = {title = "Teufelsflosse der Große", objective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr Teufelsflosse den Großen tötet und Teufelsflosses Balg beschafft.", description = "Gnomus weiß von dem riesigen Dimetrodon und will ihn aufessen! Er muss von irgendwoher erfahren haben, was ich durch sein Arkanoskorp gesehen habe. Nun, wir haben keine Zeit für Erklärungen. Er ist verrückt, und diese Verrücktheit könnte uns das kosten, was einem feuerfesten Anzug am Nächsten kommt.\n\nKehrt zurück zum Lavastrom in der Nähe von Baa'ri und findet Teufelsflosse den Großen. Bringt mir seinen Balg!\n\nVersucht nicht mit mir zu diskutieren, <Name>. Darüber bin ich längst hinaus.", progress = "Kommt in die Gänge! Der Appetit dieses Gnoms kennt keine Grenzen!", completion = "Endlich bin ich vollkommen vor der Lava geschützt! Natürlich könnt auch Ihr etwas von dieser Technologie abhaben, &lt;Name&gt;. Ihr habe es Euch verdient!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10674] = {title = "Das Licht der Phantasie einfangen", objective = "Benutzt die Lichtfalle, um 15 Lichtkugeln der Razaani zu fangen.", description = "Die Astralen der Razaani bei Razaans Landeplatz im Norden spielen mit einer interessanten Technologie herum.\n\nIch bin mir sicher, dass sie nichts dagegen hätten, wenn Ihr diese Falle benutzen würdet, um ein paar ihrer kleinen, rosafarbenen, schwebenden Lichtkugeln zu sammeln. Wahrscheinlich sind sie ohnehin nur Dekoration.\n\nDie Falle hat eine ganz spezielle Eigenschaft. Wenn sie geöffnet wird, sollte sie eine der schwebenden Kugel anziehen. Natürlich wird sie auch die Aufmerksamkeit der Razaani auf Euch lenken.", progress = "Ich nehme an, dass Ihr die Lichtkugeln bei Razaans Landeplatz schon besorgt habt, wenn Ihr Zeit habt, hier mit mir zu plaudern. Ich würde sie wirklich gerne untersuchen und herausfinden, was die Astralen damit vorhaben.", completion = "He! Wartet mal!!\n\nDas sieht nicht gut aus...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10675] = {title = "Ein Gnom kennt kein Erbarmen!", objective = "Beschafft Euch die Seelensammlung.", description = "<Toshley erbleicht.>\n\nDiese Kugeln bestehen sowohl aus Netherenergie als auch aus Seelen! Sogar Gnomseelen sind dabei!\n\nWie können sie es wagen! Waren sie es vielleicht, die unsere Leute, die auf dem Weg nach Norden waren, getötet haben?!\n\n<Name>, Ihr müsst dem ein Ende setzen und das geht nur, wenn Ihr ihren Anführer, Nexusprinz Razaan, ausschaltet.\n\nIhr müsst ihn jedoch aus seinem Versteck herauslocken. Ich schätze, dass Ihr das erreichen könnt, indem Ihr möglichst viele seiner Astralen der Razaani tötet.\n\nBringt mir seine Seelensammlung. Ich bin mir sicher, dass er eine hat.", progress = "Habt Ihr diesen Bastard Razaan schon erledigt?", completion = "Das geschieht ihm ganz Recht! Vielen Dank, dass Ihr dieser makaberen Mischung aus Magie und Technologie ein Ende bereitet habt.\n\nAls wahrer Held der Gnome überall auf dieser Welt, lasse ich Euch nun die höchste unserer Ehren zukommen... ein paar Stromwandler und Eure Wahl aus diesen Dingen hier!\n\nIch weiß, dass Ihr sie gut einsetzen werden!", rewards = "Gnomische ZauberstiefelHeldenhut von Toshleys StationVerwüstergamaschen der RazaaniBrustplatte des SeelenrettersIhr bekommt:\n\nStromwandler"}
MultiLanguageQuestData['de'][10676] = {title = "Bann der Illidari", objective = "Wartet, bis David Wayne das Schwert für Euch fertig geschmiedet hat.", description = "<David sammelt seine Schmiedeausrüstung zusammen.>\n\nIhr habt alles, was ich zum Schmieden einer antidämonischen Klinge brauche. Eure harte Arbeit und Euer Einsatz soll belohnt werden.\n\nEs ist an der Zeit, die Klinge zu schmieden.", progress = nil, completion = "&lt;David wischt sich den Schweiß von der Braue.&gt;\n\nDer größte Teil der Arbeit ist getan. Um die Magie jedoch zum Leben zu erwecken, muss das Schwert erst gehärtet werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10677] = {title = "Der zweite Gang...", objective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr einen überentwickelten Teufelsfeuermuskelmagen besorgt.", description = "Ich erinnere mich, dass ich östlich der Hand von Gul'dan, in der Nähe der Lavaströme um die Ruinen von Baa'ri herum größere Dimetrodonten gesehen habe. Ich möchte, dass Ihr mir einen überentwickelten Teufelsfeuermuskelmagen von den Kreaturen in dieser Gegend besorgt. Ihr müsst wahrscheinlich mehrere erlegen, bevor Ihr einen solchen Muskelmagen findet. Bleibt immer schön am Ball! Einer von ihnen hat meine nächste Mahlzeit bei sich!", progress = "Tagesmenü: Muskelmagen.", completion = "Das ist fantastisch! Aber ich habe gerade unglaubliche Nachrichten erhalten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10678] = {title = "Das Hauptgericht!", objective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr Teufelsflosses Balg besorgt.", description = "Ich werde mich kurz fassen. Ich arbeitete einst mit einem Blutelfen namens Tiorus zusammen. Meine Partnerschaft zu Tiorus brach ab, als ich mich dem Leben als Gourmet zugewandt habe. Er beschloss, unsere Forschungen mit MEINEN Erfindungen auf eigene Faust weiterzuführen. Wie auch immer, er hat ein paar seiner Hordendummköpfe meine Arkanoskorpfühler bei den Ruinen von Baa'ri benutzen lassen und dabei den Vater aller Dimetrodonten entdeckt!\n\nIch möchte, dass Ihr vor ihm dorthin gelangt und das Dimetrodon Teufelsflosse tötet. Bringt mir seinen Balg!\n\nBeeilt Euch!", progress = "Tagesmenü: Teufelsbuckels Balg", completion = "Ich brauche jetzt etwas Zeit für mich, &lt;Name&gt;. Vielen Dank für Eure Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10679] = {title = "Die Waffe härten", objective = "Reist zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan und härtet die geschmiedete Klinge des Illidaribanns in den Lavabecken. Kehrt dann mit der gehärteten Klinge des Illidaribanns zu David Wayne in Waynes Zuflucht zurück.", description = "Die Klinge ist fast fertig!\n\nMan kann beinahe schon fühlen, wie die Magie im Stahl zusammenfließt. Aber eine Sache ist noch zu tun.\n\nIhr müsst die geschmiedete Klinge zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan im Schattenmondtal bringen und das Schwert in den Lavabecken härten. Kehrt zurück, wenn Ihr den Stahl gehärtet habt.", progress = "Habt Ihr das Schwert in der Lava der Hand von Gul'dan gehärtet?", completion = "Gut gemacht!\n\n&lt;Der Schmied untersucht die Klinge sehr genau.&gt;\n\nIch würde sagen, dass sie deutlich besser ist, als die grobe Waffe der Legion, mit der wir angefangen haben. Diese Klinge wird nicht nur die Dämonen der Illidari erschlagen, sondern auch die Diener der Legion vernichten können.", rewards = "Magische Klinge des IllidaribannsBreitschwert des IllidaribannsClaymore des IllidaribannsDolch des IllidaribannsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10680] = {title = "Die Hand von Gul'dan", objective = "Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal.", description = "Die Elemente brauchen Eure Hilfe, <Volk>! Das Schattenmondtal wurde von unaussprechlichen Schrecken heimgesucht. Bis zum heutigen Tag leiden die Geister. Viele sind wütend und wollen nicht mit dem Irdenen Ring in Verbindung treten.\n\nHelft dieser Welt zu heilen, Freund.\n\nNordöstlich der Wildhammerfeste gibt es einen Ort, der als der Altar der Verdammnis bekannt ist. Begebt Euch dorthin und sprecht mit Erdheiler Torlok.", progress = nil, completion = "Es ist gut, dass Ihr gekommen seid, &lt;Volk&gt;. Wir haben viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10681] = {title = "Die Hand von Gul'dan", objective = "Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal.", description = "Die Elemente brauchen Eure Hilfe, <Volk>! Das Schattenmondtal wurde von unaussprechlichen Schrecken heimgesucht. Bis zum heutigen Tag leiden die Geister. Viele sind wütend und wollen nicht mit dem Irdenen Ring in Verbindung treten.\n\nHelft dieser Welt zu heilen, Freund.\n\nSüdöstlich von Schattenmond, im Herzen des Schattenmondtals, gibt es einen Ort, der als der Altar der Verdammnis bekannt ist. Begebt Euch dorthin und sprecht mit Erdheiler Torlok.", progress = nil, completion = "Es ist gut, dass Ihr gekommen seid, &lt;Volk&gt;. Wir haben viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10682] = {title = "Zeit zu verhandeln...", objective = "Verhandelt mit Aufseher Nuaar.", description = "Als wir hier im Ruuanwald ankamen, hielten sich die Wyrmkultisten nur im Pechschwingenkoven, der sich jenseits des Tunnels im Westen befindet, auf. Doch nun rücken sie immer näher an uns heran.\n\nIhr müsst den Aufseher der Wyrmkultisten finden. Es ist bekannt, dass er regelmäßige Kontrollgänge zwischen den verschiedenen Lagern hier im Ruuanwald durchführt.\n\nVerhandelt mit ihm. Lasst ihn wissen, dass wir kompromissbereit sind, jedoch auf keinen Fall zu dem Abschlachten der Wildtiere oder dem Fällen von Bäumen beitragen oder es tolerieren werden.", progress = nil, completion = "WAS?! Sie haben Euch fortgeschickt und unser Angebot ausgeschlagen?\n\nDas ist empörend! Wir sind in Frieden zu ihnen gekommen und sie schicken Euch weg, ohne auch nur zu versuchen, einen Kompromiss zu finden?\n\nNun, das wird Folgen haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10683] = {title = "Schrifttafeln von Baa'ri", objective = "Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Die Zerschlagenen der Aschenzungen wurden von Illidan beauftragt, in den Ruinen von Baa'ri weit im Norden Ausgrabungen durchzuführen. Sicher suchen sie nach Draeneiartefakten. Baa'ri verfügte über viele Relikte von Baa'ri, bevor Gul'dan die Stadt unter einer vulkanischen Explosion begrub. Wir müssen diese Chance nutzen, um an die Schrifttafeln von Baa'ri zu kommen. Dieser alte Text soll angeblich die Geheimnisse des Tempels von Karabor, der heute als Schwarzer Tempel bekannt ist, enthalten.", progress = "Habt Ihr die Schrifttafeln schon gefunden, <Name>?", completion = "Die Schrifttafeln von Baa'ri! Ja, die wird uns sehr wichtige Informationen liefern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10684] = {title = "Oronu der Älteste", objective = "Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Laut den Schrifttafeln wurde in Baa'ri ein Artefakt, das als Medaillon der heiligen Stimme bekannt ist, aufbewahrt. Nur die höchstrangigen Draeneipriester durften es tragen, da es uneingeschränkten Zugang zum Tempel von Karabor bot.\n\nWir müssen herausfinden, ob die Aschenzungen das Medaillon schon gefunden haben. Seine Macht wäre uns eine große Hilfe im Kampf gegen Illidan.\n\nAkamas Leutnant in Baa'ri, Oronu der Älteste, erhält täglich schriftliche Befehle von Akama. Besorgt sie Euch und bringt sie mir.", progress = "Gibt es schon Neuigkeiten, <Name>? Wir haben nicht viel Zeit.", completion = "Akamas Handschrift... wollen wir mal sehen, was wir daraus erfahren können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10685] = {title = "Die Verderber der Aschenzungen", objective = "Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal zurück.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Laut Akamas Brief wurden vier Teile des Medaillons ausgegraben und den Verderbern der Aschenzungen übergeben. Diese gefürchteten Zerschlagenen waren einst mächtige Schamanen, die nun die Elemente schänden, die sie einst verehrten.\n\nHaalum, der Verderber der Luft, befindet sich am Netherschwingenpass. Eykenen und Uylaru, die Verderber der Erde und des Feuers, wurden zuletzt bei den Teufelsgruben in der Nähe der Hand des Gul'dan gesehen. Lakaan, der Verderber des Wassers, soll sich in der Nähe der Echsennarbe aufhalten.\n\nFindet sie und besorgt Euch die Medaillonfragmente von ihnen.", progress = "Habt Ihr die vier Fragmente des Medaillons, <Name>?", completion = "Ja! Die vier Fragmente des Medaillons. Und nun setzt sie zusammen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10686] = {title = "Der Kerker des Wächters", objective = "Arkanist Thelis möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru über Akamas Aufenthaltsort befragt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Die Fragmente, die Ihr besorgt habt, sind nur eine Hälfte des Amuletts. Der Anführer der Aschenzungen, Akama, muss die andere Hälfte haben.\n\nIch wage es fast nicht, Euch darum zu bitten, da Akama sowohl böse als auch gerissen ist.\n\nEr und die Todeshörigen der Aschenzungen - die bösartigsten und grausamsten der Zerschlagenen -  sollen irgendwo im Kerker des Wächters eine Folterkammer betreiben.\n\nIch möchte, dass Ihr dieses gefürchtete Gefängnis findet und Akamas Aufenthaltsort bestimmt. Sein Stellvertreter vor Ort ist ein Zerschlagener namens Sanoru. Befragt ihn, wenn Ihr müsst.", progress = nil, completion = "Wir haben Euch erwartet, &lt;Name&gt;. Akama sagte, dass Ihr früher oder später kommen würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10687] = {title = "Ausbildungsgelände von Karabor", objective = "Larissa Sonnenhieb beim Sanktum der Sterne möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, nordöstlich des Sanktums der Sterne, beschafft.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Unsere Späher haben uns von einem massiven Zufluss von Blutelfenrekruten des Sonnenzorns in den Ruinen von Karabor berichtet. Normalerweise würden wir darin eine rein militärische Bedrohung sehen, doch wir glauben, dass hier noch mehr im Argen liegt.\n\nDie Beschreibungen ihrer Kleidung und ihres Kampfstils klingen verdächtig nach Illidan selbst. Ich will mich nicht ohne handfeste Beweise beunruhigen, daher möchte ich Euch bitten, dorthin zu gehen und mir ihre Waffen zu bringen. Dann werden wir sehen, ob meine Befürchtungen unbegründet sind oder nicht.", progress = "Habt Ihr die Aufgabe, mit der ich Euch betraut habe, erfüllt, <Name>?", completion = "Wollen wir uns diese Waffen einmal genauer ansehen, &lt;Name&gt;. Hmmm... das ist ziemlich beunruhigend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10688] = {title = "Eine notwendige Ablenkung", objective = "Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Die Waffen sind echt, wie wir befürchtet haben. Illidan bildet in den Ruinen von Karabor Dämonenjäger aus. Das müssen wir verhindern.\n\nLasst Euch nicht von dem Namen täuschen, <Name>. Sie werden ihre Macht genauso oft gegen uns einsetzen, wie gegen Dämonen.\n\nIhre Hexenmeister beschwören und unterwerfen Dämonen im Rahmen der Ausbildung der Initiierten. Ein Grubenlord namens Azaloth hat sich in der Ausbildung als zu mächtig erwiesen und wird nun unter Verschluss gehalten. Findet einen Weg, ihn frei zu lassen und auf seine Kerkermeister zu hetzen. Das sollte uns die nötige Zeit verschaffen.", progress = nil, completion = "Das sollte uns genug Zeit verschaffen... hoffentlich reicht sie aus, um weitere Informationen zu sammeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10689] = {title = "Altruis", objective = "Reist in den Westen Nagrands und sucht Altruis den Leider.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Heutzutage trifft man nur noch selten auf Dämonenjäger. Ihr eigenes Volk begegnet ihnen mit Argwohn. Und noch seltener findet man einen Dämonenjäger, der nicht im Bund mit Illidan steht.\n\nGerüchten zufolge soll ein solches Wesen hier in der Scherbenwelt leben. Sein Name ist Altruis. Er hasst alle Dämonen mit Leidenschaft und wird uns helfen, wenn Ihr ihn davon überzeugen könnt, dass wir auf seiner Seite stehen.\n\nGeht in den Westen Nagrands und sucht ihn. Vielleicht ist er bereit, etwas mehr über diese neuen Ausbildungsgelände für Dämonenjäger zu erzählen.", progress = nil, completion = "Ihr habt einen langen Weg hinter Euch, Fremder. Ich bin überrascht, dass derjenige, der Euch zu mir geschickt hat, von mir gehört hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10690] = {title = "Die Höhlenmutter", objective = "Tötet Rema.", description = "GESUCHT!\n\nRema, die Mutter und wichtigste Verteidigerin des Zackengrats südlich der Donnerfeste.\n\nIhr findet sie, indem Ihr das Dorf Richtung Osten verlasst und die Brücke über die Blutschlägerklamm überquert. Sie versteckt sich im Tunnel am südlichen Ende des Grats.\n\nKehrt mit den Nachrichten über Ihr Ableben zu Kommandant Himmelsschatten in Sylvanaar zurück.", progress = "Was kann ich heute für Euch tun?", completion = "Unglaublich. Habt Ihr Rema ganz alleine getötet?\n\nSo wie Ihr ausseht, glaube ich das. Wisst Ihr, wir sind auf der Suche nach einem starken &lt;Klasse&gt; wie Ihr es seid, um uns hier ein wenig zu helfen. Besonders bei den ständigen Problemen, die wir mit den Ogern haben, könnten wir Euch brauchen. Setzt Euch mit mir in Verbindung, wenn Ihr Interesse habt.\n\nDas Kopfgeld, das auf dem Anschlag versprochen wurde, habt Ihr Euch jedenfalls verdient.\n\nBitte, wählt Euch etwas aus!", rewards = "Schwerer ElfenlangdolchAxt des WolfschlägersArkanzauberstab von SylvanaarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10691] = {title = "Rückkehr zu den Sehern", objective = "Sprecht mit Larissa Sonnenhieb beim Sanktum der Sterne im Schattenmondtal.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Dieses Buch... könnte meine Macht verzehnfachen... Nein! Es würde meine Seele verderben, ich weiß es genau. Bringt es zurück zu denen, die Euch hierher geschickt haben, <Name>.\n\nIhr habt nun die Mittel, um Varedis aufzuhalten. Wartet, bis er sich mithilfe der Metamorphose in seiner dämonischen Form manifestiert. Genau in diesem Moment müsst Ihr das Buch in seiner Anwesenheit verbrennen. Nur so könnt Ihr ihn seiner Macht berauben.", progress = nil, completion = "Viele würden für das Buch, das Ihr bei Euch tragt, einen hohen Preis bezahlen. Es ist eine Schande, dass wir es zerstören müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10692] = {title = "Varedis muss aufgehalten werden", objective = "Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Larissa Sonnenhieb zurück.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Wir müssen dieses abscheuliche Artefakt zerstören, jedoch nicht, bevor wir damit Varedis seiner Mächte beraubt haben.\n\nWir müssen diese Akademie von Illidanimitatoren auslöschen. Dazu müsst Ihr nicht nur Varedis töten, sondern auch seine drei Nachtelfenmeister, die ihn unterstützen: Alandien, Theras und Netharel.\n\nStellt eine geeignete Truppe zusammen und kehrt zu den Ruinen von Karabor zurück. Befolgt Altruis' Anweisungen, um Varedis zu besiegen. Ich hoffe für uns alle, dass sie funktionieren. Wenn nicht... war schön, Euch kennengelernt zu haben.", progress = "Habt Ihr die Aufgabe, mit der ich Euch betraut habe, erfüllt, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Euer Sieg über Varedis ist ein entscheidender Schritt in unserem Krieg gegen Illidan.\n\nNach dieser Tat wird euer Name sicher die Runde machen.\n\nBitte erlaubt mir, die Überreste des Buchs der teuflischen Namen an mich zu nehmen. Ich werde dafür sorgen, dass es ordnungsgemäß... entsorgt wird.", rewards = "Halsberge von KaraborBeinschützer des SonnenzornsBeschwörerklingeWildruferTöteraxtZeremonieller KrisIhr bekommt:\n\n"}
