MultiLanguageQuestData['de'][10701] = {title = "Netherbrock zerschmettern", objective = "Tötet Netherbrock und meldet Euch danach bei Raketenchef Doppeldecker in Area 52 im Nethersturm.", description = "An alle, denen an einer rechtzeitigen Fertigstellung der X-52 Netherrakete gelegen ist:\n\nDer König der hiesigen Bergriesen, Netherbrock, terrorisiert die Schwindenden Weiten! Er behindert Unternehmungen am gesamten südlichen Rand der Insel!\n\nSchließt Euch mit ein paar Freunden zusammen und erledigt ihn! Kehrt dann zu mir hier in Area 52 zurück.\n\nRaketenchef Doppeldecker", progress = nil, completion = "Oh! Oh... Ihr habt Netherbrock erledigt. Das sind gute Nachrichten!\n\nJetzt, da dieser lästige Bergriese von der Bildfläche verschwunden ist, können wir die Rohstoffe der schwindenden Weiten leichter ausbeut... äh, verwalten.\n\nIch bin froh, dass diese armen, unschuldigen Elementare da unten jetzt nicht mehr von ihm zerquetscht werden.\n\nWie kann ich Euch je dafür entlohnen?", rewards = "Finstere Stiefel von Area 52NetherraketenhandschuheSchulterstücke des RaketenchefsGoblingurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10702] = {title = "Routinearbeiten", objective = "Oberanführer Or'barokh in Schattenmond im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.\n\nDazu gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig.", description = "Alle Streitkräfte der Horde in dieser Gegend sind damit beschäftigt, die Angriffe der Brennenden Legion abzuwehren. Wir haben daher niemanden, der uns die kleinen Routinearbeiten abnimmt.\n\nUnsere Versorgungskarawanen werden regelmäßig von den Wildtieren der Region bedroht. Wir können uns keine 15 Fuß von der Straße entfernen, ohne einer Schimäre, einem Teufelseber oder einem abnormal großen Skorpion in die Fänge zu laufen.\n\nGeht dort hinaus und befreit das Schattenmondtal von seinen sadistischen Wildtieren! Erschlagt sie einfach alle!", progress = nil, completion = "Fantastisch! Wenn ich noch mehr Routinearbeiten zu erledigen habe, komme ich auf Euch zurück!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10703] = {title = "Zieht Eure Knieschoner an...", objective = "Than Yoregar in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.\n\nDarunter gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig.", description = "Es ist an der Zeit, sich im Schlamm zu wälzen und dreckig zu machen. Was habt Ihr denn erwartet? Man muss schließlich laufen lernen, bevor man krabbelt, oder nich'? Ähem, anders 'rum...\n\nEgal, wir haben jedenfalls alle Hände voll mit dem Müll zu tun, mit dem uns die Legion bewirft. Daher wird Euch die Ehre zuteil, die durchgeknallten Wildtiere des Schattenmondtals zu erlegen.\n\nSchnappt Euch Schwert, Stab oder was auch immer Euch glücklich macht, und tötet so viele Wildtiere, wie Ihr könnt. So halten wir den Weg für unsere Versorgungskarawanen frei.", progress = "Kehrt zu mir zurück, wenn unsere Karawanen sicher durch die Wildnis kommen!", completion = "Jap, gute Arbeit! Hier habt Ihr ein wenig Bares für Eure Mühen. Wenn ich noch mehr Drecksarbeit zu erledigen habe, weiß ich ja, wen ich rufen soll.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10704] = {title = "Wie man in Arkatraz einbricht", objective = "A'dal bittet Euch, das obere und das untere Fragment des Schlüssels zur Arkatraz zu besorgen. Bringt beide Fragmente zu ihm zurück, damit er sie für Euch zum Schlüssel zur Arkatraz zusammenfügen kann.", description = "In dem Kristall von Ata'mal, den Ihr uns gebracht habt, war eine Nachricht versteckt. Nexusprinz Haramad hat uns dadurch wichtige Informationen für unsere Vorgehensweise gegen die Festung der Stürme zukommen lassen.\n\nEr berichtet, dass es einen zweiteiligen Schlüssel gibt, mit dem man den Satellit Arkatraz der Festung aufschließen kann.\n\nDie eine Hälfte des Schlüssels befindet sich im Besitz eines Urtums namens Warpzweig in der Botanika. Der zweite Teil wird von Panthaleon dem Kalkulator in der Mechanar bewacht.\n\nBringt mir beide Fragmente, damit ich den Schlüssel zur Arkatraz zusammensetzen kann.", progress = "<A'dals Stimme summt melodisch in Eurem Geist.>\n\nIhr seid zurück. Habt Ihr die beiden Fragmente des Schlüssels zur Arkatraz bei Euch?", completion = "Ich bin beeindruckt, &lt;Name&gt;, auch wenn ich von dem Helden, der den Kristall von Ata'mal zurückgebracht hat, nichts anderes erwartet habe.\n\nGebt mir die Fragmente, damit ich sie zu ihrer endgültigen Form zusammenfügen kann. Dann werdet Ihr Zugang zur Arkatraz haben.", rewards = "Verteidigertaillenschutz der Sha'tariA'dals GabeChampiongürtel von ShattrathPräzisionsgürtel der NaaruAnachoretenumhang der Sha'tariIhr bekommt:\n\nSchlüssel zur Arkatraz"}
MultiLanguageQuestData['de'][10705] = {title = "Seher Udalo", objective = "Sucht Seher Udalo in der Arkatraz in der Festung der Stürme.", description = "Ich hoffe, Ihr seid nicht schockiert, wenn ich Euch verrate, dass die Teile des Medaillons von Karabor, die Ihr von meinen Dienern beschafft habt, nichts als Nachbauten sind.\n\n<Akama zeigt Euch ein identisches Medaillon, das auf seiner Handfläche liegt.>\n\nMeine Todeshörigen haben dieses Geheimnis so lange wie möglich von Illidan bewahrt. Dennoch fehlt uns noch das letzte Stück.\n\nSeher Udalo erschien mir in meinen Träumen und sagte mir, dass er das letzte Stück gefunden habe. Er wird jedoch von Kael'thas auf der Arkatraz in der Festung der Stürme gefangen gehalten. Sucht ihn und findet heraus, was er weiß.", progress = nil, completion = "Der Seher der Aschenzungen ist schon lange tot. Als Ihr Euch über seinen Körper beugt, erkennt Ihr, dass auf dem Boden etwas geschrieben steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10706] = {title = "Ein mysteriöses Omen", objective = "Kehrt zu Akama im Kerker des Wächters im Schattenmondtal zurück.", description = "Bevor er starb, hat Udalo noch ein einzelnes Wort auf den Boden unter sich geschrieben. Die Schrift ist kaum lesbar, aber Ihr erkennt das Wort 'Ata'mal'.\n\nVielleicht versteht Akama die Nachricht seines Bruders.", progress = nil, completion = "Ja... natürlich! Jetzt wird alles klar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10707] = {title = "Die Terrasse von Ata'mal", objective = "Begebt Euch zur Spitze der Terrasse von Ata'mal im Schattenmondtal und beschafft das Herz des Zorns. Kehrt danach zu Akama beim Kerker des Wächters im Schattenmondtal zurück.", description = "Wir haben herausgefunden, dass die Höllenorcs unter Illidans Kommando bei der Terrasse von Ata'mal einen Kristall von Ata'mal, der als Herz des Zorns bekannt ist, aufbewahren. Sie verschleiern seine Präsenz mit einer dunklen Magie, um ihn vor den Sha'tar zu verstecken.\n\nKämpft Euch zur Terrasse von Ata'mal außerhalb des Schwarzen Tempels durch und blickt zum Himmel. Schattenfürst Todesklage kreist außerhalb Eurer Reichweite um die Terrasse herum. Ihr müsst ihn und seine Hexenmeister töten, bevor Ihr an den Kristall kommt.\n\nEs wird nicht einfach werden, <Name>. Ich wünsche Euch Glück.", progress = "Ihr seid zurück, <Name>.", completion = "Der Kristall! Seine Macht... in meinen Händen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10708] = {title = "Akamas Versprechen", objective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, <Name>. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, <Name>. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Akamas SchärpeTiefgrüne HandschuheRundschild des ZauberbrechersKlinge der AschenzungenGewehr des BlutwärtersTodeshörigenstab der AschenzungenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10709] = {title = "Zusammenführung", objective = "Sprecht mit Rexxar in der Donnerfeste im Schergrat.", description = "Ihr kommt also aus der Welt jenseits des Portals? Und Ihr kennt Rexxar. Oh ja, auch ich kenne ihn sehr gut.\n\nEr ist mein Sohn.\n\nAber er hat seine Entscheidung vor langer Zeit getroffen. Er ist keiner von uns und hier nicht willkommen. Wir haben genug Probleme mit den Ogern der Totschläger.\n\nIhr müsst eines wissen: ein Halbblut zu sein macht niemanden zu einem Mok'Nathal.", progress = nil, completion = "Mein Vater ist also tatsächlich am Leben. Ich habe nicht erwartet, dass er mir verzeiht. Das war noch nie seine Art. Aber ich hatte gehofft, dass seine Wut über meine Abreise über die Jahre schwächer geworden ist.\n\nVor dreißig Jahren habe ich die Mok'Nathal verlassen, um der Horde nach Azeroth zu folgen. Leoroxx war strikt dagegen, gab mir aber auch keinen Grund zu bleiben. Und doch hätte ich mir ein herzlicheres Willkommen gewünscht.\n\nEr wollte einen Mok'Nathal als Sohn haben und hat immer noch einen, auch wenn er nichts davon wissen möchte.\n\nIch werde ihm die Augen öffnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10710] = {title = "Testflug: Der Singende Bergrücken", objective = "Unterzeichnet Tallys Haftungsausschluss und sprecht mit Rally Zapschnapper, um das Zephyriumkapazitorium zu benutzen.", description = "Ich habe ein wenig an dem Zephyriumkapazitorium herumgebastelt und bin bereit für einen weiteren Test! Wollt Ihr mir helfen?\n\nDieser nächste Flug sollte kurz, aber schnell sein!\n\nÄh... und obwohl ich mir sicher bin, dass es nicht gefährlich wird... habe ich hier diesen Haftungsausschluss, den Ihr bitte unterschreiben möchtet. Nur eine Formalität, kein Grund zur Sorge!\n\nViel Glück! Sprecht mit Rally, wenn Ihr zum Abschuss bereit seid und kehrt zu mir zurück, wenn das Experiment vorbei ist!", progress = "Keine Sorge, <Name>! Sorgen haben noch niemandem weitergeholfen!", completion = "Wow! Ihr habt schon wieder überlebt! Ich bin ein besserer Ingenieur, als ich immer dachte!\n\nHier ist Eure Bezahlung! Und schaut doch später nochmal bei mir vorbei... Ich habe noch mehr Experimente, für die ich Versuchspersonen brauche!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10711] = {title = "Testflug: Razaans Landeplatz", objective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium.", description = "<Name>, ich habe die Effizienz des Zephyriumkapazitoriums um 30 Prozent gesteigert! Ein Versuchsobjekt von Eurem Gewicht wird dann Dank des Luftreibungsverhältnisses in ungeahnte Höhen geschleudert! Wollt Ihr meine Theorie testen? Dieses Experiment sollte Euch in die Nähe von Razaans Landeplatz schicken.\n\nSprecht mit Rally... er wird Euch für den Abschuss vorbereiten.", progress = "Was? Ihr wollt das Experiment nicht durchführen? Nicht kneifen, <Name>! Ich bin die ganze Zeit hinter Euch!", completion = "Oh, beeindruckend! So schnell schon zurück! Ich habe gesehen, wie Ihr abgehoben habt und wie eine Rakete in die Luft geschossen seid! Ich dachte, es würde mindestens einen Monat Genesung brauchen, bis Eure gebrochenen Beine wieder geheilt sind! Ihr seid hart im Nehmen, mutig und kühn! Aber vor allem... mutig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10712] = {title = "Testflug: Ruuanwald", objective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Lasst auf Eurem Flug die Netherwetterfahne rotieren. Bringt die rotierende Netherwetterfahne zu O'Mally Zapschnapper im Ewigen Hain.", description = "He <Name>! Gut, dass ich Euch treffe! Ich habe einen sehr wichtigen Auftrag für Euch.\n\nDas hier ist eine Netherwetterfahne. Ich möchte, dass Ihr während des Flugs ein paar Aufzeichnungen macht und sie zu meinem Vetter im Ruuanwald bringt.\n\nSprecht mit Rally und nehmt einen Flug mit dem Zephyriumkapazitorium zum Ruuanwald. Lasst während dem Flug die Fahne rotieren!\n\nBringt nach Eurer Landung die rotierende Fahne zu O'Mally Zapschnapper.\n\nViel Glück, <Name>. Und trödelt nicht!", progress = "Hallo hallo! Mein Klo... äh... mein Vetter Tally hat mir gesagt, dass Ihr vorbeikommen würdet. Habt Ihr etwas für mich?", completion = "Oh, Ihr habt Aufzeichnungen mit der Netherwetterfahne gemacht? Ausgezeichnet! Die Daten dieses Instruments werden zusammen mit meinen Messungen druidischer Magie sicher viele Früchte tragen!\n\nOh, die Einsatzmöglichkeiten werden Euch um den Verstand bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10713] = {title = "...und Zeit zu Handeln", objective = "Tötet 10 Roder des Wyrmkults.", description = "Wir werden nicht tatenlos zusehen, wie sie den Ruuanwald um uns herum ausrotten. Unser höchstes Augenmerk muss den Bäumen gelten.\n\n<Klasse>, ich möchte, dass Ihr in den Wald geht, und eine ganz besondere Nachricht von uns übermittelt. Ich möchte, dass Ihr jeden einzelnen ihrer Roder, dem Ihr begegnet, tötet.\n\nWenn sie nicht auf vernünftige Argumente hören möchten, dann vielleicht auf schlagkräftige.", progress = "Habt Ihr die Bäume geschützt? Habt Ihr die Roder gefällt?", completion = "Danke, &lt;Name&gt;.\n\nWir werden uns darum kümmern, dass die Wildtiere sich selbst wieder schnell vermehren. Bei den Bäumen ist dies jedoch ein sehr viel zeitaufwändigerer Prozess.", rewards = "Handschuhe des EinschlagsGürtel des BaumhütersArmschienen des WaldesVerteidigerschultern der ExpeditionIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10714] = {title = "Auf geisterhaften Schwingen", objective = "Sucht einen Zuchtmeister der Blutschläger und einen Sterndeuter der Blutschläger, die sich gerade unterhalten. Benutzt Rexxars Pfeife, um Geisterschwinge zu rufen und sie durch ihn zu belauschen.", description = "Wenn die Mok'Nathal von den Ogern der Blutschläger tyrannisiert werden, werde ich sie und ihre Anhänger aufhalten. Oger sind einfach gestrickte Wesen. Die Mok'Nathal zu belästigen bringt ihnen keine besonderen Vorteile.\n\nEs muss mehr dahinter stecken, <Name>. Nehmt Geisterschwinge, meinen Falken, und belauscht die Gespräche der Anführer der Blutschläger. Er wird unbeobachtet bleiben, wo Ihr auffallen würdet.", progress = "Was habt Ihr erfahren, <Name>?", completion = "&lt;Geisterschwinge lässt sich auf Rexxars Schulter nieder, während Rexxar aufmerksam zuhört.&gt;\n\nDie Söhne des Gruul stecken also hinter den Handlungen der Oger. Sie befehlen den Ogern der Blutschlägern, die Mok'Nathal zu vernichten, um ihre Gunst zu erlangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10715] = {title = "In die Grabenschlucht", objective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", description = "Euer Rexxar möchte also, dass ich ein Gift für ihn herstelle? Ich werde ihm geben, was er sich wünscht, aber das hat einen Preis, den auch Freunde bezahlen müssen.\n\nZunächst müsst Ihr einen kurzen Weg nach Südwesten in die Grabenschlucht zurücklegen.\n\nDort leben ein paar der giftigsten Kreaturen der ganzen Scherbenwelt, wenn nicht die giftigsten überhaupt. Ich spreche von den Krustenbohrern. Wenn Ihr ein Gift wollt, müsst Ihr ein paar Ihrer Drüsen für mich sammeln.", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", rewards = "Ihr bekommt:\n\nBlutbeulengift"}
MultiLanguageQuestData['de'][10716] = {title = "Test Flight: Raven's Wood <needs reward>", objective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück.", description = "Das Zephyriumkapazitorium ist für seinen bisher längsten Flug bereit! Was meint Ihr, <Name>? Wollt Ihr noch einmal fliegen?\n\nIch habe das Antriebssystem verbessert, aber bis ich die passenden Einstellungen gefunden habe, werden wir zusätzlichen Treibstoff brauchen, um ihm den richtigen Kick zu geben! Sprecht vor dem Flug mit Rally, er hat die Einzelheiten.\n\nViel Glück, <Name>. Dieser Flug wird Euch zum weit entfernten Rabenwald bringen. Wenn Ihr ihn überlebt - und die Oger und Arakkoa des Waldes - kommt zu mir zurück, damit wir feiern können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10717] = {title = "Wilderer wildern", objective = "Beschafft Euch 5 Netze des Wyrmkults.", description = "Verzeiht, aber ich konnte nicht umhin, Euer Gespräch mit Chawn mitzuhören. Ich würde gerne helfen.\n\nIch stelle Nachforschungen über den Pechschwingenkoven an und helfe den Druiden, mit ihnen fertigzuwerden.\n\nIch bin sehr daran interessiert, an ein paar ihrer Welplinge zu kommen. Um einen Feind wirklich verstehen zu können, muss man lernen, was er verehrt.\n\nAber zunächst bräuchten wir ein paar Netze. Die Wilderer des Wyrmkults draußen im Ruuanwald haben eine ganze Menge davon.", progress = "Wie geht es mit der Beschaffung der Netze voran? Meiner Einschätzung nach sind diese Netze der Wilderer stark genug, um unserer Sache dienlich zu sein.", completion = "Oh, die sehen hervorragend aus. Diese Kultisten wissen wirklich, was wahre Handwerkskunst ist.\n\nZu schade, dass sie sie missbrauchen.\n\nJetzt, da wir die Netze haben, bräuchte ich Eure Hilfe bei ein oder zwei Angelegenheiten. Habt Ihr Lust?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10718] = {title = "Die Stimme der Geister", objective = "Sprecht mit Rexxar in der Donnerfeste im Schergrat.", description = "<Name>, jetzt, da Ihr mich sehen könnt, müsst Ihr Rexxar etwas von mir ausrichten. Ich weiß, dass er sein Volk sucht und ich weiß auch, wo es ist.\n\nDie Mok'Nathal haben ein Dorf im Osten, hinter dem Messergrat.\n\nGeht und bringt Rexxar diese Nachricht. Sein Volk ist in Gefahr! Ich weiß, dass er ihnen sehr gerne helfen würde.", progress = nil, completion = "Wovon redet Ihr?\n\nGarm Wolfsbruder? Er war der letzte Häuptling der Donnerfürsten. Wenn Ihr mit seinem Geist gesprochen habt, muss es wahr sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10719] = {title = "Ihr seid eingeladen!", objective = "Bringt die Einladung zum Treffen zu Baumhüter Chawn im Ewigen Hain im Schergrat.", description = "Der Kultist hat diese Einladung fallenlassen, die offensichtlich an Aufseher Nuaar übergeben werden sollte. Sie ist mit dem Namen Kolphis Dunkelschuppe unterzeichnet.\n\nBaumhüter Chawn wäre sicher sehr interessiert daran.", progress = "Was habt Ihr da? Ist da ein Blutfleck auf der Einladung?", completion = "Das ist interessant, aber auch beunruhigend. Vielleicht sollten wir Samia fragen, wer dieser Kolphis Dunkelschuppe ist?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10720] = {title = "Die kleinsten Wesen", objective = "Begebt Euch zum Murmeltierbau und schlagt die Kodobalgtrommel. Vergiftet die drei Fässer im Lager der Blutschläger, während Ihr das Murmeltier kontrolliert.", description = "So einfältig sie auch sein mögen, würde es den Ogern auffallen, wenn Ihr dieses Gift in ihrem Lager verteilt. Daher will ich Euch beibringen, wie man die Hilfe eines der kleinsten Wesen in der Natur für diese Aufgabe in Anspruch nehmen kann.\n\nWenn Ihr einen einfachen Rhythmus auf dieser Trommel spielt, könnt Ihr ein Murmeltier so beeinflussen, dass es Euren Befehlen gehorcht.\n\nIn der Nähe des Lagers der Blutschläger gibt es einen Murmeltierbau. Er befindet sich im Norden in der Dolchrachenklamm hinter dem Zirkel des Blutes.\n\nBenutzt ein Murmeltier dazu, das Gift in den Fässern der Blutschläger zu verteilen, sobald Ihr es beeinflussen könnt.", progress = "Ist es vollbracht?", completion = "Viele Jahre lang habe ich versucht, die Kommunikation mit der Natur zu perfektionieren. Dies ist nur ein Bruchteil dessen, was die Tiere für Euch tun können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10721] = {title = "Grulloc einen Eber aufbinden", objective = "Beschafft Euch Grullocs Sack.", description = "<Name>, ich habe einen Eber namens Grummel als Haustier. Er möchte Euch dabei helfen, ein wenig Spaß mit einem der Söhne Gruuls in der Nähe zu treiben.\n\nGrulloc lebt an einem Ort namens Verfluchtes Dunkel. Begebt Euch dorthin und lasst Grummel dann frei. Der Gronn wird es lustig finden, ihn umher zu jagen. Ihr könnt in der Zwischenzeit den Sack, den er bewacht, stehlen und zu Baron Zobelmähne beim Zirkel des Blutes bringen.\n\nIhr gelangt zum Verfluchten Dunkel, indem Ihr den nördlichen Pfad hinunter geht und dann nach Osten durch Drachenend hindurch geht. Das Dunkel befindet sich am östlichen Rand.", progress = "So schnell schon zurück? Seid Ihr hier, um Rexxars Schulden zurückzuzahlen?", completion = "&lt;Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.&gt;\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun, da der Preis bezahlt ist, werde ich Rexxar geben, was er begehrt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10722] = {title = "Treffen am Pechschwingenkoven", objective = "Sammelt genügend Gewandfetzen von verschiedenen Wyrmkultisten, um eine Aufseherverkleidung herzustellen. Benutzt die Verkleidung, um am Treffen mit Kolphis Dunkelschuppe teilzunehmen.", description = "Ich weiß, was zu tun ist! <Name>, Ihr müsst Euch als Aufseher Nuaar ausgeben und an diesem Treffen teilnehmen!\n\nDie Wyrmkultisten tragen alle ein Standardgewand. Sammelt ein paar Fetzen davon. Wenn Ihr genügend zusammen habt, können wir eine Verkleidung herstellen, in der Ihr an dem Treffen teilnehmen könnt.\n\nSprecht mit Kolphis Dunkelschuppe und hört Euch an, was er zu sagen hat. Kehrt danach zu mir zurück.\n\nIhr findet den Koven indem Ihr durch den Tunnel des Wyrmschädels geht und dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende folgt.", progress = nil, completion = "Uns angreifen? Uns auslöschen? Das glaube ich aber nicht!\n\nDieser Pechschwingenkoven muss noch viel lernen, wenn sie denken, dass man die Expedition des Cenarius so leicht loswerden kann!\n\nWie sagt man so schön? Wie du mir, so ich dir!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10723] = {title = "Gorgrom der Drachenfresser", objective = "Sammelt 3 grausige Totems von den Ogern von Fels'mok. Stellt danach Zobelmähnes Falle bei Gorgroms Altar auf, um Gorgrom den Drachenfresser zu rufen, und tötet ihn.\n\nWenn Gorgrom tot ist, platziert die drei grausigen Totems in der Nähe seiner Leiche.", description = "Der Gronn, den wir suchen, heißt Gorgrom der Drachenfresser. Mit Zobelmähnes Falle werdet Ihr ihm kurzen Prozess machen können. Ihr könnt ihn wahrscheinlich antreffen, wenn er die Opfer der Oger von Fels'mok entgegen nimmt.\n\nFolgt der Straße, die nach Norden vom Zirkel des Blutes weg führt, und wendet Euch dann beim Ruuanwald nach Westen. Durchquert danach den Tunnel nach Nordwesten.\n\nTötet zunächst die Oger, um an ihre Köpfe zu kommen. Stellt danach die Falle bei Gorgroms Altar auf und wartet auf seine Ankunft. Tötet ihn und stellt dann die Köpfe als grausige Totems um seine Leiche herum auf. Diese Nachricht sollte man nicht missverstehen können.\n\nNehmt den Bären mit!\n\n<Misha knurrt.>", progress = "Die Oger der Blutschläger werden uns nie mehr belästigen, wenn Ihr Eure Aufgabe erfüllt habt.", completion = "Die Oger der Blutschläger und ihr Meister, Gorgrom, werden die Mok'Nathal nie wieder belästigen.\n\nIch mache mir jedoch Sorgen über die Auswirkungen unserer Tat auf die anderen Gronn. Ich glaube, wir müssen diesem Kampf ein für allemal ein Ende setzen.", rewards = "Sirrendes SchwertGezahnte AxtStab des SchiedsrichtersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10724] = {title = "Gefangener der Speerspießer", objective = "Tötet die Oger der Speerspießer, um an den Wyvernkäfigschlüssel zu kommen. Sobald Ihr ihn habt, benutzt Geisterschwinges Pfeife, um Geisterschwinge zu rufen, der den Käfig öffnen wird, um Leokk zu befreien.", description = "Kurz nach meiner Ankunft in den Bergen wurde ich von einer Gruppe von Ogern der Speerspießer angegriffen.\n\nIch konnte mich zwar freikämpfen, doch sie haben es geschafft, meinen Wyvern Leokk zu entführen. Geisterschwinge hat ihn gefunden. Er wird in der Mitte des Lagers der Speerspießer außerhalb von Gruuls Unterschlupf in einem Käfig gefangen gehalten.\n\nEiner der Oger muss den Schlüssel dazu haben. Findet ihn, dann kann Geisterschwinge damit Leokks Käfig öffnen.\n\nDas Lager liegt dort unten am nördlichen Ende der Dolchrachenklamm.", progress = "Es wäre schön, Leokk wieder an meiner Seite zu wissen.", completion = "Leokk hat uns den Kopf eines schwarzen Drachen von Drachenend gebracht, damit können wir Goc, den Gronn, der ihn gefangen genommen hat, erzürnen und ihn in die Schlacht locken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10725] = {title = "Geachtet vom Violetten Auge", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, <Name>. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", progress = "Seid gegrüßt, <Name>! Es ist mir eine Freude, Euch wieder zu sehen.", completion = "Euer Siegelring ist nun so mächtig wie der eines jeden Erzmagiers des Rats. Tragt ihn immer an Eurem Finger, damit die Eingeweihten Eure Zugehörigkeit zu uns erkennen können. Möge seine Macht Euch immer so gut dienen, wie Ihr uns gedient habt!", rewards = "Ihr bekommt:\n\nViolettes Siegel des Erzmagiers"}
MultiLanguageQuestData['de'][10726] = {title = "Geachtet vom Violetten Auge", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, <Name>. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", progress = "Seid gegrüßt, <Name>! Es ist mir eine Freude, Euch wieder zu sehen.", completion = "Euer Siegelring ist nun so mächtig wie der eines jeden Erzmagiers des Rats. Tragt ihn immer an Eurem Finger, damit die Eingeweihten Eure Zugehörigkeit zu uns erkennen können. Möge seine Macht Euch immer so gut dienen, wie Ihr uns gedient habt!", rewards = "Ihr bekommt:\n\nViolettes Siegel des großen Bewahrers"}
MultiLanguageQuestData['de'][10727] = {title = "Geachtet vom Violetten Auge", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, <Name>. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", progress = "Seid gegrüßt, <Name>! Es ist mir eine Freude, Euch wieder zu sehen.", completion = "Euer Siegelring ist nun so mächtig wie der eines jeden Erzmagiers des Rats. Tragt ihn immer an Eurem Finger, damit die Eingeweihten Eure Zugehörigkeit zu uns erkennen können. Möge seine Macht Euch immer so gut dienen, wie Ihr uns gedient habt!", rewards = "Ihr bekommt:\n\nViolettes Siegel des meisterlichen Auftragsmörders"}
MultiLanguageQuestData['de'][10728] = {title = "Geachtet vom Violetten Auge", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, <Name>. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", progress = "Seid gegrüßt, <Name>! Es ist mir eine Freude, Euch wieder zu sehen.", completion = "Euer Siegelring ist nun so mächtig wie der eines jeden Erzmagiers des Rats. Tragt ihn immer an Eurem Finger, damit die Eingeweihten Eure Zugehörigkeit zu uns erkennen können. Möge seine Macht Euch immer so gut dienen, wie Ihr uns gedient habt!", rewards = "Ihr bekommt:\n\nViolettes Siegel des großen Beschützers"}
MultiLanguageQuestData['de'][10729] = {title = "Der Pfad des violetten Magiers", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10730] = {title = "Der Pfad des violetten Bewahrers", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10731] = {title = "Der Pfad des violetten Auftragsmörders", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10732] = {title = "Der Pfad des violetten Beschützers", objective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10733] = {title = "Der violette Pfad", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt Euren Pfad gewählt, <Klasse>. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", progress = "Schön Euch wieder zu sehen, <Name>.", completion = "Eure Dienste sind eine große Ehre für uns, &lt;Name&gt;. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10734] = {title = "Der violette Pfad", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt Euren Pfad gewählt, <Klasse>. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", progress = "Schön Euch wieder zu sehen, <Name>.", completion = "Eure Dienste sind eine große Ehre für uns, &lt;Name&gt;. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10735] = {title = "Der violette Pfad", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt Euren Pfad gewählt, <Klasse>. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", progress = "Schön Euch wieder zu sehen, <Name>.", completion = "Eure Dienste sind eine große Ehre für uns, &lt;Name&gt;. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10736] = {title = "Der violette Pfad", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt Euren Pfad gewählt, <Klasse>. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", progress = "Schön Euch wieder zu sehen, <Name>.", completion = "Eure Dienste sind eine große Ehre für uns, &lt;Name&gt;. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10737] = {title = "Die Berührung des Meisters", objective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10738] = {title = "Besondere Dienste", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt uns nicht enttäuscht, <Name>. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, &lt;Name&gt;. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10739] = {title = "Besondere Dienste", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt uns nicht enttäuscht, <Name>. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, &lt;Name&gt;. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10740] = {title = "Besondere Dienste", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt uns nicht enttäuscht, <Name>. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, &lt;Name&gt;. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10741] = {title = "Besondere Dienste", objective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", description = "Ihr habt uns nicht enttäuscht, <Name>. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, &lt;Name&gt;. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", rewards = "Ihr bekommt:\n\nViolettes Siegel"}
MultiLanguageQuestData['de'][10742] = {title = "Finale", objective = "Benutzt Rexxars Kampfhorn beim Altar von Goc und tötet Goc.", description = "Jetzt geht es wie folgt weiter. Wir locken Goc von seinem Unterschlupf weg und vernichten ihn. Wenn Goc tot ist, werden die Oger der Speerspießer die Mok'Nathal nie mehr belästigen. Geht zu Gocs Altar außerhalb von Gruuls Unterschlupf und blast dann in mein Horn. Ich werde kommen und zusammen werden wir Gruuls Sohn zur Strecke bringen.", progress = "Nur wenn Goc und Gorgrom der Drachenfresser tot sind, werden die Mok'Nathal frei sein.", completion = "Der Kampf war hart und Ihr habt Euch gut geschlagen, &lt;Name&gt;. Ich bin stolz, dass ich in der Schlacht gegen Goc an Eurer Seite kämpfen durfte.\n\nDie Mok'Nathal sollten von diesen großartigen Siegen erfahren, aber ich bin noch nicht bereit, ihnen gegenüberzutreten. Ich kenne meinen Vater und ich kenne mein Herz. Es gibt immer noch vieles, was ich lernen und tun kann, um stärker zu werden und ihm zu beweisen, dass ich sein wahrer Sohn bin.", rewards = "GrollhufbalggamaschenWachstuchbundhoseTurmalinkroneAugenklappe des ÜbeltätersGeschwärzte BrustplatteLöwenartige BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10744] = {title = "Nachricht vom Sieg", objective = "Kehrt zur Wildhammerfeste zurück und sprecht mit Kurdran Wildhammer.", description = "Ihr müsst sofort Kurdran Wildhammer von unserem Sieg berichten! Seine Leute haben unter Schwadronskommandant Nuainn rund um die Uhr gekämpft, um die Wildhammerfeste zu schützen. Eure Rückkehr wird sie sicher anspornen. Jetzt, da die Bedrohung der Legion aus dem Weg geräumt ist, kann Kurdran sich endlich Illidans Streitkräften widmen. Unsere Stellung hier ist noch lange nicht gesichert, aber wir haben heute einen entscheidenden Sieg errungen.", progress = nil, completion = "&lt;Kurdran hört Euren Bericht an.&gt;\n\nDas sind in der Tat gute Nachrichten! Noch vor ein paar Tagen hätte ich mir nie träumen lassen, dass wir der Belagerung der Legion ein Ende machen könnten.\n\nIhr habt nicht nur ihren Angriff verhindert, sondern auch noch ihre Maschinerie vernichtet! Für diesen Heldenmut habt Ihr den Dank der Wildhämmer, &lt;Name&gt;.", rewards = "Handschuhe des HochmagusAuf Euch wartet eine dieser Belohnungen:\n\nBand der Pein\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10745] = {title = "Nachricht vom Sieg", objective = "Kehrt nach Schattenmond zurück und sprecht mit Oberanführer Or'barokh.", description = "Ihr müsst sofort Oberanführer Or'barokh von unserem Sieg berichten! Jetzt, da wir die Legion geschlagen und ihre Anwesenheit im Schattenmondtal beendet haben, kann der Oberanführer sich endlich unseren anderen Feinden widmen.\n\nAuch wenn die Wache der Kor'kron es nie zugeben würden, werden sie erleichtert sein, nicht mehr an zwei Fronten gleichzeitig kämpfen zu müssen.", progress = nil, completion = "&lt;Der Oberanführer hört Euren Bericht an.&gt;\n\nAusgezeichnete Nachrichten! Den Angriffen der Legion standzuhalten nahm einfach viel zu viele Leute in Anspruch. Ich habe zwar nie geglaubt, dass meine Leute versagen würden, aber sie standen unter großer Belastung.\n\nIhr habt heute bewiesen, wie wichtig Ihr für die Horde seid. Die Wache der Kor'kron wird sich jederzeit geehrt fühlen, an Eurer Seite zu kämpfen.", rewards = "Handschuhe des HochmagusAuf Euch wartet eine dieser Belohnungen:\n\nBand der Pein\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10746] = {title = "DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster", objective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, <Name>.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand des ewigen Weisen"}
MultiLanguageQuestData['de'][10747] = {title = "Welpen des Wyrmkults", objective = "Verwendet das Schwarzwelpennetz, um 10 Schwarzwelpen des Wyrmkults zu fangen.", description = "Wie ich bereits sagte würde es uns helfen, den Kult zu verstehen, wenn wir einige der Welpen, die sie beim Pechschwingenkoven züchten, untersuchen.\n\nSo wie ich das verstanden habe, müssen in ihrem höhlenartigen Lager eine ganze Menge von Welpen herumfliegen. Dort sind auch ein paar Eier, die wahrscheinlich schlüpfen werden, wenn Ihr ihnen zu nahe kommt.\n\nBitte, <Name>, nehmt das Netz und sammelt ein paar davon lebend für mich.\n\nIhr findet den Koven im Westen. Überquert die Brücke des Wyrmschädels und nehmt dann den Tunnel des Wyrmschädels. Folgt dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende.", progress = "Hattet Ihr viel Ärger beim Versuch, die Welpen zu fangen? Ich hoffe, Ihr habt Euch nicht verbrannt!", completion = "Ach herrje, das sind ja mehr, als ich gehofft hatte! Für Euren Heldenmut habt Ihr gewiss ein Lob verdient!\n\nDiese Welpenbrut sieht sehr gut aus. Sie sind wie gemacht für meine Untersuchungen.\n\nBitte, nehmt eine kleine Belohung von mir an. Ich bestehe darauf!", rewards = "Kapuze des WyrmkultistenSchwarzwelpengürtelWelpenschuppenstulpenWeißwas' GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10748] = {title = "Maxnar muss sterben!", objective = "Tötet Maxnar den Aschenmagen.", description = "Sie haben uns keine andere Wahl gelassen, <Name>. Es ist an der Zeit, der Bedrohung am Pechschwingenkoven ein Ende zu setzen. Wir müssen ihren Anführer, Maxnar den Aschenmagen, erschlagen.\n\nIch weiß nicht, ob Ihr ihn schon zu Gesicht bekommen habt, als Ihr dort wart, aber er ist ein Drachkin, halb Mensch, halb Drache. Und er ist ganz schön zäh, also unterschätzt ihn nicht!\n\nErledigt ihn schnell. Mit etwas Glück bringt Ihr so die Sicherheit in den Ewigen Hain und den Ruuanwald zurück.", progress = nil, completion = "Jetzt, da der Anführer unserer Feinde tot ist, können wir endlich wieder ein wenig aufatmen. Und Ihr habt auch noch das gesamte Gebirge vor ihrer Verwüstung bewahrt.\n\nWas auch immer ihre endgültigen Pläne gewesen sein mögen, Ihr habt sie vereitelt!\n\nIhr habt unseren Dank, &lt;Name&gt;. Bitte nehmt dieses Zeichen unserer Wertschätzung sowie unsere ewig währende Gastfreundschaft.", rewards = "Kniehosen des KovensBrustschutz des WyrmkultsDrachkinhemdHelm der PechschwingenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10749] = {title = "Baron Zobelmähnes Gift", objective = "Bringt Baron Zobelmähnes Gift zu Rexxar in der Donnerfeste im Schergrat.", description = "Hier, bringt dies zu Eurem Auftraggeber. Ich bin mir sicher, dass Rexxar es sinnvoll einzusetzen weiß.\n\nOh, und stellt sicher, dass er sich im Klaren ist, dass er mir etwas schuldet.\n\nEr weiß, was ich will. Ich bin mir sicher, dass wir uns - ganz gleich, wie er es zu beschafften gedenkt - schneller wiedersehen werden, als Ihr vielleicht denkt.\n\nJetzt seid ein <braver Junge/braves Mädel> und bringt dies zu Rexxar.", progress = "<Klasse>, so schnell schon zurück? Habt Ihr das Gift?", completion = "Die Verwendung von Giften ist ein dreckiges Geschäft. Aber so werden wir unsere Ziele erreichen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10750] = {title = "Der Pfad der Eroberung", objective = "Reist zum Pfad der Eroberung im Schattenmondtal.", description = "Meine Windreiter sind mit ein paar Neuigkeiten zurückgekehrt, <Name>. Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt weit im Süden und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Windreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10751] = {title = "Den Pfad bereinigen", objective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 10 Zauberbinder der Mondfinsternis.", description = "Wir brauchen mehr Zeit, <Volk>! Ich werde mit den anderen Windreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Windreiter mithilfe der Leuchtpistole der Kor'kron!", progress = nil, completion = "Ihr werdet es nicht glauben, Grunzer!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10752] = {title = "Auf ins Eschental!", objective = "Sprecht mit Raene Wolfsläufer in Astranaar.", description = "Vor Kurzem kam Raene Wolfsläufer aus Darnassus durch Auberdine. Sie war auf dem Weg ins Eschental und murmelte etwas von Furbolgs. Ich hatte keine Gelegenheit, sie genauer dazu zu befragen, aber vielleicht könnt Ihr Euch ja auf die Suche nach ihr begeben und ihr Eure Hilfe anbieten, <Klasse>. Nehmt die südliche Straße aus Auberdine hinaus. Folgt der Straße einfach weiter, sobald Ihr die Grenze zum Eschental erreicht habt. Dort findet Ihr schließlich Astranaar und Raene Wolfsläufer.", progress = nil, completion = "Thundris Windwirker denkt also immer noch, dass man auf mich aufpassen muss? Ich werde ihn wohl daran erinnern müssen, wer hier wen gerettet hat. Er scheint vergessen zu haben, dass ich ihn vor den schlimmsten Übeln bewahrt habe.\n\nNun, da Ihr schon hier seid, &lt;Volk&gt;, habe ich vielleicht doch eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10753] = {title = "Die Verderbnis ausmerzen", objective = "Tötet 4 Wesen der Schuppenflügelteufelsbrut, 4 Wesen der Dolchrachenteufelsbrut und 2 Teufelsverderber.", description = "Die Zahl der Verbrechen, die die Brennende Legion begangen hat, steigt ins Unermessliche. Genau in diesem Moment schickt die Legion wieder ihre Truppen aus, um die Lebewesen dieser Welt heimzusuchen. Sie sind ihrer Macht hilflos ausgeliefert und fallen einer nach dem anderen ihrer Gewalt zum Opfer. <Name>, helft mir dabei, diese Verbrechen gegen die Natur aufzuhalten und vernichtet alles, was von ihrer Verderbnis befallen wurde.\n\nHinter den Bergen im Osten könnt Ihr sehen, wie sich die Verderbnis in der Messerschlucht ausbreitet. Tötet die Verantwortlichen, die Teufelsverderber, und so viele Teufelsanbeter, wie Ihr nur könnt.", progress = nil, completion = "Es erfüllt mich nicht mit Stolz zu zerstören, was Elune erschaffen hat, aber die Verderbnis muss aufgehalten werden. Ihr habt Eure Arbeit gut gemacht, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10754] = {title = "Zugang zur Zitadelle", objective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Danath in der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Danath, der Truppenkommandant der Ehrenfeste, dafür.", progress = "Wollt Ihr mir etwas zeigen, <Name>?", completion = "Kann das wahr sein? Lasst mich die Form einmal genauer betrachten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10755] = {title = "Zugang zur Zitadelle", objective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Nazgrel, der Anführer der Streifkräfte der Horde in Thrallmar, dafür.", progress = "Wollt Ihr mir etwas zeigen, <Name>?", completion = "Eine Schlüsselform? Könnte es das sein, was uns Zugang zu den Zerschmetterten Hallen verschafft?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10756] = {title = "Großmeister Rohok", objective = "Bringt die präparierte Schlüsselform zu Rohok nach Thrallmar auf der Höllenfeuerhalbinsel.", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Rohok, unserem Schmied hier. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", progress = "Was ist das?", completion = "Nazgrel möchte, dass ich einen Schlüssel herstelle? Hat er vergessen, dass wir auf einem Schlachtfeld sind? Es gibt Klingen und Speere zu schmieden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10757] = {title = "Rohoks Bitte", objective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Rohok in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Die Schmiedekunst der Höllenorcs mag nicht gerade die anspruchsvollste sein, aber es ist dennoch Geschick für ihr Handwerk von Nöten. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe?", completion = "Ausgezeichnet. Wollen wir es versuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10758] = {title = "Heißer als die Hölle", objective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Rohok in Thrallmar.", description = "Es klappt nicht, <Name>! Egal wie viele Kohlen ich auf das Feuer lege, die Hitze des Feuers reicht einfach nicht aus.\n\nMir fällt nur noch eine Sache ein, die heiß genug sein könnte, um diesen Schlüssel auf die richtige Temperatur zu bringen, und das ist das Innere eines Teufelshäschers der Legion.\n\nIch habe bisher nur einmal gesehen, wie einer niedergestreckt wurde. Seine Innereien rauchten, brannten und dampften, als er fiel. Nehmt diese Form und haltet sie in einen gefallenen Teufelshäscher. Ich würde Euch empfehlen, ein paar Freunde mitzunehmen, falls Ihr vorhattet, ihn alleine zur Strecke zu bringen.", progress = "Habt Ihr getan, worum ich Euch gebeten habe, <Klasse>?", completion = "Ihr habt es geschafft! Jetzt müsst Ihr sie nur noch ausprobieren.", rewards = "Ihr bekommt:\n\nSchlüssel der Zerschmetterten Hallen"}
MultiLanguageQuestData['de'][10759] = {title = "Findet den Deserteur", objective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", description = "Ich habe das Gefühl, dass alle Teile des Puzzles vor meinen Augen liegen, aber ich kann sie einfach nicht sinnvoll zusammensetzen.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Nordwesten. Wahrscheinlich hat er dort Zuflucht gesucht.", progress = nil, completion = "&lt;Der Arakkoa kichert.&gt;\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10760] = {title = "Das Wrack der Sketh'lon", objective = "Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Unteroffizier Kargrul in Schattenmond.", description = "Das Wrack der Sketh'lon, direkt im Osten, ist ein unheimlicher Ort. Die Peons sind davon überzeugt, dass es dort spukt.\n\nEs gibt dort ein paar Bäume, deshalb haben die Peons keine andere Wahl, als in die Ruinen der Arakkoa zu gehen und Holz zu schlagen. Die Geister der Arakkoa nähren sich an den Arbeitern. Sie saugen ihre Lebensenergie auf und benutzen sie, um ihre verdorbene Magie zu verstärken.\n\nWir müssen herausfinden, was den Dunklen Rat dazu treibt und ihn aufhalten, bevor sein Einfluss überhand nimmt. Durchsucht das Wrack der Sketh'lon nach Hinweisen auf ihre Pläne.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Der Unteroffizier untersucht die Tagebuchseiten.&gt;\n\nHier steht nicht viel Sinnvolles, aber ein paar Einträge könnten sich als nützlich erweisen. Wie es aussieht waren die Arakkoa dabei, ein kompliziertes magisches Ritual vorzubereiten, bis sie starben, aber warum? Hier steht auch etwas Merkwürdiges über einen 'Deserteur'.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10761] = {title = "Findet den Deserteur", objective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", description = "Hier steht nichts, was erklären würde, warum die Geister dieser Arakkoa in dieser Welt zurückbleiben oder wie sie ihren Durst nach Orcblut entwickelt haben.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Süden. Wahrscheinlich hat er dort Zuflucht gesucht.", progress = nil, completion = "&lt;Der Arakkoa kichert.&gt;\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10762] = {title = "Großmeister Dumphry", objective = "Bringt die präparierte Schlüsselform zu Dumphry in der Ehrenfeste.", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Dumphry. Er ist ein Meister seiner Kunst. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", progress = "Was ist das?", completion = "Ein Schlüssel? Danath sollte uns eigentlich an Belagerungsmaschinen arbeiten lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10763] = {title = "Dumphrys Bitte", objective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Dumphry in der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Die Höllenorcs mögen vollkommene Barbaren sein, aber ihre Schmiedekunst ist nicht so primitiv, wie Ihr denken mögt. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe?", completion = "Dann wollen wir es mal versuchen. Mal sehen, was hinter der Schmiedekunst der Orcs steckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10764] = {title = "Heißer als die Hölle", objective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Dumphry in der Ehrenfeste.", description = "Es funktioniert nicht, <Kumpel/Mädel>. Ich kann einfach nicht genug Hitze erzeugen... die Materialien kommen nicht auf ausreichende Temperaturen.\n\nDie Teufelshäscher der Brennenden Legion werden von einem sengenden Kern aus Teufelsfeuer angetrieben, der viel heißer als gewöhnliches Feuer ist.\n\nWenn Ihr genügend Leute zusammentrommeln könntet, um einen davon zur Strecke zu bringen, könntet Ihr die Schlüsselform in dem gefallenen Häscher aufheizen. Aber seid vorsichtig, <Klasse>, diese Teufelshäscher können ganz schön zuschlagen!", progress = "Habt Ihr getan, worum ich Euch gebeten habe, <Klasse>?", completion = "Ihr habt es geschafft, Junge! Jetzt müsst Ihr sie nur noch zur Höllenfeuerzitadelle bringen und ein paar Orcs erlegen!", rewards = "Ihr bekommt:\n\nSchlüssel der Zerschmetterten Hallen"}
MultiLanguageQuestData['de'][10765] = {title = "Wenn Welten kollidieren...", objective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfenkanzlerin aussah. Vielleicht habt Ihr auch schon die kleineren Riesen auf dem Pfad bemerkt. Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10766] = {title = "Invasionspunkt: Katastrophe", objective = "Meldet Euch bei Plexi im Invasionspunkt: Katastrophe.", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Die Wildhammerfeste ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Plexi erwartet Euch bereits am Ankunftsort.", progress = nil, completion = "Es freut mich, Euch kennen zu lernen, &lt;Name&gt;. Mein Name ist Plexi.\n\nIch werde Euch nicht mit Höflichkeiten langweilen. Wir wissen beide, warum wir hier sind. Und nun an die Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10767] = {title = "Invasionspunkt: Katastrophe", objective = "Meldet Euch bei Nakansi im Invasionspunkt: Katastrophe.", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Schattenmond ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Nakansi erwartet Euch bereits am Ankunftsort.", progress = nil, completion = "Ihr müsst derjenige sein, von dem Blutwache Gulmok gesprochen hat. Ich habe bereits einen Plan, aber ich brauche Eure Hilfe, um die Vorbereitungen abzuschließen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10768] = {title = "Wappenröcke der Illidari", objective = "Sammelt 10 Wappenröcke der Illidari.", description = "Die Windreiter müssen nach Schattenmond zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Kor'kron, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, <Volk>?", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10769] = {title = "Zwietracht in den Rängen...", objective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Oberanführer Or'barokh in Schattenmond im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Kor'kron zurück.", description = "Forscher Tiorus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Grunzer ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n&lt;Or'barokh nickt.&gt;\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohung verdient.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErlösungsmal des BeschwörersErlösungsmal des SchlächtersErlösungsmal des ZauberwortsErlösungsmal des Beschützers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10770] = {title = "Kleine Funken", objective = "Moosborke der Uralte möchte, dass Ihr 8 Sengwichtel tötet und danach zu ihm im Ruuanwald zurückkehrt.", description = "Nordöstlich von hier, auf der Ebene über uns, liegt mein altes, zu Asche verbranntes Zuhause. Bevor die Legion ihre Sengwichtel geschickt hat, um uns in Flammen aufgehen zu lassen, stand dort einst ein stattlicher Wald. Dabei sind so viele ums Leben gekommen, dass sich mein altes Herz auch noch Jahrhunderte später nach Rache sehnt. Es sind zu viele von ihnen dort, um das Land tatsächlich zurückzufordern, aber Ihr könntet ihnen vielleicht ein wenig Angst einjagen.\n\nIhr werdet mir doch helfen, oder?", progress = nil, completion = "Es gibt so viele, dass wir sie nie alle töten können, aber Ihr habt mir Hoffnung gegeben. Vielleicht sollte ich noch ein paar Jahrhunderte lang stärker versuchen, meinen geliebten Wald wieder zum Leben zu erwecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10771] = {title = "Aus der Asche", objective = "Moosborke der Uralte möchte, dass Ihr nach Skald reist und Eisenwurzelsamen in drei verschiedene Hügel fruchtbarer Vulkanerde pflanzt. Kehrt danach zu ihm im Ruuanwald zurück.", description = "Wenn Ihr der Straße nach Osten den Berg hinauf folgt und dann nach Norden abbiegt, gelangt Ihr an mein altes Zuhause.\n\nEinst stand dort ein prächtiger Wald, dessen Name schon lange vergessen ist. Doch vor ewigen Zeiten rief die Brennende Legion Sengwichtel und andere Flammenwesen herbei, zerstörte mein Zuhause und zwang mein Volk zu fliehen. Nun bin nur noch ich übrig.\n\nIch habe ein paar Eisenwurzelsamen aufgehoben, die in fruchtbaren vulkanischen Boden gepflanzt werden können. Ihre Magie ist sehr stark. Bitte tut mir diesen Gefallen und ich werde die Schätze längst vergangener Zeiten mit Euch teilen.", progress = "Ist es vollbracht? Habt Ihr etwas Leben in mein altes Zuhause zurückgebracht?", completion = "Ihr habt viele dieser verderbten Kreaturen getötet. Mit dieser Gewissheit kann ich nun etwas ruhiger schlafen.", rewards = "WildholzstabEiserner EichenschildSengholzbogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10772] = {title = "Der Pfad der Eroberung", objective = "Reist zum Pfad der Eroberung im Schattenmondtal.", description = "Meine Greifenreiter sind mit ein paar Neuigkeiten zurückgekehrt! Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt östlich von hier und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Greifenreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10773] = {title = "Den Pfad bereinigen", objective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 5 Söhne des Corok.", description = "Wir brauchen mehr Zeit, <Volk>! Ich werde mit den anderen Greifenreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Greifenreiter mithilfe der Leuchtpistole der Wildhämmer!", progress = "Was habt ihr zu berichten, Soldat?", completion = "Ihr werdet es nicht glauben, Soldat!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10774] = {title = "Blutelf + Riese = ???", objective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfe aussah. Was machen die Riesen überhaupt hier? Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10775] = {title = "Wappenröcke der Illidari", objective = "Sammelt 10 Wappenröcke der Illidari.", description = "Die Greifenreiter müssen zur Wildhammerfeste zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Wildhämmer, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, <Volk>?", progress = "Was habt ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10776] = {title = "Zwietracht in den Rängen...", objective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Than Yoregar in der Wildhammerfeste im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Wildhämmer zurück.", description = "Gnomus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Soldat ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n&lt;Yoregar nickt.&gt;\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohung verdient.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErlösungsmal des BeschwörersErlösungsmal des SchlächtersErlösungsmal des ZauberwortsErlösungsmal des Beschützers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10777] = {title = "Asghars Totem", objective = "Bringt das Kriegstotem der Sketh'lon zu Parshah in den Magmafeldern.", description = "Was im Tagebuch des Kommandanten steht, ist wahr. Während sich die orcische Horde unter Gul'dan sammelte, versuchte mein Volk, diese Bedrohung abzuwenden, indem sie einen Angriff planten. Gul'dan erfuhr jedoch davon und wirkte einen mächtigen Zauber, der unsere Lager zerstörte und die Geister meiner Brüder zerbrach.\n\nSie müssen aufgehalten werden, bevor sie noch mehr Unheil anrichten. Sucht nach Asghar beim Wrack der Sketh'lon im Norden und bringt mir das Totem, das er bei sich trägt. Damit können wir beginnen, die Pläne des Dunklen Rats zu vereiteln.", progress = "Habt Ihr das Totem von Asghar beschafft?", completion = "&lt;Parshah untersucht das Totem.&gt;\n\nGut. Dieses alte Totem hat seine Macht über die Jahre nicht eingebüßt, doch es alleine reicht noch nicht aus, um den Dunklen Rat aufzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10778] = {title = "Die Rute von Lianthe", objective = "Besorgt Euch den Schlüssel von Lianthe von den Blutelfen in der Stätte der Mondfinsternis und benutzt ihn, um die Schließkassette von Lianthe zu öffnen und die Rute von Lianthe an Euch zu nehmen. Bringt die Rute zu Parshah in den Magmafeldern.", description = "Das Totem alleine ist nicht stark genug, um der teuflischen Magie des Dunklen Rats entgegen zu wirken.\n\nWir können es jedoch mit anderen mächtigen Gegenständen zu einem Stab verarbeiten, mit dem wir die Energien bündeln können. Es ist nicht mehr möglich, meine Brüder aus den Tiefen ihrer Verderbtheit zu erretten, aber wir können sie aufhalten.\n\nEiner dieser Gegenstände, den ich benötige, ist die Rute von Lianthe, die sich im Besitz der Blutelfen in der Stätte der Mondfinsternis im Südosten befindet. Sie wird in einem Pavillon ganz oben in den Ruinen aufbewahrt und sehr schwer bewacht. Seid vorsichtig, <Name>.", progress = "Konntet Ihr die Rute beschaffen?", completion = "Gut gemacht. Ein solcher Schatz verdient besseres, als in einer dunklen Kiste weggesperrt zu werden. Wir werden ihn für einen guten Zweck einsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10779] = {title = "Der Pfad des Jägers", objective = "Sprecht mit Kella Nachtbogen auf der Azurmythosinsel.Hallo, junger Jäger. Ihr seht aus, als wärt Ihr bereits tüchtig genug, um ein Tier auszubilden und zu Eurem Begleiter zu machen.\n\nSprecht mit Kella Nachtbogen auf der Azurmythosinsel. Sie kann Euch beibringen, wie man ein eigenes Tier beherrscht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Hallo, junger Jäger. Ihr seht aus, als wärt Ihr bereits tüchtig genug, um ein Tier auszubilden und zu Eurem Begleiter zu machen.\n\nSprecht mit Kella Nachtbogen auf der Azurmythosinsel. Sie kann Euch beibringen, wie man ein eigenes Tier beherrscht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10780] = {title = "Federn der Sketh'lon", objective = "Sammelt 8 Federn der Sketh'lon und bringt sie zu Parshah in den Magmafeldern.", description = "Uns fehlt noch ein letztes Element des Stabs. Wir müssen seine Macht gegen die Geister des Dunklen Rats richten.\n\nDies erreichen wir, indem wir Federn bei den Ruinen des Basislagers der Sketh'lon sammeln und an dem Stab befestigen. Das Basislager befindet sich im Süden, östlich der Wildhammerfeste.\n\nGul'dans Magie hat meine Brüder vernichtet und nur ihre Geister übrig gelassen, doch das war nicht alles. Die Magie hat sich an dem Zauber, den die Arakkoa vorbereiteten, genährt und eine ruchlose Macht erschaffen, die die Geister in ihren Bann gezogen hat.", progress = "Habt Ihr die Federn für den Stab schon gesammelt?", completion = "&lt;Parshah nimmt Euch die aschebestäubten Federn ab und schüttelt den Kopf.&gt;\n\nEs wäre besser gewesen, wenn ich an diesem Tag gestorben wäre, aber die Dinge sind niemals so einfach. Dass Gul'dans Magie sie in etwas verwandelt hat, das sie aufzuhalten versuchten, ist ein grausames Spiel des Schicksals.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10781] = {title = "Die Schlacht an der Purpurwacht", objective = "Bekämpft Illidans Truppen bei der Purpurwacht und überlebt!\n\nKehrt zu A'dal in Shattrath zurück, wenn Ihr als Sieger aus der Schlacht hervorgehen solltet.", description = "Während wir uns hier unterhalten, suchen sie Euch wahrscheinlich auf dem Pfad der Eroberung. Ihr müsst fliehen, <Volk>!\n\nLasst mich zurück, ich bin ohnehin dem Untergang geweiht... Sie... Ich glaube, ich höre sie kommen. Jetzt oder nie! Flieht! Wenn Ihr bleibt, werdet Ihr kämpfen müssen!\n\nWenn Ihr doch kämpft und es irgendwie schafft, zu überleben, berichtet A'dal in Shattrath von dem, was Ihr gesehen habt!", progress = nil, completion = "Wir werden weitere Nachforschungen über das Purpursiegel anstellen. Sie stellen eine Bedrohung für alles Leben in Draenor dar. Ich sehe einen Tag voraus, an dem ihr dunkler Herr für seine Verbrechen geradestehen muss. Vielleicht seid Ihr ja derjenige, der ihn der Gerechtigkeit zuführen wird, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal des Akrobaten der Sha'tarMal des Aggressors der Sha'tarMal des Magiers der Sha'tarMal des Spiritualisten der Sha'tar\n\nIhr bekommt außerdem:\n\nGabe der Sha'tar"}
MultiLanguageQuestData['de'][10782] = {title = "Das Kopfstück mit Magie erfüllen", objective = "Reist zum Altar der Verdammnis und benutzt das unfertige Kopfstück, während Ihr in der Nähe von Gul'dan steht. Kehrt zu Parshah in den Magmafeldern zurück, wenn Ihr das Kopfstück aufgeladen habt.", description = "Der Stab ist fast fertig!\n\nJetzt müssen wir nur nach das Kopfstück mit der Macht von Gul'dans Echo, das durch diesen verfluchten Ort hallt, erfüllen. Im Osten, in der Nähe der Teufelsgruben und südlich der Todesschmiede, befindet sich der Altar der Verdammnis.\n\nDort sind Teile der Vergangenheit gefangen. Wenn Ihr das unfertige Kopfstück des Stabs in die Gegend um den Altar herum bringt, werden einige Wesenheiten darauf reagieren. Seid also auf der Hut. Ihr tragt einen sehr gefährlichen Gegenstand bei Euch, der eng mit der Katastrophe zusammenhängt.", progress = "Seid Ihr mit dem magieerfüllten Kopfstück zurück?", completion = "&lt;Parshah nimmt Euch das Kopfstück ab und hält es behutsam in den Händen.&gt;\n\nDieses Kopfstück enthält die Macht, die wir brauchen, um die Pläne des Dunklen Rats im Basislager der Sketh'lon zunichte zu machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10783] = {title = "Baron Zobelmähne", objective = "Sprecht mit Baron Zobelmähne beim Zirkel des Blutes im Schergrat.", description = "Das ist mein Plan. Wir werden die Oger vergiften und dann ihren Gronnmeister vernichten.\n\nWährend meinen Reisen in diesen Bergen habe ich einen Mann namens Baron Zobelmähne getroffen. Er ist ein Meister der Alchemie und lässt sich vielleicht davon überzeugen, uns zu helfen.\n\nIhr findet ihn beim Zirkel des Blutes, unten in der Schlucht nördlich von hier. Welchen Preis er auch immer verlangen mag, nehmt ihn an!", progress = nil, completion = "Hallo, &lt;Volk&gt;. Ich bin Baron Zobelmähne. Ein Freund Rexxars ist auch mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10784] = {title = "Vernichtet das Lager der Blutschläger!", objective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", description = "<Tor'chunk beugt sich zu Euch herüber und flüstert.>\n\n<Name>, mit Euren Erfolgen im Kampf gegen die Oger bisher habt Ihr uns mehr als stolz gemacht. Und auch wenn ich vollstes Vertrauen in Rexxars Plan habe, möchte ich Euch trotzdem bitten, die Oger im Lager der Blutschläger zu vernichten, bevor Ihr zurückkehrt.\n\nSo können wir unseres Erfolgs doppelt sicher sein.\n\nIhr gelangt in das Lager, indem Ihr den Weg nach Norden aus der Donnerfeste hinausgeht. Wendet Euch am Ende des Steilwegs nach Westen durch Drachenend hindurch und dann nach Norden durch die Grabenschlucht und die Dolchrachenklamm.", progress = nil, completion = "&lt;Tor'chunk nickt und scheint dabei sichtlich zufrieden mit Eurer mörderischen Kühnheit.&gt;\n\nIhr erstaunt mich immer wieder, &lt;Name&gt;. Jedes Mal, wenn einer dieser stinkenden Oger zu Boden geht, sind wir einen Schritt näher daran, einen unwürdigen Feind loszuwerden.", rewards = "Schleichstiefel der DunkelheitSchulterschutz des ZwillingsmondesKettenschlaufengurtSchönwetters HandgelenksschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10785] = {title = "Das ist eine Falle!", objective = "Bringt die Drachenfeuerfalle zu Rexxar in der Donnerfeste im Schergrat.", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nBeeilt Euch und bringt die Falle zu Rexxar. Mein Rachedurst muss gestillt werden!", progress = "Habt Ihr bekommen, was auch immer in diesem Sack des Gronns war? Habt Ihr es Zobelmähne gebracht? Hat er Euch etwas für mich mitgegeben?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10786] = {title = "Gemetzel in Fels'mok", objective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok. Kehrt danach zu Tor'chunk Zweiklaue in der Donnerfeste im Schergrat zurück.", description = "Ich weiß, dass Rexxar Euch nach Fels'mok schicken möchte. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichtemachen!\n\nFels'mok liegt weit im Nordwesten. Reist nach Norden zum Ruuanwald und von dort aus nach Westen durch den Tunnel hinter den Rabenwald.\n\n<Name>, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok tötet. Radiert sie aus!", progress = nil, completion = "&lt;Tor'chunk grinst, als Ihr ihm von Euren Abenteuern in Fels'mok erzählt.&gt;\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, &lt;Name&gt;, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10788] = {title = "Kehrt zu Talionia zurück", objective = "Sprecht mit Talionia in Silbermond.", description = "Einer Eurer Meister, Talionia in Silbermond, schickt nach Euch, <Name>. Ich bin mir sicher, dass für Euch die Zeit gekommen ist zu lernen, wie man einen mächtigeren Dämon beschwört und kontrolliert. Ich schlage daher vor, dass Ihr Euch sofort auf den Weg macht. Wie ich weiß befindet sich Talionia im Sanktum, einer gemütlichen kleinen Hütte des Bösen an der Mördergasse.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10789] = {title = "Rückkehr zu Carendin Halgar", objective = "Sprecht mit Carendin Halgar in Unterstadt.", description = "Ah, da seid Ihr ja, <Name>.\n\nCarendin Halgar schickt nach Euch. Ihr sollt ihn im Magieviertel von Unterstadt aufsuchen. Er ist nicht gerade für seine Geduld bekannt, daher würde ich ihn an Eurer Stelle nicht so lange warten lassen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10790] = {title = "Rückkehr zu Gan'rul Blutauge", objective = "Sprecht mit Gan'rul Blutauge in Orgrimmar.", description = "Ihr seid weit von zu Hause entfernt, <Volk>. Vielleicht ist es an der Zeit, dass Ihr zurückkehrt, um von Eurem Meister Gan'rul Blutauge zu lernen. Für sein Wissen ist er bei allen, die etwas von der Kunst verstehen, bekannt, sogar bei uns hier.\n\nGan'rul lebt in der Kluft der Schatten in Orgrimmar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10791] = {title = "Willkommen Wolfgeist!", objective = "Benutzt den zeremoniellen Weihrauch in der Nähe der Kerzen in Malukaz' Hütte und beobachtet die Zeremonie. Sprecht erneut mit Malukaz, wenn die Zeremonie vorbei ist.", description = "Ich habe die Gewandung, die ich während der Zeremonie tragen werde, fast fertig. Während ich die letzten Handgriffe erledige, möchte ich Euch bitten, diesen Weihrauch bei den Kerzen in der Nähe des Runensteins zu meiner Linken zu platzieren.\n\nIch glaube, dass er uns dabei helfen wird, die Aufmerksamkeit des Wolfgeistes zu erlangen, da er aus den Tagen der orcischen Klans stammt. Ich kann fast schon sehen, wie meine Vorfahren ihn in einer Zeremonie entzündeten, in der sie dem Wolfgeist nach einer erfolgreichen Jagd dankten.\n\nSobald Ihr den Weihrauch platziert habt, werde ich mit der Zeremonie beginnen.", progress = "Die Verbindung mit dem Wolfgeist wiederherzustellen ist nur der Anfang meiner Reise, nicht das Ende.", completion = "Es ist unglaublich! Ich bin zu dieser Reise aufgebrochen, ohne auch nur die leiseste Ahnung zu haben, ob der Wolfgeist auf unsere Anrufung hin kommen würde. Und nun fühlt es sich an, als wäre er nie fort gewesen. Vielleicht war er das auch nie, &lt;Name&gt;.\n\nVielleicht hat er darauf gewartet, dass die Orcs verstehen, was ihre Entscheidung bewirkt hat.", rewards = "Helm der wölfischen ListHaube des WolfsjägersHelm der wölfischen AnmutHelm der wölfischen WildheitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10792] = {title = "Zeth'Gor muss brennen!", objective = "Tötet Peons des Blutenden Auges, um an ihre Fackeln zu kommen. Entzündet sie an der Schmiede von Zeth'Gor und werft die brennenden Fackeln auf die Gebäude von Zeth'Gor.", description = "Der Klan des Blutenden Auges hat seine noble Herkunft verraten! Wir, die Orcs, die gekämpft haben und gestorben sind, um uns vor der Verderbtheit Mannoroths zu schützen, sehen in unseren bösen Vettern nur Schwäche und Unwürdigkeit... und dafür sollen sie brennen!\n\nGeht nach Zeth'Gor, ihre Bastion im Osten, und steckt ihre Gebäude in Brand. Tötet die Peons, um an ihre Fackeln zu kommen, entzündet diese an ihrer Schmiede und werft die brennenden Fackeln auf ihre Hütten, ihren Stall und ihre Kaserne. Brennt sie alle nieder und kehrt dann zu mir zurück!\n\nFür die Horde!", progress = nil, completion = "Hah! Ich konnte die Flammen über Zeth'Gor bis hierher sehen! Mögen unsere Feinde des Blutenden Auges zu Asche zerfallen und keinem wahren Orc mehr unter die Augen kommen!\n\nVielen Dank, &lt;Name&gt;. Ihr habt geholfen, eine Beleidigung für den Geist eines jeden Orcs hinfort zu brennen.", rewards = "Umhang des VerteidigersUmhang des InfiltratorsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10793] = {title = "Val'zareqs Tagebuch: Vorboten des Krieges", objective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.\n\nSucht ihn in einem Kristallgefängnis.", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", progress = "<General Auralion schwebt in der Mitte des Kristalls.>\n\nWa... Was tut Ihr hier?", completion = "Ihr habt ihren Eroberer getötet? Dann haben wir nicht viel Zeit...\n\nDas Purpursiegel besteht aus der Elite von Illidans Dienern. Sie stehen am oberen Ende der Befehlskette für Illidans Armeen außerhalb des Schwarzen Tempels. Diese Soldaten stehen in direktem Kontakt mit dem Verräter und führen seine Anweisung ohne Fragen zu stellen aus.\n\nSie sind diejenigen, die ohne mit der Wimper zu zucken einen Angriff auf diese Welt starten und dabei alles, was ihnen in Wege steht, dem Erdboden gleich machen würden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10794] = {title = "Schurken der Zerschmetterten Hand", objective = "Sprecht mit Shenthul in Orgrimmar.", description = "<Name>, es gibt Geheimnisse auf dieser Welt, die wir jetzt noch nicht verstehen. Die Zerschlagene Hand in Orgrimmar kann Euch zu einem dieser Geheimnisse führen: der Kunst, tödliche Gifte zu brauen. Tut einfach, was sie sagen, und Ihr werdet ihr Vertrauen gewinnen.\n\nUm nach Orgrimmar zu kommen müsst Ihr das Portal in Silbermond nach Unterstadt nehmen. Begebt Euch danach aus der Stadt hinaus und sucht den in der Nähe gelegnen Turm auf, bei dem die Zeppeline der Goblins ihre Fahrgäste aufnehmen. Fliegt von dort aus nach Orgrimmar, wo Ihr Shenthul in der Kluft der Schatten finden könnt.", progress = nil, completion = "Ihr wollt also für die Zerschlagene Hand arbeiten? Wie es aussieht, bekommen wir jeden Tag jemand Neues dazu.\n\nHört genau zu. Ich werde Euch erklären, was Ihr zu tun habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10795] = {title = "Ein Treffen mit Dorgok", objective = "Tötet Dorgok im Lager der Blutschläger.", description = "Gut, ich habe Euch hier gesehen und wollte Euch in einer Angelegenheit von ziemlicher Wichtigkeit sprechen.\n\nMich ereilen Berichte, laut denen die Oger der Blutschläger einen Angriff gegen Sylvanaar und den Rabenwald planen. Wir wissen nicht, wer oder was sie dazu treibt, dies zu tun, aber ich bin entschlossen, ihren Plan im Keim zu ersticken!\n\nDie Angriffe sollen vom Lager der Blutschläger aus starten. Begebt Euch nach Nordwesten den Pfad aus dem Ruuanwald hinab in das Lager. Ich möchte, dass Ihr ihren Anführer Dorgok tötet!", progress = nil, completion = "Jetzt, da Dorgok tot ist, sind die Oger der Blutschläger ohne Anführer und hoffentlich verwirrt, bis ein neuer Anführer aus ihren Rängen gewählt wird.\n\nVielen Dank, &lt;Klasse&gt;. Ich glaube, wir können nun ein wenig aufatmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10796] = {title = "Vernichtet das Lager der Blutschläger!", objective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", description = "Ich habe gehört, dass Ihr uns im Kampf gegen die Oger bis jetzt mehr als stolz gemacht habt. Nun möchte ich Euch bitten, ihnen nochmals gegenüber zu treten. Ich möchte, dass Ihr das Lager der Blutschläger vernichtet!\n\nIhr gelangt dorthin, indem Ihr den nordwestlichen Weg aus den Ruuanwald hinab nehmt. Ihr findet die Oger am Ende des Weges.\n\nViel Glück, <Klasse>!", progress = nil, completion = "&lt;Der Leutnant nickt und scheint mit Eurer mörderischen Kühnheit sichtlich zufrieden.&gt;\n\nIch bin beeindruckt, &lt;Name&gt;. Euer Ruf scheint wohlverdient zu sein.\n\nJedes Mal, wenn einer dieser Oger zu Boden geht, sind wir einen Schritt näher daran, einen Feind loszuwerden, der uns niemals in Frieden lassen wird.", rewards = "Schleichstiefel der DunkelheitSchulterschutz des ZwillingsmondesKettenschlaufengurtSchönwetters HandgelenksschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10797] = {title = "Die Gunst der Gronn", objective = "Bringt Gorgroms Gunst zu Kommandant Haephus Steinwall im Ewigen Hain im Schergrat.", description = "Aus Dorgoks leblosem Griff fällt ein Abzeichen in Form einer kleinen Statuette. Sie hat frappierende Ähnlichkeit mit einem Gronn.\n\nKommandant Haephus Steinwall im ewigen Hain im Ruuanwald, den Weg im Osten hinauf, ist daran sicher sehr interessiert.", progress = "Hallo, Junge! Was gibt es Neues?", completion = "Oh, das ist aber hübsch. Sieht ein bisschen aus wie diese Gronn, die die Oger der Speerspießer immer durch die Gegend scheuchen.\n\nKomisch, dass Ihr es in der Hand eines Anführers der Blutschläger gefunden habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10798] = {title = "Dem Baron einen Besuch abstatten", objective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", description = "Das sind schlechte Nachrichten. Gorgrom der Drachenfresser steckt hinter den Plänen der Blutschläger, Sylvanaar anzugreifen.\n\nIch weiß nicht, warum er sie manipuliert und nicht einfach die Speerspießer dazu benutzt. Aber wenn wir uns mit einem Gronn auseinandersetzen müssen, werden wir Hilfe benötigen.\n\nIch kenne einen Mann, der in allen möglichen Arten exotischer Magie bewandert ist. Sein Name ist Baron Zobelmähne. Er hält sich beim Zirkel des Blutes auf. Ihr könnt dorthin gelangen, indem Ihr den Weg im Nordwesten hinabsteigt und dann nach Südenwesten durch die Schlucht geht.\n\nBittet ihn, uns eine Falle für den Gronn herzustellen.", progress = nil, completion = "Ah, ein Gesandter der gerühmten Allianz. Sagt mir, Lakai, warum seid Ihr es, der hierher gekommen ist und mich um dieses Ding bittet, und nicht Eurer illustrer Kommandant?\n\nKann es etwa sein, dass er Angst vor mir hat? Irgendetwas an Euch sagt mir, dass Ihr keine habt, aber ich weiß noch nicht, was das ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10799] = {title = "In die Grabenschlucht", objective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", description = "Nun gut, ich werde diese Falle herstellen, aber zunächst möchte ich etwas dafür haben.\n\nZufälligerweise befindet sich ein Gronn in der Nähe im Besitz eines Gegenstands, den ich haben möchte. Ihr könnt ihm Euch jedoch nicht stellen, zumindest noch nicht.\n\nDaher werden wir ein Schlafpulver aus dem Gift der Krustenbohrer dieser Gegend herstellen.\n\nIhr findet sie in der Grabenschlucht im Südwesten. Bringt mir ein paar ihrer Drüsen und macht schnell!", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", rewards = "Ihr bekommt:\n\nBlutbeulengift"}
MultiLanguageQuestData['de'][10800] = {title = "Gute Nacht, Gronn", objective = "Beschafft Euch Grullocs Sack.", description = "Ich habe mich mal wieder selbst übertroffen. Ich habe für Euch ein Schlafpulver erstellt, das Ihr Grulloc verabreichten könnt, dem Gronn, der besitzt, was ich möchte.\n\nGrulloc hält sich im Verfluchten Dunkel auf. Diese Gegend befindet sich am östlichen Rand von Drachenend auf der anderen Seite des Zirkels des Blutes.\n\nAn Eurer Stelle würde ich nicht lange zögern, sobald Ihr seinen Sack geschnappt habt. Die Wirkung des Staubs lässt schnell nach.", progress = "Ihr steht mir wieder gegenüber, <Klasse>. Das muss bedeuten, dass Ihr den Sack unter Grullocs Nase weggeschnappt habt.", completion = "&lt;Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.&gt;\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun werde ich Euren Kommandanten mit der Falle beschenken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10801] = {title = "Das ist eine Falle!", objective = "Bringt die Drachenfeuerfalle zu Kommandant Haephus Steinwall im Ewigen Hain im Schergrat.", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nIch bin mir sicher, dass Ihr einen bestimmten Gronn in Sinn habt. Mir ist ganz gleich welcher, Hauptsache, Ihr tötet einen. Beeilt Euch und bringt die Falle zu Kommandant Steinwall.\n\nMein Rachedurst muss gestillt werden!", progress = "Hat der Baron uns eine Falle gebaut? Eine, die stark genug ist, um einen Gronn zu töten?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10802] = {title = "Gorgrom der Drachenfresser", objective = "Beschafft Euch 3 grausige Totems von den Ogern von Fels'mok. Benutzt danach Zobelmähnes Falle bei Gorgroms Altar, um Gorgrom den Drachenfresser zu rufen und zu töten.\n\nPlatziert die 3 grausigen Totems in der Nähe seines Körpers, wenn er gestorben ist.", description = "Wir müssen den Ogern zeigen, dass sie sich nicht mit uns anlegen sollten! Wir müssen ihnen eine Nachricht zukommen lassen.\n\nReist nach Fels'mok und tötet die Oger dort. Hebt ihre Köpfe auf!\n\nGeht danach zu Gorgroms Altar und stellt die Falle auf. Daraufhin wird Gorgrom erscheinen. Ihr müsst versuchen, ihn in die Falle zu locken. Wenn er tot ist, stellt die Ogerköpfe als grausige Totems bei seinem Körper auf, damit die Oger ihren gefallenen Meister und ihre gefallenen Kameraden sehen können. Dann werden sie wissen, was man bekommt, wenn man sich mit uns anlegt!", progress = "Wurde die Nachricht schon überbracht?", completion = "Gut gemacht, &lt;Name&gt;. Sehr gut gemacht!\n\nIch nehme an, dass wir nun nicht mehr von den Ogern und ihrem Herrn hören werden.", rewards = "Sirrendes SchwertGezahnte AxtStab des SchiedsrichtersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10803] = {title = "Gemetzel in Fels'mok", objective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok.", description = "Ich weiß, dass wir vorhaben, Euch nach Fels'mok zu schicken. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichtemachen!\n\nFels'mok liegt im Westen. Reist nach Südwesten, überquert die Brücke und geht durch den Tunnel. Ihr findet sie auf der westlichen Seite des Rabenwalds.\n\n<Name>, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok auslöscht!", progress = nil, completion = "&lt;Leutnant Schönwetter grinst, als Ihr ihr von Euren Abenteuern in Fels'mok erzählt.&gt;\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, &lt;Name&gt;, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10804] = {title = "Freundlichkeit", objective = "Mordenai bei den Netherschwingenfeldern im Schattenmondtal möchte, dass Ihr 8 ausgewachsene Drachen der Netherschwingen füttert.", description = "Etwas hat sie aufgescheucht, <Volk>.\n\n<Mordenai zeigt auf die Netherdrachen, die über Euch fliegen.>\n\nSie kommen nicht einmal herunter, wenn ich sie füttere. Ich habe schon einige gesehen, die einfach zu Boden fielen. Sie sind vor Erschöpfung gestorben, noch bevor ihr Körper die Erde berührt hat.\n\nWir müssen sie retten! Die Felsspitzenschinder, die sich in der Nähe der Kristalle aufhalten, sind ihre natürliche Beute. Tötet die Schinder und nehmt ihre Kadaver. Legt einen Kadaver auf das Feld und verhaltet Euch äußerst ruhig. Solange Ihr keine hektischen Bewegungen macht, werden sie Euch auch nicht angreifen.", progress = "Ich kann sie nicht alleine retten, <Name>!", completion = "Ihr seid ein freundlicher und mitfühlender &lt;Volk&gt;, mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10805] = {title = "Massaker in Gruuls Unterschlupf", objective = "Tötet 10 Vollstrecker der Speerspießer, 5 Kampfmagier der Speerspießer, 5 Verheerer der Speerspießer und ihren Anführer Fingrom.", description = "Ihr habt Euch als sehr nützlich erwiesen. Daher werde ich Euch in meinem persönlichen Kampf gegen Gruul und seine Söhne einsetzen.\n\nDer Stamm der Speerspießer steht in der Gunst der Gronn. Auch wenn Ihr ihre Reihen an anderen Orten bereits deutlich gelichtet habt, habt Ihr die Stärksten noch nicht erwischt.\n\nGruul lasst seinen Unterschlupf nur von den Kräftigsten unter den Ogern bewachen, und genau die müsst Ihr vernichten. Begebt Euch nach Norden durch die Dolchrachenklamm. An ihrem Ende findet Ihr Gruuls Unterschlupf.", progress = nil, completion = "Sehr gut. Ich habe eine weise Wahl getroffen, als ich Euch zur Speerspitze meines Kampfes gemacht habe. Ich schätze, es ist an der Zeit, die Dinge auf eine ganz neue Ebene zu tragen.\n\nErinnert Ihr Euch an den kleinen Leckerbissen, den Ihr Grolloc für mich unter der Nase weggeschnappt habt? Ihr werdet die Gelegenheit bekommen, ihn sinnvoll einzusetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10806] = {title = "Finale", objective = "Benutzt Zobelmähnes Siegelring beim Altar von Goc und tötet Goc.", description = "Es ist für uns an der Zeit, uns Goc zu stellen, dem Herrn der Oger der Speerspießer. Es ist auch an der Zeit, dass ich mich in die Geschehnisse einmische und dem Gronn in seiner Todesstunde beiwohne.\n\nNehmt meinen Siegelring. Wenn Ihr zum Altar von Goc gelangt, benutzt ihn und ich werde Euch zu Hilfe kommen.\n\nZusammen werden wir Goc vernichten.", progress = "Bald werden alle Söhne des Gruul vernichtet sein.", completion = "Für einen wie Euch habt Ihr erstaunlich gut gekämpft. Es war mir eine Ehre, Euch an meiner Seite zu wissen. Meine Verwandlung muss Euch wohl ein wenig überrascht haben. Ich hoffe, ich habe Euch nicht allzu sehr erschreckt.\n\nWir sollten meine wahre Identität jedoch für uns behalten. Als Belohnung für Eure treuen Dienste biete ich Euch eines dieser Schmuckstücke an.", rewards = "GrollhufbalggamaschenWachstuchbundhoseTurmalinkroneAugenklappe des ÜbeltätersGeschwärzte BrustplatteLöwenartige BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10807] = {title = "Die Aschenzungen", objective = "Varen der Fordernde möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Der Aschenzungenstamm wird von allen Zerschlagenen gefürchtet. Er besteht aus den bösartigsten und blutrünstigsten Gestalten, die von Akama persönlich ausgewählt wurden. Sie sind so wild und rücksichtslos wie jeder Naga, Dämon oder Blutelf in Illidans Armee. Eine große Anzahl von ihnen wurde in den Ruinen von Baa'ri nördlich von hier stationiert. Begebt Euch dorthin und dezimiert ihre Zahl, bevor sie die Gelegenheit haben, uns anzugreifen.", progress = nil, completion = "Ehre den Sehern, &lt;Name&gt;. Ihr habt den Willen des Lichts ausgeführt und Illidans Anhänger vernichtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10808] = {title = "Dem Dunklen Rat in die Quere kommen", objective = "Tötet die Ritualisten des Dunklen Rats und benutzt Parshahs Stab, um das Beschwörungsritual des Dunklen Rats zu beenden. Kehrt danach zu Parshah in den Magmafeldern zurück.", description = "Die Geister des Dunklen Rats versuchen, ein altes und mächtiges Übel durch ein Ritual, das bei den Lavabecken südlich des Basislagers der Sketh'lon durchgeführt werden soll, in diese Welt zu beschwören.\n\nGul'dans Magie vermischt mit ihrer eigenen! Und damit wollen sie diese Kreatur in unsere Welt rufen! Das dürfen wir nicht zulassen, <Name>. Der Tod und die Zerstörung, die dieses Wesen in unsere Welt bringen würde, sind unvorstellbar!\n\nBringt den Stab zu dem Ort, an dem sie die Beschwörung durchführen wollen und benutzt seine Magie, um den Dunklen Rat ein für alle Mal aufzuhalten!", progress = "Ist es vollbracht, <Name>? Habt Ihr den Dunklen Rat davon abgehalten, das Ritual zu vollenden?", completion = "Ich habe jahrelang nach einem Weg gesucht, um den Dunklen Rat aufzuhalten. Ihr habt geschafft, wobei ich versagt habe. Die finsteren Rituale des Dunklen Rats werden nie wieder zu einer Bedrohung für uns.\n\nIch fühle mich oft schuldig, weil ich meine Kameraden vor all diesen Jahren verlassen habe, aber nun weiß ich endlich, dass es die richtige Entscheidung war. Hätte mein Gewissen damals nicht zu mir gesprochen, wäre ich nun vielleicht ein Schatten unter ihnen.", rewards = "Überlebenstunika der Sketh'lonAschengestärkte BeinschützerKrone der AscheRunenverzierte Beinplatten der Sketh'lonIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10809] = {title = "Gesucht: Worgmeister Kruush", objective = "Tötet Worgmeister Kruush und bringt seinen Kopf zu Hauptmann Nachtheul im Rückenbrecherposten.", description = "Auf dem Anschlag steht geschrieben:\n\n\"Worgmeister Kruush führt die Worgreiter des Blutenden Auges an. Da seine Reiter große Opfer unter den Versorgungskarawanen des Rückenbrecherpostens gefordert haben, wurde ein Preis auf seinen Kopf ausgesetzt.\"\n\n\"Späher berichten, dass er in Zeth'Gor gesehen wurde. Der Held, der den abgetrennten Kopf des Übeltäters zu mir bringt, wird den Dank der Horde sowie ein großzügiges Kopfgeld erhalten.\"\n\nGezeichnet: Hauptmann Nachtheul", progress = "Berichtet, <Name>. Ist das Blut des Blutenden Auges da auf Eurem Ärmel? Ich hoffe doch!", completion = "Ihr habt also den Tunichtgut Kruush erschlagen! Gut gemacht, &lt;Name&gt;! Sehr gut! Sein Tod wird seinen verfluchten Worgreitern die Giftzähne ziehen! Ich hoffe, Ihr habt auch ein paar von ihnen erledigt, als Ihr Euren kleinen Ausflug nach Zeth'Gor gemacht habt!\n\nHier ist Eure Belohung. Ihr habt sie Euch verdient!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10810] = {title = "Die beschädigte Maske", objective = "Bringt die beschädigte Maske zu O'Mally Zapschnapper in den Ewigen Hain im Schergrat.", description = "Während ihr die beschädigte Maske betrachtet, hört Ihr Geräusche aus ihrem Inneren kommen. Wenn die Maske nicht beschädigt wäre, könntet Ihr die Geräusche deutlicher hören.\n\nO'Mally Zapschnapper im Ruuanwald könnte sie vielleicht reparieren.", progress = "Geht mir nicht auf die Nerven! Könnt Ihr nicht sehen, dass ich dabei bin, mysteriöse Kräfte zu entfesseln?", completion = "Ah, was habt Ihr denn da? Lasst mich das mal genauer ansehen, &lt;Klasse&gt;. Ja, ja... es ist genau das, was ich dachte. Lasst mich die Maske für Euch reparieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10811] = {title = "Sucht Neltharaku auf", objective = "Sucht Neltharaku, den Patron des Drachenschwarms der Netherschwingen auf.", description = "Ihr Patron schwebt hoch oben in den Lüften, <Name>. Vielleicht hat die Freundlichkeit, die Ihr seinen Kindern gegenüber gezeigt habt, sein Herz bewegt. Sucht Neltharaku auf und bittet ihn um Hilfe. Zusammen könnt Ihr vielleicht die Not der Netherschwingendrachen beenden.\n\n<Mordenai zeigt in den Himmel.>\n\nFliegt hoch, <Klasse>.", progress = nil, completion = "Meine Kinder haben mir von Eurer heldenhaften Tat erzählt, &lt;Volk&gt;. Es gibt noch mehr, was Ihr tun könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10812] = {title = "Die geheimnisvolle Maske", objective = "Bringt die geheimnisvolle Maske zu Wildfürst Antelarion in den Ewigen Hain im Schergrat.", description = "Gut, jetzt sollte sie funktionieren. Was das ist, fragt Ihr? Nun, es ist ein Kommunikationsgerät. Diese Schafsköpfe kommunizieren so miteinander. Ihr wisst schon, die Brennende Legion! Ich würde Euch empfehlen, die Maske zu Wildfürst Antelarion zu bringen. Er geht dort drüben auf und ab. Immer in Bewegung!\n\nNun los mit Euch! Er versucht schon eine ganze Weile eine von den Masken in die Finger zu bekommen.", progress = "Ich traue meinen Augen nicht.", completion = "Diese Maske, die Ihr da in den Händen haltet, ist eine Gasmaske der Teufelsbrut! Und wie es aussieht, ist sie nicht beschädigt! Der Ärger, den wir damit im Konstruktionslager: Groll anrichten können, ist grenzenlos! Habt Ihr Lust, uns dabei zu helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10813] = {title = "Die Augen von Grillok", objective = "Benutzt Zezzaks Splitter, um ein Auge von Grillok zu fangen und nähert Euch damit Zezzaks Kessel. Bringt den Splitter zu Zezzak zurück, wenn Ihr das Auge dem Kessel übergeben habt.", description = "<Name>, Ihr habt im Nest der Orcs des Blutenden Auges, im gefürchteten Zeth'Gor, Euren Heldenmut bewiesen und überlebt! Vielleicht seid Ihr stark genug, um mir zu helfen, denn ich werde in den Geist ihres finstersten Hexers blicken, Grillok!\n\nNehmt diesen Splitter. Benutzt ihn, um ein Auge von Grillok zu behexen und bindet es an Euch. Kehrt dann zu mir zurück und nähert Euch meinem Kessel... er wird das Auge anziehen.\n\nGeht, <Name>. Und seid auf der Hut! Ein Auge von Grillok wird Euch an Eure Feinde verraten, wenn es auch nur die geringste Gelegenheit dazu bekommt!", progress = "Die Orcs des Blutenden Auges waren einst starke Verbündete... und nun sind sie noch stärkere Feinde.", completion = "Ich stehe tief in Eurer Schuld, &lt;Name&gt;. Ihr habt ein weiteres Mal über Zeth'Gor triumphiert und seine Dunkelheit nahe an Euer Herz gelassen. Ich werde das Auge untersuchen und damit hoffentlich die Geheimnisse seines Meisters Grillok lüften.\n\nHoffentlich kann es seine Magie nicht länger einsetzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10814] = {title = "Neltharakus Geschichte", objective = "Sprecht mit Neltharaku und hört Euch seine Geschichte an.", description = "Ich habe Informationen, die Euch vielleicht weiterhelfen können. Bitte hört Euch an, was ich zu erzählen habe.", progress = nil, completion = "Werdet Ihr uns also helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10815] = {title = "Val'zareqs Tagebuch: Vorboten des Krieges", objective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10816] = {title = "Rückforderung geheiligten Bodens", objective = "Verteidiger Aluumen möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Aufgaben für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Ihr habt Eure Arbeit bei den Zerschlagenen in Baa'ri gut gemacht, <Name>. Wollen wir mal sehen, wie Ihr gegen Illidans gefürchtetste Armee besteht.\n\nDie Terrasse von Ata'mal war einst eine geheiligte Stätte, an der wir die Kristalle von Ata'mal benutzten, um spirituelle Zeremonien durchzuführen. Nun ist dieser Orts von den Höllenorcs des Schattenmondklans besetzt worden.\n\nWir hatten guten Grund zur Annahme, dass sie einen Kristall von Ata'mal in der Nähe versteckt halten, aber unsere magische Beobachtung dieses Ortes lieferte kein Ergebnis. Dennoch sind die Orcs auf unserem geheiligten Boden eine Schmach, die wir nicht tolerieren können.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Klasse&gt;. Möge das Licht Euch beschützen.", rewards = "Krone von Ata'malAlte LederbindungenGeschwärzte KettenschienbeinschützerAschenbedeckter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10817] = {title = "Die große Vergeltung", objective = "Varen der Fordernde möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Ihr habt Euch im Kampf gegen die Zerschlagenen der Aschenzungen tapfer geschlagen, <Name>. Wenn Ihr bereit seid, habe ich eine weitere Herausforderung für Euch.\n\nVor nicht allzu langer Zeit wurde das Sanktum der Sterne Opfer eines gewaltigen Angriffs durch Illidans Höllenorcs.\n\nWir haben herausgefunden, dass die Schattenmondorcs, die die Terrasse von Ata'mal behausen, dieses Verbrechen verübt haben.\n\nZeigt ihnen, dass man sich besser nicht mit den Sehern anlegen sollte!", progress = nil, completion = "Ihr habt meinen höchsten Respekt verdient, &lt;Name&gt;.\n\nEinen Höllenorc alleine zu töten ist schon keine leichte Aufgabe. Eine ganze Meute von ihnen zu töten ist, nun... heroisch.", rewards = "Krone von Ata'malAlte LederbindungenGeschwärzte KettenschienbeinschützerAschenbedeckter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10818] = {title = "Baron Zobelmähne verlangt nach Euch", objective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", description = "<Name>, während Ihr Euch da draußen wie <ein/eine:c> Teufels<Klasse> geschlagen habt, hat Baron Zobelmähne seinen Drachen mit einer Nachricht hierher geschickt.\n\nEr hat nach Euch persönlich gefragt. So wie ich es verstanden habe, möchte er, dass Ihr seinen eigenen Kampf gegen die Gronn weiterführt.\n\nIch schätze, dass Ihr wohl die geeignetste Person in der ganzen Scherbenwelt seid, um ihm dabei zu helfen, aber an Eurer Stelle würde ich ein paar Freunde bitten, Euch zum Zirkel des Blutes zu begleiten.", progress = nil, completion = "Ah, wie ich sehe habt Ihr beschlossen, Euch ganz schön Zeit zu lassen, bis Ihr meinem Aufruf Folge geleistet habt.\n\nWie auch immer, ich hatte genug Zeit, um an meinen Racheplänen zu feilen, und Ihr sollt in der kommenden Schlacht mein Vollstrecker sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10819] = {title = "Die Gasmaske der Teufelsbrut", objective = "Setzt die Gasmaske der Teufelsbrut auf und benutzt den Legionskommunikator im Konstruktionslager: Groll im Schergrat.\n\nBereitgestellter Gegenstand: \n", description = "Ich habe eine ganz besondere Aufgabe für Euch, <Name>. Ich möchte, dass Ihr Euch in das Konstruktionslager: Groll östlich von hier einschleicht. Ihr werdet die Gasmaske der Teufelsbrut tragen müssen, wenn Ihr das Lager betretet, um den Legionskommunikator zu suchen. Sobald Ihr das Kommunikationsgerät gefunden habt, benutzt es. Sprecht mit demjenigen, der sich auf der anderen Seite meldet.\n\nWenn alles klappt, könnt Ihr dem Dämon ein Märchen auftischen! Versucht, ihm zu erzählen, dass im Konstruktionslager: Groll ein Aufstand ausgebrochen ist.\n\nViel Glück, <Klasse>.", progress = nil, completion = "Was soll das bedeuten? Niemand ruft mich! Sprecht, oder ich werde Euch für immer zum Schweigen bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10820] = {title = "Täuscht den Feind", objective = "Tötet 4 Knechte der Schicksalsschmiede und 4 Ingenieure der Schicksalsschmiede.", description = "Mit jedem Moment, in dem ich Stille höre, rückt Ihr dem Tod ein Stückchen näher! SPRECHT!\n\nWas? Das Lager revoltiert? Das kann nicht wahr sein! Meine Diener würden es niemals wagen, meine Autorität zu untergraben.\n\nNun gut, jeder Einzelne von ihnen wird für diesen Verrat bezahlen... teuer bezahlen! Bringt sie alle zum Schweigen! Meldet Euch bei mir zurück, wenn Ihr meinen Befehl ausgeführt habt, oder ich werde mich um Euch kümmern.", progress = "Meine Geduld neigt sich dem Ende zu, warum habt Ihr sie noch nicht erledigt?", completion = "Das wird ihnen sicher zeigen, dass sie besser tun sollten, was ich ihnen sage...\n\nÜbrigens... wo ist Schicksalsrufer? Warum habt Ihr mir von dieser Revolte berichtet und nicht sie?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10821] = {title = "Ihr seid gefeuert!", objective = "Tötet Schicksalsruferin.", description = "Schicksalsruferin hat nichts gegen den Aufstand unternommen? Wie kann sie es wagen! Sie hat schon seit einer Weile versucht, meine Autorität zu untergraben. Doch zum allerletzten Mal! Ihr müsst sie rufen und persönlich zur Verantwortung ziehen.\n\nIhre Grollwachen tragen die Schlüssel bei sich, mit denen sie ins Konstruktionslager: Groll gerufen werden kann. Beschafft Euch die fünf Schlüssel und aktiviert die fünf Obelisken der Legion. Die Obelisken schalten sich nach kurzer Zeit wieder ab, also seht zu, dass Ihr sie alle gleichzeitig aktiviert. Und denkt daran: die Grollwachen tragen noch mehr Schlüssel bei sich.", progress = nil, completion = "Das sind wirklich großartige Nachrichten, &lt;Name&gt;. Ich hätte es mir nicht besser wünschen können. Eure Dienste gegenüber meinem Volk sind sehr geschätzt. Bitte wählt Euch einen dieser Gegenstände aus.\n\nEuer Name wird für immer in den Herzen unseres Volkes klingen.", rewards = "Waldläuferumhang des Ewigen HainsHandgelenksschützer des RuuanwaldsAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger der ExpeditionBand des Wildfürsten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10822] = {title = "Einzelne Siegel des Sonnenzorns", objective = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!", description = nil, progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Sieg für die Seher! Kaels Streitmächte werden bald fallen!", rewards = nil}
MultiLanguageQuestData['de'][10823] = {title = "Mehr Siegel des Sonnenzorns", objective = "Wir verläuft der Kampf gegen Kaels Streitmächte?", description = nil, progress = "Wir verläuft der Kampf gegen Kaels Streitmächte?", completion = "Ihr macht Euch einen Namen, &lt;Name&gt;. Weiter so!", rewards = nil}
MultiLanguageQuestData['de'][10824] = {title = "Siegel des Sonnenzorns", objective = "Kampfmagierin Vyara beim Sanktum der Sterne möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", description = "Das Überleben der Seher hängt davon ab, ob wir es schaffen, mehr Rekruten zu sammeln als Kael'thas. Jeder Pilger aus Quel'Thalas, der sich auf seine Seite schlägt, bringt ihn einen Schritt näher an den Sieg. Und das bedeutet das Gegenteil für uns.\n\nBald werden uns jedoch die Rekruten ausgehen und es wird darauf hinauslaufen, wer den anderen schneller tötet. Beweist Euch gegenüber den Sehern und bringt mir die Siegel des Sonnenzorns der höherrangigen Blutelfen, die im Bunde mit Illidan und Kael'thas stehen. Ihr findet sie bei der Stätte der Mondfinsternis im Westen und in den Ruinen von Karabor im Nordosten.", progress = "Los, <Name>. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ausgezeichnete Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10825] = {title = "Die kugellose Wahrheit", objective = "Bringt die Kugel der Grishna zu Baumhüter Chawn in den Ewigen Hain im Schergrat.", description = "Diese merkwürdige, magische Kugel fällt aus dem Federkleid des Arakkoa.\n\nSie ist von einem unheimlichen violetten Leuchten umgeben und pulsiert zu einem unhörbaren Takt. Sie in der Hand zu halten gibt Euch ein unangenehmes Gefühl, daher packt Ihr sie schnell in Eure Tasche.\n\nVielleicht würde Baumhüter Chawn im Ruuanwald im Westen, jenseits des Tunnels und der Brücke des Wyrmschädels, sie gerne untersuchen?", progress = "<Klasse>, könnt Ihr das spüren? Ich fühle, dass etwas Unnatürliches und Böses in der Nähe ist.", completion = "Ja, es ist die Kugel, die Ihr da habt! Merkwürdig, sie scheint von den Arakkoa zu stammen. Wart Ihr kürzlich in Grishnath?\n\nAh, das erklärt das Ganze. Aber ich frage mich, welchem teuflischen Zweck dieses Objekt dient. Obwohl das Böse eindeutig darin schlummert, scheint sie doch mit der Natur verbunden zu sein.\n\nBitte erlaubt mir zu versuchen, sie zu aktivieren. Das Böse darin ist so stark, es erinnert mich an etwas...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10826] = {title = "Male des Sargeras", objective = "Bringt 10 Male des Sargeras zu Herold Saronen im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Hier im Schattenmondtal könnt Ihr eine große Ansammlung der Legion weit im Westen in der Feste der Legion und der Todesschmiede finden.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, <Name>?", completion = "Ihr seid sehr mutig, Freund. Mögen alle wissen, dass Ihr ein wahrer Freund der Priesterschaft seid!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10827] = {title = "Mehr Male des Sargeras", objective = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Wir bekämpfen die Legion, bis das Licht siegt!", description = nil, progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Wir bekämpfen die Legion, bis das Licht siegt!", completion = "Besiegt die Feinde des Lichts, wo immer Ihr sie findet, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][10828] = {title = "Einzelne Male des Sargeras", objective = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", description = nil, progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Ihr beweist auch weiterhin Euren Wert, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][10829] = {title = "Baumriese muss es wissen", objective = "Sprecht mit Baumriese, ein Urtum der Lehren, das im Rabenwald im Schergrat lebt.", description = "Das ist erschütternd! Die Arakkoa bewirken, dass die Urtume und Beschützer von bösen Geistern besessen werden!\n\nEs gibt jedoch ein Urtum, das auf gar keinen Fall davon betroffen sein kann. Sein Name ist Baumriese. Wenn wir die Bäume des Rabenwaldes retten wollen, müsst Ihr sofort zu ihm gehen!\n\nBegebt Euch in den Rabenwald. Ihr findet ihn an der Weggabelung kurz hinter Grishnath.", progress = nil, completion = "Grüße, kleiner &lt;Volk&gt;. Die Vögel in meinen Zweigen haben mir zugeflüstert, dass Ihr kommen würdet.\n\nIhr seid hier, um die Bäume des Waldes von ihrer Besessenheit zu heilen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10830] = {title = "Der Exorzismus der Bäume", objective = "Sammelt 5 Kugeln von Grishnath und 5 Terrorfederkiele und stellt daraus Exorzismusfedern her. Benutzt die Federn, um 5 Koikoigeister von den Laubbärten des Rabenwaldes zu exorzieren und zu töten.", description = "Die Grishna sind dafür verantwortlich, dass die Laubbärte und Steinborken von bösen Koikoigeistern übernommen werden.\n\nWir müssen die Bäume retten, sonst ist der Rabenwald bald verloren!\n\nKombiniert die Macht einer Kugel von Grishnath, die überall in Grishnath zu finden sind, mit einem Terrorfederkiel eines Terrorraben.\n\nBenutzt die dadurch entstandene Exorzismusfeder, um die Koikoigeister hervorzulocken und so schnell wie möglich umzubringen. Die Steinborken sind für dieses Ritual zu stark, aber wenn Ihr genügend Laubbärte befreit, werden auch sie frei sein.", progress = "Das Böse, das den Bäumen innewohnt, breitet sich auf die gesamte Natur des Waldes aus.\n\nIhr müsst schnell handeln, <Name>, bevor es zu spät ist!", completion = "Das Böse verschwindet aus dem Rabenwald! Könnt Ihr es fühlen, &lt;Name&gt;?\n\nIhr habt uns und alle Wildtiere hier vor der unweigerlichen Zerstörung gerettet, kleines Wesen!\n\nFür solche Gelegenheiten trage ich vier magische Ringe in meinen Zweigen und verschenke sie, wenn ein Held sich erhebt, um eine große Tat zu vollbringen.\n\nIhr seid solch ein Held! Im Namen des gesamten Rabenwaldes danke ich Euch.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nExorzistenband des RabenwaldsRing des LaubbartsBaumrieses RingRing der Steinborke\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10831] = {title = "Wie man ein Mondstoffschneider wird", objective = "Benutzt das magieerfüllte Netherstoffstück während Ihr im Mondbrunnen der Zuflucht des Cenarius steht, um eine Urmondstoffprobe herzustellen. Bringt die fertige Urmondstoffprobe zu Nasmara Mondweise im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", description = "Ich kann Euch die Kunst des Mondstoffschneiderns beibringen, wenn Ihr möchtet. Wenn Ihr Euch auf die Mondstoffschneiderei spezialisiert, werdet Ihr bei der Herstellung von Urmondstoff den doppelten Ertrag erhalten und Zugang zu mehreren exklusiven Mustern bekommen. Dazu müsst Ihr nur einen einfachen Test bestehen.\n\nDer Test besteht darin, eine kleine Probe Urmondstoff im Mondbrunnen der Zuflucht des Cenarius herzustellen. Ich werde Euch alle Materialien, die Ihr dafür benötigt, zur Verfügung stellen. Bringt mir die Probe, wenn Ihr sie fertig gestellt habt, damit ich sie beurteilen kann.", progress = "Habt Ihr die Urmondstoffprobe hergestellt?", completion = "&lt;Nasmara untersucht den Stoff und dreht ihn in den Händen hin und her.&gt;\n\nDas ist eine hervorragende Probe, &lt;Name&gt;. Ihr werdet einen ausgezeichneten Mondstoffschneider abgeben.", rewards = "Ihr erlernt:\n\nMondstoffschneiderei\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMondstoffschneiderei\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10832] = {title = "Wie man ein Zauberfeuerschneider wird", objective = "Bringt eine Probe einer Nethergespenstessenz zu Gidge Spruchwirker im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", description = "Ich kann Euch die Kunst der Zauberfeuerschneiderei beibringen, aber seid gewarnt, es ist eine gefährliche Kunst.\n\nDie Herstellung von Zauberstoff im Nethersturm lockt mächtige Nethergespenster an. Ich bin auf der Suche nach einem Weg, um den Effekt zu mildern, aber dazu brauche ich noch mehr Essenzen der Nethergespenster für meine Forschungen.\n\nBringt dieses Signal zum Nethersturm und benutzt es, um ein Nethergespenst zu rufen. Bringt mir seine Essenz, dann werde ich Euch unterrichten. Als Zauberfeuerschneider werdet Ihr doppelt so viel Stoff erhalten und Zugang zu exklusiven Mustern bekommen.", progress = "Habt Ihr die Nethergespenstprobe?", completion = "&lt;Gidge untersucht die Nethergespenstessenz.&gt;\n\nSogar in dieser kleinen Probe der Essenz ist seine Macht deutlich sichtbar. Vielleicht habe ich missverstanden, was vor sich geht. Wir erzürnen die Gespenster nicht, wenn wir der Umwelt die Energie nehmen. Die Umwelt und die Geister sind vielmehr eins!\n\nZögert nicht, mich zu informieren, wenn Ihr weitere Entdeckungen machen solltet... nun, da Ihr ein Zauberfeuerschneider seid.", rewards = "Ihr erlernt:\n\nZauberfeuerschneiderei\n\nDer folgende Zauber wird auf euch gewirkt:\n\nZauberfeuerschneiderei\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10833] = {title = "Wie man ein Schattenzwirnschneider wird", objective = "Benutzt den Kristall der tiefen Schatten in der Nähe des Altars der Schatten, um Eure Verbindung zu dem Altar zu stärken. Kehrt danach zu Andrion Dunkelweber im Unteren Viertel in Shattrath zurück.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", description = "Wenn Ihr Euch auf die Schattenzwirnschneiderei spezialisiert, werdet Ihr doppelt so viel Schattenstoff wie ein gewöhnlicher Schneider herstellen können und Zugang zu exklusiven Mustern erhalten.\n\nNatürlich kann jeder Schneider den Altar der Schatten benutzen, aber ein Schattenzwirnschneider hat eine tiefere Verbindung zu dem Altar und entfesselt dadurch Mächte, die sich nur wenige vorstellen können.\n\nBringt diesen Kristall in das östliche Schattenmondtal und sucht den Netherschwingenpass, der von den Netherschwingenfeldern aus nach Süden führt. Nahe am Ende der Welt findet Ihr den Altar der Schatten. Benutzt dort den Kristall.", progress = nil, completion = "Wie ich sehe war Euer Besuch beim Altar erfolgreich. Etwas an Euch hat sich verändert. Nur wenigen wird es auffallen, aber es ist ohne Zweifel da.", rewards = "Ihr erlernt:\n\nSchattenzwirnschneiderei\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchattenzwirnschneiderei\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10834] = {title = "Grillok 'Finsterauge'", objective = "Tötet Grillok Finsterauge und bringt Grilloks Augenklappe zu Zezzak im Rückenbrecherposten.", description = "Grillok Finsterauge hat einen Teil von sich den dunklen Mächten verpfändet und dafür große Macht erhalten. Sein verlorenes Auge brennt nun in irgendeiner teuflischen Grube als Schmuckstück eines Dämonen... und die Klappe, die seinen Verrat versteckt, hat ihr ganz eigenes dunkles Geheimnis.\n\nBringt mir Grilloks Augenklappe, <Name>, und ich werde Euch fürstlich für Eure Dienste belohnen.", progress = "Die Bösartigkeit der Orcs des Blutenden Auges kennt keine Grenzen und wird nur noch von der ihrer Vettern der Zerschmetterten Hand übertroffen.", completion = "Ah ja. Ich frage mich, ob Grillok in seinen dunklen, dunklen Träumen immer noch mit seinem verlorenen Auge verbunden ist, wie jemand, der eine Hand oder ein Bein in der Schlacht verloren hat...\n\nAuch ich werde davon träumen. Und wenn das Schicksal auf unserer Seite steht, werden wir dadurch erfahren, was Grillok und die Orcs des Blutenden Auges dazu gebracht hat, sich den Dämonen zu unterwerfen.", rewards = "Heilige FederwesteWams des ungezähmten GeistsGoldgewebte TunikaGüldene PurpurbrustplatteBerserkerweste der KnochenmalmerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10835] = {title = "Apotheker Antonivich", objective = "Bringt Albrecks Befund zu Apotheker Antonivich nach Thrallmar auf der Höllenfeuerhalbinsel.", description = "<Name>, ich habe einen vorläufigen Bericht über meine Befunde bezüglich der Orcs des Blutenden Auges angefertigt. Mein Kollege in Thrallmar, Apotheker Antonivich, will ihn sicher gerne lesen. Auch er befasst sich mit dem Phänomen der Höllenorcs und hofft verhindern zu können, dass eine solche Tragödie auch unseren orcischen Verbündeten zustoßen könnte.\n\nBringt diesen Bericht zu ihm. Ich werde in der Zwischenzeit weiter das Blut, das Ihr mir gebracht habt, untersuchen. Wenn das Glück auf unserer Seite ist, können wir die Ursache für das Leiden der Höllenorcs herausfinden.", progress = "Guten Tag, <Name>. Wie gefällt Euch Euer Aufenthalt auf der Höllenfeuerhalbinsel? Ich bin mir sicher, dass er sehr ergiebig ist...", completion = "Ah, ein Bericht von Albreck? Sehr gut. Die königliche Apothekervereinigung versucht verzweifelt herauszufinden, wie die Orcs der Höllenfeuerhalbinsel zu Höllenorcs geworden sind. Ihr Verrat ist unverzeihlich... und wir müssen sicherstellen, dass unsere Orcfreunde für alle Zeit vor dieser Verderbnis sicher sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10836] = {title = "Unterwanderung der Festung des Drachenmals", objective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 15 Orcs des Drachenmals tötet.\n\nSämtliche Orcs des Drachenmals in der Festung des Drachenmals kommen dafür in Frage.", description = "Ich brauche Zeit, um einen Plan zu entwickeln, mit dem ich meine Kinder und mein Weibchen retten kann. Ihr werdet mir diese Zeit beschaffen, <Sterblicher/Sterbliche>.\n\nReist zur Festung des Drachenmals am östlichen Ende der Netherschwingenfelder und vernichtet alle Orcs des Drachenmals, die Ihr finden könnt. Das daraus resultierende Chaos und die Verwirrung sollte ihre Pläne maßgeblich beeinflussen.\n\nDoch seid auf der Hut. Einige meiner Art sind bereits von den Orcs des Drachenmals verderbt worden. Für sie besteht die einzige Erlösung im Tod. Ihr habt meine Erlaubnis, auch ihr Leben zu beenden.", progress = "Ist es vollbracht? Ich hoffe nur, dass es noch nicht zu spät ist...", completion = "Gut gemacht, &lt;Name&gt;. Ich habe einen Weg gefunden, wie wir die versklavten Drachen in der Festung des Drachenmals befreien können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10837] = {title = "Zur Netherschwingenscherbe!", objective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 12 Netherrankenkristalle auf der Netherschwingenscherbe sammelt.", description = "Ich glaube, dass ich die Netherrankenkristalle mit meiner eigenen Essenz erfüllen kann. Die Macht in diesen magieerfüllten Kristallen sollte ausreichen, um die versklavten Drachen aus den Klauen ihrer Meister zu befreien.\n\nReist zur Netherschwingenscherbe, einer Insel am zerbrochenen Rand des Schattenmondtals im Südosten. Auf der Netherschwingenscherbe könnt Ihr die Netherrankenkristalle finden. Kehrt zu mir zurück, wenn Ihr genügend Kristalle gefunden habt, um Eure Taschen damit zu füllen.\n\nUnd Vorsicht, <Name>. Der Drachenmalklan hat sich nun auf der Insel niedergelassen.", progress = "Ich brauche Netherrankenkristalle.", completion = "&lt;Neltharaku nimmt Euch die Kristalle ab.&gt;\n\nIch werde nun die Kristalle mit meiner Magie erfüllen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10838] = {title = "Der dämonische Seher", objective = "Benutzt den dämonischen Seher im Höllenfeuerbecken, wartet, bis er sich eingestellt hat und führt dann eine Messung durch.\n\nBringt den dämonischen Seher und die Messungen des dämonischen Sehers zu Apotheker Antonivich in Thrallmar.", description = "Der dämonische Seher ist nun bereit. Bringt ihn hinter die Höllenfeuerzitadelle, in das Höllenfeuerbecken, und platziert ihn dort auf dem Boden. Er wird sich dann selbst auf die Höllenfeuerzitadelle einstellen. Sprecht danach mit dem Seher und schreibt auf, was Ihr erfahrt. Bringt Euren Aufschrieb zu mir...\n\nGeht, <Name>, aber erst, wenn Ihr bereit seid. Die Höllenfeuerzitadelle wird ohne Zweifel die Anwesenheit des Sehers entdecken und Wärter schicken, um ihn zu vernichten!", progress = "Habt Ihr die Messung? War Euer Auftrag mit dem dämonischen Seher erfolgreich?", completion = "Ihr habt die Messung? Ausgezeichnet. Ich bin mir sicher, dass diese Daten sich für unsere Forschungen als unersetzlich erweisen werden. Ich werde sie gleich an Apothekerin Zelana und Apotheker Albreck weiterleiten.\n\nIhr solltet stolz auf Euch sein, &lt;Name&gt;. Eure Stärke und Euer Mut steht außer Frage... genauso wie Eure Leistungen gegenüber der Horde.", rewards = "Ihr bekommt:\n\nGefängnis der Dämonenseele"}
MultiLanguageQuestData['de'][10839] = {title = "Dunkelstein des Skithverstecks", objective = "Benutzt die Rute der Läuterung bei Terokks Dunkelstein im Skithversteck und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste zurück.", description = "Das Skithversteck liegt nordwestlich der Karawane und südlich von Shattrath in einem Versteckten Hain im Wald. Man sagt, dass die Kolonie von Skettis dort einen bösartigen Altar der Verehrung errichtet hat. Wenn die Arakkoa der Skith jemals erlöst werden wollen, muss Terokks Dunkelstein zuerst geläutert werden.\n\nNehmt diese Rute der Läuterung und werft sie auf den Dunkelstein. Da sie von A'dal selbst gesegnet wurde, sollte die Reinheit der Rute stark genug sein, um den Dunkelstein zu reinigen. Nun geht. Möge das Licht über Euch wachen.", progress = "Die Dunkelheit umgibt uns. Was habt Ihr mir aus dem Skithversteck zu berichten?", completion = "Ich habe bis hierher die Explosion hören können. Nicht mit meinen Ohren, sondern mit meinem Herzen.\n\nWenn die Berührung des gesegneten Naaru A'dal nicht ausreicht, um die Arakkoa zu erlösen, dann kann nichts auf der Welt das schaffen. Diejenigen, die ihre Seele nicht dem Licht ausgeliefert haben, sind nichts als Diener des Bösen.\n\nSie müssen vernichtet werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10840] = {title = "Das Grab des Lichts", objective = "Hohepriester Orglum möchte, dass Ihr zum Grab des Lichts reist und 10 astrale Nethermanten und 10 astrale Brandschatzer tötet. Kehrt danach zu ihm zurück. Zu finden ist er bei der Flüchtlingskarawane.", description = "Im Osten, unter dem versengten Sand, befindet sich das Grab des Lichts. Das Grab ist eine verlorene Ruhestätte unserer Toten. Bevor unsere Karawane überfallen wurde, war ich auf dem Weg zu dem Grab, um es von bösen Geistern zu befreien.\n\nIch hatte ja keine Ahnung, dass es bereits von einem anderen Übel heimgesucht wird. Sogar jetzt noch plündern die Astralen die Körper unsere Gefallenen, um an die Schmuckstücke und Andenken zu kommen, die den Toten vor Jahrhunderten mit ins Jenseits gegeben wurden.\n\nAber ich kann nichts dagegen unternehmen, solange unsere Karawane ums Überleben kämpft.", progress = nil, completion = "Hier in der Wildnis der Scherbenwelt sind wir schwach. Nur wenige Helden verteidigen unsere Rechte, aber Ihr habt ihnen gezeigt, dass sie sich fürchten müssen, &lt;Klasse&gt;. Ich glaube nicht, dass die Astralen Euren starken Arm so schnell vergessen werden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10842] = {title = "Rachsüchtige Seelen", objective = "Hohepriester Orglum möchte, dass Ihr in das Grab des Lichts reist und 5 rachsüchtige Draenei besiegt.", description = "Das Grab des Lichts wurde vom Schattenrat verderbt und die toten Draenei wurden zu verfluchten Geistern, die von Zorn erfüllt sind und vor Hass auf die Lebenden brennen.\n\nBetretet das Grab", progress = "Ihr habt uns alle gerettet. Wie können wir Euch nur danken?", completion = "Ihr könnt nicht wissen, was Ihr hier getan habt, &lt;Name&gt;. Ihr habt so viele von uns aus einer ewigen Dunkelheit errettet. Ich kann nur wenig für die Lebenden tun und Euch nichts geben, das als Dank für Euch ausreichen würde. Nehmt Euch, was Euch nützlich erscheint.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nUralter Kriegstalisman der DraeneiUraltes Arkanrelikt der Draenei\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10843] = {title = "Seit ich denken kann...", objective = "Tötet Gnosh Brognat, den Anführer der Oger im Außenposten der Speerspießer.", description = "Schon seit ich denken kann haben wir gegen die Oger der Speerspießer gekämpft.\n\nWir haben es geschafft, sie so weit zurück zu drängen, dass sie nun nur noch im Außenposten der Speerspießer vertreten sind. Dieser Außenposten befindet sich dort, wo Ihr herkommt, am südwestlichen Rand des Messergrats.\n\nBeweist mir Euren Wert, indem Ihr ihren Anführer Gnosh Brognat tötet.\n\nWollen wir mal sehen, aus welchem Holz Ihr geschnitzt seid, wenn es darum geht, die Oger zu bekämpfen.", progress = nil, completion = "&lt;Leoroxx mustert Euch aufmerksam.&gt;\n\nGnosh Brognats Tod ist ein Segen für alle Mok'Nathal. Das ist gut für Euch.\n\nMal schauen, ob Ihr immer noch so heldenhaft seid, wenn wir die Messlatte etwas anheben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10844] = {title = "Konstruktionslager: Groll", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10845] = {title = "Tötet die Brutmutter", objective = "Tötet Unheilschwinge.", description = "Meine Jäger sind gerade von einer Aufklärungsmission im Singenden Bergrücken zurückgekehrt. Wie es aussieht hat sich die Zahl der Netherdrachen, die die Kristalle dort heimsuchen, deutlich vergrößert. Bald werden sie sich weiter ausbreiten!\n\nDa Ihr Euch als <fähiger/fähige:c> <Klasse> herausgestellt habt, wollen wir einmal sehen, ob Eure Fertigkeiten einem ausgewachsenen Drachen gewachsen sind.\n\nIhr findet den Singenden Bergrücken, indem Ihr nach Süden durch die Schuppenflügelbank geht. Tötet ihre Brutmutter, Unheilschwinge.", progress = nil, completion = "Nein! Ihr habt Unheilschwinge getötet? Vielleicht habe ich mich in Euch getäuscht, &lt;Klasse&gt;.\n\nVielleicht.\n\nDennoch habt Ihr die Anführer der drei größten Bedrohungen für unser Volk erschlagen. Darauf könnt Ihr stolz sein.\n\nIch werde Euch ein Zeichen meiner Wertschätzung geben, aber lasst es Euch nicht zu Kopf steigen. Ihr habt immer noch keine Ahnung davon, was es bedeutet, ein Mok'Nathal zu sein. Vielleicht werden wir immer noch auf Eure Fähigkeiten zurückkommen müssen.", rewards = "Gürtel aus Unheilschwinges HautNetherhauthandschuheGamaschen der BrutmutterBrustschutz des NetherbeschützersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10846] = {title = "Verständnis für die Mok'Nathal", objective = "Tötet Vekh, Anführer der Arakkoa der Vekh'nir.", description = "<Leoroxx schaut Euch mit einem Blick an, der Euch das Blut in den Adern gefrieren lässt.>\n\nIhr kommt zu den Mok'Nathal, aber Ihr versteht uns nicht. Ihr versteht unseren Kampf um Leben oder Tod nicht.\n\nWenn Ihr uns verstehen wollt, müsst Ihr Euch diesem Kampf aussetzen.\n\nIm Süden findet Ihr die Arakkoa der Vekh'nir. Sie halten eine Gruppe von Ogern in den Höhlen, die als Trogmas Besitz bekannt sind, als Sklaven. Dort findet Ihr auch ihren Anführer Vekh.\n\nTötet ihn!", progress = nil, completion = "Die Vekh'nir sind noch die harmlosesten unserer Feinde.\n\nIhr habt also einen übergroßen Vogel getötet. Das macht Euch noch lange nicht zu einem wahren Krieger. Das lässt Euch auch nicht unser Wesen verstehen.\n\nAber es ist ein Anfang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10847] = {title = "Die Augen von Skettis", objective = "Bringt das Auge des Reskkverstecks und das Auge des Shienorverstecks zu Rilak dem Erlösten im Unteren Viertel von Shattrath.", description = "Von den Klippen von Skettis zieht Unheil heraus.\n\nDas Schicksal meines Volkes, der Arakkoa, wird von einem unaussprechlichen Bösen verschleiert. Schon zu oft haben wir schwarze Magie für üble Taten eingesetzt. Durch A'dal erfuhren wir vom Licht und von der Erlösung.\n\nTerokk überwacht seine Kolonien von Skettis aus mithilfe von Sphären, die er mit seiner schwarzen Kunst verzaubert hat. Stehlt diese Augen aus dem Reskkversteck und dem Shienorversteck im nördlichen Terokkar. Ich möchte sehen können, was Terokk sieht. Lasst mich durch die Augen von Skettis schauen.", progress = "Ihr seid zurück, <Klasse>. Welche Neuigkeiten bringt Ihr?", completion = "Euer Mut sollte belohnt werden. Die Wachen von Skettis rücken ihre Besitztümer nur ungern heraus.\n\nAber die Heldentaten der Vergangenheit sind nun nicht von Belang. Wir sollten uns lieber darum kümmern, dass dieser Heldenmut auch in der Zukunft weiter herrscht, denn Terokks Blick richtet sich gen Süden.\n\nDiese Augen sehen alles.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErstklassiger HeiltrankErstklassiger Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10848] = {title = "Das untote Böse des Rhazeverstecks", objective = "Tötet 4 Todeskrallengeister, 4 kreischende Geister und 2 Geistraben und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", description = "Das Rhazeversteck war eine besonders bösartige Kolonie von Skettis.\n\nTrotz der Auslöschung seiner Bewohner durch die Katastrophe von Auchindoun hielt Terokk seinen Einfluss auf die bösartigen Geister dort aufrecht. Reist nach Westen zum Rhazeversteck und tötet diese mörderischen Schufte. Ihr findet sie westlich des Schattengrabs, an der Grenze zwischen der Knochenwüste und den Wäldern von Terokkar.\n\nDies wird unser erster Schlag gegen Terokk und die Wächter von Skettis werden.", progress = nil, completion = "Diese verderbten Geister haben es verdient zu sterben. Der Tod, den sie über alle anderen gebracht hätten, ist dafür Grund genug.\n\nEs besteht keine Hoffnung, dass wir die, die unter Terokks Einfluss stehen, erlösen können. Aber wir werden ihnen im Namen des Lichts ein Ende setzen.", rewards = "NachtlaubzauberstabFederumhüllter BogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10849] = {title = "Sucht Kirrik", objective = "Bringt Rilaks Schreiben zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste.", description = "Es waren noch andere Arakkoa an dem Verrat an Terokk beteiligt.\n\nKirrik erkannte in Terokk einen Scharlatan und keinen Propheten. Die einzige Prophezeiung, die Terokk vorausgesehen hat, war das Verderben, das auf seinen eigenen Wunsch heraufbeschworen wurde.\n\nEs war Kirrik, der uns mutig aus Skettis herausgeführt hat. Nach unserer Pilgerreise nach Shattrath ging Kirrik in alle anderen Kolonien, um nach Gleichgesinnten zu suchen.\n\nIn diesem Schreiben steht, was die Augen gesehen haben. Kirrik muss davon erfahren! Folgt der Straße nach Süden aus Shattrath hinaus zu der Knochenwüste und haltet nach der Karawane Ausschau.", progress = "Ihr seid weit gereist und bringt mir Nachrichten.", completion = "Rilaks Geschichte ist grausam, Reisender. Wie Ihr am Zustand der Karawane sehen könnt, gibt es dieser Tage viel Leid und Düsterkeit in den Wäldern von Terokkar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10850] = {title = "Nethergas in einem Teufelsfeuermotor", objective = "Ihr findet die Öffnung, durch die der Teufelshäscher betankt wird.", description = nil, progress = "Ihr findet die Öffnung, durch die der Teufelshäscher betankt wird.", completion = "Als Ihr den falschen Treibstoff einfüllt, beginnt der Motor des Teufelshäschers zu rumpeln und zu stottern.", rewards = nil}
MultiLanguageQuestData['de'][10851] = {title = "Die Totems meines Feindes", objective = "Sammelt 5 Totems der Speerspießer.", description = "Es gibt solche Wege, die Ahnen zu ehren, und es gibt andere Wege.\n\nDie Oger der Speerspießer tragen Totems bei sich, aber sie benutzten sie nicht, um ihre Ehrfurcht auszudrücken. Stattdessen wollen sie damit manipulieren und kontrollieren.\n\nWir sollten ihre Totems stehlen, denn sie sind unwürdig! Wir werden eine bessere Verwendung für sie finden.\n\nGeht zum Außenposten der Speerspießer im Westen, südwestlich des Messergrats. Erschlagt die Mystiker und Zermalmer der Speerspießer und nehmt ihnen die Totems ab!", progress = "Wart Ihr im Außenposten der Speerspießer und habt ihnen die Totems abgenommen?", completion = "Das sieht nach einer guten Sammlung aus. Wir sollten einen Weg finden können, sie respektvoll einzusetzen.\n\nIn der Tat habe ich sogar schon eine Idee!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10852] = {title = "Vermisste Freunde", objective = "Ethan möchte, dass Ihr 12 seiner vermissten Freunde im Skithversteck findet und sie zu ihm bei der Flüchtlingskarawane zurückbringt.", description = "Wir haben uns hier niedergelassen, weil des Nachts ein paar Kerle kamen und Radau gemacht haben. Es war gruselig. Ich weiß nicht, wann wir weitergehen werden.\n\nEinige meiner Freunde fehlen. Ich habe keine Ahnung, wo sie sind. Ich fürchte, diese schauerlichen Vogelmänner haben sie mit nach Nordwesten genommen. Wahrscheinlich haben sie sie in Käfige eingesperrt und all so was. Es wäre toll, wenn Ihr sie finden könntet. Ich mache mir Sorgen um sie.", progress = nil, completion = "Ihr habt all meine Freunde gefunden! Jetzt habe ich wieder jemanden, der mit mir spielt. Vielen Dank, Herr &lt;Name&gt;.\n\nDa ich jetzt wieder andere Kinder zum Spielen habe, könnt Ihr ja eins meiner Spielzeuge haben. Dann habt Ihr auch etwas zum Spielen.", rewards = "Ihr bekommt:\n\nRamponierte Dampfpanzersteuerung"}
MultiLanguageQuestData['de'][10853] = {title = "Geisteranrufung", objective = "Benutzt das Totem der Geisteranrufung, um 8 Geister eines geringen Netherdrachen zu sammeln.", description = "Die Geister der Netherdrachen im Singenden Bergrücken müssen befreit werden.\n\nDie Netherdrachen waren nicht immer Netherdrachen. Einst waren sie schwarze Drachen.\n\nDoch dann schwappte mit der Zerstörung dieser Welt eine Welle von Netherenergie über alles und veränderte die Eier der Drachlinge.\n\nSeitdem ist ihr eigenes Ich verzerrt. Wir müssen ihnen helfen, Frieden zu finden.\n\nDas erreicht Ihr, indem Ihr einen Drachen in der Nähe des Totems der Geisteranrufung tötet und ihm dann seine Seele nehmt.", progress = "Die Drachen des singenden Bergrückens sind vielleicht eine Bedrohung für uns, doch sie sind majestätische Wesen.\n\nOder sie waren es zumindest. Ich hoffe, dass Ihr ihre Geister retten könnt.\n\nUnd falls Ihr noch mehr Totems brauchen solltet, habe ich noch ein paar über.", completion = "Ihr habt heute eine große Tat vollbracht, &lt;Klasse&gt;. Die Geister der Drachen werden nun wieder singen können, denn sie sind frei. Und die Überreste ihrer Geister, die sie hinterlassen, dienen als mächtiges Heilmittel.\n\nHabt Ihr vielleicht Lust auf eine Reise in den Norden? Es gibt da eine Sache im Zusammenhang mit den Astralen, die mich brennend interessiert.\n\nIch fühle großen Schmerz aus dieser Richtung kommen.", rewards = "Nethererfülltes SchuhwerkChampionschulterschutz der Mok'NathalHelm des RitualistenNetherdrachenhandgelenksschützerIhr bekommt:\n\nHeilessenz eines Netherdrachen"}
MultiLanguageQuestData['de'][10854] = {title = "Die Macht Neltharakus", objective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 5 versklavte Drachen der Netherschwingen befreit.", description = "Nehmt diesen verzauberten Netherrankenkristall und begebt Euch zurück zur Festung des Drachenmals. Sucht nach den versklavten Drachen, wenn Ihr angekommen seid, und setzt die Magie des Kristalls frei. Meine eigenen Energien werden dafür sorgen, dass die Drachen ihre Fesseln abwerfen können. Wenn Ihr seht, dass ein Drache freigekommen ist, helft ihm schnell seinen Kerkermeister zu vernichten! Sie sind von der Gefangenschaft sicherlich noch geschwächt.\n\nLasst alle frei, die Ihr finden könnt und kehrt dann zu mir zurück, <Name>!", progress = "Verschwendet keine Zeit, wir haben viel zu tun!", completion = "&lt;Neltharaku lacht.&gt;\n\nDie Orcs müssen einen ganz schönen Schreck bekommen haben, als die Drachen sich plötzlich gegen sie gewendet haben. Gut gemacht, &lt;Name&gt;. Vielleicht seid Ihr wirklich der Held unseres Schwarms.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10855] = {title = "Teufelshäscher, nein Danke!", objective = "Beschafft Euch 5 Einheiten kondensiertes Nethergas von den Robogenieuren der Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt sie in einen deaktivierten Teufelshäscher. Kehrt danach zu Netherpirscher Nauthis zurück.", description = "Ah ja, der Teufelshäscher! Das ist sicherlich die schrecklichste mechanische Erfindung der Legion. Und nicht weniger als drei dieser Abscheulichkeiten sind direkt auf die Sturmsäule gerichtet.\n\nZu unserem Glück sind sie noch nicht aktiviert. Das gibt uns die Möglichkeit, dieses Problem mit Sabotage anstatt mit roher Gewalt zu lösen.\n\nBeschafft Euch kondensiertes Nethergas von den Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt es in den Tank eines Teufelshäschers. Ich glaube, sein Motor wird sich nicht allzu sehr darüber freuen.", progress = nil, completion = "Das sind ausgezeichnete Nachrichten, &lt;Name&gt;. Jetzt, da wir wissen, wie wir mit ihnen zu verfahren haben, kann ich ein paar Leute anheuern, um die übrigen Häscher zu sabotieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10856] = {title = "Die beste Verteidigung", objective = "Netherpirscher Nauthis möchte, dass Ihr 12 Zornschaffer in der Konstruktionsbasis: Gehenna nördlich der Sturmsäule vernichtet.", description = "Mutige Industriesabotage wird uns leider nur bis zu einem gewissen Punkt weiterbringen, <Name>. Genauso wie die Konstruktionsbasis: Vergessenheit als Produktionsstätte für die Teufelshäscher dient, ist die Konstruktionsbasis: Gehenna sowohl ein Stützpunkt für ihre Armee, als auch der Ort, an dem sich die meisten Teleporter der Legion befinden.\n\nIch möchte, dass Ihr dorthin geht, und ihre Zahl tüchtig verringert. Bis heute müssen sie ein volles Regiment von Zornschaffern angesammelt haben. Das dürfen wir nicht zulassen!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Macht weiter so, dann werde ich beim Nexusprinzen ein gutes Wort für Euch einlegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10857] = {title = "Teleportiert das!", objective = "Netherpirscher Nauthis möchte, dass Ihr den Stab der geistigen Beeinflussung bei den Mo'arg in der Konstruktionsbasis: Gehenna einsetzt und ihre Fähigkeit 'Teleporter sprengen' bei den drei Teleportern in der Konstruktionsbasis benutzt.", description = "So lustig es auch sein mag, Dämonen zu töten, so wenig hilft es uns, wenn die Legion weiterhin ihre Teleporter benutzen kann, um jeden Dämon, den wir töten, zu ersetzen.\n\nUnglücklicherweise habe ich gerade keinen hochwertigen Sprengstoff zur Hand... aber die Mo'arg, die die Teleporter warten, schon!\n\nNehmt diesen Stab... Ich habe seine Kraft so eingestellt, dass er die Gehirnströme der Mo'arg beeinflussen kann. Kehrt zur Konstruktionsbasis: Gehenna zurück und beeinflusst jeden Mo'arg, den Ihr seht. Viel Zeit bleibt Euch nicht, aber sie wird reichen, um ihre Sprengladungen bei den Teleportern in der Nähe zu benutzen.", progress = "Ist es vollbracht? Sind die Teleporter außer Gefecht?", completion = "Dank Euch kann ich wieder etwas durchatmen, &lt;Name&gt;. Das meine ich natürlich im übertragenen Sinne!\n\nIch nehme an, Ihr wollt nun eine Art Belohnung, oder?", rewards = "Runenverzierter SilberstabAxt des SaboteursKlinge des NetherpirschersAuf Euch wartet eine dieser Belohnungen:\n\nMagieerfüllter Draenethystkristall\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10858] = {title = "Karynaku", objective = "Sucht nach Karynaku in der Festung des Drachenmals.", description = "Ich schäme mich, Euch erneut um Hilfe zu bitten, <Name>, aber Ihr seid die einzige Hoffnung meines Schwarms. Ohne mein Weibchen stirbt die Brut der Netherschwingen vielleicht ganz aus!\n\nMacht Euch auf den Weg zur Spitze der Festung des Drachenmals und findet Karynaku.\n\nWir werden über Euch fliegen. Sollte sich ein Loch in ihrer Verteidigung auftun, wird die geballte Macht der Netherschwingen Euch zu Hilfe eilen.", progress = nil, completion = "Es sind die Ketten. Sie berauben mich meiner Macht. Der einzige Ausweg ist, den Schlüssel von Zuluhed zu beschaffen und mich loszuketten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10859] = {title = "Sammelt die Kugeln", objective = "Benutzt das Kugelfängertotem, um 15 Lichtkugeln der Razaani zu sammeln.", description = "Die Astralen der Razaani haben merkwürdige Geräte, aus denen kleine, rosafarbene schwebende Lichtkugeln herauskommen. Sie erinnern mich an Seelen.\n\nMan darf sie nicht mit den großen gelben Kugeln verwechseln, die sich aus den Astralen lösen, wenn sie sterben. Diese hier sind ganz anders.\n\nIch möchte, dass Ihr nach Norden zu Razaans Landeplatz geht und ein paar Totems aufstellt, die die rosafarbenen Lichtkugeln anziehen.\n\nBringt sie zu mir zurück, damit ich genau herausfinden kann, aus was sie bestehen.", progress = "Habt Ihr alle Lichtkugeln der Razaani, die ich brauche, gesammelt?", completion = "Etwas fühlt sich hier falsch an.\n\nBitte, &lt;Name&gt;, reicht mir das Totem. Ich muss diese Kugeln untersuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10860] = {title = "Leckerbissen der Mok'Nathal", objective = "Sammelt 3 Raptorenrippchen und 3 Stück Schlangenfleisch.", description = "Seid Ihr hungrig, <Volk>? Der große Geist hilft denen, die sich selbst helfen. Wenn Ihr Euch ein Essen verdienen wollt, schlage ich vor, dass Ihr zuhört, denn Braagor da drüben wird Euch nichts umsonst geben, zumindest nichts, was so schmackhaft wäre.\n\nDie Raptoren und Schuppenflügel des Messergrats und der Schuppenflügelbank haben alles, was man für zwei der schmackhaftesten Gerichte, die Ihr je zu essen bekommen werdet, braucht. Bringt mir ihre Raptorenrippchen und das Schlangenfleisch, und ich werde Euch beide zubereiten.\n\nIch kann Euch auch beibringen, sie selbst zu kochen, wenn Ihr in Eile seid.", progress = "Habt Ihr alle Zutaten schon? Darüber zu reden hat mir das Wasser im Munde zusammenlaufen lassen!", completion = "Mmm, ich kann sie schon schmecken! Schnell, reicht mir die Zutaten... Ich werde sie rasch klein würfeln und dann ab damit aufs Feuer!\n\nZu Eurem Glück hält sich das Zeug lange, und ich meine damit sehr lange! So, nehmt dies. Und da Ihr so freundlich wart, meine Speisekammer aufzufüllen, gebe ich Euch die Rezepte gleich noch dazu.", rewards = "Ihr bekommt:\n\nRippchen der Mok'NathalKnusperschlangeRezept: Rippchen der Mok'NathalRezept: Knusperschlange"}
MultiLanguageQuestData['de'][10861] = {title = "Präventivschlag gegen das Lithicversteck", objective = "Zerbrecht die verfluchten Eier im Lithicversteck. Erlöst 3 Jungtiere und tötet 3 bösartige Jungtiere. Kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", description = "In der verachtungswürdigen Kolonie im Südwesten, die als Lithicversteck bekannt ist, versuchen die Diener Terokks ihre geflügelten Brüder schon vor dem Schlüpfen zu verderben. Die schwarzen Zauberer von Lithic belegen die Eier mit einem schattenhaften Fluch. Wenn die Küken schlüpfen, sind sie bereits willenlose Diener Terokks.\n\nReist ins Lithicversteck und zerbrecht die Eier, bevor der Fluch wirken kann. Sogar wenn es dazu schon zu spät ist, könnt Ihr die verderbten Eier vernichten.\n\nDenkt daran, in der Dunkelheit strahlt das Licht noch heller.", progress = nil, completion = "Es ist eine grausame Aufgabe, Jungtiere zu quälen, und doch wäre es unverzeihlich, das wachsende Böse zu ignorieren. Ihr habt gute Arbeit geleistet. A'dals Gunst leuchtet auf Euch herab.", rewards = "Armschienen mit AdlergravurGefiederte ArmbindenArmschienen des KrallenpirschersGefiederte HandgelenksmanschettenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10862] = {title = "Auslieferung an die Horde", objective = "Rokag möchte, dass Ihr Rilak den Erlösten im Unteren Viertel von Shattrath aufsucht und von ihm fordert, dass er und sein Volk sich der Horde ausliefern.", description = "Die feigen Arakkoa greifen uns täglich an. Sie lauern unseren Jägern auf und plündern ab und an sogar innerhalb unserer Stadtmauern! Wir töten sie, wenn wir können, aber ihre Magie ist stark und sie schaffen es oft, unseren Truppen zu entkommen.\n\nIch habe erfahren, dass einige Arakkoa der Horde gegenüber freundlich gesonnen sein sollen. Sie leben in Shattrath im Nordwesten. Ihr Anführer nennt sich Rilak der Erlöste. Sucht im Unteren Viertel nach ihm und fordert ihn auf, sich auszuliefern.", progress = nil, completion = "Euer Volk ist wütend, aber ich kann nicht viel dagegen tun. Einige von uns wurden von der Macht der Naaru berührt und für alle Zeiten verändert. Doch diejenigen von uns, die in der Wildnis leben, sind noch immer so, wie wir damals waren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10863] = {title = "Geheimnisse der Arakkoa", objective = "Lady Dena Kennedy möchte, dass Ihr Rilak den Erlösten im Unteren Viertel von Shattrath aufsucht und herausfindet, welche Geheimnisse der Arakkoa mit Euch teilen wird.", description = "Hier an der Front müssen wir uns Tag für Tag mit den Arakkoa herumschlagen. Sie greifen uns an, wenn es ihnen gerade passt, plündern unsere Vorräte und erschlagen unsere Späher.\n\nUnd doch wissen wir nur wenig über diese rätselhaften Kreaturen. Ich habe Informationen erhalten, denen zufolge in Shattrath im Nordwesten einige Arakkoa leben sollen, die nicht so feindselig sind und vielleicht die Geheimnisse ihres Volks mit uns zu teilen bereit sind.\n\nRilak der Erlöste ist ihr Anführer. Er lebt im Norden des Unteren Viertels.", progress = nil, completion = "Es war sehr weise von Euch, mich aufzusuchen. Es gibt vieles, was ich Euch zeigen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10864] = {title = "Eine Last auf der Seele", objective = "Tötet 20 Orcs der Zerschmetterten Hand und kehrt danach zu Apotheker Antonivich in Thrallmar zurück.", description = "Ich habe ein Gerät, mit dem man Teufelsmagie analysieren kann, der dämonische Seher. Ich würde Euch den Seher ja benutzen lassen, aber zunächst müsst Ihr ihn... besänftigen. Ihr müsst wissen, dass innerhalb des Sehers ein Wesen von höchster Intelligenz steckt, das einige, sagen wir, exzentrische Bedürfnisse hat.\n\nUm den Seher zu besänftigen, müsst Ihr Orcs töten, insbesondere die Orcs der Zerschmetterten Hand. Der Seher verlangt ihre Seelen.\n\nKehrt zu mir zurück, wenn Ihr die Seelen geerntet habt. Ihr findet die Orcs nördlich, südlich und um die Höllenfeuerzitadelle herum.", progress = "Der dämonische Seher ist noch nicht besänftigt, <Name>. Kehrt zu mir zurück, nachdem Ihr die Seelen der Orcs der Zerschmetterten Hand geerntet habt.", completion = "Gut gemacht, &lt;Name&gt;. Eure Seele ist mit vielen Toden belastet... und der dämonische Seher wird nun seine Pflicht für Euch erfüllen.\n\nWollen wir hoffen, dass Ihr für das Folgende gewappnet sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10865] = {title = "Informiert Leoroxx!", objective = "Sprecht mit Leoroxx darüber, was die Astralen der Razaani treiben. Ihr findet ihn im Dorf der Mok'Nathal im Schergrat.", description = "Schnell, Ihr müsst Leoroxx über die Geschehnisse bei Razaans Landeplatz informieren.\n\nDiese Kugeln wurden aus Seelen geschaffen, einige davon Seelen der Mok'Nathal!", progress = nil, completion = "Ist das, was Ihr da sagt, überhaupt möglich? Was sage ich da? Natürlich ist es das, wenn der Geistrufer davon überzeugt ist.\n\nErinnert Ihr Euch noch, als ich sagte, dass wir vielleicht wieder Eure Hilfe brauchen würden? Wie es scheint, kann ich in die Zukunft sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10866] = {title = "Zuluhed der Geschlagene", objective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", progress = "<Karynaku brüllt.>", completion = "Ich bin frei! Ihr habt uns gerettet, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10867] = {title = "Es kann nur eine Antwort geben", objective = "Beschafft Euch die Seelensammlung.", description = "Es kann nur eine Antwort auf diese... diese SCHÄNDUNG der Seelen unserer Vorfahren geben!\n\n<Name>, wenn Ihr uns helfen wollt, die Seelen unserer verehrten Toten zu ihrem richtigen Platz zurück zu bringen, dann kehrt zu Razaans Landeplatz zurück.\n\nGeht dorthin zurück und tötet die Razaani bis ihr Anführer, Nexusprinz Razaan, sein feiges Gesicht zeigt. Tötet ihn, beschafft Euch die Seelen zurück und übergebt sie Geistrufer Dohgar!", progress = "Habt Ihr es getan? Sind die Seelen unserer Vorfahren sicher vom Bösen der Astralen?", completion = "Es ist gut, dass der Abschaum der Astralen und ihr Anführer tot sind. Ich wünsche ihren Brüdern tausend Plagen auf den Hals!\n\nIhr sollt für Eure Taten im Namen aller Mok'Nathal belohnt werden, &lt;Name&gt;! Ihr seid wirklich ein Held für uns!\n\nLasst uns nun die Seelen unserer Vorfahren dem reinigenden Feuer übergeben.", rewards = "Mantelung der Mok'NathalMaske des GeistrufersHeldenpantalons der Mok'NathalGürtel des SeelenrettersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10868] = {title = "Der Kriegspfad der Arakkoa", objective = "Beraterin Faila bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihr in der Steinbrecherfeste zurück.", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt, um zu entkommen, bevor wir losstürmen und ihnen Auge in Auge entgegentreten konnten. Sie benutzen ihre Beschwörungskreise, um ihre Krieger von dem sicheren Tod zu retten, aber wenn wir ihr Zuhause angreifen, können sie uns nicht entkommen. Das Reskkversteck und das Shienorversteck liegen im Norden und Nordosten.\n\nSucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Die Arakkoa haben gelernt, die Macht der Horde zu fürchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10869] = {title = "Die Herde ausdünnen", objective = "Leutnant Kieshammer bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihm in Allerias Feste zurück.", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt, um zu entkommen, bevor wir unsere Soldaten losschicken konnten.\n\nDas Reskkversteck und das Shienorversteck liegen im Norden und Nordwesten. Sucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt. Vielleicht fürchten sie uns nicht, aber wir können ihre Zahl dennoch verringern!", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Die Arakkoa haben gelernt, die Macht der Allianz zu fürchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10870] = {title = "Verbündeter der Netherschwingen", objective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", description = "Erlaubt mir, Euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", progress = nil, completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", rewards = "Beschützerschild der NetherschwingenVerteidigerschild der NetherschwingenKlaue des NetherschwingenschwarmsAuf Euch wartet eine dieser Belohnungen:\n\nSpiritualistentalisman der NetherschwingenZauberertalisman der Netherschwingen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10871] = {title = "Verbündeter der Netherschwingen", objective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", description = "Erlaubt mir, euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", progress = nil, completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", rewards = "Beschützerschild der NetherschwingenVerteidigerschild der NetherschwingenKlaue des NetherschwingenschwarmsAuf Euch wartet eine dieser Belohnungen:\n\nSpiritualistentalisman der NetherschwingenZauberertalisman der Netherschwingen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10872] = {title = "Zuluhed der Geschlagene", objective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", progress = nil, completion = "Ich bin frei! Ihr habt uns gerettet, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10873] = {title = "Bei Nacht verschleppt", objective = "Späher Navrin möchte, dass Ihr zum Netherweberkamm reist und 6 eingesponnene Verteidiger der Sha'tar befreit. Kehrt danach zu Navrin ins Basislager der Sha'tari zurück.", description = "Unser kleiner Außenposten wird ständig angegriffen. Vor ein paar Nächten haben die Spinnen des Netherweberkamms, der am südöstlichen Ende der Knochenwüste liegt, unser Lager überfallen. Sie haben viele von uns vergiftet, in ihre Netze gewickelt und fort getragen. Einige unserer Krieger haben zu den Waffen gegriffen und sind den Spinnen todesmutig in die finstere Nacht gefolgt.\n\nWir haben weder die Gefangenen noch die Krieger seit diesem Tag wieder gesehen. Wir hoffen, dass sie noch am Leben sind. Vielleicht halten die Spinnen sie gefangen? Wir sind nur so wenige. Könnt Ihr nach unseren Leuten suchen?", progress = nil, completion = "Ihr habt so viele gerettet. Ich habe nicht geglaubt, dass wir sie je wieder sehen würden. Wir können Euch nicht genug danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10874] = {title = "Signalfeuer des Shalasverstecks", objective = "Kirrik der Erwachte bei der Flüchtlingskarawane möchte, dass Ihr die vier Signalfeuer des Shalasverstecks löscht.", description = "Über der Knochenwüste im Osten wirft Skettis, der lange Arm Terokks, bedrohlich seine Schatten. Am Fuße von Skettis liegt das Shalasversteck, Terokks vortrefflichste Kolonie. Von diesem Stützpunkt aus führen Terokks Diener Krieg gegen das Licht.\n\nDie Unholde der Shalas kommunizieren über ein komplexes System aus magischen Signalfeuern mit ihrem Meister. Reist nach Osten, <Volk>, und löscht die Feuer. Sobald das Shalasversteck zum Schweigen gebracht wurde, können wir den Fall von Skettis planen.\n\nAber ich greife mir selbst vor.", progress = nil, completion = "Wir haben gesehen, wie der verfluchte Rauch aufgestiegen ist. Ihr seid außergewöhnlich mutig, &lt;Klasse&gt;.", rewards = "Umhang der GreifkrallenWeisenschal der ArakkoaAuf Euch wartet eine dieser Belohnungen:\n\nKokoreks Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10875] = {title = "Bericht an Nazgrel", objective = "Sprecht mit Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "<Name>, während Eures Auftrags mit dem dämonischen Seher habe ich einen Bericht über Eure Taten gegen die Höllenorcs geschickt. Nazgrel, unser berühmter Anführer in Thrallmar, möchte mit Euch sprechen. Ich glaube, er hat einen blutigen Auftrag für Euch...", progress = nil, completion = "Es ist schön, von Euren Schachzügen gegen die Höllenorcs zu erfahren, &lt;Name&gt;. Die Apotheker haben viel Zeit und viel Mühe aufgewendet, um hinter den Grund der Verderbnis zu kommen, und auch wenn diese Informationen sicher unersetzlich sind... schreit mein Orcblut danach, diesen Verrätern einen anständigen Schlag zu verpassen!\n\nHört genau zu, wenn ich Euch Eure Aufgabe erkläre...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10876] = {title = "Am Fuße der Zitadelle", objective = "Tötet Truppenkommandant Gorax, platziert die Herausforderung der Horde auf seinem Leichnam. Tötet danach die Hand von Kargath und bringt den Kopf der Hand von Kargath zu Nazgrel in Thrallmar.", description = "Truppenkommandant Gorax trainiert die Hauptmänner am Fuß der Höllenfeuerzitadelle und drillt sie, bis sie so scharf wie Rasierklingen sind. Ihr müsst ihn töten, <Name>. Sein Verlust wäre ein großer Schaden für die Höllenorcs.\n\nDas ist jedoch nicht alles, was Ihr tun müsst.\n\nNehmt dieses Banner. Platziert es auf Gorax' Leichnam. Wenn auch nur ein Tropfen echtes Orcblut in seinem Körper steckt, muss sein Kommandant, die Hand von Kargath, Eure Herausforderung annehmen!\n\nSein Kopf, der Kopf der Hand von Kargath, ist das, was ich begehre.", progress = "Habt Ihr Euch der Hand von Kargath gestellt, <Name>?", completion = "Ihr habt eine große Tat geleistet, &lt;Name&gt;. Die Höllenorcs sind eine Schande für alle wahren Orcs. Wenn wir eine Angst haben, so ist es die, erneut einer dämonischen Verderbnis zu verfallen. Unser Krieg gegen die Höllenorcs ist also mehr als nur eine Schlacht gegen schlimme Feinde, es ist eine Schlacht in uns selbst.\n\nUnd mit einer Stärke, wie Ihr sie heute bewiesen habt, werden wir diese Schlacht gewinnen.", rewards = "SchattenzaubertunikaDunkelsturmtunikaSturmschlagwesteBrustplatte des KampfmeistersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10877] = {title = "Das Schreckensrelikt", objective = "Oakun möchte, dass Ihr nach Osten zur Herrenlosen Karawane reist und das Schreckensrelikt besorgt. Kehrt zu Oakun zurück, wenn Eure Aufgabe erledigt ist.", description = "Vor langer Zeit machte sich eine Karawane auf den Weg nach Auchindoun mit der Mission, ein Schreckensrelikt aus den uralten Gräbern unter der Stadt der Toten zu bergen. Sie sind geflohen, aber das Relikt sollte ihr Untergang sein. Das Relikt ist böse und ruft Böses herbei, wenn es berührt wird. Ihre Karawane wurde irgendwo im Osten vernichtet.\n\nDieses finstere Artefakt ist der Schlüssel zu meinem schrecklichen Plan, Teribus den Verfluchten zu töten, eine Kreatur, die über der Knochenwüste ihre Kreise zieht. Wenn Ihr wünscht, könnt Ihr mir helfen, aber Euer Leben und Eure Seele stehen dabei auf dem Spiel.", progress = "Habt Ihr das Schreckensrelikt? Wir müssen es bekommen.", completion = "Es ist unglaublich, dass Ihr es geschafft habt. Das Schreckensrelikt ist viel mächtiger, als ich befürchtet hatte. Nur ein starker Held hätte die lange Rückreise mit so einem blasphemischen Gegenstand überlebt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10878] = {title = "Bevor die Dunkelheit sich senkt", objective = "Mekeda bei der Flüchtlingskarawane möchte, dass Ihr 8 Scharmützler der Kabale, 4 Zauberwirker der Kabale und 2 Initianden der Kabale tötet.", description = "Nachdem unsere Karawane einem Angriff von Kultisten der Kabale des Schattenrats zum Opfer gefallen ist, wurden Späher auf der Suche nach Hilfe nach Shattrath geschickt. Die Wachen denken, wir sind vorerst sicher, aber sie unterschätzen diese Verrückten.\n\nIch freue mich jedenfalls nicht darauf, mir meine Kehle von irgendeinem Initianden der Kabale mitten in der Nacht durchschneiden zu lassen. Tut uns allen einen Gefallen und greift sie an, bevor sie es tun.\n\nIhr findet unsere Angreifer südlich von hier, am nördlichen Eingang von Auchindoun.", progress = nil, completion = "Vorerst kann ich erleichtert durchatmen, &lt;Name&gt;. Der Schattenrat wird sich bis auf weiteres zurückhalten.\n\nSie sind Mörder und Feiglinge. Eure Zurschaustellung von Mut wird sie einschüchtern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10879] = {title = "Offensive aus Skettis", objective = "Haltet die Angreifer auf und sprecht mit Rilak den Erlösten.", description = "Skettis hat uns den Krieg erklärt! Habt Ihr genug Kraft für die Verteidigung Shattraths gesammelt?\n\nHaltet die Angreifer auf!", progress = "Wir haben jetzt keine Zeit für einen Plausch, <Name>. Wir werden angegriffen! Haltet die Eindringlinge auf!", completion = "Ich ziehe meinen Hut vor Euren Kampfkünsten, &lt;Klasse&gt;. Ihr habt Euch als wahrer Verteidiger des Lichts bewiesen. Möge A'dals Segen in Euren dunkelsten Stunden auf Euch ruhen.\n\nDoch seht zum fernen Horizont. Dunkle Wolken ziehen unheilvoll über Skettis herauf. Sicher plant Terokk schon seinen nächsten Schachzug. Für heute ist Shattrath gerettet. Doch wer weiß schon, welch Verderben der nächste Tag über uns alle bringen wird.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHalsreif aus blutigen FedernHalskette der verfluchten Federn\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10880] = {title = "Befehle der Kabale", objective = "Bringt die Befehle der Kabale zu Mekeda bei der Flüchtlingskarawane in der Knochenwüste.", description = "Die Botschaft trägt ein dunkles Siegel. Auch wenn Euch die Sprache bekannt vorkommt, scheint der Text verschlüsselt zu sein.\n\nVielleicht weiß jemand bei der Flüchtlingskarawane etwas darüber.", progress = "Wollt Ihr mir etwas zeigen, <Name>?", completion = "Ah, ja... dieser Text wurde in einer einfachen Form der Geheimschrift der Schatten geschrieben. Mein Wissen darüber ist nicht perfekt, aber es sollte ausreichen, um sie zu übersetzen.\n\nMan kann viel von den zwielichtigen Gestalten lernen, wenn man unter den Ausgestoßenen und Flüchtlingen im unteren Viertel lebt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10881] = {title = "Das Schattengrab", objective = "Geht in das Schattengrab westlich der Flüchtlingskarawane und beschafft Euch Arunens Tuch, K'alens Hammer und Atalors Schriftrolle. Kehrt danach zu Mekeda bei der Flüchtlingskarawane zurück.", description = "Viele glauben, dass der Schattenrat die Explosion, die Auchindoun in tausend Stücke gerissen hat, verursacht hat. Gerüchten zufolge sollen sie im Inneren ein großes Übel erweckt haben.\n\nWenn das stimmt, muss dieses Böse sich gegen sie gewandt haben. Laut diesen Befehlen flieht ein Teil des Schattenrats aus Auchindoun. Sie benutzen das Schattengrab, um mächtige Artefakte aus Auchindoun zu lagern.\n\nDrei dieser Artefakte sind heilig, denn sie gehörten den mächtigen Patriarchen Arunen, K'alen und Atalor. Ich muss Euch bitten, sie wieder zu holen.", progress = "Habt Ihr die Relikte, <Name>? Wir können nicht zulassen, dass der Schattenrat sie für seine dunklen Zwecke einsetzt.", completion = "Das Licht hat mich vielleicht vergessen, aber ich habe das Licht nicht vergessen. Diese Relikte waren meinem Volk einst sehr heilig.\n\nDem Schattenrat zu erlauben, sie für Böses einzusetzen ist... undenkbar!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegelerbstück der WillenskraftSiegelerbstück der Erde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10882] = {title = "Herold der Verdammnis", objective = "Ihr wurdet beauftragt, zur Arkatraz in der Festung der Stürme zu reisen und Herold Horizontiss zu töten. Kehrt danach zu A'dal auf der Terrasse des Lichts in Shattrath zurück.", description = "<Ein Missklang ertönt in A'dals 'Stimme'.>\n\nPrinz Kael'thas hat seine Wärter schlampig ausgewählt, und nun brechen die Wesenheiten, die in der Arkatraz eingesperrt waren, aus.\n\nBesonders eine davon, ein Diener der Alten Götter, der als Herold Horizontiss bekannt ist, versucht, die Vision seines Meisters von der Eroberung aller Welten in diesem Universum in die Tat umzusetzen.\n\n<Name>, Ihr dürft nicht zulassen, dass er entkommt. Kehrt zur Festung der Stürme zurück und begebt Euch in die Arkatraz. Tötet Herold Horizontiss, bevor es zu spät ist!", progress = nil, completion = "&lt;Das kristallene Klingen von A'dals Stimme fließt in einer deutlich ruhigeren Melodie als die letzten beiden Male, in denen Ihr miteinander gesprochen habt.&gt;\n\nWieder einmal habt Ihr Euren Eifer bewiesen. Wenn Herold Horizontiss ausgebrochen wäre, wären Tausende dem Konflikt zum Opfer gefallen, genauso, wie es bei einem anderen Diener der alten Götter, Skeram, auf Eurer Welt Azeroth geschehen ist.\n\n&lt;Name&gt;, was ich Euch als Belohnung anbiete, scheint im Vergleich erbärmlich zu sein, aber seid Euch bewusst, dass die ewige Dankbarkeit der Sha'tar damit verbunden ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMächtiger Anhänger der Sha'tariA'dals Halskette der ErholungMachtvoller Halsreif von Shattrath\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10883] = {title = "Der Schlüssel der Stürme", objective = "Sprecht mit A'dal in Shattrath.", description = "Ihr habt Euch in großen Taten bewiesen, <Name>. Eure Entdeckung der Litanei der Verdammnis und Kael'thas' Rolle dabei sind für unsere Sache von äußerster Wichtigkeit. Sollte Kael'thas die Litanei benutzen, würde der kleine Rest, der noch von dieser Welt übrig ist, in sich zusammenfallen.\n\nA'dal ist davon überzeugt, dass Kael aufgehalten werden muss und ist nun auf der Suche nach Abenteurern, die sich seinen Prüfungen unterziehen möchten. Die Naaru werden denjenigen, die ihre Stärke beweisen, ihre Gunst gewähren.\n\n<Khadgar nickt.>\n\nA'dal erwartet Euch...", progress = nil, completion = "Die Festung der Stürme ist eine Erfindung der Naaru, Sterblicher. Zutritt zu der Festung zu gewähren lag schon immer alleine im Ermessen der Naaru. Eine Rückkehr zur Festung der Stürme erschien uns jedoch unnötig. Vielleicht mag das für ein sterbliches Volk wie Stolz aussehen, doch wir Naaru halten nur wenig von solchen Dingen.\n\nWir gehen nun, weil wir es müssen. Kael'thas darf die Litanei der Verdammnis niemals vorlesen.\n\nAuch wenn der Weg offen steht, so würde sich nur ein Narr unerprobt hineinwagen. Unterschätzt nicht den Zweck der Prüfungen, Sterblicher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10884] = {title = "Die Prüfung der Naaru: Erbarmen", objective = "A'dal in Shattrath möchte, dass Ihr die unbenutzte Axt des Henkers aus den Zerschmetterten Hallen der Höllenfeuerzitadelle besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle werden drei Leute Eures Volkes von dem erbarmungslosen Kargath Messerfaust gefangen gehalten. Er hat vor, sie als Zeichen seiner Männlichkeit und Stärke hinzurichten. Ihr müsst diese Gefangenen retten, bevor eine solche Grausamkeit geschehen kann. Bringt mir die unbenutzte Axt des Henkers als Beweis Eurer Tat. Es darf kein einziger Tropfen Blut an der Klinge sein!", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt die Prüfung des Erbarmens abgeschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10885] = {title = "Die Prüfung der Naaru: Stärke", objective = "A'dal in Shattrath möchte, dass Ihr Kalithreshs Dreizack und Murmurs Essenz besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nDie Prüfung der Stärke besteht aus zwei Teilen. Ihr müsst den Anführer der Dampfkammern des Echsenkessels, Kriegsherr Kalithresh, töten und mir seinen Dreizack bringen. Außerdem müsst Ihr das außerdimensionale Wesen Murmur im Schattenlabyrinth in Auchindoun erlegen und mir seine Essenz bringen.\n\nWenn Ihr dies geschafft habt, habt Ihr die Prüfung der Stärke bestanden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt die Prüfung der Stärke abgeschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10886] = {title = "Die Prüfung der Naaru: Zuverlässigkeit", objective = "A'dal in Shattrath möchte, dass Ihr Millhaus Manasturm aus der Arkatraz in der Festung der Stürme rettet.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nAuf unseren Reisen haben wir viele gefährliche Wesen getroffen. Einige dieser Wesen wurden eingefangen und werden nun an Bord der Arkatraz in der Festung der Stürme gefangen gehalten.\n\nEiner der Gefangenen ist jedoch Opfer eines unglücklichen Zufalls. Er war zur falschen Zeit als blinder Passagier auf dem falschen Schiff der Naaru unterwegs.\n\nReist zur Arkatraz und rettet den Gnom Millhaus Manasturm. Stellt sicher, dass er überlebt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr habt die Prüfung der Zuverlässigkeit abgeschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10887] = {title = "Flucht aus dem Grab", objective = "Helft Akuno zur Flüchtlingskarawane zu gelangen. Sprecht danach mit Mekeda.", description = "Ich weiß Eure Hilfe zu schätzen, <Name>. Ich war mir sicher, dass ich sterben würde.\n\nLasst uns schnell von hier verschwinden. Bald werden uns noch mehr Kultisten auf den Fersen sein.", progress = nil, completion = "Ihr habt Akuno, meinen geschätzten Freund, errettet. Dafür stehe ich in Eurer Schuld, &lt;Name&gt;.", rewards = "Akunos KlingeUraltes Wappen der DraeneiAuf Euch wartet eine dieser Belohnungen:\n\nMekedas GabeAusgegrabene Kugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10888] = {title = "Die Prüfung der Naaru: Magtheridon", objective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", progress = "<A'dal grüßt Euch.>", completion = "Ihr habt Euch als Wesen mit großer Macht bewiesen. Die Naaru sind sich einig...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSchlüssel der Stürme herstellen\n\nIhr bekommt:\n\nBand des Phönixfeuers"}
MultiLanguageQuestData['de'][10889] = {title = "Rückkehr nach Shattrath", objective = "Reist nach Shattrath und Sprecht mit Rilak den Erlösten im Unteren Viertel.", description = "Auch wenn Eure Taten sehr mutig waren, wird Terokk sicher nicht lange auf seine Rache warten lassen.\n\nGeht schnell nach Shattrath! Verständigt Rilak!", progress = nil, completion = "Die Wachen von Skettis werden langsam unruhig. Shattrath steckt in Schwierigkeiten. Wir werden Terokks Rache sicher eiskalt zu schmecken bekommen.\n\nStellt schnell eine Verteidigung auf die Beine! Sprecht mit Verteidiger Grashna und lasst ihn wissen, dass Ihr bereit seid, die Waffen gegen unsere Angreifer zu erheben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10891] = {title = "Imperiale Plattenrüstung", objective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", progress = nil, completion = "Natürlich bringe ich Euch bei, wie man eine imperiale Plattenrüstung herstellt! Es wird Euch allerdings ein wenig Gold kosten... in Form von Thoriumbarren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10892] = {title = "Imperiale Plattenrüstung", objective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", progress = nil, completion = "Natürlich bringe ich Euch bei, wie man eine imperiale Plattenrüstung herstellt! Es wird Euch allerdings ein wenig Gold kosten... in Form von Thoriumbarren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10893] = {title = "Langschweif ist der springende Punkt", objective = "Tötet Draaca Langschweif, die Anführerin der Wyrmkultisten im Tunnel des Wyrmschädels.", description = "Da die Wyrmkultisten der Pechschwingen sich im Tunnel sammeln, sehen wir uns gezwungen, der Lage Herr zu werden. Ehrlich gesagt sind sie deutlich in der Überzahl.\n\nAuch wenn wir bisher diejenigen, die uns zu nahe gekommen sind, zurückhalten konnten, wären wir einem ernsthaften Angriff von ihnen nicht gewachsen.\n\nDie Lage erfordert, dass jemand sich bis an das andere Ende des Tunnels durchkämpft und ihre Anführerin, Draaca Langschweif, unschädlich macht. Habt Ihr Lust auf ein wenig Spaß?", progress = "Ist sie tot?\n\n<Name>, wenn wir auch nur die leiseste Chance gegen sie haben wollen, müsst Ihr Verwirrung unter ihren Rängen säen, indem Ihr Draaca Langschweif tötet!", completion = "Nun, da Draaca unschädlich gemacht wurde, sollten wir in der Lage sein, unseren Vorteil aus der Situation zu ziehen. Sie werden sich jetzt untereinander darum streiten, wer die Leitung übernehmen soll, und das wird uns viel Druck nehmen.\n\nEs sei denn der Aufseher aus dieser Einladung, die Ihr mir gegeben habt, nimmt ihren Platz ein.\n\nWir sollten sicherstellen, dass das niemals passieren wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10894] = {title = "Behüter des Wyrmschädels", objective = "Bringt die Einladung zum Treffen zu Behüter Mondschatten beim Eingang des Tunnels des Wyrmschädels im Schergrat.", description = "Hm, ich weiß nicht so recht, was wir tun sollen. Ich bin nicht gerade ein Militärstratege.\n\nBehüter Mondschatten weiß sicher, was zu tun ist. Er kümmert sich um unsere Verteidigung beim Tunnel des Wyrmschädels im Westen, am Ende der Brücke des Wyrmschädels. Wir unterhalten dort eine Streitmacht, falls die Kultisten zu übermütig werden.\n\nBitte, bringt ihm so schnell wie möglich diese Nachricht.", progress = "Wie kann ich Euch helfen? Bringt Ihr Nachrichten aus dem ewigen Hain?", completion = "Es ist genau so, wie ich es befürchtet habe, und das ist nicht gut!\n\nIch habe schon eine Idee, wie ich Euch helfen kann, aber vielleicht könnt zunächst Ihr uns helfen?\n\nEine Hand wäscht die andere.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10895] = {title = "Zeth'Gor muss brennen!", objective = "Benutzt das Rauchsignal unter jedem Wachturm in Zeth'Gor und kehrt danach zu Schwadronskommandant Dabir'ee beim Expeditionsposten zurück.", description = "Es ist an der Zeit, Zeth'Gor aus der Luft anzugreifen! Unsere Greifenreiter sind bereit für einen kleinen Ausflug, <Name>. Aber wir brauchen jemanden, der vom Boden aus ihre Angriffe lenkt. Seid Ihr bereit für einen kleinen Geheimauftrag?\n\nBringt diese Rauchsignale nach Zeth'Gor, dem Stützpunkt des Blutenden Auges im Westen. Dort befinden sich vier Wachtürme: einer in der Nähe der nördlichen Mauer, einer in der Nähe der südlichen Mauer, einer in der Nähe der Schmiede und einen in den Hügeln. Platziert ein Rauchsignal unter jedem Turm und wir werden sie bombardieren!", progress = "Die Zeit drängt, <Name>. Wir müssen diese Wachtürme anzünden!", completion = "Ich konnte von hier aus den Rauch und die Flammen sehen! Gute Arbeit, &lt;Name&gt;! Ihr verdient mehr als nur ein paar Lobesworte von unseren Greifenreitern. Was Ihr da getan habt, erfordert eine gehörige Portion Mut.", rewards = "Heilige FederwesteWams des ungezähmten GeistsGoldgewebte TunikaGüldene PurpurbrustplatteBerserkerweste der KnochenmalmerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10896] = {title = "Die verseuchten Beschützer", objective = "Lakotae möchte, dass Ihr 25 Baummilben tötet und danach zu ihm bei der Flüchtlingskarawane zurückkehrt. Ihr findet die Milben in den Körpern der faulenden Waldwüter und befallenen Wurzelwandler.", description = "Die Macht, die von Auchindoun freigesetzt wurde, hat verheerende Auswirkungen auf die Bäume dieses Landes. Die verderbte Magie, die dort entfesselt wurde, hat das Land in diese Wüste verwandelt, die Ihr nun hier überall sehen könnt. Die Bäume, die überlebt haben, sind nun von schädlichen Baummilben befallen, die unter ihre Rinde kriechen und ihr Holz anfressen.\n\nFaulende Waldwüter und befallene Wurzelwandler sind ein idealer Nährboden für die Milben. Man kann sie am östlichen Waldrand finden. Vernichtet diese Kreaturen und tötet dann die Milben, die aus ihrer Hülle fliehen.", progress = nil, completion = "Ihr habt viel zur Rettung der Wälder von Terokkar beigetragen, &lt;Name&gt;. Jetzt, da die schlimmsten Milbenkolonien vernichtet sind, können wir vielleicht dieses öde Land zurückerobern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10897] = {title = "Meister der Tränke", objective = "Lauranna Thar'well möchte, dass Ihr die Botanika der Festung der Stürme betretet und den Naturführer der Botanika von Hochbotaniker Freywinn besorgt. Zusätzlich möchte sie, dass Ihr ihr 5 erstklassige Heiltränke, 5 erstklassige Manatränke und 5 erhebliche Tränke des traumlosen Schlafs bringt.\n\nACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen.", description = "Wie Ihr sicher wisst, verfügen Pflanzen über Eigenschaften, mit deren Hilfe Alchemisten über Tränke andere stärken und verjüngen können.\n\nMein Wissen über die Pflanzen in der Scherbenwelt ermöglicht mir, Alchemisten beizubringen, wie sie das Beste aus ihnen herausholen können. Wenn Ihr Euer Wissen über Tränke vertiefen möchtet, müsst Ihr nur eine kleine Aufgabe für mich erledigen.\n\nHochbotaniker Freywinn in der Festung der Stürme soll angeblich einen ausführlichen Botanikführer geschrieben haben. Bringt ihn zusammen mit ein paar Proben Eurer Arbeit zu mir und ich werde Euch das Wissen lehren, das Ihr wünscht.", progress = "Seid Ihr Euch sicher, <Name>? Wenn Ihr Euch in der Kunst der Tränke spezialisiert, werdet Ihr keine weiteren Spezialisierungen erlernen können.", completion = "Ausgezeichnet! Wie es aussieht, seid Ihr begierig darauf zu lernen, also lasst uns beginnen. Ich werde Euch beibringen, wie Ihr das Beste aus den Pflanzen für Eure alchimistischen Tränke herausholt.\n\nIhr werdet sehen, dass ganz schön viel in den Kräutern steckt, wenn man weiß, was man zu tun hat. Manchmal kann man sogar zwei Tränke mit den Materialien für einen herstellen.", rewards = "Ihr erlernt:\n\nMeister der Tränke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Tränke\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10898] = {title = "Wolkenschwinge", objective = "Begleitet Wolkenschwinge und meldet Euch dann bei Rilak dem Erlösten in Shattrath.", description = "Wolkenschwinge flattert um Euch herum.\n\nEurer Einschätzung nach möchte er, dass Ihr ihm folgt.", progress = nil, completion = "Also stand der arme Wolkenschwinge unter dem schrecklichen Fluch von Luanga dem Kerkermeister!\n\nWolkenschwinge hatte sich auf den Weg ins Shalasversteck gemacht, um zu versuchen, die anderen auf den Weg des Lichts zu bringen. Sie haben seine Versuche nicht gerade positiv aufgenommen, vor allem nicht, da sie direkt am Fuße von Skettis liegen.\n\nLuanga war einer von Terokks gefürchtetsten Dienern. Es war gut von Euch Wolkenschwinge zu befreien! Ich danke Euch.", rewards = "Gamaschen des stillen FeuersPlatte des ErlösersHimmelshexerhutIhr bekommt:\n\nMinischwing"}
MultiLanguageQuestData['de'][10899] = {title = "Meister der Transmutation", objective = "Zarevhi in der Sturmsäule im Nethersturm möchte, dass Ihr ihm 4 Einheiten Urmacht bringt.\n\nACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen.", description = "Jeder Alchemist kann Euch erklären, dass Materie formbar ist und jede Substanz in eine andere verwandelt werden kann. Jedoch wird dabei nichts wirklich erschaffen oder zerstört.\n\nEin wahrer Meister der Transmutation kann lernen, diese Grenzen zu überwinden. Und ich kann Euch zeigen, wie man dies erreichen kann!\n\nAls angehender Transmutierer seid Ihr sicher mit der Urmacht vertraut, der Verbindung der Materialien aller Urkräfte. Beweist mir Euer Können in der Kunst der Transmutation. Dann werde ich mein Wissen mit Euch teilen.", progress = "Seid Ihr sicher, dass Ihr ein Meistertransmutierer werden wollt? Wenn Ihr Euch auf diesem Gebiet spezialisiert, werdet Ihr Euch nicht auf Tränke oder Elixiere spezialisieren können.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Diese Transmutationen sind in jeder Hinsicht perfekt!\n\nIch werde Euch nun beibringen, wie man mit Hilfe der alchimistischen Transmutation Materie aus dem Nichts erschaffen kann! Nutzt Euer Wissen weise, Meistertransmutierer.\n\nWenn Ihr mich nun entschuldigen möchtet, ich muss einen Kunden aufsuchen, der an Urmacht interessiert ist.", rewards = "Ihr erlernt:\n\nMeister der Transmutation\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Transmutation\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10900] = {title = "Das Mal von Vashj", objective = "Brennt es nieder, <Volk>! Brennt alles nieder! Sie haben nichts verdient. Habt Ihr mich verstanden? NICHTS! Sie müssen für ihre Taten bezahlen. Auch für ihre zukünftigen.\n\nIch würde Vashj selbst töten, wenn ich von diesen verdammten Fesseln frei wäre.\n\nOder wollt Ihr vielleicht Neptulons Arbeit erledigen? Ihr Tod ist uns beiden dienlich, Weichhaut. Werdet Ihr mir dabei helfen, den heiligen Knüppel herzustellen?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10901] = {title = "Der Knüppel von Kar'desh", objective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!", progress = "Mit dem Knüppel werde ich meine Fesseln lösen können und zum Schlangenschrein zurückkehren, um meine Rache an Vashj und ihren Dienern zu üben!", completion = "Endlich!\n\nMit gelösten Fesseln und dem Knüppel in meinem Besitz werde ich diese Meereshexe wieder zurück in die eisigen Tiefen senden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10902] = {title = "Meister der Elixiere", objective = "Begebt Euch in den Schwarzen Morast in den Höhlen der Zeit und besorgt 10 Essenzen der Unendlichkeit von den Fürsten der Zeitenrisse und den Bewahrerinnen der Zeitenrisse. Bringt die Essenzen zusammen mit 5 Elixieren der erheblichen Verteidigung, 5 Elixieren des Meisters und 5 Elixieren der erheblichen Beweglichkeit zu Lorokeem im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie wählen!", description = "Ich habe mein Leben der Perfektion meiner Elixiere gewidmet. Trotz meines Erfolgs habe ich es nie geschafft, ein Elixier des ewigen Lebens herzustellen.\n\nIch glaube zu wissen, welche Reagenz mir fehlt. Ich habe von einem Ort in Azeroth gehört, der die Höhlen der Zeit genannt wird. Die Eindringlinge dort, Fürsten der Zeitenrisse genannt und die Bewahrerinnen der Zeitrisse können auf den Zeitlinien hin- und herspringen.\n\nDurch diesen Wechsel in der Zeit entstehen Risse, die sich in alle Ewigkeit ziehen und zu unendlicher Essenz kristallisieren. Bringt mir diese Essenzen zusammen mit Proben Eures handwerklichen Könnens und ich werde Euch alles beibringen, was ich weiß.", progress = "Die Essenzen! Habt Ihr sie?", completion = "Ihr versteht Euch auf Elixiere, wenn man diesen hier glauben mag. Ihr werdet ein guter Schüler sein.\n\nDiese Essenzen werden ausreichen, um mein Rezept zu entwickeln. Für diese Entdeckung werde ich Berühmtheit unter allen Alchimisten erlangen!\n\nWenn Ihr nun bereit seid zu lernen, bin ich bereit zu lehren.", rewards = "Ihr erlernt:\n\nMeister der Elixiere\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Elixiere\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10903] = {title = "Rückkehr zur Ehrenfeste", objective = "Sprecht mit Gehilfe Klatu im Gasthaus der Ehrenfeste.", description = "<Name>, während Ihr mit Eurem Auftrag in Zeth'Gor beschäftigt wart, habe ich Nachricht von meinem befehlshabenden Offizier, Oberst Jules erhalten. Er wurde während des Kampfes beim Außenposten von Gor'gaz von einer dämonischen Verderbnis befallen. Sein Zustand wird immer schlechter.\n\nIhr habt so viele große Erfolge gegen die Höllenorcs erzielt. Eure Kraft in der Schlacht steht außer Frage... ist Euer Geist auch so stark?\n\nBitte, kehrt zur Ehrenfeste zurück und sprecht mit Klatu. Er befindet sich in einem Raum über dem Gasthaus der Ehrenfeste.", progress = nil, completion = "Ja, es ist wahr. Oberst Jules' Zustand hat sich in den letzten Tagen stark verschlechtert. Anachoret Barada betet schon die ganze Zeit für ihn... Wir hoffen, dass er geheilt werden kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10904] = {title = "Teufelsmunition", objective = "Beschafft Euch 5 Teufelskanonenkugeln.", description = "Wir müssen der Brennenden Legion den Zugang zu Schwelle des Todes versperren, aber zunächst müsst Ihr die beiden Warptore zerstören!\n\nDas Problem ist, dass wir diesen Dingern nicht einmal einen Kratzer zufügen können, daher müsst Ihr ihre eigenen Waffen gegen sie verwenden.\n\nDie Mächte des Todes, die Augen des Todes, die Oberschmiede der Todesschmiede und die Techniker der Todesschmiede tragen die Munition für die Teufelskanonen bei sich.\n\nNormalerweise kann diese Munition ihnen nichts anhaben, aber wenn Ihr die Kanonenkugeln zu mir bringt, werde ich sie mit dem unbändigen Zorn der Natur erfüllen!", progress = "Habt Ihr die Kanonenkugeln schon?", completion = "Diese Dinger stinken ja schlimmer, als ich dachte!\n\nSchnell, gebt sie mir, damit ich die mit der Macht der Natur erfüllen kann. Dann werden sie zu tödlichen Waffen gegen die teuflischen Meister und ihre unnatürlichen Schöpfungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10905] = {title = "Meister der Tränke", objective = "Sprecht mit Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch auf die Herstellung von Tränken spezialisieren möchtet, empfehle ich Euch, Lauranna Thar'well von der Expedition des Cenarius aufzusuchen.\n\nIhr Wissen über die Pflanzen wird Euch dabei helfen, das Beste aus Euren Rohmaterialien herauszuholen. Sucht sie in den Zangarmarschen auf und sagt ihr, dass ich Euch geschickt habe.", progress = nil, completion = "Ihr wollt, dass ich Euch bei Euren Studien der Tränke helfe? Nun gut, &lt;Name&gt;. Wollen wir mal schauen, was wir da machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10906] = {title = "Meister der Elixiere", objective = "Sprecht mit Lorokeem im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch auf die Herstellung von Elixieren spezialisieren möchtet, empfehle ich Euch, den Arakkoa namens Lorokeem um Hilfe zu bitten.\n\nSein Wissen über Elixiere sucht seinesgleichen und doch verschwendet er sein Können darauf, ein Elixier des ewigen Lebens zu brauen. Sucht nach ihm und schaut, was er Euch beibringen kann.", progress = nil, completion = "Ihr wollt von mir lernen? Hmmm, ja. Vielleicht seid Ihr ja ein geeigneter Schüler.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10907] = {title = "Meister der Transmutation", objective = "Sprecht mit Zarevhi in der Sturmsäule im Nethersturm.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch in der Kunst der Transmutation spezialisieren möchtet, empfehle ich Euch, den Astralen namens Zarevhi um Hilfe zu bitten. Er lebt in der Sturmsäule im Nethersturm.\n\nSeine Beherrschung der Transmutation ist... nun, exotisch! Seht nach, was Ihr von ihm lernen könnt. Aber seid vorsichtig: Astrale sind hartnäckige Verhandlungspartner.", progress = nil, completion = "Ihr wollt, dass ich Euch bei Euren Studien der Transmutation helfe? Nun gut, &lt;Name&gt;. Wollen wir mal schauen, was wir da machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10908] = {title = "Sprecht mit Rilak dem Erlösten", objective = "Kirrik der Erwachte möchte, dass Ihr mit Rilak dem Erlösten im Unteren Viertel von Shattrath sprecht.", description = "Ihr seht überrascht aus, dass ich mit Euch rede. Ich mache Euch keinen Vorwurf. Mein Volk, die Arakkoa, verdienen Euren Argwohn.\n\nSprecht mit Rilak dem Erlösten in Shattrath, wenn Ihr mehr erfahren wollt. Er hält sich im nördlichen Teil des Unteren Viertels bei den anderen Ausgestoßenen der Skettis auf.\n\nUnd <Name>, wir werden voneinander hören.", progress = nil, completion = "So treffen wir uns also, &lt;Name&gt;. Bitte vergebt mir meine fehlenden Manieren, aber die Zeit drängt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10909] = {title = "Höllengeister", objective = "Klatu in der Ehrenfeste möchte, dass Ihr das Relikt des Anachoreten beim Außenposten von Gor'gaz benutzt, die Orcs der Zerschmetterten Hand in der Nähe des Relikts tötet und dann 10 freigesetzte Höllengeister vernichtet, um Oberst Jules zu rächen.", description = "Oberst Jules wurde in einer Schlacht in der Nähe des Außenpostens von Gor'gaz, einer der Lieblingsorte der Höllenorcs der Zerschmetterten Hand, verflucht. Mein Meister Barada versucht verzweifelt, den armen Menschen zu heilen, aber er braucht Hilfe. Der verwirrte Geist des Oberst sucht nach Frieden, und ich fürchte, dass ein Teil des Weges dazu der Weg der Rache ist.\n\nBringt dieses Relikt des Anachoreten zum Außenposten von Gor'gaz. Stellt es in der Nähe der Orcs der Zerschmetterten Hand auf und besiegt sie. Das wird ihre Höllengeister freisetzen. Ihr müsst die Höllengeister töten, damit Jules Geist sich erholen kann.", progress = "Die Höllengeister der Orcs der Zerschmetterten Hand sind für Jules' arme Seele eine Schmach. Sagt mir, <Name>... habt Ihr ihn gerächt?", completion = "Die Orcs der Zerschmetterten Hand sind verderbt und nicht mehr zu retten. Und dennoch erfüllt es mein Herz mit Traurigkeit, dass die Rettung von Oberst Jules ein solches Blutvergießen erfordert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10910] = {title = "Die Schwelle des Todes", objective = "Benutzt das Druidensignal bei der Schwelle des Todes, um einen Druiden des Ewigen Hains zu rufen und mit ihm zu sprechen.\n\nBereitgestellter Gegenstand: \n", description = "Wir haben von einer sogar noch größeren Bedrohung durch die Legion erfahren. Im Süden befindet sich ein Portal, dass als Schwelle des Todes bekannt ist. Es ist die Tür zu einer entsetzlichen Welt, in der die Legion ihre verschiedenen Hunderassen züchtet.\n\nUm dorthin zu gelangen, müsst Ihr den Ewigen Hain Richtung Osten verlassen und den Pfad hinauf gehen. Folgt dem Weg nach Süden durch die Messerschlucht, an Razaans Landeplatz vorbei durch den Messergrat und über die Schuppenflügelbank. Nehmt dann den Pfad hinab nach Vekhaar und betretet die Schwelle des Todes durch den Tunnel südlich des Dorfs der Mok'Nathal.\n\nBenutzt dieses Druidensignal, sobald Ihr angekommen seid.", progress = nil, completion = "Ich bin sehr erleichtert, dass Wildfürst Antelarion Euch zu uns geschickt hat. Das Problem ist noch viel schlimmer, als wir befürchtet haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10911] = {title = "Feuer frei!", objective = "Verwendet die naturalisierte Munition, um die Kontrolle über die Teufelskanonen der Schwelle des Todes zu erlangen. Benutzt die Kanonen, um das südliche Warpportal und das nördliche Warpportal zu zerstören.", description = "Jetzt, da unsere Munition der Brennenden Legion Schaden zufügen kann, ist es an der Zeit, dass Ihr sie benutzt.\n\nEs gibt zwei Warptore, die für die Teleportation und die Verbesserung der Schrecken der Leere benutzt werden. Eines befindet sich im Süden, das andere im Norden. Beide liegen in der Reichweite einer Teufelskanone.\n\nKämpft Euch bis zu den Teufelskanonen durch und benutzt die naturalisierte Munition, um die Kontrolle über die Kanonen zu erlangen und die Warptore zu zerstören.\n\nHütet Euch jedoch von den Verteidigern, die ausschwärmen werden, um die Kanone anzugreifen!", progress = "Habt Ihr beide Warpportale schon zerstört?", completion = "Euer Heldenmut ist beeindruckend!\n\nSehr gut. Nun, da die Warpportale außer Gefecht sind, bleibt nur noch eines zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10912] = {title = "Der Hundehetzer", objective = "Tötet den Hundehetzer.", description = "Baelmon der Hundehetzer muss sterben! Er ist es, der das Ritual vollzieht, mit dem das Portal aufrechterhalten wird!\n\nDas Portal der Schwelle des Todes befindet sich am nördlichen Ende der Schlucht. Wenn Ihr es gefunden habt, findet Ihr auch Baelmon.\n\nIhr werdet dabei Hilfe brauchen, also nehmt diesen Stab mit. Benutzt ihn, wenn Ihr gegen den Hundehetzer kämpft, und ein paar meiner Freunde werden Euch zu Hilfe eilen.\n\nKehrt zu Wildfürst Antelarion zurück, wenn Ihr Baelmon besiegt habt.\n\nUnd <Name>, vielen Dank für alles, was Ihr unseretwegen auf Euch genommen habt.", progress = "Ist es vorbei? Ist die Gefahr an der Schwelle des Todes abgewendet?", completion = "Ihr seid wirklich ein ganz erstaunlicher &lt;Volk&gt;! Wenn ich schon zuvor dachte, dass wir in Eurer Schuld stehen, so gibt es nun einfach keinen Weg mehr, Euch je für Eure Taten zu danken.\n\nAber wir wollen es dennoch versuchen. Vielen Dank, Held des ewigen Hains!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNatashas ArkanfadenNatashas KampfketteNatashas HalsreifNatashas GluthalsketteNatashas WächterkordelNatashas Krallenhalsschmuck\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10913] = {title = "Ein unangemessenes Begräbnis", objective = "Kommandant Ra'vaj beim Basislager der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 8 getötete Kämpfer der Auchenai und 8 getötete Verteidiger der Sha'tar verbrennt.", description = "Gibt es nichts, was man gegen diese Flut der Verderbnis tun kann? Meine Soldaten kämpfen schon seit Tagen gegen die Auchenai und ein Ende ist nicht in Sicht. Jeder Gefallene, ob Sha'tar oder Auchenai, wird sofort vom Schlachtfeld gezerrt. Ihre Seelen werden geraubt und an unbekannte Orte gebracht.\n\nDas werde ich nicht zulassen! Ein angemessenes Begräbnis ist leider nicht möglich, aber diese Bestien werden ihre Seelen nicht bekommen! Nehmt diese Fackel und begebt Euch zum Schlachtfeld östlich von hier. Verbrennt jeden Leichnam, den Ihr finden könnt! Wir werden ihre Rituale nicht verstärken!", progress = "Ich weiß, es ist eine grausame Aufgabe...", completion = "&lt;Kommandant Ra'vaj schüttelt traurig den Kopf.&gt;\n\nEs ist nicht genug... Es ist einfach nicht genug.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10914] = {title = "Wir brauchen einen Helden!", objective = "Kommandant Ra'vaj beim Basislager der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 12 Initianden der Auchenai und 5 Verdammnisverkünder der Auchenai tötet.", description = "Es reicht. Wir brauchen einen Helden. Unsere Streitkräfte können der immer wachsenden Zahl der Auchenai nicht mehr Herr werden.\n\n<Kommandant Ra'vaj schaut Euch an.>\n\nWollt Ihr <unser Held/unsere Heldin> sein? Kehrt zum Schlachtfeld zurück und greift ihre Soldaten an. Beschäftigt sie, damit meine Späher hinter die Linien gelangen und herausfinden können, was sie dort vorbereiten.", progress = "Keine Gefangenen!", completion = "Ihr habt es geschafft, &lt;Name&gt;! Dank Euch konnten wir eine neue Entdeckung machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10915] = {title = "Der gefallene Exarch", objective = "Kommandant Ra'vaj beim Basislager der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr den Inhalt des Sargs der Auchenai vernichtet.", description = "Sie verfüttern die Seelen, die sie gestohlen haben, an einen Sarg, den sie aus der Auchenaikrypta entwendet haben. Meine Späher glauben, dass sich der erste Exarch der Krypta in diesem Sarg befindet. Die Auchenai versuchen, ihn wieder zum Leben zu erwecken!\n\nIhr müsst Euch zur westlichen Seite von Auchindoun durchschlagen und den Inhalt des Sargs stören, bevor sie ihm genügend Seelen füttern konnten. Falls Ihr Euch verirren solltet, folgt einfach den wandelnden Seelen.\n\nWas auch immer sich in dem Sarg befinden mag - vernichtet es!", progress = "Ihr müsst dieses uralte Böse vernichten, bevor es seine Macht wiedererlangt.", completion = "Der Sieg ist unser! Diese Niederlage wird die Auchenai um mehrere Wochen zurückwerfen.", rewards = "Verteidigerbeinplatten der Sha'tariSchützenhandschuhe der Sha'tariElekkbalgschiftungTunika des TodessprechersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10916] = {title = "Nach Gebetsperlen graben", objective = "Sucht die Gebetsperlen der Draenei und bringt sie zu Gehilfe Klatu in der Ehrenfeste.", description = "Anachoret Barada hat vor, die Verderbnis aus Oberst Jules zu exorzieren und braucht dafür einen Gehilfen. So ein Gehilfe muss allerdings gut vorbereitet sein...\n\nIch schäme mich sehr, es zuzugeben, aber ich habe meine Gebetsperlen im Hof der Ehrenfeste verloren. Ich glaube, dass Fei-Fei der Hund sie gestohlen und verbuddelt hat, aber ich weiß nicht wo. Sprecht mit seiner Meisterin, Stabsfeldwebel Tracy Stolzbrunn. Vielleicht weiß sie, wo Fei-Fei seine gestohlenen Schätze aufbewahrt.", progress = "Habt ihr die Gebetsperlen schon gefunden, <Name>? Ihre Macht ist für viele heilige Rituale unerlässlich... darunter auch für einen Exorzismus...", completion = "Ihr habt die Gebetsperlen gefunden! Gut gemacht, &lt;Name&gt;. Ihr seid in der Tat ein Wunder. Im einen Moment erschlagt Ihr die Schrecken der Höllenfeuerhalbinsel, im anderen findet Ihr verlorene Schätze. Euer Volk ist wirklich sehr vielseitig!\n\nEs ist gut, dass Ihr diese Perlen gefunden habt... Sie sind für das folgende Exorzismusritual von äußerster Wichtigkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10917] = {title = "Die Pflicht eines Ausgestoßenen", objective = "Bringt 30 Arakkoafedern zu Vekax im Unteren Viertel von Shattrath.", description = "Als Ausgestoßener gelte ich bei den Arakkoa, die der Stadt Skettis treu ergeben sind, als vogelfrei. Ich kann diese Mauern aus Angst um mein Leben nicht verlassen. Aber das heißt noch lange nicht, dass ich mich nicht rächen kann.\n\nIch habe einen kleinen Schatz, den ich hergeben würde, wenn Ihr mir dabei helft, meine Möchtegernmörder zu erledigen. Bringt mir die Federn der Bewohner der verschiedenen Arakkoaverstecke von Terokkar als Beweis für ihr Ableben.", progress = "Seid Ihr mit den Federn zurück, <Name>?", completion = "&lt;Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.&gt;\n\nJa, das wird Skettis zeigen, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Hier ist die Belohnung, die ich Euch versprochen habe. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt.", rewards = "Ihr bekommt:\n\nTasche des Verstoßenen"}
MultiLanguageQuestData['de'][10918] = {title = "Mehr Federn", objective = "Die Schoßhunde von Skettis behalten uns Ausgestoßene immer noch genau im Auge. Sobald einer von uns es wagt, einen Fuß aus Shattrath zu setzen, sind wir so gut wie tot.\n\nBringt mir mehr Federn als Beweis für Euren Sieg über sie.", description = nil, progress = "Die Schoßhunde von Skettis behalten uns Ausgestoßene immer noch genau im Auge. Sobald einer von uns es wagt, einen Fuß aus Shattrath zu setzen, sind wir so gut wie tot.\n\nBringt mir mehr Federn als Beweis für Euren Sieg über sie.", completion = "&lt;Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.&gt;\n\nJa, das wird Skettis zeigen, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Hier ist die Belohnung, die ich Euch versprochen habe. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt.\n\n&lt;Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.&gt;", rewards = "Ihr bekommt:\n\nTasche des Verstoßenen"}
MultiLanguageQuestData['de'][10919] = {title = "Fei-Feis Belohnung", objective = "Fei-Fei schaut Euch erwartungsvoll an...", description = nil, progress = "Fei-Fei schaut Euch erwartungsvoll an...", completion = "&lt;Fei-Fei bellt glücklich und schnappt sich das Hundeleckerli. Er schaut nach links und rechts um zu entscheiden, wo er seinen neuen Schatz vergraben soll...&gt;", rewards = nil}
MultiLanguageQuestData['de'][10920] = {title = "Für die Gefallenen", objective = "Verteidiger Haylen möchte, dass Ihr 20 Schreckenswitwen tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt.", description = "Als die Schreckenswitwen unseren Außenposten angegriffen haben, hörten wir die Stimme der Naaru, die uns in die Schlacht schickte. Wir verfolgten die Kreaturen bis in die tiefe Nacht hinein. Ein paar unserer Leute wurden in der Dunkelheit tot aufgefunden, andere hörten wir im verzweifelten Kampf gegen die Spinnen.\n\nDer Morgen zeigte uns, dass wir tapfer gekämpft und dennoch verloren hatten. Das Gift der Schreckensweber wird meine Kameraden bald dahinraffen, und auch ich werde nicht mehr lange durchhalten können. Doch bevor ich sterbe möchte ich die Gewissheit haben, dass die Schreckenswitwen geschlagen wurden.", progress = "Ich kann das Gift in meinen Adern spüren. Die Naaru rufen mich, ich sehe das Licht. Sind die Schreckenswitwen schon besiegt?", completion = "Ich habe die Geräusche Eures Kampfes bis hierher hören können, &lt;Klasse&gt;. Der Klang Eures Sieges hat mein Herz mit Hoffnung erfüllt. Wenn Ihr gegen eine solch gewaltige Überzahl bestehen könnt, kann auch ich vielleicht noch die Kraft finden, um meine Kameraden von diesem schrecklichen Ort fort zu führen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10921] = {title = "Terokkarantula", objective = "Verteidiger Haylen möchte, dass Ihr Terokkarantula tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt.", description = "Ihr habt sehr viele Schreckenswitwen erschlagen, aber sie werden sich weiter vermehren und uns bald wieder angreifen. Tief im Netherweberkamm befindet sich das Nest von Terokkarantula, der Brutmutter dieser grausamen Kreaturen. Wenn wir in Sicherheit leben wollen, muss sie sterben.", progress = "Ist Terokkarantula schon tot?", completion = "Die Schreckensspinnen wurden geschlagen. Ihr habt so viele von ihnen getötet und nun auch noch ihre verderbte Mutter erlegt. Meine Vergiftungen sind zu schwer, als dass ich mich zurück in die Freiheit kämpfen könnte.\n\nBitte, nehmt etwas von meiner Ausrüstung. Ich werde mein Bündel erleichtern und Euch die nötigen Werkzeuge geben, um heil zum Außenposten der Sha'tar zu gelangen.", rewards = "Edle PlattenschulterstückeKlinge der VergeltungAuf Euch wartet eine dieser Belohnungen:\n\nGesegneter SiegelringBuch der vielen Segnungen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10922] = {title = "In den Knochen wühlen", objective = "Begleitet Letoll und seine Truppe und beschützt sie, während sie ihre Ausgrabung durchführen. Kehrt danach zu Zwergowitz beim Basislager der Sha'tari zurück.", description = "Heda! Ihr seht aus, als könntet Ihr gut auf Euch selbst aufpassen, <Volk>. Meine Truppe und ich hier sind auf der Suche nach einem Leibwächter, der auf uns aufpasst, während wir zu einer Ausgrabungsstätte im Norden gehen. Die Bezahlung ist ziemlich gut und Ihr müsst nur schauen, dass keine fiese Kreatur mich oder meine Angestellten tötet.\n\nWenn Ihr es heil zurückschafft ohne irgendwelche Todesopfer, wird Zwergowitz da drüben Euch bezahlen.", progress = nil, completion = "Ein Knochenwurm! Fantastisch! Das könnte tatsächlich das erste Mal seit Beginn der Geschichtsschreibung sein, dass Letoll tatsächlich eine Entdeckung gemacht hat!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10923] = {title = "Das Böse rückt näher", objective = "Oakun möchte, dass Ihr das Schreckensrelikt zum Gequälten Hügel bringt. Tötet dort die Todessprecher und Verdammnisverkünder der Auchenai, um 20 Verdammnisschädel zu sammeln. Sucht danach den Beschwörungskreis des Gequälten Hügels auf und benutzt das Schreckensrelikt, um Teribus den Verfluchten zu beschwören und zu vernichten. Kehrt zu Oakun zurück, wenn Ihr Eure Aufgabe erfüllt habt.", description = "Jetzt müsst Ihr das Schreckensrelikt in einem bösartigen nekromantischen Ritual benutzen, um Teribus den Verfluchten herauszufordern. Im Nordosten, hinter Auchindoun, liegt der Gequälte Hügel. An diesem Ort versammeln sich die Nekromanten.\n\nDie Todessprecher und Verdammnisverkünder der Auchenai tragen Verdammnisschädel bei sich, die mit mächtigen nekromantischen Verzauberungen belegt sind. Wenn Ihr genügend Schädel sammelt, könnt Ihr ihre Macht mit der des Schreckensrelikts vereinen und Teribus so befehlen, sich Euch zu stellen.", progress = "Habt Ihr Teribus den Verfluchten aus den Himmeln Terokkars vertrieben?", completion = "Terokkar wurde von einem schlimmen Übel befreit. Die Sha'tar stehen in Eurer Schuld.", rewards = "DrachenknochengroßschwertDrachenknochenschulternAuf Euch wartet eine dieser Belohnungen:\n\nDrachenknochentalisman\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10924] = {title = "Verwichtelt und zugenäht!", objective = "Bringt 8 Phiolen Sphärenhetzerblut zu Sab'aoth in Kosmozang.", description = "Das Blut der Sphärenhetzer in dieser Gegend ist eine sehr mächtige Reagenz und mein größter Verkaufsschlager.\n\nNormalerweise ziehe ich mit meinen Wichtel Zeppit los, um es zu sammeln. Es ist einfach viel zu ätzend, als dass Ihr es sammeln könntet, aber Zeppit kann es nichts anhaben.\n\nHier im Laden ist immer mehr los. Hättet Ihr daher etwas dagegen, wenn ich Euch Zeppit mitschicke, um etwas Blut zu sammeln? Zeppits Aufmerksamkeit neigt jedoch dazu abzuschweifen. Ihr müsst daher nahe an dem Hetzer stehen, wenn er gestorben ist, um sicherzugehen, dass Zeppit seine Arbeit erledigt.", progress = "War Zeppit freundlich genug, das Blut für Euch zusammeln?", completion = "Das sollte genügend Vorrat für meine Zwecke sein.\n\nIch hoffe, der Wichtel hat Euch nicht allzu viel Ärger gemacht. Er hat manchmal Haare auf den Zähnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10926] = {title = "Rückkehr zum Basislager der Sha'tari", objective = "Verteidiger Haylen möchte, dass Ihr zum Basislager der Sha'tari in die Knochenwüste zurückkehrt und mit Späher Navrin sprecht.", description = "Wir werden es nicht ohne Hilfe zurück schaffen. Das Gift der Schreckensweber ist zu stark. Ihr müsst für uns zum Basislager der Sha'tari gehen. Späher Navrin wird eine Rettungstruppe nach uns schicken.", progress = nil, completion = "Es ist gut zu wissen, dass einige unserer Krieger tapfer gegen die Schreckenswitwen gekämpft und überlebt haben. Wir werden sofort eine Rettungstruppe nach ihnen schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10927] = {title = "Die Krabbler erschlagen", objective = "Tötet 6 Höhlenkrabbler.", description = "Kommandant Himmelsschatten möchte, dass wir diesen Tunnel freiräumen, damit wir den Handel mit der Zuflucht beschleunigen können. Ich darf meinen Posten hier nicht verlassen, daher übertrage ich Euch diese Aufgabe. Räumt den Tunnel frei und meldet Euch dann sofort bei Kommandant Himmelsschatten!", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;. Dieser Tunnel ist unsere direkte Verbindung zum Sumpf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10928] = {title = "Die Krabbler erschlagen", objective = "Tötet 6 Höhlenkrabbler.", description = "Tor'chunk Zweiklaue möchte, dass wir diesen Tunnel freiräumen, damit wir den Handel mit dem Sumpfrattenposten beschleunigen können. Ich darf meinen Posten hier nicht verlassen, daher übertrage ich Euch diese Aufgabe. Räumt den Tunnel frei und meldet Euch dann sofort bei Tor'chunk Zweiklaue!", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;. Dieser Tunnel ist unsere direkte Verbindung zum Sumpf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10929] = {title = "Stampfen", objective = "Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm 8 Kadaver eines ausgewachsenen Knochenwühlers bringt.", description = "Würdet Ihr gerne noch mehr Aufgaben für die Forscherliga erledigen? Wir alle hier finden diese Knochenwürmer ziemlich faszinierend.\n\nIch habe hier eine Trommel, die Ihr draußen in der Knochenwüste benutzen könnt. Schlagt sie einfach und schaut, was dabei herauskommt. Wenn es ein Wurm ist, dann tötet ihn und bringt uns den Kadaver, damit wir ihn untersuchen können. Wir werden eine ganze Menge an Kadavern brauchen, wenn wir ein repräsentatives Testergebnis erzielen wollen.", progress = "Wir glauben, dass das, was wir bei den Ausgrabungen gefunden haben, tatsächlich nur ein Wurmkind war!", completion = "Sandgnome? Ja, klar... Die Wüste kann schon schlimme Dinge mit den Leuten anstellen.\n\nIch glaube, wir werden mit diesen Würmern hier einen wahren Durchbruch erzielen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10930] = {title = "Der große Knochenwurm", objective = "Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm riesige Knochenwurmorgane bringt.\n\nBringt auch den Stampfer zu ihm zurück.", description = "Ich hatte Recht! Die Kadaver, die Ihr mir gebracht habt, stammen von heranwachsenden Würmern! Wisst Ihr, was das bedeutet? Das bedeutet, dass es irgendwo da draußen noch einen großen geben muss! Wenn wir ihm das richtige Futter anbieten, können wir ihn sicher hervorlocken. Mal überlegen... etwas Großes! Ja!\n\nIch erinnere mich daran, hier auf der anderen Seite der Knochenwüste ein paar Grollhufe gesehen zu haben. Geht dorthin und tötet einen von ihnen. Benutzt die Trommel, sobald Ihr ihn erlegt habt. Hoffentlich kommt der große Wurm dann heraus, um zu fressen. Bringt mir seine Organe, wenn Ihr es schafft ihn zu töten!", progress = "Nehmt ein oder zwei Freunde mit!", completion = "Erstaunlich! Schaut Euch das an! Dieses Wasauchimmer hat eine Art Staub in seiner Wiemanesauchnennenmag. Aber ich will Euch nicht mit meinen wissenschaftlichen Fachbegriffen langweilen. Ich habe den kleineren Würmern ein paar Zähne gezogen und daraus diese unglaublich scharfen Messer gemacht. Wollt Ihr eins?", rewards = "Dib'Muads CrysmesserCrysmesser der ehrwürdigen MutterShanis CrysmesserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10931] = {title = "Rückkehr zur Exodar", objective = "Sprecht mit Caedmos in der Exodar.Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10932] = {title = "Rückkehr zur Exodar", objective = "Sprecht mit Caedmos in der Exodar.Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10933] = {title = "Rückkehr nach Silbermond", objective = "Sprecht mit Aldrae in Silbermond.Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10934] = {title = "Rückkehr nach Silbermond", objective = "Sprecht mit Aldrae in Silbermond.Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][10935] = {title = "Der Exorzismus des Oberst Jules", objective = "Sprecht mit Anachoret Barada. Benutzt die Gebetsperlen, um bei dem Ritual zu helfen und sprecht mit Oberst Jules, wenn er gerettet wurde. Kehrt danach zu Gehilfe Klatu zurück.", description = "<Name>, es ist an der Zeit, Oberst Jules zu retten. Sein Zustand hat sich verschlechtert, und Barada fürchtet, dass wir ihm nicht mehr helfen können, wenn wir ihn nicht bald von seiner Verderbnis heilen.\n\nNehmt die Gebetsperlen, die Ihr gefunden habt, und sprecht mit Anachoret Barada, um das Ritual zu beginnen. Lasst Euch dabei auf keinen Fall unterbrechen... und wenn alles gut geht, wird Oberst Jules gerettet sein. Sprecht mit Jules, wenn Ihr es geschafft habt, und kehrt danach zu mir zurück.", progress = "Geht zu Anachoret Barada, <Name>. Er muss mit seinem Ritual Erfolg haben, wenn der Oberst gerettet werden soll.", completion = "Ihr habt es geschafft, &lt;Name&gt;. Ihr habt Oberst Jules' Seele gerettet und die Dunkelheit in ihm vertrieben. Das ist eine großartige und selbstlose Tat! Die Tat eines Helden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10936] = {title = "Trollbann sucht Euch", objective = "Gehilfe Klatu hat Euch informiert, dass Truppenkommandant Danath Trollbann nach Euch sucht. Sprecht mit ihm in der Kaserne der Ehrenfeste auf der Höllenfeuerhalbinsel.", description = "Während Ihr beschäftigt wart, kam ein Bote und hat in der Halle auf Euch gewartet. Ich nehme an, er hatte keine Lust mehr zu warten oder er hat beim Anblick von Jules, der hier durch den Raum schwebt, das Weite gesucht.\n\nWie auch immer, Truppenkommandant Danath sucht Euch. Ich schlage vor, dass Ihr ihn so schnell wie möglich in der Kaserne aufsucht!", progress = nil, completion = "Das wird auch langsam Zeit! Ich habe davon erfahren, was Ihr und dieser Draeneipriester angestellt habt! Ihr habt meinen Boten völlig schockiert!\n\nJetzt, da Ihr damit fertig seid, habe ich einen kleinen Auftrag in der Höllenfeuerzitadelle für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10937] = {title = "Die Züchtigung des Drillmeisters", objective = "Truppenkommandant Danath Trollbann befiehlt Euch, Drillmeister Zurok so schnell wie möglich zur Strecke zu bringen. Kehrt zu dem Truppenkommandanten in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück, wenn der Drillmeister tot ist.", description = "Ich erhalte Berichte, denen zufolge die Höllenorcs der Zerschmetterten Hand vor der Höllenfeuerzitadelle dabei sind, einen groß angelegten Angriff zu organisieren. Offensichtlich sind sie alles andere als glücklich über Eure Siege über all die anderen Klans.\n\nBegebt Euch zur Basis der Zitadelle am Ende des Pfads des Ruhmes. Dort werdet Ihr sehen, dass die Höllenorcs mitten in den Vorbereitungen stecken und sie eiskalt überraschen.\n\nVernichtet den Verantwortlichen der Truppe. Tötet Drillmeister Zurok!", progress = nil, completion = "Ich wollte es nicht glauben, bis ich es nicht von Euch persönlich gehört habe. Unsere Späher berichten uns jetzt schon, dass die Zerschmetterte Hand ohne ihren geschätzten Drillmeister, der ihnen sagt, was zu tun ist, völlig überfordert ist.\n\nIhr habt einen langen Weg zurückgelegt, &lt;Name&gt;. Ich vertraue darauf, dass Ihr diese Rüstung zusammen mit meinem Dank annehmt. Tragt sie mit Stolz, denn Ihr habt sie verdient!", rewards = "SchattenzaubertunikaDunkelsturmtunikaSturmschlagwesteBrustplatte des KampfmeistersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][10938] = {title = "Segenskartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Segenskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Segenskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Segenskarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Segenskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Kreuzzug"}
MultiLanguageQuestData['de'][10939] = {title = "Sturmkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Sturmkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Sturmkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Sturmkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Sturmkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Zorn"}
MultiLanguageQuestData['de'][10940] = {title = "Furienkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Furienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Furienkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Furienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Furienkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Vergeltung"}
MultiLanguageQuestData['de'][10941] = {title = "Deliriumkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Deliriumkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Deliriumkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Deliriumkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Deliriumkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Wahnsinn"}
MultiLanguageQuestData['de'][10942] = {title = "Die Kinderwoche", objective = "Benutzt die Pfeife des Blutelfenwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand: \n", description = "Ein ganz besonderes kleines Mädchen wird sich sehr darüber freuen, Euch zum Freund zu haben, und sei es nur für eine kurze Zeit.\n\nNehmt diese Pfeife. Ihr könnt damit das Kind rufen, dessen Patenschaft Ihr übernommen habt. Diese Patenschaft wird nicht lange dauern, nur solange die Kinderwoche andauert.\n\nBitte, <Name>, ruft Eurer Waisenkind herbei. Ich weiß, dass sie schon darauf brennt Euch kennenzulernen und die Chance zu haben, einen Blick auf die Welt außerhalb der Stadt zu werfen!", progress = nil, completion = "Hm, Ihr seid also mein Pate? Ich bin Salandria! Ich bin schon, seit ich ein Baby war, hier. Meine Eltern sind im Krieg gestorben, daher lebe ich im Waisenhaus.\n\nEs ist nicht so übel, aber ich wollte schon immer gern die Welt sehen. Ich habe bisher nicht einmal einen Fuß aus der Stadt hinaus gesetzt. Ich habe schon eine Liste gemacht mit all den coolen Orten, die ich sehen will, und all den tollen Sachen, die ich machen möchte.\n\nIch bin bereit, wenn Ihr bereit seid!", rewards = nil}
MultiLanguageQuestData['de'][10943] = {title = "Die Kinderwoche", objective = "Benutzt die Pfeife des Draeneiwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand: \n", description = "Ein ganz besonderes kleines Mädchen wird sich sehr darüber freuen, Euch zum Freund zu haben, und sei es nur für eine kurze Zeit.\n\nNehmt diese Pfeife. Ihr könnt damit das Kind rufen, dessen Patenschaft Ihr übernommen habt. Diese Patenschaft wird nicht lange dauern, nur solange die Kinderwoche andauert.\n\nBitte, <Name>, ruft Eurer Waisenkind herbei. Ich weiß, dass sie schon darauf brennt Euch kennenzulernen und die Chance zu haben, einen Blick auf die Welt außerhalb der Stadt zu werfen!", progress = nil, completion = "Ihr müsst der Abenteurer sein, der in der Kinderwoche mein Pate ist! Ich bin Dornaa, freut mich sehr, Euch kennenzulernen.\n\n&lt;Für einen Moment sieht sie sehr traurig aus.&gt;\n\nMutter und Vater wurden im Krieg getötet. Ich bin schon mein ganzes Leben lang im Waisenhaus. Es ist wirklich schön dort, aber ich wollte schon immer gerne die Welt sehen.\n\nIch habe schon eine Liste mit all den Orten gemacht, die ich gerne sehen würde, wenn es Euch nichts ausmacht. Wir werden so viel Spaß zusammen haben!\n\nIch bin bereit, wenn Ihr bereit seid!", rewards = nil}
MultiLanguageQuestData['de'][10944] = {title = "Das gefährdete Geheimnis", objective = "Reist zum Kerker des Wächters im Schattenmondtal und sprecht mit Akama.", description = "Nochmals vielen Dank, <Name>. Ich kenne Euren Namen. Akama hat Euch seine Pläne anvertraut, daher werde ich Euch ebenso vertrauen.\n\nDie Naga haben herausgefunden, dass ich gegen Illidan arbeite und mich grausamer Folter unterzogen. Sie haben jedoch nichts aus mir herausbekommen. Akama selbst hat mir beigebracht, wie man Schmerz mithilfe von Meditation überwindet.\n\nIllidan hat den Naga aufgetragen, mich zu ihm persönlich zu bringen. Er hätte mich sofort durchschaut und die tiefsten Geheimnisse meiner Seele gesehen.\n\nWir müssen Akama warnen! Unsere Pläne sind in Gefahr!", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Olum ist einer meiner engsten Freunde und meiner treuesten Anhänger. Sein Beitrag zu unserem Werk ist für unsere Pläne unverzichtbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10945] = {title = "Hch'uu und das Pilzvolk", objective = "Bringt Euer Waisenkind Salandria nach Sporeggar in den Zangarmarschen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt. Sprecht danach mit Hch'uu.", description = "Ich habe eine Freundin namens Hch'uu. Sie hat mir erzählt, dass sie im Waisenhaus gelandet ist, weil sie vor einem bösen Fungusgiganten fliehen musste und sich verlaufen hat.\n\nWir hatten sehr viel Spaß zusammen, bis ihr Volk sie letztes Jahr gefunden und mitgenommen hat. Ich glaube, sie haben sie an einen Ort namens Sporeggar gebracht.\n\nIch würde sie und das Pilzdorf gerne sehen. Die Waisenmatrone hat mir gesagt, dass es auf der westlichen Seite der Zangarmarschen liegt, zwischen dem Sporenwindsee und dem Sumpflichtsee.\n\nGehen wir dorthin? Gehen wir dorthin? Bitte?!", progress = nil, completion = "Vielen Dank, dass Ihr mir die Möglichkeit gegeben habt, Salandria wiederzusehen. Ich habe sie im letzten Jahr so sehr vermisst, aber wir sind immer noch gute Freunde.\n\nWir sind uns einig, dass wir, wenn wir groß sind, genauso mutige Abenteurer werden wollen, wie Ihr es seid!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10946] = {title = "Die List der Aschenzungen", objective = "Reist in die Festung der Stürme und tötet Al'ar, während Ihr die Gugel der Aschenzungen tragt. Kehrt nach Abschluß der Aufgabe zu Akama ins Schattenmondtal zurück.", description = "Olums Opfer war gewaltig. Ich hätte ihn niemals gebeten, sein Leben für mich zu geben. Aber so ist es geschehen.\n\nWenn wir Illidan in falscher Sicherheit wiegen wollen, müssen wir seine Befehle ausführen, zumindest fürs Erste.\n\nIch befehlige eine große Armee von Aschenzungen, aber außer den Todeshörigen kann ich keinem davon trauen.\n\nIhr sollt die Tat, die Illidan wünscht, ausführen. Nehmt diese Gugel. Sie ist magisch. Jeder, der Euch Kaels Phönix Al'ar erschlagen sieht, wird Euch für einen meiner Männer halten.", progress = "Ist es vollbracht, <Name>? Illidan ist kein besonders geduldiger Herr!", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Dies bringt uns einen Schritt näher, Illidans Blick abzuwenden. Von uns und von...\n\n\n\nEs liegt noch mehr Arbeit vor uns, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10947] = {title = "Ein Artefakt aus der Vergangenheit", objective = "Reist zu den Höhlen der Zeit in Tanaris und verschafft Euch Zugang zur Schlacht um den Berg Hyjal. Habt Ihr dies geschafft, so bezwingt Furor Winterfrost und bringt das zeitverzerrte Phylakterium zu Akama im Schattenmondtal.", description = "Dank Euch richtet sich Illidans Aufmerksamkeit nun auf Kael'thas. Es ist an der Zeit zu handeln!\n\nIn einer Vision sah ich ein mächtiges Artefakt, welches in unserem Entscheidungskampf von größter Bedeutung sein wird, das Phylakterium eines mächtigen Lichs, bekannt als Winterfrost. Leider ging es nach seiner Niederlage in der Schlacht um den Berg Hyjal für immer verloren.\n\nEs gibt jedoch einen Weg, um wieder an das Artefakt zu gelangen. Die Legenden sprechen von einem Ort in Azeroth, welcher von bronzenen Drachen bewacht wird... ein Ort an dem Vergangenheit und Gegenwart nebeneinander existieren. Dort werdet Ihr finden, was wir suchen!", progress = "Ist das Phylakterium bereits in Eurem Besitz, <Name>?", completion = "Meine Vision... nun wird mir alles klar. Die Macht, die dieses Artefakt über eine Seele ausüben kann... sie einzuschließen... sie in sich selbst aufzunehmen... Ich werde diese Kraft dazu nutzen, um zurückzuholen, was rechtmäßig mir gehört! Der Augenblick ist gekommen, um den Kampf gegen Illidan aufzunehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10948] = {title = "Die Seelengeisel", objective = "Reist nach Shattrath und erzählt A'dal von Akamas Bitte.", description = "Ihr fragt Euch vielleicht, warum ich so weit gehe, um mein Vorhaben zu verschleiern. Warum arbeite ich nicht einfach offiziell mit den Naaru zusammen?\n\nMeine ureigene Essenz, meine Seele, wird im Schwarzen Tempel als Geisel gehalten. Mit einem Wimpernschlag könnte Illidan mich ausradieren... bis jetzt! Dieses Phylakterium wird es mir ermöglichen, meine Seele wieder in meine Kontrolle zu bringen.\n\nEs ist soweit, <Name>. Ich werde Maiev und meine Todeshörigen bis an Illidans Türschwelle führen.\n\nSprecht mit A'dal und berichtet ihm von unserem Plan. Wenn wir gemeinsam zuschlagen, werden wir Illidans Verteidigung durchbrechen können.", progress = nil, completion = "&lt;A'dals Licht umfängt Euch, als er Euch begrüßt. Ihr habt das Gefühl, dass er schon weiß, worum Ihr ihn bitten wollt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10949] = {title = "Zutritt zum Schwarzen Tempel", objective = "Reist zum Eingang des Schwarzen Tempels im Schattenmondtal und sprecht mit Xi'ri.", description = "<A'dal zeigt Euch ein Bild eines Naaru außerhalb des Schwarzen Tempels, der Seite an Seite mit Verteidigern der Draenei und Magistern der Blutelfen kämpft. Ihr wisst sofort, dass dies die Ablenkung ist, auf die Akama wartet.>", progress = nil, completion = "&lt;Xi'ri scheint Eure Anwesenheit zu bemerken. Offensichtlich konzentriert er sich auf die Schlacht in der Umgebung.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10950] = {title = "Auchindoun und der Ring der Beobachtung", objective = "Bringt Euer Waisenkind Dornaa zum Versammlungsstein beim Ring der Beobachtung in der Mitte von Auchindoun. Auchindoun liegt inmitten der Knochenwüste der Wälder von Terokkar. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", description = "Einer der Priester, der uns regelmäßig besucht, hat mir eine Geschichte über einen Ort in der Nähe erzählt. Er wird Auchindoun genannt und soll für die Draenei sehr wichtig sein.\n\nEr sagte, dass die Körper der verstorbenen Draenei an diesen Ort gebracht wurden. Aber vor einer Weile hat etwas Böses ihn in die Luft gejagt.\n\nIch würde dort gerne den Ring der Beobachtung sehen. Die Waisenmatrone hat mir gesagt, dass er in der Mitte der Knochenwüste liegt, auf der südlichen Seite der Wälder von Terokkar.\n\nKönnen wir dort bitte hingehen, <Herr/Frau> <Name>?", progress = nil, completion = "Oh, es ist wundervoll! Es sieht zwar ziemlich alt aus... und man sieht, dass es in die Luft gesprengt wurde. Aber schaut Euch doch nur um!\n\nOh, und habt Ihr Euch den Himmel angeschaut?\n\nKlasse!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10951] = {title = "Eine Reise zum Dunklen Portal", objective = "Geht mit Eurem Waisenkind Salandria die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", description = "Wie können wir uns all die interessanten Orte anschauen und dabei das Dunkle Portal vergessen?!\n\nDie Erwachsenen versuchen immer, uns Gruselgeschichten darüber zu erzählen, und schildern, wie gefährlich es dort ist mit den vielen Dämonen und all dem Zeugs.\n\n<Salandria rollt mit den Augen.>\n\nAber Ihr seid hier, also kann es ja nicht so schlimm sein, oder?\n\nIch will es selbst sehen. Könnt Ihr Euch noch erinnern, wo genau es sich am östlichen Rand der Höllenfeuerhalbinsel befindet?", progress = nil, completion = "Dieser Ort ist so viel cooler als in den Geschichten. Es ist beeindruckend!\n\nIst es wahr, dass ein mächtiger Zauberer namens Medivh es erschaffen hat?\n\nIch frage mich, was wohl auf der anderen Seite ist. Ihr wart schon dort, nicht wahr? Hm, wir sollten ganz sicher an einen Ort auf der anderen Seite des Dunklen Portals gehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10952] = {title = "Eine Reise zum Dunklen Portal", objective = "Geht mit Eurem Waisenkind Dornaa die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", description = "Es gibt einen Ort, den wir auf jeden Fall anschauen müssen: das Dunkle Portal!\n\nDie Waisenmatronen versuchen uns immer Gruselgeschichten darüber zu erzählen und wie gefährlich es dort ist mit vielen Dämonen und Leuten wie Euch, die hindurch kommen.\n\n<Dornaa rollt mit den Augen.>\n\nAber Ihr seid hier und Ihr seid nett, also kann es ja nicht so schlimm sein, oder?\n\nIch will es selbst sehen. Könnt Ihr Euch noch erinnern, wo genau es sich am östlichen Rand der Höllenfeuerhalbinsel befindet?", progress = nil, completion = "Die Geschichten der Waisenmatrone kommen diesem Ort nicht einmal im Geringsten nahe! Es ist beeindruckend! Sie hat gesagt, dass ein mächtiger Zauberer namens Medivh es erschaffen hat.\n\nWas ist auf der anderen Seite? Ihr wart schon dort, nicht wahr? Hm, wir sollten ganz sicher an einen Ort auf der anderen Seite des Dunklen Portals gehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10953] = {title = "Besuch beim Thron der Elemente", objective = "Bringt Euer Waisenkind Salandria zum Thron der Elemente in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Elementaristin Sharvak.", description = "Habt Ihr vom Thron der Elemente gehört? Er soll angeblich in Nagrand sein wo all die mächtigen Elementare sind.\n\nIch werde bald eine große Magierin oder eine Hexenmeisterin! Daher werde ich lernen müssen, wie man diese Elemente bändigt.\n\nKönnen wir vielleicht dorthin gehen?\n\n<Salandria schaut Euch listig an.>\n\nDas wäre fast schon eine Bildungsreise. Der Thron soll angeblich nördlich von Garadar sein, auf der anderen Seite des Himmelsweisensees.", progress = nil, completion = "Ihr bringt ein Kind hierher? Das ist ganz schön gewagt, aber ich verspreche Euch, dass Ihr nichts zustoßen wird, zumindest wenn sie Incineratus nicht zu nahe kommt.\n\nHm, welch Pech, dass sie eine Blutelfe ist. Könnte sie eine tiefere Verbindung zur Welt erlangen, könnten wir ihr vielleicht etwas beibringen, damit sie dabei helfen kann, die Wunden dieser Erde zu schließen. Aber vielleicht wird die Gegenwart der Elemente ihr ein paar Einblicke in ihre Natur geben.\n\nGeht in Frieden und kümmert Euch gut um sie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10954] = {title = "Jheel ist beim Aerissteg!", objective = "Bringt Euer Waisenkind Dornaa zum Aerissteg in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Jheel.", description = "Ich vermisse meinen Bruder Jheel. Er ist ein paar Jahre älter als ich und hat eine Ausbildung bei den Astralen in Nagrand angefangen.\n\nEs wäre so schön ihn einmal zu besuchen. Er liebt Geologie und so was, daher hat er bestimmt sehr viel Spaß.\n\nDie Waisenmatrone hat mir gesagt, dass er an einem Ort namens Aerissteg in Nagrand in Ausbildung ist. Er soll sich an der Straße weit westlich von Telaar und nordwestlich des großen Bergs Oshu'gun befinden.", progress = nil, completion = "Oh, ich habe Dornaa so sehr vermisst. Vielen Dank, dass Ihr mich mit ihr besuchen kommt. Ich bin hier nur von Astralen umgeben und fühle mich oft einsam. Sie sind sehr streng was die Geschäfte am Oshu'gun angeht.\n\nAber sobald mein Juwelenschleiferexamen abgeschlossen ist, werde ich auf einen Besuch ins Waisenhaus zurückkehren. Letzte Woche hätte ich fast bestanden, aber morgen werde ich es ganz sicher schaffen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10955] = {title = "Morthis Flügelraunen", objective = "Sucht nach Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Bevor die druidischen Orden sich zum Zirkel des Cenarius zusammenschlossen, brachten die Druiden der Kralle aufstrebenden jungen Druiden die Kunst des Fliegens bei. Nach der Auflösung des Ordens wurden die früheren Mitglieder was ihre Schüler angeht sehr wählerisch.\n\nMorthis Flügelraunen sucht noch immer nach einem würdigen Lehrling. Nur wenige Druiden haben je alle Formen beherrscht, die ihnen zur Verfügung stehen, doch Ihr versprecht das zu haben, wonach Morthis sucht. Sucht ihn bei der Zuflucht des Cenarius in den Zangarmarschen auf.", progress = nil, completion = "&lt;Morthis sieht Euch skeptisch an.&gt;\n\nIch suche schon lange nach einem Schüler, dem ich mein Wissen weitergeben kann. Obwohl die Druiden der Kralle kein offizieller Orden mehr sind, werde ich bis ans Ende meiner Tage einer von ihnen sein.\n\nVon diesem Moment an nehme ich Euch als Schüler an. Ich werde Euch in die Geheimnisse der Sturmkrähe einweihen. Ihr müsst im Gegenzug bereit sein, alles, worum ich Euch bitte, zu tun. Habt Ihr das verstanden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10956] = {title = "Der Sitz der Naaru", objective = "Bringt Euren Schützling Dornaa zu O'ros im unteren Teil des Sitzes der Naaru in der Exodar auf der Azurmythosinsel. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt.", description = "Wisst Ihr etwas über die Naaru? Das sind diese engelhaften Wesen, die den Draenei schon lange Zeit helfen. Ich habe ein paar von ihnen in Shattrath gesehen.\n\nMan sagt, dass der Naaru O'ros dabei war, als die Exodar in Eure Heimatwelt gereist ist. Ich würde das gerne selbst sehen.\n\nKönnt Ihr mich dorthin bringen? Ich wette, wenn wir eines dieser Portale im Tempel des Mondes in Darnassus benutzen, sind wir ganz schnell! Und wenn wir da sind, können wir einfach Eure Karte anschauen, wenn wir uns verirren.", progress = "Ich habe Euch erwartet.", completion = "&lt;Ihr spürt O'ros' melodische Stimme in Eurem Geist.&gt;\n\nVielen Dank, dass Ihr dieses Kind zu mir gebracht habt, &lt;Name&gt;. Sie ist in der Tat etwas ganz Besonderes und wird einst eine wichtige Persönlichkeit für die Draenei werden. Dies verdankt sie nicht zuletzt Eurer Freundlichkeit und dem Eindruck, den Ihr auf sie gemacht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10957] = {title = "Die Erlösung der Aschenzungen", objective = "Helft Akama die Kontrolle über seine Seele wieder zu erlangen, indem Ihr Akamas Schemen im Schwarzen Tempel besiegt. Kehrt anschließend zu Seher Kanai zurück.", description = "Als Illidan die Treue der Zerschlagenen erlangt hat, war Akama der Weiseste unter uns. Er wusste, dass eine direkte Konfrontation mit dem Verräter das Ende unseres Volkes bedeuten würde.\n\nStattdessen hat er diesen Moment in aller Verstohlenheit geplant und vorbereitet. Ein Versagen wäre eine Katastrophe... nicht nur für Akama, nicht nur für die Zerschlagenen, sondern für die gesamte Scherbenwelt. Niemand, der Illidan so nahe stand, war je in der Lage gewesen, ihm einen solchen Schlag zu versetzen.\n\nHelft Akama dabei, seine Seele zu befreien. Dann wird er Euch Zutritt zu Illidans Sanktum gewähren.", progress = "Ja, <Name>?", completion = "Es ist vollbracht, &lt;Name&gt;. Nun ist es an der Zeit, Illidan zu vernichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10958] = {title = "Sucht die Aschenzungen auf", objective = "Sucht Akamas Todeshörige im Schwarzen Tempel.", description = "<Als Ihr zu Xi'ri aufblickt, schärft sich Euer Geist und Euer Wille wird stark. Eure Arbeit hier ist noch nicht vorüber. Ihr müsst in den Schwarzen Tempel gehen und Akamas Anhänger finden.>\n\n<Es hängt sehr viel von Akamas Erfolg ab.>", progress = nil, completion = "Wir haben Euch bereits erwartet, &lt;Name&gt;. Akama braucht dringend Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10959] = {title = "Der Sturz des Verräters", objective = "Seher Kanai möchte, dass Ihr Illidan im Schwarzen Tempel besiegt.", description = "Jetzt, da Illidans Leutnants besiegt sind, wird Akama die Türen zu Illidans Sanktum aufbrechen. Haltet Euch und Eure Streitkräfte bereit, um sofort hinein zu stürmen, sobald Akama es geschafft hat.\n\nWir wissen immer noch nicht, was aus Maiev geworden ist, aber wir müssen ohne sie beginnen.\n\nIch hoffe, dass Eure Streitkräfte der Sache gewachsen sind. Illidan wird nicht sehr erfreut sein, wenn er Akama zu Gesicht bekommt.", progress = "Ja, <Name>?", completion = "Es ist geschehen, wie es vorherbestimmt war, &lt;Name&gt;. Illidans Leutnants sind einer nach dem anderen gefallen... und sogar der Verräter fand den Tod!\n\nWisset eines, &lt;Name&gt;: bei jeder Entscheidung, die Akama seit der Ankunft Illidans in seinem Leben getroffen hat, war dieser Augenblick sein Ziel. Illidan ist nun endlich tot und unser Volk... ist frei!", rewards = "Ihr bekommt:\n\nGesegnetes Medaillon von Karabor"}
MultiLanguageQuestData['de'][10960] = {title = "Wenn ich groß bin...", objective = "Bringt Euren Schützling Salandria zu den Paladinlehrern auf dem Platz der Weltenwanderer in Silbermond. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt. Sprecht danach mit Lady Liadrin, der Matriarchin der Blutritter.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden und die Wachen nach den Paladinlehrern fragen könnt.", description = "Wusstet Ihr in meinem Alter schon, dass Ihr später mal <ein/eine:c> <Klasse> werden wollt?\n\nIch weiß noch nicht, was ich einmal werden will. Vielleicht ein Magier oder Hexenmeister, wie ich vorhin schon sagte - oder vielleicht ein Paladin der Blutritter! Ja, ich will auf jeden Fall Blutritter werden!\n\nMan sagt, dass die echten Blutritter in Silbermond in Eurer Welt ausgebildet werden. Könnt Ihr mich dorthin bringen? Die Geschichten, die ich gehört habe, besagen, dass die Paladinlehrer sich auf dem Platz der Weltenwanderer in dieser Stadt aufhalten.\n\nBitte bringt mich dorthin. Bitte!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10961] = {title = "Der Zauber des Erwachens", objective = "Bringt 10 Sumpfblüten, 10 Urflechten und 10 Traumwinden zu Morthis Flügelraunen in der Zuflucht des Cenarius.", description = "Vor langer Zeit wurden die Relikte, mit deren Hilfe man den Weg der Sturmkrähe lehrte, einem uralten Druiden anvertraut.\n\nWir werden diese Relikte für Eure Ausbildung brauchen, daher müssen wir den Wächter aus seinem Schlummer erwecken.\n\nIch werde Euch einen Trank zubereiten, mit dessen Hilfe Ihr den Vorgang erleichtern könnt. Für das Gebräu benötige ich gewöhnliche Kräuter und Sumpfblüten, die auf den höchsten Pilzen in den Marschen wachsen. Fliegt an ihnen hoch und seid beim Sammeln der Blüten vorsichtig, <Name>, sie sind ziemlich empfindlich und könnten bei falscher Handhabung heftig explodieren.", progress = "Habt Ihr alle Zutaten, die ich für die Zubereitung des Tranks benötige? Vorsicht, bringt nur keine Pollen in meine Nähe, bitte. Ich muss deswegen immer furchtbar niesen.\n\n<Morthis schnüffelt gedemütigt bei einem Niesen.>", completion = "&lt;Morthis nimmt die Kräuter entgegen und untersucht sie. Er holt eine Phiole hervor und beginnt den Trank zu mischen.&gt;\n\nEs dauert nur einen Moment, &lt;Name&gt;. Dann müsst Ihr zur Mondlichtung reisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10962] = {title = "Zeit die Höhlen zu besuchen", objective = "Bringt Euren Schützling Dornaa zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.\n\nErwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels.", description = "Im Waisenhaus erzählt der alte Priester, der uns immer besuchen kommt, oft Geschichten über die Höhlen der Zeit. Er sagt, dass sie im Zentrum der Zeit liegen und unheimlich wichtig sind, damit alle Dinge ihren gewohnten Gang gehen.\n\nIch weiß nicht genau, was das heißt, aber er hat gesagt, dass es da Drachen gibt, die dabei helfen die Welt zu retten! Ich will einen Drachen sehen!\n\nKönnten wir da hingehen? Er sagte, dass der Eingang sich am östlichen Rand einer großen Wüste namens Tanaris befände.\n\nVielleicht könnt Ihr mir ja auch ein Andenken kaufen, während wir da sind?", progress = "Meint Ihr, dass die Geschichten über die Höhlen der Zeit stimmen?", completion = "Supi! Mein eigener Drache! Ich hoffe, dass ich eines Tages das Glück haben werde, einen Drachen zum Freund zu haben.\n\n&lt;Dornaa springt fröhlich auf und ab und presst ihr neues Spielzeug fest an sich.&gt;\n\nDas war der beste Ausflug meines ganzen Lebens! Hoffentlich ist er nie vorbei!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10963] = {title = "Zeit die Höhlen zu besuchen", objective = "Bringt Euren Schützling Salandria zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.\n\nErwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels.", description = "Im Waisenhaus erzählt der stinkende alte Priester, der uns immer besuchen kommt, oft Geschichten über die Höhlen der Zeit. Er sagt, dass sie im Zentrum der Zeit liegen und unheimlich wichtig sind, damit alle Dinge ihren gewohnten Gang gehen.\n\nIch weiß nicht genau, was das heißt, aber er hat gesagt, dass es da Drachen gibt, die dabei helfen die Welt zu retten! Ich will einen Drachen sehen!\n\nKönnten wir da hingehen? Er sagte, dass der Eingang sich am östlichen Rand einer großen Wüste namens Tanaris befände.\n\nVielleicht könnt Ihr mir ja auch ein Andenken kaufen, während wir da sind?", progress = "Wenn das, was man über die Höhlen der Zeit sagt, stimmt, muss dieser Ort sehr mächtig sein!", completion = "Klasse! Mein eigener Drache! Eines Tages will ich einen echten besitzen.\n\n&lt;Salandria schaut ihr neues Spielzeug scharf an. Fast hört man die Räder in ihrem Kopf rattern.&gt;\n\nDas war der beste Ausflug meines ganzen Lebens! Ich hoffe, er geht nie vorbei!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10964] = {title = "Den Schläfer wecken", objective = "Benutzt den Zauber des Erwachens um Clintar Traumwandler aus dem Smaragdgrünen Traum zu holen. Sprecht mit ihm, sobald er zu sich kommt.", description = "Nehmt den Zauber mit Euch und reist zu Sturmgrimms Grabhügel auf der Mondlichtung. Im südlichsten Teil von Sturmgrimms Grabhügel, der von den Traumwächtern bewacht wird, werdet Ihr Clintar Traumwandler finden.\n\nGebt ihm den Zaubertrank und beschützt ihn, während er erwacht. Er wird sehr leicht verwundbar sein, während sein Geist sich mit seinem Körper verbindet, und Euch sicher nicht erkennen. Erklärt ihm, wer Ihr seid, wenn er zu Kräften kommt, <Name>. Er wird Eure Hilfe brauchen, um die Relikte für das Ritual zu sammeln.", progress = "<Ihr bereitet Euch darauf vor, dem schlafenden Druiden den Zaubertrank zu verabreichen.>", completion = "&lt;Der &lt;Klasse&gt; erwacht aus seinem Schlaf und wirkt benommen und ausgezehrt. Sein Blick wandert auf der Suche nach unsichtbaren Verfolgern im Raum herum.&gt;\n\nMorthis?\n\nNein, Ihr seid nicht Morthis... Wer seid Ihr, &lt;Volk&gt;, und warum stört Ihr meine Ruhe?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10965] = {title = "Mehr als ein Traum", objective = "Beschützt Clintar Traumwandlers Geist während er die Relikte von Aviana sammelt. Sprecht danach mit Traumwächter Lurosa.", description = "<Clintar hört Euch nickend zu, als Ihr Morthis Anweisungen weitergebt, aber er scheint Angst zu haben.>\n\nIch kann mich nicht vollständig aus dem Smaragdgrünen Traum zurückziehen, um Euch zu helfen. Ich werde Euch jedoch ein Fragment meiner Seele auf der Suche nach den Relikten mitgeben. Passt gut darauf auf, <Volk>, denn mein Geist ist sehr zerbrechlich.\n\nDer Smaragdgrüne Traum selbst ist zu einem fremdartigen und gefährlichen Ort geworden. Er hält mich fest umklammert. Ich werde mich nicht lösen können, bis der Smaragdgrüne Traum wieder normal geworden ist. Was Ihr um Euch herum seht ist nur ein Nachhall der Wirklichkeit im Traum selbst!", progress = "Beeilt Euch, <Volk>. Wenn diese Kreaturen aus dem Grabhügel entkommen, ist nicht nur Clintar Traumwandler in Gefahr!", completion = "Ihr hattet Glück, dass Clintar stark genug war, seine Essenz so lange am Leben zu erhalten, &lt;Name&gt;. Nur wenige Druiden schaffen das, während sie im Smaragdgrünen Traum angegriffen werden. Gebt gut auf die Relikte Acht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10966] = {title = "Zurück zum Waisenhaus", objective = "Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im Unteren Viertel.", description = "Verdammt! Ich glaube, wir müssen zum Waisenhaus in Shattrath zurück.\n\nIch hatte so viel Spaß! Ihr seid <der/die> Tollste aller Welten, <Name>! Ihr seid jetzt <mein großer Bruder/meine große Schwester>!\n\n<Dornaas Augen füllen sich mit Tränen.>\n\nIch werde Euch so vermissen! Wenn ich groß bin, will ich genauso sein wie Ihr!!!", progress = nil, completion = "Es ist Balsam für die Seele zu wissen, dass es Helden wie Euch gibt, die ihre Zeit so selbstlos opfern.\n\nIch sehe jetzt schon, dass die Zeit mit Euch einen großen Eindruck auf Dornaa gemacht hat. Es ist schön, dass die Kinder eine Gelegenheit bekommen, einmal aus der Stadt heraus zu kommen und die Welt zu sehen.\n\nSie möchte, dass Ihr Euch um einen ihrer Lieblingsbegleiter kümmert, genauso, wie Ihr Euch um sie gekümmert habt. So könnt Ihr Euch immer an sie erinnern.\n\nSchaut doch ab und zu mal vorbei!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElekkhalsbandEi des KolumbusSchläfriger WillyBeinchenMagisches Leckerli\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10967] = {title = "Zurück zum Waisenhaus", objective = "Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im Unteren Viertel.", description = "Verdammt! Ich glaube, wir müssen zum Waisenhaus in Shattrath zurück.\n\nIch hatte so viel Spaß! Ihr seid <der/die> Tollste aller Welten, <Name>! Ihr seid jetzt <mein großer Bruder/meine große Schwester>!\n\n<Salandrias Augen füllen sich mit Tränen.>\n\nIch werde Euch so vermissen!!!", progress = "Schön, Euch wiederzusehen, <Klasse>. Hatten die kleine Salandria und Ihr eine schöne Zeit zusammen?", completion = "Es ist Balsam für die Seele zu wissen, dass es Helden wie Euch gibt, die ihre Zeit so selbstlos opfern.\n\nIch sehe jetzt schon, dass die Zeit mit Euch einen großen Eindruck auf Salandria gemacht hat. Es ist schön, dass die Kinder eine Gelegenheit bekommen, einmal aus der Stadt heraus zu kommen und die Welt zu sehen.\n\nSie möchte, dass Ihr Euch um einen ihrer Lieblingsbegleiter kümmert, genauso, wie Ihr Euch um sie gekümmert habt. So könnt Ihr Euch immer an sie erinnern.\n\nSchaut doch ab und zu mal vorbei!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEi des KolumbusElekkhalsbandSchläfriger WillyBeinchenMagisches Leckerli\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][10968] = {title = "Besucht den Scharfseher", objective = "Bringt Euren Schützling Dornaa zu Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt.", description = "Ich spüre, dass dieses Kind etwas ganz besonderes ist.\n\nIhr solltet sie zu Scharfseher Nobundo hier auf der Exodar bringen. Ich glaube, dass er Euch beide schon erwartet.\n\nIhr findet Nobundo auf der höchsten Terrasse in der Kristallhalle.", progress = nil, completion = "Ich habe gehofft, doch gleichzeitig befürchtet, dass sie nur in meiner Fantasie existiert. Dieses Kind ist erstaunlich!\n\nBisher hat kein Draenei in diesem Alter und ohne Ausbildung eine so tiefe Verbindung zu den Elementen gezeigt. Sie muss ihre Fähigkeiten von einem uralten Vorfahren geerbt haben.\n\nIch werde der Weisenmatrone in Shattrath einen Brief schicken und sie darum bitten, dass das Kind bei uns bleiben kann.\n\nBitte sorgt bis dahin für ihr Wohlergehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10969] = {title = "Sucht Ameer!", objective = "Sucht Kommandant Ameer beim Wachposten des Protektorats auf.", description = "Es scheint als ob eine außenstehende Macht Interesse an den Geschäftsmethoden des Konsortiums gewonnen hat. In den letzten beiden Tagen wurden fünf Händler des Konsortiums als vermisst gemeldet. Es besteht großer Grund zur Annahme, dass das Astraleum etwas damit zu tun hat. Wenn Ihr helfen möchtet, sucht nach Kommandant Ameer beim Wachposten des Protektorats.\n\nIhr findet den Wachposten des Protektorats östlich von hier auf der nächsten Insel.", progress = nil, completion = "Ja, das stimmt. Doch das Konsortium ist nicht die einzige Gruppierung, die Verluste zu vermelden hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10970] = {title = "Ein barmherziger Auftrag", objective = "Beschafft Euch den sichergestellten Gefängnisschlüssel des Astraleums und bringt ihn zu Kommandant Ameer beim Wachposten des Protektorats im Nethersturm.", description = "Wir haben diese Gefängniskugel auf unserer letzten Spähermission im Gebiet des Astraleums sichergestellt. Hätte sie nicht dieses schwache Störsignal gesendet, hätten wir sie vielleicht nie gefunden.\n\nWir glauben, dass einer von uns darin eingesperrt ist, aber wir haben keine Möglichkeit die Kugel zu öffnen ohne den Inhalt zu verletzen.\n\nWir wissen nur, dass praktisch jedes Mitglied des Astraleums den Schlüssel dazu haben könnte. Beschafft Euch einen Schlüssel und bringt ihn zu uns, damit wir das Geheimnis der Kugel entschlüsseln können.", progress = "Hattet Ihr Glück?", completion = "Tretet zurück, &lt;Name&gt;. Es könnte auch eine Falle des Astraleums sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10971] = {title = "Geheimnisse des Astraleums", objective = "Kommandant Ameer beim Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm eine Identifizierungsmarke eines Gefangenen des Astraleums bringt.", description = "<Ameer hält eine Marke hoch.>\n\nIch habe diese Identifizierungsmarke eines Gefangenen bei den Überresten des gefallenen Vorpostens gefunden. Ich gehe davon aus, dass alle ihre Gefangenen auf diese Weise markiert werden.\n\nIch werde damit anfangen, alle Marken zu katalogisieren. Vielleicht kann ich so etwas über das System ihrer Gefangennahmen herausfinden. Falls Ihr auf Euren Abenteuern noch mehr Gefängnisschlüssel des Astraleums finden solltet, könnt Ihr damit die Gefängnisse des Astraleums beim Stützpunkt des Astraleums direkt südlich von hier aufschließen. Bringt mir alle Identifizierungsmarken, die Ihr finden könnt!", progress = "Habt Ihr ein paar Identifizierungsmarken finden können?", completion = "Es scheint sich hierbei um mehr als eine einfache Identifizierungsmarke zu handeln. Auf den Marken ist eine Art Code zu sehen. Ich stehe kurz davor, ihn zu entschlüsseln. Wenn ich doch nur mehr Marken hätte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10972] = {title = "Katalog der Gefangenen des Astraleums", objective = "Ich brauche mehr Identifikationsmarken, <Name>. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", description = "Ich brauche mehr Identifizierungsmarken, <Name>. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", progress = "Ich brauche mehr Identifikationsmarken, <Name>. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", completion = "Wir sind der Wahrheit auf der Spur, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][10973] = {title = "Tausend Welten", objective = "Kommandant Ameer am Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm 5 Gefängnisschlüssel des Astraleums bringt.", description = "Ich habe den Code entschlüsselt! Jede Marke ist in verschiedene Segmente geteilt. Die Vorderseite der Marke ist immer gleich. Darauf steht: \"Tausend Welten...\". Ich bin mir nicht sicher, was das zu bedeuten hat, aber es klingt irgendwie heimtückisch.\n\nAuf der Rückseite der Marke stehen die wichtigen Angaben. Die erste Gruppe von Runen gibt den Aufenthaltsort an, die zweite die Art der Gefangenschaft. Des Weiteren sieht es aus, als ob die Schlüssel zu einem besonderen Schlüssel zusammengefügt werden können, mit dem man eine andere Art von Gefängnis öffnen kann. Jetzt brauche ich noch mehr Schlüssel...", progress = "Ich weiß, dass ich Euch um viel bitte, aber denkt an all die Leben, die wir retten könnten!", completion = "&lt;Ameer fügt die Schlüssel geschickt zusammen und betrachtet die Markierungen auf der so hergestellten Schlüsseltafel.&gt;\n\n\"Tausend Welten zerschlagen, tausend weitere noch zu bezwingen... So lautet der Wille des Nexuskönigs.\"\n\n&lt;Ameer dreht die Tafel um und liest die Rückseite.&gt;\n\nStasiskammern von Bash'ir?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10974] = {title = "Stasiskammern von Bash'ir", objective = "Benutzt die Schlüsseltafel des Astraleums - Alpha um die Stasiskammer Alpha im Landeplatz von Bash'ir im Schergrat zu öffnen.\n\nBringt Beweisstücke aus Alpha zum Bild von Kommandant Ameer beim Landeplatz von Bash'ir.", description = "Das Astraleum hat eine kleine Siedlung am nördlichsten Rand des Schergrats, die als Landeplatz von Bash'ir bekannt ist. Laut der Schlüsseltafel soll es in Bash'ir noch größere Gefängnisse geben. Die Anhänger des Astraleums nennen sie Stasiskammern.\n\nDie Schlüsseltafel gewährt Zugang zu einer ganz bestimmten Stasiskammer am Landeplatz, die als Stasiskammer Alpha bekannt ist. Nehmt den Schlüssel und kundschaftet sie aus.\n\nMein Bild wird neben dem Landeplatz von Bash'ir auf Eure Rückkehr warten. Sprecht mit mir, wenn Ihr fertig seid.", progress = "Ihr habt es geschafft! Hattet Ihr Glück?", completion = "&lt;Das Bild von Kommandant Ameer kramt in den Beweisstücken.&gt;\n\nEs ist schlimmer als ich dachte... Diese Kammern enthalten wilde Bestien und Kreaturen von vielen verschiedenen Welten. Das Astraleum hofft, eines Tages Kontrolle über diese Bestien zu gewinnen und sie ihrem Willen zu unterwerfen. Wir müssen sie alle vernichten!", rewards = "Ihr bekommt:\n\nSchatzbehälter des Protektorats"}
MultiLanguageQuestData['de'][10975] = {title = "Die Reinigung der Kammern von Bash'ir", objective = "Wir sitzen in der Sackgasse, <Name>. Die Daten, die Ihr gesammelt habt, haben uns genügend Informationen geliefert, um unsere Verbündeten aus den kleineren Gefängnissen des Nethersturms retten zu können. Wir müssen uns jedoch dringend um die Bedrohung kümmern, die von den Kammern hier im Ladeplatz von Bash'ir ausgeht.\n\nSchließt Euch dem Kampf gegen das Astraleum an! Bringt mir die Gefängnisschlüssel des Astraleums, damit ich Stasiskammerschlüssel für die Stasiskammern von Bash'ir für Euch herstellen kann.", description = nil, progress = "Wir sitzen in der Sackgasse, <Name>. Die Daten, die Ihr gesammelt habt, haben uns genügend Informationen geliefert, um unsere Verbündeten aus den kleineren Gefängnissen des Nethersturms retten zu können. Wir müssen uns jedoch dringend um die Bedrohung kümmern, die von den Kammern hier im Ladeplatz von Bash'ir ausgeht.\n\nSchließt Euch dem Kampf gegen das Astraleum an! Bringt mir die Gefängnisschlüssel des Astraleums, damit ich Stasiskammerschlüssel für die Stasiskammern von Bash'ir für Euch herstellen kann.", completion = "Es gibt immer noch mehr Arbeit, die erledigt werden muss, &lt;Name&gt;. Begebt Euch nun auf die Suche nach einer Stasiskammer und vernichtet, was auch immer darin lauern mag!", rewards = "Ihr bekommt:\n\nStasiskammerschlüssel des Astraleums"}
MultiLanguageQuestData['de'][10976] = {title = "Das Abzeichen des Nexuskönigs", objective = "Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr ihm ein Abzeichen des Nexuskönigs bringt.", description = "Jetzt muss ich wissen, was das Astraleum in der Managruft in Auchindoun gefangen hält.\n\nVielleicht ist Euch in Euren Kämpfen gegen die Bestien der Stasiskammern von Bash'ir ein Gegenstand untergekommen, der als Abzeichen des Nexuskönigs bekannt ist. Wenn Ihr einen solchen Gegenstand finden solltet, bringt ihn sofort zu mir! Dieses Abzeichen ist der letzte Teil, den ich zur Herstellung eines Schlüssels brauche, der Euch Zugang zu der Stasiskammer in der Managruft gewähren wird.", progress = "Dies wird Eure furchteinflößendste Aufgabe sein, <Name>.", completion = "Endlich!\n\n&lt;Kommandant Ameer liest die Inschrift auf dem Abzeichen des Nexuskönigs.&gt;\n\nZwei Gefängnisse? Schon der Gedanke an die Schrecken, die darin hausen mögen, lässt mich erzittern...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10977] = {title = "Stasiskammern der Managruft", objective = "Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr den Stasiskammerschlüssel der Managruft verwendet, um die Stasiskammer in der Managruft Auchindouns zu öffnen.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ich habe aus dem Abzeichen des Nexuskönigs einen neuen Schlüssel hergestellt, mit dem Ihr die Stasiskammern in der Managruft betreten könnt.\n\nLaut den Glyphen auf dem Abzeichen gibt es gleich zwei davon: eine in der Nähe der Vorderseite, eine weitere in der Nähe von Nexusprinz Shaffar. Der Schlüssel, den ich Euch nun geben werde, öffnet die Stasiskammer in der Nähe der Vorderseite.\n\nIch möchte, dass Ihr in die Managruft von Auchindoun reist und die Stasiskammer der Managruft öffnet.", progress = "Ich könnte verstehen, wenn Ihr lieber nicht weitermachen wollt, <Name>.", completion = "Ich habe von Euren Heldentaten erfahren, &lt;Name&gt;. Haramad und ich sind uns beide einig, dass Ihr dafür eine großartige Belohnung verdient habt.\n\nObwohl... Ach, Ihr habt schon genug getan. Ich kann Euch nicht guten Gewissens um noch mehr bitten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][10978] = {title = "Rückkehr zu Morthis Flügelraunen", objective = "Bringt die Relikte von Aviana zu Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen.", description = "Jetzt, da die Relikte geborgen wurden, müsst Ihr diesen Ort so schnell wie möglich wieder verlassen. Clintar hat seine eigene Sicherheit sowie die der Traumwächter für Euch aufs Spiel gesetzt, <Name>. Nun muss er sich vollkommen auf den Kampf gegen die Macht konzentrieren, die in den Smaragdgrünen Traum eingedrungen ist.\n\nBringt die Relikte zu Morthis Flügelraunen und berichtet ihm, was Ihr hier gesehen habt. Vielleicht kann er uns dabei helfen herauszufinden, mit wem Clintar es zu tun hat.", progress = "Hat Clintar Euch bei der Beschaffung der Relikte geholfen?", completion = "&lt;Morthis nimmt Euch die Relikte ab, während Ihr Eure Erlebnisse in den Grabhügeln schildert.&gt;\n\nDas sind äußerst beunruhigende Nachrichten, &lt;Name&gt;. Es gab ein paar Störungen im Smaragdgrünen Traum, aber ich kann mich nicht entsinnen, dass je von einer außenstehenden Macht gesprochen wurde, die ihre Finger im Spiel hat. Seid Ihr sicher, dass Clintar es genau so gemeint hat?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10979] = {title = "Zum Ewigen Hain", objective = "Sprecht mit Arthorn Windweise im Ewigen Hain im Schergrat.", description = "Seid Ihr sicher, dass Ihr einen Raben im Grabhügel gesehen habt?\n\nDas ist eine erschreckende Entwicklung. Wir können Clintar und den Traumwächtern nicht direkt helfen. Wenn wir jedoch herausfinden, was den Smaragdgrünen Traum bedroht, können wir es vielleicht aufhalten.\n\nWir haben erfahren, dass ein alter Arakkoakult im Schergrat wiederauflebt, der den Rabengott anbetet. Geht zum Ewigen Hain und sucht nach Arthorn Windweise. Vielleicht besteht zwischen den Geschehnissen dort und dem Angriff auf den Smaragdgrünen Traum eine Verbindung.", progress = nil, completion = "&lt;Arthorn hört aufmerksam zu. Ihr erklärt, dass Morthis Flügelraunen Euch geschickt hat, um zu untersuchen, ob zwischen dem Kult des Rabengottes und den merkwürdigen Geschehnissen auf der Mondlichtung ein Zusammenhang besteht. Die Nachricht erschüttert sie zwar, jedoch scheint es mehr an der Art und Weise der Botschaft selbst zu liegen.&gt;\n\nOh mein...\n\nIch habe Timeon bei seinen Nachforschungen über den Rabenkult unterstützt. Ich hätte jedoch nie gedacht, dass der Rabe auch außerhalb des Schergrats Einfluss hätte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10980] = {title = "Das Buch des Raben", objective = "Benutzt das Auge eines Ätherrochen in Verbindung mit Eurem Stein des Sehers, um die Geister des Rabenkultes sehen zu können. Sucht beim Vortexgipfel nach dem Geist von Sai'kkal dem Ältesten und fragt ihn über das 'Buch des Raben' aus. Kehrt danach zu Arthorn Windweise zurück.", description = "Euren Erzählungen nach scheint Morthis mit seinen Verdächtigungen doch richtig gelegen zu haben. Wir brauchen jedoch Gewissheit.\n\nBei seinen Nachforschungen ist Timeon auf ein 'Buch des Raben' gestoßen, das angeblich ein altes Schriftstück des Kultes sein soll.\n\nDie Arakkoageister werden sich Euren Augen nicht zu erkennen geben. Begebt Euch mit diesem Stein zu den höchsten Gipfeln im westlichen Teil des Schergrats südlich des Rabenwaldes, beschafft Euch das Auge eines Ätherrochen und kombiniert beides, um Eure Sicht zu verstärken. Sucht nach dem Geist, den Timeon als Geist von Sai'kkal dem Ältesten identifiziert hat.", progress = "<Arthorn schaut Euch hoffnungsvoll an.>\n\nKonntet Ihr an Informationen über das Buch gelangen?", completion = "Ist es nicht erstaunlich, dass diese Kultisten sogar unter den Arakkoa als Ketzer galten? Dass der Hass der traditionellen Priester auf sie groß genug war um ihren heiligen Text zu zerstören ist unglaublich! Wir müssen an dieses Buch herankommen, &lt;Name&gt;. Es ist der Schlüssel zum Geheimnis des Rabengottes. Damit werden wir verhindern können, dass er den Smaragdgrünen Traum an sich reißt.\n\nSollten wir Erfolg haben, wird Morthis mich vielleicht endlich als seinen Schüler akzeptieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10981] = {title = "Nexusprinz Shaffars persönliche Kammer", objective = "Nur die standhaftesten und erfahrensten Abenteurer würden auf ein solches Angebot eingehen, <Name>. Falls Ihr Euch den Schrecken der zweiten Stasiskammer der Managruft stellen wollt, kann ich einen Schlüssel dazu herstellen. Bringt mir ein Abzeichen des Nexuskönigs! Dann werde ich tun, worum Ihr bittet.", description = nil, progress = "Nur die standhaftesten und erfahrensten Abenteurer würden auf ein solches Angebot eingehen, <Name>. Falls Ihr Euch den Schrecken der zweiten Stasiskammer der Managruft stellen wollt, kann ich einen Schlüssel dazu herstellen. Bringt mir ein Abzeichen des Nexuskönigs! Dann werde ich tun, worum Ihr bittet.", completion = "Und hier habt Ihr den versprochenen Schlüssel zu Shaffars persönlicher Stasiskammer.", rewards = "Ihr bekommt:\n\nShaffars Stasiskammerschlüssel"}
MultiLanguageQuestData['de'][10982] = {title = "Das Auge des Haramad", objective = "Ihr habt viel für das Protektorat und das Konsortium getan, <Name>. Daher ist es nur gerecht, dass einer unserer neuen Schlüssel an Euch geht. Mit diesem Schlüssel könnt Ihr Shaffars persönliche Stasiskammer jederzeit öffnen, ohne den Schlüssel dabei zu zerstören.\n\n\n\nEr ist von Dauer und wird auf ewig Euch gehören.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDas Auge des Haramad"}
MultiLanguageQuestData['de'][10983] = {title = "Mog'dorg der Weise", objective = "Besucht Mog'dorg den Weisen auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", description = "Mog'dorg weise! Er schicken Grok in Stadt, Hilfe holen. Blutschlägerklan brauchen Hilfe.\n\nMog'dorg sagen, schicken mächtige Kleine zu ihm in Schergrat. Er stehen auf Turm bei Zirkel des Blutes. Mog'dorg weise!", progress = nil, completion = "Grok sagt, ich bin weise? Ich weiß ja nicht so recht.\n\nVielleicht liegt das daran, dass ich der Einzige meines Klans bin, der aufrichtig versucht uns vor der Vernichtung durch den Speerspießerklan zu retten. Und natürlich vor Gruul und seinen Söhnen, die sie unterstützen.\n\nIch hoffe, dass Ihr gekommen seid, um uns aus der unaufhaltsamen Verdammnis zu erretten, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10984] = {title = "Sprecht mit dem Oger", objective = "Sprecht mit dem Oger Grok im Unteren Viertel von Shattrath.", description = "<V'erus Stimme erfüllt Euren Geist mit kristallener Melodie und Klarheit.>\n\nEs streunt ein Oger im Unteren Viertel umher, der alle Passanten um Hilfe anfleht. Doch keiner will seiner Not Gehör schenken. Könntet Ihr ihm vielleicht helfen?\n\nSein Name ist Grok. Er sitzt in der Nähe der Händler im Südwesten.\n\nSeid bedankt, <Name>.", progress = nil, completion = "Ihr helfen Grok? Grok brauchen Hilfe! Blutschläger brauchen Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10985] = {title = "Ein Ablenkungsmanöver für Akama", objective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel im Schattenmondtal betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", progress = "<Xi'ri registriert Eure Anwesenheit.>", completion = "&lt;Xi'ri pulsiert vor Energie, Ihr fühlt, wie ein Gegenstand in Euren Händen Gestalt annimmt. Es ist das Medaillon, das Ihr A'dal im Namen von Akama gegeben habt. Seine Macht hat sich durch die Magie der Naaru noch verstärkt. Die Sha'tar haben Euch das Medaillon von Karabor anvertraut, und damit den Zugang zum Schwarzen Tempel.&gt;", rewards = "Ihr bekommt:\n\nMedaillon von Karabor"}
MultiLanguageQuestData['de'][10986] = {title = "Blick zum Himmel", objective = "Sprecht mit Behüterin Elaira bei der Zwielichthöhe in Nagrand.", description = "Alle Teile des Buchs des Raben zu finden wird schwierig. Wenn sie es überhaupt überleben. Wir benötigen schärfere Augen als Eure dafür.\n\nUnten im westlichen Nagrand, am östlichen Rand der Zwielichthöhe, untersucht Behüterin Elaira die lokalen Vogelarten. Sucht sie auf und schaut, ob sie Eure Vogelperspektive etwas verbessern kann, damit Ihr die Teile des Buchs des Raben finden könnt.", progress = nil, completion = "&lt;Elaira hört Euch aufmerksam zu, als Ihr ihr von Eurer Suche nach dem Buch des Raben und Arthorns Vorschlag berichtet, die verschollenen Teile des Buchs mit Hilfe von Vögeln zu finden.&gt;\n\nDas ist eine ausgezeichnete Idee. Nagrand ist voll von geeigneten Kandidaten für diese Aufgabe, aber welchen sollen wir wählen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10987] = {title = "Der Spatz in der Hand", objective = "Benutzt das Sperbernetz um einen wilden Sperber zu fangen und bringt ihn zu Behüterin Elaira auf der Zwielichthöhe.", description = "Die wilden Sperber Nagrands haben von allen Raubvögeln hier die schärfsten Augen. Wegen Ihrer Größe wurden sie von den größeren Windrocs aus den meisten Gegenden verdrängt.\n\nDie meisten Sperber nisten hier auf der Zwielichthöhe. Wenn Ihr einen davon fangt, kann ich ihn so trainieren, dass er die Teile Eurer vergrabenen Tafel entdecken kann.\n\nDas wird allerdings nicht so einfach. Die Sperber sind sehr scheu und werden fliehen, sobald sie Euch sehen. Ich schlage vor, dass Ihr einen davon in die Enge treibt oder Euch nahe genug anschleicht, damit Ihr ihn mit einem Netz fangen könnt.", progress = "Habt Ihr einen Sperber fangen können?", completion = "Gut gemacht! Ich versuche immer noch, das Vertrauen der Sperber zu gewinnen, aber meine Kenntnisse über sie reichen bereits aus, um diesen hier für Eure Zwecke auszubilden.", rewards = nil}
MultiLanguageQuestData['de'][10988] = {title = "Die Rabensteine", objective = "Sammelt 8 Rabensteine in Skettis und bringt sie zu Arthorn Windweise im Ewigen Hain im Schergrat.", description = "Ich habe Euren Sperber so dressiert, dass er auf einen bestimmten Pfeifton reagiert. Wenn er diesen Ton hört, wird der Vogel zu Euch fliegen und Euch zu dem nächsten Tafelfragment führen. Arthorn berichtete, dass die Tafelfragmente im Gebiet von Skettis in den südöstlichen Wäldern von Terokkar vergraben sind. Dort wird der Vogel auf Euch warten.\n\nBringt die Pfeife zurück zu Arthorn, wenn Ihr alle Steine zusammen habt. Sie wird sich darum kümmern, dass es dem Vogel gut geht und ihn in die Freiheit entlassen.\n\nRichtet Arthorn meine Grüße aus, wenn Ihr sie seht.", progress = "Habt Ihr genügend Fragmente gesammelt, damit ich das Buch des Raben rekonstruieren kann?", completion = "&lt;Arthorn nimmt Euch die Fragmente des Buchs des Raben ab und setzt sie zusammen.&gt;\n\nEin Teil der Schrift ist verwittert, aber ich sollte das meiste davon entziffern können...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10989] = {title = "Mog'dorg der Weise", objective = "Sprecht mit Mog'dorg dem Weisen auf der Spitze des Turms außerhalb des Zirkels des Blutes im Schergrat, bei dem Chort sich aufhält.", description = "Mog'dorg der Weise wartet auf Euch auf Spitze des Turms. Er mir aufgetragen, nach fähigen Helden wie Euch Ausschau zu halten. Ihr ihn in einer sehr wichtigen Sache sprechen müsst.\n\nGeht jetzt, aber erzählt niemandem davon! Es ist ein Geheimnis!", progress = nil, completion = "Endlich hat Chort mir jemanden geschickt, der in der Lage sein könnte, mir zu helfen. Ich bin bemüht, die Blutschläger vor der Auslöschung durch die Speerspießer zu bewahren. Und natürlich durch Gruul und seine Söhne, die sie unterstützen.\n\nIch vertraue fest darauf, dass Ihr unserer Geheimorganisation helfen und uns in die Freiheit führen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10990] = {title = "Die Essenz des Adlers", objective = "Besiegt den Wächter des Adlers und erlangt die Essenz des Adlers. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.\n\nWenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im ewigen Hain auf.", description = "Das Buch des Raben berichtet, dass die Anhänger des Raben die Geister seiner Rivalen eingefangen und in kleinen Schreinen aus Stein gebannt haben. Jedem Schrein wurde ein Wächter zugeteilt, um zu verhindern, dass die Feinde des Raben sie befreien.\n\nDer erste dieser Schreine ist der des Adlers und befindet sich in den Hügeln südlich des Jorunesees und westlich der Steinbrecherfeste in den Wäldern von Terokkar.\n\nDie Tafel besagt, dass der Adler tapfer gekämpft hat, jedoch von einem Schwarm von Feinden überwältigt wurde. Die Rüstung und Belastbarkeit Eurer Bärenform ist für einen solchen Kampf bestens geeignet.", progress = "<Der Sperber scheint mit Arthorns Stimme zu sprechen.>\n\nKonntet Ihr die Essenz des Adlergeistes befreien?", completion = "&lt;Arthorn scheint die Macht der Essenz über die Sinne des Sperbers wahrzunehmen.&gt;\n\nAuch tausende von Jahren der Gefangenschaft konnten die Macht des Adlergeistes nicht schmälern. Wenn die anderen Essenzen genauso stark sind wie die des Adlers, hat der Rabengott allen Grund Euch zu fürchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10991] = {title = "Die Essenz des Falken", objective = "Besiegt den Wächter des Falken und erlangt die Essenz des Falken. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.\n\nWenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im ewigen Hain auf.", description = "<Der Vogel spricht mit Arthorns Stimme.>\n\nDer zweite Geist, der von den Anhängern des Raben gebannt wurde, war der Geist des Falken.\n\nEr wurde zum Gedenken an die Priester des Raben, als sie noch über Macht verfügten, in der Nähe von Skettis eingesperrt.\n\nAm Ufer des Sees von Ere'Noru, im Nordwesten von Skettis, werdet Ihr den Schrein des Falken finden.\n\nUm den Wächter des Falken zu bezwingen, müsst Ihr die Kräfte des Falken zu Eurem Vorteil nutzen. Setzt die Schnelle und Anmut Eurer Katzengestalt ein, um den Wächter zu besiegen, bevor dieser seine volle Macht erlangt!", progress = "<Wieder einmal erklingt Arthorns Stimme aus dem Schnabel des Sperbers.>\n\nHabt Ihr die Essenz des Falken?", completion = "&lt;Der Sperber übermittelt Arthorns Worte.&gt;\n\nGut gemacht, &lt;Name&gt;. Ich hatte schon Angst, dass das Gefängnis des Falken bei der Explosion von Auchindoun zerstört wurde. Wir sind schon fast auf die Begegnung mit Anzu vorbereitet, &lt;Name&gt;. Ich würde gerne mit Euch gehen, um da zu sein, wenn dieser selbst ernannte 'Gott' zurück in seine Grube getrieben wird, aus der er gekrochen ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10992] = {title = "Die Essenz des Habichts", objective = "Besiegt den Wächter des Habichts und bringt die Essenz des Habichts zu Arthorn Windweise im Ewigen Hain.", description = "<Arthorns Stimme richtet sich an Euch.>\n\nDer letzte und mächtigste Geist, der im Buch des Raben erwähnt wird, ist der Geist des Habichts. Man sperrte ihn in einen Schrein, fern von Skettis, auf einer entlegenen Insel südöstlich von Auchindoun.\n\nIch vermute, dass mit der Beschreibung nur eine Insel gemeint sein kann, die Stätte der Gramschwingen.\n\nDie Tafel beschreibt, dass die Krallen des Vogel dem Wächter des Habichts kaum einen Kratzer zufügen können. Verzichtet daher in dieser Schlacht auf körperliche Angriffe und beschwört zum Bezwingen dieses Feindes den Zorn der Sterne. Wiederholt den Fehler des Habichts nicht!", progress = "Konntet Ihr den Wächter des Habichts besiegen und die Essenz besorgen?", completion = "Endlich haben wir alle Essenzen zusammen. Morthis Flügelraunen muss einen Weg finden, um sie in einem Amulett zu vereinen. Mit diesem Amulett könnt Ihr den Rabengott herausfordern, ihn aus dem Smaragdgrünen Traum locken und schließlich besiegen. Ich werde ihm meine Aufzeichnungen über die Geister zusenden, in der Hoffnung, dass er den Wert meiner Erkenntnisse zu schätzen weiß.\n\nEin jeder der Geister hat einen Glücksbringer gesegnet, den ich für Euch bereit hielt.", rewards = "Ihr bekommt:\n\nGlücksbringer des schnellen Fluges"}
MultiLanguageQuestData['de'][10993] = {title = "Rückkehr zur Zuflucht des Cenarius", objective = "Bringt Arthorns Päckchen zu Morthis Flügelraunen in der Zuflucht des Cenarius.", description = "Bringt die Essenzen zu Morthis Flügelraunen und berichtet ihm von unseren Erkenntnissen über den Rabengott.\n\nMorthis weiß am besten, wie man die Essenzen und Informationen einsetzen kann, um Anzu hervorzulocken. Macht Euch schnell auf den Weg zu ihm. Keiner weiß, wie lange Clintar und die Traumwächter den Angriffen des Raben noch standhalten können!\n\n<Arthorn greift nach Eurem Arm als Ihr Euch zum Gehen abwendet.>\n\nBitte, <Name>, erzählt Morthis wie sehr ich Euch geholfen habe. Ich fürchte, dass er mein Mitwirken nicht selbst erkennt!", progress = "Ich habe auf Nachricht von Arthorn gewartet. Was habt Ihr herausgefunden?", completion = "&lt;Morthis nimmt das Päckchen entgegen, entdeckt Arthorns Notizen und überfliegt sie, ohne etwas über den Absender verlauten zu lassen.&gt;\n\nEinerseits ist es eine Erleichterung endlich zu wissen, wer unser Feind ist, doch dieser Anzu ist ein Wesen von nicht zu unterschätzender Macht. Es ist wichtig, das Wesen und den Namen seines Feindes zu kennen, aber wir sind noch nicht bereit, ihm entgegen zu treten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10994] = {title = "Auf der Jagd nach dem Mondstein", objective = "Bringt einen Mondstein des Südstroms zu Morthis Flügelraunen in der Zuflucht des Cenarius.", description = "Wenn man die Essenzen mit einem seltenen Edelstein wie dem Mondstein des Südstroms verbindet, habt Ihr die Möglichkeit, sie im Kampf gegen Anzu freizulassen.\n\nDas einzige Problem dabei ist, dass die Mondsteine des Südstroms nur auf der Azsharaseite des Flusses auf den Klippen nahe der Flussquelle gefunden werden können.\n\nDen letzten Nachtelfenspähern, die nach den Steinen suchten, ist großes Unheil widerfahren. Ihr Boot liegt noch immer in der Nähe der Stelle, wo sie den Stein gesichtet haben, im Fluss. Haltet Eure Augen offen und nähert Euch der Fundstelle von Seiten Azsharas.", progress = "Ihr seht aus, als hättet Ihr einiges durchgemacht! War der Mondstein wirklich so schwer zu finden?", completion = "&lt;Morthis scheint hin- und hergerissen. Einerseits möchte er über Eure Geschichte lachen, andererseits ist ihm bewusst, wie knapp Ihr mit dem Mondstein entkommen seid. Er begnügt sich damit, den leuchtenden Stein anzustarren.&gt;\n\nIch werde mich daran machen, den Stein mit den Essenzen der Vögel zu erfüllen. Bald werdet Ihr bereit sein, den Rabengott herauszufordern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10995] = {title = "Grulloc hat zwei Schädel", objective = "Beschafft Euch Grullocs Drachenschädel.", description = "Im Osten, am Rand von Drachenend, könnt Ihr das Verfluchte Dunkel finden. An diesem Ort schmiedet Grulloc, Sohn des Gruul, seine dümmlichen Pläne.\n\nIch habe gehört, dass er trickreich um eines seiner Besitztümer gebracht wurde. Wart Ihr das etwa? Nur zu schade, dass er bei dieser Gelegenheit nicht gleich umgebracht wurde.\n\nWenn wir unsere Freiheit wiedererlangen wollen, müsst Ihr ihm seinen wertvollsten Besitz rauben: einen Drachenschädel, den er als Erinnerung an das Gemetzel seines Vaters am schwarzen Drachenschwarm bewahrt. Doch um an den Schädel heranzukommen, werdet Ihr ihn töten müssen.", progress = "Ist Grulloc schon Geschichte?", completion = "Das muss ein harter Kampf gewesen sein, &lt;Klasse&gt;. Ich bin sehr erleichtert, dass er uns nun nicht mehr auf die Pelle rücken wird.\n\nIch werde diesen Schädel zu Chort schicken, damit er auf ihn aufpasst. Ich glaube, dass wir unser Ziel mit eurer Hilfe erreichen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10996] = {title = "Maggocs Schatztruhe", objective = "Beschafft Euch Maggocs Schatztruhe.", description = "Im Messergrat über uns und im Südosten zieht Maggoc seine Kreise. Sein Vater hat ihn zum Wächter des östlichen Teils der Berge erkoren, und er benutzt sein Amt, um jegliches Wesen zu terrorisieren, das ihm in die Quere kommt.\n\nAls Sohn des Gruul muss auch er verschwinden, damit mein Klan überleben kann. Und da kommt Ihr ins Spiel.\n\nMaggoc trägt stets eine Schatztruhe bei sich. Beweist mir, dass Ihr ihn umgebracht habt, indem Ihr mir seine teure Truhe bringt. Was auch immer Ihr darin finden mögt, dürft Ihr gerne behalten.", progress = "Habt Ihr die Truhe?", completion = "Sie war leer? Was ein Pech! Aber nun habt Ihr eine Ahnung von der sinnlosen Gewalt, unter der wir leiden müssen.\n\nJetzt, da Maggoc tot ist, sind wir meinem Traum von einem Zuhause, in dem wir Oger unser Schicksal selbst schmieden können, einen entscheidenden Schritt näher gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10997] = {title = "Sogar ein Gronn hat Standards", objective = "Beschafft Euch Slaags Standarte.", description = "Kennt Ihr Euch in Shattrath aus, <Klasse>? Über der Stadt im Nordwesten gibt es einen Ort, den man die Hügelwand nennt. Man kann nur mit einem fliegenden Reittier dorthin gelangen.\n\nEiner der Söhne Gruuls, Slaag, hat sich selbst ins Exil dorthin begeben und die Herrschaft über die Oger der Gordunni, die dort leben, an sich gerissen. Auch wenn er so weit entfernt lebt, können wir ihn nicht am Leben lassen. Er könnte zurückkommen, wenn er erfährt, dass seine Brüder tot sind!\n\n<Name>, Ihr müsst dorthin reisen und seine Standarte als Beweis für seinen Tod mitbringen.", progress = "Haltet Ihr Slaags Standarte schon in Euren Händen?", completion = "Ich bin erleichtert, dass Slaag nicht mehr unter uns weilt. Nun müssen wir nicht länger in Angst vor seiner drohenden Rückkehr leben!\n\nWenn Ihr nichts dagegen habt, würde ich die Standarte gerne als Symbol der Hoffnung für alle Oger dieser Berge entgegennehmen.\n\nVielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10998] = {title = "In den übelsten Kreisen", objective = "Beschafft Euch Vim'gols üblen Zauberfolianten.", description = "Es gibt einen weiteren Gronn, der getötet werden muss: Skulloc Seelenschänder. Er weiß sich zu verstecken, doch es gibt einen Weg, ihn hervorzulocken.\n\nEr wurde von einem Ogerhexenmeister namens Vim'gol der Üble ausgebildet, an dessen Zauberfolianten Ihr gelangen müsst!\n\nMan beschwört Vim'gol, indem man innerhalb eines Feuerkreises bei seinem Zirkel steht. Findet Vim'gols Kreis in den Bergen im Nordosten, nahe der Zerschlagenen Wildnis.", progress = "Habt Ihr Vim'gol den Üblen beschworen und seinen toten Klauen den Zauberfolianten entrissen?", completion = "Ich scheue mich davor, ein Ding von solcher Abscheulichkeit auch nur anzufassen. Und doch müssen wir den Folianten lesen, wenn wir sein Wissen erkunden und Skulloc aus seinem Versteck locken möchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][10999] = {title = "Ein Schuss, ein Treffer", objective = "Bringt mir 8 Troggsteinzähne.", description = "Bringt mir 8 Troggsteinzähne.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11000] = {title = "Schänder der Seelen", objective = "Beschafft Euch Skullocs Seele.", description = "Der Zauberfoliant ist der Schlüssel zu Skullocs Untergang.\n\nUm das Ritual zu beginnen, müsst Ihr am Hügel des Seelenschänders laut aus dem Buch vorlesen. Daraufhin werden der Geist des Seelenschänders sowie die Geister seiner Opfer erscheinen. Sie werden versuchen, den Seelenschänder zu vernichten. Ihr müsst sie so lange daran hindern, bis Skulloc vollständig in diese Welt übergetreten ist.\n\nDurchquert den Dolchrachenklamm Richtung Norden. Ihr findet den Grabhügel auf der anderen Seite des Zirkels des Blutes auf der rechten Seite vor Gruuls Unterschlupf.\n\nBringt mir Skullocs Seele!", progress = "Habt Ihr Skullocs Seele schon geraubt?", completion = "Es ist also vorüber. Ihr habt uns von den Fesseln der Sklaverei durch die Söhne von Gruul befreit. Ihr habt den Klan der Blutschläger vor der sicheren Auslöschung bewahrt.\n\nEs gibt keine Worte um zu beschreiben, wie tief ALLE Oger des Schergrats, Blutschläger wie Speerspießer, in Eurer Schuld stehen, &lt;Name&gt;.\n\nSchaut dort, wie all die Oger sich versammeln um Euch Tribut zu zollen! Sollen Gruul und seine Marionette, der alte König Maulgar, sich ruhig in ihrem Unterschlupf verkriechen. Geht zu den Ogern als ihr neuer König!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11001] = {title = "Vernichtet den Rabengott", objective = "Tötet den Rabengott und kehrt dann zu Morthis Flügelraunen bei der Zuflucht des Cenarius zurück.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Wir haben bei der Vernichtung des Rabengottes keine Zeit zu verlieren. Ihr müsst den mit Essenz erfüllten Mondstein zu einem Ort von großer Macht bringen, um den Gott aus der relativen Sicherheit des Smaragdgrünen Traums zu locken.\n\nSteigt in die Sethekkhallen hinab und setzt den Mondstein in die Fänge der Rabenklaue ein. Ihr findet den Raum vor der Halle des Klauenkönigs.\n\nAnzu muss glauben, dass seine Anhänger sich versammelt haben, um ihn wieder in dieser Welt willkommen zu heißen. Zeigt keine Gnade, sobald er sich manifestiert hat!", progress = "Was gibt es neues aus den Sethekkhallen? Habt Ihr Anzu besiegt?", completion = "Schön, Euch wiederzusehen, &lt;Name&gt;. Euer Sieg über den Rabengott ist weit mehr als nur ein Test oder ein Aufnahmeritual.\n\nIhr habt Euch als würdig bewiesen, das Wissen, das die Druiden der Klaue seit unzähligen Generationen bewahren, zu erhalten.", rewards = "Ihr erlernt:\n\nSchnelle Fluggestalt\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchnelle Fluggestalt\n\nIhr bekommt außerdem:\n\nGötze der Rabengöttin"}
MultiLanguageQuestData['de'][11002] = {title = "Magtheridons Untergang", objective = "Bringt Magtheridons Kopf zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Allianz!\n\nBringt Magtheridons Kopf zu Danath Trollbann in der Ehrenfeste.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, &lt;Name&gt;. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Belagerung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nA'dals Siegel der VerteidigungBand des purpurroten FurorsLichtwächterband der NaaruRing des Aufsässigen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11003] = {title = "Magtheridons Untergang", objective = "Bringt Magtheridons Kopf zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Horde!\n\nBringt Magtheridons Kopf zu Nazgrel in Thrallmar.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, &lt;Name&gt;. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Besetzung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nA'dals Siegel der VerteidigungBand des purpurroten FurorsLichtwächterband der NaaruRing des Aufsässigen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11004] = {title = "Schattenwelt", objective = "Severin möchte, dass Ihr nach Skettis reist und 6 Einheiten Schattenstaub von den dort lebenden Arakkoa sammelt.", description = "Himmelskommandant Adaris wurde bei einem Überfall der Skettis schwer verletzt. Seitdem hat er immer und immer wieder sein Bewusstsein verloren.\n\nIch befürchte, dass er Opfer einer Fieberphantasie wurde. In seinen wenigen wachen Momenten bat er mich darum, ein Elixier aus Schattenstaub herzustellen, wie ihn die Arakkoa bei sich tragen. Er scheint zu glauben, dass er dank des Elixiers in eine Art \"Schattenwelt\" sehen könne, in welcher die wahren Anführer der Arakkoa hausen.\n\nIch schenke diesem Unsinn natürlich keinen Glauben, fürchte jedoch, dass er nicht eher ruhen wird, bis er eines dieser Elixiere in Händen hält. Werdet Ihr uns helfen?", progress = "Habt Ihr den Staub, <Name>?", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde dem Kommandanten eine kleine Menge zukommen lassen... damit er seinen Willen bekommt. Ihr könnt den Rest behalten, vielleicht findet Ihr ja eine Verwendung dafür.", rewards = "Ihr bekommt:\n\nElixier der Schatten"}
MultiLanguageQuestData['de'][11005] = {title = "Die Geheimnisse der Krallenpriester", objective = "Beschafft Euch von Severin ein Elixier der Schatten und verwendet es, um Krallenpriester Ishaal, Krallenpriester Skizzik und Krallenpriester Zellek in Skettis ausfindig zu machen und sie zu töten. Kehrt nach Abschluss Eurer Aufgabe zu Kommandant Adaris zurück.", description = "Danke, dass Ihr mir im Fieberwahn zugehört habt. Schon seit geraumer Zeit versuchen wir die Kommandokette der Skettis aufzudecken und sie zu zerschlagen. Wir wussten von der Existenz dreier Kleriker, den Krallenpriestern, jedoch haben wir niemals einen von ihnen zu Gesicht bekommen. Nun wissen wir warum.\n\nSprecht mit Severin und beschafft Euch mehr von seinem Elixier. Verwendet das Elixier, um die drei Krallenpriester, Ishaal, Skizzik und Zellek ausfindig zu machen und zu töten. Gerüchten zur Folge findet man sie im Ala'rakversteck, am östlichen Ufer des Schattenwindsees.", progress = nil, completion = "Ihr habt Euch mit Bravour geschlagen, &lt;Name&gt;. Durch den Verlust der Krallenpriester wurde dem Feind ein empfindlicher Schlag versetzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11006] = {title = "Mehr Schattenstaub", objective = "Der Kommandant scheint doch nicht aus einem Fieberwahn heraus gesprochen zu haben. Bringt mir mehr Staub und ich werde ein weiteres Elixier für Euch herstellen.", description = nil, progress = "Der Kommandant scheint doch nicht aus einem Fieberwahn heraus gesprochen zu haben. Bringt mir mehr Staub und ich werde ein weiteres Elixier für Euch herstellen.", completion = "Ihr könnt mir auch weiterhin noch Staub bringen. Ich werde so viele Elixiere für Euch herstellen, wie Ihr benötigt.\n\nAuf Befehl des Kommandanten.", rewards = "Ihr bekommt:\n\nElixier der Schatten"}
MultiLanguageQuestData['de'][11007] = {title = "Kael'thas und die tiefgrüne Sphäre", objective = "Bringt die tiefgrüne Sphäre zu A'dal in Shattrath.", description = "Die Luft um Euch herum ist von einem Summen erfüllt - einem freundlichen Summen. Die Naaru wissen von Eurem Sieg. Vielleicht sind sie der Grund für Euer Bedürfnis, die Sphäre inmitten der immer noch zuckenden Überreste von Kael'thas Sonnenwanderer aufzuheben. Welche Geheimnisse mögen darin stecken?\n\nVielleicht weiß A'dal in Shattrath mehr über diesen Gegendstand.", progress = "Ihr habt meinen Ruf vernommen? Ja...", completion = "&lt;A'dals Gedanken vermischen sich mit den Euren.&gt;\n\nDie Sphäre... Sonderbar. Wusstet Ihr, dass er überlebt hat? Ja. Hier drin, in der Sphäre selbst. Ganz sicher verstümmelt. Er gehorcht nun einer höheren Macht. Nein, nicht Illidan.\n\nHöher.\n\nKil'jaeden der Betrüger kommt...\n\nNicht hierher...\n\n&lt;A'dal führt Euren Geist an einen anderen Ort.&gt;\n\nAzeroth. Unbekannt.\n\nRuht Euch aus. Eure Brüder und Schwestern werden die Festung der Stürme wieder übernehmen.\n\n&lt;A'dal summt eine Kriegshymne.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGriff des VerfinsterersSonnenkönigs TalismanTelonicus' ChaosanhängerFürst Blutdursts Anrecht\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11008] = {title = "Feuer über Skettis", objective = "Haltet nach monströsen Kalirieiern oben in den Siedlungen von Skettis Ausschau und benutzt die Sprengladungen der Himmelswache, um sie in die Luft zu sprengen. Kehrt danach zu Himmelsoffizier Doryn zurück.", description = "Glaubt Ihr, dass Ihr das Zeug dazu habt, ein Teil der Himmelswache zu sein? Wir werden überprüfen müssen, wie gut Ihr in der Luft zurechtkommt.\n\nDie Arakkoa züchten eine gigantische Menge von ihren Kampfvögeln, die sie auf unsere Späher hetzen! Ich möchte, dass Ihr diese Sprengladungen nehmt und ihre Brutstätten über den Siedlungen der Arakkoa zerstört. Macht aber einen Bogen um die monströsen Kaliri, welche die Brutstätten bewachen. Sie werden Euch vom Reittier holen, bevor Ihr wisst, wie Euch geschieht!", progress = "Habt Ihr Euren Auftrag schon erledigt?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Das wird diesen Vogelwesen zeigen, wer die wahren Herren der Lüfte sind!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11009] = {title = "Ogerhimmel", objective = "Mog'dorg der Weise hat Euch gebeten, mit Chu'a'lor in Ogri'la im Schergrat zu sprechen.", description = "Jetzt, da Ihr uns aus der Knechtschaft befreit habt, können wir mit der Wiedervereinigung der Klans beginnen. Es wird einige Zeit dauern; lange geschürter Zorn kühlt nur langsam wieder ab.\n\nEs ist umso eiliger, dass Ihr nach Ogri'la, hoch oben im Westen, reist. Verteidigt es und uns so gut, wie Ihr könnt. Schützt uns vor den Mächten, wie es einst die Gronn taten: Astrale, Dämonen und noch viel schlimmer, der schwarze Drachenschwarm, erwarten Euch.\n\nSolltet Ihr den Himmel der Oger gefunden haben, ersucht Chu'a'lor um Rat für die weitere Vorgehensweise.", progress = nil, completion = "Mog'dorg hat eine Nachricht voraus geschickt, um mich über Euer Kommen zu informieren. Ich bin froh, dass Ihr hier seid.\n\nNach dem Fall der Söhne des Gruul, ist es nur noch eine Frage der Zeit - es dürfte nicht sehr lange dauern - bevor die unterschiedlichen Bewohner dieser Bergterrasse und die des Nordens beginnen, Jagd auf unsere Ogerbrüder dort unten zu machen.\n\nDies gilt es zu verhindern und ich vertraue auf Eure Unterstützung, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11010] = {title = "Bomberangriff", objective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", description = "Ihr habt ein fliegendes Reittier... ja und! Glaubt Ihr denn, dass Ihr das Zeug dazu habt, es gekonnt einzusetzen?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und obendrein bedrohen sie das friedliche Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n&lt;Himmelsoffizier Vanderlip grinst.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBomberangriff: Bei Questabschluss\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11011] = {title = "Ewige Wachsamkeit", objective = "Sprecht mit Morthis Flügelraunen, um einen mit Essenz erfüllten Mondstein zu erhalten.", description = "Euer Sieg über Anzu, den Rabengott, ist eine wahrhaft heldenhafte Leistung. Ich fürchte allerdings, dass er nicht aufgeben und weiterhin versuchen wird, in die Scherbenwelt zurückzukehren.\n\nSolange seine Gefolgsleute am Leben sind, wird er sich immer wieder erheben. Daher solltet Ihr den mit Essenz erfüllten Mondstein stets bei Euch haben, falls Anzu sich erneut regt.", progress = nil, completion = "Behaltet den Mondstein bei Euch, &lt;Name&gt;. Wenn Ihr glaubt, dass Anzu seine Kräfte sammelt, um in diese Welt zurückzukehren, verwendet den Stein um ihn zu besiegen.", rewards = "Ihr bekommt:\n\nMit Essenz erfüllter Mondstein"}
MultiLanguageQuestData['de'][11012] = {title = "Der Blutschwur der Netherschwingen", objective = "Unser Land ist verloren. Man entführt unsere Kinder in der Nacht, versklavt sie - oder schlimmer...\n\n<Mordenais Stimme wird angespannt.>\n\nEs ist an der Zeit, mein Freund. Zeit, uns wieder das zu nehmen, was einst unser war! Ihr habt Euch als tapferer Kämpfer und verständnisvolle Seele erwiesen.\n\nWerdet Ihr schwören, dem Drachenschwarm der Netherschwingen beim Kampf um unser Land und den Wiederaufbau unserer Heimstätten zu helfen? Werdet Ihr schwören, über den Schwarm zu wachen, damit unser Fleisch und Blut aufs Neue zum Leben erwachen kann? Schwört und lasst uns im Namen unserer Heimat und unserer Familien kämpfen!", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11013] = {title = "Im Dienste der Illidari", objective = "Reist zur Netherschwingenscherbe und überreicht Oberanführer Mor'ghor beim Basislager des Drachenmals das Empfehlungsschreiben der Illidari.", description = "Die Netherschwingenscherbe... Was einst eine Feste der Zuflucht für die Netherschwingen war, ist nun das Zuhause des Drachenmalklans. Die Orcs haben vielleicht die Kontrolle über unser Land gewonnen, unsere Magie ist dort jedoch noch stark. Stark genug, um Eure wahre Identität zu verschleiern und um Euch in die Ränge des Drachenmalklans einzuschleusen.\n\nIch habe dieses Schreiben für Euch aufgesetzt, überreicht es ihrem Anführer, Oberanführer Mor'ghor. Fliegt den Fängen unseres Feindes entgegen, reist zum Basislager des Drachenmals und beginnt Euer neues Leben als Höllenorc Illidan Sturmgrimms.", progress = "<Mor'ghor grunzt.>\n\nIhr seid spät...", completion = "&lt;Mor'ghor überfliegt das Schreiben und lacht.&gt;\n\nEin Todesritter? Ihr könnt einem Todesritter nicht mal das Wasser reichen, Wurm.\n\n&lt;Mor'ghor mustert Euch scharf.&gt;\n\nNun gut... Ihr könntet es vielleicht noch zum Peon schaffen. Im schlimmsten Fall werfe ich Euch in die Grube und lasse Euch dort verrotten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11014] = {title = "In der Höhle des Löwen", objective = "Sprecht mit Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals.", description = "<Mor'ghor zerknüllt das Empfehlungsschreiben und wirft es beiseite.>\n\nAlso Grunzer, eins nach dem anderen. Wenn Ihr meiner teuren Armee des Drachenmals beitreten wollt, dann müsst Ihr arbeiten. Jeder arbeitet hier auf der Scherbe. Sucht Euch Arbeit und seht zu, dass Ihr Euch nicht zu dämlich anstellt. Eventuell werde ich Euch später mit interessanteren Dingen beauftragen.\n\nSprecht mit Zuchtmeister Varkule Drachenodem, er steht in der Mitte des Lagers. Nach Einschätzung Eurer Fertigkeiten, wird er Euch eine entsprechende Arbeit zuteilen.\n\nUnd jetzt verschwindet!", progress = nil, completion = "Varkule findet schon was für Euch, Grunzer. Euch steht eine Aufgabe zu, die Euren Fertigkeiten am besten gerecht wird und unserer Kristallförderung zu Gute kommt. Ihr müsst Euren Arbeitsauftrag einmal am Tag ausfüllen.\n\nJa, es gibt da einen Haufen Drecksarbeit zu erledigen, aber auch die Ahnen haben mal als Peon begonnen.", rewards = nil}
MultiLanguageQuestData['de'][11015] = {title = "Kristalle der Netherschwingen", objective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 30 Kristalle der Netherschwingen bringt.", description = "Ihr taugt zu nichts, was? In Ordnung, auch Vollidioten wie Ihr können uns hier noch zur Hand gehen. Sucht auf der Scherbe einfach nach Kreaturen und tötet sie. Manchmal befinden sich auf ihren Körpern Kristalle der Netherschwingen. Sammelt und bringt sie mir, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", progress = "Kristalle der Netherschwingen werden für vielerlei Dinge verwendet. Hauptsächlich zur Herstellung von Waffen und Rüstungen...", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11016] = {title = "Balg eines Netherminenschinders", objective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 35 Bälge eines Netherminenschinders bringt.", description = "Ein Kürschner, ja? Nun, Ihr werdet hier mehr als genug Häutbares finden! Sucht in der Nähe der Kristallformationen nach Schindern. Tötet sie und nehmt ihre Bälge an Euch. Vielleicht sind die ein oder anderen sogar etwas wert, bringt mir genau diese.", progress = "Wir verwenden die Bälge von Schindern zum Ausfüttern von Rüstungen und die Herstellung von Planen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11017] = {title = "Netherstaubpollen", objective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Netherstaubpollen bringt.", description = "Ein Blümchenpflücker?! Köstlich... bedauerlicherweise benötigen unsere Magier und Schamanen Eure Dienste. Die Netherstaubbüsche, die hier auf der Scherbe wachsen, besitzen spezielle Pollen, die bei magischen Angelegenheiten wohl recht nützlich sind. Bringt mir das Zeug, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", progress = "Wie ich schon sagte, Netherstaubpollen werden von unseren Zauberern verwendet.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11018] = {title = "Netheriterz", objective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Einheiten Netheriterz bringt.", description = "Ein Minenarbeiter!\n\n<Varkule nickt Euch zu.>\n\nEin Orc ganz nach meinem Geschmack! So hat Varkule auch einmal angefangen - mit Bergbau! Es gibt doch nichts Besseres als runter in die Mine zu gehen und richtig schmutzig zu werden, nicht wahr?\n\nGeht jetzt und sucht nach Netheritablagerungen. Holt alles, was wertvoll ist, heraus und bringt mir das Erz.", progress = "Gug dort drüben verwendet das Erz zum Verstärken unserer Waffen und Rüstungen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11019] = {title = "Freund unter Feinden", objective = "Ihr habt doch nicht etwa geglaubt, dass wir Euch den Armeen der Höllenorcs ganz alleine überlassen würden, oder?\n\n<Yarzills Augen flackern in einem durchscheinenden Blau.>\n\nGenau, wir sind hier an Eurer Seite, <Name>. Bei jedem Dienst, den Ihr den Höllenorcs bei Eurem Versuch, die Weiten der Netherschwingen zurückzuerobern, erweist, werden wir dafür sorgen, dass sie einen ausreichenden Rückschlag erleiden.\n\nIhr müsst Euch sehr unauffällig verhalten, um keinerlei Aufmerksamkeit während Euren Sabotageeinsätzen auf Euch zu ziehen.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11020] = {title = "Ein langsamer Tod", objective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr Yarzills Hammel zusammen mit den Teufelsdrüsen verwendet, um 12 Peonlager des Drachenmals zu vergiften.", description = "Die Anhänger des Drachenmals haben bei fast allen Kristallformationen hier oben Peons stationiert. Ein bloßes Töten, würde Euch bei weitem zu viel unerwünschte Aufmerksamkeit einbringen. Wir können ihre Reihen aber auch auf eine andere Art und Weise lichten, ohne bei dem misstrauischen Mor'ghor Verdacht zu erwecken.\n\nReist in die Wildnis des Schattenmondtals und tötet die besudelten Tiere. Nehmt ihre verderbten Teufelsdrüsen an Euch. Wendet die Teufelsdrüsen in der Nähe der Peons auf den Hammel an, den ich Euch geben werde. Ein Biss und sie sind tot!", progress = "Es ist eine schmutzige Arbeit, <Name>.", completion = "&lt;Yarzill flüstert ganz leise.&gt;\n\nAusgezeichnete Arbeit, &lt;Name&gt;. Verhaltet Euch fürs Erste ruhig. Kommt morgen wieder zu mir, dann können wir das Ganze noch einmal machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11021] = {title = "Ishaals Almanach", objective = "Bringt Ishaals Almanach zu Himmelskommandant Adaris im Norden von Skettis.", description = "Dieser geheimnisvolle Foliant lag bei Krallenpriester Ishaals Leichnam. Die darin abgebildeten arkanen Symbole und Schaubilder von Himmelskörpern sind Euch völlig fremd.\n\nSämtliche Aufzeichnungen wurden in einer für Euch unverständlichen Sprache verfasst; vermutlich eine uralte Form der Arakkoaschriftsprache. Vielleicht solltet Ihr damit zu Himmelskommandant Adaris gehen.", progress = "Ihr wollt mir etwas zeigen?", completion = "Was habt Ihr mir da gebracht? Die Sprache dieses Folianten ist mir fremd, &lt;Name&gt;... mein Blutverlust... muss meinen Geist verschleiert haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11022] = {title = "Sprecht mit Mog'dorg", objective = "Sprecht mit Mog'dorg dem Weisen. Er steht oben auf dem Turm auf der Ostseite des Zirkels des Blutes im Schergrat.", description = "<König/Königin> <Name>! Bevor Ihr uns verlasst und nach Ogri'la geht, sprecht mit Mog'dorg dem Weisen!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11023] = {title = "Und wieder ein Bombenangriff!", objective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", description = "Diese Flakgeschütze bereiten uns noch immer Sorgen, <Name>.\n\nVersteht mich bitte nicht falsch - Ihr habt das letzte Mal hervorragende Arbeit geleistet, aber das ändert leider nichts an der Tatsache, dass diese verdammten Dämonen ihre Munitionsvorräte schneller wieder aufzufüllen vermögen, als wir sie vernichten können. Unsere Männer da hineinzuschleusen ist momentan also ein mehr als riskantes Unterfangen, ganz zu schweigen von dem Risiko, das die Dämonen für Ogri'la darstellen.\n\nWas sagt Ihr? Wollt Ihr es noch einmal versuchen?", progress = "Wie steht es mit dem Bombenangriff?", completion = "Hervorragend, &lt;Name&gt;! Ich würde Euch ja sofort wieder in die Luft schicken und ein paar Bomben werfen lassen, aber unsere Richtlinien hier schreiben vor, dass unsere Piloten ausreichend Ruhe und Erholung erhalten müssen. Es tut mir leid, ich mache die Regeln nicht, aber lasst Euch versichern, dass ich sie durchsetzen werde!\n\nSehen wir uns morgen wieder, Sportskanone?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBomberangriff: Bei Questabschluss\n\nIhr bekommt:\n\nApexissplitter"}
MultiLanguageQuestData['de'][11024] = {title = "Ein Verbündeter im Unteren Viertel", objective = "Bringt Ishaals Almanach zu Rilak dem Erlösten im Unteren Viertel in Shattrath.", description = "Im Unteren Viertel gibt es einen Arakkoa namens Rilak... ihm kann Vertrauen geschenkt werden. Nehmt das Buch... und bringt es zu ihm.\n\n<Adaris gibt Euch das Buch wieder und verliert daraufhin das Bewusstsein.>", progress = "Ihr seid mit dem Geruch Skettis' behaftet! Was hat das zu bedeuten?", completion = "Das kann nicht sein... dies war einst Eigentum eines Krallenpriesters. Wie ist es nur in Eure Hände gelangt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11025] = {title = "Die Kristalle", objective = "Chu'a'lor möchte, dass Ihr 5 Apexissplitter einsammelt. Bringt sie zu ihm in Ogri'la hoch oben im Schergrat.", description = "Beim richtigen Umgang mit den Kristallen der Berge, weisen diese seltsame Kräfte auf, wie zum Beispiel die Klarheit des Geistes, die wir hier in Ogri'la entdeckt haben.\n\nAlle Kreaturen oben auf den Bergen begehren danach und benutzen die Splitter, um ihre eigenen Ziele voranzutreiben. Der Wert dieser Kristalle hat sogar eine regelrechte Wirtschaft aufkommen lassen.\n\nUm uns helfen zu können, müsst Ihr zunächst etwas über die Apexissplitter lernen. Bringt mir ein paar Exemplare. Nicht nur die Kreaturen hier besitzen welche, gelegentlich findet man sie auch bei den großen Kristallen, dort, wo die Hetzer graben.", progress = "Wenn Ihr mehr über die Splitter und Kristalle lernt, werdet Ihr uns und unsere Ogerbrüder dort unten besser beschützen können.\n\nDie Splitter selbst wurden nach einer uralten und mittlerweile ausgelöschten Arakkoazivilisation benannt, die einst auf den Spitzen dieser Berge lebte.\n\nNun, habt Ihr die Splitter bei Euch?", completion = "&lt;Chu'a'lors linker Kopf beginnt zu sprechen.&gt;\n\nDiese sind genau richtig.\n\nDenkt daran, &lt;Name&gt;, der Wert dieser Splitter liegt nicht in ihrem Verkaufspreis. Es ist nicht einmal das, was sie für Euch tun können, sobald sie ordnungsgemäß zusammengeschmiedet wurden... auch wenn sich darüber streiten lässt.\n\n\n\nDer wahre Wert liegt in dem Unterfangen, das es auf sich zu nehmen gilt, um in den Besitz dieser Splitter zu gelangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11026] = {title = "Bannt die Dämonen", objective = "Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen.", description = "Ihr seid genau zur rechten Zeit hier eingetroffen! Wir brauchen dringend Unterstützung. Als Gegenleistung werden wir Euch etwas sehr seltenes und von beiderseitigem Wert für Euch und für uns überlassen.\n\nWir sind keine gewalttätigen Oger mehr, aber die nahegelegenen Dämonen drohen uns und die Himmelswache zu überrennen. Das Problem mit Dämonen ist, hat man sie erst einmal getötet, tauchen sie wenig später in einem neuen Körper wieder auf!\n\nWenn Ihr allerdings mit diesem Kristall ein Bannportal beschwört und ein Dämon in dessen Nähe stirbt, wird seine Essenz in das Portal gezogen und er in seine Heimatebene verbannt!", progress = "Wir nehmen an, Ihr habt den Bannkristall dazu benutzt, eine ganze Reihe dieser Dinger der Brennenden Legion zum Packen zu bewegen?", completion = "Das wird ihnen eine Lehre gewesen sein! Kommen wir nun zu Eurer Belohnung.\n\nDie Dämonen des Konstruktionslagers: Wut im Norden haben an ihrer südlichen Grenze einen besonderen Transporter errichtet. Sie verwenden dieses experimentelle Transporttor, um den Einfluss des Lagers weiter auszudehnen. Wir brauchen Euch wohl nicht erst erklären, was passieren wird, wenn sie sich zu weit ausbreiten.\n\nAlso, wenn wir Ihr wären, würden wir diese Rune der Dunkelheit zu Gahk schaffen und ihn Fragen, wie Ihr helfen könnt. Geht es langsam mit ihm an, &lt;Name&gt;, er ist ebenfalls neu hier.", rewards = "Ihr bekommt:\n\nRune der Dunkelheit"}
MultiLanguageQuestData['de'][11027] = {title = "Habt Ihr die Rune der Dunkelheit?", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKristallgeschmiedete Rune der Dunkelheit"}
MultiLanguageQuestData['de'][11028] = {title = "Countdown des Schicksals", objective = "Kehrt zu Himmelskommandant Adaris ins Schattenwindlager in den Wäldern von Terokkar zurück und erzählt ihm die Neuigkeiten über Terokks Rückkehr.", description = "Dieser Almanach prophezeit die Rückkehr von Terokk, dem mächtigsten und furchtbarsten Skettiskönig der Arakkoageschichte.\n\nIch habe dies immer für eine Legende gehalten, <Name>. Die Wiederkehr der Krallenpriester und Eure Entdeckung dieses Folianten belehren mich jedoch eines Besseren.\n\nMit jedem Tag wächst die Macht Terokks und seine Ankunft naht. Die einzige Chance, die Ihr habt, ist ihn vorzeitig in unsere Welt zu holen. Geht zurück nach Skettis und sprecht mit Adaris über das Ganze. Lasst uns hoffen, dass er die Weisheit besitzt, um die richtige Entscheidung zu treffen.", progress = nil, completion = "Die Arakkoa möchten Terokk zurück aus dem Jenseits der Zeit holen und Rilak... möchte einen Weg finden, um diesen Vorgang zu beschleunigen? Hat er denn seinen Verstand verloren?\n\n&lt;Adaris legt sich geschwächt nieder.&gt;\n\nIhr habt Eure Pflicht erfüllt, &lt;Name&gt;. Es ist an der Zeit, dass Ihr die Sache meinen Männern überlasst. Das ist jetzt eine rein militärische Angelegenheit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11029] = {title = "Eine schäbige Verkleidung", objective = "Verwendet die schäbige Arakkoaverkleidung, um den Stammbaum der Feinde von Sahaak zu beschaffen. Kehrt anschließend zu Hazzik zurück.", description = "Öffnet das Päckchen, <Name>. Es ist eine Verkleidung. Sie sieht nicht sehr überzeugend aus, oder?\n\nIch fertige sie für astrale Schmuggler an, auf der Suche nach seltenen Büchern. Es gibt einen Schreiber der Arakkoa, der auf der zentral gelegenen Insel in Skettis lebt, die als Terokks Ruh bekannt ist; sein Name ist Sahakk. Er ist alt und fast blind.\n\nVerwendet die Verkleidung, um mit ihm zu sprechen und besorgt Euch das Buch, den Stammbaum der Feinde. Seid auf der Hut, <Name>. Andere Arakkoa lassen sich von der Verkleidung nicht täuschen.", progress = "Das Buch, <Name>. Habt Ihr es?", completion = "Ausgezeichnet! Das Buch beinhaltet eine Aufstellung der Nachfahren von Terokks alten Feinden. Es wurde vorhergesagt, dass ihr Tod Terokks Rückkehr ankündigen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11030] = {title = "Unser Junge möchte der Himmelswache beitreten", objective = "Beschafft ein instabiles Fläschchen der Bestie.", description = "Wir haben ein kleines Problem, <Klasse>: Wir haben eine Menge Söhne. Seit die Himmelswache bei uns in der Nähe stationiert wurde, wünschen sie sich nichts sehnlicher, als der Wache beizutreten.\n\nAls stolzer Vater möchten wir natürlich, dass sie zum Zeitpunkt ihrer Bewerbung alle Vorteile haben, die sie kriegen können. Würdet Ihr also für uns die Teufelskristallschmiede in einem der beiden Lager im Norden oder im Süden aufsuchen und ein magisches Fläschchen für unsere Söhne beschaffen? Ihr könnt ihren grünen Rauch kaum verfehlen.\n\nWir denken, die Herstellung eines Fläschchens erfordert zehn Apexissplitter. Gerne würden wir Euch Splitter mitgeben, aber leider haben wir keine mehr zur Hand.", progress = "Habt Ihr das magische Fläschchen schon bekommen? Es würde Torkus Junior alles bedeuten.", completion = "Ihr seid ein Lebensretter, &lt;Name&gt;!\n\nUnsere Jungs werden von dieser Neuigkeit begeistert sein!\n\nOk, eines geschafft und eines fehlt noch. Wir haben Euch doch bestimmt von dem anderen Fläschchen erzählt, das sie benötigen, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11031] = {title = "Nicht mehr Erzmagier", objective = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", description = nil, progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nViolettes Siegel des großen BewahrersViolettes Siegel des großen BeschützersViolettes Siegel des meisterlichen Auftragsmörders"}
MultiLanguageQuestData['de'][11032] = {title = "Nicht mehr Beschützer", objective = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", description = nil, progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nViolettes Siegel des großen BewahrersViolettes Siegel des ErzmagiersViolettes Siegel des meisterlichen Auftragsmörders"}
MultiLanguageQuestData['de'][11033] = {title = "Nicht mehr Assassine", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nViolettes Siegel des großen BewahrersViolettes Siegel des großen BeschützersViolettes Siegel des Erzmagiers"}
MultiLanguageQuestData['de'][11034] = {title = "Nicht mehr Bewahrer", objective = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", description = nil, progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nViolettes Siegel des meisterlichen AuftragsmördersViolettes Siegel des großen BeschützersViolettes Siegel des Erzmagiers"}
MultiLanguageQuestData['de'][11035] = {title = "Ein Schatten am Horizont", objective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 10 Relikte der Netherschwingen sicherstellt.", description = "Am nordöstlichen Ende dieser Insel gibt es ein Dock, das dem Verpacken und dem Transport der Kristalle und Relikte der Netherschwingen dient. Transporter des Drachenmals transportieren die Güter vom Dock zu der Festung des Drachenmals, während die Ahnen des Drachenmals den Boden vor möglichen Angreifern schützen.\n\nUm dem Drachenmal einen Schlag zu versetzen, bleibt nur ein Angriffspunkt offen: der Himmelspfad des Drachenmals.\n\nFliegt zu den zerschlagenen Inseln des Himmelspfads des Drachenmals und lauert den Transportern auf, die diesen Weg einschlagen. Bringt unsere gestohlenen Relikte wieder in Sicherheit!", progress = "Tote Orcs singen nicht, <Name>. Stellt sicher, dass keiner der Transporter des Drachenmals entkommt.", completion = "&lt;Yarzill flüstert.&gt;\n\nIhr habt den Netherschwingen einen großen Dienst erwiesen, &lt;Name&gt;. Der Fall des Drachenmals rückt in greifbare Nähe. Von innen heraus breitet sich nun eine Krankheit aus - eine unheilbare Krankheit...\n\nSolltet Ihr wieder an Arbeit bei dem Himmelspfads des Drachenmals interessiert sein, so kommt morgen wieder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11036] = {title = "Außerirdische Früchte!", objective = "Bringt die konservierten Früchte zu Raketenchef Doppeldecker in Area 52 im Nethersturm.", description = "Ich muss ganz ehrlich zugeben, dass ich nicht die leiseste Ahnung habe, wozu diese Lieferung dienen soll, aber Raketenchef Doppeldeckers Anweisungen waren sehr genau - nur die besten Früchte, konserviert, um eine lange Reise zu überstehen und gut versiegelt sollen sie sein.\n\nEs gab noch weitere Anweisungen, irgendetwas über Schwerelosigkeit hier und Niedrigdruck da. Ich gebe nicht mal vor, alles zu verstehen, aber der Preis stimmt, also kriegt er seine Supernahrung. Bringt diese Kiste zu ihm in der Area 52. Nachdem Ihr den Nethersturm betreten habt, folgt der Straße, bis Ihr die Stadt seht.", progress = "Ist das die Lieferung vom alten Orok?", completion = "&lt;Der Raketenchef überprüft den Inhalt der Kiste.&gt;\n\nSieht soweit gut aus. Wieder etwas, dass ich von der Liste streichen kann. Nun müssen wir noch nur dafür sorgen, dass die Rakete vom Boden abhebt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11037] = {title = "Eine seltsame Vision", objective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", description = "<Name>, ich hatte eine höchst ungewöhnliche Vision, auf die ich mir keinen Reim machen kann. Ich sah einen Pfeil, einen gigantischen Pfeil, der sich auf einem Feuerschweif gen Himmel erhob. Für einen geübten Magier wäre es ein Leichtes etwas derartiges zu erschaffen, doch ein Gefühl sagt mir, dass dieses Objekt nicht das Produkt von Magie ist.\n\nEs wird anders sein, als alles, was die Völker von Azeroth je erschaffen haben. Ihr müsst diejenigen finden, die an diesem Wunderwerk arbeiten, <Name>. Gewährt ihnen Eure Hilfe, denn ohne sie werden sie versagen.", progress = nil, completion = "&lt;Der Raketenchef hört Euch aufmerksam zu, als Ihr ihm von der Vision des Sehers erzählt.&gt;\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch die Rakete hinter mir an! Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11038] = {title = "Unterstützung für Exarch Orelis", objective = "Sprecht mit Exarch Orelis in Area 52.", description = "Vor nicht allzu langer Zeit entsandte Hohepriesterin Ishanah eine kleine Gruppe von Anachoreten unter dem Kommando von Exarch Orelis in den Nethersturm. Sie hatten den Auftrag, die Aktivitäten von Kael'thas und seinen Gefolgsleuten zu untersuchen, doch bisher haben wir keinerlei Nachricht von ihnen erhalten.\n\nIch habe die Befürchtung, dass unsere Präsenz im Zielgebiet nicht stark genug ist, um diesen Auftrag erfolgreich abzuschließen. Sicherlich würde der Exarch von Eurem Wissen und Eurer Erfahrung profitieren. Wäret Ihr bereit zur Area 52 zu reisen und ihn zu unterstützen?", progress = nil, completion = "So, Ihr seid also hierher gekommen, um unsere Untersuchungen über Kael'thas Pläne zu unterstützen? Eure Hilfe ist uns sehr willkommen. Der Nethersturm ist voll von Agenten der Blutelfen, die nichts unversucht lassen, um das Land ins Chaos zu stürzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11039] = {title = "Meldung bei Spionagemeister Thalodien", objective = "Meldet Euch bei Spionagemeister Thalodien in Area 52.", description = "Vor einiger Zeit schickte Voren'thal eine kleine Einheit in den Nethersturm, um Kael'thas' Aktivitäten genauer zu beobachten. Unser Anführer hat vollstes Vertrauen in die Fähigkeiten von Spionagemeister Thalodien und seinen Männern und hat sich daher entschlossen, seiner Bitte um Verstärkung nachzukommen.\n\nThalodiens Bericht fiel recht knapp aus, doch geht daraus eindeutig hervor, dass er eine Entdeckung von größter Wichtigkeit gemacht hat. Erstattet ihm in der Area 52 Meldung und unterstützt ihn soweit es Euch möglich ist, <Name>.", progress = nil, completion = "&lt;Einen Augenblick lang huscht ein Ausdruck der Enttäuschung über das Gesicht des Spionagemeisters.&gt;\n\nIch hatte wenigstens auf eine ganze Einsatzgruppe gehofft, aber wenn Voren'thal es für sinnvoll hielt, Euch alleine zu entsenden, werde ich meine Pläne entsprechend anpassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11040] = {title = "Ersatzteile für den Raketenchef", objective = "Bringt Bossis Ersatzteile zu Raketenchef Doppeldecker nach Area 52 im Nethersturm.", description = "Wie oft ich mit einem Goblin zusammengearbeitet habe, kann ich an einer Hand abzählen. Normalerweise konkurrieren wir mit ihnen, aber als ich Raketenchef Doppeldeckers Anfrage erhielt, konnte ich sie nicht einfach so ablehnen.\n\nDiese Kiste ist voller Einzelteile für die ich hier keine Verwendung habe, aber die für das Projekt des Raketenchefs sehr nützlich sein könnten. Wäret Ihr so freundlich und würdet Sie bei ihm abgeben, wenn Ihr an der Area 52 vorbeikommt?\n\nWer weiß, vielleicht schaffen es einige gnomische Teile, seine Erfindung vor der Zerstörung zu bewahren!", progress = "Diese Kiste sieht aus, als stamme sie von einem Goblinmeisteringenieur. Hat Bossi Euch geschickt?", completion = "Ich weiß nicht einmal, was einige dieser Teile bewirken! Einige von ihnen werden mir sicherlich sehr nutzen. Ich hätte niemals gedacht, dass ich mal lernen müsste, wie ein Gnom zu denken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11041] = {title = "Eine unerledigte Aufgabe...", objective = "Tötet 10 Felslandschinder und Barash die Höhlenmutter. Kehrt nach erfolgreicher Erledigung zu Oberanführer Mor'ghor beim Basislager des Drachenmals zurück.", description = "Im Namen unseres großen Meisters... zum Ruhme Illidans!\n\nIm Auftrag von Oberanführer Mor'ghor soll das große Plateau der Netherschwingenscherbe gesichert werden. Da fast alle Drachen der Netherschwingen eingefangen oder vom Land vertrieben wurden, nehmen die Felsklauen langsam überhand und bedrohen unsere Kristallernte.\n\nVernichtet sie alle, ihre Höhlenmutter und ihren Gefährten, Arvoar.\n\nMor'ghor befiehlt es so!\n\n<Es scheint ganz so, als hätte der Orc beim Absichern des Plateaus versagt. Es ist an der Zeit, dass Ihr Euch bei Mor'ghor als würdig erweist!>", progress = "Wer wagt es, an Mor'ghor heranzutreten? Ich hoffe für Euch, dass es von Wichtigkeit ist.", completion = "Ihr habt also bei den Überresten einer meiner Aufseher eine Anordnung gefunden und die Sache selbst in die Hand genommen? Ihr habt es geschafft, Mor'ghor zu beeindrucken. Gut gemacht...", rewards = "Handschuhe des DrachenzähmersAuferstehungsstiefelAugurengurt des DrachenmalsMantelung der HimmelsteilerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11042] = {title = "Eine verblüffende Vision", objective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", description = "Mich verfolgt eine seltsame Vision, <Name>. Ich sehe eine riesige Rauchwolke, die gen Himmel steigt, und ein gigantisches Feuer, welches sich noch weit höher erhebt. Es ist weder ein natürliches Phänomen, noch ein Werkzeug des Bösen; so viel ist sicher.\n\nIch habe keine Vorstellung davon, wie es aussieht, ich weiß nur, dass es das Werk Vieler ist. Dennoch, ohne weitere helfende Hände, wird diese Vision wohl nie Realität werden.\n\nReist in den Nethersturm, <Klasse>. Findet die Erschaffer dieser Erscheinung und bietet ihnen Eure Hilfe an.", progress = nil, completion = "&lt;Der Raketenchef hört Euren Ausführungen über die Vision des Sehers aufmerksam zu.&gt;\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch das Ungetüm hinter mir an. Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11043] = {title = "Ein besserer Greif", objective = "Sprecht mit Brunn Flammenbart in der Wildhammerfeste im Schattenmondtal.", description = "Wie ich hörte, unterhalten die Wildhammerzwerge in ihrer Festung im südlichen Schattenmondtal einen Greifenhorst. Könntet Ihr, wenn Ihr Euch dorthin begebt, in meinem Namen mit ihnen sprechen? Ich habe da einige Ideen, wie man ihre Greifen noch verbessern könnte!\n\nWarum sie nur mit einer Rüstung ausstatten, wenn man sie noch mit einem Höhenmesser, einem Rückspiegel und einer Rakete bestücken kann? Stellt Euch nur vor, welche Geschwindigkeiten ein Greif mit einer, auf seinem Rücken festgeschnallten, Rakete erreichen würde! Ich nenne meine Erfindung den Turbogreifen 8000!", progress = nil, completion = "&lt;Brunns Gesicht errötet, bis es nicht länger von seinem Bart zu unterscheiden ist.&gt;\n\nEr möchte WAS mit meinen Greifen anstellen?\n\nWenn diese kleine Ratte auch nur versucht, irgendetwas anderes als einen Sattel auf meinen Greifen zu befestigen, reise ich persönlich zum Schergrat und stopfe ihm mit seinen Raketen das Maul!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11044] = {title = "Visionen voller Zerstörung", objective = "Sprecht mit Schwadronskommandant Nuainn in der Wildhammerfeste.", description = "Eine Vision voller Zerstörung reißt mich oft aus dem Schlaf. - Ein Regen aus grünem Feuer, der auf die Erde herabregnet und die tapferen Verteidiger einer mächtigen Festung verbrennt. Seit Wochen schon verfolgt mich dieser Traum, doch erst kürzlich ist mir seine Bedeutung offenbart worden.\n\nWeit im Osten, im Schattenmondtal, erwehren sich die Wildhammerzwerge den ständigen Angriffen der Brennenden Legion und zahlloser anderer Feinde. Sie kämpfen tapfer, doch wenn sie nicht bald Entsatz erhalten, werden ihre Feinde triumphieren. <Name>, Ihr müsst ihnen zur Seite stehen. Helft ihnen in ihrem verzweifelten Kampf.", progress = nil, completion = "Eine Vision sagt Ihr? Es interessiert mich nicht, ob er es in einer Vision gesehen, in einem Brief gelesen oder es aus dem Mund eines Grubenlords vernommen hat, aber er hat den Nagel auf den Kopf getroffen! Was führt Euch hierher, Freund? Oh, und wir sind für jede Unterstützung dankbar!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11045] = {title = "Zorus der Richter", objective = "Sprecht mit Zorus dem Richter in der Wildhammerfeste.", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Zorus der Richter versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihm jede Hilfe willkommen ist.\n\nSolltet Ihr ins Tal reisen, haltet Ausschau nach Zorus bei der Wildhammerfeste, sie liegt zentral im Süden des Tals.", progress = nil, completion = "Fantei spricht die Wahrheit, Eure Hilfe kommt mir sehr gelegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11046] = {title = "Chefapothekerin Hildagard", objective = "Sprecht mit Chefapothekerin Hildagard in Schattenmond.", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Chefapothekerin Hildagard versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihr jede Hilfe willkommen ist.\n\nFalls Ihr Euch jemals dorthin begebt, sucht Hildagard beim Dorf Schattenmond auf, es liegt im nordwestlichen Teil des Tals.", progress = nil, completion = "Fantei hat ein gutes Gedächtnis. Es ist schon Monate her, dass ich in Shattrath war, um Zutaten zu kaufen. Allerdings hat er Recht. Ich könnte etwas Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11047] = {title = "Die Bitte des Gesellen", objective = "Sprecht mit Dama Wildmähne im Dorf Schattenmond im Schattenmondtal.", description = "Als ein Windreitermeisterlehrling gehört es zu meinen Aufgaben, die Tiere zu versorgen, wenn sie nicht gerade fliegen. Das Problem ist, dass die Windreiter sich kaum erholen können, da wir über so wenige von ihnen verfügen.\n\nIch fürchte, dass wenn wir nicht bald Ersatz erhalten, sie sich alle zu Tode fliegen werden. Im westlichen Schattenmondtal, im Dorf Schattenmond, gibt es einen großen Stall. Dama Wildmähne überwacht dort die Ausbildung und Versorgung der dortigen Windreiter.\n\nWürdet Ihr in meinem Namen mit ihr sprechen und ihr von unserer Situation berichten?", progress = nil, completion = "&lt;Dama hört sich Agadais Bitte an.&gt;\n\nIch kann nicht dafür garantieren, dass wir über genügend Windreiter verfügen, aber ich werde sehen, was ich tun kann. In der momentanen Situation haben wir Schwierigkeiten, die Nachfrage der verschiedenen Käufer und Außenposten abzudecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11048] = {title = "Kroghans Bericht", objective = "Sprecht mit Blutwache Gulmok im Dorf Schattenmond.", description = "Meine ursprünglichen Befehle sahen vor, dass ich für kurze Zeit in Garadar bleibe und ich mich anschließend bei Blutwache Gulmok im Dorf Schattenmond melden sollte. In meiner Zeit hier ist mir klar geworden, dass Garadar von einer langfristigen Zusammenarbeit mit der Horde profitieren würde.\n\nIch weiß, dass Blutwache Gulmok alle verfügbaren Truppen braucht, aber er wird auch einsehen müssen, dass meine Mission hier noch nicht zu Ende ist. Reist nach Schattenmond, im nordwestlichen Teil des Schattenmondtals, und informiert Blutwache Gulmok über meine verspätete Ankunft.", progress = nil, completion = "&lt;Gulmok beginnt zu murren, als er von Kroghans Entscheidung hört.&gt;\n\nIch verstehe durchaus seinen Standpunkt, doch unsere Schützengräben besetzen sich nicht von selbst! Die Legion bombardiert uns Tag und Nacht mit Höllenbestien. Wenn Kroghan sich verspätet, könnt Ihr ja seinen Platz auf dem Schlachtfeld einnehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11049] = {title = "Die große Eierjagd", objective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ein Ei der Netherschwingen einsammelt.", description = "Solltet Ihr bei Euren Erkundungen auf Eier der Netherschwingen stoßen, bringt sie zu mir.\n\nEines ist sicher, ein Ei der Netherschwingen ist ein seltener Fund. Lasst den Kopf nicht hängen, falls Ihr keine Eier finden könnt. Die Anhänger des Drachenmals waren beim Einsammeln recht gründlich. Sie haben fast alle aufgespürt und an unbekannte Stellen versendet.\n\nMan findet die Eier im Besitz von Kreaturen der Insel, in der Nähe von Kristallformationen, in den Minen oder auch in Netheritansammlungen oder Netherstaubbüschen.\n\nHaltet Euch bedeckt. Mor'ghor soll wenn möglich nichts von Eurem Unterfangen erfahren.", progress = "Was macht die Eierjagd?", completion = "Neltharaku wird höchst erfreut sein, &lt;Name&gt;. Gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11050] = {title = "Immer her mit den Eiern", objective = "Diese Eier dürfen auf keinen Fall in die falschen Hände geraten, <Name>. Wenn Ihr noch mehr Eier findet, bringt sie mir.\n\nVerhaltet Euch auf jeden Fall unauffällig und erregt bloß keinen Verdacht!", description = nil, progress = "Diese Eier dürfen auf keinen Fall in die falschen Hände geraten, <Name>. Wenn Ihr noch mehr Eier findet, bringt sie mir.\n\nVerhaltet Euch auf jeden Fall unauffällig und erregt bloß keinen Verdacht!", completion = "Ihr seid ein wahrer Held, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][11051] = {title = "Bannt mehr Dämonen", objective = "Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen.", description = "Wenn wir die Dämonen richtig einschätzen, was sehr wahrscheinlich ist, da wir sie ausgiebig studiert haben, werden sie versuchen, den Schaden an ihrem kostbaren Transporter so schnell wie möglich zu reparieren.\n\nAlso, wenn Ihr Eure Chance auf eine weitere Rune der Dunkelheit wahrnehmen möchtet, nehmt den Bannkristall und erledigt dort draußen noch mehr Dämonen für uns. Schließlich wollt Ihr uns doch dabei helfen, die Bedrohung durch die Dämonen in den Griff zu kriegen, nicht wahr?\n\nWir sagten Chance, weil der von uns angewandte Herstellungsprozess nicht immer einwandfrei funktioniert. Manchmal kommt eine Rune der Dunkelheit dabei heraus, dann wieder etwas völlig anderes.", progress = "Jemand mit Eurer Erfahrung dürfte keine Probleme damit haben, ein paar Dämonen zu bannen. Ihr habt doch keine Schwierigkeiten damit, oder <Volk>?", completion = "Wir wünschten uns, der Herstellungsprozess für Runen der Dunkelheit wäre narrensicher, &lt;Name&gt;. Unglücklicherweise ist er das nicht. Nehmt bitte diesen Sack und seht mal, was wir heute hergestellt haben. Wir haben es nicht übers Herz gebracht, selbst nachzusehen.\n\nWenn Ihr eine Rune der Dunkelheit erhaltet, vergesst nicht, Gahk aufzusuchen und sie bei ihm gegen eine kristallgeschmiedete Rune der Dunkelheit einzutauschen. Mit ihr könntet Ihr Shartuuls Transporter erneut ausschalten.\n\nOh, und &lt;Name&gt;, denkt daran, morgen wiederzukommen und den Bannkristall abzuholen. Es sind genug Dämonen da, die gebannt werden möchten.", rewards = "Ihr bekommt:\n\nKronks GrabbelsackApexissplitter"}
MultiLanguageQuestData['de'][11052] = {title = "Akamas Versprechen", objective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, <Name>. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.", progress = "<A'dal bemerkt Euch und umarmt Euch mit einem warmen Licht. Er scheint zu wissen, dass Ihr etwas für ihn habt.>", completion = "&lt;Als Ihr A'dal das Medaillon übergebt, verschwindet es mit einem Lichtblitz in seinem Geist.&gt;\n\n&lt;Für einen kurzen Moment erscheint eine Szene vor Euch... vielleicht aus der Zukunft. Ihr seht, wie Akama und Maiev aus dem Kerker des Wächters heraustreten und sich zum Schwarzen Tempel durchschlagen. Eine dritte, in Schatten gehüllte Gestallt hilft ihnen dabei. Als Ihr genauer hinschaut, erkennt Ihr, dass Ihr diese Gestalt seid.&gt;", rewards = "Akamas SchärpeTiefgrüne HandschuheRundschild des ZauberbrechersKlinge der AschenzungenGewehr des BlutwärtersTodeshörigenstab der AschenzungenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11053] = {title = "Erhebt Euch, Aufseher!", objective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", description = "Es ist selten, dass ein Peon so lange überlebt wie Ihr. Es ist allerdings noch seltener, dass sich ein Peon vom Abschaum abhebt und in einen neuen Rang aufsteigt.\n\n<Varkule klatscht.>\n\nDer Oberanführer hat nach Euch verlangt, Grunzer. Sicherlich erwartet Euch ein neuer Rang.", progress = nil, completion = "Ich habe Eure Handlungen mit einem wachsamen Auge verfolgt, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr ein unschätzbarer Gewinn für das Drachenmal seid. Daher werde ich Euch zum Aufseher befördern. Ein neuer Rang bedeutet natürlich auch neue Verantwortungen, denen Ihr gerecht werden müsst.\n\nErhebt Euch, Aufseher &lt;Name&gt;! Erhebt Euch und sucht diejenigen auf, die Eure Hilfe hier im Basislager brauchen.", rewards = "Ihr bekommt:\n\nAbzeichen des Aufsehers"}
MultiLanguageQuestData['de'][11054] = {title = "Aufsehen und Ihr: Die richtige Wahl treffen", objective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 10 Einheiten Knotenhautleder und 1 gehärteten Balg von Tyrantus bringt.", description = "Ihr seid also der neue Aufseher, was? Tja, es gibt da eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe. Bevor Ihr dort hinausgehen und diesen Peons etwas Verstand einprügeln könnt, braucht Ihr Eure \"Waffe\". Jeder Aufseher muss die Materialien zur Herstellung seiner eigenen \"Waffe\" sammeln und Ihr seid da keine Ausnahme.\n\nIch benötige Knotenhautleder und den gehärteten Balg von Tyrantus. Ihr findet Tyrantus in der Biokuppel Fernfeld, welche in der nördlichen Gegend des Nethersturms zu finden ist.", progress = "Es gilt Peons zur Ordnung zu rufen, <Name>! Beeilt Euch!", completion = "Ahh! Vielleicht habt Ihr ja doch das Zeug zum Aufseher. Diese übergroße Echse war schon das Leid vieler Orcs!\n\n&lt;Chefvorarbeiter Lehmklump beginnt mit der Herstellung der Waffe.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11055] = {title = "Der Schuhmerang: Das Mittel gegen den wertlosen Peon", objective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 faule Peons des Drachenmals zur Ordnung ruft. Gebt anschließend auch Euren Schuhmerang wieder zurück.", description = "Dies hier ist Euer Schuhmerang. Es gibt viele andere, aber dieser ist Eurer.\n\nAls Aufseher werdet Ihr diesen Schuhmerang verwenden, um Furcht in die Herzen aufsässiger Peons zu pflanzen. Der richtige Einsatz des Schuhmerangs wird für Gehorsam und Unterwürfigkeit sorgen.\n\nGeht weit hinaus zu den Kristallfeldern und diszipliniert jeden Peon, den Ihr beim Faulenzen erwischt. Zeigt ihnen die Macht des Schuhmerangs!", progress = "Der Trick liegt im Handgelenk, <Name>.", completion = "Ein Tag harter Arbeit! Es zahlt sich aber aus, oder? Beim Anblick der schuftenden Taugenichtse bei den Kristallen wird einem richtig Warm um's Herz... Nun ja, das ist alles für heute. Kommt morgen wieder, dann könnt Ihr ein weiteres Mal den Schuhmerang schwingen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11056] = {title = "Hazziks Handel", objective = "Sucht nach Hazziks Päckchen bei seiner Behausung im östlichen Skettis und kehrt damit zu ihm zurück.", description = "Erwähnt unsere Unterhaltung nicht. Adaris würde nichts davon gutheißen.\n\nIch gehöre der niedrigsten Kaste der Arakkoa an, <Name>. Während Terokks Herrschaft hätte man mich den dunklen Mächten geopfert, die von den Krallenpriestern verehrt werden. Sollte was Ihr sagt, wahr sein und sollten die Krallenpriester wirklich Terokks Rückkehr herbeisehnen, dann müsst Ihr dies unbedingt verhindern - ganz egal, was Euer Anführer sagt!\n\nIch habe etwas für Euch, das Ihr sehr nützlich finden werdet. Bei meiner alten Behausung im Oberen Shil'akversteck liegt ein Päckchen. Bringt es mir.", progress = "<Name>, Ihr seid zurück! Ich dachte schon, Ihr hättet mich im Stich gelassen.", completion = "Ausgezeichnet, &lt;Name&gt;. Ihr werdet sehen, dass ich mein Wort halte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11057] = {title = "Schwierigkeiten in der Tiefe", objective = "Sprecht mit Mog'dorg dem Weisen. Ihr findet ihn auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", description = "Wir wissen Euren Eifer, uns hier in Ogri'la unterstützen zu wollen, sehr zu schätzen, <Klasse>. Doch bevor wir Euer großzügiges Angebot annehmen können, müssen wir Euch zunächst um einen Gefallen bitten.\n\nUnsere Brüder dort unten sind Sklaven der Söhne von Gruul. Bitte, sprecht mit Mog'dorg dem Weisen. Er ist der Anführer einer Widerstandsbewegung der dort heimischen Oger gegen die Gronn.\n\nIhr findet ihn auf dem Turm, auf der östlichen Seite der Arena des Zirkels des Blutes.", progress = nil, completion = "Man hat Euch von hoch oben zu mir geschickt? Wahrlich, meine Mission ist gesegnet! Ich versuche die Blutschläger vor der Ausrottung durch den Speerspießerklan und Gruuls Söhne zu bewahren.\n\nIch nehme an, dass Ihr unsere geheime Organisation unterstützen und uns die Freiheit bringen werdet?", rewards = nil}
MultiLanguageQuestData['de'][11058] = {title = "Ein Apexisrelikt", objective = "Erlangt Apexisschwingungen von einem Apexisrelikt.", description = "Vor langer Zeit lebte hier eine Sekte der Arakkoa, die Apexis. Überreste ihrer seit langem ausgestorbenen Zivilisation sind auch heute noch allgegenwärtig. Wir nennen sie Apexisrelikte.\n\nDas Einzige, was wir mit Sicherheit wissen, ist, dass sie bei richtiger Benutzung einen Segen gewähren. Jedes Relikt repräsentiert eine farbige Sequenz, welche, wenn man die Kristalle in der richtigen Reihenfolge drückt, zu einer Serie von Stufen führen, eine schwieriger als die andere.\n\nEs wird ein Apexissplitter benötigt, um das Relikt zu aktivieren. Kehrt zurück, wenn Ihr mehr über die Apexisschwingungen erfahren habt.", progress = nil, completion = "&lt;Chu'a'lors Köpfe nicken Euch anerkennend zu.&gt;\n\nIhr habt einen scharfen Verstand, &lt;Name&gt;. Wir haben erheblich länger gebraucht, um das Relikt erfolgreich zu benutzen.\n\nNun, da Ihr wisst wie, könnt Ihr es so oft Ihr wollt verwenden. Denkt jedoch daran, dass für die Aktivierung eines Relikts immer ein Apexissplitter erforderlich ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11059] = {title = "Wächter des Monuments", objective = "Beschafft den Kopf eines Apexiswächters.", description = "Ihr habt erfolgreich herausgefunden, wie man die Ein-Personen-Relikte benutzt. Aber wie Ihr wahrscheinlich schon bemerkt habt, umgeben die kleineren noch größere Relikte.\n\nDiese großen Apexismonumente funktionieren auf die exakt gleiche Weise, allerdings werden 35 Apexissplitter benötigt, um sie zu aktivieren.\n\nViel größere Sorgen bereiten uns die Wächter, die bei der Benutzung eines Relikts beschworen werden. Diese Kristallkonstrukte haben sich vor langer Zeit gegen ihre Arakkoameister gewendet und gefährden nun Ogri'la.\n\nWir möchten Euch bitten, einen von ihnen zu zerstören und uns einen Beweis Eurer Tat zu bringen.", progress = "Wir verabscheuen Gewalt, aber wenigstens ist das Konstrukt, das Ihr vernichten sollt, kein lebendiges Wesen.\n\nWo wir schon davon sprechen, habt Ihr den Kopf?", completion = "&lt;Chu'a'lor mustert Euch voller Respekt.&gt;\n\nEure und die geistige Gewandtheit Eurer Freunde ist wahrlich beeindruckend. Dafür, dass Ihr uns und unsere Lebensweise verteidigt habt, stehen wir, nein, stehen ganz Ogri'la und die Himmelswache in Eurer Schuld.\n\nDenkt daran &lt;Name&gt;, Ihr könnt jederzeit mit einer Gruppe zurückkehren, um die großen Apexismonumente zu benutzen. Bringt aber genügend Apexissplitter mit, um sie aktivieren zu können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11060] = {title = "Eine kristallgeschmiedete Rune der Dunkelheit", objective = "Die Dämonen machen das Konstruktionslager: Wut größer. Bald sie zu stark sind und uns vernichten werden. Ihr sie zuerst schlagen müsst!\n\nShartuuls Transporter sein Schlüssel zu Sieg, aber er werden beschützt von magischem Schild und mächtigen Dämon, einem Zerrütter. Wir mächtiger Hexenmeister und wir Euch herstellen werden eine besondere Rune der Dunkelheit, mit der Ihr Zerrütter kontrollieren könnt. <Volk> geben GahkRune der Dunkelheit, wir geben <Volk> kristallgeschmiedete Rune der Dunkelheit.\n\nIhr übernehmen den Zerrütter und übernehmen Herrschaft über so viele aus dem Portal kommende Dämonen wie möglich, um sie aufzuhalten!", description = nil, progress = "Die Dämonen machen das Konstruktionslager: Wut größer. Bald sie zu stark sind und uns vernichten werden. Ihr sie zuerst schlagen müsst!\n\nShartuuls Transporter sein Schlüssel zu Sieg, aber er werden beschützt von magischem Schild und mächtigen Dämon, einem Zerrütter. Wir mächtiger Hexenmeister und wir Euch herstellen werden eine besondere Rune der Dunkelheit, mit der Ihr Zerrütter kontrollieren könnt. <Volk> geben GahkRune der Dunkelheit, wir geben <Volk> kristallgeschmiedete Rune der Dunkelheit.\n\nIhr übernehmen den Zerrütter und übernehmen Herrschaft über so viele aus dem Portal kommende Dämonen wie möglich, um sie aufzuhalten!", completion = "Kleiner &lt;Volk&gt;, nicht vergessen, wenn Ihr einen Zerrütter kontrollieren, Ihr müssen seinen Hammer dazu benutzen, um die Schilde von Warptor zu zerschlagen und den gefangenen Dämonen freizulassen.\n\nDann Ihr müssen zerschlagen diesen Dämon und ihn beherrschen. Dann kommen neuer Dämon, den Ihr auch beherrschen müssen, bis der Aufseher der Eredar auftauchen.\n\nDann Ihr auch ihn erschlagen werdet!!!", rewards = "Ihr bekommt:\n\nKristallgeschmiedete Rune der Dunkelheit"}
MultiLanguageQuestData['de'][11061] = {title = "Die Pflichten eines Vaters", objective = "Beschafft ihm ein instabiles Fläschchen des Zauberers.", description = "Was das andere magische Fläschchen angeht, man bekommt es ausschließlich an einem Ort: der Landeplatz von Bash'ir. Es handelt sich um einen Stützpunkt der Astralen und sie sind Fremden gegenüber nicht gerade freundlich eingestellt, daher könnte es etwas gefährlich werden.\n\nSicherlich fragt Ihr Euch jetzt, wo man diesen Landeplatz von Bash'ir findet? Steigt auf Euer fliegendes Reittier und reist in Richtung Nord, Nordosten, bis Ihr ein gutes Stück hinter dem Konstruktionslager: Wut seid, dann müsstet Ihr den besagten Landeplatz sehen. Die Kristallschmiede von Bash'ir befindet sich in der nordöstlichen Ecke des Stützpunkts.\n\nDanke für Eure Hilfe, <Name>. Es bedeutet unseren Söhnen alles!", progress = "Dieses Fläschchen des Zauberhexers wird meine Jungs sicherlich noch intelligenter machen, als sie es ohnehin schon sind. Damit sollten ihnen die täglichen Pflichten in der Himmelswache der Sha'tari etwas leichter fallen.", completion = "Wir können Euch gar nicht genug danken, &lt;Name&gt;!\n\nSo instabil diese zwei Fläschchen auch sein mögen, mit ihrer Hilfe können wir nun einen unserer Jungs nach Norden zum Außenposten der Himmelswache schicken.\n\nWartet einen kleinen Augenblick, während wir einen von ihnen rufen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRegelmäßig - Torkus Junior rufen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11062] = {title = "Der Außenposten der Himmelswache", objective = "Sprecht mit Himmelskommandant Keller beim Außenposten der Himmelswache im Schergrat.", description = "<Name>, wir haben uns gefragt, ob Ihr vielleicht nach Norden aufbrechen würdet, um unseren Freunden beim Außenposten der Himmelswache einen Besuch abzustatten?\n\nKommandant Keller und seine Himmelswache führen zu unserem Schutz diverse Unternehmungen durch und erst kürzlich bat er uns, jeden vorbeizuschicken, der Willens ist, sie bei ihrer Arbeit zu unterstützen.\n\nDas wäret dann wohl Ihr!\n\nBrecht so schnell wie möglich dorthin auf und übermittelt ihnen unsere besten Grüße.", progress = nil, completion = "Willkommen im Außenposten der Himmelswache. Wisst Ihr, ich habe den gesamten Posten mit meinen eigenen Händen errichtet.\n\nSchon richtig gehört, alles was Ihr hier vor Euch seht!\n\n&lt;Dem Himmelskommandanten scheint es ernst zu sein.&gt;\n\nIhr müsst ja ganz schön scharf auf einen Kampf sein, wenn Ihr extra hierher gekommen seid, um mit mir zu sprechen. Es war nett vom alten Chu'a'lor, Euch vorbeizuschicken. Wir können hier immer etwas Frischfleisch gebrauchen.\n\nWenn es Euch nichts ausmacht, würde ich vorschlagen, Ihr unterhaltet Euch ein wenig mit meinem Himmelsoffizier Vanderlip. Stört Euch nicht an ihrem Gebaren, ihre Zunge ist womöglich schärfer als das Breitschwert, das sie bei sich trägt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11063] = {title = "Sich Flügel verdienen...", objective = "Ihr möchtet also zu den Himmelsteilern gehören, ja? Ihr habt Euch mit Sicherheit als fähiger Anhänger des Drachenmals bewiesen, aber in den Lüften der Scherbenwelt ist dies bedeutungslos. Es gibt eine Frage zu klären: KÖNNT IHR FLIEGEN?\n\nUnd ich frage nicht etwa, ob Ihr auf einen Netherdrachen steigen und wie diese Transportertrottel eine Ladung Kristalle zu der Festung liefern könnt. Ich rede davon, der Beste zu sein... der Toporc...\n\nDort drüben im Westen gibt es sechs Reiter. Besiegt sie alle und ich werde Euch Flügel der Himmelsteiler geben.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11064] = {title = "Drachenmalrennen: Murg \"Grufti\" Moorbiss", objective = "Folgt Murg \"Grufti\" Moorbiss und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Murg \"Grufti\" Moorbiss besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", description = "Lasst Euch von dem grauen Haar nicht täuschen, Grunzer. Ich bin trotz allem ein zehnmal so guter Reiter! Glaubt bloß nicht, dass dieser Totgesagte keine Tricks mehr im Ärmel hat.\n\nVersucht mir zu folgen und nicht von Eurem Reittier geworfen zu werden, das ist alles. Wenn Ihr das fertig bringt, wird Grufti seine Niederlage eingestehen.\n\nWir heben ab, sobald Ihr bereit seid.", progress = nil, completion = "Ein Kinderspiel? Was ist nur aus den Helden geworden... Ich bin mir sicher, dass die anderen Reiter eine größere Herausforderung sein werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11065] = {title = "Bändigt ein paar Ätherrochen!", objective = "Bändigt mithilfe des Bändigungsseils 5 Ätherrochen.", description = "Wollt Ihr der Himmelswache und Ogri'la aushelfen?\n\nHört mir erst zu, bevor Ihr einfach davonrennt, <Junge/Mädel>. Wir benötigen dringend mehr Reittiere. Die Missionen und Bombenangriffe auf den Landeplatz von Bash'ir haben uns so manches Reittier gekostet.\n\nDie Ätherrochen, die beim Vortexgipfel und am Kristallrücken herumfliegen, sollten für unsere Zwecke genügen. Ihr müsst sie nicht einmal hierher zurückbringen, obwohl das nett wäre. Bändigt sie einfach und bindet sie irgendwo an, wir holen sie dann später ab.\n\nSeid Ihr dieser Aufgabe gewachsen?", progress = "Habt Ihr schon ein paar Ätherrochen gebändigt? Ihr seht so aus, als könntet Ihr mit einem Lasso umgehen. Sicher habt Ihr Euren Auftrag schnell abgeschlossen.", completion = "Juhuu! Gute Arbeit, &lt;Name&gt;! Diese Rochen werden ein paar hervorragende Reittiere abgeben!\n\nBleibt ruhig noch ein wenig, die Himmelswache der Sha'tari kann Männer mit Euren Talenten immer gut gebrachen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11066] = {title = "Bändigt noch mehr Ätherrochen!", objective = "Bändigt mithilfe des Bändigungsseils 5 Ätherrochen.", description = "Ich hoffe Ihr seid bereit, noch ein paar mehr Ätherrochen zu bändigen! Soweit ich das beurteilen kann, liegt Euch der Umgang mit dem Seil im Blut!\n\nUnd es dient einem guten Zweck, denn so kriegen wir nicht nur frische Reittiere, sondern Ihr helft uns auch noch Ogri'la zu beschützen, wofür die Oger dankbar sind.\n\nNicht vergessen, die Ätherrochen fliegen beim Vortexgipfel und am Kristallrücken im Nordosten herum.\n\nSchafft Ihr es, noch ein paar mehr für mich zu bändigen?", progress = "Ihr leistet hervorragende Arbeit für uns, <Name>! Ich möchte Euch nur wissen lassen, dass wir Eure Bemühungen, uns mit frischen Reittieren zu versorgen, sehr zu schätzen wissen!", completion = "Ihr erstaunt mich immer wieder! Ich sage Euch was, warum lasst Ihr das Lasso nicht für heute ruhen und wir sehen uns morgen wieder?\n\n&lt;Khatie lacht.&gt;\n\nNochmals vielen Dank, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nApexissplitter"}
MultiLanguageQuestData['de'][11067] = {title = "Drachenmalrennen: Trope der Rußhuster", objective = "Folgt Trope dem Rußhuster und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Trope den Rußhuster besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", description = "Das Drachenmal behandelt einen richtig, <Name>. Selbst so ein ausgelaugtes und gezeichnetes Wesen wie ich bekommt seine Chance. Wenn Ihr Euch den Himmelsteilern als würdig erweisen wollt, dann müsst Ihr mich besiegen.\n\nIch werde Euch wie einen Schwarm lästige Fliegen abschütteln...\n\nWir heben ab, sobald Ihr bereit seid.", progress = nil, completion = "Interessant... Euer nächstes Rennen wird sich zweifellos als viel schwieriger erweisen. Corlok ist kein Weichei.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11068] = {title = "Drachenmalrennen: Corlok der Veteran", objective = "Folgt Corlok dem Veteranen und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Corlok den Veteranen besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", description = "Ihr fordert MICH heraus? Jetzt muss ich aber lachen!\n\nIst das Euer Ernst? Na gut! Achtet lediglich darauf, nicht zu sterben. Ihr schafft das doch, nicht zu sterben, oder?? Auch wenn ich Schädel nach Euch werfe und in Kreisen um Euch und Eure erbärmlichen Flugkünste fliege?\n\nLasst mich einfach wissen, wann's losgehen kann, dann heben wir ab.", progress = nil, completion = "Die nächsten zwei Reiter sind die besten Piloten, die die Zwerge und Orcs von Azeroth zu bieten hatten. Ihr habt keine Chance!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11069] = {title = "Drachenmalrennen: Schwadronskommandant Ichman", objective = "Folgt Schwadronskommandant Ichman und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Ichman besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", description = "Drei Jahre habe ich in diesem Loch zugebracht. Drei Jahre lang war ich Kriegsgefangener des verdammten Frostwolfklans. Ich musste in ihrem Turm sitzen und ihr endloses Gejammer über die Brücke nach Dun Baldar ertragen. Wie \"ungerecht\" es doch sei, dass bla, bla, bla, bla... Im Krieg gibt es keine Gerechtigkeit! Zur Hölle mit ihnen allen!\n\nIn dem Augenblick, in dem ich befreit wurde, habe ich diesen Ort für immer verlassen und bin hierhergekommen, um ein neues Leben zu beginnen. Mulv und ich konkurrieren jetzt um den Platz des Toporcs. Sollte das auch Euer Ziel sein, dann müsst Ihr erstmal an mir vorbei, Anfänger.\n\nEs geht los, wenn Ihr bereit seid.", progress = nil, completion = "Ich glaube es nicht! Mulverick ist Eure nächste Herausforderung. Dieses Rennen werdet Ihr auf keinen Fall überleben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11070] = {title = "Drachenmalrennen: Schwadronskommandant Mulverick", objective = "Folgt Schwadronskommandant Mulverick und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Mulverick besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", description = "Drei Jahre lang Blut, Schweiß und Tränen. Hauptsächlich Tränen... Es ist erstaunlich, wie viele Tränen selbst ein hartgesottener Soldat vergießt, wenn es im Krieg zur Sache geht.\n\n\"Sie springen mit ihren Pferden in unseren Turm!\" \"Warum muss die feindliche Basis so gut verteidigt sein?\" \"Verdammt, der Feind hat die Heilerhütte erobert, ich mache mich vom Acker!\"\n\nVerdammte Feiglinge...\n\nKaum war das Dunkle Portal offen, hab' ich die Möglichkeit beim Schopfe gepackt und mich aus dem Land der Weicheier verabschiedet. Jetzt arbeite ich als Toppilot für die Jungs des Drachenmals. Wenn Ihr also der Toporc werden wollt, müsst Ihr mich erst einmal schlagen.\n\nEs geht los, sobald Ihr bereit seid.", progress = nil, completion = "Nun Grunzer, es sieht ganz so aus, als gäbe es jetzt nur noch Euch und den Hauptmann. Viel Glück! Ihr werdet es brauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11071] = {title = "Drachenmalrennen: Hauptmann Himmelsdonner", objective = "Folgt Hauptmann Himmelsdonner und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Hauptmann Himmelsdonner besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", description = "Ihr wagt es, Himmelsdonner herauszufordern? Die Welt um Euch herum wird in Dunkelheit versinken, wenn meine Meteore den Horizont zerreißen.\n\nIhr habt keine Chance, Soldat. Offenbar ist es jedoch Euer Wunsch, zu sterben...\n\nIch werde bei Eurem morbiden Vorhaben mitspielen. Vielleicht kann ich anderen Narren, die nach der gleichen Verrücktheit streben, zumindest eine Lehre erteilen.\n\nWir reiten los, wenn Ihr bereit seid!", progress = nil, completion = "Ich hätte es mir nie träumen lassen, dass es jemanden gibt, der talentiert genug ist und Himmelsdonner besiegen kann. Wisst Ihr was das bedeutet, ja? Ihr seid jetzt der Toporc! Ihr müsst Euren Titel verteidigen.", rewards = "Ihr bekommt:\n\nPeitsche der Himmelsteiler"}
MultiLanguageQuestData['de'][11072] = {title = "Feindesblut", objective = "Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück.", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Karrog der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Benutzt sie bei den Beschwörungskreisen, die es in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mitzunehmen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeitverlorene Opfergabe"}
MultiLanguageQuestData['de'][11073] = {title = "Terokks Fall", objective = "Bringt die Zeitverlorene Opfergabe, die Hazzik angefertigt hat, zu dem Schädelhaufen im Zentrum von Skettis. Beschwört Terokk und bezwingt ihn. Habt Ihr Eure Aufgabe erfüllt, kehrt zu Himmelskommandant Adaris zurück.", description = "Ich... ich habe bezüglich Eures Verhaltens gegenüber dem Arakkoagefangenen ein Auge zugedrückt, <Name>. Es sieht ganz so aus, als hätte Euch Euer Instinkt nicht getäuscht. Es war richtig, mit ihm zusammenzuarbeiten.\n\nBitte versteht... Ich hätte mich in der jetzigen Lage inmitten eines Aufruhrs wiedergefunden, hätte ich Eure Bemühungen, Terokk in diese Welt zu bringen, gebilligt.\n\nNehmt die Gegenstände, die Hazzik für Euch zusammengestellt hat und führt Euren Plan weiter fort. Ich werde meinen Männern befehlen, Euch Rückendeckung zu geben, wenn es an der Zeit dafür ist. Ich rate Euch, auch selbst Verstärkung mit Euch zu bringen. Ich fürchte Ihr habt nur diese eine Chance.", progress = nil, completion = "Ihr habt uns alle sehr stolz gemacht, &lt;Name&gt;. Ich werde die Kunde von Euren Taten in Shattrath verbreiten. Die Himmelswache steht für immer in Eurer Schuld.", rewards = "WindstürmerlanzeSeverins StockJuwelenbesetzte RuteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11074] = {title = "Zeichen der Nachfahren", objective = "Sammelt zeitverlorene Schriftrollen von den zeitverlorenen Arakkoa in Skettis ein und bringt sie zu den Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört und bezwingt die Nachfahren der Gegner Terokks und kehrt zu Hakkiz mit Akkarais Kralle, Garokks Stachel, Vekkaz' Schuppe und Gezzaraks Klaue zurück.", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Garogg der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Verbrennt sie bei den Beschwörungskreisen, die es überall in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mit Euch zu bringen.", progress = "Ich benötige einen Gegenstand von jedem der Nachfahren von Terokks ärgsten Feinden. Nur dann können wir Terokk beschwören.", completion = "Hervorragend! Hier, nehmt dies. Ich habe dieses Bündel aus den Gegenständen erstellt, die Ihr mir gebracht habt. Damit werdet Ihr Terokk beschwören können.\n\nSeid auf der Hut, &lt;Name&gt;. Er ist der mächtigste Arakkoa aller Zeiten. Unterschätzt ihn nicht!", rewards = "Ihr bekommt:\n\nZeitverlorene Opfergabe"}
MultiLanguageQuestData['de'][11075] = {title = "Die Netherschwingenminen", objective = "Sucht die Herrin der Minen auf der Netherschwingenscherbe auf.", description = "Wir benötigen Eure Hilfe bei den Netherschwingenminen, Aufseher <Name>.\n\nVor zwei Tagen machten wir eine düstere Entdeckung und daraufhin kamen unsere Minenarbeiten zum Stillstand. Ein Minenarbeiter arbeitete in den Tiefen der Mine und hieb seine Hacke in eine ungewöhnliche Kristallformation. Unglücklicherweise war diese Kristallformation mit einem sehr verärgerten Netherdrachen verbunden. Die Bestie erwachte aus ihrem Schlaf und tötete all unsere Arbeiter.\n\nErstattet bei der Herrin der Minen Bericht. Man erwartet Euch beim Eingang der Minen, südwestlich von hier.", progress = nil, completion = "Die Minenarbeiter leisten harte Arbeit, aber keiner von ihnen wagt es, einen Schritt tiefer in die Minen zu setzen. Sie sterben lieber, als dass sie sich tiefer in die Minen zwingen lassen! Es wird Eure Aufgabe sein, die von ihnen vernachlässigten Pflichten zu erfüllen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11076] = {title = "Die Dinge in den Griff bekommen...", objective = "Die Herrin der Minen bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Kisten mit Fracht der Netherminen einsammelt.", description = "Die Mühen unserer harten Arbeit liegen überall in diesen Minen verstreut. Wagenladungen voller Fracht bedecken jeden Zentimeter dieser Mine! Auf Grund der Plage kommen wir nur an nichts von alledem heran.\n\nGenau hier kommt Ihr ins Spiel, <Name>. Eure tägliche Arbeit bei der Mine wird aus dem Einsammeln der von den Minenarbeitern und Tiefenminenarbeitern zurückgelassenen Fracht bestehen.\n\nSammelt die Fracht der Netherminen ein und kehrt zu mir oder meiner Schwester zurück.", progress = "Habt Ihr die Fracht eingesammelt?", completion = "Gut gemacht, &lt;Name&gt;. Kommt morgen für einen weiteren Einsatz in den Tiefen der Mine wieder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11077] = {title = "Drachen sind unsere geringste Sorge", objective = "Der Vorarbeiter des Drachenmals bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Netherminenschinder und 5 Netherminenhetzer tötet.", description = "Als der Drache erwachte, schreckte er in diesen Minen noch ganz andere bösartige Kreaturen auf. Insbesondere zwei Arten sind dem Drachenmal ein Dorn im Auge: Netherminenschinder und Netherminenhetzer. Ihr müsst uns helfen, sie alle zu töten. Ich bitte Euch lediglich einmal pro Tag um Eure Mithilfe.\n\nGeht hinein und vernichtet so viele, wie Ihr nur könnt!", progress = nil, completion = "Das sollte für heute reichen, Aufseher. Kommt morgen für eine weitere Aufräumrunde wieder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11078] = {title = "Den Himmel beherrschen", objective = "Beschafft Euch Drachenzähne.", description = "Während Ihr herumgeflogen seid, sind Euch sicherlich die Drachen aufgefallen. Schätze, ihr Zorn blieb Euch bisher erspart. Helft uns, diese Biester ein für alle Mal zu erledigen, <Name>!\n\nNachtreißer und Obsidia beherrschen dieses Plateau, während Insidion und Zornschwinge den Himmel über den Terrassen im Nordosten für sich beanspruchen. Jeder der Drachen hat ein Nest in seinem Revier gebaut. Ich frage mich, ob Ihr und Eure Freunde einen aufsuchen würdet, <Kumpel/Mädel>. Brecht ein Ei mit 35 Apexissplittern auf, um den Drachen herunterzulocken.\n\nBringt mir ein paar Zähne als Beweis.", progress = "Wie geht es voran, <Name>? Ich brauche Euch sicherlich nicht extra zu sagen, wie wichtig die ganze Angelegenheit für unsere Luftüberlegenheit ist.", completion = "Ja! Diese Zähne sehen scharf aus, als könnten sie beinahe alles wie Butter durchschneiden!\n\nErlaubt mir, Euch und Eure Freunde dazu zu ermuntern, weiterhin so gute Arbeit zu leisten! Diese Drachen sind gefährliche Raubtiere, die unseren Himmel lange genug unsicher gemacht haben.\n\nEuch sind sicherlich die Drachenschuppen aufgefallen. Wie ich hörte, kann man aus ihnen einen mächtigen Umhang herstellen, sofern man eine Schuppe von jedem der Drachen besitzt. Sollte Euch der Umhang nicht zusagen, bin ich jederzeit bereit, ihn gegen einen Apexiskristall einzutauschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11079] = {title = "Eine Teufelspeitsche für Gahk", objective = "Beschafft Euch eine Teufelspeitsche.", description = "Gahk manchmal glauben, es nicht gut ist, schlau zu sein. Gahk möchten nicht so viel nachdenken müssen. Ich wollen, dass <kleiner/kleine:r> <Volk> große Dämonen totschlagen!\n\nSie haben einige Anführer und jeder von ihnen haben Peitschen, um den mickrigen Dämonen Verstand einzuprügeln. Gahk wollen so eine Peitsche!\n\nDazu Ihr herausfordern müssen einen Dämonenanführer in Konstruktionslager. Einen solchen Ihr finden bei brennenden, grünen kristallinen Teufelsprisma. Benutzen 35 Apexissplitter, um sie zu rufen. Sie hören auf Namen wie Galvanoth, Braxxus, Zarcsin und der Verbrenner der Mo'arg.", progress = "Ihr haben Peitsche?", completion = "Gahk mögen Peitsche. Vielleicht Ghak nehmen Peitsche und bearbeiten ein paar Dämonen!\n\nMich sagen zu &lt;Volk&gt;, dass &lt;Volk&gt; kann jederzeit beschwören Dämonenanführer, solange &lt;Volk&gt; haben viele Freunde und 'ne Menge Splitter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11080] = {title = "Die Strahlung des Relikts", objective = "Erlangt Apexisstrahlung von einem Apexisrelikt.", description = "Nachdem Ihr die erleuchtenden Schwingungen der Apexisrelikte am eigenen Leib erfahren habt, ist es an der Zeit, ein tieferes Verständnis für die Funktionsweise der Relikte zu bekommen. Wir würden von Euren Beobachtungen profitieren.\n\nJe mehr Eure Fähigkeiten wachsen, Euch auf die Kräfte der Relikte einzustellen, desto mehr Wissen werdet Ihr über sie erlangen. Ist es erst einmal soweit, wird Euch ein Strahlungsausstoß des Relikts Euren Erfolg anzeigen.\n\nKehrt zu uns zurück, wenn Ihr eine solche Strahlungsaura erlangt habt.", progress = "Habt Ihr eine Aura der Apexisstrahlung von dem Apexisrelikt erlangt?", completion = "Euer Geschick im Umgang mit den Relikten erstaunt uns immer wieder, &lt;Name&gt;. Dürften wir Euch vorschlagen, mindestens einmal am Tag den Gebrauch der Relikte zu üben, damit Euer Verstand seine Schärfe bewahrt?", rewards = "Ihr bekommt:\n\nApexissplitter"}
MultiLanguageQuestData['de'][11081] = {title = "Der große Aufstand der Finsterblut", objective = "Bringt die Fluchtpläne der Finsterblut zur Herrin der Minen.", description = "Dieses Schriftstück beschreibt einen von den Zerschlagenen der Finsterblut geplanten Aufstand. Offenbar diente der Drache der allgemeinen Zerstreuung, um von ihrer Flucht abzulenken. Beim Betrachten der überall in der Mine herumliegenden Leichen, könnte man von einem Fehlschlag ihres Plans ausgehen.\n\nBringt die Fluchtpläne zur Herrin der Minen.", progress = "Was ist das?", completion = "Ausgezeichnete Arbeit, Aufseher. Man wird Mor'ghor von Euren herausragenden Taten für das Drachenmal berichten.\n\nLasst uns jetzt wieder auf diese Hunde der Finsterblut zu sprechen kommen. Sie planen ihre Flucht, ja? Sie wagen es, sich dem einzig wahren Fürsten der Scherbenwelt zu widersetzen? Ihre Meister werden dafür bezahlen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11082] = {title = "Suche nach der Wahrheit", objective = "Findet einen Aufpasser der Finsterblut und verhört ihn. Kehrt mit den Informationen der Finsterblut und mit der Hand des Aufpassers zur Herrin der Minen zurück.", description = "Diese Minenarbeiter sind viel zu dumm, als dass sie irgendeinen Fluchtplan aushecken könnten. Wir müssen die Quelle des Übels finden und bestrafen. Wagt Euch in die Tiefen der Minen und sucht nach den Aufpassern der Finsterblut. Wenn sie nicht schon von den Bewohnern der Minen überwältigt wurden, so halten sie sich zweifellos versteckt.\n\nSolltet Ihr einen von ihnen ausfindig machen, verhört ihn so lange, bis er das wahre Gehirn, das hinter diesem Fluchtplan steckt, preisgibt. Kehrt mit der Identität des Verräters und der Hand des Aufpassers zu mir zurück.", progress = "Nun? Warum dauert das so lange?", completion = "Nichts zu sagen? Vielleicht erinnert er sich ja, wenn er auf dem Boden dieser verfluchten Mine zu Tode blutet... Vergesst nie, was es bedeutet, die Mächte Illidans herauszufordern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11083] = {title = "Verrückt und verwirrt", objective = "Ronag der Sklaventreiber in den Netherschwingenminen im Schattenmondtal möchte, dass Ihr den verrückten Großknecht der Finsterblut und 5 verrückte Minenarbeiter der Finsterblut tötet.", description = "Sorgt Euch nicht wegen diesem Drachen, <Name>. Wir haben bereits Pläne für ihn...\n\nTiefer in der Mine gibt es eine verrückte Schar der Finsterblut. Nachdem der Drache ausgebrochen ist, wurde ihnen der Weg zum Ausgang versperrt. Nach zwei Tagen der Abgeschiedenheit scheinen sie auf irgendeine Art und Weise jegliche Würde verloren zu haben.\n\nSie haben sich dem Kannibalismus und der Gewalt verschrieben. Dieser Wahnsinn ist hier alles andere als erwünscht. Findet und tötet sie. Alle!", progress = nil, completion = "Ja, ich verstehe das nicht... Man würde doch meinen, dass sie nach zwei Tagen nicht derart ausgehungert sein können. Finsterblut...\n\n&lt;Ronag schüttelt den Kopf.&gt;\n\nSowas von dämlich...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11084] = {title = "Seid gegrüßt, Hauptmann!", objective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", description = "Nun sieh einer an... Ihr lebt also noch. Das trifft sich gut, denn Mor'ghor hat nach Eurer sofortigen Anwesenheit in seinem Turm verlangt. Los mit Euch!", progress = nil, completion = "&lt;Mor'ghor nickt.&gt;\n\nGanz recht, ich habe Hauptmann gesagt. Ihr habt Euch eine weitere Beförderung verdient, &lt;Name&gt;.\n\nIhr arbeitet wirklich wie keiner der Höllenorcs, die ich bis jetzt gesehen habe. Macht weiter so, dann schafft Ihr es vielleicht eines Tages zum Oberanführer.\n\nZieht jetzt los und übernehmt das Kommando. Ich schlage vor, dass Ihr versucht, Euch Eure Flügel der Himmelsteiler zu verdienen.", rewards = "Ihr bekommt:\n\nAbzeichen des Hauptmanns"}
MultiLanguageQuestData['de'][11085] = {title = "Flucht aus Skettis", objective = "Begleitet die gefangene Himmelswache in Sicherheit und meldet Euch anschließend bei Himmelsoffizier Doryn.", description = "Seid gegrüßt, <Name>. Ich danke Euch, dass Ihr mir zu Hilfe gekommen seid.\n\nIch war auf einer Erkundungsmission, als mich die riesigen Vögel der Arakkoa von meinem Netherrochen rissen.\n\nVerschwinden wir von hier, solange es noch geht!", progress = nil, completion = "Danke, dass Ihr unseren Späher gerettet habt, &lt;Name&gt;. Jeden Tag verlieren wir gute Leute und es kommen beileibe nicht genug Rekruten nach, um sie alle zu ersetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11086] = {title = "Schwächt das Portal des Zwielichts", objective = "Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 Agenten der Todesschatten tötet.", description = "Als Hauptmann des Drachenmals liegt es in Eurem Verantwortungsbereich, sämtliche Unternehmungen der Brennenden Legion in der Scherbenwelt auszulöschen. Es ist Eure Pflicht, die zum Schweigen zu bringen, die sich Fürst Illidan widersetzen!\n\nDie Dämonen versuchen törichterweise das Portal auf der Zwielichthöhe im Westen von Nagrand zu stabilisieren. Sie müssen für ihren Verrat bezahlen. Ihr werdet der Orc sein, der für die Begleichung ihrer Schulden sorgt.\n\nReist zur Zwielichthöhe und vernichtet die dortigen Bewohner. Ihr seid dafür verantwortlich, täglich mindestens einen Angriff auf ihre Stellungen durchzuführen.", progress = nil, completion = "Ausgezeichnete Arbeit, Hauptmann! Fürst Illidan wird von Euren Heldentaten erfahren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11088] = {title = "<DEPRECATED>Unravelling Your Training", objective = "Bringt Jonathan LeCraft 10 Zauberfeuerstoff.", description = "Bringt mir eine Menge Zauberfeuerstoff und dann könnt Ihr alles vergessen.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nZauberfeuerschneiderei verlernen"}
MultiLanguageQuestData['de'][11089] = {title = "Die Seelenkanone Reth'hedrons", objective = "Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 2 Teufelsstahlbarren, 1 Adamantitrahmen, 1 Khoriumkraftkern und 1 makellose arkane Essenz bringt.", description = "Reth'hedron herrscht jetzt über die Zwielichthöhe in Nagrand. Ein Eredar von solch großer Macht, der auf diese Welt losgelassen wurde, verheißt nichts Gutes für die Illidari. Ach, uns fehlt es einfach an den benötigten Ressourcen, um Reth'hedron vernichten zu können. Schon gar nicht mit dem Krieg, den die Sha'tar zum Schwarzen Tempel getragen haben. Nein... ich habe einen besseren Plan.\n\nIhr werdet Reth'hedron unterdrücken, ihn zurück durch das Portal des Zwielichts verbannen. Für diesen Zweck muss eine Seelenkanone angefertigt werden.\n\nKehrt zu mir mit den Materialien auf der Liste zurück.", progress = "Habt Ihr die benötigten Bauelemente für die Anfertigung der Seelenkanone?", completion = "&lt;Balthas fügt die Elemente, die Ihr ihm gebracht habt, geschickt zusammen.&gt;\n\nIhr seid jetzt bereit für den zweiten Teil des Plans, Hauptmann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11090] = {title = "Unterdrückt den Unterdrücker", objective = "Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal hat Euch den Auftrag gegeben, die Seelenkanone auf Reth'hedron den Unterdrücker in Nagrand anzuwenden.\n\nBringt auch die Seelenkanone wieder zurück.", description = "<Balthas hält ein fremdartiges Gerät in die Höhe.>\n\nDies ist eine Seelenkanone. Die Auswirkungen können bei der richtigen Abstimmung verheerend sein. Diese ist auf mein Blut abgestimmt. Dasselbe Blut, das auch durch die Adern von Reth'hedron fließt - meinem Bruder. Ja, seine falsche Loyalität wird sein Ende sein.\n\nNehmt die Kanone und fliegt zur Zwielichthöhe im westlichen Nagrand. Findet Reth'hedron und feuert! Ihr müsst auf Eurem Reittier bleiben und Euch in Reichweite befinden, damit die Auswirkungen erfolgreich sind. Behauptet Euch ihm gegenüber und er wird keine andere Wahl haben als zu fliehen!", progress = "Ist es vollbracht?", completion = "Er wird zurückkehren, aber für den Moment hat der Krieg der Legion gegen Fürst Illidan eine Schwäche erfahren. Man wird ihm von Euren Taten berichten, Hauptmann.", rewards = "Tunika des IllidarifürstenBeinschützer der BesinnungHörner der IllidariDisziplinarrute der IllidariIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11091] = {title = "Ein besonderer Dank an Euch", objective = "Sprecht mit Jho'nass in Ogri'la im Schergrat.", description = "Die in unserem Namen auf Euch genommenen Anstrengungen ehren uns. Es gibt da jemanden, den Ihr unbedingt kennenlernen solltet.\n\nJho'nass ist unser bester Rüstmeister. Er verwaltet eine ganze Reihe von auserlesenen Waren, die nur den engsten Verbündeten von Ogri'la zum Kauf angeboten werden.\n\nIhr seid ein solcher Verbündeter, <Name>.\n\nWenn Ihr etwas Zeit erübrigen könnt, solltet Ihr ihn unbedingt aufsuchen. Soweit wir wissen, hat er, als Zeichen unserer Dankbarkeit, eine Kleinigkeit für Euch vorbereitet.", progress = nil, completion = "Hey, Mann, das ist toll! Wir haben viel von Euren guten Taten gehört. Das ist fantastisch. Wir haben da so ein Gefühl, dass Ihr für Ogri'la alles zum Guten wenden werdet. Ihr werdet uns beschützen und alles wird heiter und sonnig!\n\nHier, nehmt das. Es ist ein kleines Überlebenspaket, dass wir zum Dank für Euch zusammengestellt haben.\n\nWerft doch bitte einen Blick auf unsere Waren. Wir haben eine reichhaltige Auswahl der erlesensten Gegenstände, von denen Euch sicherlich das eine oder andere Stück interessieren wird.", rewards = "Ihr bekommt:\n\nÜberlebenspaket von Ogri'la"}
MultiLanguageQuestData['de'][11092] = {title = "Glück auf, Kommandant!", objective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", description = "Hauptmann <Name>!\n\n<Zuchtmeister Varkule grüßt Euch.>\n\nOberanführer Mor'ghor möchte, dass Ihr Euch umgehend bei ihm meldet!", progress = nil, completion = "Fürst Illidan hat mich höchstpersönlich mit Eurer Beförderung zum Kommandanten beauftragt! So etwas hat es noch nie gegeben. Ihr seid der Erste des Drachenmals, der solch einen Rang außerhalb des Schwarzen Tempels erlangt hat.", rewards = "Ihr bekommt:\n\nAbzeichen des Kommandanten"}
MultiLanguageQuestData['de'][11093] = {title = "Hungrige Netherrochen", objective = "Benutzt den Netherrochenkäfig in den Wäldern südlich des Schattenwindlagers und erlegt in der Nähe des hungrigen Netherrochens einige Schattenwindhetzer. Kehrt anschließend zu Deesak dem Tierführer der Himmelswache zurück.", description = "Hat man einen Netherrochen erst einmal richtig gezähmt, dann ist er ein loyales und gehorsames Reittier. Unglücklicherweise beansprucht der Krieg bei Skettis unsere Netherrochen über Gebühr.\n\nTäglich müssen wir dutzende von Einsätzen fliegen, sodass die armen Tiere kaum zur Ruhe kommen. Und seit uns auch noch das Futter ausgegangen ist, können die armen Biester froh sein, wenn sie einer der Vogelmenschen erledigt, bevor es der Hunger tut.\n\nWenn Ihr uns zur Hand gehen wollt, nehmt Euch einen unserer Rochen und führt ihn in die Wälder im Süden aus. Sie essen das Fleisch der dort lebenden Schattenwindhetzer, vorausgesetzt, man hat sie gerade frisch erlegt.", progress = "Ihr seid also zurück! Hat sich der Rochen auch gut benommen?", completion = "Vielen Dank &lt;Name&gt;, dass Ihr Euch um den Rochen gekümmert habt. Mit vollem Magen fliegen diese Burschen gleich viel besser. Schließlich sollen unsere Jungs nicht abgeschossen werden, nur weil ihre Netherrochen zum Fliegen zu schwach waren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElixier der erheblichen BeweglichkeitElixier des Adepten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nNetherrochen freigeben\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11094] = {title = "Tötet sie alle!", objective = "Überbringt Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals.", description = "Kommandant <Name>, stillgestanden! Ihr werdet mit einem Bataillon von Himmelsteilern losziehen und den Außenposten der Seher am Fuße der Netherschwingenfelder ausradieren. Ist das Sanktum der Sterne erst einmal zerstört, stehen uns die Verbindungswege zu unseren Posten bei der Stätte der Mondfinsternis und bei der Stätte der Illidari erneut wieder offen.\n\nLos jetzt! Benutzt diese Leuchtpistole, um den Himmelsteilern das Zeichen zum Angriff zu geben!", progress = "Beruhigt Euch, Kind.", completion = "Es war gut, dass Ihr zu uns gekommen seid. Vielleicht können wir diesen Angriff des Drachenmals zu unserem Vorteil nutzen und den Spieß umdrehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11095] = {title = "Kommandant Hobb", objective = "Bringt die Leuchtpistole des Drachenmals zu Kommandant Hobb beim Sanktum der Sterne im Schattenmondtal.", description = "Das Drachenmal wagt es nur dann, uns anzugreifen, wenn unsere Abwehr geschwächt ist. Sie hätten einige Niederlagen hinzunehmen, wenn wir auf ihre Angriffe vorbereitet wären.\n\nIch möchte, dass Ihr sie zu uns führt, <Name>.\n\n<Thelis nickt.>\n\nJa... in eine Falle. Nehmt die Leuchtpistole, die Euch ihr Oberanführer gegeben hat, und bringt sie zu Kommandant Hobb. Er steht direkt außerhalb dieses Gebäudes Wache.", progress = "<Hobb nickt.>", completion = "&lt;Hobb grinst.&gt;\n\nDie tödlichste Falle aller Zeiten...", rewards = nil}
MultiLanguageQuestData['de'][11096] = {title = "Bedrohung von oben", objective = "Tötet bei der Hügelwand 20 Oger der Gordunni und kehrt anschließend zu Yuula in Shattrath zurück.", description = "So, Ihr wollt also der Himmelswache beitreten? Nun, ich weiß, dass Ihr fliegen könnt, aber vermögt Ihr auch zu kämpfen?\n\nDie Himmelswache hat einst geschworen, Shattrath vor allen drohenden Gefahren, egal ob nah oder fern, zu schützen. Die bei der Hügelwand im Norden lebenden Oger der Gordunni stellen eine unmittelbare Bedrohung für uns dar.\n\nEs erwies sich als sehr schwer für unsere Bodentruppen, die Oger zu erreichen. Hier kommen wir ins Spiel. Seht was Ihr tun könnt, um die Oger im Zaum zu halten.", progress = nil, completion = "Gute Arbeit, Fliegerass! Ich habe das Gefühl, dass Ihr hier sehr gut hineinpasst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11097] = {title = "Die tödlichste Falle aller Zeiten", objective = "Helft Kommandant Hobb und den Sehern bei der Verteidigung des Sanktums der Sterne. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Seher zurück.", description = "Nehmt diese Medaillen der Seher. Mor'ghor wird einen Siegesbeweis sehen wollen, wenn all das hier vorüber ist. Er wird sie als Beute von den gefallenen Soldaten der Seher wiedererkennen.\n\nJetzt gilt es noch das Leuchtsignal abzufeuern, um die Räuber des Drachenmals herbeizurufen. Sobald Ihr bereit seid, werden wir sie niederschmettern. Gebt mir einfach den Befehl.", progress = "Habt Ihr sie mit Euren Fäusten zerschmettert, Kommandant?", completion = "&lt;Mor'ghor lacht.&gt;\n\nHAHA! Ich habe gewusst, dass ich auf Euch zählen kann, Kommandant! Ich möchte, dass Ihr das Sanktum der Sterne mindestens einmal pro Tag überfallt. Sie werden keine andere Wahl haben und das Schattenmondtal verlassen müssen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11098] = {title = "Nach Skettis!", objective = "Bringt das Paket mit Sprengladungen zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis.", description = "Die Hügelwand ist nur eine der vielen Fronten, an denen wir eingesetzt werden. Eine nicht unmittelbare, aber dennoch sehr große Bedrohung lauert hinter den Skethylbergen, in Form der Arakkoastadt Skettis.\n\nVor einigen Monaten entdeckten unsere Späher dort einen massiven Anstieg der Arakkoaaktivitäten. Daraufhin erfolgte eine ganze Reihe von Angriffen auf Shattrath. Seitdem haben wir einige unserer Streitkräfte außerhalb ihrer Stadt stationiert.\n\nNehmt diese Sprengladungen und bringt sie zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis. Sagt ihm einfach, Ihr wäret <der neue Rekrut/die neue Rekrutin>.", progress = "Ihr habt etwas für mich?", completion = "Danke für den Nachschub, wir werden ihn zu verwenden wissen! Ein neuer Rekrut? Dann wollen wir doch mal sehen, aus welchem Holz Ihr geschnitzt seid!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11099] = {title = "Tötet sie alle!", objective = "Überbringt Anachoret Ceyla beim Altar der Sha'tar die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals.", description = "Kommandant <Name>, stillgestanden! Ihr werdet mit einem Bataillon von Himmelsteilern losziehen und den Außenposten der Aldor nordwestlich unseres geliebten Schwarzen Tempels ausradieren. Ist der Altar der Sha'tar erst einmal zerstört, stehen uns die Verbindungswege zu unseren Posten bei der Echsennarbe erneut wieder offen.\n\nLos jetzt! Benutzt diese Leuchtpistole, um den Himmelsteilern das Zeichen zum Angriff zu geben!", progress = "Beruhigt Euch, Kind.", completion = "Es war gut, dass Ihr zu uns gekommen seid. Vielleicht können wir diesen Angriff des Drachenmals zu unserem Vorteil nutzen und den Spieß umdrehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11100] = {title = "Kommandant Arcus", objective = "Bringt die Leuchtpistole des Drachenmals zu Kommandant Arcus beim Altar der Sha'tar im Schattenmondtal.", description = "Das Drachenmal wagt es nur dann, uns anzugreifen, wenn unsere Abwehr geschwächt ist. Sie hätten einige Niederlagen hinzunehmen, wenn wir auf ihre Angriffe vorbereitet wären.\n\nIch möchte, dass Ihr sie zu uns führt, <Name>.\n\n<Ceyla nickt.>\n\nJa... in eine Falle. Nehmt die Leuchtpistole, die Euch ihr Oberanführer gegeben hat, und bringt sie zu Kommandant Arcus. Er steht direkt außerhalb dieses Gebäudes Wache.", progress = "<Arcus nickt.>", completion = "&lt;Arcus grinst.&gt;\n\nDie tödlichste Falle aller Zeiten...", rewards = nil}
MultiLanguageQuestData['de'][11101] = {title = "Die tödlichste Falle aller Zeiten", objective = "Helft Kommandant Arcus und den Aldor bei der Verteidigung des Altars der Sha'tar. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Aldor zurück.", description = "Nehmt diese Medaillen der Aldor. Mor'ghor wird einen Siegesbeweis sehen wollen, wenn all das hier vorüber ist. Er wird sie als Beute von den gefallenen Soldaten der Aldor wiedererkennen.\n\nJetzt gilt es noch das Leuchtsignal abzufeuern, um die Räuber des Drachenmals herbeizurufen. Sobald Ihr bereit seid, werden wir sie niederschmettern. Gebt mir einfach den Befehl.", progress = "Habt Ihr sie mit Euren Fäusten zerschmettert, Kommandant?", completion = "&lt;Mor'ghor lacht.&gt;\n\nHAHA! Ich habe gewusst, dass ich auf Euch zählen kann, Kommandant! Ich möchte, dass Ihr den Altar der Sha'tar mindestens einmal pro Tag überfallt. Sie werden keine andere Wahl haben und das Schattenmondtal verlassen müssen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11102] = {title = "Bomberangriff", objective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", description = "Ihr könnt also wie eine Krähe herumfliegen... ja und! Schon mal etwas am Boden ausradiert, während Ihr geflogen seid? Lust, es mal zu probieren?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und eine Gefahr für Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nimmt, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n&lt;Himmelsoffizier Vanderlip grinst.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBomberangriff: Bei Questabschluss\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11103] = {title = "Nicht mehr Weise", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des ewigen ChampionsBand des ewigen VerteidigersBand des ewigen Bewahrers"}
MultiLanguageQuestData['de'][11104] = {title = "Nicht mehr Bewahrer", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des ewigen ChampionsBand des ewigen VerteidigersBand des ewigen Weisen"}
MultiLanguageQuestData['de'][11105] = {title = "Nicht mehr Held", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des ewigen WeisenBand des ewigen VerteidigersBand des ewigen Bewahrers"}
MultiLanguageQuestData['de'][11106] = {title = "Nicht mehr Verteidiger", objective = "Man kann die Kräfte Eures Ringes neu formen, doch wird es nicht einfach, Eure Auswahl rückgängig zu machen. Seid Ihr sicher, dass Ihr seine momentane Form durch eine andere ersetzen möchtet?", description = nil, progress = "Man kann die Kräfte Eures Ringes neu formen, doch wird es nicht einfach, Eure Auswahl rückgängig zu machen. Seid Ihr sicher, dass Ihr seine momentane Form durch eine andere ersetzen möchtet?", completion = "Es ist ein Leichtes, die Sande der Zeit vorwärts fließen zu lassen. Man kann den Fluss auch umkehren, doch ist dies mit großen Mühen verbunden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des ewigen ChampionsBand des ewigen WeisenBand des ewigen Bewahrers"}
MultiLanguageQuestData['de'][11107] = {title = "Verneigt Euch vor dem Hochlord", objective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", description = "Ich bin der Überbringung einer an Euch gerichteten Nachricht nicht einmal würdig, Sire. Bitte verzeiht dieses ungebührliche Benehmen. Oberanführer Mor'ghor möchte, dass Ihr Euch umgehend bei ihm meldet!", progress = nil, completion = "Ihr seid der erste Hochlord des Drachenmals, &lt;Name&gt;. Der Meister hat beschlossen höchstpersönlich hierher zu kommen, um Euch zu befördern.", rewards = nil}
MultiLanguageQuestData['de'][11108] = {title = "Fürst Illidan Sturmgrimm", objective = "Trefft Euch mit Illidan Sturmgrimm. Solltet Ihr überleben, sucht Barthamus im Unteren Viertel von Shattrath auf.", description = "Kommt, Hochlord <Name>. Illidan höchstpersönlich erwartet Euch!", progress = nil, completion = "Ich war der Erste, wisst Ihr. Das verlassene Kind eines Monsters...\n\n&lt;Barthamus schüttelt seinen Kopf.&gt;\n\nWir haben Euch alles zu verdanken, &lt;Name&gt;. Ganz allein habt Ihr das Reich des Drachenmals zerschmettert und dabei genug Informationen gesammelt, die meine Brüder mehr als ein Leben lang beschäftigen werden.\n\nEs ist zwar nicht viel, aber es gibt da etwas, das wir Euch anbieten können... Ein jeder meines Schwarms hat sich dazu bereit erklärt, Euch bei Euren Abenteuern in der Scherbenwelt zu begleiten. Fragt sie einfach und sie werden mit Euch einen Bund eingehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11109] = {title = "Jorus, der kobaltblaue Drache der Netherschwingen", objective = "Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZügel des kobaltblauen Drachen der Netherschwingen"}
MultiLanguageQuestData['de'][11110] = {title = "Malfas, der lila Drache der Netherschwingen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZügel des lila Drachen der Netherschwingen"}
MultiLanguageQuestData['de'][11111] = {title = "Onyxien, der onyxfarbene Drache der Netherschwingen", objective = "Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZügel des onyxfarbenen Drachen der Netherschwingen"}
MultiLanguageQuestData['de'][11112] = {title = "Suraku, der azurblaue Drache der Netherschwingen", objective = "Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZügel des azurblauen Drachen der Netherschwingen"}
MultiLanguageQuestData['de'][11113] = {title = "Voranaku, der violette Drache der Netherschwingen", objective = "Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZügel des violetten Drachen der Netherschwingen"}
MultiLanguageQuestData['de'][11114] = {title = "Zoya, der viridiangrüne Drache der Netherschwingen", objective = "Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZügel des viridiangrünen Drachen der Netherschwingen"}
MultiLanguageQuestData['de'][11117] = {title = "Fangt die wilden Wolpertinger!", objective = "Goldark Spatzenjäger möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr eine Synthebräubrille tragen müsst, um die Biester sehen zu können.", description = "Da, jetzt. Habt Ihr's gehört? Diese Geräusche in den Hügeln. Das sin' die Wolpertinger! Gerissene Biester sin' das, angelockt vom Duft des Braufests. Ich würd' mir ja gern' ein paar davon fangen, aber ich hab' mir mein Bein aufgeschlagen und kann diese Viecher einfach nich' einholen. Tja, da könnt Ihr mir helfen!\n\nNehmt dieses Netz und werft's über diese kleinen Teufel. Bringt mir fünf der Biester und ich werd' Euch für Eure Mühe belohnen!\n\nOh, eine Sache noch – um die Viecher überhaupt sehen zu können, müsst Ihr eine Synthebräubrille tragen! Sagt mir, falls Ihr eine braucht.", progress = "Na, wart Ihr benebelt genug, um die Viecher zu sehen?", completion = "Na sieh einer an! Da habt Ihr ja 'nen ganzen Packen Wolpertinger gefangen!\n\n&lt;Er nimmt einen herzhaften Schluck aus seinem Maßkrug.&gt;\n\nIch sach' Euch was. Da Ihr so'n fantasch... fantastischer Jäger seid, dürft Ihr eins der Viecher für Euch selbst behalten!", rewards = "Ihr bekommt:\n\nWolpertingerhumpen"}
MultiLanguageQuestData['de'][11118] = {title = "Parade der rosa Elekk", objective = "Reist zu den Biergärten außerhalb von Sturmwind, Darnassus und der Exodar, zappt an jedem Ort drei Elekk und kehrt anschließend zu Goldark Spatzenjäger zurück. Um die rosa Elekk sehen zu können, müsst Ihr eine Synthebräubrille tragen.", description = "Sich zu betrinken ist eine altehrwürdige Tradition auf dem Braufest – es ist schon fast eine Bedingung! Die Sache ist die. Mir wurde berichtet, dass die Feierlichkeiten in ganz Azeroth von Halluzinationen überschattet werden! Das können wir nicht zulassen!\n\nNormale Waffen können diesen Elekk nichts anhaben – sie gehen einfach durch sie hindurch. Nehmt daher dieses fantastische Stück gnomischer Maschinenbaukunst, reist zu den anderen Biergärten und zappt sie ins Nichts. Vergesst nicht, Ihr müsst eine Synthebräubrille tragen, um sie sehen zu können! Sagt es mir einfach, wenn Ihr eine Brille braucht.", progress = "Sind die verdammten rosa Elekk nun endlich verschwunden?", completion = "Gute Arbeit! Rosa Elekks... welch unsinnige Vorstellung!", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11119] = {title = "Angriff auf den Landeplatz von Bash'ir!", objective = "Sprecht mit dem Äthertechnikerlehrling im Außenposten der Himmelswache im Schergrat.", description = "Hey, <Junge/Mädel>! Auf der Suche nach etwas Spaß?\n\nAlle paar Stunden starten meine Äthertechniker einen Angriff auf den Landeplatz von Bash'ir tief im Nordosten des Schergrats. Sie bestehen darauf, dass sie Bash'irs Kristallschmiede nur 'erforschen', aber egal wie man es dreht, es ist eigentlich nichts anderes, als ein Überfall. Wir benutzen die Kristallschmiede, um uns mit neuer Ausrüstung zu versorgen und meistens bleibt noch genug übrig, um einen guten Gewinn herauszuschlagen.\n\nGeht 'runter zur Landebahn und sprecht mit dem Äthertechnikerlehrling. Er wird Euch sagen können, wann der nächste Einsatz stattfindet.", progress = nil, completion = "Egal, was Keller dazu meint, ich bevorzuge es, unsere Einsätze als Forschungsexkursionen zu betrachten.\n\nEs stimmt allerdings, dass wir dort Vorräte für die Himmelswache beschaffen, jedenfalls, wenn wir lange genug dort bleiben können.\n\nIhr seht so aus, als wäret Ihr bereit, uns den Rücken gegen die Astralen freizuhalten. Wenn Ihr uns die Astralen lange genug vom Leib haltet, werden wir Euch alle zusätzlich an der Kristallschmiede hergestellten Gegenstände zum Verkauf anbieten, also bringt Eure Apexissplitter und Kristalle mit!\n\nWir ziehen in 0 |4Minute:Minuten; los.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11120] = {title = "Parade der rosa Elekk", objective = "Reist zu den Biergärten außerhalb von Silbermond, Donnerfels und Unterstadt, zappt an jedem Ort drei Elekk und kehrt anschließend zu Glodrak Jägerspatz zurück. Um die rosa Elekk sehen zu können, müsst Ihr eine Synthebräubrille tragen.", description = "Schaut doch, wir verdienen hier unser Geld. Betrunkene Leute? Das ist ein ziemlich gutes Geschäft. Es gibt da allerdings eine Sache, die einem die Umsätze völlig vermiest – Halluzinationen. Ich sag's Euch, meine Jungs berichten mir, dass die Saufbo-, äh, ehrenwerten Kunden überall rosa Elekk sehen.\n\nIch kann keine beunruhigten Kunden gebrauchen. Hier, nehmt das, reist zu den anderen Biergärten und kümmert Euch für mich um die Angelegenheit, ja? Achtet darauf, dass Ihr eine Synthebräubrille tragt! Sagt es mir einfach, wenn Ihr eine Brille braucht.", progress = "Ihr räumt das kleine Problem, von dem ich Euch erzählt habe, doch aus dem Weg, oder?", completion = "Das habt Ihr gut gemacht, Kindchen. Hier, nehmt dies als Lohn für Eure Arbeit.", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11121] = {title = "DAILY TEST QUEST (RAID)", objective = "Sprecht mit <QUESTGIVER> in <AREA>.Sucht<QUESTGIVER> in <LOCATION>. Sie/er hat eine schwierige Aufgabe für Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Sucht<QUESTGIVER> in <LOCATION>. Sie/er hat eine schwierige Aufgabe für Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11122] = {title = "Hin und zurück", objective = "Holt ein Fässchen von Flynn Feuerbräu in Kharanos und bringt es zu Pol Bernruh zurück. Wenn Ihr Euren Widder verliert, könnt Ihr Neill Ramstein nach Ersatz fragen.", description = "Ihr wollt also beim Braufest aushelfen? Ich habe die perfekte Aufgabe für Euch. Ich werde Euch auf einen meiner Rennwidder setzen und nach Kharanos reiten lassen. Es gibt da ein paar Fässchen, die ich abholen muss. \n\nFlynn Feuerbräu wartet auf einem Hügel neben einem Stapel mit Fässchen. Sobald Ihr nahe genug seid, wird er Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es Pol Bernruh zu. Ihr könnt immer nur ein Fässchen gleichzeitig tragen. \n\nSeid Ihr bereit?", progress = nil, completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist und die Dunkeleisenzwerge immer wieder angreifen, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nSo, jetzt muss ich Euch erst einmal für Eure Arbeit bezahlen. Hier sind Eure Biermarken, viel Spaß auf dem Braufest!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11123] = {title = "Untersuchung der Ruinen", objective = "Sprecht mit Inspektor Tarem beim Gasthaus \"Zur Süßen Ruh\".", description = "Der arme James, er ist nie ganz über die Zerstörung des Gasthauses \"Zur Süßen Ruh\" und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Monster, die dafür verantwortlich sind, zu finden.\n\nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertigwerden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.\n\nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig, auf Eurer Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.", progress = nil, completion = "Es freut mich, dass Hauptmann Mumm endlich auch andere mit dieser Untersuchung beauftragt.\n\nIch habe diesen Bereich mit reflektierendem Puder abgestaubt. Verdächtige Gegenstände und Hinweise werden dadurch sichtbar. Ihr könnt Euch also wesentlich leichter auf Eure Bemühungen konzentrieren. Seht Euch alles an, was der Staub zum Leuchten gebracht hat.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReflektierender Staub\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11124] = {title = "Untersuchung der Ruinen", objective = "Untersucht das Gasthaus \"Zur Süßen Ruh\" an der Grenze zwischen dem Brachland und den Düstermarschen.", description = "Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses \"Zur Süßen Ruh\" stoßen.\n\nTheramore hat einen Ermittlungsbeamten entsendet, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Ich habe einen meiner Männer als Spion dorthin abkommandiert und ich möchte mich bei dieser Untersuchung nicht auf die Kompetenz dieser Menschen verlassen.\n\nEgal was Ihr findet, gebt nicht einmal einen kleinen Fetzen davon an den Ermittlungsbeamten weiter. Wir kümmern uns selbst darum.", progress = nil, completion = "&lt;Der Inspektor betrachtet Euch mit Misstrauen.&gt;\n\nMan hat mir gesagt, dass Ihr mir bei dieser Untersuchung... helfen werdet. Nun gut.\n\nIch habe dieses Puder verwendet, um die Ruinen nach Hinweisen abzusuchen, die uns beim Identifizieren der Täter behilflich sein könnten. Der Staub bringt alles zum Leuchten, was bei dem Überfall eine Rolle gespielt hat. Nur zu, untersucht alles, was verdächtig erscheint.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReflektierender Staub\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11126] = {title = "Verräter unter uns", objective = "Konfrontiert 5 Aufwiegler der Deserteure und kehrt zu Calia Hastings nahe der Docks in Theramore zurück.", description = "Schön, Euch zu sehen, <Klasse>. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.\n\nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.\n\nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich glaube, wir haben sie überrascht. Ihre Agenten wähnten sich innerhalb der Stadt vermutlich in Sicherheit.\n\nMit der Zeit werden die Aufwiegler zurückkehren und ihre Lügen wieder verbreiten. Wir werden die Zeit, die Ihr uns verschafft habt, nutzen, um die Deserteure weiter auszusperren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11128] = {title = "Propagandakrieg", objective = "Bringt das Propagandamaterial der Deserteure zu Calia Hastings nahe der Docks in Theramore.", description = "Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure scheinbar auf einem Schiff zu den Docks geschmuggelt haben.\n\nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kajüte des Kapitäns.", progress = "Konntet Ihr die Propagandahandzettel finden und in Beschlag nehmen?", completion = "&lt;Die SI:7-Agentin nickt zustimmend.&gt;\n\nAusgezeichnet. Jetzt müssen wir die Deserteure nur noch diskreditieren, damit sie in Theramore nie wieder Fuß fassen können. Ich weiß auch schon wie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11129] = {title = "Kyle wird vermisst!", objective = "Ahab Weizhuf beim Dorf der Bluthufe in Mulgore möchte, dass Ihr seinen geliebten Hund Kyle den Wilden füttert.\n\nFüttert Kyle mit zartem Schreiterfleisch und kehrt anschließend zu Ahab Weizhuf zurück.", description = "Helft mir, <Name>! Mein geliebter Hund Kyle ist mir weggelaufen. Ich weiß nur, dass er irgendwo in der Nähe des Dorfes der Bluthufe einsam und hungrig herumstreunt.\n\nWürdet Ihr ihn für mich finden und füttern? Wenn er erst einmal etwas gefressen hat, wird er sich wieder beruhigen und nach Hause zurückkehren.\n\nUm ihn zu füttern, müsst Ihr etwas zu Essen finden. Schreiterfleisch mag er besonders gerne. Geht einfach Richtung Osten, dort solltet Ihr genügend Schreiter finden. Erlegt einen und bringt sein saftiges Fleisch zu Kyle. Wenn Ihr Kyle im Dorf antrefft, müsst Ihr das Fleisch nur auf den Boden legen und er wird zu Euch kommen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Nachdem er gefressen hatte, kam Kyle sofort nach Hause und hat sich schlafen gelegt. Vielen Dank für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11130] = {title = "Oh, es glitzert!", objective = "Gaunah möchte, dass Ihr Gaunahs Notiz zu Budd in den Geisterlanden, direkt außerhalb von Zul'Aman, bringt.", description = "Nur keine Scheu, <Mann/Süße>! Lasst den alten Gaunah mal einen Blick auf Eure Klunker werfen...\n\nHmm. Ja, nicht schlecht, aber das Zeug könnte besser sein. Viel, viel besser.\n\n<Gaunah kommt näher und flüstert.>\n\nSchätze von unschätzbarem Wert lassen sich überall finden, <Name>, man muss nur wissen wo! Heute ist Euer Glückstag! Ich kenne da einen Typen, der Euch zu mehr Reichtümern verhelfen kann, als Ihr jemals tragen könntet.\n\nStattet meinem alten Kumpel Budd in der Nähe von Zul'Aman einen Besuch ab und zeigt ihm das hier. Sagt ihm, dass der alte Gaunah Euch geschickt hat, dann wird er Euch bei seinem neuen Projekt mit einsteigen lassen.", progress = "<Budd beäugt die Notiz misstrauisch.>\n\nWas habt Ihr da, <Klasse>?", completion = "&lt;Budd liest die Notiz.&gt;\n\nAhh! Ein Freund von Gaunah? Willkommen!\n\nIhr kommt genau richtig, mein Freund. Wie es das Schicksal so will, habe ich gerade erst meine Kollegen verloren. Tragisch, wirklich, aber außergewöhnliche Belohnungen haben oft ihren Preis. Lasst uns nicht zu sehr ans Negative denken!\n\nIhr habt sicherlich schon von meinen zahlreichen Ausbeuten und Entdeckungen gehört. Nun, das war alles nichts im Vergleich zu dem hier! Ich sage es Euch, wir sind nahe dran, hier in Zul'Aman Geschichte zu schreiben. Ihr hattet das Glück, rechtzeitig zu kommen, um auf der untersten Ebene dabei zu sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11131] = {title = "Löscht das Feuer!", objective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", description = "Ihr müsst uns helfen! Der kopflose Reiter greift das Dorf an. Überall brennen Feuer! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, <Name>, schließt Euch der Brandwache an. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund, der näher bei den Flammen steht, weiterreichen. Wenn Ihr alle Feuer löscht, könnt Ihr uns vielleicht noch retten!", progress = "<Name>, Ihr hattet geschworen, die Kinder zu retten!", completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", rewards = "Ihr bekommt:\n\nSüßes SauresGewichtige KürbislaterneKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11132] = {title = "Versprechen, Versprechen...", objective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr bei Hohepriester Nalorakks Terrasse in Zul'Aman nach seiner Karte sucht.", description = "Meine Theorien bestätigen die Gerüchte, dass in Zul'Aman sagenhafte Schätze zu finden sind. Das bedeutet Reittiere und Anwesen für alle!\n\nNun ja, eins nach dem anderen. Ihr müsst Euch Euren Anteil natürlich verdienen...\n\nUnsere anfänglichen Bemühungen haben uns hier doch nicht so weit gebracht, wie ich es mir erhofft hatte. Tatsächlich sieht es so aus, dass meine Karte, und die Tagelöhner, denen ich sie geliehen habe, verschwunden sind. Sie sind aufgebrochen, um einen Troll namens Nalorakk zu jagen. Ich kann zwar die Gruppe ersetzen, aber ich brauche diese Karte!\n\nSolltet Ihr diese Aufgabe bewältigen, dann wird man von Euch sagen, dass Ihr derjenige wart, der Budd Winterhäldler geholfen hat, die Geheimnisse von Zul'Aman zu lüften!", progress = "Ah, wenn das nicht <Name> ist!\n\nHabt Ihr meine Karte ausfindig gemacht?", completion = "&lt;Budd scheint etwas geschockt zu sein.&gt;\n\nOh? Ihr habt sie gefunden?\n\nÄhm, ich meine, natürlich habt Ihr das! Gut gemacht, &lt;Klasse&gt;.\n\nLasst mal sehen, ob ich etwas Kleines für Euch habe... ahh, ja, das könnte passen.", rewards = "Ihr bekommt:\n\nZerlumpter Beutel aus Hexerstoff"}
MultiLanguageQuestData['de'][11133] = {title = "Diskreditierung der Deserteure", objective = "Calia Hastings möchte, dass Ihr verfälschte Handzettel an 6 Wachen von Theramore verteilt. Erstattet ihr anschließend Bericht nahe der Docks in Theramore.", description = "Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.\n\nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals wieder Fuß zu fassen.\n\n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>\n\nFangt doch schon einmal an, während ich den nächsten Schritt plane.", progress = "Ich dachte, ich hätte Gelächter bei den Kasernen gehört. Habt Ihr die Handzettel verteilt, die ich Euch gegeben habe?", completion = "&lt;Calia kichert, als Ihr von der Reaktion der Wachen auf das Propagandamaterial berichtet.&gt;\n\nGenau wie ich gehofft hatte! Ich bin mir sicher, dass jeder Agent der Deserteure, der versucht Theramore zu infiltrieren, sofort ausgelacht wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11134] = {title = "Das Ende der Deserteure", objective = "Nehmt Gavis Grauschild gefangen und erstattet anschließend Bericht bei Calia Hastings nahe der Docks in Theramore.", description = "Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.\n\nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.", progress = nil, completion = "Gavis' Forderung ist nicht so haarsträubend wie sie scheint. Wenn man sie richtig behandelt, gelingt es Lady Jaina vielleicht sogar die Deserteure wieder in unsere Gemeinschaft zu integrieren. Doch diese Entscheidung obliegt alleine ihr.\n\nEs war mir eine große Freude mit Euch zu arbeiten, &lt;Name&gt;! Ohne Eure Hilfe wäre die gesamte Operation sicherlich nicht halb so glatt gelaufen. Ich werde Euch in meinem Bericht an Sturmwind lobend erwähnen, so dass alle wissen, dass es Euer Einsatz war, der der Bedrohnung durch die Deserteure ein Ende gesetzt hat.", rewards = "GesellengugelStiefel des ScharmützlersArmbrust des SöldnersGesellenhelmPrachtmeerumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11135] = {title = "Der kopflose Reiter", objective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", description = "Der kopflose Reiter wurde zwar vertrieben, aber solange die Schlotternächte noch andauern, wird er wiederkehren. <Name>, befreit uns von diesem Leid und dem wahnsinnigen Treiben des Kopflosen. Stellt Euch dem Reiter, wenn er und sein Kopf vereint sind, und vernichtet ihn!\n\nEr haust tief im Unglückseligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Findet seinen Kürbisschrein und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nGeht, <Name>. Möge das Licht Euch immer beistehen.", progress = nil, completion = "Der Ursprung dieses Schreins ist unbekannt, aber es besteht kein Zweifel, wem hier gehuldigt wird...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11136] = {title = "Beunruhigende Berichte", objective = "Erstattet Hauptmann Wymor bei der Späherwacht Bericht.", description = "Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.\n\nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.", progress = nil, completion = "&lt;Der Hauptmann versucht ganz offensichtlich Eure Fähigkeiten einzuschätzen.&gt;\n\nIhr habt also von dem Schiffswrack an der Küste gehört? Gut, ich könnte noch etwas Hilfe gebrauchen, um meinen Verdacht gegenüber den Überlebenden zu bestätigen. Willkommen an Bord, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11137] = {title = "Defias in den Düstermarschen?", objective = "Besorgt Euch die Befehle der Defias von Garn Mathers und bringt sie zu Hauptmann Wymor bei der Späherwacht.", description = "Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden auch alle rote Kopftücher!\n\nDie Defias sind Handwerker und Zunftgenossen, keine Seefahrer. Was haben sie bei einem Schiffswrack auf einem Kontinent, der sie nicht interessiert, zu suchen?\n\nMan sagt, ihr Anführer residiert auf einer großen Insel, die nicht weit von der Küste entfernt, nordöstlich des Turms liegt. Tötet ihn und nehmt alle Dokumente an Euch, die Ihr in seinem Besitz findet.", progress = "Konntet Ihr ihren Anführer finden?", completion = "&lt;Hauptmann Wymor nimmt die Befehle von Euch entgegen und liest sie.&gt;\n\nWas in aller Welt könnte mit 'Kostbare Fracht' gemeint sein? Die Defias haben zwar kleinere Schmuggeleien im Land von Sturmwind betrieben, aber dies hier ist ganz offensichtlich eine Nummer zu groß für sie. Die Sprache in diesen Befehlen lässt auf einen wohlhabenden oder adligen Herren schließen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11138] = {title = "Renn McGill", objective = "Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe der Schreckensmoorküste.", description = "Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.\n\nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.\n\nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.", progress = "Seid gegrüßt, <Klasse>. Was führt Euch hierher?", completion = "&lt;Renn sieht sich die Befehle an.&gt;\n\nEs war also eine kostbare Fracht an Bord! Wir müssen sie finden, bevor sie von den Defias geborgen wird. Diese Kerle sind zwar keine Taucher, aber wir werden Teile ihrer Ausrüstungen benötigen, wenn Ihr mir bei der Bergung der Fracht behilflich sein wollt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11139] = {title = "Tauchausrüstung aus zweiter Hand", objective = "Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in den Düstermarschen.", description = "Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mithilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese \"Leihgabe\" kommt.\n\nSucht diese Insel nach einer Kiste mit einer Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!", progress = "Mal sehen, was Ihr Euch von den Defias \"borgen\" konntet.", completion = "Na super, die Ausrüstung ist in einem weitaus schlimmeren Zustand, als ich befürchtet hatte... und das Werkzeug!\n\nNun gut, ich habe Euch versprochen, das Ganze wieder funktionstüchtig zu machen, also fange ich mal besser mit der Arbeit an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11140] = {title = "Bergt die Fracht!", objective = "Bringt 6 geborgene Geldkassetten zu Renn McGill in den Düstermarschen.", description = "Nun, ich konnte die Ausrüstung so reparieren, dass Ihr eine Weile damit tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.\n\nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Tauchhelm funktioniert, solltet Ihr versuchen, Teile des Wracks auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Diese Hydras sind gefährlich.", progress = "Konntet Ihr bei Eurer Suche nach Wrackteilen etwas über die Fracht der Defias herausfinden?", completion = "&lt;Renn durchstöbert den Inhalt der Geldkassetten, die Ihr geborgen habt.&gt;\n\nGute Arbeit. Mal sehen, ob wir Eure 'Kostbare Fracht' hier drin finden...", rewards = "Purpurrote BarbuteFleischreißerSchwert des MatrosenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11141] = {title = "Jaina muss davon erfahren", objective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", description = "Ihr müsst Lady Jaina sofort von Eurem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann stellt sich die Frage, wer es war und ob diese Person noch am Leben ist!\n\nEines ist jedoch sicher, <Name>. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.", progress = nil, completion = "Ihr und Renn habt ausgezeichnete Arbeit geleistet. Danke, dass Ihr diese Informationen ans Licht und sofort zu mir gebracht habt. Es bestehen keine Zweifel, die Defias haben einen finsteren Plan ausgeheckt und wollen gegen Sturmwind und seine Verbündeten vorgehen. Der Aufwand dieses Unterfangens übersteigt alle bisherigen Operationen der Defias. Sie müssen irgendwo einen wohlhabenden Gönner haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11142] = {title = "Beobachtet die Insel Alcaz", objective = "Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten. Sprecht mit Lady Jaina Prachtmeer in Theramore, wenn Ihr die Beobachtung abgeschlossen habt.", description = "Offenbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Um dort hinein zu kommen, bräuchten wir allerdings eine ganze Brigade von Soldaten.\n\nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.\n\nDie Insel birgt den Schlüssel zum Geheimnis darüber, in wie fern die Defias in dieser Entführung verwickelt sind.", progress = nil, completion = "&lt;Lady Jaina hört sich Euren Bericht über die Beobachtung aufmerksam an.&gt;\n\nEin Runenkreis, Drachkin? Die Defias haben mit Sicherheit unabhängige Magier in ihren Reihen, aber niemanden, der mächtig genug wäre, um von derartigen Dingen Gebrauch zu machen!\n\nWarum sollten schwarze Drachkin Interesse an einer Insel voller Naga haben? Es gibt viele unbeantwortete Fragen, aber eines ist sicher: die Defias haben einen mächtigen Verbündeten aus den oberen Rängen der Allianz.", rewards = "Handgelenksschützer des BogenschützenGleißende SchuppenbrustplatteJuwelenbesetzter DolchSumpfgasstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11143] = {title = "Der entscheidende Grimmweis", objective = "Erstattet Hauptmann Darill bei der Nordwacht Bericht.", description = "Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses \"Zur Süßen Ruh\" gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.\n\nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen Zufall. Bitte geht und sprecht mit Hauptmann Darill, er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf Richtung Norden zur Nordwacht. Es ist der zweite Außenposten entlang der Straße.", progress = nil, completion = "Hauptmann Mumm vermutet, dass die Grimmtotem hinter der Zerstörung des Gasthauses Zur süßen Ruh stecken? Sie würden zwar auf meiner Liste der Verdächtigen nicht ganz oben stehen, aber wenn Hauptmann Mumm Euch hierher geschickt hat, um dieser Spur nachzugehen, dann wird er schon seine Gründe haben. Wie dem auch sei, die Grimmtotem sind uns schon seit einer ganzen Weile ein Dorn im Auge und wir freuen uns über jede Unterstützung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11144] = {title = "Bestätigung des Verdachts", objective = "Bringt die Schlachtpläne der Grimmtotem zu Hauptmann Darill bei der Nordwacht.", description = "Die Grimmtotem sind vielleicht der kriegerischste Klan der Tauren, aber sie sind keineswegs unorganisiert. Sollten sie das Gasthaus \"Zur Süßen Ruh\" wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.\n\nIm Nordwesten liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben sie als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, ich bin mir jedoch ganz sicher, dass Ihr dort auch die Befehle finden werdet. Sucht bei den Ältesten im Dorf nach dem Verbleib der Pläne.", progress = "Konntet Ihr die Pläne aufspüren?", completion = "&lt;Hauptmann Darill wirft einen Blick auf die Schlachtpläne.&gt;\n\nIch würde sagen, das ist eindeutig genug. Sie haben sich dazu entschlossen, die Siedlungen der Menschen hier in dieser Gegend zu bekämpfen. Ich bin überzeugt, dass Theramore ihr nächstes Ziel ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11145] = {title = "Gefangene der Grimmtotem", objective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 5 Gefangene von Theramore befreit.", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, <Klasse>, aber bringt mir meine Männer lebend zurück.", progress = nil, completion = "Die befreiten Gefangenen kehren bereits aus dem Dorf der Schwarzhufe zurück. Die Informationen, die sie dem Hauptmann geben können, werden uns im nächsten Kampf gegen die Grimmtotem einen Vorteil verschaffen.\n\nIhr habt meinen Dank und den meiner Männer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11146] = {title = "Raptorenfänger", objective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 6 Raptoren einfangt. Ihr könnt entweder Blutsumpfraptoren oder Blutsumpfkreischer einfangen.", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. Ich an Eurer Stelle würde sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf.", progress = "Habt Ihr diese Raptoren schon eingefangen?", completion = "Scheint, als hättet Ihr ein paar Kratzer abbekommen! Auf jeden Fall seid Ihr in einer wesentlich besseren Verfassung als es die Grimmtotem sein werden, nachdem wir unsere neuen Raptorenfreunde auf sie losgelassen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11147] = {title = "Lasst die Raptoren los", objective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr den Raptorenköder bei der Windmühle im Dorf der Schwarzhufe platziert.", description = "Jetzt, da wir unsere Raptoren haben, besteht unser nächster Schritt darin, sie für einen Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem... nun, eigentlich ist es ja auch völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren werden sich um den Rest kümmern.", progress = nil, completion = "&lt;Der Unteroffzier versucht erst gar nicht sein Grinsen zu unterdrücken.&gt;\n\nGut, damit werden sie wohl den einen oder anderen Überfall aussetzen müssen.", rewards = "WappenschulterschutzAuf Euch wartet eine dieser Belohnungen:\n\nBuch des AdeptenAnhänger der Wildheit\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11148] = {title = "Waffen der Grimmtotem", objective = "Hauptmann Darill bei der Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager im Nordwesten.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen. Ausgehend von der Größe ihrer Angriffstrupps, schätzen wir jedoch, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", progress = "Habt Ihr die Waffen im Dorf der Schwarzhufe erbeuten können?", completion = "&lt;Hauptmann Darill inspiziert die Waffen, die Ihr ihm aus dem Dorf der Schwarzhufe gebracht habt.&gt;\n\nEs gibt keinen Zweifel, sie entsprechen genau der Beschreibung. Allerdings gibt es da ein Problem - diese Waffen wurden nie im Kampf eingesetzt. Das Dorf der Schwarzhufe scheint nicht der einzige Posten der Grimmtotem in den Marschen zu sein.", rewards = "KnochenlangdolchBesonders scharfe AxtBeißende GroßaxtAuf Euch wartet eine dieser Belohnungen:\n\nGlühender Turmalinring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11149] = {title = "Tabethas Unterstützung", objective = "Sprecht mit Tabetha auf ihrem Hof.", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich wüsste aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, im Süden, liegt ein kleines Gehöft, das Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und angesehene Wahrsagerin. Folgt der Straße Richtung Süden bis zu ihrem Hof und bittet sie, Euch bei der Suche nach den Tätern, die für das Massaker beim Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, zu helfen.", progress = nil, completion = "Ihr wollt also, dass ich die Grimmtotem ausfindig mache, ja? Was würdet Ihr sagen, wenn ich der Meinung bin, dass das nicht nötig ist?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11150] = {title = "Brennt den Grollhornposten nieder!", objective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Ich hoffe, dass die Grimmtotem die Botschaft verstanden haben. Jeglicher Versuch, hier wieder aufzukreuzen, wird mit weit mehr als nur einer Fackel bestraft. Dafür werden meine Schüler und ich sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11151] = {title = "Gerechtigkeit im Namen der Familie Hyal", objective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", description = "Die Grimmtotem waren zwar lediglich eine Plage für mich, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um Jim Hyals Familie zu retten, aber vielleicht denken die Grimmtotem demnächst zweimal nach, bevor sie jemanden aus Theramore angreifen.", progress = nil, completion = "&lt;Der Hauptmann hört sich Euren Bericht aufmerksam an.&gt;\n\nWir haben James und seine Familie gerächt, aber selbst das kann den angerichteten Schaden nicht ersetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11152] = {title = "Endlich Frieden", objective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder der Gerechtigkeit überantwortet wurden.\n\n<Hauptmann Mumm fertigt einen kleinen Blumenkranz an.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Steine auf dem Friedhof genau nördlich der Tore von Theramore.", progress = nil, completion = "&lt;Hauptmann Mumm lächelt, als ihr ihm von den Ereignissen beim Grab der Familie Hyal berichtet.&gt;\n\nEs ist gut zu wissen, dass sie es verstehen. Ihr habt ihnen doch nichts von James erzählt, oder?\n\nIch werde ihm die Nachricht von seiner Frau überbringen lassen, aber ich bezweifle, dass er es verstehen wird.", rewards = "Gamaschen des langen WegesBedeckung des ScharmützlersStahlbebänderte HalsbergeSchneide des KampfzauberersStahlverstärkte HalsbergeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11153] = {title = "Durchbrecht die Blockade", objective = "Nehmt Petrovs Splitterbomben und werft sie auf die Piraten. Beseitigt 25 Piraten der Blockade und 10 Kanonen der Blockade. Kehrt zu Bombenschütze Petrov in Westwacht zurück, sobald Ihr den Auftrag erfüllt habt.", description = "Alle unsere Schiffe sind gesunken! Wir benötigen Eure Hilfe, um die Piratenblockade in der Straße der Trümmer zu durchbrechen!\n\nNehmt diese Splitterbomben und lasst Euch vom Zeppelin mitnehmen, den Eggenmeiser uns 'ausgeliehen' hat. Er wird Euch über die Schiffe der Piraten, dieser Gauner, hinwegfliegen und Ihr werdet ihnen die Hölle heiß machen!\n\nWenn Ihr sie nicht in Stücke bomben könnt, dann werden wir die Blockade wohl nie durchbrechen können.", progress = "Wir treffen uns also wieder? Das muss heißen, dass Ihr es geschafft habt! Ihr habt's diesen Fieslingen, diesen Piraten des Nordmeers gezeigt!\n\nStimmt's?", completion = "Das wollte ich hören! Ihr habt was drauf, &lt;Name&gt;, so viel ist klar!\n\nDenkt Ihr, dass Ihr morgen wiederkommen könntet? Bis dahin haben wir neue Splitterbomben. Ich würde Euch ja wieder losschicken, aber mein Gehilfe Feknut ist noch nicht vom Guanosammeln zurück - Fledermausguano. Den brauchen wir für die Bomben.\n\nWieso braucht der eigentlich so lange?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11154] = {title = "Jagt ihnen eine Guanoangst ein!", objective = "Sammelt 10 Stück Dunkelklauenguano ein und bringt sie zu Ingenieur Feknut am Stählernen Tor.", description = "Ihr, ja Ihr... Ich brauche Eure Hilfe!\n\nPetrov hat mich hier hochgeschickt, damit ich Fledermausguano für die Splitterbomben, die er in Westwacht herstellt, sammle. Er hat mich in mein Verderben geschickt!\n\nDie Dunkelklauenfledermäuse hängen im nördlichen Bruchwald herum. Ich werde jedoch keinen Schritt von dieser Plattform machen, außer um nach Hause zu gehen!\n\nAber Ihr... Ihr könntet ihn für mich besorgen! Ja? Och büdde!!\n\nHier, nehmt diese Knallfrösche. Ich denke mir, dass wenn man sie unter den Fledermäusen losgehen lässt, sie sich so erschrecken werden, dass der Guano von alleine kommt!", progress = "Bitte sagt mir, dass Ihr den Dunkelklauenguano habt?!", completion = "Iiih, was stinkt denn da so? Puuh, Ihr seid das! Nun, ich hab' Euch eben eine stinkige Aufgabe gegeben!\n\nDanke schön, &lt;Klasse&gt;. Seid unbesorgt, ich werde das Zeugs zu Petrov bringen, sobald wir von hier wegkommen.\n\n\n\nHabt ihr das gehört, Jungs? Machen wir, dass wir von hier verschwinden!!!", rewards = "EisschlägerbänderEisverkrustetes CapeVerstärkte HauerbalghalsbergeGurt des BlutbinderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11155] = {title = "Schon wieder Schaufelhauersuppe?", objective = "Küchenchefin Schwarzkessel hat Euch gebeten, ihr 6 Schaufelhauerfleisch zu beschaffen. Sie befindet sich in Westwacht.", description = "Nachdem ein Großteil unseres Viehs verschwunden ist, sollten wir uns schnell mit neuen Vorräten eindecken - oder die Bestien in dieser Gegend werden unser kleinstes Problem sein!\n\nDa ich für die Versorgung dieser Meute verantwortlich bin, werde ich Euch nach Osten schicken, um mir etwas Fleisch zu besorgen. Genauer gesagt will ich uns ein wenig Schaufelhauerfleisch zubereiten.\n\nNehmt Euch jedoch vor den Hirschen in Acht... die sind gefährlich!", progress = "Nichts geht über das zarte Fleisch, das man aus der Seite eines Schaufelhauers schneidet!", completion = "Damit werde ich eine feine Mahlzeit für die Jungs auftischen können.\n\n&lt;Die Köchin lehnt sich etwas vor und flüstert Euch ins Ohr.&gt;\n\nHier, mein Junge, nehmt Euch etwas hiervon. Ihr seht so aus, als könntet Ihr etwas mehr auf den Knochen vertragen!", rewards = "Ihr bekommt:\n\nSchaufelhauersuppe"}
MultiLanguageQuestData['de'][11156] = {title = "Räuber des Grollhornpostens", objective = "Tötet 12 Grimmtotem des Grollhornpostens und kehrt zu Lehrling Morlann auf Tabethas Hof zurück.", description = "Die Grimmtotem beim Grollhornposten im Norden werden mit jedem Tag dreister. In der Nacht kann man sie oft von ihren Taten singen hören, wie sie diejenigen vertrieben haben, die sich hier niederlassen wollten.\n\nSie haben fest vor, uns von Tabethas Hof zu vertreiben, obwohl sie schon Generationen von Schülern hier ausgebildet hat. Wir haben den Hof so gut es geht verteidigt, aber Lehrling Garion wurde bei dem letzten Angriff verletzt.\n\nGeht zum Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Die Überfälle müssen ein Ende nehmen.", progress = nil, completion = "&lt;Lehrling Morlann nickt.&gt;\n\nGut. Wie sagt man so schön? Ich werde ihre Gesellschaft nicht missen. Inmitten des Sumpfs würde man sich normalerweise etwas Zurückgezogenheit wünschen, oder nicht?", rewards = "Erdbindertunika der GrimmtotemUmhang des ZerstörersGrollhorngurtAuf Euch wartet eine dieser Belohnungen:\n\nMorlanns anderes SiegelMorlanns Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11157] = {title = "Das Gelege des Bösen", objective = "Zerstört 15 Eier der Protodrachen und 15 Protowelpen. Kehrt danach zu Hauptmann Adams in Westwacht zurück.", description = "<Name>, in dieser Sache vertraue ich nur Euch. Die Protowelpen und Eier der Protodrachen im südöstlich gelegenen brennenden Wald müssen beseitigt werden!\n\nSeitdem wir hier angekommen sind, steht die Glutstätte in Flammen. Da muss irgendeine abartige Magie am Werk sein - und seit Kurzem scheint sie zu wachsen. Meine Männer sagen mir, dass wenn wir nicht schon bald etwas unternehmen, wir in ein paar Wochen vom Feuer umgeben sein werden!\n\nBegebt Euch dorthin und beseitigt die Gefahr, indem Ihr die Protowelpen und die Eier zerstört.", progress = nil, completion = "Gute Arbeit! Mit ein bisschen Glück wird die Vernichtung ihres Geleges und ihrer Welpen die feurigen Bestien vertreiben und verhindern, dass sich das magische Feuer ausbreitet.\n\nWartet... Was ist das für ein Geräusch? Hört sich an, wie das Schlagen von Schwingen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11158] = {title = "Blutsumpffedern", objective = "Bringt 5 Blutsumpffedern zu Brogg in Morastwinkel.", description = "Überrascht Euch Broggs Anwesenheit, <Volk>? Keine Sorge! Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könntet es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für die Zerstörung unserer alten Heimat und den Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um die Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe. Für das Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus dem Blutsumpfbau.", progress = "<Brogg sieht Euch hoffnungsvoll an.>\n\nHabt Ihr Federn für Brogg?", completion = "&lt;Brogg nimmt die Federn entgegen.&gt;\n\nBrogg ist zufrieden mit diesen Federn. Starke Magie. Brogg weiß nicht, wie die Raptoren sie mit Macht erfüllen, doch Raptorenfedern sind für Rituale immer am besten geeignet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11159] = {title = "Geister der Festung der Steinbrecher", objective = "Brogg in Morastwinkel möchte, dass Ihr 10 Geister der Steinbrecher tötet, um sie so ihrer letzten Ruhe zu überantworten.", description = "Brogg hat das Totem fertig gestellt, mit dem Ihr den Geistern seiner Freunde Frieden geben könnt. Als die Drachkin über uns herfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk. Seitdem hoffte er auf einen gemeinsamen Gegenangriff aller überlebenden Steinbrecher.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher im Norden. Verwendet es in der Nähe von Ogerskeletten, um ihre Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", progress = "Brogg muss wissen, ob Ihr den aufgebrachten Geistern der Steinbrecher Frieden geschenkt habt?", completion = "Brogg ist für Eure Hilfe sehr dankbar, auch wenn es Oberanführer Mok'Morokk wohl nie sein wird. Wenigstens können sich die verbliebenen Steinbrecher jetzt auf die Probleme der Lebenden konzentrieren und die Toten ruhen lassen. Jetzt gibt es für Brogg nur noch eine Sache zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11160] = {title = "Das Banner der Steinbrecher", objective = "Beschafft das Banner der Steinbrecher und bringt es Brogg in Morastwinkel.", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort, dem heutigen Flammenbau, aufbewahrt wurde. Brogg braucht das Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben.\n\nDer alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Das Banner befindet sich tief in der Höhle. Seid vorsichtig, <Name>.", progress = "Habt Ihr das Banner der Steinbrecher?", completion = "Ihr habt Broggs Dank, &lt;Name&gt;. Brogg hat mit dem Klanbanner noch große Pläne.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11161] = {title = "Die Essenz der Feindschaft", objective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leiche an. Denkt daran, dass nur tote Drachkin ihre Essenzen freigeben!\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", progress = "Habt Ihr die Essenzen? Brogg braucht sie, um seine toten Freunde zu rächen!", completion = "Ihr habt Broggs Dank, &lt;Name&gt;. Wenn Brogg erst einmal ihre Magie dem Totem hinzugefügt hat, kann er endlich die Geister seiner gefallenen Freunde erlösen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11162] = {title = "Herausforderung für den schwarzen Drachenschwarm", objective = "Stellt das Banner der Steinbrecher nahe des Eingangs zu Onyxias Hort auf, wartet auf ihre Reaktion und kehrt anschließend zu Brogg in Morastwinkel zurück.", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. <Name>, Ihr habt mir sehr dabei geholfen, mich auf diesen Moment vorzubereiten. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr auf eine Höhle trefft, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden Ihr Land zurückerobern!", progress = "Broggs Rache ist nahe!", completion = "&lt;Brogg hört Euch aufmerksam zu, während Ihr ihm die Geschehnisse am Eingang zu Onyxias Hort schildert.&gt;\n\nBrogg vermutete schon, dass Onyxia zu feige ist, um sich Euch persönlich entgegenzustellen. Sie ist keinen Deut besser als der schwarze Drachenschwarm, der auch nur angreift, wenn der Sieg schon sicher ist.\n\nBrogg ist Euch für Eure Hilfe sehr dankbar, &lt;Name&gt;, und er wird nie vergessen, was Ihr für ihn getan habt. Brogg wird weiterhin dafür kämpfen, dass die Steinbrecher zurückerobern, was rechtmäßig ihnen gehört!", rewards = "Übergroße Kapuze der SteinbrecherBroggs KampfharnischRestaurierte HaudraufstulpenBroggs besserer KampfharnischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11163] = {title = "Agentin mit Herz", objective = "Meldet Euch bei Donna Brascoe, um eine Belohnung für Euer Heldentum in Zul'Aman zu erhalten. Donna hält sich momentan in den Geisterlanden, direkt außerhalb von Zul'Aman auf.", description = "<Donna sieht sich um und beginnt zu flüstern.>\n\n<Name>, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", progress = nil, completion = "&lt;Donna sieht sich um und beginnt zu flüstern.&gt;\n\n&lt;Name&gt;, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11164] = {title = "Jäger der verlorenen Hauer", objective = "Prigmon möchte, dass Ihr 10 Hauer eines Waldtrolls von Trollen in Zul'Aman einsammelt. Bringt sie zu ihm bei Budds Lager in den Geisterlanden.", description = "Hey Mann! Du bist neu hier, oder? Kannst du mir einen Gefallen tun?\n\nBudd will seiner Waldtrollverkleidung den letzten Schliff verpass'n. Meinte, dass er schon fast fertig is' und nur noch eine letzte Sache braucht. Hauer.\n\nMeine Kürschnerkünste wär'n hier reine Zeitverschwendung. Trollhauer rauszieh'n... ah, bei so was würde mir sofort schlecht werd'n. \n\nBring mir 10 Trollhauer, ja, Mann?", progress = "Beeilt Euch, Mann!\n\nWenn ich Budd die Hauer nicht bald bringe, lässt er mich seine Maske allein in Zul'Aman testen!", completion = "Ahh... gut, genau danach habe ich gesucht!\n\nHier, der versprochene Lohn, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11165] = {title = "Ein Troll unter Trollen", objective = "Prigmon möchte, dass Ihr seinen Vetter Zungam in Zul'Aman ausfindig macht und ihm zur Seite steht.", description = "Hör zu, Mann, da gibt's noch was anderes, was du für den alten Prigmon tun könntest.\n\nZungam, mein alter Taugenichts von Vetter, steckt in Zul'Aman fest. Er lebt auch noch - ich habe sein Rauchsignal erst letzte Nacht geseh'n!\n\nIch sollte ihn eigentlich verrott'n lass'n, dafür, dass er mich in dieses ganze Schlamassel verwickelt hat... allerdings schuldet er mir noch eine Stange Geld.\n\nTu, was du kannst, um ihn da rauszuhol'n, das Abkassier'n kannste mir überlass'n!", progress = nil, completion = "Ich bin frei!\n\nAls man mich erwischt hat, hat man mir zwar fast alles entrissen, aber hier - nehmt meine letzten Münzen als Dank für Eure Mühe.\n\nWenn Ihr was braucht, helfe ich Euch natürlich jederzeit aus, Mann. Das ist das Mindeste, was ich tun kann....", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11166] = {title = "Das X markiert Euren Untergang!", objective = "Betretet Zul'Aman und erkundet Halazzis Kammer, Jan'alais Plattform und Akil'zons Plattform. Berichtet Budd bei seinem Lager in den Geisterlanden von den Details dieser Bereiche.", description = "Wie konnten diese Narren nur versagen? Ich habe ihnen gesagt, dass sie vorsichtig sein müssen - sogar meine Karte und Verkleidungen habe ich ihnen gegeben, damit sie sich leichter einschleichen können. Ach, was soll's. Das Gute an der Sache ist, dass diese Gelegenheit jetzt Euch und Euren Freunden zuteil wird.\n\nWenn Ihr Euch richtig anstellt, dann seid Ihr auf dem besten Weg, ein Teil meiner Mannschaft zu werden und damit an all dem unermesslichen Ruhm teilzuhaben, der bald mein sein wird. Nicht, dass ich Euch brauchen würde, vergesst das nicht.\n\nEs gibt da noch einige Bereiche auf der Karte, die noch besser erforscht werden müssen, bevor unsere Ausgrabung wirklich beginnen kann...", progress = nil, completion = "&lt;Budd versucht, nicht die Fassung zu verlieren.&gt;\n\nÄh - so, &lt;Name&gt; - es war aber auch an der Zeit, dass Ihr, äh, wieder zurückkehrt. Ja - Ihr haltet das gesamte Unterfangen auf.\n\nNun, dann lasst uns mal die Karte beschriften...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11167] = {title = "Die neue Seuche", objective = "Apotheker Lysander im Hafen der Vergeltung will, dass Ihr 10 unversehrte Behälter aus dem Schiffswrack im Südosten bergt.", description = "Nicht lange nachdem uns Arthas zu dieser elenden Existenz verurteilt hatte, arbeiteten wir in der Königlichen Apothekervereinigung an der Herstellung unserer eigenen Pest. Eine Pest, die alles Fleisch verschlingen würde, ob lebendiges, totes oder untotes.\n\nNun ist uns die Herstellung dieser Pest geglückt und wir sind hier, um sie persönlich an die Geißel zu liefern.\n\nDie Allianz hat das Schiff mit dem letzten Erregerstamm, der in unseren Labors in Unterstadt gezüchtet wurde, abgefangen. Begebt Euch zum Wrack, das von hier aus gesehen im Südosten liegt, und bergt so viele Behälter, wie Ihr nur könnt.", progress = "Konntet Ihr die Behälter bergen, <Name>?", completion = "Schön, dass Ihr unverletzt zurückgekehrt seid. Die Gefahr, dass man beim Hantieren der Behälter infiziert wird, besteht. Vermutlich hätte ich Euch schon zuvor davor warnen sollen.", rewards = "Blauvelts Handschuhe für den besonderen MomentEhrfurchtgebietende WorgfellkappeGeschuppte FlinkfingerhandschuheAntike verstärkte BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11168] = {title = "Die Mischung verstärken", objective = "Bringt Apotheker Lysander im Hafen der Vergeltung im Heulenden Fjord 3 riesige Giftdrüsen von riesigen Gezeitenkrabblern.", description = "Ich habe das Gefühl, dass die lange Reise auf See die Effektivität unserer Pest beeinträchtigt hat. Was wir brauchen ist ein starkes Gift, um die Wirksamkeit des Erregerstamms zu erhöhen.\n\nDie Krabben in der Nähe dieses Strands sind entfernte Verwandte der viel kleineren braunen Gezeitenkrabbler. Die kleinere tropische Art produziert ein paralytisches Gift, das stark genug ist, um einen Oger außer Gefecht zu setzen.\n\nWas größer ist, ist ja bekanntlich besser! Das Gift der viel größeren Drüsen der hier ansässigen Art sollte stärker sein. Bringt mir ein paar!", progress = "Konntet Ihr die Giftdrüsen beschaffen, nach denen ich suche, <Name>?", completion = "Ihr beweist weiterhin Eure Kompetenz, &lt;Name&gt;. Hoffentlich wird dieses Gift genügen, um unsere Pest auf den gewünschten Wirkungsgrad zu bringen.\n\nZumindest sollte es dabei helfen, die Empfänger zu schwächen und sie leichter zu infizieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11169] = {title = "Die Waffe der Grimmtotem", objective = "Lehrling Garion bei Tabethas Hof möchte, dass Ihr das erbeutete Totem an 10 scheckigen Staubsuhlerkrokilisken oder Staubsuhlerdolchrachen ausprobiert.", description = "Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, hatte ich noch ein recht seltsames Totem an mich bringen können, welches unsere Feinde gegen uns eingesetzt haben.\n\nAnscheinend verschießt es im Gefecht Blitze aus wilder Energie. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beherbergen eine ganze Reihe aggressiver, scheckiger Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht die Krokilisken in Reichweite des Totems zu bekämpfen.", progress = "Wart Ihr mit dem Testen des Totems erfolgreich?", completion = "&lt;Der Lehrling hört Euch aufmerksam zu, während Ihr ihm den Verlauf des Experiments schildert.&gt;\n\nEin bisschen Dunst und ein paar Blitze? Das war alles? Hinter dem Totem muss noch mehr stecken! Die Grimmtotem würden so etwas doch nicht mit aufs Schlachtfeld bringen, wenn es keinen Nutzen hat!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11170] = {title = "Test auf See", objective = "Sprecht mit Fledermausführerin Kamilla, nehmt eine Reitfledermaus und fangt die Verstärkungstruppen der Allianz ab. Werft die Seuchenphiolen auf 16 Reservisten der Nordflotte, sobald Ihr Euch in Reichweite befindet.", description = "Wir haben soeben die Nachricht erhalten, dass Verstärkungstruppen auf dem Weg sind, um den Streitkräften der Allianz beizustehen. Sie konnten keinen besseren Zeitpunkt dafür wählen!\n\nWir benötigen dringend Testobjekte und diese Reservisten der Nordflotte sind ideal dafür geeignet!\n\nNehmt diese Seuchenphiolen an Euch und sprecht mit Kamilla, der Fledermausführerin. Sagt ihr, dass Ihr eine Reitfledermaus benötigt, um einen speziellen Auftrag für uns auszuführen.\n\nWerft die Phiolen auf die Verstärkungsflotte, sobald Ihr Euch über dem Meer befindet. Ich kann es kaum erwarten, zu sehen, was dabei herauskommt!", progress = nil, completion = "Hmmpff... die Berichte vom Schlachtfeld sind... nicht ermutigend!", rewards = "Bereifte StulpenAzurkettenhalsbergeSchultern mit WidderhornintarsienAuf Euch wartet eine dieser Belohnungen:\n\nRunenbeschriebener Muschelschalenhalsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11171] = {title = "Hexlord? Pah!", objective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr Hexlord Malacrass in Zul'Aman tötet.", description = "Ausgezeichnet! Meinem großen Auftritt in Zul'Aman steht fast nichts mehr im Weg.\n\nIhr habt gute Arbeit geleistet, <Name>. Ich habe mit meiner Mannschaft gesprochen und sie scheint sich langsam mit Euch anfreunden zu können. Ich würde sagen, dass Ihr schon bald ein festes Mitglied der Gruppe sein könntet. Ihr müsst nur noch eine Sache erledigen - beseitigt diesen Hexlord.\n\nEs ist nichts weiter dabei, wirklich. Knöpft Euch diesen Schuft einfach vor, er wird wahrscheinlich sofort kehrt machen und abhauen. Gebrechlichere, ältere Trolle gleichen ihre Schwächen oft mit einem einschüchternden Titel aus, versteht Ihr?", progress = nil, completion = "Endlich! Jetzt, da der leichte Teil der Arbeit erledigt ist, kann ich wenigstens einen weiteren Meilenstein in der Geschichte setzen. Vorerst muss ich mich aber noch einer kleinen Angelegenheit zuwenden - Euch...\n\nIch fürchte, &lt;Name&gt;, dass es an der Zeit für mich ist, Euch gehen zu lassen. Ich glaube, dass Ihr Eure Leistung hier vollbracht habt, vielleicht seid Ihr sogar an Eure Grenzen gestoßen.\n\nSeid nicht traurig. Immerhin bedarf es für die Teilnahme an solch einem außerordentlichen Unterfangen schon sehr besonderer Individuen, die nicht gleich den Verstand verlieren. Hier, schaut doch mal, das ist ein kleines Andenken für Euch, damit Ihr mich nicht vergesst.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11172] = {title = "Der Zeppelinabsturz", objective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", description = "Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Erst vor ein paar Tagen kam hier eine Abgesandte des Dampfdruckkartells wegen dieser Sache vorbei.\n\nSie war auf der Suche nach Informationen über die Fracht des Zeppelins und dessen Piloten Beezil, aber keiner von uns hat den Absturz wirklich beobachtet. Ich bezweifle, dass sie die Aufräumarbeiten am Wrack und die Bergung der Fracht alleine bewältigen kann.\n\nWenn Ihr etwas Zeit habt, solltet Ihr mal bei Beezils Wrack vorbeischauen. Ihr findet es östlich von hier, in der Nähe der Berge.", progress = nil, completion = "Also haben Euch diese einzelgängerischen Magier hierher geschickt? Wie kann ich sicher sein, dass Ihr auch wirklich vertrauenswürdig seid?\n\nSchätze, ich kann jede Hilfe gebrauchen und eigentlich gibt es hier draußen auch nicht viel, das einen Magier interessieren könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11173] = {title = "Der Reagenziendieb", objective = "Bringt 6 Phiolen Marschengift zu Lehrling Garion bei Tabethas Hof.", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich ihn einfach zu ignorieren, meistens vergebens. Dieses Mal möchte ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Sobald Ihr mir das Gift bringt, werde ich Morlanns Vorräte auffrischen, noch bevor er irgendetwas merkt.", progress = "Habt Ihr das Gift bekommen? Morlann wird jeden Moment bemerken, dass nichts mehr da ist...", completion = "&lt;Lehrling Garion überprüft das Gift.&gt;\n\nAbsolut perfekt! Er wird den Unterschied nie bemerken.", rewards = "Bedeckung des WanderersVerzauberter UmhangErprobter MarschenholzbogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11174] = {title = "Korrosionsschutz", objective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 10 Schlamme auflöst.", description = "Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, sie unter Kontrolle zu halten, werden sie das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann auf keinen Fall mit leeren Händen zurückkehren, <Klasse>! Ihr müsst mir helfen, diese Schlamme aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um es anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", progress = "Habt Ihr irgendwelche Fortschritte bei Eurer Brühschlammerjagd gemacht?", completion = "Es sieht da draußen schon etwas ruhiger aus...\n\nIch schätze, es ist an der Zeit, die Bergungsarbeiten fortzusetzen.", rewards = "Kobaltdurchwirkte HandschuheTunika des MarschenwächtersRostfreier TaillenschutzKorrodierter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11175] = {title = "Meine Tochter", objective = "Der alte Zasterstein hat Euch gebeten, seine Tochter, die Vorarbeiterin Irena Zasterstein, zu finden. Sie sollte sich am Stählernen Tor befinden.", description = "Sagt mir, ist es wahr? Sind die Forscher, die in die Flüsterschlucht hinabgestiegen sind, verrückt geworden?\n\nMeine Tochter ist die Vorarbeiterin der Forscherliga, die Richtung Norden zum Stählernen Tor gezogen ist. Nach all den schrecklichen Ereignissen, die uns in letzter Zeit zugestoßen sind, habe ich Angst um ihre Sicherheit.\n\nIch bitte Euch, <Klasse> - ich bin zu alt, um mich auf die Reise zu machen. Ihr Name ist Irena. Werdet Ihr Euch dorthin begeben und nachsehen, ob es ihr gut geht?", progress = nil, completion = "Grrr. Ich hab's gewusst! Er ist viel zu beschützerisch! Das ist so peinlich.\n\nNicht, dass ich nicht darüber froh wäre, Euch zu sehen... Ich freue mich! Wir alle freuen uns. Wir können Eure Hilfe gebrauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11176] = {title = "An die Arbeit", objective = "Forscherin Irena Zasterstein hat Euch gebeten, mit einem der Chefarchäologen des Stählernen Tores zu sprechen. Diese befinden sich am Stählernen Tor.", description = "Unsere Arbeit hier draußen fängt eigentlich gerade erst an. Aber jetzt, da wir diese Flugmaschinen aus Westwacht geliefert bekommen haben, sollten wir so richtig zum Arbeiten kommen.\n\nDas Problem ist, dass uns nicht genug qualifizierte Piloten zur Verfügung stehen. Und da sich die Situation im nördlich gelegenen Bruchwald verschlimmert, würde ich die Sache hier gerne schnell unter Dach und Fach bringen und dann wieder gen Heimat aufbrechen.\n\nFalls Ihr noch eine Hand frei haben solltet, dann sprecht mit einem meiner Chefarchäologen. Ihr könnt sie in der Nähe der Flugmaschinen im Norden und Süden der Ausgrabungsstätte finden.", progress = nil, completion = "Irena hat Euch hierher geschickt, nicht wahr? Gut, dann haben wir Arbeit für Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11177] = {title = "Der Einsiedler beim Irrlichtanwesen", objective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", description = "Es gibt da einen Burschen, die Einheimischen nennen ihn \"Sumpfauge\" Jarl, der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nDas Irrlichtanwesen befindet sich in der Gegend beim Hexenhügel. Folgt der Straße von Theramore aus in Richtung Nordwesten, Ihr werdet das Anwesen finden, bevor die Straße in Richtung Westen abbiegt.", progress = nil, completion = "Runter von meinem Grundstück... es sei denn, hm, Ihr wollt dem alten \"Sumpfauge\" beim Kochen zur Hand gehen. Was sagt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11178] = {title = "Blut des Kriegsherren", objective = "Bringt Zul'jins Blut zu Budd bei seinem Lager in den Geisterlanden, direkt außerhalb von Zul'Aman.", description = "Ihr begutachtet die Phiole mit dem pulsierenden Blut und Eure Gedanken schweifen zu dem launischen kleinen Mann außerhalb von Zul'Aman.\n\nIhr könnt es kaum erwarten, Budds Gesicht beim Anblick dieser Phiole zu sehen!", progress = "<Budd versucht seinen Unmut bei Eurer Ankunft zu verbergen.>\n\nIhr schon wieder...\n\nWie sage ich es Euch am besten... Ich bin einfach viel zu beschäftigt, als dass ich Euch während meiner Vorbereitungen noch länger zur Seite stehen könnte, <Name>.\n\nGlaubt mir, <Name>, es ist zu Eurem Besten. Vielleicht schafft Ihr es ja, nach vielen Jahren harter Arbeit und mit etwas Glück, Euch selbst einen Namen zu machen.\n\nFalls ja, dann könnt Ihr erzählen, dass alles bei dem unvergleichlichen Budd Winterhäldler begonnen hat!", completion = "Da... das Blut von Zul'jin selbst, sagt Ihr?\n\n&lt;Budd reißt sich zusammen und spricht weiter.&gt;\n\nNun gut, ich weiß diese Geste zu schätzen, &lt;Klasse&gt;, aber ich hätte ihn natürlich selbst mit Leichtigkeit vernichten können. Er wird niemals so furchtbar gewesen sein, wie man in den Legenden sagte. So etwas wird oft völlig übertrieben, Ihr werdet das schon noch verstehen. Wahrscheinlich litt der alte Kerl bereits unter Arthritis!\n\nEgal, ich denke, dass dies das Mindeste war, was Ihr im Gegenzug für meine Güte habt tun können.\n\nVerschwindet jetzt - ich muss diese Phiole loswerden!", rewards = nil}
MultiLanguageQuestData['de'][11179] = {title = "Finlay ist darmlos", objective = "Sammelt 7 Stück makellosen Schattensäblerkatzendarm und kehrt zu Finlay Pfeilmacher zurück. Er befindet sich in Westwacht.", description = "Jetzt seht Euch mal all diese Armbrustschützen an - und wer muss ihre ganzen Waffen instand halten? Ich, Finlay Pfeilmacher!\n\nDer Hauptmann hat meinem Helfer befohlen, sich für den Umzug nach Fort Wildervaar bereitzumachen, und ich habe nicht die Zeit, um allen Katzendarm für ihre Sehnen zu sammeln!\n\n<Klasse>, seid <ein guter Kamerad/eine gute Kameradin> und beschafft mir ein paar Katzendärme. Die Nebelsäbler, die durch den Fjord streifen, werden dafür ausreichen - doch denkt daran, dass Ihr nur die makellosesten Innereien mitbringt! Mit angerissenen Därmen können wir nichts anfangen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11180] = {title = "Was sucht den Hexenhügel heim?", objective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr Informationen von 10 auferstandenen Gebeinen oder auferstandenen Geistern sammelt.", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", progress = "Was habt Ihr von den Spukgeistern erfahren können?", completion = "&lt;Mordant holt ein kleines Blatt Papier und einen Stift hervor und beginnt, sich Notizen über Eure Berichterstattung zu machen.&gt;\n\nIhr konntet herausfinden, dass sich die Geister an diesem Ort auf die Anzahl aller belaufen, die jemals auf diesem Land gelebt haben, und nicht nur auf die vorherigen Besitzer.\n\nEtwas hat sie zu Grunde gerichtet und getötet. Wer der Sache verfällt, erfährt die Wahrheit nicht, bis es zu spät ist. Wir müssen dem Ganzen ein Ende bereiten, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11181] = {title = "Der Hexenfluch", objective = "Bringt 9 Zweige Hexenfluch zu Mordant Grimsby beim Irrlichtanwesen.", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, <Name>. Es könnte unsere letzte Hoffnung sein.", progress = "Konntet Ihr ein paar Pflanzen finden? Wir müssen schnell handeln, bevor das Übel, das hinter dieser Heimsuchung steckt, in dieser Gegend vollends überhand nimmt.", completion = "&lt;Mordant nimmt das Pflanzenbündel von Euch entgegen.&gt;\n\nDiese entsprechen exakt der Beschreibung! Während Eurer Abwesenheit habe ich die Fackel vorbereitet. Jetzt müssen wir die Pflanzen nur noch hier am Ende befestigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11182] = {title = "Ursachen", objective = "Tötet 5 Tierführer der Drachenschinder und Skeld Drachensohn. Geht in die Glutstätte und sucht ein Urtum der Glutstätte auf, falls Ihr das schaffen solltet.", description = "Alles in der Natur strebt nach einem Gleichgewicht -ein Gleichgewicht, das nur dann gestört wird, wenn diejenigen, die nicht mit der Natur im Einklang sind, eingreifen.\n\nIhr verschwendet Eure Kraft, wenn Ihr die Welpen und Drachen tötet. Die eigentlichen Missetäter hinter der Ausbreitung dieser magisch brennenden Wälder sind die vor Kurzem erwachten Vrykul und ihr Gebieter Skeld Drachensohn.\n\nWenn Ihr Blut vergießen wollt, dann fangt mit denen an. Ihr Unterschlupf befindet sich im Süden der Glutstätte.", progress = "Na mein Kleiner, wie steht es im Kampf gegen die Antreiber?", completion = "Schade, dass man ein Raubtier nur mit der Hilfe eines anderen Raubtiers erlegen kann - aber so ist das Gesetz der Natur nun einmal.\n\nVielleicht können die Protodrachen und -welpen jetzt wieder in Frieden leben. Doch angesichts des erneuten Erwachens der Vrykul, bezweifle ich das.", rewards = "Feuersteinverstärkte SchiftungKalteisenarmbindenArkanumgebundene ArmschienenAuf Euch wartet eine dieser Belohnungen:\n\nAbzeichen der Dunkeleisen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11183] = {title = "Die Reinigung des Hexenhügels", objective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr die Fackel am Ende des Docks aufstellt und alles bezwingt, was daraufhin erscheint.", description = "Die Fackel ist fertig. Stellt sie am Ende des Docks auf und seid auf alles gefasst.\n\nIch weiß wirklich nicht, was der Rauch der Fackel bewirken wird... falls überhaupt etwas geschieht. Eigentlich hege ich für gewöhnlich Zweifel an dererlei Hokuspokus, aber wir haben keine andere Wahl. Viel Glück, Ihr und Jarl könnt es brauchen.", progress = "Ist es vorbei?", completion = "Es hat funktioniert?\n\n&lt;Mordant räuspert sich.&gt;\n\nIch meine... es hat funktioniert! Jarl und ich stehen tief in Eurer Schuld, &lt;Name&gt;. Jetzt muss ich mich nur noch um den schlechten Einrichtungsgeschmack meines Freundes kümmern. Ich befürchte, dass das nicht allzu einfach wird.", rewards = "Mordants ReisetunikaGrimsbys greller GurtGeschuppte MarschenlaufschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11184] = {title = "GESUCHT: Schlächterklaue der Gefräßige", objective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch anschließend bei Drazzit Tropfhahn in Morastwinkel.", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden gebeten, den Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn wurde autorisiert, jeden, der der Bedrohung durch Schlächterklaue ein Ende setzt, großzügig zu entlohnen.", progress = nil, completion = "Endlich hat sich jemand um diese Sache gekümmert. Ich dachte schon, dass ich die Belohnung verdreifachen müsste, bevor jemand diesen verdammten Raptor zur Strecke bringt!", rewards = "RaptorbalgbeinschützerSchützende IngenieursgamaschenAuf Euch wartet eine dieser Belohnungen:\n\nRaptoraugenring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11185] = {title = "Brief der Apothekerin", objective = "Bringt den versiegelten Brief zu Andello Porter auf Tabethas Hof.", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, enthält alarmierende Beweise für das enge Bündnis der Grimmtotem mit den neuen Herren von Lordaeron.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nAndello Porter, der SI:7-Agent bei Tabethas Hof, sollte umgehend von diesem Brief erfahren.", progress = "Was habt Ihr da, <Klasse>?", completion = "&lt;Andello liest den Brief, bestürzt über dessen Inhalt.&gt;\n\nDies bestätigt lediglich unseren Verdacht, den wir seit langem über das Zusammenspiel von Horde und den Verlassenen hegen. Mit Hilfe der Magie und den Waffen der Verlassenen würden die Grimmtotem zu einem noch viel gefährlicheren Gegner werden. Das Gleichgewicht der Macht in Kalimdor könnte ernsthaft in Gefahr sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11186] = {title = "Zeichen des Verrats?", objective = "Bringt den versiegelten Brief zu Nazeer Blutlanze in Brackenwall.", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, deutet auf eine geheime Korrespondenz zwischen Unterstadt und den Anführern der Grimmtotem hin.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nVielleicht kann Euch Nazeer Blutlanze in Brackenwall sagen, was mit dieser Information geschehen soll.", progress = "Was habt Ihr da, <Klasse>?", completion = "Wenn es das ist, was es zu sein scheint, dann müssen die Verlassenen eine gute Erklärung dafür finden!\n\nDie Torheiten der Grimmtotem haben die Geduld des Kriegshäuptlings schon seit langem auf die Probe gestellt. Für gewöhnlich war es üblich, dass diese Angelegenheiten unter den &lt;Volk&gt; ausgemacht werden, aber das könnte nun anders aussehen.\n\nEs wird einige Zeit dauern, bis man den Verdächtigungen nachgegangen ist. Sprecht mit niemandem über das, was Ihr heute gesehen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11187] = {title = "Magierleutnant Malister", objective = "Hauptmann Adams möchte, dass Ihr mit seinem Berater Magierleutnant Malister sprecht. Er befindet sich in Westwacht.", description = "DAS IST UNFASSBAR! Die Protodrachen greifen die Wache an!\n\nBestien wie diese, hätten eigentlich davon abgeschreckt werden sollen, als Ihr Euch um ihr Gelege und ihre Welpen gekümmert habt.\n\nIhr habt Euch doch um sie gekümmert, oder?\n\n<Name>, die Situation verlangt direktere Maßnahmen. Sprecht mit meinem Berater Magierleutnant Malister. Er wird Euch das geben, was Ihr benötigt, um diese teuflischen Kreaturen zu erreichen.", progress = nil, completion = "&lt;Malister winkt Euch herbei und flüstert Euch zu.&gt;\n\nIch habe befürchtet, dass so etwas passieren könnte. Ich habe versucht, den Hauptmann von seiner Vorgehensweise abzuraten - doch er ist ein Zwerg der Tat, der ein genaues Bild davon hat, wie die Dinge ablaufen sollen.\n\nLasst uns über die Möglichkeiten sprechen, die uns noch offen bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11188] = {title = "Zwei Untaten...", objective = "Magierleutnant Malister in Westwacht hat Euch damit beauftragt, 3 Protodrachen zu vernichten.", description = "Nun da wir diese Protodrachen aus der Glutstätte verärgert haben, könnten sie dazu neigen, ihre Angriffe auf die Wache fortzuführen. Das darf nicht passieren.\n\nIch tue es zwar nur ungern, auf eine Untat eine weitere folgen zu lassen, aber in diesem Fall sieht es so aus, als müssten wir diese Kreaturen vernichten. Eine bedauerliche Vorgehensweise, aber eine, der wir uns nichtsdestotrotz verpflichten müssen.\n\nNehmt meinen Zauberstab. Ich habe zwar versucht, seine Reichweite zu erhöhen, aber austeilen tut er nicht viel. Was er jedoch kann, ist die Aufmerksamkeit der Protodrachen auf sich zu ziehen.", progress = nil, completion = "&lt;Der Magierleutnant seufzt.&gt;\n\nEine unerfreuliche Sache, so viel ist sicher. Tja, was getan ist, ist getan. Wenn wir Glück haben, werden sich die Welpen in der Glutstätte, die einmal zu Drachen heranwachsen werden, nicht mehr an unsere schändlichen Taten erinnern.\n\nUnd wenn wir ein wenig mehr Glück haben, wird sich dieser magische Wald nicht weiter ausbreiten.\n\nHier, &lt;Name&gt;. Bitte, nehmt dieses Almosen aus unserer Schatzkammer entgegen... für all Eure Mühen. Es ist das Mindeste, was wir tun können.", rewards = "Indigorobe der ErfrischungEisenbeschlagene GamaschenVerschränkter KettengurtWohltuende SchädelkappeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11189] = {title = "Ein letztes Mal", objective = "Eskortiert den Geist von Entdecker Jaren sicher zu Irena Zasterstein. Sie befindet sich am Stählernen Tor im heulenden Fjord.", description = "Tag auch. Bin ich tot? Ich denke schon - ich schwebe ja über meinem eigenen Körper!\n\nOh, welch unglückliche Wendung des Schicksals. Ich wollte gerade um Irenas Hand anhalten, als die Geißel über uns hereinbrach.\n\nIch weiß, dass sie immer noch am Leben ist... Ich kann sie in meinem Herzen fühlen.\n\n<Klasse>, meint Ihr, dass Ihr mich sicher zu ihr hinbringen könntet? Die Geißel kann meinen Geist noch immer sehen und mir zweifellos schreckliche Dinge antun.\n\nIch möchte einen letzten Blick auf ihr wunderschönes Gesicht werfen. Ihr könnt dann für mich sagen, dass ich sie liebe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11190] = {title = "Nicht allen passt dieselbe Größe", objective = "Kanonier Ely hat Euch damit beauftragt, 10 Kanonenkugeln der Westwacht einzusammeln und sie zu ihm zurückzubringen. Er befindet sich in Westwacht.", description = "Na, <Junge/Mädchen> - welches Genie hat denn unsere Kanonen nicht in der Standardgröße gebaut? Jetzt müssen wir spezielle Kanonenkugeln herstellen, um sie aus den Teufelsgeräten zu feuern!\n\nIch wäre Euch wohlgesinnt, solltet Ihr Euch aufmachen und die Kugeln finden, die wir schon verschossen haben. So wie dieser Haufen schießt, werden sie mit Sicherheit überall im Süden und Osten verstreut sein.\n\n<Der Kanonier breitet seine Arme aus, um Euch eine Vorstellung von der Größe der Kanonenkugeln zu geben.>\n\nDas wäre sicherlich schneller, als wenn wir sie neu herstellen würden.", progress = "Unsere Munition hier in der Gegend wird langsam ziemlich knapp, <Klasse>. Unsere Feinde brauchen eins auf die Mütze - ganz besonders Skorn!\n\nHabt Ihr noch mehr Kugeln für uns?", completion = "Oh, seid gesegnet, &lt;Name&gt; - seid gesegnet!\n\nStellt sie doch gleich dort ab, wo Ihr steht. Ich werde einen meiner Jungs schon bald losschicken, um sie zu verladen. Dann müssen wir uns keine Sorgen mehr darum machen, dass uns beim Bombardieren von Skorn die Kugeln ausgehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11191] = {title = "Der alte Leuchtturm", objective = "Sprecht mit Babs Zischeldrill bei dem Leuchtturm auf der Insel östlich von Theramore.", description = "Der alte Leuchtturm draußen im Osten ist schon seit langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, den ganzen Betrieb wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann wesentlich sanfter zu den Docks gelangen. Was kann ich dagegen noch einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", progress = nil, completion = "Gut. Ich kann jede Hilfe gebrauchen. Als Allererstes möchte ich die Lampe wieder zum Leuchten bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11192] = {title = "Drescheröl", objective = "Bringt 4 Behälter mit Drescheröl zu Babs Zischeldrill beim Leuchtturm in der Nähe von Theramore.", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch unelegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Man findet sie genau unterhalb der Docks von Theramore.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", progress = "Konntet Ihr etwas Drescheröl auftreiben?", completion = "Nun, ich habe ja meine Zweifel, aber es ist im Moment eben die einzige Lösung. Sobald das Ganze wieder funktioniert, wird sich sicherlich etwas anderes zum Betreiben der Lampe finden lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11193] = {title = "Heimtückische Bewohner der Tiefe", objective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", progress = "Was darf es heute sein? Der Barsch ist ausgezeichnet.", completion = "Nun ja, mir dieses Buch zukommen zu lassen, war ganz schön aufmerksam von der alten Babs. Ich weiß nicht, ob Ihr ein wenig darin geblättert habt, aber in den Geschichten steckt schon die ein oder andere Wahrheit. Seefahrer erfinden sowas nicht einfach, versteht Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11194] = {title = "Ist das wahr?", objective = "Sprecht mit Nat Pagle bei Nats Angelplatz in den Düstermarschen.", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut aufgelacht habt. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran ist?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr ganz sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in der Tidenbucht, welche südwestlich jenseits der Bucht der Düstermarschen liegt.", progress = nil, completion = "So, Ihr wollt also etwas über Meeresungeheuer wissen? Hmm... na gut, ich hätte da ein Angebot für Euch. Das Ganze beinhaltet aber reichlich Alkohol und Ihr werdet dabei ziemlich in Verlegenheit geraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11195] = {title = "Das Spiel mit der Puppe", objective = "Bringt die zerlumpte Voodoopuppe zu Gaunah in Shattrath.", description = "Ich bin gerührt, <Name>, is' kein Scherz, Mann. Ich kann mich nich' daran erinnern, dass <ein/eine:r> <Volk> Zungam jemals aus der Patsche geholf'n hätte.\n\nDas hier habe ich einem der Wilden weggenomm'n, als man mich festgebund'n hat. Es sieht zwar nich' nach etwas Großartigem aus, aber wenn jemand den Wert einschätz'n kann, dann ist das mein guter alter Freund Gaunah!\n\nSolltest du hier lebend wieder rauskomm'n, dann statte ihm einen Besuch in Shattrath ab, es lohnt sich.", progress = "Hey, <Name>! Ich habe gehört, dass Ihr Euch einen Platz in Budds Mannschaft verschafft habt. Ihr werdet keine Zeit haben, dies zu bereuen, Kumpel, das kann ich Euch versprechen.\n\nWas habt Ihr denn da, Mann?", completion = "Hey, wo habt Ihr denn das her?\n\nNein, nein, sagt's nicht - das stammt vom Hexenfürst persönlich! Jetzt ist mir alles klar. Starkes Mojo! Der Träger dieses Relikts, egal wie oft er schon in Ungnade gefallen sein mag, wird vom Hochadel stets verehrt werden. Unglaublich!\n\n&lt;Als Gaunah die Puppe in die Höhe hält, fällt ein kleiner, rostiger Glücksbringer von deren Hals. Der Troll will ihn gerade wegstecken, aber wendet sich Euch dann mit einem Funkeln in den Augen zu.&gt;\n\nIch habe gerade kein Bares bei mir, Mann, aber nehmt doch bitte das hier...", rewards = "Ihr bekommt:\n\nBezaubertes Juwel der Amani"}
MultiLanguageQuestData['de'][11196] = {title = "Der Kriegsherr der Amani", objective = "Besiegt den neuen Kriegsherrn der Amani, Daakara.", description = "Die Amani haben ihre Streitmacht wiederaufgebaut und einen neuen Kriegsherrn hervorgebracht, der sie anführt, <Name>. Der nennt sich Daakara der Unbesiegbare, aber wir wollen doch mal sehen, ob er seinem Namen gerecht wird.\n\nDu musst erst all seine Handlanger aus dem Weg räumen, bevor du Daakara gegenübertreten kannst. Besieg ihn und bereite den Ambitionen der Zandalari und der Amani ein Ende.", progress = "Dieser neue Kriegsherr muss fallen, bevor die Zandalari hier dauerhaft Fuß fassen können.", completion = "Der Sieg gehört uns, &lt;Name&gt;! Die Zandalari fliehen und ohne die Führung ihres Kriegsherrn werden die Amani bald in interne Streitigkeiten verfallen.", rewards = "Roben der UneinigkeitSchulterstücke des EhrgeizesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11198] = {title = "Bezwingt Tethyr!", objective = "Major Mühlens bei den Docks von Theramore möchte, dass Ihr Tethyr bezwingt.", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Ich muss gestehen, dass ich beim ersten Anblick des Ungeheuers zu zweifeln begann, ob wir die Docks wirklich verteidigen können. Ihr habt Eure Arbeit jedoch bravourös gemeistert!", rewards = "Purpurrote TunikaSchiftung der schnellen WindeGoldener HelmTurm von TheramoreMeeresungeheuerharpuneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11199] = {title = "Meldung bei Kundschafter Wisslich", objective = "Hauptmann Adams möchte, dass Ihr Euch bei Kundschafter Wisslich am Glutspeerturm meldet.", description = "<Name>, nun da man sich diese verdammten Proto-Dinger einmal vorgenommen hat, habe ich eine weitere Aufgabe für Euch.\n\nEiner meiner Kundschafter hat mir von verdächtigen Aktivitäten der Verlassenen im Süden berichtet. Es sieht so aus, als würden sie im Vrykuldorf namens Halgrind ihr Unwesen treiben.\n\nIch möchte, dass Ihr die dortigen Ermittlungen persönlich übernehmt. Sprecht mit Kundschafter Wisslich, findet heraus, was er bisher in Erfahrung bringen konnte und macht dort weiter, wo er aufgehört hat.\n\nEr wurde das letzte Mal am Glutspeerturm gleich westlich von Halgrind gesehen.", progress = nil, completion = "Oh, gut, Hilfe - und genau zur rechten Zeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11200] = {title = "Kein bloßer Zufall", objective = "Krog in Brackenwall möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", description = "Wir haben die Ruinen des Gasthauses so gut es geht nach Beweisen abgesucht. Ich bin beunruhigt, was die Ergebnisse unserer Ermittlungen betrifft, aber wir müssen die Wahrheit erfahren.\n\nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe im Nordosten. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.", progress = "Was konntet Ihr im Dorf der Schwarzhufe finden?", completion = "&lt;Krog betrachtet die Waffen und die Rüstung, die Ihr ihm aus dem Dorf der Schwarzhufe mitgebracht habt.&gt;\n\nDas ist ganz unverkennbar die Arbeit von Mosarn. Ihn weiter auszufragen würde zu viel Aufmerksamkeit erregen. Wie gut, dass wir bei Angelegenheiten mit den Grimmtotem etwas mehr Handlungsfreiheit haben.", rewards = "KnochenlangdolchBesonders scharfe AxtGrimmtotemumhangAuf Euch wartet eine dieser Belohnungen:\n\nGlühender Turmalinring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11201] = {title = "Die Verschwörung der Grimmtotem", objective = "Bringt die Schlachtpläne der Grimmtotem zu Krog in Brackenwall.", description = "Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Hochrangige Vertreter der Grimmtotem hießen bereits Morde und Entführungen gut, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten Ihr nächstes Ziel sein.\n\nDas Dorf der Schwarzhufe im Nordosten, in der Nähe des Blaumoors, ist eine große neue Siedlung der Grimmtotem. Ihre Anführer, die Ältesten, dürften alle Anordnungen von Donnerfels bei sich tragen. Versucht an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.", progress = "Konntet Ihr die Pläne ausfindig machen?", completion = "&lt;Krog überfliegt die Schlachtpläne.&gt;\n\nIch bin mir jetzt ganz sicher, dass die Grimmtotem einen Angriff auf die Menschen planen. Allerdings weiß ich nicht, was ihre Absichten uns gegenüber sind. Die Handlungen der Grimmtotem haben in der Vergangenheit für gespannte Verhältnisse innerhalb der Horde gesorgt, doch der Kriegshäuptling hat die Lage bis jetzt immer entschärft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11202] = {title = "Mission 'Ewige Flamme'", objective = "Kundschafter Wisslich im Glutspeerturm hat vorgeschlagen, dass Ihr mithilfe der Immerbrandfackeln die 4 Pestkessel um Halgrind herum zerstört.", description = "Die Verlassen führen nichts Gutes im Schilde und so wie ich das sehe, spielen diese Pestkessel voller Schlamm dabei eine große Rolle.\n\nIch würde vorschlagen, dass wir sie zerstören, bevor man sie für weitere Zwecke verwenden kann. Ich war einmal so frei, ein paar Fackeln aus der Glutstätte schon bereitzustellen. Die Dinger brennen nun schon seit Tagen!\n\nHier, nehmt. Ich kann sie nicht so gut gebrauchen wie Ihr. Sie werden Euch bei der Zerstörung der Kessel von großem Nutzen sein.", progress = nil, completion = "Fein!\n\nAber was genau war das noch einmal, was Ihr in diesen Kesseln gefunden habt? Wollt Ihr damit sagen, dass die Verlassenen dort unten eine Pest unter den Vrykul verbreiten?", rewards = "Geprägter HermelingurtKnochenverzierte ArmschienenMagdunschiftungRunenplattenhelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11203] = {title = "Sucht Tabetha auf", objective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", description = "Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zum Üben noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für den Angriff auf das Gasthaus verantwortlich sind, noch immer auf freiem Fuß sind.\n\nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.\n\nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.", progress = nil, completion = "&lt;Tabetha lächelt.&gt;\n\nKrog möchte, dass ich die Grimmtotem ausfindig mache, ja? Nun gut, dafür braucht es aber keine Magie.\n\nScheinbar haben wir einen gemeinsamen Feind. Die Grimmtotem haben in der Nähe einen Außenposten errichtet und sind mir und meinen Schülern ein ständiger Dorn im Auge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11204] = {title = "Rückkehr zu Krog", objective = "Sprecht mit Krog in Brackenwall.", description = "Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, detaillierte Informationen zu jedem Stück zu behalten.\n\nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, die Grimmtotem hegen auch eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.", progress = nil, completion = "Er hat bestätigt, dass die Grimmtotem seine besten Kunden sind? Mosarn hat uns weit mehr geholfen als er ahnt. Mit dieser Menge an Hinweisen, die die Grimmtotem belasten, dürften wir unsere Hauptverdächtigen gefunden haben.", rewards = "Purpurrote BarbuteFleischreißerSchwert des MatrosenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11205] = {title = "Brennt den Grollhornposten nieder!", objective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Unsere letzte Botschaft dürfte bei den Grimmtotem angekommen sein.\n\nWas Euch betrifft, so solltet Ihr Eurer Kontaktperson in Brackenwall von Eurem Erfolg berichten. Ich weiß, dass die Zerstörung des Gasthauses Zur süßen Ruh zwischen Horde und Allianz für Spannungen sorgen könnte. Sollten mir Ermittler von Theramore begegnen, werde ich ihne gerne berichten, dass die Grimmtotem eigenständig gehandelt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11206] = {title = "Das Walten der Gerechtigkeit", objective = "Kehrt zu Krog in Brackenwall zurück.", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden. Aber ich habe den Eindruck, dass Euch das vermutlich nicht kümmert. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus \"Zur Süßen Ruh\" bestraft.\n\nGeht und sagt Eurem Vorgesetzten, dass seiner Rache genüge getan wurde.", progress = nil, completion = "&lt;Krog hört sich Euren Bericht an.&gt;\n\nIch bin beeindruckt, &lt;Name&gt;. Ich hatte vermutet, dass die verbrecherischen Grimmtotem nicht so einfach auszumachen sind. \n\nTabethas Warnungen stoßen nicht auf taube Ohren, allerdings unterliegt es nicht meiner Verantwortung, die Grimmtotem zu bestrafen. Ich werde es natürlich in meinem Bericht an den Kriegshäuptling erwähnen. Sprecht mit niemandem über die Sache, bevor Thrall sich der Grimmtotem angenommen hat. Ihr habt gute Arbeit geleistet, indem Ihr das Rätsel um das Gasthaus Zur süßen Ruh gelöst und uns vom Verdacht der Einwohner von Theramore befreit habt.", rewards = "Gamaschen des langen WegesBedeckung des ScharmützlersStahlbebänderte HalsbergeSchneide des KampfzauberersStahlverstärkte HalsbergeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11207] = {title = "Bergt die Fracht!", objective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", description = "Der Zeppelin hatte Morastwinkels Vorräte für die nächsten sechs Monate geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch auf Dauer ist das keine Lösung.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt, was die Sache ziemlich erschwert. Ohnehin denke ich, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir bei der Bergung helfen?", progress = "<Moxie scheint beinahe wahnsinnig vor Sorge.>\n\nIst die Fracht intakt? Konntet Ihr irgendetwas bergen?", completion = "Wow! Ich hätte nie geglaubt, dass da draußen noch so viel intakte Fracht liegt. Keine Ahnung, welche Ausbeute Drazzit von uns erwartet, aber zunächst wird er sich mit diesem Fund zufrieden geben müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11208] = {title = "Lieferung für Drazzit", objective = "Bringt die Zeppelinfracht zu Drazzit Tropfhahn in Morastwinkel.", description = "Drazzit erwartet sicher bald Nachricht von mir, doch solange die Absturzstelle nicht gesichert ist, kann ich hier nicht weg. Würdet Ihr, sofern Ihr etwas Zeit erübrigen könnt, einen Teil der geborgenen Fracht nach Morastwinkel bringen?\n\nFalls Ihr den Weg nicht kennt: die Siedlung liegt südwestlich von hier, hinter den Ruinen der Steinbrecher. Ihr könnt auch die Straße, die von Tabethas Hof wegführt, nehmen. Nachdem Ihr in Morastwinkel angekommen seid, sucht nach einem Typen namens Drazzit Tropfhahn.", progress = "Ja?", completion = "&lt;Drazzit nimmt die Fracht entgegen.&gt;\n\nIch bin so hungrig, ich könnte glatt einen ganzen Drachen verschlingen! Schön, dass es Moxie endlich gelungen ist, einen Teil der Fracht hierher zu schaffen. Wir waren zuletzt sogar dazu verdammt, mit dem Oger um seine Jagdbeute zu würfeln, ansonsten wären wir verhungert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11209] = {title = "Nats Abmachung", objective = "Nat Pagle bei Nats Angelplatz möchte, dass Ihr seinen neuen Köder ausprobiert.", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", progress = "Vergesst nicht, die Abmachung lautet \"Kommt nicht eher wieder, bevor Euch etwas gebissen hat\".", completion = "Nicht übel, aber wenn ich Ihr wäre, dann würde ich so schnell wie möglich ein Bad nehmen.\n\nSo, jetzt zu dem Meeresungeheuer...\n\nNehmt Euch ruhig ein oder zwei Bierchen in der Zwischenzeit.", rewards = "Ihr bekommt:\n\nDunkelmondspezialmischung"}
MultiLanguageQuestData['de'][11210] = {title = "Oh, es ist wahr!", objective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit einem klugen Menschenverstand dergleichen tun.\n\nDas ist also Euer Plan! Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", progress = nil, completion = "&lt;Ihr erzählt von Eurem Besuch bei Nat Pagle, lasst dabei den Teil mit dem Ködertest aber vorsichtshalber aus.&gt;\n\nNun, es hört sich ganz so an, als ob wir genau wissen, was es zu tun gilt. Ich treffe schon einmal die Vorbereitungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11211] = {title = "Hilfe für Morastwinkel", objective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", description = "Als diese Goblinfrau... wie war doch gleich ihr Name... Boxie, Foxy... Moxie, genau! Egal, jedenfalls erwähnte sie, als sie auf ihrem Weg zum Zeppelinwrack hier vorbeikam, dass die Siedlung Morastwinkel in Schwierigkeiten wäre.\n\nAnscheinend hatte der abgestürzte Zeppelin wohl Vorräte für die Siedlung geladen. Folgt einfach der Straße südlich von hier, vorbei an den Ruinen der Steinbrecher. Kurz danach solltet Ihr Morastwinkel erreicht haben.\n\nSprecht dort unten mit Drazzit Tropfhahn und seht, ob er nicht Eure Hilfe gebrauchen kann.", progress = nil, completion = "Es war gut, dass Tabetha Euch hierher geschickt hat. Solange der Zeppelin noch nicht geborgen ist, muss ich sie um einige Nahrungsmittel bitten. Leider ist sie selbst gerade knapp an Vorräten. Oh, falls Ihr nach einer Herausforderung sucht: ich habe erst kürzlich ein Kopfgeld auf einen besonders gefährlichen Raptor ausgesetzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11212] = {title = "Tabethas Hof", objective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", description = "Tief im Herzen des Sumpfs lebt eine alte Frau namens Tabetha. Wir wussten noch nie wirklich viel über sie, außer dass sie älter ist, als sie scheint. Sie hat uns hier von Zeit zu Zeit geholfen und auch den Frieden zwischen der Horde und unseren Kräften schon oft bewahrt.\n\nNormalerweise hörten wir regelmäßig von ihr, aber seit Kurzem ist es still geworden.\n\nKönntet Ihr einmal bei ihr vorbeischauen, falls Ihr Zeit habt? Folgt einfach der Straße jenseits der Nordwacht weiter Richtung Süden und in den Morast. Ihr könnt ihren Hof von der Straße aus sehen.", progress = nil, completion = "Gut, dass man Euch von Theramore hierher entsandt hat. Der von Eurem Freund gehegte Verdacht entspricht der Wahrheit. Wir haben ein paar neue Nachbarn... und dabei handelt sich nicht um die Sorte, der man gerne ein Stück Kuchen bringt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11213] = {title = "Seht nach Tabetha", objective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", description = "Eine Menschenfrau namens Tabetha lebt auf einem kleinen Hof, fast inmitten der Marschen. Normalerweise würde ich mich nicht mit einem Menschen abgeben, aber ihre Hilfe hat sich schon so manches Mal als nützlich erwiesen.\n\nLeider habe ich seit geraumer Zeit nichts mehr von ihr gehört und ich würde mir wünschen, dass jemand zu ihrem Hof reist und nach dem Rechten sieht.\n\nWenn Ihr der Straße aus dem Dorf in Richtung Süden und anschließend ins Innere des Sumpfs folgt, werdet Ihr auf ihren Hof im Herzen des Morasts stoßen.", progress = nil, completion = "Welch Glück, dass Nazeer Euch hierher entsandt hat. Wir haben ein paar neue Nachbarn und seit sie ihr Lager hier aufgeschlagen haben, waren sie nichts als Störenfriede.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11214] = {title = "Mission nach Morastwinkel", objective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", description = "Das Dampfdruckkartell hat vor Kurzem im südlichen Teil der Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Würdet Ihr für uns dorthin reisen?", progress = nil, completion = "So, Theramore ist also an Geschäften mit uns interessiert? Nun, ein derartiges Angebot werde ich nicht ablehnen. Neue Vorräte sind hier nur schwer zu beschaffen, also sind neue Handelspartner stehts willkommen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11215] = {title = "Helft Morastwinkel", objective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", description = "Für den neuen Außenposten des Dampfdruckkartells im südlichen Teil der Marschen sieht es momentan nicht so gut aus. Der Zeppelin mit den Vorräten für Morastwinkel ist abgestürzt und nun fehlt es an Werkzeugen, Nahrung und medizinischen Versorgungsgütern.\n\nFolgt der Straße nach Süden in die Marschen. Bevor Ihr Morastwinkel erreicht, führt Euch die Straße zunächst noch an Tabethas Hof und den Ruinen der Steinbrecher vorbei. Bitte helft den Einwohnern von Morastwinkel, so gut Ihr könnt.", progress = nil, completion = "Jede Hilfe ist willkommen! Wir richten uns hier gerade ein und versuchen, das Beste aus unserer Situation hier zu machen, bis die Vorräte des Zeppelins eintreffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11216] = {title = "Erzmagier Alturus", objective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan im Gebirgspass der Totenwinde.", description = "Mein Mentor hat mich hierher geschickt, um nach Unterstützung zu suchen, aber unglücklicherweise darf ich mich nicht außerhalb des Unteren Viertels aufhalten. Die Leute, die dieses Etablissement besuchen, sind leider alles andere als hilfreich.\n\nIhr scheint anders zu sein, begebt Euch wohl gerne auf Abenteuer. Wenn Ihr uns bei unserem Unterfangen unterstützen wollt, dann sprecht mit Erzmagier Alturus außerhalb von Karazhan, Medivhs alter Behausung.\n\nIch werde versuchen, mir in der Zwischenzeit Zutritt zum Rest der Stadt zu verschaffen. Man munkelt, dass sich ein ehemaliger Kollege von uns hier aufhält.", progress = nil, completion = "Danke, dass Ihr Euch die Zeit genommen habt, um uns hier zur Hilfe zu kommen. Vor uns liegt eine Menge wichtiger Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11217] = {title = "Entwindet den Drachen", objective = "Gizzix Rußgurgel in Morastwinkel möchte, dass Ihr ihm 8 Drachenwinden bringt.", description = "Nachdem der Zeppelin mitsamt unseren Vorräten abgestürzt ist, gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun, was wir können, aber inmitten all dieser Insekten, umgeben von Feinden, bleiben Verletzungen nicht aus. Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch unser Pflanzenvorrat geht ebenfalls zur Neige.\n\nMan nennt sie Drachenwinde und sie wächst im Drachendüster und im Drachensumpf östlich der Siedlung. Die Pflanze besteht aus gewundenen Stängeln und wenn man sie ansieht, scheint sie zu pulsieren.", progress = "Habt Ihr einige Drachenwinden gefunden?", completion = "Danke! Damit sollten wir eine Weile überleben können, bis Moxie mit den restlichen Vorräten von der Zeppelinabsturzstelle zurückkehrt.", rewards = "GesellenschulterklappenGeölte LedergamaschenSchneide des KampfzauberersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11218] = {title = "Warnung! Sprengstoff!", objective = "Verwendet Stahlrings idiotensicheres Dynamit, um 6 Erzfragmente aus der Flüsterschlucht und 18 Edelsteine aus der Flüsterschlucht zu beschaffen. Bringt die Gegenstände anschließend zu Pionier Stahlring in Westwacht zurück.", description = "<Name>, der Hauptmann hat mich mit einer Mission beauftragt - und ich hätte gerne Eure Hilfe.\n\nEine Truppe meiner Kameraden bei der Forscherliga wurde verrückt, als sie in der Flüsterschlucht im Norden etwas ausgrub. Sie greifen einen jeden an, der versucht, dort hineinzugelangen.\n\nDer Hauptmann ist nur wegen dem Erz für die Wache beunruhigt. Zu unserem Glück habe ich genau das Richtige für unseren Zweck.\n\nGeht dorthin, jagt das Erz in die Luft und bringt es gemeinsam mit allen Edelsteinen, die Ihr finden könnt, zurück. Diesen Laden zu schmeißen ist nicht gerade billig, müsst Ihr wissen!\n\nMuss Euch jedoch warnen - das Erz ist seltsam!", progress = "Diesen Ort aufzubauen scheint eine endlose Aufgabe zu sein. Ich hoffe nur, dass Ihr bekommen könnt, was wir benötigen, um weiterzumachen.", completion = "Ihr habt von dem Erz ein seltsames Gefühl bekommen? Vielleicht werden wir das Zeug dann doch nicht verwenden.\n\nDiese Edelsteine sind wirklich hübsch! Ich frage mich, was ich für die bekommen kann? Es gibt natürlich immer Reparaturen zu erledigen und neue Dinge herzustellen.\n\nDoch, ich finde, dass unsere Zusammenarbeit profitabel war. Nehmt dies... es ist das mindeste, was ich machen kann!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11219] = {title = "Löscht das Feuer!", objective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", description = "Die Kinder der Horde brauchen Eure Hilfe, <Name>. Der kopflose Reiter, einst ein Paladin der Menschen und jetzt ein wahnsinniger Unhold, hat unser Dorf in Brand gesetzt! Ihr müsst diese Feuer löschen!\n\nSchnappt Euch einen Eimer Wasser und löscht die Flammen damit. Ihr könnt den Eimer auch an einen Verbündeten, der näher bei den Feuern steht, weiterreichen. Löscht alle Feuer und haltet den kopflosen Reiter auf!", progress = nil, completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", rewards = "Ihr bekommt:\n\nKürbisdrops der SchlotternächteGewichtige Kürbislaterne"}
MultiLanguageQuestData['de'][11220] = {title = "Der kopflose Reiter", objective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", description = "Solange der Kopf des kopflosen Reiters nicht vernichtet wird, wird sein verheerendes Wüten kein Ende nehmen.\n\nDer Reiter haust tief im Unglückseligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Geht dorthin und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nDies wird den Unhold hervorrufen. Vernichtet den Kopf des Reiters und er wird uns nie wieder plagen.", progress = nil, completion = "Der Ursprung dieses Schreins ist unbekannt, aber es besteht kein Zweifel, wem hier gehuldigt wird...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11221] = {title = "Berichte vom Schlachtfeld", objective = "Sprecht mit Dunkelläuferin Lyana und Todespirscher Razael. Sie befinden sich auf dem Schlachtfeld in der Blutklamm südlich vom Hafen der Vergeltung. Kehrt zu Hochexekutor Anselm zurück, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Unsere Mission in Nordend ist es, Arthas zu zerstören. Die Allianz ist hierbei doch nur ein Hindernis, das wir vernichten werden, wo auch immer wir es finden.\n\nWir konnten ihre östlichste Flotte zerstören, doch die Überlebenden haben sich am Verlassenen Strand im Süden verbarrikadiert.\n\nUnsere Streitkräfte hätten ihre provisorischen Verteidigungsanlagen schon vor langer Zeit überrennen sollen - wir haben ihren Überlebenswillen jedoch unterschätzt. Sucht nach Dunkelläuferin Lyana und Todespirscher Razael, meine Offiziere auf dem Schlachtfeld, und lasst Euch von ihnen über die Situation Bericht erstatten.", progress = nil, completion = "Kanonen halten uns auf? Ich werd' denen zeigen, was Kanonen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11222] = {title = "Beweis des Verrats", objective = "Sprecht mit König Varian Wrynn in Burg Sturmwind.", description = "Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen diejenigen, die ihren Plan ausgeführt haben, die Defias, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.\n\nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, <Name>.", progress = nil, completion = "&lt;Hochlord Bolvar hört sich Jainas Botschaft an.&gt;\n\nSeid Ihr sicher? Das ist eine schwerwiegende Anschuldigung...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11223] = {title = "Rückkehr zu Jaina", objective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", description = "Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer eine treue Freundin und loyale Verbündete gewesen.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", progress = nil, completion = "Das sind ausgezeichnete Neuigkeiten, &lt;Name&gt;! Ich hatte befürchtet, dass der Hochlord an der Aufrichtigkeit unserer Informationen zweifeln würde, aber meine Sorge war wohl unberechtigt.\n\nTheramore und die Allianz werden Euch für Eure Bemühungen reichlich belohnen.", rewards = "Handgelenksschützer des BogenschützenGleißende SchuppenbrustplatteJuwelenbesetzter DolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11224] = {title = "Schickt die Packmulis packen", objective = "Forscherin Abigail möchte, dass Ihr Euch in die Nähe von 10 verlassenen Packmulis begebt, um jedes Mal Eure Hand zu /heben. Kehrt zu ihr zurück sobald Ihr damit fertig seid. Sie befindet sich in der Westwacht.", description = "Mir sind Gerüchte zu Ohren gekommen, nach denen in der Flüsterschlucht im Norden schlimme Dinge passieren. Ein Großteil der Forscherliga ging dorthin - und man sagt, dass das, was sie dort entdeckten, sie in den Wahnsinn trieb.\n\nDas ändert jedoch nichts daran, dass sie die meisten unserer Mulis und den überwiegenden Teil unserer Ausrüstung mitnahmen. Aber die Mulis werde ich nicht verlieren!\n\nFalls Ihr Euch dort herumtreiben solltet und Euch zufällig ein paar Mulis über den Weg laufen, dann müsst Ihr Euch ihnen nur nähern und sie mit erhobener Hand bedrohen. Das wird sie so sehr erschrecken, dass sie bestimmt wieder nach Hause kommen werden.", progress = "Das ist ein schwerer Schlag für uns. Ich wage es nicht einmal mir auszumalen, was sie dort unten entdeckt haben.\n\nEs hält mich schon die ganze Nacht lang wach, wenn ich nur versuche mir vorzustellen, was es denn sein könnte.", completion = "Ich stehe in Eurer Schuld, &lt;Klasse&gt;. Nachdem wir den Großteil unserer Mulis und Ausrüstung wiederbeschafft haben, können wir zumindest darauf hoffen, bald wieder zahlreicher zu sein.\n\nBitte, nehmt dies.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11225] = {title = "Der Einsiedler des Hexenhügels", objective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", description = "Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.\n\nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn \"Sumpfauge\" Jarl, machen sich bereits einige Anzeichen bemerkbar.\n\nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.\n\nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.", progress = nil, completion = "Seid Ihr hierher gekommen, um mich auszuspionieren? Nein?\n\nDann seid Ihr vielleicht ein Liebhaber der guten Küche? Gut, ich kann Eure Hilfe gebrauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11227] = {title = "Lasst sie Krähen fressen", objective = "Pontius, der Hüter des Zwingers im Hafen der Vergeltung, möchte, dass Ihr mithilfe des Seuchenhundkäfigs einen hungrigen Seuchenhund herbeiruft und diesen dann mit dem Krähenfleisch der Fjordkrähen füttert. Letztere befinden sich westlich des Hafens der Vergeltung.", description = "Der Hochexekutor möchte, dass ich mit meinen Hunden die gegnerischen Späher aufspüre. Aber ich kann Euch das gleich sagen, dass diese Seuchenhunde nirgendwo hingehen, bevor sie nicht richtig gefüttert wurden.\n\nWenn es unserem Militär nicht in den Sinn kommt, dass diese Biester wählerisch genug sind, um den Müll nicht zu fressen, der mir gegeben wurde, dann können sie auch nicht erwarten, dass sie irgendwelchen Nutzen auf dem Schlachtfeld haben werden.\n\nIhr scheint etwas Zeit zu haben. Wieso nehmt Ihr nicht einen der Hunde und geht mit ihm auf Krähenjagd im Westen? Für uns ist ihr Fleisch nicht sehr bekömmlich, doch meine Jungs stehen drauf!", progress = nil, completion = "Hast du ein paar Krähen gejagt, Junge? Guter Junge, guter Junge!\n\nAh, diese Hunde erinnern mich an die Zeiten, als ich Reinrassige in Tirisfal aufzog... das waren gute Zeiten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSeuchenhund freigeben\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11228] = {title = "Eine Hölle aus Eis...", objective = "Sprecht mit Vizeadmiral Keller im Hafen von Valgarde.", description = "Auf Fordragon wird noch etwas zukommen, wenn er denkt, dass die paar Deckschrubber, die er zum Schutz dieses Hafens geschickt hat, noch viel länger durchhalten werden.\n\n<Macalroy begutachtet Eure Ausrüstung und hebt eine Braue.>\n\nEuch könnte es jedoch ein wenig besser ergehen.\n\nWie wichtig es ist, diesen Hafen zu halten, kann nicht genug betont werden - und seitdem diese Monster über unsere Köpfe hinwegfliegen, hat sich die Situation noch verschlechtert.\n\nMeldet Euch bei Vizeadmiral Keller im Nordwesten, nicht weit von hier. Sagt ihm, dass Ihr gekommen seid, um ein paar Hintern zu versohlen und Kaugummi zu kauen - Ihr jedoch keinen Kaugummi mehr habt.", progress = nil, completion = "Der Zwerg spricht die Wahrheit. Wir können es uns nicht leisten, diesen Hafen zu verlieren. Er ist einer von zwei sicheren Häfen in dieser Eishölle, die der Allianz gehören - der andere liegt ein paar Hundert Meilen westlich von hier, an der Küste der boreanischen Tundra.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11229] = {title = "Die Windläuferflotte", objective = "Sprecht mit Fledermausführerin Kamilla im Hafen der Vergeltung und fragt nach einer Möglichkeit, zur Windläufer hindurchzukommen. Meldet Euch dann bei Kapitän Harker an Bord des Schiffs.", description = "Östlich des Verlassenen Strands sind die Schiffe 'Windläufer', die 'Vergeltung ihrer Majestät' und die 'Ewige Vergessenheit' stationiert. Schickt dem Flottenkommandant Kapitän Harker den Auftrag, dass die Kanonen der Allianz zerstört werden müssen.\n\nSprecht mit unserer Fledermausführerin Kamilla und fragt nach einer Möglichkeit, um zum Standort der Flotte hindurchzukommen. Beeilt Euch, <Name>. Jede Minute, die wir gegen die Allianz kämpfen, ist eine Minute, die wir gegen Arthas kämpfen könnten.", progress = nil, completion = "Ich hoffe, dass Ihr bereit seid, zu kämpfen, &lt;Name&gt;. Die Flotte ihrer Majestät braucht Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11230] = {title = "Hinterhalt!", objective = "Kapitän Harker an Bord der Windläufer möchte, dass Ihr 15 Marinesoldaten der Nordflotte tötet.", description = "Das hätte ein Kinderspiel sein sollen. Ihre Streitkräfte sind hungrig, verletzt und schlecht ausgerüstet. Doch irgendwie sind wir geradewegs in ihre Falle gelaufen.\n\nZwecks Deckung näherten wir uns dem Riff vom Süden her, worauf wir dann sofort von der Allianz - diesen Hunden - geentert wurden.\n\nLeider muss ich sagen, dass Ihr uns zuerst dabei helfen müsst, unsere Schiffe zurückzubekommen, bevor unsere Kanonen auf irgendetwas schießen können.", progress = nil, completion = "Diese Bastarde zurechtzustutzen, war saubere Arbeit. Meine Männer werden sich um den Rest kümmern.", rewards = "Kapuze der GüteKnochenbewehrter HarnischNerubischer InnenpanzerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11231] = {title = "Von Schlüsseln und Käfigen", objective = "Vater Levariol möchte, dass Ihr genug Schlüssel für einen Gjalerbronkäfig sammelt, um 10 Gefangene von Gjalerbron zu befreien. Kehrt zu ihm zurück, sobald Ihr damit fertig seid. Er befindet sich in Westwacht.", description = "Dem Hauptmann mag es egal sein, aber das wenige was wir wissen ist, dass die Vrykul im nördlich gelegenen Gjalerbron abscheuliche Riten durchführen, die Teil einer Art Erweckungsritual sind.\n\nSie bedienen sich lebendiger Opfer für ihre unheiligen Rituale!\n\n<Klasse>, Ihr müsst dem ein Ende bereiten! Es kommt nicht darauf an, wer oder was in diesen Käfigen ist - egal was, es muss befreit werden. Ich wette, dass die Vrykul die Schlüssel bei sich tragen.\n\nBeim Licht, das letzte was wir gebrauchen können ist, dass noch mehr dieser seltsamen Vrykul umherlaufen; oder sogar schlimmer: dass sie etwas erwecken, das noch boshafter ist.", progress = nil, completion = "Gesegnet sollt Ihr sein, mein Kind! Mit Eurer Hilfe scheint das Licht selbst an den dunkelsten Orten.\n\nBitte, nehmt dies. Ein gerechter Lohn für Eure guten Taten. So werde ich mich um das Heil derer kümmern, die Ihr befreit habt - oder zumindest um diejenigen der Zurückgekehrten, die dem Licht wahrhaftig angehören und auf der Seite der Allianz sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11232] = {title = "Lenkt unseren Blick", objective = "Markiert mit den Rauchsignalen die Stellen entlang der Nordwand am Verlassenen Strand, an denen sich die Kanonen der Allianz befinden. Meldet Euch bei Dunkelläufer Lyana in der Blutklamm, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Wir sollten uns den Weg zurück zu unseren Kanonen freikämpfen können. Unglücklicherweise sind die Sichtverhältnisse alles andere als wünschenswert, weswegen Ihr unsere Ziele vom Boden aus markieren müsst.\n\nNehmt diese Rauchsignale mit Euch, geht zur Stellung der Allianz am Verlassenen Strand westlich von hier und markiert mit ihnen die Kanonen, die sich entlang der Nordwand befinden.\n\nSagt Lyana Bescheid, sobald der Weg für die Bodentruppen frei ist. Wir können hier drüben auf uns selbst aufpassen.", progress = nil, completion = "Ausgezeichnet. Ich werde unseren Bodentruppen signalisieren, dass sie sich in Bewegung setzen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11233] = {title = "Den Todesstoß landen", objective = "Dunkelläuferin Lyana südlich des Hafens der Vergeltung möchte, dass Ihr Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric tötet. Ihr findet sie am Verlassenen Strand.", description = "Ihr habt Euren Wert auf dem Schlachtfeld bewiesen, <Name>. Womöglich habt Ihr das Blatt zu unseren Gunsten gewendet.\n\nNun habe ich einen wichtigen Auftrag für Euch. Ich bin mir nicht sicher, wie lange die von uns entdeckte Schwachstelle vorhanden sein wird. Wir müssen uns das Überraschungsmoment zu Nutze machen.\n\nIch möchte, dass Ihr die Verwirrung, die unser Angriff ausgelöst hat, nutzt und Euch hinter die feindlichen Linien begebt, um ihre Anführer zu töten. Diese sind wie folgt nach Rang geordnet: Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric. Viel Glück, <Klasse>.", progress = nil, completion = "Dies ist Ausdruck des unumstrittenen Sieges unserer Streitmacht. Anselm wird sehr erfreut sein, wenn er davon erfährt.", rewards = "BrombeerstachelgroßstabFroststeinentersäbelErdstachelBeschwichtigender VerprüglerElekkhornarmbrustFelszackenprüglerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11234] = {title = "Meldung an Anselm", objective = "Erstattet Hochexekutor Anselm Bericht. Er befindet sich im Hafen der Vergeltung im Heulenden Fjord.", description = "Dann lasst uns doch mal den alten Anselm benachrichtigen. Der Sieg kam später als erwartet - doch besser spät als nie. Sagt ihm, dass unsere Streitkräfte ein paar Stunden benötigen werden, um der Nachhut hier den Rest zu geben.\n\nHoch lebe die Bansheekönigin!", progress = nil, completion = "Wurde auch langsam Zeit. Die Allianz ist uns jetzt schon eine ganze Weile lang ein Dorn im Auge.\n\nWir haben jedoch keine Zeit zum Feiern. Richtet Euren Blick nach Westen - es sieht aus, als hätten wir Besuch.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11235] = {title = "Mit Gjalerbron fertigwerden", objective = "Hauptmann Adams möchte, dass Ihr 15 Krieger von Gjalerbron, 8 Runenmagier von Gjalerbron und 8 Schlafwächter von Gjalerbron tötet. Kehrt danach zu ihm zurück. Ihr findet ihn in Westwacht.", description = "Und nun haben wir ein anderes Problem. Diejenigen meiner Späher, die mit dem Leben davon gekommen sind, haben mir berichtet, dass die Vrykul in ihrer Hauptfestung gen Norden nichts Gutes im Schilde führen.\n\nSie nennen den Ort Gjalerbron - obwohl man das 'Gj' wie ein 'Sch' ausspricht. Seltsame Kreaturen sind das.\n\nAber das ist nicht wichtig. Was wichtig ist, ist, dass Ihr Euch dorthin begebt und das Leben so vieler dieser Kreaturen auslöscht, wie Ihr nur könnt. Findet gleichzeitig heraus, was sie dort treiben.\n\nIch weiß, dass ich mich auf Euch verlassen kann, <Name>.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Ein Glück, dass wir sie los sind!\n\nAber was Ihr über diesen Ort zu berichten habt, macht mir noch immer Sorgen. Ich denke, dass unsere Eindämmungsaktion noch nicht ganz beendet ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11236] = {title = "Nekrogroßfürst Mezhen", objective = "Tötet Nekrogroßfürst Mezhen. Kehrt dann zu Hauptmann Adams zurück. Ihr findet ihn in Westwacht.", description = "Die Geißel ist in Gjalerbron und sie haben Nekromanten bei sich! Sie versuchen sicherlich, die Vrykul zu Arthas' Gefolgsleuten zu machen.\n\nIch will, dass der Anführer der Nekrolords eliminiert wird!\n\nTut alles was Ihr könnt, <Name>. Aber sorgt dafür, dass Nekrogroßfürst Mezhen und das, was er versucht zu bewerkstelligen, aus der Welt geschafft wird.\n\nEine Allianz zwischen den Vrykul und der Geißel werde ich nicht dulden!\n\nGeht zur Plattform in der hinteren rechten Ecke von Gjalerbron, dort werdet Ihr Mezhen finden.", progress = nil, completion = "&lt;Der Hauptmann seufzt erleichtert auf.&gt;\n\nTja, das sollte es uns ein wenig einfacher machen.\n\n&lt;Name&gt;, Ihr habt immer wieder bewiesen, dass Ihr für Westwacht und die Allianz insgesamt von unschätzbarem Wert seid. Sucht Euch etwas aus der Schatzkammer aus! Es ist das mindeste, was wir tun können!", rewards = "WorghautschulternDämmerverflochtene GamaschenGoldbelegter KaltstahlgurtTuch der HochherzigkeitIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11237] = {title = "Angriffspläne von Gjalerbron", objective = "Übergebt die Angriffspläne von Gjalerbron an Magierleutnant Malister. Er befindet sich in Westwacht.", description = "In diesen Plänen wird ein unmittelbar bevorstehender Angriff auf Westwacht bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm Glacion, der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden.\n\nMagierleutnant Malister könnte in dieser Sache sicherlich behilflich sein. Überbringt ihm die Pläne. Ihr findet ihn in der Feste gen Süden.", progress = "Was?! Pläne für einen Angriff auf die Wache?\n\nEIN FROSTWYRM?!!!", completion = "&lt;Name&gt;, wir dürfen das nicht zulassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11238] = {title = "Der Frostwyrm und sein Meister", objective = "Erschlagt Wyrmrufer Elend und benutzt das Wyrmruferhorn, um Glacion herbeizurufen und ihn niederzustrecken. Kehrt anschließend gemeinsam mit dem Horn zu Magierleutnant Malister zurück. Er befindet sich in Westwacht.", description = "Das hier zu mir zu bringen, war die richtige Entscheidung, <Name>. Ihr müsst zum nördlich gelegenen Gjalerbron gehen und den Wyrm und seinen Meister, Wyrmrufer Elend, niederstrecken.\n\nNoch während wir hier reden könnte der Frostwyrm schon unterwegs sein.\n\nWenn ich die Pläne jedoch richtig verstehe, dann wird Glacion zurückgerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst. Ihr müsst das Wesen besiegen, sobald es landet!\n\nUnd <Name>: Bitte bringt mir das Horn. Wir würden es nicht gerne sehen, wenn es wieder in falsche Hände geraten sollte.", progress = "Ist der Angriff abgewendet? Wurden der Frostwyrm und sein Meister vernichtet?\n\nHabt Ihr das Horn zurückgebracht?", completion = "Wahnsinn, das Horn ist kalt!\n\nIhr habt Westwacht wieder einmal vor ihrem sicheren Untergang bewahrt. Welch ungewöhnlicher Mann Ihr seid, &lt;Name&gt;. Wenn es nur mehr wie Euch geben würde.\n\nTja, das verlangt allerdings nach einer Belohnung. Was würdet Ihr bevorzugen?", rewards = "ErdbrunnenfußlappenMagiespitzenhelmSilberstahlstulpenAuf Euch wartet eine dieser Belohnungen:\n\nVerlorenes Vrykulabzeichen\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11239] = {title = "Im Dienste des Lichts", objective = "Erschlagt 10 ewige Beobachter, 4 furchterregende Schrecken und 2 eitrige Kreaturen. Informiert danach Vater Levariol von Eurem Erfolg. Er befindet sich in Westwacht.", description = "Euer Dienst ist beispielhaft gewesen, <Name>. Doch es gibt etwas, das mir Sorgen bereitet: die Geißel.\n\nDas Licht kann ihre Anwesenheit nicht dulden und genauso wenig sollen wir es tun. Ich hoffe, dass es nicht zu viel verlangt ist, wenn ich Euch zurück ins nördlich gelegene Gjalerbron schicken würde, damit Ihr die Geißel in diesem abscheulichen Unterschlupf vernichtet! Seht zu, dass Ihr auch in den Hallen des Erwachens unter Gjalerbron nachseht.\n\nReinigung ist der Weg zur Erlösung, mein Kind. Macht uns stolz!", progress = nil, completion = "&lt;Der Priester spricht einen kaum hörbaren Segen für Euch aus.&gt;\n\nSeid gesegnet, &lt;Name&gt;. Ihr habt meine Gebete erhört. Steht mit Stolz und erhobenem Kinn im Lichte. Wisset, dass Eure Taten höchst heilig waren!\n\nIch bin mir sicher, dass Euch die Truhen der Kirche etwas Brauchbares bieten können.", rewards = "Majestätische PantalonsStammesbrustharnischLehmbefleckte SchienbeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nWorgzahnanhänger\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11240] = {title = "Anführer der Verwirrten", objective = "Erschlagt Squeeg Götzenjäger und meldet Euch dann bei Pionier Stahlring in Westwacht.", description = "Also, ich sag es nicht gerne, mein Freund, aber während Ihr fort wart, fing der Hauptmann an, ein stärkeres Interesse an diesem Ort zu hegen.\n\nSieht so aus, als wollte er meinen alten Boss bei der Forscherliga dort drin tot sehen. Ich schätze mal, dass wir uns für eine Offensive rüsten, um den Rest von ihnen zu beseitigen. Der Hauptmann will gewissermaßen, dass sie einen Kopf kürzer gemacht werden.\n\nWollt Ihr mir einen Gefallen tun? Geht zurück zur Flüsterschlucht und bereitet Squeeg Götzenjäger ein Ende. Meiner Erinnerung zufolge könnte er sich in der Höhle in der nordwestlichen Ecke befinden.", progress = nil, completion = "&lt;Der Pionier murrt, als wünschte er sich, dass Ihr es nicht geschafft hättet.&gt;\n\nDer Hauptmann wird erfreut darüber sein, dass Ihr Erfolg hattet.\n\nNun ja, Ihr habt so gut bei der Flüsterschluchtsache mitgemacht, wieso sucht Ihr Euch nicht hiervon etwas aus?", rewards = "Zornverwobene SchulterpolsterGestachelter SchädelschutzFlüsterstahlhandschützerFederumsäumte SchulterpolsterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11241] = {title = "Flammenspur", objective = "Eskortiert Apotheker Hanes vom Verlassenen Strand. Meldet Euch bei Apotheker Lysander, sobald Ihr diese Aufgabe abgeschlossen habt. Er befindet sich im Hafen der Vergeltung im Heulenden Fjord.", description = "Danke, dass Ihr mir aus diesem Schlamassel geholfen habt, <Name>. Ich habe mich nicht danach gesehnt, zu sehen, was diese Allianzmistkerle für mich auf Lager hatten.\n\nLasst uns von hier verschwinden und schauen wir mal, ob wir es ihnen irgendwie heimzahlen können. Ist das ein Lagerfeuer dort drüben?", progress = nil, completion = "Apotheker Hanes ist am Leben? Ihr habt die Vorräte der Allianz verbrannt? Das hat ihm garantiert Riesenspaß gemacht.\n\nAuf jeden Fall steht die königliche Apothekervereinigung in Eurer Schuld, &lt;Name&gt;. Unser Dank für Euch kommt aus den Tiefen unserer schwarzen Herzen.", rewards = "Eisbereifter DolchSteinklingenschlitzerWelpenschädelschockerMajestätisches SzepterKaltstachellangbogenAusgedienter VrykulzerkracherIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11242] = {title = "Endlich frei!", objective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", description = "Zorn hielt mich gefangen, <Name>, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Was ist das? Der Foliant von Thomas Thomson, sagt Ihr? Aber das ist doch der Name des kopflosen Reiters, bevor er dem Flucht zum Opfer fiel! Heißt das, seine Seele ist endlich frei? Bedeutet dies wirklich, dass er die guten Einwohner von Azeroth nie wieder heimsuchen wird? Was für ein Freudentag! &lt;Name&gt;, von Euren Heldentaten wird man noch lange zu berichten wissen. Die Kinder und sogar ihre Kinder werden sich stets an Euren Namen erinnern!", rewards = "Ihr bekommt:\n\nKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11243] = {title = "Falls Valgarde fällt...", objective = "Vizeadmiral Keller möchte, dass Ihr 12 Eindringlinge der Drachenschinder oder Worge der Drachenschinder tötet. Er befindet sich im Hafen von Valgarde im Heulenden Fjord.", description = "Falls Valgarde fällt, wird unser Hauptversorgungsweg nach Nordend zum Stillstand kommen. Von da an wäre es nur eine Frage der Zeit, bis wir alle Diener des Lichkönigs sind. Nun, ich weiß nicht, wie es um Euch steht, aber ich habe eine Frau und drei Kinder in Elwynn - soll mich der Teufel holen, wenn ich ohne einen Kampf unterginge.\n\nDie Situation hier ist kritisch. Wir können jede Unterstützung gebrauchen, die Ihr aufbringen könnt. Begebt Euch zum Eingangstor und helft den Wachen, die Stadt gegen die Eindringlinge zu verteidigen!", progress = "Es ist gut möglich, dass das Schicksal der Welt in unseren Händen liegt.", completion = "Ihr habt unseren Verteidigern die nötige Unterstützung gegeben, &lt;Name&gt;. Dank Euch ist die Moral höher denn je. Ich denke, dass sie den Rest des Ansturms alleine bewältigen können. Ich habe großes mit Euch vor...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11244] = {title = "Die Retter retten", objective = "Vizeadmiral Keller möchte, dass Ihr 8 Späher von Valgarde rettet, die mit Harpunen beschossen und zum Sterben liegen gelassen wurden. Er befindet sich im Hafen von Valgarde im Heulenden Fjord.", description = "Wir waren hier seit einem Monat, als diese missgestalteten Riesen aus dem Nichts auftauchten. Für einen Angriff waren wir schlecht vorbereitet und so mussten wir für unsere Selbstgefälligkeit bitter bezahlen. Ein komplettes Archäologenteam war verschwunden und einige Einwohner wurden entführt und zu den Ruinen gebracht. Seitdem sind wir in der Defensive.\n\nZu allem Übel wurden die Späher, die wir zur Rettung unserer Leute aussandten, von den Vrykul mit Harpunen beschossen und im Wald direkt nördlich von Valgarde zum Sterben liegen gelassen. Räumt diese Harpunen aus dem Weg und befreit unsere Späher!", progress = nil, completion = "Was die Vrykul unseren Spähern angetan haben, war ein grausamer Akt der Barbarei. Es war zur Abschreckung gedacht, um unseren Willen zu schwächen... und uns in die Flucht zu schlagen.\n\nEs hat nicht funktioniert.\n\nWir werden diesen Monstern zeigen, was es bedeutet, gegen die Allianz Krieg zu führen!", rewards = "BrombeerstachelgroßstabFroststeinentersäbelErdstachelBeschwichtigender VerprüglerElekkhornarmbrustFelszackenprüglerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11245] = {title = "Türme des sicheren Untergangs", objective = "Der Unteroffizier der Westwacht meint, dass es sinnvoll wäre, wenn man mit dem Leuchtsignal des Unteroffiziers die Türme in Skorn markiert, damit sie anschließend unter Kanonenbeschuss genommen werden können.", description = "<Gnädiger Herr/Gnädige Frau>, wenn wir durch Skorn ziehen, müssen wir die Türme zerstören!\n\nWenn Ihr sie Euch anseht, dann werdet Ihr feststellen, dass sich viele Zauberer auf den Türmen befinden. Sich zu nah an sie heranzuwagen, würde für uns den sicheren Tod bedeuten!\n\nWir verfügen jedoch über die Möglichkeit, Kanonensalven aus Westwacht anzufordern. Um das zu tun, müssen wir nahe genug herankommen und ein Leuchtsignal auf die Stelle schießen, wo sich die Magier befinden.\n\nKommt nur nicht zu nah ran!", progress = "Sich zu nah an die Türme heranzuwagen bedeutet den sicheren Tod, solange die Zauberer dort oben sind.", completion = "Ausgezeichnetes Zielen, gnädiger Herr! Ich darf nicht vergessen, den Kanonieren in der Wache eine Runde auszugeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11246] = {title = "Grausam, aber notwendig", objective = "Der Unteroffizier der Westwacht möchte, dass Ihr nach Skorn geht und mit der Machete des Unteroffiziers 20 Vrykul des Winterskornstammes zerstückelt.", description = "Wir haben Berichte erhalten, nach denen die Vrykul von den Toten auferstehen können - ähnlich der Geißel, doch eine andere Art des Untodes.\n\nLasst uns kein Risiko eingehen.\n\nHier, nehmt meine Machete. Wir werden durch diesen Ort ziehen und Ihr werdet die Überreste der von uns erschlagenen Vrykul zerstückeln müssen. Ich würde es tun, wenn ich keinen empfindlichen Magen hätte.\n\n<Der Unteroffizier lächelt selbstgefällig.>\n\nIch habe den ganzen Morgen damit verbracht, sie zu schärfen - sie sollte also für die Aufgabe geeignet sein.", progress = nil, completion = "Nun ja, mein Herr - ich muss sagen, dass Ihr mit besonderem Eifer an diese spezielle Sache herangegangen seid.\n\n&lt;Der Unteroffizier blickt Euch misstrauisch an.&gt;\n\nNaja, ich werde meine Machete jetzt wieder zurücknehmen, wenn es Euch recht ist. Sie sieht stumpf aus und wir wollen doch nicht, dass Ihr aus Versehen ausrutscht und mich genau so zerstückelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11247] = {title = "Brenne, Skorn - brenne!", objective = "Der Unteroffizier der Westwacht hat Befehle erhalten, nach denen Ihr mit der Fackel des Unteroffiziers die beiden Langhäuser und die Kaserne in Skorn in Brand stecken sollt.", description = "Hauptmann Adams gab mir strikte Anweisungen, sicherzustellen, dass die Infrastruktur dieses Ortes starken Schaden nimmt.\n\nDa Ihr jedoch hier draußen das Kommando habt, liegt es in Eurem Ermessen, <Sire/Mylady>.\n\nDürfte ich vorschlagen, dass wir beide Langhäuser und die Kaserne, die sich im niedriger gelegenen Teil Skorns befinden, niederbrennen? Dazu müssen wir nur in jedes Gebäude eindringen und diese Fackel hier werfen.", progress = "Dürfte ich vorschlagen, dass wenn wir die Gebäude in Brand setzten, wir uns dann nicht zu lange in ihnen aufhalten?", completion = "Sehr gut, Sire. Das wäre ohne Eure Hilfe nicht zustande gekommen.\n\nIch bin mir sicher, dass sich der Hauptmann über meinen Bericht freuen wird, sobald wir hier fertig sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11248] = {title = "Operation: Skorns Zorn", objective = "Hauptmann Adams möchte, dass Ihr das Befehlsinsigne der Westwacht in Skorn benutzt und anschließend mit dem Unteroffizier der Westwacht sprecht.\n\nBereitgestellter Gegenstand: \n", description = "<Name>, ich muss Euch nun darum bitten, eine Operation durchzuführen, die so gefahrvoll und tödlich ist, dass nur Ihr sie bewältigen könnt.\n\nAn unserer östlichen Grenze befindet sich die Vrykulfestung Skorn. Meine Späher berichten mir, dass diese 'Riesen' kurz davor sind, uns anzugreifen. Meine Streitkräfte sind jedoch über den ganzen Fjord verstreut, weswegen ich nicht über genügend Männer verfüge, um den Ort gewaltsam in Besitz zu nehmen.\n\nIhr werdet stattdessen gerissen sein müssen. Ich habe schon einen Unteroffizier, der über Details in Kenntnis gesetzt ist, vorgeschickt. Zeigt dieses Befehlsinsigne in Skorn vor und er wird sich Euch zeigen und Eure Befehle befolgen.", progress = nil, completion = "Sehr angenehm, Euch kennen zu lernen, Sire! Ich freue mich auf unsere Zusammenarbeit.\n\nWo wir gerade davon reden: Wir haben jede Menge zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11249] = {title = "Verhindert seinen Aufstieg!", objective = "Präsentiert die Vrykulrolle des Aufstiegs in der Nähe des Scheiterhaufens vor der Hütte des Thans, um ihn herauszurufen und ihn niederzustrecken. Ihr seid Euch sicher, dass Vater Levariol an dem Ritual und damit auch an der Schriftrolle Interesse finden wird. Er befindet sich in Westwacht.", description = "Diese riesige Schriftrolle ist aus Drachenhaut gefertigt. Ihr entrollt die mehr als zehn Meter lange Schriftrolle und seht, dass die Bilder auf ihrer schuppigen Oberfläche ein rätselhaftes Vrykulritual darstellen.\n\nEin Than der Vrykul, umgeben von engelhaften Wesen, steigt in den Himmel auf. Eine rätselhafte finstere Figur zeichnet sich vom Hintergrund des Bildes ab.\n\nIhr habt eine ungute Vorahnung, dass der Than von Skorn im Begriff ist, genau dies zu tun. Ihr müsst das verhindern! Vor der Hütte des Thans, auf Skorns höchstem Punkt, steht ein großer Scheiterhaufen.", progress = "Ja? Wie kann ich Euch behilflich sein, mein Kind?", completion = "Ja, mein Sohn, dies könnte Unheil bedeuten. Ihr habt offenbar richtig gehandelt.\n\nDanke, dass Ihr mir diese Schriftrolle gebracht habt. Ich kann es kaum erwarten, herauszufinden, was sie zu bedeuten hat. Würde ich es wagen, eine Vermutung anzustellen, dann würde ich behaupten dass die Vrykul einen Weg haben, um den Tod zu überwinden. Oder zumindest diejenigen, die dessen würdig sind.\n\nIndem Ihr den Than der Winterskorn besiegt habt, habt Ihr bewiesen, dass er unwürdig war. Nur das Licht weiß, was aus ihm geworden wäre und welch Schrecken er über uns gebracht hätte, hättet Ihr ihn nicht erschlagen.", rewards = "Geschmeidige RehhautmokkasinsVerjüngende KordelSchockgebundene SchiftungOnyxhandschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11250] = {title = "Hoch lebe der Eroberer von Skorn!", objective = "Bringt das Befehlsinsigne der Westwacht zu Hauptmann Adams zurück. Ihr findet ihn in Westwacht.", description = "Wir - oder eher Ihr - haben alles getan, zu dessen Erfüllung wir hier her gekommen sind, <Sire/Mylady>. Ich muss sagen, dass es mir eine Freude war, von solch <einem jungen Mann/einer jungen Frau> Befehle zu erhalten.\n\nDer Hauptmann will höchstwahrscheinlich von Eurem Erfolg in Kenntnis gesetzt werden. Solltet Ihr jedoch aus irgendeinem Grund hier bleiben wollen, dann stehe ich Euch zur Verfügung.", progress = "Ich schließe mal aus Eurer Anwesenheit, dass es Skorn nicht mehr gibt. Lieg' ich da richtig?", completion = "Das sind unglaublich gute Neuigkeiten! Ich wusste, dass Ihr es schaffen würdet, &lt;Name&gt;!\n\nWenigstens einer, der hier Resultate liefern kann!\n\nTja, das verlangt nach einer Belohnung. Nur zu, sucht Euch etwas aus - für Euch steht die Schatzkammer offen.", rewards = "Rankengewebte TunikaSonnenfeuerschreiterSchieferplattenarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nKrafterfüllter Anhänger\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11251] = {title = "Ein neuer Abschnitt", objective = "Kundschafterin Valory möchte, dass Ihr den Geräuschen nachgeht, die vom nordöstlichen Teil von Wyrmskol herstammen.", description = "Der Preis war hoch, aber wir konnten die Untersuchung der Ausgrabungsstätte beenden.\n\nKeine guten Neuigkeiten - fast jeder wurde erschlagen oder gefangen genommen. Es werden nur ein paar Wächterveteranen vermisst.\n\nWir Späher haben alles getan, was wir hier tun können. Ihr müsst dort weitermachen, wo wir aufgehört haben.\n\nVom Hügel im Nordosten aus dringen Geräusche eines Gefechts herüber. Seht einmal nach, <Klasse>. Wir können nur darauf hoffen, dass es ein paar Überlebende gibt und dass sie Informationen haben, die wir gegen diesen Feind verwenden können.", progress = nil, completion = "Ihr mögt vielleicht spät dran sein, doch es ist gut, jemanden freundlich Gesinnten zu sehen.\n\nNun hört auf herumzustehen und in der Nase zu bohren. Es gibt viel zu tun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11252] = {title = "Nach Utgarde!", objective = "Verteidiger Mordun hat Euch mit der Exekution von Ingvar dem Brandschatzer, der tief in Utgarde wohnt, beauftragt.\n\nAnschließend sollt Ihr dessen Kopf zu Vizeadmiral Keller bringen.", description = "Zugehört, <Junge/Mädchen>. Ich habe meinen Teil dieser Kreaturen erledigt – und übrigens Euren Teil gleich mit. Was Ihr wissen müsst, ist Folgendes...\n\nDie Vrykul sind furchtlose Kämpfer. Scheint so, als sehnten sie sich danach, im Kampf zu sterben. Ihre Zahl und Wildheit bedeutet für uns den Untergang, um es einfach auszudrücken.\n\nEs gibt jedoch einen, den sie hoch schätzen. Man nennt ihn Ingvar. Ich weiß nicht, wieso sie um seine Gunst werben, aber wenn Ihr ihn tötet, wird das ihr Selbstvertrauen erschüttern.\n\nVielleicht werden wir dann eine Chance haben...", progress = "Es freut mich, zu sehen, dass Ihr wohlauf seid.\n\nWir hatten bis jetzt in etwa genau so viele Verluste, wie wir verschmerzen können.", completion = "Hervorragend!\n\nDas könnte die Glückswende sein, auf die wir alle so lange gehofft haben.\n\nGut gemacht, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des HenkersRing der DezimierungSignet des schnellen Richturteils\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11253] = {title = "Den Feind ausschnüffeln", objective = "Benutzt die Seuchenhundleine in der Nähe der Seuchenhundkäfige im Hafen der Vergeltung und sucht dort nach Hinweisen, wo der Seuchenhundfährtenleser Euch hinführt.\n\nBereitgestellter Gegenstand: \n", description = "Nun, da der Bengel einen vollen Magen hat, wird er vielleicht eher dazu geneigt sein, zu kooperieren. Hier ist seine Leine. Ihr müsst ihn dann nur noch aus seinem Käfig holen, sobald Ihr bereit seid.\n\nIch weiß zwar nicht, welchen Fund sich Anselm von Euch verspricht, aber sucht nach Hinweisen, wo auch immer der Hund Euch hinführen mag.", progress = nil, completion = "Die schuppige Schriftrolle ist mit schlicht gezeichneten Bildern bedeckt. Ihr habt das Gefühl, dass dies genau das ist, woran der Hüter des Zwingers gedacht hat, als er Euch darum bat, nach Hinweisen zu suchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11254] = {title = "Die Karte aus Drachenhaut", objective = "Bringt die Karte aus Drachenhaut zu Hochexekutor Anselm im Hafen der Vergeltung.", description = "Nach genauerer Untersuchung scheint es sich bei der Schriftrolle um eine Karte des Fjords zu handeln, die mit vielen Bildern versehen ist. Die Lage verschiedener Dörfer wird mithilfe von Markierungen dargestellt, die wie Stammessymbole aussehen.\n\nDer Standort des Hafens der Vergeltung wird mit einem unverhältnismäßig großen Totenschädel markiert.\n\nFür Hochexekutor Anselm wird diese Karte höchstwahrscheinlich von militärischem Wert sein.", progress = "Ihr habt etwas, das Ihr mir zeigen wollt, <Klasse>?", completion = "&lt;Der Hochexekutor betrachtet aufmerksam die Karte und lässt ab und an den Blick schweifen, um im Fjord nach Landmarken zu suchen.&gt;\n\nDa drüben befindet sich der östliche Küstenstrich. Die Dörfer der Drachenschinder und Winterskorn befinden sich hier und hier... und das hier oder diejenigen, die zum Töten freigegeben sind, sind wir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11255] = {title = "Gefangene in Wyrmskol", objective = "Vizeadmiral Keller im Hafen von Valgarde im Heulenden Fjord möchte, dass Ihr 3 Gefangene aus Valgarde befreit.", description = "Diese Schlacht ist noch lange nicht vorbei, <Name>. Wenn unsere Leute, die sich in dem Dorf befinden, noch immer am Leben sind, dann muss jemand dort hingehen und sie befreien.\n\n<Vizeadmiral Keller nickt Euch zu.>\n\nGeht nach Wyrmskol im Norden und seht Euch nach unseren Leuten um, sobald Ihr dort seid. Sollten sie irgendwo eingesperrt sein, dann müsst Ihr einen Weg finden, sie zu befreien.\n\nVielleicht haben sie etwas mehr Kunde über das, was wir hier wirklich bekämpfen.", progress = nil, completion = "Die Soldaten, die Ihr befreit habt, konnten uns einiges berichten. Diese Monster nennen sich 'Vrykul'. Der Stamm, der sich in Wyrmskol niedergelassen hat, wird von einem Mystiker namens Yanis angeführt, ein Untergebener von Ingvar dem Brandschatzer - auch ein Vrykul.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11256] = {title = "Skorn muss fallen!", objective = "Häuptling Aschtotem möchte, dass Ihr das Emblem der Winterhufe in Skorn benutzt und dann mit dem Helden der Winterhufe sprecht.\n\nBereitgestellter Gegenstand: \n", description = "<Name>, gen Süden befindet sich die Vrykulfestung Skorn. Die seltsamen Riesen, die dort wohnen, sind vor Kurzem erwacht und haben damit begonnen, uns anzugreifen, wo auch immer es ihnen möglich ist.\n\nMeine Späher berichten mir, dass sie kurz davor sind uns hier anzugreifen. Wir sind jedoch nicht stark genug, um solch eine Streitmacht abzuwehren. Stattdessen werden wir uns aufmachen und gen Norden, in weniger gefährliche Lande, ziehen.\n\nIch bitte Euch, dass Ihr Euch etwas Schlaues einfallen lasst, um uns etwas Zeit zu verschaffen. Einen Mutigen, der über Näheres in Kenntnis gesetzt ist, habe ich schon vorgeschickt. Wenn Ihr dieses Emblem in Skorn vorzeigt, wird er sich zeigen und Euch so gut wie möglich zur Seite stehen.", progress = nil, completion = "Es wird interessant sein, an Eurer Seite zu kämpfen und etwas über Euer Volk zu lernen, &lt;Klasse&gt;.\n\nWollen wir fortfahren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11257] = {title = "Grausam, aber notwendig", objective = "Der Held der Winterhufe möchte, dass Ihr mit der Machete des Kriegerhelden 20 Vrykul des Winterskornstammes in Skorn zerstückelt.", description = "Unsere Ältesten erzählen uns, dass die Vrykul womöglich von den Toten auferstehen können - ähnlich den wandelnden Toten, die Ihr Geißel nennt, doch eine andere Art des Untodes.\n\nWir sollten kein Risiko eingehen.\n\nHier, nehmt meine Machete. Wir werden durch diesen Ort ziehen und Ihr zerstückelt die Überreste der von uns erschlagenen Vrykul.\n\nIch habe den ganzen Morgen damit verbracht, sie zu schärfen - sie sollte also selbst den dicksten Knochen spalten.", progress = nil, completion = "Habt Ihr das schon einmal gemacht? Ihr scheint im Umgang mit der Machete geübt zu sein.\n\n&lt;Der Held sieht Euch misstrauisch an.&gt;\n\nIch werde sie Euch jetzt wieder wegnehmen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11258] = {title = "Brenne, Skorn - brenne!", objective = "Der Held der Winterhufe schlägt vor, dass Ihr mit der Fackel des Helden die zwei Langhäuser im Nordosten und -westen und die Baracken in Skorn in Brand setzt.", description = "Häuptling Aschtotem hat mir befohlen, viele Gebäude hier zu zerstören.\n\nIhr habt aber die Verantwortung, also ist es auch Eure Aufgabe, <Name>.\n\nIch schlage vor, wir brennen die zwei Langhäuser und die Baracken ab, die im tieferen Bereich von Skorn stehen. Alles, was wir zu tun haben, ist in jedes hinein zu gehen und sie mit dieser Fackel in Brand zu stecken.", progress = nil, completion = "&lt;Der Held nickt Euch zu, von Eurem guten Umgang mit der Fackel überzeugt&gt;\n\nLasst diese Vrykul die Hitze dieses Landes spüren. Lasst sie die Furcht kennenlernen, die sie anderen aufzwingen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11259] = {title = "Türme des sicheren Untergangs", objective = "Der Held der Winterhufe meint, dass es sinnvoll wäre, wenn man mit dem Leuchtsignal des Kriegerhelden die Türme in Skorn für Luftangriffe markiert.", description = "Wenn wir durch Skorn ziehen, müssen wir die Türme zerstören.\n\nWenn Ihr sie Euch genau anseht, dann werdet Ihr feststellen, dass sich viele Zauberer auf den Türmen befinden. Sich zu nah heranzuwagen bedeutet den sicheren Tod.\n\nWir können jedoch Windreiterunterstützung aus dem Lager der Winterhufe anfordern. Um das zu tun, müssen wir nahe genug herankommen und ein Leuchtsignal auf die Stelle schießen, wo sich die Magier befinden.\n\nKommt nur nicht zu nah ran.", progress = nil, completion = "Ihr habt einen starken Arm, &lt;Name&gt;.\n\nSieht so aus, als würden sich die Windreiter endlich einmal nützlich erweisen anstatt den ganzen Tag nur rumzustehen und zu trinken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11260] = {title = "Verhindert seinen Aufstieg!", objective = "Präsentiert die Vrykulrolle des Aufstiegs in der Nähe des Scheiterhaufens vor der Hütte des Thans, um ihn herauszurufen und ihn niederzustrecken. Ihr seid Euch sicher, dass Großmutter Ankha an dem Ritual und damit auch an der Schriftrolle Interesse finden wird. Sie befindet sich im Lager der Winterhufe.", description = "Diese riesige Schriftrolle ist aus Drachenhaut gefertigt. Ihr entrollt die mehr als zehn Meter lange Schriftrolle und seht, dass die Bilder auf ihrer schuppigen Oberfläche ein rätselhaftes Vrykulritual darstellen.\n\nEin Than der Vrykul, umgeben von engelhaften Wesen, steigt in den Himmel auf. Eine rätselhafte finstere Figur zeichnet sich vom Hintergrund des Bildes ab.\n\nIhr habt eine ungute Vorahnung, dass der Than von Skorn im Begriff ist, genau dies zu tun. Ihr müsst das verhindern! Vor der Hütte des Thans, auf Skorns höchstem Punkt, steht ein großer Scheiterhaufen.", progress = "Ja? Wie kann ich Euch behilflich sein, Kind?", completion = "Ja, dies könnte Unheil bedeuten. Ihr habt offenbar richtig gehandelt.\n\nDanke, dass Ihr mir diese Schriftrolle gebracht habt. Ich werde herausfinden, was sie zu bedeuten hat. Würde ich es wagen, eine Vermutung anzustellen, dann würde ich behaupten dass die Vrykul einen Weg haben, um den Tod zu überwinden. Oder zumindest diejenigen, die dessen würdig sind.\n\nIndem Ihr den Than der Winterskorn besiegt habt, habt Ihr bewiesen, dass er unwürdig war. Nur das Licht weiß, was aus ihm geworden wäre und welch Schrecken er über uns gebracht hätte, hättet Ihr ihn nicht erschlagen.", rewards = "Geschmeidige RehhautmokkasinsVerjüngende KordelSchockgebundene SchiftungOnyxhandschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11261] = {title = "Der Bezwinger von Skorn!", objective = "Bringt das Zeichen der Winterhufe zu Häuptling Aschtotem im Lager der Winterhufe zurück.", description = "Ihr habt alles getan, wofür wir hierher ausgesandt wurden, <Klasse>. Ich muss zugeben, dass Ihr gut kämpft. Eure Leute sind nicht so merkwürdig, wie ich es zu Anfang dachte.\n\nHäuptling Aschtotem will sicherlich von Eurem Erfolg erfahren, aber solltet Ihr Euch entscheiden aus irgendeinem Grund hier zu bleiben, werde ich weiter an Eurer Seite kämpfen.", progress = "Welche Neuigkeiten aus Skorn bringt Ihr, <Name>?", completion = "Das sind in der Tat gute Neuigkeiten! Ihr habt uns etwas mehr Raum zum Atmen verschafft, nun können wir unsere Abreise weiter vorbereiten.\n\nBitte, nehmt etwas davon als Zeichen unserer Wertschätzung.", rewards = "Rankengewebte TunikaSonnenfeuerschreiterSchieferplattenarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nKrafterfüllter Anhänger\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11262] = {title = "Ingvar muss sterben!", objective = "Dunkelläuferin Marrah möchte, dass Ihr Ingvar den Brandschatzer in Burg Utgarde tötet.", description = "Von unserer gesamten Aufklärungstruppe bin nur ich übrig geblieben.\n\nDiese Vrykul sind erbarmungslose Kämpfer. Angesichts ihrer Zahl und brutalen Taktiken ist es unsere einzige Hoffnung, ihren Anführer zu erschlagen. Beten wir dafür, dass sie das ins Chaos stürzen wird.\n\nIngvar ist sein Name. Bringt mir seinen Kopf!", progress = "Das ist sozusagen nur die Spitze des Eisbergs.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Nun da sie keinen Anführer mehr haben, sollte unser Kampf gegen die Vrykul von größerem Erfolg gekrönt sein.\n\nDienste wie dieser dürfen nicht unbelohnt bleiben!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des HenkersRing der DezimierungSignet des schnellen Richturteils\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11263] = {title = "Mit Gjalerbron fertigwerden", objective = "Häuptling Aschtotem hat Euch gebeten, 15 Krieger von Gjalerbron, 8 Runenmagier von Gjalerbron und 8 Schlafwächter von Gjalerbron zu töten. Kehrt im Anschluss zu ihm im Lager der Winterhufe zurück.", description = "Meine Fernläufer, die überlebten und zurückkehren konnten, haben mir berichtet, dass die Vrykul in ihrer Hauptfestung im Westen erwacht sind.\n\nEs ist ein verbotener Ort, der als Gjalerbron bekannt ist. Die Langläufer sagen, dass die Vrykul dort seltsame Rituale durchführen.\n\nWir können nicht gestatten, dass das so weitergeht.\n\nWärt Ihr bereit, uns weiter zu unterstützen? Werdet Ihr die Vrykul am Gjalerbron töten, bevor sie ihr Vorhaben beenden und uns hier angreifen?", progress = nil, completion = "Ihr habt meinen Dank, &lt;Name&gt;. Ich weiß, dass Ihr weder mir noch meinem Volk verpflichtet seid.\n\nWas Ihr über diesen Ort sagt, besorgt mich noch immer und ich spüre, dass unser Feldzug noch nicht beendet ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11264] = {title = "Nekrogroßfürst Mezhen", objective = "Tötet Nekrogroßfürst Mezhen. Kehrt danach zu Häuptling Aschtotem im Lager der Winterhuf zurück.", description = "Die Toten sind am Gjalerbron und sie haben Nekromanten bei sich?\n\nWir müssen den Anführer dieser Nekrolords beseitigen.\n\nWie auch immer Ihr es fertig bringt, <Name>, aber stellt sicher, dass Nekrogroßfürst Mezhen und sein Vorhaben ausgelöscht werden.\n\nWir können es uns nicht leisten, dass die Vrykul Erfolge verbuchen, was auch immer sie mit diesen Untoten anstellen!\n\nGeht zur Plattform in der hinteren rechten Ecke von Gjalerbron, dort werdet Ihr Mezhen finden.", progress = nil, completion = "&lt;Häuptling Aschtotem atmet erleichtert durch.&gt;\n\nDas sollte den Druck etwas mildern.\n\n&lt;Name&gt;, wieder und wieder habt Ihr Euren Wert für das Lager der Winterhufe bewiesen. Bitte, wählt etwas von unseren Gaben. Ich bestehe darauf.", rewards = "WorghautschulternDämmerverflochtene GamaschenGoldbelegter KaltstahlgurtTuch der HochherzigkeitIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11265] = {title = "Von Schlüsseln und Käfigen", objective = "Großmutter Ankha möchte, dass Ihr genug Schlüssel für einen Gjalerbronkäfig sammelt, um 10 Gefangene von Gjalerbron zu befreien. Kehrt zu ihr zurück, sobald Ihr damit fertig seid. Sie befindet sich im Lager der Winterhufe.", description = "Das Wenige, was wir wissen, ist, dass die Vrykul im westlich gelegenen Gjalerbron abscheuliche Riten durchführen, die Teil einer Art Erweckungsrituals sind.\n\nSie bedienen sich lebendiger Opfer für ihre Rituale.\n\n<Name>, Ihr müsst dem ein Ende bereiten! Es kommt nicht darauf an, wer oder was in diesen Käfigen ist - egal was, es muss befreit werden. Ich wette, dass die Vrykul die Schlüssel bei sich tragen.\n\nDie Vrykul stellen eine Gefahr für uns dar, und das Letzte, was wir gebrauchen können, sind noch mehr dieser seltsamen Kreaturen - oder schlimmer: dass sie Etwas erwecken, das noch böser ist...", progress = nil, completion = "Mir fällt ein großer Stein vom Herzen, zu hören, dass Ihr erfolgreich wart. Und es bereitet mir Freude zu wissen, dass einige der Befreiten Taunka sind.\n\nBitte, nehmt dies als Gegenleistung für Eure Taten. Ich werde mich um die Wunden der Befreiten kümmern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11266] = {title = "Angriffspläne von Gjalerbron", objective = "Übergebt die Angriffspläne von Gjalerbron an Celea Frostmähne. Sie befindet sich im Lager der Winterhufe.", description = "In diesen Plänen wird ein unmittelbar bevorstehender Angriff auf das Lager der Winterhufe bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm Glacion, der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden.\n\nCelea Frostmähne könnte in dieser Sache sicherlich behilflich sein. Überbringt ihr die Pläne. Ihr findet sie im Lager im Osten.", progress = "Was?! Pläne für einen Angriff auf unser Lager?\n\nEIN ANGRIFF AUS DER LUFT?! EIN GROSSER WYRM?!!!", completion = "&lt;Name&gt;, wir dürfen das nicht zulassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11267] = {title = "Der Frostwyrm und sein Meister", objective = "Erschlagt Wyrmrufer Elend und benutzt das Wyrmruferhorn, um Glacion herbeizurufen und ihn niederzustrecken. Kehrt anschließend gemeinsam mit dem Horn zu Celea Frostmähne zurück. Sie befindet sich im Lager der Winterhufe.", description = "Das hier zu mir zu bringen, war die richtige Entscheidung – Euer Instinkt hat Euch gut beraten. Meine Windreiter würden jedoch mit einem Drachen nicht fertigwerden. Ihr müsst zum westlich gelegenen Gjalerbron gehen und den Wyrm und seinen Meister, Wyrmrufer Elend, niederstrecken.\n\nDer Frostwyrm könnte sich schon auf den Weg gemacht haben!\n\nWenn ich die Pläne jedoch richtig verstehe, dann wird Glacion zurückgerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst. Vernichtet die Kreatur, nachdem sie gelandet ist!\n\nUnd <Name>: Bitte bringt mir das Horn. Wir würden es nicht gerne sehen, wenn es wieder in falsche Hände geraten sollte.", progress = "Ist der Angriff abgewehrt? Wurden der Frostwyrm und sein Meister vernichtet?\n\nHabt Ihr das Horn zurückgebracht?", completion = "Dieses Horn ist so kalt wie das Land... vielleicht sogar kälter!\n\nIhr habt das Lager der Winterhufe vor seinem sicheren Untergang bewahrt - was jedoch nicht heißen soll, dass wir hier noch viel länger bleiben werden. Was für ein eigenartiger Mann Ihr seid, &lt;Name&gt;. Vielleicht ist Euer Volk von der anderen Seite des Ozeans im Grunde genommen doch nicht so böse.\n\nDas verlangt nach einer Belohnung. Was würdet Ihr vorziehen?", rewards = "ErdbrunnenfußlappenMagiespitzenhelmSilberstahlstulpenAuf Euch wartet eine dieser Belohnungen:\n\nVerlorenes Vrykulabzeichen\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11268] = {title = "Die wandelnden Toten", objective = "Tötet 10 ewige Beobachter, 4 furchterregende Schrecken und 2 eitrige Kreaturen. Bringt anschließend Nachricht Eures Erfolgs zu Großmutter Ankha im Lager der Winterhufe.", description = "Ihr wart uns eine riesengroße Hilfe, <Name> - es gibt jedoch Etwas, das mir Sorgen bereitet: die sogenannte Geißel.\n\nDie Geister der Erde und Luft, des Wassers und des Feuers im Inneren der Welt würden zwar ihre Anwesenheit nicht dulden, scheinen jedoch nichts dagegen zu unternehmen. Wir werden dafür sorgen, dass man sich um sie kümmert!\n\nVielleicht ist es zu viel verlangt, aber ich hätte es gerne, dass Ihr zurück gen Westen nach Gjalerbron geht und die unnatürlichen Kreaturen der Geißel in diesem abscheulichen Nest vernichtet. Seht zu, dass Ihr auch in den Hallen des Erwachens unter Gjalerbron nachseht!", progress = nil, completion = "&lt;Die Großmutter nickt zustimmend angesichts Eurer Taten.&gt;\n\nIch danke Euch, &lt;Name&gt;, Ihr habt das Richtige getan und uns damit ein wenig mehr Zeit verschafft, um unseren Abmarsch vorzubereiten. Wir werden schon bald gen Norden ziehen.\n\nIch bin zu alt - wenn es soweit ist und wir gehen, werde ich nicht alles mit mir tragen können. Hättet Ihr hiervon gerne etwas?", rewards = "Majestätische PantalonsStammesbrustharnischLehmbefleckte SchienbeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nWorgzahnanhänger\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11269] = {title = "Daunen in letzter Minute", objective = "Gil Grisert möchte, dass Ihr ihm 10 Büschel Daunen eines gefleckten Hippogryphen bringt.", description = "Die Vorhut der Truppen der Allianz wird in ein paar Tagen eintreffen. Die Soldaten werden ihre Winterausrüstung erwarten und ich hab' noch nicht alle Umhänge angefertigt, die sie benötigen.\n\nFür das Futter der Umhänge verwende ich die Daunen von gefleckten Hippogryphen, doch mein Vorrat wird nicht ausreichen!\n\nIhr müsst mir helfen, <Name>. Hauptmann Adams wird sich mir vorknüpfen, wenn die Umhänge nicht rechtzeitig fertig sind! Bringt mir alle Daunen, die Ihr dort draußen finden könnt. Sie werden von mausernden Hippogryphen, die in der Wildnis um das Fort herum anzutreffen sind, fallengelassen.", progress = "Habt Ihr mir ein paar Daunen gebracht? Ich könnte sie wirklich gut gebrauchen...", completion = "Gott sei Dank! Dies sollte genügen, um die bestellten Umhänge noch rechtzeitig herzustellen. Bevor die Truppen ankommen, werde ich natürlich keinen Schlaf finden, doch das ist noch immer um einiges besser, als Hauptmann Adams' Zorn ertragen zu müssen.\n\nIch kenne die Geschichten, die man über ihn erzählt!", rewards = "Kunstvoll gefertigte GamaschenSangschuppenbrustplatteKaltgeschmiedete Beinplatten aus BronzeAuf Euch wartet eine dieser Belohnungen:\n\nSchimmerndes Kalteisenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11270] = {title = "Krieg ist die Hölle", objective = "Hochexekutor Anselm im Hafen der Vergeltung möchte, dass Ihr mithilfe der brennenden Fackel 10 der Leichen, die westlich des Orts herumliegen, verbrennt.", description = "Wir beseitigen langsam die Überbleibsel von Sturmwinds Nordflotte, die an dieser Küste vor Anker lag. Die Leichen im Westen sind ein Zeichen dafür, wie brutal die Konfrontation gewesen ist.\n\nEs berührt zwar meinen feinen Sinn für Ästhetik nicht im Geringsten, stellt jedoch eine Gefahr für unser aller Leben dar.\n\nIm Reich des Lichkönigs sind die Toten eine Waffe, die jederzeit gegen uns verwendet werden kann. Nehmt diese Fackel - Ihr werdet dafür sorgen, dass das nicht geschieht.", progress = nil, completion = "Ich bin froh, dass Ihr Befehle befolgen könnt. Wenn man mir ein Kupferstück für jeden arroganten Narren in glänzender Rüstung gäbe, der hierher kommt und denkt, dass er tun und lassen kann, wie ihm beliebt... tja, dann hätte ich schon ein paar Goldstücke beisammen.\n\nNun, da Ihr einen gewissen Grad an Disziplin bewiesen habt, hätte ich ein paar Aufgaben anzubieten, die für jemanden wie Euch besser geeignet wären.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11271] = {title = "Hastige Vorbereitungen", objective = "Ahota Weißfrost im Lager der Winterhufe möchte, dass Ihr ihm 10 Büschel Daunen eines gefleckten Hippogryphen bringt.", description = "Die Daunen des gefleckten Hippogryphen werden von meinem Volk hoch geschätzt und werden bei uns für alles verwendet - von der Pfeilmacherei, bis hin zu zeremoniellen Gewändern. Wir bereiten uns darauf vor, diesen Posten zu verlassen, also ist das meine letzte Chance in dieser Saison, sie zu sammeln.\n\nMit Eurer Hilfe werde ich genug zusammenbekommen, um jedem die nötige Ausrüstung für den Marsch durch die Hügel bieten zu können. Die Bedingungen verschlechtern sich sehr schnell dort oben und jederzeit könnte ein Sturm ohne Vorwarnung aufziehen.\n\nDie Daunen liegen rings um den Posten herum auf dem Boden.", progress = "Habt Ihr schon ein paar Daunen gesammelt?", completion = "Dank Eures Beitrags werden wir gut auf die Reise vorbereitet sein. Ich habe nicht viel, das ich Euch für Eure Hilfe anbieten könnte, aber ich werde Euch etwas aus meiner übrigen Kampfausrüstung aussuchen lassen.", rewards = "Kunstvoll gefertigte GamaschenSangschuppenbrustplatteKaltgeschmiedete Beinplatten aus BronzeAuf Euch wartet eine dieser Belohnungen:\n\nSchimmerndes Kalteisenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11272] = {title = "Eine Rechnung begleichen", objective = "Hochexekutor Anselm möchte, dass Ihr Prinz Keleseth in Burg Utgarde tötet.", description = "Glaubt dieser Elfenprinz etwa, dass er in meine Stadt kommen, meine Königin beleidigen, meine Leute töten und mit all dem davonkommen kann? Glaubt er, dass wir untätig zusehen werden, wenn Utgardes Horden sich auf einen Angriff vorbereiten?\n\nNicht in einer Million Jahre.\n\nIhr werdet direkt nach Utgarde gehen und ihn töten. Ich will, dass Arthas von unserer Ankunft erfährt und weiß, dass wir es ernst meinen.\n\nMeldet Euch bei der Dunkelläuferin Marrah in der Burg Utgarde, wenn Ihr die Tat vollbracht habt, und sie wird sich um eventuelle Folgen kümmern.", progress = "Habt Ihr etwas zu berichten, <Name>?", completion = "Rache ist süß. Und dies ist nur ein Vorgeschmack dessen, was Arthas noch bevorsteht.\n\nEr wird früh genug das bekommen, was er verdient hat. Dann und nur dann werde ich glücklich sterben können.", rewards = "Wickel der San'laynVendettabindungenArmschienen des RunenmagiersUnterarmschienen des VergeltungsbringersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11273] = {title = "Die Menschenliga", objective = "Sucht Wyrmskol nach Pulroy ab.", description = "Wir waren kurz davor, einen sensationellen archäologischen Fund zu machen, als wir von diesen Monstern angegriffen wurden! Leider war ich der Einzige, der es zurück nach Valgarde schaffte. Nun weiß ich nicht, ob meine Mannschaft tot oder am Leben ist, aber die Artefakte, die wir damals ausgruben, müssen gefunden werden!\n\nFalls Ihr nach Wyrmskol gehen solltet, würdet Ihr dann nach meiner Mannschaft Ausschau halten? Wenn es noch Hoffnung gibt, dass die Informationen geborgen werden können, müssen wir versuchen, sie zurückzubekommen!\n\nSucht zuerst nach Pulroy. Ihn habe ich als letzten gesehen, bevor ich flüchtete.", progress = nil, completion = "Ihr habt Pulroy gefunden - jedoch ein wenig zu spät wie es aussieht.\n\nWährend Ihr den Leichnam genauer betrachtet, fällt Euch ein Tagebuch auf, das fest von Pulroys totenstarrer Hand umklammert wird. Ihr seht Euch das Buch genauer an und stolpert über Etwas, das wie das Gekritzel eines sterbenden Zwergs aussieht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11274] = {title = "Zedd ist wahrscheinlich tot", objective = "Sucht Wyrmskol nach Zedd ab.", description = "An den Finder dieses Tagebuchs:\n\nDiese blutrünstigen Scheusale haben sich in den Ruinen von Wyrmskol eingenistet. Was genau sie wollen und wieso sie hier sind, ist ein Rätsel. Auf jeden Fall sind die Artefakte nicht sicher, solange sich diese Menschenbestien hier herumtreiben.\n\nZedd und ich haben etwas entdeckt, als wir uns versteckt haben: eine Glyphe, mit der man die Schrifttafeln entziffern kann! Unglücklicherweise wurden Zedd und ich letzte Nacht voneinander getrennt. Er hatte die Glyphe. Glorenfeld und Daegarn hatten die Schrifttafeln bei sich. Wo sie sind, weiß ich nicht...\n\nFindet Zedd.\n\n-Pulroy", progress = nil, completion = "Ihr habt Zedd gefunden. Ihr seid zwar kein Doktor, aber die Prognose für Zedd würde sicherlich negativ ausfallen.\n\nEs sieht so aus, als hätten sie versucht, ihn an die Worge zu verfüttern. Scheußlich...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11275] = {title = "Das Horn schnitzen", objective = "Nokoma Schneeseher im Lager der Winterhufe möchte, dass Ihr ihr 6 unbeschädigte Widderhörner bringt.", description = "Mein Volk jagt schon seit Generationen die Riesenyeti in diesen Hügeln und dieses Jahr werde ich zum ersten Mal daran teilnehmen. Es wird wahrscheinlich die letzte Jagd sein, bevor wir den Posten für immer verlassen.\n\nUm mich auf die Jagd vorzubereiten, muss ich ein lautes Blashorn aus den Geweihen der Frosthornböcke herstellen, die durch die verschneite Gegend in der Nähe unseres Lagers streifen. Die Ältesten meinen, dass der Ton des Horns dem Paarungsruf der weiblichen Yetis ähnelt, aber ich hab' da so meine Zweifel.\n\nBringt mir die besten Hörner der Frosthornböcke, die Ihr finden könnt, <Name>, und ich werde mir eines davon aussuchen.", progress = "Habt Ihr brauchbare Hörner finden können?", completion = "All diese Hörner sind großartig, &lt;Name&gt;. Lasst sie mich einmal näher betrachten, damit ich mir dasjenige aussuchen kann, welches ich auf der Jagd benutzen werde.\n\nDen Rest gebe ich dann den Handwerkern, damit sie daraus etwas schnitzen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11276] = {title = "Und da waren es Zwei...", objective = "Sucht in den Katakomben von Utgarde nach Glorenfeld.", description = "Ihr untersucht Zedd, doch von der Glyphe fehlt jede Spur. Nachdem Ihr überall in der Gegend nachgesucht habt, entdeckt Ihr ein paar auf den Boden geschriebene Zeichen:\n\n\"Glor und Dae in den Katakomben. Haben Glyphe und Tafeln.\"\n\nVielleicht solltet Ihr Euch in die Katakomben im Norden begeben und nach Glorenfeld und Daegarn suchen. Die Brücke über die Worgengrube wird Euch direkt zum Tunnel und zum Eingang der Katakomben führen.", progress = nil, completion = "Wurde verdammt noch mal Zeit! Pulroy und Zedd sind tot.\n\nUnd Daegarn...\n\n&lt;Glorenfeld schüttelt den Kopf.&gt;\n\nEr wurde vom Anführer der Drachenschinder gefangen genommen und Tief ins Innere der Katakomben verschleppt. Ich konnte mitanhören, wie dieser zu groß geratene Bastard etwas über ein Opfer an den \"Schreckenskönig\" sagte.\n\nDaegarn hat die Glyphe in seinem fettigen Bart versteckt.\n\nWie bitte? Zwerge verstecken immer Dinge in ihrem Bart!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11277] = {title = "Die Tiefen des Anrüchigen", objective = "Glorenfeld in den Katakomben von Utgarde möchte, dass Ihr 10 Wyrmskoltafeln einsammelt.", description = "Sie halten Daegarn in 'nem Käfig im großen Kampfring gleich hier in der Nähe gefangen. Soviel ich mitbekommen habe, lassen die Drachenschinder ihre Gefangen gegen ihre stärksten Gladiatoren kämpfen. Die Verlierer werden danach ins untere Geschoss geworfen, um dort von Nekromanten der Geißel in Ghule verwandelt zu werden! Grauenhaft ist das!\n\nAber eins nach dem anderen! Die Tafeln liegen überall im Kerker verstreut. Lasst uns die erstmal einsammeln, bevor Ihr versucht, den Helden zu spielen.", progress = "Überprüft jede Nische und Ritze!", completion = "Gut gemacht, mein Freund. Da wir nun die Tafeln in Händen halten, können wir versuchen Daegarns Leben zu retten und die Glyphe zurückzubekommen, damit wir endlich das Geheimnis dieser uralten Relikte lüften können!\n\nIch behalte erst einmal die Tafeln und Ihr befreit Daegarn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11278] = {title = "Rückkehr nach Valgarde", objective = "Bringt Glorenfelds Päckchen zu Beltrand McSorf im Hafen von Valgarde.", description = "Was für 'ne Schande, dass wir zwei unserer besten Zwerge bei der Ausgrabung der Relikte verloren haben. Sie gaben ihr Leben hin, um diese Kunde sicher zu verwahren.\n\n<Glorenfeld wickelt die Glyphe und Tafeln in einen Lumpen Stoff ein.>\n\nBringt sie nach Valgarde zurück. McSorf wird wissen, was mit diesem Fund zu tun ist.\n\nWas mich angeht? Ich werde alleine schon zurechtkommen - bin schließlich in einem Stück bis hierhergekommen!", progress = "Ihr seid zurück!", completion = "Diese Tafeln zu sortieren, wird einige Zeit dauern. Alles, was ich bei einer ersten Untersuchung herausfinden konnte, ist, dass das, was auch immer einmal hier gewesen ist, ein Vorfahre der Menschen war. Diese Vrykuldinger haben sie wahrscheinlich bis auf den letzten umgebracht. Wie immer dem auch sei, wir werden mehr wissen, sobald ich diese Relikte geordnet habe.", rewards = "SpannbalgschiftungWickeltücher des DiakonsStromlinienförmige StampferGereinigte TirasianplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11279] = {title = "Grüne Eier und Welpen", objective = "Seuchenbringer Tillinghast möchte, dass Ihr 10 Exemplare verseuchter Protowelpen einsammelt und sie anschließend bei ihm abliefert. Er befindet sich in Neu-Agamand.", description = "Diese neue Seuche, an der wir gerade arbeiten, ist formidabel. Ich denke, wir sollten ihre Tests ausweiten.\n\nWie wäre es damit, sie an den Proto-Welpen auszuprobieren?!\n\nStellt Euch nur die Möglichkeiten vor. Wir könnten nicht nur Humanoide, sondern alle Kreaturen anstecken!\n\nHier, ich habe mir einen Seuchenkanister für den richtigen Zeitpunkt aufbewahrt - und Ihr scheint mir die richtige Person zu sein.\n\nBesprüht damit die Eier in der Glutstätte im Nordwesten und fangt anschließend ein paar Exemplare der ausgeschlüpften verseuchten Proto-Welpen ein.", progress = "Wie soll ich ohne diese Proben herausfinden, ob dieser letzte Stamm unseres Erregers auf alle möglichen Kreaturen angewandt werden kann?", completion = "Was?! Nein, das kann nicht stimmen.\n\nVERDAMMT!\n\nDiese Version der Seuche scheint die Protowelpen bis auf den grünen Leuchteffekt nicht wirklich zu beeinflussen!\n\nMein Traum davon, alles was wir berühren mit der Seuche anzustecken, scheint sich in Luft aufgelöst zu haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11280] = {title = "Draconis Gastritis", objective = "Seuchenbringer Tillinghast in Neu-Agamand möchte, dass Ihr mit Tillinghasts verseuchtem Fleisch einen Protodrachen anlockt und verfolgt, wie er auf das gefressene Zeug reagiert.", description = "Wartet, da kommt mir eine Idee! Was wäre, wenn die Welpen nur deswegen nicht gestorben sind, weil sie auf die Schale der Eier gesprüht wurde?\n\n<Name>, wir müssen die Seuche irgendwie in sie hineinbekommen!\n\nIch weiß! Ich habe hier ein wenig verseuchtes Fleisch. Nehmt es, geht zur Glutstätte und bringt sie dazu, es zu fressen!\n\nHalt, wir denken hier nicht groß genug. Bringen wir einen der Protodrachen, die hoch am Himmel fliegen, dazu, herunterzukommen und es zu essen.\n\nGenau!\n\nBleibt in der Nähe des Fleischs und betrachtet das Geschehen. Ja, es könnte Euch angreifen - aber das ist nun mal der Preis des Fortschritts.", progress = nil, completion = "NEEEEIIIIIIIN!\n\n&lt;Der Seuchenbringer fängt an zu weinen.&gt;\n\nAlle meine Hoffnungen... alle meine Träume - zerstört!\n\nGeht, &lt;Name&gt;. Geht und überlasst mich meinem Trübsal. Ich bin ein Nichts.\n\nHier, Ihr könnt ebenso gut all mein Hab und Gut an Euch nehmen. Wenn der Rest der Apotheker von meinem Versagen erfährt, dann bin ich sowieso erledigt und werde es nicht mehr brauchen.", rewards = "Indigorobe der ErfrischungEisenbeschlagene GamaschenVerschränkter KettengurtWohltuende SchädelkappeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11281] = {title = "Den Ruf der Natur nachahmen", objective = "Testet das geschnitzte Horn und kehrt anschließend mit den Ergebnissen zu Nokoma Schneeseher im Lager der Winterhufe zurück.", description = "Die grobe Form des Horns ist nun fertig, doch bevor ich die traditionellen Muster in die Oberfläche kerbe, möchte ich sichergehen, dass es auch funktioniert. Ahota hat mir gesagt, dass er seine Hörner immer am Fuße des gefrorenen Wasserfalls nördlich des Lagers testet. Er hat mir auch gesagt, dass unsere Jäger die Akustik des gefrorenen Wassers schon seit Generationen zu diesem Zweck verwenden. Ich kann es kaum erwarten, noch mehr darüber zu erfahren!\n\nWerdet Ihr mir dabei helfen, das Horn zu testen? Wenn ich alles richtig gemacht habe, dann werdet Ihr sogar einen Yeti anlocken - also macht Euch darauf gefasst! Bringt das Horn zurück, sobald Ihr es getestet habt.", progress = nil, completion = "&lt;Nokoma hört sich Euren Bericht über den Test an.&gt;\n\nDa bin ich erleichtert, dass das Horn so gut funktioniert hat... vielleicht etwas zu gut, wenn das, was Ihr sagt, stimmt. Seid Ihr Euch sicher, dass das Biest gesprochen hat? Wenn das wahr sein sollte, dann bin ich mir nicht sicher, ob ich mit auf die Jagd gehen kann. Ich werde mit Häuptling Aschtotem darüber sprechen müssen.\n\nKann sein, dass dieses Horn am Ende nur dekorativen Zwecken dienen wird - was seinen Wert jedoch nicht mindert. Vielen Dank für Eure Hilfe, &lt;Name&gt;.", rewards = "Gholamgewirkter WickelBeschriftete WorgfelltreterBerufene SchuppenpanzergamaschenAuf Euch wartet eine dieser Belohnungen:\n\nBraxleys Hinterhoffusel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11282] = {title = "Eine Lektion in Sachen Angst", objective = "Gorth möchte, dass Ihr Ulf den Aderlasser, Oric den Elenden und Gunnar Thorvardsson tötet und das Banner der Verlassenen durch ihre Körper rammt. Erschlagt solange Vrykul auf der anderen Seite der Blockade der Verlassenen, bis die Drei auftauchen.", description = "Wenn du so viele Kämpfe gemacht hast wie Gorth, dann weißt du, dass man den Bösewichten sehr viel Angst machen muss, wenn man sie gut verhauen will!\n\nDiese Vrykul aber keine Angst. Du machst einen nieder, aber sofort kommt ein anderer... und der brüllt dann lauter und hat eine größere Waffe als der davor.\n\nDas Einzige, wovor Vrykul Angst haben, ist, wenn wir den größten und bösesten Vrykul von allen töten.\n\nGeh und murks so lange Winterskorn auf der anderen Seite der Blockade, bis Vrykulhelden auftauchen! Du machst sie dann alle tot und bohrst Flagge der Königin in sie hinein. Die müssen lernen, Angst zu haben!", progress = nil, completion = "Du hast dort drüben ein paar gute Murkser gemacht. Ich habe gesehen, wie Vrykul fallen und mit Sylvanas Flagge gestochen werden.", rewards = "Geerdete HoseVoodooverbundener StarkhelmSteinbodenspaltbeilAuf Euch wartet eine dieser Belohnungen:\n\nFlinkfingerband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11283] = {title = "Zahl der Toten in Quälheim", objective = "Unteroffizier Gorth möchte, dass Ihr nach Quälheim geht und 16 Vrykul des Winterskornstammes tötet.", description = "Vrykul kommen aus dem Ort da im Westen - hört gar nicht mehr auf und kein Ende in Sicht!\n\nGorth hat da eine Idee. Du gehst HINEIN in die Stadt und murkst Winterskorn. DANN werden sie nicht mehr rüberkommen!", progress = nil, completion = "Du musst viel Übung im Murksen haben. Du bist fast so gut wie Gorth!", rewards = "SpannbalgschiftungWickeltücher des DiakonsStromlinienförmige StampferGereinigte TirasianplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11284] = {title = "Der Yeti von nebenan", objective = "Vorarbeiter Colbey bei Fort Wildervar möchte, dass Ihr Schmetterhorn besiegt.", description = "Wenn die Schildwachen mir schon nicht helfen können, würdet Ihr? Ich bin der Vorarbeiter der Mine hinter der Brücke dort. Meine Männer schürfen Erz für die Waffen, die unsere Expeditionstruppe brauchen wird, um einen Pfad durch die Grizzlyhügel zu schlagen.\n\nEin riesiger Yeti ist in die Mine eingedrungen und blockiert den Tunnel, den wir brauchen, um weiter zu arbeiten! Wir haben versucht, ihn durch Schreie zu verscheuchen und aus seinem Unterschlupf zu vertreiben, aber nichts hat geholfen.\n\nVielleicht könntet Ihr ihn wecken, mit einer Portion Fleisch von den Frosthornböcken aus den schneebedeckten Gegenden um die Stadt herum? Bitte... Wir sind verzweifelt!", progress = nil, completion = "Ihr habt es geschafft? Beim Licht, Ihr seid ein wandelndes Wunder! Ich hatte mich schon mit dem Gedanken abgefunden, Hauptmann Adams persönlich erklären zu müssen, warum die Waffen seiner Männer nicht rechtzeitig fertig geworden sind.", rewards = "Gholamgewirkter WickelBeschriftete WorgfelltreterBerufene SchuppenpanzergamaschenAuf Euch wartet eine dieser Belohnungen:\n\nBraxleys Hinterhoffusel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11285] = {title = "Quälheim muss brennen!", objective = "Unteroffizier Gorth will, dass Ihr nach Quälheim geht und Gorths Fackel benutzt, um 1 Behausung der Winterskorn, 1 Wachturm der Winterskorn, 1 Brücke der Winterskorn und 1 Kaserne der Winterskorn in Brand zu stecken.", description = "Die Winterskorn töten vielleicht nicht genug. Vielleicht verbrennen wir einfach auch ihre Häuser! Eh... und ihre Brücken. Wir sollten sichergehen und die ganze Stadt mit Feuer kaputt machen!\n\nDu nimmst diese Fackel. Geh nach Quälheim, im Westen, und verbrenn ALLES! Wird ihnen eine Lehre sein.", progress = nil, completion = "Ich schätze, du hast alles mit Feuer kaputt gemacht. Ich seh' ein paar Stellen, die nicht brennen... aber für Gorth ist das nah genug.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11286] = {title = "Die Artefakte des Stählernen Tores", objective = "Weiser Nebelläufer möchte, dass Ihr 10 Artefakte vom Stählernen Tor aufsammelt. Kehrt zu ihm zurück, sobald Ihr alle habt. Er befindet sich am Stählernen Tor.", description = "Ich bin aus einem anderen Grund hier in dieser Gegend - ein alter Freund hat mich in meinen Träumen gerufen. Es bringt jedoch mein Blut zum Kochen, mit ansehen zu müssen, wie diese kleinen Dinger mit ihren Maschinen ein großes Loch in den Boden graben.\n\nSo wie ich das sehe, graben diese sogenannten Zwerge Artefakte aus - Artefakte, die wichtige Zeugnisse unserer Vergangenheit sein könnten.\n\nIch möchte, dass Ihr dort hinunter geht und diese Dinger zu mir bringt. Lasst Euch von keinem dieser Zwerge aufhalten.", progress = "Wie viele Artefakte habt Ihr an diesem Stählernen Tor finden und aufsammeln können?", completion = "&lt;Der Weise knurrt als Zeichen seiner Anerkennung für das, was Ihr auf sein Geheiß unternommen habt.&gt;\n\nVielleicht werde ich mir schon bald die Zeit nehmen können, um diese Artefakte zu untersuchen und herauszufinden, welche Bedeutung sie für uns haben.\n\nEs gibt jedoch wichtigere Angelegenheiten, um die wir uns jetzt kümmern müssen.", rewards = "Knisternder UmhangAuf Euch wartet eine dieser Belohnungen:\n\nSchonungsloses BandWorgzahntalisman\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11287] = {title = "Findet den Weisen Nebelläufer", objective = "Großmutter Ankha hat Euch gebeten nachzusehen, in welcher Verfassung sich der Weise Nebelläufer befindet. Sie glaubt, dass er sich am oder in der Nähe des Stählernen Tores befindet.", description = "<Verehrter/Verehrte:c> <Klasse>, ich mache mir zunehmend Sorgen um meinen Sohn Weiser Nebelläufer - er ist nun schon so lange fort. Das Land ist grausam und tödlich.\n\nEr sprach von einer immer wiederkehrenden Vision und brach dann mit einer kleinen Gruppe Fernläufer in Richtung Westen auf, um ihrem Ursprung nachzugehen. Er erwähnte einen Namen - 'Stählernes Tor', glaube ich, war es.\n\nWerdet Ihr nach ihm suchen? Ich möchte sichergehen, dass ihm auch nichts Schlimmes zugestoßen ist.", progress = nil, completion = "Meine Mutter soll sich keine Gedanken um meine Sicherheit machen. Ich danke Euch jedoch dafür, dass Ihr gekommen seid, Fremder.\n\nDa Ihr nun schon einmal da seid - könntet Ihr mir vielleicht bei ein paar Angelegenheiten helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11288] = {title = "Das strahlende Licht", objective = "Ares der Schwurgebundene in den Katakomben von Utgarde möchte, dass Ihr das geheiligte Artefakt bergt.\n\nDiese Aufgabe ist zeitlich begrenzt.", description = "<Ares liegt im Sterben. Er versucht zu sprechen und keucht.>\n\nIch bin ein Abgesandter des Argentumkreuzzugs und wurde mit einer heiligen Aufgabe beauftragt.\n\nUnsere Streitkräfte in den Pestländern wurden dezimiert. Mit dem Licht der Morgendämmerung, läuterten sie das Artefakt, machten es wieder rein. Die Erlösung... so viele gaben ihr Leben für sie.\n\nDoch es gibt immer noch Hoffnung... noch ist Zeit.\n\nDas Artefakt wurde in die Grube der Gefallenen geschleudert - tief unter uns, von den grausamen Toten bewacht.\n\n<Ares' Körper erglüht in einem blendenden Licht.>\n\nDas - Licht - wird - Euch - beschützen.", progress = "<Ares ist bewusstlos.>", completion = "Ihr fühlt Euch dazu verpflichtet, das heilige Schwert neben Ares zu legen.\n\nNachdem Ihr dies getan habt, werdet Ihr noch einmal vom Licht geblendet.", rewards = "Eisbereifter DolchSteinklingenschlitzerWelpenschädelschockerMajestätisches SzepterKaltstachellangbogenAusgedienter VrykulzerkracherIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11289] = {title = "Von Ehre geleitet", objective = "Bringt das geheiligte Artefakt zu Lord Irulon Wahrklinge zurück. Er befindet sich in Valgarde.", description = "<Ares lächelt.>\n\nEhre dem Licht. Ihr habt es geschafft!\n\n<Ares hustet.>\n\nNehmt das Artefakt und bringt es nach Valgarde zurück. Lord Irulon Wahrklinge erwartet dessen Rückkehr.\n\nKämpft mit Ehre. Immer - Ehre.\n\n<Ares stirbt.>", progress = "Beim Licht!", completion = "Viele Männer und Frauen mussten ihr Leben lassen, um dieses Schwert zu bergen. Ach, ich fürchte, dass der tapfere Ares nicht der Letzte sein wird.\n\nDoch aus Euren Taten spricht das Licht, o Held. Dieses heilige Schwert wird Lord Tirion Fordring höchstpersönlich tragen. Selbst jetzt arbeitet sich der Argentumkreuzzug zur Eiskrone vor. Lord Fordring hat geschworen, dass er die Mauern dieser verfluchten Stätte mit seinen eigenen Händen niederreißen wird! Und mit dem Schwert könnte er sich sogar gegen den Lichkönig behaupten.\n\nLord Fordring bleibt unsere größte Hoffnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11290] = {title = "Schlachtpläne der Drachenschinder", objective = "Vizeadmiral Keller im Hafen von Valgarde im Heulenden Fjord möchte, dass Ihr ihm die Schlachtpläne der Drachenschinder bringt.", description = "Wir konnten zwar nur sehr wenig über Ingvars Aufenthaltsort erfahren, doch was wir wissen, ist, dass Yanis in einer Höhle in der Nähe der Worggrube in Wyrmskol wohnt.\n\nInformationen, die wir von den geretteten Soldaten erhalten haben, deuten darauf hin, dass Yanis die Schlachtpläne der Drachenschinder bewacht.\n\nIch möchte, dass Ihr zurück nach Wyrmskol geht und diese Schlachtpläne beschafft.", progress = "Habt Ihr die Schlachtpläne der Drachenschinder bei Euch?", completion = "&lt;Vizeadmiral Keller überfliegt kurz die Pläne.&gt;\n\nHervorragend! So wie es aussieht, gibt es noch viel mehr Vrykuldörfer im Fjord. Ein anderer Vrykulstamm bereitet sich auf einen Angriff auf Westwacht vor. Verdammt! Soweit ich es beurteilen kann, ist es vielleicht schon zu spät. Wir haben seit Tagen keine Nachricht mehr aus Westwacht erhalten. So oder so - wir müssen Westwacht warnen!", rewards = "Kapuze der GüteKnochenbewehrter HarnischBlutbefleckte KettengamaschenNerubischer InnenpanzerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11291] = {title = "Auf nach Westwacht!", objective = "Bringt die Schlachtpläne der Drachenschinder zu Hauptmann Adams. Er befindet sich in Westwacht im Heulenden Fjord.", description = "<Vizeadmiral Keller rollt die Schlachtpläne aus.>\n\nWir wissen nun genug, um Valgarde weiterhin zu schützen. Ihr müsst diese Schlachtpläne nach Westwacht bringen. Westwacht befindet sich oben auf den Klippen im Westen des Fjords. Sprecht mit der Flugmeisterassistentin Emilune Winterwind. Sie wird Euch auf einen Greifen in Richtung Westwacht setzen.\n\nFindet Hauptmann Adams, sobald Ihr angekommen seid. Er hat dort das Sagen. Adams wird wissen, was mit diesen Plänen anzufangen ist.", progress = "Valgarde wurde nicht vernichtet? Welch Überraschung.\n\nMuss an unserer Hilfe gelegen haben. Keller hat damit sicherlich nichts zu tun.", completion = "&lt;Hauptmann Adams nimmt Euch die Pläne ab.&gt;\n\nIch freue mich, dass Ihr Euch dazu entschlossen habt, hierher zu kommen. Meine Berater und ich werden diese Pläne eine Zeitlang untersuchen. In der Zwischenzeit können wir jede Hilfe gebrauchen, die wir kriegen können!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11292] = {title = "Auf die Schwachen Jagd machen", objective = "Fallensteller Jethan in Fort Wildervar möchte, dass Ihr ihm aus 8 Fallen gefangene Beute bringt.", description = "Es freut mich, Euch kennenzulernen. Ich komme von den Grizzlyhügeln, um mit Euresgleichen Geschäfte zu machen. Mein Volk unterhält dort einen großen Außenposten. Ihr wärt gut damit beraten, ihn zu besuchen, falls Ihr nach Norden ziehen solltet.\n\nIch habe in den Wäldern und Schneegebieten in der Gegend Fallen aufgestellt. Mit dem Fleisch und Fell der Kreaturen, die in die Falle gehen, werde ich genug haben, um mit dem Stadtvolk Handel betreiben zu können.\n\nSolltet Ihr gewillt sein, mir dabei zu helfen die gefangene Beute zu sammeln, könnte ich Euch einen Teil meines Gewinns anbieten. Seid jedoch gewarnt: Dort draußen seid Ihr nicht das einzige Raubtier.", progress = "Ich hoffe, Ihr seid nicht mit leeren Händen zurückgekommen. Ich dachte, wir hätten ein Abkommen.", completion = "&lt;Fallensteller Jethan begutachtet die Kreaturen, die Ihr ihm gebracht habt.&gt;\n\nGut gemacht. Einige davon werden einen besseren Preis erzielen als andere - aber ich sollte genug haben, um mit den Ansässigen handeln zu können.", rewards = "Erderfüllte GamaschenFizzniks patentierte OhrenschützerArkanumschildStiefel des meisterlichen ArtilleristenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11293] = {title = "Marktschreier für die Gerstenbräus!", objective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", description = "Lasst alle wissen, dass die Gerstenbräus auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält! Ich werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder für 4 Minuten borge. Verwendet die Zügel, um ihn anzutreiben, aber achtet drauf, ihn nicht zu sehr zu erschöpfen.", progress = nil, completion = "Gut gemacht! Die Ankündigung wird unser Geschäft bestimmt ins Rollen bringen.\n\nWir hatten Euch ja auch eine Belohnung versprochen, hier ist sie. Die Gerstenbräus halten ihr Wort.\n\nOh, wenn Ihr die gute Kunde von den Gerstenbräus noch einmal verbreiten wollt, könnt Ihr gerne an einem anderen Tag wieder kommen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11294] = {title = "Marktschreier für die Donnerbräus!", objective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", description = "Wir müssen die Leute wissen lassen, dass die Donnerbräus ihre Bitte nach gutem Gebräu erhört haben. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält!\n\nWir werden Euch das Ganze etwas erleichtern, indem wir Euch einen Rennwidder 4 Minuten lang borgen.\n\nAchtet darauf, nicht zu schnell zu reiten, denn Ihr werdet keine Apfelkisten in Eisenschmiede finden und wir können es nicht riskieren, den Marktschreiern der Gerstenbräus behilflich zu sein.", progress = nil, completion = "Gute Arbeit! Das wird es diesen arroganten Gerstenbräus aber zeigen.\n\nNa dann, wir haben Euch eine Belohnung versprochen und hier ist sie. Wir Donnerbräus belohnen Euch mit Preisen, die Gerstenbräus belohnen Euch mit faulen Sprüchen und falschen Versprechen.\n\nIhr habt Euch weise entschieden.\n\nWenn Ihr auch weiterhin den richtigen Weg einschlagen wollt, dann kommt an einem anderen Tag noch einmal vorbei und verbreitet die Kunde.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11295] = {title = "Die Offensive beginnt", objective = "Sprecht mit Unteroffizier Gorth bei der Blockade in der Nähe des Aufzugs westlich vom Hafen der Vergeltung im Heulenden Fjord.", description = "Niemand scheint sehr viel über die Vrykul zu wissen. Unsere Aufzeichnungen deuten darauf hin, dass sich seit Jahrhunderten nichts mehr in ihren Landen geregt hat. Dennoch sind sie ausgerechnet jetzt, wo wir gegen Arthas ins Feld ziehen, hier.\n\nDie Karte, die Ihr geborgen habt, verdeutlicht, dass wir sie besiegen müssen, wenn wir unsere Truppen tiefer ins Landesinnere von Nordend bewegen wollen.\n\nEiner meiner besten Unteroffiziere, eine Monstrosität namens Gorth, wacht über die Blockade in der Nähe des Aufzugs. Unterstützt ihn dabei, einen Präventivschlag gegen Quälheim vorzunehmen. Wenn die Vrykul einen Angriff starten, dann wird er von dort aus geführt.", progress = nil, completion = "Du kommst, um zu helfen? Gut... gut...\n\nGorth wurde schon müde vom ständigen Vrykulmurksen. Hilfe ist gut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11296] = {title = "Gefangen im Bruchwald", objective = "Fernläufer Himmelswolke möchte, dass Ihr 7 seiner Fernläufer der Winterhufe befreit. Meldet Euch wieder bei ihm, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich am Stählernen Tor.", description = "Irgendetwas - höchstwahrscheinlich waren es die wandelnden Toten der Geißel - hat die Kreaturen in dieser Gegend in Unruhe versetzt.\n\nAls wir den Weisen hierher eskortierten, verloren wir den Großteil unseres Jagdtrupps an die Bruchwitwen, die im Norden des Bruchwaldes vorkommen.\n\nIch muss hier bleiben und die Wenigen, die von uns übrig geblieben sind, beschützen - doch Ihr... Ihr könntet nachsehen, ob meine Fernläufer noch immer am Leben sind. Sie sind in Bruchwitwenkokons eingeschlossen.\n\nWürdet Ihr das tun, <Fremder/Fremde>?", progress = nil, completion = "Das war eine sehr mutige Tat, &lt;Klasse&gt;. Ich wusste nicht, dass jemand Eures Volkes zu solch einem selbstlosen Akt fähig ist.\n\nDas nächste Mal werde ich die Warnungen meiner Ältesten beherzigen und einen großen Bogen um den Bruchwald machen. Ich rate Euch, dasselbe zu tun.", rewards = "EisschlägerbänderEisverkrustetes CapeVerstärkte HauerbalghalsbergeGurt des BlutbinderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11297] = {title = "Nach Eindringlingen Ausschau halten", objective = "Sprecht mit Apotheker Malthus im Apothekerlager.", description = "Selbst die Erde kann die Flut des Todes nicht eindämmen, die über sie hinwegschwappt. Leichen wandeln umher und verbreiten Fäulnis mit alarmierender Geschwindigkeit.\n\nEine kleine Expedition hat sich auf den Weg die westlichen Klippen hoch gemacht und in der Nähe der Flüsterschlucht ihr Lager aufgeschlagen. Doch seht für Euch selbst, <Name>. Versucht herauszufinden, aus welchem Grund sie dort sind, und haltet sie davon ab, ihre Gifte in unser Land zu bringen. Reist vom Posten aus gen Südwesten in Richtung der Klippen, die den westlichen Strand säumen. Ihr Lager wird sich westlich des Ausgrabungsortes am Stählernen Tor befinden.", progress = nil, completion = "Ah, ja, das zurückgezogene Bisonvolk des Nordens. Ich habe gesehen, wie sie herumschleichen - im Glauben, man würde sie nicht sehen. Ich nehme einmal an sie bilden sich ein, dass dieses Land ihnen gehört? Nun, das ist nur eine der vielen Veränderungen, die sich in Kürze ergeben werden.\n\nIch habe zwar nicht damit gerechnet, Gesellschaft zu bekommen, aber wenn Ihr schon einmal im Auftrag des Narren hier seid, könnt Ihr Euch genauso gut nützlich machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11298] = {title = "Was ist in dem Gebräu?", objective = "Apotheker Malthus im Apothekerlager möchte, dass Ihr ihm 5 zwergische Fässchen bringt.", description = "Im Südosten gibt es einen Landstrich namens Flüsterschlucht. In ihr wimmelt es nur so von verrückt gewordenen Forscherligisten! Sie griffen unsere Karawane an, als wir durch diese Gegend zogen, und außerdem attackieren sie ununterbrochen unsere Jagdtrupps.\n\nIch muss wissen, was der Grund dieses Wahnsinns ist! Ich vermute einmal, dass was auch immer sie aus diesen Fässchen, die überall in der Schlucht verstreut herumliegen, trinken, zu ihrem Wahnsinn beiträgt. Ich möchte, dass Ihr die Fässchen dieser Zwerge stehlt, während sie mit Schürfen beschäftigt sind.", progress = "Habt Ihr nun die Fässchen bei Euch oder nicht?", completion = "&lt;Der Apotheker schenkt sich einen Krug voll des Gebräus ein.&gt;\n\nTja, zum Wohl!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11299] = {title = "Der Ring des Richturteils", objective = "Findet Daegarn. Sucht im Ring des Richturteils im Inneren der Katakomben von Utgarde.", description = "Ihr habt vielleicht schon den Raum, in dem Daegarn gefangen gehalten wird, gesehen, als Ihr dabei wart, die Tafeln zu sammeln. Er befindet sich am Ende dieses Korridors und dann ein paar Stufen hinunter. Daegarn befindet sich in dem Raum am Ende dieser Treppen - fest hinter Gittern verschlossen!\n\nBegebt Euch dorthin und findet ihn. Vielleicht könnt Ihr wenigstens die Glyphe von ihm bekommen.", progress = nil, completion = "Jap - Ihr habt mich gefunden. Jippi-jei!\n\nUnd nein, ich hab' die Glyphe nicht. Mein Bart war das Erste, was diese Biester durchsucht haben! Oluf hat sie jetzt - er ist der Häuptling der Gladiatoren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11300] = {title = "Überwältigende Niederlage im Ring", objective = "Besiegt die Gladiatoren im Ring des Richturteils und stellt Euch Oluf dem Gewalttätigen. Besiegt Oluf und nehmt ihm die uralte Glyphe ab.\n\nBringt die uralte Glyphe zu Glorenfeld am Eingang zu den Katakomben von Utgarde.", description = "Oluf wird erst dann rauskommen, wenn Ihr die anderen Gladiatoren besiegt habt. Das ist so gut wie unsere einzige Möglichkeit, an diese Glyphe heranzukommen. Schnappt Euch Eure beste Klopp-Ausrüstung und dann ab mit Euch in den Ring des Richturteils und auf geht's. Geht zu Glorenfeld drüben am Eingang zu den Katakomben und gebt ihm die Glyphe, falls Ihr sie zurückbekommen könnt.\n\nIch? Macht Euch um mich keine Sorgen! Wir sind kurz davor, das fehlende Bindeglied zu entdecken, das die Herkunft der Menschheit klären wird.", progress = "Daegarn? Die Glyphe?", completion = "Faszinierende Geschichte! Da gibt es tatsächlich etwas, das über die Dinger richtet? Wozu?! Zu welchem Zweck?\n\nNun, vergesst diesen Unsinn. Das soll irgendwer anderes herausfinden. Wir haben Glyphe und Tafeln wieder - und die ganze Tortur hat nur zwei Todesopfer gefordert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11301] = {title = "Gehirne! Wir wollen Gehirne!", objective = "Apotheker Grick im Apothekerlager möchte, dass Ihr ihm 12 verwirrte Forscherhirne bringt.", description = "Hat Euch Malthus mit seiner Faselei über Bierkrüge und verrückte Zwerge schon in seinen Bann gezogen?\n\nIch will ja nicht in Frage stellen, dass Zwerge verrückt sind, aber ich denke, dass es zu nichts führt, ihr Bier zu stehlen.\n\nWas wir brauchen ist Köpfchen - beziehungsweise etwas aus dem Köpfchen. Und zwar viel davon. Wir werden diesem Rätsel im Nu auf den Grund gehen und vielleicht sogar eine neue Zutat für unsere Seuche finden.\n\nNehmt diese Säge, geht nach Südosten zum Flüsterschlund und tötet ein paar Zwerge. Mithilfe der Säge könnt Ihr die Gehirne sammeln. Bringt sie dann hierher.", progress = "Konntet Ihr die Gehirne bekommen? Falls nicht, dann will ich meine Säge zurückhaben. Und versucht bloß nicht, mit der Säge abzuhauen.", completion = "Oh, diese Gehirne sind schön! Sogar wunderschön! Genau das, was ich brauche.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Nun werde ich Malthus mal die Wahrheit zeigen, die er durch seine rosarote Brille nicht sehen konnte.", rewards = "Erderfüllte GamaschenFizzniks patentierte OhrenschützerArkanumschildStiefel des meisterlichen ArtilleristenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11302] = {title = "Die geheimnisvollen Frostnymphen", objective = "Sprecht mit Lurielle auf der Gefrorenen Lichtung.", description = "Als wir das erste Mal nach geeigneten Stellen für das Fort suchten, begegneten wir auf zwei der Lichtungen hier im Norden feindlich gesinnten Kreaturen. Doch als wir über die schneebedeckte Lichtung, die direkt südlich der Stadt liegt, liefen, wurden wir von den dortigen Dryaden nur mit Interesse beäugt, jedoch nicht angegriffen.\n\nWir waren müde und vom Wetter mitgenommen. Sie hätten mit Leichtigkeit mehrere von unseren Männern töten können, taten es jedoch nicht.\n\nVielleicht könnten sie ganz unerwartet zu unseren Verbündeten werden, wenn wir uns ihnen nur nähern würden. Seid Ihr dazu bereit, zur Gefrorenen Lichtung zu reisen und mit ihnen Kontakt aufzunehmen?", progress = nil, completion = "&lt;Ihr stellt Euch vor und Lurielle lauscht Euren Worten.&gt;\n\nWie gut, Euch endlich kennenzulernen, &lt;Name&gt;. Wir haben lange darauf gehofft, dass Ihr und die anderen Neuankömmlinge Repräsentanten schicken würdet. Wir wagen uns nicht sehr oft aus unseren Lichtungen heraus, zumal dieses Land derzeit einige Veränderungen erfährt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11303] = {title = "Der Hinterhalt", objective = "Geht zu Lydells Hinterhalt und sprecht mit Lydell.", description = "Die Vrykul in Quälheim sind endgültig platt gemacht, daran ich keinen Zweifel. Doch ihr Anführer noch immer in der Stadt und will nicht aufgeben.\n\nGorth schickt Lydell und seine Helfer, um guten Hinterhalt im Nordwesten zu machen. Du redest mit Lydell und findest heraus, wie man Vrykulhäuptling herauslockt. Dann tötest du ihn - machst ihn richtig platt.", progress = nil, completion = "Wir sind alle dabei gewesen, nur der Ehrengast blieb Zuhause.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11304] = {title = "Neu-Agamand", objective = "Bringt Lysanders Erregerstamm zum obersten Seuchenfürsten Harris. Er befindet sich in Neu-Agamand im Westen des Heulenden Fjords", description = "Ich befürchte, dass die Ausrüstung hier im Hafen der Vergeltung nicht wirklich die beste ist. Dabei soll das hier ein militärischer Außenposten sein.\n\nIhr müsst eine Probe dieses Erregerstammes für mich zum obersten Seuchenfürsten Harris in Neu-Agamand bringen - folgt der Straße außerhalb von Quälheim nach Süden und dann nach Westen. Dort haben sie bessere Ausrüstung - er wird wissen, was zu tun ist.\n\nIhr müsst Euch beeilen, <Name>. Unsere Feinde sind stärker und zahlreicher als wir. Wir müssen eine wirksame Waffe gegen sie entwickeln!", progress = "Ja, <Name>?", completion = "Dieser Erregerstamm ist alles andere als nutzlos, mein Freund! Die Narren im Hafen der Vergeltung! Die Antworten lagen die ganze Zeit direkt vor ihrer Nase!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11305] = {title = "Eine maßgeschneiderte Formel", objective = "Geht zu Thorvalds Lager, erschlagt Thorvald, nehmt das Blut des Patriarchen der Drachenschinder an Euch und bringt es zum obersten Seuchenfürsten Harris in Neu-Agamand.", description = "Wir haben das Vrykuldorf Halgrind nun schon seit Wochen mit dem Zeugs besprüht, aber die Dreckskerle wollen einfach nicht tot umfallen.\n\nSeien wir doch mal ehrlich, <Name>, inzwischen wurde fast alles unserer Seuche ausgesetzt: Menschen, Zwerge, Hunde, selbst das Vieh... Während unsere Erregerstämme sich an ihren Wirt anpassen, wird die Mischung noch weiter verunreinigt. Was wir brauchen, ist ein Erreger, der speziell an die Körper der Vrykul angepasst ist.\n\nDer Anführer Halgrinds flüchtete aus der Stadt, nachdem wir sie einnahmen - er befindet sich westlich von hier. Der Fakt, dass er ein Patriarch des Drachenschinderklans ist, macht sein Blut ideal für unsere Zwecke.", progress = "Konntet Ihr die nötige Probe beschaffen, <Name>?", completion = "Das wird reichen. Zeit für ein wenig echte Apothekerarbeit, &lt;Name&gt;!", rewards = "Federleichtes ClaymoreSäuregeätzte KnöchelGekräftigter VollstahldolchDonnerbüchse mit MiniabzugIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11306] = {title = "Aufkochen und umrühren", objective = "Füllt die leere Apothekerflasche im Kessel mit Vrykulblut auf und vermischt ihren Inhalt so lange mit Harris' Seuchenproben, die sich in der Nähe befinden, bis Ihr eine ausgewogene Mixtur erhaltet.\n\nSprecht wieder mit dem obersten Seuchenfürsten Harris, sobald Ihr die Aufgabe erledigt habt.", description = "Ihr habt bis jetzt gute Arbeit geleistet, <Name>. Ich würde Euch gerne ein paar meiner Techniken zeigen - sie sind weiter fortgeschritten und werden Euch ein besseres Verständnis von der Seuche vermitteln.\n\nNehmt diese leere Flasche und füllt sie mit dem Blut aus dem Kessel zu meiner Linken. Nehmt dann die Seuchenproben zu meiner Rechten und gebt so viel zum Blut hinzu, bis Ihr eine ausgewogene Mischung erhaltet.", progress = "Wie geht es Eurem Experiment, <Name>? Lasst es mich wissen, falls Ihr Fragen bezüglich des wissenschaftlichen Aspekts hinter dem Ganzen haben solltet!", completion = "Ausgezeichnet! Ihr seid ein begabter Schüler, &lt;Name&gt;.\n\nNun zum spaßigen Teil: die Anwendung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11307] = {title = "Feldversuch", objective = "Geht nach Halgrind und wendet das Seuchenspray auf 10 Verseuchte Vrykul der Drachenschinder an. Kehrt anschließend zum obersten Seuchenfürsten Harris zurück und erstattet ihm über die Ergebnisse Bericht.", description = "Da wir nun über einen an vrykulsche Wirte angepassten Seuchenerreger verfügen, müssten wir ihn eigentlich an unseren Exemplaren in Halgrind austesten. Wenn alles nach Plan verläuft, sollten sie augenblicklich zerfallen, da die Seuche ihre Eingeweide zersetzt!\n\nHalgrind befindet sich nördlich von hier. Unsere Seuchenbringer verbreiten dort gerade den alten Erreger - sollte nicht zu übersehen sein.", progress = nil, completion = "Die Seuche ließ unsere Subjekte nicht zerfallen? Seid Ihr Euch sicher, &lt;Name&gt;??!\n\nEs muss einen externen Faktor geben, den wir nicht berücksichtigen... vielleicht ist es die niedrige Temperatur, die in diesem Klima herrscht? Vielleicht... eine Mutation unseres Erregers!", rewards = "Generöses BollwerkAuf Euch wartet eine dieser Belohnungen:\n\nFoliant des Eifers\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11308] = {title = "Zeit aufzuräumen", objective = "Sprecht mit \"Eisensäge\" Jenny in Neu-Agamand.", description = "Da ich nun einmal ein praktisch veranlagter Mann bin, erkläre ich hiermit unsere Forschung an diesem Ort für erfolgreich. Schließlich lässt sich noch jede Armee aufhalten, wenn man nur unter ihren eigenen Reihen Zwietracht sät?\n\nIch werde dafür sorgen, dass man im Hafen der Vergeltung bald genug Nachrichten unserer Errungenschaften erhalten wird. Aber zuerst müsst Ihr Euch um die Säuberung unserer Teststätte kümmern.\n\nFragt \"Eisensäge\" Jenny, ob sie eine Monstrosität nach Euren Wünschen anfertigen kann - eine mit explosionsartiger Kraft, wenn Ihr versteht, was ich meine.", progress = nil, completion = "Was wollt Ihr? Könnt Ihr nicht sehen, dass ich gerade beschäftigt bin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11309] = {title = "Benötigte Teile", objective = "\"Eisensäge\" Jenny in Neu-Agamand möchte, dass Ihr 6 Schaufelhauerbänder und 1 Pfund frisches Fleisch besorgt.", description = "So, Harris will also, dass der Ort demoliert wird, hä? Ja, ich kann aushelfen.\n\nIhr werdet mir jedoch ein paar Teile besorgen müssen. Ich kann es mir nicht leisten, meine kostbarsten Komponenten für etwas zu verwenden, das in die Luft gejagt werden soll.\n\nAls Allererstes brauche ich Schaufelhauerbänder... viel besser als die der Menschen.\n\nAußerdem brauche ich noch ein Pfund Fleisch. Ein Kerl namens Anton verkauft billiges Fleisch. Er ist entlang der Straße gen Westen anzutreffen.", progress = "Habt Ihr die Komponenten schon?", completion = "Ausgezeichnet! Ja, ja, das wird völlig ausreichen!", rewards = "Schockresistente KapuzeBebänderte KettenhandschuheGeneröse BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11310] = {title = "Warnung: Ein wenig Montage benötigt", objective = "Benutzt den Monstrositätenbausatz in Halgrind und tötet mithilfe der hirnlosen Monstrosität 20 verseuchte Vrykul. Kehrt nach Neu-Agamand zu \"Eisensäge\" Jenny zurück, sobald Ihr fertig seid.", description = "Nun gut, hier, bitte schön! Unser Freund wird etwas... instabil sein - also schlage ich vor, dass Ihr ihn erst zusammenbaut, wenn Ihr in Halgrind seid.\n\nTreibt, wenn Ihr dort seid, mithilfe der Monstrosität so viele Vrykul wie nur möglich zusammen, bevor die Selbstzerstörung ausgelöst wird.\n\nKommt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt mir, was auch immer übrig geblieben ist. Körperteile kann ich immer gut gebrauchen!", progress = nil, completion = "Großartige Arbeit, &lt;Name&gt;. Ihr würdet nicht zufällig nach etwas... langfristigem suchen, oder? In dieser Gegend gibt es viel zu tun, ich könnte definitiv Hilfe gebrauchen!", rewards = "Feuerläuternde TunikaBiegsame LederfußlappenUnentrinnbarer GurtLeichtgebundener BrustschutzIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11311] = {title = "Die Elemente bekämpfen", objective = "Windzähmer Kagan im Lager der Winterhufe möchte, dass Ihr 8 Bergelementare tötet. Zu töten sind entweder heulende Zyklone oder Eissplitterelementare.", description = "Wenn Ihr hier überleben wollt, so wie wir es bisher getan haben, müsst Ihr den Herausforderungen der Natur direkt ins Auge blicken. In Anbetracht der starken Zunahme der Elementare in dieser Gegend würde Unachtsamkeit gegenüber den Elementen Euer Leben fordern.\n\nWir müssen die Zahl der Elementare ein letztes Mal reduzieren, bevor wir diesen Ort verlassen können. Seid Ihr willens, uns zu helfen, während wir uns um die Vorbereitungen kümmern?\n\nIhr müsst sämtliche Eissplitterelementare oder heulende Zyklone töten, die Euch in den verschneiten Hügeln rings um den Außenposten herum begegnen.", progress = nil, completion = "Der Einfluss der Elementargeister ist geschwunden, doch sie werden ihn wiedererlangen. Wir haben uns die nötige Zeit verschafft, um unsere Aufgabe hier zu Ende zu bringen und Abschied zu nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11312] = {title = "Die Gefrorene Lichtung", objective = "Sprecht mit Lurielle in der Gefrorenen Lichtung.", description = "Seit Generationen erzählt mein Volk sich Geschichten über Frostnymphen, die sich auf verborgenen Lichtungen in der Wildnis tummeln. Als Kind war ich entgegen des Rates meiner Eltern auf der Suche nach ihnen und wäre zum Schluss beinahe erfroren.\n\nHeutzutage muss man jedoch nicht mehr die Wälder durchkämmen, um sie zu finden. Sie haben sich aus mir unerklärlichen Gründen dazu entschlossen, ans Licht zu treten, und ich denke nicht, dass diese Veränderung ignoriert werden kann. Begebt Euch auf die riskante Reise zur Gefrorenen Lichtung gen Südosten und sucht nach den Nymphen - doch seid gewarnt: Euer Weg führt Euch durch die Siechende Lichtung.", progress = nil, completion = "&lt;Ihr stellt Euch vor und Lurielle lauscht Euren Worten.&gt;\n\nWie gut, Euch kennenzulernen, &lt;Klasse&gt;. Meine Schwestern haben oft beobachtet, wie die Taunka in den Wäldern nach uns suchen, doch unsere Königin hat uns jeglichen Kontakt mit Fremdlingen verboten. Ihr könnt uns nur sehen, weil das Land in Aufruhr ist und viele meiner Schwestern in Gefahr sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11313] = {title = "Geister des Eises", objective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr ihr 15 eisige Kerne bringt.", description = "Einst waren die Eiselementare, die unsere Lichtung umgeben, unsere Gefährten, doch dann wurde das Land von einem Sturm unberechenbarer, zerstörerischer Macht erfasst, der sie zu unseren Feinden machte!\n\nUnd dieses Gräuel ist nur eines von vielen, die meine Schwestern und ich bis jetzt ertragen mussten. Wir haben uns Euch gezeigt und hoffen nun, dass Ihr den Verfall, von dem unsere Lichtungen beschlichen und unsere Schwestern vergiftet wurden, abwenden könnt!\n\nWir haben die Kerne der Eiselementare gesammelt und sicher verwahrt, damit wir sie eines Tages vielleicht wieder zurückrufen können. Werdet Ihr helfen?", progress = "Habt Ihr die Kerne gefunden?", completion = "&lt;Lurielle nimmt schweigend die Kerne entgegen.&gt;\n\nIch danke Euch, &lt;Name&gt;.\n\n\n\nIch verspreche, meine Freunde, dass ich alles in meiner Macht stehende tun werde, um Euch zurückzurufen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11314] = {title = "Die gefallenen Schwestern", objective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr ihren Anhänger auf 7 Eisnymphen verwendet.", description = "Gen Südwesten befand sich einst eine Lichtung, die dieser hier sehr ähnlich sah. Geheimnisvolle Kräfte und fremde Magie formen das Land neu. Das Eis der Lichtung ist aufgetaut und die Schwestern, die dort wohnen, wurden von der plötzlichen Veränderung in den Wahnsinn getrieben.\n\nWir wollten Kontakt mit ihnen aufnehmen, doch sie griffen uns an. Ich befürchte, dass viele von ihnen nicht mehr zu retten sind, allerdings kann ich die Hoffnung nicht aufgeben.\n\nNehmt meinen Anhänger, reist zur südwestlich gelegenen Lebendigen Lichtung und versucht, mit seiner Hilfe meine Schwestern zu befreien.", progress = nil, completion = "Es besteht also Hoffnung für meine Schwestern?\n\n&lt;Lurielle wendet ihren Blick von Euch ab und richtet ihn dann auf den Boden.&gt;\n\nIch fühle mich schuldig, nicht früher an den Anhänger gedacht zu haben. Wir hätten vielleicht noch mehr Schwestern retten können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11315] = {title = "Wilde Ranken", objective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr 8 Exemplare des scharlachroten Efeus tötet.", description = "Die Schwestern, die auf der Lebendigen Lichtung gen Südwesten leben, hegten einst wunderschöne Beete mit scharlachrotem Efeu, doch dieselbe Kraft, die sie in den Wahnsinn trieb, verwandelte auch ihren geliebten Efeu.\n\nDie Ranken greifen nun nach den Füßen jedes Unbesonnenen oder schlingen sich um jeden, der sich der Lichtung nähert. Bevor wir sie wieder kultivieren können, müssen die Ranken gezähmt und entwurzelt werden.\n\nBeseitigt so viele Exemplare des Efeus wie Ihr nur könnt. Die Sache ist schon außer Kontrolle geraten.", progress = nil, completion = "Vielen Dank für Eure Hilfe, &lt;Name&gt;. Die Lebendige Lichtung war einst ein wunderschöner Ort, und wenn wir zurückkehren, werden wir es wieder zu dem machen, was es einmal war.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11316] = {title = "Geflechte der Siechenden Lichtung", objective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr 10 Dornrankenkriecher tötet.", description = "Die Lichtung im Westen wurde in einen grässlichen Ort verwandelt, der nun Siechende Lichtung genannt wird. Zwischen den Bäumen, Steinen und ihrem Teich hausen nun schreckliche Biester.\n\nMir ist es ein Rätsel, wo diese Kreaturen herkamen oder welche ungeheuren Kräfte sie zum Leben erweckten, doch man muss sich um sie kümmern!\n\nLieße man ihnen die Lichtung, dann fürchte ich, dass ihr Gift sie ein für alle Mal verderben wird. Säubert die Lichtung von den Kreaturen, die unsere Schwestern töteten.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Hätten wir Verbündete wie Euch gehabt, als sich die ersten Veränderungen im Land regten, dann hätten wir vielleicht einiges, das uns verloren ging, erhalten können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11317] = {title = "Die Läuterung", objective = "Weiser Nebelläufer am Stählernen Tor hat Euch geraten, Euren inneren Aufruhr durch Meditation am Frostklingenschrein zu besänftigen.", description = "Der Grund, wieso wir dem Bruchwald trotzen konnten, hat seinen Ursprung in den sorgenschweren Träumen von Ulfang dem Worgen. Er ist mein Freund und ruft um Hilfe. Ihr müsst zu ihm gehen.\n\nJedoch habt Ihr nicht die Möglichkeit, mit ihm zu reden oder unter den anderen Worgen zu wandeln. Ich kenne einen Weg.\n\nZuerst müsst Ihr Euch von Eurem inneren Aufruhr befreien.\n\nAuf der Spitze des Frostklingengipfels, nordöstlich vom Lager der Winterhufe, gibt es einen Schrein, zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.\n\nMeditiert dort und kehrt zu mir zurück.", progress = nil, completion = "Ich kann die Veränderung in Euch bereits spüren.\n\nSeid Ihr bereit für den nächsten Schritt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11318] = {title = "Das ist Widderrennen... zumindest fast", objective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", description = "Ihr wollt also die Rennwidder testen? Nun, ich hoffe, Ihr seid auf Geschwindigkeit gefasst. Bevor ich Euch auf die Welt loslasse, müsst Ihr mir erst einmal beweisen, dass Ihr mit diesen feinen Tieren auch wirklich umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Rennzügel und lasse Euch auf einem Widder reiten. Zeigt mir, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten. Sprecht mit meinem Lehrling, Pol Bernruh, falls Ihr Anweisungen für den Umgang mit den Widdern benötigt.", progress = nil, completion = "Nicht schlecht! Es dauert meist ein wenig, bis man seinen Widder zu kontrollieren versteht. Hat man den Dreh erstmal raus, würde man sich wünschen, dass jeder Widder ein Rennwidder wäre.\n\nWie bitte? \"Wo ist meine Belohnung?\". Ha, ha, ha... Ihr dürft mit dem schnellsten Widder am Rennen teilnehmen! Ihr wollt noch mehr? Na, wie wäre es damit...\n\nAls Belohnung dürft Ihr anderen hier auf dem Braufest aushelfen. Es gibt jede Menge zu tun... und Belohnungen für eifrige, junge Widderrennmeister.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11319] = {title = "Samen der schwarzbeseelten Bewahrer", objective = "Lurielle auf der Gefrorenen Lichtung möchte, dass ihr 8 Sporen einfriert.", description = "Der Ort im Nordwesten, den man nun Siechende Lichtung nennt, war einst das Zuhause etlicher Bewahrer der Lichtung. Gemeinsam mit den Schwestern kümmerten sie sich um deren Pflege.\n\nDie Lichtung veränderte sich und die Schwestern starben, doch irgendwie konnten die Bewahrer überleben. Nun säen sie giftige Sporen im Land und sorgen auf diese Weise dafür, dass das gesunde Grün verwelkt.\n\nIch werde Euch einen der Kerne von den Eiselementaren geben. Sobald Ihr einen Sporen zerstört habt, sollt Ihr ihn mithilfe des Eiskristalls einfrieren und ihn auf diese Weise davon abhalten, sich zu regenerieren.", progress = nil, completion = "Der Eiskristall hat Euch gut gedient? Das werde ich mir merken müssen. Einmal die Arbeit der Bewahrer zu zerstören, wird sie jedoch nicht aufhalten, da bin ich mir sicher.", rewards = "Halsberge des schwarzbeseelten BeschützersWurzel des EwigenTuch des destillierten HassesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11321] = {title = "Sagte da jemand \"Souvenir\"?", objective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGelber Braufestkrug"}
MultiLanguageQuestData['de'][11322] = {title = "Die Läuterung", objective = "Behüterin Mondblatt am Stählernen Tor hat Euch geraten, Euren inneren Aufruhr durch Meditation am Frostklingenschrein zu besänftigen.", description = "Seit einiger Zeit habe ich Alpträume, die sich um den Worg Ulfang drehen. Er hat um Hilfe gerufen. Ihr müsst zu ihm gehen.\n\nJedoch habt Ihr nicht die Möglichkeit, mit ihm zu reden oder unter den anderen Worgen zu wandeln, aber ich kenne einen Weg.\n\nDoch zuerst müsst Ihr Euch durch Meditation von Eurem inneren Aufruhr befreien, Euch läutern.\n\nAuf der Spitze des Frostklingengipfels weit im Nordosten befindet sich ein Schrein, zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.\n\nMeditiert dort, befreit Euch und kehrt zu mir zurück.", progress = nil, completion = "Ich kann die Veränderung in Euch bereits spüren.\n\nSeid Ihr bereit für den nächsten Schritt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11323] = {title = "Im Worgpelz", objective = "Der Weise Nebelläufer hat Euch gebeten, Ulfang im Bruchwald zu suchen und ihm zu helfen.\n\nKehrt zum Weisen Nebelläufer zurück, um einen Ersatz zu erhalten, solltet Ihr die Worgverkleidung verlieren.\n\nBereitgestellter Gegenstand: \n", description = "Aus meinen Träumen weiß ich, dass Ulfang sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds aufhält.\n\nEr ist in großer Gefahr.\n\nIch habe eine magische Verkleidung erschaffen, die Euch wie ein Worg aussehen lassen wird, während Ihr im Bruchwald seid. Die Verkleidung ist schwach und hängt von der merkwürdigen Magie dieses Geisterwaldes ab. Sie wird zwar nur die Worgs überzeugen, es sollte Euch jedoch ermöglichen, nah zu Ulfang zu gelangen.\n\nBitte, <Klasse>, findet ihn und helft ihm.", progress = nil, completion = "Du siehst anders aus und riechst auch anders... Du bist nicht aus meinem Rudel. Erzähl mir deine Geschichte. Ich habe mehr als genug Zeit, solange ich hier gefangen bin.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11324] = {title = "Alphaworg", objective = "Ulfang hat Euch gebeten, Garwal zu erschlagen. Kehrt danach zum Weisen Nebelläufer am Stählernen Tor zurück und bringt die Worgverkleidung mit.", description = "Wenn du die Augen von Klauenwürger gegessen hast, sollte es dir möglich sein, Garwal zu sehen und ihm seine Kehle herauszureißen!\n\n<Volk>, such nach Garwal im westlichen Bruchwald und töte ihn. Geh zu Nebelläufer, sobald du ihn getötet hast, und sag ihm, dass ich wieder der Alphaworg bin!", progress = "<Name>, Ihr seid zurück. Was gibt es Neues von Ulfang?", completion = "Garwal war überhaupt kein Worg! Ich kenne diese Kreaturen... sie werden Worgen genannt.\n\nDoch Ulfang meinte, dass es aus den Grizzlyhügeln kam und gen Süden ging? Seltsam. Hier gibt es gar keine Worgen.\n\nIch danke Euch, dass Ihr Ulfang geholfen habt, seinen wahren Platz in seinem Rudel zurückzuerhalten. Nun werden wir beide friedlich schlafen können.\n\nBitte, Ihr müsst das als Zeichen des Dankes akzeptieren.", rewards = "Gholamgewirkte BeinlingeProtodrachenzahnschiftungDunkelstahlringpanzerschienbeinschützerHalsberge des WorgblutberserkersDer folgende Zauber wird auf euch gewirkt:\n\nAlpha Worg: Quest Complete\n\nIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11325] = {title = "Im Worgpelz", objective = "Behüterin Mondblatt hat Euch gebeten, Ulfang im Bruchwald zu suchen und ihm zu helfen.\n\nKehrt zu Behüterin Mondblatt zurück, um einen Ersatz zu erhalten, solltet Ihr die Worgverkleidung verlieren.\n\nBereitgestellter Gegenstand: \n", description = "Aus meinen Träumen weiß ich, dass Ulfang sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds befindet.\n\nEr ist in großer Gefahr.\n\nIch habe eine magische Verkleidung erschaffen, die Euch wie ein Worg aussehen lassen wird, während Ihr im Bruchwald seid. Die Verkleidung ist schwach und hängt von der merkwürdigen Magie dieses Geisterwaldes ab. Sie wird zwar nur die Worgs überzeugen, doch es sollte Euch ermöglichen, nah zu Ulfang zu gelangen.\n\nBitte, <Klasse>, findet ihn und helft ihm.", progress = nil, completion = "Du siehst anders aus und riechst auch anders... Du bist nicht aus meinem Rudel. Erzähl mir deine Geschichte. Ich habe mehr als genug Zeit, solange ich hier gefangen bin.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11326] = {title = "Alphaworg", objective = "Ulfang hat Euch gebeten, Garwal zu erschlagen. Kehrt danach zu Behüterin Mondblatt am Stählernen Tor zurück und bringt die Worgverkleidung mit.", description = "Wenn du die Augen von Klauenwürger gegessen hast, sollte es dir möglich sein, Garwal zu sehen und ihm seine Kehle herauszerreißen!\n\n<Volk>, such nach Garwal im westlichen Bruchwald und töte ihn. Geh zu Mondblatt, sobald du ihn getötet hast, und sagt ihr, dass ich wieder der Alphaworg bin!", progress = "<Name>, Ihr seid zurück. Was gibt es Neues von Ulfang?", completion = "Garwal war überhaupt kein Worg! Das Ding, in das er sich verwandelt, hört sich schon viel eher wie ein Worgen an!\n\nDoch Ulfang meinte, dass es aus den Grizzlyhügeln kam und gen Süden ging? Seltsam. Hier gibt es gar keine Worgen.\n\nIch danke Euch, dass Ihr Ulfang geholfen habt, seinen wahren Platz in seinem Rudel zurückzuerhalten. Nun werden wir beide friedlich schlafen können.\n\nBitte, Ihr müsst das als Zeichen des Dankes akzeptieren.", rewards = "Gholamgewirkte BeinlingeProtodrachenzahnschiftungDunkelstahlringpanzerschienbeinschützerHalsberge des WorgblutberserkersDer folgende Zauber wird auf euch gewirkt:\n\nAlpha Worg: Quest Complete\n\nIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11327] = {title = "Mission 'Paket beschaffen'", objective = "Kundschafter Wisslich möchte, dass Ihr nach Halgrind geht und das Paket des Apothekariums beschafft. Kehrt zu ihm zurück, sobald Ihr das getan habt. Er befindet sich am Glutspeerturm.", description = "Tja, verdammt, wir brauchen ein wenig von dem Seuchenzeugs.\n\nIch weiß!\n\nWährend Ihr die Bottiche zerstört habt, konnte ich sehen, wie einer der Apotheker aus Neu-Agamand von den Vrykul nach Halgrind verschleppt wurde. Armer Hund.\n\n<Name>, ich könnte wetten, dass der Apotheker das Gut bei sich trägt. Meint Ihr, dass Ihr nach Halgrind gehen und dieses Paket besorgen könntet?", progress = "Dieser Ort könnte einem Alptraum entstammen. Vrykul oder nicht - niemand hat es verdient, ein Opfer der königlichen Apothekervereinigung zu sein.\n\nIch bin froh hier drüben in Sicherheit zu sein. Habt Ihr das Paket schon gefunden?", completion = "Heiliger... was zum Teufel?! Seht Euch dieses Zeugs an!\n\nWir müssen es so schnell wie möglich zurück zur Wache bringen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11328] = {title = "Mission 'Kunde über die Verlassenen'", objective = "Kundschafter Wisslich möchte, dass Ihr das Paket des Apothekariums zu Peppy Falschdüse bringt. Sie befindet sich in der Taverne in Westwacht.", description = "Gut, nun ich denke, dass Ihr das Zeugs zu Peppy Falschdüse in der Wache bringen solltet. Sie ist so was wie ein Alchemistenamateur - aber der einzige den wir haben.\n\nEins noch zu Peppy: Sie trinkt für ihr Leben gerne. Ihr werdet sie also höchstwahrscheinlich in der Taverne finden - die 'Atmosphäre aufsaugen'.\n\nIch bin mir sicher, dass sie wissen wird, was zu tun ist.", progress = "J-aa, w's wilsd du... hicks?", completion = "Hoppla... das'is was anderes!\n\nNun guud, las misch maal das Scheugs seh'n. Isch liebe es mit Alchemie herumsuufuschn!\n\nInteressaant, interessant... hier, ich denge, isch weiß, was wir mach'n müssn. Ein weenich davon, vermischd mit genauu der rischdischn Menge hiervoon.\n\nWeisd du, isch denke, ein wenig von dem Fusel wäre auch nich schleschd ...hicks!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11329] = {title = "Ich werde alles versuchen!", objective = "Christopher Sloan bei Fort Wildervar möchte, dass Ihr ihm 5 Nordbarben bringt.", description = "In meinem ganzen Leben will ich nie wieder ein Fass mit gesalzenem Fisch sehen! Jeden Tag fülle ich hier Fässer und es sind noch so viele zu füllen!\n\nIch wünschte, ich hätte nicht alle Köder aufgebraucht, die ich von Nat Pagle gekauft habe. Haben wie von Zauberhand funktioniert. Jetzt habe ich Glück, wenn ich einen Fisch pro Stunde fangen kann!\n\nIch habe gehört, Nordbarben wären gute Köderfische, aber wer wäre verrückt genug, um in einen eiskalten See zu tauchen und die Wasserpflanzen nach ihnen zu durchwühlen? Ich nicht... aber vielleicht, nur vielleicht, kann ich Euch ja überreden...", progress = "Ihr seht aus, als wärt Ihr noch in einem Stück. Etwas von den Ködern bekommen?", completion = "Naja, die sind mit Sicherheit hässlich genug, aber ich schätze, mir ist es egal, ob es tatsächlich funktioniert. Ich werd' froh sein, sobald die Expedition hier durchgezogen ist und ich einfach nur noch für mein Abendessen angeln muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11330] = {title = "Dasch wird auf jeden Fall... funzen!", objective = "Peppi Falschdüse in Westwacht schlägt vor, dass Ihr dem gefangenen Vrykul der Drachenschinder Peppis Spezialmix verabreicht, um zu sehen, welche Wirkung er hat.", description = "Voila, schofortwirkender Seuschenimpfstoff!\n\nAber ich werde dasch hundertpro nicht an mir selbscht austeschten - und ich weisch, dass du nicht mein Verschuchskaninchen spielen wilscht!\n\nO'isch hab'... isch hab' eine Idee!\n\nDa ischt ein Vrykul, der wird von unsch im Keller der Burg gefangen gehalten. Wiescho nimmscht du nicht einfach diesen Mix - hab ihn schelbst gemischt! - und gehscht da runter und gibscht's dem Ries'n zu trinken... hicks?!", progress = nil, completion = "Hä? Echt ätzend! V'dammt, ich hab' die Schache verschlimmert - oder vielmehr hab' ich ihre Scheuche für schie perfektioniert... hicks!\n\n&lt;Peppi verzieht ihr Gesicht und nimmt einen kräftigen Schluck von dem übel riechenden Gebräu, das sie schon die ganze Zeit trinkt.&gt;\n\nNun, isch hatte gehofft, dass'esch nicht soweit kommen wird, aber s'sieht so ausch, als hätten wir keine andere Wahl... hicks.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11331] = {title = "Du sagst's ihm... hicks!", objective = "Peppi Falschdüse hat Euch dazu gebracht, Hauptmann Adams die schlechten Nachrichten über die Seuche der Verlassenen zu überbringen. Ihr findet ihn in Westwacht.", description = "So sieht's ausch: Ich werde es dem Hauptmann nicht sagen. Ich bin nur ein Amateur in Sachen Alchemie - das ischt nicht mein Aufgabengebiet und ich hab' gerade Pause!\n\nAuscherdem ist er ein mortzmäßiger Griesgram... und du kennscht ihn besser wie ich!\n\nAlscho geh' zu ihm in die Burg und sag's ihm. Bin mir schicher, dass er die Sache nüchtern betrachten wird... hicks.\n\n<Peppi wendet sich wieder dem Trinken zu.>", progress = nil, completion = "Ja, &lt;Name&gt;, was denn schon wieder?\n\nWAS?!! Eine Seuche der Verlassenen, die ihre Opfer im Nu zerfrisst?\n\nIhr habt meinen Vrykul in Schleim verwandelt?\n\n\n\nNun gut, ich weiß, was wir tun müssen - oder besser gesagt, was IHR tun müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11332] = {title = "Mission: Verseucht mal das hier!", objective = "Hauptmann Adams hat Euch befohlen, 5 Bomben auf die Seuchenkessel bei Neu-Agamand abzuwerfen. Kehrt erst zu ihm zurück, sobald Ihr die Aufgabe erledigt habt. Er befindet sich in Westwacht.", description = "Die Königliche Apothekervereinigung denkt also, sie könnte eine perfekte, neue Seuche erschaffen und uns alle auf der Stelle in Schleim verwandeln?!\n\nNicht so lange ich hier kommandiere!\n\nGeht hinaus auf den Hof und sprecht mit Greer Erzhammer. Er hält einen Greifen und ein paar Bomben für Euch bereit. Ich möchte, dass Ihr die Seuchenkessel bei Neu-Agamand in Stücke sprengt!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;, gut gemacht!\n\n\n\nDas wird diesen nichtsnutzigen Verlassenen schon zeigen, was passiert, wenn man sich mit uns anlegt!\n\nIch würde einmal behaupten, dass Ihr Euch etwas aus der Schatzkammer verdient habt!", rewards = "FlammenbinderhandlappenFroststeinverzierter TaillenschutzArmschienen des reinen SchlagsSmaragdschuppige SchulterstückeIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11333] = {title = "Reise in die Welt der Geister", objective = "Thoralius der Weise in Valgarde möchte, dass Ihr seinen Reagenzienbeutel findet.", description = "Es mag zwar sein, dass die Forscherliga mithilfe ihrer archäologischen Funde dies und jenes über die Vergangenheit herausfinden und der Vizeadmiral mit purer Gewalt Antworten auf gegenwärtige Fragen erhalten kann, doch die Wahrheit an sich liegt in den Geistern.\n\nMit den richtigen Reagenzien kann ich in die Welt der Geister blicken; denn dies ist der Ort, an dem sich Vergangenheit, Gegenwart und Zukunft von Nordend befinden.\n\nWenn Ihr mehr darüber erfahren wollt, werde ich meinen Reagenzienbeutel benötigen. Er kam mir auf einem Schiff abhanden, das nun auf dem Grund der Dolchbucht gen Osten liegt.", progress = "Habt Ihr meinen Reagenzienbeutel gefunden?", completion = "Sieht ein bisschen mitgenommen aus, erfüllt jedoch seinen Zweck.\n\n&lt;Thoralius greift in den Beutel und zieht ein paar seltsam aussehende Wurzeln heraus.&gt;\n\nMan lege sie ins Feuer und inhaliere!\n\n&lt;Thoralius atmet tief ein. Sein Körper fängt an zu zittern.&gt;\n\nWa... Was... Es kann nicht sein... Ich kann es nicht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11334] = {title = "Er schießt, er trifft!", objective = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.", description = "[PH] Shoot a marked target.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][11335] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, <Name>. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", progress = "Wie ist die Lage, <Name>? Gibt es Neuigkeiten von der Front?", completion = "Das sind gute Neuigkeiten, &lt;Klasse&gt;! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", rewards = "Ihr bekommt:\n\nEhrenabzeichen des ArathibeckensEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11336] = {title = "Ruf zu den Waffen: Alteractal", objective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, <Name>, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", progress = "Wie ist die Lage, <Name>? Gibt es Neuigkeiten von der Front?", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", rewards = "Ihr bekommt:\n\nEhrenabzeichen des AlteractalsEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11337] = {title = "Ruf zu den Waffen: Auge des Sturms", objective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Der Kampf gegen die Horde kennt keine Grenzen, <Name>. Sogar in der Scherbenwelt gibt es beständig Streitigkeiten über Gebietsansprüche und alter Hass wird von Neuem entfacht. Krieg ist allgegenwärtig!\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz, genau wie in Azeroth, obsiegen wird.", progress = nil, completion = "Wir sind dem endgültigen Sieg über die Horde wieder einen Schritt näher gekommen. Niemals dürfen wir zulassen, dass der Feind sich einen Brückenkopf in dieser oder in irgendeiner anderen Welt sichert.", rewards = "Ihr bekommt:\n\nEhrenabzeichen vom Auge des SturmsEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11338] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", rewards = "Ihr bekommt:\n\nEhrenabzeichen der KriegshymnenschluchtEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11339] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, <Klasse>! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", progress = "Ihr seid schon zurück? Bringt Ihr Nachricht von Sieg?", completion = "Ihr habt der Horde heute ehrenvoll gedient, &lt;Name&gt;. Der heutige Sieg sichert uns tausend weitere Siege!", rewards = "Ihr bekommt:\n\nEhrenabzeichen des ArathibeckensEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11340] = {title = "Ruf zu den Waffen: Alteractal", objective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, <Name>. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Es gibt nichts Ehrenvolleres, als die feindlichen Invasoren aus dem Gebiet der Horde zu vertreiben. Ich verneige mich vor Eurem Mut und danke Euch dafür, dass Ihr unseren Streitkräften heute einen großen Dienst erwiesen habt!", rewards = "Ihr bekommt:\n\nEhrenabzeichen des AlteractalsEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11341] = {title = "Ruf zu den Waffen: Auge des Sturms", objective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wo auch immer wir dem Feind begegnen, werden wir ihn bekämpfen und vernichten. Egal ob dies in Azeroth, in der Scherbenwelt oder irgendwo sonst auf der Welt getan werden muss.\n\nWir dürfen nicht zulassen, dass die Allianz ihre Position im Auge des Sturms weiter festigt. Bringen wir den Kampf also zu ihnen... denn morgen ist es vielleicht schon zu spät.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Ihr ehrt uns alle, &lt;Name&gt;. Wir müssen dem Feind zeigen, dass wir ihn immer und überall bekämpfen können!", rewards = "Ihr bekommt:\n\nEhrenabzeichen vom Auge des SturmsEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11342] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Allianz ist ein heimtückischer Gegner, <Name>. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", progress = nil, completion = "Die Horde steht in Eurer Schuld, &lt;Name&gt;. Euer Mut und Einsatz während der Verteidigung unseres Landes macht uns alle stolz.", rewards = "Ihr bekommt:\n\nEhrenabzeichen der KriegshymnenschluchtEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][11343] = {title = "Das Echo von Ymiron", objective = "Thoralius der Weise möchte, dass Ihr die Geisterwelt betretet und Wyrmskol nach Informationen über die Geheimnisse von Wyrmskol durchsucht.", description = "Die Geisterwelt ist unter den Einfluss des Lichkönigs geraten. Furcht erregende Kreaturen, aus Alpträumen geformt, wachen nun über das Reich der Elemente. Ich spüre, dass diese Val'kyr ein schreckliches Geheimnis wahren.\n\nIch bin zu alt und schwach, um eine weitere Reise zu überstehen. Ihr müsst an meiner statt gehen, <Name>.\n\nNehmt dieses Räuchergefäß, geht nach Wyrmskol und begebt Euch mit seiner Hilfe ins Geisterreich. Geht nach Nordosten! Dort befindet sich der Ort. Meidet die Val'kyr um jeden Preis, damit Ihr nicht ihr Schicksal teilen müsst und auf ewig in ihrer Welt gefangen seid.", progress = "Was habt Ihr entdeckt?", completion = "Ich verstehe nicht. Die Kreaturen, die Ihr gesehen habt, sahen genauso aus, wie die Vrykul, die Valgarde angreifen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11344] = {title = "Die Qualen von Niffelvar", objective = "Thoralius der Weise möchte, dass Ihr die Geisterwelt betretet und Niffelvar nach Informationen über die Geheimnisse von Niffelvar durchsucht.", description = "Alles, was wir über die Vrykul wissen, deutet darauf hin, dass sie erst vor Kurzem in Nordend auftauchten. Wie kann es dann sein, dass wir Visionen von Vrykul sehen, die 15.000 Jahre zurückreichen? Hätten die Vrykul zuvor schon in Nordend existiert, wüssten wir mit Sicherheit davon.\n\nSetzt Eure Reise fort und begebt Euch nach Niffelvar. Der Weg, den Ihr nehmen müsst, führt Euch nach Nordosten, durch Wyrmskol hindurch und den Pfad hoch in Richtung Damm. Auf der anderen Seite des Dammes, auf den Klippen, befindet sich schließlich Niffelvar.\n\nMacht von dem Räuchergefäß Gebrauch, sobald Ihr dort angekommen seid, und sucht in der Gegend nach Hinweisen.", progress = nil, completion = "Menschenkinder, die von Vrykul in die Welt gesetzt wurden? Und Ymiron gab Befehl, alle menschlichen Nachkommen zu töten?\n\n&lt;Thoralius verstummt für einen Moment.&gt;\n\nSo sehr ich es leugnen möchte, was mir so deutlich vor Augen geführt wurde: ich kann es nicht. Es gibt kein ausgestorbenes \"fehlendes Bindeglied\", das die Herkunft der Menschen klären würde. Die Vrykul sind das fehlende Bindeglied - sie sind die Vorfahren der Menschheit.", rewards = "Blauvelts Handschuhe für den besonderen MomentEhrfurchtgebietende WorgfellkappeGeschuppte FlinkfingerhandschuheAntike verstärkte BeinschützerIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11345] = {title = "Preise für Kugeln", objective = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.", description = "[PH] Shoot a marked target.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n[PH] Tiny Creepy Rag Doll"}
MultiLanguageQuestData['de'][11346] = {title = "Das Buch der Runen", objective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr ihm das Buch der Runen bringt.", description = "Das Plateau der Riesen, das weite steinige Gebiet im Südosten, wurde von Eisenzwergen regelrecht überflutet. Späher haben von Zwergen berichtet, die Steinriesen aus dem Boden locken, um dann Runen in ihre Haut zu meißeln.\n\nWas sie dazu treibt ist mir unerklärlich, aber ich vermute, dass sie irgendwie versuchen, aus den Riesen Waffen zu machen. Die Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch, <Name>.", progress = "Habt Ihr das Buch bei Euch?", completion = "&lt;Ausgrabungsleiter Belvar blättert durch das Buch der Runen.&gt;\n\nHmm... hier steht so viel geschrieben. Ich werde eine Weile brauchen, um mich eingehend damit zu befassen - und wenn wir diese Runen verstehen wollen, dann werden wir versuchen müssen, unsere eigenen herzustellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11348] = {title = "Die Rune des Befehls", objective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr die Rune des Befehls austestet und Binder Murdis besiegt.", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", progress = nil, completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nUnser Wissen darüber, wie sie Runen handhaben, hat sich stark vergrößert. Womöglich werden wir bei der nächsten Begegnung mit den Zwergen daraus einen Vorteil ziehen können.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11349] = {title = "Die Runen meistern", objective = "Bringt Ausgrabungsleiter Belvar in Fort Wildervar ein Set mit Eisenrunenwerkzeugen.", description = "Ich habe eine Reihe von Hacken, Hämmern und Meißeln bei mir, die jedoch nicht dazu geeignet sind, die Runen in den Stein zu hauen. Die Werkzeuge der Eisenzwerge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das über bloße Wörter hinausgeht. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nIch meine zu wissen, wie es funktioniert, doch ohne diese Werkzeuge, bin ich mir nicht sicher, ob es klappen wird. Sucht in der Nähe der Eisenzwergzelte auf dem Plateau der Riesen nach Sets, die so aussehen wie meins hier, und bringt sie mir.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "&lt;Belvar nimmt die Werkzeuge vorsichtig in die Hand.&gt;\n\nIch werde sie einmal ausprobieren. Wenn wir die Motive der Eisenzwerge ergründen und sie besiegen wollen, dann muss ich mir über die Wirkung der Runen im Klaren sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11350] = {title = "Das Buch der Runen", objective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr ihm das Buch der Runen bringt.", description = "Ich wurde von Häuptling Aschtotem zum Plateau der Riesen geschickt, einem breiten, felsigen Plateau im Südosten, auf der anderen Seite der Gefrorenen Lichtung.\n\nDie Gegend wurde von den Eisenzwergen erobert, die allem Anschein nach die Riesen umwandeln, die aus dem Boden brechen.\n\nDie Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch. Es ist unsere einzige Möglichkeit, wie wir hinter ihre Pläne kommen können.", progress = "Habt Ihr das Buch bei Euch?", completion = "&lt;Der Fernläufer blättert durch das Buch der Runen.&gt;\n\nIch bin zwar kein Geschichtskundiger, jedoch mit der Sprache der Eisenzwerge vertraut. Ich denke, dass die Runen, die sie in die Haut der Riesen ritzen, ihrer Sprache entstammen - nur gibt es da ein paar Unterschiede.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11351] = {title = "Die Runen meistern", objective = "Bringt Fernläufer Pembe im Lager der Winterhufe ein Set mit Eisenrunenwerkzeugen.", description = "Ich denke, dass ich herausgefunden habe, was die Eisenzwerge dort machen: Ihre Werkzeuge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das mehr ist als nur bloße Wörter. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nWenn ich ein Set mit solchen Werkzeugen hätte, könnte ich die Runen dieses Buchs nachmachen. Ich konnte zwar einen dieser Kästen in den Zelten auf dem Plateau der Riesen finden, doch er war leer. Haltet nach ähnlichen Kästen Ausschau, sucht nach einem Set dieser Werkzeuge und bringt es mir.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "&lt;Pembe sieht sich die Werkzeuge genauer an.&gt;\n\nSie sind zerbrechlicher als ich dachte. Gebt mir einen Augenblick, damit ich sie ausprobieren kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11352] = {title = "Die Rune des Befehls", objective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr die Rune des Befehls ausprobiert und Binder Murdis besiegt.", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", progress = "Habt Ihr versucht, die Rune einzusetzen?", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nMein Volk wird den Eisenzwergen auf seinem Zug gen Norden sicherlich noch einmal begegnen. Doch das nächste Mal werden wir bereit sein und ihre Pläne durchkreuzen, bevor sie richtig loslegen können.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11354] = {title = "Gesucht: Nazans Reitgerte", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Nazans Reitgerte zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Der heutige Käufer interessiert sich für ein Stück, das sich momentan noch im Besitz des Reittiers von Illidans Herold befindet. Ich spreche natürlich von Vazruden dem Herold und seinem Drachenreittier Nazan.\n\nWenn Euch der Finderlohn angemessen erscheint, solltet Ihr Euch zum Bollwerk der Höllenfeuerzitadelle aufmachen und mir die Reitgerte des Drachen beschaffen.\n\nMeine Quellen versicherten mir, dass sich die Reitgerte im Besitz des Drachen höchstpersönlich befindet. Anscheinend verbot dieser seinem Herren die Benutzung der Gerte.", progress = "Die Reitgerte, bitte!", completion = "Wieder ein zufriedener Kunde. Der Gegenstand scheint in gutem Zustand zu sein, hervorragend. Ihr werdet entsprechend entlohnt werden.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11355] = {title = "Marsch der Riesen", objective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr mithilfe der runensuchenden Hacke die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Was genau ihr endgültiges Reiseziel ist, weiß ich nicht.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung.\n\nDeaktiviert mithilfe dieser Hacke die Runen auf den Leichen der Riesen und kehrt mit Euren Funden zu mir zurück.", progress = nil, completion = "&lt;Forscher Aderan lauscht Euren Worten, als Ihr von Euren Funden berichtet.&gt;\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Hier wird also nachdrücklich befohlen, in diese Richtung zu ziehen, doch die Runen sind mehr als nur Antrieb. Irgendetwas zieht sie an, nur was?", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11356] = {title = "Kostümierte Waisenmatrone", objective = "Sprecht mit einer kostümierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", description = "Während der Schlotternächte werden von den Waisenhäusern der Menschen Ausflüge für die Waisenkinder organisiert. Die Kinder sollen Allianzdörfer auf dem Land besuchen. Die armen Kleinen würden so gerne einen wahren Helden wie Euch sehen!\n\nWarum stattet Ihr ihnen keinen Besuch ab? Ihr findet die Waisenkinder in Goldhain im Wald von Elwynn, in Kharanos in Dun Morogh und bei der Azurwacht auf der Azurmythosinsel. Sprecht mit der Aufsicht der Kinder, einer kostümierten Waisenmatrone, sie wird Euch den Kindern vorstellen.", progress = nil, completion = "Ihr seid hier, um die Kinder zu besuchen! Wie wundervoll! In ihrem kurzen Leben ist ihnen so viel Kummer widerfahren. Es ist gut, dass sie einen wahren Helden wie Euch sehen. Es hellt ihr Gemüt wirklich auf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11357] = {title = "Maskierte Waisenmatrone", objective = "Sprecht mit einer maskierten Waisenmatrone in Klingenhügel, Brill oder beim Falkenplatz.", description = "Während der Schlotternächte werden mit den Orcwaisenkindern Ausflüge zu zahlreichen Dörfern der Horde unternommen. Die Waisenmatronen dachten, dass es vielleicht gut für die Kinder wäre, wenn sie wahren Helden einmal bei der Arbeit zusehen könnten.\n\nWarum besucht Ihr sie nicht? <Ein mutiger/Eine mutige:c> <Klasse> wie Ihr könnte ihre Gemüter mit Geschichten Eurer Heldentaten aufhellen! Geht entweder nach Klingenhügel in Durotar, Brill in Tirisfal oder zum Falkenplatz im Immersangwald. Sprecht mit der maskierten Waisenmatrone und sie wird Euch den Kindern vorstellen.", progress = nil, completion = "Die Kinder lieben es, wenn sie Helden bei ihrer Arbeit zusehen können. Ich hoffe, dass ein jedes dieser Kinder einmal ein starkes Mitglied der Horde sein und letztendlich in einer glorreichen Schlacht sterben wird!\n\nAh, der Gedanke an ein solch ehrbares Schicksal rührt mich zu Tränen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11358] = {title = "Der Leitstein", objective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr das Probestück einer Rune mit der zerbrochenen Schrifttafel vergleicht.", description = "Wenn wir ausfindig machen könnten, was die Riesen nach Nordwesten zieht, könnten wir sie vielleicht aufhalten, bevor sie ihr Ziel erreichen.\n\nIch konnte zwar viele der Runenprobestücke, die Ihr mir gebracht habt, entziffern, doch diejenigen, die ich nicht kenne, beunruhigen mich am meisten. Als ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt dieses Probestück, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", progress = nil, completion = "&lt;Aderan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.&gt;\n\nNatürlich! Dieser Megalith muss der Schlüssel zu den Plänen der Eisenzwerge sein. Wir müssen ihn zerstören, bevor sie ihren Plan in die Tat umsetzen können!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11359] = {title = "Megalith zertrümmern", objective = "Bezwingt Megalith und kehrt anschließend zu Forscher Aderan in Fort Wildervar zurück.", description = "Mit Megalith schuf Binder Murdis den Mächtigsten unter den mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Nachdem die Expeditionskorps eingetroffen sind, werden unsere Soldaten die restlichen Riesen isolieren und besiegen können und auf diese Weise ihre eisenzwergischen Meister aus ihren Lagern vertreiben.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", progress = nil, completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort, der diesen Namen trägt, ist mir zwar unbekannt, doch es klingt wie ein Wort titanischen Ursprungs. Was haben die Eisenzwerge mit solch einem Ding vor? Wir sollten die Sache im Auge behalten, &lt;Name&gt;, denn wir müssen das Ding finden, bevor die Eisenzwerge ihren Plan in die Tat umsetzen können.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11360] = {title = "Übung bei der Brandwache", objective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind alle Helden von Goldhain bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nEinige Wachen haben nördlich von hier ein kleines Lager für Übungen der Brandwache errichtet. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen oder das in der Nähe der Feuer stehende Fass verwenden.\n\nBis dann, <Name>. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", progress = "Hallo, <Name>. Habt Ihr Euch im Feuerlöschen geübt? Vergesst das Übungslager im Norden nicht!", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11361] = {title = "Feuerübung", objective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Klingenhügel.", description = "Die Grunzer haben ein Übungslager zum Feuerlöschen außerhalb des Dorfes aufgebaut. In letzter Zeit fangen die Gebäude in Klingenhügel rasch Feuer - Ihr solltet helfen und Euch im Feuerlöschen üben!\n\nVerlasst Klingenhügel in Richtung Westen und biegt rechts ab, wenn Ihr an der Stadtmauer vorbei seid. Haltet nach dem Übungslager Ausschau. Schnappt Euch Wassereimer und löscht damit die Übungsfeuer.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Kinder, seht Euch diesen Helden gut an. Werdet alle so stark und mutig wie er, dann werdet auch Ihr eines Tages für die Horde kämpfen.", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11362] = {title = "Gesucht: Keli'dans gefiederter Stab", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Keli'dans gefiederten Stab zu beschaffen. Bringt ihn zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Die Geschmäcker sind sehr verschieden, nehmt zum Beispiel meinen neuesten Käufer.\n\nIn der Höllenfeuerzitadelle residiert ein Blutorc namens Keli'dan der Zerstörer. Dieser Orc ist im Besitz eines recht gewöhnlichen Stabes; nichts, was einen zweiten Blick wert wäre. Und doch ist es genau dieser Stab, den mein Kunde wünscht.\n\nWer bin ich schon, dass ich diesen Auftrag ablehnen könnte?\n\nAlso, wenn Ihr von mir entlohnt werden wollt, solltet Ihr Euch in den Blutkessel begeben, dort werdet Ihr Keli'dan und seinen Stab finden.", progress = "Ihr seid wieder hier... also müsst Ihr den Stab bei Euch tragen!", completion = "Möglicherweise werde ich noch einige frische Federn an den Stab anbringen lassen, bevor ich ihn seinem Käufer übergebe. Mit den ganzen Arakkoas in dieser Gegend sollte das jedoch kein großes Problem darstellen. Ein eher unwichtiges Detail und nichts, das mich davon abhalten könnte, Euch angemessen zu entlohnen.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11363] = {title = "Gesucht: Messerfausts Siegel", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Messerfausts Siegel zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Am heutigen Tage ist ein sehr reicher Sammler an mich herangetreten, dem es nach etwas besonders Einzigartigem verlangt.\n\nKriegshäuptling Kargath Messerfaust trägt sein persönliches Siegel, mit dem er alle offiziellen Dokumente abzeichnet, stehts bei sich. Ich möchte, dass Ihr es für mich beschafft.\n\nIhr findet ihn tief in den Zerschmetterten Hallen. Es besteht kein Zweifel, dass Ihr Euch zunächst durch eine recht beeindruckende Armee kämpfen müsst, bevor Ihr das Siegel in den Händen haltet. Aber ich glaube fest an Euren Erfolg!", progress = "Ich hörte Gerüchte, nach denen der Kriegshäuptling seine Hände durch Waffen hat ersetzen lassen. Ist das wahr?", completion = "Wahrlich eine beeindruckende Akquisition; eine, die es wert ist, dass die Barden noch in Jahrzehnten darüber berichten. Hier, Ihr habt Euch diese Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11364] = {title = "Gesucht: Zenturionen der Zerschmetterten Hand", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Zenturionen der Zerschmetterten Hand zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", description = "Zweifelt Ihr an Eurem Meister? Gut, dann verstehen wir uns, ja?\n\nEs ist das Blut der Zenturionen der Zerschmetterten Hand, nach dem es mich verlangt. Sucht sie in den Zerschmetterten Hallen der Höllenfeuerzitadelle.\n\nWenn Euch die Belohnung lieb ist, werdet Ihr erst zurückkehren, nachdem Ihr sie alle getötet habt.", progress = nil, completion = "Ihr habt Euch Eure Belohnung in der Tat verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11365] = {title = "Marsch der Riesen", objective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr mithilfe der Hacke zum Runensuchen die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Ich weiß nicht, was sie vorhaben, noch wohin sie wollen.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung. Streckt ein paar dieser Riesen nieder - dadurch werden die Runen aufhören zu leuchten, so dass man Proben aus dem Körper der Riesen brechen kann.\n\nNehmt diese Hacke mit Euch und bearbeitet mit ihrer Hilfe die runenbeschriebenen Steinriesen. Dadurch werden die Runen deaktiviert. Kehrt mit Euren Funden zu mir zurück, sobald Ihr Euch mit genug Riesen gemessen habt.", progress = nil, completion = "&lt;Der Weise lauscht Euren Worten, als Ihr von Euren Funden berichtet.&gt;\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Ich bin zwar kein Experte, was diese Runen angeht, aber dass sie sich wiederholen deutet darauf hin, dass es ein ausdrücklicher Befehl ist.\n\nDiese Gravuren sind jedoch mehr als nur Wegweiser. Es scheint, als steuerten sie die Riesen auf etwas zu, nur was?", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11366] = {title = "Der Leitstein", objective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr die Runenprobe mit der zerbrochenen Schrifttafel vergleicht.", description = "Wir müssen herausfinden, was die Riesen nach Nordwesten zieht, damit wir sie aufhalten können, bevor sie ihr Ziel erreichen.\n\nDie Runenproben gaben uns zwar einige Anhaltspunkte, doch es sind die unbekannten Runen, über die ich mir Sorgen mache.\n\nAls ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt diese Probe, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", progress = nil, completion = "&lt;Edan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.&gt;\n\nMegalith? Es ist Wort für Wort das, was auf der Schrifttafel steht! Dieser Megalith muss das Herzstück der rätselhaften Pläne der Eisenhaften darstellen.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11367] = {title = "Megalith zertrümmern", objective = "Bezwingt Megalith und kehrt anschließend zu Weiser Edan im Lager der Winterhufe zurück.", description = "Mit Megalith schuf Binder Murdis eine Art Schlussstein in der Hierarchie der mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Ich werde Häuptling Aschtotem ersuchen, auf unserem Marsch gen Norden ein paar unserer Männer zur Beseitigung des letzten Rests dieser mit Runen versehenen Riesen einzusetzen.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", progress = nil, completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort mit diesem Namen ist meinem Volk unbekannt, doch es klingt, als wäre es von den \"Titanen\" geschaffen, von denen die Außenstehenden sprechen. Die Eisenzwerge waren schon immer ein gerissener und gefährlicher Feind, &lt;Name&gt;. Wir müssen diese Riesen im Auge behalten und Steinschmiede finden, bevor sie ihre Pläne verwirklichen können.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11368] = {title = "Gesucht: Das Herz von Quagmirran", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm das Herz von Quagmirran zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ich habe einen recht ungewöhnlichen Auftrag für Euch. Eine bestimmte wohlhabende Persönlichkeit, mit der ich in außerweltlichem Kontakt stehe, interessiert sich für ein besonders makaberes Stück.\n\nGenau genommen verlangt sie das Herz von Quagmirran.\n\nWie ich hörte, verfügt dieses Biest gleich über drei Herzen, doch ich denke, eines dürfte für unsere Zwecke ausreichend sein. Soweit ich informiert bin, ruht Quagmirran in einem tiefen See in den Sklavenunterkünften des Echsenkessels.", progress = "Ich vertraue darauf, dass Ihr eine Möglichkeit findet, das Herz sicher hierher zu bringen!", completion = "Wenn ich es mir recht überlege, dann ist es eigentlich eine Schande, dass ich Euch nicht darum gebeten habe, mir alle Herzen zu bringen. Vielleicht beim nächsten Mal. Wie auch immer, Ihr habt Euch Euren Anteil redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11369] = {title = "Gesucht: Ei der Schattenmutter", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm ein Ei der Schattenmutter zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Unter den Marschenläufern in den Zangarmarschen gibt es stets nur eine oberste Mutter. Man nennt sie die Schattenmutter und wenn sie stirbt, schlüpft ihre Nachfolgerin aus einem der hinterbliebenen Eier.\n\nEiner meiner Käufer interessiert sich für eben diese Eier. Beiläufig erwähnte er etwas davon, dass das geschlüpfte Wesen eine hervorragende Ergänzung für seinen Zoo wäre.\n\nWenn Euch meine Bezahlung angemessen erscheint, solltet Ihr in den Tiefensumpf aufbrechen und die Schattenmutter töten, um an das Ei zu gelangen.", progress = "Sprechen wir uns wieder, weil Ihr das Ei habt? Fantastisch, lasst es mich sehen!", completion = "Ist es nicht fantastisch, wie sehr man das Leben in diesem Ei spüren kann? Ich werde mich beeilen und es rechtzeitig zu seinem Käufer bringen müssen. Wir wollen doch nicht, dass es hier bei uns schlüpft, nicht wahr?\n\nEure Bezahlung steht bereit.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11370] = {title = "Gesucht: Die Aufzeichnungen des Kriegsherren", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Aufzeichnungen des Kriegsherren zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Vielen ist bekannt, dass Kriegsherr Kalithresh ein hervorragender Stratege ist, doch nur wenige wissen, dass er sein gesamtes Wissen auch niedergeschrieben hat.\n\nEiner meiner Kunden hat davon erfahren und nun wünscht er diese Aufzeichnungen in seinen Besitz zu bringen.\n\nDaher möchte ich Euch bitten, in die Dampfkammer des Echsenkessels einzudringen, um das Buch für mich zu beschaffen.", progress = "Mein Kunde wird langsam ungeduldig. Ich nehme an, er möchte das strategische Wissen des Kriegsherren zur Lösung eines seiner laufenden Konflikte einsetzen.", completion = "Tatsächlich glaube ich, dass mein Kunde nicht genügend Zeit aufbringen kann, um das Buch in seiner Gesamtheit zu studieren. Nun gut, überlassen wir das ihm. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11371] = {title = "Gesucht: Myrmidonen des Echsenkessels", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 14 Myrmidonen des Echsenkessels zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", description = "Mah'duun hat gehört und verstanden. Jetzt sollt Ihr sein Werkzeug sein.\n\nMir wurde offenbart, dass die Myrmidonen des Echsenkessels vernichtet werden müssen. Sucht in den klammen Räumen der Dampfkammer unter dem Echsenkessel nach ihnen.\n\nIch erwarte nichts Geringeres als ihre vollständige Vernichtung.", progress = nil, completion = "Ich nehme an, es war ein Kampf ganz nach Eurem Geschmack? Die Belohnung wird Euch ebenfalls zusagen.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11372] = {title = "Gesucht: Die Kopfschmuckfedern von Ikiss", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Kopfschmuckfedern von Ikiss zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Kürzlich ist eine Taurenfrau an mich herangetreten, deren Ehemann schon bald in den Stand eines Häuptlings erhoben wird. Sie würde ihn gerne mit einer besonderen Verzierung für seinen Federkopfschmuck überraschen.\n\nGenau genommen hätte sie gerne die Kopfschmuckfedern des niederträchtigen Klauenkönigs Ikiss.\n\nWenn Euch meine ausgesetzte Belohnung angemessen erscheint, solltet Ihr zu den Sethekkhallen von Auchindoun aufbrechen und Ikiss einen Besuch abstatten.", progress = "Die Häuptlingszeremonie findet bald statt, beeilt Euch.", completion = "Diese Federn werden dem Kopfschmuck des Häuptlings den letzten Schliff geben. Ihr habt Euch Eure Bezahlung redlich verdient, &lt;Klasse&gt;.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11373] = {title = "Gesucht: Shaffars wundersames Amulett", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Shaffars wundersames Amulett zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Heute möchte ich Euch mit einer persönlichen Angelegenheit beauftragen. Aber keine Sorge, die Belohnung macht die Gefahr wieder mehr als wett.\n\nMeine Familie hat noch eine Rechnung mit Nexusprinz Shaffar und seinen Anhängern offen. Sollte mir sein Amulett in die Hände fallen, wäre dies ein sicheres Zeichen dafür, dass sich jemand seiner angenommen hat.\n\nWenn Euch meine Belohnung angemessen erscheint, solltet Ihr zu seinen Gemächern in der Managruft von Auchindoun aufbrechen.", progress = "Nur wenige wissen, dass Shaffar seine magische Macht ausschließlich aus diesem Amulett bezieht. Ohne es ist er machtlos.\n\nWenn es sich also in Eurem Besitz befindet, lässt dies nur den Schluss zu, dass er tot ist.", completion = "&lt;Eine Woge der Zufriedenheit scheint von dem Windhändler auszugehen.&gt;\n\nGut, es freut mich, von seinem Ende zu hören. Wer weiß, vielleicht gelingt es mir sogar, die Geheimnisse des Amuletts für mich zu nutzen und wenn nicht, werde ich es zu einem angemessenen Preis verkaufen.\n\nIch schätze diese Belohnung ist mehr als ausreichend.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11374] = {title = "Gesucht: Der Seelenedelstein des Exarchen", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Seelenedelstein des Exarchen zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "In dem Bestreben, die nekromantischen Künste besser zu verstehen, werden in der Auchenaikrypta von Auchindoun eine Unzahl von abscheulichen Experimenten durchgeführt. Zahlreich sind die Geister derer, die in den finsteren Hallen gefoltert und ermordet wurden.\n\nEiner meiner Kunden wünscht die Befreiung eines dieser gequälten Geister. Nach meinen Informationen ist dieser Geist in einem Seelenedelstein gefangen, der sich im Besitz von Exarch Maladaar befindet.\n\nSucht ihn mit gebotener Schnelligkeit in der Krypta auf und bringt mir seinen Edelstein.", progress = "Könnt Ihr Euch vorstellen, für alle Ewigkeit in einem Edelstein gefangen zu sein?", completion = "Ihr seid wahrlich ein Held, &lt;Name&gt;. Ich bin mir sicher, dass mein Kunde einen Weg finden wird, um den Geist seiner Geliebten aus dem Edelstein zu befreien. Eure Belohnung für diese hervorragende Arbeit wartet bereits auf Euch.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11375] = {title = "Gesucht: Murmurs Flüstern", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Murmurs Flüstern zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Wenn ich Euch eingeweiht habe, werdet Ihr diesen Auftrag mit Sicherheit nicht mehr annehmen wollen.\n\nEiner meiner besonders exzentrischen Kunden befasst sich mit der Erforschung toter Existenzen. Wenn man diversen Gerüchten Glauben schenkt, zerstörte das als Murmur bekannte Wesen die letzte Welt von der es beschworen wurde vollständig. Der Professor würde gerne das so genannte 'Flüstern' dieser Kreatur analysieren, um zu verstehen, wie Murmur so eine Zerstörung verursachen konnte.\n\nWürdet Ihr für mich in das Schattenlabyrinth in Auchindoun eindringen und das 'Flüstern' für mich beschaffen?", progress = "Ich bin mir nicht einmal sicher, welche Form ein Flüstern in der körperlichen Welt annimmt, aber der Professor versicherte mir, dass Ihr es erkennen werdet, wenn Ihr es seht.\n\nVielleicht ist es so etwas wie der Kehlkopf des Wesens?", completion = "Ich fürchtete schon, Ihr würdet nicht mehr zurückkehren. Ich hoffe doch, der Kampf gegen Murmur hat Euch nicht taub werden lassen?\n\nHier ist Eure Belohnung. Der Professor wird zweifellos sehr zufrieden sein. Ich fürchte mich nur davor, was er mit diesem Gegenstand anfangen wird.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11376] = {title = "Gesucht: Bösartige Ausbilderinnen", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 3 bösartige Ausbilderinnen zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", description = "Mah'duun hat vernommen, dass die Grausamkeit der sechsarmigen Dämonen im Schattenlabyrinth beispiellos ist.\n\nBegebt Euch nach Auchindoun, sucht und tötet sie alle.\n\nBemüht Euch nicht, mich ein zweites Mal aufzusuchen, wenn Ihr scheitert.", progress = "Habt Ihr die Ausbilderinnen alle getötet? Nein?\n\nHabe ich Euch nicht aufgetragen, erst zurückzukehren, wenn alle tot sind?", completion = "Ich bin sehr zufrieden. Auch der, der über den Nether zu mir spricht, ist hoch erfreut. Mah'duun hat Eure Belohnung bereits vorbereitet.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11377] = {title = "Rache ist süß", objective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs einen Kalirieintopf zu kochen. Kehrt anschließend zu ihm zurück.", description = "Heute Abend koche ich für eine ganz besondere Festgemeinschaft. Einer der Gäste flog vor Kurzem in Skettis herum, als er plötzlich von einem riesigen Kaliri erfasst wurde und zu Boden fiel. Er brach sich dabei sein Bein.\n\nFür seine 'Gute Besserungs'-Feier soll nun etwas ganz Besonderes auf dem Speiseplan stehen: Kalirieintopf.\n\nIch werde Euch meinen Topf zur Verfügung stellen und es wird Eure Aufgabe sein, den Eintopf zu kochen. Das Rezept ist an sich recht einfach, Ihr benötigt nur einen riesigen Kaliriflügel und einige Doppelwarper.", progress = "Rieche ich da etwas zu essen?", completion = "Oh, das riecht aber lecker! Ich hoffe, Ihr habt dem Vogel einen guten Kampf geliefert.\n\nBitte, nehmt Euch ruhig etwas von meinen speziellen Vorräten. Jemand mit Eurem Talent sollte damit etwas anfangen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFass mit FischenKiste mit Fleisch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11378] = {title = "Gesucht: Der Kopf des Epochenjägers", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Kopf des Epochenjägers zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Die Geschmäcker meiner Kunden variieren von banal zu sehr exotisch. Und manchmal wollen sie mit den exotischen Gegenständen, die ich ihnen beschaffe, sehr banale Dinge anstellen.\n\nMein momentaner Kunde gehört zu dieser Sorte. Er, dessen Name hier unerwähnt bleiben soll, wünscht sich nichts sehnlicher, als den Kopf des Epochenjägers an seiner Wand aufzuhängen.\n\n<Klasse>, Ihr müsst einen Weg finden, um zurück durch die Zeit ins Alte Hügelland zu reisen und besagten Kopf für unseren Trophäen sammelnden Kunden beschaffen.", progress = "Der Kopf des Epochenjägers... wie kommt jemand bloß auf die Idee, sich diesen an die Wand hängen zu wollen?\n\nSelbst wenn, dann geht man doch selbst auf die Jagd. Was soll man denn den eigenen Freunden erzählen, wenn sie einem Fragen über den Kampfverlauf stellen?\n\nBleibt höchstens eine Notlüge.", completion = "Wie ich sehe, seid Ihr wieder gesund und munter im Hier und Jetzt angekommen.\n\n&lt;Der Windhändler sieht sich um.&gt;\n\nMir scheint, dass sich nichts verändert hat. Auf der anderen Seite, würde ich es wahrscheinlich gar nicht merken.\n\nEin sauberer Schnitt, mein Kunde wird zufrieden sein. Hier ist Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11379] = {title = "Superheißes Ragout", objective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs ein Dämonenragout Surprise, zwei Rippchen der Mok'Nathal und eine Knusperschlange zu kochen. Kehrt anschließend zu ihm zurück.", description = "Ich versuche gerade, etwas ganz Besonderes zu kreieren. Aber um ehrlich zu sein, bin ich mittlerweile eher ein Theoretiker geworden. Irgendwie ist mir mein Sinn für Abenteuer abhandengekommen.\n\nIhr aber... Ihr erinnert mich irgendwie an mich selbst in jungen Jahren. Bereit, sich der Welt mit Schwert und Bratpfanne zu stellen.\n\nIch möchte, dass Ihr meinen Lieblingskochtopf nehmt und Euch zum Schergrat aufmacht. Füllt ihn mit ein paar Rippchen und Knusperschlangen - natürlich gekocht, für die Extraportion Würze. Zum Schluss erhitzt Ihr das Ganze über einem abyssischen Leichnam. Dies ist die einzige Wärmequelle, die heiß genug ist, um dieses Gericht perfekt zu garen.", progress = "Verlief mein kleines Experiment erfolgreich?", completion = "Nun sieh mal einer an...\n\n&lt;Als der Rokk ein wenig von Eurem Gericht probiert, zeichnet sich auf seinem Gesicht eine Mischung aus Entzücken und abnormen Schmerzen ab.&gt;\n\nHeiliger A'dal ist das lecker! Ein Koch mit Eurem Talent braucht stets die richtigen Zutaten! Hier, bedient Euch aus meinen Vorräten und macht mich stolz!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFass mit FischenKiste mit Fleisch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11380] = {title = "Manaziös", objective = "Der Rokk im Unteren Viertel von Shattrath möchte, dass Ihr 15 Manabeeren in den Biokuppeln im Nethersturm sammelt.", description = "War ja klar! Ich denke meine Vorräte sind lückenlos und sofort kommt jemand um die Ecke, der etwas Ausgefallenes haben möchte: Manabeere Surprise.\n\nUnglücklichweise findet man Manabeeren nur in den Biokuppeln des Nethersturms. Aber macht Euch nicht die Mühe, auf der Sturmsäule zu suchen - dort ist alles abgeerntet.\n\nEs bedarf eines wahren Meisters der Kochkunst, um nur die besten Beeren zu pflücken, also enttäuscht mich nicht!", progress = "Hattet Ihr Erfolg?", completion = "Noch nie sah ich so saftige Beeren! Ich fühle mich schon vom bloßen Hingucken geistig gestärkt.\n\nWarum nehmt Ihr nicht etwas von meinen Fisch- und Fleischvorräten? Anscheinend habe ich eh keine Verwendung mehr dafür. Sicherlich werdet Ihr daraus etwas ganz Besonderes kochen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFass mit FischenKiste mit Fleisch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11381] = {title = "Suppe für die Seele", objective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs eine spirituelle Suppe zu kochen. Kehrt anschließend zu ihm zurück.", description = "Irgendetwas liegt in der Luft. Noch nie hatte ich so viele Bestellungen für meine berühmte Suppe - sie weckt die inneren Geister und streichelt die Seele.\n\nIch erkenne einen Koch, wenn ich einen sehe! Würdet Ihr mir im Austausch gegen eine kleine Gewinnbeteiligung ein wenig aushelfen?\n\nHier, nehmt meinen Kochtopf, sammelt etwas Grollhuffleisch und ich verrate Euch ein kleines Geheimnis. Was glaubt Ihr, macht meine Suppe so angenehm für die Seele? Es hat nichts mit Hühnchen zu tun! Es liegt daran, dass ich sie beim Ahnengrund in Nagrand koche, um alles Geisterhafte, das in der Luft schwebt, einzufangen.", progress = "Was riecht hier so gut?", completion = "Das ist eine feine Ladung spirituelle Suppe. Es fehlt nur noch etwas Pfeffer für den richtigen Geschmack!\n\nHier, wie versprochen, Euer Anteil. Und weil Ihr so gute Arbeit geleistet habt, dürft Ihr Euch noch an meinen Vorräten bedienen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFass mit FischenKiste mit Fleisch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11382] = {title = "Gesucht: Aeonus' Stundenglas", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Aeonus' Stundenglas zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Einige meiner Kunden sind wirklich verrückt. Es gibt Dinge, denen man nachjagt und andere, über die man nicht einmal nachdenken sollte!\n\nMein heutiger Kunde ist der Inbegriff von Größenwahn! Er verlangt nichts Geringeres als Aeonus' Stundenglas.\n\nJa, Ihr habt richtig gehört, das Stundenglas von Aeonus, seines Zeichens Angehöriger des ewigen Drachenschwarms!\n\nAber wer bin ich schon, dass ich widersprechen könnte? Insbesondere bei der Menge Gold, die er mir geboten hat. Also, seid Ihr bereit, die Höhlen der Zeit aufzusuchen und in den Schwarzen Morast zu reisen, um das Stundenglas zu beschaffen?", progress = "An Eurer Stelle wäre ich mit Zeitreisen sehr vorsichtig. Schließlich wollt Ihr ja nicht versehentlich einen Eurer eigenen Vorfahren töten und so Eure eigene Existenz in der Gegenwart auslöschen!", completion = "Seltsam, dass der Sand in diesem Ding noch immer aufwärts fließt. Ich schlage vor, wir schaffen es lieber schnellstmöglich zu seinem neuen Besitzer.\n\nIch muss Euch für diese gute Arbeit danken, &lt;Klasse&gt;. Ihr habt Euch Eure Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11383] = {title = "Gesucht: Fürsten der Zeitenrisse", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Fürsten der Zeitenrisse zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", description = "Mah'duun weiß, was zu tun ist. Mah'duun weiß, dass Ihr Fürsten der Zeitenrisse töten müsst. Doch Mah'duun ist sich des Zeitpunkts nicht sicher.\n\nDas klingt alles sicherlich sehr seltsam für Euch, doch die Stimme im Wind sagte mir auch nicht viel mehr.\n\nBegebt Euch in die Höhlen der Zeit und reist in den Schwarzen Morast. Dort wird sich Euch alles offenbaren.", progress = nil, completion = "Anscheinend habt Ihr Euren Weg in die Vergangenheit und wieder zurück gefunden. Eure Fähigkeiten als &lt;Klasse&gt; sind bemerkenswert. Die Belohnung gehört Euch.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11384] = {title = "Gesucht: Warpzweigsplitter", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm einen Warpzweigsplitter zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Vor Kurzem trat eine Druidin der Kaldorei mit einer herzzerreißenden Bitte an mich heran. Gut, sie hatte auch eine ganze Menge Gold bei sich...\n\nEs scheint, als versuchten die Streitkräfte von Darnassus ein arkanes Urtum namens Warpzweig neu zu erschaffen. Dieses gigantische Baumwesen hat sich wohl verirrt oder wurde von der Verderbnis durchdrungen, naja, jedenfalls hält es sich zurzeit in der Botanika der Festung der Stürme auf.", progress = "Schwierigkeiten die Botanika zu finden? Ihr könnt sie gar nicht verfehlen, sie ist ein Teil der Festung der Stürme am östlichen Rand des Nethersturms.", completion = "Oh, Ihr habt es tatsächlich geschafft! Er ist so klein. Unglaublich, das Warpzweig aus diesem kleinen Ding neu erstehen soll und wie man mir sagte, ist es ein ziemlich langwieriger Prozess, den die Druiden da vor sich haben.\n\nEgal, wie versprochen, habe ich hier Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11385] = {title = "Gesucht: Kanalisierer der Sonnensucher", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 6 Kanalisierer der Sonnensucher zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", description = "Mah'duun wurde offenbart, dass die Kanalisierer der als Sonnensucher bekannten Kampfeinheit heute getötet werden müssen.\n\nIhr findet sie in der Botanika der Festung der Stürme.\n\nIhr wollt das Kopfgeld? Also tötet sie!", progress = nil, completion = "Mit den Kanalisierern ist es aus. Der, der aus dem Nether zu mir spricht ist zufrieden und Ihr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11386] = {title = "Gesucht: Pathaleons Projektionsgerät", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Pathaleons Projektionsgerät zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ich habe stets angenommen, Pathaleon könnte sein Abbild nur mithilfe von Magie an die verschiedensten Orte in der Scherbenwelt projizieren. Offensichtlich lag ich damit falsch.\n\nMein neuester Kunde verriet mir, dass der Blutelf stattdessen ein mechanisches Gerät verwendet, um mit den diversen Offizieren von Kael'thas zu kommunizieren. Wenn ich es richtig verstanden habe, stahl er es von einigen Zaxxisrebellen im Nethersturm.\n\nMein Kunde wünscht, dieses Projektionsgerät zu besitzen. Also, warum stattet Ihr Pathaleon nicht einen Besuch ab? Ihr findet ihn in der Mechanar der Festung der Stürme.", progress = "Es ist ja nicht so, dass die Projektionstechnologie alleine schon etwas Besonderes wäre, aber die Reichweite dieses Modells ist enorm und bisher unerreicht!", completion = "Ich bin versucht, es für mich zu behalten und meinem Kunden sein Geld zurückzuzahlen. Mit diesem Gerät könnte ich meine Geschäfte über noch größere Entfernungen abwickeln.\n\n&lt;Der Windhändler seufzt.&gt;\n\nAber ich kann meinen guten Ruf nicht so leichtfertig aufs Spiel setzen.\n\nWo wir schon von meiner Reputation reden, vielen Dank, dass Ihr mir dabei geholfen habt, sie zu wahren. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11387] = {title = "Gesucht: Zerstörer der Sturmschmiede", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Zerstörer der Sturmschmiede zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle vernichtet wurden.", description = "Im Inneren der Mechanar gibt es eine Vielzahl mechanischer Konstrukte und man hat Mah'duun mit ihrer Vernichtung beauftragt.\n\nBetretet die Festung der Stürme, sucht die Zerstörer der Sturmschmiede und vernichtet sie.\n\nKehrt anschließend zurück, um Eure Belohnung zu erhalten.", progress = "<Der Netherpirscher scheint sich über Eure Anwesenheit zu wundern.>\n\nDie Zerstörer sind noch längst nicht alle vernichtet.", completion = "Mah'duun liebt es, gegen Konstrukte zu kämpfen! Sie sind nicht so fehlerbehaftet wie organische Lebewesen.\n\nIhr habt Euch die Belohnung verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11388] = {title = "Gesucht: Horizontiss' Schriftrolle", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm Horizontiss' Schriftrolle zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Meinem heutigen Kunden verlangt es nach etwas besonders Ausgefallenem.\n\nMan erzählt sich, dass Herold Horizontiss ein Jünger der Alten Götter sei. Des Weiteren soll er stets eine Schriftrolle bei sich tragen, die die Anweisungen der Götter für ihn enthalten, alles Leben im Universum in ihrem Namen zu unterwerfen.\n\nObwohl er die Schriftsprache der Rolle nicht entziffern können wird, wünscht mein Kunde dennoch, diese zu besitzen.\n\nDringt in die Arkatraz der Festung der Stürme ein und beschafft sie für mich, <Klasse>!", progress = "Es muss ganz schön gefährlich sein, sich in die Angelegenheiten der Alten Götter einzumischen.\n\nNaja, besser Ihr als ich!", completion = "Bevor ich den Zorn der Alten Götter auf mich ziehe, hüte ich mich lieber davor, die Schriftrolle überhaupt zu berühren. Ich werde einen meiner Assistenten mit der Zustellung beauftragen.\n\nIhr habt Eure Belohnung mehr als verdient, &lt;Klasse&gt;, und ich wünsche Euch für die Zukunft alles Glück der bekannten Welt!\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11389] = {title = "Gesucht: Schildwachen der Arkatraz", objective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Schildwachen der Arkatraz zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", description = "Die Schildwachen der Arkatraz sind wahnsinnig geworden. Die Gefangenen laufen Amok und die Wachen greifen all jene an, die helfen wollen.\n\nMah'duun vernimmt im Raunen des Netherwindes die Stimme des Sprechers. Der Sprecher befiehlt die Vernichtung der Schildwachen.\n\nBringt diese Aufgabe zu Ende und die heutige Belohnung gehört Euch!", progress = nil, completion = "Vielleicht wenden die Naaru sich nach der Vernichtung der Schildwachen an das Konsortium, um Ersatz anzufordern? Mah'duun weiß es nicht und es interessiert ihn auch nicht.\n\nIhr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11390] = {title = "Ich kann fliegen!", objective = "Der Chefarchäologe des Stählernen Tores möchte, dass Ihr 3 Säcke voller Relikte vom Grund der Ausgrabungsstätte zu einer der Plattformen auf der Nord- oder Südseite des Stählernen Tores befördert.\n\nBenutzt den Enterhaken der Flugmaschine für diese Aufgabe.\n\nMeldet Euch bei ihm zurück, sobald Ihr damit fertig seid.", description = "Tja, auf was wartet Ihr denn noch, es gibt viel zu tun!\n\nHier sind die Schlüssel zu unserer Flugmaschine. Schnappt Euch drei Säcke voller Relikte und befördert sie auf die Kranplattformen auf der Nord- und Südseite des Stählernen Tores. Ich werd' sie für Euch markieren.\n\nMacht schnell! Wir haben nicht den ganzen Tag Zeit!", progress = nil, completion = "Gute Arbeit - ich mein' jedoch, dass Ihr über einen Auffrischungskurs in Sachen grundlegende Fliegerei nachdenken solltet.\n\nNun ja, macht nichts, einer ist so gut wie der andere. Hier ist Eure heutige Ausbeute.", rewards = "Knisternder UmhangAuf Euch wartet eine dieser Belohnungen:\n\nSchonungsloses BandWorgzahntalisman\n\nIhr bekommt außerdem:\n\nErstklassiger Heiltrank"}
MultiLanguageQuestData['de'][11391] = {title = "Patrouille am Stählernen Tor", objective = "Für die Leute am Stählernen Tor seid Ihr jetzt ein Fliegerass, also will der Chefarchäologe des Stählernen Tores, dass Ihr über der Ausgrabungsstätte patrouilliert und alle Angreifer bekämpft.\n\nMeldet Euch wieder bei ihm zurück, wenn Ihr Eure Patrouille geflogen habt.", description = "Äh? Heute wieder da zum Arbeiten?\n\nNun gut, hier sind die Schlüssel. Heute muss nichts mehr befördert werden, also haltet nur nach Dingen Ausschau, die verdächtig aussehen, okay?\n\nHab' ein paar Raketen und 'n Maschinengewehr auf sie draufgepackt - für den Fall der Fälle.", progress = nil, completion = "Gut geschossen, Ass.\n\nHier ist Euer Lohn. Kommt morgen wieder und dreht noch 'ne Runde, hört Ihr?", rewards = "Ihr bekommt:\n\nErstklassiger Heiltrank"}
MultiLanguageQuestData['de'][11392] = {title = "Ruft den kopflosen Reiter", objective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11393] = {title = "Wo ist Forscher Jaren?", objective = "Vorarbeiterin Irena Zasterstein hat Euch gebeten, nach ihrem Verlobten Forscher Jaren zu suchen.", description = "<Name>, mein Verlobter Jaren ging mit einer kleinen Gruppe Forscher nach Westen, um Gerüchten über Artefakte entlang der Küste des Frostmaares nachzugehen. Dort unten gibt es jedoch Murlocs und ich befürchte, dass ihnen das Schlimmste zugestoßen sein könnte.\n\nIhr hättet sicherlich Zeit um nachzusehen, ob es ihnen gut geht, oder? Gleich hier in der Nähe, im Südwesten, gibt es einen Weg hinunter zum Strand - hütet Euch jedoch vor den Worgs und anderen Dingen, die im Wald herumstreunen.", progress = nil, completion = "&lt;Der Forscher wirf Euch ein Lächeln zu, als Ihr ihm erzählt, wer Euch geschickt hat. Mit gedämpfter Stimme fährt er fort.&gt;\n\nIrena hat sich um mich Sorgen gemacht? Das hat sie von ihrem Vater, müsst Ihr wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11394] = {title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", objective = "Forscher Jaren hat Euch gebeten, entlang der Küste des Frostmaares wahllos 15 Diener der Geißel zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", description = "Ich bin ursprünglich hierhergekommen, um ein paar Gerüchten über auszugrabende Artefakte nachzugehen. Ich hab' zwar gewusst, dass es entlang dieser Küste Murlocs gibt, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde.\n\n<Der Forscher reckt seinen Hals und späht hinter dem Baum hervor.>\n\nDie Diener der Geißel sind dort draußen und sie verwandeln Murlocs und überhaupt alles, was ihnen in die Finger gerät, in wandelnde Tote!\n\n<Klasse>, ich denke, dass es unsere Pflicht ist, etwas dagegen zu unternehmen. Wäre es denkbar für Euch, einen guten Teil dieser Geißel zu beseitigen?", progress = nil, completion = "&lt;Jaren wirkt sehr erfreut über Euren Erfolg, macht jedoch Zeichen, dass Ihr flüstern sollt.&gt;\n\nGute Arbeit, &lt;Name&gt;! Eure Kleidung hat jedoch eine Menge von diesem klebrigem Geißelzeugs abbekommen. Vielleicht solltet Ihr Euch über ein kurzes Bad Gedanken machen. Das Wasser ist zwar kalt, wird Euch jedoch im Nu von dem Dreck befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11395] = {title = "Es ist eine Vorrichtung der Geißel", objective = "Liefert die Vorrichtung der Geißel bei Forscher Jaren an der Küste des Frostmaares ab.", description = "Der Diener der Geißel, den Ihr soeben erlegt habt, hielt in seinen Klauen dieses Gerät. In ihm eingefasst, befindet sich ein Juwel, ähnlich den Juwelen, welche die Spitze geißelnder Kristalle bilden.\n\nForscher Jaren würde sicherlich gerne einen Blick darauf werfen.", progress = "Was für ein seltsam anzusehendes Gerät Ihr da habt, <Klasse>. Lasst mich einmal einen besseren Blick drauf werfen.", completion = "Ich weiß, was das ist! &lt;Name&gt;, es ist eine Steuerung für diese geißelnden Kristalle!\n\nIch würde alles darauf verwetten, dass man mit ihrer Hilfe die Kraftfelder abschalten kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11396] = {title = "Die Schilde abschalten", objective = "Forscher Jaren an der Küste des Frostmaares hat Euch gebeten, 3 geißelnde Kristalle zu zerstören.", description = "Seht Euch den Knopf an der Seite der Steuerung an - hier. Ich könnte wetten, dass man mithilfe der Steuerung dessen Schild abschalten könnte, wenn man nur nahe genug an einen der geißelnden Kristalle herankäme. Danach müsste das Ding nur rechtzeitig zerstört werden, bevor es seinen Schild wieder aktiviert.\n\nWas sagt Ihr dazu, <Name>? Lust? Ich kann Euch versprechen, dass eine nette Belohnung winken würde, brächtet Ihr es zustande, die Schilde abzuschalten und die Kristalle zu zerstören.\n\nEs ist das Mindeste, was wir tun können, um die Geißel daran zu hindern, noch mehr Ihresgleichen zu erschaffen.", progress = nil, completion = "Sehr schön!\n\n&lt;Jaren wendet seinen Blick hastig in alle Richtungen, um nachzusehen, ob auch niemand seinen Ausbruch bemerkt hat.&gt;\n\nGut, Ihr habt es Euch redlich verdient, hiervon eines auszusuchen - ich fand sie, als ich dort unten war.\n\nUnd &lt;Name&gt;, sagt Irena, dass ich sie liebe und dass es mir gut geht, falls Ihr wieder beim Stählernen Tor vorbeischauen solltet.", rewards = "Widdergehörnter GroßhelmGhulzerquetschende StampferAuf Euch wartet eine dieser Belohnungen:\n\nErdbinders Band der RegenarationErfüllte Froststeinrune\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11397] = {title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", objective = "Apothekerin Anastasia möchte, dass Ihr entlang der Küste des Frostmaares wahllos 15 Diener der Geißel vernichtet. Kehrt zu ihr zurück, sobald Ihr Eure Aufgabe erledigt habt. Sie befindet sich im Apothekerlager.", description = "Ich bin hierhergekommen, um ein Gerücht zu untersuchen, nach dem die Geißel hier in der Nähe präsent sei. Ich hatte zwar erwartet, entlang der Küste dort unten Murlocs vorzufinden, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde!\n\nDie Diener der Geißel sind dort unten und sie verwandeln Murlocs und überhaupt alles, was sie in die Finger bekommen, in wandelnde Tote!\n\n<Klasse>, wir werden es nicht hinnehmen, dass sie noch mehr Ihresgleichen erschaffen - ganz besonders nicht aus Murlocs! Nicht weit weg vom Lager, im Nordwesten, befindet sich eine Rampe, die hinunter zum Strand führt. Seht zu, dass Ihr Euch rechtzeitig um die Geißel kümmert!", progress = nil, completion = "&lt;Anastasia scheint sich eine Zeit lang Gedanken über Euren Erfolg zu machen.&gt;\n\nIhr habt Eure Aufgabe sicherlich zufriedenstellend erledigt, doch irgendwie habe ich das Gefühl, als müssten wir etwas anderes tun, um der Geißel auf diesem Strand Einhalt zu gebieten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11398] = {title = "Es ist eine Vorrichtung der Geißel", objective = "Liefert die Vorrichtung der Geißel bei Apothekerin Anastasia im Apothekerlager ab.", description = "Der Diener der Geißel, den Ihr soeben erlegt habt, hielt in seinen Klauen dieses Gerät. In ihm eingefasst, befindet sich ein Juwel, ähnlich den Juwelen, welche die Spitze geißelnder Kristalle bilden.\n\nApothekerin Anastasia würde sicherlich gerne einen Blick darauf werfen.", progress = "Was habt Ihr denn da, <Klasse>? Lasst mich einmal einen besseren Blick darauf werfen!", completion = "Ich kann Euch sagen, was das hier ist, &lt;Name&gt;. Es ist ein Steuergerät für die geißelnden Kristalle dort unten!\n\nIch würde alles darauf verwetten, dass man mit ihrer Hilfe die Kraftfelder abschalten kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11399] = {title = "Die Schilde abschalten", objective = "Apothekerin Anastasia im Apothekerlager hat Euch gebeten, 3 geißelnde Kristalle zu zerstören.", description = "Seht Euch den Knopf an der Seite der Steuerung an - hier. Ich könnte wetten, dass, käme man nahe genug an einen der geißelnden Kristalle heran, man mithilfe der Steuerung dessen Schild abschalten könnte. Danach müsste man das Ding nur rechtzeitig zerstören, bevor es seinen Schild wieder aktiviert.\n\nMutig genug, einen weiteren Abstecher dort hinunter zu wagen, <Name>? Ich kann Euch versprechen, dass eine nette Belohnung winken würde, brächtet Ihr es zustande, die Schilde abzuschalten und die Kristalle zu zerstören.\n\nEs würde weniger Diener der Geißel bedeuten und dazu noch aus Murlocs geschaffene: Wie könntet Ihr es dann auch ablehnen?", progress = nil, completion = "&lt;Anastasia dreht sich um und wirft ihrer Sukkubus ein Lächeln zu.&gt;\n\nAlso gut, &lt;Name&gt;, ich gestehe, dass Ihr gewiss verdient habt, Euch hiervon eins auszusuchen.", rewards = "Widdergehörnter GroßhelmGhulzerquetschende StampferAuf Euch wartet eine dieser Belohnungen:\n\nErdbinders Band der RegenarationErfüllte Froststeinrune\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11400] = {title = "Braufestwidder", objective = "Bringt den Handstempel \"Ehrenbrauer\" zu Pol Bernruh in der Nähe des Eingangs zum Braufestplatz in Dun Morogh.", description = "Wenn Ihr Pol Bernruh, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11401] = {title = "Ruft den kopflosen Reiter", objective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11402] = {title = "Clayton's Quest: Extreme!", objective = "Seriously, go slay those Evil Squirrels!", description = "Clayton wants you to find and slay twenty Evil Squirrels.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11403] = {title = "Endlich frei!", objective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Durotar, Brill oder beim Falkenplatz.", description = "Zorn hielt mich gefangen, <Name>, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", progress = "Schön, Euch wiederzusehen, <Name>. Ich bin sicher, die Kinder freuen sich schon auf die Geschichten über Eure Heldentaten.", completion = "Was sagt Ihr? Dieser heilige Foliant gehörte einst einem gefallenen Paladin der Allianz. War er der kopflose Reiter? Also wurde er endlich besiegt?\n\nWas für ein glorreicher Tag, &lt;Name&gt;! Eure Legende wird wachsen! Möge man noch von Euch berichten, wenn die Schreckensherrschaft des kopflosen Reiters längst vergessen ist.", rewards = "Ihr bekommt:\n\nKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11404] = {title = "Ruft den kopflosen Reiter", objective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11405] = {title = "Ruft den kopflosen Reiter", objective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11406] = {title = "Alles muss bereit sein", objective = "Sprecht mit Gil Grisert in Fort Wildervar.", description = "Hauptmann Adams erwartet, dass alle Vorbereitungen in Fort Wildervar getroffen sind, sobald das Expeditionskorps gen Norden zieht. Die dortigen Späher und Handwerker wurden damit beauftragt, die Ausrüstungen und Rationen unserer Männer für den Aufstieg in die Hügel bereitzustellen.\n\nDer Hauptmann ist für sein hitziges Temperament berüchtigt, also möchte ich jemanden vorausschicken, um nach den Vorbereitungen zu sehen. Fort Wildervar befindet sich weit im Nordosten, jenseits von Skorn, in dem schneebedeckten Gebiet, das an die Grizzlyhügel grenzt. Sucht dort nach Gil Grisert und sorgt dafür, dass er bereit ist.", progress = nil, completion = "Der Rüstmeister hat Euch also geschickt?\n\n&lt;Gil wirkt erleichtert.&gt;\n\nUm ehrlich zu sein, hinken wir hier ein bisschen hinterher und bräuchten etwas Hilfe, wenn wir unsere Ziele erfüllen wollen.\n\n&lt;Gil läuft es kalt den Rücken hinunter.&gt;\n\nKeiner meiner Männer hat Lust, Hauptmann Adams' Zorn die Stirn bieten zu müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11407] = {title = "Marktschreier für die Brauerei Drohn!", objective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", description = "Ihr wollt dem Braufest also zu Stärke und Ehre verhelfen. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nWir werden Euch einen Rennwidder für 4 Minuten borgen.\n\nSeid aber vorsichtig. Diese geizigen Goblins haben entlang der Strecke keine Apfelkisten aufgestellt.", progress = nil, completion = "Ihr habt Euer Wort gehalten und die Kunde von unseren Braumeistern verbreitet. Vielen Dank. Wir haben Euch diese Lose versprochen, hier habt Ihr sie. Ich kann mir gut vorstellen, dass die Trolle ihre Lose nicht so einfach rausrücken...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11408] = {title = "Marktschreier für T'chalis Voodoobrauerei!", objective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", description = "Wir müssen alle wissen lassen, dass die Trolle auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nIch werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder für 4 Minuten borge.\n\nSeid aber vorsichtig. Die Goblins haben entlang der Strecke keine Apfelkisten aufgestellt... so was von geizig.", progress = nil, completion = "Ihr habt's wirklich gemacht! Wir müssen uns gleich auf den Ansturm der Besucher vorbereiten, die sicher schon auf dem Weg sind! Danke!\n\nOh, richtig, wir hatten Euch eine Belohnung versprochen. Das dürfen wir natürlich nicht vergessen...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11409] = {title = "Das ist Widderrennen... zumindest fast", objective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich lasse Euch dafür auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", progress = "Kommt Ihr mit dem Reitwidder zurecht?", completion = "Hey, das war gar nicht schlecht... seid Ihr sicher, dass Ihr kein Zwerg seid?\n\nEs gibt noch viel mehr Rennen, nicht nur von meiner Seite. Ihr werdet auf dem gesamten Braufestplatz Leute finden, die nach einem ordentlichen Widderrennmeister suchen. Also dann, macht Euch selbst mal nützlich.\n\nOh! Nicht, dass Ihr's vergesst, diese Widder wurden auf legale Weise erworben. Nur damit wir uns verstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11410] = {title = "Der Eine, der entkam", objective = "Christopher Sloan in Fort Wildervar möchte, dass Ihr Frostflosse besiegt.", description = "Die Barbe, die Ihr gebracht habt, sollte zwar ein guter Köder für die meisten Fische sein, doch ich befürchte, dass sie die Aufmerksamkeit eines Monsters erregen wird!\n\nAls ich das erste Mal hier war, brachte ich ein wenig von Nat Pagles Lieblingsköder an meinem Haken an und warf ihn ins Wasser aus. Allerdings klammerte sich ein riesiges Monster mit mächtigen Zähnen und Eiszapfen, die von seinen Flossen hingen, daran fest!\n\nEs hätte mich ins eisige Wasser gezogen, hätte ich die Leine nicht durchschnitten! Ich kann den neuen Köder nicht benutzen, solang' sich niemand um die alte Frostflosse kümmert. Nehmt diesen Köder und werft ihn in der Nähe des versunkenen Bootes in der Mitte des Sees aus. Frostflosse wird nicht widerstehen können!", progress = nil, completion = "Endlich können wir in Ruhe fischen gehen! Aber es wird sowieso darauf hinauslaufen, dass sobald wir etwas fangen, das Expeditionskorps eintreffen und alles für sich beanspruchen wird.\n\nHabt unseren Dank, &lt;Name&gt;. Fühlt Euch hier bei uns wie Zuhause.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11411] = {title = "Lager der Winterhufe", objective = "Sprecht mit Häuptling Aschtotem im Lager der Winterhufe.", description = "Auf meinen Reisen als Kurier habe ich schon viele seltsame Bewohner des Heulenden Fjords gesehen, doch eine Gruppe stach mir besonders ins Auge. Aus der Ferne sehen sie aus wie Tauren, doch bei näherer Betrachtung kann man erkennen, dass sie völlig verschieden sind - stämmiger und zotteliger.\n\nIch fand eine ihrer Siedlungen weit im Norden, jenseits von Halgrind, Skorn und den nördlichen Wäldern. Das Lager der Winterhufe, so wird es genannt. Es liegt inmitten der Ausläufer des Gjalerhorn, nahe der Grenze zu den Grizzlyhügeln. Nehmt Kontakt mit ihnen auf und seht nach, ob sie für uns von Nutzen sein könnten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11412] = {title = "Hin und zurück", objective = "Holt bei dem Goblin, der auf der Straße zur Messerbucht festsitzt, ein Fässchen ab und bringt es zu Widdermeister Rays Assistenten. Wenn Ihr Euren Widder verliert, könnt Ihr Widdermeister Ray nach Ersatz fragen.", description = "Ich bin froh, dass Ihr hier seid. Wir haben einiges um die Ohren! Der Goblin, der uns mehr Gebräu bringen sollte, hatte auf seinem Weg von der Messerbucht hierher einen Unfall. Ihr müsst uns das Gebräu zustellen!\n\nIch werde Euch auf einen meiner Rennwidder setzen und Ihr folgt einfach der Straße zur Messerbucht.\n\nSobald Ihr nahe genug seid, wird man Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es einem meiner fähigen Assistenten zu. Wir brauchen drei Fässchen. Erledigt Eure Sache gut, dann haben wir eventuell weitere Aufträge für Euch.", progress = nil, completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist, die Dunkeleisenzwerge immer wieder angreifen und unser Lieferant irgendwo feststeckt, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nHier sind die Marken, die wir Euch versprochen haben. Viel Spaß damit!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Widder absteigen\n\nIhr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][11413] = {title = "Sagte da jemand \"Souvenir\"?", objective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGelber Braufestkrug"}
MultiLanguageQuestData['de'][11414] = {title = "Verrat unter den Brüdern", objective = "Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren.", description = "Behüterin Mondblatt ist in meinen Träumen erschienen! Ein Freund von ihr, ist ein Freund von mir.\n\nBis zum letzten Vollmond war ich der Alphaworg meines Rudels, doch dann kam der weiße Worg Garwal aus dem Norden und mithilfe meiner einstigen Brüder stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas Unnatürliches an sich.\n\nUm mir zu helfen, musst du zuerst diejenigen töten, die mich verraten haben.\n\nBjomolf jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt. Und such' nach Varg: Er befindet sich im Südosten, in der Nähe des Westspeerturms.\n\nDein Aussehen wird sie nicht täuschen.", progress = nil, completion = "Der Geruch von Blut auf deiner Schnauze gefällt mir. Brüder sollten sich nicht gegenseitig bekämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11415] = {title = "Verrat unter den Brüdern", objective = "Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren.", description = "Weiser Nebelläufer ist in meinen Träumen erschienen! Ein Freund von ihm ist ein Freund von mir.\n\nBis zum letzten Vollmond war ich der Alphaworg meines Rudels, doch dann kam der weiße Worg Garwal aus dem Norden und mithilfe meiner einstigen Brüder stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas Unnatürliches an sich.\n\nUm mir zu helfen, musst du zuerst diejenigen töten, die mich verraten haben.\n\nBjomolf jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt. Und suche nach Varg: Er befindet sich im Südosten, in der Nähe des Westspeerturms.\n\nDein Aussehen wird sie nicht täuschen.", progress = "<Ein leises Knurren entweicht Ulfangs Kehle.>\n\nBjomolf und Varg sind nicht tot!", completion = "Der Geruch von Blut auf deiner Schnauze gefällt mir. Brüder sollten sich nicht gegenseitig bekämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11416] = {title = "Augen des Adlers", objective = "Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren.", description = "Garwal verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen oder riechen, außer er wünscht es. Eine Möglichkeit haben wir jedoch.\n\nMein Feind, der große Adler Klauenwürger, besitzt Augen, so sagt man, denen nichts entgeht. Nähmest du also seine Augen, würdest du Garwal sicherlich sehen können.\n\nKlauenwürgers Nest befindet sich am Ende des Wasserfalls, gleich südwestlich des Vrykuldorfs namens Skorn. Berührst du die Eier in seinem Nest, wird er vom Himmel kommen, um dich zu töten.\n\nHol' dir seine Augen.", progress = "Hast du die Augen des Adlers dabei?", completion = "&lt;Ulfang heult lauthals, als er von Eurem Sieg über seinen Feind, den großen Adler, erfährt.&gt;\n\nDass du ihn erlegt hast, macht dir alle Ehre. Ich wünschte, es wäre mein Maul gewesen, dessen Biss sein Ende herbeiführte.\n\nDas Opfer, welches er für uns erbrachte, soll nicht vergebens gewesen sein. Hier, friss!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11417] = {title = "Augen des Adlers", objective = "Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren.", description = "Garwal verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen, außer er wünscht es. Eine Möglichkeit haben wir jedoch.\n\nMein Feind, der große Adler Klauenwürger, besitzt Augen, so sagt man, denen nichts entgeht. Nähmest du also seine Augen, würdest du Garwal sicherlich sehen können.\n\nKlauenwürgers Nest befindet sich am Ende des Wasserfalls, gleich südwestlich des Vrykuldorfs namens Skorn. Berührst du die Eier in seinem Nest, wird er vom Himmel kommen, um dich zu töten.\n\nHol' dir seine Augen.", progress = "Hast du die Augen des Adlers dabei?", completion = "&lt;Ulfang heult lauthals, als er von Eurem Sieg über seinen Feind, den großen Adler, erfährt.&gt;\n\nDass du ihn erlegt hast, macht dir alle Ehre. Ich wünschte, es wäre mein Maul gewesen, dessen Biss sein Ende herbeiführte.\n\nDas Opfer, welches er für uns erbrachte, soll nicht vergebens gewesen sein. Hier, friss!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11418] = {title = "Wir nennen ihn Stahlfeder", objective = "Spürt Stahlfeder auf, der über Fort Wildervar kreist, und benutzt den gefiederten Glücksbringer, um hinter sein Geheimnis zu kommen. Berichtet Gil Grisert anschließend von dem, was Ihr herausgefunden habt.", description = "Wir konnten beobachten, wie ein mutiger Hippogryph über dem Fort kreist, schließlich im Sturzflug nach unten schnellt und Beute macht. Jethan dort drüben hat schon ein paar Schüsse auf ihn abgegeben, aber seine Pfeile prallten einfach ab!\n\nWir haben uns daran gewöhnt, diese bemerkenswerte Kreatur Stahlfeder zu nennen, doch weshalb es die Gegend um Fort Wildervar herum bevorzugt, wissen wir nicht. Die meisten Hippogryphen nehmen sich vor Menschen in Acht.\n\nForscher Aderan hat uns dabei geholfen, aus einer der Federn der Kreatur einen Glücksbringer herzustellen. Er behauptet, dass es dem Benutzer erlaubt, die Welt durch Stahlfeders Augen zu sehen.", progress = "Hat Aderans Glücksbringer funktioniert?", completion = "Ihr habt ein Nest mit Jungen gesehen? Hmm, also ist unser \"er\" eigentlich eine \"sie\", oder?\n\nIch denke, dass sich damit die Sache erledigt hat. Ich würde es auch nicht wollen, dass man ein Nest voller Jungen nur deswegen an einen anderen Ort bringt, weil es einen neuen Nachbarn gibt.\n\n&lt;Gil wirft Fallensteller Jethan einen spöttischen Blick zu.&gt;\n\nBin mir sicher, dass wir gut miteinander auskämen, wenn der gute Jethan nicht versuchen würde, aus ihr eine Trophäe zu machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11419] = {title = "Braufestwidder", objective = "Bringt den Handstempel \"Ehrenbrauer\" zu Driz Purzelfix in der Nähe des Eingangs zum Braufestplatz in Durotar.", description = "Wenn Ihr Driz Purzelfix, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11420] = {title = "Der Weg zur Vergeltung", objective = "Wachoffizier Zorek bei Valgarde am Heulenden Fjord möchte, dass Ihr die Harpunenbetriebsanleitung zurückholt.", description = "Vor zwei Wochen hat unser Chefingenieur eine Harpunenkanone der Vrykul in die Finger bekommen - dieselbe Art Kanone, die diese Vrykul benutzen, um unsere Schiffe auszuschalten. Durch die Studien dieser Waffe konnte er eine umfangreiche Betriebsanleitung zusammenstellen.\n\nLeider wurde er gefangen und in das Dorf Wyrmskol nördlich von hier verschleppt. Wir haben ihn dann letztendlich gefunden, doch da lag er im Sterben und hatte die Anleitung nicht mehr bei sich. Seine letzten Worte deuten darauf hin, dass die Anleitung in den Katakomben von Utgarde verloren gegangen ist - jenem Ort, der sich im nordwestlichen Teil von Wyrmskol befindet. Besorgt mir diese Anleitung!", progress = "Habt Ihr die Anleitung gefunden?", completion = "&lt;Zorek blättert die Anleitung durch.&gt;\n\nDer Anleitung nach haben die Vrykul ein Spezialwerkzeug, welches ihnen erlaubt, die Harpunen mit tödlicher Präzision zu bedienen. Es sieht ein bisschen wie das Rad eines unserer Schiffe aus. Zudem ist es tragbar und scheint wie ein Schlüssel in die Harpunen zu passen. Wir müssen eines davon in die Finger bekommen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11421] = {title = "Jetzt drehen wir mal richtig auf...", objective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr das Langhaus der Drachenschinder, das Dockhaus der Drachenschinder, das Lager der Drachenschinder und 8 Verteidiger der Drachenschinder vernichtet.\n\nBringt den Harpunenkontrollmechanismus zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", description = "Wir müssen zuschlagen, solange die Verwirrung unter den Truppen der Vrykul anhält! Nehmt den Harpunenkontrollmeachanismus an Euch und sucht entlang der Klippen das am nördlichsten gelegene Harpunengebäude des Dorfes.\n\nNehmt eine der vrykulschen Harpunenkanonen auf dem Dach des Gebäudes in Euren Besitz, sobald Ihr dort seid, und macht Wyrmskol die Hölle heiß! Zerstört das Lang- und Dockhaus, das Lager und sämtliche Verteidiger, die die Vrykul auf Euch hetzen könnten!\n\nSolltet Ihr dies vollbringen, wird die Dolchbucht ein viel sicherer Hafen sein!", progress = "Steht Wyrmskol in Flammen?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Ihr habt einen guten Teil dieser Drachenreiter ausgeschaltet und ihre Führung richtig sauer gemacht.\n\nSeid Ihr bereit, nach Valgarde zurückzukehren und Zorek die guten Neuigkeiten zu überbringen? Falls dem so ist, dann hätte ich da eine verrückte Idee!", rewards = "Bereifte StulpenAzurkettenhalsbergeSchultern mit WidderhornintarsienAuf Euch wartet eine dieser Belohnungen:\n\nRunenbeschriebener Muschelschalenhalsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11422] = {title = "Dreizack des Sohnes", objective = "Alte Eisflosse möchte, dass Ihr Rottkiems Dreizack zurückholt. Er wohnt auf der kleinen Insel an der Küste des Frostmaares.", description = "<Die Kratzer, die er in den Felsen ritzt, stellen mehrere Symbole dar: einen Dreizack, einen Mur'ghul, die Sonne, ein Schiffswrack und ein grobes Strichmännchen, welches Euch darstellt.>\n\n<Es braucht einige Zeit dahinterzukommen, was Euch der Murloc mitteilen möchte. Offensichtlich will er, dass Ihr ihm einen Dreizack von der Küste des Frostmaares besorgt, doch was das Bild der Sonne bedeuten soll, ist Euch ein Rätsel - zumindest bis Ihr erkennt, dass er damit seinen Sohn meint.>\n\n<Sein Sohn wurde in einen Mur'ghul verwandelt! Er möchte, dass Ihr nach Süden geht, in der Nähe des Schiffswracks nach ihm sucht und seinen Dreizack zurückbringt.>", progress = "<Alte Eisflosse beäugt Euch mit einem seiner toten Augen und sucht nach Zeichen des Dreizacks seines Sohnes.>", completion = "&lt;Als er seine Hand ausstreckt, um den Dreizack von Euch in Empfang zu nehmen, zittert diese ein wenig. Könnte es sein, dass der gealterte Murloc trauert?&gt;\n\n&lt;Was sammelt sich da für eine Flüssigkeit in seinem Auge?&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11423] = {title = "Das Vermächtnis des Feindes", objective = "Reist nach Niffelvar nördlich des Geisterklingenpostens und sucht die Sage des Winterfluchs, die Sage der Val'kyr und die Sage der Zwillinge.", description = "Während unsere Armeen durch Nordend marschieren, werden unsere Feinde nicht nur Niederlage um Niederlage erleiden müssen. Ihre Häuser werden in Flammen stehen, unsere Seuchen werden ihre Leichen zerfressen, jede Spur ihrer Existenz wird vom Erdboden getilgt sein.\n\nFür jemanden wie mich, den es nach Wissen dürstet, ist das beunruhigend. Niffelvar, die Stadt im Osten, wird bald von unseren Streitkräften aus dem Hafen der Vergeltung ausgelöscht werden. Helgus, der Barde der Vrykul, lebte dort und schrieb drei Sagen: die Sage der Zwillinge, die Sage des Winterfluchs und die Sage der Val'kyr. Besorgt diese, bevor Niffelvar dem Erdboden gleichgemacht wird.", progress = "Die Schriftrollen, <Name>? Habt Ihr sie?", completion = "Dies ist von enormem Wert, &lt;Name&gt;. Ich muss meine Anstrengungen erneut aufnehmen, Texte der Vrykul zu übersetzen.\n\nVersteht mich nicht falsch. Unsere Feinde müssen vernichtet werden... nicht so ihr uraltes Wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11424] = {title = "Schildhügel", objective = "\"Eisensäge\" Jenny möchte, dass Ihr 5 alte Knochen der Vrykul von den wiederauferstandenen Vrykul beim Schildhügel südlich von Neu-Agamand besorgt.", description = "Meine Arbeit sollte in Kriegszeiten eigentlich ziemlich leicht sein - es müsste überall brauchbare Körperteile geben.\n\nDoch so einfach ist es nicht. Wenn diese Eierköpfe alles Mögliche an tödlichen Plagen in den feindlichen Dörfern freisetzen, werden dabei die meisten Materialien verunreinigt.\n\nEs gibt jedoch einen Ort, an dem sich brauchbare Exemplare finden lassen. Der Schildhügel südlich von hier ist ein alter Friedhof der Vrykul. Dort laufen die Toten noch herum, sind aber frei von irgendwelchen Seuchen - sowohl von unseren als auch denen des Lichkönigs. Besorgt mir ein paar Knochen und ich werd' Euch gut bezahlen.", progress = "Habt Ihr nun meine Knochen?", completion = "Hmpf... die werden erstmal reichen. Irgendwas scheint mit ihnen nicht zu stimmen.\n\nIch sag's Euch, ich hantiere schon seit Jahren mit Körperteilen herum, aber ich hatte noch nie so'n komisches Gefühl im Bauch. Wie dem auch sei, Geschäft ist Geschäft. Hier ist Eure Bezahlung.", rewards = "FlammenbinderhandlappenFroststeinverzierter TaillenschutzArmschienen des reinen SchlagsSmaragdschuppige SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11425] = {title = "Test Quest - Craig", objective = "Bla, bla.", description = "Auf zur Quest!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11426] = {title = "Den Mechanismus ausfindig machen", objective = "Wachoffizier Zorek bei Valgarde am Heulenden Fjord möchte, dass Ihr ihm einen Harpunenkontrollmechanismus bringt.", description = "Macht Euch keine Sorgen, <Name>; all dies wird zu etwas Großem führen! Etwas RIESIGEM! Ihr müsst mir nur erst einmal vertrauen und tun, wie ich es Euch sage.\n\nFür die nächste Stufe des Planes, müssen wir einen in der Anleitung erwähnten Mechanismus besorgen. Ich habe den starken Verdacht, dass Ihr einen bei einem dieser Vrykuls finden werdet, welche die Harpunenkanonen in Wyrmskol bedienen. Ihr werdet sie auf der Ostseite des Dorfes an den Docks bei den Langhäusern finden.", progress = "Habt Ihr den Mechanismus gefunden?", completion = "Überragend! Diese zu groß geratenen Affen werden bald merken, was es heißt, sich mit der Allianz anzulegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11427] = {title = "Trefft Leutnant Eishammer", objective = "Wachoffizier Zorek möchte, dass Ihr den Harpunenkontrollmechanismus zu Leutnant Eishammer außerhalb von Niffelvar bringt.", description = "Seht Ihr diese Gebäude der Vrykul auf den Klippen im Nordosten? Die Vrykul nennen diesen Ort Niffelvar. Von dort aus kommen die meisten Ihrer Harpunenangriffe auf unsere Fregatten.\n\nDoch wisst Ihr was? Es ist Zeit es ihnen heimzuzahlen, <Name>. Nehmt diesen Harpunenkontrollmechanismus und trefft Euch mit Leutnant Eishammer, der sich in einem Gebäude der Vrykul im Nordwesten von Niffelvar versteckt hält.\n\nWenn Ihr bereit seid, könnt Ihr Euch auf einen meiner Greifen schwingen und Ihr werdet schnurstracks zu ihm gebracht!", progress = "Was ist das denn? Sehe ich aus wie ein Kindermädchen?", completion = "&lt;Leutnant Eishammer nimmt Euch den Harpunenkontrollmechanismus ab.&gt;\n\nAh, Ihr bringt Geschenke!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11428] = {title = "Hüter Welkblatt", objective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr Hüter Welkblatt tötet.", description = "Eure Freundschaft und Unterstützung haben uns schon viel geholfen, <Name>. Es gibt jedoch noch eine Sache, um die ich Euch bitten muss.\n\nIhr habt sie gesehen, die Verderbnis, welcher die Siechende Lichtung und die dort lebenden Biester anheim gefallen sind. Die schwarzbeseelten Bewahrer werden diese Monstrositäten weiterhin aus den Wassern und der Erde unserer Lichtung auferstehen lassen, wenn wir nichts gegen sie unternehmen.\n\nDer mächtigste unter den schwarz beseelten Bewahrern wird Hüter Welkblatt genannt. Tötet ihn, <Name>, und Ihr werdet damit den Weg zur Errettung der Lichtung ebnen, so wie Ihr einst den Weg zur Errettung meiner Schwestern ebnetet.", progress = nil, completion = "Als ich hörte, dass die Bewahrer sich gegen uns gewendet hatten, brach mir das Herz. Einst betrachteten wir sie als unsere Brüder und engsten Freunde.\n\nMeine Trauer gilt unseren verlorenen Brüdern und Schwestern, doch ohne Eure Hilfe gäbe es für uns keine Hoffnung auf die Zukunft. Ihr werdet hier unter uns immer willkommen sein, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11429] = {title = "Aufstellen und abrocken!", objective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr das Banner der Allianz in Quälheim aufstellt und dieses gegen Angreifer verteidigt.\n\nKehrt gemeinsam mit dem Banner zu Leutnant Eishammer zurück, falls Ihr überleben solltet.", description = "Ich habe nicht die Absicht, das Schicksal dieser Mission in die Hände irgendeines Möchtegerns zu legen, der noch nicht auf die Probe gestellt wurde.\n\nWenn Ihr mir also beweisen wollt, dass Ihr das Zeug dazu habt, diese Mission auszuführen, werdet Ihr das machen müssen, was ich Euch sage.\n\nNehmt diese Schlachtstandarte und macht Euch auf den Weg nach Quälheim, gleich nördlich von hier. Begebt Euch zur Ortsmitte und stellt unsere Flagge auf, sobald Ihr dort angelangt seid. Wehrt sämtliche Vrykuldrecksäcke, die versuchen sollten, unsere geliebte Flagge zu beseitigen, ab und kehrt zu mir zurück, sobald Ihr die Vorherrschaft der Allianz gesichert habt.", progress = "Noch immer am Leben, wie ich sehe. Offensichtlich strengt Ihr Euch nicht richtig an.", completion = "Für die Allianz! Ihr beweist Stärke, &lt;Name&gt; - genug, um einigen Vrykul in Niffelvar die Schädel einzuschlagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11430] = {title = "Harpunenmeister Yavus", objective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr Harpunenmeister Yavus in Niffelvar tötet.", description = "Das war eine ziemlich eindrucksvolle Vorstellung, die Ihr da geliefert habt, <Name>. Doch bevor Ihr Euch selbst auf die Schulter klopft: In Niffelvar gibt es noch Arbeit zu erledigen.\n\nWir haben den Vrykul, der für die meisten Harpunenangriffe auf unsere Fregatten verantwortlich ist, ausfindig gemacht - nennt sich Yavus. Ihr findet ihn in der Hauptharpunenanlage an den Klippen von Niffelvar, südlich von hier.\n\nSpürt ihn auf und richtet ihn für seine Verbrechen gegen die Allianz!\n\nMacht mich stolz, <Name>!", progress = nil, completion = "Sie werden einige Zeit brauchen, um Yavus zu ersetzen. Jetzt ist der perfekte Zeitpunkt, um Zoreks Plan in die Tat umzusetzen! Während sie sich eiligst darum kümmern, Niffelvar wieder unter ihre Kontrolle zu bringen, werdet Ihr ihre eigenen Harpunenkanonen in Besitz nehmen und gegen sie verwenden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11431] = {title = "Fangt die wilden Wolpertinger!", objective = "Der \"Zwerg\" Glodrak Jägerspatz möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr eine Synthebräubrille tragen müsst, um die Biester sehen zu können.", description = "Hey, Ihr da. Ich bin ein verrückter Zwerg! Wir Zwerge glauben, dass man unsichtbare Kreaturen sehen kann, wenn man nur mit ausreichend Gebräu versorgt ist. Wahrscheinlich wandern einige sogar gerade jetzt auf dem Braufestplatz umher! Ihr könnt sie aber nur sehen, wenn Ihr eine Synthebräubrille tragt.\n\nVielleicht gäbe es auch einen anderen Weg, aber er ist mir nicht bekannt.\n\nAlso, bringt mir mithilfe dieses Netzes, das ich von einem wirklich betrunkenen Zwerg habe, fünf Wolpertinger.\n\nWenn Ihr sie nicht sehen könnt, sagt es mir und ich gebe Euch eine Synthebräubrille.", progress = "Habt Ihr etwas für mich oder sucht Ihr nur wieder nach einem Grund, um Euch zu betrinken?", completion = "Was! Es gibt sie wirklich? Jetzt tut es mir richtig leid, dass ich diesem Zwerg gegen das Knie getreten habe...\n\nIch brauche eine Minute... und einen Schluck...\n\n&lt;Er trinkt aus seinem Krug.&gt;\n\nIch denke, ich überlasse Euch einen... als Beweis dafür, dass betrunkene Zwerge - gibt es überhaupt andere? - wirklich die Wahrheit sagen.", rewards = "Ihr bekommt:\n\nWolpertingerhumpen"}
MultiLanguageQuestData['de'][11432] = {title = "Schlafende Riesen", objective = "Magierleutnant Malister hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich in Westwacht.", description = "Ich habe zufällig mit anhören können, über was Ihr mit Vater Levariol gesprochen habt. Erlaubt mir, Euch darauf hinzuweisen, dass der Auftrag, den er Euch erteilt hat, nicht weit genug geht.\n\nIhr müsst Euch auch um die Vrykul kümmern, die in den Hallen des Erwachens tief im Fels unter Gjalerbron im Schlaf liegen!\n\nIch hege keine Zweifel daran, dass die Rituale, mit deren Hilfe man sie erweckt, der Schlüssel zu ihrem Untergang sind. Die Nekrolords verfügen höchstwahrscheinlich über irgendeine Vorrichtung, mit der Ihr die Vrykul vorzeitig aus ihrem Schlaf reißen könnt.\n\nSolch eine Behelligung wird sich für die Vrykul als fatal erweisen.", progress = nil, completion = "Ihr habt getan, was getan werden musste. Es mag vielleicht sein, dass gewisse Leute das Töten Wehrloser als unehrenhafte Tat betrachten, doch in diesem Fall wäre es töricht gewesen, nicht so zu handeln.\n\nUnd wir hätten sie doch nicht einfach so dort herumstehen lassen können, nur damit sie später durch ein Ritual erweckt werden, oder?\n\nEs war eine mutige Sache, die Ihr dort unten in den Katakomben für uns alle hier oben geleistet habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11433] = {title = "Schlafende Riesen", objective = "Ahota Weißfrost hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich im Lager der Winterhufe.", description = "Ich habe zufällig mit anhören können, über was Ihr mit Großmutter Ankha gesprochen habt. Bei allem Respekt, aber ich meine, dass der Auftrag, den sie Euch erteilt hat, nicht weit genug geht.\n\nIhr müsst Euch auch um die Vrykul kümmern, die in den Hallen des Erwachens tief im Fels unter Gjalerbron im Schlaf liegen!\n\nIch hege keine Zweifel daran, dass die Rituale, mit deren Hilfe man sie erweckt, der Schlüssel zu ihrem Untergang sind. Die Nekrolords verfügen höchstwahrscheinlich über irgendeine Vorrichtung, mit der Ihr die Vrykul vorzeitig aus ihrem Schlaf reißen könnt.\n\nSolch eine Behelligung wird sich für die Vrykul als fatal erweisen.", progress = nil, completion = "Ihr habt getan, was getan werden musste. Es mag vielleicht sein, dass die Unklugen das Töten Hilfloser während sie aufwachen als unehrenhafte Tat betrachten, doch in diesem Fall wäre es töricht gewesen, nicht so zu handeln.\n\nUnd wir hätten sie doch nicht einfach so dort herumstehen lassen können, nur damit sie später durch ein Ritual erweckt werden, oder?\n\nEs war eine mutige Sache, die Ihr dort unten in den Katakomben für uns alle hier oben geleistet habt, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11434] = {title = "Vergessene Schätze", objective = "Der hübsche Terry im Halunkeneck möchte, dass Ihr ihm 1 Amanivase und 1 Adlerfigurine aus dem Schiffswrack gen Süden holt.", description = "Ich hab' ein Vermögen gemacht, weil ich mich auf Schätze spezialisiert hab', auf die gewöhnliche Piraten keinen Wert legen: Kunst, Antiquitäten, Sammlerstücke.\n\nSüdlich von hier ist die Stelle, an der die Flotte vom schwarzen Konrad vor Jahren einmal sank. Doch Taucher haben alles an Gold und Juwelen weggeschafft - nichts ist übrig geblieben, bis auf zwei uralte Artefakte. Eins davon ist eine Amanivase in Museumsqualität, das andere ist eine Adlerfigurine.\n\nGeht, beschafft mir die Dinger und ich werd' ein gutes Wörtchen für Euch bei den anderen Piraten einlegen. Ich würd' sogar was beisteuern, damit sich Euer Unterwasserabenteuer etwas leichter bewältigen lässt.", progress = "Habt Ihr meine Relikte beschaffen können, <Name>? Mit Schönheit alleine kommt man im Leben auch nicht über die Runden... selbst ich nicht!", completion = "Gemeinsam werden wir's zu was bringen, &lt;Name&gt;. Mit meinem guten Aussehen und Eurem... unerschütterlichen Optimismus werden wir sicherlich ein dickes Geschäft machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11435] = {title = "Gathered Pumpkins NYI", objective = "Bringt das Bündel Kürbislaternen zur kostümierten Waisenmatrone.", description = "Hi, <Name>! Danke, dass Ihr den Reiter vertrieben habt! Jetzt, da er weg ist, hat uns die Matrone erlaubt, durchs Dorf zu ziehen!\n\nIch habe ein paar Kürbisse gefunden, die der Reiter fallen ließ. Die sehen unheimlich aus... würdet Ihr sie nehmen und der Matrone zeigen?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewichtige Kürbislaterne"}
MultiLanguageQuestData['de'][11436] = {title = "Gehen wir Harpunenreiten!", objective = "Katapultiert Euch mithilfe der großen Harpunenkanone der Vrykul nach Valgarde. Erstattet Wachoffizier Zorek Bericht, falls Ihr Erfolg haben solltet.", description = "An den steilen Klippen des Heulenden Fjords vorbeizunavigieren, kann ein nervenaufreibendes Unterfangen sein! Ich hab' jedoch herausgefunden, wie man mithilfe von Vrykultechnologie und zwergischer Raffinesse etwas herstellen kann, das die Sache einfacher gestalten wird. Es hat nur ein paar Einstellungen und Feinabstimmungen gebraucht und Eishammers Harpunensteuerung war fertig! Natürlich wurde sie noch nicht getestet, aber deswegen seid Ihr ja hier!\n\nNehmt die Steuerung, geht zur großen Kanone in Niffelvar und katapultiert Euch mit ihrer Hilfe nach Valgarde. Erstattet Zorek Bericht, falls Ihr Erfolg haben solltet. Oh ja, da fällt mir ein: Ihr könnt die Steuerung behalten.", progress = "<Zorek blickt Euch an und hebt eine Braue.>", completion = "Ihr seid verrückt, &lt;Name&gt;! Jetzt mal ehrlich: Welcher Trottel würde eine Harpunenkanone als Beförderungsmittel verwenden?\n\nIch denke jedoch, dass man ein wenig verrückt sein muss, um das abzuziehen, was Ihr dort oben an den Klippen abgezogen habt! Fantastische Arbeit! Wir haben Nachricht erhalten, dass Ingvar, der Anführer der Drachenschinder, vor Wut nur so tobt! Vielleicht werdet Ihr ihn eines Tages in den Boden stampfen können - im Namen unserer geliebten Allianz.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11439] = {title = "Übung bei der Brandwache", objective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", description = "Jetzt, da der kopflose Reiter in der Gegend ist, sind die mutigen Zwerge von Kharanos jederzeit für einen Einsatz der Brandwache bereit. Wollt auch Ihr helfen?\n\nDie Gebirgsjäger haben südlich von hier ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, <Name>. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", progress = nil, completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11440] = {title = "Übung bei der Brandwache", objective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind die Friedensbewahrer jederzeit bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nDie Friedensbewahrer haben westlich von hier, in Richtung der Exodar, ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, <Name>. Besucht uns bitte wieder, wenn Ihr genug geübt habt!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11441] = {title = "Braufest!", objective = "Sprecht mit dem Organisator des Braufests.", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Eisenschmiede, um ein kostenloses Bier zu erhalten.", progress = nil, completion = "Ho ho! Seid Ihr wegen des Freibiers hier?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKristallklares GerstenbräuDonner 45Gordokgrog\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11442] = {title = "Willkommen auf dem Braufest!", objective = "[PH] Speak to the Brewfest Organizer and receive a free beer.", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "Ho ho! Seid Ihr wegen des Freibiers hier?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKristallklares GerstenbräuDonner 45Gordokgrog\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11443] = {title = "Tauchgang in der Dolchbucht", objective = "Harold Lagras auf dem Grund der Dolchbucht möchte, dass Ihr ihm 10 Vorratskisten von Valgarde bringt.", description = "Hä... ähm... Was ist los? Was macht Ihr dort unten?\n\nIch? Oh... nun ja, seht Ihr... ich bin... ähm... Ich versuche hier ein wenig aufzuräumen! Befehl von Keller höchstpersönlich! \"Harry,\" hat er zu mir gesagt, \"ich will, dass du dir 'ne Tauchglocke aufsetzt und in den Schiffswracks in der Dolchbucht nach UNSEREM Zeugs suchst...\"\n\nHe, wenn Ihr schon mal hier unten seid, vielleicht könntet Ihr mir dann helfen. In der ganzen Bucht liegen allerhand Schmuckstü... ähh, ich meine Vorratskisten herum. Geht und bringt mir alles, was Ihr finden könnt. Setzt Euch den Taucherhelm auf, damit Euch die Luft nicht ausgeht.", progress = "Habt Ihr die Vorratskisten gefunden?", completion = "Super! Ihr seid mit Sicherheit sehr effizient. So ist's... Ach was, gebt mir einfach die Kisten. Ich muss sie in meinem Büchlein verzeichnen, Inventur machen und ein paar andere Sachen, die Ihr nicht versteht und für die Ihr nicht ausgebildet seid, an mich nehmen. Macht Euch keine Sorgen, ich werde Keller auf jeden Fall sagen, was für tolle Arbeit Ihr hier unten geleistet habt! - genau. M-hm, Ihr könnt jetzt gehen. Husch, husch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11446] = {title = "Braufest!", objective = "Sprecht mit dem Organisator des Braufests.", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Orgrimmar, um ein kostenloses Bier zu erhalten.", progress = nil, completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKleiner SchwipsDschungeltropfenGordokgrog\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11447] = {title = "Willkommen auf dem Braufest!", objective = "[PH] Speak to the Brewfest Organizer and receive a free beer.", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKleiner SchwipsDschungeltropfenGordokgrog\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11448] = {title = "Der Außenposten der Forscherliga", objective = "Liefert McSorfs Bündel bei Stanwad im Außenposten der Forscherliga im Heulenden Fjord ab.", description = "Das ist alles ein Haufen kryptischer Unsinn! Trotz dieser Glyphe werde ich aus den Tafeln einfach nicht schlau. Zugegeben, Kryptografie ist nicht eine meiner Stärken.\n\nIhr werdet die Glyphe und Tafeln zu unserem Kryptografen Stanwad bringen müssen. Unglücklicherweise habe ich seit zwei Wochen nichts mehr von Stanwad gehört. Er nahm ein Team aus zwanzig Wissenschaftlern mit zur Ausgrabungsstätte an den südöstlichen Klippen des Fjords und seitdem hat man nichts mehr von ihm gehört. Das Beste, was ich machen kann, ist es, McGoyver da drüben zu sagen, dass er Euch auf seiner Flugmaschine mitnehmen soll.", progress = "<Stanwad gibt seiner Unzufriedenheit mit einem Brummen Ausdruck.>", completion = "&lt;Stanwad nimmt Euch das Bündel ab und fängt an, die Daten zu sortieren.&gt;\n\nUnglaublich. Wie viele Leute meint Ihr, haben für diese Informationen ihr Leben gelassen?\n\n&lt;Stanwad schüttelt seinen Kopf.&gt;\n\nIhr werdet Euch wahrscheinlich darüber freuen, dass das, was McSorf und sein Trupp an ausgemachten Idioten herausgefunden haben, ein uraltes Rezept für einen Tundraeintopf ist. Hat er nicht bemerkt, dass die Symbole gewöhnliche Gemüsesorten darstellen und das Piktogramm einen Humanoiden zeigt, der besagtes Gemüse mampft? Man braucht keine verdammte Glyphe, um diesen Code zu knacken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11449] = {title = "Feuerübung", objective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Brill.", description = "Die Todespirscher haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Weitere Schäden an den Gebäuden von Brill können wir uns nicht leisten - also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nGeht Richtung Westen am Friedhof vorbei und folgt dem Straßenverlauf, bis Ihr das Übungslager erreicht.", progress = "Habt Ihr ein paar Feuer gelöscht, <Name>? Das Übungslager liegt westlich von Brill.", completion = "Gut gemacht, &lt;Name&gt;! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11450] = {title = "Feuerübung", objective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone beim Falkenplatz.", description = "Die Wachen haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Wir können nicht zulassen, dass der kopflose Reiter alles zunichtemacht, was wir in harter Arbeit wieder aufgebaut haben – also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nVerlasst die Stadt durch das südliche Tor in Richtung der Kreuzung. Dort werdet Ihr das Übungslager finden.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", rewards = "Ihr bekommt:\n\nSüßes SauresKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][11451] = {title = "Alicias Gedicht", objective = "Man hat Euch gebeten, Alicias Gedicht zu Caylee Dak in Shattrath in der Scherbenwelt zu bringen.", description = "Hi! Ich habe für meine Freundin Caylee ein Gedicht verfasst. Sie verbringt Ihre Zeit gerne bei den Aldor in Shattrath. Ihr wisst schon, in der Scherbenwelt!\n\nWärt Ihr so freundlich und würdet ihr das Gedicht bringen? Meine Mutter sagt, ich sei noch zu jung, um selbst nach Shattrath zu reisen!", progress = "Oh, ein Gedicht?", completion = "Was für ein anrührendes Gedicht. Habt vielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11452] = {title = "Der schlummernde König", objective = "Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt nach Westwacht zurück, falls Euch dies gelingen sollte, und setzt Hauptmann Adams über Euren Erfolg in Kenntnis.", description = "Ein Bündel Pergament fällt aus der regungslosen Hand des Oberanführers. Auf ihm könnt Ihr die Umrisse der Rituale erkennen, die in den Katakomben unter Euch vonstattengehen.\n\nEs scheint jedoch, als hätte die Königin der Vrykul Angerboda Schwierigkeiten, König Ymiron zu erwecken. Das Ritual findet auf der Terrasse des Winters, einer großen Kammer am nördlichen Ende von Gjalerbron, statt.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht aufhalten, bevor es zu spät ist.", progress = nil, completion = "Ich bin mir nicht sicher, aber der eine Teil hört sich gar nicht gut an! Dass sich der Lichkönig mit Ymiron davonmacht, kann nur Schwierigkeiten bedeuten. Bedauerlich nur, dass Ihr nicht imstande wart, ihn gemeinsam mit seiner Königin zu töten.\n\nNichtsdestotrotz, Ihr habt ihnen einen großen Strich durch die Rechnung gemacht und uns die nötige Zeit verschafft.\n\nUnd wer weiß, so viel wie Ihr herumkommt, ist es gut möglich, dass Euch König Ymiron noch einmal über den Weg laufen wird. Ich bin mir sicher, dass es ihm bei Eurer nächsten Begegnung nicht so gut ergehen wird.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11453] = {title = "Der schlummernde König", objective = "Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt zum Lager der Winterhufe zurück, falls Euch dies gelingen sollte, und berichtet Häuptling Aschtotem über Euren Erfolg.", description = "Ein Bündel Pergament fällt aus der regungslosen Hand des Oberanführers. Auf ihm könnt Ihr die Umrisse der Rituale erkennen, die in den Katakomben unter Euch vonstattengehen.\n\nEs scheint jedoch, als hätte die Königin der Vrykul Angerboda Schwierigkeiten, König Ymiron zu erwecken. Das Ritual findet auf der Terrasse des Winters, einer großen Kammer am nördlichen Ende von Gjalerbron, statt.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht aufhalten, bevor es zu spät ist.", progress = nil, completion = "Ich bin mir nicht sicher, aber der eine Teil hört sich gar nicht gut an! Dass sich der Lichkönig mit Ymiron davonmacht, kann nur Schwierigkeiten bedeuten. Bedauerlich nur, dass Ihr nicht imstande wart, ihn gemeinsam mit seiner Königin zu töten.\n\nNichtsdestotrotz, Ihr habt ihnen einen großen Strich durch die Rechnung gemacht und uns die nötige Zeit verschafft.\n\nUnd wer weiß, so viel wie Ihr herumkommt, ist es gut möglich, dass Euch König Ymiron noch einmal über den Weg laufen wird. Ich bin mir sicher, dass es ihm bei Eurer nächsten Begegnung nicht so gut ergehen wird.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11454] = {title = "Findet die Saboteure", objective = "Sucht nach Coren Düsterbräu im Grimmigen Säufer in den Schwarzfelstiefen.Die Angreifer der Dunkeleisenzwerge scheinen diesen Papierfetzen versehentlich zurückgelassen zu haben.\n\nObwohl die Pläne in einem verfremdeten zwergischen Dialekt verfasst worden sind, ist die Unterschrift \"Coren Düsterbräu\" eindeutig genug, genauso wie die Erwähnung der Taverne 'Zum Grimmigen Säufer', tief in den Schwarzfelstiefen. Ihr solltet den Überfällen ein Ende bereiten und den Organisator der Überfälle aufsuchen.Ihr bekommt:\n\n", description = "Die Angreifer der Dunkeleisenzwerge scheinen diesen Papierfetzen versehentlich zurückgelassen zu haben.\n\nObwohl die Pläne in einem verfremdeten zwergischen Dialekt verfasst worden sind, ist die Unterschrift \"Coren Düsterbräu\" eindeutig genug, genauso wie die Erwähnung der Taverne 'Zum Grimmigen Säufer', tief in den Schwarzfelstiefen. Ihr solltet den Überfällen ein Ende bereiten und den Organisator der Überfälle aufsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkeleisenbierbecher"}
MultiLanguageQuestData['de'][11455] = {title = "Der Duft des Goldes", objective = "Der hübsche Terry im Halunkeneck im Heulenden Fjord möchte, dass Ihr 4 Einheiten Bärenmoschus von den tollwütigen Braunbären in der Gegend besorgt.", description = "Wir Piraten sind zwar für allerhand Dinge bekannt, doch Hygiene gehört nicht dazu. Auf den meisten Piratenschiffen befinden sich fünf oder sechs Mal so viele Ratten wie Leute.\n\nFührt man sich das vor Augen, ist es kein Wunder, dass gleich nachdem wir hierher gezogen sind, die Bären auf dieser Insel an Tollwut erkrankten. Lange Rede, kurzer Sinn: Der Boss will sie alle tot sehen.\n\nZufälligerweise hab' ich ein Rezept für ein Bärenmoschusparfüm, das unter Sturmwinds Edelleuten beliebt ist. Wir töten die Bären und verkaufen den Moschus: Das ist DIE Geschäftsmöglichkeit für uns. Was meint Ihr dazu?", progress = "Habt Ihr mir den Bärenmoschus gebracht, Kumpel?", completion = "Ausgezeichnete Arbeit! Es mag vielleicht nicht ganz so waghalsig sein wie das Beutemachen auf hoher See, doch ich soll verdammt sein, mir diese Gelegenheit entgehen zu lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11456] = {title = "Den Überlebenden zu essen geben", objective = "Urahn Atuik in Kamagua im Heulenden Fjord möchte, dass Ihr zur Insel der Speere geht und ihm 6 Stück Fleisch eines Inselschaufelhauers beschafft.", description = "In Sachen Nahrung sind wir Tuskarr größtenteils auf den Fischfang angewiesen. In Zeiten großer Not werden wir jedoch gelegentlich auch auf Landtiere Jagd machen.\n\nDas in der Nähe gelegene Iskaal wurde erst kürzlich von Piraten angegriffen und es kommen ständig neue Überlebende aus dem Dorf zu uns herüber.\n\nWir haben diese Woche keinen großen Fang gemacht - es gibt jedoch genug fleischbepackte Schaufelhauer auf der Insel.\n\nHelft meinem Volk bei der Jagd auf diese großen Biester und bringt uns deren Fleisch.", progress = "Habt Ihr das benötigte Fleisch bekommen können?", completion = "Ich danke Euch, &lt;Name&gt;. Mein Volk erlebt Zeiten großer Not.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11457] = {title = "Kamagua bewaffnen", objective = "Urahn Atuik möchte, dass Ihr ihm 3 Schimärenhörner beschafft.", description = "Issliruk, der Geist des Krieges, wird von meinem Volk als silberner Adler dargestellt. Unsere Geschichten über ihn berichten davon, wie er gegen einhundert Worgs kämpfte, um seine Jungen zu beschützen.\n\nAuch für uns ist nun die Zeit gekommen, dem Feind im Kampfe zu begegnen und unsere Brüder zu beschützen. Die Hörner der Frostflügelschimären, die sich in den verschneiten Teilen der Insel eingenistet haben, sind scharf und können mühelos zu Speerspitzen weiterverarbeitet werden. Bringt mir die besten Hörner, die Ihr finden könnt.", progress = "Schön, Euch wiederzusehen, <Volk>.", completion = "Ihr erweist Euch weiterhin als wertvoller Verbündeter, &lt;Name&gt;. Wir werden nicht vergessen, was Ihr für uns getan habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11458] = {title = "Rache für Iskaal", objective = "Urahn Atuik möchte, dass Ihr nach Iskaal geht und 8 Sklavenhändler des Nordmeeres niederstreckt. Macht von dem Horn von Kamagua Gebrauch, solltet Ihr Unterstützung benötigen.", description = "Das Totem von Issliruk ist bereit, <Name> - wofür ich Euch danken möchte. Fürs Erste müssen wir unsere friedlichen Sitten ablegen und einen Schlag gegen jene ausführen, die sich auf unser Land und unsere Sippe gestürzt haben.\n\nDie freibeuterischen Sklavenhändler, die für den Überfall auf Iskaal verantwortlich sind, haben ihren Verstand verloren und all ihre Gefangenen abgeschlachtet. Geht in Richtung Osten nach Iskaal und erledigt, was erledigt werden muss. Nehmt dieses Horn und ruft nach meinen Brüdern, solltet Ihr Unterstützung benötigen.", progress = nil, completion = "Ihr seid ein großartiger Verbündeter, &lt;Name&gt;. Mein Volk steht für immer in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11459] = {title = "Zeh'gehn sachd", objective = "Kehrt zum hübschen Terry zurück, um herauszufinden, was Zeh'gehn von Euch will.", description = "Na lucks mal so än, Mann. Bis' du schaäf drouf, unsr'oins unnä di Floss'n zu graifn un' de olle Mackreilä ans Däch zu spül'n, di moi Crew sai Gut begrapscht hät?\n\nDu wiäst mia ne Kröide aus'm Wassä zieh'n müssn, Kamerad. Jo, un' dänn wüäd mainerainer dia zaichn, wer de Radde is, Mann. Nei, nei, de Kröide wiäd's dia zaichn. Du wiäst's woul mit di eich'nen Glupschä säin müss'n.\n\nSchaff ouch mol'n richdich's Mässä rübbä, baim Klabaudamann. Nu lous, Freundschen.", progress = nil, completion = "Ihr habt kein Wort von dem verstanden, was Zeh'gehn gesagt hat? Tja, das war klar.\n\nDann lasst uns doch mal sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11460] = {title = "Vertrauen will verdient sein", objective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr nach einer Fjordlarve sucht und sie an einen der Falken im Käfig zu seinen Füßen verfüttert.", description = "Der erste und wichtigste Aspekt der Falknerei ist die Bindung zwischen <dem Falkner/der Falknerin> und <seinem/ihrem> Vogel. Doch Vertrauen will <vom Herren/von der Herrin> verdient werden!\n\n<Hidalgo deutet auf die Falken im Käfig zu seinen Füßen.>\n\nUm ihr Vertrauen zu gewinnen, werdet Ihr zuerst ihre Bäuche füllen müssen.\n\nAuf dem Speiseplan der Fjordfelsenfalken, wie man diese Vögel nennt, befinden sich hauptsächlich Larven. Diese Insekten nisten unter losen Steinen, die im gesamten Fjord verstreut liegen. Findet eine Larve, kehrt hierher zurück und verfüttert sie an die Falken im Käfig.", progress = "Das ist eine wichtige Übung, <Name>. Wenn Ihr ein Falkner werden wollt, müsst Ihr lernen, wie man einen Vogel ernährt.", completion = "Gut, &lt;Name&gt;. Wie ich sehe, seid Ihr schon im Begriff, Freunde zu werden - er hat Euch als Herr akzeptiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11461] = {title = "DEPRECATED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11464] = {title = "Spielschulden", objective = "Taruk im Halunkeneck möchte, dass Ihr die Schulden von \"Silbermond\" Harry eintreibt.", description = "Ich habe gehört, Ihr habt für Terry ein paar Sachen geregelt. Ich habe darauf gehofft, dass hier mal jemand Verlässliches auftauchen würde.\n\nWisst Ihr, Piraten lieben das Glücksspiel. Jedoch bezahlen sie nicht gern ihre Spielschulden.\n\nWenn Ihr daran interessiert seid, für mich ein paar Münzen einzukassieren, wär' ich gewillt, Euch einen Anteil abzugeben.\n\nArbeiten wir Euch mit etwas Einfachem ein. \"Silbermond\" Harry ist ein kleiner Exzentriker, bewahrt in seinem Zelt allerlei teuren Blutelfenschnickschnack auf - aber wenn ich ihn treffe, tut er immer so, als wäre er pleite. Holt mein Gold.", progress = "Ihr seid zurück. Habt Ihr, was mir gehört?", completion = "Eine gut gemachte Arbeit. Hier ist Euer Anteil, &lt;Name&gt;. Wo der herkommt, gibt es noch mehr.\n\nAuf dieser Insel gibt es keinen Mangel an herumgammelnden Piraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11465] = {title = "Die geplünderte Karawane", objective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr mithilfe des dressierten Steinfalkens 5 Fjordtruthähne einfangt.\n\nKehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt den Käfig mit.", description = "Ich führte eine Karawane von Valgarde hierher, doch sie wurde von Drachenschindern angegriffen. Ich bin der einzige Überlebende dieses Hinterhalts. Zu allem Unglück habe ich es nicht geschafft, die Ladung Fjordtruthahn mit mir zu nehmen. Das ist die perfekte Gelegenheit für Euch, gemeinsam mit Eurem Falken den Sprung ins kalte Wasser zu wagen.\n\n<Hidalgo reicht Euch einen Käfig.>\n\nNehmt diesen Falkenkäfig und begebt Euch gen Westen die Straße entlang, die aus diesem Lager herausführt. Fangt mithilfe des Falkens die freilaufenden Truthähne ein und kehrt anschließend hierher zurück, sobald Ihr genug habt.\n\nVergesst nicht, die Falken zu füttern!", progress = "Euer Falke muss ständig gefüttert werden, sonst wird er die Jagdbeute, die er für Euch fangen soll, auffressen.", completion = "Die Dreckskerle sind gewieft - und geduldig! Wir dürfen unseren Feind nicht länger unterschätzen. Diese Vrykul sind tödliche Jäger!\n\nTrotzdem: Mission abgeschlossen. Vielleicht ist die Zeit reif für Euch, auf etwas Jagd zu machen, das schwieriger zu fangen ist, als ein fetter Truthahn, hm?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11466] = {title = "Jack hebt gern' mal einen", objective = "Taruk im Halunkeneck im Heulenden Fjord möchte, dass Ihr Jack Adams' Schulden eintreibt.", description = "Unser nächster Kunde, Jack Adams, wird nicht so leicht zu besiegen sein wie Harry. Er verbringt den ganzen Tag damit, gemeinsam mit seinen Freunden, die allesamt harte Piratenjungs sind, einen zu heben. Lasst uns diesmal keine Gewalt anwenden - könnte sonst schlimm ausgehen.\n\nVersucht, seine Trinkgewohnheiten zu Eurem Vorteil zu nutzen - denn ab 'ner bestimmten Menge Alkohol kippt jeder um.\n\nVielleicht könnte ja eine der Schankmaiden behilflich sein. Sobald er weggetreten ist, könntet Ihr ja Eure Hand in seine Tasche gleiten lassen und an das herankommen, was eigentlich mir gehört.", progress = "Habt Ihr bekommen können, was mir gehört, <Name>?", completion = "Ich bin beeindruckt, &lt;Name&gt;. Und ich gehör' nicht gerade zu der Sorte, die sich leicht beeindrucken lässt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11467] = {title = "Des toten Mannes Schulden", objective = "Taruk im Halunkeneck will, dass Ihr auf dem Plateau am nordöstlichen Ende der Insel der Speere gleich nördlich von Iskaal auf die Suche nach dem Schatz des Schwarzen Konrad geht.", description = "Ihr habt vielleicht vom Schwarzen Konrad gehört, er ist ein berühmter Pirat in dieser Gegend.\n\nEr hat sehr gern auf meine Kämpfe gewettet. Er hat allerdings auch sehr gern nicht gezahlt.\n\nIch würde mein Geld gern haben, aber das Problem ist... er ist tot.\n\nIch war schon drauf und dran, die ganze Sache abzuschreiben, als ich das hier gefunden habe...\n\n<Taruk faltet eine Karte von der Insel der Speere auf, das nordöstliche Plateau ist mit einem roten X markiert.>\n\nEr hat seinen Schatz im Land der Tuskarr versteckt. Ich möchte, dass Ihr ihn holt. Ich will verdammt sein, wenn ich diesen Brackschlürfer ohne zu bezahlen davonkommen lasse.", progress = "Habt Ihr den Schatz gefunden, <Name>?", completion = "Ich werde das Gold nehmen. Es ist, was Konrad mir geschuldet hat. Den Rest könnt Ihr behalten.\n\nWenn Ihr mal eine Festanstellung braucht, bin ich mir sicher, ich könnte da etwas arrangieren. Möget Ihr in der Zwischenzeit stets Wind in den Segeln haben, mein Freund.", rewards = "Ihr bekommt:\n\nSchatz vom schwarzen KonradAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11468] = {title = "Falke gegen Habicht", objective = "Hidalgo am Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euren dressierten Steinfalken nutzt, um 10 Fjordhabichte zu erbeuten.\n\nKehrt mit dem Käfig zu Hidalgo zurück, wenn Ihr die Aufgabe Abgeschlossen habt.", description = "Spürt Ihr die Nähe, <Name>? Ihr fühlt sicherlich bereits, wie sich eine echte Bande zwischen Euch und Eurem Falken entwickelt. Würdet Ihr mir glauben, wenn ich Euch sage, dass es Zeit ist, durch die Augen Eures Vogels zu sehen? Ja, das ist der Meistergrad der Falknerei.\n\nDoch zuerst müsst Ihr mehr jagen! Der Vogel muss seine Reflexe verbessern und beschleunigen. Lasst es ihn mit einem anspruchsvolleren Gegner aufnehmen! Die Fjordhabichte der Region haben die Baumkronen über uns zu ihrer Heimat gemacht. Sie sind Euer nächstes Ziel!", progress = "Euer Falke muss stetig gefüttert werden, sonst wird er auch die Beute fressen, die er lediglich töten soll.", completion = "Ja, die Habichte weisen ein starkes territoriales Verhalten auf und fliegen oft im Schwarm. Ich schätze, das hätte ich Euch auch erzählen können, bevor ich Euch rausgeschickt habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11469] = {title = "Schrubbseife", objective = "Lukchen Frostbug will, dass Ihr Tran vom fetten Roy besorgt, als Hauptbestandteil ihrer magischen Schrubbseife. Kehrt zu ihr auf das östliche Piratenschiff beim Halunkeneck zurück, wenn Ihr ihn habt.", description = "Jo, ich muss das Deck blitzeblank geschrubbt haben, bevor der verrückte Jonah wiederkommt. Un' ich werd das nicht auf meinen Knien machen!\n\nProblem: Wir ham keine Seife mehr. Das is' aber mehr Euer Problem als meins. Ihr seid <der Neue/die Neue> un' ich hab 'nen Spezialauftrag für Euch.\n\nOben an der Nordwestküste der Insel gibt's nen ganzen Haufen Seelöwen. Auf den Eisschollen in der Nähe findet Ihr den Alphabullen, den fetten Roy. Ihr bringt mir seinen Tran und ich zauber die beste Seife, die Ihr je geseh'n habt!", progress = "Wo is' der Tran? Un' versucht nich' mir zu sagen, dass er keinen hat.\n\nDer fette Roy is' so verdammt fett, is'n Wunder, dass er überhaupt noch rumflanier'n kann!", completion = "Iiäh, das is' mal 'n Gestank!\n\nMacht schon, legt ihn dort hin. Ich wirk' meinen Zauber und dann wird mit Sicherheit Schrubbseife draus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11470] = {title = "Unter dem Vogelvieh gibt es keine Ehre", objective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr mithilfe Eures dressierten Steinfalkens 8 Eier eines Fjordhabichts sammelt.\n\nKehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und nehmt den Käfig mit.", description = "Ihr seid definitiv für den nächsten Schritt in der Falknerei bereit, <Name>.\n\nNehmt Euren dressierten Falken und geht zum Vrykulfalkennest in der Nähe des Aufzugs am Steinwall östlich von hier. Von dort aus werdet Ihr Euren Falken aussenden, um die Eier des Habichts zu sammeln. Ihre Nistplätze liegen in den abgelegenen Bereichen der Klippen um das Nest herum. Findet diese Nester und ergattert mithilfe Eures Falkens die Eier!\n\nNehmt Euch jedoch vor den Fjordhabichtmatriarchinnen in Acht, <Name>. Merkt Euch, dass Ihr mithilfe der Flucht- und Gleitfähigkeiten Eures Falkens Angriffen entgehen könnt.", progress = "Ihr habt Euren Vogel jetzt unter Kontrolle, <Name>. Zeigt Eurem Falken, wohin er fliegen soll, und bringt mir diese Eier.", completion = "Bravo, &lt;Name&gt;! Bravo! Die Bande zwischen Euch und Eurem Falken sind stark! Vielleicht könnt Ihr in absehbarer Zukunft auch ein paar Aufklärungsmissionen in Vrykulgebiet unternehmen.", rewards = "Feuerläuternde TunikaBiegsame LederfußlappenUnentrinnbarer GurtLeichtgebundener BrustschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11471] = {title = "Jetzt geht's lo-os", objective = "Annie Bonn im Halunkeneck möchte, dass Ihr Jonah Sterlings Handfernrohr zu ihr bringt.", description = "Ich weiß, weshalb du hier bist, <Name>. Du sollst unseren Anführer Jonah Sterling töten.\n\nIch würde dir in dieser Angelegenheit gerne meine Hilfe anbieten, denn Jonahs Führungsstil bringt unsere Mission in Gefahr.\n\nGleichzeitig die Flotten der Horde und Allianz anzugreifen: purer Selbstmord. Die Tuskarr in die Sklaverei verkaufen zu wollen, obwohl sie schon nach ein paar Tagen außerhalb dieses Klimas sterben: katastrophal.\n\nJonahs Unterschlupf befindet sich in einer Höhle westlich von hier. Bringt mir sein Handfernrohr als Beweis und meine erste Handlung als neue Anführerin wird es sein, alle Feindseligkeiten gegen unsere Verbündeten einzustellen.", progress = "Tja, <Name>. Hast du Jonahs Handfernrohr bekommen können?\n\nDein Wort alleine genügt mir nicht, verstehst du? Schließlich bin ich eine Piratin.", completion = "Jonah Sterlings Tage sind endlich gezählt! Er hätte niemals gedacht, dass es diese \"Magd\" mal zu was bringen würde.\n\nIch werde die Zeit, in der sich die Neuigkeiten über Jonahs Tod unter den Piraten verbreiten, dazu nutzen, meine Führung zu festigen. Meine Crew wird deinen Verbündeten keine Probleme mehr bereiten, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGlücksknoten des MatrosenTaschenuhr des Ersten MaatsSchlag des Meeres\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11472] = {title = "Der Weg zu seinem Herzen...", objective = "Werft einem Riffbullen schmackhafte Rifffische zu, um ihn zu einer Riffkuh zu führen. Habt Ihr den Zweien verholfen, wahre Liebe zu finden, dann kehrt zu Anuniaq in Kamagua zurück.", description = "Die Nordmeerpiraten haben den fetten Roy, den Alphabullen der Seelöwen dieser Insel, abgeschlachtet. Dann haben sie aus ihm Seife gemacht, um die Decks ihrer Schiffe sauber zu schrubben!\n\n<Anuniaq seufzt.>\n\nJetzt werden sich die Seelöwen nicht paaren. Helft mir, ihre Zahl aufrechtzuerhalten.\n\nDie Riffbullen halten sich südöstlich von hier an der Zwillingsküste auf. Sie mögen ganz besonders die schmackhaften Rifffische, die am östlichen und westlichen Ufer zu finden sind.\n\nNehmt dieses Netz hier und sammelt genug Fische, mindestens ein Dutzend - vielleicht mehr -, um einen Bullen durch die Meerenge zu einer Riffkuh zu locken.", progress = nil, completion = "Das sind gute Neuigkeiten! Jetzt werden mehr Bullen durch die Meerenge schwimmen, um sich mit den Kühen zu paaren. Schon bald werden wir viele Jungtiere auf den Inseln haben.\n\nDank Euch, &lt;Volk&gt;. Was auch immer Ihr in der Vergangenheit getan haben mögt, wisst, dass Ihr der Zukunft von Kamagua einen Dienst erwiesen habt!\n\nWir müssen so weitermachen, wenn wir dafür sorgen wollen, dass sich ihre Population erholt. Kommt morgen bitte wieder, damit wir ein weiteres Paar zusammenbringen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11473] = {title = "Ein Verräter unter uns", objective = "Sprecht mit Zeh'gehn im Halunkeneck.", description = "Unser Kapitänleutnant, Annie Bonn, tut in letzter Zeit ziemlich paranoid. Sie scheint sich sicher, dass wir einen Spion unter uns haben, könnt'er das glauben?\n\nNa jedenfalls haben wir hier 'ne narrensichere Methode, Ratten zu jagen. Wisst Ihr, der gute Zeh'gehn dort drüben ist ein echter Hexendoktor. Hat einen Stammbaum bis nach Zul... Dingens oder so.\n\nGeht und sagt ihm, dass wir seine Wahrsagerkünste brauchen. Ich muss Euch warnen, <Name>, nur ein oder zwei von uns können auch nur irgendetwas von dem verstehen, was Zeh'gehn sagt.", progress = nil, completion = "Hia drüban, Maan. Du komman, um mich zu seh'n?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11474] = {title = "Ärger am hohen Kliff", objective = "Sprecht mit Walt.", description = "Wie immer müssen meine Crew und ich die eigentliche Arbeit erledigen. Zum Glück ist McSorfs Team nicht umsonst gestorben. Die Glyphe, die sie geborgen haben, wird uns bei der Entschlüsselung der Funde, die wir hier gemacht haben, helfen - das heißt, wenn wir jemals wieder in ihre Nähe kommen! Diese verdammten Eisenzwerge sind überall wie Pilze aus dem Boden geschossen und versuchen nun die Ausgrabungsstätten zuzuschütten! Ist das zu fassen? Die Dreckskerle wollen unsere Funde unter einem Haufen Erde begraben!\n\nWie dem auch sei, sprecht mit Walt dort drüben. Er wird Euch einweisen.", progress = nil, completion = "Über die Hälfte unseres Teams ist tot oder wird vermisst, Kleiner. Das ist unsere letzte Stellung hier oben auf dem hohen Kliff. Diese verdammten Eisenzwerge haben uns aus Ivalds und Baelguns Ruine vertrieben. Ich hab' jedoch einen Plan auf Lager, mit dessen Hilfe wir dort wieder reinkommen, bevor sie all unsere tollen Sachen unter der Erde begraben und wir unsere gesamten Daten für immer verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11475] = {title = "Das nötige Werkzeug für den Job", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr seine Bauwerkzeuge beschafft.", description = "Ich hab' dieses deaktivierte Konstrukt schon seit Tagen untersucht, <Name>. Denke, dass ich eine passable Kopie des Golems anfertigen kann, die genug Platz für einen Passagier haben wird. Dahinter steckt die Idee, dass sich damit die Eisenzwerge täuschen lassen und wir Zutritt zu Baelguns Ruine erhalten.\n\nNun, ohne Hammer und Schüreisen werde ich gar nichts machen können. Ich brauch' mein Werkzeug! Unglücklicherweise hab' ich es in Ivalds Ruine zurückgelassen, als die Eisenzwerge das erste Mal angriffen. Beschafft mir mein Werkzeug!\n\nIvalds Ruine befindet sich weit im Nordosten.", progress = "Schritt Nummer Eins: Walts Werkzeug besorgen.", completion = "Da ich mein Werkzeug nun wieder habe, kann die Arbeit beginnen. Das heißt, sobald ich ein paar Materialien habe. Die werdet Ihr mir nämlich als nächstes besorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11476] = {title = "Ein Frosch und ein Messer", objective = "Besorgt Euch ein glänzendes Messer von \"Silbermond\" Harry und fangt einen Ganovenfrosch. Bringt dann beides zu Zeh'Gehn im Halunkeneck.", description = "Einige der Piraten hier... wir haben unsere ganz eigener Art zu sprechen. Zeh'gehn hat... sehr viele spezielle Arten zu reden... alles zusammengemischt.\n\nSoweit ich es verstehe, will er einen Frosch und ein Messer.\n\n\"Silbermond\" Harry könnte ein Messer für lau haben. Frösche rennen hier überall durch den Ort, schnappt Euch einfach einen und bringt ihn zusammen mit dem Messer zu ihm.\n\nAlso, ich will nicht in den Schuhen von dem armen Viech stecken, wenn Ihr wisst, was ich mein'.", progress = "Dia hat da Frosch un' Schnitza bekom, Mann?", completion = "Gut Dank, Bruddah. Da Frosch is' echt krass!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11477] = {title = "Nicht in meinem Element?", objective = "Donny in Ivalds Ruine im Heulenden Fjord möchte, dass Ihr 10 Eisenrunenzerstörer, 5 Eisenrunenhilfsarbeiter und 2 Eisenrunenweise tötet.", description = "Leiser, <Volk>, leiser. Die Finger der Eisenzwerge sind schnell am Abzug. Nun, lasst Euch nicht von den Geschehnissen dort unten in der Grube täuschen. Diese stählernen Monstrositäten sind nicht dabei, irgendwas auszugraben! Nein, <Herr Kamerad/Frau Kameradin> - ganz im Gegenteil: Sie schütten die Stätte zu! Aus irgendeinem verrückten Grund wollen sie verhindern, dass irgendjemand diesen Ort findet.\n\n\"Was muss das für ein Zwerg sein, der uralte Relikte und Ausgrabungsstätten unter der Erde begraben will\", frage ich Euch. Nun, das will ich Euch verraten: Es ist die Art von Zwerg, die man mit rücksichtsloser Hingabe um die Ecke bringt! Geht dorthin und schaltet sie aus!", progress = "Ihr werdet so viele töten müssen, bis Ihr Euren Teil erfüllt habt.", completion = "Gute Arbeit, &lt;Name&gt;. Das wird ihre Vergrabungsaktion ein wenig verlangsamen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11478] = {title = "Außenposten dort drüben...", objective = "Überbringt Donnys Brief an Stanwad im Außenposten der Forscherliga.", description = "Ich sehe, dass Ihr noch nicht im Außenposten der Forscherliga im Süden wart und meinen Bruder besucht habt. Wieso tut Ihr Donny nicht einen Gefallen und überbringt Stanwad diese Nachricht. Es wird ihn interessieren, darüber zu erfahren, was die Eisenzwerge hier oben treiben.\n\nWie ich bereits sagte: Setzt auf und begebt Euch in Richtung Süden. Kurz bevor Ihr Baelguns Ruine erreicht, werdet Ihr den Außenposten sehen.", progress = "Nachrichten von Donny?", completion = "Tja, nichts, das wir nicht schon wüssten. Zumindest wissen wir jetzt, dass Donny noch immer am Leben ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11479] = {title = "\"Krähenbein\" Dan", objective = "Konfrontiert \"Krähenbein\" Dan. Er befindet sich auf einem der Schiffe im Halunkeneck. Sprecht mit dem hübschen Terry, sobald diese Aufgabe erfüllt ist.", description = "Kröide hat geplabbärt, Kamerad. \"Krähenbein\" Dan is' uff de Kuddä da druiben.\n\nAm bestän geis'du da rübbä un' souchst nach de Radde, Mann. Gei z'rück zum Terry, wenn de Kielhaulerai fäddich is'.", progress = "Ich kann's gar nicht fassen, dass es Dan war. Habt Ihr Euch schon drum gekümmert?", completion = "Das sind mal traurige Neuigkeiten. Dan war'n alter Freund von mir... UND hat mir Gold geschuldet. Egal, wenn er mit diesen Südmeerbastarden gemeinsame Sache gemacht hat, dann hat er bekommen, was er verdient.\n\nWas Euch betrifft, mein Freund... Würde mal sagen, dass Ihr auf dem Weg nach oben seid, und zwar buchstäblich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11480] = {title = "Nummer Zwei kennenlernen", objective = "Sprecht mit Annie Bonn im Halunkeneck.", description = "Es ist nicht unbeachtet geblieben, was für gute Arbeit Ihr bis jetzt für uns geleistet habt, <Name>. Unsere Zweitkommandierende, die charmante Annie Bonn, ist überaus beeindruckt von dem, was Ihr bisher getan habt, und will Euch kennenlernen.", progress = nil, completion = "Aber, aber, aber... Wenn das nicht &lt;Name&gt; ist. Ihr taucht hier im Halunkeneck auf, niemand hat von Euch gehört, außer irgend so ein Goblin, den dieser Schwachkopf Terry seinen Freund nennt.\n\nSagen wir einfach mal, dass ich ein wenig... skeptisch bin... was Eure Absichten hier angeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11481] = {title = "Krise am Sonnenbrunnen", objective = "Adyen der Lichtwächter auf der Aldorhöhe in Shattrath hat Euch gebeten, zum Sonnenbrunnenplateau zu reisen und dort mit Larethor zu sprechen.", description = "Bei den Naaru, ich danke Euch, <Volk>, für Euer Bemühen.\n\nUnsere Arbeit hier ist jedoch noch lange nicht beendet, weswegen ich Euch darum bitten muss, eine entscheidende Mission auszuführen - eine Mission so wichtig wie alle, mit denen ich Euch jemals beauftragt habe.\n\nUnsere Streitkräfte sind weit verteilt. Und um das Ganze noch schlimmer zu machen, mussten wir ein Kontingent nach Azeroth abbestellen, das die Entwicklung der Dinge auf dem Sonnenbrunnenplateau untersuchen soll.\n\nIhr werdet dort gebraucht, <Name>. Meldet Euch bei Larethor und richtet ihm aus, ich wünschte, wir könnten mehr Männer entbehren.", progress = nil, completion = "Noch ein Soldat aus Shattrath? Welch willkommener Anblick!\n\nWünschte es gäbe mehr wie Euch, aber wir müssen mit dem auskommen, was uns gegeben ist. Was auch immer dort draußen geschieht, es wird nicht darauf warten, dass wir vorbereitet sind.\n\nSeht Euch ein wenig um, &lt;Klasse&gt;. Es gibt viel zu erledigen. Packt mit an und tut Euren Teil.\n\nOh, ich vergaß: Macht Euch nicht über die Anfänger... ähhm, Anhänger der Seher lustig. Sieht aus, als würden wir in dieser Sache am selben Strang ziehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11482] = {title = "Pflicht ruft", objective = "Dathris Sonnensturm auf der Sehertreppe in Shattrath besteht darauf, dass Ihr umgehend nach Azeroth reist und Euch bei Larethor am Sonnenbrunnen meldet.", description = "Hört mich an, <Volk>.\n\nDie Pflicht verlangt, dass Ihr Euch zurück nach Azeroth begebt. Ein jeder, der dazu im Stande ist zu kämpfen, soll sich umgehend auf dem Sonnenbrunnenplateau melden.\n\nIch fürchte, dass ich Euch keine weiteren Informationen geben kann als diese:\n\nFür diese Mission werdet Ihr Euch mit den Aldor zusammentun. Sprecht mit einem Draenei namens Larethor, sobald Ihr dort ankommt.\n\nAnscheinend fordert die Situation, dass wir unsere Differenzen beiseite legen und uns zusammenschließen.\n\nMacht Euch bereit. Das hier klingt ernst.", progress = nil, completion = "Willkommen auf dem Sonnenbrunnenplateau, Anfänger der... Wie bitte? Oh - Anhänger der Seher, natürlich. Habe ich das nicht gesagt?\n\nNun, gut, kommen wir gleich zur Sache. Hinter diesen Mauern geht es ernsthaft zur Sache, und das ist für unsere beiden Völker von großem Interesse. Und da keiner von uns über genügend Streitkräfte verfügt, um die Sache alleine anzugehen, werden wir ZUSAMMENARBEITEN. Verstanden?\n\nNa dann fangen wir doch einmal an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11483] = {title = "Wir können es nachbauen", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr ihm ein großes Fass, ein Seil in Industriestärke und Dunkeleisenblöcke bringt.", description = "Werkzeug? - vorhanden. Materialien? - nicht vorhanden.\n\nWenn wir dieses Ding bauen wollen, dann werdet Ihr mir die Materialien besorgen müssen.\n\nEins nach dem anderen, <Name>. Für das Skelett benötige ich ein großes Fass aus Niffelvar, ein paar Dunkeleisenblöcke aus Valgarde und ein Seil in Industriestärke aus Quälheim.\n\nDie Vrykulorte Niffelvar und Quälheim liegen nordwestlich von hier; Valgarde befindet sich in der Dolchbucht - was auch im Nordwesten liegt. Sprecht mit McGoyver, um die Blöcke zu bekommen. Er wird Euch hierher zurückfliegen, wenn Ihr alles besorgt habt.", progress = "Habt Ihr die Materialien für das Skelett dabei?", completion = "Ausgezeichnet. In Kombination mit der Haut wird daraus ein makelloser Klon des Konstrukts, das von den Eisenzwergen verwendet wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11484] = {title = "Wir haben die Technik", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr ihm einen makellosen Schaufelhauerbalg und ein Stück Rippenstahl bringt.", description = "Für eine Maschine wie diese ist der Unterbau zwar wichtig, doch wir dürfen die Wichtigkeit der Verkleidung des Konstrukts nicht unterbewerten. Wenn wir die Eisenzwerge zum Narren halten wollen, dann muss das Abbild perfekt sein!\n\nIch kann dafür sorgen.\n\nBringt mir einen makellosen Schaufelhauerbalg von den Schaufelhauern dieser Region und ein Stück Rippenstahl von den Vrykul in Niffelvar oder Quälheim gen Nordwesten.", progress = "Wir werden im Nu weiter nach unseren Relikten suchen können!", completion = "Ich werde dafür sorgen, dass das Konstrukt einsatzbereit ist, sobald der Unterbau steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11485] = {title = "Eisenrunenkonstrukte und du: Raketensprünge", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und dessen Fähigkeit 'Raketensprung' bei Walts Eisenrunengravur ausführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Nun gut, <Name> - die Zeit ist gekommen, dass Ihr in dieses Ding klettert und den Umgang mit seinen grundlegenden Fähigkeiten lernt. Steigt auf die Werkbank, wenn Ihr bereit seid, und ich werde Euch ins Innere des Konstrukts setzen.\n\nEure erste Lektion dreht sich um die Bedienung des Transportsystems des Konstrukts. Ihr werdet bemerken, dass sich überall in der Ausgrabungsstätte spezielle Gravuren der Eisenzwerge befinden. Diese Runen werden von ihren Konstrukten dazu verwendet, sich aufzuladen und von einem Punkt zum nächsten zu fliegen. Versucht es einmal mit meiner Runengravur hier.", progress = "Lasst Euch von diesen Schwarzmalern nichts gefallen!", completion = "Ihr seid schon fast bereit, mit diesem Kunstwerk ins Feld zu ziehen, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11488] = {title = "Terrasse der Magister", objective = "Exarch Larethor beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die Terrasse der Magister absucht und einen Blutelfenspion namens Tyrith findet.", description = "Willkommen am Sonnenbrunnen, <Klasse>. Macht Euch mit der Umgebung vertraut und legt dort Hand an, wo Ihr nur könnt. Es gibt viel zu tun!\n\nIch? Ja, ich hätte da eine Kleinigkeit, die erledigt werden müsste, aber ich bin mir nicht sicher, ob Ihr der Aufgabe gewachsen wäret.\n\nWir hatten einen Kontaktmann auf der Terrasse der Magister im Einsatz, der uns diverse Informationen zukommen ließ. Er hat jedoch vor Kurzem versäumt, uns Bericht zu erstatten, weswegen ich mir zunehmend Sorgen mache.\n\nDie Terrasse befindet sich gleich im Osten, die Anhöhe hoch. Die Informationen, die er gesammelt hat, sind entscheidend für unsere Mission.\n\nDenkt Ihr, dass Ihr damit zurecht kommt, <Volk>?", progress = nil, completion = "...Kommt näher, &lt;Volk&gt;... Hört genau auf meine Worte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11489] = {title = "Eisenrunenkonstrukte und du: Daten sammeln", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Daten sammeln' in der Nähe des Eisenzwergrelikts ausführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Während Ihr das Konstrukt bedient, wird Eure wichtigste Aufgabe das Sammeln von Daten sein. Ich habe ein Eisenzwergrelikt in den Karren dort drüben gelegt - es geht um den schwebenden blitzerfüllten Kristall.\n\nSteigt auf die Werkbank und ich werde Euch wieder in das Konstrukt setzen. Führt die Datensammlungsfähigkeit des Konstrukts aus, sobald Ihr wieder hinterm Steuer sitzt, und sammelt die Testdaten auf.", progress = "Passt wie angegossen, oder?", completion = "Perfekt! Funktioniert einwandfrei!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11490] = {title = "Der Seher der Seher", objective = "Tyrith möchte, dass Ihr die Kugel auf dem Balkon in der Terrasse der Magister benutzt.", description = "Geht zur Terrasse... benutzt die Kugel.\n\n<Tyrith ringt nach Luft.>\n\nBeeilt Euch... Ihr müsst sie aufhalten... bevor sie...\n\n<Tyrith stirbt.>", progress = nil, completion = "Ich denke, dass es kein Zufall ist, dass sich unsere Wege heute kreuzen.\n\nIch meine zu erkennen, dass dies eine Fügung des Schicksals ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11491] = {title = "Eisenrunenkonstrukte und du: Täuschung", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Bluffen' auf Lebronski ausführt, nachdem Ihr über seinen Teppich gestiegen seid.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Man muss immer einen Notfallplan auf Lager haben, für den Fall, dass der Hauptplan fehlschlagen sollte! Das ist auch der Grund, weshalb ich das Konstrukt mit ein paar Antispionagesystemen ausgestattet habe.\n\nEs könnte sein, dass, sobald Ihr Euch in Baelguns Ausgrabungsstätte befindet, Euer toller, neuer Schlitten Verdacht erregt. Und genau dafür ist die Täuschungsfähigkeit da! Macht einfach bei jeder Konfrontation davon Gebrauch und Euch wird kein Leid zugefügt.\n\nVersucht es einmal an Lebronski und steigt auf seinen Teppich. Führt die Fähigkeit aus, sobald er Euch anschnauzt!\n\nSteigt auf die Werkbank, wenn Ihr bereit seid anzufangen.", progress = nil, completion = "Ihr habt's ihm gezeigt! Nun ist es an der Zeit, Euch ins Feld ziehen zu lassen!\n\nHoffe, Ihr seid Euch der Sache sicher...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11492] = {title = "Nicht totzukriegen", objective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor am Sammelpunkt der Zerschmetterten Sonne treffen.", description = "Der Sonnenbrunnen heißt Euch willkommen, Sterbliche. Ihr trefft in der Tat zur rechten Zeit ein.\n\nWie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Findet ihn, Sterbliche. Noch einmal muss er aufgehalten werden.\n\nAndere Angelegenheiten von gleicher Dringlichkeit erfordern meine sofortige Aufmerksamkeit. Ich lege Kaels Schicksal in Eure Hände. Ihr dürft nicht versagen.\n\nMit etwas Glück werden wir uns wieder sprechen.", progress = "Nun ja, <Klasse>, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.\n\nWelch Kunde bringt Ihr mir?", completion = "&lt;Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten auf der Terrasse der Magister berichtet.&gt;\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.\n\nIch habe Euch unterschätzt, &lt;Volk&gt;. Bitte, nehmt dies im Namen der Sonnenbrunnenoffensive - eine Gabe, die eines Helden, wie Ihr einer seid, würdig ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeingeschliffener PurpurspinellGlänzender PurpurspinellGlänzender Purpurspinell\n\nIhr erlernt außerdem:\n\nHeroische Contenance\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11493] = {title = "UNUSED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11494] = {title = "Blitzerfüllte Relikte", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und mit der Fähigkeit 'Daten sammeln' 15 Lesungen von Eisenrunendaten durchführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Euer Konstrukt ist nun einsatzbereit. Alle Fähigkeiten wurden einer kurzen Prüfung unterzogen und ich habe die Maschine so programmiert, dass sie die Sprache der Titanen verstehen und sprechen kann.\n\nBegebt Euch mit dem Konstrukt zu Baelguns Ausgrabungsstätte genau südlich von hier, findet die dort überall verstreut liegenden blitzerfüllten Relikte und sammelt deren Daten. Erinnert Euch daran, jeglichen Eisenzwerg zu täuschen, der Verdacht an der Echtheit Eures Konstrukts hegt. Und vergesst nicht, per Raketensprung von Rune zu Rune zu springen und auf diese Weise mobiler zu sein!\n\nSteigt auf den Tisch, wenn Ihr bereit seid!", progress = nil, completion = "Und wieder einmal beweist Walt, dass er in der Tat der beste Zwerg ist! Was hältst du jetzt von meinem Konstrukt, Lebronski!\n\nIch danke Euch, &lt;Name&gt;. Diese Daten werden sich zweifellos als unbezahlbar erweisen - wenn ich erst einmal herausbekommen habe, wie man sie aus dem Konstrukt herausbekommt.", rewards = "Schockresistente KapuzeBebänderte KettenhandschuheGeneröse BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11495] = {title = "Der zarte Knall des Donners", objective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die donnernde Höhle in Baelguns Ausgrabungsstätte erkundet.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", description = "Die Höhle, die wir in Baelguns Ausgrabungsstätte freigelegt haben, war DER Ort, vor dem sich die meisten fernhielten... Kann nicht sagen, dass ich ihnen das vorwerfe. Der Schlund der Höhle spuckte krachenden Donner, <Name>! Ohrenbetäubender Donnerknall war es!\n\nIch denke, dass gegen Ende ein jeder die Höhle aufgegeben hatte. Denjenigen, die sich hineinwagten, um den Ort zu erkunden, widerfuhr Schlimmstes - und meistens kamen sie nicht zurück.\n\nIch möchte, dass Ihr Euch diese Höhle einmal anseht, wenn Ihr in Baelguns Ausgrabungsstätte seid. Begebt Euch ins Innere, erkundet die Gegend um die Titanenstatue und meldet Euch dann mit den Funden wieder bei mir zurück.", progress = nil, completion = "Unglaublich! Was könnten diese Eisennervensägen im Schilde führen? Was machen sie auf den Sturmgipfeln? Und wer ist dieser Loken?! Ich werde die Informationen an unsere zentrale Operationsbasis in der Drachenöde weiterleiten, &lt;Name&gt;. Auch werde ich sie wissen lassen, dass Ihr bei der Beschaffung besagter Infos außerordentlich wertvoll gewesen seid.", rewards = "Federleichtes ClaymoreSäuregeätzte KnöchelGekräftigter VollstahldolchDonnerbüchse mit MiniabzugIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11496] = {title = "Die Barrieren des Sanktums", objective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und getriebenen Verschlingern verschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche den Osten des Sanktums der Sonnenweiten umgeben.", description = "Zuerst müssen wir das Sanktum der Sonnenweiten einnehmen. Sobald wir es gesichert haben, werden wir in der Lage sein, seine Energien für die Öffnung eines Portals nach Shattrath zu nutzen.\n\nDas Sanktum quillt über von Getriebenen - frühere Blutelfen, die zu hirnlosen Schatten ihrer selbst verkümmert sind. Die Verteidigungsanlangen hätten dieses Eindringen normalerweise verhindert, aber die Getriebenen haben die Energiequellen der Schutzbarrieren gestohlen.\n\nStellt den Getriebenen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt sie, um die Barrieren des Sanktums aufzuladen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11497] = {title = "Fliegen lernen", objective = "Sprecht mit Ilsa Trubelbräu in der Wildhammerfeste im Schattenmondtal.", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, der sein eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch zur Wildhammerfeste im Südwesten des Schattenmondtals begeben, und dort Ilsa Trubelbräu nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", progress = nil, completion = "Ach, Nutral hat Euch also hierher geschickt? Sehr gut... Erinnert mich daran, dass ich ihm einen Krug Bier zum Dank für all die Fluglehrlinge, die er zu mir schickt, zukommen lasse.\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Niemand fliegt besser als die Wildhammer und diejenigen, die von uns ausgebildet wurden. Für ein Entgelt, ein nicht zu kleines wohlgemerkt, lehre ich Euch die Kunst des Fliegens!\n\nUnd wenn Ihr fertig seid, dann vergesst nicht mit Brunn zu sprechen - er hat ein paar schöne Greifen zur Auswahl!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11498] = {title = "Fliegen lernen", objective = "Sprecht mit Olrokk in Schattenmond im Schattenmondtal.", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, <der sein/die ihr> eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch nach Schattenmond im Nordwesten des Schattenmondtals begeben, und dort Olrokk nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", progress = nil, completion = "Blut und Donner, Nutral hat mir schon wieder einen Boden-Grunzer geschickt! Sehr gut... für einen Draenei.\n\n&lt;Olrokk spuckt auf den Boden neben Euch.&gt;\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Für einen großen Sack Gold bringe ich Euch genug bei, um nicht unehrenhaft in den Tod zu stürzen.\n\nUnd wenn Ihr fertig seid, dann vergesst nicht, Dama Wildmähne einen unserer Windreiter abzukaufen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11499] = {title = "Gesucht: Der Siegelring von Prinz Kael'thas", objective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Siegelring von Prinz Kael'thas zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf der Terrasse der Magister und nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Heute werde ich das Unmögliche von Euch verlangen, <Klasse>. Denn heute müsst Ihr mir den Siegelring von Kael'thas Sonnenwanderer, Lord der Blutelfen, beschaffen!\n\nEs ist wahr, die Gerüchte von seinem Tod waren aus der Luft gegriffen. Er ist nun einmal mehr erschienen - und diesmal auf der Terrasse der Magister auf der Insel von Quel'Danas. Was er dort macht, soll Euch jemand anderes berichten. Was ich weiß ist, dass es unzählig viele Sammler gibt, die an diesem Prinzenring interessiert sind. Und ich will ihnen diesen Ring beschaffen.\n\nOder, um genau zu sein will ich, dass Ihr ihn für mich beschafft.", progress = "Die Terrasse der Magister muss in der Tat ein gefährlicher Ort sein - so nahe am Sonnenbrunnen, wie sie ist.\n\nIhr habt doch keine Bedenken, oder?", completion = "Der Blutelfenprinz ist also diesmal wirklich tot? Wie schade, ich dachte immer, dass er Klasse besäße. Wenn man sich denkt, dass jemand so erhaben für solch einen lumpigen Betrag zur Strecke gebracht werden konnte.\n\nAber es ist nun einmal so, wie man sagt: Geschäft ist Geschäft. Eure Belohnung ist verdient, Abenteuerer.\n\nKommt morgen wieder und ich werde einen anderen Auftrag für Euch haben.", rewards = "Ihr bekommt:\n\nAbzeichen der GerechtigkeitGerechtigkeitspunkteAbzeichen der Gerechtigkeit"}
MultiLanguageQuestData['de'][11500] = {title = "Gesucht: Schwestern der Qual", objective = "Netherpirscher Mah'duun möchte, dass Ihr 4 Schwestern der Qual erschlagt. Kehrt zu ihm in das Untere Viertel in Shattrath zurück, sobald Ihr sie getötet habt, um das Kopfgeld einzufordern.", description = "Mah'duun vernahm eine Stimme, die ihm zuflüsterte, dass die Schwestern der Qual in die Hölle zurückgeschickt werden müssen, aus der sie kommen.\n\nMah'duun weiß, dass sich die Dämonen auf der Terrasse der Magister auf der Insel Quel'Danas befinden.\n\nIhr werdet Euch des Kopfgeldes wegen auf dieses Unterfangen einlassen oder auch nicht.", progress = nil, completion = "Wer weiß, weshalb die dämonischen Schwestern den Tod finden müssen? Sorgt Ihr Euch darum?\n\nMah'duun denkt, dass Ihr Euch jedoch genug darum sorgt, um das Kopfgeld einzustreichen.\n\nKommt morgen wieder und die Winde werden wieder zu Mah'duun gesprochen haben.", rewards = "Ihr bekommt:\n\nGefängnisschlüssel des Astraleums"}
MultiLanguageQuestData['de'][11501] = {title = "Neues aus dem Osten", objective = "Sprecht mit Hauptmann Adams in Westwacht.", description = "Die Leute in Westwacht müssen erfahren, was hier vor sich geht, <Name>. Ich möchte, dass Ihr persönlich Hauptmann Adams die Nachricht überbringt.\n\nSagt mir Bescheid, sobald Ihr bereit seid, und ich werde Euch die Maschine für einen letzten Flug bereitstellen. Sie wird Euch zwar nach Westwacht tragen, jedoch höchstwahrscheinlich dabei in die Luft fliegen.\n\nEs war mir ein Vergnügen...", progress = nil, completion = "Herrlich... Als ob es nicht schon genug wäre, dass uns die Geißel am - na Ihr wisst schon - klebt, nun müssen wir uns auch noch mit einem wütenden uralten Titanenkonstrukt herumschlagen!\n\nIch werde etwas Zeit brauchen, um das zu verarbeiten, &lt;Volk&gt;. In der Zwischenzeit werdet Ihr hier genug Arbeit finden, die getan werden muss.", rewards = "Generöses BollwerkAuf Euch wartet eine dieser Belohnungen:\n\nFoliant des Eifers\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11502] = {title = "Zur Verteidigung von Halaa", objective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Lakoor in Telaar zurück.", description = "Wir sind kein kriegerisches Volk, <Volk>. Wenn der Krieg jedoch über unser Land kommt, rennen wir nicht vor ihm davon.\n\nDie Allianz und die Horde bekämpfen sich in der Stadt Halaa im Nordwesten. Wir wissen nicht, was die Blutelfen vorhaben, aber jeder Sieg, den die Horde erringt, wäre katastrophal. Die gemeinsame Geschichte unseres Volks mit den Orcs ist eine des Blutvergießens und des Verrats.\n\nGeht nun, streckt den Feind in Halaa nieder und Ihr werdet mit Münze, Ehre und Ruhm belohnt.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Eure Mühen werden nicht unbeachtet bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11503] = {title = "Feinde - alte und neue", objective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Karrtog in Garadar zurück.", description = "Unser uralter Feind, die Draenei, sind mit mächtigen Verbündeten wiedergekehrt. Sie führen Krieg in Halaa, südwestlich von hier.\n\nSie dürfen nicht siegreich sein, denn Garadar wäre gewiss als Nächstes dran.\n\nGeht und erschlagt diejenigen, die es wagen, unserem uralten Feind beizustehen.", progress = nil, completion = "Ihr macht unserem Volk große Ehre. Ihr habt unseren Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11504] = {title = "Die Toten stehen auf!", objective = "Orfus von Kamagua am Uralten Aufzug im Heulenden Fjord möchte, dass Ihr nach Fengirs Hinweis, Rodins Hinweis, Isuldofs Hinweis und Windans Hinweis sucht.", description = "Der Pfad östlich von uns gehört zu den wichtigsten Jagdgebieten der Tuskarr. Zumindest war das einmal so...\n\nWenn in jüngerer Zeit unsere Jäger nach Kamagua zurückkehren, behaupten sie, dass die Toten wiederauferstanden seien und nach Blut trachten! Aus diesem Grund sind mein Sohn und ich hierhergekommen. Urahn Atuik hat uns dazu aufgefordert, an der Steilküste nach einer Lösung des Problems zu suchen.\n\nWerdet Ihr uns in diesen Zeiten der Not zur Seite stehen? Ich suche nach Helden, die gewillt sind, den Gefahren des im Südosten gelegenen Schildhügels ins Auge zu blicken. Sucht in den entweihten Gräbern nach Hinweisen und kehrt mit den Funden zu mir zurück.", progress = "Die Tuskarr brauchen Eure Hilfe!", completion = "&lt;Orfus' Barthaare sträuben sich.&gt;\n\nPiraten... kennt ihre Verworfenheit keine Grenzen?\n\nWir müssen die gestohlenen Artefakte wiederbeschaffen und sie an diesen verwunschenen Ort zurückbringen, damit mein Volk einmal mehr erleben kann, was das Wort 'Frieden' bedeutet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11505] = {title = "Geister von Auchindoun", objective = "Helft der Allianz, einen Turm in der Knochenwüste zu sichern.", description = "Auchindouns Geister sind zwar nicht am Konflikt zwischen Allianz und Horde beteiligt, sollten wir sie jedoch auf unsere Seite ziehen können, hätten wir unseren Feinden gegenüber einen Vorteil in dieser Region.\n\nEin uralter Brauch führt die Lebenden auf den Pfad zu den Geistertürmen in der Knochenwüste, um den Geistern dort ihre Ehre zu erweisen - jedoch nur zu speziellen Tageszeiten. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werdet Ihr dadurch die Geister auf unsere Seite ziehen.\n\nSollten wir Erfolg damit haben, die Gunst der Geister zu erlangen, werden sie uns eine Wohltat erweisen, die unsere Bestrebungen unterstützen wird.", progress = "Die Geister sind ruhelos, <Name>. Habt Ihr Eure Aufgabe vollbracht?", completion = "Die Geister sind ihrer Ruhe einen Schritt näher. Es ist gut, ihre Gunst zu erlangen - besonders dann, wenn so nahe an ihrer Ruhestätte Krieg geführt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11506] = {title = "Geister von Auchindoun", objective = "Helft der Horde, einen Turm in der Knochenwüste zu sichern.", description = "Die Draenei mögen unsere Feinde sein, aber die Geister ihrer Urahnen in Auchindoun sind rastlos und niemandem untertan.\n\nEin uralter Brauch der Draenei verlangt von ihnen, dass sie zu verschiedenen Tageszeiten bei den Geistertürmen in der Knochenwüste ihren Urahnen Respekt zollen. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werden dadurch die Geister in Auchindoun zur Ruhe kommen.\n\nDie Allianz wird versuchen, die Türme einzunehmen, um die Gunst der Geister zu erlangen. Wir müssen sicherstellen, dass die Horde hier erfolgreich ist.", progress = "Die Geister von Auchindoun sind um uns. Werden sie uns eine Wohltat zuteilwerden lassen?", completion = "Die Geister sind einen Schritt näher daran, ihre Ruhe zu finden, und haben uns deswegen ihre Gunst verliehen.\n\nEs muss eine Demütigung für unseren Feind sein, dass sich seine eigenen Urahnen gegen ihn wenden - auch, wenn es nur vorübergehend ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11507] = {title = "Urahn Atuik und Kamagua", objective = "Orfus von Kamagua im Heulenden Fjord möchte, dass Ihr Orfus' Bündel nach Kamagua zu Urahn Atuik bringt.", description = "<Orfus packt die Hinweise, die Ihr ihm mitgebracht habt, zu einem Bündel zusammen.>\n\nMein Volk befindet sich in einer verbitterten Auseinandersetzung mit den Freibeutern des Nordmeeres, von der es keinen Ausweg zu geben scheint. Wenn irgendein Tuskarr uns helfen und die Schandtaten der Piraten ungeschehen machen kann, dann ist das Urahn Atuik von Kamagua. Ihr müsst diese Hinweise schleunigst zu ihm bringen.\n\nUm nach Kamagua zu gelangen, müsst Ihr den Uralten Aufzug hinter mir nehmen. Lasst Euch von ihm direkt nach Kamagua befördern und sucht Urahn Atuik auf.", progress = "Neuigkeiten von Orfus?", completion = "Orfus ist ein guter Tuskarr - einer unserer stärksten Krieger. Ich wusste, dass er uns nicht im Stich lassen würde.\n\nErlaubt mir, einen Blick auf das zu werfen, was Ihr mir mitgebracht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11508] = {title = "Grezzix Achsenbruch", objective = "Sprecht mit Grezzix Achsenbruch.", description = "Das Halunkeneck weit im Süden dient den Piraten als Hafen. Unglücklicherweise haben sie in ihrem Lager viele tödliche Verteidigungsanlagen aufgestellt.\n\nEs gibt jedoch jemanden, der uns vielleicht dabei helfen könnte, den Ort zu infiltrieren.\n\nVor Kurzem kam ein Piratensöldner namens Grezzix Achsenbruch in unser Dorf. Er ist auf der Suche nach Verpflegung und Unterkunft. Als Gegenleistung würde er uns Informationen über unsere Feinde geben und unseren Feinden Fehlinformationen über unsere Angriffspläne zukommen lassen. Sucht ihn auf, <Name>. Er befindet sich auf seinem Schiff südwestlich von hier.", progress = nil, completion = "Harr, Kamerad. Grezzix hat's nie gemocht, sich die Hände schmutzig zu machen! Grezzix findet das Piratenleben toll, solange er keine von den Arbeiten machen muss.\n\nIch hab' diese Artefakte gesehen. Sie sind der Grund dafür, wieso ich hier bin und nicht im Halunkeneck! Schlimme, schlimme Dinger sind das...\n\nHe, ist doch dein Leben, oder? Du willst ins Lager rein und Grezzix kann dir dabei helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11509] = {title = "Sich einen Ruf machen", objective = "Sprecht mit \"Silbermond\" Harry im Halunkeneck über die verschwundenen Vrykulartefakte.", description = "Alle Freibeuter des Nordmeeres fürchten und respektieren Grezzix. Ich denke mal, dass sie meine besonderen Talente achten und mein tolles Schiff beneiden. Alles, was du machen musst, ist, hinter meinem Kabinenjungen Lou hinterher zu latschen, und du bist in... in wie Zinn, sozusagen. Piraten lieben Zinn.\n\nRed' einfach mit Lou, wenn du fertig bist, und er wird dich zum Halunkeneck bringen.\n\nOh ja, als Erstes wirst du wohl mit \"Silbermond\" Harry sprechen müssen. Er wird mehr über das Zeugs Bescheid wissen, das sie mitgehen haben lassen. Pass bloß auf, was du vor ihm sagst. Das is'n Verrückter... verrückt nach Blutelfen ist er.", progress = nil, completion = "&lt;Harry blickt Euch an und zieht eine Augenbraue hoch.&gt;\n\nSo, du bist also wie ich, hm? Ein wenig exzentrisch.\n\n&lt;Harry flüstert Euch zu.&gt;\n\nNiemand zieht sich hier so an.\n\nWas diese Artefakte angeht... Jeder, der mit den Dingern in Berührung kam, ist am Ende entweder tot gewesen, verschwunden oder gleich beides.\n\nWenn du noch immer mehr erfahren willst, kann ich dir weiterhelfen - wird dich aber was kosten.\n\n&lt;Harry zwinkert Euch zu.&gt;\n\nDu tust mir 'nen Gefallen und ich lass dich am Leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11510] = {title = "\"Bodo von der Hermannsklause\"", objective = "\"Silbermond\" Harry im Halunkeneck möchte, dass Ihr den Orca \"Bodo von der Hermannsklause\" tötet und den Wahrsagerkristall der Sin'dorei wiederbeschafft.", description = "Das Erste, was Jonah Sterling gemacht hat, nachdem er durchgedreht ist, war, meinen hoch geschätzten Wahrsagerkristall der Sin'dorei zu nehmen und ihn an \"Bodo von der Hermannsklause\", den Orca und Fluch meines Lebens, zu verfüttern.\n\nNein, ich hab' dem verdammten Ding nicht den Namen gegeben. Ich weiß nur, dass er an den Schiffen im Halunkeneck vorbei in Richtung Südosten geschwommen ist. Bring diesen übergroßen Goldfisch um und reiß ihm meinen schönen Sin'doreikristall aus dem Bauch.\n\nMach das und wir kommen ins Geschäft.", progress = "Hast du dich verirrt?", completion = "&lt;Harry nimmt Euch den Kristall ab und fängt an, ihn zu liebkosen.&gt;\n\nOh, mein Schatz! Hat dir der große, böse Wal wehgetan? Alles wird gut. Ich werde dich nie wieder aus den Augen lassen!\n\n&lt;Harry blickt zu Euch auf.&gt;\n\nSo, wo waren wir stehen geblieben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11511] = {title = "Der Stab des Sturmfurors", objective = "Beschafft den Stab des Sturmfurors und bringt ihn zu Orfus von Kamagua im Heulenden Fjord.", description = "Diese Artefakte sind verflucht und es wäre purer Wahnsinn, auf die Suche nach ihnen zu gehen, <Volk>. Ich weiß mit Sicherheit, dass ein jeder, der mit einem der Gegenstände in Berührung gekommen ist, entweder verrückt geworden ist oder getötet wurde.\n\nDieser Stab hier zum Beispiel: Das Letzte, was ich gehört habe, war, dass das Schiff, auf dem er sich befand, aufgegeben wurde und man es irgendwo im Osten der Insel der Speere, die sich nördlich von hier befindet, sich selbst überließ.\n\nÜberprüf mal den Frachtraum des Schiffs, wenn du das Ding wirklich willst.\n\nAber was auch immer du machst, bring den Stab bloß nicht wieder hierher! Und mach um Abdul einen großen Bogen! Er wird dir das Herz herausreißen.", progress = "Habt Ihr den Stab?", completion = "Wir müssen alle Artefakte zurückbringen, &lt;Name&gt;. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11512] = {title = "Das gefrorene Herz Isuldofs", objective = "Beschafft das gefrorene Herz Isuldofs und bringt es zu Orfus von Kamagua im Heulenden Fjord.", description = "Einige sagen, dass Jonah nie ganz richtig im Kopf war, doch ich weiß, was wirklich passiert ist. Es war das Herz. Dieses verdammte gefrorene Herz! In dem Moment, als er es aus dem Grab nahm, sah ich, wie es ihn veränderte - konnte sehen, wie das Blut in seinen Adern gefror... Es war damals, als ihn wirklich der Wahnsinn packte.\n\nEr verließ uns, um sich in seiner Höhle auf der Nordseite der Insel zu verkriechen. Das Letzte, was ich gehört habe, war, dass er das Herz in den hinteren Teil seiner Bärenhöhle verbannt hat. Doch das ist nicht genug und es kommt viel zu spät...\n\nIch werde dich eigenhändig umbringen, wenn du das Herz mit hierher nimmst!", progress = "Das... das gefrorene Herz Isuldofs?", completion = "Wir müssen alle Artefakte zurückbringen, &lt;Name&gt;. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11513] = {title = "Manazellen abfangen", objective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", description = "Ich habe mir einen Plan ausgedacht, wie wir an eine Energiequelle kommen können, die stark genug ist, um unser Portal zu erschaffen.\n\nDie Streitmächte der Astralen auf dem Landeplatz von Bash'ir im Nordwesten des Schergrats schmuggeln Manazellen aus der Festung der Stürme heraus und schaffen sie in Kael'thas' Namen zum Sonnenbrunnen.\n\nSie haben die Zellen zwar versteckt, aber es gibt einen Weg, wie Ihr sie finden könnt. Die Astralen tragen Phasenvorrichtung bei sich, mit deren Hilfe Ihr die eingeschmuggelten Waren entdecken könnt.\n\nHütet Euch jedoch vor den Phasenwyrm, den Wächtern der Manazellen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSunwell Portal Quests Flag\n\nIhr bekommt:\n\nVorratspaket der Zerschmetterten Sonne"}
MultiLanguageQuestData['de'][11514] = {title = "Das Sonnenbrunnenportal aufrechterhalten", objective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", description = "Wir müssen den Energiefluss zu unserem Portal aufrechterhalten oder es wird kollabieren. Die versteckten Manazellen der Astralen auf dem Landeplatz von Bash'ir werden den Zweck erfüllen. Der Landeplatz befindet sich weit im Norden auf dem Hochplateau in der nordwestlichen Ecke des Schergrats.\n\nBeschafft Euch eine Phasenvorrichtung von einem der Astralen und benutzt sie, um die Schmuggelwaren zu finden.\n\nNehmt Euch nur vor den Phasenwyrms in Acht, von denen sie die Manazellen bewachen lassen.", progress = "<Name>, wie steht es um die Manazellen, die Ihr heute für uns beschaffen wollt?", completion = "Diese Manazellen werden unser Portal weiterhin mit Energie speisen.\n\nKehrt morgen wieder zurück und ich werde Euch wieder auf Manazellensuche schicken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSunwell Portal Quests Flag\n\nIhr bekommt:\n\nVorratspaket der Zerschmetterten Sonne"}
MultiLanguageQuestData['de'][11515] = {title = "Blut für Blut", objective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe des Teufelstrinkers 4 ausgemergelte Getriebene des Teufelsbluts tötet. Um den Teufelstrinker zu speisen, benötigt Ihr das Dämonenblut von Racheherolden, die sich in der Nähe befinden.", description = "Als Kaels Streitmacht durch das Portal schritt, wurden seine loyalsten Lakaien auf eine entsetzliche Weise belohnt: Sie blieben zurück und soffen tagelang Dämonenblut.\n\nDas Blut hat sie verändert und ihnen neue Kräfte verliehen - es wird jedoch auch ihr Verderben sein.\n\nNehmt Blutproben von anderen Dämonen und benutzt sie, um den Teufelstrinker zu speisen und diese arroganten Narren ihrer Macht zu berauben. Tötet sie, sobald sie geschwächt sind. Kehrt dann zu mir zurück.", progress = "Diese Monster sind eine Schande für unser Volk. Wir müssen sie vernichten, <Name>.", completion = "Narren. Sie haben gelernt, wie man Teufelsenergie entzieht, aber nicht, wie man sie behält.\n\nWir haben Glück, &lt;Name&gt;. Ein erfahrener Streiter des Teufelsbluts hätte gewiss einen beeindruckenden Gegner abgegeben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal des SargerasSiegel des Sonnenzorns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11516] = {title = "Vernichtet den Durchgang", objective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe der zischenden Glut ein lebendiges Leuchtfeuer beschwört und damit so lange glühende Höllenfunken in seiner Nähe tötet, bis es zu einem instabilen lebendigen Leuchtfeuer wird. Kehrt anschließend mit letzterem zum Durchgang der Legion zurück und zerstört ihn.", description = "Wir müssen diesen Durchgang schließen, damit die Legion keine Verstärkung mehr zur Insel von Quel'Danas schicken kann.\n\nNehmt diese Glutstücke, in ihnen befindet sich eine meiner Kreationen: ein lebendiges Leuchtfeuer. Es besitzt so lange eine mächtige zerstörerische Kraft, wie es mit genug Energie versorgt wird.\n\nFindet die Höllenfunken, die in dieser Gegend umherwandern, und erschlagt sie in der Nähe des lebendigen Leuchtfeuers. Mit jedem Male wird das Leuchtfeuer mächtiger - bis es instabil wird.\n\nSobald Ihr das geschafft habt, bringt Ihr das Leuchtfeuer zum Durchgang. Es wird dann wissen, was zu tun ist.", progress = "Ist es vollbracht, <Name>? Kael'thas darf keine weitere Verstärkung durch die Legion erhalten.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Dämonen werden den Durchgang womöglich rechtzeitig reparieren. Na dann werden wir ihn wohl noch einmal in die Luft jagen müssen.", rewards = "Ihr bekommt:\n\nVorratspaket der Zerschmetterten Sonne"}
MultiLanguageQuestData['de'][11517] = {title = "Meldung an Nasuun", objective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", description = "Ich bin so froh, dass Ihr hier seid, <Klasse>! Nun, da wir das Sanktum eingenommen haben, müssen wir uns schleunigst daran machen, ein magisches Portal zu öffnen, das von Shattrath in der Scherbenwelt aus hier her führt.\n\nMein Lehnsherr Exarch Nasuun will mithilfe der Offensive genau das tun. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Öffnung des Portals zu helfen.\n\nReist nach Shattrath und sprecht mit ihm. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11519] = {title = "Der verlorene Schild der Aesiriten", objective = "Sprecht mit Kapitän Ellis an Bord der Gnädigen Schwester.", description = "Wenn du genau hinhörst, kannst du im Nordosten das Feuer von Kanonen vernehmen. Das ist Kapitän Ellis' Schiff, die \"Gnädige Schwester\". Die Sache ist nur, dass Ellis und seine gesamte Crew vor 'nem Monat getötet wurden.\n\n<Harry nickt bestätigend.>\n\nGeisterschiff...\n\nWenn du mehr über den Schild wissen willst, dann ist Ellis genau der richtige Mann dafür.\n\nZwischen dem Halunkeneck und Sorlofs Strand liegt eine Insel, vor der die \"Gnädige Schwester\" ungefähr alle 5 Minuten vor Anker geht, um ihre Crew neu aufzustocken. Denke mal, dass es in der Gegend genug Möglichkeiten dazu geben wird...", progress = nil, completion = "Harr, moi Crew un' ich haben den Schild mitgehen lass'n! Wir woll'n versuchen, ihn dieser nichtsnutzigen, diebischen Landratte namens Sorlof wieder wegzunehmen! Magst du uns dabei helfen, harr?\n\nNu, wie du sehen kannst, werden wir 'ne Skelettcrew haben!\n\n&lt;Kapitän Ellis lacht.&gt;\n\nDas Gnädige Schwesterlein wird 'nen neuen Pulverjungen brauchen, der sich an die großen Wummen drüb'n auf'm Poopdeck setzt. Denkst du, du schaffst das, mein Junge?\n\nHilf moi Crew, Sorlof um die Ecke zu bringen, und wir teilen gemeinsam die Beute! Du kannst den Schild haben und meine Crew und ich kriegen den Rest!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11520] = {title = "Die eigenen Wurzeln entdecken", objective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt.", description = "Grüße, <Volk>.\n\nLeider kann ich Euch nichts anbieten, solange ich keine Reagenzien auf Lager habe.\n\nEines der benötigten Reagenzien ist eine Besonderheit. Es trägt den Namen Messerdornwurzel und ist besonders schwierig zu sammeln.\n\nZum Glück kenne ich da ein Geheimnis...\n\nMan benutzt einfach die Drüsen eines Messerdornschinders, um auf diese Weise einen Hetzer zu kontrollieren, der dann eine Wurzel freilegt.\n\nWenn Ihr die Wurzeln finden wollt, dann müsst Ihr in die Scherbenwelt reisen und von Shattrath aus gen Nordosten fliegen, bis Ihr die Messerdornhöhen erreicht.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVorratspaket der Zerschmetterten Sonne"}
MultiLanguageQuestData['de'][11521] = {title = "Eure Wurzeln wiederentdecken", objective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt.", description = "Ich verfüge im Moment über genug Vorräte. Ich werde jedoch eine Menge Messerdornwurzeln benötigen, um der Nachfrage nachzukommen.\n\nMan benutzt einfach die Drüsen eines Messerdornschinders, um auf diese Weise einen Hetzer zu kontrollieren, der dann eine Wurzel freilegt.\n\nWenn Ihr die Wurzeln finden wollt, dann müsst Ihr in die Scherbenwelt reisen und von Shattrath aus gen Nordosten fliegen, bis Ihr die Messerdornhöhen erreicht.\n\nKehrt zu mir zurück, <Name>, sobald Ihr fünf dieser Wurzeln gesammelt habt.", progress = "Ich bitte Euch, <Name>. Ich bin viel zu beschäftigt, als dass ich mich auf unnützes Geschwätz einlassen würde.\n\nSagt mir Bescheid, sobald Ihr die besagten Wurzeln eingesammelt habt.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.\n\nDanke noch mal für Eure Hilfe!", rewards = "Ihr bekommt:\n\nVorratspaket der Zerschmetterten Sonne"}
MultiLanguageQuestData['de'][11523] = {title = "Fahrt die Barrieren hoch!", objective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und Verschlingern beschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche die Gebäude der Sonnenweiten umgeben.", description = "Wir haben die Kristallbarrieren um das Sanktum erfolgreich reaktiviert, aber warum hier aufhören?\n\nWir werden Verteidigungen um die anderen Gebäude herum aufbauen, aber die Getriebenen sind dickköpfig und stehlen weiterhin Energie von den Kristallbarrieren.\n\nStellt ihnen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt die Überreste, um die Barrieren des Sanktums zu energetisieren, die Sicherheit unseres Vorhabens hängt davon ab.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Die Barrieren erhalten allmählich ihre Kraft zurück. Die Sonnenweiten werden im Handumdrehen uns gehören!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11524] = {title = "Unberechenbares Verhalten", objective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", description = "Wir sind zwar nicht genug, um das Sanktum der Sonnenweiten einzunehmen, aber ich habe einen Plan, mit dem wir den Kampf zu unseren Gunsten wenden können.\n\nDie unkontrollierten Energien des Sonnenbrunnens verursachten Fehlfunktionen bei den Wachposten, die auf dieser Insel patrouillieren. Die Kristallkerne, die ihr Verhalten steuern, sind irreparabel beschädigt.\n\nIch habe neue Kristalle angefertigt, mit denen wir sie unter unsere Kontrolle bringen werden. Steckt die Kristalle ins Innere der besiegten Wachposten. Wir benötigen jede Hilfe, die wir bekommen können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11525] = {title = "Weitere Konvertierungen", objective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", description = "Mein Plan, die beschädigten Kristalle der unberechenbaren Wachposten auszutauschen, hat funktioniert. Wir konnten mit ihrer Hilfe das Sanktum der Sonnenweiten einnehmen.\n\nIch habe neue Kristalle angefertigt, die noch mehr von ihnen unter unsere Kontrolle bringen werden. Platziert diese im Inneren besiegter Wachposten. Wir werden sie dann an verschiedene Orte entsenden, um sie dort einzusetzen, sobald sie konvertiert sind.", progress = "Habt Ihr die Wachposten konvertiert, <Name>?", completion = "Ausgezeichnet. Die konvertierten Wachposten werden uns bei der Sicherung unseres Gebiets helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11526] = {title = "Eine Magistrix wird vermisst", objective = "Benutzt die erbeutete Schriftrolle der Legion in der Nähe des Portals auf dem Platz der Morgenröte. Findet Magistrix Seyla, sobald Ihr auf der anderen Seite des Portals seid.", description = "Wir haben eine unserer Agentinnen ausgesandt, um das Teufelsportal in der Mitte des im Süden gelegenen Platzes der Morgenröte zu untersuchen. Sie ist noch nicht zurückgekehrt.\n\nNehmt diese Schriftrolle - eine der Leichen des Feindes trug sie bei sich. Wir nehmen an, dass sie Euch den Zugang durch das Portal gewährt. Schreitet durch das Portal, spürt Magistrix Seyla auf und helft, so gut Ihr nur könnt.", progress = "Seid still, <Klasse>. Die Truppen der Legion bewachen die Gegend südlich des Tors.", completion = "Es ist lieb von Theris, dass er sich um mich Sorgen macht, aber wir haben hier größere Probleme - viel größere.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11527] = {title = "Meuterei auf der Gnädigen", objective = "Kapitän Ellis an Bord der Gnädigen Schwester im Heulenden Fjord möchte, dass Ihr 5 Schießpulverfässer aus dem Frachtraum des Schiffs besorgt.", description = "Aye, wir haben Schwierigkeiten, <Kamerad/Herzchen>. Moine Kanoniere sind am Meutern! Moi Crew un' ich an Deck werden wohl versuchen müssen, Sorlof in den Hintern zu treten und gleichzeitig mit den meuternden Kanonieren unter Deck fertigzuwerden.\n\nDu wirst ma' nach unten gehen und dich um die meuternden Seehunde kümmern müssen. Nimm auch ihr Schießpulver mit – wirst es für die Wumme drüben auf'm Poopdeck brauch'n.\n\nMit dir an der fetten Wumme wird Sorlof sicher abnibbeln und die Beute freigeben!", progress = "Es wimmelt nur so von meuternden Seehunden und Meeresriesen!", completion = "Hoffen wir mal, dass diese abtrünnigen, schmierigen Ratten ihre Lektion gelernt haben! Nun ist's Zeit, dass du dich an die fette Wumme setzt, Kamerad!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11528] = {title = "Ein Winterhauchgeschenk", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWinterhauchgeschenk"}
MultiLanguageQuestData['de'][11529] = {title = "Sorlofs Beute", objective = "Vernichtet Sorlof mithilfe der Dicken Berta, holt Euch Sorlofs Beute und kehrt mit ihr zu Kapitän Ellis auf der Gnädigen Schwester zurück.", description = "Meine Mannschäft macht die digge Berda für dich feddich, Matrouse. Dat Fräulein hat sich's entweder auf dem Bug oudär auf die andere Saide von die Kuddä gämüdlich gemacht. Na lous, rann an die Kiste und mach dich feuäbereit, wenn Sorlof in Sicht is'!\n\nWenn wiä dann ers' mal die Landradde erwischt haben, wirst du für uns an die Beude rankommen müss'n - wiä können ja nich von dem verdammten Boud runnä! Bring mir die Beude, dann gibt's auch ne kleine Pütz Gold für dich - der Schild...", progress = "Mach hinne, me Jung!", completion = "Geschäft is' Geschäft, me Jung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11530] = {title = "Der Schild der Aesiriten", objective = "Bringt den Schild der Aesiriten zu Orfus von Kamagua. Er befindet sich am Uralten Aufzug im Heulenden Fjord.", description = "Hiä is' der Schild. Ik hoff' mal dat Euch dat Dingens näch' genauso verfluchen wiäd wie es dat mit meiner Mannschäft un' mich gemacht hät. Ihr müssd nou mal nich nach Hause gehn, aber hiä bleiben, dat könnt Ihr nu auch nich'... Ik bin miä sischr, dat es da ein paar Leude geben wiäd, die dat Dingens zurück haben wolln.\n\nNou schaff miä die Schüssl vom Kahn!", progress = "Ihr seid zurückgekehrt!", completion = "Wir müssen alle Artefakte zurückbringen, &lt;Name&gt;. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11531] = {title = "Seltsames Motorteil", objective = "Bringt K. Lee Kleinkram in Telredor das seltsame Motorteil.", description = "Dieses seltsame Motorteil sieht zwar nicht so aus, als würde es in eine Dampfpumpe passen, jedoch scheint alles andere, was Ihr so herumliegen seht, noch weniger dafür geeignet zu sein. Vielleicht weiß K. Lee Kleinkram mehr darüber.", progress = "Du meine Güte! Was habt Ihr denn da, <Name>?", completion = "&lt;K. Lee sieht sich das Motorteil an und wirkt für einen Moment abwesend.&gt;\n\nDas ist mal was echt Besonderes. Hm, schwer zu sagen, woher das Ding kommt. Ich behalte es erst einmal für mich und werde Euch für die Unannehmlichkeiten entschädigen.\n\nAber unter uns gesagt, denke ich, dass es am besten wäre, wenn wir niemandem davon erzählen.\n\n&lt;K. Lee zeigt Euch ihr bestes Lächeln.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11532] = {title = "Ablenkungsmanöver an der Todesschneise", objective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", description = "Die Legion wird uns angreifen, sobald ihre Truppen im Süden nicht mehr gebunden sind. Im Moment hält die Geißel in der Todesschneise ihre Streitkräfte beschäftigt. Jedoch nicht mehr lange.\n\nIch möchte, dass Ihr mit einem Drachenfalken über die Schneise hinwegfliegt und die Dämonen mithilfe dieser arkanen Ladungen dezimiert.\n\nWenn alles gut geht, werden Kaels Lakaien es nicht einmal bemerken, wenn wir die Waffenkammer einnehmen. Sprecht mit Ayren, dem Drachenfalkenmeister im westlichen Teil des Hafens, sobald Ihr bereit seid loszufliegen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11533] = {title = "Die Luftangriffe müssen weitergehen", objective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", description = "Dank unserer Luftangriffe gegen die Truppen der Legion in der Todesschneise konnten wir dem Feind die Waffenkammer abjagen.\n\nTatsächlich lief die Sache so gut, dass wir unsere Luftangriffe gegen sie weiterführen werden. Nehmt diese arkanen Ladungen und verwendet sie gegen ihre Truppen.\n\nSprecht mit Ayren Wolkenbrecher im Hafen der Sonnenweiten, sobald Ihr abflugbereit seid.", progress = "Habt Ihr Eure Mission erfüllt, <Name>?", completion = "Dämonen, die wir heute töten, sind Dämonen, die wir morgen nicht mehr bekämpfen müssen. Weiter so.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11534] = {title = "Meldung an Nasuun", objective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", description = "Ich bin so froh, dass Ihr hier seid, <Klasse>! Nachdem wir dieses Sanktum den Getriebenen weggenommen hatten, beeilten wir uns, ein Portal zu erschaffen, das von Shattrath in der Scherbenwelt aus hierher führt.\n\nMein Lehnsherr Exarch Nasuun leitet die Bemühungen der Offensive, dieses Portal aufrechtzuerhalten. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Energieversorgung des Portals behilflich zu sein.\n\nReist nach Shattrath und sprecht mit Nasuun. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.", progress = nil, completion = "Portanuus hat Euch geschickt? Gut, wir haben keine Zeit zu verlieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11535] = {title = "Vorbereitungen", objective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, 3 Stück Erz aus ihren Truhen zu stehlen.", description = "Versorgungsgüter sind auf dem Weg hierher - wird mir zumindest gesagt.\n\nTrotzdem können wir es uns nicht leisten, hier zu warten und zu hoffen, dass Hilfe kommen wird, bevor die Offensive zum Stillstand kommt. Wir müssen das Beste aus dem machen, was uns gegeben ist.\n\nFür meinen Teil benötige ich Erz, um daraus einen Amboss zu fertigen und anzufangen, unsere Rüstungen und Waffen aufzubessern.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt.\n\nWenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11536] = {title = "Hört jetzt nicht auf!", objective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, um 3 Stück Erz aus ihren Truhen zu stehlen.", description = "Da wir jetzt einen Amboss haben, kann ich so richtig anfangen zu arbeiten.\n\nIch werde das Eisenerz der Dunkelflossen immer gut gebrauchen können, egal wie viele Versorgungsgüter wir bekommen. Wenn wir hier gewinnen wollen, dann benötigen wir regelmäßige Waffen- und Rüstungslieferungen.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt. Wenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", progress = "Habt Ihr das Erz, nach dem ich Euch gefragt habe, eingesammelt?", completion = "Ausgezeichnet! Damit werde ich Rüstungen und Waffen für unsere Soldaten herstellen können.\n\nEure Hilfe ist Gold wert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11537] = {title = "Die Schlacht muss weitergehen", objective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", description = "Wir müssen zusehen, dass wir die Armeen der Legion weiterhin besiegen und entmutigen.\n\nDie Abgesandten des Hasses sind Stoßtruppen der Legion, die immer dann eingesetzt werden, wenn ihre Streitkräfte erhebliche Verluste zu verzeichnen haben. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen auf dem Platz der Morgenröte. Tötet den Abgesandten, sobald Ihr ihm begegnet, und spießt anschließend seinen Körper auf.", progress = "Wart Ihr erfolgreich, <Name>?", completion = "Euer Engagement ist beispielhaft, &lt;Name&gt;. Wir werden den Streitkräften der Brennenden Legion zeigen, wozu wir im Stande sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11538] = {title = "Die Schlacht um die Waffenkammer der Sonnenweiten", objective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte oder der Waffenkammer der Sonnenweiten niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", description = "Die Brennende Legion hält die Waffenkammer der Sonnenweiten - sie ist von taktischer Wichtigkeit für unseren Einsatz. Solange ihre Moral hoch bleibt, werden wir das Gebäude ihrem Griff nicht entziehen können.\n\nDie Abgesandten des Hasses sind Elitestoßtruppen der Legion, die als Verstärkung für taktisch wichtige Stellungen eingesetzt werden. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen der Legion. Tötet den Abgesandten, sobald Ihr ihm begegnet, und durchspießt seinen Körper.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11539] = {title = "Den Hafen einnehmen", objective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Schützen der Dämmerklingen niederstreckt.", description = "Die Armee der Dämmerklingen - sie gehört zu Kaels Elitestreitkräften - wurde im Hafen der Sonnenweiten und in Morgenstern stationiert.\n\nDer Hafen ist von höchster strategischer Bedeutung für unsere Pläne. Je mehr Dämmerklingen Ihr also beseitigt, umso mehr helft Ihr uns damit. Kael'thas wird den Tag bereuen, als er sich von seinem Volk abwandte und sich mit der Brennenden Legion einließ.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11540] = {title = "Vernichtet die Dämmerklingen", objective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Bogenschützen der Dämmerklingen niederstreckt.", description = "Wir haben die Armee der Dämmerklingen aus dem Hafen der Sonnenweiten vertrieben. Die Sonnenweiten gehören nun uns. Doch... bin ich nicht vollends zufrieden.\n\nIch möchte, dass Ihr Euch ins westlich gelegene Morgenstern begebt und jeden überlebenden Anhänger der Dämmerklingen erschlagt, der Euch über den Weg läuft. Sie besiegelten ihr Schicksal, als sie Kael an diesen Ort folgten.", progress = nil, completion = "Was geht nur durch Prinz Kael'thas Sonnenwanderers Kopf, wenn er von den Niederlagen seiner Armeen erfährt?\n\nIst es Verzweiflung? Hilflosigkeit? Furcht?\n\nIch hoffe doch, dass dem so ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11541] = {title = "Belästigung an der Küste der Grünkiemen", objective = "Kapitänin Valindria möchte, dass Ihr 10 Grünkiemensklaven befreit und zu ihr zurückkehrt, sobald Ihr damit fertig seid. Sie befindet sich auf der 'Silbermonds Stolz' im Hafen der Sonnenweiten.", description = "Die Naga haben die Küste der Grünkiemen im Südosten erobert. Ihre Frauen, die Sirenen der Dunkelflossen, haben die Murlocs bezaubert und zu ihren Sklaven gemacht.\n\nEs ist meine Pflicht, dafür zu sorgen, dass das, was auch immer die Naga dort treiben, gestört wird. Hier kommt Ihr ins Spiel.\n\n<Klasse>, ich möchte, dass Ihr den weiblichen Naga die Kontrollkugeln abnehmt und sie auf den Boden in der Nähe der Grünkiemensklaven werft, damit die Kugel zerspringt und die Murlocs befreit werden.\n\nIch nehme an, dass die Murlocs erbost sein werden und sich gegen ihre Meister wenden werden.", progress = nil, completion = "Das reicht für heute. Zeit und Regelmäßigkeit ist hier der Schlüssel zum Erfolg. Wenn wir sie zu sehr belästigten, würden sie ihre Aufmerksamkeit direkt auf uns richten - und das wollen wir nicht.\n\nKommt morgen wieder zurück, damit wir für ein wenig mehr Belästigung sorgen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11542] = {title = "Haltet die Verstärkung auf", objective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet. Fliegt dann über die Unterstützungsflotte der Dämmerklingen hinweg und benutzt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", description = "Wir stoßen vor und nehmen den Hafen als Nächstes ein, um unsere Kontrolle über die Sonnenweiten zu festigen. Leider ist eine Flotte Schiffe mit Reservisten der Dämmerklingen auf dem Weg dorthin, um Kaels Truppen zu verstärken.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie sich nicht großartig verteidigen können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11543] = {title = "Den Feind vom Leibe halten", objective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet und über die Flotte mit Verstärkungstruppen der Dämmerklingen hinwegfliegt. Benutzt solange Ihr fliegt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", description = "Wir konnten die Sonnenweiten vollständig einnehmen. Leider hat sich eine Flotte Schiffe mit Reservisten der Dämmerklingen auf den Weg gemacht, um den Hafen einzunehmen.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie keine wirkliche Gegenwehr starten können.", progress = "Konntet Ihr Eure Aufgabe erfüllen, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Es sollte eine Weile dauern, bis irgendwelche Verstärkungstruppen im Hafen ankommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11544] = {title = "Waffen von Ata'mal", objective = "Schmiedin Hauthaa möchte, dass Ihr 5 Stück gereinigtes Metall von Ata'mal herstellt. Um dies zu tun, müsst Ihr Waffen von Ata'mal auf ihrem Amboss in der Waffenkammer der Sonnenweiten auf der Insel von Quel'Danas zerlegen.", description = "Die Terrasse von Ata'mal im Osten des Schattenmondtals ist den Draenei heilig. Derzeit ist sie jedoch von Höllenorcs besetzt, die das spezielle Erz, das dort vorkommt, geschürft und daraus Waffen und Rüstungen der Verderbnis hergestellt haben.\n\nIch brauche die Waffen, um eine Legierung mit Nagaerz herzustellen. Unsere Anachoreten haben meinen Amboss mit der Fähigkeit gesegnet, sie zu reinigen.\n\nIhr könnt die Waffen an den Auserwählten, Tötern und Dunkelwirkern des Schattenmondklans finden. Bringt sie hierher, zerlegt und reinigt sie auf meinem Amboss und übergebt mir das gereinigte Resultat.", progress = "<Klasse>, ich brauche so viel gereinigtes Metall von Ata'mal, wie nur möglich.", completion = "Ich danke Euch, Freund. Nun werde ich mehr von der speziellen Legierung herstellen können, die zur Herstellung der Waffen und Rüstungen unserer Streitkräfte verwendet wird.\n\nAußerdem habe ich hier ein wenig von dem Extrakt, das bei der Herstellung übrig geblieben ist. Ihr werdet es wahrscheinlich sehr nützlich für Eure Waffen finden. Wählt bitte das aus, was Euren Zwecken am besten dient.\n\nKehrt zu mir am morgigen Tage zurück. Ich werde mit Sicherheit mehr Waffen benötigen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnete WaffenbeschichtungRechtschaffene Waffenbeschichtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11545] = {title = "Eine milde Gabe", objective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", description = "Wir haben die Sonnenweiten dem Feind entrissen - der endgültige Sieg steht kurz bevor. Der Preis war hoch und viele tapfere Kämpfer gaben dafür ihr Leben.\n\nMein Ziel ist es, sicherzustellen, dass die Gefallenen nicht vergessen werden. Also bitte ich Euch, dass Ihr einen Moment innehaltet, um über eine Spende für eine Gedenkstätte nachzudenken. Alles übrig gebliebene Gold wird an die Witwen und Waisen der Gefallenen gehen.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11546] = {title = "Geschäft geöffnet", objective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr 5 Blutbeeren von den Büschen auf Quel'Danas sammelt.", description = "Willkommen, <Name>.\n\nEs gibt mehrere Möglichkeiten, wie ich Euch bei Eurem Unterfangen behilflich sein kann.\n\nIch habe zum Beispiel vor Kurzem ein Rezept für ein einzigartiges Elixier entdeckt.\n\nDie Blutbeere ist in vielen Regionen Azeroths ein wildes Gewächs und wurde sehr lange als lästig empfunden. Ich habe jedoch herausgefunden, dass die Pflanze, wenn sie den Kräften des Sonnenbrunnens ausgesetzt wird, besondere Eigenschaften annimmt, die destilliert und anschließend getrunken werden können, um die eigenen Fähigkeiten zu verstärken.\n\nGeht zu den Büschen in der Nähe und bringt mir eine Probe - dann werdet Ihr sehen, was ich meine.", progress = "Habt Ihr diese Beeren schon gesammelt?", completion = "Ausgezeichnet, &lt;Name&gt;.\n\nIch hoffe, dass Euch dies bei Eurem Unterfangen helfen wird.", rewards = "Ihr bekommt:\n\nBlutbeerenelixier"}
MultiLanguageQuestData['de'][11547] = {title = "Kenne deine Leylinien", objective = "Astromant Darnarian im Sanktum der Sonnenweiten möchte, dass Ihr den Kristall des Astromanten am Blutkristall, am Portal auf dem Platz der Morgenröte und in der Nähe des Nagaschreins an der Küste der Grünkiemen benutzt.", description = "Trittbrettfahrer!\n\nAlle wollen sie ihre Wünsche sofort erfüllt haben, ohne auch nur einen Gedanken daran zu verschwenden, wie viel Anstrengung selbst im einfachsten Portal steckt.\n\nVielleicht wird Euch etwas Aufklärung ein wenig mehr Dankbarkeit für meine unermüdlichen Anstrengungen beibringen.\n\nNehmt diesen Kristall und stimmt ihn auf den Blutkristall im Westen ab. Dieselbe Prozedur müsst Ihr dann am Portal auf dem Platz der Morgenröte im Süden und in der Nähe des Nagaschreins an der Küste der Grünkiemen im Südosten wiederholen.\n\nVielleicht werdet Ihr dann Eure heiß geliebten Translokationen mehr schätzen...", progress = "Habt Ihr den Kristall schon ausgerichtet, <Klasse>?", completion = "Ja, ja. Sehen wir uns das doch einmal an.\n\nAlles scheint in Ordnung zu sein. Also gut. Hier ist Euer Translokator.\n\nWenn auch nur ein Teil Eurer Messungen fehlerhaft ist, dann ist es unvorhersehbar, wo genau Ihr landen werdet. Aber dann wäret Ihr wohlgemerkt selber schuld.", rewards = "Ihr bekommt:\n\nDarnarians Rolle der Teleportation"}
MultiLanguageQuestData['de'][11548] = {title = "Eure weitere Unterstützung", objective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", description = "Wir haben den Gefallenen zu Ehren ein Denkmal errichtet - ein kleiner Trost für die Familien, die ihre Angehörigen verloren haben.\n\nIch werde damit beginnen, Spenden zu sammeln, um die Waisen und Ehepartner unserer Kriegshelden zu unterstützen. Falls Ihr eine kleine Spende machen könntet, würdet Ihr viel dazu beitragen.", progress = "Wollt Ihr eine Spende machen?", completion = "Ihr seid eine tugendhafte Seele, &lt;Name&gt;. In Zeiten des Krieges und Triumphs werden die Gefallenen nur zu leicht vergessen. Die Freunde und Familien der Toten danken Euch.", rewards = nil}
MultiLanguageQuestData['de'][11549] = {title = "Ein großmütiger Spender", objective = "Anachoret Kairthos möchte, dass Ihr 1000 Gold spendet, um Anachoretin Ayuri in ihrem Vorhaben zu unterstützen. Wenn Ihr die Aufgabe abschließen solltet, werdet Ihr den Namen \"<Name> der Zerschmetterten Sonne\" tragen.", description = "Ihr habt viel für uns getan, <Name>. Wir sind Euch für Eure Unterstützung sehr dankbar.\n\nIhr habt vielleicht bemerkt, wie sich die Anachoretin Ayuri dort draußen bemüht. Sie hat ein großes Herz und ist sehr überzeugend, aber die Spenden kommen nicht gerade an das heran, was sie sich erhofft hatte.\n\nFalls Ihr eine große Spende machen würdet, um ihre Sache zu unterstützen, werde ich mich persönlich dafür stark machen, dass Eure Taten in diesem Krieg weit und breit bekannt sein werden. Was sagt Ihr dazu?", progress = "Seid Ihr bereit dazu, den Beitrag zu leisten?", completion = "Ihr seid wahrhaftig eine großzügige Person und ein würdiger Verbündeter. Von nun an sollt Ihr als \"&lt;Name&gt; der Zerschmetterten Sonne\" bekannt sein. All diejenigen, die hier kämpften, werden von Euren Taten wissen.", rewards = nil}
MultiLanguageQuestData['de'][11550] = {title = "Der Betrüger betritt die Bühne...", objective = "Meldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas, nördlich von Quel'Thalas.\n\nSprecht mit Flugmeistern in Eisenschmiede und Silbermond, sie werden Euch dorthin bringen.", description = "Kael'thas' finstere Pläne konnten unseren größten Anstrengungen zum Trotz ausgeführt werden. Der Sonnenbrunnen wurde wieder entfacht, um die Ankunft des Betrügers vorzubereiten.\n\nDer Gegenstand, der vor mir steht und über dem A'dal schwebt, repräsentiert den derzeitigen Status der Verteidigungsanlagen des Sonnenbrunnens. Es wurden riesige Barrieren errichtet, um unsere Angriffe auf die inneren Hallen zu behindern. Wenn unsere Welt jemals Hilfe benötigen sollte, dann wäre es jetzt.\n\nMeldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas nördlich von Quel'Thalas.", progress = nil, completion = "Kil'jaeden stürzt sich mit der geballten Kraft der Brennenden Legion auf diese Welt. Sollte er beschworen werden, wird unsere Welt abermals im Chaos versinken. Eure Unterstützung auf der Insel von Quel'Danas ist entscheidend für unseren Sieg über die Legion.\n\nUnsere Magier arbeiten daran, die Barrieren zu durchbrechen, die uns den Zugang zum Sonnenbrunnen versperren. Leistet Euren Beitrag im Kampf gegen die Streitkräfte der Legion, indem Ihr der Offensive der Zerschmetterten Sonne helft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11554] = {title = "Ein Freund an der Front", objective = "Euer Beitrag zur Offensive wurde nicht übersehen, <Name>. Die vereinten Kräfte der Aldor und Seher bedanken sich bei Euch.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVorratspaket der AldorVorratspaket der Seher"}
MultiLanguageQuestData['de'][11555] = {title = "Eure Verbündeten wollen Euer Wohl", objective = "Ihr beweist Euch weiterhin als würdig in dieser überaus wichtigen Schlacht, <Name>. Bitte nehmt dies als Zeichen unserer fortwährenden Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVorratspaket der AldorVorratspaket der Seher"}
MultiLanguageQuestData['de'][11556] = {title = "Auf dem Schlachtfeld zollt man Euch Respekt", objective = "Ohne Euch hätten wir nie so weit kommen können, <Name>. Die vereinten Kräfte der Aldor und Seher sind nicht genug, um die Legion und Kael zu vernichten. Wir sind froh darüber, Verbündete von Eurem Kaliber unter uns zu haben.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVorratspaket der AldorVorratspaket der Seher"}
MultiLanguageQuestData['de'][11557] = {title = "Alle Kämpfer begegnen Euch mit Ehrfurcht", objective = "Ihr seid einer unserer allerbesten Kämpfer, <Name>. In unserer Armee wird man Euren Namen nicht so schnell vergessen.\n\nIm Namen unserer Streitkräfte bitte ich Euch, dieses kleine Geschenk entgegenzunehmen.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVorratspaket der AldorVorratspaket der Seher"}
MultiLanguageQuestData['de'][11558] = {title = "Gefährliche Liebschaft", objective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt.", description = "Diese Liebesepidemie hat etwas Unnatürliches an sich. Sie ist abscheulich und hat sie erst einmal unsere Verteidigung geschwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits so viele unserer Leute von diesem lächerlichen Verhalten befallen sind. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser Dummheit befallen wurde.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", rewards = nil}
MultiLanguageQuestData['de'][11559] = {title = "Winterflossenhandel", objective = "Sammelt 5 Winterflossenmuscheln und liefert sie bei Ahlurglgr ab. Dieser befindet sich in der Zuflucht der Winterflossen.", description = "Da Ihr Euch nun mit den Winterflossen verständigen könnt, ist es an der Zeit, Euch einmal vorzustellen. Handel mit ihnen zu treiben, ist mit die beste Art und Weise, dies zu tun.\n\nMurlocs schätzen Muscheln höher als alles andere und Ihr einziger überlebender Händler nennt sich Ahlurglgr. An Eurer Stelle würde ich also eine Handvoll Winterflossenmuscheln sammeln und sie ihm zum Geschenk machen.\n\nDie Muscheln liegen überall im Graben verstreut, können jedoch auch jenseits des Grabens, im Dorf und den Höhlen der Winterflossen, gefunden werden.", progress = "Was ist das denn? Wer seid Ihr?\n\nIhr seid ein - ein <Volk>! Wie kommt es, dass Ihr unsere Sprache sprechen könnt?", completion = "Die sind für mich? Ist das einer Eurer Tricks, &lt;Volk&gt;? Nein?\n\nNa dann danke ich Euch! Seid stets willkommen, wenn Ihr noch mehr Muscheln habt und mit mir handeln wollt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11560] = {title = "Oh neeiin, die Kaulquappen!", objective = "König Mrgl-Mrgl möchte, dass Ihr 20 Kaulquappen der Winterflossen befreit und anschließend zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen.", description = "Wie gut, dass Ihr wieder da seid!\n\nAls der Erdrutsch in der Nähe des Dorfes auf der anderen Seite des Wassers die Höhlen freilegte, kam ein gehässiger Hummerstrok namens Claximus aus ihnen herausgekrochen und stahl sich mit den Kaulquappen der Winterflossen davon.\n\nIrgendetwas geschah mit den Murlocs, die ihm in die Höhlen nachfolgten, denn als sie wieder herauskamen, waren sie unter seiner Kontrolle.\n\n<Klasse>, Ihr müsst auf die andere Seite schwimmen, im Dorf und in den Höhlen nach den Kaulquappen der Winterflossen suchen und sie in Sicherheit bringen.\n\nDie Zukunft des Winterflossenstammes liegt in Euren Händen!", progress = nil, completion = "Egal was passiert, die Murlocs der Winterflossen haben eine sichere Zukunft vor sich.\n\nFür Eure Selbstlosigkeit habt Ihr Lob und eine Belohnung verdient, &lt;Name&gt;!", rewards = "HummerstrokschnitzlerSchulterstücke des UntergangsAuf Euch wartet eine dieser Belohnungen:\n\nGezeitensegenSchimmerndes Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11561] = {title = "Die da!", objective = "Brglmurgl in der Zuflucht der Winterflossen möchte, dass Ihr insgesamt 15 Murlocs der Winterflossen tötet, egal ob Krieger, Orakel oder Küstenschläger.", description = "Unsere Brüder und Schwestern auf der anderen Seite des Wassers sind zu unseren Todfeinden geworden. Sie haben unsere Kaulquappen entführt, uns aus unserem Dorf vertrieben und mehr von meinem Volk ermordet, als ich zählen kann.\n\nErweist Euch als nützlich, <Volk>! Schwimmt auf die andere Seite des Grabens und metzelt sie nieder!\n\nErst dann wird es in Frage kommen, Euch hier zu akzeptieren - trotz des Wohlwollens, das Euch der neue König gezeigt hat. Und solltet Ihr es versäumen, dann könnt Ihr genauso gut jetzt gehen und nie mehr wiederkehren!", progress = nil, completion = "Das freut mich. Ich kann den kupfernen Geruch ihres Blutes an Euren Händen riechen.\n\nDas ist ein guter Anfang, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11562] = {title = "Mein Putzmurloc erpresst mich", objective = "König Mrgl-Mrgl möchte, dass Ihr mit Mrmrglmr sprecht. Er befindet sich im nordwestlichen Teil der Zuflucht der Winterflossen.", description = "Ich muss Euch etwas Peinliches gestehen: Ich werde erpresst!\n\nMrmrglmr hatte sich damit einverstanden erklärt, ein paar Dinge von mir zu putzen, und dabei mein Ersatzmurlockostüm in die Finger bekommen. Er hat mir damit gedroht, den anderen Murlocs zu zeigen, wer ich wirklich bin.\n\nIch muss Euch nicht erklären, wie katastrophal das für mich wäre! Abgesehen davon habe ich mir einen Plan ausgedacht, zu dessen Umsetzung wir das Kostüm zurückbekommen müssen.\n\nIch bitte Euch, <Name>, geht zu Mrmrglmr und erledigt, was auch immer er von Euch verlangt. Er befindet sich nördlich von hier, auf der anderen Seite der Zuflucht.", progress = nil, completion = "Ah, Ihr müsst also König Mrgl-Mrgls Speichellecker sein. Ich nehme mal an, dass der Nachtelf Euch hierher geschickt hat, um mich zu beschwichtigen?\n\nGut, ich hab' genau die richtige Arbeit für jemanden, der so mächtig ist wie Ihr!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11563] = {title = "Grmmurggll Mrllggrl Glrggl!!!", objective = "Mrmrglmr will, dass Ihr mit Glrggls Kopf zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen.", description = "Wenn Eure erbärmlichen kleinen Augen für etwas nützlich wären, könntet Ihr sehen, dass wir von den Orcas in der nördlich gelegenen Bucht abgeschlachtet werden!\n\nWenn Euer geschätzter Nachtelfenkönig sein Ersatzkostüm wirklich zurückhaben will, werdet Ihr mir bestimmt einen Gefallen tun und mir den Kopf des Königs der Orcas bringen - Glrggl: Er trotzt den Gezeiten, dem Schicksal und schwimmt... Vernichter der Hoffnung, Hoffnung auf Leben... Welle um Welle: Todesgesänge...!\n\nMacht schnell, <Volk>, Murlocs der Winterflossen verlieren ihr Leben, während wir hier reden und Zeit vergeuden!", progress = "Wenn Ihr Glrggls Kopf nicht dabei habt, dann verschwendet bloß nicht meine Zeit!", completion = "Nicht übel!\n\nDa der König der Orcas nun tot ist, werden die Wale untereinander um die Herrschaft kämpfen und uns weniger angreifen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11564] = {title = "Deftiger Orcaeintopf", objective = "Hackebeil Bmurglbrm hat Euch damit beauftragt, 7 Einheiten saftigen Orcatran zu beschaffen. Bringt sie anschließend zu ihm in die Zuflucht der Winterflossen.", description = "Man sagt mir, <Volk>, dass Ihr womöglich hinter Glrggl, dem König der Orcas, her seid.\n\nDas ist ja alles schön und gut, aber wenn Ihr jemals den Eintopf schmecken wollt, für den es sich zu leben lohnt, dann werdet Ihr mir den saftigen Tran der Orcas aus der Glimmerbucht bringen müssen.\n\nBeeilt Euch... Ich hab' noch eine Menge an dem Wal hier herumzuschneiden, wenn Ihr für Eure Mühen belohnt werden wollt.", progress = "Habt Ihr genug des benötigten Orcatrans mitgebracht?", completion = "Ah, ja, das dürfte reichen.\n\nStellt die Dinger einfach irgendwo hin. Letzte Nacht ist ein wenig Eintopf übrig geblieben - könnt ein wenig davon haben.", rewards = "Ihr bekommt:\n\nDeftiger OrcaeintopfAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11565] = {title = "Das Ersatzkostüm", objective = "Bringt König Mrgl-Mrgls Ersatzkostüm zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen.", description = "Ausgezeichnet. Das Geheimnis Eures Königs wird von mir sicher verwahrt, solange er uns im Kampf gegen unsere Feinde unterstützt.\n\nHier, bringt dies zu ihm. Ich hab es sauber gemacht, obwohl ich keine Ahnung hab, wieso er eine zweite Verkleidung braucht.\n\nVielleicht hat er etwas mit Euch vor?", progress = "Habt Ihr das Ersatzkostüm dabei, <Name>?", completion = "&lt;Als er das Ersatzkostüm sieht, reibt er seine kostümierten Gliedmaßen aneinander.&gt;\n\nSehr gut gemacht. Nun, zurück zu den wirklich dringlichen Angelegenheiten. Ich habe eine Aufgabe von äußerster Wichtigkeit für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11566] = {title = "Ergebt Euch... nicht!", objective = "König Mrgl-Mrgl in der Zuflucht der Winterflossen möchte, dass Ihr ihm die Klaue von Claximus bringt.", description = "Die Zeit ist gekommen, um dieser schrecklichen Situation ein Ende zu bereiten, <Name>. Claximus muss sterben, wenn die Murlocs der Winterflossen eine Chance auf eine bessere Zukunft haben sollen!\n\nIch möchte, dass Ihr diesen Murlocanzug nehmt - meinen Ersatz - und in die Höhlen der Winterflossen geht. Tut so, als würdet Ihr Euch ergeben wollen, schwingt die weiße Fahne und die Murlocs werden Euch nicht angreifen.\n\nIhr findet Claximus in der südwestlichsten Ecke der Höhlen. Kümmert Euch um ihn, sobald Ihr nahe genug herangekommen seid, und bringt mir eine seiner Klauen als Beweis dafür, dass die gräuliche Tat vollbracht ist.", progress = "Ist es vollbracht, <Klasse>? Ist Claximus tot?", completion = "Bedauerlich, aber notwendig. Ich werde dann mal die Klaue an mich nehmen, wenn Ihr sie noch habt, &lt;Name&gt;.\n\nDanke für all Eure Hilfe. Da Claximus nun besiegt ist, können wir vielleicht die verbliebenen Murlocs wieder vereinigen und diese Höhlen verschließen.\n\nIch bitte Euch, mein Freund, nehmt dies... Es ist das Mindeste, was ich für Euch angesichts Eurer Hilfe tun kann!", rewards = "Oculus der verlorenen SeeDurchnässte LederschulterstückeBeinlinge mit rostigen MaschenSumpfstrokplattenhandschuheIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11567] = {title = "Die uralte Rüstung der Kvaldir", objective = "Bergt die uralte Rüstung der Kvaldir und bringt sie zu Orfus von Kamagua im Heulenden Fjord.", description = "Ich war auf dem Schiff, das die Rüstung hierher bringen sollte. Wir hatten das Schiff gerade erst bestiegen und uns auf den Weg gemacht, als wir von einem Zerstörer der Verlassenen angegriffen wurden.\n\nWir wurden geentert. Sie nahmen das ganze Beutegut an sich und übergaben unser Schiff den Fluten...\n\nDas war das Letzte, was ich je von der Rüstung gesehen habe. Wenn du willst, kannst du mit meinem Bomber vom Halunkeneck zur gefürchteten Insel fliegen, wo der Zerstörer vor Anker liegt. Red' mal draußen mit meiner Frau Alanya - sie ist dein Ticket zur Insel.\n\nUnd falls du das Ding finden solltest, dann wage bloß nicht, es hierher zu bringen!", progress = "Habt Ihr die Rüstung gefunden?", completion = "Wir müssen alle Artefakte zurückbringen, &lt;Name&gt;. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11568] = {title = "Wieder zur Ruhe kommen lassen", objective = "Verwendet das Bündel mit Vrykulartefakten bei den geplünderten Grabhügeln des Schildhügels und legt das gefrorene Herz Isuldofs, den Schild der Aesiriten, den Stab des Sturmfurors und die uralte Rüstung der Kvaldir wieder zurück.\n\nKehrt zu Orfus von Kamagua am Uralten Aufzug zurück, falls Ihr erfolgreich sein solltet.", description = "<Orfus reicht Euch einen Ranzen.>\n\nIn diesem Ranzen befinden sich die Artefakte, die Ihr zurückgebracht habt. Findet die Gräber des Schildhügels, die sich weit gen Südosten befinden und aus denen die Gegenstände ursprünglich gestohlen wurden, und legt die Artefakte wieder hinein. Ich hoffe, dass diese Geste den Geistern, die derzeit unsere Jagdgebiete heimsuchen, ein Zeichen sein und sie beschwichtigen wird.\n\nSeid stark, <Name>...", progress = nil, completion = "Schlimme Neuigkeiten, &lt;Name&gt;. Mein Volk ist in Gefahr und muss gewarnt werden. Diese entarteten Seefahrer werden keine Gnade für die Kalu'ak übrig haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11569] = {title = "Schlüsselmeister Urmgrgl", objective = "Glrglrglr in den Höhlen der Winterflossen möchte, dass Ihr Urmgrgls Schlüssel beschafft.", description = "Ich muss aus diesen Höhlen raus! Magisches Zeugs sickert durch die Wände und wirkt sich irgendwie auf unsere Gedanken aus. Es scheint von Kaltarra über uns zu kommen.\n\nIch will nicht kontrolliert werden, will nicht das Schicksal der anderen teilen!\n\nSchlüsselmeister Urmgrgl hält sich weiter unten in der Höhle gen Süden auf. Er trägt den Schlüssel für meinen Käfig bei sich. Bringt den Schlüssel hierher, damit wir meinen Käfig aufsperren und von hier verschwinden können.\n\nBeeilt Euch!", progress = "Habt Ihr den Schlüssel?\n\nNein, mir sind die anderen egal. Ich will hier nur raus!", completion = "Schnell, gebt her!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11570] = {title = "Flucht aus den Höhlen der Winterflossen", objective = "Eskortiert Lurgglbr, bis er in Sicherheit ist, und überbringt anschließend König Mrgl-Mrgl in der Zuflucht der Winterflossen die guten Neuigkeiten.", description = "Das Schloss an meinem Käfig sieht zwar nicht gerade fest aus, doch fliehen würde ich ohne Unterstützung nicht - so dumm bin ich nicht.\n\nWerdet Ihr mir helfen, heil aus diesen Höhlen herauszukommen? Wir haben keine Zeit zu verlieren, <Volk>.\n\nLasst den König bitte wissen, dass es mir gut geht, wenn Ihr zurück zur Zuflucht gelangt. Er wird Euch sicherlich belohnen.", progress = nil, completion = "Das sind wundervolle Neuigkeiten! Und Ihr meint, Lurgglbr hätte entdeckt, dass die Ausströmungen aus den Höhlen diesen Wahnsinn verursachen?\n\nDas kann nur bedeuten, dass die Magie aus Kaltarra stärker wird. Der Nexuskrieg... die Schlacht zwischen dem blauen Drachenschwarm und den restlichen Drachen weitet sich aus.\n\nBald werden wir uns dem nicht mehr entziehen können!", rewards = "FischaugenpiekserMrgls KlingeSzepter der WinterflossenSchimmernder OrcazahnAmphibische SpeerharpuneMuschelzerkracherIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11571] = {title = "Lernen, wie man kommuniziert", objective = "König Mrgl-Mrgl hat Euch eine Muschel gegeben, die Ihr bei Verbrühers Überresten benutzen sollt. Kehrt mit der gefüllten Muschel des Königs zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen.", description = "Um zu helfen, müsst Ihr Euch zuerst mit dem Dialekt der Winterflossen vertraut machen. Dazu werden wir uns die Kräfte von Natur und Magie zu Nutze machen.\n\nNehmt diese leere Muschel. Am Grunde des Wassergrabens lebt Verbrüher, Elementar des Zorns von Wasser und Luft.\n\nBenutzt die Muschel bei seinen Überresten, um seinen magischen Dampf einzufangen, sobald er besiegt ist. Kehrt mit der vollen Muschel zu mir zurück und ich werde Euch mit dem Wissen der Winterflossenzunge erfüllen.\n\nGlücklicherweise hat mir ein Freund einen Wasseratmungszauber beigebracht, den ich auf Euch wirken werde.", progress = "Konntet Ihr die Muschel mit Verbrühers Dampf füllen?", completion = "Nun werde ich Verbrühers Essenz dazu benutzen können, Euch meine Sprachkenntnisse der Winterflossen zu vermitteln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11572] = {title = "Rückkehr zu Atuik", objective = "Überbringt Urahn Atuik in Kamagua die schlechten Nachrichten.", description = "Kehrt zu Urahn Atuik nach Kamagua zurück. Er und der Rest meiner Leute müssen vor dem drohenden Unheil aus dem Meer gewarnt werden.\n\n<Orfus zittert vor Angst.>\n\nMit dem Uralten Aufzug könnt Ihr zu ihm gelangen. Bitte beeilt Euch!", progress = nil, completion = "Die Kalu'ak danken Euch für alles, was Ihr getan habt, &lt;Name&gt;. Wir müssen uns jetzt auf den Kampf vorbereiten und unsere Brüder und Schwestern auf der anderen Seite des Meeres vorwarnen.\n\nIch hoffe, dass es noch nicht zu spät ist...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHorn des HeroldsHeiler des kommenden MorgensZorn des aufziehenden Sturms\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11573] = {title = "Orfus der Kamagua", objective = "Sucht am Uralten Aufzug im Heulenden Fjord nach Orfus von Kamagua.", description = "Seid gegrüßt, <Reisender/Reisende>. Ich bin Lunkhauer von den Kalu'ak - oder Tuskarr, wie es in Eurer Sprache heißt. Mein Gefährte und ich wurden erst kürzlich ausgeschickt, um die seltsamen Vorgänge entlang einem unserer Jagdpfade zu untersuchen. Doch als wir auf den Friedhof namens Schildhügel zugingen, wurden wir von den Untoten angegriffen. Ich hatte Glück, es bis zu diesem Lager zu schaffen, jedoch weiß ich nicht, was mit Orfus geschehen ist.\n\nVom Uralten Aufzug aus, südöstlich von hier entlang der Klippen, gingen wir getrennte Wege. Werdet Ihr einmal nachsehen, ob alles mit ihm in Ordnung ist?", progress = nil, completion = "Lunkhauer ist am Leben? Immerhin gibt es heute ein paar gute Nachrichten zu hören...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11574] = {title = "Zu knapp für meinen Geschmack", objective = "Endorah möchte, dass Ihr Euch auf das Bernsteinflöz nördlich der Kriegshymnenfeste begebt und ihren Rettern ihren Dank aussprecht.", description = "Ich habe ihnen alles erzählt, woran ich mich erinnern kann. Wieso glauben sie mir nicht? Ich habe in der Nähe des Abgrundes nach Kräutern gesucht, als sie wie aus dem Nichts auftauchten - dunkle Magier mit magischen Biestern. Ich war umzingelt!\n\nÜber mir erschien ein riesiger magischer Würfel. Er öffnete sich und sog mich einfach auf. Ich schwöre, es ist die Wahrheit!\n\nGenau als er im Begriff war, sich zu schließen, schossen meine Retter auf den Rücken roter Drachen im Sturzflug vom Himmel. Es war atemberaubend! Meine Entführer wurden verstreut und ich konnte fliehen.\n\nIch habe ihnen niemals für meine Rettung danken können. Ich bitte Euch, <Klasse>, findet sie und sagt ihnen meinen Dank.", progress = nil, completion = "Ihr könnt Eurer Freundin erzählen, dass es eine Freude und unsere Pflicht war, sie zu retten.\n\nIhre Begegnung war in meinen Augen nichts als ein kleiner Teil eines großen Gesamtbildes.\n\nDalaran scheut keine Mühe, um dieses Geheimnis zu lüften, aber um ganz ehrlich zu sein, könnten wir etwas Hilfe gebrauchen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11575] = {title = "Gerade noch rechtzeitig", objective = "Mücke in der Valianzfeste möchte, dass Ihr Euch auf das Bernsteinflöz im Norden begebt und ihren Rettern ihren Dank aussprecht.", description = "Ich habe ihnen alles erzählt, woran ich mich erinnern kann. Wieso glauben sie mir nicht? Ich habe in der Nähe des Abgrundes nach Kräutern gesucht, als sie wie aus dem Nichts auftauchten - dunkle Magier mit magischen Biestern. Ich war umzingelt!\n\nÜber mir erschien ein riesiger magischer Würfel. Er öffnete sich und sog mich einfach auf. Ich schwöre, es ist die Wahrheit!\n\nGenau als er im Begriff war, sich zu schließen, schossen meine Retter auf den Rücken roter Drachen im Sturzflug vom Himmel. Es war atemberaubend! Meine Geiselnehmer wurden verstreut und ich konnte fliehen.\n\nIch habe ihnen niemals für meine Rettung danken können. Ich bitte Euch, <Klasse>, findet sie und sagt ihnen meinen Dank.", progress = nil, completion = "Ihr könnt Eurer Freundin erzählen, dass es eine Freude und unsere Pflicht war, sie zu retten.\n\nIhre Begegnung war in meinen Augen nichts als ein kleines Teil eines großen Gesamtbildes.\n\nDalaran scheut keine Mühe, um dieses Geheimnis zu lüften, aber um ganz ehrlich zu sein, könnten wir etwas Hilfe gebrauchen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11576] = {title = "Die Klamm beobachten: Spaltkliffanomalie", objective = "Garren vom Bernsteinflöz möchte, dass Ihr das Arkanometer bei der Spaltkliffanomalie benutzt.", description = "Grüße, <Volk>. Ich bin Garren von Dalaran.\n\nVor nicht allzu langer Zeit war die Klamm ein friedlicher Ort - zumindest in geothermischer Hinsicht. \n\nDoch erst vor Kurzem traten mit alarmierender Regelmäßigkeit Erdbeben und Risse im Boden auf, die ein einzigartiges Energiefeld mit gigantischen Kräften freigesetzt haben.\n\nMeine Aufgabe ist es, diese Anomalien zu beobachten und aufzuzeichnen. Meine Instrumente zeigen an, dass eine weitere an der nach Südwesten ausgerichteten Klippenwand aufgetreten ist.\n\nNehmt dieses Gerät und benutzt es, wenn ihr den neuen Riss feststellt.", progress = nil, completion = "Faszinierend!\n\nDies ist bisher der größte Riss.\n\nIch fürchte allerdings, dass uns das Schlimmste noch bevorsteht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11578] = {title = "Die \"Fress\"-Quest (123)aa", objective = "Tötet Koboldgezücht - und zwar 2 davon.", description = "$TNichtsnutz;! Tötet Koboldgezücht, und zwar 2 davon.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nJahr des Huhns\n\nIhr bekommt:\n\nErfrischendes QuellwasserSchwacher Heiltrank"}
MultiLanguageQuestData['de'][11579] = {title = "Die \"Fress\"-Quest (123)aa", objective = "Tötet Koboldgezücht, und zwar 2 davon.", description = "$TNichtsnutz;! Tötet Koboldgezücht, und zwar 2 davon.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nJahr des Huhns\n\nIhr bekommt:\n\nErfrischendes QuellwasserSchwacher Heiltrank"}
MultiLanguageQuestData['de'][11580] = {title = "Entweiht dieses Feuer!", objective = "Entweiht das Freudenfeuer der Horde im Silberwald!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFreudenfeuer ausstampfen\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11581] = {title = "Entweiht dieses Feuer!", objective = "Entweiht das Freudenfeuer der Allianz in Westfall!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFreudenfeuer ausstampfen\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11582] = {title = "Die Klamm beobachten: Die Kluft", objective = "Garren vom Bernsteinflöz möchte, dass Ihr den Arkanometer bei der Kluftanomalie benutzt und mit den Messungen zu ihm zurückkehrt.", description = "Habt Ihr das gespürt?! Und das war nur das Nachbeben... Ihr hättet vor ein paar Minuten hier sein sollen!\n\nIch fürchte, ich muss Eure Dienste erneut in Anspruch nehmen. Meine Instrumente sagen mir, dass es westlich von hier zu einem gewaltigen Riss gekommen ist, tief unterhalb der Wasseroberfläche.\n\nWie zuvor möchte ich, dass Ihr den Arkanmeter nehmt und die Anomalie ausmesst.\n\nIch werde einen Zauber wirken, der es Euch ermöglicht, unter Wasser zu atmen. Sollte er abklingen, bevor Ihr etwas gefunden habt, so kommt zu mir zurück und ich werde ihn erneuern.", progress = nil, completion = "Wie groß war es?\n\nDas ist unmöglich! Ich muss das sofort nach Dalaran melden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11583] = {title = "Ehrt die Flamme", objective = "Ehrt die Flamme von Westfall.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11584] = {title = "Ehrt die Flamme", objective = "Ehrt die Flamme des Silberwaldes.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11585] = {title = "Höllschreis Wacht", objective = "Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste.", description = "Throm-Ka, <Volk>! Willkommen in der Kriegshymnenfeste. Zu sehen, dass ein solch dekorierter Held der Horde dem Ruf der Pflicht Folge leistet, erfüllt mein Herz mit Stolz!\n\nDiese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Wir haben viele Schlachten schlagen müssen, um hier in Nordend Fuß zu fassen. Von hier aus wird unsere Reise zur Eiskrone beginnen und die Führungskraft von Höllschreis Sohn soll uns zum Erfolg verhelfen!\n\nGarrosh wartet unten auf Eure Ankunft.\n\nLok'tar ogar!", progress = nil, completion = "Ein Held der Horde, wie?\n\n&lt;Garrosh beschnüffelt die Luft um Euch herum.&gt;\n\nAngst...\n\n&lt;Garrosh spuckt auf den Boden.&gt;\n\nIhr werdet nicht lange durchhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11586] = {title = "Höllschreis Wacht", objective = "Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste.", description = "Throm-Ka, <Volk>! Willkommen in der Kriegshymnenfeste. Zu sehen, dass ein solch dekorierter Held der Horde dem Ruf der Pflicht Folge leistet, erfüllt mein Herz mit Stolz!\n\nDiese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Wir haben viele Schlachten schlagen müssen, um hier in Nordend Fuß zu fassen. Von hier aus wird unsere Reise zur Eiskrone beginnen und die Führungskraft von Höllschreis Sohn soll uns zum Erfolg verhelfen!\n\nGarrosh wartet unten auf Eure Ankunft.\n\nLok'tar ogar!", progress = nil, completion = "Denkt bloß nicht, dass ich vergessen habe, was Ihr für mein Volk in Nagrand getan habt, &lt;Name&gt;. Höllschrei vergisst niemals.\n\nDafür stehe ich in Eurer Schuld und aus diesem Grund gebe ich Euch jetzt diese Chance: Lauft! Verlasst diesen Ort und blickt niemals zurück.\n\nKehrt nach Hause zurück und sprecht ein Gebet für die Sterbenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11587] = {title = "Gefängnisausbruch", objective = "Bibliothekar Donathan vom Bernsteinflöz möchte, dass Ihr den Beryllmagierjägern auf der Beryllspitze den Beryllkerkerschlüssel abnehmt und ihn dazu verwendet, die eingesperrten Magier aus ihren arkanen Gefängnissen zu befreien.", description = "Grüße, <Klasse>. Ich bin Donathan, ein loyaler Repräsentant Dalarans.\n\nVergebt mir mein abruptes Auftreten, aber wir befinden uns mitten in einer Krise. In ganz Azeroth werden Magier entführt und ich wurde dazu ermächtigt, jeden einzuberufen, der uns dabei helfen kann, hinter dieses Rätsel zu kommen.\n\nDas Lager gleich südlich von uns ist der Ort, an dem die Untersuchung beginnen wird. Ich fordere Euch auf, einen der dort gefangen gehaltenen Magier zu befreien. Dazu müsst Ihr den Magierjägern in der Nähe einen Schlüssel abnehmen und damit das arkane Gefängnis aufsperren.", progress = "Ich vertraue darauf, dass Ihr unablässig daran arbeitet, einen gefangenen Magier zu befreien...", completion = "Gut gemacht, &lt;Name&gt;.\n\nDie Kirin Tor nehmen die Hilfe, die Ihr geleistet habt, dankend entgegen. Wisset, dass kein Dienst, den Ihr uns erweist, unbelohnt bleiben wird.\n\nBitte, nehmt diese milde Gabe als Zeichen der Wertschätzung Dalarans.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11590] = {title = "Entführung", objective = "Donathan möchte, dass Ihr den arkanen Binder auf einen verwundeten Beryllzauberer auf der Beryllspitze anwendet und ihn anschließend auf das Bernsteinflöz bringt.", description = "<Name>, wir haben ein Problem.\n\nIch habe soeben erfahren, dass einer unserer Erzmagier, der sich auf dem Weg von Dalaran hierher befand, vermisst wird. Natürlich vermuten wir, dass die Magierjäger dahinter stecken.\n\nDie Zeit drängt. Wir müssen umgehend herausfinden, was Lady Evanor zugestoßen ist, wenn wir darauf hoffen wollen, sie zu befreien.\n\nNehmt dieses Gerät. Kehrt zur Beryllspitze zurück und wendet es auf einen Beryllzauberer an, wenn er sich kurz vor dem Tod befindet. Es sollte ihn lange genug binden, damit Ihr ihn zur weiteren Befragung hierher bringen könnt.", progress = "Habt Ihr einen Beryllzauberer gefangen genommen, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.\n\nEr wird umgehend für das Verhör bereit sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAbduction: Quest Complete (Force Cast)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11591] = {title = "Meldet Euch bei Stahlkiefers Karawane", objective = "Findet Grunzer Zornfaust. Er befindet sich bei Stahlkiefers Karawane.", description = "Stahlkiefer, diese minderbemittelte Kanaille, hat versucht unsere Karawane mit Vorräten auf einer Abkürzung durch einen Friedhof der Taunka zu führen!\n\nWir haben gerade Verbindung mit ihnen aufgenommen!\n\nNun ist die Karawane dezimiert - überrannt von den Geistern der Taunka, die aus ihren Gräbern auferstanden, als er über sie trampelte.\n\nBegebt Euch nach Süden und seht, ob Ihr die Situation in den Griff bekommt, <Klasse>. Ich habe Grunzer Zornfaust mit ein paar Anderen losgeschickt, um dort auszuhelfen.\n\nSeht doch einfach mal nach, ob Ihr ihnen zur Hand gehen könnt.", progress = nil, completion = "Das ist nicht gut, &lt;Klasse&gt;.\n\nFernläufer Stolzhuf meint, dass es sich hier um die Begräbnisstätte seiner geehrten Urahnen handelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11592] = {title = "Wir schlagen zu!", objective = "Helft Fernläufer Stolzhuf und seinen Räubern des Kriegshymnenklans dabei, den Angriff auf Stahlkiefers Karawane zu überleben, und besiegt den Geist des Truppenkommandanten Stahlkiefer.\n\nMeldet Euch wieder bei Oberanführer Bor'gorok, falls Ihr erfolgreich sein solltet. Er befindet sich im Außenposten Bor'gorok.", description = "Einer unserer Orcs namens Stahlkiefer hat versucht, etwas Zeit einzusparen, indem er eine Abkürzung durch unsere Begräbnisstätte nahm. Hoffentlich ist dies nicht ein Verhalten, das die Horde üblicherweise an den Tag legt, <Volk>, oder die Taunka werden Euer Ende sein!\n\nDoch Ihr seht aus, als wolltet Ihr dabei helfen, die Sache wieder geradezubiegen. Gut!\n\nStahlkiefers verfluchter Geist sucht nun diesen Ort heim und stört die Überreste meiner Ahnen. Wir müssen ihm ein Ende bereiten!\n\nErstattet Eurem Oberanführer Bor'gorok beim Außenposten gen Norden Bericht, falls wir dies überstehen sollten.\n\nSteht Ihr mir bei?", progress = nil, completion = "Blut und Donner! Ihr habt unsere frisch geknüpfte Bande mit den Taunka gerettet.\n\nIch danke Euch dafür, dass Ihr die Dinge ins Lot gebracht habt. Aka'Magosh, &lt;Name&gt;!", rewards = "Gürtel des DämmeraugesSchattenwickelhandschuheStiefel des TundraschreitersAuf Euch wartet eine dieser Belohnungen:\n\nEifer des Kriegshymnenklans\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11593] = {title = "Die geehrten Toten", objective = "Grunzer Zornfaust bei Stahlkiefers Karawane möchte, dass Ihr mit Zornfausts Fackel insgesamt 10 tote Karawanenwachen oder -arbeiter in beliebiger Kombination einäschert.", description = "Unsere Gefallenen haben das Begräbnis eines Helden verdient, doch wir können sie nicht hier auf geheiligtem Taunkaboden begraben.\n\nIch werde zwar nicht von Euch verlangen ihre Leichen hierher zurückzuschleifen, doch nehmt dies und begebt Euch weiter in den Friedhof hinein. Steckt unsere toten Karawanenwachen und -arbeiter in Brand, wenn Ihr sie findet.\n\nEhrt unsere Toten, <Klasse>!", progress = nil, completion = "Ich danke Euch, &lt;Klasse&gt;. Wir sind die Horde - die Horde lässt ihre Toten nicht im Stich!\n\nEs hätte von vornherein niemals passieren dürfen. Stahlkiefer ist ein Dummkopf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11594] = {title = "Lasst sie zur Ruhe kommen", objective = "Zerstört 20 Taunkageister, also entweder geisterhafte Weise oder wiederauferstandene Fernläufer, und geht anschließend zu Stahlkiefers Karawane und meldet Euch dort bei Grunzer Zornfaust.", description = "Truppenkommandant Stahlkiefers Dummheit hat dieses Chaos verursacht. Was hat er sich dabei gedacht, als er eine Karawane durch eine Begräbnisstätte der Taunka führte?\n\nDoch was geschehen ist, ist geschehen. Und es liegt nun an uns, mit den Konsequenzen fertigzuwerden.\n\nOberanführer Bor'gorok hat mich darum gebeten, Fernläufer Stolzhuf in jeder erdenklichen Hinsicht zu unterstützen. Der Fernläufer möchte, dass wir die Geister seiner Ahnen zur Ruhe kommen lassen.\n\nWas sagt Ihr, <Klasse>? Seid Ihr <Manns/stark> genug, mit solch einer einfachen Aufgabe fertigzuwerden?", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;! Ihr müsst ja über enorme Kampferfahrung verfügen, wenn ihr es mit den Untoten aufnehmt. Und falls nicht, trifft es spätestens jetzt zu.\n\nIhr werdet sie gebrauchen können, wenn Ihr in Nordend überleben wollt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11595] = {title = "Die Verteidigung der Kriegshymnenfeste", objective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", description = "Höllschrei trägt die Last der Horde auf seinen Schultern. Lasst Euch von seinem Temperament nicht von Euren Pflichten abbringen, <Name>.\n\n<Saurfang nickt Euch zu.>\n\nHabt Ihr gedacht, dass ich den Namen eines Helden von Orgrimmar vergessen würde? Es kommt nicht jeden Tag vor, dass ich das Vergnügen habe, den Kopf Nefarians aufzuspießen!\n\nDie Geißel hat mit ihrem Angriff auf diese Festung begonnen. Unsere Soldaten halten zwar stand, benötigen jedoch dringend Verstärkung. Meldet Euch bei Razgor. Er ist direkt außerhalb der Kriegshymnenfeste stationiert.", progress = nil, completion = "&lt;Oberanführer Razgor salutiert.&gt;\n\nEuer Ruf eilt Euch voraus, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11596] = {title = "Die Verteidigung der Kriegshymnenfeste", objective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", description = "Lasst Euch von Höllschrei nicht von Euren Pflichten als Soldat der Horde abbringen, <Volk>. Er trägt eine schreckliche Last in dieser gefrorenen Einöde, da der Ausgang seines Angriffs den Sieg über die Geißel oder die Auslöschung allen Lebens auf Azeroth bedeutet. Aus diesem Grund benötigen wir Eure Stärke und Weisheit.\n\nDie Geißel hat mit ihrem Angriff auf diese Festung begonnen. Unsere Soldaten halten zwar stand, benötigen jedoch dringend Verstärkung. Meldet Euch bei Razgor. Er ist direkt außerhalb der Kriegshymnenfeste stationiert.", progress = nil, completion = "Gerade rechtzeitig... Die Zahl der Neruber scheint sich vor gerade einer Woche verdoppelt zu haben. Wir könnten jede Hilfe gebrauchen, die wir hier draußen kriegen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11597] = {title = "Die Verteidigung der Kriegshymnenfeste", objective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", description = "Es scheint, als würden wir uns immer in den aussichtslosesten Situationen treffen, Skarabäusfürst. Wart Ihr bei unserem letzten Treffen nicht dabei, die Welt vor dem sicheren Untergang zu retten?\n\n<Saurfang fängt an zu kichern.>\n\nEure Unterstützung ist sehr willkommen hier in Nordend, trotz allem, was der junge Häuptling sagen mag.\n\nWenn wir nur ein Dutzend mehr Soldaten mit Eurer Stärke hätten, würden wir jetzt in Orgrimmar zusammen um ein Feuer herum sitzen.\n\nMeldet Euch bei Oberanführer Razgor. Er befindet sich gleich draußen am Haupteingang der im Süden gelegenen Kriegshymnenfeste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11598] = {title = "Den Großfelsbruch zurückerobern", objective = "Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 15 Neruber der Nerub'ar tötet.", description = "Während die Kriegshymnenfeste zu allen Seiten hin durch zehn Fuß hohe Wälle aus Stein und Stahl geschützt ist, ist dieser Steinbruch ein leichtes Ziel und Angriffen der Neruber ausgeliefert.\n\n<Razgor deutet in Richtung Westen.>\n\nJenseits dieses Steinbruchs stehen tausende Diener der Geißel und warten auf den Angriffsbefehl. Sollten die Neruber unsere inneren Verteidigungsanlagen überwinden, werden wir von Arthas' untoten Legionen überrannt.\n\nWir dürfen das nicht zulassen - weshalb Ihr zum Angriff übergehen und die Neruber im Steinbruch abschlachten müsst.\n\nBlut und Donner, <Soldat/Soldatin>! Nehmt beides mit auf den Weg.", progress = nil, completion = "Ihr habt ihren Vormarsch gebremst, doch bestimmt werden sich ihnen noch viele im Kampf anschließen. Konntet Ihr irgendwelche von den Eiersäcken finden, als Ihr im Steinbruch wart?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11599] = {title = "Mein Bruder Thassarian", objective = "Sucht nach William Allerton im Inneren der Mine von Fernhain.", description = "Ich habe kürzlich von William Allerton, einem Familienfreund, Nachricht erhalten, dass mein Bruder am selben Tag wie er den Dienst an der Waffe hier in der Valianzfeste angetreten hat. Die Sache ist nur... mein Bruder ist bereits seit Jahren tot.\n\nAlles, was ich besaß, habe ich verkauft, um nach Thassarian zu suchen, nur um dann von den örtlichen Behörden Steine in den Weg gelegt zu bekommen. Mir wurde sogar mit einer Festnahme gedroht, falls ich weiterhin herumschnüffeln sollte.\n\nIch brauche jemanden, dem die Obrigkeiten wohlgesinnt sind... jemanden wie Euch. Wenn Ihr mir dabei helfen könntet - ich habe gehört, dass Williams in der Mine von Fernhain stationiert ist.", progress = nil, completion = "Die Leiche passt zu Leryssas Beschreibung von William Allerton. Seltsamerweise finden sich keine Biss- oder Kratzspuren an ihm.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11600] = {title = "Der verstorbene William Allerton", objective = "Bringt den Einberufungsbescheid zu Leryssa in die Valianzfeste in der Boreanischen Tundra.", description = "Williams Hals wurde von einem scharfen Gegenstand durchschnitten.\n\nWeitere Nachforschung gibt einen einzelnen Hinweis preis, der Leryssa nützlich sein könnte - ein Einberufungsbescheid mit dem Namen William Allerton.", progress = "Ihr habt mit William gesprochen, <Name>?", completion = "Ihr denkt also, dass Williams Tod, den er durch die Geißel gefunden hat, purer Zufall war? Da ist was faul dran, so viel ist sicher.\n\nIrgendetwas geht vor sich. Wir müssen Thassarian finden.", rewards = "Stiefel des SeefahrersBeinschützer des MeeressprechersMeeresknochentopfhelmAuf Euch wartet eine dieser Belohnungen:\n\nTalisman der Tundra\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11601] = {title = "Verloren und wiedergefunden", objective = "Sprecht mit James Diakon im Gasthaus der Valianzfeste.", description = "Der arme Herr Allerton könnte uns dabei helfen, meinen Bruder zu finden.\n\n<Leryssa enthüllt ein großes Buch, einem Rekrutierungsregister nicht unähnlich.>\n\nHab's mir ausgeliehen, ok? Wollen doch mal sehen, ob dieser Einberufungsbescheid ein Datum hat.\n\nWilliam sah Thassarian in der Schlange, als sie eingezogen wurden. Ihre Einträge müssen dicht nebeneinander stehen... hier ist er!\n\nEr wurde... Einheit S zugewiesen? Alle anderen Einheiten wurden nach Städten der Allianz benannt.\n\nWas für eine Einheit ist das? Wohin wurden sie geschickt? Wir sollten uns umhören. Findet heraus, ob die Gastwirte irgendetwas gehört haben.", progress = nil, completion = "Kann Euch leider nicht weiterhelfen, mein Freund. Aber vielleicht kenne ich jemanden, der es kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11602] = {title = "Von der Quelle abschneiden", objective = "Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 10 Eiersäcke der Nerub'ar zerstört.", description = "Die Luftaufklärung des Steinbruchs berichtet, dass die Neruber ihre Eier auf den Gerüsten, welche die Basis umgeben, verstauen. Kluge Biester sind das... Sie bewahren ihre Eier an trockenen, hoch gelegenen Plätzen auf, abseits vom Brennpunkt des Konflikts.\n\nIhr werdet wieder dorthin gehen und ihre Eier ausfindig machen müssen. Findet sie, zerschmettert und zerschlagt sie.\n\nJeder Eiersack, den Ihr zerstört, bedeutet, dass sich zwanzig Neruber weniger an unseren Leichen gütlich tun.", progress = nil, completion = "Trotz unserer Bemühungen kommen immer mehr. So kann es nicht weitergehen, &lt;Name&gt;.", rewards = "Schlängelnder StabStachelkolben des SoldatenHeimtückische ZauberklingeMorgenstern des SanitätersLangbogen des KriegshymnenklansGroßschwert des KampferfahrenenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11603] = {title = "In vino veritas", objective = "Bergt eine Flasche Wein der Kul Tiras aus dem gesunkenen Schiffswrack nordöstlich der Valianzfeste und bringt sie zum alten Paßbrand im Gasthaus der Valianzfeste.", description = "Das Militär war alles, was dem alten Paßbrand blieb. Selbst nachdem er in den Ruhestand gegangen war, klammerte er sich daran wie an sein eigenes Leben.\n\nEr kennt den Namen jedes Generals, jeder Einheit, Brigade und Abteilung... einfach alles. Er ist der Mann, nach dem Ihr sucht.\n\nDas Problem ist nur, dass er vom Schicksal gezeichnet ist. Er spricht mit niemandem, außer er bekommt seinen Wein der Kul Tiras. Erinnert ihn an die Zeiten, als er bei der Marine war.\n\nIch habe schon seit Monaten keine Lieferung mehr bekommen. Das letzte Schiff aus Kul Tiras ist nordöstlich von hier gesunken. Versucht doch eine Flasche von dort zu bergen und sie Paßbrand zu bringen.", progress = "<Der alte Mann sieht mit ausdruckslosem Blick zu Euch auf.>", completion = "Mmmmm... nicht zu bitter... nicht zu trocken... das ist wie in alten Tagen, als ich gemeinsam mit den Jungs beim Militär war.", rewards = "Ihr bekommt:\n\nKümmelbranntwein"}
MultiLanguageQuestData['de'][11604] = {title = "Ein Deserteur", objective = "Findet das Gefängnis in der inneren Festung der Valianzfeste und sprecht mit dem Deserteur.", description = "Einheit S... Einheit S... hmmm... ergibt keinen Sinn... sollte nach einer Stadt benannt sein...\n\nDunkelhain wurde in die Drachenöde geschickt. Die Goldhainjungs in den Fjord. Wo hab ich das nochmal gehört...\n\nAch ja... der Deserteur! Da ist ein Fahnenflüchtiger im Gefängnis der Kaserne. Wurde erst vor Kurzem hineingeworfen. Sagte immer wieder, dass \"S\" für Selbstmord stünde.\n\nSucht nach dem Deserteur. Er hat vielleicht ein paar Informationen für Euch.", progress = nil, completion = "Was'n los? Probleme hab' ich genug!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11605] = {title = "Die geehrten Ahnen", objective = "Ältester Atkanok außerhalb des Froststeinbruchs möchte, dass Ihr die Statuen des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret identifiziert.", description = "<Eine fern klingende Stimme hallt in Eurem Kopf wider, als Ihr Euch die Steinstatue anseht.>\n\nLasst Euch nicht erschrecken, <Fremder/Fremde>. Ich bin Ältester Atkanok, ein uralter Ahne des Tuskarrvolkes, ein geübter Handwerker zu meiner Zeit und seit Jahrhunderten der Wächter dieses Steinbruchs.\n\nDer Steinbruch wurde überrannt, wodurch meine Statuen nicht fertig gebaut werden konnten, während die Geister der Ahnen auf der Welt umherwandeln. Werdet Ihr mir helfen, dies wieder zurecht zu biegen?\n\nAls Erstes muss ich die Namen der wandelnden Ahnen wissen. Sucht nach den Markierungen in der Nähe der Statuen.", progress = "<Die ferne Stimme erklingt wieder.>\n\nHabt Ihr die Namen der umherwandelnden Ältesten herausfinden können?", completion = "&lt;Die Stimme des Ältesten Atkanok grüßt Euch, als Ihr seiner Statue nähertretet.&gt;\n\nGut gemacht, &lt;Name&gt;. Da wir nun die Namen der umherwandelnden Ältesten haben, können wir mit den durch die Angriffe gestörten Zeremonien weitermachen. Bevor die Geister der Ältesten jedoch zu ihren Steinen geführt werden können, müssen wir die Geister der ermordeten Handwerker und Schamanen besänftigen. Sonst erhören die Geister der Ahnen den Ruf der Zeremonie womöglich nie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11606] = {title = "Geduld ist eine Tugend, die wir nicht brauchen", objective = "Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr 15 Kisten mit Munition des Kriegshymnenklans besorgt.", description = "Wir können so viele Neruber töten und so viele Eier zerstören, wie wir wollen - immer werden neue nachkommen, solange wir ihre Tunnel und Versorgungsschächte nicht sprengen. Natürlich können wir das nicht machen, wenn wir keine schwere Munition haben. Unglücklicherweise wird der Großteil unseres Vorrats von den Goblins und Schmieden für unsere Belagerungspanzer und Waffen verwendet.\n\nDoch zufälligerweise haben wir einen beträchtlichen Vorrat von dem Zeug drüben im Großfelsbruch, unter all dem nerubischen Mist. Ihr müsst nur dorthin gehen und es mir bringen.", progress = "Uns rennt die Zeit davon, <Klasse>.", completion = "Wenn meine Berechnungen stimmen - was sie oft nicht tun -, dann werdet Ihr ungefähr 10 bis 20 Zephyriumtiefenladungen benötigen.\n\nAch, und Ihr werdet die Süßen in ihren Schlundlöchern platzieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11607] = {title = "Verlorene Geister", objective = "Ältester Atkanok am äußeren Rand des Froststeinbruchs möchte, dass ihr die Geister von 3 Handwerkern von Kaskala und 3 Schamanen von Kaskala befreit.", description = "Bei dem Angriff auf den Steinbruch wurden die Handwerker und Schamanen, die dort arbeiteten, getötet. Die Gewalt riss die Geisterwelt in absolutes Chaos und wir werden den Ahnen nicht den Weg nach Hause weisen können, wenn wir keinen Weg finden, die Geister der Ermordeten zu besänftigen.\n\nDie Angreifer selbst schenken den Geistern keine Beachtung, doch ihre Begleiter, die Beryllhunde, können die Geister spüren und lassen kein Auge von ihnen ab.\n\nRäumt die Beryllhunde aus dem Weg und befreit mithilfe der rohen Energie, die übrig bleibt, die Geister der Unschuldigen aus ihrem Gefängnis.", progress = "Wie ergeht es den Geistern der Unschuldigen?", completion = "Ich kann spüren, dass der Aufruhr in der Geisterwelt sich zu legen beginnt. Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Die Geister der Ahnen können sich glücklich schätzen, Eure Hilfe in diesen Zeiten der Not zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11608] = {title = "Begrabt diese Kakerlaken!", objective = "Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr mithilfe des Bündels mit Zephyriumsprengsätzen die Schlundlöcher der Nerub'ar zerstört. Diese befinden sich südlich, östlich, westlich und nördlich der Kriegshymnenfeste.", description = "Norden, Süden, Osten und Westen: Dort liegen die Orte, um die Ihr Euch Sorgen machen solltet. Diese Festung, die sich mitten im Großfelsbruch befindet, ist von vier ideal gelegenen Schlundlöchern der Nerub'ar umringt.\n\n<Holgoth reicht Euch ein Bündel.>\n\nGeht sehr vorsichtig mit diesem Paket um, <Name>. Ein falscher Handgriff und Ihr seid Hundefutter.\n\nIn dem Bündel befinden sich Zephyriumsprengsätze. Begebt Euch zu jedem der Schlundlöcher der Nerub'ar und platziert eine Ladung in der Mitte. Wenn alles gut geht, werden die Tunnel einstürzen.\n\nNun bewegt Euch!", progress = nil, completion = "Das wird sie aufhalten - zumindest denke ich, dass es das wird. Wie dem auch sei, Ihr habt Euren Teil erledigt. Und das ist alles, was sich ein Orc wünschen kann, oder nicht?", rewards = "Beinschützer des MarschenläufersHelmkappe des TundraschreitersGroßfelsbrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nRache des Kriegshymnenklans\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11609] = {title = "Die Reste beseitigen", objective = "Bringt Ältester Atkanok 6 Ritualobjekte der Tuskarr. Er befindet sich außerhalb des Froststeinbruchs.", description = "Nun, da die Geister der ermordeten Handwerker und Schamanen zur Ruhe gekommen sind, gibt es nichts, was uns davon abhalten könnte, die durch den Angriff unterbrochenen Zeremonien abzuschließen. Ihr müsst die Rolle übernehmen, die traditionell einem Schamanen der Tuskarr vorbehalten ist, und Ihr müsst über alle notwendigen Ritualgegenstände verfügen.\n\nWir haben keine Zeit, neue zu fertigen, also werdet Ihr den Steinbruch nach den Gegenständen absuchen, die von den Opfern des Angriffs zurückgelassen wurden. Geht mit den Objekten vorsichtig um, <Name>, denn einige sind Hunderte von Jahren alt. Womöglich werdet Ihr sie den Händen der Eindringlinge entreißen müssen.", progress = "Habt Ihr alle benötigten Ritualgegenstände besorgen können?", completion = "&lt;Ihr haltet die Objekte vor der Statue des Ältesten Atkanok hoch.&gt;\n\nDas wird genügen, obwohl sie sich in einem traurigen Zustand befinden. Einige von ihnen wurden Jahrhunderte lang benutzt, um am Ende von Barbaren gestohlen und ramponiert zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11610] = {title = "Die Ahnen nach Hause führen", objective = "Ältester Atkanok möchte, dass Ihr die Geister des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret zu ihren Steinmonumenten geleitet.", description = "Dank Eurer Hilfe können die Geister der Ahnen nun zu ihren rechtmäßigen Stätten geführt werden, den Statuen, die von den Handwerkern der Kaskala und Schamanen liebevoll hergestellt wurden.\n\nDie Zeremonien für diese Ahnen wurden während des Angriffs auf den Steinbruch unterbrochen und Ihr werdet sie zu Ende bringen müssen. Nehmt die Objekte, die Ihr aus dem Steinbruch beschafft habt, stellt Euch vor die Statuen mit den Namensschildern und tragt diesen Sprechgesang vor.\n\n<Worte in einer fremden Sprache durchströmen Euren Kopf, doch Ihr habt keine Schwierigkeiten, Euch an sie zu erinnern.>", progress = nil, completion = "Die Ahnen haben ihre Statuen gefunden und Euch gebührt ihr Dank, &lt;Name&gt;. Die Handwerker von Kaskala werden in den Steinbruch zurückkehren und sicherstellen, dass die Blutlinie der Ahnen ungebrochen weitergeht. Für unseren Teil werden wir, die Ahnen, Euch weiterhin mit Interesse beobachten, da Euer Weg anscheinend gerade erst begonnen hat.", rewards = "Mantel des SeefahrersGamaschen des WalfängersGelöste BindungenAuf Euch wartet eine dieser Belohnungen:\n\nEisstromhalsschmuck\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11611] = {title = "Von der Geißel eingenommen", objective = "Großknecht Mortuus in der Kriegshymnenfeste möchte, dass Ihr 5 Peons des Kriegshymnenklans befreit.", description = "<Mortuus seufzt.>\n\nPeons... Wir könnten genauso gut ein Schild aufstellen, das den Nerub'ar eine freie Mahlzeit verspricht.\n\nSeht, das Problem mit Peons ist, dass sie: (1.) dumm wie Brot sind und sie (2.) schwächer sind als ein aussätziger Gnom. Kein Wunder, dass die Geißel sich sie als Erstes vorknöpft.\n\nDas versetzt mich in eine relativ prekäre Lage: Ohne Peons kommt die Arbeit zum Erliegen. Keine Peons, kein Bau.\n\nFindet und befreit meine Peons, <Volk>. Falls sie am Leben sind, solltet Ihr sie im Großfelsbruch in Netze eingesponnen vorfinden.", progress = "Keine Peons, keine Bauten. Und nein, wir werden sie nicht durch Goblins ersetzen. Viel zu teuer...", completion = "Die meisten von ihnen haben es zurückgeschafft. Zumindest diejenigen, die klug genug waren, um zu wissen, dass wir uns in dem gigantischen Stein- und Stahlgebäude befinden...\n\nAbgesehen davon habt Ihr gute Arbeit geleistet. Habe gehört, dass Ihr mehr als ein Dutzend von ihnen da rausgeholt habt.\n\nOh ja, wie soll ich sagen... Ihr seid hier in der Feste in aller Munde...", rewards = "Verwitterter ArbeiterumhangStiefel des MarschenläufersHandbedeckung der WestklammGroßfelsbeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11612] = {title = "Den Steinbruch zurückerobern", objective = "Etaruk möchte, dass Ihr 12 Beryllschatzjäger tötet. Er befindet sich in der Nähe des Eingangs zum Froststeinbruch.", description = "Ihr seid hier gerne gesehen, <Klasse>. Mein Name ist Etaruk und ich war einmal ein Handwerker hier im Froststeinbruch.\n\nMeine Gefährten und ich waren gerade dabei, mehrere neue Statuen für die aller neuesten Riten vorzubereiten, als wir sahen, wie diese geheimnisvollen blauen Plattformen über unser Plateau geflogen kamen.\n\nAls sie landeten, strömte ein Schwarm von Magiern, die sich auf ihnen befanden, in den Steinbruch, plünderten und ermordeten meine Freunde. Wenn wir sie nicht aufhalten, werden sie unsere Statuen zerstören und sich mit unseren Artefakten davonmachen. Werdet Ihr mir dabei helfen, die Eindringlinge zu besiegen?", progress = "Habt Ihr damit begonnen, den Steinbruch von unseren Feinden zu befreien?", completion = "Da nun diese seltsamen Magier wissen, dass die Leute von Kaskala und ihre Alliierten den Steinbruch nicht so leicht aufgeben werden, müssen wir uns erst recht bemühen und sie endgültig besiegen.\n\nMeine Brüder in Kaskala wurden auch angegriffen und werden uns nicht unterstützen können. Doch mit Eurer Hilfe, &lt;Name&gt;, können wir die Plünderer überwältigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11613] = {title = "Karuks Schwur", objective = "Karuk möchte, dass Ihr 6 Räuber der Skadir und 5 Langbootsmänner der Skadir tötet.", description = "Sie nennen sich selbst die Kvaldir. Mein Volk erzählt sich Legenden über sie. Wir nennen sie die Tuk-Hariq - die Läufer des Nebels.\n\nMein Dorf wurde von diesen riesigen Dunstkerlen zerstört. Jeder, den ich kannte, wurde von ihnen erschlagen, auch mein Vater Ariut.\n\nDas Gesetz der Tuskarr fordert von mir Vergeltung an jenen zu üben, die das Blut meiner Verwandten vergossen.\n\nIch bin nichts weiter als ein Fischer und habe noch nicht die Reifeprüfung zum Mann hinter mir... Ich kann den niederträchtigen Kvaldir noch nicht auf Augenhöhe begegnen.\n\nIch stünde tief in Eurer Schuld, wenn Ihr in meinem Namen Blutrache übtet.", progress = "Wart Ihr erfolgreich, <Volk>? Die Kvaldir sind grausame <Klasse>. Erwartet kein Pardon von ihnen.", completion = "Ihr habt meinem Volk einen großen Gefallen erwiesen, &lt;Name&gt;. Ich muss Euch jedoch noch um eine Sache bitten.", rewards = "Klaue der TuskarrHaistecherKompakte PfeilschleuderTranschnitzerRute des MediumsAuf Euch wartet eine dieser Belohnungen:\n\nMedizinstecken\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11614] = {title = "Schweigen ist Gold", objective = "Findet Schattenpirscher Luther im Großfelsbruch.", description = "Wir sind auf Befehl von Varimathras hier! Die Mission der Schattenpirscher ist einfach: spionieren. Nun, spionieren und ein kleiner Meuchelmord am Rande.\n\nEiner meiner besten Agenten wird vermisst. Ich habe schon seit Tagen nichts mehr von ihm gehört, weshalb ich das Schlimmste befürchte. Und ich meine nicht den Tod - sein Tod wäre ideal! Ich befürchte, dass er uns hintergeht... vielleicht sogar zum Verräter wurde.\n\nSein letzter bekannter Aufenthaltsort ist der nördlich gelegene Großfelsbruch. Er war im Begriff, sensible Informationen über die Neruber zu sammeln. Findet ihn...\n\nam besten tot...", progress = nil, completion = "Viel toter geht's wohl kaum... Seltsamerweise haben die Neruber die Leiche nicht verschlungen.\n\nNach genauer Untersuchung sehr Ihr, dass Luther seinen Tod selbst herbeigeführt hat - mit tödlichem Gift. Klug. Neruber werden sich nicht in die Nähe dieser vergifteten Leiche wagen.\n\nIhr bemerkt, dass Luther ein Tagebuch in Händen hält.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11615] = {title = "Geheimnisse der Nerub'ar", objective = "Bringt Luthers Tagebuch zu Schattenpirscher Barthus in der Kriegshymnenfeste.", description = "Ihr blättert durch die Seiten des Buchs und sucht nach Allem, das von Interesse sein könnte. Auf der letzten Seite stolpert Ihr über mehrere Einträge hektischen Gekritzels.\n\nNekrolords. Habe mindestens ein Dutzend gezählt.\n\nHöfe im Westen sind eine Art Brutstätte der Geißel.\n\nUnzählige Opfer.\n\nDenke, die haben es auf mich abgesehen. Habe mich auf zur Feste gemacht. Lebend bekommen die mich nicht.\n\nSchreckensgift - Haemotoxin. Die werden eine Überraschung erleben, wenn sie mich beißen.\n\nBringt dieses Schreiben zu Barthus.", progress = "Ist er tot?", completion = "&lt;Barthus schlägt die letzte Seite des Tagebuchs auf und fängt an zu lesen.&gt;\n\nDas sind sehr schlechte Neuigkeiten. Höllschrei muss umgehend davon erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11616] = {title = "Nachricht an Höllschrei", objective = "Bringt Barthus' Notiz zu Höllschrei in der Kriegshymnenfeste.", description = "<Barthus reißt die letzte Seite heraus und rollt sie zusammen.>\n\nBringt dies sofort zu Höllschrei! In der Zwischenzeit werde ich eine Gruppe ausschicken, die die Höfe auskundschaften soll.\n\nIhr müsst Höllschrei auf jeden Fall davon unterrichten, dass wir Verstärkung benötigen werden.", progress = "Was hat diese Störung zu bedeuten? Bürdet mir keinen Unsinn auf!", completion = "&lt;Höllschrei liest den Tagebucheintrag.&gt;\n\nIst das alles?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11617] = {title = "Ihre Flucht vereiteln", objective = "Etaruk möchte, dass ihr die nördliche Plattform, die östliche Plattform und die westliche Plattform zerstört. Er befindet sich außerhalb des Froststeinbruchs.", description = "Ich bin mir sicher, dass Ihr diese blauen und weißen Plattformen, die über dem Steinbruch schweben, gesehen habt. Sie dienen Magiertötern als Transportmittel für ihre Truppenlandungen und nun werden sie mit Artefakten und Fragmenten unserer Statuen beladen.\n\nWir müssen sie aufhalten, bevor sie den Steinbruch verlassen.\n\nDie kleinen Kreaturen, die im Steinbruch herumgraben, tragen Sprengstoff bei sich. Nehmt ihnen das Zeugs ab und zerstört die drei schwebenden Plattformen. Der Anführer hält von einer vierten, gelandeten Plattform aus Ausschau, doch um ihn werden wir uns erst später kümmern.", progress = nil, completion = "Für die Magierjäger wird es schwerer, den Steinbruch zu plündern und unsere Artefakte zu stehlen, als gedacht. Mit Eurer Hilfe, werden wir den Steinbruch zurückerobern und die Dinge wieder richtig stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11618] = {title = "Verstärkung trifft ein...", objective = "Macht Schattenpirscher Ickoris ausfindig. Er befindet sich bei den Höfen des Kriegshymnenklans westlich der Kriegshymnenfeste.", description = "<Höllschrei schüttelt seinen Kopf.>\n\nIhr habt es vielleicht nicht bemerkt, aber wir versuchen hier, einen Krieg zu gewinnen, <Volk>. Ich benötige alle verfügbaren Soldaten an den Brandherden des Konflikts. Das bedeutet, dass wir keine echten Soldaten für kleinere Übergriffe abziehen können.\n\n<Höllschrei hält inne und denkt nach.>\n\nWenn Barthus Verstärkung am Hof will...\n\n<Höllschrei klatscht seine Hände zusammen.>\n\n...wird er sie bekommen! Meldet Euch bei Barthus' Auftragsmördern, die sich westlich von hier bei den Höfen aufhalten. Lasst sie wissen, dass Verstärkung eingetroffen ist.", progress = nil, completion = "Das ist alles? Ein &lt;Volk&gt;? Höllschrei hat nur einen einzigen &lt;Klasse&gt; geschickt?\n\nWenn ich noch eine Kinnlade hätte, wäre sie jetzt auf den Boden gefallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11619] = {title = "Gamel der Grausame", objective = "Karuk möchte, dass Ihr Gamel den Grausamen tötet. Er befindet sich am Strand der Peitschennarbe.", description = "Mein eigener Vater wurde vom Anführer dieser Plünderer getötet - man nennt ihn Gamel den Grausamen. Er hat das Innere der Höhle an diesem Strand zu seinem Heim gemacht.\n\nIhr habt Euch bereits um seine Männer gekümmert. Führt zu Ende, was Ihr angefangen habt, <Name>. Rächt meinen Vater und ich werde mit Euch meinen restlichen Besitz teilen.", progress = "Habt Ihr Gamel besiegt, <Klasse>?", completion = "Ihr habt es vollbracht, &lt;Name&gt;! Die Geister der getöteten Tuskarr können nun in Frieden ruhen - ihr Tod wurde gerächt!", rewards = "Hut des WerftmeistersMantelung des MeeressprechersAuf Euch wartet eine dieser Belohnungen:\n\nStarrer HauerringHalsband der Riesenschildkröte\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11620] = {title = "Eines Vaters Wort", objective = "Geht zum Schrein der Schuppen auf dem Strand der Peitschennarbe und haltet dort nach Veehja Ausschau.", description = "Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, <Volk>. Man munkelt, dass die Kvaldir im Tempel in der westlichen Gegend des Strandes eine Nagapriesterin am Leben gelassen haben.\n\nSie wird ohne Zweifel gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht erwartet mein Vater, dass sie auf irgendeine Weise mit Euch kooperieren wird.", progress = nil, completion = "Hsssssssssssss! Seid Ihr hier, um Euch über mich lustig zu machen, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11621] = {title = "Leviroths Tafel", objective = "Kehrt zu Karuk zurück und überbringt ihm die Information, die Ihr auf der Tafel gefunden habt.Ihr seht Euch die Radierungen auf der Tafel genau an und sucht nach verständlichen Textpassagen. Endlich findet Ihr folgendes Fragment:\n\n\"Für ihn, der in den dunkelsten Gewässern haust, werden die Söhne des Nebels Tausende von Seelen fordern, bis schließlich sein Abgesandter erwacht.\"\n\nKaruk könnte an dieser Information interessiert sein.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr seht Euch die Radierungen auf der Tafel genau an und sucht nach verständlichen Textpassagen. Endlich findet Ihr folgendes Fragment:\n\n\"Für ihn, der in den dunkelsten Gewässern haust, werden die Söhne des Nebels Tausende von Seelen fordern, bis schließlich sein Abgesandter erwacht.\"\n\nKaruk könnte an dieser Information interessiert sein.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11622] = {title = "Geheimnisse der Peitschennarbe", objective = "Sucht in den Ruinen der Peitschennarbe in der Boreanischen Tundra nach Veehja und sprecht mit ihr.Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, <Volk>. Man munkelt, dass die Kvaldir eine Handvoll von Nagapriesterinnen im Inneren des Tempels am Leben gelassen haben.\n\nDie Hohepriesterin Veehja wird zweifellos gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht kann sie Euch mehr darüber sagen, was die Schrift auf der Tafel zu bedeuten hat.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, <Volk>. Man munkelt, dass die Kvaldir eine Handvoll von Nagapriesterinnen im Inneren des Tempels am Leben gelassen haben.\n\nDie Hohepriesterin Veehja wird zweifellos gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht kann sie Euch mehr darüber sagen, was die Schrift auf der Tafel zu bedeuten hat.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11623] = {title = "Ein Besuch beim Kurator", objective = "Etaruk am äußeren Rand des Frostfelssteinbruchs möchte, dass Ihr Kurator Insivius tötet.", description = "Der Anführer der Magierjägertruppen ist eine gefürchtete Kreatur namens Kurator Insivius. Mein Volk hat seit Generationen zu Land und zu Wasser unzählige Biester gejagt, doch ich habe noch nie etwas gesehen, das diesem Kurator auf irgendeine Art und Weise ähnelt.\n\nEr ist mit einer der fliegenden Scheiben am oberen Rand des Steinbruchs gelandet und überwacht von dort aus die Operation. <Name>, ich kann nur glauben, dass die Ahnen selbst Euch zu mir geschickt haben, um mir dabei zu helfen, diese Magierjäger ein für alle Mal aus diesem Steinbruch zu verjagen.", progress = nil, completion = "Der Kurator und seine Männer müssen gedacht haben, dass sie bei Plünderungen im Steinbruch leichtes Spiel haben würden, doch Ihr habt sie eines Besseren belehrt, &lt;Name&gt;. Ich bin Euch für Eure Hilfe zutiefst dankbar und bin mir sicher, dass die Ahnen weiterhin auf Euch Acht geben werden.", rewards = "RobbenfellbindungenHandschuhe der MeeresstimmeTaillenschutz des verlorenen KreuzfahrersEiskalter RundschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11624] = {title = "Der Himmel wird es wissen", objective = "Sprecht mit Imperean in den Ruinen von Eldra'nath.", description = "Ich muss herausfinden, was meinem Meister Scharfseher Grimmläufer zugestoßen ist!\n\nKurz zuvor war er dabei, die Magnatauren im nahegelegenen Magmut zu beobachten. Doch gerade ist einer seiner Grunzer zurückgekehrt und meint, dass der Trupp zerschlagen wurde und der Weissager in die Tiefen dieses Ortes verschleppt wurde.\n\nBevor ich Euch jedoch auf eine Selbstmordmission schicke, möchte ich die Geister befragen, um mehr zu erfahren.\n\nEs gibt ein Luftelementar namens Imperean in den westlich gelegenen Ruinen von Eldra'nath. Es ist weise und könnte Euch vielleicht die Informationen geben, nach denen Ihr sucht.", progress = nil, completion = "Wie töricht von Euch, hierher zu kommen, kleiner &lt;Volk&gt;.\n\nWonach verlangt es Euch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11625] = {title = "Der Dreizack von Naz'jan", objective = "Veehja möchte, dass Ihr zur nordöstlichsten Ecke der Ruinen der Peitschennarbe geht und nach Ragnar Drakkarlund sucht. Tötet ihn und nehmt ihm den Dreizack von Naz'jan ab.", description = "Fünfhundert Jahre ist es her, seit Azshara ihm die Tiefen des Gewässers unter uns zum Kerker machte. Doch nun trachten die Barbaren danach, das Werk unserer Königin zunichtezumachen!\n\nSie haben unsere Stadt erobert und damit begonnen, meine Brüder ihrem dunklen Gott zu opfern! Als alle Naga schon geopfert waren, da griffen sie nach den Tuskarr – ihre Geister werden keine Ruhe finden!\n\nIch werde Euch helfen, denn für mich wäre es, als trinke ich einen großen Schluck, um meinen Durst nach Rache zu stillen. Ihr Anführer Ragnar hält sich im Nordosten des Gebietes der Peitschennarbe auf. Er nennt einen goldenen Dreizack sein Eigen. Bringt ihn mir!", progress = "Habt Ihr den Dreizack bei Euch?", completion = "Aussssssgezeichnet! Wir werden Kvaldirs Bestien töten! Ich werde dieser Brut schon zeigen, was passiert, wenn man sich mit einer Priesterin der Schuppe anlegt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11626] = {title = "Der Abgesandte", objective = "Sucht nach Leviroth unter einem Eisberg, der gleich nördlich der Ruinen der Peitschennarbe im Wasser treibt. Erschlagt ihn mit dem Dreizack von Naz'jan und kehrt zu Karuk in die Gegend nördlich des Strands der Peitschennarbe zurück.", description = "Raj Naz'jan war der Imperator der Peitschennarbe, als Leviroth eingekerkert wurde. Azshara selbst segnete seinen Dreizack, so dass er die Bestie töten würde, sollte sie jemals entkommen.\n\nNun tragt Ihr ihn, <Volk>. So sehr es mich anwidert, doch ich werde meine Rache an diesen barbarischen Riesenmännern haben.\n\nNehmt den Dreizack und begebt Euch nördlich der Ruinen der Peitschennarbe in die Tiefen. Leviroth befindet sich unterhalb des Eisberges, der den Ruinen am nächsten ist.\n\nStreckt ihn nieder und treibt den Dreizack tief in sein Fleisch! Kehrt anschließend zu dem, der Euch ausgesandt hat, zurück. Ich möchte Euch nicht wieder sehen.", progress = nil, completion = "Die Geister meines Volkes können nun in Frieden ruhen. Ihr habt mir dabei geholfen, meinem Vater Ehre zu erweisen... Vielleicht werde ich eines Tages genauso stark sein wie Ihr.", rewards = "Gelenkbänder der EiswelleWalfängerhandschuheHaisichere HelmkappeMeeresknochenbeinplattenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11627] = {title = "Siedepunkt", objective = "Imperean möchte, dass Ihr Brodler und Neer unterwerft. Kehrt zu ihm zurück, sobald sie sich Euch ergeben haben. Er befindet sich in den Ruinen von Eldra'nath.", description = "Ihr seid also auf Informationen aus: Aufenthaltsort und Zustand Eures 'Weissagers'. Um seine eigenen Probleme vorauszusehen, hat es wohl nicht ganz gereicht.\n\nNichtsdestotrotz werde ich Euch helfen, dieses Wissen zu erlangen. Doch zuerst werdet Ihr etwas für mich tun.\n\nZweifellos habt Ihr den Krieg zwischen Feuer und Wasser im Süden gesehen. Brodler bringt Neers Teich unablässig zum Kochen und die zwei kämpfen nun schon seit einer Ewigkeit.\n\nBegebt Euch zur Kohlschwarzen Anhöhe und zum Kochenden Teich und bringt die beiden dazu, dass sie mit ihrem Gezanke aufhören.", progress = nil, completion = "Es freut mich, obwohl sie zweifellos ein wenig weiterstreiten werden.\n\nEs gibt jedoch noch etwas anderes, das Ihr erledigen müsst, bevor Ihr zu Eurer Geisterflüsterin zurückkehren könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11628] = {title = "Der Mantel der Geißel", objective = "Häuptling Orkan in Taunka'le möchte, dass Ihr ihm 5 verseuchte Mammutpelze bringt.", description = "Im Nordosten zeichnet sich die Tempelstadt En'kilah, Sitz der Geißel in der Boreanischen Tundra, drohend am Horizont ab. Aus dem Schutz ihrer Mauern heraus hat der Kommandant der Geißel seine Neruber ausgesandt, um uns einzukesseln.\n\nWeiterhin defensiv zu bleiben, wäre der Untergang für meine Leute, doch meine Ratgeber unterscheiden sich in ihren Strategien. Durm würde blindlings hineinstürmen, während die Weise Aeire ein heimliches Vorgehen vorziehen würde.\n\nDie Tempelstadt hat das Land und die Kreaturen rings um sich verdorben. Aeire glaubt, dass die Pelze der verseuchten Mammuts als Mantel dienen könnten, mit dessen Hilfe ein Eindringling versteckt werden könnte.", progress = "Habt Ihr mir die Mammutpelze gebracht?", completion = "So sehr ich mich auch dagegen sträube, solche von Krankheiten nur so strotzenden Dinger ins Dorf zu bringen, sie könnten uns doch einen Vorteil gegenüber unseren Feinden verschaffen.\n\n&lt;Der Häuptling deutet auf die Weise Aeire und winkt die Pelze mit Verachtung von sich.&gt;\n\nWährend sie die Pelze vorbereitet, müssen wir etwas Anderes herstellen - den Umhang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11629] = {title = "Kehrt zur Geisterflüsterin zurück", objective = "Liefert Impereans Urluft bei der Geisterflüsterin Fletschfang im Außenposten Bor'gorok ab.", description = "Ihr habt getan, was von Euch verlangt wurde, und nun gebe ich Euch, wonach es Euch verlangt.\n\nLiefert diese Urluft bei der Geisterflüsterin im Außenposten Bor'gorok ab. Wenn sie weise ist, wird sie ein Ritual kennen, mit dem Ihr die Informationen, nach denen Ihr sucht, bekommen könnt.", progress = "<Name>, Ihr seid zurückgekehrt. Was habt Ihr erfahren?\n\nWas ist das für ein Geräusch?", completion = "Imperean hat Euch seine eigene Urluft gegeben? Ich kann seine heulenden Winde hören!\n\nIch kenne ein Ritual, für das wir es benutzen können. Wir müssen uns beeilen, bevor seine Urluft sich selbst in Stücke reißt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11630] = {title = "Schlechte Erde", objective = "Bringt 8 Klumpen verseuchte Erde zu Häuptling Orkan in Taunka'le.", description = "Die Weise Aeire glaubt, dass, falls wir die Bälge mit der verdorbenen Erde außerhalb der Tempelstadt härten, sie daraus einen Mantel herstellen könnte, durch den die meisten Diener der Geißel Eure Gegenwart ignorieren werden. Ihr solltet dann gut dazu passen, meint sie.\n\nSie wird besser Recht haben. Es ist die einzige Chance, die wir haben, um Informationen zu sammeln und einen Gegenschlag zu planen.\n\nIhr solltet die Erde, die sie benötigt, in den Gegenden südlich und westlich der Festung finden. Bringt sie zu mir, wenn Ihr genug gesammelt habt.", progress = "Habt Ihr die Erde bei Euch, welche die Weise Aeire benötigt, um den Umhang fertig zu stellen?", completion = "&lt;Häuptling Orkan nimmt die Klumpen Erde, die Ihr gesammelt habt, vorsichtig entgegen.&gt;\n\nWir sollten die Dinger so schnell wie möglich zur Weisen Aeire bringen.\n\nDer Häuptling grunzt und gibt ein Murren von sich und tut so, als würde ihn der verdorbene Schmutz nicht stören.&gt;\n\nWir können nie wissen, wann der Kommandant der Geißel seinen finalen Angriff auf das Dorf starten wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11631] = {title = "Vision der Luft", objective = "Vollzieht mithilfe von Impereans Urluft ein Ritual bei Fletschfangs Totem im Außenposten Bor'gorok, um Informationen über Scharfseher Grimmläufer zu beschaffen.\n\nSprecht anschließend mit Geistredner Fletschfang.", description = "Hier, <Name>, ich habe die Urluft auf Euch abgestimmt.\n\nÖffnet in Anwesenheit meines Totems der Luft Eure Seele und konzentriert Euch auf Scharfseher Grimmläufers Schicksal.\n\nDer Geist des Windes berührt alles - wenn wir Glück haben, wird man Euch eine Vision gestatten.", progress = "Bringt die Urluft wieder zu mir, wenn Ihr das Gefühl habt, genug gesehen zu haben.", completion = "Sie haben seinen Geist in Ketten gelegt. &lt;Name&gt;, wir müssen seiner Qual ein Ende setzen!\n\nIhr müsst Euch in das Herz Magmuts begeben und einen Weg finden, ihn zu befreien!", rewards = "Bedeckung des HeilersRegenerativer BalgharnischGekühlte KettenstiefelAuf Euch wartet eine dieser Belohnungen:\n\nMörderischer Eisring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11632] = {title = "Was der kalte Wind mit sich bringt...", objective = "Bringt Ith'rix' gehärteten Knochenpanzer zu Hochfürst Saurfang in der Kriegshymnenfeste.", description = "Ihr haltet das Knochenpanzerfragment von Ith'rix dem Ernter in Euren Händen und erkennt, dass dies erst der Anfang ist. Selbst jetzt spürt Ihr, dass der Sieg nur von kurzer Dauer sein wird. Der Lichkönig wird sicherlich noch Tausende Biester wie Ith'rix haben, die nur darauf warten, auf die Horde losgelassen zu werden.\n\nNehmt Eure Trophäe und präsentiert sie Hochfürst Saurfang in der Kriegshymnenfeste. Er sollte davon in Kenntnis gesetzt werden, dass Ihr einen mächtigen Agenten der Geißel besiegt habt.", progress = "Was habt Ihr denn da?", completion = "&lt;Ein Grinsen zieht sich über Saurfangs Gesicht.&gt;\n\nKommt mir bekannt vor... Mit der Macht von Kalimdor wurden in der Wüste von Silithus tausend Insekten wie dieses hier zertrampelt.\n\nDer Ort hier ist anders, die Umwelt anders, doch die Ergebnisse werden dieselben sein.\n\n&lt;Saurfang inspiziert Euch.&gt;\n\nIhr werdet die Horde in Nordend Stolz machen und ihr alle Ehre bereiten, &lt;Name&gt;.", rewards = "Gamaschen der GluthitzeTaillenschutz des MarschenläufersSchulterklappen des EbenenjägersBrustplatte des SchlachtführersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11633] = {title = "Dabei sein ist alles", objective = "Häuptling Orkan in Taunka'le möchte, dass Ihr das magieerfüllte Tuch der Geißel in der Tempelstadt En'kilah überwerft und die Säule des Blutes, die Säule der Pein und die Säule der Fäulnis auskundschaftet.", description = "Die Weise Aeire hat das Tuch fertig gestellt. Nehmt es mit und begebt Euch zur Tempelstadt En'kilah. Werft es Euch über, sobald Ihr Euch in der Stadt befindet, um Euch vor den meisten der dort hausenden Dienern der Geißel zu verbergen. Das wird unsere beste Möglichkeit sein, Informationen über die Befestigungen und Anführer unserer Feinde zu sammeln.\n\nKundschaftet die drei großen Säulen der Stadt aus, während Ihr den Umhang übergezogen habt. Das Tuch wird Euch von den meisten Dienern der Geißel beschützen, doch die Monstrositäten der En'kilah werden Euch finden, wenn Ihr zu nah an sie herankommt.", progress = nil, completion = "&lt;Häuptling Orkan hört Euch aufmerksam zu, als Ihr von Euren Beobachtungen berichtet.&gt;\n\nDie Informationen, die Ihr gesammelt habt, werden uns bei der Planung unseres Angriffs auf die Tempelstadt helfen. Wir werden einen Weg finden müssen, die von Euch identifizierten Offiziere zu besiegen und Zugang zu dieser Nekropole zu erhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11634] = {title = "Windreitermeister To'bor", objective = "Meldet Euch bei Windreitermeister To'bor in der Kriegshymnenfeste.", description = "Ihr seid ganz schön hart, <Name>. Ich denke, dass Eure Talente woanders besser aufgehoben wären - ich spreche von der Wurzel des ganzen verdammten Problems!\n\n<Razgor deutet in Richtung Westen.>\n\nDort befinden sich tausend Diener der Geißel, mindestens zwei schwebende Todesmaschinen und wer weiß was sonst noch.\n\nAber Ihr werdet es herausfinden und Euch darum kümmern... Das ist richtig, Ihr werdet der Armee der Geißel, die gerade dabei ist, unsere Tür einzutreten, die Hölle heiß machen.\n\nGeht zur Spitze der Kriegshymnenfeste und meldet Euch bei Windreitermeister To'bor. Er wird Euch erwarten.", progress = nil, completion = "He, Mann! Hab dich erwartet.\n\n&lt;To'bor deutet gen Westen.&gt;\n\nWirf mal 'nen kurzen Blick da rüber. Auf der ander'n Seite der Tundra ist der Tod, Mann... Tod.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11635] = {title = "Scharfseher Grimmläufers Geist", objective = "Sprecht mit dem Geist von Scharfseher Grimmläufer im Inneren von Magmut.", description = "Ihr müsst nach Magmut im Osten.\n\nIhr müsst in die Tiefen der Höhlen hinabsteigen.\n\nIhr müsst mit dem Geist von Scharfseher Grimmläufer sprechen!", progress = nil, completion = "Ich danke Euch für die Atempause, &lt;Klasse&gt;. Wenn wahre Freiheit für mich doch nur so einfach zu erringen wäre.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11636] = {title = "Ritt auf dem magischen Teppich", objective = "Sprecht mit Yanni in der Kriegshymnenfeste, um die sichere Reise zur Küste zu arrangieren. Sprecht mit Vernichter Grek'lor, sobald Ihr bei Garroshs Landeplatz angekommen seid.", description = "Danke, Maan. Ich sprech von Belagerungsmaschinen! An der Westküste bei Garroshs Landeplatz ham wir schwere Panzer stationiert. Wir werden Euch zu diesen Panzern bring'n und Ihr werdet einen davon benutz'n, um der Geißel zu zeig'n, was passiert, wenn die Horde Gerechtigkeit walt'n lässt!\n\nDer einzig schwierige Teil des Ganzen wird's sein, Euch dorthin zu bring'n. Kommt nich' in Frage, dass wir Euch auf einem unserer Windreiter dorthin schick'n. Zu riskant.\n\nSeht Ihr das Feenwesen da drüben? Den elfischen Blondschopf? Yanni heißt der, Maan. Er kann Euch sicher zur Küste bring'n. Sprecht mit Vernichter Grek'lor, sobald Ihr dort seid!", progress = nil, completion = "DEN TOTEN KEINE GNADE!\n\nKeiner von denen hatte den Mumm, zurückzubleiben und unsere prächtigen Panzer zu verteidigen, nachdem Höllschrei die Küste für 'verdammt' erklärte. Zumeist ist es hier ruhig, da sich die Geißel gerade neu formiert, um schließlich die Kriegshymnenfeste anzugreifen. Manchmal begegnet mir ein vereinzelter Zombie oder Ghul, aber die machen's normalerweise nicht lange.\n\nNatürlich ist da dann auch der Nebel...\n\n&lt;Grek'lor erschaudert.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11637] = {title = "Kaganishu", objective = "Findet Kaganishus Fetisch und wendet ihn auf die Überreste von Scharfseher Grimmläufer an.\n\nIhr werdet nach Magmut gehen und den Fetisch Scharfseher Grimmläufers Geist geben müssen.", description = "Nachdem mein kleiner Trupp Grunzer getötet wurde, schleppte man mich hier runter und vollzog ein Ritual, an dessen Ende mein Tod stand. Derjenige, der dafür verantwortlich ist, heißt Kaganishu.\n\nIhr habt zwar seine Schamanengehilfen bezwungen, doch mein Geist ist noch immer an diesen Ort gebunden. Nachdem er mich erschlug, nahm er meinen Körper und erschuf daraus einen Fetisch, der mich jetzt hier gefangen hält. Mit seiner Hilfe lernt Kaganishu all das, was ich über Schamanismus weiß.\n\nIhr müsst ihm den Fetisch wegnehmen und ihn auf meinen Geist anwenden. Kaganishu befindet sich in den Höhlen hier in der Nähe.\n\nNur dann werde ich wirklich frei sein.", progress = "Beeilt Euch, <Klasse>, wendet den Fetisch auf mich an, bevor es zu spät ist.", completion = "Ich bin frei. Vielen Dank, &lt;Name&gt;.\n\nUnd nun habe ich eine letzte Bitte an Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11638] = {title = "Bringt meine Überreste zurück", objective = "Bringt Scharfseher Grimmläufers Überreste, die zu Füßen seines Geistes liegen, zur Geisterflüsterin Fletschfang im Außenposten Bor'gorok.", description = "<Name>, würdet Ihr, nun da mein Geist befreit wurde, mir die Ehre erweisen und meine Überreste zu Geisterflüsterin Fletschfang bringen? Sie liegen auf dem Boden zu meinen Füßen.\n\nIch spüre, dass die Geisterflüsterin sich noch immer im Außenposten Bor'gorok gen Westen befindet, dort wo ich sie zum letzten Mal sah.", progress = "Ihr kehrt früher zurück, als ich erwartet habe. Was habt Ihr erfahren können?", completion = "Ich danke Euch dafür, dass Ihr seinen Geist aus Kaganishus Griff befreit habt und mit seinen Überresten zurückgekommen seid. Wir verfügen über wenig, mit dem wir Euch belohnen könnten, doch Ihr dürft nehmen, was auch immer Ihr zu Gesicht bekommt.\n\nUnd nun werde ich ihn zurück zu den Lebenden befördern - dort wo er hingehört.", rewards = "Zweig der ewigen FlammeGewehr des verlorenen SchützenAuf Euch wartet eine dieser Belohnungen:\n\nTrockener Erdenkreis\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11639] = {title = "Rache an Magmut", objective = "Tötet 10 Schamanen der Magmut, 5 Futterwühler der Magmut, 3 Zermalmer der Magmut und 3 Gefährtinnen von Magmutregar. Kehrt anschließend zu Ortrosh im Außenposten Bor'gorok zurück.", description = "Der Oberanführer verbietet dem Schamanen, meine Wunden zu heilen. Er sagt, es sei eine gute Lektion für mich und gebe mir Zeit, um über mein Versagen nachzusinnen.\n\nDoch Ihr könntet mich und all jene, die in Magmut fielen, rächen!\n\nIch weiß, dass die Geisterflüsterin will, dass Ihr Euch dorthin begebt und den Weissager befreit.\n\nEs ist ganz in der Nähe im Osten. Geht, <Klasse>... Geht und erschlagt die Magnatauren und ihre Schneebolddiener. Stellt die Ehre des Außenpostens wieder her!", progress = nil, completion = "Die Toten werden durch unsere Taten geehrt, &lt;Name&gt;.\n\n\n\nVielleicht kann ich jetzt wieder zu dem Krieger werden, der ich einst war.", rewards = "Mehrlagige FrosttunikaVerstärkter Helm aus KaribubälgenStachelmantel von MagmutBernsteinplattenbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11640] = {title = "Worte der Macht", objective = "Bringt die Rolle von Hohepriester Naferset, die Rolle von Hohepriester Talet-Kha und die Rolle von Hohepriester Andorath zu Häuptling Orkan in Taunka'le.", description = "In den Säulen, die Ihr beschrieben habt, hausen die Oberleutnants des Anführers der Geißel: die Hohepriester. Sie befehligen nicht nur die Truppen der Geißel, sondern besitzen auch den Schlüssel zur Nekropole über ihnen und damit auch zum Meister.\n\nEin endloser Strom von Dienern der Geißel wird uns überrennen, wenn wir nicht ihren Anführer finden und besiegen können. Ich kann meine Leute nicht schutzlos zurücklassen, egal wie sehr Durm auch den Kampf zum Feind tragen möchte. Es fällt also Euch zu, <Name>, die Hohepriester zu töten und die Schriftrollen, die sie bei sich tragen, an Euch zu nehmen.", progress = "Wir müssen in diese Nekropole hineinkommen, wenn wir durch die Reihen der Geißel brechen wollen und den Weg für die Dorfbewohner freimachen wollen.", completion = "&lt;Häuptling Orkan liest den Text, der auf den Schriftrollen geschrieben steht.&gt;\n\n'Shabtir bakh sokhen.'\n\nWorte der uralten, harten Sprache der Neruber und derjenigen, die darin begabt sind.\n\n'Der Diener unterwirft sich des Meisters Autorität.' Dies sind die Worte, die Euch den Eintritt in die Nekropole gewähren werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11641] = {title = "Ein mutiger Schlag", objective = "Erschlagt 15 Ghule der En'kilah und 5 Nekromanten der En'kilah und meldet Euch dann wieder bei Durm Eisbalg. Er befindet sich in Taunka'le.", description = "Von Anfang an habe ich dazu geraten, dass Häuptling Orkan unsere mächtigen Krieger sammeln und unseren Feind in seiner Basis angreifen soll. Mein Ratschlag drang in taube Ohren und er hat bewiesen, dass er lieber Zeit verplempert, wie es die Weise Aeire vorgeschlagen hat.\n\nIch werde nicht länger warten. Wenn Häuptling Orkan zu feige ist, unsere Krieger in die Schlacht zu schicken, dann werdet vielleicht Ihr dazu bereit sein, ihm zu zeigen, dass ein Frontalangriff Erfolg haben kann. Erstürmt die Tempelstadt En'kilah und erschlagt alles, was sich Euch in den Weg stellt, <Name>.", progress = nil, completion = "Ihr habt Eure Furchtlosigkeit bewiesen und Euer Können im Kampf gezeigt. Ich glaube, dass Ihr einen guten Krieger der Taunka abgeben würdet. Ich wünschte nur, dass der Häuptling dasselbe Verständnis aufbringen könnte.\n\nAngesichts der Tatsache, dass wir verzweifelt versuchen das Dorf zu evakuieren, bevor es von der Geißel überrannt wird, können wir uns glücklich schätzen, Euch als Verbündeten an unserer Seite zu wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11642] = {title = "Panzer reparieren sich nicht von selbst", objective = "Sprecht mit Mobu auf Garroshs Landeplatz.", description = "Wir müssen diese Panzer wieder zum Laufen bringen! Die werden sich nicht von selbst reparieren. Mobu wird sich darum kümmern. Sprecht mit ihm und seht nach, was er braucht. Vielleicht könnt Ihr ihn dazu bringen, endlich seinen Mund zu halten, bevor er mich endgültig zum Ausrasten bringt und ich ihn entzwei spalte!", progress = nil, completion = "Ihr seid der neue Panzerfahrer? Ich hab' nichts dagegen! Wir müssen diese Dinger nur wieder zum Laufen bringen. Ähm, ja, wenn Ihr Euch ohne Panzer auf die Ebene von Nasam wagt, seid Ihr so gut wie tot.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11643] = {title = "Mobus pneumatisches Panzertransjigamarick", objective = "Mobu an der Echoküste in der Boreanischen Tundra möchte, dass Ihr sein pneumatisches Panzertransjigamarick beschafft.", description = "Die Schraubenschlüssel sind zu nichts zu gebrauchen, <Klasse>. Ich brauche mein pneumatisches Panzertransjigamarick, um diese Dinger wieder zum Laufen zu bekommen! Unglücklicherweise hab ich es in meiner alten Bude auf der anderen Seite dieses Landeplatzes gelassen. Das ist die heruntergekommene Hütte neben den Ställen. Ihr werdet dorthin gehen und sie für mich holen müssen, weil ich in diesem Nebel ganz sicher nirgendwo hingehen werde.\n\nOh ja, <Klasse>, nehmt Euch vor dem Nebel in Acht. Der Nebel ist es, der diese Küsten in Stücke riss.", progress = "Habt Ihr das P.P.T. gefunden?", completion = "Gute Arbeit, &lt;Klasse&gt;! Wo hab' ich nur diese Ersatzteile gelassen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11644] = {title = "Superstarke Metallplatten!", objective = "Mobu an der Echoküste in der Boreanischen Tundra möchte, dass Ihr 10 superstarke Metallplatten sammelt.", description = "Ich brauche Metall, um diese Panzer zusammenzuflicken! Superstarke Metallplatten liegen überall auf Garroshs Landeplatz und auf dem Grund der Bucht verstreut.\n\nSeid nur vorsichtig, wenn Ihr dort draußen seid und nach Platten sucht. Der Nebel ist... ähm... AGGRESSIV! Der Nebel war es, der den Landeplatz und die angrenzende Tuskarrsiedlung zerstörte. Arme, kleine Tuskarr...", progress = "Vergesst nicht: Der Nebel ist böse!", completion = "Gute Arbeit, &lt;Klasse&gt;! Wo hab' ich nur diese Ersatzteile gelassen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11645] = {title = "Dreckige, stinkende Schneebolde!", objective = "Bringt 10 von Pfiffis Werkzeugen zu Pfiffi Wackelspross. Sie befindet sich bei der Landebahn Kurbelzisch.", description = "Diese dreckigen, stinkenden Schneebolde... die haben alle meine Vorräte geklaut!\n\nWelche Schneebolde fragt Ihr? Sie sehen wie Kobolde aus, nur, dass sie den Magnatauren dienen, irgendwie sogar auf sie Acht geben. Ich weiß - seltsam!\n\nAber egal. Wollt Ihr mir aushelfen? Ich weiß, dass die kleinen Kriecher sich mit meinem ganzen Zeugs davongestohlen haben. Dumm von mir zu denken, dass sie an der Nordseite des Landeplatzes sicher wären.\n\nWieso tut Ihr mir nicht einen Gefallen und begebt Euch in Richtung Norden zu ihrem dummen Magnamut. Ich werde auch Gold dafür lockermachen, wenn Ihr mir all mein Zeug schnell zurückbringt!", progress = "Habt Ihr alle meine Vorräte dabei, <Klasse>? Ich kann einfach NICHTS machen, wenn ich nicht all mein Zeug hab'!", completion = "Oh, &lt;Name&gt;, Ihr seid einfach der Beste!\n\nHier, wie versprochen: Eure Bezahlung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11646] = {title = "Die Boreanische Inquisition", objective = "Donathan hat Euch befohlen, Bibliothekar Normantis Eure Hilfe anzubieten. Er befindet sich im Magierturm auf dem Bernsteinflöz.", description = "Hört genau zu, <Name>, denn wir haben keine Zeit zu verlieren.\n\nEuer Gefangener wird hier in unserem Turm auf die Vernehmung vorbereitet. Eure Hilfe könnte vonnöten sein, falls wir uns begrenzter Zusammenarbeit gegenübersehen.\n\nMacht Euch auf den Weg dorthin, wo er festgehalten wird, und sagt Bibliothekar Normantis, dass ich Euch zu seiner Unterstützung geschickt habe.", progress = nil, completion = "Es war weise von Donathan, Euch zu schicken, &lt;Klasse&gt;.\n\nWie sich zeigt, habe ich gerade Verwendung für jemanden außerhalb der Kirin Tor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11647] = {title = "Die Kessel neutralisieren", objective = "Die Weise Aeire in Taunka'le möchte, dass Ihr mithilfe ihres Totems den Kessel im Osten, den Kessel in der Mitte und den Kessel im Westen der Tempelstadt En'kilah neutralisiert.", description = "Die Seuchenkesseln innerhalb der Tempelstadt En'kilah bereiten mir große Sorgen, <Name>. Es steht fest, dass Häuptling Orkan Eurem Urteil und Wissen über unseren Feind traut. Würdet Ihr mir bei den Kesseln zur Hand gehen, wenn Ihr schon dabei seid, dem Häuptling bei der Umsetzung seiner Pläne in der Tempelstadt zu helfen?\n\nIch habe ein Totem vorbereitet, das den Inhalt der Kessel angreift und neutralisiert. Alles, was Ihr tun müsst, ist, die Kessel zu finden und das Totem bei jedem zu benutzen. Jede Waffe der Geißel, die wir zerstören, bringt uns dem Sieg einen Schritt näher.", progress = nil, completion = "&lt;Die Weise Aeire nimmt das Totem von Euch entgegen.&gt;\n\nHat das Totem funktioniert? Es vorzubereiten hat uralte Magie beansprucht, die von den Weisen seit Generationen nicht mehr angewandt wurde. Von all dem überlieferten Wissen findet heute nur noch ein Bruchteil Anwendung.", rewards = "Mehrlagige Kapuze des FrostsRhinozerosgelenkbänderStachelhandschuhe von MagmutGekühlte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11648] = {title = "Überredungskunst", objective = "Bibliothekar Normantis vom Bernsteinflöz möchte, dass Ihr den Neuralinjektor so lange auf den eingesperrten Beryllzauberer anwendet, bis er den Aufenthaltsort von Lady Evanor verrät.", description = "Wie praktisch, dass Ihr hier seid, <Volk>.\n\nIhr müsst verstehen, dass der Verhaltenskodex der Kirin Tor unser Ergreifen 'extremer' Mittel nicht duldet - selbst in Zeiten der Verzweiflung wie diesen.\n\nIhr jedoch als Außenstehender seid nicht an solche Einschränkungen gebunden und könntet jedes Mittel einsetzen, um an Informationen heranzukommen.\n\nTut, was Ihr tun müsst. Wir müssen umgehend in Erfahrung bringen, wo Lady Evanor gefangen gehalten wird!\n\nIch werde mich in der Zwischenzeit mit dem Ordnen dieser Regale beschäftigen. Oh ja, und hier, vielleicht nützt Euch dieses alte Ding...", progress = "Nun? Wisst Ihr, wo sich Lady Evanor aufhält?", completion = "Ausgezeichnet! Es war äußerst wichtig, dass wir diese Informationen erhalten.\n\nGut gemacht, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11649] = {title = "Partikel der Wutentbrannten", objective = "Beschafft 5 Sturmpartikel und bringt sie zu Imperean in den Ruinen von Eldra'nath.", description = "Da wir uns um ihre kleine Streiterei gekümmert haben, bleibt noch übrig, dass wir Euch und Eurer Geisterflüsterin helfen.\n\nWie Ihr seht, wurden meine Vasallen vom anhaltenden Krieg zwischen Feuer und Wasser erzürnt. Das wird sich so bald auch nicht ändern, doch für Euch wird es von Vorteil sein.\n\nUm Euch zu helfen, benötigen wir ihre Partikel. Dringt tiefer in die Ruinen ein und beschafft sie Euch von den Sturmwesen.", progress = "Sobald Ihr die benötigten Partikel habt, werde ich sie mit einem Teil meiner Essenz verbinden. Das Resultat wird Euch das geben, was Ihr benötigt.", completion = "Ich bedauere den Verlust dieser Sturmwesen, doch ich halte mein Wort... selbst gegenüber einem Sterblichen wie Euch.\n\nNun lasst uns doch mal sehen, ob wir etwas Nützliches fertigen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11650] = {title = "Nur noch ein paar Kleinigkeiten...", objective = "Findet Pfiffis Werkzeuge, einen überladenen Kondensatoren und eine Handvoll von Felsnars Kies. Bringt dies alles zu Pfiffi Wackelspross, die sich auf Kurbelzischs Landebahn aufhält.", description = "Wie Ihr vielleicht gemerkt habt, haben wir den Landeplatz auf der südlichen Grenze eines Magnataurenbaus errichtet!\n\n<Pfiffi murmelt etwas Gemeines über Kurbelzisch.>\n\nDer Alte hat mir die Verantwortung übertragen, eine... ähhm... kreative Lösung für dieses Problem zu finden. Denn wenn wir nicht bald was gegen sie unternehmen, werden sie runterkommen und uns alle Gliedmaßen einzeln ausreißen!\n\nHier kommt Ihr also ins Spiel. Ich möchte, dass Ihr mir alles auf dieser Einkaufsliste besorgt. Bitte.", progress = "Wieso fällt es mir schwer, Euch zu glauben, dass Ihr alle Gegenstände auf meiner Liste eingesammelt habt?", completion = "Nun gut, das ist schon besser! Das Einzige, was wir jetzt noch machen müssen, ist, all das Zeugs hier zusammenzubauen.\n\nJa, alles klar, als ob Ihr mir dabei helfen würdet.\n\nImmer mit der Ruhe, das wird nur 'ne Sekunde dauern, da ich ja jetzt meine Werkzeuge wieder habe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11651] = {title = "Danke vielmals...", objective = "Sprecht mit Vernichter Grek'lor an der Echoküste.", description = "Vielen Dank für all Eure Hilfe, Kumpel. Ihr könnt Grek'lor sagen, dass die Panzer einsatzbereit sind. Hoffentlich könnt Ihr diesen Ort ein für alle Mal säubern!", progress = nil, completion = "Aufgrund des gegenwärtigen Zustands unserer Transport- und Schiffswege, konnten wir keine einzige Belagerungsmaschine zur Kriegshymnenfeste schaffen. Diese Panzer sind alle, die von der ursprünglichen Expedition übrig geblieben sind. Nun, da sie einsatzbereit sind, werdet Ihr sie dazu benutzen, die Offensive in der Ebene von Nasam zurückzuschlagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11652] = {title = "Die Ebene von Nasam", objective = "Tötet mithilfe des Belagerungspanzers der Horde 100 Soldaten der Geißel und rettet 3 verletze Soldaten des Kriegshymnenklans auf der Ebene von Nasam. Außerdem müsst Ihr herausfinden, wer der Anführer des Angriffs der Geißel ist.\n\nMeldet Euch bei Garrosh Höllschrei in der Kriegshymnenfeste, solltet Ihr Erfolg haben.", description = "Springt in einen der Panzer und fahrt auf die südlich von hier gelegene Ebene von Nasam, sobald Ihr bereit seid.\n\nMacht vom Waffenarsenal des Panzers Gebrauch, um die Armee der Geißel auszuschalten. Solltet Ihr in Schwierigkeiten geraten, wird sie der \"Fleischklopfer\" in Stücke reißen und die Landminen werden ihnen den Todesstoß versetzen! Sollten Euch ein paar unserer Soldaten über den Weg laufen, dann schnappt sie Euch! Und noch etwas: Überall in dem Gebiet können Treibstofftanks gefunden werden.\n\nVersucht nah genug an das Gebäude in der Mitte heranzukommen und seht nach, was dort vor sich geht.\n\nGeht zu Höllschrei, falls Ihr das alles durchsteht!", progress = nil, completion = "Kel'Thuzad? Es ist also wahr - Naxxramas kehrt wieder zurück...\n\nVielleicht habe ich Euch unterschätzt, &lt;Name&gt;. Ihr habt der Horde einen großen Dienst erwiesen. Der Kriegshäuptling wäre stolz auf Euch!\n\n\n\nWenn Kel'Thuzad diese Diener der Geißel kontrolliert, ist nicht abzusehen, was der Lichkönig sonst noch für uns auf Lager hat... Ich brauche Zeit, um mir diese neue Information durch den Kopf gehen zu lassen, &lt;Name&gt;. Ihr könnt wegtreten.", rewards = "Grek'lors HausanzugSchiftung des KriegshymnenspähersTreter des PanzerkommandantenGrek'lors Brustplatte des BlutfurorsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11653] = {title = "Ha! ... Jetzt seid Ihr nicht mehr so groß!", objective = "Testet Pfiffis ultrafortschrittlichen prototypischen Verkürzungsblaster an 5 Zermalmern der Magmut oder Gefährtinnen von Magmutregar aus. Kehrt wieder zu Ihr zurück, sobald Ihr das erledigt habt. Sie befindet sich auf der Landebahn Kurbelzisch.", description = "Das wird's ihr zeigen, <Chef/Chefin>! So, das hier müsst Ihr also für mich machen...\n\nNehmt meinen Blaster und begebt Euch in Richtung Norden nach Magmut. Wenn wir irgendeine Chance gegen diese Monster haben wollen, dann müssen wir sie einen Kopf kürzer machen... um es mal so zu sagen.\n\nUm abzuschätzen, wie effektiv das ist, müsst Ihr für mich die Magnatauren töten, während die Effekte des Blasters noch immer auf sie wirken. Die Zermalmer oder Gefährtinnen werden genügen, den Nachwuchs könnt Ihr ignorieren... die sind zu klein, um sich darüber Sorgen machen zu müssen.", progress = "Seid Ihr Euch sicher, dass Ihr den Blaster an genug dieser monströsen Biester ausgetestet habt?", completion = "Was meint Ihr damit: Es hat nicht funktioniert?!\n\nAber... aber...\n\n&lt;Pfiffi fängt an zu weinen.&gt;\n\nOkay, damit können wir fertig werden. Ich bin ein großes Mädchen. Zeit, über den Tellerrand hinaus zu sehen!", rewards = "Wizzelnobs SchulterbedeckungVerstärktes GummibandRingbesetzte HandgelenksschützerAuf Euch wartet eine dieser Belohnungen:\n\nDünne Geschicklichkeitsverstärkende Spule\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11654] = {title = "Die Säule des Blutes", objective = "Sucht in der Säule des Blutes nach weiteren Informationen über die Phiole mit frischem Blut.", description = "Als Ihr die Phiole mit Blut, die Ihr gefunden habt, untersucht, fällt Euch auf, dass der Inhalt noch immer warm ist. Das Opfer muss gerade eben erst Blut gelassen haben und noch immer am Leben sein.\n\nWelchen Nutzen hat die Geißel für Blut? Sie waren in der Vergangenheit nie an lebenden Gefangenen interessiert. Wenn Ihr den Ursprung des Blutes finden könnt, dann könnt Ihr vielleicht herausfinden, was die Geißel vorhat.", progress = "Wie... wie habt Ihr mich gefunden?", completion = "&lt;Der Schneefährtenleser der Taunka wirkt geschwächt und kann Euch gerade noch antworten.&gt;\n\nIch habe nicht... lange. Vielleicht... Vielleicht könnt Ihr sie aufhalten... bevor...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11655] = {title = "In den Nebel hinein", objective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr Kvaldir tötet und 8 Relikte der Tuskarr beschafft.", description = "Auf der anderen Seite des Nebels gen Norden werdet Ihr Garroshs Landebahn vorfinden. Im Süden liegen die Ruinen meiner alten Heimat Pal'ea. Beide Orte wurden von den Kvaldir, einer uralten Macht, ausgeplündert.\n\nDiese Furcht erregenden Barbaren erschlugen gnadenlos alle meine Brüder und Schwestern und trieben Eure Leute ins Landesinnere.\n\nAlles, was von den Tuskarr aus Pal'ea übrig bleibt, sind die persönlichen Hinterlassenschaften, Relikte sozusagen, die von den Kvaldir mitgenommen wurden. Wir sind zwar kein rachsüchtiges Volk, doch Gerechtigkeit muss walten. Die Relikte der Tuskarr müssen zu mir zurückgebracht werden. Begebt Euch in den Nebel und findet sie...", progress = "Mit Blut und Ruhm müsst Ihr dienen... Bringt die Relikte der Tuskarr wieder zurück.", completion = "&lt;Waltor wird von Trauer ergriffen.&gt;\n\nSchutt und Asche... das ist alles, was sie zurückgelassen haben. Ihnen muss eine Lektion erteilt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11656] = {title = "Setzt ein Zeichen und verbrennt sie", objective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr die Tuskarrfackel benutzt und die Schiffe der Kvaldir bei Pal'ea und Garroshs Landeplatz verbrennt. Ihr müsst die folgenden Schiffe verbrennen: Die Schlangenschlund, die Kur Drakkar, die Bors Hammer und die Bors Amboss.", description = "Die Magie der Tuskarr ist dem Schamanismus, wie er von Eurem Volke genannt wird, ähnlich. Während wir den Elementen im Vergleich zu Euch auf verschiedene Art und Weise dienen, ist die Macht, die wir beschwören können, eindrucksvoll.\n\n<Waltor hantiert mit einem fackelähnlichen Stab vor Euch herum.>\n\nIch möchte, dass Ihr mit dieser Tuskarrfackel in den Nebel zurückkehrt und einen Schlag gegen die Schiffe der Kvaldir führt. Ihr werdet drei ihrer Schiffe gen Norden, bei Garroshs Landeplatz auf der anderen Seite des Nebels, angedockt vorfinden, und ein weiteres in Richtung Süden, vor der Küste Pal'eas. Steckt ihre Schiffe in Brand und setzt damit ein Zeichen! Damit es ein jeder sehen kann!", progress = nil, completion = "Den Kvaldir zu zeigen, dass wir ihnen Widerstand leisten, ist vielleicht das, was wir brauchen, um mein Volk in den anderen Lagern zu retten. Vielleicht werden die Kvaldir ihr Handeln überdenken, wenn sie glauben, dass es Vergeltung nach sich ziehen wird.", rewards = "Stiefel des SeefahrersBeinschützer des MeeressprechersMeeresknochentopfhelmAuf Euch wartet eine dieser Belohnungen:\n\nTalisman der Tundra\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11657] = {title = "Fackeln fangen", objective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Freudenfeuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier nacheinander und kommt wieder zu mir zurück.\n\nSeid vorsichtig! Die Fackeln sind gefährlich, wenn sie auf dem Boden aufkommen! Und fangt sie alle auf! Wenn eine davon auf den Boden fällt, müsst Ihr zurück zum Freudenfeuer und von vorn anfangen. Viel Glück.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", rewards = "Ihr bekommt:\n\nJonglierfackelBrandblüte"}
MultiLanguageQuestData['de'][11658] = {title = "Plan B", objective = "Sammelt 10 Kriegshymnenausrüstungen und ein Kriegshymnenbanner. Bringt sie zurück zu Pfiffi Wackelspross an der Landebahn Kurbelzisch.", description = "Okay, keine Panik! Der Blaster hat vielleicht nicht funktioniert, aber uns stehen noch immer Möglichkeiten offen.\n\n<Pfiffi schnippt mit den Fingern.>\n\nWir werden die Aufmerksamkeit von der Landebahn weglenken! Um das zu bewerkstelligen, brauchen wir zuerst ein paar Dinge.\n\n<Wackelspross mustert Euch von Kopf bis Fuß.>\n\nStahlkiefers Karawane gleich im Westen hat dummerweise eine Abkürzung durch einen Taunkafriedhof genommen und wurde von deren wiederauferstandenen Geistern zerstört.\n\nBegebt Euch dorthin und nehmt den toten Orcs ein paar Gewänder ab. Nehmt auch eines ihrer Banner mit!", progress = "Wir werden viele ihrer Gewänder brauchen, wenn das hier funktionieren soll... Wir müssen einfach nur etwas finden, das Euch passt!\n\nUnd dann werd' ich einfach mal einen Hauch meiner genialen Ingenieursfertigkeit hinzufügen und puff ist Euer Aussehen wie für die Rolle, die Ihr spielen müsst, geschaffen.", completion = "Fein, aber diese Kleider stinken!\n\nMich persönlich würdet Ihr nie und nimmer in solchen Fetzen rumrennen sehen. Aber wir werden aus all den Dingern eines heraussuchen müssen, dass zu Eurer... Figur passt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11659] = {title = "Zerschmettert die Kugeln!", objective = "Zerstört 5 Blutkugeln und meldet Euch anschließend bei Schneefährtenleser Junek in Taunka'le.", description = "Sie lassen... die Gefangenen ausbluten... geben das Blut... in diese Kugeln.\n\n<Grumm schließt kurz die Augen und lehnt seinen Kopf zurück.>\n\nDas Blut... hoch zur Nekropole gebracht... um Blutprinzen satt zu machen...\n\n<Grumm ringt nach Luft.>\n\nVer-Versprecht mir... dass Ihr... Blutkugeln... zerstört... Nachricht an... Junek.\n\n<Der Schneefährtenleser fällt in Ohnmacht.>", progress = nil, completion = "Ich hatte befürchtet, dass sie Grumm gefangen genommen haben, doch ich hätte niemals gedacht, dass sie ihm solch schreckliche Dinge antun würden. Ich habe noch nie miterlebt, dass ein Krieger eine verlorene Schlacht mit der Geißel überlebt.\n\nIch danke Euch dafür, mir berichtet zu haben, welch Schicksal ihn ereilte, &lt;Name&gt;. Er war ein mächtiger Krieger und wir werden ihn als solchen in Erinnerung behalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11660] = {title = "Horn des uralten Seemanns", objective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr ihm das Horn des uralten Seemanns bringt.", description = "Ein Leutnant der Kvaldir namens Orabus führte den Überfall auf mein Volk bei Pal'ea an. Er beaufsichtigte die Zerstörung beider Dörfer und verschwand anschließend im Nebel.\n\nIn diesen ersten Tagen ging das Wort um, dass ein Horn existiere, das Orabus den Nebelwirkern der Kvaldir zum Geschenk machte. Dieses Horn kann dazu benutzt werden, ihn, falls nötig, zu beschwören.\n\nWir müssen dieses Horn den Nebelwirkern der Kvaldir wegnehmen und Orabus heraufbeschwören. Wenn er zerstört ist, könnten sich die Barbaren vielleicht zurückziehen.\n\nSucht nach den Nebelwirkern im südlich gelegenen Pal'ea.", progress = "Findet das Horn des uralten Seemanns!", completion = "Ihr müsst mithilfe des Horns des uralten Seemanns Orabus anrufen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11661] = {title = "Orabus der Steuermann", objective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr mithilfe des Horns des uralten Seemanns Orabus den Steuermann beschwört. Erschlagt Orabus den Steuermann, sobald er beschworen ist.", description = "Nehmt das Horn an Euch und reist gen Westen zur Landebrücke des Kriegshymnenklans. Geht zum Ende der Landebrücke, presst das Horn an Eure Lippen und stoßt hinein. Das Geräusch sollte Orabus wecken.\n\nErschlagt das grauenhafte Ungetüm und kehrt zu mir zurück!", progress = nil, completion = "Es scheint, als hätte der Verlust ihres Leutnants sie nur wachgerüttelt. Sie sind wütender und aggressiver als je zuvor!\n\n&lt;Walter seufzt.&gt;\n\nIhr habt getan, was in Eurer Macht stand, &lt;Klasse&gt;. Das Allermindeste, was Ihr verdient habt, ist eine Entschädigung dafür, dass Ihr sie dezimiert habt.", rewards = "Transboreanische ArmschienenWeste der FlutebenenTreter des BettelmönchsAuf Euch wartet eine dieser Belohnungen:\n\nHalsschmuck des Streitlustigen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11662] = {title = "Sucht nach Karuk!", objective = "Sucht Karuk am Strand der Peitschennarbe auf.", description = "Ein weiterer Überlebender von Pal'ea mit Namen Karuk hat sich auf den Weg zur Hauptbasis der Kvaldir in der Boreanischen Tundra gemacht - weit südlich von hier, dort, wo der Schnee einst reichlich war. Karuk versteckt sich irgendwo auf den Klippen, die am Strand der Peitschennarbe emporragen.\n\nSucht nach Karuk und lasst ihn wissen, was Ihr hier an der Echoküste für mein Volk geleistet habt.\n\nDer sicherste Weg zu Karuk führt durch Eure Festung. Von der Kriegshymnenfeste aus folgt Ihr der Straße in Richtung Süden bis zum Strand der Peitschennarbe.", progress = nil, completion = "Es war klug von Waltor, Euch zu mir zu schicken, &lt;Volk&gt;. Die Götter schenken denjenigen ein Lächeln, die Gerechtigkeit walten lassen. Ihr werdet derjenige sein, durch welchen die Boshaften ihre gerechte Strafe erhalten werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11663] = {title = "Geheime Nachrichten teilen", objective = "Normantis möchte, dass Ihr Euch bei Bibliothekar Donathan auf dem Bernsteinflöz meldet.", description = "Ich danke Euch, <Klasse>! Die Informationen, die Ihr herausbekommen habt, sind von entscheidender Bedeutung für die Kirin Tor.\n\nKehrt umgehend zu Donathan zurück, während wir uns Gedanken darüber machen, wie wir Lady Evanor nun befreien können.", progress = nil, completion = "Vergebt mir, &lt;Name&gt;. Ich weiß, dass das unangenehme Arbeit war.\n\nWäre unsere Lage hier nicht so verzweifelt, hätte ich Euch nie darum gebeten, uns auf solch einer Art und Weise beizustehen.\n\nSo... Was habt Ihr entdeckt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11664] = {title = "Flucht aus dem Nebel", objective = "Begleitet Muhtoo die Jüngere und helft ihr, aus dem Nebel herauszukommen. Sprecht mit dem Ältesten Muhtoo, solltet Ihr Muhtoo die Jüngere in Sicherheit gebracht haben.", description = "Ich kann die Kreaturen des Nebels draußen hören. Ihre Schreie treiben mich in den Wahnsinn, doch eine Flucht will ich nicht wagen. Und wo würde ich überhaupt hingehen? Wie lange würde es dauern, bis sie mich einholen und wie die anderen hinrichten?\n\nWie weit, so frage ich mich, ist der Nebel eigentlich schon gekrochen, <Fremder/Fremde>? Hat er schon den gesamten Kontinent erfasst?\n\nWäret Ihr willens, mir dabei zu helfen, dem Nebel zu entfliehen? Ich denke, dass ich uns zurück zu meinem Vater führen kann. Ich spüre seinen Lebensgeist noch immer. Er befindet sich in der Nähe.", progress = nil, completion = "Die Winde flüstern es, &lt;Name&gt;. Euer Name ist den Elementen bekannt. Ihr habt Muhtoo an diesem heutigen Tage einen großen Dienst erwiesen und sollt dafür belohnt werden.", rewards = "Transboreanische WickeltücherSchulterpolster der FlutebenenHandgelenksschützer der WestklammIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11665] = {title = "Krokilisken in der Stadt", objective = "Bringt dem alten Barlo ein Krokiliskenbaby. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", description = "Hallo, <Junge/Mädchen>. Ich bin froh, dass Ihr vorbeigeschaut habt, um mit einem alten Mann zu sprechen - zuhause gibt es Schwierigkeiten.\n\nEin fliegender Händler hat neulich eine Ladung Krokiliskenbabys an ein paar leichtgläubige Kinder verkauft. Krokilisken sind wilde Bestien. Viele sind entkommen und halten sich jetzt in den Wasserwegen der Stadt verborgen.\n\nNehmt Eure stärkste Angelrute, werft sie in Sturmwind oder Orgrimmar aus und bringt einen der kleinen Teufel zurück zu mir. Ich kann es kaum erwarten, einen zu sehen.", progress = "Schon Kroks in den Abwasserkanälen gefangen?", completion = "Was für eine miese kleine Kreatur! Ich bin mir sicher, dass der Rokk irgendwas Leckeres aus ihr machen wird.\n\nIch mach natürlich nur Spaß.\n\n&lt;Der alte Barlo zwinkert neckisch.&gt;", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][11666] = {title = "Köderbanditen", objective = "Bringt dem alten Barlo einen schwarzen Stachelflosser. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", description = "Ihr wisst wahrscheinlich alles über den goldenen Stachelflosser - in den Flüssen von Terokkar kommen sie recht häufig vor, außerdem sind sie eine Delikatesse für Priester. Es gibt jedoch einen, von dem Ihr noch nicht gehört habt: den schwarzen Stachelflosser.\n\nDer Fisch ist berüchtigt für seine Gerissenheit und dafür, dass er schwierig einzufangen ist. Ihr müsst Eure Angelschnur in letzter Sekunde einziehen, denn sie knabbern am Köder, bevor sie sich ihn schnappen.\n\nWerft Eure Angelrute in den Gewässern von Terokkar aus und bringt mir einen schwarzen Stachelflosser. In Seen braucht Ihr gar nicht erst zu suchen - der Flitzer kommt nur in Fließgewässern vor.", progress = "Wie fischt sich's denn heute, mein Junge?", completion = "Nun sieh mal einer an... Ihr habt einen Großen gefangen! Dieser alte Mann wird heute Abend gut essen.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][11667] = {title = "Der Eine, der entkam", objective = "Fangt den größten Matschflosser der Welt und bringt ihn zum alten Barlo. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", description = "Feigenschimmers Matschflosser ist ein erstaunlich schneller Gründler, den man in den Gewässern von Nagrand anfindet. Sie wachsen ihr ganzes Leben lang und sind als Kämpfer sehr bekannt.\n\nVor Jahren fing ich den größten Matschflosser der Welt, da bin ich mir sicher... Doch dann brachte er meine Leine zum Reißen und kam davon.\n\nEinem Angler Eures Kalibers muss man nicht sagen, was zu tun ist - Euer Schicksal erwartet Euch an den Seen von Nagrand.", progress = "Sagt mir, dass Ihr ihn gefangen habt. Bitte sagt mir, dass Ihr den Mistkarpfen gefangen habt.", completion = "Da ist er! Diese Narbe würde ich immer wiedererkennen.\n\nAber um ganz ehrlich zu sein, habe ich ihn mir... größer vorgestellt. Tja - denke, dass ich ihn freilassen und es an einem anderen Tag noch einmal versuchen werde.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][11668] = {title = "Garnelenfangen ist nicht einfach", objective = "Bringt dem alten Barlo 10 riesige Süßwassergarnelen. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", description = "In den Seen der Zangarmarschen gibt es viele große Fische. Habt Ihr Euch jemals darüber Gedanken gemacht, was sie fressen?\n\nGarnelen - riesige Süßwassergarnelen. Der Rokk hat mir erzählt, dass man unendlich viele Garnelengerichte zubereiten kann.\n\nGarnelen sind jedoch zu klein, als dass man sie mit einer Angelschnur fangen könnte. Hier also der Trick: Schneidet eine aufgedunsene Stachelkiemenforelle auf und Ihr werdet, wenn Ihr Glück habt, die eine oder andere Garnele darin finden.", progress = "Was haben wir denn heute gefangen, mein Junge?", completion = "Ihr könnt mit Haken und Messer gut umgehen. Reicht mir die süßen Leckerbissen und ich werde Euch davon kosten lassen.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][11669] = {title = "Teufelsblutfilet", objective = "Bringt dem alten Barlo einen monströsen Teufelsblutschnapper. Ihr könnt Barlo beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", description = "Dieser alte Mann wird bald jagen gehen. Ich werde mir vor Azsharas Küste einen Mammuthai fangen.\n\nDie Sache ist nur, dass ich ein Toxin benötige, das auf einer Speerspitze haften bleibt, wenn man sich unter Wasser befindet. Um so etwas herzustellen, benötige ich die Drüsen eines giftigen Fischs: dem Teufelsblutschnapper.\n\nSolch ein abscheulicher Fisch gedeiht nur in den Gewässern der Höllenfeuerhalbinsel und des Schattenmondtals. Bringt mir das Mordsding und Ihr macht aus mir einen glücklichen alten Mann.", progress = "Der Teufelsblut ist ein Wunder der Evolution. Er kann in allen Gewässern und sogar Lava überleben. Fischer sind seine einzigen natürlichen Feinde.\n\nGlück beim Beutefang gehabt?", completion = "Das ist der größte und hässlichste Fisch, den ich je gesehen habe. Ich kann mir gar nicht vorstellen, was Ihr als Köder benutzt habt.\n\nLegt das Biest einfach auf den Boden und ich werde mich darum kümmern, sobald ich mir sicher sein kann, dass es tot ist.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][11670] = {title = "Es waren die Orcs, ganz ehrlich!", objective = "Spießt Magmutregars Leiche mit dem Kriegshymnenbanner auf, während Ihr als Orc des Kriegshymnenklans verkleidet seid. Kehrt anschließend zu Pfiffi Wackelspross zurück und bringt die Verkleidung mit. Sie befindet sich auf der Landebahn Kurbelzisch.", description = "Ich habe aus all den Gewändern, die Ihr... ähm... gefunden habt, eine Verkleidung gefertigt, mit der Ihr wie ein Orc des Kriegshymnenklans aussehen werdet. Ich hatte die geniale Idee, sie mit ein paar alten Sachen zu kombinieren, die noch von den letzten Schlotternächten herumlagen, also sollte sie idiotensicher sein!\n\nHier, in diesem Sack befindet sich die Verkleidung und das Banner, das Ihr gefunden habt. Begebt Euch ins Innere von Magmut und erschlagt Magmutregar, den Häuptling der Magnatauren.\n\nWenn Ihr sie davon überzeugen wollt, dass sie ihre Aufmerksamkeit den Orcs des Kriegshymnenklans schenken sollen, werdet Ihr das Banner aufstellen müssen, solange Ihr verkleidet seid.", progress = "Es ist also vorbei? Ihr habt die Drecksarbeit gemacht und sie den Orcs vom Außenposten Bor'gorok in die Schuhe geschoben.", completion = "Du lieber Himmel, Ihr habt es getan!\n\nNun gut, diese lästigen Magnatauren und ihre Schneeboldlakaien sollten ihre Aufmerksamkeit auf die Horde richten.\n\nWie kann ich mich dafür jemals bei Euch erkenntlich zeigen, &lt;Name&gt;?", rewards = "FrostbeißerGezackte EisfaustZehrender GroßstabUmhang des frierenden HeilersAuf Euch wartet eine dieser Belohnungen:\n\nHalsschmuck der Frostsprecher\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11671] = {title = "Wettlauf gegen die Zeit", objective = "Donathan vom Bernsteinflöz hat Euch damit beauftragt, mithilfe des Beryllschilddetonators den Schild auf der Beryllspitze zu zerstören. Danach sollt Ihr Salrand besiegen und ihr den Schlüssel abnehmen, den sie bei sich trägt.", description = "Es stimmt also: Sie haben sie.\n\nKeine Frage, was getan werden muss, <Volk>. Wir WERDEN sie befreien.\n\nIch muss hier bleiben und bei den Rettungsvorbereitungen helfen. Also wende ich mich noch einmal an Euch; dieses Mal mit der Bitte, den Gefängnisschlüssel zu finden. Alles, was wir über diese Salrand wissen, ist, dass sie nicht verletzt werden kann, solange ihr Schild noch intakt ist.\n\nWir haben einen speziellen Sprengsatz so präpariert, dass er sie ihres Schutzes berauben wird, damit Ihr Eure Pflicht tun könnt. Kehrt zu mir zurück, wenn Ihr den Schlüssel habt.\n\nBeeilt Euch, <Name>. Lady Evanor erleidet Qualen!", progress = "Habt Ihr Salrands Schlüssel bei Euch?", completion = "Zerbrochen?\n\nLasst mich einmal sehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11672] = {title = "Eingezogen", objective = "Trefft Euch mit General Arlos im Inneren der Kaserne in der Valianzfeste.", description = "Ihr seid zur Einberufung gekommen, richtig? Normalerweise müsstet Ihr genauso wie alle anderen Rekruten in einer Reihe stehen. Normalerweise hättet Ihr Pech, weil das Rekrutierungsregister abhandengekommen ist und ich niemanden aufnehmen kann, bis die neuen Bücher ankommen.\n\nDoch glücklicherweise, <Name>, habe ich von Euch und Euren Taten in der Scherbenwelt gehört. Um ehrlich zu sein, seid Ihr den anderen Trotteln bei Weitem überlegen. In Reih und Glied stehen ist nichts für Euch.\n\nGeht zur Kaserne und sprecht mit General Arlos. Er wird mehr als froh darüber sein, jemanden Eures Kalibers zu treffen.", progress = nil, completion = "Wir haben Eure Ankunft erwartet, &lt;Name&gt;. Willkommen in Nordend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11673] = {title = "Holt mich hier raus!", objective = "Bringt Bonker Wechselvolt in Sicherheit und meldet Euch bei Kurbelzisch Vollgas auf der Landebahn Kurbelzisch.", description = "Ich habe gewusst, dass sie früher oder später jemanden schicken würden... später natürlich, wie sich zeigt.\n\nIch bin hierhergekommen, um mit den Schneebolden zu verhandeln, doch ihr wichtigster Schamane Kaganishu hat sich stattdessen dazu entschlossen, dass ich wohl besser als Leckerbissen für Magmutregar geeignet wäre.\n\nWartet... Wie bitte?! Sie haben Euch gar nicht geschickt?!\n\nHABEN SIE MICH ETWA VERGESSEN?!\n\nOkay, Ihr seid jetzt hier - das ist das einzig Wichtige.\n\nSobald Ihr diese Kette zerbrochen habt, werden wir uns auf den Weg zurück zur Landebahn machen. Dann könnt Ihr Kurbelzisch mitteilen, dass ich heil zurück bin.\n\nDas heißt, falls er sich überhaupt an mich erinnert.", progress = nil, completion = "Hä? Was?\n\nBonker wer?\n\nIch hab' keine Ahnung, von wem Ihr da sprecht, aber ich nehm' Euch beim Wort. Wenn Ihr ihn oder sie aus Magmuts Grube befreit habt, dann nehme ich mal an, Ihr habt Euch eine Belohnung verdient.\n\nLasst mich einmal nachsehen, was hier so herumliegt.", rewards = "Zweig der ewigen FlammeGewehr des verlorenen SchützenAuf Euch wartet eine dieser Belohnungen:\n\nTrockener Erdenkreis\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11674] = {title = "Die Weise Hochmesa wird vermisst", objective = "Findet die Weise Hochmesa in der Nähe der Höhlen des Todes.", description = "Viele neue Rätsel erzählt man sich nun landauf, landab. Eine unserer Weisen, Hochmesa, ist törichterweise mit einem Fernläufer gen Norden gegangen, um etwas Merkwürdiges bei den Höhlen des Todes zu untersuchen.\n\nWas sind das für Höhlen, fragt Ihr? Sie sind ein Heiligtum der Magnatauren, wo diese sich im Alter hinbegeben, um zu sterben. Vor ein paar Tagen sah sie in deren Nähe etwas vom Himmel fallen.\n\nWenn Ihr ein Freund der Taunka seid, so möchte ich Euch bitten, sie zu finden und ihr zu helfen. Sie ist nicht so dickköpfig, dass sie Eure Hilfe ablehnen würde.", progress = nil, completion = "Die Großmutter hat Euch geschickt? Sie muss von mir enttäuscht sein.\n\nDoch als ich das große Objekt vom Himmel fallen sah, konnte ich nicht auf eine ganze Gruppe Fernläufer und Schneefährtenleser als Begleitung warten. Wissen wartet auf niemanden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11675] = {title = "Ein würdiges Ende", objective = "Erschlagt 10 verseuchte Magnatauren und kehrt anschließend zur Weisen Hochmesa gleich südlich der Höhlen des Todes zurück.", description = "Die Magnatauren bei den Höhlen des Todes haben sich mit einer Seuche infiziert. Wir müssen die Ursache finden, doch zuerst müssen wir ihrem Leiden ein Ende setzen.\n\n<Volk>, Ihr müsst in Richtung Norden die Hänge vor uns hinaufgehen und so viele der armen Kreaturen erschlagen wie nur möglich.", progress = nil, completion = "Was können wir sonst machen, außer sie von ihrem Leiden zu befreien? Auf jeden Fall kamen sie hierher, um zu sterben, also trauert nicht um sie. Zumindest habt Ihr sie in Würde sterben lassen.\n\nNun müssen wir der Ursache der Seuche ein Ende bereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11676] = {title = "Gnadenvolle Freiheit", objective = "Schattenpirscher Canarius auf den Höfen des Kriegshymnenklans möchte, dass Ihr 5 Gefangene der Geißel befreit.", description = "Die Soldaten, die sie verschont haben, werden in Käfigen festgehalten, die überall auf diesem Ackerland verstreut herumstehen. Dank einiger Meisterstreiche in Sachen Diebstahl konnten wir zwar an ein paar Schlüssel gelangen, doch wir kommen einfach nicht an die Gefangenen heran, ohne uns Angriffen auszusetzen.\n\nWir benötigen Euer \"Geschick\", um diese Schlüssel zu sichern und die Gefangenen zu befreien. Schlagt den Nekrolords und Monstrositäten die Schädel ein und nehmt ihnen die Schlüssel ab. Befreit anschließend die Gefangenen mit diesen Schlüsseln.", progress = nil, completion = "Jeder befreite Gefangene ist eine untote Monstrosität weniger, um die wir uns kümmern müssen, &lt;Name&gt;. Ihr habt der Horde einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11677] = {title = "Haltet die Seuche auf", objective = "Die Weise Hochmesa gleich südlich der Höhlen des Todes möchte, dass Ihr Hochmesas reinigende Samen auf den Seuchenkessel in den Höhlen des Todes anwendet, um ihn zu neutralisieren.", description = "Ich bin davon überzeugt, dass die Seuche von etwas ausgeht, das sich in den Höhlen dort oben befindet.\n\n<Klasse>, nehmt diese Samen. Normalerweise verwende ich sie zum Schutz gegen die Geißel, doch vielleicht kann man mit ihnen auch die Höhle von all jenen Übeln befreien, die dort vor sich gehen.\n\nFindet den Quell dieser Seuche und werft sie dort hinein.", progress = nil, completion = "&lt;Die Weise lässt ihren Kopf hängen und seufzt vor Erleichterung.&gt;\n\nDas ist ein guter Anfang. Wenn es doch nur unser einziges Problem wäre.", rewards = "Handlappen der GluthitzeRhinozerosmaskeTaillenbund des EbenenjägersGekühlte SchulterplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11678] = {title = "Findet Borstenhorn", objective = "Sucht in Talramas nach Fernläufer Borstenhorn.", description = "Borstenhorn hätte schon längst zurückkommen sollen.\n\nDer andere Grund, wieso wir hierhergekommen sind, war die Untersuchung des Gebäudes der Geißel im Westen, das vom Himmel gefallen ist. Er ist impulsiv und hat sich höchstwahrscheinlich in Schwierigkeiten gebracht.\n\n<Name>, geht dorthin und findet ihn, bitte.", progress = nil, completion = "Ich bin... nicht... lange für diese... Welt, kleiner &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11679] = {title = "Den Schlüssel neu schmieden", objective = "Donathan möchte, dass Ihr mit Surristrasz auf dem Bernsteinflöz sprecht.", description = "Verspätungen, Verspätungen... genau das, was wir uns gerade nicht leisten können!\n\nSo sehr ich es hasse, Lord Surristrasz zu stören, er ist die einzige Hoffnung, unsere geliebte Evanor zu retten.\n\nBringt die Schlüsselfragmente zu ihm und hofft, dass er guter Laune ist.\n\nBeeilt Euch, <Klasse>, unsere Angriffstruppe wartet.", progress = "Du wagst dich in meine Nähe, Sterblicher?\n\nBete und hoffe um deiner ungeborenen Kinder Willen, dass dein Anliegen die Mühe wert ist.", completion = "Die frivolen Spiele, die du hier treibst, führen zu nichts...\n\nDu und deine Verbündeten in Dalaran tappen im Dunkeln, während die Zukunft dieser Welt im Begriff ist, der Dunkelheit zu verfallen.\n\nUnd dennoch, die Sache könnte meinen Drachen die nötige Unterhaltung bieten.\n\nZeig mir diesen Schlüssel...", rewards = nil}
MultiLanguageQuestData['de'][11680] = {title = "Jemanden unter seine Fittiche nehmen", objective = "Gebt Kriegsmagier AnzimSalrands Schlüssel, wenn Ihr bereit seid, Evanor zu befreien.\n\nBereitgestellter Gegenstand: \n", description = "Der Schlüssel ist neu geschmiedet.\n\nNun hört meinen Rat, <Volk>. Vollbringt die Tat oder krepiert beim Versuch, denn sollte einem meiner Drachen auch nur eine einzige Schuppe gekrümmt werden, werde ich Euch persönlich zur Rechenschaft ziehen.\n\nHinfort mit Euch.", progress = nil, completion = "Das ist es - der Schlüssel ist unser!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11681] = {title = "Evanor retten", objective = "Anzim vom Bernsteinflöz möchte, dass Ihr gemeinsam mit seinen Kriegsmagiern losfliegt, um Lady Evanor auf der Beryllspitze zu befreien. Danach sollt Ihr Euch bei Ihr im Magierturm auf dem Bernsteinflöz melden.", description = "Endlich greifen wir an!\n\nSobald wir den Platz gesäubert haben, werde ich den Schlüssel verwenden.\n\nIhr müsst dafür sorgen, dass Lady Evanor sicher ist, nachdem sie befreit wurde.\n\nBeeilt Euch, lasst uns losfliegen!", progress = nil, completion = "Eure Heldentaten werden nicht vergessen werden, &lt;Klasse&gt;.\n\nBitte, nehmt dies und habt meine aufrichtige Dankbarkeit.", rewards = "Gürtel der GluthitzeVerkohlte TreterGlimmende RingpanzerhandschuheBrodelnder TaillenschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11682] = {title = "Drachengespräche", objective = "Lady Evanor hat Euch ausgesandt, um mit Surristrasz vom Bernsteinflöz zu sprechen.", description = "Ich bin mir über Eure jüngsten Taten im Klaren, <Name>, und möchte Euch noch einmal dafür danken.\n\nWas diese örtliche Bedrohung angeht, haben wir alles erfahren, was wir über sie erfahren können. Doch nun zu wichtigeren Angelegenheiten...\n\nAzeroth braucht Euch. Die Region gleich westlich von hier ist das Zentrum einer ernsten Krise.\n\nIch werde Lord Surristrasz über die Details in Kenntnis setzen. Ihr müsst umgehend mit ihm sprechen.\n\nViel Glück, <Freund/Freundin> von Dalaran.", progress = nil, completion = "So, &lt;Volk&gt;. Wir werden wieder miteinander sprechen.\n\nWenn ich meinen Bericht erzählt habe, werdet Ihr Euch wünschen, ihn nie gehört zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11683] = {title = "Gefallene Nekropole", objective = "Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zur Weisen Hochmesa zurück, welche sich gleich südlich der Höhlen des Todes befindet.", description = "Von der gefallenen Nekropole im Westen kann man nur annehmen, dass sie noch immer voll von Schergen der Geißel ist.\n\nWährend Ihr in Talramas seid, <Klasse>, möchte ich Euch bitten, alle Diener des Lichkönigs zu erledigen, die Ihr dort und in den umgebenden Teichen finden könnt.", progress = nil, completion = "Habt Dank, &lt;Name&gt;.\n\nDer Lichkönig und seine Geißel liegen auf Nordend wie eine Pest. Wir dürfen nicht ruhen, ehe alle vollkommen vernichtet sind und wir ihm den Garaus gemacht haben!", rewards = "Mehrlagige FrostsandalenVerstärkter Brustschutz aus KaribubälgenBernsteinplattentaillenschutzAuf Euch wartet eine dieser Belohnungen:\n\nPhiole der Erneuerung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11684] = {title = "Aufspüren der Schlundlöcher", objective = "Großvater Mahan in Taunka'le möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt.", description = "Könnt Ihr die Beben in der Erde spüren?\n\nDie Neruber der Geißel bewegen sich tief unter der Erde. Sie sind im Südwesten, in den Geysirfeldern, wieder hervorgekommen und schikanieren die von Häuptling Orkan ausgeschickten Patrouillen.\n\n<Der Taunkaälteste bietet Euch eine abgenutzte Karte an.>\n\nVielleicht kann ein Einzelner dort siegen, wo die Patrouillen versagt haben. Nehmt dies mit Euch zu den Geysirfeldern und tragt die Positionen der nerubischen Schlundlöcher ein.", progress = "Habt ihr die Positionen der Schlundlöcher eingetragen?", completion = "&lt;Großvater Mahan nimmt die Karte entgegen, bewegt sich aber kein Stück, um sie zu untersuchen...&gt;\n\nEure Informationen werden wir später einsetzen können, wenn wir bereit sind, den Plan umzusetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11685] = {title = "Das Herz der Elemente", objective = "Bringt 5 Elementarherzen zu Windzähmerin Barah in Taunka'le.", description = "Jetzt, da wir die genaue Position der Schlundlöcher der Neruber kennen, können wir diese einstürzen lassen, um die Offensive der Geißel zum erliegen zu bringen und ihre Streitkräfte hart zu treffen. Windzähmerin Barah kennt einen Weg, Elementare zu zügeln, um die von den Nerubern benutzten Tunnel zu zerstören, doch sie wird Eure Hilfe benötigen.\n\nSüdöstlich des Dorfes, nahe der Küste hinter den Gefrorenen Weiten werdet Ihr eine Region finden, die von gefrorenen Erdelementaren beherrscht wird. Die Herzen dieser Elemente sind genau das, was Windzähmerin Barah braucht.", progress = "Großvater Mahan hat mir mitgeteilt, dass Ihr zugestimmt habt, dabei zu helfen, die Tunnel zum Einsturz zu bringen.", completion = "Das sollte ausreichen, um den Kern eines mächtigen Elementar zu erschaffen, doch Stein allein wird meinem Elementar kein Leben einhauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11686] = {title = "Die Höfe des Kriegshymnenklans", objective = "Schattenpirscher Ickoris bei den Höfen des Kriegshymnenklans möchte, dass Ihr die Kornkammer des Kriegshymnenklans, Torps Bauernhof und den Schlachthof des Kriegshymnenklans ausspäht.", description = "Luthers Notizen nach benutzt die Geißel diesen Ort jetzt als Brutstätte für die Monster, die man über die Felder trampeln sieht.\n\n<Ickoris schaudert es.>\n\nDiese Monster waren einst Orcs... Tauren...\n\nBevor wir einen Plan schmieden können, benötigen wir mehr Informationen. Ich möchte, dass Ihr drei Stätten untersucht, die von der Geißel heimgesucht werden: die Kornkammer des Kriegshymnenklans südwestlich von uns, Torps Bauernhof direkt in unserem Westen und der alte Schlachthof des Kriegshymnenklans nördlich von hier.\n\nKehrt zu mir zurück, sobald Ihr diese ausgespäht habt.", progress = nil, completion = "Das ist weitaus schlimmer als das, was in Luthers Tagebuch stand. Dieser Ort wimmelt von Schergen der Geißel und sie infizieren alles, was sie anfassen.\n\n&lt;Ickoris nickt.&gt;\n\nEs wird noch schlimmer - wenn man sich das überhaupt vorstellen kann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11687] = {title = "Der Doktor und der Lichfürst", objective = "Vernichtet Doktor Klingengrinser und Lichfürst Frostwinter und kehrt anschließend zur Weisen Hochmesa zurück. Sie befindet sich gleich südlich der Höhlen des Todes.", description = "Es gibt zwei... die... getötet... werden müssen.\n\nDer Doktor und... der Lichfürst... sind... dort oben. Findet sie... vernichtet sie… bevor...\n\n... es... zu spät ist...", progress = nil, completion = "Borstenhorn ist tot?!\n\nIch hätte ihn niemals alleine dorthin gehen lassen dürfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11688] = {title = "Verdammte, dreckige Schweine", objective = "Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 10 untote Schweine tötet.", description = "Seht sie Euch nur an! Meine wunderschönen Kodos können sich nicht gegen diese dreckigen Schweine verteidigen, sie sind hilflos! Ihr müsst mir etwas Zeit verschaffen, <Volk>. Ich denke, ich kann die Kodos von dieser Krankheit heilen, aber Ihr müsst diese untoten Schweine von ihnen fern halten, sonst bleibt kein Kodo mehr übrig, um geheilt zu werden!\n\nBewegt Euch da raus und bringt diese Schweine unter die Erde - dauerhaft!", progress = "Ich brauche mehr Zeit! Haltet diese Schweine von meinen Kodos fern!", completion = "Ich glaube, ich bin soweit, &lt;Volk&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11689] = {title = "Schlechte Nachrichten überbringen", objective = "Sprecht mit Großmutter Taiga in Taunka'le.", description = "Die Großmutter wird davon erfahren müssen, <Name>.\n\nWürdet Ihr bitte nach Taunka'le zurückkehren? Sagt Ihr, dass ich bald nachkommen werde.", progress = nil, completion = "Welch Nachricht überbringt Ihr mir von Hochmesa?\n\n&lt;Ihr erklärt, was Ihr wisst, und überbringt der Großmutter die schlechten Nachrichten über Fernläufer Borstenhorn.&gt;\n\nMein... mein Enkel!\n\n&lt;Die Großmutter gibt sich Mühe, die Fassung zu wahren.&gt;\n\nEr starb einen ehrenhaften Tod, den Tod eines Taunka!\n\nIhr wart der Letzte, der bei ihm gewesen ist, &lt;Name&gt;. Also soll er auf ewig ein Teil von Euch sein. Habt meinen Dank dafür, seine letzten Wünsche erfüllt zu haben.", rewards = "Verstärkte Stiefel aus KaribubälgenStachelbrustharnisch von MagmutBernsteinplattenkopfschutzAuf Euch wartet eine dieser Belohnungen:\n\nRing des frierenden HeilersGroßmutters Talisman der Läuterung\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11690] = {title = "Bringt sie lebend zurück", objective = "Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 8 infizierte Kodobestien rettet.", description = "Nehmt diese Reittrense, <Name>. Ihr werdet merken, dass ich einen kleinen Medizinspender in das Mundstück eingearbeitet habe. Das Ding wird die Infektion heilen, sobald der Kodo darauf beißt. Sobald Ihr sie geheilt habt, müsst Ihr sie nach Hause reiten. Sie werden nicht bei Kräften sein, also müsst Ihr sie sanft hierher bewegen.\n\nBringt mir meine Babys zurück, <Name>!\n\nEins noch, Ihr habt 10 Minuten! Das Gegenmittel im Inneren der Trense bleibt nur so lange wirksam.", progress = "Holt sie aus diesen von der Geißel verseuchten Feldern!", completion = "Ihr seid ein wahrer Held, &lt;Name&gt;. Ohne Euch wären meine Kodos da draußen gestorben. Ihr habt meinen Dank und den Dank aller Soldaten und Reisenden, die diese Kodos benutzen werden, um unsere Stellung in Nordend zu stärken!", rewards = "Transboreanische BedeckungBrustharnisch des MarschenläufersWestklammgamaschenGroßfelsschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11691] = {title = "Beschwört Ahune", objective = "Bringt dieses Magmatotem des Irdenen Rings zum Eisbrocken.", description = "Ich und meine Schamanen haben all unsere Kräfte für die Schlacht mit dem Frostfürsten gesammelt. Ihr werdet die Faust der Erdenmutter sein, <Name>.\n\nNehmt dieses Magmatotem und benutzt es in der Nähe des Eisbrockens im Nordosten. Ahune leitet seine Kraft durch diesen Brocken. Unsere Hoffnung ist, dass das Totem seine Verbindung mit der Elementarebene durchtrennen wird.\n\nWenn wir Glück haben, dann könnten wir ihn vielleicht besiegen.\n\nMacht Euch bereit, <Name>. Wenn Ahune uns gegenübersteht, wird sein Zorn gewaltig sein.", progress = "Dieser Eissplitter lässt das tiefe  Rumpeln und Knacken gewaltiger Gletscherzungen erklingen. Seine Kälte lässt Eure Gedanken erstarren und treibt sie in einen leblosen, endlosen Winter.", completion = "Das Magmatotem zerbirst in drei einzelne Flammen, als Ihr es in die Nähe des Eisbrockens bringt. Der Brocken schimmert - und löst sich anschließend in Luft auf...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAhune - Summoning Rhyme Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11692] = {title = "Bei Bixie einchecken", objective = "Mordle Zahnrad möchte, dass Ihr Bixie Zangkeuler aufsucht, die sich südlich der Höhlen des Todes befindet.", description = "Ihr seid <ein gemachter Held/eine gemachte Heldin>. Ich hab' noch ein anderes Problem!\n\nMeine Chefin Tinky ist gemeinsam mit Bixie Zangkeuler nach Osten gegangen und ich bekomme das Sendesignal von diesem Dings einfach NICHT zum Laufen! Tinky ist die Einzige, die es reparieren kann, und es muss wirklich einwandfrei laufen.\n\nDenkt Ihr, dass Ihr sie finden könntet? Bixie meinte irgendwas davon, einem alten Magnatauren zu einem Ort namens 'Die Höhlen des Todes' folgen zu wollen.\n\nIch schätze mal, dass Ihr sie dort finden werdet.\n\nSprecht mit Kara Sternengala; sie wird dafür sorgen, dass man Euch dorthin bringt.", progress = nil, completion = "Womit kann ich dienen, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11693] = {title = "Oh, großartig... verseuchte Magnatauren!", objective = "Tötet 10 verseuchte Magnatauren. Kehrt anschließend zu Bixie Zangkeuler südlich der Höhlen des Todes.", description = "Tinky und ich sind hierhergekommen, um Jagd auf einen alten Magnatauren zu machen. Offenbar sind diese Höhlen dort oben der Ort, den sie zum Sterben aufsuchen.\n\nAuf keinen Fall hatten wir gewusst, dass sie dort drin verseucht werden. Wir können hier keine umherstreunenden verseuchten Wesen gebrauchen - ist nicht gesund.\n\nSagt mal, wieso könnt Ihr nicht ein paar von den Dingern beseitigen, während ich versuche herauszufinden, wie es weitergehen soll?", progress = nil, completion = "Gute Arbeit, aber ich würde mir an Eurer Stelle bei nächster Gelegenheit eine Dusche gönnen.\n\nNa, dann lasst uns mal das Problem hier draußen richtig anpacken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11694] = {title = "Irgendetwas geht in diesen Höhlen vor", objective = "Bixie Zangkeuler möchte, dass Ihr Bixies Desinfektionspuder in den Seuchenkessel in den Höhlen des Todes schüttet, um ihn zu neutralisieren. Bixie schleicht gleich südlich der Höhlen des Todes herum.", description = "Während Ihr Euch also um diese verseuchten Biester gekümmert habt, hab' ich mich mal in diesen Höhlen dort oben umgesehen.\n\nSie werden von Kultisten verseucht!\n\nDa gibt es einen Kessel, in dem sie irgend so ein übles Zeug brauen. Ich hab' ein Pulver bei mir, das ich normalerweise als Gegengift verwende und das ich mit ein paar anderen Sachen vermischt habe. Ich denke, dass sich damit das Gebräu neutralisieren lässt!\n\nNehmt es mit Euch, geht zu einer der Höhlen dort oben und seht nach, ob es funktioniert.", progress = "Die Zeit verrinnt, <Klasse>. Das Letzte, was wir gebrauchen können, sind verseuchte Magnatauren, gegen die wir kämpfen müssen.\n\nDie Normalen sind schon schlimm genug!", completion = "Ich hab' gewusst, dass etwas in Euch steckt. Nun, es gibt da noch eine Sache, um die Ihr Euch für mich kümmern müsst.", rewards = "Handlappen der GluthitzeRhinozerosmaskeTaillenbund des EbenenjägersGekühlte SchulterplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11695] = {title = "Das Horn des Elementarfurors", objective = "Tötet Häuptling Burbelgobbel und Häuptling Gurgelboggel, nehmt ihnen die untere und obere Hornhälfte ab und bringt sie zu Windzähmerin Barah in Taunka'le.", description = "Ich kann aus diesen Stücken leblosen Steins das Ebenbild eines Elementars erschaffen, doch ihm Leben einzuhauchen, ist etwas anderes. Um das zu tun benötigen wir Hilfe und ein bisschen Glück.\n\nDer Legende nach soll einst ein großer Held der Taunka auf der Suche nach einem uralten Artefakt namens \"Horn des Elementarfurors\" gewesen sein. Ich werde Euch eine Schriftrolle mit der Abschrift dieser Geschichte leihen. Ich weiß zwar nicht, ob etwas Wahres an ihr dran ist, doch uns bleibt nichts anderes übrig. Falls die Legende stimmen sollte, dann könnten die Hornteile auf den Flutebenen nördlich und südwestlich des Dorfes zu finden sein.", progress = "Konntet Ihr das Horn finden? Ist die Legende wahr?", completion = "&lt;Barah nimmt beide Hälften des Horns entgegen und versucht, sie zusammenzufügen.&gt;\n\nSturmhuf wäre stolz auf Euch, &lt;Name&gt;. Vielleicht werde ich, wenn wir uns um die Geißel gekümmert haben, das Horn mit auf eine Pilgerfahrt zu Sturmhufs Grab nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11696] = {title = "Ahune ist hier!", objective = "Findet Luma Himmelsmutter in den Sklavenunterkünften.", description = "<Name>, Eure Gegenwart ist ein Segen. Ahune befindet sich in den Höhlen und sammelt Kräfte für seinen Angriff. Truppen des Irdenen Rings wurden vorausgeschickt, doch alleine werden sie ihn nicht besiegen können.\n\nErkundet die Höhlen, <Name>. Findet unsere Schamanen des Irdenen Rings und meldet Euch bei ihrer Anführerin, Luma Himmelsmutter. Mit vereinten Kräften werden wir Ahune vielleicht besiegen können, bevor es zu spät ist.", progress = nil, completion = "Ahunes Kälte breitet sich in diesen Höhlen aus, &lt;Name&gt; - ein Vorgeschmack des eisigen Todes, der uns erwarten würde, sollte er seine volle Stärke erlangen. Erdenmutter sei Dank, dass sie Euch gesandt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11697] = {title = "Mist, Tinky ist in die Nekropole gelaufen!", objective = "Sucht Tinky Dochtpfiff im Inneren von Talramas.", description = "Ich habe Tinky gewarnt, nicht alleine loszuziehen, doch sie musste ja einfach die verunglückte Nekropole im Westen untersuchen.\n\nIch bin 100% sicher, dass diese Kultisten aus diesem Ding rausgekommen sind, weshalb ich jetzt 100% sicher bin, dass Tinky in Schwierigkeiten steckt!\n\nSie ist die Top-Ingenieurin der Landebahn. Ohne sie sind wir verdammt!\n\nIch würde ja selber gehen, doch eines dieser Dinger hat mir schon wieder Fesseln angelegt, bevor ich verschwinden konnte. <Name>, falls sie irgendwer da rausholen kann, seid Ihr es!", progress = nil, completion = "Hey Ihr! Wer seid Ihr?\n\nBixie hat Euch geschickt? Ausgezeichnet, dann holen wir mich mal hier raus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11698] = {title = "Man kann auch gleich die Geißel auslöschen", objective = "Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zu Bixie Zangkeuler zurück, welche sich gleich südlich der Höhlen des Todes befindet.", description = "Falls die Kultisten oben in diesen Höhlen den Absturz überlebt haben, dann kann man nur annehmen, dass die gefallene Nekropole im Westen noch immer voll von Schergen der Geißel ist. Es gibt sie bestimmt auch massenweise bei den Teichen, die sich dort befinden!\n\nWährend Ihr in Talramas seid, <Klasse>, meint Ihr, Ihr könntet alle Lakaien des Lichkönigs, die Ihr dort findet, platt machen?", progress = nil, completion = "Danke, &lt;Name&gt;.\n\nDer Lichkönig und seine Geißel sind wirklich Furcht einflößend, doch wir können nicht ruhen, ehe sie nicht in frischen Gräbern ruhen!", rewards = "Mehrlagige FrostsandalenVerstärkter Brustschutz aus KaribubälgenBernsteinplattentaillenschutzAuf Euch wartet eine dieser Belohnungen:\n\nPhiole der Erneuerung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11699] = {title = "Bin in diesem verdammten Käfig gefangen... aber nicht mehr lange!", objective = "Findet einen Motorkernkristall, ein magisches Gyroskop und einen Geißelsteuerungsstein. Liefert die Gegenstände anschließend bei Tinky Dochtpfiff in Talramas ab.", description = "Die Kultisten haben mich in diesen Käfig gehext und er hat kein Türgitter. Sie wussten jedoch nicht, dass ich der Hauptingenieuer für Transmaterie auf der Landebahn bin!\n\nMit Eurer Hilfe und ein wenig Schmalz werde ich schon bald hier raus sein.\n\nIch werde einen Motorkernkristall von einem der Ghule hier benötigen, ein magisches Gyroskop ihrer Doktoren und einen Geißelsteuerungsstein von ihrem Lichfürsten ganz oben.\n\nMit dem ganzen Zeug sollte ich ein Portalgerät basteln können, mit dem ich auf gnomische Art entkommen und wieder zu Kurbelzisch gelangen kann!", progress = "Habt Ihr das ganze Zeug mitgebracht?", completion = "Hervorragend! Jetzt nur noch eine Modifikation hier und eine kleine Änderung da...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11700] = {title = "Lasst es Bixie wissen", objective = "Sprecht mit Bixie Zangkeuler gleich südlich der Höhlen des Todes.", description = "Mein böser Zwilling ist irgendwo da draußen.\n\nIch bin mir ziemlich sicher, dass sie noch nicht zurück bei der Landebahn ist. Vielmehr, wo immer es sie hin verschlagen hat, sie ist jetzt an einem Ort, an dem es viel kälter ist als hier. Doch ich konnte sie nur für einen kurzen Moment \"fühlen\".\n\nNun gut, ich werde das Ding neu konfigurieren und mich selbst schon bald zurück zur Landebahn teleportieren. Meint Ihr, Ihr könntet in der Zwischenzeit nach Osten zu Bixie gehen und sie wissen lassen, dass ich sie dort treffen werde?\n\nDanke, <Name>!", progress = nil, completion = "Tinky hat einen bösen Zwilling?!\n\nNun, wenn sie sagt, dass es ihr gut geht und dass sie bald selbst zurück zur Landebahn kommt, soll mir das Recht sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11701] = {title = "Zurück zum Landeplatz", objective = "Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch in der Boreanischen Tundra.", description = "Nun gut, ich denke, dass ich mich auch wieder auf den Weg zurück zum Landeplatz mache. Mit meiner Verletzung am Bein werde ich sicherlich ein wenig länger brauchen.\n\nSagt mir, denkt Ihr, dass Ihr vor mir dort ankommen und dem alten Kurbelzisch die guten Neuigkeiten überbringen könntet? Ich wette, dass Euch auch eine Belohnung winken wird.\n\nDanke, <Name>!", progress = nil, completion = "Das sind Neuigkeiten, &lt;Name&gt;. Ein Wunder, dass bei all den Problemen hier draußen der Landeplatz nicht schon längst von der Landkarte getilgt wurde.\n\nDoch Dank Euch, gibt es nun einen Gegner weniger, um den wir uns den Kopf zerbrechen müssen.\n\nFür Anlässe wie diesen hier habe ich ein paar spezielle Gegenstände aufgehoben. Wieso sucht Ihr Euch nicht einfach einen aus?", rewards = "Verstärkte Stiefel aus KaribubälgenStachelbrustharnisch von MagmutBernsteinplattenkopfschutzAuf Euch wartet eine dieser Belohnungen:\n\nRing des frierenden HeilersHypergizmatischer Energieverstärker\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11702] = {title = "König Mrgl-Mrgl", objective = "Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen.", description = "Das wiad sich schräg anhöan, <Klasse>, aber da wiad es einen Murloc geben, dea fragen wiad, ob wia ihm helfen könn'n!\n\nMan nennt ihn König Mrgl-Mrgl, dea Anführa dea Wintaflossen. Er und seine Leute wurden aus dem Dorf gejagt und sie wollan, dass Ia kommt und ihn'n helft.\n\nIa findat ihn, wenn Ia nach Westan geht und de Klippen runterlauft. Ea hängt im Süden dea Zuflucht dea Winterflossen ab.", progress = nil, completion = "Endlich - Hilfe! Und dem Anschein nach Horde.\n\nDas passt... Eure Leute sind sehr geübt, wenn es ums Kämpfen geht. Davon werden wir jede Menge benötigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11703] = {title = "Gelangt zu Getry", objective = "Geht zu den Höfen des Kriegshymnenklans und findet Schattenpirscher Getry.", description = "Der für die Entführung und Verwandlung unserer Hordesoldaten in untote Monster verantwortliche Agent der Geißel nutzt die nordwestliche Farm als Brutstätte. Schattenpirscher Getry hat die ganze letzte Woche die Machenschaften dieses Monsters verfolgt und ein paar entscheidende Informationen gesammelt, mit deren Hilfe wir die Bedrohung womöglich aus der Welt schaffen können.\n\nGelangt zu Getry und seht nach, ob Ihr verhindern könnt, dass dort am laufenden Band neue Diener der Geißel produziert werden. Ihr findet Getry bei dem verlassenen Turm an der nordwestlichen Grenze dieser Höfe.", progress = nil, completion = "&lt;Getry mustert Euch von Kopf bis Fuß.&gt;\n\nDas ist alles, was Ickoris schicken konnte?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11704] = {title = "König Mrgl-Mrgl", objective = "Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen.", description = "Das ist mal seltsam, <Klasse>, aber da wird es einen Murloc geben, der Euch um Hilfe bitten wird!\n\nMan nennt ihn König Mrgl-Mrgl, der Anführer der Winterflossen. Es scheint, als hätte man seine Leute und ihn aus ihrem Dorf verjagt - nun wollen sie jemanden, der ihnen hilft.\n\nUnd dieser Jemand seid Ihr!\n\nIhr findet die Zuflucht der Winterflossen und den König in westlicher Richtung. Geht einfach die Straße entlang, bis Ihr die Klippen erreicht, und steigt sie in der Nähe des Kochenden Teiches hinab.", progress = nil, completion = "Endlich - Hilfe! Und dem Anschein nach Allianz.\n\nGut so... Eure Leute sind sehr geübt, wenn es ums Kämpfen geht. Davon werden wir jede Menge benötigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11705] = {title = "Törichtes Unterfangen", objective = "Helft Getry dabei, Varidus den Flenser bei den Höfen des Kriegshymnenklans zu besiegen.\n\nFalls Ihr erfolgreich sein solltet, erstattet Garrosh Höllschrei Bericht.", description = "Das ist Wahnsinn. Wie kann man von uns erwarten, dass wir uns mit einem Nekrolord der Geißel und einer unbekannten Zahl an Gefolgsleuten anlegen?\n\n<Getry schluchzt.>\n\nWenn Ickoris Euch schickt, dann muss er Euch für große Taten in der Lage halten. Vielleicht verursacht Ihr hier und heute ja ein Wunder, was?\n\nWenn Ihr soweit seid, steigen wir hinunter und treten Varidus gegenüber.\n\nWenn wir es in einem Stück aus dieser Misere heraus schaffen, meldet Euch bei Höllschrei in der Kriegshymnenfeste.", progress = nil, completion = "Und Ihr seid siegreich zurückgekehrt, genau wie ich dachte! Ich habe es Saurfang ja gesagt, dass Ihr spitze seid.\n\n&lt;Höllschrei grunzt besserwisserisch.&gt;\n\nVielleicht wird das dem alten Hund zeigen, dass er nicht auf alles eine Antwort hat, was?", rewards = "HermelinkragenumhangVerstärkte Kutte des BettelmönchsPlattenrüstung des gütigen KreuzfahrersAuf Euch wartet eine dieser Belohnungen:\n\nGravierter Schaufelhaueranhänger\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11706] = {title = "Der Kollaps", objective = "Windzähmerin Barah in Taunka'le möchte, dass Ihr die nerubischen Schlundlöcher mithilfe des Horns des Elementarfurors zum Einsturz bringt und Fürst Kryxix besiegt.", description = "Ich habe Alluvius mithilfe des Horns des Elementarfurors erschaffen und gebunden. Geht zum südlichsten Schlundloch und lasst das Horn erschallen - er wird seinem Ruf gehorchen.\n\nDas Erdbeben, das Alluvius hervorrufen wird, sollte die nerubischen Tunnel zum Einsturz bringen und ihrem Flankenangriff ein Ende setzen. Ich wäre nicht überrascht, wenn sich der Hauptmann der Neruber nach dem Erdbeben zeigen würde. Sollte der Einsturz der Tunnel ihren Angriff nicht zum Halt bringen, würde ein Sieg über ihren Anführer in dieser Hinsicht sicherlich Erfolg haben.", progress = "Habt Ihr Alluvius losgelassen und den nerubischen Angriff zum Erliegen gebracht?", completion = "Eure Dienste gegen die Neruber haben den überwältigenden Ansturm der Geißel kurzzeitig zum Stillstand gebracht und gewähren uns eine Verschnaufpause. Dank Eurer Taten können wir die nördlich gelegene Festung der Geißel angreifen, ohne einen Angriff aus dem Westen fürchten zu müssen.\n\nWas das Horn angeht: Ich werde es einstweilen in sicheren Gewahrsam nehmen, bis wir seine Macht wieder benötigen. Sturmhuf hat sein Leben dafür gegeben, dieses Horn zu sichern, und wir können es uns nicht leisten, es noch einmal zu verlieren.", rewards = "Manschetten der GluthitzeRhinozeroshandschuheBrustharnisch des EbenenjägersGekühlte SchienbeinschützerIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11707] = {title = "Notruf", objective = "Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch.", description = "Oh, gut, Ihr seid <Name>, nicht wahr?\n\nWir benötigen heute wiedereinmal Eure Hilfe. Es geht genauso wie gestern um die Landebahn Kurbelzisch im Norden! Die Magnatauren und die Geißel... und die Pumpstation!\n\nEs ist verrückt, sag' ich Euch, verrückt!\n\nIhr müsst dorthin gehen und mit dem alten Vollgas sprechen - und zwar dalli!", progress = nil, completion = "Wie ich sehe, hat es Himmelhopper endlich mal geschafft, Hilfe zu schicken. Und nicht zu früh, möchte ich hinzufügen!\n\nWillkommen, Bruder, wir benötigen dringend Eure Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11708] = {title = "Die Mechagnome", objective = "Hört Euch Kurbelzisch Vollgas' Bericht an und sucht anschließend Jinky Flügelirre auf der Landebahn Kurbelzisch auf.", description = "Nun, da Ihr hier seid, ist der Zeitpunkt gekommen, dass ich Euch die ganze Geschichte über das erzähle, was hier los ist.\n\nGeht nach draußen, sobald Ihr meinen Bericht gehört habt, und sprecht mit Jinky Flügelirre. Sie wird sich von da ab um alles kümmern.", progress = "Tagchen.", completion = "Der Alte hat Euch zu mir geschickt, hm? Und er hat Euch alles darüber erzählt, was hier draußen vor sich geht?\n\nGut... dann packen wir mal die Sache an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11709] = {title = "Nork Blutwahns Aufgabe", objective = "Sprecht mit Aufseher Nork Blutwahn in der Kriegshymnenfeste in der Boreanischen Tundra.", description = "Obgleich Ihr viel getan habt, um unsere Position hier in diesen gefrorenen Weiten zu festigen, lauern noch immer andere Gefahren in den Schatten. Ich möchte, dass Ihr Aufseher Nork Blutwahn helft, der im Internierungslager stationiert ist, welches gleich südöstlich der Kriegshymnenfeste liegt. Sucht ihn auf und bietet ihm Eure Hilfe beim Transport und beim Austausch der Gefangenen an.\n\nWegtreten, <Name>.", progress = nil, completion = "&lt;Nork spottet.&gt;\n\nGefangene? Das sind keine Gefangenen. Das sind feige Hunde! Seht sie Euch nur an. Wusstet Ihr, dass jeder einzelne dieser gelbbäuchigen \"Soldaten\" vor unsere Tore kam und seine Waffen und seine Rüstung niedergelegt hat?\n\nNach dem zu urteilen, was wir gehört haben, werden diese Männer und Frauen entlassen und zurück nach Hause geschickt, wenn sie von uns gefangen werden.\n\n&lt;Nork spuckt.&gt;\n\nErbärmlich...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11710] = {title = "Was ist nur los mit der Transmaterie?", objective = "Sammelt 15 Ersatzteile von Kurbelzisch und liefert sie an Mordle Zahnrad auf der Landebahn Kurbelzisch.", description = "Überall im Osten sind Ersatzteile verstreut: in den Siedenden Teichen, den Geysirfeldern... ach, was sag ich, wahrscheinlich sogar bis zur Pumpstation hin liegt das Zeugs rum. Bringt es alles wieder zurück. Vielleicht werde ich es dann hinbekommen, mit dem Ding auch jemanden von hier wegzuteleportieren, ganz abgesehen davon, dass ich noch die eingehenden Transmatierieanschlüsse ausrichten muss.\n\nIch würde ungern einen weiteren Unfall erleben...", progress = "Wir werden 'ne Menge Ersatzteile brauchen, um dieses Ding am Laufen zu halten.\n\nBitte sagt mir, dass Ihr alles dabei habt, was wir benötigen.", completion = "Das ist großartig, &lt;Klasse&gt;! Diese Teile sehen aus, als wären sie in einem brauchbaren Zustand.\n\nWenn ich jetzt nur herausfinden könnte, wie man eines dieser verfluchten Dinger repariert...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11711] = {title = "Angsthasenlieferung... unter 30 Minuten - ansonsten gratis", objective = "Bringt den Deserteur der Allianz zur Kreuzung östlich der Kriegshymnenfeste und feuert die Leuchtpistole des Kriegshymnenklans ab, um der Allianz ein Zeichen zu geben.\n\nMeldet Euch bei Späher Tungok, nachdem die Übergabe des Deserteurs der Allianz erfolgreich abgeschlossen wurde.", description = "Mit jedem Tag, der verstreicht, kommen mehr Deserteure an unser Tor. Wir haben einfach nicht genug Platz, um all diese Maden zusammenzupferchen. Ganz besonders dann nicht, wenn wir die Schweine bei Laune halten wollen.\n\n<Nork prustet vor Lachen.>\n\nIch möchte, dass Ihr einen der Feiglinge zur Kreuzung im Osten begleitet und diese Leuchtpistole abfeuert. Einer ihrer Hauptmänner wird auftauchen, sobald die Allianz das Leuchtsignal sieht, und Euch den Feigling abnehmen.\n\nMeldet Euch bei Späher Tungok auf der Oststraße, nachdem die Lieferung stattgefunden hat.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Das ist ein dreckiger, unnützer Allianzmistkerl weniger, den wir versorgen müssen...\n\nFalls Ihr noch mehr Arbeit wollt, die Tauren und Blutelfen hier in der Nähe bräuchten ein wenig Hilfe.\n\nNatürlich haben wir hier draußen auch unsere eigenen Probleme, mit denen wir uns herumschlagen müssen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11712] = {title = "Verflucht nochmal!", objective = "Jinky Flügelirre bei der Landebahn Kurbelzisch möchte, dass Ihr die fluchrekursive Transmaterieinjektion auf 6 der Mechagnome von Kurbelzisch anwendet.", description = "Wenn Ihr dem alten Mann zugehört habt, wisst Ihr, dass manche Gnome dort draußen manipuliert wurden. Ritzelmeister Mechazod hat sie mit etwas infiziert, das den 'Fluch des Fleisches' neutralisiert, und nun sind sie Roboter!\n\nWir meinen, einen Weg gefunden zu haben, sie wieder mit einem Fluch zu belegen, der sie wieder normal macht. Dazu müsst Ihr diese fluchrekursive Transmaterieinjektion auf die Leichen der Mechagnome, über die Ihr stolpert, anwenden.\n\nWir hoffen, dass dieses Zeugs sie heilen und es uns erlauben wird, sie wieder hierher zurückzuteleportieren.\n\nWas meint Ihr dazu, <Name>?", progress = nil, completion = "Ihr habt es geschafft... es hat funktioniert!\n\nIch kann es gar nicht glauben, dass Ihr so viele retten konntet. Wir können uns glücklich schätzen, Euch hier bei uns zu haben!", rewards = "Mehrlagige Kapuze des FrostsRhinozerosgelenkbänderStachelhandschuhe von MagmutGekühlte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11713] = {title = "Aufspüren der Schlundlöcher", objective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt.", description = "Kurbelzisch hat ein Luftüberwachungsteam losgeschickt, um die Schlundlöcher der Neruber im Süden der Geysirfelder zu kartieren, doch das ist noch nicht zurückgekehrt. Ich kann nicht länger auf die Informationen warten, deshalb brauche ich jemanden, der zu Fuß die Schlundlöcher sucht.\n\nIch verstehe die damit verbundenen Gefahren und werde Euch dementsprechend entschädigen. Nehmt diese Karte mit und tragt die entscheidenden Informationen über die Schlundlöcher ein, auf die Ihr dort draußen trefft.", progress = "Habt ihr die Positionen der Schlundlöcher eingetragen?", completion = "&lt;Abner nimmt die Karte entgegen und studiert sie genau.&gt;\n\nGroßartig! Das ist alles, was wir an Informationen brauchen, um mit der Operation zu beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11714] = {title = "Ungeziefer vertilgen", objective = "Späher Tungok in der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr 8 Blutsporenernter, 5 Blutsporenfeuerteufel und 2 Blutsporenröster tötet.", description = "Hättet Ihr vielleicht Interesse, mir dabei zu helfen, diese Felder zu säubern? Sie sind mit dreckigen kleinen Rattenmenschen übersät! Kobolde, Schneebolde oder wie auch immer Ihr sie nennen wollt, sie sind über den ganzen verdammten Ort verstreut. Der Gestank alleine ist die reinste Hölle!\n\nKümmert Euch für mich um das Ungeziefer und ich werde dafür sorgen, dass es sich für Euch lohnt, <Name>.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Ich danke Euch!", rewards = "Transboreanischer MantelBedeckung der FlutebenenBrustschutz der gesalbten WundenAuf Euch wartet eine dieser Belohnungen:\n\nSiegelring des Spähers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11715] = {title = "Öl für das Projekt", objective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mit dem tragbaren Ölsammler 8 Fässer Öl sammelt.", description = "Ich möchte eine Maschine bauen, die die Tunnel zum Einsturz bringt, welche die Geißel benutzt, um ihre Neruber einzusetzen. Aber da die Hauptbohrplattform außer Betrieb ist, müssen wir uns irgendwie anders Treibstoff für das Gerät besorgen.\n\nDraußen in den Geysirfeldern im Südosten gibt es kleine Öllachen, die entfernt von der Hauptplattform aus dem Boden quellen. Wenn Ihr genug Öl von diesen Lachen besorgen könnt, kann ich Treibstoff herstellen, um die Maschine zu betreiben.\n\nSetzt einfach den Sammler in der Nähe der Plattform ein und er wird das Öl in seinen Tank pumpen.", progress = "Habt Ihr den Treibstoff?", completion = "&lt;Abner beginnt den Öltank des Sammlers zu leeren.&gt;\n\nDas per Hand zu destillieren ist schwierig, doch ich werde das schon bald erledigt haben. In der Zwischenzeit brauchen wir noch eine weitere Komponente, um die Maschine fertig zu stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11716] = {title = "Die wundersamen Blutsporen", objective = "Blutmagierin Laurith in der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr 10 Blutsporenkarpelle beschafft.", description = "Wir sind Zeugen von etwas Außergewöhnlichem, <Volk>. Ein paar Schritt weit entfernt von uns existiert ein ganzes Ökosystem, das noch nicht entdeckt wurde! Ich vermute, dass die Blutsporenpflanze die Natur hier zum Sprießen bringt.\n\nIch habe ein wenig Blütenstaub der nahe gelegenen männlichen Blutsporenpflanze gesammelt, doch zur Bestäubung fehlen mir noch die weiblichen Rezeptoren. Besorgt mir einen Scheffel der Blutsporenkarpelle. Ihr könnt sie in der Nähe der größeren Pflanzen finden, die uns umgeben.\n\nNehmt Euch jedoch vor ihren Wächtern in Acht! Die Kobolde werden sie nicht ohne Weiteres aufgeben!", progress = "Die Versuche müssen weitergeführt werden!", completion = "Herrlich! Einfach herrlich!\n\n&lt;Laurith trägt ein wenig Blütenstaub auf eines der Blutsporenkarpelle auf und spricht eine Beschwörungsformel.&gt;\n\nHmpf... ich verstehe nicht. Außer... Aber natürlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11717] = {title = "Pollen von den Motten besorgen", objective = "Blutmagierin Laurith in der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr 5 Pollen von Blutsporenmotten besorgt.", description = "Es liegt auf der Hand! Die Blutsporenmotten sind für die Bestäubung dieser Ebenen verantwortlich. Es muss etwas aus dem Stoffwechsel der Motten sein, das als Katalysator für die Funktion dieser Pollen dient. Es fängt jetzt alles an, einen Sinn zu ergeben, <Name>. Deshalb töten die Kobolde die Motten nicht, sondern beschützen sie so gut sie können! Diese dreckigen, kleinen Ratten haben das durchschaut!\n\nNun, dann müssen wir uns einfach unsere eigenen Mottenpollen besorgen! Was meint ihr dazu? Besorgt Ihr mir welche im Namen der Wissenschaft?", progress = "Die Pollen sind der Schlüssel!", completion = "Ah-ha!\n\n&lt;Laurith sprenkelt die Mottenpollen über die Blutsporenkarpelle.&gt;\n\nSeht Euch das an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11718] = {title = "Ein Bot im Mammutpelz", objective = "Abner Zischeldrill auf Landebahn Kurbelzisch möchte, dass Ihr ihm 6 dicke Mammutbälge bringt.", description = "Ich habe die Grundstruktur eines alten Bots so rekonfiguriert, dass er ein Erdbeben auslösen wird, das stark genug ist, die Tunnel zum Einsturz zu bringen. Doch die Maschine ist empfindlich gegenüber Nordends beißender Kälte.\n\nIch habe einen Weg gefunden, ihn mit den dicksten Bälgen einheimischer Mammuts zu isolieren. Sie streifen auf den Ebenen südlich der Landebahn und in der Nähe der Geysirfelder herum. Bringt genug Bälge mit, um die Maschine fertigzubauen und sie auf die Neruber loszulassen!", progress = "Bringt mir diese Bälge so schnell wie möglich! Ich werde die Maschine ohne sie nicht fertig stellen können!", completion = "&lt;Abner inspiziert die Bälge. Der aufgewirbelte Staub bringt ihn zum Husten.&gt;\n\nKörperhygiene wird bei diesen Tieren wohl nicht besonders groß geschrieben? Einige von diesen Fellen sind völlig verdreckt. Nun, ich sollte wohl besser damit anfangen, sie zu reinigen. Ist ja nicht so, dass hier irgendwer Zeit übrig hätte - oh nein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11719] = {title = "Ein geeignetes Versuchsobjekt", objective = "Blutmagierin Laurith auf der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr die bestäubte Blutsporenblume verwendet und sie dabei zusehen lasst, was passieren wird.", description = "<Laurith mustert Euch von Kopf bis Fuß.>\n\nSo, wir haben also diese bestäubte Blutsporenblume hier, aber niemanden, an dem wir ihre Wirkung ausprobieren könnten. Sagt mir, wäret Ihr vielleicht daran interessiert, das hier auf Eure Haut zu reiben und mich dabei zusehen zu lassen, was passiert? Was könnte schon Schlimmes dabei passieren?\n\nKeine Sorge, <Name>! Schmiert Euch einfach ein wenig von dem hier ins Gesicht.", progress = "Habt keine Angst.", completion = "Ur Machthorn wird entzückt sein! Das ist besser, als ich es je erwartet hätte!\n\nWomöglich ist es an der Zeit, dass ich Euch die Wahrheit erzähle.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11720] = {title = "Die Invasion von Gammut", objective = "Sprecht mit Ur Machthorn in der Blutsporenprärie in der Boreanischen Tundra.", description = "Höllschrei hat Machthorn und mich mit der entmutigenden Aufgabe betraut, die Magnatauren an der südlichen Front der Kriegshymnenfeste auszurotten. Mit uns kam ein kompletter Zug erfahrener Hordesoldaten. Unser erster Vorstoß in die nahe gelegenen Magnataurenhöhlen erwies sich als recht erfolglos, da unser kompletter Trupp von den Verteidigern der Höhlen ausgelöscht wurde. Wir sind die einzigen, die übrig sind...\n\nWir sind weder Wissenschaftler noch Forscher. Wir sind Soldaten der Horde, so wie Ihr...\n\nSprecht jetzt mit Ur Machthorn.", progress = nil, completion = "Die Blutsporen, die Ihr gesammelt habt, könnten uns einen Vorteil gegen die Magnatauren von Gammut verschaffen. Mit Eurer Hilfe versteht sich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11721] = {title = "Gammutra der Peiniger", objective = "Erschlagt Gammutra und bringt den Kopf von Gammutra zu Ur Machthorn in der Blutsporenprärie in der Boreanischen Tundra.", description = "Magnatauren leben in Rudeln, gleich den Löwen: ein oder zwei dominante Männchen und mehrere Weibchen gemeinsam mit ihrem Nachwuchs. Der Anführer von Gammut, der Magnataurenhöhle westlich von hier, wird Gammutra genannt. Es ist Gammutra, der über diese Magnataurenpopulation herrscht, also ist es auch Gammutra, den wir niederstrecken müssen, um jegliche Art des Aufruhrs durch die Magnatauren zu verhindern.\n\nNehmt diesen Beutel mit zerdrückten Blutsporen an Euch und geht nach Gammut. Schwächt Gammutra mithilfe der Blutsporen und erschlagt ihn! Bringt mir sein Haupt als Beweis.", progress = "Das Pulver kann dazu verwendet werden, alle Magnatauren zu schwächen. Was auch der Grund dafür ist, weshalb das Rattenvolk in dieser Gegend es so gut behütet.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;! Würdet Ihr Laurith und mir die Ehre erweisen, zu Höllschrei zu gehen und ihm den Kopf des Biests zu präsentieren? Er wird äußerst zufrieden sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11722] = {title = "Trophäen von Gammut", objective = "Bringt den Kopf von Gammutra zu Garrosh Höllschrei in der Kriegshymnenfeste.", description = "Der Sieg der Horde ist nicht allein uns zu verdanken, <Name>. Ihr wart es, <der/die> Ihr Euer Leben riskiertet, um die Blutsporen zu testen, und Ihr seid es gewesen, <der/die> Gammutra zu guter Letzt ein Ende bereitete.\n\nErweist uns die Ehre und kehrt zur Kriegshymnenfeste zurück, um Fürst Höllschrei den Kopf von Gammutra zu präsentieren.", progress = "So schnell schon wieder zurück?", completion = "&lt;Höllschrei hebt den Kopf von Gammutra mit einer Hand auf und spuckt in sein Gesicht.&gt;\n\nSie werden es lernen, &lt;Name&gt;... Sie werden es alle lernen. Mit der Horde ist nicht zu spaßen...", rewards = "Transboreanische GamaschenSchulterstücke des MarschenläufersRingpanzer des TundraschreitersGroßfelshelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11723] = {title = "Setzt den Schüttlo-Rüttlo ein!", objective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mithilfe des Schüttlo-Rüttlo 5000 die Tunnel der Neruber zum Einsturz bringt und Fürst Kryxix besiegt.", description = "Ich präsentiere Euch die Maschine, die uns vor der Bedrohung durch die Neruber beschützen wird!\n\n<Abner strahlt vor Stolz, als er Euch seinen fertigen Bot zeigt.>\n\nNehmt diese Fernsteuerung, geht zu einem der nerubischen Schlundlöcher auf den Geysirfeldern und aktiviert mit ihrer Hilfe den Schüttlo-Rüttlo 5000. Er wird dann den Rest von alleine erledigen.\n\nWundert Euch nicht, wenn das von ihm verursachte Erdbeben die Aufmerksamkeit eines nerubischen Anführers erregt. Genau genommen wäre es eine großartige Gelegenheit, der nerubischen Offensive den Rest zu geben.", progress = nil, completion = "&lt;Abner hört Euch aufmerksam zu, während Ihr vom Erfolg des Schüttlo-Rüttlo 5000 und Euch berichtet.&gt;\n\nKurbelzisch wird über die Nachrichten hocherfreut sein! Und wer weiß, vielleicht wird er sogar einen Mechaniker aus Euch machen!", rewards = "Manschetten der GluthitzeRhinozeroshandschuheBrustharnisch des EbenenjägersGekühlte SchienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11724] = {title = "Mächtiges Mottenomelett?", objective = "Bringt das schwere leuchtende Ei zu Blutmagierin Laurith in der Blutsporenprärie in der Boreanischen Tundra.", description = "Dieses Ei war jemandem offensichtlich sehr wichtig, wie die Leiche in der Nähe zeigt. Wenn man das Ei genauer betrachtet, merkt man, dass es bereits für den Versand in die Blutsporenprärie markiert war, an Blutmagierin Laurith. Das ist östlich von hier!\n\nNehmt das Ei und bringt es zur wartenden Blutmagierin.", progress = "Grüße!", completion = "Alkor ist Geschichte, wie? Eine Schande... Was das Ei angeht, so haben wir keine wirkliche Verwendung mehr dafür. Wir haben wesentlich größere Probleme, um die wir uns jetzt kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11725] = {title = "Auf der Suche nach Trudelflug", objective = "Macht Iggy \"Trudelflug\" Zinkenwechsel auf den Geysirfeldern ausfindig.", description = "Ich hätte die Mission selber fliegen sollen. Es ist nicht so, dass ich Trudelflug nicht vertrauen würde - ganz und gar nicht. Verdammt, er war der beste Flügelmann, mit dem ich je geflogen bin.\n\nNein, es ist nur so, dass ich eigentlich dafür zuständig bin, solch eine wichtige Mission zu fliegen.\n\nIch habe Trudelflug mit unserer schnellsten Aufklärerstaffel ausgesandt, um die Teiche weit im Süden und gleich westlich der nerubischen Schlundlöcher auszukundschaften.\n\nFindet Trudelflug, <Name>.", progress = nil, completion = "Gnom sei Dank. Es war schrecklich.\n\nDa war ein greller Lichtblitz am Boden und das Nächste, woran ich mich erinnern kann, ist, dass die komplette Staffel im Begriff war, abzustürzen! Ich bin ziemlich schwer verletzt, hatte also nicht die Möglichkeit, die Absturzstelle nach anderen Überlebenden abzusuchen. Doch irgendetwas sagt mir, dass es nicht sehr viele geben wird.\n\n&lt;Iggy verzieht sein Gesicht vor Schmerz.&gt;\n\nWerdet Ihr mir dabei behilflich sein, meine Mission zu beenden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11726] = {title = "Ein klein wenig Würze", objective = "Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr 4 Gewürzbeutel der Gorloc sammelt.", description = "Die Wölfe haben das Wrack nach dem Absturz durchwühlt und dabei wohl den Mikrofilm unserer Mission aufgefressen.\n\nIch habe einen Plan, wie wir diesen Mikrofilm wiederbeschaffen können, doch ich brauche Eure Hilfe, um das zu bewerkstelligen.\n\nGen Süden und Osten in den Flutebenen leben Kreaturen, die man die Gorloc nennt. Sie bereiten ihre Mahlzeiten mit üblen Gewürzen zu, die jede andere Kreatur grün anlaufen lassen würden. Wenn Ihr genug Gewürzbeutel von den Dampfrülpsern der Gorloc und den Watschlern der Gorloc sammelt, kann ich Euch daraus den Wolfsköder herstellen.", progress = "Habt Ihr die Gewürzbeutel dabei?", completion = "&lt;Iggy hält sich die Nase zu, als er die Gewürzbeutel leert, und spricht zu Euch mit einem nasalen Ton in seiner Stimme.&gt;\n\nJetzt, wo wir alles Nötige haben, werde ich es mit den Notrationen vermischen, um daraus einen Köder für die Wölfe zu basteln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11727] = {title = "Eine Zeit für Helden", objective = "Meldet Euch bei Unteroffizier Hammerberg in der Valianzfeste.", description = "Es ist gut, Euch unter uns zu haben, <Name>. Wir haben alle von Euren vergangenen Taten erfahren.\n\nWie Ihr wisst, ist König Wrynn dabei, große Armeen nach Nordend zu bewegen, die denen von Arthas begegnen sollen. Doch Armeen sind nichts ohne die Helden, die sie inspirieren und führen.\n\nIch möchte, dass Ihr <dieser Held/diese Heldin> für meine Männer seid. Kämpft an ihrer Seite gegen die Geißel, die unsere Festung belagert.\n\nMeldet Euch bei Unteroffizier Hammerberg außerhalb der inneren Burgwehr. Die Valianzfeste darf nicht fallen. Die Zukunft unserer Kampagne hängt davon ab.", progress = nil, completion = "Bei Magnis Bart! Sieht aus, als wäre die Artillerie gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11728] = {title = "Lupus pupus", objective = "Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr ihm 8 Mikrofilmteile bringt.", description = "Was auch immer Ihr macht, nehmt auf keinen Fall einen Happen von diesem Köder. Legt ihn einfach in der Nähe eines ölbeschmierten Wolfes. Wenn sie verzweifelt genug sind, den Mikrofilm zu fressen, dann werden sie sich wie wild auf den Köder stürzen, sobald sie ihn riechen.\n\nWartet einfach nur, bis die Dinge ihren natürlichen Lauf nehmen und sucht im... äh... Nebenprodukt nach dem Film.\n\nIch würde Euch ja meinen speziellen Lupus Pupus Spatus für den Job anbieten, aber ich habe ihn bei der Landebahn gelassen. Es tut mir leid, sagen zu müssen, dass Ihr die... ähhm... Suche auf die altmodische Art und Weise durchführen müsst.", progress = "Habt Ihr den Mikrofilm beschaffen können?", completion = "&lt;Iggy hält sich die Nase zu, als er den Mikrofilm entgegen nimmt.&gt;\n\nIgittigitt! Nun ja, wir haben Absatz 8.2, Paragraph B des Notfallprotokolls entsprechend den Film wieder beschafft. Nichts im Protokoll deutet jedoch darauf hin, dass ich es putzen muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11729] = {title = "Der Ultraüberschallschrauber", objective = "Liefert den Ultraüberschallschrauber bei Pfiffi Wackelspross ab. Sie befindet sich auf der Landebahn Kurbelzisch.", description = "Die Einheit, die Ihr soeben in ihre Bestandteile zerlegt habt, hatte das hier in ihrem Inneren.\n\nEs sieht ziemlich kompliziert aus... bei der Landebahn wird sicherlich jemand ein Auge drauf werfen wollen. Vielleicht Pfiffi Wackelspross?", progress = "Hey!", completion = "Mein Schraubenzieher... Ihr habt meinen Schraubenzieher gefunden! Hab mich schon gefragt, wo ich das Ding verloren hab'.\n\nHmm, Ihr habt es im Inneren eines ihrer Roboter gefunden, meint Ihr? Das bringt mich auf eine Idee...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11730] = {title = "Meister und Diener", objective = "Programmiert mithilfe des Ultraüberschallschrauber 15 Roboter um und kehrt anschließend wieder zu Pfiffi Wackelspross bei der Landebahn Kurbelzisch zurück.\n\nAchtet darauf, die kaputten Roboter zu plündern, bevor Ihr sie umprogrammiert.", description = "Der Ultraüberschallschrauber ist das ultimative Werkzeug, wenn es sich um das Bearbeiten von mechanischen Dingen dreht!\n\nGeht zurück zu den Teichen und zerlegt ein paar von Mechazods Robotern. Ihr müsst dann nur noch ihre Überreste mit dem Schraubenzieher bearbeiten und ich wette mit Euch, dass sie sich auf unsere Seite schlagen werden - zumindest für kurze Zeit.\n\nIch bin mir ziemlich sicher, dass er sich nicht auf die Mechagnome anwenden lässt, also könnt Ihr sie getrost ignorieren.\n\nOh, und falls die Roboter irgendwas dabei haben sollten, müsst Ihr es an Euch nehmen, bevor Ihr sie mit dem Schraubenzieher bearbeitet!", progress = nil, completion = "Juhuu! Und Ihr habt den Schraubenzieher in einem Stück zurückgebracht!\n\nDass wir diese Roboter umprogrammiert haben, wird sich noch als großer Vorteil im Kampf gegen Ritzelmeister Mechazod herausstellen. Ich meine, Ihr habt Euch eine Kleinigkeit dafür verdient.", rewards = "Mehrlagige FrosttunikaVerstärkter Helm aus KaribubälgenStachelmantel von MagmutBernsteinplattenbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11731] = {title = "Fackelwurf", objective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ... den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11732] = {title = "Entweiht dieses Feuer!", objective = "Entweiht das Freudenfeuer der Allianz im Arathihochland!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFreudenfeuer ausstampfen\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11733] = {title = "Reise zum Riss", objective = "Surristrasz möchte, dass Ihr die Reise nach Kaltarra antretet. Sobald Ihr dort angelangt seid, sollt Ihr mit Erzmagier Berinand sprechen.", description = "Ich habe Eure Taten aufmerksam verfolgt, <Sterblicher/Sterbliche>. Tut nicht so, als wärt Ihr überrascht. Mit Sicherheit habt Ihr gespürt, wie mein Auge auf Euch ruht.\n\nDie Zeit ist nun gekommen, Euch nicht mehr gänzlich im Dunkeln herumtappen zu lassen. Ihr seid nun bereit, der nackten Wahrheit ins Auge zu blicken.\n\nDoch bevor Ihr die Geschichte hört, sollt Ihr erst erfahren, womit wir es zu tun haben.\n\nTrefft alle nötigen Vorbereitungen, <Klasse>...", progress = nil, completion = "Willkommen in Kaltarra, &lt;Klasse&gt;.\n\nHinter dem Transitusschild liegen wir verborgen, nur einen Steinwurf weit vom Nexus entfernt, der Festung des großen Aspekts Malygos und seinem blauen Drachenschwarm.\n\nFühlt Euch wie Zuhause.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
