MultiLanguageQuestData['de'][11788] = {title = "Eine Schraube lockern", objective = "Nehmt Twonkie, ED-210, Max Kawummso und den Zermalmer auseinander und meldet Euch anschließend bei Jinky Flügelirre.", description = "Okay, denke, wir sind bereit, den vorletzten Angriff zu starten... Bevor Ihr jedoch Mechazod den Garaus machen könnt, müsst Ihr zuerst seine Leutnants auseinandernehmen!\n\nIhr findet Twonkie, ED-210, Max Kawummso und den Zermalmer jeweils an der West-, Nord-, Zentral- und Südstation.\n\nDreht einfach an den Ventilen bei den Stationen herum, um ihr Vorhaben zu sabotieren und sie hervorzulocken. Ihr könnt sie nicht übersehen: Bei jeder Station gibt es ein Drehlicht.", progress = nil, completion = "Wow, Ihr habt überlebt!\n\nIch denke, dass es nur noch eine Sache zu tun gibt. Kümmern wir uns um Ritzelmeister Mechazod.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11789] = {title = "Ein Soldat in Not", objective = "Sanitäter Hagedorn außerhalb der Valianzfeste möchte, dass Ihr Euch ins Innere des Laderaums der Sturmbrecher begebt und Hagedorns Gegengift aus einer Kiste mit Vorräten für Erste Hilfe beschafft.", description = "Ihr da! Bitte, ich brauche Eure Hilfe. Dieser Soldat wird dem Gift der Gruftbestie erliegen, wenn wir nicht sofort handeln.\n\nIch konnte die Wirkung des Giftes verlangsamen, doch ohne eine angemessene Menge Gegengift kann ich es nicht neutralisieren.\n\nMir wurde eine neue Lieferung Gegengift versprochen, die mit der letzten Sendung der Sturmbrecher aus dem Süden hätte ankommen sollen. Begebt Euch ins Innere ihres Frachtraums und sucht nach einer Kiste mit Material für Erste Hilfe.\n\nBeeilung, <Klasse>! Wir können es uns nicht leisten, weitere Männer unnötig sterben zu lassen.", progress = "Das Gegengift... Habt Ihr es bei Euch?", completion = "Ich danke Euch, &lt;Name&gt;. Dieser Mann wird sich zwar nur langsam erholen, doch verlieren werden wir ihn nicht.\n\nWas meint Ihr? Kultisten auf der Sturmbrecher? Ihr sagt besser jemandem Bescheid... und bringt etwas als Beweis mit.", rewards = "Ihr bekommt:\n\nErstklassiger Verjüngungstrank"}
MultiLanguageQuestData['de'][11790] = {title = "Kultisten unter uns", objective = "Sprecht mit Kapitän \"Linksdatsch\" Gaffelsegel an Deck der Sturmbrecher in der Valianzfeste.", description = "Auf diesem Altar befinden sich alle Markierungen des Kults der Verdammten. Es scheint, als hätten Fanatiker vom Festland es bis nach Nordend geschafft. Es wäre vielleicht klug, den Kapitän des Schiffs darüber in Kenntnis zu setzen.\n\nVielleicht befindet er sich über Deck.", progress = nil, completion = "Kultisten? Unter Deck? Ich werde wohl meine gesamte Crew auspeitschen lassen müssen!\n\nHört zu... wieso lassen wir nicht Admiral Kantelbree die Angelegenheit in die Hand nehmen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11791] = {title = "Benachrichtigt Arlos", objective = "Sprecht mit General Arlos im inneren Bereich der Valianzfeste.", description = "Wir müssen General Arlos so schnell wie möglich davon in Kenntnis setzen. Ich kenne den Hauptmann schon eine ganze Weile und, glaubt mir, er ist einer von der vorsichtigeren Sorte.\n\nWer weiß, wie viele Kultisten in anderen Schiffen in unsere Siedlungen hier in Nordend geschmuggelt wurden? Die Sache könnte verheerende Folgen haben.", progress = nil, completion = "Vielen Dank für Eure Anteilnahme, &lt;Name&gt;. Wir wurden erst vor Kurzem auf die Situation aufmerksam gemacht.\n\nBeirat Talbot hat mir versichert, dass dies ein vereinzelter Vorfall war und aus militärischer Sicht kein Grund zur Besorgnis besteht.\n\nUnsere zivilen Behörden werden sicherstellen, dass gegen jeden, der darin verwickelt ist, ordnungsgemäß vorgegangen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11792] = {title = "Feinde des Lichts", objective = "Herold Vurenn möchte, dass Ihr die Kultisten der Nekrolyten in der Nähe von Fernhain gen Norden der Valianzfeste bekämpft und ihnen das Kommuniqué der Kultisten abnehmt.", description = "Nun macht mal halblang. Ich weiß nicht, wie es Euch geht, <Klasse>, aber mich konnten die Worte des Generals nicht so wirklich überzeugen. Sie klangen so unsicher... als wären sie nicht die seinen.\n\nIrgendetwas stimmt hier nicht. All unsere Versuche, gemeinsam an der Sache zu arbeiten, wurden blockiert und verzögert. Es ist an der Zeit, das Ganze etwas selbstständiger anzugehen.\n\nWenn wir mehr über die Kultisten in der Festung herausfinden möchten... dann sollten wir vielleicht denjenigen nachgehen, die sich außerhalb befinden.\n\nBerichten unseres Geheimdienstes zufolge gibt es nördlich von hier eine kleine Gruppe von ihnen, welche die Geißel in ihrem Treiben unterstützt. Findet heraus, ob sie irgendwelche Hinweise bei sich tragen.", progress = "Ihr seid zurück, <Name>.", completion = "Diskretion, &lt;Name&gt;. Wir können uns dieses Beweismaterial nicht ansehen, solange neugierige Blicke auf uns gerichtet sind.", rewards = "Beinschützer des MarschenläufersHelmkappe des TundraschreitersGroßfelsbrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nZorn des Herolds\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11793] = {title = "Weitere Ermittlungen", objective = "Bringt das Kommuniqué der Kultisten zu Verteidigerin Yaala im Gasthaus der Valianzfeste.", description = "Ich befürchte, dass es sich hier um eine Angelegenheit handelt, die ich einem meiner Agenten übertragen muss... jemanden, der im Geheimen operieren kann. Behaltet das Beweisstück bei Euch und bringt es zu Verteidigerin Yaala im Gasthaus. \n\nSagt ihr, dass ich Euch geschickt habe, und sprecht mit niemanden sonst über diese Sache. Wir wissen nicht, wer alles für den Kult arbeiten könnte.", progress = "Herold Vurenn hat Euch geschickt?", completion = "Verschwendet keine Zeit, &lt;Klasse&gt;. Was sind das für Informationen, die Ihr über den Kult habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11794] = {title = "Die Jagd ist eröffnet", objective = "Verteidigerin Yaala möchte, dass Ihr das Okular des Exorzisten an den drei genannten Orten in der Valianzfeste einsetzt, um die Mitglieder des Kults der Verdammten zu enttarnen und zu töten.", description = "Ich habe es zu meiner persönlichen Angelegenheit gemacht, so viel wie möglich über den hinterlistigen Todeskult herauszufinden, einschließlich ihrer Geheimsprache.\n\nVurenn hatte recht. Die Kultisten sprechen von getarnten Agenten, die sich an verschiedenen Orten innerhalb der Valianzfeste aufhalten sollen: den unteren Docks, dem Gefängnis im Inneren der Festung und der Küche des Gasthauses.\n\nNehmt dieses Okular und verwendet es an den soeben erwähnten Orten. Jeder, der erst vor Kurzem die nekromantischen Kräfte des Kults benutzt hat, wird von einer dunklen Aura umhüllt sein. Kümmert Euch um die Kultisten, bevor etwas Schlimmes geschieht.", progress = "Habt Ihr die Aufgabe erledigt, um die ich Euch gebeten habe, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Ich bekomme das Gefühl jedoch nicht los, dass es nicht das Letzte ist, was wir von diesen Todeskultisten hören werden.\n\nDie Dunkelheit hat es so an sich, selbst bei klarer Sicht vor dem Auge verborgen zu bleiben", rewards = "Transboreanische GamaschenSchulterstücke des MarschenläufersRingpanzer des TundraschreitersGroßfelshelmIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11795] = {title = "Notfallprotokoll: Sektion 8,2. Absatz C", objective = "Beschafft 6 Insignien eines Piloten von Kurbelzisch von den Leichnamen der Aufklärungspiloten von Kurbelzisch und bringt sie zurück zu Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen.", description = "Verletzt oder nicht, als Schwadronenkommandant bin ich dafür verantwortlich, die Insignien aller Piloten, die unter meinem Kommando gefallen sind, zu finden und zurückzubringen. In all den Jahren, die ich mit Kurbelzisch geflogen bin, ist es noch nie vorgekommen, dass wir das Siegel eines Piloten nicht zurückgebracht haben.\n\nAufgrund meiner Verletzung wäre es gefährlich für mich, außerhalb der Sicherheit des Wracks umherzustreifen, doch vielleicht wärt Ihr bereit, mir dabei zu helfen, die Insignien zurückzubekommen? In der Zwischenzeit werde ich Vorbereitungen treffen, um meine letzte Pflicht als Schwadronenkommandant zu erfüllen.", progress = "Habt Ihr die Insignien bei Euch?", completion = "Nochmals danke, &lt;Name&gt;. Dank Eurer Hilfe werde ich diese Mission, so katastrophal sie auch war, vielleicht endlich abschließen, Kurbelzisch Bericht abstatten und den Toten gebührenden Respekt zollen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11796] = {title = "Notfallprotokoll: Sektion 8,2. Paragraph D", objective = "Iggy \"Trudelflug\" Zinkenwechsel möchte, dass Ihr die Wracks im Osten, Süden und Nordwesten beseitigt.", description = "Es gibt nur noch eine Sache zu tun, bevor ich endlich wieder zur Landebahn zurückkehren und meinen Bericht erstatten kann. Laut Abschnitt 8.2, Paragraph D des Notfallprotokolls muss ich so viele Wrackteile wie nur möglich beseitigen, um zu verhindern, dass unsere Technologie in feindliche Hände gerät.\n\nIch werde Euch meine Fackel geben, wenn Ihr mir dabei helfen wollt, diesen letzten Dienst zu erfüllen. Ich will gar nicht daran denken, was die Goblins der Horde alles anstellen würden, wenn sie diese Maschinen in die Finger bekämen.", progress = "Habt Ihr die Wrackteile schon beseitigt?", completion = "Und wieder einmal hab ich Euch zu danken, &lt;Name&gt;. Ohne Eure Hilfe wäre nichts Nützliches bei diesem Unglück herausgesprungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11797] = {title = "Die Belagerung", objective = "Unteroffizier Hammerberg möchte, dass Ihr 6 Gruftkriecher auf den Sanden von Nasam außerhalb der Valianzfeste tötet.", description = "Aber, aber, aber. Es ist gut zu sehen, dass Arlos schwere Geschütze auffährt.\n\nVersteht mich nicht falsch - unsere Jungs geben ihr Bestes, doch kämpfte jemand Eures Kalibers an ihrer Seite, stünden die Chancen sehr gut, dass sich die Schlacht zu unseren Gunsten wendet. Ich bin mir nicht sicher, wie lange wir noch gegen diese untoten Neruber durchhalten können.\n\nWas würdet Ihr davon halten, dort hinauszugehen und ein paar dieser Kriecher für mich zu töten? Zeigt den Jungs, wie's gemacht wird.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Zeigt den Jungs, wie's gemacht wird. Nur ein toter Kriecher ist auch ein guter Kriecher!", rewards = "Schlängelnder StabStachelkolben des SoldatenHeimtückische ZauberklingeMorgenstern des SanitätersGroßschwert des KampferfahrenenLangbogen der ValianzfesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11798] = {title = "Der Ritzelmeister", objective = "Untersucht das Handbuch des Ritzelmeisters und bringt Mechazods Kopf zu Kurbelzisch Vollgas zurück.", description = "Ritzelmeister Mechazod ist wahnsinnig! Er meint, er schenke uns Unsterblichkeit, indem er den sogenannten 'Fluch des Fleisches' entfernt, doch was er in Wahrheit aus uns macht, sind mechanische Sklaven!\n\n<Name>, wir sind uns ziemlich sicher, dass er sich immer noch in der Pumpstation draußen in der Mitte des Teiches gen Osten aufhält.\n\nDas letzte Mal, als wir ihn sahen, war er ganz oben im Führerhäuschen. Geht dort hoch und untersucht sein Zeug.\n\nIhr müsst Euch Mechazod stellen, wenn die Gnome... nein, wenn überhaupt jemand überleben soll!", progress = "Jinky hat mir gesagt, dass Ihr zu mir kommen würdet. Ist es vollbracht?", completion = "&lt;Der alte Gnom gibt einen lauten erleichterten Seufzer von sich.&gt;\n\nEs ist also getan... Ihr habt uns gerettet! Wer weiß, wie weit sich sein Wahnsinn verbreitet hätte, hättet Ihr ihn nicht aufgehalten?\n\nAngesichts der Bedrohung durch die blauen Großdrachen und den Nexuskrieg, geschweige denn den Lichkönig, ist das Letzte, was wir brauchen, eine frei herumlaufende, verrückte Schöpfung der Titanen!\n\nIch danke Euch, &lt;Name&gt;!", rewards = "Bedeckung des HeilersRegenerativer BalgharnischGekühlte KettenstiefelAuf Euch wartet eine dieser Belohnungen:\n\nMörderischer Eisring\n\nIhr bekommt außerdem:\n\n"}
