MultiLanguageQuestData['de'][11864] = {title = "Eine Missionsrichtlinie", objective = "Der Dämon hat viele Namen und jeder Name hat zur einen oder anderen Zeit eine besondere Bedeutung gehabt. Während die Einzelheiten eher unwichtig waren, war das Ergebnis immer dasselbe: der Tod.\n\nDoch nun, fast fünfzig Jahre nachdem alles begann, wird das Detail ausnahmsweise den Teufel einholen und zu seinem Untergang führen.\n\nDiesmal haben wir ihn... Es wird kein Entrinnen für Nesingwary geben.\n\nNordend wird als Schlachtfeld unseres Kampfes dienen. Der Jäger wird zum Gejagten!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11865] = {title = "Des Todes unwürdig", objective = "Zaza beim Lager der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr den Haufen Kunstpelze dazu verwendet, um 8 von Nesingwarys Fallenstellern in die Falle zu locken.", description = "Gleich südlich von hier streiften einst Karibus frei und in Frieden umher. Doch dann kam Nesingwary und alles wurde anders. Nun befinden sich die Karibus in einem ständigen Zustand der Raserei und Panik. Sie werden von den im Feld versteckten Jägern und Fallenstellern gejagt.\n\nNesingwarys Henker sind nicht einmal des Todes würdig. Sie müssen dieselben Qualen erleiden, die sie den Karibus zufügen!\n\nNehmt diesen Haufen Kunstpelze und legt sie auf die Karibufallen, die im Süden aufgestellt sind. Beobachtet, wie die Jäger in ihre eigenen tödlichen Fallen tappen!", progress = "Habt kein Mitleid mit ihnen, <Volk>.", completion = "Ihr führt der Erdenmutter Arbeit aus, &lt;Name&gt;, doch genießt Euren Sieg nicht allzu lange. Wir haben das Versteck des Anführers der Fallensteller entdeckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11866] = {title = "Die Ohren unserer Feinde", objective = "Erzdruide Lathorius beim Lager der D.E.H.T.A. in der Boreanischen Tundra hat gesagt, dass er Euch belohnen wird, wenn Ihr ihm 15 Ohren von Nesingwarys Lakaien bringt.", description = "Ob sie Schatzsucher sind oder blutrünstige Jäger der Steppe, jeder, der Nesingwary unterstützt und es wagt, gegen unsere geliebte Tierwelt vorzugehen, soll als Feind der D.E.H.T.A. betrachtet werden.\n\nSolltet Ihr diese dreckigen Sympathisanten von Nesingwary umbringen, bringt mir einen Beweis ihres Ablebens und Ihr sollt mit einem Segen der Druiden der D.E.H.T.A. belohnt werden.", progress = "Ohren erfüllen den Zweck doch sehr wohl...", completion = "Die werde ich mir um den Hals hängen. Lasst sie unsere Botschaft hören und lasst diese Ohren die Überbringer unserer Wahrheit sein!", rewards = "Ihr erlernt:\n\nSegen der D.E.H.T.A.\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11867] = {title = "Spitzt die Ohren", objective = "Erzdruide Lathorius beim Lager der D.E.H.T.A. in der Boreanischen Tundra hat gesagt, dass er Euch belohnen wird, wenn Ihr ihm 15 Ohren von Nesingwarys Lakaien bringt.", description = "Ob sie Schatzsucher sind oder blutrünstige Jäger der Steppe, jeder, der Nesingwary unterstützt und es wagt, gegen unsere geliebte Tierwelt vorzugehen, soll als Feind der D.E.H.T.A. betrachtet werden. Solltet Ihr diese dreckigen Sympathisanten von Nesingwary umbringen, bringt mir einen Beweis ihres Ablebens und Ihr sollt mit einem Segen der Druiden der D.E.H.T.A. belohnt werden.", progress = "Ob sie Schatzsucher sind oder blutrünstige Jäger der Steppe, jeder, der Nesingwary unterstützt und es wagt, gegen unsere geliebte Tierwelt vorzugehen, soll als Feind der D.E.H.T.A. betrachtet werden.\n\nSolltet Ihr diese dreckigen Sympathisanten von Nesingwary umbringen, bringt mir einen Beweis ihres Ablebens und Ihr sollt mit einem Segen der Druiden der D.E.H.T.A. belohnt werden.", completion = "Die werde ich mir um den Hals hängen. Lasst sie unsere Botschaft hören und lasst diese Ohren die Überbringer unserer Wahrheit sein!", rewards = "Ihr erlernt:\n\nSegen der D.E.H.T.A."}
MultiLanguageQuestData['de'][11868] = {title = "Die Schlächterin wird kommen", objective = "Zaza beim Lager der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr Karen die Schlächterin tötet.", description = "Am südlichen Zipfel dieser Klippen werdet Ihr die heimtückische Anführerin der Karibujäger finden. So barbarisch wie sie ist keine Zweite: Sie schändet die Kadaver der erlegten Tiere, indem sie ihr Blut trinkt und die Monde anheult!\n\nFindet diese Mörderin. Findet Karen und bereitet ihrem wertlosen Dasein ein Ende.\n\nBereitet Euch ordentlich vor, <Name>. Karen die Schlächterin tut sich an den Reichtümern gütlich, mit denen Nesingwary sie überhäuft hat!", progress = nil, completion = "Vielleicht wird ihr Tod Anderen, die es wagen sollten, Tiere nur des Sports und der Reichtümer wegen zu töten, eine Lehre sein.", rewards = "NymphenstrümpfeTuch des AngreifersGurt des BindersBeinplatten des EbenenhütersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11869] = {title = "Glücklich wie eine Turnmuschel", objective = "Hierophantin Cenius beim Lager der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr 10 beutegierige Taucher tötet.", description = "Westlich von uns befindet sich der Kum'uyasee. Soviel wir wissen, ist es das einzige Habitat für Süßwasserriesenmuscheln auf der ganzen Welt.\n\nNatürlich wird der See heute von Nesingwarys Lakaien als Farm zur Riesenperlenzucht genutzt. Sie müssen aufgehalten werden! Jedem, der die Bedrohung einer ganzen Spezies in Kauf nimmt, muss eine Lektion erteilt werden.\n\nGeht zum Kum'uyasee und sucht nach den beuteverrückten Tauchern. Erschlagt so viele von ihnen, bis sich das Wasser rot färbt! Kehrt wieder zu mir zurück, sobald Ihr ein Exempel statuiert habt!", progress = nil, completion = "Na dann lasst uns mal sehen, wie stark ihre Nerven sein werden, wenn sie erst sehen, was aus ihren Kameraden geworden ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11870] = {title = "Die Verlassenen Weiten", objective = "Sucht Hierophantin Liandra in den Verlassenen Weiten auf.", description = "Wir haben soeben Nachricht von Liandra erhalten, dass von Nesingwary angeheuerte Söldner Waren vom Strand auf Nesingwarys Hauptfrachtschiff verladen. Sie versuchen zweifellos Profit aus ihrem blutrünstigen Handel zu schlagen!\n\nSie hat uns darum gebeten, Verstärkung zu den Verlassenen Weiten, die sich direkt südlich von hier am Strand der Boreanischen Tundra befinden, zu entsenden.\n\nLasst Eile walten, Liandra erwartet Euch dort!", progress = nil, completion = "Cenius hat Euch geschickt? Nun, Ihr seid keinen Moment zu früh!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11871] = {title = "Nicht, solange wir Wache halten", objective = "Hierophantin Liandra in den Verlassenen Weiten in der Boreanischen Tundra möchte, dass ihr 12 Lieferungen von Tierteilen beschafft.", description = "Überall auf diesem Strand verteilt, inmitten des Treib- und Strandguts befinden sich Kisten und Säcke voll mit Leichenteilen von Tieren. Es scheint, als würde Nesingwary mit den Freibeutern des Nordmeeres gemeinsame Sache machen. Diese dreckigen Piraten transportieren die Waren, die Nesingwarys mordlustige Lakaien vor der Küste sammeln. Es besteht kein Zweifel daran, dass all diese Sachen in den Heimen und auf den Schultern reicher, skrupelloser Individuen auf ganz Azeroth landen werden.\n\nDoch das wird nicht passieren. Nicht, solange wir Wache halten. Bringt mir alle Lieferungen, die Ihr auf diesem Strand finden könnt. Sie werden sie niemals in die Finger bekommen!", progress = "Wir werden diesen Tieren ein ordentliches Begräbnis geben.", completion = "Gute Arbeit, &lt;Name&gt;. Nun lasst uns den Anführer der Piraten angreifen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11872] = {title = "Der ruchlose Käpt'n...", objective = "Erschlagt Käpt'n I. Glu, kehrt anschließend ins Lager der D.E.H.T.A. zurück und sprecht mit Hierophantin Cenius.", description = "Es ist wirklich abscheulich, sich selbst den Namen \"Käpt'n I. Glu\" zu verleihen, als ob man über alle Kreaturen der See Herr wäre. Niemandem ist es erlaubt, solch einen Anspruch zu erheben!\n\nDieser \"Käpt'n I. Glu\" muss gefunden und erschlagen werden. Er wurde zuletzt beim Wrack direkt vor der Küste der Verlassenen Weiten gesehen. Findet und tötet ihn.\n\nKehrt zu Hierophantin Cenius beim Lager der D.E.H.T.A. zurück, sobald es vollbracht ist, und lasst sie wissen, dass die Mission ein Erfolg war.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Wir rücken Nesingwary auf den Pelz!", rewards = "Rute der WilddiebbestrafungWünschelruteZauberstab des BewahrersFlinke KlingeG.E.H.T.A.Boreanische BarriereIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11873] = {title = "Teilt Kurbelzisch die Neuigkeiten mit", objective = "Begebt Euch zurück zur Landebahn Kurbelzisch und sprecht mit Kurbelzisch Vollgas.", description = "Währet Ihr so freundlich und würdet zurück zur Landebahn gehen, um Kurbelzisch mitzuteilen, dass ich in Kürze komme, um meinen förmlichen Bericht abzuliefern? Ich muss mich um das Wrack meiner Flugmaschine kümmern und dann mache ich mich auf den Weg.\n\nIch bin sicher, dass Kurbelzisch weiß, dass er Euch dafür danken muss, dass ich noch lebe und für die Rückholversuche.\n\nIch frage mich nur, was der alte Mann selbst gemacht hätte, wenn er mit uns geflogen wäre. Diese Zeiten fehlen mir.", progress = nil, completion = "&lt;Kurbelzisch hört sich erleichtert Euren Bericht an.&gt;\n\nIch hätte sie begleiten sollen. Wir wären vielleicht in der Lage gewesen, die Mission zu Ende zu bringen ohne einen Piloten zu verlieren.\n\nTrudelflug hat jedoch Recht, wir haben Euch für das, was Ihr retten konntet, zu danken. Eure Mühe könnte im Kampf gegen die Neruber eventuell entscheidend sein.", rewards = "Mantel des starren ZornsVerstärkte Gamaschen aus KaribubälgenStachelhelm von MagmutBernsteinplattenhandschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11875] = {title = "Einen Vorteil gewinnen", objective = "Bringt dem Abgesandten Mordin in Shattrath 8 Netherrückstände.", description = "Die Truppen der Offensive der Zerschmetterten Sonne werden jeden Vorteil, den sie sich verschaffen können, nutzen müssen, um Kil'Jaedens Verbündete zurückzuschlagen. Meine Kollegen in Sturmwind haben Öle hergestellt, mit deren Hilfe wir die Klingen und Rüstungen unserer Truppen verstärken können.\n\nDie Hauptzutat - ich spreche von Netherrückständen - gibt es überall in der Scherbenwelt. Man muss nur wissen, wo man suchen muss. Jeder Meister der Kräuterkunde, Kürschnerei und des Bergbaus, der die Zeichen kennt, kann sie sammeln und gleichzeitig seinem Gewerbe nachgehen. Finden kann man die Rückstände nur bei Kräutern, Erzen und Bestien, die allesamt ausschließlich in der Scherbenwelt zu finden sind.", progress = "Habt Ihr Netherrückstände bei Euch?", completion = "Danke für Eure Hilfe, &lt;Name&gt;. Jeder Beitrag für die Kriegsvorbereitungen zählt. Unsere Männer werden jeden Vorteil nutzen müssen, den sie sich verschaffen können.", rewards = "Ihr bekommt:\n\nErheblicher Verjüngungstrank"}
MultiLanguageQuestData['de'][11876] = {title = "Hilfe für die Hilflosen", objective = "Erzdruide Lathorius beim Lager der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr mithilfe des Fallenzerstörers der D.E.H.T.A. 8 Mammutkälber befreit.", description = "Majestätische Tiere, findet Ihr nicht?\n\n<Lathorius deutet auf die Mammuts der nördlichen Tundra.>\n\nMit jedem weiteren Tag schwindet ihre Zahl. Dämonen, die sich selbst als Jäger bezeichnen, erlegen sie des Sports und der Reichtümer wegen.\n\n<Lathorius' Gesicht verzerrt sich vor Wut.>\n\nEs ist das Winseln, das mich wahnsinnig macht, <Name>. Ihr könnt hören, wie der Wind es durch die Luft trägt. Die Mammutkälber, die in den schrecklichen Fallen der Jäger gefangen sind, rufen nach uns.\n\nNehmt den Hammer hier und zertrümmert diese Fallen. Befreit die Kälber!", progress = nil, completion = "&lt;Erzdruide Lathorius wischt sich die Tränen aus dem Gesicht.&gt;\n\nSie hatten niemals eine Chance. Verwaist und alleine, wie sie nun sind, werden sie sicherlich sterben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11877] = {title = "Angriffspläne des Sonnenzorns", objective = "Lord Torvos in Shattrath möchte, dass Ihr die Angriffspläne des Sonnenzorns beschafft.", description = "Wir verstärken unsere Offensive auf Quel'Danas und haben herausgefunden, dass Kael'thas' Diener einen Gegenangriff planen. Er hofft, dass die Angriffe seiner im Nethersturm stationierten Blutelfen des Sonnenzorns unsere Aufmerksamkeit vom Sonnenbrunnen ablenken und uns dazu bringen werden, Truppen abzuziehen.\n\nWir dürfen das nicht zulassen, <Name>. An dieser Front wird jede Klinge benötigt.\n\nReist in den Nethersturm und beschafft Euch ihre Angriffspläne. Jeder der Blutelfen des Sonnenzorns dort oben könnte die Pläne bei sich tragen. Viel Glück, <Name>.", progress = "Seid Ihr mit den Plänen zurückgekommen?", completion = "&lt;Lord Torvos nimmt die Pläne entgegen und sieht sie sich an.&gt;\n\nIhr habt der Offensive einen großen Dienst erwiesen, &lt;Name&gt;. Wir sollten uns jedoch keine Ruhe gönnen. Unsere Feinde werden in Zukunft sicherlich noch mehr Unheil über uns bringen.", rewards = "Ihr bekommt:\n\nVorratspaket der Zerschmetterten Sonne"}
MultiLanguageQuestData['de'][11878] = {title = "Khu'nok wird's wissen", objective = "Bringt das verwaiste Mammutkalb zu Khu'nok dem Ungetüm in der Boreanischen Tundra.", description = "Es war wohl eine tapfere Tat, die gefangenen Kälber zu befreien, doch werden viele von ihnen sterben. Seht: Ohne jemanden, der auf sie Acht gibt, sind diese Kälber in der Wildnis ganz auf sich alleine gestellt.\n\nDoch es gibt eine Möglichkeit! Noch immer bleibt Hoffnung!\n\nNördlich von hier, auf den Mammutfeldern direkt bei den Siedenden Teichen, findet Ihr Khu'nok das Ungetüm: ein Mammut, so weise wie sein unendlich hohes Alter. Nehmt dieses verwaiste Mammut und liefert es bei Khu'nok ab. Er wird wissen, was damit zu tun ist.", progress = nil, completion = "&lt;Euer Geist vernimmt eine Stimme. Es ist Khu'nok.&gt;\n\nIch hörte Euren Namen in den pfeifenden Winden, &lt;Name&gt;. Ihr habt für meinesgleichen Großes vollbracht. Deswegen betrachten wir Euch als Verbündeten. Weh mir, unsere Qual kann nicht ohne Blutvergießen und Gewalt ein Ende finden.\n\nDer Preis des Friedens für die Mammuts wird Kraas Tod sein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11879] = {title = "Kraa der Mammutvernichter", objective = "Tötet Kraa den Mammutvernichter und beschafft Euch Kraas Kriegshellebarde. Liefert Kraas Kriegshellebarde bei Erzdruide Lathorius beim Lager der D.E.H.T.A. in der Boreanischen Tundra ab.", description = "Ihr könnt das Wesen, welches für das Gemetzel an meinem Volk verantwortlich ist, nicht alleine besiegen. Die Mammuts der Tundra werden Euch helfen!\n\nGeht auf die Ebenen hinaus und sucht einen Mammutbullen. Er wird sich von Euch reiten und kontrollieren lassen. Steigt auf und reitet zu Kraas Ruhestätte. Gemeinsam werdet Ihr sein Ende herbeiführen.\n\nVernichtet Kraas Armeen und nehmt ihm seine begehrte Kriegshellebarde ab. Kehrt zu Lathorius beim Lager der D.E.H.T.A. zurück, solltet Ihr erfolgreich sein.", progress = "Was ist passiert?", completion = "&lt;Lathorius nimmt Euch die Hellebarde ab.&gt;\n\nIst es das, was ich denke?\n\n&lt;Lathorius grinst.&gt;\n\nKlasse! Ausgezeichnet! Und wieder wurde einer von Nesingwarys Lakaien seiner gerechten Strafe zugeführt!", rewards = "Überhemd der D.E.H.T.A.KunstlederkapuzeEthische SchulterklappenSabatons der MoralIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11880] = {title = "Die Multiphasen-Vermessung", objective = "Herold Haronem in Shattrath möchte, dass Ihr die spektrografische Multiphasenbrille benutzt, um 6 Multiphasenmessungen durchzuführen.", description = "Ich bin mir sicher, dass der 'gnomische Erfinder' ein Spinner ist. Er sprach von irgendwelchen dunklen Verzerrungen, die um Oshu'gun in den Geisterfeldern in Nagrand aufgetaucht sind.\n\nLaut seiner Aussage, soll diese, äh, spektrografische... öh... Multiphasen-Brille es dem Träger erlauben, die Verzerrungen zu sehen und Messungen an ihnen vorzunehmen. Er bestand darauf, dass es für unser Vorhaben am Sonnenbrunnen äußerst wichtig sei, diese Daten zu sammeln. Ich denke zwar, dass er einen Sprung in der Schüssel hat, jedoch wurde ich damit beauftragt, alles zu untersuchen, was vielleicht hilfreich sein könnte. Hättet Ihr etwas dagegen, Messungen durchzuführen?", progress = "Konntet Ihr die Messungen durchführen? Der Gnom wird mich wieder anbrüllen, wenn ich die kostbaren Daten nicht herbekomme.", completion = "Danke für Eure Hilfe. Ihr wisst gar nicht, wie es ist, wenn man sich mit 'Doktor' Waffelfritte dort drüben auseinandersetzen muss. Wenn er nicht gerade damit beschäftigt ist, meinen Fortschritt zu 'überprüfen', verhökert er gerade eines seiner Geräte - die übrigens alle Erfindungen für militärische Zwecke sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11881] = {title = "Fertig zum Transport!", objective = "Helft Jenny dabei, von der Absturzstelle bis nach Taunka'le zu Fezzix Drehgang zu gelangen, ohne dabei ihre ganze Ladung zu verlieren.", description = "Habt Ihr die Flugmaschinen gesehen, die hier in der Gegend herumschwirren? Das ist das Nonplusultra gnomischer Innovation.\n\nIch habe lange darauf gewartet, ihre Technologie in die Finger zu bekommen, und jetzt bietet sich mir die perfekte Möglichkeit. Eines ihrer Aufklärungsgeschwader ist in den Siedenden Teichen, dem südwestlichen Teil der Geysirfelder, abgestürzt.\n\nBlast diese Pfeife in der Nähe einer der abgestürzten Maschinen und mein getreues Muli Jenny wird Euren Ruf hören. Sie wird Euch folgen und das Wrack mitschleppen, doch Ihr müsst sie beschützen. Sie lässt ihre Ladung nämlich fallen, sobald sie angegriffen wird.", progress = "Versagt nicht! Ich zähle auf Euch.", completion = "&lt;Fezzix inspiziert das Wrack.&gt;\n\nJenny sieht zwar ein wenig fertig aus, aber sie wird's schon überstehen. Was das Wrack angeht: Es ist zwar etwas... angeschlagener als ich gehofft habe, aber ich sollte einen Nutzen dafür finden können. Ihr seid jedoch noch nicht aus dem Schneider. Wir werden das Baby hier wieder zusammenbauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11882] = {title = "Spiel mit dem Feuer", objective = "Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte.", description = "Möchtet Ihr ein paar heiße neue Fertigkeiten erlernen?\n\nOb Ihr jemals meine beeindruckende Fertigkeit erreichen werdet, sei zwar dahingestellt, aber ein oder zwei Kunststückchen werdet Ihr wahrscheinlich aufschnappen können, wenn Ihr <ein aufmerksamer Schüler/eine aufmerksame Schülerin> seid. Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.", progress = nil, completion = "Grüße. Seid Ihr hier, um zu lernen, was man mit Feuer alles machen kann?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11883] = {title = "Feuertanzen?", objective = "Sprecht mit einem Feuertanzmeister in einer der Hauptstädte.Ihr wollt die Feuertanzkunst erlernen?\n\nNun, dann sprecht einfach mit einem Feuertanzmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr wollt die Feuertanzkunst erlernen?\n\nNun, dann sprecht einfach mit einem Feuertanzmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11884] = {title = "Nedar, Herr der Rhinozerosse", objective = "Killinger der Höhlenbehüter im Außenposten der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr Nedar, den Herrn der Rhinozerosse, und seinen Begleiter \"Vesperhino\" tötet.", description = "Westlich von hier, auf den hohen Klippen über dem Kum'uyasee streift ein abscheuliches Wesen namens Nedar umher. Der selbsternannte \"Herr der Rhinozerosse\" macht in den Ödlanden Jagd auf verletzte oder junge Beute - Rhinozerosse, die sich nicht gegen seine feigen Angriffe wehren können. Um das Ganze noch schlimmer zu machen: Nedar hat selbst ein Rhinozeros großgezogen, das ihm als Reittier und Beschützer dient.\n\nEs kommt selten vor, dass D.E.H.T.A. jemals den Tod eines Tieres verlangen würde, doch Nedars verdorbenes Rhinozeros muss aus der Welt geschafft werden... Tötet sie beide und kehrt zu mir zurück.", progress = "Habt Ihr sie beide erschlagen?", completion = "Zumindest werden die Rhinozerosse jetzt wieder in Frieden leben können. Ich danke Euch, &lt;Name&gt;.", rewards = "Regenerativer StoffGamaschen des HöhlenwächtersKopfstück des ScharfsehersBlockade des EbenenhütersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11885] = {title = "Feindesblut", objective = "Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück.", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Karrog der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Benutzt sie bei den Beschwörungskreisen, die es in Skettis gibt. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mitzunehmen.", progress = nil, completion = "Hervorragend! Hier, nehmt dies. Ich habe dieses Bündel aus den Gegenständen erstellt, die Ihr mir gebracht habt. Damit werdet Ihr Terokk beschwören können.\n\nSeid auf der Hut, &lt;Name&gt;. Er ist der mächtigste Arakkoa aller Zeiten. Unterschätzt ihn nicht!", rewards = "Ihr bekommt:\n\nZeitverlorene Opfergabe"}
MultiLanguageQuestData['de'][11886] = {title = "Ungewöhnliche Aktivitäten", objective = "Geht zum Lager des Schattenhammers südlich des Eingangs zur Tiefschwarzen Grotte am Zoramstrand im Eschental und sucht nach Briefen des Schattenhammers. Die Kultisten werden sie voraussichtlich bei sich tragen. Benutzt anschließend das totemische Leuchtfeuer, um einen Führer des Irdenen Rings zu beschwören.", description = "Spaß und Frivolität müssen sein, <Klasse>, doch einige von uns haben sich ernsteren Angelegenheiten zu widmen.\n\nZu Beginn des Festes erhielten wir Kunde von unseren Anhängern nahe des Zoramstrands über stark erhöhte Aktivitäten des Schattenhammerkults. Die Macht, die diese Wahnsinnigen verehren, ist tief in der Entstehungsgeschichte dieser Festtage verwurzelt. Dies kann kein Zufall sein. Begebt Euch zum Lager in den Ruinen südlich des Eingangs zur Tiefschwarzen Grotte und findet heraus, ob die Kultisten Informationen liefern können - wendet Gewalt an, falls nötig. Platziert dieses Leuchtfeuer auf dem Boden, sobald Ihr etwas gefunden habt, um einen Führer des Irdenen Rings zu beschwören.", progress = "Was habt Ihr entdeckt?", completion = "Das ist Besorgnis erregend, mein Freund. Es deutet daraufhin, dass hinter der bloßen Unruhe der örtlichen Feuer- und Wasserelementare etwas viel Größeres steckt und diesem Etwas auf den Grund gegangen werden muss...", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11887] = {title = "Notrationen", objective = "Sammelt 7 gnomische Notfallwerkzeugkästen und bringt sie zu Fezzix Drehgang in Taunka'le. Die Kästen findet Ihr bei den Leichen abgestürzter Aufklärungspiloten von Kurbelzisch.", description = "Als Ihr das Hab und Gut des toten Gnoms durchwühlt, fällt Euch ein kleines Paket auf, das mit Rationen, Werkzeugen und einem praktischen, gnomischen Klebeband gefüllt ist. Der Inhalt dieser Kästen könnte für Fezzix Drehgang vielleicht hilfreich sein, wenn die Zeit für ihn gekommen ist, das Wrack der gnomischen Flugmaschinen wieder zusammenzubauen.\n\nEin paar dieser Werkzeugkästen zu Fezzix zu bringen, könnte vielleicht sogar eine Belohnung wert sein.", progress = "Was habt Ihr denn da?", completion = "Gnomische Werkzeuge? Für mich? Die sollten das um einiges einfacher machen, als ich es erwartet habe, diese Flugmaschine wieder zusammenzubauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11888] = {title = "Reitet nach Taunka'le", objective = "Sprecht mit Weiser Erde und Himmel in Taunka'le.", description = "<Volk>, der Häuptling lässt sich Zeit... Zeit, die Taunka'le nicht hat!\n\nMan spricht über Euch und davon, wie tapfer Ihr seid. Anstatt darauf zu warten, dass Garrosh Hilfe schickt, bitte ich Euch darum, dass Ihr meinem Volke helft.\n\nTaunka'le liegt weit im Nordosten. Folgt der Straße nach Osten aus der Festung heraus und geht an der Kreuzung in Richtung Norden. Danach wird es nicht lange dauern, bis Ihr zu einer weiteren Kreuzung kommt. Folgt dem Pfad nach Osten, südlich und dann östlich der großen Teiche entlang des Randes der Flutebenen.\n\nSprecht mit dem Weisen Erde und Himmel, wenn Ihr ankommt.", progress = nil, completion = "Es überrascht mich nicht, dass der Häuptling der Orcs keine Zeit für unsere Probleme hat. Die Anstrengungen des Abgesandten sind nur ein Tropfen auf den heißen Stein.\n\nDoch nun seid Ihr hier. Wir werden sehen, ob es eine gute Idee gewesen ist, Euch zu schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11889] = {title = "Der Tod lauert in der Luft", objective = "Unteroffizier Hammerberg möchte, dass Ihr mithilfe des verstärkten Netzes 6 verseuchte Flammenspucker außerhalb der Valianzfeste tötet.", description = "Es gelingt uns, die Front gegen diese Insekten aufrecht zu halten. Einige dieser frechen Scheusale können jedoch über die eben erwähnte Frontlinie einfach hinwegfliegen und prasseln wie Geschosse auf unsere inneren Verteidigungsstellungen herab.\n\nIch habe verstärkte Fischernetze von den Schiffen unserer Zivilisten angefordert. Wenn Ihr einen guten Wurfarm habt, werden sie Euch dabei helfen, den Feind vom Himmel zu holen. Dezimiert sie, damit unsere Verteidigung die Festung halten kann.", progress = nil, completion = "Wir werden sie schlagen - egal ob zu Land oder in der Luft. Und wenn diese ruchlosen Bastarde über das Meer kommen, werden wir ihnen eine Tracht Prügel verpassen, die sie nicht vergessen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11890] = {title = "Was haben sie vor?", objective = "Untersucht die Gegend um die Pumpstation Kurbelzisch herum. Kehrt anschließend wieder zum Weisen Erde und Himmel in Taunka'le zurück.", description = "Die Gnome sind in den westlichen Teichen auf Schwierigkeiten gestoßen. Es geschieht ihnen recht, denn sie haben das Land mit ihren sogenannten Erfindungen verschmutzt.\n\nIch möchte, dass Ihr zu ihrer Pumpstation geht und nachseht, was mit ihnen geschehen ist. Kehrt anschließend wieder zu mir zurück.", progress = nil, completion = "In der Tat beunruhigende Neuigkeiten.\n\nMein Volk wird schon bald diesen Ort verlassen. Wir werden durch die Reihen der Geißel brechen, um zu unserer Hauptsiedlung Eisnebel in der Drachenöde zu gelangen.\n\nDoch bevor wir das tun, müssen wir uns um alles kümmern, was die Gnome in ihrem Wahn fabriziert haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11891] = {title = "Eine unschuldige Verkleidung", objective = "Benutzt die Krabbenkugel und spioniert das neue Lager des Schattenhammers aus. Es befindet sich westlich des Eingangs zur Tiefschwarzen Grotte auf dem Zoramstrand im Eschental. Benutzt anschließend das totemische Leuchtfeuer, um den Führer des Irdenen Rings zu beschwören.", description = "Dieser Information zufolge scheint es, als hätten die Kultisten ein weiteres Lager nordwestlich der großen Ansammlung auf dem Zoramstrand und als sprächen sie mit... Gästen?\n\nMan könnte Vieles in Erfahrung bringen, würde man das Geschehen verfolgen, <Volk>. Nehmt diese Kugel - sie wird Euch wie einer der Kriecher aussehen lassen, die am örtlichen Strand vorkommen. Belauscht das Gespräch mit diesen \"Gästen\" der Kultisten im nordwestlich gelegenen Lager und erstattet mir Bericht, sobald Ihr das getan habt.", progress = "Konntet Ihr ihren Geheimnissen auf die Spur kommen?", completion = "Sie wollen einen Frostfürsten beschwören? Nein! Sie dürfen das Gleichgewicht nicht stören!", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11892] = {title = "Die Ermordung von Harold Fährten", objective = "Erzdruide Lathorius beim Lager der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr Harold Fährten tötet.", description = "Ihr habt viel für die Tiere der Boreanischen Tundra getan, <Name>. Wir haben Nesingwarys Lakaien zurückgeschlagen und ihnen eine Lektion erteilt, die sie nicht so schnell vergessen werden.\n\nHarold Fährten, der für die Massenabschlachtung in Nagrand verantwortliche Agent, ist auch als Zuständiger für Nesingwarys Operationen in der Tundra ausgemacht worden. Er befindet sich westlich von hier beim Kum'uyasee.\n\n<Lathorius reicht Euch ein Horn mit komplizierten Schnitzereien.>\n\nFindet Fährten und tötet ihn. Lasst dieses Horn erschallen, solltet Ihr Hilfe benötigen.", progress = "Ist der boreanische Schlächter tot?", completion = "Ach, Nesingwary ist fort. Vielleicht war er von Anfang an gar nicht da...\n\n&lt;Lathorius seufzt.&gt;\n\nDer Dämon schlüpft einem gerne durch die Finger, doch seine Tage sind gezählt. Wir werden ihn finden und dann...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der ganzheitlichen BewahrungRing der indignierten WutAktivistensignet der Zauberwucht\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11893] = {title = "Die Macht der Elemente", objective = "Dorain Frosthuf in Taunka'le möchte, dass Ihr mithilfe des Totems der Windseele die Energie von 10 Dampfwütern sammelt.", description = "Ich hab immer wieder versucht, diesem dummen Goblin zu sagen, dass seine Maschinen nicht zuverlässig funktionieren.\n\nDoch die Macht der Elemente reicht weit und ist beständig. Wenn meine Lehrzeit vorüber ist, werde ich ihre ganze Macht beherrschen. Mein jetziges Wissen sollte jedoch ausreichen, um unserem Freund Fezzix helfen zu können.\n\nNehmt dieses Totem der Windseele und stellt es in der Nähe der Dampfwüter westlich des Dorfes auf. Das Totem wird die Energie der zerstörten Elementare aufsammeln. Kehrt anschließend mit dem voll aufgeladenen Totem zu mir zurück und ich werde den Rest erledigen.", progress = nil, completion = "&lt;Dorain nickt Euch zu.&gt;\n\nGut. Das wird genug sein, um Fezzix direkt vor Augen zu führen, was ich ihm schon so lange sagen möchte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11894] = {title = "Zusammenflicken", objective = "Fezzix Drehgang in Taunka'le möchte, dass Ihr ihm 5 dampfgegerbte Bälge bringt.", description = "Könnt Ihr Euch noch an all das gnomische Klebeband erinnern, das Ihr mir gebracht habt?\n\nNun, ich habe einen Zweck dafür gefunden. Der Rumpf dieser Flugmaschine ist an manchen Stellen so kaputt, dass ich ihn verstärken muss, wenn ich jemals wieder fliegen will.\n\nDorain dort drüben hat mir erzählt, dass die Taunka aus dampfgegerbten Karibubälgen wasserdichte Behälter herstellen. Marschenkaribus können überall in der Gegend um das Dorf herum und im Süden auf den Flutebenen gefunden werden. Besorgt mir die besten Bälge, die Ihr finden könnt, und gerbt sie über den Dampfschlöten auf den Geysirfeldern.", progress = "Habt Ihr die gegerbten Karibubälge dabei?", completion = "Fantastisch! Noch ein paar kleine Änderungen und ich bin wieder ein Goblin der Lüfte!", rewards = "Wizzelnobs SchulterbedeckungVerstärktes GummibandRingbesetzte HandgelenksschützerAuf Euch wartet eine dieser Belohnungen:\n\nDünne Geschicklichkeitsverstärkende Spule\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11895] = {title = "Bezwingt den Sturm", objective = "Besiegt die Sturmbö und kehrt anschließend zum Weisen Erde und Himmel in Taunka'le zurück.", description = "So, wie Ihr das beschreibt, sollte man leicht mit den Kreaturen aus Metall fertigwerden können. Doch zuerst müsst Ihr den Sturm bezwingen.\n\nHinter mir in der Hütte befindet sich ein Totem. Richtet Euren Willen darauf, sobald Ihr bereit seid, und der Sturm wird kommen. Ihr müsst den Sturm besiegen und auf diese Weise seine Essenz in Euch aufnehmen.\n\nFalls noch andere beim Kampf dabei sind und ihr zusammenarbeitet, solltet Ihr den Sturm besiegen können. Kehrt danach wieder zu mir zurück, <Klasse>.", progress = "Habt Ihr den Sturm schon bezwungen?", completion = "Ich kann spüren, wie Euch die Macht des Sturms durchströmt!\n\nIhr seid bereit, &lt;Name&gt;. Lasst uns beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11896] = {title = "Eine Schwäche für Blitze", objective = "Zerstört 15 verschiedene Robotereinheiten im größeren Teichareal um die Pumpstation Kurbelzisch herum, während sie von der Macht des Sturms geschwächt sind. Ignoriert jedoch die Mechagnome.\n\nKehrt anschließend zu Weiser Erde und Himmel in Taunka'le zurück.", description = "Ihr tragt nun die Macht des Sturms in Euch. Ich werde Euch die Mittel verleihen, um sie zu konzentrieren und auf die Roboter in den Teichen zu leiten.\n\nNehmt diese Blitzschlagrute und nutzt sie gegen die verschiedenen Roboter der Mechagnome, die im größeren Teichareal gen Westen zu finden sind. Gegen die Mechagnome selbst müsst Ihr sie nicht einsetzen: Großmutter Taiga hat Anderes mit ihnen vor.\n\nZerlegt sie in ihre Einzelteile, sobald die Roboter von der Macht des Sturms geschwächt sind!", progress = nil, completion = "Nun, da wir uns um ihre robotischen Diener gekümmert habe, ist es Zeit, dass wir uns größerer Beute widmen. Unglücklicherweise kann ich spüren, wie gerade in diesem Moment die Macht des Sturms in Euch schwindet.\n\nNichtsdestotrotz hat sie ihren Zweck erfüllt und ich denke, dass Ihr durchaus in der Lage seid, den nächsten Schritt ohne ihre Hilfe zu unternehmen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeakness to Lightning: On Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11897] = {title = "Stopft die Schlundlöcher", objective = "Unteroffizier Hammerberg möchte, dass Ihr mithilfe des Brandsatzes die Schlundlöcher süd- und nordwestlich der Valianzfeste zum Einsturz bringt.", description = "Die Geißel will einfach nicht locker lassen, <Name>. Es sind diese verfluchten Schlundlöcher: Soweit wir wissen, sind sie durch Tunnel verbunden, die bis zur Eiskrone reichen. Sie werden von gigantischen untoten Würmern gegraben.\n\nWenn ich irgendetwas in den Jahren unter Tage gelernt habe, dann ist es, dass Tunnel ohne Stützpfeiler durch eine Explosion ganz leicht zum Einsturz gebracht werden können.\n\nNehmt diese Sprengsätze und platziert sie an den Eingängen der Schlundlöcher, die sich auf der Erhöhung im Westen jenseits des Strandes befinden. Kommt hierher zurück, sobald Ihr sie zum Einsturz gebracht habt.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ohne Euch hätte die Valianzfeste den Angreifern womöglich nicht standhalten können. Dank Eurer Hilfe werden wir weiterkämpfen können.", rewards = "Transboreanische BedeckungBrustharnisch des MarschenläufersWestklammgamaschenGroßfelsschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11898] = {title = "Durchbruch", objective = "Besiegt Prinz Valanar und seine Leutnants Vanthryn den Erbarmungslosen und Luthion den Grässlichen. Meldet Euch anschließend bei Häuptling Orkan in Taunka'le.", description = "Auf der niedrigsten Ebene der Tempelstadt befindet sich ein grauer, in Licht getauchter Altar. Stellt Euch davor und sprecht die Worte auf den Schriftrollen laut aus, damit Euch der Eintritt in die grauenhafte Nekropole namens Naxxanar gewährt wird.\n\nSeid vorsichtig, <Name>. Prinz Valanar wird mit Sicherheit von seinem persönlichen Gefolge umgeben sein - ein jeder bereit, seinen Meister unter Einsatz seines Lebens zu schützen.\n\nIhr müsst einen Weg durch die Nekropole bis zum Sitz des Prinzen finden. Falls Ihr ihn nicht besiegen solltet, <Name>, befürchte ich, dass mein Volk niemals die Sicherheit Eisnebels erleben wird.", progress = "Habt Ihr Prinz Valanar besiegt?", completion = "Nachdem der Prinz besiegt worden ist, sind die Truppen der Geißel in der boreanischen Tundra verschwunden. Aber machen wir uns nichts vor: Sie werden nicht lange fernbleiben, weshalb ich Durm darauf vorbereiten muss, die Dorfbewohner nach Eisnebel zu führen.\n\n&lt;Der Häuptling schüttelt zögerlich seinen Kopf.&gt;\n\nIch hatte zwar schon viele Meinungsverschiedenheiten mit Durm, aber ich vertraue auf sein Urteil und seine Fähigkeiten. Ich kann Taunka'le nicht aufgeben, also werde ich es so lange verteidigen, bis ich erschlagen werde.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKette der aufmerksamen GedankenUmklammerung des unsterblichen WillensHalsreif der machtvollen Erlösung\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11899] = {title = "Seelen der vom Fluch befreiten", objective = "Fangt mithilfe von Großmutters Seelenfänger 10 Seelen der Mechagnome von Kurbelzisch. Kehrt anschließend zu Großmutter Taiga in Taunka'le zurück, sobald Ihr das erledigt habt.", description = "Die Mechagnome in den Teichen gen Westen sind uns ein großes Rätsel. Kurze Zeit, nachdem die Gnome von der Pumpstation und aus der Umgebung verschwanden, sind sie aufgetaucht.\n\nSie stellen eine Gefahr dar und man muss sich um sie kümmern.\n\nNehmt diesen Seelenfänger und wendet ihn auf die Überreste der Mechagnome an, um ihre Seelen einzufangen. Wenn Ihr zurückkommt, werden wir sie freilassen und so vielleicht herausfinden, was mit ihnen geschehen ist.", progress = nil, completion = "Nun müssen wir die gefangenen Seelen befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11900] = {title = "Die Zähler ablesen", objective = "Erzmagier Berinand im Transitusschild möchte, dass Ihr mit den Messwerten seiner Instrumente in Kaltarra zu ihm zurückkehrt.", description = "Ich hatte gehofft, dass die Auswirkungen des Nexus nur auf diese Region beschränkt wären. Vor Kurzem haben wir jedoch Meldungen aus allen Teilen Azeroths erhalten, die darauf hinweisen, dass die geologische Instabilität rapide ansteigt!\n\nDer Nexus muss regelmäßig überwacht werden, während ich nach einer Lösung des Problems suche.\n\nIch habe in ganz Kaltarra empfindliche Instrumente aufgestellt, die als Malygos' Seherkugeln getarnt sind. Eines befindet sich im Graben in der Nähe des Nexus und die anderen drei sind in den Gebäuden entlang der Talgrenze versteckt. Sucht sie alle auf und kehrt mit den Messwerten zu mir zurück.", progress = nil, completion = "Die Sache ist schlimmer, als erwartet.\n\nMalygos leitet zu viel Energie in diesen Ort. Wenn niemand ihn aufhält, wird aus Azeroth eine weitere Scherbenwelt...\n\nZum Glück glaube ich, eine provisorische Lösung gefunden zu haben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11901] = {title = "Truppen? Welche Truppen?", objective = "Gerald Grün in Fernhain möchte, dass Ihr euch in die Mine im Norden begebt und herausfindet, was mit der Einsatztruppe, die dorthin geschickt wurde, geschehen ist.", description = "Die Geißel ist überall, <Klasse>. Wir haben mithilfe der Bauern und Kumpels eine Miliz zusammengestellt, doch das wird einfach nicht genügen.\n\nDie eine Einsatztruppe, die uns von der Valianzfeste geschickt wurde, verteidigt die Mine. Wir haben schon seit Tagen nichts von ihnen gehört!\n\nWenn Ihr uns wirklich helfen wollt, wieso geht Ihr dann nicht zur Mine und seht nach? Vielleicht können wir sie dazu bringen, uns Verstärkung zu schicken.", progress = nil, completion = "Euer Magen fühlt sich mulmig an, als Ihr Euch dem Korn nähert. Der Gestank ist fast unerträglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11902] = {title = "Schädliche Beweise", objective = "Kehrt zu Gerald Grün in Fernhain zurück.", description = "Die Kornsäcke verströmen den faulen Gestank, den Ihr mittlerweile mit der Seuche verbindet. Das wird wahrscheinlich erklären, was mit den Verteidigern der Mine, den Fußsoldaten, geschehen ist.\n\nAm besten gebt Ihr Gerald Grün Bescheid.", progress = nil, completion = "Die armen Jungs... sie hatten nie eine Chance!\n\nDas klingt jedenfalls, als hätten wir einen Maulwurf in unseren Reihen. Wahrscheinlich ein Agent des Kults der Verdammten. Verflucht sollen diese Wahnsinnigen sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11903] = {title = "Zeit zu handeln", objective = "Gerald Grün in Fernhain möchte, dass Ihr 14 verseuchte Aasfresser tötet.", description = "Nun, <Name>. Da den letzten Rest unserer Truppen in Fernhain nun der Tod oder Schlimmeres geholt hat, bleibt uns nur eins übrig: selbst gegen diese Geißel zu kämpfen.\n\nWir haben in dem, was von Fernhain übrig ist, Milizen stationiert. Ohne Eure Hilfe, ist ihre Chance, zu gewinnen, gering. Geht und steht ihnen bei. Meine Jungs und ich werden diesen Pfad bewachen. Wir können nicht zulassen, dass die Geißel durchbricht!", progress = nil, completion = "Ihr habt Euch mit der Geißel in der einzigen Sprache verständigt, die sie kennt: Gewalt und Tod. Unglücklicherweise kommen immer mehr!", rewards = "Transboreanische ArmschienenWeste der FlutebenenTreter des BettelmönchsAuf Euch wartet eine dieser Belohnungen:\n\nHalsschmuck des Streitlustigen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11904] = {title = "Die Früchte unserer Arbeit", objective = "Geht zur Mine in Fernhain, nehmt Hauptmann Jacobs den Wegrollsperrenschlüssel ab und macht den Wagen mit Erz los. Kehrt zu Gerald Grün in Fernhain zurück, sobald Ihr Eure Aufgabe beendet habt.", description = "Es kommen immer mehr Diener der Geißel... doch aufgeben dürfen wir nicht! Hört zu, <Name>. Im Inneren dieser Mine gibt es einen Wagen beladen mit dem letzten Rest Erz, den die Allianz auf dieser Seite des Kontinents für lange Zeit sehen wird.\n\nDas Problem ist nur, dass die Wegrollsperre des Wagens verschlossen ist. Als das Militär dort hineingegangen ist, hat Hauptmann Jacobs alles an wichtiger Ausrüstung, inklusive des Wegrollsperrenschlüssels, beschlagnahmt.\n\nDie Seuche, von der die Soldaten in der Mine infiziert wurden, muss auch Jacobs infiziert haben. Nehmt ihm den Schlüssel ab und bergt das Erz.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Dieses Erz wird in der kommenden Zeit von entscheidender Wichtigkeit für die Allianz sein. Ich gehe mal davon aus, dass unser heutiges Handeln den Lauf der Dinge beeinflussen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11905] = {title = "Das Unvermeidliche hinauszögern", objective = "Das Abbild der Kriegsmagierin Kaitlyn im Nexus möchte, dass Ihr den interdimensionalen Refabrikator in der Nähe des Risses benutzt.", description = "Azeroths Leylinien werden zum Nexus umgeleitet.\n\nDer Zustrom arkaner Energien verursacht einen Riss zwischen den Dimensionen.\n\nIch kann es zwar nicht aufhalten, habe jedoch einen Weg gefunden, es zu verlangsamen.\n\nNehmt diesen Gegenstand und aktiviert ihn in der Nähe des sich bildenden Risses.", progress = "Wart Ihr schon beim Riss?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Erdbeben lassen schon nach.\n\nMit etwas Glück haben wir uns genug Zeit verschafft, um einen Weg zu finden, wie wir Malygos' Pläne durchkreuzen können.", rewards = "Zeitlinienversetzte StulpenZeitstoppende HandschuheBindungen der SabotageStulpen des verwirrten RiesenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11906] = {title = "Die Teiche säubern", objective = "Sammelt 15 Ersatzteile von Kurbelzisch und bringt sie zu Eisenauge in Taunka'le.", description = "<Eisenauge läuft eine Träne über die Wange.>\n\nIch habe gehört, dass Ihr wieder zu den Teichen im Westen zurückgeht. Ich habe etwas für Euch zu tun, wenn Ihr schon einmal dort draußen seid, <Volk>.\n\nDie Gnome, die sich einen feuchten Dreck um das Land scheren, haben es mit ihren Maschinen verschmutzt. Ich möchte, dass Ihr alle Ersatzteile, über die Ihr stolpert, aufsammelt.\n\nBringt sie mir und ich werde mich darum kümmern, dass sie anständig entsorgt werden, bevor wir diesen Ort für immer verlassen.", progress = "Wenn wir uns nicht um das Land kümmern, wird es hier bald keinen Raum für Leben mehr geben.", completion = "Es ist der Weg der Taunka, das Land in einem makellosen Zustand zu verlassen, bevor wir weiterziehen.\n\nWir werden uns schon bald auf den Weg zu unserer Hauptsiedlung Eisnebel machen. Ihr habt uns dabei geholfen, viel schneller abzureisen.\n\nIch danke Euch.", rewards = "Mantel des starren ZornsVerstärkte Gamaschen aus KaribubälgenStachelhelm von MagmutBernsteinplattenhandschutzIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11907] = {title = "Die Offiziere", objective = "Besiegt Twonkie, ED-210, Max Kawummso und Molok den Zermalmer und meldet Euch anschließend beim Weisen Erde und Himmel in Taunka'le.", description = "Es ist bekannt, dass Ritzelmeister Mechazod vier Offiziere hat, welche die Roboter in den Teichen kontrollieren.\n\nWir müssen ihnen ein Ende machen!\n\nUnsere Fernläufer und Schneefährtenleser behaupten, dass, falls man die Ventile an der West-, Nord-, Zentral- und Südstation zudrehen sollte, seine Offiziere auf schnellstem Wege herbeieilen würden, um zu verhindern, dass man ihnen einen Strich durch die Rechnung macht.\n\nDie genannten Stationen befinden sich bei den rotierenden Lichtern in den Teichen um die Pumpstation herum.\n\nBeeilt Euch, <Name>!", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;.\n\nDadurch, dass diese seltsamen Kreaturen zerstört wurden, sollte es ein Leichtes sein, mit dem Rest der Teiche fertig zu werden.\n\nWir schulden Euch Dank.", rewards = "FrostbeißerGezackte EisfaustZehrender GroßstabUmhang des frierenden HeilersAuf Euch wartet eine dieser Belohnungen:\n\nHalsschmuck der Frostsprecher\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11908] = {title = "Referenzmaterial", objective = "Jeremias Hohning möchte, dass Ihr das Buch \"Felder, Fabriken und Werkstätten\" aus dem brennenden Gebäude neben der Mine in Fernhain holt.", description = "Ich war für die Erntegolems verantwortlich - eine wichtige Aufgabe, bis die Geißel den größten Teil des Ackerlands zerstörte. Ich habe jedoch eine Idee, wie wir die Erntegolems nützlich wieder einsetzen können.\n\nIch kann die Erntesammler so verkabeln, dass sie uns im Kampf gegen die Geißel helfen.\n\nJetzt bin ich auch nicht gerade ein Experte, was das angeht, deshalb brauche ich mein Handbuch. Das Problem ist aber, dass ich es in der Werkstatt vergessen habe... welche ungünstigerweise das brennende Gebäude dort neben der Mine ist. Meint Ihr, Ihr könntet es für mich holen?", progress = "Habt Ihr mir mein Buch besorgt?", completion = "Ausgezeichnet! Darin sollte stehen, was ich wissen muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11909] = {title = "Besiegt den Ritzelmeister", objective = "Untersucht das Handbuch des Ritzelmeisters und bringt Mechazods Kopf zu Großmutter Taiga in Taunka'le.", description = "Dieser Ritzelmeister Mechazod ist ganz offensichtlich nicht ganz bei Trost. Wenn seine sogenannte Heilung und Unsterblichkeit bedeuten, dass alle von uns zu Robotersklaven werden, dann muss man ihn aufhalten!\n\nDie Winde, die mir den Weg weisen, flüstern mir zu, dass er sich auf dem Dach der Pumpstation in der Mitte des Teiches gen Westen befindet.\n\nHöchstwahrscheinlich befindet er sich in dem Führerhäuschen ganz oben auf dem Gebäude. Geht dort hoch und untersucht sein Zeug.\n\n<Name>, Ihr müsst Mechazod entgegentreten, wenn wir überleben sollen!", progress = "Ist es vorbei? Geht von Ritzelmeister Mechazod keine Bedrohung mehr aus?", completion = "&lt;Die Großmutter gibt einen tiefen erleichterten Seufzer von sich.&gt;\n\nEs ist vollbracht... Ihr habt uns gerettet! Hättet Ihr ihn hier nicht aufgehalten, wer weiß, wie weit sich dieser Fehler der Gnome verbreitet hätte?\n\nAngesichts der Bedrohung durch die blauen Großdrachen und den Nexuskrieg, geschweige denn den Lichkönig, ist das Letzte, was wir brauchen, eine frei herumlaufende, verrückte Schöpfung der Titanen!\n\nIch danke Euch, &lt;Name&gt;!", rewards = "Gespannter TreibholzbogenErdgeborene SchienbeinschützerWindkindstabStab des GeistrufersFeuergetaufter KriegshammerIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11910] = {title = "Geheimnisse der Urtume", objective = "Erzmagier Berinand im Transitusschild möchte, dass Ihr 3 eiszeitliche Späne und 3 magiegebundene Späne von den Urtumen in Kaltarra besorgt.", description = "Offensichtlich hat die Instabilität in dieser Region Auswirkungen auf die einheimischen Kreaturen gehabt.\n\nMich interessieren die Urtume und ihre jüngsten Adaptationen. Ich vermute, dass ihr Wandel zu diesen 'magiegebundenen' Urtumen vielleicht Hinweise über unsere verzwickte Lage hier liefern wird.\n\nFür meine Forschungen brauche ich Proben beider Urtume. Beeilt Euch...", progress = "Habt Ihr die Proben, die ich angefordert habe, gesammelt?", completion = "Ja, ja. Die sollten auf jeden Fall genügen.\n\nIch danke Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11911] = {title = "Beschleunigen", objective = "Das Abbild der Kriegsmagierin Kaitlyn im Nexus möchte, dass Ihr 5 arkane Splitter von kristallinen Beschützern beschafft.", description = "Ich habe in der kurzen Zeit, die mir hier gegeben wurde, mehr gelernt, als in Jahrzehnten des Studiums.\n\nDiese Urtume sind einer ungeheuerlich hohen Dosis arkaner Energie ausgesetzt. Es verwandelt sie buchstäblich in etwas... anderes.\n\nIch bin zuversichtlich, dass ihre Metamorphose noch eine weitere Stufe beinhaltet. Beschafft mir Hinweise auf ihren endgültigen Zustand.", progress = "Die kristallinen Urtume... Existieren sie wirklich?", completion = "Faszinierend!\n\nUnd sie sind auch noch aggressiv, meint Ihr. Das würde darauf hinweisen, dass irgendeine Intelligenz hinter dieser Manipulation steckt.\n\nGut möglich, dass es sich hier um kein natürliches Phänomen handelt...", rewards = "Sandalen der mystischen EvolutionTreter der zerrissenen ZukunftStacheltreter der MutationBelebende SabatonsStiefel des unbeugsamen BeschützersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11912] = {title = "Verrückt nach Beeren", objective = "Bibliothekarin Serrah im Transitusschild möchte, dass Ihr 10 Frostbeeren von den Frostbeerbüschen in Kaltarra besorgt.", description = "Oh! Welch Erleichterung, einmal ein neues Gesicht zu erblicken! Ich hatte schon das Gefühl, man hätte uns aufgegeben.\n\nWir wurden vor Tagen von unseren Versorgungswegen abgeschnitten und die Situation sieht nicht gerade, nun ja, rosig aus. Um ehrlich zu sein, war das von Anbeginn ein Selbstmordauftrag, wenn Ihr mich fragt.\n\nVielleicht bin ich für all diese Brutalität nicht aus dem richtigen Holz geschnitzt - geschweige denn für diese bittere Kälte! Ich wäre viel lieber wieder zurück in Dalaran und dabei, uralte Texte zu untersuchen.\n\nDoch kommen wir zur Sache: Unsere Essensvorräte gehen zur Neige. Bitte, sammelt, was Ihr nur könnt, und bringt es mir.", progress = "Habt Ihr schon etwas zu essen gefunden?", completion = "Tja, es ist nicht viel, aber es sollte uns für einen weiteren Tag am Leben halten.\n\nIch meine, dass dies ein angebrachter Preis für Eure Mühen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11913] = {title = "Kein Risiko eingehen", objective = "Wendy Darren möchte, dass Ihr mithilfe von Wendys Fackel 8 Säcke Korn aus Fernhain verbrennt.", description = "Ich habe mitgehört, was Ihr Gerald gesagt habt, und mir gefällt es gar nicht. Wenn Kultisten es schaffen konnten, das Korn in den Minen mit ihrer grauenhaften Seuche zu vergiften, hätten sie es genauso gut mit dem Korn draußen machen können.\n\nWir haben keine Zeit, die Spreu vom Weizen zu trennen. Wir müssen geschwind handeln und alles verbrennen.\n\nNehmt diese Fackel und steckt alle Kornsäcke, die Ihr dort draußen finden könnt, in Brand. Es wäre eine Tragödie, wenn wir diesen Angriff nur überlebt hätten, um anschließend vor der Seuche kapitulieren müssten.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Ich würde es nicht gerne sehen, wenn die Überlebenden des Angriffs auf Fernhain über verseuchtes Korn stolpern würden.", rewards = "Transboreanischer MantelBedeckung der FlutebenenBrustschutz der gesalbten WundenAuf Euch wartet eine dieser Belohnungen:\n\nSiegelring des Spähers\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11914] = {title = "Das Geheimnis hüten", objective = "Bibliothekarin Serrah im Transitusschild möchte, dass Ihr arkane Schlangen in der Nähe des Nexus tötet und 5 Nexusmanaessenzen sammelt.", description = "Unsere Existenz hier draußen hängt gänzlich davon ab, ob man uns entdeckt. Sollte der Schild nicht funktionieren, auch nur für einen Moment, gehen Malygos' Diener uns an den Kragen.\n\nEine meiner Aufgaben ist, das Mana der Kriegsmagier auf einem gewissen Niveau zu halten, damit ihre Konzentration nicht nachlässt. Da wir von der Versorgung abgeschnitten sind, sehe ich mich gezwungen zu improvisieren.\n\nIch könnte Eure Hilfe gebrauchen, <Name>.\n\nSehr nahe am Nexus tun sich die arkanen Schlangen an den reichen Manavorkommen gütlich. Wenn sie erst einmal besiegt sind, werden sie eine Manaessenz erzeugen, die ich gebrauchen kann.", progress = "Habt Ihr die Manaessenzen dabei, um die ich Euch gebeten habe?", completion = "Euer Dienst für Dalaran wird nicht unbemerkt bleiben, &lt;Volk&gt;.\n\nIch hoffe, dass Ihr mit dieser Entlohnung zufrieden seid.", rewards = "Versengtes SchuppencapeKettenstrang der AusbrennungStulpen des scharlachroten WächtersAuf Euch wartet eine dieser Belohnungen:\n\nSerrahs Stern\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11915] = {title = "Spiel mit dem Feuer", objective = "Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte.", description = "Möchtet Ihr ein paar heiße neue Fertigkeiten erlernen?\n\nOb Ihr jemals meine beeindruckende Fertigkeit erreichen werdet, sei zwar dahingestellt, aber ein oder zwei Kunststückchen werdet Ihr wahrscheinlich aufschnappen können, wenn Ihr <ein aufmerksamer Schüler/eine aufmerksame Schülerin> seid. Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.", progress = nil, completion = "Grüße. Seid Ihr hier, um zu lernen, was man mit Feuer alles machen kann?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11916] = {title = "Höllschreis Champion", objective = "Geht nach Taunka'le und sucht Häuptling Orkan auf.", description = "Ihr habt Euch allen Herausforderungen, mit denen Ihr konfrontiert wurdet, gestellt und sie mit links gemeistert. Es ist Euch zu verdanken, <Name>, dass die Horde nun in Nordend Fuß gefasst hat.\n\nDoch unsere Arbeit hat gerade erst begonnen. Wir müssen zur Eiskrone marschieren und ihre Mauern niederreißen!\n\nEuer nächster Auftrag beginnt im Osten, in Taunka'le. Unsere Verbündeten, die Taunka, sind in äußersten Schwierigkeiten und benötigen unsere Hilfe. Lasst Euch von Durgot Wolfsbruder, unserem Stallmeister, eine Reisemöglichkeit organisieren und sucht nach Häuptling Orkan in Taunka'le.", progress = nil, completion = "Ich befürchte, Ihr könntet zu spät sein, Champion. Viele meiner Brüder und Schwestern haben Taunka'le schon den Rücken gekehrt und suchen Unterschlupf in der Drachenöde weit im Osten.\n\nEs gibt hier jedoch noch viel zu erledigen und nur Wenige, die uns mit ihrer Kraft zur Hand gehen würden...", rewards = "Axt des gefrorenen TodesBoreanischer ZerkracherTurm des unendlichen GeistesStab des entschlossenen BettelmönchsFuror des wütenden DrachenKlaue der einsamen SeeleIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11917] = {title = "Zurückschlagen", objective = "Beschwört mithilfe des Eisbrockens auf dem Zoramstrand im Eschental den Leutnant der Frostwelle, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nKehrt zum Lager am Zoramstrand zurück – dorthin, wo die großen Eisbrocken liegen. Sie nehmen mit ihrer Hilfe Verbindung mit den Elementaren auf – genau so, wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11918] = {title = "Grundausbildung", objective = "Raelorasz im Transitusschild möchte, dass Ihr 10 Spruchwirker von Kaltarra tötet.", description = "Das ist Krieg, <Sterblicher/Sterbliche>, und wir bilden die Speerspitze.\n\nEure kleinen Streitereien über Land oder Währung sind Nichtigkeiten, wenn man sie mit diesem Konflikt vergleicht. Wir stehen dem Aspekt Malygos und seinem gesamten blauen Drachenschwarm gegenüber. Alles, was Ihr wissen müsst, ist, dass es diese Welt nicht mehr geben wird, falls er siegen sollte.\n\nWir sind hier nur wenige und kämpfen gegen viele an. Dass wir sterben werden ist so gut wie sicher und unser endgültiger Erfolg liegt lediglich darin, unseren Feind zu verlangsamen.\n\nGeht jetzt. Beeilt Euch, während ich mich entscheide, was ich mit Euch machen soll.", progress = nil, completion = "Gut, &lt;Klasse&gt;, da Ihr Euch jetzt mit dem Feind vertraut gemacht habt, ist es Zeit, an die Arbeit zu gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11919] = {title = "Drachenjagd", objective = "Raelorasz möchte, dass Ihr mithilfe von Raelorasz' Speer ein Nexusdrachenjunges bändigt und es anschließend zu ihm zurückbringt. Er befindet sich im Transitusschild.", description = "Die Blauen haben damit angefangen, ihre Drachen mit mysteriösen Runen zu bedecken. Ich muss herausfinden, was sie zu bedeuten haben.\n\n<Raelorasz ritzt sich mit einem Speer in die Hand und benetzt die Spitze mit seinem Blut.>\n\nNehmt dies hier und wendet es auf einen von ihnen an. Wartet, bis es gebändigt ist, und bringt es zu mir zurück, bevor die Wirkung nachlässt.\n\nIhre Jungen gehen in der nordwestlichen Ecke des Tals auf Nahrungssuche.", progress = "Konntet Ihr einen der Nexusdrachen einfangen?", completion = "Das Schicksal dieser jungen Drachen muss Euer Gewissen nicht belasten, &lt;Volk&gt;. Malygos alleine trägt die Verantwortung hierfür.\n\nIch arbeite unablässig an der Lösung des Rätsels um diese Runen. Wir werden nicht mehr Leben nehmen, als unbedingt notwendig.", rewards = "Robe der GluthitzeVerkohlter DrachengürtelFlammenerfüllte BindungenHelm des scharlachroten DrakonidenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11920] = {title = "Kultisten unter uns", objective = "Sprecht mit Kapitän \"Linksdatsch\" Gaffelsegel an Deck der Sturmbrecher in der Valianzfeste.", description = "Auf diesem Altar befinden sich alle Markierungen des Kults der Verdammten. Es scheint, als hätten Fanatiker vom Festland es bis nach Nordend geschafft. Es wäre vielleicht klug, den Kapitän des Schiffs darüber in Kenntnis zu setzen.\n\nVielleicht befindet er sich über Deck.", progress = nil, completion = "Kultisten? Unter Deck? Ich werde wohl meine gesamte Crew auspeitschen lassen müssen!\n\nHört zu... wieso lassen wir nicht Admiral Kantelbree die Angelegenheit in die Hand nehmen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11921] = {title = "Noch einmal Fackeln werfen", objective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", description = "Seid gegrüßt, Feuerjongleur! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für einen Experten in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", progress = "Schnell! Es gibt keine Zeit zu verlieren!", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11922] = {title = "Fackelwurf", objective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister des Sonnenwendfests.", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ... den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11923] = {title = "Fackeln fangen", objective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Freudenfeuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier nacheinander und kommt wieder zu mir zurück.\n\nSeid vorsichtig! Die Fackeln sind gefährlich, wenn sie auf dem Boden aufkommen! Und fangt sie alle auf! Wenn eine davon auf den Boden fällt, müsst Ihr zurück zum Freudenfeuer und von vorn anfangen. Viel Glück.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", rewards = "Ihr bekommt:\n\nJonglierfackelBrandblüte"}
MultiLanguageQuestData['de'][11924] = {title = "Noch einmal Fackeln fangen", objective = "Fangt nacheinander 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", description = "Fackeln zu fangen, hält einen auf Zack, daran besteht kein Zweifel. Denkt Ihr, dass Ihr es lange durchhalten werdet?\n\nNa dann lasst uns mal sehen...", progress = nil, completion = "Wie geht es Eurem Arm, &lt;Name&gt;? Das war eine glanzvolle Vorstellung dort draußen - wie ein echter Meisterjongleur!", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11925] = {title = "Noch einmal Fackeln fangen", objective = "Fangt nacheinander 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", description = "Fackeln zu fangen, hält einen auf Zack, daran besteht kein Zweifel. Denkt Ihr, dass Ihr es lange durchhalten werdet?\n\nNa dann lasst uns mal sehen...", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Wie geht es Eurem Arm, &lt;Name&gt;? Das war eine glanzvolle Vorstellung dort draußen - wie ein echter Meisterjongleur!", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11926] = {title = "Noch einmal Fackeln werfen", objective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", description = "Seid gegrüßt, Feuerjongleur! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für einen Experten in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", progress = nil, completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11927] = {title = "Man munkelt", objective = "Geht zum Gasthaus in der Valianzfeste und sucht Leryssa auf.", description = "He, <Name>. In der Gaststätte ist ein Mädchen, das nach Euch gefragt hat. Sie heißt Leryssa.\n\nIch denke nicht, dass sie Euch kennt, aber sie sagt, dass sie Eure Hilfe benötigt. Sie klang wirklich verzweifelt.", progress = nil, completion = "Vielen Dank, dass Ihr gekommen seid, um mich zu sehen. Ich wusste nicht, an wen ich mich sonst hätte wenden können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11928] = {title = "Fernhain", objective = "Reist nach Fernhain in der Boreanischen Tundra und sprecht mit Gerald Grün.", description = "Meine Jungs sollten die Sache von jetzt an in die Hand nehmen können, <Name>. Die Valianzfeste kann weit mehr trotzen als diesen Angriffen. Ich mache mir jedoch um unser Ackerland und die Mine in Fernhain Sorgen.\n\nWir haben kurz vor dem Überfall eine komplette Einsatzgruppe ausgesandt, um unsere Schürfoperationen in der Mine zu beschützen - sie sollten in der Lage sein, unsere Zivilisten zu verteidigen.\n\nGerald Grün ist für die dortigen Dorfbewohner verantwortlich. An der Nordwand der Valianzfeste gibt es eine Passage, die Euch direkt zu ihm führen wird. Seht nach, wie Ihr ihm helfen könnt.", progress = nil, completion = "Ihr seid hier, um zu helfen? Dann kommt Ihr gerade rechtzeitig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11929] = {title = "Taunka'les Untergang", objective = "Sprecht mit Mutter Tauranook außerhalb von Taunka'le.", description = "Wir sind verloren, <Name>. Dieser Ort ist schon seit vielen Generationen unsere Heimat gewesen, doch er ist nicht länger sicher. Hier begegnet einem nur noch der Tod... Tod und die Erinnerung daran, wie es einst gewesen ist.\n\nIch habe die Evakuierung von Taunka'le beordert. Alle verbliebenen Taunka müssen den Ort sofort verlassen und sich auf den Weg zu unserer Hauptsiedlung Eisnebel in der Drachenöde machen.\n\n<Orkan deutet in Richtung Osten.>\n\nIhr müsst dabei helfen, mein Volk in Sicherheit zu bringen, <Name>. Mutter Tauranook erwartet Euch am Eingang des Dorfes. Beeilt Euch! Die Geißel ist überall und kommt immer näher!", progress = nil, completion = "&lt;Mutter Tauranook wischt sich die Tränen von den Wangen.&gt;\n\nEs gab einmal eine Zeit, als ich über diese Tundra wandeln konnte und ich, so weit das Auge reichte, Schnee erblicken konnte.\n\nDoch der Schnee hat uns verlassen und uns damit signalisiert, dass unsere Zeit hier zu Ende ist. Wir verbinden viele glückliche Erinnerungen mit Taunka'le und der boreanischen Tundra...\n\n&lt;Mutter Tauranook wimmert.&gt;\n\nVielleicht wird die Zukunft unsere Wiederkehr bringen - gemeinsam mit dem Schnee.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11930] = {title = "Quer durch Transborea", objective = "Eskortiert die Evakuierten aus Taunka'le durch die Transborea bis zu Wartuk Eiskind in der Drachenöde.", description = "Der Pfad durch Transborea im Osten ist der einzige Weg, um die Drachenöde zu erreichen. Viele Gefahren erwarten Euch auf der Reise durch die Tundra. Nehmt Euch vor der Geißel und ihrem Einfluss auf die Landkreaturen in Acht. Es gehen Gerüchte um, dass unsere eigenen Brüder und Schwestern von den Toten auferstehen und die Karawanen angreifen, die sich auf den Weg in die Drachenöde befinden! Verteidigt Eure Karawane und bringt die Evakuierten in Sicherheit!\n\nWartuk Eiskind erwartet Euch auf der anderen Seite der Brücke, welche in die Drachenöde führt.", progress = nil, completion = "&lt;Wartuk sieht Euch mit einem grimmigen Gesichtsausdruck an.&gt;\n\nEisnebel gibt es nicht mehr...", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11931] = {title = "Den Code entziffern", objective = "Raelorasz im Transitusschild möchte, dass Ihr den azurblauen Kodex von Inquisitor Caleras besorgt und 3 schimmernde Runen seiner Zauberbindern von Kaltarra besorgt.", description = "Ich spüre, dass die Drachen in dieser Gegend über eine bestimmte Eigenart verfügen, doch was die Runen, mit denen ihr gesamter Körper bedeckt ist, zu bedeuten haben, entzieht sich mir noch immer.\n\nOhne einen Kodex wird es mich mehr Zeit kosten, sie zu deuten, als wir uns leisten können.\n\nNicht weit von hier entfernt befindet sich ein Verräter der Kirin Tor namens Caleras, der höchstwahrscheinlich über eine Kopie des Wälzers, den ich benötige, verfügt. Seine Handlanger besitzen die Runen, die ich für meine Übersetzung benötige.\n\nBeeilt Euch, <Sterblicher/Sterbliche>. Jede Minute, die verstreicht, gewinnt Malygos an Kraft.", progress = "Beeilt Euch, Sterblicher.\n\nJede Minute, die verstreicht, gewinnt Malygos an Kraft.", completion = "Gut gemacht, &lt;Volk&gt;.\n\nHoffen wir mal, dass wir etwas finden, dass wir gegen Malygos verwenden können.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11932] = {title = "Feiglinge und Dummköpfe", objective = "Sprecht mit Ataika in Kaskala nordöstlich der Valianzfeste.", description = "Hört mir zu, <Name>. Nichts für ungut, aber die Mission, auf die sie Thassarian angesetzt haben, war ein reiner Selbstmord.\n\nEine Handvoll unserer Männer wurden losgeschickt, um einen Angriff auf die größte Ansammlung der Geißel in dieser Gegend zu starten. Nennt mich verrückt, aber ein Ziggurat der Geißel, die sich außerhalb einer verseuchten nerubischen Stadt befindet, mit nur zwölf Mann zu stürmen, ist nicht meine Art von Spaß.\n\nSolltet Ihr noch immer daran interessiert sein, Thassarian zu finden, dann hört dies: Wir sollten uns mit einem Tuskarr namens Ataika in Kaskala gen Nordosten treffen, um eine Überfahrt nach Osten zu arrangieren. Viel Glück auf Eurem vergeblichen Unterfangen.", progress = nil, completion = "Ich kann mich an den Mann, von dem Ihr sprecht, erinnern. Er trug die Markierungen Karkuts.\n\nMöge Karkut unsere Gefallenen beschützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11933] = {title = "Raubt die Flamme der Exodar", objective = "Bringt die Flamme der Exodar zum Geschichtenerzähler.", description = "Die Flamme, die aus dem Innersten der Exodar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Dies scheint mir ein neues Feuer zu sein... Doch Ihr sagt, dass es von der Exodar stammt? Faszinierend! Dass Ihr es ins Innere des Schiffs schaffen konntet... Natürlich werde ich Euch dafür bezahlen. Solltet Ihr etwas Ähnliches finden, dann sucht mich bitte wieder auf.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11934] = {title = "Euer Potenzial freisetzen", objective = "Bringt diesem Typen ein bisschen Zeugs.", description = "Heute schaltet Ihr eine Seite in Eurem Zauberbuch frei, eine, von der Ihr gar nicht wusstet, dass sie überhaupt existiert. Bringt mir was und ich werde das Ding für Euch aufmachen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11935] = {title = "Raubt die Flamme von Silbermond", objective = "Bringt die Flamme von Silbermond zum Meister der Lehren.", description = "Diese Flamme, die aus Silbermond entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Welch prächtiges Feuer! Ihr habt das hier in Silbermond gefunden, sagt Ihr? Unglaublich! Wer weiß, was wir mit den Flammen aller vier Städte vollbringen könnten?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes SmorcFeuriges FestgebräuHandvoll Sommerblüten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHat alle Fackelquests abgeschlossen\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11936] = {title = "Einen Plan ausbrüten", objective = "Raelorasz im Transitusschild möchte, dass Ihr Wyrmkin von Kaltarra erschlagt und mit ihren gefrorenen Äxten 5 Eier von blauen Drachen zertrümmert.", description = "Unser Vorhaben hier ist simpel: Wir sollen uns weiterhin vor Malygos verstecken, seine Brut beobachten und seine Pläne mit allen Mitteln vereiteln. Zu diesem Zweck habe ich eine Aufgabe für Euch.\n\nDie Blauen legen ihre Eier am Fuße des Nexus. Da sie so viel arkaner Energie ausgesetzt sind, werden sie sicherlich eher schlüpfen - und es ist nicht abzusehen, welchen Effekt es auf ihre Brut haben wird.\n\nIch habe nicht vor, das herauszufinden. Erschlagt die örtlichen Wyrmkin und benutzt ihre gefrorenen Äxte, um anschließend die Eier aufzuschlagen.", progress = nil, completion = "Es tut mir leid, die Vernichtung von Dracheneiern anzuordnen, ob Feind oder nicht.\n\nMöge der Zweck dieses Krieges die Mittel heiligen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11938] = {title = "Zeit schinden", objective = "Thassarian in der Klagenden Ziggurat in der Boreanischen Tundra möchte, dass Ihr 20 Anhänger der Geißel in der Tempelstadt En'kilah erschlagt. Benutzt Lurids Knochen, falls Ihr Unterstützung benötigt.", description = "Da wir nun über dieses Phylakterium verfügen, sollte ich keine Probleme haben, mir die benötigten Informationen zu beschaffen. Es wird jedoch nicht lange dauern, bis die Geißel in der Tempelstadt bemerkt, dass etwas faul ist.\n\nIch wäre nicht in der Lage, hier einen ausgewachsenen Angriff abzuwehren. Oder vielleicht doch? ... Ich will es lieber nicht herausfinden.\n\nIch möchte, dass Ihr dort hinuntergeht und ihnen ein paar Verluste zufügt. Hoffentlich werden sie lange genug abgelenkt sein, damit uns die beiden hier ihr Herz ausschütten können... bildlich gesprochen natürlich. Nehmt Lurid mit Euch - er wird vielleicht von Hilfe sein.", progress = "Ist es vollbracht?", completion = "Das sollte uns etwas Zeit verschaffen. Isidorus ist zwar kooperativ gewesen, doch ich hatte die traute Zweisamkeit mit dem Lich wirklich nötig.", rewards = "Gürtel des DämmeraugesSchattenwickelhandschuheStiefel des TundraschreitersAuf Euch wartet eine dieser Belohnungen:\n\nPein des Todesritters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11939] = {title = "?????", objective = "[PH]Quest to close this questline - summon and kill a mature drake (Elite?) - Fight a drake in the dungeon?", description = "[PH]Quest to close this questline - summon and kill a mature drake (Elite?) - Fight a drake in the dungeon?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][11940] = {title = "Drachenjagd", objective = "Raelorasz möchte, dass Ihr mithilfe des mit Blut benetzten Speers ein Nexusdrachenjunges bändigt und es anschließend zu ihm zurückbringt. Er befindet sich im Transitusschild.", description = "Ich brauche noch mehr Drachenjunge, um meine Untersuchung der Runen auf ihren Körpern fortzuführen.\n\nSie können in der nordwestlichen Ecke des Tals gefunden werden...\n\n<Raelorasz ritzt sich mit einem Speer in die Hand und benetzt die Spitze mit seinem Blut.>\n\nNehmt dies hier und wendet es auf eines von ihnen an. Wartet, bis es gebändigt ist, und bringt es zu mir zurück, bevor die Wirkung nachlässt.", progress = "Habt Ihr mir für meine Forschung ein Drachenjunges mitgebracht?", completion = "Das Schicksal dieser jungen Drachen muss Euer Gewissen nicht belasten, &lt;Volk&gt;. Malygos alleine trägt die Verantwortung hierfür.\n\nIch arbeite unablässig an der Lösung des Rätsels um diese Runen.\n\nLasst Euch versichern, dass wir nicht mehr Leben nehmen werden, als unbedingt notwendig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11941] = {title = "Rätselhaft...", objective = "Bringt das schillernde Fragment zu Raelorasz im Transitusschild.", description = "Irgendetwas an diesem Altmetall hält Euch davon ab, es wegzuwerfen.\n\nVielleicht ist Raelorasz in der Lage, etwas Licht ins Dunkel zu bringen, welchen Nutzen das Ding hat.", progress = "Was habt Ihr da, <Klasse>?", completion = "Es war eine weise Entscheidung, dies zu mir zu bringen, &lt;Name&gt;.\n\n\n\nWenn Ihr wahrhaftig wünscht, unser Unterfangen zu unterstützen, egal wie hoch das Risiko ist, dann werde ich Euch seinen Zweck verraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11942] = {title = "Worte der Macht", objective = "Thassarian in der Klagenden Ziggurat möchte, dass Ihr in die Tempelstadt En'kilah geht und Hohepriester Talet-Khas Rolle aus der Säule der Pein, Hohepriester Nafersets Rolle aus der Säule der Fäulnis und Hohepriester Andoraths Rolle aus der Säule des Blutes besorgt.", description = "Der Lich hat gesprochen, <Name>. Die Hohepriester von En'kilah hüten das Geheimnis darüber, wie man Naxxanar betreten kann.\n\nGeht zur Säule des Blutes, Säule der Pein und Säule der Fäulnis und tötet jeden der Priester.\n\nKehrt wieder zurück, sobald Ihr die drei Schriftrollen an Euch gebracht habt.", progress = "Ihr lasst Euch Zeit, oder wie? Ich weiß nicht, wie lange ich diesen Lich noch gefesselt halten kann.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Jetzt nur noch eine letzte Information.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11943] = {title = "Die Zelle", objective = "Raelorasz im Transitusschild möchte, dass Ihr General Cerulean die Gefängnisummantelung und Kriegshetzer Goredrak den Energiekern abnehmt.", description = "Ihr habt ein Fragment eines speziellen Gefängnisses gefunden, <Name>.\n\nMalygos' Diener sperren ihre gefangenen Magier und andere arkane Wesen in ähnlichen Gefängnissen ein, doch dieses hier wurde für etwas gebaut, das, wie soll ich sagen... stärker ist.\n\nGeht, in der Hoffnung, dass der Feind unseres Feindes unser Freund ist, und sucht die restlichen Fragmente des Gefängnisses.\n\nSie werden höchstwahrscheinlich im Besitz von Malygos' vertrautesten Untergebenen sein.", progress = "Habt Ihr irgendein anderes Teil des Gefängnisses gefunden?", completion = "&lt;Die Teile, die Ihr gesammelt habt, fangen an, in Raelorasz' Händen hell zu leuchten.&gt;\n\nEs ist vollbracht.\n\nIch spüre die Anwesenheit eines mächtigen Wesens in diesem Gefängnis. Hoffen wir darauf, dass es sich als Verbündeter erweist.", rewards = "Ihr bekommt:\n\nVerstärktes arkanes Gefängnis"}
MultiLanguageQuestData['de'][11944] = {title = "Umzingelt!", objective = "Korporal Venn in Todeswehr möchte, dass Ihr 7 Verteidiger der Ziggurat niederstreckt.", description = "Unsere Situation ist beinahe hoffnungslos. Uns wurde befohlen, mit einer Handvoll Männer die Klagende Ziggurat einzunehmen.\n\nWir können von Glück sprechen, wenn wir diese Position gegen die Geißel halten können. Wir sind zahlenmäßig unterlegen, haben Verletzte und sitzen in der Falle.\n\nWenn Ihr uns ein wenig entlasten könntet, wären wir in der Lage, unsere Position zu festigen. Tötet ein paar der Untoten, die sich um das Gebäude herum befinden - wir werden ihren Vorstoß abwehren.", progress = nil, completion = "Das sollte uns etwas Zeit verschaffen, &lt;Name&gt;. Wir werden die Hoffnung auf Unterstützung aus der Valianzfeste nicht aufgeben.", rewards = "Gamaschen der GluthitzeTaillenschutz des MarschenläufersSchulterklappen des EbenenjägersBrustplatte des SchlachtführersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11945] = {title = "Auf das Schlimmste gefasst sein", objective = "Utaik möchte, dass Ihr nach Kaskala geht und 8 Kisten mit Vorräten von Kaskala sammelt.", description = "Dunkle Zeiten sind über uns hereingebrochen. Karkuts Geist wandelt auf Erden und sammelt die Geister der toten Tuskarr ein.\n\nDie Söhne des Nebels haben viele unserer Brüder auf dem Gewissen. Bald schon wird unser geliebtes Kaskala in Schutt und Asche liegen.\n\nDoch es gibt noch Hoffnung. Vielleicht nicht für uns, aber wir haben unsere Familien nach Unu'pe geschickt. Wir kämpfen hier, um ihre Zukunft zu sichern.\n\nSie werden Vorräte brauchen, um nicht zu verhungern. Es gibt nicht genug Nahrungsmittel in Unu'pe. Bergt so viele Vorräte wie nur möglich, bevor es für unsere Familien zu spät ist.", progress = "Wart Ihr erfolgreich, <Name>? Unsere Verwandten in Unu'pe sind von dem, was wir unternehmen, abhängig.", completion = "Ich danke Euch, &lt;Name&gt;. Diese Vorräte werden unsere Cousins, Cousinen und Kinder mit Essen versorgen. Unser Stamm muss fortbestehen, selbst wenn Kaskala fallen sollte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11946] = {title = "Keristrasza", objective = "Keristrasza möchte, dass Ihr sie ansprecht, sobald Ihr bereit seid, Malygos entgegenzutreten.\n\nSprecht mit Raelorasz im Transitusschild, falls Ihr Euer verstärktes arkanes Gefängnis verlieren solltet.", description = "Ich bin... frei?\n\nIch war dazu bestimmt, für immer in einem leeren Abgrund umherzustreifen und nun bin ich errettet? Ihr könnt nicht nachvollziehen, wie dankbar ich Euch bin, <Sterblicher/Sterbliche>.\n\nAls ich mich weigerte, mich Malygos' Willen zu unterwerfen, hat er dies zu meinem Gefängnis gemacht, es zerschmettert und die Stücke verstreut. Würde ich auch Einhundert Eurer Lebenszeiten leben, vergessen werde ich Eure Gefälligkeit nicht.\n\nVielleicht werde ich mit der Zeit Wege finden, mich für Euren Gefallen erkenntlich zu zeigen. Fürs Erste müssen wir unsere Aufmerksamkeit jedoch auf Malygos richten. Ich bin schwach und es gibt viel zu erledigen.\n\nIch brauche Eure Hilfe, <Name>.", progress = nil, completion = "Wir können nicht warten, bis ich wieder zu Kräften komme.\n\nIn Bezug auf unsere Vorbereitungen muss ich mich auf Euch verlassen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11947] = {title = "Zurückschlagen", objective = "Beschwört mithilfe des Eisbrockens am Ethel Rethor in Desolace den Leutnant des Eishagels, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nIm Schatten des Ethel Rethor im Nordwesten von Desolace befindet sich ein Lager. Dort haben sie Eisbrocken, mit denen sie Verbindung mit den Elementaren aufnehmen – genau so, wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", progress = "Seid Ihr siegreich zurückgekehrt?", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11948] = {title = "Zurückschlagen", objective = "Beschwört mithilfe des Eisbrockens auf der Insel der Wasserelementare im Westen des Schlingendorntals den Leutnant des Eiswinds, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nNeptulon hat schon seit längerem eine Operationsbasis auf einer Insel im Westen des Schlingendorntals. Dort hat der Schattenhammerkult Eisbrocken aufgestellt, mit deren Hilfe sie Verbindung mit dem Reich des Gezeitenjägers aufnehmen – genau so, wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", progress = nil, completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11949] = {title = "Nicht ohne einen Kampf!", objective = "Ataika möchte, dass Ihr nach Kaskala geht und dort 12 Räuber der Kvaldir tötet.", description = "Kaskala ist uns ein geheiligter Ort, <Volk>. Unsere Vorfahren wurden vom Geiste Tayutkas selbst hierher geführt.\n\nNun greifen uns diese scheußlichen Kreaturen grundlos aus dem Nebel heraus an.\n\nWir werden ihnen beweisen, dass unsere Speere nicht nur für den Walfang geeignet sind. Kämpft an unserer Seite, <Volk>. Vielleicht wird mein Volk sich in Zukunft für Eure Güte erkenntlich zeigen.", progress = "Wir werden uns mit Händen und Füßen wehren, <Name>. Wir werden diesen Kvaldir keinen Zentimeter überlassen, ohne dass sie für ihn teuer bezahlen.", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde tief in Eurer Schuld stehen, wenn ich hier jemals lebend davonkomme.", rewards = "Fußlappen der EiswelleGürtelbund des WellenläufersUmschlossene HandgelenksschützerAuf Euch wartet eine dieser Belohnungen:\n\nRing aus Tiefseestoßzähnen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11950] = {title = "Muahits Weisheit", objective = "Findet den Ältesten Muahit in Kaskala.", description = "Hört zu, <Name>. Krieger wie ich sind entbehrlich. Sollte ich fallen, würden meine Brüder und Vettern meinen Speer aufheben und damit weiterkämpfen.\n\nAber ohne weise Ältere kann mein Volk nicht überleben. Dieser sture Muahit, der Ehrwürdigste unserer Schamanen, weigert sich, den Tayutka geweihten Altar auf der Insel in der Mitte zu verlassen. Es wäre ein schwerer Verlust, wenn diese Monster ihn erschlagen würden.\n\nIhr seid ein Außenstehender, vielleicht wird er auf Euch hören. Bringt ihn zur Vernunft... bittet ihn darum, sich nach Unu'pe in Sicherheit zu bringen, bevor es zu spät ist.", progress = nil, completion = "Ataika hat Euch geschickt, stimmt's? Nichts wird mich umstimmen.\n\nNoch ist nichts verloren. Die Geister sind noch immer mit uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11951] = {title = "Köder und Rute", objective = "Keristrasza hat Euch gebeten, 10 kristallisierte Manasplitter in Kaltarra zu sammeln.\n\nFalls Ihr Euer verstärktes arkanes Gefängnis verliert, sprecht mit Raelorasz beim Transitusschild.", description = "Während meiner Gefangenschaft konnte ich viel über Malygos lernen. Das Schicksal erlaubt es uns nun, dieses Wissen gegen ihn einzusetzen.\n\nEs gibt einen großen blauen Drachen, der über dem Nexus seine Kreise dreht, Saragosa. Sie dient zugleich als Wächterin des Aspekts und als seine Gefährtin. Falls irgendwelche ernsthaften Bedrohungen auftreten, alarmiert sie ihren Meister bezüglich der Gefahr.\n\nIch habe während meiner Gefangenschaft schwer unter Saragosa leiden müssen, und jetzt ist es an der Zeit für sie, zu sterben. Doch erst einmal brauchen wir den perfekten Köder...", progress = "Habt Ihr die Manasplitter gesammelt, die ich benötige?", completion = "Habt Dank, &lt;Name&gt;.\n\nIch bin von den Folgen meiner Gefangenschaft geschwächt und meine Kraft kehrt nur langsam zurück.\n\nIch werde mit der Macht dieser Kristalle weise umgehen. Sie sind ein Nebenprodukt von Malygos' üblen Plänen. Mit etwas Glück werden sie ihren Teil zu seinem Verderben beitragen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11952] = {title = "Zurückschlagen", objective = "Beschwört mithilfe des Eisbrockens in der Höhle unter dem Feuerwachtgrat im Nordwesten der Sengenden Schlucht den Leutnant des Eises, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nDer Feuerwachtgrat in der Sengenden Schlucht ist eine bekannte Bastion des Schattenhammerkults. Vor Kurzem haben sie damit begonnen, mithilfe der Eisbrocken in der Höhle Verbindung mit dem Reich des Gezeitenjägers aufzunehmen – genau so, wie sie es in Silithus machen. Ich sträube mich zwar sehr dagegen, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", progress = nil, completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11953] = {title = "Gegenschlag", objective = "Beschwört mithilfe des Eisbrockens in den Kavernen des Schattenhammers im Norden von Silithus den Leutnant des Gletschers, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nSilithus ist der Hauptsitz des Schattenhammerkults auf Azeroth. Im Norden haben sie damit begonnen, mithilfe neuer Eisbrocken Verbindung mit dem Reich des Gezeitenjägers aufzunehmen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", progress = nil, completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11954] = {title = "Zurückschlagen", objective = "Beschwört mithilfe des Eisbrockens in der Nähe des Dunklen Portals auf der Höllenfeuerhalbinsel den eisigen Templer, zerstört ihn und kehrt anschließend zu einem der Urahnen des Irdenen Rings zurück. Letztere befinden sich in den Hauptstädten.", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nUm Ahunes Gelingen zu garantieren, hat der Kult neben dem Dunklen Portal in Draenor ein Basislager errichtet. Sie verwenden Eisbrocken, um die Ankunft des Frostfürsten zu koordinieren. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", progress = "Seid Ihr siegreich zurückgekehrt?", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf den heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11955] = {title = "Ahune der Frostfürst", objective = "Begebt Euch in die Sklavenunterkünfte im Echsenkessel in den Zangarmarschen und sprecht mit Numa Wolkenschwester.", description = "Ich glaube, dass Ihr stark genug seid, um Euch der ultimativen Aufgabe zu stellen, die uns noch bevorsteht.\n\nWir dürfen nicht zulassen, dass das eintrifft, was der Schattenhammer und Neptulons Nagaketzer vorhaben. Im Namen Azeroths und allen Lebens auf der Welt: Wir müssen handeln. Uns ist klar, was getan werden muss. Ihr müsst in die Sklavenunterkünfte tief im Inneren des Echsenkessels reisen und Euch dort mit unseren Schamanen treffen. Geht - und macht schnell!", progress = nil, completion = "Den Geistern sei Dank, dass Ihr hier seid! Schnell, wir müssen Ahune beschwören, bevor es zu spät ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11956] = {title = "Findet das Phylakterium", objective = "Begebt Euch nach Todeswehr und reitet mit Abenddämmerung zu der Stelle, an der sich Tanathals Phylakterium befindet. Nehmt es an Euch und bringt anschließend zu Thassarian im Inneren der Klagenden Ziggurat.", description = "Keine Zeit für Geplauder, <Name>. Ich wurde ausgesandt, um diese Ziggurat einzunehmen, was sich als purer Selbstmord erwiesen hat. Ich habe meine Pflicht als Soldat erfüllt, doch nun ist es an der Zeit, Antworten zu bekommen.\n\nDieser Lich verfügt über Wissen, das ich benötige, doch ich kann seinen irdischen Körper nicht verletzen, um an dieses Wissen heranzukommen.\n\nDer Lich bewahrt seine Seele in einem Phylakterium auf, und solange es verborgen bleibt, ist es mir unmöglich, ihm die Information zu entlocken.\n\nKehrt zum Lager zurück, nehmt mein Pferd Abenddämmerung, steigt auf und lasst Euch von ihm zum Phylakterium führen. Bringt es zu mir.", progress = "Ihr seid zurück, <Name>. Habt Ihr das Phylakterium mitgebracht?", completion = "Gerade rechtzeitig, &lt;Name&gt;. Einen Lich festzuhalten, ist nicht so einfach, wie es aussieht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11957] = {title = "Saragosas Ende", objective = "Keristrasza möchte, dass Ihr mithilfe des arkanen Kraftfokus' Saragosa anlockt und sie anschließend besiegt.", description = "Durch Verwendung der Manakristalle, die Ihr uns gebracht habt, habe ich diesen arkanen Fokus hergestellt.\n\nSaragosa ist ein Vielfraß. Sie wird seinen Verlockungen nicht widerstehen können. In seinem Inneren liegt Magie verborgen, die Ihre Macht erheblich verringern wird. Lasst uns hoffen, dass sie meine List nicht erkennt...\n\nMacht Euch bereit, <Name>, und sprecht wieder mit mir, sobald Ihr bereit seid, Euch Saragosa zu stellen.", progress = "Saragosa darf nicht am Leben bleiben!", completion = "Diese Welt ist ein besser Ort, nun, da Saragosa nicht mehr existiert, doch unsere Arbeit ist noch nicht beendet.\n\nDie Zeit ist reif, Malygos selbst anzugreifen!", rewards = "Feuergehärteter GürtelbundFlammengehärtete HandgelenksschonerKauterisierende KettengamaschenAuf Euch wartet eine dieser Belohnungen:\n\nFuror des scharlachroten Drachen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11958] = {title = "Nichts darf verderben", objective = "Beschafft von den Wolvar 6 gestohlene Güter von Moa'ki. Bringt sie zum Ältesten Ko'nani im Hafen Moa'ki zurück.", description = "Die Wolvar sind seit jeher unsere natürlichen Feinde gewesen. Doch das Eindringen unseres Volkes in die große Drachenöde hat sie dazu gezwungen, sich auf eine kleine Lichtung im Norden zurückzuziehen.\n\nHeute Morgen war die Erde in Aufruhr - seitdem sind sie aggressiver denn je. Sie sind mehrmals über unsere Güter hergefallen... Dinge, die wir brauchen werden, wenn wir die bevorstehende Wanderung überleben wollen.\n\nSucht die Schneewehenwolvar auf und beschafft unsere Güter wieder; als Zeichen Eures guten Willens und der Freundschaft.", progress = "Das natürliche Gleichgewicht wurde in letzter Zeit mehrmals gestört.\n\nIch hoffe, dass Ihr uns dabei helfen werdet, den schmerzhaften Wandel unserer Lebensweise zu überleben.", completion = "Ich werde nicht behaupten, dass ich Euch gerne darum bitte, so etwas für uns zu tun. Es ist alles, was wir machen können, um unseren schnellen Aufbruch vorzubereiten - obwohl wir nicht genau wissen, wohin wir gehen sollen.\n\nMeine Zauberer sagen mir, dass Ihr gekommen seid, um das Land vor dem, der im Schatten wandelt, zu bewahren.\n\nIch vertraue darauf, dass Ihr auch das Volk dieses Landes retten werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11959] = {title = "Tötet Loguhn", objective = "Zeichnet Euch mit Loguhns Blut und kehrt dann zum Ältesten Ko'nani im Hafen Moa'ki zurück.", description = "Und schon kommt es statt schlimm noch schlimmer. Es gibt nur noch einen Weg... leider. Loguhn muss sterben!\n\nEr ist das Alphamännchen des Schneewehenstammes und ein wirklich übler Wolvar.\n\nDoch das ist die einzige Möglichkeit, eine kleine Atempause von ihren Angriffen und Raubzügen zu bekommen.\n\nIhr werdet den \"Reißer des Fleisches\" vor seiner Hütte am Nordhang der Lichtung finden. Er ist größer als die anderen und schwer zu verfehlen. Tötet ihn und zeichnet Euch mit seinem Blut, um sowohl Eure Überlegenheit als auch Euren Respekt zu zeigen.", progress = "Ist das Loguhns Blut oder Euer eigenes, <Volk>?", completion = "Loguhns ehrenhaftes Opfer durch Eure Hände ist genau das, was meine Leute brauchen. Jetzt werden wir das Beste mit den Wolvar machen, die um seinen Platz kämpfen.\n\nDas muss ausreichen.", rewards = "Armschienen des HaitauchersIm Meer verrostete StulpenAuf Euch wartet eine dieser Belohnungen:\n\nSchimmernder HauerringBartenhalsschmuck\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSlay Loguhn: Quest Complete\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11960] = {title = "Zukunftsplanungen", objective = "Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau'i im Hafen Moa'ki ab.", description = "Um unser Überleben zu sichern, müssen wir entschlossen gegen die Wolvar vorgehen. Ich mache mir jedoch Sorgen, dass wir in unserem Eifer zu viele von ihnen erschlagen werden.\n\nDie Schneewehenwolvar haben genauso wie wir das Recht zu überleben – also werden wir beide dafür sorgen, dass sie dieses Recht auch bekommen.\n\nWenn er es nicht schon längst getan hat, dann wird Euch Ältester Ko'nani darum bitten, mit den Wolvar fertigzuwerden. Und aus diesem Grund möchte ich auch, dass Ihr ihre Jungen einfangt und sie zu mir bringt, wenn Ihr Euch auf der Lichtung im Norden befindet.", progress = "Wie viele Jungen hättet Ihr in solch kurzer Zeit wohl retten können, hm?", completion = "Nun, ich schätze mal, dass Ihr genug von ihnen gerettet habt. Ich danke Euch, &lt;Volk&gt;.\n\nNun werden die Wolvar weiterhin mit uns überleben können - das heißt, wenn wir überhaupt überleben werden.\n\nDenkt Ihr, dass Ihr morgen wieder zurückkommen könntet, damit wir noch mehr von den Welpen retten können?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11961] = {title = "Die Geister wachen über uns", objective = "Ältester Muahit in der Bucht des Njordatems möchte, dass Ihr im Wasser nach Iruks Leiche sucht und Issliruks Totem bergt.", description = "Mächtige Geister wachen über meinen Stamm - Kaskala wird nicht untergehen.\n\nIssliruk wird uns Mut verleihen, Tayutka wird dafür sorgen, dass unsere Überlebenden immer zu essen und ein Dach über dem Kopf haben, und Karkut wird über die Gefallenen wachen, damit sie nicht vom rechten Weg abkommen.\n\nDoch Issliruks Führung brauchen wir jetzt am nötigsten. Ich habe meinen Neffen Iruk darum gebeten, mir Issliruks Totem zu bringen, doch er wurde von den Speeren der Kvaldir durchbohrt und sein Körper fiel nördlich von hier ins Wasser. Bringt mir das Totem, <Name>. Lasst nicht zu, dass meines Neffen Tod umsonst gewesen ist.", progress = "Das Totem, <Volk>. Habt Ihr es bei Euch?", completion = "Könnt Ihr Issliruks Gegenwart spüren, &lt;Name&gt;? Er möchte nicht, dass seine Kinder von den Nebelläufern getötet werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11962] = {title = "Eine letzte Lieferung", objective = "Liefert die Kiste mit Erz aus Fernhain zu Hilda Steinschmiede in der Valianzfeste.", description = "Das war's dann. Mithilfe der letzten Ladung Erz, die Ihr geborgen habt, sollten wir genug haben, um es zur Valianzfeste zu schicken.\n\nFalls Fernhain von der Landkarte Azeroths getilgt wird, dann lasst uns wenigstens diejenigen sein, die einst als Erste unser Land verteidigten und als Letzte aufgaben.\n\nBringt dieses Erz zu Hilda Steinschmiede - sie ist eine gute Freundin von mir. Sagt ihr, dass sie aus diesem Erz ein paar gute Waffen herstellen soll. Wir werden in Zukunft reichlich von ihnen benötigen.", progress = "Was habt Ihr denn da?", completion = "Erz aus Fernhain? Bislang ist keine Lieferung vorgesehen. Stimmt etwas nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11963] = {title = "Waffen für Fernhain", objective = "Kehrt zu Gerald Grün in Fernhain zurück.", description = "Fernhain wurde überrannt und alles, woran Gerald denkt, ist, mir meine Erzlieferung zu beschaffen? Ich versichere Euch, der Mann ist mindestens genauso beherzt wie einer unserer Soldaten an der Front.\n\nWir können nicht zulassen, dass die Zivilisten ihr Land verlieren, wenn sie dazu bereit sind, dafür zu kämpfen. Wir haben vielleicht nicht die nötigen Truppen übrig, doch wir können ihnen Waffen liefern.\n\nDiese hier waren eigentlich für die neuen Rekruten gedacht, aber mit dem Erz, das Ihr mir gebracht habt, kann ich den Bedarf abdecken. Lasst Gerald wissen, dass die Waffen auf dem Weg sind.", progress = nil, completion = "Hilda schickt uns Waffen? Das sind ausgezeichnete Neuigkeiten, &lt;Name&gt;. Ich wollte den Jungs gerade sagen, dass sie ihre Sachen packen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11964] = {title = "Rauchwerk für die Sommerflämmlinge", objective = "Der Meister der Lehren möchte, dass Ihr einem SommerflämmlingRauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Allianz.", description = "Habt Ihr gewusst, dass unsere Feuer des Sonnenwendfestes in jedem Land brennen, in dem auch eine Siedlung der Allianz existiert? Sie befinden sich in den Lagern außerhalb der Städte und werden von Flammenwächtern gepflegt. Die Wächter kümmern sich darum, dass die Freudenfeuer hell brennen und die Feierlichkeiten weitergehen.\n\nJeder Flammenwächter hat einen Sommerflämmling bei sich - einen Abgesandten der Geister des Feuers.\n\nMöchtet Ihr einem Sommerflämmling Eure Ehrerbietung erweisen, <Name>? Dann nehmt dieses Rauchwerk des Sommers und bringt es einem von ihnen. Besänftigt den kleinen Feuergeist und er könnte sich dafür erkenntlich zeigen.", progress = "Feurige Grüße, verehrter <Klasse>. Ihr befindet Euch auf geheiligtem Boden. Willkommen zum Sonnenwendfest.", completion = "Ah, und was haben wir denn hier? Welch angenehmes Aroma! Ich bin mir sicher, dass seine Flamme rein und hell leuchten wird!\n\nNehmt diese Blüte, &lt;Name&gt; - nehmt und lasst mich alleine... Ich muss mich um diesen kostbaren Brennstoff kümmern...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSommerflämmling Rauchwerk geben\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11965] = {title = "Zu den Waffen!", objective = "Geht zum Rathaus in Fernhain und lasst die Glocke läuten.", description = "Fernhain hat nun wieder eine Chance, im Kampf zu bestehen, <Name>. Das ist alles, was wir uns gewünscht haben, und Ihr habt es ermöglicht.\n\nAlles, was wir jetzt noch brauchen, ist ein Sammelpunkt. Ich werde meinen Männern sagen, dass sie die Waffen zu unserem Rathaus bringen sollen. Geht und läutet die Rathausglocke, damit alle Überlebenden wissen, wo sie sich sammeln müssen.\n\nEs ist an der Zeit, der Geißel zu beweisen, aus welchem Holz wir geschnitzt sind.", progress = nil, completion = "Danke nochmal dafür, dass Ihr uns geholfen habt, &lt;Name&gt;. Die Einwohner Fernhains werden Euch nicht vergessen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nUnzähmbarer Halsreif des LichtsKette der TotenglockeAnhänger des revolutionären Gedankens\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11966] = {title = "Rauchwerk für die Festflämmlinge", objective = "Der Geschichtenerzähler möchte, dass Ihr einem FestflämmlingRauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Horde.", description = "Habt Ihr gewusst, dass unsere Feuer des Sonnenwendfestes in jedem Land brennen, in dem auch eine Siedlung der Horde existiert? Sie befinden sich in den Lagern außerhalb der Städte und werden von Flammenbewahrern gepflegt. Die Bewahrer kümmern sich darum, dass die Freudenfeuer hell brennen und die Feierlichkeiten weitergehen.\n\nJeder Flammenbewahrer hat einen Festflämmling bei sich - einen Abgesandten der Geister des Feuers.\n\nMöchtet Ihr einem Festflämmling Eure Ehrerbietung erweisen, <Name>? Dann nehmt dieses Rauchwerk des Sommers und bringt es einem von ihnen. Besänftigt den kleinen Feuergeist und er könnte sich dafür erkenntlich zeigen.", progress = "Feurige Grüße, verehrter <Klasse>. Ihr befindet Euch auf geheiligtem Boden. Willkommen zum Sonnenwendfest.", completion = "Ah, und was haben wir denn hier? Welch angenehmes Aroma! Ich bin mir sicher, dass seine Flamme rein und hell leuchten wird!\n\nNehmt diese Blüte, &lt;Name&gt; - nehmt und lasst mich alleine... Ich muss mich um diesen kostbaren Brennstoff kümmern...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSommerflämmling Rauchwerk geben\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11967] = {title = "Die Roten versammeln", objective = "Keristrasza hat Euch gebeten, sie zu Raelorasz am Transitusschild zu bringen.", description = "Malygos ist sich mit Sicherheit dessen bewusst, dass etwas nicht stimmt.\n\nIch kenne ihn. Seine Aufmerksamkeit ist auf mehrere Ziele gerichtet. Ich bin zuversichtlich, dass ich ihn aus der Sicherheit seines Reiches locken kann, wenn er davon erfährt, was mit seiner teuren Saragosa geschehen ist.\n\nBringt mich umgehend zu Raelorasz, <Name>. Er muss jeden seiner Drachen dazu bewegen, sich Malygos zu stellen.", progress = "Habt Ihr Neuigkeiten für mich, <Name>?", completion = "Mir ist die Nachricht über Keristraszas Rettung zu Ohren gekommen. Gepriesen seien Eure Taten.\n\nIch kann es kaum erwarten, wieder mit ihr zu sprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11968] = {title = "Das Blatt wendet sich", objective = "Ältester Muahit möchte, dass Ihr Euch zur Bucht des Njordatems begebt und Heigarr den Schrecklichen erschlagt.", description = "Die Geister haben unseren Hilferuf vernommen, <Name>. Es ist ein Zeichen, dass Kaskala vielleicht noch gerettet werden kann.\n\nNutzt die Verwirrung aus, die das Wetter verursacht hat, und erschlagt den Anführer der Kvaldir. Euer Handeln wird die Schlacht zu unseren Gunsten wenden, da bin ich mir sicher.", progress = nil, completion = "Ihr habt uns einen großen Gefallen erwiesen, &lt;Volk&gt;. Der Kampf ist noch nicht gewonnen, doch mein Volk hat nun eine Chance.", rewards = "FlossenschnitzerTranquetscherZooks WandersteckenSchneide der TuskarrAuf Euch wartet eine dieser Belohnungen:\n\nHandbuch der Gezeiten\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11969] = {title = "Die Falle zuschnappen lassen", objective = "Raelorasz möchte, dass Ihr Raelorasz' Funken beim Signalfeuer in Kaltarra benutzt.", description = "Dass sich mir diese Möglichkeit bietet, habe ich größtenteils Euren Mühen zu verdanken, <Name>.\n\nDaher wäre es nur passend, wenn Ihr den Angriff auf Malygos einleiten würdet.\n\nNehmt diesen Funken und entzündet damit das Signalfeuer nordwestlich des Nexus. Keristrasza wird sich von dort an Eurer annehmen.", progress = "Habt Ihr Euch mit Keristrasza getroffen?", completion = "Wir haben Malygos einen Schlag verpasst, mussten es jedoch teuer bezahlen.", rewards = "Gezackter SchuppenkolbenFeurige RuteSchwelende KralleRute des PurpurhütersPurpurner WilleSchuppiger FlammenumhangIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][11970] = {title = "Der Meister der Sommerlehre", objective = "Sprecht mit einem Meister der Lehren in einer der Hauptstädte.", description = "Unser Fest soll eine Zeit der Freude und des Lachens sein, so viel ist sicher. Es ist jedoch wichtig, dass Ihr den Ursprung dieser Feiertage kennt und versteht. Bildung will ausgesucht sein und gewürdigt werden.\n\nDer Meister der Lehren in den Hauptstädten wird Euch den Weg weisen können. Geht jetzt und lernt.", progress = nil, completion = "Liebend gerne werde ich Euch zeigen, was ich weiß.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11971] = {title = "Der Erzähler der Sommergeschichten", objective = "Sprecht mit einem Geschichtenerzähler in einer der Hauptstädte.", description = "Unser Fest soll eine Zeit der Freude und des Lachens sein, so viel ist sicher. Es ist jedoch wichtig, dass Ihr den Ursprung dieser Feiertage kennt und versteht. Bildung will ausgesucht sein und gewürdigt werden.\n\nDer Geschichtenerzähler in den Hauptstädten wird Euch den Weg weisen können. Geht jetzt und lernt.", progress = nil, completion = "Liebend gerne werde ich Euch zeigen, was ich weiß.", rewards = "Ihr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11972] = {title = "Splitter von Ahune", objective = "Bringt die Eissplitter zu Luma Himmelsmutter.", description = "In diesen Splittern pulsiert ein Unheil verkündendes Licht. Halten sie die letzte Essenz des Frostfürsten in ihrem Inneren verborgen?", progress = "Seid gegrüßt, <Name>. Ihr seht besorgt aus, solltet Euch jedoch freuen. Der Frostfürst ist besiegt!", completion = "Ja, diese Splitter enthalten in ihrem Inneren die letzte Essenz des Frostfürsten, die es auf dieser Welt gibt. Wir werden sie beseitigen und Ahune in die niederen Sphären der Kälte verbannen.\n\nDanke Euch, &lt;Name&gt;. Euer Name wird für den Rest der Zeit in den Liedern des Irdenen Rings besungen werden. Bitte erweist uns eine Ehre und akzeptiert diese milde Gabe, ein Symbol Eurer Verwandschaft mit Wärme und Licht.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSommerlicher HimmelswappenrockSommerlicher Flammenwappenrock\n\nIhr bekommt außerdem:\n\nBrandblüte"}
MultiLanguageQuestData['de'][11973] = {title = "Kriegsgefangene", objective = "Kriegsmagierin Kaitlyn möchte, dass Ihr Keristrasza befreit.", description = "Malygos hat Keristrasza als seine Gefährtin auserkoren!\n\nDies darf nicht geschehen.\n\n<Volk>, Ihr müsst tun, was auch immer vonnöten ist, um ihr dieses Schicksal zu ersparen.", progress = nil, completion = "So, es ist also vollbracht...\n\nWir für unseren Teil werden niemals vergessen, welch Opfer sie zu diesem Zweck gebracht hat.", rewards = "Tuch der flüssigen AngriffeMantelung von KeristraszaUmhang des AzurlichtsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11975] = {title = "Nun, wenn ich einmal groß bin...", objective = "Geht mit Eurem Waisenkind Salandria zur Straße der Urahnen in Silbermond, um die Elite Tauren Chieftain zu sehen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", description = "Vielleicht habe ich Euch das schon gefragt, aber als Ihr so alt wart wie ich, wusstet Ihr dann, dass Ihr eines Tages, wenn Ihr groß seid, <ein/eine:c> <Klasse> sein würdet?\n\nIch weiß nicht, was ich einmal werden will. Vielleicht eine Magierin oder eine Hexenmeisterin oder ein Blutritter, wie ich davor schon mal gesagt hab? Oder vielleicht... ein Rockstar!! Wie Sig Nicious, der Blutelf, bei den 'Elite Tauren Chieftain'!\n\nHabe gehört, dass wenn die nicht gerade auf Tour sind, dann hängen sie in Silbermond ab! Könntet Ihr mich dorthin bringen? Sie sitzen auf einem Balkon in der Straße der Urahnen herum und warten darauf, dass Leute vorbeikommen.\n\nBitte bringt mich dorthin. Bitte!", progress = nil, completion = "Habt Ihr das gesehen? Die haben mir zugejubelt!!\n\nNun weiß ich, wie sie sich fühlen, wenn sie auf der Bühne stehen und singen! Ich konnte die Kraft und Energie spüren!\n\nFür mich ist es genauso wie in ihrem Lied!\n\nMy mind is made up, I am going to be a rock star when I grow up! (Mein Entschluss steht fest. Ich werde ein Rockstar sein, wenn ich groß bin!)", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11976] = {title = "Eissplitter", objective = "Bringt die Eissplitter zu Luma Himmelsmutter.", description = "In diesen Splittern pulsiert ein Unheil verkündendes Licht. Halten sie die letzte Essenz des Frostfürsten in ihrem Inneren verborgen?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSommerlicher HimmelswappenrockBrandblüte"}
MultiLanguageQuestData['de'][11977] = {title = "Ein Tauren unter Taunka", objective = "Geht zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf.", description = "<Wartuk deutet in Richtung Nordosten.>\n\nSie ist ziemlich freundlich, müsst Ihr wissen. Wäre Eure Abgesandte nicht gewesen, hätten die überlebenden Flüchtlinge womöglich die Hoffnung aufgegeben. Sie ist vielleicht nicht von Geburt an eine Taunka, doch der Stamm hat sie für die Zwischenzeit zur Dorfältesten auserkoren.\n\nWenn Ihr <derjenige seid, den/diejenige seid> die; ich meine, dann geht bitte zum Flüchtlingslager und stattet der Abgesandten Leuchthuf einen Besuch ab. Sie erwartet Euch.", progress = nil, completion = "Was Ihr hier sehen könnt, ist alles, was von den Taunka aus der boreanischen Tundra und der Drachenöde übrig geblieben ist. Sie sind ein gebrochenes Volk... geschunden und von der Geißel fast ausgerottet.\n\n&lt;Leuchthuf schüttelt ihren Kopf.&gt;\n\nNur die Horde kann sie jetzt noch retten. Nur die Horde kann ihren gebrochenen Geist wieder heilen. Wir werden sie pflegen, bis sie wieder bei bester Gesundheit sind, und sie werden im Gegenzug die Horde in Nordend verstärken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11978] = {title = "Mit offenen Armen empfangen", objective = "Abgesandte Leuchthuf im Flüchtlingslager von Westwind in der Drachenöde möchte, dass Ihr 10 Waffen der Horde beschafft.", description = "Bevor wir diese Taunka offiziell in die Horde aufnehmen können, müssen wir den Nerubern der Anub'ar, von denen die Wälder hier in der Nähe nur so wimmeln, unsere Waffen wieder abnehmen. Sie gingen verloren, als eine Karawane von Agmars Hammer letzte Nacht in einen Hinterhalt der Geißel geriet.\n\nWagt Euch in die Wälder hinaus, die sich östlich des Flüchtlingslagers von Westwind befinden, und bringt mir diese Waffen zurück, <Volk>.", progress = "Ohne Rüstungen und Waffen werden unsere neuesten Mitglieder schutzlos ihre Wanderung nach Agmars Hammer antreten müssen.", completion = "Das ist genau, was wir brauchen, &lt;Name&gt;! Die Waffen der Horde zu schwingen, wird ihre Seele erfrischen und ihnen den nötigen Schutz gegen die Geißel geben.\n\nSeid Ihr bereit für das Aufnahmeritual?\n\n\n\nIhr werdet derjenige sein, der unsere neuen Verbündeten offiziell in die Horde aufnehmen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11979] = {title = "Die Taunka und die Tauren", objective = "Geht zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf.", description = "Die Geißel hat Eisnebel, die Hauptstadt der Taunka, unter ihre Kontrolle gebracht! Alle Taunka, die das Massaker überlebt haben und fliehen konnten, wurden im Flüchtlingslager von Westwind an der westlichen Grenze der Drachenöde in Sicherheit gebracht.\n\nFürst Höllschrei glaubt, dass sich die Taunka der Horde anschließen müssen, wenn sie überleben wollen, und hat eine Taurenabgesandte nach Westwind entsandt, um unsere Beziehung zu den Wintertauren zu festigen. Reist zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf - Ihr werdet sie unterstützen.", progress = nil, completion = "Was Ihr hier sehen könnt, ist alles, was von den Taunka aus der boreanischen Tundra und der Drachenöde übrig geblieben ist. Sie sind ein gebrochenes Volk... geschunden und fast ausgerottet.\n\n&lt;Leuchthuf schüttelt ihren Kopf.&gt;\n\nNur die Horde kann sie jetzt noch retten. Nur die Horde kann ihren gebrochenen Geist wieder heilen. Wir werden sie pflegen, bis sie wieder bei voller Gesundheit sind, und sie werden im Gegenzug die Horde in Nordend verstärken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11980] = {title = "Stolz der Horde", objective = "Blutwache Roh'kill im Flüchtlingslager von Westwind in der Drachenöde möchte, dass Ihr 15 Wegelagerer der Anub'ar niederstreckt.", description = "Ich gehörte zur Eskorte der Karawane, die mit einer Waffenlieferung auf dem Weg in dieses Lager war. Der Angriff kam schnell und ohne Vorwarnung. Wir bekämpften und erschlugen Dutzende dieser Biester, doch am Ende waren es einfach zu viele. Tor'zin und ich konnten gerade noch mit dem Leben davonkommen...\n\nWären wir nicht verletzt, würden wir uns selbst draußen in den Wäldern auf die Jagd nach diesen Scheusalen machen. Werdet Ihr uns dabei helfen, unseren verlorenen Stolz wiederzuerlangen? Sucht in den Wäldern östlich von hier nach Nerubern der Anub'ar und tötet sie! Für die Horde!", progress = nil, completion = "&lt;Roh'kill salutiert vor Euch.&gt;\n\nIhr habt unsere Ehre bewahrt, &lt;Name&gt;. Wir beide, Tor'zin und ich, danken Euch für diese selbstlose Tat!", rewards = "Armschienen des SpinnenwärtersGürtel des LichtungswanderersBrustplatte aus zischendem ChitinBeinplatten des Bewahrers von AgmarAuf Euch wartet eine dieser Belohnungen:\n\nSkarabäus von Isanoth\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][11981] = {title = "Findet Kurun!", objective = "Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt.", description = "Das Gesicht des Irdenen Kriegers ist überzogen mit Rissen und Furchen. Obwohl es ihm nicht möglich ist, zu bluten, könnt Ihr doch fühlen, dass der Krieger dem Tode nahe ist.\n\nDem Mund des Kriegers entflieht eine leise, heisere Stimme.\n\n\"Findet… Kurun... Ihr müsst Kurun... finden.\"\n\nEr schaut Euch hilflos an, als ob Ihr eine Antwort darauf geben könntet, wer oder was Kurun sein könnte.\n\n\"Unser... Anführer... er steht auf dem... Hügel, der Thor Modan überschaut... er befehligt uns. Bitte... sagt ihm... wir können die Stadt nicht... einnehmen...\"", progress = nil, completion = "&lt;Ihr überbringt Kurun die Nachricht, die der gefallene Irdene Euch gegeben hat. &gt;\n\nSie kämpfen tapfer, aber er hat Recht. Ohne Hilfe werden wir die Eisenzwerge von Thor Modan nicht bezwingen können. Meine Riesen und die Irdenen haben lange gegen das Böse des Eisens gekämpft, aber unsere Streitmacht ist nicht groß genug, um den Kampf um Thor Modan zu gewinnen. Werdet Ihr uns helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11982] = {title = "Es regnet Zerstörung", objective = "Kurun auf dem Hügel, der Thor Modan überblickt, möchte, dass Ihr die Arbeiten der Eisenzwerge dadurch stört, dass Ihr Felsbrocken in den freigelegten Bereich von Thor Modan werft.", description = "Unter uns liegt die uralte Dunkeleisenbastion Thor Modan. Vor Tausenden von Jahren brachen die Steinriesen das Land entzwei, wobei Teile der Stadt zum Einsturz gebracht und ein großer Anteil des Rests freigelegt wurde.\n\nSelbst jetzt versuchen die Eisenzwerge, ihre alte Hauptstadt zurückzugewinnen, aber das werden wir nicht erlauben. Meine Riesen füllen den Graben mit Felsbrocken und Geröll, in der Hoffnung, ihn damit zu verschließen und die Eisendiener bei der Arbeit zu töten. Nehmt die Felsbrocken, die Ihr nordöstlich des Grabens findet, und helft uns, ihren Machenschaften einen Riegel vorzuschieben.", progress = "Was habt Ihr zu berichten?", completion = "So schnell wir auch den Graben füllen, so schnell machen die Eisenzwerge ihn doch wieder frei. Wir werden die Stadt nicht allein durch den Angriff von oben einnehmen können. Ihr müsst den Irdenen helfen, die auf dem Platz unten kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11983] = {title = "Blutschwur der Horde", objective = "Sprecht mit den Taunka im Flüchtlingslager von Westwind und bringt 5 von ihnen dazu, der Horde Treue zu geloben.\n\nBringt den Blutschwur der Horde wieder zur Abgesandten Leuchthuf, sobald Ihr diese Aufgabe abgeschlossen habt.", description = "Sie sind bereit, <Name>. Diese Taunka würden nur zu gerne der Horde beitreten und alles dafür geben, die Geißel aus der Welt zu schaffen.\n\n<Leuchthuf gibt Euch eine Schriftrolle, die das Siegel der Horde trägt.>\n\nIn dieser Schriftrolle steht der Blutschwur der Horde geschrieben. Die Tradition verlangt, dass unsere neuen Taunkabrüder- und -schwestern die darin befindlichen Worte verlauten lassen.\n\nNehmt diese Schriftrolle und verpflichtet die Taunka in den Dienst der Horde, <Kommandant/Kommandantin>. Bringt die Rolle wieder zu mir zurück, wenn Ihr Euren Auftrag abgeschlossen habt.", progress = "Sie werden der Horde zu mehr Kraft verhelfen, Kommandant.", completion = "Ich danke Euch dafür, Kommandant &lt;Name&gt;. Sie hatten nichts mehr. Doch Euch ist es zu verdanken, dass sie einen neuen Sinn gefunden und damit neue Hoffnung geschöpft haben... Hoffnung auf ein Morgen... auf ein neues Leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11984] = {title = "Die Käfige vollmachen", objective = "Samir am Granitquell möchte, dass Ihr mithilfe des Käfigs des Kopfgeldjägers einen Troll einfangt, der von Budd betäubt wurde.", description = "Der alte Budd hat auch schon bessere Tage erlebt.\n\nSeit unserem Aufenthalt in den Geisterlanden war er für uns komplett nutzlos. Wir mussten einen Weg finden, es selbst zu schaffen, und heutzutage bedeutet das, Trolle an den Höchstbietenden zu verkaufen.\n\nZum Glück haben wir vor Kurzem eine Verwendung für Budd gefunden. Irgendetwas an seinem Zustand erlaubt es ihm, mit den hiesigen Trollen in Kontakt zu treten, also haben wir ihm ein kleines Spiel beigebracht, das uns einigen Profit eingebracht hat.\n\nSeht selbst. Sprecht mit Budd, nehmt ihn mit in den Südwesten zu den Ruinen von Drak'Zin und benutzt diesen Käfig, sobald er einen Troll erwischt.", progress = "Habt ihr es geschafft, einen Eistroll zu fangen?", completion = "Gut gemacht, &lt;Klasse&gt;. Sieht so aus, als ob wir Budd noch ein wenig länger behalten werden.\n\nEuer Käfig wird gleich abgeholt. Hier ist Euer Anteil an der Belohnung.\n\nOh und willkommen im Lager. Bleibt ruhig, ich bin mir sicher, dass wir eine Verwendung für Euch finden...", rewards = "Quetscher der aufgehobenen EmanzipationJochschlitzerStachel der verleugneten AutonomieTrillerarmbrustSchwert des unfreien GeistesStreitkolben des HelotenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11985] = {title = "In die Bresche springen", objective = "Kurun auf dem Hügel, der Thor Modan überblickt, möchte, dass Ihr den Eisenthan Argrum tötet.", description = "Wenn wir die Verteidiger in Thor Modan nicht besiegen, dann können die Eisenzwerge bis in alle Ewigkeit ausharren. Die Irdenen haben tapfer gegen die Konstrukte gekämpft, die die Söhne des Eisens aufgebaut haben.\n\nDie Tunnel verengen sich zu schnell, als dass meine Riesenkameraden uns von Nutzen sein könnten, was unsere Optionen einschränkt. Wärt Ihr bereit, Euch in die Stadt zu wagen und den Zwerg, der den Widerstand befehligt, zu töten?", progress = "Ist es Euch gelungen, den Kommandanten zu töten?", completion = "Gut gemacht, &lt;Name&gt;. Der Verlust des Kommandanten der Eisenzwerge sollte ausreichen, um die verbleibenden Verteidiger zu bezwingen. Die Irdenen sollten in der Lage sein, mit den Überlebenden fertig zu werden.", rewards = "Schmiedegeschweißte SandalenEisenbrechergamaschenFlammengeprüfter BrustschutzHandschutz der mangelnden BeherrschungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11986] = {title = "Das beschädigte Tagebuch", objective = "Sammelt 8 der fehlenden Tagebuchseiten, ergänzt damit das Tagebuch und bringt Torthen Grabtief im Lager der Westfallbrigade das vervollständigte Buch.", description = "Dieses abgenutzte, mit Matsch beschmutzte Tagebuch hat auch schon bessere Tage gesehen. Beim Durchblättern fallen Euch Dutzende von Notizen, Diagrammen und Abbildungen ins Auge.\n\nDie Handschrift des Autors kommt Euch vage bekannt vor, aber Ihr könnt sie nicht einordnen, bis Ihr einen Eintrag seht, der mit dem Namen Brann Bronzebart unterschrieben ist.\n\nDie hintere Hälfte des Buches, die die jüngsten Einträge enthalten hätte, ist abgerissen worden. Seiten fliegen über das Schlachtfeld und es wird unmöglich sein, herauszufinden, was Brann entdeckt hat, bis das Buch wieder ganz ist.", progress = "Was habt Ihr da?", completion = "Ihr habt Branns Tagebuch gefunden? Das ist unglaublich! Seit einiger Zeit nun haben wir kein Lebenszeichen mehr von ihm erhalten und wir waren besorgt, dass er gefangen oder getötet worden sein könnte. Was hat er in Thor Modan entdeckt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11987] = {title = "Glückskarte: Silber", objective = "Auf Euch wartet eine dieser Belohnungen:\n\n", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKiste mit Schätzen"}
MultiLanguageQuestData['de'][11988] = {title = "Der Runenschlüsselstein", objective = "Bringt Torthen Grabtief im Lager der Westfallbrigade 5 Fragmente des Runenschlüsselsteins.", description = "Brann erwähnt in seinem Tagebuch, dass er einen Runenschlüsselstein benutzte, um die entscheidenden Runen auf der von ihm gefundenen Scheibe zu erhellen. Ohne den Schlüsselstein ist auf der Scheibe wenig mehr als sinnloses Kauderwelsch zu lesen.\n\nAm Ende von Branns letztem Eintrag beschreibt er, wie es den Verteidigern der Eisenzwerge gelang, ihm den Schlüsselstein abzunehmen, ihn zu zerbrechen und die Einzelteile unter sich aufzuteilen. Bevor wir also die runenverzierte Scheibe entziffern können, müssen wir die Fragmente in unseren Besitz bringen. Jeder der Zwerge in Thor Modan oder in den Gebäuden drum herum könnte Fragmente bei sich haben.", progress = "Habt Ihr genügend Fragmente, um den Schlüsselstein wieder zusammenzusetzen?", completion = "&lt;Torthen macht sich schnell daran, die von Euch gesammelten Fragmente zusammenzusetzen.&gt;\n\nEs ist nicht vollständig, aber trotzdem sollte es uns ermöglichen, den Großteil der Informationen auf der Scheibe zu lesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11989] = {title = "Waffenstillstand?", objective = "Drakuru am Granitquell möchte, dass Ihr in der Nähe seines Käfigs das stumpfe Schnitzmesser benutzt und dann mit ihm sprecht.", description = "Pass auf, Mann.\n\nDu bist <ein/eine:r> <Volk> und Drakuru hat mehr von euren Köpfen geschrumpft als er sich erinnern kann - und selbst wenn ich mich erinnern könnte, so weit könnt' ich gar nich' zählen. Da hast du Glück gehabt, dass ich in dies'm Käfich gefangen bin oder ich würd' der Liste glatt noch ein' hinzufüg'n. \n\nAber, da es is', wie es is', wie wär's, wenn wir unsere kleinen Meinungsverschiedenheiten kurz beseite schieben, hm?\n\nDrakuru weiß Dinge, Mann. Dinge, die dir bei deinen Anstrengungen helfen könn'.\n\n<Drakuru ritzt seine Handfläche an einem seiner Hauer ein und streckt seine Hand durch die Käfigstäbe.>\n\nAlso, was sachst du, Mann... Waffenstillstand?", progress = "Gute Wahl, Mann. Du wirst es nich' bereu'n...", completion = "So!\n\nNu' sin' wir durch Blut verbunden. 'Ne echte Verbindung, die wir da ham.\n\nHör Drakuru gut zu, &lt;Volk&gt;. Es gibt viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11990] = {title = "Phiole der Visionen", objective = "Drakuru am Granitquell möchte, dass Ihr ihm eine Kristallphiole, einen Wassergraswedel und 3 Dunstblätter bringt.", description = "Immer hübsch eins nach'm anner'n, Mann. Zuerst muss noch ein wenig Vorarbeit geleistet werden.\n\nKeine Ahnung, wie lange die mich hier behalten. Du brauchst ein mächtiges Elixier, damit wir in Kontakt bleib'n könn'.\n\nSo ein Glück, dass mir da gerade das Richtige einfällt! Un' die Zutaten finden sich alle in der Nähe.\n\nIch brauch'ne Phiole von dem hübschen kleinen Trollmädel da drüb'n, ein bisschen Wassergras aus'm See im Norden und ein paar Dunstblätter, die um das Lager herum zu finden sind.\n\nBeeil dich, Mann, bevor'se mich davonschlepp'n.", progress = "Hast du den Kram, Mann?", completion = "&lt;Drakuru nimmt die Zutaten und verbindet sie geschickt in der Phiole.&gt;\n\nSo viel dazu, Mann. Jetzt aber ab an die Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11991] = {title = "Interpretationssache", objective = "Drakuru möchte, dass Ihr 5 Flaschen gefrorenes Mojo von den Drakkaritrollen in den Ruinen von Drak'Zin beschafft und anschließend das Elixier bei Drakurus Kohlenbecken trinkt.", description = "Da gibt's ein legendäres Set von Artefakten, seit Tausenden von Jahren verloren, hergestellt, um die Feste Drak'Tharon undurchdringlich zu machen.\n\nViele halt'n 'se für 'nen Mythos, aber Drakuru weiß es besser, Mann!\n\nIch war ganz kurz davor, herauszufinden, wo eins is', aber dann wurd' ich gefang'n, während ich dabei war, die Hieroglyphen zu deuten. Geh in den Südwesten und benutz dieses Elixier am Kohlenbecken in den Ruinen von Drak'Zin, damit ich die Deutung zu Ende bring'n kann.\n\nUm meine Seele dort zu beschwör'n, gehört in das Elixier ein bisschen gefrorenes Mojo. Ich hass' es, meine Brüder fallen zu seh'n, aber es is' ja für die gute Sache.", progress = nil, completion = "Ahh, gut... Gut gemacht, Mann.\n\nKann die Hieroglyphen auf den Mauern von hier aus gut lesen...", rewards = "Astrale KapuzeDrakurus gespenstischer HelmHelm der GeistverbindungenGeistgeschmiedeter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11992] = {title = "Navigation Charts (Deprecated)", objective = "Obtain the missing parts of the Skadir Navigational Chart and bring it to Karuk in Riplash Stand.", description = "You've uncovered the first part of a navigation chart drawn on flayed dragonskin. If you could complete it you'd be able to find the kvaldir's future plans of attack.\n\nOther mariners in Riplash might have the missing charts on them. Karuk would be interested in the information they contain.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11993] = {title = "Die Runenprophezeiungen", objective = "Torthen Grabtief im Lager der Westfallbrigade möchte, dass Ihr die drei Runenplatten entziffert.", description = "Wir haben keine Zeit zu verlieren! Nun, da wir den Runenschlüsselstein wieder zusammengesetzt haben - nun, fast zumindest - können wir den Inhalt der Runenplatten, an denen Brann vor seiner Flucht gearbeitet hat, entziffern.\n\nWir können nicht wissen, ob er alle drei Platten entziffern konnte, aber wir müssen einfach davon ausgehen, dass er genug Informationen gesammelt hat, um seinen nächsten Schritt zu planen.\n\nStellt Euch vor jede der Platten und benutzt den Schlüsselstein, um ihren Inhalt zu entschlüsseln. Brann könnte auf uns angewiesen sein!", progress = nil, completion = "&lt;Torthen hört zu, als Ihr den Inhalt der Runenplatten wiedergebt.&gt;\n\nBei Madorans Hammer, er hat eine völlig neue Titanenstadt entdeckt!\n\n'Die Wiege von Stein und Eisen.'\n\n'Ulduar an den Sturm geschmiegt.'\n\nWas meint ihr, was das heißt? Könnte es sein, dass wir am Ende alle dorther stammen, nach all den Jahren?\n\nWir müssen ihm folgen, wir müssen ihn finden!", rewards = "Armschienen des WegfindersFäustlinge des EntdeckersSchiftung des SpurenverwischersWegbeschreitergurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][11995] = {title = "In Sternenruh wird Eure Anwesenheit benötigt", objective = "Sprecht mit dem Abbild von Erzmagierin Modera in Sternenruh.", description = "<Klasse>, ich weiß, die Tuskarr werden Euch um viele Gefallen bitten, doch Ihr müsst so schnell wie möglich nach Sternenruh aufbrechen!\n\nDieser Aufruhr des Landes heute Morgen hat mit Sicherheit mehr Folgen, als nur den Einheimischen einige Unannehmlichkeiten zu bereiten.\n\nSternenruh liegt westlich der Kreuzung der Straße, die gen Norden aus dem Hafen hinausführt. Dort befindet sich Erzmagierin Modera. Sie wird euch erwarten.", progress = nil, completion = "Ich habe Euch erwartet, &lt;Klasse&gt;. Wir haben viel Arbeit vor uns, Ihr und ich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11996] = {title = "Eure Anwesenheit wird in Agmars Hammer verlangt", objective = "Sprecht mit dem Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer.", description = "<Klasse>, ich weiß, die Tuskarr werden Euch um viele Gefallen bitten, doch Ihr müsst so schnell wie möglich nach Agmars Hammer aufbrechen!\n\nDieser Aufruhr des Landes heute Morgen hat mit Sicherheit mehr Folgen, als nur den Einheimischen einige Unannehmlichkeiten zu bereiten.\n\nAgmars Hammer liegt westlich der Kreuzung der Straße, die gen Norden aus dem Hafen hinausführt. Erzmagier Aethas Sonnenhäscher höchstpersönlich wird Euch erwarten!", progress = nil, completion = "Was hat denn so lange gedauert? Die Zeit wartet nur auf Aspekte, &lt;Volk&gt;.\n\nWir haben viel Arbeit zu tun - Ihr und ich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11997] = {title = "REUSE", objective = "Sprecht mit Hauptmann Gryan Starkmantel im Lager der Westfallbrigade.Die Westfallbrigade ist in den nordöstlichen Teil der Grizzlyhügel beordert worden, um eine Passage für unsere Truppen ausfindig zu machen. Sie haben ein Basiscamp nordöstlich des Grauschlunds und südwestlich von Thor Modan errichtet.\n\nIhr kennt den Anführer der Brigade, Hauptmann Gryan Starkmantel, vielleicht als hochdekorierten Veteran des Kriegs gegen die Geißel in Lordaeron. Aber die Leute in Westfall ehren ihn wegen seiner Entscheidung, das Schlachtfeld zu verlassen und nach Hause zurückzukehren, um gegen die Defias zu kämpfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Die Westfallbrigade ist in den nordöstlichen Teil der Grizzlyhügel beordert worden, um eine Passage für unsere Truppen ausfindig zu machen. Sie haben ein Basiscamp nordöstlich des Grauschlunds und südwestlich von Thor Modan errichtet.\n\nIhr kennt den Anführer der Brigade, Hauptmann Gryan Starkmantel, vielleicht als hochdekorierten Veteran des Kriegs gegen die Geißel in Lordaeron. Aber die Leute in Westfall ehren ihn wegen seiner Entscheidung, das Schlachtfeld zu verlassen und nach Hause zurückzukehren, um gegen die Defias zu kämpfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11998] = {title = "Den Schlag abschwächen", objective = "Bringt Brugar Steinscher im Lager der Westfallbrigade ein Fässchen mit zum Heulen gutem Fusel.", description = "Die beste Chance, unsere Streitkräfte schnell zum Eiskronengletscher zu bringen, ist das Tunnelnetzwerk unter der uralten Stadt der Eisenzwerge namens Thor Modan.\n\nBrugar Steinscher und seine Jungs von der Forscherliga werden zwar nicht sehr erfreut darüber sein, aber Befehl ist Befehl.\n\nDie Neuigkeiten würden vielleicht sogar besser rüberkommen, wenn Ihr ihm ein Fässchen vom Fusel des Fallenstellers Hugh Glass mitbringen würdet. Jener hält sich südlich von hier beim Handelsposten von Rotholz an der Baumgrenze auf.\n\nDer Mann ist nicht ganz richtig im Kopf, aber 'nen besseren Fusel findet Ihr hier draußen nicht.", progress = "Was habt Ihr denn da?", completion = "Lasst mich das einmal klarstellen: Ein &lt;Volk&gt;, den ich nicht kenne, bringt mir ein Fässchen mit dem besten Alk, den es in diesem elenden Wald gibt. Okay, na dann, was wollt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][11999] = {title = "Leichenfleddern", objective = "Findet die Pläne der Mondruhgärten und bringt sie zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer.", description = "Die Mondruhgärten im Südwesten waren die letzte Ruhestätte einiger Hochgeborenen. Sie waren auch ein machtvoller Leyliniennexus.\n\nDer Blaue Drachenschwarm hat sich einer magischen Vorrichtung bedient, welche sie die Sognadel nennen, um diesen Nexus zu zerstören und die entfesselten Kräfte nach ihrem Willen nutzen zu können.\n\nIch brauche mehr Informationen und möchte, dass Ihr sie mir beschafft!\n\nNachdem das Land bei den Ruinen zerstört wurde, haben sich die Geister der Hochgeborenen erhoben und die anwesenden Magierjäger um die Hälfte dezimiert. Geht und durchsucht ihre Leichen nach Hinweisen.", progress = "Ihr seid zurückgekehrt. Was habt Ihr entdeckt?", completion = "Merkwürdig, sie streben ein Abkommen mit dem Astraleum an. Die Astralen könnten sich für Malygos und seinen Wahnsinn als machtvolle Verbündete erweisen.\n\nDas darf nicht geschehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12000] = {title = "Leichenfleddern", objective = "Findet die Pläne der Mondruhgärten und bringt sie zu Erzmagierin Modera in Sternenruh.", description = "Die Mondruhgärten im Südwesten waren die letzte Ruhestätte einiger adliger Elfen, von Hochgeborenen. Sie waren auch ein machtvoller Leyliniennexus.\n\nDer blaue Drachenschwarm hat sich einer magischen Vorrichtung bedient, welche sie die Sognadel nennen, um diesen Nexus zu zerstören und die entfesselten Kräfte nach ihrem Willen nutzen zu können.\n\nIch brauche mehr Informationen und ich hoffe, Ihr werdet sie für mich beschaffen.\n\nNach dem Aufruhr bei den Ruinen haben sich die Geister der Hochgeborenen erhoben und die anwesenden Magierjäger um die Hälfte dezimiert. Geht und durchsucht ihre Leichen nach Hinweisen.", progress = "Ihr seid zurück. Was habt Ihr entdeckt?", completion = "Merkwürdig, sie streben ein Abkommen mit dem Astraleum an. Die Astralen könnten sich für Malygos und seinen Wahnsinn als machtvolle Verbündete erweisen.\n\nDas darf nicht geschehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12001] = {title = "Jagdtarot: Geringe Bestien", objective = "Sammelt 12 zerrissene Felle und benutzt anschließend das Jagdtarot, um den Jäger herbeizurufen. Ihr könnt die zerrissenen Felle nur von Bestien der Stufe 5 oder höher erhalten.", description = "Als Ihr Euren Blick auf die Karte fixiert, fängt das Bild an zu verschwimmen, sich zu verändern, bis Ihr Euch schließlich selbst sehen könnt, bekleidet mit den Fellen vieler Wölfe und Bären. Das Einzige, was Ihr daraus schließen könnt, ist, dass dies Euer Schicksal sein müsste, falls Ihr die Macht des Tarots anrufen solltet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12002] = {title = "Brüder in der Schlacht", objective = "Tötet 10 Runenschlachtgolems und kehrt zu Brugar Steinscher im Lager der Westfallbrigade zurück.", description = "Ich hoffe, dass Gryan weiß, dass ich meine Männer aus Thor Modan zurückgezogen habe, als die Schlacht begann. Wir können dort einfach nichts ausgraben, bevor nicht Ruhe eingekehrt ist.\n\nIhr scheint mir allerdings von der tapferen Sorte zu sein, und Ihr besitzt das Vertrauen von Starkmantel.\n\nThor Modan befindet sich gleich im Nordosten, und die Schlacht zwischen unseren irdenen Brüdern und den Schöpfungen dieser verfluchten Eisenzwerge dauert noch an. Helft unseren Brüdern, das Kräfteverhältnis auszugleichen und ich werde versuchen herauszufinden, wie wir diese Ausgrabung von Thor Modan bewerkstelligt kriegen.", progress = "Wie stehen die Dinge in Thor Modan?", completion = "&lt;Brugar hört sich Euren Bericht an.&gt;\n\nHört sich fast so an, als würde sich die Lage langsam beruhigen. Wir werden beginnen, nach Eingängen zum Tunnelsystem der Eisenzwerge zu suchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12003] = {title = "Die Suche nach den Tunnels", objective = "Brugar Steinscher im Lager der Westfallbrigade möchte, dass Ihr das Nordgebäude, das Ostgebäude und das Südgebäude von Thor Modan untersucht.", description = "Wir fangen bei den abseits gelegenen Gebäuden an, nach dem Tunnelsystem zu suchen.\n\nAls ich das Gebiet mit meinen Männern verlassen habe, sah es so aus, als würden die Verteidiger der Eisenzwerge in den Gebäuden Schutz suchen. Seid vorsichtig, wenn Ihr sie untersucht.\n\nDie Eingänge zu den Tunnels werden wahrscheinlich hinten in den Gebäuden zu finden sein. Ich weiß zwar nicht genau, was Starkmantel dort zu finden erhofft, aber ich bezweifle, dass die Eisenzwerge die Suche besonders einfach machen werden.", progress = nil, completion = "&lt;Brugar gibt einen Schwall zwergischer Schimpfwörter von sich.&gt;\n\nKeine Eingänge? Kein einziger?\n\nWar ja klar, dass es nicht so einfach sein würde. Nun, ich denke, ein Streifzug durch die Stadt selber wird sich nicht vermeiden lassen. Meine Jungs werden nie an ihre eigentliche Arbeit zurückkehren können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12004] = {title = "Verhindert das Abkommen", objective = "Bringt Windhändler Mu'fahs Überreste und die Schuppen von Goramosh zum Abbild der Erzmagierin Modera in Sternenruh.", description = "Wir müssen zwei Fliegen mit einer Klappe schlagen, <Klasse> - und Ihr seid der Schläger.\n\nIn dem Fall sind unsere zwei Fliegen Windhändler Mu'fah und Goramosh. Sie sollten sich irgendwo in der westlichen Hälfte der Mondruhgärten aufhalten. Höchstwahrscheinlich befinden sie sich in dem größeren zweistöckigen Gebäude am Rande der Grube.\n\nIch hätte auch gerne einen Beweis ihres Ablebens, wenn es Euch nichts ausmacht.", progress = "Habt Ihr ein Abkommen zwischen dem blauen Drachenschwarm und dem Astraleum verhindern können?", completion = "Goramoshs Bemerkung, dass es bereits zu einer Absprache gekommen sei, bereitet mir Sorge.\n\nDennoch müssen wir uns erstmal um zwei Würmer weniger Gedanken machen. Widmen wir uns also wichtigeren Angelegenheiten.", rewards = "Gugel des Initianden der Kirin TorArmschienen des violetten JägersBeinschützer des AzurjägersKopfschutz der DalaranwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12005] = {title = "Verhindert das Abkommen", objective = "Bringt Windhändler Mu'fahs Überreste und die Schuppen von Goramosh zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer.", description = "Wir müssen zwei Fliegen mit einer Klappe schlagen, <Klasse> - und Ihr seid der Schläger.\n\nIn dem Fall sind unsere zwei Fliegen Windhändler Mu'fah und Goramosh. Sie sollten irgendwo in der westlichen Hälfte der Mondruhgärten sein. Höchstwahrscheinlich befinden sie sich in dem größeren zweistöckigen Gebäude, welches die Grube überblickt.\n\nUnd ich hätte gerne einen Beweis ihres Ablebens, wenn es Euch nichts ausmacht.", progress = "Habt Ihr ein Abkommen zwischen dem blauen Drachenschwarm und dem Astraleum verhindern können?", completion = "Schon gut, &lt;Klasse&gt;. Legt sie einfach dort vor Agmars Thron auf den Boden.\n\n\n\nNur Goramoshs Bemerkung, dass es bereits zu einer Absprache gekommen sei, bereitet mir Sorge.\n\nDennoch müssen wir uns erstmal um zwei Würmer weniger Gedanken machen. Widmen wir uns also wichtigeren Angelegenheiten.", rewards = "Gugel des Initianden der Kirin TorArmschienen des violetten JägersBeinschützer des AzurjägersKopfschutz der DalaranwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12006] = {title = "Rächt diese Gräueltat!", objective = "Tötet insgesamt 15 Magierjäger der Drachenöde, Mondruhpirscher, Zauberer der Sognadel, Fokushexer oder eine Kombination aus mehreren. Kehrt zu Ethenial Mondnacht zurück, sobald Ihr das erledigt habt.", description = "Diese sogenannten Magierjäger kamen hierher und zerstörten unsere Ruhestätte.\n\nVerschafft uns Genugtuung oder ich werde dafür sorgen, dass Eure Operationsbasis von den Geistern der Toten überrannt wird!", progress = "Irgendwie habe ich das Gefühl, dass Ihr noch nicht genug von diesen Schändern getötet habt!", completion = "Also gut, Ihr habt getan, worum ich Euch gebeten habe, wenn nicht noch mehr.\n\nIch danke Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12007] = {title = "Opfer müssen erbracht werden", objective = "Drakuru möchte, dass Ihr ihm das Auge der Propheten zum Kohlenbecken in Zeb'Halak bringt.\n\nIhr müsst Zim'bos Mojo einsammeln, um Drakurus Elixier dort benutzen zu können.", description = "Ich hab's, Mann!\n\nIm Norden auf der Ziggurat bei Zeb'Halak gibt's einen Steinkopf mit Rubinaugen. Eines davon is' das Auge der Propheten! Bring's zu der Kohlenpfanne dort und trink mein Elixier.\n\nFür mein Elixier wirst du wieder einmal etwas Mojo benötigen - dieses Mal vom Kriegsherrn Zim'bo.\n\nEs is' nich' schön, Zim'bo zu töten, aber er hat 'nen Blutschwur geleistet, Drak'Tharon zu verteidigen un' er hat versagt. Jetzt wird uns zumindest sein Mojo helfen, Drak'Tharon zurückzuerobern.", progress = "Hast du das Auge der Propheten, Mann?", completion = "Das isses, Mann!\n\nUn' es is' sogar noch wertvoller, als ich gehofft hab'. Das bringt sicher mehr Leuten Hoffnung in diesen dunklen Zeiten.\n\nJetzt bloß keine Zeit verlier'n. Lass uns ma' gucken, wo das nächste Artefakt versteckt sein könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12008] = {title = "Agmars Hammer", objective = "Reist nach Agmars Hammer in der Drachenöde und sprecht mit Oberanführer Agmar.", description = "Direkt östlich dieses Flüchtlingslagers befindet sich Agmars Hammer - ein Zeichen dessen, welch Stärke die Horde in der Drachenöde besitzt.\n\nZwar hege ich keine Zweifel daran, dass unsere Brüder und Schwestern von der Horde schon das Ergebnis unserer Versuche sehen können, mit denen wir die Taunka zum Anschluss an die Horde bewegen wollen, doch ungeachtet dessen möchte ich, dass die Erfolgsnachricht von Euch höchstpersönlich an Oberanführer Agmar überreicht wird.\n\nGeht nun, <Name>! Schnell wie der Wind! Ostwärts nach Agmars Hammer!", progress = nil, completion = "Während Ihr zweifellos anderswo für die Horde eingetreten seid, waren noch viel mehr mit der Erweiterung unseres Machtbereichs ins Landesinnere von Nordend beschäftigt. Selbst während wir hier noch sprechen, errichten unsere Streitkräfte Basen auf den gefrorenen Weiten dieses trostlosen Ödlands.\n\nWir haben die Geißel umzingelt. Der Sieg rückt näher, während sich unsere Armeen in Massen am Fuße Angrathars, der Pforte des Zorns, versammeln. Bald schon werden wir das Tor niederreißen und zur Eiskrone durchbrechen können.\n\nDoch es gibt noch viel Arbeit zu erledigen...\n\nZuerst müssen wir die Neruber aufhalten!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12009] = {title = "Tua'keas Krabbenfallen", objective = "Sammelt 8 von Tua'keas Krabbenfallen ein und bringt sie wieder zu ihm. Er befindet sich im Hafen Moa'ki.", description = "Wegen all der Probleme hab' ich alle meine Gehilfen verloren. Ich wollte nur einmal fragen, ob Ihr mir vielleicht helfen könnt?\n\nIch hab' überall hier im Wasser meine Krabbenfallen aufgestellt. Könntet Ihr sie mir zurückbringen? Ich bin zu alt für so etwas und die See kann sehr gefährlich sein.\n\nHier, bitte, nehmt diesen Atmungssack. Er wird Euch mit Luft versorgen, solange Ihr dort unten seid.", progress = "Wie viele Krabben habt Ihr denn mitgebracht?", completion = "Ich bin nur ein einfacher Fallensteller. Die Welt steht plötzlich Kopf. Es ergibt einfach keinen Sinn.\n\nIch hoffe, dass Ihr's wieder richten könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12010] = {title = "Das Schicksal Orlonds", objective = "Findet Feldmesser Orlond innerhalb Thor Modans.", description = "Als wir mit den Ausgrabungen begonnen haben, habe ich Feldmesser Orlond losgeschickt, die Stabilität der Tunnel in Thor Modan zu überprüfen. Ich habe ihn nicht entkommen sehen, als wir uns zu Beginn der Schlacht zurückzogen, und mache mir Sorgen, dass er noch immer in der Stadt gefangen ist.\n\nWenn wir eine Armee durch Thor Modan bewegen wollen, brauchen wir die Informationen, die er gesammelt hat. Starkmantel und seine Vorgesetzten würden mir die Haut abziehen, wenn eine Brigade unter den Tunneln begraben würde!", progress = nil, completion = "Eine kurze Untersuchung der Leiche ergibt, dass der Feldmesser schon geraume Zeit tot ist. In seiner Tasche findet Ihr einige handgeschriebene Notizen Orlonds.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12011] = {title = "Anzeichen großen wässrigen Ärgers", objective = "Informiert Tua'kea im Hafen Moa'ki über die zerstörte Krabbenfalle.", description = "Diese Krabbenfalle scheint von irgendwas zerstört worden zu sein, das viel größer ist, als die Haie, die in der Nähe umherkreisen.\n\nSollte Tua'kea, der Fischer im Hafen Moa'ki, vielleicht davon erfahren?", progress = nil, completion = "Das sind nicht gerade die Nachrichten, die ich hören wollte, &lt;Volk&gt;.\n\nNein, nein... es ist gut, dass Ihr's mir gesagt habt, doch ich befürchte, dass mein alter Erzfeind in diese Gewässer zurückgekehrt ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12012] = {title = "Den Urahnen benachrichtigen", objective = "Reist in eine der Hauptstädte und sprecht mit dem Urahnen des Irdenen Rings.", description = "Hiervon muss der gesamte Irdene Ring erfahren. Ich bin mir nicht sicher, wie es weitergehen soll, doch der Urahne, von dem Ihr überhaupt erst diese Aufgabe bekommen habt, könnte es wissen. Ich bitte Euch, kehrt zum Urahnen zurück und findet heraus, wie es weitergehen soll - wir müssen etwas unternehmen!", progress = "Was bedrückt Euch, mein Kind?", completion = "Das sind in der Tat schlimme Neuigkeiten. Wir müssen alles tun, was in unserer Macht steht, um diesen Krieg zu verhindern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12013] = {title = "Weg mit Arkanimus", objective = "Vernichtet Arkanimus und kehrt zu Ethenial Mondnacht bei den Mondruhgärten zurück.", description = "Es gibt eine letzte Sache, die Ihr für mich tun müsst, <Klasse>. Ich möchte, dass Ihr Arkanimus für mich vernichtet!\n\nDie Zauberer im Westen benutzten dieses riesige Gerät am Himmel, um eine enorme Grube in unsere Ruhestätte zu bohren. Als sie dies taten, ließen sie das Ungeheuer frei!\n\nEs würde mich nicht stören, wenn es nur die Lebenden etwas anginge, doch Arkanimus ernährt sich von den Geistern der Toten.\n\nIhr werdet dem jetzt ein Ende bereiten!", progress = "Haltet Ihr mich für einen Narren? Arkanimus frisst noch immer die Seelen meiner Brüder und Schwestern, <Klasse>!", completion = "Ihr habt meinen tiefsten Dank, &lt;Name&gt;.\n\nFalls nicht schon geschehen, solltet Ihr Eure Vorgesetzten über die Gefahr informieren, die der blaue Drachenschwarm entfesselt hat. Indem sie den Leylinienanker unter den Gärten zerstören, drohen sie, uns alle zu vernichten!", rewards = "Ausbleichende HandlappenVom Tode berührte StiefelKristallplattenschulterstückeAuf Euch wartet eine dieser Belohnungen:\n\nRing des Jenseits\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12014] = {title = "Fels in der Brandung?", objective = "Beschafft den tragbaren Seismographen und führt mit ihm Messungen durch, um die Stabilität in Thor Modan zu untersuchen. Kehrt anschließend zu Brugar Steinscher im Lager der Westfallbrigade zurück.", description = "Orlonds Aufzeichnungen deuten darauf hin, dass er einen Ausrüstungsgegenstand namens \"tragbarer Seismograph\" mitbrachte, doch das Gerät ist nirgendwo zu finden.\n\nDie Messwertaufzeichnungen zeigen, dass Orlond all seine Messungen in den Tunneln von Thor Modan durchführte, bis auf eine einzige, die mit der Aufschrift \"östliches Ende der freigelegten Tunnel\" gekennzeichnet ist.\n\nDer letzte Eintrag in dem Buch deutet darauf hin, dass Orlond versuchte, im Wasser Zuflucht zu finden, und von unterirdischen Dreschern angegriffen wurde. Womöglich haben sie seine Ausrüstung mitgenommen. Ihr müsst es wiederbeschaffen, bevor Ihr die letzte Messung durchführen könnt.", progress = "Was habt Ihr gefunden?", completion = "&lt;Brugar überfliegt den Bericht.&gt;\n\nDas ist gar nicht gut. Selbst wenn wir die Tunnel hinter der Blockade ausgraben könnten, hätten wir noch immer keine Garantie dafür, dass sie nicht einstürzen würden. Es sieht so aus, als wären ein paar dieser Bereiche seit Generationen nicht besucht worden. Wir werden Hauptmann Gryan die schlechten Neuigkeiten überbringen müssen.", rewards = "Verstaubte BergbauergamaschenHandgelenksschützer mit EktoplasmafleckenBesessener TaillenschutzSchockstahlschulterschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12015] = {title = "Test Quest for Craig", objective = "Craig Amai at wherever wants you to bring him 5 whatevers.", description = "klajsdklajlsdIhr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12016] = {title = "Der Köder", objective = "Besorgt das Fleisch von \"Zwei gewaltige Scheren\" und liefert es bei Tua'kea im Hafen Moa'ki ab.", description = "Ich bin mir sicher... dass unser uralter aquatischer Erzfeind Tu'u'gwar, \"Der mit dem Essen spielt\", zurückgekehrt ist. Wir, das heißt Ihr und ich, müssen ihm eine Falle stellen.\n\nWenn Tu'u'gwar eine Schwäche hat, dann ist das sein Magen. Es gibt eine Sorte Fleisch, zu der er sicherlich nicht Nein sagen könnte.\n\nKili'ua, \"Zwei Gewaltige Scheren\", die Mutter aller Krabben, lebt auf einer Insel gen Südwesten. Ihr müsst Ihr einen Besuch abstatten und mir ihr Fleisch bringen.", progress = "Habt Ihr Kili'uas saftiges Fleisch mitgebracht?", completion = "Wenn Ihr Kili'ua niederstrecken konntet... vielleicht könnt Ihr dann auch dasselbe mit Tu'u'gwar machen.\n\nVielleicht aber auch nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12017] = {title = "Fleisch am Haken", objective = "Streckt Tu'u'gwar nieder und kehrt anschließend zu Tua'kea im Hafen Moa'ki zurück.", description = "Die Zeit ist gekommen, <mein Freund/meine Freundin>: wir müssen uns um Tu'u'gwar kümmern!\n\nIch habe das Fleisch so präpariert, dass das Biest mit Sicherheit kommen wird, sobald Ihr den Haken draußen im Wasser mit einem Köder verseht. Folgt einfach der Angelschnur hier und Ihr werdet ihn finden.\n\nWas auch immer Ihr macht, Tu'u'gwar darf Euch auf keinen Fall verschlingen, <Name>!", progress = "Ich meine gesehen zu haben, dass das Wasser aufgewühlt wurde... Ist Tu'u'gwar tot?", completion = "Wir freuen uns über Euren Erfolg, mein junger Freund! Da schwimmt Blut im Wasser und es ist das Blut unseres Feindes!\n\nDieser alte Fischer wird Euch auf ewig dankbar sein und mit Sicherheit auch alle Kalu'ak, sobald ich die Neuigkeit verbreitet habe!\n\nHier, ich bestehe darauf - nehmt bitte etwas als Belohnung.", rewards = "Ohrenschützer des FischersDrescherhauttunika von Moa'kiBeinlinge des HaitauchersKrustentierstampferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12018] = {title = "Rache ist süß", objective = "Beschafft Euch 2 Gargoylekieselhaufen von Aasgargoyles von den östlichen Aasfeldern. Kehrt zu Lord Bevis zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Du da... Du siehst nach einem Kämpfer aus. Seit die Geißel meine Familie ermordet hat, gelüstet es mich nach Rache. Besorgt mir 2 Gargoylekieselhaufen, damit ich sie zu Boden schmettern und auf ihnen herumtrampeln kann, bis sie in klitzekleine Stücke zersprungen sind.\n\nLos. Geht. Tötet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12019] = {title = "Letzte Riten", objective = "Geht zur Tempelstadt En'kilah und sucht die Teleportationskugel unter der schwebenden Geißelzitadelle von Naxxanar. Benutzt sie, um ganz nach oben zu gelangen und helft dort Thassarian.", description = "Im Tod diente ich Arthas, denn ich hatte keine Wahl. Er hatte die Kontrolle über meinen Willen und meinen Körper. Die Mitglieder des Kults der Verdammten dienen Arthas als Lebende... aus freien Stücken.\n\nJetzt, da wir wissen, wie wir mit den Machtworten Naxxanar betreten, können wir dieser Kultistenseuche ein Ende bereiten. Geht nach En'kilah und sucht unter der schwebenden Zitadelle nach der Teleportationskugel.\n\nArbeitet Euch nach oben durch und trefft mich ganz oben. Bewaffnet Euch mit all Eurem Mut. Es kann sein, dass wir da nicht lebend rauskommen.", progress = "Gelobet seid Ihr, <Name>.", completion = "Ihr habt Euch gut geschlagen, &lt;Name&gt;. Ich hatte gehofft, meine Schwester vor alledem bewahren zu können. Dank Euch ist sie am Leben und wohlauf.\n\nMeine Pflicht gegenüber meinem König und meiner Armee ist getan. Es ist offensichtlich, dass ich unter meinen Kameraden nicht länger willkommen bin. Ich werde meinen eigenen Weg finden müssen, wo ich niemandes Kriege mehr schlage als meine eigenen und niemand anderem mehr folge als meinem Herzen.\n\nVielleicht sehen wir uns eines Tages wieder, &lt;Klasse&gt;. Bis dahin nehmt dies als Zeichen meiner Dankbarkeit.", rewards = "Axt des gefrorenen TodesBoreanischer ZerkracherTurm des unendlichen GeistesStab des entschlossenen BettelmönchsFuror des wütenden DrachenKlaue der einsamen SeeleIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12020] = {title = "Dieses eine Mal, als ich betrunken war...", objective = "Sprecht mit Boxi Bolzdreher im Braufestlager.", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Boxi und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", progress = nil, completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, &lt;Klasse&gt;, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Weiterhin noch viel Spaß auf dem Braufest.", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][12021] = {title = "Ein Brief in die Heimat", objective = "Bringt den Brief zu Lady Alustra in den östlichen Aasfeldern.Der Brief wurde offenbar von einem verstorbenen Dorfbewohner der Aasfelder an einen Einwohner Sturmwinds adressiert. Vielleicht ist einer der überlebenden Dorfbewohner im östlichen Lager gewillt, ihn zu seinem vorgesehenen Empfänger zu bringen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Brief wurde offenbar von einem verstorbenen Dorfbewohner der Aasfelder an einen Einwohner Sturmwinds adressiert. Vielleicht ist einer der überlebenden Dorfbewohner im östlichen Lager gewillt, ihn zu seinem vorgesehenen Empfänger zu bringen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12022] = {title = "Haut weg das Zeug!", objective = "Benutzt den Krug alkoholfreies Braufestbier, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxi Bolzdreher.", description = "He da! Ihr seht aus, als vertragt Ihr Euer Bier. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? \n\nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.\n\nEs ist ganz leicht, nehmt Euch einen der alkoholfreien Braufestbierkrüge und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.", progress = "Hebt einen zu Euch und werft dann einen zu Ihr. A.L.K. hält das aus, dafür habe ich sie ja gebaut.", completion = "Wisst Ihr, was das war? Gnomische Ingenieurskunst von ihrer besten Seite! A.L.K. hat das weggesteckt wie ein Champion!\n\nIch glaube Ihr seid jetzt bereit, wenn die Dunkeleisenzwerge das nächste Mal wieder auftauchen.", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][12024] = {title = "Die Gefallenen registrieren", objective = "Durchsucht die Skelette auf den Aasfeldern nach Siedlungsdokumenten der Allianz.", description = "Danke, dass Ihr gekommen seid, <Name>. Wir haben noch keine Kunde von der Feste Wintergarde erhalten. Sie kämpfen dort sicher noch immer gegen die Geißel, aber ich kann nicht glauben, dass sie uns einfach so unserem Schicksal überlassen haben.\n\nWir müssen die Namen der Gefallenen herausfinden, damit wir ihre Familien benachrichtigen können. Als uns das Militär der Allianz hierher gebracht hat, mussten wir alle unsere Siedlungsdokumente ausfüllen und stets bei uns tragen.\n\nDurchsucht die Leichen und bringt mir die Dokumente, die Ihr finden könnt, damit ich eine Namensliste anfertigen kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12025] = {title = "Ein Scharlachroter unter uns", objective = "Sucht bei den erst kürzlich auferstandenen Aasghule in der östlichen Gegend der Aasfelder nach Beweisen hinsichtlich des Scharlachroten Kreuzzugs. Bringt Lady Alustra alles, was Ihr finden könnt.", description = "Gut zu sehen, dass nicht auch Ihr von der Geißel entstellt wurdet. Vielleicht möchtet Ihr uns hier zur Hand gehen.\n\nDer Scharlachrote Kreuzzug hat im Norden Stellung bezogen, um offensichtlich die Geißel zu bekämpfen. Was mich jedoch beunruhigt, ist, dass sie schon mit dem Bau beschäftigt waren, bevor wir angegriffen wurden - sie müssen irgendwelche Informationen gehabt haben.\n\nIch muss unbedingt wissen, ob einer unserer Dorfbewohner darin verwickelt gewesen ist. Sucht bei denjenigen von uns, die als Ghule zurückgebracht wurden, nach Hinweisen. Egal was Ihr findet, bringt es mir.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12026] = {title = "Das beschädigte Tagebuch", objective = "Sammelt 8 der fehlenden Tagebuchseiten, ergänzt damit das Tagebuch und bringt der Weisen Paluna im Camp Oneqwah das vervollständigte Buch.", description = "Dieses abgenutzte, mit Matsch beschmutzte Tagebuch hat auch schon bessere Tage gesehen. Beim Durchblättern fallen Euch Dutzende von Notizen, Diagrammen und Abbildungen ins Auge.\n\nDas einzige Stück Text, das Ihr lesen könnt, ist ein Eintrag, der mit dem Namen Brann Bronzebart unterschrieben ist.\n\nDie hintere Hälfte des Buches, die die jüngsten Einträge enthalten hätte, ist abgerissen worden. Jemand hielt die Notizen für wichtig genug, um sie zerstören zu wollen. Wenn Ihr die fehlenden Seiten auf dem Schlachtfeld finden könntet, würden sie vielleicht brauchbare Hinweise liefern.", progress = "Was ist das, was Ihr da habt?", completion = "Wer ist dieser Brann Bronzebart? Die Eisenzwerge hatten keine Verwendung für ihn und ich verstehe nicht, warum wir ein Interesse an seinen Notizen haben sollten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12027] = {title = "Mr. Floppys gefährliches Abenteuer", objective = "Helft Emily und Mr. Floppy, den Weg zurück zum Lager der Westfallbrigade zu finden, dann sprecht mit dem Knappen Walter.", description = "Entschuldigt bitte, <mein Herr/meine Dame>, wisst Ihr den Weg zurück zum Soldatenlager?\n\nMr. Floppy und ich wollten einen Spaziergang im Wald machen und mein Bruder Walter sollte mit uns kommen, aber dann musste er Knappenaufgaben erledigen.\n\nAlso gingen Mr. Floppy und ich alleine, aber wir haben uns verlaufen und da war ein ganzer Haufen hungriger Wölfe. Da haben wir diesen Turm gefunden.\n\nDie Wölfe haben sich verzogen, aber wir wissen immer noch nicht, wo wir sind.\n\nIch habe Mr. Floppy gefragt, aber er weiß den Weg auch nicht. Würdet Ihr uns helfen? Bitte?", progress = nil, completion = "Dem Himmel sei Dank, dass Ihr Emmy gefunden habt! Als sie ohne mich losgezogen ist, habe ich mir große Sorgen gemacht.\n\nIch freue mich auch, dass Mr. Floppy wohlbehalten wieder zurück ist.", rewards = "TrampelpfadkordelStiefel der sicheren ReiseBeinschützer der unfehlbaren NavigationArmschienen des AufpassersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12028] = {title = "Spirituelle Eingebung", objective = "Sprecht mit Toalu'u dem Mystiker im Hafen Moa'ki, nachdem Euch die spirituelle Eingebung zuteil wurde.", description = "<Volk>, seitdem die Erde bebte und sich auftat, haben wir nichts mehr von unseren Leuten in Indu'le gehört!\n\nHabt Ihr schon einmal versucht, mithilfe einer Vision etwas in Erfahrung zu bringen? Ich meine, dass Loguhns Bezwinger auch dazu imstande wäre.\n\nIch werde Euch einen besonderen Weihrauch geben, den Ihr dann in meine Kohlenpfanne streuen müsst. Atmet seine Dämpfe tief ein und Euer Geist wird emporgehoben werden. Auf diese Weise könnt Ihr herausfinden, was sich in Indu'le ereignet hat.\n\nSolange Euer Geist frei dahinschwebt, werde ich durch Eure Augen blicken können.", progress = "Was denkt Ihr?", completion = "Geister und dahingestammelter Unsinn? Das kann nicht sein!\n\nWir brauchen mehr Rat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12029] = {title = "Die angesengte Geißel", objective = "Mack beim Granitquell möchte, dass Ihr seinen Grog benutzt, um 20 ausgemergelte Geißeltrolle in Drak'Tharon zu verbrennen.", description = "<hicks>... Muss diese Leischen verbrennen, bevor sie anfangen rumzuwandern.\n\nPapa hat immer gesagt, das Einzige, was schlimmer is', als 'nen Troll töten zu müssen, is', ihn zweimal töten zu müssen.\n\nSagt mal, <hicks>... wegen der Geißel, wir kommen nisch in die Trollfestung im Norden, bis diese Trolle 'n bisschen weniger geworden sind.\n\nWie wär's, wenn Ihr was von mei'm Grog hier nehmt und die Bastarde von ihrem Leid erlöst?", progress = nil, completion = "Gut gemacht!\n\n&lt;Mack lacht eine Weile hysterisch.&gt;\n\nOoch, jetzt kommt schon. Das war lustisch...&lt;Hick&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12030] = {title = "Mana'loa der Älteste", objective = "Sprecht mit der Statue vom Ältesten Mana'loa in Indu'le.", description = "Mein Volk...\n\n<Der Mystiker ist kurz davor zusammenzubrechen.>\n\nAls Euer Geist durch das Dorf flog, spürte ich, dass der Älteste Mana'loa Euch bemerkte. <Name>, er möchte mit Euch sprechen. Die Steinältesten gelten bei uns als Quell uralter Weisheiten und werden deswegen verehrt.\n\nDer Älteste muss helfen wollen. Ihr findet ihn in der nordwestlichen Ecke des Dorfes.", progress = nil, completion = "Ich habe Euch erwartet, &lt;Volk&gt;. Ich sah, wie Euer Geist vorbeiflog, und spürte den Blick des Mystikers in Euren Augen.\n\nEuer Schicksal und das der Kalu'ak sind nun eins.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12031] = {title = "Freiheit den Verweilenden", objective = "Erlöst insgesamt 15 Geister von Indu'le, egal ob Fischer, Mystiker oder Krieger, und kehrt anschließend zum Ältesten Mana'loa in Indu'le zurück.", description = "Der geheiligte Boden der Elfen im Westen wurde aufgerissen. Nun fließt ihre magische Energie übers Land und hinterlässt eine Spur der Verwüstung.\n\nDie Versuche des blauen Drachenschwarms, die Magie zu kontrollieren, stellen eine Gefahr für die Seelen der Kalu'ak dar.\n\nDie Energie kam aus den Tiefen des Sees. Für die meisten Dorfbewohner brachte sie den plötzlichen Tod und die Überlebenden trieb sie in den Wahnsinn.\n\n<Name>, Ihr müsst diese Geister von ihrer Qual erlösen, damit sie ihre Reise fortsetzen können. Lasst die Wahnsinnigen jedoch in Frieden; vielleicht werden sie eines Tages wieder zu Verstand kommen.", progress = "<Ältester Mana'loa durchschaut Euch. Er spürt, dass Ihr seinen Auftrag noch nicht ausgeführt habt.>", completion = "Nicht unbedingt die angenehmste Aufgabe, doch eine notwendige und gnadenvolle.\n\nDa wäre noch eine andere Sache, die Ihr für die Kalu'ak erledigen müsst und zu deren Erfüllung Ihr bestimmt seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12032] = {title = "Gespräche mit den Tiefen", objective = "Nehmt mithilfe der Perle der Tiefen Verbindung mit der Meeresgöttin Oacha'noa auf und tut, was sie befiehlt.\n\nKehrt zu Toalu'u dem Mystiker im Hafen Moa'ki zurück, falls Ihr die Feuerprobe bestehen solltet.", description = "Die Meeresgöttin Oacha'noa muss befragt werden. Nur sie wird wissen, welches Schicksal die Kalu'ak erwarten wird. Wisset auch, dass nur die Perle der Tiefen sie aus dem trüben Abyssal hervorlocken kann.\n\nVor der Südwestküste befindet sich die Salzzinne und auf ihr der Altar, auf dem auch die Perle liegt.\n\nNehmt am Altar mit Oacha'noa Verbindung auf und sie wird mit Sicherheit Eurem Ruf folgen. Tut, was sie verlangt, sonst werdet Ihr ihren Zorn auf Euch ziehen und damit auch das Ende aller Tuskarr einläuten.\n\nKehrt wieder zum Mystiker zurück, falls Ihr überleben solltet.", progress = "<Name>, Ihr seid zurückgekehrt!", completion = "Ihr habt mit Oacha'noa gesprochen?!\n\nNun, wenn es Ihr Wille ist, dass wir uns mit Eurem Volk verbünden sollen, dann soll es so sein. Ältester Ko'nani wird dies als unser Schicksal akzeptieren, ob zum Guten oder Schlechten.\n\nMein Volk glaubt, dass alle Seelen eins mit der Magie der Welt sind. Wir müssen die blauen Drachen davon abhalten, die Magie zu kontrollieren, oder wir sind verloren!\n\nIch hätte niemals gedacht, dass jemals ein &lt;Volk&gt; der Held der Kalu'ak sein würde, doch Ihr habt das Gegenteil bewiesen. Im Namen meines Volkes will ich mich bei Euch bedanken, &lt;Name&gt;.\n\nMöget Ihr die Gunst und den Schutz der Götter ernten.", rewards = "Kriegsstab der beißenden KälteVerzierter DrachenknochenstreitkolbenStab der stachelbewehrten BestieSchimmernde EisklingeGekühlter SchädelkracherImportierte eisenbeschlagene ArmbrustIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12033] = {title = "Nachricht aus dem Westen", objective = "Lest den Brief von Saurfang und zerstört ihn anschließend.\n\nSprecht mit Bote Torvus, sobald Ihr die Aufgabe abgeschlossen habt.", description = "<Torvus schüttelt Eure Hand und steckt Euch heimlich einen Brief zu.>\n\n<Torvus flüstert leise.>\n\nSpielt einfach mit, <Name>.\n\nSchön, Euch hier zu sehen, Soldat! Fürst Höllschrei hat Oberanführer Agmar zweifellos seine kräftigsten Krieger geschickt!\n\n<Torvus flüstert wieder.>\n\nLest ihn und werft ihn danach in den Feuerkrug neben mir.", progress = "Wir werden die Geißel vernichten!", completion = "&lt;Torvus nickt Euch zu.&gt;\n\nHaben wir uns also verstanden? Ich werde zu meinem Fürsten zurückkehren und ihm sagen, dass Ihr eingewilligt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12034] = {title = "Der Sieg ist nahe...", objective = "Sprecht mit Schlachtrufer Juktok in Agmars Hammer.", description = "Die wahre Bedrohung geht jetzt nur noch von zwei Orten aus: der Schreckenszitadelle Naxxramas, die weit im Osten über der Allianzfestung Wintergarde schwebt, und der Grube von Narjun, durch welche die untoten Armeen von Azjol'Nerub an die Oberfläche gelangen. Es war auch genau diese Grube, aus der die Neruber der Anub'ar kamen, als sie das Taunkadorf Eisnebel angriffen und es letztendlich dem Erdboden gleichmachten.\n\nWir werden die Anub'ar vernichten und die Grube von Narjun zuschütten.\n\nMeldet Euch bei Schlachtrufer Juktok; er wird Euch über Einzelheiten informieren.", progress = nil, completion = "Zu Land und aus der Luft - so werden wir der Bedrohung durch die Anub'ar ein Ende setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12035] = {title = "Wiederverwertung von Technologie", objective = "Jeremias Hohning in Fernhain möchte, dass Ihr 5 Erntesammler zerstört und dann Jeremias' Werkzeuge benutzt, um sie neu zu verkabeln.", description = "Okay, ich hab's! Die Neuverkabelung ist etwas kompliziert, aber nichts, was <ein cleverer/eine clevere:c> <Klasse> wie Ihr nicht hinbekommen würde.\n\nNehmt meine Werkzeuge und setzt ein paar der Erntesammler außer Betrieb. Wenn das erledigt ist, benutzt die Werkzeuge, um alle roten Drähte in die blauen Buchsen zu stecken. Dadurch werden sie in den Selbstverteidigungsmodus übergehen. Beeilt Euch, <Name>. Nicht mehr lange und es wird nicht mehr viel zu retten übrig sein.", progress = nil, completion = "Gute Arbeit! Ich fühle mich endlich wieder nützlich... und das soll was heißen.", rewards = "Verwitterter ArbeiterumhangStiefel des MarschenläufersHandbedeckung der WestklammGroßfelsbeinplattenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12036] = {title = "Aus den Tiefen von Azjol-Nerub", objective = "Erforscht die Grube von Narjun und kehrt anschließend mit dem, was Ihr gefunden habt, zu Schlachtrufer Juktok in Agmars Hammer zurück.", description = "Die untoten Neruber, die Eisnebel angriffen, kamen aus einem gigantischen Schlundloch, das \"die Grube von Narjun\" genannt wird. Wenn sich niemand um sie kümmert, werden diese Scheusale unseren Truppen an der Pforte des Zorns in die Flanke fallen und unserem Siegeszug ein jähes Ende bereiten.\n\nIch brauche Späher vor Ort, <Name>. Geht nach Westen und untersucht die Grube von Narjun. Wir müssen ihren Hauptausgang finden und ihn versiegeln! Findet heraus, wo er sich befindet.", progress = nil, completion = "Dieses verdammte Schlundloch muss direkt mit Azjol-Nerub verbunden sein. Es ist schlimmer als ich dachte.\n\n&lt;Juktok hält einen Moment lang inne, um nachzudenken.&gt;\n\nSuchen und vernichten... So wird unsere nächste Vorgehensweise aussehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12037] = {title = "Rettungsaktion", objective = "Mack beim Granitquell möchte, dass Ihr nach Drak'Tharon geht und herausfindet, was mit Kurzel passiert ist.", description = "Orcs... die hör'n einfach nich' zsch... zsch... zu... <Hick>! Wisst Ihr, was ich mein', <Volk>?\n\nKurzel is' schon seit Jahr'n bei uns. Man sollte denk'n, sie hätte mittlerweile begriff'n, wie die Dinge bei uns ablauf'n. Lock die Narren für die gefährliche Arbeit her, dann greif die Beute ab, wenn die Gefahr vorüber is'. Was is' daran scho schwer zu versteh'n?\n\nSie versteht's nich'... die läuft losch und will die Sache selbscht inne Hand nehmen. Wahrscheinlich isse schon tot, aber ich würd' mich schrecklich fühlen, wenn wir ihr nicht folgen würd'n... nur bin ich in keiner Verfassung dazu... <Hick>!\n\nAlso, was sagt Ihr, Kumpel?", progress = nil, completion = "Ich wusste es!\n\nSelbscht, nachdem ich eine Weile verschwunden war, sind mir diese rückgratlosen Ratten nich' nachgekomm'n.\n\nNun, sie ham Euch gesandt. Das is' immerhin etwas, denk' ich…\n\nHier, nehmt das. Es is' mir lieber, dass Ihr's kriegt als diese Schwachköpfe im Lager.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKurzels AngstKurzels ZornKurzels Kriegsband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12038] = {title = "Die angesengte Geißel", objective = "Mack am Granitquell möchte, dass Ihr seinen Grog nehmt und 30 ausgemergelte Geißeltrolle in Flammen aufgehen lasst.", description = "Worauf wartet Ihr, <Klasse>? Diese verseuschten Trolle bring'n sisch nisch selbst um!\n\nIhr wischt ja, worum's geht. Geht zur Feschde Drak'Tharon im Norden. Nehmt ein bisschen von dieschem Grog un' werft ihn nach ihnen aus sischerer Dischtanz…<hick>. Un' dann einfach surückleh'n und suguck'n, wie se in Flamm'n aufgeh'n.", progress = "Na, die Geißel versengt, <Name>?", completion = "Gut gemacht!\n\n&lt;Mack lacht einen Moment lang hysterisch.&gt;\n\nOh, na kommt. Dasch hat Spaß gemacht…&lt;hicks&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12039] = {title = "Das schwarze Blut von Yogg-Saron", objective = "Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 10 Proben des schwarzen Blutes von Yogg-Saron beschafft.", description = "Angrathar, die Pforte des Zorns... Ich sah, wie die Metallstreben des Tores pulsierten und zu schwingen begannen, als wären sie lebendig! In meinen 50 Jahren habe ich noch nie Metall \"atmen\" sehen.\n\nDie Einzigen, die etwas darüber wussten, waren die Tuskarr. Sie nannten es \"das schwarze Blut von Yogg-Saron\" und meinten, dass ich mich davon fernhalten solle.\n\nWestlich außerhalb von Eisnebel gibt es ein Schlundloch namens \"die Grube von Narjun\". Ich hörte, dass die Schlundlöcher reich an diesem seltsamen Erz seien. Könntet Ihr versuchen, mir ein paar Proben zu besorgen, falls Ihr in diese Richtung gehen solltet?", progress = "Was wäre das Leben, wenn man kein Risiko einginge?", completion = "Es ist so leicht... als würde es nichts wiegen! Ich brauche etwas Zeit, um das Metall zu analysieren und um zu sehen, ob ich es irgendwie verwenden kann! Tests! Ich muss ein paar Tests machen!\n\nIch werde von mir hören lassen, &lt;Name&gt;. Falls sich irgendwas ergeben sollte, dann werdet Ihr als Erster davon erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12040] = {title = "Arthas zum Feinde", objective = "Kilix der Entwirrer in der Grube von Narjun in der Drachenöde möchte, dass Ihr 6 Unterfürsten der Anub'ar tötet.", description = "Wir befinden uns mitten im Bürgerkrieg. Im Herzen dieser Welt kämpfen meine letzten lebenden Artgenossen gegen die totale Vernichtung an. Der Lichkönig will das Königreich von Azjol-Nerub um jeden Preis in seine Gewalt bringen. Diejenigen, die dagegen sind, werden zu Feinden der Geißel erklärt und zum Tode verurteilt.\n\nArthas ist unser beider Feind...\n\nSchließt Euch uns an und befreit diesen Ort von den Anub'ar! Anub'arak selbst soll ihre quälenden Todesschreie hören!", progress = "Das Reich Azjol wird wieder erblühen!", completion = "Es gibt noch Tausende ihrer Art und sie ergießen sich wie eine Flut aus jedem dunklen Spalt, den es in Nordend gibt. Ihr alleine habt keine Chance, doch zusammen... Zusammen vielleicht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12041] = {title = "Das verlorene Reich", objective = "Liefert Kilixs Schlachtplan bei Oberanführer Agmar im östlichen Agmars Hammer ab.", description = "Ihr habt gezeigt, dass Ihr bereit seid, dem Reich Azjol in Zeiten der Not beizustehen; aus diesem Grund wird das Reich Azjol der Horde seine Unterstützung zusichern.\n\nNehmt diese Schriftrolle hier und bringt sie zu Eurem Anführer. Darin beschrieben stehen die Stärken und Schwächen der Neruber, die für die Angriffe auf Eisnebel verantwortlich sind. Betrachtet es einfach als Zeichen unseres guten Willens - die Bereitschaft, Eurem Volke zur Hand zu gehen. Nutzt das Wissen auf diesen Seiten und vernichtet die Anub'ar. Tut dies und Ihr habt uns allen einen großen Dienst erwiesen.\n\nLebt wohl, <Volk>.", progress = "Was habt Ihr da in Eurer Hand?", completion = "&lt;Oberanführer Agmar überfliegt das Schreiben.&gt;\n\nIst es das, von dem ich denke, dass es das ist? Mit dem Wissen, das darin geschrieben steht, werden wir den Ansturm der Anub'ar ZERSCHLAGEN!\n\nEs war eine gute Entscheidung, mir dieses Schreiben zu bringen, &lt;Name&gt;. Womöglich wird es Euch gestattet sein, der letzten Schlacht bei Angrathar beizuwohnen oder sogar daran teilzunehmen! LOK'TAR!", rewards = "Sattelgurt des EiswüstenhauchsHandschuhe des SchneewehenhäschersEisscherbindungenSabatons des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12042] = {title = "Das Herz der Uralten", objective = "Drakuru möchte, dass Ihr zur höchsten Kammer beim Holzfällerposten Blauhimmel geht und dort nach dem Herz der Uralten sucht.", description = "Geheimnisse der Zeitalter, offenbart euch mir jetzt!\n\n<Drakuru schaut durch das Auge der Propheten.>\n\nAah, glorreich is' meine Zukunft, <Name>. Du hast Glück, mich zu kennen…\n\nDa! Ich seh's, Mann. Das Herz der Uralten. Das war zu einfach!\n\nDu findest das Herz in der Nähe von 'ner Goblinleiche östlich von hier. Sie is' oben in 'ner Kammer, in der Nähe eines Flusses aus zerbrochenen Bäumen.\n\nBeeil dich, Mann, bevor es jemand anderes findet!", progress = nil, completion = "Dieser unglückliche Goblin hat anscheinend das Herz während der Ausgrabungen in der Gegend aus der Erde geholt.\n\nEr hatte eindeutig keine Ahnung, was er dort gefunden hat.\n\nIhr kommt zu dem Schluss, dass es während des Chaos damals übersehen worden ist.", rewards = "Ihr bekommt:\n\nHerz der Uralten"}
MultiLanguageQuestData['de'][12043] = {title = "Verteidigung von Düsenrost", objective = "Tötet 12 Buddler der Weiten und 1 Zuchtmeister der Weiten, die sich in den Ausgrabungsorten um Galakronds Ruhestätte herum befinden. Kehrt anschließend zu Narf im Düsenrostposten zurück, sobald die Aufgabe erledigt ist.", description = "Ihr da, <Klasse>! Diese Untoten südlich von uns belästigen ständig unsere Arbeit. Nun geht schon und räumt sie aus dem Weg.", progress = "Hä? Wer seid Ihr? Was wollt Ihr?", completion = "Oh! Ja, die Untoten. Hier ist Eure Bezahlung - nun trollt Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12044] = {title = "Aufstockung", objective = "Geht zu den Ausgrabungsorten, die sich um Galakronds Ruhestätte herum befinden, sammelt 8 Ladungen Kompositerz und bringt sie anschließend zu Xink im Düsenrostposten.", description = "Aber hallo! Die Diener der Geißel graben im Süden irgend so ein uraltes Drachending aus. Mir könnte es eigentlich völlig egal sein, aber die holen dabei auch Karrenladungen voll mit Kompositerz aus dem Boden.\n\nGeht und klaut mir ein wenig von dem Erz. Angesichts der vielen Waffen, die von der Horde hergestellt werden, sollte ordentlich was dabei rausspringen.", progress = "Habt Ihr das Erz dabei? Mein Träger wird bald zurück sein - wir müssen diese Lieferung verschicken, solange der Kampf noch tobt!", completion = "Ha! Das ist ziemlich viel! Wie geht es Eurem Rücken?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12045] = {title = "Eiskristalle", objective = "Sammelt 4 Eissplitterklumpen von den Eiselementaren gen Norden und bringt sie zu Zivlix im Düsenrostposten.", description = "Ich habe Euch noch nie zuvor gesehen... Seid Ihr neu in der Schlucht? Freut mich, Euch hier zu haben. Ein paar mehr helfende Hände kann ich immer gut gebrauchen.\n\nMachen wir's so: Ihr beschafft mir die Materialien, ich stelle meine Maschine fertig, dann verkaufen wir das Zeugs an diese Befehlshabertypen und alle gehen reich nach Hause.\n\nIch habe die meisten der Hauptkomponenten hier, also brauche ich nur noch ein paar der Materialien für die Waffe selbst. Narf hat gemeint, dass die gezackten Eissplitter dieser Elementare gen Norden die perfekten Schrapnelle für meine Bomben wären. Geht und holt mir ein paar, ok?", progress = "Habt Ihr die Splitter? Ich bin schon fast fertig mit der Hauptkühlungseinheit.", completion = "Ausgezeichnet! Sie sind sogar schärfer als erwartet. Ich werde sie erst einmal in den Schnee stecken und sie solange dort lassen, bis die Bombe fertig ist.\n\nNa dann sehen wir mal... Was kommt als nächstes dran...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12046] = {title = "Weiches Hüllenmaterial", objective = "Sammelt 12 dünne Tierbälge von den Jormungartunnelgräbern oder den Drachenknochenkondoren in der Nähe des Düsenrostpostens und bringt sie anschließend zu Zivlix.", description = "Meine Schrapnellbomben brauchen neues Hüllenmaterial. All das Zeug hier ist zu hart und die Schrapnelle werden bei der Explosion nicht richtig verstreut.\n\nWas wir brauchen ist richtig dünner Tierbalg. Die Jormungartunnelgräber im Westen würden womöglich geeignete Bälge hergeben... oder vielleicht auch die Kondore, die bei den Drachenknochen nach Essbarem suchen. Geht und bringt mir, was auch immer sich finden lässt.", progress = "Läuft die Jagd gut? Habt Ihr meine Bälge dabei?", completion = "Gut... gut... die hier sollten genügen. Die Schrapnellbomben sind fast fertig.\n\nHalt... was ist mit meinen Eissplittern passiert? Narf hat mir gesagt, dass die Splitter von diesen Elementaren verzaubert sein sollen, doch sie schmelzen genauso wie die Dinger, die von Narfs grimmiger Visage hängen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12047] = {title = "Etwas, das nicht schmilzt", objective = "Sucht inmitten der Drachenknochen östlich des Düsenrostpostens nach 12 zersplitterten Knochenstücken.", description = "Nein, nein, nein! Diese Eissplitter funktionieren überhaupt nicht! Sie schmelzen, bevor sie überhaupt irgendwelchen Schaden anrichten. Das war das letzte Mal, dass ich auf Narfs Meinung in Sachen Materialien vertraut habe. Das bedeutet, dass wir irgendwas ganz anderes zur Herstellung des Schrapnells benötigen.\n\nIch hab's! Ich bin genial - Knochensplitter.\n\nHier liegen überall Knochen herum, an denen die Jormungar ziemlich gründlich herumgenagt haben. Seht einmal nach, ob Ihr mir nicht einen zersplitterten Knochen finden könnt, den ich gebrauchen kann.", progress = "Konntet Ihr irgendwelche Splitter finden?", completion = "Ausgezeichnet! Mehr brauche ich nicht, um die neuen Bomben austesten zu können. Einen Moment, ich werde das hier mal austesten!", rewards = "Lichtbrechende SchulterpolsterHyperamplifizierte NaturlederwesteGestraffte KettenstiefelAuf Euch wartet eine dieser Belohnungen:\n\nAutomatischer WaffenbeschichterDonnerkondensator\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12048] = {title = "Waffen der Geißel", objective = "Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 8 Waffen der Geißel bringt.", description = "Aus diesem verdammten Erz lässt sich nichts gewinnen. Es will einfach nicht zusammenhalten! Ich habe alles versucht, doch das Metall der Geißel lässt sich nicht verbiegen!\n\nWenn ich vielleicht ein paar Proben von den Waffen der Geißel hätte, wäre ich vielleicht dazu in der Lage, den Schmiedeprozess zurückzuverfolgen und sie gleichzeitig auseinanderzunehmen.\n\nEisnebel wimmelt nur so von gepanzerten Nerubern der Geißel. Geht dorthin und beschafft mir ein paar ihrer Waffen! Mit Eurer Hilfe könnte ich vielleicht sogar etwas aus diesem Erz machen.\n\nEisnebel liegt im Westen.", progress = "<Borus pfeffert seine Werkzeuge auf den Boden.>\n\nDie sind nutzlos!", completion = "Diese hier befinden sich in einem ausgezeichneten Zustand, &lt;Name&gt;. Ich werde mich sofort an die Arbeit machen. Wenn daraus irgendwas werden soll, dann werdet Ihr es als Erster erfahren!", rewards = "Gamaschen des EiswüstenhauchsBeinlinge des SchneewehenhäschersHelm aus Anub'architinBrustschutz des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12049] = {title = "Schwer zu schlucken", objective = "Kämpft so lange gegen einen bulligen Jormungar östlich des Düsenrostpostens, bis er sein Maul öffnet, um dann eine potente Sprengladung hineinzuwerfen. Sammelt, nachdem er explodiert ist, 6 Stücke verbranntes Jormungarfleisch vom Boden auf und bringt sie zu Xink.", description = "Die Truppen werden sich sicherlich die Bäuche vollstopfen wollen.\n\nIch werde Euch in ein kleines Geheimnis einweihen, das <ein zart Besaiteter/eine zart Besaitete:r> <Volk> wie Ihr niemals wissen könnte... diese Jormungarwürmer schmecken nämlich wie Hühnchen.\n\nGeht nach Osten und fordert einen dieser riesigen, bulligen Jormungar heraus. Es ist eher unwahrscheinlich, dass Ihr dazu in der Lage sein werdet, einen von ihnen so mir nichts, dir nichts zu töten - wartet also, bis er sein Maul weit aufsperrt und werft das hier seinen Rachen hinunter. Bringt mir so viele Fleischstücke, wie Ihr nur schleppen könnt.", progress = "Habt Ihr alles bekommen? Ihr stinkt zweifellos danach.", completion = "Ha, ha! Eins der Fleischstücke ist genau hier drüben gelandet! Saubere Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12050] = {title = "Holz hacken", objective = "Ruft mithilfe von Xinks Schreddersteuerung einen Schredder, sobald Ihr das Nistgebiet der Harpyien im Norden erreicht habt. Sammelt 50 Bündel Nutzholz von den Bäumen in der Gegend und kehrt anschließend zu Xink im Düsenrostposten zurück.\n\nWendet Euch an Xink im Düsenrostposten, falls Ihr Xinks Schreddersteuerung verlieren solltet, um eine neue zu erhalten.", description = "Als nächstes müssen wir etwas Holz für all die im Bau befindlichen Türme der Allianz beschaffen. Im Süden gibt es einige dünne Bäume, doch die Bäume im Norden, auf denen die Harpyien nisten, sehen so aus, als wären sie ein viel besseres Baumaterial für Gebäude.\n\nNehmt die Steuerung hier. Benutzt sie, wenn Ihr im Nistgebiet der Harpyien seid, und einer meiner Schredder wird zu Euch kommen. Sammelt so viel Holz, wie er nur tragen kann. Die Harpyien werden sicherlich damit nicht einverstanden sein, dass Ihr deren Zuhause fällt - kümmert Euch also um sie, falls nötig.\n\nLos, ran ans Holz!", progress = "Wo ist die Lastenmaschine? Hoffe, die Jormungar haben sie nicht erwischt. Sie hatte diesmal eine ziemlich große Ladung dabei.", completion = "Wenn ein Baum im Wald umfällt und Ihr wegen der Sägerei nichts hören könnt, macht er dann ein Geräusch?", rewards = "Kratzstange aus KaltwindEnergieerfüllter DrachenknochensplitterKompositstab aus HarpyienrückgratenReaktive KriegsaxtKompaktes Utensil zur explosiven HeimzahlungAufmontierter KnochenschredderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12051] = {title = "Ein paar Federn rascheln lassen", objective = "Narf im Düsenrostposten möchte, dass Ihr 20 Harpyien nordwestlich des Düsenrostpostens tötet.", description = "Diese Harpyien haben unsere Profite schon lange genug beeinträchtigt! Tötet sie alle.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12052] = {title = "Nimm das, Harpyie!", objective = "Tötet die Meisterin des Kaltwinds und 15 Kaltwindharpyien in den Bergen nordwestlich des Düsenrostpostens. Kehrt zu Narf zurück, sobald die Aufgabe erledigt ist.\n\nSprecht mit Xink im Düsenrostposten, falls Ihr seine Schreddersteuerung benötigen solltet.", description = "<Klasse>, habt Ihr das gesehen? Das ist die Harpyie, die den Überfall auf unsere Lieferungen zur Pforte angeführt hat! Ich hab' sie schon einmal gesehen: im hinteren Teil der Kaltwindanhöhen.\n\nDiese Harpyien haben unsere Profite schon lange genug beeinträchtigt! Tötet sie alle.", progress = "Ich erinnere mich an Euch. Ihr seid nicht tot - doch diese Harpyienweiber werden es wohl besser sein.", completion = "Das sollte diese Scheusale eines Besseren belehren. Hier... nehmt Eure Belohnung und macht, dass Ihr davonkommt.", rewards = "Fabelhaftes hüftwärmendes BandNarfs explosionsfester FadenGezackter KettenverbundExperimenteller AllzweckgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12053] = {title = "Die Macht der Horde", objective = "Schlachtrufer Juktok in Agmars Hammer in der Drachenöde möchte, dass Ihr die Schlachtstandarte des Kriegshymnenklans in Eisnebel aufstellt und sie gegen alle Angreifer verteidigt.\n\nBringt die Schlachtstandarte des Kriegshymnenklans wieder zurück, wenn Ihr die Aufgabe abgeschlossen habt.", description = "Die Taunka sind zu unseren Waffenbrüdern geworden - wir müssen ein Zeichen der Solidarität setzen und Eisnebel zurückerobern.\n\nDas Dorf befindet sich am Fuße der Berge westlich von Agmars Hammer. Macht Euch auf den Weg dorthin und fordert die Neruber der Anub'ar zum Kampfe heraus! Rammt unser geliebtes Banner der Horde in den Boden, sobald Ihr dort angelangt seid, und vernichtet all diejenigen, die es wieder niederreißen möchten!\n\nDie Anub'ar sollen die wahre Macht der Horde spüren! Möge unsere Schlachtstandarte das Letzte sein, das sie vor dem Tode sehen werden!", progress = "Es ist nicht einfach, <Name>!", completion = "Wir haben den Sieg zu Land errungen! Und bald werden wir ihn auch in der Luft erringen!", rewards = "Gesegnete Handlappen des SpitzenreitersStiefel des SchneewehenhäschersGürtelbund des WestwindsStulpen des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12054] = {title = "Das Tagebuch entschlüsseln", objective = "Bringt der Weisen Paluna in Camp Oneqwah einen Geisteratemzweig.", description = "Vor'takh hat Recht... Wir können uns diese Gelegenheit nicht durch die Lappen gehen lassen.\n\nZum Glück weiß ich, wie wir das Tagebuch dieses Branns übersetzen könnten.\n\nDie Schamanen der Rotfangfurbolgs, die sich am Schrein des Herzensblutes südlich des Lagers versammeln, pflanzen ein Kraut mit Namen 'Geisteratem' an. Ein erfahrener Mystiker kann daraus einen Weihrauch herstellen, mit dessen Hilfe er sich die Weisheit der Geister der Vorfahren zu Nutze machen kann.\n\nDie Gärten der Schamanen sind ein wohl gehütetes Geheimnis; doch sucht den Schamanen namens Grumbald Einauge auf - er sollte das Kraut bei sich tragen, da er es für seine Opfergaben an Ursoc benötigt.", progress = "Habt Ihr genug von dem Kraut mitgebracht?", completion = "Gut gemacht, &lt;Name&gt;. Ich werde das Rauchwerk vorbereiten und dann werden wir sehen, was genau dieser königliche Zwerg so weit von zu Hause gemacht hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12055] = {title = "Ein seltsames Gerät", objective = "Bringt Goramoshs seltsames Gerät zum Abbild der Erzmagierin Modera in Sternenruh.", description = "Ihr seid Euch sicher, als Ihr das seltsame Gerät aufhebt, dass es von magischer Natur ist. Leider scheint es keinen erkennbaren Nutzen aufzuweisen.\n\nWomöglich weiß die Erzmagierin in Sternenruh östlich der Mondruhgärten mehr darüber.", progress = "Was habt Ihr denn da?", completion = "&lt;Name&gt;, wenn ich mich nicht täusche, habt Ihr den Schlüssel entdeckt, mit dessen Hilfe wir die Absichten der Magierjäger genau erkennen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12056] = {title = "Zum Tode verurteilt: Hochkultist Zangus", objective = "Tötet Hochkultist Zangus und bringt den Kopf des Hochkultisten Zangus zu Hauptmann Gort in Agmars Hammer in der Drachenöde.", description = "Ich habe mit eigenen Augen beobachten können, wie er uns verriet! Der Verräter hat einen Angriff der Anub'ar auf diese Festung geleitet, bei dem einige meiner besten Soldaten ums Leben kamen.\n\n<Gort schüttelt den Kopf.>\n\nEr hat die ganze Zeit über gemeinsame Sache mit der Geißel gemacht und wir haben davon nichts gewusst! Wie viele Verräter wie Zangus gibt es denn? Wir werden sie alle finden und wenn wir sie haben...\n\n<Gort macht mit seinem Finger eine Bewegung, als durchschneide er seine Kehle.>\n\nErster auf der Liste ist Zangus. Unsere Späher berichten mir, dass er sich in der Grube von Narjun gen Westen verstecken soll. Findet ihn, tötet ihn und bringt mir seinen Kopf.", progress = "Ist da der abgetrennte Kopf eines Orcs in Eurem Rucksack oder seid Ihr bloß froh, mich zu sehen?", completion = "&lt;Gort hält den Kopf hoch und starrt in seine toten Augen.&gt;\n\nIch hab' dir gesagt, dass wir dich erwischen würden...\n\nHier ist Eure Belohnung, &lt;Klasse&gt;. Damit hätten wir eine Sorge weniger, die uns Kopfschmerzen bereitet hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12057] = {title = "Der fleischgebundene Foliant", objective = "Bringt Hauptmann Gort in Agmars Hammer den fleischgebundenen Folianten.", description = "Der Foliant ist in Fleisch eingebunden und es scheint, als würde er bluten. Nach näherer Betrachtung entdeckt Ihr unzählige Seiten, die über und über mit seltsamen blutigen Symbolen beschriftet sind.\n\nWelches Wissen auch immer in diesem Folianten enthalten sein mag, es könnte von Bedeutung sein. Bringt ihn zurück zu Hauptmann Gort in Agmars Hammer östlich von Eisnebel.", progress = "<Gort hebt eine Braue.>", completion = "&lt;Gort nimmt den Folianten an sich.&gt;\n\nBarbaren... In Orcfleisch eingebunden... Diese Sprache... Dass sie wirklich existiert, wurde jedoch niemals bestätigt. Es ist die Sprache des Todes... die Zunge der Geißel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12058] = {title = "Die Runenprophezeiungen", objective = "Die Weise Paluna im Camp Oneqwah möchte, dass Ihr die drei Runenplatten entziffert.", description = "Branns Tagebuch enthält auch eine Legende für die Symbole der Eisenzwerge. Ich habe sie auf einen Schlüsselstein übertragen, der Euch beim Verstehen der Inschrift auf den Runenplatten helfen wird.\n\nLaut seinen Tagebucheinträgen scheint es, als suche Brann Hinweise auf die Herkunft seines Volks. Haltet Eure Augen nach jedem Hinweis auf seinen Aufenthaltsort offen.\n\nKehrt nach Thor Modan zurück, nordöstlich von hier, stellt Euch vor jede der Platten und verwendet den Stein, um ihren Inhalt zu bestimmen. Die Allianz darf ihn nicht vor uns finden.", progress = "Habt Ihr Thor Modans Geheimnisse enthüllt?", completion = "&lt;Die Weise Paluna hört Euch zu, als Ihr die Übersetzung der Platten wiederholt.&gt;\n\nAlso glaubt Brann, eine neue Titanenstadt entdeckt zu haben?\n\n\"Die Wiege von Stein und Eisen.\"\n\n\"Ulduar schmiegt sich in den Sturm.\"\n\nIch werde den Häuptling bitten, Fernläufer zu den Sturmgipfeln zu entsenden. Mein Volk kennt diese Lande gut und sollte in der Lage sein, diesen eigensinnigen Zwerg aufzuspüren.", rewards = "Armschienen des WegfindersFäustlinge des EntdeckersSchiftung des SpurenverwischersWegbeschreitergurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12059] = {title = "Ein seltsames Gerät", objective = "Bringt Goramoshs seltsames Gerät zum Abbild des Erzmagiers Aethas Sonnenhäscher.", description = "Ihr seid Euch sicher, als Ihr das seltsame Gerät aufhebt, dass es von magischer Natur ist. Leider scheint es keinen erkennbaren Nutzen aufzuweisen.\n\nWomöglich weiß der Erzmagier in Agmars Hammer nordöstlich der Mondruhgärten mehr darüber.", progress = "Was habt Ihr denn da?", completion = "&lt;Name&gt;, wenn ich mich nicht täusche, habt Ihr den Schlüssel entdeckt, mit dessen Hilfe wir die Absichten der Magierjäger genau erkennen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12060] = {title = "Projektionen und Pläne", objective = "Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.\n\nKehrt anschließend mit den Informationen zum Abbild der Erzmagierin Modera in Sternenruh zurück.", description = "Das hier ist ein Teleportationsgerät. Müsste ich raten, würde ich meinen, dass es einen zur Sognadelplattform über den Mondruhgärten gen Westen teleportiert.\n\nIch möchte, dass Ihr es benutzt, um herauszufinden, was sich dort oben befindet. Es scheint, als könne man sich mit dem Gerät auch wieder zurückbefördern, also müsstet Ihr nicht herunterspringen.\n\nMeinen Erwartungen nach wird sich ganz oben auf der Sognadel eine Art Apparat befinden, den es zu untersuchen gilt.\n\nIhr solltet den Teleporter benutzen können, solange Ihr Euch in den Gärten aufhaltet.", progress = nil, completion = "Was Ihr beschreibt... hört sich wie eine Projektion des Arkanomikons an!\n\n&lt;Kurz kommt die Sorge der Erzmagierin zum Vorschein, doch dann gewinnt ihre unerschütterliche Fassung wieder die Oberhand.&gt;\n\nDas Arkanomikon ist eine Karte all der Stellen auf der Welt, an denen sich die magischen Leylinien überkreuzen. Mit seiner Hilfe hat der blaue Drachenschwarm die 'Anker' der Leylinien entdeckt und zerstört, um die magische Energie wieder zurück zum Nexus zu leiten.\n\nNun stellt sich die Frage, weshalb sich der Zerstörungspfad nach Osten zieht, wenn er sich doch nach Westen ziehen sollte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12061] = {title = "Projektionen und Pläne", objective = "Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.\n\nKehrt anschließend mit den Informationen zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück.", description = "Das hier ist ein Teleportationsgerät. Müsste ich raten, würde ich meinen, dass es einen zur Sognadelplattform über den Mondruhgärten gen Südwesten teleportiert.\n\n<Name>, ich möchte, dass Ihr mit seiner Hilfe herausfindet, was sich dort oben befindet. Es scheint, als könne man sich mit dem Gerät auch wieder zurückbefördern, also müsstet Ihr nicht herunterspringen.\n\nMeinen Erwartungen nach wird sich ganz oben auf der Sognadel eine Art Apparat befinden, den es zu untersuchen gilt.\n\nIhr solltet den Teleporter benutzen können, solange Ihr Euch in den Gärten aufhaltet.", progress = nil, completion = "Was Ihr beschreibt... hört sich wie eine Projektion des Arkanomikons an!\n\n&lt;Nur kurz kommt die Sorge des Erzmagiers zum Vorschein, bis seine unerschütterliche Fassung wieder die Oberhand gewinnt.&gt;\n\nDas Arkanomikon ist eine Karte all der Stellen auf der Welt, an denen sich die magischen Leylinien überkreuzen. Mit seiner Hilfe hat der blaue Drachenschwarm die 'Anker' der Leylinien entdeckt und zerstört, um die magische Energie wieder zurück zum Nexus zu leiten.\n\nNun stellt sich die Frage, weshalb sich der Zerstörungspfad nach Osten zieht, wenn er sich doch nach Westen ziehen sollte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12062] = {title = "Beleidigt Coren Düsterbräu", objective = "Geht und fangt Streit mit Coren Düsterbräu an.", description = "Coren Düsterbräu ist im nächsten Raum und gerade dabei, Dunkeleisenzwerge zu einem weiteren Angriff auf das Braufest aufzustacheln. Macht ihn nieder!\n\nGeht zu ihm hin und provoziert einen Streit. Sagt ihm, dass nicht einmal Säue sein Bier saufen würden.\n\nMacht Euch auf einen Kampf gefasst, wenn Ihr das sagt - das letzte Mal, als jemand über sein Gebräu herzog... warf man ihn Schreckensebern zum Fraß vor.", progress = nil, completion = "Was? Was sagst du da? Du wagst es! Mein Bier kann sich mit dem Spülwasser, das sie auf dem Braufest ausschenken, allemal messen!\n\nDafür wirst du bezahlen, &lt;Klasse&gt;!", rewards = nil}
MultiLanguageQuestData['de'][12063] = {title = "Eisnebels Stärke", objective = "Sucht in Eisnebel nach Banthok Eisnebel.", description = "<Großmutter Eisnebel verbeugt sich.>\n\nEs ist mir eine Ehre, Euch kennenzulernen, <mein Held/meine Heldin>. Es ist Euch zu verdanken, dass viele von uns heute hier versammelt und am Leben sind, bereit, gegen die Geißel in die Schlacht zu ziehen.\n\nIhr habt so viel für uns getan, dass es mich in Verlegenheit bringt, Euch ein weiteres Mal um Unterstützung zu bitten. Es geht um meinen einzigen Sohn Banthok. Ich sprach mich zwar des Öfteren dagegen aus, doch er verließ diesen Ort, um sich auf die Suche nach seinem Vater, Oberhäuptling Eisnebel, zu begeben. Als er das letzte Mal gesehen wurde, zog er in Richtung Westen nach Eisnebel. Ich bitte Euch: Findet Banthok. Ich wüsste weder ein noch aus, würde ich meinen Sohn verlieren.", progress = nil, completion = "Mein Vater ist noch immer am Leben! Wir müssen ihn retten! Ich schaffe es nicht alleine, &lt;Volk&gt;. Ihr müsst mir helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12064] = {title = "Ketten der Anub'ar", objective = "Banthok Eisnebel in Eisnebel in der Drachenöde möchte, dass Ihr ihm Anok'ras Schlüsselfragment, Tivax' Schlüsselfragment und Sinoks Schlüsselfragment beschafft.", description = "Sie haben meinen Vater mit magischen Ketten gefesselt und halten ihn in der Mitte von Eisnebel fest. Alles, was ich in Erfahrung bringen konnte, ist, dass drei mächtige Magier der Anub'ar dafür sorgen, dass er gefangen gehalten wird, und dass ein jeder einen Teil des Schlüssels in Händen hält.\n\nDurchsucht Eisnebel nach diesen Magiern, tötet sie und nehmt ihnen die Schlüsselfragmente ab. Sobald wir erst einmal alle drei Teile haben, werden wir meinen Vater befreien können. Und sobald er frei ist...\n\nVergeltung wird sie ereilen, ehe sie sich versehen.", progress = "Bringt mir diese Schlüsselfragmente!", completion = "Ja, das wird funktionieren.\n\n&lt;Banthok fügt die Schlüsselfragmente mit äußerster Geschicklichkeit zusammen.&gt;\n\nSo, fertig. Mit diesem Schlüssel werden wir meinen Vater aus den Klauen der Anub'ar befreien.", rewards = "Schulterstücke des EiswindsSchulterstücke des SchneewehenhäschersSchulterschützer aus Anub'architinSchulterstücke des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12065] = {title = "Der Fokus am Strand", objective = "Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.\n\nKehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück.", description = "Die Streitkräfte der Magierjäger operieren am Glimmerstrand südlich der Mondruhgärten. Ich vermute, Ihr werdet dort einen schwer bewachten Fokus samt zuständigem Hauptmann vorfinden.\n\nEs besteht kein Zweifel, dass der Hauptmann der Truppe so etwas wie eine Steuerung für das Gerät bei sich trägt. Beschafft Euch diese Steuerung und wendet sie auf den Fokus an.\n\nMit etwas Glück, können wir ein wenig mehr darüber erfahren, was sie dort draußen wirklich vorhaben.", progress = nil, completion = "Wie merkwürdig, dass Euch diese Informationen auf magische Art und Weise übertragen wurden.\n\nWir wissen jetzt nicht nur, dass sie den Energiefluss des Mondruhgartens umgeleitet haben, sondern auch, dass sie diese Energie absichtlich irgendwie manipulieren. Was haben sie bloß mit all dieser Magie vor?\n\nMir gefällt das alles nicht, &lt;Name&gt;, ganz und gar nicht!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Focus on the Beach: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12066] = {title = "Der Fokus am Strand", objective = "Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.\n\nKehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück.", description = "Die Streitkräfte der Magierjäger operieren am Glimmerstrand südlich der Mondruhgärten. Ich vermute, Ihr werdet dort einen schwer bewachten Fokus samt zuständigem Kapitän vorfinden.\n\nEs besteht kein Zweifel, dass der Hauptmann der Truppe so etwas wie eine Steuerung für das Gerät bei sich trägt. Beschafft Euch diese Steuerung und wendet sie auf den Fokus an.\n\nWenn Ihr es geschickt anstellt, können wir etwas mehr darüber erfahren, was sie dort draußen wirklich vorhaben.", progress = nil, completion = "Wie merkwürdig, dass Euch diese Informationen auf magische Art und Weise übertragen wurden.\n\nWir wissen jetzt nicht nur, dass sie den Energiefluss des Mondruhgartens umgeleitet haben, sondern auch, dass sie diese Energie absichtlich irgendwie manipulieren. Was haben sie bloß mit all dieser Magie vor?\n\nMir gefällt das alles überhaupt nicht, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Focus on the Beach: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12067] = {title = "Ein Brief an Zuhause", objective = "Liefert Hauptmann Malins Brief bei Kommandantin Saia Azurstahl in Sternenruh ab.", description = "Im Innenfutter ihrer Robe findet Ihr einen Brief, in dem Folgendes geschrieben steht:\n\n\"Vater,\n\nes tut mir leid, dass ich mich nicht gemeldet habe und du nicht wusstest, wo ich bin. Wenn du diesen Brief liest, dann bin ich schon tot.\n\nIch wurde dazu gezwungen, für Malygos' Armeen zu arbeiten, da sie mir gedroht haben, unsere Familie umzubringen, wenn ich mich weigerte. Ich schäme mich so sehr dafür.\n\nIch bitte dich alles zu tun, was in deiner Macht steht, um sie zu bekämpfen. Und mach dir keine Sorgen um mich. Ich halte sie zum Narren und sabotiere sie nun von innen.\n\nIch liebe dich, Papa!\n\nEm\"\n\nKommandantin Saia Azurstahl wird das hier sicherlich sehen wollen!", progress = "Ein Brief für mich?\n\n<Die Kommandantin liest einen Moment lang in Eurem Gesicht.>\n\nIch denke nicht... - müssen schlechte Nachrichten sein.", completion = "Oh nein... und wir haben Euch dorthin geschickt, um sie zu töten, stimmt's?\n\n&lt;Die Kommandantin schüttelt den Kopf und seufzt.&gt;\n\nEs tut mir leid. Ich werde mich darum kümmern, dass der Brief umgehend an ihren Vater Erzmagier Malin in Sturmwind geschickt wird. Macht Euch keine Sorgen; man wird Euch mit der Sache nicht in Verbindung bringen... Es war nicht Eure Schuld.\n\nVersucht es zu vergessen. Ihr hättet es auf keinen Fall wissen können, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12068] = {title = "Stimmen aus dem Staub", objective = "Drakuru möchte, dass Ihr in die Ruinen von Drakil'jin geht, dort die Tafeln der Drakkari sammelt und 5 Einheiten heiliges Mojo von den Orakeln und Beschützern der Drakkari sammelt. Geht danach zu Drakurus Kohlenbecken in den Ruinen, benutzt Drakurus Elixier und ruft sein Abbild herbei.", description = "<Drakuru platziert das Auge des Propheten über seiner Augenbraue und das Herz der Uralten auf seine Brust.>\n\nWir sind nah' dran, Mann, sehr nahe!\n\nWir müssen nur noch die Tafeln der Drakkari finden. Niemand weiß, wie alt sie sind oder was auf ihnen geschrieben steht, doch mithilfe des Auges und des Herzens kann Drakuru sie lesen. Sie befinden sich tief in der Krypta in Drakil'jin, östlich von hier.\n\nBesorg' dir heiliges Mojo von den Orakeln und Beschützern, nachdem du die Tafeln gefunden hast, und beschwör' mich. Sie sollten stolz sein, dafür sterben zu dürfen.", progress = "Gut, dich zu sehen, <Name>.\n\nHaste die Tafeln gefunden?", completion = "Wir haben es vollbracht, &lt;Name&gt;!\n\nWir haben alle Komponenten, die wir brauchen, um das Läuterungsritual durchzuführen.", rewards = "Hauchdünne SchulterpolsterHelm des aufsteigenden QualmsPhasenverschobene StiefelGeistgeschmiedete BeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nPerlen des rachsüchtigen Geists\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12069] = {title = "Die Rückkehr des Oberhäuptlings", objective = "Befreit Oberanführer Eisnebel mit dem Gefängnisschlüssel von Anub'ar und helft ihm dabei, Unterkönig Anub'et'kan zu besiegen.\n\nNehmt Euch ein Bruchstück aus Anub'et'kans Panzer und bringt es zurück zu Oberanführer Agmar in Agmars Hammer in der Drachenöde.", description = "<Banthok überreicht Euch den Gefängnisschlüssel.>\n\nIhr müsst Euch beeilen, <Name>. Nehmt den Schlüssel und befreit meinen Vater aus dem Gefängnis der Anub'ar. Helft ihm anschließend dabei, ihren Anführer Unterkönig Anub'et'kan zu töten. Reißt dann ein Stück seines Chitinpanzers heraus und präsentiert es der Horde in Agmars Hammer als Trophäe. Agmar soll die Macht des Oberhäuptlings mit eigenen Augen sehen!", progress = "Worum geht's, <Name>? Ich bin äußerst beschäftigt.", completion = "Ihr seid ein mutiger &lt;Klasse&gt;, &lt;Name&gt;. Ihr habt den Oberanführer befreit und der Horde damit einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12070] = {title = "Neue Kraft für die Truppen", objective = "Benutzt den Splitter der Erde, um den Grizzlyhügelriesen, die in den Felshügeln kämpfen, neue Kraft einzuflößen. Tötet alle Eisenzwerge, die sich Euch widersetzen, und erstattet dann Kurun auf dem Hügel, der Thor Modan überblickt, Bericht.", description = "Die Söhne des Eisens haben ihre Runen benutzt, um viele meiner Brüder zu fesseln und benutzen sie dazu, die Belagerung von Thor Modan zu beenden. Ich wünschte, wir müssten sie nicht bekämpfen, aber wir haben keine andere Wahl.\n\nMeine Riesen werden ihnen nicht lange standhalten können.\n\nIch habe diesen irdenen Splitter mit einem Segen versehen, der unseren Verbündeten helfen wird. Nehmt ihn mit Euch in die Schlacht in den Felshügeln im Norden und benutzt ihn, um meinen Brüdern Vertrauen und Stärke einzuflößen. \n\nTötet alle Eisenzwerge, die sich Euch in den Weg stellen.", progress = "Habt Ihr meinen Segen den Riesen meinen Segen übermittelt?", completion = "Ihr habt unseren Verbündeten die Kraft gegeben, weiterzukämpfen, und dafür danke ich Euch. Trotzdem müssen wir einen Weg finden, diese Schlacht zu beenden, bevor wir überrannt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12071] = {title = "Angriff aus der Luft!", objective = "Sprecht mit Valnok Windzürner in Agmars Hammer.", description = "Sie haben gesehen, über welche Macht die Horde auf Land verfügt, nun müssen sie unsere Kraft aus der Luft zu spüren bekommen! Ich möchte, dass Ihr Euch umgehend bei Valnok Windzürner meldet! Er befindet sich hier, in Agmars Hammer.\n\nValnok wurde schon über die Einzelheiten Eurer Mission unterrichtet und erwartet Euch.", progress = nil, completion = "&lt;Valnok salutiert Euch.&gt;\n\nIhr seid also das Ass, oder was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12072] = {title = "Verdammt sollen die Seuchenbestien sein!", objective = "Geht nach Eisnebel, benutzt Valnoks Leuchtpistole, um einen Kriegsreiter der Kor'kron zu rufen, setzt auf und tötet mit seiner Hilfe 25 Seuchenbestien der Anub'ar!\n\nKehrt anschließend wieder zu Valnok Windzürner in Agmars Hammer zurück, sobald Ihr diese Mission erfüllt habt.", description = "Ihr habt zweifellos die Armee der Seuchenbestien der Anub'ar gesehen, die in Eisnebel erschaffen wird. Die Anub'ar wollen diese Monster auf unsere Soldaten an der Pforte des Zorns hetzen - doch das darf nicht passieren!\n\nNehmt diese Leuchtpistole, geht nach Eisnebel im Westen und feuert sie ab, um einen meiner Kriegsreiter zu rufen. Sitzt auf und vernichtet mit seiner Hilfe die Seuchenbestien, die man vom Boden aus nicht erreichen kann!\n\nKehrt zu mir zurück, sobald Ihr ihre Luftstreitkräfte dezimiert habt, und holt Eure Belohnung ab!", progress = nil, completion = "&lt;Valnuk salutiert.&gt;\n\nUnd aus der Luft kam ihre Vernichtung! Vielleicht werdet Ihr schon bald nach Angrathar beordert, Held!", rewards = "Armschienen des EiswüstenhauchsArmschienen des LichtungswanderersVersteinerter KnochenbrustschutzAuf Euch wartet eine dieser Belohnungen:\n\nHalsband des Geißelghuls\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12073] = {title = "Das Eisen bearbeiten", objective = "Tötet 10 beliebige Eisenzwerge in Thor Modan und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück.", description = "Die Allianz ist nicht die einzige Macht, die sich uns in den Grizzlyhügeln entgegenstellt. Die Eisenzwerge halten die Ostküste unter ihrer Kontrolle, obwohl Thor Modan im Nordosten von Steinriesen belagert wird.\n\nEin fähiger Krieger nutzt die Schwäche seiner Gegner aus, und wir wären töricht, wenn wir die Verwundbarkeit der Eisenzwerge in Thor Modan ignorieren würden. Zeigt ihnen keine Gnade. Erschlagt alle und jeden, der sich Euch in den Weg stellt.\n\nDie 'Söhne des Eisens' werden die Horde schon fürchten lernen.", progress = nil, completion = "&lt;Späher Vor'takh lächelt.&gt;\n\nThor Modan steht also kurz vor dem Fall?\n\nSehr gut. Dann können wir bald unsere Aufmerksamkeit auf Dun Argol richten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12074] = {title = "Ein nützlicher Verbündeter", objective = "Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt.", description = "Die alte Zwergenhauptstadt Thor Modan, weit im Nordosten, wird von einer mysteriösen Truppe, bestehend aus Steinriesen und Irdenen, belagert.\n\nWarum die Schöpfungen der Titanen gegeneinander Krieg führen, geht über meinen Horizont und liegt außerhalb des Interessengebietes der Horde. Jedoch haben wir hier eine Gelegenheit, einen gemeinsamen Feind zu schwächen.\n\nReist nach Thor Modan und sucht diesen 'Kurun', der die Riesen und die Irdenen befehligt. Macht mit ihm gemeinsame Sache und benutzt seine Streitkräfte, um die Eisenzwerge zu zermalmen.", progress = nil, completion = "&lt;Ihr stellt Euch Kurun vor.&gt;\n\nSo sind die Söhne des Eisens also auch Eure Feinde?\n\nMeine Streitkräfte haben die Eisenzwerge in ihrer Stadt eingeschlossen, aber wir könnten Hilfe bei der Erstürmung gebrauchen. Werdet Ihr uns unterstützen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12075] = {title = "Mageres Angebot", objective = "Beschafft eine Steinfleischprobe von der Eisriesenleiche am Höhleneingang nördlich von Zort in der Kristallschlucht und kehrt wieder zu ihm zurück, sobald die Aufgabe abgeschlossen ist. Er befindet sich in der Nähe des Zentrums der Schlucht.", description = "Kalt hier draußen, findet Ihr nicht, <Volk>?\n\nKo'char hat sich geweigert, mich zu treffen. Es scheint, als hätte er dringlichere Dinge auf dem Herzen - nämlich Angriffe der Jormungar, die in der Höhle dort unten hausen. Vielleicht könntet Ihr mir dabei helfen, Ko'char davon zu überzeugen, dass ich einer der Guten bin.\n\nIch sah, wie einige der Würmer am Höhleneingang im Norden an einem der Riesen herumnagten... Mir ist es noch immer schleierhaft, weshalb die Würmer sie so leicht töten können. Bringt mir eine Probe seiner Wunden.", progress = "Seid Ihr nun mit meiner Probe zurückgekehrt? Ich bin froh, dass Euch die Kälte nicht erwischt hat.", completion = "Das ist perfekt. Danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12076] = {title = "Dreckige Angelegenheit", objective = "Füllt 2 Phiolen mit ätzendem Speichel, indem Ihr den Schaber auf Euch anwendet. Bringt die Phiolen wieder zu Zort in der Kristallschlucht, wenn Eure Aufgabe abgeschlossen ist.", description = "Sogar beim ersten Anblick lässt sich ganz deutlich erkennen, dass die von Euch gebrachte Probe Zeichen einer ätzenden Spucke aufweist. Logischerweise ist anzunehmen, dass die Würmer dieselbe Substanz, mit der sie sich durch die Erde graben, auch als wirksame Waffe gegen die Eisriesen einsetzen.\n\nNehmt diesen Schaber und fordert ein paar dieser Würmer zum Kampf heraus. Entfernt mit dem Schaber ihre Spucke, wenn Ihr davon getroffen wurdet, und bringt sie hierher.\n\nBeschafft mir eine ordentliche Menge - ich werde das Zeug als Basis für ein Elixier verwenden müssen.", progress = "Da, auf Eurer Schulter scheint noch immer etwas Spucke zu kleben, <Volk>. Passt auf oder es wird sich glatt durch Eure Rüstung brennen.", completion = "Noch immer frisch. Einen Moment, ich werde das hier mit dem Rest des Elixiers vermischen, das ich vorbereitet habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12077] = {title = "Zwei Mal am Tag anwenden", objective = "Bietet das von Zort zubereitete Elixier Ko'char dem Unbezwingbaren an.", description = "Dieses Elixier sollte Schutz vor ihrer Spucke bieten. Würdet Ihr es Ko'char anbieten? Sagt ihm auch, dass es noch viel mehr davon gibt und er es haben kann, wenn er sich erkenntlich zeigen wird.", progress = "Der Wicht möchte, dass wir für ihn kämpfen, nicht wahr? Wie bin ich überrascht.", completion = "Um ehrlich zu sein, mein Kleiner, traue ich dieser Mixtur nicht und werde sie auch nicht probieren. Behalte sie... Du hast vielleicht mehr Vertrauen in diesen naiven Wicht als ich und kannst sie besser gebrauchen.", rewards = "Ihr bekommt:\n\nZorts schützendes Elixier"}
MultiLanguageQuestData['de'][12078] = {title = "Wurmcowboy", objective = "Betretet die Höhlen in der Kristallschlucht und fangt mithilfe stabiler Kisten 3 Exemplare der Jormungarbrut. Achtet jedoch darauf, dass Ihr die Kisten einsteckt, sobald die Jormungarbrut gefangen ist!\n\nBringt sie dann zu Zort in der Kristallschlucht.", description = "So soll es sein. Vielleicht können wir diese Würmer zu irgendwas gebrauchen, wenn die Riesen uns schon nicht helfen wollen. Die Brutmutter in der Höhle dort oben hat sicherlich ihren Nachwuchs in der Nähe. Nehmt diesen Kasten, fangt mir 3 Exemplare ihres Nachwuchses und bringt sie anschließend zu mir.\n\nWo Diplomatie versagt, ist Versklavung eine absolut rentable Alternative.", progress = "Ihr seid zurückgekehrt! Habt Ihr die Biester mitgebracht? Ich muss hier raus... Ich bin mir ziemlich sicher, dass mich Ko'char vor ein paar Minuten zertreten wollte.", completion = "Das dürfte reichen. Vielleicht werde ich diese Biester, sobald sie voll ausgewachsen sind, zurückbringen und sie eigenhändig mit den Riesen bekannt machen.\n\nEin Haufen unnützer Steine, wenn Ihr mich fragt.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12079] = {title = "Das Revier", objective = "Ko'char der Unbezwingbare möchte, dass Ihr die Höhlen am nördlichen Ende der Kristallschlucht erforscht und 8 Eiskernjormungarfresser tötet.", description = "Sei gegrüßt, <mein Kleiner/meine Kleine>. Ich weiß zwar nicht, welcher Wahnsinn dich in die Kristallschlucht getrieben hat, doch du bist mir willkommen.\n\nDiese Eiswürmer... diese Jormungar haben Geschmack an meinen Brüdern gefunden. Dass meinesgleichen dir in irgendeiner Art und Weise wohlgesinnt sein werden, halte ich für unwahrscheinlich, doch wenn du uns dabei helfen willst, mit den Würmern fertigzuwerden, dann hast du meine ungeteilte Aufmerksamkeit.\n\nWenn wir die Höhle wieder in unseren Besitz bringen wollen, müssen wir zuerst die Schlucht von diesen Jormungarfressern befreien. Steh unserem Kampf bei, <Volk>!", progress = nil, completion = "Ein Gemetzel nach meinem Geschmack.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12080] = {title = "Mächtig großer Wurm", objective = "Betretet die Eiskernhöhlen und streckt Rüttelbohrer nieder. Benutzt Zorts schützendes Elixier, falls Ihr es noch besitzen solltet, um Euch vor dem ätzenden Speichel der Jormungar zu schützen.\n\nKehrt zu Ko'char dem Unbezwingbaren in der Kristallschlucht zurück, wenn die Aufgabe abgeschlossen ist.", description = "In den Höhlen dort unten gibt es eine Brutmutter. Wir nennen sie Rüttelbohrer - ein Name, der Ihr von einem Abenteurer aus den Pestländern beschert wurde. Ich schlug gerade ihren ersten Angriff zurück, als ich sie für einen Moment zu Gesicht bekam. Sie ist so groß, dass sie eines meiner Jungen ganz verschlingen könnte. Wir werden die Höhle erst wieder in unseren Besitz bringen können, wenn sie beseitigt ist.", progress = nil, completion = "Sie ist also tot - gut, so soll es sein. Du hast auf jeden Fall bewiesen, dass deine Absichten nobler sind als die des Wichts.\n\nÜber die nördliche Schlucht erreicht Ihr den Kristallsangwald. Es ist ein verfluchter und gefährlicher Ort, &lt;Volk&gt;. Sei auf der Hut, wenn das dein nächstes Ziel sein sollte.\n\nHier, nimm das als Belohnung für deine Mühen, mein Kleiner. Du hast meinen Segen. Gute Reise.", rewards = "Dünne JormungarbeinwickelRüttelbohrertötergamaschenBrustschutz des EiskernsKristallplattenbeinschützerIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12081] = {title = "Gavrock", objective = "Sprecht mit Gavrock in den Ruinen von Tethys.", description = "Ohne Eure Hilfe wären wir nicht dazu in der Lage gewesen, das Blatt in der Schlacht um Thor Modan zu unseren Gunsten zu wenden. In dieser uralten Stadt tobt schon seit langem ein Kampf zwischen den Kräften der Erde und des Gesteins. Ich kann nur hoffen, dass wir die Situation eine zeitlang beruhigt haben.\n\nDie Eisenzwerge können noch immer ihre Magie dazu benutzen, um meine Brüder zu versklaven. Gavrock sucht nach einem Weg, wie wir die runenbeschriebenen Riesen befreien können. Ihr könnt ihn auf einer kleinen Inselgruppe namens Ruinen von Tethys finden. Diese Gruppe liegt vor dem zentralen Teil der Ostwindküste gen Süden.", progress = nil, completion = "Ich weiß, dass Kurun für Eure Hilfe dankbar ist. Der Sieg über Thor Modan wird eine große Errungenschaft für uns sein, doch unsere Brüder werden wir dadurch nicht befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12082] = {title = "Dan-ta dan-ta dan-ta-dah!", objective = "Eskortiert Harrison aus den Ruinen von Drakil'jin, sprecht dann mit Harkor im gleichnamigen Lager.", description = "Hört zu, <Kleiner/Kleines>. Das hier ist kein Ort, an dem Ihr herumtollen solltet.\n\nIch mach' gleich den Abflug. Bleibt dicht hinter mir und ich hol' Euch hier raus.", progress = nil, completion = "Ihr habt also das kleine Abenteuer mit unserem guten Freund überlebt, hm?\n\nDas sollte Euch eigentlich schon Belohnung genug sein, aber hier - ich habe heute meinen großzügigen.", rewards = "Sandalen der schnellen FluchtGewickelte LederstulpenUmgenähte HandgelenksschützerLastentragender GurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12083] = {title = "Über den Waldländern", objective = "Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.\n\nKehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück.", description = "Ich bin davon überzeugt, dass es noch mehr von diesen Fokussen geben muss, von denen wiederum jeder die Leylinienenergien weiterleitet. Wir wissen allerdings immer noch nicht genau, was sie mit all der Energie anstellen wollen.\n\nIch schätze, dass sich ein weiterer auf dem höchsten Punkt des Waldlandes von Lothalor gen Süden befinden muss. Ihr werdet also wieder einmal herausfinden müssen, wer dort das Sagen hat, und ihm anschließend das Steuergerät abnehmen, da ich mir sicher bin, dass es für jeden Fokus ein spezielles Gerät geben muss.\n\nSeid auf der Hut, <Name>, die Wälder sind voller Gefahren.", progress = nil, completion = "Sie erfüllen mithilfe des Fokus ihre Truppen mit Macht? Das ergibt keinen Sinn; so mächtig sind die Magierjäger nicht.\n\nDas muss also bedeuten, dass sie die Magie ausschließlich dort verwenden, wo auch immer sie die jeweilige Leylinie hinleiten.\n\nWir werden mehr Informationen benötigen, wenn wir sie finden und aufhalten wollen!", rewards = "Sandalen des Initianden der Kirin TorSchulterpolster des violetten JägersHandschützer des AzurjägersHandgelenksschützer der DalaranwacheDer folgende Zauber wird auf euch gewirkt:\n\nAtop the Woodlands: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12084] = {title = "Über den Waldländern", objective = "Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.\n\nKehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück.", description = "Ich bin überzeugt, dass es mehr dieser Fokusse gibt - jeder von ihnen leitet die Energie der Leylinien um. Wir wissen jedoch noch nicht genau, was sie mit all dieser Energie anstellen.\n\nIch schätze, Ihr werdet einen weiteren hoch über den Waldländern im Süden finden. Ihr werdet erneut die zuständige Person finden müssen und die Steuerung, welche diese bei sich trägt, an Euch nehmen - ich bin mir sicher, dass jeder Fokus über eine eigene verfügt.\n\nBeeilt Euch bei Eurem Auftrag, <Klasse> Ich spüre, dass uns die Zeit davonrinnt.", progress = nil, completion = "Sie bündeln diese Energie in ihren Truppen? Aber das ergibt keinen Sinn - die Magierjäger sind nicht entsprechend mächtig.\n\nDas kann nur bedeuten, dass sie die Energie in Wirklichkeit nur am Endpunkt der Umleitung, die sie an den Leylinien vorgenommen haben, nutzen.\n\nWir werden weitere Informationen benötigen, wenn ich einen Plan ausarbeiten soll, um sie zu stoppen.", rewards = "Sandalen des Initianden der Kirin TorSchulterpolster des violetten JägersHandschützer des AzurjägersHandgelenksschützer der DalaranwacheDer folgende Zauber wird auf euch gewirkt:\n\nAtop the Woodlands: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12085] = {title = "Ein Brief an Zuhause", objective = "Liefert Leutnant Ta'zinnis Brief bei Oberanführer Agmar in Agmars Hammer ab.", description = "Im Innenfutter seiner Robe findet Ihr einen Brief, in dem Folgendes geschrieben steht:\n\n\"Deino,\n\nTut Ta'zinni leid, dass er verschwunden ist. Wenn du diesen Brief liest, dann bin ich tot.\n\nDie haben mich gezwungen, für Malygos' Armeen zu malochen. Die haben mir gedroht, meine Familie umzumurksen, wenn ich mich weigerte. Und Ta'zinni wollte das nicht zulassen!\n\nMach dir um mich keine Sorgen, pass nur gut auf deine Kinder auf. Ich hab die hier ausgetrickst und sabotiere sie jetzt von innen heraus.\n\nHab dich lieb, Schwester!\n\nTa'zinni\"\n\nOberanführer Agmar wird das hier sicherlich sehen wollen!", progress = "Was soll das? Wollt Ihr etwa einen Brief verschicken?\n\nAlle Briefe gehen erst mal über mich. Hier gibt es nämlich Spione und Verräter!\n\n<Der Oberanführer mustert Euch kurz. Ihr fragt Euch, ob er nicht auf der Stelle die Wachen rufen und Euch umbringen lassen wird.>\n\nNun gut, aber macht schnell. Sollte mir jedoch nicht gefallen, was ich da geschrieben sehe, dann werde ich Euch an meine Worgs verfüttern.\n\n<Agmar grinst, als sich Gar'mak und Lak'tuk zu Euch umdrehen, mit einem Blick in ihren Augen, als wärt Ihr ihre nächste Mahlzeit.>", completion = "Ahahahaha... ach Herr je, wie rührend.\n\n&lt;Der herablassende Ton im tiefen Gelächter des Oberanführers ist unüberhörbar.&gt;\n\nWas habe ich gesagt? Verräter! Immerhin, es gab einmal eine Zeit, da kannte ich Deino. Zumindest ist sie ein Troll von Ehre!\n\nSie wird herausfinden, was mit ihrem Bruder geschehen ist - dafür werde ich sorgen. Und bei der Gelegenheit werde ich sogar vergessen ihr zu sagen, dass Ihr für seinen Tod verantwortlich seid.\n\n&lt;Agmar starrt Euch an. Sein Blick wirkt berechnend.&gt;\n\nDoch nun gehört Ihr mir, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12086] = {title = "Karkuts Sohn", objective = "Geht in Richtung Osten nach Todeswehr jenseits von Unu'pe.", description = "Der Mann, nach dem Ihr sucht, ist weit nach Osten gegangen und hat einen Ort in Küstennähe jenseits von Unu'pe aufgesucht, den man Todeswehr nennt.\n\nSeid vorsichtig, wenn Ihr dorthin geht und nach ihm sucht, <Name>. Er trug das Zeichen Karkuts... der über die Toten wacht.", progress = nil, completion = "Thassarian? Ja, er war hier... was ist mit ihm? Wir haben dringendere Probleme im Moment, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12087] = {title = "A Little Help Here? DEPRECATED", objective = "Corporal Venn at Death's Stand wants you to kill 8 Ziggurat Defenders.", description = "We were sent here to take over the Howling Ziggurat, due north.  We weren't expecting to make it back alive.... hell, we already lost half our crew.\n\nTassarian was on point and the higher ups... well, they didn't like something about him.\n\nHe took off this morning... he might've gone to the ziggurat on his own.  But right now we have more pressing matters to worry about.  The Scourge keeps getting closer and closer to the camp, we need to take care of them -- now!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12088] = {title = "Thassarian der Todesritter", objective = "Seht nach Thassarian im Inneren der Klagenden Ziggurat nördlich von Todeswehr.", description = "Nun, <Name>, Ihr habt uns also geholfen... deshalb ist es wohl nur angemessen, wenn wir Euch auch helfen.\n\nIhr sucht nach Thassarian? Er verschwand heute Morgen. Wir vermuten, dass er gen Norden zur Klagenden Ziggurat gegangen ist. Wenn wir nicht Seite an Seite mit ihm gekämpft hätten, würden wir ihn sogar für einen Verräter halten.\n\nIhr müsst verstehen, er ist ein Todesritter... und ich weiß, dass diese auf unserer Seite sind und so weiter... aber vor nicht allzu langer Zeit waren diese Arthas' Diener.\n\nAber nicht Thassarian. Er ist ein guter Kerl. Geht zur Klagenden Ziggurat und seht, ob er zurechtkommt.", progress = nil, completion = "Leryssa... sucht nach mir? Ihr müsst mir helfen, &lt;Name&gt;. Wir müssen dies zu Ende bringen, bevor ihr etwas zustößt.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12089] = {title = "GESUCHT: Magister Keldonus", objective = "Erschlagt Magister Keldonus und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Magister Keldonus\n\nVerbrechen: Verrat\n\nZustand: lebendig\n\nIm Namen der Horde ist Magister Keldonus, einstiger Magierkommandant von Agmars Hammer, auf der Stelle zu töten.\n\nGesichtet wurde Keldonus das letzte Mal, als er auf dem Weg nach Südwesten in Richtung der Mondruhgärten unterwegs war, um sich dort dem blauen Drachenschwarm und dem Feldzug gegen die Magie anzuschließen.\n\nKeldonus sollte mit Vorsicht begegnet werden.\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", progress = nil, completion = "Nicht das Erste dieser Magierweicheier, das uns verraten hat, und sicherlich nicht das Letzte. Ist aber auch verdammt schade... Er war einer unserer besten Magier. Er konnte ein Büffet herzaubern, dass einem das Wasser im Munde zusammenlief und Herzen höher schlugen...\n\nBAH!", rewards = "Belastbarkeit des ZauberwächtersKeldonus fehlender ZaubersplitterRückendreherGewehr der MagiertöterMagiertodBlutverschmierter MetzlerIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12090] = {title = "Gesucht: Gigantaur", objective = "Erschlagt Gigantaur und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Gigantaur\n\nVerbrechen: Angriffe auf die Horde; \"potthässlich\"\n\nZustand: lebendig\n\nDer Magnataurenfürst Gigantaur wird in Verbindung mit einer Reihe von Angriffen auf die Soldaten und Anlagen der Horde in der Drachenöde gesucht.\n\nZuletzt wurde Gigantaur in den Wäldern und auf den Straßen südlich und südöstlich von Agmars Hammer gesehen.\n\nGigantaur gilt als bewaffnet und extrem gefährlich.\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", progress = nil, completion = "Ihr habt dieses hässliche Pferdegesicht also erwischt, hm? Tja, eine Plage weniger, um die sich unsere Soldaten draußen auf den eisigen Weiten kümmern müssen.", rewards = "Umhang des ChaosheilersArmschienen des Waldläufers von LothalarStulpen des FelsgratjägersPlattengamaschen der MagnataurenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12091] = {title = "GESUCHT: Schreckensklaue", objective = "Erschlagt Schreckensklaue und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Schreckensklaue\n\nVerbrechen: Angriffe gegen die Horde\n\nZustand: lebendig\n\nSchreckensklaue wird wegen zahlreicher Angriffe auf Karawanen der Horde, die entweder nach Gallgrimm oder von dort aus unterwegs waren, gesucht. Ihm sollte mit äußerster Vorsicht begegnet werden.\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", progress = nil, completion = "Wurde auch langsam mal Zeit, dass jemand der Metzelei dieser dreckigen Bestie ein Ende macht! Gut gemacht, &lt;Name&gt;.", rewards = "Federn der DracheneiswüsteSchultern des Waldläufers von LothalarBrustschutz des FelsgratjägersSchreckenskrallengriffIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12092] = {title = "Stärkt die Urtume", objective = "Benutzt die Borke der Wanderer und stärkt damit 3 Urtume von Lothalor. Kehrt anschließend zu Sarendryana in Sternenruh zurück.", description = "Nicht nur Euer Volk ist von dem betroffen, was der blaue Drachenschwarm getan hat. Auch die Urtume der Wälder von Lothalor gen Südosten bekamen die Auswirkungen zu spüren.\n\nEinige fielen der Verderbnis anheim - diese müsst Ihr um jeden Preis meiden -, doch die meisten können noch immer gerettet werden. Die Treants in den Wäldern scheinen jedoch immun gegen die Magie zu sein, die durch das Land sickert und mit der auch die Wyrms kommen.\n\nBittet die Treants um ihre Borke und gebt sie den Urtumen zu essen. Hoffentlich wird das genügen, um sie zu retten.", progress = "Ein zusätzlicher Vorteil, der sich durch die Rettung der Urtume ergeben könnte, wäre, dass sie es in Erwägung zögen, die Allianz in ihrer Not zu unterstützen. Ungeachtet dessen, ist es das Richtige zu tun.\n\nWie vielen konntet Ihr nun Kraft verleihen, <Klasse>?", completion = "Ich danke Euch, &lt;Volk&gt;! Wir haben schon so viel verloren. Ihr habt dafür gesorgt, dass uns die Majestätischsten von Nordends Kindern erhalten bleiben.\n\nIch werde bald gehen und mit den Urtumen sprechen, die Ihr gerettet habt. Mal sehen, ob sie uns in diesen Zeiten der Not nicht helfen können.", rewards = "Armschienen des NaturzornsGürtel des Waldläufers von LothalarTreter von SternenruhRindenbedeckte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12093] = {title = "Runen des Zwangs", objective = "Gavrock in den Ruinen von Tethys möchte, dass Ihr die vier Runen des Zwangs ausschaltet, indem Ihr Aufseher Durval, Aufseher Korgan, Aufseher Lochli und Aufseher Brunon besiegt.", description = "Noch während Kurun Thor Modan angreift, wirken die Eisenzwerge ihre Magie gegen unsere Brüder. Indem sie unsere Brüder aus der Erde beschwören und sie mit Runen an sich binden, zwingen die Söhne des Eisens sie zum Kampf gegen die Kinder des Steins.\n\nEntlang der Ostwindküste verwenden sie Runen des Zwangs, um versklavte Riesen zu den Schlachtfeldern im Norden zu entsenden.\n\nFindet die vier Runen des Zwangs und zwingt ihre Aufseher zum Erscheinen, indem Ihr die Runenweber überwältigt, die jede Rune bemannen. Ohne die Aufseher sind die Runen nutzlos.", progress = "Habt Ihr die Runen an der Küste ausgeschaltet?", completion = "Gut. Nun müssen wir rasch handeln, bevor die Söhne des Eisens bemerken, dass ihre Runen wirkungslos geworden sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12094] = {title = "Latente Macht", objective = "Ladet den Splitter von Gavrock am ersten, zweiten und dritten uralten Stein auf und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück.", description = "So lange die Runen des Zwangs nicht aktiv sind, besteht die Chance, dass wir die runenbeschriebenen Riesen freilassen können.\n\nIch werde Euch ein Stück des Steins geben, der schon seit meiner Erschaffung ein Teil von mir geblieben ist. Erfüllt man ihn mit der richtigen Kraft, so kann man mit seiner Hilfe die gefangenen Riesen befreien.\n\nZwischen dem Waldrand und dem Eisenpfad befinden sich Orte der Macht - Orte, die Euer Volk Leylinienknotenpunkte nennen würde - und dort gibt es auch zwei uralte Steinmarkierungen. Eine weitere Steinmarkierung befindet sich auf einer Insel am südlichen Ende dieser Ruinen. Ladet den Splitter bei jedem dieser Steine auf.", progress = "Habt Ihr die uralten Steine gefunden?", completion = "Ich kann die Macht spüren, mit der Ihr den Splitter erfüllt habt, und ich hoffe, dass sie genügen wird, um die runische Magie zu bannen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12095] = {title = "Zum Drachenjägerposten", objective = "Sprecht mit Rokhan in Drachensturz in der Drachenöde.", description = "Östlich von hier, im Herzen der Drachenöde, befindet sich ein Feld, auf dem sich nichts als Drachenknochen und Schnee befinden. Die Geißel hat mehrere Lager in der zentralen Tundra aufgeschlagen und ruft Frostwyrms wieder ins Leben, um sie dann auf unsere Streitkräfte an der Pforte des Zorns zu hetzen. Rokhan und seine Drachenjäger können zwar mit den meisten dieser Frostwyrms fertigwerden, doch einer von ihnen erweist sich als problematisch.\n\nSucht Rokhan in Drachensturz im Nordosten auf. Helft ihm und seinen Männern Sarathstra niederzustrecken und Ihr werdet reichlich belohnt werden!", progress = nil, completion = "Denkst du, dass du dort siegen kannst, wo Rokhan versagt?", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12096] = {title = "Stärkt die Urtume", objective = "Benutzt die Borke der Wanderer, um 3 Urtume von Lothalor zu stärken, und kehrt anschließend zu Erdwächter Graif in Agmars Hammer zurück.", description = "Die Urtume des Waldlandes von Lothalor im Süden werden von Arkanwyrm verderbt... Wyrm, die direkt aus der Erde gekommen sind!\n\nDie schon Verderbten sind tödlich und nützen uns nichts, doch die meisten können noch immer gerettet werden. Zum Glück scheinen die Treants der Wälder immun gegen alles zu sein, was dort vor sich geht.\n\nBittet die Treants, Euch etwas von ihrer Rinde abzugeben, und verfüttert diese anschließend an die Urtume - das sollte sie stärken.\n\nNun lasst mich in Ruhe arbeiten! Ich muss ein Auge auf diese Apotheker werfen.", progress = nil, completion = "Habt meinen Dank, &lt;Klasse&gt;.\n\nSobald ich herausgefunden habe, was diese widerwärtigen Apotheker vorhaben, werde ich mich auf den Weg zu den Wäldern machen und sehen, ob ich die Urtume davon überzeugen kann, dass sie sich uns anschließen.\n\nZumindest sollte ich sie davon überzeugen können, ihre Retter in Frieden zu lassen!", rewards = "Armschienen des NaturzornsGürtel des Waldläufers von LothalarTreter von SternenruhRindenbedeckte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12097] = {title = "Sarathstra, Geißel des Nordens", objective = "Sprecht mit Rokhan, um den Frostwyrm Sarathstra herbeizurufen.\n\nTötet Sarathstra und liefert Sarathstras gefrorenes Herz bei Hauptmann Gort in Agmars Hammer ab.", description = "Meine Jäga sind tot oda eingefrostet, <Name>. Noch imma Lust drauf? Ein Wort reicht und ich werde nochmal nach'm Drachen rufen.\n\nBring das gefrorene Herz vom Biest nach Agmars Hammer und gib es Gort. Er wiad dich ganz bestimmt dick belohnen, Mann.", progress = "<Gort hebt eine Braue.>\n\nSchon zurück?", completion = "HA! Ihr habt es geschafft! Die Soldaten an der Pforte des Zorns stehen in Eurer Schuld, &lt;Name&gt;! Das wird einigen von ihnen sicherlich ein paar Tage mehr auf dieser Welt bescheren.", rewards = "Hüfttuch der energischen ZerstörungVerbund der rechtschaffenen VerfolgungGürtel der rachsüchtigen LäuterungGurt der kraftvollen VernichtungIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12098] = {title = "Durchsucht Indu'le", objective = "Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen.", description = "Ich bin mir sicher, dass Ihr den nächsten Leylinienfokus irgendwo in den Überresten von Indu'le im Südosten finden werdet. Das Problem ist nur, dass wir überhaupt keine Meldungen darüber erhalten haben, ob es dort einen gibt oder nicht.\n\nWenn Ihr das Dorf bitte nach irgendwelchen Hinweisen über den Fokus oder die Magierjäger und ihren Kommandanten in der Gegend durchsuchen würdet, wäre ich dankbar.\n\nVergesst nicht, auch im See nachzusuchen, wenn es sein muss.", progress = nil, completion = "An dieser Stelle findet Ihr die Leiche des Kommandanten der Magierjäger.\n\nNach seinem Aussehen und dem Zustand der Truppen um ihn herum zu urteilen, scheinen sie nicht ertrunken zu sein. Vielmehr erweckt die Szene den Eindruck, als hätten sie den Angriff der Elementare aus den Rissen im Seebett nicht erwartet.\n\nDem Anschein nach waren die Magierjäger für ihr eigenes Ableben verantwortlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12099] = {title = "Endlich frei", objective = "Befreit mit Gavrocks Runenbrecher 4 runenbeschriebene Riesen und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück.", description = "Der Steinsplitter, den Ihr mit Kraft erfüllt habt, sollte mächtig genug sein, um die runische Magie zu bannen, die meine Brüder gefangen hält.\n\nNehmt ihn mit und sucht nach den runenbeschriebenen Riesen, die im Norden die Ostwindküste entlang marschieren. Setzt die Macht, die im Stein gespeichert ist, frei und seht, was passiert.\n\nFalls er funktionieren sollte, dann müssten die Riesen wieder zur Besinnung kommen und den Befehlen der Eisenzwerge nicht mehr Folge leisten. Sollte der Stein nicht funktionieren, ist es möglich, dass die Riesen geschwächt werden und Euch angreifen. Doch haben wir überhaupt eine Wahl? Wenn wir es nicht versuchen, werden sie für immer versklavt bleiben.", progress = "Konntet Ihr irgendeinen meiner Brüder befreien?", completion = "Das Ding ist also nicht zuverlässig? Ich wünschte, dass es keine Frage des Glücks wäre, doch zumindest sind wir auf dem richtigen Weg. Ohne Eure Hilfe, wäre dies nie möglich gewesen. Falls Ihr noch mehr über die Machenschaften der Eisenzwerge und deren Pläne bezüglich der Steinkinder herausfinden solltet, dann sucht uns auf und wir werden Euch anhören, &lt;Name&gt;.", rewards = "Zweig des umherirrenden GeistesKlaue der FreiheitKlinge des BefreiersDer HeckenschützeSpitze des erhabenen NachsinnensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12100] = {title = "Der Verwesung Einhalt gebieten", objective = "Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr 15 infizierte Wildtiere tötet und ein verwesungsresistentes Organ beschafft.", description = "Die Geißel bringt Tod und Krankheit mit sich. Wir übersehen nur zu oft, dass die Tierwelt in den von der Geißel verseuchten Gegenden stark angeschlagen ist und durch die ansteckende Verwesung letztendlich ausgelöscht wird.\n\nFür die meisten einheimischen Tiere der Drachenöde ist es schon zu spät. Die Tiere sind schon mit der Krankheit der Geißel infiziert, deren Kennzeichen eitrige Pusteln sind - nun verwesen sie vor sich hin und sind von Tollwut befallen.\n\nGeht nach Westen zur Grube von Narjun und tötet die infizierten Tiere. Seht nach, ob sich in ihren Leichen ein gut erhaltenes Organ finden lässt, da wir eins brauchen, um ein Gegengift daraus herzustellen.", progress = "Tötet die Tiere, um die Verbreitung der Krankheit zu verhindern, und bringt mir ein verwesungsresistentes Organ.", completion = "Zwar schmerzt es mich, Tiere zu töten, jedoch müssen wir uns dieser Pflicht annehmen. Kommen wir nun zum nächsten Schritt: der Impfung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12101] = {title = "Der gute Doktor...", objective = "Liefert das verwesungsresistente Organ bei Doktor Sintar Malefius in Agmars Hammer ab.", description = "Die Verlassenen, unsere Verbündeten, haben die wichtigsten Mitglieder ihrer Apothekervereinigung hierher entsandt, um uns bei der Vernichtung der Geißel an der Pforte des Zorns zu unterstützen. Unter ihnen befindet sich jemand namens Doktor Sintar Malefius, ein Kenner, wenn es um die Fäulnis der Geißel und deren Verbreitung geht. Ich hatte zuvor mit ihm eine Einigung in Bezug auf die Impfung der betroffenen Tiere erzielt - seitdem wartet er auf ein Organ.\n\nLiefert dieses verwesungsresistente Organ bei Dr. Malefius ab und lasst ihn wissen, dass es von mir ist. Von ihm werdet Ihr auch Euren nächsten Auftrag erhalten.", progress = "Was jetzt?", completion = "Der rüpelhafte Ochsenmensch konnte tatsächlich ein verwesungsresistentes Organ besorgen? Verflucht... ich war mir sicher, dass diese Aufgabe seinen missgebildeten Geist bis ins nächste Jahrtausend beschäftigen würde.\n\nNa gebt schon her, Junge. Ich habe ohnehin schon viel zu tun, auch wenn Eure schwächlichen Bedürfnisse mir nicht gerade im Weg stehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12102] = {title = "Auf der Suche nach dem rubinfarbenen Flieder", objective = "Doktor Sintar Malefius in Agmars Hammer in der Drachenöde möchte, dass Ihr 1 rubinfarbenen Flieder pflückt.", description = "Ein Glücksfall, dass der Rubindrachenschrein gleich im Osten liegt. Dort findet sich auch eine Blume, die man den rubinfarbenen Flieder nennt. Diese lebensspendende Pflanze ist alles, was ich brauche, um einen Impfstoff für die gesunden Tiere dieser Region herzustellen.\n\nGeht nach Osten und sucht im Rubindrachenschrein nach dem Flieder.\n\nEine Sache noch: Wie alle Drachenschreine in dieser verfluchten Einöde so wird auch dieser Drachenschrein von der Geißel heimgesucht. Passt also auf, wo Ihr hintretet. Wir wollen doch nicht, dass Ihr von einem Glutwyrm verschlungen werdet.\n\n<Sintar lacht.>", progress = "Habt Ihr den rubinfarbenen Flieder dabei?", completion = "Das war doch nicht so schwer, oder?\n\nNun gebt mir ein wenig Zeit, damit ich den Impfstoff herstellen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12104] = {title = "Kehrt zu Soar zurück", objective = "Liefert Sintars Impfstoff bei Soar Falkenzorn in Agmars Hammer ab.", description = "<Doktor Malefius gibt Euch eine Phiole, die mit einer trüben Flüssigkeit gefüllt ist.>\n\nBitte schön, <Volk>. Bringt das hier wieder zu diesem Rindvieh und lasst es wissen, dass damit alle Schulden beglichen sind. Wir sind nun ganz offiziell wieder quitt.\n\nLasst mich allein, bevor ich Jennings auf Euch loslasse.", progress = "Habt Ihr den Impfstoff dabei?", completion = "&lt;Soar hält die Phiole in die Höhe und überprüft seinen Inhalt.&gt;\n\nBleibt nur noch eine Sache zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12105] = {title = "Abstieg in die Dunkelheit", objective = "Bringt Mikhails Tagebuch zu Leutnant Dumont bei der Ammertannhütte.", description = "Das Tagebuch wurde von einem Einwohner Silberwassers namens Mikhail geschrieben. Es beschreibt die Ankunft einer Gruppe von Schattenanbetern, die sich \"Wolfskult\" nannten.\n\nZunächst waren die Dorfbewohner zögerlich, sich dem Kult anzuschließen, aber mit der Zeit gab es mehr und mehr Sympathisanten unter der Bevölkerung.\n\nBeunruhigt dadurch, schickte Mikhail seine Tochter Dasha aus Silberwasser fort, und er versuchte, vernünftig mit den Dörflern zu reden.\n\nSein letzter Eintrag erwähnt eine Versammlung der Dorfoberen, um nicht näher beschriebene Ereignisse in der Hohlsteinmine zu diskutieren.", progress = "Was habt Ihr da?", completion = "Ich dachte mir doch, dass es mehr damit auf sich hat, als lediglich ein isoliertes Dorf voller Feinde.\n\nWir haben ein paar Männer in der Nähe der Hohlsteinmine, vielleicht lohnt es sich ja, sich dort ein wenig umzusehen.", rewards = "Zurückgelassener HelmWeggeworfenes BergarbeiterwamsGeflickte TrapperschulterstückeRostige HöhlenstampferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12106] = {title = "Durchsucht Indu'le", objective = "Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen.", description = "Ich bin mir sicher, dass Ihr den nächsten Leylinienfokus irgendwo in den Überresten von Indu'le im Südosten finden werdet. Das Problem ist nur, dass ich überhaupt keine Meldungen darüber erhalten habe, ob es dort einen gibt oder nicht.\n\nIch möchte, dass Ihr Euch im Dorf nach irgendwelchen Hinweisen über den Fokus oder die Magierjäger und ihren Kommandanten in der Gegend umseht.\n\nSucht auch im See nach, wenn es sein muss!", progress = nil, completion = "An dieser Stelle findet Ihr die Leiche des Kommandanten der Magierjäger.\n\nNach seinem Aussehen und dem Zustand der Truppen um ihn herum zu urteilen, scheinen sie nicht ertrunken zu sein. Vielmehr erweckt die Szene den Eindruck, als hätten sie den Angriff der Elementare aus den Rissen im Seebett nicht erwartet.\n\nDem Anschein nach waren die Magierjäger für ihr eigenes Ableben verantwortlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12107] = {title = "Endstation", objective = "Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.\n\nKehrt danach zum Abbild der Erzmagierin Modera in Sternenruh zurück.", description = "In seinen Roben findet Ihr zwei Dinge von Interesse.\n\nZum einen handelt es sich um einen Talisman, der eindeutig zur Steuerung eines Fokus dient. Zum anderen um eine Sammlung mehrerer Befehle, die von jemand namens Sidragos ausgestellt wurden und letztendlich für den Anführer in den Mondruhgärten gedacht waren.\n\nLaut Anordnung auf dem nassen Pergament, soll Goramosh all seine Magierjägertruppen nach Osten zum Azurdrachenschrein beordern.\n\nVielleicht solltet Ihr so viel wie möglich von dem Fokus erfahren und dann nach Osten gehen, um den Drachenschrein von der westlichen Seite her beobachten zu können.", progress = nil, completion = "WAS?!\n\n&lt;Einen Augenblick lang verzerrt sich das Abbild vor Euch, während die Erzmagierin versucht, ihre Fassung wiederzugewinnen.&gt;\n\nAber natürlich, wir hätten eigentlich wissen müssen, dass sie das die ganze Zeit über vorhatten. Schnell, es gibt keine Zeit zu verlieren.\n\nWyrmruh muss gewarnt werden!", rewards = "Stab des LeyheilersDaschals ausrangiertes MesserStreitkolben des violetten WächtersManagetränkte KlaueAuf Euch wartet eine dieser Belohnungen:\n\nFoliant des Violetten Turms\n\nDer folgende Zauber wird auf euch gewirkt:\n\nThe End of the Line: Quest Complete\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12108] = {title = "Mikhails Grab", objective = "Bringt Mikhails Notiz zum Kartografen Tobias bei der Ammertannhütte.Der Erdhaufen ist in Wahrheit ein hastig gebuddeltes Grab. Der darin befindliche Körper ist nicht mehr erkennbar, aber Ihr findet eine Notiz, die ihn als Mikhail identifiziert.\n\nDie Notiz erwähnt erneut die Holhsteinmine. Vielleicht kennt sich bei der Ammertannhütte jemand in der Gegend aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Erdhaufen ist in Wahrheit ein hastig gebuddeltes Grab. Der darin befindliche Körper ist nicht mehr erkennbar, aber Ihr findet eine Notiz, die ihn als Mikhail identifiziert.\n\nDie Notiz erwähnt erneut die Holhsteinmine. Vielleicht kennt sich bei der Ammertannhütte jemand in der Gegend aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12109] = {title = "Meldet Euch bei Gryan Starkmantel... schon wieder", objective = "Sprecht mit Hauptmann Gryan Starkmantel im Lager der Westfallbrigade.", description = "Die Jungs von Westfall wurden nach Osten geschickt, um einen Weg in die nördlichen Territorien zu finden. Ihr zweites Missionsziel ist das Sicherstellen von strategisch wichtigen Ressourcen - ich bin mir also sicher, dass es ihnen nichts ausmachen würde, eine Mine zu untersuchen.\n\nSucht nach dem Lager der Westfallbrigade weit im Nordosten und sucht nach Gryan Starkmantel. Ihr werdet Euch vielleicht noch an ihn erinnern können, wenn Ihr jemals schon in Westfall gewesen seid. Sagt ihm auf jeden Fall, dass ich Euch geschickt habe.\n\nEr wird Euch nur zu gerne erlauben, eine intakte Mine für den König in Besitz zu nehmen.", progress = nil, completion = "Dumont hat Euch geschickt? Schön. Sehen wir einmal, was Ihr für uns tun könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12110] = {title = "Endstation", objective = "Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.\n\nKehrt danach zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück.", description = "In seinen Roben findet Ihr zwei Dinge von Interesse.\n\nZum einen handelt es sich um einen Talisman, der eindeutig zur Steuerung eines Fokus dient. Zum anderen um eine Sammlung mehrerer Befehle, die von jemand namens Sidragos ausgestellt wurden und letztendlich für den Anführer in den Mondruhgärten gedacht waren.\n\nLaut Anordnung auf dem nassen Pergament, soll Goramosh all seine Magierjägertruppen nach Osten zum Azurdrachenschrein beordern.\n\nVielleicht solltet Ihr so viel wie möglich von dem Fokus erfahren und dann nach Osten gehen, um den Drachenschrein von der westlichen Seite her beobachten zu können.", progress = nil, completion = "WAS?!\n\n&lt;Einen Augenblick lang verzerrt sich das Abbild vor Euch, während der Erzmagier versucht, seine Fassung wiederzugewinnen.&gt;\n\nAber natürlich, wir hätten eigentlich wissen müssen, dass sie das die ganze Zeit über vorhatten. Schnell, es gibt keine Zeit zu verlieren.\n\nDer Wyrmruhtempel muss gewarnt werden!", rewards = "Stab des LeyheilersDaschals ausrangiertes MesserStreitkolben des violetten WächtersManagetränkte KlaueAuf Euch wartet eine dieser Belohnungen:\n\nFoliant des Violetten Turms\n\nDer folgende Zauber wird auf euch gewirkt:\n\nThe End of the Line: Quest Complete\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12111] = {title = "Wo die wilden Tiere wohnen", objective = "Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr mithilfe der Packung mit Impfstoffen 5 Schneewehenelche und 5 arktische Grizzlys impft.", description = "In dieser Packung befinden sich mehrere Phiolen mit dem von Sintar hergestellten Gegengift. Nun möchte ich, dass Ihr die Wälder in der Nähe nach Schneewehenelchen und arktischen Grizzlys absucht. Werft, wenn Ihr eines der Tiere gefunden habt, eine Phiole in deren Nähe. Die Phiole wird zerspringen und ein dünnes Gas freisetzen, das als Impfstoff dienen wird. Die Tiere müssen lediglich in die Gaswolke hineingehen, um geimpft und letztendlich gerettet zu werden.\n\nVerabreicht den Impfstoff so vielen Tieren wie nur möglich und kehrt anschließend zu mir zurück.", progress = nil, completion = "Ihr habt etwas Ehrenhaftes getan, &lt;Name&gt;. Ich bitte Euch, sucht Euch eine Belohnung aus.", rewards = "RubinholzstabStab der MondruhgärtenScharfe Klinge des WaldlandsStachelkeule von KaltwindKampferprobter MagnataurenzermalmerArmbrust des gestählten WaldläufersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12112] = {title = "Erstarrte Verhandlungen", objective = "Geht zum Zentrum der Kristallschlucht und sucht Zort auf.", description = "Nun, es scheint, als hättet Ihr Euch letztendlich doch ein wenig nützlich gemacht. Meiner Erfahrung nach, gibt es nicht viele Eures Volkes, die das von sich behaupten können.\n\nWir haben hier keine Verwendung mehr für Euch. Geht zur Kristallschlucht und seht nach, ob mein Bruder Zort ein helfendes Händchen gebrauchen könnte. Er wollte die Riesen davon überzeugen, ob sie nicht ihr Leben lassen wollen, damit wir's nicht tun müssen. In unserer Familie galt er nicht gerade als der Klügste.", progress = nil, completion = "Ich lass mir was einfallen, wie Ihr Euch nützlich machen könnt - bleibt noch ein Weilchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12113] = {title = "Ohne Fleisch kein Preis", objective = "Harkor in Harkors Lager möchte, dass Ihr 10 Stück feinfasriges Worgfleisch von den streunenden Grauheulern und 10 Schaufelhornsteaks von den Langhufgrasfressern beschafft.", description = "Guten Tag, <Klasse>! Wollt Ihr Euch nicht an mein Feuer setzen?\n\nIch würde Euch zwar eine gute, heiße Mahlzeit anbieten, nur habe ich keine. Ich sitze hier fest und warte auf einen Kumpanen, ansonsten würde ich mich selbst um die Sache kümmern.\n\nIhr scheint mehr als genug Zeit übrig zu haben und in dieser Gegend gibt es eine Menge Fleisch. Was würdet Ihr davon halten, wenn Ihr mir helfen und etwas zu Essen beschaffen würdet?", progress = "Mein Bauch knurrt, <Volk>. Konntet Ihr etwas zu Essen beschaffen?", completion = "Ausgezeichnet!\n\nNichts schmeckt besser zum Bier als ein heißes Stück Fleisch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12114] = {title = "Therapie", objective = "Harkor in Harkors Lager möchte, dass Ihr 10 Drakkaribeschützer und 10 Drakkariorakel außerhalb der Ruinen von Drakil'jin tötet.", description = "Trolle… Ich hass'se alle! <Harkor spuckt.>\n\nIch hab's ja mal geschafft, so 'ner Bande von Bestien in die Hände zu fallen… War so nah dran, mir meinen Kopf schrumpfen zu lassen!\n\nMeine Freunde sagen mir, ich solle einfach weitermachen und das alles hinter mir lassen, aber das geht einfach nich'.\n\nWollt Ihr wissen, was mich glücklich machen würde, <Volk>? 'Nen Haufen ihrer Leichen zu sehen, so hoch, dass er die Sonne verdunkelt! Ich hab' gutes Gold für Euch, wenn Ihr das möglich macht.", progress = nil, completion = "Habt Dank, &lt;Klasse&gt;.\n\nWenn es die Zeit erlaubt, werd' ich aufsteh'n und mal ein bisch'n herumschauen.", rewards = "Kilt der friedlichen RückgewinnungTherapeutischer UmhangGamaschen der AggressionstherapieHandschützer der AuslöschugBrustschutz des ausgedrückten ZornsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12115] = {title = "Koltira und die Sprache des Todes", objective = "Bringt den fleischgebundenen Folianten zu Koltira Todesweber.", description = "Es gibt einen, der sich vor Kurzem unserer Sache verschrieben hat, jemanden, der diesen Folianten womöglich entschlüsseln kann. Ein freier Todesritter hat sich vorübergehend hier in Agmars Hammer niedergelassen. Einst stand er im Dienste von Arthas und war ein Mitglied der Geißel - vielleicht ist er dazu imstande, die Sprache der Toten zu übersetzen.\n\nNehmt den fleischgebundenen Folianten, bringt ihn zu Koltira und bittet ihn, die Seiten zu übersetzen.", progress = "Was ist, <Volk>?", completion = "Es gibt nur zwei Dinge im Leben, die mich interessieren, Peon, und einen Folianten der Geißel für Euch zu übersetzen, gehört nicht dazu.\n\nJedoch... vielleicht könnte sich ja was arrangieren lassen, das uns beiden zugute kommt.\n\n&lt;Koltira zieht sein Schwert aus der Scheide.&gt;\n\nDas ist meine Runenklinge Bifrost - und Bifrost durstet es nach dem Blut des Lichkönigs und seiner Diener; doch zuerst muss ich Runen der Macht auf seine Klinge einprägen: Symbole des Frosts, des Blutes und des Unheiligen. Bringt mir die passenden Quellen der Macht und ich werde Euren Folianten übersetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12116] = {title = "Man braucht schon einen starken Magen...", objective = "Kraz in Harkors Lager möchte, dass Ihr Euch in die Ruinen von Drakil'jin begebt und 5 Drakkarikanopen einsammelt.", description = "Seid gegrüßt, <Klasse>. Nett von Euch, anzuhalten und Euch Kraz' Geschichte anzuhören.\n\nSeit vielen Jahren bemüht sich Kraz, die Geister zu hören und ihre Wünsche zu erfüllen.\n\nIn letzter Zeit hat Kraz viele Stimmen aus diesen Ruinen rufen gehört. Sie streben nach Frieden, den sie alleine nicht finden können.\n\nWenn Ihr den Geistern derer, die zuvor gekommen sind, helfen wollt, so betretet die Gruft und sammelt etwas, das einst diesen gequälten Seelen gehörte.", progress = "Was habt Ihr in der Gruft für Kraz gefunden, <Klasse>?", completion = "Innereien? Eine interessante Wahl, &lt;Volk&gt;.\n\nKraz soll mal sehen, was man alles von ihnen lernen kann. Danke, dass Ihr Euch in die Tiefen dieses Ortes gewagt und der Gefahr getrotzt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12117] = {title = "Reist zum Hafen Moa'ki", objective = "Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit dem Ältesten Ko'nani.", description = "<Volk>, gerade erhielten wir Kunde aus dem Hafen Moa'ki. Heute Morgen ist dort etwas sehr schreckliches passiert!\n\nIhr wart uns hier eine große Hilfe. Würdet Ihr auf das Boot steigen und in Richtung Drachenöde reisen?\n\nSo wie sich die Dinge anhören, könnte Ältester Ko'nani mit Sicherheit Eure Hilfe gebrauchen.", progress = nil, completion = "Was sagt Ihr, &lt;Volk&gt;? Hotawa hat Euch geschickt?\n\nGut, gut... es gibt viel zu tun. Wir können jede Hilfe, die man uns anbietet, gebrauchen!", rewards = "Kilt des wandernden HeilersHandschutz der WindesweitenHaltbares WorgfellcapeAuf Euch wartet eine dieser Belohnungen:\n\nHalsreif des Nordwindes\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12118] = {title = "Reist zum Hafen Moa'ki", objective = "Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit Häuptling Ko'nani.", description = "<Volk>, gerade erhielten wir Kunde aus dem Hafen Moa'ki. Heute früh ist dort etwas sehr Schreckliches passiert!\n\nIhr wart uns hier eine große Hilfe. Wäre es denkbar für Euch, auf das Boot zu steigen und in Richtung Drachenöde zu reisen?\n\nSo wie sich die Dinge anhören, könnte Häuptling Ko'nani mit Sicherheit Eure Hilfe gebrauchen.", progress = nil, completion = "Was sagt Ihr mir da, &lt;Volk&gt;? Anuniaq hat Euch geschickt?\n\nGut, gut... es gibt viel zu tun. Wir können jede Hilfe, die sich uns bietet, gebrauchen!", rewards = "Kilt des wandernden HeilersHandschutz der WindesweitenHaltbares WorgfellcapeAuf Euch wartet eine dieser Belohnungen:\n\nHalsreif des Nordwindes\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12119] = {title = "Eine Audienz erhalten", objective = "Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab.", description = "<Name>, Ihr müsst so schnell, wie Ihr könnt, zum Wyrmruhtempel reisen und dem Bediensteten Tariolstrasz diesen Brief überreichen.\n\nDer Tempel liegt im Zentrum der Drachenöde. Folgt der Straße in östliche Richtung bis zu ihrem Ende und durchquert die Dracheneiswüste, um dorthin zu gelangen.\n\nWenn der Bedienstete Euer Vorstellungsschreiben erst einmal gesehen hat, wird er Euch sicherlich eine Audienz bei Königin Alexstrasza beschaffen, denke ich. Wir können nur darauf hoffen, dass es nicht schon zu spät ist.\n\nIch danke Euch für all das, was Ihr für uns getan habt. Gute Reise!", progress = "Ja? Was kann ich für Euch tun, <Volk>?", completion = "Ein Vorstellungsschreiben und Gesuch um ein Treffen mit der Königin? Zeigt einmal her.\n\nWas auch immer Euer Anliegen auch sein mag, ich hoffe es ist wichtig. Der Himmel wimmelt heute nur so von angreifenden Blauen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12120] = {title = "Schlaghammer von Drak'aguul", objective = "Kraz in Harkors Lager möchte, dass Ihr Drak'aguul außerhalb der Ruinen von Drakil'jin tötet und mit dem Schlaghammer von Drakil'jin zurückkehrt.", description = "Verderbnis...\n\nKraz hatte sie sogar schon spüren können, bevor Ihr die Töpfe brachtet. Die Verderbnis erfüllt die uralten Drakkarigeister mit großer Angst und hält sie davon ab, die Ruhe zu finden, nach der es sie verlangt.\n\nKraz wird nicht lügen, <Klasse>. Diesen Ort zu reinigen wird ein großes Opfer abverlangen, doch darüber werden wir ein anderes Mal sprechen.\n\nUnter den Lebenden hier befindet sich einer, der den Schlüssel zu seiner Läuterung in Händen hält. Sucht Drak'aguul auf und bringt Kraz seinen Schlaghammer.", progress = "Habt Ihr den Schlaghammer gefunden, <Name>?", completion = "So weit, so gut, &lt;Name&gt;, doch nun kommt die wahre Prüfung.", rewards = "Schulterpolster des GlöcknersTaillenschutz der zweckdienlichen BeschaffungPolierter HirschhornhelmStulpen des HammerschwingersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12121] = {title = "Wir sehen uns auf der anderen Seite wieder", objective = "Kraz in Harkors Lager möchte, dass Ihr den Schlaghammer von Drakil'jin auf die Gongs außerhalb der Ruinen von Drakil'jin anwendet. Ihr sollt die Ruinen betreten, sobald Ihr erschlagen wurdet, und mit dem Geist von Gan'jo sprechen, solange Ihr tot seid.", description = "Diese Drakkari sind Euch eindeutig mit barbarischer Feindschaft begegnet. Ihr schuldet ihnen gar nichts. In der Tat sind es nur Wenige, welche die Aufgabe, die Kraz heute von Euch verlangt hat, ausführen würden.\n\nUm diesen Ort zu reinigen und die Geister ihrer letzten Ruhe zu übergeben, müsst Ihr sie im Reich des Todes wiedertreffen.\n\nIn der Krypta ist jemand, der Euch auf der anderen Seite erwartet. Er hat die Informationen, die wir benötigen, <Name>.\n\nSchlagt die Gongs mit dem Hammer. Der Geist dessen, der diesen Ort verderbt, wird Euch mit Sicherheit in die Geisterwelt befördern.\n\nKraz erwartet Eure Wiederkehr.", progress = nil, completion = "Euer Kommen wurde vorhergesagt, &lt;Klasse&gt;. Es ist gut, dass Ihr gekommen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12122] = {title = "Eine Audienz erhalten", objective = "Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab.", description = "<Name>, Ihr müsst so schnell wie Ihr könnt zum Wyrmruhtempel reisen und dem Bediensteten Tariolstrasz diesen Brief überreichen.\n\nDer Tempel liegt im Zentrum der Drachenöde. Folgt der Straße in östliche Richtung bis zu ihrem Ende und durchquert die Dracheneiswüste, um dorthin zu gelangen.\n\nWenn der Bedienstete Euer Vorstellungsschreiben erst einmal gesehen hat, wird er Euch sicherlich eine Audienz bei Königin Alexstrasza beschaffen, denke ich. Wir können nur darauf hoffen, dass es nicht schon zu spät sind.\n\nIch danke Euch für all das, was Ihr für uns getan habt. Gute Reise!", progress = "Ja? Was kann ich für Euch tun, <Volk>?", completion = "Ein Vorstellungsschreiben und Gesuch um ein Treffen mit der Königin? Zeigt einmal her.\n\nWas auch immer Euer Anliegen auch sein mag, ich hoffe, es ist wichtig. Der Himmel wimmelt heute nur so von angreifenden Blauen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12123] = {title = "Die Königin verständigen", objective = "Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab.", description = "<Der Drachenwächter zieht Euer Vorstellungsschreiben aus dem Ärmel.>\n\nJa... ja, ich meine, dass Ihr jetzt zur Königin gehen könnt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde dafür sorgen, dass einer dieser Drachen Euch sicher zur obersten Etage des Tempels bringen wird. Ihr werdet Euren Brief persönlich an Königin Alexstrasza überreichen müssen.", progress = "Schön, Euch endlich persönlich kennenzulernen, <Name>. Ich kannte Euch schon, da wart Ihr noch nicht geboren.", completion = "Ihr habt viel Mut, uns diese Informationen zu bringen. Ich habe mich schon gewundert, weshalb der blaue Drachenschwarm einen so waghalsigen Angriff auf den Tempel selbst eingeleitet hat. Nun wissen wir, dass sie riesige Mengen genau der Magie verwenden, die ihrer Ansicht nach eine Bedrohung für Azeroth darstellt.\n\n&lt;Die Königin schüttelt ihren Kopf, scheinbar vor Ratlosigkeit.&gt;\n\nScheinheilig, aber was soll's. Wenn Malygos nicht wieder zur Vernunft kommt, haben wir keine andere Wahl, als auf ihren Angriff Taten folgen zu lassen.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12124] = {title = "Die Königin verständigen", objective = "Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab.", description = "<Der Drachenwächter zieht Euer Vorstellungsschreiben aus dem Ärmel.>\n\nJa... ja, ich meine, dass Ihr jetzt zur Königin gehen könnt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde dafür sorgen, dass einer dieser Drachen Euch sicher zur obersten Etage des Tempels bringen wird. Ihr werdet Euren Brief persönlich an Königin Alexstrasza überreichen müssen.", progress = "Schön, Euch endlich persönlich kennenzulernen, <Name>. Ich kannte Euch schon, da wart Ihr noch nicht geboren.", completion = "Ihr habt viel Mut, uns diese Informationen zu bringen. Ich habe mich schon gewundert, weshalb der blaue Drachenschwarm einen so waghalsigen Angriff auf den Tempel selbst eingeleitet hat. Nun wissen wir, dass sie riesige Mengen genau der Magie verwenden, die ihrer Ansicht nach eine Bedrohung für Azeroth darstellt.\n\n&lt;Die Königin schüttelt ihren Kopf, scheinbar vor Ratlosigkeit.&gt;\n\nScheinheilig, aber was soll's. Wenn Malygos nicht wieder zur Vernunft kommt, haben wir keine andere Wahl, als auf ihren Angriff Taten folgen zu lassen.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12125] = {title = "Im Dienste des Blutes", objective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Blutgemme auf die verstörten Bewohner von Indu'le anwendet und sie gefüllt wieder zu ihm zurückbringt.", description = "Einst stillte das Blut Unschuldiger den Durst der Klinge - doch leider bietet sich mir diese Möglichkeit nicht mehr.\n\n<Koltira hält inne und denkt nach.>\n\nWir müssen improvisieren. Südlich von hier, oben auf den hohen Klippen befindet sich das Tuskarrdorf Indu'le. Erst kürzlich wurde es vom blauen Drachenschwarm mit seiner chaotischen Magie überrannt, was die dort heimischen Tuskarr in den Wahnsinn trieben.\n\nNehmt diese Blutgemme hier und wendet sie auf die geistig verwirrten Dorfbewohner an. Wenn ich das Blut Unschuldiger schon nicht haben kann, dann soll mir das Blut der Sanftmütigen gehören!", progress = "Bringt mir das Blut der Sanftmütigen.", completion = "Eine simple Aufgabe für jemanden so simpel, wie Ihr es seid. Ihr habt meine Erwartungen erfüllt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12126] = {title = "Im Dienste des Unheiligen", objective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die unheilige Gemme auf Fürst Vallenhal anwendet und sie gefüllt wieder zu ihm zurückbringt.", description = "Die Macht des Unheiligen ist unter meinesgleichen begehrt. Sie ist Grundlage unserer Existenz und gewährt jenen den Tod, die es wagen sollten, sich darüber zu mokieren! Glücklicherweise gibt es einen Quell, der mich in Zeiten der Not mit Energie versorgt.\n\nNehmt diese unheilige Gemme und macht Euch auf den Weg zum östlich gelegenen Rubindrachenschrein. Dort werdet Ihr auch Fürst Vallenhal, einen von Arthas' Todesrittern, finden. Schwächt ihn im Kampfe und entfesselt dann die Macht der Gemme. Sie wird ihm den Rest geben und ihm seine unheilige Energie nehmen!", progress = "Füllt die Gemme mit unheiliger Macht!", completion = "&lt;Koltira macht große Augen.&gt;\n\nBeeindruckend. Ihr habt einen von Arthas' Todesrittern besiegt... Sicherlich wart Ihr nicht allein... doch immerhin...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12127] = {title = "Im Dienste des Frosts", objective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Frostgemme auf die Eisklagegeister anwendet und sie gefüllt zu ihm zurückbringt.", description = "Die beißende Kälte beschützt den Todesritter und hält seine Feinde fern. Er beherrscht die Macht des Frosts, bringt Chaos und Zerstörung!\n\nNehmt diese Frostgemme und durchquert die Tundra der Drachenöde, bis Ihr den Spiegel der Morgenröte östlich des Wyrmruhtempels erreicht. Dort, auf dem zugefrorenen See, werdet Ihr Euch Legionen von Eisklagegeistern stellen müssen und ihnen die Essenz des Frosts abnehmen. Bedient Euch der Macht der Gemme, sobald sie geschwächt sind, <Name>!", progress = "Hier in Nordend stehen wir alle im Dienste des Frosts.", completion = "Ich spüre, &lt;Name&gt;, wie mich die Kälte durchströmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12128] = {title = "Seht mal nach Raegar", objective = "Sprecht mit Raegar Brechbraue im Prospektorat.", description = "Bei all der Aufregung um die Armee, die versucht, durch Thor Modan zu ziehen, hätte ich Raegars Truppe unten beim Prospektorat beinahe vergessen.\n\nIch habe Raegar und seine Assistenten gemeinsam mit einem Bergsteigerfreund dorthin geschickt, um einen kleinen Posten in der Nähe von Dun Argol am südlichen Zipfel der Ostwindküste zu errichten.\n\nSie wollten die Eisenzwerge ausspionieren, die sich in den südlichen Hügeln aufhalten, doch ich habe noch nichts von ihnen gehört. Könntet Ihr einmal nachsehen, ob es ihnen gut geht, wenn Ihr schon in diese Richtung unterwegs seid?", progress = nil, completion = "Hmm... Ihr seht zwar nicht wie ein Forschungsassistent aus, doch das macht nichts. Die Eisenzwerge bereiten sich auf einen Krieg vor und mein Forschungsteam ist noch nicht zurückgekehrt. Wir könnten hier etwas Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12129] = {title = "Der perfekte Plan", objective = "Bringt Raegar Brechbraue im Prospektorat die kompletten Blaupausen für einen Kriegsgolem.", description = "Die Eisenzwerge machen keinen Hehl daraus, dass sie Kriegsvorbereitungen treffen. Mit ihren Riesen, Golems und Blitzelementaren haben sie den technologischen Vorteil gegenüber der Westfallbrigade. Sollte es ihnen nicht rechtzeitig gelingen, einen Weg in den Norden zu finden, könnten die Eisernen sie überraschen.\n\nWir müssen sie hier halten und ich weiß auch genau den richtigen Weg dafür. Dun Argol ist voller Runenschmiede, die am Fließband Kriegsgolems produzieren. Sie tragen die Pläne für die spezifischen Teile bei sich, also müsst Ihr alle Stücke finden und zusammensetzen.", progress = "Ist es Euch gelungen, die Pläne von den Runenschmieden zu bekommen?", completion = "Ihr habt sie alle? Exzellent! Ich kann es kaum abwarten, den Ausdruck auf ihren Gesichtern zu sehen, sobald der Golem fertig ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12130] = {title = "Lieber requirieren als produzieren", objective = "Bringt 8 Teile eines Kriegsgolems zu Raegar Brechbraue im Prospektorat.", description = "Wir haben die Blaupausen, aber ohne entsprechende Bauteile können wir nichts damit anfangen! Wir haben keinen Zugang zu einer Schmiede, zu Materialien noch viel weniger. Aber es gibt in Dun Argol eine ganze Ladung Materialien.\n\nEuer Job?\n\nGebt ihnen ein neues Zuhause.\n\nVermutlich sind sie um die Gebäude, in denen die Eisenrunenschmiede arbeiten, herum verteilt. Würde mich nicht wundern, wenn die Runenschmiede ein wenig gereizt reagieren, wenn Ihr ihnen die Früchte ihrer harten Arbeit stehlt. Je mehr Ihr bringen könnt, desto besser wird dieser Golem.", progress = "Ich sehe, dass Ihr es in einem Stück da raus geschafft habt. Habt Ihr die Teile?", completion = "&lt;Raegar wischt sich mit der Handfläche über die Stirn.&gt;\n\nOh, nein. Das wird härter, als ich dachte. Diese Dinger haben keine Seriennummern oder ähnliches, wie?\n\nWann immer man einen Gnom braucht, ist keiner da…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12131] = {title = "Wir haben die Macht", objective = "Bringt Durars Energiezelle und Kathorns Energiezelle zu Raegar Brechbraue im Prospektorat.", description = "Wir sind fast da, doch der Kriegsgolem will ohne Energie nicht funktionieren. Den Informationen nach, die ich in Argul sammeln konnte, bevor wir entdeckt wurden, erschaffen Runenschmied Durar und Runenschmied Kathorn jeweils eine Energiezelle.\n\nWir werden eine Energiezelle von jedem Runenschmied benötigen, um unseren Golem zum Laufen zu kriegen.\n\nDie Runenschmiede sollten in ihren Werkstätten auf der zentralen Ebene von Dun Argol zu finden sein.", progress = "Nun, habt Ihr diese Energiezellen dabei?", completion = "&lt;Raegar nimmt Euch die Batterien ab.&gt;\n\nAusgezeichnet! Wir sollten jetzt loslegen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12132] = {title = "Die Macht zu Zerstören...", objective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Welt der Schatten betretet und 6 schattenhafte Peiniger besiegt.\n\nSprecht mit Koltira Todesweber, solltet Ihr die Welt der Schatten wieder betreten müssen.", description = "Ihr habt zwar schon viel für mich getan, doch eine Sache bleibt noch.\n\nNeben der Euch bekannten Welt existiert eine zweite, die Welt der Schatten, die Welt meiner Peiniger - von wo aus sie mich beständig angreifen. Nun bin ich meinen eigenen Dämonen gegenüber machtlos, doch Ihr könntet ihrer Herrschaft des Schreckens ein Ende setzen. Ihr besitzt die Stärke, ich habe es mit meinen eigenen Augen gesehen.\n\nBegebt Euch in die Welt der Schatten und stellt Euch den Dämonen, die mich quälen!\n\nTut dies und ich werde den Folianten wie versprochen übersetzen.", progress = nil, completion = "Die Macht, die ich besitze hat ihren Preis, &lt;Name&gt;. Viele Ritter, ob des Lichts oder der Dunkelheit, ließen in der letzten Schlacht bei der Kapelle des hoffnungsvollen Lichts ihr Leben. Die Zukunftsaussichten sehen schlecht aus, doch zumindest weiß ich jetzt, was mich erwartet. Der Lichkönig wird mich nie gänzlich aus seinem Griff entlassen und für das allein muss er sterben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12133] = {title = "Zermatsch den Kürbis", objective = "Bring das versengte, heilige Symbol zur kostümierten Waisenmatrone.", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", progress = "Ja, <Name>?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, &lt;Name&gt;. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\n Eines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", rewards = "Ihr bekommt:\n\nKrude verpacktes Geschenk"}
MultiLanguageQuestData['de'][12134] = {title = "Sashas Jagd", objective = "Sasha möchte, dass Ihr nach Julheim geht und dort 12 Jäger von Julheim tötet.", description = "Dieses Ding... dieser Fluch... der sich auf Silberwasser und Julheim auswirkt... er verwandelt mein Volk in Bestien.\n\nMein Vater hat versucht, sie zu warnen, doch stattdessen hörten sie alle lieber auf den Wolfskult.\n\nSie sind nun schon zu lange verwandelt - es ist Zeit, sie auszuschalten... um ihrer selbst willen.", progress = nil, completion = "Diese Monster zu töten, wird meinen Vater nicht zurückbringen... doch das spielt jetzt keine Rolle, oder?", rewards = "Wappen des WolfstötersBlutiges BollwerkStab der rechtschaffenen VergeltungAuf Euch wartet eine dieser Belohnungen:\n\nSzepter der leidenschaftlichen Vergeltung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12135] = {title = "\"Lasset die Feuer kommen!\"", objective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht, nachdem der kopflose Reiter diese entzündet hat. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", description = "Ihr müsst uns helfen! Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, <Name>, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", progress = nil, completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", rewards = "Ihr bekommt:\n\nSüßes SauresGewichtige KürbislaterneKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][12136] = {title = "Der übersetzte Foliant", objective = "Liefert den übersetzten fleischgebundenen Folianten bei Hauptmann Gort in Agmars Hammer ab.", description = "Hier ist es, <Name>. Ich habe alles, was auf den Seiten des Folianten geschrieben steht, übersetzt. In seinem Inneren befindet sich eine Liste, auf der die Namen aller Anhänger des Kults der Verdammten geschrieben stehen, die es auf diesem Kontinent gibt.\n\nIhr Netzwerk an Spionen und Agenten ist gelinde gesagt beeindruckend.\n\nLebet wohl, <werter Freund/werte Freundin>. Möge das Buch Euch und Eurem Volke gut dienen.", progress = "Es wurde auch langsam Zeit! Wo seid Ihr nur gewesen?", completion = "&lt;Gort nimmt Euch den Folianten ab und fängt an zu lesen.&gt;\n\nWAS! Das kann nicht stimmen. Ein paar dieser Orcs kenne ich nun schon seit Jahren!\n\nLasst mich alleine, &lt;Name&gt;. Ich habe viel Arbeit zu tun und viele Verräter hinzurichten.\n\nNehmt einen dieser Gegenstände als Entschädigung für den Ärger, der Euch bereitet wurde. Ihr habt der Horde heute einen großen Dienst erwiesen.", rewards = "Kopfbedeckung des EiswüstenhauchsBrustplatte des SchneewehenhäschersBeinlinge aus Anub'architinHelm des steinigen PfadesIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12137] = {title = "Ganz ruhig, Mann", objective = "Gan'jo möchte, dass Ihr den Schnee des ewigen Schlafes von seiner Kiste in den Ruinen von Drakil'jin nehmt.\n\nIhr müsst den Schnee bei den dortigen uralten Drakkarigeistern einsetzen und anschließend die Partikel der Drakkarigeister zurück zu Kraz in Harkors Lager bringen.", description = "Es is', wie die Prophezeiung sagte, Mann. <Ein/Eine:r> <Volk> kommt, um unsre Geister zur Ruhe zu bring'n. Wir warten jetzt schon lange Zeit!\n\nDie Drakkari sind 'n verlor'nes Volk geworden, grimmig und wild.\n\nAber es is' allein unsre Schuld, Mann. Dieser Ort muss geläutert werd'n und nur die Lebenden können das machen.\n\nRed' wieder mit mir, wenn du bereit bist, in deinen Körper zurückzukehren. Nimm dann den Schnee aus der Truhe hier neben mir un' bring meine Brüda in den Schlaf.\n\nBring ihre Überreste zu deinem Geisterführer, der weiß, was als Nächstes zu tun is'.", progress = "Habt Ihr Eure Aufgabe in der Krypta erledigt, <Klasse>?", completion = "Gute Arbeit.\n\nBitte, setzt Euch und hört zu. Es gibt viele Dinge, die wir besprechen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12138] = {title = "... oder vielleicht doch nicht", objective = "Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt anschließend zu Raegar Brechbraue im Prospektorat zurück.", description = "Man könnte meinen, dass die Jungs, die diese Energiezellen hergestellt haben, auch daran gedacht hätten, sie aufzuladen - aber nein, sie müssen die Sache komplizierter machen.\n\nNun gut, wir werden diese Zellen auf die schwierige Art und Weise aufladen. In ihnen ist zwar genug Energie gespeichert, um den Golem für kurze Zeit zum Laufen zu bringen, doch erwartet nicht von ihm, dass er auch gut im Kämpfen ist.\n\nKönnt Ihr die Blitzwachen sehen, die von den Eisenzwergen an der Grenze von Dun Argol postiert wurden? Nehmt den Golem mit, geht nah an sie heran, zerstört die Wachen und lasst den Golem ihre Energie absorbieren.", progress = nil, completion = "Endlich ist er bereit. Ich hoffe nur, dass er so lange zusammenhält, bis die Arbeit getan ist. Wenn wir den in Dun Argol kommandierenden Than nicht ausschalten, dann wird Hauptmann Gryan eine böse Überraschung erleben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12139] = {title = "\"Lasset die Feuer kommen!\"", objective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der maskierten Matrone, sobald alle Feuer erloschen sind.", description = "Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen!\n\nBitte, <Name>, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", progress = nil, completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", rewards = "Ihr bekommt:\n\nSüßes SauresGewichtige KürbislaterneKürbisdrops der Schlotternächte"}
MultiLanguageQuestData['de'][12140] = {title = "Ein Hoch auf Roanauk!", objective = "Geht nach Agmars Hammer, sucht Roanauk Eisnebel auf und macht ihn zu einem Mitglied und Anführer der Hordestreitkräfte.\n\nKehrt anschließend mit dem Blutschwur der Horde zu Oberanführer Agmar zurück, sobald Ihr diese Aufgabe abgeschlossen habt.", description = "Wie die Tauren, die Verlassenen, Trolle und Blutelfen, so brauchen auch die Taunka einen Anführer, der von ihrem eigenen Blute abstammt. Der eine, den Ihr aus Eisnebel befreit habt - Roanauk -, wird dieser Anführer sein.\n\n<Oberanführer Agmar überreicht Euch ein Pergament.>\n\nIch gebe Euch etwas, das Ihr schon kennt - auf ihm steht der Blutschwur der Horde geschrieben.\n\nBringt das Pergament zu Roanauk Eisnebel und nehmt ihn als Anführer der Taunka in die Horde auf.\n\nLassen wir ihn nicht warten.\n\n<Agmar nickt Euch zu.>", progress = nil, completion = "Ein so mächtiger Schamane wird uns an der Pforte des Zorns sicherlich den Sieg bescheren!", rewards = "Ehrenhafter UmhangVersteinerter KnochenfußschutzAuf Euch wartet eine dieser Belohnungen:\n\nSonnenstrahlblumenSignet des Schwurs\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12141] = {title = "Eine diplomatische Mission", objective = "Sprecht mit Karuk am Strand der Peitschennarbe südwestlich der Valianzfeste.", description = "Ich sehe, dass Ihr sehr begierig drauf seid, zu helfen, <Name>. Ihr seid nicht den ganzen Weg nach Nordend gereist, damit Ihr Euch in einer Stadt verkriecht! Ich hab genau die richtige Aufgabe für Euch... etwas, das Euch weit weg von hier bringt.\n\nWir haben lange versucht, uns das Wohlwollen der in Nordend heimischen Tuskarr zu sichern. Neulich kam ein junger Tuskarr zu uns und ersuchte Hilfe, etwas, womit wir zu dieser Zeit nicht dienen konnten.\n\nJetzt, da Ihr da seid, könnt Ihr ihm vielleicht zur Hand gehen. Sucht nach Karuk in der Nähe des Strandes der Peitschennarbe südwestlich von hier und schaut, was Ihr für ihn tun könnt.", progress = nil, completion = "Ihr seid gekommen, um mir zu helfen? Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12142] = {title = "Schädlingsbekämpfung", objective = "Duane bei der Front der 7. Legion möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet.", description = "Uhh! Als wir uns um den letzten Drachen gekümmert haben, hat einer dieser kleinen Schneeboldwichte unser Lager verwüstet. Jedes Mal, wenn wir ihnen den Rücken kehren, bereiten sie uns irgendwelchen Ärger... Ich hab's satt!\n\nDie Schneebolde gen Süden verstecken sich hinter den örtlichen Magnatauren - hängen an ihren Rockzipfeln sozusagen. Geht und schlachtet sie nieder.\n\nUnd falls die Magnatauren für ihre Sklaven eintreten sollten, dann tötet sie auch.", progress = "Habt Ihr diese Schädlinge beseitigt?", completion = "Ein Glück, dass wir sie los sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12143] = {title = "Jagd durch die Schluchten", objective = "Duane möchte, dass Ihr die Schneebolde im Canyon nordöstlich der Front der 7. Legion verfolgt und Euch anschließend um deren Anführer kümmert.", description = "Ich kann es nicht fassen! Gerade wollte noch so eine Bande von diesem Gezücht mit unseren Vorräten abhauen. Sie machen sich in Richtung der nördlichen Schlucht davon. Verfolgt sie und kümmert Euch um ihren Anführer!", progress = nil, completion = "Kühlhauer, wie? Ich hab' den Namen schon mal gehört. Richtig gute Arbeit, &lt;Klasse&gt;. Hoffentlich können wir jetzt wieder unsere Aufmerksamkeit den Drachen zuwenden.", rewards = "Bedeckung des WyrmwärtersSchluchtenläuferwesteTaillenschutz des WyrmjägersHandgelenksschützer des WyrmbannsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12144] = {title = "Schädlingsbekämpfung", objective = "Kontokanis in Drachensturz möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet.", description = "Ai, Mann! Ein von dene kleine rattige Schneebolds hat bei die letzte Drachenangriff unsere Lager auf'n Kopp gestellt, Mann. Die sin' uns imma auf'n Fersen, sobald wir ihn' den Rücken zudreh'n. Un' ich hab genug! \n\nIm Osten vastecke'n die sich unter die Röcke von 'nen paar Magnataur'n, die hia leben. Geht un tut sie abschlacht'n. Un' wenn die Magnataur'n sich da für ihre Sklaven reinhäng'n tun, tötet sie auch, Mann.", progress = nil, completion = "Nich' schad' um die, Mann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12145] = {title = "Jagd durch die Schluchten", objective = "Kontokanis möchte, dass Ihr die Schneebolde in der Schlucht südlich von Drachensturz verfolgt und anschließend ihren Anführer beseitigt.", description = "Ich kann das nich' glauben! Noch 'ne Bande von dem Gezücht wollt' grad mit mea von unsere Vorräte abhau'n! Die flitzen grad runta in die Schlucht, lauft ihn' nach un' kümmat Euch um den ihr Chef!", progress = nil, completion = "Eisfaust, ai? Den Namen hab ich schon mal gehört. Das war mal gute Arbeit, Mann. Jetz' können wir Dunk'lspea uns hoff'ntlich wieda um die Drach'n kümman.", rewards = "Bedeckung des WyrmwärtersSchluchtenläuferwesteTaillenschutz des WyrmjägersHandgelenksschützer des WyrmbannsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12146] = {title = "Beunruhigende Hinweise", objective = "Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann.", description = "Die untere Seite des Horns schmückt ein Siegel, das einen Hammer und einen Blitz zeigt. Irgendetwas an diesem Horn wirkt bei einem Magnataur vollkommen fehl am Platze.\n\nGeht nach Süden den Pfad der Titanen entlang, bringt das Horn zum Wyrmruhtempel und sucht jemanden auf, der an diesen bedrohlichen Hinweisen Interesse haben könnte.", progress = "Ja, <Volk>?", completion = "Es ist für einen Magnatauren in der Tat seltsam, so einen Gegenstand bei sich zu tragen... und sehr beunruhigend. Ich bin froh, dass Ihr es mir gezeigt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12147] = {title = "Beunruhigende Hinweise", objective = "Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann.", description = "Die untere Seite des Horns schmückt ein Siegel, das einen Hammer und einen Blitz zeigt. Irgendetwas an diesem Horn wirkt bei einem Magnataur vollkommen fehl am Platze.\n\nGeht nach Osten, durchquert die Dracheneiswüste und bringt das Horn zum Wyrmruhtempel. Sucht dort jemanden auf, der an diesen bedrohlichen Hinweisen Interesse haben könnte.", progress = "Ja, <Volk>?", completion = "Es ist für einen Magnataur in der Tat seltsam, so einen Gegenstand bei sich zu tragen... und sehr beunruhigend. Ich bin froh, dass Ihr es mir gezeigt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12148] = {title = "Einzigartig", objective = "Findet und tötet Knochenkracher in der Nähe der Schlucht nordwestlich des Azurdrachenschreins. Bringt jegliche Informationen zurück zu Aurastrasza im Wyrmruhtempel.", description = "So ein seltsames Siegel bei einem Magnatauren... das lässt auf ungewöhnlich viel Organisation schließen.\n\nEs kommt nur selten vor, dass Magnatauren ihr aggressives Naturell beiseitelegen, um miteinander zu kooperieren. Ich vermute, dass sie ihre Aufmerksamkeit darauf gerichtet haben, einen Überfall auf eine große Siedlung zu starten.\n\nIch bezweifle sehr, dass dieses Horn einzigartig ist - Ihr müsst mich also vom Gegenteil überzeugen. In der Schlucht gen Nordwesten des Azurdrachenschreins befindet sich Knochenkracher. Geht, fordert ihn heraus und bringt mir irgendwelche Informationen, die meine Befürchtungen bestätigen könnten.", progress = "Habt Ihr irgendwas herausfinden können?", completion = "Es ist also wahr? Sie hätten sich für solch einen Angriff keinen besseren Zeitpunkt aussuchen können... zwischen der Geißel und dem blauen Drachenschwarm - es ist unwahrscheinlich, dass es sonst noch irgendjemand bemerkt hat.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12149] = {title = "Die mächtigen Magnatauren", objective = "Bringt Blutschmaus, Eisberster und Drachenblut, die sich östlich des Wyrmruhtempels befinden, zur Strecke.\n\nBlutschmaus wohnt im südöstlichen Bereich der Dracheneiswüste, gleich nördlich des Smaragddrachenschreins. Eisberster patrouilliert an der nördlichen Grenze des Spiegels der Morgenröte. Drachenblut wandert am Fuße der Klippen westlich des Bronzedrachenschreins umher.\n\nKehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Magnatauren erschlagen habt.", description = "Magnatauren sind furchtbar gewalttätige Kreaturen... das ist der eigentliche Grund dafür, weshalb man nie größere Ansammlungen von ihnen zu Gesicht bekommt, ohne dass sie sich gerade gegenseitig abschlachten. Irgendwo gibt es einen neuen mächtigen Anführer unter ihnen. Wir müssen ihm nachstellen, wenn wir dieser Bedrohung ein Ende setzen wollen.\n\nIch werde mich einmal umhören und möchte, dass Ihr sie in der Zwischenzeit so gut wie möglich ablenkt.\n\nÖstlich von hier wurden 3 Fackeln aufgestellt, in deren Nähe sich 3 dominante Magnatauren befinden. Schaltet sie aus und beschafft uns ein wenig Zeit, damit wir diesen Anführer zur Strecke bringen können.", progress = "Habt Ihr die Magnatauren schon besiegt?", completion = "Ausgezeichnete Arbeit. Niemand konnte mir zwar sagen, wer dieser Anführer nun sein könnte, doch ich habe den Namen von jemandem herausfinden können, der ihn uns verraten kann.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12150] = {title = "Der zurückgezogene Runenmeister", objective = "Sucht Dregmar Runenbrand auf. Er befindet sich in der Nähe seiner Höhle auf dem Weg zu den Klippen am Spiegel der Morgenröte. Fordert ihn heraus und tut, was notwendig ist, um den Namen des magnataurischen Anführers herauszufinden. Kehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Information erhalten habt.", description = "Dregmar Runenbrand ist ein magnataurischer Runenmeister... eine Seltenheit unter seinesgleichen. Er verbringt zwar die meiste Zeit allein, ist jedoch dafür bekannt, schon seit einiger Zeit mit den mächtigeren und einflussreicheren Magnatauren der Drachenöde zu verkehren. Er wird schon wissen, wer dieser neue Anführer sein soll.\n\nEs ist eher unwahrscheinlich, dass wir von ihm in irgendeiner Form Hilfe in Bezug auf die wachsende Bedrohung durch die Geißel und den blauen Drachenschwarm erwarten können, also möchte ich, dass Ihr alles Notwendige unternehmt, um die Informationen von Dregmar zu beschaffen.\n\nMir wurde gesagt, dass er sich auf den Klippen am Spiegel der Morgenröte aufhält.", progress = nil, completion = "Grom'thar der Donnerbringer. Gut. Lasst uns also dieser Magnataurenbedrohung hier und jetzt ein Ende setzen.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12151] = {title = "Rücksichtsloser Kriegsherr", objective = "Geht zum Fackelring südlich des Azurdrachenschreins und stoßt in das geschmückte Kriegshorn. Besiegt Grom'thar den Donnerbringer und bringt seinen Kopf zurück zu Aurastrasza im Wyrmruhtempel.", description = "Es gibt keinen Grund daran zu zweifeln, dass Dregmars Worte wahr sind. Ob nun Grom'thar Euch unterliegt oder Ihr von ihm besiegt werdet... Es macht keinen Unterschied: Er wird sich seine Hände reinwaschen können.\n\nFolgt seinen Anweisungen... nehmt das Horn, das Ihr mir zuvor gebracht habt, geht zum Fackelring südlich des Azurdrachenschreins und stoßt zum Zeichen der Herausforderung hinein.\n\nTötet anschließend Grom'thar den Donnerbringer und bringt mir seinen Kopf.", progress = "Habt Ihr diese Gefahr endgültig aus der Welt schaffen können?", completion = "Wirklich beeindruckend.\n\nNun da Grom'thar der Donnerbringer nicht mehr ist, können wir die restlichen Magnatauren sich gegenseitig bekämpfen lassen und unsere Aufmerksamkeit größeren Gefahren zuwenden.\n\nBeeindruckende Arbeit, &lt;Klasse&gt;.", rewards = "Emmes verlorene ZauberklingeTaigashaKurzklinge des RubinverbündetenRamponierte Dualklinge der MagnataurenLangbogen des RubinreitersAuf Euch wartet eine dieser Belohnungen:\n\nTalisman der Lebensbinderin\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12152] = {title = "Jin'arraks Ende", objective = "Kraz in Harkors Lager möchte, dass Ihr die heilige Drakkariopfergabe aus den Ruinen von Drakil'jin holt und den Drakkariseelenstaub darauf benutzt. Benutzt die beseelte Drakkariopfergabe bei den Gongs außerhalb der Ruinen von Drakil'jin.", description = "Es ist gut, Euch wieder unter den Lebenden begrüßen zu dürfen. Viele von denen, die auf dem Weg der Toten wandeln, kehren nicht zurück, um davon zu berichten.\n\nWährend Ihr weg wart, hatte Kraz eine Vision, die ihm offenbarte, was noch zu tun ist.\n\nIn der Gruft liegt noch irgendwo eine heilige Opfergabe. Nehmt diesen Seelenstaub, der aus den von Euch gesammelten Überresten gewonnen wurde und benutzt ihn auf der Opfergabe.\n\nDie mit dem Staub bedeckte Opfergabe wird dem verderbten Kriegsherren ein Ende bereiten und viele gepeinigte Seelen erlösen.\n\nMögen Euch die Geister Euch in Euren Handlungen leiten, <Name>.", progress = nil, completion = "Es ist vollbracht.\n\nEure Selbstlosigkeit hat vielen Seelen ewigen Frieden gebracht und Äonen der Qual beendet.\n\nMöge diese Tat Eure eigene Seele erleuchten und die Bürden, die Ihr tragt, leichter machen, denn ich sehe, dass Ihr noch viele Gefahren bestehen müsst.\n\nLebt wohl, &lt;Name&gt;.", rewards = "Gezackter TrollreißerAxt des besiegten KriegslordsSchnabeldolchGezackter KalteisenschlitzerAuf Euch wartet eine dieser Belohnungen:\n\nZweig der aufschlussreichen TräumeGlühende Voodookugel\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12153] = {title = "Der Eisenthan und sein Amboss", objective = "Setzt die Fähigkeiten Eures Kriegsgolems ein, besiegt den Eisenthan Zornhammer und kehrt dann zu Raegar Brechbraue im Prospektorat zurück.", description = "Nun, da Ihr Euren Kriegsgolem aufgeladen habt, werden wir all diese Energie einer guten Sache zuführen. Aktiviert den Golem innerhalb von Dun Argol, um ihn zu kontrollieren.\n\nWir haben Informationen, dass Dun Argols Anführer, Eisenthan Zornhammer, von seinem Leibwächter rund um die Uhr beschützt wird.\n\nDieser Leibwächter ist das Konstrukt, mit dem er reist. Er wird der Amboss genannt. Setzt das Konstrukt außer Gefecht und sein Schutz wird vernichtet.\n\nDer Than befindet sich in dem Gebäude an der obersten Stelle Dun Argols und überwacht vom untersten Geschoss aus die Produktion.", progress = nil, completion = "Es hat funktioniert?\n\n&lt;Raegar räuspert sich.&gt;\n\nIch meine… Natürlich hat es funktioniert! Das ist unglaublich!\n\nIn Zukunft werden Initianden der Forscherliga die Geschichte hören, wie Raegar Brechbraue, &lt;Name&gt; und ein Blechkasten von einem Golem den Than von Dun Argol besiegten!", rewards = "Geerdete HandschuheExzentrikerschiftungKurzschlussstiefelSchienbeinschützer des GolemreitersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12154] = {title = "Stromausfall", objective = "Benutzt Raegars Sprengstoff, um den Runenkraftkern in Dun Argol zu zerstören, und erstattet anschließen Bericht bei Raegar Brechbraue im Prospektorat.", description = "In der großen Halle an der Spitze von Dun Argol befindet sich die Energieversorgung für das ganze Gebiet. Wenn Ihr den Kraftkern zerstören könnt, wird es Dun Argol für einige Zeit lahm legen.\n\nKeine Energie bedeutet keine Golems, keine Wachposten und keine Blitzwaffen mehr.\n\nAls wir hier heraufgeschickt wurden, sagte man uns, dieser Sprengstoff sei für Ausgrabungen gedacht, aber dank Eisenthan Zornhammer musste die Forschung ja eingestellt werden. Wir können ihn vielleicht dennoch verwenden - er ist das einzig verfügbare Mittel, mit dem wir den Kraftkern zerstören können.", progress = nil, completion = "&lt;Raegar nickt anerkennend.&gt;\n\nIch kann's nicht mit ansehen, wie Sprengstoff auf den Müll wandert, und so erteilt er unseren Feinden sicher einen herben Rückschlag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12155] = {title = "Zermatsch den Kürbis", objective = "Bring das versengte, heilige Symbol zur maskierten Waisenmatrone.", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", progress = "Ja, <Name>?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, &lt;Name&gt;. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\n Eines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", rewards = "Ihr bekommt:\n\nKrude verpacktes Geschenk"}
MultiLanguageQuestData['de'][12156] = {title = "ABGELEHNT", objective = "Eskortiert den Gesandten der Allianz ins Dorf Silberwasser. Erstattet Leutnant Dumont bei der Ammertannhütte Bericht, sobald Ihr Eure Aufgabe abgeschlossen habt.Ich hätte eigentlich vor ungefähr einer Stunde in Richtung Nordwesten, nach Silberwasser, aufbrechen sollen. Meine Militäreskorte scheint sich zu verspäten.\n\nIch werde nicht zulassen, dass diese diplomatische Mission in Verzug gerät, nur weil ein neuer Rekrut verschlafen hat.\n\nWir verhandeln gerade ein Abkommen mit den Einheimischen und Pünktlichkeit ist von größter Bedeutung. Was meint Ihr? Wenn Ihr mich begleitet, so werdet Ihr fürstlich entlohnt werden für Eure Mühen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich hätte eigentlich vor ungefähr einer Stunde in Richtung Nordwesten, nach Silberwasser, aufbrechen sollen. Meine Militäreskorte scheint sich zu verspäten.\n\nIch werde nicht zulassen, dass diese diplomatische Mission in Verzug gerät, nur weil ein neuer Rekrut verschlafen hat.\n\nWir verhandeln gerade ein Abkommen mit den Einheimischen und Pünktlichkeit ist von größter Bedeutung. Was meint Ihr? Wenn Ihr mich begleitet, so werdet Ihr fürstlich entlohnt werden für Eure Mühen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12157] = {title = "Der vermisste Kurier", objective = "Sprecht mit Kurier Lanson in Sternenruh in der Drachenöde.", description = "Wir können uns glücklich schätzen, es bis hierher geschafft zu haben, <Name>. Wir wurden von der Geißel aus dem Hinterhalt angegriffen, als wir anlandeten.\n\nWie sich herausstellte, war einer meiner Männer ein Spion des Kults der Verdammten. Thassarian scheint mehr Beweise über die Infiltration durch die Kultisten zu haben. So wie es aussieht, zieht sich das ganze bis in die Spitze.\n\nIch habe einen meiner besten Kuriere auf den Weg zu unserem Außenposten in der westlichen Drachenöde geschickt, doch er ist noch nicht zurückgekehrt. Werdet Ihr in die Drachenöde reisen und nach ihm suchen? Kurier Lanson ist sein Name.", progress = nil, completion = "Als ich die Brücke überquerte, die in die Drachenöde führte, wurde ich aus dem Hinterhalt von einer Gruppe Anub'ar angegriffen! Ich war umzingelt! Diese Scheusale wussten, dass ich kommen würde. Ich konnte gerade noch meine Haut retten. Diese Liste, die ich in Händen halte, muss nach Wintergarde gebracht werden, doch meine Wunden sind zu schwer, als dass ich die Reise schaffen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12158] = {title = "Hohlsteinmine", objective = "Sucht nach Hinweisen in der Hohlsteinmine, nordwestlich vom Lager der Westfallbrigade.", description = "Ich wollte eigentlich ein paar unserer Jungs losschicken, um nach der Hohlsteinmine zu sehen. Hatten aber noch keine Gelegenheit - alle Hände voll zu tun mit der Horde im Westen und den Eisenzwergen im Osten.\n\nWenn allerdings Dumont Euch gesandt hat, kann ich Euch wenigstens in die richtige Richtung schicken.\n\nIhr findet den Eingang zur Mine nicht weit von hier im Nordwesten. Versucht einzuschätzen, ob es sich lohnt, dort zu operieren. Wir könnten die zusätzlichen Ressourcen gut gebrauchen, solange unsere Mine in Fernhain geschlossen ist.", progress = nil, completion = "Ihr seid gekommen, um mir zu helfen, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12159] = {title = "Seelenunfrieden", objective = "Petrov bei der Hohlsteinmine möchte, dass Ihr mit der Minenarbeiterlaterne die Leichen von 8 Minenarbeitern der Hohlsteinmine verbrennt.", description = "<Petrov wirkt zutiefst verstört, atmet schwer und lässt seinen Blick nervös über die Mine schweifen.>\n\nMeine Kameraden... wir müssen ihren Seelen Frieden gewähren! Ich töte sie und töte sie, aber... sie kommen einfach zurück!\n\nErst hatte ich ja eine Idee, aber ich denke nicht, dass ich den Mut habe, sie selbst auszuführen.\n\nVielleicht könnt Ihr das für mich tun? Nehmt diese Laterne und verbrennt mit ihrem Öl die Leichen, damit sie nicht wieder aufstehen.\n\nIch beantworte Eure Fragen später. Helft erst meinen Freunden!", progress = "Habt Ihr meinen Freunden Frieden gewährt, <Name>?", completion = "Ruhet in Frieden, Freunde! Seid unbesorgt - ich erzähle allen, dass wir niemals aufgegeben haben!", rewards = "Spezialbehandelte RobenBärenlederhelmFellgefütterter BrustschutzKnochenpanzer des GefallenenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12160] = {title = "Ein Name aus der Vergangenheit", objective = "Kehrt zu Hauptmann Gryan Starkmantel im Lager der Westfallbrigade zurück.", description = "Es hat funktioniert! Es hat funktioniert! Meine Kameraden können endlich ihre wohlverdiente Ruhe genießen. Wir, die Bergleute von der Hohlsteinmine, bringen immer unsere Arbeit zu Ende - wir geben niemals auf!\n\nAus diesem Grund hat Arugal an uns auch ein Exempel statuiert. Wir wollten uns nicht fügen, müsst Ihr wissen. Wir wollten uns nicht seinem Wolfskult anschließen!", progress = nil, completion = "Verflucht soll unser Glück sein. Wir finden die einzige Mine auf dieser Seite der Hügel, die noch intakt ist, und sie ist voller Diener der Geißel.\n\nNichts für ungut, mein Freund. Doch es hört sich so an, als sei der Überlebende, den Ihr gefunden habt, durch den Verlust seiner Freunde ein wenig verstört. Arugal ist schon seit Jahren tot... Ich habe einst sogar sein Grab gesehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12161] = {title = "Ruuna die Blinde", objective = "Sprecht mit Ruuna der Blinden in Ruunas Lager in der Nähe des Vordrassilpasses.", description = "He, Ihr. Ich habe zufällig gehört, was Ihr da dem Hauptmann erzählt habt und wollte Euch nur sagen… Die Dinge sind nicht ganz so einfach in Nordend.\n\nNur weil jemand tot ist, heißt das nicht, dass er ganz verschwindet.\n\nSüdwestlich von hier, in der Nähe des Vordrassilpasses, lebt eine blinde Frau, die unter dem Namen Ruuna die Blinde bekannt ist. Man sagt, dass sie mit den Toten spricht und Visionen von der Vergangenheit und der Zukunft hat.\n\nIch habe nicht alles von Eurer Geschichte mitbekommen, aber es hört sich an, als könnte sie für Euch von Interesse sein.", progress = nil, completion = "Euch verlangt es nach Wissen, das Ihr nicht selbst erlangen könnt, deswegen seid Ihr zu mir gekommen. Doch muss ich Euch warnen, Fremder, womöglich wird es Euch nicht gefallen, was ich zu sagen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12162] = {title = "Julheim", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12163] = {title = "Das Böse lauert am Meeresgrund", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12164] = {title = "Stunde des Worgen", objective = "Sasha im Handelsposten Weißkiefer möchte, dass Ihr zur Blutmondinsel geht und Selas, Varlam, Blutschlund und den Schatten von Arugal tötet.", description = "Es ist wohl Zeit, <Name>. Arugal muss besiegt werden.\n\nNehmt ein paar Leute mit, denen Ihr vertrauen könnt, und geht zur Blutmondinsel gleich hier im Osten vor der Küste.\n\nWir werden schnell zuschlagen. Schaltet Arugals Leutnants aus - ich komme dann zu Euch, wenn es Zeit ist, das Monster höchstpersönlich zu erlegen.", progress = nil, completion = "Wir haben ihn gut erwischt, &lt;Name&gt;. Doch nicht gut genug.\n\nEine Sache ist jedoch sicher... In dieser Gegend werden wir ihn nicht mehr zu Gesicht bekommen.", rewards = "Worgreißende SchulterstückeScharfe MesserklauenschiftungFellbesetzte WorgtöterschiftungZahnbrechender SchulterschutzKnochenpolierte EisplattenschulternIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12165] = {title = "Ein faszinierender Plan", objective = "Bringt die vollständige Blaupause für die Kriegsgolems zu Ausgrabungsleiter Rokar in Camp Oneqwah.", description = "Ausgrabungsleiter Rokar hat sich entschieden, uns zu helfen. Er hat einen Plan erarbeitet, die Stärke der Eisenzwerge gegen sie zu wenden.\n\nIch muss zugeben, dass unser 'Freund' einsichtiger ist, als ich ihm zugetraut hätte. Er hat Recht, wenn er sagt, dass wir zu wenige sind, um einen direkten Angriff wagen zu können.\n\nReist nach Dun Argol, in die verschneiten Regionen im Südosten, und stehlt alle Blaupausenteile für ihre Kriegsgolems von den Runenschmieden dort. Bringt die vollständige Blaupause zu Rokar und wir werden sehen, ob sein Plan Wert hat.", progress = "Habt... habt Ihr die Blaupausen, die ich brauche?", completion = "Also will Tormak den Plan in die Tat umsetzen? Ich vermute, er hätte Euch nicht geschickt, wenn er das nicht wollte.\n\nOh Mann… wie kriege ich bei all dem Druck nur heraus, wie das Ganze zusammengesetzt werden muss?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12166] = {title = "Das flüssige Feuer Elunes", objective = "Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, das flüssige Feuer Elunes zu nutzen, um die Kadaver von 6 verseuchten Elchen und 6 tollwütigen Grizzlys zu läutern.", description = "Werdet Ihr mir beistehen, <Volk>?\n\nDie Geißel ist weiter nach Norden vorgedrungen, nach Eisnebel. Wohin auch immer sie ziehen, sie verbreiten ihr Übel und alle Kreaturen leiden.\n\nNehmt diese Phiole, sie ist mit dem flüssigen Feuer Elunes aus dem Mondbrunnen gefüllt. Bitte, nutzt dieses Elixier und läutert die Kadaver der toten Wildtiere, die ihr findet.", progress = nil, completion = "Wir haben für die Kreaturen dieses Landes getan, was möglich war. Jetzt müssen wir direkte Schritte gegen jene unternehmen, die das alles verursacht haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12167] = {title = "Tötet die Kultisten", objective = "Sammelt für Aufseherin Jodi Mondweise 5 funktionstüchtige Kultistenanzüge und bringt sie zu ihr nach Sternenruh.", description = "Die Kultisten der Anub'ar sind indirekt für die Verseuchung der Tiere hier verantwortlich und wir müssen dem ein Ende setzen!\n\nDie Dämpfe, die aus den Anzügen der Kultisten quellen durchsickern alles, dem sie sich nähern, vergiften und verderben ihre Umgebung.\n\nIhr müsst nach Eisnebel im Norden gehen und sie töten. Bringt mir all die Anzüge, die Euren Angriff unbeschadet überstehen, und ich werde mich darum kümmern, dass diese fachgerecht entsorgt werden.", progress = "Diese Kultisten sind eine der Geißeln der Schöpfung!", completion = "Gut gemacht.\n\nIch werde diese widerwärtigen Kleider im Mondbrunnen waschen und sie mit der Macht der Mondgöttin vernichten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12168] = {title = "Zangus Ehrengabe", objective = "Bringt Zangus Ehrengabe zu Aufseherin Jodi Mondweise in Sternenruh.", description = "Eine Inschrift auf der Rückseite der Ehrengabe gibt kund:\n\n\"Gewidmet meinem Lieblingsschüler,\n\nSolltest du weiterhin derart vielversprechende Talente zeigen, werde ich dich Wunder lehren, die deine kühnsten Träume übersteigen.\n\nSolltest du nicht, werde ich deine Entsorgung in Auftrag geben.\n\nMit den besten Wünschen,\n\nHochkultist Zangus\"\n\nOhne Zweifel wird die Aufseherin in Sternenruh die Ehrengabe sehen wollen.", progress = "Etwas Verderbtes ist nah, ich spüre es.\n\nIhr tragt dieses Unheil mit Euch! Was ist es, <Name>?", completion = "So, der Anführer der Kultisten hat sich also selbst entlarvt. Wir haben einen Namen.\n\nEitelkeit und Stolz werden sein Untergang sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12169] = {title = "Der Hochkultist", objective = "Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, Hochkultist Zangus zu töten.", description = "Ich habe bereits von Zangus geträumt, doch ohne den Kontext, den Ihr mir hier liefert, wusste ich nicht, was es zu bedeuten hat. Ihr habt Klarheit in die Vision gebracht, mit der mich die Göttin segnete und ich weiß nun, dass wir ihn im Norden, in der Grube von Narjun finden werden.\n\nIhr kennt unser Ziel, <Name>. Wenn wir dem Leiden des Landes ein Ende setzen wollen, muss der Hochkultist sterben!", progress = "Ich spüre, dass Hochkultist Zangus noch am Leben ist.\n\nIst etwas nicht in Ordnung, <Name>? Vielleicht müsst Ihr Euch erst ausruhen?", completion = "Nun, da der Hochkultist vernichtet ist, kann der Rest seiner Streitkräfte von diesem Landstrich gefegt werden und die Tiere werden sich erholen.\n\nVielen Dank, &lt;Name&gt;. Möge die Göttin Eure Pfade erhellen.", rewards = "Gamaschen des EiswüstenhauchsBeinlinge des SchneewehenhäschersHelm aus Anub'architinBrustschutz des steinigen PfadesIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12170] = {title = "Keilerei in Schwarzwasser", objective = "Räuberhauptmann Kronn möchte, dass Ihr 10 Einheiten oder Spieler der Allianz beim Holzfällerlager von Schwarzwasser tötet.", description = "Kurz nachdem wir angekommen sind, hat die Venture Company ihren Betrieb eingestellt. Sie hatten ganz klar Angst davor, was wir mit Raffzähnen wie ihnen machen würden.\n\nNun da sie weg sind, sind ihre Holzfällerlager verlassen. Unsere Kriegsmaschinerie ist ein hungriges Biest... Ohne unsere Vorräte aufzustocken, werden wir es nicht zur Eiskrone schaffen.\n\nLeider scheint die Allianz denselben Gedanken zu haben und wir müssen sicherstellen, dass wir diejenigen sind, die obsiegen. Macht Euch auf den Weg zum Holzfällerlager und helft uns, den Allianzabschaum zu bekämpfen.", progress = "Habt Ihr die Hunde der Allianz umgelegt? Wir müssen siegen!", completion = "Gut gemacht, &lt;Name&gt;. Wir haben zwar noch nicht die volle Kontrolle über das Holzfällerlager, aber dank Euch sind wir dem Ziel, die Allianzwürmer zu zertreten, einen Schritt näher gekommen.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12171] = {title = "Von Verrätern und Verrat", objective = "Zeigt Palena Silberwolke in Sternenruh das Schreiben der Allianz.", description = "Die Liste, die in meinem Besitz ist, muss zu Oberkommandant Halford Wyrmbann gebracht werden. Er befehligt die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde.\n\nFalls einige der Verräter auf dieser Liste in Wintergarde stationiert sind... könnte das katastrophale Folgen haben.\n\nBeeilung, <Name>. Zeigt Palena Silberwolke hier in Sternenruh das Dokument und erklärt ihr Eure Mission. Sie wird Euch auf ihrem schnellsten Hippogryph zur Feste Wintergarde schicken!", progress = "Hallo, <Volk>.", completion = "&lt;Palena liest die Notiz.&gt;\n\nIhr werdet meinen schnellsten Hippogryph nehmen, &lt;Volk&gt;! Diese Informationen müssen unverzüglich Oberkommandant Wyrmbann übergeben werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12172] = {title = "Abstimmung auf Dalaran", objective = "Das Abbild der Erzmagierin Modera in Sternenruh möchte, dass Ihr Euch auf Nordends Leylinien abstimmt.", description = "Willkommen, <Magier/Magierin>.\n\nIhr müsst Euch mittlerweile schon gefragt haben, wo Dalaran ist und wie man dorthin kommt. Nun, ich werde Euch helfen.\n\nDoch bevor ich Euch beibringen kann, wie man sich zu unserer glorreichen Stadt hinteleportiert, müsst Ihr Euch auf Nordends Leylinien abstimmen - sonst würdet Ihr nämlich vernichtet werden.\n\nHier, nehmt diesen Abstimmungskristall und verwendet ihn in der Grube unter der Sognadel in den Mondruhgärten gen Westen; dann werdet Ihr bereit sein, den Zauberspruch zu lernen.", progress = nil, completion = "Nun gut. Wenn Ihr bereit seid, dann bin ich es auch.", rewards = "Ihr erlernt:\n\nTeleportieren: Dalaran\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTeleportieren: Dalaran\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12173] = {title = "Abstimmung auf Dalaran", objective = "Das Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer möchte, dass Ihr Euch auf Nordends Leylinien abstimmt.", description = "Grüße, <Magier/Magierin>.\n\nIhr müsst Euch mittlerweile schon gefragt haben, wo Dalaran ist und wie man dorthin kommt. Nun, ich kann Euch in der Sache helfen, wenn Ihr einen einfachen Test überstehen könnt.\n\nDoch bevor ich Euch beibringe, wie man sich zu unserer glorreichen Stadt teleportieren kann, müsst Ihr Euch auf Nordends Leylinien abstimmen - andernfalls würdet Ihr Euch nämlich selbst vernichten!\n\nHier, nehmt diesen Abstimmungskristall und verwendet ihn in der Grube unter der Sognadel in den Mondruhgärten gen Südwesten; dann werdet Ihr bereit sein, Euch meine Lehre anzueignen.", progress = nil, completion = "Also gut. Wenn Ihr denkt, dass Ihr bereit seid, dann lasst uns nicht viel mehr von meiner Zeit verschwenden.", rewards = "Ihr erlernt:\n\nTeleportieren: Dalaran\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTeleportieren: Dalaran\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12174] = {title = "Oberkommandant Halford Wyrmbann", objective = "Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", description = "<Palena gibt Euch das Schreiben zurück.>\n\nSchneesturm wird Euch zur Feste Wintergarde bringen, <Name>. Ich versichere Euch, dass das der schnellste Ritt wird, den Ihr je unternommen habt. Geht jetzt!", progress = "Was habt Ihr da, Soldat?", completion = "&lt;Der Oberkommandant liest das Schreiben durch und knüllt es dann zusammen.&gt;\n\nWisst Ihr, wo die Leute auf dieser Liste jetzt sind? Seht mal nach draußen, neben dem Eingangstor. Sie hängen von den Bögen.\n\nGhulköder...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12175] = {title = "Graue Worgbälge", objective = "Balghändler Jun'ik möchte, dass Ihr ihm 3 graue Worgbälge von Graunebeljägern in den nördlichen Wäldern bringt.", description = "Lass mich dir was sagen, Mann: Wenn du dafür verantwortlich bist, die Armeen der Horde auszurüsten, dann brauchst du 'ne Menge Bälge!\n\nEroberin Krenna, die Wölfin, die diesen Ort hier leitet, hat mir 'ne knappe Frist gesetzt. Wenn ich ihr gesamtes Regiment nicht bis Ende der Woche ausgerüstet hab', dann kann ich mit den Bären in der Grube spielen.\n\nHilf mir aus und ich zahle dir einen Spitzenpreis. Ich brauche Bälge von Graunebeljägern.\n\nDu findest sie in Gruppen überall im Norden, auf der Jagd nach Hirschen. Denk dran, Mann: Spitzenpreis!", progress = "Hast du die Bälge, Mann?", completion = "Du hast mein Leben gerettet, Bruder. Falls du an mehr Arbeit interessiert bist: Es gibt noch mehr, wo das herkam.", rewards = "Zurückgelassener HelmWeggeworfenes BergarbeiterwamsGeflickte TrapperschulterstückeRostige HöhlenstampferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12176] = {title = "Ein kleiner Ersatz", objective = "Balghändler Jun'ik möchte, dass Ihr ihm 6 Grizzlybälge bringt.", description = "Krenna wird Worgbälge für die ganzen Kleider brauchen. Für ihre Armee wird es jedoch nicht genug von den Bälgen geben - jetzt nicht und auch in Zukunft nicht.\n\nDiese Worgs - die sind dünn, Mann! Okay, ich sag dir, was wir machen... sofern du ein Geheimnis für dich behalten kannst.\n\nIm Osten von Voldrune gibt es Grizzlybären so fett wie Oger. Diese großen Bälge - die können wir benutzen!\n\nBeeil dich, <Bruder/Schwester>. Krenna ist nicht gerade für ihre Geduld bekannt.", progress = "Hast du die Bälge dabei, Mann?", completion = "Ich steh' in deiner Schuld, Mann. Nimm dies als Bezahlung.", rewards = "Spezialbehandelte RobenBärenlederhelmFellgefütterter BrustschutzKnochenpanzer des GefallenenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12177] = {title = "Jun'iks Vertuschung", objective = "Bringt dem Balghändler Jun'ik in der Burg Siegeswall in den Grizzlyhügeln 1 Kohlestück und 5 Portionen herkömmliches Mehl.", description = "Ah, wir ham ein kleines Problem. Grizzlyfelle... sin' braun, Mann!\n\nDenk nach... Denk nach!\n\nIch hab's, Mann! Es is' doch so: Grau is' schwarz und weiß durcheinander vermischt. Du besorgst mir ein bisch'n Kohle und ein bisch'n Mehl, ich werd' das alles mahlen und bestäub' die Felle damit. Das wird keinem auffallen!\n\nKohle gibt's in der Schmiede zum Verhütten und Mehl krichst du beim Versorger.", progress = "Hast du den Kram, Mann?", completion = "Hoffen wir das Beste, Mann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12178] = {title = "Lieferung für Krenna", objective = "Nehmt das Bündel Felle und bringt es zu Krenna in Burg Siegeswall.", description = "Das is' es, Mann. Lass uns diese Felle zu Krenna bringen und gucken, ob sie den Test besteh'n.\n\nHoffen wir, dass Krenna nix bemerkt, um unserer beider willen.", progress = "Habt Ihr eigentlich irgendeine Ahnung, mit wem Ihr sprecht?", completion = "Für wen haltet Ihr mich eigentlich? Diese Felle riechen nach Mehl!\n\nDies ist eine echte Beleidigung der Horde!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12179] = {title = "Specialization 1 [PH]", objective = "LOG: Complete this quest for Specialization 1.", description = "DESCRIPTION: Complete this quest for Specialization 1.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12180] = {title = "Die gefangenen Ausgrabungsleiter", objective = "Befreit die Ausgrabungsleiter Gann, Torgan und Varana, dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück.", description = "Raegar hat ein Team von Ausgrabungsleitern nach Dun Argol gesandt, um nach Artefakten und Informationen über die Geschichte der Siedlung zu suchen. Raegars Team hätte nie gedacht, dass so viele Feinde dort sein würden.\n\nSie werden gefangen gehalten, während die Eisenzwerge zum Krieg rüsten. Wir haben nicht genug Männer, um sie da herauszuboxen, und Raegar ist so sehr in seine Phantasien zur Vernichtung der Eisenzwerge versunken, dass er keine große Hilfe wäre.\n\nSomit liegt es an Euch, <Name>. Jeder der Eisen oder ihrer Diener könnte den Schlüssel zu den Zellen, in denen unsere Männer gefangen gehalten werden, bei sich tragen.", progress = nil, completion = "&lt;Gebirgsjäger Kilian hört Euch zu, als Ihr erzählt, was die entführten Ausgrabungsleiter zu berichten hatten.&gt;\n\nSie erwähnten Loken und einen Krieg gegen Steinriesen? Seid Ihr sicher?\n\nAlso waren Raegars Instinkte richtig. wir müssen einen Weg dort hinein finden und mehr über ihre Pläne herausbekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12181] = {title = "Gebt dem Zeugs einen Namen", objective = "Zeigt Tobias Sarkhoff in Neu-Agamand die Pesthauchprobe.", description = "Du meine Güte, wie lange ist es her? Wie lange arbeiten wir nun schon an dieser verdammten Seuche? Wir haben eine halbe Ewigkeit mit Fehlschlägen verbracht und wurden nun endlich mit Perfektion gesegnet. Dieses Zeugs... Es hat noch nicht einmal einen richtigen Namen! Diese Pest... wie Dunst - Hauch... Das ist es: PESTHAUCH! Dieser Pesthauch wird das Gewebe des Lebens selbst zersetzen!\n\n<Harris reicht Euch eine Phiole.>\n\nNun gut, findet den Fledermausführer Tobias und zeigt ihm diese Probe. Er wird Euch nach Gallgrimm bringen.", progress = "Eine Lieferung extrem tödlichen Giftgases nach Gallgrimm? Kommt nur näher!", completion = "Ähm, ja, Ihr könnt die Phiole bei Euch behalten. Ihr habt mein Vertrauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12182] = {title = "Nach Gallgrimm!", objective = "Liefert die Pesthauchprobe beim obersten Seuchenfürsten Middleton ab. Er befindet sich in Gallgrimm im Osten der Drachenöde.", description = "Für dich habe ich eine spezielle Fledermaus aufgetrieben, <Kumpel/Süße>. Auf ihr wirst du den schnellsten und sanftesten Ritt haben, den ich dir bieten kann. Sie wird dich direkt nach Gallgrimm bringen - und das mit Stil.\n\nÜbergib dann einfach die Phiole an den obersten Seuchenfürsten Middleton, nachdem du gelandet bist.", progress = "Ihr spielt also den Lieferjungen?", completion = "Oh, was für ein wundervoller Tag! Und seht, dort, gleich hinter dem Berg im Nordosten gibt es haufenweise Diener der Geißel, die wir ausradieren können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12183] = {title = "Überzeugende Verkleidung", objective = "Bringt eine Aufseheruniform zu Gebirgsjäger Kilian im Prospektorat.", description = "Wenn, wie Ausgrabungsleiterin Varana behauptet, manche Eisenzwerge mit diesem Loken kommunizieren können, dann sind es bestimmt die Vorarbeiter, denen dieses Privileg zukommt.\n\nWir müssen Euch da reinbekommen, damit Ihr rausfindet, was es damit auf sich hat, aber das wird nicht leicht. Zunächst braucht Ihr die richtige Uniform.\n\nDanach machen wir uns über das richtige Make-up Gedanken.\n\nFindet einen der Vorarbeiter in Dun Argol, tötet ihn und nehmt seine Uniform mit. Wenn Blut daran klebt, dann ist es Eure eigene Schuld.", progress = "Habt Ihr die Uniform bekommen?", completion = "&lt;Kilian nimmt Euch die Uniform ab.&gt;\n\nDamit sollte es klappen. Es bleibt keine Zeit, noch ein Namensschild mit '&lt;Name&gt;' anzunähen, aber wenn wir mit Euch fertig sind, sollte jeder, der Euch aus der Nähe betrachtet, Euch für einen echten Vorarbeiter halten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12184] = {title = "Fotosafari", objective = "Benutzt Kilians Kamera, um Bilder von 8 Eisenzwergen in Dun Argol aufzunehmen. Dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück.", description = "Nun, da wir die Uniform haben, brauchen wir noch einige Informationen, um Eure Verkleidung perfekt zu machen.\n\nRaegar hat diese Kamera mitgebracht, um die Entdeckungen des Teams zu dokumentieren, aber ich habe eine andere Verwendung im Sinn. Ich möchte, dass Ihr sie mit nach Dun Argol nehmt und mit ihr Bilder von den Eisenzwergen macht.\n\nNatürlich werden Eure Modelle nicht sonderlich kooperativ sein, daher müsst Ihr sie eventuell zunächst, ähm... \"beruhigen\". Bringt die Kamera mit den Bildern zurück, wenn Ihr fertig seid.", progress = "Habt ihr die Schnappschüsse gemacht?", completion = "Gut, das sollte ausreichen. Nun werde ich eine Verkleidung anfertigen können, die Euch zu einem waschechten Eisenzwerg machen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12185] = {title = "Setzt Eure beste Miene auf für Loken", objective = "Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und kehrt dann zu Gebirgsjäger Kilian im Prospektorat zurück.", description = "Mithilfe der Bilder, die Ihr gemacht habt, habe ich alles zusammenbekommen, was Ihr für Eure Aufseherverkleidung braucht. Ihr werdet einen feinen Eisenzwerg abgeben, wenn ich das mal sagen darf.\n\nNehmt die Verkleidung mit nach Dun Argol, verkleidet Euch damit und geht zum östlichsten Gebäude in der breiten mittleren Ebene der Stadt.\n\nDort solltet Ihr ein Podest sehen, wo der Than und die Vorarbeiter ihre Befehle von Loken erhalten. Aktiviert es, während Ihr verkleidet seid und erfahrt so viel wie möglich aus der Kommunikation.", progress = nil, completion = "Könnte es sein, dass Loken tatsächlich nicht übertreibt? Die Steine der Titanen und die Eisensöhne kämpfen gegeneinander um die Kontrolle der antiken Stadt Ulduar. Das ist Wahnsinn, &lt;Name&gt;, und es könnte unsere einzige Chance, die wahre Geschichte über das Volk der Zwerge zu erfahren, zunichte machen!", rewards = "Schiftung der VorsehungGürtel des scharfen GehörsSchulterpolster der bevorstehenden DesastersFlüsternde StampferIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12188] = {title = "Die Seuche der Verlassenen und du: Wie man nicht stirbt", objective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr ihm 10 ektoplasmische Überreste bringt.", description = "Wie genau nun die Seuche funktioniert, ist wohl kaum wichtig. Alles, was Ihr wissen müsst, ist, dass sie genau das macht, für was sie geschaffen wurde. Ich habe es zuwege gebracht, einen inaktiven Erregerstamm der Seuche künstlich herzustellen.\n\n<Middleton entkorkt die Phiole, setzt sie an die Nase und atmet ein.>\n\nSeht, mein Körper ist - zumindest größtenteils - unversehrt. Würdet Ihr das nun mit einem Agens vermischen, wären wir alle nichts weiter als ein Haufen klebriger Masse.\n\nAm Strand südlich von hier befinden sich die lächerlichen Geister einstiger Soldaten der Allianz. Zerstört sie und bringt mir ihre ektoplasmischen Überreste.", progress = "Die Überreste werden als Agens zur Aktivierung der Seuche dienen!", completion = "Das wird reichen, &lt;Name&gt;. Haben sich diese lächerlichen Welpen Euch gestellt oder haben sie Euch lediglich mit geisterhaften Sorgentränen überschüttet?\n\nAh, sie sind so ergreifend...", rewards = "Handlappen des EiswüstenhauchsGeisterzornbänderGürtel des geisterhaften EssenzGespensterschimmerbeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12189] = {title = "Schwachköpfe, wo man nur hinsieht!", objective = "Reist nach Gallgrimm in der Drachenöde und sprecht mit dem obersten Seuchenfürsten Middleton.", description = "Die Lieferung aus Neu-Agamand hätte schon letzte Woche in Gallgrimm ankommen und nach ein paar einfachen Feldversuchen bei mir abgeliefert werden sollen. Hierbei handelt es sich um etwas, das für die Horde unerlässlich ist - um den letzten Teil des \"Siegesmosaiks\" sozusagen.\n\n<Sintar seufzt.>\n\nEs ist ziemlich entmutigend, nur von Schwachköpfen und Trotteln umgeben zu sein!\n\nGeht nach Gallgrimm gleich an der östlichen Grenze der Drachenöde. Findet diesen Kasper Middleton und lasst ihn wissen, dass ich auf das Paket warte.", progress = nil, completion = "Wir sind auf ein kleines Problem gestoßen - ist auch NUR nebensächlich. Jeder, der mit der Seuche arbeiten wollte, ist einfach verdampft. Wir arbeiten gerade daran, die Formel ein klein wenig anzupassen, damit sie einen nicht gleich umbringt, wenn man auch nur einen Blick darauf werfen sollte. Die gute Neuigkeit ist, dass ich schon fast fertig bin!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12190] = {title = "Sagt hallo zu meinem kleinen Freund", objective = "Prigmon möchte, dass Ihr Harkors Zutaten zu Harkor in Harkors Lager bringt.", description = "Harkor wird hin und weg sein, wenn er diese erstklassig'n Zutat'n sieht. Das Einzige, was es noch zu tun gibt, is', sie zu ihm zu bringen.\n\nEr hat sein Lager anner östlichen Küste inner Nähe dieser spukenden Ruinen - Drakil'jin werd'nse genannt. Ihr werdet wahrscheinlich eher dort ankommen, weil ich mich um diese Leichen hier kümmern muss... außer, Ihr möchtet Euer Glück lieber beim Einbalsamieren versuch'n.", progress = "Was kann ich für Euch tun?", completion = "Nun denn! Der gute alte Prigmon hat Euch geschickt, nich' wahr?\n\nDas sollte genug für ein mächtig leck'res Essen sein. Fehlen nur noch ein paar Kleinigkeiten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12191] = {title = "Haut weg das Zeug!", objective = "Trefft A.L.K fünfmal mit dem Krug alkoholfreies Braufestbier und sprecht dann mit Bissel Schnellhub.", description = "Diese lästigen Dunkeleisenzwerge sind wieder da! Wir müssen sichergehen, dass Ihr Euch im Falle eines Falles verteidigen könnt. Noch viel wichtiger ist, wir müssen sichergehen, dass Ihr unser Eigentum verteidigen könnt!\n\nA.L.K. hier wartet auf ein bisschen Action, wie sieht es bei Euch aus? Trinkt von den Krügen alkoholfreies Braufestbier und werft sie dann auf A.L.K.! Trefft das Ziel fünfmal und sprecht dann wieder mit mir.", progress = "Ext den Krug und werft ihn dann auf A.L.K.! Ich denke, die Schläge machen ihr nichts aus. Sonst hätte ich sie ja nicht gestoh... äh... gebaut.", completion = "Wow... A.L.K. ist nicht kaputt gegangen... Hm... Wer hätte das gedacht?\n\nIch meine, hey, Ihr habt es geschafft! Eure Zielfertigkeit ist gut, zumindest gut genug, um bei der Verteidigung des Lagers zu helfen. Ich glaube, Ihr seid nun bereit, den Dunkeleisenzwergen gegenüberzutreten, wenn sie wieder aufkreuzen.", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][12192] = {title = "Dieses eine Mal, als ich betrunken war...", objective = "Sprecht mit Bissel Schnellhub im Braufestlager.", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Bissel und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", progress = nil, completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, &lt;Klasse&gt;, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Weiterhin noch viel Spaß auf dem Braufest.", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][12193] = {title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", objective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Braufestmarken einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...  \n\nooohhh.... oder seins...", rewards = "Ihr bekommt:\n\nBlauer Braufestkrug"}
MultiLanguageQuestData['de'][12194] = {title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", objective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Braufestmarken einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNa ja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", rewards = "Ihr bekommt:\n\nBlauer Braufestkrug"}
MultiLanguageQuestData['de'][12195] = {title = "Ein unerwarteter \"Gast\"", objective = "Bringt 5 ausgewachsene Hirschgeweihe zu Tormak dem Vernarbten in Camp Oneqwah.", description = "Eine kürzlich zurückgekehrte Jagdexpedition hat mehr als nur Wild ins Lager gebracht.\n\nSie sind auf einen verwundeten Zwerg gestoßen, der vor den Eisenzwergen aus der Feste von Dun Argol geflohen war. Er könnte Informationen haben, die wir gegen unseren uralten Feind verwenden können, aber bevor er von Nutzen für uns sein kann, müssen wir sein Fieber in den Griff bekommen.\n\nDie Geweihe des Silberfellhirschs, der in den nahen Wäldern zu finden ist, werden seit Langem zur Herstellung von Heilpackungen verwendet. Bringt mir genügend Geweihe, dann sehen wir mal, ob meine Heilpackung unseren 'Gast' wieder auf die Füße bekommt.", progress = "Habt Ihr die Geweihe dabei?", completion = "Das sollte reichen. Schauen wir mal, ob es funktioniert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12196] = {title = "Von Grund auf", objective = "Bringt Ausgrabungsleiter Rokar im Camp Oneqwah 8 Teile eines Kriegsgolems.", description = "Es bleibt nicht mehr genug Zeit, die Teile selbst zu schmieden, aber die Gießereien drüben in Dun Argol, südöstlich von hier, arbeiten Tag und Nacht und stellen Golemteile am laufenden Band her.\n\nIch glaube, Ihr solltet dorthin zurückgehen und genug davon einpacken, damit ich nach diesen Blaupausen einen Golem herstellen kann.\n\nVermutlich liegen sie um die Gebäude herum verstreut, in denen die Eisenrunenschmiede arbeiten.\n\nBitte beeilt Euch, <Name>. Dieser Tormak wartet nur darauf, seine Drohung wahrmachen zu können!", progress = "H-habt Ihr d-diese Golemteile mitgebracht?", completion = "&lt;Rokar wischt sich mit dem Handrücken über die Stirn.&gt;\n\nOh, dem Licht sei Dank. Er hat mir angedroht, mir kein Essen zu geben, bis Ihr zurück seid. Lasst uns diesen Stapel Teile sortieren und sehen, was wir daraus machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12197] = {title = "Wir haben die Macht", objective = "Bringt Durars Energiezelle und Kathorns Energiezelle zu Ausgrabungsleiter Rokar im Camp Oneqwah.", description = "Gut, nun haben wir die Hülle eines Golem, aber das reicht Tormak noch nicht. Er sieht nicht ein, dass diese Dinge sich nicht einfach von selbst zusammensetzen und magisch zu funktionieren anfangen! Wir brauchen Energiezellen, um ihn zum Leben zu erwecken.\n\nAls ich in Dun Argol war, ist mir aufgefallen, dass die Runenschmiede Durar und Kathorn diejenigen waren, die die Zellen angefertigt haben. Wir brauchen je eine Zelle von beiden, um unseren Golem aufzuladen.\n\nIhr solltet die Runenschmiede in ihren Werkstätten in der zentralen Ebene von Dun Argol finden.", progress = "Habt Ihr diese Energiezellen?", completion = "&lt;Rokar nimmt Euch die Batterien ab.&gt;\n\nSie sind fast leer, aber es wird ausreichen, um den Golem aufzuladen. Damit ist er aber noch lange nicht bereit für einen Kampf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12198] = {title = "... oder vielleicht doch nicht", objective = "Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt dann zu Ausgrabungsleiter Rokar in Camp Oneqwah zurück.", description = "Die Zellen des Golems haben gerade genug Energie, um auf unterster Stufe zu laufen, doch für die Kampfsysteme reicht es nicht.\n\nDie gute Nachricht ist, dass die Umgebung von Dun Argol von Blitzwachen bewacht wird. Mit deren Hilfe sollten wir in der Lage sein, die Waffensysteme des Golems aufzuladen.\n\nNehmt den Golem mit, bringt ihn nah an sie heran, wenn die Wachen sterben, wird er ihre Energie absorbieren.", progress = "Habt Ihr den Golem aufgeladen? Tormak wird wieder ungeduldig...", completion = "Nun kann sich Tormak nicht mehr beschweren. Mehr kann ich an dem Golem nicht mehr machen.\n\nSobald Ihr mit ihm eine Schneise durch Dun Argol geschlagen habt, wird mich diese zu groß geratene Kuh wohl gehen lassen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12199] = {title = "Nieder mit dem Eisenthan!", objective = "Besiegt den Eisenthan Zornhammer mithilfe Eures Kriegsgolems und kehrt dann zu Tormak dem Vernarbten im Camp Oneqwah zurück.", description = "Da der Golem nun vollständig aufgeladen ist, kann er gegen den Anführer in Dun Argol eingesetzt werden.\n\nAls ich Eisenthan Zornhammer observiert habe, wurde er stets von einem persönlichen Golem beschützt, der ihn von jeglicher Gefahr ferngehalten hat.\n\nDiese Konstruktion namens \"der Amboss\" kann sabotiert werden, so dass er seinen Schild fallenlässt. Benutzt die EMP-Fähigkeit Eures Golems, um genau das zu tun. Ihr solltet Euren Golem innerhalb Dun Argols aktivieren und kontrollieren können.\n\nDer Than hält sich oben im Hauptgebäude auf und überwacht von dort aus die Produktion unten.", progress = nil, completion = "Also hat der Ausgrabungsleiter sein Versprechen wahr gemacht? Gut. Ich habe mich schon gefragt, ob all dies Schnorren von Metallstücken und Klauen von Baumaterial zu irgendwas führen würde.\n\nEs ist eine Schande, dass er uns nicht mehr nützlich sein wird.", rewards = "Geerdete HandschuheExzentrikerschiftungKurzschlussstiefelSchienbeinschützer des GolemreitersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12200] = {title = "Smaragddrachentränen", objective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr 8 Smaragddrachentränen sammelt.", description = "Da nun das träge Exemplar des Seuchenpräparats fertiggestellt und wir das Aktivierungsagens in Händen halten, fehlt uns nur noch eine passende Hülle für die Komponenten.\n\nSüdwestlich von hier an der zentralen Küste der Drachenöde liegt der Smaragddrachenschrein. Im Inneren des Schreins findet Ihr die hart gewordenen Überreste der Träne eines grünen Drachen. Ich kenn' zwar nicht die ganze Geschichte, aber anscheinend weinen sie sehr viel, bevor sie sterben - stellt Euch vor.\n\nGeht zum Smaragddrachenschrein und sammelt Tränen.", progress = "Glücklicherweise befindet sich ein Ort in der Nähe, in dem es mehr als genug Smaragddrachentränen gibt. Ansonsten hätte ich Euch nach Feralas schicken müssen.", completion = "Ich glaube, dass wir die Seuche jetzt einem Feldversuch unterziehen können. Zufälligerweise wird die Feste Wintergarde gerade von der Zitadelle des Schreckens Naxxramas belagert. Nun kommen die lebenden Toten aus genau dem Boden hervor, auf dem Wintergarde erbaut wurde - begierig darauf, Kel'Thuzads Befehle auszuführen.\n\nDie Allianz ist, wie könnte es anders sein, zahlenmäßig und an Waffenkraft unterlegen. Die Leute, die im Mausoleum von Wintergarde ihre letzte Ruhe gefunden haben, wachen von Neuem auf und es verlangt ihnen nach Fleisch!\n\nVielleicht sollten wir ihnen mal eine Kostprobe unserer Seuche bescheren, was meint ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12201] = {title = "Des Aufsehers Schatten", objective = "Bringt eine Aufseheruniform zu Späher Vor'takh in Oneqwah.", description = "Hört sich an, als sei dieser Loken der Drahtzieher hinter den plötzlichen Kriegsvorbereitungen der Eisenzwerge.\n\nNur die höchstrangigen Eisenzwerge haben für gewöhnlich Zugang zu ihm, deshalb müssen wir Euch wohl zu einem Aufseher machen, um herauszufinden, was dort vor sich geht.\n\nIch habe einen Plan dafür, jedoch brauchen wir ein paar Sachen.\n\nSucht einen der Eisenrunenaufseher in Dun Argol im Südosten und nehmt ihm seine Uniform ab.", progress = "Habt Ihr die Uniform besorgt?", completion = "Das sollte funktionieren, jedoch bleibt da noch die Frage nach dem Rest der Verkleidung. Selbst diese verblödeten Metallzwerge erkennen einen Schwindler in einer gestohlenen Uniform.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12202] = {title = "Fotosafari", objective = "Benutzt Rokars Kamera, um in Dun Argol die Bilder von 8 Eisenzwergen aufzunehmen und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück.", description = "Jetzt müssen wir nur noch letzte Handgriffe anlegen, um Euch genauso abstoßend hinzukriegen, wie es die Eisenzwerge sind.\n\nAm ehesten schaffen wir das, indem wir Eure Verkleidung an den Visagen der echten Eisenzwerge ausrichten.\n\nAls Tormaks Jagdgruppe diesen missratenen Ausgrabungsleiter gefunden hat, haben sie ihm gleich mal die Kamera, die er dabei hatte, abgenommen. Jetzt ist wohl die Zeit gekommen, sie zu benutzen.\n\nNehmt sie mit nach Dun Argol, tötet einige Eisenzwerge und bannt ihre Visagen auf dieses Gerät. Bringt es zurück, sobald Ihr genügend Exemplare habt.", progress = "Habt Ihr diese Schnappschüsse?", completion = "Das sollte reichen. Bei Garrosh, sind diese Kreaturen abstoßend!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12203] = {title = "Lokens Befehle", objective = "Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und erstattet dann Späher Vor'takh im Camp Oneqwah Bericht.", description = "Ich habe auch alles Andere, was Ihr für Eure Aufseherverkleidung benötigt, hergestellt. Bitte, versucht nicht zu würgen, wenn Ihr sie anlegt.\n\nNehmt die Sachen mit, wenn Ihr in den Südosten nach Dun Argol geht, benutzt sie, um Euch zu verkleiden, und geht dann zu dem Gebäude im äußersten Osten auf der breiten mittleren Ebene der Stadt.\n\nDort solltet Ihr ein Podest sehen, auf welchem der Than und die Aufseher ihre Befehle von Loken erhalten. Aktiviert es, während Ihr verkleidet seid, und sammelt so viele Informationen wie möglich.", progress = nil, completion = "Er hat also vor, einen Bürgerkrieg zwischen den verschiedenen titanischen Schöpfungen heraufzubeschwören? Warum bedeutet ihm die Titanenstadt Ulduar so viel? Ich nehme an, dass es dies ist, was Kurun und seine Riesen zu verhindern hoffen.\n\nNun ja, ich bezweifle, dass wir die Riesen davon abhalten können, einander zu bekämpfen, aber möglicherweise finden wir einen Weg, dies zu unserem Vorteil zu nutzen. Ich muss sofort unseren Anführern Bericht erstatten.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12204] = {title = "In Lokens Namen", objective = "Sprecht mit Hugh Glass und Gavrock über Loken und übermittelt Eure Erkenntnisse Späher Vor'takh im Camp Oneqwah.", description = "Die Eisenzwerge sind einer der erbittertsten und organisiertesten Gegner in Nordend. Wo auch immer wir hingekommen sind, haben sie uns mit dem Namen Lokens auf den Lippen bekämpft.\n\nWir müssen herausbekommen, wer dieser Loken ist und was er vorhat. Die Einheimischen könnten uns weiterhelfen.\n\nIm Nordosten, im Handelsposten von Rotholz, bietet ein Mensch namens Hugh Glass seine Waren feil. Weiter östlich, bei den Ruinen von Tethys, findet Ihr einen Steinriesen, der Gavrock genannt wird. Fragt sie nach diesem Loken. Sie müssen einfach irgendwelche brauchbaren Informationen haben.", progress = nil, completion = "Also ist er der Strippenzieher bei den Eisenzwergen? Wir müssen herausfinden, was er den Eisenzwergen von Dun Argol befohlen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12205] = {title = "GESUCHT: Der Scharlachrote Ansturm", objective = "Tötet 20 Mitglieder des Scharlachroten Ansturms und meldet Euch anschließend bei Hochexekutor Zürner in Gallgrimm.", description = "Auf Befehl des Hochexekutors Zürner sind alle Mitglieder der illegalen Organisation genannt \"der Scharlachrote Ansturm\" auf der Stelle zu töten.\n\nIhnen ist keine Gnade zu gewähren. Diejenigen, die aufgrund dieses Erlasses zur Tat schreiten werden, sollten darüber im Klaren sein, dass der Tod noch das Mildeste ist, was man erwarten kann, sollte man von den Menschen gefangen genommen werden!\n\nUm es in den Worten des Hochexekutors auszudrücken: \"Färbt den Schnee rot mit ihrem Blut!\"", progress = nil, completion = "Sehr gut gemacht, &lt;Volk&gt;. Ich vertraue einmal darauf, dass Ihr mit viel Geschick zu Werke gegangen seid.\n\nDann lasst uns mal sehen, wie viel die Toten - ähm - ich meine, wie viel die Truhen Euch einbringen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12206] = {title = "Verseuchte letzte Riten", objective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr das Seuchenfläschchen an dem Gefangenen des Scharlachroten Ansturms austestet.", description = "Habt Ihr den Steckbrief gelesen? Was denkt sich der Hochexekutor nur?!\n\n<Vicky sieht sich um und fährt mit gedämpfter Stimme fort.>\n\nWir können doch wohl nicht zulassen, dass diese Idioten vom Scharlachroten Ansturm von ihren Priestern wiedererweckt werden oder - schlimmer noch - als Diener der Geißel wieder auferstehen, nicht wahr?\n\nNein, ich stimme Euch völlig zu, wir müssen etwas gegen die Leichen unternehmen.\n\nIch hab' genau das nötige Werkzeug. Nehmt dieses Fläschchen an Euch, in ihm befindet sich die erst kürzlich von uns hergestellte Seuche, und testet dessen Inhalt an dem Gefangenen in dem Käfig hier aus.\n\nKeine Aufregung, einfach zurücklehnen und zugucken - und siehe da: keine Feinde, die wieder auferstehen können.", progress = "Habt Ihr es getan?\n\nHe, ich hab' vergessen, Euch zu sagen, dass Ihr Euch lieber nicht mit dem Zeug voll kleckern solltet! Es ist gefährlich und die Flecken lassen sich nicht entfernen - ganz zu schweigen von dem Spaß, den Ihr dabei hättet, die Stellen wieder zu heilen, an denen Euch das Fleisch vom Körper fiel.", completion = "WAS?! Das ist unmöglich! Wir haben die Seuche perfektioniert. Sie ist zu hundert Prozent tödlich.\n\n&lt;Die Apothekerin ringt die Hände - Besorgnis steht in ihrem untoten Gesicht geschrieben. Sie ist ganz offensichtlich frustriert und mit Zorn in ihrer Stimme fährt sie fort.&gt;\n\nDas ist einfach nur seltsam. Reicht mir das Fläschchen, &lt;Klasse&gt;. Ich werde auf keinen Fall die Apothekerin sein, die alles zum Scheitern brachte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12207] = {title = "Vordrassils Fall", objective = "Windseherin Grauhorn in Burg Siegeshall möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms besorgt.", description = "Vor langer Zeit pflanzten mächtige Druiden einen Baum nordöstlich von hier.\n\nEr wurde Vordrassil genannt und sollte zu einem Weltenbaum erwachsen. Es ist nicht bekannt warum, aber nachdem der Baum vollständig ausgewachsen war, entschieden die Druiden, dass er zerstört werden müsse.\n\nSeit dem Moment, an dem wir hier angekommen sind, hat die Erde zu mir gesprochen, <Name>. Ihre Schmerzenslaute kommen von den Orten, an dem Vordrassils Überreste den Boden berührten.\n\nFauliger Schlamm ist dort zu finden. Bringt mir Proben davon, sodass wir damit beginnen können, dieses Land zu heilen.", progress = "Habt Ihr die Proben sammeln können, <Name>?", completion = "Dieser Schleim stinkt nach einer Finsternis, die viel älter ist, als ihre weltliche Form einen annehmen lassen würde. Das Land selbst erinnert sich an dieses Böse, seitdem es existiert.\n\nWir müssen mehr herausfinden, &lt;Name&gt;.", rewards = "Robe der ExpurgationWachsüberzogener BrustschutzSäurefeste HalsbergeBrustplatte der unzeitigen BelohnungenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12208] = {title = "Gute Trolljagd", objective = "Unteroffizier Thurkin möchte, dass Ihr mit Samir am Granitquell sprecht.", description = "Diese nichtsnutzigen Mistkerle!\n\nSie hätten es einfacher haben können. Wir haben ihnen die Hand zum Frieden gereicht. Alles, was sie hätten tun müssen, ist, uns den Durchgang durch Drak'Tharon zu gewähren, und wir hätten sie in Ruhe gelassen.\n\nDoch nein, die hochmütigen kleinen Eistrolle wollen es anscheinend auf die harte Tour. Wir werden so oder so durch ihre kostbare Festung marschieren, um nach Zul'Drak zu gelangen. Doch nun werden sie vernichtet werden.\n\nWir haben eine Bande angeheuert, die für uns Trolle einfangen soll. Sprecht mit Samir, wenn Ihr bei der Sache mitmischen wollt. Ihr könnt ihn nordwestlich von hier, südlich von Zeb'Halak finden.", progress = nil, completion = "Ihr seid hier, um bei der Kopfgeldangelegenheit mitzumischen, wie?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12209] = {title = "Kriegsbeute", objective = "Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 8 Rüstungen des Scharlachroten Ansturms und 8 Waffen des Scharlachroten Ansturms stehlt.", description = "Ah gut, Frischfleisch. Wollt Ihr Euch bewähren, Frischfleisch?\n\nDer Scharlachrote Ansturm, die fanatischste und rassistischste Gruppe des Scharlachroten Kreuzzuges, steht vor unserer eigenen Haustüre - im Süden. Wenn wir sie bekämpfen wollen, werden wir mehr Rüstungen und Waffen benötigen, als ich in so kurzer Zeit überhaupt herstellen kann.\n\nWieso schnappen wir uns nicht einfach ihre Waffen?\n\nGenauer gesagt: Wieso schnappt IHR EUCH nicht einfach ihre Waffen?", progress = "Ich nehme, was auch immer Ihr mir an Rüstungen und Waffen besorgen könnt, Frischfleisch.\n\nQualitativ gesehen werden sie zwar nicht an das heranreichen, was ich hier herstellen kann, doch sie sind besser als gar nichts.", completion = "So frisch riecht Ihr gar nicht mehr, Frischfleisch.\n\nNun gut, das wird wohl reichen. Wie soll ich Euch nun nennen, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12210] = {title = "Trollsaison!", objective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr mit Samir am Granitquell sprecht.", description = "Ihr, <Volk>! Was für eine Verschwendung, hier herumzustehen, während es dort draußen noch Arbeit zu tun gibt!\n\nDie Feste Drak'Tharon ist der direkteste Weg nach Zul'Drak. Wir MÜSSEN sie einnehmen, um dafür zu sorgen, dass die Allianz dort sicher ankommt. Doch bis wir die nötigen Leute für einen Angriff zusammenhaben, müssen wir uns damit begnügen, die Reihen der Eistrolle zu lichten und Informationen zu sammeln.\n\nFür letzteres haben wir eine Bande von Rohlingen eingezogen, die lebendige Trolle einfangen und dann zwecks Vernehmung hierher bringen sollen. Reist nach Nordwesten und sprecht mit Samir am Granitquell. Er wird Euch sagen, wie es weitergeht.", progress = nil, completion = "Ihr seid hier, um bei der Kopfgeldangelegenheit mitzumischen, oder was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12211] = {title = "Lasst sie nicht wieder auferstehen!", objective = "Apothekerin Vicky Levine aus Gallgrimm hat Euch gebeten, Ihr Behältnis voller Ratten zu benutzen, um 15 Leichen von Anhängern des Scharlachroten Ansturms in Neuherdweiler zu beseitigen.", description = "Ich verstehe es einfach nicht. Es sollte mit der Seuche doch eigentlich funktionieren.\n\nAber Jammern hat keinen Sinn.\n\n<Aus irgendeinem Grund wirkt die Apothekerin erleichtert.>\n\nObwohl es merkwürdigerweise beim Ansturm nicht zu wirken scheint, müssen wir nach wie vor ihre Priester davon abhalten, sie wiederzuerwecken.\n\nIch habe eine andere Idee - eine, vor der Ihre Leichname keinen Schutz haben sollten.\n\nNehmt einen Behälter mit Ratten, <Name>, und lasst sie auf jede Leiche des Scharlachroten Ansturms los, die ihr finden könnt. Ich habe das Gezücht hungern lassen - also sollten sie besonders garstig sein!", progress = nil, completion = "Sehr gut! Einen Moment lang dachte ich schon, ich müsste die Ratten an jemandem ausprobieren, um sicherzustellen, dass sie nicht defekt sind.\n\nEndlich ein Fortschritt!", rewards = "Schärpe der zehrenden SeucheStulpen des KammerjägersNagetiersicherer KopfschutzHandschutz gegen BisseIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12212] = {title = "Das Lagerhaus auffüllen", objective = "Forstmeister Anderhol bei der Ammertannhütte möchte, dass Ihr Großhornhirsche tötet und 8 Stück saftiges Wildbret sammelt.", description = "Guten Tag, <Klasse>.\n\nDer gute Leutnant hier meint, dass die Horde unser Lagerhaus geplündert hätte, wodurch unser Essensvorrat nun gefährlich klein geworden sei.\n\nDiese Schwachköpfe werden dafür auf jeden Fall büßen, doch zuerst müssen wir unsere Aufmerksamkeit darauf richten, unsere Vorräte wieder aufzufüllen. Meine Männer tun alles, was in ihrer Macht steht, doch wir werden jeden benötigen, der etwas beitragen kann, wenn wir eine Krise verhindern wollen.\n\nEs sollte keine Schwierigkeiten darstellen, die Hirsche in dieser Gegend zu erlegen, um an deren Fleisch heranzukommen. Frohe Jagd!", progress = "Wie läuft die Jagd, <Volk>?", completion = "Das ist doch mal feinstes Fleisch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12213] = {title = "Die Dunkelheit darunter", objective = "Windseherin Grauhorn möchte, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet.", description = "Etwas… Dunkles… ist dem Baum Vordrassil zugestoßen. Nachdem die Druiden beschlossen hatten, ihn zu zerstören, bohrten seine hohlen Überreste ihre Wurzeln tief in den Boden.\n\nIch möchte, dass Ihr zu den drei Orten im Nordosten geht, wo der Stamm gesplittert ist und, so weit Ihr könnt, in den Untergrund vordringt.\n\nBenutzt diese Kugel, sobald Ihr eingetroffen seid, um die Spuren der Energie, welche die Gegend umgibt, anzeigen zu können. Dies könnte aufzuklären helfen, was mit Vordrassil damals passiert ist und warum er es nicht geschafft hat, ein Weltenbaum zu werden.", progress = nil, completion = "Diese Kugel… sie wurde von einer... abgrundtief bösen Macht befleckt.\n\nWas ich auch sonst noch durch weitere Untersuchungen herausfinden werde, eines ist sicher: Ich muss die Kugel so bald als möglich zerstören. Ihre verderbende Macht ist einfach zu groß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12214] = {title = "Ersatzpferde", objective = "Hänsel Bauer in Gallgrimm möchte, dass Ihr 3 Kriegspferde des Ansturms stehlt, sie anschließend bei ihm abliefert und ihm dann auch die Zügel übergebt.", description = "Hallo, <mein Herr/meine Dame>. Ich bin Hänsel. Schön, Euch kennenzulernen\n\nDer Hochexekutor kam zu mir und meinte: 'Hänsel, ich möchte, dass du uns ein paar neue Pferde beschaffst.'\n\nWas meint er denn, wo Schreckensrösser herkommen? Aus dem Boden?\n\n<Hänsel flüstert.> Auf Pferdefriedhöfen tun sie das sogar.\n\nNur gibt es hier keinen, also müsst Ihr nach Neuherdweiler im Süden gehen, die Ritter töten, ihnen die Reitgerten abnehmen und ihre Schlachtrösser stehlen.\n\nWäre gut, wenn Ihr dann mit dem Pferd zu mir reitet und mir die Zügel gebt.", progress = "Ich bin richtig erleichtert, dass Ihr hier aufgetaucht seid. Ich hatte schon Angst, dass ich die Sache selbst in die Hand nehmen muss.", completion = "Ah, gute Arbeit - nichts ist schöner als das.\n\nIhr habt Gallgrimm einen großen Dienst damit erwiesen, diese Pferde zu besorgen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12215] = {title = "Sie oder wir!", objective = "Anderhol bei der Ammertannhütte möchte, dass Ihr in den Grizzlyhügeln nach 6 Graunebeljägern sucht und sie tötet.", description = "Als ob wir nicht schon genug hätten, das uns Sorgen bereitet...\n\nAufgrund der jetzigen Essenskrise befinden wir uns mit den hiesigen Worgs im Nahrungsstreit. Die Situation wird immer schlimmer und ich befürchte, dass es schon bald nichts mehr zu jagen geben wird, wenn wir uns nicht sofort diesem Problem zuwenden.\n\nDurchkämmt den Wald, <Volk>. Tötet alle Graunebeljäger, die Ihr finden könnt. Jüngste Berichte sprechen von einer Ansammlung dieser Wesen am anderen Ufer des westlich gelegenen Flusses.", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;.\n\nDas sollte uns dabei helfen, sicherzustellen, dass die Tiere in dieser Gegend auch dort landen, wo sie hingehören - nämlich auf dem Rost über unseren Feuern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12216] = {title = "Bärenhatz!", objective = "Anderhol bei der Ammertannhütte möchte, dass Ihr 8 Grizzlyflanken von den Grizzlybären in den Grizzlyhügeln ergattert.", description = "Wir haben hart gearbeitet und so langsam sehen wir auch die Früchte dieser Arbeit, aber wir sind noch immer weit davon entfernt, unser Ziel zu erreichen. Wir brauchen viel mehr Fleisch als wir haben und die Hirschpopulation hier wird alleine nicht ausreichen.\n\nIch fürchte, Ihr müsst Eure Aufmerksamkeit etwas gefährlicherer Beute zuwenden... den Grizzlys, die dieser Gegend den Namen geben. Es gibt sie Zuhauf und sie sind wohlgenährt von den ganzen Fischschwärmen in diesen Gewässern.\n\nGebt auf Euch acht, <Klasse>!", progress = "Der mächtige <Klasse> ist zurückgekehrt!", completion = "Hervorragend!\n\nUnser Vorratslager ist nun fast wieder voll. Ihr habt euren Beitrag dazu geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12217] = {title = "Adleraugen", objective = "Anderhol bei der Ammertannhütte möchte, dass Ihr 5 Kaiseradler tötet und ihm anschließend Bericht erstattet.", description = "Nun, <Name>, wir haben herausgefunden, wie die Horde unsere verborgenen Nahrungslager lokalisieren konnte.\n\nOffensichtlich war ihre Sicht an die der arglosen Adler gebunden, die hier über den Bäumen kreisen. Mit der Sicht der Adler war es ihnen tatsächlich möglich, jede unserer Handlungen zu beobachten.\n\nAuf Befehl des Leutnants sollen wir diese majestätischen Vögel erlegen, um unserem Feind einen Strich durch die Rechnung zu machen.", progress = nil, completion = "Eine düstere Aufgabe, ich weiß. Aber wir können uns wieder sicherer fühlen, jetzt, da wir wissen, dass die Augen des Feindes nicht länger auf uns ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12218] = {title = "Verbreitet die guten Neuigkeiten", objective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr in den Seuchenverbreiter der Verlassenen steigt, zu den Randgebieten der Aasfelder fahrt und dort mithilfe der Seuchenbombe 30 hungernde Tote vernichtet.", description = "Bevor ich Euch mit den guten Neuigkeiten zu Doktor Malefius schicken kann, werdet Ihr einen einfachen Feldversuch der von mir modifizierten Seuche durchführen müssen.\n\nDie hungernden Toten strömen aus den Überresten von Altwintergarde. Beschlagnahmt eines der Gefährte am Osttor und fahrt mit ihm nach Nordosten durch den Pass der Vergeltung bis Ihr die Zwillingstürme in der südöstlichen Ecke von Wintergarde erreicht. Feuert die Seuchenbombe auf die Untoten ab, von denen es in der Gegend nur so wimmelt. Meldet Euch anschließend mit den Resultaten wieder bei mir zurück!", progress = nil, completion = "So sehr es mich verärgert, dass wir der Allianz womöglich geholfen haben, erkläre ich hiermit den Feldversuch für erfolgreich! Nächster Halt: Agmars Hammer!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12219] = {title = "Der eingegangene Weltenbaum", objective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder zu Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms beschafft.", description = "Meine Urahnen pflanzten einst einen Baum in der Mitte der Grizzlyhügel.\n\nVordrassil wurde er genannt und sollte ein Weltenbaum werden.\n\nAus Gründen, die schon lange in Vergessenheit geraten sind, beschlossen sie, den Baum zu zerstören, nachdem er seine volle Größe erreicht hatte. Seine Splitter befinden sich an drei verschiedenen Orten in der Gegend im Norden.\n\nDort, wo der Baum den Boden berührte, tauchte fauliger, lebendiger Schlamm auf. Bringt mir ein paar Schleimproben, damit ich mit meiner Arbeit beginnen und die Erde heilen kann.", progress = "Habt Ihr die Proben gesammelt, <Name>?", completion = "Der Schleim ist nicht natürlich, &lt;Name&gt;. Er ist von Natur aus verderbt und... boshaft.\n\nWir müssen noch mehr darüber herausfinden.", rewards = "Robe der ExpurgationWachsüberzogener BrustschutzSäurefeste HalsbergeBrustplatte der unzeitigen BelohnungenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12220] = {title = "Ein dunkler Einfluss", objective = "Hierophantin Thayreen bei der Ammertannhütte will, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet.", description = "Als der Baum Vordrassil fiel, bohrten seine hohlen Überreste ihre Wurzeln tief in den Boden.\n\nIch möchte, dass Ihr nach Norden geht, die drei Orte aufsucht, wo der Stamm gesplittert ist, und so tief wie möglich in den Untergrund vordringt. Sie liegen westlich von Grauschlund.\n\nBenutzt diese Kugel, sobald Ihr eingetroffen seid, um die Spuren der Energie, welche die Gegend umgibt, anzeigen zu können. Wenn wir das Land heilen wollen, müssen wir zunächst herausfinden, was dazu geführt hat, dass Vordrassil vor all diesen Jahren als Weltenbaum versagt hat.", progress = nil, completion = "Die Energie in der Kugel ist… überwältigend… \n\nEine dunkle Macht hat den Boden bei Vordrassils Überresten befleckt. Wir müssen dies weiter untersuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12221] = {title = "Die Seuche der Verlassenen", objective = "Liefert die Seuche der Verlassenen bei Doktor Sintar Malefius in Agmars Hammer ab.", description = "Ich habe ein Paket vorbereitet, das an Doktor Sintar Malefius in Agmars Hammer geschickt werden muss. Der Inhalt des Pakets besteht aus der fertigen Pesthauchprobe, zusammen mit der Herstellungsanleitung und Proben des Aktivierungsagens.\n\nIhr findet Agmars Hammer im Westen der Drachenöde. Haltet einfach nach den schwarzen, gezackten Metallgebäuden der Orcs Ausschau - das wird dann Agmars Hammer sein.", progress = "Wurde auch langsam Zeit!", completion = "&lt;Doktor Malefious wirft einen kurzen Blick auf den Inhalt des Pakets.&gt;\n\nHerrlich! Genau nach Angabe!\n\nHier ist Eure Bezahlung, &lt;Name&gt;. Behaltet das, was Ihr gesehen und getan habt, für Euch. Die Sache ist streng geheim - Informationen werden bei Bedarf weitergegeben.", rewards = "Blutverschmierte ZauberklingeStreitkolben des gefallenen RabenpriestersSchlachtkolben der FestungGewehr des BelagerungshauptmannsAxt des ZinnenverstärkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12222] = {title = "Geheimnisse der Flammenbinder", objective = "Bringt dem Förster Drach bei der Ammertannhütte 3 flammenerfüllte Talismane.", description = "Während wir versuchen, die Horde zurückzuschlagen, sammelt sich der Stamm der Drachenschinder in ihrem Dorf Voldrune, in der Nähe der Küste im Süden.\n\nDen mächtigsten Kriegern im Dorf werden flammenerfüllte Talismane gewährt, die ihnen die Fähigkeit geben, mächtige, wilde Protodrachen zu kontrollieren. Wenn es uns gelänge, die Kontrolle über einen dieser Drachen zu übernehmen, dann könnten wir ihn vielleicht dazu nutzen, die Gefahr, die von Voldrune ausgeht, zu neutralisieren.\n\nDie Flammenbinder der Drachenschinder erschaffen die Talismane und erfüllen sie mit Macht. Tötet sie und nehmt die Talismane.", progress = "Habt Ihr diese Talismane bekommen?", completion = "Mit diesen Talismanen in der Hand wird der Drache keine andere Wahl haben, als Euch zu gehorchen. Ich kann es kaum abwarten, den Gesichtsausdruck des Thans zu sehen, wenn er feststellt, dass Ihr das Kommando über seinen Protodrachen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12223] = {title = "Die Reihen lichten", objective = "Tötet 12 Huscarls der Drachenschinder und kehrt anschließend zu Förster Drach in der Ammertannhütte zurück.", description = "In Voldrune gen Süden geht es richtig zu. Thane Torvald Eriksson und seine Huscarls bereiten sich auf den Krieg vor. Ammertann wird verwundbar sein, da sich die meisten unserer Männer draußen im Feld befinden und sich um die verräterische Horde kümmern.\n\nReist nach Voldrune nahe der Südküste und zeigt diesen Drachenschindern, dass mit uns nicht zu spaßen ist.\n\nErschlagt so viele Huscarls, wie Ihr nur finden könnt. Sie sollen es sich zweimal überlegen, bevor sie unseren Konflikt mit der Horde ausnützen, um uns in den Rücken zu fallen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Nun müssen wir die Sache nur noch zu Ende führen und uns den Vorteil zu Nutze machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12224] = {title = "Der Vorposten der Kor'kron!", objective = "Meldet Euch bei Saurfang dem Jüngeren im Vorposten der Kor'kron.", description = "Gut gemacht, <Bruder/Schwester>. Ihr habt Euch allen Herausforderungen wie ein Champion der Horde gestellt: habt die verseuchten Anub'ar von Azjol-Nerub unter Euren Füßen zerquetscht! - habt die mutigen und mächtigen Taunka zu neuen Mitgliedern der Horde gemacht! - habt unsere neue Superwaffe gegen die Geißel getestet und perfektioniert!\n\nDie Zeit ist nun reif, der Moment ist gekommen: Unsere Elitesoldaten an der Pforte des Zorns brauchen Euch. Der Sohn von Saurfang im Vorposten der Kor'kron erwartet Eure Ankunft. Geht jetzt - auf nach Nordosten zur Pforte des Zorns.", progress = nil, completion = "Lok'tar Ogar! Ich habe schon viel von Euch gehört, &lt;Name&gt;. Die Narben aus Euren Schlachten sind tief - ein Zeichen Eurer Hingabe und Macht!\n\nDa der Lichkönig unsere West- und Ostflanke vernichtend geschlagen hat, bleibt nur noch unsere Streitmacht an der Pforte des Zorns übrig. Jeden Tag gewinnen wir an Boden und schon bald werden wir durch diesen Wall brechen und zur Eiskrone gelangen!\n\nSobald den Skelettdrachen Einhalt geboten wurde, werden Hochlord Fordragon und ich ins Feld ziehen.", rewards = "Sandalen der chaotischen LösungUnerbittliche ZombiezermalmerTreter des tapferen RingensVerstärkte Stiefel des ReisendenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12225] = {title = "Mmm... Bernsteinsamen!", objective = "Sprecht mit Forstmeister Anderhol in der Ammertannhütte.", description = "Euer Magen knurrt, als der starke Geruch herzhafter Nüsse Eure Aufmerksamkeit auf den mit Samen gefüllten Eimer zieht.\n\nIrgendeine aufmerksame Seele hat diese Gratisleckerbissen offensichtlich hier gelassen, um erschöpfte Besucher wieder frisch und munter zu machen. Dankbar tut Ihr Euch an den paar verbliebenen gütlich.\n\nDer Geschmack der Samen enttäuscht nicht. Ihr wollt noch mehr und macht Euch also auf den Weg, um herauszufinden, woher sie kommen...", progress = nil, completion = "Ihr habt was getan?!!\n\nDas waren Bernsteinsamen! Die Ausbeute einer ganzen Ernte!\n\nDiese magischen Samen waren womöglich die Antwort auf unsere Essenskrise. Ihr werdet das wieder richten, &lt;Name&gt;, das könnt Ihr mir glauben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12226] = {title = "Wieder raus damit", objective = "Anderhol bei der Ammertannhütte möchte, dass Ihr ihm 5 Schwarzwurzelstrünke bringt.", description = "Wir müssen schnell handeln, <Volk>! Wir können es nicht riskieren, dass diese wertvollen Samen vollständig verdaut werden. Sie müssen raus, und zwar JETZT!\n\nBesorgt ein paar Schwarzwurzeln vom Flussufer westlich von hier und ich werde Euch ein Abführmittel zubereiten, das die Sache ins Rollen bringen sollte.\n\nBeeilt Euch! Und denkt dran, Ihr habt Euch das selbst eingebrockt...", progress = "Habt Ihr die Schwarzwurzel gefunden?", completion = "Mit denen hier sollte es gut klappen…\n\n&lt;Anderhol bricht geschickt die Strünke auf und sammelt die austretende Flüssigkeit in einer kleinen Phiole.&gt;\n\nSo, und jetzt zur Sache.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12227] = {title = "Tut Eure Pflicht", objective = "Anderhol bei der Ammertannhütte möchte, dass Ihr Anderhols Karussellstöffsche nehmt und das nahegelegene Plumpsklo aufsucht, um die teilweise verarbeiteten Bernsteinsamen zurückzuholen.", description = "In Ordnung, <Volk>. Hier ist der Saft.\n\nDie Wirkung tritt sofort ein, benutzt ihn deshalb erst, wenn Ihr sicher das Plumpsklo erreicht habt.\n\nUnd jetzt besorgt mir diese Samen!", progress = "Na, habt Ihr diese Samen für mich, <Volk>?", completion = "Nun, &lt;Name&gt;? Alles gut rausgekommen?\n\nHmm, sieht so aus, als hätten wir sie gerade noch rechtzeitig retten können…", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRanziges SiegelFauliger RingHalbstumpfer Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12229] = {title = "Eine mögliche Verbindung", objective = "Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr 8 Proben des Bluts eines wahnsinnigen Furbolgs von den Furbolgs am Schrein des Herzbluts und am Schrein des Grollfangs sammelt.", description = "Vor nicht allzu langer Zeit haben wir eine Expedition in den Osten entsandt, wo sie von wahnsinnigen Furbolgs angegriffen wurde. Einer der Überlebenden beschrieb uns, wie er einen von ihnen erschlug und aus dessen Körper eine dunkle, schleimige Substanz austrat.\n\nTausende von Jahren waren die Furbolgs in dieser Gegend friedlich. Es ist möglich, dass eine Verbindung besteht zwischen dem Verhalten der Furbolgs und der dunklen Energie, die wir zuvor entdeckt haben.\n\nBringt mir ein paar Proben des Furbolgbluts. Ihr findet sie im Osten am Schrein des Grollfangs und am Schrein des Herzbluts.", progress = "Habt Ihr die Blutproben, <Name>?", completion = "Dieses Blut scheint auf dieselbe Art verdorben zu sein wie der Schleim, den Ihr zuvor gesammelt habt… Dies lässt nichts Gutes erahnen, &lt;Name&gt;.", rewards = "AnstifterhandschuheFesseln der geistigen GesundheitHelm des FurbolgläuterersBlutbespritzte SchiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12230] = {title = "Von den Belagerungsschmieden klauen", objective = "Todeswache Molder in Gallgrimm möchte, dass Ihr 6 Bomben des Belagerungsschmiedes beschafft.", description = "Ich bin mit der Zerstörung der Ballisten des Scharlachroten Ansturms beauftragt worden. Unglücklicherweise sind die Apotheker und ich über die Verteilung der uns gegebenen Ressourcen uneins, also steht mir nichts zur Verfügung, mit dem ich sie zerstören könnte!\n\nGen Nordosten liegen die Aasfelder. Die dortigen Belagerungsschmiede der Geißel bei ihren Schmieden und Fleischwagen sind so etwas wie Meister der Verwüstung.\n\nDoch zum Glück lassen sie ihre Bomben einfach so herumliegen.\n\nIch möchte, dass Ihr mir das Zeug bringt; vom Boden oder von den Schmieden selbst - ist mir egal.", progress = "Man sollte doch meinen, dass sie mich ihre Seuchenverbreiter benutzen lassen würden... damit ich sie vielleicht mit irgendwas Gefährlichem beladen und die Ballisten zerstören könnte.\n\nAber nein, nein... sie meinen, dass die nur für Spezialmissionen gedacht seien.\n\nWas auch immer!", completion = "&lt;Die Todeswache reibt sich vor Vorfreude die Hände.&gt;\n\nAusgezeichnet. Ihr Verlust ist mein... ähhm... ist unser Gewinn!\n\nIhr hattet auf dem Weg hierher doch keine Probleme mit den Dingern, oder? Einige von denen sehen ziemlich instabil aus. Ich mag vielleicht untot sein, doch meine Existenz schätze ich allemal!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12231] = {title = "Die Jungen des Bärengottes", objective = "Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr mit Orsonn am Schrein des Grollfangs und Kodian am Schrein des Herzbluts sprecht.", description = "Es ist möglich, dass die Furbolgs von den Grizzlyhügeln demselben Verderben unterliegen, das schon Vordrassil plagte. In letzter Zeit waren sie, nach Jahren der friedlichen Koexistenz, in einen tödlichen Stammeskrieg verwickelt.\n\nDie Schreine, die sie im Osten bewachen, sind das Zuhause von Ursocs Jungen.\n\nSollte die Verderbnis auch die Furbolgs betreffen, so ist es möglich, dass Kodian und Orsonn aufgrund ihrer Abstammung unversehrt geblieben sind.\n\nSollte dies der Fall sein, so findet sie und hört, was sie zu sagen haben.", progress = "Habt Ihr schon mit Ursocs Kindern gesprochen, <Name>?", completion = "Ursocs Kinder sind weise. Ihre Worte erklären viel von dem, was wir bisher gesehen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12232] = {title = "Bombardiert die Ballisten", objective = "Todeswache Molder in Gallgrimm möchte, dass Ihr mit den Bomben des Belagerungsschmiedes 5 Ballisten von Neuherdweiler unter Beschuss nehmt.", description = "Zu guter Letzt bietet sich uns die Chance, ihre Belagerungsmaschinen anzugreifen! Vermasselt es nicht.\n\nWar nur Spaß - nur ein klein wenig.\n\n<Klasse>, nehmt Neuherdweilers Ballisten mit diesen Bomben unter Beschuss.\n\nWir werden der Königlichen Apothekervereinigung zeigen, wie es auf die altmodische Art und Weise gemacht wird - ohne Gebräue!", progress = nil, completion = "Welch freudiger Tag!\n\nDa ich zur Erledigung des Auftrags nicht die Zeit und Mittel der Apotheker in Anspruch genommen habe, ist mir die Aufmerksamkeit des Hochexekutors sicher!\n\nIch kann nämlich um die Ecke denken - das ist meine größte Stärke. Ja, ja, Ihr hattet dabei natürlich auch ein Händchen im Spiel.\n\nHier, wenn ich Euch etwas gebe, versprecht Ihr mir dann, nichts von Eurem Zutun zu erwähnen?", rewards = "Wickeltuch des SaboteursAuf Euch wartet eine dieser Belohnungen:\n\nRitueller NackenschutzFackelring des Belagerungsmeisters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12233] = {title = "Den Samen aussäen", objective = "Nein, nein... Behaltet sie.\n\nIhr habt doch nicht ernsthaft erwartet, dass ich sie nach all dem an mich nehme, oder?\n\nIhr macht folgendes...", description = "Nein, nein... Behaltet sie.\n\nIhr habt doch nicht ernsthaft erwartet, dass ich sie nach all dem an mich nehme, oder?\n\nIhr macht folgendes...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12234] = {title = "Das muss ich wissen", objective = "Spionagemeisterin Repine möchte, dass Ihr die \"Tagesübersicht des Scharlachroten Ansturms: Abtei\", \"Tagesübersicht des Scharlachroten Ansturms: Kaserne\" und die \"Tagesübersicht des Scharlachroten Ansturms: Strand\" stehlt.", description = "Ich muss wissen, was in Neuherdweiler los ist.\n\nIch möchte, dass Ihr ihre Tagesübersicht stehlt, damit ich genau das herausfinden kann.\n\nBegebt Euch nach Süden. Die Pläne sollten sich in der Abtei, der Kaserne und auf dem Strand befinden. Sucht und findet sie!\n\nUnd nur für den Fall, dass Ihr Euch nicht auskennen solltet. Die Kaserne ist das große Gebäude gleich neben der Schmiede.", progress = "Wenn Ihr zu lange braucht, dann werden sich ihre Pläne ändern und wir müssen wieder von vorne anfangen.\n\nLasst Euch nicht zu viel Zeit!", completion = "Nun, worauf wartet Ihr noch, &lt;Volk&gt;? Gebt sie schon her!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12235] = {title = "Naxxramas und der Fall von Wintergarde", objective = "Sprecht mit dem Greifenkommandanten Urik an der Greifenstation in der Feste Wintergarde.", description = "Lord Fordragon hat bei der Pforte des Zorns einen vernichtenden Angriff gegen Arthas' Truppen eingeleitet. Als Antwort auf diesen Affront hat Arthas Naxxramas in den Kampf gegen uns geschickt. Während Kel'Thuzad sich in der schwebenden Zitadelle versteckt hält, wird Wintergarde von seinem Feldkommandanten Thel'zan belagert. Das untere Dorf ist bereits verloren und die Chance, Überlebende aus den Ruinen zu bergen, schwindet von Minute zu Minute.\n\nWir müssen schnell handeln! Meldet Euch umgehend bei Greifenkommandant Urik an der Greifenstation! Er wird Euch Flügel verleihen.\n\nVerlasst mich nun!", progress = nil, completion = "&lt;Urik deutet auf einen Greifen.&gt;\n\nHabt Ihr jemals schon einen von denen hier geritten? Es ist ganz einfach, &lt;Klasse&gt;. Schwingt Euch einfach auf den Sattel und sagt ihm, wohin er fliegen soll.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12236] = {title = "Ursoc, der Bärengott", objective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle findet und Ursoc mit seiner Hilfe besiegt. Streut die geläuterte Asche von Vordrassil auf Ursocs Leiche, nachdem Ihr ihn getötet habt.", description = "Der Augenblick ist gekommen, <Name>. Nun werden wir sehen, ob unsere Anstrengungen Früchte tragen oder nicht.\n\nNehmt diese Asche und sucht den Furbolg Tur Wutpranke, von dem Kodian Euch erzählt hat. Er hält sich in der Nähe von Ursocs Höhle auf, die Ihr nördlich des Grauschlunds findet.\n\nÜberzeugt Tur, Euch zu helfen, denn Ihr werdet alle Hilfe brauchen, die Ihr kriegen könnt.\n\nSobald Ihr den Bärengott bezwungen habt, streut diese Asche über seinen Körper.\n\nSelbst wenn seine weltliche Hülle zerstört ist, muss sein Geist gerettet werden.", progress = nil, completion = "&lt;Die Druidin sieht blass aus und ihre Augen starren an Euch vorbei. Sie hat anscheinend auf Eure Rückkehr gewartet und ein Paket für Euch hingestellt.&gt;", rewards = "Beinschützer der aufgelösten HoffnungGamaschen der machtvollen LäuterungKilt der göttlichen FolterHosen des geläuterten WindesSchienbeinschützer der geheiligten AuflösungIhr bekommt:\n\nBollwerk des gefolterten GottesAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12237] = {title = "Flug des Verteidigers von Wintergarde", objective = "Rettet 5 hilflose Dorfbewohner von Wintergarde und kehrt anschließend zum Greifenkommandanten Urik in Wintergarde zurück.", description = "Mit dieser Pfeife könnt Ihr einen Greifen von Wintergarde zu Euch rufen. Steigt anschließend auf, macht Euch auf den Weg nach Südosten zu den Ruinen des Dorfs Wintergarde, jetzt Aasfelder genannt, und haltet dort nach hilflosen Dorfbewohnern von Wintergarde Ausschau. Fliegt nah an sie heran, wenn Ihr einen gesichtet habt, hebt sie mithilfe des Greifs vom Boden auf und fliegt anschließend mit dem Geretteten hierher zur Greifenstation zurück.\n\nDie Diener der Geißel sind überall in der Gegend verstreut, also müsst Ihr auf der Hut sein, <Klasse>. Viel Glück!", progress = "Beeilt Euch, <Name>! Ihr müsst die Hilflosen Dorfbewohner befreien!", completion = "Bemerkenswerte Arbeit, &lt;Name&gt;! Jetzt, da unsere Bürger wieder hier sind, können wir diese Festung wieder auf Vordermann bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12238] = {title = "Die Reinigung Drak'Tharons", objective = "Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos.", description = "Bald wird Drak'Tharon von den verdorb'nen Untoten gereinigt und wieder ihrer ursprünglichen noblen Aufgabe unterstellt werden. Als Belohnung für deine Hilfe werd'n dir die wertvollsten Schätze der Feste zur Verfügung steh'n, Mann!\n\nSobald du ihre Spitze erreicht hast, musste mich beschwör'n, und ich führ' das Ritual durch.\n\nAber mich zu ruf'n, Mann, wird einiges kosten. Du musst das Mojo von den Überlebenden sammeln.", progress = nil, completion = "Wir ham' großes geleistet, Mann! Un' das is' nur der Anfang…\n\nSuch mich in Zul'Drak auf, wenn die Zeit reif is'.\n\nEs gibt 'nen Krieg zu gewinnen, Mann!", rewards = "Verführerische SabatonsSchultern des VerführersFesseln des dunklen GeflüstersSchleier der VerführungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12239] = {title = "Der Spion in Neuherdweiler", objective = "Liefert die Tagesübersicht des Scharlachroten Ansturms bei Agentin Skully in Neuherdweiler ab.", description = "Ich habe eine meiner Spioninnen beim Scharlachroten Ansturm sitzen und möchte, dass ihr diese Tagesübersicht überbracht wird, damit sie die nächste Phase unseres Angriffes planen kann.\n\nSie wird Agentin Skully genannt und ist magisch verkleidet, um wie die Totengräberin des Ansturms auszusehen.\n\nHier, bringt Ihr dieses Schreiben und macht, was sie von Euch verlangt. Ihr findet den Friedhof gleich neben der Abtei.", progress = "<Die Agentin mustert Euch von Kopf bis Fuß und gibt Euch ein Zeichen, dass Ihr zu ihr kommen sollt.>\n\nLasst mich bloß nicht auffliegen, <Klasse>!", completion = "Ihr habt Nachricht von der Spionagemeisterin?\n\n&lt;Die Agentin vergewissert sich, dass niemand zusieht, und legt die Schaufel ab.&gt;\n\nLasst mich diese Pläne einmal sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12240] = {title = "Ein Mittel zum Zweck", objective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe der Termiten der LevinefamilieGroßknecht Kaleiki hervorlockt und ihn tötet.", description = "Mit der letzten Lieferung habe ich von meiner Schwester am Bollwerk ein paar Fässer mit Termiten geschickt bekommen. Sie werden bei dem, was ich mit Euch vorhabe, nützlich sein, denke ich.\n\nDie Abholzungsarbeiten bei Neuherdweiler sind uns ein Dorn im Auge, doch bisweilen haben wir es noch nicht geschafft, jemandem Zugang zu verschaffen, um ihren Vorarbeiter auszuschalten.\n\nIch denke jedoch, dass er mit Sicherheit angerannt käme, wenn Ihr diese Termiten auf seine kostbaren Holzarbeiten loslassen würdet.\n\nBereit, ihn auszuschalten, <Klasse>?", progress = nil, completion = "Ich habe gewusst, dass meine Schwester uns nicht im Stich lassen würde.\n\nGut gemacht, &lt;Name&gt;. Das Sägewerk des Scharlachroten Ansturms wird eine ganze Weile außer Betrieb sein, was die Herstellung neuer Bauwerke oder Ballisten erst einmal lahmlegt.\n\nIch danke Euch, dass Ihr mir dabei geholfen habt, meinem Familiennamen gerecht zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12241] = {title = "Zerstört den Schössling", objective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr die grüne Fackel nehmt und sie benutzt, um Vordrassils Schössling zu verbrennen. Bringt Vordrassils Asche zurück zu Windseher Grauhorn.", description = "Die Taten der Furbolgs müssen rückgängig gemacht werden, <Name>. Der beste aller Vorsätze zählt nicht viel, wenn das Resultat von solch starker Verderbnis durchzogen ist.\n\nDer Schössling muss zerstört werden, da er die Quelle dieses finsteren Einflusses ist. Nehmt diese Fackel und benutzt sie, um den verderbten Schössling in Flammen aufgehen zu lassen, und bringt mir dann seine Asche.\n\nEinmal durch das Feuer gereinigt, werde ich alle Macht, die ich habe, einsetzen, um den Schatten, der auf der Asche liegt, zu beseitigen. Ihr werdet sie brauchen, um Ursoc von der bösen Macht zu befreien, die ihn beherrscht.", progress = "Habt Ihr die Asche für mich, <Name>?", completion = "Ich kann nichts versprechen, &lt;Name&gt;. Aber ich werde mein Bestes geben, um sie zu reinigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12242] = {title = "Vordrassils Samen", objective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr nach Grauschlund geht und 8 Samen von Vordrassil beschafft.", description = "Wir müssen dafür sorgen, dass Vordrassil niemals wieder wächst. Die Furbolgs müssen seine Samen eingesammelt haben.\n\nGeht nach Grauschlund in der Mitte der Grizzlyhügel und beschafft alle Samen, die Ihr finden könnt. Ich werde dafür sorgen, dass sie auf jeden Fall vernichtet werden.", progress = "Habt Ihr Vordrassils Samen dabei, <Name>?", completion = "Habt Dank, &lt;Name&gt;. Ich werde sie dann an mich nehmen.\n\nDie verderbende Macht dieser Samen ist gefährlich. Ich muss sie umgehend zerstören.", rewards = "Tuch der besitzergreifenden SeeleAuf Euch wartet eine dieser Belohnungen:\n\nHoarders HalsketteBand des Borklings\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12243] = {title = "Feuer auf dem Wasser", objective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe des Feuerwassers des Apothekers die Segel der Sündenbabel in Brand steckt.\n\nGeht unter Deck, während die Deckmatrosen damit beschäftigt sind, das Feuer zu löschen, und sucht nach Kapitän Shelys Seekarten.", description = "Ich hab' noch einen Auftrag für Euch.\n\nIch habe es geschafft, ein wenig der Seuche so zu manipulieren, dass ich daraus mein weltbekanntes brennendes Wasser zusammenbrauen konnte. Ich möchte, dass Ihr damit die Segel der Sündenbabel in Brand steckt!\n\nWerft es vom Dock aus auf die Segel. Die Deckmatrosen werden damit beschäftigt sein, das Feuer zu löschen, was Euch die Gelegenheit bietet, unter Deck zu huschen und an die Seekarten des Kapitäns heranzukommen.\n\nDas Schiff liegt im Hafen des Kreuzzüglers vor Anker, südlich von Neuherdweiler. Die Kapitänskajüte befindet sich auf dem ersten Unterdeck hinter der Treppe.", progress = "Bitte sagt mir NICHT, dass mein Feuerwasser keine Wirkung auf ihre Segel hatte!\n\nIch hätte rein gar keine Lust, es wieder dort draußen austesten zu müssen.", completion = "Ahhahahahahahahahaha!\n\nOhne ihre Seekarten gibt es für sie kein Entrinnen mehr.\n\nSieht mir nach dem Ende des Scharlachroten Ansturms aus - gerade, als sie richtig in Fahrt kamen. Wie traurig.\n\nHeh.", rewards = "Gelenkbänder der HochseeStiefel des LichtungswanderersSchulterschutz des WestwindsAuf Euch wartet eine dieser Belohnungen:\n\nSünderbuße\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12244] = {title = "Schredder reparieren", objective = "Synipus beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 3 kaputte Schredder bringt.", description = "Hört mal, Freundchen. Wieso krempelt Ihr nicht Eure Ärmel hoch und schnappt Euch 'nen Schraubenschlüssel? Gibt viel zu tun! Diese Schredder müssen aufgemöbelt und runter zur Venturebucht geschickt werden, und das schon gestern...\n\nKein Schraubenschlüssel? Und zu was seid Ihr dann gut? Könnt dann genauso gut mit dem Rest der Blechköpfe runtergehen und mit der Horde spielen!\n\nSolang' könntet Ihr auch versuchen, 'n paar von den kaputten Schreddern hier hoch zur Reparatur zu bringen. Seid vorsichtig! Sie sind in einem ziemlich miesen Zustand.", progress = nil, completion = "&lt;Synipus pfeift.&gt;\n\nOh, was für 'ne Schönheit! Wir richten sie gleich wieder her!\n\nWenn Ihr nix zu tun habt, dann sprecht mit Gordun und lasst Euch runter zur Venturebucht bringen. Die brauchen da sicher 'ne helfende Hand.\n\nOh, und solange Ihr dort seid, benutzt doch diese Schlüssel an 'nem runderneuerten Schredder. Wartet, bis Ihr seht, was die Babys anrichten, wenn sie mal repariert sind!", rewards = "Ihr bekommt:\n\nSchlüssel zum runderneuerten Schredder"}
MultiLanguageQuestData['de'][12245] = {title = "Keine Gnade für Gefangene", objective = "Spionagemeisterin Repine hat Euch gebeten, Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai zu töten.\n\nFalls Ihr Erfolg habt, berichtet Hochexekutor Zürner in Gallgrimm davon.", description = "Wir haben noch mehr Narren für Euch, die Ihr umbringen müsst.\n\nMeine Männer berichten mir, dass einige unserer guten Bürger es geschafft haben, dem Scharlachroten Ansturm in die Hände zu fallen.\n\nDas kann so nicht angehen.\n\nGeht zurück nach Neuherdweiler und tötet Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai.\n\nBerichten nach zu urteilen, sind sie über das gesamte Gebiet verteilt und werden in Käfigen festgehalten; doch auf sie wartet zweifellos die Folter.\n\nSprecht mit ihnen und tötet sie dann!", progress = nil, completion = "Was? Ihr habt angenommen, wir würden Euch ausschicken, um sie zu retten?\n\nWarum sollten wir das denn tun, wenn sich bereits gezeigt hat, dass sie sich ohne weiteres gefangen nehmen lassen?\n\nNordend ist ein kalter Ort, junger &lt;Name&gt;. Ich schlage vor, Ihr gewöhnt Euch dran.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12246] = {title = "Eine mögliche Verbindung", objective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr am Schrein des Grollfangs und am Schrein des Herzbluts 8 Blutproben von wahnsinnigen Furbolgs sammelt.", description = "Die Furbolgs, die östlich von hier leben, sind aggressiver und bestialischer als die, an die wir gewöhnt sind. Unsere Streitkräfte sind mehr als einmal mit ihnen aneinandergeraten und die Überlebenden sprechen immer von einer dunklen, schleimigen Substanz, die aus ihren Körpern tropft.\n\nIhr Zustand könnte mit den Verunreinigungen zu tun haben, die wir auf Vordrassils Überresten gefunden haben.\n\nBringt mir Proben des Furbolgbluts. Ihr findet sie am Schrein des Grollfangs und am Schrein des Herzbluts, weit im Osten.", progress = "Habt Ihr die Blutproben sammeln können, <Name>?", completion = "Die Verderbnis in diesem Blut gleicht der in dem Schleim. Ich habe kein gutes Gefühl bei der Sache.", rewards = "AnstifterhandschuheFesseln der geistigen GesundheitHelm des FurbolgläuterersBlutbespritzte SchiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12247] = {title = "Kinder von Ursoc", objective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr mit Orsonn im Schrein des Grollfangs und mit Kodian im Schrein des Herzensblutes sprecht.", description = "Die Furbolgs der Grizzlyhügel sind von einer Art Verderbnis befallen, so viel steht fest. Nun ist ein Stammeskrieg zwischen ihnen ausgebrochen, nachdem sie jahrelang friedlich miteinander gelebt hatten.\n\nWas wir noch herausfinden müssen, ist, ob die Bären, die sie als Götter verehren, auch der Verderbnis anheim gefallen sind.\n\nUrsocs zwei Kinder, Orsonn und Kodian, halten sich im Schrein des Herzensblutes und des Grollfangs auf, süd- und südöstlich von Grauschlund.\n\nSeht nach, ob sie mit Euch über das, was dort geschehen ist, sprechen werden.", progress = nil, completion = "Ursocs Kinder sind weise. Ihre Worte erklären einiges von dem, was wir gesehen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12248] = {title = "Vordrassils Schössling", objective = "Hierophantin Thayreen in der Ammertannhütte möchte, dass Ihr mithilfe der grünen Fackel Vordrassils Schössling anzündet und ihr die daraus entstehende Asche von Vordrassil bringt.", description = "Die Druiden von einst scheinen guten Grund gehabt zu haben, Vordrassil zu zerstören. Wir können nicht zulassen, dass die Furbolgs ihn wieder gedeihen lassen.\n\nAuf der anderen Seite hängt die Rettung von Ursocs Geist von der Magie ab, die in diesem Schössling steckt.\n\nNehmt diese Fackel und steckt mit ihrer Hilfe den Baum in Brand. Er befindet sich in der Mitte von Grauschlund im Inneren von Vordrassils altem Baumstamm. Bringt mir die Asche von Vordrassil. Ich hoffe, dass, sobald er vom Feuer gereinigt wurde, wir mithilfe seiner Magie Ursocs Geist von seiner Dunkelheit läutern können.", progress = "Habt Ihr mir die Asche gebracht, <Name>?", completion = "Ja! Vordrassils Magie ist erhalten geblieben und steckt noch immer in dieser Asche. Vielleicht gibt es doch noch Hoffnung für Ursoc.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12249] = {title = "Ursoc, der Bärengott", objective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle aufsucht und mit seiner Hilfe Ursoc besiegt. Streut anschließend die geläuterte Asche von Vordrassil auf Ursocs Leiche.", description = "Es ist Zeit, <Name>. Nehmt diese Asche und sucht nach dem Furbolg, von dem Kodian gesprochen hat. Wenn er sich auf die Suche nach Ursoc gemacht hat, dann wird er in der Nähe seines Baus nördlich von Grauschlund sein.\n\nIhr werdet seine Hilfe benötigen. Alleine werdet Ihr Ursoc nicht besiegen können.\n\nBenutzt die Asche, um seinen Geist zu läutern, sobald Ihr Ursoc besiegt habt. Erst dann werden wir wissen, ob unsere Mühen umsonst waren oder nicht.", progress = nil, completion = "&lt;Die Druidin sieht blass aus und ihre Augen starren an Euch vorbei. Sie hat anscheinend auf Eure Rückkehr gewartet und ein Packet für Euch hingestellt.&gt;", rewards = "Beinschützer der aufgelösten HoffnungGamaschen der machtvollen LäuterungKilt der göttlichen FolterHosen des geläuterten WindesSchienbeinschützer der geheiligten AuflösungIhr bekommt:\n\nBollwerk des gefolterten GottesAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12250] = {title = "Vordrassils Samen", objective = "Hierophantin Thayreen in der Ammertannhütte will, dass Ihr zum Grauschlund geht und 8 Samen von Vordrassil besorgt.", description = "Wir können nicht zulassen, dass Vordrassil wieder wächst. Wenn die Furbolgs es einmal geschafft haben, ihn wachsen zu lassen, dann können sie es wieder tun.\n\nGeht zum Grauschlund im Zentrum der Grizzlyhügel und besorgt Vordrassils Samen. Ich werde dann sicherstellen, dass sie ein für alle Mal verschwinden.", progress = "Habt Ihr die Samen, <Name>?", completion = "Danke, &lt;Name&gt;. Ich werde sie an mich nehmen.\n\nDie verderbende Macht dieser Samen ist äußerst gefährlich. Ich muss sie sofort zerstören.", rewards = "Tuch der besitzergreifenden SeeleAuf Euch wartet eine dieser Belohnungen:\n\nHoarders HalsketteBand des Borklings\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12251] = {title = "Kehrt zum Oberkommandanten zurück", objective = "Sprecht mit Oberkommandant Halford Wyrmbann in Wintergarde in der Drachenöde.", description = "<Name>, Ihr müsst umgehend zum Oberkommandanten Halford Wyrmbann zurückkehren. Lasst ihn wissen, dass unsere Mission ein voller Erfolg war und dass die wenigen verbliebenen Dorfbewohner, die gerettet wurden, wieder bei der Arbeit sind.", progress = nil, completion = "&lt;Halford salutiert vor Euch.&gt;\n\nDas Stadtvolk ist wieder bei der Arbeit? Jetzt schon? Ausgezeichnet, Soldat! Wir werden diese Stadt im Handumdrehen wieder aufgebaut und befestigt haben. Nicht mehr lange und unsere Truppen werden einsatzbereit sein und Lord Fordragon bei seinem Kampf an der Pforte des Zorns zur Seite stehen.\n\nIch bin natürlich etwas zu voreilig - bevor wir nämlich überhaupt erst daran denken können, Euch zu Bolvars Hilfe zu schicken, muss hier noch einiges getan werden.", rewards = "Gesegnete Handlappen des SpitzenreitersStiefel des SchneewehenhäschersGürtelbund des WestwindsStulpen des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12252] = {title = "Foltert den Folterer", objective = "Hochexekutor Zürner in Gallgrimm möchte, dass Ihr Folterer Alphonse fünfmal mit dem Brandeisen bearbeitet und die Informationen aus ihm herausquetscht. Anschließend sollt Ihr ihn töten.", description = "Genug! Ich möchte, dass Ihr den Qualen meines Volkes ein Ende setzt!\n\nDer Folterer des Scharlachroten Ansturms, Alphonse, erzwingt auf die blutigste Art und Weise Informationen von allen, die von diesen Scheusalen gefangen genommen werden! Ich muss wissen, was sie wissen.\n\nAus gewissen Quellen habe ich erfahren, dass er sich im Keller ihrer Kaserne, die sich gleich neben der Schmiede befindet, eingerichtet hat.\n\nIch werde Euch mein eigenes Brandeisen ausleihen, damit die Arbeit auch richtig erledigt wird.\n\nFindet ihn und beschafft Euch die Informationen.", progress = nil, completion = "Sie wussten das alles? Und wer zum Teufel ist dieser Großadmiral Westwind, den er erwähnt hat?!\n\n&lt;Der Hochexekutor murmelt vor sich hin und meint, dass er Überraschungen nicht ausstehen kann.&gt;\n\nGut zu wissen. Besser das, als nur Vermutungen anzustellen. Ich hoffe, dass Ihr Euer... ähm, ich meine, dass Ihr mein Mal hinterlassen habt.", rewards = "Gewänder des EiswüstenhauchsKapuze des SchneewehenhäschersEisscherschulterstückeKristallplattenstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12253] = {title = "Rettung vom Marktplatz", objective = "Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 6 gefangene Dorfbewohner von Wintergarde befreit.", description = "Gleich diesen Weg entlang befindet sich der Dorfplatz von Wintergarde. Einst war dies ein geschäftiger Ort für die Bürger von Wintergarde, doch nun ist aus ihm ein Kampfschauplatz geworden und wimmelt nur so von blutrünstigen Spuken, die sich um jeden Preis an den Lebenden rächen wollen.\n\nIn den Gebäuden um den Platz herum befinden sich gefangene Dorfbewohner, die unbedingt befreit werden müssen! Dies mag jetzt vielleicht etwas viel verlangt sein, <Name>, doch Ihr seid <der einzige Soldat, den/die einzige Soldatin> die; ich entbehren kann. Befreit unsere Leute. Folgt diesem Pfad zum Dorfplatz, geht zu den Häusern und tötet alles, was sich Euch in den Weg stellt! Kehrt wieder zu mir zurück, falls Ihr überleben solltet.", progress = nil, completion = "&lt;Halford spricht ein Gebet für die Verstorbenen.&gt;\n\nIhr verrichtet des Lichtes Arbeit, &lt;Name&gt;.\n\nIch fürchte, dass unsere Arbeit gerade erst begonnen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12254] = {title = "Ohne Gebet", objective = "Agentin Skully in Neuherdweiler möchte, dass Ihr das Gebetsbuch von Bischof Straß besorgt.", description = "Diese Pläne lassen darauf schließen, dass etwas kurz bevorsteht.\n\nDoch zuerst ist da noch die Sache mit diesem seltsamen Schutz, über den die Truppen des Ansturms verfügen. Wenn Gallgrimm ein für alle Mal mit ihnen abrechnen will, dann müssen wir den Verantwortlichen dafür finden und ihn ausschalten.\n\nIch habe bemerkt, dass der Bischof in der Kapelle gegenüber dem Sägewerk auf der anderen Seite von Neuherdweiler häufiger als sonst den Truppen seinen Segen erteilt. Tötet ihn und nehmt ihm sein Gebetsbuch ab.\n\nVielleicht wird es uns einen Hinweis geben.", progress = "Ihr habt das Gebetsbuch des Bischofs? Habt Ihr darin auch irgendetwas Ungewöhnliches gefunden?", completion = "Ihr meint also, dass auf der letzten Seite des Buches ein neuer Segen geschrieben steht?\n\n&lt;Die Agentin blickt Euch über die Schulter, als Ihr die letzte Seite aufschlagt.&gt;\n\nVerdammt nochmal! Das ist die Handschrift des Hochabtes! Ich würde Euer Leben darauf verwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12255] = {title = "Der Than von Voldrune", objective = "Besiegt mithilfe von Flammenbringer den Than Torvald Eriksson und meldet Euch anschließend bei Förster Drach bei der Ammertannhütte.", description = "Nun, da Ihr die flammenerfüllten Talismane in Händen haltet und die Verteidigung von Voldrune geschwächt habt, können wir einen Schlag gegen ihren Anführer ausführen, den Than Torvald Eriksson.\n\nSein Lieblingsreittier ist ein nicht zu bändigender Protodrache, den er Flammenbringer nennt. Er wird im westlichen Teil von Voldrune in Ketten gehalten, doch mithilfe der Talismane solltet Ihr ihn lange genug beherrschen können, um ihn gegen den Than einzusetzen.\n\nDer Than hält sich irgendwo oben auf den Türmen von Voldrune auf. Sucht dort nach ihm, sobald Ihr Flammenbringer unter Eure Kontrolle gebracht habt, und zeigt keine Gnade.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Ich bezweifle, dass irgendeiner der Förster sich an dem Protodrachen hätte versuchen wollen, doch wir konnten es einfach nicht zulassen, dass die Drachenschinder eine Basis in den Grizzlyhügeln errichten. Wenn es mit der Horde nur auch so leicht wäre...", rewards = "Krone des KopfbindersTunika des zurechtgewiesenen ThansBeinschützer des angefochtenen FeudalismusHelm des SchädelverformersAuf Euch wartet eine dieser Belohnungen:\n\nThanhäschersiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12256] = {title = "Geheimnis der Flammenbinder", objective = "Bringt 3 flammenerfüllte Talismane zu Unteroffizier Nazgrim in Burg Siegeswall.", description = "Während die feige Allianz unsere Stellungen angreift, bereiten sich die Vrykul der Drachenschinder im Außenposten Voldrune gen Südosten auf den Krieg vor. Die Vrykul sind bei Weitem nicht der stärkste Feind, dem wir uns hier gegenübersehen, doch wir müssen sie aus dem Weg räumen, bevor sie eine wirkliche Bedrohung für uns darstellen.\n\nDen stärksten ihrer Krieger ist es gestattet, auf schlecht trainierten Protodrachen in die Schlacht zu reiten. Um die Bestien zu kontrollieren, erschaffen die Flammenbinder mächtige Talismane. Ihr werdet sie töten und die Talismane an Euch bringen müssen, damit unser Plan funktioniert.", progress = "Habt Ihr diese Talismane dabei?", completion = "Die Macht der Talismane bewirkt, dass die Drachen keine andere Wahl haben, als Euren Befehlen zu gehorchen. Das Schicksal des Thans ist besiegelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12257] = {title = "Eine Demonstration der Stärke", objective = "Tötet 12 Huscarls der Drachenschinder und kehrt zu Unteroffizier Nazgrim am Siegeswall zurück.", description = "Das Vrykuldorf Voldrune im Südosten bereitet sich auf den Krieg vor. Der Than von Voldrune kann keine große Armee in die Schlacht führen, aber durch unsere reduzierte Truppenstärke sind wir dennoch in Gefahr.\n\nWir können nicht riskieren, einem Angriff ausgesetzt zu werden, also müssen wir die Initiative ergreifen. Wenn Ihr <ein wahrer/eine wahre:c> <Klasse> der Horde seid, werdet Ihr auf eine Chance brennen, Eure Stärke zu demonstrieren.\n\nMäht die Huscarls nieder und beweist diesem Drachenschinderklan, dass mit der Horde nicht zu spaßen ist!", progress = nil, completion = "Ihr habt getan, worum ich Euch gebeten habe. Jetzt sind die Drachenschinder in der Defensive und es ist bald an der Zeit, sich um ihren Anführer zu kümmern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12258] = {title = "Das Schicksal der Toten", objective = "Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 15 rachsüchtige Spuke tötet.", description = "Der Dorfplatz am Ende dieses Weges wimmelt nur so von untoten Bürgern von Wintergarde! Unsere eigene Krypta versorgt die Geißel mit einer schier endlosen Zahl Krieger, die sie dann auf uns hetzen kann. Zeigt ihnen jedoch keine Gnade, <Name>. Einst waren sie Sterbliche wie wir, des Mitgefühls und Denkens fähig, doch jetzt sind aus ihnen wütende Untote geworden, die nur ein Ziel kennen: unsere völlige Zerstörung.\n\nGeht zum Dorfplatz, wenn Ihr den Mut dazu habt, und befördert die rachsüchtigen Spuke wieder zu ihrem Schöpfer zurück. Sorgt dafür, dass sie in Frieden ruhen können.", progress = nil, completion = "Vielleicht werden sie jetzt in Frieden ruhen können, da es ihren Geistern nicht mehr verwehrt ist, zum Licht emporzusteigen.\n\nMeine Gedanken und Gebete gehen nun an Lord Fordragon und unsere Streitkräfte an der Pforte des Zorns. Wir müssen hier ausharren, auch wenn ihnen das vielleicht nur genug Zeit verschaffen wird, um den Lichkönig zu besiegen. Wintergarde darf nicht fallen.", rewards = "Sattelgurt des EiswüstenhauchsHandschuhe des SchneewehenhäschersEisscherbindungenSabatons des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12259] = {title = "Der Than von Voldrune", objective = "Besiegt mithilfe von Flammenbringer Than Torvald Eriksson und meldet Euch anschließend bei Unteroffizier Nazgrim in Burg Siegeswall.", description = "Mit den flammenerfüllten Talismanen können wir den Than endlich herausfordern!\n\nSein Lieblingsreittier ist ein wilder Protodrache namens Flammenbringer. Er wird im westlichen Teil Voldrunes in Fesseln gehalten, aber mit der Kraft der Talismane solltet Ihr ihn Eurem Willen unterwerfen und gegen den Than einsetzen können.\n\nSobald Ihr Flammenbringer unter Kontrolle gebracht habt, sucht auf den Turmspitzen von Voldrune nach dem Than, um ihn mit Flammenbringer zu erledigen.", progress = nil, completion = "Die wenigen verbliebenen Drachenschinder wagen es nicht, sich uns nach dem Kampf mit dem Than entgegenzustellen. Kein Erbarmen mit unseren Feinden - das ist der Weg der Horde.", rewards = "Krone des KopfbindersTunika des zurechtgewiesenen ThansBeinschützer des angefochtenen FeudalismusHelm des SchädelverformersAuf Euch wartet eine dieser Belohnungen:\n\nThanhäschersiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12260] = {title = "Die perfekte Heuchelei", objective = "Agentin Skully in Neuherdweiler möchte, dass Ihr das Abbild eines Rabenpriesters des Ansturms stehlt. Bringt den magischen Spiegel der Banshee wieder zurück, wenn Ihr das getan habt.", description = "Womöglich fragt Ihr Euch, wie ich diese Gestalt aufrechterhalten kann... Ich verwende einen magischen Spiegel, den mir die Spionagemeisterin geliehen hat.\n\nEr hat zwar nur eine gewisse Menge an Energie, doch ich denke, dass genug für uns beide da ist. Hier, nehmt ihn. Ich möchte, dass Ihr Euch mit seiner Hilfe als Rabenpriester des Ansturms ausgebt.\n\nMacht schnell... ich weiß nicht, wie lange ich noch so bezaubernd aussehen werde, wenn Ihr den Spiegel habt.\n\nIhr müsst wissen, dass Eure Verkleidung nicht sofort perfekt sein wird. Idiotensicher ist sie erst dann, wenn ich eine Chance hatte, Euch zu helfen.", progress = "Bitte sagt mir, dass Ihr den Spiegel nicht zerbrochen habt!", completion = "Nicht schlecht, &lt;Klasse&gt;. Nun, da das Abbild des Priesters im Spiegel gefangen ist, hätte ich noch eine andere Aufgabe für Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Perfect Dissemblance: Quest Completion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12261] = {title = "Kein Ausweg", objective = "Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist und kehrt dann zu Serinar zurück.", description = "Sie beziehen ihre Macht aus den Knochen meiner toten Brüder...\n\nFür den Kult habe ich nichts übrig, aber ihre Dreistigkeit verblüfft mich. Es wird keine Gnade für sie geben... ich würde ihnen ohnehin keine gewähren, so oder so.\n\nStellt sicher, dass ihnen kein Fluchtweg bleibt, wenn das Schlachten beginnt. Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist.", progress = "Habt Ihr die Barriere aufgestellt?", completion = "Exzellent. Sobald sie in Panik fliehen, wird die Barriere dort bereit sein, um ihnen einen freundlichen Abschied zu bereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12262] = {title = "Und niemand, der Euch retten wird...", objective = "Tötet außerhalb des Obsidiandrachenschreins 6 Nekrolyten der Brennenden Tiefen und 10 glimmende Skelette. Kehrt zu Serinar zurück, sobald Eure Aufgabe abgeschlossen ist.", description = "Niemand wird verschont. \n\nDort draußen besudelt dieser Nekrolytenabschaum und seine Skelettdiener mein Land mit seiner Anwesenheit. Schlachtet sie ab, alle.", progress = nil, completion = "Haben sie um ihre jämmerlichen Leben gebettelt? Schwächlinge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12263] = {title = "Nur die besten Absichten", objective = "Wartet, bis Serinar Euch in die Verkleidung eines Nekrolyten der Brennenden Tiefen gehüllt hat. Dringt in die Tiefen des Schlundes von Neltharion vor, um aufzudecken, was den Kult der Verdammten hierher lockt. Kehrt mit Details ihres Vorhabens zu Serinar zurück.", description = "Der Kult der Verdammten ist nicht nur hier, um die Macht aus toten Drachen zu extrahieren. Ich hege einen Verdacht, was ihre Absichten betrifft. Aber ich brauche Euch, um ihn zu bestätigen.\n\nIch werde Euch das Aussehen dieses toten Nekrolyten verleihen. Dringt in das Innerste der Höhle vor und überprüft ihre Gründe, diesen geheiligten Ort heimzusuchen. Ich werde alles durch Eure Augen beobachten. \n\nSeid vorsichtig, <Name>. Die Illusion ist empfindlich, erleidet Ihr Schaden wird sie wahrscheinlich zerbrechen.", progress = "Diese Pestilenz ermüdet mich.", completion = "Wir sind der schwarze Drachenschwarm. Seit tausenden von Jahren haben wir Chaos und Verwüstung auf Azeroth verbreitet. Der Kult der Verdammten verehrt den Tod - was sie so lieben werden wir ihnen mit Freuden servieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove Serinar's Disguise and Sight\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12264] = {title = "Das Ausmerzen der Verdammten", objective = "Tötet in Neltharions Schlund 3 Nekromanten der Brennenden Tiefen, 6 glimmende Konstrukte und 6 glimmende Spuke. Kehrt dann zu Serinar zurück.", description = "Die Tiefen der Höhle wimmelten nur so von den Scheusalen der Kultisten. Es gibt nur eine Art, mit solchen Kreaturen fertigzuwerden... Ihr wisst, was zu tun ist.", progress = "Ich komme nicht umhin, mich zu fragen, ob sie naiv genug sind, um zu glauben, dass ich es damit bewenden lasse oder ob sie einfach gern getötet werden.", completion = "Ihre Schreie zu hören... zuzusehen, wie das letzte Quäntchen Leben aus ihren erbärmlichen Körpern sickert... so erfrischend, nicht wahr?\n\nIch liebe es.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12265] = {title = "Die Schändung der Entweiher", objective = "Findet 8 nekromantische Runen, die auf den Boden von Neltharions Schlund gezeichnet wurden und löscht sie aus. Kehrt zu Serinar zurück, sobald die Aufgabe abgeschlossen ist.", description = "In den Runen, die wir auf dem Weg in die Höhle entdeckt haben, habe ich eine große Ansammlung von Magie gespürt. Mit Spielereien, wie ihnen die Magie zu entziehen, brauchen wir uns nicht abzugeben... zumeist ist die direkte Lösung die Effektivste.\n\nZerstört die Runen... löscht sie aus und stellt sicher, dass der Kult zu der Macht, die er hier angesammelt hat, keinen Zugriff hat.", progress = nil, completion = "Gut. Es gibt mehr zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12266] = {title = "Kunde der Zerstörung", objective = "Kehrt zum Wyrmruhtempel zurück und lasst Yntrige wissen, dass Serinars Aufgabe abgeschlossen ist.", description = "Ihr könnt nun gehen, <Volk>.\n\nSagt Yntrige, sie hat ein üppiges Schlachtfest verpasst.", progress = nil, completion = "Oh, Ihr seid es.\n\nIch hatte gehofft, dass Serinar einfach zurückkehren würde, sobald die Aufgabe erledigt gewesen wäre... Ich nehme mal an, dass er irgendwas gefunden hat, das er töten muss. Er verpasst eine wunderbar chaotische Schlacht!\n\nSeid Ihr noch immer da? Ich bin mit Euch fertig.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12267] = {title = "Neltharions Flamme", objective = "Äschert mit Neltharions Flamme die Beschwörungskammer im hinteren Teil von Neltharions Schlund ein. Tötet Rothin den Verfallenen, nachdem Ihr seine Aufmerksamkeit auf Euch gezogen habt, und kehrt anschließend zu Serinar am Eingang der Höhle zurück.", description = "Die Reihen des Kults sind dünner geworden, ein Teil ihrer Macht ist vergangen - es ist Zeit, gegen die Quelle der Verderbnis vorzurücken.\n\nRothin der Verfallende belebt im hinteren Teil der Höhle schwarze Drachen als Magmawyrms wieder. Geht zur Beschwörungskammer und läutert die verbliebenen Knochen auf die einzige Art und Weise, wie man sicherstellen kann, dass niemand je wieder mit ihnen herumspielen wird... mit Feuer.\n\nDie Knochen zu verbrennen wird mit Sicherheit Rothins Aufmerksamkeit erregen - und wenn dem so sein sollte, dann kümmert Euch auch darum, dass er vernichtet wird.\n\nIn der Phiole sollte sich genug magische Kraft befinden, um die Aufgabe zu erledigen.", progress = "Ihr seid ein ziemlich effektives Werkzeug, <Klasse>. Eure Beteiligung an dieser Läuterung wird mit Wohlwollen betrachtet.", completion = "Den Knochen meines Schwarms wurde diese Besudelung erspart. Ihr habt mir gut gedient und sollt dafür angemessen entlohnt werden.", rewards = "Robe von Hohepriester ForithTuch des Lord PrestorBeinplatten des besiegten RittersAuf Euch wartet eine dieser Belohnungen:\n\nHalsband des Wyrmsklaven\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12268] = {title = "Einzelteile", objective = "Pipthwak beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern bringt.", description = "Bah! Das Ding ist ein einziges Durcheinander!\n\nGoblinische Ingenieurskunst lässt 'ne Menge zu wünschen übrig, das könnt Ihr mir glauben. Schaut Euch das hier nur an! Ein Wunder, dass es überhaupt jemals funktioniert hat.\n\nHelft mir mal, ja? Um dies auch nur ansatzweise zum Laufen zu bringen, muss ich diverse Zahnräder, Winkel und Federn ersetzen. Ihr solltet keine Probleme haben, sie in der Nähe des Sägewerks zu finden.", progress = "Habt Ihr diese Ersatzteile für mich, <Klasse>?", completion = "In der Tat. Nun sollte es hinhauen...\n\nSo, bitte. Ein weiterer Schredder bereit für den Kampf. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12269] = {title = "Nicht in unserer Mine", objective = "Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Bergarbeiterausweise von Wintergarde beschafft.", description = "Wir wurden von dieser verdammten Nekropole völlig überrumpelt! Durch den Überfall haben wir auch die Minen von Wintergarde an den Feind verloren. Und was noch viel schlimmer ist: Kel'Thuzads Akolyten haben die toten Bergarbeiter in Diener der Geißel verwandelt und benutzen sie, um ihre Belagerungsingenieure mit Rohstoffen aus unserer Mine zu versorgen!\n\nIhre Rohstoffquelle muss zum Erliegen kommen und unsere verlorenen Brüder wieder ihre Ruhe finden.\n\nGeht nach Nordosten zu den Minen von Wintergarde im Bereich der Aasfelder und vernichtet die auferstandenen Bergarbeiter. Bringt ihre Ausweise wieder zu mir zurück, damit ich sie als verstorben in unser Register aufnehmen kann.", progress = "Habt Ihr ihre Ausweise dabei?", completion = "&lt;Leoric nimmt Euch die Ausweise ab.&gt;\n\nIch werde die hier unserem Buchhalter geben und den Familien der Bergarbeiter die schlimmen Neuigkeiten überbringen.\n\nEs gibt noch immer viel zu tun, wenn wir hier und letztendlich an der Pforte des Zorns die Oberhand gewinnen wollen. Lord Fordragon ist auf uns angewiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12270] = {title = "Schreddert die Allianz", objective = "Grekk im Holzfällerlager Blauhimmel möchte, dass Ihr 3 Schredder besorgt und diesen zu ihm zurückkehrt.", description = "Sperrt die Ohren auf, <Klasse>: Ich brauche diese Schredder! Und genauso wichtig: Ich muss sie von der Allianz fernhalten!\n\nSie haben die Schredder rundum erneuert und setzen sie nun gegen unsere Brüder in der Venturebucht ein. Nun werden wir sie ihre eigene Medizin schmecken lassen!\n\nWenn Ihr einen Schredder da draußen seht, dann schnappt ihn Euch! Wenn Ihr dabei irgendwelchen Allianzlern über den Weg lauft, bringt sie um und schnappt Euch dann den Schredder! Sobald Ihr einen habt, bringt ihn zurück zu mir und wir machen uns an die Arbeit.\n\nWeggetreten!", progress = "Habt Ihr mir schon diese Schredder geholt, <Klasse>?", completion = "Gute Arbeit, Soldat!\n\nNun nehmt diesen Schlüssel und begebt Euch runter zur Venturebucht. Verwendet einen der runderneuerten Schredder, um Chaos unter unseren Feinden zu verbreiten.\n\nAch ja, wendet Euch an Darrok, wenn Ihr die Abkürzung nehmen wollt!", rewards = "Ihr bekommt:\n\nSchlüssel zum runderneuerten Schredder"}
MultiLanguageQuestData['de'][12271] = {title = "Die Rute des Zwangs", objective = "Liefert den Stab des Folterers bei Hochexekutor Zürner in Gallgrimm ab.", description = "Ein Stab fällt aus Alphonses toter Hand. Er ist mit pulsierenden magischen Runen versehen.\n\nHat er damit seine Geständnisse bekommen?\n\nDer Hochexekutor sollte sich das besser einmal ansehen.", progress = "Habt Ihr diesen Stab dem Folterer abgenommen?", completion = "Alphonse hatte ihn bei sich, meint Ihr? Das ergibt Sinn.\n\nIch habe so etwas früher schon einmal gesehen, als ich noch jünger war, zu der Zeit, als Lordaeron noch bestand und ich als Folterer in den Diensten des Königs Terenas stand. Man nennt es einen Stab des Zwangs.\n\n&lt;Der Hochexekutor ringt die Hände in hämischer Vorfreude.&gt;\n\nIch habe eine Idee, wie wir ihn uns zunutze machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12272] = {title = "Das blutende Erz", objective = "Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Proben des seltsamen Erzes aus der Mine von Wintergarde beschafft.", description = "Stunden vor der Invasion durch Naxxramas stolperte einer der Bergarbeiter über ein dunkles Erz, aus dem eine zähe Flüssigkeit tropfte. In dem Chaos, das bei der Evakuierung der Mine herrschte, verloren wir jedoch die aus der seltsamen Ader herausgehauenen Proben. Nun untersucht die Geißel das Erz, um herauszufinden, wie sie es in ihren todbringenden Maschinen verwenden können.\n\nIhr müsst zurück zur Mine von Wintergarde gehen, die nordöstlich von hier in den Aasfeldern gelegen ist, und in Besitz dieses seltsamen Erzes gelangen. Die Sache ist für den Erfolg unserer Mission unerlässlich!", progress = "Habt Ihr die Proben des seltsamen Erzes mitgebracht?", completion = "Vielleicht ist dies der Moment, der Augenblick an dem sich die Dinge gegen die Geißel wenden werden. Ihr habt Euch als Held der Allianz erwiesen - zumindest in meinen Augen, &lt;Name&gt;.\n\nWenn Ihr nun so freundlich sein könntet und mir etwas Freiraum ließet. Ich werde etwas mehr Zeit benötigen, um dieses Erz zu untersuchen und Unreinheiten und Schwächen zu entfernen.\n\nWeiter an die Arbeit, Verbündeter. Ich werde mich bei Euch melden, sobald ich Neues habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12273] = {title = "Die Verleumdung", objective = "Hochexekutor Zürner in Gallgrimm hat Euch damit beauftragt, den Stab des Zwangs auf Kommandant Jordan, Kanonierführer Zierhut, Schmied Gutmann und Stallmeister Mercer anzuwenden.\n\nTötet sie, sobald Ihr den Stab verwendet habt, um ihnen als letzte Worte die Verleumdung des Scharlachroten Ansturms abzuverlangen.", description = "Es ist Zeit, dass wir die Streitkräfte des Scharlachroten Ansturms vollkommen demoralisieren!\n\nIch möchte, dass Ihr diesen Stab nehmt und mit ihm vier ihrer Anführer bezaubert: Kommandant Jordan im oberen Stockwerk der Kaserne, Kanonierführer Zierhut auf der südöstlichen Rampe am Strand, Schmied Gutmann in der Schmiede und Stallmeister Mercer bei den Ställen.\n\nBeherrscht sie mithilfe des Stabes, lasst sie den Scharlachroten Ansturm verleumden und tötet sie anschließend!", progress = nil, completion = "&lt;Ihr meint, ein flüchtiges Lächeln über Zürners Gesicht huschen zu sehen.&gt;\n\nIhr seid nun offiziell mein Lieblingstodesritter, &lt;Name&gt;. Falls Ihr Lust dazu habt, dann solltet Ihr es vielleicht in Erwägung ziehen, ein Offizier der Hand der Rache zu werden.\n\nIhr würdet als Todeswache anfangen und ich meine, dass Ihr nach ein paar Jahrzehnten das Zeug zum Juniorexekutor hättet!\n\nNein? Nun ja, übereilen wollen wir es ja nicht... Lasst Euch Zeit und denkt einmal darüber nach.", rewards = "Robe der verkalkten TränenFleischgewebte Gamaschen des FolterersHandgelenksschützer des QuälersSabatons des VollstreckersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12274] = {title = "In Ungnade fallen", objective = "Agentin Skully in Neuherdweiler möchte, dass Ihr die Glocke der Abtei läutet und anschließend vom Hochabt die benötigten Informationen beschafft.", description = "Wir müssen noch mehr vom Hochabt erfahren. Nun, da uns das Gesicht eines Rabenpriesters zur Verfügung steht, können wir Euch nahe genug an ihn heranbringen, damit Ihr mit ihm sprechen könnt.\n\nLeider müssen wir ihn zuerst von seinen Leibwächtern trennen, ansonsten werdet Ihr nie etwas aus ihm herausbekommen.\n\n<Die Agentin stützt sich auf ihre Schaufel und scheint nachzudenken.>\n\nIch denke, ich hab's! Geht die Abtei hinauf und läutet die Glocke, während Ihr verkleidet seid. Daraufhin sollten die Leibwächter des Abtes angerannt kommen, worauf Ihr hinuntergehen und mit ihm sprechen könnt.", progress = "Was habt Ihr herausfinden können? Habt Ihr überhaupt schon mit ihm gesprochen?", completion = "Was zum Teufel ist hier los?!\n\nEr ist von alleine gesprungen? Seid Ihr Euch sicher, dass Ihr ihn nicht gestoßen habt?\n\n&lt;Die Agentin blickt Euch skeptisch an.&gt;\n\nGut. Offensichtlich wird hier mehr gespielt, als wir zuerst dachten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nA Fall from Grace: Quest Completion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12275] = {title = "Der Sprenggnom", objective = "Sprecht mit Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde.", description = "Viertelblitz hat vor Kurzem einen meiner Spezialisten angefordert, um eine Aufklärungsmission in den Minen von Wintergarde durchführen zu können; also habe ich ihm Schleicha geschickt, meinen Sprengmeister. Dummerweise dachte ich, dass er die Grube der Verdammnis nach abgeschlossener Mission hätte zuschütten können, um uns damit einen weiteren Sieg über die Geißel zu bescheren.\n\nNun ist schon ein ganzer Tag vergangen und Schleicha ist noch immer nicht zurück. Ich will wissen, was los ist! Sprecht mit Belagerungsingenieur Viertelblitz und findet meinen vermissten Agenten!", progress = nil, completion = "Ich hab' so ein schlechtes Gefühl deswegen, &lt;Klasse&gt;. Ich fürchte, dass ich in meiner Eile, an das seltsame Erz aus der Mine von Wintergarde heranzukommen, Agent Schleicha womöglich zum Tode verurteilt habe.", rewards = nil}
MultiLanguageQuestData['de'][12276] = {title = "Die Suche nach Schleicha", objective = "Sucht und findet Schleicha den Sprenggnom in den Minen von Wintergarde. Holt Euch Viertelblitz' Zielsuchroboter zu Hilfe, wenn Ihr die Minen nicht finden könnt.\n\nBereitgestellter Gegenstand: \n", description = "Ich hab zwar noch nichts von Schleicha gehört und weiß auch nicht, welches Schicksal ihn ereilt hat, doch vielleicht kann ich dabei helfen, ihn zu finden.\n\n<Viertelblitz hält ein kleines mechanisches Spielzeug in die Höhe.>\n\nDas ist kein Spielzeug, <Klasse>. Tatsächlich handelt es sich hier um meine neueste mechanische Errungenschaft. Sie ist nur dafür da, um das zu finden, was verloren gegangen ist. Die Umstände sind zwar nicht die besten, doch die Maschine ist Eure beste Chance, Schleicha zu finden.\n\nStellt den Roboter neben mir auf den Boden, sobald Ihr mit der Suche beginnen wollt.", progress = nil, completion = "&lt;Schleichas leblose Hand umklammert einen Zettel.&gt;\n\nSie sind hinter mir her. Kein Ausweg. Habe mich versteckt, aber sie wissen, dass ich hier bin. Bald werden sie mich finden.\n\nDie Bergarbeiter schürfen ununterbrochen nach dem seltsamen Erz, mit dem die Kriegsmaschinen der Geißel betrieben werden. Es gibt viel Gerede. Die Sprache des Todes verwirrt mich, doch ich konnte ein paar häufig verwendete Laute und Sätze identifizieren. Das Wort \"Yogg-Saron\" wird dabei mit einem verachtenden Tonfall ausgesprochen, worauf gewöhnlich laute Wutausbrüche folgen. Sie nennen das Erz \"Saronit\". Und das bedeutet?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12277] = {title = "Überlasst nichts dem Zufall", objective = "Beschafft eine Minenbombe von Wintergarde und verwendet sie, um den oberen und unteren Minenschacht von Wintergarde zu sprengen. Erstattet Belagerungsingenieur Viertelblitz bei der Feste Wintergarde in Drachenöde Bericht, sobald Ihr die Aufgabe erfüllt habt.", description = "Lest weiter, wenn Ihr guten Herzens und reinen Gewissens seid.\n\nIn dieser Mine ruht in der Nähe des Schafotts des Vorarbeiters eine ordentliche Ladung Dynamit. Geht hin, nehmt Euch mehrere Stangen Sprengstoff und schlagt Euch zum Eingang der Mine durch. Platziert das Dynamit und sprengt den Eingang in die Luft, sobald Ihr dort angekommen seid. Vergesst nicht, dass es sowohl auf der oberen als auch der unteren Ebene einen Eingang zu den Minen von Wintergarde zu sprengen gibt.\n\nIhr dürft nichts dem Zufall überlassen. Das Böse dort darf niemals freigelassen werden. Möge das Licht Euch den Weg weisen.", progress = nil, completion = "Sein Tod soll nicht umsonst gewesen sein, mein Freund. Die Informationen, für die Schleicha sein Leben gelassen hat, werden Verwendung finden, um den Lichkönig zu bezwingen. Ich verspreche Euch, dass wir das in Ordnung bringen werden.", rewards = "Ehrenhafter UmhangVersteinerter KnochenfußschutzAuf Euch wartet eine dieser Belohnungen:\n\nSonnenstrahlblumenSignet des Schwurs\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12278] = {title = "Bier des Monats e.V.", objective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Euer Papierkram sieht in Ordnung aus. Willkommen im Verein, &lt;Name&gt;!\n\nStellt Euch schon mal darauf ein, zu Beginn jedes Monats Post von uns zu erhalten. Schaut doch mal vorbei, wenn Euch das Bier schmeckt, das Ihr bekommen habt, und wir werden Euch noch mehr davon verkaufen. Dieser Verein gibt und gibt und gibt.", rewards = nil}
MultiLanguageQuestData['de'][12279] = {title = "Bärenhunger", objective = "Bringt Hugh Glass am Handelsposten von Rotholz 6 Nordlachse.", description = "Zum Glück seid Ihr zurück, Hinkejoe! Ich hatte Sorge, dass Griselda und ich ganz allein sein würden.\n\nIch koche uns gerade eine schöne Mahlzeit, aber Griselda will davon nichts wissen.\n\nSie hätte gerne den Fisch, der sich an der Ostwindküste im Osten tummelt. Für mich ist der ja nichts, aber sie war schon immer ziemlich wählerisch. Sechs große Fische sollten eigentlich reichen, um sie glücklich zu machen.\n\nNun, rennt... ähh... hinkt los, Joe. Wir wollen das Mädchen doch nicht warten lassen, oder?", progress = "Wenn Ihr Euch nicht beeilt, wird hier gleich nicht nur ihr Magen knurren...", completion = "Ihr! Ihr seid ja gar nicht Hinkejoe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12280] = {title = "Reparaturen", objective = "Lurz beim Holzfällerposten Blauhimmel möchte, dass Ihr 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern sammelt.", description = "Zwanzig Schredder bis morgen Mittag!\n\nWer macht diese Pläne überhaupt? Auf jeden Fall niemand, der diese Mülleimer schon mal wieder zusammensetzen musste, so viel ist mal sicher…\n\nWenn ich mein Soll erfüllen soll, dann brauche ich Unterstützung. Helft mir und ich teile meine Kommission mit Euch - das ist doch gerecht, oder?\n\nIch brauche Zahnräder, Winkel und Federn. Sie liegen überall auf dem Boden bei den Schreddern herum.", progress = "Und, habt Ihr die Teile für mich?", completion = "Danke, &lt;Name&gt;. Das sollte die Arbeit am Laufen halten - bis morgen jedenfalls…\n\nHier ist das versprochene Geld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12281] = {title = "Die Kriegsmaschine der Geißel verstehen", objective = "Liefert Viertelblitz' Paket bei Oberkommandant Halford Wyrmbann in der Feste Wintergarde ab.", description = "Wir müssen uns mit dem Gedanken trösten, dass Schleichas Tod, wenn auch tragisch, dem Wohle aller gedient hat. Seine Entdeckung in Verbindung mit Euren Heldentaten in der Mine und den von Euch zurückgebrachten Proben bringen uns einen Schritt näher, die Kriegsmaschinerie der Geißel zu verstehen.\n\nBringt Viertelblitz' Paket zu Oberkommandant Halford Wyrmbann. In ihm befinden sich eine Probe des seltsamen Erzes und meine Analyse.", progress = "Ich habe davon gehört, wie tapfer Ihr in der Mine gewesen seid, <Name>.", completion = "&lt;Halford öffnet das Paket und liest sich die Analyse durch.&gt;\n\nIch bin weit davon entfernt, ein Wissenschaftler zu sein, &lt;Name&gt;, Ihr müsst also mein pöbelhaftes Verständnis über das Geschriebene entschuldigen. Nun, sollte ich zumindest die Intelligenz eines heranwachsenden Schuljungens besitzen, dann lässt sich aus dieser Analyse schließen, dass wir noch rein gar nichts über die Kriegsmaschinerie der Geißel wissen. Das Einzige, was wir wissen, ist, dass die Geißel dieses schmutzige Metall zur Herstellung ihrer Belagerungsmaschinen verwendet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12282] = {title = "Spuren der Vergangenheit", objective = "Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr seine Seherkugel holt.", description = "Dieses Land wird von den Erinnerungen der Vergangenheit heimgesucht, <Name>. Ich kann die Schreie der Gefallenen hören, wie sie über ganz Nordend hallen.\n\nArthas hat auf allem, das er berührt hat, ein schreckliches Mal hinterlassen. Es ist also wichtig für uns, etwas über die Vergangenheit zu lernen, damit wir unseren Feind besser verstehen können. Womöglich werden verborgene Wahrheiten zutage treten, die uns bei unserem Unternehmen helfen könnten.\n\nZuerst müsst Ihr meine Seherkugel aus dem Rathaus besorgen, <Name>. Verlasst diesen Turm und biegt nach Links ab, den Pfad entlang, um zum Dorfplatz zu gelangen.", progress = "Habt Ihr meine Seherkugel geholt?", completion = "Gut gemacht, &lt;Name&gt;. Wie vom Schicksal vorherbestimmt, werdet Ihr uns durch diese schweren Zeiten führen. Jetzt beginnt die lange Reise.", rewards = "VisionärsrobeFührungshandschuhe des SehersSchädelkappe der WachsamkeitAuf Euch wartet eine dieser Belohnungen:\n\nVorahnung der Voraussicht\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12283] = {title = "Die Wahrheit wird herauskommen", objective = "Agentin Skully möchte, dass Ihr das Tagebuch von Hochgeneral Abbendis beschafft und es zu Hochexekutor Zürner in Gallgrimm bringt.", description = "Wir müssen herausfinden, was hier vorgeht - und dazu brauchen wir das Tagebuch des Generals!\n\nIch bin mir ziemlich sicher, dass es auf ihrem Nachtkästchen im oberen Stockwerk ihres Hauses liegt - das Haus neben der Kirche, gegenüber den Ställen und dem Sägewerk.\n\nBringt das Tagebuch zum Hochexekutor in Gallgrimm, sobald Ihr es gefunden habt.\n\nIhr werdet das wohl auf die altmodische Art und Weise machen müssen; der Spiegel besitzt nur noch wenig Energie - gerade noch genug für mich.\n\n<Die Agentin grinst.>", progress = "Es wurde auch langsam Zeit, <Name>! Was hat Euch nur aufgehalten?", completion = "Verdammt! Wieso konntet Ihr mir keine guten Neuigkeiten bringen?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12284] = {title = "Haltet sie auf Trab", objective = "Kommandant Bargok möchte, dass Ihr beim Holzfällerposten Blauhimmel 15 Einheiten oder Spieler der Allianz tötet.", description = "Wir mussten hier schlimme Verluste hinnehmen, <Volk>.\n\nDie einzige gute Nachricht ist, dass wir genauso viel ausgeteilt wie eingesteckt haben. Ich habe um Verstärkung gebeten, doch der Großteil unserer Truppen steckt in der Venturebucht fest. Sieht so aus, als ob wir fürs Erste auf uns allein gestellt wären.\n\nEgal, wie schlimm es wird, wir dürfen nicht zurückweichen! Die wertvollen Ressourcen, die diese Region bietet, sind ausschlaggebend für den langfristigen Erfolg der Horde in Nordend.\n\nWir müssen die Allianzler auf Trab halten, bis Hilfe eintrifft. Macht Euch auf den Weg und verpasst ihnen einen Denkzettel.", progress = nil, completion = "Fünfzehn umgelegt, hm? Schön, das zu hören, &lt;Klasse&gt;.\n\nDas hat uns zumindest ein wenig Zeit erkauft - ich schätze wenigstens einen Tag.\n\nHier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12285] = {title = "Tu anderen...", objective = "Hochexekutor Zürner in Gallgrimm hat Euch befohlen, mit dem Kopf des Hochgenerals zurückzukehren.", description = "Ihr Angriff steht kurz bevor, <Klasse>. Ihr müsst dort hineingehen und den Kopf des Scharlachroten Ansturms buchstäblich vom Rumpf abtrennen!\n\nEs wird nicht einfach sein... Abbendis wird sicherlich von einer großen Zahl ihrer Mannen umgeben sein.\n\nBringt mir ihren Kopf und ich werde dafür sorgen, dass Ihr für Gallgrimms Rettung eine anständige Belohnung erhaltet.\n\nSolltet Ihr jedoch versagen, dann kommt bloß nicht wieder zurück!", progress = "Soll ich etwa meinen Truppen sagen, dass wir gen Agmars Hammer ziehen sollen?\n\nOder konntet Ihr den Hochgeneral töten?", completion = "Dann lasst uns mal sehen, ob sie ohne ihren Kopf wieder ins Leben gerufen werden kann!\n\n&lt;Das Gelächter des Hochexekutors zieht etliche verstohlene Blicke auf sich.&gt;\n\nIch mach' mir zwar ein wenig Sorgen darüber, dass Ihr diesen Großadmiral habt entkommen lassen, doch der Held des Tages seid Ihr allemal, &lt;Name&gt;!\n\nSucht Euch etwas aus... Ihr habt es verdient!", rewards = "Der Reinheit gesalbte KriegsbänderHandgelenksschützer der ReumütigenBindungen des machtvollen BezwingersManschetten des EnthauptersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12286] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie diese hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12287] = {title = "Orik Treuherz und der Vergessene Strand", objective = "Sucht Orik Treuherz auf der Dämmerkuppe in der Drachenöde auf.", description = "Ich habe in die Kugel gesehen und sah den Pfad, den Ihr gehen müsst, <Name>.\n\nVor vielen Jahren wurde ein Gräuel an den Küsten der Drachenöde begangen. Die Tat selbst verbleibt im Dunkel, doch ich bin sicher, dass Euer Schicksal im Süden liegt, inmitten der Ruinen des Vergessenen Strands.\n\nNehmt die Straße nach Südosten über den verwüsteten Dorfplatz. Folgt dem Pfad bis Ihr die Dämmerkuppe erreicht. Dort werdet Ihr einen meiner alten Freunde treffen, Orik Treuherz. Er wird Euch erwarten.", progress = nil, completion = "Zelig schickte Nachricht, mein Freund. Wir haben Euch erwartet.\n\nIch bin Orik Treuherz, Paladin des Argentumkreuzzugs. Die Priesterin auf der anderen Seite des Feuers ist Tilda Darathan. Wir sind im Namen der Argentumdämmerung hier, um die unglücklichen verdammten Seelen, die versuchen Wintergarde zu verlassen, zu bezwingen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12288] = {title = "Überfordert!", objective = "Aumana beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Abschnürbinde auf 10 verwundete Scharmützler anwendet.", description = "Ihr da, <Klasse>! Helft mir!\n\nWertvolle Leben gehen verloren! Es gibt einfach viel zu viele Verwundete, als dass ich mich um sie alle alleine kümmern könnte. Wenn wir unsere Soldaten nicht heilen können, dann können wir gleich allesamt unsere sieben Sachen packen und aus den Grizzlyhügeln verschwinden!\n\nHier, nehmt diese Abschnürbinde und verbindet damit die unten auf dem Schlachtfeld liegenden Verwundeten.\n\nBeeilt Euch, <Name>! Sie liegen im Sterben!!", progress = nil, completion = "Oh, ich danke Euch, ich danke Euch.\n\nDank Euch werden wir einen weiteren Tag erleben. Vielleicht gibt es noch Hoffnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12289] = {title = "Tritt rein, solang' sie am Boden liegen", objective = "Unteroffizier Hartsmann möchte, dass Ihr 15 Einheiten oder Spieler der Horde im Holzfällerlager Blauhimmel besiegt.", description = "Dies ist ein schwarzer Tag für die Allianz. Viele gute Menschen sind tot oder liegen im Sterben. Unser einziger Trost ist, dass sie gut gekämpft und viele unserer Feinde mit in den Tod gerissen haben.\n\nDa der Großteil unserer Streitkräfte in der Venturebucht stationiert ist, müssen wir uns diesem Sturm alleine stellen. Die Ressourcen dieser Region sind für die Allianz essentiell und können das Zünglein an der Waage im Kampf gegen die Horde bedeuten. Wir dürfen nicht versagen!\n\nGeht nun, <Name>. Schlagt zu, während sie noch ihre Wunden lecken. Nehmt Rache für Eure gefallenen Kameraden und seid das Licht unserer Hoffnung!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;.\n\nIhr habt uns hier etwas Zeit verschafft, wenn auch wohl nicht mehr als einen Tag. Dennoch dankt Euch die Allianz für Euren Einsatz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12290] = {title = "Das Düstergraselixier", objective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr 5 Düstergräser von den Düsterhöhen holt.", description = "Die Geister der Verdammten spuken an der Küste umher. Zu Lebzeiten waren sie tapfere und ehrenhafte Soldaten der Allianz, doch im Tod sind sie verflucht. Wenn wir sie befreien wollen, müssen wir die Quelle ihrer Pein finden!\n\nIm Südosten, auf den Düsterhöhen werdet Ihr ein seltenes Kraut finden, das Düstergras genannt wird. Daraus werde ich ein Elixier zubereiten, welches Euch zeitlich begrenzten Zugang zur Welt der Vergessenen gewähren wird. Geht jetzt und sammelt das Gras.", progress = "Habt ihr das Düstergras besorgt?", completion = "&lt;Orik nimmt das Düstergras und beginnt, ein Elixier zu mixen.&gt;\n\nEs dauert nicht mehr lange, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12291] = {title = "Die vergessene Geschichte", objective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Euch die Geschichte der vergessenen Arbeiter, vergessenen Scharfschützen, vergessenen Ritter und der vergessenen Fußsoldaten anhört.", description = "Die Toxine im Düstergraselixier werden Euch bewusstlos werden lassen. Die Wirkung des Düstergrases ist so stark, dass selbst Euer Geist getäuscht wird, wodurch Ihr für kurze Zeit in die Welt der Toten eintreten könnt.\n\nWenn Ihr dann ein Geist seid, müsst Ihr mit den geisterhaften Bewohnern des Vergessenen Strands reden. Findet die Quelle ihrer Pein und kehrt zu mir zurück.\n\nDenkt daran, <Name>, diese Geister waren einst Soldaten der Allianz. behandelt sie mit Respekt, Ehre und Würde.\n\nNun nehmt das Elixier und wagt Euch nach Süden zur Vergessenen Küste.", progress = "Ich habe genug Düstergras, um noch mehr Elixiere herzustellen, <Name>.", completion = "&lt;Tränen sammeln sich in Oriks Augen.&gt;\n\nSie wissen es nicht. Keiner von ihnen weiß es! Sie halten Arthas für einen großen Helden, wo es in Wirklichkeit doch Arthas war, der die Schiffe verbrennen lies. Es war Arthas der uns in dieser gefrorenen Öde dem Tod überließ!\n\n&lt;Orik weint.&gt;\n\nNicht alle Soldaten der Flotte des Prinzen sind im frostigen Winter umgekommen. Ich war nur ein Jüngling, als ich die Chance bekam, gegen die Geißel zu kämpfen... und unsere Heimat vor der sicheren Zerstörung zu retten. Ich ergriff diese Chance, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12292] = {title = "Die Unterstützung der Einheimischen", objective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr Euch zum Handelsposten Immergrün begebt und die Zedernholzkiste beschafft.", description = "Der Kampf mit der Horde ist in den Grizzlyhügeln zum Stillstand gekommen. Unsere Streitkräfte sind fast gleich stark und alle Zeichen deuten darauf hin, dass wir eine Pattsituation erreicht haben.\n\nBis zu diesem Morgen jedenfalls. Die einheimischen Fallensteller und Pelzjäger haben um unsere Hilfe gebeten. Anscheinend hat die Horde etwas, das ihnen gehört... Irgendein Relikt.\n\nWir holen es ihnen zurück und gewinnen dank ihrer Unterstützung den Vorsprung, den wir benötigen. Macht Euch auf zum Handelsposten Immergrün, westlich von Burg Siegeswall, und seht Euch nach einer Zedernholzkiste um.", progress = "Habt Ihr die Kiste für mich, <Name>?", completion = "Sie ist verschlossen, oder? Sieht ziemlich gewöhnlich aus.\n\n&lt;Leutnant Dumont schüttelt die Kiste, was ein hölzernes Klappern hervorruft.&gt;\n\nIch denke, das macht nichts. Solange uns das hier einen Vorsprung gegenüber der Horde verschafft, ist es mir auch egal, wenn hier drin das Heilmittel gegen die Seuche wäre.", rewards = "Dorngeschützte BeinlingeUmhang des verletzten FallenstellersFlickfellhoseBeinschützer der behenden VerfolgungSchnappzahnbeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12293] = {title = "Schließt den Handel ab", objective = "Bringt die Zedernholzkiste zu Ivan im Posten des Espenhains.", description = "Wir haben, was die Fallensteller wollen. Nun ist es an uns, sie auf unsere Seite zu bringen.\n\nBringt die Kiste zu einem Fallensteller namens Ivan im Posten des Espenhains, gleich nördlich von hier.\n\nWenn alles gut geht, werden wir bald Waldmänner als Späher für die königliche Armee einsetzen können.", progress = "Habt Ihr etwas für uns?", completion = "Ihr habt es geschafft! Ihr habt die Kiste, welche die Horde uns gestohlen hat, zurückgebracht. Wir danken Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12294] = {title = "Ein vorläufiger Pakt", objective = "Kehrt zu Leutnant Dumont in der Ammertannhütte zurück.", description = "Nun gut, <Name>. Euer Volk hat seinen Teil der Abmachung eingehalten.\n\nSagt Dumont, dass wir auch unseren Teil einhalten werden.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Mit der Hilfe der Einheimischen steht uns auch die logistische Unterstützung zur Verfügung, die wir dazu brauchen, um die Horde in dieser Region auszumanövrieren.\n\nIch habe noch mehr Aufgaben für Euch, falls Ihr daran interessiert seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12295] = {title = "Eine Übung in Sachen Diplomatie", objective = "Sprecht mit dem Entsandten Ducal in Silberwasser.", description = "Wir hatten wochenlang versucht, mit den Fallenstellern zu verhandeln, jedoch erfolglos, bis Ihr ihre verdammte Kiste gefunden habt.\n\nDas sollten gute Neuigkeiten für unseren Entsandten in Silberwasser sein. Vor ungefähr einer Woche haben wir Ducal dorthin geschickt und sein letzter Brief lässt darauf schließen, dass er nur wenig Fortschritt gemacht hat.\n\nGeht nach Silberwasser und helft ihm bei seinen diplomatischen Angelegenheiten. Folgt den Straßen in Richtung Norden. Nach ein paar Brücken solltet Ihr dort ankommen.", progress = nil, completion = "Gut, Euch endlich kennenzulernen, &lt;Name&gt;! Wir haben hier oben von Euch gehört. Willkommen in Silberwasser.\n\nDiese Fallensteller sind ein toller Haufen Jungs und Mädels. Ein hartes Völkchen - sie kennen sich sehr gut mit dem hiesigen Gelände aus. Ihr werdet sehen, dass es eine großartige Sache ist, dass wir sie endlich auf unsere Seite geholt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12296] = {title = "Leben oder Tod", objective = "Rheanna beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Bandage bei 10 verwundeten Westfall-Einheiten anwendet.", description = "Oh, dieses Gemetzel...\n\nIch habe schon viele Schlachten erlebt, <Klasse>, aber das war brutaler als alles, was ich bisher gesehen habe. Unser Kampf gegen die Horde ist erbarmungsloser denn je geworden. Es heißt hier in Nordend sie oder wir... Leben oder Tod.\n\nWenn wir hier auch nur einen Tag länger überleben wollen, müssen wir unsere Verletzten heilen. Es sind zu viele, als dass ich sie alleine retten könnte.\n\nIch habe besondere Verbände hergestellt, die es ermöglichen, dass Ihr mir helfen könnt. Nehmt sie und behandelt diejenigen damit, die ihren Wunden noch nicht erlegen sind.", progress = nil, completion = "Wundervoll!\n\nDie Allianz wird noch einen weiteren Tag erleben, nicht zuletzt dank Eures Fleißes.\n\nNehmt meinen Dank an, Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12297] = {title = "Von Verrätern und Verrat", objective = "Hauptmann Adams möchte, dass Ihr das Schreiben der Allianz zu Greer Erzhammer in Westwacht bringt.", description = "Die Liste, die ich in Händen halte, muss an Oberkommandant Halford Wyrmbann überbracht werden. Er kommandiert die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde stationiert ist.\n\nWenn sich irgendeiner der Verräter auf dieser Liste in Wintergarde befindet... könnten die Folgen katastrophal sein.\n\nBeeilt Euch, <Name>. Zeigt Greer Erzhammer hier in Westwacht dieses Schreiben und erklärt ihm, was es mit Eurer Mission auf sich hat. Für die Reise nach Wintergarde wird er Euch seinen schnellsten Greifen geben!", progress = "Hallo, <Klasse>.", completion = "&lt;Greer schiebt seine Brille auf die Stirn, liest sich die Mitteilung durch und blickt Euch verwundert an.&gt;\n\nIch werde Euch meinen schnellsten Greifen geben! Diese Information muss unverzüglich an Oberkommandant Wyrmbann ausgehändigt werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12298] = {title = "Oberkommandant Halford Wyrmbann", objective = "Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", description = "<Greer gibt Euch das Schreiben wieder zurück.>\n\nHimmelsweise wird Euch nach Wintergarde bringen, <Name>. Ich kann Euch versichern, dass dies der schnellste Flug sein wird, den Ihr je erlebt habt. Geht jetzt!", progress = "Was habt Ihr denn da, Soldat?", completion = "&lt;Der Oberkommandant liest sich das Schreiben durch und zerknüllt es anschließend.&gt;\n\nWisst Ihr, wo sich diese Leute auf der Liste im Moment befinden? Seht Euch draußen in der Nähe des Eingangstores einmal um. Es sind diejenigen, die vom Torbogen baumeln.\n\nGhulköder...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12299] = {title = "Nördliche Gastfreundschaft", objective = "Sergei in Silberwasser will, dass Ihr 8 Marodeure von Burg Siegeswall tötet.", description = "Gut, Euch zu sehen. Lasst uns unseren Pakt zelebrieren, indem wir zünftig auf Hordejagd gehen.\n\nIhr findet außerhalb der Stadt im Westen einige Marodeure von Burg Siegeswall. Warum begebt Ihr Euch nicht dorthin und bringt sie wie räudige Tiere, die sie ja auch sind, zur Strecke?\n\nLasst uns doch mal sehen, ob unsere neuen Verbündeten ihren großen Worten auch Taten folgen lassen.", progress = nil, completion = "Nicht schlecht, nicht schlecht. Am Ende seid Ihr nicht ganz so weich wie manche der anderen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des blutigen FeuersGlücksbringer des BettelmönchsKlaue des Hasses\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12300] = {title = "Eignungstest", objective = "Findet Unteroffizier Knochenknacker nordwestlich von Silberwasser und besteht den Eignungstest.", description = "Gut, <Freund/Freundin>. Ihr habt uns einen oder zwei Gefallen erwiesen, aber das alleine zeugt nicht von Mut.\n\nIn dieser Gegend seid Ihr kein wahrer Jäger, solange Ihr nicht die Haut Eurer Beute tragt.\n\n<Sergei zieht sein Kürschnermesser aus der Scheide und reicht es Euch.>\n\nDer Anführer dieser mutterlosen Orcs, die unsere Stadt angreifen, wird Knochenknacker genannt; Ihr findet ihn in einem Lager weiter nordwestlich von hier.\n\nJa, richtig. Ihr werdet das Monster häuten.", progress = "Die Einwohner Silberwassers... sind nicht das, was sie zu sein scheinen.", completion = "Tut es nicht, &lt;Name&gt;. Die Leute, die Euch hierher sandten... Ihr dürft ihnen nicht trauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12301] = {title = "Möge die Wahrheit uns befreien", objective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Oriks kristalline Kugel in den Ruinen des Vergessenen Strands einsetzt, um die Vergessenen zu erlösen.", description = "Zelig hat mir vor Jahren diese Kristallkugel mit speziellen Anweisungen zu ihrer Verwendung übergeben. Fünf Jahre lang - wann auch immer ich Wut, Angst oder Kummer bezüglich des hier Geschehenen verspürte - sollte ich meine Gedanken auf diese Kugel konzentrieren.\n\nJetzt verstehe ich, wieso Zelig mir diese Kugel gab.\n\nBringt meine kristalline Kugel zum Vergessenen Strand. Findet die Ruinen meiner alten Basis in den oberen Gefilden des Strands und legt die Kugel in die Mitte der Stadt. Lasst die Vergessenen die Welt mit meinem Herzen und meiner Seele sehen.", progress = nil, completion = "&lt;Orik wirft Euch ein Lächeln entgegen.&gt;\n\nIhr habt heute eine gute Tat vollbracht, &lt;Name&gt;. Hunderte verlorener Seelen wurden nun Dank Euch erlöst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12302] = {title = "Worte der Warnung", objective = "Begebt Euch zum nordwestlichen Ende von Silberwasser.", description = "Danke, dass Ihr mir helft, <Name>. Mein Name ist Sasha. Hört zu, ich muss so schnell wie möglich von hier verschwinden.\n\nDie Leute, die Euch hergeschickt haben… meine Leute… sie haben sich verändert. Sie sind keine guten Leute mehr… und wollen, dass Ihr Euch in... in einen von ihnen verwandelt.\n\nDieser... \"Test\", mit dem sie Euch beauftragt haben, ist nur der Anfang.\n\nBegebt Euch zum nordwestlichen Ende von Silberwasser. Dort werdet Ihr etwas Interessantes finden...\n\nViel Glück... und vertraut niemandem.", progress = nil, completion = "Wer ist da? Seid Ihr hier, um mich zu töten?\n\nBitte! Das müsst Ihr nicht tun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12303] = {title = "Die Kriegsanstrengungen finanzieren", objective = "Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 6 vergessene Schätze beschafft.", description = "<Der Rüstmeister senkt seine Stimme und flüstert Euch zu.>\n\n<Klasse>, ich brauche Eure Hilfe - unsere Truhen sind leer. Unsere gesamten Mittel sind an den Vorposten der Kor'kron und den Kampf an der Pforte des Zorns gegangen.\n\nMir wurde jedoch zugeflüstert, dass sich auf den Schiffswracks am Vergessenen Strand im Südosten Schätze ergattern lassen.\n\nWir müssen schon bald etwas unternehmen oder wir werden den Kampf gegen den Scharlachroten Ansturm nicht weiterführen können. Krieg ist nicht gerade billig, müsst Ihr wissen!", progress = "Wie viel von den Allianzschätzen konntet Ihr in Eure Finger bekommen?", completion = "&lt;Dem Rüstmeister stockt der Atem, worauf er Euch einen Moment lang skeptisch mustert.&gt;\n\nIch vertraue einmal darauf, dass Ihr nichts von dem Gold für Euch selbst behalten habt? Ich denke nicht, dass Ihr angesichts dessen, dass hier das Schicksal von Gallgrimm auf dem Spiel steht, so selbstsüchtig sein könntet, oder?\n\nAußerdem werde ich Euch prozentual am Gewinn beteiligen. Es ist zwar nicht viel, doch in Zeiten wie diesen, muss ein jeder Opfer bringen.", rewards = "Kapuze des vergessenen ScharfschützenBruststück des vergessenen HauptmannsKriegsklinge des vergessenen FußsoldatenAuf Euch wartet eine dieser Belohnungen:\n\nValonforts AndenkenReif des vergessenen Söldners\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12304] = {title = "Ein Grundstück am Strand", objective = "Feldmesser Hansen gleich nördlich des Vergessenen Strands möchte, dass Ihr 20 vergessene Geister vernichtet.", description = "Es ist Zeit, dass Gallgrimm expandiert!\n\nWir werden uns um den Scharlachroten Ansturm schon rechtzeitig kümmern, doch zuerst möchte ich, dass Ihr dafür sorgt, dass unsere Anstrengungen am Vergessenen Strand zum Ziel führen. Die Grundstücke dort versprechen einiges, und habt Ihr schon die Aussicht gesehen?\n\nUnglücklicherweise ist der Ort nur so von Menschengeistern, gestrandeten Mannschaften und dergleichen verpestet. Sie wollen einfach nicht wahrhaben, dass sie tot sind.\n\nSäubert den Strand und die Gewässer vor der Küste und wir beide könnten vielleicht darüber reden, dort unten schon bald ein gemütliches, neues Mausoleum zu bauen.", progress = nil, completion = "Habt Ihr's jetzt vor Augen, &lt;Klasse&gt;? Es wird DER Urlaubsort in Nordend schlechthin!\n\nWie gefällt Euch denn der Name \"Hansens Bucht\" oder vielleicht \"Bucht von &lt;Name&gt;\"? Hat was, findet Ihr nicht auch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12305] = {title = "Gedanken des Abschieds", objective = "Kehrt zu Zelig dem Visionär in der Feste Wintergarde in der Drachenöde zurück.", description = "Ihr habt mir und Hunderten von Veteranen der Allianz Ehre erwiesen, <Name>. Es war weise von Zelig, Euch hierher zu schicken. Bitte geht zu ihm zurück und überbringt ihm meinen Dank. Er wird über das, was am Vergessenen Strand geschehen ist, erfreut sein.\n\nDie Gabe, in die Zukunft zu blicken, wurde mir zwar, im Gegensatz zu Zelig, nicht zu Teil. Dennoch bin ich sicher, dass Großes auf Euch wartet, <mein Freund/meine Liebe>.\n\nLebt wohl.", progress = nil, completion = "&lt;Zelig lächelt.&gt;\n\nIch fühle mich Euch zu tiefster Dankbarkeit verpflichtet, mein Held. Orik ist für mich wie ein Bruder. Ihr habt sein Leben verändert und den Hoffnungen zahlloser anderer neues Leben eingehaucht.", rewards = "Kapuze des vergessenen ScharfschützenBruststück des vergessenen HauptmannsKriegsklinge des vergessenen FußsoldatenAuf Euch wartet eine dieser Belohnungen:\n\nValonforts AndenkenReif des vergessenen Söldners\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12306] = {title = "Bier des Monats e.V.", objective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", description = "Gemeinsam ist man stark, <Name>. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Du wirst dich uns anschließen, &lt;Name&gt;? Wir sind gut zu dir, Mann. Wenn du bei diesem Verein mitmachst, bekommst du nur das Beste!\n\nZu Monatsbeginn schicken wir dir Bier. Wenn's dir schmeckt, dann komm doch wieder hierher. Wir sorgen dafür, dass du noch mehr davon bekommst.", rewards = nil}
MultiLanguageQuestData['de'][12307] = {title = "Wolfsbannwurzel", objective = "Katja in Silberwasser möchte, dass Ihr 8 Wolfsbannwurzeln ausreißt.", description = "Habt Ihr schon von der Wolfsbannpflanze gehört? Es ist ein schreckliches Unkraut... es zerstört unsere Ernte.\n\nWir haben die ganze letzte Woche damit verbracht, es zu beseitigen, doch die Wurzeln fangen wieder an zu sprießen.\n\nEs mag vielleicht nicht dringend erscheinen, doch ein Wiederaufleben der Pflanze könnte eine wahre... Katastrophe sein. Denkt Ihr, dass Ihr uns dabei helfen könntet, die Wurzeln in der Nähe des Dorfes herauszureißen?", progress = nil, completion = "&lt;Katja schwankt und wendet sich nervös von Euch ab.&gt;\n\nIch danke Euch, &lt;Name&gt;. Ihr seid nicht mit Wolfsbann in Berührung gekommen, oder? Ich hab' diese... Allergien, die mir hin und wieder Probleme bereiten.", rewards = "Tuch der GartenpflegeSchulterstücke des KräutersammlersGurt der wachsenden RankenAuf Euch wartet eine dieser Belohnungen:\n\nSchnittanhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12308] = {title = "Flucht aus Silberwasser", objective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!", progress = nil, completion = "Worgen. Verdammte, vom Licht verlassene, dreckige Worgen.\n\nEs ist an der Zeit, dass wir den Einheimischen zeigen, was zivilisierte Leute mit Bestien, wie sie es sind, machen werden.", rewards = "Gewandung der eingesperrten BestieStiefel des inneren LeidensHandgelenksschützer der gequälten SeeleSabatons der vernichteten MenschheitAuf Euch wartet eine dieser Belohnungen:\n\nWorgtöterring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12309] = {title = "Findet Durkon!", objective = "Sucht Dragoner Durkon bei der Gruft von Wintergarde in der Drachenöde auf.", description = "Nachdem die Geißel an der Südmauer durchgebrochen war, habe ich Dragoner Durkon befohlen, die örtliche Gruft zu untersuchen. Vor wenigen Augenblicken habe ich seinen Bericht erhalten.\n\nDie Untoten, die uns heimsuchen, kommen aus zwei Quellen: den Ruinen von Wintergarde, die nun eine Brutstätte der Geißel sind, und aus unserer eigenen Gruft! In all dem Chaos und der Verwirrung hat es die Geißel geschafft, einen Nekrolord in die Gruft zu bekommen.\n\nIn seiner Nachricht bat Durkon um Unterstützung. Ihr werdet ihn suchen und ihm helfen, <Name>. Die Gruft befindet sich an der westlichen Grenze des Dorfplatzes.", progress = nil, completion = "Oh Junge, hier unten ist die Hölle los! Ich habe es beim letzten Mal kaum lebend herausgeschafft - weshalb ich dann die Bitte an den Hochkommandaten gestellt habe.\n\n&lt;Durkon mustert Euch von oben bis unten.&gt;\n\nIhr habt diesen irren Blick in Euren Augen, &lt;Volk&gt;. Glücklicherweise muss man irre sein, um das zu tun, was ich gleich von Euch verlangen werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12310] = {title = "Eine prompte Reaktion", objective = "Leutnant Dumont möchte, dass Ihr zum Posten des Waldrands geht und Vladek sowie 7 Fährtenleser von Silberwasser erledigt.", description = "Unsere Reaktion muss prompt erfolgen. Und entschlossen. Wir müssen diesen Wilden zeigen, dass sie sich besser nicht mit uns anlegen sollten.\n\nUnsere Späher haben die restlichen Fährtenleser von Silberwasser ausfindig gemacht… Ihr wisst schon, die, die nicht in den Flammen umgekommen sind. Anscheinend blockieren sie die Straße nach Südosten... vielleicht versuchen sie ja, uns einzukreisen.\n\nBegebt Euch zum Posten des Waldrandes und kümmert Euch um sie. Ihr Anführer ist angeblich ein Mann namens Vladek... stellt sicher, dass er auf der Strecke bleibt.", progress = "Ist es vollbracht, <Name>?", completion = "Was für eine Schande, dass sich diese Fährtenleser als… befallen herausgestellt haben. Wir hätten schon noch ein paar mehr Kämpfer gebrauchen können.\n\nMögen ihre armen Seelen in Frieden ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12311] = {title = "Die Gruft des Adligen", objective = "Dragoner Durkon in der Feste Wintergarde möchte, dass Ihr Nekrolord Amarion tötet.", description = "Innerhalb der kalten Steinmauern dieser Gruft liegen die Gebeine der Adligen und der Würdenträger Nordends. Im Herzen dessen sitzt jetzt ein Nekrolord und erweckt die Leichen als Diener der Geißel wieder.\n\nIhr müsst es bis zum Ende der Gruft schaffen und Nekrolord Amarion töten. Nur dann wird der Angriff aus dem Inneren der Gruft zum erliegen kommen!\n\nUnd, <Name>, haltet Ausschau nach allen Informationen, die sich in dem Raum verbergen, in dem Amarion haust.", progress = nil, completion = "Wenn wir es jetzt schaffen, die Angriffe der Geißel vom Äußeren der Feste zu stoppen, schaffen wir es vielleicht, Hilfe zu Lord Fordragon an der Pforte des Zorns zu schicken.", rewards = "Gewänder des EiswüstenhauchsKapuze des SchneewehenhäschersEisscherschulterstückeKristallplattenstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12312] = {title = "Geheimnisse der Geißel", objective = "Bringt den fleischgebundenen Folianten zu Dragoner Durkon in der Feste Wintergarde in der Drachenöde.", description = "Um die fleischgebundenen Kapitel dieses Folianten herum sind seltsame Symbole gekritzelt sowie Formen, die mit einer Klinge in die Seiten gekratzt worden zu sein scheinen. Ihr habt keine Ahnung, was dort geschrieben steht, doch Ihr seid Euch sicher, dass, was auch immer es sein mag, es wichtig ist.\n\nÜbergebt den Folianten an Dragoner Durkon, welcher an der Oberseite der Gruft von Wintergarde Wache hält.", progress = "Ein Foliant der Geißel?", completion = "Welche Informationen dieses Buch auch birgt, sie müssen von großer Bedeutung sein! Als Ihr auf der Flucht wart, konnte ich das Heulen und Klagen durch die Gruft hallen hören!\n\nDer Oberkommandant muss darüber in Kenntnis gesetzt werden!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12313] = {title = "Rettet das Braufest!", objective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.Rettet das Braufest! Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Rettet das Braufest! Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12314] = {title = "Nieder mit Kapitänin Zorna!", objective = "Tötet Kapitänin Zorna und erstattet Baron Freimann in der Venturebucht Bericht.", description = "Die Streitkräfte der Horde sind kurz davor, unsere Reihen zu durchbrechen und die Eroberung der Venturebucht abzuschließen, wenn wir nicht handeln. Ihre Soldaten werden dabei von Kapitänin Zorna angeführt, in der Nähe des Schiffs an der abgelegenen Seite der Bucht.\n\nWenn Ihr sie besiegen könnt, bricht die Offensive der Horde zusammen und wir können den Hafen einnehmen. Seid auf der Hut, <Name>, denn Zorna ist eine starke Kämpferin. Ihr werdet mehrere Leute brauchen, um sie zu besiegen, es sei denn, Ihr habt Zugang zu einem reparierten Schredder. Den könntet Ihr zu Eurem Vorteil einsetzen.", progress = "Habt Ihr Kapitänin Zorna erschlagen?", completion = "Gut gemacht, &lt;Name&gt;! Ohne ihre Anführerin ist die Horde schwach und unorganisiert. Ich werde unsere Männer zum Angriff formieren.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von NordendEhrepunkte"}
MultiLanguageQuestData['de'][12315] = {title = "Zerschmettert Kapitän Hellwasser!", objective = "Tötet Kapitän Hellwasser und erstattet anschließend General Khazgar in der Venturebucht Bericht.", description = "Mit jedem Vorrücken treffen unsere Männer auf frische Truppen der Allianz, so als ob ihr Kommandant jeden meiner Schritte vorausahnen würde!\n\nEs ist an der Zeit, dass für den guten Kapitän Hellwasser die letzte Stunde schlägt. Er befehligt seine Truppen von Bord eines Zerstörers der Allianz am anderen Ende der Bucht.\n\nDas wird kein einfacher Kampf, <Name>! Zieht mit ein paar vertrauensvollen Freunden los oder schlitzt Hellwasser mit einem der reparierten Schredder auf, falls Ihr einen Schlüssel dafür besitzt! So oder so - er muss sterben!", progress = nil, completion = "Ihr seid ein wahrer Soldat der Horde, &lt;Name&gt;! Euer Mut wird meine Männer zum Sieg führen!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von NordendEhrepunkte"}
MultiLanguageQuestData['de'][12316] = {title = "Haltet sie auf!", objective = "Besiegt 10 Einheiten oder Spieler der Horde in der Venturebucht und kehrt zu Leutnant Stuart zurück.", description = "Wir können nicht zulassen, dass die Horde die Venturebucht kontrolliert. Der Hafen ist für unsere Operationen in den Grizzlyhügeln und dahinter überlebenswichtig.\n\nHauptmann Starkmantel ist mit dem Rest der Westfallbrigade nach Osten aufgebrochen, um einen Weg durch die Berge zu finden, also haben wir keine Verstärkungen mehr.\n\nWerft Euch in die Schlacht, <Name>, und tötet die Berserker aus Burg Siegeswall, welche die Horde gegen uns gesandt hat. Mäht sie nieder, bis keiner mehr steht. Die Allianz muss diesen Hafen einnehmen!", progress = nil, completion = "Eure Tapferkeit hat die Männer der Westfallbrigade inspiriert. Nun kämpfen sie mit noch größerer Entschlossenheit. Der Hafen wird bald unser sein.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12317] = {title = "Haltet sie auf!", objective = "Besiegt 10 Einheiten oder Spieler der Allianz in der Venturebucht und kehrt zu Zenturion Kaggrum zurück.", description = "Diese vermaledeite Westfallbrigade stellt sich als härterer Gegner heraus, als wir gedacht haben. Obwohl sie nur wenige sind, kämpfen sie gut und tapfer, und wir können es uns nicht leisten, abzuwarten.\n\nDer Befehl Eroberin Krennas lautet, den Hafen schnell einzunehmen. Ihr müsst die Pattsituation aufheben, <Name>. Findet die Marinesoldaten des Gegners und schlachtet sie ab, bis der Widerstand gebrochen ist. Erst dann können wir den Hafen einnehmen.\n\nBeeilt Euch. Wir wollen Eroberin Krenna nicht warten lassen.", progress = nil, completion = "Der Hafen wird bald unser sein. Ihr habt uns heute einen großen Dienst erwiesen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12318] = {title = "Rettet das Braufest!", objective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", description = "<Name>, unsere Spione haben ein teuflisches Komplott ans Licht gebracht! Die Dunkeleisenzwerge wollen unser geliebtes Braufest dem Erdboden gleichmachen!\n\nCoren Düsterbräu, Oberhaupt einer abtrünnigen Familie von Braumeistern, hat die Zwerge der Schwarzfelstiefen mobilisiert – zudem werden wir auch noch ständig von ihren Maulwurfmaschinen angegriffen.\n\nUnser Spion befindet sich im \"Grimmigen Säufer\", einer Taverne im Inneren des Schwarzfels. Er wird mehr über Düsterbräus Komplott wissen.", progress = nil, completion = "Ihr kommt vom Braufestlager? Was für ein Tag! Das Braufest kann vielleicht noch gerettet werden.\n\n&lt;Name&gt;, Coren Düsterbräu muss gestoppt werden! Wir dürfen nicht zulassen, dass er unseren heiligen Feiertag sabotiert. Das Bier muss fließen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12319] = {title = "Das Rätsel des Folianten", objective = "Übergebt Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde den fleischgebundenen Foliant.", description = "Worum könnte es sich handeln, <Name>? Es handelte sich bestimmt um keinen gewöhnlichen Fluch, den der verdammte Lich auf Euch gelegt hat!\n\n<Durkon blättert die entsetzlichen Seiten des Folianten durch.>\n\nIch weiß nicht einmal, ob ich es richtig herum halte. Wir müssen herausfinden, welche Informationen dieser Foliant birgt!\n\n<Durkon gibt Euch das Buch.>\n\nDer Oberkommandant wird wissen, was zu tun ist. Bringt ihm den fleischgebundenen Folianten und schildert ihm genau, was hier vorgefallen ist.", progress = "Der Nekrolord ist Geschichte?", completion = "&lt;Halfords Augen öffnen sich weit.&gt;\n\nDas Schicksal lächelt heute auf uns herab, &lt;Name&gt;. Ich kenne genau den Richtigen, den man wegen dieses Folianten aufsuchen muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12320] = {title = "Die Sprache des Todes verstehen", objective = "Bringt den fleischgebundenen Folianten zu Inquisitor Hallard im Gefängnis der Feste Wintergarde.", description = "Nehmt das Buch und folgt dem Pfad zur Kaserne. Nehmt in der Kaserne die Treppe hinunter zum Gefängnis. Dort werdet Ihr Inquisitor Hallard und unseren Bürgermeister Gottfried finden. Ich glaube, dass Gottfried das fehlende Teil dieses Puzzles ist und das Hallard genau der richtige ist, um daraus ein vollständiges Bild zu machen.\n\nGeht!", progress = "Kommt Ihr vom Oberkommando, mein Sohn?", completion = "Mit der entsprechenden Motivation wird uns Gottfried vielleicht verraten, was er darüber weiß.\n\n&lt;Hallard wendet sich Bürgermeister Gottfried zu.&gt;\n\nNicht wahr, Bürgermeister?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12321] = {title = "Eine rechtschaffene Predigt", objective = "Wartet, bis Inquisitor Hallard seine rechtschaffene Predigt gehalten hat, und kehrt dann mit Euren Entdeckungen zu Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde zurück.", description = "Gottfried Guters, einst ein rechtschaffener Mann und Bürgermeister von Wintergarde, arbeitet nun für die Geißel. Seine Verwandlung vom Menschen zu einem untoten Ghul kam langsam und mit der Zeit. Nun hört er den Ruf des Lichkönigs und lebt nur noch, um seinem Meister zu dienen.\n\nDoch wie alle Mitglieder der Geißel beherrscht Gottfried die Sprache des Todes und mit der richtigen Überredungskunst wird er uns erzählen, was wir über den Folianten wissen müssen.\n\nKehrt zum Oberkommandanten an die Front zurück, sobald Ihr gehört habt, was Ihr hören sollt. Ich werde hier dementsprechend aufräumen.", progress = nil, completion = "Wir hätten über das verfluchte Mausoleum Bescheid wissen sollen. Das ist absurd! Herzog August Feindhammer und Ambo Unkesch werden zur Vorbereitung des nächsten Angriffs an die Front geschickt werden.\n\nSobald Ihr die Minen geräumt habt, werde ich Euch zu Feindhammer schicken, sodass wir mit unserem Angriff auf die Geißel von Naxxramas beginnen können!\n\nDie bisher von Euch gesammelten Informationen werden von unseren fähigsten Greifen zu Lord Fordragon an die Pforte des Zorns gebracht werden!", rewards = "Gelenkbänder der HochseeStiefel des LichtungswanderersSchulterschutz des WestwindsAuf Euch wartet eine dieser Belohnungen:\n\nSünderbuße\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12323] = {title = "Räuchert sie aus", objective = "Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Unteroffizier Downey.", description = "In einigen der Gebäuden hier in der Mitte der Venturebucht gibt es noch immer vereinzelte Gruppen von feigen Mitarbeitern der Venture Company. Ich brauche zwar jeden Mann, den ich entbehren kann, da draußen für den Kampf gegen die Horde, jedoch können wir genauso wenig zulassen, dass diese Nachzügler der Venture Company in diesen Gebäuden campieren.\n\nVielleicht können wir sie davon \"überzeugen\", auf ihr Schiff zurückzukehren. Nehmt diese Rauchbombe hier und räuchert mit ihr die Nachzügler in der Baracke, dem Sägewerk oder im Stall aus. Geht jedoch nicht zu nah ran - wahrscheinlich beißen sie.", progress = "Habt Ihr schon den letzten Rest der Männer von der Venture Company ausgeräuchert?", completion = "Gut gemacht, Soldat! Nun kann sich der Rest der Männer auf die Horde konzentrieren.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12324] = {title = "Räuchert sie aus", objective = "Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Steingardist Rachtotem.", description = "Es ist ja nicht nur so, dass dieser Hafen lediglich mit feigen Allianzheulsusen verpestet wäre, nein, denn um die Sache noch schlimmer zu machen, gibt es noch immer Mitarbeiter der Venture Company, die sich in einigen Gebäuden verkrochen haben. Es ist einfach reine Zeitverschwendung, sie zu töten, und ich kann sowieso keine Krieger entbehren.\n\nVielleicht können wir sie davon \"überzeugen\", auf ihr Schiff zurückzukehren. Nehmt diese Rauchbombe hier und räuchert mit ihr die Nachzügler in der Baracke, dem Sägewerk oder im Stall aus. Geht jedoch nicht zu nah an sie ran - man kann nie wissen, welche Krankheiten sie in sich tragen.", progress = nil, completion = "Der General wird sehr darüber erfreut sein, dass Ihr Euch um die Venture Company gekümmert habt. Nun können sich die Männer darauf konzentrieren, die Allianz zurückzuschlagen.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12325] = {title = "Hinein ins Feindgebiet", objective = "Sprecht mit Greifenmeister Urik und fliegt zu Thorsons Posten. Meldet Euch bei Herzog August Feindhammer, wenn Ihr bei Thorsons Posten in der Drachenöde angekommen seid.", description = "Ihr habt viel zu unserem Kampf gegen die Geißel beigetragen, <Name>. Tatsächlich steigt die Moral derjenigen, die mit Euch in Berührung gekommen sind, rasant an! Solch einen Einfluss habt Ihr auf die Soldaten und Bewohner von Wintergarde, <Verbündeter/Verbündete>.\n\nUnd es ist Euch zu verdanken, dass wir nun darauf vorbereitet sind, in die Offensive zu gehen! Ihr sollt Euch bei Herzog August Feindhammer melden. Er befindet sich auf der anderen Seite der Aasfelder bei Thorsons Posten, östlich von hier. Greifenkommandant Urik an der Greifenstation hat einen speziellen Greifen bereitgestellt, der Euch hinter Feindeslinien absetzen wird. Geht jetzt!", progress = nil, completion = "Ah, der namhafte Held ist angekommen. Willkommen im Zentrum des Geschehens, &lt;Name&gt;. Erlaubt mir, Euch auf den neuesten Stand zu bringen!\n\nThel'zans stärkste Truppen haben sich bis ins Mausoleum von Wintergarde durchgekämpft. Sie erkunden seine Tiefen auf der Suche nach Leichen und Seelen, um sie auf Wintergarde zu hetzen, während Naxxramas schreckliche Seuchenmaschinen der Geißel auf uns niederprasseln lässt, um uns in Schach zu halten!\n\nWir müssen jetzt zuschlagen und darauf hoffen, dass Lord Fordragon bei den Zornpforten noch etwas länger durchhalten kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12326] = {title = "Dampfpanzerüberraschung", objective = "Zerstört mithilfe des Dampfpanzers der Allianz 6 Seuchewagen und ladet die Elitesoldaten der 7. Legion beim Mausoleum von Wintergarde ab. Sprecht anschließend mit Ambo Unkesch im Inneren des Mausoleums von Wintergarde, wenn Eure Aufgabe erledigt ist.", description = "Diese Mission dreht sich nur um eins: Suchen und Vernichten. Ihr werdet mit einem Panzer in die Aasfelder fahren und die Seuchewagen in ihre Einzelteile zerlegen. Der Panzer wird von drei Soldaten der 7. Legion begleitet, die alle überleben müssen, wenn die Mission erfolgreich enden soll!\n\nIhr werdet nah an einen Seuchewagen heranfahren müssen, um Euren Ingenieur einzusetzen. Sobald es keine Seuchewagen auf dem Feld mehr gibt, bewegt Euch in Richtung des Mausoleums, das sich vor der zerstörten Festung befindet, und setzt den Rest Eures Trupps ab. Trefft Euch im Inneren des Mausoleums mit Ambo Unkesch.", progress = "Man nennt mich Unkesch - Ambo Unkesch. Und das Vergnügen ist ganz auf deiner Seite.", completion = "Wieso ich keine Hosen trage, ist nicht wichtig. Sagen wir einfach mal, dass mich ein Schrapnell der Geißel am falschen Ort getroffen hat und belassen es dabei, in Ordnung?\n\nDu hast also die Seuchewagen auf den Feldern alle gemacht und meine Soldaten in einem Stück hier abgeliefert. Beeindruckend. Du bist einer der Ersten, der's bis hierher geschafft hat, Kumpel. Schade nur, dass du gleich wieder raus auf die Aasfelder musst. Ja, genau - wir hatten so was wie 'nen kleinen Rückschlag.", rewards = "Wickeltuch des SaboteursAuf Euch wartet eine dieser Belohnungen:\n\nRitueller NackenschutzFackelring des Belagerungsmeisters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12327] = {title = "Außerkörperliche Erfahrung", objective = "Trinkt den samtigen Trank bei Ruunas Kristallkugel und werdet Zeuge einer Vision der Vergangenheit.", description = "Ah, Ihr sucht nach einer Vision der Vergangenheit. Ihr seid <ein weiser/eine weise:r> <Volk>.\n\nJedes Mal, wenn jemand hierher kommt und etwas wissen möchte, dann wollen sie anscheinend immer nur die Zukunft erfahren. Wenn Ihr mein Alter erreicht, dann erkennt Ihr, dass es in den meisten Fällen einfach nützlicher ist, in die Vergangenheit zu blicken.\n\nTrinkt von diesem Trank und werft einen Blick in meine Kristallkugel. Lasst uns sehen, was wir herausbekommen können.", progress = "Ja, <Name>?", completion = "Habt Ihr irgendetwas aus Eurer Vision erfahren können? Ihr habt Julheim erwähnt, während Ihr Euch in Trance befandet - was das zweite Mal ist, dass heute jemand den Namen dieses Ortes ausspricht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12328] = {title = "Ruunas Bitte", objective = "Ruuna die Blinde möchte, dass Ihr 4 Handvoll samtigen Staubs besorgt.", description = "Ich werde Euch für meine Dienste kein Gold abnehmen, weil ich ahne, dass Eure Taten notwendig sind und viel davon abhängt, was Ihr heute lernt.\n\nIch werde Euch jedoch darum bitten, ein Reagenz für mich zu besorgen. Bringt mir samtigen Staub von den Farnfressermotten nordöstlich von hier. Tut das und ich werde Euch einen Trank bereiten, der Euch an den Ort und die Zeit bringt, da die Geschehnisse stattfanden, die Ihr gesehen haben müsst.", progress = "Habt Ihr den Staub bekommen, <Name>?", completion = "Gut. Das wird ausreichen.\n\nIm Handumdrehen werde ich den Trank fertig haben.", rewards = "Gurt des WahrsagersSchulterstücke des ProphetenHandschutz mit hauchdünnen FleckenGedankenklärender SchutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12329] = {title = "Schicksal und Zufall", objective = "Sprecht mit Sasha im Handelsposten Weißkiefer.", description = "Es gibt zwei Arten von Leuten auf dieser Welt, <Name>. Diejenigen, die an den Zufall glauben, und diejenigen, die nicht daran glauben.\n\nAn dem Tag, als ich mein Augenlicht verlor, wurde mir das Geschenk des Hellsehens zuteil. Ich nehme an, dass Ihr erraten könnt, zu welcher Gruppe von Leuten ich gehöre.\n\nHeute früh wurde einer jungen Frau namens Sasha dieselbe Vision gewährt wie Euch. Ihr werdet mit ihr sprechen wollen.\n\nIhr findet sie direkt östlich von hier im Handelsposten Weißkiefer auf dem Weg nach Julheim.", progress = nil, completion = "Ich habe mich schon gefragt, wann Ihr auftauchen würdet. Denkt Ihr, dass Ihr mir hier helfen könntet?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12330] = {title = "Anatol wird reden", objective = "Sasha im Handelsposten Weißkiefer möchte, dass Ihr den Betäubungspfeil nehmt und ihn auf Tatjana in Julheim schießt. Bringt Tatjana dann zum Handelsposten Weißkiefer zurück.", description = "Meine Schwester ist hier irgendwo, und ich kriege dieses Monster einfach nicht zum Reden.\n\nEr kümmert sich anscheinend nicht um sein eigenes Wohlergehen, aber ich habe da eine Idee. Ich kenne Anatols Frau, Tatjana, noch aus der Zeit, bevor der Wolfkult ankam; sie war eine Pferdehändlerin.\n\nNehmt diesen Betäubungspfeil. Bringt sie lebend zurück, wir werden sie brauchen, wenn wir ein Druckmittel gegen Anatol haben wollen.\n\nIch werde Euch helfen, die Person, die hinter all dem steckt zu finden, sobald wir meine Schwester haben.", progress = nil, completion = "Das… das war knapp.\n\nWir müssen Anya retten. Jetzt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSonnenwendsiegelTatjanas AnhängerSiegel des schlummernden Wolfs\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12331] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
