MultiLanguageQuestData['de'][12410] = {title = "Eimer mit Süßigkeiten", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12411] = {title = "Das Gelöbnis der Schwester", objective = "Sucht nach Anya im Grauheulerbau in der Nähe von Julheim.", description = "Bitte, <Name>. Ich weiß, Ihr seid hinter Arugal her. Ich schwöre bei meinem Vater, dass ich Euch helfen werde, ihn zur Strecke zu bringen.\n\nAber ich flehe Euch an… Anya ist komplett unschuldig, wir können sie nicht diesen Wilden überlassen.\n\nHelft mir, meine Schwester zu retten und Ihr könnt mich an Eurer Seite wissen, wenn Ihr Euch Arugal stellt.\n\nIch kenne die Höhle, von der Anatol gesprochen hat. Sie befindet sich auf der anderen Seite dieses Hügels. Lasst uns gehen, meine Schwester ist in Gefahr.", progress = nil, completion = "Ich will nicht mehr hier bleiben. Die Worgenmänner sind gemein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12412] = {title = "Freund meines Feindes", objective = "Eroberin Krenna in Burg Siegeswall möchte, dass Ihr 8 Jäger von Silberwasser und ihren Anführer Vladek am Posten des Waldrands tötet.", description = "Wenn ich in Euren Kopf nur eine Sache hineinbekomme, dann soll es die hier sein: Die Allianz muss in den Grizzlyhügeln zerschmettert werden.\n\nEs gibt dort zu viel Holz, Erz, Wild und strategisches Territorium für uns, als dass wir auch nur an einer einzigen Front nachgeben dürften.\n\nBisher waren wir siegreich... aber da gibt es etwas, das das Zünglein an der Waage zugunsten unseres Feindes sein könnte.\n\nWeit östlich von hier am Posten des Waldrands, wollen sich Fallensteller der Allianz anschließen. Tötet sie, ehe sie Gelegenheit dazu haben.", progress = nil, completion = "Ihr seid zurück. Und am Leben.\n\nNun, was soll dieser Unsinn über Worgen?", rewards = "Dorngeschützte BeinlingeUmhang des verletzten FallenstellersFlickfellhoseBeinschützer der behenden VerfolgungSchnappzahnbeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12413] = {title = "Angriff auf Silberwasser", objective = "Eroberin Krenna in Burg Siegeswall möchte, dass Ihr 8 Verteidiger von Silberwasser in den Hügeln von Silberwasser erschlagt.", description = "Vor ein paar Stunden waren die Fallensteller nichts weiter als eine Bande Arbeiter, die sich der Allianz anzuschließen drohten.\n\nDoch nun sind sie etwas anderes... nämlich ein Risiko. Ich mag Risiken nicht. Geht zu den Hügeln außerhalb ihrer Hauptstadt Silberwasser im Norden der Grizzlyhügel und helft meinen Männern, sie zu vernichten.", progress = nil, completion = "Nicht schlecht, &lt;Name&gt;. Ihr seid womöglich zu mehr zu gebrauchen, als ich zuerst gedacht hatte.", rewards = "Gewandung der eingesperrten BestieStiefel des inneren LeidensHandgelenksschützer der gequälten SeeleSabatons der vernichteten MenschheitAuf Euch wartet eine dieser Belohnungen:\n\nWorgtöterring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12414] = {title = "Aufgesessen", objective = "Reitet 5 Hochlandmustangs zurück zu Knappe Percy im Lager der Westfallbrigade.", description = "Hauptmann Starkmantel hat den Großteil unserer Kallvarie... Kavllarie... äh, Reiterei für den Kampf in der Venturebucht zurückgelassen.\n\nWir haben 'nen guten Platz für das Lager ausgewählt, weil hier in der Gegend und in den Felshügeln Massen von Hochlandmustangs umherrennen. Der Hauptmann hat mir befohlen, 'n paar von denen zu fangen.\n\nHelft Ihr dabei? Ich habe einen Stock und ein bisschen Schnur und da wachsen haufenweise wilde Karotten in der Nähe des Lagers. Pflückt Karotten und benutzt sie zusammen mit dem Stock, um den Mustang anzulocken. Reitet anschließend mit ihm hierher zurück.", progress = nil, completion = "Oh! Das sind auf alle Fälle gute Pferde! Ich denke, der Hauptmann wird ziemlich zufrieden mit unserer Arbeit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12415] = {title = "Der Pferdebrüller", objective = "Erschreckt 15 Hochlandmustangs und kehrt zu Soolok Sturmwut im Camp Oneqwah zurück.", description = "Die \"Westfallbrigade\" der Allianz lagert weit im Norden nahe Thor Modan. Törichterweise haben sie ihre Streitkräfte aufgeteilt, um sich gegen unsere Kontrolle der Venturebucht aufzulehnen, und sind nun ohne Kavallerie.\n\nIm Moment versuchen sie, die wilden Hochlandmustangs zu fangen und zu zähmen, die im Gebiet um das Lager der Westfallbrigade herum und in den Felshügeln leben. Wir müssen sie aufhalten, ehe sie ihre verlorenen Reittiere ersetzen können. Nehmt dies und werft es in die Nähe der Pferde, um sie zu verscheuchen.", progress = nil, completion = "&lt;Soolok nickt anerkennend.&gt;\n\nGut gemacht, &lt;Name&gt;. Wir dürfen die Allianz keinen einzigen Vorteil gewinnen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12416] = {title = "Im Eifer des Gefechts", objective = "Unterstützt Hauptmann Iskandar, die Schluchten zu halten. Tötet 12 eisige Ghulangreifer, 8 eisige Spukangreifer und 1 eisigen Monstrositätenangreifer.\n\nKehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist.", description = "Die Geißel hat den Schrein gestürmt. Die Bewahrerin des Schreins, Dahlia Sonnenhand, ist nicht aufzufinden. Die roten Wyrms, die bei der Verteidigung des Schreins fielen und nun die Gestalt pervertierter Skelettglutwyrms angenommen haben, suchen uns nun heim. Die Situation ist ernst, <Volk>.\n\nHauptmann Iskandar führt eine Gruppe von Leuten wie Euch an und versucht, den Zustrom der Geißel einzudämmen, der aus dem Schrein kommt.\n\nUnterstützt ihn... aber bleibt bitte hinter seinen Männern. Der Strom der Geißel ist endlos und ich möchte Euch nicht in einer dieser zerklüfteten Schluchten verlieren.", progress = "Ich bin froh, dass Ihr noch unter den Lebenden seid, <Volk>.", completion = "Es war eine widerwärtige Aufgabe und ich danke Euch recht herzlich dafür.\n\nDie Geißel darf nicht noch näher an den Wyrmruhtempel herankommen, sonst werden wir den Tempel mit Sicherheit verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12417] = {title = "Zur Erde zurückkehren", objective = "Erlangt über einen der nördlichen oder südlichen Pässe Zugang zum Rubindrachenschrein und sucht nach Rubineicheln. Pflanzt die Rubineicheln in der Nähe der gefallenen roten Drachen ein, um ihre Leichen wieder der Erde zu übergeben. Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist.", description = "Ich habe noch eine Aufgabe, die Aufmerksamkeit erfordert. Meine Brüder sterben im Kampf dort oben und wenn wir nicht schnell handeln, werden sie nur die Ränge der Magmawyrms verstärken.\n\nÜber die anderen Pässe im Süden oder Norden könnt Ihr in den Schrein gelangen... die Geißel dürfte dort nicht so stark vertreten sein.\n\nSucht im Schrein nach Rubineicheln, die vom Baum gefallen sind, und pflanzt sie in der Nähe meiner gefallenen Brüder ein. Auf diese Weise können sie neues Leben schenken... für jeden meiner Art ein würdevolles Schicksal.", progress = "Ich habe mir schon darüber Sorgen gemacht, dass der Schrein Euer Leben gefordert haben könnte. Es ist gut, dass Ihr noch immer lebt.", completion = "In der Erde können meine Brüder neues Leben spenden. Ihr habt sie vor einem weitaus schlimmeren Schicksal als dem Tod bewahrt.\n\nIch kenne in Eurer Sprache kein Wort, das ausdrückt, wie viel das meiner Art bedeutet. Ich danke Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12418] = {title = "Durch das Feuer", objective = "Betretet den Schrein durch einen der nördlichen oder südlichen Pässe, tötet dann 6 eisige Nekromanten und eliminiert den Quell der Verderbnis unter dem Schrein. Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist.", description = "Ich habe eine letzte Aufgabe für Euch, <Volk>... eine, die das Blatt in dieser Schlacht wenden sollte.\n\nKehrt zum Schrein zurück und tötet die Nekromanten, die diese Angriffe nähren. Sind sie erst einmal tot, sollten wir in der Lage sein, ihre Truppen zurückzuschlagen und letztendlich den Schrein wieder einzunehmen.\n\nIch brauche Euch auch, um den Quell der Verderbnis unter dem Schrein ausfindig zu machen und ihm ein Ende zu setzen.\n\nIch weiß, ich habe viel von Euch verlangt, aber wenn Ihr das für mich erledigt, dann können wir diese Schlacht gewinnen.", progress = "Ihr seid zurückgekehrt! Habt Ihr getan, worum ich Euch gebeten habe?", completion = "Dahlia... sie haben sie zu einer von ihnen gemacht?\n\nDahlia war uns für so lange Zeit treu... Wenn sie ein Wesen von ihrer Hingabe verderben können, ist das kein gutes Omen für den Rest der jungen Völker. Ich danke Euch, dass Ihr sie erlöst habt. Ich hoffe, sie hat ihren Frieden gefunden.\n\nIhr habt uns heute mit Eurer selbstlosen Unterstützung geehrt, &lt;Volk&gt;. Ich werde dem Rat eine Nachricht über die Taten, die Ihr hier vollbracht habt, zukommen lassen. Geht mit unserem Segen.", rewards = "Treter der kohlschwarzen SchluchtGürtel des GeißeltötersWyrmfeuerhandschuheRubinfarbener Gürtelbund des RekrutenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12419] = {title = "Das Schicksal des Rubindrachenschreins", objective = "Bringt Dahlia Sonnenhands Rubinfibel zu Krasus in der Ratskammer im Wyrmruhtempel und berichtet ihm von Dahlias Schicksal.", description = "Als Ihr die Fibel aufhebt, flammt ihr schwaches Glühen leicht auf.\n\nKrasus wird von Dahlias Schicksal erfahren wollen. Geht zum Wyrmruhtempel und bringt ihm das Schmuckstück.", progress = "Hallo, <Volk>. Ich spüre die Nähe meiner Rubinfibel. Gebt sie mir.\n\nWas ist mit Dahlia geschehen?", completion = "Die Geißel hat Dahlia ergriffen? Das ist für uns alle ein düsterer Tag.\n\nIch werde nach einem neuen Bewahrer suchen, sobald der Schrein zurückerobert wurde. Dank für Eure Mühen... der Rubindrachenschrein ist ein heiliger Ort für uns - und die Opfer, die Eure Art gebracht hat, werden nicht leichtfertig vergessen werden.\n\nGut zu wissen, dass es noch immer Helden wie Euch gibt - eines Tages werde ich wieder auf Euch zurückkommen. Mögen Eure Abenteuer bis zu jenem Tage ersprießlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12420] = {title = "Bier des Monats e.V.", objective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12421] = {title = "Bier des Monats e.V.", objective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", description = "Gemeinsam ist man stark, <Name>. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Euer Papierkram sieht in Ordnung aus. Willkommen im Verein, &lt;Name&gt;!\n\nStellt Euch schon mal darauf ein, zu Beginn jedes Monats Post von uns zu erhalten. Schaut doch mal vorbei, wenn Euch gefällt, was Ihr bekommen habt, und wir werden Euch noch mehr davon verkaufen. Dieser Verein gibt und gibt und gibt.", rewards = nil}
MultiLanguageQuestData['de'][12422] = {title = "Scheinbegnadigung", objective = "Liefert den Begnadigungsbrief bei der gefangenen Fallenstellerin in den Silberwasserhügeln ab.", description = "Hört zu, <Name>. Ich möchte, dass Ihr diskret und schnell handelt.\n\nEiner von Krennas höchsten Unteroffizieren hat außerhalb von Silberwasser eine Ausgestoßene gefangen genommen. Nun, wenn die Dinge so laufen wie immer, dann wird die Gefangene hingerichtet werden, bevor der Tag um ist.\n\nWir können das nicht zulassen. Die Gefangene entspricht der Beschreibung aus dem Tagebuch nach Mikhails ältester Tochter.\n\nWenn wir sie auf freien Fuß setzen und ihr auf den Fersen bleiben, dann wird sie uns zu demjenigen führen, der die Fallensteller beherrscht. Bringt ihr diesen Brief.", progress = "Seid Ihr hier, um mich zu töten?", completion = "Ihr werdet mich gehen lassen... einfach so? Hört her, ich möchte keine Schwierigkeiten mit Euch haben... diese Monster haben meinen Vater getötet und meine Schwester entführt. Ich habe gerade andere Sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12423] = {title = "Mikhails Tagebuch", objective = "Bringt Mikhails Tagebuch zu Eroberin Krenna in Burg Siegeswall.", description = "Soviel Ihr versteht, wurde dieses Tagebuch von einem Bewohner Silberwassers namens Mikhail geschrieben.\n\nEs wurde in einer Variante der gemeinen Menschenzunge verfasst. Vielleicht solltet Ihr dieses Buch zu Eroberin Krenna bringen.", progress = "Was habt Ihr denn da?", completion = "Hah! Soll das ein Witz sein?\n\nSelbst für Bücher, die ich verstehen kann, habe ich kaum Nutzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12424] = {title = "Gorgonna", objective = "Bringt Mikhails Tagebuch zu Gorgonna in Burg Siegeswall.", description = "Das Buch ist in der dreckigen Zunge der Menschen geschrieben. Es muss sofort verbrannt werden.\n\nGebt es meiner Schwester Gorgonna und vergeudet nicht meine Zeit.", progress = "Habt Ihr etwas, das Ihr mir zeigen wollt?", completion = "Kann das sein? Der Mann, der dieses Tagebuch geschrieben hat, fürchtete um das Leben seiner Töchter und hat sie also nach Silberwasser geschickt.\n\nWir haben soeben eine Geächtete in den Außenbezirken der Stadt aufgegriffen, die ungefähr genauso alt ist wie die älteste Tochter.\n\nHört zu, &lt;Name&gt;. Da steckt noch mehr dahinter... Wir können dieses Tagebuch nicht einfach verbrennen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12425] = {title = "Ruuna die Blinde", objective = "Sprecht mit Ruuna der Blinden in Ruunas Lager nahe dem Pass von Vordrassil.", description = "Diese Fallenstellergeschichte verspricht, weitaus wichtiger zu werden, als wir erst annahmen.\n\nWenn sie nicht der Allianz angehören, könnte es gut sein, dass sie zur Geißel gehören - was großen Ärger bedeuten würde.\n\nUnsere vorherigen Anstrengungen haben sich vielleicht dennoch bezahlt gemacht. Wir beobachteten, wie sich unser ehemaliger Gefangener mit einer Art Wahrsagerin traf, bevor wir ihre Spur verloren.\n\nIch bin mir ziemlich sicher, dass sie uns zu ihren Anführern führt, wenn wir sie nur wiederfinden. Sucht Ruuna die Blinde und seht, was Ihr herausfinden könnt.", progress = nil, completion = "Ihr sucht nach Wissen, das Ihr nicht bekommen könnt, also seid Ihr zu mir gekommen. Ich muss Euch warnen, Fremdling, meine Antworten mögen Euch vielleicht nicht gefallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12426] = {title = "DEPRECATED", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12427] = {title = "Die Siegeswallgrube: Bärenringen!", objective = "Besiegt Eisenbalg in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten.", description = "Ihr seid also an den Kämpfen interessiert, oder was? Nun, Krenna hat die Grubenkämpfe für alle registrierten Kämpfer verboten. Doch Ihr, <mein Freund/meine Liebe>, seid streng genommen Euer eigener Herr und von diesem Verbot nicht betroffen.\n\nNette Gesetzeslücke, nicht wahr?\n\nFalls Ihr jedenfalls interessiert sein solltet, dann kann ich Euch zu Anfang etwas Einfaches geben - einen popeligen Bären zum Beispiel. Ihr dürft sogar ein paar Freunde mitnehmen!", progress = nil, completion = "Gute Arbeit, Mann! Hier ist Euer Anteil.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12428] = {title = "Die Siegeswallgrube: Kampf gegen irren Furbolg", objective = "Besiegt Torgg Donnertotem in der Siegeswallgrube und sprecht Buchmacher Vel'jen auf eine Belohnung an.", description = "Ihr seid nicht schlecht. Wirklich nicht schlecht.\n\nGlaubt Ihr, Ihr könnt es mit einem Furbolg aufnehmen? Wie sieht's mit einem dieser extragroßen, verrückten Nordendfurbolgs aus?\n\nGut, gut. Stellt Euch eine Crew zusammen und ab in den Ring. Dann lasst uns den Leuten mal eine gute Show bieten... Vielleicht verdienen wir uns ja auch die eine oder andere Münze, wenn wir schon dabei sind.", progress = nil, completion = "Da habt Ihr aber einige Tricks drauf, mein Freund! Da wurde einiges gegen Euch gewettet, was, finanziell gesehen, gute Nachrichten sind!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12429] = {title = "Die Siegeswallgrube: Blut und Metall", objective = "Besiegt Rostblut in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten.", description = "Es ist schön, einen echten Kämpfer in der Gegend zu haben... Wir hatten die letzten paar Wochen nur Gefangene und eingesperrte Bestien. Den Leuten wird langweilig, müsst Ihr wissen.\n\nWie dem auch sei, Eure nächste Herausforderung ist ein echter Eisengolem, der aus den Tiefen von Thor Modan entwendet wurde... Denkt Ihr, dass Ihr das schaffen könnt?", progress = nil, completion = "Mein Herz wär' mir gerade fast stehen geblieben! Dachte, der Metallhaufen würde Euch fertig machen, Mann!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12430] = {title = "Die Siegeswallgrube: Der Tod ist wahrscheinlich", objective = "Besiegt Horgrenn Höllspalter in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten.", description = "Ich werde ganz ehrlich mit Euch sein. Der nächste Herausforderer ist ein Mörder.\n\nIm wahrsten Sinne des Wortes.\n\nEr hätte eigentlich letzte Woche hingerichtet werden sollen, doch er hat den Henker mit seiner linken Hand erwürgt, also haben Krennas Wächter ihn mir einfach gegeben.\n\nIhr müsst nicht gegen ihn kämpfen, wenn Ihr nicht wollt. Ich würde es Euch nicht verübeln.", progress = nil, completion = "Geschickt, geschickt. Ihr habt mit dem Orc wirklich kurzen Prozess gemacht, &lt;Klasse&gt;.\n\nDie Wetten standen Sieben zu Eins gegen Euch - habt bei der Sache ordentlich was verdient!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12431] = {title = "Die Siegeswallgrube: Entscheidungskampf", objective = "Besiegt Krenna in der Siegeswallgrube.", description = "Ihr müsst Krenna wirklich an die Nieren gegangen sein. Sie und Gorgonna hatten Krach - Euereins wird umgehend in der Grube verlangt.\n\nEs kursieren ein paar wilde Gerüchte, dass es ein Kampf bis auf den Tod sein soll! Das wären zwar schlechte Neuigkeiten für Euch, doch für uns und unser Geschäft sind es großartige!\n\nAuf jeden Fall könnt Ihr Eurem Schicksal nicht entrinnen... am besten geht Ihr schleunigst dorthin und bringt es hinter Euch.", progress = nil, completion = "Was heute passiert ist... musste passieren. Das bedeutet jedoch nicht, dass ich mich auch darüber freuen muss.\n\nIch habe mein Volk von einer Tyrannin befreit, jedoch auch eine Schwester verloren. Ich danke Euch für Eure Hilfe, &lt;Name&gt;. Lasst mich jetzt alleine.", rewards = "Aufgeladener ErdverbindungshandschutzHandschützer des BlutgladiatorsHandschutz der reißenden KraftHandschützer der verlockenden MachtStulpen mit leuchtenden SchnallenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12432] = {title = "Ritt auf der roten Rakete", objective = "General Gorlok im Leuchtturm in der Venturebucht möchte, dass Ihr den Holzfrachter der Allianz zerstört.\n\nGeneral Gorlok befindet sich nur dann im Leuchtturm, wenn sich dieser in Besitz der Horde befindet.", description = "Ihr da, <Volk>! Schwingt Euren lausigen Hintern hier rüber!\n\nDie Allianz hat gleich nordöstlich von hier eine transportbereite Ladung Holz. Da wir sie mit Sicherheit nicht in unsere Finger bekommen können, gibt es nur eins zu tun: sie zu zerstören!\n\nDer Goblin am Ende des Docks hier hat ein paar einsatzbereite Torpedos auf Lager. Den Treibstoff dafür gibt es auf dem Goblinschiff, das im Hafen liegt.\n\nBesorgt Euch etwas Treibstoff, setzt Euch auf einen der Torpedos und steuert ihn in ihr Schiff hinein.\n\nWegtreten!", progress = nil, completion = "Ha, ha! Was für ein Ritt - nicht wahr, &lt;Klasse&gt;?\n\nWenn wir die hiesigen Ressourcen nicht kontrollieren können, dann kann das niemand!\n\nWann werden diese mickrigen Quälgeister von der Allianz endlich erkennen, dass sie der mächtigen Horde nicht gewachsen sind?", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12433] = {title = "Auf der Suche nach Lösungsmittel", objective = "Gurtor in der Hordenbasis in der Venturebucht möchte, dass Ihr ihm einen Kanister Element 115 bringt.", description = "Gah! Nicht schon wieder. Noch eine geplatzte Dichtung...\n\nJedes Mal, wenn das passiert, verklebt sich das ganze Getriebe mit diesem Schmierstoff. Ohne Lösungsmittel dauert das Saubermachen dann Stunden.\n\nIch sag' Euch was, <Volk>. Auf dem Lastkahn der Venture Company im Hafen gibt es guten Raketentreibstoff. Denke, dass sie ihn Element 115 nennen. Das Zeug wäre ein großartiges Lösungsmittel.\n\nBesorgt mir ein wenig davon und ich werde dafür sorgen, dass es sich für Euch lohnen wird.", progress = "Habt Ihr ein wenig Element 115 mitgebracht, <Name>?", completion = "Ahh, ja. Das wird mir einige Stunden Arbeit sparen.\n\nNehmt dies für Eure Mühen, mein Freund. Haltet nach mehr Element 115 Ausschau - ich so viel gebrauchen, wie Ihr finden könnt.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12434] = {title = "Immer auf der Suche nach Lösungsmittel", objective = "Habt Ihr noch mehr von diesem Element 115 für mich, <Name>?", description = nil, progress = "Habt Ihr noch mehr von diesem Element 115 für mich, <Name>?", completion = "Gute Arbeit, &lt;Klasse&gt;!\n\nBringt, so viel Ihr könnt.", rewards = "Ihr bekommt:\n\nEhrepunkteMünze der Venture Co."}
MultiLanguageQuestData['de'][12435] = {title = "Erstattet Lord Devrestrasz Bericht", objective = "Sprecht mit Lord Devrestrasz im Wyrmruhtempel.", description = "Ich verabscheue den Verlust von Leben... egal welches es auch sein mag. Doch ich werde nicht untätig dabei zusehen, wie Malygos uns auslöschen und den Tempel schänden wird!\n\nIch habe Lord Devrestrasz zum Kommandanten der Verteidigung des Wyrmruhtempels ernannt.\n\nSprecht mit Torastrasza, damit sie Euch einen Drachen zur Verfügung stellt, mit dem Ihr zu ihm fliegen könnt.\n\nIch bitte Euch, <Name>, leistet ihm Hilfe. Eure Beteiligung an der Verteidigung des Wyrmruhtempels wird für unseren Sieg über den blauen Drachenschwarm von entscheidender Bedeutung sein.", progress = nil, completion = "Ihr müsst &lt;Name&gt; sein. Die Königin hat mir gesagt, dass Ihr kommen würdet.\n\nFalls Ihr uns beistehen wollt, dann wisset, dass Eure Hilfe dringend gebraucht wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12436] = {title = "Zusatzeinkommen", objective = "Versorger Lorkran in Burg Siegeswall will, dass Ihr 5 saftige Wildbrete von Großhornhirschen in der Nähe besorgt.", description = "Grüße, <Klasse>. Ihr werdet sehen, dass wir hier in der Burg Siegeswall das kaufen und verkaufen, was Krenna ge- und verkauft sehen will… zu dem Preis, zu dem Krenna uns kaufen und verkaufen sehen will.\n\nDas ist alles recht einengend. Ich hoffe, noch einige Münzen nebenher verdienen und gleichzeitig unsere Grunzer versorgen zu können. Warum geht Ihr nicht und jagt einige Hirsche, und bringt mir dann das Wildbret?\n\nSie sind sehr zahlreich in dieser Gegend, also bringt mir nur das beste Fleisch.", progress = "Habt Ihr das Wildbret schon, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Die werden zwei oder drei Grunzer satt machen. Nicht schlecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12437] = {title = "Ritt auf der roten Rakete", objective = "Kommandant Hauser im Leuchtturm in der Venturebucht möchte, dass Ihr den Holzfrachter der Horde zerstört.\n\nKommandant Hauser befindet sich nur dann im Leuchtturm, wenn sich dieser im Besitz der Allianz befindet.", description = "Hört mir zu, <Name>. In dieser Schlacht sind Ressourcen genauso wichtig, wie taktische Überlegenheit.\n\nIch habe eine Mission für Euch, die das Blatt im Kampf gegen die Horde zu unseren Gunsten wenden könnte.\n\nAm Ende des Docks befinden sich Torpedos, mit deren Hilfe wir den Holzfrachter der Horde im Nordwesten versenken können.\n\nIhr werdet ein wenig von dem Treibstoff benötigen, der auf dem Schiff der Goblins im Hafen gelagert wird, Euch auf einen der Torpedos setzen und ihn dann in ihren Frachter steuern!", progress = nil, completion = "Gut zu sehen, dass Ihr den Einschlag überlebt habt. Was für eine Explosion!\n\nWir können es uns einfach nicht leisten, dass die Horde sich mit all dem Holz davonmacht.\n\nGut gemacht, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12438] = {title = "GESUCHT: Kreug Eidbrecher", objective = "Tötet Kreug Eidbrecher und kehrt zu Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde zurück, um dort Eure Belohnung abzuholen.", description = "Von: Illusia Lune\n\nDer Fleischriese der Geißel bekannt als Kreug Eidbrecher ist für den Tod meines Mannes, meiner Kinder und meiner geschätzten Freunde der Familie Wisperschleier verantwortlich. An die Mutigen unter Euch, die Jagd auf ihn machen und sich das Kopfgeld verdienen wollen: Kreug hält sich im südöstlichen Abschnitt der Aasfelder auf.\n\nIch verlange Gerechtigkeit! Tötet Kreug Eidbrecher!\n\nIch habe für den Fall, dass Kreug erschlagen wird, ein wenig Gold und ein paar Gegenstände gesammelt und sie Hochlord Leoric von Zeldig gegeben - als Belohnung für den erfolgreichen Jäger.\n\nBitte rächt uns!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich werde Illusia benachrichtigen, dass ein Held ihrem Hilferuf gefolgt ist und sich der Herausforderung gestellt hat! Hier ist Eure Belohnung.", rewards = "Armschienen des EiswüstenhauchsArmschienen des LichtungswanderersVersteinerter KnochenbrustschutzAuf Euch wartet eine dieser Belohnungen:\n\nHalsband des Geißelghuls\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12439] = {title = "Erschütterung im Westen", objective = "Sprecht mit Rodney Wells in der Feste Wintergarde zwecks eines Ritts nach Sternenruh im Westen der Drachöde.", description = "Und wieder droht eine dunkle Macht alles, was wir aufgebaut haben, zu zerstören, <Name>. Ihr müsst gen Westen nach Sternenruh gehen. Erzmagierin Modera hat eine große Erschütterung der magischen Leylinien unserer Welt gespürt, um die wir uns auf der Stelle kümmern müssen!\n\nGeht jetzt, <Name>! Sprecht mit Rodney Wells an der Greifenstation hier in Wintergarde und erzählt ihm von Eurer Mission. Er wird Euch seinen schnellsten Greifen geben, um Euch nach Sternenruh zu bringen. Sprecht mit Erzmagierin Modera, sobald Ihr ankommt.", progress = nil, completion = "Wir wollen sicher keine weitere Teilung, mein Freund. Ich tue alles, was ich kann, um Euch bei Eurer Mission zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12440] = {title = "Nach Sternenruh!", objective = "Sprecht mit dem Abbild der Erzmagierin Modera in Sternenruh im Westen der Drachenöde.", description = "Wenn Ihr bereit seid, schicke ich Euch auf dem Rücken meines schnellsten Greifen nach Sternenruh. Findet und sprecht mit Erzmagierin Modera, sobald Ihr dort ankommt.\n\nViel Glück, Allianzler!", progress = nil, completion = "Vas hat meinen Hilferuf also erhört, ja? Und keine Sekunde zu früh.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12441] = {title = "GESUCHT: Hochschamane Blutpfote", objective = "Tötet Hochschamane Blutpfote und kehrt anschließend zu Hochlord Leoric von Zeldig in Wintergarde in der Drachenöde zurück, um Eure Belohnung abzuholen.", description = "Von: Drolfy\n\nWährend ich mit meinen Vettern Skrot und Brod draußen auf den Düsterhöhen war, wurden wir von einer Bande heimtückischer Wolvar des Blutpfotenstammes angegriffen. Wir wollten fliehen, doch ich fürchte, dass sie Skrot und Brod erwischt haben.\n\nIch will Rache! Gibt es dort draußen jemanden, der mutig genug ist, um sich auf die Düsterhöhen im Südosten der Drachenöde zu wagen und dort Hochschamane Blutpfote mitsamt seinen Spießgesellen zu töten?\n\nIch habe Hochlord Leoric von Zeldig eine große Summe Gold gegeben, damit er sie an jeden vergeben kann, dem das Kopfgeld zusteht!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;! Ich werde Drolfy benachrichtigen, dass sich ein Held der Herausforderung gestellt hat und dass Blutpfotes Tage gezählt sind!", rewards = "RubinholzstabStab der MondruhgärtenScharfe Klinge des WaldlandsStachelkeule von KaltwindKampferprobter MagnataurenzermalmerArmbrust des gestählten WaldläufersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12442] = {title = "GESUCHT: Ansturmkommandant Iustus", objective = "Tötet den Ansturmkommandanten Iustus und kehrt anschließend zu Hochlord Leoric von Zeldig in Wintergarde in der Drachenöde zurück, um Eure Belohnung abzuholen.", description = "Von: Hochlord Leoric von Zeldig\n\nAuf dem nordöstlichen Pfad nach Wintergarde wurde ein Bataillon der 7. Legion vom Ansturmkommandanten Iustus und einer Armee hirnloser Zeloten überfallen und getötet. Solchen kalten und berechnenden Taten darf man nur mit Gewalt begegnen!\n\nWintergarde verlangt Gerechtigkeit! Sucht und findet den Ansturmkommandanten Iustus im Basislager des Ansturms gen Nordosten und macht seiner erbärmlichen Existenz ein Ende.\n\nIch werde das Kopfgeld an jeden ausbezahlen, der Mut genug beweist, um sich der Aufgabe zu stellen!", progress = nil, completion = "Zumindest musste der Scharlachrote Ansturm dadurch einen Rückschlag erleiden, was sie in ihren ruchlosen Plänen eine Zeitlang zurückwerfen wird. Ihr habt Wintergarde einen großen Dienst erwiesen, &lt;Name&gt;.", rewards = "Handgelenksschützer des QuälersSabatons des VollstreckersBeinpolster des InquisitorsRobe des GerechtenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12443] = {title = "Auf der Suche nach Lösungsmittel", objective = "Barbelfink in der Allianzbasis in der Venturebucht möchte, dass Ihr ihm einen Kanister Element 115 bringt.", description = "Gah! Nicht schon wieder. Noch eine geplatzte Dichtung...\n\nJedes Mal, wenn das passiert, verklebt sich das ganze Getriebe mit diesem Schmierstoff. Ohne Lösungsmittel dauert das Saubermachen dann Stunden.\n\nIch sag' Euch was, <Volk>. Auf dem Lastkahn der Venture Company im Hafen gibt es guten Raketentreibstoff. Denke, dass sie ihn Element 115 nennen. Das Zeug wäre ein großartiges Lösungsmittel.\n\nBesorgt mir ein wenig davon und ich werde dafür sorgen, dass es sich für Euch lohnen wird.", progress = "Habt Ihr ein wenig Element 115 mitgebracht, <Name>?", completion = "Ahh, ja. Das wird mir einige Stunden Arbeit sparen.\n\nNehmt dies für Eure Mühen, mein Freund. Haltet nach mehr Element 115 Ausschau - ich so viel gebrauchen, wie Ihr finden könnt.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12444] = {title = "Gemetzel am Schwarzwasser", objective = "Späherhauptmann Carter möchte, dass Ihr 10 Einheiten oder Spieler der Horde im Holzfällerlager Schwarzwasser tötet.", description = "Die Venture Company verlässt soeben die Grizzlyhügel. Früher holzten sie hier Bäume ab, aber die Lage ist inzwischen etwas zu gefährlich für sie geworden.\n\nIhre verlassenen Stätten sind nun frei plünderbar und wir müssen verdammt noch mal zusehen, dass die Horde die Finger davon lässt.\n\nDas Holzfällerlager Schwarzwasser ist das kleinste der drei Abholzungsstätten in diesem Gebiet, aber wir brauchen es trotzdem. Eure Rolle ist es, die Streitkräfte der Horde abzuwehren. Alles dort ergatterte Holz werden sie zu Waffen machen, die sie später anderenorts gegen uns einsetzen.", progress = "Wie läuft die Jagd?", completion = "Gute Arbeit, &lt;Name&gt;. Wir könnten hier mehr von Eurer Sorte gebrauchen, dann würden wir der Horde schon austreiben, sich mit uns anzulegen.", rewards = "Ihr bekommt:\n\nEhrepunkte"}
MultiLanguageQuestData['de'][12446] = {title = "Immer auf der Suche nach Lösungsmittel", objective = "Habt Ihr noch etwas Element 115 für mich, <Name>?", description = nil, progress = "Habt Ihr noch etwas Element 115 für mich, <Name>?", completion = "Gute Arbeit, mein Freund!\n\nImmer schön her damit.", rewards = "Ihr bekommt:\n\nEhrepunkteMünze der Venture Co."}
MultiLanguageQuestData['de'][12447] = {title = "Der Obsidiandrachenschrein", objective = "Reist zum Obsidiandrachenschrein nordwestlich des Wyrmruhtempels und gleich westlich der Pforte des Zorns. Sucht im Inneren des Schreins nach Serinar und bietet ihm Eure Hilfe an.", description = "Die Geißel ist im Anmarsch. Korialstrasz ruft in dem zwecklosen Versuch, ihren Rubindrachenschrein zu retten seine Verbündeten zusammen. Doch scheint es, als würden die Gebete zur Rettung des roten Schwarms die Schreine der anderen Schwärme nicht mit einschließen.\n\nÜberrascht? Ich bin es nicht.\n\nEiner meiner Schwarmbrüder ist zum Obsidiandrachenschrein aufgebrochen. Er wird ihn von dem untoten Ungeziefer reinigen, der ihn befallen hat. Alles was Ihr tun müsst, um zu beweisen, dass Ihr nobler und rechtschaffener seid, als die hehre Alexstrasza selbst, ist lediglich kurz dort vorbeizuschlendern und ein paar Mal Eure Waffe zu schwingen.\n\nAmüsant, nicht?", progress = nil, completion = "Ich bin mir nicht sicher, was mich mehr überrascht: dass Ihr einem schwarzen Drachen zu Hilfe kommt oder dass Ihr nach einem Gespräch mit Yntrige noch immer in einem Stück seid.\n\nIhre Worte sind Gift, aber ich schätze, dass der Wyrmruhtempel manchmal selbst einen von uns in Schach halten kann.\n\nOder vielleicht sind es nur die Armeen des roten Drachenschwarms, die sich hier in Massen versammelt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12448] = {title = "Im Eifer des Gefechts", objective = "Unterstützt Hauptmann Drayzen, die Canyons zu halten. Tötet 12 eisige Ghulangreifer, 8 eisige Spukangreifer und 1 eisigen Monstrositätenangreifer.\n\nKehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist.", description = "Die Geißel hat den Schrein gestürmt. Die Bewahrerin des Schreins, Dahlia Sonnenhand, ist nicht aufzufinden. Die roten Wyrms, die bei der Verteidigung des Schreins fielen und nun die Gestalt pervertierter Skelettglutwyrms angenommen haben, suchen uns nun heim. Die Situation ist ernst, <Volk>.\n\nHauptmann Drayzen führt eine Gruppe von Leuten wie Euch an und versucht, den Zufluss der Geißel aus dem Schrein zu stoppen.\n\nUnterstützt ihn... aber bleibt bitte hinter seinen Männern. Der Strom der Geißel ist endlos und ich möchte Euch nicht in einer dieser zerklüfteten Schluchten verlieren.", progress = "Ich bin froh, dass Ihr noch unter den Lebenden seid, <Volk>.", completion = "Es ist eine widerwärtige Aufgabe und ich danke euch, dass Ihr sie dennoch abgeschlossen habt\n\nDer Geißel darf nicht erlaubt werden, noch weiter aus dem Schrein auszubrechen, sonst wird das ganze Land hier von ihnen überrannt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12449] = {title = "Zur Erde zurückkehren", objective = "Betretet den Schrein durch den südlichen Pass und sucht nach Rubineicheln. Benutzt die Rubineicheln nahe den gefallenen roten Drachen, um ihre Körper zur Erde zurückkehren zu lassen. Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist.", description = "Ich habe noch eine Aufgabe, die Aufmerksamkeit erfordert. Schwarmbrüder sterben im Kampf dort oben und wenn wir nicht schnell handeln, werden sie nur die Ränge der Magmawyrms verstärken.\n\nBetretet den Schrein durch den südlichen Pass... die Geißel dürfte dort nicht so stark vertreten sein.\n\nVom Baum im Schrein fallen Rubineicheln, sucht nach ihnen und pflanzt sie nahe den Leichen meiner gefallenen Brüder ein. So können sie neues Leben schenken... für jeden meiner Art ein würdevolles Schicksal.", progress = "Ich hatte mir bereits Sorgen gemacht, dass Euch die Geißel im Schrein überwältigt hatte. Es ist gut, dass Ihr noch lebt.", completion = "In der Erde können meine Brüder neues Leben schenken. Ihr habt sie vor einem weitaus schlimmeren Schicksal als dem Tod bewahrt.\n\nIch kenne in Eurer Sprache kein Wort, das ausdrückt, wie viel das meiner Art bedeutet. Ich danke Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12450] = {title = "Durch das Feuer", objective = "Betretet den Schrein durch den südlichen Pass, tötet dann 6 eisige Nekromanten und eliminiert den Quell der Verderbnis unter dem Schrein. Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist.", description = "Ich habe eine letzte Aufgabe für Euch, <Volk>... eine, die das Blatt in dieser Schlacht wenden sollte.\n\nKehrt zum Schrein zurück und tötet die Nekromanten, die diese Angriffe nähren. Sind sie erst einmal tot, sollten wir in der Lage sein, ihre Truppen zurückzuschlagen und letztendlich den Schrein wieder einzunehmen.\n\nIch brauche Euch auch, um den Quell der Verderbnis unter dem Schrein ausfindig zu machen und ihm ein Ende zu setzen.\n\nIch weiß, ich habe viel von Euch verlangt, aber wenn Ihr das für mich erledigt, dann können wir diese Schlacht gewinnen.", progress = "Ihr seid zurück! Habt Ihr getan, worum ich Euch bat?", completion = "Dahlia... sie haben sie zu einer von ihnen gemacht?\n\nDahlia war uns für so lange Zeit treu... Wenn sie ein Wesen von ihrer Hingabe verderben können, ist das kein gutes Omen für den Rest der jungen Völker. Ich danke Euch, dass Ihr sie erlöst habt. Ich hoffe, sie hat ihren Frieden gefunden.\n\nIhr habt uns heute mit Eurer selbstlosen Unterstützung geehrt, &lt;Volk&gt;. Vielleicht tragen nicht alle Mitglieder der Horde das schwarze Herz ihrer Ahnen in sich. Ich werde dem Rat eine Nachricht über die Taten, die Ihr hier vollbracht habt, zukommen lassen.", rewards = "Treter der kohlschwarzen SchluchtGürtel des GeißeltötersWyrmfeuerhandschuheRubinfarbener Gürtelbund des RekrutenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12451] = {title = "Weiter nach Camp Oneqwah", objective = "Sprecht mit Späher Vor'takh im Camp Oneqwah.", description = "Als wir mit der Konstruktion von Burg Siegeswall beschäftigt waren, entsandte ich Späher Vor'takh, um mit unseren verbündeten Taunka im Osten Kontakt aufzunehmen. Sie sind in Camp Oneqwah zu finden, das sich im östlichsten Teil der Grizzlyhügel jenseits von Grauschlund befindet.\n\nMacht Euch auf den Weg dorthin, hört Euch an, was Vor'takh zu berichten hat, und bietet ihm Eure Unterstützung in allen Angelegenheiten an, die er und der dortige Häuptling erledigt haben wollen. Ihr habt Beachtliches für Burg Siegeswall geleistet und ich weiß, dass Vor'takh für Eure Hilfe dankbar sein wird.", progress = nil, completion = "&lt;Ihr stellt Euch kurz vor und erklärt, dass Ihr von Unteroffizier Nazgrim geschickt wurdet.&gt;\n\nAh, Ihr seid also so was wie Verstärkung. Gut.\n\nTormak und seine Männer können Eure Klinge gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12452] = {title = "zzOLD The Fate of the Ruby Dragonshrine", objective = "Bringt Dahlias Rubinfibel zu Ceristrasz und erzählt ihm von ihrem Schicksal.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12453] = {title = "Der Himmel hat Augen", objective = "Windseherin Grauhorn möchte, dass Ihr die silberne Feder auf 6 Kaiseradler in den Grizzlyhügeln anwendet.", description = "Ich wurde gebeten, unser Vorgehen gegen die Allianz zu unterstützen. Im Moment sind unsere Militärstreitkräfte ungefähr gleich stark und wir versuchen, einen Vorteil gegenüber den anderen zu erhaschen.\n\nDie Kaiseradler, die über den Bergen und Bäumen dieser Gegend ihre Bahnen ziehen, wären ausgezeichnete Späher. Nehmt diese silberne Feder und lasst mich mit ihrer Hilfe durch die Augen der Adler sehen.\n\nDie Bewegungen unseres Feindes zu sehen, wird uns den benötigten strategischen Vorteil gewähren. In den Bergen gen Osten findet Ihr reichlich Adler.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Eure Hilfe ist willkommen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsigne des blutigen FeuersGlücksbringer des BettelmönchsKlaue des Hasses\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12454] = {title = "Kreislauf des Lebens", objective = "Nishera die Gartenbewahrerin im Smaragddrachenschrein möchte, dass Ihr 5 Smaragdhimmelsklauen niederstreckt.", description = "Ysera schläft im Smaragdgrünen Traum und dort hält sie Wache - über ihn selbst und Azeroth. Doch aus dem Traum ist ein Alptraum geworden und nun befürchte ich, dass Ysera davon betroffen ist.\n\nVor Kurzem habe ich sie darum gebeten, uns im Kampf gegen die Geißeleinheiten zu unterstützen, die bei den anderen Schreinen Frostwyrms wieder auferstehen lassen. Doch sie verstand mich falsch.\n\nStattdessen befahl sie unseren Drachenschreinverteidigern, all diejenigen als Feinde zu betrachten, die nicht dem Grünen Drachenschwarm angehören.\n\nIch möchte, dass Ihr ein paar Himmelsklauen niederstreckt. Der Schrein muss wieder ins Gleichgewicht gebracht werden.", progress = nil, completion = "Es gibt keinen Grund, Eure Rolle im Kreislauf des Lebens zu bedauern. Geburt, Tod und Wiedergeburt - all diese Dinge sind Teil der natürlichen Ordnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12455] = {title = "In alle Winde verstreut", objective = "Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr 8 Munitionskisten von Wintergarde beschafft.", description = "Der Munitionsabwurf ist schlecht gelaufen, <mein Freund/meine Freundin>. Die Munitionslieferung aus Westwacht wurde von den Frostwyrms abgefangen, die über uns kreisen. Die Flugmaschinen wurden innerhalb von Sekunden auseinandergerissen und ihre Ladung in alle Winde verstreut. Der Großteil liegt noch immer auf den Aasfeldern herum.\n\nIch möchte, dass Ihr wieder dorthin geht und die Munitionskisten bergt, die überall in dieser verdammten Gegend verstreut liegen.\n\nBeeilt Euch! Ohne Gewehre und Munition wird diese Offensive nicht ins Rollen kommen, <Kumpel/Süße>!", progress = "Wo ist meine Munition, Jungchen?", completion = "Gerade rechtzeitig! Einige meiner Soldaten waren ein wenig übereifrig und beschlossen, die Krypten direkt im Osten und Westen aufzusuchen. Natürlich wurden sie sehr schnell von diesen hirnlosen Ghulen überwältigt... Wir müssen die Überlebenden retten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12456] = {title = "Der Federschmuck von Alystros", objective = "Nishera die Gartenbewahrerin im Smaragddrachenschrein möchte, dass Ihr den Federschmuck von Alystros beschafft.", description = "Ich kann fühlen, dass sich der Schrein noch nicht wieder im vollständigen Gleichgewicht befindet. Unser Handeln hat den tiefgrünen Bewahrer verärgert und ich spüre, dass er nicht mit sich reden lassen wird.\n\nAlystros, die riesige Himmelsklaue, sitzt am südlichen Ende des Smaragddrachenschreins. Er ist es, der für die Luftverteidigung des Drachenschreins verantwortlich ist. Ich befürchte, dass wir uns um ihn kümmern müssen.\n\nHier, nehmt diese gemauserten Himmelsklauenfedern und legt sie genau dort auf den Boden, wo er sie sehen kann. Er wird kommen. Bringt mir seinen Federschmuck.", progress = "Habt Ihr Euch um Alystros gekümmert? Habt keine Angst davor, Eure Freunde um Unterstützung zu bitten.\n\nGenau genommen würde ich es Euch angesichts der immensen Stärke des tiefgrünen Bewahrers sogar raten!", completion = "Weint nicht um Alystros. Er hat sein ewiges Leben der Verteidigung des Smaragddrachenschreins gewidmet und wird wiedergeboren werden.\n\nWenn er wieder zu uns zurückkehrt, wird er hoffentlich nicht von der Unruhe des smaragdgrünen Alptraums ergriffen, von der anscheinend die Träumerin heimgesucht wird.", rewards = "Alystros' FedergurtUralte Gamaschen des TräumersTiefgrüne gekettelte StiefelGürtel des SmaragdwächtersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12457] = {title = "Die Maschinenkanone und du", objective = "Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr 8 verletzte Soldaten der 7. Legion rettet.", description = "Wir haben gleich im Osten und Westen Kettenkanonen und Barrikaden aufgestellt. Unsere verletzten Soldaten verstecken sich in beiden Seiten und versuchen ihr Bestes, um die hirnlosen Ghule nicht auf sich aufmerksam zu machen.\n\nDa wir nun Munition haben, möchte ich, dass Ihr Euch an eine der Maschinenkanonen setzt und einen Durchgang für unsere Soldaten freischießt! Ruft einen Soldaten aus seinem Versteck, sobald Ihr bereit seid, und haltet ihm die Geißel mit schwerem Feuer vom Leib!\n\nLos, Bewegung!", progress = "Hast du unsere verletzten Soldaten gerettet?", completion = "&lt;Name&gt;, seit Silithus habe ich nicht mehr solche Heldentaten gesehen!\n\nIch bin mir sicher, dass jeder einzelne dieser Soldaten zu Lord Fordragon gehen und dich für eine Beförderung vorschlagen wird!\n\nNun aber zu dringlicheren Angelegenheiten. Wir haben Rückmeldung von unseren Spähern erhalten, dass Thel'zan in der Nähe ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12458] = {title = "Samen der Peitscher", objective = "Lord Itharius in der Spitze des Wyrmruhtempels möchte, dass Ihr 3 Peitschersamen zu ihm zurückbringt.", description = "Wir brauchen mehr Waffen für den Kampf gegen die Geißel. Die natürlichen Kräfte des Smaragddrachenschreins gen Südosten könnten vielleicht die Antwort sein.\n\nJede untote Kreatur, die auch nur einen Fuß in den Drachenschrein setzen sollte, zerfällt zu Staub. Außer diejenigen, die von Sylvanas erlöst wurden.\n\nIch möchte eine Theorie austesten und ich möchte, dass Ihr <derjenige seid, der/diejenige seid> die; das in die Hand nehmen soll, <junger/junge:r> <Volk>. Geht zum Smaragddrachenschrein und holt Euch die Samen von den dort heimischen Smaragdpeitschern.", progress = "Wie viele Samen hättet Ihr wohl bis jetzt sammeln können, hm?", completion = "Selbst jetzt kann ich den Puls der Natur in diesen Samen spüren.\n\nWir müssen sie gut verwenden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12459] = {title = "Das Schaffende kann auch zerstören", objective = "Lord Itharius in der Spitze des Wyrmruhtempels möchte, dass Ihr einen geschwächten wiedererweckten Frostwyrm, den geschwächten Turgid den Grässlichen und den geschwächten Aufseher Todesblick vernichtet.", description = "Da uns nur drei Samen zur Verfügung stehen, müssen wir den bestmöglichen Nutzen für sie finden.\n\nEure Ziele sind die wiederbelebten Frostwyrms, die im Norden in der Nähe von Galakronds Ruhestätte ihre Bahnen ziehen, Turgid der Grässliche in der zerstörten Kaserne auf den Aasfeldern gen Osten und Aufseher Todesblick in Jintha'kalar weit im Nordosten.\n\nEin niedriger Diener der Geißel würde von den Samen sofort vernichtet werden – eines Eurer Ziele lediglich geschwächt; jedoch genug, damit Ihr aus eigener Kraft mit ihnen fertigwerden könnt.", progress = nil, completion = "Ausgezeichnet. Genau wie ich es schon die ganze Zeit vermutet habe. Ich werde versuchen müssen, mit Ysera Verbindung aufzunehmen, um herauszufinden, ob sie dies gutheißt oder nicht.\n\nWenn wir sie aus ihrem Alptraum entreißen können, versteht sich.\n\nHabt Dank, &lt;Name&gt;. Eure Hilfe war unerlässlich.", rewards = "Mantel von IthariusHandschuhe des SmaragdjägersHaube des tiefgrünen JägersBrustplatte des Zorns der NaturIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12460] = {title = "Beim Rubindrachenschrein Bericht erstatten", objective = "Meldet Euch bei Ceristrasz, der sich auf dem Grat östlich des Rubindrachenschreins befindet. Der Schrein liegt westlich des Wyrmruhtempels.", description = "Wir brauchen Eure Hilfe am Rubindrachenschrein.\n\nDie Drachen sind vom blauen Drachenschwarm und der Geißel umzingelt und werden von allen Seiten bedrängt... ihnen geht es nicht besser als uns. Die Situation ist zwar ernst, doch sie bietet uns die seltene Gelegenheit, eine wertvolle Allianz aufzubauen.\n\nIch habe ein Regiment angefordert, um den roten Drachenschrein gegen die Geißel zu unterstützen. Wenn Ihr etwas Kampfeswillen in Euch habt, dann geht bitte zu Ceristrasz und helft ihm, so gut Ihr nur könnt. Ihr findet ihn auf dem Grat östlich des Schreins.", progress = nil, completion = "Botschafter Lauriel hat Euch geschickt?\n\nFalls Ihr wieder mit ihr sprechen solltet, dann lasst sie bitte wissen, dass wir ihre Unterstützung sehr schätzen. Wir kämpfen an zu vielen Fronten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12461] = {title = "Beim Rubindrachenschrein Bericht erstatten", objective = "Meldet Euch bei Vargastrasz, der sich gleich östlich von Agmars Hammer auf einer Anhöhe in der Nähe des Rubindrachenschreins befindet.", description = "Ihr geht zum Rubindrachenschrein. Das ist keine Bitte.\n\nDie Drachen werden von allen Seiten vom blauen Schwarm und der Geißel belagert... es geht ihnen nicht besser, als uns hier. Wir haben nicht oft die Gelegenheit, den Frevel unserer Vorfahren wiedergutzumachen.\n\nIch habe ein Regiment zusammengestellt, das den roten Drachenschwarm am Rubindrachenschrein im Kampf gegen die Geißel unterstützen wird. Schließt Euch ihm an und zerquetscht die Geißel unter Euren Stiefeln!\n\nFür die Horde!", progress = nil, completion = "Botschafter Golluck hat Euch geschickt?\n\nWenn Ihr wieder mit ihm sprecht, lasst ihn bitte wissen, dass wir sehr dankbar für seine Unterstützung sind. Wir kämpfen hier eindeutig an zu vielen Fronten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12462] = {title = "Schon Spaß gehabt?", objective = "Yord \"Katastrophe\" Eisbart im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr Nekrolord X'avius, Nekrolord Horus und 15 Diener von Naxxramas tötet.", description = "Am Ende der Treppe liegt das Tor zur Welt der Verdammnis: Diener der Geißel, wohin das Auge nur blickt, und mit jeder Sekunde werden es mehr. Laut den wenigen Informationen, die wir über den Ort sammeln konnten, sind zwei Nekrolords wie wild damit beschäftigt, alle Toten in den ersten beiden Krypten unter uns in Diener der Geißel zu verwandeln. Doch bevor wir die innere Kammer durchbrechen und zu Thel'zan gelangen können, werden wir uns um die beiden Witzbolde und ihre Spießgesellen aus Naxxramas kümmern müssen.\n\nSteigt hinab ins Mausoleum; dort werdet ihr Nekrolords, Schreckenswachen und Schemen vorfinden. Schaltet sie aus.", progress = nil, completion = "Das wird Ambo ein wenig Zeit verschaffen, um die Dinge wieder in den Griff zu bekommen.", rewards = "Schulterstücke des EiswindsSchulterstücke des SchneewehenhäschersSchulterschützer aus Anub'architinSchulterstücke des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12463] = {title = "Ramschbart muss gefunden werden!", objective = "Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr Ramschbart findet.", description = "Es kursiert das Gerücht, dass Thel'zan und seine Diener einen Tunnel freigelegt haben sollen, den einst die Geißel gegraben haben soll und der die Balsamierungskammern des Mausoleums mit den großen Krypten verbindet. Vor Kurzem erst schickte ich meinen besten Schurken Ramschbart aus, um nach Antworten zu suchen. Ich warte noch immer auf eine Antwort von ihm. Müsste ich wetten, würde ich sagen, dass er's nicht geschafft hat.\n\nIch möchte also, dass Ihr diese Stufen hinabsteigt, zur Balsamierungskammer vordringt und dort nach Ramschbart sucht. Tot oder lebendig, er wird Antworten haben.", progress = nil, completion = "&lt;Ihr findet bei Ramschbarts Leiche ein Tagebuch.&gt;\n\nErster Eintrag:\n\nSie schleifen Leichen durch den Tunnel und bringen sie in den Balsamierungsraum, um dort mit ihnen herumzuexperimentieren. In diesem Mausoleum gibt es einen unerschöpflichen Vorrat an Leichen. Was nicht wiederbelebt werden kann, wird in irgendein Knochenkonstrukt verwandelt.\n\nZweiter Eintrag:\n\nIch befürchte, dass dieser Lich Thel'zan ein dunkles Geheimnis verbirgt. Wer ist dieser Kerl? War er einst... einer von uns?\n\nDritter Eintrag: Ich habe herausgefunden, wo sich das Phylakterium des Lichs befindet. Es ist...\n\n&lt;Die restlichen Seiten wurden herausgerissen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12464] = {title = "Mein alter Feind", objective = "Liefert den Kopf des Hochgenerals bei Kommandant Eligor Morgenbringer in der Feste Wintergarde ab.", description = "Mein alter Feind Hochgeneral Abbendis hat es nach Nordend geschafft.\n\nIrgendwie hat sie die Angriffe auf Tyrs Hand überlebt und ist mit einer kleinen Streitmacht hierhergekommen. Sie haben Neuherdweiler im Süden gegründet.\n\nSie könnten sich zwar im Kampf gegen die Geißel als nützlich erweisen, doch Abbendis ist ein viel zu kluger Gegner, als dass sie uns am Leben lassen wird. Glaubt mir: Wenn wir sie in Frieden lassen, dann werden, ehe wir uns versehen, unsere Kehlen durchgeschnitten sein.\n\nAlso werden wir sie beseitigen und dann wieder zur Tagesordnung zurückkehren. Bringt mir ihren Kopf als Beweis.", progress = "Ist es vollbracht?", completion = "Ein unglücklicher, jedoch notwendiger Schritt, die Sache mit Abbendis. In einem anderen Leben, denke ich, hätte ich Seite an Seite mit ihr kämpfen können.\n\n&lt;Der Kommandant verstummt und wirkt einen Moment lang in Gedanken versunken.&gt;\n\nIch mache mir ein wenig Sorgen über diesen Großadmiral, von dem Ihr sprecht. Naream Westwind meint Ihr? Ich kann nicht glauben, dass er noch immer am Leben ist. Er muss steinalt sein. Wir werden uns jedoch später noch um ihn kümmern müssen.\n\nDoch bevor das geschieht, so denke ich, habt Ihr Euch eine Belohnung und ein wenig Erholung verdient.", rewards = "Blutverschmierte ZauberklingeStreitkolben des gefallenen RabenpriestersSchlachtkolben der FestungGewehr des BelagerungshauptmannsAxt des ZinnenverstärkersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12465] = {title = "Ramschbarts Tagebuch", objective = "Beschafft die 4., 5., 6. und 7. Seite von Ramschbarts Tagebuch und bringt sie Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde.", description = "Was auch immer auf den restlichen Seiten von Ramschbarts Tagebuch gestanden haben mag, muss wieder gefunden werden. Sucht in den Kammern auf der anderen Seite dieses Tunnels nach Ramschbarts Angreifern. Sie müssen diejenigen gewesen sein, die sein Tagebuch in Stücke rissen!\n\nBringt Ambo Unkesch die fehlenden Seiten, falls Ihr sie finden solltet. Er befindet sich am Eingang zum Mausoleum von Wintergarde.", progress = "Mit Sicherheit fühle ich mich nicht wie ein Gewinner...", completion = "&lt;Ambo liest sich die Seiten durch.&gt;\n\nEs gibt eine gute und es gibt eine schlechte Nachricht. Welche willst du zuerst hören?\n\nAch, was soll's, wieso dir die Wahl lassen. Die gute Nachricht ist, dass, sollten wir Thel'zans Phylakterium in die Hände bekommen, wir ihn zerstören können. Die schlechte ist, dass ein ziemlich großer Frostwyrm dieses Ding bei sich hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12466] = {title = "Dem Eissturm hinterher: Front der 7. Legion", objective = "Meldet Euch bei Legionskommandant Tyralion an der Front der 7. Legion im Zentrum der Drachenöde.", description = "Ihr müsst Euch zur Front der 7. Legion im Norden der Drachenöde begeben. Kehrt zur Feste Wintergarde zurück und verlasst die Stadt über das Nordtor. Geht dann immer weiter nach Norden, bis Ihr auf eine Straße trefft. Haltet Euch links und folgt Ihr so lange, bis Ihr die Schneefallgrenze erreicht. Dort angekommen, müsst Ihr in Richtung Westen gehen, bis Ihr beim Pfad der Titanen angelangt seid. Folgt diesem Pfad nach Norden und er wird Euch direkt zur Front der 7. Legion führen.\n\nSprecht mit Legionskommandant Tyralion, sobald Ihr dort angekommen seid. Er wird Euch erwarten.\n\nUnd <Name>: Es war mir eine Freude. Lebt wohl.", progress = nil, completion = "Nun wisst Ihr, wieso sie diesen Ort Dracheneiswüste nennen. Wo das Auge nur hinreicht, liegen Knochen dieser Biester verstreut.\n\nWir haben wahrscheinlich ein Dutzend oder mehr dieser Frostwyrm niedergestreckt und noch immer kein Ende in Sicht. Mit all den Knochen, die herumliegen, kann die Geißel Zehntausende dieser Kreaturen erwecken.\n\n&lt;Tyralion räuspert sich.&gt;\n\nIch möchte Euch zwar nicht mit den Details langweilen, &lt;Klasse&gt;, doch wir haben Euren gesuchten Wyrm gefunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12467] = {title = "Dem Eissturm hinterher: Thel'zans Phylakterium", objective = "Nehmt Eissturm Thel'zans Phylakterium ab und bringt es zurück zu Hochkommandant Halford Wyrmbann in der Feste Wintergarde.", description = "Der Frostwyrm ist dort draußen.\n\n<Tyralion deutet nach Westen.>\n\nUnd es ist ein ganz großer!\n\nWenn Ihr bereit seid zu kämpfen, dann geht und sprecht mit \"Wyrmköder\". Er wird ihn zu uns \"holen\". Sobald Eissturm dann nah genug an uns herangekommen ist, werden wir ihn an den Boden fesseln und ihn erledigen! Hoffentlich können wir ihn mit Eurer Hilfe ausschalten und Euch das Phylakterium beschaffen.\n\nKehrt zur Feste von Wintergarde zurück, sobald Ihr das Phylakterium habt, und meldet Euch bei Hochkommandant Halford Wyrmbann. Zuletzt war er damit beschäftigt, Vorbereitungen für den Entscheidungskampf mit Thel'zan zu treffen.", progress = "Habt Ihr Thel'zans Phylakterium dabei?", completion = "Wir haben so viele gute Soldaten an dieses Scheusal Thel'zan verloren. Ich wünschte, ich könnte dort sein und Euch dabei zusehen, wie Ihr sein Phylakterium vor ihm in Stücke zerschlagt und damit seiner Existenz ein Ende bereitet.", rewards = "Kopfbedeckung des EiswüstenhauchsBrustplatte des SchneewehenhäschersBeinlinge aus Anub'architinHelm des steinigen PfadesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12468] = {title = "Die Aufgabe des Eroberers", objective = "Sprecht mit Unteroffizier Nazgrim in Burg Siegeswall.", description = "Die Horde gleicht einer großartigen Kriegsmaschine und Ihr seid nichts weiter als ein Zahnrad.\n\nIch bin dafür zuständig, den Treibstoff für diese Maschine zu besorgen. Wenn ich versage, wird die Maschine versagen.\n\nHolz, Erz, Wasser... es ist alles da und wir wollen es - so auch die Allianz.\n\nBevor wir gegen den Menschenabschaum vorgehen können, müssen wir zuerst unsere Kontrolle über die westliche Region festigen.\n\nSprecht mit Unteroffizier Nazgrim. Er wird Euch einen Auftrag geben, bei dem Ihr die Vrykul in Voldrune ausschalten müsst. Tut dies - und solltet Ihr Euch nicht als komplett unfähig erweisen, dann werden wir Euch mit weiteren Aufgaben betrauen.", progress = nil, completion = "Krenna hat Euch also zu mir geschickt? Sie muss Euch nicht gerade gemocht haben, doch dann fragt man sich, ob sie überhaupt jemanden mag.\n\nDieser Vrykulaußenposten wird eine harte Nuss sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12469] = {title = "Zurück an den Absender", objective = "Folgt dem Grat nach Osten und liefert das Sprengstoffpaket bei Xink im Düsenrostposten im Norden der Drachenöde ab.", description = "Bei näherer Betrachtung scheint es, als hätte der Goblin ein Paket voller Sprengstoff durch die Eiswüste getragen und wollte es irgendwo abliefern. Die Harpyienfedern, die ganz in der Nähe halb mit Schnee stecken, lassen darauf schließen, wie er sein Ende gefunden haben musste.\n\nEs scheint, als wäre der Goblin mit seinem Sprengstoffpaket von irgendwo im Osten aus zur Pforte des Zorns unterwegs gewesen. Das Klügste wird sein, den Grat zurück nach Osten entlang zu gehen und den Absender über das Schicksal seines Läufers zu unterrichten.", progress = "Hallo Ihr!", completion = "Ha! Wir haben noch einen verloren, oder was? Diese Harpyien werden langsam zu einer echten Landplage.\n\nEgal! Es gibt Arbeit zu tun. Würdet Ihr uns freundlicherweise zur Hand gehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12470] = {title = "Mysterium der Unendlichkeit", objective = "Chromie auf der Spitze des Wyrmruhtempels möchte, dass Ihr zum Bronzedrachenschrein reist. Stellt das Stundenglas der Ewigkeit dort im Inneren des Schreins auf den Boden.\n\nBeschützt das Stundenglas so lange wie nötig und kehrt anschließend mit den erhaltenen Informationen zu Chromie zurück.", description = "Ein Zeitsturm am Bronzedrachenschrein gen Nordosten hält die Ewigen davon ab Zugang zu erhalten und einzutreten.\n\nDer ewige Drachenschwarm und die Verteidiger kämpfen dort um die Kontrolle über den Drachenschrein. Wir müssen diese Gelegenheit wahrnehmen und uns die Informationen schnappen.\n\nIhr seid nicht unsterblich - Ihr könnt den Drachenschrein betreten und das Stundenglas der Ewigkeit benutzen. Stellt es auf, beschützt es lange genug und der Anführer des ewigen Drachenschwarms sollte sich zeigen.\n\nSeid gewarnt, der ewige Drachenschwarm wird versuchen, Euch aufzuhalten!", progress = nil, completion = "Ihr habt Nozdormu gesehen? Das ergibt keinen Sinn.\n\n&lt;Chromie scheint einen Augenblick über das nachzudenken, was Ihr gesagt habt.&gt; Hm, das sind eigentlich gute Neuigkeiten! Wir hatten keine Ahnung, wohin oder wann der Lord der Zeit verschwunden ist. Wir wussten lediglich, dass er verschwand, um sich wichtigen Angelegenheiten zu widmen.\n\nNun, Ihr habt zwar nicht herausfinden können, wer nun der Anführer des ewigen Drachenschwarms ist, doch Ihr habt herausgefunden, dass Nozdormu am Leben ist, es ihm gut geht und dass er sich zur Wehr setzt!\n\nIch danke Euch, &lt;Name&gt;. Wir werden uns bald wiedersehen!", rewards = "ZeitsplitterkeilDolch der wiederkehrenden VergangenheitKracher der ZeitkrümmungZweig der fröhlichen ErinnerungsstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12471] = {title = "Grausamkeiten der Kvaldir", objective = "Sprecht mit Karuk über den eingesperrten Tuskarrgefangenen", description = "Ich danke Euch für meine Rettung, <Name>. Die Kvaldir sind Tiere!\n\nSie ließen uns gegen die anderen Gefangenen kämpfen. Es wäre barmherzig gewesen, uns alle einfach zu töten.\n\nDer Jüngling Karuk ist noch immer am Leben. Ich habe seine Ankunft hier bemerkt. Sagt ihm, dass sein Vater bis zuletzt kämpfte.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Ihr habt meinem Klan gegenüber viel Wohlwollen gezeigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12472] = {title = "Endgültigkeit", objective = "Bringt Thel'zans Phylakterium zu Legionskommandant Yorik im Inneren des Mausoleums von Wintergarde in der Drachenöde.", description = "Euren Heldentaten ist es zu verdanken, dass Lord Fordragon zum vollen Angriff auf Thel'zan geblasen hat. Die 7. Legion ist in die Beschwörungskammer des Mausoleums vorgedrungen und hat etwas gefunden, das wie ein Tor zur Hölle aussieht. <Der Einzige, der/Die Einzige> die; noch fehlt, seid Ihr.\n\nHier, nehmt das Phylakterium und meldet Euch bei Legionskommandant Yorik im Inneren des Mausoleums von Wintergarde.\n\nGleich außerhalb der Festung gibt es einen Tunnel, der von der Geißel ausgehoben wurde und über den Ihr schnell zu Yorik gelangen könnt. Geht nun, <Name>! Führt uns zum Sieg!", progress = "<Yorik seufzt vor Erleichterung.>\n\nWir dachten schon, dass Ihr nicht kommen würdet, <Name>.", completion = "Wenn Ihr bereit seid, dann werde ich das Phylakterium vor dem Tor aufstellen und Thel'zan herbeirufen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12473] = {title = "Ein Ende und ein neuer Anfang", objective = "Besiegt Thel'zan den Dämmerbringer und meldet Euch anschließend bei Oberkommandant Halford Wyrmbann in Wintergarde in der Drachenöde.", description = "Jede gute Geschichte hat einen Anfang und ein Ende, <Name>. Unsere Geschichte ist zwar noch weit davon entfernt, ein Ende zu finden, doch ich soll verdammt sein, wenn sie nicht schon jetzt Stoff für Legenden ist! Ganz gleich, was mit uns geschehen wird; wenn das hier vorbei ist wird man noch Jahre später über das sprechen, was Ihr bei Wintergarde geleistet habt.\n\nNun denn, <Verbündeter/Verbündete>, wenn Ihr bereit seid, werde ich mithilfe des Phylakteriums Thel'zan aus seinem Versteck locken.\n\nFalls wir es überstehen sollten, dann informiert Oberkommandant Halford Wyrmbann in Wintergarde über unseren Erfolg.", progress = nil, completion = "Dank Euch ist Wintergarde nun sicher, &lt;Name&gt;. Für die Meisten ist es unbegreiflich, wie ein einziger Mann in solch kurzer Zeit es schaffen kann, das Blatt in dieser Schlacht zu unseren Gunsten zu wenden. Doch wie man sieht, sind wir noch hier und siegreich! Ihr habt diesen Leuten wieder zu neuer Hoffnung verholfen und Euch den Respekt unserer Befehlshaber verdient.\n\n\n\nLord Fordragon ist nach Angrathar zurückgekehrt, um dort unsere Truppen auf die Zerstörung der Pforte des Zorns vorzubereiten, und wünscht sich Euch an seiner Seite! Ich könnte mir keinen besseren Soldaten für den Auftrag vorstellen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12474] = {title = "Auf zur Feste Fordragon!", objective = "Geht zur Feste Fordragon in der Drachenöde und sprecht mit Hochlord Bolvar Fordragon.", description = "Naxxramas' Kriegsmaschine ist zum Stillstand gebracht worden. Nun ist die Zeit gekommen, da Ihr unseren Streitkräften bei Angrathar, der Pforte des Zorns, zur Seite stehen sollt. Im Norden der Drachenöde schmiegt sie sich an einen Berg, unsere Operationsbasis namens Feste Fordragon. Dort wird Euch auch Lord Fordragon erwarten! Geht jetzt, <Name>!\n\nVerlasst die Stadt über das Nordtor und geht so lange in nord-nordwestliche Richtung, bis Ihr Euer Ziel erreicht habt.\n\nDas Licht beschütze Euch!", progress = nil, completion = "Diese Auszeichnung wird nur an diejenigen gegeben, die jenseits der Pflicht gehandelt haben, im Namen der Allianz. Ich könnte die Male, dass ich dies hier an jemanden Übergebe, an einer Hand abzählen, &lt;Name&gt;, und doch hat es noch niemand so verdient wie Ihr! Herzlichen Glückwunsch!\n\nNun lasst uns einen Blick auf die Pforte des Zorns werfen. Kommt Euch etwas bekannt vor? Das sollte es. Das seltsame Erz, das Ihr in den Minen von Wintergarde gefunden habt, ist dasselbe, aus dem auch die Pforte des Zorns geschaffen ist. Wir werden ihre Schwachstelle finden und sie bloßlegen, auf dass alle sie sehen können! Zuerst jedoch...", rewards = "Sandalen der chaotischen LösungUnerbittliche ZombiezermalmerTreter des tapferen RingensVerstärkte Stiefel des ReisendenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12475] = {title = "Männergeheimnisse", objective = "Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr die Karte des Scharlachroten Ansturms findet und sie zu ihm zurückbringt.", description = "Es war nach dem Verrat am Vergessenen Strand, als sich Prinz Arthas mit Muradin im Schlepptau auf die Suche nach Frostgram machte. Könnte es sein, dass sich die Höhle, in der das Schwert gefunden wurde, ganz in der Nähe befindet? Welche Geheimnisse birgt sie? Die Kugel hat zwar keine Antworten auf diese Fragen, doch etwas kann sie mir zeigen.\n\nIm Nordosten der Feste Wintergarde befindet sich ein Außenposten des Scharlachroten Ansturms. Dort gibt es irgendwo eine Karte. Die Kugel sagt mir, dass uns diese Karte von großem Nutzen sein wird.\n\nBeschafft sie mir!", progress = "Habt Ihr die Karte des Scharlachroten Ansturms gefunden?", completion = "Eine Höhle? Könnte es sein? Die Sache ist eindeutig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12476] = {title = "Die Rückkehr des Kreuzzugs?", objective = "Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 20 Mitglieder des Scharlachroten Ansturms im Basislager des Ansturms tötet.", description = "Nordöstlich der Feste Wintergarde ist ein neues Lager, das vom Scharlachroten Kreuzzug - oder eher dem Scharlachroten Ansturm, wie sie sich jetzt nennen - aufgeschlagen wurde. Obwohl wir nicht sicher sind, warum sie sich in Nordend rumtreiben, sind sie sicherlich nicht weniger gefährlich als zuvor. Seit letzter Nacht hat der Scharlachrote Ansturm zwölf unserer Soldaten getötet. Denen muss eine Lektion erteilt werden, <Name>.\n\nGeht zum Basislager des Ansturms und lichtet ihre Reihen.", progress = nil, completion = "Hoffentlich hat der Ansturm die Botschaft jetzt verstanden. Ich hoffe die Prügel haben ausgereicht, um sie an ihrer Zugehörigkeit zweifeln zu lassen.", rewards = "Ihr bekommt:\n\nRunenverzierter Heiltrank"}
MultiLanguageQuestData['de'][12477] = {title = "Der Weg der Erlösung", objective = "Bringt \"Der Weg der Erlösung\" zu Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde.", description = "Schon einmal von \"Der Weg der Erlösung\" gehört? Es ist angeblich ein Pamphlet, in dem das prophetische Gerede von Hochgeneral Abbendis vom Scharlachroten Ansturm festgehalten ist. Darin kann man die Motive und Ziele der Scharlachroten Fanatiker finden - ganz zu schweigen von einem Haufen Irrsinn.\n\nBegebt Euch zum Basislager des Ansturms nordöstlich der Feste Wintergarde und besorgt eine Ausgabe von \"Der Weg zur Erlösung\" von einem der Soldaten des Ansturms.", progress = "Habt Ihr eine Ausgabe gefunden?", completion = "&lt;Halford liest in dem Pamphlet.&gt;\n\nAbbendis ist vollkommen übergeschnappt. Das Licht spricht jetzt zu ihr?\n\nAbgesehen von diesem Irrsinn gibt uns dieses Pamphlet einen nie dagewesenen Einblick in die Sichtweise der Scharlachroten Fanatiker. Das ist großartig, &lt;Name&gt;. Lord Fordragon wird erfreut sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12478] = {title = "Frostgramhöhlen", objective = "Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr am Ende der Frostgramhöhlen Zeligs Seherkugel benutzt. Lüftet die Geheimnisse der Vergangenheit!", description = "Sie haben sie 'Frostgramhöhlen' benannt. Weshalb der Scharlachrote Ansturm an solchen Dingen interessiert ist, ist nicht bekannt, doch wie die Sache aussieht, wird die Gegend um die Höhle herum schwer bewacht. Nichtsdestoweniger müssen wir fortfahren!\n\nHier, nehmt diese Seherkugel, verlasst die Stadt gen Norden, schlagt dann den Weg in nördliche Richtung ein und Ihr werdet zur Scharlachroten Wacht gelangen. Anschließend müsst Ihr die Höhle betreten und Euch bis zu deren Ende hindurchkämpfen. Macht von der Kugel Gebrauch, sobald Ihr dort seid, und kehrt alsdann mit dem, was Ihr gefunden habt, wieder hierher zurück.", progress = "Habt Ihr schon die Frostgramhöhlen erforscht?", completion = "Muradin lebt? Ist es möglich? Ich muss König Bronzebart umgehend davon berichten!\n\nIch muss die Kugel befragen; es muss noch mehr zu wissen geben - irgendwo!", rewards = "Hüfttuch der energischen ZerstörungVerbund der rechtschaffenen VerfolgungGürtel der rachsüchtigen LäuterungGurt der kraftvollen VernichtungIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12479] = {title = "Auf nach Nordend!", objective = "Sprecht mit dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra oder im Hafen der Vergeltung im Heulenden Fjord.Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra Bericht erstattet oder nach Valgarde im Heulenden Fjord geht.", description = "Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra Bericht erstattet oder nach Valgarde im Heulenden Fjord geht.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12480] = {title = "Auf nach Nordend!", objective = "Sprecht mit dem Rekrutierer der Horde im Inneren der Kriegshymnenfeste in der Boreanischen Tundra oder im Hafen der Vergeltung im Heulenden Fjord.Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Horde in der Kriegshymnenfeste in der Boreanischen Tundra Bericht erstattet oder zum Hafen der Vergeltung im Heulenden Fjord geht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Horde in der Kriegshymnenfeste in der Boreanischen Tundra Bericht erstattet oder zum Hafen der Vergeltung im Heulenden Fjord geht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12481] = {title = "Salz in die Wunde streuen", objective = "Lest Björn Halgurdsson in Quälheim die Vrykulbeleidigung laut vor, lockt ihn dann zu Lydells Hinterhalt und helft den anderen, ihn zu töten.", description = "Die Vrykul beweisen viel Geschick in dieser Angelegenheit. Glücklicherweise habe ich noch ein Ass im Ärmel.\n\nDieser Anführer von ihnen, Björn, ist ein echter Hitzkopf. Wir haben aus ein paar Fetzen ihrer Sprache eine, wie wir meinen, gute Beleidigung gebastelt. Irgendwas, das sich um seine Mutter und großes Nutzvieh dreht... Wir sind uns nicht so ganz sicher.\n\nNehmt dieses Stück Papier und lest es ihm vor. Lockt ihn hierher zurück, sobald er hinter Euch her ist. Wir werden dafür sorgen, dass er nicht lebend davonkommt.", progress = "Die Arbeit eines Meuchelmörders ist nicht so glamourös, wie immer behauptet wird.", completion = "Gute Arbeit. Den armen Trottel hat's eiskalt erwischt.", rewards = "Geprägter HermelingurtKnochenverzierte ArmschienenMagdunschiftungRunenplattenhelmIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12482] = {title = "Gegen Niffelvar", objective = "Waldläuferhauptmann Areiel möchte, dass Ihr nach Niffelvar geht und 5 Krieger der Drachenschinder, 4 Runenseher der Drachenschinder und 4 Jagdhunde der Drachenschinder tötet.", description = "Wir erwarten Verstärkung vom Hafen der Vergeltung, um gegen Niffelvar vorzugehen. Wenn wir es früher einnehmen könnten, würde uns das einen riesigen Vorteil gegen die Allianz verschaffen.\n\nGeht in die Stadt und schaut, ob Ihr ihre Reihen etwas schmälern könnt.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Wenn unsere Truppen aus dem Hafen der Vergeltung eintreffen, werden wir uns um jeden übrig gebliebenen Vrykul kümmern können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12483] = {title = "Schimmerkappeneintopf", objective = "Prigmon am Granitquell möchte, dass Ihr 5 Schimmernde Schneekappen und 5 Eisschlangenaugen in den Ruinen von Drak'Zin und 5 Süßwurzeln aus Zeb'Halak sammelt.", description = "Sag, wo du gerade hier bist, was hältst du davon, dem alten Prigmon bei 'ner kleinen Arbeit zu helfen? Hab'n Freund, der'n fiesen Eintopf macht - so einen haste noch nie gegessen!\n\nGibt'n paar Zutaten, die man hier in der Gegend finden kann un' die er braucht. Sind in den Ruinen im Südwesten und im Lager gleich nördlich von hier.\n\nWas sagst du, Mann?", progress = "Du hast die Zutaten für'n alten Prigmon besorgt, <Name>?", completion = "Oh, Mann - Schimmerkappeneintopf! Ich kann ihn schon fast schmecken...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12484] = {title = "Geißelkebab", objective = "Prigmon am Granitquell möchte, dass Ihr eine mumifizierte Trollleiche zu Mack Fearsen bringt und sie dort ins Feuer werft.", description = "Uff.\n\nMir tut es im Herzen weh, diese unglückseligen Trolle einzuwickeln, doch nicht so sehr, wie es meinem Rücken weh tut!\n\nHelft dem alten Prigmon und bringt eine der Leichen rüber zu Mack.\n\nWenn wir sie nicht verbrennen, werden sie in Kürze wieder herumlaufen.", progress = "Was habt Ihr denn da, <Volk>?", completion = "Nisch is' schöner, alsch die Geißel brennen zu sehen... &lt;hicks&gt;.\n\nHab' ein kleinesch Lied darüber geschrieben. Wollt Ihr's mal hör'n? Es geht so...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12486] = {title = "Auf zum Außenposten Bor'gorok, schnell!", objective = "Sprecht mit Geisterflüsterin Fletschfang im Außenposten Bor'gorok.", description = "Habt Ihr das gespürt?\n\n<In seiner Verwirrung fasst sich Sauranok kurz an die Brust. Als er seine Hand wegzieht, hinterlässt sie glühend heißen Dampf.>\n\nEtwas Schreckliches ist meinem alten Freund Scharfseher Grimmläufer zugestoßen - gerade eben konnte ich es fühlen.\n\nEr hatte einen Schüler und diesen nahm er mit, als er sich auf die Reise nach Norden machte. Sie wollten der Oberanführerin dabei helfen, einen Außenposten an der Grenze des Sholazarbeckens zu errichten.\n\nSie heißt Fletschfang und gehört den Geisterflüsterern an.\n\nWomöglich wird sie wissen, was passiert ist - oder zumindest dabei helfen können, es herauszufinden.", progress = nil, completion = "Der Mystiker weiß Bescheid? Ihr meint, dass er gespürt hat, dass Weissager Grimmläufer etwas Schreckliches zugestoßen ist?\n\nWie ich befürchtet habe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12487] = {title = "Auf nach Burg Siegeswall! Doch Achtung!", objective = "Stellt Euch Eroberin Krenna vor. Sie befindet sich in Burg Siegeswall in den Grizzlyhügeln.", description = "Ich habe von unserer Basis in den Grizzlyhügeln einen Hilferuf erhalten. Geht also hinaus und sucht Eroberin Krenna auf.\n\n<Der Hochexekutor wedelt mit einem Bündel Pergament, als sei es ihm völlig egal, was darauf stünde.>\n\nSie versucht, alle dortigen natürlichen Ressourcen für uns zu sichern oder so was in der Art. Hütet Euch nur vor ihr. Man sagt, dass sie selbst für einen Orc ziemlich aggressiv sein soll.\n\nFolgt der Straße nach Osten und dann nach Südosten. Überquert die Brücke am Drachenwirbelzufluss und biegt am Handelsposten Immergrün nach Osten ab.", progress = nil, completion = "Wer seid Ihr?\n\nSagt mir, wieso ich Euch nicht an Ort und Stelle in zwei Teile spalten soll!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12488] = {title = "Der Hochexekutor braucht Euch", objective = "Sprecht mit Hochexekutor Zürner in Gallgrimm in der Drachenöde.", description = "Es ist gut, dass ich Hochexekutor Zürners Brief abfangen konnte, bevor Oberanführer Agmar ihn erhielt. Was hat sich Zürner nur dabei gedacht?\n\n<Der Unteroffizier zerreißt den Brief.>\n\n<Klasse>, geht und seht einmal nach, was der Hochexekutor will.\n\nFolgt der Straße nach Osten und durchquert die Dracheneiswüste. Ein Pfad, der aus der Wüste hinausführt, findet sich auf der südöstlichen Seite. Gallgrimm, die Stadt der Verlassenen, wird sich dann direkt vor Euch, auf der Südseite des Berges, befinden.", progress = nil, completion = "Man hat Euch aus Agmars Hammer geschickt? Wurde auch langsam Zeit!\n\nNein, ich benötige keine Hilfe. Ich kann einfach niemanden entbehren. Ihr werdet jedoch genügen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12489] = {title = "Willkommen im Sholazarbecken", objective = "Folgt dem Pfad in Richtung Nordwesten, bis Ihr das Lager erreicht, das Monti erwähnt hat.", description = "Wo bist du noch mal her? Ich würde mal meinen, dass der Trottel von einem Erzmagier dich geschickt hat, stimmt's?\n\nDu hast Glück gehabt, dass du's heil hierher geschafft hast, <mein Junge/mein Mädel>! Sie hätten dich beinahe in die Luft gejagt!\n\nDer Dschungel hier ist ein verdammt gefährlicher Ort, ganz besonders dann, wenn die Venture Company in der Gegend ist.\n\nNa los, du Hohlkopf! Auf zum Boss... er wird sich um dich kümmern. Das Lager liegt in Richtung Nordwesten am Wegesende.\n\nHopp, hopp!", progress = nil, completion = "Ha! Es passiert nicht oft, dass man mitten im Dschungel jemanden trifft, den man überhaupt nicht kennt.\n\nDu bist einer von den Druidenlakaien, der \"mir und meinen bösen Machenschaften ein Ende setzen soll\", stimmt's? Ja, ja - viel Glück damit!\n\n&lt;Hemet lacht schallend und tätschelt sein Gewehr.&gt;\n\nHätte das auch nicht gedacht! Du bist recht herzlich eingeladen, bei der Jagd mitzumachen, sobald wir uns um die Hunde von der Venture Company gekümmert haben. Es ist genug für alle da.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12490] = {title = "Veehjas Rache", objective = "Veehja im Schrein der Schuppen möchte, dass Ihr 6 Matrosen der Skadir, 3 Nebelwirker der Skadir und 2 Runenmagier der Skadir erschlagt.", description = "Heute haben wir ein und denselben Feind, <Volk>! Mein Volk wurde von diesen Kvaldir ausgelöscht... meine Stadt wurde so gut wie dem Erdboden gleichgemacht. Es ist Zeit, Rache zu nehmen!\n\nAls Gegenleistung für meine Hilfe möchte ich, dass Ihr die barbarischen Monster erschlagt, die den Strand der Peitschennarbe besudeln. Euch winkt eine großzügige Belohnung, <Klasse>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12491] = {title = "Düsterbräus Düsterbräu", objective = "Bringt Düsterbräus Düsterbräu zu Ipfelkofer Eisenfass im Braufestlager in der Nähe von Eisenschmiede.", description = "Coren Düsterbräus Leiche hielt dieses fest an seinen Bauch gedrückte Fass umklammert. Hierbei muss es sich um sein berüchtigtes Düsterbräu handeln!", progress = "<Name>, Ihr macht so ein grimmiges Gesicht. Habt Ihr schlechte Neuigkeiten?", completion = "Das ist Coren Düsterbräus Trunk? Das Bier, das er um jeden Preis beim Braufest präsentieren wollte? Nun, rein offiziell können wir diesen Beitrag zwar nicht anerkennen, doch aus Respekt einem gescheiterten Braumeister gegenüber, werde ich mir vielleicht ein Schlückchen erlauben...", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][12492] = {title = "Düsterbräus Düsterbräu", objective = "Bringt Düsterbräus Düsterbräu zu Zapfus Schwindelfass im Braufestlager in der Nähe von Orgrimmar.", description = "Coren Düsterbräus Leiche hielt dieses fest an seinen Bauch gedrückte Fass umklammert. Hierbei muss es sich um sein berüchtigtes Düsterbräu handeln!", progress = "He, <Name>, Euer Gesicht ist so dreckig! Seid Ihr in die Schwarzfelstiefen hinabgestiegen?", completion = "Ah, Düsterbräu hat also sein Bier letztendlich beim Braufest präsentieren können. Wie schade nur, dass er dafür hat sterben müssen...\n\nNaja... zum Wohl, nicht wahr?", rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][12493] = {title = "PvP-Test", objective = "Tötet 10 Gegner.", description = "Bringt ein paar von der anderen Seite um! Diese Typen sind doch total ätzend! Ich muss was testen, wiederholen wir das also wieder und wieder und wieder...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEroberungspunkte"}
MultiLanguageQuestData['de'][12495] = {title = "Audienz bei der Drachenkönigin", objective = "Geht zum Wyrmruhtempel in der Drachenöde und sucht Alexstrasza die Lebensbinderin auf.", description = "Unser Angriff auf Angrathar hat die Geißel zwar ins Wanken gebracht, doch beugen wollen sie sich nicht. Ihre Frostwyrms stoßen von hoch droben auf das Schlachtfeld herab, was einen Vormarsch zur Pforte selbst unmöglich macht. Die Angriffe der Frostwyrms müssen gestoppt werden, doch bevor wir die Knochen uralter Drachen schänden, müssen wir ihre Königin um Erlaubnis bitten.\n\nReist gen Südosten zum Wyrmruhtempel und sucht Königin Alexstrasza auf. Erzählt ihr von unserem Vorhaben und erbittet ihren Rat.\n\nGeht nun, <Name>!", progress = nil, completion = "Ihr seid gekommen, um meinen Rat zu hören, Sterblicher - das weiß ich. Doch wisst Ihr was Euch erwartet?\n\n&lt;Alexstrasza deutet gen Norden.&gt;\n\nNördlich von hier befindet sich der Ort, an dem Galakrond, Vorfahre aller Drachen, sein Leben ließ. Es war Galakrond, aus dem die Titanen die Aspekte schufen. Nun stellt Euch vor, welch Macht er besaß. Seine Größe allein übertraf die aller Aspekte zusammengenommen! Nun könnt Ihr dreimal raten, was die Geißel in der großen Drachenöde vorhat.\n\nFrostwyrm, Sterblicher, sollten Eure geringste Sorge sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12496] = {title = "Audienz bei der Drachenkönigin", objective = "Geht zum Wyrmruhtempel in der Drachenöde und sucht Alexstrasza die Lebensbinderin auf.", description = "Ich weiß, dass Ihr danach hungert, die Geißel vor uns an der Pforte des Zorns zu vernichten, doch zuerst müssen wir uns um die Gefahr kümmern, die über uns lauert. Solange die Angriffe der Frostwyrms andauern, können wir nicht weitermarschieren.\n\nDoch bevor wir die Ruhestätte von Drachen angreifen, muss uns zuerst Erlaubnis erteilt werden. Macht Euch nun auf den Weg zu den geheiligten Hallen der Drachen, dem Wyrmruhtempel. Sucht Königin Alexstrasza auf, sobald Ihr angekommen seid.\n\nReitet, <Name>! Auf nach Südosten, auf zum Wyrmruhtempel!", progress = nil, completion = "Ihr seid gekommen, um meinen Rat zu hören, Sterblicher - das weiß ich. Doch wisst Ihr was Euch erwartet?\n\n&lt;Alexstrasza deutet gen Norden.&gt;\n\nNördlich von hier befindet sich der Ort, an dem Galakrond, Vorfahre aller Drachen, sein Leben ließ. Es war Galakrond, aus dem die Titanen die Aspekte schufen. Nun stellt Euch vor, welch Macht er besaß. Seine Größe allein übertraf die aller Aspekte zusammengenommen! Nun könnt Ihr dreimal raten, was die Geißel in der großen Drachenöde vorhat.\n\nFrostwyrm, Sterblicher, sollten Eure geringste Sorge sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12497] = {title = "Galakrond und die Geißel", objective = "Sprecht mit Torastrasza im Wyrmruhtempel in der Drachenöde.", description = "Hoch oben auf der Serpentine, auf den Schultern des rekonstruierten Sturmriesenfürsten Thiassi sitzt er, Antiok, der Großnekrolord der Geißel. Von dort aus befiehlt er die Armeen der Untoten und lässt sie Tag und Nacht graben, um Galakronds riesige Knochen freizulegen. Sollten sie Galakrond wieder zum Leben erwecken, wären all unsere Mühen umsonst gewesen.\n\nMir ist es zwar nicht möglich, den geballten Zorn des roten Drachenschwarms anzurufen, um Euch auf Eurer Reise zu unterstützen, doch meinen Segen werde ich Euch gewähren. Geht nun und sprecht mit meinem Majordomus Torastrasza.", progress = nil, completion = "Die Tapferkeit der Sterblichen erstaunt mich immer wieder. Der Tod hat seinen kalten Blick auf Euch fixiert - und was macht Ihr? Ihr stemmt Euch gegen den Anspruch, den er geltend machen will! Genau aus diesem Grund wird Euresgleichen so geliebt... und so gehasst.\n\nDie Auseinandersetzung zwischen Malygos und dem roten Drachenschwarm ist erbittert und festgefahren, jedoch gibt es noch immer etwas, das wir tun können, um zu helfen.", rewards = nil}
MultiLanguageQuestData['de'][12498] = {title = "Auf rubinroten Schwingen", objective = "Zerstört 30 Ödnisplünderer und beschafft Euch Antioks Sense. Kehrt anschließend zu Alexstrasza der Lebensbinderin im Wyrmruhtempel zurück, solltet Ihr diese Aufgabe abschließen.", description = "Signalisiert mit diesem Leuchtfeuer einem Bezwinger des Wyrmruhtempels, dass er neben Euch landen soll. Klettert dann auf seinen Rücken und fliegt gen Norden zu Galakronds Ruh. Sobald Ihr dort angelangt seid, befehlt Ihr dem Drachen, die Aasfresser der Geißel zu vernichten, die mit der Ausgrabung von Galakrond beschäftigt sind. Dann, sobald die Gegend gesäubert ist, fliegt Ihr zur Serpentine über Galakronds Ruhestätte, zerstört Großnekrolord Antiok und nehmt ihm die Sense ab, mit deren Hilfe er die Drachen beherrscht.\n\nErledigt dies und kehrt anschließend zu Königin Alexstrasza zurück, um eine für einen Helden angemessene Belohnung zu erhalten!\n\n<Name>, nehmt Euch vor den faulenden Sturmriesen in Acht, die in der Gegend umherirren!", progress = "Zerstört die Anhänger der Geißel in Galakronds Ruhestätte, bevor es zu spät ist!", completion = "Ich wusste, dass Ihr zurückkehren würdet, &lt;Name&gt;. Ihr habt dem Wyrmruhpakt gut gedient und unser Volk vor dem sicheren Tod bewahrt. Lasset es alle wissen und schickt die Schreiber an, es für die Nachwelt aufzuzeichnen!", rewards = "Bedeckung des GeißeltötersWyrmfeuerbindungenBrustplatte des RubinchampionsAuf Euch wartet eine dieser Belohnungen:\n\nWille des roten Drachenschwarms\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12499] = {title = "Die Rückkehr nach Angrathar", objective = "Sprecht mit Hochlord Bolvar Fordragon in der Feste Fordragon und erzählt ihm von Eurem Sieg über die Geißel.", description = "Da Antiok nun erschlagen und die Sense in unserem Besitz ist, werden die Angriffe der Frostwyrms auf unsere Streitkräfte aufhören. Die verbliebenen Wyrms in der Drachenöde werden gejagt und vernichtet, ihre Knochen wieder der Erde übergeben werden.\n\nDie Zeit ist nun gekommen, um ihnen ein letztes Mal entgegenzutreten, <Name>. Kehrt zur Feste Fordragon zurück und erstattet Hochlord Fordragon Bericht.", progress = nil, completion = "Wisset: All Eure bisherigen Taten liefen auf dieses Treffen hinaus. Ohne Eure Mühen wären wir am Ende gewesen! Haltet nun Wache, während ich ins Feld ziehe und der Sache ein Ende bereite!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von NordendEmblem des Heldentums"}
MultiLanguageQuestData['de'][12500] = {title = "Die Rückkehr nach Angrathar", objective = "Sprecht mit Saurfang dem Jüngeren im Vorposten der Kor'kron und erzählt ihm von Eurem Sieg über die Geißel.", description = "Da Antiok nun erschlagen und die Sense in unserem Besitz ist, werden die Angriffe der Frostwyrms auf unsere Streitkräfte aufhören. Die verbliebenen Wyrms in der Drachenöde werden gejagt und vernichtet, ihre Knochen wieder der Erde übergeben werden.\n\nDie Zeit ist nun gekommen, um ihnen ein letztes Mal entgegenzutreten, <Name>. Kehrt zum Vorposten der Kor'kron zurück und erstattet Saurfang dem Jüngeren Bericht.", progress = nil, completion = "Mein Vater hatte Recht mit Euch, &lt;Name&gt;. Alles, was er sagte, ist eingetroffen - bleibt nur noch eine einzige, letzte Pflicht. Ich werde mit den Kor'kron nun an die Front gehen. Die Zeit, diesen Krieg zu beenden, ist gekommen. Die Tyrannei des Lichkönigs wird heute ein Ende finden!\n\nNehmt meinen Posten ein, &lt;Name&gt;, und behaltet unsere Truppen im Auge.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12501] = {title = "Trollpatrouille", objective = "Kommandant Kunz von der Argentumwache möchte, dass Ihr die vier Posten des Argentumkreuzzugs besucht, die Befehle der dortigen Hauptmänner ausführt und anschließend zurückkehrt und Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel findet Ihr in Drak'Agal und Alchemist Finkelstein am Posten von Heb'Valok.", description = "Zieht Eure Waffe, <Volk>. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", progress = nil, completion = "Nun gut, &lt;Name&gt;, immerhin habt Ihr es in einem Stück zurückgeschafft. Das ist vermutlich auch schon was wert…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12502] = {title = "Trollpatrouille: Standarten hoch", objective = "Hauptmann Brandon möchte, dass Ihr das Banner des Argentumkreuzzugs auf den Drakkaripodesten in Drak'Sotra aufstellt.", description = "Hört zu, <Klasse>. Dies ist der Argentumkreuzzug. Unsere Männer werden bis zum bitteren Ende kämpfen und sich niemals beschweren, egal wie die Umstände auch sein mögen.\n\nNichtsdestoweniger haben wir schwere Verluste auf dieser Kampagne hinnehmen müssen, sind schwer gezeichnet und haben seit Monaten gar keinen oder nur wenig Schlaf gehabt. Das alles geht auf Kosten der Moral, ob wir es wahr haben wollen oder nicht.\n\nEuch mag es wie eine Kleinigkeit erscheinen, doch ein Soldat ist beruhigt, wenn er seine Standarte über dem Schlachtfeld wehen sieht. Nehmt diese Banner und stellt sie auf den Podesten in Drak'Sotra auf.", progress = nil, completion = "Gute Arbeit, mein Freund.\n\nEs ist schon erstaunlich, wie viel so ein bisschen Fahne auf dem Schlachtfeld bewirken kann.\n\nAls nächstes solltet Ihr rüber zu Hauptmann Rupert gehen. Er ist bei der Mauer gleich nordöstlich von hier stationiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12503] = {title = "Verteidigt die Stellung", objective = "Kommandant Falstaav hat Euch damit beauftragt, 10 beliebige Diener der Geißel auf dem Hof der Argentumwache zu vernichten.", description = "Obwohl wir im unteren Drittel von Zul'Drak bedeutende Erfolge erzielt haben, müssen wir uns noch immer dem Ansturm der Geißel stellen. So will es nun mal diese eisige Hölle.\n\nDie Angriffe hören nicht mehr auf, doch meine Männer müssen sich ausruhen. Falls Ihr einverstanden seid, dann würden wir Euch gerne zu ihrer Unterstützung schicken.\n\nUnten auf dem Hof ist kein Ende der Kämpfe abzusehen. Tötet dort so viele Diener der Geißel, wie Ihr nur könnt, <Klasse>.", progress = nil, completion = "Eure Unterstützung in dieser Sache wird sehr geschätzt. Ohne Eure Hilfe hätten wir Schwierigkeiten damit, die Untoten von unseren Stufen fernzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12504] = {title = "Der Argentumkreuzzug rückt ab!", objective = "Unteroffizier Stackhammer am Altar von Sseratus möchte, dass Ihr mit 10 seiner Argentumsoldaten sprecht und ihnen sagt, dass sie sich bei ihm zurückmelden sollen.", description = "<Der Unteroffizier überfliegt die Befehle, die Ihr ihm überbracht habt, und runzelt die Stirn.>\n\nSeht her, <Klasse>, ich würde liebend gerne einfach meine Sachen packen und von hier verschwinden, aber seht Euch doch nur mal um: All meine Männer sind in Kämpfe verwickelt.\n\nIch sag Euch was: Ihr seid bis hierhergekommen, denkt Ihr, dass Ihr mir nicht einen kleinen Gefallen tun und meine Soldaten dort draußen zusammentrommeln könntet?\n\nSagt ihnen, dass sie Befehl vom Unteroffizier haben und sich sofort bei mir zurückmelden sollen. Helft etwas nach, wenn Ihr wollt.", progress = nil, completion = "Nun gut. Wir werden den Rest zusammentrommeln und uns zum Stützpunkt zurückziehen.\n\nEs ist eine Schande, dass wir schon so bald zurück müssen. Fühlt sich nicht gerade an, als wäre die Arbeit hier erledigt, und um ganz ehrlich zu sein, habe ich das Gefühl, dass der Prophet vor dem Altar große Schwierigkeiten bereiten wird!", rewards = "Kampfbereite BeinwickelTapferer Gürtel der SchlachtDicke Armschienen der SchlachtKampfbereites WamsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12505] = {title = "Neue Befehle für Unteroffizier Stackhammer", objective = "Kommandant Kunz hat Euch gebeten, Unteroffizier Stackhammer am Altar von Sseratus die Neuen Einsatzbefehle zu bringen.", description = "<Klasse>, Ihr seid hier, um zu helfen, richtig? Ich habe neue Befehle für unsere Truppen, die derzeit am Altar der Drakkari im Norden eingesetzt sind.\n\nIhr könnt ihn nicht verfehlen. Einfach immer der Straße folgen. Es sollte nicht schwer sein, Unteroffizier Stackhammer zu finden.", progress = "Worum geht's?", completion = "&lt;Der Zwergenunteroffizier schaut argwöhnisch auf die Befehle in Eurer Hand.&gt;\n\nSind diese neuen Befehle etwa für mich, mein Herr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12506] = {title = "Ärger am Altar von Sseratus", objective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr das Hauptaltargebäude auf dem Altar von Sseratus untersucht.", description = "Es gibt Ärger am Altar des Schlangengottes.\n\nDie Anwesenheit der Geißel hat das Land geschwächt, <Volk>, und dies wiederum hat die wilden Götter geschwächt.\n\nWir wissen, dass die Drakkari dies ausnutzen und den Göttern Böses antun.\n\nIhr müsst die Sache für mich genauer untersuchen. Der Altar von Sseratus befindet sich am Ende der Allee gen Norden. Schleicht hinten herum und werft einen Blick in das Hauptaltargebäude.\n\nWas auch immer Ihr macht, meidet die Propheten um jeden Preis!", progress = nil, completion = "Tot?\n\n&lt;Die Stimmung des Verhexers wirkt sichtlich gedrückt, als Ihr ihm die Neuigkeiten bringt.&gt;\n\nSie haben Sseratus getötet und viel von seinem Mojo getrunken - der Prophet ganz besonders!\n\nWir müssen einen Weg finden, wie wir ihn beseitigen können, bevor er noch mehr und zu viel trinkt!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12507] = {title = "Seltsames Mojo", objective = "Liefert das seltsame Mojo bei Verhexer Ubungo in der Argentumwache ab.", description = "Diese Flasche mit seltsamem Mojo mag womöglich der Schlüssel dazu sein, herauszubekommen, was hier wirklich vor sich geht.\n\nVerhexer Ubungo, der Zandalaritroll bei der Argentumwache, wird vielleicht einen Blick darauf werfen wollen.", progress = "Was habt Ihr denn da?", completion = "Das ist das Mojo der Wildgötter, &lt;Klasse&gt;!\n\nDas ist nicht gut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12508] = {title = "Die Sache erledigen", objective = "Korporal Mala am Altar von Sseratus möchte, dass Ihr Champions von Sseratus, Priester von Sseratus oder Schlangenführer der Drakkari tötet - insgesamt jedoch 10.", description = "Ich habe Euer Gespräch mit dem Unteroffizier zufällig mit angehört. Das ändert jedoch nichts an der Tatsache, dass wir hier draußen noch immer einen Job zu erledigen haben.\n\nWenn Ihr schon mal dort draußen seid, denkt Ihr, dass Ihr uns dabei helfen könntet, einige dieser Anhänger von Sseratus von ihrem Leid zu befreien?", progress = nil, completion = "Danke, &lt;Klasse&gt;. Ich hätte es gehasst, gehen zu müssen, ohne erreicht zu haben, was wir hier draußen eigentlich erreichen wollten.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12509] = {title = "Trollpatrouille: Starker Magen", objective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr den Mut der kauernden Rekruten des Kreuzzugs wiederherstellt.", description = "Endlich trifft die Patrouille ein!\n\nSo sieht's aus, <Volk>. Wir haben in dieser Kampagne gerade einen Haufen unserer besten Soldaten verloren und mussten unsere Rekruten anfordern, um die Lücken zu schließen.\n\nWir haben gerade eine unserer härtesten Schlachten ausgefochten und viele unserer Rekruten waren einfach nicht bereit, diesem Feind gegenüberzutreten. Es kommen noch mehr Kämpfe auf uns zu und sie müssen bereit sein, Befehle zu befolgen.\n\nWenn es eine Sache gibt, die mir auf den Magen schlägt, dann ist das Feigheit. Vielleicht könnt Ihr ihnen helfen, den Mut zum Weitermachen zu finden.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Und keine Sekunde zu früh. Mir wurde berichtet, dass ein Gegenangriff kurz bevorsteht.\n\nMacht Euch auf den Weg. Der nächste Posten befindet sich im Nordosten in der Nähe des Kolosseums", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Rupert Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12510] = {title = "Kostbare elementare Flüssigkeiten", objective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr 3 kostbare elementare Flüssigkeiten beschafft.", description = "<Der Verhexer untersucht die Mojokaraffe.> Ich habe eine Idee, wie wir mit dem Propheten von Sseratus fertigwerden können. Doch zuerst werden wir dazu ein paar Dinge benötigen.\n\nDie Felder von Drak'Sotra befinden sich gleich im Süden. Aufgrund der Belastung, der das Land durch die Geißel und den Tod von Göttern ausgesetzt war, wurde die Barriere zwischen den Welten geschwächt und nun ergießt sich eine Flut von Elementaren über unsere Welt.\n\nWir benötigen die kostbaren Flüssigkeiten ihrer Fürsten. Fügt man nämlich drei Elementarglieder zusammen, entsteht daraus eine Verbindung zu ihrer Ebene, wodurch einer ihrer Fürsten heraufbeschworen werden kann.", progress = "Habt Ihr die kostbaren Flüssigkeiten dabei?", completion = "Ausgezeichnet. Werden die Flüssigkeiten mit dem Mojo kombiniert, vermindert sich dadurch dessen Effektivität, ohne dass es dabei völlig vernichtet wird.\n\nNun - eine Sache noch.", rewards = "Gewandung des BlutbindersStulpen des großen OpfersBrustplatte des AltarsStiefel des BlutvergießersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12511] = {title = "Die Hügel der bärigen Augen", objective = "Meldet Euch bei Leutnant Dumont bei der Ammertannhütte in den westlichen Grizzlyhügeln.", description = "Während wir in Wintergarde uns darauf konzentrieren, standzuhalten und der Entwicklung der Dinge an der Pforte des Zorns entgegenzublicken, kämpfen sich Bataillone von so weit her wie Westfall durch das Dickicht der Grizzlyhügel mit all seinen unfreundlichen Bewohnern. Ihr Unternehmen ruht auf der Hoffnung, eine alternative Route zur Eiskrone zu finden.\n\nDer bei der Ammertannhütte stationierte Leutnant Dumont hat die Hilfe fähiger Bürger in Anspruch genommen, die gewillt sind, Leib und Leben in der unerforschten Wildnis aufs Spiel zu setzen. Werdet Ihr Euch dieser Herausforderung stellen?", progress = nil, completion = "Ihr wärt beinah' abgeschossen worden, stimmt's? Wilde Monster - diese Horde.\n\nSie werden für ihre Taten bezahlen. Zumindest darauf könnt Ihr Euch verlassen, &lt;Klasse&gt;.\n\nNun ist es Zeit, dass Ihr Euch an die Arbeit macht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12512] = {title = "Lasst niemanden zurück", objective = "Dr. Rogers in Drak'Sotra möchte, dass Ihr Kreuzfahrer Lamoof, Kreuzfahrer Jonathan und Kreuzfahrerin Josephine findet. Legt ihnen dann die Verbände des Kreuzfahrers an und gebt ihnen so lange Geleitschutz, bis sie bei Dr. Rogers angelangt sind.", description = "Ahh, gut. Sie haben jemanden geschickt.\n\nHört zu, <Volk>. Wir brauchen hier Hilfe. Unsere Truppen wurden zurückgedrängt und wir haben Drak'Sotra an die Geißel verloren. Niemand weiß, woher sie kamen...\n\nDie Sache ist die, dass wir jeden verfügbaren Mann hier benötigen und dass einige unserer Besten noch nicht vom Schlachtfeld zurückgekehrt sind.\n\nIch möchte, dass Ihr jetzt, da die Kämpfe eingestellt wurden, die Ruinen aufsucht, dort nach unseren Verwundeten sucht, sie wieder zusammenflickt und anschließend hierher bringt.\n\nSucht Drak'Sotra ab! Sie können nicht weit sein.", progress = "Habt Ihr unsere Veteranen schon gerettet, <Name>?", completion = "Habt sie alle gerettet, oder? Außerordentlich!\n\nWürdet Ihr es womöglich in Erwägung ziehen, ein wenig hierzubleiben? Für so jemanden wie Euch hätten wir sicherlich Verwendung...", rewards = "Umhang des RettersBindung des RettersOpferungsarmschienen des VerteidigersSchädelkappe des VerheerersIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12513] = {title = "Netter Hut...", objective = "Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris.", description = "Mein Hut? Ja, er sieht von weitem etwas ungewöhnlich aus, ich weiß... nur wenige Schneider wissen, wie man sie anfertigt.\n\nAls ich noch jung und heißblütig war, galt er als eine Art Siegestrophäe. Viele kamen und wollten ihn mir streitig machen... doch niemand schaffte es.\n\nAch ja, lange ist's nun her. Doch heute bin ich ein alter Mann: Ich trinke, ich gehe fischen, doch ich duelliere mich nicht mehr.", progress = "Ich war unschlagbar, zu jener Zeit... stolz und das zurecht. Noch nie hat ein Herausforderer diesen großartigen Hut gewonnen... noch nie...", completion = "Mein... mein Hut! IHR wart das also. Hab' ich's mir doch gedacht. Die alten Narben fingen wieder an wehzutun, als Ihr näherkamt - doch... so jung?! Ihr habt Euch kein Bisschen verändert!\n\nNun... jetzt wisst Ihr also mein Geheimnis. Ich WURDE besiegt... ein einziges Mal. Ihr habt ihn mehr als nur verdient.", rewards = "Ihr bekommt:\n\nBreitkrempiger Haliskanhut"}
MultiLanguageQuestData['de'][12514] = {title = "Pilzemixer", objective = "Sammelt 10 Krauskappenfungi und bringt sie zu Verhexer Ubungo in der Argentumwache.", description = "Was wir nun brauchen, ist etwas, um das Mojo stärker zu machen - etwas, das bewirkt, dass der Prophet an Macht verliert, sobald er es trinkt.\n\nDrak'Agal liegt gen Osten. Dort gibt es auch einen Pilz, den die Einheimischen Krauskappenfungus nennen. Ich denke, das ist genau das, was wir brauchen.\n\nSammelt eine gehörige Menge und bringt sie hierher zurück. Wenn wir sie mit dem Mojo vermischen, dann wird das diejenigen, die es trinken, in Verwirrung bringen.", progress = "Habt Ihr alle Fungi mitgebracht?\n\nOh und hütet Euch vor den Basilisken, die dort drüben umherstreifen.", completion = "&lt;Der Verhexer nickt zustimmend.&gt;\n\nGebt mir den Fungus und ich werde ihn mit dem Mojo und den Flüssigkeiten der Elementarfürsten vermischen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12515] = {title = "Netter Hut...", objective = "Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris.", description = "Mein Hut? Ja, er sieht von weitem etwas ungewöhnlich aus, ich weiß... nur wenige Schneider wissen, wie man sie anfertigt.\n\nAls ich noch jung und heißblütig war, galt er als eine Art Siegestrophäe. Viele kamen und wollten ihn mir streitig machen... doch niemand schaffte es.\n\nAch ja, lange ist's nun her. Doch heute bin ich ein alter Mann: Ich trinke, ich gehe fischen, doch ich duelliere mich nicht mehr.", progress = "Ich war unschlagbar, zu jener Zeit... stolz und das zurecht. Noch nie hat ein Herausforderer diesen großartigen Hut gewonnen... noch nie...", completion = "Mein... mein Hut! IHR wart das also. Hab' ich's mir doch gedacht. Die alten Narben fingen wieder an wehzutun, als Ihr näherkamt - doch... so jung?! Ihr habt Euch kein Bisschen verändert!\n\nNun... jetzt wisst Ihr also mein Geheimnis. Ich WURDE besiegt... ein einziges Mal. Ihr habt ihn mehr als nur verdient.", rewards = "Ihr bekommt:\n\nBreitkrempiger Haliskanhut"}
MultiLanguageQuestData['de'][12516] = {title = "Zu viel des Guten", objective = "Erschlagt den verworrenen Propheten von Sseratus und kehrt anschließend zu Verhexer Ubungo in der Argentumwache zurück.", description = "Hier - habe das Mojo modifiziert. Wenn der Prophet es nun trinkt, wird er nicht nur ein wenig seiner Macht verlieren, nein, auch sein Geist wird von den Effekten des Pilzes verwirrt sein.\n\nDas ist zumindest der Gedanke bei der Sache.\n\nDamit er es trinkt, würde ich vorschlagen, dass Ihr es ihm einfach zuwerft. Wenn ich nur daran denke, wie arrogant er beim Altar gewirkt hat, dann würde ich behaupten, dass er es auf jeden Fall fangen und trinken wird.\n\nWenn Ihr ihn nicht tötet, <Klasse>, dann wird Euer Argentumkreuzzug ein schreckliches Ende nehmen.", progress = nil, completion = "Erstaunlich! Ihr habt Eure Leute und den Rest von Nordend vor seinem Wahnsinn gerettet.\n\nUnglücklicherweise wird in den höher gelegenen Bereichen von Zul'Drak noch mehr dieses Wahnsinns betrieben.", rewards = "Gewand des SterndeutersBindungen des BlutbindersMessingschulterpolster des AngreifersGeschmeidige HandgelenksschützerIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12517] = {title = "Schurkenkartenset", objective = "Beschwört mithilfe des Schurkenkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", description = "Jetzt, da Ihr alle Schurkenkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Schurkenkartenset zu sammeln! Ich bin beeindruckt.", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", rewards = "DunkelmondrobeDunkelmondkettenhemdDunkelmondweste"}
MultiLanguageQuestData['de'][12518] = {title = "Magierkartenset", objective = "Beschwört mithilfe des Magierkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", description = "Jetzt, da Ihr alle Magierkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Magierkartenset! Glückwunsch!", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHalskette des Dunkelmond-JahrmarktsAnhänger des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][12519] = {title = "Trollpatrouille: Was wollt Ihr - 'ne Medaille?", objective = "Hauptmann Grondel vor dem Kolosseum möchte, dass Ihr 7 Medaillons der Drakkari von den Drakkarileichen in der Nähe beschafft.", description = "Seht mich an, <Volk>. Sehe ich so aus, als hätte ich Zeit dafür, Berichte auszufüllen?\n\nIch hab alle Hände voll zu tun, den Posten hier von der Geißel freizuhalten, und sie wollen, dass ich mich mit Papierkram rumschlage!\n\n<seufz> Hat keinen Zweck, sich aufzuregen. Ich muss dem Kommandanten eine Liste aller Feinde besorgen, die wir in unserem letzten Gefecht getötet haben.\n\nWollt Ihr hilfreich sein? Geht und beschafft mir alle Medaillen, die Ihr bei den toten Trollen hier in der Gegend finden könnt. Das muss reichen.", progress = "Habt Ihr mir die Medaillen gebracht, <Volk>?", completion = "Jetzt aber!\n\nIhr habt mir ein gutes Stück Arbeit erspart, Junge. Ich bin dankbar. Ich werde Euch auf jeden Fall in meinem Bericht erwähnen.\n\nFort mit Euch. Finkelstein wird wahrscheinlich ein Stück weiter im Westen auf Euch warten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Grondel Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12520] = {title = "Meister der Rhinozerosjagd: Die Prüfung", objective = "Tötet 15 Splitterhornrhinozerosse und kehrt anschließend zu Hemet Nesingwary in Nesingwarys Basislager zurück.", description = "Keine unsanfte Landung kann den alten Hemet davon abhalten, Herr über das größte Wild zu werden, welches das Sholazarbecken zu bieten hat. In der Wildnis nordwestlich des Lagers regieren die gewaltigen Splitterhornrhinozerosse über den Dschungel. Ihr könnt der Expedition beweisen, was Ihr wert seid, <Junge/Mädel>, indem Ihr mir beweist, dass Ihr hart genug seid, diesen mächtigen Bestien entgegenzutreten.", progress = nil, completion = "Gut, gut, sieht so aus, als hättet Ihr die Rhinozerosse letztendlich doch überlebt und zwar in guter Verfassung, wenn ich das so sagen darf. Doch zur Rhinozerosjagd gehört mehr, als die Bestie nur anzustarren, während sie auf Euch zustürmt, in der Hoffnung, dass Ihr auch richtig zielt. Nein, Ihr braucht mehr als nur das, um Euch ihrem Patriarchen zu stellen, der den Gerüchten nach im Dschungel lebt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12521] = {title = "Wo in aller Welt ist Hemet Nesingwary?", objective = "Sprecht mit Erzmagier Pentarus, wenn Ihr bereit seid, zum Sholazarbecken zu reisen. Sprecht mit Monti Maulschuss im Wildwuchsmangal, sobald Ihr im Sholazarbecken angekommen seid.", description = "Als ich hörte, dass der sagenumwobene Hemet Nesingwary in See stach und sich auf den Weg in Richtung Sholazarbecken machte, bot ich mich an, um ihm bei der Finanzierung seiner Expedition zu helfen. Wir wussten nur wenig über Sholazar, doch man sagt, dass es ein üppiges Paradies in der Mitte des gefrorenen Kontinents sei.\n\nHemet war damit einverstanden, Proben exotischer Pflanzen, Reagenzien und Kristalle zurückzuschicken. Wir haben noch keine Nachrichten von ihm erhalten. Monti Maulschuss sollte ihnen Vorräte bringen, doch auch er ist nicht zurückgekehrt. Falls Ihr Euch die Sache einmal genauer ansehen wollt, dann werde ich Euch meine Flugmaschine zur Verfügung stellen.", progress = nil, completion = "Ja, Hemet ist hier - er ist im Lager. Geht einfach nach Nordwesten in Richtung Fluss und Ihr werdet ihn schon bald sehen. Und bei der Liebe des Lichts, mein Junge, sorgt dafür, dass er jemanden schickt, um mich hier runterzuschneiden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12522] = {title = "Brauch 'nen Motor, hol 'nen Motor", objective = "Weslex Schnellzang in Nesingwarys Basislager möchte, dass Ihr ihm den Motor einer Flugmaschine bringt.", description = "Sie ist ruiniert... ruiniert! Ich habe der Kapitänin noch gesagt, sie soll mit solch wertvoller Fracht vorsichtig umgehen, aber hört sie schon auf mich? Nein!\n\nAls das Schiff auf Grund lief, ging meine Flugmaschine kaputt, die Geist von Gnomeregan. Nun haben wir keine Möglichkeit mehr, Bericht zu erstatten!\n\nAllerdings könnte es sein, dass die lächerliche Venture Company durch den Abschuss einer weiteren Flugmaschine etwas zu unseren Gunsten getan hat. Sie haben sie dort abgeschossen, wo Monti in die östlichen Sümpfe abgesprungen ist. Sucht die Stelle und bergt den Motor. Er ist vielleicht unsere letzte Hoffnung.", progress = "Nun, konntet Ihr den Motor bergen? Ich weiß nur, dass der Erzmagier, der diese Expedition finanziert, langsam nervös wird.", completion = "Da... setzt ihn einfach da ab. Vorsichtig! Wenn Ihr den auch noch ruiniert, stecken wir in großen Schwierigkeiten! Nun lasst mal sehen, was ich tun kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12523] = {title = "Hast ein Teil, dann gib ein Teil", objective = "Bringt 7 Ersatzteile der Venture Co. zu Weslex Schnellzang in Nesingwarys Basislager.", description = "Großartig! Nun, da wir einen Motor haben, benötigen wir eine Auswahl an anderen Teilen, um die Maschine wieder flugtauglich zu machen. Keine Sorge, ich weiß, was ich tue.\n\nEin guter Mechaniker kann mit allem seine Werke zusammenhalten, aber hoffen wir mal, dass es nicht so weit kommt.\n\nJedenfalls haben diese Dummköpfe der Venture Company einen ganzen Haufen an Ersatzteilen für ihre Minenausrüstung überall in Schwindelgrins' Grabungsstätte herumliegen, auf der anderen Seite dieser gelben Kristallsäule im Nordosten. Sammelt ein paar auf und bringt sie hierher zurück.", progress = "Habt Ihr diese Teile bekommen?", completion = "Mit ein bisschen Arbeit sollte es funktionieren. Meine arme Flugmaschine sieht am Ende aber wohl eher aus wie ein Schredder der Venture Company. Das arme Mädchen muss warten, bis wir zurück in Dalaran sind, um ihre richtige Form wiederzukriegen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTeach River's Heart Taxi Path\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12524] = {title = "Missgeschick der Venture Co.", objective = "Debaar in Nesingwarys Basislager möchte, dass Ihr 15 Mitglieder der Venture Company tötet. Ihr könnt entweder Grobiane der Venture Co. oder Ausgräber der Venture Co. töten.", description = "Seitdem wir hier sind, hat uns die Venture Company beim Versuch gestört, unsere Lagerstätte zu sichern und die Gegend auszukundschaften. Normalerweise wäre es uns egal, was sie machen, doch sie haben damit begonnen, sich unsere Späher zum Feind zu machen und unsere Versorgungsflieger vom Himmel zu holen.\n\nWir können diese Beleidigung nicht weiter zulassen. Hemet Nesingwarys Expedition ist hierhergekommen, um zu jagen, und jagen wird sie auch.\n\nGeht zu Schwindelgrins' Grabungsstätte auf der anderen Seite der Kristallsäule gen Nordosten und tötet jeden Angestellten der Venture Company, der Euch über den Weg läuft!", progress = nil, completion = "Das sollte ihre Operationen ins Stocken bringen, doch ich mache mir darüber sorgen, dass der Vorarbeiter versuchen wird, mehr Arbeiter herbeizuschaffen. Wir müssen die Sache zu Ende bringen, solange wir noch können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12525] = {title = "Wischt ihm das Grinsen vom Gesicht", objective = "Tötet Großknecht Schwindelgrins und Fleischklops und kehrt danach zu Debaar in Nesingwarys Basislager zurück.", description = "Großknecht Schwindelgrins muss seine Koffer packen, wenn wir seine Mine endgültig schließen wollen, aber seid auf der Hut. Sein Leibwächter Fleischklops ist ein großer, fieser Oger und wird Euch nicht kampflos zum Großknecht lassen.\n\nDie beiden halten sich vermutlich auf einer Plattform auf, von der aus sie Überblick über die gesamte Operation der Venture Company in Schwindelgrins' Grabungsstätte haben.\n\nDenkt daran, die Grabungsstätte ist auf der anderen Seite der Sonnenstrahlsäule im Nordosten. Viel Glück, <Name>.", progress = nil, completion = "Es tut gut zu hören, dass die Venture Company uns keinen Ärger mehr bereiten wird. Ihr habt meinen und Hemets Dank, dass Ihr Euch dieses Problems angenommen habt. Ein Großwildjäger kann nicht guten Gewissens die Waffe gegen eine andere Person erheben.", rewards = "Ogerzerschmetternde HandgelenksschützerArmschienen des auflebenden WaldesHassverbundene ArmschienenStreunende HandgelenksschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12526] = {title = "Beherrschen der Rhinozerosjagd: Die Verfolgung", objective = "Sprecht mit Orakel Soo-rahm bei den Knochen von Nozronn.", description = "Gut, dann ist das geklärt. Wir suchen diesen eingeborenen Weisen und wechseln ein paar Worte mit ihm. Er wird uns seine Dienste jedoch nicht freiwillig anbieten.\n\nMir wurde erzählt, dass er einen kleinen Unterstand nahe der Knochen von Nozronn besitzt, gleich auf der anderen Seite des Flusses im Süden. Sucht ihn auf, stellt Euch vor und fragt, was er dafür benötigt, um uns beim Aufspüren des Rhinozerospatriarchen zu helfen.", progress = nil, completion = "Was führt Euch zu Rahms Schrein?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12527] = {title = "Gefräßige Lauerer", objective = "Bringt 5 Basiliskenkristalle zu Alchemist Finkelstein im Schrein in Heb'Valok.", description = "Finkelstein, mein Meister, befindet sich im Schrein in Heb'Valok gen Nordwesten und stellt dort ein Wahrheitsserum her. Doch um dies zu tun, benötigt er etliche Basiliskenkristalle. Heb'Valok befindet sich westlich der Straße in Richtung Norden und vor dem Altar von Sseratus.\n\nÖstlich von Drak'Agal gibt es lauernde Basilisken.\n\nSchnappt Euch ein paar Ratten von Zul'Drak und werft sie den Basilisken zum Fraß vor. Sobald sie fünf von ihnen gegessen haben, sind sie für gewöhnlich vollgefressen und lassen dann mit sich alles machen, sodass Ihr gefahrlos an ihre Kristalle herankommen könnt.\n\nDie Basilisken zu töten, würde Euch nichts bringen... dadurch würdet Ihr nur ihre Kristalle zerbrechen!", progress = "Was soll das?\n\nHabt Ihr vielleicht zufällig meinen nichtsnutzigen Lehrling Stößelpot gesehen?\n\nIch habe ihn vor längerer Zeit losgeschickt, um etwas für mich zu besorgen, und er ist noch immer nicht zurückgekehrt!", completion = "Oh, wie ausgezeichnet! Ich danke Euch. Die Kristalle scheinen in einem ausgezeichneten Zustand zu sein!\n\nStößelpot hat Euch bestimmt dazu angestiftet, seine lästigen Aufgaben für ihn zu erledigen. Nichtsdestotrotz: Eure Unterstützung in dieser Sache wird sehr geschätzt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12528] = {title = "Gute Miene zum bösen Spiel", objective = "Meldet Euch beim Hochschamanen Rakjak auf dem Hügel der Wildherzen und stellt Euch als neuer \"Sklave\" vor.", description = "Meine Beute! Du nehmen meine Beute!\n\n<Gekgek verhöhnt Euch mit seinem Speer.>\n\nDu bist so dumm, <Volk>. Nun du was schulden Gekgek! Du Wildherzensklave sein. Du erschlagen noch viel mehr Bestien für Wildherzen.\n\nDu gehst zu Hügel der Wildherzen in den Nordosten - Du sagst Hochschamanen Rakjak, du neuer Sklave.\n\nGeh, <Volk>! Geh oder ich schleuder dich Purschen zu Poden!\n\n<Gekgek schüttelt drohend seinen Speer.>", progress = nil, completion = "Du neuer Sklave?\n\nGut. Sie geh'n uns langsam aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12529] = {title = "Der Sklave der Affenjäger", objective = "Tötet für Hochschamanen Rakjak in den Hügeln der Wildherzen 8 Hartknöchelfutterwühler und 6 Hartknöchelstürmer.\n\nSprecht mit dem Ältesten Harkek im Hügel der Wildherzen, falls Ihr Goregeks Fesseln verlieren solltet.", description = "Du denkst, du ein so großer Jäger, hm? Du kein Wildherz, du nichts wissen über Jagd.\n\nGoregek ist großer Affenjäger. Er töten so viele Affen, du kannst gar nicht an Krallen abzählen.\n\nDu gehst mit Goregek und jagst Hartknöchel im Osten. Du der Sklave, <Volk>. Du machst, was Goregek dir sagen.", progress = nil, completion = "Dummer &lt;Volk&gt;, Goregek zeigen Sklave, wie es gemacht wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12530] = {title = "Knöchelchen schikanieren", objective = "Goregek hat Euch einen Knöchelchenpiekser gegeben, den Ihr auf die kleinen Knöchelchen anwenden sollt, um so die Hartknöchelmatriarchin aus ihrem Versteck zu locken. Tötet die Hartknöchelmatriarchin und erstattet anschließend dem Hochschamanen Rakjak auf dem Hügel der Wildherzen Bericht.\n\nSolltet Ihr Goregeks Fesseln verlieren, sprecht mit dem Ältesten Harkek vom Hügel der Wildherzen.", description = "He, Sklavendings!\n\nRakjak wollen, dass ich Babysitter spielen für dich, während ich Hartknöchel umhau. Ich heute sein großzügig, deshalb du darfst auch ein paar umhauen, aber du Goregek nicht im Weg stehen!\n\nRakjak noch nicht wissen, aber Goregek hat ein Auge auf große, fiese Mama von Hartknöchel geworfen. Wir losziehen und gehen zu Lichtung der Hartknöchel im Osten, pieksen ein paar kleine Knöchelchen mit dem Piekser und schwups, sie kommen rausgeschossen!\n\n<Goregek reibt sich vergnügt die Hände.>", progress = nil, completion = "Goregek Euch mitgenommen hat, um große Mama von Hartknöchel umzuhauen, ja? Du seien Glückspilz!\n\nBlöde Knöchelchen gut quieken!\n\n&lt;Rakjak quiekt laut und bricht in Gelächter aus.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12531] = {title = "Bedrohung aus dem Untergrund", objective = "Findet Serfex unter dem Sand des südlichen Flusses, tötet ihn und bringt seine Klaue zu Hochschamane Rakjak auf dem Hügel der Wildherzen.\n\nWenn Ihr Dajiks gebrauchte Kreide verliert, sprecht mit Ältesten Harkek auf dem Hügel der Wildherzen.", description = "Messerkiefertöter, Hühnerjäger, neuer Wildherzsklave...\n\nIch weiß, du nicht willst Sklave bleiben, also ich sag dir, was zu tun. Zeig, du besser als andere Wildherzjäger und dann Rakjak dich respektiert.\n\nUnter Sand von südlichem Fluss gibt es Tier, das Wespen, Hartknöchels und sogar Wolvar tötet. Er heißt Serfex. Du bringst Klaue von Serfex zu Rakjak und vielleicht er dich aus Sklaverei entlässt.\n\nHoffe, Dajik dich gut unterrichtet, damit Serfex leichter Kram wird.", progress = "Ich nicht nach dir gefragt, <Volk>. Was du willst?", completion = "Du tötest Serfex? Ich wette, du mächtigem Wolvar gefolgt, der Serfex getötet, und Klaue genommen.\n\nJetzt meine Klaue.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12532] = {title = "Aus dem Staub gemacht!", objective = "Fangt für den Ältesten Harkek 12 entflohene Hühner.\n\nSolltet Ihr Dajiks gebrauchte Kreide verlieren, sprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen.", description = "Dummer Goregek ins Hühnerhaus gestolpert und alle Hühner hat rausgelassen!\n\nSie überall um den Hügel herum sein - na los, du holen Hühner zurück!\n\n<Der Älteste Harkek scheucht Euch mit einer Handbewegung davon.>", progress = "Hühner gefangen?", completion = "Gut! Ich mir schon Sorgen gemacht haben wegen Essen. Ich schon ziemlichen Hunger haben.\n\nDanke, &lt;Volk&gt;.", rewards = "Fleckiger StallwärmerEierwärmerstiefelStrohgamaschenGesprungener NestverstärkerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12533] = {title = "Der Lehrling des Wespenjägers", objective = "Tötet für Hochschamanen Rakjak auf dem Hügel der Wildherzen 6 Saphirblaue Schwarmwespen und 9 Saphirblaue Schwarmdrohnen.\n\nSprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen, falls Ihr Dajiks gebrauchte Kreide verlieren solltet.", description = "Rakjak nicht dumm. Du vielleicht gut im Töten. Vielleicht Wildherzen dich können machen zu echten Jäger.\n\nDajik jagt Riesenwespen besser als alle anderen Wolvar. Geh mit Dajik zum Saphirschwarm im Südosten oder zum Fluss im Süden und lern das Jagen.", progress = nil, completion = "Wir töten viele, viele Wespen.\n\nRakjak nicht denken, dass es mal keine geben wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12534] = {title = "Die Saphirkönigin", objective = "Bringt den Stachel der Saphirkönigin zu Hochschamane Rakjak auf dem Hügel der Wildherzen.\n\nWenn Ihr Dajiks gebrauchte Kreide verliert, wendet Euch an Ältesten Harkek auf dem Hügel der Wildherzen.", description = "Hartknöchels können gefährlich sein, aber die meisten halten sich fern von Wolvar. Wespen allerdings nicht fürchten Wildherzen... sie sogar manche unserer Jäger töten.\n\nIch weiß, Rakjak möchte Wespenkönigin tot haben, aber kein Wolvar will in ihren Schwarm hineingehen. Du gehst und tötest Königin im Saphirschwarm im Südosten und holst Stachel für Rakjak. Ich wette, Rakjak mag das.", progress = "Du riechst wie Wespendinger.", completion = "Du Wespenkönigin getötet! Du stärker, als Rakjak dachte.\n\nVielleicht Wespen gehen jetzt weg und hören auf, Jäger der Wildherzen anzugreifen.", rewards = "Chitinverstärkte KapuzeStachelsicherer BrustschutzGesichtsschutz mit InsektengitterKäferquetschende SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12535] = {title = "Unfug im Gange", objective = "Hochschamane Rakjak auf dem Hügel der Wildherzen möchte, dass Ihr ihm 8 Himmelszeltkristallformationen bringt.", description = "Du guter Jäger, doch Wildherzen dich können stärker machen. Harkek denken, du vielleicht bereit für etwas Wichtigeres.\n\nBevor Rakjak dich auf wichtige Mission schicken, du Sachen für Rakjak sammeln müssen. Überall im Süden am Fluss entlang sind blaue Kristalle. Rakjak braucht viele blaue Kristalle.\n\nDu gehst und holst Kristalle jetzt.", progress = "Fast bereit für lange Reise. Gekgek gerade kommen zurück mit Krokilisken.", completion = "Guter &lt;Volk&gt;! Okay, alles bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12536] = {title = "Ein holpriger Ritt", objective = "Reitet auf dem gefangenen Krokilisken zur Zuflucht der Nebelflüsterer und fragt Zepik nach weiteren Anweisungen.\n\nSprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen, falls Ihr Zepiks Jagdhorn verlieren solltet.", description = "Zepik ist bester Jäger von Wildherzen. Zepik jagt Großzungen... hässliche Dinger in der Nähe von Sumpf, die alles stehlen wollen, was sie können finden.\n\nZepik gehen auf lange Wanderung, um Schrein von Großzungen kaputt zu machen und zu versuchen, sie zu verscheuchen. Wir wollen keine Großzungen in diesem Land mehr.\n\nAn Nordostseite von Hügel sind Krokilisken angekettet, neben Baum. Geh mit Zepik und mach, was Zepik dir sagen.", progress = "Man Zepik gesagt haben, dass du guter Jäger, obwohl du nicht von Wildherzen.", completion = "Wir sind hier! Wir schnell handeln müssen.\n\nPass auf Großzungen auf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12537] = {title = "Der Blitz schlägt immer zwei Mal ein", objective = "Zepik möchte, dass Ihr vor dem Wetterschrein der Nebelflüsterer die Himmelszeltkristallformation zertrümmert.\n\nFalls Ihr Zepiks Jagdhorn verlieren solltet, dann sprecht mit dem Ältesten Harkek auf den Hügeln der Wildherzen.", description = "Okay, die Kristalldinger...\n\nDie Großzungen benutzen Kristalle, um Regenschreine mit Energie zu versorgen. Zepik nicht ganz wissen, wie es funktioniert, doch Zepik wissen, dass wenn sie falsche Kristalle benutzen, dann Wolken und Regen verrückt spielen!\n\nZepik versucht hat, sich in so einen Regenschrein einzuschleichen, doch es nicht so gut gelaufen. Es auf jeden Fall besser laufen, wenn zu zweit!\n\nDu nehmen Kristalle, sie dann stellen auf großes Steinsäuleschreinding und sie zerschlagen, um Energie rauszulassen. Zepik nicht so sicher, was wird passieren, du also besser einen Schritt zurück machen, nachdem du Kristalle kaputt gemacht hast.", progress = nil, completion = "Es so gut funktioniert!\n\nIhr gesehen, wie Blitz den Orakeltypen fertig gemacht hat? So gut!\n\n&lt;Zepik reibt sich die Hände und kichert irre.&gt;", rewards = "Handschuhe des knisternden SturmsStatikzerstreuende SchulterpolsterGürtel des eingefangenen BlitzschlagsZepiks geerdete BeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12538] = {title = "Der Nebel hört nicht zu", objective = "Zepik möchte, dass Ihr 12 Gorlocs der Nebelflüsterer tötet.\n\nSprecht mit dem Ältesten Harkek vom Hügel der Wildherzen, falls Ihr Zepiks Jagdhorn verlieren solltet.", description = "Gorillas und Wespen sind langweilig! Großzungen sind das einzige, wo die Jagd wirklich Spaß macht.\n\nWenn wir Chaos im Regenschrein anrichten, töten wir auch jede Menge Nebelgroßzungen. Das wird sie lehren, nicht zum Dorfdings zurückzukommen.\n\n<Zepik nickt voller Zuversicht.>", progress = nil, completion = "Ich schlitze Großzungen richtig gut auf.\n\nIhr habt gute Arbeit gemacht, wie's aussieht.\n\nNein, ich mach nur Scherz! Ihr guter Jäger. Ich froh, mit Euch zu jagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12539] = {title = "Und raus hier", objective = "Sucht den Weg zurück zum Hügel der Wildherzen und sprecht mit Hochschamane Rakjak.", description = "In Ordnung, wir fertig! Zeit für Rückweg. Dieses Mal aber kein Krokilisk zum Reiten.\n\nWenn wir uns nach Osten wenden und in Nähe des Grats halten, sollte es uns zurückführen den ganzen Weg entlang der Hügel.\n\nMüssen aufpassen, uns nicht zu weit vom Grat zu entfernen, oder wir vielleicht ins Baumdorfding der Großzungen geraten. Zepik nicht denkt, sie uns gerade mögen.", progress = nil, completion = "Von Blitz getroffen?\n\n&lt;Rakjak bricht einen Moment lang in Lachen aus.&gt;\n\nDu guter Jäger. Rakjak dich mögen. Vielleicht eines Tages du kannst Ehren-Wildherz sein!\n\nAber nur vielleicht!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Remove Retainer Items\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12540] = {title = "Tu nur meine Pflicht", objective = "Sucht für Hochschamanen Rakjak auf dem Hügel der Wildherzen ein verletztes Orakel der Regenrufer.", description = "Gut, <Kumpel/Dame>, Rakjak hat weitere wichtige Aufgabe. Du gehst verletzte Großzunge fangen, die Fährtenleser am Fluss im Norden ausgemacht.\n\nDieses Mal nicht bringst Jäger, weil sie vielleicht einfach töten wollen. Ich möchte es verstecken, damit ich es pieksen können und machen, dass es mir Dinge sagen.\n\nGeh und bring mir Großzungenpreisding.", progress = nil, completion = "Nicht mich töten, bitte! Wir nur nach Fisch gesucht! Wir nicht wollen sterben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Set Oracle Friendly\n\nIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12541] = {title = "Trollpatrouille: Der Lehrling des Alchemisten", objective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hierher geschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, <Volk>. Und merkt Euch: Timing ist alles!", progress = "Seht Ihr, <Name>, wahre Alchemie ist mehr, als nur ein paar Zutaten zusammenzumischen...", completion = "Ihr habt es geschafft!\n\nDie Informationen, die wir von diesem Troll bekommen haben, werden mit Sicherheit von großem Wert sein. Ich werde das, was Ihr geleistet habt, auf jeden Fall in meinem Bericht an den Hauptmann erwähnen.\n\nHabt Dank, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlchemist Finklestein Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12542] = {title = "Der Ruf des Kreuzzugs", objective = "Meldet Euch bei Kreuzritter Valus in der Lichtwarte in der Drachenöde.", description = "<Klasse>! Der Argentumkreuzzug sucht nach fähigen Soldaten, die gewillt sind, ihre Differenzen beiseite zu legen und gemeinsam gegen die Streitkräfte des Lichkönigs in den Krieg zu ziehen. Werdet Ihr für unsere Sache kämpfen?\n\nGeht nach Norden zur Lichtwarte, falls Ihr Interesse haben solltet, und sprecht mit Kreuzritter Valus.\n\nDie Warte befindet sich inmitten der Ruinen der gebrandschatzten Trollstadt von Jintha'kalar an der Grenze zu Zul'Drak.\n\nLebt wohl.", progress = nil, completion = "Das Reich der Drakkari befindet sich nur ein paar Schritt weit entfernt.\n\n&lt;Valus deutet nach Osten.&gt;\n\nÜber Tausende Jahre hinweg hielten sich die Drakkari vom Rest der Welt fern und zogen es vor, innerhalb der Grenzen ihrer riesigen Tempelstädte und Ziggurats zu bleiben. Angesichts dessen war es überraschend, auf diese Trümmer hier zu stoßen. Etwas höher, jenseits der Treppen, die Nach Zul'Drak führen und von denen eine drohende Gefahr ausgeht, befinden sich die Ruinen der Feste Drak'Tharon. Der gesamte erste Ring von Zul'Drak ist zerstört...\n\nWieso greift die Geißel erst jetzt an?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12543] = {title = "Eine Opfergabe für Soo-rahm", objective = "Bringt dem Orakel Soo-rahm in der Nähe der Knochen von Nozronn 5 Intakte Kobragiftzähne.", description = "Wir nicht kennen Euch, <Fremder/Fremde>, aber wir wissen, Ihr wollt etwas.\n\nWir sprechen mit Knochen von Nozronn für Euch, aber Ihr müsst bringen Opfergaben für uns. Wir brauchen mächtige Kaiserkobragiftzähne, um unsere Orakelhalskette fertig zu stellen.\n\nIhr geht zum Wildwuchsmangal, nordöstlich unserer Hütte, findet Kobras und bringt beste Giftzähne wieder. Dann wir bringen Knochen zum Sprechen für Euch.", progress = "Wir müssen wissen, bringt Ihr Giftzähne?", completion = "&lt;Das Orakel inspiziert die Giftzähne.&gt;\n\nWir gutheißen! Knochen von Nozronn werden mit &lt;Name&gt; sprechen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12544] = {title = "Die Knochen von Nozronn", objective = "Benutzt Soo-rahms Weihrauch in der Nähe der Knochen von Nozronn, kehrt dann mit den Informationen, die Ihr in Erfahrung gebracht habt, zu Hemet Nesingwary in Nesingwarys Basislager zurück.", description = "Knochen von Nozronn, Orakel Soo-rahm schickt <Name> zu Euch!\n\nWir haben Weihrauch für Euch vorbereitet. Zündet es an und platziert es neben Nozronns Kopf und Ihr werdet seine Stimme hören.\n\n<Verwirrt weist Ihr Soo-rahm darauf hin, dass Ihr ihm bisher noch nicht einmal Eure Frage genannt habt.>\n\nStimmt, wir nicht wissen, aber mächtiger Nozronn kennt sie. Zweifelt nicht. Nozronn wird Frage beantworten, die Euch auf dem Herzen liegt.\n\nGeht. Nozronn nicht warten.", progress = nil, completion = "&lt;Hemet hört zu, während Ihr beschreibt, was Ihr in Erfahrung gebracht habt.&gt;\n\nWeiter so, Junge. Kein totes Rhinozeros wird Hemet Nesingwary erzählen, wo und was er jagen darf. Wir werden es diesem Knochenhaufen zeigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12545] = {title = "Die Säuberung von Jintha'kalar", objective = "Kreuzritter Valus bei der Lichtwarte in der Drachenöde möchte, dass Ihr 15 Anhänger der Geißel von Jintha'kalar tötet.", description = "Wir mussten diesen uralten Drakkaritempel einem ganzen Schwarm von einmarschierenden Dienern der Geißel abringen. Nur etwa einhundert Schritt von uns entfernt befindet sich die in Ruinen liegende Stadt von Jintha'kalar. Dort laufen Totenbeschwörer der Geißel Amok und verwandeln die verbliebenen lebenden Drakkaritrolle in Diener des Lichkönigs.\n\nFür das Licht sind sie alle verloren. Sie müssen alle beseitigt werden.\n\n<Valus sieht Euch streng an.>\n\nAlle.", progress = "Lasst nichts zurück, was der Lichkönig wiederbeleben könnte!", completion = "Wie Ihr sehen könnt, befindet sich die Kriegsmaschinerie der Geißel auf dem Vormarsch, und trotzdem sind die Armeen der Allianz und Horde gespalten, was sie zu leichter Beute macht. Aus diesem Grund müssen wir zusammenhalten.\n\n&lt;Valus wirkt einen Moment lang gedankenverloren.&gt;\n\nDer Argentumkreuzzug hat Verwendung für einen Mann wie Euch. Wäret Ihr womöglich daran interessiert, Euch unserer Sache zu widmen und Seite an Seite mit dem Aschenbringer in die Schlacht zu ziehen?", rewards = "Klaue des untoten VerheerersKlinge des GeißeltötersGelenkspalterschnellklingeZauberstab des blendenden LichtsZauberstab des reinigenden FeuersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12546] = {title = "Wiedergewinnung", objective = "Geht zur Lawine im Sholazarbecken und verwendet die Omegarune, um den Etymidian zu aktivieren. Tötet mit ihm 200 Diener der Geißel, Bythius den Fleischformer, Urgreth von den Tausend Gräbern und Hagel'skorn.\n\nSprecht mit dem Avatar von Freya im Sholazarbecken, sobald Ihr diese Aufgabe abgeschlossen habt.", description = "Es ist soweit, <Name>. Der Etymidian ist eine der zerstörerischsten Kräfte, die jemals von den Titanen erschaffen wurden, und ich lasse ihn nur ungern auf meine Lande los.\n\nDoch habe ich keine Wahl. Unsere Feinde zwingen mich dazu und der Zorn der Titanen wird alle vernichten.", progress = "Die, die das Leben bedrohen... habt Ihr Euch um sie gekümmert?", completion = "Ich bin dankbar für Eure Hilfe, &lt;Name&gt;. Es ist meine Pflicht, über diese Lande und alles Leben in ihnen zu wachen.\n\nDank Euch wird dieses Leben weiter bestehen, um aufzublühen, während die Streitkräfte des Todes in den Grenzregionen Krieg führen.\n\nEure Taten werden niemals vergessen werden.", rewards = "Starren des strafenden KonstruktsHelm des rächenden BeschützersKopfschutz der gewaltigen ZerstörungHelm der überragenden WutGroßhelm des TitanenprotektoratsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12547] = {title = "Die Aktivierungsrune", objective = "Besorgt die Omegarune von der Terrasse des Formers und bringt sie zu Etymidian.", description = "Dieses kolossale Wesen scheint nicht aktiviert zu sein. Ihr bemerkt auf der Brust einen leeren Spalt in Runenform.\n\nVielleicht gelingt es Euch, die fehlende Rune im nahegelegenen Aussichtspunkt zu finden.", progress = "<Der runenförmige Spalt auf der Brust des Etymidians scheint mit einer schwachen Energie zu leuchten.>", completion = "&lt;Ihr hört das polternde Geräusch von reibendem Stein, während Etymidians Gliedmaßen mit Leben durchströmt werden.&gt;\n\nIch werde gebraucht?", rewards = "Schiftung des RunensuchersBeinschützer der geleiteten ReiseSehender AugengürtelPfadfindende TreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12548] = {title = "Der Etymidian", objective = "Durchschreitet das Tor am südlichen Ende des Sholazarbeckens und sucht auf der anderen Seite nach der Waffe, die der Etymidian genannt wird.", description = "Der Moment ist gekommen, <Name>. Das Tor wurde zum ersten Mal seit sieben Jahrhunderten wieder aktiviert. Schreitet hindurch und es wird Euch dorthin bringen, wo sich unsere letzte Hoffnung befindet.\n\nBereiten wir jenen ein Ende, die den Makel der Untoten in dieses unberührte Land zu bringen versuchen. Entfesseln wir den Etymidian.", progress = nil, completion = "&lt;Als Ihr die Inschrift auf diesem Steinkoloss lest, wird Euch klar, dass dies die Waffe ist, von der Freya sprach. Dies ist der Etymidian.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12549] = {title = "Beherrschen der Schreckenssäblerjagd: Zum Raubtier werden", objective = "Tötet 15 Schreckenssäbler und kehrt anschließend zu Buck Cantwell in Nesingwarys Basislager zurück.", description = "Falls Ihr schon einmal mit Hemet auf der Jagd gewesen seid, dann wisst Ihr, dass er sein Können schon an vielen großen Katzen erprobt hat, doch die Schreckenssäbler hier im Sholazarbecken gehören nicht dazu. Sie können Wild von einer Größe zu Fall bringen, wie ich es bei anderen Katzen noch nie erlebt habe. Solch ein Raubtier in den Griff zu bekommen, ist ein Zeichen dafür, dass man ein echter Jäger ist.\n\nFalls Ihr also beweisen wollt, dass Ihr der Herausforderung gewachsen seid, dann testet Euer Können an einem Schreckenssäbler. Sie leben in der Gegend um das Lager herum und südlich des Flusses.", progress = nil, completion = "Nun, Ihr habt bewiesen, dass Ihr ein fähiger Jäger seid; doch wie würdet Ihr als Fährtenleser abschneiden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12550] = {title = "Meister der Schreckenssäblerjagd: Der Beute auf der Spur", objective = "Buck Cantwell in Nesingwarys Basislager möchte, dass Ihr 3 Shangofährten aus den Schreckenssäblerfährten nahe des Bittertidensees herauslest.", description = "Ich habe gehört, dass die Eingeborenen Geschichten von einem riesigen Schreckenssäbler erzählen, den sie Shango nennen. Ich habe bisher keine Beweise seiner Existenz gesehen, aber meine Wunden haben mich davon abgehalten, mich aus dem Lager zu wagen.\n\nWenn Ihr Euch für so etwas wie einen Fährtenleser haltet, seid Ihr vielleicht in der Lage, die Wahrheit über Shango herauszufinden. Debaar sagte, sie sah bei ihrem letzten Ausflug einige breite Spuren. Geht nach Norden in Richtung des Bittertidensees und sucht am Südufer nach den Abdrücken.", progress = nil, completion = "&lt;Buck hört Euch zu, während Ihr über Euren Fund berichtet.&gt;\n\nIch glaube, Ihr habt womöglich die Beweise gefunden, die wir für diesen Shango brauchen. Und ich glaube, ich habe eine Idee, wo wir ihn finden können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12551] = {title = "Meister der Krokiliskenjagd: Die Prüfung", objective = "Tötet 15 Mangalkrokilisken und kehrt zu Debaar in Nesingwarys Basislager zurück.", description = "Ich warne Euch, Fremdling - keine Kommentare über den Schiffsbruch. Ich muss mir schon genug vom Rest der Expedition anhören.\n\nWenn Ihr Euch aber am Jagen versuchen wollt, solltet Ihr Eure Fähigkeiten an den gerissenen Mangalkrokilisken erproben. Sie leben entlang des Flusses im Süden und im Wildwuchsmangal im Osten. Beweist, dass Ihr ihnen gewachsen seid, und wir sprechen uns wieder, Jäger.", progress = nil, completion = "Beeindruckend, &lt;Klasse&gt;. Seid Ihr sicher, dass Ihr kein Mitglied der Expedition seid?\n\nNein, ausgeschlossen. Ihr hättet sonst irgendwann einen Witz über den Unfall gerissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12552] = {title = "Tod den Nekromagiern", objective = "Unteroffizier Mondsplitter in Drak'Sotra möchte, dass Ihr 8 Nekromagier von Hath'ar vernichtet.", description = "Kolramas ist gleich hier im Südosten abgestürzt, nachdem die Trolle es vom Himmel geholt haben. Unglücklicherweise sind bei dem Absturz nicht alle Diener der Geißel vernichtet worden.\n\nNun lassen sie unsere Männer wieder von den Toten auferstehen und verwenden sie gegen uns!\n\nDies muss ein Ende haben. Ihr werdet dafür sorgen, dass ihre Nekromagier getötet werden! Haben wir uns da verstanden?", progress = nil, completion = "Es ist nicht genug!\n\n&lt;Die Stimme des Unteroffiziers versagt. Er trauert um seine gefallenen Kameraden, die nun in Diener der Geißel verwandelt wurden.&gt;\n\nDiese Männer haben mehr Respekt von uns verdient!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12553] = {title = "Seglerspinndrüsen", objective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr 5 intakte Seglerspinndrüsen beschafft.", description = "Wieso muss ich mich immer mit den schweren Aufgaben herumschlagen?\n\nDie Diener der Geißel bei Kolramas sind mit Seuchensprühern ausgerüstet und kommen uns gefährlich nahe. Ihr wollt gar nicht erst wissen, was passieren würde, wenn sie sich auf den Weg hierher machen sollten!\n\nIch habe eine Idee, wie wir sie runterholen könnten, doch dazu brauchen wir zuerst etwas... etwas von ihren eigenen Kreaturen.\n\nDie Segler der Hath'ar spinnen ein sehr starkes Netz, das wir gut gebrauchen können. Beschafft Euch ein paar ihrer Spinndrüsen.", progress = "Diese Spinndrüsen müssen noch intakt sein, wenn ich aus ihnen ein Gerät bauen soll, das auch funktioniert.", completion = "Die werden reichen!\n\nNun werden wir ein paar Rohteile besorgen müssen, damit ich das Abschussgerät für Euch zusammenstellen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12554] = {title = "Malas der Verderber", objective = "Unteroffizier Mondsplitter in Drak'Sotra besteht darauf, dass Ihr ihm den Kopf des Verderbers bringt.", description = "<Name>, geht noch einmal dort hin!\n\nDer Anführer von Kolramas, Malas der Verderber, steht ganz oben auf der abgestürzten Nekropole.\n\nTötet ihn und bringt mir seinen Kopf!", progress = "Ich freue mich schon darauf, seinen Kopf auf einen Spieß zu stecken. Dann soll er mal sehen, wie er sich davon wieder erholen will!", completion = "Ihr seid der Held der Stunde, &lt;Name&gt;.\n\n\n\nIhr verdient unseren tiefsten Respekt und mehr als das, denke ich.", rewards = "Gamaschen der sorgfältigen EnthauptungBeinschützer der feierlichen RacheZeremonielle PikengamaschenBeinplatten des rachsüchtigen BettelmönchsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12555] = {title = "Ein Wirrgespinst", objective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr mithilfe des Wirrgespinstwerfers 5 Seuchensprüher zerstört.", description = "Fertig! Ein Wirrgespinstwerfer, der nur so darauf wartet, dass Ihr mit ihm die Seuchensprüher vom Himmel holt.\n\nIhr müsst nur zielen und feuern. Das Gewebe sollte ihre Schwebezauber lange genug blockieren, um sie genauso wie Kolramas zum Absturz zu bringen.\n\nIrgendwie poetisch. Ich mag das!", progress = nil, completion = "Juhu! Ihr seid der Beste, &lt;Name&gt;!\n\nIch habe mich nicht wirklich danach gesehnt, von dem Geißelzeugs besprüht zu werden, so viel steht fest! Ich schätze mal, dass es diesen dummen Nerubern jetzt schwer fallen wird, ihr Böses weiterhin zu verbreiten!\n\nWie wär's, wenn ich Euch etwas dafür gebe, dass Ihr meine Haut gerettet habt?", rewards = "Stab des PflichtgebundenenKlinge der SorgfaltStab der SorgfaltMesser des PflichtgebundenenPflichtgebundener Streitkolben der ReinheitSpaltbeil der SorgfaltIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12556] = {title = "Meister der Rhinozerosjagd: Der Todesstoß", objective = "Bringt Farunns Horn zu Hemet Nesingwary in Nesingwarys Basislager.", description = "Nun, da wir wissen, wo wir Farunn finden können, bleibt uns nur noch der Kampf gegen diese edle Kreatur. Seid Ihr bereit, Euch diesem Rhinozeros zu stellen, <Name>? So, wie der Geist tobte, bin ich mir sicher, dass er die Wahrheit über die Stärke des Tiers sagte.\n\nWenn Ihr bereit seid, ihm entgegenzutreten, dann geht nach Norden vorbei an der Sonnenstrahlsäule und sucht nach Farunn am Nordostufer des Bittertidensees. Womöglich hält er sich aber auch an der Schimmersäule auf. Bringt sein Horn zurück, um Eures Sieges zu gedenken.", progress = "Habt Ihr die wilde Kreatur getötet?", completion = "&lt;Hemet untersucht das Horn.&gt;\n\nEine wundersame Trophäe von einem erstaunlichen Tier! &lt;Name&gt;, mir sind Gerüchte über sogar noch größeres, grimmigeres Wild in den nördlichen Regionen des Beckens zu Ohren gekommen und ich hätte gerne, dass Ihr uns dabei helft, es aufzuspüren.", rewards = "Leichtfüßige MokassinsHufhorngürtelGeschabter RhinozeroshornbrustschutzRhinozerosgurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12557] = {title = "Laborarbeit", objective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr in sein Labor geht und ihm eine schlammige Moormade, einen getrockneten Fledermausflügel, einen Bernsteinsamen und ein wenig gekühlten Schlangenschleim beschafft.", description = "Die Tatsache, dass Ihr mich unterbrecht, lässt mich darauf schließen, dass Ihr unter denjenigen sein möchtet, die ich für eine Lehrstelle in Erwägung ziehe.\n\nEin lobenswertes Bestreben...\n\nSollte ich eines Tages Eurem Gesuch entgegenkommen, muss ich sicher sein, dass Ihr Euch in meinem Labor auch auskennt. Hier gibt es viele Reagenzien und Zutaten; einige gibt es in Hülle und Fülle, andere wiederum ganz und gar nicht.\n\nLasst Euch Zeit, <Klasse>. Sucht nach einer schlammigen Moormade, einem getrockneten Fledermausflügel, einem Bernsteinsamen und nach ein wenig gekühltem Schlangenschleim.\n\nFindet diese Zutaten und ich werde wissen, dass Euer Anliegen ernst zu nehmen ist.", progress = "Habt Ihr Euch schon an mein Labor gewöhnt, <Klasse>?", completion = "Ja, ja, das ist ein guter Anfang.\n\nSollte Ich Euch dazu auffordern, mir bei einem echten Rezept zu helfen, dann werdet Ihr die Zutaten recht zügig finden müssen.\n\nMerkt Euch das, &lt;Klasse&gt;.\n\nLebet wohl.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlchemist Finklestein Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12558] = {title = "Meister der Schreckenssäblerjagd: Bereit zum Angriff", objective = "Bringt Shangos Pelz zu Buck Cantwell in Nesingwarys Basislager.", description = "Shango wartet, <Name>. Wenn Ihr bei Eurer Spurensuche erfolgreich wart, dann wird er nicht wissen, dass Ihr ihn verfolgt - und Ihr braucht diesen Vorteil.\n\nEr soll größer, stärker und wilder als alle anderen Schreckenssäbler des Beckens sein. Reist nach Norden, zum Westufer des Bittertidensees und nahe der Wasserfälle, die ihn speisen, und kämpft mit Shango. Kehrt nach Eurem Sieg mit dem Pelz zurück.", progress = "Habt Ihr Euch Shangos angenommen?", completion = "Was für ein exquisiter Pelz von solch einem noblen Tier! Es ermutigt mich, dass die Gerüchte über Shango tatsächlich wahr waren, &lt;Name&gt;. Eure Jagd auf diese Kreatur war makellos. Ihr seid ein wahrer Jäger.", rewards = "FellfetzenschiftungSchulterpolster des SchreckenssäblerzahnsSchulterstücke der schnellen ErfrischungSchulterstücke des stillen NebelsBrünierte SchutzhaubeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12559] = {title = "Aufladen des Tors - Hort der Schöpfer", objective = "Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr Euch zum Hort der Schöpfer begebt und den Aktivierungsschalter Gamma betätigt.", description = "Es ist nun also soweit. Lasst uns das Tor aktivieren.\n\nIhr findet den ersten Schalter im Hort der Schöpfer, am westlichen Rand des Beckens.\n\nHütet Euch, <Name>. Die Titanen nutzten den Hort, um ihre Werke zu überwachen. Viele ihrer Steindiener bewachen diesen Ort nach wie vor.", progress = "Ihr seid zurück, kleines Wesen. Ich begann, mich um Euer Wohlergehen zu sorgen.", completion = "Wir haben die Hälfte geschafft, &lt;Name&gt;. Ein weiterer Schalter muss aktiviert werden, ehe wir den Etymidian erlangen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12560] = {title = "Meister der Krokiliskenjagd: Der Plan", objective = "Bringt Debaar in Nesingwarys Basislager 5 Sandfarnwedel.", description = "Der Mangalkrokilisk ist ein Meister des Hinterhalts und ich habe vor, bei dieser Großwildjagd die Besten diesbezüglich zu übertreffen. Daher müssen wir für Euch eine überzeugende Tarnung zusammenstellen. Wir werden Pflanzen verwenden, die im sandigen Boden der Fluss- und Seeufer wachsen.\n\nDer Sandfarn ist am besten für unsere Zwecke geeignet; er wächst im sandigen Gebiet nahe der Ufer des Meeresklammstroms genau südlich von hier, am Bittertidensee und bei den Bittertidenfällen im Norden sowie an den Rändern des Flussnabels, dem großen See jenseits des Mangal im Osten.", progress = "Bringt Ihr mir alle Farne, die wir brauchen?", completion = "&lt;Debaar nimmt die Sandfarnwedel und beginnt, sie um Euren Körper zu binden.&gt;\n\nJa, das sollte funktionieren. Haltet still! Wir wollen doch einen Busch aus Euch machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12561] = {title = "Eine Vertrauensfrage", objective = "Gewinnt Freyas Vertrauen, indem Ihr 6 verseuchte Leichname und 10 Knochensensenverheerer in den Verlorenen Landen vernichtet.", description = "Das hätte niemals passieren dürfen. Die untoten Streitkräfte erstürmen die Wiege des Lebens!\n\nWenn Ihr nicht hier seid, um die Diener des Lichkönigs zu vernichten, dann verlasst diesen Ort sofort. Lenkt mich nicht von meinen Pflichten ab, wenn Ihr nicht meinen Zorn auf Euch ziehen wollt.", progress = "Vergeudet nicht meine Zeit, Sterblicher. Die Kreationen der Titanen müssen verteidigt werden!", completion = "Also gut, &lt;Volk&gt;. Ich bin zufrieden, dass Ihr nicht einer von des Lichkönigs Dienern seid... vielleicht gibt es doch etwas, das Ihr für uns tun könnt.", rewards = "Bindung der geläuterten LeichenBespritzte ZombiehandgelenksschützerSkelettzerkracherStulpen mit SchutzmittelfleckenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12562] = {title = "Die Drakkari brauchen keine Wasserelementare!", objective = "Unterleutnant Jax in der Argentumwache möchte, dass Ihr 10 Wasserbinder der Drakkari tötet.", description = "Unsere Spione berichten uns, dass, seitdem diese Wasserelementare auf den Feldern von Drak'Sotra aufgetaucht sind, sich eine Anzahl von Schamanen der Drakkari von den höheren Bereichen Zul'Draks dort eingefunden hat, um die Kontrolle über sie zu erlangen.\n\nIch kann nicht genug betonen, <Herr/holde Dame>, welche Gefahr dies für uns darstellen könnte. Wir wollen auf keinen Fall, dass ihnen Wasserelementare zur Verfügung stehen.\n\nDer Hauptmann hat befohlen, dass diese Wasserbinder der Drakkari die Klinge zu spüren bekommen sollen. Geht in Richtung Süden, wenn Ihr bereit seid.", progress = nil, completion = "Ausgezeichnete Arbeit, mein Herr!\n\nIch werde mich darum kümmern, dass der Hauptmann über Eure Missionsresultate in Kenntnis gesetzt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12563] = {title = "Trollpatrouille", objective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok.", description = "Zieht Eure Waffe, <Volk>. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", progress = nil, completion = "Nun ja, &lt;Name&gt;, zumindest habt Ihr es in einem Stück wieder zurückgeschafft. Ich vermute mal, dass das schon etwas wert ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12564] = {title = "Trollpatrouille: Etwas gegen die Schmerzen", objective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt.", description = "So tapfer meine Männer auch sein mögen, sie sind noch immer sterblich.\n\nWunden und Schmerz vermindern Ihre Fähigkeit, ihre Missionen durchzuführen. Diese natürliche Sache kann nicht geändert werden, egal wie viel man trainiert.\n\nGlücklicherweise hat einer unserer Alchemisten ein Rezept für eine Salbe entwickelt, die auf unsere Bandagen geschmiert werden kann und den Schmerz unserer Soldaten erheblich lindert.\n\nFür die Salbe benötigt man eine besondere Mohnblume, die von den Trollen gleich westlich von hier angebaut wird. Geht zu den Feldern von Drak'Sotra und sammelt ein paar von ihnen, bevor unsere Vorräte zu Ende gehen.", progress = "Habt Ihr den Wassermohn gesammelt, <Name>?", completion = "Ausgezeichnete Exemplare, &lt;Name&gt;.\n\nIm Namen meiner Soldaten möchte ich mich bei Euch bedanken.\n\nHauptmann Rupert wird wahrscheinlich der nächste Halt auf Eurer Patrouille sein. Er ist an der Wand gleich östlich von hier stationiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12565] = {title = "Der Segen von Zim'Abwa", objective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr der Statue von Zim'Abwa 10 Drakkariopfergaben darbringt.", description = "Es macht mir Mut zu sehen, mit welchem Eifer sich der Argentumkreuzzug der Geißel entgegenstellt, <Volk>. Ich würde Euch gerne in dieser Sache unterstützen.\n\nDie Drakkaritrolle dieser einst prächtigen Stadt brachten ihren Göttern regelmäßig Opfergaben dar. Heute jedoch werden sie von den Drakkari vernachlässigt oder müssen Schlimmeres erfahren.\n\nFalls Ihr den Göttern etwas opfern solltet, würden sie sich dafür erkenntlich zeigen.\n\nZim'Abwas Statue befindet sich gleich gen Südwesten. Zim'Abwa würde Eure Gaben, die Drakkariartefakte, dankbar entgegennehmen und Euch somit für einen Beschützer von Zul'Drak halten.", progress = "<Zim'Abwa starrt gen Norden und Süden. Sein Blick ist unergründlich.>", completion = "&lt;Wenn Zim'Abwa der Mimik fähig wäre, dann würde er ein böses Grinsen aufsetzen.&gt;", rewards = "Ihr erlernt:\n\nSegen von Zim'Abwa\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12566] = {title = "Hilfe für das Lager der Winterhufe", objective = "Sprecht mit Häuptling Aschtotem im Lager der Winterhufe.", description = "Ich bin Fernläufer Nanik von den Taunka und wurde vom Häuptling des Lagers der Winterhufe ausgesandt, um Verbündete für den Kampf gegen die Vrykul zu gewinnen. Sie sind westlich und südlich unseres Dorfes aufmarschiert; doch obwohl wir für jeden unserer Toten Zehn von ihnen erschlagen, können wir nicht standhalten.\n\nApotheker Scyllis hat uns versprochen, zu unserer Unterstützung viele mutige <Helden/Heldinnen> wie Euch nach Nordosten zu entsenden. Werdet Ihr meinem Volk dabei helfen, die Angriffe der Vrykul abzuwehren?\n\nFolgt der Straße nach Nordwesten und überquert den Fluss. Das Lager der Winterhufe liegt im Vorgebirge.", progress = nil, completion = "So, so, Nanik hat also Hilfe gefunden? Sagt mir, &lt;Name&gt;, wie kommt es, dass Ihr ohne ihn hierher gefunden habt? Niemand kennt dieses Land besser als die Taunka.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12567] = {title = "Der Segen von Zim'Abwa", objective = "<Ihr habt das Gefühl, als würde Zim'Abwas steinernes Antlitz durch Euch durch und in Eure Seele blicken.\n\nZim'Abwa ist erfreut, möchte jedoch, dass Ihr ihm mehr Dankbarkeit und Respekt entgegenbringt, indem Ihr ihm mehr Drakkariopfergaben darbringt.\n\nEr wird Euch angemessen belohnen.>", description = nil, progress = "<Ihr habt das Gefühl, als würde Zim'Abwas steinernes Antlitz durch Euch durch und in Eure Seele blicken.\n\nZim'Abwa ist erfreut, möchte jedoch, dass Ihr ihm mehr Dankbarkeit und Respekt entgegenbringt, indem Ihr ihm mehr Drakkariopfergaben darbringt.\n\nEr wird Euch angemessen belohnen.>", completion = "&lt;Ihr spürt Zim'Abwas Zustimmung. Aus irgendeinem Grund wisst Ihr, dass Zim'Abwa mehr Tribut verlangt!&gt;", rewards = "Ihr erlernt:\n\nSegen von Zim'Abwa"}
MultiLanguageQuestData['de'][12568] = {title = "Trollpatrouille: todsicher gehen", objective = "Hauptmann Rupert möchte, dass Ihr das einäschernde Öl über 5 besiegte Argentumfußsoldaten gießt.", description = "Glaubt mir, <Volk>. Ich weiß...\n\nDer ständige Gestank von verbranntem Fleisch macht selbst mich krank - mich, einen Verlassenen. Nichtsdestotrotz ist es unsere heilige Pflicht, dafür zu sorgen, dass unsere Brüder niemals Teil der Geißel werden.\n\nGießt dieses Öl über die Leichen unserer Gefallenen, um sicherzugehen, dass wir ihnen auf dem Schlachtfeld nicht als Feinde begegnen müssen.", progress = nil, completion = "Habt Dank, &lt;Name&gt;.\n\nEs ist zwar nicht die glorreichste Aufgabe, die es auf dem Schlachtfeld zu tun gibt, doch getan werden muss sie. Eure Unterstützung wird in meinem Bericht erwähnt werden.\n\nHauptmann Grondel wird höchstwahrscheinlich in nordöstlicher Richtung auf Euch warten, gleich außerhalb des Amphitheaters.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Rupert Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12569] = {title = "Meister der Krokiliskenjagd: Der Hinterhalt", objective = "Bringt Buschräubers Kiefer zu Debaar in Nesingwarys Basislager.", description = "Der größte Krokilisk im Becken, aufgrund seines Geschicks zum Hinterhalt landläufig bekannt als \"Buschräuber\", sonnt sich gerne im flachen Wasser des Flussnabels. Das ist der große See in der Mitte des Beckens, östlich unseres Lagers.\n\nIch möchte, dass Ihr die Tarnung nehmt, die ich vorbereitet habe, und Euch am Westufer des Flussnabels versteckt, um Buschräuber aufzulauern und dann zuzuschlagen, sobald er sich zeigt. Bringt mir seinen mächtigen Kiefer zurück, falls es Euch gelingt, ihn zu überwältigen.", progress = "Hat der Plan geklappt?", completion = "&lt;Debaar hört zu, während Ihr das Versagen der Tarnung beschreibt.&gt;\n\nWas meint Ihr damit, dass unser Plan nicht so geklappt hat wie geplant?\n\nNun, zu Eurer Ehre habt Ihr es immerhin geschafft, ihn zu töten. Seht Euch die Größe dieses Kiefers an! Hemet wird stolz darauf sein, was wir geleistet haben. Dieser Krokilisk war wahrhaftig ein Monstrum.", rewards = "Gurt mit BissspurenKrokoschuppenmokassinsKnochenpanzer mit SchmierfleckenAuf Euch wartet eine dieser Belohnungen:\n\nGebogener Krokiliskenzahn\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12570] = {title = "Glückliche Missverständnisse", objective = "Geleitet das verletzte Orakel der Regenrufer sicher zum Baldachin der Regenrufer und sprecht mit dem Hochorakel Soo-say.", description = "Tut leid! Ich nicht wollen dir Ärger machen!\n\n<Das verwundete Orakel starrt Euch eine Weile lang leer an.>\n\nDu mich retten! Wir danken. Wir gehen zurück zu Dorf jetzt. Du auch kommen... du bei uns bleiben können! Wauwaumenschen irgendwie immer gemein.\n\nMir sagen, wenn fertig zum Aufbruch, ja?", progress = nil, completion = "Du uns helfen? Du dann willkommen, Trockenhaut.", rewards = "Gamaschen der heilenden PalmwedelHandschutz aus zerfetzten BlätternGürtel des IrrglaubensAuf Euch wartet eine dieser Belohnungen:\n\nRing der missverstandenen Gesten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12571] = {title = "Mach böse Schlangen fort", objective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Giftspitze und 10 Kaiserkobras tötet.\n\nWenn Ihr Lafoos Käfertasche verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "Wir lange hier vor Wauwaumenschen. Das hier sehr heiliger Ort - wir nicht werden gehen.\n\nDu aussehen, als ob vielleicht gut sein, aber Lafoo bleiben bei dir nur für alle Fälle. Du verstehst, denken wir.\n\nGibt Schlangendinger, die versuchen, unsere Jungen zu essen. Geh mit Lafoo und mach, dass sie aufhören, ja? Besonders großes Ding nahe Wasserfall im Nordosten.", progress = nil, completion = "Schlangen weg?\n\nGut, &lt;Volk&gt;. Wir dir danken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12572] = {title = "Götter wollen Glitzerglitzer", objective = "Sammelt 6 von den Schätzen, die Lafoo ausgräbt, und bringt sie zum Hochorakel Soo-say auf dem Baldachin der Regenrufer.\n\nSprecht mit dem Hochorakel Soo-say auf dem Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet.", description = "Soo-say sagt zu uns, wir mit dir gehen. Du nett sein, okay?\n\nOoh, ooh! Wir wissen! Wir können Soo-say glücklich machen, wenn wir mehr Opferdinge zum Schrein bringen! Wir nicht müssen weit gehen, es um Dorf herum immer Sachen zum Ausgraben geben... du suchen einfach nach Funkeln in Erde!\n\nGehen wir! Gehen wir! Mehr Opferdinge für Schrein!", progress = "Hallo Trockenhaut. Du mit Lafoo gut auskommen?", completion = "Glitzerglitzer für den großen Regenstein! Gut! Gut!\n\nWir diese gleich vor den Altar legen. Lafoo daran gedacht haben, ja? Er sein ein sehr kluger Regenrufer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12573] = {title = "Frieden schließen", objective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Schamanen Vekjik ein Friedensangebot unterbreitet und anschließend mit seiner Antwort wieder zurückkehrt.\n\nSprecht mit dem Hochorakel Soo-say im Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet.", description = "Wir haben großartige Idee. Du waren Freund mit Wauwaumenschen, vielleicht sie auf dich hören.\n\nWir wollen, dass du geben Opferdinger zu Schamane Vekjik. Er im Südwesten, wo Fluss zu Wasserfall wird. Sag Wauwaumann, dass wir nicht wollen kämpfen. Sag ihm, wir jetzt nett.\n\nDu gut, <Volk>. Wir wissen, dass du das richtig machen.", progress = "Wauwaumenschen sind jetzt nett zu uns?", completion = "So gemein! Wir sind nur nett und sie sind nur gemein.\n\nSie spielen immer mit großen Steinen rum... vielleicht sie nicht wissen, dass große Steine heilig.", rewards = "Tuch des gereichten ZweigsLeuchtkäfercapeUmhang des surrenden SchwarmsUmhang der gehärteten SchildkröteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12574] = {title = "Schon zurück?", objective = "Reist zur Zuflucht der Nebelflüsterer und sprecht mit Nebelrufer Soo-gan.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "<Das Hochorakel Soo-say starrt eine Weile auf Eure Stirn, bevor er zu sprechen beginnt.>\n\nSoo-gan nach Hilfe fragen. Wir glauben, sie vielleicht wieder von den Wauwauleuten angegriffen.\n\nWir dich und Jaloot schicken, um zu helfen... Folgen dem Fluss westwärts bis zu Zuflucht der Nebelflüsterer. Tun, was Soo-gan sagen... Wauwauleuten auf die Nase hauen, wenn sie werden böse, sie das nicht mögen.\n\n<Das Hochorakel Soo-say beginnt, wieder auf Eure Stirn zu starren, als Ihr ihn verlasst.>", progress = nil, completion = "Wir glauben, dich schon mal gesehen. Du Nebelflüstererdorf schon einmal besucht?\n\nSoo-say sagt, du gut. Soo-say schlau, also wir dir auch trauen.\n\n&lt;Nebelrufer Soo-gan schenkt Euch ein unbeholfenes, breites Lächeln.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12575] = {title = "Der verlorene Schatz der Nebelflüsterer", objective = "Tötet Kriegsfürst Tartek und bringt den Schatz der Nebelflüsterer für Soo-gan in der Zuflucht der Nebelflüsterer zurück.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "Also ein paar Wauwaumenschen kommen und zerschlagen blaue Kristalle am großen Nebelstein! Viel Regen und Blitz und Böses... blau ist falscher Kristall für großen Nebelstein! Dumme Wauwaumenschen.\n\nNach Blitz Wauwaumenschen gestohlen großen Schatz, wir im See gefunden. Wir brauchen Schatz zurück, um dem großen Nebelstein zu geben! Nebelstein ist wütend, nach dem, was die Wauwaumenschen getan!\n\nEiner von denen, die stehlen, heißt Tarter... nein, Tiktak... nein, nein... Tartek. Das es ist: Tartek! Er ging zum Lagerding im Norden. Geh' und hol' Schatz zurück!", progress = "Dumme Wauwaudiebe.", completion = "Du es geschafft! Du stark und nett! Gut Freund von Nebelflüsterern!\n\n&lt;Nebelrufer Soo-gan zeigt ein großes, zähnereiches Grinsen.&gt;", rewards = "Armschienen der schnellen WiedergewinnungBeinschützer des aggressiven AbgesandtenKlare irdene SchuppenrüstungHandschützer der vergänglichen FreundschaftIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12576] = {title = "Mit harter Hand", objective = "Tötet 8 Speerträger der Wildherzen und 6 Strauchdiebe der Wildherzen für Nebelrufer Soo-gan in der Zuflucht der Nebelflüsterer.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "Wir versuchen, nett zu Wauwaumenschen sein, seit sie ankamen, aber sie einfach nur gemein.\n\nUns egal, dass sie dumm - sie nicht viel Schaden machen. Jetzt sie aber heilige Schreine verwüstet. Heilige Schreine nicht zum Verwüsten da. Große Steine hier, seit uns die Großen vor langer, langer Zeit erschaffen.\n\nWir nicht wüssten, was zu tun, wenn große Nebelsteine zerstört. Geh zu ihrem Lager im Norden... mach, dass Wauwaumenschen aufhören und nicht zurückkommen!", progress = nil, completion = "Du gut zuschlagen. Danke für helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12577] = {title = "Hausezeit!", objective = "Kehrt zum Baldachin der Regenrufer zurück.", description = "Du gute Trockenhaut. Nebelflüsterer sicher, Schatz sicher und Wauwaumenschen uns jetzt auf jeden Fall in Ruhe lassen.\n\nDu gehen zurück zu Baldachin der Regenrufer und sagen Soo-say, du gute Arbeit gemacht.", progress = nil, completion = "Du schon so bald zurück!\n\nGut gelaufen, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12578] = {title = "Der wütende Gorloc", objective = "Reist ins Mooswandlerdorf und sprecht gleich nach Eurer Ankunft mit Moodle.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "Ich nicht glaube, dass du rechzeitig zurück, um wieder zu gehen, aber ich falsch. Ich sende Moodle zu nahen Mooswandlerfreunden, um dumme Mooswandler zu knuffen, weil nicht kommen Schrein sehen. Ihr Dorf ist östlich, den Hügel hoch, nordöstlich von kaputter Säule.\n\nDu gehst mit Moodle! Er besonders schlauer Regenrufer... du ihm gut zuhören.", progress = "Soo-say ist etwas ungeschickt, aber nicht dumm. Ich denke allerdings, dass er viel zu schnell vergibt... die Wauwaumenschen werden nicht einhalten oder uns in Frieden lassen. Der einzige Weg, sie aufzuhalten, ist, sie zu töten... es gibt keinen \"Frieden\".\n\n<Moodle drückt die Brust raus und deutet auf sich selbst.>\n\nDarin bin ich gut.", completion = "Bevor Ihr etwas sagt, haltet mich nicht für so töricht wie die meisten Orakel, die Ihr getroffen habt. Ich war ein wenig in der Welt unterwegs, ich habe Eure Sprache gelernt und ich lasse mich nicht so schnell überlisten.\n\nIch wusste bereits vor unserer Ankunft, dass die Mooswandler tot sind, obwohl ich nicht ahnte, dass dahinter die Untoten steckten.\n\nSie dürften gar nicht in der Lage sein, dieses Land zu betreten... die Zerstörung der Lebensblutsäule muss es ihnen irgendwie gestattet haben. Wir müssen dafür sorgen, dass sie verschwinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12579] = {title = "Lebensblut des Mooswandlerschreins", objective = "Moodle möchte, dass Ihr 10 Lebensblutscherben sammelt, aber haltet Euch von der Höhle innerhalb der Säule selbst fern.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "Ich habe schon immer vermutet, dass die Säulen die Hauptursache für unser Wetter und die Abgeschiedenheit von den Untoten sind... das gibt mir ein wenig Bestätigung.\n\nVor nicht allzu langer Zeit hörten wir, wie die Lebensblutsäule in einer großen Explosion umkippte. Das Wetter änderte sich fast schlagartig für die Mooswandler... Es begann zu schneien, etwas, das wir nie zuvor erlebt hatten.\n\nIndem sie mehr Lebensblutkristalle zum großen Moosstein brachten, gelang es ihnen, das Schneien zu beenden. Wenn wir ebenso verfahren, hilft es vielleicht auch dabei, die Untoten fernzuhalten.", progress = "Die Mooswandler waren gute Leute... sie verdienten all das nicht.", completion = "Womöglich ist es zu spät, um noch etwas mit den Scherben zu ändern, aber unsere Möglichkeiten sind eben begrenzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12580] = {title = "Retter der Mooswandler", objective = "Moodle möchte, dass Ihr 6 Mooswandleropfer im Mooswandlerdorf rettet, obwohl manche von ihnen vielleicht bereits nicht mehr länger leben.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", description = "Es besteht die schwache Hoffnung, dass die Mooswandler noch nicht alle tot sind... und sie verdienen es bei Weitem nicht, derart abgeschlachtet zu werden.\n\nLasst uns Rache nehmen für dieses Blutbad und sehen, ob wir dabei noch einige von ihnen retten können.", progress = "Ich wünschte, ich hätte früher gewusst, wie wichtig die Säulen und Steine sind... vielleicht hätte ich dies verhindern können.", completion = "Ich bin sehr froh, dass einige gerettet werden konnten... mit ein wenig Glück kehren sie sicher zum Baldachin der Regenrufer zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12581] = {title = "Bürde eines Helden", objective = "Tötet Artruis den Herzlosen.\n\nMoodle wird Euch bei dieser Aufgabe nicht begleiten können.", description = "Vielleicht wehren die Kristalle die Untoten allmählich ab, aber es gibt immer noch eine Sache, die erledigt werden muss.\n\nWir müssen den Anführer dieser Untoten aufspüren und töten, um sicherzugehen, dass niemand diese Ungeheuer zu uns zurücktreibt. Wenn ich richtig vermute, hält er sich irgendwo innerhalb der umgestürzten Säule, der Versprengten Scherbe, auf.\n\nDie dorthin verschleppten Leichen deuten jedenfalls darauf hin.\n\nIch platziere die Splitter und informiere Soo-say. Um den Rest müsst Ihr Euch kümmern.", progress = "<Das Phylakterium ruht bedrohlich neben Artruis' toter Hülle auf dem Boden.>", completion = "&lt;Innerhalb von Artruis' Phylakterium erkennt Ihr etwas, das wie endlose Leere wirkt... und Ihr glaubt, von irgendwo dort drin Schreie aus der Ferne zu vernehmen.&gt;\n\n&lt;Als Ihr gerade gehen wollt, seht Ihr, wie ein Objekt in die Leere gleitet, knapp außer Reichweite.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHalsreif der BindungBluterfüllter AnhängerArtruis' FokussteinStachelhalsband der Knechtschaft\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12582] = {title = "Champion der Wildherzen", objective = "Ich wusste, du bist kein Verräter, wie die anderen behaupten. Wir zusammen gejagt... Ich dich kennen besser als alle anderen. Danke, dass du mich gerettet.\n\nVielleicht klingt komisch... ich Großzungen nicht besonders mögen... aber selbst ich fühle schlecht, weil Großzunge so gestorben... sie gut genug kämpfen, um gerechten Kampf zu verdienen.\n\nDu wieder willst Freund mit Wildherz sein? Ich glaube, ich kann sie überzeugen, dass du mich gerettet und es den Großzungen gut gegeben. Ich aber nicht möchte, dass du mich dumm dastehen lässt - du also sicher, dass du nichts mehr mit Großzungen zu tun haben willst?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Set Wolvar Honored\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12583] = {title = "Abgestürzter Seuchensprüher", objective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr Seuchensprüherteile sammelt.", description = "Ich weiß, dass einer dieser Seuchensprüher irgendwo in Drak'Sotra westlich von uns abgestürzt ist.\n\nSeht doch einmal nach, ob Ihr die Stelle finden könnt. Ich kann die Teile des Sprühers dazu benutzen, um ein Gerät herzustellen, mit dem wir diese Dinger vom Himmel holen werden!", progress = "Habt Ihr die Teile? Hm? Habt Ihr sie?", completion = "&lt;Die Spezialistin weicht einen Schritt zurück, als sie die Teile sieht.&gt;\n\nBäh, die Dinger sind einfach nur widerwärtig!\n\nOkay, okay, gebt sie mir und ich werde sehen, was sich machen lässt. Ich hätte Euch wahrscheinlich zuerst zu einem Priester schicken sollen, damit er die Dinger läutert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12584] = {title = "Das pure Böse", objective = "Hauptmann Rupert möchte, dass Ihr 10 Brocken Saronit einsammelt und sie anschließend zu Etrigg in der Argentumwache bringt.", description = "Wir wissen, dass Kolramas, die abgestürzte Nekropole gen Südosten, eine große Menge Erz namens Saronit an Bord gehabt hat, als die Trolle sie vom Himmel holten.\n\nMeine Späher berichten mir, dass allerlei Saronit im Inneren des Dings herumliegt.\n\nEtrigg und seine Freunde drüben in der Argentumwache brauchen eine Ladung von dem Zeugs für ihre Forschungen.\n\nIch möchte also, dass Ihr dort hineingeht und nachseht, ob Ihr genug für sie sammeln könnt.", progress = "Ja, <Klasse>?\n\nSagt mir bitte, dass Ihr das Saronit, das wir bei Hauptmann Rupert beantragt haben, dabei habt.", completion = "Könnt Ihr das pure Böse dieses Zeugs spüren?\n\nWir müssen den Sachverstand und die Magien, die uns zur Verfügung stehen, gemeinsam mit der Macht des Heiligen Lichts dazu einsetzen, um den Schleier der Bosheit, der dieses verdorbene Erz umgibt, zu durchdringen. Wir müssen seinen Ursprung erkunden.\n\nSchnell, gebt mir das Saronit!", rewards = "Schulterpolster des SterndeutersStiefel des AltarsHandschuhe des schnellen TodesAuf Euch wartet eine dieser Belohnungen:\n\nRituelles Band des Lichts\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12585] = {title = "Trollpatrouille: Annehmlichkeiten", objective = "Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt.", description = "Tja, es ist nicht gerade glamourös, muss aber gemacht werden.\n\nMeine Truppen haben sich die Seele aus dem Leib gekämpft, während sie tagelang knietief in abgestandenem Wasser standen. Das kann einfach nicht gut für einen sein.\n\nWas sie brauchen ist ein warmes Feuer, um sie trocken zu bekommen und ihre Stimmung zu bessern.\n\nIn diesem Teil der Stadt gibt es nichts, das trocken bleibt, doch die toten Wurzeln dieser Dornholzbäume sind irgendwie gegen die Feuchtigkeit resistent.\n\nBesorgt uns etwas Brennholz und wir werden Euch mächtig dankbar sein.", progress = "Habt Ihr das Holz für das Feuer, <Volk>?", completion = "Sehr nett von Euch, &lt;Name&gt;. In der Tat: sehr nett.\n\nNun, Ihr werdet Hauptmann Arnath westlich von hier finden, die Anhöhe hoch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Grondel Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12586] = {title = "In Search of Bigger Game", objective = "Talk to <x> at <x>.Well, <Name>, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.", description = "Well, <Name>, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12587] = {title = "Trollpatrouille", objective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok.", description = "Zieht Eure Waffe, <Volk>. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", progress = nil, completion = "Nun ja, &lt;Name&gt;, zumindest habt Ihr es in einem Stück wieder zurückgeschafft. Ich vermute mal, dass das schon etwas wert ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12588] = {title = "Trollpatrouille: Könnt Ihrs aushalten?", objective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr mit dem Stahlspaten in den uralten Erdhaufen in der Nähe herumgrabt, um das uralte Relikt der Drakkari zu finden.", description = "Einer unserer Trupps ist während der letzten Offensive über eine alte Schatzkarte gestolpert. Falls das, was auf der Karte eingezeichnet ist, stimmt, dann gibt es hier in der Nähe unbezahlbare Trollartefakte.\n\nMeine Soldaten haben die Drakkari und gleichzeitig auch die Geißel am Hals - haben also alle Hände voll zu tun. Ich möchte, dass Ihr diese Sache genauer untersucht.\n\nNehmt diese Schaufel; Ihr werdet sie für die lockeren Erdhaufen im Südwesten benötigen. Kehrt wieder zu mir zurück, nachdem Ihr die Gegend gründlich durchsucht habt.", progress = nil, completion = "Danke, dass Ihr Euch die Sache für mich angesehen habt, &lt;Name&gt;. Eure Unterstützung wird in meinem Bericht Erwähnung finden.\n\nAls Nächstes solltet Ihr wahrscheinlich Hauptmann Rupert aufsuchen - er ist östlich von hier an der Mauer stationiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12589] = {title = "Kick, was für'n Kick?", objective = "Schießt mit dem RJR-Gewehr den Apfel vom Kopf von Wilhelm dem Glückspilz und sprecht dann mit Drostan.", description = "Also Ihr denkt, Ihr könnt schießen?\n\nNun, dann wollen wir mal sehen. Hier, wir geben Euch für den Anfang etwas Nettes und Harmloses. Keine Sorge, sie hat überhaupt keinen Rückstoß. Vergesst nicht, das Gewehr auf nichts zu richten, auf das Ihr nicht schießen wollt.\n\nWenn Ihr bereit seid, zielt einfach mal auf den Apfel auf'm Kopf von Wilhelm dem Glückspilz und dann lasst se fliegen!", progress = "Zufrieden mit dem Ergebnis?", completion = "Kein schlechter Schuss, aber mit ein bisschen Übung werdet Ihr noch besser werden. Was haltet Ihr von einer kleinen Wette?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12590] = {title = "Blahblah[PH]", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12591] = {title = "Trollpatrouille: Werfen", objective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr hocheffektive Granaten in der Nähe von 5 nerubischen Kratern einsetzt.", description = "Clever...\n\nGerade, als es so aussah, als würden wir die Sache unter Kontrolle bekommen, haben sie einen Tunnel unter uns durchgegraben und den Schrein eingenommen!\n\nJetzt sind wir zwischen zwei Armeen der Neruber gefangen und unsere Lage wird von Sekunde zu Sekunde schlimmer.\n\nAls Erstes müssen wir sie daran hindern, Verstärkung zu erhalten. Die Tunnel müssen verschlossen werden.\n\nNehmt diese Granaten und werft sie in die Krater im Nordwesten.", progress = nil, completion = "Wir sind noch lange nicht über den Berg, doch Euer Einsatz hat geholfen, den Gegner zu verlangsamen.\n\nHauptmann Grondel in Drak'Agal hat wahrscheinlich Arbeit für Euch.\n\nLebt wohl, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Rupert Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12592] = {title = "Des großen Jägers Wettstreit", objective = "Tötet 60 Beutetiere, während Ihr Hemet und seinen Kameraden bei der Jagd helft. Kehrt zu Drostan in Nesingwarys Basislager zurück, wenn Ihr Eure 60 getötet habt, um Ergebnisse zu vergleichen.", description = "Also habt Ihr so was wie 'nen Jägerinstinkt. Ihr schießt nicht übel und Hemet hat Euch auch nicht davongejagt, also muss er Euch in die Jagd einplanen.\n\nWas haltet Ihr von 'nem kleinen Wettkampf, nur Ihr und ich?\n\nHemet und die anderen werden Euch bitten, ihnen bei der Jagd zu helfen. Unterwegs werden wir beide zählen, wie viele ihrer Ziele wir erledigt haben. Naja, das ist nichts, das Ihr mit 'nem Augenzwinkern bewältigen könnt, und Ihr werdet viele verschiedene Kreaturen töten müssen. Weidmannsheil!", progress = nil, completion = "So, Ihr gesteht also schon Eure Niederlage ein?\n\n&lt;Drostans Unterkiefer klappt nach unten, als Ihr ihm erzählt, dass Ihr bereits die erforderliche Zahl getötet habt.&gt;\n\nUnmöglich! Wie in ganz Azeroth habt Ihr das geschafft? Ich bin gerade mal bei 58! So knapp!\n\nAber abgemacht ist abgemacht. Ich hab' Euch unterschätzt, &lt;Name&gt;, aber Ihr habt Euch den Sieg wirklich verdient.", rewards = "Finger der geschickten DezimierungArmschienen des schnellen TodesGesichtsschutz des zielsicheren TreffersHelm des brutalen AbschlachtensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12593] = {title = "Im Dienste des Lichkönigs", objective = "Meldet Euch bei Instrukteur Razuvious, sobald Ihr dort seid.", description = "Alles, was ich bin: Zorn, Grausamkeit, Rache, verleihe ich Euch, mein erwählter Ritter. Ich schenke Euch Unsterblichkeit, auf dass Ihr ein neues dunkles Zeitalter der Geißel einleitet.\n\nSeht die Länder unter uns. Der Scharlachrote Kreuzzug will alles zunichtemachen und die Kapelle des Hoffnungsvollen Lichts stellt sich uns trotzend entgegen - eine Schande für die Pestländer. Sie werden für ihre Frechheit zahlen.\n\nIhr werdet zu meiner Vergeltung. Auf Euren Schritt folgt die Verderbnis. Geht nun und folgt Eurer Bestimmung, Todesritter.", progress = nil, completion = "Ihr habt den Ruf des Lichkönigs vernommen, &lt;Klasse&gt;. Die Zeit, Eurem Meister zu antworten, ist gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12594] = {title = "Trollpatrouille: Juckt mich kein bisschen", objective = "Hauptmann Grondel möchte, dass Ihr 7 moosbedeckte Amokläufer in Drak'Agal tötet.", description = "Von all den Posten, die es gibt, haben sie ausgerechnet den hier für mich ausgesucht.\n\nDer Ort ist von modrigem, fahlem Wasser nur so überflutet, was nun zu einem Paradies für Abwasserelementare geworden ist!\n\nIch weiß nicht wirklich, was sie sind oder wieso sie hier sind, und um ehrlich zu sein, juckt es mich kein bisschen. Was ich weiß, ist, dass sie aus meinem Sektor einen Saustall machen! Wie soll ich nur irgendeine militärische Operation mit Würde durchführen können, wenn diese Dinger hier umherstreifen?\n\nGeht hinaus, <Klasse>, und kommt nicht eher wieder zurück, bis Ihr Euren Anteil dieser Schmutzfinken von meinem Schlachtfeld entfernt habt!", progress = nil, completion = "Seid Ihr Euch da sicher, &lt;Volk&gt;?\n\nFür mich scheint es, als gäbe es jetzt noch mehr von den Dingern als zuvor!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Grondel Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12595] = {title = "Auf der Suche nach größerem Wild", objective = "Sprecht mit Dorian Drachenlauer in Dorians Außenposten im Sholazarbecken.", description = "Nun, <Name>, Ihr habt auf jeden Fall bewiesen, dass Ihr alles an Tieren jagen könnt, was es so gibt: Rhinozerosse, Katzen und Krokilisken. Für einige Mitglieder dieser Expedition sind diese Kreaturen genug, um an ihnen ihre Jagdkünste zu erproben, doch anderen - wie mir selbst zum Beispiel - verlangt es nach größeren Herausforderungen.\n\nDorian Drachenlauer ist nach Norden gegangen. Er befindet sich jetzt auf der anderen Seite des Bittertidensees und hat dort ein Lager aufgeschlagen. Er hat Gerüchte über gigantische, urzeitliche Drachen gehört. Stellt Euch nur mal vor, was das für eine Beute wäre! Geht und seht mal nach Dorian und findet heraus, ob er Glück gehabt hat.", progress = nil, completion = "Der alte Hemet hat mich letztendlich also doch nicht vergessen. Ich nehme an, dass er bei der Jagd mitmachen möchte, nachdem wir die ganze harte Arbeit erledigt haben. Macht Euch keine Sorgen, es sind genug Drachen für alle da. Hemets Wunsch wird erfüllt werden.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12596] = {title = "Pa'trollieren", objective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra südöstlich von hier stationiert.\n\nHauptmann Grondel ist in Drak'Agal gleich im Osten stationiert.\n\nAlchemist Finkelstein ist in Heb'Valok im Norden stationiert.", description = "Willkommen in der Argentumwache, Grünling. Ich bin Kommandant Kunz, doch Ihr, Ihr könnt mich... Kommandant nennen.\n\nDenkt bloß nicht, dass Ihr ohne jemandem Bericht zu erstatten durch meine Gegend ziehen und Eure eigenen Missionen auswählen könnt.\n\nHier, Ihr habt mir Bericht zu erstatten und meine Befehle haargenau zu befolgen. Verstanden?!\n\nZuerst müsst Ihr Euch mit meinen Männern und der Region, die wir säubern sollen, vertraut machen.\n\nMeldet Euch bei jedem von ihnen und tut das, was sie von Euch verlangen. Kehrt anschließend wieder zu mir zurück und Eure Patrouille ist beendet.", progress = nil, completion = "Wurde auch Zeit, dass Ihr Euren Kadaver hierher zurückschleift! Dachte schon, wir hätten Euch an die Geißel verloren - nicht, dass das ein großer Verlust gewesen wäre...\n\nFalls Ihr noch weiterhin dem Kreuzzug dient, dann solltet Ihr Beeindruckenderes liefern.\n\nMerkt Euch das, &lt;Volk&gt;! Eure zukünftigen Patrouillen werden anhand Eurer Pünktlichkeit belohnt werden.\n\nWegtreten.", rewards = "Pantalons des PflichtgebundenenHandgelenksschützer des DienstesGerippter Helm der KnechtschaftGürtel des DienensAuf Euch wartet eine dieser Belohnungen:\n\nAbscheulicher Foliant der Lehren\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12597] = {title = "Etwas gegen die Schmerzen", objective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt.", description = "So tapfer meine Männer auch sein mögen, sie sind noch immer sterblich.\n\nWunden und Schmerzen erschweren die Durchführung ihrer Missionen - das ist eine einfache Tatsache des Lebens und keine Ausbildung der Welt wird daran etwas ändern.\n\nGlücklicherweise hat einer unserer Alchemisten ein Rezept für eine Salbe entwickelt, die auf unsere Bandagen geschmiert werden kann und die Schmerzen unserer Soldaten erheblich lindert.\n\nFür die Salbe benötigt man eine besondere Mohnblume, die von den Trollen gleich westlich von hier angebaut wird. Geht zu den Feldern von Drak'Sotra und sammelt ein paar von den Blumen, bevor unsere Vorräte zu Ende gehen.", progress = "Habt Ihr den Wassermohn gesammelt, <Name>?", completion = "Ausgezeichnete Exemplare, &lt;Name&gt;.\n\nIm Namen meiner Soldaten möchte ich mich dafür bedanken, was Ihr heute getan habt.\n\nHauptmann Rupert wird wahrscheinlich der nächste Halt auf Eurer Patrouille sein. Er ist an der Wand gleich östlich von hier stationiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12598] = {title = "Hinunterwerfen", objective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr die hocheffektiven Granaten in der Nähe von 5 nerubischen Kratern verwendet.", description = "Sehr schlau...\n\nGerade als es so schien, als würden wir die Dinge unter Kontrolle bringen, haben sie sich direkt unter uns hindurchgegraben und den Schrein eingenommen!\n\nNun sind wir zwischen zwei nerubischen Armeen eingeschlossen und unsere Lage verschlimmert sich von Minute zu Minute.\n\nUnsere erste Handlung muss sein, dass wir verhindern, dass sie Nachschub bekommen. Ihre Tunnel müssen versiegelt werden.\n\nNehmt diese Granaten und werft sie in die Tunnel gen Nordwesten.", progress = "Habt Ihr die nerubischen Krater schon versiegelt, <Name>?", completion = "Wir sind keinesfalls schon aus dem Schneider, doch wir haben erreicht, dass der Gegner langsamer vorankommt.\n\nHauptmann Grondel oben in Drak'Agal wird Euch wahrscheinlich brauchen.\n\nLebt wohl, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Rupert Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12599] = {title = "Annehmlichkeiten", objective = "Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt.", description = "Tja, es ist nicht gerade glamourös, muss aber getan werden.\n\nMeine Truppen haben sich die Seele aus dem Leib gekämpft, während sie tagelang knietief in abgestandenem Wasser standen. Das kann einfach nicht gut für einen sein.\n\nWas sie brauchen ist ein nettes, gutes Feuer, um sie trocken zu bekommen und ihre Stimmung zu bessern.\n\nIn diesem Teil der Stadt ist alles durchnässt, doch die toten Wurzeln dieser Dornholzbäume sind irgendwie gegen die Feuchtigkeit resistent.\n\nBesorgt uns etwas Brennholz und wir werden Euch mächtig dankbar sein.", progress = "Habt Ihr das Holz für das Feuer, <Volk>?", completion = "Sehr nett von Euch, &lt;Name&gt;. In der Tat: Sehr nett.\n\nNun, Ihr werdet den alten Finkelstein westlich von hier finden, die Anhöhe hoch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Grondel Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12601] = {title = "Der Lehrling des Alchemisten", objective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hier hergeschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, <Volk>. Und merkt Euch: Timing ist alles!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlchemist Finklestein Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12602] = {title = "Der Lehrling des Alchemisten", objective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hierher geschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, <Volk>. Und merkt Euch: Timing ist alles!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12603] = {title = "Klauen schärfen", objective = "Tötet 6 urzeitliche Drachen und sprecht anschließend mit Dorian Drachenlauer in Dorians Außenposten.", description = "Die urzeitlichen Drachen besetzen den Großteil des Gebiets im Norden und Osten und ich fühle selbst auf diese Entfernung hin die Hitze ihres Atems. Bevor wir uns den mächtigsten unter den Drachen stellen können, müssen wir unsere Fähigkeiten an den geringeren erproben.\n\nDoch seid nach wie vor auf der Hut: Jedes dieser Wesen kann einen ganzen Mann verschlingen. Kehrt zu mir zurück, sobald Ihr Euch mit den Kampftaktiken dieser Drachen vertraut gemacht habt, und ich werde Euch unseren nächsten Schritt erklären.", progress = nil, completion = "Ich höre die Zuversicht in Euren Worten. Gut, die Erfahrung wird Euch hilfreich sein, wenn wir uns der Königin der Drachen stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12604] = {title = "Herzlichen Glückwunsch!", objective = "Ihr lagt auf dieser Patrouille hervorragend in der Zeit. Es scheint, als wäret Ihr doch für etwas zu gebrauchen.\n\nHier, wie versprochen, ein kleiner Bonus für Eure Mühen.\n\nMacht weiter so, <Name>.\n\nWegtreten.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStrip On Patrol Aura\n\nIhr bekommt:\n\nBeutel des Patrouillenführers"}
MultiLanguageQuestData['de'][12605] = {title = "Den Köder sichern", objective = "Bringt 6 urzeitliche Jungtiere zu Dorian Drachenlauer in Dorians Außenposten.", description = "Es ist ziemlich unwahrscheinlich, dass wir Brutmutter Slivinas Aufmerksamkeit erregen werden, wenn wir wie Trottel mit unseren Armen herumfuchteln; doch wenn wir schlau sind, dann können wir sie dazu bringen, uns anzugreifen. Darüber hinaus würden wir auch mehr, ähm, Futter für mein kleines Projekt liefern.\n\n<Dorian wirft einen Blick auf Spleenix.>\n\nMacht Euch jedoch darüber im Moment keine Sorgen. Sucht einfach nach den urzeitlichen Dracheneiern in der Gegend östlich und nordöstlich des Lagers. Zerschlagt sie und fangt die Jungtiere ein, wenn sie aus den Eiern springen. Sobald die Brutmutter dann erst einmal mitbekommt, was wir getan haben, wird sie keine andere Wahl haben, als sich uns zu stellen.", progress = "Habt Ihr den Köder schon beschafft, den Ihr dazu benötigt, um die Aufmerksamkeit der Brutmutter auf Euch zu ziehen?", completion = "Ah, gut gemacht. Spleenix hat jetzt genug Jungtiere!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12606] = {title = "In Kokons eingesponnen!", objective = "Hauptmann Rupert möchte, dass Ihr die nerubischen Kokons in Drak'Sotra öffnet und wieder zu ihm zurückkehrt, sobald Ihr 3 gefangene Fußsoldaten befreit habt.", description = "Nun, da die Tunnel versiegelt wurden, werden wir uns als Nächstes darum kümmern, diejenigen wieder hierher zu bringen, die in feindliche Hände gefallen sind.\n\nMit etwas Glück sind noch einige unserer Soldaten, die sich in den nerubischen Kokons befinden, am Leben und relativ unversehrt.\n\nBefreit sie, <Klasse>, solange Ihr noch Gelegenheit dazu habt!", progress = nil, completion = "Die Neruber haben einen hohen Tribut gefordert, &lt;Klasse&gt;.\n\nNichtsdestotrotz bin ich dankbar für das, was Ihr getan habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCaptain Rupert Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12607] = {title = "Ein Mammutunternehmen", objective = "Bringt ein Spaltzahnmammut zu Spleenix in Dorians Außenposten.", description = "Dorian dachte, bevor Ihr losgeht und Brutmutter Slivina heraufordert, wäre es vielleicht eine gute Idee, wenn Hemet und Ihr zusammenarbeitet und auf dem Rücken eines Mammuts in die Schlacht zieht.\n\nDie Gegend um das Lager herum ist voll von ihnen. Nehmt einfach dieses Zaumzeug und legt es einem Spaltzahnmammut an. Nehmt Euch jedoch vor den Bullen in Acht. Sie werden das Geschirr auf keinen Fall tragen. Bringt das Mammut hierher zurück, wenn Ihr ein passendes gefunden habt.", progress = nil, completion = "Perfekt! Das Einzige, was wir nun brauchen, ist, für Hemet eine Trittleiter zu besorgen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12608] = {title = "Angriff der Kultisten", objective = "Sprecht mit dem Avatar von Freya im Katarakt der Regenrufer.", description = "<Es scheint, als hätte der Avatar von Freya recht. Die Untoten waren nicht in der Lage, das Sholazarbecken zu betreten, bevor die Lebensblutsäule umstürzte. Stattdessen hatten sie ihre lebenden Agenten vom Kult der Verdammten entsandt.>\n\n<Ihr warnt sie besser vor den lebenden Agenten des Lichkönigs im Sholazarbecken.>", progress = nil, completion = "Die Lebenden... freiwillige Diener des Lichkönigs?\n\nAll diese Zeit habe ich den falschen Feind gesucht, &lt;Volk&gt;. Lasst uns eilen und die Kultisten in diesen Landen ausmerzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12609] = {title = "Die Regale einräumen", objective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 Einheiten frischen Spinnensekrets von den Falltürkrabblern in Zul'Drak sammelt.", description = "Hört zu, <Klasse>. Ich weiß, dass ich damit viel von Euch verlange...\n\nFrisches Spinnensekret ist etwas schwer zu bekommen, sogar in diesen stark verseuchten Regionen. Doch Finkelstein hat gesagt, dass er nicht eher zufrieden ist, bis er nicht weniger als ein ganzes Fass hat, und dass er es schon bald braucht.\n\nIch werde meine Männer weiterhin draußen auf dem Feld Reagenzien sammeln lassen, doch falls die Bestellung des Alchemisten rechtzeitig ausgefüllt werden soll, dann werden sie etwas Unterstützung brauchen.\n\nHaltet nach Falltürkrabblern Ausschau, wenn Ihr auf den Feldern von Zul'Drak seid, und bringt mir alles Sekret, das Ihr finden könnt.", progress = "Habt Ihr meine benötigten Reagenzien dabei, <Klasse>?", completion = "Diese hier sehen wie ausgezeichnete Proben aus, &lt;Name&gt;.\n\nDanke für Eure Unterstützung.", rewards = "KreuzzüglergroßschwertHochgespannter BogenRuhmreiche ZauberklingeDorniger Zweig des LichtsKnöchel des SiegesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12610] = {title = "Ihre Flügel stutzen", objective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 makellose Fledermausflügel von den Fledermäusen von Zul'Drak sammelt.", description = "Seitdem Finkelstein hier ist, bin ich dazu verdammt, verschiedene Zutaten für seine Experimente und Rezepte zu sammeln.\n\nIch werde meinem Eid zwar treu bleiben und meine Befehle ausführen, doch ich bin ein erfahrener Veteran! Ich habe an dutzenden Konflikten teilgenommen. Ich wäre viel lieber an der Front, um direkt Einfluss auf den Ausgang des Kreuzzuges zu nehmen.\n\nHelft mir, <Volk>. Sammelt ein paar Fledermausschwingen, damit ich vielleicht schon eher dort mitmischen kann, wo der eigentliche Kampf stattfindet.", progress = "Habt Ihr die Fledermausschwingen für Finkelstein schon eingesammelt?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.\n\nIch danke Euch für Eure Unterstützung.", rewards = "Geflochtene FledermaussehnenJägerwamsStulpen des SammlersFledermausfellfäustlingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12611] = {title = "Siebenfach zurückgezahlt", objective = "Der Avatar von Freya möchte, dass Ihr Thalgran Seuchenbringer besiegt, indem Ihr mit Freyas Wall seine Todesblitze siebenfach auf ihn zurückwerft.", description = "Die Agenten des Lichkönigs haben törichterweise diese Lande betreten, in denen die Macht des Lebens regiert. Jedes Leid, das sie anrichten, soll ihnen siebenfach heimgezahlt werden.\n\nDas unmittelbar für die Verderbnis des Landes verantwortliche Monster nennt sich Thalgran Seuchenbringer; Ihr findet ihn genau nördlich von hier. Nehmt diesen Zauberschutz, um die Macht des Todes auf ihn zurückzuwerfen. Zeigt der Geißel, dass die Macht des Lebens über alles siegt.", progress = "Ist es vollbracht, <Name>?", completion = "Ihr erweist Euch weiterhin als würdig, &lt;Name&gt;. Womöglich war ich vorschnell, Euch zu verurteilen.\n\nIch nahm an, Ihr wärt gemeinsam mit den Wilderern gekommen, die kürzlich in meinen Landen strandeten, aber vielleicht seid Ihr bereit, dies hinter Euch zu lassen.", rewards = "Gugel des LäuterersGeißelbanntreterBerührung des HütersSchutz des LebensspendersIhr bekommt:\n\nSiegel des rachgierigen Herzens"}
MultiLanguageQuestData['de'][12612] = {title = "Die gestürzte Säule", objective = "Reist zur Lebensblutsäule und sucht nach Hinweisen, die auf die Ursache ihrer Zerstörung hinweisen.", description = "Die Titanen schufen ganze Lebensformen hier und behüteten ihr uneingeschränktes Wachstum.\n\nDie fünf Kristallsäulen, die das Becken umgeben, strömen reine Lebenskraft aus. Die Geißel hätte niemals in das Becken einfallen dürfen, aber eine der Säulen wurde zerstört.\n\nGeht zur Lebensblutsäule und versucht herauszufinden, was geschah. Kein Untoter hätte sich der Säule nähern können, also haltet die Augen nach lebenden Eindringlingen offen. Ihr findet das, was von der Säule übrig ist, unmittelbar südlich von hier.", progress = nil, completion = "&lt;Die Leiche ist schwer verbrannt. In der Umgebung liegen offensichtlich die Überreste einiger Pulverfässer.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12613] = {title = "Aufladen des Tors - Die Warte der Schöpfer", objective = "Der Avatar von Freya möchte, dass Ihr Euch zur Warte der Schöpfer im Osten des Sholazarbeckens begebt und den Aktivierungsschalter Theta betätigt.", description = "Wir können nun nicht mehr zurück, <Volk>. Ihr habt den ersten Schalter umgelegt, doch einer verbleibt.\n\nDie Titanen konstruierten einen zweiten günstigen Aussichtspunkt, von wo aus sie ihre Kreationen überwachten. Ihr findet ihn im Osten, hoch oben in den Bergen.\n\nBetätigt den Aktivierungsschalter Theta innerhalb der Warte, um das Tor zu öffnen.", progress = "Ist es vollbracht, <Name>?", completion = "Das Tor wurde aktiviert, &lt;Name&gt;. Es ist an der Zeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12614] = {title = "Postnatale Aggression", objective = "Tötet Brutmutter Slivina und kehrt zu Dorian Drachenlauer bei Dorians Außenposten zurück.", description = "Brutmutter Slivina ist vermutlich ein wütendes Knäuel aus Zähnen, Stacheln und Klauen. Ihr habt ihre Kinder gestohlen und keine Mutter kann so etwas verzeihen.\n\nDie kleinen Biester sind zwar aus Eiern geschlüpft, aber sie liebt sie dennoch so wie Euch Eure Mutter liebt.\n\nSie wird zugleich verzweifelt und wild sein - alles, was Hemet an einem Gegner liebt. Ihr und er, zusammen mit diesem Mammut, solltet Ihr ihr gewachsen sein.\n\nSie hält sich am nördlichen Rand des Wilden Dickichts auf und hungert nach Rache.", progress = nil, completion = "Nun, ich hatte eine komplette Rede vorbereitet, aber der alte Mann höchstpersönlich möchte einige Worte an Euch richten.", rewards = "Umhang des tödlichsten SpielsHemets TrophäengewehrKurzbogen des DrachentötersNesingwarys StrauchwerkbrennerGlänzender ProtodrachenumhangIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12615] = {title = "Der Segen von Zim'Torga", objective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Torga 10 Drakkariopfergaben darbringt.", description = "Verhexer Ubungo hat Euch wahrscheinlich von den Opfergaben an die Götter von Zul'Drak erzählt. Zim'Abwa ist nicht der einzige Gott, der von den Drakkari vergessen wurde.\n\nWir haben unter dem Mantel Zim'Torgas, der Mutter des Wohlstands, Schutz genommen. Es gilt dasselbe wie für Zim'Abwa: Reicht ihr Opfergaben der Drakkari dar und sie wird Euch sicherlich ihren Segen verleihen.", progress = "<Ihr könnt spüren, wie die Augen der Mutter des Wohlstands auf Euch ruhen. Sie fragt sich, was ein <Volk> wie Ihr hier bei Ihr zu suchen hat.>", completion = "&lt;Zim'Torgas Gedanken erfüllen die Euren. Sie spürt die Opfergaben und auch, dass Ihr sie ihr geben wollt. Sie ist erfreut.&gt;\n\n&lt;Sie lässt Euch wissen, dass Ihr dafür angemessen belohnt werdet.&gt;", rewards = "Ihr erlernt:\n\nSegen von Zim'Torga\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12616] = {title = "Kammer der Geheimnisse", objective = "Der Abgesandte der Argentumdämmerung möchte, dass Ihr Tenris Mirkbluts Kammer in den Bedienstetenunterkünften in Karazhan durchsucht.", description = "Ausgezeichnet, ein erfahrener Abenteurer. Genau das, was wir brauchen.\n\nEs gab Gerede unter den Kirin Tor, die Medivhs Turm bewachen, dass etwas in Karazhan nicht stimme. Es ging darum, dass dort drinnen eine neue Macht schlummere, eine Macht, die weder der Magie des Wächters noch der Legion unterstellt sei. Ihren Erkundungen zufolge scheint es, als handle es sich um einen Elfenprinzen namens Tenris Mirkblut; außerdem gäbe es Grund zur Annahme, dass er der Geißel diene.\n\nGeht, mein Freund, untersucht Mirkbluts Kammer und bringt sämtliche Informationen mit, die Ihr finden könnt.", progress = nil, completion = "Wenn die Befehle, die Ihr gesehen habt, echt sind, dann verheißt das, was Ihr gesehen habt, wirklich nichts Gutes. Wir können nur darauf hoffen, dass man ihn aufgehalten hat, ehe der Feind zu viel über unsere Stärken herausgefunden hat.\n\nHabt Dank, &lt;Name&gt;. Möget Ihr sicher sein in diesen dunklen Zeiten.", rewards = "Ihr bekommt:\n\nMonsterjägerausrüstung"}
MultiLanguageQuestData['de'][12617] = {title = "Die Eindringlinge vernichten", objective = "Der Avatar von Freya am Katarakt der Regenrufer möchte, dass Ihr Euch zum Lager der Todeshand im Nordwesten begebt und 8 infiltrierende Kultisten tötet.", description = "Ich bin die Verkörperung von nur einem Aspekt Freyas, Tochter der Titanen. Ich bin die Lebenswächterin - ich wurde hier zurückgelassen, um dieses Land gegen die Bedrohung der Geißel zu schützen.\n\nNie hatte ich geahnt, dass der Lichkönig willige, lebendige Diener aussenden würde, um seine Befehle auszuführen.\n\nIch könnte diese Kultisten mit Leichtigkeit selbst zerschmettern, doch nur ich alleine stehe zwischen den untoten Armeen und dem übrigen Becken. Geht, <Name>, überbringt diesen anmaßenden Eindringlingen meinen Zorn.", progress = nil, completion = "Ihr sprecht die Wahrheit. Die Eindringlinge im Lager wurden beseitigt... aber ich fürchte, es könnte zu spät gewesen sein.", rewards = "Gewandung der LebenswächterinUralter HornhelmTreter des gebundenen LebensHandgelenksschützer der Rache der TitanenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12618] = {title = "Der Segen von Zim'Torga", objective = "<Zim'Torga schaut weiterhin teilnahmslos. Sie fragt sich, ob Ihr durch das Überreichen weiterer Drakkariopfergaben ihr zu Ehren einen weiteren Segen wünscht.>", description = nil, progress = "<Zim'Torga schaut weiterhin teilnahmslos. Sie fragt sich, ob Ihr durch das Überreichen weiterer Drakkariopfergaben ihr zu Ehren einen weiteren Segen wünscht.>", completion = "&lt;Die Mutter des Wohlstands blickt voller Wohlwollen auf Euch herab.&gt;", rewards = "Ihr erlernt:\n\nSegen von Zim'Torga"}
MultiLanguageQuestData['de'][12619] = {title = "Die verzierte Runenklinge", objective = "Geht zu den Waffenregalen in der Schwarzen Festung und sucht nach einem kampferprobten Schwert. Verwandelt es anschließend in einer Runenschmiede zu einem Runenklingenschwert.\n\nBringt das Runenklingenschwert danach zu Instrukteur Razuvious in der Schwarzen Festung.", description = "Das einzig wirklich wichtige Stück Ausrüstung eines Todesritters ist seine Runenklinge. Mit dieser Klinge beherrscht er die Mächte des Frosts, des Blutes und der Dunkelheit. Außerdem dient sie als Gefäß, in dem der Todesritter Runenmacht speichern kann.\n\nDie Zeit ist gekommen, um Eure erste Runenklinge zu erschaffen. Geht zu den Waffenregalen auf der ersten Ebene und sucht nach einem kampferprobten Schwert. Bringt dieses Schwert anschließend zu einer Runenschmiede in der Nähe und verwandelt es in eine Runenklinge.", progress = "Die Runenklinge ist ein Teil von Euch. Ein <Klasse> kann ohne eine Runenklinge nicht kämpfen.", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt es geschafft, Eure erste Runenklinge herzustellen. Mit dieser werdet Ihr Chaos und Zerstörung hervorrufen! Ihr werdet eine Spur des Blutes hinterlassen, ein Schlachtfeld mit den Leichen all derer übersät, die es wagen sollten, sich der Geißel zu widersetzen.", rewards = "Ihr erlernt:\n\nRunen schmieden\n\nIhr bekommt außerdem:\n\nRunenbeschriebene Seelenklinge"}
MultiLanguageQuestData['de'][12620] = {title = "Der Zorn der Lebenswächterin", objective = "Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr auf dem Gipfel der Schimmersäule Freyas Horn blast.", description = "Wir waren nicht schnell genug, <Name>. Diese verdammten Kultisten sind an der Schimmersäule und wollen sie zerstören - ich kann sie spüren.\n\nWir haben nicht viel Zeit. Besteigt die Schimmersäule, und wenn Ihr ganz oben angelangt seid, dann stoßt in das Horn, um meine Energie durch die Säule zu leiten.\n\nWir werden diesem Abschaum schon zeigen, dass mit den Schöpfungen der Titanen nicht zu spaßen ist.", progress = nil, completion = "Beeindruckend. Ich hätte nicht gedacht, dass jemand wie Ihr, der Ihr nur ein Sterblicher seid, sich als so wertvoller Verbündeter erweisen würde.\n\nIch fürchte jedoch, dass wir nicht genug unternommen haben. Denn es scheint nicht so, als wäre es gelungen, der Geißel Einhalt zu gebieten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12621] = {title = "Freyas Pakt", objective = "Hört zu, was der Avatar von Freya zu sagen hat.", description = "Die Kultisten wurden erledigt, doch die Invasion der Geißel nicht aufgehalten. Die Situation wird langsam verzweifelt, <Name>.\n\nEs gibt einen letzten Ausweg. Bevor ich Euch jedoch mehr verrate, muss ich sicher sein, dass Ihr mir vollkommen vertraut.", progress = "Uns bleibt wenig Zeit. Die Geißel rüstet sich zum letzten Schlag.", completion = "Es gibt kein Zurück mehr. Wenn Ihr mir helfen wollt, müsst Ihr dies ohne zu zögern tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12622] = {title = "Die Anführer in Jin'Alai", objective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr den Schatz von Kutube'sa, den Schatz von Gawanil und den Schatz von Chulo dem Verrückten beschafft.", description = "Denkst du auch das, was Ahunae denkt, Mann?\n\nEinige der Drakkaritrolle haben sich bei den Teichen von Jin'Alai im Südwesten versammelt. Wir werden ihre Anführer herauslocken müssen und Ahunae weiß auch ganz genau, wie du das machen wirst!\n\nGeh und töte diese Trolle. Sobald du genug von ihnen getötet hast, werden ihre Anführer aufkreuzen.\n\nWenn sie neben ihren Totems aufkreuzen, dann krall dir auf jeden Fall die Schätze von Kutube'sa, Gawanil und Chulo dem Verrückten, Mann.", progress = "Der <Klasse> muss wieder bei Ahunae sein, weil der <Klasse> alle Schätze gesammelt hat.", completion = "Der Skalpierer denkt, dass du genau sein &lt;Volk&gt; bist!\n\nWas machen denn diese Schokoladenriegel hier drin? Was sollen wir damit machen, Mann?\n\nAhunae sagt, dass du sie wieder zurückhaben kannst!", rewards = "Sandalen des SterndeutersStiefel des großen OpfersGeschmeidiger Gürtel des BlutvergießersAuf Euch wartet eine dieser Belohnungen:\n\nRing der schützenden Ahnen\n\nIhr bekommt außerdem:\n\nSchokoriegel"}
MultiLanguageQuestData['de'][12623] = {title = "Auf zum Hexendoktor", objective = "Sprecht mit Hexendoktor Khufu in Zim'Torga.", description = "Wir Zandalari könnten Eure Hilfe gebrauchen, <Name>. Wir müssen dem, was die Drakkari ihren Göttern antun, ein Ende setzen!\n\nGen Nordosten die großen Stufen hoch in Richtung der nächsten Ebene von Zul'Drak liegt Zim'Torga. Es ist die Heimat einer weiteren Götterstatue und eine Zuflucht, die mein Volk verzweifelt zu verteidigen versucht.\n\nIch hätte gerne, dass Ihr Euch dorthin begebt und mit Hexendoktor Khufu sprecht. Seid jedoch gewarnt, der Ort wird ständig von den Drakkari angegriffen.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Es freut mich, dass Umbungo jemanden gefunden hat, dem er vertrauen konnte.\n\nWillkommen in Zim'Torga.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12624] = {title = "Er könnte überall sein!", objective = "Sucht nach einem goldenen Verlobungsring, den Ihr in den Mägen der verschiedenen Kreaturen im Sholazarbecken finden könnt.", description = "Als ich herausfand, dass Fräulein Boulian Nesingwary bei seiner Expedition half, habe ich mich sofort als Deckmatrose gemeldet. Ihr müsst wissen, dass ich sie schon seit Monaten heiraten wollte!\n\nIch hatte alles geplant. In derselben Nacht, als wir Schiffbruch erlitten, wollte ich um ihre Hand anhalten... doch nun ist der Ring verschwunden. Ich habe überall nach ihm gesucht!\n\nEs mag sich vielleicht verrückt anhören, doch ich weiß, dass sich der Verlobungsring im Sholazarbecken befindet. Wenn niemand von der Venture Company ihn gestohlen hat, vielleicht hat ihn dann irgendeine wilde Kreatur gefressen. Doch er ist dort, irgendwo... Ich weiß es einfach!", progress = "Der Ring, <Name>! Bitte... sagt mir, dass Ihr ihn gefunden habt!", completion = "Ihr habt es geschafft! Ihr habt ihn tatsächlich gefunden!\n\nIch weiß nicht... ich weiß nicht, wie ich Euch danken soll!", rewards = "Schulterstücke der EntschlossenheitStiefel der DominanzUmhang der erneuerten HoffnungAuf Euch wartet eine dieser Belohnungen:\n\nRing des hingebungsvollen Versprechens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12625] = {title = "Herrschaft über Acherus", objective = "Meldet Euch bei Meisterbelagerungsschmied Corvus auf der Etage der Garnison in der Schwarzen Festung.Erblicket Acherus, die große Zitadelle des Todes! Nicht einmal die mächtige Naxxramas könnte einem direkten Angriff der Schwarzen Festung Stand halten.\n\nObwohl Eure Gedanken vielleicht noch vernebelt sind, haben wir keine Zeit zu verlieren. Ihr müsst die Herrschaft über Acherus und Eure Gedanken erlangen! Die Hörner des Krieges erklingen!\n\nNehmt die Treppen auf dieser Etage - im Norden, Süden, Osten und Westen - um zur Garnisonsetage über uns zu gelangen. Sprecht mit Meisterbelagerungsschmied Corvus und besorgt seinen Statusbericht. Dieser muss an Thalanor geliefert werden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Erblicket Acherus, die große Zitadelle des Todes! Nicht einmal die mächtige Naxxramas könnte einem direkten Angriff der Schwarzen Festung Stand halten.\n\nObwohl Eure Gedanken vielleicht noch vernebelt sind, haben wir keine Zeit zu verlieren. Ihr müsst die Herrschaft über Acherus und Eure Gedanken erlangen! Die Hörner des Krieges erklingen!\n\nNehmt die Treppen auf dieser Etage - im Norden, Süden, Osten und Westen - um zur Garnisonsetage über uns zu gelangen. Sprecht mit Meisterbelagerungsschmied Corvus und besorgt seinen Statusbericht. Dieser muss an Thalanor geliefert werden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12626] = {title = "Kompanie der Verdammten", objective = "Liefert Corvus' Bericht bei Geißelkommandant Thalanor auf der Garnisonsebene der Schwarzen Festung ab.", description = "<Corvus salutiert vor Euch.>\n\nUnsere Vorräte an Waffen, Rüstungen und Munition haben schon fast ihre volle Kapazität erreicht. Wir sind nun kriegsbereit!\n\n<Corvus rollt ein fleischiges Stück Pergament aus.>\n\nAuf der anderen Seite der Garnison südwestlich von hier werdet Ihr die Offiziersquartiere vorfinden. Bringt diesen Statusbericht dorthin und übergebt ihn Geißelkommandant Thalanor, dem Bataillonskommandanten der Kompanie der Verdammten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12627] = {title = "Nach Jin'Alai durchkommen", objective = "Hexendoktor Khufu in Zim'Torga möchte, dass Ihr den blauen, grünen, purpurnen und roten Kessel sabotiert.", description = "Ich habe versucht, mit den Göttern Zwiesprache zu halten. Jedoch führen die Medizinmänner bei den Teichen von Jin'Alai Rituale durch, die meine Versuche unterbinden.\n\nEs ist äußerst wichtig, dass wir dieses Hindernis beseitigen. Falls Ihr nach Südwesten in das Gebiet mit den Teichen gehen solltet, dann bin ich mir sicher, dass Ihr die Kessel findet, die sie für ihre Magie verwenden.\n\nSabotiert jeden einzelnen von ihnen und setzt ihrem Ritual ein Ende, denn es hindert mich an meiner Arbeit.", progress = nil, completion = "Ja, ich kann den Unterschied spüren. Habt Dank.\n\nDann lasst uns einmal sehen, ob wir jetzt mit den Göttern Kontakt aufnehmen können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBreaking Through Jin'Alai: Quest Complete Force Cast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12628] = {title = "Mit Har'koa sprechen", objective = "Sprecht mit Har'koa am Altar von Har'koa.", description = "Die Götter haben gesprochen, <Name>. Wir wissen jetzt, was Ihr tun müsst.\n\nIhr müsst jetzt zum Altar von Har'koa im Südosten gehen und mit der Leopardengöttin sprechen.", progress = nil, completion = "Hört gut zu, kleiner &lt;Volk&gt;. Die Zeit drängt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12629] = {title = "Es gibt kein Entkommen", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Monstrositäten, sammelt den Ghulsabber, den Ihr dort finden werdet, und bringt mir ihre Überreste.", progress = "Habt Ihr die Komponenten, um die ich Euch gebeten habe, mitgebracht, <Name>?", completion = "&lt;Stefan inspiziert die faulen Komponenten.&gt;\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, &lt;Klasse&gt;. Jetzt wird's erst richtig spannend...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12630] = {title = "Narsch treten und Haare krümmen", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe von Narsch 10 Haarproben von den siechenden Trollen sammelt.\n\nKehrt zu Stefan zurück, falls Ihr Narsch verlieren solltet, damit er ihn für Euch zurückbekommt.", description = "Bevor Ihr Narsch trefft, solltet Ihr etwas wissen.\n\nIhm wurde mal vor längerer Zeit eine toxische Dosis Seuche verabreicht und nun ist er taub, blind und kann kaum was spüren.\n\nDas hat aber auch sein Gutes. Er ist nun praktisch immun gegen das Zeugs und deshalb für gewisse Aufgaben wie die, die ich Euch gleich geben werde, perfekt geeignet.\n\nIn der Nähe gibt es viele Trolle, die erst kürzlich verseucht wurden, und wir müssen untersuchen, welche Auswirkungen die Seuche auf sie hat. Hier, nehmt Narsch mitsamt diesem Schuh. Gebt ihm einen kräftigen Tritt, nachdem Ihr einen Troll erschlagen habt, und er wird wissen, dass er eine Haarprobe zu nehmen hat.", progress = "Wie sieht's mit dem Schuh aus, <Volk>?", completion = "Wisst Ihr, Ihr erinnert mich unheimlich stark an meinen Narsch.\n\nVielleicht sind es auch nur die Ohren...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKickin' Nass and Takin' Manes: Quest Complete (Force Cast)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12631] = {title = "Eine Art Einladung...", objective = "Bringt den untoten Halsreif zu Stefan in der Schwarzen Wacht.\n\nBereitgestellter Gegenstand: \n", description = "Dieser bluttriefende Halsreif ist aus Knochen gefertigt. Es ist von komplexer Art und wurde für einen bestimmten Zweck hergestellt.\n\nIhr starrt ihn an und werdet von etwas Unheilvollem ergriffen, das Euch dazu zwingen möchte, den Halsreif zu tragen. Ihr kämpft gegen den Drang an und beschließt endlich, ihn zur Schwarzen Wacht zurückzubringen.\n\nWenn irgendjemand eine Erklärung dafür hat, dann ist das ein Todesritter...", progress = nil, completion = "Ich bin in der Tat mit Gegenständen wie diesem vertraut.\n\n&lt;Stefan blickt Euch in die Augen.&gt;\n\nEs scheint, &lt;Name&gt;, als wärt Ihr... auserwählt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12632] = {title = "Aber zunächst meine Jungen", objective = "Har'koa hat Euch gebeten, ihre Barthaare mit den Leichnamen ihrer Kinder zu benutzen und sie wiederzubeleben. Kehrt zu ihr am Altar von Har'koa zurück, sobald Ihr fertig seid.", description = "Ich bin der letzte der Götter, der unterworfen wurde, deshalb müssen wir zunächst versuchen, die anderen zu befreien. Da ich durch die Magie meiner Unterdrücker gebunden bin, ist es mir nicht möglich, zu erkennen, was mit ihnen geschehen ist.\n\nAber zuvor möchte ich Euch um einen Gefallen bitten. Schon jetzt nutzen die Drakkari meine Magie gegen mich. Sie haben meine Jungen in Monster verwandelt.\n\nNehmt eins meiner Barthaare. Erschlagt meine gequälten Kinder und nutzt seine Magie, um sie aus diesem Alptraum zu erwecken und ins Leben zurückzubringen.", progress = "Ich habe noch mehr Kinder, um deren Erlösung von ihren Qualen ich Euch bitte.", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde niemals vergessen, was Ihr getan habt.", rewards = "Handlappen des SterndeutersHose des BlutvergießersMessinghelm des AngreifersAuf Euch wartet eine dieser Belohnungen:\n\nFokus des Spiritisten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12633] = {title = "Die Finsternis ruft", objective = "Bringt Stefan in der Schwarzen Wacht den zuckenden Halsreif.\n\nBereitgestellter Gegenstand: \n", description = "Aus Knochen geschnitzt und bluttriefend, weist dieser Halsreif ein kompliziertes und wohlüberlegtes Design auf.\n\nBeim Betrachten überwältigt Euch eine beunruhigende Aura - eine, die Euch nötigt, es anzulegen. Ihr ringt den Drang nieder und entschließt Euch, es zur Schwarzen Wacht zurückzubringen.\n\nWenn jemand hierfür eine Erklärung hat, dann ein Todesritter...", progress = nil, completion = "In der Tat kenne ich mich mit Gegenständen dieser Art aus.\n\n&lt;Stefan sieht Euch in die Augen.&gt;\n\nEs sieht so aus, &lt;Name&gt;, als seid Ihr… auserwählt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12634] = {title = "Die einen machen Limonade draus, die anderen Schnaps", objective = "Bringt 1 Orange, 2 Bananenbündel und 1 Papaya zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", description = "Das Leben hat mir dieses Mal eine Wagenladung Zitronen beschert! Als das Schiff auf Grund lief, zerbrachen die Krüge mit meinem besten Gebräu! Alles, was wir jetzt noch haben, sind ein paar Flaschen Rum und das stärkt keine durstige Expedition!\n\nWir müssen etwas Alkohol brennen und das schnell!\n\nDie Bäume im Wildwuchsmangal im Osten scheinen überladen mit Früchten zu sein, aber für mich sind sie zu hoch. Sucht nach guten, starken Ranken, mit denen Ihr ein paar dieser Früchte von den Bäumen schütteln könnt. Bringt mir alles, was Ihr finden könnt.", progress = "Hattet Ihr Glück und habt ein paar Früchte von diesen verflucht hohen, knausrigen Bäumen bekommen?", completion = "Gut, das ist eine bessere Auswahl, als ich von diesem Ort erwartet hätte. Nun zur entscheidenden Frage: Können wir daraus etwas Trinkbares destillieren? Wir fangen besser gleich damit an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12635] = {title = "Relikte der Schneeleopardengöttin", objective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 10 Har'koarelikte beschafft.", description = "Ich habe mitbekommen, dass Ihr Euch um das Wohlergehen von Har'koa kümmern werdet. Viel Glück.\n\nIch wollte nur einmal fragen, ob Ihr, während Ihr in der Nähe des Altars seid, nicht ihre Relikte für mich einsammeln wollt? Ich brauche nicht viele und es ist nur ein kurzer Abstecher nach Südosten.\n\nWas sagt Ihr dazu?", progress = "Die Drakkari sind so sehr damit beschäftigt, sich selbst zu zerstören, es wäre schade, wenn auch gleichzeitig die historische Bedeutung ihres Reiches verlorenginge.", completion = "Ahh, erstklassige Exemplare!\n\nIhr könnt hier die Abweichung von den Grundsymbolen erkennen. Ziemlich außergewöhnlich.\n\nWie schade, dass die Eistrolle fest dazu entschlossen scheinen, ihren eigenen Untergang herbeizuführen.\n\nHabt Ihr zum Beispiel gewusst, dass die Drakkari aufgrund ihrer äußerst brutalen Art vom Rest der Trollnationen verbannt wurden?\n\nEs ist wahr! Wie sonst hätten Trolle in solch einem rauen Klima wie hier landen können?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12636] = {title = "Das Auge von Acherus", objective = "Meldet Euch beim Lichkönig in der Schwarzen Festung.", description = "Seht, Acherus, die große Zitadelle des Todes! Seinesgleichen gibt es nur ein Mal auf dieser Welt! Nicht einmal Naxxramas, die mächtige Nekropole, könnte einem direkten Angriff der Schwarzen Festung widerstehen. Über dessen Fassade zeichnet sich drohend das allsehende Auge von Acherus ab. Von dort aus kann sein Meister über große Entfernungen sehen und die Gebiete seiner Feinde ausspionieren. Was das Auge sieht, sieht auch der Lichkönig, und nun ist die Zeit gekommen, dass Ihr durch das Auge blickt! der Lichkönig hat Euch gerufen, <Name>.\n\nGeht nun! Geleidet Euch wohl, <Bruder/Schwester>...", progress = nil, completion = "Der Zeitpunkt, das Blut unserer Feinde zu vergießen, rückt näher. Zuerst müsst Ihr erfahren, was Ihr zerstören wollt, bevor Ihr Euch Hals über Kopf in die Schlacht stürzt.\n\nIch werde Euch Sicht jenseits des Sichtbaren gewähren, mein Champion. Mit dem Auge von Acherus werdet Ihr nun die Geheimnisse unseres Feindes stehlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12637] = {title = "Um ein Haar", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den untoten Halsreif zu Datura Blutrose bringt.", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, <Volk>.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", progress = "Ja, <Volk>?", completion = "Nun habt Ihr gesehen, was Euch beinahe zugestoßen wäre.\n\nWie ich schon zuvor erwähnt habe, war dies kein Zufall. Ein solches Gerät herzustellen, erfordert viel Aufmerksamkeit, und die benötigten Ressourcen würden nicht auf ein zufälliges Ziel verschwendet werden.\n\nIm Grunde genommen ist es so: Die Geißel hat es auf Euch abgesehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12638] = {title = "Eine knappe Sache", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den zuckenden Halsreif zu Datura Blutrose bringt.", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, <Volk>.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", progress = nil, completion = "Nun habt Ihr also gesehen, welches Schicksal Euch gedroht hätte.\n\nWie ich schon erwähnte, war dies kein Zufall. Die Erschaffung eines solchen Apparates ist sehr umständlich. Ihr habt es geschafft, irgendwie die Aufmerksamkeit der Führung der Geißel auf Euch zu ziehen.\n\nDie Frage ist nicht wie, warum oder gar wer,... sondern was wir deswegen tun können?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12639] = {title = "Die gefrorene Erde", objective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 7 Essenzen der gefrorenen Erde beschafft.", description = "Diese Elementare haben wir in der Nähe gefunden und dann eingefangen - nun stehen mir zahlreiche Verteidiger zur Verfügung. Man muss jedoch über erhebliche Kräfte verfügen, um sie stark genug zu machen, damit sie auch gegen unsere Feinde standhalten können.\n\nDie gefrorene Erde bei Drak'Mabwa gen Nordwesten hat genau das, was ich brauche, um unsere Verteidigungen aufrechtzuerhalten. Ich werde noch mehr von ihrer Essenz benötigen, um meine Arbeit weiterhin machen zu können.", progress = "Ich hoffe, dass Ihr genug zurückgebracht habt. Die Angriffe aus den Teichen von Jin'Alai sind verzweifelter geworden, nach dem, was Ihr dort angerichtet habt", completion = "Habt Dank, &lt;Klasse&gt;. Mit diesen Essenzen sollte ich recht lange Zauber wirken können.", rewards = "Gelenkbänder des BlutbindersStulpen des BlutbindersWeicher Helm des BlutbindersAuf Euch wartet eine dieser Belohnungen:\n\nBand des Blutvergießers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12640] = {title = "Die Risse versiegeln", objective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr 7 Elementarrisse verschließt.", description = "Dagoda wird dich nach Nordwesten in Richtung Drak'Mabwa schicken, Mann, damit du dort mehr Zeug für ihre Verteidiger beschaffen kanns', falls sie das nich' schon gemacht hat.\n\nWenn du schon mal da oben bis', dann sollst du für Ahunae die Risse zerstören, aus denen die Elementare strömen. Das Letzte, was wir brauchen können, is', dass sie uns angreifen!\n\nPass bloß auf: Wenn du nämlich versuchst, die Risse zu schließen, dann wird noch mehr dieser gefror'nen Erde auftauchen.", progress = nil, completion = "Ahunae hofft, dass Dagoda alle Verteidiger, die sie haben wollte, bekommen hat. Nun, da die Risse verschlossen sind, wird sie wahrscheinlich keine mehr bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12641] = {title = "Tod kommt von ganz oben", objective = "Der Lichkönig befiehlt Euch, mithilfe des Auges von Acherus die Scharlachrote Festung, die Schmiede von Neu-Avalon, das Rathaus von Neu-Avalon und die Kapelle der Scharlachroten Flamme zu analysieren.\n\nDas Auge von Acherus lässt sich mithilfe der Steuerung für das Auge von Acherus kontrollieren.", description = "Hoch über dieser Plattform ist das Auge von Acherus. Dort werdet Ihr eine Sonde herbeirufen, mit der Ihr dann die Befestigungsanlagen des Scharlachroten Kreuzzugs bei Neu-Avalon analysieren könnt. Das Auge hat jede Menge Kräfte, welche die Beschaffung dieser Informationen einfach gestalten sollten.\n\nAnalysiert mithilfe der magischen Kräfte des Auges die Schmiede, Wacht, Kapelle und das Rathaus. Die Kontrollmechanismen für das Auge befinden sich auf jeder Seite dieser Plattform. Verliert nun keine Zeit mehr, <Name>.\n\nDie Geißel wird diesen Ort einnehmen. Der Lichkönig befiehlt es!", progress = "Unser Angriff auf den Scharlachroten Kreuzzug wird zur Legende werden.", completion = "Sie bereiten sich wie erwartet auf den Kampf vor, doch da ist noch etwas Anderes. Ich spüre die Anwesenheit eines alten Feindes. Ein Feind, den ich vor langer Zeit vernichtet habe...\n\nEs macht nichts. Wir werden sie mit der geballten Macht der Geißel konfrontieren, bevor sie überhaupt die Chance haben, ihre Häuser zu evakuieren und ihre Verteidigungen bereitzustellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12642] = {title = "Der Geist von Rhunok", objective = "Sprecht mit dem Geist von Rhunok am Altar von Rhunok.", description = "Mein Gefühl sagt mir, dass Rhunok nicht viel Zeit bleibt.\n\nIch kann sehen, dass der Geist des arktischen Bärengottes sich bereits von seinem geschwächten Körper gelöst hat. Und es ist sein Geist, mit dem Ihr in Kontakt treten müsst.\n\nSein Altar liegt im Nordwesten, jenseits von Drak'Mabwa.", progress = nil, completion = "Ich bin kurz davor, loszulassen. Ihr müsst Euch beeilen oder es wird alles verloren sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12643] = {title = "Lichtblick", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Ghule und Monstrositäten, die Ihr dort finden werdet, und bringt mir ihre Überreste.", progress = "Habt Ihr die Komponenten gebracht, um die ich Euch gebeten habe, <Name>?", completion = "&lt;Stefan inspiziert die faulen Komponenten.&gt;\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, &lt;Klasse&gt;. Jetzt wird's erst richtig spannend...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12644] = {title = "Destille Wasser sind tief", objective = "Schließt den Destillationsprozess erfolgreich ab und bringt Donnerbräus Dschungelpunsch, wenn er fertig ist, zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", description = "Nun, da wir über die Rohmaterialien verfügen, bereitet mein Assistent den Destillierapparat vor. Er wird den Prozess überwachen, aber ich möchte, dass Ihr dabei helft, alles unter Kontrolle zu behalten. Womöglich denkt Ihr, dass wir einfach alles in den Apparat werfen und gut, aber das stimmt nicht.\n\nZutaten und Hitze müssen immer zu bestimmten Zeiten zugeführt werden, der Druck wiederum zu anderen. Euch bleiben nicht mehr als 10 Sekunden, um rechtzeitig zu reagieren. Sprecht mit \"Schluckspecht\" McManus, sobald ihr bereit seid zu destillieren.", progress = "Und, wie ist es geworden?", completion = "&lt;Schnapsbart schüttelt den Behälter.&gt;\n\nEs ist etwas drin, aber die Millionen-Gold-Frage ist, ob man es auch trinken kann. Ihr geht nirgendwo hin! Ihr seid auch dafür verantwortlich, das Probieren des Produkts zu überwachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12645] = {title = "Der Geschmackstest", objective = "Bietet Hemet Nesingwary, Hadrius Harlowe und Tamara Wackelspross eine Probe von Donnerbräus Dschungelpunsch an. Kehrt anschließend zu Schnapsbart Donnerbräu in Nesingwarys Basislager zurück.", description = "Und nun der Moment der Wahrheit!\n\n<Schnapsbart kichert.>\n\nIch wollte das schon immer mal sagen. Normalerweise würde ich ein neues Getränk bei einem Bankett vorstellen, aber wir können mitten im Dschungel nun mal keins abhalten.\n\nBringt stattdessen Proben zu ein paar guten Freunden und berichtet mir von ihrer Reaktion. Lasst mal sehen, wir wollen auf jeden Fall Hemets Meinung und ebenso Hadrius Harlowes. Sie sind hier im Lager. Ihr solltet auch Tamara Wackelspross beim Landeplatz am See in der Nähe des Beckenzentrums eine Geschmacksprobe anbieten.", progress = "Lasst mich nicht warten, <Name>. Was ist herausgekommen?", completion = "Zwei von drei Kostern sind also zufrieden, hm? Nicht schlecht für einen ersten Versuch. Ganz und gar nicht. Ich denke, ich muss für Tamara als Entschuldigung etwas anderes zusammenrühren.\n\nHm... wie sollten wir diese Kreation nennen?", rewards = "Ihr bekommt:\n\nKungaloosh"}
MultiLanguageQuestData['de'][12646] = {title = "Der Feind mein Prophet", objective = "Der Geist von Rhunok am Altar von Rhunok möchte, dass Ihr sein Mojo des arktischen Bärengottes wiederbeschafft.", description = "Mein Prophet hat zu viel von meiner Kraft zu schnell absorbiert und sich dadurch selbst getötet. Ihr könnt das Ergebnis in den mit Wasser gefüllten Kratern gen Süden in Drak'Mabwa sehen.\n\nMeine früheren Priester haben ihn schon wiedererweckt, damit er zu Ende bringen kann, was er angefangen hat. Sie speisen ihn mit meiner Kraft und es wird nicht mehr lange dauern, bis er wieder erwacht.\n\nIhr müsst ihm ein Ende bereiten und mein Mojo zurückbringen, bevor es zu spät ist.", progress = "Schnell, <Volk>, sagt mir, habt Ihr mein Mojo?", completion = "Ihr habt es geschafft.\n\nEs gibt jedoch noch eine andere Angelegenheit, die Ihr für mich erledigen müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12647] = {title = "Dem Leid ein Ende bereiten", objective = "Der Geist von Rhunok möchte, dass Ihr das Rauchwerk des Foltermeisters dazu einsetzt, um seinen Körper zu erwecken. Danach sollt Ihr Rhunok mithilfe der Macht, die sein Geist Euch verliehen hat, töten.\n\nFalls aus irgendeinem Grund die Aura für das Mojo von Rhunok von Euch weichen sollte, dann könnt Ihr zum Geist von Rhunok zurückkehren und Euch wieder segnen lassen.", description = "Mein Körper ist jetzt zu weit entfernt, <Name>. Es ist nur eine Frage der Zeit, bis ein neuer Prophet erkoren wird und das zu Ende bringt, was die anderen begonnen haben.\n\nIch werde Euch meine letzten Kräfte verleihen. Der Foltermeister im Inneren des Altargebäudes hat ein Rauchwerk bei sich, das meinen Körper erwecken und wieder verwundbar machen wird.\n\nMacht von dem Rauchwerk Gebrauch und seid so nett und bereitet meinem Leid ein Ende.\n\nIch entschuldige mich schon einmal im Voraus, falls ich mich wehren sollte. Der Wille zu überleben ist selbst bei mir stark ausgeprägt.", progress = "Wenn Ihr nicht schon bald meinem Leiden ein Ende bereitet, <Name>, dann könnte alles zu spät und verloren sein.", completion = "Ihr habt getan, was getan werden musste, und mir damit gleichzeitig Ehre erwiesen.\n\nTiefsten Dank, &lt;Name&gt;. Ich hoffe nur, dass Ihr und Har'koa in der Lage sein werdet, den anderen zu helfen.", rewards = "Schulterpolster des BlutbindersGürtel des BlutbindersTuch des BlutvergießersAhnenbrustplattenDer folgende Zauber wird auf euch gewirkt:\n\nAn End to the Suffering: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12648] = {title = "Leger kleiden", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält, ist es Euch möglich, Euch ungestört unter ihnen zu bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen - nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif, besucht den Händler der Geißel gleich östlich von hier und bringt mir von dort eine Flasche bitteres Plasma mit.", progress = "Nun, <Name>?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12649] = {title = "Anziehen!", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält könnt Ihr Euch ungestört unter ihnen bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen. Nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif und besucht den Händler der Geißel gleich östlich von hier. Bringt mir von dort eine Flasche bitteres Plasma mit.", progress = "Nun, <Name>?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12650] = {title = "Eigene Artefakte plündern", objective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 7 Rhunokianartefakte beschafft.", description = "Es gibt noch einen Altar in der Nähe, wo es Artefakte zu retten gibt.\n\nMan sagt, dass die Drakkari im Altar von Rhunok im Nordwesten jenseits der zerstörten Tundra von Drak'Mabwa schon so weit sind, dass sie ihre eigene heilige Stätte plündern.\n\n<Klasse>, ich wäre Euch sehr dankbar, wenn Ihr diese Artefakte retten und sie ihren unwürdigen Händen entreißen könntet.", progress = "Man kann die Drakkari einfach nicht verstehen. Sie sind nichts weiter als brutale Barbaren, die noch tiefer gesunken sind.", completion = "Lasst mich einen Blick auf sie werfen.\n\n&lt;Der Chronist untersucht die Artefakte, die Ihr gebracht habt.&gt;\n\nHmpf, ich würde einmal sagen, dass wir uns glücklich schätzen können, dass Ihr diese hier aus ihrem Besitz befreit habt, &lt;Klasse&gt;.\n\nWie überaus interessant. Dieses Artefakt hier zeigt die Ereignisse während der Teilung. Es war einmal eine Zeit, als Nordend den nördlichsten Teil von Kalimdor darstellte.\n\nDoch nach der Teilung brach das Land vom Rest ab und wurde schließlich zu dem Kontinent, den wir heute Nordend nennen.\n\nDas ist natürlich der Grund dafür, wieso die Drakkari hier und auf den südlichen Kontinenten vorzufinden sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12651] = {title = "Landeplatz am See", objective = "Sprecht mit Tamara Wackelspross am Landeplatz am See.", description = "Als der Ärger mit der Venture Company begann, bat ich Marvin Wackelspross und seine Frau Tamara, ihre Flugmaschinen nach Osten an den Flussnabel zu verlegen. Außerdem sollten sie dort ein kleines Lager aufbauen, damit wir es als Stützpunkt zum Einfliegen von Vorräten und zur Beobachtung des Gebiets nutzen können.\n\nSie sollten inzwischen angekommen und mit dem Aufbau beschäftigt sein. Der Flussnabel ist in der Nähe der Beckenmitte, wo die Flüsse ineinanderfließen. Sucht nach dem Landeplatz am See am nordöstlichen Ufer. Marvin erwähnte, dass dies der beste Platz sei.", progress = nil, completion = "Hemet schickt Euch also? Wir wollten ihn gerade benachrichtigen, dass wir hier alles aufgebaut und zum Laufen gebracht haben. Bitte verzeiht Marvin, falls er Euch ignoriert, aber er ist immer sehr versunken in seine Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12652] = {title = "Gebt dem Ghul Zucker", objective = "Knorpelsack an der Reliquie der Pein möchte, dass Ihr die Schüssel voll sämigem Hirn mit Kutteln in der Nähe von 10 zerfallenden Ghulen benutzt.", description = "Komm ma' her, Ghuul! Jep, mit dir red ich.\n\nIs' jetzt Fudderzeit. Muss all das Zeuch all den Ghuul'n bring'n!\n\nIs' diesma' schpessial Fudder, jawoll, ja! 'Ne Schüssel voll sämigem Hirn mit Kuddeln… Mjam, mjam, mjam.\n\nEinfach Schüssel neben Ghuul fall'n lass'n. Gut, um Freunde zu find'n.\n\nHabt Ihr Ghuulfreunde? Ha, ha, ha?", progress = "Fertich mit Ghuuls füddern?", completion = "Mjam, mjam!", rewards = "Erdige HosenAlte MonstrositäteneingeweideZweimal verdaute schwere KettenrüstungsteileGeschnitzter KnochenhelmAuf Euch wartet eine dieser Belohnungen:\n\nVersteinerter Ghulfinger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12653] = {title = "Zurück zu Har'koa", objective = "Sprecht mit Har'koa am Altar von Har'koa.", description = "Und nun ist es für Euch an der Zeit, zur Leopardengöttin zurückzukehren. Irgendwie spüre ich, dass sie andere Pläne für Euch hat.\n\nSagt Ihr, was auch immer kommt, wir sind ewig.", progress = nil, completion = "&lt;Die Katzengöttin heult auf vor Schmerzen.&gt;\n\nMeine Seele ist erfüllt von Kummer über den Verlust eines weiteren Freundes. Aber fürchtet Euch nicht, er wird zurückkehren und sein Geist wird für immer leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12654] = {title = "Der Teilzeitjäger", objective = "Bringt Pechs Überreste zu Tamara Wackelspross am Landeplatz am See.", description = "Als Hemet mich bat, Marvin hierher zu begleiten, hoffte ich, dass ich Gelegenheit fände, zwischen dem Reparieren der Flugmaschinen und dem Aufbauen des Lagers meine Jagdfähigkeiten zu verbessern.\n\nIch wollte einen wilden Löwen namens Pech erlegen. Angeblich lebt er südlich von hier, nahe der Stelle, wo der Wildwuchsmangal auf die nördliche Seite der Himmelszeltsäule trifft. Wenn Ihr die Kreatur findet, könntet Ihr mir ihre Überreste bringen? Wenn die Gerüchte wahr sind, ergeben sie eine Trophäe, vor der selbst Hemet Respekt hätte!", progress = "Habt Ihr Pech gefunden?", completion = "Ihr habt sie! Nun muss ich daraus nur noch eine Trophäe herstellen. Das wird der harte Teil - einen Weg zu finden, das Ganze so zu präparieren, dass Hemet sich nicht auf meine Kosten lustig macht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12655] = {title = "Der Segen von Zim'Rhuk", objective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Rhuk 10 Drakkariopfergaben darbringt.", description = "Es gibt noch einen vernachlässigten Gott in Zul'Drak.\n\nZim'Rhuks Statue befindet sich direkt im Norden. Er ist als \"der Weise\" bekannt und auch dafür, dass er sehr beschützerisch ist, wenn es um sein Reich geht. Er unterhält Wächter, die jeden die Rute spüren lassen, der nicht schlau genug ist, um ungesehen an ihnen vorbeizuschleichen.\n\nGeht den Wächtern aus dem Weg und gebt Zim'Rhuk die Drakkariopfergaben, damit Ihr Euch seinen Segen zunutze machen könnt.", progress = "<Ihr spürt, dass Zim'Rhuk Euch kein Vertrauen entgegenbringt. Er ist kurz davor, einen seiner Wächter herbeizurufen.>", completion = "&lt;Zim'Rhuk akzeptiert die Opfergaben, die Ihr ihm zu Füßen legen möchtet, obwohl er weiß, dass Ihr sie den Leichen anderer abgenommen habt.&gt;\n\n&lt;Ihr reicht ihm die Opfergaben dar, worauf er kurz zögert, zustimmt und Euch dann schließlich seinen Segen erteilt.&gt;", rewards = "Ihr erlernt:\n\nSegen von Zim'Rhuk\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12656] = {title = "Der Segen von Zim'Rhuk", objective = "<Zim'Rhuk ist beeindruckt und frustriert, dass Ihr anscheinend wieder einmal seinen Wächtern durch die Finger gegangen seid - zumindest für den Moment.>\n\n<Platziert die Gaben zu seinen Füßen und er wird Euch abermals seinen Segen gewähren.>", description = nil, progress = "<Zim'Rhuk ist beeindruckt und frustriert, dass Ihr anscheinend wieder einmal seinen Wächtern durch die Finger gegangen seid - zumindest für den Moment.>\n\n<Platziert die Gaben zu seinen Füßen und er wird Euch abermals seinen Segen gewähren.>", completion = "&lt;Zim'Rhuk zwingt Euch eine Vision auf, in der einer seiner Wächter Euch unter seinen Füßen zerquetscht. Vielleicht solltet Ihr versuchen, Zim'Rhuk zu besänftigen und ihm noch mehr Opfergaben darzubringen.&gt;", rewards = "Ihr erlernt:\n\nSegen von Zim'Rhuk"}
MultiLanguageQuestData['de'][12657] = {title = "Die Macht der Geißel", objective = "Der Lichkönig gebietet Euch, seine Befehle zu Hochlord Darion Mograine in der Schwarzen Festung zu bringen.\n\nBenutzt den leuchtenden Transporter, der sich hinter dem Lichkönig befindet, um zu Hochlord Darion Mograine in die Hallen des Befehls zu gelangen.", description = "Hört gut zu, Todesritter, denn was ich Euch mitzuteilen habe, wird einen Krieg auslösen. Mein endgültiges Urteil ist gesprochen: Tod - Allen. Niemand, der die Unverschämtheit besitzt, sich gegen die Macht der Geißel zu stemmen, darf ungeschoren davonkommen!\n\nIhr habt mir bei Eurer ersten Aufgabe gut gedient, also sollt Ihr mir auch bei Eurer nächsten Aufgabe gut dienen. Bringt mein Urteil, meinen Befehl zu Hochlord Mograine. Er befindet sich auf der ersten Etage des Kommandopostens von Acherus. Sagt ihm, dass er den Angriff einleiten soll.\n\nUnd wenn der Scharlachrote Kreuzzug erst einmal beseitigt ist, werden wir uns um die Argentumdämmerung kümmern.", progress = nil, completion = "Die Hörner des Krieges werden schon bald über dieses Land erschallen, sie werden die Toten erwecken und die Kriegsmaschine der Geißel ins Rollen bringen. Leid komme über diejenigen, die sich uns in den Weg stellen!\n\nIhr und Eure Brüder werdet den Angriff leiten, &lt;Name&gt;. Und wenn ich das nächste Mal einen Blick auf die Lande des Scharlachroten Kreuzzuges werfen werde, so werden mir die Legionen von Acherus die Sicht nehmen. Der Marsch auf Neu-Avalon beginnt.", rewards = "Ihr erlernt:\n\nHerrschaft über Acherus\n\nIhr bekommt außerdem:\n\nKlingenbewehrtes schwarzes Amulett"}
MultiLanguageQuestData['de'][12658] = {title = "Mein Kuschelroc", objective = "Bringt Spleenix bei Dorians Außenposten 7 Eier eines Rocs.", description = "Dorian ließ mich die von ihm gefangenen Drachenjungen ausbilden und füttern und das hat mich ins Grübeln gebracht. Ich möchte einen eigenen Begleiter!\n\nNein, keinen jungen Drachen. Ich möchte keinen Begleiter, der mir die Hand abbeißen kann!\n\nAllerdings gibt es in den Knochenfeldern nordöstlich des Lagers jenseits des von Drachen dominierten Gebiets eine große Menge Blutklauenrocs. Die ausgewachsenen lassen sich wohl nicht mehr zähmen, aber wenn Ihr mir die Eier aus ihren Nestern bringt, kann ich sie vom Moment des Schlüpfens an großziehen.", progress = "Habt Ihr diese Eier?", completion = "Oh, die sind wirklich schön! Ich bin die Gesellschaft mechanischer Eichhörnchen und Hühner so leid. Es wird wundervoll sein, einen Begleiter zu haben, dessen Gelenke nicht geölt werden müssen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12659] = {title = "Skalpe!", objective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr Ahunaes Messer benutzt, um 10 Heb'Drakkartrolle zu skalpieren.\n\nDer Skalpierer erinnert Euch daran, sie zuerst auszuplündern.", description = "Ich glaub', es is' an der Zeit, ein wenig zu skalpieren, Mann!\n\nDie Trolle von Heb'Drakkar eignen sich gut für so was. Mit ihren schicken Knüppeln und ihren Angriffen wollnse's ja gar nich' anders!\n\nUnd Ahunae gibt dir sogar sein Messer, damit du den Job richtig gut machen kannst.", progress = nil, completion = "Oh, das is' zu komisch.\n\n&lt;Name&gt; is' ein &lt;Volk&gt; ganz nach mei'm Geschmack!\n\nHast du noch mein Messer?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12660] = {title = "Vernichtungswaffen", objective = "Der Avatar von Freya möchte, dass Ihr zum Lager der Todeshand in den Nordwesten geht und 4 Stück des instabilen Sprengstoffs zerstört.", description = "Die Lakaien des Lichkönigs haben es gewagt, Vernichtungswaffen in meine Lande zu bringen. Dies werde ich nicht tolerieren.\n\nGeht zu ihrem Außenposten im Norden und zerstört die Waffen, die sie gegen das Land einsetzen wollen. Wir dürfen nicht zulassen, dass die Geißel auch nur einen Zoll dieser heiligen Länder besudelt.", progress = nil, completion = "Ich danke Euch, &lt;Volk&gt;. Es ist gut, in Euch einen Verbündeten zu wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12661] = {title = "Als Spion nach Voltarus", objective = "Stefan möchte, dass Ihr Euren bezauberten Halsreif benutzt, um Euch in Voltarus einzuschleichen und dort alles zu tun, was der Anführer der Geißel von Euch verlangt.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und besorgt Euch einen neuen.", description = "Ihr habt die Einzelheiten meines Plans sicher bereits erraten.\n\nWir setzen das Interesse, das die Geißel an Euch hat, gegen sie ein. Ihr schleicht Euch verdeckt hinein. Ich weiß, dass dies vermutlich den Tod bedeutet, aber wenn wir nichts tun, so ist Euer Tod ganz gewiss.\n\nReist nach Nordosten zum Reliquiar des Schmerzes und stellt Euch auf die Plattform, nachdem Ihr Euch verkleidet habt. Einmal in Voltarus, müsst Ihr das Vertrauen des Geißelkommandanten erlangen.\n\nBlast dieses Horn, wenn Ihr Eure Mission abgeschlossen habt, und ich werde zu Euch fliegen, um den Bericht entgegenzunehmen.", progress = nil, completion = "Nun gut… Ich muss zugeben, ich bin schon etwas überrascht, Euch zu sehen, &lt;Name&gt;.\n\nSagt, was habt Ihr in Erfahrung bringen können?", rewards = "Sandalen der SpionageSubtile FaustStulpen des GeheimagentenGelenkbänder des DoppelagentenTuch der DuplizitätIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12662] = {title = "Heb'Jin erledigen", objective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr Heb'Jin tötet.", description = "<Dagoda sieht Ahunae an und seufzt.>\n\nIhr wollt Euch wirklich um Heb'Drakkar kümmern? Einfach nur Skalps zu sammeln, wird nicht genug sein. Ihr müsst ihren Anführer Heb'Jin ausschalten.\n\nDas Problem ist nur, dass er oben auf dem Fledermaushorst steht und von dort seine Truppen antreibt.\n\nSchlagt seine Trommel und ich versichere Euch, dass er herunterkommen wird. Das ist der Moment, in dem Ihr ihn töten könnt.\n\nNehmt doch auch dieses Netz hier - wir haben es von seinen Kopfgeldjägern. Fangt damit seine Fledermaus ein, nachdem sie gelandet ist. Auf diese Weise müsst Ihr nicht beide bekämpfen.", progress = nil, completion = "Ihr habt es geschafft!\n\n&lt;Dagoda gibt Euch einen fetten Schmatzer auf die Wange.&gt;\n\nIhr könnt Euch gar nicht vorstellen, wie mich das erleichtert! Die Trolle greifen uns von allen Seiten an und uns dagegen zu verteidigen, setzt uns wirklich unter Druck - von seinem ununterbrochenen Geschrei ganz zu schweigen.\n\nBitte, &lt;Name&gt;, sucht Euch von dem hier etwas aus.", rewards = "Gamaschen des RitualsStulpen des AltarsGeschmeidiger Mantel des BlutvergießersAuf Euch wartet eine dieser Belohnungen:\n\nBand des nebligen Mojo\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12663] = {title = "Wiedervereint", objective = "Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht.", description = "<Name>!\n\nDu musst mein Geschenk bekommen haben! Dreh dich um, Mann, und lasst mich dich mal ansehen... Ahhh, du machst mich stolz.\n\nWir haben viel hinter uns, du und ich, und nun werden wir beide dem Lichkönig dienen.\n\nHalt dich an mich und du wirst davon profitieren, Mann. Profitieren... doch zuerst müssen wir dich auf den neuesten Stand bringen. Viel ist passiert, seitdem wir uns das letzte Mal gesehen haben.\n\nGeh und sprich mit Grindbruch, damit er dich auf einen Rundflug über Zul'Drak mitnimmt. Hör mir zu und du wirst alles erfahren, was du wissen musst.", progress = nil, completion = "So, nun weißt du, was uns gegenübersteht, Mann.\n\nGeh hinunter, lass dir etwas Zeit, lern das Land kennen und denk dir irgendeine Strategie aus.\n\nIch werde schon bald ein paar Aufgaben für dich haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKill Credit"}
MultiLanguageQuestData['de'][12664] = {title = "Dunkler Horizont", objective = "Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht.", description = "Ahh, noch ein Bittsteller, der des Lichkönigs Ruf gefolgt ist.\n\n<Drakuru schnüffelt an Euch.>\n\nFrisch verseucht, hm? Du riechst noch immer wie die Lebenden!\n\nDie Reihe derer, die den Segen des Lichkönigs suchen, ist lang. Du musst dich von den Massen abheben und beweisen, dass du wahrer Macht würdig bist.\n\nAls ich über Zul'Drak hinweg sah, konnte ich spüren, dass etwas in dir steckt. Ich war es, der dich zu uns \"einladen\" ließ.\n\nDer Rest liegt an dir...\n\nGeh und sprich mit Grindbruch und er wird dich auf einen Rundflug über Zul'Drak mitnehmen. Es wird viel zu tun geben, wenn du überhaupt irgendeinen Wert für mich besitzen willst.", progress = "Hast du dir das Schlachtfeld schon angesehen, Mann?", completion = "So, nun weißt du, was uns gegenübersteht, Mann.\n\nIch möchte, dass du hinunter gehst, das Land kennenlernst und dich unter deine Brüder mischst. Sei bereit...\n\nSchon bald wird es viel für dich zu tun geben. Enttäusch mich bloß nicht!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKill Credit"}
MultiLanguageQuestData['de'][12665] = {title = "Ich spüre eine Erschütterung", objective = "Har'koa hat Euch gebeten, herauszufinden, was mit Quetz'lun geschehen ist. Sprecht mit ihr, um heimlich auf einem ihrer Kinder zum Altar von Quetz'lun zu reiten.\n\nKehrt zu ihr am Altar von Har'koa zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Etwas ist nicht in Ordnung mit Quetz'lun, der Windnattergöttin. Was genau es ist, vermag ich nicht zu sagen, aber ich weiß, dass ihr Altar von mächtigen Kreaturen überrannt wurde.\n\nIch werde Euch dorthin auf dem Rücken eines meiner von Euch geretteten Kinder entsenden. Zusammen werdet Ihr Euch schnell und verstohlen bewegen können, um das Rätsel um Quetz'luns Schicksal zu lösen.\n\nMein Kind wird Euch sicher zu mir zurückbegleiten. Haltet nur Eure Augen offen.\n\nSobald Ihr bereit seid, sagt Bescheid und ich werde eins meiner Kätzchen rufen.", progress = "Warum die Verzögerung, <Name>?", completion = "Ich danke Euch, dass Ihr mein Kätzchen sicher zurückgebracht habt.\n\nTief in meinem Inneren wusste ich es bereits. Ich habe versucht, es zu leugnen, aber Eure Augen haben die Wahrheit ans Licht gebracht.\n\nTrotzdem spüre ich noch etwas Anderes. Es ist nicht alles so, wie es scheint.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12666] = {title = "Vorbereitungen für die Unterwelt", objective = "Har'koa am Altar von Har'koa möchte, dass Ihr 8 Stück heiliger Zier sammelt und sie anschließend bei ihr abliefert.", description = "Quetz'lun mag vielleicht tot sein, doch ich kann ihren Geist noch immer spüren: Sie ist in der Unterwelt bei ihrem Altar. Wir müssen herausfinden, wie wir Euch dorthin bringen können.\n\nWie es das Glück so will, steht mir eine Anzahl einstiger Bittsteller zur Verfügung, die nicht länger ihre heilige Zier benötigen. Meine Unterdrücker und Klauen werden sie höchstwahrscheinlich noch immer tragen.\n\nBringt mir diesen Schmuck und ich werde Euch mithilfe seiner Energie ein Tor zu Quetz'luns höllischer Unterwelt öffnen.", progress = "Ich hätte niemals geglaubt, dass es dazu kommen würde - die Drakkari sind wahrhaftig verloren.", completion = "&lt;Die Leopardengöttin blickt traurig auf die vor ihr liegende Sammlung heiliger Symbole.&gt;\n\nEs gab eine Zeit, als diese hier noch etwas zu bedeuten hatten... Sehen wir einmal, ob wir sie zu einem besseren Zweck einsetzen können", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDer Atem von Har'koa\n\nIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12667] = {title = "Sucht die Windschlangengöttin auf", objective = "Geht zum Altar von Quetz'lun und sucht Quetz'luns Geist auf.", description = "Ihr seid nun zwar bereit, doch ich bin mir nicht sicher, ob Ihr auch für das gewappnet seid, was denn kommen wird.\n\nWenn Ihr Euch zurück in den Bereich von Quetz'luns Altar begebt, dann werdet Ihr damit auch das Reich des Todes betreten. Ich hab's so im Gefühl, dass es kein angenehmer Aufenthalt sein wird.\n\nVersucht, Euch von den Dingen dort drinnen nicht ablenken zu lassen. Geht einfach nur in Richtung Altargebäude und sucht Quetz'luns Geist auf.", progress = nil, completion = "Du Wurm. Sag mir, wieso ich dich nicht an Ort und Stelle vernichten soll?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12668] = {title = "Den Weg zur Rache ebnen", objective = "Quetz'luns Geist am Altar von Quetz'lun hat Euch damit beauftragt, in der Nähe ihrer Seelenbrunnen 12 Trolle zu töten. Diese können entweder Anbeter von Quetz'lun oder schlangengebissene Berserker sein.\n\nKehrt erst dann wieder zu ihr zurück, wenn Ihr Eure Aufgabe erfüllt habt.", description = "Ich habe etwas Besonderes für meine Lieblingshohepriester geplant. Doch zuerst werdet Ihr den Grundstein für meine Rache legen und Euch somit beweisen.\n\nIhr wollt doch am Leben bleiben, oder?\n\nWie Ihr gesehen habt, genießen meine Verehrer ihren hiesigen Aufenthalt. Doch nun ist die Zeit gekommen, dass sie ihre letzte Schuld begleichen müssen.\n\nTut mir doch einen klitzekleinen Gefallen, <Name>: Lockt sie in die Nähe meiner Seelenbrunnen und macht ihrem Dasein ein Ende.\n\nSie schmecken gar köstlich - und ihr Opfer wird nicht umsonst gewesen sein, das kann ich Euch versichern.", progress = "Wieso kehrt Ihr schon zurück, obwohl Eure Aufgabe noch nicht erfüllt ist? Erkennt Ihr denn nicht, dass nur ein einziger Gedanke von mir genügt, um Euch zu zerstören?\n\nGeht nun, kleiner <Volk>. Führt meinen Befehl zu Ende!", completion = "Exquisit. Vielleicht seid Ihr doch zu etwas zu gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12669] = {title = "So weit, so schlecht", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zu Drakuru zurückkehrt und alles tut, was er von Euch verlangt.\n\nWährend Ihr beim Reliquiar des Schmerzes seid, sollt Ihr die Verdünnungslösung in 5 Seuchenkessel schütten.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", description = "Alles, was Ihr mir berichtet habt, stimmt mit unseren Informationen überein. Etwas über Drakuru zu erfahren und sein Vertrauen zu gewinnen, stellt die Basis für Eure zukünftigen Missionen dar.\n\nKehrt zu ihm zurück und macht, was er sagt. Tut alles, was nötig ist, um glaubwürdig zu erscheinen, <Name>. Vieles hängt davon ab, wie Ihr Euch macht.\n\nDoch dieses Mal werdet Ihr eine zusätzliche Aufgabe bekommen: Gießt diese Lösung in ihre Seuchenkessel dort draußen. Dadurch sollte ihr Seuchenwirkstoff neutralisiert und ihre Ladung unbrauchbar gemacht werden.", progress = "<Name>, bitte sagt mir, dass Eure Tarnung nicht aufgeflogen ist...", completion = "Gute Arbeit, &lt;Name&gt;!\n\nDas Zeug in den Kesseln zu verdünnen, wird nicht nur Leben retten, sondern auch dafür sorgen, dass sich die Geißel in dieser Region nicht so schnell verbreitet.\n\nNun kommt schon, erzählt mir, was Ihr über Drakurus Strategie in Zul'Drak erfahren habt.", rewards = "Kordeln der DuplizitätFragile Stiefel des SpitzelsHelm des leisen WispernsSchild des InfiltratorsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12670] = {title = "Die Scharlachrote Ernte", objective = "Meldet Euch bei Prinz Valanar bei der Todesbresche.", description = "Unterhalb von Acherus befindet sich die Todesbresche, die Bühne, auf der unser Angriff auf den Scharlachroten Kreuzzug stattfinden wird. Schwingt Euch auf einen meiner Geißelgreifen, die auf beiden Seiten dieser Plattform zu finden sind, und meldet Euch bei Prinz Valanar. Tut, was er sagt, und Ihr möget den Tag erleben, an dem diese Länder unter unsere Herrschaft fallen werden.", progress = nil, completion = "Riecht Ihr das?\n\n&lt;Valanar macht einen kurzen Atemzug.&gt;\n\nFrisches Fleisch… Der Geruch des Scharlachroten Kreuzzugs liegt in der Luft.\n\nEntschuldigt, &lt;Klasse&gt;, ich bin sicher, dass Ihr nicht interessiert seid an meiner Art der feinen Küche. Ihr seid hier, um zu arbeiten! Um den Angriff anzuführen! Ja... ich weiß. Der Lichkönig hat mir alles erzählt, was ich über Euch wissen muss, &lt;Name&gt;.\n\nDie Zeit ist gekommen, um Blut zu vergießen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12671] = {title = "Aufklärungsflug", objective = "Helft Pilot Vic den Aufklärungsflug abzuschließen.", description = "Es wird Zeit, dass wir hier Flugzeuge zum Laufen bringen. Die Professorin hat mich gebeten, das seltsame Wetterphänomen im Nordosten zu untersuchen.\n\nDie Sache ist, dafür brauche ich einen Copiloten, wenn wir in unbekanntes Territorium fliegen. Keine zehn Pferde bekommen mich da alleine hin.\n\nWas meint Ihr, Heißsporn? Vielleicht lernt Ihr noch ein oder zwei Dinge dazu. Und wenn Ihr erstmal lernt, mit den Winden des Nordens umzugehen... dann könnt Ihr so ziemlich überall fliegen.", progress = nil, completion = "Ihr habt mir da oben das Leben gerettet, Kumpel. Nette Flugkünste!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12672] = {title = "Wegbereiter", objective = "Quetz'luns Geist verlangt, dass Ihr 10 Fragmente unterweltlicher Macht sammelt. Kehrt zu ihr zum Altar von Quetz'lun zurück, wenn Euch dies geglückt ist.", description = "Ich werde Euch die Chance geben, Eure Existenz noch ein wenig zu genießen.\n\nFragmente der Kraft, die meinem Fluch Nahrung gaben, sind über den Altarboden verteilt. Es ist mein Wunsch, dass Ihr einige davon für mich aufsammelt. Nicht so viele, dass mein Fluch aufgehoben wird, aber genug, dass es mir schließlich gelingen wird, Rache an meinem Propheten zu üben.\n\nGeht, Insekt. Lauft und erfüllt meine Befehle, bevor ich meine Meinung darüber ändere, Euch am Leben zu lassen.", progress = "Eine Schande, dass Har'koa Euch nicht früher vorbeigeschickt hat. Auf der anderen Seite haben wir uns nie besonders gut verstanden.\n\nSie hat Eure Hilfe vermutlich einfach nur lange genug zurückgehalten, damit das hier geschieht.", completion = "Mit diesen wird es funktionieren. Wahrscheinlich brauche ich sie allerdings sowieso nicht.\n\nAber es hat Spaß gemacht, Euch nach meiner Pfeife tanzen zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12673] = {title = "Nach oben buckeln, nach unten treten", objective = "Oberanführer Drakuru in Voltarus möchte, dass Ihr das Szepter der Suggestion auf die Seuchenspuke anwendet und sie dann 7 Seuchenkristalle sammeln lasst.", description = "Wenn du es jemals wert sein willst, die Geschenke des Lichkönigs zu erhalten, dann musst du lernen, ein großer Anführer zu sein - einer, der Respekt abverlangt!\n\nIch habe eine Aufgabe für dich, die deine Fähigkeit zu Führen verfeinern wird, Mann...\n\nEinige meiner Diener sind dazu ausgebildet, Seuchenkristalle in dem Gebiet unter uns zu sammeln, doch sie sind faul und arbeiten nur langsam. Du wirst die Leitung über sie haben, Mann.\n\nNimm dieses Szepter und zeig ihnen, wie man die Arbeit richtig macht. Lass sie die Kristalle sammeln, sobald sie unter deiner Kontrolle sind!", progress = "Wurden meine Untergebenen von dir zurechtgepeitscht, <Name>?", completion = "Wir werden mehr Kristalle haben als je zuvor!\n\nMach weiter so, &lt;Name&gt;. Ich werde schon bald noch mehr Aufgaben für dich haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12674] = {title = "Zornentbrannte Hölle", objective = "Quetz'luns Geist am Altar von Quetz'lun möchte, dass Ihr Quetz'luns Verhexungsstecken auf Hohepriester Mu'funu, Hohepriester Tua-Tua und Hohepriester Hawinni anwendet. Anschließend sollt Ihr sie vernichten.", description = "Es ist nun Zeit, dass Ihr meine drei Hohepriester Mu'funu, Tua-Tua und Hawinni bestraft. Sie befinden sich alle irgendwo im Altargebiet verstreut.\n\nNehmt diesen Verhexungsstecken - er ist von meinem Zorn und Unwillen erfüllt. Ich bin mir sicher, dass er ein effektives Werkzeug sein wird.\n\nIhr müsst ihn einfach einsetzen und sie anschließend vernichten. Der Hex wird sich dann um den Rest kümmern.\n\n<Quetz'lun grinst über beide Ohren.>\n\nHabt Erfolg und ich werde Euch womöglich gehen lassen - versagt und Ihr werdet sterben.", progress = "DENKT IHR ETWA, DASS ICH EIN IDIOT BIN?\n\nSIE SIND NICHT TOT!", completion = "&lt;Der schreckliche Geist vor Euch gibt ein Gekicher von sich, das Euer Blut gefrieren lässt.&gt;\n\nSie hätten damit rechnen können. Und ich werde ihnen dasselbe wieder und immer wieder zu spüren geben...", rewards = "Gelenkbänder des WahrsagersRitueller SchulterschutzAhnengurtSchädelkappe der BlutvergießersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12675] = {title = "Eine letzte Sache", objective = "Liefert die Fragmente unterweltlicher Macht bei Har'koa ab und bittet sie um einen Teil ihres Geistes. Sie befindet sich noch immer am Altar von Har'koa.", description = "Da gäbe es noch eine letzte Sache zu erledigen und meine Rache am Propheten wäre perfekt. Die Fragmente der Macht, die Ihr gesammelt habt, müssen mit einem Teil des Geistes eines lebendigen Gottes erfüllt werden. Ihr werdet also Har'koa anflehen müssen, ob sie nicht etwas von ihrem Geist abgeben möchte.\n\nSobald dies dann getan ist und Ihr zurückkehrt, wird es nicht in der Unterwelt sein, nein, Ihr werdet zur materiellen Welt meines Altars zurückkehren. Meine Kinder und Wächter werden Euch nicht länger angreifen - Ihr könnt also zu meinem Propheten gelangen, ohne Euch großartig Sorgen wegen ihnen machen zu müssen.", progress = "Ihr seid zurückgekehrt, <Name>.", completion = "Ein Teil meines Geistes?\n\n&lt;Die Schneeleopardengöttin hält einen Moment inne, um darüber nachzudenken.&gt;\n\nDas ist ein ziemlich teures Geschenk, wenn man sich überlegt, dass es zu Rachezwecken eingesetzt wird und ich durch die Machenschaften meiner Unterdrücker schon ziemlich geschwächt wurde.\n\nIch weiß vielleicht trotzdem einen Weg, wie wir die Sache lösen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12676] = {title = "Sabotage", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr eine weitere Aufgabe für Drakuru erledigt.\n\nZusätzlich dazu müsst Ihr an 5 Geißelwagen im Reliquiar des Schmerzes Sprengladungen anbringen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", description = "Wir werden versuchen herauszufinden, welchen Zweck diese Kristalle erfüllen, und Ihr geht zurück nach Voltarus und tut, was Drakuru von Euch verlangt.\n\nMit jeder Aufgabe, die Ihr für ihn erledigt, wird er Euch mehr Vertrauen schenken und uns damit Einblick in sein Denken gewähren.\n\nIch habe auch eine andere Aufgabe für Euch, während Ihr schon mal dort seid: Drakurus Geißelwagen stellen eine beträchtliche Gefahr dar - sie müssen zerstört werden.\n\nMacht Euch auf den Weg zu den Wagen und bringt diese Sprengladungen an. Geht in Deckung, sobald Ihr sie scharf gemacht habt! Die Explosion wird Euch verraten, wenn Ihr zu nah dran steht.", progress = nil, completion = "Ausgezeichnet!\n\nEuer verdeckter Einsatz hat sich wirklich ausgezahlt, &lt;Name&gt;.\n\nNun lasst uns einmal einen Blick auf dieses Szepter werfen...", rewards = "Häute der TäuschungSchulterschutz der TäuschungGürtel des VerrätersAuf Euch wartet eine dieser Belohnungen:\n\nAbzeichen des Spitzels\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12677] = {title = "Gefährliche Materialien", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr nach Voltarus geht und all das erledigt, was Drakuru Euch aufgibt. Während Ihr dort seid, sollt Ihr 5 geerntete Seuchenkristalle stehlen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", description = "Seuchenkristalle?! Was könnte dieser Mistkerl Drakuru nur vorhaben? Offensichtlich arbeitet er an etwas Bedeutendem.\n\nTanzt weiterhin nach seiner Pfeife und vielleicht, sobald er sich etwas mehr an Euch gewöhnt hat, wird er Euch seine Pläne verraten. Versucht in Voltarus ein paar Proben der geernteten Kristalle in die Finger zu bekommen, wenn gerade niemand hinsieht.\n\nDoch aufgepasst! Der Umgang mit diesen Kristallen könnte Euch enttarnen.", progress = "Willkommen zurück, <Name>.\n\nKonntet Ihr irgendwelche Proben von Drakurus Kristallen mitgehen lassen?", completion = "Faszinierend!\n\nWir werden uns diese Kristalle gleich einmal näher ansehen, um deren Beschaffenheit herauszufinden.\n\nNun sagt mir, &lt;Name&gt;, gibt es irgendwelche Neuigkeiten über diesen Drakuru?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12678] = {title = "Leid wird vom Chaos getrieben", objective = "Prinz Valanar in der Todesbresche befiehlt Euch, 10 Scharlachrote Kreuzfahrer oder Scharlachrote Arbeiter, und 10 Bürger von Havenau zu töten.", description = "Sie haben Stellung außerhalb der Todesbresche bezogen und versuchen vergeblich, uns zurückzudrängen. Sie hoffen, dass sie dadurch ihre Pferde, Minen, ihr Holz und ihre Bürger retten können.\n\nDies wird Eure erste Lektion in Sachen Geißelkriegsführung sein: SCHRECKEN!\n\nGeht an die südliche Front und tötet die Scharlachroten Kreuzfahrer. Lasst ihre Leichen in Ruhe, damit wir sie für unseren Todesfeldzug einsetzen können.\n\nDoch was am aller wichtigsten ist: tötet die flüchtenden Dorfbewohner. Tote Soldaten nehmen sie in Kauf, doch einfache Bürger? Das erfüllt die Herzen der Menschen mit Furcht.", progress = nil, completion = "Könnt Ihr es spüren, &lt;Name&gt;? Dieses Gefühl ist pure Macht, wie sie durch Euren Körper fließt. So etwas kennen Sterbliche nicht.\n\nWir haben an den Fronten den Sieg errungen. Die Spuke werden die Reste beseitigen und alles für Razuvious' Ankunft vorbereiten. Wir werden unsere Aufmerksamkeit nun auf taktischere Ziele richten.", rewards = "Ihr bekommt:\n\nValanars Siegelring"}
MultiLanguageQuestData['de'][12679] = {title = "Heute Abend speisen wir in Havenau", objective = "Orithos der Himmelsverdunkler in der Todesbresche möchte, dass ihr 15 Saronitpfeile beschafft.", description = "Die Himmelsverdunkler sind hirnlose Konstrukte, die nur ein Ziel kennen: TÖTEN! Sie haben es ganz besonders darauf abgesehen, jeden zu töten, der aus Havenau flieht, um sich in Neu-Avalon in Sicherheit zu bringen. Gewiss können wir diese Feiglinge nicht entwischen lassen, nur damit sie später die Waffen gegen uns erheben werden!\n\nEs gibt jedoch ein kleines Problem. Sie verwenden Saronitpfeile, um ihre Reichweite zu maximieren und den größtmöglichen Schaden anzurichten. Saronit ist allerdings ein Metall, das nur in Nordend vorkommt, also sind die Vorräte begrenzt! Beschafft mir diese Pfeile und ich werde Euch reich belohnen.", progress = "Anhand der Flugbahn ihrer Pfeile würde ich sagen, dass sich die meisten südlich von uns auf den Höfen von Havenau und in deren näheren Umgebung finden lassen.", completion = "Gut gemacht, &lt;Klasse&gt;! Eure Taten treiben die Kriegsmaschinerie der Geißel voran!\n\nAch ja, Eure Belohnung - wie versprochen.", rewards = "Unheilige Bedeckung des HimmelsverdunklersBlutige Bedeckung des HimmelsverdunklersBedeckung des NordwindsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12680] = {title = "Grand Theft Palomino", objective = "Salanar der Reiter in der Todesbresche möchte, dass Ihr ein Pferd aus den Ställen von Havenau stehlt und es zu ihm bringt.", description = "Welch Zufall, dass der Scharlachrote Kreuzzug keinen Steinwurf von hier entfernt einen Stall voller Pferde hat. Sie bewachen ihn zwar hartnäckig, doch ein aufstrebender junger Todesritter könnte durch ihre Verteidigungen brechen und nehmen, was rechtmäßig ihm gehört!\n\nSobald Ihr dann ein Pferd aus den Ställen von Havenau besorgt habt, sollt Ihr es zu mir bringen und ich werde sehen, ob es sich in ein ordentliches Todesstreitross umwandeln lassen wird oder nicht.\n\nMerkt Euch, <Name>: Gestohlen ist es erst dann, wenn man sich erwischen lässt. Und nehmt Euch vor dem verrückten Stallmeister Kitrik in Acht!", progress = "Ihr wollt doch nicht für immer zu Fuß gehen, oder?", completion = "Nun zum eigentlichen Test: Habt Ihr das Zeug dazu, ein ungezähmtes Todesstreitross zu beherrschen und den Willen dessen zu brechen, nach dem es Euch am meisten verlangt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12681] = {title = "Reagenzagent", objective = "Bringt Colvin Norrington an Dorians Außenposten 5 verdrehte Rocklauen.", description = "Der Erzmagier Pentarus in Dalaran wird erwarten, dass wir mit allerlei Arten von Reagenzien und Glücksbringern zurückkehren. Es sieht so aus, als hätten die Einheimischen Tierteile recht gern. Verdrehte Klauen von Blutklauenrocs scheinen ihnen die Liebsten zu sein.\n\nEs ist nicht an mir, zu sagen, ob die Gerüchte stimmen oder nicht, aber ich habe so das Gefühl, dass da durchaus etwas dran sein könnte.\n\nDie Rocs leben in den Knochenfeldern im Nordosten, wo sie sich von den Überresten alter Mammuts ernähren. Wollt Ihr mir helfen, für die Forschungsarbeit des Erzmagiers Klauen zu sammeln?", progress = "Habt Ihr es geschafft, verdrehte Klauen zu finden?", completion = "&lt;Colvin schaut bewundernd auf die Klauen, die Ihr mitgebracht habt.&gt;\n\nDiese werden mehr als ausreichen. Die Gorlocs haben ein Sprichwort, welches besagt: je verdrehter die Klaue, umso mehr Macht besitzt sie. Ich bin mir sicher, der Erzmagier wird bei dieser Expedition etwas für sein Geld bekommen.", rewards = "Stiefel des FeldforschersHydrazahnbundhosenArmschienen des RocjägersNorringtons brünierte BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12682] = {title = "Unerforschtes Gebiet (DEPRECATED)", objective = "Nicht alle von uns in dieser Expedition sind hier, um das größte und seltenste Wild zu jagen. Manche von uns haben tatsächlich ernsthaft zu arbeiten.\n\nDas schiere Bestehen eines solchen Ortes ist für den Geist zu viel - ein tropisches Paradies mitten in Nordend. Ich wäre kein Gelehrter angesehenen Rufs, wenn ich nicht zumindest versuchen würde, diesen Ort zu verstehen.\n\nNehmt dies.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Nicht alle von uns in dieser Expedition sind hier, um das größte und seltenste Wild zu jagen. Manche von uns haben tatsächlich ernsthaft zu arbeiten.\n\nDas schiere Bestehen eines solchen Ortes ist für den Geist zu viel - ein tropisches Paradies mitten in Nordend. Ich wäre kein Gelehrter angesehenen Rufs, wenn ich nicht zumindest versuchen würde, diesen Ort zu verstehen.\n\nNehmt dies.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12683] = {title = "Brenn darauf zu helfen", objective = "Colvin Norrington bei Dorians Außenposten möchte, dass Ihr 5 Proben Hydrasputum sammelt und 5 Bittertidenhydras tötet.", description = "Es gibt kein Material im ganzen Becken, das ätzender und beißender ist als Bittertiden-Hydrasputum. Ich besitze besondere Behälter, um es für Erzmagier Pentarus' Studien zu sammeln. Nun brauche ich nur noch jemanden, der mutig genug ist, es, ähm... einzusammeln.\n\nIhr wirkt wie <ein abgehärteter, abenteuerlustiger/eine harte> abenteuerlustige:c; <Klasse>. Was haltet Ihr davon, Euch ein bisschen Geld zu verdienen und gleichzeitig Dalarans Sache zu helfen?\n\nAlles, was Ihr zu tun habt, ist, diesen Behälter zum Bittertidensee im Südwesten mitzunehmen. Greift eine Hydra an und benutzt den Behälter, um das Sputum einzufangen, das sie auf Euch niederregnen lässt.", progress = "Habt Ihr diese Proben besorgt?", completion = "Wunderbar! Hier ist Eure Bezahlung, wie abgemacht. Und, äh, ein kleiner Rat: Ihr solltet in den nächsten Tagen lange, heiße Bäder nehmen, wenn dieses \"brennende Gefühl\" weiter anhält.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12684] = {title = "Das Blut eines toten Gottes", objective = "Har'koa hat Euch gebeten, 7 Blutproben von Mam'toth zu sammeln. Bringt sie zu ihr am Altar von Har'koa.", description = "Mam'toth, der Gott der Mammuts, hat sich selbst vernichtet und dabei lieber den Großteil seines Tempels mit sich gerissen, als es seinen Trollen zu erlauben, seine Macht zu erlangen.\n\nWenn ich einen Teil meines Geistes opfern soll, so brauche ich etwas, um mich zu stärken.\n\nMam'toth hat einen enormen Krater im Nordosten hinterlassen, gerade nördlich des Altars von Quetz'lun. In diesem Krater lebt sein Blut noch immer.\n\nBringt es mir.", progress = "Ich wünschte, es gäbe etwas, womit wir Mam'toth von den Toten zurückholen könnten, aber es gibt nichts.\n\nWir können ihm und seinem Opfer Ehre erweisen, indem wir den Kampf gegen die Drakkari fortführen.", completion = "Nun gut. Lasst uns sehen, ob das hier funktioniert...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12685] = {title = "Man erntet, was man sät", objective = "Erschlagt den ausgelaugten Propheten von Quetz'lun und informiert anschließend Hexendoktor Khufu in Zim'Torga.", description = "Darauf ist es hinausgelaufen... Rache.\n\n<Har'koa seufzt.>\n\nNehmt diesen Beutel mit Ritualgegenständen und vollzieht in der Nähe von Quetz'luns Leiche auf ihrem Altar ein Ritual. Wenn alles reibungslos abläuft, dann sollte Ihr Geist in die materielle Welt gezogen werden, von wo aus sie ihre Macht vom Propheten wiedererlangen kann.\n\nDer Rest wird an Euch liegen, <Name>. Ihr müsst den Propheten in seinem ausgelaugten Zustand erschlagen.", progress = nil, completion = "&lt;Der Hexendoktor schüttelt ungläubig den Kopf.&gt;\n\nEs hört sich an, als wärt Ihr Quetz'luns Unterwelt gerade noch lebend entkommen.\n\nIch bin froh, dass es Euch gibt. Ich weiß nicht, ob ich den Mut gehabt hätte, um mit dieser Situation fertig zu werden!", rewards = "Klinge des BlutvergießersRitueller SchildAhnenstulpenWeiche Gamaschen des BlutbindersAuf Euch wartet eine dieser Belohnungen:\n\nHalsamulett des mächtigen Mojo\n\nDer folgende Zauber wird auf euch gewirkt:\n\nYou Reap What You Sow: Quest Complete Force Cast\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12686] = {title = "Null Toleranz", objective = "Drakuru in Voltarus möchte, dass Ihr zum Reliquiar des Schmerzes geht und das Ermächtigungsszepter auf einen Diener von Drakuru anwendet, um anschließend mit seiner Hilfe Darmuk zu töten.", description = "Ignoranz! Unerträglich ist das, Mann! Meine ganze Ladung Seuche ist zu nichts zu gebrauchen!\n\nDieser Bastard Darmuk! Er war dafür verantwortlich, ein Auge auf die Seuche zu werfen, doch enttäuscht hat er mich, Mann, enttäuscht!\n\nDas wird dir eine gute Lektion sein, <Name>. Versagen ist wie ein gefährlicher Virus: Du musst schnell sein, ihn einfangen und töten, bevor er dich tötet!\n\nNimm dieses Szepter, es wird meine verseuchten Trolle stärker machen, damit du sie dann auf Darmuk hetzen und ihn töten kannst. Er liegt dort unten im Süden auf der Lauer.\n\nLass dies ein Beispiel für alle sein, Mann: Enttäusch Drakuru nich'!", progress = "Hat Darmuk für sein Versagen schon bezahlen müssen, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Du lernst schneller, als ich gedacht habe.\n\nGeh jetzt und ruh dich etwas aus. Bald werde ich dich einer noch größeren Prüfung unterziehen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Complete Credit Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12687] = {title = "Ins Reich des Schattens", objective = "Salanar der Reiter auf der Todesanhöhe hat Euch dazu herausgefordert, einen dunklen Reiter von Acherus zu erschlagen und sein Todesstreitross von Acherus in Eure Gewalt zu bringen.\n\nBringt das Todesstreitross von Acherus auf die Todesanhöhe und lasst den Ruf des Reiters ertönen, um Salanar herbeizurufen.", description = "Das Pferd, das Ihr gestohlen habt, wurde ins Reich der Schatten verschleppt. Dort wird mein dunkler Reiter das Biest niederstrecken und es wieder als Todesstreitross auferstehen lassen. Denkt Ihr, dass Ihr den Mut besitzt, dem Ross hinterher ins Reich des Schattens zu folgen?\n\nSolltet Ihr einwilligen, werde ich Euch dorthin befördern. Geht nach Süden, sobald Ihr dort angekommen seid, und sucht auf den Feldern nach einem der dunklen Reiter. Um den Sieg davonzutragen, müsst Ihr ihn niederstrecken, sein Todesstreitross übernehmen und es wieder zur Todesanhöhe bringen. Lasst den Ruf des Reiters ertönen, falls Ihr erfolgreich sein solltet.", progress = nil, completion = "Ihr hattet dort Erfolg, wo andere Initianden fehlschlugen, &lt;Name&gt;. Dafür werdet Ihr großzügig belohnt werden.", rewards = "Ihr erlernt:\n\nTodesstreitross von Acherus\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTodesstreitross beschwören\n\nIhr bekommt außerdem:\n\nSiegel des dunklen Reiters"}
MultiLanguageQuestData['de'][12688] = {title = "Ein Desaster konstruieren", objective = "Helft Ingenieurin Helice, aus Schwindelgrins' Grabungsstätte zu entkommen, und sprecht dann mit Hemet Nesingwary in Nesingwarys Basislager.", description = "Diese idiotischen Goblins und ihre Anhänger haben beschlossen, dass diese Säule und ihre Kristalle nun ihnen gehören. Ich kam hierher, um die Kristalle zu untersuchen und Proben zu sammeln, aber sie haben mich überwältigt und wollten mich nicht zum Lager zurückkehren lassen.\n\nWenn Ihr mir helft, hier auszubrechen, können wir diesen Schlägern eine Lektion erteilen, die sie nie vergessen werden!", progress = nil, completion = "Danke, dass Ihr Helice befreit und ihr zu einer sicheren Rückkehr verholfen habt. Wir waren alle bereits voller Sorge, als sie nicht von ihrer Suche nach Kristallen zurückkehrte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12689] = {title = "Hand der Orakel", objective = "Hallo! Freut mich sehr, dich wiederzusehen!\n\nIch wusste, wir Freunde. Ich wusste es! Du guter Freund. Nicht nur von uns, sondern von allen Orakeln. Danke, dass du uns gerettet hast! Danke, danke!\n\nIch gesehen, wie du Wauwau gut verprügelt hast! Untotes Ding gesagt, dass ihr einmal gute Freunde - stimmt das? Ich davon nichts wissen. Doch du Wauwau fertig gemacht haben, oder? Du jetzt nur noch Freund von Orakel?\n\nHalt! Nicht zustimmen ohne Nachdenken. Du sicher nicht mehr Freund sein willst von Wauwauleuten?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Set Oracle Honored\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12690] = {title = "Brennstoff", objective = "Drakuru in Voltarus möchte, dass Ihr das Szepter des Befehls auf die aufgeblähten Monstrositäten anwendet und dann ihre Fähigkeiten dazu einsetzt, um 60 Schädelberster der Drakkari zu töten und 3 Häuptlinge der Drakkari hervorzulocken.\n\nDie Häuptlinge tauchen erst dann auf, wenn genug Schädelberster getötet wurden.", description = "Es wird Zeit, dass wir auf Gundrak marschieren, Mann. Es wird Zeit, dass ich dich auf diese Trolle loslasse!\n\nSie sind durch unsere Mauern gestoßen und haben gleich nördlich von hier eine ganze Armee in Stellung gebracht.\n\nHahaha!\n\nSie werden nichts weiter als Brennstoff sein, Mann! Wir werden die Häuptlinge gefangen nehmen und den Rest töten! - alles Teil meines eigentlichen Plans...\n\nHier, nimm dieses Szepter und befiehl meine Monstrositäten. Schick sie zur Drakkariarmee und lass sie alle töten! Sobald die Häuptlinge auftauchen, wird mein Begleiter Schieferschwinge herbeieilen, sie ergreifen und hierher zu mir bringen.", progress = "Hast du die Trolle platt gemacht, <Name>?", completion = "Wir haben es geschafft, Mann!\n\nIch habe die Häuptlinge eingesperrt und du hast mithilfe meiner Monstrositäten den Sieg über ihre Armeen davongetragen.\n\nZeit zu feiern, Mann!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12691] = {title = "Eine verwitterte Kiste", objective = "Erbeutet einen gewaltigen, steinernen Schlüssel von einem der Sholazarwächter in der Nähe und bringt ihn zur verwitterten Kiste bei der Warte der Schöpfer.", description = "Die steinerne Kiste scheint verschlossen zu sein. Offensichtlich passt ein Schlüssel in das große Schlüsselloch aus Stein.\n\nVielleicht besitzt einer der Wächter in der Nähe diesen Schlüssel.", progress = "Die Steinkiste rührt sich nicht.", completion = "Der gewaltige, steinerne Schlüssel dreht sich mit einem tiefen Knarzen und die Kiste öffnet sich, um den verborgenen Schatz im Inneren zu enthüllen.", rewards = "Alte WächterbeinwickelBindung des uralten BewahrersSteinhantiererhandschuheSteingebundener BrustschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12692] = {title = "Rückkehr des Lichjägers", objective = "Kehrt zum Hügel der Wildherzen zurück und sprecht mit dem Ältesten Harkek.", description = "Gut, ich kehre zum Hügel der Wildherzen zurück, damit auch alle Wildherzen wissen, was du für Wolvar und Zepik getan. Du großer Jäger und sie so dumm, das nicht zu glauben.\n\nGeh zu Hügel zurück und sprich mit Ältesten Harkek... Ich sorge dafür, dass er erster Wildherz seien, der weiß, dass du kein Verräter.\n\nDanke, Lichjäger.", progress = nil, completion = "Es gut, dich wiederzusehen. Ich wusste, du kein Verräter, ich froh, dass Zepik bewiesen hat.\n\nIch höre, du nun Lichjäger - das ziemlich gut! Du machst Harkek stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12695] = {title = "Rückkehr der netten Trockenhaut", objective = "Kehrt zum Baldachin der Regenrufer zurück und sprecht mit dem Hochorakel Soo-say.", description = "Juhu! Soo-say wohl sorgen um uns! Vielleicht du gehst zurück zu Stadt und sagst ihm, dass alles in Ordnung? Ja, geh und erzähl Soo-say.\n\nIch werde glänzendes Kugelding von totem Lichkerl schnappen - ich dich dort treffen! Geh, geh! Ich dich dort treffen!", progress = nil, completion = "Gut, dich wiederzusehen! Wir besorgt, als du nicht sofort zurückkamst.\n\nJaloot dich zurückgetrieben - viel Energie in Jaloot, er sehr schnell. Er mir erzählte, wie du ihn vor Lichding gerettet. Moodle mir erzählt, wie du auch Mooswandler gerettet. Du wirklich nett.\n\nIch hoffe, du bei uns eine Weile bleibst. Immer etwas zu tun hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12696] = {title = "Luftüberwachung", objective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordosten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.", progress = nil, completion = "Die Professorin hat Euch zu mir geschickt? In Ordnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12697] = {title = "Gothik der Ernter", objective = "Sprecht mit Gothik dem Ernter in der Todesbresche.", description = "CHAOS, <Name>! Der Kreuzzug ist wild geworden. Sie haben alle Streitkräfte außerhalb von Neu-Avalon dazu abbestellt, eine Blockade am Lichtgipfel östlich von hier zu errichten. Sie versuchen wie verzweifelt die Mine von Havenau leerzuschürfen und das Erz auf die Fregatten zu verladen, die an der Küste vor Anker liegen.\n\nNa dann lasst uns mal ein wenig Unruhe stiften. Gothik der Ernter, Großnekromant des Lichkönigs, hat uns mit seiner Anwesenheit gesegnet. Er hält ein Geschenk parat, das er gerne dem Scharlachroten Kreuzzug machen würde... Sucht ihn auf.", progress = nil, completion = "Ihr habt hart gekämpft, um in das Reich des Ernters einzudringen... Wartet.\n\n&lt;Gothik betrachtet seine Notizen.&gt;\n\nIch möchte mich entschuldigen, &lt;Volk&gt;. Alte Gewohnheiten wird man nicht so schnell los.\n\nValanar hat Euch also geschickt? Ich kann mich dann darauf verlassen, dass Ihr eine gewisse Kompetenz besitzt.\n\nIch habe ein Geschenk für diese Hunde vom Scharlachroten Kreuzzug. Eines, das ihre Arbeit in den Minen sicherlich vorantreiben wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12698] = {title = "Das Geschenk, das nicht aufhört zu schenken", objective = "Gothik der Ernter in der Todesbresche hat Euch die Gabe des Ernters gegeben, um sie gegen die Scharlachroten Minenarbeiter einzusetzen. Erschafft mithilfe des Geräts 5 Scharlachrote Ghule und kehrt anschließend zu Gothik zurück.", description = "Ich bin aus dem gefrorenen Innersten von Naxxramas gekommen, um mich an Seelen gütlich zu tun und unseren Todfeinden eine ordentliche Tracht Prügel zu verpassen - nur leider gibt es keine Seelen mehr.\n\nDieses Gerät, das ich Euch gleich geben werde, ist ein tragbarer Seuchenverbreiter. Nehmt ihn, geht nach Osten zu den Minen von Havenau und entfesselt ihn auf die Scharlachroten Minenarbeiter, die dort drinnen arbeiten. Verwandelt die Minenarbeiter mit seiner Hilfe in Ghule und kehrt zu mir zurück, wenn Ihr eine kleine Armee um Euch gesammelt habt. Für sie habe ich einen besonderen Platz im Seelenstaubsauger freigehalten!", progress = "Eine kleine Anmerkung: Minenarbeiter werden nicht immer zu Ghulen. Manchmal verwandeln sie sich in wütende Geister, die fest dazu entschlossen sind, Euch zu töten.", completion = "Sie wissen, dass die Minenarbeiter nicht länger sicher sind. Sie werden sich nun umso schneller zurückziehen, mit dem Rücken zu uns!", rewards = "Ihr bekommt:\n\nAmulett des Seelenernters"}
MultiLanguageQuestData['de'][12699] = {title = "Der peinliche Vorfall", objective = "Sucht nach Vics Schlüssel im See am Flussnabel.", description = "Es gibt da ein kleines Problem zu lösen, bevor wir losziehen können. Wisst Ihr, ich kann den Schlüssel für meine Flugmaschine einfach nicht finden.\n\nIch hab' so ziemlich überall nach ihm gesucht... Vielleicht könnt Ihr mir helfen. Es gibt nur noch einen Ort, an dem ich noch nicht gesucht habe: im See.\n\nIch werde Euch sogar meinen eigenen Lufttank zur Verfügung stellen. Er ist zwar fast leer, hat jedoch noch genug Luft für ein paar Atemzüge.", progress = "Habt Ihr schon was gefunden, <Name>?", completion = "Ausgezeichnet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12700] = {title = "Gelegenheitsangriff", objective = "Sprecht mit Prinz Valanar in der Todesbresche.", description = "Nur die Streitkräfte des Scharlachroten Kreuzzugs bei Neu-Avalon und dem Lichtgipfel stellen noch eine Herausforderung dar! Die Zeit, die Scharlachrote Flotte beim Lichtgipfel anzugreifen, ist gekommen.\n\nDas Ablenkungsmanöver an der Mine hat sie ins Chaos gestürzt. Sie versuchen verzweifelt, die Gegend freizuräumen und zu ihren Schiffen zurückzukehren.\n\nDie Zeit ist reif! Prinz Valanar nutzt die Gelegenheit, um ihrer Flotte den letzten Stoß zu versetzen. Meldet Euch bei ihm - umgehend!", progress = nil, completion = "Ihr habt uns gut gedient, &lt;Klasse&gt;. Nur wenige Eurer Brüder haben den ersten Angriff auf die Eindringlinge des Scharlachroten Kreuzzugs überlebt. Ihr seid als einer der Stärksten hervorgegangen.\n\n\n\nÖstlich von uns jenseits der Mine von Havenau liegt die Küste - vom Scharlachroten Kreuzzug \"Lichtgipfel\" genannt. Zwischen uns und ihren Schiffen stehen Eintausend ihrer Soldaten. Unüberwindlich? Davon kann kaum die Rede sein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12701] = {title = "Massaker am Lichtgipfel", objective = "Prinz Valanar in der Todesbresche hat Euch befohlen, 100 Scharlachrote Verteidiger zu vernichten.", description = "In ihrer Eile werden die Diener des Scharlachroten Kreuzzugs einen schwerwiegenden Fehler begehen: zu vergessen, ihre Loren zu überprüfen.\n\nIhr sollt nach Osten zur Mine von Havenau reisen und die Lore finden, die meine Diener am Nebengebäude abgestellt haben. Klettert dann hinein und ein Scharlachroter Minenarbeiter wird sich unwissentlich darum kümmern, dass Ihr sicher hinter die feindlichen Linien gebracht werdet.\n\nSobald Ihr dann an Bord eines ihrer Schiffe seid, sollt Ihr ihre Kanonen gegen sie verwenden! SCHLACHTET SIE ALLE AB!\n\nRuft den Geißelgreif herbei, wenn Ihr bei der Kanone steht, und er wird Euch sicher wieder zurückbringen.", progress = "<Klasse> kennen keine Angst!", completion = "Ihr habt die gesamte Flotte des Scharlachroten Kreuzzugs in wenigen Minuten ausradiert! Ich werde vom Lichkönig dafür eine Auszeichnung erhalten! Alles, was vom Scharlachroten Kreuzzug noch übrig bleibt, sind die Bewohner von Neu-Avalon.\n\nIch werde die Brandstifter und Nekromanten umgehend auf Havenau ansetzen. Ihr werdet meinen Report zum Hochlord bringen!", rewards = "Ihr bekommt:\n\nSaronitplattenarmschienen"}
MultiLanguageQuestData['de'][12702] = {title = "Hühnerparty!", objective = "Fangt 12 entflohene Hühner für Ältesten Harkek auf dem Hügel der Wildherzen.", description = "Ich wette, Ihr nicht ratet, was schon wieder passiert.\n\nNe, nicht Goregek oder Hühner.\n\nJa, gut, ich lüge. Goregek schon wieder Hühner frei gelassen. Dummer Goregek mit hungrigem Bauch.\n\nLass mich wissen, wenn du brauchst Hilfe von einem der Jäger... sie hier irgendwo in der Nähe.", progress = "Hühner normalerweise nicht weit kommen... Wenn Wespen sie nicht essen, vielleicht wir sie einfach das nächste Mal draußen auf Feld lassen.", completion = "Du gut darin.\n\nVielleicht wir eines Tages Goregek einfach in Fluss fallen lassen, damit du das nie wieder machen musst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12703] = {title = "Kartaks Wut", objective = "Bringt eine reine Probe vom Blut der Orakel zum Altar von Kartak, um Kartak zu beschwören. Mit der Hilfe von Kartaks geteilten Kräften sollt Ihr für Schamanen Jakjek in Kartaks Stellung 50 in der Nähe befindliche, funkenbesprühte Gorlocs töten.", description = "Du der große Lichjäger, he? Gut, so starken Wildherzverbündeten in Kampf zu haben. Vielleicht du stark genug, sogar Kartak zu rufen.\n\nGroßer Kampf bei Kartaks Stellung im Südwesten. Geh und töte Funken-Großzungen, bis du kriegst gute Menge von Orakelblut. Bring Blut zu Altar in Kartaks Stellung, um Kartak für schmackhafte Gelage von Großzungen zu rufen.\n\nKartak nimmt deinen Körper, wenn du würdig... Mit Kartaks Kraft du tötest mehr Großzungen als in besten Träumen.\n\nGeh und töte viele, Jäger!", progress = nil, completion = "Ritual ging so leicht für dich!\n\nDu eines Tages kommst zurück für mehr Töten, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12704] = {title = "Besänftigung des großen Regensteins", objective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr einen Gefährten auswählt und 6 glänzende Kostbarkeiten sammelt.\n\nSprecht noch einmal mit dem Hochorakel Soo-say, um Euch die Hilfe eines Eurer früheren Gefährten zusichern zu lassen.", description = "Seit Mooswandler angegriffen wurden, ich in Sorge, wir vielleicht nicht gut zu Großem Regenstein... wir vielleicht zu gierig. Wir müssen mehr Schätze opfern!\n\nDu letztes Mal gut darin, Glitzers zu finden... vielleicht du suchst um Dorf herum nach mehr Glitzers? Du womöglich brauchst einen von guten Regenrufern zu Hilfe. Sag uns nur, wen.", progress = "Nie genug Glitzers... Großer Regenstein gut zu uns, wir müssen gut sein zu Großer Regenstein.", completion = "So viele gute Glitzers! Du gut darin.\n\nKomm zurück später für mehr, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12705] = {title = "Wille der Titanen", objective = "Erlangt einen getrübten Kristall von den Wolvar in der Nähe der Zuflucht der Funkenbesprühten und bringt ihn zum großen Blitzstein, um Soo-holu zu beschwören. Tötet mithilfe Soo-holus geteilter Macht 50 in der Nähe befindliche Wolvar der Wildherzen und kehrt anschließend zu Blitzrufer Soo-met in der Nähe des großen Donnersteins zurück.", description = "Wauwaumenschen angreifen Funkenbesprühten... wir müssen kämpfen oder sie nur angreifen auch andere Orakel.\n\nDu gut Freund von uns, also wir erlauben dir vielleicht besondere Ehre. Die Großen haben vor langer Zeit hinterlassen Beschützer für Schreine... Er immer noch hier, aber er nicht wissen, etwas falsch, bis Schreine verwüstet.\n\nWauwaumenschen da unten haben böse Kristalle zum Ärgermachen... Bring einen bösen Kristall zu Blitzschrein, damit Soo-holu weiß, dass er helfen.\n\nErschreck nicht, wenn Soo-holu deinen Körper nimmt... er sehr mächtig, also er dich beschützt.", progress = nil, completion = "Soo-holu stark, hm? Ich sehr froh, dass er zugestimmt, seinen Körper mit dir für Kampf zu teilen.\n\nEr mehr Vertrauen in Leute, die er schon vorher getroffen, also vielleicht komm zurück ein anderes Mal, um mehr zu helfen, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12706] = {title = "Sieg an der Todesbresche!", objective = "Liefert Prinz Valanars Bericht bei Hochlord Darion Mograine in Acherus: der Schwarzen Festung ab.", description = "<Prinz Valanar händigt Euch eine versiegelte Schriftrolle aus.>\n\nDies ist der komplette Bericht über Euren Sieg bei der Todesbresche. Bringt ihn zu Hochlord Mograine in Acherus. Ich habe dafür gesorgt, dass in dem Report von Euren Heldentaten die Rede ist. Mograine wird Euch zweifellos für diesen Sieg belohnen, <Name>.\n\nNun geht!", progress = "Ich war mir sicher, dass Ihr es nicht mehr in einem Stück zurückschaffen würdet, <Klasse>. Vielleicht steckt doch mehr in Euch, als ich zuerst vermutet habe.", completion = "&lt;Hochlord Mograine liest sich den Report durch.&gt;\n\nDie gesamte Flotte des Scharlachroten Kreuzzugs?\n\n&lt;Hochlord Mograine nickt.&gt;\n\nSolch Macht, &lt;Name&gt;... Solch eine Darbietung von Dominanz habe ich schon seit Jahren nicht mehr gesehen... seit mein Vater...\n\n\n\nEs ist nicht wichtig...\n\nJa: Eure Auszeichnung - bevor ich sie vergesse.", rewards = "Ihr bekommt:\n\nGravierte Saronitbeinplatten"}
MultiLanguageQuestData['de'][12707] = {title = "Wollige Gerechtigkeit", objective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr mithilfe des Medaillons von Mam'toth ein tobendes Mammut beruhigt, um dann auf ihm zu reiten. Anschließend sollt Ihr 12 Jünger von Mam'toth zu Tode trampeln.", description = "Ahunae hat über deine Reise zum Krater Mam'toth gehört, Mann. Die Kinder von Mam'toth sind erzürnt und schreien nach Gerechtigkeit!\n\nFolg der Allee in Richtung Nordosten die Stufen hoch zur nächsten Ebene von Zul'Drak. Zu deiner Rechten wirst du die Überreste des Altars von Mam'toth finden.\n\nHalt' das Medaillon von Mam'toth einem tobenden Mammut vor die Nase, wenn du dort bist. Es wird sich dann für eine Weile beruhigen, was dir die Chance gibt, auf seinen Rücken zu springen.\n\nReite anschließend mit ihm alle Jünger von Mam'toth nieder, die dir über den Weg laufen!", progress = nil, completion = "Erster Punkt für die Opfer, Mann!", rewards = "Kapuze des SterndeutersSchulterschützer des BlutbindersBeinplatten des BlutvergießersEisige ArmbrustWeiche Stiefel des BlutbindersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12708] = {title = "Verzauberte Tikikrieger", objective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 12 verzauberte Tikikrieger zerstört.", description = "Ich weiß, dass Ihr Euch auf dem Weg zur Festung von Zol'Maz gen Nordosten befindet, <Klasse>. Ich möchte, dass Ihr Euch um die Spezialwächter des Kriegsfürsten kümmert, wenn Ihr schon einmal dort seid.\n\nDie verzauberten Tikikrieger, wie sie genannt werden, stellen eine äußerst reelle Gefahr dar. Sollten die Drakkari sie in Massen produzieren, würden wir recht schnell überrannt werden.\n\nNa dann wollen wir ihnen mal zeigen, dass es sich nicht lohnt, die Dinger zu erschaffen.", progress = nil, completion = "Jetzt werden sie es sich wahrscheinlich zweimal überlegen, bevor sie mehr von diesen Dingern herstellen. Mich schaudert der Gedanke daran, wie es sein würde, wenn wir gegen eine ganze Armee dieser Dinger kämpfen müssten.\n\n&lt;Der Elementzähmer scheint, einen Moment lang in Gedanken versunken zu sein.&gt;\n\nIch nehme einmal an, dass es genauso wäre, als würde man gegen die endlosen Wellen der Geißel ankämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12709] = {title = "Verhexte Behälter", objective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 12 Behälter der Festung Zol'Maz sammelt.", description = "Entschuldigt, <Name>, mir scheint, Ihr seid unterwegs nach Nordosten zur Festung Zol'Maz? So eine Reise wäre für uns eine großartige Gelegenheit, unsere Sammlung der Schätze der Drakkari zu vollenden.\n\nIch habe erfahren, dass der Kriegsfürst der Drakkari extrem paranoid ist. Alle seine Behältnisse in der Feste hat er mit schrecklicher Magie verhexen lassen. Es wird gemunkelt, dass die Tikikrieger das Heilmittel haben - aber wer weiß das schon genau?\n\nWenn Ihr Euch die Zeit nehmen würdet, mir ein paar der Behälter zu holen, wäre ich Euch ziemlich dankbar.", progress = "Kann es sein, dass sich die Behältnisse in Eurem Rucksack befinden?", completion = "Seht Euch das alles nur mal an!\n\nSeht Euch dies an, &lt;Name&gt;. Dieses von Euch mitgebrachte Exemplar zeigt es deutlich: Die Drakkari erkannten, dass das Land durch die Anwesenheit der Geißel schwächer wurde.\n\nDer Kriegsfürst fühlte sich dazu gezwungen, die sich dadurch bietende Gelegenheit wahrzunehmen. Er drängte die Propheten dazu, Ihre Götter zu töten, um deren Macht zu beherrschen und die Streitkräfte des Lichkönigs zurückzudrängen.\n\nSie waren so oder so dem Untergang geweiht. Sie waren somit unbewusst für ihre eigene Zerstörung verantwortlich!", rewards = "Kapuze des BlutbindersGürtel der göttlichen HerkunftGeschmeidige Weste des BlutbindersAuf Euch wartet eine dieser Belohnungen:\n\nHalsamulett des Blutvergießers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12710] = {title = "Enthüllung", objective = "Drakuru in Voltarus möchte, dass Ihr den Teleporter benutzt, der in sein oberes Gemach führt.", description = "Gute Arbeit, <Name>.\n\nDu bist der Beweis, dass ich'n Auge für Talent besitze! Nun siehst du, weshalb mir der Lichkönig seinen Segen gegeb'n hat...\n\nDie Zeit is' gekommen, dir meinen eigentlichen Plan zu enthüllen, Mann.\n\nNun wirst du seh'n, wie wir über die Schwärme der Drakkaritrolle hinwegfegen werd'n, um unseren angestammt'n Platz im großen Palast von Gundrak einzunehmen.\n\nNimm dieses Szepter, Mann. Es is'n Zeichen meines Vertrauens in dir. Es wird dir Zugang zu meinen oberen Gemächern gewähren, damit du selbst Zeuge unserer Geheimwaffen sein kannst.", progress = "Hast du meine Schöpfungen mit eigenen Augen sehen können, <Name>?", completion = "So, da hast du es also, Mann.\n\nWir werden die ultimative Geißelarmee erschaffen und sie wird dem Lichkönig dienen. Er wird äußerst zufrieden sein!\n\nDu kannst das Szepter behalten, &lt;Name&gt;. Du wirst es brauchen, um meine Armee in die Schlacht zu führen...\n\nSchon bald!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12711] = {title = "Herrenlose Post", objective = "Auf dem Briefkasten liegen einige unleserliche Briefe und Schriftrollen. Nutzlos…\n\nVielleicht solltet Ihr mal hinein schauen?", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12712] = {title = "Der Schlüssel des Kriegslords Zol'Maz", objective = "Har'koa in Zim'Torga möchte, dass Ihr den Schlüssel des Kriegslords Zol'Maz beschafft.", description = "<Name>, wir benötigen einen Schlüssel, um die Ketten des Nashorngottes Akali zu lösen. Selbst jetzt, während wir hier noch reden, ist er auf dem Weg zur Schlachtbank.\n\nDer Drakkarikriegslord Zol'Maz trägt den Schlüssel bei sich. Als er von Euren Heldentaten erfuhr, hat er sich mitsamt seiner Familie in sein Bollwerk zurückgezogen; die Stufen hoch gen Nordosten.\n\nDer Kriegslord ist stark und Ihr werdet Hilfe benötigen. Solch Hilfe ließe sich herbeirufen, indem Ihr während des Kampfes vor seinen Toren das Tiki, das Schwert und die Zauberformeln seiner Familienmitglieder miteinander kombiniert.", progress = "Ich kann nicht genug betonen, wie wichtig es ist, dass wir den Schlüssel des Kriegslords um jeden Preis in die Hände zu bekommen.", completion = "Es wäre vielleicht besser gewesen, wenn ich Euch darum gebeten hätte, ihn direkt nach Gundrak zu bringen anstatt hierher.\n\nIch denke jedoch, dass es am besten ist, wenn Ihr zuerst hört, was ich noch zu sagen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12713] = {title = "Verrat", objective = "Stefan in der Schwarzen Wacht möchte, dass Ihr Drakuru besiegt.\n\nFalls Ihr Euren bezauberten Halsreif verlieren solltet, dann kehrt zu Stefan in der Schwarzen Wacht zurück und besorgt Euch einen neuen.", description = "Die Zeit ist gekommen, um dieser Scharade ein Ende zu setzen, <Name>.\n\nSo wertvoll Eure Informationen auch sein mögen, wir müssen Drakuru erledigen und sein Projekt stoppen, bevor seine verrückten Spießgesellen auf die Welt losgelassen werden.\n\nWir haben Euer Szepter für die Aufgabe modifiziert. Wenn die Zeit reif ist, werdet Ihr es gegen Drakurus Seuchenbluttrolle einsetzen und sie damit gegen ihren eigenen Meister aufhetzen. Es ist Eure einzige Chance, ihn zu vernichten.\n\nKämpft gut.", progress = "Habt Ihr Euch Drakuru schon gestellt, <Name>?", completion = "So, es ist vollbracht.\n\nEs gibt noch immer viel zu tun, doch Dank Euch wird unsere Arbeit hier viel einfacher sein.\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerräterhalsreifHalsreif des VerratsHalsreif des Verräters\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12714] = {title = "Der Wille des Lichkönigs", objective = "Kehrt zur Todesbresche zurück und meldet Euch bei Prinz Valanar.", description = "Es ist der Wille des Lichkönigs, der uns vorantreibt, <Name>. Niemand ist sich dessen mehr bewusst, als die Todesritter. Unsere schiere Existenz ist mit seinem Bewusstsein verbunden. Sicherlich habt Ihr ihn zu Euch sprechen hören, habt gespürt, wie er in Eure Gedanken eindringt...\n\nKönnt Ihr ihn jetzt hören? Vielleicht ist es zu früh für Euch.\n\n<Mograine schließt seine Augen und es scheint, als nickte er jemandem zu.>\n\nJawohl, mein Fürst. Es wird vollbracht werden.\n\n<Name>, Ihr sollt zur Todesbresche zurückkehren und Euch bei Prinz Valanar melden. Der Lichkönig befiehlt es!", progress = nil, completion = "Havenau ist unser! Tausend Leichen liegen auf dem Boden verstreut und warten nur auf ihre Wiedergeburt. Jetzt werden wir die Kraft der Geißel auf unseren Feind entfesseln!\n\nDie Ghule haben schon mit ihrem Angriff auf Neu-Avalon begonnen. Unsere Streitkräfte sind ihnen gefolgt und haben die Krypta der Erinnerung eingenommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12715] = {title = "Die Krypta der Erinnerung", objective = "Meldet Euch bei Prinz Keleseth in der Krypta der Erinnerung.", description = "Die Angriffe auf die Tore der letzten Bastion des Scharlachroten Kreuzzugs haben begonnen. Unsere Ghule sind dabei, ihre Streitkräfte an den Frontlinien zu zermürben, während wir hart daran arbeiten, die Verteidigung unserer Basis an vorderster Front zu verstärken - damit meine ich die Krypta der Erinnerung.\n\nGeht nach Süden zur Krypta - sie liegt gleich bei Neu-Avalon - und meldet Euch bei meinem verehrten Bruder Prinz Keleseth.\n\nEr wird Euch erwarten.\n\nMacht Euch bereit, <Name>, denn Ihr werdet Zeuge der nächsten Stufe unserer Kriegsführung sein: DOMINANZ!\n\nReitet aus, Todesritter!", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Ich bin Blutfürst Keleseth, Herrscher über die südöstlichen Gebiete Nordends. Der Lichkönig möchte mich und meine Fähigkeiten dazu einsetzen, diesen Sterblichen, dieser Beleidigung in den Augen der Geißel, ein Ende zu setzen. Wie mit allen Dingen, die der Lichkönig von mir verlangt, so werde ich auch jetzt mit Freude gehorchen. Meinen Durst mit einem Meer an endlos vielen Seelen zu stillen, versüßt natürlich die Sache, meint Ihr nicht auch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12716] = {title = "Des Seuchenfürstens Gesuch", objective = "Noth der Seuchenfürst möchte, dass Ihr ihm 1 leeren Kessel, 1 Eisenkette und 10 Kreuzfahrerschädel bringt.", description = "Seht Euch dieses Kürbisbeet an! Merkt Ihr, dass irgendetwas fehlt? Natürlich merkt Ihr das nicht - und wisst Ihr warum? Weil Ihr ein Idiot seid! Euer Gehirn war womöglich das Erste, was gestorben ist.\n\n<Noth seufzt.>\n\nIch wurde dazu beauftragt, einen Seuchenkessel zusammenzustellen, und Ihr werdet mir dabei helfen.\n\nDirekt hinter dem Tor von Neu-Avalon befindet sich das Gasthaus. Dort sollt Ihr mir einen leeren Kessel stehlen. Geht dann anschließend zur Schmiede, die sich auch gleich in der Nähe des Tores befindet, und besorgt mir eine Eisenkette. Bringt das Zeug gemeinsam mit zehn Kreuzfahrerschädeln zu mir. Soll ich Euch auch noch sagen, woher Ihr die Schädel bekommt?", progress = "Habt Ihr die Materialien gesammelt, um die ich Euch gebeten habe?", completion = "Perfekt! Nun gebt mir einen Moment lang Zeit, damit ich die Vorbereitungen treffen kann.", rewards = "Ihr bekommt:\n\nGurt des Seuchenbringers"}
MultiLanguageQuestData['de'][12717] = {title = "Noths Spezialgebräu", objective = "Werft den Haufen Kreuzfahrerschädel in den Seuchenkessel.", description = "Der Kessel kann nun seine faule Verderbnis ausspeien und über das Land verbreiten!\n\nNun, Todesritter: Eine kurze Lektion in Sachen Seuchenkessel. Das Gas des Kessels ist für alles Lebendige tödlich, erfüllt die Diener der Geißel jedoch mit Macht. Wie alle Schöpfungen der Geißel ernährt sie sich vom Tod und wird stärker, je länger sie sich nähren kann.\n\nNehmt diese Kreuzfahrerschädel und werft sie in den Kessel. Ihr werdet mit dem Resultat sehr zufrieden sein.", progress = "Der Kessel rührt sich nicht.", completion = "Der Seuchenkessel fängt an zu rasseln, als Ihr die Schädel hineinwerft.\n\nNach ein paar Sekunden tauchen ein paar Phiolen mit dunkler Flüssigkeit auf der Oberfläche auf.", rewards = "Ihr bekommt:\n\nNoths Spezialgebräu"}
MultiLanguageQuestData['de'][12718] = {title = "Mehr Totenschädel fürs Gebräu", objective = "Im Seuchenkessel blubbert und kocht das giftige Gebräu - überall dickes Gas verbreitend.\n\nHabt Ihr noch mehr Kreuzfahrerschädel, die Ihr hineinwerfen könnt?", description = nil, progress = "Im Seuchenkessel blubbert und kocht das giftige Gebräu - überall dickes Gas verbreitend.\n\nHabt Ihr noch mehr Kreuzfahrerschädel, die Ihr hineinwerfen könnt?", completion = "Der Seuchenkessel fängt an zu rasseln, als Ihr die Schädel hineinwerft.\n\nNach ein paar Sekunden spürt Ihr die herrliche Wirkung der dunklen und schaumigen Flüssigkeit, auch Noths Spezialgebräu genannt.", rewards = "Ihr bekommt:\n\nNoths Spezialgebräu"}
MultiLanguageQuestData['de'][12719] = {title = "Es gibt kein Entrinnen", objective = "Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, Bürgermeister Quimby zu töten und die Registratur von Neu-Avalon zu beschaffen.", description = "Es wird schon ausreichen, wenn wir sie komplett vernichten, <Name>. Und um das zu erreichen, wird es nicht genügen, dass nur ein paar Hundert hirnlose Ghule die Tore von Neu-Avalon angreifen. Wir müssen ins Allerheiligste des Dorfes vordringen und ihre Würdenträger beseitigen. Ihnen muss gezeigt werden, dass niemand der Geißel entkommen kann!\n\nMacht Euch auf den Weg in Richtung Südwesten zum Rathaus von Neu-Avalon und beseitigt den Bürgermeister. Sucht dort auch nach der Registratur von Neu-Avalon und bringt sie mir.", progress = "Es gibt kein Entrinnen!", completion = "Die Registratur wird uns Vieles über die Insekten des Scharlachroten Kreuzzugs verraten.\n\n&lt;Keleseth blättert durch die Seiten der Registratur.&gt;\n\nTodes- und Geburtsraten, doch was am allerwichtigsten ist: Logistik.\n\nSeht her, &lt;Name&gt;, sie haben schon vier Schiffe ausgesandt. Lasst mich sehen... Worauf steuern sie zu?\n\n\n\nWAS? Das ist nicht möglich. Sie segeln nach Nordend!\n\nNeben den Koordinaten steht geschrieben: \"Scharlachroter Morgen.\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12720] = {title = "Wie man Freunde gewinnt und Feinde beeinflusst", objective = "Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, die Wahrheit über den \"Scharlachroten Morgen\" herauszufinden.\n\nNehmt Keleseths Überzeuger aus der juwelenbesetzten Schatulle und bringt damit einen Scharlachroten Kreuzzügler zum Reden.", description = "Auf meinen Weltreisen habe ich mehrere interessante Entdeckungen gemacht. Habt Ihr zum Beispiel gewusst, dass man einem Mann jede auch noch so verheimlichte Wahrheit entlocken kann, indem man ihn nur richtig dazu ermutigt? Wie es das Glück so will, habe ich ein wenig \"Ermutigung\" zur Hand.\n\n<Keleseth nimmt etwas aus einer juwelenbesetzten Schatulle.>\n\nDies ist mein \"Überzeuger\", wie ich ihn nenne. Legt ihn an und zieht aufs Feld hinaus, Todesritter. Richtet das spitze Ende auf die Soldaten von Neu-Avalon. Findet die Wahrheit über den \"Scharlachroten Morgen\" heraus.", progress = "Wendet den Überzeuger auf einen Scharlachroten Kreuzfahrer an. Einer von ihnen wird letztendlich... brechen - äh, ich meine: aufgeben.", completion = "Ein Erwachen? Was für einen Unsinn redet Ihr da! Was für ein Idiot würde sein Volk schon mitten in die gefrorenen Weiten führen? Womöglich wird dieser Kurier jedoch die Antwort haben.", rewards = "Ihr bekommt:\n\nKeleseths Siegelring"}
MultiLanguageQuestData['de'][12721] = {title = "Randale", objective = "Har'koa in Zim'Torga möchte, dass Ihr Akali befreit und danach Hexendoktor Khufu in Zim'Torga benachrichtigt.", description = "<Name>, wir haben keine Zeit mehr. Ihr müsst den Schlüssel nehmen und Akali befreien.\n\nEr wird im Hof vor Gundrak, der Hauptstadt von Zul'Drak, gefangen gehalten. Akalis Ketten sind an vier Verankerungen befestigt. Um den Rhinozerosgott zu befreien, müsst Ihr jede einzelne von ihnen aufschließen.\n\nIn Gundrak wimmelt es nur so von Eistrollen. Ich glaube jedoch, dass Ihr mit der nötigen Vorsicht ohne große Gefahr hineinschleichen könnt.\n\nInformiert bitte den Hexendoktor, sobald Ihr die Sache erledigt habt.", progress = nil, completion = "Nein!\n\nSchon wieder wurde ein Gott vernichtet und seine Kräfte gestohlen. Und nun hat uns der Prophet von Akali direkt bedroht.\n\nWenn er kommt, dann wegen Har'koa. Wir können nicht zulassen, dass er auch noch ihre Kraft an sich reißt.\n\nEinmal mehr müssen wir die Götter um Rat bitten, &lt;Name&gt;. Sie werden uns sagen, was getan werden muss.", rewards = "Handschuhe des BlutbindersKopfbedeckung des BlutvergießersAhnenkriegsstiefelGeschmeidige Weste des BlutvergießersDer folgende Zauber wird auf euch gewirkt:\n\nRampage: Quest Complete Force Cast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12722] = {title = "Wie Lämmer zur Schlachtbank", objective = "Baron Totenschwur in der Krypta der Erinnerung hat Euch befohlen, 10 Soldaten des Scharlachroten Kreuzzugs und 15 Bürger von Neu-Avalon zu erschlagen.", description = "Die meisten Menschen wären geflohen, sobald eine Nekropole der Geißel über ihren Köpfen erschienen wäre. Doch nicht so der Scharlachrote Kreuzzug!\n\nIch muss zugeben, dass ich unseren Austausch mit dem Kreuzzug doch recht genieße. Im Laufe der Jahre haben Schlachten zwischen ihnen und der Geißel zu einigen der tragischsten Ereignisse in der Geschichte der Menschheit geführt. Und trotzdem stehen wir hier - SCHON WIEDER - und kämpfen gegen sie!\n\nWir sollen ihnen nicht die Freuden der ewigen Knechtschaft unter der Herrschaft des Lichkönigs verwehren! Geht nach Neu-Avalon und erfüllt ihren Todeswunsch. Lasst niemanden am Leben.", progress = nil, completion = "Ihr seid ziemlich effektiv mit der Klinge, &lt;Name&gt;. Vielleicht - mit des Lichkönigs Erlaubnis, versteht sich - wärt Ihr dazu geneigt, einer meiner Diener zu werden? Stratholme sucht nach einem neuen Bürgermeister.", rewards = "Ihr bekommt:\n\nSchienbeinschützer des Abschlachtens"}
MultiLanguageQuestData['de'][12723] = {title = "Hinter den Linien der Scharlachroten", objective = "Meldet Euch bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon.", description = "Ich habe Orbaz, Thassarian und Koltira ausgesandt, um hinter feindlichen Linien nach dem Kurier zu suchen. Sie haben die Scharlachrote Taverne ganz im Süden von Neu-Avalon zu ihrer Operationsbasis gemacht. Sie liegt hinter den zwei Obstgärten versteckt, neben der Kapelle der Scharlachroten Flamme. Ihr sollt bis zur Taverne vordringen und Euch bei Orbaz Blutbann melden. Er wird Euch über ihre derzeitige Lage aufklären.", progress = nil, completion = "Sieht so aus, als würden wir heutzutage jedem Einlass in den Dunklen Orden gewähren. Als mir das Geschenk zuteil wurde, war es anders - sehr anders!\n\nWas diesen Kurier angeht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12724] = {title = "Der Pfad des gerechten Kreuzfahrers", objective = "Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, die Patrouillenaufstellung von Neu-Avalon aus der Scharlachroten Festung zu stehlen.", description = "Wir haben nicht den geringsten Hinweis darüber, wann und wo dieser Kurier erscheinen soll. Diese Menschen wussten auch nichts.\n\n<Orbaz deutet auf die Leichen des Scharlachroten Kreuzzugs, die über den Boden verteilt liegen.>\n\nAus dem letzten konnte ich noch etwas Nützliches herausprügeln. Im Inneren der Scharlachroten Festung befindet sich ein Plan, auf dem all ihre Patrouillen eingezeichnet sind. Ich möchte, dass Ihr in die Festung einbrecht und ihn stehlt.\n\nDie Wacht ist das größte Gebäude in Neu-Avalon nordöstlich von hier.", progress = "Durchsucht alle Fugen und Ecken dieser Wacht! Der Plan ist dort!", completion = "&lt;Orbaz blättert durch die Seiten des Plans.&gt;\n\nDiese nutzlosen Scheusale sind geschäftig gewesen! Patrouillen im Norden, Süden, Westen und Osten, doch kein Wort über ihre Kurierwege. Wartet. Was ist das? Es sieht so aus, als gäbe es eine Patrouille, die von den westlichen Pestländern ausgeht. Und sie wird heute genau hier vorbeikommen! Ich brauche etwas Zeit zum planen.", rewards = "Ihr bekommt:\n\nBlutbanns Kommandostulpen"}
MultiLanguageQuestData['de'][12725] = {title = "Im Tode vereint", objective = "Sucht nach Koltira Todesweber in der Scharlachroten Festung.", description = "Durch die Linien des Scharlachroten Kreuzzugs zu brechen, war keine einfache Aufgabe. Wir mussten während des Angriffs hohe Verluste hinnehmen und verloren einen unserer besten Todesritter: Koltira Todesweber. Ich weiß nicht, ob er tot oder am Leben ist, doch ich soll verdammt sein, wenn wir nicht nach ihm suchen würden.\n\nAls ich ihn das letzte Mal sah, war er in Ketten gelegt und wurde zur Scharlachroten Festung nordöstlich von hier verschleppt. Durchsucht jeden Winkel dieser Festung, Todesritter. Findet Koltira!", progress = nil, completion = "Es war töricht, mir zu folgen. Ich habe versagt. Sie hätten mich sterben lassen sollen - nun werden womöglich zwei von uns getötet werden.\n\n&lt;Koltira schüttelt den Kopf.&gt;\n\nWir sind &lt;Klasse&gt; der Geißel - das ist dem Bündnis der dunklen Bruderschaft ein Dorn im Auge.\n\nThassarian, du verdammter Trottel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12726] = {title = "Lied von Wind und Wasser", objective = "Soo-nee möchte, dass Ihr die Trommeln des Sturms auf dem Sturmherrenschelf verwendet und Haifun dabei helft, 3 Sturmwiedergänger und 3 Aqueousgeister zu verschlingen.", description = "Du Sturm zugehört, ja? Das Sturmherrenschelf hallt mit uralten Liedern... das Lied von Wind und Wasser.\n\nDer große Sturm verschlingt die Söhne des Taifuns und des Unwetters. Hier, nimm diese Trommel und spiel sein Lied... Haifuns Lied.\n\nHilf ihm, Wind und Wasser aufzusaugen, damit Sturm weitermachen kann.", progress = nil, completion = "Ich danke dir, &lt;Name&gt;. Dank dir wird uns der große Sturm freundlich gesonnen sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12727] = {title = "Blutiger Ausbruch", objective = "Erschlagt Hochinquisitor Valroth und bringt Valroths Kopf zu Thassarian in der Scharlachroten Taverne in Neu-Avalon.", description = "Der Alarm wurde geläutet. Der Hochinquisitor und seine Akolyten werden bald hier sein. Ich bin zu schwer verwundet, um von irgendwelchem Nutzen sein zu können, werde jedoch so gut wie möglich helfen.\n\nErschlagt den Hochinquisitor und seine Spießgesellen. Reißt ihm den Kopf ab und bringt ihn Thassarian. Rache wird seine barbarische Seele besänftigen.\n\nUnd noch etwas, <Name>: Falls Ihr überleben und zurück zu Thassarian gelangen solltet, dann sagt ihm, dass sie in der Kapelle Gefangene hinrichten. Womöglich wird er Euch dann dorthin schicken, damit Ihr einmal mehr den Helden spielen könnt.", progress = "Was ist mit Koltira?", completion = "Ich werde den Kopf dieses Monsters an die Ghule verfüttern!\n\n&lt;Thassarian wirft den Kopf ins Hinterzimmer.&gt;\n\nHat es Koltira wieder herausgeschafft?\n\n&lt;Thassarian hält inne.&gt;\n\nIch bin mir sicher, dass er's geschafft hat. Diese Mauern können ihn nicht lange halten.\n\nZeit, Rache zu nehmen.", rewards = "Ihr bekommt:\n\nSaronitkampfplatte"}
MultiLanguageQuestData['de'][12728] = {title = "Die Klamm beobachten: Höhlen der Winterflossen", objective = "Bibliothekar Garren vom Bernsteinflöz möchte, dass Ihr zu den Höhlen der Winterflossen geht und dort das Arkanometer benutzt.", description = "Ich muss meine Notizen zusammentragen und eine Präsentation für meine Kollegen in Dalaran vorbereiten.\n\nWährend ich das mache, muss ich Euch darum bitten, den Höhlen der Winterflossen im Norden einen Besuch abzustatten. Dort müsst Ihr Euch in den Eingang der Höhle stellen und das Arkanometer benutzen.\n\nKehrt umgehend zu mir zurück, sobald Ihr die Daten gesammelt habt. Ohne sie würde mein Material unvollständig sein.", progress = nil, completion = "Ausgezeichnet, jetzt ist mein Bericht komplett.\n\nIch werde den Rat auf jeden Fall von Eurer Gefälligkeit wissen lassen, &lt;Name&gt;.", rewards = "HöhlenstulpenSchiftung der widerhallenden WahrheitKrankensteins HandgelenksschützerGurt des gerissenen RaumsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12729] = {title = "Die Götter haben gesprochen", objective = "Bringt das unbefleckte Herz des Wächters und die stürmische Essenz des Behüters zu Har'koa in Zim'Torga.", description = "Die Götter haben gesprochen und wir müssen uns ihrer Weisheit beugen.\n\nGeht in den Norden nach Zim'Rhuk und vernichtet dort Wächter, bis sie Euch das unbefleckte Herz abtreten. Reist in den Osten zum Altar von Quetz'lun und bringt Unfrieden unter die Altarbehüter, bis Ihr ihre stürmische Essenz bergen könnt.\n\nBringt beides zu Har'koa und sie wird sie zu etwas zusammenfügen, das den verblichenen Akalipropheten zwingen wird, zu erscheinen.", progress = "Habt Ihr, was benötigt wird, <Name>?", completion = "Euer Heldenmut scheint grenzenlos, &lt;Name&gt;.\n\nBitte gebt mir das Herz und die Essenz und ich werde sie in etwas verwandeln, das den Propheten zwingen wird, vor Euch zu erscheinen.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12730] = {title = "Beschwörung bei Zol'Heb", objective = "Har'koa in Zim'Torga möchte, dass Ihr den Propheten von Akali tötet.", description = "Ihr müsst dieses Beschwörungsjuwel nach Zol'heb gleich südlich von Gundrak bringen.\n\nDort befindet sich ein Kreis der Macht. Benutzt dieses Juwel und zwingt damit den Propheten von Akali zu erscheinen.\n\nMein Herz ist mit Euch, <Name>. Gemeinsam haben wir schon viel durchgestanden und Ihr habt alles getan, was in Eurer Macht steht, um nicht nur mein Leben zu retten, sondern auch das der anderen Götter, die von den Drakkari vernichtet wurden.\n\nDoch ich fürchte, dass wir uns in diesem Leben nicht mehr wiedersehen werden.", progress = "Das Einzige, was ich Euch anbieten kann, sind die Wärme meiner Worte und den damit verbundenen Herzenstrost.\n\nLasst Euch so viel Zeit wie nötig, um all Euren Mut zusammenzunehmen und bereit zu sein; doch ich flehe Euch an: Lasst Euch nicht zu lange Zeit oder der Prophet wird über uns kommen.", completion = "Ihr habt es geschafft! &lt;Name&gt;, Ihr seid der Held von Zul'Drak!\n\nWir stehen in Eurer Schuld und werden diese doch nie begleichen können. Die Zandalari haben mir jedoch eine Reihe von Objekten anvertraut und meinen, dass sie Euch womöglich interessieren könnten.\n\nBitte, ich möchte, dass Euch dies gehört - ein Zeichen unserer Dankbarkeit - doch beeilt Euch. Ich spüre, dass es noch eine weitere wichtige Angelegenheit gibt!", rewards = "Robe des bezwungenen ProphetenAufwendige Tunika der ZandalariBrustharnisch des tobenden WütersVerbund des entsetzten GottesIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12732] = {title = "Des Herzbluts Stärke", objective = "Bringt eine Phiole voll Sonnenstrahlherzblut zu Rejek auf dem Hügel der Wildherzen.", description = "Eines Tages Rejek mächtiger Krieger. Blut und Himmelsfeuer Rejek stark machen werden. Du bald siehst.\n\nRejek gibt dir Phiole, bringe sie zur obersten Spitze der Sonnenstrahlsäule, weit im Westen. Fülle Wasser in Phiole.\n\nDann du gehst nach Norden zu Grenze von Becken, zu Felsvorsprung nördlich von Knochenfelder. Du findest und tötest Blutklauenmatriarchin. Nimm Herzblut.\n\nDu mischt Herzblut und Wasser und bringst zu Rejek. Rejek trinkt, macht stark.", progress = "Du bringst Rejek Geschenk?", completion = "Rejek dankt dir. Rejek trinkt, wird stark, nie vergisst mächtiges Geschenk von &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12733] = {title = "Herausforderung des Todes", objective = "Olrun die Schlachtenruferin hat Euch befohlen, 5 Duelle mit anderen Todesrittern zu gewinnen.\n\nIhr könnt gegen Initianden der Todesritter oder gegen Spieler kämpfen.", description = "Sie wurde ins Leben gerufen, als der Lichkönig auf den gefrorenen Weiten den Sieg über Illidan Sturmgrimm errang: Die Herausforderung des Todes ist ein Übergangsritus, den alle Todesritter über sich ergehen lassen müssen.\n\nSucht andere Todesritter von Acherus auf und fordert sie zu einem Duell heraus. Sie sind dazu verpflichtet, die Herausforderung zu akzeptieren und so lange zu kämpfen, bis ein Sieger hervortritt!\n\nGeht nun, <Name>! Sieg der Geißel! Ehre dem Lichkönig!", progress = "Habt Ihr die Herausforderung des Todes abgeschlossen?", completion = "Dem Sieger gehört der Ruhm, &lt;Klasse&gt;! Gut gemacht! Die Gunst des Lichkönigs ist Euch an diesem Tage sicher.", rewards = "Ihr bekommt:\n\nInsigne der Geißel"}
MultiLanguageQuestData['de'][12734] = {title = "Rejek: Erstes Blut", objective = "Taucht Rejeks Klinge in das Blut der Leichen von einer saphirblauen Schwarmwespe, einem Hartknöchelstürmer und 3 Mitgliedern des Stamms der Nebelflüsterer - es können entweder Orakel der Nebelflüsterer oder Krieger der Nebelflüsterer sein. Kehrt zu Rejek auf dem Hügel der Wildherzen zurück, sobald die Aufgabe abgeschlossen ist.", description = "Rejek gerade jüngster Krieger in ganzem Stamm der Wildherzen geworden. Vater gab Rejek ein mächtiges Schwert, um Feinde der Wildherzen zu besiegen, aber alter Brauch sagt, Schwert muss erst Blut schmecken. Alter Krieger normalerweise das macht. Du Rejek diese Ehre machen?\n\nNimm Klinge, steche in Leichen aller Wildherzenfeinde: Wespen und Hartknöchel im Südwesten und Großzungen. Vielleicht Klinge in Blut von Nebelflüsterern tauchen, weit im Nordwesten bei Bittertidensee.", progress = "Du Rejeks Klinge in Blut gebadet?", completion = "Rejek sieht Blutspuren seiner Feinde auf der Klinge. Nun hat Rejek mächtige Waffe für mächtigen Krieger, der er wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12735] = {title = "Ein reinigendes Lied", objective = "Soo-nee beim Baldachin der Regenrufer will, dass Ihr am Bittertidensee, am Tausendwinterfluss und am Flussnabel das läuternde Glockenspiel erklingen lasst und die bösen Geister tötet, die das Wasser dort verschmutzen.", description = "Erde in Sholazar ist sauber. Die Säulen haben das Land Jahrhunderte lang beschützt.\n\nWasser, nicht so sauber, kommt von draußen... von Meeren, von Seen, von Flüssen. Wasser bringt manchmal böse Geister mit - muss gesäubert werden.\n\nNimm dieses Glockenspiel und spiele am Bittertidensee, am Tausendwinterfluss und am Flussnabel. Das macht böse Geister wütend... und dann musst du sie töten.", progress = nil, completion = "Wasser... gesäubert. Ja. Alles gut.\n\nDu verstehst uns, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12736] = {title = "Lied der Besinnung", objective = "Soo-nee im Baldachin der Regenrufer möchte, dass Ihr das Didgeridoo des Nachsinnens auf der Spitze der Schimmersäule, der Sonnenstrahlsäule, der Mooslichtsäule und der Himmelszeltsäule verwendet.", description = "Natürlich du nicht so schlau wie ein Gorloc! Du nur <Volk>.\n\nDu aber nicht hoffnungslos! Du zeigst, du kannst lernen. Vielleicht Kristalle machen dich schlau, wie Kristalle uns machen schlau!\n\nIch dich lehren Lied spielen, um Geist zu reinigen. Du spielst Lied bei Kristallen, dann Kristalle machen deinen Geist besser... nicht so gut wie den von Gorlocs, aber besser als jetzt. Lebensblutsäule kaputt, aber andere Säulen immer noch gut!", progress = nil, completion = "Du sehen? Ich kann dir sagen, schon schlauer geworden. Und wenn nicht schlauer... dann... glücklicher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12737] = {title = "Lied der Fruchtbarkeit", objective = "Soo-nee beim Baldachin der Regenrufer möchte, dass Ihr zum Sturmherrenschelf nordwestlich des Horts der Schöpfer geht und das Horn der Fruchtbarkeit neben 8 Hügeln durchtränkten Mutterbodens blast.", description = "Ein Sturm ist ein zerstörerisches Kraft. Sturm verbrennt Bäume. Sturm überflutet Häuser.\n\nDoch Sturm kann auch Leben spenden, wenn man kennt richtiges Lied. Bei Sturmherrenschelf über Hort der Schöpfer gibt es klein Dreckhügel. Die sehr fruchtbar - darin starke Samen. Warten nur auf richtiges Lied.\n\nDu nehmen dies Horn und spielen Lied für Samen.", progress = nil, completion = "Du lernen schnell, &lt;Name&gt;. Du Lied gut gelernt. Vielleicht ich zeigen anderes Lied nächstes Mal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12738] = {title = "Schrei nach Rache!", objective = "Meldet Euch bei Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme.", description = "Der Schrei nach Rache darf nicht zu überhören sein, <Name>. Kommandant Seuchenfaust hat sich mit einer Kompanie von Todesrittern auf den Weg gemacht, um die Kapelle der Scharlachroten Flamme dem Erdboden gleichzumachen. Falls dort irgendwelche Todesritter gefangen sein sollten, dann wird Seuchenfaust sie da rausbringen.\n\nIhr könnt sie noch immer einholen, wenn Ihr Euch beeilt. Die Kapelle befindet sich westlich von hier.", progress = nil, completion = "Sie bestehen auch nur aus Fleisch und Knochen - der Geißel also nicht gewachsen.\n\nWir haben zwar keinen unserer Brüder gefunden, sind jedoch über etwas Besonderes gestolpert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12739] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Malar Tapferhorn hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Tauren, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns - für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12740] = {title = "Fallschirme für den Argentumkreuzzug", objective = "Kommandant Falstaav in der Argentumwache möchte, dass Ihr 10 Argentumkreuzfahrer oder Argentumschildmänner draußen auf dem Hof mit Fallschirmen versorgt.", description = "Diese Himmelsschrecken töten meine Leute! In den Tod zu stürzen, ist eine schreckliche Art zu sterben.\n\n<Klasse>, Ihr müsst diese Fallschirme hinaus zu ihnen aufs Feld bringen! Zumindest haben sie dann eine Überlebenschance.", progress = nil, completion = "Ihr seid ein guter Mann, &lt;Name&gt;. Wir können uns glücklich schätzen, dass Ihr zufällig vorbeigekommen seid.\n\nBleibt doch ein Weilchen. Ich bin mir sicher, dass es hier vieles zu tun gibt, bei dem ein fähiger &lt;Klasse&gt; wie Ihr helfen könnte.", rewards = "Reißleine des KreuzfahrersBrustharnisch des RettersStiefel des RettersKlinge des wackeren DienstesAuf Euch wartet eine dieser Belohnungen:\n\nReißleine des Retters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12741] = {title = "Die Stärke des Sturms", objective = "Sammelt 3 Essenzen des Monsuns und 3 Essenzen des Sturms ein und bringt sie zum Sturmschrein. Kehrt mit der wahren Macht des Sturms zu Rejek auf dem Hügel der Wildherzen zurück.", description = "Dumme Großzungen denken, Singen zu Wolken ihnen Macht gibt. Rejek zeigt Großzungen, wie man Macht kriegt - durch Nehmen!\n\nWeit im Nordwesten liegt großes, flaches Gebiet, das Großzungen \"Sturmherrenschelf\" nennen. Rejek ist sicher, man kann dort nur hinkommen, wenn fliegen wie ein Vogel.\n\nAuf diesem Schelf hat Rejek von mächtigen Kräften von Wind und Wasser gehört. Töte sie für ihre Bosheit und bringe dann zum \"Sturmschrein\" von Großzungen an der Westseite des Schelfs. Rejek wird warten, bis du mit ultimativer Macht zurückkommen.", progress = "Du bringst Rejekwahre Macht des Sturms?", completion = "Nun Rejek zeigt feigen Großzungen, wie man Elemente wirklich benutzt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12742] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Ellen Stanbrück hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Menschen, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns - für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12743] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Yazmina Eichendorn hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen eine recht angriffslustige Nachtelfe, an deren Hinrichtung Ihr besonderen Gefallen finden solltet.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns - für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12744] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Donovan Dulfrost hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hierher, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Zwergen, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns - für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12745] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Goby Blastenheimer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Gnom, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns - für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12746] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Valok den Gerechten hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Vor allem gibt es dort drinnen einen recht angriffslustigen Draenei, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", progress = "Wie fühlt es sich an?", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns; für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12747] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Lady Eonys hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen eine recht angriffslustige Blutelfe, an deren Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns; für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12748] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Kug Eisenkiefer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Orc, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", progress = "Wie fühlt es sich an?", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns; für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12749] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Iggy Dunkelhauer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustiger Troll, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns - für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12750] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Antoine Brack hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, <Name>. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Diener der Verlassenen, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", progress = nil, completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, &lt;Name&gt;. Ihr seid ein Diener der Geißel, einer von uns; für immer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12751] = {title = "So etwas wie Heimkehr", objective = "Überbringt Thassarian in der Scharlachroten Taverne in Neu-Avalon die Nachricht Eures Sieges.", description = "Kehrt zu Thassarian in der Scharlachroten Taverne zurück und lasst ihn wissen, dass Koltiras Schrei nach Rache erhört wurde. Die Kapelle der Scharlachroten Flamme wird in weniger als ein paar Stunden nur noch ein Haufen Asche sein.\n\nIhr seid ein kaltblütiges Monster, <Name>. Ich verneige mich vor Euch, <Bruder/Schwester>.", progress = nil, completion = "Wieder ein Sieg für die Geißel! Für diese Hunde, diese Scharlachroten, gibt es kein Entrinnen mehr. Jetzt ist es nur noch eine Frage der Zeit...", rewards = "Ihr bekommt:\n\nSiegel der dunklen Bruderschaft"}
MultiLanguageQuestData['de'][12752] = {title = "Verzweifelte Forschung", objective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", description = "<Name>, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, <Name>. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", progress = nil, completion = "Grüße, Bruder. Ihr möget zwar im Namen der Argentumdämmerung geschickt worden sein, doch das ist nicht der Grund, weshalb Ihr hier seid... Ihr seid hier, um Eurem Volk den Respekt zu verschaffen, den wir uns so redlich verdient haben. Alle Verlassenen würden zustimmen, wenn ich sage: der Zweck heiligt die Mittel. Und unsere Forschungen für das Heilmittel der Zombieseuche sind genau dieses Sprichwort in die Tat umgesetzt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12753] = {title = "Eine verzweifelte Allianz", objective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", description = "<Guter/Gute> <Name>, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, <Name>.", progress = nil, completion = "Bruder &lt;Volk&gt;, ich bin stolz, in diesen Zeiten der Not an Eurer Seite stehen zu dürfen. Seid gesegnet und möge die Allianz zwischen Zwergen und Menschen eintausend Jahre lang währen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12754] = {title = "Überfall am Rundblick", objective = "Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, den Scharlachroten Kurier zu töten und seine Sachen und die Nachricht zu beschaffen.", description = "Während Ihr damit beschäftigt wart, Kirchen niederzubrennen und Ungeziefer zu beseitigen, habe ich mich an die Ausarbeitung eines Plans gemacht.\n\nDer Scharlachrote Kurier wird den Scharlachroten Rundblick innerhalb der nächsten Stunde passieren. Die Straßen dort sind recht ungeschützt und wimmeln nur so von Kreuzfahrern. Werft diese provisorische Tarnung über, wenn Ihr dort angekommen seid, und wartet, bis der Kurier vorbeikommt. Schlagt mit all Eurer Wildheit zu, sobald er in Eurer Reichweite ist! Macht ihn nieder und nehmt sein Hab und Gut mitsamt seinen Kleidern!\n\nDer Rundblick ist 200 Meter östlich von hier.", progress = "Wenn Ihr diesen Kurier verpasst, werde ich gezwungen sein, Euch zu töten. Mit \"gezwungen\" meine ich, dass ich großen Gefallen daran finden werde, Euer Leben auszulöschen.\n\nBEEILT EUCH!", completion = "&lt;Orbaz liest sich die Nachricht durch.&gt;\n\nDie Armeen von Herdweiler und Tirisfal werden direkt in ein Massaker laufen.\n\n&lt;Orbaz grinst.&gt;\n\nNun zum zweiten Teil des Plans. Ihr werdet diese Nachricht höchstpersönlich an Hochgeneral Abbendis übergeben - dafür sind die Kleider gedacht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12755] = {title = "Begegnung mit dem Schicksal", objective = "Orbaz Blutbann hat Euch befohlen, die Nachricht des Scharlachroten Kuriers bei Hochgeneral Abbendis im Königshafen abzuliefern.", description = "Diese Nachricht muss Abbendis erreichen. Wir wollen nicht ihren Verdacht auf uns ziehen. Sie müssen weiterhin davon ausgehen, dass alles für sie nach Plan verläuft.\n\nIhr werdet die Kleider des Scharlachroten Kuriers anlegen und mit der Hilfe von ein wenig dunkler Magie seine Gestalt annehmen.\n\nAbbendis befindet sich im Königshafen südlich des Scharlachroten Rundblicks. Erzählt ihr die Neuigkeiten und bekommt so viel Informationen wie möglich aus ihr heraus. Sie wird uns sagen können, was es über den \"Scharlachroten Morgen\" zu wissen gibt.", progress = "Wo seid Ihr gewesen? Ihr seid zwei Stunden zu spät. Wir waren gerade dabei, einen Kurier zum Hochkommandanten zu schicken.", completion = "&lt;Hochgeneral Abbendis liest sich die Nachricht durch.&gt;\n\nVerdammt! Die Armeen von Herdweiler und Tirisfal dürfen Neu-Avalon nicht erreichen! Die Geißel wird sie alle töten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12756] = {title = "Der Scharlachrote Ansturm tritt hervor", objective = "Liefert das Buch \"Der Weg der Erlösung\" bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon ab.", description = "Hört gut zu, Kurier. Die Lande des Scharlachroten Kreuzzugs sind verloren. Neu-Avalon und Havenau wurden von der Geißel überrannt. Die Fratze des Todes ist über uns gekommen und droht damit, uns jeden Augenblick in seine Gewalt zu bringen.\n\nKehrt mit dieser Nachricht zu Galvar zurück:\n\n\"Lasst Eure Armeen umdrehen und bereitet Eure Schiffe darauf vor, in Richtung der gefrorenen Weiten zu segeln. Wenn wir uns das nächste Mal sehen, wird es in Nordend sein.\"\n\nGebt dies Galvar.\n\n<Abbendis händigt Euch ein Tagebuch aus.>\n\nEs wird alles erklären.\n\nDen Scharlachroten Kreuzzug gibt es nicht mehr. Lang lebe der Scharlachrote Ansturm!", progress = "<Orbaz lacht.>\n\nWas ist das? Ein Malbuch für Kinder?", completion = "&lt;Orbaz blättert durch das Tagebuch.&gt;\n\nWas für ein Müll! Dies ist der \"Scharlachrote Morgen\"?\n\nSie segeln in ihren Tod! Konzentrieren wir uns lieber auf die anrückenden Armeen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12757] = {title = "Die Armeen des Scharlachroten Ansturms rücken näher...", objective = "Liefert das Buch \"Der Weg der Erlösung\" bei Hochlord Darion Mograine in \"Acherus: der Schwarzen Festung\" ab.", description = "Wir müssen uns auf die anrückenden Armeen vorbereiten, <Name>. Ihr werdet Hochlord Mograine schleunigst von Eurer Entdeckung berichten! Ich werde ein Portal direkt nach Acherus öffnen. Tretet hindurch und Ihr werdet dorthin befördert.\n\nGebt Hochlord Mograine auch Abbendis' Tagebuch. Vielleicht wird er es nützlich finden.", progress = "Ihr habt was getan?", completion = "Ihr seid zu einem Werkzeug des Untergangs geworden, &lt;Klasse&gt;! Wir werden diese anrückenden Armeen vernichten und ihre Toten zu unseren Dienern machen!", rewards = "Ihr bekommt:\n\nBlutgetränkte Saronitplattenschiftung"}
MultiLanguageQuestData['de'][12758] = {title = "Des Helden Helm", objective = "Besorgt Sprengstoff der Venture Co. von der Venture Company in Schwindelgrins' Grabungsstätte und benutzt ihn, um den Kopf eines Sturmbetrachters zu erhalten. Bringt Rejek beim Hügel der Wildherzen den Kopf des Sturmbetrachters.", description = "Rejek hört Geschichten von riesigen Metallmännern beim weit entfernten Sturmherrenschelf. Du finden es weit im Nordwesten, außerhalb des Rands des Beckens.\n\nStell dir vor, wie Rejek den Kopf eines Riesenmetallmanns als Helm benutzen. Machen Rejek unaufhaltsam! Machen Rejek mächtig!\n\nDu es holen für Rejek, aber Metallkopf vielleicht nicht einfach abzumachen von Metallkörper. Vielleicht Bomben klauen von kleinen, grünen Männchen und ihren Freunden in Schwindelgrins' Grabungsstätte in der Nähe der Sonnenstrahlsäule? Benutzen Bomben um Kopf abzukriegen von Metallkörper und bringen zu Rejek.", progress = "Du bringen Rejek neuen Helm?", completion = "Rejek sieht, du seien erfolgreich gewesen! Jetzt Rejek probieren neuen Kriegshelm auf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12759] = {title = "Instrument des Krieges", objective = "Holt einige von Zepiks Fallen aus seiner Truhe in Kartaks Stellung. Verwendet die Fallen, um 50 der sich in der Nähe aufhaltenden, funkenbesprühten Gorlocs zu töten, dann kehrt zu Schamane Jakjek in Kartaks Stellung zurück.", description = "Zepik mir erzählen, du vielleicht der beste Gorlocjäger, er getroffen... außer Zepik. Immer noch große Schlacht im Südwesten - du gehen helfen.\n\nZepik ein paar der größten, bösesten Fallen in seiner Truhe in Kartaks Stellung hat... Vekgar befohlen, sie für Kampf zu nutzen, also du sie auch benutzen. Geh jede Falle auswählen, die du willst, und töte viele von Großzungen.\n\nGanz, ganz viele!", progress = "Ziemlich durcheinander! Aber immer noch so lustig.", completion = "Du fast so gut mit diesen Fallen wie Zepik!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12760] = {title = "Geheime Kraft der Wildherzen", objective = "Nutzt den geheimen Trank der Wildherzen und tötet mit der Kraft des Tranks 30 funkenbesprühte Gorlocs um Kartaks Stellung herum.", description = "Schlacht tobt immer noch in Kartaks Stellung... Ich denke, es an der Zeit für dich, großes Geheimnis der Wildherzen zu lernen.\n\nWir haben Beeren aus anderen Ländern, aus denen wir gekommen... sie nicht so besonders an sich, aber mische sie mit Trinkgetränks und sie machen Wildherz ganz stark. Du nun ein Wildherz... es Zeit, du wirst auch stark.\n\nIch gebe dir jetzt Trinken und dann zerschmetterst du alle Funken-Großzungen.", progress = nil, completion = "Du wilder Kämpfer... komm bald zurück für mehr Kampf. Nie genug gute Kämpfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12761] = {title = "Beherrschen der Kristalle", objective = "Erlangt die Verteidigung des Kristalls in der Zuflucht der Funkenbesprühten und verwendet sie, um 50 in der Nähe befindliche Wildherzwolvar zu töten. Kehrt zu Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten zurück, sobald diese Aufgaben abgeschlossen sind.", description = "Funkenbesprühte immer noch angegriffen von Wauwaumenschen... Wir glauben, sie vielleicht nicht aufhören, wenn wir nicht sie aufhalten. Wir haben aber geheime Waffe, wir schicken sie zu Soo-met, damit er nutzen kann, um alle Orakel zu schützen.\n\nGeheime Waffe ist von den Großen persönlich... besonders glänzende Kristalle, die wir in heiligen Tempeln der Großen gefunden. Sei sehr vorsichtig, nicht zerbrechen.\n\nKristalle sind in Kiste nahe Schrein in Zuflucht der Funkenbesprühten, weit im Südwesten. Du gehst und benutzt Kristalle, um Soo-met helfen, Wauwaumenschen zu schlagen.", progress = "Sehr mächtig. Wauwaumenschen nicht wissen von Macht der Großen. Dumme Wauwaumenschen.", completion = "Danke, Trockenhaut.\n\nIch behalten diese Kristalle - sie uns beschützen. Vielleicht du kommst bald zurück und uns hilfst noch einmal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12762] = {title = "Macht der Großen", objective = "Ladet den schlafenden polierten Kristall an der offenen Lebensblutsäule. Reist zur Zuflucht der Funkenbesprühten und verwendet die Kraft des Kristalls, um 30 der sich in der Nähe aufhaltenden Wolvar der Wildherzen zu töten. Sprecht anschließend mit Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten.", description = "Wir müssen etwas unternehmen, um Wauwaumenschen aufzuhalten, die Zuflucht der Funkenbesprühten angreifen. Jaloot mir einen ganz besonderen Kristall gebracht, den er im Flussnabel gefunden hat... Wir erst einen wie ihn zuvor gesehen.\n\nDer Kristall jetzt nicht hat genug Kraft, aber die geöffnete Lebensblutsäule sollte genug Energie haben, um ihn aufzuladen, wenn du ihn in die Nähe bringst. Sobald der Kristall aufgeladen ist, geh zu Zuflucht der Funkenbesprühten im fernen Südwesten und lass dich von der Energie des Kristalls groß und stark machen.\n\nDann es Zeit, Wauwaumenschen in Hintern zu treten.", progress = "Gut, dass du uns hier hilfst. Langer Kampf.", completion = "So viel Energie in dir... voller Kraft der Großen.\n\nIch nicht lüge, ich ein bisschen neidisch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12763] = {title = "Verschiebung von Prioritäten", objective = "Späher Vor'takh möchte, dass Ihr nach Zul'Drak reist und Euch bei Unteroffizier Riannah an der Lichtbresche meldet.\n\nMakki Orkan im Lager Oneqwah wird für Euren Transport sorgen.", description = "So dringend unsere Bedürfnisse hier auch sein mögen - es gibt Neuigkeiten aus den Ländern im Norden, die wir nicht ignorieren dürfen.\n\nIch habe soeben eine Nachricht vom Argentumkreuzzug erhalten. Offensichtlich sammeln sich die Streitkräfte der Geißel dort und drohen, Zul'Drak zu überrennen.\n\nIch muss wohl kaum erwähnen, <Name>, dass unser Kampf hier aussichtslos wäre, wenn das geschähe. Ihr müsst den Kreuzzüglern dort helfen, die Armeen des Lichkönigs zurückzuschlagen.\n\nSprecht mit Makki, sobald Ihr aufbruchbereit seid.", progress = nil, completion = "Möge das Licht obsiegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12766] = {title = "Sprecht mit Eurem Abgesandten", objective = "Sprecht mit Lauriel Wahrklinge im Wyrmruhtempel.", description = "<Der Drache in Elfengestalt nimmt Euch das Vorstellungsschreiben ab, liest es sich kurz durch und steckt es in seinen Ärmel.>\n\nAlles scheint in Ordnung zu sein. Wenn es Euch jedoch nichts ausmacht, dann würde ich Euch darum bitten, mit dem Abgesandten hier im Tempel zu sprechen.\n\nSie hat noch eine Sache von großer Wichtigkeit, um die Ihr Euch kümmern solltet, bevor wir Euch hoch zur Königin schicken können.\n\n<Er klopft sich auf den Ärmel, in dem er den Brief gesteckt hat.>\n\nIch werde ihn sicher aufbewahren, bis Ihr zurück seid.", progress = nil, completion = "Ihr müsst &lt;Name&gt; sein. Man hat mir gesagt, dass Ihr kommen würdet.\n\nIch denke, dass ich hier eine Aufgabe habe, für die Ihr ganz besonders gut geeignet seid. Nehmt Euch ihrer an und Ihr würdet in die hiesige Drachengemeinschaft aufgenommen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12767] = {title = "Sprecht mit Eurem Abgesandten", objective = "Sprecht mit Golluck Felsenfaust im Wyrmruhtempel.", description = "<Der Drache in Elfengestalt nimmt Euch das Vorstellungsschreiben ab, liest es sich kurz durch und steckt es in seinen Ärmel.>\n\nAlles scheint in Ordnung zu sein. Wenn es Euch jedoch nichts ausmacht, dann würde ich Euch darum bitten, mit dem Abgesandten hier im Tempel zu sprechen.\n\nEr hat noch eine Sache von großer Wichtigkeit, um die Ihr Euch kümmern solltet, bevor wir Euch hoch zur Königin schicken können.\n\n<Er klopft sich auf den Ärmel, in dem er den Brief gesteckt hat.>\n\nIch werde ihn sicher aufbewahren, bis Ihr zurück seid.", progress = nil, completion = "Ihr müsst &lt;Name&gt; sein. Mir wurde gesagt, dass Ihr kommen würdet.\n\n\n\nIch habe hier etwas, um das Ihr Euch kümmern müsst. Tut es und Ihr würdet Euch den hiesigen Drachen beweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12768] = {title = "Der Wächter des Wyrmruhtempels", objective = "Sprecht mit Tariolstrasz im Wyrmruhtempel.", description = "Ihr habt mehr als nur Eure Vertrauenswürdigkeit bewiesen.\n\nIhr solltet zum Wyrmruhtempel zurückkehren und erneut mit dem Wächter Tariolstrasz sprechen, <Name>.", progress = nil, completion = "Schon so bald zurück, &lt;Name&gt;?\n\nCeristrasz hat uns schon berichtet, dass Ihr kommen würdet. Ich danke Euch für das, was Ihr am Rubindrachenschrein geleistet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12769] = {title = "Der Wächter des Wyrmruhtempels", objective = "Sprecht mit Tariolstrasz im Wyrmruhtempel.", description = "Ihr habt mehr als nur Eure Vertrauenswürdigkeit bewiesen.\n\nIhr solltet zum Wyrmruhtempel zurückkehren und erneut mit dem Wächter Tariolstrasz sprechen, <Name>.", progress = nil, completion = "Schon so bald zurück, &lt;Name&gt;?\n\nVargastrasz hat uns schon berichtet, dass Ihr kommen würdet. Ich danke Euch für das, was Ihr am Rubindrachenschrein geleistet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12770] = {title = "Umverteilung der Ressourcen", objective = "Gryan Starkmantel will, dass Ihr Euch bei Unteroffizier Riannah an der Lichtbresche in Zul'Drak meldet.\n\nIhr könnt wegen einer Transportmöglichkeit zur Lichtbresche bei Samuel Klarbuch vorsprechen.", description = "Hört zu, <Klasse>!\n\nEure Tage hier sind gezählt. So sehr wir fähige Kämpfer in unseren Reihen brauchen, gibt es Ärger im Norden, der unsere Probleme wie eine sommerliche Sturmwindparade erscheinen lässt.\n\nEs sieht aus, als ob die Geißel ihre Anstrengungen konzentrieren und einen Vorstoß nach Zul'Drak durchführen würde. Wenn Zul'Drak fallen sollte, könnten wir genauso gut einpacken.\n\nIhr könnt Eure Besorgungen hier noch erledigen, aber dann müsst Ihr zur Lichtbresche aufbrechen. Redet mit Samuel, wenn Ihr eine Transportmöglichkeit braucht.\n\nWegtreten.", progress = nil, completion = "Möge das Licht obsiegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12771] = {title = "Eisenschmiede", objective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu König Magni Bronzebart in Eisenschmiede bringt.", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, <Name>. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Eisenschmiede ankommt. Magni Bronzebart wird es kaum erwarten können, den Kampf nach Nordend zu tragen, und dies wird ihn sicherlich seinem Ziel ein Stück näher bringen.", progress = "Hallo <Name>. Noch nie habe ich einen kräftigeren <Volk> gesehen! Die Prüfungen der Scherbenwelt haben Euch hart gemacht, Bruder. Ihr seid der Stolz Eures Volkes!", completion = "Bei meinem Barte! Diesem hier wohnt eine Kraft inne, die einer Flotte unserer Flugmaschinen Konkurrenz machen könnte! Ich werde es meinen Kriegspriestern geben und wir werden uns einen Plan ausdenken, mit dem wir diese schrecklichen Nekropolen so schnell wie möglich wieder nach Nordend schicken können... mit uns dicht auf den Fersen!\n\nOh, Muradin, mein Bruder, du musst leben! Bei der Ehre der Bronzebärte: Ich werde dich finden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12772] = {title = "Eine verzweifelte Allianz", objective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", description = "<Guter/Gute> <Name>, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, <Name>.", progress = nil, completion = "&lt;Name&gt;, geehrter &lt;Volk&gt;, seid willkommen. Möget Ihr im Schein des Lichts baden - möge Eure uralte Weisheit unser Land in diesen Zeiten der Not schützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12773] = {title = "Darnassus", objective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu Tyrande Wisperwind in Darnassus bringt.", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, <Name>. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Darnassus ankommt. Liefert es bei Tyrande Wisperwind ab - für ihre Priesterinnen wird es einen unerlässlichen Quell der Macht im Kampfe gegen die unheiligen Streitkräfte des Nordens darstellen.", progress = "<Name>, mein Sohn. Wieder einmal sind wir in einen Konflikt verwickelt, der alles, was wir kennen, in Stücke reißen könnte. Es ist gut, dass ein <Klasse> mit Euren Talenten und Eurer Stärke uns bei der Verteidigung des Weltenbaums zu Hilfe kommt.", completion = "Was ist das? Was für ein Segen! Das Licht, das sie in diesem Artefakt aufgefangen haben, scheint beinahe so hell wie das Licht des Mondes! Unsere Priester werden diese Kraft gegen unsere Feinde einsetzen und des Lichkönigs Invasion wird mit Sicherheit fehlschlagen. Habt Dank, &lt;Name&gt;. Unser Weltenbaum wird nun in Sicherheit sein.\n\nAuch spürten wir, dass weit im Norden womöglich ein weiterer Weltenbaum existieren könnte - versteckt in der Nähe des Lichkönigs eigenen Reichs. Der Tag mag vielleicht kommen... an dem wir beide Bäume hüten und eine neue Ära des Friedens einläuten mögen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12774] = {title = "Sturmwind", objective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu König Varian Wrynn in Sturmwind bringt.", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, <Name>. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Sturmwind ankommt. Der König von Sturmwind ist vor Kurzem zurückgekehrt. Ich bin mir sicher, dass er für dieses Werkzeug dankbar sein wird.", progress = "<Name>, gut Euch zu sehen. Eure Stärke und Euer Können sind wie ein Segen in diesen Zeiten von Kummer und Schmerz.", completion = "Also haben Shattraths heilige Leute erschaffen, was sie versprochen haben! Im Nachhinein würde ich sagen, dass es die richtige Entscheidung war, so viele Priester und Paladine dorthin zu beordern, anstatt sie gegen die Geißel in den Kampf zu schicken. Mit diesen heiligen Waffen werden wir vielleicht dazu imstande sein, den verdammten Lichkönig und seine Dienerschaft zurückzuschlagen!\n\nUnd so ernenne ich Euch hiermit zu Fürst &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12775] = {title = "Eine verzweifelte Allianz", objective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", description = "<Guter/Gute> <Name>, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, <Name>.", progress = nil, completion = "Bruder, wir wurden wieder gerufen, um gegen die Geißel zu kämpfen. Es ist gut, dass Ihr hier seid - mit Eurer Stärke und der Kraft des Lichtes mögen wir vielleicht doch noch den Sieg davontragen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12776] = {title = "Die Exodar", objective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt bei Velen in der Exodar abliefert.", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, <Name>. Behaltet es stets im Auge und sorgt dafür, dass es sicher zur Exodar gelangt. Liefert es bei Prophet Velen in der Halle des Lichts ab, auf dass er seine Kräfte gegen die unheiligen Streitkräfte des Nordens einsetzen mag.", progress = "Meine Tochter, die Lande der Menschen und Orcs hatten einen positiven Einfluss auf Euch - eine solche Stärke wohnt Euch nun inne...", completion = "Ah, ich kann sehen, wie die Kraft der Naaru durch diesen Gegenstand leuchtet, als wohnte das Licht selbst in seinem Inneren. So viel Gutes kann mit diesem Werkzeug vollbracht werden; die Nekropolen, die aus den gefrorenen Weiten des Nordens geschickt wurden, werden sicherlich scheitern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12777] = {title = "Eine verzweifelte Allianz", objective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", description = "<Guter/Gute> <Name>, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, <Name>.", progress = nil, completion = "Zu sehen, dass ein nobler &lt;Volk&gt; wie Ihr uns zu Hilfe eilt, erfüllt mein Herz mit Licht. Seid gesegnet, guter &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12778] = {title = "Das Ende des Scharlachroten Kreuzzugs", objective = "Geht zur Todesbresche und sucht den Lichkönig auf.", description = "Die Falle hat zugeschnappt, Todesritter. Die Armeen von Herdweiler und Tirisfal sind angekommen; gerade rechtzeitig, um noch zu sehen, wie ihre Enklave in Flammen steht! Falls sie jetzt umkehren sollten, werden sie mit dem Rücken zu uns kämpfen müssen.\n\n<Mograine schüttelt den Kopf.>\n\nNein, ihnen bleibt nur eine Wahl, deren Resultat unumgänglich wäre: IHR ENDE!\n\nWährend wir hier noch sprechen, bereiten sie sich auf ihr letztes Gefecht vor.\n\nDer Lichkönig erwartet Eure Rückkehr, Champion. Er ist dort unten bei der Todesbresche und hält Ausschau.", progress = nil, completion = "Ihr habt mir gut gedient, &lt;Name&gt;. Die Lande des Scharlachroten Kreuzzugs wurden von der Geißel gebrandmarkt. Ihr habt für Tod und Vernichtung gesorgt, so weit das Auge reicht, und mir den letzten Rest der Armeen des Scharlachroten Kreuzzugs ans Messer geliefert.\n\n\n\nEs ist nun Zeit, dass Ihr zu Ende bringt, was Ihr begonnen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12779] = {title = "Alle Dinge müssen ein Ende...", objective = "Der Lichkönig hat Euch befohlen, den Scharlachroten Kreuzzug auszuradieren.\n\nBenutzt das Horn der Frostbrut, um einen Frostbrutbezwinger herbeizurufen und mit ihm 150 Scharlachrote Soldaten und 10 Scharlachrote Ballisten zu vernichten. Weicht Geschossen aus, indem Ihr aus ihrer Schusslinie fliegt!", description = "Ihr habt unzählige Legionen vernichtet und noch immer verlangt es Eurem dunklen Herzen nach mehr, <Name>.\n\n<Der Lichkönig hält inne.>\n\nAlle Dinge müssen ein Ende haben, Todesritter. Das letzte Aufgebot der Armeen des Scharlachroten Kreuzzugs stellt sich uns entgegen. Für sie wird es kein Entrinnen geben... Sie haben keine Wahl. Aus diesem Grund werden sie auch mit einer Wildheit kämpfen, wie Ihr sie noch nie erlebt habt.\n\nStoßt in dieses Horn und ruft einen meiner Wyrms herbei. Klettert auf seinen Rücken und reitet mit ihm in die Schlacht. Mit seiner Hilfe werdet Ihr dem Scharlachroten Kreuzzug ein Ende bereiten.", progress = "Tötet sie alle...", completion = "Kniet nieder, Ritter. Hiermit setze ich Euch diesen Helm auf, um Euer schreckenerregendes Aussehen zu vervollkommnen. Jeder, der auch nur wagen sollte, einen Blick auf Euer dunkles Antlitz zu werfen, wird wissen, dass ihn der Tod ereilen wird. Lasst niemanden es wagen, sich gegen unseren König zu stellen, ohne dass er Euren gnadenlosen Zorn zu spüren bekäme, &lt;Name&gt;.\n\nEs bleibt nur noch eine letzte Aufgabe...\n\n\n\nDie Kapelle des hoffnungsvollen Lichts.", rewards = "Ihr bekommt:\n\nGroßhelm des Geißelchampions"}
MultiLanguageQuestData['de'][12780] = {title = "Der Feind unseres Feindes", objective = "Unteroffizier Riannah in der Lichtbresche möchte, dass Ihr mit Stefan in der Schwarzen Wacht sprecht und ihm Eure Unterstützung anbietet.So geschmacklos es für uns auch sein mag, mit Todesrittern zusammenzuarbeiten, wir können uns einfach nicht leisten, bei unseren hiesigen Verbündeten wählerisch zu sein.\n\nWir sind zwischen der Geißel und den Drakkari eingeschlossen, die nichts weiter wollen, als uns aus dem Weg zu räumen, damit sie zueinander kommen können.\n\nReist nach Westen zur Schwarzen Wacht. Sprecht dort mit Stefan und seht nach, ob Ihr ihm zu Diensten sein könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "So geschmacklos es für uns auch sein mag, mit Todesrittern zusammenzuarbeiten, wir können uns einfach nicht leisten, bei unseren hiesigen Verbündeten wählerisch zu sein.\n\nWir sind zwischen der Geißel und den Drakkari eingeschlossen, die nichts weiter wollen, als uns aus dem Weg zu räumen, damit sie zueinander kommen können.\n\nReist nach Westen zur Schwarzen Wacht. Sprecht dort mit Stefan und seht nach, ob Ihr ihm zu Diensten sein könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12781] = {title = "Willkommen!", objective = "Bringt den Geschenkgutschein der Schwarzen Festung zu Siouxsie der Banshee in der Schwarzen Festung.", description = "Willkommen zu World of Warcraft!\n\nAls besonderen Dank dafür, dass Ihr die World of Warcraft Collector's Edition gekauft habt, erhaltet Ihr diesen Geschenkgutschein. Tauscht ihn bei Siouxsie der Banshee in der Schwarzen Festung ein und Ihr werdet ein Geschenk erhalten: einen kleinen Gefährten, der Euch auf Eurer Suche nach Abenteuern und Ruhm begleiten wird.\n\nNochmals danke. Genießt Euren Aufenthalt in World of Warcraft!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDiablosteinPandahalsbandZerglinglasso"}
MultiLanguageQuestData['de'][12782] = {title = "Verzweifelte Forschung", objective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", description = "<Name>, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, <Name>. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", progress = nil, completion = "Was für ein ausgezeichnetes Exemplar Ihr seid. Wir müssen viele Experimente durchführen und unser Nachschub an Freiwilligen ist fast erschöpft. So, Elfe, wie es schon Euer Name andeutet: Habt Ihr etwas Blut übrig? Frisches Blut ist immer willkommen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12783] = {title = "Verzweifelte Forschung", objective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", description = "<Name>, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, <Name>. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", progress = nil, completion = "Was für ein ausgezeichnetes, robustes Exemplar Ihr seid. Wir haben viele Experimente durchzuführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist in der Tat willkommen und mit dem Zorn in Eurem Blute ließe sich stundenlang forschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12784] = {title = "Verzweifelte Forschung", objective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", description = "<Name>, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, <Name>. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", progress = nil, completion = "Was für ein ausgezeichnetes Exemplar Ihr seid. Wir müssen viele Experimente durchführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist immer willkommen und ich bin mir sicher, dass jemand Eurer Statur etwas Blut übrig hat...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12785] = {title = "Orgrimmar", objective = "Großapotheker Putress möchte, dass Ihr Apotheker Karlov in Orgrimmar das Zwei-Seuchen-Hirn bringt.", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Orgrimmar. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Karlov. Er ist bei Thrall in Orgrimmar.", progress = "Willkommen in Orgrimmar, <Name>. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, &lt;Name&gt;, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12786] = {title = "Donnerfels", objective = "Großapotheker Putress möchte, dass Ihr Apotheker Chaney in Donnerfels das Zwei-Seuchen-Hirn bringt.", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Donnerfels. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Chaney. Er ist bei Magatha Grimmtotem in Donnerfels.", progress = "Willkommen in Donnerfels, <Name>. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, &lt;Name&gt;, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12787] = {title = "Die Unterstadt", objective = "Großapotheker Putress möchte, dass Ihr Apothekermeister Faranell in Unterstadt das Zwei-Seuchen-Hirn bringt.", description = "Die Zombieseuche war ein versteckter Segen. Auf unserer Suche nach einem Heilmittel haben wir sehr viel über die Geißel und ihre ansteckende Krankheit gelernt. Unsere Forschungen haben uns Waffen gegen sie verliehen. Waffen - und Werkzeuge...\n\nNehmt das hier, es ist der Kopf eines Zombies und er wurde zum Teil von seiner Seuche geheilt, indem wir ihm ein aus unseren neusten Entdeckungen hergestelltes Präparat injiziert haben. Liefert den Kopf beim Apothekermeister Faranell ab. Ich habe eine Liste mit Experimenten, denen der Kopf unterzogen werden soll.", progress = "Grüße, <Name>. Seid Ihr aus Shattrath gekommen? Habt Ihr Anweisungen von Großapotheker Putress für mich?", completion = "Ah, was für ein ausgezeichnetes Exemplar du doch bist. Die Krankheit - die Krankheiten, wie sie durch dein Gehirn tanzen, müssen dir so erhabene Visionen bescheren. Wir werden lange Nächte miteinander verbringen, werden sprechen, du und ich, und ich werde dir deine Gedanken herauspicken, während ich dir das Fleisch von deinem Schädel abziehe.\n\nHab keine Angst, Kleiner. Dein Opfer wird uns ein unglaubliches Wissen vermitteln. Du bist ein Geschenk für die Verlassenen - du wirst ein neues Zeitalter einläuten; ein Zeitalter, in dem wir von den Völkern dieser Erde respektiert werden. Dein Platz in der Geschichte ist sicher...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12788] = {title = "Silbermond", objective = "Großapotheker Putress möchte, dass Ihr Apothekerin Tepesh in Silbermond das Zwei-Seuchen-Hirn bringt.", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Silbermond. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meiner Assistentin Apothekerin Tepesh. Sie ist bei Lor'themar Theron in Silbermond.", progress = "Willkommen in Silbermond, <Name>. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, &lt;Name&gt;, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12789] = {title = "Auf zur Bresche!", objective = "Kreuzritter Valus bei der Lichtwarte möchte, dass Ihr Euch bei Unteroffizier Riannah in Lichtbresche in Zul'Drak meldet.", description = "Macht Euch bereit, <Klasse>. Ich entsende Euch zur Lichtbresche nordöstlich von hier.\n\nIch habe Nachricht erhalten, dass die Geißel dazu übergegangen ist, Zul'Drak einzunehmen.\n\n<Valus starrt Euch direkt in die Augen.>\n\nDies wird nicht passieren.\n\nSeht zu, dass die Diener der Geißel dort vernichtet werden. Das Licht verlangt danach.\n\nWegtreten.", progress = nil, completion = "Ausgezeichnet. Valus muss meinen Bericht erhalten haben.\n\nLasst uns an die Arbeit gehen, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12790] = {title = "Hin- und zurückkommen: mit Magie", objective = "Erzmagierin Celindra am Violetten Tor möchte, dass Ihr den Teleporter zum Kristall der Violetten Wacht und den Teleporter zum Dalarankristall verwendet.", description = "Nur, falls Ihr es nicht wissen solltet: Ihr könnt den Kristall auf der Plattform hinter mir dazu benutzen, um Euch zur Violetten Wacht im Kristallsangwald unterhalb von Dalaran zu teleportieren.\n\nIm Gegenzug könnt Ihr dann auch den Kristall in der Wache verwenden, um zur Kammer über mir zu gelangen.\n\nTut dies nun für mich.", progress = "Ich spüre, dass Ihr noch nicht alle beide Teleportationskristalle verwendet habt.\n\nMacht nichts, lasst Euch Zeit.", completion = "Ausgezeichnet, &lt;Klasse&gt;. Nun wisst Ihr, wie man zum Kristallsangwald gelangt und wie man auch wieder zurückkommt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12791] = {title = "Das magische Königreich Dalaran", objective = "Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab.", description = "Hallo, <Name>. Ihr wisst womöglich, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran liegt nicht länger unter seiner schützenden Kuppel am Ufer des Lordameresees. Nun schwebt die Insel auf magische Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr nun bereit dazu seid, zur Stadt zu reisen. Sprecht mich wieder an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nSucht Erzmagierin Celindra auf, sobald Ihr dort angekommen seid, und gebt Ihr mein Signet als Beweis dafür, dass wir gesprochen haben.", progress = "Ich grüße Euch, <Klasse>.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12792] = {title = "Das Wichtigste zuerst", objective = "Kommandant Kunz in der Argentumwacht möchte, dass Ihr Euch bei Unteroffizier Riannah in der Lichtbresche meldet.", description = "Hört gut zu, <Volk>!\n\nIn der gesamten Region kriselt es. Überall, wo Ihr hinseht, werdet Ihr Leute finden, die Eure Hilfe gebrauchen könnten.\n\n<Kunz blickt Euch direkt in die Augen.>\n\nDoch niemand braucht Eure Hilfe gerade dringender als Riannah. Die Diener der Geißel haben sich nun zwischen uns gedrängt. Sie und ihre Männer sind also abgeschnitten.\n\nLichtbresche, der Ort, an dem sich ihre Streitkräfte befinden, liegt gleich südwestlich von hier.", progress = nil, completion = "Mein Bericht muss Kunz erreicht haben.\n\nEs ist gut zu wissen, dass er wohlauf ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12793] = {title = "Rauch am Horizont", objective = "Khufu in Zim'Torga möchte, dass Ihr zur Lichtbresche reist und Euch bei Unteroffizier Riannah meldet.\n\nMaaka wird Euch dorthin bringen.", description = "Habt Ihr das gehört, <Volk>?\n\nDas Schlachtengeschrei weit im Westen reicht bis hierher und übertönt selbst unser eigenes.\n\nDie Geißel droht damit, durch die Linien derer zu brechen, die dem sogenannten Argentumkreuzzug angehören. Dies zu verhindern, ist so dringend vonnöten, wie alles andere in der Region.\n\nReist zur Lichtbresche und unterstützt sie bei ihrem Kampf dort. Sprecht mit Maaka und er wird Euch sicher dorthin bringen.", progress = nil, completion = "Möge das Licht obsiegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12794] = {title = "Das magische Königreich Dalaran", objective = "Bringt der Erzmagierin Celindra am Violetten Tor in Dalaran das Signet der Kirin Tor.", description = "Hallo, <Name>. Es ist Euch möglicherweise bekannt, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran befindet sich nun nicht länger unter der schützenden Kuppel an den Ufern des Lordameresees. Nun schwebt die Stadt auf magische Art und Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr bereit seid, zu der Stadt zu reisen. Sprecht mich erneut an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nWenn Ihr dort seid, so sprecht mit der Erzmagierin Celindra und gebt ihr mein Signet als Beweis dafür, dass Ihr von mir kommt.", progress = "Ich grüße Euch, <Klasse>.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12795] = {title = "Farbe bekennen", objective = "Datura Blutrose an der Schwarzen Wacht möchte, dass Ihr mit Kommandant Falstaav in der Argentumwache sprecht.", description = "Gerade erst habe ich ein Signalfeuer über der Baumlinie gen Osten gesehen.\n\nDas kann nur bedeuten, dass die Dinge für die Kreuzfahrer in der Argentumwache nicht so glatt laufen.\n\nIch kann unseren Posten hier nicht verlassen, <Volk>, Ihr jedoch schon. Wenn es die Zeit erlaubt, dann macht Euch auf den Weg zu Kommandant Falstaav und seht nach, ob Ihr ihnen nicht die Arbeit erleichtern könnt.", progress = nil, completion = "Wie es der Zufall so will, gibt es da etwas, bei dem Ihr uns helfen könnt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12796] = {title = "Das magische Königreich Dalaran", objective = "Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab.", description = "Hallo, <Name>. Ihr wisst womöglich, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran liegt nicht länger unter seiner schützenden Kuppel am Ufer des Lordameresees. Nun schwebt die Insel auf magische Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr nun bereit dazu seid, zur Stadt zu reisen. Sprecht mich wieder an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nSucht Erzmagierin Celindra auf, sobald Ihr dort angekommen seid, und gebt Ihr mein Signet als Beweis dafür, dass wir gesprochen haben.", progress = "Ich grüße Euch, <Klasse>.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12797] = {title = "Zurück durchs Tor", objective = "Bringt die Omegarune zum Avatar von Freya im Katarakt der Regenrufer im Sholazarbecken.", description = "Ihr sagt die Wahrheit, <Volk>. Ich kann spüren, wie die Essenz des Sholazarbeckens selbst jetzt, während wir hier miteinander sprechen, durch die untote Seuche allmählich verbraucht wird.\n\nIch habe mich selbst, mein Sein, an diese Rune gebunden, <Volk>. Bringt sie zu derjenigen, die Euch hierher geschickt hat; denn nur ihre eigene Macht kann mir den Zugang zu ihrem Reich gewähren.", progress = "Ihr seid zurückgekehrt, <Name>.", completion = "Gut gemacht.\n\nWehe unseren Feinden. Wehe denjenigen, die dem Lichkönig dienen und den Kreationen der Titanen mit Zerstörung drohen. Wehe - denn der Etymidian ist gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12798] = {title = "Schwertkartenset", objective = "Beschwört mithilfe des Schwertkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", description = "Jetzt, da Ihr alle Schwertkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set der Schwertkarten zusammen zu bekommen! Ausgezeichnet.", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", rewards = "Dunkle StoffschulternGedeckte LederschulterpolsterAzurblauer Schulterschutz"}
MultiLanguageQuestData['de'][12799] = {title = "Geister aufsaugen", objective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 5 Einheiten uralten Ektoplasmas von den verlorenen Drakkarigeistern in den Teichen von Zha'jin sammelt.", description = "\"Ihr solltet froh sein, dass er kommt,\" meinten sie. \"Ihr werdet seine Gesellschaft genießen,\" meinten sie...\n\nTja, es ist nicht so, als hätte ich in der Sache irgendeine Wahl. Finkelstein ist der beste Alchemist des Kreuzzugs. Ich nehme einmal an, dass ich mich geehrt fühlen sollte, dass er sich hier bei mir eingerichtet hat. Doch seitdem er hier ist, wurde ich dazu verbannt, verschiedene alchemistische Zutaten zu sammeln.\n\nSagt mir, <Volk>, was haltet Ihr davon, wenn Ihr mir zur Hand ginget? Gleich südlich von hier gibt es ein paar Teiche, die von Geistern der uralten Trolle heimgesucht werden. Bringt mir ihr Ektoplasma.", progress = "Guten Tag, <Volk>. Habt Ihr das Ektoplasma gesammelt, um das Finkelstein gebeten hat?", completion = "Habt Dank, &lt;Klasse&gt;.\n\nDas sollte meinen Männern wertvolle Zeit ersparen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12800] = {title = "Befehl des Lichkönigs", objective = "Meldet Euch bei Geißelkommandant Thalanor bei Braumanns Mühle.", description = "Die Scharlachrote Enklave gibt es nicht mehr und um die Reste des Kreuzzugs wird man sich in Nordend kümmern.\n\nWir werden nun all unsere Aufmerksamkeit auf die Kapelle des Hoffnungsvollen Lichts richten. Wir werden es nicht mehr zulassen, dass diese Beleidigung an Euren Meister weiter existiert!\n\nIch habe meinen letzten Befehl erteilt. Geißelkommandant Thalanor erwartet Euch an Braumanns Mühle. Geht nach Nordwesten, dann durch die Höhle und Ihr erreicht das Giftige Tal. Folgt dem Pfad aus dem Tal heraus und Ihr werdet zur Mühle gelangen.\n\nEnttäuscht mich nicht, <Name>.", progress = nil, completion = "Der Hochlord und die anderen &lt;Klasse&gt; sind bereit zuzuschlagen! Wir werden den letzten Rest Leben von diesem Flecken Erde tilgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12801] = {title = "Das Licht der Morgendämmerung", objective = "Besiegt die Streitkräfte der Argentumdämmerung und findet das Licht der Morgendämmerung.\n\nMeldet Euch bei Hochlord Darion Mograine, falls Ihr überleben solltet.", description = "Die Diener der Argentumdämmerung in der Kapelle des Hoffnungsvollen Lichts lehnen sich gegen uns auf. Sie wagen es, sich der Geißel entgegenzustellen, und allein aus diesem Grund müssen sie vernichtet werden!\n\nDie mächtigen Armeen des Lichkönigs stehen für die kommende letzte Schlacht um die Pestländer bereit. Heute werden wir als Helden der Geißel verewigt werden!\n\nMeldet Euch bei Hochlord Darion Mograine, wenn Ihr kampfbereit seid. Er wird den endgültigen Marschbefehl geben und unsere Armeen bei der Kapelle des Hoffnungsvollen Lichts anführen.", progress = "<Hochlord Mograine nickt.>", completion = "Für uns wird es keine Buße geben, &lt;Name&gt;. Wir sind auf ewig dazu verdammt, als Monster auf dieser Welt zu wandeln. Der Lichkönig mag uns zwar nicht mehr völlig beherrschen, doch die Geister unserer Vergangenheit werden auf ewig unsere Erinnerungen heimsuchen.\n\nWir müssen es also auf die einzige Art und Weise wiedergutmachen, in der wir uns verstehen: das Töten...\n\nIch ersuche Euch also, mir nach Acherus zu folgen und dort als Ritter der Schwarzen Klinge zu dienen. Gemeinsam werden wir den Lichkönig vernichten und der Geißel ein Ende machen.", rewards = "Großschwert der Schwarzen KlingeGroßaxt der Schwarzen KlingeIhr erlernt:\n\nSchwarzes Tor\n\nDer folgende Zauber wird auf euch gewirkt:\n\nLehren: Schwarzes Tor\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12802] = {title = "Mein Herz liegt in Euren Händen", objective = "Drakuru möchte, dass Ihr ihm das Herz der Uralten zur Drak'atal Passage bringt.\n\nUm das Elixier verwenden zu können, müsst Ihr 5 verzweifelte Mojo sammeln.", description = "<Drakurus Stimme erfüllt Euren Geist.>\n\nHe, Mann! Das Auge der Propheten is' der Wahnsinn! Ich hab's benutzt, um dich zu beobachten un' ich seh', du hast jetzt das Herz! Nich' schlecht...\n\nJetzt musst du's zu meinem Podest bei der Passage von Drak'atal bringen, 'n kleines Stück östlich von hier.\n\nAuf dem Sockel da musst du mein Elixier trink'n, um mich zu beschwör'n. Diesmal musst du 'n bisschen verzweifeltes Mojo von den Verteidigern da reinmischen, damit's klappt.", progress = nil, completion = "Beeindruckend, Mann! Gütig vom Schicksal, dass es uns zusamm'gebracht hat.\n\nBald säuber' ich Drak'Tharon und nehm' Rache für meine Brüda. Un' du kriegst Drak'Tharons größten Schatz zur Belohnung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12803] = {title = "Naturgewalt", objective = "Begebt Euch zur Seuchenfront zwischen dem Katarakt der Regenrufer und den Verlorenen Landen im Sholazarbecken und sucht den Avatar von Freya.", description = "Ich bin nicht sicher, was ich sah, als ich nach Nordosten flog, aber es sah aus wie eine gigantische Frau, die in den Landen dort die Geißel aufmischte.\n\nIch hörte den Professor über eine gewisse \"Lebenswächterin\" sprechen, von den Titanen dazu beauftragt, das Sholazarbecken zu behüten. Ich bin nicht bewandert in Titanengeschichte, aber das klingt, als sei sie die Richtige.\n\nIch weiß auch, dass alle Teilnehmer unserer Expedition so gut wie tot sind, wenn die Geißel die Grenze zwischen den Verlorenen Landen und dem Rest von Sholazar überquert. Was haltet Ihr davon, sie zu suchen und ihr zu helfen?", progress = nil, completion = "Ihr seid nicht von hier. Aber Ihr gehört auch nicht zur Geißel.\n\nWas soll ich mit Euch anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12804] = {title = "Ein Steak für Jäger", objective = "Bringt 5 Langhalsgrasfresser-Steaks zu Korg dem Spalter in Nesingwarys Basislager.", description = "Manchmal gibt es nichts Schlimmeres als ein Lager voller Jäger. Die sind so erpicht darauf, Raubtiere zu erlegen, dass ich nur trockenes, zähes Fleisch bekomme. Und das ist nicht gerade etwas, worauf man sich nach einem langen, beschwerlichen Tag auf der Jagd freuen kann.\n\nZum Glück kann man hier in der Nähe aber auch zartes, saftiges Fleisch finden. Südlich des Flusses und Lagers leben Langhalsgrasfresser. Das wäre wirklich perfektes Fleisch für unsere hungrigen Jäger. Bringt mir die besten Fleischstücke und wir können einen Festschmaus für unsere Kameraden zubereiten.", progress = "Habt Ihr die Steaks?", completion = "Das nenne ich eine Mahlzeit! Wenn es etwas Gutes an dem Schiffbruch gibt, dann wohl, dass wir davor bewahrt worden sind, einen Monat lang nichts anderes als Pökelfleisch zu essen! Vielen Dank nochmals, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12805] = {title = "Einfangen von Lebenskraft", objective = "Der Avatar von Freya möchte, dass Ihr Euch zur Versprengten Scherbe im Südosten begebt und den Edelstein der Lebenskraft an 8 vernichteten Lebensblutelementaren verwendet.", description = "Die Lebensblutsäule wurde mit brachialer Gewalt umgeworfen und ließ die Erde selbst erbeben.\n\nDie Elementare, die sich bei der Versprengten Scherbe aufhalten, tragen die Lebensessenz in sich, die der Säule ihre Stärke verlieh. Ich kann nicht zulassen, dass diese Energie verschwendet wird, denn nur vier Säulen bestehen noch.\n\nBegebt Euch zur Versprengten Scherbe im Südosten und sucht die Lebensblutelementare.\n\nVerwendet diesen Edelstein bei ihren Überresten, um ihre wilde Energie einzufangen. Wir brauchen diese Energie, um das Land zu heilen, wenn alles vorüber ist.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Der Sturz der Säule ist eine Schande, doch wir müssen retten, was noch zu retten ist.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12806] = {title = "Zur Todesanhöhe so schnell Ihr könnt!", objective = "Meldet Euch bei Lordkommandant Arete auf der Todesanhöhe in Eiskrone.", description = "Einige würden sagen, dass unsere allerwichtigste Aufgabe nicht den Lichkönig betrifft, sondern die völlige Zerstörung des Scharlachroten Ansturms. Eine Torheit, wie ich meine, doch wer bin ich, um darüber urteilen zu können?\n\nDie Todesanhöhe befindet sich weit im Südwesten an den Klippen, die über das Meer hinausblicken. Dort befindet sich Lordkommandant Arete und führt höchstpersönlich Aufsicht über die Zerstörung des Scharlachroten Ansturms.\n\n<Der Baron räuspert sich.>\n\nSeht zu, dass Ihr Euch so schnell wie möglich bei ihm meldet. Er hat nach Euch und nur nach Euch gefragt.", progress = nil, completion = "Wurde verdammt noch mal Zeit! Zweifellos hat Baron Splitter sich Zeit gelassen, Euch zu mir zu schicken.\n\nIch sollte den leeren Platz zwischen seinen Schultern entfernen lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12807] = {title = "Was bis jetzt geschehen ist...", objective = "Lauscht Lordkommandant Aretes Erzählung über die Todesanhöhe.", description = "Wir haben viel zu tun, aber ich finde, zuerst steht eine kleine Gedächtnisauffrischung an.\n\nWir Todesritter haben eine anschauliche Vergangenheit mit unseren Freunden, den Scharlachroten, hinter uns - und die sind dumm genug, sich im nordwestlich gelegenen Hafen unter uns auszuruhen.\n\nWenn Ihr bereit für ein paar Worte seid, dann wendet Euch noch einmal an mich und ich werde Euch erleuchten.", progress = nil, completion = "In seiner Torheit hat sich der Argentumkreuzzug entschieden, angesichts der Anwesenheit des Scharlachroten Ansturms ein Auge zuzudrücken. Wir hingegen werden das nicht tun.\n\nEs ist uns gleich, ob sie im Kampf gegen den Lichkönig hilfreich wären. Wir halten sie nicht für würdig genug, um zu existieren. Wir werden ihnen ein Ende bereiten, ein für alle Mal!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12808] = {title = "Eine verzweifelte Allianz", objective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", description = "<Guter/Gute> <Name>, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, <Name>.", progress = nil, completion = "Mein gnomischer Bruder, ich bin stolz, in diesen Zeiten der Not an Eurer Seite stehen zu dürfen. Seid gesegnet und mögen die schlauen Augen Eures Volkes den Weg zu unserer Erlösung finden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12809] = {title = "Eisenschmiede", objective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu Hochtüftler Mekkadrill in Eisenschmiede bringt.", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, <Name>. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Eisenschmiede ankommt. Hochtüftler Mekkadrill in Tüftlerstadt wird es kaum erwarten können, sich die Kraft des Artefakts zu Nutze zu machen.", progress = "Hallo, <Name>! Seht Euch mal an! Ich sehe, dass Ihr seit unserer letzten Begegnung haargenau einskommasieben-drei Mikrometer gewachsen seid. Die Luft der Scherbenwelt hatte einen Effekt auf Euch, da bin ich mir sicher.", completion = "Unglaublich makellos! Der Grad an Lichtenergie, den dieses Gerät speichern kann, übersteigt alles bisher Bekannte! Oh, nur daran zu denken, welche Möglichkeiten sich dadurch eröffnen, lässt meine Bartstoppeln zittern und meine Zehennägel sich aufstellen - ho, ho! Der antinachtaktive Photostreugenoauslöser, den ich daraus herstellen könnte, würde die Nacht zum Tage machen! Die Geißel wird gar nicht wissen, wie Ihr geschieht. Wir werden sie alle mit nur einem Zug am Hebel vernichten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12810] = {title = "Blut im Wasser", objective = "Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr die Blutblase mit dem Blut von 10 ausgehungerten Haien füllt.", description = "Die Truppen im Hafen des Ansturms haben erhebliche Verstärkung durch Greifenreiter erhalten. Ihr braucht ein Reittier, mit dem Ihr sie aus der Luft holen könnt. Doch zunächst benötigen wir die Komponenten für das Ritual, das dies erst einmal ermöglichen wird.\n\nEine beträchtliche Menge Blut ist für die Durchführung des Rituals vonnöten.\n\n<Der Lordkommandant deutet nach Nordwesten hinab.>\n\nUnten im Hafen gibt es bereits verfügbare Vorräte... Haie. Kehrt nicht zurück, ehe Ihr nicht diese Blase mit ihrem Blut gefüllt habt.", progress = nil, completion = "Gut gemacht. Nehmt Euch einen Moment Zeit, das Salzwasser auf Eurer Haut zu trocknen, ehe wir fortfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12811] = {title = "Verzweifelte Forschung", objective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", description = "<Name>, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, <Name>. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", progress = nil, completion = "Was für ein ausgezeichnetes, robustes Exemplar Ihr seid. Wir haben viele Experimente durchzuführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist in der Tat willkommen und mit Eurem wilden Blut ließe sich stundenlang experimentieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12812] = {title = "Orgrimmar", objective = "Großapotheker Putress möchte, dass Ihr Apotheker Karlov in Orgrimmar das Zwei-Seuchen-Hirn bringt.", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Orgrimmar. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Karlov. Er ist bei Thrall in Orgrimmar.", progress = "Grüße, <Name>. Seid Ihr aus Shattrath gekommen? Habt Ihr Anweisungen von Großapotheker Putress für mich?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, &lt;Name&gt;, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12813] = {title = "Erhebt euch von den Toten!", objective = "Setaal Dunkelheiler auf der Todesanhöhe hat Euch die Tinktur des Dunkelheilers gegeben. Träufelt sie auf 10 beliebige Leichen der Einheiten des Scharlachroten Ansturms, die Ihr im Hafen des Ansturms findet.", description = "Wie gütig... wie großzügig unser Lordkommandant doch ist. Wo er Blumen und Sonnenschein ist, bin ich nur von Hass erfüllt.\n\nEs reicht nicht, ihre erbärmlichen Leben zu beenden - ich möchte sie erniedrigen... entwürdigen!\n\nWas könnte unaussprechlicher sein, als sich in das zu verwandeln, was man hasst? Seine Existenz der Auslöschung einer Sache zu widmen und dann am Ende selbst dazu zu werden?\n\nWie traurig.\n\nBringt diese Tinktur nach Nordwesten zum Hafen des Ansturms. Träufelt sie auf ihre reglosen Leichen und beobachtet das Geschehen - aber meidet die Kathedrale.", progress = nil, completion = "&lt;Der Todesritter der Draenei fixiert Euch mit kaltem, starrem Blick, ihre Augen leer und tot. Ein durchtriebenes Grinsen kriecht über ihre Gesichtszüge.&gt;\n\nIch habe noch mehr Tinktur für morgen vorbereitet. Auf dann, gehabt Euch wohl.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12814] = {title = "Ihr werdet einen Greifen brauchen", objective = "Bringt Uzo Todesrufer auf der Todesanhöhe einen Greifen des Ansturms.", description = "Was könnte passender sein, als einen ihrer eigenen Greifen gegen sie einzusetzen? Geht zum Hafen des Ansturms und nehmt die Zügel eines ihrer Greifen aus den toten Klauen seines Reiters.\n\nKehrt mit dem Greifen zu Uzo Todesrufer zurück. Er wird für seine Verwandlung sorgen und Euch weitere Instruktionen geben.", progress = "Warum hat das so lange gedauert? Sind ihre Greifen langsam? Dagegen müssen wir etwas unternehmen!", completion = "Oh ja, das wird gut!\n\nTretet zurück... ich werde den Zorn des Blutrituals herbeirufen!", rewards = "Helm des ErgebenenArmschienen des GreifenreitersGreifenfellmokassinsStulpen der DringlichkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12815] = {title = "Flugsperrzone", objective = "Uzo Todesrufer auf der Todesanhöhe möchte, dass Ihr 10 Greifenreiter des Ansturms tötet.", description = "Nun, da du einen Knochengreifen hast, möchte ich, dass du jeden Tag dort hinunter fliegst und den Luftraum über dem Hafen des Ansturms zu einer Flugverbotszone machst.\n\nIch muss zugeben, Mann, dass es mich nicht wirklich juckt, ob du die Greifenreiter nun mit dem Knochengreifen tötest oder nich'. Doch ich meine, dass es um einiges einfacher sein wird, zu ihnen zu kommen, wenn du den Greifen nimmst.\n\nDavon abgesehen verfügt er über eine Menge netter kleiner Tricks, die du dir zunutze machen kannst.", progress = "Wieso bist du so schnell schon zurück? Wenn mich meine Augen nicht täuschen, dann fliegen diese Jungs vom Ansturm noch immer da rum!", completion = "So soll's sein! Und weißt du was? Das muss jeden Tag, den wir hier sind, gemacht werden.\n\nIch hoffe, dass du morgen wieder zurückkommen wirst. Dein Knochengreif wird auf dich warten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12816] = {title = "Untersucht die Geißel bei Silbermond", objective = "Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Silbermond und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Silbermond gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr Eure Untersuchung schon abgeschlossen? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12817] = {title = "Untersucht die Geißel bei der Exodar", objective = "Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb der Exodar und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers. Kehrt anschließend zu Leutnant Kregor zurück.", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung der Exodar gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", progress = "Habt Ihr Eure Untersuchung schon abgeschlossen? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12818] = {title = "Aufräumen", objective = "Jeer Funksockel in K3 hätte gerne 10 verbrannte Trümmer.", description = "Um auf den Punkt zu kommen... Ricket hat mich gebeten, ein paar stärkere Landminen zusammenzubauen, aber mir gehen die Teile aus.\n\nDirekt westlich der Stadt findet Ihr die Überreste unseres letzten Raketenschlittens... Ricket war ein wenig aufgeregt, als sie ihn auftankte, aber vermutlich hätte ich den Einfüllstutzen auch nicht direkt über den Schubdüsen anbringen dürfen. Aus Fehlern lernt man, nicht wahr?\n\nUm den kaputten Schlitten herum sollten jede Menge Ersatzteile liegen... Wieso geht Ihr nicht los, verjagt diese Plünderer und schnappt Euch ein paar Trümmer?", progress = "Wir brauchen etwas, das wir zur Isolation unserer Maschinen gegen die Kälte verwenden können... denk nach, Jeer, denk nach!\n\nOh, he! Habt Ihr ein paar dieser Trümmer für mich?", completion = "Die kann ich gut gebrauchen, danke!\n\nIhr habt da draußen nicht zufällig Dim gesehen? Ich habe ihn schon vor einer ganzen Weile weggeschickt und er kam bisher nicht zurück. Ich hoffe, es geht ihm gut.\n\nWo wir gerade davon sprechen... Ich frage mich, wo Janks ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12819] = {title = "Nur einen Minenwurf entfernt", objective = "Jeer Funksockel in K3 bittet Euch, dass Ihr Funksockels Werkzeuge aus seinem Minenfeld holt.", description = "Verflixt nochmal! Wo sind meine Werkzeuge? Gerade eben waren sie doch noch da.\n\nOh! Ich habe sie wohl vergessen, als ich das Minenfeld im Westen angelegt habe. Das ist ziemlich ärgerlich. Ich wäre sehr erfreut, wenn Ihr mir die Werkzeuge wieder beschaffen könntet. Ihr müsst allerdings vorsichtig sein, wo Ihr hintretet... Ihr solltet denselben Weg benutzen können, auf dem ich herausgekommen bin.\n\nOh, versucht übrigens nicht, dorthin zu fliegen... ich war nämlich so klug und habe Türme aufgestellt, die alles angreifen, was aus der Luft kommt. Und sie kümmern sich nicht sonderlich darum, wer angeflogen kommt.", progress = "Wenn Janks hier wäre, hätte ich einfach ihn schicken können. Aber... wenn ich's mir recht überlege... bin ich mir nicht sicher, ob ich ihm überhaupt gesagt habe, wo der sichere Weg ist.\n\nNa, zum Glück gibt es hier ja genügend von Euch Abenteurern, nicht wahr?", completion = "Ha ha! Das sind sie! Danke vielmals. Hoffentlich hattet Ihr nicht allzu große Probleme auf Eurem Weg durch das Feld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12820] = {title = "Zwölf auf einen Streich", objective = "Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor 12 Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger.", description = "Ich warte schon eine Ewigkeit auf diese Minen! Naja, zumindest einige Tage. Warum hat das so lange gedauert?\n\nAlso, die Sache ist die, <Kompadre/meine Beste>... es gibt da einen wilden Haufen von Magnatauren - man kennt sie ja... groß, behaart und unglaublich hässlich. Und sie sind ganz scharf darauf, sich K3 unter den Nagel zu reißen.\n\nWird aber nicht klappen.\n\nWir haben ihnen ein paar Steine in den Weg gelegt... nordöstlich von hier steht unsere Verteidigung. Leider sind die Energievorräte unserer Lasertürme ziemlich eingeschränkt... und da kommen diese Minen ins Spiel! Begebt Euch dorthin und jagt sie in die Luft!", progress = nil, completion = "Also... ich habe hier gesessen und habe mich an meiner eigenen Vollkommenheit gelabt, als ich in der Ferne einen Knall gehört habe! Und dann noch einen! Und noch ein Dutzend mehr! Bei dem Gedanken daran, dass all diese Magnatauren und Schneebolde in den Tod rennen, hat sich ein kleines, aber feines Lächeln in mein liebliches Gesicht geschlichen.\n\nWar es so fantastisch, wie ich es mir vorstelle?", rewards = "EisenwollbindungenOrkanwindschutzPlattenschädelschutzAuf Euch wartet eine dieser Belohnungen:\n\nSouvenirring der K3-Expedition\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12821] = {title = "Zellenblocktango", objective = "Ricket am K3 möchte, dass Ihr den Transporterakku findet und damit die Transporterplatte in Garms Erhebung aktiviert.", description = "Der Pioniertrupp ist bereit! Das heißt, dass jetzt Spaß angesagt ist!\n\nUnserem großen Angriff auf Garm steht nur noch eine Sache im Weg! Ich habe einen Läufer losgeschickt, um einen Teleporter hinter ihm aufzustellen... mit Erfolg, wenn ich das hinzufügen darf. Er ist zurückgekommen, um den Akku zu holen, der für den Betrieb benötigt wird. Aber der Teleporter funktioniert immer noch nicht... das heißt, dass der Akku dort nicht angekommen ist.\n\nIch möchte, dass Ihr auf der anderen Seite von Garms Bann nach dem Transporterakku sucht. Bringt ihn dann weiter östlich zu Garms Erhebung, sobald Ihr ihn gefunden habt, und aktiviert den Teleporter.", progress = "Selbst Magnatauren sollten wissen, dass man sich am besten nicht mit Goblins anlegt!", completion = "Hervorragend!\n\n&lt;Ein böses Grinsen breitet sich in Rickets Gesicht aus.&gt;\n\nDie Zerstörung kann beginnen!", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12822] = {title = "Kenne keine Furcht", objective = "Ricket auf dem K3 möchte, dass Ihr 6 Garmwächter und 8 schneeblinde Anhänger tötet.", description = "Nun verfügen wir über einen offenen Teleporter, doch mein Plan ist äußerst komplex und facettenreich, weswegen er eine fehlerfreie Koordinierung erfordert. Außerdem müssen Vorräte gesammelt werden! Und Truppen rekrutiert! Voraussichtlich kommen Wochen voll harter Arbeit auf Euch zu!\n\nHaha, da habe ich Euch aber einen Schrecken eingejagt, oder? Hier, Freundchen, springt durch den Teleporter und dann auf in den Kampf!! Unsere Pioniere werden Euch Deckung geben... Sie können nicht entkommen!", progress = nil, completion = "Haha! Das wird diese Rohlinge lehren, unsere Zeit zu verschwenden. Von diesem Tag an wird der Anblick grüner Haut die Herzen aller Magnatauren mit Furcht erfüllen!", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12823] = {title = "Ein perfekter Plan", objective = "Gino auf Garms Erhebung möchte, dass Ihr das dichtgepackte Sprengstoffbündel in der Nähe von Frostgeweides Altar anbringt und anschließend Tormar Frostgeweide tötet. Danach sollt Ihr entkommen, bevor die Höhle über Euch einbricht.", description = "Hallo! Ihr wollt Euch uns für den Angriff anschließen, nehme ich an?\n\nIch habe eine besondere Aufgabe für Euch... wir werden dafür sorgen, dass die gesamte Höhle über ihnen einstürzt! Am hinteren Ende der Höhle müsste Frostgeweides Altar zu finden sein. Schleicht Euch heran und bringt dieses dichtgepackte Sprengstoffbündel irgendwo in der Nähe an.\n\nSobald der Sprengstoff erst einmal platziert ist, sollt Ihr noch lange genug bleiben, um sicherzustellen, dass Frostgeweide auch ins Gras beißt, und dann so schnell wie möglich verschwinden! Niemand weiß, wie lange die Höhle intakt bleibt, nachdem das Ding in die Luft geflogen ist!", progress = "Das Sprengstoffbündel ist mein Baby... Ich habe Wochen gebraucht, um es perfekt hinzubekommen. WOCHEN!\n\nDas ist eine lange Zeit... okay.", completion = "Der ganze Berg hat gebebt! War es toll? Ich bin mir sicher, dass es das war! Wie könnte es auch anders sein?\n\nUnd die Erfinderliga beschwert sich darüber, dass alle meine Erfindungen in die Luft fliegen. Natürlich tun sie das! Ha!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12824] = {title = "Explosive Stimmung", objective = "Begebt Euch zu Ricket am K3.", description = "Ihr seid aber schnell, das muss ich schon sagen! Danke für die Hilfe mit dem Sprengstoff... ich habe schon seit geraumer Zeit darauf gewartet, diese Erfindung mal richtig zu testen!\n\nGeht zu Ricket und berichtet ihr, dass wir nun keine Probleme mehr mit den Magnatauren haben sollten... meine Pioniere werden sich um die restlichen kümmern.\n\nDanke vielmals!", progress = nil, completion = "Ihr habt alles in die Luft gejagt? So wird's gemacht! Ich wette, dass Gino großen Spaß dabei hatte!\n\nWir sind sehr dankbar für Eure große Hilfe, &lt;Name&gt;. Wie wäre es im Gegenzug mit einem Geschenk?", rewards = "Chirurgenhandschuhe von K3Schrotsicherer FeldchirurgenschutzMammutmukluksRickets HausteckenGoblinischer SchadensabsorbiererIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12825] = {title = "Ein Zeichen des Dankes", objective = "[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12826] = {title = "Leicht instabil", objective = "Liefert Jeers verbesserte Landminen bei Ricket am K3 ab.", description = "Fantastisch!\n\nNein, nicht Ihr... meine neuen Minen. Ihr seid schon etwas eingebildet, wie? Ich allerdings bin absolut brillant! Mein Intellekt ist unerreicht.\n\nÜber was hatten wir nochmal gesprochen? Ach ja, meine neuen Minen! Neu und verbessert... bereit für jede hinterhältige Idee, die Ricket wieder ausgeheckt haben mag.\n\nSeid doch bitte so nett und bringt sie zu Ricket. Sie ist gleich da drüben... wird also keine allzu lange Reise werden. Seid jedoch vorsichtig, sie ist etwas durchgeknallt.", progress = "Jeer ist fertig mit den Minen? Fein.", completion = "Hach, sind das nicht die süßesten kleinen Babys der Zerstörung, die es auf der Welt gibt?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12827] = {title = "Rationen-Recycling", objective = "Ricket am K3 bittet Euch, 16 getrocknete Gnollmahlzeiten von den wilden Hügelgnollen in der Nähe zu beschaffen.", description = "Hey! Ein neues Gesicht! Wollt Ihr Ricket vielleicht zur Hand gehen?\n\nWir haben gerade ein etwas unerwartetes Problem... Nahrungsmangel. Ich weiß, ich weiß... wir hätten das voraussehen müssen, aber die Sache ist die: Hier kommen viele Pioniergruppen durch, die jedoch nicht allzu lange bleiben, weswegen wir uns normalerweise keine Sorgen um Langzeitverköstigungen machen müssen. Doch der gute, alte K3 scheint ja jetzt ziemlich gefragt zu sein.\n\nOb es eine bequeme Lösung gibt? Im Westen befinden sich einige Lager der Gnolle... und wie es Gnolle nun einmal so an sich haben, sind auch einige dort in der Gegend verstreut, auf der Suche nach Nahrung. Hättet Ihr etwas dagegen, ein paar ihrer Rationen zu stibitzen?", progress = "Ah, hallo! Mein Magen knurrt schon... wie ist es gelaufen?", completion = "Hoffentlich haben sie sich nicht allzu sehr geziert, als es darum ging, ihre Kostbarkeiten mit Euch zu teilen. Wir sind bisher immer ziemlich gnädig gewesen, wenn sie sich an unsere Reste gemacht haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12828] = {title = "Welch Eingebung!", objective = "Ricket auf dem K3 möchte, dass ihr ein I.D.S.V. besorgt, damit ein Mammut in die Luft jagt und 8 Stücke herzhaftes Mammutfleisch einsammelt.", description = "Huch, das Zeug ist bösartig! Vielleicht nicht für den Geschmack eines Gnolls oder so, aber ich dachte, dass, was auch immer sie hatten, wenigstens... essbar wäre?\n\nDann müssen wir eben kreativer sein.\n\nTore besitzt einen Sprengstoffspender nördlich der Stadt... nicht weit vom großen Höhleneingang, könnt ihn nicht übersehen. Ich bin sicher, sie hat den Sprengstoff für irgendwelche Grabungsarbeiten vorgesehen, aber ich habe eine bessere Idee.\n\nNehmt Euch etwas davon und bewerft damit eines der Mammuts in der Nähe... die meisten von ihnen halten sich im Westen auf. Sammelt das Fleisch und bringt es zurück.", progress = "Ich weiß, mein Plan war brillant. Macht Euch keine Sorgen.\n\nFühlt es sich in dieser Präsenz von Großartigkeit nicht wunderbar an? Ein bisschen kribbelnd vielleicht?", completion = "Und es ist bereits erledigt! Ich übertreffe mich zuweilen selbst.\n\nVielen Dank, Freund!", rewards = "Sattelgurt aus MammutsehneGaloschen aus MammutbalgWollgugelDickhäuterschutzgerät von K3Fesseln aus polierten HauernIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12829] = {title = "Einrücken", objective = "Tore Rumpelschlüssel vor der Kristallnetzhöhle möchte, dass Ihr 12 Kristallnetzspinnen tötet.", description = "He, Ihr! Heiß' Tore. Ich leite den Mineneinsatz hier auf dem K3... oder ich werde es in Kürze tun!\n\nDiese Höhle hier ist voller gruseliger Krabbelviecher. Ich glaube, wir könnten ein paar weniger Spinnen gebrauchen, bevor wir hineingehen - was meint Ihr?", progress = nil, completion = "Haha! Schön, dass Ihr nix gegen schmutzige Arbeit habt.\n\nBin echt dankbar, Kumpel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12830] = {title = "Rückgewinnung des Erzes", objective = "Tore Rumpelschlüssel vor der Kristallnetzhöhle hätte gerne, dass Ihr 5 Proben unreines Saroniterz sammelt.", description = "Wir gehen hinein!\n\nAls wir ankamen, waren hier ein paar Schneebolde... Ihre Ausgrabungen scheinen jedoch kein glückliches Ende genommen zu haben. Nicht weiter wichtig - wir hätten sowieso bald übernommen.\n\nIch habe einige unserer Bergmänner hineingeschickt, um ein paar Erzproben zu sammeln, die ich zur Kalibrierung unserer Maschinen benutzen möchte, aber sie sind noch nicht zurückgekehrt.\n\nMacht es Euch was aus, da mal hineinzugehen und Eurerseits ein paar Proben für mich zu sammeln? Die Schneebolde besitzen vermutlich ein paar, obwohl ich glaube, dass die meisten von ihnen inzwischen tot sind.", progress = "Habt Ihr'n bisschen Erz für mich?", completion = "Huh, das ist vielleicht ein Gestank! Ihr hattet'n kleines Handgemenge mit diesen Schneebolden, oder?\n\nFinde ich aber gut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12831] = {title = "Nur teilweise vergessen", objective = "Ein verletzter Goblinminenarbeiter in der Kristallnetzhöhle möchte, dass Ihr ihm einen Eisspitzengiftbeutel von einer Eisspitzenspinne bringt.", description = "Urgh... es fühlt sich an, als hätte ich einen Propeller im Magen.\n\nIch glaube, ich kann gehen, aber seitdem ich im hinteren Teil der Höhle von etwas gebissen wurde, hat sich was ziemlich Bösartiges in meinem Körper ausgebreitet. Die Spinne war größer als die anderen... und sie war auffällig gefärbt.\n\nRicket kann mir vermutlich ein Gegengift brauen, doch sie braucht den Giftbeutel von der, die mich da gebissen hat. Würde es Euch etwas ausmachen, sie für mich zu finden? Ich glaube nicht, dass Tore kommt.\n\nIch stelle mich hier einfach tot und hoffe, dass sie mich in Ruhe lassen.", progress = "<Der verletzte Goblinminenarbeiter krümmt sich vor Schmerzen.>", completion = "Das sollte reichen... Ich hoffe, Ricket kann mir etwas zusammenmischen. Also, bereit zum Aufbruch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12832] = {title = "Bittere Trennung", objective = "Begleitet den verletzten Goblinminenarbeiter aus der Kristallnetzhöhle und meldet Euch danach bei Ricket in K3.", description = "He da - danke Euch! Ich dachte schon, dass ich Futter für die Spinnen werden würde. Aber man sollte sich nicht zu früh freuen - lasst uns hier verdammt nochmal verschwinden!\n\nSagt mir Bescheid, sobald Ihr bereit seid... Beeilt Euch.", progress = nil, completion = "Danke, dass Ihr unserem Minenarbeiter dort geholfen habt, &lt;Name&gt;! Ein Gegengift zu mischen dürfte kein großes Problem darstellen.\n\nWenn Ihr Tore wieder trefft, richtet ihr doch bitte aus, dass sie verrückt ist.", rewards = "Daschals gezackte KlingeSchneeblindschlächterVerzerrtes SpiegelbildGarms SchutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12833] = {title = "Überbestand", objective = "Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor den Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger.", description = "Ah, hallo! Ihr seid nicht wie alle anderen Abenteurer davongelaufen? Ihr seid einfach ein Schatz, wie? Ich habe mich schon gefragt, ob ich komisch rieche!\n\nWir könnten hier immer noch etwas Hilfe gebrauchen und Ihr seid genau <der/die> Richtige dafür. Könnt Ihr Euch an diese Magnatauren erinnern? Nun ja, anscheinend ist die Höhle nicht ganz eingestürzt... es sind also noch immer ziemlich viele übrig. So viel zu \"Gino hat sich um sie gekümmert\", wie?\n\nZum Glück hat Jeer mehr als genug Minen hergestellt. Ihr habt verstanden!", progress = nil, completion = "Ich mag Euch. Genau genommen seid Ihr super!\n\nEin Hoch auf &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12834] = {title = "Weder Regen noch Schnee noch explodierender Flieger", objective = "[PLACEHOLDER] Test cold-weather bomber on giant.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12835] = {title = "Voll ausgewachsen", objective = "[PLACEHOLDER] Test Grown Up Jormungar on Giant", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12836] = {title = "Zeichen der Dankbarkeit", objective = "Ricket am K3 möchte, dass Ihr Knarzfell tötet.", description = "Ich hätte genau die richtige Arbeit für einen eifrigen Neuling! Wir haben ein Gnollproblem. Man könnte es sogar Gnollplage nennen! Wirklich lästige Kreaturen. Es kommen immer mehr von ihnen angekrochen. Mittlerweile sind sie schon hier und klauen unsere Teile! Unfassbar!\n\nAnfang und Ende dieses Problems ist ihr dreister Anführer, Knarzfell. Ich will, dass Ihr Euch um das \"Ende\" kümmert. Stattet ihm in seinem Lager in den Blendschneehügeln weit draußen im Westen einen Besuch ab.\n\nUnd wenn ich sage \"Besuch abstatten\", meine ich damit \"ihn grausam töten\". Alles klar? Alles klar!", progress = "Ich mag Ricket, weil sie soooo lecker ist!\n\nOh, willkommen zurück! Wie sieht es mit der Schädlingsbekämpfung aus?", completion = "Echt stark! Ihr seid genau mein &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12837] = {title = "Tore hat die Waren", objective = "[PLACEHOLDER] Meldet Euch bei Tore", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12838] = {title = "Informationsbeschaffung", objective = "Aurochs Grimmbann auf der Todesanhöhe möchte, dass Ihr 5 Geheimdokumente des Ansturms beschafft.", description = "Ich muss wissen, was der Scharlachrote Ansturm heute plant. Ihr werdet mir in dieser Sache helfen.\n\nFliegt zum Hafen des Ansturms, durchwühlt die Truhen dort und sucht nach Dokumenten. Sie werden verschlossen sein, tut also alles, was nötig ist, um an die Schlüssel der Anhänger des Scharlachroten Ansturms heranzukommen.", progress = "Habt Ihr die Informationen?", completion = "Gebt sie mir. Ich werde sie durchgehen und nur das Wichtigste heraussuchen. Wenn ich etwas gefunden habe, werde ich mich bei Euch melden.\n\nKommt so oder so morgen wieder. Es ist allgemein bekannt, dass sie jeden Tag ihre Pläne ändern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12839] = {title = "Der große Plan (des Admirals)", objective = "Bringt dem Lordkommandanten Arete auf der Todesanhöhe die Nachricht vom Großadmiral.", description = "Auf den ersten Blick gleicht diese Notiz jeder anderen Botschaft, nach der Ihr gesucht habt; doch nachdem Ihr ihren Inhalt kurz überflogen habt, seid Ihr vom Gegenteil überzeugt.\n\nDer Brief besagt, dass sich Großadmiral Westwind irgendwo auf der Insel aufhält, sich momentan aber zurückgezogen hat. Er schreibt von einem glorreichen Tag, der bald anbrechen wird und an dem der Scharlachrote Ansturm zuerst über den Lichkönig und danach über den Rest der Welt kommen wird, um endlich wieder Ordnung nach Azeroth zu bringen.\n\nDer Lordkommandant wird das sofort sehen wollen!", progress = "Der Bericht des Scharlachroten Ansturms muss zu Aurochs Grimmbann gebracht werden.\n\n<Der Lordkommandant sieht Euch erwartungsvoll an - damit seid Ihr entlassen.>", completion = "Eine Nachricht von Westwind? Warum sagt Ihr das nicht gleich?\n\n&lt;Arete reißt Euch den Brief aus der Hand, um ihn zu lesen.&gt;\n\nDieser Narr! Er ist wirklich hier?!\n\n&lt;Der Lordkommandant lacht.&gt;\n\nDas sind neue Nachrichten. Ich frage mich nur: Wie gedenkt er, die Welt zu erobern, nachdem er den Lichkönig gestürzt hat? Was nicht heißt, dass er etwas davon auch nur in seinen wildesten Träumen erreichen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12840] = {title = "Streng vertraulich", objective = "Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr Informationen aus den Kapitänen Welsington und Hartford herausprügelt.", description = "Wenn jemand weiß, wo sich der Admiral aufhält, dann sicherlich seine Kapitäne auf den Schiffen im Hafen des Ansturms.\n\n<Der Lordkommandant reibt sich die Hände.>\n\nWenn ich mich recht entsinne, lauten ihre Namen Welsington und Hartford. Prügelt die Information aus ihnen heraus und macht danach ihrem kümmerlichen Leben ein Ende.\n\nIch will wissen, wo sich der Großadmiral versteckt!", progress = nil, completion = "Sie haben Landgren wieder erweckt? Dann ist er es, der den Aufenthaltsort des Großadmirals kennt!", rewards = "Aretes BefehlFlammender Schlagring des VerhörmeistersKrummdolch des AssassinenEinschüchterung des BrummbärenVerhörstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12841] = {title = "Der Handel der Alten", objective = "Lok'lira die Greisin in der Verlassenen Mine möchte, dass Ihr Yrkvinns Runen von Aufseherin Syra holt.", description = "Ja, es muss der kleine grüne Gefangene sein, den Ihr meint... Eventuell können wir uns gegenseitig helfen.\n\nMit Gewalt kriegt Ihr den Goblin hier nicht raus, zumindest nicht lebendig.\n\nBei meinen Leuten bin ich als Yrkvinn die Illusionistin bekannt. Wie Ihr sehen könnt, haben mich die Hyldnir gefangen genommen.\n\nHätte ich meine Runen, dann könnte ich dafür sorgen, dass Ihr Euch hier ungesehen bewegen könnt. Tiefer im Berg findet Ihr eine Aufseherin namens Syra, die in den Minen patrouilliert. Sie hat meine Runen. Nehmt sie ihr ab, dann reden wir weiter.", progress = "Meine Runen, <Name>? Habt Ihr sie?", completion = "Ich war mir nicht sicher, ob Ihr zurückkommen würdet. Der Gedanke daran, was aus mir werden würde, wenn ich zu lange hier bliebe, machte mir schon Angst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12842] = {title = "Runen schmieden: Vorbereitung auf den Kampf", objective = "Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, mithilfe Eurer Fertigkeit 'Runen schmieden' eine beliebige Rune in Eure runenbeschriebene Seelenklinge zu prägen.\n\nIhr könnt die Prägung auf Eurer Waffe jederzeit durch eine andere ersetzen, solange Ihr Euch in der Nähe einer Runenschmiede befindet.", description = "Das Zeichen des Krieges ist für immer in Eure Seele gebrannt, Todesritter. Ihr habt die dunkle Kunst des Runenschmiedens erlernt und könnt nun Runen der Macht in Eure Waffen prägen.\n\nBereitet Euch auf den Kampf vor. Kehrt zu einer der Runenschmieden hier im Herzen von Acherus zurück und bedient Euch der neugewonnenen Kunst, um Eure Waffe mit einer Rune der Macht zu versehen!\n\nKehrt zu mir zurück, sobald Eure Klinge vor dunkler Energie leuchtet!", progress = "Verschwendet nicht meine Zeit, <Name>. Wir stehen am Rande einer Apokalypse!", completion = "Merkt Euch diese Worte, &lt;Klasse&gt;: Die Runenschmiede ist ein Instrument der Geißel. Es gibt sie nur in Acherus, Naxxramas und im Herzen der Eiskrone! Ihr könnt Eure Waffen nur an einer Runenschmiede mit Prägungen versehen.\n\nKehrt noch oft zurück, um all Eure Waffen mit Runen zu versehen. Ein &lt;Klasse&gt; muss auf alles vorbereitet sein, das sich ihm in den Weg zu stellen wagt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12843] = {title = "Sie haben unsere Männer!", objective = "Gretchen Zischelfunken möchte, dass Ihr nach Sifreldar geht und 5 Goblingefangene befreit.", description = "Ihr müsst uns helfen! Wir führten gerade eine Expedition in die Berge durch, um einen Übertragungsturm aufzustellen, als wir angegriffen wurden.\n\nSie sahen aus wie Vrykul, nur dass ihre Haut blau und eisbedeckt war... und es waren nur Frauen! Sie nahmen alle Männer der Expedition mit und ließen uns Frauen gehen. Bitte, <Name>! Wir vermuten, dass sie in Sifreldar, dem Dorf oberhalb von K3, festgehalten werden.", progress = nil, completion = "Ihr habt es geschafft! Unsere Männer sind zurück!", rewards = "Pelzbesetzte SchulterwärmerPelzbesetzte FäustlingeBrustschutz des eisigen AufstiegsGipfelarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nRing der eisigen Stimmung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12844] = {title = "Ausrüstungsbergung", objective = "Gretchen Zischelfunken möchte, dass Ihr 8 Teile der K3-Ausrüstung aus Sifreldar holt, das nördlich des K3 liegt.", description = "Bitte, <Name>. Als die Hyldnir unsere Männer entführten, nahmen sie auch unsere gesamte Ausrüstung mit. Es ist natürlich viel wichtiger, dass wir unsere Männer wiederbekommen, aber wenn Ihr auf Ausrüstungsgegenstände stoßen solltet, wäre ich Euch sehr dankbar, wenn Ihr sie uns zurückbringen könntet.\n\nIhr findet ihr Dorf direkt über uns im Norden.", progress = "Was macht unsere Ausrüstung, <Name>?", completion = "Danke, &lt;Name&gt;! Mal sehen, was wir mit diesen Teilen noch anfangen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12846] = {title = "Lasst keinen Goblin zurück", objective = "Findet den Eingang zu den Verlassenen Minen im Norden von Sifreldar und sucht nach Hinweisen auf Zeev Zischelfunkens Aufenthaltsort.", description = "Alle unsere Männer sind zurück... dank Euch, <Name>! Nun... alle bis auf einen.\n\nMein Bruder Zeev ist laut den anderen immer noch da oben. Offenbar gibt es dort eine Art Mine, in der die Gefangenen arbeiten müssen. Geht dorthin und seht nach, ob Ihr etwas herausfinden könnt.", progress = nil, completion = "Ihr gehört definitiv nicht zu den Hyldnir... warum seid Ihr also hier? Ah... Ihr sucht bestimmt nach dem neuen Gefangenen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12847] = {title = "Zweite Chancen", objective = "Tötet Erzbischof Landgren und beschwört anschließend Aretes Tor in Gegenwart seiner Leiche. Sprecht mit Lordkommandant Arete im Hafen des Ansturms, sobald er sein Verhör mit dem Geist des Erzbischofs beendet hat.", description = "Ich hörte, sie hätten einen Erzbischof in ihrer Kathedrale, aber ich hatte ja keine Ahnung, dass sie Landgren wiedererweckt und befördert haben! Die Kathedrale wird schwer bewacht und hat nur einen Eingang, also werdet Ihr Hilfe brauchen.\n\nWir müssen immer noch erfahren, wo sich der Großadmiral aufhält, doch dieses Mal gehen wir kein Risiko ein!\n\nNehmt dieses Gerät. Damit seid Ihr in der Lage, für mich ein Portal zu beschwören, sobald Ihr den Erzbischof getötet habt.\n\nIch hole mir meine Antworten direkt von seiner unterworfenen Seele! Wir werden Großadmiral Westwind finden!", progress = "Ja?", completion = "Verborgene Höhlen auf der Rückseite der Insel. Wie überaus interessant.\n\nNun, wenigstens weiß ich jetzt, wo sich alle meine vermissten Spione befinden.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12848] = {title = "Der endlose Hunger", objective = "Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, einen unwürdigen Initianden zu befreien und ihn kaltblütig umzubringen!\n\nEntweder ist es Euer oder ihr Leben!", description = "Schon bald, <Klasse>, wird sich der unaufhörliche Hunger Eurer bemächtigen - und wenn dies geschieht, werdet Ihr gewaltige Schmerzen erleiden. Es gibt nur ein Heilmittel gegen das Leid: Der Hunger muss gestillt werden.\n\nIch gebe Euch den Schlüssel, der Eure Erlösung sein wird.\n\nDiejenigen, die der dunklen Bruderschaft unwürdig sind, werden ans Herz von Acherus gekettet. Befreit mithilfe des Schlüssels einen unwürdigen Initianden. Erlaubt ihm, seine Ausrüstung zu tragen und mit Euch um seine Freiheit zu kämpfen. Tötet: und der Schmerz wird aufhören. Versagt: und Ihr werdet für alle Ewigkeit leiden müssen.\n\nLebt oder sterbt - die Wahl liegt bei Euch.", progress = "Zwei Leben, ein Schlüssel... Enttäuscht mich nicht, <Name>.", completion = "Wie erwartet: Mein auserwählter Ritter hat den Sieg davongetragen! Ihr seid nun bereit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12849] = {title = "Die Macht des Blutes, des Frosts und der unheiligen Kraft", objective = "In den Hallen des Befehls findet Ihr die Schulen des Bluts, des Frosts und der unheiligen Kraft. Jede dieser Schulen hat einen Lehrer, der Euch mit Wissen der verschiedenen dunklen Künste versorgen kann.\n\nIch, Lord Thorval, bin der Direktor der Schule des Blutes. Lady Alistra herrscht über die Schule der unheiligen Kraft und der Erzlich Amal'thazad über die des Frosts.\n\nIhr müsst jedes Mal wieder hierherkommen, wenn Ihr mehr Macht erlangt habt, und trainieren!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12850] = {title = "Meldet Euch bei Geißelkommandant Thalanor", objective = "Meldet Euch beim Geißelkommandanten Thalanor auf dem Balkon auf der ersten Ebene der Schwarzen Festung.", description = "Geißelkommandant Thalanor erwartet Eure Ankunft. Ihr findet ihn auf dem Überhang direkt südöstlich unserer derzeitigen Position. Meldet Euch bei ihm und verlangt nach einem Geißelgreifen, der Euch dann zur Todesbresche bringen wird.\n\nPrinz Valanar wird unten auf Euch warten.\n\nLeidet wohl, <Bruder/Schwester>!", progress = nil, completion = "Der Krieg hat begonnen, &lt;Klasse&gt;! Ich werde Euch meinen besten Greifen zur Verfügung stellen - er wird Euch zur Todesbresche bringen. Chaos, Tod und Zerstörung! Dies alles werdet Ihr einläuten - und noch vieles mehr!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12851] = {title = "Eiskalte Jagd", objective = "Brijana in Brunnhildar möchte, dass Ihr Eiszahn benutzt und 7 Frostworge und 15 Frostriesen im Uralten Wintertal tötet.", description = "Die Prüfung wartet, Frau!\n\nBesitzt Ihr das Herz einer Kriegerkönigin? Oder das einer jammernden Näherin?\n\nHabt Ihr einmal Krieg geschmeckt, werdet Ihr die Antwort wissen.\n\nIhr könnt Eure Mutter anlügen, Eure Schwestern und sogar Euch selbst, doch das Schlachtfeld fördert immer die wahre Natur zutage.\n\nWenn Ihr Eure Vorbereitungen abgeschlossen habt, setzt Euch auf Eiszahn und reitet in die Schlacht. Von seinem Rücken aus müsst Ihr den Regen des Todes auf unseren Feind darniederprasseln lassen!", progress = "Habt Ihr die Schlacht überlebt, <Name>?", completion = "Vielleicht besitzt Ihr wirklich das Herz einer Kriegerin.\n\nDie Zeit wird es zeigen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12852] = {title = "Den Admiral aufgespürt", objective = "Lordkommandant Arete möchte, dass Ihr Euch um Großadmiral Westwind kümmert. Kehrt danach zum Lordkommandanten auf die Todesanhöhe zurück.", description = "Als Hochgeneral Abbendis in Neuherdweiler konfrontiert wurde, schützte sich der Großadmiral selbst vor seiner Flucht mit einer undurchdringlichen Magiesphäre.\n\nIch bin besonders erfahren im Zunichtemachen von Magie.\n\nNehmt dies, um es gegen ihn in der Versteckten Senke einzusetzen, wenn er seine Sphäre erneut herbeiruft. Ich wünschte, ich könnte dabei sein, um seinen Gesichtsausdruck zu sehen.\n\nErledigt ihn.", progress = nil, completion = "MAL'GANIS?!\n\n&lt;Der Lordkommandant lacht hemmungslos.&gt;\n\nDie Narren wurden schon wieder von Dämonen überwältigt und jetzt sind sie vernichtet!\n\nIch vertraue darauf, dass mein liebster &lt;Klasse&gt; lange genug bei uns bleibt, um dabei zu helfen, den Rest von ihnen auszuschalten? Vielleicht kann Euch etwas hiervon überzeugen?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett des KreuzzugsWestwinds abtrünnige SchlingeEmelines MedaillonVerstärkter Titannackenschutz\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12853] = {title = "Luxusreise!", objective = "Sprecht mit Jeer Funksockel am K3 in den Sturmgipfeln.", description = "Hallo, <Kumpel/Süße>!\n\nMögt Ihr Spannung und Explosionen?! Wer mag das nicht? Ich kenne genau den richtigen Ort für Euch. Unten bei K3, dem Luxusziel schlechthin, erfinden sie immer neue innovative Sachen und Wege, wie man andere Sachen in die Luft jagen kann! Klingt spannend, was? Falls Ihr bei dem Spaß mitmachen wollt, dann macht Euch noch heute auf den Weg dorthin und sprecht mit Jeer Funksockel!\n\nObligatorische Ausschlussklausel: Zur Teilnahme an oben angedeuteter \"Spannung\" kann unter Umständen körperliche Arbeit vonnöten sein.", progress = nil, completion = "Willkommen in K3!\n\nWir sind hier, um zu diesen Gipfeln vorzudringen und einen guten Anteil dieser erstaunlichen Titanenmaschinen in die Finger zu bekommen. Jedoch haben wir in dieser Hinsicht relativ wenig Fortschritte gemacht. Gnolle, Schneebolde, Magnatauren... es ist genug für jedermann da... geschweige denn, dass wir irgendeinen unserer Flieger in der Luft halten können, ohne dass ihre Motoren gleich einfrieren.\n\nJedoch gibt es genug Arbeit zu tun - Ihr helft mit, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12854] = {title = "Auf Branns Spuren", objective = "Beschafft die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Archäologe Andorin in der Eisfestung.", description = "Nach der Entdeckung von Branns Tagebuch in den Grizzlyhügeln fanden wir nur noch eine einzige Nachricht von Brann. Eine mysteriöse Notiz tauchte im Hauptquartier der Forscherliga auf, ohne Hinweis auf ihren Ursprung. Sie besagte nur, dass wir Brann in seinem Lager treffen und ihm bei seiner Suche helfen sollten.\n\nMeiner Meinung nach müsste sich das Lager nordöstlich von hier befinden, jenseits von Bors Atemstrom und am Fuße einiger Ruinen vom Pfad der Titanen.", progress = "Habt Ihr Branns Lager gefunden?", completion = "&lt;Archäologe Andorin blickt Euch erwartungsvoll an.&gt;\n\nIhr solltet eigentlich mit Brann zurückkehren, nicht mit einem Stück Papier. Was ist hier los?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12855] = {title = "Den Täter ausschnüffeln", objective = "Nutzt das Frosthundhalsband im Verlassenen Lager um herauszufinden, wer Branns Habseligkeiten an sich genommen hat. Wenn Ihr sie finden konntet, setzt das Kommunikationsgerät ein und sprecht mit wem auch immer Ihr Kontakt bekommt.", description = "Der Tonfall von Branns Notiz lässt vermuten, dass er etwas mit der Notiz vergraben wollte, möglicherweise eine Art Bündel. Seid Ihr sicher, dass Ihr nicht mehr gefunden habt?\n\nGut, dann müsst Ihr einen der Frosthunde mitnehmen, die die Frosterben zum Fährtenlesen nutzen. Bringt ihn zum zerstörten Lager und lasst ihn Branns Spur aufnehmen.\n\nEr sollte Euch zumindest dorthin führen, wo Ihr seine verschwundenen Habseligkeiten finden könnt, und mit etwas Glück sogar zu Brann selbst.", progress = "Wer seid Ihr?", completion = "Ihr... Ihr seid kein Mitglied der Forscherliga, so weit ich weiß. Aber Ihr habt den Kommunikator gefunden, daher müssen sie Euch geschickt haben. Gut, das ist fast das, was ich erhofft hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12856] = {title = "Kaltherzig", objective = "Befreit 3 gefangene Protodrachen und 9 gefangene Brunnhildar.", description = "Einen ehrenhaften Tod auf dem Schlachtfeld zu finden, bringt uns allen Ruhm; in einem Eisblock eingefroren zu sein und auf ewig verspottet zu werden, tut dies nicht...\n\nIhr sollt zur Stadt der Frostriesen Dun Niffelem fliegen, die gleich östlich des Uralten Wintertals liegt, und unsere gefangenen Protodrachen befreien. Mit ihrer Hilfe werdet Ihr dann die gefrorenen Fesseln unserer Schwestern lösen und sie sicher nach Hause bringen können.\n\nNehmt Euch jedoch vor den Keulen der Riesen in Acht, Schwester, wenn Ihr nicht zu den Gefangenen zählen wollt.", progress = "War Eure Mission erfolgreich, Schwester?", completion = "Eure Mühen scheinen sich gelohnt zu haben, Schwester.\n\nIhr habt den Brunnhildar zu Ruhm verholfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12857] = {title = "Gesucht: Rachmähnes Flosse", objective = "Beschafft Rachmähnes Flosse und bringt sie zu Häuptling Zornklaue in der Lichtbresche in Zul'Drak.", description = "Von Häuptling Zornklaue:\n\nGetreuer Seelöwe von Häuptling Zornklaue Rachmähne hat Hand gebissen, die es füttern wollte. Zornklaue sagt, dass Rachmähne zu nichts nutzt wegen Drakurutrolle. Häuptling Zornklaue sehr traurig sein, dass er bitten muss, dass Rachmähne getötet wird und seine Flosse als Beweis zurückgebracht wird.\n\nIhr finden Rachmähne im Südosten bei Zornklauensee.\n\nHäuptling Zornklaue leid tun, wegen schlechtem Geschreibe. Das erste Mal, dass ich eines dieser Dinger benutze und Häuptling Zornklaue ist Wolvar, nicht Menschenwesen.", progress = "Armer Rachmähne. Er war Geschenk von Schwager.", completion = "&lt;Häuptling Zornklaue weint.&gt;\n\nHatte Rachmähne schon, seit er ein kleiner Heuler. Trauriger Tag für Zornklaue. Zuerst Troll hat Zornklaue angegriffen, dann er machen Rachmähne schlecht. Zornklaue nie mehr mit Troll handeln, nie mehr!", rewards = "Stab des sorgenvollen HäuptlingsHammer der stillen TrauerSichel des brütenden ZornsSchwert des herzzerreißenden GemetzelsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12858] = {title = "Puzzleteile", objective = "Sucht 6 Fragmente der Scheibe des Erfinders und setzt sie damit wieder zusammen.", description = "Dem Licht sei Dank, dass jemand meine Nachricht erhalten hat. Nun, da ich vor den Eisenzwergen sicher bin, muss ich Euch erneut um Eure Hilfe bitten. Ich habe einen Hinweis auf Norgannons Schlüsselstein, der den Zugang zu Ulduars Archiven bewacht, jedoch von den Titanen in zwei Stücke geteilt und versteckt wurde.\n\nEines der Stücke, die Hülle des Schlüsselsteins, wird in der Bibliothek des Erfinders an der Nordküste südlich von Ulduar aufbewahrt. Als Erstes müsst Ihr jedoch die Fragmente einer alten Zugangsscheibe von den Wächtern der Bibliothek beschaffen.", progress = "Konntet Ihr die Scheibe zusammensetzen?", completion = "Wunderbar! Da wir die Scheibe jetzt haben, müsst Ihr damit das Gewölbe des Erfinders öffnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12859] = {title = "Das Allerneueste: Feuer noch immer heiß!", objective = "Schamanenältester Moky in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe des Feuerlöschers der Zornklauen 15 Hüttenfeuer im Zornklauenbau löscht.", description = "Trolle greifen Zornklauenbau an und schmeißen Zornklaue raus! Doch es kommt noch schlimmer: Trolle brennen jetzt Dorf! Das sehr schlecht. Häuptling hat Schamanen der Zornklauen namens Moky befohlen, Feuer zu untersuchen. Ergebnisse sehr überraschend! Feuer noch immer heiß und kann Sachen anzünden.\n\nWerdet Ihr den Zornklauen helfen und das Feuer ausmachen? Moky hat speziellen Feuerlöscher der Zornklauen für Euch. Benutzt speziellen Feuerlöscher, um Feuer im Zornklauenbau gen Südosten zu löschen. Muss manchmal oft sprühen, damit Feuer ausgeht, doch Löscher immer Wasser haben! Zornklauenmagie sehr stark!", progress = nil, completion = "Es ist seltsam, weil ich weiß, dass Ihr Feuer ausgemacht, doch Feuer brennen noch immer. Vielleicht dieses Ding doch nicht so gut, was? Doch Moky Euch für Eure Arbeit bezahlen! Hoffentlich Trolle brennen auch!", rewards = "Ihr bekommt:\n\nDer FeuerlöscherAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12860] = {title = "Daten schürfen", objective = "Nutzt die Scheibe des Erfinders, um 7 Teile der versteckten Daten aus den Datenbanken zu beschaffen.", description = "Diese Scheibe, die Ihr zusammengebaut habt... sie ist leer! Dieser gerissene Mimir muss die Informationen irgendwo anders versteckt haben. Seht Euch in der Bibliothek des Erfinders um, sind dort irgendwelche Datenbanken?\n\nVielleicht ist es das, was Ihr mit der Scheibe machen müsst. Versucht, sie in der Nähe einer dieser Datenbanken einzusetzen. Vielleicht kann man darauf die Informationen speichern. Meldet Euch erneut bei mir, wenn Ihr das ausprobiert habt, und lasst mich wissen, was Ihr herausfinden konntet. In der Zwischenzeit werde ich versuchen, die andere Hälfte des Archivschlüssels zu finden.", progress = "Habt Ihr die Scheibe ausprobiert? Was habt Ihr gefunden?", completion = "&lt;Brann sieht die Scheibe in Eurer Hand an.&gt;\n\nIch weiß nicht, ob darauf etwas gespeichert ist oder nicht! Ihr müsst mir sagen, was passiert ist.\n\n&lt;Ihr beschreibt den Datenwiederherstellungsprozess.&gt;\n\nEs hat also funktioniert? Zumindest kann man sich darauf verlassen, dass Mimir systematisch vorgeht. Nach allem, was ich gehört habe, könnte ich das über die anderen Bewahrer jedoch nicht behaupten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12861] = {title = "Die Trolle sind durchgedreht!", objective = "Häuptling Zornklaue in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe der \"Schlossöffner\" von Drakuru, welche die verschiedenen Drakurutrolle bei sich tragen, 8 gefangene Zornklauen befreit.", description = "Drakuru... Ihr wisst, wer dieser Troll ist? Ich denke, dass böse Trolle von Troll namens Drakuru kontrolliert werden. Sie nennen sich Drakurutrolle - deswegen weiß ich das. Nun Ihr sehen, wieso ich Häuptling der Zornklauen. Klügster aller Wolvar!\n\nDoch das nicht der Grund, weshalb ich mit Euch jetzt sprechen. Böse Trolle gekommen und Zornklauen aus Bau geschmissen. Doch Zornklauen, die nicht weglaufen, werden jetzt als Gefangene in Dorf gehalten. Ihr gehen zu Zornklauenbau im Südosten und befreit gefangene Zornklauen. Tötet Trolle für Schlossöffner. Ihr vielleicht töten viele Trolle für viele Schlossöffner.", progress = nil, completion = "Zornklaue Euch danken, &lt;Name&gt;. Doch Zornklauenbau wahrscheinlich für immer verloren und Freundschaft mit Trolle auch für immer verloren... und wenn ich denken, mir einfallen, dass Rachmähne auch für immer verloren. Auch Schwager weg. Hrm, Ihr haben Häuptlings Frau gesehen? Ich glaube, sie auch weg.\n\nVielleicht Ihr jetzt gehen. Häuptling ein wenig deprimiert.", rewards = "Roben des BefreiersHandgelenksschützer der heilenden FingerTreter des freien HorizontsGamaschen des klugen HäuptlingsIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12862] = {title = "Wenn alles andere versagt", objective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", progress = nil, completion = "Au! Das sah schmerzhaft aus. Aber es war ein ziemlich beeindruckender Auftritt, Bursche!\n\nWillkommen in der Eisfestung! Seid Ihr hier, um uns zu helfen, einen Weg nach Eiskrone zu finden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12863] = {title = "Danksagung", objective = "Bringt Glorthal Steifbart in der Eisfestung die Kiste mit Heilvorräten.", description = "Ah! Danke, dass Ihr gekommen seid, <Kamerad/Fräulein>.\n\nAngesichts Eurer großen Augen und zitternden Hände würde ich vermuten, dass Ihr noch nicht lange hier seid. Da wäre es wohl angebracht, dass Ihr unsere freundlichen Gastgeber kennenlernt!\n\nWir haben einige zusätzliche Heilvorräte... ehrlich gesagt, hatten wir nicht erwartet, derart bequem unterzukommen. Geht voraus, gebt Glorthal dort drüben diese Kiste und helft ihm, wenn's geht. Wir wollen ja nicht, dass sie uns für undankbar halten, wo sie uns doch mit derart offenen Armen empfangen haben.", progress = "Hallo.", completion = "Heilvorräte? Vielen Dank! Ich weiß zwar ehrlich gesagt nicht genau, was ich damit anfangen soll, aber sie werden uns gewiss nützlich sein.\n\nEs freut mich, Euch kennenzulernen... Euer Volk ist wirklich sehr unterschiedlich. Wir bekommen hier oben nicht sehr oft Besuch - und es ist schön, mal ein paar neue Gesichter zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12864] = {title = "Vermisste Späher", objective = "Glorthal in der Frostfestung hat darum gebeten, im Tal namens Bors Atem und bei Bors Sturz nach Anzeichen für die vermissten Späher der Frosterben zu suchen.", description = "Da Ihr schon mal hier seid: Es gibt da etwas, bei dem ich Eure Hilfe gebrauchen könnte.\n\nEinige unserer Späher sind schon seit geraumer Zeit nicht mehr zurückgekehrt. Die Gipfel sind eine unwirtliche Gegend... doch die Jungs wissen, was sie tun.\n\nGeht nach Osten... sie sollten sich entlang des Tals namens Bors Atem und in der Nähe von Bors Sturz befinden... in dieser Richtung jedenfalls. Solltet Ihr irgendeinen von ihnen finden, dann muss ich sofort davon erfahren. Wir haben einige Feinde in der Gegend - falls irgendwer von denen ein wenig dreist werden sollte. Besser zu viel vorgewarnt als zu wenig.", progress = nil, completion = "Wenn ein Späher so lange nicht zurückkommt... dann ist so etwas zu erwarten. Waren es die Harpyien?\n\nKönig Sturmherz lässt uns das ganze Jahr hart trainieren... er hat uns zu sehr guten Kämpfern gemacht. In Zeiten wie diesen verstehe ich, weshalb dies nötig ist. Er ist der weiseste und stärkste Anführer, den ich bis jetzt unter meinesgleichen gesehen habe... lasst Euch von seiner samtweichen Haut nicht täuschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12865] = {title = "Treue Gefährten", objective = "Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 8 Stück frisches Rhinozerosfleisch beschafft und es an die Sturmspitzenadler auf den Gipfeln über der Stadt verfüttert.", description = "Frischfleisch! Schön, Euch kennenzulernen! Ich hätte da etwas Arbeit für Euch, falls Ihr Zeit haben solltet.\n\nIm Osten liegen die Fußmarschen... eine ziemlich unwirtliche Gegend, doch es gibt dort ziemlich viele grasende Rhinozerosse. Unsere Vögel haben Geschmack an ihrem Fleisch gefunden, doch auf die Jagd zu gehen, ist bei all den in der Gegend nistenden Protodrachen immer etwas gefährlich für sie.\n\nFalls Ihr Lust habt, dann geht dorthin und besorgt ein wenig Rhinozerosfleisch, bringt es zurück zu den Gipfeln über uns und verfüttert es an die Adler, die dort nisten.", progress = nil, completion = "Schönen Dank... und ich bin mir sicher, dass die Adler auch ziemlich dankbar sind. Sie sind mächtige Verbündete und solange sie Euch wohlgesonnen sind, wird es Euch gut ergehen.", rewards = "Stiefel der heulenden WindeGehärteter PeitschengürtelKaputter KeuschheitsgürtelKieferbrecherIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12866] = {title = "Den Aggressoren Einhalt gebieten", objective = "Glorthal Steifbart in der Eisfestung möchte, dass Ihr 8 Frostfederkreischerinnen und 8 Frostfederhexen tötet.", description = "Verdammte Harpyien. Ich kann mich schon gar nicht mehr daran erinnern, wie oft wir die Viecher schon zu Kleinholz verarbeitet haben... und nach jedem Kampf geben sie für eine Weile Ruhe. Ich hatte gedacht, dass sie es dieses Mal verstanden hätten.\n\nDoch anscheinend nicht.\n\nIhr Gedächtnis mag vielleicht ein wenig kurz sein, doch wenn man genug von ihnen totschlägt, lassen sie einen in Ruhe. Würdet Ihr hinunter in die Täler gen Norden und Osten gehen und einen Großteil von ihnen beseitigen?", progress = nil, completion = "Es ist Drecksarbeit, ich weiß, doch wir sind Euch dafür dankbar. Was war nun noch mal der Name, den der Späher genannt hat... Sirana?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12867] = {title = "Babydiebe", objective = "Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 15 Eier eines Sturmspitzenadlers zurückbringt.", description = "Wenn Ihr noch vor ein paar Wochen nach oben geblickt hättet, hättet Ihr Dutzende dieser wunderschönen Adler durch die Lüfte gleiten sehen. Jetzt sieht man nur noch ein paar, wenn überhaupt. Sie bleiben jetzt fast die ganze Zeit bei ihren Nestern, weil die Harpyien einige ihrer Eier gestohlen haben.\n\nDie Harpyien haben Geschmack am Fleisch der Adler gefunden, wie es scheint... Die kranken Miststücke kümmern sich lange genug um die Eier, bis diese ausschlüpfen, um sich dann an den Jungen gütlich zu tun. Geht zu den Tälern im Norden oder Osten und findet die Eier... Bringt sie hierher und ich werde sie wieder zurück in die Nester legen.", progress = "Wir werden uns um dieses Harpyienproblem kümmern... Die Adler werden schon bald wieder frei durch die Lüfte segeln können.", completion = "Sehr gut, &lt;Name&gt;. Ihr macht Euch schnell Freunde.\n\nWenn Ihr bald wieder vorbeischaut, dann wird sich mit Sicherheit einer finden lassen, der Euch auf ihm reiten lässt... Sie sollten jetzt wissen, dass man Euch vertrauen kann.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12868] = {title = "Sirana Eisschrei", objective = "Glorthal Steifbart in der Eisfestung möchte, dass Ihr Sirana Eisschrei tötet.", description = "Diese Sirana Eisschrei scheint diejenige zu sein, die die Harpyien zu noch mehr Aggressivität anstachelt. Ich vermute, dass sie ihre Angriffe bald einstellen werden, wenn wir ihr den Garaus machen.\n\nEiner unserer Sturmreiter behauptet, sie am Gipfel nordwestlich von hier gesehen zu haben. Findet das Weib und macht ihm ein Ende, ein für alle Mal.", progress = nil, completion = "Es ist also vollbracht. Vielen Dank.\n\nIch habe mit Fjorlin gesprochen - er sagte, dass seine Männer die Harpyien unter Kontrolle halten werden. Solange wir sie im Auge behalten, werden sie nicht so schnell wieder den Mut haben, meine Leute anzugreifen.\n\nMir ist klar, dass das keine sehr angenehme Aufgabe war - nehmt dies als Zeichen meiner Anerkennung.", rewards = "Zauberstab der kühlen ErneuerungBerührung des EiskreischersIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12869] = {title = "Zu weit getrieben", objective = "Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr auf einem Sturmspitzenadler 16 Sturmgipfelwyrms in den Fußmarschen niederstreckt.", description = "Ihr seid mit Loken dort gewesen, nicht wahr? Die Eisenzwerge haben Veranus, die Brutmutter der Protodrachen, gefangen genommen. Die Drachen scheinen nicht im Mindesten froh über die Situation zu sein... sie sind sehr aggressiv geworden.\n\nSie sind ins Sturmspitzengebiet eingedrungen und werden von den Adlern mit allen Mitteln bekämpft. Ihr wisst, auf welcher Seite wir stehen... Sie haben schon immer zu uns gehalten - es ist Zeit, den Gefallen zu erwidern.\n\nKönig Sturmherz hat mir diesen Hammer hinterlassen. Macht von ihm gut Gebrauch und seht zu, dass ich ihn wieder zurückbekomme.", progress = "Die Situation ist völlig außer Kontrolle geraten.", completion = "So wie ich das sehe, sind die Drachen nicht so leicht zu entmutigen. Schaut morgen wieder hier vorbei, falls Ihr Zeit haben solltet, um uns zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12870] = {title = "Uralte Relikte", objective = "Bringt 10 Relikte von Ulduar zu Rork Spitzkinn in die Eisfestung.", description = "Seid gegrüßt!\n\nBevor Ihr Eure große Suche, Euer großes Abenteuer antretet, könnte Ich Euch um einen kleinen Gefallen bitten, <Kamerad/Fräulein>?\n\nIn diesen Bergen gibt es lauter kostbare Relikte und Schmuckstücke... Dieser Ort ist für die Liga wie ein wahrgewordener Traum. Ich wäre Euch sehr dankbar, wenn Ihr Schätze dieser Art zu mir bringen könntet, falls Ihr über welche stolpern solltet. Für die Unannehmlichkeiten könnt Ihr sogar etwas von meinem Bier haben! Glaubt mir, <Kamerad/Fräulein>, das ist ein gutes Geschäft!", progress = "Habt Ihr ein paar dieser Relikte gefunden?", completion = "Wunderschön! Gut gemacht habt Ihr das.\n\nKippen wir uns einen hinter die Birne! Lasst uns diesen glorreichen Fund feiern!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLuftiges SilberbräuWorgzahn HafermehlstarkbierSchneefall LagerDrachenfeuer Chilibier\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12871] = {title = "Hilfe von der Forscherliga", objective = "Bringt Norgannons Schale zu Lagnus in die Eisfestung.", description = "Interessant. Ich kann keine Schließmechanismen auf der Schale erkennen. Das lässt mich darauf schließen, dass man mehr als nur das andere Teil finden muss, um den Schlüsselstein zusammenzufügen.\n\nBringt die Schale zurück zum Expeditionsleiter Lagnus in der Eisfestung. Sobald er dann erst einmal seine Scheu überwunden hat, sollte er anhand der Schale herausfinden können, wie der Kern aussieht. Vielleicht können sie auch die Frostzwerge dazu bringen, bei der Suche zu helfen.\n\nIch werde versuchen herauszufinden, wie sich die zwei Teile zusammenfügen lassen. Wir werden uns wiedersehen, wenn wir beide etwas weiter gekommen sind.", progress = "Hallo!", completion = "Bei Muradins Bart! Ist das hier das, von dem ich denke, dass es das ist?! Brann hat sich diesmal wirklich selbst übertroffen... wie auch Ihr in dem Fall! Die Jungs Zuhause werden das niemals glauben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12872] = {title = "Norgannons Schale", objective = "Beschafft Euch Norgannons Schale von Archivar Mechaton.", description = "Scheibe des Erfinders wird aufgeladen.\n\nProzess abgeschlossen.\n\nNotfallprotokoll Gamma in Bearbeitung.\n\nLadevorgang von Notfallprotokoll abgeschlossen. Bitte zum Aktivieren von Archivar Mechaton, den Wächter von Norgannons Schale, aufgeladene Scheibe verwenden. Scheibe wird von Archivar Mechaton freigegeben, sobald Eure Identität verifiziert wurde.\n\nEuch ein angenehmes Jahrtausend.", progress = "Steht nicht nur so da, zeigt mir die Schale!", completion = "Das ist sie! Das ist die erste Hälfte von Norgannons Schlüsselstein. Gut gemacht, &lt;Name&gt;. Wenn ich wieder in Eisenschmiede bin, werde ich Euch als Ehrenmitglied der Forscherliga vorschlagen!", rewards = "Gehärtete Ranke des RaufersKlinge des AnbeginnsBerührung des SchöpfersSchneide des SchöpfersDolch der MaidIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12873] = {title = "Der König der Frosterben", objective = "Sprecht mit Yorg Sturmherz in der Eisfestung.", description = "Auf jeden Fall... Ich weiß ganz genau, wie der Kern aussieht. Falls ihn irgendeiner der Frosterben gesehen haben sollte, dann wird ihm die Beschreibung mit Sicherheit bekannt vorkommen.\n\nWir haben keine Zeit zu verlieren, lasst uns also gleich zur Sache kommen. Geht zu König Sturmherz und erbittet seine Hilfe... Er wird sicherlich jemanden kennen, der uns helfen kann, den Kern zu finden. Und seid freundlich zu ihm - in dieser Gegend wird er sehr respektiert.", progress = nil, completion = "Norgannons Kern? Noch nie davon gehört. Kann jedoch gut sein, dass ich jemanden kenne, der es hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12874] = {title = "Eifer der Frosterben", objective = "Yorg Sturmherz in der Eisfestung hat Euch gebeten, mit Fjorlin Frostbraue zu sprechen und Euch der Herausforderung zu stellen.", description = "Ich wäre ja durchaus bereit, Reisenden in Not Unterkunft zu bieten, aber ich möchte mich auch nur ungern in Eure Angelegenheiten einmischen.\n\nIch sag Euch was... meine Leute sind ehrliche und aufrichtige Krieger. An dem Tag, an dem ein Frosterbe zum Mann wird, muss er sich im Kampf beweisen. Er muss uns zeigen, dass er sich nicht von Größe einschüchtern lässt.\n\nBeweist mir, dass Ihr genauso stark und wild seid wie meine Männer, dann werde ich dafür sorgen, dass sie Euch ein Ohr schenken oder Euch ihre Klinge zur Verfügung stellen. Sprecht an der Klippe im Süden mit Fjorlin, er wird Euch auf die Probe stellen.", progress = "Ihr seid zurück. Wart Ihr siegreich?", completion = "Ha! Ich bin beeindruckt... vielleicht fließt doch etwas Frosterbenblut durch Eure Adern? Ihr steht jedoch zu Euren Worten, und genau das wollte ich wissen.", rewards = "FrostheulgurtNomadenarmschienenBrustplatte des NordwaldläufersKaltblütige BeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12875] = {title = "Ein erfahrener Führer", objective = "Macht Drom Frostgriff ausfindig.", description = "Ich weiß nicht, wo sich dieser Kern versteckt, das war Euch doch klar? Aber ich habe gesagt, dass ich Euch helfe, und das werde ich auch.\n\nEs gibt da einen Einsiedler namens Drom Frostgriff, der in einer Höhle nördlich von hier lebt... unten im Tal. Wir haben uns ein wenig von den Titanen entfernt, da es nur noch so wenige gibt, aber Drom ist den alten Wegen treu geblieben... Er behält ihre wichtigsten Plätze im Auge und unterhält sich häufig mit dem Bewahrer Creteus.\n\nIhr könnt ihn vermutlich im hinteren Teil seiner Höhle antreffen... sagt ihm, dass ich Euch schicke, dann wird er Euch helfen.", progress = nil, completion = "&lt;Drom hustet ein wenig Blut aus.&gt;\n\nNorgannons Kern, sagt Ihr? Ich habe einige Tage damit verbracht, mehr darüber herauszufinden, aber das scheint eines der Relikte zu sein, die noch immer gut beschützt sind. Vermutlich aus gutem Grund.\n\nWenn König Sturmherz Euch hergeschickt hat, dann muss er etwas Nobles in Euch sehen... und ich werde mich dem Wunsch meines Königs nicht widersetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12876] = {title = "Unwillkommene Gäste", objective = "Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr 10 Sturmgeschmiedete Eindringlinge tötet.", description = "Unsere Späher haben im Tal nördlich von hier Eisenzwerge gesichtet. Ich hab' zufällig mitgekriegt, dass König Sturmherz Euch ausschickt, um Drom zu besuchen, und ehrlich gesagt mach' ich mir wegen denen ein bisschen Sorgen.\n\nFalls Ihr auf Eurem Weg auf Eisenzwerge stoßt, zeigt keine Gnade und erledigt sie schnell für mich, in Ordnung? Ich glaub' nicht, dass sie schon wissen, wo genau wir sind oder wie man hierher kommt, und ich will, dass das auch so bleibt.", progress = nil, completion = "Schlechte Neuigkeiten, Kamerad. Diese Eisenzwerge scheinen immer mehr zu werden... wir haben sie über die ganzen Berge verstreut gesehen. Das riecht nach Krieg.\n\nHabt Dank dafür, dass Ihr Euch um dieses Pack gekümmert habt... wir haben dadurch etwas mehr Zeit gewonnen.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12877] = {title = "Der einsame Wächter", objective = "Beschafft Frostgriffs Siegelring von einem der Eisenzwergüberwacher und bringt ihn zu Creteus in den Fußmarschen.", description = "Ich habe den Kern nie gefunden... doch ich habe oft mit dem Hüter Creteus gesprochen und das, was er gesagt oder besser: das, was er nicht gesagt hat, hat ihn verraten. Ihr findet Creteus auf der anderen Seite der Berge gen Osten in den Fußmarschen, wo er über die Maschine der Schöpfer Wache hält. Es kann gut sein, dass sich der Kern dort befindet, doch zuerst müsst Ihr Creteus' Gunst erlangen.\n\nDie Eisenzwerge sind hier gewesen und haben nach etwas gesucht... es ist gut möglich, dass sie nach dem Kern gesucht haben. Sie haben mir meinen Ring weggenommen. Findet ihren Anführer, erlangt meinen Ring zurück und legt diesen dann Creteus vor, damit er weiß, dass ich Euch geschickt habe.", progress = "Hallo, <Volk>.\n\nEs erfreut mich, zu sehen, dass Ihr Euch dazu entschlossen habt, meine Bekanntschaft nicht mit der Klinge, sondern mit der Zunge zu machen. Meinen Erfahrungen nach scheint dies in letzter Zeit eine immer seltenere Eigenschaft unter Euresgleichen zu sein.", completion = "Droms Ring? Dass er Euch nicht selbst vorgestellt hat, lässt mich darauf schließen, dass es ihm nicht gut geht. Tut mir leid, das zu hören. Drom ist ein nobler Zwerg, wenn auch ein neugieriger.\n\nNun denn, weshalb seid Ihr hierher gekommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12878] = {title = "Das versteckte Relikt", objective = "Creteus in den Fußmarschen hat Euch Informationen zukommen lassen, mit deren Hilfe Ihr Norgannons Kern finden könnt. Macht Euch auf den Weg dorthin.", description = "Während Eurer Abwesenheit wurde mir das Privileg einer Unterhaltung mit dem Zwerg Brann Bronzebart zuteil. Er gab mir zu verstehen, dass seine Aufgabe die Suche nach dem Schlüsselstein sei. Es stimmt mich zufrieden, dass seine Absichten zufriedenstellend sind... Dieser Zwerg, so glaube ich, könnte das Wesen sein, für das der Schlüsselstein geschaffen wurde.\n\nNorgannons Kern befindet sich im Eisigen Grab gen Südosten. Seine Bewacher sind uralte Wesen aus Eis. Sie werden Euch nicht willkommen heißen. Besiegt die Wächter und beschafft den Schlüsselstein. Ihr habt meinen Segen, <Volk>.", progress = nil, completion = "&lt;Die Truhe öffnet sich. Luft entweicht und erfüllt die Kammer mit einem modrigen Geruch, als läge dort etwas, das schon seit unzähligen Jahren hier gewesen ist. Norgannons Kern liegt auf dem Boden der Truhe, von den Jahren unberührt.&gt;", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12879] = {title = "Zorn des Frosterbenkönigs", objective = "Bringt Norgannons Kern zu Creteus in die Fußmarschen.", description = "<Als Ihr den Kern aus der Kiste nehmt, hört Ihr donnernde Schritte im Gang, die sich Euch nähern. In der Ferne ist leise der Klang eines Kampfes zu vernehmen.>", progress = "Jemand nutzt die Seelenschmiede, um diese Armee zu erschaffen... Ulduar ist nicht mehr sicher. <Volk>, konntet Ihr den Kern finden?", completion = "Jemand nutzt die Seelenschmiede, um diese Armee zu erschaffen... Ulduar ist nicht mehr sicher.\n\n&lt;Volk&gt;, ich freue mich, dass Ihr vor diesen Monstrositäten zum Kern gelangen konntet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12880] = {title = "Der Meisterforscher", objective = "Bringt Norgannons Kern zu Brann Bronzebart in die Maschine der Schöpfer.", description = "Zum Kombinieren des Schlüsselsteins benötigt Ihr Norgannons Bindung - ein Gerät, das sich in der Maschine des Schöpfers in der großen Grube neben uns befindet. Brann müsste inzwischen mit der anderen Hälfte des Schlüsselsteins da unten sein. Ich habe ihn in Bezug auf den Gebrauch des Geräts instruiert. Er erwartet Euch.\n\nIch werde tun, was ich kann, um die Eisenzwerge abzulenken, aber ich weiß nicht, wie lange ich sie aufhalten kann. König Sturmherz wird in Kürze mit ein paar seiner Männer in der Eisfestung eintreffen, um bei der Verteidigung zu helfen. Bitte beeilt Euch, <Volk>.", progress = "Hallöchen, Kamerad! Schön, Euch zu sehen. Habt Ihr ihn gefunden?", completion = "Ihr seid brillant! Wirklich brillant. Das ist wahrlich ein glorreicher Tag.\n\nSchnell, gebt mir den Kern, bevor die Zwerge hier auftauchen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCosmetic Enchant Cast\n\nIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12881] = {title = "Die Gebrüder Bronzebart", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12882] = {title = "Uralte Relikte", objective = "Bringt 10 Relikte von Ulduar zu Olut Bierbauch bei der Absturzstelle Grom'ash.", description = "Willkommen auf den Gipfeln.\n\nIch habe eine einfache Bitte an Euch, bevor Ihr Euren großen Ausflug antretet - wo auch immer dieser hinführen mag. In diesen Bergen verstreut gibt es uralte Ulduarschätze und -relikte. Die meisten befinden sich höchstwahrscheinlich im Besitz der verschiedenen empfindsamen Wesen dort.\n\nBringt jeden dieser Schätze zu mir zurück und ich werde Euch angemessen belohnen. Ich habe viele Sorten Starkbier - vielleicht werde ich Euch sogar mittrinken lassen.", progress = "Konntet Ihr die Relikte, von denen ich sprach, finden?", completion = "Die werden reichen! Herzlichen Dank. Ein Humpen für Eure Müh'?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLuftiges SilberbräuWorgzahn HafermehlstarkbierSchneefall LagerDrachenfeuer Chilibier\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12883] = {title = "Befehle von Drakuru", objective = "Bringt Drakurus Befehle zu Kreuzfahrerlord Lantinga in der Lichtbresche in Zul'Drak.", description = "Die Diener vernehmen den Ruf Eures Meisters! Der Lichkönig wird Drakuru die volle Kontrolle über die Armeen der Geißel in Zul'Drak geben. Uns wurde befohlen, alles zu töten.\n\nALLES MUSS STERBEN!\n\nWir werden die Leichen auf dem Todesfeld sammeln und sie dann zu Prinz Navarius in Zeramas schicken, damit sie dort in Diener der Geißel verwandelt werden! Nichts wird verschwendet, solange Drakuru ein Auge aufhält!\n\nBald werden wir das Blut der Propheten trinken und stärker werden, als jemals zuvor! Zul'Drak und Gundrak werden an die Geißel fallen!", progress = "Drakuru, hm? Ich habe den Namen schon einmal gehört...", completion = "Wenn dies derselbe Drakuru ist, wie der aus der Feste Drak'Tharon, dann... dann werden wir Hilfe von außerhalb benötigen.\n\nIn der Nähe sind Todesritter von Acherus stationiert. Sie folgen offensichtlich derselben Spur der Verwüstung, welche die Geißel hinterlassen hat, wie der Argentumkreuzzug. Da die Hälfte unserer Armee an der Argentumwache benötigt wird, um dort gegen die verrückt gewordenen Drakkaritrolle zu kämpfen, werden wir uns mit den Rittern der Schwarzen Klinge zusammentun müssen.\n\n&lt;Lantinga murmelt vor sich hin.&gt;\n\nIch hatte gehofft, dass ich diese Gauner nach der Sache bei der Kapelle des hoffnungsvollen Lichts nie wieder sehen müsste...", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12884] = {title = "Die Schwarze Wacht", objective = "Liefert Drakurus Befehle bei Stefan Vadu in der Schwarzen Wacht in Zul'Drak ab.", description = "Westlich von hier auf der anderen Seite der zerstörten Straßen und Gebäude liegt die Schwarze Wacht - ein Lager der Todesritter.\n\n<Kreuzfahrerlord Lantinga rollt die Schriftrolle mit Drakurus Befehlen wieder zusammen.>\n\nNehmt diese Befehle und liefert sie bei Stefan Vadu ab; er ist der leitende Todesritter in der Schwarzen Wacht. Lasst ihn wissen, dass der Argentumkreuzzug sich um Prinz Navarius kümmern wird und dass sie sich um Drakuru kümmern werden müssen.\n\nSeid vorsichtig, <Name>. Der Weg zur Schwarzen Wacht wimmelt nur so von Dienern der Geißel.", progress = "Was habt Ihr denn da, <Volk>?", completion = "&lt;Stefan liest sich das Schreiben durch, zerknüllt es und wirf es ins Feuer.&gt;\n\nNichts Neues. Der Argentumkreuzzug ist wieder einmal etwas zu langsam. Wir haben diesen Drakuru schon seit den Grizzlyhügeln verfolgt. Er ist zur Vernichtung bestimmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12885] = {title = "Die Verbannten von Ulduar", objective = "Sprecht mit Bergfels dem Steinformer in Bergfels' Zuflucht.", description = "Die Sturmgipfel sind faszinierend, aber hier findet Ihr mehr als bloß Titanenruinen. Jeder, der hier lebt, muss die Bedrohung durch Loken und seine Diener ertragen.\n\nEr hat seine Lieblingsdiener, die Eisenzwerge, auf einen brutalen Feldzug gegen alle Kreaturen aus Stein geschickt und die Irdenen aus Ulduar verbannt, die in Bergfels' Zuflucht an einem Berghang westlich der Bibliothek des Erfinders Unterschlupf fanden. Die dortigen Eisenzwerge setzen Bergfels und seinen Brüdern jedoch ordentlich zu. Findet sie und helft ihnen, <Name>.", progress = nil, completion = "Ihr kennt also Brann Bronzebart, wie? Er ist unser engster Verbündeter unter denen, die aus Fleisch sind. Wir sind Blutsbrüder im Kampf gegen Loken und seinen Anhängern, im Kampf um Ulduar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12886] = {title = "Der Drakkensryd", objective = "Verwendet die Hyldnirharpune, um 10 Drachenreiterinnen des Hildarthings im Tempel der Stürme zu besiegen.", description = "Das ist es, Ihr habt alle Aufgaben des Hildarthings bestanden... alle bis auf eine. Ihr seid unter den besten und wildesten unserer Schwestern aufgewachsen.\n\nDie letzte Aufgabe steht nun bevor. Der Drakkensryd - die wahre Prüfung des Werts und Kampfgeistes einer Hyldnir. Dort gibt es nur Euch, Euren Reitdrachen, eine Kettenharpune und einige Eurer Schwestern, mit denen Ihr um die Vorherrschaft kämpfen werdet.\n\nVerschont niemanden, dies wird nicht geduldet.", progress = "Fort mit Euch!", completion = "Sif... bist du das?", rewards = "Gamaschen der Eisigen WeitenEisharte ArmschienenLichtberührte MantelungSchulterstücke des AufstiegsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12887] = {title = "Nichts als Spaß und Spiele", objective = "Zerstört das Okular und erstattet danach Baron Splitter im Schattengewölbe Bericht.", description = "Die Ritter der Schwarzen Klinge wollen die Geißelbasis im Nordwesten einnehmen, die man das Schattengewölbe nennt. Ich habe einen Kontaktmann in der Gruppe, der um Hilfe gebeten hat.\n\nDer erste Schritt ist, den Lichkönig zu blenden. Er nutzt ein Gerät namens Okular, das über den Türmen des Gewölbes schwebt, um das Gebiet zu überwachen.\n\nUnsere Zwerge haben etwas geschaffen, das sich dagegen einsetzen lässt. Wenn das 'Auge' zerstört ist, findet Baron Splitter auf dem Gelände des Gewölbes. Er wird so tun, als stünde er noch immer unter der Kontrolle des Lichkönigs.", progress = "Das Okular steht noch! Thassarian war ein Narr, Euch zu trauen.\n\nWer immer Ihr auch seid, kehrt nicht zurück, bevor es zerstört ist. Ich darf hier nicht enttarnt werden!", completion = "Vielleicht können wir jetzt wirklich etwas bewegen. Aber lasst Euch nicht täuschen, der Lichkönig kann immer noch durch seine Diener der Geißel 'sehen'.\n\nDarum seid Ihr hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12888] = {title = "SCHROTT-E", objective = "Bringt die Zugriffskarte für SCHROTT-E sowie 4 Handvoll Kobaltbolzen und 5 überladene Kondensatoren zu SCHROTT-E in die Bibliothek des Erfinders.", description = "Mit dieser Karte erhält der Benutzer Zugriff auf die Steuerkonsole des Schrottbots genannt SCHROTT-E. Möglich sind Wartung des Roboters und Umprogrammierung seiner Direktiven.\n\nSCHROTT-E scheint dem Inneren der Bibliothek des Erfinders zugewiesen worden zu sein. Die Karte zeigt eine Liste aller defekten Komponenten und ausgefallenen Systeme des Bots. Mit den entsprechenden Teilen kann er jedoch wieder funktionstüchtig gemacht werden.", progress = "<Ihr öffnet die Zugangsklappe von SCHROTT-E.>", completion = "&lt;Ihr beginnt, die auf der Zugriffskarte angegebenen Reparaturen auszuführen. Als sie beendet sind, schließt Ihr die Zugangsklappe und schaltet den Stromschalter ein.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12889] = {title = "Die Prototypenkonsole", objective = "Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.", description = "Bezeichnung: SCHROTT-E.\n\nDirektive: Instandhaltung von Konsolen und Datenbanken der Bibliothek des Erfinders in Hüter Mimirs Abwesenheit.\n\nZeit seit letztem Instandhaltungszyklus: 489 Tage.\n\nStatus der schematischen Daten: unbekannt.\n\nAktuelle Aufgaben: Reparatur der Prototypenkonsole.", progress = nil, completion = "Ihr untersucht den Bildschirm der Prototypenkonsole. Mindestens einer von Mimirs Bauplänen scheint die lange Zeit zwischen den Instandhaltungszyklen überstanden zu haben. Den angezeigten Diagrammen und Anweisungen der Bauplandatei nach zu urteilen, könntet Ihr den abgebildeten Mechagnom mit Leichtigkeit selbst zusammenbauen.", rewards = "Ihr erlernt:\n\nKonstruktionsset: Schrottbot\n\nDer folgende Zauber wird auf euch gewirkt:\n\nKonstruktionsset: Schrottbot\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12890] = {title = "Wenn Größe von Bedeutung wäre...", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][12891] = {title = "Ich habe da eine Idee, aber zuerst...", objective = "Baron Splitter im Schattengewölbe hat Euch gebeten, eine Kultistenrute, einen Monstrositätenhaken, ein Spukseil und 5 Geißelessenzen zu besorgen.", description = "Als ich im, äh, Dienste des Lichkönigs stand, bedienten wir uns oft eines Geräts namens \"Herrschaftsstab\", mit dem wir dafür sorgten, dass einige der intelligenteren Diener der Geißel nicht aus der Reihe tanzten.\n\nIhr müsst mir dabei assistieren, einen neuen zu konstruieren.\n\nZu Eurem Glück sind alle notwendigen Komponenten verfügbar: eine Kultistenrute, ein Monstrositätenhaken, ein Spukseil und eine Handvoll Geißelessenz.\n\nDies sollte nicht allzu schwierig werden, <Klasse>.", progress = "Wenn es Euch gelungen ist, die Dinge zu besorgen, um die ich Euch gebeten habe, baue ich das Gerät - mit ein paar Modifikationen zu unseren Gunsten - und dann sind wir im Geschäft.", completion = "Schnell, gebt sie mir und bleibt außer Sichtweite!\n\nDie Rute, der Haken und das Seil sind miteinander kombiniert in ihrem Nutzen sehr selbsterklärend. Ich brauche das Ergebnis nur mit den Essenzen zu durchziehen und dann werden wir fortfahren können.\n\nIn seiner Bauweise mag es zwar banal sein, in seiner Anwendung ist es jedoch außergewöhnlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12892] = {title = "Nichts als Spaß und Spiele", objective = "Zerstört das Okular und erstattet Bericht bei Baron Splitter im Schattengewölbe.", description = "Die Ritter der Schwarzen Klinge wollen die Geißelbasis im Nordwesten einnehmen, die man das Schattengewölbe nennt. Ich stehe mit einem von ihnen in Kontakt, der uns um Hilfe gebeten hat.\n\nDer erste Schritt wird es sein, dem Lichkönig die Sicht zu rauben. Er verwendet zur Überwachung des Gebiets ein Gerät namens \"Okular\", das über den Türmen des Gewölbes schwebt.\n\nUnsere Goblins haben etwas konstruiert, das Ihr dagegen einsetzen könnt. Nachdem das \"Auge\" zerstört ist, müsst Ihr Baron Splitter auf dem Gelände des Gewölbes finden. Er gibt vor, immer noch unter der Kontrolle des Lichkönigs zu stehen.", progress = nil, completion = "Womöglich sind wir nun imstande, wirklich etwas zu unternehmen. Lasst Euch jedoch nicht täuschen, der Lichkönig kann immer noch durch seine Geißeldiener \"sehen\".\n\nAus diesem Grund seid Ihr hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12893] = {title = "Befreit Euren Geist", objective = "Baron Splitter im Schattengewölbe möchte, dass Ihr den Herrschaftsstab auf die Leichen von Ekel, Lady Nachtwald und dem Springer anwendet.", description = "Ekel, Lady Nachtwald und der Springer würden im Kampf gegen den Lichkönig exzellente Waffen abgeben, wenn sie von seinem Willen befreit werden könnten. Genau das ist der Zweck des Herrschaftsstabs.\n\nIhr findet sie auf den Hängen im Osten und Westen des Gewölbes sowie auf der mittleren Ebene des Gewölbes über uns. Der Stab muss auf die drei Leichen angewandt werden.\n\nFliegt nun. Wir werden sie auf unsere Seite holen!", progress = nil, completion = "Wir werden diese drei gut gebrauchen können, wenn wir endlich das Gewölbe einnehmen.\n\nWo wir gerade dabei sind...", rewards = "Schal des SchattengewölbesAuf Euch wartet eine dieser Belohnungen:\n\nLady Nachtwalds VerlobungsringBaron Splitters SiegelKette des Herrschers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12894] = {title = "Lager der Kreuzfahrer", objective = "Sucht Kreuzfahrer MacKellar im Lager der Kreuzfahrer in Zul'Drak auf.", description = "Kreuzfahrer Dargath, Kreuzfahrer MacKellar, Ingenieur Schilf und die Zwillinge Gerk und Burr wurden vor Tagen zum Todesfeld entsandt, um dort eine neue Front zu eröffnen. Dem letzten Briefwechsel zufolge, hatten sie an der Grenze zu den Todesfeldern nordwestlich von hier erfolgreich ein Lager errichtet.\n\nAngesichts dieser neuen Informationen über Drakuru und Prinz Navarius denke ich, dass es nur klug wäre, jemanden schnellstens zum Lager der Kreuzfahrer zu entsenden.\n\nPackt Eure Sachen, <Name>. Ihr müsst sofort los!", progress = nil, completion = "Es lief alles gut, bis die Geißel angriff. Sie haben sich mit Dargath, Gerk und Burr davongemacht und haben darüber hinaus auch unser Beförderungsmittel zerstört. Ratet mal, wer den Angriff angeführt hat.\n\n&lt;MacKellar nickt.&gt;\n\nNavarius...\n\nScheint, als wäre die ganze Gegend hier eine Art Werkstatt, in der Diener der Geißel hergestellt werden. Wir stehen mitten in einem verdammten untoten Minenfeld!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12895] = {title = "Der verschwundene Bronzebart", objective = "Holt die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Boktar Blutfurie an der Absturzstelle Grom'ash.", description = "Vor unserem Aufbruch erhielt ich die Akte, die Späher Vor'takh über diesen Brann Bronzebart angelegt hat. Seinen Tagebucheintragungen und Funden an den Grizzlyhügeln zufolge besteht kein Zweifel, dass Brann zu den Sturmgipfeln aufgebrochen ist. Bevor wir abstürzten sah ich noch kurz eine Lagerstätte. Sie liegt südlich von hier, jenseits der Fußmarschen, oberhalb des gefrorenen Flusses namens Bors Atemstrom. \n\nWenn Brann nicht dort ist, dann durchsucht das Lager und die Umgebung nach Hinweisen darauf, wohin dieser verflixte Zwerg aufgebrochen ist. Bringt mir alles, was Ihr dort findet.", progress = "Habt Ihr Bronzebarts Lager schon finden können?", completion = "Bei unserem Glück hätte ich das vermutlich vorhersehen müssen. Aber so leicht wird er mir nicht davonkommen. Ich bin gespannt, was in der Nachricht steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12896] = {title = "Wenn man ihn nicht überzeugen kann", objective = "Besiegt General Lichtbann und informiert anschließend Thassarian an Bord der Himmelsbrecher über Euren Erfolg.", description = "Todesritter wie General Lichtbann werden an der kurzen Leine gehalten und können nur unter höchst außergewöhnlichen Umständen dazu gebracht werden, sich gegen den Lichkönig zu stellen.\n\nDer General hält sich ausschließlich im Gewölbe auf und überwacht die Erschaffung neuer Waffen. Wagt Euch an eines seiner Waffenregale in der Nordschmiede und er wird auftauchen, das versichere ich Euch. Ich werde Euch Ekel, Lady Nachtwald und den Springer zur Unterstützung schicken.\n\nWenn wir das Schattengewölbe endlich erobern wollen, muss General Lichtbann fallen!", progress = nil, completion = "General Lichtbann und seine Streitkräfte wurde besiegt? Das Schattengewölbe ist erobert?", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12897] = {title = "Wenn man ihn nicht überzeugen kann", objective = "Besiegt General Lichtbann und berichtet dann Koltira Todesweber an Bord des Kanonenboots Orgrims Hammer von Eurem Erfolg.", description = "Todesritter wie General Lichtbann werden an einer zu kurzen Leine gehalten, als dass wir sie vom Willen des Lichkönigs loslösen könnten... außer unter außergewöhnlichen Umständen.\n\nDer General hält sich innerhalb des Gewölbes auf und beaufsichtigt die Herstellung neuer Waffen. Sabotiert eines seiner Waffenregale an der nördlichen Schmiede und ich versichere Euch, er wird kommen. Ich werde Ekel, Lady Nachtwald und den Springer zu Eurer Unterstützung mitschicken.\n\nWenn wir das Schattengewölbe jemals erobern wollen, muss General Lichtbann fallen!", progress = nil, completion = "General Lichtbann und seine Streitkräfte sind besiegt? Ist das Schattengewölbe eingenommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12898] = {title = "Das Schattengewölbe", objective = "Meldet Euch bei Baron Splitter im Schattengewölbe.", description = "Das klingt, als hättet Ihr Euch außerordentlich gut geschlagen. Außerdem konntet Ihr dabei drei wichtige Verbündete für die Ritter der Schwarzen Klinge gewinnen.\n\n<Thassarian lässt seinen Blick zum Horizont schweifen.>\n\nIhr solltet zurückgehen. Inzwischen werden Baron Splitter und die anderen Todesritter erbittert kämpfen, um das Schattengewölbe gegen die Macht der Geißel zu verteidigen.\n\nSie werden gewiss Eure Hilfe benötigen.", progress = nil, completion = "Schön, dass Ihr zurück seid. Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSanft glühende KugelChuchus kleiner HorrorkastenDornige Rosenbrosche\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12899] = {title = "Das Schattengewölbe", objective = "Meldet Euch bei Baron Splitter im Schattengewölbe zurück.", description = "Anscheinend seid Ihr sehr erfolgreich gewesen. Zudem habt Ihr im gleichen Atemzug drei sehr wichtige Verbündete für die Ritter der Schwarzen Klinge gewonnen.\n\n<Koltira blickt hinab auf die Karte am Boden.>\n\nIhr solltet zurückgehen. Mittlerweile werden Baron Splitter und die anderen Todesritter bestimmt bis zum letzten Blutstropfen darum kämpfen, das Schattengwölbe gegen den Ansturm der Geißel zu verteidigen.\n\nIch bin mir sicher, dass sie Eure Hilfe gebrauchen könnten.", progress = nil, completion = "Gut, dass Ihr zurückgekehrt seid. Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSanft glühende KugelChuchus kleiner HorrorkastenDornige Rosenbrosche\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12900] = {title = "Ein Geschirr anfertigen", objective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr 3 Bälge von Eismähnenyetis besorgt.", description = "Ihr wollt also reiten? Wenn Ihr es so weit geschafft habt, dann habt Ihr wohl auch einen Versuch bei den Hildarthings verdient.\n\nAber eins nach dem anderen. Zuerst müssen wir Euch ein Geschirr anfertigen.\n\nIn den Klippen im Süden streifen vereinzelte Yetigruppen herum. Ihre Haut ist zäh und hat genau die richtige Dicke. Bringt mir einige, dann können wir dafür sorgen, dass Ihr Euch auf den Weg des Bärenreiters begebt.", progress = "Habt Ihr die Bälge schon gefunden? Die Yetis streifen in den Hügeln unter uns herum.", completion = "Die sollten genügen. Ich werde das Geschirr für Euch bald fertig haben.", rewards = "YetibalgmantelungAstrids ReithandschuheSchneetreter von BrunnhildarAuf Euch wartet eine dieser Belohnungen:\n\nRunenverzierter Ring aus Brunnhildar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12901] = {title = "Aus nichts etwas herstellen", objective = "Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr 10 Stück Metallschrott der Geißel beschafft.", description = "Prinz Navarius muss gestoppt werden. Wir können nicht zulassen, dass die Geißel diese Gegend weiterhin als Werkstatt zur Zombieherstellung verwendet. Wenn wir den Panzer zum Laufen bekommen, dann könnten wir womöglich eine Chance haben. Was ich jetzt brauche, sind Ersatzteile.\n\nNordwestlich von hier befindet sich eine Gegend namens Thryms Ende. Die Armeen der Geißel benutzen diese Gegend als eine Art Basis. Über dieser Basis verteilt sind die Trümmer, die sie bei ihrer Ankunft hinterlassen haben. Überall liegt vereinzelter Metallschrott der Geißel herum. Beschafft Euch das Zeug und ich werde versuchen, es sinnvoll einzusetzen.", progress = "Ich weiß wirklich nicht, ob dieser Plan funktionieren wird, <Name>. Bringt mir einfach den Metallschrott und ich werde tun, was ich kann.", completion = "Was ist das für ein Schrott! Ah, verdammt! Es ist zu nichts zu gebrauchen. Das Metall der Geißel ist also nicht die Lösung. Was machen wir nur?", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12902] = {title = "Auf der Suche nach Antworten", objective = "Durchsucht den Zornklauenbau nach Hinweisen darüber, wer oder was die Angriffe gegen die Wolvar der Zornklauen eingeleitet hat.", description = "Diese armen Kreaturen sind die einzigen Überlebenden.\n\nLaut dem, was ihr Häuptling sagt, seien Drakkaritrolle und Zornklauen jahrtausendelang Verbündete gewesen. Sie hätten hier über Generationen hinweg neben den Trollen gelebt und den Wandel der Welt um sie herum nicht bemerkt. Für die Zornklauen ist ein Troll ein Troll, also kam der Trollangriff auf ihren Bau überraschend.\n\nWir benötigen ein paar Antworten, <Name>. Durchkämmt ihr Dorf südöstlich von hier nach Hinweisen darüber, wer oder was für diese Angriffe verantwortlich ist.", progress = nil, completion = "Da schwebt eine Schriftrolle über dem seltsamen Altar. Das muss genau das sein, wonach Kreuzfahrerlord Lantinga sucht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12903] = {title = "Dafür sind Freunde da...", objective = "Kreuzfahrer MacKellar im Lager der Kreuzfahrer möchte, dass Ihr nach Kreuzfahrer Dargath, Gerk und Burr sucht.", description = "Wir wurden von Prinz Navarius und mindestens einem Dutzend Diener der Geißel angegriffen. Ich sagte zu Dargath und den Zwillingen, dass sie im Panzer bleiben sollen, doch sie wollten nicht auf mich hören. Dargath sah mir in die Augen und sagte: \"Wenn niemand diesen Panzer verlässt, dann werden sie uns alle umbringen.\" Anschließend ließ er Schilf den Motor abstellen und griff an. Das Heldenhafteste, was ich jemals gesehen habe.\n\nIch hörte, wie der Prinz den Monstern Befehle zubrüllte. Hat sich angehört, als würde er sie in nordwestliche Richtung nach Thryms Ende schicken. Wir müssen unsere Freunde retten. Werdet Ihr nach ihnen suchen?", progress = nil, completion = "Die drei haben ein großes Opfer gebracht, das man so bald nicht vergessen wird. Ihr Dahinscheiden wird nicht umsonst gewesen sein. Wir werden siegreich sein!", rewards = "Kapuze des SanitätersStulpen des GrünheilersPantalons des LäuterersAuf Euch wartet eine dieser Belohnungen:\n\nHorn des Argentumfurors\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12904] = {title = "Das Licht verwehrt mir meine Rache", objective = "Gerk in Thryms Ende in Zul'Drak möchte, dass Ihr 15 Vargul tötet.", description = "Sie... sie haben meinen Bruder getötet.\n\n<Gerk kämpft gegen die Tränen an.>\n\nHaben ihn wie ein Tier abgeschlachtet. Nun liegt er auf einem ihrer Tische auf der anderen Seite des Lagers - bereit für ihre grauenhaften Experimente. Dargath ist auch tot. Der Paladin hat bei den Ruinen gen Nordosten eine echte Heldentat vollbracht, doch der Anführer der Vargul, Algar, war zu stark.\n\nIch bin als einziger übrig und werde auch bald tot sein. Ich... ich verwandle mich.\n\nWenn mir das Licht meine Rache verwehrt, werdet Ihr, <Klasse>, sie mir dann gewähren? Tötet sie alle.", progress = "Ihr tut der Welt einen Gefallen, <Klasse>. Diese Monster müssen aufgehalten werden!", completion = "&lt;Gerk liegt im Sterben.&gt;\n\nS... Sie sagen, dass diese Vargul... diejenigen sind... die der Lichkönig als unwürdig erachtete. Kön... könnt Ihr Euch... das vorstellen? Den... Denkt nur einmal daran... wie mächtig... diejenigen sein müssen, die... würdig sind...\n\nIch werde für Euch beten, Held... im Jenseits... Möget Ihr nie mehreren von ihnen begegnen.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12905] = {title = "Mildred die Grausame", objective = "Sprecht mit Mildred der Grausamen in der Verlassenen Mine.", description = "Abgemacht, <Name>. Ihr helft mir, mich von diesen Ketten zu befreien, und ich helfe Euch, Euren kleinen grünen Freund zu finden.\n\nDie Hyldnir, die diese Mine leitet, wird Mildred die Grausame genannt und das aus gutem Grund.\n\nSagt ihr, dass Ihr geschickt wurdet, um bei der Arbeit in den Minen zu helfen. Tut, was auch immer sie von Euch verlangt, bis sie Euch die Schlüssel für meine Ketten anvertraut.", progress = nil, completion = "Ich habe auf Ersatz für einen meiner Aufseher gewartet. Wurde langsam Zeit, dass du auftauchst.\n\nNa, dann schicken wir dich mal an die Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12906] = {title = "Disziplin", objective = "Mildred die Grausame an der Verlassenen Mine möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul anwendet.", description = "Dann wollen wir Euch für den Anfang mal etwas Leichtes geben. Die Vrykulmänner, die für uns in den Minen schuften, tun dies gegen ihren Willen... und lediglich aus Furcht vor unseren Klingen.\n\nHin und wieder verliert einer von ihnen seine Motivation. Haltet nach denjenigen Ausschau, die nicht kooperieren wollen, und weist sie in ihre Schranken.\n\nHier, nehmt diese Disziplinarrute - Ihr wollt Schmerzen zufügen und niemanden totschlagen. Nun ja, die meiste Zeit zumindest.", progress = "Bist du fertig? Hoffe, du hast nicht zu viele von diesen Mistkerlen totgeschlagen. Wir brauchen die Arbeitskräfte.", completion = "Für eine neue Aufseherin nicht schlecht. Ich hab' noch eine andere Aufgabe, falls du dich heute mutig fühlst.", rewards = "Mildreds GugelGeschmeidige ProtodrachengamaschenTrainingshelm der VrykulMildreds UmklammerungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12907] = {title = "Exempel statuieren", objective = "Mildred die Grausame in der Verlassenen Mine möchte, dass Ihr Garhal tötet.", description = "Auf jede Aktion folgt eine Gegenreaktion, Schwester. In unserem Fall sieht es wie folgt aus: Wir üben Druck auf die Männer aus und als Folge wurden neue Gerüchte über einen Aufstand laut.\n\nDas bärtige Schwein hinter diesen Hetzreden wird Garhal genannt. Schafft ihn beiseite... und sorgt dafür, dass die anderen Männer sein Ableben mitverfolgen. Sie müssen lernen, dass Ungehorsam nicht toleriert wird.", progress = nil, completion = "Wenn ich am Anfang Bedenken bezüglich Eures Engagements hatte, dann sind diese nunmehr verflogen. Noch ein klein wenig mehr Mühe von Eurer Seite her und Ihr könntet zu einem permanenten Mitglied meiner Operation werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12908] = {title = "Eine bestimmte Gefangene", objective = "Bringt Mildreds Schlüssel zu Lok'lira der Greisin in die Verlassene Mine.", description = "Ihr seid gnadenlos und habt Euch in dieser Gegend bewährt.\n\nIch habe eine weitere Aufgabe für Euch. Eine der gefangenen Vrykul ist zu einer größeren Belastung geworden, als vorauszusehen war.\n\nSie besaß die Frechheit, auf ihr Recht zu pochen, am Hildarthing, unserem heiligen Wettstreit der Stärke und Kampfkünste, teilnehmen zu dürfen.\n\nHier ist der Schlüssel zu ihren Fesseln. Aber macht es so schmerzlos wie möglich, denn sie ist immerhin eine Frau, wenn auch keine von uns.", progress = "Wurde auch langsam Zeit.", completion = "Ich wusste, dass Ihr zurückkommt! Befreit mich von diesen Fesseln, dann helfe ich Euch, den Goblin zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12909] = {title = "Der Nase trauen", objective = "Sprecht mit Khaliisi am Fuße des Berges östlich der Absturzstelle Grom'ash.", description = "Um Brann aufzuspüren, brauchen wir eine Kreatur mit präzisem Geruchssinn, die gut Spuren lesen kann. Zwar waren im Zeppelin keine Hunde, aber ich glaube, ich habe einen Ersatz gefunden.\n\nNach dem Absturz schickte ich Khaliisi den Osthang des Berges hinab, um zu jagen. Ihre Katze Frostbeißer kann im Schnee hervorragend Beute machen. Sagt ihr, dass sie sich vorerst von ihrer Gefährtin trennen muss. Sie kann allein jagen, aber wir haben keine andere Möglichkeit, Brann Bronzebart zu finden.", progress = nil, completion = "Boktar hat Frostbeißer also eine andere Aufgabe zugedacht, was? Nun, ich hoffe wirklich für ihn, dass die Sache wichtig ist. Er weiß, dass man einen Jäger normalerweise nicht von seinem Gefährten trennt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12910] = {title = "Den Täter ausschnüffeln", objective = "Schwingt Euch auf Frostbeißer und folgt der Fährte von Branns Notiz bis zu ihrem Ausgangspunkt. Beschafft anschließend Branns Kommunikator und stellt mit seiner Hilfe Kontakt mit Brann Bronzebart her.", description = "Dieses Mal werde ich Boktar seinen Willen lassen, doch ich erwarte von ihm, dass er es auch wieder gut macht. Seht mich nicht so an. Boktar mag vielleicht das Kommando haben, doch niemand sagt einem Jäger, was er zu tun hat.\n\n'Dein Begleiter muss verschwinden,' sagt er. 'Mach, dass er zu Knurren aufhört.'\n\nUnd ganz plötzlich ändert er seine Meinung, so wie es ihm gerade in den Kram passt. Dann wieder beschwert er sich darüber, dass Frostbeißer ihn ein wenig gebissen haben soll. Doch keine Sorge, er wird Euch ausgezeichnete Dienste leisten und Eure Beute aufspüren. Nachdem er sein Ziel gefunden hat, liegt es an Euch, mit den Eisenzwergen, Brann oder wem auch immer Ihr finden mögt fertigzuwerden.", progress = "Wer... wer seid Ihr?", completion = "&lt;Ihr aktiviert den Kommunikator und das Bild eines Zwergen erscheint. Es kann sich nur um Brann Bronzebart handeln.&gt;\n\n&lt;Seinem Gesichtsausdruck nach zu urteilen, scheint Brann erschrocken darüber zu sein, Euch zu sehen, und fängt an, wie wild zu gestikulieren.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12911] = {title = "Kill Credit Test", objective = "/wave at Kill Credit Test", description = "/wave at me and I'll assign 'kill credit to player' to you.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12912] = {title = "Ein großer Sturm rückt an", objective = "Gymer, König der Sturmriesen, hat Euch gebeten, einen Weg zu finden, ihn aus seinem Käfig zu befreien. Sprecht mit Ingenieur Schilf im Lager der Kreuzfahrer.", description = "Ihr seid nicht wie die anderen, <mein Kleiner/meine Kleine>. Ihr stinkt nicht nach uraltem Tod. Womöglich kann man Euch vertrauen.\n\nIch bin Gymer, König der Sturmriesen. Ich wurde von meinem Bruder Thiassi, jetzt ein untoter Diener des Lichkönigs, hierher gelockt. Als ich erkannte, dass sein Hilferuf eine Falle ist, war es schon zu spät. Nun bin ich ein Gefangener der Geißel und ich fürchte, dass ich schon bald dasselbe Schicksal teilen werde, wie viele andere Sturmriesen.\n\nFindet einen Weg, mich aus diesem Käfig zu befreien, und ich werde Euch helfen, so gut ich kann.", progress = nil, completion = "Ein... ein Sturmriese? Ich weiß nicht so recht, &lt;Name&gt;. Das hört sich riskant an. Auf der anderen Seite denke ich nicht, dass wir allzu viele Möglichkeiten haben.\n\nWenn ich das mache, dann müsst Ihr mir versprechen, dass Ihr Euren Freund dazu bringt, uns dabei zu helfen, mit Navarius und seinen Spießgesellen fertig zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12913] = {title = "Sprich Orcisch, Mann!", objective = "Sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash.", description = "<Brann fängt an, wie wild zu gestikulieren und in seiner Muttersprache zu faseln.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\nGar Ruk dagUm loch angor-magi ta har ruk!\n\n<Ein wenig später erkennt Ihr, dass das Gespräch zu nichts führt. Vielleicht wird der Schamane Moteha Windkind bei der Absturzstelle Grom'ash wissen, was zu tun ist.>", progress = nil, completion = "Boktar wird nicht erfreut darüber sein, dass Ihr Brann nicht gefunden habt, doch zumindest seid Ihr nicht mit leeren Händen zurückgekehrt. Nun lasst uns sehen, was wir wegen diesem plappernden Zwerg machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12914] = {title = "Gymers Rettung", objective = "Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr ihm 6 Essenzen der Banshees und 6 Einheiten Kieselerde bringt.", description = "Ihr meint also, dass er in einen 30 Meter großen Käfig gesperrt ist, wie?\n\nWenn meine Berechnungen stimmen, dann sollten wir zumindest die Scharniere des Käfigs schwächen können, um dem Riesen genug Spielraum zum Ausbrechen zu geben.\n\nDamit das funktioniert, brauche ich ein paar Verflüssiger und Stabilisatoren.\n\nDie Essenz der Banshees sollte sich sehr gut als Verflüssiger eignen. Ihr könnt das Zeug von den Banshees in den Toten Feldern nordöstlich von hier bekommen. Die Stabilisatoren könnt Ihr von den Erdwütern im Südwesten nahe der Schwarzen Wacht bekommen.\n\nBewegt Euch!", progress = "Ohne die Verflüssiger und Stabilisatoren werde ich nie den Sprengstoff herstellen können, den wir benötigen, um Euren Freund aus seinem Gefängnis zu befreien.", completion = "Glücklicherweise haben wir genug Sprengstoff gehabt. Die riesige Zephyriumladung herzustellen, sollte dank der Materialien, die Ihr mir gebracht habt, kein Problem mehr darstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12915] = {title = "Zäune reparieren", objective = "Thorim im Tempel der Stürme möchte, dass Ihr Fjorn und 5 Sturmgeschmiedete Eisenriesen in Fjorns Amboss östlich von Dun Niffelem tötet.\n\nMit Thorims Glücksbringer der Erde könnt Ihr seine Irdenen zur Unterstützung holen. Zum Benutzen des Glücksbringers benötigt Ihr einen Granitfelsen aus Fjorns Amboss in der Nähe.", description = "Wenn ich den Tempel der Schöpfer aus meines Bruders Kontrolle entreißen möchte, müssen die Dinge zwischen mir und meinen alten Verbündeten besser stehen.\n\nVielleicht wäre es ein erster Schritt zu einer neuen Freundschaft mit den Frostriesen, wenn wir zusammen einen gemeinsamen Feind vernichten würden.\n\nFjorn hat zur Belagerung von Dun Niffelem Eisenriesen eingesetzt. Er befindet sich bei Fjorns Amboss weit östlich von hier - geht dorthin und besiegt ihn. Schwächt seine Streitkräfte so weit, bis die Söhne Hodirs den Sieg davontragen.\n\nHier, <Name>, nehmt diesen Glücksbringer und ruft mit ihm meine Irdenen zu Hilfe.", progress = nil, completion = "Es ist also vollbracht.\n\nHoffen wir, dass es ausreicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12916] = {title = "Unsere einzige Hoffnung", objective = "Sprecht mit Gymer in Thryms Ende in Zul'Drak, nachdem Ihr mit der riesigen Zephyriumladung die Umzäunung der Geißel geöffnet habt, in welcher der Gefangene festgehalten wird.", description = "Das, was ich Euch gleich geben werde, nennt sich Zephyrium. Die Substanz ist hochexplosiv und weist einige besondere Eigenschaften auf. Dank seiner Formbarkeit, werdet Ihr die Scharniere und Spalten füllen können und so maximalen Schaden anrichten.\n\nKehrt zu Eurem Freund zurück und benutzt die riesige Zephyriumladung, um ihn zu befreien.\n\nHoffen wir, dass er seinen Teil der Abmachung einhalten wird. Er ist unsere einzige Hoffnung.", progress = "Ich bin ein Riese meines Wortes, mein Kleiner.", completion = "FREIHEIT!\n\nHabt keine Angst, mein Kleiner. Gymer ist ein ehrenhafter Riese. Ich wünsche genauso wie Ihr und Euer Volk, dass die Geißel aus diesem Land vertrieben und der Lichkönig vernichtet wird. Ich werde Euch wie versprochen so gut wie möglich helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12917] = {title = "Mit der Stimme des Windes sprechen", objective = "Bringt 5 Stimmen des Windes zu Moteha Windkind an der Absturzstelle Grom'ash.", description = "Ich denke, mit unserem Glück hätten wir nicht erwarten sollen, Brann so leicht zu finden. Wenn wir herausfinden können, was Brann sagt, könnt Ihr ihn davon überzeugen, seinen Ort preiszugeben.\n\nDie Macht des Windes ist in diesen Bergen stark, was sich uns als äußerst nützlich erweisen könnte. Ein geübter Schamane kann den Klang aller Stimmen dieser Welt über den Wind hören.\n\nIm Nordwesten, auf der verschneiten Ebene, werdet Ihr Kreaturen des Windes finden, die Sturmreiter. Fangt ihre Stimmen ein und bringt sie zu mir.", progress = "Habt Ihr die Stimmen des Windes?", completion = "Ihr solltet jetzt mit dem Zwerg sprechen können. Fragt Boktar, was er von Euch benötigt. Wir haben keine Zeit zu verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12918] = {title = "Edelsteine perfektionieren", objective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Ounhulo in Valgarde.", description = "Ist so kalt wie der Atem eines Frostwyrms hier oben, findet Ihr nicht? Mir fehlen nicht nur die Kunden für mein Handwerk, sondern auch der Vorrat an Edelsteinen, die ich verkaufen könnte. Wenn Ihr mir einige ungeschliffene Edelsteine für meine Vorräte bringen würdet, dann könnte ich Euch beibringen, wie man Edelsteine perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", progress = "Ihr seid zu großzügig. Das Mindeste, was ich tun kann, ist, Euch beizubringen, wie man einen Edelstein perfektioniert.", completion = "Das sind die perfekten Exemplare für meine Vorräte. Ich werde Euch nicht nur beibringen, wie man das Handwerk des Edelsteinschleifens perfektioniert, nein, ich werde außerdem einen der Edelsteine in seine perfekte Form schleifen und ihn Euch dann als Belohnung geben.", rewards = "Ihr erlernt:\n\nEdelsteinperfektion\n\nDer folgende Zauber wird auf euch gewirkt:\n\nEdelsteinperfektion\n\nIhr bekommt außerdem:\n\nKleiner Samtbeutel"}
MultiLanguageQuestData['de'][12919] = {title = "Die Rache des Sturmkönigs", objective = "Sprecht mit Gymer, um auf ihm zu reiten.\n\nVernichtet 100 Diener der Geißel und Algar den Auserwählten, Thrym und Prinz Navarius. Meldet Euch bei Kreuzfahrer MacKellar im Lager der Kreuzfahrer, falls Ihr erfolgreich sein solltet.", description = "Der Lichkönig hat mein Volk dezimiert. Nun verwendet die Geißel die Leichen von Sturmriesen, um daraus entweder hirnlose Fleischriesen zu erschaffen oder noch Schlimmeres: zusammengeflickte Monstrositäten wie Thrym.\n\nIch werde vor nichts zurückschrecken, um dafür zu sorgen, dass sie alle von dieser Welt getilgt werden. Zusammen werden wir die Diener der Geißel vernichten, die Zul'Drak bedrohen.\n\nWir werden sie alle töten: Navarius, Algar und Thrym!\n\nWenn Ihr bereit seid, dann lasst es mich wissen und wir werden unsere Zerstörungsreise antreten.", progress = nil, completion = "Unglaublich! Darüber wird man noch lange, lange Zeit reden, &lt;Name&gt;! Ein Mann ritt auf dem Kopf des Königs der Sturmriesen und vernichtete eine ganze Armee der Geißel!\n\nUnd ich war da, als es passierte...", rewards = "Greifer des RiesenreitersHörner des geladenen SchreckensArmschienen des rachsüchtigen SchwarmsSchulterstücke des LebenslichtsUmklammerung des SturmriesenIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12920] = {title = "Brann einholen", objective = "Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen. Erstattet anschließend Boktar Blutfurie bei der Absturzstelle Grom'ash Bericht.\n\nFalls Ihr Branns Kommunikator verlieren solltet, dann sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash.", description = "Worauf wartet Ihr noch? Dank Moteha wurde die Sprachbarriere durchbrochen. Tretet mit Brann Bronzebart in Verbindung und versucht, so viel wie möglich darüber herauszufinden, wo er sich versteckt hält und hinter was er her ist.\n\nVielleicht lässt sich aus diesem Desaster noch etwas Gutes gewinnen.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Boktar lauscht Eurem Bericht über Euer Gespräch mit Brann.&gt;\n\nAn den Worten des Zwergs ist etwas Wahres dran. Vor'takhs Plan ist nicht der Stil der Horde. Wenn Brann Bronzebart einen Weg kennt, wie diese Eisenzwerge und ihre Schutzherren aufzuhalten sind, dann dient es unserer Sache, ihm zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12921] = {title = "Tapetenwechsel", objective = "Trefft Euch mit Lok'lira der Greisin in Brunnhildar.", description = "Ausgezeichnet. Am östlichen Ende der Mine gibt es einen Ausgang, der nach Brunnhildar führt. Macht Euch auf den Weg dorthin. Ich werde Euch dort treffen.\n\nWir dürfen nicht gemeinsam gesehen werden, damit nicht der Verdacht entsteht, dass Ihr mir helft. Ich werde meine Magie dazu verwenden, mein Aussehen zu verändern. Macht Euch keine Sorgen, <Volk>. Wir werden Euren Freund im Nu gefunden haben.", progress = nil, completion = "Ihr seid hier - gut. Ich denke, dass ich jetzt weiß, wo sich Euer Goblin befindet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12922] = {title = "Des Veredlers Feuer", objective = "Ihr müsst 10 wütende Funken von den wutentbrannten Klagegeistern auf dem Frostfeldsee sammeln und anschließend den Amboss bei Fjorns Amboss verwenden.", description = "Ein geheimnisvolles Schimmern tritt durch die poröse Außenfläche dieses Stück Metalls nach Außen.\n\nIhr habt das Gefühl, dass es das Klügste wäre, die Schlacke mit Fjorns Amboss wegzubrennen.\n\nWährend Ihr gerade darüber nachdenkt, wo Ihr in dieser gefrorenen Einöde etwas finden könntet, das heiß genug dafür wäre, läuft Euch ein Feuerklagegeist über den Weg...", progress = "Die Oberfläche des Ambosses ist glühend heiß, im scharfen Gegensatz zu der winterlichen Luft, die ihn umgibt.", completion = "Ihr legt das Metall auf den Amboss und sofort, nachdem Ihr die Funken dazugegeben habt, fangen sie an, das Erz wie wild zu bearbeiten.\n\nAls die Funken schließlich verglüht sind, ist nur noch ein großes Stück Metall übrig, das auf besondere Art und Weise schimmert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12924] = {title = "Ein Bündnis schließen", objective = "Ihr sollt nach Dun Niffelem gehen und König Jokkum darum bitten, Thorims Rüstung neu schmieden zu lassen. Nachdem Ihr Jokkums Aufgabe abgeschlossen habt, sollt Ihr mit Njormeld in Dun Niffelem sprechen.", description = "<Thorim lächelt zum ersten Mal, seitdem Ihr ihn kennt.>\n\nLangsam fängt es an, so auszusehen, als hätte das Schicksal seine Finger im Spiel, <Volk>.\n\nEure Entdeckung stellt die Überbleibsel meiner Rüstung dar, die ich vor langer Zeit in einem Anflug von Trauer abgeworfen und den Elementen überlassen habe. Nur die Söhne Hodirs können sie neu schmieden - sie sind die eigentlichen Erbauer.\n\nWomöglich habt Ihr genug getan, um ihren Hass mir gegenüber zu beschwichtigen. Sucht ihren König Jokkum auf, falls er noch lebt.\n\nVersucht, seine Gunst zu gewinnen, und erbittet seine Hilfe.", progress = nil, completion = "Es scheint, als wäre meine Technik erheblich besser geworden. Entweder ist es das oder die Legenden, die diesen Amboss umranken, sind wahr.\n\nDiese Rüstung ist besser als die alte und hat weniger Materialien benötigt.\n\nMit dem, was übrig geblieben ist, konnte ich etwas für Euch anfertigen - als Bezahlung für Eure Unterstützung.", rewards = "Gewänder von Dun NiffelemNjormelds SchulterstückeNeugeschmiedete KettengamaschenJokkums RingIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12925] = {title = "Missgeburten", objective = "Thyra Kvinnshal in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.", description = "Der Lichkönig hat uns zu drei verschiedenen Gelegenheiten Botschafter geschickt. Alle drei wurden auf der Stelle vernichtet.\n\nUnsere Schwestern in Valkyrion waren unseren Traditionen nicht so treu und gingen auf die Annäherungsversuche der Geißel ein. Anstatt die wilden Drachen zu fangen, lassen sie sie nun aus der Verseuchung und dem Schmutz auferstehen, in dem sich die Geißel suhlt.\n\nNehmt das Frostöl, das die Valkyrion von Hyldnir bei sich tragen, und lasst damit alle Eier, die Ihr findet, gefrieren. Gerüchten zufolge gibt es dort, wo die Eier aufbewahrt werden, auch einen verrotteten Tümpel der Verseuchung.", progress = nil, completion = "Wir sind Euch sehr dankbar, Schwester, denn wir können nicht zulassen, dass mit unseren wichtigen Traditionen gebrochen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12926] = {title = "Teile des Rätsels", objective = "Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen.", description = "Wir konnten mitverfolgen, wie die Eisenzwerge und ihre Konstrukte die Steinwesen, die Brann die Irdenen nennt, gemeinsam mit ihren verbündeten Riesen angriffen. Tretet mit ihm in Verbindung und helft ihm so gut Ihr nur könnt und vergesst nicht, dass alles, was Ihr von ihm und seiner Suche erfahren könnt, uns bei unserem Kampf gegen die Eisenzwerge und ihren Meister eine Hilfe sein könnte.", progress = "Habt Ihr die Scheibe zusammengefügt?", completion = "Das ging aber schnell! Nun, da wir die Scheibe haben, müssen wir herausfinden, wie wir zur ersten Hälfte des Archivschlüssels gelangen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12927] = {title = "Daten schürfen", objective = "Nutzt die Scheibe des Erfinders, um 7 versteckte Daten aus den Datenbanken zu beschaffen.", description = "Diese Scheibe, die Ihr zusammengebaut habt... sie ist leer! Bewahrer Mimir, der Tüftler, der diese Bibliothek errichtet hat, muss die Informationen irgendwo anders versteckt haben. Seht Euch in der Bibliothek des Erfinders um; sind dort irgendwelche Datenbanken?\n\nVielleicht ist das der Zweck dieser Scheibe. Versucht, sie in der Nähe einer dieser Datenbanken einzusetzen. Vielleicht kann man darauf die Informationen speichern. Meldet Euch erneut bei mir, wenn Ihr das ausprobiert habt, und lasst mich wissen, was Ihr herausfinden konntet. In der Zwischenzeit werde ich versuchen, die andere Hälfte des Archivschlüssels zu finden.", progress = "Habt Ihr die Scheibe ausprobiert? Was habt Ihr gefunden?", completion = "&lt;Brann sieht die Scheibe in Eurer Hand an.&gt;\n\nIch weiß nicht, ob darauf etwas gespeichert ist oder nicht! Ihr müsst mir sagen, was passiert ist.\n\n&lt;Ihr beschreibt den Datenbeschaffungsprozess.&gt;\n\nEs hat also funktioniert? Zumindest kann man sich darauf verlassen, dass Mimir systematisch vorgeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12928] = {title = "Norgannons Schale", objective = "Beschafft Euch Norgannons Schale von Archivar Mechaton.", description = "Scheibe des Erfinders wird aufgeladen.\n\nProzess abgeschlossen.\n\nNotfallprotokoll Gamma in Bearbeitung.\n\nLadevorgang von Notfallprotokoll abgeschlossen. Bitte zum Aktivieren von Archivar Mechaton, den Wächter von Norgannons Schale, aufgeladene Scheibe verwenden. Scheibe wird von Archivar Mechaton freigegeben, sobald Eure Identität verifiziert wurde.\n\nEuch ein angenehmes Jahrtausend.", progress = "Habt Ihr Norgannons Schale gefunden?", completion = "Das ist sie! Das ist die erste Hälfte von Norgannons Schlüsselstein. Gut gemacht, &lt;Name&gt;. Archäologe Andorin hat schon sehr lange nach Hinweisen darauf gesucht, wo diese Schale zu finden ist. Er wird mir nie glauben, dass stattdessen ein mutiger &lt;Volk&gt; sie gefunden hat.", rewards = "Gehärtete Ranke des RaufersKlinge des AnbeginnsBerührung des SchöpfersSchneide des SchöpfersDolch der MaidIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12929] = {title = "Die Irdenen von Ulduar", objective = "Sprecht mit Bergfels dem Steinformer in Bergfels' Zuflucht.", description = "Die Irdenen, die einst Ulduar bauten, bewohnten und verwalteten, wurden aus ihrem Zuhause vertrieben, als Loken die Stadt einnahm. Seitdem wurden die Verbannten von den Eisenzwergen ununterbrochen angegriffen.\n\nSie haben in einem alten Gebäude der Titanen an der Bergwand westlich der Bibliothek des Erfinders Zuflucht gefunden und ihm den Namen \"Bergfels' Zuflucht\" gegeben. Bergfels und seine Brüder kämpfen dagegen an, dass die Eisenzwerge ihren Zufluchtsort überrennen, doch sie können nicht mehr lange standhalten. Findet sie und helft ihnen, <Name>.", progress = nil, completion = "Ihr kennt also Brann Bronzebart, wie? Er ist unser engster Verbündeter unter denen, die aus Fleisch sind. Wir sind Blutsbrüder im Kampf mit Loken und seinen Anhängern, im Kampf um Ulduar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12930] = {title = "Seltene Erde", objective = "Baut mit der Spitzhacke der Irdenen 7 Klumpen verzauberte Erde ab. Bringt anschließend die Erde und 5 Einheiten Froststoff zu Bergfels dem Steinformer in Bergfels' Zuflucht.", description = "Es scheint schon so lange her zu sein, dass diese Hämmer Stein anstatt Eisen schlugen. Als wir aus Ulduar vertrieben wurden, mussten die schwächsten von uns sterben - die stärksten unserer Handwerker wurden zu Kriegern.\n\nDoch als die Eisenzwerge uns zurückschlugen, mussten selbst die Stärksten ihre Niederlage eingestehen.\n\nWir können nur wenig für die Verwundeten tun, außer uns stünde ein Vorrat an verzauberter Erde zur Verfügung. Einst bauten wir die Vorkommen an den steilen Klippen gen Nordwesten ab, aber der ständige Kampf hat uns davon abgehalten, unsere Vorräte wieder aufzufüllen. Würdet Ihr bitte helfen?", progress = "Habt Ihr ein bisschen Erde finden können?", completion = "Das wird uns erlauben, noch mehr der Gefallenen zusammenzuflicken. Im Namen aller Verteidiger der Zuflucht möchte ich Euch danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12931] = {title = "Zurückschlagen", objective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 10 sturmgeschmiedete Angreifer tötet und anschließend zu ihm zurückkehrt. Ihr könnt entweder sturmgeschmiedete Räuber oder Häscher töten.", description = "Die Verteidiger der Zuflucht haben ihr Bestes gegeben, um die Angriffe der Eisenzwerge abzuschwächen, doch wir müssen weiterhin Stück für Stück vor ihnen zurückweichen. Meine Männer sind zäh, aber nicht unermüdlich. Ohne Verstärkung ist es nur eine Frage der Zeit, bis wir überrannt werden.\n\nWürdet Ihr uns mit Eurem Können bei der Verteidigung der Zuflucht zur Seite stehen? Die Moral der Verteidiger würde dadurch erheblich gesteigert werden und ihnen, wie auch mir, Hoffnung auf einen Gegenschlag geben.\n\nTötet jeden der Sturmgeschmiedeten, der Euch außerhalb der Zuflucht über den Weg laufen sollte. Vernichtet auch ihre Kreationen.", progress = nil, completion = "Ihr habt den Verteidigern etwas gegeben, über das sie sich freuen können. Zu sehen, wie der Feind durch Eure Hand fällt, hat ihnen neue Kraft verliehen und ihren Mut gestärkt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12932] = {title = "Das Amphitheater der Agonie: Yggdras!", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Ich sag Euch mal was, <Freundchen/meine Gute>, zwischen diesem Ort hier und den rollenden Ebenen von Nagrand ist ein großer Unterschied. Die Trolle hier sind zwar dreckiger als Oger - aber sein wir doch mal ehrlich: Ich geh' dorthin, wo es Gold gibt! Seid also willkommen in Zul'Drak, <Kollege/Kollegin>.\n\nIhr macht das erste Mal bei diesem Spektakel mit - na, dann lasst mich Euch erstmal erzählen, was Sache ist. Ich bin der Kampfveranstalter und dieser quirlige Troll neben mir ist Wodin, mein Leibwächter. Ihr seid die Unterhaltung. Wenn Ihr kämpfen wollt, dann sagt mir Bescheid und ich werde einen Kampf für Euch organisieren.\n\nWenn Ihr bereit seid und eine Gruppe Leute mitgebracht habt, dann können wir anfangen! Was meint Ihr dazu?", progress = nil, completion = "Nicht schlecht, Herr Specht. Ihr könntet hier sogar ein wenig Gold machen - falls Ihr am Leben bleiben solltet, natürlich.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12933] = {title = "Das Amphitheater der Agonie: Magnataur!", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt Stinkbart! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Der nächste Kampf ist erste Sahne, <mein Freund/meine Beste>! Anscheinend will so ein Magnataur aus der Drachenöde ein Stück vom Kuchen abbekommen. Habt Ihr schon mal gegen einen von denen gekämpft? Alles, was ich Euch sagen kann, ist, hoch zu zielen!\n\nGebt mir ein Zeichen und wir bringen die Party ins Rollen.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Wow! Als ich Stinkbart zum ersten Mal gesehen hab, dachte ich, dass Ihr geliefert wärt! Gute Arbeit!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12934] = {title = "Das Amphitheater der Agonie: Aus einer anderen Welt!", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt einen der Elementarlords! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Ich werde Euch nicht belügen, <Kumpel/meine Dame>. Könnte sein, dass Ihr dem hier nicht gewachsen seid. Euer nächster Gegner kommt aus den Elementarebenen! Ich weiß nicht mal, was genau in der Arena auftauchen wird!\n\nHinein mit Euch, falls Ihr denkt, dass Ihr das schaffen könnt, und gebt ihnen Saures!", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Unglaublich! Als das Ding auftauchte, dachte ich zuerst, dass der ganze Laden hier in die Luft gehen würde! Ihr habt diese Runde wirklich dominiert!", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12935] = {title = "Das Amphitheater der Agonie: Tuskarrmageddon!", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt Orinoko Hauerbrecher! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Euer nächster Gegner hat eine fiese, schaurige Art zu kämpfen, <Kleiner/Kleine> - die Art zu kämpfen, die man nur drauf haben kann, wenn man einmal die Radieschen von unten gesehen hat. Er ist kampfeshungrig und wird alle Register ziehen, um zu gewinnen. Passt auf! Ich habe gehört, dass er zur Übung mit Yetis kämpft!\n\nWir fangen an, wenn Ihr bereit seid.", progress = nil, completion = "Ich hab' mir schon ein wenig Sorgen gemacht, &lt;Name&gt;. Als er die Seehunde und Pinguine auf Euch losgelassen hat... nun, da wusste ich nicht so recht, was ich davon halten sollte. Hat so ziemlich lächerlich ausgesehen.", rewards = "Ihr bekommt:\n\nRunenverzierter HeiltrankRunenverzierter ManatrankSchwerer FroststoffverbandAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12936] = {title = "Das Amphitheater der Agonie: Korrak der Blutrünstige!", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt Korrak den Blutrünstigen! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Ihr werdet das nicht glauben, <Klasse>. Euer nächster Kampf wird gegen Korrak den Blutrünstigen sein! Sieht so aus, als würden die Drakkaritrolle die Muskeln spielen lassen! Und lasst es mich Euch sagen: Er hat vom Saft der Tiergötter genippt. Er ist gut und dazu bereit, Euch in den Boden zu stampfen.\n\nSeid Ihr bereit?", progress = nil, completion = "Verdammt, ich kenne Korrak noch von ganz früher, als ich noch jünger war und für den Frostwolfklan arbeitete. Er konnte nie die Klappe halten! Ich denke, dass Ihr der Welt gerade einen großen Gefallen getan habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12937] = {title = "Unterstützung für die Gefallenen", objective = "Heilt mithilfe der Vulkanschlammpackung 8 gefallene Irdene Verteidiger und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", description = "Die Verteidiger der Zuflucht kämpfen tapfer, aber sie sind dem eisernen Ansturm einfach nicht gewachsen.\n\nAus der von Euch gesammelten Erde kann ich Bandagen anfertigen, die helfen werden, die Wunden einiger Gefallener zu heilen. Je mehr Verteidiger wir zusammenflicken können, umso länger werden wir hier draußen durchhalten.\n\nHier, nehmt diese Packungen und wendet sie auf die Wunden der gefallenen Verteidiger außerhalb der Zuflucht an. Bringt so viele in die Schlacht zurück, wie Ihr nur könnt, <Name>. Jeder Verlust ist ein Verlust zu viel.", progress = nil, completion = "Die Krieger, die Ihr geheilt habt, werden helfen, die Linie noch länger zu halten. Wenn wir die Bedrohung durch die Eisernen wirklich loswerden wollen, dann müssen wir einen Weg finden, sie hinter den Linien anzugreifen", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12938] = {title = "Der Herzog", objective = "Sprecht mit Herzog Lankral im Schattengewölbe.", description = "Wir brauchen Eure volle Konzentration, <Name>. Wir können das Schattengewölbe zurzeit kaum halten. Wie Ihr sehen könnt, haben wir den Lichkönig erfolgreich geärgert.\n\n<Der Baron kichert.>\n\nIch möchte, dass Ihr mit Herzog Lankral sprecht. Er hat hier jetzt das Kommando. Ihr findet ihn innerhalb des Gewölbes.\n\nWenn ich Ihr wäre, würde ich ihn nicht warten lassen.", progress = nil, completion = "Ich freue mich, Euch endlich kennenzulernen, &lt;Name&gt;. Wir schulden Euch viel, aber noch seid Ihr nicht fertig hier.\n\nEs gibt eine Vrykulstadt hinter den Bergen im Westen, die Jotunheim genannt wird.\n\nDie dortigen Vrykul stehen andauernd vor der Herausforderung 'aufzusteigen'. Die Gewinner gehen nach Ymirheim, um dem Lichkönig als dessen Elitekriegerkaste zu dienen, den Ymirjar, während die Verlierer zu Verseuchten Vargul reduziert werden.\n\nIhr werdet dafür sorgen, dass mehr Vargul als Ymirjar daraus hervorgehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12939] = {title = "Ehrenhafte Herausforderung", objective = "Herzog Lankral vom Schattengewölbe bittet Euch, die Herausforderungsflagge zu nutzen und 6 Mjordinkrieger zu besiegen.", description = "Der erste Schritt, den wir machen werden, findet an einem Ort in Jotunheim statt, den man Wilde Klippe nennt. Er liegt gleich hinter den Bergen im Westen.\n\nAuf der Klippe trainieren die Vrykul-Krieger und werden von den Männern ihres Thans in der hohen Kunst des Kampfes ausgebildet.\n\nIch möchte, dass Ihr diese Flagge nehmt und einige von ihnen herausfordert. Wir sollten sie mit 'simplen' Fähigkeiten demoralisieren, findet Ihr nicht, <Volk>?\n\n<Der Herzog grinst und seine verrotteten Zähne blitzen im trüben Licht des Gewölbes.>", progress = nil, completion = "Ich habe bereits von Euren Fortschritten auf der Wilden Klippe gehört. Großartig, &lt;Name&gt;... wirklich großartig!\n\n\n\nUnd nun ist es Zeit, einen Erlass an den Than aufzusetzen, dessen Vrykul Ihr derart leicht besiegen konntet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12940] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12941] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12942] = {title = "Reißt ihnen die schwarzen Schwingen aus", objective = "Iva die Rachsüchtige in Brunnhildar möchte, dass Ihr nach Valkyrion geht und 12 werdende Val'kyr erschlagt.", description = "Verräter. Wir Hyldnir können sie nicht leiden.\n\nDie Bewohner von Valkyrion sind schon viel zu lange ungeschoren davongekommen. Während wir Thorim treu geblieben sind, wurden sie zu Schoßhündchen des Lichkönigs!\n\nSie nennen diejenigen, die sein Geschenk empfangen haben, die Val'kyr. Sie fliegen mit gefiederten Flügeln, wie es Harpyien nun einmal so tun.\n\nIhr findet Valkyrion weit im Nordwesten hinter dem Tempel der Stürme. Erschlagt diese geflügelten Wölfinnen, Schwester. Erschlagt sie und ich werde Euch mit einem meiner wertvollsten Besitztümer belohnen.", progress = nil, completion = "Die Val'kyr sind lediglich die Schoßhündchen des Lichkönigs. Sie werden getötet werden, diese Miststücke. Sie haben ihre Wahl getroffen, nun müssen sie sich den Konsequenzen stellen.", rewards = "Fließende ValkyrionrobeSchmerzbringer der HyldnirProtodrachenbedeckungIvas StiefelGeschuppte ProtohandgelenksschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12943] = {title = "Erlass des Schattengewölbes", objective = "Herzog Lankral vom Schattengewölbe hat angeordnet, dass Ihr den Erlass des Schattengewölbes laut vor Than Ufrang dem Mächtigen vorlest und ihn dann tötet.", description = "Than Ufrang der Mächtige residiert in seiner Halle mit Blick über die Wilde Klippe. Ich habe ihn beobachtet. Der Than ist ein geduldiger Vrykul, der Sinn für Strategie und die Kriegsführung besitzt. Er hat außerdem eine Neigung dafür gezeigt, abzuwarten und es in der anhaltenden Schlacht nicht zu übertreiben.\n\nEr muss sterben!\n\nIch habe einen Erlass aufgesetzt. Stellt Euch vor den Than und lest ihn laut vor.\n\n<Der Herzog zieht amüsiert eine Augenbraue hoch.>\n\nDas sollte ihn... zumindest reizen.", progress = nil, completion = "&lt;Herzog Lankral nickt zustimmend, als Ihr ihm von Eurem Erfolg berichtet.&gt;\n\nWir haben es mit einem Gegner zu tun, der uns nicht nur körperlich, sondern auch zahlenmäßig zusetzt. Wenn wir den Kampf um Eiskrone gewinnen wollen, dann müssen wir ihn überlisten!\n\nUfrangs Tod verschafft uns in Jotunheim einen Vorteil. Sehen wir einmal, ob wir ihn nutzen können.", rewards = "Herzog Lankrals SeidenslipperWeste von JotunheimGeschwärzte Brustplatte des GewölbesHemmnis des ThansIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12944] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12945] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12946] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12947] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12948] = {title = "Der Champion der Agonie", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt Vladof den Metzger! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Das ist das Ende, <mein Freund/meine Beste>! Euer letzter Gegner wird Eure größte Herausforderung sein. Es handelt sich um einen Vrykulchampion von den eisigen Weiten des Eiskronengletschers und er will Blut sehen! Besiegt ihn und Ihr werdet zum Champion des Amphitheaters der Agonie gekrönt! Dieser Kampf wird uns beide reich machen!\n\nSagt mir Bescheid, wenn Ihr bereit seid, und wir fangen an.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Ihr habt es geschafft, &lt;Name&gt;! Das war der aufregendste Kampf, den ich bisher gesehen habe! Was werdet Ihr mit Euren Belohnungen machen? Was - ich? Ich werde zur Schattenseite in Dalaran gehen und dort alles verprassen. Da unten geht's heiß zu!", rewards = "Eisigerer StachelspeerEntwütete KriegsaxtKühler MatschschieberVerschraubter OberrepariererScharlachschädelspalterWodins zweitbestes MesserIhr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12949] = {title = "Besorgt den Schlüssel", objective = "Vaelen der Geschundene in Ufranggs Halle hat Euch gebeten, den Schlüssel zu Vaelens Ketten zu besorgen.", description = "<Klasse>, Instrukteur Hroegar da draußen hat sich den Schlüssel zu meinen Ketten um den Hals gehängt.\n\nVielleicht könntet Ihr ihn ja besorgen, indem Ihr einfach seinen Kopf von den Schultern trennt?", progress = "Habt Ihr ihn?", completion = "Vielen Dank, &lt;Volk&gt;. Gebt mir den Schlüssel einfach, ich helf' mir dann selber weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12950] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][12951] = {title = "Gebt dem Baron Bescheid", objective = "Sprecht mit Baron Splitter im Schattengewölbe.", description = "Ihr müsst jetzt unbedingt ins Schattengewölbe zurückkehren und Baron Splitter wissen lassen, dass ich versagt habe.\n\nWisst Ihr, diese Vrykul-Teufel haben nicht nur mich gefangen genommen, sondern auch mein ganzes Regiment aus Todesrittern.\n\nIch hätte die Falle erkennen müssen, bevor sie zuschnappte, aber was geschehen ist, ist nun mal geschehen.\n\nGeht nun, bevor sie Euch auch noch erwischen! Wir sehen uns dann im Gewölbe.", progress = nil, completion = "Was?! Wir können auf keinen einzigen Todesritter verzichten und erst recht nicht auf ein ganzes Regiment!!!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Shadow Vault: See Vaelen's Invisibility\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12952] = {title = "Edelsteine perfektionieren", objective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Carter Tiffens im Hafen der Vergeltung.", description = "Meine Fähigkeiten sind an diesem verflixten Ort zu nichts nütze. Ich habe nichts zu tun! Und dabei habe ich viele Jahre damit verbracht zu lernen, wie Edelsteine geschliffen werden müssen, damit sie eine perfekte Form erhalten. Ihr seht wie jemand aus, der mir ein paar Edelsteine finden könnte, und falls Ihr das für mich tätet, würde ich Euch im Gegenzug beibringen, wie man Edelsteine perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", progress = "Das dürfte reichen. Ich werde Euch beibringen, wie man einen Edelstein perfektioniert.", completion = "Das wird reichen müssen. Ich kann Euch beibringen, wie man die Kunst des Edelsteinschleifens perfektioniert. Außerdem werde ich Euch als Beweis für meine Fähigkeiten einen von meinen Edelsteinen geben.", rewards = "Ihr erlernt:\n\nEdelsteinperfektion\n\nDer folgende Zauber wird auf euch gewirkt:\n\nEdelsteinperfektion\n\nIhr bekommt außerdem:\n\nKleiner Samtbeutel"}
MultiLanguageQuestData['de'][12953] = {title = "Valkyrion muss brennen", objective = "Benutzt die Harpunenkanone von Valkyrion, um 6 trockene Heuhaufen anzuzünden.", description = "Die Kiste ist mit Brandharpunen gefüllt. Ihr könnt Euch erinnern, draußen Harpunenkanonen und trockene Heuhaufen gesehen zu haben.\n\nVielleicht wird Iva Euch für die zusätzliche Mühe belohnen.", progress = nil, completion = "Das nenne ich Engagement! Diese Verräterinnen mögen jetzt vielleicht eine neue Meisterin haben, doch sie werden niemals vergessen, mit welchem Geschenk sich ihre Schwester von ihnen verabschiedet hat.", rewards = "Krone des FlammenbringersWollstampferStahlkappenschneestiefelBrustschutz des ValkyrionfährtenlesersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12954] = {title = "Das Amphitheater der Agonie: Yggdras!", objective = "Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", description = "Hab mich schon gefragt, wann Ihr auftauchen würdet, <Name>! Jemanden hier zu haben, der einmal Champion des Rings des Blutes gewesen ist, wird ein Kassenschlager werden! Wir werden reich sein, <mein Freund/meine Beste>! REICH!\n\nWie dem auch sei, dieses Dreckloch nennt sich Zul'Drak. Die ganzen Eistrolle scheinen den Ort als Toilette zu benutzen. Ich weiß nicht, die ganze Gegend hier scheint mir nicht mehr ganz dicht zu sein, wenn Ihr mich fragt! Doch wen juckt's, stimmt's? Wir sind hier, um etwas Gold zu machen!\n\nIhr kennt ja die Leier, <Name>. Wenn Ihr bereit seid, dann lasst es mich wissen und die Show kann losgehen!", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Hey! Ich kenne Euch. Euer Sieg im Ring des Blutes war noch monatelang in aller Munde! Zu dumm nur, dass Ihr den Titel habt abgeben müssen, als Ihr nicht aufgetaucht seid, um ihn zu verteidigen! Wie gewonnen, so zerronnen, wie? Zumindest seid Ihr noch am Leben.", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12955] = {title = "Eliminiert die Konkurrenz", objective = "Der Springer beim Schattengewölbe möchte, dass Ihr Duelle austragt und Sigrid Eiskind, Efrem den Treuen, Onu'zun und Tinky Dochtpfiff besiegt.", description = "Hrchrmmm...\n\n<Der Springer räuspert sich.>\n\nEntschuldigung. Manchmal ist es schwer, mich zu verstehen. Ihr wisst ja, wie das ist.\n\nIch wollte sicherstellen, dass, wenn Ihr Euch an der Wilden Klippe hinter den Bergen im Westen wiederfindet, Ihr den dortigen Wettbewerb eliminiert.\n\nIm Besonderen würde ich es begrüßen, wenn Ihr Sigrid Eiskind, Efrem den Treuen, Onu'zun und Tinky Dochtpfiff zu Duellen herausfordern und sie vor den Augen der Vrykul demütigen würdet.", progress = nil, completion = "Das war sehr wichtig, &lt;Name&gt;. Indem Ihr sie verjagt habt, haltet Ihr sie auch davon ab, Euch bei dem, was auch immer Ihr dort unten zu erledigen habt, in die Quere kommen.", rewards = "Eiserner SargdeckelSigrids FäustlingeEfrems ArmschienenBrustplatte des GletscherkreuzzüglersStulpen von Onu'zunIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12956] = {title = "Ein Funken Hoffnung", objective = "Ihr sollt das veredelte glänzende Erz zu Thorim in den Tempel des Sturms bringen.", description = "Offensichtlich ist dies mehr als nur ein gewöhnliches Stück Metall.\n\nEs ist anders als jedes Erz, das Ihr kennt, hart und dabei keineswegs brüchig und es glüht selbst, wenn es kalt ist.\n\nBei näherer Betrachtung könnt Ihr erkennen, dass etwas durch die Oberfläche hindurchleuchtet. Es handelt sich um eine von Thorims Runen...", progress = "Was habt Ihr denn da, kleines Wesen?", completion = "Ihr bemerkt, wie sich Thorims düsterer Gesichtsausdruck aufhellt, als Ihr ihm das Erz zeigt.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12957] = {title = "Sklaven der Sturmgeschmiedeten", objective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 6 gefangene Mechagnome befreit und 3 sturmgeschmiedete Zuchtmeister tötet.", description = "Gen Südwesten an der westlichen Seite der Verschneiten Ebenen haben die Eisenzwerge eine Mine in einen Hügel gegraben. Für den Erzabbau verwenden sie dort gefangene Mechagnome, Hüter Mimirs Diener.\n\nIch weiß nicht, woher diese Mechagnome gekommen sind, und auch nicht, was sie mit ihrer Freiheit anstellen würden, doch vielleicht können wir sie für uns gewinnen.\n\nGeht zur Gefrorenen Mine, <Name>, und befreit diese Kreaturen aus ihrer Knechtschaft. Fragt sie, ob sie an unserer Seite in den Kampf gegen die tyrannischen Eisenzwerge ziehen möchten.", progress = nil, completion = "Ich hatte gehofft, dass sich mehr Gefangene uns anschließen würden, kann's ihnen jedoch nicht verübeln. Leute, die sich uns bereitwillig anschließen, sind Mangelware, und wir sind Euch dankbar, dass Ihr uns Euren Schwertarm geliehen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12958] = {title = "Lieferung: Blutrotes Nephritamulett", objective = "Kombiniert ein Vrykulamulett mit einem Nephrit und einem Blutstein, um ein blutrotes Nephritamulet herzustellen und es dann zu Jonas Timotheus in Dalaran zu bringen.\n\nVrykulamulette könnt Ihr von jedem Vrykul in Nordend erhalten.", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung Blutjadeamulette für den Verkauf in Lorenhall beantragt. Falls Ihr mir eins bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", progress = "Habt Ihr ein blutrotes Nephritamulett für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][12959] = {title = "Lieferung: leuchtende Elfenbeinfigur", objective = "Kombiniert Elfenbein aus Nordend mit einem Chalzedon und einem Schattenkristall, um eine leuchtende Elfenbeinfigur herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nElfenbein aus Nordend könnt Ihr von jedem Schaufelhauer oder Mammut in Nordend erhalten.", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung leuchtender Elfenbeinfiguren für den Verkauf in Lorenhall beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", progress = "Habt Ihr eine leuchtende Elfenbeinfigur für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][12960] = {title = "Lieferung: tückische Sonnenbrosche", objective = "Kombiniert eine eisenzwergische Brosche mit einem Riesencitrin und einem Sonnenkristall, um eine tückische Sonnenbrosche herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nEisenzwergische Broschen könnt Ihr von jedem Eisenzwerg in Nordend erhalten.", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung tückischer Sonnenbroschen für den Verkauf in Lorenhall beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", progress = "Habt Ihr eine tückische Sonnenbrosche für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][12961] = {title = "Lieferung: aufwändige Knochenfigur", objective = "Kombiniert einen Protodrachenknochen mit einem Sonnenkristall und einem Nephrit, um eine aufwändige Knochenfigur herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nProtodrachenknochen könnt Ihr von jedem Protodrachen in Nordend erhalten.", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung aufwändiger Knochenfiguren für den Verkauf in Lorenhall beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", progress = "Habt Ihr eine aufwändige Knochenfigur für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][12962] = {title = "Lieferung: helles Rüstungsrelikt", objective = "Kombiniert den Rest einer Elementarrüstung mit einem Blutstein und einem Riesencitrin, um ein helles Rüstungsrelikt herzustellen und es dann zu Jonas Timotheus in Dalaran zu bringen.\n\nDie Reste einer Elementarrüstung könnt Ihr von jedem Klagegeist in Nordend erhalten.", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung heller Rüstungsrelikte für den Verkauf in Lorenhall beantragt. Falls Ihr mir eins bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", progress = "Habt Ihr ein helles Rüstungsrelikt für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][12963] = {title = "Lieferung: unbeständige Sonnenkuriosität", objective = "Kombiniert eine Geißelkuriosität mit einem Sonnenkristall und einem Schattenkristall, um eine unbeständige Sonnenkuriosität herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nGeißelkuriositäten könnt Ihr von jedem Diener der Geißel in Nordend erhalten.", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung unbeständiger Sonnenkuriositäten für den Verkauf in Undermine beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", progress = "Habt Ihr eine unbeständige Sonnenkuriosität für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][12964] = {title = "Das dunkle Erz", objective = "Bringt 5 Erzproben zu Bergfels dem Steinformer in Bergfels' Zuflucht.", description = "Im westlichen Teil der Verschneiten Ebenen errichteten die Sturmgeschmiedeten Eisenzwerge die Gefrorene Mine; eine Mine, in der sie ausschließlich Sklaven schuften lassen.\n\nSie befindet sich weit hinter feindlichen Linien, weswegen wir nicht viel darüber herausfinden konnten, was dort drinnen vor sich geht. Meine Späher haben mir jedoch davon berichtet, dass sie Unmengen von blass-dunklem Erz aus der Mine schaffen.", progress = "Was habt Ihr über das Erz herausgefunden?", completion = "&lt;Bergfels streckt seine Hand nach dem Erz aus, schreckt dann jedoch zurück.&gt;\n\nDieses Erz... ich kann es nicht anfassen. Es brodelt regelrecht vor unnatürlicher Energie. Kein Steinwesen wird es bearbeiten können. Was wollen sie damit nur anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12965] = {title = "Lokens Gaben", objective = "Zerstört Lokens Wut, Lokens Kraft und Lokens Gunst und kehrt dann zu Bergfels dem Steinformer nach Bergfels' Zuflucht zurück.", description = "Der Eine, der die sturmgeschmiedeten Eisenzwerge befehligt, wird Runenseher Valduran genannt. Es heißt, sein Meister, Bewahrer Loken, der Ulduar übernommen hat, habe Valduran mächtige Titanenartefakte überlassen, die ich allerdings nie mit eigenen Augen gesehen habe.\n\nDas würde erklären, warum die Sturmgeschmiedeten Krieger laut meinen Männern derart stark und wild geworden sind.\n\nValdurans Basis Nidavelir liegt im Südwesten jenseits der Verschneiten Ebenen. Begebt Euch dorthin, <Name>, und neutralisiert seine Macht. Zerstört diese Gaben von Loken und helft uns, von der Stärke seiner Anhänger zu profitieren.", progress = nil, completion = "&lt;Bergfels nickt grimmig.&gt;\n\nIhr habt die Sturmgeschmiedeten stark geschwächt, aber sie werden weiterkämpfen. Ihre Verluste interessieren sie nicht, wohingegen mehr und mehr unserer Verteidiger fallen. Selbst wenn sie einhundert oder eintausend Gefallene zu beklagen haben, werden sie weiterkämpfen, bis sie uns zu Kies zermahlen haben.", rewards = "Gamaschen der erneuten HoffnungBergfels' MantelungEntschlossenheit des SteinformersAuf Euch wartet eine dieser Belohnungen:\n\nBergfels' Anhänger\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12966] = {title = "Ihr könnt ihn nicht verpassen", objective = "König Jokkum in Dun Niffelem möchte, dass Ihr zu Fjorns Amboss geht und Njormeld sucht.", description = "<Jokkum hört Euch geduldig zu, als Ihr ihm Eure Bitte schildert, und scheint gründlich darüber nachzudenken, bevor er Euch schließlich antwortet.>\n\nAlso Ihr seid es, bei dem wir uns für Fjorns Ableben bedanken müssen?\n\nEs mag vielleicht stimmen, dass Ihr uns in Zeiten der Not geholfen habt, doch es gibt noch immer viel zu tun, um die Beziehung zwischen Thorim und uns wieder ins Reine zu bringen.\n\nFürs Erste werde ich Njormeld erlauben, die Rüstung, die wir dem Sturmherren vor vielen, vielen Zeitaltern schenkten, neu zu schmieden. Betrachtet es als Bezahlung dafür, dass Ihr uns gegen Fjorn geholfen habt.\n\nNjormeld wurde entsandt, um Fjorns Amboss zurückzubringen. Ihr solltet ihn dort vorfinden können.", progress = nil, completion = "Thorims Rüstung neu schmieden? Es ist möglich.\n\nDoch zunächst wäre da noch die Sache mit dem Amboss...", rewards = nil}
MultiLanguageQuestData['de'][12967] = {title = "Kampf gegen die Elemente", objective = "Njormeld wünscht, dass Ihr Snorri zu Fjorns Amboss begleitet und ihm dabei helft, 10 wutentbrannte Klagegeister zu töten.", description = "Snorri war einst der Stolz unserer Nation. Viele Gegner mussten unter der Keule dieses großen Kriegers ihr Leben lassen.\n\nAuch wenn er nicht mehr das ist, was er einmal war, verehren wir ihn immer noch. Das Alter fordert seinen Tribut, trübt seine Sinne und raubt ihm die Kräfte. Dennoch hat er sich wie eh und je seinen Stolz bewahrt und lässt keine Gelegenheit aus, um sich in die Schlacht zu stürzen.\n\nWo wir schon bei Schlachten sind: Wir kühlen Fjorns Amboss, damit er nach Hause zurückgebracht werden kann. Die verbliebenen Feuerklagegeister leisten noch etwas Widerstand. Helft Snorri dabei, seine ruhmreichen Tage erneut zu durchleben, <Volk>. Führt ihn gegen diesen Gegner in die Schlacht.", progress = "Ist es Euch gelungen, Snorri zu einem weiteren Sieg zu führen, <Klasse>?", completion = "Das war eine ehrenwerte Leistung, &lt;Volk&gt;. Ich sollte dem König von Eurer Mithilfe berichten.\n\nDer Amboss ist fast ausreichend abgekühlt. Wir werden uns bald in Dun Niffelem wiedersehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKill Credit"}
MultiLanguageQuestData['de'][12968] = {title = "Yuldas Torheit", objective = "Iva die Rachsüchtige aus Brunnhildar möchte, das Ihr Yulda die Sturmwirkerin in Valkyrion tötet.", description = "Die Hexe, mit der alles angefangen hat, Yulda die Sturmwirkerin, ist in unser Dorf gekommen. Sie hat es gewagt, unsere noblen Traditionen zu beleidigen und die vergifteten Versprechungen des Lichkönigs von sich zu geben.\n\nSie hätte uns von einem Schwert durchbohrt wieder verlassen sollen, aber ihre Magie war zu stark und sie konnte entkommen.\n\nIhr findet sie im größten Gebäude in Valkyrion. Zeigt ihr, dass man sich mit uns lieber nicht anlegen sollte.", progress = nil, completion = "Yulda hatte es nicht anders verdient. Wer das Hildarthing beleidigt, kommt nicht ungeschoren davon; nicht einmal eine von uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12969] = {title = "Ist das Euer Goblin?", objective = "Fordert Agnetta Tyrsdottar heraus, um Zeev Zischelfunken zu retten. Kehrt ins Dorf Brunnhildar zu Lok'lira der Greisin zurück, wenn Ihr erfolgreich wart.", description = "Ich glaube, das ist der kleine grüne Freund, nach dem Ihr gesucht habt. An Eurer Stelle würde ich eingreifen, bevor diese Hyldnir ihn in zwei Hälften zerteilt.\n\nIhr seid während des Hildarthings eingetroffen, daher müssen alle Herausforderungen von den Teilnehmern angenommen werden. Nichts hält Euch davon ab, den Platz Eures grünen Freundes einzunehmen.", progress = "Ihr seid zurück.", completion = "Das habt Ihr gut gemacht. Wie es scheint, wurde unsere Abmachung für beide Seiten zufrieden stellend erfüllt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12970] = {title = "Das Hildarthing", objective = "Hört Euch den Vorschlag von Lok'lira der Greisin an.", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber durch den Sieg über Euren ersten Hyldnir habt Ihr Euch für das Hildarthing qualifiziert - den großen Kampf Hyldnir gegen Hyldnir, um festzustellen, wer an Thorims Seite herrschen wird.\n\nDas Hildarthing ist der Grund, warum man mich eingesperrt hat, denn ich wollte daran teilnehmen, obwohl ich viel zu alt und zu schwach bin, um den Hyldnir gewachsen zu sein.\n\nWenn Ihr interessiert seid, hätte ich einen Vorschlag für Euch.", progress = nil, completion = "Dann ist es abgemacht. Ihr werdet das Hildarthing beenden und mit meiner Hilfe dafür sorgen, dass Thorim seinen rechtmäßigen Platz zurückerhält.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12971] = {title = "Sich allen Herausforderern stellen", objective = "Lok'lira die Greisin in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt.", description = "Dann kommen wir mal in die Gänge. Die gute Nachricht ist, dass Ihr Euch durch Euren Sieg über Agnetta einen Platz in der nächsten Kampfrunde ergattert habt.\n\nDie schlechte Nachricht ist, dass all Eure Gegner auch jemanden in der ersten Runde besiegt haben - wird also kein Kinderspielchen.", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;. Ihr habt einige der stärksten Kämpferinnen besiegt, die das Volk der Hyldnir zu bieten hat.", rewards = "Kopfknacker der HyldnirKrone der HyldnirProtoschuppenhoseRunenwirkergewand der HyldnirIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12972] = {title = "Ihr werdet einen Bären brauchen", objective = "Sprecht mit Brijana, die sich außerhalb von Brunnhildar aufhält.", description = "In den ersten Runden des Hildarthings war Euch das Glück hold. Um weiterzukommen, braucht Ihr einen eigenen Kriegsbären.\n\nDummerweise geben die Hyldnir nicht einfach irgendwem ihre Bären, nein: Ihr müsst Euch erst in einem wahren Kampf als siegreich erweisen, nicht nur in einem Gladiatorenwettbewerb.\n\nDie Hyldnir von Brunnhildar sind momentan in eine Fehde gegen die Söhne Hodirs verwickelt, Thorims einstige Verbündete. Sprecht mit Brijana, die Ihr direkt außerhalb des Dorfes antreffen könnt, und fragt sie, wie Ihr helfen und Euch gleichzeitig beweisen könnt.", progress = nil, completion = "Denkt Ihr, wir würden Euch einfach so einen Bären geben? Ihr müsst Euch schon beweisen, bevor wir Euch irgendetwas überlassen.\n\nUnd werdet bloß nicht übermütig, nur weil Ihr beim Hildarthing einige Herausforderer besiegen konntet.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12973] = {title = "Die Gebrüder Bronzebart", objective = "Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung.", description = "Das war's! Wir haben endlich den Schlüsselstein... Er ist schön! Ich bin schon mehr als einmal um die ganze Welt gereist, aber wegen dieses Dings war ich wieder so aufgeregt wie ein kleines Kind. Allerdings dürfte jetzt wohl nicht der richtige Zeitpunkt sein, um durchzuatmen und den Stein zu bewundern. Wir müssen von hier verschwinden.\n\nSteigt auf meine Flugmaschine und sorgt für Deckung, damit wir bei unserer Flucht vor diesen Eisenzwergen geschützt sind!", progress = "Tut mir leid, Kamerad! Ich war so konzentriert, dass ich Euch gar nicht gesehen habe.", completion = "König Sturmherz möchte Euch seinen aufrichtigsten Dank dafür aussprechen, dass Ihr ihn und seine Brüder wieder zusammengebracht habt. Es scheint, als wäre er losgezogen, um eine Rechnung zu begleichen. Vielleicht werdet Ihr ihn vor Arthas' Türschwelle wiedertreffen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing der NordwindeGezacktes EisbandBernsteinglutsiegelEisgeschmiedeter Kampfring\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12974] = {title = "Ruf des Champions!", objective = "Sucht Gurgthock im Amphitheater der Agonie in Zul'Drak auf.", description = "Pff, was hier unten vor sich geht, hat nichts mit Kämpfen zu tun. Es sind ein paar Leute, die um eine Flagge herumtanzen, mehr nicht.\n\nSucht Ihr nach einem echten Kampf? Denn, falls dem so ist, dann habe ich hier die besten Karten weit und breit.\n\nHabt Ihr schon mal von Gurgthock und Wodin gehört? Dem Goblin und dem Troll, die den Ring des Blutes in der Scherbenwelt geleitet haben? Nun, sie sind jetzt hier in Nordend und haben drüben in Zul'Drak einen komplett neuen Kampfring eröffnet. Falls Ihr Interesse haben solltet, dann geht nach Zul'Drak östlich des Kristallsangwalds. Ihr findet sie in der großen Arena im Zentrum. Sagt ihnen, dass Schufti Vickers Euch schickt!", progress = nil, completion = "Schufti hat Euch geschickt, wie?", rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][12975] = {title = "In Gedenken an", objective = "König Jokkum in Dun Niffelem wünscht, dass Ihr nach Donnerfall geht und 8 Hornfragmente einsammelt.", description = "Mit Sicherheit hat Thorim Euch von der Tragödie erzählt, die uns trennt.\n\nIn Donnerfall, nordöstlich von hier, haben die Dinge ihren Lauf genommen. Die gefrorenen Fossilen dort erinnern an den schwarzen Tag, ebenso wie die Geister, die jenen Ort heimsuchen.\n\nDamit mein Volk Thorim vergeben kann, muss der Ort ein anderes Aussehen erhalten. Ein Denkmal muss errichtet werden, damit unsere Herzen wieder Frieden finden.\n\nBegebt Euch dorthin, <Volk>. Sammelt die Teile von Hodirs Horn ein, das an jenem Tag zertrümmert wurde.", progress = "Konntet Ihr die Teile von Hodirs Horn finden?", completion = "Eine weitere gute Tat, die Ihr für Thorim vollbracht habt, &lt;Klasse&gt;.\n\nDas wird dazu beitragen, dass die Herzen meines Volkes gegenüber Thorim milde gestimmt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12976] = {title = "Ein Monument für die Gefallenen", objective = "König Jokkum wünscht, dass Ihr Hodirs Hornfragmente zu Njormeld in Dun Niffelem bringt.", description = "Bringt diese Teile zu Njormeld. Er wird die einzelnen Teile dieses heiligen Relikts für den Bau eines mächtigen Monuments verwenden.\n\nMöge es die Schmerzen lindern und die Wunden verheilen lassen, die mein Volk in diesen vielen Jahren auf sich nehmen musste.\n\nMöge seine Gegenwart dabei helfen, ein neues Zeitalter herbeizuführen, in dem wir erneut glorreiche Schlachten an Thorims Seite führen werden.\n\nGeht jetzt, <Klasse>. Njormeld erwartet Euch.", progress = "Habt Ihr Hodirs Hornfragmente dabei, <Volk>?", completion = "&lt;Njormelds Augen beginnen sichtlich zu glänzen, als er den Inhalt des Beutels auf dem Amboss entleert.&gt;\n\nHodirs Horn...\n\nEs handelt sich dabei um ein heiliges Geschenk an unser Volk von Hodir höchstpersönlich, &lt;Volk&gt;. Es ist für uns ein Relikt von größter Wichtigkeit.\n\nWenn Ihr das nächste Mal in unsere Feste zurückkehrt, werdet Ihr die Früchte Eurer Arbeit zu Gesicht bekommen.\n\nLebt wohl.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12977] = {title = "Hodirs Ruf", objective = "Lasst Hodirs Horn bei 5 Vorfahren der Niffelem und 5 ruhelosen Frosterben in Donnerfall erklingen.", description = "Ihr habt den Riesen von Dun Niffelem einen großen Dienst erwiesen. Ohne Euch würde dieses Monument nicht mehr existieren.\n\nWährend Ihr schweigend über dessen Bedeutung nachdenkt, überfluten Emotionen Euer Herz. Die Gefühle überschwemmen Euren Geist mit Gedanken und Bildern... und auch einem Gefühl der Dringlichkeit.\n\nDie Empfindungen verblassen und hinterlassen in Euch das Gefühl, dass Ihr wisst, was zu tun ist. Die ruhelosen Geister am Donnerfall müssen vernichtet werden.\n\nAls Ihr aufbrecht, stellt Ihr fest, dass Ihr ein astrales Horn in den Händen haltet.", progress = "Ein heftiger Wind wirbelt um das Horn herum. Sein Klang hallt von den umgebenden Bergen wieder.\n\nFür jemanden, der dies nicht weiß, würde es so aussehen, als bliese das Horn sich selbst...", completion = "Ein Gefühl der Ruhe und Zufriedenheit erfüllt Euch nun, und Ihr wisst, dass die einst gequälten Geister des Donnerfalls nun in Frieden ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12978] = {title = "Im Angesicht des Sturms", objective = "Bruor Eisenbann in Bergfels' Zuflucht bittet Euch, 10 Sturmgeschmiedete in Nidavelir zu töten. Tötet Sturmgeschmiedete Champions, Sturmgeschmiedete Magier oder Sturmgeschmiedete Kriegsgolems.", description = "Wie Bergfels habe auch ich einst den Hütern als Handwerker in Ulduar gedient, aber nach Lokens Verrat habe ich meinen Hammer gegen unsere neuen Gegner erhoben.\n\nWenn wir genug Mann abstellen konnten, habe ich Überfälle gegen Nidavelir angeführt, um den Druck auf unsere Verteidiger zu verringern. Allerdings stehen unsere Linien kurz vor dem Zusammenbruch.\n\nIhr habt Euch als fähiger Kämpfer und loyaler Verbündeter erwiesen. Vielleicht würdet Ihr ja unter unserem Banner den Kampf gegen Nidavelir aufnehmen - die Feste der Eisenzwerge im Südwesten auf der anderen Seite der verschneiten Ebene.", progress = nil, completion = "Vielleicht gibt es noch Hoffnung auf den Sieg, &lt;Name&gt;. Es ist uns nie gelungen, einen Angriff auf die Sturmgeschmiedeten aufrecht zu erhalten, aber mit Euren Bestrebungen könnte Valduran dennoch fallen!", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12979] = {title = "Rüstung der Dunkelheit", objective = "Bringt 4 Dunkle Rüstungen zu Bruor Eisenbann in Bergfels' Zuflucht.", description = "Diese Rüstungsplatte ist im Vergleich zum Rest der Verteidigung des Golems dick und übergroß. Eine schnelle Untersuchung seines Leichnams hat ergeben, dass diese schwerere Platte nachträglich angebracht wurde, vielleicht als unausgegorene Aufrüstung.\n\nWarum haben die Eisenzwerge diese überflüssige und nicht passende Rüstung an ihren Kriegsgolems anbringen lassen?\n\nVielleicht hätte Bruor Eisenbann eine Idee, wenn er die Gelegenheit bekäme, einige dieser Platten von den Sturmgeschmiedeten Kriegsgolems zu untersuchen.", progress = "Was habt Ihr da?", completion = "Seid vorsichtig. Haltet diese Platte so weit wie möglich von mir fern. Selbst wenn man nur in ihrer Nähe ist, erleidet man Schmerzen.\n\nAber Ihr habt Recht, &lt;Name&gt;, das sind riesige Rüstungsplatten für einen Kriegsgolem normaler Größe. Was würden die Sturmgeschmiedeten nur mit ihnen vorhaben? Es gibt nur einen Weg, das herauszufinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12980] = {title = "Die Geheimnisse der Rüstung", objective = "Bringt die dunkle Plattenrüstung zu Mimirs Werkstatt und bittet Tock den Knecht, sie sich näher anzusehen. Kehrt zu Bruor Eisenbann in Bergfels' Zuflucht zurück, wenn Ihr fertig seid.", description = "Seltsam, dass diese Plattenrüstung hier ist, doch wir müssen versuchen, so viel wie möglich mit ihrer Hilfe herauszufinden. Sie könnte Teil eines von Valdurans Plänen sein.\n\nEr hat ziemlich viel Zeit und Kraft darin investiert, das Erz für dieses Metall zu schürfen, es zu veredeln, das Metall zu schmieden und es auszutesten.\n\nAn der nördlichen Bergwand gen Osten befindet sich ein Gebäude namens Mimirs Werkstatt. Es ist schon seit langer Zeit nicht mehr in Gebrauch, doch wenn wir Glück haben, funktionieren ein paar von den Knechten noch. Bringt Eure Plattenrüstung dorthin und versucht, so viel wie möglich herauszufinden.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Bruor lauscht Eurem Bericht über das, was Ihr in der Werkstatt herausgefunden habt.&gt;\n\nValdurans Meister hat ihm also dieses unheimliche Metall gegeben, um damit die riesige Waffe zu bauen? Das muss es sein, was er für seinen letzten Schlag gegen uns einsetzen will! Wir müssen ihn aufhalten, bevor er die Waffe fertigbauen und einsetzen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12981] = {title = "Heiß und kalt", objective = "\nIhr sollt zum Frostfeldsee gehen, die zerbrechlichen Klagegeister dort vernichten und die Essenz des Eises auf den qualmenden Schrott bei Fjorns Amboss anwenden. Anschließend sollt Ihr 6 Trümmer gefrorenen Eisenschrotts sammeln und zu Fjorns Amboss in Dun Niffelem zurückkehren.", description = "Ihr starrt den Amboss an und vor Eurem innerem Auge spielen sich wieder die Szenen Eurer kürzlichen Errungenschaften ab; ganz besonders jene, die geholfen haben, dieses Artefakt hierherzubringen.\n\nEs fällt Euch ein, dass noch mehr getan werden muss. Im Osten verstreut liegt qualmender Schrott herum, Schrapnelle der einst dort gefochtenen Schlacht.\n\nKönnte man ihn auf irgendeine Art und Weise kühlen und einsammeln, stünde den Frostriesen mehr als genug Metall zur Verfügung und in der Region würden keine Kriegsüberbleibsel mehr herumliegen.", progress = "Der Amboss wird von einem strahlenden blauen Schein umgeben.", completion = "Ihr habt das Gefühl, etwas erreicht zu haben, als Ihr erkennt, dass durch Euer Handeln die wiedererweckten Bande zwischen Thorim und den Söhnen Hodirs weiter gestärkt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12982] = {title = "Gefangene der Schwarzen Klinge", objective = "Vaelen der Geschundene im Schattengewölbe bittet Euch, 8 Gefangene der Schwarzen Klinge zu befreien. Ihr findet sie in den Käfigen in der weiteren Umgebung von Jotunheim.", description = "Jetzt, da ich zurück bin, wird der Baron sicher wollen, dass ich meine Männer zurückhole. Wie ich sehe, können wir uns hier kaum halten. Die Streitkräfte des Lichkönigs sind im Begriff durchzubrechen und ohne meine gefangenen Todesritter werden wir nicht durchhalten.\n\nKönnt Ihr mir ein weiteres Mal beistehen, <Name>?\n\nGeht zurück nach Jotunheim und befreit sie aus diesen Käfigen. Macht diese verdammten Schlösser auf. Wie, spielt für mich keine Rolle. Die Vrykul sind höchstwahrscheinlich im Besitz der Schlüssel.\n\nBefreit einfach nur meine Männer!", progress = nil, completion = "Mein Dank ist Euch gewiss, &lt;Klasse&gt;. Mit den von Euch befreiten Todesrittern werden wir die Stellung halten können... vorerst.", rewards = "Ebenholzfarbene SchulterstückeSchattengewölbegugelHandschuhe des GeschundenenVerbund des SchlachtheilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12983] = {title = "Die Letzte ihrer Art", objective = "Astrid Björnrittar in Brunnhildar wünscht, dass Ihr eine Eisschlundmatriarchin aus der Überwinterungshöhle rettet.", description = "Solange ich zurückdenken kann, waren unsere besten Bären die aus der Überwinterungshöhle im Osten.\n\nDiese Zeiten könnten nun endgültig vorbei sein. Die Höhle wurde von gefräßigen Jormungar überrannt und fast alle wilden Bären wurden dabei getötet.\n\nWenn Ihr jedoch eine überlebende Matriarchin finden könntet, verspreche ich Euch, dass sie besser kämpfen wird als irgendeiner von diesen Bären, die in Gefangenschaft geboren wurden.\n\nBringt diesen Harnisch zur Überwinterungshöhle und rettet eine überlebende Matriarchin. Viel Glück bei der Suche.", progress = nil, completion = "Ich bin beeindruckt. Ich hätte nicht gedacht, dass ich jemals wieder eine Eisschlundmatriarchin zu Gesicht bekommen würde - besonders nicht in dieser Größe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12984] = {title = "Valduran der Sturmgeborene", objective = "Benutzt Bergfels' Kriegshorn, sobald Ihr Valduran den Sturmgeborenen gefunden habt. Besiegt ihn und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", description = "Wir haben keine Wahl, <Name>. Das, was Ihr in Mimirs Werkstatt herausgefunden habt, bedeutet, dass wir handeln müssen, bevor Valduran seine Waffe fertigbauen und einsetzen kann.\n\nSelbst in diesem Moment erkämpfen uns die Verteidiger der Zuflucht Zeit, damit wir uns um Valduran den Sturmgeborenen kümmern können.\n\nIhr müsst nach Nidavelir jenseits der südlich gelegenen Verschneiten Ebenen gehen, Valduran finden und ihm entgegentreten. Doch Ihr werdet nicht alleine sein. Nehmt dieses Kriegshorn mit Euch und lasst es erschallen, bevor Ihr Euch dem Anführer unserer Feinde stellt. Bruor und ich werden Euch bei diesem Kampf zur Seite stehen.", progress = nil, completion = "Valduran ist endlich tot und die Sturmgeschmiedeten geschwächt; doch falls etwas Wahres an seiner Prahlerei dran sein sollte, dann müssen wir die Chance nutzen und die Sturmgeschmiedeten bekämpfen, jetzt, da er nicht mehr da ist. Die Waffe, die sie bauen, könnte unser Ende sein.", rewards = "Blutige LederhandschuheGürtel der SturmgeschmiedetenSteinformstampferAuf Euch wartet eine dieser Belohnungen:\n\nLaterne der Zauberflamme\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12985] = {title = "Einen Kopf schmieden", objective = "Njormeld in Dun Niffelem möchte, dass Ihr mithilfe der Hacke mit Diamantspitze 8 Sturmgeschmiedete Augen von den toten Eisenriesen auf dem Frostfeldsee beschafft und dann anschließend zu ihm zurückkehrt.", description = "Grüße, <Volk>.\n\nIch habe eine Aufgabe, für die König Jokkum Euch geeignet hält, falls Ihr noch immer unsere Gunst gewinnen wollt.\n\nIch habe Pläne für ein anderes Artefakt entwickelt; eines, das unserer Festung Hodirs Segen des Schutzes gewähren wird. Ich habe fast alles, was ich zum Bau benötige. Das Einzige, was noch fehlt, sind die Augen, ja, die Augen unserer gefallenen Feinde.\n\nHier, nehmt dieses Werkzeug und löst mit ihm die Augen der toten Eisenriesen heraus, die überall auf unseren Feldern verstreut herumliegen.", progress = "Habt Ihr die letzten benötigten Komponenten mitgebracht, <Volk>?", completion = "Es ist fast vollbracht.\n\nMit diesem Artefakt wird Dun Niffelem vor kommenden Gefahren gewarnt werden, bevor sie hier auftauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12986] = {title = "Das Schicksal der Titanen", objective = "Creteus in den Fußmarschen möchte, dass Ihr zum Tempel des Erfindungsreichtums, Tempel des Winters, Tempel des Lebens und zum Tempel der Ordnung reist und mithilfe der Datenbank jeden Bereich untersucht.", description = "Norgannons Kern befindet sich nicht an diesem Ort, und ich bin mir nicht sicher, warum Ihr danach sucht, <Volk>. Ebenso unsicher bin ich mir darüber, ob Ihr wirklich wisst, welchen Nutzen der Gegenstand hat, nach dem Ihr sucht.\n\nIch möchte, dass Ihr mir helft, bevor ich darüber nachdenke, Euch meine Hilfe anzubieten. Vor Kurzem habe ich etwas über den Behüter Thorim erfahren. Seine Machtposition wird ihm streitig gemacht und sein weiteres Schicksal steht in den Sternen. Das beunruhigt mich, weil ich nichts über die anderen Behüter weiß. Macht Euch diese Datenbank zu Nutze, um ihre Tempel gen Nordosten zu durchsuchen, und setzt mich über das Ergebnis in Kenntnis.", progress = "Seid Ihr mit den Informationen zurückgekehrt, um die ich Euch gebeten habe, <Volk>?", completion = "Die Neuigkeiten, die Ihr mir überbringt, wiegen in der Tat schwer. Das Schicksal der verbliebenen Behüter ist ungewiss, aber ihre Abwesenheit verheißt für alle Länder Azeroths nichts Gutes.\n\nIch muss Eure Informationen aus der Datenbank auswerten und versuchen, mir einen Überblick über die Lage zu verschaffen. Ich glaube, ich bin im Besitz von Informationen, die für Euch im Augenblick wichtiger sind. Daher werde ich Euch zuerst an den besagten Informationen teilhaben lassen.", rewards = "EiskletterstiefelManschetten des ErfindungsreichtumsMantelung des langen WintersAuf Euch wartet eine dieser Belohnungen:\n\nRing der Ordnung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][12987] = {title = "Hodirs Helm platzieren", objective = "Njormeld möchte, dass Ihr zur Spitze der nördlich gelegenen Eisspitze in Dun Niffelem fliegt und die Worte auf den Tafeln der Verkündung rezitiert.", description = "Der Helm wurde geschmiedet.\n\nEure Mühen sind nicht unbemerkt geblieben, kleines Wesen. Es gibt zwar noch viel zu tun, doch wir, die Söhne Hodirs, sind Euch dankbar für das, was Ihr erreicht habt.\n\nIm Gegenzug biete ich Euch die Möglichkeit, unserem König und unseren Brüdern Hodirs Helm zu präsentieren.\n\nFliegt zur glitzernden Spitze des kleinen Eisstachels vor mir und rezitiert für mein Volk die Worte auf dieser Tafel.\n\nGenießt dieses Privileg, <Klasse>. Niemals zuvor wurde einem Außenstehenden solch eine Ehre gewährt.", progress = "Habt Ihr Hodirs Helm schon platziert, <Volk>?", completion = "&lt;Njormeld richtet seinen Blick hoch auf Hodirs Helm und ist sichtlich bewegt.&gt;\n\nDas genügt, kleiner &lt;Volk&gt;.\n\nDas genügt...", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][12988] = {title = "Sabotiert die Schmieden!", objective = "Sabotiert die Nordblitzschmiede, die Zentralblitzschmiede und die Südblitzschmiede mit Bergfels' Bomben. Kehrt dann zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", description = "In meiner Torheit dachte ich, dass Valdurans Projekt in Narvirs Wiege - ein großes Baugebiet im Süden - nichts weiter sei als ein groteskes Monument für \"Hüter\" Lokens Grausamkeit.\n\nJetzt kennen wir die Wahrheit: Es sollte als Waffe gegen uns und die Allianz dienen. Wir dürfen nicht zulassen, dass dieser Eisenkoloss fertiggestellt wird, <Name>, da dies das Ende der Zuflucht bedeuten würde.\n\nBegebt Euch zu Narvirs Wiege, findet die von den sturmgeschmiedeten Handwerkern genutzten Blitzschmieden und sabotiert sie.", progress = nil, completion = "Ausgezeichnete Arbeit! Zwar wird das die Eisenzwerge nicht aufhalten, aber es wird sie wertvolle Zeit kosten, diese Schmieden wieder aufzubauen. Ich wage zu behaupten, dass wir nun im Vorteil sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12989] = {title = "Die schleimige Dunkelheit", objective = "Astrid Björnrittar wünscht, dass Ihr 8 gefräßige Jormungar in der Überwinterungshöhle östlich des Dorfes Brunnhildar tötet.", description = "Die niederträchtigen Jormungar haben den größten Teil der Überwinterungshöhle eingenommen. Widerwärtige Kreaturen... Kinder von Loken, Thorims verfluchtem Bruder.\n\nAls Thorims Untertanen sind wir es uns schuldig, diesen Abschaum zu töten, wo auch immer er uns unterkommt. Ihr findet die Höhle gleich östlich von hier, außerhalb des Dorfes.", progress = nil, completion = "Die Jormungar sind abscheuliche Kreaturen. Ihr tatet gut daran, sie zu töten.", rewards = "JormungargaloschenJormungarfangzahnBrustschutz des WinterschlafsBjörnrittars kühle GamaschenGeschuppter JormungarbeschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12990] = {title = "Das Wurmloch", objective = "Bringt Jonathan LeCraft die gesuchten Materialien, um einen schnellen Tod zu vermeiden, und erhaltet einen coolen neuen Zauberspruch.", description = "Bringt mir die Materialien und ich werde Euch zeigen, wie Euer Wurmlochgenerator funktioniert.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nWurmloch: Gadgetzan"}
MultiLanguageQuestData['de'][12991] = {title = "Sie treffen, wo es wehtut", objective = "Tötet 10 Sturmgeschmiedete Konstrukteure und kehrt zu Bruor Eisenbann in Bergfels' Zuflucht zurück.", description = "Bergfels hat vor, die Pläne der Eisenzwerge in Narvirs Wiege zu durchkreuzen, und ich habe mir dazu auch so meine Gedanken gemacht. Die Arbeit am Eisenkoloss würde ohne Fachleute zum Erliegen kommen.\n\nNarvirs Wiege liegt auf der Südseite des Hügels, der Bergfels' Zuflucht überragt. Geht dorthin und vernichtet alle sturmgeschmiedeten Konstrukteure, die Euch über den Weg laufen. Zwar sind sie nicht anders, als wir früher gewesen sind, aber sie bauen eine Waffe, die eine Gefahr für uns alle darstellt.", progress = nil, completion = "Früher hätte ich niemanden um das bitten können, was Ihr getan habt, aber meine Erlebnisse mit den Eisenzwergen haben diese Gefühle erstickt. So haben wir sichergestellt, dass der Feind nicht allzu bald vorrücken kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12992] = {title = "Tötet die Vrykul!", objective = "Ekel im Schattengewölbe möchte, dass Ihr 15 beliebige Vrykul in der weiteren Umgebung von Jotunheim tötet.", description = "Die Vrykul in Jotunheim müssen plattgemacht werden!\n\nUnd zwar richtig platt, <Name>!", progress = nil, completion = "&lt;Name&gt; ist mein bester, kleiner &lt;Volk&gt;!", rewards = "VrykulzermalmerEkels SchürhakenSchmiedeeisenstabBogen aus Knochen und SehnenEkels hässlicher StockIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][12993] = {title = "Eine kolossale Bedrohung", objective = "Gelangt an die Informationen über die Angriffs- und Verteidigungsfähigkeiten des Kolosses und bringt sie zu Bergfels dem Steinformer in Bergfels' Zuflucht.", description = "Ihr habt Großes geleistet, als Ihr die Arbeiten beim Bau des Eisenkolosses verzögert habt. Allerdings fürchte ich, dass wir die Sturmgeschmiedeten dadurch nur noch entschlossener gemacht haben, den Bau ihrer Waffe zu vollenden.\n\nSelbst jetzt schicken sie immer noch neue Arbeiter und die Aufseher treiben sie an ihr Äußerstes. Am Ende können wir vielleicht nicht verhindern, dass sie den Koloss erwecken. Kehrt zurück zu Narvirs Wiege im Süden und findet die Dokumente, die mehr über die offensiven und defensiven Fähigkeiten des Kolosses verraten könnten. Sie sollten sich in der Nähe der Zelte und Schmieden auf der niedrigsten Ebene befinden.", progress = "Konntet Ihr die Dokumente finden, nach denen wir suchen?", completion = "&lt;Bergfels wirft mit großen Augen einen Blick auf die Dokumente.&gt;\n\nIch hätte niemals gedacht, dass die so etwas zustande bringen können! Unsere Männer werden gegen dieses Ungetüm keine Chance haben, wenn es erst einmal fertiggestellt ist. Glücklicherweise fehlt ihnen scheinbar noch eine wichtige Komponente.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12994] = {title = "Jagd auf Spione", objective = "Ihr müsst 3 Sturmgeschmiedete Spitzel im Uralten Wintertal besiegen.\n\nVerwendet den Fangzahn eines astralen Worgs bei der Leiche des gefallenen Worgs und beschwört damit einen astralen Frostworg, mit dessen Hilfe Ihr versteckte Feinde entlarven könnt. Wenn das Tal von den Spionen befreit wurde, sollt Ihr zur Frostworghöhlenmutter in Dun Niffelem zurückkehren.", description = "Eure aufkeimende Beziehung zu den Einwohnern von Dun Niffelem hat zu einigen unerwarteten Entdeckungen geführt.\n\nBeispielsweise seid Ihr nun aus irgendeinem Grund in der Lage, das gutturale Knurren und die Scherze der Höhlenmutter zu verstehen, zumindest bildet Ihr Euch das ein.\n\nOffenbar spürt sie die Gefahr außerhalb der Feste und möchte, dass Ihr deswegen etwas unternehmt.\n\nMit der Vorderpfote streift sie sich die Kette vom Hals und legt sie Euch zu Füßen. Als Ihr sie aufhebt, bemerkt Ihr, dass ein Reißzahn daran befestigt ist...", progress = "Die Frostworghöhlenmutter sieht Euch neugierig an.", completion = "Als Ihr der Höhlenmutter die Kette wieder um den Hals legt, leckt sie Euer Gesicht wohlwollend ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12995] = {title = "Setzt ein Zeichen", objective = "Baron Splitter im Schattengewölbe wünscht, dass Ihr 15 Banner der Schwarzen Klinge in die Nähe der Vrykulleichen steckt, die Ihr in der weiteren Umgebung von Jotunheim findet.", description = "Wir müssen den Vrykul von Jotunheim auf vielerlei Arten begegnen. Pure Gewalt ist natürlich angebracht, aber ich bevorzuge eine intelligentere Herangehensweise.\n\nIch möchte, dass Ihr sie zermürbt.\n\nMeine Männer haben einige Banner für Euch angefertigt. Nehmt sie und rammt sie in den Boden neben den Leichen gefallener Vrykul.\n\nLasst die Banner zu einer dauerhaften Mahnung gereichen, dass sie einer akuteren Bedrohung gegenüberstehen als dem Zorn des Lichkönigs.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Mögen sie die geschändeten Leichen ihrer gefallenen Kameraden erblicken und es sich lieber zwei Mal überlegen, uns anzugreifen!\n\nWenn Ihr morgen wieder kommt, werde ich dafür Sorge tragen, dass weitere Banner für Euch bereitstehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12996] = {title = "Das Aufwärmen", objective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr die Zügel der Kriegsbärenmatriarchin nutzt, um Kirgaraak zu besiegen.", description = "Ihr hattet großes Glück, Schwester. Dies ist eine Matriarchin, wie wir sie seit Jahren nicht mehr gesehen haben.\n\nEin guter Bär würde Euch nicht viel bringen, wenn Ihr nicht auf ihm reiten könnt.\n\nIch werde Euch auf Kirgaraak einiges zeigen. Er ist der größte Yeti, den wir je fangen konnten, also seid lieber vorsichtig. Und geht ruhig weg, wenn er Euch verprügeln will... denn wir halten ihn aus gutem Grund an einer Kette.", progress = "Wie ist es mit dem Yeti gelaufen?", completion = "Nicht übel. Ich hatte gehofft, dass Euch Kirgaraak den Hals bricht, damit ich Euren Bären behalten kann.\n\nDas war bloß ein Scherz, Schwester. Nun... zumindest teilweise. Ihr habt da einen wirklich schönen Bären.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12997] = {title = "In die Grube", objective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Kriegsbärenmatriarchin 6 Kriegsbären des Hildarthings besiegt.", description = "Einen angebundenen Gegner zu bezwingen, ist eine Sache; gegen ebenbürtige Bärenreiter zu kämpfen, eine andere.\n\nBegebt Euch in die Reißzahngrube und wendet das an, was Ihr gelernt habt, um Eure Gegner zu besiegen. Viel Glück, Schwester.\n\nRuhm erwartet Euch, falls Ihr siegen solltet.", progress = "Seid gegrüßt, Schwester.", completion = "Ihr habt es wirklich geschafft! Und Ihr seid bei bester Gesundheit. Wenn man von der Bärin doch nur dasselbe sagen könnte.\n\nEs wird eine Weile dauern, bis sie sich wieder erholt hat. Zum Glück werdet Ihr sie vorerst nicht brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12998] = {title = "Das Herz des Sturms", objective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr nach Uldis reist und versucht, Aufseher Narvir daran zu hindern, an das Herz des Sturms zu gelangen.", description = "Laut den Dokumenten, die Ihr aus Narvirs Wiege erbeuten konntet, ist der Eisenkoloss fast fertiggestellt. Es fehlt nur noch ein wichtiger Bestandteil - das Herz des Sturms.\n\nOhne diese Komponente wären die Waffen des Eisenkolosses weitaus schwächer als im Konzept dieses Ungetüms vorgesehen. Wenn wir Aufseher Narvir daran hindern, an das Herz zu gelangen, können wir den Koloss vielleicht besiegen!\n\nNotizen auf dem Dokument, das Ihr gefunden habt, besagen, dass sich das Herz in Uldis befindet, einer Titanenanlage weit im Süden. Den Eingang findet Ihr auf der südlichen Seite eines großen Berges, der den Strom Bors Atem überragt.", progress = nil, completion = "Das Herz in Narvirs Besitz wird dem Koloss seine volle Stärke verleihen! Wir werden keine andere Wahl haben als zu versuchen, uns dagegen zur Wehr zu setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][12999] = {title = "Die Knochenhexe", objective = "Sprecht mit der Knochenhexe in der Höhle des Dorfes Njorndar.", description = "Ihr erinnert Euch doch noch an Lady Nachtwald, oder? Sie hat Euch auf jeden Fall nicht vergessen. Sie ist die verzweifelte und sehr erzürnte Banshee, die Ihr 'gerettet' habt, als Ihr auch Ekel und mich von der Herrschaft des Lichkönigs befreit habt.\n\nDie Lady ist nach Jotunheim gegangen und hat ihre Knochenhexe unter ihre Kontrolle gebracht. Sie will bei den Vrykul von innen heraus Chaos und Verwüstung anrichten.\n\nSie möchte, dass Ihr sie aufsucht. Ihr findet sie in der Höhle auf der südlichen Seite des Dorfes Njorndar im Südwesten von Jotunheim.", progress = nil, completion = "&lt;Name&gt;, Ihr seid gekommen.\n\nIch habe schon von Euren Taten auf der Wilden Klippe gehört. Das ist gut. Ich bin froh, dass Ihr mir anscheinend dabei helfen wollt, die Vrykul hier in Jotunheim zu untergraben.\n\n\n\nWir beide werden mit ihnen eine Menge Spaß haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13000] = {title = "Notfallmaßnahmen", objective = "Blutwache Lorga bittet Euch, zu Gimoraks Bau im Osten zu gehen und von dort 6 Worgfelle mitzubringen.", description = "In diesen Bergen herrscht eine unerbittliche Kälte. Uns bleiben noch ein oder zwei Tage, bis das Holz des Wracks für das Feuer aufgebraucht ist.\n\nIn der Höhle gleich östlich von hier haben wir Worgs gesehen. Findet die Höhle und bringt von dort einige Felle mit. Das klingt zwar nicht nach einer viel versprechenden Beute, könnte jedoch den Unterschied zwischen Erfrieren und Weiterleben ausmachen.\n\nWorgs jagen nicht alleine, daher gebe ich Euch ein Leuchtfeuer. Es sollte Euch ein wenig Zeit verschaffen, falls Ihr gegen die Worgs in Unterzahl seid.", progress = "Habt Ihr die Felle?", completion = "Diese Felle sind ziemlich... groß. Die Worgs, die Ihr dafür erlegen musstet, möchte ich nur ungern zu Gesicht bekommen.\n\nWir sind Euch sehr dankbar. Es wird nämlich schon kälter.", rewards = "FrostheulgurtNomadenarmschienenBrustplatte des NordwaldläufersKaltblütige BeinplattenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13001] = {title = "Hodirs Speer schmieden", objective = "Wissenshüter Randvir aus Dun Niffelem möchte, dass Ihr 3 Immerfrostsplitter aus den Tiefen der Überwinterungshöhle sowie 3 Bälge ruhiger Mammuts aus dem Uralten Wintertal holt.", description = "Die Zeit ist gekommen, <kleiner/kleine:c> <Klasse>. Die Sterne haben diesen Tag vorausgesagt.\n\nIch erhielt eine Eingebung vom mächtigen Hodir persönlich, die mir das Geheimnis zum Bau eines mächtigen Artefakts offenbarte.\n\nWir müssen gehorchen! Wenn wir dieses Geschenk nicht anzunehmen wissen, droht uns sicher der Untergang.\n\nIch appelliere an Euch, mir bei diesem heiligen Unterfangen zur Seite zu stehen.\n\nBegebt Euch zur Überwinterungshöhle auf der anderen Seite des Tals und sammelt im eisigen Krater dort Immerfrostsplitter. Danach sammelt Bälge von den Mammuts außerhalb der Höhle.", progress = "Konntet Ihr die Materialien für den Speer besorgen, <Volk>?", completion = "Tretet zurück, &lt;Volk&gt;, und werdet Zeuge der Erfüllung einer Prophezeiung!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSee Hodir's Spear Primer\n\nIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13002] = {title = "Edelsteine perfektionieren", objective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Geba'li in der Kriegshymnenfeste.", description = "Willkommen in der Kälte, Mann. Der Ort hier is' vielleicht nicht gerade der wärmste, doch ich habe gelernt, wie man den perfekten Edelstein schleift. Alles, was ich dazu brauche, sind ein paar Edelsteine, an denen ich arbeiten kann.\n\nBring mir ein paar Edelsteine und ich werde dir beibringen, wie man Edelsteine perfektioniert. Das wird dir dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn du einen Edelstein aus Nordend von seltener Qualität schleifst.", progress = "Danach habe ich gesucht. Jetzt werde ich dir beibringen, wie man Edelsteine perfektioniert.", completion = "Die sind perfekt, Mann. Nun werde ich dir beibringen, wie man Edelsteine perfektioniert.", rewards = "Ihr erlernt:\n\nEdelsteinperfektion\n\nDer folgende Zauber wird auf euch gewirkt:\n\nEdelsteinperfektion\n\nIhr bekommt außerdem:\n\nKleiner Samtbeutel"}
MultiLanguageQuestData['de'][13003] = {title = "Drachentöten leicht gemacht", objective = "Ihr sollt mit Hodirs Speer einen Wildwyrm im Uralten Wintertal herausfordern. Wenn Ihr ihn getroffen habt, muss es zu einem Kampf auf Leben und Tod kommen.", description = "Hodirs Speer ist ein Symbol für großen Heldenmut im Kampf.\n\nSchon seine bloße Anwesenheit ruft in jedem, der nach Dun Niffelem kommt, das Verlangen nach Ruhm hervor. Ihr wart bloß in seiner Nähe und saht Euch berufen, Eure Fertigkeiten auf die Probe zu stellen.\n\nIhr sucht den Horizont ab und erblickt einen vorbeifliegenden Wildwyrm.\n\nEs ist entschieden. Von Euch beiden wird nur einer den nächsten Sonnenaufgang erleben...", progress = nil, completion = "Es ist vollbracht.\n\nIhr habt dem sicheren Tod ins Auge geblickt und seid siegreich daraus hervorgegangen.\n\nIndem Ihr allein eine solch mächtige Bestie besiegt habt, konntet Ihr Dun Niffelem eine große Ehre erweisen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13004] = {title = "Edelsteine perfektionieren", objective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Alestros in der Valianzfeste.", description = "Es ist Krieg und jeder von uns muss seinen Teil dazu beitragen! Meine Aufgabe ist das Schleifen von Edelsteinen. Ich kann nicht nur normale Edelsteine schleifen, sondern auch perfekte. Wenn Ihr Euren Beitrag leisten wollt und mir ein paar ungeschliffene Edelsteine bringt, kann ich Euch auch beibringen, wie man sie perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", progress = "Eure Spende wird sehr geschätzt. Lasst mich Euch beibringen, wie man Edelsteine perfektioniert.", completion = "Habt Dank. Ich werde Euch eine Schleiftechnik beibringen, mit der Ihr Edelsteine perfektionieren könnt, und Euch einen von meinen perfekt geschliffenen Edelsteinen geben.", rewards = "Ihr erlernt:\n\nEdelsteinperfektion\n\nDer folgende Zauber wird auf euch gewirkt:\n\nEdelsteinperfektion\n\nIhr bekommt außerdem:\n\nKleiner Samtbeutel"}
MultiLanguageQuestData['de'][13005] = {title = "Der Eid der Irdenen", objective = "Thorim, auf der Terrasse der Schöpfer, wünscht, dass Ihr in das Horn der Sturmgipfel blast und die Irdenen ruft, damit sie 20 Eisenzwerge und 7 Eisenschildwachen besiegen.", description = "Jahrelang vernachlässigte ich meine Pflichten, erging mich in Pein und Selbstmitleid.\n\nNicht so die tapferen Irdenen. Ihr Eid, diesen Grund und Boden unter Einsatz ihres Lebens zu beschützen, blieb ungebrochen.\n\nSelbst jetzt bekämpfen sie die Verderbnis des Eisens selbstlos und warten auf den Augenblick, an dem sich das Blatt wendet.\n\nDieser Augenblick ist gekommen. Wir müssen die Kräfte aller verbliebenen Irdenen Verteidiger bündeln und sie zu einem glorreichen Sieg führen. Lasst das Horn der Sturmgipfel ertönen, um sie an Eure Seite zu rufen und die Terrasse der Schöpfer zurückzuerobern.", progress = "Seid gegrüßt, <Name>! Welche Neuigkeiten bringt Ihr mir?", completion = "Das ist ein guter Anfang. Aber es wird nicht lange dauern, bis sich die Streitkräfte meines Bruders neu formiert haben. Unser Sieg muss ein alles entscheidender Sieg werden.", rewards = "Handschuhe des TerrassenguckersArmschiene von TarbashThorims UmklammerungSchultern der ErdmachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13006] = {title = "Eine schmierige Säuberung", objective = "Ihr müsst Euch in die Überwinterungshöhle westlich von Dun Niffelem begeben und 5 Einheiten viskoses Öl vom Rohöl dort besorgen.\n\nKehrt dann nach Dun Niffelem zurück und tragt das Öl auf Hodirs Helm auf.", description = "Als Ihr Euch dem Helm nähert, merkt Ihr, dass die eisige Umgebung der Oberfläche des Artefaktes bereits zugesetzt hat. Schon jetzt bedeckt ihn eine dünne Eisschicht, doch schon bald wird er komplett eingefroren sein.\n\nDa Ihr nicht wollt, dass all Eure Anstrengungen vergebens waren, entschließt Ihr Euch, in der Gegend nach einer Lösung zu suchen.\n\nAls Ihr Euch gerade abwenden wollt, blitzen die Augen des Helms auf und ein Bild der nahegelegenen Überwinterungshöhle erscheint in Eurem Geist.", progress = "Ihr beobachtet, wie sich auf dem Helm eine dicke Schicht Eis und an seinen Kanten Eiszapfen bilden...", completion = "Als Ihr den Helm mit einer dünnen Ölschicht benetzt, verschwindet das Eis und die Oberfläche beginnt zu glänzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13007] = {title = "Der Eisenkoloss", objective = "Nutzt einen gezähmten Jormungar, um den Eisenkoloss zu besiegen, und kehrt dann zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", description = "Wir konnten leider nicht verhindern, dass der Eisenkoloss fertiggestellt wird, <Name>, und das bedeutet, dass wir keine andere Wahl haben, als uns ihm im Kampf zu stellen.\n\nBruor hat einen Plan, wie wir die einzige Schwäche des Kolosses ausnutzen können.\n\nWie robust seine Panzerung auch sein mag, so vermag Jormungar-Säure sie doch zu schädigen. Übernehmt mithilfe der Kugeln am Nordrand der Verschneiten Ebenen die Kontrolle über einen Jormungar und setzt die Säure ein, um den Eisenkoloss auf der verschneiten Ebene zu vernichten. Falls Ihr Hilfe bei der Kontrolle Eurer Kreatur benötigt, sprecht mit einem der Tierführer in der Nähe.", progress = nil, completion = "Wir haben es geschafft, es ist wirklich vollbracht! Die Zuflucht wurde verschont und die Sturmgeschmiedeten sind besiegt! Wir müssen Brann warnen, bevor Loken auf die Idee kommt, seine Truppen neu aufzubauen. Wir können diesen Sieg, den Ihr heute für uns errungen habt, nur sichern, indem wir nach Ulduar gehen und Loken ein für alle Mal besiegen!", rewards = "Schneewehes PantalonsGamaschen der verstärkten ErneuerungBeinschützer aus JormungarhautBeinplatten des EisenkolossesIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13008] = {title = "Die Taktik der Geißel", objective = "Kreuzzugskommandant Entari in der Argentumvorhut von Eiskrone bittet Euch, 5 eingesponnene Kreuzfahrer zu befreien.", description = "Das Überraschungsmoment war auf unserer Seite! Wir sprengten einen Durchgang in die Bergwand und fielen in Geißelholme ein. Die Streitkräfte der Geißel kämpften erbittert und es dauerte nicht lange, bis wir überwältigt wurden. Wir wurden ins Tal zurückgedrängt und begannen damit, mit Artillerie auf die Verfolger der Geißel zu schießen. Wir konnten sie dadurch einige Zeit aufhalten, bis... diese Monster damit begannen, unsere Kreuzfahrer als lebende Schutzschilde zu missbrauchen. Aus Angst, unsere eigenen Soldaten zu töten, mussten wir den Beschuss einstellen.\n\nBefreit unsere Kreuzfahrer, die auf dem Feld außerhalb des Camps gefangen sind, <Klasse>!", progress = nil, completion = "Nach wie vor befinden sich viele Argentumkreuzfahrer dort draußen auf dem Feld und in Geißelholme, &lt;Name&gt;. Für Eure Hilfe sei Euch gedankt, aber es gibt immer noch viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13009] = {title = "Ein Neuanfang", objective = "Njormeld wünscht, dass Ihr die neugeschmiedete Rüstung zu Thorim im Tempel der Stürme bringt.", description = "Es steht weiterhin in den Sternen, ob unser Volk jemals wieder die Sympathie aufleben lassen kann, die es Thorim einst entgegenbrachte.\n\nMöge diese Rüstung - wenn schon nichts anderes - ihn an die Tage erinnern, als wir gemeinsam unbesiegbar und ehrenvoll auf dem Schlachtfeld standen.", progress = "Waren Eure Bemühungen erfolgreich, <Klasse>?", completion = "&lt;Als Ihr Thorim die neugeschmiedete Rüstung übergebt, ist er sichtlich ergriffen ob ihres Glanzes.&gt;\n\nDas habt Ihr gut gemacht, &lt;Volk&gt;, aber es gibt noch viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13010] = {title = "Krolmir, Hammer der Stürme", objective = "Thorim möchte, dass Ihr mit König Jokkum in Dun Niffelem sprecht und in Erfahrung bringt, was er über Krolmir weiß.", description = "Eine Aufgabe bleibt noch, bevor ich mein Heim an der Terrasse der Schöpfer zurückerobern kann.\n\nKrolmir muss gefunden werden.\n\nAn diesem schicksalhaften Tag warf ich ihn mit all meiner Macht und voller Zorn auf die Erde, worauf es zu einer gewaltigen Explosion kam.\n\nAll die Jahre dachte ich, ich hätte ihn verloren, aber nun muss ich Gewissheit haben.\n\nKehrt zu König Jokkum zurück und findet heraus, ob er etwas über das Schicksal meines Hammers weiß.", progress = "Schon zurück, kleiner <Volk>?", completion = "Ich bin Euch wirklich sehr dankbar, &lt;Klasse&gt;.\n\nIhr habt mir ehrenvoll gedient. Bitte nehmt dies als Zeichen meiner Dankbarkeit.", rewards = "Sturmgezeichnete ManschettenSturmpirscherumklammerungRückhandschutzAuf Euch wartet eine dieser Belohnungen:\n\nMedaillon von Schneekuppe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13011] = {title = "Jorkuttar töten", objective = "König Jokkum in Dun Niffelem möchte, dass Ihr in die Überwinterungshöhle geht und Jorkuttar niederstreckt.", description = "Mir schwebt da eine Möglichkeit vor, wie Ihr unter meinesgleichen Anerkennung finden könntet, vorausgesetzt, Ihr seid erfolgreich.\n\nDie Jormungar sind eine Plage, um die man sich am besten schnell kümmern sollte. Wenn man sie auch nur ein wenig in Ruhe lässt, dann vermehren sie sich wie die Hasen und verbreiten sich wie Feuer.\n\nSie sind südwestlich von hier aufgetaucht, in der Überwinterungshöhle. Wenn Ihre Brutmutter nicht schon bald getötet wird, werden sie sich in unserer Gegend festsetzen.\n\nEtwas zu fressen kann sie nicht verschmähen. Nehmt dieses Messer, geht zu der Höhle und besorgt Euch die Flanke eines toten Bären. Legt das Fleisch in die Nähe ihres Kraters und tötet sie, wenn sie gerade dabei ist, sich satt zu fressen.", progress = "Habt Ihr Jorkuttar getötet?", completion = "Es ist also vollbracht.\n\nJorkuttars Schreie sind durchs ganze Tal gehallt.\n\nIhr habt meinem Volk heute einen großen Dienst erwiesen, kleiner &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13012] = {title = "Urahne Sardis", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren. Ich wünsche Euch alles Gute, <Name>, und biete Euch diese Marke als Geschenk...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][13013] = {title = "Urahne Beldak", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
