MultiLanguageQuestData['de'][13033] = {title = "Urahne Arp", objective = "Ich spüre das Feuer des Lebens in Euch, <Klasse>. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][13034] = {title = "Der Zeuge und der Held", objective = "Xarantaur im Camp Tunka'lo möchte, dass Ihr Euch die erste, zweite und dritte historische Schriftrolle durchlest.", description = "Als ich meine Reisen in Nordend angetreten hatte, besuchte ich die Boreanische Tundra und traf zum ersten Mal mit den Taunka zusammen. Dort erzählte mir Windzähmerin Barah die Geschichte von Sturmhuf und seinem Kampf gegen den Nordwind, dem uralten Gegner seines Volkes.\n\nIch machte mich auf zu den Sturmgipfeln, um mehr über diesen Helden in Erfahrung zu bringen, aber seltsamerweise scheinen die Leute in Tunka'lo nichts über ihn zu wissen.\n\nVielleicht werden uns die eigenen Aufzeichnungen des Camps mehr Aufschluss darüber geben. Findet und lest die historischen Schriftrollen, die verteilt im ganzen Lager aufbewahrt werden und berichtet mir anschließend, was Ihr erfahren habt.", progress = nil, completion = "Äußerst merkwürdig... das klingt nicht nach der Geschichte, die Windzähmerin Barah mir erzählt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13035] = {title = "Lokens Lakaien", objective = "Thorim möchte, dass Ihr Eisenfaust in der Halle des Formers erschlagt. Außerdem sollt Ihr Halefnir den Zischenden und Duronn den Runenbesetzten auf der Terrasse der Schöpfer töten.", description = "Für meinen Bruder war der Angriff auf die Terrasse der Schöpfer keine halbherzige Aktion: Er entsandte eine Legion von Eisenzwergen und einige seiner mächtigsten Leutnants dorthin.\n\nBenutzt das Horn der Sturmgipfel, um die Irdenen zu Hilfe zu rufen und Lokens Diener zu vernichten.\n\nIm Inneren der Halle des Formers gen Norden werdet Ihr den Riesen Eisenfaust finden. Die anderen befinden sich tiefer im Inneren der Terrasse der Schöpfer, jenseits der Treppen im Nordwesten.", progress = "Es ist gut, Euch wiederzusehen, <Name>.", completion = "Einer nach dem anderen sind sie gefallen, die Diener meines Bruders. Lokens Aufstand wird schon bald ein Ende finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13036] = {title = "Ehre über alles", objective = "Meldet Euch bei Kreuzzugskommandant Entari in der Argentumvorhut in Eiskrone.", description = "Es war ein langer, beschwerlicher Weg bis zu unserer Errettung, <junger/junge:c> <Klasse>. Wir sind bei unseren Kämpfen durch ganze Kontinente, ja sogar Welten gezogen, um an diesen Punkt zu gelangen. Jetzt stehen wir vor unserer größten Herausforderung: Die Vernichtung des Lichkönigs und seiner Geißel.\n\nAber leider müssen wir diese Schlacht getrennt voneinander durchstehen. Die Horde und die Allianz stehen kurz vor einem Krieg und können uns keine Unterstützung zusichern. Wir müssen in unserer Sache unnachgiebig bleiben! Was bleibt uns auch anderes übrig?\n\nWerdet Ihr Euch unserer Sache anschließen? Lasst uns Eure Stärke zuteilwerden, <Klasse>! Mein Kommandant Entari erwartet Euch auf seinem Posten.", progress = nil, completion = "Wo sowohl die Allianz als auch die Horde scheiterten, war der Argentumkreuzzug erfolgreich. Allerdings war dieser Erfolg nur von kurzer Dauer. Unser Vorstoß nach Eiskrone war schnell und gewaltsam... zurückgeschlagen worden...\n\nDer Vergeltungsschlag des Lichkönigs kam unverzüglich und mit brutaler Härte. Jetzt sind wir in der Defensive.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13037] = {title = "Erinnerungen an Sturmhuf", objective = "Sprecht mit Häuptling Schnellspeer in der Frostschollentiefe und kehrt dann zu Xarantaur ins Camp Tunka'lo zurück.", description = "Als mir der bronzene Drachenschwarm die Unsterblichkeit schenkte und mich auf den Weg des Zeugen schickte, vertraute mir Nozdormu den Lehrenhammer an.\n\nDie Reaktion des Hammers auf Euren Fund sagt mir, dass die Zeit hier nicht richtig verlaufen ist und wir die richtige Zeitlinie wiederherstellen müssen.\n\nWir müssen sie finden. Im Nordwesten liegt die Frostschollentiefe, eine uralte Begräbnishöhle der Krieger von Tunka'lo. Sucht den Geist von Häuptling Schnellspeer, Sturmhufs Bruder. Fragt ihn, was ihm vom Kampf seines Bruders gegen den Nordwind in Erinnerung geblieben ist.", progress = nil, completion = "Sogar der Häuptling beginnt, seine Erinnerungen zu verlieren? Die Vergangenheit wird vor unseren Augen neu geschrieben, und wenn wir nicht herausfinden, wer dahintersteckt, dann könnte Sturmhufs Erbe für immer verloren sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13038] = {title = "Verzerrungen in der Zeit", objective = "Nutzt das Totem des Häuptlings, um 4 Frostschollenklüfte zu schließen, und bringt es danach zu Xarantaur ins Camp Tunka'lo.", description = "Dieses Grab der Tunka'lo-Krieger sollte ein ruhevoller Ort sein, der vor den Schrecken der Elemente geschützt ist.\n\nDie Frostschollentiefe wurde von einer seltsamen Kraft befallen, die die Geister der Gefallenen in Unruhe versetzt und die Erinnerungen an mein Leben durcheinander bringt.\n\nEs ist, als würden unsere Taten und Erinnerungen aus der Geschichte getilgt.\n\nZu Lebzeiten war dieses Totem ein Zeichen meiner Autorität. Es ist die letzte wirkliche Verbindung, die ich noch zu dieser Welt habe. Nehmt es und nutzt es, um die Ruhe dieses Grabes wiederherzustellen, und bringt es danach ins Camp Tunka'lo zurück.", progress = "Was habt Ihr aus dem Grab mitgebracht?", completion = "Der Geist des Häuptlings hat Euch gesagt, dass Ihr mir das hier bringen sollt?\n\n&lt;Xarantaur untersucht das Totem.&gt;\n\nAh, jetzt verstehe ich, was er beabsichtigt hat. Als er Euch auftrug, Ihr sollt mit diesem Totem die Klüfte in der Tiefe schließen, hat er uns einen Hinweis darauf gegeben, was mit der Zeitlinie geschieht. Schnellspeer ist ein weiser Häuptling, der noch im Tode über sein Volk wacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13039] = {title = "Die Vorhut verteidigen", objective = "Kreuzfahrerlord Dalfors von der Argentumvorhut in Eiskrone hat Euch gebeten, 15 Neruber der Vergessenen Tiefen zu töten.", description = "Wir können nicht in dem Tempo weitermachen. Sobald die Bresche in die Luft gesprengt wurde, öffneten sich die Fluttore. Seitdem fällt die Geißel über uns her, und es nimmt kein Ende!\n\nWir brauchen jede fähige Hand, um die Angreifer abzuwehren. Geht da raus und leistet Euren Beitrag, Freund. Tötet so viele Monster, wie Ihr nur könnt!", progress = "Gebt nicht auf, <Name>!", completion = "Wie viele von ihnen gibt es denn noch? Wir haben genug getötet, um zehn Friedhöfe zu füllen, und trotzdem kommen immer mehr. Die Lage sieht ernst aus, Freund.", rewards = "Berührung des LichtsVerzauberter PlattentaillenschutzArgentumgurtAuf Euch wartet eine dieser Belohnungen:\n\nMedaillon des Kreuzfahrers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13040] = {title = "Heilmittel für das Unheilbare", objective = "Vater Gustav aus der Argentumvorhut in Eiskrone bittet Euch, ihm 10 Giftdrüsen der Vergessenen Tiefen zu bringen.", description = "Täglich steigt die Anzahl verwundeter Soldaten. Sie werden von einer Art Gift niedergestreckt, das uns bisher gänzlich unbekannt ist. Was auch immer diese Neruber da in ihren Giftdrüsen haben, es ist unheilbar und bringt den Tod! Bisher konnten wir nur die Verbreitung des Gifts im Körper des Opfers verlangsamen. Wir müssen jedoch ein Heilmittel finden!\n\nWagt Euch in Richtung Nordwesten zum Tal außerhalb des Vorpostens und tötet die Neruber der Vergessenen Tiefen. Nehmt ihre Giftdrüsen und bringt sie zu mir.", progress = "Konntet Ihr die Giftdrüsen beschaffen, <Volk>?", completion = "Habt Dank, &lt;Name&gt;. Ich werde sofort mit der Untersuchung dieser Proben beginnen. Ich hoffe, dass bald ein Heilmittel gefunden werden kann.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRunenverzierter HeiltrankRunenverzierter Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13041] = {title = "Die Lieferung abfertigen", objective = "Bringt einen Chalzedon zu Jonas Timotheus in Dalaran.", description = "Freut mich, dass Ihr hier seid! Eine Lieferung leuchtender Elfenbeinfiguren muss so schnell wie möglich nach Lorenhall geschickt werden und mir fehlt noch ein Chalzedon für das Auge der letzten Statuette.\n\nBringt mir einen davon und ein Juwelierssymbol von Dalaran gehört Euch.", progress = "Habt Ihr schon einen Chalzedon gefunden?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Bei mir gehen die ganze Zeit Lieferungen raus, schaut also ab und zu vorbei und seht nach, was ich so brauche.", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][13042] = {title = "Tief im Inneren des Kellergewölbes", objective = "Die Knochenhexe aus Njorndar bittet Euch, Informationen bezüglich der Pläne von Dr. Maböse aus Lehrling Osterkilgr herauszuprügeln.\n\nTötet den Lehrling anschließend.", description = "Tief im Inneren des Kellergewölbes im Nordosten heckt ein verrückter Wissenschaftler, bekannt unter dem Namen Dr. Maböse, etwas aus, das seinem Namen alle Ehre macht.\n\nDer Doktor bekam die Erlaubnis des Lichkönigs, Experimente mit Varguls durchzuführen - den Vrykul, die im Kampf fallen, als unwürdig erachtet werden und dann der Geißel anheim fallen.\n\nWir müssen seiner Arbeit ein Ende machen, meine Wahrsager konnten ihn jedoch nicht aufspüren. Allerdings hat er einen Assistenten.\n\nPrügelt aus seinem Lehrling alle Informationen heraus und lasst ihn dann verschwinden.", progress = nil, completion = "Interessant. Wie es scheint, konntet Ihr den Auftrag zu meiner vollsten Zufriedenheit erledigen. Es überrascht mich, dass der Doktor einen Vargul als Assistenten hatte, wenn man bedenkt, mit welchen Kreaturen er experimentierte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13043] = {title = "Das Ganze ist größer als die Summe seiner Teile", objective = "Besteigt Nergeld und übernehmt die Kontrolle. Verteidigt ihn vor den Bewohnern der Hallen des Grauens, bis sich Dr. Maböse zeigt.\n\nNutzt Nergeld, um den Doktor zu vernichten, und kehrt dann zur Knochenhexe nach Njorndar zurück.", description = "Ihr öffnet den Folianten und erblickt verschiedene widerwärtige Illustrationen dessen, was der Doktor \"die ultimative Waffe\" nennt!\n\nDer Prototyp Nergeld ist offenbar der gewaltige Fleischriese, der am Ende der naheliegenden Hallen des Grauens steht.\n\nWürde eine Armee dieser Kreationen gebaut, dann wäre das der sichere Untergang. Wir können nur sicherstellen, dass dies nicht geschieht, indem wir Dr. Maböse vernichten!\n\nVielleicht zeigt sich der Doktor, wenn Ihr die Kontrolle über dieses Konstrukt übernehmt?", progress = "Ihr habt das Buch des Doktors mitgebracht, ihn aber nicht mithilfe des Fleischriesen vernichtet?\n\nGeht sofort zurück und tötet ihn, bevor es zu spät ist!", completion = "Ihr habt die Machenschaften des Doktors enttarnt und ihnen ein Ende bereitet.\n\n&lt;Die von der Banshee besessene Hexe lächelt und legt Euch sanft ihre große Hand auf die Schulter.&gt;\n\nDa haben wir dem Lichkönig aber einen schönen Schlag versetzt, allerdings denke ich, dass wir das noch besser können.", rewards = "Tuch der KnochenhexeGürtel von NjorndarNergelds RingGamaschen des eiszeitlichen WaldläufersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13044] = {title = "Falls es Überlebende gibt...", objective = "Sprecht mit Penumbrius in der Argentumvorhut in Eiskrone.", description = "Jenseits des Tals der Echos westlich von hier und auf der anderen Seite der Bresche liegt das erste Lager der Geißel in Eiskrone, das Geißelholme genannt wird. Wir haben dort gut gekämpft und viele Krieger der Geißel getötet, aber letzten Endes wurden wir zum Rückzug gezwungen. Dabei mussten wir viele Soldaten zurücklassen, über deren Schicksal uns nichts bekannt ist.\n\nFalls es Überlebende gibt, müssen wir versuchen, sie zu retten. Wenn Ihr diesen Südostpfad nehmt, gelangt Ihr zu Penumbrius, einem Verbündeten des bronzenen Drachenschwarms und Hüter der Protodrachenbrut. Sucht ihn auf und bittet ihn um Hilfe.", progress = nil, completion = "&lt;Penumbrius nickt.&gt;\n\nMein Volk wird Euch helfen. Gemeinsam werden wir gegen den Lichkönig und seine untoten Legionen kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13045] = {title = "Ins wilde Grün", objective = "Rettet 3 gefangene Argentumkreuzfahrer aus Geißelholme und bringt sie ins Feldlazarett im Zentrum des Argentumvorpostens. Berichtet Hochlord Tirion Fordring danach von Eurem Erfolg.", description = "Wir werden tun, was wir können, um Euch zu helfen, <Name>. Die Protobrut hat sich bereit erklärt, Euch durch die Bresche nach Geißelholme zu fliegen. Rettet alle gefangenen Argentumkreuzfahrer, die Ihr findet. Bringt sie sodann ins Feldlazarett der Vorhut, das sich inmitten dieser Basis befindet.\n\nWählt eine der Argentumhimmelsklauen aus dem Gatter hinter mir aus und fliegt los!\n\nGeißelholme liegt nordwestlich von hier auf der anderen Seite des Tals der Echos, jenseits der großen Bresche.", progress = "Mit jeder Minute, die verstreicht, sinkt ihre Chance zu überleben.", completion = "Arthas... Er schlägt rücksichtslos zu - ohne nachzudenken oder Vorsicht walten zu lassen. Wir konnten ihn überrumpeln.\n\n&lt;Hochlord Tirion Fordring hält gedankenverloren inne.&gt;\n\nWir werden unsere Verteidigung verstärken und dem Sturm trotzen.\n\nWie gut könnt Ihr mit einer Kanone umgehen, &lt;Name&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Command Argent Skytalon\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13046] = {title = "Arngrim füttern", objective = "Ihr sollt 5 körperlose Jormungar an Arngrim verfüttern und dann zu Arngrims gefrorenem Abbild in Dun Niffelem zurückkehren.\n\nIhr müsst ins Uralte Wintertal gehen und Arngrims Zahn auf die dort herumstreunenden Jormungar anwenden. Sobald sie eine körperlose Form angenommen haben, müsst Ihr sie bekämpfen, bis sie geschwächt sind.", description = "Arngrims Hunger war legendär.\n\nSogar im Tode gleicht sein Gesichtsausdruck dem eines Hungernden. Ihr stellt fest, dass Euer Magen anfängt zu knurren, wenn Ihr ihn auch nur anseht.\n\nEs heißt, dass er im Leben nie wirklich satt war und dass es absolut nichts gab, was er nicht gegessen hätte. Ihr fragt Euch, ob es einen Weg gibt, den alten König zu füttern.\n\nWährend Ihr noch überlegt, fällt einer von Arngrims gewaltigen gefrorenen Zähnen aus, prallt von seinem Bart ab und landet in Eurer Hand.", progress = nil, completion = "Als Ihr den Zahn in Arngrims Kiefer verankert, habt Ihr den Eindruck, dass Eure Bemühungen den Hunger des alten Königs gestillt haben... vorerst zumindest.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13047] = {title = "Die Abrechnung", objective = "Trefft Euch mit Thorim in der Nähe des Tempels der Weisheit. Berichtet König Jokkum in Dun Niffelem, wie der Kampf ausgegangen ist.", description = "Loken hat meine Frau getötet und meine Anhänger gegen mich aufgewiegelt. Er hat mir alles genommen, was ich hatte, doch heute... wird sich das ändern.\n\nHeute werden wir unseren geheiligten Boden zurückerobern. Heute... wird Loken sterben.\n\nTrefft mich auf der Brücke in der Nähe des Tempels der Weisheit gleich südwestlich von Ulduar. Ich werde dies zu Ende bringen, so oder so.\n\nIch brauche Euch als Zeugen. Ihr werdet mir nicht helfen - das ist eine persönliche Angelegenheit.\n\nBenachrichtigt Jokkum, den König der Frostriesen, sobald die Sache erledigt ist. Er ist ein guter Freund und wird wissen, was zu tun ist.", progress = nil, completion = "Nein... das darf nicht wahr sein...\n\nNiemand kann Thorim im Einzelkampf besiegen - weder Riese noch Bestie... niemand! Ganz besonders nicht sein feiger Bruder.\n\nBei den Namen meiner Vorväter schwöre ich...\n\nLoken wird dafür büßen!", rewards = "Handschuhe des DienersRauer Handschutz des KletterersStulpen des WindgreifersStulpen der WachsamkeitIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13048] = {title = "Wo die Zeit aus dem Ruder lief", objective = "Setzt den Lehrenhammer bei den Taunka-Relikten ein, um ihn an Sturmhufs Zeit anzupassen. Kehrt zu Xarantaur nach Camp Tunka'lo zurück, wenn er auf 6 Relikte aus Sturmhufs Zeit eingestimmt wurde.", description = "Der Lehrenhammer kann uns helfen, den Schaden, den die Zeitlinie genommen hat, zu korrigieren, aber dafür müssen wir erst herausfinden, wo die Geschichte das erste Mal verändert wurde.\n\nDank Häuptling Schnellspeer und Eurer Erkenntnisse aus der Frostschollentiefe wissen wir, dass die Veränderung etwa zur Zeit von Sturmhufs Tod stattfand.\n\nNun müsst Ihr zur Heulenden Senke nördlich des Lagers gehen und die Grabstätten untersuchen, die von den Dienern des Nordwinds schon zerstört wurden. Der Lehrenhammer wird auf die Artefakte aus Sturmhufs Zeit reagieren und sich selbst auf die richtige Zeit einstellen.", progress = "Habt Ihr den Lehrenhammer auf Sturmhufs Zeit eingestimmt?", completion = "&lt;Xarantaur nimmt Euch den Lehrenhammer ab.&gt;\n\nZumindest konnten wir bestimmen, zu welcher Zeit Sturmhuf gelebt hat. Mit diesem Wissen können wir die Zeitachse wiederherstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13049] = {title = "Die Waffen des Helden", objective = "Findet Sturmhufs Rüstung und Speer und bringt die Gegenstände zu Xarantaur in Camp Tunka'lo zurück.", description = "Noch wurden nicht alle Aufzeichnungen des Lagers manipuliert. Meine Helfer haben mir dabei geholfen, diese Aufzeichnungen mit der wahren Zeitfolge zu finden.\n\nSie stimmen darin überein, dass Sturmhuf ein Ehrenbegräbnis bei den Dorfältesten unten in der Heulenden Senke im Norden bekam.\n\nDie meisten der dortigen Gräber wurden bereits zerstört und ihr Inhalt als Trophäen von den Wesen des Nordwinds entnommen. Begebt Euch in die Senke und versucht, Sturmhufs Rüstung und Speer von den Saaten des Sturms zu erlangen, die diese Dinge für sich beansprucht haben.", progress = "Habt Ihr Sturmhufs Rüstung und Speer gefunden?", completion = "Wir sind froh, dass Ihr diese Gegenstände unversehrt zurückbringen konntet, &lt;Name&gt;. Mit ihrer Hilfe kann ich den Lehrenhammer benutzen, um Euch in die Zeit zurückzuschicken, als der Nordwind damit begonnen hatte, die wahre Zeitlinie zu manipulieren. Das ist die einzige Möglichkeit, wie wir den wahren Geschichtsverlauf dieses Ortes wiederherstellen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13050] = {title = "Veranus", objective = "Thorim aus dem Tempel der Stürme möchte, dass Ihr ihm 5 kleine Eier von den Protodrachen bringt, die auf den Gipfeln in der Umgebung von Brunnhildar hausen.", description = "Wenn ich die Armee meines Bruders angreifen will, muss ich irgendwie um sie herumkommen.\n\nIch habe meinen Reitdrachen schon vor Jahren freigelassen. Veranus war prächtig, die Anführerin ihrer eigenen Brut - zu der sie jetzt zurückgekehrt ist.\n\nEs wird sehr schwer werden, sie zu finden, aber es gibt vielleicht eine Möglichkeit. Aus Stolz hat sie ihr altes, leeres Nest behalten. Sie ist nur noch vom Namen her eine Brutmutter, da sie das Brutalter bereits überschritten hat.\n\nBringt mir kleine Eier aus den anderen Nestern in der Nähe von Brunnhildar. Ich habe da so eine Idee.", progress = "Habt Ihr die Eier, <Name>?", completion = "Ja... die sollten reichen. Hoffen wir, dass mein Plan aufgeht, &lt;Name&gt;.\n\nVeranus ist ein großer Drache und ich würde mich nur ungern mit einem niederen zufrieden geben müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13051] = {title = "Territoriale Vergehen", objective = "Legt die gestohlenen Protodracheneier in das Nest der Brutmutter und kehrt dann zu Thorim in den Tempel der Stürme zurück.", description = "Veranus ist stolz wie kein anderes Tier, das ich je gekannt habe. Sie hat noch immer ihr altes Nest und achtet darauf, dass es nicht von einem jüngeren Protodrachen in Besitz genommen wird.\n\nLegt die Eier, die Ihr gesammelt habt, in ihr Nest. Ihr findet es auf dem kleinen Gipfel südöstlich von hier.\n\nIch müsste sie unter Kontrolle haben, bevor sie Euch aus lauter Wut umbringt; zumindest hoffe ich das.", progress = "Grüße, <Name>!", completion = "Ich freue mich, dass meine alte Freundin zurück ist. Es scheint fast so, als würde sich das Blatt langsam wenden... und das habe ich allein Euch zu verdanken, kleiner Freund.", rewards = "Rasiermesserscharfer EiszapfenThorims ReitgerteArmbrust der StürmeThorims ZermalmerBeschützer der BrutmutterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13052] = {title = "Luftüberwachung", objective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordwesten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordwesten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13053] = {title = "Suche nach Überlebenden", objective = "Helft Zak Wackelspross, den Testflug zu beenden.", description = "Gretchen Zischelfunken möchte meine Flugmaschine nutzen, um nach Überlebenden ihrer Expedition zu suchen. Offenbar glaubt sie, dass diese im Dorf im Norden gefangen gehalten werden.\n\nDas Problem ist, dass ich keinen Copiloten habe. Wenn Ihr mir aushelfen wollt, dann zeige ich Euch gern ein oder zwei hilfreiche Tricks.\n\nWas sagt Ihr, <Name>? Abgemacht?Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nKaltwetterflug\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13054] = {title = "Der vermisste Fährtenleser", objective = "Sucht in Gimoraks Bau östlich der Absturzstelle Grom'ash nach Fährtenleser Val'zij.", description = "Ich kann Euch nicht guten Gewissens in die Worghöhle gehen lassen, ohne Euch zu warnen, dass wir zuvor schon jemanden dorthin geschickt haben, der jedoch nicht zurückgekehrt ist.\n\nWir rechnen mit dem Schlimmsten, aber vielleicht ist er auch noch am Leben. Solltet Ihr ihm helfen können, zu uns zurückzukehren, wären wir Euch sehr dankbar - Fährtenleser Val'zij ist einer unserer wenigen Jäger.", progress = nil, completion = "Das tut wirklich weh, Mann. Ich weiß nicht, ob ich es schaffen werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13055] = {title = "Höhlenmedizin", objective = "Fährtenleser Val'zij hält sich in Gimoraks Bau auf und möchte, dass Ihr ihm 1 Giftdrüse der Jormungar und 8 Höhlenpilze bringt.", description = "Wie schön, ein freundliches Gesicht zu sehen, vielleicht das Letzte, das ich seh'n werde.\n\nEiner dieser Jormungar hat mich gestochen, bevor ich entkommen konnte. Mein Körper fühlt sich schon ganz taub an, Mann.\n\nIch brauch'ne Giftdrüse, um ein Gegengift herzustellen, und außerdem einige der Höhlenpilze, die hier wachsen... sie werden das Gift verlangsamen.\n\nBitte beeil dich - hab nich' mehr viel Zeit.", progress = "Du bist wieder da, Mann?", completion = "Danke dir, Mann. Vielleicht lebe ich doch noch 'n bisschen länger.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13056] = {title = "Für Rache ist immer Zeit", objective = "Fährtenleser Val'zij möchte, dass Ihr Gimorak in Gimoraks Bau tötet.", description = "Ich müsste vorerst zurechtkommen, <Name>. Aber ich möchte dich noch um 'nen Gefallen bitten.\n\nIch wäre diesen Würmern nie in die Hände gefallen, wenn meine Windnatter Heesha nicht vom gemeinsten Worg, den ich seit langer Zeit gesehen habe, getötet worden wäre.\n\nMach dir um mich keine Sorgen; mir wird es besser gehen, wenn der Worg keinen Atemzug mehr von sich gibt. Du solltet ihn weiter drinnen in der Höhle finden", progress = "Hast du diesen dreckigen Bastard schon gefunden, <Name>?", completion = "Es geht mir schon viel besser, Mann. Ich weiß nicht, ob es an dem Gegengift liegt oder daran, dass der dreckige Worg bekommen hat, was er verdient.", rewards = "Stiefel der heulenden WindeGehärteter PeitschengürtelKaputter KeuschheitsgürtelKieferbrecherIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13057] = {title = "Die Terrasse der Schöpfer", objective = "Findet Thorim an der südöstlichen Kante der Terrasse der Schöpfer gleich nordwestlich von Dun Niffelem.", description = "Es ist Zeit, <Name>. Ich bin jetzt bereit, mich Loken zu stellen.\n\nBegeben wir uns nun zur Terrasse der Schöpfer, wo wir auf die Truppen meines Bruders treffen werden. Der Narr wird noch bereuen, sich je mit mir angelegt zu haben.", progress = nil, completion = "Wir sind da, &lt;Name&gt;. Heute werden die Truppen meines Bruders erfahren, wie es ist zu verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13058] = {title = "Die Windrichtung ändern", objective = "Reist mithilfe des Lehrenhammers in der Zeit zurück, schlüpft in Sturmhufs Rolle und stellt Euch dem Nordwind. Beschafft Euch das Horn des Elementarfurors, sobald Sturmhuf gestorben ist und es fallengelassen hat, und benutzt es, um den Nordwind zu erledigen. Kehrt danach zu Xarantaur ins Camp Tunka'lo zurück.", description = "Zu guter Letzt haben wir alles, was wir brauchen, um das wieder gut zu machen, was der Nordwind und seine Anhänger angerichtet haben. Ihr habt den Lehrenhammer auf Sturmhuf selbst und seine Zeit ausgerichtet.\n\nHier, nehmt wieder den Hammer an Euch, geht zum Tempel des Lebens, schlüpft mit seiner Hilfe in Sturmhufs Rolle und stellt Euch dem Nordwind. Doch wisset: Um die Zeitlinie wieder herzustellen, muss Sturmhuf sterben, sobald der Nordwind geschwächt ist.\n\nSobald dies geschehen ist, müsst Ihr das Horn des Elementarfurors an Euch bringen und mit ihm den Nordwind vernichten.", progress = "Habt Ihr es getan? Ist die echte Zeitlinie wiederhergestellt?", completion = "Was Ihr heute getan habt, wird dafür sorgen, dass Sturmhuf und seine Geschichte niemals in Vergessenheit geraten werden. Außerdem habt Ihr Euren Namen in die Geschichtsbücher Azeroths geschrieben. Ich werde mich für alle Ewigkeit an Euch und das, was Ihr geleistet habt, erinnern.", rewards = "Zauberstab der kühlen ErneuerungBerührung des EiskreischersAuf Euch wartet eine dieser Belohnungen:\n\nBeschwerte WurfaxtRasiermesserscharfe Eissplitter\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13059] = {title = "Rache für die Vargul", objective = "Bethod Feigr im Kellergewölbe wünscht, dass Ihr sein Schwert zu Boden werft, um Than Illskar im Kreis des Leidens herauszufordern und zu töten.", description = "Ich habe zur Herrin des Schwertes gebetet, auf dass jemand kommen und meinen Gegner vernichten möge. Than Illskar muss dafür büßen, was er mir angetan hat!\n\nIch war einst der Champion von Than Ufrang dem Mächtigen. Während meines Kampfes um die Vormachtstellung in Valhalas hat mich Illskar mit dunkler Magie sabotiert, woraufhin ich verloren habe und zu dem wurde, was ich jetzt bin.\n\nDer Than und seine Champions befinden sich unten im Kreis des Leidens. Fordert ihn in meinem Namen heraus. Besiegt ihn.\n\nBringt ihm die Qualen bei, die auch ich ertragen muss!", progress = nil, completion = "Danke, &lt;Klasse&gt;... habt Dank!\n\nIhr habt mir zu der Genugtuung und Gewissheit verholfen, dass dieser Feigling, der mir das angetan hat, bis in alle Ewigkeit genau so dahinsiechen wird wie ich.\n\nNun geht hinfort, bevor ich die Beherrschung verliere und Euch niederstrecke.", rewards = "Mantel des KellergewölbesStiefel des gefallenen ThansIllskas GroßumhangStulpen des heiligen GladiatorsReif des LeidensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13060] = {title = "Wenn alles andere versagt", objective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", progress = nil, completion = "&lt;Olut zuckt zusammen.&gt;\n\nDas hat schmerzhaft ausgesehen. War aber ein ziemlich eindrucksvoller Auftritt.\n\nSeid Ihr hier, um uns dabei zu helfen, einen Weg zum Eiskronengletscher zu finden? Unser erster Abstecher in diese Richtung endete nicht sehr eindrucksvoll. Ich denke, dass wir besser damit beraten wären, den Durchbruch von der anderen Seite her zu versuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13061] = {title = "Bereit für den Ruhm", objective = "Sprecht mit Lok'lira der Greisin in Brunnhildar.", description = "Das war's dann also. Ich werde mich jetzt um Euren Bären kümmern, Ihr werdet ihn nicht mehr benötigen. Der große Drakkensryd wird Eure nächste Herausforderung sein.\n\nSagt Euren Freunden Lebewohl und bringt alles ins Reine, bevor Ihr loszieht. Denn Ihr werdet entweder siegreich zurückkehren... oder gar nicht.", progress = nil, completion = "Ihr habt es wirklich bis hierher geschafft. Niemals hätte ich gedacht, dass Ihr so schnell bei den Hyldnir aufsteigen würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13062] = {title = "Lok'liras Abschiedsgeschenk", objective = "Sprecht mit Gretta der Schiedsfrau in Brunnhildar.", description = "Ihr wart uns eine großartige Mitstreiterin, <Name>. Doch nun kommt Eure wahre Prüfung. Dazu werdet Ihr Können, Mut und ein wenig Glück benötigen.\n\n<Lok'lira flicht eine Haarsträne in Euer Haar ein.>\n\nNun könnt Ihr nicht mehr versagen, Schwester. Sprecht mit Gretta der Schiedsfrau. Sie wird sich um Eure Abreise kümmern.", progress = nil, completion = "Bereit, loszureiten, Schwester? Es wird kein Zurück geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13063] = {title = "Für würdig befunden", objective = "Brijana möchte, dass Ihr nach Brunnhildar geht und mit Astrid Bjornrittar sprecht.", description = "Ihr hattet dort Erfolg, wo viele versagten, Schwester. Ob es nun Eurer Stärke, Eurem Mut oder einfach nur Eurem Glück zu verdanken ist, wird sich noch zeigen.\n\nGeht zurück zum Dorf und sucht nach Astrid Bjornrittar. Erzählt ihr, was Ihr erreicht habt. Doch seid gewarnt: Sie ist nicht so leicht zu beeindrucken.", progress = nil, completion = "So, Schwester, Ihr denkt also, dass ein paar so einfache Aufgäbelchen Euch zur Heldin machen?\n\nIhr werdet es noch lernen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13064] = {title = "Rivalität unter Geschwistern", objective = "Thorim möchte, dass Ihr Euch seine Geschichte anhört.", description = "Sif? Bist du es wirklich?\n\nNein? Nur <ein/eine:r> <Volk>? Aber einen Augenblick lang...\n\nGenug davon! Die Visionen meiner Sif haben mich schon viel zu lange gequält. Es wird Zeit, sie zu rächen und ihr Andenken zu ehren.\n\nMein Bruder muss bezahlen!", progress = nil, completion = "Ihr wisst jetzt ein wenig über die Geschichte dieses Landes... meines Landes.\n\nIch bitte Euch, mir zu helfen, das Unrecht wieder gutzumachen.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13065] = {title = "Urahne Ohanzee", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][13066] = {title = "Urahne Yurauk", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][13067] = {title = "Urahne Chogan'gada", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][13068] = {title = "Eine Erzählung von Heldenmut", objective = "Hochlord Tirion Fordring auf dem Kreuzfahrerturm wünscht, dass Ihr den Helden Kreuzfahrer Bridenbrad in der Stillen Nachtwache im Nordosten der Eiskrone aufspürt. Seine Feuergrube wird aus der Luft gesehen wahrscheinlich der deutlichste Hinweis auf seinen Aufenthaltsort sein.", description = "Ist es möglich, dass Ihr die Lobpreisungen an unseren verschollenen Helden gehört habt?\n\nKreuzfahrer Bridenbrad hat den Angriff gegen die Geißel an der Zerbrochenen Front unterstützt, als die Armee der Untoten über sie hereinbrach. Die Masse der Verbündeten floh, aber Bridenbrad allein kehrte zurück und trug mehr als ein Dutzend Männer in Sicherheit, einen nach dem anderen, inmitten des Gemetzels.\n\n<Klasse>, er ist seitdem nicht wieder zurückgekehrt. Man hat gesehen, wie er weit nach Nordosten zog, Richtung Stille Nachtwache. Bringt ihn wieder hierher, damit ich ihm für seinen Mut Respekt zollen kann.", progress = nil, completion = "Zurück! Seht Euch vor! Die Seuche hat von mir Besitz ergriffen und ich werde nicht zulassen, dass sie auf Euch oder andere überspringt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13069] = {title = "Schießt sie ab!", objective = "Der Springer beim Schattengewölbe möchte, dass Ihr eine Schnellfeuerharpune von Jotunheim dazu verwendet, 15 Protodrachen von Jotunheim mitsamt ihren Reitern abzuschießen.", description = "Jotunheim verfügt über Luftabwehr, sowohl Protodrachenreiter als auch Harpunenkanonen. Sie haben diese an ihren nördlichen und westlichen Verteidigunszonen konzentriert, weil sie dort am verwundbarsten sind.\n\nLasst uns ihre Verteidigung gegen sie selber richten!\n\n<Der Springer starrt Euch mit seinem einen Auge durchdringend an und kichert hysterisch.>\n\nBringt eine Harpunenkanone auf den Plattformen, welche die Klippen auf jeder Seite von Valhalas gen Südwesten überragen, unter Eure Kontrolle. Kümmert Euch um die Protodrachen und ihre Reiter. Schießt sie ab!", progress = nil, completion = "Ihr seid ein wahrer Held für unsere Sache, &lt;Name&gt;!\n\nKommt Ihr bitte morgen wieder bei mir vorbei? Ich bin mir sicher, dass es dann wieder mehr von diesen fiesen Protodrachen abzuschießen gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13070] = {title = "Eine Kaltfront nähert sich", objective = "Meldet Euch bei Belagerungsmeister Fezzik bei der Argentumvorhut in Eiskrone.", description = "Der Frost des Todes regt sich im Westen und droht, unsere Herzen und Seelen in dieser Ödnis einzufrieren, uns an ihren dunklen Meister zu binden. Aber wir werden nicht weichen und wir werden kämpfen!\n\nDie Vorbereitungen sind angelaufen. Meldet Euch bei Belagerungsmeister Fezzik am Haupttor für Euren Auftrag.", progress = nil, completion = "Wir müssen schnell sein, sonst wird uns die Geißel holen! Wir haben wirklich keine Zeit für Instruktionen, &lt;Volk&gt;. Ihr werdet wohl einfach hineinhüpfen und auf das Beste hoffen müssen.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13071] = {title = "Ekel mag Feuer!", objective = "Ekel im Schattengewölbe möchte, dass Ihr einen Protodrachen von Njorndar stehlt und ihn benutzt, um 8 Vrykulgebäude in der weiteren Jotunheimregion in Brand zu setzen.\n\nDie Festung Balargarde kann aufgrund ihrer Beschaffenheit nicht in Flammen gesetzt werden.", description = "Ekel mag Feuer! Ekel mag Protodrachen!\n\n<Die Monstrosität klatscht aufgeregt in die Hände.>\n\nKleiner <Name> jetzt gehen nach Jotunheim un' stehlen schöne Protodrache in Njorndar. Lass' Protodrache schöööne Feuers auf Häuser von Jotunheim machen!", progress = nil, completion = "Hurra, hurra! &lt;Name&gt; ist allerbeste Protodrachen-Klauer.\n\nDu kommen zurück morgen und wir machen meeehr Feuer!!!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13072] = {title = "Ein Held verbleibt", objective = "Bringt die Neuigkeiten von Kreuzfahrer Bridenbrads Schicksal zu Hochlord Tirion Fordring in den Kreuzfahrerturm.", description = "Ich weiß, warum Ihr gekommen seid... sie haben Euch geschickt um mich zurückzubringen, aber das darf nicht geschehen. Ich trage die Seuche des Todes in mir, <Klasse>, und werde mein Schicksal nicht mit jenen teilen, die mir nahe stehen. Nein, ich werde hier bleiben. \n\nIch bedaure nur, was aus mir werden wird, wenn der Tod Besitz von mir ergriffen hat. Den Tod selbst fürchte ich nicht, aber ich verabscheue den Gedanken daran, dem Verräter Arthas zu dienen.\n\nVerlasst mich... und stellt sicher, dass niemand anderes nach mir suchen wird. Ihr würdet mir einen wahren Undienst erweisen, wenn Ihr jemanden der Seuche, die ich trage, aussetzen würdet.", progress = nil, completion = "Bridenbrad wurde von der Seuche befallen? Ich kann mir kein schlimmeres Schicksal für jemanden vorstellen, der sein Leben dem Weg des Lichts gewidmet hatte; noch kann ich mir vorstellen, ihn sterbend zurückzulassen und dabei tatenlos zuzusehen.\n\nNein, der Untod soll sein Schicksal nicht sein. Wir werden einen Weg finden, diesem Helden beizustehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13073] = {title = "Eine Bitte an den Bewahrer", objective = "Hochlord Tirion Fordring im Kreuzfahrerturm hat Euch gebeten, dass Ihr bei der Erzdruidin Lilliandra Zugang erbittet und mit Bewahrer Remulos redet.", description = "Es gibt jene in dieser Welt, die auf Kräfte stoßen, die frei sind von den Grenzen unserer sterblichen Hüllen - Kräfte der Wiederherstellung, des Lebens und des Lichts. Und Bridenbrad? Das ist kein durchschnittlicher Mann... sein Heldenmut und seine Hingabe sind ein leuchtendes Vorbild. Wir können nur hoffen, dass eines dieser Wesen einschreiten wird und diesen Helden vor einem Schicksal, das schlimmer als der Tod ist, bewahren wird.\n\nGeht nun und sprecht mit der Erzdruidin Lilliandra in der Argentumvorhut... erbittet den Zugang zur Mondlichtung und ersucht Bewahrer Remulos um Hilfe.", progress = nil, completion = "Hallo, mein Kind.\n\nIch verstehe Tirions Bitte und habe Vertrauen in sein Urteilsvermögen. Wir werden sehen, was wir für Kreuzfahrer Bridenbrad tun können. Wonach Ihr fragt, ist keine Leichtigkeit - die Geißel ist nicht von dieser Welt und viele sind im Laufe der Jahre bei dem Versuch gescheitert, ihre Verderbnis zu durchbrechen.\n\nBei einem Lebewesen von Erhabenheit und Licht ist jedoch nicht alle Hoffnung verloren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13074] = {title = "Hoffnung im Smaragdgrünen Alptraum", objective = "Bewahrer Remulos auf der Mondlichtung hat Euch aufgetragen, den Smaragdgrünen Traum zu betreten und 3 Smaragdgrüne Eicheln zu besorgen.\n\nVerlasst die nähere Umgebung des Schreins von Remulos, um nach Azeroth zurückzukehren.", description = "Was wir brauchen, gibt es nur im Smaragdgrünen Traum... Eicheln, die mit einem mächtigen, regenerativen Zauber durchtränkt sind. Viele Orte in diesem heiligen Sumpf sind eng mit dem Traum verbunden und mein Schrein ist einer davon.\n\nIch werde Euch in den Traum schicken, um ein paar jener Eicheln zu besorgen. Seid aber gewarnt, <Klasse>, denn diese Methode, den Traum zu betreten, ist gefährlich, und es ist recht wahrscheinlich, dass Ihr von Alpträumen heimgesucht werdet.\n\nBeeilt Euch und findet ein paar Eicheln. Verlasst anschließend meinen Schrein oder kneift Euch selbst in den Arm, um in unsere Welt zurückzukehren.", progress = "Gut zu sehen, dass Ihr in Sicherheit seid. Habt Ihr alle Eicheln gefunden?", completion = "Hervorragende Arbeit, mein Junge.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nNaturzauber\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13075] = {title = "Remulos' Segen", objective = "Kehrt mit der Smaragdeichel zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.", description = "Ich werde ein Portal öffnen, das Euch zu dem Druiden, der Euch hergesandt hat, zurückbringen wird. Meine besten Wünsche begleiten Euch und Euren Kreuzfahrer. Ich hoffe, diese Eichel wird ihn läutern und somit vor dem abscheulichen Schicksal der Seuche bewahren können.\n\nLebt wohl, <Volk>.", progress = "Seid gegrüßt, <Klasse>. Ich wusste, dass Ihr zurückkehren würdet, ungeachtet meiner Warnungen... Aber ich bin froh, dass Ihr meiner Bitte nachkommt, niemand anderen zu gefährden.\n\nWarum seid Ihr zurückgekehrt?", completion = "Tirion hat Euch zu Remulos gesandt? Ich... fühle mich geehrt. Man richtet nicht leichtfertig seine Bitten an Wesen von solcher Macht, ganz gleich, wie edel und uneigennützig sie sein mögen. Ich danke Euch, dass Ihr derartige Mühen meinetwegen auf Euch genommen habt.\n\nPflanzt den Samen ein... Ich bin bereit.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSmaragdeicheleffekt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13076] = {title = "Es bleibt noch Zeit", objective = "Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten der Smaragdeichel.", description = "Ich fühle mich erfrischt... erneuert... aber die Seuche hält mich immer noch in ihrer eisigen Umklammerung. Ich bin Euch dennoch auf ewig dankbar für die Mühen, die Ihr für mich, einen völlig Fremden, auf Euch genommen habt. Zumindest habt Ihr mir so einige wertvolle Stunden verschafft, während derer ich nicht als grässlicher Untoter die Welt verpeste.\n\nIch danke Euch, <Klasse>. Bitte richtet auch Tirion meinen Dank aus und lasset ihn wissen, dass es mir eine Ehre war, an seiner Seite zu dienen.", progress = nil, completion = "Es erfüllt mich mit Trauer, dass es nicht funktioniert hat. Aber kein Grund zur Verzweiflung, ich habe noch andere Wesen des Guten getroffen, die uns noch immer helfen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13077] = {title = "Die Berührung eines Aspekts", objective = "Erbittet die Hilfe von Alexstrasza der Lebensbinderin im Wyrmruhtempel.", description = "Die Drachenkönigin, Alexstrasza, besitzt Magien über das gesamte Sein. In der Vergangenheit hat sie große Feuer benutzt, um Untote zu verbrennen und frisches, neues Leben an ihrer Stelle zu erschaffen. Ihre Kräfte sind vielleicht in der Lage, auch unseren Bridenbrad zu retten.\n\nAlexstrasza hat sich im Wyrmruhtempel in der Drachenöde eingerichtet. Bitte geht zu Ihr und bittet sie demütigst in meinem Namen um Hilfe.", progress = nil, completion = "Ich grüße Euch, &lt;Volk&gt;.\n\nDie Sorge steht Euch ins Gesicht geschrieben. Sagt mir, was Euch bedrückt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13078] = {title = "Dahlias Tränen", objective = "Alexstrasza die Lebensbinderin im Wyrmruhtempel verlangt von Euch, dass Ihr Dahlias Tränen aus dem Boden bergt, der von den Flammen der Rubinbehüter frisch geläutert ist.", description = "In dieser dunklen Stunde werde ich nicht diejenige sein, die einen Helden des Lichts im Stich lässt.\n\nWir werden etwas Heiliges brauchen, um auf die Rettung Eures Bridenbrads hoffen zu können... Das Überbleibsel eines frommen Wesens, das Opfer eben dieser Seuche wurde.\n\nGeht nun zum heiligen Boden in den Gängen außerhalb meines Rubindrachenschreins, dorthin, wo der Kampf stattfinden wird. Meine Rubinhüter werden herabfliegen und den Boden unter untoten Füßen mit Flammen überziehen. Ihr werdet dann Zeuge neuen Lebens sein. Dieses neue Leben wird auch Dahlias Tränen bergen - bringt sie mir.", progress = "Ah, liebste Dahlia. Ich vermisse dich so...", completion = "Mithilfe von Dahlias Tränen und uralter Magie kann ich Euch ein kleines bisschen Hoffnung für Euren großen Kreuzfahrer verschaffen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCosmetic Fire Cast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13079] = {title = "Alexstraszas Segen", objective = "Bringt den Atem von Alexstrasza zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone.", description = "Ihr müsst verstehen, <junger/junge :r> <Volk>, dass das Läutern eines Körpers zugunsten des Lebens etwas ist, das durchaus in meiner Macht liegt... die Seuche des Untodes zu entfernen, ohne den Körper in Mitleidenschaft zu ziehen, entzieht sich jedoch meiner Kontrolle.\n\nWenn dieser Bridenbrad das Leuchtfeuer des Lichts ist, wie Ihr es beschwört, wird er vielleicht die Läuterung überstehen und sich erholen, aber ich kann nicht mit Gewissheit sagen, ob dies die Erlösung sein wird, nach der Ihr strebt. Nehmt sie und geht mit all meinem Segen.", progress = "Ihr seid schon wieder hergekommen, <Klasse>. Warum setzt Ihr Euch diesem Risiko aus?", completion = "Der Atem von Alexstrasza... Ihr seid zur Drachenkönigin höchstpersönlich gegangen? Ich bin Euch unsäglich dankbar.\n\nIch bin mir der Risiken einer solchen Läuterung bewusst und bin bereit. Fahrt fort, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Breath of Alexstrasza\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13080] = {title = "Die Hoffnung stirbt zuletzt", objective = "Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten des Atems von Alexstrasza.", description = "<Bridenbrad erhebt die Hand zum Gruße, während er wieder zu Atem kommt.>\n\nEs war fast so schmerzhaft, wie es ausgesehen hat, aber es fühlte sich an, als wäre ein Teil der Verderbnis aus meinem Körper gebrannt worden. Anscheinend ist die Seuche jedoch so einfach nicht zu bezwingen.\n\n<Klasse>, danke für alles, was Ihr getan habt. Eure selbstlosen Taten haben meine Hoffnung genährt, dass es noch immer viel Gutes in der Welt gibt...Ich kann nun gehen, ohne Furcht davor, dass die Dunkelheit in meiner Abwesenheit obsiegen wird.\n\nIhr könnt nun ohne Bedenken gehen.", progress = nil, completion = "Die Seuche der Geißel ist kein leicht zu bezwingender Feind. Alexstraszas Worte legen nahe, dass wir unseren treuen Bridenbrad noch immer vor dem unvorstellbaren Schicksal des Untodes bewahren könnten, sollte er fallen, aber so leicht gebe ich ihn nicht auf.\n\nEs gibt noch einen Weg des Lichts, den ich gerne beschreiten würde. Ein weiteres Wesen, das dieses schreckliche Schicksal abwenden könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13081] = {title = "Der Wille der Naaru", objective = "Erbittet die Hilfe von A'dal in Shattrath in den Wäldern von Terokkar.", description = "Ich bin dankbar für alles, was Ihr für uns getan habt, <Name>. Ich habe noch einen letzten Auftrag für Euch... ein letztes Glimmen der Hoffnung für einen Paladin, der jede Erlösung verdient, die wir ihm bieten können.\n\nGeht nun nach Shattrath und sprecht mit dem Naaru A'dal. Er ist seit langem ein Leuchtfeuer des Lichts und mächtiger Verbündeter der Paladine. Berichtet ihm von Bridenbrad und erbittet jede Hilfe, die er Euch zu geben vermag.\n\nIch kann nicht genug betonen, wie wichtig es ist, dass Ihr Euch beeilt... Ich befürchte, dass unserem Kreuzfahrer nicht mehr viel Zeit in dieser Welt verbleibt.", progress = nil, completion = "&lt;Ein sanftes Klingen erfüllt Euren Kopf, als Ihr Euch dem Naaru nähert.&gt;\n\nIch weiß, warum Ihr hergekommen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13082] = {title = "A'dals Segen", objective = "Kehrt zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.", description = "Ich bin erfreut, dass Ihr zu mir gekommen seid, <Name>. Ich weiß von Kreuzfahrer Bridenbrad und von Euren Reisen, um ihn zu erretten. Bridenbrads Heldenmut hat eine bemerkenswerte Selbstlosigkeit in Euch zum Vorschein gebracht, und das ist an sich schon ein Wunder.\n\nDas Licht wird sich um die Seinen kümmern. Ich werde Bridenbrad meinen Segen zuteilwerden lassen, auf dass er die Verderbnis des Untodes nicht länger zu ertragen braucht. Ich werde Euch zurück nach Dalaran schicken und Ihr werdet zu ihm zurückkehren. Wisset, dass ich stets bei Euch sein werde.", progress = nil, completion = "&lt;Als Ihr Euch Kreuzfahrer Bridenbrad nähert, müsst Ihr feststellen, dass seine Haut eine fahle Farbe angenommen hat und sein Atem sehr flach geht. Es ist klar, dass er nicht mehr lang zu leben hat.&gt;\n\nIhr seid zu mir zurückgekehrt, &lt;Klasse&gt;. Ich muss zugeben... dass es gut ist, Euch wiederzusehen... Euer Antlitz erneuert meine Hoffnung, dass dieses Land eines nicht zu fernen Tages von Arthas' eisigem Griff befreit sein wird. Ich bin stolz darauf, Euch gekannt zu haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Bridenbrad Ascension\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13083] = {title = "Licht im Dunkeln", objective = "Bringt Kreuzfahrer Bridenbrads Wappenrock zu Hochlord Tirion Fordring in den Kreuzfahrerturm.", description = "<Kreuzfahrer Bridenbrads Wappenrock liegt am Boden der Truhe und beginnt leicht zu flattern, als der heulende Wind seinen Weg hineinfindet.>\n\nTirion wird dieses letzte Überbleibsel des großen Kreuzfahrers an sich nehmen wollen.", progress = "Er ist also von uns gegangen, nicht wahr? Ich habe gespürt, wie das Land um etwas Licht ärmer geworden ist.", completion = "Ich bin froh, dass Ihr ihn vor dem Untode bewahren konntet. Mit dem Segen A'dals wird ihm im Jenseits kein Übel widerfahren.\n\nWir werden uns ein Beispiel an seinem leuchtenden Vorbild und an Eurer Selbstlosigkeit nehmen. Ich danke Euch für alles, was Ihr getan habt.", rewards = "Bridenbrads SchärpeGürtel des niemals VergessenenKettengürtel der ErinnerungGurt der ewigen ErinnerungAuf Euch wartet eine dieser Belohnungen:\n\nBridenbrads Siegel\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13084] = {title = "Demoliert Jotunheim", objective = "Herzog Lankral beim Schattengewölbe möchte, dass Ihr 10 Banner der Vrykul verbrennt.", description = "Lasst uns doch mal sehen, ob wir noch weiter die Entschlossenheit der Vrykul schwächen können, <Name>.\n\nIch möchte, dass Ihr jeden Tag nach Jotunheim geht und ihre Banner verbrennt. Das mag sich nach einer unbedeutenden Sache anhören, aber wenn sie ihre Heimatstadt jeden Tag demoliert sehen, wird dies ihre Moral weit mehr schwächen, als es jede physische Gewaltmaßnahme je könnte.\n\nZumindest aber... kann es nicht schaden.", progress = nil, completion = "&lt;Der Herzog schaut Euch einen Moment lang an, dann nickt er.&gt;\n\nIhr richtet ein verheerendes mentales Trauma unter den Vrykul von Jotunheim an. Es ist der Ort, an dem sie das erste Mal wiedererweckt wurden. Ein Ort von herausragender Bedeutung für sie, übertroffen nur von Ymirheim.\n\nIhr müsst den Druck dort aufrechterhalten, während ich die Streitkräfte des Lichkönigs vom Schattengewölbe abhalte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13085] = {title = "Vaelen ist zurückgekehrt", objective = "Redet mit Vaelen dem Geschundenen im Schattengewölbe.", description = "Ich habe soeben diesen inkompetenten Narren, Vaelen den Geschundenen, gesehen, wie er in das Schattengewölbe geschlichen ist.\n\nGeht und stellt sicher, dass er seinen Fehler wieder gutmacht und mir meine Todesritter zurückbringt!", progress = nil, completion = "Ich denke, ich weiß, warum Ihr hier seid, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13086] = {title = "Die letzte Verteidigungslinie", objective = "Benutzt eine Argentumkanone, um 100 Angreifer der Geißel zu vernichten. Außerdem müsst Ihr 3 Frostbrutzerstörer töten.\n\nSolltet Ihr erfolgreich sein, kehrt zu Belagerungsmeister Fezzik zurück.", description = "Ich habe die Verteidigungen der Basis aktiviert, <Klasse>! Auf jedem der vier Türme der Vorhut ist eine einziehbare Kanone des Argentumkreuzzugs angebracht, von Vater Gustav persönlich geweiht. Ihr müsst zu einer der Kanonen fliegen und sie bemannen. Benutzt sie, um den Ansturm der Geißel zu vernichten, den der Lichkönig hergesandt hat.\n\nEine Warnung noch, die Geißel wird zweifelsohne ihre Frostwyrms schicken, um die Türme zu belagern. Blast sie vom Himmel! Wenn sie die Türme und Wälle der Basis zerstören, sind wir geliefert!", progress = "Die Schreie der Sterbenden werden mich mein Leben lang verfolgen! Helft ihnen!", completion = "Ihr habt die Kanone wie ein echter Goblinkanonier geführt, Freund. Ihr habt die Vorhut und den Argentumkreuzzug gerettet... und dabei den Hochlord selbst auf dem Schlachtfeld unterstützt. Unglaublich!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMoral des KanoniersFezziks TaschenuhrLuntenanzünder des Kanoniers\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13087] = {title = "Kochkunst des Nordens", objective = "Bringt 4 Stück kühles Fleisch zu Brom Bräugießer in Valgarde. Jede Bestie in Nordend verfügt über dieses Fleisch.", description = "Also was machen wir denn da, wenn Ihr keinen Eintopf für mich habt? Ich hab' HUNGER! Ihr könnt mir zumindest ein wenig kühles Fleisch bringen, damit ich mir selbst 'nen Eintopf machen kann! Wenn Ihr das macht, dann kann ich Euch ein Rezept geben, damit Ihr Euren eigenen machen könnt. JETZT GEHT UND BRINGT MIR EIN BISSCHEN FLEISCH!", progress = "WO IST MEIN FLEISCH!", completion = "Du hast mein Fleisch! Hier ist dein Rezept - ich hab' zu kochen!", rewards = "Ihr erlernt:\n\nNordischer Eintopf\n\nDer folgende Zauber wird auf euch gewirkt:\n\nNordischer Eintopf\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13088] = {title = "Kochkunst des Nordens", objective = "Bringt Rollick MacKreel in der Valianzfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.", description = "Wir haben eine Menge neuer Rekruten hier und die Jungs sind hungrig! Wenn Ihr mir ein wenig kühles Fleisch für einen Eintopf besorgen könntet, würde ich Euch beibringen, wie Ihr selbst einen für Euch kochen könnt.", progress = "Die Jungs brauchen Fleisch für ihren Eintopf.", completion = "Das wird unsere Rekruten satt halten! Hier ist das Kochrezept dafür.", rewards = "Ihr erlernt:\n\nNordischer Eintopf\n\nDer folgende Zauber wird auf euch gewirkt:\n\nNordischer Eintopf\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13089] = {title = "Kochkunst des Nordens", objective = "Bringt 4 Stück kühles Fleisch zu Thomas Kolichio im Hafen der Vergeltung. Alle Bestien in Nordend verfügen über dieses Fleisch.", description = "Nichts wärmt die Knochen besser, als ein aus lebenden Wesen zubereiteter Eintopf. Bringt mir etwas von dem kühlen Fleisch der hiesigen jämmerlichen Bestien und ich werde Euch zeigen, wie man einen warmen Eintopf zubereitet.", progress = "Der Eintopf wartet...", completion = "Wir können das Fleisch im Handumdrehen zu Eintopf verarbeiten.", rewards = "Ihr erlernt:\n\nNordischer Eintopf\n\nDer folgende Zauber wird auf euch gewirkt:\n\nNordischer Eintopf\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13090] = {title = "Kochkunst des Nordens", objective = "Bringt Orn Zarthuf in der Kriegshymnenfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.", description = "Die Krieger der Kriegshymnenoffensive brauchen etwas in ihren Bäuchen, um stark zu bleiben. Falls Ihr mir ein wenig kühles Fleisch von den Rhinozerossen oder den anderen Bestien besorgt, könnte ich ein bisschen Eintopf für sie kochen. Wenn Ihr mir helft, werde ich Euch das Rezept verraten.", progress = "Wenn das Fleisch hier ist, wird der Eintopf gekocht.", completion = "Ihr habt meinen Dank.", rewards = "Ihr erlernt:\n\nNordischer Eintopf\n\nDer folgende Zauber wird auf euch gewirkt:\n\nNordischer Eintopf\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13091] = {title = "Die Kunst, ein Wasserschrecken zu sein", objective = "Die Knochenhexe in Njorndar möchte, dass Ihr Besitz von einem Wasserschrecken ergreift und ihn dazu benutzt, 10 Vrykul in der Umgebung von Jotunheim zu töten.\n\nIn Frage kommende Vrykul sind Schlafwächter, Krieger von Jotunheim, Wassermagier der Mjordin, Speerschwestern von Njorndar und Varguls von Valhalas.", description = "Die Wasserschleuse vor meiner Höhle wimmelt nur so von Elementaren, die von den Vrykulzauberern erst noch gezähmt werden müssen. Ich werde Euch einen Trick zeigen, wie man für kurze Zeit Besitz von ihnen ergreifen kann, und Ihr werdet sie dafür einsetzen, Chaos und Zerstörung in Jotunheim anzurichten!\n\n<Die Banshee-verseuchte Vrykul entzieht der Luft Magie und berührt Eure Stirn.>\n\nGeht nun und öffnet die Tür zur Schleuse. Ein Wasserschrecken wird hervorkommen und Ihr werdet ihn kontrollieren, um unsere Feinde zu zerstören!", progress = "Die Knochen verraten mir, dass Ihr noch nicht ganz fertig seid.", completion = "Noch nie habe ich in den Augen eines Vrykuls solches Entsetzen gesehen - und sie halten sich für die Herren ihrer Welt.\n\nWir beide werden beweisen, dass sie falsch liegen... sehr falsch.", rewards = "Pantalons der WassermagiSpeerschwesternmantelJotunheimfesselnVerbund des SchlafwächtersDer folgende Zauber wird auf euch gewirkt:\n\nThe Art of Being a Water Terror: Quest Complete Script Effect\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13092] = {title = "In den Knochen lesen", objective = "Die Knochenhexe in Njorndar hat Euch aufgetragen, 15 Vrykulknochen zu besorgen.", description = "Einer der Vorteile davon, Besitz von dieser Kreatur zu ergreifen, ist, dass ich Zugriff auf all ihre Kräfte habe. Als Knochenhexe und Runenleserin hat sie die Macht, Knochen auszuwerfen und daraus jemandes Schicksal zu lesen.\n\n<Die Knochenhexe schmunzelt.>\n\nGut für Euch, dass es in meiner Macht steht, das Resultat zu beeinflussen.\n\nBringt mir die Knochen von Vrykul, die Ihr hier in Jotunheim tötet, und ich werde sie so werfen, dass Ihr Euer Schicksal bestimmen könnt.", progress = "Ich finde es bemerkenswert, dass diese Wesen jemals die Welt beherrschen konnten, wo sie lediglich über solch primitive Magie verfügten.", completion = "Nun werden wir sehen, was die Zukunft für Euch bereithält.\n\n&lt;Die Knochenhexe wirft die Knochen auf den Teppich vor sich.&gt;\n\nWählt Euer Schicksal, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchicksalsrune der schändlichen AbsichtenSchicksalsrune der flinken FüßeSchicksalsrune der schieren UnverwundbarkeitSchicksalsrune der urtümlichen EnergieSchicksalsrune der unübertroffenen Lebenskraft\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13093] = {title = "In den Knochen lesen", objective = "Bringt noch mehr Vrykulknochen und wir werden dafür sorgen, dass sich das Schicksal zu Euren Gunsten wendet.", description = nil, progress = "Bringt noch mehr Vrykulknochen und wir werden dafür sorgen, dass sich das Schicksal zu Euren Gunsten wendet.", completion = "Wählt Euer Schicksal, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchicksalsrune der schändlichen AbsichtenSchicksalsrune der flinken FüßeSchicksalsrune der schieren UnverwundbarkeitSchicksalsrune der urtümlichen EnergieSchicksalsrune der unübertroffenen Lebenskraft"}
MultiLanguageQuestData['de'][13094] = {title = "Schämen sie sich denn nicht?", objective = "Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.", description = "Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.\n\nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Horde darüber zu unterhalten, und nun ist es weg!\n\nSie müssen es gewesen sein, <Klasse>. Bitte beschafft das Buch.", progress = "Bitte, <Name>, sagt mir, dass Ihr das Buch gefunden habt...", completion = "Ihr habt es gefunden?! Ja, ja, alles ist da.\n\nHier, bitte, nehmt dies als Zeichen meines Dankes.", rewards = "Schultern des NordlichtsGeschmeidiger MammutbalgmantelSchulterschutz des TundrafährtenlesersTundraschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13095] = {title = "Schämen sie sich denn nicht?", objective = "Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.", description = "Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.\n\nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Allianz darüber zu unterhalten, und nun ist es weg!\n\nSie müssen es gewesen sein, <Klasse>. Bitte beschafft das Buch.", progress = "Bitte, <Name>, sagt mir, dass Ihr das Buch gefunden habt...", completion = "Ihr habt es gefunden?! Ja, ja, alles ist da.\n\nHier, bitte, nehmt dies als Zeichen meines Dankes.", rewards = "Schultern des NordlichtsGeschmeidiger MammutbalgmantelSchulterschutz des TundrafährtenlesersTundraschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13096] = {title = "Gal'darah muss bezahlen", objective = "Tol'mar in Dubra'Jin möchte, dass Ihr Gal'darah in Gundrak erschlagt.", description = "Hast du's gesehen, Mann?\n\nEs muss wohl das Furchtbarste gewesen sein, das ich jemals gesehen hab'. Der große Akali: vor meinen Augen getötet. Schrecklich...\n\nIch habe geschworen, mich nicht in die Sache hier verwickeln zu lassen. Ich soll nur beobachten. Doch das kann so nicht hingenommen werden! Gal'darah muss dafür bezahlen!\n\nGeh nach Gundrak und such ihn auf. Komm zu mir zurück, sobald Akalis Tod gerächt wurde, Mann.", progress = nil, completion = "Du hast es getan?! Gal'darah gibt es nich' mehr?\n\nHier, Mann, nimm. Ist'n Geschenk dafür, dass du diesem Mistkerl seine gerechte Strafe erteilt hast.", rewards = "Listige MojoscherpeSeltsamer VoodoogürtelWaldläufergürtel des gefallenen ImperiumsSchnalle des gefallenen HalbgottsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13097] = {title = "Offene Rechnungen", objective = "Har'koa möchte, dass Ihr mit Tol'mar in Dubra'jin sprecht.", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, <Name>, macht Euch von Gundrak aus in nördliche Richtung nach Dubra'Jin und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", progress = nil, completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13098] = {title = "Für die Nachwelt", objective = "Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und 6 Geschichtstafeln der Drakkari sammelt.", description = "Gundrak ist verloren, Mann.\n\nDie Geschichte wird sich vor deinen Augen wiederholen. Wenn Trolle sich gegen ihre eigenen Götter wenden, dann ist's das sichere Ende. Es ist nur eine Frage der Zeit.\n\nWenn wir die Ereignisse bis ins Detail erfassen können, dann würde sich vielleicht verhindern lassen, dass zukünftige Generationen denselben dunklen Weg einschlagen.\n\nWenn du mutig genug bist, dann geh nach Gundrak und such nach Hinweisen darüber, was dazu geführt hat, dass das Reich der Drakkari so enden musste.", progress = "Hast du die Geschichtstafeln der Drakkari gefunden, Mann?", completion = "&lt;Bah'Kini überfliegt die Worte auf den Tafeln nur kurz und widmet Euch dann wieder ihre Aufmerksamkeit.&gt;\n\nDie sind echt, &lt;Volk&gt;. Sie werden ihren angestammten Platz in meiner Sammlung finden.\n\nVielleicht können wir diesem Treiben endlich ein Ende machen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des LöwenkopfesRing des faulen MojosSolides PlatinbandVoodoosiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13099] = {title = "Nur ma' nachsehen", objective = "To'kini möchte, dass Ihr mit Bah'kini in Dubra'Jin sprecht.", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", progress = nil, completion = "Ne langjährige Schülerin? Ha!\n\nWenn'a mit \"langjährig\" n' ganzes Leben meint, dann das stimmt das sicha, eh.\n\nTo'kini is' mein feiga Vater - zu feige, sich füa nen Posten so nah bei Gundrak zu melden... deswegen hatter mich geschickt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13100] = {title = "Energieerfüllter Pilzhackbraten", objective = "Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.", description = "Wir haben eine wichtige Lieferung zu machen! Orton Bennet bei Kuriositäten & Meer braucht einen Pilzhackbraten.\n\nBeschafft also einige energieerfüllte Pilze aus der Kanalisation von Dalaran und ein wenig kühles Fleisch und bereitet sie in Eurer Bratenform zu. Liefert den fertigen Hackbraten bei Orton ab.", progress = "Habt Ihr mir irgendwas zu essen mitgebracht?\n\nIch scheine nie von diesem Laden wegzukommen und sei es auch nur für eine Minute.", completion = "Das sieht köstlich aus! Danke!", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13101] = {title = "Versammlung im Zauberkasten", objective = "Bringt 4 nordische Eintöpfe, die Ihr selbst gekocht habt, und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.", description = "Arille Azurblick im Zauberkasten hat bald eine Versammlung bei sich und braucht so fix wie möglich ein Festmahl!\n\nIhr müsst einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen namens \"Noch ein Gläschen\" in der Mitte von Dalaran beschaffen. Der Besitzer des Käseladens schuldet mir den Wein - Ihr werdet ihn irgendwo im Laden finden.\n\nBringt die Eintöpfe und den Wein zu Arille.", progress = "Wo ist mein Essen? Die Versammlungsmitglieder könnten jeden Augenblick hier sein!", completion = "Das ist genug Essen für alle! Ich bin mir sicher, dass die Kunden zufrieden sein werden.", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13102] = {title = "Kanaleintopf", objective = "Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nBringt den fertigen Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.", description = "Ajay Grün, der Gastwirt in der Kanalisation von Dalaran, braucht einen Gemüseeintopf für seine Kunden, da ihnen dort unten das Essen ausgeht.\n\nSammelt 4 Kristallsangkarotten aus dem Kristallsangwald, gebt sie gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nDen Kristallsangwald könnt Ihr über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.\n\nBringt den Gemüseeintopf zu Ajay, sobald er fertig gekocht ist.", progress = "Ich hab' hungrige Leute dort unten! Wir brauchen etwas Eintopf.", completion = "Das wird im Nu weg sein! Danke!", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13103] = {title = "Käse für Leuchtegold", objective = "Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.\n\nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.", description = "Ranid Leuchtegold im Lederladen in Dalaran hatte plötzlich ein heftiges Verlangen nach Wein und Käse.\n\nIm Laden \"Noch ein Gläschen\" in der Mitte von Dalaran gibt es ein Regal mit Käse - holt Euch etwas davon und sammelt dann noch einige halbvolle Weingläser ein, die überall in Dalaran verstreut herumstehen. Danach sollt Ihr den Wein in eine Flasche füllen und diesen dann gemeinsam mit dem Käse Ranid servieren.\n\nWir denken, dass er den Unterschied nicht bemerken wird.", progress = "Habt Ihr einen Diener mit meiner Wein- und Käseplatte gesehen? Mich hat der kleine Hunger gepackt!", completion = "Aha, das scheint mir ein guter Jahrgang zu sein!", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13104] = {title = "Noch einmal in die Bresche, Held", objective = "Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.", description = "Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!\n\nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.\n\nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.", progress = nil, completion = "Meine Kenntnisse der Taktiken der Geißel sind ohne Gleichen.\n\n&lt;Der Schwarze Wächter mustert Euch.&gt;\n\nVor der Schlacht um die Kapelle des hoffnungsvollen Lichts dienten meine Ritter und ich dem Lichkönig... sein eisiger Griff kontrollierte jede unserer Handlungen. Das Licht der Morgendämmerung hat alles verändert...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13105] = {title = "Noch einmal in die Bresche, Held", objective = "Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.", description = "Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!\n\nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.\n\nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.", progress = nil, completion = "Eure Macht ist gewachsen, getreuer Ritter.\n\n&lt;Hochlord Darion Mograines Blick ist auf Euch gefallen.&gt;\n\nUnsere Rache wird bald vollzogen, Bruder. Koltira steht der Horde auf der Orgrims Hammer bei, während Thassarian die Allianz auf der Himmelsteiler unterstützt. Die Schwarze Klinge wird schon bald über Eiskrone hinwegfegen und die Armeen des Lichkönigs vernichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13106] = {title = "Die Schwarzwacht", objective = "Sprecht mit Dunkelreiterin Arly in der Schwarzwacht in Eiskrone.", description = "Die Geißel verfügt über eine große Einrichtung, genannt die Fleischwerke, die zur Produktion von Monstrositäten und Fleischriesen dient. Wenn wir sie ausschalten könnten, würden wir den Lichkönig eines Gutteils seiner Armee berauben.\n\nIch habe Dunkelreiterin Arly in die Gegend entsandt. Sie hat westlich von Corp'rethar auf einem Höhenrücken eine kleine Basis errichtet, die Schwarzwacht, von wo aus sie die Fleischwerke überblicken kann. Ich habe gehört, dass der Argentumkreuzzug jemanden entsandt hat, um ihre Bemühungen dort zu koordinieren, aber die Dunkelreiterin wird wissen, was zu tun ist.", progress = nil, completion = "Gut. Wir brauchen jede Hilfe, die wir kriegen können. Olakin hier ist der Beitrag des Argentumkreuzzugs zu unseren Bemühungen. Lassen wir das Gequatsche und machen wir uns an die Arbeit, die Geißel ihrer Krieger aus Fleisch zu berauben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13107] = {title = "Senfwürstchen!", objective = "Füllt den leeren Picknickkorb mit 4 Rhinowürstchen, die Ihr selbst gekocht habt, und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.\n\nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran.", description = "Erzmagier Pentarus sieht sich gelegentlich gerne ein Kampfballspiel an und möchte auch gehen, doch er braucht für die Reise etwas zu essen.\n\nIhr müsst seinen Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Bereichen der Stadt zu finden.\n\nBringt ihm seinen Picknickkorb, damit er bereit für das große Spiel ist.", progress = "Bin fast startklar - muss nur noch auf das Essen und... ähm... meine Magierkollegen warten.", completion = "Perfekt! Ich hoffe nur, dass die Dalaraner Demolierer endlich mal ein Spiel gewinnen werden!", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13108] = {title = "Koste es, was es wolle!", objective = "König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Loken besiegt. Danach sollt Ihr mit Lokens Zunge zu König Jokkum zurückkehren.", description = "So oder so, Loken wird sterben.\n\nSelbst wenn ich ihm alle Gliedmaßen einzeln herausreißen muss, wird er schon bald für seine Taten büßen.\n\nSolltet Ihr vor mir auf ihn treffen, so mögen der Ruhm und die Ehre für seine Niederlage Euer sein.\n\nKehrt zu mir mit seiner verlogenen Zunge zurück und erhaltet dafür meinen Dank und Segen.", progress = "Wurde Loken seiner gerechten Strafe zugeführt?", completion = "Dieser niederträchtige Wurm ist tot?\n\nIhr habt Euch für mein Volk als ein wahrer Segen erwiesen, kleiner &lt;Volk&gt;.\n\nBitte nehmt dieses Geschenk als Dank für Eure loyale Freundschaft an.", rewards = "Robe des BlitzesGehärtete ZungentunikaHalsberge des BlitzschlägersBrustplatte des gezackten SteinsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13109] = {title = "Diametral entgegengesetzt", objective = "König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Volkhan besiegt.", description = "Ich muss offen zu Euch sein, <kleiner/kleine:r> <Volk>. Meine Leute sind nicht mehr dieselben, seit unsere Bande mit Thorim gebrochen sind.\n\nAls ihr Anführer wünsche ich mir nichts sehnlicher, als dass ihre Herzen heil werden und unsere Freundschaft mit dem Sturmherren erneuert wird. Mit Eurem Sieg über Fjorn habt ihr einen Schritt auf diesem Weg getan. Ich wünschte, Ihr würdet einen weiteren Schritt wagen...\n\nIn den Hallen der Blitze sitzt jemand, der selbst mächtiger als Fjorn ist und sich an unserer Existenz stört. Volkhan wird nicht eher ruhen, bis entweder er oder wir ausgelöscht sind.", progress = nil, completion = "Volkhans Schrecken wird mein Volk nicht länger bis in den Schlaf verfolgen.\n\nSetzt Eure Bemühungen fort, kleiner &lt;Volk&gt;. Ich bin mir sicher, dass meine Leute Thorim mit der Zeit vergeben werden.", rewards = "Blitzerfüllte MantelungVerkohlter LederschulterschutzSturmgeschmiedete SchulternSchulterstücke des erloschenen HassesMantelung von VolkhanIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13110] = {title = "Die rastlosen Toten", objective = "Vater Gustav im Tal der Echos in Eiskrone möchte, dass Ihr die Überreste von wiedererweckten Kreuzfahrern mit Weihwasser benetzt, um 10 ruhelose Seelen zu befreien.", description = "Nicht all unsere Soldaten haben es lebend aus Geißelholme herausgeschafft. Viele wurden getötet und in entartete Reflexionen ihres früheren Selbst verwandelt. Das ist der Weg der Geißel. Für jene armen Verdammten gibt es keinen ewigen Frieden. Wir müssen ihren Seelen Ruhe verschaffen.\n\nReist durch die Bresche nach Geißelholme und tötet die skelettartigen wiedererweckten Kreuzfahrer. Sprenkelt dieses Weihwasser über ihre Gebeine, so dass ihre Seelen befreit werden können.", progress = "Es ist eine makabere Aufgabe, <Name>, aber sie muss getan werden.", completion = "Der Weg des rechtschaffenen Kreuzfahrers ist von Ungerechtigkeit und Übel gesäumt. Rettung kann es nur geben, wenn man nicht vom Weg abweicht. So, wie Ihr es heute vorgelebt habt.", rewards = "Die ArgentumentschlossenheitKlinge der EchosStab der erlösten SeelenGustavs HandIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13111] = {title = "Einzigartig", objective = "Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und ein Fragment des Kolosses der Drakkari beschafft.", description = "Hör zu, Mann.\n\nAuf den ersten Blick sieht es so aus, als würde es sich hierbei wieder um die alte Leier handeln: Trolle, die verbotene Kräfte anzapfen und genau die Wesen zerstören, die sie eigentlich anbeten sollten.\n\nIn dem Fall stimmt es zwar auch, doch an diesen Drakkari ist etwas Besonderes dran. Wenn das, was ich herausgefunden habe, stimmt, dann gibt es in Gundrak einen ganz besonderen Golem - einen Golem, wie er noch nie zuvor erschaffen wurde!\n\nDu willst ein Abenteuer, Mann? Dann geh nach Gundrak und bring mir ein Stück dieses Golems, damit ich es untersuchen kann.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", rewards = "Pelzbesetzte MokassinsRhinozerosbalgkniestiefelSchuppenstiefel der gefallenen HoffnungTrollkickerSlipper des Mojo-DojosIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13112] = {title = "Energieerfüllter Pilzhackbraten", objective = "Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.", description = "Orton Bennet bei Kuriositäten & Meer braucht 'nen Pilzhackbraten.\n\nBeschafft also 'n paar energieerfüllte Pilze aus der Kanalisation von Dalaran und etwas kühles Fleisch und bereitet sie in Eurer Bratenform zu. Das Resultat liefert Ihr dann bei Orton ab.\n\nWenn der Rat mir nur erlauben würd', meine Gnomspezialität aufzutischen, ich würd' ihnen schon zeigen, was wirklich lecker ist!", progress = "Habt Ihr etwas für mich? Ich komme so selten aus meinem Laden raus.", completion = "Hat Awilo das Essen geschickt? Versprecht Ihr mir, dass da keine Gnome drin sind?", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13113] = {title = "Versammlung im Zauberkasten", objective = "Bringt 4 nordische Eintöpfe und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.", description = "Kannst du dir das vorstellen? Die Horde hat Kannibalismus für illegal erklärt... das ist einfach nicht richtig, sag ich dir! Ich schätze mal, dass ich mich auf meine Arbeit konzentrieren sollte, wenn wir schon eine Bestellung haben.\n\nArille Azurblick im Zauberkasten hat viele Besucher bei sich, Mann. Er braucht einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen in der Mitte von Dalaran.\n\nBring also den Wein und den Eintopf zu Arille.", progress = "Wo ist das Essen? Meine Gäste werden bald hier sein!", completion = "Meine Gäste sollten das passabel finden. Sagt ihnen nur nicht, dass es von Awilo kommt.", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13114] = {title = "Kanaleintopf", objective = "Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nBringt den Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.", description = "Wir haben eine neue Bestellung. Der Gastwirt in der Kanalisation von Dalaran braucht einen Gemüseeintopf, weil seine Kunden nich' so viel zu essen haben, Mann.\n\nDer hat deswegen nach einem Gemüseeintopf gefragt, da er meinen letzten Eintopf mit dem Gnom drin nicht so gern gemocht hat. Besorg dir 4 Kristallsangkarotten aus dem Kristallsangwald, koch sie gemeinsam mit 4 Stück kühlem Fleisch und bring das Resultat anschließend zu Ajay.\n\nDu kannst den Wald über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.", progress = "Gebt Acht, dass diesmal kein Gnom im Eintopf ist!", completion = "Eintopf sieht gut aus. Danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13115] = {title = "Käse für Leuchtegold", objective = "Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.\n\nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.", description = "Ranid Leuchtegold im Lederladen verlangt es ordentlich nach Wein und Käse. Warum er keinen leckeren Gnom mag, versteh ich nicht.\n\nHol dir den Käse aus dem Käseladen in der Mitte von Dalaran und die halbvollen Weingläser, die auf den Tischen in der Stadt stehen. Geh danach zu Ranid und servier ihm Wein und Käse.\n\nDen Wein könnte man sozusagen als \"Auslese\" bezeichnen, Mann.", progress = "Habt Ihr einen Diener mit meiner Wein- und Käseplatte gesehen? Mich hat der kleine Hunger gepackt!", completion = "Dieser Wein ist ziemlich beeindruckend! Ich muss wissen, woher er kommt.", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13116] = {title = "Senfwürstchen!", objective = "Füllt den leeren Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.\n\nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran.", description = "Erzmagier Pentarus schaut sich gerne sein verrücktes Kampfballspiel an, doch dafür braucht er auch was zu essen.\n\nDu musst seinen Picknickkorb mit 4 gekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Ecken der Stadt zu finden.\n\nFüll seinen Korb mit den leckeren Senfwürstchen auf, Mann.", progress = "Stellt sicher, dass die wilden Senfwürstchen 100% Rhinozeros sind und dass kein Gnom drin ist!", completion = "Perfekt! Ich hoffe nur, dass die Dalaraner Demolierer endlich mal ein Spiel gewinnen werden!", rewards = "Ihr bekommt:\n\nKleines GewürzsäckchenFeinschmeckerpreis"}
MultiLanguageQuestData['de'][13117] = {title = "Wo kommen sie her?", objective = "Untersucht einen Beschwörungsaltar im östlichen Teil der Fleischwerke und berichtet dann Dunkelreiterin Arly bei der Schwarzwacht davon.", description = "Die unermüdlichen Lakaien des Lichkönigs arbeiten Tag und Nacht an der Erschaffung zahlloser neuer Monstrositäten und Fleischriesen da unten in den Fleischwerken.\n\nAber das war noch nicht alles. Mehr und mehr skelettene Arbeiter tauchen auf und beschleunigen die Arbeit noch zusätzlich.\n\nWenn wir nicht herausfinden, wo sie herkommen und wie sie so schnell arbeiten können, werden wir überrannt, bevor wir die Initiative übernehmen können. Sucht im Südosten und findet die Quelle dieser Skelette!", progress = "Habt Ihr den Ursprung dieser Skelette gefunden?", completion = "&lt;Ihr berichtet der Dunkelreiterin von Euren Entdeckungen beim Beschwörungsaltar.&gt;\n\nSo etwas habe ich vermutet. Das dürfen wir nicht länger zulassen. Unsere oberste Priorität ist es, diese Beschwörungsaltäre zu zerstören, dann erst kümmern wir uns um das Unheil, das die Geißel hier bereits erschaffen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13118] = {title = "Die Reinigung von Geißelholme", objective = "Der Schwarze Wächter im Tal der Echos möchte, dass Ihr 3 Hohepriester der Vergessenen Tiefen, 3 Unterkönige der Vergessenen Tiefen und 8 wiedererweckte Kreuzfahrer tötet.", description = "Die Geißel hat ihre Armeen gegen den Argentumkreuzzug gesandt und ist zurückgeschlagen worden. Was sie jetzt macht, nennt sich \"zuschlagen und niederbrennen\". Alle Gefangenen, die sie in Geißelholme gefangen halten, werden hingerichtet und als Diener des Lichkönigs wiederbelebt.\n\nOhne Zweifel wird der Argentumkreuzzug wünschen, dass Ihr seine Soldaten in Ehren verabschiedet. Etwas Derartiges werde ich nicht von Euch verlangen. Um zu siegen, müssen wir die Geißel unterschiedslos ausmerzen.\n\nZieht nach Geißelholme, nordwestlich durch die Bresche, und mäht alle nieder, die sich Euch in den Weg stellen.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihre Zahlen gering zu halten wird dem Argentumkreuzzug die Zeit geben, die er braucht, um Fuß fassen zu können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13119] = {title = "Zerstört die Altäre", objective = "Tötet Meisterbeschwörer Zarod und benutzt seinen Beschwörerstab, um den ersten, zweiten, dritten und vierten Beschwörungsaltar zu zerstören. Habt Ihr diese Aufgabe erledigt, kehrt zu Dunkelreiterin Arly bei der Scharzwacht zurück.", description = "Sie beschwören also ihre Arbeiter und Krieger an diesen Altären?\n\nDie werden als Erstes verschwinden müssen. Der Meisterbeschwörer sollte einen Stab haben, mit dem er das Portal aktivieren kann. Wenn Ihr ihn also tötet und seinen Stab nehmt, dann könnt Ihr mit ihm das Beschwörungsportal überladen und dessen Altar zerstören.\n\nFührt diese Prozedur bei allen vier Altären durch und kehrt zu mir zurück, sobald sie zerstört wurden.", progress = nil, completion = "&lt;Dunkelreiterin Arly nickt anerkennend.&gt;\n\nGut. Jetzt können wir unser Augenmerk darauf richten, den Rest der Fleischwerke zu zerstören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13120] = {title = "Todesblick", objective = "Benutzt die Kugel des Todesblicks, um Kugeln in die Kugelhalterung des Monstrositätenlabors, des Fleischriesenlabors und des Kesselbereichs zu legen. Kehrt anschließend zu Dunkelreiterin Arly in die Schwarzwacht zurück.", description = "Die Fleischwerke sind eine gewaltige Operation, und es wird schwer, alles, was sich dort abspielt, im Auge zu behalten. Zum Glück habe ich einen Plan.\n\n<Arly holt eine Kugel aus den Falten ihres Umhangs hervor und zeigt sie Euch.>\n\nDies ist eine Kugel des Todesblicks. Mit ihr können wir die Aktionen der Geißel verfolgen und entscheiden, wie wir am besten zuschlagen.\n\nLegt diese Kugeln auf die Halterungen, die in drei äußerst wichtigen Bereichen zu finden sind: im Monstrositäten- und Fleischriesenlabor gen Südwesten und auch in der Gegend um den riesigen grünen Kessel weit im Westen.", progress = "Habt Ihr diese Kugeln in ihre Halterung gelegt?", completion = "&lt;Dunkelreiterin Arly schließt ihre Augen und scheint sich auf etwas zu konzentrieren, das weit in der Ferne liegt.&gt;\n\nMit den Augen des Todes selbst beobachte ich unseren Feind. Dieses Wissen wird uns helfen, ihn endgültig zu vernichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13121] = {title = "Durch das Innere Auge", objective = "Die Knochenhexe in Njorndar hat Euch beauftragt, das Auge des Lichkönigs zu benutzen, um an Informationen zu gelangen.", description = "Wir müssen die Werkzeuge des Lichkönigs gegen ihn richten, wenn wir unseren nächsten Schritt in die Wege leiten wollen.\n\nHinter den Bergen im Südwesten liegt die Feste Kul'galar. In ihr halten sich die Orakel von Jotunheim auf, die Befehle von ihrem Meister empfangen und andere durch das Auge des Lichkönigs ausspionieren.\n\nEs ist jenes Auge, zu dem Ihr Euch durchkämpfen müsst. Obwohl man es nicht dazu verwenden kann, den Schleier um die Eiskronenzitadelle zu durchdringen, solltet Ihr dennoch Wertvolles mit seiner Hilfe herausfinden können, so dass wir wissen werden, wie wir am besten weiter vorgehen.", progress = nil, completion = "Perfekt! Es ist wahr, dass Iskalder angeblich der größte Vrykulkrieger sein soll, der je existiert hat. Und Vardmadra selbst wird herkommen, um ihn zu bewerten!\n\nWir müssen sofort handeln, wenn wir vor ihnen zu diesem alten Helden gelangen wollen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13122] = {title = "Der Geißelstein", objective = "Der Schwarze Wächter im Tal der Echos möchte, dass Ihr ihm 15 Geißelsteine bringt.", description = "Ein Geißelstein ist ein Gegenstand, der allen Einheiten der Geißel bei Geburt oder Erschaffung übergeben wird. Es verleiht dem Träger gewisse Vorteile, aber was wichtiger ist, gewährt den Anführern der Geißel jederzeit Einblick in den Aufenthaltsort und die Bewegungen all ihrer Einheiten.\n\nMit genügend Geißelsteinen sollte ich in der Lage sein, die Bewegungen anderer Geißeleinheiten in Eiskrone zu überwachen.\n\nSammelt alle Geißelsteine, die Ihr finden könnt, während Ihr Geißelkrieger in Geißelholme tötet. Kehrt zu mir zurück, wenn eure Taschen voll sind.", progress = "Geißelsteine werden uns dabei helfen, den Gegner aufzuspüren.", completion = "Dann lasst uns doch mal sehen, ob ich uns mit diesen Steinen nicht ein wenig Einblick verschaffen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13124] = {title = "Der Kampf geht weiter", objective = "Raelorasz möchte, dass Ihr Belgaristrasz und seine Gefährten aus dem Oculus befreit.", description = "Malygos und seine Handlanger werden von Tag zu Tag stärker. Jetzt hat man auch noch unsere jüngste Angriffseinheit gefangen genommen und hält sie im Oculus fest.\n\nWir müssen versuchen, sie zu befreien! Belgaristrasz und seine Gefährten sind für uns unerlässlich.", progress = nil, completion = "Hört gut zu, &lt;Volk&gt;.\n\nEure Arbeit hier hat gerade erst begonnen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing der KühnheitBlühendes BandBand der MotivationZuverlässiges Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13125] = {title = "Die Luft steht still", objective = "Der Schwarze Wächter beim Tal der Echos in Eiskrone will, dass Ihr Salranax den Zerfleischer, Unterkönig Talonox und Hohepriester Yath'amon tötet.", description = "Ihr müsst die Herren von Geißelholme besiegen, wenn dieser Ort vom Würgegriff der Geißel befreit werden soll.\n\nSalranax der Zerfleischer steht dem Tempel auf der ersten Ebene von Geißelholme vor. In der Nähe von Salranax findet Ihr den Hohepriester Yath'amon, der beim Geisterturm auf der zweiten Ebene predigt. Unterkönig Talonox hält bei der Schreckensgrube Hof, die obere Straße hinauf.\n\nSie sind alle herausragende Gegner und sollten mit Bedacht angegangen werden. Benutzt dieses Kriegshorn, wenn Ihr Hilfe brauchen solltet. Die Todesritter von Acherus werden kommen.", progress = "Erledigt sie, <Name>!", completion = "Ein hart erkämpfter Sieg, &lt;Name&gt;! Die Leutnants werden ausgetauscht, aber zumindest für heute steht die Luft um Geißelholme still.", rewards = "Kobalts SchulterschutzLeiahs FußpolsterSixens SchädelkappeJaydes verstärkte HandschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13126] = {title = "Vereinte Front", objective = "Belgaristrasz möchte, dass Ihr 10 Zentrifugenkonstrukte zerstört, um Varos' Schild zu beseitigen. Danach müsst Ihr Varos Wolkenwanderer besiegen.", description = "Von jetzt ab werden wir unsere Kräfte vereinen müssen, um weiter voranzukommen.\n\nVaros über uns versteckt sich hinter einem undurchdringlichen Schild. Um zu ihm zu gelangen, müsst Ihr die Zentrifugenkonstrukte zerstören, die diesen Schild mit Energie versorgen.\n\nJeder von uns kann Euch Drachen des jeweiligen Schwarms zur Verfügung stellen. Sie werden Euch helfen, ihn zu enthüllen.", progress = nil, completion = "Es ist, wie ich es erhofft hatte, &lt;Volk&gt;. Wir arbeiten gut zusammen.\n\nMöge unsere fortwährende Kooperation genügen, um die vor uns liegenden Aufgaben zu bewältigen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13127] = {title = "Magierlord Urom", objective = "Belgaristrasz möchte, dass Ihr Magierlord Urom im Oculus besiegt.", description = "Zwischen uns und unserem ultimativen Ziel hier steht nur noch ein Hindernis. Sein Name ist Urom.\n\nEr bewacht den dritten Ring über uns. Nehmt Euch vor seiner mächtigen Zauberei in Acht.\n\nStreckt ihn nieder. Lasst ihn dafür büßen, dass er dem Feind die Treue geschworen hat!", progress = "Habt Ihr Euch um Magierlord Urom gekümmert?", completion = "Der Sieg ist in Reichweite, Freund.\n\nKonzentration, denn jetzt kommt die wahre Prüfung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13128] = {title = "Schlacht in den Wolken", objective = "Belgaristrasz möchte, dass Ihr Eregos im Oculus tötet.", description = "Die Zeit ist gekommen, Euch Eregos zu stellen.\n\nEr bezieht seine Kraft aus den Energien, mit deren Verteidigung er beauftragt wurde... er trinkt aus dem Brunnen des großen Aspekts Malygos.\n\nJedoch können wir dank des Sieges über den Magierlord nun die volle Kraft unserer Drachen entfesseln. Eregos wird Euch sicherlich unterliegen, wenn Ihr sie weise einsetzt.", progress = nil, completion = "Ich spüre bereits, wie ihre Abwehr schwächer wird!\n\nDas ist der größte Schlag, den wir dem Herrn der Magie seit Beginn dieses Krieges zufügen konnten.\n\nVergesst nicht, Eregos' Lager aufzusuchen. Einige seiner Schätze könnten von Interesse für Euch sein.", rewards = "Fesseln der DankbarkeitErhabene GelenkbänderBindungen des RaeloraszArmschienen der EhrerbietungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13129] = {title = "Psychospielchen", objective = "Kurzel möchte, dass Ihr den Fetzen von Kurzels Bluse auf die Reste von Novos dem Beschwörer anwendet und anschließend den sekretbefleckten Stoff zu ihr in die Feste Drak'Tharon bringt.", description = "<Kurzel reißt einen langen Streifen ihrer Bluse heraus und drückt ihn Euch in die Hand.>\n\nHier, <Volk>, nehmt. Taucht den Stoff in die Überreste von Novos dem Beschwörer.\n\nWir finden schon noch raus, was die Anführer der Geißel antreibt.", progress = "Habt Ihr das Tuch?", completion = "Hoffentlich finden wir jemanden, der bereit ist, diese Probe zu untersuchen.", rewards = "Beschämende FesselnVerachtende BänderBeschuldigte HandgelenksschützerAbgeleugnete ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13130] = {title = "Der Stein, der eine Revolution auslöste", objective = "Kreuzzugsarchitekt Silas im Tal der Echos in Eiskrone möchte, dass Ihr 10 Stämme kristallines Kernholz und 10 Stücke altes elfisches Mauerwerk sammelt.", description = "Wenn Ihr Geißelholme heute betrachtet, mögt Ihr lediglich eine ranzige Grube der Verwesung sehen, aber eines Tages wird es ein Ort voll Pracht und Ehre sein. Hochlord Fordring hat den Namen \"Festung der Gerechtigkeit\" auserkoren.\n\nNun, selbst der Bau einer uneinnehmbaren Festung wie der Eiskronenzitadelle hat mit einem einzelnen Stein begonnen. Und so beginnt unsere Suche nach dem Stein, der eine Revolution auslösen wird.\n\nReist nach Kristallsang, südlich von hier, und sucht das Unbändige Dickicht im Osten. Sobald Ihr dort seid, sammelt kristallines Kernholz vom Boden des Dickichts und elfisches Mauerwerk von den Ruinen von Shandaral.", progress = "Habt Ihr Euch verlaufen?", completion = "Kernholz ist von Natur aus resistent gegen Verrottung, Krankheit und Seuche. Dieses Kernholz jedoch schlägt diese Dinge sogar zurück! Auch das Bauwerk, das nun noch den Auswirkungen des unbändigen Dickichts ausgesetzt ist, wird in ähnlicher Weise wirken.\n\nBald schon werden wir einen großen Schritt weiter sein.", rewards = "AdeptengelenkbänderGurt der BegnadigungStabilitätsgurtArchitektenschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13131] = {title = "Schrott in der Truhe", objective = "Brigg im Turm Utgarde möchte, dass Ihr 5 blitzblanke Silberbarren, 3 glänzende Schmuckstücke, 2 goldene Kelche und eine Jadestatue beschafft.", description = "Seh dir das nur an! Meine Truhe war noch nie sou leer.\n\nMeine Jungs machten Luftsprünge, als sie all die Beude sah'n, und nu? Seh sie dir nur mal an! Nichts als Knochengerippe!\n\nWeiter drinnen gibt es mehr als genug Beude und sie ist nicht von der verfluchten Sorte, darauf würd ich wetten!\n\nBring mir die Beude und ich werde dich reich belounen, Kumpel.", progress = "Wie ging's dir da drin, Kumpel?", completion = "Klasse! Du hast's geschafft, Kumpel.\n\nNu kann ich mein Gesicht dem Käpt'n zeigen, ohne um mein Leben fürcht'n zu müssen - dir und deinen Kameraden sei Dank.\n\nHier ist noch ein wenig Beude als Gegenleistung für dich.", rewards = "Robe mit eingewebten SchmuckstückenExotische LedertunikaGüldene RingpanzerhalsbergeVersilberte KampfplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13132] = {title = "Die Rache ist mein!", objective = "Brigg im Turm Utgarde möchte, dass Ihr König Ymiron tötet.", description = "Glück allein hat mich vor dem Schicksal meiner Kumpel bewahrt. Bei dem Trubel wurde ich umgestoßen - war von Anfang an ein wenig angeheitert gewesen. Also, ich hab dann hochgeguckt und sah, wie sich die ersten von ihnen verwandelten...\n\nDa stand so'n riesen Kerl mit jeder Menge Wachen, der sich das alles ansah. Sie sangen den Namen Ymiron... Wenn Ihr ihn umbringt, werden meine Kumpel vielleicht befreit.", progress = "Hast du denjenigen gefunden, der hier das Sagen hat, <Volk>?", completion = "Großartig! Vielleicht werden meine Kumpel jetzt in Frieden ruhen können.\n\nHier, Junge. Es soll nich' heißen, dass der alde Brigg nich' großzügig zu denjenigen sei, die ihm einen Gefallen getan haben.\n\nGut, mit dir Geschäfte zu machen.", rewards = "Gugel des rachgierigen HauptmannsKopfschutz des GegenschlagsHelm der gerechten VergeltungPlattenhelm der zornigen RacheGesichtsschutz der StrafeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13133] = {title = "Findet den Held aus alter Zeit", objective = "Die Knochenhexe aus Njorndar möchte, dass Ihr mit Iskalder zurückkehrt.", description = "Rasch, <Name>, geht in den Südwesten zu den Hallen der Vorfahren!\n\nDort werdet Ihr auf die schlummernden Mjordin stoßen. Weckt sie, bis Ihr Iskalder gefunden habt. Dann setzt dieses Amulett bei ihm ein und bringt ihn zu mir.\n\nGeht jetzt. Die Zeit ist knapp!", progress = "Wo ist der Held aus alter Zeit?\n\nWir haben keine Zeit zum Plaudern. Geht zu den Hallen der Vorfahren und findet ihn, bevor es zu spät ist!", completion = "Er ist ein schönes Exemplar und wird uns gute Dienste erweisen.\n\nNun müssen wir dafür sorgen, dass wir Vardmadra mit ihm in die Falle locken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13134] = {title = "Lasst ihr Blut fließen", objective = "Dunkelreiterin Arly aus der Schwarzwacht möchte, dass Ihr 5 Bottiche mit Balsamierungsflüssigkeit und 5 Blutkugeln zerstört.", description = "Die Geißel kann ihre Fleischmonster nicht ohne Blut und Balsamierungsflüssigkeit erschaffen, da die Teile geschützt und funktionsfähig bleiben müssen. Wenn wir ihnen diese Materialien nehmen würden, bräche ihre Armee auseinander und wir könnten ihre Schöpfungen mit Leichtigkeit zerstören.\n\nIn allen Laboren, in denen Fleischriesen und Monstrositäten zusammengeflickt werden, werdet Ihr Bottiche mit Balsamierungsflüssigkeit sowie riesige Kugeln voller Blut finden. Zerstört sie und bringt all jenen, die Euch aufhalten wollen, den Tod!", progress = nil, completion = "&lt;Ein dunkles, hohles Lachen hallt Euch entgegen, als Ihr zur Dunkelreiterin kommt.&gt;\n\nIhr riecht nach Sieg, &lt;Name&gt;, und das sind wahrlich gute Neuigkeiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13135] = {title = "Es könnte uns alle umbringen", objective = "Kreuzzugsingenieur Spitzpatrick aus dem Tal der Echos in Eiskrone möchte, dass Ihr 8 Stücke kristallisierte Energie besorgt.", description = "Südöstlich von hier, am Ostrand des Kristallsangwaldes, befindet sich ein Gebiet, das man Unbändiges Dickicht nennt. Die verschiedensten Kreaturen leben dort, jedoch alle von ihnen teilen die Eigenschaft der Bindung an magische Energien. Jedes von ihnen enthält reine, kristallisierte Energie, die uns alle töten könnte, wenn sie je instabil würde!\n\nBegebt Euch ins Unbändige Dickicht und tötet seine Bewohner, um die kristallisierte Energie zu erhalten. Wir benötigen Treibstoff, sie müssen sterben - von welcher Seite man es auch betrachtet, für uns ist es von Vorteil.", progress = "Habt Ihr die kristallisierte Energie?", completion = "Ah, das ist perfekt, Der Bomber müsste in null Komma nichts einsatzbereit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13136] = {title = "Gezackte Splitter", objective = "Bringt Kreuzfahrer Olakin Sainrith in der Schwarzwacht 10 gezackte Splitter.", description = "Ihr habt diesen gezackten, dunklen, brüchigen Splitter aus dem Körper eines Ghul gezogen. Die metallische Klinge ist nicht glatt und wurde vermutlich von einer ungeübten Hand geschmiedet oder aus einem größeren Stück herausgebrochen.\n\nIhr erinnert Euch, ähnliche Splitter in den Körper aller Ghule, die Euch in den Fleischwerken begegnet sind, gesehen zu haben, daher fragt Ihr Euch, warum ihre Schöpfer überhaupt Metall verwendet haben. Möglicherweise fällt Kreuzfahrer Olakin Sainrith dazu etwas ein, wenn Ihr ihm die Splitter aus mehreren Ghulen bringt.", progress = "Was ist das Widerliches?", completion = "&lt;Olakin begutachtet die Splitter vorsichtig.&gt;\n\nIhr habt so etwas bei allen Ghulen da unten gesehen? In all meinen Kämpfen gegen die Geißel ist mir so etwas noch nie begegnet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13137] = {title = "Nicht so ehrenhafter Kampf", objective = "Die Knochenhexe aus Njorndar möchte, dass Ihr Iskalder auf der Kriegsnarbenwarte besiegt.", description = "Auf dem höchsten Gipfel im Südwesten über Jotunheim liegt die Kriegsnarbenwarte. Dieser Ort ist den Vrykul heilig und hier tragen sie neben Valhalas gern ihre ehrenhaften Kämpfe aus.\n\nWir werden einen nicht so ehrenhaften Kampf dort besuchen.\n\nRuft Eure Gefährten zusammen und fliegt zum Turm. Entzündet das Signalfeuer, wenn Ihr bereit seid, und ich werde in Iskalders Gestalt erscheinen.\n\nWir werden kämpfen, Ihr werdet siegen, und Vardmadra wird gewiss anwesend sein, um sich den Kampf anzusehen!", progress = nil, completion = "Ich habe Vardmadra vorerst in Sicherheit gebracht, und an diesem Ort wird sie bleiben, bis wir unsere endgültige Rache nehmen!", rewards = "Handgelenksschützer der KnochenhexeFurorwickel von NjorndarIskalders SchicksalKriegsnarbenwartenbänderIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13138] = {title = "Ich schmelze... schmelze!", objective = "Benutzt die Tasche mit gezackten Splittern in der Nähe eines der Hochöfen auf der untersten Ebene von Malykriss. Kehrt mit dem verhütteten Metallbarren zum Kreuzfahrer Olakin Sainrith bei der Schwarzwacht zurück.", description = "<Olakin wendet einen der Splitter in seiner gepanzerten Hand.>\n\nMit genug Energie dahinter könnten sie Rüstungen durchdringen. Wir müssen herausfinden, woraus sie bestehen und was der Lichkönig mit ihnen vorhat.\n\nIm Osten in der Nähe der Eiskronenzitadelle liegt Malykriss. Aus den wenigen Berichten, die uns vorliegen, geht hervor, dass es voller Ausrüstung zum Verhütten und Schmieden ist. Bringt die Splitter dorthin und schmelzt sie in einem der offenen Hochöfen auf der untersten Ebene von Malykriss ein. Sobald das Metall eingeschmolzen und verändert ist, können wir es identifizieren.", progress = "Habt Ihr diese Fragmente schon eingeschmolzen?", completion = "Es besteht kein Zweifel, dies ist Rohsaronit. Wir haben daraus hergestellte Waffen in den Händen von Günstlingen des Lichkönig gesehen, aber dies ist das erste Mal, dass es für andere Zwecke benutzt wird. Der Umfang dieser Minenarbeiten muss riesig sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13139] = {title = "Im gefrorenen Herzen Nordends", objective = "Liefert Vater Gustavs Bericht bei Hochlord Tirion Fordring in der Argentumvorhut in Eiskrone ab.", description = "Silas und Spitzpatrick haben nun genug Material und Treibstoff, um mit dem Bau der Festung der Gerechtigkeit zu beginnen. Ihr und die Schwarze Klinge haben dafür gesorgt, dass die Geißel in Geißelholme dezimiert wurde und ihre Leutnants besiegt sind.\n\nIch habe mich entschieden, wo wir beginnen werden, doch zuerst müsst Ihr Hochlord Tirion Fordring meinen Bericht überbringen. Auf seinen Befehl hin werden wir in Eiskrone einmarschieren.", progress = "Steht bequem, <Name>. Was gibt es zu berichten?", completion = "Eure Hilfe bei der Sicherung der Front war ein wesentlicher Bestandteil. Der erste echte Sieg in diesem Krieg ist nahe - daher ist unser nächster Schritt auch von größter Wichtigkeit.\n\nSeid unbesorgt, &lt;Name&gt;, die Geißel wird nicht kampflos aufgeben. Eure größte Herausforderung steht Euch noch bevor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13140] = {title = "Die Runenschmiede von Malykriss", objective = "Bringt Kreuzfahrer Olakin in der Schwarzwacht 5 runenverzierte Saronitplattenrüstungen.", description = "Die Splitter, die Ihr gefunden habt, können nur von einem Ort stammen: aus Malykriss. Hier, östlich von Corp'rethar, finden alle Metallarbeiten des Lichkönigs statt.\n\nVerwirrend daran ist, dass man kein Metall benötigt, um die Monstrositäten oder Fleischriesen zusammenzuflicken oder um die Skelettdiener zu beschwören. Findet die Skelettrunenschmiede auf der untersten Ebene von Malykriss und nehmt die Platten, die sie bearbeiten, an Euch. Wir müssen herausfinden, warum dieses Metall in den Fleischwerken Verwendung findet.", progress = "Konntet Ihr diese runenverzierten Platten an Euch bringen?", completion = "Diese Platten sehen fast genauso aus wie die Splitter. Sie müssen die herausgeschnittenen Stücke dafür verwenden, um die hier produzierten Ghule zu verbessern. Die Geißel ist verzweifelt genug, um aus allem eine Waffe herzustellen, wie es scheint. Umso mehr ein Grund, diesen schrecklichen Ort umso schneller zu zerstören!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13141] = {title = "Die Schlacht um den Kreuzfahrerturm", objective = "Begebt Euch zum Kreuzfahrerturm und platziert das gesegnete Banner des Kreuzzugs auf dem Haufen Kreuzfahrerschädel. Verteidigt das Banner gegen den Angriff der Geißel, bis das Land auf dem Turm gereinigt ist. Kehrt dann zu Vater Gustav ins Tal der Echos in Eiskrone zurück.", description = "<Hochlord Fordring hält ein Banner des Argentumkreuzzugs in den Händen.>\n\nDieses Banner ist unvergleichlich, <Name>. Es enthält einen mächtigen Segen, der große Teile verseuchten Landes reinigen kann.\n\nIhr müsst es durch die Bresche in den Nordwesten in ein Gebiet bringen, das die Geißel spöttisch Kreuzfahrerturm nennt. Stellt das Banner auf die Schädel unserer am Kreuzfahrerturm gefallenen Brüder und verteidigt es gegen alle Angriffe. Sobald das Land gereinigt ist, kehrt Ihr zu Vater Gustav zurück.\n\nGeht jetzt, <Name>, und habt keine Furcht.", progress = nil, completion = "Gesegnetes Licht! Wir haben den Turm eingenommen! Endlich können wir mit dem Bau der Festung der Gerechtigkeit beginnen. Hochlord Fordring und die Ritter sind bereits zu unserer neuen Basis aufgebrochen. Ihr müsst Euch dort mit ihnen treffen, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13142] = {title = "Rache der Banshee", objective = "Die Knochenhexe aus Njorndar möchte, dass Ihr für sie Rache nehmt, indem Ihr Oberthan Balargarde herausfordert und besiegt.", description = "Die Zeit ist gekommen, <Name>. Ihr müsst mit Euren Freunden den Fürsten der Festung Balargarde, den Meister von Jotunheim, Oberthan Balargarde, herausfordern.\n\nAm höchsten Punkt der Festung, die sich am Südwestrand von Jotunheim befindet, werdet Ihr auf ein Horn stoßen. Blast hinein und lasst all jene, die unerschütterlich genug sind, Eure Herausforderung hören.\n\nBalargarde wird keine andere Wahl haben, als sich Euch zu stellen. Und ich... Verzeihung, Vardmadra wird dort sein, um das Urteil zu fällen.\n\n<Die von einer Banshee besessene Vrykul stößt ein bellendes Lachen aus.>", progress = nil, completion = "Was ich im Moment fühle, lässt sich nicht in Worte fassen, &lt;Name&gt;. Meine Rache ist vollzogen, und es gibt hier für mich nichts mehr zu tun.\n\nKönnte ich doch hier sein, wenn der Lichkönig endlich gestürzt wird.\n\nAber lasst Euch nicht täuschen, denn Jotunheim ist noch lange nicht 'erledigt'. Ich werde diese Hexe weiterhin unter Kontrolle behalten, bis die Vrykul keine Bedrohung mehr darstellen.\n\nSeht Euch um, in dieser Höhle könnt Ihr viele wertvolle Dinge sehen. Sucht Euch etwas aus.", rewards = "VergeltungsmesserSchnellklinge der kalten RückkehrBollwerk der ErlösungAuf Euch wartet eine dieser Belohnungen:\n\nDer HexenzauberfoliantEndspiel des Knochenwerfers\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13143] = {title = "Neuer Rekrut", objective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr einen unterworfenen geschmeidigen Pirscher zur Spitze der Felsen nordöstlich der Anhöhe des Leidens bringt.", description = "Eins nach dem anderen. Ich habe ein paar geschmeidige Pirscher auf den Bollwerken östlich von hier gesehen. Sie hatten uns gedient, bevor wir uns von Arthas losrissen. Außerdem sind sie so ziemlich die besten Kundschafter, die es gibt, wenn man sie mit dem Auge der Herrschaft nur ein wenig antreibt.\n\nFliegt dorthin, findet einen der Pirscher, setzt ihm ein wenig zu, wendet dann dieses Siegel der Schwarzen Klinge auf ihn an und er wird Euch gehorchen. Führt ihn anschließend zur Spitze der Felsen nordöstlich von hier und er wird seinen Weg zu mir finden.", progress = "Ich bin mir sicher, dass ihre neuen Meister nicht zimperlich mit ihnen umgehen werden; doch sie werden die Striemen, die wir ihnen beibrachten, auf jeden Fall nicht vergessen. Sie werden diese Siegel fürchten, solange sie leben.", completion = "Ich habe den armen Teufel an den Pfosten dort drüben gekettet und werde mir noch mehr von ihnen schnappen.\n\nNa, dann lasst uns doch das Auge mal ein wenig benutzen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast: See Quest Invis 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13144] = {title = "Zwei Geißeln mit einem Skelett schlagen", objective = "Dunkelreiterin Arly an der Schwarzwacht möchte, dass Ihr 3 angekettete Monstrositäten mit brennenden Skeletten zerstört.", description = "Einige ihrer Kreationen haben die Arbeiter in den Fleischwerken bereits fertiggestellt. Im Moment sind die Kreaturen noch an die Säulen rund um die Kante des Labors gekettet, aber wenn wir nicht schnell etwas unternehmen werden sie mit den Armeen des Lichkönigs marschieren.\n\nAus den auf dem Boden der Fleischwerke verteilten Knochenhaufen ragen gierig greifende Arme heraus. Diese Arme gehören zu Skeletten, die mit der Macht des Feuers belegt sind. Findet und befreit diese Skelette, bringt sie in die Nähe der fertigen Monstrositäten und genießt die Vorstellung!", progress = nil, completion = "Ah, gut. Es geht doch nichts über den Geruch von verbranntem fauligen Fleisch am Morgen. Der Geruch ist ein Sieg über die Geißel.", rewards = "FleischwerkfesselnFleischwerkhandgelenksschützerFleischschuppenarmschienenGehärtete KnochenhandgelenksschützerIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13145] = {title = "Die Unheilvolle Festung", objective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr mithilfe eines geschmeidigen Pirschers Malykriss erkundet.", description = "Wir müssen wissen, mit was wir es zu tun haben.\n\nBringt mithilfe des Auges der Herrschaft einen geschmeidigen Pirscher unter Eure Kontrolle und erkundet die Gegend. Als ich hierher geflogen bin, habe ich ein paar Stellen gesehen, die Ihr für mich genauer untersuchen sollt: die Warte im Nordosten, das Gebiet der Arbeiter im Südosten, die große Schmiede in der Nähe des Zentrums und den Ritualbereich im Südwesten.\n\nDer Pirscher kann weit springen und Stürze aus größerer Höhe machen ihm nichts aus. Nutzt dies zu Eurem Vorteil und die Bollwerke werden kein Hindernis mehr darstellen.", progress = "Fliegen mag zwar etwas eleganter sein, aber wir hätten ohne den Pirscher nie so nah herankommen können, ohne dabei gesehen zu werden.", completion = "Ausgezeichnete Arbeit. Es scheint, dass mehr Todesritter Arthas treu geblieben sind, als ich zuerst dachte.\n\nEr versucht Acherus mit allen Mitteln zu ersetzen, so viel steht fest. Eine Zitadelle komplett aus Saronit wäre mit Sicherheit nicht leicht zu zerstören. Doch das müssen wir gar nicht... Wir können dem Treiben hier und jetzt ein Ende bereiten und die Anführer der Todesritter aus dem Weg schaffen, bevor sie eine wirkliche Bedrohung darstellen.\n\nUnd was am allerwichtigsten ist: Wir müssen für genug Tumult sorgen, um diese Todesritter von ihren Anführern zu trennen, damit wir zuschlagen können.", rewards = "Beinplatten der HerrschaftKordel des geschmeidigen PirschersListige LedertunikaVerzauberte Armreife des SpähersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13146] = {title = "Jede Menge Großzügigkeit", objective = "Vereth der Gewiefte möchte, dass Ihr nach Malykriss geht und mithilfe der Eisenkette des geschmeidigen Pirschers eine Geißelbombe zu einer schwerfälligen Schreckensgestalt zieht. Tötet auf diese Weise 4 schwerfällige Schreckensgestalten.", description = "Wir müssen für ein wenig Tumult sorgen, um diese Todesritter von ihren Anführern wegzubekommen. Ich nehme an, dass, sollten wir ihre Untergebenen dort unten beseitigen, sie ihren Operationen mehr Aufmerksamkeit widmen müssten.\n\nMonstrositäten sind leichte Beute - langsam, berechenbar und was am allerwichtigsten ist: sie sind dumm. Nutzt ihr Vertrauen zu den Pirschern, um die Geißelbomben, die überall in dem Gebiet herumliegen, zu ihnen zu schleifen. Ihr werdet sie anzünden können, lange bevor die Monstrositäten überhaupt herausfinden, wie ihnen geschieht.", progress = nil, completion = "Sie sind nicht einmal auf den Gedanken gekommen, Hand an Euch zu legen, stimmt's? Wenigstens sind sie berechenbar.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13147] = {title = "Kuppler", objective = "Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr einen geschmeidigen Pirscher benutzt, um in Malykriss Steine auf Umbralschläger zu werfen, sobald sie sich niederen Untoten nähern. Kehrt zurück, sobald Ihr 5 Kämpfe provoziert habt.", description = "Der Hauptunterschied zwischen Vargul und niederen untoten Günstlingen ist, dass die Vargul noch über so viel Verstand verfügen, um es zu verabscheuen, als Arbeiter herangezogen zu werden. Niemals wird es einem Vargul gefallen, an der Seite von Skeletten oder Ghulen arbeiten zu müssen.\n\nWir werden uns diese Abneigung zunutze machen und Zwietracht zwischen den Umbralschlägern und den anderen Untoten in Malykriss säen. Das sollte die Produktion abbremsen und die Todesritter zum Babysitting zwingen.\n\nSollte einfach zu machen sein - ein paar Steine auf die Schläger, sobald sie sich den niederen Untoten nähern, werden genügen.", progress = nil, completion = "Gibt also keinen Grund, unsere eigenen Männer zu opfern, wenn sie sich so leicht beeinflussen lassen, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13148] = {title = "Halskettenreparatur", objective = "Repariert die Halskette mit einem einzigen Chalzedon und bringt sie zu Jonas Timotheus im Juwelierladen auf dem Handelsmarkt der Magier in Dalaran.", description = "Bei der kaputten Halskette liegt eine Rechnung, auf der steht: \"Eigentum von Jonas Timotheus - Cartier & Co., edle Juwelierwaren - Handelsmarkt der Magier - Dalaran\".\n\nVielleicht solltet Ihr sie reparieren und zu ihm zurückbringen.", progress = "Was führt Euch hierher?", completion = "Wo habt Ihr das gefunden?! Vor ein paar Wochen ging eine Lieferung von mir raus und viele dieser Halsketten wurden daraus gestohlen! Lasst mich meine Schuld begleichen und Euch dieses Juwelierssymbol geben.", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][13149] = {title = "Illusionen bannen", objective = "Chromie möchte, dass Ihr den arkanen Disruptor auf die verdächtigen Kisten im Stratholme der Vergangenheit anwendet und sie anschließend am Eingang von Stratholme trefft.", description = "Der ewige Drachenschwarm möchte Prinz Arthas hinters Licht führen und auf diese Weise die Geschichte verändern.\n\nWenn er sich davon überzeugen lässt, dass keines der Körner hier verseucht ist, dann wird er seine verhängnisvolle Entscheidung niemals treffen und die Einwohner Stratholmes am Leben lassen.\n\nWendet diesen arkanen Disruptor auf alle Kornkisten an, die Euch verdächtig erscheinen.", progress = nil, completion = "Das habt Ihr gut gemacht, Freund. Arthas' Truppen haben das verseuchte Korn entdeckt.\n\nHört jetzt gut zu. Es gibt noch mehr zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13150] = {title = "ZZOLDLost: Widget", objective = "Repariert den Apparat und bringt ihn zu Jonas Thimotheus im Juwelierladen in Dalaran.Unten am Apparat ist eine Rechnung, laut der \"Jonas Timotheus - Juwelier\" in Dalaran der Besitzer ist. Wenn Ihr ihn reparieren und zu ihm zurückbringen würdet, vielleicht würde er Euch dann belohnen.", description = "Unten am Apparat ist eine Rechnung, laut der \"Jonas Timotheus - Juwelier\" in Dalaran der Besitzer ist. Wenn Ihr ihn reparieren und zu ihm zurückbringen würdet, vielleicht würde er Euch dann belohnen.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13151] = {title = "Die Eskorte des Königs", objective = "Chromie möchte, dass Ihr Arthas bei seiner Ausmerzaktion in Stratholme begleitet. Ihr sollt wieder mit ihr sprechen, nachdem Mal'Ganis besiegt ist.", description = "Schon bald wird Arthas vor einem verzweifelten Dilemma stehen und eine folgenschwere Entscheidung treffen.\n\nIch muss Euch bitten, den Prinzen bei seiner Ausmerzaktion in Stratholme zu begleiten.\n\nArthas muss lebend durch Stratholme kommen und Ihr müsst dafür sorgen, dass er Mal'Ganis besiegt!", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;.\n\nDer Plan des ewigen Drachenschwarms wurde durchkreuzt und die Geschichte bleibt, wie sie ist.\n\nEure Unterstützung war von unschätzbarem Wert - nehmt meinen Dank und auch den des gesamten bronzenen Drachenschwarms.", rewards = "Handschuhe des ZeitwächtersHandlappen der erhaltenen GeschichteHandschutz der chronologischen EreignisseStulpen der SäuberungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13152] = {title = "Ein Besuch beim Doktor", objective = "Dunkelreiterin Arly von der Schwarzwacht möchte, dass Ihr den Metallpflock, an den 'Flicken' im Sanktum der Reanimation gekettet ist, zerstört und diesem helft, sich an Doktor Sabnok zu rächen.", description = "Sie haben diese Ghule also unten im Sanktum der Reanimation mit zerbrochenen Saronitsplittern ausgestattet? Wir müssen dem ein Ende setzen, bevor sie diese Ghule gegen unsere Truppen einsetzen.\n\nFindet den Eingang zum Sanktum der Reanimation im Gebiet um das Fleischriesenlabor in den Fleischwerken. Dort hält das Ghulgenie Doktor Sabnok seine schaurigste Schöpfung 'Flicken' fest. Befreit Flicken von seinen Ketten und helft ihm, sich am Doktor zu rächen. Möge seine eigene Kreatur sein Untergang sein.", progress = "Habt Ihr die Schöpfung des Doktors schon freigelassen?", completion = "&lt;Dunkelreiterin Arly wirft den Kopf in den Nacken und lacht finster.&gt;\n\nEin passendes Ende für den 'guten' Doktor, findet Ihr nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13153] = {title = "Die Krieger schützen", objective = "Zauberin Kaylana in der Tausendwinterfestung möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen abnehmt.", description = "<Name>, gut, Euch zu sehen. Wir müssen uns beeilen, solange sich die Schlacht etwas gelegt hat, und unsere Vorräte aufstocken. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Man hat beobachtet, wie die Horde in dieser Gegend Rüstungen einsammelt.\n\nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.\n\nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.", progress = "Habt Ihr die Rüstungen nun gefunden?", completion = "Oh, die tropfen noch immer. Hättet Ihr sie nicht zuerst abtrocknen können?", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13154] = {title = "Pfeil und Knochen", objective = "Bogenmacher Randolph in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", description = "Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.\n\nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.\n\nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!\n\nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!", progress = "Wie ist die Jagd gelaufen? Ich habe Gerüchte darüber gehört, dass es an dem Ort spuken soll. Ich gehe jedoch nie selbst dorthin.", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13155] = {title = "Vereth der Gewiefte", objective = "Meldet Euch bei Vereth dem Gewieften auf der Anhöhe des Leidens in Eiskrone.", description = "Ich habe schon Gerüchte über Malykriss und Arthas' neuen Todesritterorden gehört, bin jedoch davon ausgegangen, dass es sich dabei nur um etwas handelt, das dazu dienen soll, die Lücke wieder aufzufüllen. Ihre Zahl lässt jedoch darauf schließen, dass er versucht, einen Zahn zuzulegen.\n\nWir haben vor nicht allzu langer Zeit einen unserer Besten nach Malykriss entsandt - Vereth den Gewieften. Ihr solltet ihn auf der Anhöhe des Leidens gleich westlich von Malykriss im Hof der Knochen antreffen.\n\nVersucht, auf Eurem Weg dorthin nicht zu viel Aufmerksamkeit auf Euch zu ziehen.", progress = nil, completion = "Die unheilvolle Festung... ein Zeugnis dessen, wie ungern Arthas verliert. Lasst uns die Klinge tief hineintreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13156] = {title = "Ein seltenes Kraut", objective = "Anachoret Tessa in der Tausendwinterfestung möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel der Horde abnehmt.", description = "Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.\n\nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn der Kräuterbeutel der Horde, die Ihr dort finden könnt. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.\n\nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen die Kräuter ab!", progress = "Hoffe, Ihr habt aus Versehen keine dieser Peitscher herausgezogen! Die haben den Gefreiten Doane letzte Woche ziemlich übel verpeitscht.", completion = "Ausgezeichnet! Das wird helfen, unsere Truppen vor der Kälte zu schützen.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13157] = {title = "Der Kreuzfahrerturm", objective = "Sucht den Hochlord Tirion Fordring beim Kreuzfahrerturm in Eiskrone auf.", description = "Ihr könnt stolz darauf sein, dass Ihr es wart, der der Argentumdämmerung dazu verholfen hat, in Eiskrone Fuß zu fassen, <Name>. Der Kreuzfahrerturm bietet dem Lichkönig und seinen missratenen Günstlingen nun direkt die Stirn.\n\nHochlord Fordring und die Kreuzfahrer, die überlebt haben, erwarten Eure Ankunft beim Kreuzfahrerturm. Durchquert erneut die Bresche und sucht den Hochlord auf!", progress = nil, completion = "Der Weg zu den Toren der Eiskronenzitadelle wird lang und beschwerlich. Ich und die Soldaten der Argentumdämmerung möchten Euch für alles danken, was Ihr bisher getan habt. Es beruhigt uns, zu wissen, dass Ihr an diesem verfluchten Ort an unserer Seite kämpfen werdet.\n\n&lt;Hochlord Tirion Fordring salutiert.&gt;", rewards = "Die ArgentumschädelkappeEntschlossenheit des KreuzzüglersTirions KopfbandKreuzfahrerhelmkappeDie ArgentumkroneIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13158] = {title = "Diskretion ist der Schlüssel", objective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Aufseher Alturas sprecht.", description = "Hört mir zu, <Volk>.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans in die Wege leiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis aufmacht und mit Aufseher Alturas sprecht. Er wird Euch die Einzelheiten erklären.\n\nDas ist nicht alles: Die Sache muss mit äußerster Diskretion behandelt werden. Wir müssen versuchen, die Einwohner Dalarans wenn möglich nicht zu beunruhigen. Habe ich mich klar ausgedrückt?\n\nSehr gut. Nun geht!", progress = nil, completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13159] = {title = "Eindämmung", objective = "Aufseher Alturas möchte, dass Ihr die Violette Festung betretet und den Invasionsstreitkräften des blauen Drachenschwarms ein Ende bereitet. Ihr sollt Euch wieder bei ihm melden, sobald Cyanigosa getötet wurde.", description = "Hier ist der Gefängnisschlüssel.\n\nMeine Männer und ich werden als letzte Verteidigungslinie hier bleiben, falls Ihr dem Angriff nicht standhalten könnt.\n\nSprecht auf jeden Fall mit Leutnant Sinclari. Sie wird Euch Zugang zu den Verteidigungsvorrichtungen des Gefängnisses beschaffen.\n\nBeeilt Euch, <Volk>. Es bleibt nur wenig Zeit. Die Wenigen, die ich zurückgelassen habe, werden ohne Eure Hilfe nicht lange durchhalten. Meldet Euch wieder bei mir, sobald die Invasoren erfolgreich zurückgeschlagen wurden.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Die Krise ist also abgewendet?\n\nDas sind wirklich gute Neuigkeiten. Ich werde sie an Rhonin weiterleiten.\n\nBitte, nehmt dies als Zeichen des Danks, den Euch Dalaran entgegenbringt.", rewards = "Tätowierte WildhautgamaschenVerliehene PantalonsLabyrinthische BeinschützerBeinplatten des Wächters von DalaranIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13160] = {title = "Eine überwältigende Aussicht", objective = "Vereth der Gewiefte möchte, dass Ihr die Hebefähigkeiten des geschmeidigen Pirschers benutzt, um 12 schlafende Eishautwachposten zu zerstören.", description = "Gargoyles eignen sich sehr gut als Kundschafter und können tödlich sein, wenn man ihnen den Angriff aus der Luft überlässt, doch haben sie einen offensichtlichen Schwachpunkt. Die meisten von ihnen müssen längere Zeit in Steinform verbringen, um sich zu erholen und die Energie zu sammeln, die sie brauchen, um ihre schweren Körper durch die Luft zu bewegen.\n\nAls ich durch das von Euch benutzte Auge geblickt habe, sind mir Dutzende von Eishautwachposten aufgefallen, die an den östlichen und südlichen Innenwänden ruhten. Benutzt den Jäger, um zu ihnen hinauf zu gelangen und vernichtet sie, während sie schlafen.", progress = nil, completion = "Die stellen keine so große Bedrohung mehr da, wenn sie schlafen.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13161] = {title = "Der Reiter des Unheiligen", objective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Rokir, den Reiter des Unheiligen, tötet.", description = "Es ist Zeit, dass wir damit anfangen, den Kopf des Ganzen zu beseitigen.\n\nIch diente ziemlich lange neben Rokir. Er kennt die unheiligen Künste besser als jeder andere Todesritter, den ich getroffen habe, und er ist genauso skrupellos. Nehmt es nicht zu leicht.\n\nRokirs Stärken treten dann am stärksten hervor, wenn er sich auf seinem eigenen Grund und Boden befindet. Leider haben wir in dieser Hinsicht keine andere Wahl. Bleibt jedoch auf den Beinen, um seinen untoten Dienern aus dem Weg zu gehen, und Ihr solltet siegreich hervorgehen.\n\nSeid flink, <Klasse>, und nehmt die Sache nicht zu leicht.", progress = nil, completion = "Die Welt wird ohne Rokir ein viel besserer Ort sein - glaubt mir.", rewards = "MorschknochenzauberstabWeggeworfene SchlachthaushandschuhePlattenbeine des UnheiligenBlutverkrustete StiefelIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13162] = {title = "Die Reiterin des Frostes", objective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Saph, die Reiterin des Frostes tötet.", description = "Saph... So einen Todesritter wie sie gibt es kein zweites Mal. Sie wird Euch mit sanften Worten übergießen und während Ihr Euch absolut sicher seid, dass kein Funken Boshaftigkeit in ihr steckt, wird sie Euch durchlöchern - weiterhin ein Lächeln auf den Lippen. Unterschätzt sie nicht.\n\nIch mache mir keine Sorgen, dass Ihr Saph besiegen könnt, doch werdet bloß nicht zu übermütig. Ihre Stärke liegt darin, ihre Opfer in falscher Zuversicht zu wiegen und sie kurz darauf mit einem heftigen Frosthagel in tausend Einzelteile zu zerschießen.\n\nSeid immer auf der Hut und unterschätzt sie nicht.", progress = nil, completion = "Ich muss gestehen, dass ich ihr Lachen vermisse... und dieses Lächeln, das langsam in ihr Gesicht schlich, bevor sie jemanden tötete. Muss jetzt jedoch weniger auf der Hut sein, also nehme ich an, dass ich mich nicht beschweren kann.", rewards = "Axt des GerissenenKriegsbeil des FrostkletterersEisige SchnellschneideSaphs SpalterIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13163] = {title = "Der Reiter des Blutes", objective = "Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr Baelok, den Reiter des Blutes, tötet.", description = "Baelok ist einer der wenigen Vrykul, den ich jemals in den Rängen aufsteigen sah, und das war größtenteils seiner schieren Brutalität zu verdanken. Wenn die Konkurrenz erst einmal tot ist, gibt es um einiges weniger, mit dem man konkurrieren müsste.\n\nEure Gruppe muss sich verteilen und so viel Abstand voneinander halten wie Ihr es die Situation zulässt, wenn der Kampf beginnt. Er wird nicht zögern, Eure Lebensenergie zu rauben, also werdet Ihr ihn so oft wie möglich daran hindern müssen.\n\nIch vertraue auf Euch. Seht zu, dass er stirbt.", progress = nil, completion = "Er hat also endlich den Kürzeren gezogen? Gut zu hören.", rewards = "Groteske MetzgerhosenBedeckung des BlutpirschersBrustplatte des verspritzten BlutesAuf Euch wartet eine dieser Belohnungen:\n\nBlutgeschmiedeter Kreis\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13164] = {title = "Blutbanns Schicksal", objective = "Vereth auf der Anhöhe des Leidens hat Euch ausgesandt, um Orbaz Blutbann zu töten.", description = "Nun, da die Reiter der Heerschar des Leids tot sind, ist die Zeit gekommen, ihrem wahren Anführer ein Ende zu bereiten: Orbaz Blutbann.\n\nMograine war hier, als Ihr weg wart, und hat mir gesagt, dass er herausgefunden hat, wo sich Orbaz versteckt hält. Unter der Eiskronenzitadelle befindet sich eine riesige Grube - und Orbaz befindet sich am Rand dieser Grube.\n\nEinige der stärksten Agenten der Schwarzen Klinge wurden schon ausgesandt - holt also Hilfe und auf mit Euch in den Kampf. Es ist Zeit, dass Blutbann stirbt.", progress = "Sind wir diesen jämmerlichen Möchtegernarthas los?", completion = "Also ist Mograine höchstpersönlich erschienen, um die Sache zu Ende zu bringen? Ich kann mir vorstellen, dass es böses Blut zwischen den beiden gegeben haben muss - kein Wunder also, dass er ein Stück vom Kuchen abbekommen wollte.\n\nIhr habt außerordentlich gute Arbeit geleistet, &lt;Volk&gt;, und sollt dementsprechend belohnt werden. Die Schwarze Klinge spricht Euch ihren Dank aus.", rewards = "Blutbanns FallBlutbannumhangBlutbanns EntschlossenheitBlutbanntuchIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13165] = {title = "Acherus zurückerobern", objective = "Benutzt Euren Zauber 'Schwarzes Tor' und kehrt nach Acherus, der Schwarzen Festung, zurück. Meldet Euch bei Hochlord Darion Mograine, sobald Ihr dort seid.", description = "Der Dunstschleier hat sich gelüftet. Nun kann ich genauso klar sehen wie an dem Tag, als ich den Aschenbringer in mein eigenes Herz rammte, um meines Vaters verfluchte Seele zu befreien – dies ist meine letzte Erinnerung an mein Leben als freier Mann.\n\nWir müssen Acherus von der Geißel zurückerobern, wenn unser Orden in dieser neuen Welt überleben will. Ich habe Euch gezeigt, wie man ein schwarzes Tor beschwören kann. Das Tor wird Euch zurück nach Acherus befördern, wenn Ihr es ruft, <Name>. Ruft es herbei und trefft mich dort. Die erste Schlacht der Ritter der Schwarzen Klinge ist in vollem Gange!", progress = nil, completion = "Der Lichkönig ist nach Nordend zurückgekehrt, verwundet vom Aschenbringer, doch auf der zweiten Ebene befindet sich noch immer die letzte seiner Armeen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13166] = {title = "Die Schlacht um die Schwarze Festung", objective = "Vernichtet 10 Diener der Geißel und helft, Flickwerk zu vernichten. Kehrt zu Hochlord Darion Mograine zurück, solltet Ihr erfolgreich sein.", description = "Die Hallen des Befehls wurden gesichert, doch der Lichkönig hat uns ein kleines Geschenk im Herzen von Acherus zurückgelassen. Der zusammengenähte Schrecken Flickwerk und eine Horde von Monstrositäten haben die zweite Ebene in ihre Kontrolle gebracht.\n\nBenutzt den Teleporter, um auf die zweite Ebene zu gelangen, und zerstört die restlichen Streitkräfte der Geißel. Greift Flickwerk auf keinen Fall alleine an! Ihr müsst das Ungetüm mit anderen Todesrittern von Acherus bekämpfen!\n\nGeht, <Name>. Meine Kraft wird Euch tragen!", progress = "Acherus wird unser sein!", completion = "Gut gemacht, &lt;Klasse&gt;. Um die verbliebenen Diener der Geißel wird man sich im Nu gekümmert haben und der Wiederaufbau kann von Neuem beginnen.\n\nIch habe eine allerletzte Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13167] = {title = "Tod dem Verräterkönig", objective = "Kilix der Entwirrer in der Grube von Narjun hat Euch damit beauftragt, Anub'arak in Azjol-Nerub zu besiegen. Danach sollt Ihr Kilix Anub'araks zerbrochenen Panzer zurückbringen.", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nNach seinem Verrat hat er unser Heimatland entstellt und verdorben und es schließlich zu dem erbärmlichen Haufen Dreck gemacht, zu dem es heute geworden ist. Er herrscht über eine Armee untoter Neruber, die wie ihr Anführer dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende, <Klasse>. damit würdet Ihr unseren beiden Völkern einen großen Dienst erweisen.\n\nBringt mir Anub'araks Panzer, wenn Ihr schaffen solltet, was noch keiner vor Euch geschafft hat.", progress = "Ist es vollbracht, <Klasse>? Hat der Verräterkönig letztendlich sein Ende gefunden?", completion = "&lt;Kilix starrt den Panzer an und jedes einzelne seiner Augen fängt an, intensiv zu leuchten.&gt;\n\nEs ist VOLLBRACHT!\n\n&lt;Volk&gt;! Euer Name soll in die Geschichte meines Volkes eingehen.\n\nIch stehe in Eurer Schuld...", rewards = "Kilix' SeidenslipperDon Sotos StiefelHüllenfragmentsabatonsSchienbeinschützer des VerrätersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13168] = {title = "Abschiedsgeschenke", objective = "Keritose Blutklinge im Schattengewölbe möchte, dass Ihr eins der Augen der Herrschaft benutzt, um die Kontrolle über einen gefangenen Eidolonwächter zu übernehmen.", description = "Schaut, was wir hier haben... Augen der Herrschaft. Normalerweise tut der Kult alles nur Erdenkliche, um diese Dinger geheim zu halten, aber vermutlich haben sie ziemlich wenig Rückzugsmöglichkeiten, wenn wir sie in ihrem eigenen Haus erschlagen.\n\nDie Augen erlauben es jedem Wesen von relativer Macht, die Handlungen eines untoten Dieners präzise zu kontrollieren. Wie Ihr Euch vorstellen könnt, kann dies im Falle des typischen unbeholfenen Ghuls oder Skeletts extrem praktisch sein.\n\nHabt Ihr Lust, es einmal auszuprobieren? Benutzt eines der Augen bei einem der gefangenen Schatten.", progress = "Die Tricks, die durch diese Augen möglich werden, sind offenkundig. Dies werden sehr nützliche Werkzeuge sein.", completion = "Gar nicht schwer, hm? Jedes halbwegs intelligente Wesen sollte wenig Schwierigkeiten haben, niedere Untote zu kontrollieren. Ich schätze, nur ein echter Totenbeschwörer kann diese benutzen, um die Kontrolle über eines der mächtigeren untoten Geschöpfe zu ergreifen. Das dürfte allerdings kein Problem sein. Mir fallen bereits diverse Varianten der Zerstörung ein, die wir mithilfe der erbärmlichsten Diener ausführen können.\n\nSollen wir es einmal ausprobieren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13169] = {title = "Der beste Freund des Untoten", objective = "Keritose Blutklinge im Schattengewölbe wünscht, dass Ihr mithilfe des Eidolonwächters 18 hungernde Seuchenhunde füttert.", description = "Unter den Untoten in der Saronitmine gen Süden ist es üblich, ihre Seuchenhunde hungern zu lassen, um sie besonders aggressiv zu halten. Benutzt den Schemen, um nahe heranzukommen und füttert einige der Hunde. Ich verspreche Euch, Ihr werdet fortan keinerlei Schwierigkeiten mehr mit ihnen haben. Vielleicht werden sie sich ihrem Wohltäter sogar anschließen.\n\nKommt den Dingern jedoch nicht zu nahe, bevor Ihr sie gefüttert habt. Ihre Nasen lassen sich von Eurem Schemen nicht so leicht hinters Licht führen.", progress = nil, completion = "Sie sind sofort eingeschlafen, stimmts?", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13170] = {title = "Ehre ist was für Schwächlinge", objective = "Keritose Blutklinge im Schattengewölbe hätte gerne, dass Ihr 20 ruhelose Aufklärer tötet.", description = "Ghule sind sehr zerbrechlich, wenn es hart auf hart kommt, und die Aufklärer in der Saronitmine den Weg hinunter in Richtung Südwesten sind da keine Ausnahme. Mithilfe eines Schattens sollte es Euch eigentlich nicht schwerfallen, ranzuschleichen und ihre Aufklärer geräuschlos auszuschalten.\n\nBeseitigt so viele Aufklärer, wie Ihr in angemessener Zeit erwischen könnt... Ihre Reihen sollen gelichtet werden, bevor wir das nächste Mal angreifen.", progress = nil, completion = "Ohne Euch auch nur die Hände schmutzig gemacht zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13171] = {title = "Schickt sie zurück", objective = "Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 10 Eindämmungskristalle der Geißel zu bannen.", description = "Meine Hauptsorge ist die Saronitmine, die sich den Weg hinunter in Richtung Südwesten befindet. Sie holen unglaubliche Mengen an Erz aus dieser Mine und ich würde schon gerne wissen, was sie damit vorhaben. Um das herauszufinden, fangen wir damit an, ihre Verteidigung zu schwächen.\n\nMir sind mehrere Kristalle aufgefallen, die in der ganzen Basis verteilt stehen, und nehme an, dass es sich hier um irgendwelche Verteidigungsanlagen handelt, ähnlich den Ziggurats. Zerstört mithilfe des Eidolonwächters jeden Kristall, den Ihr finden könnt.", progress = nil, completion = "Ausgezeichnete Arbeit. In der Luft sollte also so gut wie keine Gefahr mehr lauern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13172] = {title = "Chaos säen", objective = "Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 80 Untote im Tränenbruch abzuschlachten. Sprecht mit ihm, um Euch einen Skelettgreifen für den Angriff zu sichern.", description = "Effektives Werkzeug, nicht wahr? Sehr gut gemacht, wie Ihr ihre Verteidigung geschwächt habt, <Klasse>. Nun können wir den Hauptangriff vorantreiben.\n\nDer Plan ist einfach und direkt - wir wollen alles beseitigen, was sich bewegt, und die Verwirrung ausnutzen, um ein paar Informationen in die Hände zu bekommen.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde Euch einen Skelettgreif besorgen.", progress = nil, completion = "Sie sind so gut wie schutzlos ausgeliefert. Viel einfacher geht's wohl nicht.", rewards = "TränenmantelPelzbesetzter HelmBlutklingeSchmierige SaronitschulterstückeKettenhandschuhe des SteinbruchsIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13173] = {title = "Das Durcheinander nutzen", objective = "Uns ist es gelungen, eine ganze Reihe von Arbeitern in die Finger zu bekommen. Sie sollten sich gut eignen.\n\nIch möchte, dass Ihr eins der Augen benutzt, um einen Arbeiter in die Mine zu schicken. Wenn das ganze Lager in Aufruhr ist, sollte es ihnen unmöglich sein, Euch von einem der anderen Arbeiter zu unterscheiden, die nach dem Angriff umherlaufen.\n\nFindet denjenigen, der für die ganze Operation zuständig ist und macht Euch an die Arbeit. Mit etwas Glück werden wir recht schnell herausfinden, wohin das Saronit verschickt wird. Ich werde Euch durch das Auge hindurch beobachten.", description = "Uns ist es gelungen, eine ganze Reihe von Arbeitern in die Finger zu bekommen. Sie sollten sich gut eignen.\n\nIch möchte, dass Ihr eins der Augen benutzt, um einen Arbeiter in die Mine zu schicken. Wenn das ganze Lager in Aufruhr ist, sollte es ihnen unmöglich sein, Euch von einem der anderen Arbeiter zu unterscheiden, die nach dem Angriff umherlaufen.\n\nFindet denjenigen, der für die ganze Operation zuständig ist und macht Euch an die Arbeit. Mit etwas Glück werden wir recht schnell herausfinden, wohin das Saronit verschickt wird. Ich werde Euch durch das Auge hindurch beobachten.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13174] = {title = "Das Durcheinander nutzen", objective = "Keritose Blutklinge im Schattengewölbe verlangt ein Dokument des Tränenbruchs, ein Geschäftsbuch des Tränenbruchs, eine Karte des Tränenbruchs und einen Zeitplan des Tränenbruchs.", description = "Den Betrieb zum Stillstand zu bringen ist nur die eine Hälfte des Plans. Das andere wichtige Ziel an dieser Stelle ist es, herauszufinden, wohin all das Saronit geschickt wird. Uns sind ein paar Orte bekannt, an denen es wieder auftaucht, doch bei der Menge, die sie aus dem Boden holen, liegt die Vermutung nahe, dass da ein viel größeres Projekt läuft.\n\nSeid Ihr einmal in der Mine, so nehmt alle Dokumente mit, die Ihr finden könnt. Solltet Ihr den Ort mit einem der Greifen angreifen, so könnt Ihr Euch fallenlassen, sobald Ihr die Arbeit erledigt habt.", progress = "Habt Ihr das, was ich wollte?", completion = "Dann lasst uns mal sehen... Was haben wir denn hier...\n\n&lt;Keritose durchforstet die Papiere und scheint wenig zu finden, was er nicht schon vorher wusste - als er plötzlich auf das stößt, wonach er suchte...&gt;\n\nMalykriss! Die unheilvolle Festung. Es scheint, als hätte der Verlust seiner Todesritter Arthas nicht allzu glücklich gemacht... Ich bin mir nicht sicher, was er mit dem ganzen Saronit anfängt, doch er scheint in übertriebenem Maße etwas ausgleichen zu wollen.\n\nDer Junge ist nicht daran gewöhnt, zu verlieren.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13175] = {title = "Die Kontrolle zurückgewinnen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13176] = {title = "Die Lieferung vorbereiten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13177] = {title = "Keine Gnade für die Gnadenlosen", objective = "Hauptmann Zanneth in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Horde tötet.", description = "Willkommen in der Tausendwinterfestung, <Name>. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", progress = nil, completion = "Wie ruhmreich! Wahrlich, Ihr gehört zu den Champions der Allianz.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13178] = {title = "Tötet sie alle!", objective = "Kommandant Dardosh in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Allianz tötet.", description = "Willkommen in der Tausendwinterfestung, <Name>. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!\n\nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.", progress = nil, completion = "Lok'tar! Sieg für die Horde!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13179] = {title = "Keine Gnade für die Gnadenlosen", objective = "Hauptmann Zanneth in Tausendwinter möchte, dass Ihr 10 Mitglieder der Horde tötet.", description = "Willkommen in Tausendwinter, <Name>. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", progress = nil, completion = "Wie ruhmreich! Wahrlich, Ihr gehört zu den Champions der Allianz.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13180] = {title = "Tötet sie alle!", objective = "Kommandant Dardosh in Tausendwinter möchte, dass Ihr 10 Mitglieder der Allianz tötet.", description = "Willkommen in Tausendwinter, <Name>. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!\n\nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.", progress = nil, completion = "Lok'tar! Sieg für die Horde!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13181] = {title = "Sieg in Tausendwinter", objective = "Gewinnt einen Kampf auf dem Schlachtfeld in Tausendwinter und kehrt dann zu Taktikoffizier Ahbramis zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.", description = "Hauptmann Zanneth mag vielleicht zufrieden damit sein, einen Haufen Hordeleichen vor sich liegen zu haben, doch die Kontrolle über die Tausendwinterfestung zu erlangen, ist für die Expedition Valianz von äußerster Wichtigkeit. Kümmert Euch darum, dass sie weiterhin in unseren Händen bleibt.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", progress = nil, completion = "Genau das, was ich hören wollte! Ein Sieg auf dem Tausendwintersee - selbst ein vorübergehender - ist ein äußerst wichtiger Bestandteil unserer Gesamtstrategie gegen die Horde.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13182] = {title = "Vergesst die Eier nicht!", objective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr Azjol-Nerub betretet und 6 Eier der Geißelneruber zerstört.", description = "In ganz Azjol-Nerub liegen Eier verteilt, die von den Nerubern der Geißel gehegt und gepflegt werden und schon bald schlüpfen werden. Sie werden ihre Zahl noch zusätzlich mehren.\n\nEs würde nicht viel nützen, wenn alle Untoten aus den Höhlen getilgt und diese faulen Eier ausschlüpfen würden, nur damit sie an ihre Stelle treten.\n\nKümmert Euch auf jeden Fall darum, dass unsere uralte Heimat von allen Eiern der Geißel gereinigt wird, während Ihr den Ort erkundet, der einst Azjol-Nerub gewesen ist.", progress = nil, completion = "Es macht mich traurig zu sehen, dass es dazu gekommen ist. Wenn wir unser Reich nur wieder zu dem machen könnten, was es einst war...", rewards = "Ausstoßende StulpenReinigende HandschützerWickeltücher des bezwungenen BannsHandschuhe der verbannten AuferlegungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13183] = {title = "Sieg in Tausendwinter", objective = "Gewinnt einen Kampf in einem Schlachtfeld von Tausendwinter und kehrt anschließend zu Taktikoffizier Kilrath in Tausendwinter zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.", description = "Dardosh mag es zwar genügen, unsere Feinde zu töten, doch es ist von äußerster Wichtigkeit, dass wir die Tausendwinterfestung kontrollieren. Tut, was auch immer nötig ist, damit Tausendwinter uns gehört.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", progress = nil, completion = "Ihr habt heute wahrlich etwas Großartiges fertiggebracht. Euer Opfer wird geschätzt!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13184] = {title = "Die Nützlichkeit überdauern", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13185] = {title = "Setzt der Belagerung ein Ende", objective = "Leutnant Murp in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Allianz zerstört.", description = "Ich sie gehört! Die Allianz bald kommen. Mach drei Belagerungsmaschinen kaputt und komm dann wieder zu Murp.", progress = "Hast du ihre Belagerungsmaschinen kaputt gemacht?", completion = "Gute Arbeit. Murp wäre gern dabei gewesen, um zu helfen.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13186] = {title = "Setzt der Belagerung ein Ende", objective = "Chefdemolierer Legoso in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Horde zerstört.", description = "Es ist nur eine Frage der Zeit, bis diese Burg von den Streitkräften der Horde belagert wird. Zerstört drei ihrer Belagerungsmaschinen und kehrt anschließend zu mir zurück.", progress = nil, completion = "Ausgezeichnet. Das sollte ihren Angriff verlangsamen.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13187] = {title = "Die Gesichtslosen", objective = "Seher Ixit möchte, dass Ihr Herold Volazj und die drei Vergessenen an seiner Seite tötet.", description = "Jedes Mal, wenn mein Volk im Kampf gegen die Streitkräfte der Untoten an Boden verlor, grub es tiefer.\n\nVersehentlich legten sie Diener der Alten Götter frei, Wesen, die nur als die Gesichtslosen bekannt sind.\n\nAm Ende konnten wir nicht an zwei Fronten kämpfen.\n\nMit Eurer Hilfe werden die Gesichtslosen hoffentlich endlich fallen.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;.\n\nDank Eures Sieges über die Diener der Alten Götter kann sich nun mein Volk aufmachen, die Stadt seiner Vorfahren zu erobern.", rewards = "Mantel des vereitelten ÜbelsSchulterpolster der VerachtungSchulterplatten des AbgeschafftenSchulterklappen der GesichtslosenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13188] = {title = "Auf den Spuren der Könige", objective = "Bringt den Brief zu König Varian Wrynn, Anhänger der Allianz in Burg Sturmwind in Sturmwind.", description = "Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, <Name>, doch wisset: Einst wart Ihr ein Held der Allianz.\n\n<Darion starrt Euch an.>\n\nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Allianz zeigen.\n\nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Sturmwind. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn König Varian Wrynn bringen. Benutzt das Portal.", progress = "Ihr habt nur noch Sekunden zu leben.", completion = "&lt;Varian starrt in die Ferne.&gt;\n\nIn der Tat, alter Freund... Blut und Ruhm.\n\n&lt;Varian richtet seinen Blick auf Euch.&gt;\n\nWäre dieser Brief von Tirion nicht, wärt Ihr nichts weiter als ein Fleck auf meinem Boden. Nur die Empfehlung eines der größten Paladine, der jemals gelebt hat, hätte Euer Überleben sichern können.\n\nWir... Wir werden zusammen gegen die Geißel kämpfen - gegen den Lichkönig!\n\nEHRE DER ALLIANZ!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13189] = {title = "Der Segen des Kriegshäuptlings", objective = "Bringt den Brief zum Kriegshäuptling der Horde in Orgrimmar.", description = "Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, <Name>, doch wisset: Einst wart Ihr ein Held der Horde.\n\n<Darion starrt Euch an.>\n\nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Horde zeigen.\n\nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Orgrimmar. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn dem Kriegshäuptling überbringen. Benutzt das Portal.", progress = "Eine interessante Wende der Ereignisse.", completion = "Es ist diesem Paladin zu verdanken, dass Etrigg am Leben ist. Hätte Lord Fordring ihn nicht aus Stratholme befreit, wäre er hingerichtet worden.\n\nDass Tirion Fordring alles geopfert hat, um das Leben eines Orcs zu retten... Ich kenne nur einen Menschen, der solch ein Opfer gebracht hat.\n\n&lt;Thrall hält eine Träne zurück.&gt;\n\nDu wirst immer in meinem Herzen bleiben, Taretha.\n\nJa. Für Tirion Fordring und Etrigg! Wir werden Euch als Mitglied der Horde akzeptieren und Euren Orden als Verbündete betrachten.\n\nBlut und Donner! Für die Horde!", rewards = nil}
MultiLanguageQuestData['de'][13190] = {title = "Alles zu seiner Zeit", objective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr die Leiche eines Wächters der Ahn'kahar beschafft und sie auf das Kohlenbecken von Ahn'kahet in Ahn'kahet legt.\n\nDiese Quest kann nur auf dem Schwierigkeitsgrad 'Heroisch' beendet werden.", description = "Ahn'kahet, woher wir einst kamen...\n\nIch träume davon, dass wir eines Tages Tod und Dunkelheit, in deren Griff sich unsere uralte Heimat befindet, überwinden werden. Zu diesem Zweck habe ich einen Plan entworfen, mit dem wir unsere Feinde entmutigen können.\n\nIhre kostbaren Wächter müssen brennen!\n\nLegt ihre Leichen auf die Kohlenpfanne tief im Inneren der Stadt. Der Geruch ihrer verbrannten Überreste wird in der Luft hängen und unseren Feind an seine Schwäche erinnern.\n\nGeht mit Bedacht vor, <Klasse>! Ihre untoten Leichen sind äußerst zerbrechlich und werden rasch verrotten.", progress = "Konntet Ihr die Leiche eines Wächters verbrennen, <Volk>?", completion = "Aha!\n\nMöge der spöttische Geruch des Versagens an ihren leeren Seelen nagen!\n\nIch danke Euch, &lt;Klasse&gt;. Ihr habt den Untoten an diesem heutigen Tage einen Schlag versetzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13191] = {title = "Verwüster auftanken", objective = "Belagerungsschmied Starkhuf in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.", description = "Lok'tar, <Name>! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die Feuerelementare in der Gegend zu bekämpfen, bis Ihr welche findet!", progress = "Nun? Konntet Ihr die Glutstücke finden? oder hat die Allianz alles gestohlen und Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird uns dabei helfen, die Allianz in den kommenden Schlachten zu besiegen!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13192] = {title = "Die Wälle schützen", objective = "Hoodoomeister Fu'jin in der Tausendwinterfestung möchte, dass Ihr 10 verzauberte Brustplatten der Allianz aus dem Gebiet der Eiswasserfälle beschafft.", description = "Hey, Mann. Bei dem Ort hier krieg ich 'ne Gänsehaut, weißt du?\n\nHier spuken viel zu viele Geister rum. Ich will Hoodoobarrieren aufstellen, brauch aber 'n paar Seelen dafür, Mann. Aber nich' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.\n\nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man 'ne Seele heraussaugen kann. Bring die Allianzler dort um - vielleicht haben sie das Zeug, das wir brauchen.\n\nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin', dann haben die Elementare vielleicht welche, Mann.", progress = "Hast du die Rüstungen mit dabei, Mann?", completion = "Ooh, ja, das is' das Zeug, Mann!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13193] = {title = "Pfeil und Knochen", objective = "Leutnant Vieron Flammenfeder in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", description = "Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. <Name>, ich brauche Drachenknochen für unsere Pfeilspitzen.\n\nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.\n\nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.", progress = "Schon so früh zurück? Verflixt, hatte gehofft, mich einen Moment lang ausruhen zu können.", completion = "Tja, ich nehme an, das heißt für mich: noch eine Nacht Knochen schärfen. Wieso bin ich nicht wie mein Bruder in Silbermond geblieben?", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13194] = {title = "Mit Rosen heilen", objective = "Primalist Mulfort möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.", description = "Zwischen den Schlachten mag einer schon fast daran glauben, dass es Hoffnung auf Frieden in diesem Land gäbe. Leider hat unser Schicksal anderes mit uns vor.\n\nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.\n\nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen ihre Kräuterbeutel ab.\n\nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.", progress = "Habt Ihr die Kräuter dabei? Die Verwundeten und Kranken werden von Stunde zu Stunde mehr.", completion = "Ich danke Euch, das wird uns eine große Hilfe bei der Behandlung unserer verwundeten Soldaten sein.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13195] = {title = "Ein seltenes Kraut", objective = "Anachoret Tessa in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel abnehmt.", description = "Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.\n\nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn Kräuterbeutel der Horde. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.\n\nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen ihre Kräuter ab!\n\nDie Peitscher in der Gegend können auch welche bei sich haben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13196] = {title = "Pfeil und Knochen", objective = "Bogenmacher Randolph in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", description = "Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.\n\nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.\n\nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!\n\nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!", progress = "Wie ist die Jagd gelaufen? Ich habe Gerüchte darüber gehört, dass es an dem Ort spuken soll. Ich gehe jedoch nie selbst dorthin.", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13197] = {title = "Verwüster auftanken", objective = "Belagerungsschmied Starkhand in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.", description = "<Name>! Wurde auch langsam Zeit, dass Ihr auftaucht. Wir mögen zwar die letzte Schlacht verloren haben, doch wir sollten uns noch immer auf die nächste vorbereiten! Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und beschafft mehrere Stück Immerglut.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihnen die Glutstücke weg. Wir müssen verhindern, dass die Festung in ihrer Kontrolle bleibt!", progress = "Nun? Konntet Ihr die Glutstücke finden? Oder ist Euch die Horde zuvorgekommen und hat Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13198] = {title = "Die Krieger schützen", objective = "Zauberin Kaylana in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen der Horde abnehmt.", description = "<Name>, gut, Euch zu sehen. Wir müssen uns auf unseren nächsten Angriff auf die Festung vorbereiten. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Die Horde war damit beschäftigt, in dieser Gegend Rüstungen einzusammeln.\n\nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.\n\nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.", progress = "Habt Ihr die Rüstungen nun gefunden?", completion = "Oh, die tropfen noch immer. Hättet Ihr sie nicht zuerst trocknen können?", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13199] = {title = "Pfeil und Knochen", objective = "Leutnant Vieron Flammenfeder in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", description = "Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. <Name>, ich brauche Drachenknochen für unsere Pfeilspitzen.\n\nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.\n\nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.", progress = "Schon so früh zurück? Verflixt, hatte gehofft, mich einen Moment lang ausruhen zu können.", completion = "Tja, ich nehme an, das heißt für mich: noch eine Nacht Knochen schärfen. Wieso bin ich nicht wie mein Bruder in Silbermond geblieben?", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13200] = {title = "Verwüster auftanken", objective = "Belagerungsschmied Starkhuf in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.", description = "Lok'tar, <Name>! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die dortigen Feuerelementare zu bekämpfen, bis Ihr welche findet!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13201] = {title = "Mit Rosen heilen", objective = "Primalist Mulfort in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.", description = "So viele unserer Tapferen sind in der Schlacht gefallen, doch noch mehr werden sterben, wenn sie nicht behandelt werden.\n\nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.\n\nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen die Kräuterbeutel ab.\n\nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13202] = {title = "Die Mauern verhexen", objective = "Hoodoomeister Fu'jin in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und Allianzspielern dort 10 verzauberte Brustplatten der Allianz abnehmt.", description = "Hey, Mann. Siehst du, wie die Allianzler sich's in ihrer Festung bequem machen?\n\nDenke, die sehen ein wenig zu bequem aus, findste nich'? Ich will den Ort verhexen, aber ich brauch dafür 'n paar Seelen, Mann. Aber nich' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.\n\nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man 'ne Seele heraussaugen kann. Bring die Allianzler dort um - die haben das Zeug, das wir brauchen.\n\nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin', dann haben die Elementare vielleicht welche, Mann.", progress = "Hast du die Rüstungen mit dabei, Mann?", completion = "Ooh, ja, das is' das Zeug, Mann!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13203] = {title = "Ein Winterhauchgeschenk", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWinterhauchgeschenk"}
MultiLanguageQuestData['de'][13204] = {title = "Abgefahrene Pilze", objective = "Ihr sollt 6 groteske Pilze von den wilden Höhlenbestien in Ahn'kahet sammeln und sie bei Kilix dem Entwirrer in der Grube von Narjun abliefern.", description = "Ein unförmiges Stück pilzähnlichen Fungus fällt von einem besonders übel riechenden, schlammbedeckten Teil des Fleischs der Höhlenbestie. Als Ihr ihn näher betrachtet, werdet Ihr von dessen Gestank überwältigt und weicht angewidert zurück.\n\nIhr wundert Euch, ob die Neruber so etwas appetitlich finden. Ihr steckt den klebrigen Organismus in Eure Tasche und seid fest dazu entschlossen, es herauszufinden...", progress = "Was im Namen der Schöpfung ist das?!", completion = "Habt Ihr irgendeine Vorstellung davon, was Ihr da mit Euch herumgetragen habt, &lt;Klasse&gt;?\n\nDie Höhlenbestien, von denen Ihr das habt, sondern ihren Abfall nicht auf die dahergebrachte Art und Weise ab. Ihr solltet Eure Hände waschen...\n\nDanke, dass Ihr an uns gedacht habt, doch falls Ihr noch mehr von diesen Dingern finden solltet, dann haltet Euch davon fern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13205] = {title = "Abrüstung", objective = "Verteidiger Mordun möchte, dass Ihr Burg Utgarde betretet und 5 Waffen der Vrykul stehlt.", description = "Glaubt mir, <Kamerad/Fräulein>, die Waffen der Vrykul sind durchweg gefährlich!\n\nIch habe ihre Schneiden am eigenen Leib erfahren und muss sagen, dass sie etwas Unnatürliches an sich haben. Sie sind täuschend gut ausbalanciert und unverschämt scharf - kurz gesagt einfach tödlich.\n\nGelangt in ihre Festung und krallt Euch zumindest einige dieser Waffen! Vielleicht können wir etwas von ihnen lernen, vielleicht auch nicht.\n\nIm Endeffekt ist es so: Je weniger Äxte sie herumschwingen, desto besser.", progress = "Habt Ihr Euch ein paar dieser Vrykuläxte gekrallt?", completion = "&lt;Mordun pfeift.&gt;\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nKein Glück...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett des ruhigen GemütsRasierklingenanhängerHalskette des gestreuten LichtsGewebte Stahlhalskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13206] = {title = "Abrüstung", objective = "Dunkelläuferin Marrah möchte, dass Ihr 5 Waffen der Vrykul aus Burg Utgarde stehlt und sie ihr in Burg Utgarde bringt.", description = "Wir müssen hinter das Geheimnis der Waffen dieser Barbaren kommen!\n\nWenn Ihr nur gesehen hättet, wie leicht sie meine Gefährten in Stücke schnitten, würdet Ihr verstehen, weshalb ich so dränge.\n\nSucht den Ort ab. Sammelt so viele ihrer Waffen, wie Ihr nur tragen könnt.", progress = "Konntet Ihr ihre Waffen stehlen?", completion = "Jede Waffe, die wir ihnen abnehmen, wird nicht im Fleisch eines Soldaten landen.\n\nDanke.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHalskette der ruhigen HimmelHundertzahnhalsketteAmulett der eingeschränkten KraftKachelsteinanhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13207] = {title = "Die Hallen des Steins", objective = "Brann Bronzebart möchte, dass Ihr ihn bei der Suche nach den Geheimnissen, die in den Hallen des Steins verborgen liegen, begleitet.", description = "Also ich bin überrascht, an einem Ort wie diesem andere Abenteurer anzutreffen.\n\nWenn meine Untersuchungen über diese Hallen stimmen, dann sind hier gewaltige Entdeckungen zu machen!\n\nIhr könnt gerne mitkommen, wenn ich mich darauf verlassen kann, dass Ihr mir Rückendeckung gebt.", progress = "Tja, nun, es hat sich letztlich als gut herausgestellt, dass wir uns begegnet sind.", completion = "Gibt immer mehr Fragen als Antworten, nicht wahr, Kamerad?", rewards = "Mantel des unerschrockenen EntdeckersSchulterpolster des AbenteurersSchiftung der verlorenen GeheimnisseSchulterstücke der AufklärungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13211] = {title = "Das Feuer wird Euch läutern", objective = "Kreuzfahrer Olakin Sainrith bei der Schwarzwacht möchte, dass Ihr mithilfe Olakins Fackel 7 eitrige Leichen verbrennt.", description = "Die Geißel benutzt unsere eigenen Gefallenen gegen uns, indem sie sie als Ghule oder Skelette wiederauferstehen lässt oder ihre Körper zerlegt und die Einzelteile benutzt, um neue Monstrositäten herzustellen. Das muss aufhören!\n\nDie Toten sind Helden, die in Verteidigung allen Lebens fielen und ein solch grausiges Schicksal muss ihnen erspart bleiben. Darüber hinaus können wir es uns einfach nicht leisten, ihnen im Feld erneut gegenüberzustehen, als Waffen gegen uns eingesetzt. Nehmt diese Fackel mit Euch in die Fleischwerke und verbrennt alle Leichen, die Ihr im Sanktum der Reanimation oder im Monstrositätenlabor finden könnt.", progress = nil, completion = "&lt;Kreuzfahrer Olakin Sainrith hört aufmerksam zu, während Ihr Bericht erstattet.&gt;\n\nEs ist nicht das Begräbnis, das sie verdient hätten, aber es ist besser als nichts und besser für die, die noch leben. Ich danke Euch, &lt;Name&gt;.", rewards = "Sanfte Berührung des KreuzfahrersOlakins verzauberte FackelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13212] = {title = "In die Brüche gegangen", objective = "Bergt Olakins Oberkörper, Olakins Beine, Olakins linken Arm und Olakins rechten Arm und bringt sie der Dunkelreiterin Arly in der Schwarzwacht.", description = "Die Entführung des Kreuzzüglers Olakin lässt die Streitkräfte des Argentumkreuzzugs beim letzten Sturm auf die Fleischwerke führerlos dastehen. Obwohl für mich ein Kreuzzügler aussieht wie der andere, sehen die Argentumsoldaten das anders.\n\nEs gefällt mir gar nicht, unsere Zeit mit einer Schnitzeljagd zu verschwenden, aber ich habe keine andere Wahl. Unser heldenhafter Kreuzzügler wurde vermutlich schon längst in seine Einzelteile zerlegt und seine Überreste beim Zusammenbau von Monstrositäten verwendet. Geht hinunter in die Fleischwerke, tötet die Schrecken, die unsere Truppen bekämpfen, und bringt Olakins Körperteile zurück.", progress = "Habt Ihr die, äh, Überreste von Kreuzfahrer Olakin?", completion = "Nun, ich denke, es ist gut, dass wir den Kreuzfahrer \"gerettet\" haben, obwohl ich bezweifle, dass es dies war, was seine Kameraden im Sinn hatten. Dann lasst uns mal sehen, was wir tun können, um ihn wieder auf die Beine zu bringen, damit wir diese Farce hinter uns bringen und unsere Mission hier vollenden können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13213] = {title = "Kampf bei Valhalas", objective = "Sprecht mit Geirrvif in Valhalas.", description = "Ich sehe und höre viele Dinge, <Name>, und etwas sehr Wichtiges ist passiert, seitdem Ihr Oberthan Balgarde besiegt habt: Man will gegen Euch in Valhalas kämpfen!\n\nDie Kampfgrube befindet sich gen Norden. Geht jetzt, nehmt Eure Freunde mit, und sprecht mit Geirrvif der Val'kyr. Bei den Herausforderern, die sie gegen Euch in den Ring werfen wird, werdet Ihr sicherlich Unterstützung brauchen.\n\nViel Glück.", progress = nil, completion = "Ihr habt unsere besten Kämpfer besiegt. Euer Name ist in aller Munde, &lt;Name&gt;.\n\nWomöglich denkt Ihr, das mich das stört - doch das tut es nicht. Wenn sie Euch unterliegen, dann sind sie unwürdig und nichts weiter als niedere Vargul!\n\nDoch vielleicht kann ich Euch und Euren Freunden etwas anderes geben, mit dem Ihr Euch vergnügen könnt. Valhalas ist unter anderem ein Ort, in dem Kämpfe jeglicher Art mit verschiedenartigen Gegnern geboten werden.\n\nSprecht mich wieder an, wenn Eure Freunde und Ihr bereit seid weiterzumachen. Wir werden sehen, ob Ihr wahrhaftig würdig seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13214] = {title = "Kampf bei Valhalas: Gefallene Helden", objective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, im Einzelkampf alle sechs gefallenen Helden zu besiegen: Eldreth, Geness Halbseele, Jhadras, Masud, Rith und Talla.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", description = "Wenn Ihr glaubt, soweit zu sein, dann habe ich genau den richtigen Kampf für Euch, um Euch Eure ersten Sporen zu verdienen.\n\nEine andere Gruppe von Außenseitern dachte, sie wären bereit, sich der Härte Valhalas zu stellen. Sie schwangen große Reden und fielen am Ende doch wie all die anderen vor ihnen.\n\nWenn Ihr Euch für so anders haltet - wenn Ihr glaubt, Ihr hättet die Fähigkeiten und die Erfahrung, hier gegen solch sagenumwobene Krieger anzutreten - dann nehmt die Herausforderung bitte an.", progress = nil, completion = "Frischfleisch.\n\n&lt;Der Todesritter der Vrykul spuckt Euch vor die Füße.&gt;\n\nIhr denkt alle, dass Ihr das Zeug dazu habt, hier zu kämpfen.\n\nIhr seid nichts angesichts der Macht der Vrykul und der Geißel!\n\nDoch immerhin habt Ihr es geschafft, sechs inkompetente Leichen zu besiegen - Ihr müsst also was können. Doch höchstwahrscheinlich nicht genug für das, was als nächstes kommen wird.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13215] = {title = "Kampf bei Valhalas: Khit'rix der Dunkle Meister", objective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Khit'rix den Dunklen Meister zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", description = "Verschiedene Wesen reisen um die ganze Welt, um sich in Valhalas selbst zu beweisen; einige kommen sogar aus der Unterwelt.\n\nKhit'rix der Dunkle Meister ist so einer.\n\nEr ist in den Tiefen dieser Erde geboren, dort, wo Wahnsinn herrscht, und er verlangt nach jemandem, der anders als die meisten ist und sich ihm im Ring stellen wird. Ihr werdet genügen.\n\nWagt Ihr es, <Volk>, dem nerubischen Alptraum gegenüberzutreten?", progress = nil, completion = "Ihr wollt mich damit beeindrucken, dass Ihr gemeinsam mit Euren Freunden einen einzelnen nerubischen Priester umhauen konntet?\n\nGeht mir aus den Augen, bevor ich meine Ghule auf Euch hetze!", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13216] = {title = "Kampf bei Valhalas: Die Rückkehr von Sigrid Eiskind", objective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Sigrid Eiskind zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", description = "Ein alter Feind von Euch ist zurückgekehrt: Sigrid Eiskind. Vielleicht könnt Ihr Euch noch daran erinnern, wie Ihr sie auf der Wilden Klippe besiegt habt?\n\nEgal, sie kann sich noch sehr gut an Euch erinnern. Sie besteht darauf, sich noch einmal beweisen zu dürfen.\n\nIch persönlich denke, dass es eher um Rache geht, doch auch das kann hier nützlich sein.\n\nIch überlasse es Euch, <Name>. Werdet Ihr Euch einmal mehr Sigrid Eiskind stellen?", progress = nil, completion = "Der Sieg über eine der Hyldnir ist schon ein bisschen beeindruckend, &lt;Volk&gt;, aber Ihr hattet die Hilfe Eurer Freunde.\n\nIhr hattet Glück, dass Ihr Drache nicht mit von der Partie war.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRunenverzierter HeiltrankRunenverzierter Manatrank\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13217] = {title = "Kampf bei Valhalas: Massaker!", objective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Massaker zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", description = "Ihr habt es zwar bis hierher geschafft, <Name>, doch um weiterhin in Valhalas zu kämpfen, müsst Ihr einem gigantischen Schrecken gegenübertreten, wie Ihr ihn Euch gar nicht vorstellen könnt.\n\nIch muss Euch dazu raten, jetzt kehrt zu machen. Massaker ist ein Fleischberg, erschaffen von den grausamsten Köpfen, die im Dienste des Lichkönigs stehen.\n\nIch kann mir nicht vorstellen, wie Eure Freunde und Ihr ihn besiegen wollt. Die Entscheidung liegt jedoch bei Euch.", progress = nil, completion = "Euer Können im Ring flößt mir langsam Respekt ein, &lt;Name&gt;. Jetzt kann ich Euch wirklich nicht leiden.\n\nIch hätte es lieber gehabt, Eure Freunde und Euch an der Fußsohle dieses Fleischriesens kleben zu sehen!", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13218] = {title = "Kampf bei Valhalas: Than Todesstoß", objective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Than Banahogg den \"Todesstoß\" zu besiegen.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", description = "Die Vrykul von Jotunheim haben nicht übersehen, welches Können Ihr an den Tag legt, <Name>. Than Banahogg hat ein persönliches Interesse an Euch gezeigt und darauf bestanden, Euer nächster Gegner zu sein.\n\nWenn Ihr Massaker schlimm fandet, dann wäre es wohl besser, wenn Ihr jetzt nach Hause geht. Than Banahoggs Spitzname ist \"Todesstoß\". Ich denke, Ihr könnt erraten, wie er sich den verdient hat.\n\nAkzeptiert Ihr die Herausforderung des Thans?", progress = nil, completion = "Ich weiß nicht, welche Tricksereien Ihr aus dem Ärmel gezogen habt, um den Than umzuhauen - von hier aus konnte ich's nicht sehen -, doch ich kann Euch versichern, dass Ihr Euren nächsten Kampf nicht überleben werdet.\n\nJa, ich weiß, wer es ist. Rennt, &lt;Volk&gt;, rennt weg! Flieht in die letzten Ecken dieser Welt.\n\nOder bleibt und sterbt - mir ist es gleich.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13219] = {title = "Kampf bei Valhalas: Letzte Herausforderung", objective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Prinz Sandoval zu besiegen.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", description = "Ich fürchte, dass Euer Erfolg auch Euer Untergang sein wird, <Name>.\n\n<Könnte die Val'kyr noch bleicher werden, dann würde sie das gerade.>\n\nNachrichten über Euren Erfolg in Valhalas sind bis tief in die Eiskronenzitadelle vorgedrungen und haben jemanden wachgerufen, den Ihr lieber nicht kennen möchtet.\n\nPrinz Sandoval höchstpersönlich ist in diesem Augenblick auf dem Weg hierher. Gjonner hat Euch gewarnt und gesagt, dass Ihr wegrennen solltet, und ich kann ihm nicht widersprechen.\n\nWas werdet Ihr tun? Er ist auf dem Weg hierher. Werdet Ihr Euch dem Blutprinzen im letzten Kampf entgegenstellen?", progress = nil, completion = "Euer Sieg über Prinz Sandoval macht mich krank. Ein ungewaschener Bauer wie Ihr es seid hätte freiwillig sein Leben dafür geben sollen, auch nur die Chance zu bekommen, ihm begegnen und vor seinen Füßen niederknien zu dürfen.\n\nIhr habt Eure verdammte Belohnung verdient. Entscheidet Euch schnell.", rewards = "Roben der zurückhaltenden FeierKampfplatte der ungehörten OvationenBrustschutz des ungewollten ErfolgsTunika des übermäßigen SiegersIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13220] = {title = "Olakin wieder zusammensetzen", objective = "Beschafft Euch eine Garnspule und den Spalter des Doktors. Geht dann zur Steinplatte des Sanktums der Reanimation und versucht, Kreuzfahrer Olakins sterbliche Überreste wiederzubeleben. Kehrt zu Dunkelreiterin Arly in die Schwarzwacht zurück, sobald die Aufgabe vollbracht ist.", description = "Wir können es uns nicht leisten, irgendwelche Zeit zu verlieren und Olakin wieder zusammenzusetzen. Zum Glück bietet Euch die Geißel den perfekten Ort, um ihn wieder zusammenzuflicken.\n\nIn der Nähe des Fleischriesenlabors in den Fleischwerken befindet sich das Sanktum der Reanimation. Sucht in der Gegend nach einer Garnspule und dem Spalter des Doktors. Bringt anschließend Olakins sterbliche Überreste zur großen Platte in der Mitte des Sanktums und macht Euch an die Arbeit.", progress = nil, completion = "Olakin sollte sich glücklich schätzen. Niemand wird aus den Fängen der Geißel befreit, niemand. Kein Garn der Welt und keine heldenhafte Tat wird ihn jedoch ein zweites Mal retten. Ich werde dafür sorgen, dass er sich daran erinnert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13221] = {title = "Noch bin ich nicht tot!", objective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Absalan dem Frommen an Bord der Himmelsbrecher Bericht.", description = "Das Licht ist mir hold. Noch bin ich in diesem wahrgewordenen Alptraum nicht umgekommen, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt, zu entkommen.\n\nAlleine werde ich es nicht schaffen, mein Kind, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen, zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", progress = nil, completion = "Dem Licht sei Dank. Ich glaubte, Vater Kamaros sei tot, oder ihm sei noch Schlimmeres zugestoßen. Eure Tapferkeit und Euer Mitgefühl haben dazu geführt, dass ein wichtiger Verbündeter zum Argentumkreuzzug zurückkehren konnte. Ihr habt meinen Dank und den des Kreuzzugs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13222] = {title = "Belagerungsmaschinen verteidigen", objective = "Chefdemolierer Legoso in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder beschützt. Die Maschine muss drei Gebäude zerstören.\n\nSpieler, die den Rang \"Gefreiter\" oder höher besitzen, können Belagerungsmaschinen in Goblinwerkstätten bauen.", description = "An vorderster Front, <Name>! Wir starten unseren Angriff auf die Tausendwinterfestung. Diese barbarischen Hordler denken wohl, sie könnten sich feige hinter ihren Mauern verkriechen? Nun, ich denke nicht! Wir werden ihnen zeigen, wie mächtig gnomische Technologie ist, und ihre Mauern zertrümmern!\n\nDoch ohne Mannschaft ist selbst die stärkste Belagerungsmaschine hilflos ausgeliefert. Steuert oder beschützt eine unserer Belagerungsmaschinen - es müssen drei Gebäude der Horde zerstört werden.", progress = nil, completion = "Das sollte ihnen zeigen, wie mächtig gnomische Erfindungen sind!", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines SteinbewahrersEhrepunkte"}
MultiLanguageQuestData['de'][13223] = {title = "Belagerungsmaschinen verteidigen", objective = "Leutnant Murp in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder verteidigt. Die Maschinen müssen 3 Gebäude der Allianz zerstören.\n\nBelagerungsmaschinen können von Spielern der Horde, die einen Rang haben, in Goblinwerkstätten gebaut werden.", description = "Die Allianz die Festung nicht mehr lange halten wird. Murp würde Mauern kaputt hauen, doch Murp muss im Lager bleiben. Murp wünscht sich, er könnte Allianzler kaputt hauen, die Verwüster von Horde wehtun wollen.\n\nDu, <Name>! Du gehst anstatt Murp. Beschütz 3 Belagerungsmaschinen, wenn die gerade die Allianzgebäude kaputt machen. Zeig der Allianz wie klug Murp ist!", progress = nil, completion = "Gute Arbeit. Murp wäre gern dabei gewesen, um zu helfen.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13224] = {title = "Orgrims Hammer", objective = "Sucht Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer über dem Eiskronengletscher auf.", description = "Der Argentumkreuzzug hat meinen böse zugerichteten Körper von der Zerbrochenen Front hergeschleppt. Was für ein ruhmreicher Kampf, <Volk>. Meine Axt sang, als sie ohne Unterschied Allianzabschaum und Geißler niedermachte.\n\nMeine Zeit ist vorüber. Es wird ein guter Tod sein. Überbringt eine Nachricht für mich, Soldat.\n\nUnsere Basis fliegt außerhalb der Reichweite der Geißel - hoch droben, zwischen Mord'rethar und Aldur'thar. Sie wird \"Orgrims Hammer\" genannt.\n\n<Hork bemüht sich vergeblich, zu salutieren.>\n\nFliegt hoch und geht dem Monstervehikel der Allianz aus dem Weg, der Himmelsbrecher. Sagt Korm... Sagt ihm, dass ich gestorben bin... im Kampf... Für die Horde.", progress = nil, completion = "&lt;Korm salutiert.&gt;\n\nVerdammt soll die Geißel sein - und die Allianz! Hork war einer unserer Besten. Wir werden unsere Rache haben. Für Höllschrei und für die Horde!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13225] = {title = "Die Himmelsbrecher", objective = "Sprecht mit Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher, die über der Eiskrone fliegt.", description = "Wir steckten bis zum Hals in Einheiten der Geißel und der Horde. Die Schreie der Sterbenden erfüllten das Feld. Es war die reine Folter... erbarmungslos!\n\nMein Körper hat einfach irgendwann aufgegeben und ich fiel. Der Argentumkreuzzug hat mich wieder zurückgeholt. Sie haben mich von der Zerbrochenen Front geholt und hergebracht. Ich werde es aber nicht schaffen. Bitte, gewährt Ihr einem sterbenden Soldaten einen letzten Wunsch, <Volk>? Unsere Basis, die Himmelsbrecher, fliegt über der Eiskrone. Dort werdet Ihr meinen befehlshabenden Offizier, Stabshauptmann Bartlett antreffen. Sagt ihm, dass ich als Soldat der Allianz gestorben bin.", progress = nil, completion = "&lt;Stabshauptmann Bartlett salutiert.&gt;\n\nEr war ein verdammt guter Soldat. Verflucht sei die Horde und verflucht sei die Geißel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13226] = {title = "Der Tag der Abrechnung kommt!", objective = "Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.", description = "Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!\n\nIch beschwöre Euch, <Bruder/Schwester>, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.\n\nGeht jetzt, <Klasse>, der Tag der Abrechnung steht bevor!", progress = nil, completion = "Meine treuen Ritter haben mir einen guten Dienst erwiesen. Es scheint, dass Ihre Anwerbungsbemühungen uns einen Helden beschert haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13227] = {title = "Der Tag der Abrechnung kommt!", objective = "Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.", description = "Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!\n\nIch beschwöre Euch, <Bruder/Schwester>, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.\n\nGeht jetzt, <Klasse>, der Tag der Abrechnung steht bevor!", progress = nil, completion = "Meine treuen Ritter haben mir einen guten Dienst erwiesen. Es scheint, dass Ihre Anwerbungsbemühungen uns einen Helden beschert haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13228] = {title = "Die Zerbrochene Front", objective = "Korm Schwarznarbe an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und einen sterbenden Berserker dazu befragt, was geschehen ist.", description = "Welche Schlacht?! Diese Truppen waren auf Aufklärungsmission!\n\nUnd was soll das Gerede von wegen Allianz?\n\nJetzt hört mir mal zu, <Name>! Ich muss wissen, was hier vor sich geht und ich muss es JETZT wissen!\n\nBewegt Euch und besorgt mir ein paar Antworten! Durchkämmt das Schlachtfeld und sucht nach Überlebenden - Hinweisen - irgendwas etwas!", progress = nil, completion = "Sie haben gesehen, dass die Allianz das Tor angegriffen hat und sie sind ihnen in den Rücken gefallen...\n\n&lt;Nach einer kurzen Pause bricht Korm in Gelächter aus.&gt;\n\nDAS ist genau das, wofür die HORDE steht!\n\nWenn sie nicht gewesen wären, so würden die Allianzmaden nun vermutlich das Tor halten!\n\nIhr Mut hat uns kostbare Zeit verschafft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13229] = {title = "Noch bin ich nicht tot!", objective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Bruder Keltan an Bord der Orgrims Hammer Bericht.", description = "Das Licht ist mir hold. Noch bin ich in diesem wahr gewordenen Alptraum nicht umgekommen, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt, zu entkommen.\n\nAlleine werde ich es nicht schaffen, <Klasse>, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen, zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", progress = nil, completion = "Ihr habt gute Arbeit geleistet. Wir glaubten Vater Kamaros verloren. Eure Tapferkeit wird allen denen, die sich der Geißel widersetzen, als Beispiel dienen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13230] = {title = "Rächt mich!", objective = "Ein sterbender Berserker hat Euch darum gebeten, 5 sterbende Soldaten an der Zerbrochenen Front zu töten. Erstattet Himmelshäscher Korm Schwarznarbe auf der Orgrims Hammer Bericht, sobald dies erledigt ist.", description = "Ich kann sie hören, <Bruder/Schwester>...\n\nDas Stöhnen der verwundeten Allianzler... Sie verspotten mich...\n\nBeendet, was wir hier begonnen haben, <Klasse>. Zeigt keine Gnade... Lasst niemanden am Leben.\n\nFür die Horde...", progress = nil, completion = "Die Zeiten der Toleranz gegenüber der Allianz sind vorbei, &lt;Name&gt;.\n\nSie haben unseren Hass verdient! Sie sollen in Angst vor der Horde zittern, solange, bis sie nicht länger unsere Welt verschmutzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13231] = {title = "Die Zerbrochene Front", objective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr Euch an die Zerbrochene Front begebt, den sterbenden Soldaten befragt und ihm dann erneut Bericht erstattet.", description = "Was?! Neeeiinn!\n\nWir haben uns doch solche Mühe gegeben, diesen Angriff geheim zu halten. Woher wusste die Horde Bescheid? Die Reserven... Die Männer... Alles verloren? Unfassbar!\n\nUnsere Pläne in Eiskrone basierten darauf, dass das Tor vor der Horde genommen werden würde. Wir müssen uns schnell neu formieren und uns darauf vorbereiten, eine weitere Offensive zu starten.\n\nBegebt Euch zum Schlachtfeld und sucht nach Überlebenden. Versucht, so viele Informationen wie möglich über diese Tragödie zu sammeln.\n\nUnd macht Euch bereit, <Name>, für einen Krieg - an zwei Fronten...", progress = nil, completion = "Wir mussten also eine Schlappe einstecken - eine verheerende Niederlage... Dies wird nicht vergessen werden.\n\nMerkt Euch meine Worte, &lt;Klasse&gt;. Die Horde wird hierfür bezahlen... Es wird keine Gnade geben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13232] = {title = "Tötet mich!", objective = "Der sterbende Soldat an der Zerbrochenen Front möchte, dass Ihr 5 sterbende Soldaten erlöst und dann Stabshauptmann Justin Bartlett auf der Himmelsbrecher Bericht erstattet.", description = "Sie verspotten uns - selbst noch hier, während sie im Sterben liegen...\n\nIch bitte Euch... Lasst es nicht zu, dass ihr Spott das Letzte sein wird, was ich höre...\n\nTötet mich... erlöst mich von dieser Qual... und führt mich... zum Licht.\n\nGeht zu meinen Gefährten... gewährt ihnen dieselbe Gnade.\n\nHinterlasst der Geißel nichts, das sie wiederbeleben könnte!\n\nIch flehe Euch an...", progress = nil, completion = "Was Ihr getan habt, war nicht einfach, &lt;Klasse&gt;, aber das Richtige.\n\nLasst Euch von den Erinnerungen an das, was Ihr getan habt, nicht quälen. Nutzt Eure Gefühle aus - den Kummer und den Schmerz! Nutz sie aus und richtet sie gegen die Schuldigen.\n\nDie Horde muss bezahlen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13233] = {title = "Keine Gnade!", objective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr in Eiskrone 15 Spieler der Horde tötet.", description = "Es ist, wie ich es Euch gesagt habe. Es waren nicht nur leere Worte, im Zorn gesprochen.\n\nWieder und wieder hat die Horde gezeigt, dass sie nichts auf das gibt, was uns am Herzen liegt. Für ihre Sünden gegen das Licht müssen sie mit dem Leben zahlen!\n\nJeder einzelne von ihnen.\n\nStellt Euch nur vor, <Name>, eine Welt ohne ihren Makel. Malt Euch aus, wie glücklich unsere Kinder aufwachsen könnten. Denkt daran, wie ehrfürchtig Eure Nachkommen Euren Namen aussprechen würden - da sie doch wissen, dass sie all ihr Glück nur Euch zu verdanken haben.\n\nGeht nun und lasst die Vision Realität werden!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;!\n\nBringt sie zur Strecke und lasst sie dafür bezahlen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13234] = {title = "Sie müssen zahlen!", objective = "Himmelshäscher Korm Schwarznarbe möchte, dass Ihr 15 Spieler der Allianz in Eiskrone tötet.", description = "Die Zeit ist gekommen!\n\nViel zu lange mussten wir die Selbstgerechtigkeit der Allianz ertragen! Viel zu lange mussten wir uns zurückhalten, haben unsere Welt nicht von Schwachen und Verzweifelten gereinigt.\n\nJetzt endlich werden wir die Erniedrigung beenden! Jetzt werden wir ihnen die wahre Bedeutung von Angst zeigen! Jetzt werden wir der Horde Ehre machen!\n\nHier, in Eiskrone, werden wir die Allianz brechen!\n\nGeht, <Klasse>. Geht und bringt sie zur Strecke. Brecht sie! Nehmt ihnen den Willen zu leben!", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Klasse&gt;.\n\nSchon bald wird die Allianz ängstlich vor Euch flüchten und die Horde wird Euren Namen ehren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13235] = {title = "Der gigantische Fleischgigant", objective = "Sprecht mit Markgraf Dhakar am westlichen Ende der Fleischwerke, um die Aufmerksamkeit von Morbidus zu erregen. Erstattet der Dunkelreiterin Arly an der Schwarzwacht Bericht, nachdem Ihr Morbidus getötet habt.", description = "Mit der Zerstörung der Fleischwerke und der Vernichtung der Diener des Lichkönigs habt Ihr gute Arbeit geleistet. Nun ist alles, was noch zu tun bleibt, die Vernichtung des Meisterwerks der Fleischwerke - die Vernichtung des Fleischgiganten namens Morbidus.\n\nEs wird kein einfacher Kampf sein, doch das Schattengewölbe hat Markgraf Dhakar mit ein paar Unterstützungstruppen entsandt. Trefft Euch mit ihm beim höchsten Punkt der Fleischwerke am westlichen Rand. Sagt ihm Bescheid, wenn Ihr angriffsbereit seid, und er wird seine Truppen in die Schlacht schicken.", progress = nil, completion = "Nun da des Lichkönigs Fleischgigant vernichtet ist, muss ihm klar sein, dass auch der Rest seiner Truppen nicht unverwundbar ist. Mit Euch an unserer Seite wird es uns gelingen, den Lichkönig erneut das Fürchten zu lehren.", rewards = "Mantel des FleischriesenSchulterpolster der FleischwerkeSchiftung des RiesenchampionsSchulterstücke von MorbidusIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13236] = {title = "Armee der Verdammten", objective = "Matthias Lehner im Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern auferstehen lasst.", description = "Ihr glaubt wahrscheinlich, Ihr wärt ziemlich stark - wie Ihr so gegen diese Untoten kämpft und ihre Knochen mit Euren Kriegsmaschinen zermalmt.\n\nDas ist jedoch nichts im Vergleich mit der Stärke, der es bedurfte, um sie zu erschaffen.\n\nIch habe gesehen, wie der Prinz selbst es gemacht hat. Ich kann Euch zeigen, wie das geht... wenn Ihr wollt.", progress = nil, completion = "Die wahre Macht des Prinzen lag nicht darin, aus Leichen Armeen zu erschaffen... das war einfach.\n\nAber seine eigenen Männer zu töten, diejenigen, an deren Seite er viele Kämpfe bestritten hat... Die wahre Macht des Prinzen lag darin, das tun zu können, was er tun musste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13237] = {title = "Stechen und Stoßen", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten besiegt.", description = "Verlasst Euch drauf, während Euer Hauptmann von seinem Hass auf die Rivalen Eurer Allianz abgelenkt ist, richte ich meine volle Aufmerksamkeit auf den wahren Feind hier: den Lichkönig und seine Untergebenen.\n\nUm auch nur darauf hoffen zu können, ihn in seiner Zitadelle zu besiegen, müssen Eure Leute beide Tore erobern und halten.\n\nKonzentrieren wir uns für den Augenblick jedoch auf das Erste. Kehrt zur Front zurück und stoßt durch ihre Verteidigungslinie. Sucht nach irgendwelchen Schwachstellen, die wir ausnützen könnten.\n\nIch erwarte Euren Bericht, <Klasse>.", progress = nil, completion = "Wirklich, &lt;Klasse&gt;?\n\nNichts Besonderes zu berichten?\n\n\n\nDa bin ich anderer Meinung...", rewards = "MonstrositätenlederumhangAuf Euch wartet eine dieser Belohnungen:\n\nRing des gefallenen SchattenadeptenAmulett des ruchlosen Totenbeschwörers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13238] = {title = "Zu etwas zu gebrauchen?", objective = "Himmelshäscher Korm Schwarznarbe möchte, dass Ihr mit dem Chefingenieur Kupferklammer an Bord der Orgrims Hammer sprecht.", description = "Goblins! Überdrehte Wichtigtuer...\n\nHört mal, <Name>. Kupferklammer, unser Hausingenieur, besteht darauf, dass er etwas Nützliches gefunden hat, was er mir unbedingt zeigen muss.\n\nIch bin nicht in der Stimmung, mir sein piepsiges Gezeter anzuhören. Das letzte Mal, dass ich ihm Aufmerksamkeit schenkte, hat er glatt eine Stunde lang durchgequäkt. Ich konnte mich gerade noch davon abhalten, ihn mit einem Tritt in Sindragosas Sturz zu befördern!\n\nIhr werdet an meiner Statt gehen und ihm Honig ums Maul schmieren. Lasst es mich wissen, falls er tatsächlich etwas herausgefunden haben sollte.", progress = nil, completion = "Zu beschäftigt? Pühhh! Das Baby hier fliegt sich doch selbst!\n\nVergesst das. Ihr tut's auch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13239] = {title = "Verflüchtigung", objective = "Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt um 3 Frostbrutvollstrecker anzulocken.\n\nUm das Öl benutzen zu können, müsst Ihr auf dem Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und zurückgelassene Rüstung einsammeln.", description = "Wo soll ich anfangen...? Nun, Ihr müsst wissen, dass ich als Chefingenieur dieses Fahrzeugs Zugang zu allen möglichen nachrichtendienstlichen Berichten habe – ja, ja, es ist wahr, und seit Kurzem interessiere ich mich ganz besonders für die Frostwyrms, die Ihr im Süden gesichtet habt. Ich denke, ich habe einen Plan entwickelt, wie ihnen beizukommen sein könnte... Gut, ein paar Kleinigkeiten müssen noch von Euch erledigt werden, aber eigentlich nur Folgendes: Ihr baut eine Attrappe aus Rüstungsteilen und bestreicht sie mit dieser Lösung hier und dann geht Ihr in Deckung!\n\n... Immer noch da, <Volk>?", progress = nil, completion = "Juhuu! Ich hab' von hier aus gesehen, wie sie in Flammen aufgegangen sind! Ich werde das mal als weiteren Erfolg verzeichnen und anfangen, das Zeug für die Invasion abzufüllen - obwohl es natürlich noch einiger weiterer Versuche bedarf, wenn es Euch interessiert...", rewards = "SchmugglerarmschienenMukluks des GletscherläufersGürtel des HimmelskapitänsPlattenarmreif der HimmelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13240] = {title = "Timear prophezeit Zentrifugenkonstrukte in Eurer Zukunft!", objective = "Erzmagier Timear in Dalaran hat vorausgesehen, dass Ihr 10 Zentrifugenkonstrukte zerstören müsst.", description = "Ihr müsst zum Oculus über Kaltarra reisen, <Name>.\n\nIch habe eine Situation vorausgesehen, in der Ihr die dortigen Zentrifugenkonstrukte zerstören müsst. Ich kann Euch versichern, dass, solltet Ihr nicht zuerst diese magischen Schöpfungen beseitigen, Eure Gruppe versagen wird.\n\nDies habe ich gesehen und dies müsst Ihr tun.", progress = nil, completion = "&lt;Der Erzmagier nickt, bevor Ihr überhaupt etwas gesagt habt.&gt;\n\nIch weiß. Ihr habt die Konstrukte, wie ich vorhergesehen habe, zerstört und konntet dann dazu überschreiten, gegen Varos Wolkenwanderer zu kämpfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBelobigungsabzeichen der Kirin TorBelobigungsabzeichen des ArgentumkreuzzugsBelobigungsabzeichen der Schwarzen KlingeBelobigungsabzeichen des WyrmruhpaktsBelobigungsabzeichen der Söhne von Hodir\n\nIhr bekommt außerdem:\n\nGerechtigkeitspunkteEmblem des HeldentumsEmblem der EhreEmblem der Eroberung"}
MultiLanguageQuestData['de'][13241] = {title = "Timear prophezeit Berserker der Ymirjar in Eurer Zukunft!", objective = "Erzmagier Timear in Dalaran möchte, dass Ihr 7 Berserker der Ymirjar tötet.", description = "In nicht allzu ferner Zukunft werden zwischen Euch und dem Sieg lediglich König Ymirons Champions stehen.\n\nIhr werdet zur Festung namens Turm Utgarde tief in den Wäldern des Heulenden Fjords reisen. Ich kann nicht genug betonen, wie wichtig es ist, dass Ihr und Eure Reisegefährten Euch um die dortigen Berserker der Ymirjar kümmert.\n\nSolltet Ihr dies versäumen, ist es gut möglich, dass es Euch zum Verhängnis werden wird, <Name>!", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.\n\nHättet Ihr dies nicht getan, hättet Ihr im Kampf mit dem König sicherlich gegen unzählige der überlebenden Berserker kämpfen müssen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBelobigungsabzeichen der Kirin TorBelobigungsabzeichen des ArgentumkreuzzugsBelobigungsabzeichen der Schwarzen KlingeBelobigungsabzeichen des WyrmruhpaktsBelobigungsabzeichen der Söhne von Hodir\n\nIhr bekommt außerdem:\n\nGerechtigkeitspunkteEmblem des HeldentumsEmblem der EhreEmblem der Eroberung"}
MultiLanguageQuestData['de'][13242] = {title = "Die Dunkelheit regt sich", objective = "Geht aufs Schlachtfeld hinaus, sucht nach Saurfangs Schlachtrüstung und bringt sie zu Hochfürst Saurfang in der Kriegshymnenfestung in der Boreanischen Tundra.", description = "Die Dunkelheit regt sich, <Name>. Etwas Tragisches hat sich ereignet, das niemand außer der Zeitlose selbst voraussehen hätte können. Bald wird Euer Volk von Wut und Hass erfasst werden. Krieg ist am Horizont.\n\nDer rote Drachenschwarm hat alles getan, was in seiner Macht steht. Was als Nächstes passiert, liegt in den Händen der sterblichen Völker Azeroths.\n\nLeider beginnt Eure Reise mit Schmerz. Ein Vater hat heute ein Kind verloren und Ihr müsst die schlimme Nachricht überbringen. Sammelt Saurfangs Rüstung ein und bringt sie zum Ältesten Saurfang zurück.", progress = "<Saurfangs Miene verzieht sich.>\n\nMein Herz... meine Stärke...", completion = "&lt;Saurfang blickt gen Himmel.&gt;\n\nWie auch Brox, so starb auch mein Sohn als Held. Trauert nicht über ihn, &lt;Name&gt;. Für einen Orc gibt es kein besseres Ende! Keine größere Ehre! In diesem Moment schwillt mein Herz vor Stolz.\n\nIch danke Euch dafür, dass Ihr unsere Schlachtrüstung zurückgebracht habt. Sie wird auf seinen Scheiterhaufen auf dem Ahnengrund in Nagrand gelegt werden.\n\nWir müssen unsere volle Aufmerksamkeit dringlicheren Angelegenheiten zuwenden.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13243] = {title = "Timear prophezeit Ewige Agenten in Eurer Zukunft!", objective = "Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 4 ewige Agenten töten müsst.", description = "Die Zeitlinie wird vom ewigen Drachenschwarm bedroht. Ohne Euer Eingreifen wird die Zeit zunichtegemacht werden!\n\nIhr müsst in die Höhlen der Zeit gehen und zu einem Zeitpunkt zurückreisen, an dem ein Ereignis namens 'das Ausmerzen von Stratholme' stattfand.\n\nMir bereitet es Kopfschmerzen, auch nur zu versuchen, in alle möglichen Vergangenheiten zu blicken, doch ich weiß, dass es äußerst wichtig für Euch ist, die ewigen Agenten zu töten.\n\nNur durch ihren Tod wird die wahre Vergangenheit beibehalten und Gegenwart und Zukunft werden davor bewahrt, für immer ungeschehen gemacht zu werden!", progress = nil, completion = "Für den Augenblick sind wir gerettet. Habt Dank.\n\nUnglücklicherweise bieten sich den Ewigen aufgrund der Art und Weise ihres Eingreifens beinahe endlos viele Möglichkeiten, dies wieder zu tun.\n\nWas ich erkennen kann, ist, dass in Zukunft Ihr im Herzen des Kampfes gegen sie stehen werdet, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBelobigungsabzeichen der Kirin TorBelobigungsabzeichen des ArgentumkreuzzugsBelobigungsabzeichen der Schwarzen KlingeBelobigungsabzeichen des WyrmruhpaktsBelobigungsabzeichen der Söhne von Hodir\n\nIhr bekommt außerdem:\n\nGerechtigkeitspunkteEmblem des HeldentumsEmblem der EhreEmblem der Eroberung"}
MultiLanguageQuestData['de'][13244] = {title = "Timear prophezeit Titanvorposten in Eurer Zukunft!", objective = "Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 7 Titanvorposten töten müsst.", description = "Ganz Azeroth ist in Gefahr. Der verrückte Gott Loken besitzt die Macht, allem ein Ende zu bereiten!\n\nIm Irdischen Wachturm in den Hallen der Blitze stehen Titanvorposten kurz davor, Lokens schrecklichen Willen auszuführen - dem würden unzählige Ahnungslose zum Opfer fallen.\n\nIch habe in die Zukunft geblickt, <Name>. Ihr seid <derjenige, der/diejenige> die; sich darum kümmern wird, dass dies nicht geschieht!", progress = nil, completion = "Wir stehen alle in Eurer Schuld, &lt;Name&gt;.\n\nWenn ich mir über irgendetwas sicher bin, dann ist es das, dass Ihr uns in der Vergangenheit nicht enttäuscht habt und dies auch in Zukunft nicht tun werdet!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBelobigungsabzeichen der Kirin TorBelobigungsabzeichen des ArgentumkreuzzugsBelobigungsabzeichen der Schwarzen KlingeBelobigungsabzeichen des WyrmruhpaktsBelobigungsabzeichen der Söhne von Hodir\n\nIhr bekommt außerdem:\n\nGerechtigkeitspunkteEmblem des HeldentumsEmblem der EhreEmblem der Eroberung"}
MultiLanguageQuestData['de'][13245] = {title = "Todesbeweis: Ingvar der Brandschatzer", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der Axt des Brandschatzers zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Ihr müsst eine Gruppe zusammenstellen und sie nach Burg Utgarde führen. Dort sollt Ihr dann nach Ingvar dem Brandschatzer suchen und ihn töten, bevor er mit seinen Vrykultruppen die nahegelegenen Städten der Allianz und Horde überfallen und plündern kann.\n\nIch brauche seine Axt als Beweis dafür, dass man sich um ihn gekümmert hat. Es wäre ja nicht so, dass ich Euch nicht vertrauen würde. Doch es ist einfach nur klug, sich absolut sicher zu sein, ob die Aufgabe nun erledigt wurde.", progress = "Habt Ihr die Axt? Ist Ingvar tot?", completion = "Sehr gut. Legt die Axt einfach bei der Wand dort drüben ab.\n\nIch bin mir sicher, dass man in Valgarde und im Hafen der Vergeltung heute Abend etwas ruhiger ist, nun, da Ihr Euch um den Barbaren gekümmert habt.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13246] = {title = "Todesbeweis: Keristrasza", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit Keristraszas gebrochenem Herzen zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Seid Ihr mit der Geschichte von Keristrasza vertraut?\n\nDamit, dass sie maßgeblich daran beteiligt war, Saragosa, Malygos' Gefährtin, zu töten? Wie er wiederum Keristrasza zur Gemahlin nahm und sie in einen Block aus Eis einschloss?\n\nWir wissen nun, dass Malygos seine Magie dazu benutzt hat, um ihren Willen zu brechen, was sie in den Wahnsinn getrieben hat.\n\n<Name>, Ihr müsst in den Nexus nach Kaltarra gehen und ihr ein Ende bereiten, bevor sie komplett überläuft.\n\nZwar macht es mich traurig, doch ich muss darauf bestehen, dass Ihr mir ihr Herz als Beweis bringt.", progress = "Wenn wir einen Weg gewusst hätten, wie wir sie erlösen können, hätten wir Euch nicht darum gebeten, ihrem Leben ein Ende zu bereiten.\n\nWir wissen jedoch, wie mächtig Malygos' Beherrschung der magischen Kräfte geworden ist. Seiner Beeinflussung der Leylinen Azeroths ist es zu verdanken, dass ihm heute niemand gleich kommt, wenn es um das Arkane geht.", completion = "Bedauerlich, doch äußerst notwendig.\n\nDie Kirin Tor könnten es sich nicht leisten, einen der wichtigsten roten Großdrachen an unseren größten Feind zu verlieren. Hätte Malygos sie im Nexuskrieg gegen uns eingesetzt, wäre dies verheerend gewesen.\n\nIch bedauere es einfach, dass wir sie stattdessen nicht haben retten können.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13247] = {title = "Todesbeweis: Leywächter Eregos", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit einem Leylinienempfänger zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Der Nexuskrieg tobt weiter und wir müssen etwas unternehmen, um das Blatt zu wenden! Seid Ihr willens, ins Herz der Schlacht zu fliegen, <Name>?\n\nLeywächter Eregos ist der Beschützer des Kanals, durch den Malygos die magische Energie von Azeroths Leylinien schleust. Würde er getötet, wäre dies ein großer Rückschlag für den Feind.\n\nBitte bringt mir einen seiner Leylinienempfänger, damit wir ihn untersuchen können.", progress = "Habt Ihr Euch um den Leywächter gekümmert, <Klasse>?\n\nIch muss Euch nicht daran erinnern, dass Malygos versucht, jeglichen Gebrauch von Magie auf der Welt zu unterbinden, und dass der blaue Drachenschwarm jeden tötet, der mit ihr umgehen kann und nicht auf ihrer Seite ist.", completion = "Habt Dank, &lt;Name&gt;. Die Untersuchung dieses Empfängers sollte uns weitere Einblicke darüber verschaffen, wie Malygos die Leylinien manipuliert.\n\nWenn wir eine Schwachstelle in seinem Ansatz finden können, wären wir vielleicht in der Lage, sie auszunutzen und das Blatt zu wenden.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13248] = {title = "Todesbeweis: König Ymiron", objective = "Erzmagier Lan'dalok in Dalaran möchte, dass Ihr mit dem Medaillon der verstorbenen Königin zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "König Ymiron im Turm Utgarde ist der Lieblingsvrykul des Lichkönigs. Das alleine ist Grund genug, ihm ein Ende zu bereiten.\n\nDoch sollte er die Hörner erschallen lassen und alle Anführer der Ymirjar sowie der Mjordin zu sich rufen, würden die Vrykul zu einer Macht heranwachsen, die stärker als jede andere Gruppe innerhalb der Geißel wäre!\n\nEs liegt an Euch, <Name>, dafür zu sorgen, dass dies nicht geschieht. Bringt mir das Medaillon, das er um seinen Hals trägt, damit ich weiß, dass Ymiron keine Gefahr mehr darstellt.", progress = "Ymiron darf das Reich der Vrykul nicht vereinen. Sollte er triumphierend nach Eiskrone zurückkehren, wird sehr wahrscheinlich alles verloren sein.", completion = "&lt;Der Erzmagier nickt ernst, als Ihr ihm das etwas große geratene Schmuckstück überreicht.&gt;\n\nWas getan ist, ist getan. Welch edles Volk, diese Vrykul. Schade nur, dass der Lichkönig seine tödlichen Haken in sie hineingetrieben hat.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13249] = {title = "Todesbeweis: Der Prophet Tharon'ja", objective = "Erzmagier Lan'dalok in Dalaran möchte, dass Ihr mit dem verzauberten Tiki des Propheten zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Einst war die Feste Drak'Tharon eine stolze Bastion des Drakkarireiches. Nun ist sie nichts weiter als ein Sprungbrett für den Lichkönig in seinem Kampf, Zul'Drak ein Ende zu bereiten und die Kräfte der Trollgötter an sich zu reißen.\n\nDoch sollten wir ihren Anführer Prophet Tharon'ja ausschalten, könnten wir vielleicht den Zustrom weiterer Trolle der Geißel verhindern. Das Mindeste, was dabei herauskommen könnte, wäre, dass der Argentumkreuzzug in Zul'Drak eine Sorge weniger hat.\n\nBringt mir sein Tiki, damit ich weiß, dass der Prophet tot ist.", progress = "Habt Ihr Euch dem Propheten schon gestellt? Habt Ihr das Tiki bei Euch?", completion = "Mit etwas Glück wird die Feste Drak'Tharon jetzt, da sie ohne Anführer ist, ein kleineres Problem für diejenigen darstellen, die in dieser Region gegen die Geißel kämpfen.\n\n&lt;Der Erzmagier blickt auf das Tiki in Eurer Hand.&gt;\n\nAuch ist es gut, dass das Tiki sein Mojo verloren hat. Ich hätte keine Vorstellung davon gehabt, wie man es benutzt, geschweige denn, ob es das Richtige wäre, dergleichen zu tun.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13250] = {title = "Todesbeweis: Gal'darah", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit den Überresten von Akalis Mojo zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Die Drakkaripropheten von Zul'Drak haben das undenkbare getan: Sie haben die meisten ihrer Götter getötet und ihre Kraft in sich aufgenommen! Der gefährlichste von allen ist Akalis Hochprophet Gal'darah.\n\nGal'darah hält sich in den Tiefen von Gundrak verborgen und hat fast das gesamte Mojo des toten Akali in sich aufgesaugt. Nun ist er kurz davor, mit seinen Anhängern aus der Stadt auszubrechen. Wenn wir ihn jetzt nicht töten, werden wir in einem Meer des Wahnsinns ertrinken und von unvorstellbarer Macht erdrückt!\n\nBeeilt Euch, <Name>, bringt mir, was von Akalis Mojo übrig geblieben ist.", progress = "Habt Ihr das Mojo dabei?\n\nEs macht mich krank, mit ansehen zu müssen, wie ein weiteres großes Trollreich zugrunde geht.\n\nIch kann mir nur denken, dass, hätte sich der Lichkönig nicht eingemischt, die Trolle sich nicht dazu gezwungen gesehen hätten, sich gegen ihre eigenen Götter zu wenden und ihre Kraft zu stehlen, um sie als Verteidigung gegen die Geißel einzusetzen.", completion = "Habt Dank, &lt;Name&gt;. Ich werde mich darum kümmern, dass die Essenz der Götter so lange sicher aufbewahrt wird, bis sie an den Stamm der Zandalari übergeben werden kann.\n\nVielleicht werden sie in der Lage sein, einen Weg zu finden, Akali mit dieser Essenz wieder ins Leben zu rufen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13251] = {title = "Todesbeweis: Mal'Ganis", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem Artefakt aus der Heimatwelt der Nathrezim zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "<Name>, ein Freund innerhalb des bronzenen Drachenschwarms hat mir Informationen zukommen lassen, die wir ausnützen müssen.\n\nDie mysteriösen Geschöpfe der Brennenden Legion namens Schreckenslords werden in Hinblick auf ihre Rasse auch als die Nathrezim bezeichnet. Wenig ist über ihre Heimatwelt bekannt, und selbst das ist nur ein Gerücht.\n\nEs ist jedoch bekannt, dass Mal'Ganis in der Vergangenheit einen entscheidenden Fehler gemacht hat: er hinterließ ein Artefakt seiner Heimatwelt!\n\nÜber die Höhlen der Zeit müsst Ihr in der Zeit zurückreisen und einem Ereignis beiwohnen, das auch 'das Ausmerzen von Stratholme' genannt wird. Beschafft das Artefakt.", progress = "Wir müssen Mal'ganis' Fehler ausnutzen. Es kommt nicht jeden Tag vor, dass sich uns solch eine Chance bietet.\n\nWenn wir dieses Artefakt untersuchen können, könnten wir die Nathrezim vielleicht besser verstehen!", completion = "Erstaunlich! Ich habe noch nie etwas ähnliches gesehen. Ich werde mich darum kümmern, dass es den richtigen Händen in der Violetten Zitadelle übergeben wird.\n\nWenn man Euch nur erlaubt hätte, den Lauf der Geschichte zu ändern. Wenn man Arthas vielleicht davon abgehalten hätte... nein, so etwas führt nur ins Chaos.\n\nDie Hüter der Zeit kennen sich mit solchen Angelegenheiten am besten aus.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13252] = {title = "Todesbeweis: Sjonnir der Eisenformer", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der 'Datenscheibe: Fluch des Fleisches' zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Nur wenig ist über das Leiden bekannt, welches 'Fluch des Fleisches' genannt wird. In den Hallen des Steins gibt es jedoch Informationen zu holen.\n\nSjonnir der Eisenformer scheint sich ziemlich gut mit dem Fluch auszukennen. Wir wissen aus guter Quelle, dass er eine titanische Informationsscheibe bei sich hat, die all unsere Fragen beantworten könnte.\n\nBesorgt mir diese Scheibe, <Name>, damit wir mehr erfahren können.", progress = "Habt Ihr die Scheibe?", completion = "Ist sie nicht erstaunlich, die Titanentechnologie? Die Informationen befinden sich in der Scheibe selbst!\n\nIch hoffe nur, wir können herausfinden, wie wir sie aus der Scheibe herausbekommen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13253] = {title = "Todesbeweis: Loken", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem himmlischen Rubinring zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Loken im Inneren der Hallen der Blitze steht kurz davor, unserer Welt ein Ende zu bereiten. Muss ich noch mehr sagen, <Name>?\n\nEr sitzt dort und lauscht dem verrückten Geflüster des Alten Gottes, der unter Nordend gefangen ist. Ihr müsst umgehend mit einer Gruppe zu den Sturmgipfeln reisen!\n\nGeht zum Irdischen Wachturm und stellt Euch Loken zum Kampf. Haltet ihn auf, bevor es zu spät ist! Bringt mir seinen Rubinring, damit ich weiß, dass wir wieder sicher sind.", progress = "Wir sprechen wieder miteinander, <Name>. Bedeutet das, dass wir vor Lokens Wahnsinn sicher sind? Oder sind wir dem Untergang geweiht.", completion = "&lt;Erzmagier Lan'dalock seufzt vor Erleichterung.&gt;\n\nUm ehrlich zu sein, hatte ich befürchtet, dass Euch das Schlimmste zugestoßen wäre. Es ist schwierig, untätig herumzustehen, während andere wie Ihr sich mit Angelegenheiten auseinandersetzen, bei denen es um Leben und Tod geht und die unsere Welt anscheinend tagtäglich beschäftigen.\n\nWas werden wir mit diesem gigantischen Ring jetzt bloß nur anfangen?", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13254] = {title = "Todesbeweis: Anub'arak", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der unnützen Krone Anub'araks zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Die Neruber der Geißel sind eine Plage für unsere Truppen.\n\nHier, über der Welt schwebend, sind wir zwar vor ihnen sicher, doch setzt man seinen Fuß auf das Land unter uns, hat man ständig den Gedanken im Hinterkopf, dass die untoten Neruber aus den Tiefen Azjol-Nerubs jeden Augenblick aus der Erde springen und angreifen könnten.\n\nEs liegt im besten Interesse von uns allen, wenn sie ins Chaos gestürzt werden. Tötet ihren früheren König, den Majordomus des Lichkönigs, den Gruftlord Anub'arak.\n\nBitte bringt mir seine Krone... es wäre ja nicht so, dass er sie noch trägt.", progress = "Ich bin froh, dass Ihr es seid, der nach Azjol-Nerub hinabsteigt, nicht ich.\n\nIch bin nicht gerne unter der Erde.", completion = "Welchen Schrecken Ihr begegnet sein müsst, als Ihr die Oberstadt durchquert habt.\n\n&lt;Lan'dalock wirft einen Blick auf die stumpfe Krone in Eurer Hand.&gt;\n\nVielleicht sollten wir das für den Zeitpunkt beiseite legen, wenn sich die Neruber dazu entschließen, einen neuen König zu krönen?", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13255] = {title = "Todesbeweis: Herold Volazj", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem siechenden Gehirn des Gesichtslosen zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Die Neruber von Ahn'kahet gruben zu tief, als sie versuchten, dem Überfall der Geißel zu entkommen. Sie kamen dem alten Gott in den Tiefen Nordends zu nah.\n\nDer Alte Gott, von ihnen wach gerufen, hetzte seine wild gewordenen Kreaturen auf sie - die Neruber saßen also sprichwörtlich in der Klemme.\n\nHerold Volazj, der Anführer der Streitkräfte des alten Gottes, ist eines der alptraumhaften Wesen, die auch die Gesichtslosen genannt werden. Beseitigt ihn und bringt mir sein verdorrtes Gehirn.\n\nNur bitte ich Euch, dass Ihr versucht, bei Verstand zu bleiben.", progress = "<Name>? Seid Ihr noch bei Verstand?", completion = "&lt;Der Erzmagier beäugt das Gehirn misstrauisch.&gt;\n\nWo ich gerade daran denke: Ich bin mir nicht so ganz sicher, ob man sich ohne Gefahr so nah an diesem Ding aufhalten kann. Ihr meint also, dass es noch immer am Leben ist?\n\n&lt;Er schüttelt seinen Kopf.&gt;\n\nWir haben einen Platz für solche Dinge hier in der Zitadelle. Ich werde mich darum kümmern, dass einer meiner Lehrlinge es umgehend dorthin bringt.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13256] = {title = "Todesbeweis: Cyanigosa", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit Cyanigosas Kopf zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", description = "Wir werden überfallen! Der blaue Drachenschwarm hat sich in die Violette Festung teleportiert und sie planen, von dort auszubrechen und sich im Rest von Dalaran zu verbreiten!\n\nEs gab schon Berichte von Gefangenen, die dadurch versehentlich befreit wurden. Es würde mich nicht wundern, wenn sie einige von ihnen absichtlich freilassen würden.\n\n<Name>, könnt Ihr schnell ein Team zusammenstellen und Euch dorthin begeben? Cyanigosa ist die Anführerin der Invasionstruppen. Bringt mir ihren Kopf!", progress = "Wenn ich so darüber nachdenke: Weshalb würde sich jemand in ein Gefängnis hineinteleportieren, nur um dann wieder auszubrechen? Es handelt sich hier ja nur um den sichersten Ort in der ganzen Stadt.\n\nDie Blauen müssen wirklich verrückt geworden sein!", completion = "Die Gefahr ist vorüber und der Rest der Gefangenen, die ausgebrochen sind, sitzen einmal mehr im Gefängnis.\n\nDalaran schuldet Euch Dank, &lt;Name&gt;!\n\nNun muss ich mit jemanden darüber sprechen, wieso es so einfach gewesen ist, den Teleportationsschutz des Gefängnisses zu umgehen?!", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem der EhreEmblem der EroberungEmblem des Triumphs"}
MultiLanguageQuestData['de'][13257] = {title = "Vorbote des Krieges", objective = "Meldet Euch bei Thrall in der Feste Grommash in Orgrimmar.", description = "Champion, der Kriegshäuptling braucht Euch. Über Orgrimmar ist das Kriegsrecht verhängt worden. Alle Handels- und Dienstleistungsaktivitäten wurden eingestellt, während sich der Kriegshäuptling auf einen unvermeidlichen Konflikt vorbereitet.\n\nMehr kann ich Euch nicht sagen - nicht jetzt, nicht hier.\n\nDer Kriegshäuptling befiehlt, dass sich die stärksten Champions in seinem Thronsaal melden. Geht jetzt, <Name>! Nehmt das Portal zurück nach Orgrimmar und sucht Thrall auf.", progress = nil, completion = "Dämonenfürst Varimathras und Chefapotheker Putress sind für diesen Verrat verantwortlich.\n\n&lt;Thrall nickt.&gt;\n\nDerselbe Putress, der auch das Heilmittel gegen die letzte Seuche der Geißel gefunden hat.\n\nDiejenigen, die sich ihrem Regime nicht anschließen wollten, sind hingerichtet oder verbannt worden. Sylvanas wurde bei dem Staatsstreich beinahe getötet.\n\nFür die Horde ist die Unterstadt verloren. Orgrimmar wird die Flüchtlinge der Verlassenen aufnehmen, bis diese Krise überwunden ist. Fürs erste stehen wir unter Kriegsrecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13258] = {title = "Gelegenheit", objective = "Sprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle.", description = "Wir sind kürzlich über Schemata gestolpert, die auf eine Schwachstelle in der Eiskronenzitadelle hinweisen - eine offene Stelle in ihrer Verteidigung, bildlich und wörtlich genommen.\n\nDie Pläne, die gefunden wurden, zeigen eine Öffnung, die mehrere hundert Meter in den Boden geht. Wir sind uns nicht sicher, welchem Zweck sie dient, doch unseren Aufklärungsberichten zufolge ist sie für die Geißel äußerst wichtig.\n\nSprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle. Sie leitet den dortigen Angriff.", progress = nil, completion = "Gerade rechtzeitig, &lt;Name&gt;. Koltira hatte gute Worte für Euch übrig. Vielleicht werdet Ihr in der Lage sein, die Situation zu unseren Gunsten zu ändern.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13259] = {title = "Für Überlegenheit sorgen", objective = "Unteroffizier Kregga an der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.", description = "Wir haben eine einzige Chance, dieser Zitadelle ein wenig Schaden zuzufügen - sorgen wir also dafür, dass wir's richtig machen.\n\nWir sind in den Besitz von schweren Saronitbomben gelangt, die von der Geißel hergestellt wurden. Doch bevor wir sie loslassen können, müssen wir erst die Gegend sichern.\n\nWir werden die Verteidigungsstellungen der Geißel schnell unter Kontrolle bringen müssen, bevor ihre Verstärkung eintrifft.\n\nSteht meinen Männern zur Seite und kommt wieder zurück, wenn Ihr bereit für ein kleines Feuerwerk seid.", progress = nil, completion = "Ihr habt kurzen Prozess mit der Geißel gemacht, &lt;Name&gt;. Lasst uns zu Ende bringen, weswegen wir hier sind.", rewards = "Stoßfester KopfschutzTunika des bulligen SchreckensHandschuhe des verrückten BombersKrallenschuhe der EiswandlerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13260] = {title = "Der Insider", objective = "Himmelshäscher Korm wünscht, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", description = "Obwohl wir keine Gelegenheit auslassen sollten, der Allianz einen Schlag zu versetzen, dürfen wir auf gar keinen Fall die Geißel vergessen.\n\nWir haben zwar nicht genug Männer, um in den nächsten Wochen einen vernünftigen Ausfall in den Gletscher zu wagen, doch sollte uns das nicht davon abhalten, so viel wie möglich über ihre Verteidigung in Erfahrung zu bringen.\n\nIch habe unseren Todesritter gebeten, Euch in dieser Sache zu beraten. Schließlich kennt niemand den Feind besser als sie.\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", progress = nil, completion = "&lt;Koltira mustert Euch.&gt;\n\nIch hoffe für Euch, dass Ihr dem gewachsen seid, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13261] = {title = "Verflüchtigung", objective = "Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt, um 3 Frostbrutvollstrecker anzulocken.\n\nUm das Öl benutzen zu können, müsst Ihr auf dem dortigen Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und eine zurückgelassene Rüstung einsammeln.", description = "Wahuu! Es funktioniert! Nicht dass ich irgendwelche Zweifel an meiner übernatürlichen Genialität gehabt hätte... Ich war nur nicht ganz sicher, was für eine Art von Explosion kommen würde... Lasst uns einfach sagen, dass ich froh bin, dass Ihr Euch nicht die Augenbrauen abgefackelt habt... So, nun muss ich dem alten Korm nur zeigen, wie man die Wyrms auftaut. Dann muss er mich befördern zum... zum... zu was-auch-immer nach Chefingenieur kommt! Hier, nehmt noch eine Portion von dem Zeug und kehrt an die Front zurück, ich werde mit Korm reden...\n\nNa? Bewegt Euch!", progress = nil, completion = "Nichtsnutz!\n\nKorm sagte bloß, er sei zu beschäftigt, und als ich ihn endlich dazu gekriegt hab', nach oben zu kommen und es sich anzusehen, hattet Ihr auch schon alles Öl aufgebraucht. Jetzt ist er verärgert und will mich bis morgen nicht einmal mehr in seiner Nähe haben...\n\nKommt dann wieder und wir versuchen es nochmal!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13262] = {title = "Jagt es hoch!", objective = "Geht zu dem nahen Saronitbombenstapel und zündet die Lunte an.", description = "Besser werden wir die Sache hier wohl nicht unter Kontrolle bekommen. Legen wir los, <Name>.\n\nIch brauche jemanden, der die Lunten an diesen Bomben anzündet, und es sieht so aus, als wärt Ihr derjenige.", progress = nil, completion = "Diese Bomben sehen ziemlich durchschlagskräftig aus. Sie sollten zumindest für eine ordentliche Delle in der umgebenden Struktur sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13263] = {title = "Eine kurze Lunte", objective = "Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.", description = "Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.\n\nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.", progress = nil, completion = "Dieses pulsierende Objekt ist von einer dicken Eisschicht umgeben. Es schimmert geheimnisvoll unter Wasser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13264] = {title = "Das ist monströs!", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", description = "Monstrositäten...\n\nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.\n\nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.\n\nZu Eurem Glück kenne ich diese Geheimnisse.\n\nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.", progress = nil, completion = "Seht Ihr, &lt;Klasse&gt;?\n\nRaffinesse kann mitunter selbst in aussichtslos scheinenden Situationen für Chancengleichheit sorgen.", rewards = "Slipper der durchbrochenen FrontMantel der WiedererweckungGamaschen des SpukjägersSchulterstücke des GeißelbannsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13265] = {title = "Das Plündern von Stoffen", objective = "Dem Schnitt Eurer Kleider nach zu urteilen nehme ich an, dass Ihr selbst ein Schneider seid und somit leicht erlernen könnt, was ich beizubringen habe.\n\nViele der Humanoiden des Nordens tragen Kleider, die recht schnell in Stoff umgewandelt werden können, wenn man den Dreh raus hat.\n\nGegen eine kleine Gebühr kann ich Euch beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", description = nil, progress = "Dem Schnitt Eurer Kleider nach zu urteilen nehme ich an, dass Ihr selbst ein Schneider seid und somit leicht erlernen könnt, was ich beizubringen habe.\n\nViele der Humanoiden des Nordens tragen Kleider, die recht schnell in Stoff umgewandelt werden können, wenn man den Dreh raus hat.\n\nGegen eine kleine Gebühr kann ich Euch beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", completion = "Ihr findet extra Stoff? Macht aus ihm etwas Wunderschönes!", rewards = "Ihr erlernt:\n\nPlündern nordischer Stoffe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPlündern nordischer Stoffe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13266] = {title = "Ein Leben ohne Reue", objective = "Nehmt das Portal nach Unterstadt, das sich in der Feste Grommash befindet, und meldet Euch bei Vol'jin.", description = "Am Tage meines Todes möchte ich sagen können, dass ich ein Leben ohne Reue geführt habe. Diejenigen, die mein Dahinscheiden betrauern, werden wissen, dass ich ein Kriegshäuptling war, der die besten Entscheidungen für sein Volk getroffen hat.\n\nDoch Varimathras' und Putress' Verrat... Alles, wofür wir gearbeitet haben, ist umsonst gewesen.\n\n<Thrall gibt einen langen Seufzer von sich.>\n\nPortale nach Unterstadt werden vorübergehend aktiv sein. Vol'jin wird auf Euch warten. Ich werde Euch schon bald dort antreffen. Gemeinsam werden wir die Sache wieder bereinigen, <Name>.", progress = nil, completion = "Lasst mich Euch auf den neuesten Stand bringen, &lt;Name&gt;.\n\nUnterstadt ist eine Kriegszone. Putress' Apotheker und Varimathras' Dämonen haben die Kontrolle übernommen. Sie haben sich drinnen verschanzt und setzen diese verdammte Seuche gegen unsere Truppen ein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13267] = {title = "Die Schlacht um Unterstadt", objective = "Unterstützt Thrall und Sylvanas, Unterstadt für die Horde zurückzuerobern.\n\nMeldet Euch bei Thrall, solltet Ihr erfolgreich sein.", description = "Ganz Unterstadt steht unter Varimathras' Kontrolle. Unsere Soldaten stehen bereit und warten auf den Angriffsbefehl des Kriegshäuptlings.\n\nHelft der Horde, Unterstadt zurückzuerobern, und verdient Euch einen Platz unter unseren größten Champions! Erstattet Thrall Bericht, falls Ihr den Angriff überleben solltet.\n\nMeldet Euch beim Kriegshäuptling, sobald Ihr bereit seid loszulegen.", progress = nil, completion = "Die Zukunft ist unsicher. Die Tage, an denen Horde und Allianz Seite an Seite gegen einen gemeinsamen Feind kämpften, sind gezählt. Dies ist der Beginn einer neuen Schlacht, &lt;Name&gt; - eine Schlacht, in der es keinen Gewinner geben kann.\n\nDoch wir müssen unseren Marsch auf Eiskrone weiterführen. In dieser Hinsicht bleibt uns keine andere Wahl. Unsere Erlösung liegt in Helden wie Ihr es seid, &lt;Name&gt;. Die Zukunft der Horde - die Zukunft der Welt - liegt in Euren Händen.\n\nKehren wir nach Orgrimmar zurück. Ihr müsst umgehend wieder nach Nordend reisen.", rewards = "Weisheitsgamaschen des KriegshäuptlingsHeldentumbeinschützer des KriegshäuptlingsEhrengamaschen des KriegshäuptlingsBlutbadbeinplatten des KriegshäuptlingsBrutalitätsbeinschützer des KriegshäuptlingsVoraussichtsgamaschen des KriegshäuptlingsDer folgende Zauber wird auf euch gewirkt:\n\nRückkehr nach Orgrimmar\n\nIhr bekommt:\n\nMedaillon des Heldentums"}
MultiLanguageQuestData['de'][13268] = {title = "Das Plündern von Stoffen", objective = "Ihr seht wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht - vielleicht kann ich Euch dann helfen.\n\nDie Humanoiden des Nordens tragen Kleider, die, wenn man weiß wie, recht schnell in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", description = nil, progress = "Ihr seht wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht - vielleicht kann ich Euch dann helfen.\n\nDie Humanoiden des Nordens tragen Kleider, die, wenn man weiß wie, recht schnell in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", completion = "Kommt wieder zurück, wenn Ihr über ausreichend Können verfügt. Ich kann Euch alles beibringen, was ein Schneider nur lernen kann.", rewards = "Ihr erlernt:\n\nPlündern nordischer Stoffe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPlündern nordischer Stoffe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13269] = {title = "Das Plündern von Stoffen", objective = "Die Humanoiden der Nordlande tragen Kleidungsstücke, die, wenn man weiß wie, in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten Humanoiden in Nordend zusätzlichen Froststoff erhalten.", description = nil, progress = "Die Humanoiden der Nordlande tragen Kleidungsstücke, die, wenn man weiß wie, in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten Humanoiden in Nordend zusätzlichen Froststoff erhalten.", completion = "Möget Ihr viele humanoide Wesen töten und ihren Stoff nehmen.", rewards = "Ihr erlernt:\n\nPlündern nordischer Stoffe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPlündern nordischer Stoffe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13270] = {title = "Das Plündern von Stoffen", objective = "Du siehst wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht, also habe ich da was für dich.\n\nDie Humanoiden vom Norden tragen Sachen, die in Stoff umgewandelt werden können, wenn man nur weiß wie.\n\nWenn du ein bisschen Geld locker machen willst, dann kann ich dir beibringen, wie man Stoffe plündert. Dadurch wirst du von den Humanoiden aus Nordend noch mehr Froststoff bekommen.", description = nil, progress = "Du siehst wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht, also habe ich da was für dich.\n\nDie Humanoiden vom Norden tragen Sachen, die in Stoff umgewandelt werden können, wenn man nur weiß wie.\n\nWenn du ein bisschen Geld locker machen willst, dann kann ich dir beibringen, wie man Stoffe plündert. Dadurch wirst du von den Humanoiden aus Nordend noch mehr Froststoff bekommen.", completion = "Gut, mit dir Geschäfte zu machen.", rewards = "Ihr erlernt:\n\nPlündern nordischer Stoffe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPlündern nordischer Stoffe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13271] = {title = "Eine Stimme im Dunklen", objective = "Untersucht die nahe Stimme in Naz'anak, den Vergessenen Tiefen.", description = "Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.\n\nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.\n\nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.\n\n\"Das hättet Ihr nicht tun sollen.\"", progress = nil, completion = "Ich sah, wie er es weggeworfen hat, wisst Ihr? Er hat es ganz bis hier herunter geworfen.\n\nSagte, er bräuchte es nicht mehr. Sagte, es würde ihn schwach machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13272] = {title = "Das Plündern von Stoffen", objective = "Als Schneider meine ich, dass Ihr bereit seid, das zu lernen, was ich beizubringen habe.\n\nViele der humanoiden Wesen des Nordens tragen Kleidung, die sich mit dem geeigneten Wissen schnell in Stoff umwandeln lässt.\n\nFür ein paar Goldstücke kann ich Euch beibringen, wie man Stoffe plündert, um den Humanoiden aus Nordend zusätzlichen Stoff abzugewinnen.", description = nil, progress = "Als Schneider meine ich, dass Ihr bereit seid, das zu lernen, was ich beizubringen habe.\n\nViele der humanoiden Wesen des Nordens tragen Kleidung, die sich mit dem geeigneten Wissen schnell in Stoff umwandeln lässt.\n\nFür ein paar Goldstücke kann ich Euch beibringen, wie man Stoffe plündert, um den Humanoiden aus Nordend zusätzlichen Stoff abzugewinnen.", completion = "Ich denke, dass Ihr diese Fähigkeit äußerst wichtig finden werdet, um zu schneiderischer Größe zu gelangen!", rewards = "Ihr erlernt:\n\nPlündern nordischer Stoffe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPlündern nordischer Stoffe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13273] = {title = "Dem Kern hinterher", objective = "Geht zu Branns Basislager und sucht nach Ausgrabungsleiter Khronas Notizen und Ausgrabungsleiter Sorens Karten.", description = "Da wir nun Norgannons Schale in Händen halten, muss nur noch die zweite Hälfte des Archivschlüssels gefunden werden. Zum Glück habe ich die Forscherliga intensiv nach Hinweisen über den Aufenthaltsort des Kerns suchen lassen.\n\nWeit südöstlich der Bibliothek des Erfinders an den Hängen nördlich von Dun Niffelem befindet sich ein Lager, das meinen Namen trägt. Dort sind diejenigen der Forscherliga stationiert, die nach der zweiten Hälfte des Schlüssels suchen. Bringt mir die Karten und Notizen, die sie angefertigt haben, und die andere Schlüsselhälfte sollte sich finden lassen.", progress = "Habt Ihr diese Notizen mitgebracht?", completion = "Zerstört? Was soll das heißen. das Lager wurde zerstört?\n\n&lt;Brann ballt wütend die Faust.&gt;\n\nDiese Eisenzwerge werden dafür bezahlen! Wir können nur noch wenig tun. Wir müssen uns darauf konzentrieren, den Schlüssel fertig zu stellen. Doch sobald ich in die Hallen von Ulduar gelange, werden die Eisenzwerge und ihre Meister für das, was sie getan haben, zur Verantwortung gezogen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13274] = {title = "Hüter des Kerns", objective = "Beschafft Norgannons Kern.", description = "Die Aufzeichnungen von Ausgrabungsleiter Soren erzählen uns, dass sich Norgannons Kern in der Obhut einer Schildwache namens Athan befindet - eine von Mimirs Schöpfungen.\n\nSoren meint, dass das Gewölbe, in dem Athan residiert, heutzutage \"Lokens Handel\" genannt wird.\n\nLoken, wie? Die Irdenen haben seinen Namen erwähnt.\n\nMan sagt, dass sich das Gewölbe südwestlich des zerstörten Lagers der Forscherliga befindet und dass dessen Eingang an einem Berghang mit Aussicht auf das Uralte Wintertal zu finden ist.\n\nFindet diesen Athan und beschafft Euch den Kern. Ich wäre jedoch nicht sonderlich überrascht, wenn Ihr auch kämpfen müsstet.", progress = "Hatte Ausgrabungsleiter Soren recht? Habt Ihr Norgannons Kern endlich gefunden?", completion = "Das ist es! Der Schlüssel ist beinahe in Reichweite. Jetzt müssen wir nur noch herausfinden, wie wir die Schale und den Kern zu einem einzigen Schlüssel zusammenfügen können. Sehen wir einmal nach, was Ausgrabungsleiter Soren dazu zu sagen hatte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13275] = {title = "Zeit zum Verstecken", objective = "Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.", description = "Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.\n\nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.\n\nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.", progress = "Habt Ihr das Blut?", completion = "Worauf wartet Ihr dann noch? Ihr müsst Euch damit einreiben!\n\nSchnell! Oder er wird Euch sehen!", rewards = "GeißelhammerStumpfer GehirnwäscherMesser des PilotenStreitkolben des letzten BefehlsBlutbrief des RitualistenRuhm des SchützenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13276] = {title = "Das ist monströs!", objective = "Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr das Monstrositätenwiedererweckungsset benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr dann 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", description = "Ihr wisst, was zu tun ist, <Klasse>.\n\nNehmt dieses Set und erschafft mit den Eingeweiden ihrer Monstrositäten Eure eigene Monstrosität. Lasst sie dann die feindlichen Truppen am Tor angreifen.\n\nIhr tätet gut daran, die Taktik noch zu verfeinern, bevor wir das Tor angreifen.", progress = nil, completion = "Wie ich sehe, entwickelt sich Eure Fertigkeit in Bezug auf Monstrositäten gut.\n\nSeid gewissenhaft, mein Freund, und schon bald wird das Tor der Horde gehören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13277] = {title = "Gegen die Riesen", objective = "Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Schrecken auf Mord'rethar bringt.", description = "Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.\n\nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.\n\nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.\n\nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.", progress = "Hattet Ihr Erfolg gegen die Riesen, <Volk>?", completion = "Hervorragend. Diese Exemplare sehen brauchbar aus.\n\nUnd wieder ist es an der Zeit, die Stärke des Gegners gegen ihn zu verwenden...", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13278] = {title = "Koprus der Entweihte", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Koprus den Entweihten bei Mord'rethar tötet.", description = "Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, <Klasse>.\n\nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.\n\nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;.\n\nMit einigen Nachforschungen können wir vielleicht herausfinden, wie sie eine derartige Kreatur erschaffen.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13279] = {title = "Grundkenntnisse der Chemie", objective = "Koltira Todesweber an Bord der Orgims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord'rethar gießt.", description = "<Koltira nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...\n\nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.\n\nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.\n\nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;.\n\nWenn unsere Armeen eintreffen, um gegen die Zitadelle zu marschieren, haben wir einen fundierten Plan, um das Tor des Todes einzunehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMolchaugenringFroschzehenbandFledermauswollsiegel\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13280] = {title = "König der Berge", objective = "Fetzi Gangzwinger in Ymirheim möchte, dass Ihr ihren Hüpfboter benutzt, um die Schlachtstandarte der Allianz in den Schädelhaufen auf dem Gipfel des Berges zu stecken.", description = "Ihr müsst meinen Hüpfboter nur so schnell wie möglich von Ymirheim zum Gipfel dieses Berges dort im Nordwesten bringen, <Name>!\n\nDieser heimtückische, nichtsnutzige Bumm Donnerbombe arbeitet an seinem eigenen Bot und ich befürchte, dass er beinahe fertig ist. Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!\n\nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass niemand besser ist, als die Allianz - und meine Ingenieursfertigkeiten!", progress = "Wartet mal eine Sekunde... Ihr habt unsere Schlachtstandarte noch nicht aufgestellt?!\n\nWas hält Euch auf?", completion = "IHR HABT ES GESCHAFFT! IHR HABT ES GESCHAFFT!\n\n&lt;Fetzi springt in die Luft und umarmt Euch innig.&gt;\n\n\n\nAch, Ihr seid einfach der Beste, den es gibt!\n\nDenkt Ihr, dass Ihr morgen wiederkommen könntet?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13281] = {title = "Die Seuche neutralisieren", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord'rethar schüttet.\n\npustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.", description = "Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, <Volk>.\n\nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.\n\nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.\n\nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord'rethar.", progress = nil, completion = "Ein Seuchenkessel weniger, um den wir uns kümmern müssen, wenn die Schlacht beginnt.\n\nEuer Kommandant wird äußerst zufrieden sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13282] = {title = "Rückkehr an die Oberfläche", objective = "Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", description = "Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.\n\nWir werden uns wiedersehen. Er wird nach Euch suchen.\n\nEs ist nur eine Frage der Zeit, bis er Euch findet.", progress = nil, completion = "&lt;Name&gt;! Wir dachten, Ihr seid tot!\n\nWir haben ein paar Männer bei der Explosion verloren... doch wir haben den Dienern der Geißel auf jeden Fall gut Schaden zugefügt. Sie sind auf schleunigstem Rückzug zur Zitadelle und hinterlassen große Lücken in ihrer Verteidigung. Es ist Zeit vorzurücken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13283] = {title = "König der Berge", objective = "Bumm Donnerbombe in Ymirheim möchte, dass Ihr seinen Hüpfboter benutzt, um die Schlachtstandarte der Horde in den Schädelhaufen auf dem Gipfel des Berges zu stecken.", description = "Also, <Name>, Ihr müsst meinen Hüpfboter zum Gipfel dieses Berges dort im Südosten bringen, wie gestern!\n\nDiese weibische, selbstgerechte Fetzi Gangzwinger meint, dass ihr Hüpfboter besser sei als meiner. Ha! Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!\n\nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass die Horde und meine verrückten Ingenieursfertigkeiten die Besten sind!", progress = "Wartet mal eine Sekunde... Ihr habt unsere Schlachtstandarte noch nicht aufgestellt?!\n\nWie kommt das?", completion = "Ah, &lt;Volk&gt;, ich wusste, dass Ihr der Richtige für den Job sein würdet!\n\n\n\nIch muss zugeben, &lt;Klasse&gt;, dass Euch das im Moment auf meiner Liste ganz weit oben stehen lässt!\n\nWas sagt Ihr dazu, diese Vorstellung morgen nochmal zu wiederholen? Es würde sich für Euch lohnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13284] = {title = "Bodenangriff", objective = "Eskortiert die Truppen der Himmelsbrecher zu den Toren von Ymirheim. Kehrt zu Feldkommandant Koup am Rand des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.", description = "Grüße, <Klasse>.\n\nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.\n\nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.", progress = nil, completion = "Ihr habt meinen Dank.\n\nDiese Operation war gnadenlos, doch uns blieb keine bessere Möglichkeit - unseren Lufteinheiten haben sie genauso schonungslos zugesetzt. Wir müssen diese Vrykul loswerden, wenn wir auch nur den Hauch einer Chance haben wollen, in Eiskrone weiter vorzustoßen.\n\nWir werden später höchstwahrscheinlich noch mehr Hilfe benötigen. Bitte schließt euch uns wieder an, sollte sich die Möglichkeit ergeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13285] = {title = "Den Schlüsselstein schmieden", objective = "Brann Bronzebart möchte, dass Ihr ihn im Tempel des Erfindungsreichtums trefft und ihm dabei helft, Norgannons Schale und Norgannons Kern zusammenzufügen. Meldet Euch bei Boktar Blutfurie bei der Absturzstelle Grom'ash, sobald dies getan ist.", description = "Aha! Da ist er ja: der Tempel des Erfindungsreichtums, Sitz von Hüter Mimir höchstpersönlich! Natürlich, dort würde man hingehen, um die zwei Teile des Schlüssels zusammenzufügen.\n\nDen Notizen des Ausgrabungsleiters zufolge ist der Tempel des Erfindungsreichtums einer der höchsten Punkte auf der westlichen Seite der Terrasse der Schöpfer. Das bedeutet, dass sich der Ort ungefähr östlich der Absturzstelle Grom'ash befinden sollte.\n\nIch treffe Euch im Tempel und wir werden die zwei Teile zusammenfügen.", progress = nil, completion = "&lt;Boktar nickt zustimmend, als Ihr ihm davon erzählt, wie Ihr Brann dabei geholfen habt, die Teile zu beschaffen und sie zusammenzufügen.&gt;\n\nBrann könnte genau der Verbündete sein, den wir brauchen, um herauszufinden, was wirklich in Ulduar vor sich geht. Es war gut von Euch, ihm zu helfen. Gegen diesen Loken und seine untergebenen Eisenzwerge benötigen wir jede Hilfe, die wir bekommen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBernsteinglutsiegelEisgeschmiedeter KampfringGezacktes EisbandRing der Nordwinde\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13286] = {title = "... Jede Hilfe, die wir kriegen können", objective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr mit Thassarian sprecht.", description = "Schlimme Zeiten, <Klasse>...\n\nSo ungern ich das auch tue, ich bin mittlerweile bereit, Hilfe von wirklich jedem anzunehmen - selbst von unserem Todesritter.\n\nGeht zu Thassarian und seht, ob er uns dabei helfen kann, Taktiken gegen die Geißel zu entwickeln, die uns den Sieg bringen können, sobald wir einen weiteren Angriff beginnen können.\n\nWir sind so weit gekommen... wir dürfen jetzt nicht scheitern!", progress = nil, completion = "Es war weise von Stabshauptmann Bartlett, Euch zu mir zu schicken.\n\nWährend er sich um euren Konflikt mit der Horde sorgt, muss sich jemand voll und ganz auf die wahre Mission hier konzentrieren - den Marsch auf die Eiskronenzitadelle.\n\nWer könnte besser Eure Bemühungen koordinieren, als ein ehemaliger Diener des Lichkönigs?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13287] = {title = "Stechen und Stoßen", objective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten bei der Zerbrochenen Front tötet.", description = "Wie jemand mit Eurer Erfahrung sicher weiß, gibt es keinen besseren Weg, etwas über seinen Gegner herauszufinden, als sich ihm im Kampf gegenüberzustellen.\n\nObschon Ihr sicher nach dem Ruhm giert, die Eiskronenzitadelle einzunehmen, kann dies jedoch nicht passieren, bevor nicht jedes der Tore des Lichkönigs erobert ist. Vorerst müsst Ihr Eure Anstrengungen auf das erste der Tore konzentrieren...\n\nKehrt zur Zerbrochenen Front zurück. Verwickelt den Gegner in eine Schlacht. Sucht nach einer Schwäche, die wir ausnutzen könnten, und kehrt dann mit einem detaillierten Bericht zu mir zurück.", progress = nil, completion = "Ehrlich, &lt;Klasse&gt;?\n\nNichts besonderes zu berichten?\n\n\n\nIch erlaube mir, das Gegenteil zu behaupten...", rewards = "MonstrositätenlederumhangAuf Euch wartet eine dieser Belohnungen:\n\nRing des gefallenen SchattenadeptenAmulett des ruchlosen Totenbeschwörers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13288] = {title = "Das ist monströs!", objective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", description = "Monstrositäten...\n\nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.\n\nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.\n\nZu Eurem Glück kenne ich diese Geheimnisse.\n\nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.", progress = nil, completion = "Seht Ihr, &lt;Klasse&gt;?\n\nRaffinesse kann mitunter selbst in aussichtslos scheinenden Situationen für Chancengleichheit sorgen.", rewards = "Slipper der durchbrochenen FrontMantel der WiedererweckungGamaschen des SpukjägersSchulterstücke des GeißelbannsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13289] = {title = "Das ist monströs!", objective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", description = "Ihr wisst, was Ihr zu tun habt, <Klasse>.\n\nNehmt dieses Set hier und benutzt die Eingeweide ihrer Monstrositäten, um eine eigene zu erschaffen, dann befehlt ihr, die Streitkräfte des Gegners am Tor anzugreifen.\n\nIhr tätet gut daran, vor unserem nächsten Angriff auf das Tor diese Taktik zu verfeinern.", progress = nil, completion = "Ich sehe, dass sich Eure Fähigkeiten mit den Monstrositäten beachtlich entwickelt haben.\n\nBleibt eifrig bei der Sache, Freund, und schon bald wird das Tor in der Hand der Allianz sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13290] = {title = "Bitte recht aufmerksam", objective = "Stabshauptmann Bartlett möchte, dass Ihr mit Chefingenieur Bolzenschlüssel in der Himmelsbrecher redet.", description = "Chefingenieur Bolzenschlüssel hat sich als unabdingbar auf der Sturmbrecher erwiesen. Ohne seine Genialität lägen wir mittlerweile schon mehrfach über den halben Gletscher verstreut.\n\nDas Problem ist nur, dass er jede einzelne popelige Erfindung oder Entdeckung gleich diskutieren will - obwohl ich die Hälfte sowieso nicht verstehe.\n\nMein Augenmerk muss jetzt aber ausschließlich auf unseren Feinden liegen. Ich kann mir keine Ablenkungen erlauben.\n\nBitte stattet ihm einen Besuch an meiner Stelle ab, <Name>. Und assistiert ihm, wenn Ihr könnt. Ihr findet ihn unter Deck.", progress = nil, completion = "Cappy hat Euch an seiner Stelle geschickt, oder?\n\nNun gut, &lt;Klasse&gt;. Krempelt Eure Ärmel hoch... es ist Zeit, an die Arbeit zu gehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13291] = {title = "Geliehene Technologie", objective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher will, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front benutzt.\n\nUm die Lösung zu benutzen, braucht Ihr einen zurückgelassenen Helm, eine zurückgelassene Rüstung und einen Knochenhaufen, die allesamt an der Zerbrochenen Front gefunden werden müssen.", description = "Ich kapier's ja, ich kapier's ja. Cappy ist zu beschäftigt, um es sich selber anzusehen. Selbst Schuld!\n\nSeht Ihr, ich habe es geschafft, eine gewisse Lieferung Lösungen vom Feind zu 'leihen'. Und so sehr ich es auch hasse, mit minderwertiger Goblintechnologie zu hantieren, so bin ich doch versucht, hier mal eine Ausnahme zu machen.\n\nNehmt diese Probe. Ihr müsst für mich einige Feldversuche durchführen, um ihre Nützlichkeit unter Beweis zu stellen, während ich versuche, ein wenig umgekehrte Ingenieurskunst zu betreiben und den Erschaffungsprozess zu duplizieren.\n\nGeht an die Front und sammelt das Material, um eine Attrappe zu bauen, dann benutzt das Öl.", progress = nil, completion = "Gute Neuigkeiten!\n\nIch habe es geschafft, die Lösung zu reproduzieren - was natürlich kaum eine Errungenschaft darstellt.\n\nIch bezweifle, dass diese Neanderthaler von Goblins jemals etwas gebastelt bekommen, das wir Gnome nicht im Schlaf nachbauen könnten.", rewards = "SchmugglerarmschienenMukluks des GletscherläufersGürtel des HimmelskapitänsPlattenarmreif der HimmelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13292] = {title = "Die Lösungslösung", objective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front einsetzt.\n\nUm die Lösung benutzen zu können, benötigt Ihr einen zurückgelassenen Helm, zurückgelassene Rüstung und einen Knochenhaufen, die alle an der Zerbrochenen Front zu finden sind.", description = "Oh, ja, ja. Wieder zurück, hmm? Man kann nie genug Training haben, was?\n\nUnd hier ist sie, die Lösung für das ärgerliche Frostwyrmproblem.\n\nVerringert ihre Anzahl, <Volk>. Je mehr Ihr jetzt ausschaltet, desto weniger sitzen uns im Nacken, wenn wir uns aufmachen, die Zitadelle anzugreifen.\n\nViel Glück Euch. Und bringt doch bitte zurück, was Ihr nicht braucht.", progress = nil, completion = "Großartig! Wirklich großartig. Ihr werdet noch zum Wyrmtöterprofi!\n\nKommt wieder, wenn Ihr bereit seid, Ihre Reihen weiter auszudünnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13293] = {title = "Auf nach Ymirheim!", objective = "Redet mit Bumm Donnerbombe in Ymirheim.", description = "Ihr müsst hinunter nach Ymirheim, der großen Stadt der Frostvrykul im Zentrum von Eiskrone.\n\nUnser Kumpel, Bumm Donnerbombe, ist schon da, im Westen der Stadt und repräsentiert die Kriegshymnenoffensive in einem Wettkampf gegen die Allianz. Es steht sein Hüpfboter gegen ihren in einem Wettkampf um den Titel König der Berge!\n\nLasst uns nicht im Stich, <Name>. Der Stolz der goblinischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier auf dem Schiff auf Euch.\n\nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Feiglingen ordentlich in den Hintern tretet!", progress = nil, completion = "Oh Mann, bin ich froh, Euch zu sehen. Hat Euch der Häuptling von der Hammer hergeschickt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13294] = {title = "Gegen die Riesen", objective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Spuken auf Mord'rethar bringt.", description = "Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.\n\nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.\n\nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.\n\nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.", progress = "Hattet Ihr Erfolg gegen die Riesen, <Volk>?", completion = "Hervorragend. Diese Exemplare sehen brauchbar aus.\n\nUnd wieder ist es an der Zeit, die Stärke des Gegners gegen ihn zu verwenden...", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13295] = {title = "Grundkenntnisse der Chemie", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord'rethar gießt.", description = "<Thassarian nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...\n\nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.\n\nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.\n\nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;.\n\nWenn unsere Armeen eintreffen, um gegen die Zitadelle zu marschieren, haben wir einen fundierten Plan, um das Tor des Todes einzunehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMolchaugenringFledermauswollsiegelFroschzehenband\n\nIhr bekommt außerdem:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13296] = {title = "Auf nach Ymirheim!", objective = "Sprecht mit Fetzi Gangzwinger in Ymirheim.", description = "Ihr müsst runter nach Ymirheim, der großen Frostvrykulstadt im Zentrum von Eiskrone.\n\nFetzi Gangzwinger ist schon da, im Süden der Stadt, und repräsentiert die Expedition 'Valianz' in einem Wettkampf gegen die Mistkerle der Horde. Es steht Fetzis Hüpfboter gegen ihren in einem Wettkampf um den Titel des Königs der Berge!\n\nLasst uns nicht im Stich, <Name>. Der Stolz der gnomischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier in der Feste auf Euch.\n\nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Idioten ordentlich in den Hintern tretet!", progress = nil, completion = "Hat Euch der Boss von der Himmelsbrecher hier runter geschickt? Ist das nicht süß?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13297] = {title = "Die Seuche neutralisieren", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord'rethar schüttet.\n\npustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.", description = "Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, <Volk>.\n\nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.\n\nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.\n\nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord'rethar.", progress = nil, completion = "Ein Seuchenkessel weniger, um den wir uns kümmern müssen, wenn die Schlacht beginnt.\n\nEuer Hauptmann wird äußerst zufrieden sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13298] = {title = "Koprus der Entweihte", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Koprus den Entweihten in Mord'rethar tötet.", description = "Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, <Klasse>.\n\nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.\n\nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;.\n\nMit einigen Nachforschungen können wir vielleicht herausfinden, wie sie eine derartige Kreatur erschaffen.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13299] = {title = "ZZOLDWisp Cloak", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nIrrwischumhang"}
MultiLanguageQuestData['de'][13300] = {title = "Vom Saronit abhängig", objective = "Absalan der Fromme an Bord der Himmelsbrecher möchte, dass Ihr 10 Saronitminensklaven rettet.", description = "Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.\n\nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.\n\nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Expedition 'Valianz' als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, <Name>?", progress = nil, completion = "Sie werden wahnsinnig gemacht? Stimmen in ihren Köpfen?\n\nStimmen in Eurem Kopf?!\n\nIch möchte, dass Ihr Eure Gedanken von dem Unheil befreit, das diesen Ort ergriffen hat, &lt;Klasse&gt;.\n\nWir werden versuchen morgen den Rest von ihnen da rauszubekommen, wenn Ihr eine Chance hattet, Euch auszuruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13301] = {title = "Bodenangriff", objective = "Eskortiert die Truppen der Kor'kron zu den Toren von Ymirheim. Kehrt zu Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.", description = "Grüße, <Klasse>.\n\nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.\n\nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.", progress = nil, completion = "Ihr habt meinen Dank.\n\nDiese Operation war gnadenlos, doch uns blieb keine bessere Möglichkeit - unseren Lufteinheiten haben sie genauso schonungslos zugesetzt. Wir müssen diese Vrykul loswerden, wenn wir auch nur den Hauch einer Chance haben wollen, in Eiskrone weiter vorzustoßen.\n\nWir werden später höchstwahrscheinlich noch mehr Hilfe benötigen. Bitte schließt euch uns wieder an, sollte sich die Möglichkeit ergeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13302] = {title = "Vom Saronit abhängig", objective = "Bruder Keltan an Bord der Orgrims Hammer möchte, dass Ihr 10 Saronitminensklaven rettet.", description = "Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.\n\nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.\n\nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Kriegshymnenoffensive als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, <Name>?", progress = nil, completion = "Sie werden wahnsinnig gemacht? Stimmen in ihren Köpfen?\n\nStimmen in Eurem Kopf?!\n\nIch möchte, dass Ihr Eure Gedanken von dem Unheil befreit, das diesen Ort ergriffen hat, &lt;Klasse&gt;.\n\nWir werden versuchen morgen den Rest von ihnen da rauszubekommen, wenn Ihr eine Chance hattet, Euch auszuruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13303] = {title = "Test Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nIrrwischumhang\n\nIhr bekommt außerdem:\n\nHasenkäfig (Braun)"}
MultiLanguageQuestData['de'][13304] = {title = "Feldreparaturen", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken im Tal der Verlorenen Hoffnung beschafft und sie zum defekten Verwüster bringt.", description = "Die Geißel erholt sich noch immer von unserem Angriff, <Name>. Jetzt ist die Zeit, die Gunst der Stunde zu nutzen und zuzuschlagen.\n\nDas strategisch wichtige Tal unter uns ist weit offen. Wir haben in der südöstlichen Ecke des Tals der Verlorenen Hoffnung ein zerlegtes Verwüsterfahrzeug entdeckt, das sich, so glauben wir, noch in einem funktionsfähigen Zustand befindet.\n\nFalls Ihr die restlichen Teile von den Aasfressern der Geißel beschaffen könntet, solltet Ihr es wieder zum Laufen bringen können. Ein einziger funktionierender Verwüster kann unter den Bodeneinheiten des Feindes verheerenden Schaden anrichten.", progress = "Der Verwüster wurde stark beschädigt.", completion = "Der Verwüster hat schon bessere Tage gesehen, aber die Struktur hat keinen dauerhaften Schaden genommen. Die Ersatzteile, die Ihr gebracht habt, sollten ausreichen, um ihn zumindest vorübergehend wieder ans Laufen zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13305] = {title = "Tut Euer Schlechtestes", objective = "Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.", description = "Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.\n\nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.\n\nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.", progress = nil, completion = "Seht Ihr? Ihr habt Euren gerechten Anteil zwar getötet, doch für jeden Einzelnen, den Ihr vernichtet habt, kam ein weiterer aus der Erde, um dessen Platz einzunehmen.\n\nIhr wisst nicht, wem Ihr hier gegenübersteht, &lt;Name&gt;. Lasst es mich Euch zeigen.", rewards = "Handschutz des VerwüstersStaubmantel des VerwüsterfahrersZahnriemen des runderneuerten VerwüstersBeschleunigerstampferKettengamaschen des AntriebsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13306] = {title = "Errichtet die Barrikaden", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.", description = "Sobald unsere Truppen sich hinter Aldur'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.\n\nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.\n\nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.", progress = nil, completion = "&lt;Koltira nickt kurz.&gt;\n\nGut. Sie bieten nicht gerade viel Schutz, aber immer noch besser als nichts. Dieses Tor ist noch immer der perfekte Engpass, wenn die Geißelanführer wissen, was sie tun. Wir müssen so viel von dem umliegenden Gebiet wie möglich einnehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13307] = {title = "Blutbespritzte Banner", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.", description = "Im Tal der Gefallenen Helden und am Eiskronengletscher, im Westen Aldur'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.\n\nEs obliegt Euch, uns von diesem Hindernis zu befreien und den Widerstand auszudünnen, bevor die Hauptstreitmacht vorrücken kann.", progress = nil, completion = "Ihr habt die Bannerträger der Geißel und ihre Lakaien entfernt? Gut. Unsere Vorbereitungen müssen weitergehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13308] = {title = "Geistiger Zwang", objective = "Dunkelsprecher R'khem in den Saronitminen möchte, dass Ihr den Schlüssel des Großknechts beschafft, um so seine Ketten zu öffnen.", description = "<Die Kreatur spricht direkt über Euren Geist mit Euch. Ihre Gedanken sind schmerzhaft und seltsam.>\n\n<Volk>, ich brauche Eure Hilfe. Ich bin genau so wie Eure versklavten Freunde ein Opfer der dem Lichkönig dienenden Ymirjar und ihrer Habsucht. Sie nahmen mich gefangen, als ich die Tiefen verließ, um die Geräusche aus dieser Höhle zu untersuchen, und legten mich in Ketten.\n\nWürdet Ihr mir bitte helfen? Der Vorarbeiter dieser Minen trägt den Schlüssel zu meinen Ketten bei sich. Tötet ihn!\n\n<Ihr könnt ein drängendes Gefühl in Eurem Geist spüren, als würde die Kreatur versuchen, Euch zu zwingen.>", progress = "Ihr werdet für den Dienst, den Ihr mir erwiesen habt, reich belohnt werden.\n\n<Der Dunkelsprecher lässt besänftigende Gefühle in Eurem Geist entstehen.>\n\nIhr werdet es nicht bereuen, mich zu entfesseln.", completion = "&lt;Als Ihr auf die Kreatur zugeht, wird Euer Geist von einer weiteren Welle der Euphorie, vermischt mit ein wenig Schmerz, überwältigt.&gt;\n\nGut... gut! Nur damit Ihr wisst, dass ich gerecht bin, werde ich Euch zuerst Eure versprochene Belohnung geben.\n\nUnd dann werdet Ihr mir freiwillig den Schlüssel geben.", rewards = "Fußpolster des DunkelsprechersTreter des DunkelsprechersSabatons des DunkelsprechersEisenlaufschuhe des DunkelsprechersIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13309] = {title = "Luftangriff", objective = "Feldkommandant Koup an der Kante des Gletschers im Osten von Ymirheim hat Euch befohlen, den Geschützturm der Himmelsbrecher zu benutzen, um den Truppentransporter der Himmelsbrecher lange genug in der Luft zu halten, bis alle abgeworfen wurden.", description = "Ich habe ein paar geeignete Jungs, die bereit sind, in Ymirheim abgeworfen zu werden. Ihr könntet mir helfen, indem Ihr sie sicher dorthin bringt.\n\nDort haben die Vrykul so etwas wie automatische Speerkanonen aufgebaut, um unsere Transporter auszuschalten. Wir haben unsere Ingenieure einen Geschützturm bauen lassen, mit dem Rauchgranaten abgeschossen werden können, um diesen Speerkanonen etwas entgegenzusetzen. Schießt einfach in die Nähe der Kanonen. Das sollte ihre Sicht blockieren und sie außer Kraft setzen.\n\nSetzt Euch an einen der Türme und sorgt dafür, dass alle meine Jungs in einem Stück zu ihrem Abwurfgebiet gelangen.", progress = nil, completion = "Ausgezeichnete Arbeit, Soldat. Wir könnten hier noch mehr so fähige Leute wie Euch gebrauchen. Schaut doch einen anderen Tag noch mal vorbei, wenn die Operation noch im Gange ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13310] = {title = "Luftangriff", objective = "Bodentruppenkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim hat Euch befohlen, den Geschützturm der Kor'kron zu benutzen, um den Truppentransporter der Kor'kron lange genug in der Luft zu halten, bis alle abgeworfen wurden.", description = "Nun gut, Grünschnabel, ich hab' etwas für dich, damit du nicht völlig nutzlos bist.\n\nEine Einheit von hochtrainierten Spitzeln ist bereit für ihren Abwurf in Ymirheim. Die Vrykul dort haben automatische Speerkanonen aufgestellt, die unsere Transporter in Stücke geschossen haben, also haben wir unsere Ingenieure einen Geschützturm auf der Orgrims Hammer bauen lassen, mit dem Rauchgranaten abgeschossen werden können.\n\nIhr seid der Schütze. Feuert auf ihre Speerkanonen, um ihnen die Sicht zu nehmen und sie außer Kraft zu setzen. Sorgt dafür, dass alle meine Männer abgeworfen werden und der Transporter ganz bleibt.", progress = "Job erledigt?", completion = "Also nur zum Teil unnütz. Gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13311] = {title = "Dämonenkartenset", objective = "Beschwört mithilfe des Dämonenkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", description = "Jetzt, da Ihr alle Dämonenkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set der Dämonenkarten zusammen zu bekommen! Glückwunsch!", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", rewards = "Messer des Dunkelmond-JahrmarktsRichtklinge des Dunkelmond-JahrmarktsMagierstab des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][13312] = {title = "Das Eisenwallbollwerk", objective = "Besiegt Grimkor den Boshaften und kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", description = "Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.\n\nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.", progress = nil, completion = "Grimkor ist also durch Eure Hand gefallen? Ausgezeichnete Arbeit. Mit ihm aus dem Weg sind unsere Chancen, das Bollwerk während des Angriffs zu halten, um einiges größer.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13313] = {title = "Die Augen im Himmel erblinden lassen", objective = "Benutzt die BGR-3, um damit 6 Kampfaufklärer der Himmelsbrecher abzuschießen. Dann meldet Euch wieder bei Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer.", description = "Die Allianz hat es irgendwie geschafft, eine Schwadron von Aufklärungsfahrzeugen über das Tal der Gefallenen Helden und den Eiskronengletscher zu entsenden, die weiten Gebiete westlich von Aldur'thar.\n\nWir können ihnen nicht die Führung in diesem Kampf überlassen. Chefingenieur Kupferklammer hat mich mit der perfekten Waffe, um dieser Bedrohung Herr zu werden, ausgestattet. Er nennt seine neue Rakete die BGR-3. Ich habe seine Versicherung, dass sie die fliegenden Maschinen der Allianz mit einem einzigen Treffer ausschalten wird. Geht und benutzt diese Waffe dazu, uns die Oberhand zu verschaffen.", progress = nil, completion = "Gut. Weniger dieser stinkenden Allianzler, die uns im Weg stehen. Wir werden ihnen zeigen, wie wahre Krieger aussehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13314] = {title = "Beschafft die Nachricht", objective = "Beschafft Euch 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.", description = "Die Horde führt irgendetwas im Schilde - mir gefällt das nicht. Nach der verrückten Vorstellung, die sie an der Zerbrochenen Front geliefert haben, sind sie zu allem fähig, und es liegt an uns, sie aufzuhalten.\n\nEs herrscht viel Bewegung am Himmel über dem Eiskronengletscher westlich von Aldur'thar und dem Eisenwallbollwerk. Späher und Boten der Horde auf Drachenfalken fliegen wie der Wind ein und aus - Berichte und Befehle bei sich tragend. Nehmt diese Pfeilpistole und tötet mit ihr die Späher der Orgrims Hammer. Am besten wird es wahrscheinlich dann funktionieren, wenn Ihr auch fliegt.", progress = "Habt Ihr die Sendungen abgefangen?", completion = "Es ist gut, jemanden Kompetenten zu haben, der unsere Mission ausführt, &lt;Name&gt;. Wenn wir nur eine Armee von Leuten wie Euch hätten, könnten wir der Horde zeigen, aus was wir gemacht sind. Diese Berichte, die Ihr abgefangen habt, werden uns dabei helfen, in diesem Kampf die Oberhand zu behalten. Wir sind vielleicht am Boden, doch noch lange nicht K.O.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13315] = {title = "Vorschau", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.", description = "Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen, wenn sich die Horde, mit der Ihr Euch unbedingt messen wollt, nicht einmischen wird...\n\nWie dem auch sei: unser nächstes Ziel wird das Tor der Verwüstung sein. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.\n\nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.", progress = nil, completion = "Schön und gut, &lt;Klasse&gt;.\n\nNun, da Ihr mit eigenen Augen gesehen habt, wem wir hier gegenüberstehen, ist es Zeit, an die Arbeit zu gehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13316] = {title = "Die Wächter von Corp'rethar", objective = "Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp'rethar tötet.", description = "Corp'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.\n\nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.\n\nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.", progress = nil, completion = "Ich hoffe, dass sich Euer Erfolg bei Corp'rethar als Omen für die kommende Schlacht erweisen wird. Der Lichkönig kann nicht tatenlos herumstehen, während wir auf die Tore seiner Festung zumarschieren.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13317] = {title = "----", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13318] = {title = "Gefährliche Gewandung", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", description = "Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.\n\nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, <Klasse>, und wendet sie dann auf einen Unterwerfer an.", progress = nil, completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13319] = {title = "Befehlskette", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr nach Aldur'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.", description = "Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.\n\nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, <Volk>, ist für den Augenblick gut genug.\n\nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;. Doch brecht Euch beim \"Auf die Schulter klopfen\" nicht den Arm. Sie werden diese Aufseher im Nu ersetzt haben...", rewards = "Brustschutz des KultbrechersKultistengugelJhaeqons TunikaSavryns schlammige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13320] = {title = "Kann nicht reproduziert werden", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Bolzenschlüssel bringt.", description = "Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.\n\nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.\n\nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...\n\nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Bolzenschlüssel.", progress = "Was habt Ihr da, <Volk>?", completion = "&lt;Bolzenschlüssel schüttet den Inhalt des Fläschchens in seinen Tetrahydropartikelanalysierer.&gt;\n\nWas wir hier sehen, ist nichts weiter, als dass diese Flüssigkeit kein Gemisch bilden kann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13321] = {title = "Jetzt neu testen", objective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", description = "Das sollte seinen Zweck erfüllen!\n\nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.\n\nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", progress = nil, completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", rewards = "Kesselrührstab des KultistenBogen der RückwärtsbewegungZuckender StreitkolbenVerdrehter StraßendiebprüglerAuf Euch wartet eine dieser Belohnungen:\n\nTödliche Rasiermesserwurfpfeile\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13322] = {title = "Jetzt neu testen", objective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr das verdünnte Kulttonikum trinkt, Kultisten in Aldur'thar tötet und ihnen ihre besudelte Essenz abnehmt. Fügt danach 10 von den Essenzen zu einer windenden Masse zusammen und werft diese dann in einen ihrer Kessel.", description = "Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.\n\nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", progress = nil, completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13323] = {title = "Gefährliche Gewandung", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", description = "Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...\n\nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.", progress = nil, completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13324] = {title = "Prismenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Prismenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Prismenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Prismenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Prismenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Illusion"}
MultiLanguageQuestData['de'][13325] = {title = "Chaoskartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Chaoskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Chaoskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Chaoskartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Chaoskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Berserker!"}
MultiLanguageQuestData['de'][13326] = {title = "Adligenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Adligenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Adligenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Adligenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Adligenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDunkelmond-Karte: GrandeurDunkelmond-Karte: GrandeurDunkelmond-Karte: GrandeurDunkelmond-Karte: Grandeur"}
MultiLanguageQuestData['de'][13327] = {title = "Untodeskartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Untodeskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Untodeskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Untotenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Untotenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Tod"}
MultiLanguageQuestData['de'][13328] = {title = "Einen Scherbenhaufen hinterlassen", objective = "Bringt Koltira Todesweber an Bord der Orgrims Hammer den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.", description = "Oberhalb der Schlachtfelder von Corp'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.\n\nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.\n\nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!", progress = "Habt Ihr die neuen Waffen des Lichkönigs zerstört?", completion = "&lt;Koltira nimmt die Kristallsplitter entgegen und spricht mit ruhiger Stimme.&gt;\n\nIch erinnere mich hieran...\n\nSchwächere Männer würden leicht unter ihrem Angriff zusammenbrechen. Diese Bedrohung zu beenden war gute Arbeit.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13329] = {title = "Vor dem Tor des Schreckens", objective = "Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.", description = "Der Großbrand, das Gebiet vor Corp'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.\n\nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.\n\nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.", progress = nil, completion = "&lt;Koltira hört sich Euren Bericht an.&gt;\n\nGut. Ich werde die Ingenieure so viel wie möglich von der Säure zusammenmischen lassen, bevor wir Corp'rethar mit der Hauptstreitmacht angreifen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13330] = {title = "Blut der Auserwählten", objective = "Kriegshetzer Davos Rabatz auf der Orgrims Hammer hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.", description = "Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten \"Auserwählten\" des Lichkönigs plattzumachen.\n\nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.", progress = nil, completion = "Wohl doch nicht ganz so stark, wie? Der Lichkönig erntet nun, was er gesät hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13331] = {title = "Der Allianz die Augen zuhalten", objective = "Benutzt die BGR-3 um 6 Kampfaufklärer der Himmelsbrecher zu zerstören und erstattet dann dem Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer Bericht.", description = "Die Allianz ist hartnäckig, so viel gestehe ich ihr zu, aber es bedarf mehr, um uns aufzuhalten. Nehmt diese BGR-3 und schießt erneut die Kampfaufklärer der Himmelsbrecher ab.\n\nIch bezweifele zwar, dass die Nachricht in ihre dicken Schädel reingeht, aber wir verfügen über genügend Raketen, um unseren Punkt deutlich zu machen. Geht und haltet über dem Tal der Gefallenen Helden, westlich von Aldur'thar, nach ihren Aufklärern Ausschau. Und kommt nicht zurück, solange Ihr sie nicht in Trümmer gelegt habt.", progress = nil, completion = "Mal wieder gut gemacht. Die Vorherrschaft der Horde ist gesichert, jedenfalls bis dieser Allianzlerabschaum sich entschließt, uns erneut herauszufordern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13332] = {title = "Errichtet die Barrikaden", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.", description = "Sobald unsere Truppen sich hinter Aldur'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.\n\nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.\n\nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.", progress = nil, completion = "&lt;Thassarian nickt kurz.&gt;\n\nGut. Sie bieten nicht gerade viel Schutz, aber immer noch besser als nichts. Dieses Tor ist noch immer der perfekte Engpass, wenn die Geißelanführer wissen, was sie tun. Wir müssen so viel von dem umliegenden Gebiet wie möglich einnehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13333] = {title = "Mehr Sendungen abfangen", objective = "Fangt 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer ab und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.", description = "Trotz unserer Anstrengungen schickt die Horde weiterhin Späher in diese Gegend des Eiskronengletschers, westlich des Eisenwallbollwerks und Aldur'thar.\n\nWir können es uns nicht leisten, der Horde bei dieser Erkundungsoperation die Oberhand zu lassen. Nehmt wieder diese Pfeilpistole mit Euch und zeigt den Spähern der Orgrims Hammer keine Gnade! Bringt die abgefangenen Sendungen zu mir.\n\nWir werden die Fehlschläge der Horde zu unseren Gunsten nutzen.", progress = "Habt Ihr die Sendungen abgefangen?", completion = "&lt;Der Hochkapitän nimmt die Sendungen entgegen.&gt;\n\nDas ist genau, was wir brauchen. Selbst die Horde ist nicht so dumm, einen Ansturm auf die Geißel blind zu wagen. Mit ihren Berichten in Händen, werden wir gut vorbereitet sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13334] = {title = "Blutbespritzte Banner", objective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.", description = "Im Tal der Gefallenen Helden und am Eiskronengletscher, im Westen Aldur'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.\n\nEs obliegt Euch, uns von diesem Hindernis zu befreien und zu testen, wie es um deren Widerstand steht, bevor die Hauptstreitmacht vorrücken kann.", progress = nil, completion = "Ihr habt die Bannerträger der Geißel und ihre Lakaien entfernt? Gut. Unsere Vorbereitungen müssen weitergehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13335] = {title = "Vor dem Tor des Schreckens", objective = "Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.", description = "Der Großbrand, das Gebiet vor Corp'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.\n\nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.\n\nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.", progress = nil, completion = "&lt;Thassarian hört Euch zu, als Ihr von Eurem erfolgreichen Test erzählt.&gt;\n\nDie Säure hat also funktioniert? Gut. Wir werden sie brauchen, wenn die Armee die Häscher mit voller Stärke angreifen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13336] = {title = "Blut der Auserwählten", objective = "Kürassier Drosche auf der Himmelsbrecher hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.", description = "Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten \"Auserwählten\" des Lichkönigs plattzumachen.\n\nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.", progress = nil, completion = "Der Verräterkönig wird gestürzt werden. Daran hege ich keinen Zweifel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13337] = {title = "Das Eisenwallbollwerk", objective = "Besiegt Grimkor den Boshaften und kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", description = "Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.\n\nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.", progress = "Habt Ihr Eure Mission abgeschlossen?", completion = "Grimkor ist also durch Eure Hand gefallen? Ausgezeichnete Arbeit. Mit ihm aus dem Weg sind unsere Chancen, das Bollwerk während des Angriffs zu halten, um einiges größer.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13338] = {title = "Die Wächter von Corp'rethar", objective = "Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp'rethar tötet.", description = "Corp'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.\n\nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.\n\nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.", progress = nil, completion = "Ich hoffe, dass sich Euer Erfolg bei Corp'rethar als Omen für die kommende Schlacht erweisen wird. Der Lichkönig kann nicht tatenlos herumstehen, während wir auf die Tore seiner Festung zumarschieren.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13339] = {title = "Einen Scherbenhaufen hinterlassen", objective = "Bringt Thassarian an Bord der Himmelsbrecher den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.", description = "Oberhalb der Schlachtfelder von Corp'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.\n\nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.\n\nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!", progress = "Habt Ihr die neuen Waffen des Lichkönigs zerstört?", completion = "&lt;Thassarian nimmt die Kristallsplitter entgegen und spricht mit ruhiger Stimme.&gt;\n\nIch erinnere mich hieran...\n\nSchwächere Männer würden leicht unter ihrem Angriff zusammenbrechen. Diese Bedrohung zu beenden war gute Arbeit.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13340] = {title = "Schließt Euch dem Angriff an", objective = "Meldet Euch bei Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim.", description = "Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.\n\nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.\n\nFeldkommandant Xutjja befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Xutjjas Truppen sind nahe der Kante des Gletschers im Norden der Stadt positioniert.", progress = nil, completion = "Mehr Fleisch für den Schleifer. Willkommen in der Hölle, Soldat.\n\nMeine Männer werden den Angriff auf das Tor von hier aus beginnen, und wir werden einige Infiltratoren aus der Luft absetzen. Wir brauchen mehr Leute an beiden Fronten. Ich habe so das Gefühl, dass sich dieser Angriff eine ganze Weile ziehen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13341] = {title = "Schließt Euch dem Angriff an", objective = "Meldet Euch bei Feldkommandant Koup an der Kante des Gletschers im Osten von Ymirheim.", description = "Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.\n\nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.\n\nFeldkommandant Koup befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Koups Truppen sind nahe der Kante des Gletschers im Osten der Stadt positioniert.", progress = nil, completion = "Willkommen in der Hölle, Soldat.\n\nMeine Männer werden den Angriff auf das Tor von hier aus beginnen, und wir werden einige Infiltratoren aus der Luft absetzen. Wir brauchen mehr Leute an beiden Fronten. Ich habe so das Gefühl, dass sich dieser Angriff eine ganze Weile ziehen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13342] = {title = "Keine Wanze", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", description = "So, <mein Freund/meine Freundin>, es ist an der Zeit eine Wanze zu platzieren.\n\nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.\n\nIm nördlichen Bereich von Aldur'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um unseren kleinen Spion zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Klasse&gt;.\n\nDer Bote hat uns bereits einige wertvolle Informationen zukommen lassen.", rewards = "Mantel des dunklen BotensGillys StrangulierungsstulpenKettenhandschuhe des dämonischen DienersBeinplatten der NordexpeditionEingeweidesprenger von Aldur'tharIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13343] = {title = "Geheimnis der Ewigen, die 2.", objective = "Chromie auf der höchsten Ebene des Wyrmruhtempels wünscht, dass Ihr noch einmal zum Bronzedrachenschrein reist.\n\nSobald Ihr dort seid, sollt Ihr das Stundenglas der Ewigkeit auf den Boden stellen und Eurem vergangenen Selbst dabei helfen, es vor den Truppen des ewigen Drachenschwarms zu beschützen.", description = "Da seid Ihr ja! Oder haben wir gerade erst miteinander gesprochen?\n\n<Chromie denkt über die Vielfalt der temporalen Möglichkeiten nach.>\n\nWie dem auch sei, die Ewigen sind hinter Euch her! Nun, an und für sich sind sie nicht hinter Euch her, sondern eher hinter der vergangenen Version von Euch, die einst das Stundenglas der Ewigkeit verteidigte. Ihr könnt Euch noch daran erinnern, oder?\n\nIhr wart das damals, nur seid Ihr es jetzt auch wieder. Halt, das ist nicht so wichtig. Was wichtig ist, ist, dass Ihr zurück zum Bronzedrachenschrein geht und Euch und das Stundenglas vor ihren Angriffen schützt, bevor man Euch aus der Geschichte entfernt!", progress = nil, completion = "Ach du meine Güte, Ihr habt es geschafft! Ich war mir nicht sicher, ob es Euch gelingen würde.\n\nIhr seid während des Kampfes für einen Moment aus dem Zeitfluss verschwunden! Ich habe schon gedacht, wir hätten Euch verloren!\n\nDoch da seid Ihr gesund und munter - Euer vergangenes Selbst auf der anderen Seite der Zeitschleife, in der Ihr feststecktet, gerettet.\n\nIhr seid ein ziemlich temporaler Held, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRune des ZukunftsblicksRune der endlichen VariationenRune der unendlichen Macht\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][13344] = {title = "Keine Wanze", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", description = "Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, <Volk>.\n\nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt unserer Feinde informiert sind.\n\nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", progress = nil, completion = "Gut gemacht, Freund.\n\nDer Bote ist bereits bei der Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13345] = {title = "Brauche mehr Informationen", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen.", description = "Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...\n\nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!\n\nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.", progress = "Habt Ihr herausgefunden, was die Forscher im Schilde führen, <Klasse>?", completion = "Das ist in der Tat alarmierend...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13346] = {title = "Es kann der Böseste nicht in Frieden ruhen...", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar besiegt.", description = "Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!\n\nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.\n\nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.\n\nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.\n\nBeeilt Euch, <Volk>! Vernichtet ihn, bevor er noch mächtiger wird!", progress = nil, completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", rewards = "Polierter ZombievernichterVerkrusteter ZombiefingerBerührung des UnlebensIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13347] = {title = "Wiedergeboren aus der Asche", objective = "Geht zum Schlachtfeld vor Angrathar, der Pforte des Zorns, findet Fordragons Schild und bringt ihn zu König Varian Wrynn nach Burg Sturmwind in Sturmwind.", description = "Unser Schicksal steht schon von Geburt an fest. Bolvars Fall, wenn auch tragisch, war unvermeidlich.\n\nAlles, was Ihr jetzt noch tun könnt, <Name>, ist, Eurem Helden die letzte Ehre zu erweisen. Geht zum Schlachtfeld, holt Euch Bolvars Schild und bringt ihn Eurem König. Übermittelt ihm bei der Übergabe diese Botschaft: \"Nicht alles ist verloren. Aus der Asche der Gefallenen wird eine Macht emporsteigen, die Reiche vereinen und das Böse aus dieser Welt treiben wird.\"\n\nEr darf den Glauben nicht verlieren. Geht jetzt, <Name>. Euer Volk braucht einen Helden - es braucht Euch.", progress = "<König Wrynn wischt sich eine Träne aus dem Gesicht.>\n\n<Er nickt.>\n\nDas ist meine Schuld.", completion = "Die Drachenkönigin hat recht, &lt;Name&gt;. Noch ist nicht alles verloren. Ich werde die Macht sein, die aus der Asche steigt, und ich werde das Böse der Horde aus der Welt schaffen. Der Tod unserer Brüder und Schwestern wird nicht umsonst gewesen sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13348] = {title = "Sinnlosigkeit", objective = "Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", description = "Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.\n\nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.", progress = nil, completion = "Da seid Ihr ja. Gute Arbeit unten im Tal. Das Gemetzel konnte man selbst von hier oben aus verfolgen.\n\nSeid Ihr in Ordnung? Ihr seht aus, als hättet Ihr einen Geist gesehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13349] = {title = "Die Wiege der Frostbrut", objective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.", description = "Wir müssen unseren Vorteil ausnutzen und weitermachen. Lasst uns den Streitkräften der Geißel keine Pause gönnen.\n\nSindragosas Sturz liegt gleich östlich jenseits des Tals der Verlorenen Hoffnung. Der Kult der Verdammten operiert dort unter strenger Aufsicht der untoten Vrykullakaien des Lichkönigs.\n\nEs ist ein Ort großer Macht, möglicherweise ein Friedhof des blauen Drachenschwarms, in dem sie aus den Knochen blauer Drachen die gefürchtete Frostbrut erschaffen.\n\nEin Angriff dort würde es für den Feind erheblich schwieriger machen, an Frostwyrms heranzukommen. Was sagt Ihr dazu, <Name>?", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr ruht Euch besser für eine Weile aus. Ihr seht ein wenig blass aus.", rewards = "Axt des blutbefleckten EisesZorn des VerderbersOpferdolch des NekrolordsBogen des WyrmjägersZerhacker des WiedererweckersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13350] = {title = "Es kann der Böseste nicht in Frieden ruhen...", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar vernichtet.", description = "Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.\n\nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.\n\nKehrt in seine Kammer im Norden von Aldur'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.\n\nEilt Euch, <Volk>! Vernichtet ihn, bevor er noch mächtiger wird!", progress = nil, completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13351] = {title = "Vorschau", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.", description = "Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen - außer, die Allianz mischt sich ein.\n\nAls Nächstes werden wir uns auf Aldur'thar, das Tor der Verwüstung, konzentrieren. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.\n\nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.", progress = nil, completion = "Schön und gut, &lt;Klasse&gt;.\n\nNun, da Ihr mit eigenen Augen gesehen habt, wem wir hier gegenüberstehen, ist es Zeit, an die Arbeit zu gehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13352] = {title = "Gefährliche Gewandung", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", description = "Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.\n\nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, <Klasse>, und wendet sie dann auf einen Unterwerfer an.", progress = nil, completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13353] = {title = "Gefährliche Gewandung", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", description = "Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...\n\nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.", progress = nil, completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13354] = {title = "Befehlskette", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr nach Aldur'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.", description = "Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.\n\nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, <Volk>, ist für den Augenblick gut genug.\n\nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;. Doch brecht Euch beim \"Auf die Schulter klopfen\" nicht den Arm. Sie werden diese Aufseher im Nu ersetzt haben...", rewards = "Brustschutz des KultbrechersKultistengugelJhaeqons TunikaSavryns schlammige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13355] = {title = "Kann nicht reproduziert werden", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Kupferklammer bringt.", description = "Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.\n\nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.\n\nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...\n\nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Kupferklammer.", progress = "Was habt Ihr da, <Volk>?", completion = "&lt;Kupferklammer schüttet den Inhalt des Fläschchens in seinen Partikelanalysierer.&gt;\n\nAhh... ich weiß genau das Richtige!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13356] = {title = "Jetzt neu testen", objective = "Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", description = "Das sollte seinen Zweck erfüllen!\n\nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren Irren-Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.\n\nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", progress = nil, completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", rewards = "Kesselrührstab des KultistenBogen der RückwärtsbewegungZuckender StreitkolbenVerdrehter StraßendiebprüglerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13357] = {title = "Jetzt neu testen", objective = "Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", description = "Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.\n\nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", progress = nil, completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13358] = {title = "Keine Wanze", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", description = "So, <mein Freund/meine Freundin>, es ist an der Zeit eine Wanze zu platzieren.\n\nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.\n\nIm nördlichen Bereich von Aldur'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt den Beschwörungskristall der Kultisten, um unseren kleinen Spion zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Klasse&gt;.\n\nDer Bote hat uns bereits einige wertvolle Informationen zukommen lassen.", rewards = "Mantel des dunklen BotensGillys StrangulierungsstulpenKettenhandschuhe des dämonischen DienersBeinplatten der NordexpeditionEingeweidesprenger von Aldur'tharIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13359] = {title = "Wo Drachen einst fielen", objective = "Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.", description = "Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.\n\nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.", progress = "Habt Ihr den Staub bekommen, <Name>?", completion = "Selbst die mächtigen Wyrm mussten seinem Ruf folgen. Wie könnte ein einfacher Sterblicher wie Ihr ihm widerstehen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSindragosas Erhebung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13360] = {title = "Zeit für Antworten", objective = "Sprecht mit Matthias Lehner im Hof der Knochen.", description = "Ihr habt viele Fragen, <Name>. Ihr seid <der Einzige, der/die Einzige> die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?\n\nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!\n\nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.", progress = nil, completion = "Da seid Ihr ja. Ich habe mich schon gefragt, wann Ihr auftauchen würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13361] = {title = "Der Jäger und der Prinz", objective = "Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.", description = "Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.\n\nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.\n\nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.", progress = "Habt Ihr es gesehen, <Name>? Habt Ihr es gesehen?", completion = "Nach dem Kampf erkannte der Prinz, dass das, was ihn zurückhielt, seine Menschlichkeit war... Er konnte noch immer fühlen... konnte noch immer bluten. Er hatte noch immer ein Herz.\n\nSeine erste Handlung als König war es, sein Herz loszuwerden. Er warf es die Grube hinunter, in der wir uns zum ersten Mal begegneten. Und Ihr, &lt;Name&gt;, wart der Erste, der es seitdem berührt hat.", rewards = "Handschuhe der schmerzhaften RückbesinnungHandschuhe der beunruhigenden ErinnerungGamaschen des WendepunktsBlutbefleckter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13362] = {title = "Wissen ist eine schreckliche Bürde", objective = "Meldet Euch bei Koltira Todesweber an Bord der Orgrims Hammer.", description = "Jetzt wisst Ihr, womit Ihr es zu tun habt, <Name>. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.\n\nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.\n\nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.", progress = nil, completion = "Der Geist eines kleinen Kindes... Das Herz Arthas'... langsam, langsam... In meinem Kopf dreht sich alles.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13363] = {title = "Hilfe vom Argentumkreuzzug", objective = "Sprecht mit Hochlord Tirion Fordring im Kreuzfahrerturm.", description = "Es gab Gerüchte unter den Todesrittern über die Ereignisse, von denen Ihr gesprochen habt. Ich hatte immer gedacht, dass sie etwas... symbolischer gemeint wären.\n\nWir müssen die anderen warnen, aber diskret. Sobald der Lichkönig von unserem Aufbruch erfährt, wird er das Herz an einen anderen Ort bringen lassen - solch eine Chance werden wir nie wieder bekommen.\n\nDie Horde und die Allianz wurden schon zuvor vom Kult der Verdammten infiltriert. Die Schwarze Klinge operiert zu nah an der Geißel.\n\nWir müssen mit Tirion Fordring und seinem Argentumkreuzzug sprechen.", progress = nil, completion = "Harte Worte, &lt;Name&gt;. Hätte jemand anderes das gesagt, hätte ich ihn wahrscheinlich für verrückt erklärt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13364] = {title = "Tirions Schachzug", objective = "Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.", description = "Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.\n\nUnd nun wird mir gesagt, dass es sich hierbei um Arthas' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.\n\nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!\n\nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.", progress = nil, completion = "Ich betrachte das, was wir soeben durchgemacht haben, nicht als Fehlschlag, &lt;Name&gt;... im Gegenteil.\n\nDadurch, dass ich einen Blick in sein Herz werfen konnte, habt Ihr mir erlaubt, das zu bestätigen, was ich wissen musste. Es gibt keinen Arthas Menethil mehr - nur noch den Lichkönig.", rewards = "Klinge der inhaltslosen LeereMesser der matten SeeleHammer des zerrenden WandelsStab des jugendlichen SchmerzesIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13365] = {title = "Keine Wanze", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", description = "Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, <Volk>.\n\nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt des Kultes informiert sind.\n\nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", progress = nil, completion = "Gut gemacht, Freund.\n\nDer Bote ist bereits bei der Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13366] = {title = "Brauche mehr Informationen", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen...", description = "Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...\n\nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!\n\nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.", progress = "Habt Ihr herausgefunden, was die Forscher im Schilde führen, <Klasse>?", completion = "Das ist in der Tat alarmierend...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13367] = {title = "Es kann der Böseste nicht in Frieden ruhen...", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar besiegt.", description = "Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!\n\nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.\n\nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.\n\nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.\n\nBeeilt Euch, <Volk>! Vernichtet ihn, bevor er noch mächtiger wird!", progress = nil, completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", rewards = "Polierter ZombievernichterVerkrusteter ZombiefingerBerührung des UnlebensIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13368] = {title = "Es kann der Böseste nicht in Frieden ruhen...", objective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar tötet.", description = "Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.\n\nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.\n\nKehrt in seine Kammer im Norden von Aldur'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.\n\nEilt Euch, <Volk>! Vernichtet ihn, solange noch Zeit ist!", progress = nil, completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13369] = {title = "Das Schicksal wendet sich gegen Euch", objective = "Steht Lady Jaina Prachtmeer in Orgrimmar zur Seite. Sprecht mit Thrall, dem Kriegshäuptling der Horde in Orgrimmar auf dem Kontinent Kalimdor.", description = "Auf Geheiß von Lady Prachtmeer werde ich eine diplomatische Mission nach Orgrimmar entsenden, um Thrall, dem Kriegshäuptling der Horde, ein paar Fragen zu stellen. Ihr werdet ihr auf dieser Reise zur Seite stehen und dafür sorgen, dass ihr nichts zustößt. Kehrt anschließend mit Nachricht aus Orgrimmar zu mir zurück.\n\nSprecht mit Jaina, wenn Ihr bereit seid zu gehen.", progress = nil, completion = "Die Horde will keinen Krieg, &lt;Volk&gt;. Hört gut zu...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13370] = {title = "Ein königlicher Coup", objective = "Benutzt das Portal in der Feste Grommash, um nach Burg Sturmwind zurückzukehren und Thralls Nachricht an König Varian Wrynn zu übergeben.", description = "Euer Champion Bolvar ist bei der Verteidigung unserer Welt ums Leben gekommen. Die Horde ist vom Verlust eines solch großen Helden schwer getroffen, jedoch war sie für die feigen Angriffe Putress' auf die Pforte des Zorns nicht verantwortlich. Wir haben auch Verluste unter unseren mächtigen Helden zu beklagen aufgrund dieses Verrats.\n\nSagt Eurem König, dass wir alles in unserer Macht Stehende tun werden, um diejenigen, die für diese feige Tat verantwortlich sind, zur Rechenschaft zu ziehen. Wir werden alles tun, um einen Konflikt mit der Allianz zu vermeiden, doch wir werden nicht zögern, uns zu verteidigen, sollte man uns provozieren.", progress = nil, completion = "Sie haben die Unterstadt verloren? Dann ist jetzt der Augenblick gekommen, zuzuschlagen. Wir werden uns Putress höchstpersönlich vorknöpfen und die Ruinen von Lordaeron für die Allianz zurückerobern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13371] = {title = "Es ist Zeit, totzuschlagen", objective = "Benutzt das Portal nach Unterstadt im Inneren von Burg Sturmwind, um Euch nach Unterstadt zu teleportieren. Meldet Euch bei Broll Bärenfell, wenn Ihr am Zielort angekommen seid.", description = "Bevor Ihr nach Orgrimmar aufgebrochen seid, habe ich Broll und Valeera nach Unterstadt entsandt. Um genau zu sein, sind sie gerade am Eingang zur Kanalisation stationiert und erwarten Befehl.\n\nLady Prachtmeer wird außerhalb der Unterstadt ein Portal für unsere Truppen erschaffen. Geht dorthin und meldet Euch bei Broll. Jaina und ich werden dicht hinter Euch sein.", progress = nil, completion = "Wer sollt Ihr sein? Varian hat gesagt, dass er Helden schicken würde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13372] = {title = "Der Schlüssel der fokussierenden Iris", objective = "Liefert den Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.", description = "Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.\n\nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.", progress = "<Name>, Ihr seid mit dem Schlüssel zur fokussierenden Iris in Berührung gekommen! Habt Ihr ihn dabei?\n\n\n\nWie konntet Ihr jemals in seinen Besitz gelangen? Oh, Saphiron hatte seinen Schlüssel noch immer?", completion = "Nur die ältesten Mitglieder des blauen Drachenschwarms sind in Besitz dieser Schlüssel. Malygos, ihr Meister, vertraut sie nur ihnen an.\n\nDas ist die Gelegenheit, auf die wir gewartet haben, um den Aspekt der Magie anzugreifen!&lt;Die Königin der Drachen mustert Euch kurz.&gt;\n\nIhr könnt mit dem Schlüssel, so wie er ist, keinen Zugang zur fokussierenden Iris erhalten, doch ich kann Euch mit einem Teil meiner Macht erfüllen; genug, um damit die Iris einen Spalt zu öffnen.\n\nEs wird genügen, um Malygos Zorn auf Euch zu ziehen.", rewards = "Ihr bekommt:\n\nSchlüssel der fokussierenden Iris"}
MultiLanguageQuestData['de'][13373] = {title = "Vorzüge der Grenzwissenschaft", objective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementhauptmänner und 15 Gargoylewegelagerer tötet.", description = "Ich habe unsere Infragrüntechnologie in die beschlagnahmten Bomber eingebaut - das wird Euch auf eurer ersten Mission in Feindgebiet beschützen! Sprecht mit Rizzy Ratschenwackel, um einen Bomber zu bekommen, und fliegt dann zum Bombardement!\n\nIhr werdet Bomben, Raketen und Schilde haben. Sorgt dafür, dass Eure Schilde aufgeladen bleiben, und werft die Bomben auf die Diener der Geißel im Bombardement ab. Kommt zurück, nachdem Ihr Eure Ziele getroffen habt, und es wird Euch noch mehr Arbeit erwarten.", progress = "Ihr habt Eure Trefferquote noch nicht erfüllt, <Name>. Sind die Bomber zu schwer zu fliegen?", completion = "Ha, Ihr habt sie erwischt! Wie hat Euch der Bomber gefallen? Ich hoffe, dass Ihr den Dreh raus habt, denn ich habe noch mehr Missionen für Euch...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13374] = {title = "Bereit zur Revolte!", objective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.", description = "<Name>, nur unsere besten Piloten bekommen eine Mission wie diese. Eine Mission, bei der es sehr tief in Feindgebiet geht und bei der Ihr nur von Infragrüntechnologie beschützt werdet!\n\nBeantragt einen weiteren Bomber von Rizzel und fliegt mit ihm dieses Mal durch das Tal der Verlorenen Hoffnung. Bei dieser Mission habt Ihr Boden- und Luftziele - haltet also die Augen auf und sorgt dafür, dass Eure Schilde aufgeladen bleiben!\n\nViel Glück!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13375] = {title = "Der heroische Schlüssel der fokussierenden Iris", objective = "Liefert den heroischen Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.", description = "Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.\n\nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.", progress = "<Name>, Ihr seid mit dem Schlüssel zur Iris in Berührung gekommen! Habt Ihr ihn dabei?\n\n\n\nWie konntet Ihr jemals in seinen Besitz gelangen? Oh, Saphiron hatte seinen Schlüssel noch immer?", completion = "Nur die ältesten Mitglieder des blauen Drachenschwarms sind in Besitz dieser Schlüssel. Malygos, ihr Meister, vertraut sie nur ihnen an.\n\nDas ist die Gelegenheit, auf die wir gewartet haben, um den Aspekt der Magie anzugreifen!&lt;Die Königin der Drachen mustert Euch kurz.&gt;\n\nIhr könnt mit dem Schlüssel, so wie er ist, keinen Zugang zur fokussierenden Iris erhalten, doch ich kann Euch mit einem Teil meiner Macht erfüllen; genug, um damit die Iris einen Spalt zu öffnen.\n\nEs wird genügen, um Malygos Zorn auf Euch zu ziehen.", rewards = "Ihr bekommt:\n\nHeroischer Schlüssel der fokussierenden Iris"}
MultiLanguageQuestData['de'][13376] = {title = "Totale Vernichtung: Das Tal der Verlorenen Hoffnung!", objective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.", description = "<Name>, der Kampf geht weiter. Zu unserem Glück haben wir uns mit Bomben und Raketen eingedeckt! Zeit für eine weitere Bombenmission - diese hier ist eine längere: Es geht über das Bombardement hinweg und zum Tal der Verlorenen Hoffnung. Setzt Euch wieder in einen Infragrünbomber, fliegt hinaus und verarbeitet die Diener der Geißel in kleine Geißelstückchen!", progress = "Worauf wartet Ihr? Wir haben das Material und den Befehl... wir brauchen nur mutige Schützen wie Euch, um sie einzusetzen.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Während Ihr dort draußen wart, habe ich andere Schützen über Euch reden hören... Denke, dass Ihr eine echte Zukunft als Angriffsflieger habt!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13377] = {title = "Die Schlacht um Unterstadt", objective = "Helft König Varian Wrynn und Lady Jaina Prachtmeer, Großapotheker Putress zur Rechenschaft zu ziehen! Meldet Euch bei König Varian Wrynn, solltet Ihr erfolgreich sein.", description = "Tief im Inneren von Unterstadt versteckt er sich: der Meuchelmörder, der für den Tod Bolvars und den Tod unserer mutigen Soldaten an der Pforte des Zorns verantwortlich ist.\n\nVarian hat die geballte Macht der Allianz mitgebracht, um dabei zu helfen, die Stadt auseinanderzunehmen. Schließt Euch ihm und Lady Prachtmeer auf ihrer Jagd an und verdient Euch Euren Platz unter den größten Champions der Allianz!\n\nSprecht mit König Varian Wrynn, wenn Ihr bereit seid.", progress = nil, completion = "Schon viel zu lange ist die Horde unbehelligt geblieben. Wir haben ihre Gebiete gedeihen lassen und als Gegenleistung für unsere Großzügigkeit haben sie daran gearbeitet, unseren Untergang herbeizurufen.\n\nFrieden? Zwecklos... nichts hat er uns gebracht. Wir haben einige unserer größten Helden an den \"Frieden\" verloren. Sehen wir einmal, was die Schlacht uns bringen wird...\n\nKehrt nach Nordend zurück, &lt;Name&gt;. Erobert es für Euren König - FÜR DIE ALLIANZ!", rewards = "Voraussichtsgamaschen des KönigsEhrengamaschen des KönigsWeisheitsgamaschen des KönigsBrutalitätsbeinschützer des KönigsHeldentumbeinschützer des KönigsBlutbadbeinplatten des KönigsIhr bekommt:\n\nMedaillon des Heldentums"}
MultiLanguageQuestData['de'][13378] = {title = "Chefingenieur Kupferklammer", objective = "Sprecht mit Chefingenieur Kupferklammer.Sprecht mit Chefingenieur Kupferklammer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Sprecht mit Chefingenieur Kupferklammer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13379] = {title = "Grüne Technologie", objective = "Sprecht mit Grenzwissenschaftsingenieurin Tezzla.", description = "Tezzla ist diejenige, nach der Ihr sucht, genau... sie beherrscht nun eine neue Wellenlänge namens Infragrün und hält sich damit in der Nähe der Geißel versteckt! Nahe genug, um Bomben auf sie abzuwerfen!\n\nIch werde Euch Infragrünsicht verleihen, damit Ihr sie sehen könnt. Sie befindet sich über Aldur'thar, dem Tor der Verwüstung. Geht, los, geht... ich weiß, dass sie Arbeit für mutige Helden hat, die scharf darauf sind, in die Luft zu fliegen! Äh, ich meine: die scharf darauf sind, die Geißel in die Luft fliegen zu lassen!\n\nUnd <Name>, die Allianz hat unsere Technologie gestohlen und ihren eigenen versteckten Flugplatz in der Nähe errichtet. Haltet Euch von der Plattform mit den Bannern der Allianz fern!", progress = nil, completion = "Ja, ja! Ihr habt mich gefunden! Und gerade rechtzeitig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13380] = {title = "Den Angriff leiten", objective = "Kibli Killohertz möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementkapitäne und 15 Gargoylewegelagerer tötet.", description = "Infragrüntechnologie ermöglicht es uns, hier versteckt zu bleiben - direkt unter der Nase der Geißel! Außerdem haben wir spezielle Bomber mit Infragrüntechnologie ausgerüstet... doch nicht um sie zu tarnen, nein! Wir benutzen die Technologie, um sie zu schützen!\n\nSprecht mit Karen Nein und fordert einen Bomber an. Fliegt mit ihm zum Bombardement... benutzt seine Schilde und sein Geschütz, um Euch zu schützen, und seinen Bombenwerfer, um die Ziele der Geißel zu treffen. Trainiert gut, kommt dann wieder zu mir zurück und ich werde eine noch wichtigere Mission für Euch haben!", progress = "<Name>, die Bomber sind schwierig zu fliegen, doch Ihr müsst sie beherrschen, wenn wir unseren Kampf gegen die Geißel gewinnen wollen.", completion = "Ich konnte die Explosionen von hier aus hören, &lt;Name&gt;. Haben die Schilde gut funktioniert? Haben sie Euren Bomber intakt gehalten?\n\nIch hoffe, dass dem so ist, weil ich jetzt noch mehr Missionen für Euch habe...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13381] = {title = "Watt ist mein Ziel", objective = "Kibli Killohertz wünscht, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.", description = "Zieht Euch warm an, <Name>, und fangt an zu beten. Diese nächste Mission wird Euren Verstand und Eure innere Stärke auf die Probe stellen wie ein Besuch der Schwiegereltern!\n\nFordert einen weiteren Bomber von Karen Nein an. Fliegt mit ihm über das Bombardement und das Tal der Verlorenen Hoffnung hinweg. Diesmal habt Ihr mehr Ziele, am Boden und in der Luft. Sorgt dafür, dass Euer Schutzschild und Eure Munition geladen ist, <Name>! Ich werde Euch wiedertreffen, wenn die Sache vorbei ist.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13382] = {title = "Mission mit Hertz: Das Tal der Verlorenen Hoffnung", objective = "Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.", description = "Der Kampf geht weiter! Eure neuen Befehle sind hier. Es handelt sich um eine Langstreckenbombenmission zum Bombardement und zum Tal der Verlorenen Hoffnung. Fragt Karen nach einem Bomber und macht der Geißel mit Euren Bomben und Raketen die Hölle heiß!", progress = "Einfach draufhalten, <Name>. Der Luftkampf wird sich nicht von alleine gewinnen lassen!", completion = "Willkommen zurück, &lt;Name&gt;. Wie war die Schlacht? Aufregend? Ruht Euch erst einmal aus. Doch kommt wieder zurück, wenn Ihr neue Befehle habt.\n\nFür die Allianz!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13383] = {title = "Killohertz", objective = "Chefingenieur Bolzenschlüssel möchte, dass Ihr zum verborgenen Allianzflugplatz über Aldur'thar, dem Tor der Verwüstung, fliegt und Kibli Killohertz aufsucht.", description = "Die Goblins hatten Glück: Sie haben eine neue Energie gefunden. Sie nennen sie Infragrün und ich soll ein einäugiger Oger sein, wenn diese Psychopathen damit keinen grünen Volltreffer gelandet haben.\n\nGeht und sucht nach Kibli Killohertz. Er befindet sich auf einem kleinen, versteckten Flugplatz der Allianz über Aldur'thar, dem Tor der Verwüstung, und ist dort für die umgekehrten Ingenieursbestrebungen in Bezug auf die Infragrüntechnologie zuständig. Ich werde Euch Infragrünsicht geben, damit Ihr ihn finden könnt. Geht zur Kuppel, auf der unsere Banner der Allianz wehen. Falls Ihr in der Nähe des Flugplatzes der Horde herumfliegen solltet, dann seid Ihr in jeder Menge grünen Schwierigkeiten.", progress = nil, completion = "Ja, ja, ja! So gut, Euch zu sehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13384] = {title = "Entscheidung im Auge der Ewigkeit", objective = "Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.\n\nDiese Quest ist für den normalen Modus, also für die 10-Mann-Version des Auges der Ewigkeit, gedacht.", description = "Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.\n\nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.\n\n<Krasus klingt sehr betroffen, als er diese letzten Worte ausspricht.>\n\n<Name>, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.", progress = "Malygos und nur Malygos allein trägt das Herz der Magie bei sich. Es ist sein kostbarster Besitz.", completion = "Dies ist ein sehr trauriger Tag, nicht nur für uns Drachen, sondern für alle lebendigen Wesen Azeroths. Wir haben einen unserer nachdenklichsten, intelligentesten und ältesten Freunde verloren. Die Magie hat ihren Wächter verloren.\n\nLasst uns hoffen, dass sich dies in den kommenden Jahren als weise Entscheidung herausstellen wird, &lt;Name&gt;. Am Horizont braut sich noch immer ein Sturm zusammen und uns fehlt einer unserer mächtigsten Verteidiger.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKette des uralten WyrmsHalsreif des roten DrachenschwarmsAnhänger des DrachenverschworenenDrachenschuppenkragen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13385] = {title = "Heroische Entscheidung im Auge der Ewigkeit", objective = "Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.\n\nDiese Quest kann sowohl in der 10-Mann-Version als auch in der 25-Mann-Version des Auges der Ewigkeit abgeschlossen werden.", description = "Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.\n\nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.\n\n<Krasus klingt sehr betroffen, als er diese letzten Worte ausspricht.>\n\n<Name>, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.", progress = "Malygos und nur Malygos allein trägt das Herz der Magie bei sich. Es ist sein kostbarster Besitz.", completion = "Dies ist ein sehr trauriger Tag, nicht nur für uns Drachen, sondern für alle lebendigen Wesen Azeroths. Wir haben einen unserer nachdenklichsten, intelligentesten und ältesten Freunde verloren. Die Magie hat ihren Wächter verloren.\n\nLasst uns hoffen, dass sich dies in den kommenden Jahren als weise Entscheidung herausstellen wird, &lt;Name&gt;. Am Horizont braut sich noch immer ein Sturm zusammen und uns fehlt einer unserer mächtigsten Verteidiger.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWyrmruhhalskette der MachtMedaillon der LebensbinderinGunst der DrachenköniginPerlen des Nexuskriegchampions\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13386] = {title = "Ausnutzen einer Öffnung", objective = "Redet mit Hauptmann Kendall unterhalb der Eiskronenzitadelle.", description = "Ich habe eine interessante Aufgabe für Euch, <Name>. Allerdings nur, wenn Ihr auf eine Herausforderung aus seid.\n\nWir haben von einer Öffnung unterhalb der Eiskronenzitadelle gehört. Unsere Ingenieure haben sie studiert und gehen davon aus, dass sie eine strukturelle Schwäche darstellt.\n\nWir haben ein paar Männer mit einer \"geborgten\" Ladung Saronitbomben dorthin entsandt. Sie stehen unter dem Kommando von Hauptmann Kendall.\n\nMit ein bisschen Hilfe könnten wir den Streitkräften der Geißel einen ordentlichen Schlag verpassen. Was sagt Ihr, <Name>?", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Thassarian sagte schon, dass Ihr kommen würdet. Jeder Freund von Thassarian ist auch mein Freund. Zumindest jeder lebende Freund... er umgibt sich mitunter mit seltsamer Gesellschaft.", rewards = "Ihr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13387] = {title = "Sicherung des Gebiets", objective = "Kapitän Kendall bei der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.", description = "Die Saronitbomben sind platziert, <Name>. Wir haben aber nur einen Versuch, also muss es unbedingt funktionieren.\n\nWir müssen für eine Weile die Kontrolle über das Gebiet haben, um eine sichere Detonation garantieren zu können. Lasst uns versuchen, die Anzahl der Geißel ein wenig zu reduzieren.", progress = "Für die Allianz!", completion = "Ihr seid so gut, wie Thassarian gesagt hat. Gute Arbeit!", rewards = "Stoßfester KopfschutzTunika des bulligen SchreckensHandschuhe des verrückten BombersKrallenschuhe der EiswandlerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13388] = {title = "Lasst sie hochgehen!", objective = "Hauptmann Kendall unterhalb der Eiskronenzitadelle möchte, dass Ihr die Lunte an dem nahegelegenen Saronitbombenstapel anzündet.", description = "Das sieht doch schon mal alles recht gut aus. Also, gehen wir's an!\n\nDer Bombenstapel befindet sich gleich in der Nähe der Grube. Ich werde beginnen, die Männer zu evakuieren.", progress = nil, completion = "Diese Bomben sehen ziemlich durchschlagskräftig aus. Sie sollten zumindest eine ordentliche Delle in die umgebende Struktur machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13389] = {title = "Eine kurze Lunte", objective = "Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.", description = "Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.\n\nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.", progress = nil, completion = "Dieses pulsierende Objekt ist von einer dicken Eisschicht umgeben. Es schimmert geheimnisvoll unter Wasser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13390] = {title = "Eine Stimme im Dunklen", objective = "Untersucht die nahe Stimme in Naz'anak, den Vergessenen Tiefen.", description = "Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.\n\nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.\n\nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.\n\n\"Das hättet Ihr nicht tun sollen.\"", progress = nil, completion = "Ich sah, wie er es weggeworfen hat, wisst Ihr? Er hat es ganz bis hier herunter geworfen.\n\nSagte, er bräuchte es nicht mehr. Sagte, es würde ihn schwach machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13391] = {title = "Zeit zum Verstecken", objective = "Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.", description = "Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.\n\nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.\n\nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.", progress = "Habt Ihr das Blut?", completion = "Worauf wartet Ihr dann noch? Ihr müsst Euch damit einreiben!\n\nSchnell! Oder er wird Euch sehen!", rewards = "GeißelhammerStumpfer GehirnwäscherMesser des PilotenStreitkolben des letzten BefehlsBlutbrief des RitualistenRuhm des SchützenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13392] = {title = "Rückkehr an die Oberfläche", objective = "Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", description = "Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.\n\nWir werden uns wiedersehen. Er wird nach Euch suchen.\n\nEs ist nur eine Frage der Zeit, bis er Euch findet.", progress = nil, completion = "Ihr seid es, &lt;Name&gt;! Wir dachten schon, es hätte Euch erwischt.\n\nEure Explosion hat der Geißel ganz schön wehgetan. Und dabei fast noch Hauptmann Kendalls Augenbrauen weggesengt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13393] = {title = "Feldreparaturen", objective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken sammelt und sie zu dem defekten Verwüster im Tal der Verlorenen Hoffnung bringt.", description = "Alles klar. Lasst uns aber nicht zu früh feiern. Wir müssen aus dem Vorteil, den wir mit unserer kleinen Bombardierung errungen haben, Kapital schlagen.\n\nWir haben ein funktionierendes Katapult der Verwüster-Klasse von der Horde auf dem Feld unten entdeckt. Die Spuke scheinen es auseinanderzunehmen.\n\nWenn Ihr es wieder zusammensetzen könntet, wären wir in der Lage, den Armeen der Geißel im Tal ernstlichen Schaden zuzufügen.\n\nKlar, Ihr werdet ziemlich in der Unterzahl sein, aber ich setze großes Vertrauen in Euch.", progress = "Der Verwüster wurde stark beschädigt.", completion = "Der Verwüster hat schon bessere Tage gesehen, aber die Struktur hat keinen dauerhaften Schaden genommen. Die Ersatzteile, die Ihr gebracht habt, sollten ausreichen, um ihn zumindest vorübergehend wieder ans Laufen zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13394] = {title = "Tut Euer Schlechtestes", objective = "Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.", description = "Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.\n\nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.\n\nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.", progress = "Habt Ihr genug mit Euren Kriegsmaschinen gespielt?", completion = "Seht Ihr? Ihr habt Euren gerechten Anteil zwar getötet, doch für jeden Einzelnen, den Ihr vernichtet habt, kam ein weiterer aus der Erde, um dessen Platz einzunehmen.\n\nIhr wisst nicht, wem Ihr hier gegenübersteht, &lt;Name&gt;. Lasst es mich Euch zeigen.", rewards = "Handschutz des VerwüstersStaubmantel des VerwüsterfahrersZahnriemen des runderneuerten VerwüstersBeschleunigerstampferKettengamaschen des AntriebsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13395] = {title = "Armee der Verdammten", objective = "Matthias Lehner beim Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern aufstellt.", description = "Ihr meint wohl, Ihr seid ziemlich stark... diese Untoten zu bekämpfen und ihre Knochen mit Euren Kriegsmaschinen zu zerquetschen.\n\nDas ist aber noch gar nichts, verglichen mit der Stärke, derer es bedarf, um sie zu erschaffen.\n\nIch habe selbst gesehen, wie der Prinz es gemacht hat. Ich kann Euch zeigen, wie das geschehen ist... wenn Ihr wollt.", progress = nil, completion = "Die wahre Stärke des Prinzen lag nicht darin, Armeen aus Leichen zu erschaffen... das war leicht.\n\nAber seine eigenen Männer zu töten, mit denen er in vielen Schlachten Seite an Seite gefochten hatte... die wahre Stärke des Prinzen war seine Fähigkeit, zu tun, was getan werden musste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13396] = {title = "Sinnlosigkeit", objective = "Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", description = "Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.\n\nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.", progress = nil, completion = "Gut geschossen, &lt;Name&gt;. Die Geißel hatte keine Chance.\n\nGeht es Euch gut? Ihr seht aus, als hättet ihr einen Geist gesehen. Naja, wenn ich so darüber nachdenke, wäre das in diesen Gegenden kein wirklich unüblicher Anblick.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13397] = {title = "Sindragosas Sturz", objective = "Thassarian an Bord Himmelsbrecher möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.", description = "Ihr seid ein echter Star, <Name>. Wisst Ihr, wenn ich einem der anderen Soldaten einen Auftrag erteile, stehen die Chancen, dass er ihn erfolgreich ausführt, etwa fünfzig zu fünfzig. Die Chancen, dass er lebend zurückkommt... nun, unwesentlich schlechter.\n\nAber bei Euch ist die Sache stets geritzt. Zuverlässig wie ein gnomisches Uhrwerk!\n\nWie dem auch sei, ich habe noch einen für Euch. Sindragosas Sturz, im Osten des Tals. Dort gehen verstärkte Aktivitäten der Kultisten vor sich, inklusive und sich nicht beschränkend auf die Erschaffung von Frostwyrms. Ich brauche Euch, um denen mal ordentlich die Zähne einzutreten.\n\nIch hasse Kultisten.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Neben Euch verblasst der Rest von uns!", rewards = "Axt des blutbefleckten EisesZorn des VerderbersOpferdolch des NekrolordsBogen des WyrmjägersZerhacker des WiedererweckersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13398] = {title = "Wo Drachen einst fielen", objective = "Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.", description = "Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.\n\nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.", progress = "Habt Ihr den Staub bekommen, <Name>?", completion = "Selbst die mächtigen Wyrm mussten seinem Ruf folgen. Wie könnte ein einfacher Sterblicher wie Ihr ihm widerstehen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSindragosas Erhebung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13399] = {title = "Zeit für Antworten", objective = "Sprecht mit Matthias Lehner im Hof der Knochen.", description = "Ihr habt viele Fragen, <Name>. Ihr seid <der Einzige, der/die Einzige> die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?\n\nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!\n\nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.", progress = nil, completion = "Da seid Ihr ja. Ich habe mich schon gefragt, wann Ihr auftauchen würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13400] = {title = "Der Jäger und der Prinz", objective = "Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.", description = "Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.\n\nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.\n\nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.", progress = "Habt Ihr es gesehen, <Name>? Habt Ihr es gesehen?", completion = "Nach dem Kampf erkannte der Prinz, dass das, was ihn zurückhielt, seine Menschlichkeit war... Er konnte noch immer fühlen... konnte noch immer bluten. Er hatte noch immer ein Herz.\n\nSeine erste Handlung als König war es, sein Herz loszuwerden. Er warf es die Grube hinunter, in der wir uns zum ersten Mal begegneten. Und Ihr, &lt;Name&gt;, wart der Erste, der es seitdem berührt hat.", rewards = "Handschuhe der schmerzhaften RückbesinnungHandschuhe der beunruhigenden ErinnerungGamaschen des WendepunktsBlutbefleckter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13401] = {title = "Wissen ist eine schreckliche Bürde", objective = "Meldet Euch bei Thassarian an Bord der Himmelsbrecher.", description = "Jetzt wisst Ihr, womit Ihr es zu tun habt, <Name>. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.\n\nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.\n\nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.", progress = nil, completion = "Immer langsam, &lt;Name&gt;. Wieso fangt Ihr nicht einfach noch mal von vorne an... von ganz vorne.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13402] = {title = "Tirions Hilfe", objective = "Sprecht mit Hochlord Tirion Fordring auf dem Kreuzfahrerturm.", description = "Es ist nicht das erste Mal, dass ich die Geschichte über Arthas und sein Herz gehört habe... habe immer gedacht, dass es eine erfundene Geschichte für gewöhnliche Soldaten wäre.\n\nWir müssen umgehend danach handeln. Leider müssen wir das Ganze geheim halten.\n\nArthas' Agenten sind überall und wenn er es herausfindet, wäre unser Plan zunichte.\n\nWir müssen dies zum Argentumkreuzzug bringen. Jeder einzelne Paladin in dem Orden wurde von Tirion höchstpersönlich erlesen. Wenn irgendwer noch nicht von den Kultisten infiltriert wurde, dann sind es diese Jungs.", progress = nil, completion = "Harte Worte, &lt;Name&gt;. Hätte jemand anderes das gesagt, hätte ich ihn wahrscheinlich für verrückt erklärt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13403] = {title = "Tirions Schachzug", objective = "Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.", description = "Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.\n\nUnd nun wird mir gesagt, dass es sich hierbei um Arthas' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.\n\nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!\n\nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.", progress = nil, completion = "Ich betrachte das, was wir soeben durchgemacht haben, nicht als Fehlschlag, &lt;Name&gt;... im Gegenteil.\n\nDadurch, dass ich einen Blick in sein Herz werfen konnte, habt Ihr mir erlaubt, das zu bestätigen, was ich wissen musste. Es gibt keinen Arthas Menethil mehr - nur noch den Lichkönig.", rewards = "Klinge der inhaltslosen LeereMesser der matten SeeleHammer des zerrenden WandelsStab des jugendlichen SchmerzesIhr bekommt:\n\nEmblem des Heldentums"}
MultiLanguageQuestData['de'][13404] = {title = "Statische Schocktruppen: das Bombardement", objective = "Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementkapitäne und 20 Gargoylewegelagerer tötet.", description = "Dies wird ein Kurzstreckeneinsatz, über das Bombardement. Gut zum warm werden. Bereit?", progress = "Bleibt dran, <Name>. Der Luftkrieg gewinnt sich nicht von selbst!", completion = "Willkommen zurück, &lt;Name&gt;. Eine kurze Mission, aber belebend, was? Macht erstmal 'ne Pause. Aber kommt zurück, sobald Ihr neue Befehle habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13405] = {title = "Ruf zu den Waffen: Strand der Uralten", objective = "Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wir kämpfen in Nordend nicht nur gegen die Armeen des Lichkönigs, sondern auch gegen die Armeen der Horde.\n\nAuf dem Strand der Uralten wurde ein mächtiges Titanenrelikt gefunden. Wie Ihr vielleicht schon wisst, sind wir Zwerge seit Jahren Hüter solcher Artefakte gewesen und sind deswegen auch ihre rechtmäßigen Besitzer.\n\nIn diesem Fall ist die Horde sehr scharf darauf, das Relikt aus den Titanenruinen zu klauen. Sie werden es sicherlich als Waffe gegen uns einsetzen - wir müssen sie also um jeden Preis aufhalten.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Mit Eurer Hilfe wird der komplette Strand der Uralten der Allianz zufallen.", rewards = "Ihr bekommt:\n\nEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][13406] = {title = "Auf derselben Wellenlänge: Das Bombardement", objective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementhauptmänner und 20 Gargoylewegelagerer tötet.", description = "Bereit, Euch mit einer kurzen Bombenmission aufzuwärmen? Ihr habt Eure Befehle und wir unsere Bomber - bestückt und bereit.", progress = "Ihr habt Eure Trefferquote noch nicht erfüllt, <Name>. Los, raus da mit Euch und jagt etwas in die Luft!", completion = "Ha, Ihr habt sie erwischt! Ich konnte hören, wie einzelnen Körperteile der Geißel die Bergwand herunterrasselten. Gute Arbeit. Wir werden schon bald noch mehr für Euch haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission beendet\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13407] = {title = "Ruf zu den Waffen: Strand der Uralten", objective = "Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Nur weil wir in Nordend einmarschieren, um die Geißel zu vernichten, muss das noch lange nicht heißen, dass wir der Allianz eine Pause gönnen.\n\nDie Zwerge von der Forscherliga haben ein mächtiges Titanenrelikt gefunden und der Blitz soll uns treffen, wenn wir es einfach der Allianz überlassen.\n\nGeht, <Name>, und vernichtet unsere Feinde. Sie sollen wissen, dass, egal wo wir uns auch begegnen, sie weiterhin unsere Todfeinde sind.", progress = nil, completion = "Ihr macht uns große Ehre, &lt;Name&gt;! Die Schwächlinge der Allianz müssen unter dem Stiefel der mächtigen Horde zerquetscht werden!", rewards = "Ihr bekommt:\n\nEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][13408] = {title = "Höllenfeuerbefestigungen", objective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, <Name>, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", rewards = "Ihr bekommt:\n\nInsigne der AllianzAbzeichen der Ehrenfeste"}
MultiLanguageQuestData['de'][13409] = {title = "Höllenfeuerbefestigungen", objective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", rewards = "Ihr bekommt:\n\nInsigne der HordeAbzeichen von Thrallmar"}
MultiLanguageQuestData['de'][13410] = {title = "Höllenfeuerbefestigungen", objective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, <Name>, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", rewards = "Ihr bekommt:\n\nAbzeichen der Ehrenfeste"}
MultiLanguageQuestData['de'][13411] = {title = "Höllenfeuerbefestigungen", objective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", progress = "Kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gute Arbeit, &lt;Name&gt;. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", rewards = "Ihr bekommt:\n\nAbzeichen von Thrallmar"}
MultiLanguageQuestData['de'][13412] = {title = "Corastrasza", objective = "Bibliothekarin Serrah möchte, dass Ihr mit Corastrasza in Kaltarra sprecht.", description = "Grüße, <Klasse>. Dürfte ich Euch um einen Gefallen bitten?\n\nCorastrasza ist die Schwester von Raelorasz - dem roten Drachen, der hier in unserem Außenposten das Sagen hat. Sie ist gegen seinen Willen zu einem der oberen Nexusringe geflogen, um ein paar blaue Drachen, die über fürchterliche Macht verfügen, zu beobachten.\n\nEr macht sich um sie Sorgen, obwohl er es nie zugeben wird, und würde jegliche Neuigkeiten über ihr Wohlergehen begrüßen.\n\nSeid so gut und sucht sie auf. Bittet sie, ihren Stolz beiseite zu legen und ihrem Bruder eine Nachricht zu schicken.", progress = nil, completion = "Es ist ziemlich anmaßend, Euch in die persönlichen Angelegenheiten eines Drachen einzumischen, meint Ihr nicht, &lt;Volk&gt;?\n\nDoch abgesehen davon, wäre es nicht richtig, meinem Bruder vorzuenthalten, dass es mir gut geht. Ihr könnt Eurer aufdringlichen Freundin sagen, dass ich meinen Bruder über das, was ich mache, auf dem Laufenden halten werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13413] = {title = "Schlacht in den Wolken", objective = "Corastrasza auf dem oberen Ring des Nexus in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.", description = "Ihr besitzt den Mut, Euch so nah an Malygos' Hort heranzuwagen, <Sterblicher/Sterbliche>? Oder ist es einfach nur Ignoranz? Bald werden wir es wissen...\n\nIch bin ein erfahrener Ausbilder der anmutigen Drachen des roten Drachenschwarms. Meine Aufgabe hier ist es, den Feind zu studieren und meinen kostbaren Begleitern die Taktiken beizubringen, die sich am effektivsten gegen den Meister der Blauen erweisen werden.\n\nDamit Ihr zeigen könnt, ob Ihr die Nerven und das Können besitzt, werde ich Euch erlauben, auf einem meiner Drachen in den Kampf gegen die Untergebenen des Feindes zu reiten.\n\nDie Möglichkeit besteht - Ihr müsst nur danach fragen...", progress = "Tja, Sterblicher, was haltet Ihr von meinen Begleitern?", completion = "Mein Drache sagt mir, dass Ihr es mit ein wenig Übung zu einem fähigen Kämpfer machen könntet.\n\nNun gut. Im Interesse unseres Krieges mit Malygos werde ich Euch erlauben, nach Belieben mit einem meiner Begleiter zu trainieren.\n\nBereitet Euch vor, &lt;Volk&gt;, denn er ist ein heftiger und gnadenloser Gegner.", rewards = "AngriffshalsbergeÜbergriffgewänderWeste des AngreifersBelagernde BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13414] = {title = "Schlacht in den Wolken", objective = "Corastrasza auf dem oberen Ring des Nexus in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.", description = "So sehen wir uns wieder, <Volk>. Ich muss zugeben, dass Ihr mir langsam ans Herz wachst.\n\nLiege ich richtig in der Annahme, dass Ihr gekommen seid, um Eure Luftkampffertigkeiten zu verbessern?\n\nMeine Begleiter stehen wie immer bereit, Ihr zerstörerisches Feuer über den Feind zu ergießen.\n\nSprecht nur ein Wort und sie werden Euch zur Verfügung stehen.", progress = "Ja, <Volk>?", completion = "Ich habe heute eine leichte Steigerung bemerkt, &lt;Klasse&gt;. Es gab Momente, in denen es so schien, als wäret Ihr eins mit dem Drachen.\n\nIhr könnt gerne nach Eurem Belieben mit meinen kostbaren Begleitern trainieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13415] = {title = "Die Bibliothekenkonsole", objective = "Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.", description = "Norgannons Schale liegt in Reichweite, <Name>. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!\n\nJedenfalls sollt Ihr die Scheibe dazu benutzen, um die Schale zu besorgen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.", progress = "Auf der Konsole befindet sich eine Öffnung, die anscheinend für die Scheibe des Erfinders gedacht ist.", completion = "&lt;Ihr schiebt die Scheibe in die Konsole. Plötzlich erscheinen Lichter auf deren Oberfläche und eine mechanische Stimme sagt:&gt;\n\nScheibe des Erfinders bestätigt. Willkommen zurück, Hüter Mimir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13416] = {title = "Die Bibliothekenkonsole", objective = "Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.", description = "Norgannons Schale liegt in Reichweite, <Name>. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!\n\nJedenfalls sollt Ihr die Scheibe zur Konsole bringen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.", progress = "Auf der Konsole befindet sich eine Öffnung, die anscheinend für die Scheibe des Erfinders gedacht ist.", completion = "&lt;Ihr schiebt die Scheibe in die Konsole. Plötzlich erscheinen Lichter auf deren Oberfläche und eine mechanische Stimme sagt:&gt;\n\nScheibe des Erfinders bestätigt. Willkommen zurück, Hüter Mimir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13417] = {title = "Die Gebrüder Bronzebart", objective = "Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung.", description = "Das war's! Wir haben endlich den Schlüsselstein... Er ist schön! Ich bin schon mehr als einmal um die ganze Welt gereist, aber wegen diesem Ding war ich wieder so aufgeregt wie ein kleines Kind. Allerdings dürfte jetzt wohl nicht der richtige Zeitpunkt sein, um durchzuatmen und den Stein zu bewundern. Wir müssen von hier verschwinden.\n\nSteigt auf meine Flugmaschine und sorgt für Deckung, damit wir bei unserer Flucht vor diesen Eisenzwergen geschützt sind!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing der NordwindeGezacktes EisbandBernsteinglutsiegelEisgeschmiedeter Kampfring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13418] = {title = "Kriegsvorbereitung", objective = "Sprecht mit Offizier Van Rossem, um Euch sicher zur Himmelsbrecher in Eiskrone bringen zu lassen, und meldet Euch dann bei Stabshauptmann Justin Bartlett.", description = "Ihr da!\n\nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.\n\nIhr habt vielleicht die Gerüchte über unseren fehlgeschlagenen Bodenangriff auf den Gletscher gehört, doch lasst mich Euch beruhigen. Wir führen unseren Angriff jetzt von einem der fortgeschrittensten Gefährte aus, die es in Azeroth gibt: die Himmelsbrecher. Die Horde hat keine Chance und auch Arthas nicht.\n\nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen.", progress = nil, completion = "Willkommen auf der Himmelsbrecher.\n\nVon hier aus werden wir die Vorarbeit für unseren Angriff auf Arthas leisten. Es gibt noch viel zu tun, doch bevor wir uns ins eigentliche Getümmel stürzen können, wollen wir sichergehen, dass der Argentumkreuzzug ausreichend Verstärkung erhalten hat - wir werden später ihre Hilfe benötigen.\n\nSprecht mit Absalan dem Frommen auf dem Hauptdeck, wenn Ihr das nicht schon getan habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13419] = {title = "Kriegsvorbereitung", objective = "Sprecht mit Himmelshäscher Klum, um Euch sicher zur Orgrims Hammer in Eiskrone bringen zu lassen, und meldet Euch dann bei Himmelshäscher Korm Schwarznarbe.", description = "Ihr da!\n\nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.\n\nDie Hunde von der Allianz sind vor uns nach Eiskrone geeilt, unvorbereitet, und haben für ihre Ungeduld genau das bekommen, was sie verdienen. Wir haben uns Zeit gelassen, haben uns vorbereitet und schon bald werden wir den echten Angriff starten - von einem der fortgeschrittensten Gefährte in ganz Azeroth aus: der Orgrims Hammer. Die Allianz hat keine Chance und auch Arthas nicht.\n\nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen und zu helfen.", progress = nil, completion = "Willkommen auf der Orgrims Hammer.\n\nVon hier aus werden wir die Vorarbeit für unseren Angriff auf Arthas leisten. Es gibt noch viel zu tun, doch bevor wir uns ins eigentliche Getümmel stürzen können, wollen wir sichergehen, dass der Argentumkreuzzug ausreichend Verstärkung erhalten hat - wir werden später ihre Hilfe benötigen.\n\nSprecht mit Bruder Keltan auf dem Hauptdeck, wenn Ihr das nicht schon getan habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13420] = {title = "Immerfrost", objective = "Ihr müsst nach Dun Niffelem zurückkehren und Euch bei Calder über das Stück Immerfrost erkundigen.\n\nBereitgestellter Gegenstand: \n", description = "Dieses Stück Eis war enormen Kräften und natürlicher Magie aus den Tiefen der Erde ausgesetzt. Zusammen haben diese Effekte ein Eis geschaffen, das niemals schmelzen wird.\n\nDa Ihr Euch in solchen Dingen nur wenig auskennt, entschließt Ihr Euch, die Probe zurück nach Dun Niffelem zu bringen. Dort muss es irgendjemanden geben, der mit dessen Eigenschaften vertraut ist.", progress = nil, completion = "&lt;Das Licht des Immerfrosteises leuchtet in Calders Augen, als er es hochhält.&gt;\n\nAhh, Immerfrost - Symbol des Herzens meines Volkes...\n\nImmerfrost gab es einst in dieser Region in Hülle und Fülle. Doch im Laufe der Zeit haben die Jormungar beinahe alles verschlungen. Heute ist es sehr selten und äußerst wertvoll für mein Volk.\n\nHaltet auf Euren Reisen durch dieses Land nach noch mehr Stücken Immerfrosts Ausschau. Bringt mir alles, was Ihr finden könnt, und wir werden überaus dankbar sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13421] = {title = "Vergesst das Immerfrosteis nicht!", objective = "Habt Ihr noch mehr Immerfrost gefunden, kleiner <Volk>?", description = nil, progress = "Habt Ihr noch mehr Immerfrost gefunden, kleiner <Volk>?", completion = "Gut gemacht, kleiner &lt;Klasse&gt;.\n\nImmerfrost gab es einst in dieser Region in Hülle und Fülle. Doch im Laufe der Zeit haben die Jormungar beinahe alles verschlungen. Heute ist es sehr selten und äußerst wertvoll für mein Volk.\n\nHaltet auf Euren Reisen durch dieses Land nach noch mehr Stücken Immerfrosts Ausschau. Bringt mir alles, was Ihr finden könnt, und wir werden überaus dankbar sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13422] = {title = "Disziplin bewahren", objective = "Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul in der Verlassenen Mine anwendet.", description = "Ihr habt das geschafft, woran andere gescheitert sind. Doch auf Euren Lorbeeren könnt Ihr Euch noch nicht ausruhen.\n\nIhr müsst anderen zeigen, was Stärke und Engagement wirklich bedeuten.\n\nDie Aufsässigen in der verlorenen Mine müssen wieder einmal diszipliniert werden. Zeigt es ihnen, Schwester... zeigt ihnen, was es bedeutet, uns nicht zu gehorchen.", progress = nil, completion = "Ihr geht weiterhin mit gutem Beispiel voran. Wir sehen zu Euch auf, Schwester.", rewards = "Ihr bekommt:\n\nHyldnirbeute"}
MultiLanguageQuestData['de'][13423] = {title = "Euren Titel verteidigen", objective = "Gretta die Schiedsfrau in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt.", description = "Alle sind von Eurer Leistung beeindruckt, Schwester. Doch lasst Eure Deckung nicht sinken. Jeder neue größenwahnsinnige Herausforderer wird jetzt herauskommen und sich Euren Titel als Hyldskvinnar schnappen wollen.\n\nZeigt diesen Emporkömmlingen, aus welchem Holz Ihr geschnitzt seid.", progress = "Wir verbeugen uns vor Eurer Kraft, Schwester.", completion = "Ihr erweist Euch weiterhin als würdig. Eure Anwesenheit ehrt uns.", rewards = "Ihr bekommt:\n\nHyldnirbeute"}
MultiLanguageQuestData['de'][13424] = {title = "Zurück in die Grube", objective = "Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Eisschlundmatriarchin 6 Kriegsbären des Hildarthings besiegt.", description = "Um auch weiterhin wirklich gut reiten zu können, werdet Ihr Euch jeden Tag gegen die Hyldnir beweisen müssen.\n\nBegebt Euch zurück zur Reißzahngrube und zeigt ihnen, wozu Ihr fähig seid. Sie werden dankbar sein, gegen jemanden zu verlieren, der so geschickt ist wie Ihr.", progress = nil, completion = "Ihr beweist auch weiterhin, was Ihr könnt. Eure Schwestern respektieren Euch noch immer.", rewards = "Ihr bekommt:\n\nHyldnirbeute"}
MultiLanguageQuestData['de'][13425] = {title = "Die Missgeburten müssen sterben", objective = "Gretta die Schiedsfrau in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.", description = "Euer Können unter Euresgleichen zu beweisen, ist nicht genug. Ihr müsst auch gegen unsere Feinde kämpfen, liebe Schwester.\n\nDie Valkyrionverräter verhöhnen weiterhin unsere edlen Drachenreittraditionen, indem sie verseuchte Protodrachen großziehen.\n\nKommt in den Besitz ihres Frostöls, das sie bei sich tragen, und benutzt es, um ihre widerwärtigen verseuchten Eier einzufrieren.", progress = nil, completion = "Ihr seid in mehr als nur einer Hinsicht eine Anführerin. Wir danken Euch, Schwester.", rewards = "Ihr bekommt:\n\nHyldnirbeute"}
MultiLanguageQuestData['de'][13426] = {title = "Der Zeuge Xarantaur", objective = "Sprecht mit Xarantaur im Camp Tunka'lo.", description = "Scheint, als wären wir nicht die einzigen Besucher dieser Gegend. Ein Kurier hat eine Nachricht von einem Tauren namens Xarantaur weitergeleitet, der gemeint hat, er habe ein Taunkadorf namens Camp Tunka'lo besucht. Der Zettel war zwar etwas kryptisch geschrieben, doch es scheint, als sei dieser Xarantaur in die Sturmgipfel gegangen, um der Geschichte einer Taunkalegende nachzugehen.\n\nTrefft Euch mit ihm, <Name>. Seht nach, ob das, was er weiß, uns in irgendeiner Art und Weise behilflich sein kann. Seiner Beschreibung nach befindet sich Camp Tunka'lo weit gen Osten, jenseits der Terrasse der Schöpfer und nördlich von Dun Niffelem.", progress = nil, completion = "Boktar hat also meine Nachricht erhalten? Das sind ausgezeichnete Neuigkeiten. Ich habe bezweifelt, ob der Träger, ein Fernläufer der Taunka, überhaupt irgendjemanden erreichen würde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13427] = {title = "Ruf zu den Waffen: Alteractal", objective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, <Name>, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", progress = nil, completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13428] = {title = "Ruf zu den Waffen: Alteractal", objective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, <Name>. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", progress = nil, completion = "Es gibt nichts Ehrenvolleres, als die feindlichen Invasoren aus dem Gebiet der Horde zu vertreiben. Ich verneige mich vor Eurem Mut und danke Euch dafür, dass Ihr unseren Streitkräften heute einen großen Dienst erwiesen habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13429] = {title = "Ein Ablenkungsmanöver für Akama", objective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", progress = nil, completion = "&lt;Xi'ri pulsiert vor Energie, Ihr fühlt, wie ein Gegenstand in Euren Händen Gestalt annimmt. Es ist das Medaillon, das Ihr A'dal im Namen von Akama gegeben habt. Seine Macht hat sich durch die Magie der Naaru noch verstärkt. Die Sha'tar haben Euch das Medaillon von Karabor anvertraut, und damit den Zugang zum Schwarzen Tempel.&gt;", rewards = "Ihr bekommt:\n\nMedaillon von Karabor"}
MultiLanguageQuestData['de'][13430] = {title = "Die Prüfung der Naaru: Magtheridon", objective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", progress = nil, completion = "Ihr habt Euch als Wesen mit großer Macht bewiesen. Die Naaru sind sich einig...", rewards = "Ihr bekommt:\n\nBand des Phönixfeuers"}
MultiLanguageQuestData['de'][13431] = {title = "Der Knüppel von Kar'desh", objective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13432] = {title = "Die Phiolen der Ewigkeit", objective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.\n\nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13433] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
