MultiLanguageQuestData['de'][13476] = {title = "Große Ehre", objective = "Bringt ein Ehrenabzeichen jedes Schlachtfelds zu einem Kriegshetzer der Horde in einer der Hauptstädte, Shattrath, Dalaran oder Tausendwinter.", description = "Der Horde in einer der größten Schlachten gegen die Allianz zu dienen, ist das Ausschlaggebende für große Ehre! Die Wenigen jedoch, die der Horde auf ALL unseren aktiven Schlachtfeldern gedient haben, sind unsere wahren, großen Kämpfer. Unsere Gegner sollen besiegt werden, aber nicht mittels vereinzelter Gefechte, sondern durch einen gut koordinierten Krieg.\n\nGeht und schmettert die Allianz an allen Fronten nieder! Für Ehre! Für die Horde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13477] = {title = "Gemeinsames Bestreben", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13478] = {title = "Gemeinsames Bestreben", objective = "Bringt ein Ehrenabzeichen jedes Schlachtfelds zu einem Brigadegeneral der Allianz in einer der Hauptstädte, Shattrath, Dalaran oder Tausendwinter.", description = "Wir kämpfen nicht mehr in vereinzelten Schlachten gegen die Horde, <Junge/Mädel>.\n\nDer gesamte Sieg an einer Front bedeutet der Horde die Ressourcen abzusprechen, die sie ansonsten in einer anderen Schlacht gegen uns verwenden würden. Ebenso könnte das Aufgeben in was auch immer für einer Schlacht unserem Gegner andernorts in der Welt einen Vorteil verschaffen.\n\nDie Allianz benötigt mehr Kämpfer mit diesem globalen Verständnis... wirklich bewährte Veteranen! <Name>, kommt zu mir zurück, wenn Ihr Euch gegen die Horde auf all unseren aktiven Schlachtfeldern bewährt habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13479] = {title = "Die große Eiersuche", objective = "Der Frühlingsernter möchte, dass Ihr 20 Eierschalenstücke besorgt.", description = "Nobelgarten, das Fest des Lebens und Frühlings! Ich hoffe, die Eiersuche hat Euch Spaß gemacht, denn ich könnte die Hilfe von jemandem, der so tüchtig ist wie Ihr, gut brauchen.\n\nIch bin mir nicht sicher, welcher Art die Magie war, die für die Erschaffung der Eier eingesetzt wurde und die Druiden halten sich mit Erklärungen zurück. Vielleicht könntet Ihr während Eurer Suche ein paar Eierschalenstücke für mich mitsammeln. Den Inhalt der Eier könnt Ihr behalten; alles was ich brauche ist eine Probe des Eis selber.", progress = "Habt Ihr die Schalenstücke?", completion = "Exzellent, exzellent, vielen Dank! Ich werde wahrscheinlich mehr Proben brauchen, um aussagekräftige Ergebnisse zu erhalten, aber für heute habt Ihr gute Arbeit geleistet.", rewards = "Ihr bekommt:\n\nBlühender Zweig"}
MultiLanguageQuestData['de'][13480] = {title = "Die große Eiersuche", objective = "Der Frühlingssammler möchte, dass Ihr 20 Eierschalenstücke besorgt.", description = "Nobelgarten, das Fest des Lebens und Frühlings! Ich hoffe, die Eiersuche hat Euch Spaß gemacht, denn ich könnte die Hilfe von jemandem, der so tüchtig ist wie Ihr, gut brauchen.\n\nIch bin mir nicht sicher, welcher Art die Magie war, die für die Erschaffung der Eier eingesetzt wurde und die Druiden halten sich mit Erklärungen zurück. Vielleicht könntet Ihr während Eurer Suche ein paar Eierschalenstücke für mich mitsammeln. Den Inhalt der Eier könnt Ihr behalten; alles was ich brauche ist eine Probe des Eis selber.", progress = "Habt Ihr die Schalenstücke?", completion = "Exzellent, exzellent, vielen Dank! Ich werde wahrscheinlich mehr Proben brauchen, um aussagekräftige Ergebnisse zu erhalten, aber für heute habt Ihr gute Arbeit geleistet.", rewards = "Ihr bekommt:\n\nBlühender Zweig"}
MultiLanguageQuestData['de'][13481] = {title = "Lasst uns von hier verschwinden!", objective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Bruder Keltan an Bord der Orgrims Hammer Bericht.", description = "Das Licht ist mir hold. Dieser wahrgewordene Alptraum hat mich noch nicht erledigt, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt zu entkommen.\n\nAlleine werde ich es nicht schaffen, <Klasse>, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13482] = {title = "Lasst uns von hier verschwinden", objective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Absalan dem Frommen an Bord der Himmelsbrecher Bericht.", description = "Das Licht ist mir hold. Dieser wahrgewordene Alptraum hat mich noch nicht erledigt, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt zu entkommen.\n\nAlleine werde ich es nicht schaffen, mein Kind, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", progress = nil, completion = "Dem Licht sei Dank. Ich glaubte, Vater Kamaros sei tot oder ihm sei noch Schlimmeres zugestoßen. Eure Tapferkeit und Euer Mitgefühl haben dazu geführt, dass ein wichtiger Verbündeter zum Argentumkreuzzug zurückkehren konnte. Ihr habt meinen Dank und den des Kreuzzugs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13483] = {title = "Frühlingsernter", objective = "Sprecht mit einem Frühlingsernter in Klingenhügel, in Brill, im Dorf der Bluthufe oder auf dem Falkenplatz.", description = "Falls Ihr nach Arbeit sucht - ich habe gehört, dass es in den Siedlungen in der Nähe großer Städte - in Klingenhügel, in Brill, im Dorf der Bluthufe und am Falkenplatz - Magier geben soll, die Eiersucher anstellen, die ihnen bei ihren Forschungen helfen. Ich kenne keine Einzelheiten, aber die werden sie Euch sicher gerne geben.", progress = nil, completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", rewards = nil}
MultiLanguageQuestData['de'][13484] = {title = "Frühlingssammler", objective = "Sprecht mit einem Frühlingssammler in Goldhain, Kharanos, Dolanaar oder Azurwacht.", description = "Falls Ihr nach Arbeit sucht - ich habe gehört, dass es in den Siedlungen in der Nähe großer Städte - Goldhain, Kharanos, Dolanaar und Azurwacht - Magier geben soll, die Eiersucher anstellen, die ihnen bei ihren Forschungen helfen. Ich kenne keine Einzelheiten, aber die werden sie Euch sicher gerne geben.", progress = nil, completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", rewards = "Ihr bekommt:\n\n"}
