MultiLanguageQuestData['de'][13501] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][13502] = {title = "Einen Korb bekommen!", objective = "Der Nobelgartenverkäufer möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokoladen wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", rewards = "Ihr bekommt:\n\nEierkorb"}
MultiLanguageQuestData['de'][13503] = {title = "Einen Korb bekommen!", objective = "Der Nobelgartenhändler möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokolade wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", rewards = "Ihr bekommt:\n\nEierkorb"}
MultiLanguageQuestData['de'][13504] = {title = "Arbeiter der Splitterspeere", objective = "Tötet 10 Arbeiter der Splitterspeere.", description = "In den Ruinen im Norden und Nordosten gibt es eine große Schar von Splitterspeertrollen, die dort herumstöbern. Ich vermute, sie suchen nach magischen Artefakten, aber keiner unserer Späher kann von nennenswerten Funden in ihren Ausgrabungsstätten berichten. Vielleicht treiben sie ja auch einfach nur ihre Kriegsmaschinerie voran.\n\nEines ist aber recht sicher: Arbeitermangel würde ihren Angriff schwächen, also verpassen wir ihnen einen Arbeitermangel. Seid Ihr dabei?", progress = nil, completion = "Gute Arbeit. Vielen Dank, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13505] = {title = "Relikte der Hochgeborenen", objective = "Erhaltet 8 Hochgeborenenrelikte.", description = "Es gibt überall an der Dunkelküste ähnliche Ruinen wie diese und viele von ihnen werden von geplagten Geistern der Hochgeborenen heimgesucht. Aus Rücksicht auf ihre verfluchten Seelen haben wir uns bisher damit zurückgehalten, die Ruinen nach Artefakten zu durchsuchen, aber solche guten Vorsätze müssen im Angesicht dieser neuen Bedrohung durch die Trolle aufgegeben werden.\n\nBitte bergt sämtliche Artefakte, auf die Ihr stoßt, während Ihr den Schildwachen bei der Erfüllung ihrer Ziele in den Ruinen helft, und bringt sie zu mir zurück. Ich würde gern so viele retten, wie ich kann.", progress = "Konntet Ihr irgendwelche Artefakte bergen?", completion = "Perfekt! Habt vielen Dank. Ich würde nur sehr ungern noch mehr Zeugnisse unserer Kultur an den Krieg verlieren - viel zu Vieles mussten wir schon opfern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13506] = {title = "Grund zur Sorge", objective = "Bringt die Splitterspeerbefehle zu Leutnant Morra Sternenhauch in den Ruinen von Mathystra.", description = "Hierbei scheint es sich um Befehle zu handeln, die von einem Vorgesetzten im Kriegslager der Splitterspeere an die Vorarbeiter in den Ruinen geschickt wurden. Der Großteil der Dokumente ist von unwesentlichem strategischen Wert, aber ein paar Zeilen fallen Euch auf.\n\n\"Wir haben noch eine Nachtelfenspionin aufgegriffen. Sie wurde zum Lager gebracht, um ihr unter Folter mehr Informationen zu entlocken. Haltet nach weiteren Spionen Ausschau - wir können es uns nicht leisten, dass unsere Operation hier aufgedeckt wird.\"\n\nLeutnant Sternenhauch möchte diese Informationen sicher sehen.", progress = "Ja, <Klasse>?", completion = "\"Noch einen\"? Sie haben also mehr als einen. Ich werde keinen meiner Leute der Folter überlassen, wir müssen schnell handeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13507] = {title = "Verwehrt ihnen die Arbeit", objective = "Tötet 6 Vollstrecker der Horde und 6 Mystiker der Splitterspeere.", description = "Im Norden haben die Splitterspeere ein Kriegslager, in dem sie ihre Katapulte bauen. Das Lager wird von einigen ihrer Mystiker bewacht, aber ich habe auch erste Berichte erhalten, dass Orcs und Tauren ebenfalls gesichtet wurden.\n\nIch möchte keine Spekulationen anstellen, was das bedeuten könnte, aber ich möchte sehr wohl, dass Ihr Euch auf den Weg macht und sie tötet, bevor sie noch weitere Angriffe auf unsere Schildwachen starten können.", progress = nil, completion = "Ausgezeichnete Arbeit. Eine weitere Bedrohung, über die wir uns etwas weniger Sorgen machen müssen. Wir werden unseren Angriff fortsetzen, während sie noch desorientiert sind.", rewards = "Tyshas BrustschutzBedeckung aus BlätternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13508] = {title = "Schnelle Reaktion", objective = "Findet die gefangenen Nachtelfen im Kriegslager der Splitterspeere.", description = "Wir haben vor ein paar Tagen den Kontakt mit einer meiner Späherinnen verloren. Ich hielt sie für tot, aber anscheinend wurde sie nur gefangen genommen. Den Trollen nach haben sie aber zwei Gefangene... Die einzige weitere Person, die in Frage kommt, ist Alanndarian Nachtweise, eine Zivilistin, die sich gestern Vormittag gegen meinen Rat in der Gegend aufgehalten hat.\n\nDie Splitterspeere haben im Norden ein Kriegslager aufgeschlagen - dorthin werden sie mit an Sicherheit grenzender Wahrscheinlichkeit alle Gefangenen gebracht haben. Macht sie ausfindig und befreit sie, wenn Ihr könnt.", progress = nil, completion = "&lt;Alanndarian sieht äußerst blass aus, doch schwache Atemzüge bezeugen, dass noch Leben in ihr steckt.&gt;\n\nIhr seid hier, um... mich zu retten? Etwas später... als ich gehofft hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13509] = {title = "Kriegsvorräte", objective = "Zerstört 12 Vorratskisten der Splitterspeere.", description = "Die Trolle sammeln ihre Truppen und Vorräte in ihrem Kriegslager im Norden. Sie werden von dort fast mit Sicherheit ihren Angriff auf Lor'danel starten, sobald sie sich bereit fühlen. Es sollte nicht lange dauern, dieses Gesindel in die Flucht zu schlagen, ich bin jedoch dagegen, unnötige Risiken einzugehen.\n\nIch möchte, dass Ihr Euch einen Weg in das Kriegslager erkämpft und alle Vorräte in Brand steckt, die Ihr finden könnt. Dieser Rückschlag sollte uns einige Zeit verschaffen, bis sie einen Gegenangriff starten können.", progress = nil, completion = "Ausgezeichnete Arbeit. Das sollte sie ein wenig aufhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13510] = {title = "Rechtzeitige Ankunft", objective = "Bringt Schildwache Aynasha in Sicherheit.", description = "Schön Euch zu sehen. Ich habe mich nicht darauf gefreut, das Gleiche durchzumachen wie Alanndarian, also ist mir Eure Rettung sehr willkommen.\n\nIch konnte den Anführer der Trolle entdecken, bevor man mich fasste. Ich dachte, ich hätte die perfekte Gelegenheit, ihn auszuschalten, aber er wird von einer Art magischem Schild geschützt. Morra muss davon in Kenntnis gesetzt werden, bevor sie ihren Angriff startet, aber zuerst müssen wir hier verschwinden.\n\nHelft mir zum Dock - ich werde Lor'danel über den Wasserweg erreichen und Ihr könnt die Informationen zu Morra zurückbringen.", progress = nil, completion = "Eine Art Schild, sagt Ihr? Dagegen haben wir vielleicht ein Mittel. Balthule ist ein Einfall gekommen, wie man jegliche Schutzzauber ihrer Schamanen durchbrechen kann. Vielleicht funktioniert das auch damit. Danke, dass Ihr Aynasha gerettet und mir diese Informationen überliefert habt - das könnte womöglich unseren Kampf hier entscheiden.", rewards = "Morras HandschuheAynashas ReserveschwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13511] = {title = "Ein verbitterter Wunsch", objective = "Tötet Rit'ko, den Folterer der Splitterspeere.", description = "Morra schickt Euch? Ich hätte auf sie hören sollen - es ist wohl zu einfach, Trolle nicht ernst zu nehmen.\n\n<Alanndarian lacht leise in sich hinein.>\n\nDafür ist es jetzt ohnehin viel zu spät. Wir sind jetzt sterblich... dies ist das Schicksal, dem wir früher oder später erliegen werden. Ich habe Zeit genug gehabt, mich damit abzufinden.\n\nEine Bitte habe ich jedoch... tötet den Folterer, der mir das hier angetan hat. Sie nennen ihn Rit'ko... Ihr könnt ihn weiter vorne bei der anderen Gefangenen finden.\n\n<Alanndarian lächelt schwach, zuckt dann vor Schmerz zusammen und sinkt wieder zu Boden.>", progress = nil, completion = "Alanndarian ist also tot. Das bedrückt mich sehr, kommt aber nicht gänzlich unerwartet. Ich erwarte von diesen Wilden keine Gnade und werde ihnen auch keine zuteilwerden lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13512] = {title = "Strategische Schläge", objective = "Tötet Sheya Sturmwirker und Lorenth Donnerruf.", description = "Der Bestie den Kopf abzuschlagen hat keinen Sinn, wenn es einen zweiten Kopf gibt, der ihn ersetzen kann. Bevor wir ihren Anführer ausschalten können, müssen wir die Unteranführer töten, die das Machtvakuum füllen würden. Momentan werden sie nicht so gut beschützt und Ihr solltet sie ohne weitere Unterstützung besiegen können.\n\nNehmt diesen Dryadenspeer und spürt sie auf. Das Gift an seiner Spitze sollte ihre Zaubersprüche verlangsamen. Meine Späher berichten mir, dass einer von ihnen in der Wasserkammer in den Ruinen im Osten ist und der andere wurde hinter den Überresten des Turmes im Südwesten gesichtet.", progress = nil, completion = "Ihr habt eine Menge Talent bewiesen für jemanden, der noch so jung ist. Gute Arbeit. Offenbar steht uns die letzte Schlacht kurz bevor.", rewards = "Ihr bekommt:\n\nZauberstab der Dryade"}
MultiLanguageQuestData['de'][13513] = {title = "Kein Zurück", objective = "Erhaltet 6 Amulette der Splitterspeere.", description = "Ich arbeite bereits an einem Mittel, um ihre Schutzzauber zu überwinden. Mit einem Fokus, der auf ihren Mächten beruht, und etwas Druidenmagie sollten wir in der Lage sein, ihre Schilde zu durchbrechen.\n\nSpürt ihre Schamanen im Osten und Südosten auf und beschafft einige ihrer Amulette. Ich werde sie vorbereiten und einen Pfeil verzaubern, den Ihr Sandrya Mondsturz für den Angriff überbringen könnt.", progress = "Habt Ihr die Amulette bei Euch?", completion = "Diese Amulette sind genau das, was ich brauche. Ich werde sie für Sandrya vorbereiten - man wird Euch sicher gleich beauftragen, Euch mit ihr zu treffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13514] = {title = "Der Zorn der Urtume", objective = "Benutzt einen rachsüchtigen Beschützer um 30 Trolle der Splitterspeere zu töten und 6 Gebäude der Splitterspeere zu zerstören.", description = "Seid Ihr hier, um Euch dem Angriff anzuschließen? Wenn Ihr nach Sandrya Mondsturz sucht, findet Ihr sie in der Höhle am Ende dieses Tals, wo sie den Angriff auf den Anführer der Splitterspeere leitet.\n\nWo Ihr schon hier seid, könnten wir allerdings auch Eure Hilfe beim Zusammentreiben des restlichen Stammes brauchen. Zieht mit einem der rachsüchtigen Beschützer los und sorgt dafür, dass auch das letzte Gebäude zerstört und der Stamm bis auf den letzten Troll ausgelöscht wird. Wir wollen doch nicht, dass sie versuchen, sich an uns zu rächen, wenn wir nicht darauf gefasst sind, oder?", progress = nil, completion = "Ihr habt Euch dort oben hervorragend geschlagen! Wir können von Glück reden, Euch bei uns zu haben.\n\nIch habe noch keine Nachricht über ihren Anführer erhalten. Wenn Ihr noch nicht mit Sandrya in der Höhle am Ende des Tals gesprochen habt, solltet Ihr das unbedingt nachholen, bevor Ihr wieder aufbrecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13515] = {title = "Das Ende der Bedrohung", objective = "Sprecht mit Sandrya Mondsturz, um den Angriff zu starten, und helft ihr dann dabei, Jor'kil den Seelenreißer zu töten.", description = "Auf uns warten ihr Anführer und seine Leibwache. Meine Schildwachen sind bereit, seine Leibwächter auszuschalten. Wir warten nur auf diesen Pfeil, um das Schicksal ihres Anführers zu besiegeln.\n\nLasst es mich wissen, wenn Ihr bereit für den Angriff seid. Sobald meine Schildwachen die Höhle stürmen, werde ich den Schild des Anführers zertrümmern und wir werden ihm gemeinsam entgegentreten. Schlagt geschwind zu und wir können diese Bedrohung für unsere Ländereien hier und heute beenden.\n\nWir warten nur auf Euch - sprecht mit mir, wenn Ihr bereit seid.", progress = nil, completion = "Wir stehen tief in Eurer Schuld für alles, was Ihr getan habt, um diese Schlacht zu einem glücklichen Ende zu bringen.\n\nEs geschieht nicht oft, dass wir einen derartig eindeutigen Sieg davontragen können, aber wie es scheint, steht hinter dieser Verschwörung mehr als nur der Stamm der Splitterspeere. Wenn Ihr seine Leiche noch nicht nach Informationen durchsucht habt, solltet Ihr dies tun, bevor Ihr weiterzieht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13518] = {title = "Die letzte Welle Überlebender", objective = "Macht alle überlebenden Flüchtlinge von Auberdine ausfindig.", description = "Für Laird ist es zu spät, er hat es nicht mehr rechtzeitig geschafft.\n\nDie letzte Welle Nachtelfen aus Auberdine hat vor ein paar Stunden versucht zu entkommen. Sie sind in ihrem alten Zuhause geblieben und haben sich an die Hoffnung geklammert, dass es gerettet werden kann, aber offenbar mussten sie sich letzten Endes den Naturgewalten beugen. Ich befürchte, dass viele von ihnen es nicht schaffen werden, so wie Laird.\n\nEilt Euch. Geht zur Küste im Westen hinunter und macht so viele Überlebende ausfindig, wie Ihr könnt. Wir schicken Schildwachen und Hippogryphen, aber jeder Augenblick zählt - wir müssen wissen, wer überleben könnte.", progress = nil, completion = "Ich danke Euch, &lt;Klasse&gt;. Manche von ihnen hätten es ohne Eure Hilfe nicht geschafft.\n\nWir werden die Verwundeten ins Hauptgebäude bringen, sobald alle sicher in der Stadt angekommen sind. Vielleicht könnt Ihr uns später dort aufsuchen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13519] = {title = "Der Schattenhammer", objective = "Tötet Hochkultist Azerynn und 10 Fanatiker des Schattenhammers im Lager des Schattenhammers.", description = "Eine Gruppe von Schattenhammerkultisten hat südwestlich von hier Lager aufgeschlagen. Sie stellen eine Armee von Wasserelementaren zusammen, die gegen Lor'danel eingesetzt werden könnte.\n\nIhr Anführer, der Hochkultist Azerynn, hat einen Pakt mit den dunklen Göttern geschlossen, die seinem Kult Macht über die Elemente gewähren. Kümmert Euch darum, bevor es zu spät ist, <Name>.\n\nDer Kataklysmus hat die Elemente verwirrt... es ist nur eine Frage der Zeit, bis sie genug Elementare haben, um unsere Verteidigung zu übermannen.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Der Schattenhammer ist ein gefährlicher Kult. Die Gefahr, die sie darstellen, zu unterschätzen, wäre die Tat eines Narren.", rewards = "Fanatische TreterHandschuhe der Kettenbewehrten FaustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13520] = {title = "Der Segen der Meere", objective = "Sammelt 16 verkrustete Muschelmuskeln.", description = "Gut, Euch zu sehen. Dank Euch sind unsere Verwandten sicher nach Hause gekommen und ich hege Hoffnung, dass Ihr uns auch weiterhin helfen könnt.\n\nIhre Wunden werden so schlimm sein wie die von Laird - jeder einzelne wurde an der Küste arg mitgenommen und von den Elementaren angegriffen. Ich tue, was ich kann, aber es scheint, als hätten die Elementare ein Gift, das die Wundheilung einschränkt. Ich hoffe eine Salbe herstellen zu können, aber dazu benötige ich Sekret von Muschelmuskeln, die an der Küste zu finden sind. Könnt Ihr mir helfen?", progress = "Habt Ihr die Muschelmuskeln? Ich fürchte, wir haben nicht mehr viel Zeit.", completion = "Die sind ideal. Ich danke Euch vielmals!\n\nIch gehe davon aus, dass sie Euch selbst danken wollen, falls sie wieder zu Kräften kommen. Vielleicht könnt Ihr ja später noch einmal hierherkommen.", rewards = "Ihr bekommt:\n\nTauchergürtel"}
MultiLanguageQuestData['de'][13521] = {title = "Dröhnkiste 413", objective = "Sammelt 4 Proben verderbtes Gezeitenkriecherfleisch und bringt es zur Analyse zur Dröhnkiste 413.", description = "Seid gegrüßt!\n\nIch helfe Tharnariun dabei, herauszufinden, was die Tiere in der Gegend verderbt. Ich habe ein Gerät aufgestellt, das Tierteile und mögliche Verderbniserreger analysieren kann. Wenn Ihr mir ein paar gute Proben besorgen könnt, so werden wir schnell herausfinden, was es mit der Verderbnis auf sich hat.\n\nDas erste Gerät ist die Dröhnkiste 413. Sie steht am Strand östlich der Stadt. Besorgt das Fleisch der verderbten Gezeitenkriecher in der Nähe und bringt es zur Dröhnkiste, damit wir es analysieren können.", progress = "<Die Dröhnkiste 413 dröhnt Euch erwartungsvoll entgegen.>", completion = "&lt;Das Gerät knattert vor sich hin und plötzlich ertönt Hexknalls statische Stimme.&gt;\n\nWunderbar! Ich hoffe, Ihr habt nicht zu viele getötet. Wir wollen sie nicht dem Aussterben nahe bringen, sondern nur schnell herausfinden, wo die Verderbnis herkommt! Ich fahre jetzt mit der Analyse fort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13522] = {title = "Gefahr aus dem Wasser", objective = "Tötet 8 widerwärtige Gischte.", description = "Ein paar der Überlebenden des letzten Angriffs von Auberdine versuchen noch immer, an die Küste und in Sicherheit zu gelangen. Wir haben vor weniger als einer Stunde erst erfahren, dass sie kommen. Ich wünschte, wir hätten mehr Vorwarnzeit gehabt...\n\nAn der Küste westlich von hier wimmelt es von bösartigen kleinen Wasserelementaren. Wir müssen sie beseitigen, wenn die Überlebenden es bis nach Lor'danel schaffen sollen. Macht Euch sofort auf den Weg und tötet jeden Elementar, den Ihr finden könnt.", progress = nil, completion = "Wir sind Euch für Eure Anstrengungen sehr dankbar. Seit dem Kataklysmus sind die Elementare außer Kontrolle. Wir hegen wenig Hoffnung, Auberdine zurückzuerobern, ohne vorher die Elementare auszulöschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13523] = {title = "Macht über die Gezeiten", objective = "Wendet die Kugel von Elune an den Überresten von 6 wütenden Gezeitengeistern an.", description = "Sorgt Euch nicht um mich. Meine Wunden sind tief und bald wird mich der Tod ereilen.\n\nNun liegt alles in Euren Händen... Ihr müsst den Schattenhammer aufhalten.\n\nDie Alten Götter, die von ihnen verehrt werden, haben ihnen Macht über die ruhelosen Wassergeister gewährt... diese Macht ist heikel. Kanalisiert Elunes Präsenz durch diese Kugel, sobald die Elementare besiegt sind.\n\nVerwendet die Macht Elunes, um die Geister für immer zu verbannen.", progress = nil, completion = "Ihr habt es geschafft... nicht alles war vergebens...\n\nMeine Zeit ist gekommen. Geht nun, &lt;Name&gt;. Möge Elune Euch beschützen.", rewards = "GezeitenumhangTharills SegenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13524] = {title = "Flucht aus Silberwasser", objective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Gewandung der eingesperrten BestieStiefel des inneren LeidensHandgelenksschützer der gequälten SeeleSabatons der vernichteten MenschheitAuf Euch wartet eine dieser Belohnungen:\n\nWorgtöterring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13525] = {title = "Was ist mit den Furbolgs der Schwarzfelle los?", objective = "Sprecht mit dem Ältesten Brolg in der Schwarzfellfeste.", description = "Unsere Vorfahren lebten schon seit Generationen friedlich neben den Furbolgs der Schwarzfelle. In letzter Zeit aber ist der Kontakt zu den Siedlungen abgebrochen, die sich tiefer im Wald befinden. Eines ihrer größeren Dörfer, Schwarzfellfeste, befindet sich südlich von hier.\n\nReist dorthin und findet den Ältesten Brolg. Fragt ihn, warum sich sein Volk von uns zurückgezogen hat und bietet Eure Hilfe an, wenn es ihrer bedarf.", progress = nil, completion = "Was verschlägt Euch hier her, Außenseiter?\n\n&lt;Ihr erzählt dem Ältesten, dass Foriel Rundblatt vom Hain der Uralten Euch geschickt hat. Der Älteste scheint sich ein wenig zu beruhigen.&gt;\n\nDer Elf hat Recht. Die Streitmächte aus Teufelswald sind bis zur Dunkelküste vorgedrungen und haben mein Volk krank gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13526] = {title = "Der Bärenklau", objective = "Bringt 8 Stängel Bärenklau zum Ältesten Brolg in der Schwarzfellfeste.", description = "Die garstigen Satyrn aus Teufelswald haben begonnen, ihr Gift an die Dunkelküste zu bringen, in unser Land. Die Verderbnis zerstört das Land und verdreht dessen Bewohner – auch mein Volk.\n\nUnsere Magie alleine reicht nicht aus, um sie wieder gesunden zu lassen. Es gibt allerdings eine Pflanze namens Bärenklau, mit der wir Fieber senken und die Schwachen stärken. Mit der Hilfe dieser Pflanze könnte auch der Einfluss der Satyrn geheilt werden. Ihr findet die Pflanze in der Wildnis in der Nähe des Dorfes.", progress = "Habt Ihr den Bärenklau?", completion = "Die Stängel sind kümmerlich und schwach, aber mehr haben wir nicht. Die Verderbnis verbreitet sich schnell und selbst die Pflanzen bleiben nicht verschont.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13527] = {title = "Über Geschmack lässt sich nicht streiten", objective = "Erhaltet die Probe eines faulenden Bärenkadavers östlich der Dröhnkiste 413.", description = "<Das Gerät rauscht ein paar Augenblicke lang, bevor Hexknalls Stimme ertönt.>\n\nInteressant! Der Ursprung der Verderbnis kommt definitiv von einer externen Quelle - was mich weniger verwundert - aber es scheint, als wurde sie durch das Essen verderbter Nahrung übertragen, ein großes Säugetier wahrscheinlich, ich würde auf einen Bären tippen.\n\nSucht den Strand nach dem Kadaver des Bären ab. Östlich von hier würde es am meisten Sinn ergeben, an der Seite des Strandes, die zum Landesinneren zeigt. Bringt mir eine Probe von seinem Fleisch.", progress = "Willkommen zurück! Habt Ihr den Kadaver gefunden und ihm eine Probe entnehmen können?", completion = "Das sieht eindeutig nach dem Zeug aus, das sie gegessen haben. Lasst mich das genauer anschauen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13528] = {title = "Dröhnkiste 723", objective = "Sammelt 6 Proben verderbte Eingeweide eines Distelbären und bringt sie für eine Analyse zur Dröhnkiste 723.", description = "Wir konnten noch an ein paar anderen wilden Tieren eine Infektion feststellen. Es sind sogar gute Neuigkeiten, dass die Kriecher sich an den Bären angesteckt haben – hoffentlich lassen sich alle Fälle auf diese eine Quelle zurückführen. Jetzt müssen wir unsere Aufmerksamkeit den Bären widmen.\n\nDie Dröhnkiste 723 ist in der Nähe der Wasserfälle östlich von hier. Es ist keine schöne Arbeit, aber sie ist nötig: Ich brauche für die Analyse frische Bäreneingeweide für die Dröhnkiste. Mit weiteren Informationen können die nächsten Schritte leichter bestimmt werden.", progress = "<Die Dröhnkiste 723 dröhnt Euch erwartungsvoll entgegen.>", completion = "&lt;Es rauscht statisch, bevor Hexknalls verzerrte Stimme ertönt.&gt;\n\nWir bekommen gerade die Ergebnisse. Wir sollten jeden Augenblick mehr Informationen darüber erhalten, wie die Bären sich die Verderbnis eingefangen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13529] = {title = "Der Ursprung der Verderbnis", objective = "Tötet Zenn Faulhuf und 8 üble Grells in der Klippenquellgrotte.", description = "Ich habe mich auf den Weg gemacht, als ich die Neuigkeiten von Hexknall gehört habe. Ich weiß jetzt, wer hinter allem steckt: Zenn Faulhuf.\n\nEr kam von Teldrassil hierher, nachdem er von dort für das Wirken pervertierter Magie verjagt worden war. Die Art von Verderbnis, die er anwendet, ist in meinen Reihen nicht willkommen und es scheint als sei er dieses Mal einen Schritt zu weit gegangen. Vielleicht hat er es aus Rache getan.\n\nZenn wurde zu lange akzeptiert und es ist an der Zeit, dass wir diese Bedrohung all dessen, was natürlich ist, beseitigen. Tötet Zenn und seine Diener. Sucht mich dann in Lor'danel auf.", progress = nil, completion = "Es ist vollbracht. Ich danke Euch. Ich hoffe nur, dass die Wildtiere nach seinem Tod etwas mehr Frieden finden werden.", rewards = "ZiegenhautwesteVerwobene KettengamaschenStab aus SatyrhornIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13537] = {title = "Lust auf Barsch", objective = "Benutzt Eure Angelfertigkeit, um 4 Dunkelküstenbarsche zu erhalten.", description = "Nach all dem Bootfahren und Bauen bin ich erschöpft... und hungrig. Wisst Ihr, worauf ich Lust habe? Fisch. Fisch klingt für mich jetzt unfassbar gut.\n\nDunkelküste ist für Barsch bekannt. Wenn Ihr mir welchen fischt, werde ich dafür sorgen, dass es sich für Euch lohnt.", progress = "<Ihr hört Johnathans Bauch knurren, als Ihr Euch nähert.>\n\nBesser hätten Worte es nicht ausdrücken können.", completion = "Es scheint, als sei Angeln etwas, das Euch liegt. Mein Bauch ist für dieses Geschenk sehr dankbar.\n\nIch glaube, Ihr könnt mit dieser Angelrute mehr anfangen als ich. Nehmt sie.", rewards = "Ihr bekommt:\n\nStaats Angelrute"}
MultiLanguageQuestData['de'][13538] = {title = "Sabotage aus dem Süden", objective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Ahbramis in Tausendwinter zurück.", description = "Die drei Türme südlich des Tausendwinterflusses entziehen der Festung Energie!\n\nMacht den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm dem Erdboden gleich und erstattet mir dann Bericht. Denkt dran, nur Belagerungsmaschinen können einen Turm beschädigen, deshalb müsst Ihr sie gut vor der Horde beschützen!", progress = nil, completion = "Ich habe die Explosion bis hier gehört! Gute Arbeit - wir haben schon damit begonnen, die Energie in das Relikt der Titanen umzuleiten, um eine Superaufladung für unsere eigenen Truppen zu ermöglichen.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13539] = {title = "Einstürzende Turmbauten", objective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Kilrath in Tausendwinter zurück.", description = "Während die Allianz gegen unsere Türen hämmert, schaut ein wahrer Taktiker über das Offensichtliche hinaus.\n\n\"Greif ihn an, wo er unvorbereitet ist, erscheine, wo du nicht erwartest wirst.\"\n\n<Name>, überquert den Tausendwinterfluss und macht einen der drei Türme im Süden dem Erdboden gleich. Unsere Hexenmeister berichten, dass die Türme Energie abziehen, die wir benutzen könnten, um unsere eigenen Truppen zu stärken.\n\nKehrt zu mir zurück, sobald Ihr einen Turm zerstört habt.", progress = nil, completion = "Und nun, um den Feind zu vernichten, muss der Zorn unserer Truppen geweckt werden. Um den Vorteil darin zu sehen, den Feind zu besiegen, müssen sie ihre Belohnungen erhalten. Ich hoffe, dass dies hier Euren Dienst an der Horde ausreichend entlohnt.", rewards = "Ihr bekommt:\n\nEhrepunkteSplitter eines Steinbewahrers"}
MultiLanguageQuestData['de'][13542] = {title = "Gegen den Wind", objective = "Benutzt den Mondbrunnen in den Ruinen von Auberdine, um 8 Armschienen des rasenden Zyklons zu zerstören.", description = "Wenn wir die Ruinen von Auberdine aus den Händen des Schattenhammers zurückerlangen möchten, so müssen wir uns dauerhaft um die Elementare kümmern, die sie beschworen haben.\n\nHier kommt Ihr ins Spiel.\n\nIch erwarte nicht, dass Ihr die Stadt alleine einnehmt, aber während wir hier oben heilen, könnt Ihr sie für uns schonmal weichklopfen.\n\nUm mit den rasenden Zyklonen auf lange Sicht fertigzuwerden, müsst Ihr Euch nach Westen begeben, sie töten, ihre Armschienen an Euch nehmen und sie in den Mondbrunnen werfen. Das wird die Armschienen zerstören und verhindern, dass die Elementare wieder beschworen werden können.", progress = nil, completion = "Ich kann Euch gar nicht genug danken, &lt;Name&gt;. Nun haben wir eine realistische Chance, die Ruinen zurückzuerobern, sobald wir uns erholt haben.", rewards = "Windstille ArmschienenSehr ruhige ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13543] = {title = "Drei Hammer zu Brechen...", objective = "Tötet Wolkenzähmerin Wildmähne, Windmeister Tzu-Tzu und Himmelsfürst Braax.", description = "Ich bin über die Ruinen von Auberdine geflogen, um das Gebiet auszukundschaften. Drei Schattenhammerkultisten dort sind für die Elementare verantwortlich, die die zerstörte Stadt eingenommen haben.\n\nBegebt Euch zu den Ruinen westlich von hier. Sucht und besiegt Wolkenzähmerin Wildmähne, Windmeister Tzu-Tzu und den Himmelsfürst Braax.\n\nWenn sie aus dem Weg geschafft sind, werden Schildwache Selarin und ihre Truppen eine Chance haben, ihre Heimat zurückzuerobern.", progress = nil, completion = "Ohne dass die Drei hier weiter Elementare anlocken, wird es in den Ruinen von Auberdine weitaus weniger von ihnen geben.\n\nIch danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13544] = {title = "Der Bärensegen", objective = "Bringt das gesegnete Kräuterbündel zum Ältesten Brolg in Schwarzfellfeste.", description = "Bevor der Bärenklau verwendet werden kann, um die Betroffenen zu reinigen, müssen wir ihn dafür vorbereiten und segnen. Nördlich von unserem Dorf ist ein Weitschreiter namens Flinkfuß zu finden. Um das Bündel zu vervollständigen, brauchen wir seine Schwanzfedern.\n\nBringt die Schwanzfedern und das Bärenklaubündel zur uralten Bärenstatue in den Ruinen beim Hain der Uralten, noch weiter nördlich als Flinkfuß.\n\nFügt am Schrein die Schwanzfedern dem Bärenklau hinzu und erhaltet den Segen des Bärengeists.", progress = "Wart Ihr bei der uralten Bärenstatue?", completion = "&lt;Der Älteste Brolg nimmt das gesegnete Bündel entgegen und betrachtet es.&gt;\n\nDas ist genau das, was ich brauche. Der Bärengeist ist uns wohlgesinnt und es gibt doch noch Hoffnung für meine Brüder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13545] = {title = "Die Befallenen reinigen", objective = "Der Älteste Brolg möchte, dass Ihr das gesegnete Kräuterbündel benutzt, um 7 Furbolgs der Schwarzfellfeste zu läutern und die Geister der Verderbnis, die sie in den Wahnsinn treiben, tötet.", description = "Mit den vom Bärengeist gesegneten Pflanzen im Kräuterbündel können meine Brüder nun gereinigt werden. Die Verderbnis aus Teufelswald hat sie in den Wahnsinn getrieben und sie greifen jeden an, der ihnen zu nahe kommt. Ihr müsst damit rechnen, dass die Befallenen feindlich auf Euch reagieren werden, bis Ihr die Geister der Verderbnis getötet habt, die sie verfolgen.\n\nKehrt zu mir zurück, wenn Ihr meine Brüder von der Verderbnis befreit habt.", progress = nil, completion = "Ihr habt gute Taten vollbracht. Mein Volk beginnt, sich von dem Wahnsinn zu lösen. Wenn der Ursprung der Verderbnis jedoch weiterhin hier ist, so werden sie bald wieder verderbt sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13546] = {title = "Der Schänder", objective = "Der Älteste Brolg in der Schwarzfellfeste möchte, dass Ihr Sharax den Schänder tötet.", description = "Die Jadefeuersatyrn von Teufelswald haben sich ihren Weg zur Dunkelküste gebahnt und jedem Land, jedem Wasser und jeder Kreatur unterwegs die Verderbnis auferlegt. Ihr habt gesehen, was die Verderbnis mit meinem Volk und unserer Heimat angestellt hat. Wenn wir die Satyrn nicht bekämpfen, so wird unser Schicksal das Gleiche sein.\n\nIn der Höhle östlich von hier ist Sharax der Schänder zu finden, der Satyr, der für das Leiden der Schwarzfelle verantwortlich ist. Tötet ihn, <Name>, und befreit uns von seinem Einfluss. Zeigt den Satyrn, dass die Schwarzfelle nicht so leicht unterzukriegen und zu verderben sind.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Ihr werdet von meinem Volk als Held gefeiert. Ohne Euch wären wir dem Wahnsinn und dem Tod ausgesetzt gewesen. Möge der große Bärengeist immer über Euch wachen.", rewards = "Stiefel der SchwarzfelleJägerbogen der SchwarzfelleRitualstecken der SchwarzfelleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13547] = {title = "Die Geister locken", objective = "Lockt die Geister von Thundris Windwirker, Elissa Sternenhauch, Taldan und Caylais Mondfeder.", description = "Eure Freunde im Flüchtlingslager sind sich der tatsächlichen Gefahr nicht bewusst, welche die Schattenhammerkultisten bereits über die Welt gebracht haben.\n\nDamit Ihr Euch der Sache annehmen könnt, müsst Ihr zuerst Hilfe von den Toten aus Auberdine bekommen.\n\nSucht in den Ruinen der Stadt nach den Leichen von Thundris Windwirker, Elissa Sternenhauch, Taldan, und Caylais Mondfeder. Lockt die Geister aus ihren Körpern heraus und bringt sie zu mir.", progress = nil, completion = "So viel Tod und Schmerz. Und zweifellos wird es noch mehr davon geben.\n\nAlles, was ich will, ist doch nur die Umarmung der Göttin spüren, so wie die anderen.\n\nZuerst müssen wir aber versuchen, mehr Leid und Zerstörung zu verhindern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13548] = {title = "Eimer mit Süßigkeiten", objective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][13549] = {title = "Männchen oder Weibchen?", objective = "Chronist To'kini in Zim'Torga möchte, dass Ihr mit To'kinis Blasrohr Frostleoparden und Eispfotenbären einschläfert. Kehrt mit jeweils 3 Weibchen zu ihm zurück.", description = "Ich bin daran interessiert, neben den Artefakten der Drakkari auch ein paar Tiere von Zul'Drak mit mir zurück nach Zandalar zu bringen. Männchen der Frostleoparden und Eispfotenbären habe ich schon – ich brauche aber Weibchen!\n\nZu dumm, dass mein Fallensteller in einem überaus unglücklichen Unfall ums Leben kam. Wäret Ihr vielleicht dazu bereit, für ihn einzuspringen?\n\nSchläfert die Leoparden und Bären mit diesem Blasrohr ein und vergewissert Euch, dass es auch Weibchen sein werden, die Ihr dann zu mir zurückbringt, wenn Ihr so nett wärt. Finden könnt Ihr sie an den Altären von Rhunok, Quetz'lun und Har'koa.", progress = nil, completion = "Wirklich sehr ausgezeichnete Exemplare, &lt;Name&gt;! Sie werden mit Sicherheit für Neugierde und stundenlange Spekulationen unter meinen Kollegen zuhause sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13554] = {title = "Heilung im Dunkeln", objective = "Erhaltet 6 Proben widerlicher Schleim von den Kreaturen in der Klippenquellgrotte.", description = "<Das Gerät spuckt ein paar zusammenhangslose Wortfetzen aus, bevor Hexknalls Stimme wiederzuerkennen ist.>\n\nNachtratten! Sie haben Nachtratten gefressen! Diese kleinen Nervensägen kommen nur von einem Ort, einer Höhle an den Klippen östlich von hier. Ihr müsst nach Nordosten gehen, um zu dem Pfad zu gelangen, der zu den Höhlen führt - sucht nach einer Öffnung unter dem Wasserfall.\n\nDie Nachtratten dort brüten entweder etwas Übles aus, oder jemand hat ihnen einen Verderbniserreger absichtlich zukommen lassen. In jedem Fall brauche ich Proben von dem Zeug!", progress = "Habt Ihr das Zeug bekommen? Je früher ich an einem Heilmittel arbeiten kann, umso schneller können wir die Tiere retten!", completion = "Das sollte mehr als genug sein! Vielen Dank! Ich fange sofort an, an dem Heilmittel für dieses Übel zu arbeiten.", rewards = "RattenhaarwesteSekretbefleckte WesteBeschmutzter StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13556] = {title = "Eier für Dubra'Jin", objective = "Ha'wana in Dubra'Jin möchte, dass Ihr 12 Raptoreier von Gundrak sammelt.", description = "Wie geht's, Mann? Was meinst du, kannst du mir helfen? Bah'Kini braucht 'ne Menge Raptoreier, um sie Dubra'Jin zu opfern.\n\nWas denkst du denn, wieso uns die Drakkari noch nicht überrannt haben?! Ja weil Dubra'Jin uns hilft!\n\nDu musst für uns die Raptoreier sammeln - die sind hier in Gundrak bei den Bäumen. Manchmal tragen die Raptoren sie auch rum, damit sie warm bleiben.", progress = "Wer hätt gedacht, dass der große Dubra'Jin so viele Eier haben will? Was will der eigentlich mit denen?", completion = "Eins, zwei, drei... hehe, das wird reichen, Mann! Jetzt werden wir für 'ne ganze Weile sicher sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13557] = {title = "Der Wächter des Glücks", objective = "Befreit 8 unverderbte Distelbären oder unverderbte Nachtratten aus den Käfigen in der Klippenquellgrotte.", description = "Dieser Schlüssel scheint für die Käfige zu sein, die überall in der Klippenquellgrotte verstreut sind. Tharnariun würde sich sicher freuen, wenn Ihr die Situation nutzt, um die Nachtratten und Distelbären zu befreien, die nicht verderbt wurden und gefangen gehalten werden.", progress = "Ja, <Volk>?", completion = "Gut zu hören, dass Ihr ein paar der Wildtiere befreien konntet. Mit ein wenig Glück werden wir ein Heilmittel finden, bevor die Verderbnis die anderen Tiere umbringt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13558] = {title = "Donner herbeirufen", objective = "Benutzt Aetherions Ritualkugel und erhaltet Aetherions Essenz.", description = "Aetherion ist zwar schon fast in unserer Welt, aber trotzdem können wir ihn noch ausschalten!\n\nAm Ende des Docks schwebt eine Ritualkugel. Ich möchte, dass Ihr mit ihr das Ritual vollendet und den Elementarlord aus seinem Vortex holt.\n\nVertraut mir, <Name>, ich und die anderen von Euch befreiten Geister werden Aetherion extrem schwächen. Allerdings müsst Ihr ihm den letzten Stoß versetzen, um das Volk der Kaldorei aus Dunkelküste vor der Zerstörung zu retten.\n\nBringt die Essenz Aetherions zu Corvine Mondaufgang im Flüchtlingslager, damit er Bescheid weiß.", progress = "Ihr seid zurückgekehrt. Welche Neuigkeiten bringt Ihr mir?", completion = "Yalda? Die Geister der anderen aus den Ruinen von Auberdine?\n\n&lt;Der Druide denkt über Eure Erlebnisse in den Ruinen nach.&gt;\n\nIch kann mich an alle erinnern. Wir werden sie sehr vermissen, aber sie haben nun zum Wohle aller die Umarmung der Göttin gefunden.\n\nAnde'thoras-ethil, mögen Eure Schwierigkeiten geringer werden, &lt;Name&gt;!", rewards = "Aetherionerfüllte WesteKettenhose aus AuberdineIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13559] = {title = "Hodirs Tribut", objective = "Gewöhnlicher Tribut war nicht gut genug für den großen Hodir, als er unter den Frostriesen wandelte.\n\nEr mag zwar nicht mehr bei uns sein, doch wir haben die Tradition beibehalten, seiner Stärke und Weisheit Tribut zu zollen. Es täte Eurem Ruf sehr gut, wenn Ihr Euch an dieser Tradition beteiligen würdet, kleiner <Klasse>.", description = nil, progress = "Gewöhnlicher Tribut war nicht gut genug für den großen Hodir, als er unter den Frostriesen wandelte.\n\nEr mag zwar nicht mehr bei uns sein, doch wir haben die Tradition beibehalten, seiner Stärke und Weisheit Tribut zu zollen. Es täte Eurem Ruf sehr gut, wenn Ihr Euch an dieser Tradition beteiligen würdet, kleiner <Klasse>.", completion = "Die Söhne Hodirs nehmen Euren Tribut an, kleines Wesen. Ihr schreitet voran auf Eurem Weg, Euren Wert als Verbündeter zu beweisen - auf mehr als eine Art.", rewards = nil}
MultiLanguageQuestData['de'][13560] = {title = "Der nicht so tiefe Ozean", objective = "Gorbold Stahlhand möchte, dass Ihr Gary aufsucht, um weitere Anweisungen zu erhalten.", description = "Ihr seht sehr fähig aus!\n\nAn der Küste hier sind viele Wracks - viele alte und ein paar neue. Ich versuche schon seit einiger Zeit, mich darum zu kümmern und die wertvollen Reste besser zu nutzen, aber die Murlocs, die sich dort breitgemacht haben, haben andere Vorstellungen. Ich habe viele Abenteurer losgeschickt und keiner kam zurück.\n\nSorgt Euch nicht, ich habe meine Lektion gelernt und Euer Schicksal wird ein anderes sein. Schwimmt in Richtung Norden und sucht Gary - er wird Euch den neuen Plan erklären. Es ist ganz einfach.", progress = nil, completion = "Die Ablenkung hat also funktioniert? Gut! Macht Euch wegen der Schätze keine Sorgen. Ich und Gary werden uns darum kümmern, diesmal.\n\nUm ehrlich zu sein glaube ich, dass sie mich aus der Stadt verjagen würden, wenn noch mehr schief läuft und noch ein weiterer Abenteurer verloren geht.", rewards = "SchiffswrackbogenAuf Euch wartet eine dieser Belohnungen:\n\nLeuchtendes Murlocauge\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13561] = {title = "Trost für die Hochgeborenen", objective = "Tötet 6 verfluchte Hochgeborene und 6 zuckende Hochgeborene.", description = "Ich bin nach Bashal'Aran gekommen, um den besorgten Geistern der Hochgeborenen Frieden zu gewähren, aber mit jedem Hieb scheint meine Hand sich mehr zu wehren. Wenn Ihr mir helfen wollt, so könnt Ihr Euch meiner Dankbarkeit sicher sein.", progress = nil, completion = "Ihr habt meinen Dank. Und auch wenn man es ihnen nicht anmerkt, den Dank der Geister der Hochgeborenen habt Ihr auch.\n\nEine sichere Reise wünsche ich Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13562] = {title = "Die letzte Flamme von Bashal'Aran", objective = "Löscht die letzte Flamme von Bashal'Aran aus.", description = "In Zeiten wie diesen müssen wir innehalten und unsere Lebensweise überdenken. Wir sind nun sterblich und egal, wie sehr wir auch etwas anderes bevorzugen würden, wir verdienen den Platz, den wir nun in dieser Welt einnehmen.\n\nBashal'Aran, einst die Stadt unserer Vorfahren, ist nun die Heimat ihrer verfluchten Geister. Ihr findet Bashal'Aran, wenn Ihr der Straße in Richtung Süden folgt. Wir hatten Hoffnung gehegt, Rettung zu finden, aber wir haben sie zu lange leiden lassen. Es ist an der Zeit, die letzte Flamme von Bashal'Aran auszulöschen.", progress = nil, completion = "Ihr habt unseren Dank. Es ist an der Zeit, die Vergangenheit hinter uns zu lassen und uns der Zukunft zu widmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13563] = {title = "Ewige Liebe", objective = "Befreit den Geist von Anaya Dämmerflucht und erhaltet ihren Anhänger.", description = "Ich möchte Euch meinen Dank für unsere Rettung aussprechen. Man könnte behaupten, ich hätte Glück gehabt, doch meine geliebte Anaya ist schon lange tot. Ich bin einsam und in Schwierigkeiten und leider benötige ich schon wieder Eure Hilfe.\n\nNach meiner Rettung bin ich in den Wäldern von Dunkelküste umhergewandert und habe die Ruinen von Bashal'Aran entdeckt... und sah den Geist meiner geliebten Anaya.\n\nSie muss befreit werden, doch ich selbst bekomme es nicht übers Herz. Ihr Geist muss zerstört werden.", progress = "Es ist mir irgendwie gelungen, nicht mit dem gleichen Gift in Berührung zu kommen wie all die anderen. Doch in gewissem Sinne beneide ich sie sogar... eine Ewigkeit in Einsamkeit zu verbringen erscheint kaum lebenswert.\n\nIch vermisse dich so sehr, Anaya.", completion = "Ich danke Euch, &lt;Name&gt;. Vielleicht wäre es besser gewesen... wenn ich es selbst getan hätte. Doch selbst nach Tausenden von Jahren konnte ich die Hand nicht gegen sie erheben.\n\nIch bitte Euch, lasst mich nun allein in meiner Trauer...", rewards = "Rastlose GamaschenTrostloser SchildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13564] = {title = "Ein verlorener Freund", objective = "Findet Grimmklaue.", description = "Bitte helft mir... Ich kann mich kaum aufsetzen.\n\nMein Freund, ein Bär namens Grimmklaue, ist nicht hier. Ich habe ihn vorausgeschickt, um den Schildwachen unsere Ankunft anzukündigen, bevor wir Auberdine verließen, doch er kam nie an. Ich spürte bereits, dass etwas nicht in Ordnung war, als wir uns auf den Weg machten, aber durch die Evakuierung konnte ich der Angelegenheit nicht nachgehen.\n\nSollte er sich verletzt haben, so gibt es nur einen Ort, den er aufsuchen würde: das Welkende Dickicht nördlich von Auberdine, an der Straße südlich von hier. Bringt ihn sicher zu mir zurück... ich habe niemanden außer ihm.", progress = nil, completion = "Seid gegrüßt. Ihr scheint Interesse an meinem Freund zu haben. Ich nehme an, sein Freund Volcor hat Euch geschickt? Wenn er nicht selbst gekommen ist, so muss auch er verwundet sein. Ich hoffe, er wird bald gesunden.\n\nGrimmklaue ist zu schwer verletzt, um weit transportiert werden zu können, und er muss dringend behandelt werden. Ich fürchte, ich kann nicht zulassen, dass Ihr ihn mitnehmt, aber vielleicht könnt Ihr mir dabei helfen, mich um ihn zu kümmern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13565] = {title = "Zweiten Grades", objective = "Benutzt die versteinerte Wurzel, ruft 6 siechende Ents und entledigt Euch Lady Janiras, der Anführerin der Naga.", description = "Unbesonnene Gewalt können wir nicht gutheißen - das liegt nicht in unserer Natur. Doch mitunter bringt die Vermeidung von Kämpfen unübersehbare Folgen mit sich, wie in unserem Fall mit den Naga.\n\nAls die Erde in dieser Gegend brach, erschienen östlich von hier kleine Ruinen. Diese Ruinen waren einst die Heimat der Untertanen Königin Azsharas. Nun scheint es, als sei dieses Volk auf der Suche nach etwas zurückgekehrt.\n\nNehmt diese versteinerte Wurzel. Ihr könnt sie auf ihre Gefallenen anwenden und Ents zu Hilfe rufen. Kümmert Euch schleunig um sie und ihre Anführerin.", progress = nil, completion = "Ich danke Euch, Verbündeter. Wir werden wachsamer sein, sollten sie wiederkehren.", rewards = "Moosige StiefelNagaschuppenarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13566] = {title = "Materialien für das Ritual", objective = "Besorgt 3 Schnurrhaare eines Mondpirschers, 3 Büschel gefleckter Rehhaare und 3 Proben Distelbärenfell.", description = "Während wir uns um Grimmklaue kümmern, möchte ich Euch bitten, kampflos von den Wildtieren ein paar Materialien für das Ritual zu sammeln.\n\nIch benötige Schnurrhaare eines Mondpirschers westlich von hier - geht zu den schlafenden Mondpirschern und versucht, ihnen die Haare auszureißen, und entfernt Euch, bevor sie aufwachen.\n\nIch brauche auch Haare der Rehe östlich von hier, aber meidet die Hirsche.\n\nUnd zu guter Letzt brauche ich das Fell der Bären beim Wasser nordöstlich von hier. Wartet, bis sie einen Fisch gefangen haben, besorgt die Fellprobe, und entfernt Euch von den Bären, bevor sie aufgegessen haben.\n\nBitte, fügt ihnen keine Schmerzen zu.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe? Und bitte sagt mir, dass Ihr den Tieren keine Schmerzen zugefügt habt, um sie zu erhalten.", completion = "Diese Materialien sind perfekt. Sie sind die letzten Zutaten für einen speziellen Weihrauch, an dem ich arbeite. Ich werde es Euch gleich erklären - lasst mich die Zutaten nur schnell vermischen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13567] = {title = "Der Geist des Hirsches", objective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Hirschgeists einzuholen.", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister verschreiben.\n\nWenn Ihr Euch mit dem großen Hirschgeist verbünden wollt, so bringt diesen Weihrauch zu den Wäldern nördlich von Bashal'Aran. Meditiert vor dem großen Geist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", progress = nil, completion = "Ich sorge für mein Volk. Ich führe es nicht mit Gewalt, sondern mit Weisheit und Schnelligkeit. Weisheit leitet uns tiefer in die Wälder, wenn Gefahr droht, und Schnelligkeit sorgt dafür, dass unsere Feinde nur noch unsere Abwesenheit feststellen können.\n\nDank meiner Weisheit kann ich Eure wahren Absichten hinter der Bitte nach meinem Segen sehen und weiß, dass Ihr den Segen meiner Schnelligkeit verdient. Ihr werdet ihn erhalten, doch Ihr müsst Euch darüber im Klaren sein, dass die anderen Geister Euch nicht mehr willkommen heißen werden, sobald Ihr ihn habt. Überlegt Euch gut, ob dies Euren Wünschen entspricht, bevor ich Euch meinen Segen erteile.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRitual Bond Quest Complete"}
MultiLanguageQuestData['de'][13568] = {title = "Der Geist des Mondpirschers", objective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Mondpirschergeists einzuholen.", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister zuschreiben.\n\nWenn Ihr Euch mit dem großen Mondpirschergeist verbünden wollt, so bringt diesen Weihrauch in die Länder südlich der Ruinen von Lornesta. Meditiert vor dem großen Mondpirschergeist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", progress = nil, completion = "Ich teile diese Wälder gerne und akzeptiere Nachtelfen in meiner Heimat - manchmal bezeichne ich sie sogar als Freunde. Auch wenn sie in letzter Zeit viel unter der Verderbnis gelitten haben, so kann ich doch in Euch die gleiche Stärke, Ehre und auch das Temperament sehen, das ich an ihnen schätze.\n\nWenn Ihr den Wert der Wildheit erkennt, die zur Bezwingung mancher Probleme wichtig ist, so bin ich bereit, Euch meinen Champion zu nennen. Ihr müsst jedoch wissen, dass Euch die anderen Geister nicht akzeptieren werden, wenn Ihr Euch mir verschreibt. Überlegt Euch diese Entscheidung gut.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRitual Bond Quest Complete"}
MultiLanguageQuestData['de'][13569] = {title = "Der Bund des Rituales", objective = "Atmet den Weihrauch vor Bewahrer Karithus ein und trefft eine Entscheidung zwischen dem Segen des großen Hirschgeistes, des großen Distelbärgeistes und des großen Mondpirschergeistes.\n\nNur einer der Geister kann Euch seinen Segen erteilen, also wählt weise.", description = "Ich werde mich um Grimmklaue kümmern, bis er sich vollständig erholt hat. Bald wird er bereit sein, in seine Heimat zurückzukehren. Ich habe eine weitere Aufgabe für Euch, während wir warten...vielmehr möchte ich Euch einen Gefallen tun, wenn Ihr dies wünscht.\n\nDie großen Geister der Wildtiere sind unter uns und warten auf Hilfe, um die Zerstörung aufzuhalten. Sie sind immer bei uns, auch jetzt, und mit den Materialien, die Ihr mir gebracht habt, kann ich Euch ermöglichen, sie zu sehen. Sprecht mit den Geistern, wählt einen von ihnen und kehrt mit dem Segen dieses Geistes zu mir zurück.", progress = nil, completion = "Es ist vollbracht. Ihr habt den Segen eines der großen Geister erhalten und nun kann ich das Ritual mit Euch abschließen. Bitte haltet still.", rewards = "MondpirscherarmschienenUmhang des HirschesDistelbärgurtDer folgende Zauber wird auf euch gewirkt:\n\nRituelle Bindung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13570] = {title = "Zum Andenken an Auberdine", objective = "Ich möchte Euch meinen tiefsten Dank für Eure Hilfe aussprechen. In meiner Trauer habe ich Euch zuvor nicht die Dankbarkeit entgegengebracht, die Ihr verdient hättet. Ohne Euch wären wir jetzt wohl nicht hier.\n\nSeid Euch gewiss, dass Ihr hier immer Freunde haben werdet.\n\nUnd sorgt Euch nicht um meine Einsamkeit. Grimmklaue ist gute Gesellschaft und er bietet mir mehr Trost, als ich erwartet hätte.\n\nNehmt dies und unseren Segen, bis wir einander wiedersehen, <Name>.", description = nil, progress = nil, completion = nil, rewards = "Cerelleans DolchWeißklauendolchDunkelküstenbogenIhr bekommt:\n\nWelkchen"}
MultiLanguageQuestData['de'][13571] = {title = "Fletchers Fundbüro", objective = "Durch den Gestank nach etwas Abgestandenem und Ungewaschenem hindurch dringt Euch bekannter Geruch in die Nase! Es scheint, als wäre dieser einst so mächtige Abenteurer ganz verrückt nach Kungaloosh.\n\nAls Ihr durch die Gitterstäbe schaut, könnt Ihr gerade so eben das Rezept erkennen, das auf seinem Arm steht...", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nKungaloosh\n\nDer folgende Zauber wird auf euch gewirkt:\n\nKungaloosh"}
MultiLanguageQuestData['de'][13572] = {title = "Jadefeuerkohlenpfannen", objective = "Gren Fetzfell in der Schwarzfellfeste möchte, dass Ihr 8 Jadefeuerkohlenpfannen zerstört.", description = "Die Satyrn aus Teufelswald haben angefangen, Hass und Verderbnis in unsere Länder zu bringen. Sie haben Sharax den Schänder geschickt, um Teile des Waldes zu unterwerfen, den wir Schwarzfelle unsere Heimat nennen.\n\nEr vergiftet nicht nur das Land, die Tiere und die Pflanzen, sondern hat auch überall im Dorf Jadefeuerkohlenpfannen aufgestellt, die ihm dabei helfen, Kontrolle über mein Volk zu erlangen. Die Kohlenpfannen zu zerstören, wird ihn allein nicht aufhalten können, aber es wird seinen Einfluss mindern, während wir mit dem Ältesten Brolg zusammen unsere Brüder befreien können.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Dank Euren Anstrengungen können wir vielleicht die übrigen Schwarzfelle retten.", rewards = "Zerrissener FellgürtelFeuerstampferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13573] = {title = "Malfurions Rückkehr", objective = "Sucht nach Malfurion Sturmgrimm beim Auge des Vortex südöstlich des Flüchtlingslagers in Dunkelküste.", description = "Wir haben erst vor kurzem die Neuigkeiten von Malfurions Erwachen gehört, nur Augenblicke, bevor der Kataklysmus über uns hereinbrach.\n\nKaum, dass er zu sich gekommen war, stieß er eine mysteriöse Warnung aus: das Land würde sich spalten, wenn nichts unternommen würde, und die Schockwellen würden über Dunkelküste zusammenlaufen.\n\nDann machte er sich - Berichten zufolge - in diese Richtung auf. Ich wurde hierher geschickt, um nach ihm zu suchen, habe aber nun alle Hände damit zu tun, den Flüchtlingen zu helfen.\n\nVielleicht könnt Ihr für uns südöstlich von hier nach ihm suchen.", progress = nil, completion = "Es gilt, keine Zeit zu verschwenden, &lt;Klasse&gt;. Es nimmt jedes bisschen meiner Energie in Anspruch, die Landmasse Dunkelküstes zusammenzuhalten und zu verhindern, dass sie einfach in den Ozean gerissen wird... Ihr müsst mir gut zuhören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13575] = {title = "Das Land im Blut", objective = "Sprecht mit dem Ältesten Braunpfote im Lager der Schwarzfelle südwestlich des Auges des Vortex.", description = "Wenn wir die Naturgewalten stabilisieren möchten, so können wir jedes bisschen Hilfe gebrauchen. Die Furbolgs des Schwarzfellstammes haben diese Gegend schon lange zu ihrer Heimat erklärt und sind mit dem Land eng verbunden.\n\nIhr Schamane und Ältester Braunpfote hat große Macht über die Elemente. Seine Hilfe wäre von unschätzbarem Wert. Versucht, ihre Unterstützung zu erhalten.", progress = nil, completion = "Dem großen Malfurion Sturmgrimm zolle ich viel Respekt. Ich kann mein Volk in diesen schlimmen Zeiten jedoch nicht alleine lassen. Vielleicht gibt es eine Möglichkeit, wie wir einander helfen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13576] = {title = "Gegenseitige Hilfe", objective = "Benutzt das besänftigende Totem, um die Überreste von 8 unbändigen Feuerelementaren zu absorbieren.", description = "Da viele meiner Brüder vom Wahnsinn oder von der Verderbnis eingenommen worden sind, habe ich kaum eine Wahl, als mich mit Euch zu verbünden. <Volk>, Ihr könnt auf unsere Hilfe zählen... sobald ich weiß, dass ich auf Eure zählen kann.\n\nWie Ihr sehen könnt, haben wir hier ein paar Probleme mit den Feuerelementaren. Helft uns, sie zu bekämpfen, und wendet dieses Totem auf ihre feurigen Überreste an.\n\nWir werden dafür sorgen, dass sie dahin zurückgehen, wo sie herkamen - ob es ihnen gefällt oder nicht.", progress = nil, completion = "Das Element Feuer ist einzigartig in seiner Eigenschaft, sich oft weiter auszubreiten, wenn man es willkürlich angreift... und so den Flammen noch mehr Angriffslust verleiht.\n\nWir werden jedoch besonnen vorgehen, &lt;Name&gt;. Wir werden es endgültig bekämpfen.", rewards = "Versengte StiefelVersengter SchildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13577] = {title = "Der letzte Wildekin", objective = "Sprecht mit Aroom beim Mondbestrahlten Bau nördlich vom Auge des Vortex.", description = "Es gab einst viele Wildekin in Dunkelküste. Sie waren so eng mit dem Land verbunden, das vom Kataklysmus zerstört wurde, dass ihre Zahlen stark zurückgingen.\n\nAroom ist der letzte Wildekin seines Stammes; er ist ein mächtiger Ältester mit einer starken Verbindung zu Elune. Seine Hilfe wird zur Heilung des Landes unumgänglich sein. Ihr könnt ihn nördlich von hier beim Mondbestrahlten Bau finden.", progress = nil, completion = "Die Kreatur scheint versunken in tiefe Trauer. Ihre Augen starren durch Euch hindurch, als Ihr Euch nähert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13578] = {title = "Arooms Abschied", objective = "Erhaltet 8 Federn von getöteten Wildekin.", description = "<Die Kreatur ruft traurig, und wendet sich Euch zu.>\n\nAroom ist Letzter von Stamm...\n\nAndere nicht ruhen... brauchen Scheiterhaufen. Bringt Aroom Federn der anderen... sie müssen ruhen.\n\nAroom hilft Euch dann.", progress = "Ihr bringt Federn?", completion = "Ich danke Euch. &lt;Volk&gt;, bald kann mein Stamm ruhen.", rewards = "WildekinklauendolchGürtel aus EulenbestienfedernIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13579] = {title = "Der Beschützer von Ameth'Aran", objective = "Sprecht mit Selenn in den Ruinen von Ameth'Aran.", description = "Nichts heilt das Land schneller als die Stärke seiner Bewohner. Wir Nachtelfen haben das Glück, dass ein paar unserer besten Verbündeten sowohl das Land als auch dessen Bewohner zugleich sind. \n\nSelenn, ein Urtum des Krieges, wurde mit der Bewachung der Ruinen von Ameth'Aran südlich von hier beauftragt. Geht dorthin und ersucht seine Hilfe.", progress = nil, completion = "Wenn der große Malfurion meine Anwesenheit verlangt, so ist es meine Pflicht, dieser Aufforderung Folge zu leisten. Es ist aber auch meine Pflicht, diese Ruinen zu beschützen.\n\nVielleicht könnt Ihr mir helfen, beiden Aufgaben nachzukommen, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13580] = {title = "Die Elemente beruhigen", objective = "Platziert das aufgeladene Besänftigungstotem auf der Spitze des Gezackten Riffs am Lodernden Strand und beschützt es, bis das Ritual abgeschlossen ist.", description = "Die Geister der Feuerelemente sind nun in dem Totem aufbewahrt. Bringt es zur Spitze des Gezackten Riffs am Lodernden Strand und platziert es dort.\n\nDie besänftigende Energie des Totems wird die Elementare langsam umspülen, bis ihre Wut abgeklungen ist.\n\nIhr müsst das Totem beschützen, denn Feuer reagiert auf das Ritual der Besänftigung alles andere als wohlgesinnt.", progress = nil, completion = "Wir stehen in Eurer Schuld, &lt;Name&gt;. Vielleicht können wir nun mit Malfurions Hilfe den Rest von Dunkelküste retten.", rewards = "SterndeuterwesteFeurige ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13581] = {title = "Der Schwur der Schwarzfelle", objective = "Kehrt zu Malfurion Sturmgrimm beim Auge des Vortex zurück.", description = "Es wird zwar nicht unverzüglich geschehen, doch bald wird der Ärger der Elementare abklingen und mein Volk wird weiterleben.\n\nIch werde Euch und Malfurion helfen, soweit es in meiner Macht steht.", progress = nil, completion = "Das sind gute Nachrichten, &lt;Name&gt;. Die Furbolgs mögen auf den ersten Blick wie ein Volk der Wilden erscheinen, aber ihre Verbindungen zum Land sind uralt und ihre Schamanen sind ohnesgleichen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEye of the Vortex - Detect Quest Invisibility 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13582] = {title = "Das Feuer Elunes", objective = "Erhaltet Elunes Fackel von Horoo dem Flammenbewahrer.", description = "Wir brauchen für Ritual besondere Flamme - Feuer Elunes.\n\nGeist Horoo ist östlich von hier. Horoo trägt Elunes Flamme. Bringt Flamme, um Geister zu Ruhe zu bringen.\n\nIhr habt Arooms Dank.", progress = "Ihr habt Fackel?", completion = "&lt;Aroom heult in tiefen Tönen auf.&gt;\n\nEndlich Brüder können ruhen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13583] = {title = "Der Schwur der Wildekin", objective = "Kehrt zu Malfurion Sturmgrimm beim Auge des Vortex zurück.", description = "Wildekin bei Elune. Aroom in Eurer Schuld.\n\nAroom hilft Euch. Kehrt zu Malfurion zurück. Aroom kommt nach.", progress = nil, completion = "Die Wildekin waren einst die Wächter des Landes. Es ist gut zu hören, dass Aroom dies nicht vergessen hat.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReaktion erzwingen 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13584] = {title = "Die Erde beruhigen", objective = "Tötet 8 wütende Erdelementare.", description = "Ich würde meine Verantwortung vernachlässigen, wenn ich meinen Posten verließe, gerade jetzt, wo so viele Elementare in den Ruinen außer Kontrolle herumtoben.\n\nLasst uns zuerst die Elementare beseitigen, bevor wir uns überlegen, wie wir Malfurion helfen können. Was meint Ihr, <kleiner/kleine:c> <Klasse>?", progress = nil, completion = "Es ist offensichtlich, &lt;Name&gt;. Die Elemente werden sich nicht beruhigen, bis Malfurion das Gleichgewicht wieder ins Land gebracht hat. Wenn ich ihm helfe, so gehe ich gewissermaßen auch meiner Arbeit nach.", rewards = "Erdverkrustete KetteErdgeborener StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13585] = {title = "Der Eid, zu beschützen", objective = "Sprecht mit Malfurion Sturmgrimm beim Auge des Vortex in Dunkelküste.", description = "Ich bin meiner Aufgabe hier so gut wie möglich nachgegangen. Sagt Malfurion, dass ich so bald wie möglich kommen werde.\n\nIch wünsche Euch viel Glück, <Name>. Ich wünsche uns allen viel Glück.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Selenns Hilfe dabei, den Vortex zurückzuhalten, wird unschätzbar wertvoll sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEye of the Vortex - Detect Quest Invisibility 3\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13586] = {title = "Der Smaragdgrüne Traum", objective = "Begebt Euch durch das Alptraumportal in der Erdspaltergrotte und sprecht mit Thessera.", description = "Unsere Anstrengungen, die Zerstörung aufzuhalten, scheinen bisher nicht ausreichend. Ich befürchte, dass wir Hilfe jenseits dieser Welt benötigen werden.\n\nDie Schattenhammerkultisten haben in der Erdspaltergrotte östlich von hier ein Portal zum von Alpträumen geplagten Smaragdgrünen Traum erstellt. Dort halten sie einen Drachen namens Thessera gefangen.\n\nGeht durch das Alptraumportal und befreit sie. Sie wird eine mächtige Verbündete für uns sein.", progress = nil, completion = "Malfurion ruft? Ja... ich kann seine Stimme durch den Traum hindurch hören...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13587] = {title = "Der erwachende Alptraum", objective = "Erhaltet die smaragdgrüne Schriftrolle von dem Alptraumwächter in der Erdspaltergrotte.", description = "Malfurions Worte sind wahr, <kleiner/kleine:c> <Klasse>. Der Riss droht, Dunkelküste zu spalten und unsere Welt von der Euren zu trennen.\n\nLasst mich Euch helfen, solange ich kann, bevor der Riss die Zerstörung beider Orte beschleunigt.\n\nZuerst müsst Ihr mich von meinen Fesseln befreien; erlangt die smaragdgrüne Schriftrolle von dem Wächter, der in den Hallen unter uns zu finden ist.", progress = "Habt Ihr es geschafft, <Name>?", completion = "Ich danke Euch, &lt;Name&gt;. Ihr habt mir meine Freiheit geschenkt. Nun lasst uns sehen, was ich Euch und Eurer Welt Gutes tun kann.", rewards = "Ihr bekommt:\n\nThesseras Gabe"}
MultiLanguageQuestData['de'][13588] = {title = "Das Auge aller Stürme", objective = "Fliegt mit Thessera und zerstört 12 Zwielichtreiter und das Zwielichtportal.", description = "Zwielichtreiter kreisen über dem Vortex. Ich fürchte, es ist ihre Magie, die die kataklysmischen Kräfte gegen unsere Anstrengungen sichert.\n\nFliegt mit Thessera los, um die Reiter und das Portal, aus dem sie kamen, zu zerstören.", progress = nil, completion = "Das Blatt hat sich gewendet, &lt;Name&gt;. Wir sollten in der Lage sein, weiteren Schaden zu vermeiden.\n\nEs gibt aber immer noch viel zu tun.", rewards = "SmaragdwesteHammer des PortalverschließersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13589] = {title = "Die Eindringlinge der Splitterspeere", objective = "Meldet Euch bei Leutnant Morra Sternenhauch bei den Ruinen von Mathystra.", description = "Als ob wir mit dem Land und den gegen uns gewandten Elementen nicht schon genug zu tun hätten, scheint es jetzt auch noch, als habe etwas die Trolle im Nordosten aufgewiegelt. Sie marschieren für den Kampf auf. Ich weiß nicht genau, was sie vorhaben, aber sie haben bereits ein paar unserer Späher angegriffen und belagern die Kultisten beim Turm von Althalaxx.\n\nWir haben einen Trupp unserer besten Schildwachen losgeschickt, um ihrem Angriff entgegenzutreten. Ich bin mir sicher, dass sie Hilfe gebrauchen könnten, also wäre es gut, wenn Ihr Euch zu den Ruinen nordöstlich von hier begebt und Euch ihnen anschließt.", progress = nil, completion = "Glynda hat Euch geschickt, um uns zu helfen, ja? Es war weise von ihr, das zu tun. Ich kann Hilfe sicherlich gebrauchen.\n\nIch arbeite gerade unseren Erstlingsplan aus, um ihre Ränge nach und nach zu dezimieren. Bitte helft in der Zwischenzeit Tysha und Balthule aus, wenn Ihr könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13590] = {title = "An vorderster Front", objective = "Meldet Euch bei Jägerin Sandrya Mondsturz im Splitterspeertal.", description = "Ihre Streitmächte sind geschwächt, die Vorräte zerstört und die Befehlshaber zweiten Rangs sind tot. Es ist an der Zeit, den Kampf in ihr Territorium zu verlagern und ihren Anführer zu töten. Ich bin zugegebenermaßen immer noch nicht sicher, wo die plötzliche Aggression ihren Ursprung fand, aber vielleicht finden wir in ihrem Lager weitere Informationen.\n\nNehmt den Pfeil, den Balthule vorbereitet hat, und meldet Euch bei Sandrya Mondsturz im Splitterspeertal, um am Angriff teilzunehmen. Am besten sichert Ihr Euch einen Platz auf einem unserer Nachtsäbler - zu Fuß ist es zu gefährlich.", progress = "Seid gegrüßt, <Klasse>. Habt Ihr den Pfeil?", completion = "Gut, Euch zu treffen. Ich habe von Euren Anstrengungen, uns zu helfen gehört, und ich muss zugeben, dass ich von Eurer Hilfe gegen die Trolle ein wenig beeindruckt bin. Wir befinden uns am Ende der Schlacht und ich hoffe, Ihr seid gut vorbereitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13591] = {title = "Beunruhigende Verbindungen", objective = "Bringt Höllschreis Brief zu Waldläuferin Glynda Nal'Shea in Lor'danel.", description = "Der Brief von Garrosh Höllschrei bestätigt den Verdacht, der während der Offensive im Splitterspeertal aufkam. Die Anwesenheit der Verlassenen bei den Ruinen des Turms, die Vorräte der Horde und ihre Vollstrecker im Kriegslager der Splitterspeere sind erst der Anfang. Garrosh selbst hat die Splitterspeere kontaktiert, um die Offensive in Richtung Lor'danel zu treiben, und es scheint, als habe er offensichtlich auch vor, von Süden vorzustoßen.\n\nGlynda Nal'Shea benötigt diese Informationen, um die Nachtelfen auf den Angriff vorbereiten zu können.", progress = "Ihr seid zurück! Ich habe gehört, die Schlacht ist gut verlaufen?", completion = "Nun, das sind in der Tat beunruhigende Neuigkeiten. Ich werde sofort Boten nach Eschental senden und versuchen, Verstärkung für sie aufzustellen.\n\nIch kann Euch für all Eure Hilfe in diesen schlimmen Zeiten nicht genug danken. Heldenhafte Taten wie die Euren verdienen eine Belohnung. Ich glaube, ich habe etwas, dass Euch gute Dienste leisten wird.", rewards = "Silberbestickter UmhangSilbergestanzte StiefelSilberschuppengürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13592] = {title = "Feldübungen eines Recken", objective = "Sir Marcus Barlow beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Selbst wenn wir für den Wettkampf trainieren, ist es gut, nicht zu vergessen, dass die Geißel noch immer da draußen ist.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13593] = {title = "Recke von Sturmwind", objective = "Sprecht wieder mit Marschall Jacob Alerius, falls Ihr ein Recke von Sturmwind werden wollt.", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation von Sturmwind beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Sturmwind ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Wir sind stolz, dass Ihr eingewilligt habt, mit uns zu trainieren und in unserem Namen anzutreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13594] = {title = "Vergesst die Horde nicht", objective = "Tötet 10 beliebige Mitglieder der Horde in Bathrans Schlupfwinkel.", description = "Evenar und die anderen Schüler taugen vielleicht nicht viel für den Kampf, aber Ihr seht so aus, als ob Ihr Euch recht wacker schlagen würdet. Dem Abschaum der Horde am anderen Ende der Straße Richtung Osten in Bathrans Schlupfwinkel muss eine Lektion erteilt werden.\n\nIhr neuer Kriegsfürst Garrosh Höllschrei führt mit ihnen nichts Gutes im Schilde. Wollt Ihr ihnen Manieren beibringen?\n\nIch würde Euch begleiten, aber mein Befehl lautet, hier zu bleiben und Orendils Schüler zu beschützen – und genau das werde ich auch tun.", progress = nil, completion = "&lt;Die Schildwache blickt Euch einen Augenblick anerkennend an.&gt;\n\nIhr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Wenn die anderen Abenteurer, die wir noch zu Gesicht bekommen werden, Euch auch nur ein wenig ähneln, sollten wir diesen Krieg gegen die Orcs und ihre Horde schneller hinter uns gebracht haben, als erwartet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13595] = {title = "Mit ihren eigenen Waffen", objective = "Erbeutet eine Wildfeuerflasche und werft sie auf Bathrans Leichnam, um ihn zu verbrennen.", description = "Diese Kreaturen... diese sogenannte Horde... Sie haben mich in meinen besten Jahren gefällt und sie ernten mein Haar für ihre finsteren Pläne.\n\nWerdet Ihr mir helfen, dem ein Ende zu bereiten, <Volk>?\n\nIch habe zufällig ein paar ihrer Kräuterkundigen von etwas sprechen hören, das sie Wildfeuer nannten, am Tisch entlang des Weges. Wenn Ihr die Flasche dieses widernatürlichen Zeugs nehmen und es auf meinen toten Körper im Nordosten werfen würdet, würde er verbrennen und mein Haar würde hier nicht mehr wachsen.\n\nIch bin schon tot und es ist ein kleiner Preis, um sie aufzuhalten.", progress = "All Eure Leben sind so kurz. Warum besteht Ihr darauf, sie damit zu vergeuden, Euch gegenseitig umzubringen?", completion = "Ihr habt mir geholfen, zur Erde zurückzukehren, &lt;Name&gt;.\n\nJetzt wird mein Haar nicht länger für diese Kreaturen sprießen. Besser noch: Ich werde umso baldiger wieder wachsen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13596] = {title = "Schattenhammerpläne", objective = "Erhaltet 6 Schattenhammerpläne aus dem Lager der Schattenhammer.", description = "Wir wissen nicht genau, welche Ziele die Schattenhammerkultisten südwestlich von hier verfolgen. Wir fürchten, sie wollen Lor'danel angreifen, allerdings können ihre Motive weitaus tiefer liegen.\n\nBegebt Euch zum Lager der Schattenhammer und besorgt ihre Pläne so schnell Ihr könnt, <Name>. Uns bleibt möglicherweise nicht viel Zeit.", progress = "Habt Ihr die Pläne, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Gebt mir einen Moment, um mit ihren Plänen vertraut zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13597] = {title = "Der Geist des Distelbären", objective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Distelbärgeists einzuholen.", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister verschreiben.Wenn Ihr Euch mit dem großen Distelbärgeist verbünden wollt, so bringt diesen Weihrauch zu der Höhle östlich des Strudels. Meditiert vor dem großen Distelbärgeist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", progress = nil, completion = "Seit ewigen Zeiten durchstreife ich diese Wälder und lebe in diesen Bergen. Durch Schnee und Feuer sah ich Zivilisationen kommen und gehen, während die Natur besteht. Nun hat sich die Erde selbst gegen uns gewandt und es ist offensichtlich, dass wir kämpfen müssen, um unser Vermächtnis zu bewahren.\n\nEuer Herz ist aufrecht und ich würde Euch als meinen Champion wählen. Wenn Euch die dicke Haut und Resistenz der Distelbären am Herzen liegt, so nehmt meine Gabe an. Ihr solltet jedoch wissen, dass Ihr danach von den anderen Geistern nicht mehr akzeptiert werdet, also entscheidet Euch weise.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRitual Bond Quest Complete"}
MultiLanguageQuestData['de'][13598] = {title = "Widerliche Arznei", objective = "Sammelt 6 rauchende Fliegenpilze.", description = "Mit Hilfe meiner Heilmagie habe ich keine Zweifel, dass Grimmklaue sich wieder erholen wird. Von den Wilderern jedoch, die ihm das zugefügt haben, kann ich nicht dasselbe sagen. Um während seiner Genesung seine Schmerzen zu lindern und seine Wunden zu behandeln, wäre allerdings eine Salbe von Nutzen.\n\nÖstlich von hier befinden sich die Ruinen von Lornesta. Dort unter den Steinen wachsen verschiedene rauchende Fliegenpilze, die in der feuchten Umgebung wunderbar gedeihen. Bringt mir ein paar der Fliegenpilze, sodass ich eine Salbe für unseren Freund zubereiten kann.", progress = "Grimmklaue ist ein recht hartnäckiger Kämpfer. Ich habe ein wenig Mitleid mit den Wilderern, obwohl ihre Absichten abscheulich waren.", completion = "Ihr habt meinen Dank, Jüngling. Mit dieser Salbe sollte sich Grimmklaue um einiges schneller erholen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13599] = {title = "Grimmklaues Rückkehr", objective = "Kehrt zu Volcor und Grimmklaue in Lor'danel zurück.", description = "Nun, da der Bund geschlossen ist, liegt der Segen auf Euch. Es wird Euch das Reisen in diesen Landen sehr erleichtern.\n\nGrimmklaue hat sich vollständig erholt. Er hat sich auf den Weg nach Lor'danel gemacht, bevor ich etwas sagen konnte. Das bedeutet wohl, dass auch der Zeitpunkt Eurer Abreise gekommen ist.\n\nEs hat mich sehr gefreut, Eure Bekanntschaft zu machen. Lebt wohl, und leitet meine besten Wünsche an Volcor und Grimmklaue weiter.", progress = nil, completion = "Ihr seid zurückgekehrt! Es ist gut, Euch wiederzusehen. Ich gehe davon aus, dass wir Euch für Grimmklaues Rückkehr zu danken haben?\n\nLeider... habe ich schlechte Neuigkeiten. Ich konnte das Gift nicht neutralisieren... ihr Zustand hat sich verschlechtert. Gershalla starb kurz nach Eurer Abreise und Volcor... Volcor starb kurz vor Eurer Rückkehr.\n\nDie sichere Rückkehr Grimmklaues hat er noch erlebt und er starb mit einem Lächeln im Gesicht. Ich wünschte nur, ich hätte mehr für ihn tun können.\n\nNun muss ich all meine Kräfte darauf richten, Shaldyn zu retten, also entschuldigt mich bitte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13600] = {title = "Eine würdige Waffe", objective = "Bringt Marschall Jacob Alerius beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "&lt;Der Marschall nimmt die Klinge von Drak'Mar entgegen.&gt;\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13601] = {title = "Hilfe für die Flüchtlinge", objective = "Schildwache Lendra in Lor'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.", description = "Bei Elune! Anscheinend haben einige derer, die wir nach dem Angriff auf das alte Auberdine totgeglaubt hatten, ein Flüchtlingslager außerhalb der Ruinen der Stadt aufgeschlagen.\n\nDie Kultisten am Lager des Schattenhammers hatten vor, kurzen Prozess mit ihnen zu machen. Bloß gut, dass Ihr ihre Stellung so erfolgreich angreifen konntet.\n\nTrefft Priesterin Alinya im Flüchtlingslager östlich des alten Auberdine tief im Süden.", progress = nil, completion = "Vielen Dank, dass Ihr uns zu Hilfe eilt. Wie Ihr sehen könnt, ist die Lage der Flüchtlinge schier aussichtslos.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13602] = {title = "Naga des Strandes", objective = "Tötet 15 beliebige Naga der Rächerflossen am Zoramstrand.", description = "An der Küste im Westen lauert das Böse.\n\nDer Zoramstrand ist die Ruhestätte der verfluchten Stadt Zoram, die während der Großen Zerschlagung zerstört wurde und im Meer versank. Dort liegt sie seit langer Zeit, verloren für die Nachtelfen. Verloren und beinahe vergessen.\n\nJetzt sind die Naga zurückgekehrt und wir wissen nicht aus welchen Gründen. Aber Gründe spielen keine große Rolle. Wir müssen diese Feinde vernichten und sie zurück in ihre Tiefen zwingen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Eure Handlungen gegen die Naga am Zoramstrand waren rühmenswert.\n\nIch weiß, dass diese Heldentat nicht leicht zu vollbringen war, denn die Stärke und Arglist der Naga sind den Nachtelfen wohl bekannt. Wir wissen das, denn sie und wir haben eine gemeinsame Vergangenheit.\n\nDie Naga sind verfluchte Hochgeborene der Nachtelfen. Vor zehntausend Jahren schloss Königin Azshara in ihrer Verzweiflung einen Pakt mit den Alten Göttern, damit die Überlebenden ihres Volkes nicht in einem nassen Grab enden.\n\nDie Naga sind das Ergebnis dieses Paktes.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13603] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Marschall Jacob Alerius beim Argentumturnierplatz.", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13604] = {title = "Datenscheibe des Archivums", objective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13605] = {title = "Der letzte Flüchtling", objective = "Begleitet Archäologin Hollee in Sicherheit.", description = "Es gab ein riesiges Erdbeben und alles wurde dunkel. Meine nächste Erinnerung ist, wie ich hier als Gefangene aufwachte. Der ganze Ort ist voll von Elementaren!\n\nIch hoffe, es geht allen gut. Dieser Schattenhammerabschaum hat besser keinem meiner Freunde Leid zugefügt!\n\nSchnell, <Klasse>, benutzt etwas Scharfes, um das Schloss hier zu öffnen. Zusammen sollten wir es bis zum Flüchtlingslager schaffen.", progress = nil, completion = "Ah, Ihr seid der gute Mann, der meine Hollee gerettet hat!\n\nNun, ich habe für Euch eine passende Belohnung. Wir können Euch nicht genug dafür danken, sie in Sicherheit gebracht zu haben, &lt;Name&gt;.", rewards = "Latzhose des ArchäologenKniehosen des ArchäologenGrabungsstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13606] = {title = "Freyas Siegel", objective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, <Name>, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", progress = "Freyas Siegel, <Name>? Habt Ihr es?", completion = "Verdammt gute Arbeit, &lt;Name&gt;. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13607] = {title = "Das Himmlische Planetarium", objective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", progress = "Habt Ihr ihn gefunden, <Name>?", completion = "Es ist verschlossen? War ja klar!\n\nDann wollen wir doch mal sehen, was für Informationen wir aus diesem Müllhaufen rausholen können...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13609] = {title = "Hodirs Siegel", objective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", progress = "Habt Ihr das Siegel, <Name>?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13610] = {title = "Thorims Siegel", objective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Thorim ist nicht er selbst, <Name>. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", progress = "Nun, <Name>? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, &lt;Name&gt;.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13611] = {title = "Mimirons Siegel", objective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", progress = "Konntet Ihr das Siegel an Euch bringen, <Name>?", completion = "Das muss man Euch wirklich lassen, &lt;Name&gt;. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13612] = {title = "Die Verteidigung von Mor'shan", objective = "Kadrak beim Schutzwall von Mor'shan will, dass Ihr 5 Scharmützler des Eschentals und 5 Bogenschützen des Eschentals tötet.", description = "Lok'tar, <Volk>!\n\nDer Feldzug hat endlich begonnen! Bald wird sich ganz Eschental in den Händen der Horde befinden.\n\nWie wir erwartet haben, zwingt unser Angriff den Feind dazu, unsere Verteidigung an jeder erdenklichen Stelle auf die Probe zu stellen.\n\nHier in Mor'shan wurde ihre Angriffskraft geschwächt! Aber die Schlinge zieht sich immer enger zu. Sie haben keine Wahl, als uns hier weiter unter Druck zu setzen.\n\nErkundet die Umgebung, <Klasse>. Sucht nach den Überlebenden der Nachtelfen und vernichtet sie, bevor sie sich zu einem neuen Angriff sammeln können!", progress = "War Eure Jagd erfolgreich, <Volk>?", completion = "Gute Arbeit, &lt;Klasse&gt;!\n\nEure Bemühungen werden uns dabei helfen, die Feinde auf Trab zu halten, während wir mit unseren Streitkräften über das Land herfallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13613] = {title = "Rettet die Gefallenen", objective = "Verwendet die heilkräftige Salbe bei 5 verletzten Verteidigern von Mor'shan.", description = "Unsere Streitkräfte schlagen sich großartig, <Klasse>.\n\nAber so erfreulich das auch ist, jemand muss sich noch um die Verwundeten kümmern, von denen sich noch viele auf dem Schlachtfeld befinden.\n\nIch habe eine Salbe angerührt, die den Verwundeten genug Kraft geben sollte, um zur weiteren Behandlung zum Schutzwall zurückzukehren. Bitte verabreicht sie jedem, der sie benötigt, bevor sie für unsere Sache verloren sind.", progress = nil, completion = "Habt Dank, &lt;Volk&gt;. Ich werde den Dienst, den Ihr der Horde geleistet habt, in meinem Bericht erwähnen.\n\nDiese Truppen werden in kürzester Zeit wieder kampfbereit sein!", rewards = "Gamaschen des reisenden ArztesHalbmondhandschuheSchulterstücke der ersten HilfeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13614] = {title = "Algalon", objective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", description = "Ihr habt es wirklich geschafft, <Name>. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", rewards = "Ihr bekommt:\n\nSack mit Schätzen von UlduarSchlüssel des Himmlischen Planetariums"}
MultiLanguageQuestData['de'][13615] = {title = "Leere Köcher", objective = "Truun im Schutzwall von Mor'shan verlangt von Euch, 10 brauchbare Pfeile in der Umgebung des Himmelssturzsees einzusammeln.", description = "Seid gegrüßt, <Klasse>, und willkommen am Schutzwall.\n\nEs mag hier etwas chaotisch zugehen, aber seid unbesorgt. Kadrak hat diesen Stützpunkt gut abgeschottet. Nicht ein einziger Elf konnte unsere Reihen durchbrechen!\n\nWo Ihr schon mal hier seid... Ich erwarte eine neue Versorgungslieferung aus Orgrimmar. Sie müsste jeden Tag eintreffen, aber unseren Wachmännern gehen bald die Pfeile aus.\n\nBringt mir jeden, den Ihr findet, und Ihr werdet es nicht bereuen.", progress = "Habt Ihr die Pfeile, die wir brauchen, <Klasse>?", completion = "Gute Arbeit, &lt;Klasse&gt;.\n\nDamit sollten wir bis zum Eintreffen der nächsten Lieferung durchhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13616] = {title = "Auf Winters Schneide", objective = "Marschall Jacob Alerius beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge errungen, nach der ich suche?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13617] = {title = "Nach Westen zum Strand", objective = "Sprecht mit Talen am Stützpunkt an der Grotte im Eschental.", description = "<Name>, ein Freund von mir könnte Eure speziellen Fähigkeiten gut gebrauchen. Sein Name ist Talen und er ist so eine Art Archäologe. Neuerdings fasziniert ihn der Untergang der alten Stadt Zoram mit ihren Schätzen.\n\nWenn Ihr ihm zur Hand gehen wollt, findet Ihr ihn im Stützpunkt an der Grotte den Weg entlang nach Westen.", progress = nil, completion = "Hallo, &lt;Klasse&gt;.\n\nWie war das? Ihr sagt, Shyela schickt Euch?\n\n\n\nSehr gut, fangen wir an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13618] = {title = "Findet Gorat!", objective = "Kadrak am Schutzwall von Mor'shan will, dass Ihr die Gegend um den Himmelssturzsee herum nach Gorat absucht.", description = "Gorat ist einer der fähigsten Assassinen der Horde.\n\nDie bloße Erwähnung seines Namens erfüllt die Herzen unserer Gegner von der Allianz mit Angst.\n\nEr ist zuverlässig, absolut loyal, und – bisher – pünktlich.\n\nEtwas stimmt nicht, <Klasse>.\n\nGorats Aufgabe bestand darin, den Elf zu finden und zu töten, der für diesen Angriff auf den Schutzwall verantwortlich ist.\n\nEr sollte sich irgendwo in der Gegend um den Himmelssturzsee herum aufhalten.\n\nFindet ihn!", progress = nil, completion = "Hört gut zu, &lt;Volk&gt;...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13619] = {title = "Abschlussbericht", objective = "Gorat will, dass Ihr die Phiole mit Gorats Blut zu Kadrak beim Schutzwall von Mor'shan bringt.", description = "<Gorat hustet schwer, als er versucht, zu sprechen.>\n\nEs war... ein Hinterhalt...\n\nWir waren... auf dem Rückweg zum Schutzwall. Die anderen... alle sind... verloren...\n\nWir haben... ihren Anführer entdeckt... \n\n<Gorat füllt sorgfältig eine Phiole mit dem Blut, das aus einer seiner Wunden quillt.>\n\nMeine Männer... müssen gerächt werden... Bringt dies... zu Kadrak...\n\nEr wird wissen, was zu tun ist...\n\n<Gorat stirbt.>", progress = "Habt Ihr Gorat gefunden, <Klasse>?", completion = "&lt;Kadrak hört aufmerksam zu, während Ihr ihm Gorats letzte Worte übermittelt.&gt;\n\nEs ist also so, wie ich befürchtet hatte. Möge er in Frieden ruhen – aber jetzt noch nicht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13620] = {title = "Zu Dinah, sofort!", objective = "Kadrak möchte, dass Ihr die Phiole mit Gorats Blut zu Dinah am Schutzwall von Mor'shan bringt.", description = "Vielleicht war niemand der Horde so treu ergeben wie Gorat. Bisher ist er noch bei keiner Mission gescheitert, und es scheint, als ob er es nicht zulassen wollte, dass dies seine erste wird.\n\nGorat hat Euch diese Phiole zu einem bestimmten Zweck gegeben. Dinah ist die Tochter eines ehrwürdigen Schamanen und sie ist mächtiger, als es erscheint. Bringt die Phiole zu ihr und hofft, dass wir nicht zu spät kommen.", progress = "Was habt Ihr da, <Volk>?", completion = "Sehen wir uns das mal an, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDinah Dummy Spell\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13621] = {title = "Gorats Vergeltung", objective = "Dinah will, dass Ihr Gorats machterfülltes Blut auf Gorats Leichnam anwendet und dann Hauptmann Elendilad vernichtet.", description = "Das Glück ist uns heute hold, <Volk>.\n\nGorats Blut war noch frisch genug, sodass ich ein besonderes Ritual durchführen konnte, das mir als Kind beigebracht wurde.\n\nVerwendet dieses angereicherte Blut auf Gorats Leichnam, um seinen dort noch immer wandelnden Geist zu beschwören.\n\nErweist ihm diesen letzten Dienst. Dann kehrt hierher zurück und berichtet Kadrak.\n\nMögen die Geister Euch schützen.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;.\n\nDer Hauptmann der Elfen ist tot und die Seele eines unserer geliebten Brüder ruht nun in Frieden.\n\nIch werde die Kunde von Euren Taten an meine Vorgesetzten in Orgrimmar weiterleiten.", rewards = "Gorats VermächtnisKadraks BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13622] = {title = "Uralte Geschichten", objective = "Bringt die zerschmetterten Fragmente von Val'anyr zur Archivumkonsole im Archivum in Ulduar.", description = "Die Stücke lassen sich zu einem eleganten Hammer zusammenfügen. Seine Bauweise erweckt den Eindruck, zumindest teilweise von titanischer Natur zu sein.\n\nWomöglich könnte man über die Konsole im Archivum mehr über dieses Artefakt erfahren.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][13623] = {title = "Lieferung für Orendil", objective = "Bringt den Beutel voll Bathranshaar zu Orendil Rundblatt in Maestras Posten im Eschental.", description = "Rasch, <Name>. Ich werde das Bathranshaar in diesen Beutel füllen, aber Ihr müsst es an meinen Meister Orendil Rundblatt liefern. Ihr findet ihn in Maestras Posten, einfach Richtung Süden die Straße entlang auf der linken Seite.\n\nAber seht Euch vor, wir haben Nachricht erhalten, dass der Posten von der Horde angegriffen wird!", progress = "Ihr seid mutig, unter diesen Umständen hierher zu kommen.\n\nWie lautet Euer Anliegen, Fremder?", completion = "Also hatte Evenar Erfolg. Um es genauer zu sagen, IHR hattet Erfolg.\n\nIch kann Euch nicht genug danken, &lt;Klasse&gt;, aber diese Blätter müssen noch weiter verarbeitet werden, bevor sie als Heilmittel gegen das Unheil dienen können, welches das Kind Relara dahinsiechen lässt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13624] = {title = "Eine Staffel nur für Euch", objective = "Verwendet eine Staffel der Schildwachen aus Maestras Posten, um 3 Zerstörer des Eschentals und 10 Eindringlinge der Horde zu vernichten.", description = "Ich gehe davon aus, Ihr seid hier, um zu helfen, <Klasse>. Die Lage ist so schlimm, wie sie erscheint. Um es auf den Punkt zu bringen: Wir verlieren!\n\nMeine Mädchen und ich sind die letzte Verteidigungslinie gegen die Horde, aber wir werden hier nicht verschwinden, ohne den Kampf zu ihnen zu tragen. Bereit für eine Herausforderung?\n\nIch habe eine kleine Staffel von Schildwachen, die ich Euch unterstellen könnte. Bringt sie in ihre Nähe und ich bin mir sicher, dass ihre magischen Pfeile diese Räuber und Eindringlinge vernichten werden.\n\nSprecht mich wieder an, falls Ihr Ersatz benötigt.", progress = nil, completion = "Einer meiner Späher in den Wäldern hat mir von Euch berichtet, aber ich hatte ja keine Ahnung, wozu Ihr wirklich in der Lage seid!\n\nHabt Dank, &lt;Name&gt;. Durch das, was ihr erreicht habt, hat sich das Blatt gewendet. Ich habe keine Zweifel mehr, dass wir sie bis zum Tagesende besiegt haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13625] = {title = "Reitgrundlagen", objective = "Trefft ein Nahkampfziel fünfmal mit der Fähigkeit \"Zustoßen\" und wendet die Fähigkeit \"Schildbrecher\" auf 2 ungeschützte Distanzziele sowie die Fähigkeit \"Sturmangriff\" auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Die meisten Wettkämpfe des Turniers verlangen von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Trainingsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf das Streitross der Quel'dorei. Macht Euch mit den verfügbaren Taktiken vertraut und besiegt anschließend die drei verschiedenen Arten von Trainingsattrappen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13626] = {title = "Den Gefallenen zu Ehren", objective = "Holt Feeros heiligen Hammer und das Gebetsbuch des Läuterers zurück.", description = "Es gab hier zwei Menschen: Feero Eisenhand und Delgren der Läuterer. Sie waren Mitglieder einer heiligen Organisation, die als Argentumdämmerung bekannt ist. Beide fielen bei der Verteidigung des Postens gegen den ersten Angriff der Horde.\n\nIch werde Euch meinen magischen Umhang borgen. Es ist ein Geschenk von Cenarius. Mit seiner Hilfe kann ich mich unsichtbar machen.\n\nFindet die beiden Leichname und spürt Feeros Hammer sowie Delgrens Gebetsbuch auf. Feeros Leichnam ist im Hof und Delgren liegt auf der Spitze des Turms.\n\nSeht Euch vor, denn der Hexenmeister dort oben wird Euch sehen können.", progress = "Unsere Verluste sind niederschmetternd.", completion = "Ich freue mich nicht sonderlich darauf, den Brief an die Botschaft der Argentumdämmerung in Darnassus zu schreiben. Zumindest sind wir in der Lage, die meisten ihrer Besitztümer zu den Angehörigen zurückzuschicken.\n\nIch kann Euch nicht genug für Euren Mut danken, &lt;Name&gt;. Bitte nehmt dies im Namen des Postens entgegen.", rewards = "Delgrens GamaschenOnaeyas HandschuheFeeros SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13627] = {title = "Wie die Axt im Walde", objective = "Bringt 12 grob gehauene Bauhölzer zu Stumpi Sprengbolz beim Argentumturnierplatz.", description = "Kommt näher. Nein, nicht zu nah. Wir wollen doch keinen Grund für unnötige Verdächtigungen geben, nicht wahr?\n\nDiese Turnierhalle benötigt mehr Holz, als wir auf Lager haben, und die Kosten für einen Ferntransport von den Grizzlyhügeln werde ich auf keinen Fall zahlen. Im Westen des Kristallsangwaldes, in der Nähe des Großen Baumes, wachsen etliche junge Kristallsangeichen. Das wäre genau das Holz, das wir zum Bauen und als Gerüstmaterial bräuchten. Nehmt dieses Beil, schlagt einige Bäume und haut daraus ein paar Hölzer. Aber lasst Euch dabei bloß nicht erwischen!", progress = "Habt Ihr die \"Waren\", von denen wir gesprochen hatten?", completion = "Das ist exzellentes Bauholz und der Preis stimmt auch! Besser noch, diese angestaubten Typen vom Argentumkreuzzug werden's nie erfahren. Sie bekommen ihre heißgeliebte Turnierhalle und ich bekomme meinen Bonus für den schnellen Bauabschluß. Wenn das mal kein Gewinn für beide Seiten ist, dann weiß ich auch nicht mehr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13628] = {title = "Gut Holz", objective = "Truun will, dass Ihr mit Brutusk zum Lager des Kriegshymnenklans reitet.\n\nSprecht mit Kadrak, um Kadraks Zügel zu erhalten und Brutusk reiten zu können.", description = "Kadrak hat gerade neue Befehle für unsere Truppen erhalten. Mir ist zu Ohren gekommen, dass wir mit dem Angriff auf Eschental beginnen!\n\nIch habe viel zu wenig Vorräte, um einen Angriff zu unterhalten, und meine Lieferung aus Orgrimmar ist noch nicht eingetroffen.\n\nIch bin gezwungen zu improvisieren und könnte Eure Hilfe gebrauchen, <Klasse>.\n\nSprecht mit Kadrak und fragt ihn nach den Zügeln von Brutusk. Der Kodo wird Euch zum Lager des Kriegshymnenklans tragen. Sobald Ihr dort seid, sucht nach Gorka und bittet sie, Euch mit Baumstämmen zu beladen.", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Es ist schön, zu sehen, dass die Straße zum Schutzwall von Mor'shan frei bleibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13629] = {title = "Val'anyr, Hammer der Uralten Könige", objective = "Werft die zerschmetterten Teile von Val'anyr in Yogg-Sarons Schlund, während er den Zauber 'Ohrenbetäubendes Gebrüll' wirkt, und vernichtet ihn, um den neugeschmiedeten Hammer der Uralten Könige zu erhalten.\n\nDies kann nur auf dem Schwierigkeitsgrad \"Heroisch\" beendet werden und nur dann, wenn Ihr von maximal drei Wächtern von Ulduar unterstützt werdet.", description = "Die Archivumkonsole hat eine Möglichkeit angedeutet, wie die Fragmente von Val'anyr wieder zusammengefügt werden können: Ihr müsst die Fragmente ins Innere der körperlichen Form des Wesens namens Yogg-Saron bekommen.\n\nEs mag vielleicht aussichtslos klingen, doch Ihr denkt, dass ein Artefakt von solcher Macht das Risiko wert sein könnte.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVal'anyr, Hammer der Uralten Könige"}
MultiLanguageQuestData['de'][13630] = {title = "Aus diesem Grund", objective = "Deaktiviert den blauen, den grünen und den roten Mondstein.", description = "Die Furbolgs sind von ihren Anhöhen herabgestiegen und haben die Ruinen von Ordil'Aran im Norden überrannt. Ich vermute, dass sie das getan haben, weil sie von etwas angezogen wurden, was die toten Kultisten dort entdeckt haben: drei Mondsteine.\n\nLiladris Mondbach wird Euch raten, wie Ihr mit den Furbolgs auf eine direktere Weise fertigwerdet und ich werde ihr nicht widersprechen. Aber ich würde Euch darum bitten, Euch zu den Ruinen zu begeben und die Mondsteine zu deaktivieren.", progress = nil, completion = "Habt Dank, &lt;Name&gt;.\n\nJetzt, wo die Mondsteine von Ordil'Aran deaktiviert sind, brauchen wir uns hier nicht um weitere Überfälle der Furbolgs zu sorgen.\n\nNichtsdestotrotz sind meine Späher mit verstörenden Neuigkeiten aus dem Dorf der Furbolgs zurückgekehrt. Dort braut sich etwas zusammen.\n\nIch frage mich, ob ich Euch darum bitten kann, für mich eine Warnung nach Astranaar zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13631] = {title = "Ende gut, alles gut", objective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", description = "Wir sollten uns jetzt besser beeilen, <Name>. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", progress = "Seid Ihr soweit, <Name>?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", rewards = "Tuch des HimmelsheroldsSonnenglimmertuchAuf Euch wartet eine dieser Belohnungen:\n\nBranns SiegelringSternenlichtsiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13632] = {title = "Zwei Fronten", objective = "Tötet 10 beliebige Furbolgs in den Ruinen von Ordil'Aran.", description = "Die Mondpriesterin hat einen Plan, der sicherstellen soll, dass keine weiteren Furbolgs aus dem Hochland herabsteigen. Ich mache mir mehr Sorgen um diejenigen, die bereits bei den Ruinen sind und von denen einige sich direkt vor dem Posten zusammenrotten.\n\nSo unangenehm es auch sein mag, ich muss Euch bitten, Euch nach Norden in die Ruinen von Ordil'Aran zu begeben und die Furbolgs zu vernichten. Wir können nicht an zwei Fronten gleichzeitig kämpfen!\n\nHabt Dank, <Klasse>.", progress = nil, completion = "Wir stehen in Eurer Schuld, &lt;Klasse&gt;. Wenn ich Eines über die Furbolgs weiß, dann dies: Sie schätzen es nicht, blutige Nasen zu bekommen.\n\nEs wird nicht lange dauern, bevor sie den Schwanz einziehen und in ihr Dorf zurückkehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13633] = {title = "Der schwarze Ritter von Westfall?", objective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, der Cooperfamilie in Westfall zu entstammen. Würdet Ihr Euch aufmachen und den Wohnsitz der Familie in Mondbruch in Westfall aufsuchen? Vielleicht lässt sich dort ein Beweis für seine Geschichte finden.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen, solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, &lt;Name&gt;. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13634] = {title = "Der schwarze Ritter von Silberwald?", objective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, aus Valgans Feld im Silberwald zu stammen, einem kleinen Gehöft an der westlichen Küste des Lordameresees. Könntet Ihr dem Hof einen Besuch abstatten und mich wissen lassen, ob seine Geschichte der Wahrheit entspricht?", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, &lt;Name&gt;. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13635] = {title = "Statusbericht des südlichen Tors", objective = "Liefert den Statusbericht von Pilot Hammerfuß bei Hauptmann Rugelfuß im Tal der Könige ab.", description = "Wir müssen den Gebirgsjägern im Tal der Könige einen Statusbericht zukommen lassen.\n\nIch gehe davon aus, dass Ihr sowieso in diese Richtung wolltet - könntet Ihr den Bericht für mich abliefern? Nehmt den Tunnel östlich von hier und meldet Euch beim Wachposten. Der Bericht muss direkt zu Hauptmann Rugelfuß.", progress = "Was führt Euch hier her?", completion = "Der Statusbericht des südlichen Tors? Ausgezeichnet. Ich warte schon seit Längerem auf Neuigkeiten von dort.\n\nEs finden sich immer mehr Troggs auf den Hügeln und ich fürchte, die Außenposten dort werden als Erstes von den Aggressionen zu spüren bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13636] = {title = "Befehle für Sturmlanze", objective = "Bringt die Befehle für Sturmlanze zu Gebirgsjäger Sturmlanze in der Station Algaz.", description = "Gebirgsjäger Sturmlanze muss neue Befehle bei seinem Posten der Station Algaz erhalten. Ihr stört Euch doch nicht daran, sie ihm zu bringen? Folgt der Straße bis ihr nordöstlich von hier den Bunker seht.\n\nIhr könnt ihm auch gerne bei seinen Aufgaben helfen. Natürlich würde ich Euch dafür entsprechend belohnen.", progress = nil, completion = "Befehle! Mal sehen, was es zu tun gibt... ha! Mit den Rattenmenschen soll ich mich herumschlagen. Die sind hier eh schon überall, also macht das auch keinen Unterschied mehr.\n\nWollt Ihr helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13637] = {title = "Widdertransport", objective = "Die Gebirgsjäger im Südtoraußenposten haben eine Widderlieferung für ihre Patrouillen angefordert. Ich hätte nicht gedacht, dass wir Kräfte erübrigen können, aber dank Euch können wir ihnen wenigstens einen zukommen lassen.\n\nHättet Ihr etwas dagegen, ihn für mich bei Soldat Hammerfall abzugeben? Lasst mich wissen, wenn Ihr bereit zum Aufbruch seid.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Die Gebirgsjäger im Südtoraußenposten haben eine Widderlieferung für ihre Patrouillen angefordert. Ich hätte nicht gedacht, dass wir Kräfte erübrigen können, aber dank Euch können wir ihnen wenigstens einen zukommen lassen.\n\nHättet Ihr etwas dagegen, ihn für mich bei Soldat Hammerfall abzugeben? Lasst mich wissen, wenn Ihr bereit zum Aufbruch seid.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13638] = {title = "Der gefangene Gebirgsjäger", objective = "Hauptamnn Rugelfuß in Thelsamar möchte, dass Ihr den Gebirgsjäger Kieselwut findet.Ihr habt Euch als mehr als fähig im Kampf erwiesen. Nun habe ich eine etwas wichtigere Angelegenheit für Euch.\n\nEiner meiner Männer, Gebirgsjäger Kieselwut, wurde von den Troggs gefangen genommen, die wir am südlichen Teil der Berge bekämpfen. Naja, er gab mehr auf, als dass er wirklich gefangen genommen wurde, aber das Resultat ist das gleiche. Er wollte wohl von innen herausfinden, wer ihr Anführer ist.\n\nIhr müsst ihn da rausholen. Sie halten ihn wahrscheinlich in der Nähe der höheren Höhlen tief im Berg.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr habt Euch als mehr als fähig im Kampf erwiesen. Nun habe ich eine etwas wichtigere Angelegenheit für Euch.\n\nEiner meiner Männer, Gebirgsjäger Kieselwut, wurde von den Troggs gefangen genommen, die wir am südlichen Teil der Berge bekämpfen. Naja, er gab mehr auf, als dass er wirklich gefangen genommen wurde, aber das Resultat ist das gleiche. Er wollte wohl von innen herausfinden, wer ihr Anführer ist.\n\nIhr müsst ihn da rausholen. Sie halten ihn wahrscheinlich in der Nähe der höheren Höhlen tief im Berg.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13639] = {title = "Nachschub für die Ausgrabungsstätte", objective = "Findet Huldar, Miran und Saean.", description = "Eisenband hat südöstlich von hier eine Ausgrabungsstätte, für die er ordentlich Sprengstoff von der Liga geschickt bekommen hat. Huldar, Miran und Saean sind gerade mit der letzten Ladung los und können wahrscheinlich Hilfe gebrauchen.\n\nWeit sind sie sicher noch nicht gekommen, so stark wie sie sind. Mit vollen Fässern ist man nicht so schnell.\n\nSie haben den normalen Weg zur Ausgrabungsstätte eingeschlagen, durch das Südtor und am Loch vorbei. Versucht, sie einzuholen und ihnen zu helfen, ja?", progress = nil, completion = "Ha, es braucht mehr als einen Hinterhalt der Dunkeleisenzwerge, um uns aufzuhalten!\n\nAber Saean... ich hätte nie gedacht, dass er ein Sympathisant ist. Wir arbeiten schon seit fast einem Jahr mit ihm zusammen... vielleicht habe ich nur nicht richtig aufgepasst.\n\nIch werde mich später darüber sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13640] = {title = "Managerqualitäten", objective = "Überzeugt demoralisierte Peons, wieder an die Arbeit zu gehen und 5 Stück frisch gespaltenes Holz zu sammeln.", description = "Truun braucht Holz, wie? Normalerweise könnte ich ihm welches liefern, aber nicht heute.\n\nDurch die ständigen Angriffe der Elfen ist das Holzschlagen zu einem gefährlichen Unterfangen geworden. Meine Peons sträuben sich und wagen sich nicht in den Wald.\n\nIhr wollt Holz? Dann überzeugt die Peons, ihre Arbeit wieder aufzunehmen.\n\nUnd sorgt dafür, dass ihnen nichts zustößt! Ich kann es mir nicht leisten, noch weitere zu verlieren!", progress = "Habt Ihr das Holz bekommen, das Ihr benötigt?", completion = "Es scheint, Ihr habt das eine Problem gelöst, nur um vor einem neuen zu stehen, &lt;Klasse&gt;.", rewards = "ArbeitslagerkittelMantelung des ManagersHände der ErmutigungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13641] = {title = "Der Seherkristall", objective = "Bringt einen Seherkristall zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", description = "Jetzt, da wir wissen, dass der Schwarze Ritter nicht die Wahrheit spricht, müssen wir einen Weg finden, seine Verbindung zu den toten Rittern nachzuweisen.\n\nIch kenne einen Weg um die Wahrheit über ihren Tod aufzudecken, doch er benötigt ein seltenes Material. Wir müssen einen Seherkristall auftreiben, der nur bei den unbändigen Sehern gefunden werden kann, die sich in der Nähe der Nachtelfenruinen in den Trostlosen Wäldern im Zentrum des Kristallsangwaldes versammeln. Findet einen dieser Seher, <Name>, und bringt mir die Kristalle, die er bei sich trägt.", progress = "Habt Ihr einen Seherkristall finden können?", completion = "Der wird vollkommen genügen. Nun bleibt nur noch, ihn mit der Macht des Lichtes zu erfüllen, sodass er die Fähigkeit erhält, die unter Lügen verborgene Wahrheit zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13642] = {title = "In Licht getaucht", objective = "Stellt ein eingetauchtes Gebräu her.", description = "Das Gebräu ist noch nicht ganz fertig. Es muss noch in das Licht von Elune getaucht werden, bevor wir auch nur daran denken können, es dem Kind zu geben.\n\nIm Westen am Falathimsee ist uns ein Ort bekannt, wo das Mondlicht der Göttin fortwährend auf die Erde fällt - bei Tag und bei Nacht. Bitte, <Name>, um Relaras Willen flehe ich Euch an: Nehmt das Gebräu und badet es in Elunes Strahlen.\n\nAber hütet Euch! Seltsame Dinge gehen im Gebiet um den See vor sich und ich befürchte, dass es nicht mehr sicher ist, dorthin zu gehen.", progress = "Hattet Ihr Schwierigkeiten, zum Licht von Elune am Falathimsee zu gelangen?", completion = "Jetzt, da das Gebräu von Elunes Licht gesegnet wurde, kann es nach Astranaar gebracht werden.\n\nEs bleibt keine Zeit zu verlieren, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13643] = {title = "Die Geschichten toter Männer", objective = "Benutzt den Seherkristall an den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff, um herauszufinden, wie sie gestorben sind, und kehrt anschließend zu Kreuzfahrerin Rhydalla zurück.", description = "Die Kristalle werden die Wahrheit darüber ans Tageslicht bringen, wie drei der Turnierteilnehmer gestorben sind. Bringt ihn zum Friedhof östlich des Turnierplatzes und benutzt ihn bei den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff.\n\nWenn diese Männer wirklich ermordet worden sind, dann müssen wir einen Weg finden, eine Verbindung zum Schwarzen Ritter herzustellen, bevor er wieder zuschlägt. Beobachtet genau, was der Kristall Euch zu sagen hat, <Name>, denn wir müssen sicher sein, dass diese Todesfälle keine Zufälle gewesen sind.", progress = "Habt Ihr den Gräbern der erschlagenen Kämpfer einen Besuch abgestattet?", completion = "Ihr sagt also, dass Lorien Sonnenfeuer mit Gift getötet und Sir Wendell lebendig verbrannt wurde? Beides schreckliche Arten zu sterben. Nur Conall fand seinen Tod durch kalten Stahl und anhand Eurer Beschreibung war es die Tat eines Feiglings, die ihn ins Grab brachte, nicht ehrenhafter Kampf.\n\nAlle drei trainierten mit dem Schwarzen Ritter und sollten gegen ihn kämpfen. Das kann kein Zufall sein. Wir müssen einen Weg finden zu beweisen, dass es das Werk des Schwarzen Ritters gewesen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13644] = {title = "Aus den Tiefen", objective = "Tötet Bote Aphotic.", description = "Als ich spürte, wie sich diese... Dinger... erhoben, kam ich hierher, um sie wieder in die Tiefen zurückzuschicken. Ich fand den Leichnam Eures Freundes und schleppte ihn mit, soweit ich konnte, bevor ich mir mein Fesselgelenk brach. Das ist alles, was ich tun konnte, um diese verdorbenen Tentakel abzuwehren.\n\nEs gibt einen, der die Tentakel und die Augen lenkt. Er nennt sich Bote Aphotic – Ihr habt ihn sicher schon aus dem Süden brüllen hören.\n\nDer Bote befindet sich außerhalb der Reichweite meiner Magie, aber Ihr könntet zu ihm gelangen. Falls Ihr es wagt...", progress = "Der Bote lebt noch, <Name>. Ich kann den Falathimsee nicht reinigen, bevor er vernichtet ist.", completion = "Jetzt, da der Bote tot ist, kann ich mit der Reinigung des Sees beginnen.\n\nIch bin Euch zu tiefstem Dank verpflichtet, &lt;Name&gt;. Ich beklage den Tod Eures Freundes, aber ich weiß, dass seine Überreste zur Rückgewinnung des Waldstückes beitragen werden.", rewards = "Schuhe der AblutionDüstere TreterHerzenswegs SegenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13645] = {title = "Zu Raene Wolfsläufer", objective = "Überbringt den leuchtenden Edelstein an Raene Wolfsläufer in Astranaar im Eschental.", description = "Ich bitte Euch, diesen Edelstein Raene Wolfsläufer persönlich zu übergeben. Soweit ich weiß, hält sie sich noch immer in Astranaar im Südosten auf.\n\nZumindest ist die Straße relativ sicher. Es sollte Euch also leicht fallen, dem Verlauf bis dorthin zu folgen. Natürlich, wenn es Euch lieber ist... Ich glaube, dass Schildwache Avana bereit wäre, Euch einen ihrer Nachtsäbler zu leihen, damit Ihr schneller dorthin gelangt.\n\nWie Eure Wahl auch ausfällt, lasst es Euch wohlergehen, <Name>. Mögen unsere Wege sich bald wieder kreuzen.", progress = "Ich bin Raene Wolfsläufer. Wer mögt Ihr wohl sein?", completion = "Teronis ist tot?\n\n&lt;Die Lady beweint leise den Verlust ihres Freundes und beruhigt sich dann einen Augenblick später.&gt;\n\nWir müssen das Gute daran sehen. Sein Opfer war nicht umsonst. Seid Ihr bereit, dies durchzuziehen, &lt;Klasse&gt;?\n\nAlso gut, gebt mir etwas Zeit, darüber nachzudenken, wie wir fortfahren sollten. Ich werde es bald wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13646] = {title = "Auf einen Sprung nach Astranaar", objective = "Sprecht mit Schildwache Luara in Astranaar im Eschental.", description = "Ihr wart uns eine große Hilfe, <Name>. Ohne Euch wären wir bereits vernichtet worden.\n\nMit dem größten Vergnügen würde ich Euch jederzeit einen meiner Nachtsäbler anvertrauen, damit Ihr mit ihm nach Astranaar im Südosten reiten könnt. Ich bin mir sicher, dass Ihr dort wichtige Angelegenheiten zu klären habt.\n\nIch würde es Euch hoch anrechnen, wenn Ihr bei Eurem Eintreffen mit meiner Schwester Schildwache Luara sprechen könntet und Ihr mitteilt, dass ich wohlauf bin.\n\nSprecht mich einfach wieder an, wenn Ihr bereit zum Aufbruch seid. Ihr könnt Euch jederzeit ein Reittier leihen.", progress = nil, completion = "Avana lebt?! Ich hatte schon befürchtet, sie sei tot, als ich von dem Angriff auf Maestras Posten erfuhr!\n\nWie Ihr seht, haben wir mit der Horde ebenfalls alle Hände voll zu tun.\n\nIhr habt mir das größte Geschenk gemacht, indem Ihr mir mitgeteilt habt, dass sie wohlauf ist. Wann immer Ihr wünscht, mit einem meiner Nachtsäbler zurück zu Maestras Posten zu reiten, soll er Euch gehören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13647] = {title = "Jagdanschluss", objective = "Sprecht mit Marek Eisenherz bei der Jagdhütte der Weltenwanderer.", description = "Ihr habt den Kampf sicherlich in Euch.\n\nWisst Ihr, östlich von hier sind bei der Jagdhütte ein paar Jäger, hoch in den Bergen, die könnten einiges mit Euch gemeinsam haben. Warum besucht Ihr sie nicht und findet heraus, ob sie interessante Arbeit für Euch haben?", progress = nil, completion = "Hallo auch, Junge! Die Gebirgsjäger haben Euch geschickt, hm? Ich glaube, wir haben die Arbeit, nach der Ihr sucht. Willkommen in der Jagdhütte der Weltenwanderer!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13648] = {title = "GESUCHT: Der Spion der Dunkeleisenzwerge", objective = "Tötet Gorick Fassschlucker.", description = "Ein Spion der Dunkeleisenzwerge hat sich in der Stadt breitgemacht und Dokumente von der Forscherliga gestohlen. Jetzt versteckt er sich hier irgendwo in der Nähe. Das letzte Mal wurde er oben auf den Hügeln südlich der Stadt gesehen.\n\nJeden, der den Spion seiner Gerechtigkeit zuführen kann, erwartet eine große Belohnung. Tot oder lebendig - tot bevorzugt!", progress = nil, completion = "Ihr habt den Spion gefasst! Das geschieht ihm recht! Und gute Neuigkeiten sind es für uns. Wir können uns nun etwas beruhigter um unsere Arbeit kümmern, da wir uns um ihn wenigstens nicht mehr sorgen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13649] = {title = "Justins spaßiger Test", objective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxey Bolzdreher.", description = "He da! Ihr seht aus, als könntet Ihr gut mit Bier umgehen. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? \n\nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.\n\nEs ist ganz leicht, nehmt einen Freibierkrug und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBraufestmarke"}
MultiLanguageQuestData['de'][13650] = {title = "Hände weg von unseren Gütern!", objective = "Untersucht das Artefakt des umgestürzten Riesen, das Artefakt der übertrieben gekleideten Frau und das Artefakt der zerbrochenen Schrifttafel.", description = "Wir haben in der Ausgrabungsstätte ein paar unglaubliche Artefakte gefunden. Es ist nicht leicht, zu glauben, dass sie wirklich alle authentisch sind, aber es könnte sich dabei um historisch wichtige Entdeckungen handeln.\n\nLeider haben wir durch den Überfall der Troggs Zugang zu drei der wichtigsten Funde bisher verloren. Ich fürchte, die Troggs haben sie während unserer Abwesenheit gestohlen oder zerstört.\n\nBegebt Euch zur Ausgrabungsstätte und findet den umgestürzten Riesen, die übertrieben gekleidete Frau und die zerbrochene Schrifttafel und stellt sicher, dass sie noch intakt sind.", progress = nil, completion = "Oh, das ist gut! Ich bin erleichtert... ich war wirklich besorgt, sie wären inzwischen alle kaputt. Vielen Dank, dass Ihr nachgeschaut habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13651] = {title = "Braucht bisschen Öl", objective = "Gorka im Lager des Kriegshymnenklans möchte, dass Ihr 5 natürliche Öle von den faulenden Schleimen im Eschental sammelt.", description = "Ihr habt Euer Holz, aber die Elfen machen es Eurem Kodo unmöglich, zum Schutzwall von Mor'shan zurückzukehren.\n\nIch habe einen Läufer zum Splitterholzposten geschickt, damit er Hilfe herbeiholt. Es sollte ihre Streitkräfte nicht allzu viel Zeit kosten, den Weg wieder frei zu machen.\n\nIn der Zwischenzeit würde ich Euch bitten, uns einen Dienst zu erweisen. Rost hat unsere Schredder unbrauchbar gemacht. Mit ein wenig Schmiermittel wären sie wieder so gut wie neu.\n\nDas Öl des faulenden Schleims in der Nähe im Norden würde sich bestens dafür eignen.", progress = "Habt Ihr das Öl gesammelt, das wir brauchen, <Klasse>?", completion = "Habt Dank für das Öl, &lt;Klasse&gt;. Jetzt haltet Euch fest!\n\nMein Läufer ist mit niederschmetternden Neuigkeiten zurückgekehrt...\n\nDer Splitterholzposten ist umzingelt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13652] = {title = "Verteidigung des Steinwerkdamms", objective = "Sucht Chefingenieur Hinderweir VII am Steinwerkdamm.Wir sind für Eure Hilfe sehr dankbar. Wir werden mit der Zeit immer mehr von der Ausgrabungsstätte zurückerhalten und ich bin froh, dass unsere Arbeit durch die Besatzung nicht umsonst war.\n\nWir haben Eure Zeit schon arg in Anspruch genommen. Ein Freund von mir könnte Eure Hilfe sicher gut gebrauchen, wenn Ihr bereit seid, noch mehr auszuhelfen. Geht zur anderen Seite des Loch; dort befindet sich der Steinwerkdamm. Sucht dort nach Chefingenieur Hinderweir VII.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Wir sind für Eure Hilfe sehr dankbar. Wir werden mit der Zeit immer mehr von der Ausgrabungsstätte zurückerhalten und ich bin froh, dass unsere Arbeit durch die Besatzung nicht umsonst war.\n\nWir haben Eure Zeit schon arg in Anspruch genommen. Ein Freund von mir könnte Eure Hilfe sicher gut gebrauchen, wenn Ihr bereit seid, noch mehr auszuhelfen. Geht zur anderen Seite des Loch; dort befindet sich der Steinwerkdamm. Sucht dort nach Chefingenieur Hinderweir VII.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13653] = {title = "Krise am Splitterholzposten", objective = "Gorka will, dass Ihr sie zum Schutzwall von Mor'shan begleitet und Euch bei Kadrak meldet.\n\nSprecht mit Ihr, wenn Ihr bereit zur Abreise seid.", description = "Aus dem Splitterholzposten wird keine Hilfe kommen.\n\nDie Elfen haben einen Großangriff auf unseren dortigen Stützpunkt gestartet und sie haben den Ort umzingelt!\n\nWir müssen Kadrak informieren, koste es, was es wolle!\n\nEuer Kodo wurde mit dem Holz beladen, das Ihr gesammelt habt. Lasst mich wissen, wenn Ihr bereit seid, und wir greifen die feindlichen Reihen im Sturm an.", progress = "Was ist hier los, <Klasse>?", completion = "Gorka...\n\nWir müssen immer auf Verluste vorbereitet sein. Ihre ehrenvollen Verdienste für die Horde werden niemals vergessen werden.\n\nAll ihre Opfer werden nicht vergeblich gewesen sein!", rewards = "Stola des TrauerndenGamaschen des VerlustsBürde des OpfersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13654] = {title = "Etwas ist mit dem Knappen", objective = "Beschafft einen großen Oberschenkelknochen eines skelettierten Holzfällers und setzt damit Maloric außer Gefecht. Durchsucht ihn nach Beweisen und meldet Euch anschließend bei Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", description = "Jeden Tag macht der Knappe des Schwarzen Ritters Maloric eine große Sache daraus, wie er mit der Axt auf seiner Schulter in Richtung Kristallsangwald aufbricht. Er will uns weismachen, er hacke Holz, nur kehrt er niemals mit mehr als nur ein paar Zweigen zurück.\n\nNormalerweise geht er in Richtung Ruinen südwestlich des Zwielichtspiegels. Er verbringt viel Zeit dort draußen, selbst für einen Knappen, der seinem Ritter gegenüber Pflichten hat.\n\nFindet einen Weg, ihn entweder abzulenken oder außer Gefecht zu setzen, und durchsucht ihn. Sollte er etwas im Schilde führen, dann werden wir es wissen.", progress = "Habt Ihr den Knappen durchsucht und irgendwelche Anhaltspunkte gefunden?", completion = "&lt;Kreuzfahrerin Rhydalla untersucht den Inhalt des Beutels mit angewidertem Gesicht.&gt;\n\nEs ist alles da, &lt;Name&gt;: das Gift, das Lorien tötete, eine Sammlung Messer, Fackeln und Öl. Niemand hier hat Grund dazu, diese Dinge zu besitzen, und kein Knappe würde dies ohne den Befehl seines ritterlichen Meisters tun. Wir haben unseren Mörder gefunden, &lt;Name&gt;, doch für wen arbeitet er?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13655] = {title = "Dokument der Forscherliga (2 von 6)", objective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es scheint potentielle Ausgrabungsstätten in ganz Loch Modan aufzuführen. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", progress = nil, completion = "Seht Euch das an. Ihr habt eines der gestohlenen Dokumente gefunden!\n\nWir sind sehr dankbar, dass Ihr es zurückgebracht habt. Hoffentlich ist Euch ein bisschen Gold als Finderlohn genug?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13656] = {title = "Dokument der Forscherliga (1 von 6)", objective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", description = "Auf diesem Dokument ist das Wappen der Forscherliga und ausführliche Informationen über in Loch Modan einheimische Kreaturen sind darauf aufgeführt. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", progress = nil, completion = "Hallo, Kleiner! Ihr scheint eines der gestohlenen Dokumente gefunden zu haben, hm?\n\nVielen Dank, dass Ihr es zurückgebracht habt. Wir geben Euch gerne eine kleine Belohnung dafür.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13657] = {title = "Dokument der Forscherliga (3 von 6)", objective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es ist mit historischen Informationen zu den wichtigen Orten in Loch Modan beschriftet. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", progress = nil, completion = "Unsere historischen Aufzeichnungen! Beim Gedanken daran, dass das Gesindel der Dunkeleisenzwerge Informationen über unsere Vergangenheit hat, hat sich mir der Magen umgedreht.\n\nWir sind sehr dankbar, dass Ihr uns die historischen Aufzeichnungen zurückgebracht habt. Wir möchten Euch ein paar Münzen als Belohnung anbieten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13658] = {title = "Dokument der Forscherliga (4 von 6)", objective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es scheinen Informationen zu allen Transportwegen in und nach Loch Modan darauf aufgeführt zu sein. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", progress = nil, completion = "Oha, Informationen über unsere Transportwege in ihren Händen schreien förmlich nach Ärger!!\n\nVielen Dank, dass Ihr uns das Dokument gebracht habt, bevor sie viel damit anfangen konnten! Ihr habt uns sicherlich viel Ärger erspart. Hier, nehmt ein paar Münzen als Lohn für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13659] = {title = "Dokument der Forscherliga (6 von 6)", objective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es sind Einschätzungen zu den unterschiedlichen Bedrohungen in Loch Modan darauf aufgeführt. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", progress = nil, completion = "Ha! Sie haben sich sicherlich darüber geärgert, wie weit unten sie auf unserer Liste mit Bedrohungen stehen! Dieses Dokument war zugegebenermaßen nicht mehr aktuell, aber immer noch einen Lacher wert.\n\nNatürlich werden wir Euch trotzdem einen Finderlohn geben, weil Ihr das Dokument zurückgebracht habt - wir sind für Eure Bemühungen sehr dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13660] = {title = "Dokument der Forscherliga (5 von 6)", objective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", description = "Auf diesem Dokument ist das Wappen der Forscherliga; es ist eine detaillierte Liste aller bei den Ausgrabungen von Eisenbands Arbeitern im südöstlichen Loch Modan gefundenen Artefakte. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", progress = nil, completion = "Unsere Artefakteliste! Ich war wirklich besorgt, dass diese Liste den Dunkeleisenzwergen dabei helfen würde, mit den Informationen die Artefakte zu stehlen.\n\nVielen Dank, dass Ihr die Liste zurückgebracht habt. Natürlich entlohnen wir Eure Mühen mit ein paar Münzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13661] = {title = "Wertschätzung aus tiefstem Herzen", objective = "Ihr habt alle unsere Dokumente gefunden! Wir können Euch wirklich nicht genug für Eure Mühen danken... wir hatten die Hoffnung aufgegeben. Wir waren uns ganz sicher, dass die Dunkeleisenzwerge mit diesen Informationen sehr viel Unheil anstellen könnten. Es ist gut zu wissen, dass sie mit ihren Angriffen weiterhin im Dunklen tappen werden.\n\nIch möchte Euch für alle Eure Mühen im Namen der Liga danken und Euch ein Geschenk machen. Ein Artefakt, um genau zu sein... etwas, das wir bei unseren Ausgrabungen gefunden haben. Ihr habt den Dank der gesamten Forscherliga.", description = "Ihr habt alle unsere Dokumente gefunden! Wir können Euch wirklich nicht genug für Eure Mühen danken... wir hatten die Hoffnung aufgegeben. Wir waren uns ganz sicher, dass die Dunkeleisenzwerge mit diesen Informationen sehr viel Unheil anstellen könnten. Es ist gut zu wissen, dass sie mit ihren Angriffen weiterhin im Dunklen tappen werden.\n\nIch möchte Euch für alle Eure Mühen im Namen der Liga danken und Euch ein Geschenk machen. Ein Artefakt, um genau zu sein... etwas, das wir bei unseren Ausgrabungen gefunden haben. Ihr habt den Dank der gesamten Forscherliga.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "SternenschießerEntdeckte BrustplatteAlter ZwergenhammerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13662] = {title = "Anerkennung erlangen", objective = "Ihr habt Euch in der Hierarchie der Bruderschaft hochgearbeitet, <Volk>. Wir betrachten Euch nun mit Wohlwollen. Eine ziemliche Leistung!\n\nFalls Ihr an mehr Arbeit interessiert sein solltet und damit mehr Respekt bei uns verdienen wollt, dann hört zu.\n\nWir können das feurige Fluxus veredeln, indem wir der Mischung einfache Dunkeleisenrückstände hinzufügen. Die genannten Rückstände können in den Schwarzfelstiefen gefunden werden.\n\nBringt mir so viel von den Dunkeleisenrückständen, wie Ihr nur finden könnt!", description = nil, progress = "Ihr habt Euch in der Hierarchie der Bruderschaft hochgearbeitet, <Volk>. Wir betrachten Euch nun mit Wohlwollen. Eine ziemliche Leistung!\n\nFalls Ihr an mehr Arbeit interessiert sein solltet und damit mehr Respekt bei uns verdienen wollt, dann hört zu.\n\nWir können das feurige Fluxus veredeln, indem wir der Mischung einfache Dunkeleisenrückstände hinzufügen. Die genannten Rückstände können in den Schwarzfelstiefen gefunden werden.\n\nBringt mir so viel von den Dunkeleisenrückständen, wie Ihr nur finden könnt!", completion = "Immer her mit den Dunkeleisenrückständen!", rewards = nil}
MultiLanguageQuestData['de'][13663] = {title = "Die Befehle des Schwarzen Ritters", objective = "Erhaltet mithilfe des verzauberten Zaumzeugs Kontrolle über den Greifen des Schwarzen Ritters und reitet auf seinem Rücken zum Zielort. Beschafft Euch die gestohlene Einladung zum Turnier und die Befehle des Schwarzen Ritters, sobald Ihr dort angekommen seid, und bringt sie zurück zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", description = "Wir müssen herausfinden, wer den Schwarzen Ritter zum Turnier geschickt hat und was sich sein Meister daraus erhofft, die Konkurrenz zu töten.\n\nDie Kirin Tor haben in dieser Angelegenheit ihre Unterstützung angeboten und uns ein Werkzeug zur Verfügung gestellt, dass uns in unserer Suche helfen wird.\n\nBringt dieses verzauberte Zaumzeug zum Lager des Schwarzen Ritters am östlichen Rand des Turniergeländes und benutzt es, um Kontrolle über den Greifen des Schwarzen Ritters zu erhalten. Die Verzauberung des Zaumzeugs wird das Tier zwingen, Euch zum Wohnort seines Meisters zu bringen. Durchsucht ihn und bringt alles zurück, was Ihr finden könnt.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Kreuzfahrerin Rhydalla wird blass, als sie die Befehle liest.&gt;\n\nDas kann nur eins bedeuten, &lt;Name&gt;. Der Schwarze Ritter ist ein Anhänger des Kults der Verdammten und wurde von Arthas ausgesandt, um das Turnier zu stören!\n\nDer Schwarze Ritter hat sich als Furcht erregender Kämpfer entpuppt und Ihr werdet mindestens genauso gut sein müssen, um Ihm entgegenzutreten. Kehrt zu mir zurück, wenn Ihr Champion geworden seid, und wir werden einen Weg finden, für seine Niederlage zu sorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13664] = {title = "Der Sturz des Schwarzen Ritters", objective = "Besiegt den Schwarzen Ritter und sprecht anschließend mit Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", description = "Wir müssen den finsteren Plänen des Schwarzen Ritters ein Ende setzen und unseren Widersachern zeigen, dass wir nicht untätig daneben stehen und zusehen, wie unsere Champions ermordet werden.\n\nEr wird mittlerweile annehmen, dass ihm jemand auf den Fersen ist. Fordert ihn am helllichten Tage zum Kampf heraus, <Name> - wenn er nicht ablehnen oder jemanden im Dunklen ermorden kann.\n\nNehmt mein Argentumstreitross für den Kampf. Es steht in den Stallungen, in der Nähe des Argentumpavillons.\n\nSprecht dann mit Knappe Cavin im Ring der Champions. Der Knappe wird den Schwarzen Ritter zum Kampf rufen und Ihr werdet ihn für seine Taten büßen lassen.", progress = "Ist es vollbracht?", completion = "Mit dem Tod des Schwarzen Ritters kann das Turnier einmal mehr seinen Nutzen erfüllen. Die Champions der Horde und Allianz können ihre Waffenfertigkeiten demonstrieren und für den Tag trainieren, an dem Arthas und seine Diener keine Bedrohung mehr für uns darstellen werden.\n\nIhr habt den Dank des Argentumkreuzzugs, &lt;Name&gt;, und all derer, die unserem Ruf gefolgt sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13665] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Hauptmann Joseph Holley beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Sturmwind lieben ihre Ritter über alles und freuen sich darauf, uns gewinnen zu sehen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf das Streitross aus Sturmwind, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Sturmwind stolz machen werdet, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13666] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Arkanist Taelis beim Argentumturnierplatz.", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, &lt;Name&gt;. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13667] = {title = "Das Argentumturnier", objective = "Sprecht mit Arkanist Taelis beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nArkanist Taelis ist der Repräsentant des Silberbunds in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Allianz im nordöstlichen Teil des Geländes.", progress = nil, completion = "Ich habe Euren Namen in die Listen aufgenommen, &lt;Name&gt;. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13668] = {title = "Das Argentumturnier", objective = "Sprecht mit Magister Edien Sonnental beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nMagister Edien Sonnental ist der Repräsentant der Sonnenhäscher in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Horde im südöstlichen Teil des Geländes.", progress = nil, completion = "Ich habe Euren Namen in die Listen aufgenommen, &lt;Name&gt;. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13669] = {title = "Eine würdige Waffe", objective = "Bringt die Klinge von Drak'Mar zu Arkanist Taelis beim Argentumturnierplatz.", description = "Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt wurden.\n\nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak'Marsee im Nordosten der Drachenöde in der Nähe von Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Stimmen die Geschichten der wandernden Barden? Habt Ihr eine Klinge mitgebracht?", completion = "Es besteht kein Zweifel daran, dass dies eine Klinge von außerordentlicher Qualität und Balance ist. Nun verstehe ich, weshalb diese Waffen unter den Champions der Allianz so begehrt sind.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13670] = {title = "Auf Winters Schneide", objective = "Arkanist Taelis beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", description = "Der Knappe des Großchampions von Eisenschmiede hat mir eine interessante Geschichte erzählt.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so ausgezeichnet, wie der Knappe meinte, doch woher wusste er von ihr? Das macht nichts - sie wird ihrem neuen Besitzer gute Dienste leisten. Vielleicht ist es nur gerecht, dass der Großchampion von Eisenschmiede der einzige sein wird, der sie trägt.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13671] = {title = "Feldübung", objective = "Avareth Flinkstoß beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Während Ihr auf dem Weg seid, den berittenen Kampf zu beherrschen, vergesst nicht, die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.\n\nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht. Haltet Euch jedoch vom Bombardement fern - man würde Euch überwältigen.", progress = "Habt Ihr Euch im Kampf gegen die Geißel erprobt?", completion = "Ihr habt Euch als fähiger Kämpfer erwiesen, &lt;Name&gt;, und Ihr werdet dem Rest der Streiter ein Beispiel sein, die da lautstark fordern, im Auftrag der Allianz anzutreten.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13672] = {title = "Der Herausforderung gewachsen", objective = "Überreicht Arkanist Taelis beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiter zu unterziehen.", description = "Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.\n\nKehrt zu mir zurück, wenn Ihr für die Herausforderung bereit seid.", progress = "Wollt Ihr Euch der Herausforderung des Streiters stellen?", completion = "Sehr gut, ich werde die Vorbereitungen treffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13673] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Magister Edien Sonnental beim Argentumturnierplatz.", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, &lt;Name&gt;. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13674] = {title = "Eine würdige Waffe", objective = "Bringt die Klinge von Drak'Mar zu Magister Edien Sonnental beim Argentumturnierplatz.", description = "Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt werden.\n\nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak'Marsee im Nordosten der Drachenöde in der Nähe von Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Stimmen die Geschichten der wandernden Barden? Habt Ihr eine Klinge mitgebracht?", completion = "Es besteht kein Zweifel daran, dass dies eine Klinge von außerordentlicher Qualität und Balance ist. Nun verstehe ich, weshalb diese Waffen unter den Champions der Allianz so begehrt sind.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13675] = {title = "Auf Winters Schneide", objective = "Magister Edien Sonnental beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", description = "Einer der Recken von Orgrimmar hat mir eine interessante Geschichte erzählt.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so ausgezeichnet, wie der Recke meinte, doch woher wusste er von ihr? Das macht nichts - sie wird ihrem neuen Besitzer gute Dienste leisten. Vielleicht ist es nur gerecht, dass der Großchampion von Orgrimmar der einzige sein wird, der sie trägt.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13676] = {title = "Feldübung", objective = "Amariel Sonnenschwur beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.", description = "Das Turnier ist eine Gelegenheit, Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Vergesst nicht, auf Eurem Weg zur Beherrschung des berittenen Kampfes auch die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.\n\nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht.", progress = "Habt Ihr Euch im Kampf gegen die Geißel erprobt?", completion = "Ihr habt Euch als fähiger Kämpfer erwiesen, &lt;Name&gt;, und Ihr werdet dem Rest der Streiter ein Beispiel sein, die da lautstark fordern, im Auftrag der Horde anzutreten.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13677] = {title = "Reitgrundlagen", objective = "Trefft ein Nahkampfziel fünfmal mit der Fähigkeit 'Zustoßen' und wendet die Fähigkeit 'Schildbrecher' auf 2 ungeschützte Distanzziele sowie die Fähigkeit 'Sturmangriff' auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Die meisten Wettkämpfe des Turniers erfordern von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Trainingsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf den Falkenschreiter der Sonnenhäscher. Macht Euch mit ihm vertraut und besiegt anschließend die drei verschiedenen Arten von Trainingsattrappen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", rewards = "Ihr bekommt:\n\nSiegel des Streiters"}
MultiLanguageQuestData['de'][13678] = {title = "Der Herausforderung gewachsen", objective = "Überreicht Magister Edien Sonnental beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiters zu unterziehen.", description = "Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.\n\nKehrt wieder zu mir zurück, wenn Ihr bereit seid, die Herausforderung anzutreten.", progress = "Wollt Ihr Euch der Herausforderung des Streiters stellen?", completion = "Sehr gut, ich werde die Vorbereitungen treffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13679] = {title = "Die Herausforderung des Streiters", objective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Arkanist Taelist beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Ihr habt hart trainiert, <Streiter/Streiters> <Name>, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen geschickten Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf das Streitross der Quel'dorei, das dort untergebracht ist.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr Knappe David vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, <Name>. Möget Ihr stets sicher im Sattel sitzen und Eure Pfeile ins Schwarze treffen.", progress = nil, completion = "Meine gebührenden Glückwünsche, &lt;Name&gt;. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13680] = {title = "Die Herausforderung des Streiters", objective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Magister Edien Sonnental beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.", description = "Ihr habt hart trainiert, <Streiter/Streiterin> <Name>, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen erfahrenen Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf den Falkenschreiter der Sonnenhäscher.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr ein Menschenkind, einen Knappen namens David, vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, <Name>. Möget Ihr sicher im Sattel sitzen und Euer Pferd gleichmäßig reiten.", progress = nil, completion = "Meine gebührenden Glückwünsche, &lt;Name&gt;. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13681] = {title = "Wie der Block so der Splitter", objective = "Bringt 15 kleine Steinblöcke zu Stümpi Sprengbolz beim Argentumturnierplatz.", description = "Stein für diesen Job zu besorgen war der reinste Alptraum, das kann ich Euch sagen! Es gibt in den Ruinen sichere Orte, an denen es tonnenweise Stein zu finden gibt, doch diese selbstgerechten Paladine wollen einfach nicht zugreifen. Hat was mit unbezahlbaren Artefakten zu tun, oder so was.\n\nWie dem auch sei: Darüber zu jammern wird auch nicht helfen, diesen Ort aufzubauen. In den Fußmarschen und der Bibliothek des Erfinders in den Sturmgipfeln gibt es eine ganze Reihe Titanenruinen. Nehmt meinen, ähm, 'Meißel' mit und seht, ob Ihr diese riesigen Blöcke nicht in brauchbare Stücke zerhauen könnt.", progress = "Habt Ihr die Steinblöcke dabei?", completion = "Die sollten reichen. Sagt den Kreuzfahrern bloß nicht, woher Ihr sie habt. Ich bin mir sicher, dass sie sich darüber aufregen würden. Aber hey, es ist ja nicht so, als wären die Titanen für sie zurückgekommen. Wenn's nach mir geht, kann man sie sich einfach nehmen. Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13682] = {title = "Bedrohung von oben", objective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", progress = nil, completion = "&lt;Name&gt;, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von NordendSiegel des Champions"}
MultiLanguageQuestData['de'][13683] = {title = "Die Rituale aufhalten", objective = "Stört 8 Ritualedelsteine.", description = "Ich habe zufällig mit angehört, welchen Verlust Illiyana erfahren musste. Ich kann ihren Wunsch nach Rache verstehen. Ich frage mich, ob Ihr, während Ihr diese ausführt, uns einen Dienst erweisen könntet?\n\nZweifellos habt Ihr bereits die Satyrn von Satyrnaar und Xavian gesehen, wie sie ekelhafte Rituale durchführen. Ich glaube, sie bereiten Rituale vor, die jeden der Nachtelfen, den sie fangen, in Satyrn verwandeln sollen. Wir Draenei möchten ebenfalls nicht, dass diese üble Magie sich verbreitet.\n\nWürdet Ihr die Ritualedelsteine stören während Ihr dort seid?", progress = nil, completion = "Wir stehen in Eurer Schuld, &lt;Klasse&gt;.\n\nDie Rituale können nicht mehr abgeschlossen werden und die Satyrn kämpfen nun auf verlorenem Posten, da sie ihre Anzahl nicht mehr mehren können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13684] = {title = "Ein Recke von Sturmwind", objective = "Sprecht mit Marschall Jacob Alerius beim Argentumturnierplatz, um ein Recke von Sturmwind zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sturmwind anzutreten, <Name>. Nun solltet Ihr mit Marschall Jacob Alerius sprechen, der Sturmwinds Wettkämpfer anführt. Als Großchampion von Sturmwind wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Na dann willkommen an Bord, Recke &lt;Name&gt;. Die Delegation von Sturmwind ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13685] = {title = "Ein Recke von Eisenschmiede", objective = "Sprecht mit Lana Starkhammer beim Argentumturnierplatz, um ein Recke von Eisenschmiede zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Eisenschmiede anzutreten, <Name>. Nun solltet Ihr mit Lana Starkhammer sprechen, die die Wettkämpfer von Eisenschmiede anführt. Als Großchampion der Stadt wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Gut, Euch kennenzulernen, Recke. Eisenschmiede braucht Wettkämpfer wie Euch, um auf dem Turnier zu bestehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13688] = {title = "Ein Recke von Gnomeregan", objective = "Sprecht mit Ambrose Bolzenfunk beim Argentumturnierplatz, um ein Recke von Gnomeregan zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Gnomeregan anzutreten, <Name>. Nun solltet Ihr mit Ambrose Bolzenfunk sprechen, der die Wettkämpfer von Gnomeregan anführt. Als Großchampion der Gnome wird er Euch in ihrem Namen für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Na dann willkommen an Bord, Recke &lt;Name&gt;. Die Delegation von Gnomeregan ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13689] = {title = "Ein Recke von Darnassus", objective = "Sprecht mit Jaelyne Abendlied beim Argentumturnierplatz, um ein Recke von Darnassus zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Darnassus anzutreten, <Name>. Nun solltet Ihr mit Jaelyne Abendlied sprechen, die die Wettkämpfer von Darnassus anführt. Als Großchampion der Nachtelfen wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Willkommen zur Turniersdelegation von Darnassus, &lt;Name&gt;. Es wird eine Freude sein, an Eurer Seite zu trainieren und am Wettkampf teilzunehmen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13690] = {title = "Ein Recke der Exodar", objective = "Sprecht mit Kolosos beim Argentumturnierplatz, um ein Recke der Exodar zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner der Exodar anzutreten, <Name>. Nun solltet Ihr Euch Kolosos vorstellen, dem Leiter der Delegation der Exodar. Als Großchampion der Draenei wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Na dann willkommen an Bord, Recke &lt;Name&gt;. Die Delegation der Exodar ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13691] = {title = "Ein Recke von Orgrimmar", objective = "Sprecht mit Mokra dem Schädelberster beim Argentumturnierplatz, um ein Recke von Orgrimmar zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Orgrimmar anzutreten, <Name>. Nun solltet Ihr mit Mokra dem Schädelberster sprechen, der Orgrimmars Wettkämpfer anführt. Als Großchampion von Orgrimmar wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Ihr wollt also für Orgrimmar antreten? Nur, weil Ihr ein paar Attrappen verhauen habt, heißt das noch lange nicht, dass Ihr auch gewinnen werdet. Doch von nun an werdet Ihr mit den Besten zusammen trainieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13692] = {title = "Das Schwert und die See", objective = "Der alte Barlo im Kristallsangwald möchte, dass Ihr ihm das Schwert der Ritterwürde bringt.", description = "Mein Schwert ist auf See verloren gegangen. Holt es herauf und bringt es zurück!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][13693] = {title = "Ein Recke von Sen'jin", objective = "Sprecht mit Zul'tore beim Argentumturnierplatz, um ein Recke von Sen'jin zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sen'jin anzutreten, <Name>. Nun solltet Ihr mit Zul'tore sprechen, der die Krieger von Sen'jin anführt. Als Großchampion der Trolle wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Ihr denkt, dass Ihr das Zeug dafür habt, in Sen'jins Namen am Wettkampf teilzunehmen? Wir werden es herausfinden, denke ich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13694] = {title = "Ein Recke von Donnerfels", objective = "Sprecht mit Runok Wildmähne beim Argentumturnierplatz, um ein Recke von Donnerfels zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Donnerfels anzutreten, <Name>. Nun solltet Ihr mit Runok Wildmähne sprechen, der Donnerfels' Wettkämpfer anführt. Als Großchampion von Donnerfels wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Im Namen von Donnerfels und seinen Kriegern heiße ich Euch willkommen, &lt;Name&gt;. Kämpft unter unserem Banner stets mit Ehre und Tapferkeit.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13695] = {title = "Ein Recke von Unterstadt", objective = "Sprecht mit Todespirscher Visceri beim Argentumturnierplatz, um ein Recke von Unterstadt zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Unterstadt anzutreten, <Name>. Nun solltet Ihr mit Todespirscher Visceri sprechen, der Unterstadts Wettkämpfer anführt. Als Großchampion wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Willkommen in der Delegation von Unterstadt, &lt;Name&gt;. Als Recke werdet Ihr mit uns trainieren, um Euch auf die höchste Stufe des Wettkampfes vorzubereiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13696] = {title = "Ein Recke von Silbermond", objective = "Sprecht mit Eressea Morgensänger beim Argentumturnierplatz, um ein Recke von Silbermond zu werden.", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Silbermond anzutreten, <Name>. Nun solltet Ihr mit Eressea Morgensänger sprechen, die Silbermonds Wettkämpfer anführt. Als Großchampion von Silbermond wird sie Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, <Name>, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", progress = nil, completion = "Ihr wollt also für Silbermond antreten? Nun gut. Ich werde Euch in die Namensliste aufnehmen und Ihr könnt sofort damit anfangen, mit den anderen Recken zusammenzuarbeiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13697] = {title = "Das Wappen des Recken", objective = "Bringt 25 Siegel des Recken zu Mokra dem Schädelberster beim Argentumturnierplatz.", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13698] = {title = "Sprengstoffschreddern", objective = "Verwendet einen Kriegshymnenschredder um 8 Fässer mit Sprengstoff zu vernichten.", description = "Ich hasse es, Euch wieder dorthin zurückzuschicken, aber Eurer Beschreibung entnehme ich, dass wir es nicht zulassen dürfen, dass sie den ganzen Sprengstoff verwenden, den sie gelagert haben!\n\nEs ist zu gefährlich für Euch, ihn einfach so zu zerstören, aber wenn Ihr einen der Schredder stehlen könntet, bin ich mir sicher, dass er robust genug ist, den Explosionen standzuhalten.\n\nNachdem Ihr den Sprengstoff vernichtet habt, kehrt mit dem Schredder wieder hierher zurück. Es wäre närrisch, ihn wieder der Horde zu überlassen.", progress = nil, completion = "Ich habe die Explosionen bis hierher sehen können! Diesen widerwärtigen Orcs und ihren Goblinlakaien wird es nun schwer fallen, den Wald weiter zu zerstören!\n\nWir können Euch nicht genug danken, &lt;Name&gt;. Bitte nehmt dies.", rewards = "SchredderklingePulverbrennerwesteWaldbehütergamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13699] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Marschall Jacob Alerius beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, im Namen Sturmwinds beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet im Namen Sturmwinds auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Allianz platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13702] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Herzlichen Glückwunsch, <Name>. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumknappeSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13703] = {title = "Recke von Eisenschmiede", objective = "Sprecht wieder mit Lana Starkhammer, falls Ihr ein Recke von Eisenschmiede werden wollt.", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Wollt Ihr der Turniersdelegation von Eisenschmiede beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Eisenschmiede ernannt hat, wird Euer Knappe unser Banner in die Schlacht tragen dürfen.", progress = nil, completion = "Wir sind stolz, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und ich weiß, dass Ihr auf dem Schlachtfeld glänzen werdet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13704] = {title = "Recke von Gnomeregan", objective = "Sprecht wieder mit Ambrose Bolzenfunk, falls Ihr ein Recke von Gnomeregan werden wollt.", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Gnomeregans Delegation könnte von jemandem wie Euch wirklich profitieren.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Gnomeregan ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Wir sind stolz, Euch unter uns zählen zu dürfen, &lt;Name&gt;, und wir freuen uns darauf, mit Euch zu trainieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13705] = {title = "Recke der Exodar", objective = "Sprecht wieder mit Kolosos, falls Ihr ein Recke der Exodar werden wollt.", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation der Exodar beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion der Exodar ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Es ist gut, dass Ihr nun zu uns gehört, &lt;Name&gt;. Wir werden alle vom Training mit Euch profitieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13706] = {title = "Recke von Darnassus", objective = "Sprecht wieder mit Jaelyne Abendlied, falls Ihr ein Recke von Darnassus werden wollt.", description = "Seid willkommen, Champion. Ich habe von Euren Leistungen gehört und wir wären geehrt, wenn Ihr der Delegation von Darnassus beitreten würdet.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Darnassus ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Die Krieger von Darnassus sind geehrt, an Eurer Seite kämpfen und trainieren zu dürfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13707] = {title = "Recke von Orgrimmar", objective = "Sprecht wieder mit Mokra dem Schädelberster, falls Ihr ein Recke von Orgrimmar werden wollt.", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Orgrimmars Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Orgrimmar ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Dann seid willkommen, &lt;Name&gt;. Ich freue mich darauf, Euch beim Training mit meinen Männern zuzusehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13708] = {title = "Recke von Sen'jin", objective = "Sprecht wieder mit Zul'tore, falls Ihr ein Recke von Sen'jin werden wollt.", description = "Grüße, Champion. Wenn Ihr wollt, dann würde ich Euch in Sen'jins Turniersdelegation willkommen heißen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Sen'jin ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Ich bin froh, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und freue mich darauf, Euch in Aktion zu sehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13709] = {title = "Recke von Donnerfels", objective = "Sprecht wieder mit Runok Wildmähne, falls Ihr ein Recke von Donnerfels werden wollt.", description = "Willkommen, Champion. Als Großchampion der Delegation von Donnerfels wäre ich stolz darauf, Euch in unseren Reihen begrüßen zu dürfen, falls Ihr dies wünscht.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Donnerfels ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Es ehrt mich, dass Ihr Euch dazu entschlossen habt, unserer Delegation beizutreten. Ich weiß, dass Ihr uns stolz machen werdet, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13710] = {title = "Recke von Unterstadt", objective = "Sprecht wieder mit Todespirscher Visceri, falls Ihr ein Recke von Unterstadt werden wollt.", description = "Seid willkommen, Champion. Die Delegation der Verlassenen könnte immer so jemanden wie Euch gebrauchen. Wollt Ihr uns beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Unterstadt ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Ihr habt eine weise Entscheidung getroffen, &lt;Name&gt;. Wir beide werden von dieser Abmachung profitieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13711] = {title = "Recke von Silbermond", objective = "Sprecht wieder mit Eressea Morgensänger, falls Ihr ein Recke von Silbermond werden wollt.", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Silbermonds Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Silbermond ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", progress = nil, completion = "Es wird uns eine Ehre sein, mit Euch zu trainieren und am Wettkampf teilzunehmen, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Tournament Eligibility Flag\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13712] = {title = "Rettung in der Not", objective = "Sprecht mit Kadrak am Schutzwall von Mor'shan und begleitet ihn zum Splitterholzposten.", description = "Ihr kommt mit mir mit, <Name>.\n\nIch kann niemanden sonst erübrigen und wir können es uns nicht leisten, den Splitterholzposten zu verlieren.\n\nBereitet Euch gut vor und sprecht mich wieder an, wenn Ihr soweit seid.", progress = nil, completion = "Gorkas Tod war nicht umsonst, &lt;Name&gt;.\n\nDer Splitterholzposten wäre sicher gefallen, wenn wir nicht rechtzeitig gekommen wären.\n\nJetzt müssen wir uns daran machen, die Verteidigung wieder aufzubauen.\n\nEs ist noch nicht vorbei...", rewards = "Ihr bekommt:\n\nGorkas Band"}
MultiLanguageQuestData['de'][13713] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Lana Starkhammer beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, im Namen von Eisenschmiede beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet im Namen von Eisenschmiede auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Allianz platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13714] = {title = "Das Wappen des Recken", objective = "Bringt 25 Siegel des Recken zu Lana Starkhammer beim Argentumturnierplatz.", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", rewards = "Ihr bekommt:\n\n"}
