MultiLanguageQuestData['de'][13723] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Ambrose Bolzenfunk beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, im Namen Gnomeregans beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet im Namen von Gnomeregan auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Allianz platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13724] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Kolosos beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, im Namen der Exodar beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet im Namen der Exodar auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Allianz platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13725] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Jaelyne Abendlied beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, im Namen Darnassus beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet im Namen von Darnassus auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Allianz platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13726] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Mokra dem Schädelberster beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner Orgrimmars die Konkurrenz vernichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Horde platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13727] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Zul'tore beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner der Dunkelspeere die Konkurrenz vernichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Horde platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13728] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Runok Wildmähne beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = "Habt Ihr den Argentumchampion bezwungen?", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Donnerfels die Konkurrenz vernichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Horde platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13729] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Todespirscher Visceri beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = "Habt Ihr den Argentumchampion bezwungen?", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Unterstadt die Konkurrenz vernichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Horde platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13730] = {title = "Spiel mit dem Teufelsfeuer", objective = "Draaka im Splitterholzposten möchte, dass Ihr den verstärkten Kanister mit 7 Teufelsfeuern vom Dämonenhügel füllt.", description = "<Draaka neigt sich zu Euch, um mit Euch zu sprechen.>\n\nHört... Bevor Ihr etwas sagt, ich WEISS, dass wir uns nicht mit dämonischen Kräften einlassen sollten...\n\nAber seht Euch um! Es herrschen verzweifelte Zeiten, <Klasse>.\n\nWir werden aller Wahrscheinlichkeit nach trotzdem hier sterben. Wir können genauso gut mit Glanz und Glorie untergehen, sage ich!\n\nAlso... Seid Ihr dabei?\n\nNehmt diesen Kanister und begebt Euch nach Südosten zum Dämonenhügel. Verwendet ihn in der Nähe der Felder aus Teufelsfeuer und bringt ihn mir wieder, wenn Ihr ihn gefüllt habt.\n\nOh, und am besten, Ihr sprecht mit niemandem darüber...", progress = nil, completion = "Oh, ja!\n\nDas wird diesen Elfen eine Lektion erteilen. Seht einfach zu!", rewards = "Schneide der TorheitTeufelsfeuerbesudelte WesteBeinschützer der verlorenen TugendIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13731] = {title = "Die Herausforderung des Recken", objective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Eressea Morgensänger beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der angebundenen Nähe der Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", progress = nil, completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, &lt;Name&gt;. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Silbermond die Konkurrenz vernichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChampionflagge der Horde platzieren\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13732] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Herzlichen Glückwunsch, <Name>. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz möchte mit Euch sprechen, <Name>, und Euch offiziell beim großen Arenakampf anmelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumknappeSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13733] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Herzlichen Glückwunsch, <Name>. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArgentumknappeSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13734] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Herzlichen Glückwunsch, <Name>. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumknappeSiegel des ChampionsSiegel des Champions"}
