MultiLanguageQuestData['de'][13736] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre Orgrimmars den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumgrunzlingSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13737] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre der Dunkelspeere den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumgrunzlingSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13738] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre von Donnerfels den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumgrunzlingSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13739] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre der Verlassenen den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumgrunzlingSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13740] = {title = "Aufstieg eines Champions", objective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Ihr habt Euch meinen und den Respekt der Euch gleichgestellten verdient, habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre Silbermonds den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, <Name>, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", progress = nil, completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, &lt;Name&gt;. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, &lt;Name&gt;, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", rewards = "Ihr bekommt:\n\nArgentumgrunzlingSiegel des ChampionsSiegel des Champions"}
MultiLanguageQuestData['de'][13741] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Lana Starkhammer beim Argentumturnierplatz.", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln, die eine mächtige Klinge bewachte. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, sodass die Klinge nimmermehr gezogen werden könnte. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13742] = {title = "Eine würdige Waffe", objective = "Bringt Lana Starkhammer beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "&lt;Der Großchampion nimmt die Klinge von Drak'Mar entgegen.&gt;\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13743] = {title = "Auf Winters Schneide", objective = "Lana Starkhammer beim Argentumturnierplatz möchte, dass Ihr ihr die Winterschneide beschafft.", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13744] = {title = "Feldübungen eines Recken", objective = "Rollo Immertreff beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13745] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Clara Torkelbräu beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Eisenschmiede freuen sich auf die Nachricht unseres Sieges - und damit diese auch eintrifft, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut. Die Recken trainieren in einem Ring direkt neben unserem Zelt. Nehmt Eure Lanze, geht zu den Reittieren außerhalb des Pavillons, steigt auf den Widder aus Eisenschmiede, der dort steht, und fordert andere Allianzrecken heraus.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Bürger von Eisenschmiede stolz machen werdet, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13746] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Ambrose Bolzenfunk beim Argentumturnierplatz.", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13747] = {title = "Eine würdige Waffe", objective = "Bringt Ambrose Bolzenfunk beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "&lt;Ambrose nimmt die Klinge von Drak'Mar entgegen.&gt;\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13748] = {title = "Auf Winters Schneide", objective = "Ambrose Bolzenfunk beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", description = "Das ist das letzte Mal, dass ich mich mit einem Todesritter anlege.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13749] = {title = "Feldübungen eines Recken", objective = "Klack Radspanner beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13750] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Klick Radspanner beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Wir wissen, wie sich alle darauf freuen, dass wir am Wettkampf mitmachen, und wir wollen sie nicht enttäuschen. Deswegen haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Turboschreiter, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr uns stolz machen werdet, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13751] = {title = "Schweigt still wie ein Grab!", objective = "Draaka im Splitterholzposten möchte, dass ihr die hastig geschriebene Notiz an Durak überbringt.\n\nBereitgestellter Gegenstand: \n", description = "Perfekt!\n\nDas wird die Elfen lehren, wozu die Horde in der Lage ist, wenn sie mit dem Rücken an der Wand steht.\n\nHört zu, <Name>. Ihr dürft niemandem etwas davon erzählen!\n\nGarrosh wird es sicherlich gutheißen, sobald er das Ergebnis sieht, aber wenn im Voraus etwas bekannt wird, enden unsere Köpfe auf einem Spieß!\n\n<Draaka händigt Euch eine hastig geschriebene Notiz aus.>\n\nBringt das zu Durak. Ihr findet ihn in den Minen hinter mir in Richtung Norden. Er wird Euch weitere Anweisungen geben.", progress = nil, completion = "Was ist das? Wer seid Ihr!?\n\n&lt;Durak liest Draakas Notiz.&gt;\n\nHrmphh...\n\nDraaka sollte es besser wissen und nicht so unverschämt sein, aber es sieht so aus, als ob Ihr bis zu den Haarspitzen mit drinsteckt und genauso viel zu verlieren habt wie jeder andere.\n\nWohlan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13752] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Kolosos beim Argentumturnierplatz.", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
