MultiLanguageQuestData['de'][13755] = {title = "Feldübungen eines Recken", objective = "Saandos beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13756] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Ranii beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger der Exodar freuen sich darauf zuzusehen, wie wir ihn gewinnen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Azurmythoselekk, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr uns stolz machen werdet, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
