MultiLanguageQuestData['de'][13760] = {title = "Feldübungen eines Recken", objective = "Illestria Klingensänger beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13761] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Airae Sternensucher beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Darnassus freuen sich darauf, zuzusehen, wie wir ihn gewinnen. Damit das auch geschieht, haben sie im Kampf gegen die Recken der anderen Allianzhauptstädte an ihren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nDer Ring der Recken der Allianz befindet sich direkt neben unserem Zelt. Geht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den darnassischen Nebelsäbler, der dort steht, und fordert die Recken heraus.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Darnassus stolz machen werdet, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13762] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Mokra dem Schädelberster beim Argentumturnierplatz.", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13763] = {title = "Eine würdige Waffe", objective = "Bringt Mokra dem Schädelberster beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13764] = {title = "Auf Winters Schneide", objective = "Mokra der Schädelberster beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13765] = {title = "Feldübungen eines Recken", objective = "Akinos beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13766] = {title = "Verschlossene Tore", objective = "Schließt mit Knorres Zweig 10 Dämonentore.", description = "Ich kann es in der Erde spüren, dass weitere Dämonen in unsere Welt gebracht werden. Bald werden es zu viele sein und wir werden von ihnen überrannt werden, ohne Hoffnung darauf, sie zurückzuschlagen.\n\nNehmt diesen Teil von mir und kehrt zum Dämonensturz und zum Dämonenstieg südlich vom Dämonenhügel zurück. Zeigt mit dem Zweig auf ein Dämonentor und konzentriert Euch. Ich habe einen Teil der Lebensenergien des Waldes in seinem Holz gespeichert und er wird das Tor schließen.", progress = nil, completion = "Wenn die Tore geschlossen sind und keine weitere Verstärkung mehr herausströmt, ist es nur eine Frage der Zeit, bevor die Dämonen nicht mehr sind.\n\nIhr seid ein Held des Waldes, &lt;Name&gt;. Ich danke Euch im Namen aller Kreaturen im Eschental.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13767] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Morah Worgschwester beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Wolf aus Orgrimmar, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13768] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Zul'tore beim Argentumturnierplatz.", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13769] = {title = "Eine würdige Waffe", objective = "Bringt Zul'tore beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13770] = {title = "Auf Winters Schneide", objective = "Zul'tore beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13771] = {title = "Feldübungen eines Recken", objective = "Schattenjäger Mezil-kree beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Willkommen zurück von Euren Übungen, &lt;Name&gt;. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13772] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Gahju beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Raptor der Dunkelspeere, der dort steht, und fordert die Recken heraus. Sie warten auf Euch im Ring der Recken der Horde gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Durch das Training mit den anderen Recken werdet Ihr Euch schnell das notwendige Wissen aneignen, mit dem Ihr sie schlagen könnt. Macht weiter so und Ihr werdet keine Probleme damit haben, sie im Wettkampf zu besiegen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13773] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Runok Wildmähne beim Argentumturnierplatz.", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
