MultiLanguageQuestData['de'][13776] = {title = "Feldübungen eines Recken", objective = "Dern Zorntotem beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13777] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Anka Klauenhuf beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Mulgorekodo, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13778] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Todespirscher Visceri beim Argentumturnierplatz.", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13779] = {title = "Eine würdige Waffe", objective = "Bringt Todespirscher Visceri beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13780] = {title = "Auf Winters Schneide", objective = "Todespirscher Visceri beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13781] = {title = "Feldübungen eines Recken", objective = "Sarah Chalke beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13782] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Tierführer Dretch beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Kampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillon, nehmt Eure Lanze, steigt auf das Schlachtross der Verlassenen, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13783] = {title = "Eine Klinge, eines Champions würdig", objective = "Besorgt Eschenbrand und bringt es Eressea Morgensänger beim Argentumturnierplatz.", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, <Name>. Ansonsten fangt Ihr Euch Warzen ein.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13784] = {title = "Eine würdige Waffe", objective = "Bringt Eressea Morgensänger beim Argentumturnierplatz die Klinge von Drak'Mar.", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13785] = {title = "Auf Winters Schneide", objective = "Eressea Morgensänger beim Argentumturnierplatz möchte, dass Ihr ihr Winterschneide bringt.", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, <Name>.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13786] = {title = "Feldübungen eines Recken", objective = "Kethiel Sonnenlanze beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", progress = nil, completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13787] = {title = "Der große Arenakampf", objective = "Bringt 3 Male des Recken zu Aneera Thuron beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Falkenschreiter von Silbermond, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLanze entfernen\n\nIhr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13788] = {title = "Bedrohung von oben", objective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", progress = nil, completion = "&lt;Name&gt;, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von NordendSiegel des Champions"}
MultiLanguageQuestData['de'][13789] = {title = "Die Schlacht zum Gegner tragen", objective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Anhänger des Kults der Verdammten im Bereich von Eiskrone.", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, <Name>. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", progress = nil, completion = "Ihr seid ein wahrer Champion, &lt;Name&gt;, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13790] = {title = "Unter Champions", objective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Diejenigen, die Ihr besiegt habt, werden bis zum Beginn des Turniers ihre Anstrengungen verdoppelt haben und danach trachten, ihren Verlust zu rächen, den sie durch Euch erfahren mussten.\n\nEs wäre Euch anzuraten, im Kampf mit den Streitern, die im Ring der Champions auf Euch warten, Eure Fähigkeiten zu verbessern. Nehmt Eure Lanze, geht zur Südseite des Platzes, besteigt eines der Euch zur Verfügung stehenden, angebundenen Reittiere und fordert sie heraus.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Allianz stolz machen werdet, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13791] = {title = "Die Schlacht zum Gegner tragen", objective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", progress = nil, completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13792] = {title = "Der Schattenwandler", objective = "Sprecht mit Gaivan Schattenwandler, der vor dem Eingang zum Grabhügel von Dor'Danil im Eschental wandelt.", description = "Jetzt, wo die Dämonentore zerstört sind, muss die Kraft des Waldes wieder regeneriert werden. Das Herz des Waldes muss wiedererlangt werden!\n\nGaivan Schattenwandler, ein mächtiger Druide der Klaue ist Richtung Südwesten am Dämonenhügel vorbei zum Grabhügel von Dor'Danil gegangen. Darin liegt das Herz des Waldes. Es wird von den Druiden von Eschental tief unter der Oberfläche beschützt.\n\nSucht nach Gaivan und erzählt ihm, was sich zugetragen hat, <Name>.", progress = nil, completion = "Ihr seid mutig, hierher zu kommen, &lt;Klasse&gt;, aber Ihr seid vielleicht zu spät. All unsere Druiden sind entweder tot oder sind verrückt geworden.\n\nDennoch, Eure Geschichte ist faszinierend und wenn das, was Ihr sagt, wahr ist, dann muss Knorre das Herz des Waldes bald bekommen oder Eschental wird vergehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13793] = {title = "Unter Champions", objective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen besiegt. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt irgendein Euch zur Verfügung stehendes Reittier aus und fordert sie heraus.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, &lt;Name&gt;. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13794] = {title = "Eadric der Reine", objective = "Sprecht mit Eadric dem Reinen beim Argentumturnierplatz.", description = "Ich habe meine Brüder des Argentumkreuzzugs gebeten, eng mit denjenigen zusammenzuarbeiten, die zum Champion aufsteigen. Eadric der Reine, der Großchampion unserer Bruderschaft, hilft dabei, die Trainingsübungen für Champions aller Städte zu beaufsichtigen und sie bei ihren letzten Vorbereitungen für den Turnierwettkampf zu unterstützen.\n\nBitte geht nun und stellt Euch ihm vor. Ich bin mir sicher, dass er begierig darauf sein wird, Eure Bekanntschaft zu machen und Euch auf Eurem Weg zum Wettkampf mit Azeroths größten Champions zu begleiten.", progress = nil, completion = "Gut, Euch endlich kennenzulernen, Champion. Der Hochlord hat mich gebeten, die Koordination der Champions in die Hand zu nehmen, um dafür zu sorgen, dass sie miteinander trainieren und die Verteidigung des Turnierplatzes verstärken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13795] = {title = "Der Geißelbann", objective = "Sprecht mit Crok Geißelbann beim Argentumturnierplatz.", description = "Der Delegationsanführer der Ritter der Schwarzen Klinge hat darum gebeten, mit Euch zu sprechen, <Klasse>. Crok Geißelbann ist ein äußerst furchterregender Kämpfer und ich hege keine Zweifel daran, dass er viel von Euch fordern wird.\n\nDie Ritter der Schwarzen Klinge haben auf der Nordseite des Turnierplatzes ihr Lager aufgeschlagen, westlich der Zeltbehausungen der Allianzdelegationen.", progress = nil, completion = "Ihr seid also ein Champion geworden, &lt;Name&gt;. Ich hatte keine Zweifel daran, dass dies geschehen wird. Wir Ritter wurden in der Hitze des Kampfes ausgebildet, nicht an hölzernen Attrappen. Lasst uns den Paladinen und ihren Gästen zeigen, was die Schlacht aus uns gemacht hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13796] = {title = "Das Herz des Waldes", objective = "Beschafft das Herz des Waldes.", description = "Ihr müsst das Herz des Waldes um jeden Preis zu Knorre bringen!\n\nEs liegt tief unten im Grabhügel von Dor'Danil - verdorben von der Horde. Nur Knorre kann es reinigen.\n\nUm es vom Fleck zu bewegen, braucht Ihr jedoch eine Kraft der Natur. Wenn Ihr ausreichend reine Erdgeister von den abtrünnigen Druiden und Bewahrern einsammelt, können die Erdgeister zu einer Kraft der Natur vereint werden.\n\nViel Glück, <Name>!", progress = "<Name>, Ihr seid zurückgekehrt.", completion = "Das Herz des Waldes! Es ist verdorben!\n\n&lt;Das große Urtum knarrt, als seine gigantischen Gliedmaßen damit beginnen, ein Ritual durchzuführen.&gt;\n\nBleibt zurück, &lt;Name&gt;, ich werde versuchen, das Herz zu reinigen, bevor alles verloren ist!", rewards = "WaldgrazienmantelungGamaschen des abtrünnigen DruidenKnarzrindenschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13797] = {title = "Gemeinheiten", objective = "Durchsucht die Haufen frischen Gerölls, um 10 Erzklumpen zu finden.", description = "Draaka benötigt eine Art von Magnet – etwas, das ihre dämonischen Geschosse anzieht.\n\n<Durak grinst verschlagen.>\n\nZufällig kenne ich eine Methode, die unserem Zwecke dienlich sein sollte.\n\nIhr sucht die Minen nach faustgroßen Erzklumpen ab, und ich bereite eine besondere... Verzauberung vor.", progress = "Habt ihr die Erzklumpen eingesammelt, die wir brauchen?", completion = "Gute Arbeit! Sie sollten den Fluch für unsere Zwecke lange genug tragen können...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13798] = {title = "Regen der Zerstörung", objective = "Nutzt das verfluchte Erz, um Ziele für Draaka zu markieren. Ihr müsst 30 Nachtelfentruppen und 5 tobende Urtume töten.\n\nSprecht mit Durak, um die Wichtelverkleidung aufzufrischen.", description = "Gerade rechtzeitig, <Klasse>. Die Elfen haben einen weiteren Angriff gestartet!\n\nVerwendet das verfluchte Erz von den Wachtürmen aus, um die Ziele für Draaka zu markieren.\n\nIhre Projektile werden Eure Ziele treffen und magische Höllenflammen hervorbrechen lassen, die alle Feinde im Umfeld vernichten.\n\nEs gibt starke Vorurteile gegen den Gebrauch von dämonischer Magie. Unberechtigterweise, aber dennoch. Aus diesem Grund werde ich Euch für die Dauer der Mission in einen Wichtel verwandeln, um zu verhindern, dass man Euch erkennt.", progress = nil, completion = "Habt Ihr das gespürt, &lt;Name&gt;!?\n\nWie die reine Teufelskraft durch Euer Sein brodelt?\n\nDas ist mit nichts vergleichbar!", rewards = "Verwichtelte KlingeVerfluchter StreitkolbenDuraks ZauberstabAuf Euch wartet eine dieser Belohnungen:\n\nBand der faulen Stärke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nCancel Imp Disguise\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13799] = {title = "Wo sind meine Schlüssel?", objective = "Dr. Finger möchte, dass Ihr seinen bösen Zwilling, Bösfinger, tötet und ihm seine Schlüssel abnehmt.", description = "Ich kann meine Schlüssel nicht finden! Sicher ist mein böser Zwilling schuld daran. Bitte \"kümmert\" Euch um ihn, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13801] = {title = "Geisterelfen", objective = "Vernichtet 15 beliebige Nachtelfengeister in den Grabhügeln von Dor'Danil.", description = "H-habt Ihr das gehört? Geister! Ich hasse Geister!\n\nIhr schauerliches Geheul kommt aus den Grabhügeln im Süden. Ahhh! Macht, dass sie aufhören!\n\nBitte, <mein Herr/gnädiges Fräulein>, ich zahle gutes Geld dafür, wenn Ihr mir diese Stimmen aus dem Kopf schafft!", progress = nil, completion = "Wohooo!!\n\nIhr habt die Stimmen zum Schweigen gebracht! Habt Dank, vielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13802] = {title = "Der Goblin mit zwei Gehirnen", objective = "Bringt das Stammhirn eines Sabberzahnmurlocs zu Professor Flozz an der Küste.", description = "Seht Ihr sie dort, entlang der Küste? Was für prächtige Exemplare! Seht Euch nur an, wie Ihre primitive Gesellschaft zusammenarbeitet, wie eine gut geölte Maschine, vom niedrigsten Arbeiter bis zu ihrem Anführer, den ich \"König Burgrurble\" genannt habe.\n\nIch muss einfach ihre Gehirne untersuchen.\"\n\nKönnt Ihr mir ein intaktes Stammhirn eines Sabberzahnmurlocs beschaffen? Tötet sie - für die Wissenschaft!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13803] = {title = "Das Blut der Schwachen", objective = "Kadrak will, dass Ihr die blutbesudelte Axt zu Durak im Splitterholzposten bringt.\n\nBereitgestellter Gegenstand: \n", description = "Wir wussten, dass die Elfen sich nicht kampflos ergeben würden, aber niemand hatte damit gerechnet, dass sie es fertig bringen, den Splitterholzposten zu belagern...\n\nEs wird Zeit, dass sie dafür bezahlen!\n\nIn der Nähe, im Grabhügel von Dor'Danil, liegt etwas, das dem Feind äußerst teuer ist – das Herz des Waldes.\n\nIch brauche jemanden, der sich bis zum Herzen durchschlägt und es verderbt.\n\nDieser jemand seid Ihr, <Name>.\n\nDoch zunächst bringt meine Axt zu Durak hier in den Minen. Er wird mit dem Blut unserer Feinde etwas anzufangen wissen.", progress = nil, completion = "Das Herz des Waldes verderben?\n\nWie skrupellos – ein äußerst heimtückischer Schlag...\n\nDas gefällt mir!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13805] = {title = "Mitten ins Herz!", objective = "Durak will, dass Ihr das besudelte Blut der Kaldorei auf das Herz des Waldes anwendet.", description = "So...\n\nDas Blut der gefallenen Kaldorei hat sich gewandelt. Es kann jetzt auf das Herz des Waldes im Grabhügel von Dor'Danil angewandt werden. Dadurch wird es gänzlich verderbt werden.\n\nDas heilige Relikt der hochmütigen Elfen wird gegen sie gerichtet. Das ist die Ironie des Lebens!\n\n<Durak lacht gehässig.>\n\nDer Grabhügel schmiegt sich in die Hügel im Südosten. Einer meiner Wichtel hat eine Blutspur gelegt, die vom Eingang bis zum Herzen führt.\n\nEilt Euch! Kadrak ist wahrscheinlich nicht besonders geduldig.\n\nFort mit Euch, <Klasse>.", progress = nil, completion = "Ist es vollbracht?\n\nGute Arbeit, &lt;Name&gt;! Das wird ihre Streitkräfte langsam schwächen und auch ihren Geist.", rewards = "Skrupellose ArmschienenBlutbesudelte StiefelDurchbohrer des Herzens des WaldesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13806] = {title = "Dämonendienst", objective = "Locke Okarr im Splitterholzposten will, dass Ihr 12 Satyrportale in Satyrnaar und Xavian schließt.", description = "Höret, <Klasse>, ich weiß, dass dieser Angriff auf den Splitterholzposten uns alle mitgenommen hat, aber falls wir die Satyrportale aus den Augen verlieren, steht uns nach dieser Krise eine noch größere bevor.\n\n<Locke starrt Euch ausdruckslos an.>\n\nIhr wisst nichts von den Portalen?\n\nIm Nordosten in der Region von Satyrnaar und Xavian unternehmen die Satyrn den Versuch, Dämonen zu beschwören, um ihre Zahl zu stärken.\n\nWir müssen diese Portale schließen, egal was sich uns dort auch in den Weg stellen mag.", progress = nil, completion = "Gute Arbeit, &lt;Volk&gt;!\n\nEine Sache weniger, um die wir uns sorgen müssen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13808] = {title = "In geheimer Mission", objective = "Kadrak will, dass Ihr das Geheimsignalpulver in die schwelende Kohlenpfanne gegenüber von Satyrnaar schüttet.\n\nBereitgestellter Gegenstand: \n", description = "Ich habe eine besondere Aufgabe. Für sie brauche ich einen gut ausgerüsteten, sachkundigen Helfer. Da ich niemanden sonst erübrigen kann, muss ich mich wohl mit Euch begnügen...\n\nDer Feind hat das Holzfällerlager des Kriegshymnenklans angegriffen und vom Rest unserer Streitkräfte abgeschnitten. Eine wichtige Diplomatin der Blutelfen, die auf dem Weg nach Orgrimmar war, wird dort gefangen gehalten.\n\nSie muss befreit werden.\n\nNehmt die Straße nach Nordosten und schüttet dieses Pulver in die schwelende Kohlenpfanne, um unseren Geheimagenten dorthin zu rufen. Tut, was immer er von Euch verlangt.\n\nWegtreten!", progress = nil, completion = "Es gibt für Euch hier alle Hände voll zu tun.\n\nHoffen wir, dass Ihr dieser Aufgabe gewachsen seid...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13809] = {title = "Bedrohung von oben", objective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", progress = "Habt Ihr den Stoßtrupp des Kults der Verdammten besiegt?", completion = "&lt;Name&gt;, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von NordendSiegel des Champions"}
MultiLanguageQuestData['de'][13810] = {title = "Die Schlacht zum Gegner tragen", objective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, <Name>. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", progress = nil, completion = "Ihr seid ein wahrer Champion, &lt;Name&gt;, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13811] = {title = "Unter Champions", objective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und von Euren Gegnern lernen. Champions aller Städte üben im Ring der Champions. Nehmt Eure Lanze, steigt auf irgendeins der angebundenen Reittiere, die Euch am Silberbundpavillon zur Verfügung stehen, und fordert sie heraus.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Horde stolz machen werdet, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13812] = {title = "Bedrohung von oben", objective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", progress = nil, completion = "&lt;Name&gt;, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nAbenteurerbedarf von NordendSiegel des Champions"}
MultiLanguageQuestData['de'][13813] = {title = "Die Schlacht zum Gegner tragen", objective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", progress = nil, completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13814] = {title = "Unter Champions", objective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt Euch irgendein zur Verfügung stehendes aus und fordert die Champions zu Übungskämpfen heraus.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, &lt;Name&gt;. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13815] = {title = "Stümpfe machen", objective = "Krokk will, dass Ihr mit der Splitterholzaxt die Eichen des Eschentals im Holzfällerlager des Kriegshymnenklans fällt.\n\nFalls Ihr das Geheimsignalpulver verliert, sprecht mit Kadrak im Splitterholzposten.", description = "Wie Euch bereits mitgeteilt wurde, sollen wir eine Diplomatin aus dem belagerten Holzfällerlager in Sicherheit bringen.\n\nSo wie es aussieht, ist das einfach unmöglich. Die Elfen halten tausend Pfeile auf die Ausgänge des Holzfällerlagers gerichtet.\n\nZunächst müssen wir ein Ablenkungsmanöver inszenieren – etwas, durch das sie ihren Blick eine Zeitlang vom Holzfällerlager abwenden.\n\nMeine Idee ist einfach. Nehmt diese Axt und fällt die Bäume, die sie in dieser Region pflegen.\n\nWenn Ihr damit fertig seid, verwendet das Signalpulver hier, um wieder mit mir zu sprechen.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;!\n\nIhr habt die Feinde demoralisiert und Ressourcen für die Horde gesammelt.\n\nHoffen wir, dass der Rest der Mission ebenso gut verläuft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13816] = {title = "Heroisch: Das Himmlische Planetarium", objective = "Ausgrabungsleiterin Loren im Archivum möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", progress = "Habt Ihr ihn gefunden, <Name>?", completion = "Verschlossen? Das war ja klar!\n\nIch werde Brann Bescheid sagen... vielleicht kann er etwas im Archivum entdecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13817] = {title = "Heroisch: Datenscheibe des Archivums", objective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13818] = {title = "Heroisch: Algalon", objective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", description = "Ihr habt es wirklich geschafft, <Name>. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", rewards = "Ihr bekommt:\n\nHeroischer Schlüssel des Himmlischen PlanetariumsGroßer Sack mit Schätzen von Ulduar"}
MultiLanguageQuestData['de'][13819] = {title = "Heroisch: Ende gut, alles gut", objective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", description = "Wir sollten uns jetzt besser beeilen, <Name>. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", progress = "Seid Ihr soweit, <Name>?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", rewards = "Tuch des HimmelsgeborenenSonnenglimmerumhangAuf Euch wartet eine dieser Belohnungen:\n\nBranns SiegelringSternenlichtkreis\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13820] = {title = "Die Gebrüder Sprengbolz", objective = "Sprecht mit Stumpi Sprengbolz am Argentumturnierplatz.", description = "Der Hochlord hat mich damit beauftragt, das Kolosseum so schnell wie möglich fertig zu stellen. Wir haben unsere Bauarbeiter an das Projekt gesetzt, aber wir mussten sehr schnell feststellen, dass wir Hilfe bei der Beschaffung von Materialien brauchten. Ich habe ein paar Goblins angeheuert, Stumpi Sprengbolz und seinen Bruder Stümpi.\n\nSie beaufsichtigen die Arbeiten am südöstlichen Ende des Turniergeländes. Sprecht mit Stumpi und findet heraus, ob er und sein Bruder noch weitere Hilfe dabei brauchen, das benötigte Baumaterial zu beschaffen.", progress = nil, completion = "Die Justiziarin hat Euch also geschickt? Gut, gut...\n\nWir können immer Hilfe brauchen bei der, äh, \"Anforderung\" von Materialien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13821] = {title = "Heroisch: Freyas Siegel", objective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, <Name>, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", progress = "Freyas Siegel, <Name>? Habt Ihr es?", completion = "Verdammt gute Arbeit, &lt;Name&gt;. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13822] = {title = "Heroisch: Hodirs Siegel", objective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", progress = "Konntet Ihr das Siegel bekommen, <Name>?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13823] = {title = "Heroisch: Thorims Siegel", objective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Thorim ist nicht er selbst, <Name>. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", progress = "Nun, <Name>? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, &lt;Name&gt;.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13824] = {title = "Heroisch: Mimirons Siegel", objective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", progress = "Konntet Ihr das Siegel an Euch bringen, <Name>?", completion = "Das muss man Euch wirklich lassen, &lt;Name&gt;. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13825] = {title = "Muschelette Surprise", objective = "Hey, ich erinnere mich an Euch! Seid Ihr nicht <Name>? Ihr habt mir doch mal geholfen, das ganze Muschelette zu machen!\n\nIch sag Euch was: Kommt näher und ich zeige Euch mein neustes Rezept - es ist einfach und köstlich!", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nMuschelette Magnifique\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMuschelette Magnifique"}
MultiLanguageQuestData['de'][13826] = {title = "Nat Pagle, Extremangler", objective = "Na, aber hallo, <Name>. Entweder lässt mein Gedächtnis mich langsam im Stich oder ich habe vergessen, Euch das hier zu geben, als wir uns das letzte Mal gesprochen haben...", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nNats Glücksangel"}
MultiLanguageQuestData['de'][13828] = {title = "Den Nahkampf beherrschen", objective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit 'Zustoßen' gegen ein Nahkampfziel an. Kehrt anschließend zu Arkanist Taelis beim Argentumturnierplatz zurück.", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", progress = nil, completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Übungsattrappen trainiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13829] = {title = "Den Nahkampf beherrschen", objective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit 'Zustoßen' auf ein Nahkampfziel an. Kehrt anschließend zu Magister Edien Sonnental beim Argentumturnierplatz zurück.", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf den Falkenschreiter der Sonnenhäscher, der gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", progress = nil, completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Übungsattrappen trainiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13830] = {title = "Der Geisterfisch", objective = "Marcia Balzer in Dalaran möchte, dass Ihr hinter das Geheimnis des Phantomgeisterfischs kommt.", description = "Jeder Angler in Nordend, der sein Geld wert ist, weiß über den Pygmäenschiffshalter Bescheid. Er ist nicht essbar, manchmal jedoch für Alchemisten nützlich.\n\nEs gibt jedoch einen Fisch, einen etwas verstohleneren, der sich zwischen den Schiffshaltern im Flussnabel im Sholazarbecken versteckt: der Phantomgeisterfisch. Außerhalb des Wassers werden sie zunehmend lichtdurchlässig, bis sie schließlich ganz verschwinden. Einige nehmen an, dass sie nach Sholazar zurückkehren, andere wiederum sind etwas... abergläubischer.\n\nIch möchte, dass Ihr diesen Fisch fangt und um jeden Preis hinter sein Geheimnis kommt!", progress = nil, completion = "Man wird also unsichtbar, wenn man ihn isst... was für eine seltsame Verteidigung dieser Fisch doch entwickelt hat.\n\nIch brauch ein Weilchen, um das zu verdauen - Wortspiel nicht beabsichtigt, &lt;Name&gt;; wirklich. Wieso kommt Ihr nicht morgen wieder?", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][13831] = {title = "Besorgniserregende Rezepte", objective = "Bringt die Notizen des Apothekers zu Tharnariun Baumwahrer in Lor'danel.", description = "Hier steht eine einfache, hastig zusammengezimmerte Werkbank eines Apothekers, die unter der Last gekritzelter Notizen und giftigem Gebräu fast zusammenbricht. Es sieht so aus, als hätten die Verlassenen auch Faulhufs Handwerk untersucht. Ihr schnappt Euch die Notiz, die am wichtigsten aussieht und bereitet Euch darauf vor, alles zu zerstören, bevor Ihr dem Baumwahrer von Eurer Entdeckung berichtet.", progress = "Was ist das? Habt Ihr noch etwas in der Höhle gefunden?", completion = "&lt;Tharnariun Baumwahrer durchblättert die Notizen, während Ihr Euren Bericht abliefert, sein Gesicht verfinstert sich sorgenvoll.&gt;\n\nDie Verlassenen interessieren sich für die Arbeit von Faulhuf? Mir dreht sich der Magen um, wenn ich daran denke, was sie mit seiner Verderbnis alles anrichten könnten. Ihr habt gut daran getan, die Arbeit zu zerstören, aber die Notizen beunruhigen mich sehr. Was haben die Verlassenen hier zu suchen? Arbeiten sie mit den Splitterspeertrollen im Norden zusammen? Sorgen über Sorgen, &lt;Klasse&gt;. Ich bin froh, dass Ihr hier seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13832] = {title = "Perle der Kanalisation", objective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr korrodierten Schmuck bringt.", description = "Schwer zu glauben, dass die meisten Leute, wenn sie zum Angeln in die Kanalisation von Dalaran gehen, nach Riesenratten und mutierten Fischen suchen. Besonders dann, wenn im Wasser Unmengen unbezahlbarer Juwelen zu finden sind - von gebrochenen Herzen, Dieben und achtlosen Trunkenbolden weggeworfen.\n\nDer Trick bei der Sache ist, Euren Haken am Boden entlang zu ziehen, und wenn Ihr etwas gefunden habt, beim Hochziehen nicht zu viel Kraft zu verwenden. Versucht es einmal, <Name>. Ich wäre dazu bereit, was auch immer Ihr findet gegen ein paar meiner eigenen Schmuckstücke einzutauschen.", progress = "Hattet Ihr Glück?", completion = "Also, das sieht aus, als könnte es wertvoll sein. Schwer zu sagen, bis es gesäubert und geschätzt wurde, aber ich bin noch immer dazu bereit, den Handel einzugehen, wenn Ihr es auch seid.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][13833] = {title = "Blut ist dicker", objective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 5 Blutzahnfrenzys bringt.", description = "Der Blutzahnfrenzy ist ein quirliger kleiner Fisch, der für ein Rezept zur Heilung von infizierten Wunden verwendet wird. Wir könnten ein paar von ihnen gebrauchen, wenn Ihr helfen wollt.\n\nWie der Name schon sagt, trinken sie gerne Blut. Die einzige mir bekannte Art und Weise, die kleinen Teufel zu fangen, ist, Blut ins Wasser zu schütten und dann darin zu angeln.\n\nBeschmiert Euch also mit Blut... Tötet dazu einfach eine der Bestien in der Boreanischen Tundra und springt anschließend ins Wasser. Ihr werdet im Nu den perfekten Köder haben.", progress = "Irgendwelches Glück mit den Blutzahnfrenzys gehabt? Vergesst nicht, was ich Euch über das Blut gesagt habe.", completion = "Ihr seid mutig, &lt;Name&gt;. Hoffe, dass Ihr beim Vorbereiten Eures Angelplatzes keine Gliedmaßen verloren habt. Wenn Ihr noch immer wild aufs Fischen seid, dann kommt morgen wieder und wir werden uns mehr darüber unterhalten.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][13834] = {title = "Gefährlich köstlich", objective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 10 Schreckensfische bringt.", description = "Die besten Angelplätze sind oft die gefährlichsten. Für diejenigen, die dreist genug sind, bietet sich Tausendwinter an - dort sind großzügige Fänge zu machen.\n\nGenau genommen ist es der einzige Ort, wo man den sagenhaften Schreckensfisch fangen kann - ein Fisch, tödlich und köstlich zugleich. Bringt mir ein paar und wir können weiterreden.", progress = "Seid auf der Hut, wenn Ihr hinter dem Schreckensfisch her seid.", completion = "Du meine Güte! Ihr habt Euch ein paar Schreckensfische gefangen. Das erinnert mich an die Zeit, als...\n\n&lt;Marcia erinnert sich an Geschichten von Abenteuer und Fischfang und wird sie so lange erzählen, wie Ihr nur zuhören wollt.&gt;", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][13835] = {title = "Den Schildbrecherangriff beherrschen", objective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \"Schildbrecher\" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.", description = "Ihr werdet lernen müssen, wie man die Verteidigung Eures Gegners durchbrechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf das angebundene Streitross der Quel'dorei gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", progress = "Habt Ihr die Übungen mit dem \"Schildbrecher\" abgeschlossen?", completion = "Prägt Euch Valis' Lektionen ein, &lt;Name&gt;. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13836] = {title = "Arm dran, Arm ab!", objective = "Olisarra die Gütige in Dalaran möchte, dass Ihr ihr den abgetrennten Arm bringt.", description = "Ich habe von einem tragischen Zwischenfall im Gefängnis von Dalaran gehört; ein besonders brutaler Insasse hat einer Wache einen Arm abgerissen und ihn ins Wasser geworfen. Die Leute von der \"Ersten Hilfe\"-Station haben versprochen, dass sie den Arm wieder annähen können, falls wir ihn zurückbringen.\n\nIhr angelt einfach lange genug im Wasser vor der Violetten Festung, und ich verwette meine Lieblingsangelrute darauf, dass der Arm auftaucht. Findet ihn und bringt ihn zu Olisarra der Gütigen hier in Dalaran. Sie wird wissen, was zu tun ist.", progress = "Seid gegrüßt. Habt Ihr etwas für mich?", completion = "Oh, seid gegrüßt, &lt;Name&gt;. Marcia hat gesagt, dass Ihr den fehlenden Arm des armen Kerls vorbeibringen würdet.\n\nAußerdem hat sie mir diese Tasche hier dagelassen, um sie Euch als Belohnung zu geben. Sie riecht scheußlich und ich kann es kaum erwarten, den Handel abzuschließen, falls Ihr nichts dagegen habt.", rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][13837] = {title = "Den Ansturmangriff beherrschen", objective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit 'Sturmangriff' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Avareth Flinkstoß beim Argentumturnierplatz zurück.", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos 'Sturmangriff'. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist und Euch ein paar grundlegende Strategien beibringen.", progress = "Beherrscht Ihr nun das \"Anstürmen\"?", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13838] = {title = "Den Schildbrecherangriff beherrschen", objective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher. Sprecht mit Valis Windhetzer und wendet die Fähigkeit 'Schildbrecher' gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.", description = "Ihr werdet lernen müssen, wie man durch die Verteidigung Eures Gegners brechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", progress = "Habt Ihr die Übungen mit dem \"Schildbrecher\" abgeschlossen?", completion = "Prägt Euch Valis' Lektionen ein, &lt;Name&gt;. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13839] = {title = "Den Ansturmangriff beherrschen", objective = "Nehmt Eure Lanze und steigt auf den angebundenen Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit 'Sturmangriff' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Amariel Sonnenschwur beim Argentumturnierplatz zurück.", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos 'Sturmangriff'. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.", progress = nil, completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13840] = {title = "REUSE", objective = "Beschafft Euch etwas Spezialhühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezialhühnerfutter gebt.", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHühnerei beschwören"}
MultiLanguageQuestData['de'][13841] = {title = "Entschuldigungsschreiben für Höllschrei", objective = "Draaka will, dass Ihr den Brief der Erklärung an Garrosh Höllschrei in Orgrimmar überbringt.\n\nBereitgestellter Gegenstand: \n", description = "Das könnte mein Ende bedeuten... Vielleicht sind meine Taten nicht so gut durchdacht gewesen, wie sie hätten sein sollen...\n\nDie gute Nachricht ist, dass wir einen Angriff zurückgeschlagen haben, der anderenfalls den Untergang des Splitterholzpostens zur Folge gehabt hätte. Lasst uns beten, dass Kommandant Höllschrei es genauso sieht.\n\nIch werde sicherlich nach Orgrimmar gerufen werden, um mich für meine Taten zu rechtfertigen.\n\nBitte, <Name>, eilt mir voraus und überreicht diesen Brief an Garrosh.\n\nTut was in Eurer Macht steht, um ihn mir gegenüber milde zu stimmen.", progress = nil, completion = "Narren!!\n\nDieses Weib Draaka hat sich von einem Dämonen beeinflussen lassen!\n\n&lt;Garrosh mustert Euch einen Augenblick lang.&gt;\n\nIch rieche seinen Einfluss auch an Euch, &lt;Klasse&gt;...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13842] = {title = "Der Tod steht ihm gut", objective = "Sprecht mit Durak in den Splitterholzminen.", description = "Die Dämonen wollen nichts weiter, als uns wieder von ihrer üblen Magie abhängig zu machen. Diese Abhängigkeit kann nur dazu führen, dass das gesamte Orcvolk zu Sklaven wird.\n\nIhr wünscht, dass Draaka ungeschoren davon kommt? Dann müsst Ihr den Handlanger der Dämonen finden, der sie beeinflusst hat und ihn vernichten!\n\nWenn Ihr mir nicht bald den Kopf dieses Wesens bringt, dann sorge ich dafür, dass sowohl Eurer wie auch Draakas Kopf aufgespießt werden!", progress = "Habt Ihr mir den Kopf des Feindes gebracht, <Volk>?", completion = "Grah... nun gut.\n\nIch werde das Kopfgeld wieder zurücknehmen, das ich auf Euren Kopf ausgesetzt hatte. Obwohl ich versucht bin, Euer Leben dennoch zu beenden, schon allein aus Prinzip.\n\nPasst nur gut auf, dass Ihr niemals wieder meinen Zorn weckt, &lt;Name&gt;. Jetzt geht mir aus den Augen...", rewards = "Bogen des ZornsUmhang des zurückgezogenen KopfgeldsAuf Euch wartet eine dieser Belohnungen:\n\nGarroshs Begnadigung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13843] = {title = "Das Konstruktionsset: Schrottbot", objective = "Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.Ihr durchsucht die Datenbanken der Prototypenkonsole und findet dabei ein Schema für ein Schrottbotkonstruktionsset. Mit Eurer Ingenieursfertigkeit könntet Ihr lernen, Konstruktionssets wie dieses selbst herzustellen.Ihr erlernt:\n\n", description = "Ihr durchsucht die Datenbanken der Prototypenkonsole und findet dabei ein Schema für ein Schrottbotkonstruktionsset. Mit Eurer Ingenieursfertigkeit könntet Ihr lernen, Konstruktionssets wie dieses selbst herzustellen.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nKonstruktionsset: Schrottbot\n\nDer folgende Zauber wird auf euch gewirkt:\n\nKonstruktionsset: Schrottbot"}
MultiLanguageQuestData['de'][13844] = {title = "Althalaxx plündern", objective = "Findet Narassins Foliant in den Ruinen von Althalaxx und tötet Teegan Holloway, den Kommandanten der Verlassenen.", description = "Bevor Ihr Euch gleich wieder in die Schlacht stürzt, möchte ich Euch über ein paar neue Entwicklungen in Kenntnis setzen, <Klasse>. Meine Späher berichten mir, dass der Turm von Althalaxx von den Verlassenen überrannt wird.\n\nVor dem Angriff war dieser trostlose Turm die Heimat eines fanatischen Zweigs des Schattenrats, der von dem gefallenen Hochgeborenen Athrikus Narassin angeführt wurde. Narassin ist längst tot, aber wir dürfen es nicht ignorieren, falls etwas von seinem Werk weiterbesteht. Beschafft Euch seine Forschung und tötet den Kommandant der Verlassenen, der die Ruinen plündert.", progress = "Narassin selbst bereitet uns keinen Ärger mehr, aber wenn sein Lebenswerk in die falschen Hände gerät, könnte sich das dunkle Wissen jahrzehntelanger Studien über unseren Köpfen zusammenbrauen. Habt Ihr etwas finden können?", completion = "Mal sehen, was wir hier haben... Bei Elune, seine Notizen allein schon sind in einem halben Dutzend Sprachen geschrieben. Und ist das Blut? Dieses Archiv lässt mich erschauern, aber immerhin sind wir in Sicherheit. Es wird dauern, bis wir alle Notizen entziffern können.\n\nOh, Eure Belohnung? Ja, hier. Eine nette Abwechslung, mal nicht mit untoten Dieben zu arbeiten. Jetzt zurück in den Kampf mit Euch.", rewards = "Narassins HandschuheGürtel der VerlassenenWildborkenstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13845] = {title = "Versiegelte Giftphiole", objective = "Bringt die versiegelte Giftphiole zu Alchemist Cinesra in die Kanalisation von Dalaran.", description = "Diese Giftphiole sieht besonders gefährlich aus. Womöglich könnte jemand in Dalaran daran interessiert sein.", progress = "Ist das, was ich denke, <Klasse>?", completion = "Ihr seid mutig, das hier mit Euch herumgetragen zu haben. Wenn nur ein Tropfen auf Eure Haut gekommen wäre, hättet Ihr auf schmerzlichste Weise den Tod gefunden.\n\nErlaubt mir, Euch dafür zu entlohnen... Gift von außergewöhnlicher Stärke kann ich immer gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13846] = {title = "Einen Beitrag leisten", objective = "Sprecht mit Knappe Artie, um einen Beitrag von 10 Gold an den Argentumkreuzzug zu leisten.", description = "Die besten der Champions kommen jeden Tag zur Kapelle, um der Argentumbeichtpatin zuzuhören.\n\nIhr solltet sehen, wie sehr sie von ihr inspiriert werden, <Name>. Sie ziehen nicht nur für den Argentumkreuzzug in den Kampf, sondern geben auch noch sehr viel Geld in den Klingenbeutel, wenn ich ihn herumtrage.\n\nWollt Ihr womöglich auch einen Beitrag leisten?", progress = "Wollt Ihr einen Beitrag leisten?", completion = "Habt Dank. Ich weiß einfach, dass es der Kreuzzug gut einsetzen wird!", rewards = nil}
MultiLanguageQuestData['de'][13847] = {title = "Vor den Toren des Feindes", objective = "Hauptmann Joseph Holley beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13848] = {title = "Überbringer schlechter Nachrichten", objective = "Kadrak will, dass Ihr mit Kommandant Grimmfang am Zoramstrand sprecht.\n\nBereitgestellter Gegenstand: \n", description = "Seit Beginn der Belagerung des Splitterholzpostens hat es keine Nachricht nach dort draußen geschafft. Inzwischen muss Kommandant Grimmfang sich Sorgen machen.\n\nIch entsende Euch zum Zoramstrand, um unseren Bericht abzuliefern. Er enthält keine guten Nachrichten, aber zumindest erfährt er dann die Fakten.\n\nSprecht mit Vhulgra, wenn Ihr bereit zum Aufbruch seid.", progress = nil, completion = "&lt;Kommandant Grimmfang runzelt die Stirn, als er den Bericht liest.&gt;\n\nDas sind in der Tat schlechte Nachrichten.\n\nMögen die Geister sie beschützen, bis wir unseren Weg bis zum Splitterholzposten erkämpft haben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13849] = {title = "Astranaar brennt!", objective = "Löscht 15 Feuer.", description = "<Klasse>, Astranaar steht in Flammen!\n\nSchnell, nehmt diesen Wassereimer und löscht das Feuer, bevor nichts mehr übrig ist!", progress = nil, completion = "Habt Dank!\n\nJetzt ist es an der Zeit, sich um die Horde zu kümmern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13850] = {title = "Gifttoleranz", objective = "Mor'vek im Krater von Un'Goro behauptet, dass wenn man 20-mal von dem Blut eines Gifthautravasauriers vergiftet wurde, auf einem reiten könnte, ohne zu sterben. Greift die Saurier an, um vielleicht vergiftet zu werden.", description = "Ihr wollt eine Gifthaut reiten? Dann hab' ich schlechte Neuigkeiten für Euch.\n\nDie Gifthautravasaurier, die bestehen aus nichts als Gift: giftiges Blut, giftiger Speichel, giftige Haut. Ihr steigt auf einen drauf und fallt nach ein paar Stunden tot runter.\n\nIhr müsstet zuerst gegen ihre Gifte resistent werden, bevor ich Euch einen verkaufe, und das dauert ganz schön lange... Ihr müsstet mit ihrem giftigem Blut bespritzt werden, wenn Ihr sie bekämpft. Und zwar sehr oft. Wenn Ihr wirklich daran interessiert seid: Die Gifthäute bevorzugen die nördliche Gegend der Marschen nordwestlich von hier.", progress = nil, completion = "Ihr habt es geschafft? Ihr habt es wirklich geschafft?!\n\nHo ho! Dickköpfig wie meine Frau seid Ihr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13851] = {title = "Vor den Toren des Feindes", objective = "Clara Torkelbräu beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir die Vorbereitungen für das Turnier treffen, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir würdige Verbündete sind.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13852] = {title = "Vor den Toren des Feindes", objective = "Klick Radspanner beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit hat gezeigt, dass wir den Anhängern des Argentumkreuzzugs ebenbürtig sind.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13853] = {title = "Das Feuer erwidern", objective = "Verwendet eine Schleuder von Astranaar, um 15 von Höllschreis Vandalen und ihre Wachwindreiter abzuschießen.", description = "Die meisten Feuer sind unter Kontrolle, aber wir müssen etwas gegen diese Windreiter unternehmen!\n\nSchnell, <Name>, Ihr müsst in eine unserer Glevenschleudern klettern und das Feuer erwidern!", progress = nil, completion = "Wir sind gerettet! Ihr habt genug abgeschossen. Den Rest sollten wir selbst erledigen können.\n\nIch kann Euch gar nicht genug danken, &lt;Name&gt;.", rewards = "Feuriger ReifThenysils WesteBeinschützer von AstranaarDer folgende Zauber wird auf euch gewirkt:\n\nReturn Fire: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13854] = {title = "Vor den Toren des Feindes", objective = "Ranii beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13855] = {title = "Vor den Toren des Feindes", objective = "Airae Sternensucher beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = "Habt Ihr an der Seite der Kreuzfahrer im Hof der Knochen gedient?", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass sie sich im Kampf gegen den Lichkönig auf uns verlassen können.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13856] = {title = "Vor den Toren des Feindes", objective = "Morah Worgschwester beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = "Habt Ihr an der Seite der Kreuzfahrer im Hof der Knochen gedient?", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger die besten auf Azeroth sind.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13857] = {title = "Vor den Toren des Feindes", objective = "Gahju beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir angesichts der Diener des Lichkönigs keine Angst kennen.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13858] = {title = "Vor den Toren des Feindes", objective = "Anka Klauenhuf beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache un 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir loyale Verbündete im Kampf gegen den Lichkönig sind.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13859] = {title = "Vor den Toren des Feindes", objective = "Aneera Thuron beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir bereit sind, jedem Gegner zu trotzen.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13860] = {title = "Vor den Toren des Feindes", objective = "Tierführer Dretch beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Der Argentumkreuzzug hat gesehen, wie entschlossen wir sind, und sie wissen, dass unsere Krieger die Sache zu Ende bringen werden.", rewards = "Ihr bekommt:\n\nSiegel des Recken"}
MultiLanguageQuestData['de'][13861] = {title = "Schlacht vor der Zitadelle", objective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13862] = {title = "Schlacht vor der Zitadelle", objective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13863] = {title = "Schlacht vor der Zitadelle", objective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Wir sind nie vor der Geißel zurückgewichen, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13864] = {title = "Schlacht vor der Zitadelle", objective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, <Name>, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", progress = nil, completion = "Wir haben die Geißel an allen Fronten bekämpft, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerfügung des ChampionsGeldbeutel des Champions\n\nIhr bekommt außerdem:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][13865] = {title = "Drei Anführer sind drei zu viel", objective = "Krokk will, dass Ihr Dorinar, Arminon, Endolar und 12 Eschentalspäher tötet.\n\nSprecht mit Kadrak im Splitterholzposten, falls Ihr das Geheimsignalpulver verliert.", description = "Hört gut zu, <Klasse>.\n\nIn dieser Region gibt es drei Kommandanten der Elfen, die ihre Bemühungen gezielt auf das Holzfällerlager richten. Sie zu töten, würde sicherlich Panik und ein Durcheinander anrichten. Hoffentlich ausreichend, sodass wir unsere Mission erfolgreich durchführen können.\n\nWo Ihr schon dabei seid: Die Vernichtung ihrer Späher kann unserer Sache nur dienlich sein.", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;.\n\nBei ihnen herrscht ein heilloses Durcheinander. Seht sie Euch an!", rewards = "Handschuhe der DrecksarbeitGürtel der geheimen ZeichenStiefel der VerwirrungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13866] = {title = "Zum Schutzwall!", objective = "Sprecht mit Kulg Blutspritzer an der Grenze zwischen Eschental und Azshara, um zum Schutzwall von Mor'shan gebracht zu werden. Meldet Euch bei Kadrak, wenn Ihr dort eintrefft.", description = "Diese Wälder mögen ruhig sein, aber unsere Feinde lauern hinter jedem Baum. Ich habe schon so manchen Orc mit Pfeilen in seinem Rücken entdeckt und die Waffe noch nicht gezückt.\n\nHier ist es tückisch hinter den feindlichen Linien, aber wir könnten starke Arme und kluge Köpfe dort unten im Schutzwall von Mor'shan gebrauchen. Kadrak bereitet eine Offensive von dort aus vor – er zieht Taten den Worten vor. Ihr werdet Euch gut mit ihm verstehen.\n\nSprecht mich wieder an, wenn Ihr bereit seid, und ich fliege Euch dorthin.", progress = nil, completion = "Ihr kommt genau zur rechten Zeit, &lt;Klasse&gt;. Der alte Kulg schleicht schon zu lange durch diese Wälder. Er wird übervorsichtig und fürchtet sich vor jedem Schatten. Wir werden diesen Wald nicht länger fürchten – die Zeit ist gekommen, das Eschental ein für alle Mal zu unterwerfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13867] = {title = "Die Eindämmung der Furbolgbedrohung", objective = "Tötet 15 Furbolgs im Lager der Distelfelle in Eschental.", description = "Direkt im Norden von Astranaar sind die Distelfellfurbolgs. Meine Späher berichten, dass ihre Anzahl in den letzten Monaten stark zugenommen hat. Wenn sie zu schnell anwächst, fassen sie vielleicht den Mut, Astranaar direkt anzugreifen!\n\nBegebt Euch ins Lager der Distelfelle und tötet so viele von ihnen, wie Ihr könnt.\n\nIch werde hier in Astranaar bleiben und Euren Bericht erwarten. Elune sei mit Euch, <Klasse>.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;.\n\nWir stehen unter der ständigen Bedrohung durch die Furbolgs. Hoffentlich wird sie das etwas länger von uns fernhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13868] = {title = "Schlechter Einfluss?", objective = "Überbringt den TrollglücksbringerRaene Wolfsläufer in Astranaar im Eschental.", description = "Als Ihr die Habseligkeiten der toten Furbolgs durchsucht, die vor Euch liegen, fällt ein kleiner, offensichtlich von Trollen erschaffener Glücksbringer auf den Boden.\n\nAls Ihr den Glücksbringer berührt, bekommt Ihr umgehend das Gefühl, dass es im Wald nicht mit rechten Dingen zugeht. Ein Gefühl der Unruhe und Verderbtheit durchdringt das Objekt.\n\nIhr hüllt es in ein Tuch, verstaut es in Eurem Gepäck und beschließt, es Raene Wolfsläufer zu zeigen, wenn Ihr das nächste Mal in Astranaar seid.", progress = "Was beunruhigt Euch, <Klasse>?", completion = "Ein Trollglücksbringer? Was fangen die Furbolgs mit so einem Ding an?\n\nIhr habt recht. Ein Gefühl von Verderbtheit umgibt dieses Artefakt... Sogar ich kann das spüren.\n\nEs gibt hier jemanden, der in der Lage sein müsste, zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13869] = {title = "Bergt die Überreste", objective = "Sammelt 10 Stück Holz des Kriegshymnenklans.", description = "Die Satyrn haben den Bäumen fürchterlichen Schaden zugefügt, aber das ist nichts im Vergleich zu dem Gemetzel, das die Orcs veranstaltet haben!\n\n<Das Urtum zittert sichtbar vor Wut. Seine Blätter fallen rings um Euch zu Boden.>\n\n<Volk>, begebt Euch die Straße entlang zum Holzfällerlager und holt die Überreste dieser Bäume, Treants und Urtume, welche die Horde in ihren besten Jahren gefällt hat.", progress = "Habt Ihr die Überreste, <Volk>?", completion = "Ich lebe schon lange friedlich in diesem Wald, aber wenn ich sehe, was diese Orcs hier veranstalten, dann würde ich sie am liebsten in Grund und Boden stampfen!\n\nIch werde diesem Holz jetzt seine letzte Ruhe geben. Habt Dank für Eure Hilfe, &lt;Name&gt;. Ich werde es Euch nie vergessen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13870] = {title = "Besser geht's nicht", objective = "Krokk will, dass Ihr das Holzfällerlager des Kriegshymnenklans betretet und mit Vorarbeiter Gorthak sprecht.", description = "Nun gut, <Klasse>, besser geht es nicht.\n\nDie Elfen sind dabei, sich von Euren letzten Taten zu erholen. Das ist der günstigste Augenblick, um in das Holzfällerlager vorzustoßen!\n\nBegebt Euch dorthin und sprecht mit Vorarbeiter Gorthak. Er wird Euch erklären, wie Ihr die Diplomatin am sichersten begleitet.\n\nViel Glück!", progress = nil, completion = "&lt;Gorthak seufzt enttäuscht.&gt;\n\nWenn Ihr doch nur vor einer Stunde eingetroffen wäret...\n\nDie Diplomatin wurde von einem Auftragsmörder der Elfen tödlich verwundet.\n\nWie der Feind in der Lage war, das Lager unentdeckt zu infiltrieren bleibt uns ein Rätsel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13871] = {title = "Wachen!", objective = "Vorarbeiter Gorthak will, dass Ihr ihm den Kopf eines Assassinen der Kaldorei bringt.", description = "Es ist nicht so, als ob ich nicht schon genug um die Ohren hätte!\n\nDiesen Ort am Laufen zu halten ist schon schwer genug, ohne dass die Elfen und Draenei uns ständig belästigen.\n\nJetzt schleicht obendrein noch ein Auftragsmörder im Lager umher, der eine wichtige Diplomatin getötet hat... Während meiner Wache!\n\nWer auch immer es war, er kann noch nicht weit sein, <Klasse>. Durchsucht das Lager, bis Ihr ihn findet und dann rächt die Diplomatin!\n\nZumindest kann ich dann den Kopf des Mörders in Händen halten, wenn ich mich vor Höllschrei rechtfertigen muss.", progress = "Mich interessiert nur eins, <Volk>.\n\nIst der Auftragsmörder tot?", completion = "Gute Arbeit, &lt;Klasse&gt;.\n\nEine letzte Bitte – Es ist vermutlich das Beste, wenn keiner meiner Arbeiter erfährt, dass dieser Mörder jemals existiert hat.", rewards = "DetektivrundschildGeplünderter KaldoreigürtelSicherheitsarmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13872] = {title = "Die Weisheit der Worgen", objective = "Bringt den Trollglücksbringer zu Hephaestus Pilger in Astranaar im Eschental.", description = "Der Mann, der mir direkt gegenübersteht, ist als Hephaestus Pilger bekannt. Er ist einer der Worgen.\n\nEr und seine Schwester kamen vor nicht allzu langer Zeit nach Astranaar, als sie einen neuen Ort zum Leben suchten. Soweit ich das sagen kann, ist er daran interessiert, dem Irdenen Ring bei der Katastrophe zu helfen. Seine Schwester ist sogar noch mächtiger. Sie ist nach Osten gereist, um dem Schamanen zu helfen, sich um den Vulkan zu kümmern.\n\nVielleicht kann er helfen. Bringt den Glücksbringer zu ihm und hört, was er darüber denkt.", progress = "<Der Worgen sieht Euch ausdruckslos an, als Ihr Euch nähert.>", completion = "&lt;Er sieht auf die Holzschnitzerei in Eurer ausgestreckten Hand. Der Worgen greift danach und nimmt sie an sich.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13873] = {title = "Sheelahs Vermächtnis", objective = "Wächter Menerin will, dass Ihr Sheelahs versiegelten Brief an Wächter Gurtar übergebt.\n\nBereitgestellter Gegenstand: \n", description = "Ich... Ich kann nicht glauben, dass sie von uns gegangen ist. Es ist alles so schnell gegangen...\n\nIch muss Euch wohl danken, dass Ihr meine Herrin gerächt habt. Dafür habt meinen Dank und den von Silbermond.\n\nIn Ihrer Weisheit hat meine Lady Ihr Ende vorausgesehen. Sie hat ein Sendschreiben vorbereitet für den Fall, dass ihr irgendetwas zustoßen würde.\n\nWir sollten uns einem Gefolge aus Orgrimmar anschließen, am Wegekreuz nördlich von hier. Bitte, <Volk>, trefft sie an unserer statt und sorgt dafür, dass die Nachricht übergeben wird.", progress = nil, completion = "&lt;Gurtar hört Euch zu, als Ihr ihn über Sheelahs Tod unterrichtet.&gt;\n\nIch werde dies Höllschrei persönlich übergeben, &lt;Volk&gt;.\n\nIn der Zwischenzeit könntet Ihr etwas für mich tun...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13874] = {title = "Im Bann der Glücksbringer", objective = "Sammelt 8 Trollglücksbringer.", description = "Die Furbolgs begehren etwas, das ihnen nicht gehört.\n\n<Hephaestus dreht den Glücksbringer in seiner Hand und lässt ihn dann fallen.>\n\nDiese Schnitzerei besitzt die Eigenschaft, langsam jene zu verderben, die keine Trolle sind. Soweit ich sehen kann, haben die Furbolgs das schon einmal gemacht. Manche lernen's nie.\n\nZweifellos horten sie die meisten Glücksbringer in der Höhle der Distelfelle nördlich ihres Dorfes.", progress = "Glaubt Ihr, dass Ihr schon alle Trollglücksbringer aus der Höhle der Distelfelle gesammelt habt?\n\nFalls auch nur einer verbleibt, wird der Stamm der Distelfelle weiterhin von ihm beeinflusst werden und schließlich diesen Ort angreifen.", completion = "&lt;Hephaestus nickt langsam, während er Euch direkt in die Augen blickt.&gt;\n\nIhr habt vermutlich die Distelfelle vor sich selbst beschützt, zumindest vorerst. Jedenfalls so lang sie nun davon absehen können, mächtige Objekte zu stehlen, die ihnen nicht gehören.\n\nSoweit ich das sehe, haben die Nachtelfen Probleme mit dem anderen Furbolgstamm im Süden. Darüber möchte Raene mit Euch sprechen.\n\nWie dem auch sei, es gibt dringlichere Angelegenheiten, bei denen ich Euch um Eure Unterstützung bitten möchte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13875] = {title = "Gurtars Bitte", objective = "Wächter Gurtar will, dass Ihr den Blutkelchzopf an Draaka im Splitterholzposten übergebt.", description = "Ich hätte noch eine persönliche Bitte an Euch, <Klasse>.\n\nEs ist viele Monde her, seitdem ich meine Liebste gesehen habe, Draaka. Es werden noch viele weitere verstreichen, bis wir uns wiedersehen können. Ich fürchte, dass nach so langer Zeit ihre Liebe für mich schwinden wird.\n\nDieser Zopf hat für uns beide eine besondere Bedeutung, und auch der dornige Blutkelch, die Blume, die in dieser Region wächst.\n\nIch bitte Euch, diese Blumen zu pflücken und sie mit dieser Schnur zu binden. Dann übergebt Draaka das Geschenk in meinem Namen.", progress = "Hallo, <Name>.", completion = "&lt;Draaka erfasst sofort die Bedeutung dieses Geschenks und beginnt zu weinen.&gt;\n\nOh, &lt;Name&gt;. Habt Dank für dieses Geschenk! Es bedeutet mir mehr, als Ihr ahnen könnt.\n\nEr hat nicht vergessen...", rewards = "BlutkelchschuheTreue TreterHandschuhe der unvergessenen SchwüreIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13876] = {title = "Zu weit entfernt", objective = "Gelangt in den Besitz von Blutklaues Sammlung.", description = "Ja, ich spreche Eure Sprache, <Volk>.\n\nWir Furbolgs waren schon einmal Opfer dieser Form von Verderbnis. Vor nicht allzu langer Zeit stahl unser Anführer den Götzen von Remulos. Das von Dämonen verderbte Ding verhexte den gesamten Stamm und unsere Erlösung wurde nur notdürftig durch einen Druiden herbeigeführt, der Broll Bärenfell heißt.\n\nAber dieses Mal haben wir nicht gestohlen. Die Trolle von Zoram'gar gaben uns die Glücksbringer als ein Zeichen der Freundschaft. Eine tödliche Freundschaft, wie es scheint.\n\nUnser Häuptling Dal Blutklaue ist nicht mehr zurechnungsfähig. Betretet die Höhle und kehrt mit seinen Glücksbringern zurück.", progress = "Nun? Die Zukunft der Distelfelle lastet auf Euren Schultern, <Volk>.", completion = "Es wurde getan, was getan werden musste. Da Dal unser Anführer ist, hat seine Erkrankung durch die Trollglücksbringer uns zerstört.\n\nFür die Gesundheit und die Würde unseres Stammes war es gut, dass Ihr es wart, Fremdling. Auf diese Weise wird es keinen Bürgerkrieg unter uns geben und wir finden leicht einen neuen Anführer... hoffentlich jemanden, der nicht so schnell Fremden vertraut. Vielleicht habe auch ich mich dessen schuldig gemacht?\n\nHier, erlaubt mir unsere Schuld zu begleichen, bevor sich unsere Wege für immer trennen.", rewards = "Umhang von Zoram'garAuf Euch wartet eine dieser Belohnungen:\n\nDistelring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13877] = {title = "Der Tanz auf dem Vulkan", objective = "Sprecht mit Sabina Pilger am südlichen Rand des Lavastroms am Donnergipfel in Eschental.", description = "<Der Worgen starrt Euch durchdringend an, bevor er seine Bitte vorträgt.>\n\nDer Vulkan droht, ganz Eschental zu verschlingen, wenn wir nicht rasch handeln. Lasst Euch gesagt sein, dass dies kein natürlicher Ausbruch war.\n\nMeine Schwester Sabina ist mächtig. Sie ist nach Osten zur Grenze des Lavastroms am Donnergipfel direkt nördlich der Straße gegangen. Dort erbittet sie die Hilfe anderer Elemente gegen den Feuerlord, der diese Zerstörung verursacht hat.\n\n<Name>, begebt Euch zu ihr und helft ihr, so gut Ihr könnt.", progress = nil, completion = "Mein Bruder muss Euch gesandt haben. Er hätte das nicht getan, wenn Ihr nicht in der Lage wäret, etwas zu tun, was getan werden muss.\n\nIch hoffe um unser aller Willen, dass er recht hat.\n\nDie Elementare hier sind nun meine Verbündeten. Ihr müsst tun, was sie Euch sagen, wenn wir die Zerstörung vom Rest des Eschentals verhindern wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13878] = {title = "Durch Feuer und Flamme", objective = "Brecht die Ketten auf und befreit die Wölfe aus den brennenden Ställen.", description = "Helft mir, <Klasse>! Schweinemenschen kommen und zünden Ställe an – Feuer! Feuer!\n\n<Dorak jammert etwas Unverständliches, bevor es Euch gelingt, ihn zu beruhigen.>\n\nWölfe drinnen noch angekettet. Jemand muss die kleinen Wölfe retten!", progress = "Heiß!", completion = "Ihr habt die Wölfe gerettet! So mutig! Eines Tages bekommt Ihr vielleicht einen Wolf wie diesen als Reittier.\n\n&lt;Dorak sieht auf die brennenden Ställe, dann zum nahegelegenen Fluss.&gt;\n\nWas soll ich nun tun?", rewards = "Flammenabweisendes LakenWolfspflegerstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13879] = {title = "Donnergipfel", objective = "Broyk will, dass Ihr Stikwad am Donnergipfel findet.", description = "Seid gegrüßt, <Klasse>!\n\nIch gratuliere zu Eurem siegreichen Angriff auf Astranaar. Die Elfen werden diese Schmach nicht so schnell vergessen, die sie durch Eure Hand erlitten haben.\n\nAber Ihr müsst wissen, dass die Elfen nicht das einzige Hindernis sind, dass der Eroberung des Eschentals durch die Horde im Wege steht...\n\nIm Osten benötigt ein Schamane des Irdenen Rings Hilfe bei einer anderen Krise. Ihr findet ihn in der Nähe des Fußes des Vulkans Donnergipfel.", progress = nil, completion = "&lt;Der Goblin starrt Euch an und blinzelt einige Male bevor er spricht.&gt;\n\nDie Geister haben mir geflüstert, dass diese Hilfe bald eintrifft.\n\nVerzeiht meine Überraschung, aber ich hatte darauf gehofft, dass die Geister jemanden schicken der etwas... heldenhafter ist.\n\nDie Elementare sind meine Vertrauten. Hört sie an und leistet ihren Anordnungen Folge. Falls wir scheitern, wird vom Eschental nichts mehr übrigbleiben, für das es sich zu kämpfen lohnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13880] = {title = "Heiße Lava", objective = "Verwendet das Geschenk der Erde, um 8 Lavafelsspalten zu füllen.", description = "<Der riesenhafte Erdelementar starrt auf Euch herab.>\n\nDer Lavastrom muss aufgehalten werden, wenn wir überleben wollen. Ich werde Euch einen Teil meiner Kraft übertragen. Verwendet sie, um die Lavafelsspalten zu füllen!", progress = "Fertig?", completion = "Gut gemacht, &lt;Volk&gt;. Lord Magmathars Feuer ist nun gefangen und wieder fest in der Erde verschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13881] = {title = "Aufgezehrt", objective = "Tötet 6 aufgezehrte Distelbären und untersucht den See, von dem die Distelbären trinken.", description = "Meine größte Sorge gilt den Distelbärfamilien, die diese Wälder behausen. Südlich von hier, hinter dem Bärenschrein, ist eine gesamte Generation der Bären erkrankt. Schrecklich erkrankt.\n\n<Name>, ich weiß nicht, woran sie leiden, aber es scheint sie von innen aufzuzehren. Der Gedanke, dass eine gesamte Generation nicht mehr zu retten ist, ist entsetzlich, aber wir müssen sie töten, damit ihre Körper der Erde zurückgegeben werden.\n\nUnd was noch wichtiger ist, wir müssen den Ursprung der Krankheit finden. Untersucht den See, aus dem die Bären trinken.", progress = nil, completion = "&lt;Kathrena schaudert bei der Beschreibung der in Mitleidenschaft gezogenen Tiere und dem furchtbaren Gerät auf dem Boden des Sees.&gt;\n\n&lt;Name&gt;, das ist grauenvoll. Was ist das für ein Ding und wo kommt es her? Etwas zehrt diese Tiere auf, sowohl körperlich als auch spirituell. Ich hatte damit gerechnet, dass die Satyrn oder eine Krankheit die Schuld trügen, aber es scheint einen doch eher... unnatürlichen Grund dafür zu geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13882] = {title = "Die Samenkörner des Lebens", objective = "Sammelt die Saat der Erde, die Saat des Meeres und die Saat des Himmels.", description = "Etwas versucht, das Leben aus Dunkelküste aufzuzehren! Ich werde mich umhören, ob jemand etwas über - das Ding - weiß, das Ihr gefunden habt. In der Zwischenzeit müssen wir uns aber auch um die Wildtiere kümmern, damit ihnen nicht noch weiteres Leid geschieht.\n\nKönnt Ihr ein paar Materialien für mich besorgen? Ich brauche Leben in allen möglichen Formen. Sprecht mit Onu hier am Hain, um die Saat der Erde zu erhalten. Fangt einen Dunkelküstenirrwisch, um die Saat des Himmels zu erhalten, und besorgt die Saat des Meeres von den Seemuschelschalen an der Küste westlich von hier.", progress = "Leben ist mächtig, <Name>. Konzentriert in seiner reinsten Form kann es alles überstehen. Eines Tages wird auch Dunkelküste von den Wunden genesen. Habt Ihr alles gefunden, was ich brauche?", completion = "Perfekt - das ist alles, was ich brauche. Hattet Ihr Spaß beim Irrwischfangen? Als kleines Mädchen habe ich immer Irrwische in Eschental herumgejagt.\n\n&lt;Kathrena schwelgt in Erinnerungen. Plötzlich verdunkelt sich ihr Blick.&gt;\n\nIch befürchte, ich weiß, womit wir es hier zu tun haben.", rewards = "IrrwischjägerkordelPflanzerhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13883] = {title = "Ein Wrack neben dem anderen", objective = "Bergt 10 Teile versunkenes Altmetall.", description = "Stümperhaftes Handwerk! Es gibt keine andere Erklärung...\n\nDiese Schiffe müssen in großer Eile zusammengeflickt worden sein. Ganze Panzerungsplatten fallen ab, ohne jemals einen Treffer abgefangen zu haben!\n\nIch zeige ihnen, wie man es richtig macht. Aber zuerst müsst Ihr für mich die Teile vom Meeresboden bergen.\n\nKehrt mit den Teilen zu mir zurück und ich erledige den Rest.", progress = "Habt Ihr die Panzerungsplatten geborgen, <Volk>?", completion = "Gute Arbeit, &lt;Volk&gt;.\n\nIch werde ihnen zeigen, wie ein gepanzertes Schiff gebaut werden sollte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13884] = {title = "Feuerlöscher", objective = "Tötet 10 Lavawüter. Falls Ihr einen weiteren gefrierenden Woger benötigt, sprecht mit Arctanus.", description = "Wir müssen uns zunächst um Lord Magmathars Lakaien kümmern, wenn wir dieses Gebiet zurückerobern wollen und der hitzigen Zerstörung des Waldes Einhalt gebieten wollen.\n\nDie Lavawüter auf dem Strom im Norden werden durch ihr Element gestärkt. Ich fürchte, wenn Ihr auf Euch gestellt seid, habt Ihr keine Chance gegen sie.\n\nWenn Ihr bereit seid, sprecht mich wieder an und ich werde einen meiner Helfer für Euch beschwören.", progress = nil, completion = "Ihr habt Euch auf dem Schlachtfeld wacker geschlagen. Dennoch hat Lord Magmathar Euch leider bemerkt und die Zerstörung, die Ihr über seine Lakaien gebracht habt.\n\nIhr werdet Euch um ihn kümmern müssen, oder er verbrennt Euch bei lebendigem Leibe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13885] = {title = "Verteidigung Dunkelküstes", objective = "Sprecht mit Orseus vor dem Hain der Uralten und besteigt einen Hippogryphen. Beschützt aus der Luft 8 Weißschwanzhirsche und -rehe, 8 ergraute Distelbären und 8 Mondpirschermatriarchinnen oder Mondpirscherpatriarchen vor der Verzehrung.", description = "Nun da wir wissen, dass unsere Vorsorgemaßnahmen funktionieren, sollten wir so viel Land abdecken wie möglich.\n\nWir können einen der Hippogryphen benutzen, aber alleine kann ich nichts ausrichten. Sprecht mit meinem Freund Orseus beim Flugmeister vor dem Hain. Sagt ihm Bescheid, wenn Ihr soweit seid. Ich werde Euch dort treffen. Wir werden Dunkelküste von der Luft aus abdecken und so viele Tiere wie möglich schützen!", progress = nil, completion = "Die Tiere sind also in Sicherheit. Ich danke Euch, vielen Dank!\n\nJetzt müssen wir unsere Aufmerksamkeit dem Ursprung der Verzehrung widmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13886] = {title = "Vortex", objective = "Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.", description = "Es ist an der Zeit, <Name>. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.\n\nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.", progress = nil, completion = "Es ist vollbracht. Die Kräfte des Feuers sind beruhigt und die vier Elemente befinden sich wieder in Harmonie.\n\nIhr habt den Rest des Eschentals mit Eurem Mut und Euren heldenhaften Taten gerettet, &lt;Name&gt;. Wir schulden Euch unseren ewigen Dank.", rewards = "Handschuhe des UnterdrückersGürtel des AusgleichsAuf Euch wartet eine dieser Belohnungen:\n\nBlüte des Irdenen Rings\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13887] = {title = "Gifthauteier", objective = "Bringt Mor'vek im südöstlichen Teil der Marschen 4 Eier von Gifthautravasauriern.", description = "Jetzt, da Ihr gegen das Sauriergift immun geworden seid, könnt Ihr mit den Tieren und ihren Eiern sicher umgehen. Gifthäute sind ziemlich bösartig und müssen vom Moment des Schlüpfens an trainiert werden.\n\nWenn Ihr einen reiten wollt, dann werdet Ihr ein ungeschlüpftes Ei benötigen. In den gesamten Marschen verteilt gibt es einige Ravasauriernester. Sucht nach Eiern mit helleren Schalen - das sind diejenigen, aus denen später Gifthäute schlüpfen werden.\n\nWenn Ihr mir einige Eier bringt, werde ich Euch gestatten, eins zu behalten und unter meiner Aufsicht aufzuziehen.", progress = "Habt Ihr die Eier gefunden?", completion = "Gute Arbeit. Wirklich, ich bin erstaunt, dass Ihr so viele gefunden habt. Ihre Zahl scheint in jedem Gelege zurückgegangen zu sein.\n\nIch werde Euch einen der frisch geschlüpften Gifthäute aufziehen lassen. Er wird sich vermutlich nicht zieren, Euch wissen zu lassen, was er braucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13888] = {title = "Vortex", objective = "Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.", description = "Es ist an der Zeit, <Name>. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.\n\nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.", progress = nil, completion = "Ihr habt es geschafft! Die Geister haben sich doch nicht getäuscht!\n\nDie Kräfte des Feuers sind beruhigt und die vier Elemente befinden sich wieder in Harmonie.\n\nDem Rest des Eschentals bleibt dieses Schicksal der Flammen erspart. Der Irdene Ring ist Euch zu ewigem Dank verpflichtet.", rewards = "Handschuhe des UnterdrückersGürtel des AusgleichsAuf Euch wartet eine dieser Belohnungen:\n\nBlüte des Irdenen Rings\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13889] = {title = "Sooooo hungrig", objective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", progress = nil, completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13890] = {title = "Schürt das Feuer", objective = "Kommandant Grimmfang in Zoram'gar will, dass Ihr das Öl einer Nebelpeitscherhydra ins Feuer des Leuchtturms gießt.", description = "Dies ist keine leichte Aufgabe, <Volk>!\n\nEs treffen weitere Schiffe ein und ohne den Leuchtturm werden sie sich verirren – oder noch Schlimmeres! Hiermit wird Euch die Aufgabe übertragen, sein Feuer am Brennen zu erhalten.\n\nSammelt den Tran der Hydras in diesen Gewässern und bringt ihn dann zu dieser Schmiede hier, damit daraus Öl hergestellt wird.\n\nWerft Ihr dieses Öl in das Feuer des Leuchtturms, wird uns das die Zeit verschaffen, die wir benötigen.", progress = nil, completion = "Gute Arbeit, &lt;Volk&gt;!\n\nKeine Schiffe werden mehr auf Grund laufen - dank Euch.", rewards = "Ölige ArmschienenHell erleuchtete StiefelNebelpeitscherarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13891] = {title = "Der Verschlinger Dunkelküstes", objective = "Verwendet den Lebensbringerschössling am Ufer des flachen Sees südlich des Hain der Uralten und zerstört das verschlingende Artefakt und seinen Bewacher.", description = "Jetzt, da die Kreaturen Dunkelküstes in Sicherheit sind, sollten wir unsere Aufmerksamkeit dem Artefakt widmen, das Ihr im See gefunden habt. Ich glaube, es handelt sich dabei um die Arbeit der Diener der Alten Götter. Wir werden diese Feinde mit den lebensspendenden Energien zerstören, die Dunkelküste besitzt! Bringt den Lebensbringerschössling zum Ufer des Sees südlich von hier. Bewegt ihn über die Wasser des Sees; das sollte das alte Artefakt ausschalten.\n\nSeid vorsichtig, <Name>. Das Artefakt wird sicherlich von irgendetwas bewacht.", progress = "Ich wage es gar nicht, zu fragen, <Name>, konntet Ihr das Artefakt zerstören? Was ist mit dem Bewacher?", completion = "Bei Elune, wie seht Ihr denn aus? Das muss ein heftiger Kampf gewesen sein! Ihr seid voller... nun, es sieht ein wenig wie Fischsuppe aus...\n\nWenn ein einfacher Diener solch Leid hier in Dunkelküste auslösen kann, möchte ich mir gar nicht erst überlegen, welche Katastrophen einer der Altvorderen anrichten könnte.\n\nWenigstens sind die Tiere vorerst in Sicherheit. Ich werde den von Euch geschaffenen Schössling pflanzen, um dem zerstörten Land bei der Regeneration zu helfen. Ich danke Euch, &lt;Name&gt;! Ich würde Euch ja umarmen, aber, ihr wisst ja... Fischsuppe.", rewards = "Uralte ManschettenUralte HandschützerUnbestechlicher SchalIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13892] = {title = "Keine Spuren hinterlassen", objective = "Schleicht in die Meistergleve und beobachtet mit Hilfe der Pantherfigur die Schattenhammerkultisten.", description = "Südwestlich von hier liegt der Leichnam eines Wesens, das in irgendeiner Verbindung zu den Alten Göttern steht, die die Schattenhammerkultisten verehren.\n\nEs wurde vor unserer Zeit besiegt - wenn nicht von den Titanen selbst, so sicherlich von einer ihrer Schöpfungen.\n\nIn der letzten Zeit haben wir zunehmend Aktivitäten der Kultisten beobachtet und das kann nur bedeuten, dass uns etwas Schreckliches bevorsteht.\n\nWir müssen herausfinden, was sie dort vorhaben, und warum. Nehmt diese Figur. Sie wird Euch dabei helfen, bei Euren Untersuchungen unbemerkt zu bleiben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13893] = {title = "Soggoth und Kronn", objective = "Kehrt mit den neuen Informationen zu Larien beim Hain der Uralten zurück.", description = "Die Meistergleve ist der Ort einer uralten Schlacht, <Name>. Die Titanen haben zwanzig ihrer Steinriesen gegen Soggoth ausgesandt.\n\nVon diesen zwanzig Riesen hat nur einer überlebt.\n\nAuf den Tafeln steht geschrieben, dass Kronn, der größte aller Steinriesen, sich von Soggoths Ranken hat einfangen lassen - nur lange genug, um dem Schädel der Kreatur näher zu kommen - nahe genug für sein mächtiges Schwert.\n\nEs ist gut, dass er tot ist... wir haben nicht wirklich zwanzig weitere Steinriesen zur Verfügung, um ihn erneut aufzuhalten.", progress = nil, completion = "Die Geschichte des Zwerges ist besorgniserregend... doch sehr aufschlussreich. Es scheint, als hätten wir mehr als eine Möglichkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13895] = {title = "Die schlummernden Uralten", objective = "Findet Aros nordöstlich vom Hain der Uralten in Dunkelküste.", description = "Wir haben keine zwanzig Steinriesen, um uns dem Feind anzunehmen, aber wir Riesen aus uraltem Holz sind so stark wie jeder Fels.\n\nSeht Euch um, <Volk>. Mein Volk schläft... und doch werden sie dem Horn des Bewahrers folgen, wenn es von ihnen verlangt wird.\n\nIhr könnt Aros, den Bewahrer des Hains, jenseits der Brücke nordöstlich von hier finden.\n\nBerichtet ihm vom Ernst der Lage.", progress = nil, completion = "Aros Körper ist leblos, doch er ist noch warm. Vielleicht sind seine Mörder in der Nähe.", rewards = nil}
MultiLanguageQuestData['de'][13896] = {title = "Ausgegrabenes Wissen", objective = "Sprecht mit Archäologe Groff bei Wirrbarts Ausgrabung.", description = "Hört gut zu, <Name>. Wir müssen mehr über unseren Feind in Erfahrung bringen.\n\nSüdwestlich von hier, hinter der Meistergleve, sind ein paar Ausgrabungsleiter der Zwerge, die die Ruinen in der Nähe untersuchen.\n\nVielleicht haben sie Wissen zu Tage gebracht, das uns nützlich sein könnte.", progress = nil, completion = "Ja, wir wissen das eine oder andere über Soggoth. Die Frage ist, ob Ihr wirklich mehr erfahren möchtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13897] = {title = "Die Schlacht um Dunkelküste", objective = "Tötet den Avatar von Soggoth in der Meistergleve.", description = "Die Urtume des Hains sind uns zu Hilfe gekommen, <Name>. Ich sehe selbst in diesem Augenblick durch ihre Augen.\n\nDer Schattenhammer muss sein Ritual schneller durchführen als ursprünglich geplant und bisher haben sie nur einen Teil des gefürchteten Soggoth wieder zum Leben erwecken können.\n\nZerstört diesen Teil, bevor es zu spät ist, <Name>. Ich werde andernorts gebraucht.\n\nKehrt zu den Druiden am Hain der Uralten zurück, wenn Ihr fertig seid. Sie werden Euch weitere Anweisungen erteilen.", progress = nil, completion = "Nun können wir in Frieden ruhen, &lt;Name&gt;. Es scheint, als wurde Dunkelküste gerettet. Und Ihr verdient den Dank dafür.", rewards = "Armschienen des uralten HainsSchild des DunkelküstenwärtersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13898] = {title = "Das Blatt wendet sich gegen uns", objective = "Tötet 8 Myrmidonen der Dunkelschuppen.", description = "Wir können die Naga nicht ungestraft davonkommen lassen, <Name>. Der Mord an dem Bewahrer des Hains ist eine Kriegserklärung.\n\nIhr könnt ihre Höhle auf der Insel Nazj'vel weit im Südwesten finden.\n\nÜberbringt ihnen eine deutliche Nachricht.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Naga wünschen die Zerstörung und Unterwerfung aller Oberflächenbewohner. Zögert nicht, sie aus unseren Landen zu vertreiben und sie zurück in die schattigen Tiefen des Ozeans zu drängen, dort, wo sie hin gehören.", rewards = "Zweig des HainbewahrersSchuppenmesserAuf Euch wartet eine dieser Belohnungen:\n\nFelros Signet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13899] = {title = "Der Kriegsfürst der Dunkelschuppen", objective = "Tötet Kriegsfürst Zornrücken in Nazj'vel.", description = "Wenn die Naga sich mit dem Schattenhammer verbünden wollen, so gnade ihnen Elune.\n\nBegebt Euch zu ihrer Höhle auf der Insel Nazj'vel und findet den Anführer der Naga, den Kriegsfürst Zornrücken.\n\nVielleicht kann das Horn der Urtume noch gerettet werden.", progress = nil, completion = "Der Kriegsfürst scheint das Horn nicht bei sich zu haben. Möglicherweise sprach er die Wahrheit.", rewards = nil}
MultiLanguageQuestData['de'][13900] = {title = "Das Opfer für Azshara", objective = "Haltet die Priesterinnen der Dunkelschuppen davon ab, das Horn der Urtume oben in Nazj'vel Azshara zu opfern.", description = "Der Kriegsfürst sagte, dass das Horn der Urtume als Opfergabe an Azshara oben in Nazj'vel gegeben wurde.\n\nVielleicht ist es noch nicht zu spät, das alte Relikt vor der Zerstörung zu retten.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Leider ist die Schlacht noch nicht gewonnen.", rewards = "Pantoffeln des RitualunterbrechersUralter HorngurtArmschienen des HornbläsersAuf Euch wartet eine dieser Belohnungen:\n\nTias Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13901] = {title = "Tiefe Verzweiflung", objective = "Tötet 6 Gezeitenpriesterinnen der Tiefschwarzen Grotte.", description = "Dieses Nagaproblem erweist sich als größer, als es auf den ersten Blick ersichtlich war, <Klasse>. Es scheint, als ob sich die Situation nicht einfach dadurch klärt, dass wir ihre Anzahl verringern. Um sie in ihre Schranken zu weisen, müssen wir einen nachhaltigeren Eindruck auf sie machen.\n\nReist zum nördlichen Ende des Zoramstrands und betretet die Tiefschwarze Grotte. Sobald Ihr dort seid, zeigt den Naga, dass ihre Anwesenheit in diesem Gebiet nicht länger toleriert werden wird!", progress = nil, completion = "Ausgezeichnet!\n\nDie Naga sollen zurück ins Meer, wo sie hergekommen sind!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13902] = {title = "Die Offensive festigen", objective = "Sprecht mit Balren von der Klaue am Hain der Uralten in Dunkelküste.", description = "Unsere Arbeit in Dunkelküste ist längst nicht vorbei. Wir haben die Landmassen vor dem Zerbersten bewahrt, aber unsere Feinde sind noch immer stark hier vertreten.\n\nIch möchte, dass Ihr südlich von hier ein paar Druiden am Hain der Uralten aufsucht. Sie werden von einem alten Freund von mir angeführt, von Balren von der Klaue.\n\nSagt ihnen, die Zeit ist reif, um die Schlacht zu unseren Feinden zu bringen. Ich werde nachkommen und sie unterstützen, sobald wir diese Gegend stabilisiert haben.", progress = nil, completion = "Wenn Malfurion Euch vertraut, so werde ich es ihm gleichtun. Ihr werdet sehen, dass unsere Feinde im Süden weitaus zahlreicher sind als wir.\n\nWo rohe Gewalt und Übermacht gegen uns sind, werden Strategie und Täuschung unsere größten Vorteile sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13903] = {title = "Gorishigelee", objective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", progress = nil, completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13904] = {title = "Pochiert, gerührt oder roh?", objective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", progress = nil, completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13905] = {title = "Sengende Rocfedern", objective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", description = "Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13906] = {title = "Sie werden so schnell erwachsen", objective = "Bringt 20 Gifthautzähnchen, das Gifthautjunge, 20 Stück Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Mor'vek im südöstlichen Teil des Marschlands im Krater von Un'Goro.", description = "Durch Eure fachmännische Fütterung und Pflege wird Euer Gifthautjunges schnell heranwachsen. Im Laufe seines Wachstums werden seine ersten Zähne durch bleibende ersetzt. Solltet Ihr die Milchzähne aufbewahren, werdet Ihr mit Leichtigkeit sagen können, wann es ausgewachsen genug sein wird, um zugeritten zu werden.\n\nEuer Junges wird Euch wissen lassen, was es braucht - gebt also genau Acht. Bringt mir Euren kleinen Ravasaurus und die Materialien für Euren Sattel, wenn er all seine Zähnchen verloren hat, und ich werde mich um den Rest kümmern.", progress = "Habt Ihr gut auf den Raptor achtgegeben?", completion = "Sieht aus, als hättet Ihr die Aufzucht überstanden, ohne einander umzubringen.\n\nDa, alles ist fertig. Ich habe Euren Gifthautravasaurus so abgerichtet, dass er Euch folgt, wenn Ihr in diese Pfeife blast.\n\nNur wenige besitzen die nötige Hingabe, um einen der kleinen Ravasaurier per Hand großzuziehen, aber sie sind die Mühe auf jeden Fall wert.", rewards = "Ihr bekommt:\n\nPfeife des Gifthautravasaurus"}
MultiLanguageQuestData['de'][13907] = {title = "Die Ruinen säubern", objective = "Tötet 10 Orakel der Grauflossen oder Flüchtlinge der Grauflossen, die in Wirrbarts Ausgrabung Unterschlupf suchen.", description = "Die Großbärte aus Eisenschmiede haben mich geschickt, um nach Wirrbarts Ausgrabung zu sehen, als sie von dem Desaster erfuhren. Seht Euch nur um! Wertvolle Artefakte in das Meer geschwemmt und monatelange Ausgrabungen in wenigen Minuten zunichtegemacht.\n\nAls die Gezeitenwelle eintraf, vernichtete sie die Lager der Murlocs an der Küste. Gute Nachrichten? Nein, kein Glück für uns. Die Überlebenden suchen in den Ruinen Unterschlupf und fügen der Ausgrabung mehr Schaden zu, als es die Elemente je gekonnt hätten. Könntet Ihr Eure Watstiefel anziehen und Euch für mich um die Sache kümmern?", progress = "Ich habe viel Gegurgel von dort unten gehört. Was geht vor sich?", completion = "Bravo, &lt;Name&gt;! Schauen wir die Lage doch jetzt noch einmal an.\n\nWie? MEHR Murlocs? Ich schwöre bei meinen Steinen, je mehr Murlocs man tötet, umso mehr scheinen aufzutauchen. Oder bilde ich mir das nur ein? Wir brauchen eine andere Vorgehensweise.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13908] = {title = "Aufsatteln", objective = "Bringt Mor'vek im südöstlichen Teil der Marschen im Krater von Un'Goro 20 unverwüstliche Leder, 20 Runenstoff und 80 Gold.", description = "Euer Ravasaurus ist stark und gesund, und Ihr habt Euch wirklich gut aneinander gewöhnt. Ihr werdet ihn reiten können, sobald ich Euren Sattel und das Zaumzeug fertiggestellt habe. Genau wie Ihr müssen die Materialien speziell behandelt werden, um den Giften zu widerstehen, die der Raptor erzeugt.\n\nAlles, was Ihr tun müsst, ist mir etwas unverwüstliches Leder, Runenstoff und Geld für den Rest des Materials zu bringen. Dann werde ich den Sattel im Handumdrehen fertiggestellt haben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPfeife des Gifthautravasaurus"}
MultiLanguageQuestData['de'][13909] = {title = "Treibgut übrig?", objective = "Findet 5 Stück verwertbare Grauflossentrümmer an der Küste und am Wasser in der Nähe von Wirrbarts Ausgrabung.", description = "Wir werden eine Lösung finden, <Name>. Wir brauchen nur ein bisschen zwergische Raffinesse. Denk nach, Groffy, denk schon!\n\nDie Murlocs wollen doch nur Unterschlupf, oder? Lasst uns konstruktiv sein. Das meine ich wortwörtlich.\n\nWährend der Katastrophe wurden alle möglichen Sachen an Land geschwemmt und ein paar der alten Hütten der Murlocs sind bestimmt noch benutzbar. Lauft an der Küste entlang und sucht für Murlocs geeignete Baumaterialien. Ihr werdet nicht lange suchen müssen.", progress = "Nass genug für Euch?", completion = "&lt;Archäologe Groff schaut die Trümmer durch.&gt;\n\nNaja, es findet sich kaum etwas, auf dem nicht herumgetrampelt wurde oder das nicht wie eine Toilette heruntergespült aussieht. Aber mit einem Dach drauf wird es schon ausreichen.\n\nSagt mir, &lt;Name&gt;, habt Ihr Euch je als Architekten gesehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13910] = {title = "Ein neues Zuhause", objective = "Baut eine Hütte für die Murlocs an der von Groff markierten Stelle an der Küste in der Nähe.", description = "Können wir es bauen? Natürlich! Westlich von der Ausgrabung habe ich ein Banner an der Küste aufgestellt. Der Sand ist stabil und eignet sich ebenso gut als Bauort wie jeder andere. Nehmt mein Werkzeug und die Trümmerstücke und baut diesen störrischen Plagegeistern ein neues Zuhause.", progress = "Und, was macht unser neues Heim mit Meerblick?", completion = "Haha, das klingt nach einem guten Haufen, den Ihr da gebaut habt. Sind sie darauf angesprungen? Gut, gut. Sehen wir mal, ob mein Plan erfolgreich ist.\n\n&lt;Archäologe Groff beobachtet, wie aus allen Richtungen massenweise Murlocs zum Strand gelaufen kommen. Seine Augenbrauen ziehen sich enger und enger zusammen.&gt;\n\nWas habe ich nur getan?", rewards = "Bänder des BehausungsgräbersGroffs PlaneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13911] = {title = "Der geistesabwesende Ausgrabungsleiter", objective = "Eskortiert den verwirrten Ausgrabungsleiter Wirrbart zu seinem Tagebuch. Sprecht mit Juniorarchäologe Ferd, wenn Ihr fertig seid.", description = "Und wer seid Ihr nochmal? <Name>? Kenne ich Euch? Wenn die Liga Euch schickt, dann könnt Ihr ihnen gleich sagen, dass ich hierbleibe! Ich gehe nicht ohne meinen Fund. Ich hielt ihn bereits in den Händen! Und dann brach plötzlich Geschrei aus. Und es wurde nass.\n\nHört gut zu, wer immer Ihr auch seid, ich habe alle Ereignisse von dem Tag der Gezeitenwelle in meinem Tagebuch aufgeführt. Und ich weiß auch, wo zu suchen ist. Nach dem Tagebuch, nicht nach dem Fund. Helft mir, eins zu finden, damit wir das andere finden können. Oder umgekehrt! Könnt Ihr mir folgen? Gut, dann folgt mir!", progress = nil, completion = "Ah, Ihr konntet dem Ausgrabungsleiter helfen, sein Tagebuch zu finden! Ich hätte nie gedacht, dass es die ganze Zeit hier war.\n\nEines Tages müsst Ihr mich zu der anderen Ausgrabungsstätte bringen, von der er dauernd erzählt.", rewards = "WollsammlerhandschuheUnbewusste GamaschenAuf Euch wartet eine dieser Belohnungen:\n\nBahrums Ring der schlechten Launen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13912] = {title = "Schlammige Geheimnisse", objective = "Findet eine schlammverkrustete uralte Scheibe in den Ruinen in der Nähe.", description = "Hinter Wirrbarts vergesslichem Äußeren befindet sich der Geist eines Genies, ein Mysterium im Gewand eines Senilen. Ich werde den alten Herrn nicht aufgeben. Seht hier, was ich in seinen Notizen gefunden habe... nicht hier... nein, das ist eine Einkaufsliste... Hier, auf der Seite, auf der er versucht herauszufinden, welches Jahr es ist: die Scheibe!\n\nWir glauben, dass es sich bei diesem Artefakt der Titanen um eine Art verschlüsselte Speicherscheibe handelt. Wir waren gerade dabei, es vorsichtig auszugraben, als das Desaster losbrach und nun hoffen wir, dass es sich noch immer in den Ruinen befindet. Taucht und sucht für mich danach!", progress = "Ihr habt sie gefunden? Das ist gut. Groff möchte von hier so schnell wie möglich aufbrechen.", completion = "Spektakulär! Gute Arbeit, &lt;Name&gt;! Wirrbart würde Euch sicher persönlich danken, wenn er sich an Euren Namen erinnern könnte.\n\nSeht Euch die Oberfläche der Scheibe an - diese mikroskopisch kleinen Verzierungen sind fantastisch. Dieses Rad enthält mit Sicherheit viele Informationen, wir müssen nur herausfinden, wie wir sie verstehen können...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13913] = {title = "Sie haben unsere Gnome", objective = "Rettet Boog den \"Zahnradflüsterer\" und Minx aus Schmerzensmeister Thundraks Wagen der nimmer endenden Agonie.", description = "Der Sprengstofftrupp der Gnome, die wir aus der Tüftlerstadt angefordert haben, ist letzte Woche eingetroffen. Gerade rechtzeitig, um uns bei einem Angriff der Horde zu unterstützen. An dem Tag haben wir viele Soldaten verloren. Der Großteil der Gnomtruppen ist gefallen. Jetzt steht uns das Wasser bis zum Hals, die Silberwindzuflucht ist verloren und wir haben nur noch ein dutzend Gnome.\n\nIch flehe Euch an, helft uns, <Name>. Reist nach Osten zur Silberwindzuflucht und seht Euch nach überlebenden Gnomen um. Sie wurden alle von einem großen, gnadenlosen Orc namens Thundrak weggekarrt. Findet ihn und Ihr findet unsere Gnome.", progress = nil, completion = "Habt Dank, &lt;Name&gt;. Traurige Kunde bringt Ihr vom Rest der Gnomtruppe, aber zumindest konntet Ihr ein paar retten. Dafür bin ich Euch dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13914] = {title = "Sengende Rocfedern", objective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", description = "Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13915] = {title = "Sooooo hungrig", objective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", progress = "Das Gifthautjunge leckt sich das Maul und legt den Kopf schräg.", completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13916] = {title = "Pochiert, gerührt oder roh?", objective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", progress = "Das Junge sieht Euch an.", completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13917] = {title = "Gorishigelee", objective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", progress = nil, completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCast Venomhide Counter\n\nIhr bekommt:\n\nGifthautzähnchen"}
MultiLanguageQuestData['de'][13918] = {title = "Die Verbindung der Titanen", objective = "Benutzt den Detektor für vergrabene Artefakte am Strand in der Nähe von Wirrbarts Ausgrabung, um 5 uralte Gerätefragmente zu finden. Fügt sie zusammen, um das uralte geschlitzte Gerät zu erhalten.", description = "Mit der Scheibe ergeben auch ein paar unserer früheren Funde jetzt mehr Sinn. Kurz nach meiner Ankunft hat Ausgrabungsleiter Wirrbart etwas gefunden, dass er für einen prähistorischen Toaster hielt.\n\nIch glaube eher, dass diese Kiste mit Öffnungen ein Lesegerät für besondere Daten ist. Leider ist es auseinandergefallen und mit dem Rest unseres Basislagers weggeschwemmt worden, als die Gezeitenwelle über uns hereinbrach!\n\nEs ist aber sicherlich nicht weit gekommen, <Name>. Die Einzelteile sind bestimmt im Sand vergraben. Hier, nehmt meinen einwandfrei funktionierenden Detektor für vergrabene Artefakte, um den Strand damit abzusuchen.", progress = "Habt Ihr alle Teile des geschlitzten Gerätes zusammengefügt? Möglicherweise müssen wir noch die Überreste von Wirrbarts Pausenbrot von der Datenschnittstelle des uralten Geräts entfernen.", completion = "Ja, ja, JA, das ist es! Seht her, dieser Schlitz hat genau die gleiche Größe wie die uralte Scheibe, genau, wie ich vermutet hatte. Hier ist Eure Belohnung, &lt;Name&gt; - Ihr habt sie Euch redlich verdient.\n\n\n\nSeid Ihr bereit, Euch der Geschichte zu stellen? Lasst uns herausfinden, was uns die Uralten zu sagen haben!", rewards = "Sandwichteller des ProfessorsAuf Euch wartet eine dieser Belohnungen:\n\nUnidentifiziertes Kochgerät\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTitan's Terminal Quest Complete\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13919] = {title = "Ein Ausflug zum Mondbrunnen", objective = "Nehmt Elunes Träne und reinigt sie in den Wassern des Mondbrunnens der Reinheit im Eschental.", description = "Es hat nicht funktioniert.\n\n<Ein besorgter und verzagter Ausdruck zeichnet Pelturas' Gesicht, als er die Träne aus der Suppe entfernt und sie vorsichtig wäscht.>\n\nDer Ausbruch des Donnergipfels muss sie auf irgendeine Weise beeinträchtigt haben. Ihr müsst die Träne zum Mondbrunnen der Reinheit bringen. Er liegt noch immer unversehrt und von der Macht der Göttin beschützt am südöstlichen Fuß des Vulkans.\n\nDort wascht Ihr sie in den heiligen Wassern von Elune. Was danach geschieht, vermag ich nicht zu sagen. Ich fürchte um das Leben meiner Tochter. Es liegt nun in Euren Händen, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13920] = {title = "Bevor Ihr geht...", objective = "Bringt 5 Hirschsteaks zu Kommandant Grimmfang in Zoram'gar.", description = "In Höllschreis Wacht wird jede Hilfe gebraucht, <Name>. Aber bevor Ihr Euch auf den Weg macht, gibt es noch etwas, das hier erledigt werden muss.\n\nDie meisten unserer verderblichen Waren sind während eines Angriffs der Allianz auf See verloren gegangen. Wir müssen genug Nahrungsmittel sammeln, um den Eschentalfeldzug durchführen zu können.\n\nReist nach Osten. Dort findet Ihr reichlich Wild. Kehrt mit dem besten Fleisch zurück, das Ihr für unsere Truppen finden könnt!", progress = "Ja, <Volk>?", completion = "Dieses Wildbret sollte die Stimmung unserer Soldaten für die bevorstehende Schlacht heben. Hier habt Ihr etwas für Eure Mühen.", rewards = "FleischverpackungsbändchenJe'neus JagdwesteRehpirschergamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13921] = {title = "Jener, der nach Vergebung sucht", objective = "Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.", description = "<Eine Stimme aus dem Mondbrunnen durchflutet Euren Geist und gibt Euch ein Gefühl absoluten Friedens.>\n\nIhr sucht eine Heilung für das Kind, aber wisset, das alles seinen Preis hat. Im Osten liegt der Rajenbaumturm. Vor dem Turm neben dem Mondbrunnen steht jemand, welcher der Verderbnis anheimgefallen ist.\n\nAvrus Böswisper sucht Vergebung und Erlösung, <Name>. Werdet Ihr ihm helfen, seinen Wunsch zu erfüllen und dadurch Euer eigenes Ziel zu erreichen?", progress = nil, completion = "&lt;Der Satyr grinst spöttisch, aber als ihm klar wird, dass Ihr nicht hier seid, um ihn zu züchtigen, ändert sich sein Gesichtsausdruck.&gt;\n\nEndlich naht meine Erlösung. Ich habe lange auf diesen Tag gewartet und ich glaube, ich weiß, wie ich Euch im Gegenzug dazu helfen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13922] = {title = "In den Händen des Widernatürlichen", objective = "Erlangt 5 gefallene Mondsteine.", description = "Mein ehemaliger Klan, die Teufelshufe von Nachtflucht, hat den Himmelssturzsee vor einiger Zeit überfallen. Sie haben Mondsteine geraubt, die in dieser Gegend einzigartig sind.\n\nDiese Mondsteine sind dafür bekannt, große Heilkräfte zu besitzen und können sicherlich dafür verwendet werden, das kleine Mädchen zu heilen, das krank in Astranaar liegt.\n\nNachtflucht liegt an der Straße im Osten, die nach Norden führt. Von ihr zweigen verschiedene Pfade in Richtung Osten ab, die in die Hügel führen und dort findet ihr meine reuelosen Brüder. Sie haben, was Ihr sucht.", progress = "Fünf Mondsteine werden benötigt, um sicherzustellen, dass das Mädchen geheilt wird.", completion = "Ihr habt alle Mondsteine, die benötigt werden. Und dennoch wird gesagt, dass ein Leben geopfert werden muss, um ein anderes zu retten.\n\nIch werde sicherstellen, dass die Mondsteine Relara um jeden Preis heilen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13923] = {title = "Zu Höllschreis Wacht", objective = "Sprecht mit Hauptmann Goggath in Höllschreis Wacht.", description = "Auf ins Schlachtgetümmel, <Volk>!\n\nHöllschreis Wacht ist eine unserer am stärksten umkämpften Fronten im Eschental. Die Erfahrung wird Euch nützen... vorausgesetzt, Ihr überlebt.\n\nWenn Ihr bereit seid, sprecht mit Andruk. Ich habe mit ihm besprochen, dass er Euch direkt zu Eurem Posten bringt.\n\nSobald Ihr dort eintrefft, macht Hauptmann Goggath ausfindig. Er wird Euch weitere Anweisungen erteilen.\n\nBringt Schmerz und Tod über Eure Feinde! Für die Horde!", progress = nil, completion = "Als Kind kommt ihr hierher, &lt;Volk&gt;.\n\nAls &lt;Klasse&gt; der Horde mit reichlich Kampferfahrung sollt Ihr wieder gehen!\n\nEntweder das, oder Ihr endet als Rabenfutter...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13924] = {title = "Ende gut", objective = "Überreicht die geheiligten Mondsteine Pelturas Weißmond in Astranaar im Eschental.", description = "Habt Dank, dass Ihr mich von einem Schicksal errettet habt, das schlimmer ist als der Tod, <Name>! Ihr habt mich und das Kind gerettet!\n\nNun, das Kind ist fast gerettet. Alles was Ihr tun müsst, ist die Mondsteine die Straße Richtung Westen nach Astranaar zu bringen. Händigt die Steine Pelturas aus. Er wird wissen, was zu tun ist.\n\nGeht in Frieden. Elune sei gepriesen!", progress = "<Name>, seid Ihr das? Seid Ihr mit dem Heilmittel für Relara zurückgekehrt?", completion = "Oh, &lt;Name&gt;, Ihr habt meine Tochter gerettet! Ich weiß, dass die Macht der Mondsteine meiner Tochter Ihre Kraft zurückgeben wird!\n\nEure Hilfe war unermesslich wertvoll und ich kann sie Euch nie vollständig vergelten, aber... Bitte, nehmt das hier. Abgesehen von Relara, ist dies mein wertvollster Besitz.", rewards = "WeißmondhandschuheGürtel der heilbringenden GlücksbringerStiefel des ErlösersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13925] = {title = "Ein Stückchen Vorbeugen", objective = "Testet den Lebensbringerschössling an einem gesunden ergrauten Distelbären, Weißschwanzhirsch, Mondpirscherpatriarchen oder einer gesunden Mondpirschermatriarchin in der Nähe.", description = "Seid Ihr vertraut mit den Alten, <Name>? Onu und ich sind uns sicher, dass das von Euch im See gefundene Artefakt nur ihr Werk sein kann. Und es verzehrt Dunkelküste weiterhin. Irgendetwas hat die von uns lang totgeglaubten Schrecken erweckt. Schrecken, denen weder Ihr noch ich gewachsen sind. Aber zuerst müssen wir uns um die Wildtiere kümmern.\n\nHier in diesem Schössling ist die ganze Lebensessenz, die Ihr mir gebracht habt. Ich glaube, wir können damit die Fauna der Gegend retten. Versucht es zuerst an einem nicht verzehrten Bären, Hirsch oder Mondpirscher und berichtet mir, was geschieht!", progress = "Der Schössling, den Ihr bei Euch tragt, wächst ohne Unterbrechung an Macht. Leben ist erneuerbar, <Name>. Hat es funktioniert?", completion = "Interessant... Es scheint, als könnte unser Heilmittel die Wildtiere retten, aber Ihr habt noch etwas anderes gesehen? Etwas Bösartiges, Wütendes gespürt?\n\nDas ist ein gutes Zeichen, &lt;Name&gt;. Wer auch immer hinter diesem Problem steckt ärgert sich, und das bedeutet, das wir auf dem richtigen Weg sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13926] = {title = "Kleines Waisenkind Roo von den Orakeln", objective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Orakelwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, <Name>. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, <Name>, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", progress = "Du dich um uns kümmern?", completion = "Du bringst uns weg von Wauwaujungen? Gut. Wir dich schon mögen. Wauwaujunge haben alle unsere Lieblingsspielzeuge weggenommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13927] = {title = "Kleines Waisenkind Kekek von den Wolvar", objective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Wolvarwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, <Name>. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, <Name>, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", progress = "Waisenfrau sagen, Kekek mit dir gehen.", completion = "Du bringst Kekek zum Jagen? Ist gut von alter Waisendame wegzukommen, die Kekek nicht jagen lässt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13928] = {title = "Rettet die Gefallenen", objective = "Sammelt 10 Leichen der Lachenden Schwestern.", description = "Meine Schildwachen und ich haben von Bewahrer Ordanus den Befehl erhalten, hier zu bleiben und den Turm zu verteidigen. Bisher konnten wir die Horde erfolgreich zurückschlagen, aber jetzt schlagen sie einen Bogen um uns und greifen unseren Zufluchtsort im Norden direkt an.\n\nDer Bewahrer schickt seine Dryaden aus, um die Bäume zu verteidigen, aber sie scheinen der Vorhut der Kriegshymnenorcs nicht gewachsen.\n\nIhr müsst dorthin und so viele Leichen der Lachenden Schwestern einsammeln, wie Ihr könnt. Bringt sie zu Halannia im Baum am Zufluchtsort. Sie wird wissen, was zu tun ist.", progress = "Ich bin erstaunt, dass Ihr die Reihen der Horde durchbrechen konntet und es geschafft habt, hier hereinzukommen, <Volk>.", completion = "Habt Dank, &lt;Klasse&gt;. Wir haben alle Hände voll damit zu tun, diesen Zufluchtsort zu verteidigen, aber wenn ich wieder zu Atem komme, werde ich dafür sorgen, dass diese Schwestern ins Leben zurückkehren, wenn es der Göttin gefällt.\n\nIhr habt Euren Heldenmut bewiesen... Wir könnten Eure Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13929] = {title = "Der grööößte Baum überhaupt!", objective = "Besucht mit Eurem Waisenkind Roo den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", description = "Bevor der große Krieg passiert war und wir das Dorf verlassen haben, wir erinnern uns dran, wie Soo-say uns vom größten von allen Bäumen erzählt hat!\n\nSoo-say es nennen Grauschlund oder so. Soo-say uns erzählen, es ist in der Mitte von den Kritzlihügeln. Nein, warte. Das nicht was Soo-say gesagt hat. Soo-say sagt Grizzlyhügel. Jetzt wir uns erinnern! Großer Baum und in der Mitte von Grizzlyhügeln. Kann gar nicht übersehen!\n\nDu uns bringen dahin, oki? Wir uns anschauen den großen Baum von innen? Soo-say sagen, große Bärenleute leben auch im Baum. Vielleicht wir sie auch sehen.", progress = nil, completion = "Wir haben nicht gewusst, dass Bäume sooo groß werden können. Nee. Vielleicht die Großen hatten besonderen Plan für sie?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13930] = {title = "Heimat der Bärenleute", objective = "Besucht mit Eurem Waisenkind Kekek den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", description = "Hochschamane Rakjak uns immer Geschichten von mächtigen Kriegern erzählt, auch von weit weit weg. Manchmal er hat erzählt über riesige Bärenleute, wo einen großen Krieg um eine große Baumstadt kämpfen.\n\nVielleicht du bringt Kekek dort hin, Baum anschauen, Kampf anschauen! Hochschamane Rakjak erzählt Kekek, die große Baumstadt Grauschlund steht in der Mitte von den Grizzlyhügeln.\n\nKekek hat nie eine Stadt gesehen, bevor er kennengelernt hat die Waisendame, aber die Stadt hier hat keine Krieger, nur Männer in lila Kleidern. Kekek will richtige Krieger sehen, die um eine richtige Stadt kämpfen.", progress = nil, completion = "Das sein Kekeks Art von Stadt. Bärenleute kämpfen genauso um ihr Zuhaus, wie Wildherzen es tun. Waisendame sagt Kekek, er soll nicht mit anderen Welpen kämpfen. Kekek kämpft trotzdem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13931] = {title = "Ein neues Jahr, ein neues Souvernir", objective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", rewards = "Ihr bekommt:\n\nGrüner Braufestkrug"}
MultiLanguageQuestData['de'][13932] = {title = "Ein neues Jahr, ein neues Souvernir", objective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh.... oder seins...", rewards = "Ihr bekommt:\n\nGrüner Braufestkrug"}
MultiLanguageQuestData['de'][13933] = {title = "Der Bronzedrachenschrein", objective = "Besucht mit Eurem Waisenkind Roo den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Manchmal Hochorakel Soo-say erzählt Geschichten über Schreine für Drachendinger, nicht wie großer Regenstein, aber anders. Soo-say sagt uns, vielleicht wir uns dort selbst sehen, aber nicht wie in Glitzer-Glitzer. Soo-say meint, wir uns dort sehen, wie wenn in vielen Jahren später.\n\nBringst du uns dorthin? Wir uns erinnern, Schrein für Bronzedrachendinger ist in einem Ort, der Drachenöde heißt. Soo-say sagt, großer Regenstein zeigt ihm Schrein im Nordosten vom Wyrmruhtempel, oder nordwestlich von einem Ort, den die Trockenhäute Feste Wintergarde nennen. Wir gehen?", progress = nil, completion = "Wir sind sehr glücklich, dass du uns hierhergebracht hast, &lt;Name&gt;. Wir haben uns immer Sorgen gemacht, was mit uns passieren würde, als Waisenmatrone uns in Sholazar gefunden hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13934] = {title = "Der Bronzedrachenschrein", objective = "Besucht mit Eurem Waisenkind Kekek den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Als Kekek noch ein Welpe war, er hat die Ältesten oft von einem Schrein reden hören, weit weg. Manchmal sie sagen, dass die Bronzedrachendinger dort alles über die Zukunft wissen.\n\nKekek dir sagt, er wird großer Krieger sein, wir jetzt gehen nachsehen. Bronzedrachendingschrein ist irgendwo in Drachenöde, nordöstlich von Drachendingtempel, was Wyrmruh genannt wird und nordwestlich von Menschenstadt, was Wintergarde heißt.\n\nWir dort hingehen und Zukunft anschauen. Beweisen, dass Waisendame unrecht hat. Kekek sein Krieger, kein Lümmel.", progress = nil, completion = "Du siehst? Kekek nie genug davon bekommt zu sagen, \"Kekek dir das gesagt.\"\n\nVielleicht du jetzt auch andere Sachen glauben, die Kekek sagt, wie, dass Himmel grün ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13935] = {title = "Verteidigt den Baum!", objective = "Sprecht mit Halannia, um den Schatten von Schattumbra zu beschwören und verwendet dessen Kraft, um 50 Feinde des Kriegshymnenklans am Rajenbaum zu vernichten.", description = "Wir haben die Kraft des Herzens des Waldes dazu verwendet, um den Baum gegen die Horde zu verteidigen, aber seine Kraft ist nicht grenzenlos. Wir müssen sie dazu einsetzen, die Schlacht zu ihnen zu tragen!\n\nSchattumbra, die große Katze des Waldes, streift in der Nähe umher. Von ihr sollen wir unsere Hilfe beziehen. Ihr werdet eins mit dem Schatten von Schattumbra. Ihr werdet die Essenz des Panthers in Euch aufnehmen und diejenigen vernichten, die es wagen, die Macht des Eschentals herauszufordern.", progress = nil, completion = "Eine grausamer Anblick, aber die Feinde des Eschentals haben es verdient. Die Horde maßt es sich an, zu glauben, dass sie uns unseren geliebten Wald nehmen kann.\n\nSie begehen einen tödlichen Fehler!\n\nIhr habt den Rajenbaum vor der Zerstörung bewahrt, &lt;Name&gt;. Sicherlich finden wir eine Belohnung, die unseres Champions würdig ist?", rewards = "RajenbaumschildSchattumbras ZornFrostschattenarmbrustDer folgende Zauber wird auf euch gewirkt:\n\nDefend the Tree!: Quest Completion - Exit Shade of Shadumbra\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13936] = {title = "Twidels Narretei", objective = "Hauptmann Goggath will, dass Ihr mit Twidel in Höllschreis Wacht sprecht.", description = "Verspätungen, Verspätungen, Verspätungen! Ich bin mit meiner Weisheit am Ende!\n\nMir wurde gesagt, dieser Goblin sei brillant... dass er ein Gerät entwickeln würde, das die Feinde zur Unterwerfung zwingt. Bisher hat er nichts als leere Versprechen gemacht. Wenn er noch einmal mit leeren Händen zu mir kommt, werfe ich ihn persönlich von dieser Klippe!\n\nGeht zu ihm und sprecht mit ihm, <Klasse>. Lasst ihn wissen, dass mein Geduldsfaden bald reißt!", progress = nil, completion = "Hör mir mal zu, &lt;Klasse&gt;!\n\nDer Boss weiß die Kunst und das Handwerk, die zur Herstellung besten Sprengstoffs gehört einfach nicht zu würdigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13937] = {title = "Ein Besuch bei den Wunderwerken", objective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Roo, zu.", description = "Haben wir Zeit für noch einen Halt? Wir haben gehört, dass Dalaran hat einen Spielzeugladen, aber wir dürfen nie hingehen. Waisendame sagt, zu viele Waisen würden sich in Laden drängen. Vielleicht können wir gehen, nur wir?\n\nKönnen wir ein kleines Papierzeppelin haben? Wir denken, sie haben so was bei Wunderwerke in Dalaran. Wir wollten schon immer mit so was spielen. Vielleicht du uns eins zuwerfen?", progress = nil, completion = "Das hat Spaß gemacht! Wir mögen Spielzeugladen. Vielleicht Waisenmatrone uns irgendwann mitnehmen. Wir fragen. Vielleicht fragst du sie auch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13938] = {title = "Ein Besuch bei den Wunderwerken", objective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Kekek, zu.", description = "Du bringen Kekek zu noch einen Ort? Waisenfrau sagt, dass Dalaran Spielzeugladen hat, der Wunderwerke heißt, aber Kekek den noch nie gesehen. Sie sagt, dass, wenn ein Waisenkind hingeht, sie jeden hinbringen muss. Vielleicht du bringen Kekek dorthin?\n\nKekek hat andere Kinder gesehen, die mit kleinen Papierzeppelin spielen? Kekek gehört, dass die von Wunderwerken kommen. Vielleicht du einen besorgen und ihn gemeinsam mit Kekek herumwerfen?", progress = nil, completion = "Kekek mag mit Papierzeppelin spielen. Nicht so gut wie jagen, aber damit gibt's was zu tun, wenn es langweilig sein im Waisenhaus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13940] = {title = "Den Traum verlassen", objective = "Sprecht mit Malfurion beim Auge des Vortex in Dunkelküste.", description = "Gut festhalten, <Name>. Die Reise zurück in die wirkliche Welt kann Geist und Körper von Unvorbereiteten etwas mitnehmen.", progress = nil, completion = "Ihr kommt gerade rechtzeitig zurück, &lt;Name&gt;. Ich weiß nicht, wie viel länger wir noch aushalten können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEye of the Vortex - Detect Quest Invisibility 4\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13942] = {title = "Bombenbasteln", objective = "Twidel in Höllschreis Wacht will, dass Ihr ihm 10 Proben mondberührten Ton bringt.", description = "Ich bin hier zweifellos einer Sache auf der Spur!\n\nIch habe genug flüchtige Stoffe aus unserem Arsenal, um den Sprengstoff herzustellen, den Goggath haben will, aber ich muss ihn stabilisieren und in die Bomben füllen.\n\nIch brauche Ton – und nicht einfach irgendeinen Ton... mondberührten Ton.\n\nIhn findet man nur an den nördlichen Ufern von Astranaars Seen, und er besitzt die Eigenschaften, die ich brauche um meiner Entdeckung zur größtmöglichen Wirkung zu verhelfen!", progress = "Zeigt her, was Ihr mir gebracht habt, <Volk>.", completion = "Das ist PERFEKT!\n\nOh, wartet, bis Ihr seht, was ich damit anstellen kann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13943] = {title = "Ein Deckel für die Scharmützler", objective = "Hauptmann Goggath will, dass Ihr 10 Scharmützler von Astranaar und 3 Offiziere von Astranaar tötet.", description = "Unsere Kräfte sind noch nicht bereit, Astranaar anzugreifen, <Klasse>. Sie wissen trotzdem, dass wir kommen und sie werden sich nicht damit zufrieden geben, stillzusitzen und auf uns zu warten. Am Fuße dieser Klippen haben sie ein Lager aufgeschlagen, von wo aus sie nachts ihre lästigen Angriffe starten.\n\nBevor diese Geplänkel ihre Kühnheit weiter steigern, will ich, dass Ihr ihnen einen Besuch mit dem Zorn der Horde abstattet! Kehrt zu mir zurück, wenn Ihr den Elfen ihr Mütchen ein wenig gekühlt habt.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;. Aber es gibt hier noch reichlich zu tun.", rewards = "Umhang der BereitschaftArmschienen der DemutFundamentschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13944] = {title = "Kleine Gestalt, kurze Lunte", objective = "Probiert die improvisierte Sprengstoffstange an dem liegengebliebenen Wagen in Höllschreis Wacht aus.", description = "<Twidel gestikuliert wild.>\n\nIch habs geschafft! Das sollte selbst Goggath zufriedenstellen!\n\nWir brauchen nur einen Test, der unsere Mühen eindrucksvoll beweist... ah, der Wagen!\n\nCheffe mäkelt doch schon seit Tagen, dass wir den verrotteten Schrotthaufen endlich wegschaffen sollen. Nutzt meinen Sprengstoff, um ihn in die Luft zu jagen. Wollen wir doch mal sehen, was der Hauptmann dann zu sagen hat!", progress = nil, completion = "Twidel hat also eine Möglichkeit gefunden, diesen Sprengstoff zum Funktionieren zu bringen, wie?\n\nDas war aber auch Zeit...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13945] = {title = "Gefahr vor Ort", objective = "Tötet 20 Knarzklauenfurbolgs auf dem Grabhügel von Ban'ethil und in der Umgebung.", description = "Die Aggression der Knarzklauen begrenzt unsere Möglichkeiten. Niemand von uns ist davon begeistert, mit Klingen und Pfeilen gegen Kreaturen vorzugehen, mit denen wir einst befreundet waren, aber ich befürchte, dass sie sich bald gegen Dolanaar wenden werden.\n\nDie größere Sorge sind für mich die Furbolgs auf der Lichtung von Ban'ethil und im Grabhügel von Ban'ethil. Ihr müsst nach Westen reisen, in den Grabhügel vordringen und so viele der Knarzklauen töten, wie Ihr nur könnt. Wir bekommen wahrscheinlich nicht mehr viele Gelegenheiten, ihrer Stärke Einhalt zu bieten - beeilt Euch.", progress = nil, completion = "Beeindruckend. Ich hoffe, meine Jägerin hat ihren Teil getan.\n\nWenn wir mit diesem Eifer weitermachen, können wir Teldrassil vielleicht doch noch von der Korruption befreien, die Alexstrasza selbst nicht ausbrennen konnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13946] = {title = "Vergeltung der Natur", objective = "Verwendet Zornwurzelsamen, um 12 Teufelsfelsgrellkin zu töten.", description = "Ich bin froh, dass Ihr bereit wart, Eure Fehler wieder gutzumachen - das sagt viel über Euren Charakter aus.\n\nIch habe noch eine Aufgabe für Euch. Ich habe einige Zornwurzelsamen gesammelt. Sie sind Teufelszapfen ähnlich, aber viel stärker. Die Natur reagiert oft sehr negativ auf Dämonen und diese Zornwurzelsamen beinhalten hochkonzentrierte Abwehrstoffe.\n\nNördlich von hier, am Teufelsfels, sind Grellkin, die nicht mehr zu läutern sind. Benutzt die Zornwurzelsamen, um sie auszulöschen, bevor sie zu einer größeren Bedrohung werden.", progress = nil, completion = "Gut. Ich weiß, dass das wahrscheinlich nicht gerade angenehme Arbeit war, aber wir sind Euch sehr dankbar.\n\nIch fürchte um unseren geliebten Teldrassil... es sieht aus, als werde er von Tag zu Tag verderbter, und unsere Unkenntnis der Ursache quält mich sehr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13947] = {title = "Bombenstimmung in Astranaar!", objective = "Hauptmann Goggath will, dass Ihr Twidels improvisierten Sprengstoff verwendet, um 20 Schildwachen von Astranaar zu töten und 10 Schleudern von Astranaar zu zerstören.", description = "Twidel hat also endlich einen geeigneten Sprengstoff erfunden, wie?\n\nEr hätte keinen besseren Augenblick wählen können. Während wir sprechen, bereiten die Elfen von Astranaar einen vernichtenden Angriff auf unserer Lager vor.\n\nLasst unsere neue Waffe aus dem Himmel auf sie niederregnen! Die Zerstörung von Astranaar wird ein Stich ins Herz aller Nachtelfen sein!\n\nSprecht mit Thraka, wenn Ihr bereit seid, mit dem Angriff zu beginnen.\n\nZielt gut, <Klasse>.", progress = "Astranaar brennt!\n\nFür die Horde!", completion = "Die glorreichen Geschichten der Horde sollen noch lange von Euren Taten berichten.\n\nEure Bemühungen haben dem Feind einen vernichtenden Schlag zugefügt!", rewards = "Präventiver SchlägerStab des feurigen SchicksalsGamaschen von Höllschreis WachtDer folgende Zauber wird auf euch gewirkt:\n\nSee Invis Quest Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13948] = {title = "Verbesserte Beobachtungen", objective = "Schleicht mit Hilfe der Pantherfigur in die Meistergleve und beobachtet die Anführer der Schattenhammerkultisten auf der höheren Ebene.", description = "Die Kultisten sind anscheinend dabei, die Überreste eines Wesens auszugraben, das als Soggoth der Glitschige bekannt ist.\n\nVielleicht haben die höherrangigen Kultisten mehr Informationen für uns.", progress = nil, completion = "Das sind schreckliche Neuigkeiten, &lt;Name&gt;. Wenn Ihr recht habt, so müssen wir schnell und entschieden handeln.\n\nWir können nicht zulassen, dass \"Soggoth\" wieder zum Leben erweckt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13949] = {title = "Karawane am Wegekreuz", objective = "Sprecht mit Halga Blutauge in der Fernwacht, um die nächste Wegekreuz-Karawane zu Grol'doms Hof zu begleiten.", description = "<Halga grinst entwaffnend und hält eine enorme Feuerwaffe in die Höhe.>\n\nHabt Ihr jemals eine von diesen verwendet, <Name>? Es ist ein Monster! Höllenfeuer mit Fadenkreuz. Zu schwer, um sie zu Fuß zu verwenden, aber perfekt, wenn man einer Karawane vorausreitet. Ich nenne sie den 'Straßenfeger'.\n\nWir müssen den Nachschub, den Ihr gesammelt habt, zum Wegekreuz bringen. Und ich rechne mit Schwierigkeiten. Ich hätte Euch gerne als Begleiter. Und als Feuerschutz. Sagt einfach, wenn Ihr bereit seid, und ich setze Euch an die Spitze der nächsten Karawane.", progress = "Mok'ra, Fremdling. Seid Ihr hier aus der Fernwacht?", completion = "Ihr seid ein unverhoffter Anblick, &lt;Volk&gt;. Das ist die erste Karawane, die es in dieser Woche geschafft hat!", rewards = "Gürtel des BlutaugesKranals WesteHandschuhe der KarawaneneskorteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13950] = {title = "Spielgefährten!", objective = "Nehmt Euer Waisenkind, Roo, und besucht die Zuflucht der Winterflossen. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Im Waisenhaus kann es schon sehr einsam werden, weißt du? Manchmal wollen wir mal rauskommen, neue Freunde finden.\n\nVielleicht kannst du uns irgendwohin mitnehmen, wo andere Junge sind? Wir haben von einem Ort gehört, der Zuflucht der Winterflossen genannt wird, in der großen Boreanischen Tundra. Wir glauben, dass es ganz weit drüben sein, im Nordwesten, in der Nähe der Kante der Kaltarrainsel.\n\nDie Waisendame sagen, dass jemand Tapferes dort ein paar Junge gerettet hat. Wir glauben, sie sind auch einsam. Wir glauben, sie brauchen Freunde. Bringst du uns hin?", progress = nil, completion = "Das hat Spaß gemacht! Können wir irgendwann noch mal hingehen? Wir können es gar nicht abwarten, unseren neuen Freund wiederzusehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13951] = {title = "Spielgefährten!", objective = "Nehmt Euer Waisenkind, Kekek, und besucht die Schneewehenlichtung. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Kekek ist der Meinung, es gibt nicht genügend andere Welpen, die auch bei der Waisendame leben. Vielleicht gehen wir und besuchen ein paar?\n\nKekek kennt einen Stamm, der in der Drachenöde lebt, an einem Ort, der Schneewehenlichtung heißt. Du kennst? Schneewehenlichtung ist im Norden von einer Walrossstadt, die heißt Hafen Mo'aki, und im Süden von Rubindrachenschrein.\n\n<Kekek knurrt bei der Erwähnung der Tuskarr.>\n\nDu bringst Kekek da hin, zu ein paar von den Dörfern dort. Vielleicht treffen wir neue Wolvar und zeigen ihnen, wie stark die Wildherzen sind!", progress = nil, completion = "Kekek mag neue Schneewehenfreunde, vielleicht kann irgendwann zurückkommen und zusammen jagen gehen. Vielleicht können wir Walrus-Leute umwerfen, wenn sie schlafen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13952] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Menschengeist auf dem Friedhof von Sturmwind.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][13953] = {title = "Naga unter uns", objective = "Kehrt zu Balren von der Klaue beim Hain der Uralten in Dunkelküste zurück.", description = "Der Schädel dieser Kreatur wurde wohl im Kampf mit Aros gebrochen. Es handelt sich anscheinend um eine Kreatur, die Euch bislang als Naga ein Begriff war.\n\nTrotz ihrer monströsen Gestalt sind die Naga Nachtelfen, die von der arkanen Magie von Königin Azshara verformt wurden.\n\nSie haben sich wohl dazu entschlossen zu verhindern, dass Ihr das Horn der Urtume erhaltet.", progress = nil, completion = "Die Naga haben sich mit den Schattenhammerkultisten verbündet? Das hat uns gerade noch gefehlt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13954] = {title = "Die Drachenkönigin", objective = "Nehmt Euer Waisenkind, Roo, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "In einer von Hochorakels Soo-says Geschichten es heißt, die Großen haben die Drachen gemacht und auch die Königin für die Drachen. Wir wollen sie sehen! Würdest du uns mitnehmen zur Spitze des Wyrmruhtempels? Wir erinnern uns, dass Soo-say uns erzählt hat, dass das Tempeldings in der Mitte der Drachenöde war.\n\nWir wollen wirklich so gerne die Drachenkönigin treffen. Sie muss so groß und schön sein. Vielleicht hilft sie uns, neue Eltern zu finden.\n\nDu uns nehmen mit?", progress = nil, completion = "Glaubst du, sie hat schon mal ein Orakel gesehen? Wir vielleicht das erste, das sie jemals getroffen hat! Wir glauben, sie hat uns gemocht, aber wir nicht sicher. Sie nicht redet viel. Nee. Aber hat Spaß gemacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13955] = {title = "Die Drachenkönigin", objective = "Nehmt Euer Waisenkind, Kekek, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Kekek hat Drachen immer gemocht. Wollte immer einer sein, aber Waisendame hat nein gesagt. Aber sie hat gesagt, dass vielleicht du Kekek zur Drachenkönigin bringen kannst.\n\nKekek glaubt, Waisendame hat einmal eine gute Idee. Du bringst Kekek zum Wyrmruhtempel in der Drachenöde? Fliegen ganz hoch bis zur Spitze, um Drachenkönigin zu sehen. Sie muss riesig groß sein, damit sie Königin von allen Drachen ist. Kekek kann es gar nicht erwarten, sie zu sehen!", progress = nil, completion = "Die Königin war nicht, was Kekek erwartet hat, aber Kekek versteht warum. Die Besucher von Königin werden zerquetscht, wenn sie immer großer Drache ist! Trotzdem, will das irgendwann mal sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13956] = {title = "Einen Großen treffen", objective = "Nehmt Euer Waisenkind, Roo, und besucht den Etymidian auf der Terrasse des Formers. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Hochorakel Soo-say erzählt uns immer, wie die Großen Schreine gebaut haben und wir ihnen Glitzer-Glitzer geben, aber er hat Große nie gesehen. Niemand hat Große gesehen, vielleicht weißt du, wo wir einen finden?\n\nSoo-say erzählt uns, die Großen haben ein Tor gebaut und es in die Mitte vom Süden von Sholazar gestellt. Soo-say sagt nicht, wo es hinführt, aber vielleicht er führt zu einem Großen! Bringt uns durch das Tor, damit wir es rausfinden können, <Name>.", progress = nil, completion = "Wir haben einen Großen getroffen! Nur schade, dass er geschlafen hat, aber wir verstehen. Wir schlafen auch gerne! Vielleicht haben wir von Großen das Schlafen gelernt, so wie wir auch von ihnen von Schreinen und Glitzer-Glitzer erfahren haben!\n\nKönnen wir zurückkommen und den Großen noch mal besuchen, wenn er nicht schläft?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13957] = {title = "Der mächtige Hemet Nesingwary", objective = "Nehmt Euer Waisenkind, Kekek, und besucht Hemet Nesingwary in Nesingwarys Basislager. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", description = "Weißt du, wen Kekek immer schon mal treffen wollte? Hemet Nesingwary.\n\nVielleicht kannst du Kekek mitnehmen, um ihn zu sehen? Der Älteste Harkek hat uns alles von ihm erzählt. Er kommt nach Sholazar, um die größten Tiere weit und breit zu jagen! Sogar Älteste der Wildherzen respektieren Hemet Nesingwary als großen Jäger.\n\nDer Älteste Harkek hat Kekek erzählt, dass Nesingwarys Basislager in der Mitte der Westseite von Sholazar, beim Fluss, der Meeresklammstrom genannt wird. Können wir ihn besuchen und lernen, wie man wie Hemet jagt?", progress = nil, completion = "Hilfst du Kekek, ein Buch zu lernen? Dann kann Kekek jagen mit Hemet Nesingwary!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13958] = {title = "Kritischer Zustand!", objective = "Goggath will, dass Ihr das Schlachttriagenverbandsset zu Thagg beim Rajenbaum bringt.\n\nBereitgestellter Gegenstand: \n", description = "Wir halten den Feind gut auf Trab. Der Sieg rückt immer näher!\n\nAber es ist noch nicht Zeit zum Feiern, <Klasse>. Es bleibt noch viel zu tun, bevor die Horde das Eschental für sich beanspruchen kann.\n\nBeim Rajenbaum im Osten hat eine Schlacht begonnen. Berichten zufolge sind viele Mitglieder der Horde verwundet.\n\nBringt diese Heilvorräte dorthin und übergebt sie an Thagg. Erzählt ihm von unserem Angriff auf Astranaar. Vielleicht fördert es den dortigen Kampfgeist.", progress = nil, completion = "&lt;Thagg hört aufmerksam zu, während Ihr ihm von Eurem Angriff auf Astranaar berichtet.&gt;\n\nDas sind in der Tat gute Nachrichten, &lt;Volk&gt;. Aber im Moment brauchen wir hier etwas mehr als nur gute Nachrichten.\n\nDieses Schlachttriagenverbandsset können wir hier gut gebrauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13959] = {title = "Zurück zum Waisenhaus", objective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Orakelwaisenkindes überreicht.", description = "Wir viel Spaß mit dir hatten, <Name>. Wir uns wünschen so sehr, du könntest <unser Papa/unsere Mama> sein, aber du uns jetzt zur Waisenmatrone Aria in Dalaran zurückbringen musst.\n\nDu uns vielleicht irgendwann wieder besuchen kommen? Es toll war, Winterflossenjungen zu treffen und Drachenkönigin zu sehen. Es uns wird keiner glauben, dass wir einen Großen getroffen haben!\n\nWir dich werden vermissen, <Name>. Wir versprechen, dir mal einen Brief zu schreiben, oki?", progress = nil, completion = "Hört sich an, als hätte der kleine Roo diese Woche viel Spaß gehabt. Ich weiß, dass er sehr einsam war im Waisenhaus und unbedingt ein paar neue Freunde finden wollte. Vielen, vielen Dank, dass Ihr Euch um ihn gekümmert habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSignal to Despawn Orphan\n\nIhr bekommt:\n\nNeugieriges Gorlocjunges\n\nIhr bekommt außerdem zugemailt: Neugieriges Gorlocjunges"}
MultiLanguageQuestData['de'][13960] = {title = "Zurück zum Waisenhaus", objective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Wolvarwaisenkindes überreicht.", description = "Weißt du was? So schlecht bist du gar nicht, <Name>. Du nimmst Kekek mit zu Orten, an denen was los ist. Kekek trifft viele neue Freunde und macht Dinge, die kein anderer Welpe macht.\n\nDu und Hemet Nesingwary und Schneewehenwelpen alle neue beste Freunde. Vielleicht du irgendwann das Grünehügelbuch bringen? Kekek verspricht, dir auch ab und zu zu schreiben, um zu sagen, wie die Dinge stehen. Vielleicht sogar nett sein zu Großzungenkindern.\n\nKekek muss jetzt zur Waisenmatrone Aria zurückkehren, zurück in Lilaleutestadt.", progress = nil, completion = "Habt Dank dafür, dass Ihr Euch bereit erklärt habt, diese Woche auf Kekek achtzugeben. Ich weiß, er kann etwas anstrengend sein, aber ich glaube, dass er durch etwas mehr individuelle Zuwendung und einen etwas größeren Freundeskreis große Fortschritte machen könnte. Ohne Zweifel wird er noch wochenlang von seinen Abenteuern mit Euch erzählen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSignal to Despawn Orphan\n\nIhr bekommt:\n\nNeugieriger Wolvarwelpe\n\nIhr bekommt außerdem zugemailt: Neugieriger Wolvarwelpe"}
MultiLanguageQuestData['de'][13961] = {title = "Quetscht sie aus", objective = "Verwendet Grol'doms Netz, um einen Plünderer der Klingenmähnen zu fesseln und schleppt ihn zurück zu Togrik auf Grol'doms Hof.", description = "Es entspricht unserem Instinkt, einfach auf unsere Angreifer wie wild einzudreschen, aber die Weisheit gebietet einen anderen Weg. Wir sollten einen dieser Eindringlinge der Stacheleber befragen und so viel wie möglich herausfinden. Nehmt dieses Netz, <Name>, und fesselt einen Plünderer der Stacheleber, der unseren Hof westlich von hier angreift. Schlagt die Bestie bewusstlos und bringt sie zu mir.", progress = "Springt mit unserem Gefangenen nicht all zu wild um. Um die Fragen beantworten zu können, muss er seinen Kopf auf dem Rumpf behalten.", completion = "Oje. Dieser Stacheleber sollte verhört werden, nicht weichgeklopft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13962] = {title = "Pattsituation", objective = "Thagg im Rajenbaum will, dass Ihr Bewahrer Ordanus tötet.", description = "Die Triagenverbandssets werden uns helfen, den Kampf weiterzuführen, aber wir befinden uns in einer Pattsituation.\n\nDie Dryaden sterben relativ schnell, aber ihr Anführer lässt sie kurz nach ihrem Fall immer wieder auferstehen. Wir stehen einem endlosen Strom dieses Ungeziefers gegenüber!\n\nBewahrer Ordanus versteckt sich in diesem mutierten Baum. Unsere Bemühungen, uns bis zu ihm durchzukämpfen, waren bisher vergeblich. Vielleicht könntet Ihr zu ihm gelangen, während wir mit seinen Dryaden kämpfen...\n\nDas ist sicherlich ein Kinderspiel für jemanden, der Astranaar erobert hat. Nein?", progress = nil, completion = "Sehr gut, &lt;Name&gt;.\n\nIhr habt vollbracht, was mir nicht gelungen ist. Ihr habt meine Achtung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13963] = {title = "Jedes Mittel ist recht", objective = "Verhört den Gefangenen der Klingenmähnen. Falls er nicht dort oder bewusstlos ist, kann Togrik ihn für Euch wiederbeleben.", description = "Ich schätze, ein Schwung kaltes Wasser wird ihn wieder zu Bewusstsein kommen lassen. Was glaubt Ihr, wird er uns mitzuteilen haben?\n\nIch nehme ihn in dem Viehstall hinter mir in Gewahrsam. Ich glaube nicht, dass er lange bewusstlos bleiben wird. Findet so viel heraus, wie Ihr könnt bezüglich der Frage, warum die Stacheleber unsere Höfe angreifen! Die Befragungsmethoden überlasse ich Euch.", progress = nil, completion = "Sehr interessant – diese Biester scheinen jemanden zu kennen, der 'Tortusk' heißt und der sie bezaubert und verängstigt. Er ist ein mächtiger Anführer, der sein Volk sowohl zu Heldentaten als auch zu Gräueltaten zu bewegen vermag... Aber wir Orcs können das besser nachvollziehen als alle anderen.\n\nWir sollten unsere Aufmerksamkeit auf diesen Tortusk richten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13964] = {title = "Zum Turm", objective = "Sprecht mit Schildwache Velene Sternenschlag auf der Sternenstaubspitze.", description = "Wir haben die Silberwindzuflucht verloren! Alles, was ich weiß, ist, dass es einen Überraschungsangriff der Horde gab und dass sie irgendwie die Elementarwächter des Mystralsees gegen uns aufgebracht haben.\n\nDie Überlebenden sind bis zur Sternenstaubspitze zurückgefallen. <Name>, sie benötigen Eure Hilfe.\n\nBegebt Euch nach Südsüdost. Dort findet ihr den Turm am Eingang des Steinkrallenpasses, der Euch in das Steinkrallengebirge führt. Ich bin mir sicher, dass Ihr dort Schildwache Velene Sternenschlag findet, die dort den Gegenschlag unterstützt.", progress = nil, completion = "Freut mich, Euch endlich kennenzulernen, &lt;Name&gt;. Ich kenne alle Eure Heldentaten und lasst mich Euch sagen, dass ich beeindruckt bin!\n\nGlaubt Ihr, dass Ihr uns Eure Kundigkeit zur Verfügung stellen könntet?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13965] = {title = "Schaut nach den Edunes", objective = "Sprecht mit Benjari Edune im Haus von Edune im Eschental.", description = "<Name>, falls Ihr einen Augenblick erübrigen könnt, würde ich gerne Eure Hilfe in einer kleinen Angelegenheit in Anspruch nehmen.\n\nIch habe schon längere Zeit nichts mehr von meinen Freunden den Edunes gehört. Ich frage mich, ob Ihr auf einen Sprung nach Westen bei ihnen vorbeischauen könnt?\n\nIch danke Euch. Ihr Landhaus liegt auf einem kleinen Grundstück westlich des Schreins von Aessina.", progress = nil, completion = "Ihr sagt, Faldreas schickt Euch? Guter Mann.\n\nWie es der Zufall will, könnten wir Eure Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13966] = {title = "Ein Winterhauchgeschenk", objective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, <Name>!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWinterhauchgeschenk"}
MultiLanguageQuestData['de'][13967] = {title = "Beim Ausdünnen der... Rotte?", objective = "Senani Donnerherz in der Silberwindzuflucht will, dass Ihr Euch 15 Furbolgohren von Totemikern der Fäulnisklauen und Ursa der Fäulnisklauen holt.", description = "Die Furbolgs sind zahlreicher, als wir es in diesen südlichen Gefilden erwartet hatten. Sie sind hier auch viel aggressiver, als wir es gerne hätten.\n\nWir müssen unsere Kräfte aufteilen, denn wir müssen Elfen jagen und gleichzeitig das dringend benötigte Holz schlagen. Das bedeutet, dass Ihr mir helfen müsst, die Belästigung durch die Furbolgs zu beenden.\n\nIch muss hier Forschungen durchführen. In der Zwischenzeit brauche ich Euch für eine etwas tatkräftigere Aufgabe. Bringt mir die Ohren der Furbolgs in der Nähe. Sie sollen Tarkan beweisen, dass wir das Problem in Angriff nehmen.", progress = "Und, <Name>.\n\nIst es vollbracht?", completion = "Gute Arbeit, &lt;Volk&gt;!\n\nJetzt sollten sie eine Zeitlang ihre Wunden lecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13968] = {title = "Tortusks Untergang", objective = "Tötet den Anführer der Klingenmähnen Tortusk.", description = "Im Windschatten des Chaos' im Süden scheint dieser Schläger 'Tortusk' alle Flüchtlinge der Klingenmähnen unter seinem Banner versammelt zu haben. Unter seiner Führung verwandeln sie sich in dreckige, kleine Briganten. Mit dieser Sorte lässt sich nicht verhandeln. Tortusk muss vernichtet werden.\n\nWenn man unserem Gefangenen Glauben schenken kann, findet Ihr Tortusk südöstlich von hier an einem Ort namens Dornenhügel. Durchsucht die Felsen nach einer Stelle, von wo aus er einen guten Überblick über die Straße hat. Tötet ihn, <Name>, und die unmittelbare Gefahr wird weichen.", progress = nil, completion = "Ah, Tortusk hat sich also genauso verhalten, wie ich es vorhergesagt habe? Er sprang Euch direkt an die Gurgel? Es ist gut, dass er tot ist.\n\nDie Stacheleber der Klingenmähnen wurden von ihrer Führung im Südlichen Brachland getrennt. So ein Tier wie er sollte solche Macht zweifellos nicht besitzen. Vielleicht können wir ohne seinen Einfluss in einen Dialog mit den Überlebenden treten... Obwohl dort vielleicht auch hitzige Gemüter vorherrschen.", rewards = "Zauberstab der TrennungEberjägerstiefelTogriks BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13969] = {title = "Wo sind Grol'dom Kodos?", objective = "Findet den vermissten Kodo von Grol'dom irgendwo auf dem Dornenhügel im Nördlichen Brachland.", description = "Wenn Ihr nach Süden zum Dornenhügel reist, frage ich mich, ob Ihr unsere fehlenden Kodos ausfindig machen könntet? Nicht jede Karawane hat es über den Pass der Fernwacht geschafft. Diese Schläger der Klingenmähnen haben gestern Morgen ein Packtier entführt. Vielleicht ist es nicht mehr am Leben, aber falls es noch nicht tot ist, können wir es uns nicht leisten noch mehr Vieh zu verlieren.", progress = nil, completion = "Dieser mitgenommene Kodo steht mit drei Beinen im Grab, aber er atmet noch. Die Klingenmähnen haben seine Fracht noch nicht ausgeplündert. Falls er wiederbelebt werden kann, könntet Ihr vielleicht die gesamte Ladung retten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13970] = {title = "Tierpflege", objective = "Sammelt 5 Säcke gestohlenes Getreide aus den Lagern der Klingenmähnen auf dem Dornenhügel.", description = "Kodos sind zähe Kreaturen. Mit ein wenig Nahrung bekommen wir den Dicken vielleicht wieder auf die Beine.\n\nDie Klingenmähnen haben reichlich Getreide von früheren Karawanen geraubt. Ihr könnt das gestohlene Getreide in den nahegelegenen Lagern einsammeln.", progress = "Die Kreatur hebt ihren Kopf nicht, aber sie sieht Euch mit großen und flehenden Augen an, in denen sich das Wasser sammelt.", completion = "Der Kodo ist unersättlich! Ihr hättet die Säcke genauso gut in ein großes Loch schütten können!\n\nDas Tier wird bereits wieder munter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13971] = {title = "Die Rückkehr des Kodos", objective = "Sprecht mit Kranal Fiss auf Grol'doms Hof, um Euch zu versichern, dass sein vermisster Kodo heil angekommen ist.", description = "Das riesenhafte Reptil erhebt sich langsam, stellt sich auf die Beine, die lose Erde des Brachlandes rieselt von seinen Gliedmaßen, in die das Leben zurückgekehrt ist. Instinktiv stapft das Tier zurück zu seinem Zuhause auf Grol'doms Hof.\n\nIhr wollt sicher mit Kranal Fiss sprechen, um sicherzugehen, dass es der Kodo geschafft hat.", progress = nil, completion = "Das war Euer Werk, &lt;Volk&gt;? Ja, der vermisste Kodo ist vor ein paar Minuten eingetroffen. Es wird vieler Nächte bedürfen, die Wunden der bemitleidenswerten Bestie zu versorgen, aber dank Euch ist sie noch am Leben. Und Ihr habt die gesamte Fracht gerettet!\n\nBitte sucht Euch etwas von der Ausrüstung aus, die der Kodo transportiert hat.", rewards = "FernwachtmusketeImportierte ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13973] = {title = "Grol'doms Miliz", objective = "Tötet 6 Plünderer der Klingenmähnen.", description = "Sie sind aus dem Nichts gekommen, <Klasse>! Stacheleber wo man auch hinsieht. Borsten, Schnauzen und Hauer. Wir haben uns auf den Hof zurückgezogen, aber es kamen immer mehr.\n\nUnsere besten Verteidiger sind auf dem Schlachtfeld gefallen und wir haben kein Lebenszeichen von Bauer Ralton. Ihr müsst sie für mich angreifen! Haltet mir diese Schweine vom Leib, während ich die Verwundeten verteidige, bis Hilfe eintrifft.", progress = "Ich sehe Rauch aus dem benachbarten Gebäude aufsteigen – was geht da draußen vor sich?", completion = "Ich sehe, Ihr habt Euren Weg mit Leichen gepflastert, &lt;Volk&gt;. Ich hätte es nicht besser machen können. Das Vieh ist vielleicht verloren, aber das Land bleibt das unsrige – dank Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13974] = {title = "Twidels winziges Paket", objective = "Twidel möchte, dass Ihr Twidels winziges Paket zu Flooz in der Silberwindzuflucht bringt.\n\nBereitgestellter Gegenstand: \n", description = "Woohoo!!\n\nSchaut nur, wie das brennt! Es ist revolutionär! Ein echter Durchbruch in der Explosionstechnik! Und das ist natürlich die einzige Technik, die zählt.\n\nAlle Goblins südlich von Nordend werden mich bewundern und beneiden!\n\nUnd ob Ihr es glaubt oder nicht, ich habe noch ein wenig an der Zusammensetzung gedreht, um sogar noch mehr Leistung herauszuholen!\n\nHier. Nehmt eine Probe dieses Zeugs und bringt sie nach Südosten in die Silberwindzuflucht. Mein Vetter Flooz kann es vielleicht brauchen, um die Horde bei der Eroberung dieses Ortes zu unterstützen.", progress = nil, completion = "Na sieh mal einer an! Der kleine Twidel hat es diesmal echt geschafft. Das Zeug hat Astranaar in die Luft gejagt, sagt Ihr?\n\nWie Ihr seht, brauchen wir keine Hilfe, die Silberwindzuflucht zu erobern, aber Twidel war immer ein bisschen kleingeistig.\n\nWenn das Zeug wirklich so gut ist, wie Ihr behauptet, sind die Möglichkeiten endlos...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlooz Interrupt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13975] = {title = "Die Karawane zum Wegekreuz", objective = "Sprecht mit Rocco Peitschschwinger in Grol'doms Hof und begleitet seine Karawane den gesamten Weg zum Wegekreuz.", description = "<Rocco überreicht Euch eine Schrotflinte, die Euch bekannt vorkommt.>\n\nIch habe mir erlaubt, Halgas Artillerie für Euch zu reinigen. Ich bin mir sicher, dass ich Euch nicht vor dem Rückstoß zu warnen brauche. Fragt mich einfach, wenn Ihr bereit seid, zum Wegekreuz aufzubrechen! Thork wartet dort auf Euch. Achtet darauf, dass Ihr ihm nicht pampig kommt.\n\nLasst Euch von nichts aufhalten, <Name>, und wenn Euch jemand zu nahe kommt, versetzt ihm einfach einen Stoß mit dem Kolbenende Eurer Schrotflinte. Macht uns stolz!", progress = "Wart Ihr der Jemand, den ich mit einer Schrotflinte am Ende meiner Karawane herumfuchteln sah?", completion = "Es wurde aber auch Zeit, dass ein paar Vorräte bis hierher durchkommen. Es ist schlimm genug, von Mulgore abgeschnitten zu sein, aber diese Stadt würde in die Binsen gehen, wenn wir unseren Handel mit Orgrimmar verlören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13976] = {title = "Drei Männlein steh'n im Walde", objective = "Sprecht mit Bolyun in Bolyuns Lager im Eschental.", description = "Habt Ihr Lust auf einen kurzen Abstecher in den Süden? Ich habe drei Freunde, von denen ich schon länger nichts gehört habe. Diese seltsamen Tentakel treten im Norden aus dem Boden hervor und bei all der dämonischen Aktivität wage ich es nicht, meine Familie alleinzulassen.\n\nBolyun hat sein Lager in der südwestlichen Ecke dieses Waldes aufgeschlagen - genau im Nordwesten dieses verdammten Schreins des Sengenden Feuers. Alenndaar und Harlown haben sich ihm angeschlossen, also müsste es ihnen eigentlich gut gehen, aber man kann nie wissen.\n\nHabt Dank, <Name>.", progress = nil, completion = "&lt;Klasse&gt;, Ihr müsst achtsam sein! Kaliva die üble Dämonin, die uns angekettet hat, ist in der Nähe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13977] = {title = "Massenproduktion", objective = "Flooz möchte, dass Ihr Twidels Bumm-Bumm-Pulver zu Jinx in den Stinkwerken bringt.", description = "Woohoo!! Habt Ihr das GESEHEN?!\n\nDamit müssen wir sofort in Produktion gehen.\n\nHier, bringt den Rest von diesem Zeug zu Jinx. Er richtet gerade unseren neuen Standort westlich von hier ein.", progress = "Was habt Ihr da, Boss?", completion = "&lt;Jinx untersucht das Pulver einen Augenblick lang sorgfältig.&gt;\n\nHmmm.\n\nIch brauche ein wenig Zeit. Aber ja, wir können das in eine Bombe packen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13979] = {title = "Das Expertengremium der Goblins", objective = "Holt Euch Splodiers Kopf.", description = "Wenn wir die verdammten Bombenangriffe durch diese Goblinmachwerke stoppen könnten, wären wir in der Lage, einen Gegenangriff zu starten und die Silberwindzuflucht zurückzuerobern!\n\nMeiner Erfahrung nach sind Goblins entweder faul oder unproduktiv, oder so eifrig, dass sie sich mit ihrem Sprengstoff schließlich selbst in die Luft jagen. Zu unserem Unglück werden sie von dem genialen, leitenden Bombentechniker Splodier angeführt.\n\nBegebt Euch in die Stinkwerke an der Westseite der Zuflucht und kehrt nicht zurück, bis Ihr den Kopf des leitenden Bombentechnikers in Händen haltet.", progress = "Habt Ihr den widerwärtigen, verwarzten Goblin zum Schweigen gebracht?", completion = "Das ist gut. Ohne ihn fallen ihre Techniker sicher wieder zurück in ihre alten Gewohnheiten, was zu weniger Bomben und mehr Unfällen führen wird.", rewards = "Weste des BeraterstabsStinkwerkschwertAuf Euch wartet eine dieser Belohnungen:\n\nJalins Entschädigung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13980] = {title = "Sie sind da draußen!", objective = "Jinx in den Stinkwerken möchte, dass Ihr 12 Assassinen des Eschentals tötet.", description = "Sie sind da draußen, <Klasse>. Und sie sind uns auf den Fersen.\n\nEinige meiner Männer wurden tot aufgefunden. Elfenangriffe, ohne Zweifel.\n\nIch glaube, dass sie wegen Eurer Arbeit in Astranaar versessen darauf sind, unserem Fortschritt hier Einhalt zu gebieten. Ein letztes Aufbäumen vor der Niederlage!\n\nNehmt diese Brille. Sie hilft Euch dabei, auch den am besten getarnten Elf zu erkennen. Haltet sie mir vom Leib, während wir unsere Waffe für Euch vorbereiten.", progress = nil, completion = "Gute Arbeit, Freund.\n\nEure Fähigkeiten haben uns die nötige Zeit verschafft, um die Bombe vorzubereiten. Sie ist fast fertig!", rewards = "Waffenfähiger GürtelAuf Euch wartet eine dieser Belohnungen:\n\nRing der Rückendeckung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13981] = {title = "Bombenlieferung gefällig?", objective = "Berichtet Jägerin Jalin auf der Sternenstaubspitze im Südwesten des Eschentals von der Existenz der Bombe.", description = "Das ist sicherlich die größte Sprengstoffladung, die Ihr je zu Gesicht bekommen habt. Was in aller Welt würden die Goblins mit so einem Monstrum bombardieren wollen?\n\nSoweit Ihr das beurteilen könnt, ist das Werk fast vollendet. Die Goblins scheinen den Sprengsatz gut konstruiert zu haben. Es sieht so aus, als ob er gut geschützt ist gegen jeden Schaden, den Ihr ihm zufügen könntet. Und die Bombe ist sicherlich zu groß, als dass Ihr sie von hier forttragen könntet.\n\nIhr solltet die Bombe besser Jägerin Jalin auf der Sternenstaubspitze im Südwesten melden!", progress = nil, completion = "Sie haben was? SIE IST WIE GROSS?!!!\n\nDas hört sich gar nicht gut an, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDetect: Quest Invis Default\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13982] = {title = "In Ketten gelegt", objective = "Beschafft Kalivas Herz.", description = "<Name>, Ihr müsst vorsichtig sein. Kaliva ist noch immer in der Nähe und als sie uns gefangen nahm, erwähnte sie ganz besonders Euren Namen.\n\nNur ihr Herz kann uns von diesen Ketten befreien, aber ich glaube, dies alles ist eine Falle nur für Euch!", progress = "Um freizukommen, brauchen wir Kalivas Herz.", completion = "Es ist ekelerregend, ich weiß, aber wenn wir drei diese Ketten von Kaliva loswerden wollen, reicht es nicht, dass sie tot ist.\n\nWir müssen von ihrem teuflischen Herzen essen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIn a Bind: See Invisibility Switch 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13983] = {title = "Baut Euren eigenen Sarg", objective = "Vorarbeiter Jinx möchte, dass Ihr 3 Bronzeräder, 3 Stück Kupferbeschlag und 5 Klemmbolzen sammelt.", description = "Sobald sie fertig ist, müssen wir die Bombe zu Saurboz schaffen.\n\nUnd mit 'wir' meine ich 'Ihr'.\n\nBei all den Feinden, die sich hier herumtreiben, muss ich etwas ganz Besonderes bauen, wenn Ihr mit dieser Aufgabe Erfolg haben wollt.\n\nIch könnte einen dieser kaputten Schredder umbauen, aber dazu brauche ich ein paar Teile. In den Wäldern im Westen solltet Ihr eigentlich alles problemlos finden.\n\nBeschafft mir die Teile, während ich die Bombe fertig baue.", progress = "Habt Ihr die Teile, die ich brauche, Freund?", completion = "Das sieht gut aus, &lt;Klasse&gt;.\n\nEuer Schredder sollte im Handumdrehen bereit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13985] = {title = "Leert den Schrein", objective = "Vernichtet 12 beliebige Dämonen am Schrein des Sengenden Feuers.", description = "Dem Bösen dieser Brennenden Legion muss ein Ende gesetzt werden!\n\n<Name>, Ihr habt einen ihrer Mächtigsten besiegt, aber es gibt noch immer zahlreiche Dämonen, die die Wälder im Osten im Schrein des Sengenden Feuers verseuchen.\n\nWerdet Ihr als ein Freund des Waldes diese Kreaturen vernichten und dann den Großen Baobob, das große Urtum des Krieges am Schrein von Aessina im Nordosten warnen?", progress = nil, completion = "Das war gute Arbeit, &lt;Volk&gt;. Aber Ihr seht, dass ich hier ein wenig beschäftigt bin.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13986] = {title = "Ein verletzter Kollege", objective = "Bringt Aponi Lichtmähne auf der Anhöhe der Ältesten in Donnerfels den ramponierten Stammesschild.", description = "Es war ein harter Kampf hier oben, <Klasse>, wie Ihr sicher wisst. Wir harren aus, doch ist nicht jeder unversehrt geblieben.\n\nEine der Kriegerinnen unserer Gruppe, Aponi Lichtmähne, leidet an einer infizierten Wunde an ihrem Arm. Sie wurde zur Erholung nach Donnerfels zurückgebracht. Es scheint jedoch, als hätte sie in der ganzen Aufregung ihren Schild hier an der Front vergessen - könntet Ihr es ihr bringen, zusammen mit unseren Genesungswünschen? Uns fehlt ihr Lächeln hier sehr.\n\nIhr könnt sie auf der Anhöhe der Ältesten finden.", progress = "Oh! Hallo. Ich glaube nicht, dass wir uns schon kennengelernt haben. Gibt es etwas, was ich für Euch tun kann?", completion = "Oh, mein Schild! Ich werde ihn in naher Zukunft wohl nicht brauchen, aber ich danke Euch. Ich verabscheue es, hier nutzlos herumzusitzen, wenn ich an der Front helfen könnte, doch würde es niemandem helfen, wenn ich mich in den Kampf werfe, solange mein Arm in diesem Zustand ist.\n\nGebt gut auf Euch acht da draußen, in Ordnung?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13987] = {title = "Das letzte Gefecht", objective = "Tötet 30 dämonische Eindringlinge.", description = "<Name>, ich brauche unbedingt Eure Hilfe! Ich kann gegen diesen Ansturm der Dämonen nicht ewig standhalten. Wenn ich falle, ist Astranaar als Nächstes dran!\n\nBitte helft mir!", progress = "Nur noch ein paar und wir werden es schaffen.", completion = "Ihr habt uns alle gerettet, &lt;Name&gt;! Ich habe genug Kräfte, um diesen letzten Rest zu erledigen.\n\nDieser Wald wird die Brennende Legion nicht mehr länger fürchten müssen.", rewards = "Adansonischer UmhangUnberingte BänderBaobabfruchthülseDer folgende Zauber wird auf euch gewirkt:\n\nThe Last Stand: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13988] = {title = "Mit eigenen Augen", objective = "Bringt Tongas Augen zum Donnerkopfgipfel südwestlich von Ratschet.", description = "Das Leben explodiert förmlich auf diesem kargen Boden... Mein Gefährte Jerrik hat erzählt, dass sich ähnliche Dinge überall im Brachland ereignen. Ich muss es mit eigenen Augen sehen, aber ich darf meinen Posten nicht verlassen.\n\nHier, <Name>, ich werde Euch meine 'Augen' leihen. Seit dem Tag, an dem ich meinen Namen erhalten habe, hat mein Adlergefährte hier mir gut gedient. Bitte begleitet ihn zum Donnerkopfgipfel, wo Jerrik Euch erwartet und wir werden uns umsehen.\n\nUm auf die Spitze zu gelangen, folgt der Straße Richtung Osten am Wegekreuz. Wendet Euch nach Süden, sobald Ihr einen großen Stein erreicht, der mit Malereien übersät ist.", progress = "Tonga kennt dieses Land besser als wir alle, und ich glaube, es hat ihm große Schmerzen bereitet, zu sehen, wie es auseinandergerissen wurde.", completion = "Ich bin froh, dass Tonga in der Lage war, die Überwucherung aus erster Hand mitzuerleben – Wörter können das Ausmaß der Zerstörung nicht angemessen beschreiben. Habt Ihr sein Totem dabei? Ich werde es ihm wiederbringen, wenn ich hier fertig bin.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13989] = {title = "König der Fäulnisklauen", objective = "Platziert das Blutreißerbanner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören, bevor ihr Häuptling kommt. Besiegt Häuptling Murgut.", description = "Es interessiert mich herzlich wenig, wer Ihr seid, <Volk>. Worauf es mir ankommt ist die Rettung der Furbolgs.\n\nBringt dieses Blutreißerbanner das kurze Stück in Richtung Nordosten zur Laubtatzenlichtung und platziert es auf ihrem Totemhügel. Sie werden es als einen Angriff ansehen und versuchen, das Banner zu zerstören. Haltet die Stellung. Häuptling Murgut wird auftauchen, um das Gesicht des Stammes zu wahren. Wartet auf ihn und dann tötet den Verräter!\n\nTeilt Eure Kräfte gut ein. Euch steht ein langer Kampf bevor.", progress = nil, completion = "Gut. Murgut hat seinen Stamm an die Horde verkauft und sich mit ihr verbündet, als sie Eure kostbare Silberwindzuflucht eingenommen hat, um sein Volk zu 'retten'.\n\nEr hat sie in die Sklaverei verkauft – oder Schlimmeres. Und jetzt hat er bekommen, was er verdient!\n\nLasst uns nun über einen anderen Verräter sprechen. Ich glaube, er besitzt etwas, das Eurer Rute mehr Durchschlagskraft verleihen wird.", rewards = "LaubtatzengürtelAuf Euch wartet eine dieser Belohnungen:\n\nBand der Beharrlichkeit\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][13991] = {title = "Die gestohlene Lohnliste", objective = "Sprecht mit Gazrog in der Nähe des Eingangs nach Ratschet.", description = "Und, <Name>. Ich gebe zu, dass Ihr gut in meine geliebte Horde passen würdet. Ihr habt Stärke, List und Einsatz bewiesen... Sogar Thork erwähnte Euch kürzlich namentlich, und weder er noch ich sind leicht zu beeindrucken. Gute Arbeit.\n\nJetzt wird es Zeit, dass Ihr Euch weiter in die Riemen legt. Die wöchentliche Lohnliste für die Wachen des Wegekreuzes ist verloren gegangen. Gazrog in Ratschet führt eine Untersuchung an. Sprecht mit ihm!\n\nFolgt einfach der Straße von hier Richtung Osten zur Küste.", progress = nil, completion = "Ich hatte auf eine Truppe von Grunzern gehofft... Aber wenn Ihr Euch Sergras Anerkennung verdient habt, schätze ich, dass Ihr der Aufgabe mehr als gewachsen seid. Lasst mich erklären, was hier geschehen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13992] = {title = "Eine kleine Ablenkung", objective = "Tötet 8 Zentauren der Kolkar.", description = "Ich wurde hierher geschickt, um die Aktivitäten der Zentauren auszukundschaften. Ich habe all ihre Bewegungen seit Tagen beobachtet! Es wird Zeit für mich, mich wieder davonzuschleichen, aber sie haben diesen Ort umzingelt.\n\nIhr seht aus, als ob Ihr gefährlich seid. Könnt Ihr ein wenig Chaos für mich veranstalten? Sie aufwühlen! Metzelt sie wahllos nieder. Während sie nach Euch suchen, schleiche ich mich davon, um meinen Bericht an Regthar Totenfurt zu überbringen.", progress = nil, completion = "Oh ho! Das war wunderbar. Ich hätte vermutlich nicht bleiben und zusehen dürfen. Jetzt suchen sie nach Euch. Ich stehle mich im Staub ihres ziellosen Herumgaloppierens heimlich davon.\n\nHaltet an den anderen Teichen nach meinen Kameraden Ausschau. Der Boss hat an jedem seine Leute.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13995] = {title = "Der König vom Berge der Zentauren", objective = "Sorgt dafür, dass Gorgal Zornesnarbe am Leben bleibt, während er sich mit den Zentauren anlegt und helft ihm, Kurak zu töten.", description = "Wir wurden hierhergeschickt, um die Bewegungen der Zentauren der Kolkar zu beobachten, aber nachdem wir diesen dreckigen Tieren eine Woche dabei zugesehen haben, wie sie um die Oase galoppieren, juckt es mich, meiner Axt ihre Hälse zu schmecken zu geben. Was sagt Ihr, <Klasse>? Wollt Ihr mit mir ein wenig Chaos verbreiten?\n\nMal sehen, ob wir die Aufmerksamkeit ihres stärksten Kriegers Kurak auf uns lenken können.", progress = nil, completion = "Warum musstet Ihr Gorgal denn so verärgern? Das Ergebnis gibt Euch allerdings recht. Wir müssen diese Tiere weiterhin gut beobachten, um zu sehen, was sie tun, jetzt wo Kurak aus dem Weg geräumt ist.\n\nAlso weiter beobachten, abwarten und Tee trinken. Gorgal wird das nicht mögen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13997] = {title = "If You're Reading This While I'm In Combat...", objective = "ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!", description = "Dan is the most awesome programmer in the world... the World of Warcraft!\n\nIsn't it weird that you used to not be able to talk with me at all while I was fighting? No longer, my friend, now that Dan has made significant improvements to one of my creature flags!\n\nCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][13998] = {title = "Operation Pilzkultur", objective = "Pflanzt eine Pilzkultur in der Nähe der Brackigen Oase und beobachtet das Ergebnis.", description = "Wir haben diese ungewöhnlichen Sporen kultiviert, die Ihr ausgegraben habt. Das gelang mir mit einer wundervollen Mischung aus... Reagenzien... auf die ich sehr stolz bin. Ich kann es nicht erwarten, zu sehen, wie meine manipulierten Sporen auf die Gewässer in den Oasen am Wegekreuz reagieren.\n\nDie Brackige Oase im Südosten bietet uns eine unverseuchte Region für unsere Experimente. Sät diese Kulturen in der feuchten Erde irgendwo in der Nähe der Oase für mich aus und dokumentiert die Ergebnisse.\n\nAchtet darauf, dass Ihr Euren Mund bedeckt, <Klasse>.\n\n<Helbrim grinst entwaffnend.>", progress = nil, completion = "Explosive Sporenwolken? Was Ihr nicht sagt... Erzählt mir mehr. Erstickung? Stechen? Brennen in den Augen? Hat es gejuckt? Übelkeit? Krankheit? Entzückend, ENTZÜCKEND! Ihr habt Euch Eure Bezahlung redlich verdient, &lt;Name&gt;.\n\nUnd Euer Hautausschlag müsste eigentlich in ein oder zwei Tagen wieder weg sein.", rewards = "Flauschige HandschuheSalbenbedeckte ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][13999] = {title = "Wer hat meinen Zauberpilz gegessen?", objective = "Bringt Helbrims Forschungsergebnisse zu Sashya in Ratschet im Nördlichen Brachland.", description = "Stellt Euch mal vor, was wir damit anstellen können, <Name>! Schnellwachsende Pilze, die jedes beliebige Gift übertragen können. Meine Gefährten in der Unterstadt wird das sicher interessieren.\n\nHier sind meine Aufzeichnungen und ein paar Proben. Wenn wir schnell sind, erwischen wir das nächste Schiff, das in Richtung der Östlichen Königreiche in See sticht. Nehmt die Straße östlich von hier und folgt ihr zur Goblinstadt Ratschet. Sucht nach der Taverne 'Zum geborstenen Kiel' im Südteil der Stadt und übergebt dies an meinen Mitarbeiter Sashya.", progress = "Wer seid Ihr? Hat Helbrim Euch gesandt? Verhaltet Euch unauffällig.", completion = "Ruhe! Gebt mir die Aufzeichnungen. Ist Euch jemand gefolgt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14001] = {title = "Rettungskapseln der Goblins", objective = "Rettet 6 überlebende Goblins.", description = "<Name>, es tut mir leid. Ich dachte, Ihr wärt tot!\n\nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.\n\nWir müssen unsere Brüder und Schwestern retten.\n\n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>\n\nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer hinausschwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.\n\nLasst Sassy wissen, dass ich gleich losschwimme.", progress = nil, completion = "Oh, dem Himmel sei Dank, dass Ihr überlebt habt, &lt;Name&gt;! Ich war mir so sicher, dass Ihr ertrunken seid, nachdem ich Euch über Bord habe gehen sehen.\n\n\n\nSchaut nur, wie viele Leute Ihr gerettet habt!\n\n\n\nDas habe ich ja fast vergessen. Ich habe ein paar Eurer Sachen aufgehoben. Nur für den Fall, dass Ihr es schafft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14003] = {title = "Wie man ein Samophlang repariert", objective = "Bringt das zerbrochene Samophlang hinüber zu Brak Polterrohr innerhalb des Lagers.", description = "Nun, das lief leider nicht so, wie erwartet. Ich glaube, ich habe es kaputt gemacht.\n\nAber kein Grund zur Panik. Tut mir einen Gefallen und folgt diesem Weg zu Brak hier im Lager. Er dengelt dieses Ding schnell wieder in die richtige Form!", progress = "Sagtet Ihr... Samophlang!?", completion = "Stotterspritter hat uns ein Samophlang beschafft? Lasst mich das Ding mal sehen!\n\nJupp, das kriegen wir wieder hin. Kein Problem. Reicht mir den großen Hammer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14004] = {title = "Bringt das Samophlang zurück", objective = "Bringt das Wrack des überarbeiteten Samophlangs zurück zu Stotterspritter in Düsentopfs Außenposten. Sprecht mit Wenikee, um direkt dorthin teleportiert zu werden.", description = "Nun, das hat nicht funktioniert. Ich habe ein paar zusätzliche Anzeigegeräte an dem Samophlang angebracht, die seine strukturelle Integrität messen. Sie zeigen stets einen absoluten Tiefstand an. Ich könnte einige Wählscheiben und vielleicht einen Hebel oder zwei hinzufügen und versuchen, es zu reparieren, aber... Ich glaube, das könnte alles nur noch schlimmer machen.\n\nSeht mal, was ich entdeckt habe, als ich das Ablassventil blockiert habe und die Ummantelung des Differentialgehäuses abgeflogen ist: das persönliche Gravurzeichen von 'Boss Kupferdraht'. Bringt dies zurück zu Stotterspritter und sagt ihm, er soll dieses Genie Kupferdraht auftreiben.", progress = "Ist das mein Samophlang? Es ist kaum wiederzuerkennen.", completion = "Was hat Wenikee gesagt? Kupferdraht? BOSS Kupferdraht? Oh je, das könnte sich als kompliziert erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14005] = {title = "Elunes Rache", objective = "Nutzt die Macht, die Tarindrella Euch gewährt hat, um Euch zum Herz der Verderbnis durchzukämpfen und es zu zerstören.", description = "Während Teldrassil sich selbst von der Verderbnis reinigt, welche sein Wachstum all die Jahre entstellt hat, hat sich südlich von hier am Rand des Baumes eine bösartige Wucherung gebildet. Wir haben die Möglichkeit, anzugreifen und die Quelle des Teufelsmooses, das die Knarzklauen, die Bäumlinge und alles andere verdorben hat, zu säubern.\n\nMit dem Wasser, das Ihr in den Mondbrunnen gesammelt habt, und der erneuerten Kraft von Teldrassil selbst kann ich Euch eine kurze Zeit große Macht gewähren. Setzt der Verderbnis ein Ende, <Name>.", progress = nil, completion = "Elune sei gepriesen!\n\nAlles, worauf ich gestoßen bin, deutet darauf hin, dass die Verderbnis tief in Teldrassil selbst vergraben liegt... Ich hatte schon befürchtet, wir würden die Quelle niemals angreifen können, ohne den Weltenbaum dabei zu töten. Ich bin so dankbar, dass ich falsch lag!\n\nDiese günstige Wendung des Schicksals haben wir Malfurion zu verdanken. Vielleicht werde ich ihn aufsuchen, bevor ich wieder in die Wildnis aufbreche.\n\nVielen Dank, &lt;Name&gt;. Danke für alles, was Ihr getan habt. Sicherlich werdet Ihr eines Tages ein großer Held sein!", rewards = "Unverderbte HändeKniehosen des sich wendenden SchicksalsBelebende HandgelenksschützerHaltbares TuchDer folgende Zauber wird auf euch gewirkt:\n\nCancel Vengeance of Elune\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14006] = {title = "Lest das Handbuch", objective = "Sammelt die Teile des Samophlanghandbuchs ein.", description = "Damals, als ich noch in der Tüftlerverbindung war, war Boss Kupferdraht der beste Ingenieur, den wir hatten. Er wurde abtrünnig und ging zur Venture Company, kurz bevor ich die Tüftlerverbindung verließ, und er nahm seine größten Technologien mit. Er hortete seine Geheimnisse und gab nur hier und da ein Geheimnis an den inneren Kreis seiner Vertrauten weiter.\n\nWenn er das Samophlang gebaut hat, dann besitzt er wahrscheinlich das Handbuch. Das Letzte, was ich von ihm gehört habe, war, dass er hier in der Nähe vor der Felsadermine im Nordosten arbeitet. Besorgt das Handbuch von ihm und sammelt die Seiten ein, die seine Anhänger noch haben.", progress = "Habt Ihr Kupferdraht gefunden?", completion = "Ihr habt es gefunden! Puh, es hat über 600 Seiten, und nur 30 davon wurden absichtlich frei gelassen.\n\nSehen wir uns das mal an. Kapitel drei: Rückspleißung der obenliegenden Kropfachswelle im Schwungrad-Flaschenzug? Interessant. Kapitel Sieben: Ventilsteuerung für die Hochdruck-Expansionskondensatoren!? Was für ein tolles Buch! Und ich weiß immer noch nicht, was dieses Ding macht.\n\nHier, nehmt ein paar meiner alten Werkzeuge. Lassen wir das Ding noch ein letztes Mal an!", rewards = "AltmetallschildAuf Euch wartet eine dieser Belohnungen:\n\nVeraltetes Handbuch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14007] = {title = "Zuverlässiger Schuss", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen und schießt dann dreimal auf eine Trainingsattrappe.", description = "Ich bin Bäm Megabombe, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als <Klasse> interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", progress = nil, completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14008] = {title = "Frostnova", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen und wendet den Zauber dann zweimal auf eine Trainingsattrappe an.", description = "Ich bin Zisch Zündel, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als <Klasse> interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", progress = nil, completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14009] = {title = "Das richtige Wort", objective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen, und wendet den Zauber dann dreimal auf eine Trainingsattrappe an.", description = "Ich bin Schwester Goldglanz, Eure persönliche Lehrerin, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als <Klasse> interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", progress = nil, completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14010] = {title = "Ausweiden", objective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen, und wendet es dann dreimal auf eine Trainingsattrappe an.", description = "Ich bin Slinky Scharfklinge, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als <Klasse> interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", progress = "Wann immer Ihr dazu bereit seid, mein Herr.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14011] = {title = "Urtümlicher Schlag", objective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen und wendet ihn dann zweimal auf eine Trainingsattrappe an.", description = "Ich bin Lawinus Maximus, Euer persönlicher Lehrer, <Sir/Madame>.\n\nIch habe Euren Namen hier schon mehrfach genannt bekommen, ich dachte mir, Ihr könntet vielleicht Ausbildung benötigen. Dann seid Ihr hier an der richtigen Adresse.\n\nWenn Ihr besser werdet in dem, was Ihr tut, wird es möglich sein, vollkommen neue, großartige Dinge zu tun. Vertraut mir, es funktioniert. Ich verdiene mein Geld damit, das den Leuten zu erklären.\n\nJedenfalls, verbessert Eure Fertigkeiten als Schamane und benutzt dann Eure neuen Fähigkeiten an einer der Trainingsattrappen im Südosten.", progress = "Wann immer Ihr dazu bereit seid, mein Herr.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14012] = {title = "Verderbnis", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen, dann wirkt den Zauber 3-mal auf eine Trainingsattrappe.", description = "Ich bin Bosa Blick, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als <Klasse> interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", progress = nil, completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14013] = {title = "Sturmangriff", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Führt den Angriff dann auf eine Trainingsattrappe aus.", description = "<Der Kriegomatic NX-01 schaltet sich ein.>\n\nBoss <Name> erkannt. Ich bin Kriegomatic NX-01.\n\nWarnung: Unzureichende Erfahrung erkannt! Sammelt bitte mehr Erfahrung, um weitere Fähigkeiten zu erlernen.\n\nDemonstriert neue Fähigkeiten an den Trainingsattrappen in der Nähe anwenden, um die Ausbildung fortzusetzen.", progress = "Kriegomatic NX-01 online und bereit, mein Herr.", completion = "Der Kriegomatic NX-01 ist programmiert, um zu dienen.\n\nKehrt jederzeit zurück, wenn Ihr etwas lernen wollt. Diese Einheit bringt Euch alles bei, was sie weiß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14014] = {title = "Holt unsere Sachen zurück!", objective = "Besorgt 8 Werkzeugkisten.", description = "Unsere Bomben und Werkzeuge! Diese hinterhältigen Affen aus dem Osten haben sie alle im Schutz der Dunkelheit gestohlen!\n\nKönnt Ihr dorthin gehen und sie für uns zurückholen, <Name>? Ohne diese Werkzeuge haben wir keine Chance, von dieser Insel herunterzukommen!", progress = "Bombenwerfende Affen?! Nicht auszudenken!!!", completion = "&lt;Sassy atmet beim Anblick der Werkzeuge und Bomben, die Ihr zurückgeholt habt, erleichtert auf.&gt;\n\nIch dachte, das wäre unser sicherer Untergang. Aber jetzt können wir daran arbeiten, von dieser Insel zu fliehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14016] = {title = "Der Fluch des Schwarzen Ritters", objective = "Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz möchte, dass Ihr das Grab des Schwarzen Ritters untersucht.", description = "Ich wollte die Überreste des Schwarzen Ritters nach Eurem Sieg vom Turnierplatz entfernen lassen, aber Argentumbeichtpatin Blondlocke bestand darauf, dass er ein ordentliches Begräbnis erhält. Seither hält sich eine düstere Gegenwart hartnäckig auf dem Friedhof, und niemand wagt sich mehr dorthin, um die Gefallenen zu ehren.\n\nWürdet Ihr dem Friedhof gleich außerhalb des Turnierplatzes im Osten einen Besuch abstatten und sehen, ob Ihr herausfinden könnt, was dort vor sich geht?", progress = nil, completion = "&lt;Kreuzfahrerin Rhydalla runzelt die Stirn.&gt;\n\nGlaubt Ihr, sie haben das geplant? Spielt vermutlich keine Rolle, doch es gefällt mir nicht, dass wir ihnen womöglich genau in die Hände gespielt haben. Was immer auch vor sich geht, wir müssen es vereiteln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14017] = {title = "Das Schicksal des Schwarzen Ritters", objective = "Geht nach Todessprechers Wacht, bringt Doktor Kohlers Befehle in Euren Besitz und kehrt dann zu Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz zurück.", description = "Ihr sagt, dass Kultisten die Leiche entfernt haben? Mir fällt da nur ein Ort ein, zu dem sie sie gebracht haben können: Todessprechers Wacht, das Lager auf der Anhöhe westlich des Turnierplatzes.\n\nWas auch immer die Kultisten vorhaben, man muss sie aufhalten. Die Gerüchte, die ich gehört habe, können also nur wahr sein. Der berüchtigte Doktor Kohler muss unter den Kultisten sein und seine Kunst ausüben. Sucht nach einer Anhöhe oder einem Altar, von dem aus man Sicht auf das Kultistenlager hat. Tötet den Doktor und sucht nach Beweisen über seine Machenschaften. Bremst ihn bei seiner Arbeit, egal wie.", progress = "Habt Ihr herausgefunden, was sie mit den Überresten des Schwarzen Ritters machen?", completion = "Der Doktor wird keine Zeit haben, sein Werk zu vollenden, aber sein Plan wurde schon ins Rollen gebracht. Laut Euren Berichten haben die Diener des Lichkönigs den Schwarzen Ritter wiederbelebt und mit neuer Kraft erfüllt - niemand kann sagen, was sein Meister im Schilde führt. Diese Verschwörung aufzudecken war gute Arbeit. Ich werde dem Hochmeister Adelard von Euren Funden berichten und gemeinsam werden wir die Teilnehmer des Turniers davor warnen.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14018] = {title = "Jener, der nach Vergebung sucht", objective = "Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.Die Stimme der Göttin hat am Mondbrunnen zu Euch gesprochen, <Name>. Das Heilmittel für Relara liegt im Osten beim Rajenbaumturm, der dem Verderben anheimgefallen ist.\n\nAvrus Böswisper wünscht Vergebung und Erlösung. Es liegt an Euch, ihn zu unterstützen und dabei hoffentlich auch meinem Kind zu helfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Die Stimme der Göttin hat am Mondbrunnen zu Euch gesprochen, <Name>. Das Heilmittel für Relara liegt im Osten beim Rajenbaumturm, der dem Verderben anheimgefallen ist.\n\nAvrus Böswisper wünscht Vergebung und Erlösung. Es liegt an Euch, ihn zu unterstützen und dabei hoffentlich auch meinem Kind zu helfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14019] = {title = "Affentheater", objective = "Füttert 10 bombenwerfende Affen, indem Ihr ihnen Nitrokaliumbananen zuwerft.", description = "Wir haben immense Probleme mit den Affen im Dschungel östlich von hier. Sie haben all unseren Sprengstoff gestohlen und jetzt fangen sie an, damit durch die Gegend zu werfen.\n\nUnd manchmal sogar auf uns!\n\nIch habe Zisch Zündel befohlen, etwas von seinem Nitro in diese Bananen zu füllen. Kein Affe kann einer leckeren Banane widerstehen!\n\nIhr müsst sie nur damit füttern.", progress = nil, completion = "Sie sind in die Luft gegangen, als sie die Bananen gegessen haben?! Das ist ja urkomisch!\n\nIch glaube, ich ziehe auch los und füttere ein paar.", rewards = "BananenschalenschuheBananenhalterAffenwärterhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14021] = {title = "Minenarbeiter in Not", objective = "Eskortiert den verängstigten Minenarbeiter durch die Kaja'mithöhle.", description = "Kluge Bergbauaffen!\n\nSie sind in der ganzen Höhle verstreut und bauen Erz ab… mit Spitzhacken! Das ist doch nicht normal. Ich bin mir sicher, dass es an dem Kaja'mit liegt.\n\nKeiner meiner Minenarbeiter ist wieder herausgekommen. Und ich habe nicht mehr viele! Ihr könnt also meine Not erkennen, <Name>.\n\n<Der Vorarbeiter senkt die Stimme.>\n\nDiese Typen sind nicht mal annähernd so gut wie meine alte Dschungeltrolltruppe. Ah, das waren noch Zeiten!\n\nVielleicht könnt Ihr meinen letzten Minenarbeiter hier durch die Höhle begleiten und ihm die Affen vom Leib halten? Wir brauchen dieses Kaja'mit!", progress = nil, completion = "Wir haben die Hauptader gefunden!!!\n\nSo, was hat es mit diesem Hexendoktor der Pygmäen auf sich, der die Affen kontrolliert? Wenn er nämlich tot ist, kann ich ganz legal Anspruch geltend machen… Nicht, dass ich das nicht sowieso vorgehabt hätte. Nach Goblinrecht gehört die Kaja'mithöhle uns!", rewards = "MinenarbeiterwesteFeuchtluntes \"beste\" RobenDer folgende Zauber wird auf euch gewirkt:\n\nMiner Troubles: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14022] = {title = "Pilgerfreuden", objective = "Sprecht mit Gregory Tabor außerhalb der Tore Sturmwinds.", description = "Möchtet Ihr nicht vielleicht das Pilgerfreudenfest mit uns feiern, <Name>? Dies ist eine Zeit des Besinnens auf Eure Reisen und Euer Glück, eine Zeit des Teilens - von gutem Essen und unterhaltsamen Geschichten!\n\nIhr könnt an den wundervollen Pilgerfreudenfeierlichkeiten in der Nähe der größeren Städte teilhaben, indem Ihr an einer der Festtafeln Platz nehmt und das vorhandene Essen verteilt.\n\nWenn Ihr lernen möchtet, wie man die traditionellen Pilgerfreudenspeisen zubereitet, sucht Gregory Tabor auf. Ihr findet ihn vor den Toren von Sturmwind.", progress = nil, completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14023] = {title = "Gewürzbrotfüllung", objective = "Bereitet 5 Portionen Gewürzbrotfüllung zu und bringt sie zu Jasper Moore an die Festtafel außerhalb der Tore Sturmwinds.", description = "Unsere Gewürzbrotfüllung ist das Prunkstück der Pilgerfreudentafel. Das Rezept war schon immer besonders beliebt in Sturmwind und hat nun seinen rechtmäßigen Platz im Pilgerfreudenfest-Kochbuch eingenommen.\n\nWenn Ihr in der Kochkunst bereits bewandert seid, könnt Ihr Euer Exemplar des Kochbuchs und alle benötigten Zutaten für ein Festmahl vom Händler des Pilgerfreudenfests erstehen. Und seid Ihr es nicht, so ist jetzt die beste Gelegenheit, dies zu ändern!\n\nHabt Ihr die Gewürzbrotfüllung zubereitet, bringt sie zu Jasper Moore, in der Nähe der Festtafel.", progress = "Wir können immer etwas von der köstlichen Gewürzbrotfüllung gebrauchen, sie ist ausgesprochen beliebt.", completion = "Ausgezeichnet. Genau was wir brauchen! Es ist harte Arbeit, dafür zu sorgen, dass die Tische niemals leer werden, doch es lohnt sich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14024] = {title = "Kürbiskuchen", objective = "Bereitet 5 Kürbiskuchen zu und bringt sie Edward Winslow an die Festtafel außerhalb von Eisenschmiede.", description = "Eure Gewürzbrotfüllung riecht ausgesprochen verlockend, doch keine Pilgerfreudentafel ist ohne einen prächtigen Kürbiskuchen komplett. Dies ist ein weiteres sehr beliebtes Gericht hier in Sturmwind, denn Kürbiskuchen wird aus den reifen Elwynnkürbissen zubereitet, die nur hier gedeihen.\n\nSolltet Ihr nicht wissen, wie man ihn zubereitet, könnt Ihr das Rezept in Eurem Pilgerfreundenfest-Kochbuch finden.\n\nWürde es Euch etwas ausmachen, einige Kuchen zuzubereiten und sie Edward Winslow zu bringen, außerhalb von Eisenschmiede? Sein Vorrat ist sicherlich schon knapp geworden.", progress = "Mehr Kürbiskuchen? Genau rechtzeitig.", completion = "Der Kürbiskuchen ist hier oben ausgesprochen beliebt. Ich habe noch nie zuvor gesehen, dass Zwerge über ein Gemüsegericht so aus dem Häuschen geraten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14028] = {title = "Moosbeerenchutney", objective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Jasper Moore an die Festtafel außerhalb Sturmwinds.", description = "Wenn Ihr bislang noch nie Moosbeerenchutney versucht habt, dann entgeht Euch etwas! Es wird aus den frischesten, schmackhaftesten Moosbeeren des ganzen Sumpflands zubereitet. Ersteht einfach welche vom nächsten Händler des Pilgerfreudenfests, wenn Ihr Euch an der Zubereitung versuchen wollt.\n\nDas Rezept findet Ihr in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht in Eile seid, würdet Ihr vielleicht etwas Chutney zubereiten und zu Jasper Moore bringen, außerhalb Sturmwinds? Ich habe ihm versprochen, es gegen den Kuchen einzutauschen, den Ihr mir gebracht habt.", progress = "Rieche ich da etwa Moosbeerenchutney?", completion = "Endlich, das versprochene Moosbeerenchutney! Ihr glaubt ja nicht, wie schnell die Feiernden das immer verputzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14030] = {title = "Darnassus darbt", objective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Kürbiskuchen zu Isaac Allerton in der Nähe des Eingangs nach Darnassus.", description = "Vielen Dank für das Moosbeerenchutney. Es gibt so viel zuzubereiten, ich kann kaum noch einen klaren Gedanken fassen! Und zu all dem kommt nun noch, dass Isaac Allerton in Darnassus mittlerweile praktisch alle Zutaten ausgegangen sind! Ich kann wohl kaum erwarten, dass Ihr so gut wäret, einzuspringen und etwas mehr Gewürzbrotfüllung und Kürbiskuchen zuzubereiten, oder? Der Händler sollte alle Zutaten parat haben, die Ihr benötigen würdet.\n\nIhr könnt ihn in der Nähe der Festtafel finden, auf der Wiese hinter der Terrasse der Krieger in Darnassus.", progress = "Seid Ihr gekommen, um am Pilgerfreudenfestmahl teilzunehmen?", completion = "Vielen Dank für alles! Ich hatte schon begonnen, mir Sorgen zu machen. Da Ihr schon mal hier seid, könntet Ihr gleich auch noch Euer Glück mit der Zubereitung kandierter Süßkartoffeln versuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14031] = {title = "Erfasst das Unbekannte", objective = "Verwendet Eure HGK Schnappblitz, um Bilder an den springenden Kameras der drei Höhlenmalereien und dem Altar der Pygmäen aufzunehmen.", description = "Hey, <Name>, da sind Höhlenmalereien und andere Artefakte überall in der Höhle.\n\nKönntet Ihr Eure am Gürtel befestigte HGK Schnappblitz verwenden, um an den markierten Orten Bilder aufzunehmen? Nehmt im hinteren Teil der Höhle ein Bild des Altars auf.\n\nIch bin sicher, Sassy würde diese Informationen gern in die Hände bekommen.", progress = nil, completion = "Was ist das?\n\n&lt;Sassy überprüft die Bilder, während sie Eurer Geschichte über die Kaja'mithöhle lauscht.&gt;\n\nDieser Hexendoktor der Pygmäen muss also aus einem Volk stammen, das wir noch nie gesehen haben. Vielleicht sollten wir sie Kyxillinge nennen?\n\nSie müssen die Höhle bemalt haben. Ich bin mir nicht sicher, ob mir gefällt, was Ihr mir da erzählt.\n\nFür mich klingt das so, als seien das Bilder von uns und ihnen auf einer Insel mit einem explodierenden Vulkan!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14032] = {title = "Säuberung im Koboldlager", objective = "Tötet 8 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.", description = "Eure erste Aufgabe ist eine Säuberung, <Name>. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14033] = {title = "Kandierte Süßkartoffeln", objective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Gregory Tabor außerhalb der Tore Sturmwinds.", description = "Solange Ihr hier seid, solltet Ihr Euch einen Vorrat an Süßkartoffeln von Teldrassil zulegen. Aus ihnen werden die köstlichsten kandierten Süßkartoffeln zubereitet, die Ihr je schmecken werdet!\n\nWenn Ihr mir nicht glaubt, sucht das Rezept aus Eurem Pilgerfreudenfest-Kochbuch heraus und probiert es mal! Und solltet Ihr welche übrig haben, könntet Ihr sie mit Gregory Tabor in der Nähe der Festtafel außerhalb Sturmwinds teilen. Er liebt diese Kartöffelchen! Aber wenn man ihm so zuhört, gewinnt man den Eindruck, er liebt alles, was man essen kann.", progress = "<Name>, wie schön, Euch zu sehen.", completion = "Aaah, kandierte Süßkartoffeln! Meine Leibspeise! Hat Isaac Euch davon erzählt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14034] = {title = "Foote, der Mann mit dem Plan", objective = "Besorgt die Schiffsschemata von Chefingenieur Foote in der Taverne 'Zum geborstenen Kiel' in Ratschet.", description = "Wir haben von den Spannungen zwischen der Allianz und der Horde profitiert, bis Konteradmiral Hartley in MEINEM Hafen angelegt hat und angefangen hat, seine Nase in meine Angelegenheiten zu stecken. Er hat Schiffe gejagt und beschlagnahmt, die unter der Flagge der Horde gesegelt sind, mit dem Ziel, sie davon abzuhalten, einen neutralen Hafen anzulaufen.\n\nIch werde sicher keinem wurstfingrigen Menschen erlauben, meinen Profit zu schmälern! Besorgt mir die Pläne des Flaggschiffs. Hartleys Chefingenieur pichelt sich in der Taverne zum geborstenen Kiel einen an, einfach den Hügel hinauf...", progress = "Habt Ihr, was ich brauche?", completion = "Ah, da sind sie – da steht es, genau hier! Sein Flaggschiff heißt also 'Die Kriegsmächtige', wie?\n\nWollen wir mal sehen, was man braucht, um diesen Plagegeist auf den Meeresgrund zu schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14035] = {title = "Langsam gerösteter Truthahn", objective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Isaac Allerton, in der Nähe der Tore von Darnassus.", description = "Jedes Pilgerfreudenfestmahl benötigt einen Mittelpunkt der Tafel, und damit meine ich kein dekoratives Füllhorn. Nein, die wahre Krönung der Tafel ist ein schmackhafter gerösteter Truthahn.\n\nIhr findet ein fabelhaftes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum erlegt Ihr nicht ein paar wilde Truthähne und bereitet sie selbst zu? Diese Tierchen sind überall im Wald von Elwynn unterwegs, Ihr solltet sie leicht aufspüren können.\n\nKönnt Ihr sie zu Isaac Allerton an die Tore von Darnassus bringen, sobald sie fertig zubereitet sind?", progress = "Was hat Euch denn wieder nach Darnassus verschlagen, <Name>?", completion = "Die sind grandios! Und sie kommen genau rechtzeitig, um hungrige Mäuler zu stopfen. Danke, &lt;Name&gt;! Ihr habt wahrlich alle Gänge eines traditionellen Pilgerfestmahls gemeistert.", rewards = "Ihr bekommt:\n\nTruthahnruf"}
MultiLanguageQuestData['de'][14036] = {title = "Pilgerfreuden", objective = "Sprecht mit Miles Standish im Innenhof über Unterstadt.", description = "Seid Ihr hier, um mit uns das Pilgerfreudenfest zu feiern? Dies war einst eine Zeit der Einkehr und des Gedenkens an getane Reisen und das Glück, ein gutes Mahl mit Freunden teilen zu können. Noch heute feiern viele das Fest.\n\nIhr könnt an Pilgerfreudenfeierlichkeiten in der Nähe größerer Städte teilnehmen, indem Ihr an einer der Festtafeln Platz nehmt und das dort vorhandene Essen verteilt.\n\nWenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, wendet Euch an Miles Standish im Innenhof über Unterstadt.", progress = nil, completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14037] = {title = "Gewürzbrotfüllung", objective = "Bereitet 5 Portionen der Gewürzbrotfüllung zu und bringt sie dann zu William Mullins an die Festtafel im Innenhof über Unterstadt.", description = "Unsere Gewürzbrotfüllung ist das A und O der Pilgerfreudentafel. Das Rezept stammt aus besseren Tagen in Lordaeron und hat nun seinen Platz unter den traditionellen Gerichten gefunden.\n\nSeid Ihr bereits in der Kochkunst bewandert, stattet dem Händler des Pilgerfreudenfests einen Besuch ab und Ihr erhaltet Euer eigenes Exemplar des Pilgerfreundenfest-Kochbuchs und alle hiesigen Zutaten, die Ihr benötigt, um ein Festmahl zuzubereiten. Seid Ihr noch unerfahren in der Kunst des Kochens, so ist dies die beste Gelegenheit für Euch, zu beginnen!\n\nSobald Ihr die Füllung zubereitet habt, übergebt sie William Mullins in der Nähe der Festtafel.", progress = "Die Tafel könnte wirklich noch etwas mehr Gewürzbrotfüllung vertragen.", completion = "Dafür zu sorgen, dass die ganze Festtafel immer schön gefüllt bleibt, ist keine einfache Aufgabe. Und wenn man bedenkt, dass wir eigentlich gar nicht mehr zu essen brauchen, kommt es einem besonders eigenartig vor.\n\n&lt;William zuckt mit den Achseln.&gt;\n\nTradition ist Tradition.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14038] = {title = "Minenarbeit", objective = "Setzt eine Haftmine an den dünnsten Teil des Rumpfs der Kriegsmächtigen.", description = "<Gazlowe breitet die Pläne auf dem Tisch aus und tippt mit seinem kleinen Finger auf das Achterdeck eines Schiffes unter der Wasserlinie.>\n\nDa! Dort ist der Rumpf am dünnsten, wo die Kurbelwelle auf das Schaufelrad trifft. Und das ist direkt neben dem Magazin!\n\n<Name>, man wird mich doch nicht zur Verantwortung ziehen können, wenn so ein tollkühner <Klasse> der Horde eine Haftmine an dieser Stelle des Rumpfs anbringt. Nicht einmal, wenn ich die Mine zur Verfügung stelle. Und ihn bezahle. Großzügig. Das Schiff liegt südöstlich von hier vor Anker... nichts wie hin!\n\nDann funkt mich über diesen gestohlenen Gnomcorder an.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14039] = {title = "Die Heimat der Kaldorei", objective = "Bringt das gefüllte Gefäß zu Tyrande Wisperwind in Darnassus.", description = "Es war zweifellos eine große Ehre, Euch kennengelernt zu haben. Ihr seid der lebende Beweis dafür, wie nobel Euer Volk ist.\n\nGeht jetzt und beendet diese letzte Aufgabe. Bringt das Wasser zu Tyrande Wisperwind in Darnassus.", progress = "Wie ist es Euch ergangen, junger Mann?", completion = "Ah, gesegnetes Wasser aus unseren Mondbrunnen. Ihr seid also Zeuge des Geistes der Kaldorei geworden?\n\nIn letzter Zeit fällt mir immer mehr auf, dass dieser Geist mehr Fragen aufwirft als beantwortet. Aber so ist nun mal die ständige Natur der Entdeckungen, die uns in unseren dunkelsten Stunden umtreibt.\n\nIch werde Euch die einfachsten Antworten geben, die mir zur Verfügung stehen. Malfurion ist zu mir... zu uns... zurückgekehrt, dennoch sind wir schweren Zeiten ausgesetzt. Hirschhaupt ist verschwunden und die Welt windet sich vor Schmerzen - Malfurion muss viel heilen und er wird Hilfe benötigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14040] = {title = "Kürbiskuchen", objective = "Bereitet 5 Stücke Kürbiskuchen zu und bringt sie zu Francis Eaton an die Festtafel außerhalb von Orgrimmar.", description = "Eure Gewürzbrotfüllung ist einfach wunderbar, aber uns fehlt noch der ein oder andere Kürbiskuchen zum Glück. Ein weiteres traditionelles Gericht der Region, denn hierzu werden reife Tirisfalkürbisse verwendet, die nirgends sonst gedeihen. \n\nFalls Ihr nicht wisst, wie man sie zubereitet, findet Ihr das Rezept in Eurem Pilgerfreudenfest-Kochbuch.\n\nMacht es Euch etwas aus, uns ein paar zuzubereiten und sie Francis Eaton außerhalb von Orgrimmar zu bringen? Ich bin sicher, es sind nicht mehr viele übrig.", progress = "Wir können immer frischen Kürbiskuchen gebrauchen.", completion = "Der Kuchen geht weg wie warme Semmeln. Ich glaube ja, die Leute halten sich gar nicht erst mit dem Hauptgericht auf, sondern gehen gleich über zum Nachtisch. Habt Ihr den Kuchen denn schon selbst einmal versucht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14041] = {title = "Moosbeerenchutney", objective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Dokin Grasland am Fuße des Aufzugs westlich von Donnerfels.", description = "Habt Ihr einmal das Moosbeerenchutney versucht? Es wird aus frischen, schmackhaften säuerlichen Moosbeeren vom Südstrom zubereitet. Besorgt Euch einfach welche vom Händler des Pilgerfreudenfests, wenn Ihr Euch mal am Rezept versuchen wollt.\n\nIhr findet es in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht zu viel zu tun habt, könntet Ihr vielleicht etwas Chutney zubereiten und es zu Dokin Grasland am Fuße des Aufzugs bringen, westlich von Donnerfels?", progress = "Wie gefallen Euch die Pilgerfreuden, <Klasse>?", completion = "Ah, endlich, mehr Moosbeerenchutney! Es ist unfassbar, wie schnell die Feiernden es vertilgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14042] = {title = "Kabummition", objective = "Zerstört 5 Munitions-Vorratslager von Theramore an der Küste.", description = "Hartley muss all seine Sprengmittel am Strand entladen haben. Ziehen wir ihm diesen Zahn, <Name>!\n\nGeht den Strand entlang und sucht nach seinen Sprengstoffvorräten. Zündet sie an und er sitzt ohne Bewaffnung an Land fest, während die Kriegsmächtige repariert wird.\n\nIch treffe Euch wieder hier in Ratschet.", progress = nil, completion = "Ha! Sehr gut gemacht, &lt;Name&gt;. Diese Idioten von der Allianz werden das niemals zu mir zurückverfolgen können. Inzwischen heißt es wieder zurück zur Tagesordnung: Schmuggel, doppelte Spielchen und Wucher... Ich habe viel nachzuholen.\n\nHier habt Ihr einen Anteil von meinen Gewinnen. Viel Spaß damit!", rewards = "MeißelstabKriegsmächtige HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14043] = {title = "Kandierte Süßkartoffeln", objective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Francis Eaton außerhalb der Tore Orgrimmars.", description = "Da Ihr schon mal hier seid, solltet Ihr gleich Euren Vorrat an Süßkartoffeln aus Mulgore aufstocken. Sie werden für die Zubereitung kandierter Süßkartoffeln verwendet, mein absoluter Favorit auf der Festtafel.\n\nWenn Ihr meinem Urteil nicht traut, sucht Euch das Rezept heraus und probiert es einmal! Solltet Ihr unterwegs nach Orgrimmar sein, könnt Ihr sie gleich zu Francis Eaton in der Nähe der Festtafel direkt außerhalb der Stadt bringen. Ich bemühe mich, ihn ausreichend zu versorgen, aber dort geht immer alles so schnell weg!", progress = "Willkommen zurück, <Name>.", completion = "Dokin hat Euch also dazu überredet, mit den kandierten Süßkartoffeln auszuhelfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14044] = {title = "Unterstadt ist unterversorgt", objective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Portionen Moosbeerenchutney zu Miles Standish in der Nähe des Eingangs von Unterstadt.", description = "Vielen Dank für die kandierten Süßkartoffeln. Es gibt so viel zu kochen, ich komme kaum hinterher! Und jetzt schickt mir Miles auch noch eine Nachricht, dass ihm Gewürzbrotfüllung und Moosbeerenchutney ausgehen! Ihr hättet nicht zufällig Zeit, mir damit noch etwas unter die Arme zu greifen und ein wenig mehr von beidem zu kochen? Der Händler sollte alle nötigen Zutaten vorrätig haben.\n\nIhr könnt Miles Standish in der Nähe der Festtafel finden, im Innenhof in den Ruinen über Unterstadt.", progress = "Wie gut, Euch wiederzusehen, <Name>.", completion = "Vielen Dank für alles, was Ihr gebracht habt. Einige der Tische machen schon langsam einen etwas kahlen Eindruck.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14045] = {title = "Findet Baron Küstenschipper", objective = "Findet den berüchtigten Piraten Baron Küstenschipper und sprecht mit ihm.", description = "Der ruchlose Pirat Baron Küstenschipper war der Schrecken dieser Meere, bevor die Allianz seine Flotte zerstört hat und die Überlebenden gefangen genommen hat. Gefällt mir das? Sehe ich aus, als ob ich vor Freude hüpfe und springe, <Name>?\n\nKüstenschipper hat einige meiner wertvollsten Ladungen vor seiner Gefangennahme geraubt. Man sagt, er habe sie vergraben, bevor er gefangen genommen wurde. Ich will meine Waren wieder zurück haben! Findet Küstenschipper im Lager der Allianz südlich von hier und versucht, ihm zu entlocken, wo mein Schatz ist.", progress = nil, completion = "Ha ha! Der alte Gazlowe hat seine Schätze also noch nicht abgeschrieben, oder? Nun, es sieht so aus, als ob mir das alte, goldgierige Langohr was zum Verhandeln gegeben hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14046] = {title = "Ein ehemaliger Baron", objective = "Wenn Ihr ihm traut, sprecht mit Baron Küstenschipper, um ihn von seinen Handschellen zu befreien.", description = "Ich werd' sicher am Galgen landen, Kamerad. Jetzt nützt mir der Schatz nur noch herzlich wenig...\n\nEs sei denn, ich kann mir damit mein Leben erkaufen. Ich schlag Euch'n Geschäft vor, <Volk>. Befreit mich von diesen Handschellen und ich sage Euch, wo der Schatz verbuddelt ist.\n\nUnd auf mein Wort ist Verlass. Ich war mal ein richtiger Baron, müsst Ihr wiss'n.", progress = nil, completion = "&lt;Der Baron reibt sich seine wunden Handgelenke und bricht in ein bösartiges Grinsen aus.&gt;\n\nOh, ich werde mich noch nicht dünne machen. Ich befreie meine Kameraden und haue und steche mir meinen Weg hier heraus, sobald mir danach ist. Und was Euch angeht – versprochen ist versprochen. Reden wir über diesen Schatz...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14047] = {title = "Langsam gerösteter Truthahn", objective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Francis Eaton, in der Nähe der Tore von Orgrimmar.", description = "Zu jedem Pilgerfreudenfestmahl gehört ein kulinarischer Höhepunkt - für uns ist das ein langsam gerösteter Truthahn. Es gibt nichts besseres, um ein reichhaltiges Mahl angemessen zu krönen!\n\nIhr findet ein gutes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum jagt Ihr nicht ein paar Truthähne und bereitet sie dann zu? Sie sind überall in Tirisfal zu finden.\n\nWenn sie fertig sind, könntet Ihr sie dann zu Francis Eaton außerhalb von Orgrimmar bringen?", progress = "Was hat Euch denn wieder nach Orgrimmar verschlagen, <Name>?", completion = "Die sehen köstlich aus. Vielen Dank, &lt;Name&gt;. Ihr habt wahrlich alle Gänge eines traditionellen Pilgerfestmahls gemeistert.", rewards = "Ihr bekommt:\n\nTruthahnruf"}
MultiLanguageQuestData['de'][14048] = {title = "Ich krieg einfach nicht genug ... Truthahn", objective = "Bringt 20 langsam geröstete Truthähne zu Caitrin Eisenkessel außerhalb von Eisenschmiede.", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall im Wald von Elwynn selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", progress = "Habt Ihr ein paar Truthähne aufgespürt?", completion = "Genau das Richtige, vielen Dank, &lt;Name&gt;. Ihr habt es genau getroffen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14049] = {title = "Eine äußerst ungewöhnliche Karte", objective = "Besorgt Euch den tätowierten Piratenkopf vom Eingang des Geländes der Allianz.", description = "Also, es ist so, Kamerad: Um meine Schatzkarte zu beschützen, habe ich sie auf die Kopfhaut meines ersten Steuermanns tätowiert.\n\nNatürlich ist er bereits genauso tot wie der Großteil vom Rest meiner Mannschaft. Die Mitglieder der Allianz wissen nicht einmal, was sie da in Händen halten. Sein abgeschlagener Kopf hängt an einem Baum am Eingang zu diesem Lager.\n\nSchnappt Euch den Kopf und bringt ihn zu Gazlowe in Ratschet.", progress = "War Baron Küstenschipper noch am Leben? Habt Ihr etwas für mich?", completion = "Was? Was ist das? Ich schicke Euch los, meinen Schatz zu finden und Ihr bringt mir einen verlausten Kopf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14050] = {title = "Gazlowes Vermögen", objective = "Gazlowe will, dass Ihr seinen verscharrten Schatz an den Klippen mit Meerblick ausgrabt.", description = "Verteufelt noch eins, Ihr hattet recht! Auf die Kopfhaut ist eine Karte tätowiert.\n\nDieser verfluchte Baron! Er hat meinen Schatz direkt unter meiner Nase vergraben. Oder über meinem Kopf. Diese Karte deutet auf einen Ort an den Steilufern über Ratschet im Süden.\n\nFolgt der Straße nach Westen aus der Stadt, begebt Euch auf den Hügel, geht nach Süden, dann lauft zurück zur Küste und sucht nach dem riesigen Baum, von dem aus man die Bucht überblickt. Schnappt Euch meinen Schatz und ich werde ihn mit Euch teilen!", progress = "Ich schließe jetzt meine Augen, <Name>. Und wenn ich sie wieder öffne, erwarte ich, dass dieser Raum randvoll mit Schätzen ist. Einverstanden?", completion = "Gute Arbeit, &lt;Name&gt;!\n\nOh, der Baron hat versucht, Euch aufzuhalten, wie? Nun, ich hoffe, Ihr habt's ihm gezeigt.\n\nNun, ich habe Euch einen Anteil an dem Schatz versprochen, den Ihr zurückgebracht habt. Mal sehen... Wie viel ist ein Prozent von einem halben Prozent? Ah, hier bitte schön.", rewards = "KlunkerstockWeste des GlücksDividendengamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14051] = {title = "Die Füllung ist alles!", objective = "Bringt 20 Portionen Gewürzbrotfüllung zu Caitrin Eisenkessel nahe der Festtafel außerhalb von Eisenschmiede.", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", progress = "Wie sieht es mit der Füllung aus?", completion = "Ein Glück, Ihr habt es geschafft! Ohne Gewürzbrotfüllung wäre das ganze Festmahl ein einziger Reinfall.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14052] = {title = "Unter vier Augen mit Tony", objective = "Sprecht mit Tony Zweihauer auf Prügeleiland im Nördlichen Brachland.", description = "Die Situation mit den Piraten behindert meine Unternehmungen erheblich. Käpt'n Garvey greift jedes Schiff an, das er erblickt - sogar diejenigen, von deren Besitzern ich mir ein 'Schutz'-Geld erschwindelt habe. Wir müssen diese Piraten auf frischer Tat ertappen und zwar bald!\n\nIch kenne genau den richtigen Gesellen, ein Leutnant von Garvey, der sich auf die Kungeleien vom alten Flunkerblick einlässt. Er hat mir angeboten, für mich eine kleine 'Meuterei' anzuzetteln. Sobald diese Jungs für uns arbeiten, ist das ein Kinderspiel, nicht wahr?\n\nSprecht mit Tony Zweihauer auf Prügeleiland im Süden.", progress = nil, completion = "Heiho Mann, hat Flunkerblick Euch geschickt? Gut, gut. Habt Ihr das Geld dabei? Nein?...Was ist mit den Gewehren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14053] = {title = "Schon wieder kein Moosbeerenchutney mehr?", objective = "Bringt 20 Portionen Moosbeerenchutney zu Ellen Moore an die Festtafel außerhalb Sturmwinds.", description = "Mein Mann Jasper wollte eigentlich noch mehr Moosbeerenchutney zubereiten, aber wie es scheint, hat er schon genug mit den kandierten Süßkartoffeln für all die Gäste zu tun. Würdet ihr vielleicht aushelfen? Wenn Ihr in der Kochkunst bewandert seid, braucht Ihr nur die säuerlichen Sumpfmoosbeeren, die Ihr beim Händler des Pilgerfreudenfests außerhalb von Eisenschmiede bekommen könnt.\n\nFalls Euch nicht nach Kochen ist, könnt Ihr auch jederzeit jemand anderen um die Zubereitung des Chutneys bitten.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Danke. Das sieht wirklich köstlich aus, und Ihr seid ein ganzes Stück schneller als Jasper - aber verratet ihm nicht, dass ich das gesagt habe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14054] = {title = "Kuchen versuchen", objective = "Bringt 20 Kürbiskuchen zu Mary Allerton an die Festtafel vor den Toren von Darnassus.", description = "Isaac arbeitet hart, um den Feiernden die traditionellen Ursprünge des Pilgerfreudenfests und die Zubereitung aus all den geernteten Zutaten in dieser Jahreszeit näher zu bringen. Ich bemühe mich, die Festtafeln schön gefüllt zu halten, aber Isaacs Leibspeise geht langsam zur Neige - Kürbiskuchen!\n\nKönntet Ihr welchen für uns organisieren? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr reife Elwynnkürbisse vom Händler des Pilgerfreudenfests außerhalb Sturmwinds.", progress = "Wie geht es mit dem Kuchen voran?", completion = "Die sind wunderbar. Isaac wird begeistert sein, und nicht nur er!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14055] = {title = "Rein in die Kartoffeln, raus aus den Kartoffeln", objective = "Bringt 20 kandierte Süßkartoffeln zu Jasper Moore an die Festtafel außerhalb von Sturmwind.", description = "Meine Frau Ellen hat mich damit beauftragt, für gedeckte Tafeln zu sorgen, doch sie ändert ständig ihre Meinung. Zuerst sollte ich Kürbiskuchen zubereiten, nun sind es plötzlich kandierte Süßkartoffeln.\n\nIch habe aber schon mit dem Kuchen angefangen! Vielleicht könntet Ihr mir ja mit den Süßkartoffeln aushelfen? Sie wird sicher angenehm überrascht sein, wenn wir alle ihre Wünsche erfüllen.\n\nSolltet Ihr die Süßkartoffeln selbst kandieren wollen, müsst Ihr sie beim Händler des Pilgerfreudenfests in Darnassus erstehen. Ich danke Euch, <Name>.", progress = "Habt ihr die kandierten Süßkartoffeln dabei?", completion = "Die sind genau richtig! Vielen Dank für Eure Hilfe, &lt;Name&gt;. Das Festmahl wird rechtzeitig fertig sein, und Ellen wird sich sicher freuen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14056] = {title = "Glomp sitzt darauf", objective = "Tötet Glomp und schnappt Euch Glomps Beute.", description = "Was? Glaubt Flunkerblick etwa, dass eine Meuterei so einfach und so billig ist?\n\nEgal, Mann, das wird schon hinhauen. Zunächst brauchen wir Geld. Käpt'n Garvey hortet gerne die Schätze, die wir erbeutet haben. Mit diesem Geld könnten wir meine handverlesenen Meuterer bezahlen.\n\nDer Schatz befindet sich direkt vor den Baracken hier. Ihr müsst Euch um Käpt'n Garveys 'Schatzmeister' kümmern. Allerdings lässt sich Glomp nicht so einfach herumschubsen. Glaubt mir, ich habe schon mal geschubst, und... Sagen wir, den haut nichts so schnell um.", progress = "Habt Ihr das Gold? Das Geld reicht allemal, um die Köpfe und Herzen der hirnlosen und herzlosen Halsabschneider zu gewinnen.", completion = "Sieh mal. Wir sind steinreich! Für eine Meuterei braucht man zuerst Geld. Wenn man das Geld hat, bekommt man die Macht. Holen wir uns die Macht, &lt;Name&gt;...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14057] = {title = "Gewehre. Wir brauchen Gewehre.", objective = "Besorgt 6 schwere, zwergische Gewehre.", description = "Für jede gute Meuterei braucht man ordentlich Feuerkraft. Käpt'n Garvey beansprucht die besten Schusswaffen für sich: eine ganze Ladung schwerer, zwergischer Steinschlossbüchsen. Er lagert sie bei sich im anderen Gebäude auf der anderen Seite der Insel. Bringt mir sechs dieser Büchsen und ich gebe sie an meine zukünftigen Offiziere weiter...", progress = "Gewehre, Mann. Habt Ihr sie?", completion = "&lt;Tony schnappt sich eine der Waffen und schaut durch den Lauf.&gt;\n\nOh, sehr schön. Glänzend. Laut. Die können sich sehen lassen.\n\nEs bleibt nicht mehr viel zu tun, bis wir alles soweit haben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14058] = {title = "Rein in die Kartoffeln, raus aus den Kartoffeln", objective = "Bringt 20 kandierte Süßkartoffeln zu William Mullins an die Festtafel oberhalb von Unterstadt.", description = "Roberta Carter hat mich beauftragt, eines der Festtagsgerichte zuzubereiten. Kandierte Süßkartoffeln! Normalerweise würde ich mich darum reißen, aber ich habe der Gastgeberin versprochen, mit ihr auf die Tafeln zu achten.\n\nEs wäre eine große Hilfe, wenn Ihr stattdessen für mich einige kandierte Süßkartoffeln organisieren könntet! Roberta würde mir nie vergeben, wenn ich sie im Stich lasse. \n\nWenn Ihr die Süßkartoffeln selbst kandieren wollt, müsst Ihr zunächst welche vom Händler des Pilgerfreudenfests in Donnerfels erstehen. Ich danke Euch für Eure Hilfe, <Name>!", progress = "Habt Ihr die kandierten Süßkartoffeln?", completion = "Vielen Dank, &lt;Name&gt;. Ich kann der Gastgeberin helfen und brauche Roberta dennoch nicht zu enttäuschen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14059] = {title = "Schon wieder kein Moosbeerenchutney mehr?", objective = "Bringt 20 Portionen Moosbeerenchutney zu Roberta Carter an die Festtafel in den Innenhof oberhalb von Unterstadt.", description = "Ich wünschte, ich wüsste, warum das Moosbeerenchutney immer so schnell alle ist. Manchmal habe ich das Gefühl, sie verfüttern es heimlich an die Monstrositäten, wenn gerade keiner hinschaut. Würdet Ihr uns helfen, für Nachschub zu sorgen? Wenn Ihr in der Kochkunst bewandert seid, könnt Ihr die benötigten säuerlichen Moosbeeren vom Südstrom vom Händler des Pilgerfreudenfests außerhalb von Orgrimmar bekommen.\n\nSteht Euch nicht der Sinn nach Kochen, könnt Ihr auch jederzeit jemand anderen darum bitten.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Vielen Dank für Eure Hilfe, und gebt mir Bescheid, falls Ihr jemals hinter das Geheimnis des ständig verschwindenden Chutneys kommen solltet!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14060] = {title = "Kuchen versuchen", objective = "Bringt 20 Kürbiskuchen zu Mahara Goldweizen nahe der Festtafel außerhalb von Donnerfels.", description = "Dokin und Laha bemühen sich, den Feiernden die Hintergründe des Fests und die Zubereitung der traditionellen Gerichte aus all den frisch geernteten Zutaten nahe zu bringen. Ich versuche, die Tische mit so viel Essen wie nur möglich gefüllt zu halten, aber uns geht langsam der Kürbiskuchen aus.\n\nWürdet Ihr vielleicht welchen für uns besorgen? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr dafür reife Tirisfalkürbisse, die Ihr beim Händler des Pilgerfreudenfests oberhalb von Unterstadt bekommen könnt.", progress = "Wie steht es mit dem Kuchen?", completion = "Die sind fantastisch. Danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14061] = {title = "Ich krieg einfach nicht genug… Truthahn", objective = "Bringt 20 langsam geröstete Truthähne zu Ondani Mühlenrad außerhalb von Orgrimmar.", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", progress = "Wie steht's mit der Truthahnjagd?", completion = "Prächtige Truthähne, genau was ich brauche! Ihr habt mir wirklich aus der Klemme geholfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14062] = {title = "Die Füllung ist alles!", objective = "Bringt 20 Portionen Gewürzbrotfüllung zu Ondani Mühlenrad an die Festtafel außerhalb von Orgrimmar.", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", progress = "Wie sieht es mit der Füllung aus?", completion = "Gerade rechtzeitig! Ich hätte das Festmahl ohne Gewürzbrotfüllung gar nicht auftischen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPilgerhutPilgergewandPilgerkleidPilgerrobePilgerstiefelTruthahnbüchse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14063] = {title = "Meuterei, Mann!", objective = "Verwendet das Signalhorn der Piraten, um Tony Zweihauer und seine Mannschaft an Bord der 'Dolch der Maid' zu rufen. Helft ihm, Alicia Cuthbert unter Deck zu besiegen.", description = "Nun zum schönsten Teil einer Meuterei: dem Abmurksen! Piraten interessieren sich nicht so sehr für die Frage, wer das Sagen haben soll, sondern es geht ihnen nur darum, wer das Schiff beherrscht. Im Ostende dieser Insel liegt die 'Dolch der Maid', das alte Flaggschiff von Käpt'n Garvey. Er hat die Aufsicht dem Offizier überlassen, dem er am meisten vertraut: Alicia Cuthbert. Sobald wir sie erledigt haben, gehört das Schiff uns – und damit auch das Meer.\n\nIch gebe meinen Männern den Befehl, in die Boote zu steigen. Ihr müsst an Bord der 'Dolch' gehen und an Deck in dieses Horn tuten. Das wird unser Signal sein, das Schiff zu kapern. Jippieh!", progress = "Ist das die 'Dolch der Maid', die dort in der Entfernung den Anker lichtet? Habt Ihr etwas damit zu schaffen?", completion = "Schmeißt Tony dort jetzt also den Laden? Gut! Wir brauchen in diesen Gewässern mehr Piraten wie ihn. Er ist ein echter Geschäftsmann.\n\n&lt;Flunkerblick reibt seine Hände gierig aneinander.&gt;\n\nWo wir vom Geschäft reden: ich schätze, ich bin Euch einen Anteil schuldig. Wäret Ihr daran interessiert, einen Teil Eurer Beute zu versichern? Man weiß nie, was in einer Stadt wie dieser geschieht...", rewards = "JunggesellendolchVerschwörerpantoffelnUnversicherte ArmschienenMeutererumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14064] = {title = "Teilen an der Festtafel", objective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, so viel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", progress = nil, completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14065] = {title = "Teilen an der Festtafel", objective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, so viel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", progress = nil, completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14066] = {title = "Untersuchung des Wracks", objective = "Findet den verunglückten Wagen in der Nähe der Straße zwischen Ratschet und dem Wegekreuz, und sucht das Gebiet nach Spuren und Hinweisen ab.", description = "Vor nicht allzu langer Zeit wurde eine Ladung Silber auf dem Weg von hier zum Wegekreuz gestohlen. Es war als Bezahlung für die Wachen gedacht und wir wollen das Silber zurück haben.\n\nIch habe mich nach Hinweisen umgehört, aber ich will, dass Ihr den Tatort untersucht. Begebt Euch nach Westen und sucht nach einem verunglückten Wagen einer Karawane an der Straße von hier Richtung Norden auf dem Weg zum Wegekreuz. Findet heraus, wer das Silber an sich genommen hat und holt es Euch zurück!", progress = nil, completion = "Dieser Wagen der Horde wurde nicht einfach nur ausgeraubt. Er wurde zerfetzt. Vorratskisten wurden mit scharfen Klauen auseinandergerissen. Der Wagen wurde vollständig zerstört. Die Nahrungsmittel wurden gefressen und das Silber ist weg, und dennoch wurden nützliche Vorräte zurückgelassen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14067] = {title = "Das gestohlene Silber", objective = "Tötet 8 Felshetzer und 4 Sensenklauen der Sonnenschuppen und findet das gestohlene Silber.", description = "Offensichtlich haben diese Raptoren alleine gehandelt, als sie das Silber der Horde raubten.\n\nEs wird Zeit, diesen Bestien eine Lektion zu erteilen.", progress = "Ihr seht mitgenommen aus, <Klasse>. Habt Ihr Euch mit den Dieben gerangelt?", completion = "&lt;Gazrog öffnet die Schließkassette und zählt das Silber, während Ihr berichtet.&gt;\n\nWas!? Raptoren? Nur die Raptoren? Alleine? Greifen unsere Karawanen an und plündern sie aus? Vielleicht sind sie doch so intelligent, wie die Gerüchte besagen. Als ob wir nicht schon genug Probleme hätten, müssen wir uns jetzt auch noch um diese schlauköpfigen und geldgierigen Echsen kümmern.\n\nHier, &lt;Name&gt; – Ihr habt Euch einen Teil des Silbers verdient. Habt Dank.", rewards = "Klinge mit SilberschneideSilberbesetzte GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14068] = {title = "Waptorfalle", objective = "Verwendet Kala'mas \"Waptorfalle\", um 5 kleine Waptoren zu fangen.", description = "Waptoren zu fangen, ist ganz schön schwiewig, aber ich habe eine neue Waptorfalle entwickelt, die den Gwoßteil der Wisiken ausschaltet.\n\nStellt die Falle auf dem Boden auf und sie quietscht wie ein Waptor und lockt so einen andewen in die Falle.\n\nWenn ein Waptor in meine Waptorfalle twitt, schwumpft sie ihn zusammen, sodass er nicht mehr so gefährlich ist. Es ist schwecklich einfach! Ich würde es selbst machen, aber ich bin neulich König Schnitterklaue begegnet.", progress = "Wo sind die kleinen Waptoren?", completion = "Huwwa! Ihr habt die Waptoren gefangen, nach denen ich gesucht habe! Jetzt dwessieren wir sie so, dass Twolle auf ihnen weiten können, um die Allianz zu vernichten!", rewards = "WaptorendwescherWaptorhautstiefelWaptorschuppenbwustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14069] = {title = "Gutes Personal ist schwer zu finden", objective = "Verbessert die Arbeitsmoral von 8 widerspenstigen Trollen.", description = "Ich habe versagt! Ich habe alles versucht, um unser Kaja'Cola-Soll zu erreichen, aber Ihr wisst doch, wie das mit den Trollsklaven heutzutage ist. Gutes Personal ist schwer zu finden!\n\nIch glaube, Ihr müsst hier selbst Hand anlegen. Ein kleiner Stromschlag mit der Batterie Eures goblinischen Alles-in-1-zigartigen Gürtels sollte Wunder wirken. Wenn Ihr die Arbeitsmoral von ein paar Trollen da unten anpasst, ziehen die anderen sicher schnell nach.\n\nDie Kaja'Cola-Produktion muss weitergehen, sonst macht uns der Handelsprinz einen Kopf kürzer!", progress = nil, completion = "Ich hätte es selbst nicht besser machen können. Und das habe ich auch nicht.\n\nIhr seid uns allen eine Inspiration, &lt;Name&gt;. Ich bin mir sicher, dass die Großartigkeit, die Macht und, wenn ich hinzufügen darf, der extreme Reichtum des neuen Handelsprinzen &lt;Name&gt; bald in aller Munde sein werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14070] = {title = "Selbst ist der Goblin", objective = "Verprügelt Bruno Flammhemmer, Frankie Gangschalter, Jack den Hammer und Sudsy Magee.", description = "Wir müssen gleich mehreren Schuldnern eine Nachricht zukommen lassen. Natürlich versteckt sich dieser Abschaum im Malocherviertel. Ich weiß, wie ungern Ihr in die Slums geht, <Herr/Frau> Boss, aber was soll man schon machen?\n\n<Sassy blättert durch einen Stapel Papiere.>\n\nIch habe alle Namen hier.\n\nDarf ich vielleicht vorschlagen, dass Ihr ihnen einen \"persönlichen Besuch\" abstattet? Ein paar strategisch geplante Schlägereien setzen deutliche Zeichen für die anderen Schuldner UND Eure Konkurrenten.\n\n<Name> ist kein Goblin, mit dem man sich anlegen sollte!", progress = nil, completion = "Das nenne ich einen absoluten Erfolg, mein Herr! Eure Schuldner werden es sich jetzt sicher zweimal überlegen, bevor sie Euch nicht bezahlen!\n\n&lt;Sassy kaut einen Augenblick gedankenverloren auf ihrem Stift herum.&gt;\n\nVielleicht sollten wir die Verleihzinsen erhöhen?", rewards = "Handschuhe des SchuldeneintreibersKnallende PeitscheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14071] = {title = "Cruisen", objective = "Fahrt mit dem Hot Rod durch die Gegend und holt Eure Freunde Ass, Gobber und Izzy ab.", description = "<Name>, ich habe gehört, dass Ihr die Mutter aller Firmenpartys ausrichten werdet. Laut meinen Berechnungen sollte Euer Beförderungsquotient raketenhaft in die Höhe schießen und explodieren, wenn man sieht, dass Ihr auf der Party Spaß habt!\n\nDaher schlage ich vor, Ihr unternehmt eine kleine Spritztour mit dem Hot Rod und holt Eure Freunde in der Stadt ab.\n\nVergesst mich nur nicht, wenn alles am Schnürchen läuft und Ihr <der neue Handelsprinz/die neue Handelsprinzessin> werdet, ja?", progress = nil, completion = "Gut gemacht, mein Herr. Der Hot Rod steht Euch wirklich ausgezeichnet. Ihr habt die Bevölkerung sicher schwer beeindruckt.", rewards = "Raketenhaftes GewehrSchickeriahosenHautenge LedergamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14072] = {title = "Verog aufstöbern", objective = "Sammelt 4 Geheiminformationen der Zentauren aus der Umgebung der Brackigen Oase.", description = "Regthar Totenfurt hat mich hierhergeschickt, um die Aktivitäten der Zentauren zu beobachten, aber der Anführer der Gruppe ist schwer auszumachen. Ich habe herausgefunden, dass er 'Verog der Derwisch' heißt, aber sein Aufenthaltsort bleibt unbekannt.\n\nKönnt Ihr mir ein wenig beim Auskundschaften helfen? Man würde bei den Zentauren eigentlich keine echten 'Geheiminformationen' erwarten, aber häufig befinden sich in ihren Lagern massenhaft wichtige Papiere. Sucht die Zelte der Zentauren um die Brackige Oase ab und bringt mir ein paar Informationen.", progress = "Durchsucht diese Zelte, <Name>. Versucht, den Gestank zu ignorieren.", completion = "Gute Arbeit, &lt;Name&gt;! Habt Ihr diese Papiere schon angesehen? Sie sind kaum lesbar und sehen eher wie eine wilde Schmiererei aus als wie Kriegspläne. Hass, Eifersucht, Wut, Zwietracht – es ist ein Wunder, dass Verog diese Zentauren davon abhalten kann, sich gegenseitig zu töten, ganz zu schweigen davon, sie zu einer Armee vereinen.\n\nDas können wir ausnutzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14073] = {title = "Verstärkung für Totenfurt", objective = "Meldet Euch bei Regthar Totenfurt an seinem Vorposten westlich vom Wegekreuz im Nördlichen Brachland.", description = "<Name>! Euer Ruf für die Horde wächst. Mir sind Berichte von den Vergessenen Teichen und der Brackigen Oase zu Ohren gekommen, dass Ihr unseren Zentauren-Feinden großen Schaden zugefügt habt. Gute Arbeit, in der Tat.\n\nRegthar Totenfurt leitet die Einsätze gegen die Zentauren im gesamten Nördlichen Brachland. Er könnte jemanden wie Euch zur Unterstützung seiner Streitkräfte gut gebrauchen. Meldet Euch bei ihm in seinem Vorposten an der Straße in Richtung Westen und lasst ihm jede Hilfe zukommen, die in Eurer Macht steht.", progress = nil, completion = "Ah, ich habe schon von Eurer Arbeit gehört, &lt;Klasse&gt;. Ihr habt den Zeitpunkt Eures Eintreffens gut gewählt. Ich arbeite derzeit an einer Großoffensive.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14074] = {title = "Legt mal ein Bein zu", objective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Narasi Schneedämmerung auf dem Argentumturnierplatz.", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden glücklich sein, dass etwas von der Ladung gerettet werden konnte.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14075] = {title = "Ärger in den Minen", objective = "Tötet 6 Tunnelwürmer.", description = "Wir haben schon wieder Ärger in der Kaja'mine, Boss. Die Tunnelwürmer sind zurück und fressen wortwörtlich den gesamten Profit der Handelsgesellschaft von Kajaro auf!\n\nWir können kein Kaja'mit abbauen, was die Produktion von Kaja'Cola schwer beeinträchtigt!\n\nIch habe schon versucht, den Kammerjäger zu rufen, aber er hat sich mit unserer letzten Zahlung aus dem Staub gemacht.\n\nMeint Ihr, Ihr könntet selbst in die drei Minen gehen und Euch darum kümmern? Ich würde Euch ja helfen, aber ich habe noch nicht am vom Kartell vorgeschriebenen Nahkampftraining teilgenommen.", progress = nil, completion = "Auf Nimmerwiedersehen, Ungeziefer!", rewards = "Pantoffeln des HGK-GeschäftsführersTunnelwurmwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14076] = {title = "Frühstück der Champions", objective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Scheucht die Tiefenjormungar auf, tötet sie und sammelt ihre Eiersäcke ein.", progress = "Habt Ihr die Eier besorgen können? Diese Würmer werden anfangen, ihre Tierführer zu fressen, wenn sie nicht schon bald gefüttert werden.", completion = "Gut gemacht, &lt;Name&gt;. Ich werde diese hier umgehend zu den Tierführern des Argentumkreuzzugs bringen. Sie werden keine andere Wahl haben und anerkennen müssen, dass wir um einiges mehr leisten als die Sonnenhäscher, wenn es darum geht, für den reibungslosen Ablauf im Kolosseum zu sorgen.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14077] = {title = "Die Barmherzigkeit des Lichts", objective = "Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Es genügt nicht, einfach nur an der Seite der Kreuzfahrer zu kämpfen, wir müssen uns ihre Mission zu Eigen machen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "&lt;Narasi nimmt das Gebetbuch von Euch entgegen.&gt;\n\nIch danke Euch. Dieses Buch war ein Geschenk der Beichtpatin Blondlocke selbst. Sie wäre sicher hocherfreut, dass Ihr es eingesetzt habt, um das Leid der erschlagenen Seelen zu lindern.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14078] = {title = "Abgeriegelt!", objective = "Findet Leutnant Walden am nordwestlichen Ende des Händlerplatzes.", description = "Was tut Ihr noch hier, <Bürger/Bürgerin>? Habt Ihr nicht gehört? Über die Stadt wurde eine vollständige Ausgangssperre verhängt.\n\nSprecht mit Leutnant Walden und befolgt seine Evakuierungsanweisungen.", progress = nil, completion = "Die Leiche des Mannes ist von tiefen Klauenspuren gezeichnet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14079] = {title = "Reiten lernen im Wald von Elwynn", objective = "Bringt diesen Handzettel zu Randal Weidmann beim Holzfällerlager des Osttals im Wald von Elwynn.", description = "Dieser Handzettel bewirbt das bei Randal Weidmann erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nRandal Weidmann befindet sich im Holzfällerlager des Osttals im Wald von Elwynn, von Sturmwind aus östlich die Straße entlang.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14080] = {title = "Einhalt den Aggressoren", objective = "Narasi Schneedämmerung auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", progress = nil, completion = "Eure Taten haben bewiesen, dass wir Schulter an Schulter mit dem Argentumkreuzzug stehen, während die Sonnenhäscher zu viel Zeit mit Herumstolzieren verschwenden, um noch zu den Waffen greifen zu können.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14081] = {title = "Reiten lernen im Immersangwald", objective = "Bringt diesen Handzettel zu Perascamin bei Turons Aufzucht in Silbermond.", description = "Dieser Handzettel bewirbt das bei Perascamin erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nPerascamin befindet sich bei Thurons Aufzucht, südöstlich des Hirtentors außerhalb von Silbermond.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14082] = {title = "Reiten lernen in der Exodar", objective = "Bringt diesen Handzettel zu Aalun außerhalb der Exodar auf der Azurmythosinsel.", description = "Dieser Handzettel bewirbt das bei Aalun erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nAalun befindet sich am Eingang zur Exodar auf der Azurmythosinsel.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14083] = {title = "Reiten lernen in Dun Morogh", objective = "Bringt diesen Handzettel zu Ultham Eisenhorn beim Gehöft Bernruh in Dun Morogh.", description = "Dieser Handzettel bewirbt das bei Ultham Eisenhorn erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nUltham Eisenhorn befindet sich im Gehöft Bernruh in Dun Morogh, von Eisenschmiede aus östlich die Straße entlang.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14084] = {title = "Reiten lernen in Dun Morogh", objective = "Bringt diesen Handzettel zu Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh.", description = "Dieser Handzettel bewirbt das bei Binjy Federpfiff erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nBinjy Federpfiff befindet sich bei Stahlrosts Depot, direkt nordöstlich von Kharanos in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14085] = {title = "Reiten lernen in Darnassus", objective = "Bringt diesen Handzettel zu Jartsam bei der Enklave des Cenarius in Darnassus.", description = "Dieser Handzettel bewirbt das bei Jartsam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nJartsam befindet sich in der Enklave des Cenarius in Darnassus.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14086] = {title = "Reiten lernen in Orgrimmar", objective = "Bringt diesen Handzettel zu Kildar im Tal der Ehre in Orgrimmar.", description = "Dieser Handzettel bewirbt das bei Kildar erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKildar befindet sich im Tal der Ehre in Orgrimmar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14087] = {title = "Reiten lernen in Mulgore", objective = "Bringt diesen Handzettel zu Kar Sturmsang beim Dorf der Bluthufe in Mulgore.", description = "Dieser Handzettel bewirbt das bei Kar Sturmsang erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKar Sturmsang befindet sich im Dorf der Bluthufe in Mulgore.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14088] = {title = "Reiten lernen in Durotar", objective = "Bringt diesen Handzettel zu Xar'Ti in Sen'jin im südlichen Durotar.", description = "Dieser Handzettel bewirbt das bei Xar'Ti erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nXar'Ti befindet sich in Sen'jin in Durotar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14089] = {title = "Reiten lernen in Tirisfal", objective = "Bringt diesen Handzettel zu Velma Warnam in Brill in Tirisfal.", description = "Dieser Handzettel bewirbt das bei Velma Warnam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nVelma Warnam befindet sich in Brill in Tirisfal.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14090] = {title = "Gormok will seine Schneebolde", objective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", progress = nil, completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte den Sonnenhäschern die Aufsicht über diese Kreatur gegeben. Sie sind sich so ähnlich, dass sie sich eigentlich verstehen sollten.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14091] = {title = "Da stimmt was nicht", objective = "Kehrt zu Prinz Liam Graumähne auf dem Händlerplatz zurück.", description = "Der Leutnant scheint seinen schweren Wunden erlegen zu sein. Der Prinz wird die Neuigkeiten bestimmt hören wollen.\n\nIhr hört Kampfgeräusche, die aus der Richtung des Marktes kommen.", progress = nil, completion = "Ihr seid es wieder. Sieht aus, als ob Ihr niemand wärt, der im Angesicht der Gefahr den Schwanz einziehen würde. Nun dann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14092] = {title = "Frühstück der Champions", objective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Ihr Ton wird die Tiefenjormungar aufscheuchen. Tötet sie, sammelt ihre Eiersäcke ein und bringt sie zurück zum Turnierplatz.", progress = "Habt Ihr die Eier besorgen können? Die Jormungar werden unausstehlich, wenn man sie nicht füttert.", completion = "Ich werde die Kreuzfahrer wissen lassen, dass Ihr gerade eine Ladung frisches Futter zurückgebracht habt, während der Silberbund faul herumsitzt.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14093] = {title = "Die Hölle bricht los", objective = "Prinz Liam Graumähne wünscht, dass Ihr 6 tobende Worgen tötet.", description = "Worgen! Mein Vater hat mich gewarnt, dass die Schöpfungen des Erzmagiers Arugal irgendwann Amok laufen würden.\n\nAber woher kommen sie?\n\nVermutlich macht es keinen Unterschied. Helft uns, kurzen Prozess mit ihnen zu machen. Wir werden ihnen zeigen, aus welchem Holz die Bewohner von Gilneas geschnitzt sind.", progress = "Habt Ihr Euch um die <Volk> gekümmert?", completion = "Es hat keinen Zweck, &lt;Name&gt;! Sie lassen nicht nach.", rewards = "Ihr bekommt:\n\nWolfspelzmantel"}
MultiLanguageQuestData['de'][14094] = {title = "Bergt die Vorräte", objective = "Bergt 4 Vorratskisten.", description = "Hört zu, <Name>. Wir können nicht zulassen, dass unser Proviant zerstört wird.\n\nDa Gilneas von der Außenwelt abgeschottet ist, werden wir den Winter nicht überleben, wenn wir noch mehr von unseren Vorräten verlieren.\n\nBitte helft mir dabei, zu retten, was zu retten ist.", progress = "Habt Ihr die Vorräte geborgen, <Name>?", completion = "Hervorragend! Ich werde sicherstellen, dass sie an einen sicheren Ort gebracht werden.", rewards = "Ihr bekommt:\n\nBergungsbeutel"}
MultiLanguageQuestData['de'][14095] = {title = "Die Überreste identifizieren", objective = "Bringt den Krakenzahn zum Beweis Eures Sieges zu Kreuzfahrer Silberdämmerung.", description = "Ein ganzer Zahn eines toten Kraken ist in der Tat ein seltener Fund. Kreuzfahrer Silberdämmerung wird das sehen wollen.", progress = "Was habt Ihr gefunden, Champion?", completion = "Ich wusste, dass die Krake jemandem wie Euch nicht gewachsen sein würde. Nun, da die Boote nicht mehr von ihr belästigt werden, bleibt den Kvaldir keine andere Wahl, als sich zurückzuziehen. Gute Arbeit, Champion!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14096] = {title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", objective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nOhne Verstärkung wurden Kul und seine Gefolgschaft schnell gefangen genommen. Ich habe keine Zweifel, dass der Kult die Gefangenen opfern wird - es sei denn, wir können einen Rettungseinsatz in Gang bringen. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", progress = nil, completion = "Dank Euch haben Kul und die Streiter überlebt, um weiterhin die Geißel zu bekämpfen. Das ist bei Weitem nicht das erste Mal, dass jemand Kul vor sich selbst retten musste. Ich hoffe nur, dass die Kreuzfahrer ein besseres Ventil für seinen Enthusiasmus finden, als ihm weiter zu gestatten, seine schlechten Angewohnheiten an junge und noch beeindruckbare Streiter weiterzugeben.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14098] = {title = "Evakuiert den Händlerplatz", objective = "Evakuiert 3 Zivilistenhäuser.", description = "Die Zivilisten sind hier nicht mehr sicher. Nicht mal mehr in ihren Häusern.\n\nWir tun, was wir können, um die Worgen davon abzuhalten, in die Häuser zu gelangen, aber es sind einfach zu viele.\n\nHelft uns dabei, die Häuser der Zivilisten zu evakuieren. Die Armee meines Vaters im Gefängnisviertel wird sie besser schützen können.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch werden viele Bürger Gilneas' den morgigen Tag erleben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14099] = {title = "Königlicher Befehl", objective = "Sprecht mit Gwen Armstead im Militärviertel im Südosten.", description = "Es ist Zeit für Euch, uns zu verlassen, <Name>. Geht mit den anderen Zivilisten ins Militärviertel.\n\nMeldet Euch bei Gwen Armstead, wenn Ihr die Brücke im Südosten überquert ... seht nach, ob es allen gut geht.\n\nIch werde mit den Wachen hierbleiben und den Rückzug der Zivilisten decken.\n\nGeht nun. Das ist ein Befehl!", progress = nil, completion = "Es geht uns allen gut. Wir sind ein wenig mitgenommen, aber ... wir leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14100] = {title = "Relikt des Irdenen Rings", objective = "Bringt Eure vier Totems nach Orgrimmar zu Gotura Vierwind.", description = "Ihr seid weit in Eurem Training vorangekommen, <Name>. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Gotura Vierwind im Tal der Weisheit in Orgrimmar und feilt an Eurer Beherrschung der Elemente.", progress = "Hmmm, was verleitet Euch, die Hilfe des Irdenen Rings zu suchen?", completion = "Ah, Ihr beherrscht nun die vier Totems. Ihr solltet stolz auf das sein, was Ihr bisher erreicht habt, junger &lt;Volk&gt;, aber das ist lediglich der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nFührt Euer Training weiter. Diese Welt hat noch Schlimmes vor sich - ich kann es im Wind hören und fühle es im Rumpeln der Erde. Wir müssen auf das Schlimmste vorbereitet sein.", rewards = "Ihr erlernt:\n\nTotem des Irdenen Rings\n\nDer folgende Zauber wird auf euch gewirkt:\n\nDen spieler die Totems zerstören lassen"}
MultiLanguageQuestData['de'][14101] = {title = "Drottinn Hrothgar", objective = "Hochmeister Adelard auf dem Argentumturniergelände möchte, dass Ihr Drottinn Hrothgar besiegt.", description = "Die Kvaldir, seefahrende Vrykul, die Schiffe und Küstensiedlungen überfallen, haben eine Tuskarrinsel auf der anderen Seite der Meerenge gen Norden überrannt. Ihr Anführer ist ein altgedienter Plünderer namens Drottinn Hrothgar, der die Kontrolle über diesen Teil der See erlangen möchte.\n\nMit ihm an der Macht werden unsere Lieferungen und Truppentransporte niemals sicher sein. Wir werden hier gestrandet und dem Lichkönig auf Gedeih und Verderb ausgeliefert sein.\n\nHier, bringt dieses erbeutete Kriegshorn der Kvaldir zum Tuskarrstatuenkreis im nordöstlichen Teil von Hrothgars Landestelle und verwendet es, um den Anführer der Kvaldir herauszufordern.", progress = nil, completion = "Die Niederlage von Drottinn Hrothgar wird die Kvaldir gegeneinander aufhetzen, was uns genug Zeit verschafft, unseren Vorteil zu nutzen. Der Kreuzzug und das Turnier stehen in unserer Schuld, Champion.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14102] = {title = "Nebelrufer Yngvar", objective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Nebelrufer Yngvar tötet.", description = "Die Kvaldir sind zur Küste von Nordend zurückgekehrt und wenn sich niemand um sie kümmert, werden sie verhindern, dass Vorräte und Verstärkung hier ankommen. Einer von ihnen, bekannt als Nebelrufer Yngvar, hat sich in einer Höhle auf der Westseite von Hrothgars Landestelle eingenistet. Von dort aus beeinflusst er den Nebel, um die Kvaldir und deren Meeresbestien zu verbergen.\n\nHier, nehmt diesen Glücksbringer und überquert die Meerenge nördlich des Turnierplatzes in Richtung Hrothgars Landestelle. Findet die Höhle des Nebelrufers und bringt ihn mithilfe des Glücksbringers zum Vorschein.", progress = nil, completion = "Ihr habt uns kostbare Zeit verschafft, um gegen die Kvaldir vorzurücken und das Meer von diesen Quälgeistern zu befreien. Der Argentumkreuzzug steht einmal mehr in Eurer Schuld.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14103] = {title = "Titanstaub", objective = "Hallo, <Name>! Habt Ihr was zum Handeln?", description = nil, progress = "Hallo, <Name>! Habt Ihr was zum Handeln?", completion = "Wunderbar! Noch eine Ladung Pulver!\n\nUnter uns Juwelenschleifern, ich habe bei den Magiern von Dalaran ein Riesengeschäft mit Schmuck aus \"reinem Titanium\" gemacht. Selbst mit ihrem überragenden Verstand sind sie nicht schlau genug, was Ihr Gold angeht. Ich bin hier, falls Ihr noch mehr bekommen solltet.", rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][14104] = {title = "Ornolf der Vernarbte", objective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Ornolf den Vernarbten tötet.", description = "Ornolf der Vernarbte gilt als angsteinflößender Plünderer und ist unter seinen Kvaldirbrüdern bekannt dafür, Schiffe zu plündern und zu kapern. Vom Schiff Bors Zorn aus greifen seine Mannschaft und er unsere Schiffe an und stehlen unsere Ladung.\n\nOrnolf und seine Männer gehören zu denjenigen, die Mord an den Einwohnern einer Tuskarrinsel begangen haben und diese in Hrothgars Landestelle umbenannten. Sein Schiff liegt am östlichen Ende des Hafens der Insel vor Anker. Nehmt diesen erbeuteten Banner an Euch und stellt ihn auf diesem Schiff auf, um ihn zu provozieren und in den Kampf mit Euch zu locken.", progress = nil, completion = "Ornolfs Mannschaft wird Ihren Anführer rächen wollen, aber ohne ihn werden sie einfacher zu besiegen sein. Wir haben unser Leben der Aufgabe geweiht, die Eiskrone von der Geißel und anderem Bösen zu befreien.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14105] = {title = "Todessprecher Kharos", objective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Todessprecher Kharos tötet.", description = "Der Kult der Verdammten hat seine Anstrengungen verdoppelt, um unsere Vernichtung herbeizuführen. Sie sind mutig geworden und sammeln in Todessprechers Wacht auf dem Gebirgskamm westlich des Turnierplatzes ihre Kräfte.\n\nDer erbarmungslose Todessprecher Kharos hat seinen Männern befohlen, ihre Stellungen zu befestigen, um sich darauf vorzubereiten, alle Waffen des Kults einzusetzen.\n\nMeine Männer bereiten sich und die Recken darauf vor, den Platz zu verteidigen - ich möchte jedoch, dass Champions wie Ihr, <Name>, unsere Streitkräfte anführen, um den Angriff abzuschwächen. Findet Todessprecher Kharos und tötet ihn.", progress = nil, completion = "Wahrhaftig, Ihr seid ein Beispiel für alle, die sich unter unserem Banner versammelt haben, &lt;Name&gt;. Gemeinsam werden wir der Geißel zeigen, dass wir nicht in die Knie gezwungen werden.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14106] = {title = "Na Kada's Questtest", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nManatrank"}
MultiLanguageQuestData['de'][14107] = {title = "Das Schicksal der Gefallenen", objective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr dafür sorgt, dass 6 Geister der gefallenen Helden Frieden finden.", description = "Der Argentumkreuzzug ist wohl kaum die erste Streitmacht, die den Lichkönig herausfordert. Unser Feind hetzt die Geister der Gefallenen gegen uns auf.\n\nSie streifen im Tal der Gefallenen Helden südwestlich des Platzes zwischen Aldur'thar und dem Eisenwallbollwerk umher. Die Gegend ist mit weggeworfenen Seelenkristallen, mit denen die Geißel die Geister kontrolliert, übersät. Sammelt diese Seelenkristalle und verwendet sie gemeinsam mit diesem lichtgesegneten Relikt, um den Geistern den Segen des Friedens zu verleihen. Sie haben ihre Ruhe mehr als verdient.", progress = nil, completion = "Ihr habt unseren gefallenen Brüdern einen großen Dienst erwiesen und es uns erspart, ihnen erneut auf dem Schlachtfeld begegnen zu müssen. Mit dem Voranschreiten der Kampagne gegen die Geißel ertappe ich mich dabei, über mein eigenes Schicksal nachzusinnen.\n\nSollte ich fallen, &lt;Name&gt;, würde ich wollen, dass Ihr dasselbe für mich tätet wie an diesem heutigen Tage für die Geister der Gefallenen. Ich könnte den Gedanken nicht ertragen, meinen eigenen Bruder dazu zu zwingen, mich immer wieder zu töten.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14108] = {title = "Kraken am Haken", objective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr auf einen Argentumhippogryph steigt, 8 flammende Speere auf den Nordmeerkraken werft und 6 Tiefenrufer der Kvaldir ausschaltet.\n\nIhr findet die Argentumhippogryphen gleich außerhalb des Zelts auf dem Argentumturnierplatz.", description = "Die Sonnenhäscher und der Silberbund haben Schiffe nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle anzugreifen, jedoch wurden sie von einem Seeräuberschiff der Kvaldir abgefangen und anschließend gefangen genommen. Was die Sache noch schlimmer macht, ist, dass die Kvaldir einen Weg gefunden haben, den gefürchteten Kraken aus den Tiefen des Nordmeeres hervorzurufen. Wenn irgendjemand an Bord da lebend herauskommen soll, muss der Kraken weggejagt und das Beschwörungsritual der Kvaldir... unterbrochen werden.\n\nHier <Kreuzfahrer/Kreuzfahrerin>, nehmt diese Speere. Ein Argentumhippogryph wird Euch in die Schlacht tragen.", progress = "Habt Ihr den Kraken schon verjagt? Beeilt Euch, Kreuzfahrer! Es bleibt nicht viel Zeit.", completion = "Kreuzfahrer, Ihr habt den Seemännern womöglich gerade genug Zeit verschafft, um ihre Flucht zu ermöglichen. Vielleicht werden die Leute vom Silberbund und die Sonnenhäscher das nächste Mal hinhören, bevor sie sich Hals über Kopf auf den Feind stürzen.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14109] = {title = "Ein ganz neues Ihr", objective = "Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.", description = "Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.\n\nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!", progress = "Hast du alles beisammen, <Name>? Ich kann es kaum erwarten, die neuen Sachen an dir zu sehen.\n\nDu hast doch keinen Ramsch gekauft, oder?", completion = "Oh, du wirst so toll aussehen! Allerdings nicht so toll wie ich. Bei deinem Tempo wirst du den Handelsprinzen im Handumdrehen vom Thron stoßen!\n\nIch kann es kaum abwarten, endlich nicht mehr arbeiten zu müssen! Du kaufst mir doch alles, was ich will, oder, Liebling?\n\nLass mich dir die ganzen Sachen abnehmen. Kurz bevor die Party losgeht werde ich dir beim Styling helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14110] = {title = "Ein ganz neues Ihr", objective = "Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.", description = "Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.\n\nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!", progress = "Hast du alles beisammen, <Name>? Ich kann es kaum erwarten, die neuen Sachen an dir zu sehen.\n\nMmm hmm!", completion = "Oh, du wirst so scharf aussehen! Bei deinem Tempo wirst du den Handelsprinzen im Handumdrehen vom Thron stoßen!\n\nIch kann es kaum abwarten, endlich ein gemachter Mann zu sein!\n\nLass mich dir die ganzen Sachen abnehmen. Kurz bevor die Party losgeht, werde ich dir beim Styling helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14111] = {title = "Relikt des Irdenen Rings", objective = "Bringt Eure vier Totems nach Eisenschmiede zu Weitseher Eannu.", description = "Ihr seid weit in Eurem Training vorangekommen, <Name>. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Weitseher Eannu in der Nähe der Großen Schmiede in Eisenschmiede. Er wird Euch dabei helfen, Eure Beherrschung der Elemente zu verfeinern.", progress = "In Euch regen sich die Geister. Was bringt Euch dazu, die Hilfe des Irdenen Rings zu suchen?", completion = "Wie ich sehe, beherrscht Ihr nun den Gebrauch der vier Totems. Ihr seid auf dem Weg, eins mit den elementaren Geistern zu werden - aber dies ist erst der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nEuer Training muss weitergehen! Ich spüre, dass diese Welt sehr viele Prüfungen erwarten, und wir werden die Macht der Elemente hinter uns wissen müssen, wenn wir die Oberhand gewinnen wollen.", rewards = "Ihr erlernt:\n\nTotem des Irdenen Rings\n\nDer folgende Zauber wird auf euch gewirkt:\n\nDen spieler die Totems zerstören lassen"}
MultiLanguageQuestData['de'][14112] = {title = "Was fressen eigentlich Yetis?", objective = "Savinia Lehrensang auf dem Argentumturnierplatz möchte, dass Ihr ihr 3 Stück Fleisch eines Nordmeerhais bringt.", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, der Bestie überschüssige Sonnenhäscher zum Fressen zu geben. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zur Silberklinge hinunterfliegt, die in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Sonnenhäscher in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht von den Sonnenhäschern behaupten.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14113] = {title = "Der Mittelpunkt der Party", objective = "Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.", description = "Oh, meine Güte, Baby! Alle sind gekommen! Wen interessiert da schon irgendein blöder Drache?\n\nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Du wirst so toll aussehen!\n\nWarum gehst Du nicht schon einmal rüber zum Pool und unterhältst die Leute? Ich bin in einer Minute bei Dir... Ich will nur kurz in etwas Aufregenderes schlüpfen.", progress = nil, completion = "Sehr gut, mein Herr. Die Party war anscheinend ein voller Erfolg!\n\nÄh… was ist das denn?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14115] = {title = "Ungeladene Piraten", objective = "Tötet 12 ungeladene Piraten, um Eure Karriere zu retten.", description = "Oh je! Piraten!\n\n<Name>, da sind ungeladene Südmeerpiraten auf Eurer Party!\n\nIhr müsst sofort etwas dagegen unternehmen oder Eure Karriere und jede Hoffnung, <der nächste Handelsprinz/die nächste Handelsprinzessin> zu werden, sind dahin.", progress = nil, completion = "Puh, das war knapp, Boss. Und leider habe ich noch mehr schlechte Nachrichten.\n\nBitte, erschießt mich nicht…", rewards = "SüdmeerschärpeArmschienen der völligen KatastropheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14116] = {title = "Der ungeladene Gast", objective = "Sprecht mit Handelsprinz Gallywix oben im Hauptgebäude des Hauptgeschäftssitzes der HGK auf Kezan.", description = "Während Ihr Euch um die Piraten gekümmert habt, habe ich bemerkt, wie der Handelsprinz sich nach oben geschlichen hat. Er ist auf dem Balkon oben an der Treppe.\n\n<Name>, ich glaube, er hat die Piraten geschickt.\n\n<Sassy erschaudert.>\n\nIhr solltet lieber so schnell wie möglich nach oben gehen. Lasst ihn nicht warten!", progress = nil, completion = "So, so, so, wenn das nicht mein abtrünniger Schützling Herr &lt;Name&gt; ist.\n\nIch bin tief verletzt und enttäuscht. Ihr habt mich nicht zu Eurer kleinen Party da draußen eingeladen. Tut mir leid wegen der ungebetenen Gäste… Ihr wisst ja, wie Piraten sein können.\n\nAlso, kommen wir zum Geschäft?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14117] = {title = "Die Augen von Eschental", objective = "Tötet 8 Späher der Talendrisspitze.", description = "Unsere Feinde sind in der Überzahl, <Klasse>, sogar direkt hier an unserer Türschwelle. Die Nachtelfen haben die Talrendisspitze verstärkt, weil sie unser Vordringen im Eschental unterbinden wollten. In diesem Augenblick patrouillieren ihre Späher in den nahegelegenen Hügeln und berichten über jedes Ein- und Ausgehen an diesen Toren.\n\nWir müssen Eschental diese Augen herausreißen.\n\nGeht. Eure Beute schleicht um diese Tore herum, insbesondere im Osten. Vernichtet die Späher, die uns beschatten!", progress = nil, completion = "Ausgezeichnet. Wenn ihre Späher ihnen nicht länger berichten, wird die Talendrisspitze selbst die Furcht zu spüren bekommen, die sie uns einflößen wollte.", rewards = "Stab des blutigen AugenhügelsGestohlene TalrendisstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14118] = {title = "Wildbret für die Truppen", objective = "Sammelt 15 Scheiben Wildbret von geschwächten Mooshufhirschen.", description = "Während wir die Ressourcen dieses Landes für unsere Kriegsmaschinerie aufbrauchen, berauben wir die einheimischen Tiere ihrer Heimat. Wenn sie ohnehin sterben müssen, sollte ihr Fleisch aber dennoch nicht verschwendet werden. Nicht wenn die Schlünde von Orgrimmar weit geöffnet und hungrig sind.\n\nTötet die geschwächten Mooshufhirsche, die sich noch in diesem Gebiet aufhalten, und bringt ihr Fleisch unseren Peons und Grunzern mit.", progress = "Ihr riecht nach frisch getötetem Wild, <Klasse>.", completion = "Wild – und zwar reichlich! Gute Arbeit. Das wird unsere Mägen füllen, während wir unser Arsenal bauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14119] = {title = "Blank [PH]", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nTransmutieren: Auge von Zul\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14120] = {title = "Eine Bazillion Moneten?!", objective = "Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.", description = "Ihr seid ein sehr ehrgeiziger junger Goblin, <Name>. Vielleicht ein wenig ehrgeiziger, als es für Euch gut wäre. Ich erkenne mich selbst in Euch, als ich noch jung war.\n\nIch habe einen Vorschlag. Vielleicht ist Euch ja schon aufgefallen, dass der Kajaro explodiert. Alle auf Kezan werden sterben!\n\nAber, wenn Ihr mir eine Bazillion Moneten bringt, bevor meine Yacht die Insel verlässt, werde ich dafür sorgen, dass Ihr unter den wenigen Glücklichen seid, die entkommen.\n\nWenn Ihr also leben wollt, solltet Ihr Euch lieber schnell überlegen, wo Ihr so viel Knete für mich auftreibt!", progress = nil, completion = "Eine Bazillion Moneten?!? Wo sollen wir denn so viel Knete her bekommen?\n\n&lt;Sassy überlegt einen Augenblick.&gt;\n\nÄh… hat der Handelsprinz erwähnt, ob ich mit Euch zusammen auf seiner Yacht fliehen darf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14121] = {title = "Plündert die Plünderer", objective = "Benutzt den Hot Rod, um 12 angeheuerte Plünderer umzufahren, und sammelt dabei 12 Einheiten gestohlene Beute.", description = "Wir werden alle sterben!!!\n\n<Ihr gebt Megs eine Ohrfeige, damit sie sich beruhigt.>\n\nTut mir leid, <Herr/Frau> <Name>! Es wird nicht mehr vorkommen. Wir müssen einen Weg finden, ganz schnell ganz viel Knete zu scheffeln.\n\nEs gibt bereits Berichte, dass der Handelsprinz angeheuerte Plünderer auf die Straßen des Bilgepiers geschickt hat.\n\nNehmt den Hot Rod, fahrt sie über den Haufen und nehmt Euch die Beute, die sie sich unrechtmäßig angeeignet haben. Daran wäre doch nichts Falsches, oder?\n\nSchließlich ist es für eine gute Sache!", progress = "Konntet Ihr etwas von der gestohlenen Beute zurückstehlen?", completion = "Ihr habt es wirklich geschafft?! Na, ich schätze, das haben sie verdient.\n\nDas ist aber ganz schön viel Beute. Meint Ihr, es reicht, um Euch einen Platz auf der Yacht des Handelsprinzen zu erkaufen?\n\nKönnt Ihr jemanden mitnehmen? Ich habe im Marketing gerade nicht allzu viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14122] = {title = "Der große Banküberfall", objective = "Knackt den Tresor der Ersten Bank von Kezan, um an Eure privaten Reichtümer zu gelangen.", description = "All Eure Besitztümer wurden eingefroren und die Erste Bank von Kezan hat geschlossen!\n\nIhr braucht wirklich einen Haufen Knete, Boss. Ich fürchte, Ihr müsst Euer eigenes Geld aus der Bank rauben! Mit den verschiedenen Apparaten in Eurem goblinischen Alles-in-1-zigartigen Gürtel solltet Ihr alles dabei haben, was Ihr braucht, um den Tresor zu knacken.\n\nIch hoffe nur, dass Ihr etwas für schlechte Zeiten gespart habt, wie ich es Euch immer geraten habe. Und falls Ihr es noch nicht gemerkt haben solltet: Die Zeiten sind gerade hundsmiserabel!", progress = "Habt Ihr sie? Habt Ihr den Tresor geknackt und Eure privaten Reichtümer aus der Bank geholt?", completion = "He, Ihr habt ja gespart! Ich bin so stolz auf Euch!\n\n&lt;Sassy zählt all Eure Moneten.&gt;\n\nÄh, Boss… Das reicht nicht einmal ansatzweise.", rewards = "Türklopfer der Ersten BankQuastenschuheTresorknackerhandschuheIhr bekommt:\n\nBankräubertasche"}
MultiLanguageQuestData['de'][14123] = {title = "Einfach hereinspaziert", objective = "Beschafft Euch Maltes Falken, die Mona Goblisa und die ultimative Bombe.", description = "Ich habe von unseren Geldproblemen gehört. Es gibt nur einen Weg, wie wir eine Bazillion Moneten zusammenkriegen können: Wir stehlen es von den Reichen!\n\nDieser Schleimer, der Handelsprinz, hat alle möglichen Antiquitäten und wertvolle Kunstgegenstände gestohlen. Es ist an der Zeit, es ihm zu nehmen und den Bedürftigen zu geben... natürlich vor allem uns!\n\nHobart hat eine Kappe zurückgelassen, an der er gearbeitet hat - eine Verkleidung, mit der Ihr genauso ausseht, wie einer von Gallywix' Schergen. Ihr müsst einfach nur in seine Villa spazieren und diese Gegenstände \"sicherstellen\".\n\nPasst aber auf seine Schweine auf. Sie werden Euren Geruch hinter der Verkleidung erkennen!", progress = "Habt Ihr die Waren, Boss?", completion = "Oh, toll! Dieser Kram ist ein Vermögen wert!\n\n&lt;Slinky prüft alles mit geschulten, gierigen Augen.&gt;\n\nIch hoffe nur, dass der Handelsprinz die Sachen nicht bemerkt, wenn Ihr sie ihm mit dem Rest Eures Reichtums übergebt…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14124] = {title = "Schnappt Euch das Kaja'mit", objective = "Sammelt 12 Kaja'mitbrocken.", description = "<Mein Herr/Meine Dame>, wir brauchen einen Haufen Knete, um den Handelsprinzen zu bezahlen und von Kezan weg zu kommen! Und dieser Haufen liegt genau da unten und wartet darauf, mitgenommen zu werden.\n\nDies sind die letzten bekannten Kaja'mitvorkommen. Das ist der Rohstoff, der uns zu den genialen Tüftlern und Alchemisten gemacht hat, die wir heute sind. Wenn das keine Bazillion Moneten wert ist, dann weiß ich auch nicht!\n\nNehmt ein paar meiner Kabummbomben und jagt die Vorkommen in die Luft. Sammelt danach die Kaja'mitbrocken auf.\n\nAber gebt auf die rebellischen Trolle Acht!", progress = "Wie viel Kaja'mit habt Ihr?", completion = "Gute Arbeit, mein Herr, wirklich gute Arbeit! Da habt Ihr ein echtes Vermögen in Euren Taschen.\n\nDamit lässt uns der Handelsprinz sicher auf seine Yacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14125] = {title = "Versicherungsbetrug", objective = "Überlastet den defekten Generator, macht den undichten Ofen an und lasst eine Zigarre auf das leicht entzündliche Bett fallen. Benutzt dann den Gasbot, um den Hauptgeschäftssitz der HGK in Brand zu setzen!", description = "Wir kommen der Sache näher, aber wir haben immer noch nicht genug Moneten. Zu Eurem Glück, Boss, habe ich das vorausgesehen und einen Plan entwickelt. Wir werden die Versicherung des Hauptquartiers einstreichen!\n\nIch habe mir die Freiheit genommen, das übriggebliebene Feuerwerk von Eurer Party an diesem Ort zu verteilen. Alles, was Ihr tun müsst, ist dorthin zu gehen und ein wenig Sabotage zu betreiben.\n\nDarf ich vielleicht den defekten Generator, den undichten Ofen und das leicht entzündliche Bett vorschlagen? Danach geht Ihr wieder nach draußen und schickt einen Gasbot hinein.\n\nEin narrensicherer Plan!", progress = nil, completion = "Das ist noch gar nichts. Ihr solltet den Bilgepier mal sehen… Dort steht alles in Flammen!\n\nGut, gut, ich habe keine Zeit, den Ort unter die Lupe zu nehmen. Hier ist die Knete aus der Versicherung des Bilgewasserkartells.\n\nIch muss einen Weg von der Insel herunter finden. Viel Glück, &lt;Name&gt;!", rewards = "Flammenabweisende PyjamaärmelExplosionsgefährdete ArmschienenGasgetränkte StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14126] = {title = "Lebensersparnisse", objective = "Übergebt Handelsprinz Gallywix auf Gallywix' Yacht auf Kezan Eure Lebensersparnisse.", description = "Wir haben die ganze Knete zusammen. Jetzt müssen wir nur noch eines tun, Boss: Euch zur Yacht des Handelsprinzen schaffen. Sie legt bald ab!\n\nWir müssen uns beeilen. Springt rein! Ich fahre!", progress = "Oh, <Name>, Ihr seid es. Welch unerwartete Überraschung.", completion = "Glückwunsch, Ihr habt es gerade noch geschafft. Wie ich sehe, habt Ihr mir alles gebracht, worum ich Euch gebeten habe, sogar den Hot Rod.\n\n&lt;Ein bösartiges Grinsen huscht über das Gesicht des Handelsprinzen.&gt;\n\nEine Bazillion Moneten war sicher nicht leicht zu beschaffen. Jetzt bin ich der reichste und mächtigste &lt;Volk&gt; in ganz Azeroth.\n\nZU DUMM, DASS ICH DIE BEDINGUNGEN UNSERER VEREINBARUNG JETZT ÄNDERE!\n\nIhr seid ab sofort mein Sklave. Geht unter Deck und leistet Euren Beitrag beim Kohleschaufeln. Nächster Halt: Azshara!\n\nMuhahahahahahaha!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLife Savings: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14127] = {title = "Die Rückkehr der Hochgeborenen?", objective = "Bringt die Befehle des Spähers zu Ag'tor Blutfaust am Hinteren Tor von Orgrimmar.", description = "Das Wachssiegel auf diesen Befehlen wurde erst vom Kurzen aufgebrochen. Ihr könnt die sorgfältig ausgeführte Elfenschrift nicht lesen, aber eine kleine handgemalte Karte deutet auf die nahegelegenen Ruinen. Unter der Karte stehen in einer gänzlich anderen Schrift eine Reihe von Runen in einer metallisch schimmernden Tinte.\n\nAg'tor wird diese wichtige Geheiminformation zweifelsohne sehen wollen.", progress = "Ihr habt bei einer der Leichen etwas gefunden, sagt Ihr? Gebt es mir!", completion = "&lt;Ag'tor hält das Pergament gegen das Licht und begutachtet es.&gt;\n\nNein, ich kann dies ebenfalls nicht entziffern, aber was ich sehe, gefällt mir nicht. Sind das arkane Runen?\n\nIhr müsst dies einem Experten vorlegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14128] = {title = "Die Rückkehr der Hochgeborenen?", objective = "Bringt die Befehle des Spähers zu Malynea Himmelshäscher am Umschlagplatz der Raketenbahn von Orgrimmar.", description = "Unsere Verbündeten, die Blutelfen, haben die Runen auf dieser Karte untersucht und sie können die rätselhafte Schrift vermutlich entziffern. Sucht nach Malynea Himmelshäscher. Sie leitet ihre Untersuchungen vom Umschlagplatz der Raketenbahn von Orgrimmar nördlich von hier. Es ist ein Teil des neuen Transitsystems der Goblins, das sich durch dieses Land zieht. Rasch, jetzt!", progress = "Ich nehme an, bei dieser Unterbrechung handelt es sich um etwas Wichtiges?", completion = "Was? Her damit, sofort! Ag'tor hat Recht. Das sind arkane Runen. Sie erkunden magische Stätten? Experimentieren mit arkanen Künsten? Das ist ein erstaunlicher Bruch mit Jahrtausende alten Traditionen der Nachtelfen.\n\nHmph! Die Vorstellung, dass sie in diesem Bereich irgendwelche Fähigkeiten erlangen, ist absurd. Sogar für diejenigen, die sich selbst einst zu den Hochgeborenen zählten.\n\n&lt;Malynea wirft die Schriftrolle verächtlich beiseite, aber auf ihrer Stirn bilden sich Sorgenfalten.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14129] = {title = "Schredder außer Rand und Band", objective = "Greift einen der entlaufenen Schredder in der Nähe der Tore von Orgrimmar an. Dann setzt Euch hinein, nachdem Ihr ihm erheblichen Schaden zugefügt habt.", description = "Ich habe versucht, unsere neuen Verbündeten der Horde mit der legendären Effizienz der Goblins zu beindrucken, aber im Nachhinein war die Automatisierung der Schredder eine schlechte Idee. Jetzt sind es Tötungsmaschinen, die wahllos durch unsere Ländereien pflügen. Versteht mich nicht falsch, diese Geräte haben ihren Sinn und Zweck, aber jetzt käme <ein mutiger/eine mutige:c> <Klasse> gerade recht, <der/die:c> mir hilft, diese Dinger unter Kontrolle zu bekommen.\n\nEs ist ganz einfach. Automatisierte Schredder müssen, wie alle Maschinen, geprügelt werden, bis sie sich unterwerfen. Danach übernehmt Ihr die Steuerung und ich funke Euch weitere Anweisungen zu.", progress = nil, completion = "&lt;Arbeitsaufseher Grabbits Stimme knistert über das Funkgerät.&gt;\n\nHallo, &lt;Name&gt;! Hört Ihr mich?\n\nEs ist kinderleicht, die Teufelskiste zu fahren. Für die Pedalsteuerung tretet die Pedale und, ähm, bewegt die Hebel für die Hebelsteuerung. Verstanden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14130] = {title = "Freundschaft kennt keine Farbe", objective = "Findet Ergll an der Küste der Ruinen von Arkkoran.", description = "Mein Bruder und ich werden gejagt.\n\nUnser Vatertier wurde kürzlich getötet und der schwarze Drachenschwarm hetzt diejenigen von uns, die noch am Leben sind. Ich bin hier, weil ich Azuregos finden und in Sicherheit bringen will, aber er macht es mir nicht leicht.\n\nAzuregos hat nicht viele Freunde und sein diesbezüglicher Geschmack ist ein wenig... ungewöhnlich. Der Einzige, den ich hier in der Gegend kenne, ist ein Murloc mit Namen Ergll. Ihr solltet ihn an der Küste nordöstlich von hier finden.\n\nTut, was immer vonnöten ist, um Azuregos zu finden, und schickt ihn zu mir.\n\nBitte beeilt Euch.", progress = nil, completion = "Heda! Ein neuer Freund! Bin sehr erfreut, Euch kennenzulernen. Mein Name ist Ergll. Das 'g' wird nicht gesprochen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14131] = {title = "Bohnensammler", objective = "Pflückt 10 Kahpheebohnen von den Pflanzen in den Ruinen von Arkkoran.", description = "Azuregos... Azuregos... Azi? Der Großdrache? Wir sind Freunde, zweifellos! Er brachte mir das Sprechen bei. Er sagte, er mag meinen Farbton... ein Freund von Farben, oder?\n\nKann mich nicht erinnern, wo er hingegangen ist. Hmm... Vielleicht habt Ihr etwas, das meinem Gedächtnis auf die Sprünge hilft?\n\nIch ziehe hier am Strand Kahpheepflanzen. Sie mögen Sand. Ziemlich verrückt.\n\nKönntet Ihr mir ein paar ernten?", progress = "Bin müde, so schwer sich zu konzentrieren.", completion = "Schöne Bohnen! Sie riechen absolut köstlich, oder etwa nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14132] = {title = "Was für eine Frechheit!", objective = "Tötet 10 Makrinnis in den Ruinen von Arkkoran.", description = "Ich würde sie mit ihnen teilen, wenn sie fragen würden. Sie fallen einfach über meine Kahpheepflanzen her. Das ist nicht nett! Ihr könntet ihnen eine Lektion erteilen.\n\nDiese blöden Makrinnis.", progress = nil, completion = "Zu gemein? Nein, nicht zu gemein. Sie haben es verdient.\n\nIch zerstöre ihre Pflanzen doch auch nicht. Hab ich noch nie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14134] = {title = "Holz vor der Hütte", objective = "Verwendet den umprogrammierten Schredder, um 6 Haufen azsharisches Holz zu sammeln. Falls Ihr Euren Schredder verliert, kann ein weiterer angegriffen und umprogrammiert werden.", description = "Jetzt, wo Ihr das Ding unter Kontrolle habt, sammeln wir das Holz ein, das ich mitbringen sollte. Sonst bauen diese Orcs das nächste Katapult aus MIR!\n\nFrisches Holz sollte bereits aufgestapelt in der Gegend sein. Verwendet den Schredder und sammelt so viel auf, wie Ihr könnt.", progress = "Wie läuft die Holzverarbeitung? Ihr solltet sehen, was diese Dinger mit Broccoli anstellen!", completion = "Fantastisch! Ihr habt den Schredder voll beladen. Ihr habt das Ding schon ziemlich gut unter Kontrolle...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14135] = {title = "Auf den Baum", objective = "Verwendet die Motorsäge des Schredders, um die azsharischen Schösslinge niederzumähen, und tötet 9 Heckenschützen von der Talrendisspitze, sobald sie auftauchen.", description = "Haltet kurz still, ich mache die Steuerung für die Hauptmotorsäge betriebsbereit.\n\nHeckenschützen der Nachtelfen von der Talrendisspitze verstecken sich in den Bäumen und greifen meine Arbeiter an. Ich will, dass Ihr diese Heckenschützen erledigt... indem Ihr Euch zunächst um diese Bäume kümmert. Sucht nach azsharischen Schösslingen östlich des Haupttores. Euer Schredder wird wissen, was zu tun ist. Schreddert los!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! So haben wir solche Angelegenheiten damals in Kezan geregelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14136] = {title = "Rettungseinsatz auf See", objective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 8 Berserker der Kvaldir und 3 Harpunierer der Kvaldir an Bord der Feuerfalke tötet.", description = "Die Kvaldir haben auf Hrothgars Landestelle, der kleinen Insel im Norden, ihr Lager aufgeschlagen. Wir haben Kapitän Aerthas Feuerfalke in die Gegend geschickt, aber er und seine Mannschaft sind auf eine Seeräuberbande der Kvaldir gestoßen, die in Richtung Turnierplatz unterwegs war! Nun wird die Feuerfalke von den Seeräubern angegriffen und ihre Mannschaft ist weit in der Unterzahl. Geht dort hinaus und zeigt diesen Kvaldir, weshalb es keine gute Idee ist, die Sonnenhäscher anzugreifen.\n\nDie Feuerfalke befindet sich zwischen Hrothgars Landestelle im Norden und dem Turnierplatz, auf der westlichen Seite der Straße der Meerhäscher.", progress = nil, completion = "Gute Arbeit, Champion. Der Kampf geht weiter, aber nun wissen die Kvaldir, dass wir solche Angriffe nicht dulden.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14138] = {title = "Dienst ist Dienst und Cola ist Cola", objective = "Bringt Sassys Motivation zu Vorarbeiter Feuchtlunte im Hauptgeschäftssitz der HGK auf Kezan.", description = "Wir haben so viele Probleme unten in der Kaja'mine, dass Vorarbeiter Feuchtlunte bald schon Purzelbäume schlägt, so verzweifelt wie er nach Euch sucht. Er murmelte etwas von 'widerspenstigen Trollen'.\n\nDas Kaja'mit, das unsere Trolle abbauen, ist ein wesentlicher Bestandteil unserer Kaja'Cola. Dieses blubberige Zeug bringt uns ein Vermögen und Euch sicher die Beförderung <zum Handelsprinzen/zur Handelsprinzessin> ein!\n\nAber zunächst muss die Produktion wieder ins Rollen kommen. Ihr findet den Vorarbeiter im Osten. Hier, gebt ihm das als Motivation, damit er sich wieder zusammenreißt.", progress = "Äh… alles läuft super. Ja.\n\nWas ist das?", completion = "Ein Geschenk von Sassy? Ich hoffe, es ist ein Bonus!", rewards = nil}
MultiLanguageQuestData['de'][14140] = {title = "Einhalt den Aggressoren", objective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", progress = nil, completion = "Eure Taten haben bewiesen, dass wir Sonnenhäscher dem Argentumkreuzzug um einiges bessere Verbündete sind als der Silberbund, und dass wir es sein werden, die am Ende triumphieren.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14141] = {title = "Gormok will seine Schneebolde", objective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", progress = nil, completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte dem Silberbund die Aufsicht über diese Kreatur gegeben. Die werden sich die Hände schmutzig machen müssen, wenn die Schlacht um die Zitadelle beginnt, und ich habe das Gefühl, dass sie sich als schwache und zimperliche Verbündete erweisen werden.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14142] = {title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", objective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nSie wurden mit Leichtigkeit gefangen genommen und nun schmachtet Kul in einem Käfig auf der Plattform im Lager. Ich bin mir sicher, dass der Kult die Gefangenen opfern wird - es sei denn, wir können sie retten. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", progress = nil, completion = "Kul wird weiterleben und sich wieder lächerlich machen. Und es ist keinesfalls das erste Mal, dass jemand Kul vor sich selbst retten musste. Es sind solche Beispiele, bei denen es einen nicht wundert, dass die meisten Streiter die Gewohnheiten des Silberbunds annehmen.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14143] = {title = "Legt mal ein Bein zu", objective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Girana der Blutgezeichneten auf dem Argentumturnierplatz.", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden es gerne hören, dass wir ein wenig Erfolg hatten. Vielleicht können wir die leicht vergammelten Stücke dem Silberbund geben. Das würde mir den Tag versüßen.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14144] = {title = "Die Barmherzigkeit des Lichts", objective = "Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Zwar kämpfen wir Seite an Seite mit den Kreuzfahrern, aber wir könnten auch von ihnen lernen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "&lt;Girana nimmt das Gebetbuch von Euch entgegen.&gt;\n\nIch danke Euch. Wir sind vielleicht nicht immer einer Meinung mit den Kreuzfahrern, aber ich habe in meiner Zeit hier viel von Beichtpatin Blondlocke gelernt.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14145] = {title = "Was fressen eigentlich Yetis?", objective = "Tylos Dämmerflucht auf dem Argentumturnierplatz möchte, dass Ihr ihm 3 Stück Fleisch eines Nordmeerhais bringt.", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, ein paar Mitglieder des Silberbunds an die Bestie zu verfüttern. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zum Schiff \"Scharlachroter Morgen\" hinunterfliegt, das in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Mitglieder des Silberbunds in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht vom Silberbund behaupten.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14146] = {title = "Verteidigt die Tore!", objective = "Arbeitsaufseher Grabbit will, dass Ihr zurück zum Hinteren Tor von Orgrimmar eilt und dort 20 Räuber der Nachtelfen tötet.", description = "Du meine Güte – was ist hier los?\n\n<Schreie, Rufe und Schlachtgetöse dröhnen über Funk.>\n\n<Name>! Kommt sofort hierher zurück. Eilt zurück zu den Toren. Wir werden angegriffen!\n\nHelft uns, die Eindringlinge abzuwehren. Ich lade Euren Granatenwerfer!!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14151] = {title = "Kardinalsrubin", objective = "Linzy Schwarzbolz in Dalaran möchte, dass Ihr 5 erfolgreiche Transmutationen epischer Edelsteine mithilfe Eurer Alchemiefertigkeit durchführt. Für die Transmutation akzeptable Edelsteine sind Ametrine, Augen von Zul, Schreckenssteine, Königsbernsteine und Fürstenzirkone.", description = "Man sagt, dass der Kardinalsrubin der feinste Edelstein in ganz Nordend ist. Er funkelt wie eine Kristallrose in der Sonne.\n\nBevor ich Euch die Herstellung beibringe, bitte ich Euch, fünf Transmutationen epischer Edelsteine durchzuführen, um auf diese Weise Euren Geist vorzubereiten. Welche Transmutationen Ihr wählt, das liegt bei Euch. Ihr könnt auch mehrmals dieselbe durchführen.\n\nKehrt zu mir zurück, wenn Ihr wirklich bereit seid.", progress = nil, completion = "Sehr gut, &lt;Name&gt;.\n\nDer Trick bei der Sache ist nun, die Ausrichtung der Facetten gerade richtig hinzubekommen...", rewards = "Ihr erlernt:\n\nTransmutieren: Kardinalsrubin\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTransmutieren: Kardinalsrubin\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14152] = {title = "Rettungseinsatz auf See", objective = "Begebt Euch in Richtung des Nordmeers und tötet unter den Angreifern der Schaumkrone 8 Berserker der Vrykul und 3 Harpunierer der Vrykul.", description = "Champion, Kapitänin Schaumkrone und ihr Schiff wurden nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle zu behelligen, als sie von einer Seeräuberbande der Kvaldir abgefangen wurden, die in Richtung Turnierplatz unterwegs war! Unglücklicherweise sind die Kvaldir der Mannschaft an Bord zahlenmäßig um einiges überlegen und gerade dabei, das Schiff zu übernehmen.\n\nIhr müsst Euch auf nach Norden zur Schaumkrone machen, die sich in der Straße der Meerhäscher zwischen dem Turnierplatz und Hrothgars Landestelle befindet, und der Mannschaft helfen, den Angriff abzuwehren. Das Schiff sollte sich auf der Ostseite der Meeresenge befinden.", progress = nil, completion = "Es scheint, als wären die Dinge schlimmer, wie anfangs gedacht. Ihr habt noch immer Tapferkeit gezeigt und dabei viele Besatzungsmitglieder der Schaumkrone gerettet.", rewards = "Ihr bekommt:\n\nSiegel des Champions"}
MultiLanguageQuestData['de'][14153] = {title = "Der Mittelpunkt der Party", objective = "Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.", description = "Oh, wow, Baby! Alle sind gekommen! Wen interessiert da schon so ein blöder Drache?\n\nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Ihr werdet so toll aussehen!\n\nWarum geht Ihr nicht schon einmal rüber zum Pool und unterhaltet die Leute? Ich bin in einer Minute bei Euch... Ich muss nur noch meine Sachen holen.", progress = nil, completion = "Sehr gut, meine Dame. Die Party war anscheinend ein voller Erfolg!\n\nÄh… was ist das denn?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14154] = {title = "Mit knapper Not", objective = "Haltet die Worgen im oberen Bereich des Stadtgefängnisses von Gilneas 2 Minuten lang auf.", description = "Eine dieser räudigen Flohschleudern hat Dempsey ordentlich erwischt. Wir können ihn nicht fortbringen, bevor seine Blutungen nicht gestoppt sind.\n\nMacht Euch nützlich und haltet diese Bastarde zurück. Ein paar Minuten reichen uns schon, <Bruder/Schwester>!", progress = "Wir haben's gleich! Vorsichtig, oder wir verlieren ihn!", completion = "Wir haben's geschafft, &lt;Name&gt;. Dank Euch hat ein guter Mann überlebt.", rewards = "Armschienen des KöniginnentorsDarius' SchärpeDempseys HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14155] = {title = "Arborzid", objective = "Verwendet den Schredder, um das Urtum von der Talrendisspitze zu vernichten. Notfallersatzschredder stehen am Hinteren Tor von Orgrimmar zur Verfügung, wenn Ihr Euren verliert.", description = "Wie steht es um den Schredder? Ich glaube, ich kann Eure Notfallenergievorräte einsatzbereit machen. Das wird Euch wiederaufladen, wenn Ihr beschädigt seid.\n\nHört gut zu. Diese Nachtelfen werden von einem Urtum des Krieges unterstützt, das sich westlich des Tores verwurzelt hat. Es ist ein gigantischer Baumriese. Ihr wisst, was zu tun ist! Legt ihn um!\n\nDafür seid Ihr wie geschaffen!!", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Die Eindringlinge haben sich zurückgezogen. Sie haben mir gesagt, ich sei verrückt, dass ich einen Granatenwerfer auf einem Schredder montiere...\n\nIhr habt mit dem Gerät gute Arbeit geleistet. Mit einer derartig beeindruckenden Darbietung direkt vor der Haustür des Kriegshäuptlings wird die Horde nicht mehr an den Möglichkeiten der Goblintechnologie zweifeln. Ich bin Euch zu großem Dank verpflichtet!", rewards = "ArborzidaxtAbgehackter uralter AstHolzschnitzdolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14157] = {title = "Alte Differenzen", objective = "Sprecht mit Hauptmann Broderick im Steinwallgefängnis in Gilneas.", description = "Lord Darius Crowley ist schon viele Dinge genannt worden. Rebell. Verräter. Terrorist.\n\nVor dem Bürgerkrieg nannte ich ihn einen ... Freund.\n\nIch habe ihn nie dafür verurteilt, einen Aufstand gegen mich angeführt zu haben. Sein Land und seine Bevölkerung waren durch eine zehn Meter hohe Mauer von Gilneas abgeschnitten ... Aber wir hatten keine Wahl.\n\nWie auch immer ... Crowley ist genau die Person, die wir jetzt brauchen.\n\nBetretet das Steinwallgefängnis und fragt Hauptmann Broderick, wo Crowley zu finden ist. Ich würde ja meine eigenen Männer schicken, aber es existiert immer noch böses Blut zwischen uns.", progress = nil, completion = "Graumähne will Crowley retten? Hat er den Verstand verloren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14159] = {title = "Das Arsenal des Rebellenlords", objective = "Sprecht mit Josiah Avery im Militärdistrikt in Gilneas.", description = "Das Arsenal, von dem Crowley spricht, befindet sich in einem Keller westlich von hier.\n\nEs gefällt mir zwar nicht, dass meine Gegner Artillerie in die Stadt geschmuggelt haben, aber sie könnte dabei helfen, gilnearische Leben zu retten.\n\nFindet Josiah Avery und requiriert die Rebellenartillerie. Wir müssen diese Waffen sinnvoll einsetzen.", progress = nil, completion = "Seht mich nicht an! Lasst mich in Ruhe!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Cast Summon Josiah"}
MultiLanguageQuestData['de'][14160] = {title = "Leistungsurkunde", objective = "Liefert die Leistungsurkunde bei Jonas Timotheus in Dalaran ab.", description = "Auf diesem feinen Pergament befindet sich eine Liste mit einer großen Anzahl an Leistungen, die <Name> in der Tradition der Juwelierskunst errungen hat.\n\nBringt diese Urkunde zu Jonas Timotheus nach Dalaran zurück, um eine angemessene Belohnung zu erhalten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nJuwelierssymbol von Dalaran"}
MultiLanguageQuestData['de'][14161] = {title = "Basilisken klatschen", objective = "Tötet 10 Grausteinbasilisken im Tagebau am Gebirgsfuß.", description = "Wir haben diesen ganzen Berg abgetragen, um die Mineralien aus der Mine darunter abzubauen. Aber wir haben nicht bedacht, dass die Basilisken, die dort unterirdisch hausten, nun, also, oberirdisch hausen. Ihr seht so unternehmungslustig aus. Geht dorthin und tötet ein paar dieser Plagegeister und ich greife für Euch einmal tief in unsere Geldvorräte.", progress = nil, completion = "Gut, gut. Eine Sorge weniger.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14162] = {title = "Meldet Euch bei Horzak", objective = "Findet Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar in Azshara.", description = "Ihr habt wirklich gute Arbeit geleistet, als Ihr unsere Holzfällerei zum Laufen gebracht habt. Aber ich habe gehört, dass wir langsam zu wenig Stein haben. Man sollte meinen, wenn wir Berge versetzen können, könnten wir dabei auch ein paar Steine aufsammeln...\n\nNun, das ist nicht mein Problem, aber vielleicht könnt Ihr es zu Eurem machen. Meldet Euch bei Horzak Zignibbel oben am Umschlagplatz der Raketenbahn von Orgrimmar. Findet heraus, ob Ihr ihm dabei helfen könnt, diese Operation in den Griff zu bekommen. Folgt der Straße Richtung Nordosten und Ihr findet ihn im Turm der Raketenbahn.", progress = nil, completion = "Seid Ihr hier, um zu helfen? Ausgezeichnet! Hier, unterzeichnet diesen Abfindungsverzicht. Und hier die Wettbewerbsklausel. Fangen wir an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14163] = {title = "Zu den Waffen: Insel der Eroberung", objective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Brigadegeneral der Allianz in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", description = "Da wir dem Sieg in Eiskrone immer näher kommen, ist es deutlicher geworden, dass sich unsere Armeen mit der Horde auseinandersetzen müssen, bevor sie sich um den Lichkönig kümmern können.\n\nSie haben die Elitewache bekannt als die Kor'kron eingesetzt, um unseren Vormarsch auf der Insel der Eroberung aufzuhalten. Die Insel ist von äußerst wichtiger strategischer Bedeutung, <Name>. Seht zu, dass unsere Jungs gewinnen!", progress = nil, completion = "Die Horde wird es mit unseren Streitkräften nie aufnehmen können, so lange wir Leute wie Euch auf unserer Seite haben, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][14164] = {title = "Zu den Waffen: Insel der Eroberung", objective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Kriegshetzer der Horde in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", description = "Der Sieg in Nordend wird bald unser sein... doch nicht bevor wir in Eiskrone Fuß gefasst haben, um für den Transport und die Versorgung unserer Truppen zu sorgen.\n\nDie Insel der Eroberung ist ein idealer Ort. Sie ist einfach zu verteidigen und reich an Ressourcen. Die Allianz ist zu demselben Schluss gelangt und hat die 7. Legion ausgesandt, um unseren Streitkräften die Kontrolle zu entreißen.\n\nGeht, <Name>, und sorgt dafür, dass die Horde um jeden Preis die Oberhand gewinnt!", progress = nil, completion = "Nichts wird sich zwischen uns und den endgültigen Sieg stellen. Für die Horde!", rewards = "Ihr bekommt:\n\nEroberungspunkteArenapunkte"}
MultiLanguageQuestData['de'][14165] = {title = "Kalt wie Stein", objective = "Holt einen versteinerten Bergfußminenarbeiter aus dem Tagebau am Gebirgsfuß und bringt ihn zurück zu Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar.", description = "Die Arbeiter tun fast so, als bestünde Ihre Hauptaufgabe darin, sich zu beschweren. Wenn es nicht die harte Knochenarbeit, die Überstunden oder die geringe Bezahlung sind, ist es die Tatsache, dass sie von den Basilisken in Stein verwandelt werden. Irgendwas ist immer!\n\nAber ich glaube inzwischen, dass dieses ganze Arbeiter-in-Stein-Verwandeln ein echtes Geschäft für mich werden könnte. Was ist, wenn diese Leute jetzt hochwertiges Gestein sind? Meine jammernden Beschäftigten könnten für mich als Luxusbaumaterial mehr wert sein als als Arbeiter! Schnappt Euch einen versteinerten Bergfußminenarbeiter und schleppt ihn zu mir.", progress = nil, completion = "Gut, gut, nun sehen wir uns mal an, was wir hier haben...\n\n&lt;Horzak untersucht die zerschmetterten Überreste des armen versteinerten Minenarbeiters.&gt;\n\nPah! Bröckelig! Unbrauchbar. Der gäbe nicht einmal eine gute Arbeitsplatte ab. Meine Bergarbeiter sind vielleicht mittelmäßige Arbeiter, aber sie geben lausige Steine ab.\n\n&lt;Seufz.&gt; Nun, ich nehme an, wir sollten diesen Arbeiter wieder verfleischlichen, sodass ich einen Teil meiner Investition zurückbekomme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14166] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist aus Dalaran auf dem Friedhof von Dalaran.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", progress = "Ihr habt keine Totenspeise, oder?", completion = "Oh, noch mehr köstliche Totenspeise, vielen Dank!\n\nHier, bitte, nehmt dies als Gegenleistung... eine kleine amüsante Aufmerksamkeit für die Feiertage.", rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14167] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Zwergengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14168] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Gnomengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14169] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Draeneigeist auf dem Friedhof der Exodar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14170] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Nachtelfengeist auf dem Friedhof von Darnassus.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14171] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Blutelfengeist auf dem Friedhof von Silbermond.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14172] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist eines Anhängers der Aldor auf dem Friedhof von Shattrath.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14173] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist eines Anhängers der Seher auf dem Friedhof von Shattrath.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14174] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Verlassenengeist auf dem Friedhof von Unterstadt.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", progress = "Ihr habt keine Totenspeise, oder?", completion = "Oh, noch mehr köstliche Totenspeise, vielen Dank!\n\nHier, bitte, nehmt dies als Gegenleistung... eine kleine amüsante Aufmerksamkeit für die Feiertage.", rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14175] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Orcgeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14176] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Taurengeist auf dem Friedhof von Donnerfels.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14177] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Trollgeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][14178] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Realität eines Kampfes an mehreren Fronten ist, dass wir unsere Streitkräfte nicht zu dünn verteilen dürfen, sonst riskieren wir nämlich alles zu verlieren!\n\nVon Tag zu Tag sind äußerst wichtige Truppeneinsätze vonnöten. Heute sind es unsere Streitkräfte in der Schlacht im Arathibecken, die umgehend Verstärkung benötigen.\n\nBringt mir die Siegesnachricht, <Name>. Wir können dem Abschaum der Horde nicht erlauben, jene Ressourcen zu sichern, die rechtmäßig uns gehören!", progress = nil, completion = "Das sind gute Neuigkeiten, &lt;Klasse&gt;! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", rewards = "Ihr bekommt:\n\nArenapunkte"}
MultiLanguageQuestData['de'][14179] = {title = "Ruf zu den Waffen: Auge des Sturms", objective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Der Kampf gegen die Horde kennt keine Grenzen, <Name>. Selbst in der Scherbenwelt reichen territoriale Zwistigkeiten und alte Feindschaften aus, um das Gleichgewicht zu stören und Krieg hervorzurufen.\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz in der Scherbenwelt die Oberhand gewinnt, genauso wie sie es in Azeroth getan hat.", progress = nil, completion = "Wir sind dem endgültigen Sieg über die Horde wieder einen Schritt näher gekommen. Niemals dürfen wir zulassen, dass der Feind sich einen Brückenkopf in dieser oder in irgendeiner anderen Welt sichert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14180] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Schildwache der Silberschwingen kämpfen in der Kriegshymnenschlucht zum Schutze des Waldes. Wir unterstützen sie nicht deswegen, weil wir eine Liebe für Bäume haben, sondern weil der Wald dem Territorium der Allianz als natürliche Schutzbarriere dient.\n\nIhre Not ist heute größer als je zuvor. Wir müssen umgehend Verstärkung einsetzen, wenn wir nicht dabei zusehen wollen, wie das Eschental an das Brachland angegliedert wird!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14181] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, <Klasse>! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", progress = "Ihr seid schon zurück? Bringt Ihr Siegesnachrichten?", completion = "Ihr habt der Horde heute ehrenvoll gedient, &lt;Name&gt;. Der heutige Sieg sichert uns tausend weitere Siege!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14182] = {title = "Ruf zu den Waffen: Auge des Sturms", objective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wir werden den Feind bekämpfen und vernichten, wo auch immer wir ihn finden. Azeroth, die Scherbenwelt - der Ort spielt keine Rolle.\n\nWir können der Allianz nicht erlauben, im Auge des Sturms die Übermacht zu gewinnen. Tragt noch heute die Schlacht zu ihnen... Morgen könnte es schon zu spät sein!", progress = nil, completion = "Ihr ehrt uns alle, &lt;Name&gt;. Wir müssen dem Feind zeigen, dass wir ihn immer und überall bekämpfen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14183] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Allianz ist ein heimtückischer Feind, <Name>. Sie behaupten, die Wälder des Eschentals zu verteidigen, um ihre Aggressionsakte gegen unsere Territorien im Brachland zu rechtfertigen.\n\nHeute haben wir die Möglichkeit, den Feind ein für alle Mal von unserem Land zu verjagen. Geht in die Kriegshymnenschlucht und holt zurück, was rechtmäßig uns gehört!", progress = nil, completion = "Die Horde steht in Eurer Schuld, &lt;Name&gt;. Euer Mut und Einsatz während der Verteidigung unseres Landes macht uns alle stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14184] = {title = "Meine Zeit ist um", objective = "Furien in Tethris Aran will, dass Ihr auf seinem Drachenfalken zu Furiens Posten reitet und seine Schwester Cerelia über seinen Tod unterrichtet.", description = "<Furien winkt Euch mit einer schwachen Geste zu sich heran. Er hat Schwierigkeiten, zu sprechen.>\n\nLeichtsinnig... Ich wurde von der Allianz niedergeschossen...\n\nIhr müsst... meiner Schwester Bescheid geben.\n\nNehmt mein Reittier, <Volk>... Es bringt Euch zu ihr...\n\n<Furien stirbt.>", progress = nil, completion = "Was!?\n\nFurien!! Mein Bruder lebt nicht mehr?\n\nSie werden dafür bezahlen! Allesamt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14188] = {title = "Rächt Furien!", objective = "Cerelia will, dass Ihr mit Sorrem in Furions Posten sprecht.", description = "Das darf nicht sein!\n\nMein geliebter Bruder – vernichtet vom Abschaum der Allianz!\n\nSie sollen Leiden, <Volk>! Findet eine Möglichkeit, ihnen Schmerzen zu bereiten! Ich werde nicht ruhen, bis das erledigt ist...\n\nFurien hat vor seinem Tod uralte Artefakte in den östlichen Regionen untersucht. Sprecht mit Sorrem. Vielleicht kann er Euch die Spuren meines Bruders weisen.", progress = nil, completion = "Furiens Dahinscheiden ist... bedauerlich.\n\nIch werde alles tun, was ich kann, um Euch bei dabei zu helfen, seinen Tod zu rächen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14189] = {title = "Übersetzung", objective = "Sorrem will, dass Ihr die uralten Schrifttafeln findet.\n\nSprecht mit Narimar in Furions Posten, um dorthin zu reiten, wo Furien seine Nachforschungen betrieben hat.\n\nBereitgestellter Gegenstand: \n", description = "Es stimmt, dass Furien seine letzten Tage einem besonderen Forschungsprojekt gewidmet hat. Worum es dabei genau ging, wollte er mir nicht sagen.\n\nGlücklicherweise war ich in der Lage, sein Tagebuch in meinen Besitz zu bringen, aber es ist in einem Code geschrieben, den ich nicht entschlüsseln kann.\n\nVielleicht gibt es einen Dekodierungsschlüssel für seine Übersetzung in der Region im Osten, wo er viel Zeit verbracht hat.\n\nNehmt das Tagebuch, <Klasse>, und sprecht mit Narimar, wenn Ihr bereit seid, dieses Geheimnis zu untersuchen.", progress = nil, completion = "Beim Vergleich der Buchstaben der uralten Schrifttafel mit denen in Furiens Tagebuch fällt auf, dass es deutliche Entsprechungen gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14190] = {title = "Das perfekte Prisma", objective = "Gelangt in den Besitz eines Kristallanhängers von einem Saboteur der Talrendisspitze im Tagebau am Gebirgsfuß.", description = "Es muss eine Möglichkeit geben, die Versteinerung durch die Basilisken wieder rückgängig zu machen. Diese lästigen Saboteure der Nachtelfen, die schon länger um meine Mine schleichen, müssen etwas wissen, was uns entgeht. Sie scheinen gegen den Blick der Bestien immun zu sein!\n\nIch will, dass Ihr ihr Geheimnis herausfindet, <Name>. Greift Euch ein paar der Saboteure der Talrendisspitze, die im hinteren Teil des Tagebaus herumschleichen, und holt Euch eine Probe des Zaubers oder Schnickschnacks oder was auch immer ihnen ihre Immunität verleiht. Funkt mich vom Hauptgebäude der Schmiede aus an, sobald Ihr Erfolg hattet.", progress = "<Skurrile Goblinlautsprecher rauschen und knacksen.>", completion = "&lt;Zignibbles Stimme quäkt über die Lautsprecher.&gt;\n\n&lt;Name&gt;, seid Ihr das? Seid Ihr noch am Leben? Ihr vergeudet doch nicht meine Sprengstoffvorräte, oder?\n\nHmmm... Ihr sagt, ihr hättet einen Kristallanhänger gefunden. Das ergibt Sinn. Ein perfektes Prisma würde den Blick des Basilisken brechen. Vielleicht können wir das zu unserem Vorteil ausnutzen. Zeit für ein wenig Wissenschaft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14191] = {title = "Auf Furiens Spuren", objective = "Die uralten Schrifttafeln am Schrein von Elune haben Euch den Weg zu dreien der markanten Ruinen in Sargeron gewiesen.", description = "Ihr könnt die Einzelteile des Textes entschlüsseln, aber es wird ausführlicher Studien bedürfen, bevor Furiens Arbeit einen Sinn ergeben wird.\n\nJetzt seht Ihr in den Nordosten und glaubt, dass Ihr ein paar Ruinen ausmachen könnt, die in dem Tagebuch abgebildet sind.\n\nSofern Ihr das beurteilen könnt, scheinen diese Ruinen für Furiens Forschungen eine Rolle gespielt zu haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14192] = {title = "Tausche Linse gegen Prisma", objective = "Bringt den Kristallanhänger zur Waffenkiste im Hauptquartier des Tagebaus am Gebirgsfuß.", description = "Wenn Euer Prisma darauf eingestellt ist, den Blick des Basilisken zu brechen, können wir die Eigenschaften des Kristalls dazu verwenden, den Verwandlungsprozess umzukehren. Alles was wir brauchen, ist eine Energiequelle.\n\nIn der Waffenkiste zu Eurer Rechten findet Ihr den Prototyp eines Laser-Bergbaubohrers. Ich liebe das Teil, aber es wurden fast täglich Leute damit zerstückelt. Das fing irgendwann an zu nerven. Schnappt Euch den Laserbohrer und tauscht seine Linse gegen Euren Kristall aus...", progress = "<Der Waffenschrank ist vollgestopft mit grässlichen und kaputten Experimentalgeräten. An einigen von ihnen hängen noch Gliedmaßen von Goblins. Ihr entdeckt den Laserbohrer, der liebevoll in einen samtgefütterten Holzkasten gebettet wurde.>", completion = "&lt;Ihr löst das Linsenelement und lasst den Kristall an seinen Platz rutschen. Die Waffe summt unheilvoll.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14193] = {title = "Nichts, was ein paar Melonen nicht richten können", objective = "Sammelt 8 Melonenfrüchte", description = "Die Markierungen auf den Ruinen hier machen eine Sache deutlich: Mit dem uralten Brunnen im Heiligtum von Elune scheint es etwas Besonderes auf sich zu haben.\n\nEs scheint, dass er demjenigen besondere Kräfte verleiht, der sein Gesicht in seinem Wasser wäscht. Als erstes muss es im uralten Brunnen natürlich etwas geben, mit dem man sich waschen kann.\n\nWährend Ihr über dieses Problem nachdenkt, bemerkt Ihr eine Melone an den Wurzeln eines Baumes...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14194] = {title = "Wiederverfleischlichung", objective = "Verwendet den Wiederverfleischlicher, um acht Bergfußminenarbeiter im Tagebau am Gebirgsfuß wieder zu entsteinern.", description = "<Das nahegelegene Funkgerät ruft Euch etwas zu.>\n\nHey <Name>, habt Ihr den Laser? Gut! Schaut niemals direkt hinein.\n\nZielt mit dem Schätzchen auf meine versteinerten Arbeiter und das gebrochene Licht sollte den Versteinerungsprozess umkehren. Oder er schmilzt sie. Auch egal. Sorgt dafür, dass meine Arbeiter mir wieder Profit bringen! Und falls der Wiederverfleischlichungsprozess dafür sorgt, dass sie irre werden, solltet Ihr sie töten. Wegen der Versicherung. Horzak ENDE!", progress = "Na sieh mal einer an. Alle Eure Gliedmaßen sind in Ordnung.", completion = "Ah, gut. Jetzt können sich diese Faulpelze wieder an die Arbeit machen. Ihr habt Euch einen Teil des Gewinns verdient – abzüglich der üblichen Gebühren für die Gesellschaft. Wählt!", rewards = "Wiederbefleischte ArmschienenSteinifizierungsgewehrIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14195] = {title = "Ein Schleier lichtet sich", objective = "Furiens Tagebuch hat Euch angewiesen, die Ruinen des Palastes von Elune im Norden Sargeron zu suchen.", description = "Irgendetwas ist anders... Vielleicht eine Nebenwirkung von Elunes Reinigungsrituals.\n\nWährend Ihr noch weit davon entfernt seid, die uralte Sprache perfekt zu verstehen, haben sich Eure Kenntnisse jedoch deutlich verbessert.\n\nFuriens Enthusiasmus scheint sich vor allem auf die Ruinen in den nördlichen Bergen von Sargeron zu beziehen. Er hatte das Gefühl, dort sei irgendetwas, das ihm helfen würde, die Allianz aus dieser Region zu vertreiben.\n\nIhr klappt das Tagebuch zu und seid fest entschlossen, diese Ruinen zu finden und ihnen ihre Geheimnisse zu entlocken.", progress = nil, completion = "Nun ist es Euch klar, warum Ihr hierher geführt wurdet.\n\nIhr erkennt diesen uralten Runenstein aus Furiens letztem Tagebucheintrag: \n\n\"Die Uralten verehrten die Edelsteine, die von diesem mystischen Objekt erschaffen wurden und sie behaupteten, dass es Geschenke der Göttin selbst seien. Sie glaubten, es handele sich um Waffen, die in der Lage sind, sie von jedem Feind zu erlösen.\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14196] = {title = "Feuerteufel", objective = "Ihr müsst einen tobenden Vortex erzeugen, indem Ihr 7 Anhänger von Elune mit Eurem Feuersturm vernichtet.\n\nSolltet Ihr Euren Vortexedelstein verlieren, erhaltet Ihr einen weiteren aus dem uralten Vortexrunenstein.", description = "Ihr seid nun in der Lage den Text aus dem Tagebuch zu verstehen.\n\nAuf den Runensteinen steht geschrieben, dass den Edelsteinen des Monuments die Macht innewohnt, einen Feuersturm zu entfesseln.\n\nDer Sturm könnte zu einer mächtigen Waffe werden, indem Elune ausdauernd gehuldigt würde oder indem man ihn mit der spirituellen Energie der Gefallenen auflädt.\n\nIhr betrachtet die kürzlich aufgetauchten Geister von Elunes Anhängern und kommt zu dem Schluss, dass Ihr weder die Zeit noch die Neigung dazu habt, der Göttin Eures Feindes zu huldigen...", progress = nil, completion = "Es ist vollbracht! Furiens ausdauernde Forschung war nicht vergebens.\n\nDer tobende Vortex steht endlich bereit und kann auf Eure Feinde losgelassen werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14197] = {title = "Ein zu erfüllendes Pensum", objective = "Sammelt 20 Barren Gebirgsfußeisen aus dem Tagebau am Gebirgsfuß in Azshara.", description = "Gebirgsfußeisen ist eine spröde Legierung, aber es erfüllt die Sicherheitsstandards der Goblins – wenn man die richtigen Leute schmiert. Zignibbel hat Schwierigkeiten bei der Produktion, aber das ändert nichts an meinen Fristen. Ich habe ein Pensum zu erfüllen!\n\nBegebt Euch in den Tagebau am Gebirgsfuß und sammelt so viel Barren Gebirgsfußeisen, wie Ihr finden könnt. Sie sollten dort stapelweise herumliegen und bereit zum Transport sein.", progress = "Habt Ihr die Lieferung?", completion = "Gute Arbeit! Wenn es um Eisen geht, ist mir die Quantität immer wichtiger als die Qualität.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14198] = {title = "Vortex der Vergeltung", objective = "Setzt den Edelstein des tobenden Vortexes gegen die Ruine der Nijelspitze ein. Während ihr den Feuersturm befehligt, tötet 40 Verteidiger der Nijelspitze und verbrennt 15 Händler der Nijelspitze.\n\nSolltet Ihr Euren Vortexedelstein verlieren, erhaltet Ihr einen weiteren aus dem uralten Vortexrunenstein.", description = "Ihr könnt Euch eines Anflugs von Stolz nicht erwehren, dass Ihr dieses lang verlorene Geheimnis der uralten Verehrer von Elune aufgedeckt habt.\n\nIhr besitzt nun die Macht, Eurem Feind großen Schaden zuzufügen.\n\nDa nur Furiens unermüdliche Arbeit dies ermöglicht hat, scheint es nur gerecht, dass diese Waffe auf diejenigen losgelassen werden sollte, die für seinen Tod verantwortlich sind.\n\nDer Abschaum der Allianz auf der Nijelspitze soll für den Angriff auf die Horde bezahlen!", progress = nil, completion = "Äußerst beeindruckend, &lt;Klasse&gt;.\n\nIhr habt Furiens Arbeit abgeschlossen und Rache auf seine Mörder herabregnen lassen.\n\nIhr habt der Seele meines Bruders Frieden gebracht und meinem Geist ebenfalls. Bitte nehmt dieses Geschenk zum Dank für Euren Einsatz.", rewards = "Umhang der geschickten FingerAuf Euch wartet eine dieser Belohnungen:\n\nFuriens GelassenheitFeuergarbenhalsband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14199] = {title = "Todesbeweis: Der Schwarze Ritter", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Seelenfragment des Schwarzen Ritters bringt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \"Heroisch\" abgeschlossen werden.", description = "Mein Berufsgenosse, Erzmagier Timear hat mich gebeten, Euch vor etwas Schrecklichem zu warnen. Bald werdet Ihr an der Prüfung der Champions im Argentumkolosseum in Eiskrone teilnehmen. Nehmt Euch in Acht, denn es wird sich jemand einmischen, den sie den Schwarzen Ritter nennen.\n\nBringt mir ein Fragment seiner Seele, damit die Kirin Tor wissen, dass er erledigt ist. Mir wurde gesagt, dass, solltet Ihr versagen, dies Euer eigenes Verderben sei.", progress = "Ist es so, wie Timear es vorhergesehen hat? Ist der Schwarze Ritter unerwartet aufgetaucht?", completion = "Es ist gut zu sehen, dass Ihr siegreich aus der Prüfung hervorgegangen seid. Wahrlich, Ihr seid ein Champion - und zwar nicht nur für den Argentumkreuzzug, sondern in der Tat auch für die Kirin Tor.\n\nMan kann nur hoffen, dass Ihr dem dunklen Bösewicht den letzten Stoß verpasst habt und es das Letzte sein wird, das wir von ihm gesehen haben.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des Triumphs"}
MultiLanguageQuestData['de'][14201] = {title = "Tausende Geschichten im Sand", objective = "Sammelt 5 geborgene Artefakte aus den Ruinen um den Mennarsee in Azshara.", description = "Die Ruinen um den Mennarsee im Osten erzählen eine Geschichte. Die niedrigeren Völker – wie diese plumpen Zwerge – würden mit Hacken und Schaufeln nach der Wahrheit suchen. <Malynea rümpft ihre Nase.> Wir werden ein wenig elegantere Verfahren einsetzen.\n\nMeine Wahrsagemagie ist ein wenig eingerostet, aber mit dem richtigen Schmuckstück sollte ich in der Lage sein, durch den Vorhang der Zeit zu sehen. Die Gebeine meiner Vorväter sind längst zu Staub zerfallen, aber ein paar ihrer persönlichen Schätze könnten noch existieren. Bringt sie mir.", progress = "Habt Ihr Euch für mich die Hände schmutzig gemacht?", completion = "&lt;Malynea zieht die Augenbrauen zusammen und besieht die Artefakte, die Ihr ihr gebracht habt.&gt;\n\nDie Geister der Toten gehen also noch immer in diesen alten Gemäuern um, wie? Nun, &lt;Name&gt;, ich zähle auf ihre Hilfe. Hören wir uns an, was die Toten zu sagen haben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14202] = {title = "Inspiziert das Seeufer", objective = "Begleitet den Goblinfeldmesser zu den drei Feldmessgeräten, die um den Mennarsee herum aufgestellt sind. Verteidigt ihn, während er die Geräte abliest. Ein weiterer Feldmesser kann stets über das Feldmesssignal herbeigerufen werden.", description = "All diese verflixten uralten Ruinen müssen dem Erdboden gleichgemacht werden, wenn wir jemals Azsharas ganzes Potenzial sehen wollen. Werft einen Blick auf meine Karte hier. Seht Ihr den Mennarsee im Osten? Ich kann Euch sagen, was ich dort sehe: ein zukünftiges Lager für Raketentreibstoff!\n\nAber der Boden muss eine ganz besondere Beschaffenheit haben, bevor wir ihn abmähen, planieren, aufschütten und den See ebnen können. Meine Landvermesser wurden bisher alle von dem gespenstischen Spuk in der Region vergrault. Begleitet einen meiner Nachwuchsfeldmesser in das Gebiet und sorgt dafür, dass er die Ergebnisse der Messausrüstung ablesen kann, die dort aufgestellt wurden.", progress = "Ein Rudel toter Elfen kann den Fortschritt doch nicht aufhalten. Nicht solange ich noch was zu sagen habe!", completion = "Wundervolle Arbeit! Jetzt, wo wir die Region besser kennen, können wir uns des Sees annehmen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14203] = {title = "Durchnässtes Rezept", objective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][14204] = {title = "Aus den Schatten", objective = "Besiegt 6 Blutfanglauerer.", description = "Er hat sich in einen von ihnen verwandelt ... nicht wahr? Wie sollen wir uns nur gegen einen Gegner behaupten, der etwas Derartiges anrichten kann?\n\nDas Arsenal meines Vaters ist bestimmt ein guter Anfang, denke ich.\n\nWorgen verbergen sich in den umliegenden Gassen. Nehmt einen meiner Mastiffs mit, um sie leichter finden zu können.\n\nWir müssen den Weg freiräumen, wenn wir diese Kanonen über Land bewegen wollen.", progress = "Ist die Aufgabe erledigt, <Name>?", completion = "Hervorragend. Ich werde ein paar Leute zusammentrommeln, um diese Kanonen in Position zu bringen.", rewards = "Streitkolben des AlarmbringersArmbrust des HundemeistersZauberstab des MastiffausbildersDer folgende Zauber wird auf euch gewirkt:\n\nSeuchenhund freigeben\n\nIhr bekommt:\n\nVerwitterter Stab"}
MultiLanguageQuestData['de'][14209] = {title = "Motorschaden", objective = "Untersucht Clubniks Planierraupe und sammelt eine Probe des Ektospritzers ein, der den Motor verklebt.", description = "Diese uralten Ruinen haben zehntausend Jahre Wind und Wetter überstanden. Also habe ich meine größte und beste Planierraupe dorthin geschickt, um sie dem Erdboden gleichzumachen. Ich nenne sie 'Margene'.\n\nAber meine Raupe lässt mich neuerdings im Stich, <Name>. In dem Augenblick, als ich mit ihr in diese verwunschenen Wälder gefahren bin, hat Ihr Motor mit einem markerschütternden Heulen den Geist aufgegeben. Jetzt sagen mir meine Ingenieure, dass irgendetwas ihre Ventile verstopft. Geht dorthin und untersucht Margenes Motorblock und bringt mir eine Probe von dem, was auch immer ihn blockiert.", progress = "Margene ist eine Höllenmaschine, nicht wahr?", completion = "Ich glaub, mein Kugellager knirscht! Seht Euch dieses Zeug an – igitt, RIECHT mal an diesem Zeug – meine arme, arme Raupe!\n\n&lt;Name&gt;, ich halte mich selbst für einen Klebstoffspezialisten. Ich sage, dieses Klebzeug ist nicht natürlichen Ursprungs. Es ist übernatürlich. Das ist Geisterklebstoff. Dafür brauchen wir mehr als nur einen Mechaniker...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14212] = {title = "Aufopferung", objective = "Reitet mit Lord Darius Crowley und treibt 30 Blutfangpirscher zusammen.", description = "Ihr müsst das nicht tun, <Name>. Ihr habt bereits mehr als genug getan.\n\nAber wenn Ihr Euch entschließen solltet, zu bleiben ... Ich wäre ein Narr, Euch abzuweisen.\n\nMeine Mannen haben ihre Position in der Kathedrale befestigt und sind bereit für alles, was da kommen mag.\n\nIch werde mich nun auch dorthin aufmachen und so viele von diesen flohzersetzten Teufeln mit mir nehmen, wie ich nur kann. Seid willkommen, wenn Ihr mich zu diesem Tanz begleiten wollt.", progress = nil, completion = "Macht Euch bereit, &lt;Name&gt;.\n\nHier kommen sie!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Bind Post-Sacrifices\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14213] = {title = "Zehn Pfund Fleisch", objective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", description = "Furiens Tagebuch nach zu urteilen, wurde dieses uralte Kohlenbecken hier aufgestellt, um Opferrituale durchzuführen.\n\nSoweit Ihr das vom Eingang aus erkennen könnt, wird derjenige gesegnet, der das Fleisch von Elunes Feinden auf die brennenden Glutspäne im Kohlenbecken legt.\n\nIhr seht Euch um und beschließt, dass die Satyrn, welche die Region derzeit beherrschen, sicherlich als Feinde bezeichnet werden könnten.", progress = "Das Becken erwartet still eine Opfergabe.", completion = "Das göttliche Becken versieht Euch unhinterfragt mit einem Segen.", rewards = "Ihr erlernt:\n\nGöttliche Stärkung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14214] = {title = "Nachricht für Graumähne", objective = "Sprecht mit König Graumähne im Militärviertel.", description = "Es ist soweit, <Name>. Ab hier übernehmen wir.\n\nSagt König Graumähne, dass er über das Arsenal meines Vaters verfügen kann. Es beherbergt ausreichend Feuerkraft, die Worgen von hier bis zum Nordmeer zu schießen.", progress = nil, completion = "Ich wusste, dass Crowley uns helfen würde. Seine Waffen werden uns äußerst nützlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14215] = {title = "Die Erinnerung der Toten", objective = "Bringt Kalythas Ring zum Ufer des Mennarsees. Berührt den Geist von Kalytha, um ihre Erinnerungen noch einmal zu erleben. Sprecht mit den anderen Geistern, bis Ihr das Geheimnis des Mennarsees gelüftet habt.", description = "Die Runen auf diesem Ring, den Ihr gefunden habt, sind noch immer lesbar. Er wurde einer 'Kalytha' überreicht, als sie in die Akademie aufgenommen wurde. Mit ein oder zwei richtigen Zaubersprüchen ist dies das Tor zu Ihrer Seele.\n\nBringt den Ring zurück zum Mennarsee. Kalythas Geist sollte jetzt für Euch sichtbar sein, wenn ihr am Ufer des Sees steht. Berührt sie und der Ring wird es Euch ermöglichen, die Welt so zu sehen, wie sie ihr erscheint, und ihr könnt ihre letzten Stunden miterleben. Durchforstet ihren Geist, <Name>! Sprecht mit den anderen und löst das Geheimnis des Mennarsees...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14216] = {title = "Das Geheimnis des Sarsensteins", objective = "Holt den Sarsenstein vom Grund des Mennarsees herauf.", description = "Bevor sie starb, bekam Kalytha die Aufgabe, etwas auf dem Grunde des Sees zu vergraben: ein mächtiges Artefakt, das die Erzmagier von Mennar in ihren letzten Minuten erschufen. Zweifelsohne wird Malynea Himmelshäscher dieses Artefakt sehen wollen, vorausgesetzt es existiert noch. Ihr beschließt den Grund des Mennarsees nach dem Sarsenstein abzusuchen.", progress = "Habt Ihr am See etwas entdeckt? Ihr seid klitschnass.", completion = "Ein Sarsenstein? Die sind eine Legende – zeigt mal her!\n\n&lt;Name&gt;, Sarsensteine wurden verwendet, um die magischen Energien der Leylinien umzulenken. Ist Euch eigentlich klar, was das bedeutet? Die Magier von Mennar blieben nicht aus fehlgeleiteter Loyalität zurück. Sie haben Ihr Leben geopfert, um dieses Artefakt zu erschaffen. Sie versuchten damit, dem Portal Energie zu entziehen, durch das die Dämonen nach Azeroth strömten. Sie haben Zeit gewonnen, damit der Rest der Welt zurückschlagen konnte! Ihre Tat fand in den Geschichtsberichten niemals Erwähnung. Was für eine Entdeckung!", rewards = "WassertreterstiefelWiederhergestellte Mennarische KettenrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14217] = {title = "Satyrisches Opfer", objective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", description = "Es erheitert Euch, dass dieses uralte Relikt Euch mit einem Segen ausgestattet hat, der eigentlich für Eure Feinde gedacht war.\n\nIhr seid entschlossen, so viel Nutzen wie möglich aus dieser unbeabsichtigten Gabe zu ziehen.", progress = nil, completion = "Das göttliche Becken versieht Euch unhinterfragt mit einem Segen.", rewards = "Ihr erlernt:\n\nGöttliche Stärkung"}
MultiLanguageQuestData['de'][14218] = {title = "Mit Blut und Asche", objective = "Tötet 80 Blutfangpirscher mit den Kanonen der Rebellen.", description = "Der Augenblick ist gekommen, <Name>. Wenn wir ihre Zahl signifikant reduzieren wollen, müssen wir jetzt handeln.\n\nWir verfügen über die richtige Position.\n\nWir verfügen über die nötige Feuerkraft.\n\nAlles, was noch fehlt, ist der Beweis, dass wir über ausreichend Mut verfügen... und ich bin mir sicher, dass ich keinen Feigling vor mir stehen sehe.", progress = "Wir müssen so viele wie möglich von denen erledigen, <Name>.", completion = "Ihr habt Euch wohl geschlagen, &lt;Name&gt;. Ihr habt mehr für uns getan, als von jedem Gilneer verlangt werden könnte.\n\nDie Munition geht uns aus. Wir müssen uns drinnen neu formieren.", rewards = "Standfeste StiefelGamaschen des KanoniersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14219] = {title = "Zu den Waffen!", objective = "Ihr sollt Euch 20 Satyrsäbel aus den Waffenregalen und von den Satyrn aus der Gegend besorgen. Dann legt sie auf die Statue von Elunes Dienstmaid.", description = "Ihr erkennt diese Statue sofort aus den Skizzen in Furiens Tagebuch.\n\nObwohl Euch der mit dem Eintrag verbunden Text nicht gegenwärtig ist, scheint diese Zeichnung selbsterklärend zu sein. Nach der Schlacht sollten die Waffen der Feinde dem Becken dargereicht werden, um im Austausch dafür ein göttliches Geschenk zu erhalten.\n\nAls Ihr über das Ritual nachdenkt, bemerkt Ihr das Funkeln von Stahl in einem nahegelegenen Waffenregal...", progress = "Die Statue steht erwartungsvoll da.", completion = "Als Ihr das Ritual abgeschlossen habt, erwartet Euch eine göttliche Gabe.\n\nIhr fragt Euch unwillkürlich, was Elune davon halten würde, dass jemand wie Ihr eines ihrer Geschenke entgegennimmt.", rewards = "Sandalen des RitualsVergoldeter KürassSchwerer GurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14220] = {title = "Dies ist das Ende", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14221] = {title = "Niemals aufgeben, nur manchmal zurückziehen", objective = "Sprecht mit Darius Crowley in der Kathedrale des Erwachenden Lichts.", description = "Wir hatten genug Munition, um den Bürgerkrieg einen weiteren Monat fortführen zu können. Aber es gibt mittlerweile derart viele Worgen, dass unsere Vorräte fast aufgebraucht sind.\n\nWir können nicht riskieren, dass dies passiert, während wir hier draußen schutzlos sind. Zieht Euch in die Kathedrale zurück und berichtet dem Boss. Bin mir sicher, der alte Crowley weiß, was wir als Nächstes tun sollten.", progress = nil, completion = "Wir haben ihnen alles entgegengeworfen, was wir haben... aber sie kommen noch immer. Sorgt Euch nicht, &lt;Name&gt;, wir werden noch viel mehr von ihnen über den Jordan schicken, bevor der Tag vorbei ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14222] = {title = "Das letzte Gefecht", objective = "Tötet 8 rasende Pirscher.", description = "Das hier ist ein perfekter Engpass, <Name>. Sprecht ruhig ein Gebet, wenn dergleichen Euch liegt.\n\nNehmt Euren Mut zusammen und dann lasst uns diese Köter vernichten!", progress = "Wir können es schaffen, <Name>.", completion = "Es... Es kommen keine weiteren.\n\nNein, &lt;Name&gt;. Das verheißt nichts Gutes.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFilm abspielen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14223] = {title = "Seelenfrieden", objective = "Sorrem in Furions Posten will, dass Ihr Kohor tötet.", description = "Unser Lager hat die Aufgabe, mögliche Widersacher zu beobachten. Sobald die Horde ihren Desolace-Feldzug startet, wird unsere Arbeit hier uns vor bösen Überraschungen schützen.\n\nKürzlich wurde einer unserer Späher gefangen genommen und von der Brennenden Klinge in ihrem Stützpunkt im Osten geopfert. Seitdem werden wir von einem Schuft der Brennenden Klinge bedroht und gepiesackt. Sein Name ist Kohor.\n\nIhre Tage sind gezählt, aber ich werde denjenigen großzügig belohnen, der ihn jetzt zum Schweigen bringt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14225] = {title = "Ihr erkennt es, wenn Ihr es seht", objective = "Sorrem in Furions Posten will, dass Ihr das uralte Beschwörungsritual in Festung Donneraxt findet.", description = "Mit seinen letzten Atemzügen erwähnte Kohor die Beschwörung eines Dämons, der das gesamte Gebiet bedrohen könnte.\n\nVielleicht war das ein Täuschungsversuch, aber das Risiko kann nicht eingegangen werden.\n\nDies kann nicht bis zum Einfall der Horde in Desolace warten. Ihr müsst die Festung Donneraxt nach Hinweisen durchsuchen und dieser möglichen Gefahr ein Ende setzen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14226] = {title = "Ärger unter den Füßen", objective = "Verwendet Euren persönlichen arkanen Assistenten, um 12 Legashidämonen in Insekten zu verwandeln und sie zu zerquetschen.", description = "Seht Euch an. Ihr unternehmt Botengänge. Sehr verantwortungsvoll von Euch. Ihr steigt hinauf, Ihr steigt auf... auf, auf!\n\nDämonen voraus! Viele, unerfreuliche Dämonen. Dämonen, denen Eure Innereien wohl gefallen würden! Legashidämonen in südöstlicher Richtung! Aber seid unbesorgt. Nein, nein. Es gibt keinen Grund zur Sorge, denn ich werde Euch einen Begleiter zur Seite stellen!\n\nSpitz, grausam, zerquetschend. Zielt, verkäfert, zerquetscht! Sehr leistungsfähig. Und auch sehr schmutzig... aber noch einmal: Seid unbesorgt. Nein, nein. Seid unbesorgt. Denn wir müssen zum Glück anschließend nicht saubermachen!", progress = nil, completion = "&lt;Erzmagier Xylem scheint eine Art Tanz aufzuführen, als er sich Euch zuwendet.&gt;\n\nMacht Euch keine Sorgen und achtet darauf, dass der Käfersaft nicht antrocknet, oder Ihr werdet es bereuen. Eure Stiefel würden ziemlich stinken! Es würde heute nicht gut riechen und morgen würde es noch weniger gut riechen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14227] = {title = "Die Köpfe zusammenstecken", objective = "Sammelt 100 gebleichte Schädel aus der Festung Donneraxt, stapelt sie auf dem Beschwörungszirkel der Brennenden Klinge auf und tötet dann Nazargen.", description = "Es stimmt also...\n\nDas Pergament, das Ihr in der Festung Donneraxt gefunden habt, beschreibt ein mächtiges Beschwörungsritual. Eines das stärker ist als alle anderen, von denen wir wissen, dass die Brennende Klinge sie besitzt.\n\nDieses Ritual muss selbstverständlich unterbrochen werden, koste es, was es wolle!\n\nWenn diese Dämonen vorzeitig beschworen würden, könnte die Krise abgewendet werden.", progress = nil, completion = "Ihr habt eine schlimme Krise abwenden können, &lt;Klasse&gt;.\n\nWenn diese Beschwörung noch ein wenig länger hinausgezögert worden wäre, wäre der Dämon viel zu mächtig für unsere kleine Streitmacht geworden.\n\nBitte nehmt dieses Geschenk zum Dank für Eure Dienste an.", rewards = "Schädelversengter UmhangAuf Euch wartet eine dieser Belohnungen:\n\nErdungshalsreifRing der machtvollen Unterbrechung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14230] = {title = "Handbucharbeit", objective = "Besorgt Euch das Handbuch des Abschwörers aus dem Lager der Legashi.", description = "Die hiesigen Dämonen scheinen Spaß daran zu haben, all unsere arkanen Handbücher zu stehlen. Ich möchte doch stark bezweifeln, dass die meisten von ihnen überhaupt lesen können, also tun sie dies nur aus reiner Bosheit.\n\nDie meisten dieser Bücher interessieren mich herzlich wenig, aber sie haben ein Bannzaubererhandbuch gestohlen, das ich auf alle Fälle brauchen werde, wenn ich Lehrlinge wie Euch während Xylems 'Prüfungen' am Leben erhalten will. Findet die Dämonen im Lager der Legashi im Südosten und gelangt in den Besitz des Handbuchs des Abschwörers.\n\nDas ist alles. Schwirrt ab.", progress = "Da seid Ihr ja... schon wieder... und sprecht mit mir. Ich nehme an, das bedeutet, Ihr habt mein Buch?", completion = "Spitze! Na, dann zurück an die Arbeit.\n\nDanke, Schätzchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14231] = {title = "Useless quest record", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][14232] = {title = "Ein Satz heiße Ohren", objective = "Bringt die Ohren von 25 Brennenden Klingen zu Sorrem in Furions Posten.", description = "Sorrem hat kein Geheimnis aus seiner Verachtung gegenüber der Brennenden Klinge in Festung Donneraxt gemacht.\n\nSicherlich würde ein Beweis ihres Dahinscheidens für ihn von großem Wert sein.", progress = "Was habt Ihr da, <Klasse>?", completion = "Ohren der Brennenden Klinge?\n\n&lt;Sorrem lächelt.&gt;\n\nGute Arbeit, &lt;Klasse&gt;. Dies ist nur eine Vorahnung von dem, was aus dem gesamten, ekelhaften Kult wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14233] = {title = "Orcs können schreiben?", objective = "Bringt das Feldtagebuch zu Sassy Hartzang an der Schiffbruchküste auf den Verlorenen Inseln zurück.", description = "Ihr durchwühlt die Habseligkeiten des toten Orcs und findet ein Feldtagebuch. Obwohl es vom Wasser schwer beschädigt wurde, ist die Schrift noch lesbar, wenn auch nur schlecht.\n\nIhr blättert durch die Seiten und entdeckt eine interessante Geschichte. Was für ein Glück, dass Ihr Orcisch beherrscht!\n\nWie die Yacht des Handelsprinzen wurden auch die Orcs von Kriegsschiffen der Allianz angegriffen. Ihr erinnert Euch, dass Ihr ein orcisches Kriegsschiff habt vorbeiziehen sehen, kurz bevor die Allianz das Feuer eröffnet hat. Vielleicht haben sie ja auf die Orcs statt auf Euch geschossen?\n\nDumme Orcs! Wegen ihnen seid Ihr untergegangen!", progress = "<Name>, konntet Ihr etwas Interessantes in der Höhle finden?", completion = "Orcs?! Sie wurden auch versenkt und sind gestrandet? Und jetzt ist die Allianz auf der Insel? Meint Ihr, sie werden uns töten?\n\n&lt;Sassy sieht nachdenklich aus.&gt;\n\nIch glaube, wir sollten uns mal mit diesen Orcs unterhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14234] = {title = "Der Feind meines Feindes", objective = "Bringt das Feldtagebuch zu Aggra im Basislager der Horde auf den Verlorenen Inseln.", description = "Ich schäme mich, das von Euch zu verlangen, aber ich schätze, dafür bezahlt man Euch so viel Gold. Könntet Ihr das Feldtagebuch dieses toten Orcs zum Befehlshaber ihres Lagers bringen?\n\nLaut dem Feldtagebuch sollte es sich oben auf der Insel am Hang hinter der Kaja'mithöhle im Südosten befinden.\n\nViel Glück, <Name>. Ich habe Euch immer gemocht.", progress = "<Die Orcdame betrachtet Euch mit zusammengekniffenen Augen.>\n\nIhr müsst auf dem Sklavenschiff der Goblins gewesen sein, das versenkt wurde. Was habt Ihr da in der Hand?", completion = "&lt;Die Orcdame versucht, nach dem Feldtagebuch zu greifen, unterbricht dann aber ihre Bewegung und seufzt tief.&gt;\n\nEs tut mir leid. Wir haben alle ein paar harte Tage hinter uns.\n\nIch bin Aggra. Was Ihr hier seht ist der klägliche Rest der Besatzung der Drakas Furor.\n\nVielleicht können wir ja zusammenarbeiten. Schließlich haben wir in der Allianz einen gemeinsamen Feind. Die Assassinen des SI:7 sind überall auf der Insel verstreut und werden keine Ruhe geben, bis wir alle tot sind.", rewards = "Wiederverwertete ArmschienenOrcische SpäherstiefelGamaschen des MatrosenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14235] = {title = "Das Kleine Horrortal", objective = "Findet Kilag Blutmaul im Kleinen Horrortal auf den Verlorenen Inseln.", description = "Unser Jäger, Kilag Blutmaul, ist mit ein paar Spähern den Weg nach Westen entlang gereist. Sie… suchen nach… \"wertvoller Fracht\"… auf die wir aufgepasst haben, als die abscheuliche Allianz unser Schiff versenkt hat.\n\nDer Weg dorthin wird von tödlichen Pflanzen blockiert, sodass sie nicht durchdringen konnten.\n\n<Name>, beweist Euren Wert als Goblin und <Klasse>. Reist in das Kleine Horrortal und findet Kilag.", progress = nil, completion = "&lt;Volk&gt;, könnt Ihr kämpfen?\n\nUm Euretwillen hoffe ich es einfach mal. Ansonsten gibt es keinen Weg durch diese Hölle aus Todespflanzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14236] = {title = "Unkrautvernichter", objective = "Benutzt den Unkrautvernichter Eures goblinischen Alles-in-1-zigartigen Gürtels, um 100 Pflanzen im Kleinen Horrortal niederzumähen.", description = "<Kilag bleibt zwischen den Gewehrschüssen kaum Zeit, Euch zu beachten, doch sein Blick bleibt einen Moment lang bewundernd auf Eurem goblinischen Alles-in-1-zigartigem Gürtel ruhen.>\n\nJetzt sind kreative Lösungen gefragt. Zieht etwas aus diesem Gürtel und macht Euch an die Arbeit!\n\n<Ihr denkt kurz über die Situation nach. Dann fällt Euch etwas ein, was gerade verrückt genug ist, um funktionieren zu können!>", progress = nil, completion = "Ich habe es mit eigenen Augen gesehen und kann es immer noch nicht glauben!\n\nIhr habt unseren Dank. Wir schulden Euch unser Leben, kleiner &lt;Volk&gt;. Ich hoffe, dass wir Euch diese Ehre bald zurückzahlen können.\n\nDarf ich Euch um einen kleinen Gefallen bitten, während ich mit meinen Spähern weiterziehe?", rewards = "UnkrautfaserhoseKilags WesteUnkrautstampferDer folgende Zauber wird auf euch gewirkt:\n\nWeed Whacker: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14237] = {title = "Vorrücken", objective = "Findet Kilag Blutmaul und seine Späher an der Wilden Aussicht auf den Verlorenen Inseln.", description = "Kilag sollte jetzt in Position sein. Es wird Zeit, dass Ihr zur Wilden Aussicht vorrückt. Der Rest von uns packt hier zusammen und kommt bald nach.\n\nFolgt einfach dem Pfad nach Nordwesten durch das Kleine Horrortal. Dank Euch hält sich der Horror dort ja jetzt in Grenzen, hm?\n\nKilag und seine Späher verstecken sich am Wegesrand, aber die Assassinen des SI:7 werden sie sicher bald entdecken. Ihr solltet Euch also beeilen!", progress = nil, completion = "Throm-Ka, &lt;Name&gt;. Wir haben ein Problem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14238] = {title = "Infrarot = Infratot", objective = "Tötet 10 Assassinen des SI:7.\n\nWenn Eurem orcischen Späher etwas zustößt, kehrt zu Kilag zurück und schaut, ob er einen anderen Partner für Euch hat.", description = "Seid leise! Im Tal nördlich und westlich von hier wimmelt es nur so von Assassinen der Allianz.\n\nLeider konnten wir sie noch nicht entdecken. Diese Feiglinge! Sie verstecken sich lieber, als von Angesicht zu Angesicht zu kämpfen.\n\nIhr Goblins seid doch für Eure wunderlichen Brillen bekannt. Habt Ihr nicht eine, mit der Ihr sie sehen könnt?\n\nIhr müsst Euch mit einem meiner Späher zusammentun und alle Assassinen des SI:7 töten, die Ihr entdecken könnt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;, sehr gut. Vielleicht wird aus Euch doch noch ein Orc!\n\nEs ist Zeit, weiterzuziehen. Wir sollten uns sputen.", rewards = "SpionerdrosslerkordelSpionpiekserSpionwürgerhandschuheDer folgende Zauber wird auf euch gewirkt:\n\nInfrared = Infradead: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14239] = {title = "Geht nicht ins Licht!", objective = "Es liegt jetzt an Euch. Kehrt Ihr zurück ins Leben und seid der Held, den die restlichen Überlebenden so dringend brauchen, oder bleibt Ihr bis in alle Ewigkeit hier?\n\nNur Ihr könnt das entscheiden.\n\nGeht nicht ins Licht, <Name>!Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDon't Go Into The Light!: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14240] = {title = "Zu den Klippen", objective = "Sprecht mit Späher Brax am Pfad entlang der Klippen nördlich der Wilden Schlucht auf den Verlorenen Inseln.", description = "Ich habe Späher Brax die Straße weiter zu den Klippen geschickt, die über den Strand ragen.\n\nIch werde Euch auf Bastia setzen. Reist den Pfad entlang und teilt Brax mit, dass wir einen anderen Weg nehmen.\n\nWir treffen uns beim Angriff an der Landespitze der Allianz!", progress = nil, completion = "Hallo, kleiner &lt;Volk&gt;. Bastia ist ganz schön schnell, was?\n\nWir haben wichtige Dinge zu erledigen. Helft Ihr uns?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14241] = {title = "Auf zum Gyroschrauber!", objective = "Besorgt Euch die Gyroschrauberschlüssel.", description = "Die Allianz hat der Horde etwas von größter Wichtigkeit gestohlen. Sie bewahren es auf ihren Schiffen auf.\n\nAm anderen Ende des Strands findet Ihr einen Gyroschrauber. Unsere Kriegshetzer geben Euch auf dem Weg dorthin Deckung.\n\nFliegt zu ihrem Flaggschiff, der Sog der Vergeltung, und holt unsere wertvolle Fracht zurück!", progress = "Hm, sieht nach überkomplizierter gnomischer Ingenieurskunst mit vielen unnötigen Instrumenten und Sicherheitsmaßnahmen aus.", completion = "Wo zum Teufel ist die Zündung?\n\nMich würde nicht wundern, wenn dieses Ding beim Fliegen etwas Komisches macht, zum Beispiel sich in ein Hühnchen verwandelt oder auf Ameisengröße zusammenschrumpft.\n\nHe, schaut! Da hat jemand etwas Kleingeld im Aschenbecher vergessen! Was hier wohl sonst noch so herumliegt?", rewards = "PilotenhandschuheFallschirmarmbänderGyroschraubersitzgurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14242] = {title = "Wertvolle Fracht", objective = "Findet die wertvolle Fracht unter Deck des Allianzschiffs \"Sog der Vergeltung\" am Strand der Verlorenen Inseln.", description = "Sie sagten, dass ihre \"wertvolle Fracht\" auf dem Allianzschiff, der Sog der Vergeltung, aufbewahrt würde, was auch immer das für eine Fracht sein mag.\n\nEs gibt nur eins zu tun… Fliegt mit diesem Ding dorthin und holt sie Euch zurück!", progress = "Vielleicht könntet Ihr mir helfen, aus diesem arkanen Käfig zu kommen?", completion = "Wenn Ihr nicht wärt, würde man mich jetzt sicher nach Sturmwind bringen und als Trophäe und Sklave in der Stadt präsentieren.\n\nDiese Hunde der Allianz haben mich bewusstlos am Strand gefunden und in diesen magischen Käfig gesteckt. Er hat mich davon abgehalten, eine Verbindung zu den Elementen aufzubauen.\n\nAber das ist jetzt vorbei!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14243] = {title = "Die Rache des Kriegshäuptlings", objective = "Benutzt die Macht des Zyklons der Elemente, um 50 Matrosen der Allianz zu töten.\n\nSobald Ihr Eure Aufgabe erledigt habt, werdet Ihr zur Wilden Aussicht geflogen.", description = "Brüder der Erde und des Feuers, hört mich an! Schwestern des Wassers und der Luft, folgt meinem Ruf!\n\nAzeroth steht an der Schwelle der Zerstörung! Unser aller Leben ist in Gefahr! Leiht mir Eure Macht, wie Ihr sie einst meinen Vorfahren geliehen habt. Macht dieses Kind von Kezan zum Instrument Eures Willens.\n\nSetzen wir denen ein Ende, die uns daran hindern wollen, die Welt zu heilen!", progress = nil, completion = "Ihr habt geschafft, was nur wenige hätten schaffen können, &lt;Name&gt;. Unsere Welt steht tiefer in Eurer Schuld, als Ihr es je begreifen könnt.", rewards = "Wirbelnde AxtStab des OrkansIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14244] = {title = "Auf, auf und davon!", objective = "Überlebt den Schuss mit der Raketenschleuder über die Bedrängnis.", description = "Während Ihr den Kriegshäuptling gerettet und uns alle vor der Allianz bewahrt habt, hat Vorarbeiter Feuchtlunte diese Raketenschleuder gebaut, um uns über die von Haien verseuchte Meerenge auf die größere Insel zu katapultieren.\n\nZu unserem Glück konnte der Vorarbeiter eine Instastadt aus dem Schiffswrack retten. Sobald Ihr sie aufbaut, haben wir endlich wieder eine eigene Stadt. Ich kann es kaum erwarten, wieder in einem Bett zu schlafen!\n\nFeuchtlunte hält sich dort unten am Landeplatz auf und erwartet Euch. Warum nehmt Ihr nicht gleich die nächste Rakete?", progress = nil, completion = "&lt;Name&gt;, ich bin so froh, dass Ihr die Reise gut überstanden habt… Leider kann man das nicht von allen behaupten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14245] = {title = "Die Stadt in der Kiste", objective = "Klettert auf den Sprengstoffberg und benutzt den Auslöser von Instastadt.", description = "Der Handelsprinz hatte im Frachtraum des Schiffes eine ganze Stadt in einer Kiste! Ich konnte die Kiste an mich bringen, während Ihr uns da draußen die Haut gerettet habt.\n\nWürdet Ihr mir die Ehre erweisen? Klettert einfach auf diesen riesigen Sprengstoffberg, drückt den Auslöser und Abrakablam! Ihr seid in Instastadt.", progress = nil, completion = "&lt;hust, hust&gt;\n\nHe! Wo sind die Docks? Jemand hat die Docks und die Raffinerie aus unserer Instastadt gestohlen!\n\nWer würde denn so etwas tun?\n\nWo ist dieser Handelsprinz?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14246] = {title = "Zwangsadoption", objective = "Legt 3 Sturzflieger-Eier in die Nester von Sturzfliegern und sie beschützt, bis sie eingesammelt wurden.", description = "Während diese Region immer üppiger und grüner wird, werden die Wüstenkreaturen auf immer begrenzterem Raum zusammengedrängt.\n\nBesonders besorgniserregend ist das fortschreitende Aussterben der einheimischen Sturzflieger. Während der Nistzeit tun sich die Raubtiere an den Vögeln und ihren Eiern gütlich.\n\nIch habe ein paar Sturzflieger-Eier aus Tanaris besorgt und sie mit einem unwiderstehlichen Lockstoff benetzt. Legt ein Ei in jedes Nest, das Ihr findet könnt, und beschützt es, bis ein Sturzflieger kommt und es davonträgt.\n\nIhr werdet damit dem natürlichen Gleichgewicht dieses Landes einen großen Dienst erweisen.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Klasse&gt;.\n\nDieses Land steht in Eurer Schuld.", rewards = "Federleichte GamaschenGepolsterte Stulpen des SammlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14247] = {title = "Raues Land", objective = "Thunk in Thunks Heimstatt will, dass Ihr die unnatürliche Felszunge findet.", description = "Ich wurde vom Zirkel des Cenarius offiziell beauftragt, dieses raue Land in eine saftige Prärie zu verwandeln.\n\nDie Länder südlich von hier sprießen bereits, aber hier kämpft irgendetwas dagegen an und widersteht dem Wachstum.\n\nVielleicht können Eure Augen ausfindig machen, was meinen verschlossen bleibt.\n\nBitte, <Volk>. Durchkämmt diese Länder und findet den Ursprung für die Sturheit der Wüste.", progress = nil, completion = "Ihr seht Euch um und sucht den Horizont nach etwas ab, das diesen Felsstein hier platziert haben könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14248] = {title = "Hilfe gesucht", objective = "Sprecht mit Vorarbeiter Feuchtlunte außerhalb der Kaja'mithöhle auf den Verlorenen Inseln.", description = "Tolle Neuigkeiten! Vorarbeiter Feuchtlunte hat auf der Insel eine ganze Höhle voller Kaja'mit entdeckt! Wer hätte das gedacht?\n\nNatürlich hat die Sache einen kleinen Haken. Er hat ein paar Überlebende mitgenommen, um ihm beim Abbau des Erzes zu helfen, aber keiner von ihnen ist wieder aus der Mine herausgekommen.\n\nSo verrückt es klingt, aber der Vorarbeiter sagt, dass es in der Höhle Affen gibt... mit Spitzhacken! Sie bauen das Kaja'mit ab! Wie ist das überhaupt möglich?\n\nKönntet Ihr nach Südosten zur Höhle gehen? Der Vorarbeiter steht direkt an ihrem Eingang.", progress = nil, completion = "Boss! Äh, ja, ich schätze, Ihr seid nicht mehr der Boss. Aber es ist trotzdem schön, Euch zu sehen!\n\nKönnt Ihr das glauben? Eine Höhle voller intelligenter Killeraffen, die Kaja'mit abbauen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14249] = {title = "Federgewichtig", objective = "Besorgt 80 makellose Donnerkopffedern von den Hippogryhpen in der Nähe der Ruinen von Nordressa.", description = "Ich wäre super! In Erzmagie. Der Hit! Er würde nicht mal mit mir sprechen, denn ich habe keine so dämliche Robe und keinen Hut. Pffft.\n\nDer fantastischste Erzmagier, den dieses Land jemals gesehen hat, kann nicht einfach eine Robe und einen Hut haben. Ich muss ihm zeigen, dass ich etwas ganz Besonderes bin und ich weiß auch schon genau, wie ich das mache.\n\nGeht hinaus und tötet mir ein paar dieser Hippogryphen. Bringt mir eine TONNE ihrer Federn.\n\nIhr habt mich verstanden! Eine Riesenmenge Federn! Geht, geht. Ich werde die Robe fertig haben, wenn Ihr zurück seid.", progress = "Meine Robe sieht ziemlich schick aus. Habt Ihr die Federn dabei?", completion = "Haha! Perfekt! Lasst mich das alles schnell zusammennähen. Der Erzmagier wird von meinem Auftritt sicher überwältigt sein!", rewards = "Geklebte FederstiefelRobotronische WesteScherenklingeDer folgende Zauber wird auf euch gewirkt:\n\nForcecast Ruins of Nordressa Invs Update\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14250] = {title = "Erneuerbare Ressourcen", objective = "Verwendet die Arkane Aufladung, um 5 Stück belebtes Basalt von Balboa in der Nähe der Ruinen von Nordressa zu erlangen.", description = "Wir brauchen noch mehr belebten Basalt. Dafür gibt es nur eine zuverlässige Quelle in diesem Gebiet: ein Bergriese namens Balboa. Wir können den Bergriesen nicht töten, wenn wir langfristig was von dem Zeug haben wollen, also schlagen wir immer nur kleinere Teile auf einmal ab.\n\nIhr werdet in der Lage sein, seinen Weg nordöstlich und östlich von hier zu erkennen. Findet ihn, legt den Sprengsatz vor ihm auf den Pfad und dann versteckt Euch, bis er explodiert. Sobald er das Gebiet verlassen hat, solltet Ihr den Basalt an Euch nehmen können und ihn zu mir bringen.", progress = "Ich habe ein paar Explosionen gehört. Ich kann nur schwer sagen, ob eine von ihnen von Euch war oder nicht... Diese Goblins können eine ziemliche Plage sein.", completion = "Gute Arbeit. Das gibt uns noch ein paar Stunden, bevor wir wieder zu ihm müssen, um uns mehr zu holen.\n\nEr scheint nicht gerade der hellste Riese zu sein. Ich gehe davon aus, dass wir das noch eine Zeitlang machen können, bevor er es kapiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14251] = {title = "Noch mal von vorne", objective = "Sammelt 15 Skorpionenstachel.", description = "So weit im Norden bestand bisher nie die Gefahr eines Zentaurenangriffs. Irgendjemand hat sie aufgehetzt. Ich weiß es einfach!\n\nAber davon abgesehen bin ich am Ende. Ich habe alles in diese Ladung investiert.\n\nGlücklicherweise gibt es etwas, das mir kein Zentaur nehmen kann, und das ist meine goblinische Genialität! Ich fange noch einmal ganz von vorne an und errichte ein Imperium!\n\n<Bizby macht in einiger Entfernung einen Skorpion aus.>\n\nEs gibt immer einen Markt für Gift. Was sagt Ihr?", progress = "Werfen wir doch mal einen Blick auf diese Skorpionenschwänze.", completion = "So habe ich angefangen, müsst Ihr wissen.\n\nGift an die Schurken in Orgrimmar vertickt. Ach, das waren noch Zeiten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14252] = {title = "Gutes Gold für schlechte Schwänze", objective = "Findet 15 alte Basiliskenschwänze.", description = "Ich brauche haufenweise Schwänze, <Klasse>! Und nicht irgendwelche Schwänze. Die Schwänze, die ich brauche, müssen alt sein - uralt sogar. Je oller je doller.\n\nDie Schuppen eines Basiliskenschwanzes sind einzigartig, denn sie werden mit den Jahren immer härter, ohne spröde zu werden. Die gehärteten Schuppen sind ideal für die Herstellung bestimmter Rüstungen.\n\nEs ist viele Jahre her, dass ich darauf angewiesen war, Eidechsenschuppen zu verkloppen, aber wer weiß, vielleicht stärkt es ja meinen Charakter! Falls das überhaupt noch möglich ist...", progress = "Wie läuft die Suche nach den Basiliskenschwänzen, <Name>?", completion = "Das wird reichen, &lt;Klasse&gt;.\n\nNoch mehr so Freunde wie Ihr, und ich bin in nullkommanix wieder auf den Beinen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14253] = {title = "Befiederung", objective = "Sammelt 25 Federn von Schreckenssturzfliegern.", description = "Sagt, <Klasse>, während Ihr unterwegs seid und die Ödnis der Wüste erforscht, könnt Ihr mir einen Gefallen tun?\n\nHaltet Ausschau nach Schreckenssturzfliegern. Ihre öligen Federn sind für die Befiederung von Pfeilen bestens geeignet und bei den richtigen Käufern bringen sie ein hübsches Sümmchen ein.\n\nZum Glück für Euch kenne ich alle richtigen Käufer!", progress = "Wie läuft die Suche nach den Sturzfliegern?", completion = "Nun gut, das sind reichlich Federn, &lt;Klasse&gt;.\n\nDie werden ein gutes Kissen abgeben, bis ich sie morgen zum Markt schaffe!", rewards = "Schultern aus SturzfliegerschwanzfedernFedergeschmückte BeinschützerKlauenfetzerstampferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14254] = {title = "Schwermetall", objective = "Ihr sollt 7 Stück Element 116 einsammeln und sie zu Bizby in Bizbys Karawane bringen.", description = "Ihr habt das starke Gefühl, dass dieser Stein irgendwie dafür verantwortlich ist, dass diese Region sich gegen die Wiederbegrünung wehrt.\n\nIhr seht in Richtung Westen und bemerkt dort Anzeichen von schwelenden Trümmern, die auf rätselhafte Weise damit in Verbindung zu stehen scheint.\n\nIhr vermutet, dass die Entfernung der Trümmer Thunks Bemühungen entgegenkommen würde.\n\nUnd wer weiß, wofür das Zeug gut sein könnte?", progress = "Was habt Ihr da, <Klasse>?", completion = "Was ist das?\n\n&lt;Bizby untersucht das Erz.&gt;\n\nWahnsinn! Ich kenne jemanden, der größtes Interesse daran haben wird, diese Proben in die Finger zu bekommen.\n\nUnd er würde auch äußerst großzügig dafür zahlen. Darauf wette ich.\n\nHier, &lt;Klasse&gt;. Nehmt dies als Finderlohn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14255] = {title = "Ethel Rethor", objective = "Cerelia in Furions Posten will, dass Ihr mit Korrah in Ethel Rethor sprecht.", description = "Wir haben zahlreiche Feinde in dieser Region, auch ohne dass wir den Zorn des Zirkels des Cenarius auf uns ziehen.\n\nAls wir diesen Posten hier aufgebaut haben, wurden wir gebeten, eine ihrer Forscherinnen im Auge zu behalten.\n\nKorrah wurde zuletzt am Turm im Westen gesehen. Seid so lieb und stattet ihr einen Besuch ab. Es ist schon etwas länger her, seit wir uns die Mühe gemacht habe, nach ihr zu sehen.", progress = nil, completion = "Es ist gut, dass Ihr gekommen seid.\n\nHier lauert eine große Gefahr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14256] = {title = "Die wachsende Bedrohung", objective = "Korrah will, dass Ihr mit ihr sprecht, wenn Ihr bereit seid, die Bedrohung durch die Naga näher zu besehen.", description = "Außer mir ist niemand von meiner Gruppe übrig geblieben, die hierher entsendet wurde, um die zahlreichen Veränderungen an dieser Küste von Desolace zu beobachten.\n\nIch habe Bericht von der dramatischen Zunahme der Naga erstattet, aber ohne Reaktion.\n\nMeine Mitstreiter konzentrieren sich auf die anderen Krisenherde. Deshalb muss ich Euch, <einen Fremden/eine Fremde>, bitten, mich bei meinen Forschungen zu unterstützen.\n\nZunächst gestattet mir jedoch, dass ich Euch die Bedrohung zeige, der wir gegenüberstehen.", progress = nil, completion = "Jetzt versteht Ihr. Dies ist keine einfache Bande von verdrängten Naga, sondern eine gut organisierte Armee, die in der Lage ist, große Zerstörung zu verursachen.\n\nWilligt Ihr ein, mich bei meinen Untersuchungen zu unterstützen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14257] = {title = "Zackenkämme getötet", objective = "Sammelt 10 Zackenkammknochen von Naga der Zackenkämme, 30 Zackenkammschuppen von Zauberinnen der Zackenkämme und 4 Zackenkammflossen von Kriegern der Zackenkämme.", description = "Wieder und wieder erweisen sich die Naga als Feinde des natürlichen Gleichgewichts. Ich habe keinerlei Bedenken, Ihr Blut zu vergießen.\n\nEure größten Bemühungen können ihren Kräften jedoch kaum einen nennenswerten Schaden zufügen. Wo einer fällt, scheinen zwei an seine Stelle zu treten.\n\nIch habe einen Plan, <Klasse>! Euer Ziel soll es nicht mehr nur sein, die Feinde zu töten, sondern Ihr sollt Teile ihres Körpers sammeln, die für den nächsten Schritt unserer Forschung vonnöten sind...", progress = "Habt Ihr die Teile gesammelt, die ich benötige?", completion = "Ihr habt gute Arbeit geleistet, &lt;Klasse&gt;. Aber leider ist diese Arbeit erst der Anfang.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCreate Naga Costume\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14258] = {title = "Mörsermunition", objective = "Holt 5 Goblinmörsergranaten aus dem Geheimlaborkomplex in Azshara.", description = "Die Naga sind auf diese Halbinsel vorgerückt, nachdem wir die Endhaltestelle der Raketenbahn fertiggestellt hatten. Aber es gibt kein Problem auf dieser Welt, das sich nicht mit genügend Feuerkraft lösen ließe! Mein Vater hat das immer gesagt. Vor dem Unfall.\n\nMeine Vorräte werden allerdings knapp. Tut mir einen Gefallen und sammelt die Mörsergranaten ein, die ich im Geheimlabor westlich von hier gelagert habe. Wenn Ihr reichlich neue liefert, dann lasse ich Euch selbst die Abschussbefehle für die Artillerie geben!", progress = "Ich hoffe, Ihr habt Munition für mich. Meine einzige Waffe ist zurzeit mein loses Mundwerk.", completion = "Schön! Wundervoll! Hervorragend! Ihr seid granatenstark!\n\nDa meine Mörser wieder bestückt sind, kann ich Euch mit ihnen unterstützen, wenn Ihr die Naga östlich von hier angreift. Verwendet diese Markierungen irgendwo an den Klippen, um Artillerieschläge anzufordern und ich bade das gesamte Gebiet in feuriges Auaweh. Oh, du köstliche, gnadenlose, willkürliche Zerstörung! Ich hoffe, Ihr seid gut gepanzert...", rewards = "Ihr bekommt:\n\nArtilleriesignal"}
MultiLanguageQuestData['de'][14260] = {title = "In die Tiefe gehen", objective = "Benutzt den Zackenkammglücksbringer", description = "Ich habe einen Glücksbringer erstellt, der es Euch ermöglicht, Euch bei den Naga einzuschleusen. Er gibt Euch das Erscheinungsbild eines der ihrigen.\n\nMithilfe dieser Tarnung werdet Ihr in der Lage sein, ihre Sprache zu sprechen und zu verstehen. Sie werden nicht in der Lage sein, Eure wahre Identität zu erkennen.\n\nAber seht Euch vor! Die Haie und andere Meereswesen hier werden Euch für alle sichtbar machen. Meidet sie um jeden Preis.\n\nNun geht. Sprecht mit der Priesterin von Azshara und tut, was getan werden muss, um herauszufinden, warum sie hier sind.", progress = nil, completion = "Steht nicht einfach so herum, wenn es so viel zu tun gibt!\n\nMuss ich denn jedem jede Kleinigkeit erklären?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14261] = {title = "Eiskalt", objective = "Verwendet den Kryomat 16, um 8 finstere Drachen einzufrieren und zu töten.", description = "Ich habe die perfekte Lösung für Euer Drachenproblem. Meine ganz persönlicher Kryomat 16.\n\nIch habe ihn ursprünglich entwickelt, um meine Arbeiter während des Transports und zwischen den Schichten einzufrieren. Denn dann muss ich sie nicht füttern oder unterhalten. Aber es gab... Komplikationen. Sie ist aber auch perfekt dafür geeignet, diese Drachen vom Himmel zu holen!", progress = nil, completion = "Was? Ihr habt die Drachenteile gar nicht mitgebracht? Wie enttäuschend.\n\nIch wusste, ich hätte Euch einen Vertrag unterschreiben lassen müssen, bevor ich Euch losschickte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14262] = {title = "Wie man einen Fisch ausnimmt", objective = "Tötet 6 Sturmwute der Grollflossen und 6 Seerufer der Grollflossen.", description = "Es stellt meine Geduld auf die Probe, Kreaturen abzuwehren, die jederzeit im Meer verschwinden können und wieder auftauchen, wo es ihnen beliebt. Aber ich werde mich nicht geschlagen geben, bis sie allesamt von Azsharas Antlitz gefegt sind.\n\nNaga der Grollflossen haben die Klippen erklommen und belagern uns nun von Osten her. Vernichtet sie, <Name>. Nehmt sie aus vom Schwanz bis zum Kopf, sodass sie den wahren Zorn meiner Horde zu spüren bekommen.", progress = nil, completion = "&lt;Torg sucht den Horizont ab.&gt; Trotzdem kommen immer mehr! Sie sind wie eine Plage, &lt;Name&gt;. Aber mithilfe Eurer Kraft werden wir sie zermalmen. Eines Tages.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14263] = {title = "Fidele Kräuter", objective = "Sammelt 8 Bündel Lebendigen Zornthymian in der Nähe der Ruinen von Nordressa.", description = "Lebendiger Zornthymian. Ich brauche mehr davon! Beeilt Euch, schnell!", progress = "Habt Ihr den Thymian bekommen?", completion = "Perfekt. Es ist ganz interessant, als wie nützlich sich die unscheinbarsten Dinge für eine Beschwörung dieser Art erweisen.\n\nEs gibt noch so viel zu entdecken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14264] = {title = "Nasser als Nass", objective = "Besiegt 5 Diener von Neptulon. (Ihr müsst in Nagagestalt sein, während Ihr sie bekämpft.)\n\nSolltet Ihr Euren Dreizack der Zackenkämme verlieren, sprecht mit Valishj.\n\nWenn Ihr Euren Zackenkammglücksbringer verliert, sprecht mit Korrah in Ethel Rethor.", description = "Neptulons Schergen haben diesen Ort erreicht und tun alles, um unsere Pläne zu durchkreuzen. Offensichtlich haben sie unsere Beweggründe herausgefunden.\n\nDas bestätigt nur meinen Verdacht, dass sich das, was wir suchen, tatsächlich in diesen Ruinen verbirgt!\n\nDiese Wasserelementare können sich nicht mit unseren Kräften messen! Nehmt diesen Dreizack und verwendet ihn, um die wertlosen Diener des Gezeitenjägers zu vernichten.\n\nWenn wir finden, was wir hier suchen, soll Neptulon selbst um sein Leben fürchten müssen!", progress = nil, completion = "Die feindlichen Linien dünnen sich aus, kleines Fischlein.\n\nVielleicht seid Ihr würdig, uns bei unserer Suche zu helfen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14265] = {title = "Euer Lehrmeister", objective = "Redet mit Unteroffizier Cleese im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Typ namens Cleese meinte, Ihr wärt einer seiner Lehrlinge und wollte sicherstellen, dass es Euch gut geht.", progress = nil, completion = "&lt;Name&gt;! Wo wart Ihr?\n\nWie auch immer, es ist großartig, Euch in einem Stück wiederzusehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14266] = {title = "Sturmangriff", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Übt anschließend 'Sturmangriff' gegen einen Blutfangworgen.", description = "Ihr seid am Leben, <Name>! Also habe ich wohl meine Sache richtig gemacht.\n\nEine Schande, dass unser Unterricht so abrupt abgebrochen wurde. Aber auf Eurem Weg werdet Ihr beginnen, neue Techniken zu entdecken.\n\nGeht, sammelt mehr Erfahrung, lernt etwas Neuers und probiert es dann an den Blutfangworgen im Westen aus.", progress = "Ihr seid ein schneller Lerner, <Name>. Werdet aber nicht gleich übermütig.", completion = "Gute Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14267] = {title = "Die Untersuchung des Meeresschreins", objective = "Untersucht den Schrein der Naga für Torg Zweimalmer.", description = "Die Eindringlinge der Naga haben eine Reihe von Schreinen an den Klippen errichtet. Ich kenne ihren Zweck nicht, <Name>, aber ich glaube, dass sie unsere Feinde stärken. Ich brauche jemanden, der sich dorthin begibt und diese Bedrohung untersucht.\n\nEin nahegelegener Schrein wird nur wenig bewacht. Überquert die erste Brücke östlich von hier und dann wendet Euch nach Norden in Richtung der Bucht. Ihr findet den Schrein auf einer kleinen Felszunge. Untersucht ihn und kehrt mit ein paar nützlichen Informationen zurück.", progress = nil, completion = "Der Stein in der Mitte dieses Schreins verströmt ein schwaches Schimmern und donnert mit der Kraft des wütenden Meeres.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14268] = {title = "Wasserzeichen", objective = "Priesterin Valishj will, dass Ihr die uralten Neptulon-Gravuren findet.", description = "Königin Azshara sucht nach einem Eingang zur Wasserebene. Ich weiß nicht warum.\n\nSie glaubt, dass die Uralten wussten, wie dieser Ort zu finden ist.\n\nIch wurde persönlich damit betraut, die Ruinen in dieser Gegend abzusuchen, und niemand soll ruhen, bis wir die Geheimnisse gelüftet haben, die wir suchen!\n\nNördlich von hier ist eine Ansammlung von Ruinen. Durchsucht das Geröll mit diesem Stab.\n\nKehrt zu mir erst dann zurück, wenn Ihr gefunden habt, was wir suchen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14269] = {title = "Jemand sucht nach Euch", objective = "Sprecht mit Loren der Hehlerin im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Eine Frau namens Loren... Sie schien etwas enttäuscht zu sein, als ich ihr sagte, dass es Euch gut geht.\n\nIch glaube sie sagte, sie schulde Euch Gold.", progress = nil, completion = "Oh, da seid Ihr ja!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14270] = {title = "Die Schlüsselsteinscherbe", objective = "Findet die Schlüsselsteinscherbe in der Nähe.", description = "Die Luft um diesen rätselhaften Stein knistert vor Energie. Der Stein selbst ist glatt und eiskalt. Als Ihr mit Euren Händen darüber gleitet, pulsiert er gleichmäßig wie brandende Wogen.\n\nEin keilförmiges Stück scheint an der Oberfläche des Artefakts zu fehlen. Diese 'Schlüsselsteinscherbe' ist vermutlich der Schlüssel zum Geheimnis des Steins. Durchsucht die Umgebung des Tempels und findet die Schlüsselsteinscherbe.", progress = "Der Kraftstein der Naga pulsiert und summt erwartungsvoll.", completion = "Die Schlüsselsteinscherbe gleitet an ihren Platz und plötzlich erscheinen bisher unsichtbare Runen auf der Steinoberfläche und schimmern blau und violett. Eure Knie werden weich, als mächtige, arkane Ströme unvermittelt durch Euren Körper fahren...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSturmschutz\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14271] = {title = "Berichtet Zweimalmer", objective = "Kehrt zu Torg Zweimalmer an der Südlichen Endhaltestelle der Raketenbahn in Azshara zurück und berichtet ihm von Eurer Entdeckung.", description = "Eine magische Barriere pulsiert um Euch herum und Kälte fährt Euch in die Glieder. Hinter dieser Zauberwand fühlt Ihr Euch sicher.\n\nTorg Zweimalmer wird von Eurer Entdeckung erfahren wollen!", progress = nil, completion = "Eine Energiebarriere sagt Ihr? Das erklärt einiges! Ich habe Anführer der Naga gesehen, die in der Lage waren, die Klingen meiner besten Krieger abzulenken.\n\nJetzt kennen wir die Quelle ihrer Kraft, &lt;Name&gt;. Bringen wir es zu Ende!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14272] = {title = "Ausweiden", objective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Übt 'Ausweiden' an einem Blutfangworgen.", description = "Schön, Euch lebend wiederzusehen!\n\nNein, natürlich habe ich das Gold nicht, das ich Euch schulde. Jetzt ist nun wirklich nicht die Zeit, darüber zu diskutieren!\n\nHört zu, vielleicht kann ich Euch ein oder zwei Tricks beibringen, die Euch helfen werden, trotz des ganzen Gemetzels hier Eure Haut zu retten.\n\nWährend Ihr lernt, wie man kämpft, werdet Ihr auch andere neue Dinge lernen. Geht, sammelt mehr Erfahrung und wenn Ihr dann etwas Neues gelernt habt, solltet Ihr es an den Blutfangworgen im Westen ausprobieren. Ich werde Euch beobachten.", progress = "Verhaltet Euch still, dann schnappt sich der <Volk> hoffentlich einen anderen armen Wicht anstelle von uns.", completion = "Ah, ja. Klar, Ihr wart toll.\n\nUnd jetzt lasst uns sehen, wie wir mit heiler Haut aus dieser Stadt kommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14273] = {title = "Zwielichtige Gesellen", objective = "Sprecht mit Vitus Dunkelwandler im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. So ein seltsamer Geselle namens Vitus ... der war echt unheimlich.\n\nEr hat die ganze Zeit von einem \"verbotenen Wissen\" erzählt, das er sich angeeignet hat.", progress = nil, completion = "Dunkelheit ist über unser Land gekommen. Und nicht die übliche Art Dunkelheit, wenn Ihr versteht, was ich meine.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14274] = {title = "Verderbnis", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Übt 'Verderbnis' an einem Blutfangworgen.", description = "Also ist es wahr! Ihr seid am Leben!\n\nIch hatte nie die Gelegenheit, meine größte Entdeckung mit Euch zu teilen. Aus dem geheimen Wissen der kaum entzifferbaren Bücher von Balcephoth dem Teufelsschatten... lernte ich die verbotenen Geheimnisse der...\n\nVerderbnis!\n\nGeht, sammelt mehr Erfahrung, vielleicht erlernt Ihr einen neuen Zauberspruch. Ihr könnt Ihn dann gegen die Blutfangworgen im Westen einsetzen.", progress = nil, completion = "Ja! Könnt Ihr die Macht spüren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14275] = {title = "Jemand ist Euch auf der Fährte", objective = "Sprecht mit Jäger Blake im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Mann namens Blake. Sagte etwas über einen Plan, in die Wälder zu flüchten.", progress = nil, completion = "&lt;Name&gt;! Ich wusste, dass Ihr hier irgendwo sein müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14276] = {title = "Zuverlässiger Schuss", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Übt 'Zuverlässiger Schuss' zweimal gegen einen Blutfangworgen.", description = "Also, ich habe gute und schlechte Nachrichten.\n\nDie schlechte Nachricht ist, dass es in den Wäldern mehr Worgen gibt als hier drin... also haben wir keinen sicheren Ort, an den wir uns zurückziehen können.\n\nDie gute Nachricht ist, dass Ihr langsam den Dreh raushabt. Wenn Ihr erfahrener werdet, werdet Ihr neue Dinge erlernen.\n\nSobald Ihr Eure erste Fähigkeit erlernt habt, probiert Euch doch gegen die Blutfangworgen im Westen aus.", progress = "Ihr lernt schnell. Wir werden diesen <Volk> zeigen, wer hier der echte <Klasse> ist.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Diese &lt;Volk&gt; werden bereuen, dass sie je einen Fuß auf unser Land gesetzt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14277] = {title = "Arkane Anfragen", objective = "Sprecht mit Myriam Zauberwache im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft, aber auch in diesem Teil der Stadt gibt es Worgen.\n\nWir werden weiter nach Süden ziehen, sobald sich alle gesammelt haben.\n\nDa fällt mir ein, dass jemand nach Euch gefragt hat. Es war eine Magierin namens Myriam. Sie meinte etwas wie Ihr wärt \"bereit\".", progress = nil, completion = "Ein Schüler der arkanen Künste findet immer einen Weg nach vorne. Ich freue mich, Euch zu sehen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14278] = {title = "Sucht die Schwester", objective = "Sprecht mit Schwester Almyra im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Eine Geistliche namens Schwester Almyra sagte, Ihr befändet Euch in großer Gefahr und brauchtet den Schutz des Lichts.\n\nIhr solltet mit ihr reden. Sie schien sehr in Sorge zu sein.", progress = nil, completion = "Das Licht ist mit Euch, &lt;Name&gt;. Ich bin sehr erleichtert, Euch zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14279] = {title = "Das richtige Wort", objective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen und wendet es 2-mal gegen einen Blutfangworgen an.", description = "Ihr habt noch viel zu lernen, <Name>. Und ich habe Euch viel beizubringen.\n\nEs herrschen gefährliche Zeiten, daher fürchte ich, dass wir unsere Lektionen etwas beschleunigen müssen.\n\nHabt keine Angst, <Bruder/Schwester>. Das Licht wird uns beschützen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Setzt sie dann gegen die Blutfangworgen in der Nähe ein.", progress = nil, completion = "Ihr seid gesegnet, &lt;Name&gt;. Das Licht strahlt selbst in diesen finsteren Zeiten auf Euch herab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14280] = {title = "Die Winde kennen Euren Namen… anscheinend", objective = "Sprecht mit Celestine Erntedank im Militärviertel.", description = "Die meisten von uns haben es lebend hierher geschafft, aber auch in diesem Teil der Stadt gibt es Worgen.\n\nWir werden weiter nach Süden ziehen, sobald sich alle gesammelt haben.\n\nDa fällt mir ein, dass jemand nach Euch gefragt hat. Es war die Erntehexe Celestine. Sie sagte, die Winde hätten Euren Namen geflüstert.\n\nIhr solltet Euch lieber beeilen, <Name>. Ihr müsst schnell zurückkommen und den Worgen den Garaus machen, wenn Ihr Euer Gespräch mit der Natur beendet habt.", progress = nil, completion = "Welcher Segen ereilt uns heute! Ihr seid am Leben und wohlauf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14281] = {title = "Frostnova", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Übt 'Frostnova' an einem Blutfangworgen.", description = "Es liegt ein harter Weg vor uns, <Name>. Wir müssen all unsere geistige Kraft auf unsere Aufgabe richten.\n\nWenn Ihr an Macht gewinnt, werden sich Euch neue Wege zum Arkanen in Eurem Geist offenbaren. Ihr werdet Zauber entwickeln, die Ihr vorher noch nicht kanntet.\n\nGeht, sammelt Erfahrung und nutzt dann das, was Ihr gelernt habt, gegen die Blutfangworgen.", progress = "Ich wusste gleich, dass Ihr ein begabter Schüler seid!", completion = "Ihr habt diesen Zauber so schnell und problemlos erlernt. Bald schon werdet Ihr andere unterrichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14282] = {title = "Rätsel gelöst", objective = "Ihr sollt die uralten Neptulon-Gravuren zu Korrah, Forscher des Cenarius bringen.", description = "Eure Bemühungen haben sich ausgezahlt. Das große Risiko, das Ihr eingegangen seid, hat sich gelohnt.\n\nIhr habt das Objekt der Begierde der Naga gefunden und damit ihre Gründe dafür, warum sie die Küsten von Desolace überrennen.\n\nWas die Gravuren angeht, die Ihr entdeckt habt – Eure nächste Aufgabe ist klar...", progress = "Was habt Ihr herausgefunden, <Klasse>?", completion = "Die Vision traf zu!\n\nIm Alleingang habt Ihr das erreicht, wo andere gescheitert sind.\n\nDer Zirkel wird keine Wahl haben, als diesen Entdeckungen seine Aufmerksamkeit zu schenken.", rewards = "Geschmückter GurtSteinpresserkopfbedeckungFelsengriffzerstörerDer folgende Zauber wird auf euch gewirkt:\n\nNagaverkleidung ausziehen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14283] = {title = "Mondfeuer", objective = "Erreicht Stufe 3, um 'Mondfeuer' zu erlernen und wendet es dann gegen einen Blutfangworgen an.", description = "Wir standen schon einmal am Rande der Ausrottung, <Name>. Aber wir Druiden, Hüter des alten Wegs, haben unsere Leute vor der Hungersnot gerettet.\n\nAls wir uns selbst von der Außenwelt abschnitten und unsere Ernte ein Misserfolg war, war es unser Orden, der den Segen der Erde herbeigerufen und die Früchte wieder zum Wachsen gebracht hat.\n\nGenauso wie damals sollten wir unser Schicksal in die Hände einer höheren Macht legen. Kommt mit mir und lernt, was die Wildnis uns zu lehren hat.\n\nGeht, entwickelt Eure Kräfte und setzt das, was Ihr erlernt habt, gegen die Blutfangworgen ein.", progress = "Die Erde spricht mit uns, <Name>. Sie wird uns nicht verlassen. Auch nicht in diesen finsteren Zeiten.", completion = "Nicht schlecht. Vielleicht besteht ja doch noch Hoffnung für die alten Wege.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14284] = {title = "Die Rache eines Klagegeistes", objective = "Hydronis will, dass Ihr ihn besteigt und die Priesterin Valishj besiegt.", description = "Ich bin Hydronis, ein Diener von Neptulon dem Gezeitenjäger, Herr über alle Gewässer.\n\nAzshara und ihre finsteren Naga haben sich gegen meinen Meister verbündet und ihm den Krieg erklärt. Das ist die erste in einer langen Reihe von Schlachten.\n\nIch habe erbittert gekämpft, <Volk>, und ich mache mir Sorgen.\n\nEs scheint, dass meine Taten hier die Aufmerksamkeit ihrer Priesterin auf sich gezogen haben.\n\nAllerdings habe ich nicht die Stärke, sie zu überwinden. Aber vielleicht können wir sie mit vereinten Kräften besiegen.", progress = nil, completion = "Die Priesterin existiert nicht mehr...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14285] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Solange die Worgen es darauf angelegt haben, uns alle Gliedmaßen auszureißen, kann ich Euch leider nicht so viel beibringen, wie ich möchte.\n\nWir sollten wirklich in Betracht ziehen, mit den anderen Überlebenden nach Süden zu ziehen. Wir haben erfahren, dass König Graumähne sich dort aufhält.\n\nWenn wir zusammen bleiben, steigen unsere Überlebenschancen... besonders wenn Ihr neben jemandem steht, der schmackhaft aussieht.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14286] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14287] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14288] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Solange die Worgen es darauf angelegt haben, uns alle Gliedmaßen auszureißen, kann ich Euch leider nicht so viel beibringen, wie ich möchte.\n\nWir sollten wirklich in Betracht ziehen, mit den anderen Überlebenden nach Süden zu ziehen. Wir haben erfahren, dass König Graumähne sich dort aufhält.\n\nWenn wir zusammen bleiben, steigen unsere Überlebenschancen... besonders wenn Ihr neben jemandem steht, der schmackhaft aussieht.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14289] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nDie anderen werden in diesen dunklen Zeiten die Hilfe des Lichts dringend benötigen.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14290] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14291] = {title = "Je mehr, desto sicherer", objective = "Sprecht mit König Genn Graumähne im Militärviertel.", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", progress = nil, completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14292] = {title = "Der Feind unserer Feinde", objective = "Korrah, Forscher des Cenarius, will, dass Ihr mit Lord Hydronis sprecht.", description = "Ihr habt uns einen großen Dienst erwiesen, <Klasse>.\n\nObwohl sie weiterhin eine imposante Streitmacht sind, haben Eure Bemühungen den Naga ein wichtiges Artefakt vorenthalten.\n\nIch werde meinen Mitstreitern von Eurem Fund berichten. Währenddessen hat sich der Wasserklagegeist auf der Insel Ranazjar die ganze Zeit alleine gegen den ständigen Ansturm der Naga zur Wehr gesetzt.\n\nIch bitte Euch, ihn ausfindig zu machen. Findet heraus, ob es eine Möglichkeit gibt, ihm zur Seite zu stehen.", progress = nil, completion = "Ich habe Eure Taten hier wohl beobachtet, &lt;Volk&gt;.\n\nEure Anwesenheit ist sehr geschätzt und kommt genau im rechten Augenblick.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14293] = {title = "Rettet Krennan Aranas", objective = "Rettet Krennan Aranas.", description = "Noch so viele Jahre nach dem Krieg hat Crowley genügend Waffen in diesem Keller versteckt, um das halbe Viertel in die Luft zu jagen.\n\nLeider werden wir das wahrscheinlich auch tun müssen.\n\nWir können das Feuer jedoch noch nicht eröffnen, da ein Zivilist auf der anderen Seite des Gefängnisses in der Falle sitzt.\n\nUnd dabei handelt es sich nicht um irgendeinen Zivilisten. Krennan Aranas ist einer der brillantesten Alchemisten, den die Welt je gesehen hat.\n\nEiner seiner Tränke hat meine Tochter Tess kurz nach der Geburt vor dem sicheren Tod gerettet.\n\nNehmt mein Pferd und rettet ihn. Krennan darf nicht sterben.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wir werden dafür sorgen, dass Krennan heil aus der Stadt fliehen kann.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Cannon Camera\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14294] = {title = "Neu formieren", objective = "Sprecht mit König Genn Graumähne im Graumähnenhof in Gilneas.", description = "Wir haben hier alles getan, was wir tun konnten. Gebt König Graumähne Bescheid, dass wir etwas Zeit herausschinden konnten.\n\nIch habe das Gefühl, dass es nicht lange dauern wird, bis die Worgen sich neu formieren.\n\nWir werden uns in den Graumähnenhof im Westen zurückziehen müssen, wenn es so weit kommt. Das ist der letzte Ort, an dem wir standhalten können, ohne wie ein Fisch im Netz zu zappeln.", progress = nil, completion = "Viele Möglichkeiten stehen uns nicht zur Auswahl, &lt;Name&gt;. Unser nächster Schritt wird eine wichtige Entscheidung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14295] = {title = "Schwestern des Meeres", objective = "Tötet Lady Silisthra und Lady Vesthra, indem Ihr ihre Kraftsteine deaktiviert.", description = "Zwei Hexen der Naga haben den Angriff auf diesen Außenposten ersonnen. Sie haben die direkten Angriffe meiner besten Grunzer abgewehrt, aber Ihr könnt die Aufgabe erledigen, an der andere gescheitert sind.\n\nFindet und vernichtet Lady Silisthra und Lady Vesthra am östlichen Rand der Klippen in der Nähe der Ruinen des uralten Nachtelfenkolosses. Ihr müsst zuerst die Kraftsteine vernichten, die ihnen ihre Stärke geben. Enttäuscht mich nicht, <Klasse>!", progress = nil, completion = "SO springen wir mit Schlangen in Durotar um – Wir zertreten sie unter unseren Stiefeln! Ihr habt die Horde stolz gemacht, &lt;Name&gt;. Sobald meine Verstärkung eintrifft, fegen wir den Rest dieses Ungeziefers von der Halbinsel und beanspruchen sie ein für alle Mal für uns.", rewards = "SeeschwesternwesteHandschuhe des SchlangenzermalmersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14296] = {title = "Stolpert nicht", objective = "Empfangt 6 Energieladungen von den Energieleitungen, während ihr zum Gipfel der Arkanen Spitze gelangt.", description = "Auf eine Art ist dies einfach und auf eine andere Art nicht. Den ganzen Weg nach dort oben liegen Energieleitungen. So ähnlich wie diese hier möchte ich sagen! Ich sage es also.\n\nNun zu Euch. Ihr müsst meine Springfelder verwenden, um die Spitze zu erreichen und Ihr müsst alle Leitungen berühren, die Ihr auf Eurem Weg seht. Wenn Ihr bei mir an der Spitze ankommt, solltet Ihr vor Energie nur so triefen und so soll es auch sein.\n\nUnd achtet darauf, dass Ihr nicht stillsteht, denn sonst werdet Ihr vermutlich eine unangenehme Reise antreten!", progress = "Neinneinnein, so läuft das nicht. Ihr solltet die Energie der Leitungen empfangen, bevor Ihr hier herauf kommt, erinnert Ihr Euch?\n\nNoch einmal und mit etwas mehr Haltung!", completion = "In diesem Augenblick fragen sich die meisten Schüler, ob es einen logischen Grund dafür gibt, die Energie für mein Portal in diesen Leitungen zu speichern und ob sie auf diese Weise gesammelt werden muss.\n\nNatürlich gibt es einen Grund! Ich will Euer Verhalten erforschen... Eure Strategien, Eure Fehler, Eure Frustration, Eure Siege. Das ist der eigentliche Witz, der hinter diesen Prüfungen steckt.\n\nUnd nun noch weitere. Noch mehr Prüfungen! Klingt das nicht aufregend?! Aber natürlich.", rewards = "Aufgeladene RobenSaftige ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14297] = {title = "Freiheitskämpfer", objective = "Verwendet die schmiedeeisernen Schlüssel der Kultisten und der Drachenkin, um 4 Arbeiter der Goblins auf dem Säbelrücken zu befreien.", description = "Ich wusste, dass diese Kerle Schwierigkeiten machen werden, sobald wir mit dem Turmbau anfingen. Sie spotten über unsere Bestechungsgelder. Sie stehlen unsere Arbeiter.\n\nArbeitskraft ist heutzutage nicht billig, wo in Azshara so viel gebaut wird. Ich muss diese Männer wiederhaben!", progress = nil, completion = "Dank Euch, Kumpel. Hier ist Eure Provision.\n\nNun entschuldigt mich. Ich muss dafür sorgen, dass diese Faulpelze wieder an die Arbeit gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14299] = {title = "Xylems Asyl", objective = "Nehmt das Portal zum Turm des Erzmagiers Xylem und sucht im Turm nach Joanna.", description = "Ziemlich fabelhaft von Euch! Eine wahre Freude, Euch bei der Arbeit zuzusehen. Es gibt viel zu erforschen.\n\nUnd nun los, ruht Euch in meinem Turm aus. Joanna wird Euch unterbringen. Ich öffne ein Portal für Euch.", progress = nil, completion = "Willkommen! Ihr scheint die Prüfungen relativ unbeschadet überstanden zu haben. Gut für Euch, Liebchen.\n\nIhr seht so aus, als ob Ihr mit einer bestimmten Absicht hergekommen seid. Eine Frage. Eure Gedanken sind sehr laut. Es ist mir fast unmöglich, sie zu überhören.\n\nNa los, Schätzchen. Fragt mich schon.", rewards = "AsylschuheJoannas SchärpeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14300] = {title = "Die Prüfung des Feuers", objective = "Besteht die Prüfung des Feuers, indem Ihr in den Feuerrunen steht und 10 aufeinanderfolgende Explosionen übersteht, ohne getroffen zu werden.", description = "Die Prüfung des Feuers... ohooo... Das klingt einschüchternd, nicht wahr? Nein? Hm. Tja, das habe ich mir irgendwie gedacht. Wer zuerst kommt, mahlt zuerst. Ihr berührt den Feuerkristall und das Portal zur Prüfung öffnet sich.\n\nUm diese Prüfung zu bestehen, müsst Ihr durch die Feuerrunen springen, ohne von dem Feuer getroffen zu werden. Falls Ihr lange genug durchhaltet, ohne in Flammen zu stehen, habt Ihr gewonnen!\n\nEs gibt kleine Anzeichen, die Euch helfen. Das Feuer springt zu einer neuen Rune und es zischt, wenn eine Rune erkaltet. Wenn Ihr wollt, findet es heraus. Oder Ihr ratet einfach! Das machen die meisten so.", progress = nil, completion = "Hui! Gut für Euch! Die Prüfung macht einem wirklich Feuer unter dem Hintern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14301] = {title = "Kehrt zurück und berichtet", objective = "Kehrt zu Korrah, Forscherin des Cenarius in Ethel Rethor zurück.", description = "Es ist vollbracht! Gemeinsam haben wir es geschafft, einen gefährlichen Gegner auszuschalten.\n\nNeptulon selbst wird von Euren Heldentaten zu hören bekommen, <Klasse>. Erlaubt mir, Euch in seinem Namen zu danken...\n\nIhr solltet nun gehen. Dieser Ort wird für Euch nicht mehr lange sicher sein. Bald werden die Naga auf Rache für ihre Priesterin sinnen.", progress = nil, completion = "Bitte nehmt diese Belohnung für Eure Heldentaten entgegen, &lt;Name&gt;.\n\nIhr habt uns wertvolle Zeit erkauft!", rewards = "Langbogen der DornenschuppenBalsamwickelWeste des fließenden WassersKnisternder GurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14302] = {title = "Offizielle Einschätzung", objective = "Korrah, Forscherin des Cenarius, will, dass Ihr Korrahs Bericht zu Karnum in Karnums Hain bringt.\n\nBereitgestellter Gegenstand: \n", description = "Ihr habt mit Euren Bemühungen gegen die Naga viel erreicht, <Name>. Aber ich fürchte, es ist nicht einmal ansatzweise genug...\n\nDies ist meine offizielle Einschätzung der Anwesenheit der Naga.\n\nIch bin mir sicher, dass meine Mitstreiter in der Wildnis die notwendigen Maßnahmen einleiten werden.\n\nBringt dies zu Karnum im Hain in der Mitte der Cenariuswildnis im Südwesten. Er wird wissen, was zu tun ist.\n\nHabt Dank, <Name>. Und lebt wohl.", progress = nil, completion = "&lt;Karnum öffnet Korrahs Bericht und liest ihn.&gt;\n\nDas ist wahrhaftig eine alarmierende Neuigkeit, &lt;Volk&gt; – etwas, das hier leider keine Seltenheit ist.\n\nIch werde den Rat in dieser Angelegenheit einberufen. Ihr werdet hinzugezogen, wenn es vonnöten sein sollte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14303] = {title = "Zurück zu Aggra", objective = "Informiert Aggra im Basislager der Horde auf den Verlorenen Inseln über die Geschehnisse.", description = "Kehrt zum Basislager der Horde zurück und lasst Aggra wissen, dass wir noch am Leben sind, <Name>.\n\nSagt ihr, dass ich zur Wilden Aussicht weiterziehe und dass wir uns alle im Nordwesten der Insel treffen. Ich erwarte Euch dort.\n\nWir werden die Fährte der Allianz aufnehmen und jeden einzelnen von ihnen töten!", progress = nil, completion = "&lt;Aggra betrachtet Euch argwöhnisch, als würde sie Euch nicht glauben.&gt;\n\nIch bin nicht leicht zu beeindrucken, aber wenn das, was Ihr sagt, stimmt, dann habe ich noch nie zuvor so etwas gehört.\n\nIhr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14304] = {title = "Blutabnahme", objective = "Sammelt 10 blutgefüllte Egel.", description = "In Desolace hat sich nicht nur das Land verändert. Hier haben die Wildtiere auf ihre neue Umgebung auf seltsame und manchmal höchst interessant Weise reagiert.\n\nBesonders interessiert bin ich an den verjüngten Donnerechsen, die in dieser Gegend im Westen umherstreifen.\n\nIch brauche eine Probe ihres Blutes.\n\nIhr könnt anfangen, mir zu helfen, indem Ihr dieses Glas voller Blutegel auf ein paar von ihnen absetzt.\n\nSobald sie sich mit dem Blut dieser Tiere vollgesogen haben, bringt sie mir zurück.", progress = "Habt Ihr die Proben bekommen, die ich benötige?", completion = "Das sollte ausreichen.\n\nHabt Dank, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14305] = {title = "Erntezeit", objective = "Sammelt 10 Aloedisteln.", description = "Keiner weiß es besser, als der Zirkel des Cenarius, dass diese grünende Oase genauso schnell vertrocknen kann, wie sie erblüht ist.\n\nWir müssen dafür sorgen, dass wir uns nicht in die Prozesse einmischen, die hier stattfinden, aber wir müssen sie unterstützen und schützen.\n\nEine neue Pflanzensorte hat sich nach der großen Teilung in der umgebenden Region breitgemacht.\n\nSammelt mir ein paar Proben dieser Pflanzen, sodass ich sie untersuchen kann. Ich will herausfinden, was wir von ihnen lernen können.", progress = "Habt Ihr die Proben gesammelt, die ich benötige?", completion = "Das sind schöne Exemplare, &lt;Volk&gt;.\n\nIch werde sofort mit meinen Untersuchungen beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14306] = {title = "Unkraut jäten", objective = "Tötet 7 entwurzelte Peitscher.", description = "Bei einem derart abrupten Wandeln der Ökologie ist zu erwarten, dass einige Teile der Flora und Fauna nicht so reagieren, wie wir es uns erhoffen.\n\nDie entwurzelten Peitscher sind ein lästige Beispiel dafür. Sie befinden sich in den Feldern im Osten und Süden und schaden der Region. Wir müssen sie loswerden.\n\nWährend Ihr dort seid, kümmert Euch bitte um alle dieser Schädlinge, die Ihr finden könnt.", progress = nil, completion = "Im Namen von Desolace selbst danke ich Euch, &lt;Volk&gt;.\n\nBitte nehmt unsere tiefste Dankbarkeit an.", rewards = "PeitscherstachelhandgelenksschützerStichwundenverbindende SchiftungPhytoresistenter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14307] = {title = "Steife Brise", objective = "Zerstört 5 Wirbelsturmgänger.", description = "Wandel liegt in der Luft, <Volk>. Daran besteht kein Zweifel.\n\nEs gibt zahlreiche, dringende Angelegenheiten, die um unsere Aufmerksamkeit und unsere Tatkraft buhlen. Die wichtigste unter ihnen ist der Ausbau unserer wachsenden Oase.\n\nSie ist schneller gewachsen, als wir zu hoffen gewagt haben und auch schneller, als wir verstehen können. Dennoch stößt das Wachstum nun auf Widerstand.\n\nIm Westen, wo das Gras auf den Sand trifft, verhindern Wirbelstürme ihr weiteres Eindringen in die Wüste.\n\nGeht und vernichtet diese lebensfeindlichen Hindernisse!", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Klasse&gt;.\n\nWir werden Euch zukünftig zweifellos in wichtigeren Angelegenheiten um Hilfe bitten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14308] = {title = "Angriff der Wissenschaft", objective = "Verwendet den Feuerliminator X-21, um 8 Feuer zu löschen und rettet 6 Laborpraktikanten aus dem Inferno im Geheimlabor.\n\nSprecht mit Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn, solltet Ihr Euren Feuerliminator verlieren.", description = "Habt Ihr die Explosionen auf Eurem Weg hierher gesehen? Das Geheimlabor steht in Flammen! Schon wieder! Wenn wir diese Flammen nicht löschen, wird die Temperatizität kritisch und das wird in einer Schmelzkettenreaktion resonieren.\n\nHier. Ich vertraue Euch einen Kanister eines experimentellen, hypergekühlten Druckflüssiggels an: das flüchtigste Feuerlöschmittel, das der Wissenschaft bekannt ist! (Haltet den Kanister fern von offenen Flammen.) Löscht das Feuer und rettet meine Praktikanten. Dann kontaktiert mich über den Quäkkasten der Zentralsteuerung.", progress = "<Greelys Quäkstimme dringt durch ein Lautsprecherpaar.>\n\nRaketenbahn an Geheimlabor! Raketenbahn an Geheimlabor! Geheimlabor, bitte kommen...", completion = "Gute Arbeit, &lt;Name&gt;! Jetzt müssen wir die Reaktionskernmatrix vom Treibstofftank trennen oder wir kriegen hier unsere eigene Mini-Scherbenwelt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14309] = {title = "Der Kodoflüsterer", objective = "Benutzt das Kodobesänftigungsmittel in der Nähe von 5 wütenden Kodos.", description = "Wie Ihr bereits bemerkt habt, können die ungewöhnlich schnellen Veränderungen in dieser Region sowohl positive als auch negative Effekte auf die einheimischen Kreaturen haben.\n\nIm Süden und im Osten sind wütende Kodos eine ständige Bedrohung für jeden in der Nähe.\n\nEs wird Zeit, meine Theorie zu testen. Ich habe das Blut der verjüngten Donnerechse für die Herstellung dieses Gebräus verwendet. Ich hoffe, dass er die Kodos besänftigen wird, die ihn zu sich nehmen.\n\nPlatziert ihn in der Nähe eines wütenden Kodos und seht zu, dass Ihr es mit dem entsprechenden Sicherheitsabstand tut!", progress = nil, completion = "Wundervoll! Karnum wird sehr erfreut sein!\n\nBitte nehmt dies zum Dank dafür.", rewards = "KodohirtenbedeckungStaubiges LassoDer BeruhigerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14310] = {title = "Schutzverletzung: Kernabkopplung", objective = "Aktiviert das Reaktorkontrollpult und eskortiert den Azsharitkern zurück zur Südlichen Endhaltestelle der Raketenbahn. Wendet den Feuerliminator X-21 auf den Kern an, damit er sich nicht überhitzt.", description = "Sobald wir den Zentralreaktor versenkt haben, müsst Ihr den Kern zu mir bringen. Er besteht aus 100% raffiniertem Azsharitkristall, der sowohl mächtig als auch gefährlich ist. Und hübsch anzusehen. Oh, du schöner Azsharit, Former der kommenden Welten!\n\nDer riesenhafte Hebel zu Eurer Linken wird den Kern versenken und über das Schienensystem zu mir schicken. Der Kern wird stark erhitzt sein. Deshalb müsst Ihr ihn immer wieder mit dem Feuerliminator auf dem Weg hierher abkühlen... Er darf keinesfalls kritische Temperatur erreichen!", progress = "Sorgt Euch nicht um die Spätfolgen all dieser ätzenden Chemikalien im Labor. Haare wachsen nach!", completion = "Puh, die Probe ist in Sicherheit. Und sie dampft noch immer! Habt Dank, &lt;Name&gt;.\n\nAzsharit ist ein komplexes Geheimnis, gehüllt in ein samtiges Rätsel der Gefahr. Wurfhammer besteht darauf, dass wir mehr über diese mysteriöse Substanz herausfinden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14311] = {title = "Wer Ernten will muss säen", objective = "Pflanzt 5 Samen des Cenarius in der Nähe der fruchtbaren Erdhügel in der Cenariuswildnis.", description = "In was für herrlichen Zeiten wir doch leben!\n\nDas ehemalige Ödland von Desolace blüht und birst vor Leben. Stellt Euch vor, <Klasse>, das Ödland von ganz Azeroth würde in dieser Art erblühen! Vielleicht eines Tages...\n\nEs stimmt, dass es hier gewichtigere Dinge gibt, aber warum sollten wir uns nicht einen Augenblick Zeit nehmen, um die erstaunlichen Wunder zu würdigen, deren wir Zeuge sein dürfen?\n\nOder warum nehmen wir nicht daran Teil? Hier sind ein paar Samen des Cenarius. Verwendet sie an einem fruchtbareren Ort in der Einöde.\n\nEs ist die perfekte Medizin zur Erheiterung der sorgenvollen Seele!", progress = nil, completion = "Die Verjüngung ist so belebend! Findet Ihr nicht auch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14312] = {title = "Vorstellung beim Khan", objective = "Garren Finsterwind auf Karnums Lichtung will, dass Ihr mit Khan Leh'prah sprecht.", description = "Ich habe von Euren Heldentaten hier in Desolace gehört, <Name>. Wir stehen in Eurer Schuld.\n\nLeider muss ich Euch bereits in einer weiteren Angelegenheit um Hilfe bitte, die dringlicher ist als der Rest.\n\nHier hat sich in der letzten Zeit nicht nur die Landschaft verändert. Alte Konflikte sind neuen, noch schlimmeren gewichen. Ich sollte unseren Gästen erlauben, alles Weitere zu erklären...\n\nKhan Leh'prah ist einer der Letzten des Stammes der Kolkar, der einst den gesamten Osten von Desolace beherrschte. Wir fanden ihn dem Tode nah an unserer Grenze. Hört seine Worte.", progress = nil, completion = "Habt keine Angst, &lt;Volk&gt;. Ich tue Euch nichts zuleide.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14313] = {title = "Wieder unter Menschen", objective = "Sprecht mit Krennan Aranas in Dämmerhafen.", description = "Krennans Trank hat Euch also nicht umgebracht? Nun, das heißt wohl, dass der Mensch in Euch die Überhand hat.\n\nUnter diesen Umständen werde ich Euch doch nicht erschießen. Zumindest noch nicht.\n\nSprecht mit Krennan Aranas und überbringt ihm die gute Nachricht.\n\nAber vergesst nicht, <Name>. Ich behalte Euch im Auge. Sobald Ihr irgendetwas Merkwürdiges versucht, jage ich Euch eine Kugel zwischen die Augen.", progress = nil, completion = "Es hat funktioniert! Beim Licht, es hat funktioniert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14314] = {title = "Ausbruch!", objective = "Tötet den Wächter der Magram im Dorf der Magram.", description = "Es begann mit einem Traum, der mich immer wieder vor einer Gefahr warnte, die da kommen sollte. Ich sah die dämonischen Legionen über unsereins herfallen und das Land überrennen.\n\nDer Traum ist wahr geworden. Die Brennende Klinge und ihre Dämonenmeister haben die Magram aus ihren Ländern im Süden vertrieben. Im Gegenzug haben die Magram mein Volk vernichtet und unsere Heimat übernommen.\n\nDer Kampf war wild und grausam. Nur eine Handvoll der Kolkar ist noch am Leben. Ich bitte Euch, dorthin zu gehen, wo einst mein Land im Osten war, und sie aus Ihrem Gefängnis zu befreien.", progress = nil, completion = "Habt Dank, &lt;Volk&gt;.\n\nUnser Stamm hätte ohne Eure Hilfe nicht überlebt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14316] = {title = "Cenarisches Eigentum", objective = "Sammelt 7 Vorratskisten des Cenarius in den Ländern der Magram.", description = "Seit die Dämonen ihr Land überfallen haben, haben die Magram alle Verbindungen zu Außenstehenden abgebrochen.\n\nSie sind misstrauisch und feindselig und haben damit begonnen, von anderen zu stehlen, anstatt für sich selbst zu sorgen.\n\nViele unserer benötigten Vorräte sind kürzlich verschwunden und wir vermuten, dass die Magram schuld daran sind.\n\nBitte, <Name>, geht zu ihrem Land im Osten und sucht nach unseren Besitztümern.", progress = "Habt Ihr unsere Besitztümer gefunden, <Name>?", completion = "Wie wir vermutet haben, haben die Magram unsere Vorräte gestohlen.\n\nWir werden sie in Zukunft besser bewachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14318] = {title = "Feinfühlige Verhandlungen", objective = "Khan Leh'prah will, dass Ihr den Speer des Khans der Kolkar in den Vaterstein treibt und ihn vor den Magram verteidigt, bis Khan Kammah erscheint.\n\nSprecht mit Khan Leh'prah, sobald Ihr bereit seid, zum Schlachtfeld zu reiten.", description = "Es gibt nur eine Möglichkeit, das Vertrauen und die Loyalität der Magram zu gewinnen.\n\nWir müssen sie aus ihnen herausprügeln.\n\nSie haben im Krieg gegen meinen Klan viele Verluste erlitten. Jetzt besitzen sie ein unvertrautes Land, wo sie darum kämpfen müssen, überhaupt genug zu essen zu haben.\n\nJetzt ist die richtige Zeit, um zuzuschlagen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid. Dann reitet hinein und treibt meinen Speer in den Vaterstein. Wenn wir genug von ihnen töten, wird sich ihr Khan unserem Willen unterwerfen.", progress = nil, completion = "Warum mischt Ihr Euch in die Angelegenheiten der Zentauren ein, &lt;Volk&gt;?", rewards = "Tuch der ZentaurenträumeTrutzturmschulterschutzStörrische BeinschützerDer folgende Zauber wird auf euch gewirkt:\n\nForce Reaction Magram\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14320] = {title = "Benötigte Zutaten", objective = "Findet die Kiste mit Alraunenessenz.", description = "Ah, ja. Soweit wir wissen, gibt es kein Heilmittel gegen die Folgen des Fluchs.\n\nMit der richtigen Behandlung können wir jedoch dafür sorgen, dass Euer Verstand der Eurige bleibt, nicht der eines wilden Tiers.\n\nWir haben Glück, dass die Behandlung bei Euch angeschlagen hat. In der Regel lassen sich nur kürzlich erfolgte Infektionen behandeln.\n\nWenn wir eine Hoffnung haben wollen, den Fluch jemals rückgängig zu machen, müsst Ihr weiter Eure Medizin einnehmen.\n\nFür weitere Dosen meines Serums benötige ich Alraunenessenz. Unter einer Hütte südwestlich von hier findet Ihr eine Kiste mit dieser Essenz.", progress = nil, completion = "Die Kiste wurde offensichtlich zerschlagen. Alle darin enthaltenen Phiolen sind zerbrochen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nInvasion Camera\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14321] = {title = "Invasion", objective = "Sprecht mit Gwen Armstead in Dämmerhafen.", description = "<Ein langes Messer, dessen Griff mit einem Schädel verziert ist, ragt aus dem Rücken des Milizionärs. Als Ihr Euch nach Hinweisen umseht, entdeckt Ihr ein paar wild aussehende Kriegsschiffe an der Küste.>\n\n<Jemand fällt in Gilneas ein. Berichtet sofort der Bürgermeisterin von Dämmerhafen, Gwen Armstead, davon.>", progress = nil, completion = "Verlassene! Schnell, &lt;Name&gt;! Wir müssen eine Verteidigung zusammenstellen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14322] = {title = "Böse Wissenschaft! Pfui!", objective = "Tötet 8 statisch aufgeladene Hippogryphen.", description = "Ich habe versucht, die einheimischen Hippogryphen zu domestizieren. Als ich eine Reihe von schwächenden Elektroschocks eingesetzt habe, sind sie aus irgendeinem Grund durchgedreht! Jetzt nehmen meine Testsubjekte diesen Ort völlig grundlos auseinander! <Klasse>, geht und schlachtet meine gescheiterten Experimente ab, bevor sie mich finden.", progress = nil, completion = "Die Welt ist also wieder sicher für die Wissenschaft? Ausgezeichnet! Das nächste Mal versuche ich es mit glühenden Nadeln oder so.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14323] = {title = "Supersaugstark", objective = "Saugt 20 köchelnde Wassertropfen der üblen Platscher im Osten der Ruinen von Arkkoran auf.", description = "Ich brauche noch etwas anderes. Heißes Wasser.\n\nEs ist hier nicht leicht zu bekommen. Keine heißen Quellen, keine Freunde, die mit einem teilen. Aber es gibt dennoch eine Möglichkeit. Nehmt diesen Schwamm... Er ist supersaugstark. Verwendet ihn, um ein paar üble Platscher auf der Sandbank im Osten aufzusaugen.\n\nHabt Ihr genug, wringt sie in der Nähe des Turms aus, um den Jumbo-Elementar zu beschwören. Er hat heißes Wasser.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14324] = {title = "Voll heißen Wassers", objective = "Erlangt eine Kugel voll kochendem Wasser von einem brühenden Wasserlord am Turm von Eldara.", description = "Ergll deutete an, dass Ihr in der Lage sein solltet, den vollgesogenen Seeschwamm aus Azshara dazu zu verwenden, einen 'Jumbo'-Elementar in der Nähe des Turms von Eldara im Nordosten zu beschwören.", progress = "Ihr seid zurück!", completion = "Bequem, nicht wahr? Wer braucht schon heiße Quellen? Das ist perfekt.", rewards = "Verbrühende HandschuheSchwammige WesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14325] = {title = "Arbeite für Essen", objective = "Sammelt 5 Basiliskenflanken.", description = "<Khan Kammah hört Euch aufmerksam zu, während Ihr ihm die dämonische Bedrohung erläutert und von Khan Leh'prahs Visionen berichtet.>\n\nEs ist nicht notwendig, uns einen Vortrag über Dämonen zu halten, <Volk>. Sie waren es, die unseren Klan aus unseren angestammten Ländern vertrieben haben.\n\nSie waren es, die uns gezwungen haben, das Ödland der Kolkar zu übernehmen, wo wir nun um unser Überleben kämpfen.\n\nDurch den Krieg gegen die Kolkar hat unser Volk große Verluste hinnehmen müssen. Die Wenigen, die von uns übrig geblieben sind, sind müde und hungrig.\n\nBringt meinem Volk Essen und dann können wir uns über Dämonen unterhalten.", progress = "Habt Ihr Nahrung für meinen Klan mitgebracht, <Volk>?", completion = "Sehr gut, &lt;Volk&gt;!\n\nDies wird uns für den Moment am Leben erhalten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Reaction Magram 4\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14326] = {title = "Aufs Oberdeck", objective = "Begebt Euch auf das obere Deck der Sog der Vergeltung an der Küste der Verlorenen Inseln und sprecht mit Thrall.", description = "Ich hätte nie gedacht, dass ich einst wieder ein Gefangener der Allianz sein würde. Ich kann Euch nicht sagen, wie dankbar ich bin… <Name>, oder?\n\nIch treffe Euch auf dem obersten Deck. Von dort machen wir ihnen den Garaus!", progress = nil, completion = "Meine Mission ist zu wichtig, um eine Einmischung durch diese Hunde zuzulassen. Es liegt an uns beiden, ihnen ein für alle Mal ein Ende zu setzen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMeet Me Up Top: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14327] = {title = "Versprochen ist versprochen", objective = "Khan Kammah will, dass Ihr mit Khan Leh'prah sprecht.", description = "Es scheint, als ob wir keine Wahl haben.\n\nSo sehr es mir auch widerstrebt, mit den Kolkar zusammenzuarbeiten, in den Worten ihres Khans liegt Weisheit.\n\nIhr dürft ihm mein Wort geben, dass unsere Speere ihm in der Schlacht beistehen werden.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Klasse&gt;.\n\nJetzt müssen wir die Gelkis überzeugen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14328] = {title = "Drei Prinzen", objective = "Tötet Rhoho, Sherik, und Jorreth.", description = "Die Gelkis halten sich im Südwesten von Desolace auf. Sie sind genauso stur wie die Magram, und da sie von Krieg und Vertreibung verschont geblieben sind, sind sie bedeutend stärker.\n\nUm die Gelkis gefügig zu machen, wird es einer besonderen Machtdemonstration bedürfen.\n\nKhan Shodo und seine drei Söhne regieren den Klan. Shodo ist alt und leidet unter seinen alten Kriegsverletzungen. Er verlässt niemals die Tiefen seiner Höhle. Die Quelle seiner Herrschaftsmacht liegt in seinen Söhnen.\n\nTötet sie und überzeugt den Khan, sich unserer Sache anzuschließen.", progress = nil, completion = "Meine Söhne sind alle tot... Mein Klan zerfällt...\n\nHätte ich noch meine Jugend, ich würde Euch Arme und Beine einzeln ausreißen!\n\nJetzt führt zu Ende, was Ihr begonnen habt. Tötet mich oder lasst mich alleine mit meiner Trauer, &lt;Volk&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Reaction Gelkis\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14329] = {title = "Nicht so schnell!", objective = "Khan Shodo will, dass Ihr 10 Raufer der Maraudine im Tal der Speere tötet.\n\nIhr müsst ihre Leichen nach Hinweisen über den Verbleib von Kherrah durchsuchen.", description = "<Der Khan des Klans der Gelkis starrt Euch aus leeren Augen an, als Ihr von der Bedrohung durch die Dämonen und Leh'prahs Visionen berichtet.>\n\nEs ist mir gleichgültig, was aus diesem Land wird. Ich habe meinen Klan und meine Vorväter im Stich gelassen...\n\nAuf dieser Welt gibt es nur noch eine Person, die meiner alten Seele Hoffnung geben könnte, und sie ist vermutlich ebenfalls tot.\n\nMeine geliebte Tochter Kharrah wurde vom Klan der Maraudine geraubt. Wenn Ihr sie mir lebend zurückbringt, werde ich Euren Vorschlag in Erwägung ziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14330] = {title = "Hinter verschlossenen Türen", objective = "Ihr müsst Kherrah finden, die in Maraudon gefangen gehalten wird.\n\nBereitgestellter Gegenstand: \n", description = "Ihr habt herausgefunden, wo sich Khan Shodos Tochter Kherrah aufhält. Sie wird in Maraudon gefangen gehalten!\n\nEin Rettungsversuch ist sicher riskant, aber wenn Ihr die Unterstützung des Klans der Gelkis wünscht, müsst ihr die Tochter des Khans befreien.", progress = nil, completion = "Kann ich gefahrlos gehen, &lt;Volk&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Reaction Gelkis 4\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14332] = {title = "Zeit für eine Veränderung", objective = "Kherrah will, dass Ihr mit Khan Leh'prah sprecht.", description = "<Kherrah hört Euch zu, während Ihr von den vorangegangenen Ereignissen berichtet.>\n\nIch stimme den Worten des Khans der Kolkar zu. Die Zeit des uralten Zwists ist vorüber. Es ist eine Schande, dass es einer dämonischen Krise bedurfte, um die Stämme zu vereinen.\n\nIch werde zu meinem Vater zurückkehren und ihn davon überzeugen, sich Eurer Sache anzuschließen. Ich gebe Euch mein Wort, dass er einwilligen wird.\n\nKehrt zu Khan Leh'prah zurück und unterrichtet ihn darüber, dass die Gelkis bereit stehen, wenn er sie ruft.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Volk&gt;.\n\nUnd keinen Augenblick zu früh...", rewards = "Kunstfertiger SchmuckdolchBrustharnisch des BotschaftersLautlose FußpolsterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14333] = {title = "Wo Ihr schon mal hier seid", objective = "Ihr sollt das Tal der Speere nach 6 entweihten Relikten absuchen.", description = "Die Maraudine überfallen die Lager der Gelkis seit vielen Jahren. Sie rauben alles, was sie in die Finger kriegen.\n\nEine Schandtat begehen sie besonders gerne: Sie stehlen die Relikte der Macht, die den Gelkis heilig sind. Sie schaffen sie hierher, um sie zu schänden.\n\nDer Klan der Gelkis wäre sicherlich sehr dankbar, wenn Ihr diese entweihten Artefakte findet und zerstört.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14334] = {title = "Blubberwampe", objective = "Mai'Lahii will, dass Ihr Blubberwampe tötet.", description = "Ahoi, Mann!\n\nMeint Ihr, Ihr seid in der Lage für dieses Dorf etwas zu tun?\n\nMit den meisten Walen werden wir fertig, aber dort draußen gibt es einen besonderen Wal, der zu groß für unsere Harpunen ist.\n\nBlubberwampe wird immer größer und größerer – und futtert all die Fische auf, von denen wir früher gelebt haben!\n\nBegebt Euch da raus und findet dieses Viehding - und dann lasst ihn für seine Gefräßigkeit bezahlen!", progress = nil, completion = "Ai, Mann! Ihr habt es geschafft!\n\nDank Euch haben wir bald wieder Frischfisch auf dem Tisch.", rewards = "Tranbefleckter HandschutzGeschmeidige OrcaschuppenschiftungAuf Euch wartet eine dieser Belohnungen:\n\nWalzahnanhängerOrcazahnring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14335] = {title = "Hummerplage", objective = "Tötet 5 Kaltschnappkriecher und 5 Kaltschnappzangen.", description = "Wie Ihr zweifelsohne bereits bemerkt habt, haben die Veränderungen dieses Landes zahlreiche Nebenwirkungen. Einige sind zum Vorteil, andere bereiten ernsthafte Probleme.\n\nGenau im Süden dieses Dorfes steigen die einheimischen Hummerstroks aus dem Meer und blockieren die Straße zum Dorf.\n\nBitte, <Klasse>, geht und dezimiert diese Plage.", progress = nil, completion = "Ich danke Euch im Namen aller Bewohner von Schattenflucht, &lt;Volk&gt;.", rewards = "KovenstreitaxtChitinrobenGeistwandlertreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14336] = {title = "Töten oder getötet werden", objective = "Sprecht mit Prinz Liam Graumähne außerhalb von Dämmerhafen.", description = "Die Riffe haben uns bisher immer vor einem Angriff vom Wasser aus bewahrt, doch die Erdbeben scheinen einen Weg für die Schiffe der Verlassenen geöffnet zu haben.\n\nSchnell, <Name>. Verlangsamt die Angriffe, während ich den Rest der Miliz bereit mache.\n\nIch glaube, ich höre den Prinz und seine Männer schon gegen die Verlassenen kämpfen. Sprecht mit Liam und schaut, wo Ihr helfen könnt.\n\nOh... und achtet darauf, dass er nicht in den sicheren Tod rennt. In seinem derzeitigen Zustand ist er leider etwas tollkühn.", progress = nil, completion = "&lt;Name&gt;!!! Ihr seid also WIRKLICH am Leben!\n\nIch dachte, ich hätte von alten Zeiten geträumt, als ich Eure Stimme hörte…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14337] = {title = "Schattenflucht", objective = "Karnum Marschenwirker will, dass Ihr mit Mai'Lahii sprecht.", description = "Da seid Ihr wieder, <Klasse>.\n\nIch habe Neuigkeiten aus Schattenflucht. Das Dorf braucht Hilfe. Wir haben hier alle Hände voll zu tun, also muss ich Euch bitten, Euch dort hinzubegeben und ihnen zur Seite zu stehen.\n\nDas Dorf liegt an der Küste südwestlich von hier. Wenn Ihr dort eintrefft, sucht nach derjenigen, die Mai'Lahii genannt wird.", progress = nil, completion = "Willkommen in Schattenflucht, &lt;Volk&gt;.\n\nIch war mir nicht sicher, ob der Zirkel des Cenarius jemanden schicken würde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14338] = {title = "Der Geistwandlerposten", objective = "Karnum Marschenwirker will, dass Ihr mit Maurin Knochenspalter sprecht.", description = "Seid gegrüßt, <Klasse>!\n\nEs ist schön, zu sehen, dass Ihr noch atmet. Die Zeit ist gekommen, Euch um Eure Hilfe zu bitten.\n\nIm Südwesten dieser Lichtung befindet sich der Geistwandlerposten. Dort werdet Ihr einen Verlassenen mit dem Namen Maurin Knochenspalter finden.\n\nEr könnte eine Lösung für eines unser Probleme haben, denen wir hier gegenüberstehen.\n\nSprecht mit ihm und tut, was Ihr könnt, um ihm zu helfen.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;!\n\nEs ist gut, dass Ihr endlich hergekommen seid...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14339] = {title = "Lieferungsgerät", objective = "Maurin Knochenspalter will, dass Ihr 3 hohle Kodohörner von sterbenden Kodos sammelt.", description = "Wie es das Schicksal so will, gibt es etwas Besonders zu tun – etwas, von dem der Zirkel des Cenarius ebenso profitieren wird wie ich.\n\nWisst Ihr, <Klasse>, ich stehe unter dem Druck, ein besonderes... sagen wir 'Gebräu' herzustellen. Ich glaube, meine Arbeit ist vollbracht, aber es muss getestet werden, damit ich sicher sein kann.\n\nDie Zielobjekte dieses Tests sind die Naga, die diese Region vom Westen her bedrohen. Ihr Niedergang würde dem Zirkel sicherlich dienlich sein.\n\nAber zuerst bräuchte ich ein Lieferungsgerät. Die hohlen Hörner von sterbenden Kodos wären bestens dafür geeignet.", progress = "So schnell zurück, <Klasse>?", completion = "Jaja.\n\nDie sind bestens geeignet...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14340] = {title = "Schicker Fummel", objective = "Setzt Euren neuen Zaubererhut auf und dann sprecht mit dem Abbild von Erzmagier Xylem nordöstlich des Nördlichen Umschlagplatzes der Raketenbahn.", description = "Jeder muss wohl seine eigenen Erfahrungen machen, schätze ich.\n\nHier, nehmt meinen Zaubererhut. Ich zweifle nicht daran, dass er Euch als Lehrling akzeptiert, wenn ihr der Rolle entsprechend gekleidet seid... Vielleicht müsst ihr auch erst noch ein paar seiner Mätzchen mitmachen. Und mit Mätzchen meine ich unangenehme, fiese und tödliche Mätzchen.\n\nIhr solltet ein Abbild von Xylem auf der Spitze dieses Hügels im Nordosten antreffen.", progress = "Hallo.", completion = "Na, schaut Euch mal an. Seid Ihr nicht ein Wunder des modernen Magiertums! Ziemlich schick muss ich sagen.\n\nLehrlinge. Lehrlinge? Ich glaube, dass ich bereits ziemlich viele habe, aber ich nehme an, dass man nie ZU viele Lehrlinge haben kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14341] = {title = "Smeeds Harnische", objective = "Nataka im Geistwandlerposten will, dass Ihr Smeeds Harnische an Smeed ausliefert.\n\nBereitgestellter Gegenstand: \n", description = "Verzeiht, <Volk>.\n\nIch brauche ein wenig Hilfe. Ich habe gerade eine Bestellung für Harnische fertiggestellt, die sofort ausgeliefert werden muss.\n\nIch bin ein bisschen zu alt für diese Ausflüge, besonders wenn man bedenkt, wie gefährlich es in dieser Gegend in letzter Zeit geworden ist.\n\nWäret Ihr so nett?\n\nSie gehen an Smeed, einen Goblin, der gerade südöstlich von hier lebt.", progress = nil, completion = "Ahh, meine Harnische!\n\nHabt Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14342] = {title = "Höllische Übergriffe", objective = "Felgur Zweischneid will, dass Ihr 10 niedere Höllenbestien vernichtet.", description = "Die Dämonen sind unterwegs, <Volk>!\n\nWenn nichts getan wird, werden wir in ein paar Wochen überrannt. Ich bin gerade vom Zirkel der Mannoroc zurückgekehrt, wo es Höllenbestien vom Himmel regnet!\n\nWir müssen zumindest ein wenig Zeit gewinnen. Begebt Euch dorthin und macht weiter, wo ich aufgehört habe!", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;!\n\nDie Gefahr besteht weiter, aber ihr habt uns ein wenig Zeit verschafft.", rewards = "FinsterblutdolchDämonentötermaskeBollwerk mit KlauenspurenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14343] = {title = "Maurins Gebräu", objective = "Maurin will, dass Ihr Maurins Gebräu zu Karnum in Karnums Hain bringt.\n\nBereitgestellter Gegenstand: \n", description = "<Maurin versiegelt sorgfältig die hohlen Kodohörner, in denen sich sein Gebräu befindet.>\n\nBitte sehr, <Klasse>.\n\nBringt sie zu Karnum. Es ist seine Sache, wie er es sie gegen die Naga einsetzen will. \n\nIch werde zusehen, um die Wirkungskraft meiner Formel zu beobachten!", progress = nil, completion = "Ich verabscheue es, solch unnatürliche Maßnahmen zu ergreifen, aber ich befürchte, dass wir einfach keine andere Wahl haben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14344] = {title = "Jugkars Verderben", objective = "Ihr seid dazu auserkoren, den höllischen Kern der Macht zu verwenden, um an Jugkars Altar die Herrschaft über Lord Azrethoc zu übernehmen und mit dessen Kräften Jugkar Grimm'rod zu vernichten.", description = "Ihr erkennt hierin die Essenz eines beschworenen Dämons.\n\nGefährliche und unerklärliche Energien treten aus der Oberfläche und schlängeln sich wieder hinein.\n\nWährend Ihr es anstarrt, erfüllt eine Vision Euren Geist – ein Bild von Euch, wie Ihr dämonischen Dienern gebietet. Ein Anflug der Erregung überkommt Euch, als Ihr Euch vorstellt, über so eine Macht zu verfügen.\n\nIhr seht Euch um und fragt Euch, wie dieser Schatz gegen die dämonischen Feinde eingesetzt werden könnte...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14345] = {title = "Waschtag", objective = "Sprecht mit Sorata Feuerspinner am Nördlichen Umschlagplatz der Raketenbahn.", description = "Köstlich!\n\nAzy versucht immer, magische Artefakte in die Finger zu bekommen. Er sagt, er hat versucht, sich mit diesem Erzmagier anzufreunden. Xylem!\n\nXylem hat SEHR viele Lehrlinge. Er nimmt alle möglichen bei sich auf, verschleißt sie und lässt sie überall herumlaufen. Hohe Fluktuation.\n\nDer letzte ging letzte Nacht. Er ging in Richtung dieser großen Goblinturmkonstruktion tief im Westen. Vielleicht kann er Euch helfen, Xylem zu treffen? Vielleicht weiß Xylem, wo Azy ist?\n\nBenehmt Euch!", progress = nil, completion = "Seht, Kumpel, vor ein paar Wochen war ich an Eurer Stelle. Der große, mächtige Erzmagier nimmt tatsächlich Lehrlinge auf! Wer würde so eine Gelegenheit verpassen wollen?!\n\nManchmal sind die Dinge einfach zu schön, um wahr zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14346] = {title = "Säubert unseren Riss", objective = "Karnum Marschenwirker will, dass Ihr Maurins Gebräu verwendet, um 10 Eindringlinge der Zackenkämme, 10 Sirenen der Zackenkämme und 3 Meeresriesen zu töten.", description = "Wie Ihr sicher wisst, <Name>, sind die Naga weiterhin eine ernsthafte Bedrohung für dieses Gebiet. Die Zeit ist gekommen, dass wir sie zurück ins Meer treiben!\n\nWenn Ihr bereit seid, wird Euch Grimmfeder zur Spalte bringen, wo sie einen brutalen Angriff vorbereiten. Sobald Ihr dort seid, verwendet Maurins Gebräu, um ihnen eine Lektion zu erteilen, die sie nicht so schnell vergessen sollen.", progress = nil, completion = "Eure Taten beindrucken mich immer mehr, &lt;Name&gt;.\n\nBitte nehmt dieses Geschenk im Namen des Zirkels des Cenarius entgegen.", rewards = "Gamaschen der windigen SchluchtAbgewetzter HandschutzHandgelenksschützer des MarschenwirkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14347] = {title = "Bleibt standhaft", objective = "Tötet 10 Eindringlinge der Verlassenen.", description = "<Name>! Ich bin mir nicht sicher, ob Ihr lebendig oder tot seid… Mensch oder Worgen…\n\nIch bin mir nicht einmal sicher, ob ich wache oder träume. Aber EINER Sache bin ich sicher…\n\nWir werden einen ganzen Haufen dieser mutterlosen Verlassenen töten.", progress = nil, completion = "Ja, &lt;Name&gt;! Genau wie in alten Zeiten…\n\nIch muss mich sehr zurückhalten, um Euch nicht zu erschießen, aber Krennan hat uns alles erklärt.", rewards = "Armschienen des AbweisersGürtelbund des Gilnearischen SoldatenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14348] = {title = "Ihr schafft sie nicht alleine", objective = "Jagt mit den Schwarzpulverfässern 4 entsetzliche Monstrositäten in die Luft.", description = "Schaut her, <Name>. Die besonders großen, massigen, auch Monstrositäten genannt, sind nicht so leicht zu bezwingen. Versucht also nicht, alleine mit ihnen fertigzuwerden.\n\nAber ich habe eine Idee, die so verrückt ist, dass sie tatsächlich funktionieren könnte. Sie könnte allerdings auch Euren Tod bedeuten, wenn wir nicht vorsichtig genug sind.\n\nHinter den Schuppen und in der Nähe der Windmühlen liegen einige Fässer mit Sprengpulver. Schnappt sie Euch und werft sie den Monstrositäten direkt an den Kopf. Den Rest erledige ich mit meiner treuen alten Donnerbüchse.", progress = nil, completion = "Ihr und ich, &lt;Name&gt;. Wir sind ein tolles Team…\n\nEs ist schön, dass Ihr wieder da seid.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErfrischendes QuellwasserGewürzbrot\n\nIhr bekommt außerdem:\n\nFlasche Dalaran Noir"}
MultiLanguageQuestData['de'][14349] = {title = "Der Befehl", objective = "Reist nach Unterstadt und sprecht mit Fürstin Sylvanas Windläufer.", description = "Der Befehl ist gekommen, <Klasse>. Sylvanas selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission nach Unterstadt schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort nach Unterstadt und erstattet der Dunklen Fürstin Bericht. Macht mir keine Schande, <Klasse>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14350] = {title = "Der Purpurrote Kurier", objective = "Kehrt in die Östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des Obersten Kreuzfahrers.\n\nBringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen.", description = "Wir können die Oberbefehlshaber des Scharlachroten Kreuzzugs nicht direkt angreifen; sie verfügen über eine zu gute Verteidigung. Aber bekanntlich führen viele Wege zum Ziel. Ohne ihre Hauptstreitkraft sind sie hilflos.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale nach Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, <Volk>! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAbenteurerbedarf von Nordend"}
MultiLanguageQuestData['de'][14351] = {title = "Kampf um das Hügelland", objective = "Bringt Darthalias versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt.", description = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht des Hügellands gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.\n\nBringt die versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt. Geht erhobenen Hauptes, <Klasse>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "TotenschädelschildRunenverzierte DunkelklingeHeilige BegräbnisbeinkleiderIhr bekommt:\n\nBand von Unterstadt"}
MultiLanguageQuestData['de'][14352] = {title = "Eine unheilige Allianz", objective = "Bringt die kleine Rolle zu Bragor Blutfaust nach Unterstadt.", description = "Mylady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf Weiteres abseits der Hügel der Klingenhauer aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", progress = "Was wollt Ihr, <Name>? Es sollte besser wichtig sein.", completion = "Ich habe die Insignien auf dieser Rolle schon mal während meiner Zeit in Nordend gesehen. Ihr sagt, Ihr habt dies bei der Greisin gefunden, die die Schweine im Kral der Klingenhauer anführt?\n\nVerdammt will ich sein, wenn ich es der Geißel erlauben sollte, sich hier breitzumachen. Derjenige, der dies schrieb - dieser Malcin - ist natürlich einer der Diener des Lichkönigs und das macht ihn zu einem Ziel. Eurem Ziel.\n\nSie werden Kalimdor nicht bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14353] = {title = "Eine unheilige Allianz", objective = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.", description = "Angeblich hält sich dieser Malcin außerhalb der Hügel der Klingenhauer auf. Keine Frage - er muss sterben.\n\nMeine Kontakte in Orgrimmar erzählen mir, dass ihre Späher dort unten Anzeichen der Seuche gefunden haben. Die Stacheleber weisen auch Anzeichen einer Verseuchung auf und sie sind um einiges stärker. Was auch immer die Geißel dort unten unternimmt, muss ein Ende haben. Jetzt sofort.\n\nFindet diesen Malcin und schaltet ihn aus. Meldet Euch wieder bei mir, sobald er tot ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "SchädelbrecherNagelspeierZelotenrobeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14354] = {title = "Elunes Gaben", objective = "Besucht Elunes Relikte in Sargeron.", description = "Einfach unerträglich!\n\nAusgerechnet Satyrn entweihen unser geheiligtes Land...\n\nIhre Tage sind gezählt, <Volk>. Das lasst Euch gesagt sein. Sobald wir wissen, wie viele es sind, werde ich ein Kommando anführen, welches das Land von diesen niederträchtigen Kreaturen befreit.\n\nAber bis dahin könntet Ihr vielleicht meiner Seele zu ein wenig mehr Frieden verhelfen?\n\nReist von hier nach Osten zu Sargeron und durchsucht die Ruinen. Findet die Relikte von Elune und versichert Euch, dass sie in gutem Zustand sind.\n\nIch werde Euch für diesen Dienst großzügig belohnen.", progress = nil, completion = "Die Relikte sind unbeschädigt! Das ist wirklich erfreulich.\n\nIhr habt meine innere Ruhe wieder hergestellt, &lt;Volk&gt;. Bitte nehmt dies als mein Geschenk an Euch.", rewards = "Handschuhe des HegensSchulterschutz der ProtektionAuf Euch wartet eine dieser Belohnungen:\n\nHalsreif der ErneuerungSignet des Dämonentöters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14355] = {title = "In das Scharlachrote Kloster", objective = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Bragor Blutfaust in Unterstadt.", description = "Eine meiner Aufgaben, während ich hier stationiert bin, ist es, den Verlassenen dabei zu helfen, ihre Grenzen zu überwachen – und das ist exakt das, was Ihr, <Klasse>, für mich erledigen werdet.\n\nIch mag am Leben sein, doch ist der Scharlachrote Kreuzzug bereit, meine Leute genauso schnell niederzumähen wie einen der Untoten. Sie sind ein Problem hier, ein großes sogar, und Ihr werdet etwas dagegen unternehmen.\n\nGeht zum Kloster und erschlagt Hochinquisitorin Weißsträhne und ihre Offiziere.", progress = nil, completion = "Ich bin mir sicher, dass Sylvanas erfreut sein wird, dass dieses Problem gelöst wurde, &lt;Name&gt;. Der Auftrag, den ich Euch erteilte, war kein einfacher, und doch seid Ihr hier, siegreich. Das verlangt Respekt und was Ihr getan habt, wird nicht vergessen werden.", rewards = "Schwert des OmensAuf Euch wartet eine dieser Belohnungen:\n\nStock des ProphetenDrachenbluthalskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14356] = {title = "Die Macht zu Zerstören...", objective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Bragor Blutfaust nach Unterstadt.", description = "Zugehört, <Klasse>.\n\nIhr mögt vielleicht nichts davon wissen, aber Orgrimmar hat ein Problem. Tief im Flammenschlund treibt eine Sekte des Schattenrats, die sich 'Die Sengende Klinge' nennt, ihr Unwesen. Es sind hauptsächlich Orcs und ich kann vertrauliche Informationen nicht in die Hände der Grunzer dort legen. Hier kommt Ihr ins Spiel.\n\nSie sollten zwei Bücher in ihrem Besitz haben. Ich möchte sie weder der Sengenden Klinge noch den Verlassenen überlassen. Bringt sie direkt zu mir.", progress = "Habt Ihr die Bücher in Sicherheit bringen können? Sie dürfen nicht in die falschen Hände gelangen.", completion = "Gut, &lt;Klasse&gt;, das habt Ihr gut gemacht. Ich werde sie sicher verwahren und vor neugierigen Blicken verbergen; das Letzte, was wir brauchen, ist ein wiedererstarkter Schattenrat.\n\nMeldet Euch in der Zukunft wieder bei mir; ganz offensichtlich gibt es hier immer etwas zu tun und ich könnte ein Paar fähige Hände bestimmt gebrauchen.", rewards = "Garstige BeinkleiderGamaschen des SumpfgräbersGargoylegamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14357] = {title = "Zu den Waffen!", objective = "Besorgt 20 Satyrsäbel aus dem Waffenregal und von den Satyrn aus der Gegend.", description = "Elunes Dienstmaid! Sie ist noch prächtiger als es in den Geschichten erzählt wird.\n\nDie Legenden, die dieses Relikt umgeben, kommen Euch in den Sinn, als Ihr Euch nähert:\n\nIn uralten Zeiten nach dem Krieg wurden die Waffen der Feinde dem Becken dargeboten im Austausch für eine Art göttliche Gabe.\n\nAls Ihr über das Ritual nachdenkt, bemerkt Ihr das Funkeln von Stahl in einem nahegelegenen Waffenregal...", progress = "Die Statue steht dort erwartungsvoll.", completion = "Als Ihr das Ritual abgeschlossen habt, empfangt Ihr eine göttliche Gabe.\n\nIhr könnt Euch des Gefühls nicht erwehren, dass Euch eine große Ehre zuteil geworden ist, als Ihr den Segen Elunes erhaltet.", rewards = "Sandalen des RitualsVergoldeter KürassSchwerer GurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14358] = {title = "Zehn Pfund Fleisch", objective = "Beschafft 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron.", description = "Alten Legenden zufolge wurde dieses uralte Kohlenbecken hier aufgestellt, um Opferrituale durchzuführen.\n\nSoweit Ihr Euch erinnern könnt, besagen die Geschichten, dass derjenige gesegnet wird, der das Fleisch von Elunes Feinden auf die brennenden Glutspäne im Kohlenbecken legt.\n\nIhr seht Euch um und beschließt, dass die Satyrn, welche die Region derzeit beherrschen, sicherlich als Feinde bezeichnet werden könnten.", progress = nil, completion = "Das göttliche Becken versieht Euch gnädig mit einem Segen.", rewards = "Ihr erlernt:\n\nGöttliche Stärkung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14359] = {title = "Segen von oben", objective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", description = "Ihr spürte eine tiefe Verbindung zu längst vergangenen Zeiten, nachdem Ihr den uralten Segen von diesem Relikt empfangen habt.\n\nIhr seid entschlossen, so viel Nutzen wie möglich aus dieser göttlichen Gabe zu ziehen.", progress = "Das Becken erwartet still eine Opfergabe.", completion = "Das göttliche Becken versieht Euch gnädig mit einem Segen.", rewards = "Ihr erlernt:\n\nGöttliche Stärkung"}
MultiLanguageQuestData['de'][14360] = {title = "Nichts, was ein paar Melonen nicht richten können", objective = "Ihr müsst 8 Melonenfrüchte sammeln und ihren Saft in den Kelch von Elune in Sargeron pressen.", description = "Die Markierungen der Ruinen von Sargeron in Kombination mit den Informationen aus Furiens Text lassen lassen in einer Sache keine Zweifel:\n\nMit dem Brunnen im Heiligtum von Elune hat es etwas ganz Besonderes auf sich.\n\nEs scheint, dass er einem besondere Kräfte verleiht, wenn man sein Gesicht in seinem Wasser wäscht. Als erstes muss es im uralten Brunnen natürlich etwas geben, mit dem man sich waschen kann.\n\nWährend Ihr über dieses Problem nachdenkt, bemerkt Ihr eine Melone an den Wurzeln eines Baumes...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14361] = {title = "Seelenfrieden", objective = "Tötet Kohor", description = "Unser Lager hat die Aufgabe, mögliche Widersacher zu beobachten. Sobald die Allianz ihren Desolace-Feldzug startet, wird unsere Arbeit hier sicherstellen, dass es keine Überraschungen geben wird.\n\nKürzlich wurde einer unserer Späher gefangen genommen und von der Brennenden Klinge in ihrem Stützpunkt im Westen geopfert. Seitdem werden wir von einem Schuft der Brennenden Klinge bedroht und gepiesackt. Sein Name ist Kohor.\n\nIhre Tage sind gezählt, aber ich werde denjenigen großzügig belohnen, der ihn jetzt zum Schweigen bringt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14362] = {title = "Ein Satz heiße Ohren", objective = "Sammelt 25 Ohren von Mitgliedern der Brennenden Klinge.", description = "Hauptmann Pentigast hat kein Geheimnis aus seiner Verachtung gegenüber der Brennenden Klinge in Festung Donneraxt gemacht.\n\nSicherlich würde ein Beweis ihres Dahinscheidens für ihn von großem Wert sein.", progress = "Was habt Ihr da, <Klasse>?", completion = "Ohren der Brennenden Klinge?\n\n&lt;Hauptmann Pentigast lächelt.&gt;\n\nGute Arbeit, &lt;Klasse&gt;. Dies ist nur eine Vorahnung von dem, was aus dem gesamten, ekelhaften Kult wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14363] = {title = "Ihr erkennt es, wenn Ihr es seht", objective = "Findet das uralte Beschwörungsritual in der Festung Donneraxt.", description = "Mit seinen letzten Atemzügen erwähnte Kohor die Beschwörung eines Dämons, der das gesamte Gebiet bedrohen könnte.\n\nVielleicht war das ein Täuschungsversuch, aber das Risiko kann nicht eingegangen werden.\n\nDies kann nicht bis zum Einfall der Allianz in Desolace warten. Ihr müsst die Festung Donneraxt nach Hinweisen durchsuchen und dieser möglichen Gefahr ein Ende setzen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14364] = {title = "Die Köpfe zusammenstecken", objective = "Sammelt 100 gebleichte Schädel aus der Festung Donneraxt, stapelt sie am Beschwörungszirkel der Brennenden Klinge auf und tötet dann Nazargen.", description = "Es stimmt also...\n\nDas Pergament, das Ihr in der Festung Donneraxt gefunden habt, beschreibt ein mächtiges Beschwörungsritual. Eines das stärker ist als alle anderen, von denen wir wissen, dass die Brennende Klinge sie besitzt.\n\nDieses Ritual muss selbstverständlich unterbrochen werden, koste es, was es wolle!\n\nWenn diese Dämonen vorzeitig beschworen würden, könnte die Krise abgewendet werden.", progress = nil, completion = "Ihr habt eine schlimme Krise abwenden können, &lt;Klasse&gt;.\n\nWenn diese Beschwörung noch ein wenig länger hinausgezögert worden wäre, wäre der Dämon viel zu mächtig für unsere kleine Streitmacht geworden.\n\nBitte nehmt dieses Geschenk zum Dank für Eure Dienste an.", rewards = "Schädelversengter UmhangAuf Euch wartet eine dieser Belohnungen:\n\nErdungshalsreifRing der machtvollen Unterbrechung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14365] = {title = "Ethel Rethor", objective = "Korporal Melkins will, dass Ihr mit Korrah in Ethel Rethor sprecht.", description = "Wir haben kürzlich ein Hilfegesuch von einer Forscherin des Zirkels des Cenarius erhalten.\n\nZurzeit können wir niemanden entbehren. Deshalb bitte ich Euch, ihr in unserem Namen einen Besuch abzustatten.\n\nKorrah befindet sich in der Nähe der Ruinen des Turms von Ethel Rethor an der Küste im Westen.", progress = nil, completion = "Es ist gut, dass Ihr gekommen seid.\n\nHier lauert eine große Gefahr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14366] = {title = "Durchhalten", objective = "Sprecht mit Gwen Armstead in Dämmerhafen.", description = "Ab hier schaffen wir es alleine, <Name>. Schaut Ihr nach Bürgermeisterin Armstead.\n\nDies hier ist nur ein kleiner Teil der Streitkräfte der Verlassenen. Wenn wir nicht schnell handeln, werden wir bald noch größeren Problemen gegenüberstehen.\n\nSchaut, was Ihr tun könnt, um Euch der Armee der Verlassenen an ihrem Anlegeplatz zu stellen.", progress = nil, completion = "Gute Nachrichten, &lt;Name&gt;. Ich habe die verbleibenden Milizen an die Küste geschickt, damit sie der Streitmacht der Verlassenen direkt gegenübertreten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14367] = {title = "Allens Sturmkeller", objective = "Sprecht mit Lord Godfrey im Sturmkeller von Allens Bauernhof in Gilneas.", description = "Lord Godfrey führt den Angriff auf die Verlassenen in der Nähe ihres Anlegeplatzes an. Schaut, wie Ihr ihm dabei helfen könnt, die Verlassenen zurückzuhalten.\n\nIch habe gehört, dass Godfrey den Sturmkeller in Allens Bauernhof weit im Westen unter sein Kommando gebracht hat. Sucht ihn dort.", progress = nil, completion = "Die Verlassenen sind hier und es sind viele, &lt;Name&gt;. Wir haben kaum genug Männer, um sie zurückzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14368] = {title = "Rettet die Kinder!", objective = "Rettet Cynthia, Ashley und James in Hammonds Bauernhof.", description = "Die Soldaten lassen mich nicht aus dem Keller, aber meine Kinder sind noch auf dem Bauernhof! Bitte, Ihr müsst sie finden.\n\nDie Verlassenen haben kein Mitgefühl mit den Unschuldigen. Meine Kinder sind in großer Gefahr!\n\nSie heißen Cynthia, Ashley und James. Wenn Ihr sie findet, bringt sie hierher. Ich stünde auf ewig in Eurer Schuld.", progress = "Ich… Ich weiß nicht, ob ich ohne sie weiterleben kann.", completion = "Meine Kinder sind in Sicherheit! Ihr habt etwas Wundervolles getan, &lt;Name&gt;. Ich weiß nicht, wie ich Euch danken soll.", rewards = "Gamaschen des PflegersHandschuhe des SchutzesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14369] = {title = "Entfesselt die Bestie", objective = "Tötet 8 Fußsoldaten der Verlassenen oder Seeleute der Verlassenen.", description = "Ich werde Euch nicht belügen, <Name>. Der Gedanke, einen Worgen in unseren Reihen zu haben, gefällt mir ganz und gar nicht.\n\nWer weiß schon, wie lange Krennans Gebräu anhält und wann Ihr versuchen werdet, einem von uns den Kopf abzubeißen?\n\nAber bis dahin können wir uns Eure Wildheit zunutze machen.\n\nGeht hinaus auf das Schlachtfeld und tötet so viele dieser Verlassenen, wie Ihr könnt, und zwar so brutal, wie Ihr könnt.\n\nWir werden ihnen schon beibringen, die Worgen zu fürchten, <Name>.", progress = nil, completion = "Nicht schlecht, &lt;Name&gt;. Gut, dass Ihr auf unserer Seite steht.", rewards = "Godfreys DolchVergoldete GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14370] = {title = "Rätselhafter Azsharit", objective = "Sammelt 5 Azsharitproben an den nahegelegenen Klippen.", description = "Azsharit! Aus dieser rätselhaften Kristallsubstanz wurden Waffen mit teuflischer Macht geschmiedet, aber wir haben entdeckt, dass sie in unseren Händen in der Lage ist, gewaltige Kraftmengen zu bündeln. Das könnte die größte Entdeckung der Goblins seit dem Kaja'mit sein.\n\nAber was ist es? Wo kommt es her? Warum gibt es das nur hier? Die Wissenschaft verlangt nach einer Antwort! Ich brauche weitere Proben für meine Forschungen. Sucht nach Azsharitvorkommen an den nahegelegenen Klippen.", progress = "Habt Ihr weitere Proben gesammelt? Die gedankenlosen Abenteurer sammeln dieses Zeug schon seit Jahren, ohne zu wissen, wie wertvoll es ist!", completion = "Ah, hervorragend. Einige der Proben sehen frisch aus. Ich kann mich jetzt bis über beide Ohren in dem Zeug vergraben, um dieses Rätsel zu lösen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14371] = {title = "Ein Riesenimbiss", objective = "Sammelt 8 verstümmelte Nebelschwingenkadaver von Nebelschwingenkliffbewohnern.", description = "Während Ihr an den Klippen herumklettert, könnt Ihr mir vielleicht bei einer weiteren Untersuchung helfen. Die Riesen, die an diesen Klippen entlangwandern, sind hier, seit die Berge entstanden. Vielleicht wissen sie, wo der Azsharit herkommt? Es liegt sehr in unserem Interesse, uns mit diesen Riesen gut zu stellen und es herauszufinden.\n\nSammelt ein gigantisches Mahl für mich - als Friedensangebot! Tötet die Nebelschwingenkliffbewohner, die unsere Forschungen so stark behindern, und sammelt ihre Kadaver für mich ein.", progress = "Ich hätte Euch vermutlich vorwarnen sollen, dass diese Nebelschwingenschimären Blitze schleudern können.", completion = "Puh! Was für ein Gestank! Nun, hoffentlich riecht der Kadaverhaufen für die Riesen appetitlicher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14372] = {title = "Thargads Lager", objective = "Karnum Marschenwirker will, dass Ihr mit Thargad sprecht.", description = "Es ist schön, zu sehen, dass Ihr noch atmet, <Klasse>. Mir ist zu Ohren gekommen, dass die Aktivitäten der Dämonen im Süden zunehmen.\n\nDort gibt es ein Lager im Grenzgebiet, das Gefahr läuft, durch die Bewegungen der Dämonen Richtung Norden abgeschnitten zu werden.\n\nVielleicht könnt Ihr ihnen ein wenig zur Hand gehen?\n\nIch weiß, dass der Anführer des Lagers Thargad heißt. Er wird Euch sicher kluge Anweisungen geben können.\n\nHabt Dank, <Freund/Freundin>. Gehabt Euch wohl.", progress = nil, completion = "Dämonen?\n\nIch kann Euch viel über Dämonen erzählen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14373] = {title = "Höllische Übergriffe", objective = "Tötet 10 niedere Höllenbestien.", description = "Hört mal gut zu. Und seht her.\n\n<Thargad zeigt in den Osten.>\n\nIhr seht die großen, grünen, glühenden Feuerbälle vom Himmel regnen?\n\nDas ist ein ganzer Haufen dieser hässlichen Dämonen, welche die Länder ungehindert durchstreifen. Nun, praktisch ungehindert... Ich habe sie ein wenig auf Trab gehalten und ihnen einen Denkzettel verpasst.\n\nWie wär's, wenn Ihr mal bei ihnen vorbeischaut und dort weitermacht, wo ich aufgehört habe?", progress = nil, completion = "Gut, Jungchen!\n\nZögert nicht, noch ein paar weitere zusätzlich aus den Socken zu hauen.", rewards = "FinsterblutdolchDämonentötermaskeBollwerk mit KlauenspurenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14374] = {title = "Portale der Legion", objective = "Verbannt 6 Portale beim Zirkel des Mannoroc.", description = "Hier ist sie - die Hand von Iruxos.\n\nHab sie mir selbst von einem der Anführer der Brennenden Klinge geholt.\n\nMächtiges Ding! Wisst Ihr, man benutzt sie mit Dämonenportalen und sie verschwinden einfach! Unheimliche Magie, aber wir leben in schweren Zeiten...\n\nWenn die Dämonen weiter in diesen Zahlen hier auftauchen, wird mein Lager überlaufen, bevor ich mich wehren kann.\n\nDa habt Ihr sie. Und jetzt beeilt Euch.", progress = nil, completion = "Ja, das wird uns etwas Zeit verschaffen, &lt;Klasse&gt;.\n\nIch danke Euch.", rewards = "BindungsstabArmschiene der PortaleSchiftung der VersiegelungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14375] = {title = "Die letzte Hoffnung auf Menschlichkeit", objective = "Ich muss Euch irgendwie durchkriegen, <Name>. Diese Dosis ist stark genug, um ein Pferd zu töten.\n\nAber ich kenne Euch. Ich weiß, aus welchem Holz Ihr geschnitzt seid. Ihr werdet es schon schaffen.\n\nVertraut mir. Ich weiß genau, was Ihr durchmacht.\n\nJetzt trinkt leer und schließt Eure Augen.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Worgen Intro Completion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14376] = {title = "Jugkars Verderben", objective = "Ihr seid dazu auserkoren, den höllischen Kraftkern zu verwenden, um an Jugkars Altar die Herrschaft über Lord Azrethoc zu übernehmen und mit dessen Kräften Jugkar Grimm'rod zu vernichten.", description = "Ihr erkennt hierin die Essenz eines beschworenen Dämons.\n\nGefährliche und unerklärliche Energien treten aus der Oberfläche und schlängeln sich wieder hinein.\n\nWährend Ihr es anstarrt, erfüllt eine Vision Euren Geist – ein Bild von Euch, wie Ihr dämonischen Dienern gebietet. Ein Anflug der Erregung überkommt Euch, als Ihr Euch vorstellt, über so eine Macht zu verfügen.\n\nIhr seht Euch um und fragt Euch, wie dieser Schatz gegen die dämonischen Feinde eingesetzt werden könnte...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14377] = {title = "Ein Freund der Riesen", objective = "Sprecht mit Gormungan außerhalb der Südlichen Endhaltestelle der Raketenbahn und entlockt ihm das Geheimnis des Azsharits.", description = "Eine oberflächliche Untersuchung des Azsharits, das Ihr mir gebracht habt, lässt erkennen, dass es weder biologischen Ursprungs ist noch sich auf natürliche Weise gebildet hat. Es gibt eine weitere Kreatur in Azshara mit ähnlichen Eigenschaften: die Klippenriesen, die über diese Klippen stapfen.\n\nEiner der Riesen scheint willens zu sein, uns bei unseren Forschungen zu unterstützen. Bringt das Fleisch, dass Ihr gesammelt habt, zu Gormungan, dem Riesen, der genau westlich von hier steht. Freundet Euch mit ihm an, dann fühlt ihm auf den Zahn. Findet heraus, ob er etwas über das Geheimnis des Azsharits weiß.", progress = nil, completion = "Sprecht langsamer. Was habt Ihr zu sagen? Höre ich recht? Das Azsharit bildet sich dort, wo die Riesen... Ohje. Ekelhaft!! Erzählen wir das besser nicht Dr. Wurfhammer. Er hat sein Leben diesem Zeug gewidmet.\n\nNun, zumindest wissen wir jetzt, wo das Azsharit herkommt und warum es so selten ist. Wir müssen herausfinden, wie wir die... 'Produktion' beschleunigen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14378] = {title = "Die Jagd nach Brendol", objective = "Beschafft Brendols Beutel.", description = "Ich bin zu beschäftigt, um Artefakte oder irgendetwas anderes zu sammeln, aber es gibt eine kleine Sache hier, die ich gerne klären würde.\n\nEin Apotheker der Verlassenen stöbert schon seit einer Weile in der Gegend herum. Normalerweise würde ich ihn ignorieren, aber er hat sich schon dreimal in mein Lager geschlichen und meine Vorräte geplündert... Was zu viel ist, ist zu viel!\n\nFindet den Dieb und bringt mir das, was von meinen Sachen übrig ist!", progress = "Nun, <Klasse>? Habt Ihr den Idioten gefunden?", completion = "Der Gerechtigkeit wurde genüge getan!\n\nJetzt schauen wir uns an, was von meinen Sachen übrig ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14379] = {title = "Hummerstroks!", objective = "Beschafft 7 zarte Hummerstrokschwänze.", description = "Thargad jagt praktisch ununterbrochen nach den uralten Relikten der Titanen. Er ist so darin vertieft, dass er vermutlich vergessen würde zu essen, wenn ich ihn nicht daran erinnern würde!\n\nWo wir vom Essen sprechen: Ich würde ihm gerne etwas Besonderes zubereiten. Vielleicht könnt Ihr mir dabei helfen?\n\nEntlang der Küste im Westen krabbeln Hummerstroks herum. Einen Kampf gegen sie könnte ich niemals bestehen, aber ich könnte ein fantastisches Mahl herrichten, wenn Ihr mir ein paar ihrer Schwänze brächtet.", progress = "Habt Ihr die Hummerstrokschwänze mitgebracht, <Volk>?", completion = "Ohhh, damit wird es wunderbar!\n\nThargad wird ja so überrascht sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14380] = {title = "Eine bedeutsame Entdeckung", objective = "Bringt das mysteriöse Gebräu zu Karnum auf Karnums Lichtung.\n\nBereitgestellter Gegenstand: \n", description = "<Thargad durchsucht den Ranzen und zieht ein merkwürdiges Objekt heraus.>\n\nAha, das ist seltsam... Das ist ein hohles Kodohorn mit einer Art Trank darin.\n\n<Thargad schnuppert an dem Trank.>\n\nIIH! Eindeutig kein Gesundheitselixier. Dies dient nur einem Zwecke: dem Töten.\n\nWie wäre es, wenn wir es zu Karnum bringen und schauen, ob er etwas damit anfangen kann...", progress = nil, completion = "&lt;Karnum untersucht das Gebräu.&gt;\n\nJa, &lt;Klasse&gt;. Ich weiß nicht nur, was das ist. Ich weiß auch, was Ihr damit anstellen solltet...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14381] = {title = "Säubert unseren Riss", objective = "Verwendet Maurins Gebräu, um 10 Eindringlinge der Zackenkämme, 10 Sirenen der Zackenkämme und 3 Meeresriesen zu töten.", description = "Ich erkenne diese üble Erfindung. Es ist eine schreckliche Krankheit, die beinahe sofort tötet – und zwar auf brutalste Weise. So sehr ich es auch verabscheue, so ein Mittel einzusetzen, ich fürchte, wir haben keine Wahl.\n\nWie Ihr sicher wisst, sind die Naga weiterhin eine ernsthafte Bedrohung für dieses Gebiet. Die Zeit ist gekommen, sie zurück ins Meer zu treiben!\n\nWenn Ihr bereit seid, wird Euch Grimmfeder zum Riss bringen, wo sie einen brutalen Angriff vorbereiten.\n\nSetzt das Gebräu gegen die Naga und ihren Verbündeten ein, um Desolace wieder sicher zu machen!", progress = nil, completion = "Eure Taten beindrucken mich immer mehr, &lt;Name&gt;.\n\nBitte nehmt dieses Geschenk im Namen des Zirkels des Cenarius entgegen.", rewards = "Gamaschen der windigen SchluchtAbgewetzter HandschutzHandgelenksschützer des MarschenwirkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14382] = {title = "Nimm mich mit, Kapitän, auf die Reise", objective = "Benutzt die Katapulte der Verlassenen, um auf die Schiffe zu gelangen und tötet Kapitän Morris und Kapitän Anson.", description = "Die Katapulte der Verlassenen machen uns ganz schön zu schaffen, <Name>. Und selbst wenn wir ihrer Herr würden, stehen da noch zwei Schiffe mit zwei Reihen Kanonen.\n\nIch habe jedoch einen Plan, mit dem wir zwei Fliegen mit einer Klappe schlagen. Ihr seid bei diesem Plan die Klappe.\n\nBeseitigt die Maschinisten an den Katapulten. Nutzt danach die Katapulte, um Euch selbst an Bord der Schiffe der Verlassenen zu katapultieren.\n\nWenn Ihr nicht gerade komplett daneben zielt, solltet Ihr sicher landen. Sobald Ihr an Bord seid, geht unter Deck und erledigt den Kapitän jedes Schiffes. Viel Erfolg, <Klasse>.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr seid vielleicht eine blutrünstige Bestie, aber Ihr seid unsere Bestie.", rewards = "Handschuhe der zwei Fliegen\"Fliegende\" WorgenrobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14383] = {title = "Die tobenden Tüftler der Verfallenen Gegenden", objective = "Tötet Bingham Federdings in den Verfallenen Gegenden und dazu 4 Netzgewehrgnome und 6 Britzelgnome.", description = "Halunken! Ungläubige! Seit ich meine Arbeit hier in Azshara aufgenommen habe, haben die Federdings meine Experimente behindert und meine Forschungen sabotiert. Und jetzt ist ihnen eine Bande von mittelmäßigen, zweitklassigen Tüftlern zu Hilfe geeilt! Ich habe mich dringenden Geschäften zuzuwenden. Kümmert Euch darum, dass diese Gnome für immer erledigt werden.\n\nBegebt Euch in die Verfallenen Gegenden an der Küste südlich meines Geheimlabors und lasst ihre überdimensionierten Köpfe für mich rollen.", progress = nil, completion = "Oh - fabelhaft. Erzählt mir mehr. Und dieser altkluge junge Federdings? Auch tot? Ah, wunderbar. Meine Arbeit hier ist sehr wichtig, aber manchmal vermisse ich das Gemetzel, wenn ich meine Feinde auf einem persönlicheren Level demontiere. Hier, vielleicht kann Euch etwas von meiner ausgemusterten Ausrüstung nützlich sein.", rewards = "Hobarts ErsatzradkappeAuf Euch wartet eine dieser Belohnungen:\n\nSprungfederdingsbums\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14384] = {title = "Umgeleitet!", objective = "Offizierin Jankie möchte, dass Ihr auf ihrem Reittier zur Nijelspitze fliegt und dort mit Korporal Melkins sprecht.", description = "Halt!\n\nIm Namen der Wache der Nijelspitze - ich habe Befehl, dafür zu sorgen, dass alle tauglichen Verbündeten sich bei Korporal Melkins melden.\n\nIch bin nicht befugt, weitere Informationen zu geben.\n\nIch kann allerdings Transport anbieten. Ihr dürft mein Reittier benutzen. Es wird Euch direkt dort absetzen.\n\nWegtreten.", progress = nil, completion = "Willkommen auf der Nijelspitze, &lt;Volk&gt;. \n\nAlso, dann wollen wir Euch mal über unsere Situation hier aufklären.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMelkins' Dummy\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14385] = {title = "Azsharitexperiment Nummer Eins", objective = "Besorgt Euch ein Abführmittel in Riesengröße von dem Gnomenturm in den Verfallenen Gegenden. Versucht, das Abführmittel dem Riesen Gormungan zu verabreichen.", description = "Nun, ich kann mir einen todsicheren Weg vorstellen, wie man einen Riesen dazu bringt, zur Toilette zu rennen, aber das wird Euch nicht gefallen. Wir brauchen einfach ein ... gewaltiges ... Abführmittel. Oh hey! Ihr werdet es nicht glauben, aber die Gnome haben tatsächlich so etwas. Das kann kein Zufall sein. Ich frage mich, was die da drüben wohl durchdrücken wollen.\n\nUnser Geheimdienst berichtet, dass das Abführmittel bei Federdings' Turm unten an der Küste südlich des Geheimlabors abgegeben wurde. Holt das Abführmittel und verabreicht es Gormungan!", progress = "Sobald Ihr das Abführmittel habt, versucht, es Gormungan zu verabreichen. Und gebt ihm vielleicht eine Zeitschrift oder so etwas. Tut es für die Wissenschaft!", completion = "Also ist nichts dabei rausgekommen? Im wahrsten Sinne des Wortes? Nun, Wurfhammer wird ein Nein nicht akzeptieren. Wir müssen etwas Anderes ausprobieren.\n\nVielleicht lasse ich meine Praktikanten dieses Abführmittel in das Lager der Nachtelfen schmuggeln. Das wäre doch bestimmt sehr lustig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14386] = {title = "Der Leithund", objective = "Benutzt die Mastiffpfeife, um Hilfe dabei zu bekommen, Dunkelläuferin Thyala zu töten.", description = "Ausgezeichnete Arbeit bisher, <Name>. Unsere Späher haben die Anführerin des Bodenangriffs der Verlassenen ermittelt.\n\nEine von Sylvanas persönlich ausgewählte Dunkelläuferin kontrolliert das Schlachtgeschehen vom Haus der Waldens bei der Küste aus. Nehmt diese Pfeife mit und benutzt sie, wenn Ihr in ihrer Nähe seid.\n\nIch befehle meinen Männern dann, unsere Angriffsmastiffs loszulassen, um sie zur Strecke zu bringen. Seid vorsichtig, <Name>. Ihr solltet ihr nicht allein gegenübertreten.", progress = "Ist es schon vollbracht, <Name>?", completion = "Ihr habt es geschafft, &lt;Name&gt;. Das sollte ihnen den Wind aus den Segeln nehmen.", rewards = "Weste des DunkelläufersTreter des AnführersDer folgende Zauber wird auf euch gewirkt:\n\nForcecast Cataclysm I\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14387] = {title = "Beschaffenheit des Geländes", objective = "Hauptmann Pentigast möchte, dass Ihr mit Vahlarriel auf der Nijelspitze sprecht.", description = "Ja, ja. Willkommen in Desolace, <Volk>.\n\nTut mir leid, dass wir so darauf bestehen mussten, aber wir sind nur ein kleiner Außenposten und es gibt große Probleme in dieser Region - die meisten davon ziemlich dringend.\n\nUnterm Strich heißt das: Wir können jede Hilfe gebrauchen, die wir bekommen können.\n\nZunächst einmal ist unser Freund Vahlarriel da drüben ziemlich nervös geworden und besteht darauf, dass wir ein Aufgebot zu den Ruinen im Osten entsenden.\n\nWarum geht Ihr nicht und stellt Euch vor...", progress = nil, completion = "Ist mir ein Vergnügen, Euch kennenzulernen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14388] = {title = "Azsharitexperiment Nummer Zwei", objective = "Sprecht mit Assistentin Greely, um auf Rattengröße zusammengeschrumpft zu werden. Steigt auf eine Ratte der Raketenbahn und jagt Gormungan dem Riesen damit Angst ein.", description = "Ok - neuer Plan. Wir ERSCHRECKEN sie so, dass wir es bekommen! Meiner Erfahrung nach ängstigen große Kreaturen sich vor kleinen - wie Ratten. Hmm. Hier wimmelt es nur so von Ratten, aber wie locken wir sie zu dem Riesen?\n\nHey! Es macht Euch doch nichts aus, wenn Eure Zellenmatrix auseinandergenommen und wieder zusammengesetzt wird, oder? Es tut nur während des Vorgangs weh. Ich kann Euch auf Rattengröße zusammenschrumpfen und Ihr könnt eins von den Viechern dort drüben reiten wie ein Pferd. Das ist so verrückt, dass es funktionieren muss! Lasst mich wissen, wenn Ihr zum Schrumpfen bereit seid...", progress = nil, completion = "Also hat Angst einjagen auch nichts bewirkt? Verflixt nochmal! Das muss ich Wurfhammer schonend beibringen. Azsharit wird wohl die seltenste Substanz auf dem Planeten bleiben. Wir müssen ihn äußerst sparsam verwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14389] = {title = "War das nicht klar?", objective = "Benutzt das Portal hinter Joanna in Xylems Turm, um Anara, die Geistheilerin - und hoffentlich Azuregos - zu finden.", description = "Azuregos! Ja, natürlich! Verstörter, alter Drache, aber ein gutes Herz. Ich glaube, all die Jahre, in denen er von Vagabunden angegriffen wurde, haben ihm nicht gutgetan. Heutzutage ist er ein wenig seltsam.\n\nVor nicht allzu langer Zeit, als ich wieder einmal zu Anara, unserer hiesigen Geistheilerin, zurückkehrte, fiel mir auf, dass sie und Azuregos sich anscheinend sehr gut verstehen. Ich könnte mir vorstellen, dass er ihr immer noch Gesellschaft leistet.\n\nDas Portal hinter mir ist der wahrscheinlich schnellste Weg, um zu ihr zu gelangen. Es könnte allerdings ein wenig zwicken.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14390] = {title = "Einfach kann jeder", objective = "Überzeugt Azuregos, in die Welt der Lebenden zurückzukehren und sich mit Kalecgos zu treffen.", description = "Nach langer Suche mit einigen zweifelhaften Wendungen habt Ihr endlich Azuregos gefunden.\n\nJetzt müsst Ihr ihn nur noch davon überzeugen, sich mit Kalecgos zu treffen und der Bedrohung Azsharas durch den schwarzen Drachenschwarm ein Ende zu bereiten.", progress = "<Azuregos starrt Euch an.>", completion = "Azuregos erklärt sich mit einem Treffen mit Kalecgos einverstanden. Erfolg!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14391] = {title = "Das Blatt wenden", objective = "Sprecht mit Anara, um in die Welt der Lebenden zurückzukehren, dann sprecht mit Kalecgos an der Nördlichen Endhaltestelle der Raketenbahn.", description = "Azuregos und Kalecgos sind kurz davor, sich an der Nördlichen Endhaltestelle der Raketenbahn zu treffen. Ihr solltet dort zu ihnen stoßen, um sicherzustellen, dass Kalecgos keine zusätzliche Hilfe benötigt.\n\nSolltet Ihr es vorziehen, nicht tot zu sein, wird Anara Euch höchstwahrscheinlich helfen können.", progress = nil, completion = "Schön, Euch wiederzusehen! Danke, dass Ihr Azuregos gefunden und zu mir geschickt habt.\n\nIch glaube, ich muss mich bei Euch entschuldigen - möglicherweise habe ich ein wenig untertrieben, als ich Euch über die Schwierigkeit der Aufgabe, die ich Euch stellte, ins Bild setzte. Ihr habt Euch bewundernswert geschlagen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14392] = {title = "Leb wohl, Minnow", objective = "Sprecht mit Sorata Feuerspinner im Bilgewasserhafen.", description = "Danke, kleines Wesen.\n\nManchmal ist es einfach, sich in der Umklammerung der Liebe zu verirren und die Sicht auf die wichtigen Dinge zu verlieren, sogar für einen Drachen. Ich gedenke, mich wieder vollkommen dem Ziel zu verschreiben, dass Kalec niemals Malygos' Platz einnehmen wird. Das ist die edelste Sache, die ich mir vorstellen kann.\n\nIhr solltet Euch auf den Weg zurück zum Hafen machen. Soweit ich weiß, wartet dort jemand auf Euch.\n\nVersucht, nicht zerquetscht oder von etwas gefressen zu werden.", progress = nil, completion = "Hallo - wieder einmal.\n\nHört mal, ich habe Euch meinen Hut gegeben. Er war ein Geschenk. Ich dachte, er könnte Euch vielleicht irgendwie nützlich sein. Um genau zu sein, dachte ich, Ihr würdet ihn so weit wie möglich von mir wegbringen.\n\nKönnt Ihr Euch meine Überraschung vorstellen, als Xylem höchstpersönlich hier vorbeikam, um ihn mir zurückzugeben? \"Willst du mehr wie meine anderen Lehrlinge sein, Sorata? Dann versuch's nochmal mit deinem Hut.\" Das war nicht einer der Momente, auf die ich stolz bin.\n\nAlso wie war das... Ihr habt ihn achtlos zur Seite geworfen, damit er ihn findet? Nein. Das glaube ich nicht. Ihr werdet diesen Hut nehmen und Ihr werdet ihn mögen. Ganz bestimmt.", rewards = "Ihr bekommt:\n\nVerblichener Zaubererhut"}
MultiLanguageQuestData['de'][14393] = {title = "Auf in den Kampf!", objective = "Khan Leh'prah möchte, dass Ihr 15 Hexenmeister der Brennenden Klinge, 3 Verdammniswacheneindringlinge und Priesterin Than'darissa besiegt.\n\nSprecht mit Khan Leh'prah, um in den Kampf zu ziehen.", description = "Seit unzähligen Generationen bekämpfen die Zentauren sich untereinander, aber das ist vorbei.\n\nWegen Eurer Taten stehen wir hier Seite an Seite und bekämpfen einen gemeinsamen Feind. Wir werden das Land unserer Vorfahren von diesen Dämonen zurückgewinnen, oder als Brüder sterben.\n\nWie ist es mit Euch, <Name>?\n\nIhr habt Euch das Recht verdient, an unserer Seite zu kämpfen. Ich möchte Euch eine Gruppe meiner besten Zentauren anvertrauen, damit Ihr sie in den Kampf führt.\n\nWerdet Ihr den Speer aufnehmen?", progress = nil, completion = "Gut gemacht, &lt;Name&gt;!\n\nLasst uns das hier beenden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14394] = {title = "Tod dem Agogridon", objective = "Besiegt Agogridon.", description = "Unser Ziel ist zum Greifen nahe, <Name>!\n\nWir können den Willen dieser Dämonenarmee brechen, indem wir ihren Anführer zur Strecke bringen. Gelingt es uns, wird Desolace uns gehören!\n\nWenn Ihr bereit seid, führt eine Gruppe Zentauren durch den Pass im Süden nach Schattenklamm. Findet Agogridons Versteck!\n\nIch werde die anderen Khans um mich versammeln und Euch dort treffen, damit wir uns ihm im Kampf stellen.", progress = nil, completion = "Agogridon gibt es nicht mehr.\n\nDie Dämonen werden sich nie wieder in unseren Landen ausbreiten!", rewards = "Entersäbel von AgogridonSeelensternstreitkolbenKolkarspalterDer folgende Zauber wird auf euch gewirkt:\n\nDeath to Agogridon Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14395] = {title = "Atemlos", objective = "Rettet 4 ertrinkende Wachleute.", description = "<Name>! Ich war gerade unterwegs, als es passiert ist.\n\nWir haben keine Zeit zu verlieren. Gut die Hälfte der Wachleute der Stadt hat sich in dem Bereich aufgehalten, der eingestürzt ist. Geht dorthin und rettet so viele, wie Ihr könnt.\n\nZieht sie aus dem Wasser ans Ufer. Ich kümmere mich darum, dass sie die benötigte Hilfe bekommen.", progress = "Es sind nicht mehr viele von uns übrig, <Name>. Wir müssen uns um die letzten verbliebenen Gilneer kümmern.", completion = "Ihr habt getan, was Ihr konntet, &lt;Name&gt;. Mit etwas Glück schaffen es noch ein paar andere ans Ufer.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwacher HeiltrankSchwacher Manatrank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14396] = {title = "Als das Land zerbarst", objective = "Sprecht mit Prinz Liam Graumähne auf Allens Bauernhof.", description = "Was in aller Welt war das, <Name>?\n\nDas waren keine Kanonen oder Katapulte, so viel steht fest.\n\nGeht nach draußen und seht nach, was los ist.", progress = nil, completion = "Das Meer, &lt;Name&gt;! Es hat alles verschlungen… das Land… die Verlassenen… unsere Männer!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14397] = {title = "Evakuierung", objective = "Sprecht mit Gwen Armstead in Dämmerhafen.", description = "Wir sind dem Tod nur durch schieres Glück entkommen, <Name>. Aber unser Glück ist langsam erschöpft.\n\nNoch während wir hier sprechen wird die Küste überflutet. Und auch die Landmasse unter uns scheint sich noch nicht beruhigt zu haben.\n\nIch sage es nicht gerne, aber wir müssen hier weg. Verdammt, <Name>... Ich darf mein Heimatland nicht zweimal in meinem Leben verlieren. Aber diese Erdbeben sind kein Feind, den wir besiegen können.\n\nSagt Gwen Armstead, dass sie die Evakuierung einleiten soll.", progress = nil, completion = "Liam hat Recht. Wir müssen in ein höher gelegenes Gebiet fliehen.\n\nHelft mir, die Leute zu benachrichtigen, während ich die Organisation der Evakuierung übernehme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14398] = {title = "Oma Wahl", objective = "Findet Oma Wahl in Wahls Landhaus.", description = "Es wird nicht leicht, Oma Wahl dazu zu bewegen, mit uns zu kommen. Ihr müsst dennoch alles in Eurer Macht Stehende tun, um sie zu überzeugen.\n\nIhr findet sie in Wahls Landhaus. Bitte, <Name>, seid geduldig mit ihr. Sie ist schon sehr alt und ihr Geist wird immer schwächer.", progress = nil, completion = "Oh, Besuch! Bleibt Ihr auf eine Tasse Tee, Herzchen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14399] = {title = "Oma hat sie nicht mehr alle", objective = "Findet das leinengebundene Buch.", description = "Gehen? Jetzt?\n\nNun, was sein muss, muss wohl sein. Aber wärt Ihr ein Engel und würdet etwas für mich suchen?\n\nIch habe mein Lieblingsbuch verlegt und werde ganz sicher nicht ohne es gehen.\n\n<Nachdem Ihr Oma die Dringlichkeit der Lage erläutert habt, schüttelt sie herablassend den Kopf.>\n\nLiebes, sucht einfach das Buch für mich, ja?", progress = "Wie läuft es, Schätzchen? Bleibt Ihr zum Tee?", completion = "Vielen Dank, &lt;Name&gt;. Ich hoffe, Ihr habt nicht hineingelinst!\n\nWo bleiben Eure Manieren, Herzchen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14400] = {title = "So gehe ich nicht außer Haus", objective = "Besorgt Omas gute Kleider.", description = "Was wolltet Ihr nochmal?\n\nOh, stimmt ja. Der Evakuierungsbefehl.\n\nAber so kann ich ja schlecht unter die Leute gehen, oder?\n\nSeid so lieb und holt mir meine guten Kleider. Sie hängen draußen auf der Wäscheleine.\n\n<Ihr versucht vergeblich, Oma Wahl davon zu überzeugen, dass ihre jetzige Kleidung völlig angemessen ist.>\n\nIhr jungen Leute habt einfach keine Manieren. Wurdet Ihr von Ogern großgezogen? Und jetzt geht und bringt mir meine Kleider, Liebes.", progress = "Habt Ihr alles gefunden, Schätzchen?", completion = "Ihr seid ein Goldschatz, &lt;Name&gt;! Vielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14401] = {title = "Omas Katze", objective = "Holt Felix, die Katze.", description = "Genau! Was die Evakuierung angeht, Liebes.\n\nIch kann nicht ohne meine Katze gehen. Er ist ein zuckersüßer orangefarbener Tigerkater.\n\nFelix spielt am liebsten in der Nähe eines alten Karrens in der Nähe einer Laube nordöstlich von hier.\n\nBringt ihn zu mir, dann können wir sofort aufbrechen.", progress = "Ihr seid so ein bezaubernder junger Mann, <Name>.", completion = "Da ist er ja! Omas kleiner Liebling!\n\nVielen Dank, dass Ihr ihn gefunden habt. Ich hoffe, es hat Euch nicht allzu viele Umstände bereitet.\n\nOh je… meine Fingernägel sind ja ganz dreckig!", rewards = "Omas HammerOrange DeckeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14402] = {title = "Abmarschbereit", objective = "Sprecht mit Gwen Armstead in Dämmerhafen.", description = "Ich schätze, jetzt aufzubrechen ist genauso gut wie zu jedem anderen Zeitpunkt.\n\nIch habe meine schönste Kleidung, mein Lieblingsbuch und meine geliebte Katze bei mir.\n\nIch hoffe, ich habe nichts vergessen.\n\nSagt dieser Bürgermeisterin, dass ich auf dem Weg bin. Dann sehe ich Euch wohl zusammen mit den anderen in der Stadt!", progress = nil, completion = "Ihr habt das Unmögliche geschafft, &lt;Name&gt;! Ihr habt Oma Wahl überredet, ihr Zuhause zu verlassen.\n\nIch muss schon sagen, Ihr seid etwas ganz Besonderes.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14403] = {title = "Die Brüder Hayward", objective = "Sprecht mit Sebastian Hayward in der Fischerei Hayward.", description = "Weit im Süden findet Ihr die Fischerei Hayward. Die Brüder Hayward führen sie schon seit vielen Jahren.\n\nSie kommen nicht oft in die Stadt, nur um ihre Fische zu verkaufen. Gebt ihnen Bescheid, dass die Evakuierung eingeleitet wurde.", progress = nil, completion = "Seid Ihr hier, um uns zu helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14404] = {title = "Nicht alles im Lot auf'm Boot", objective = "Besorgt Holzplanken, Kohlenteer und Schiffbauerwerkzeuge.", description = "Evakuierung, sagt Ihr? Nun, nachdem die Verlassenen hier aufgetaucht sind, kam uns diese Idee von ganz alleine.\n\nWir dachten, zur See wäre der sicherste Fluchtweg.\n\nLeider haben unsere Boote das letzte Erdbeben nicht unbeschadet überstanden.\n\nIch benötige noch ein wenig Material, um meine Reparaturen abzuschließen: Holz, Teer und meine Werkzeuge. Besorgt sie mir, damit ich und meine Brüder von hier entkommen können.", progress = "Habt Ihr mein Material, <Name>?", completion = "Toll, &lt;Name&gt;. Jetzt kann ich die Reparaturen im Handumdrehen fertigstellen.", rewards = "Ihr bekommt:\n\nSchiffsbauerbeutel"}
MultiLanguageQuestData['de'][14405] = {title = "Flucht zur See", objective = "Kehrt zu Gwen Armstead in Dämmerhafen zurück.", description = "Danke für Eure Hilfe, <Name>. Unser Schiff ist bereit zum Ablegen.\n\nUnd jetzt geht und sagt Fräulein Armstead, dass wir nicht an der Evakuierung über Land teilnehmen.\n\nWir Haywards sind seit Jahren Männer der See. Wenn wir unser Zuhause verlassen müssen, dann nur zu Wasser.", progress = nil, completion = "Soll mir Recht sein, &lt;Name&gt;. Vielleicht ergeht es den Haywards ja besser als uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14406] = {title = "Crowleys Obstgarten", objective = "Sprecht mit Lorna Crowley bei Crowleys Obstgarten.", description = "Ihr erinnert Euch doch sicher an Lord Darius Crowleys Tochter Lorna.\n\nSie hat sich nie ganz vom Verlust ihres Vaters in Gilneas erholt. Seitdem fristet sie ihr Leben als Einsiedlerin. Der einzige Besucher, den sie je in ihr Haus gelassen hat, war Krennan... und er verliert kein Wort über die ganze Sache.\n\nBenachrichtigt sie über die Evakuierung.", progress = nil, completion = "Bleibt zurück! Sonst werde ich…\n\nSeid Ihr das? Beim Licht! Ihr seid es, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14407] = {title = "Azshara Blues", objective = "Sprecht mit Kalec im Bilgewasserhafen.", description = "He! Ich bin froh, dass ich Euch erwischt habe.\n\nIch komme im Auftrag meines Meisters, Kalec. Er benötigt Eure Hilfe. Sucht ihn unter der Brücke in den Slums so bald wie möglich auf!", progress = nil, completion = "Danke, dass Ihr gekommen seid. Ich muss mich für die Geheimnistuerei entschuldigen, aber es ist ungeheuer wichtig, dass ich von gewissen Individuen nicht gesehen werde.\n\nIch bin nämlich ziemlich in der Klemme und mir sind Eure Taten in letzter Zeit aufgefallen. Hört Euch an, was ich zu sagen habe, helft mir und ich werde dafür sorgen, dass Ihr angemessen belohnt werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14408] = {title = "Neuns Plan", objective = "Beschafft die geheimen Raketenbaupläne aus den Laborarchiven am östlichen Ende des Geheimlabors. Betätigt die Türklingel und tötet den Labordirektor, wenn er herauskommt.", description = "Meine Wohltäter haben ihre spärliche Intelligenz dazu benutzt, ein interplanetares Transportmittel zu konstruieren. Mit dem jetzigen Design ist diese sogenannte \"Rakete\" eine Todesfalle. Aber ich denke, dass eine Umarbeitung der Klappe des Treibstoffkatalysators eine stabile Mischung erbringen würde, die ein atembares Sauerstoffnebenprodukt liefern würde. Um derartige Veränderungen einzubauen, benötige ich die Originalbaupläne.\n\nFindet die Laborarchive und betätigt die Türglocke, um hineinzugelangen. Der Labordirektor selbst hat die Pläne, wenn er denn noch lebt.", progress = "Ich nehme an, dass die Archive sich in der Nähe befinden, <Name>. Findet diese Pläne!", completion = "&lt;Das Raptorenweibchen schnappt sich die Papiere mit ihren Greifklauen und hält sie sich vors Gesicht. Dabei klappert sie verächtlich mit den Zähnen.&gt;\n\nDas sieht wie das Gekritzel von Kindern aus. Der gesunde Menschenverstand sagt, dass man die hydraulischen Kontrollen nicht so nah an die Brenner der zweiten Stufe legt. Immerhin, man kann noch etwas daraus machen.\n\nWisst Ihr, wie man eine Treibstoffmatrix so verändert, dass sich der Druck ändert und man eine bestimmte Beschleunigung erhält? Nein? Also schön, vielleicht könnt Ihr dann etwas anderes für mich erledigen, während ich die Rakete repariere...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14409] = {title = "Eine vorsichtige Rückkehr", objective = "Bringt Mordent Schattenfall in DarnassusDaros' Tagebuch.", description = "Schenkt mir einen Moment Eurer Zeit, <Klasse>.\n\nVeränderung liegt in der Luft. Sie hat uns aus den Ruinen von Eldre'Thalas gelockt, ein weiteres Mal hinaus in die weite Welt. Ich bin gekommen, um diese Stadt zu erforschen und darf von dieser Aufgabe nicht abweichen, doch wenn Ihr interessiert wärt, hätte ich einen Auftrag für Euch.\n\nMein Kollege ist auf dem Weg nach Darnassus, um mit der Hohepriesterin zu sprechen, auf dass wir eine Übereinkunft erreichen. Nehmt dieses Tagebuch und bringt es zu Mordent Schattenfall im Tempel. Es könnte ihm bei seiner diplomatischen Mission nützlich sein.", progress = "Es scheint, als hätte ich Zeit für eine Unterredung. Worum geht es?", completion = "Ah, Daros' Aufzeichnungen. Er war schon immer ein sehr sorgfältiger Chronist des Fortschritts. Seine Worte könnten helfen, zu erklären, wie weit wir gekommen sind.\n\nIhr habt meinen Dank dafür, dass Ihr mir dies hier gebracht habt, &lt;Volk&gt;. Vielleicht werden wir einander häufiger sehen, sobald erkannt wurde, dass wir niemandem schaden wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14410] = {title = "Die Wildnis von Feralas", objective = "Reist nach Feralas und sprecht mit Telaron Windsegler bei Träumersruh.", description = "Es ist wahrlich heldenhaft von Euch, uns beim Schutz dieses Landes zu helfen. Solltet Ihr noch mehr für die Wildnis tun wollen - es gibt noch andere, die Eure Hilfe benötigen.\n\nIm Süden liegen die grünen Wälder von Feralas. Sucht im Schatten der mächtigen Zwillingskolosse nach Telaron Windsegler. Bei Träumersruh haben er und seine Druidenfreunde der Kralle Zeichen einer beunruhigenden Krankheit gefunden.\n\nSie werden Eure Hilfe benötigen, <Klasse>. Geht in Frieden.", progress = nil, completion = "Willkommen in Feralas, &lt;Klasse&gt;. Ich danke Euch, dass Ihr gekommen seid, um uns zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14411] = {title = "Feralas Brotkrumen [PH]", objective = "Eines Tages werde ich aufwachsen und ein echter Brotkrumen sein! Nach Feralas!!!!", description = "Eines Tages werde ich aufwachsen und ein echter Brotkrumen sein! Nach Feralas!!!!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][14412] = {title = "Angespült", objective = "Tötet 6 schiffbrüchige Verlassene.", description = "Die Schiffe der Verlassenen sind viel zu nahe an unserer Fischerei gesunken. All die Überlebenden machen sich auf den Weg hierher. Wie Ihr sehen könnt, sind wir zahlenmäßig unterlegen.\n\nHelft uns, sie zurückzuhalten, während ich die Boote fertig repariere.", progress = "Verdammte Verlassene! Nicht einmal die See will sie haben!", completion = "Ausgezeichnet! Ich bin hier fast fertig.", rewards = "BootswerkstiefelReparaturgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14413] = {title = "Der Gipfel des Lernens", objective = "Sprecht mit dem Abbild von Erzmagier Xylem am Fuß der Arkanen Spitze.", description = "Ist das aufregend! Ihr fragt, was aufregend ist? Na, DIES ist natürlich aufregend!\n\nDie Zeit der Prüfungen... Zeit EURER Prüfungen. Es gilt, so viele Herausforderungen zu meistern, so vieles zu lernen. Ihr lernt etwas über Prüfungen. Ich lerne etwas über Euch.\n\nUnd jetzt geht nur. Zu meiner Arkanen Spitze. Natürlich werde ich Euch dort treffen, denn ich bin so ziemlich überall.", progress = nil, completion = "Ihr seid schon da. Ich hoffe, Ihr hattet eine angenehme Reise. Euch ist doch nicht übel geworden, oder?\n\nEs wird viel Herumrennen und genausoviel Springen geben, deshalb ist ein ausgeglichener Magen von großem Vorteil.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14414] = {title = "Feralas Brotkrumen [PH]", objective = "Eines Tages werde ich aufwachsen und ein echter Brotkrumen sein! Nach Feralas!!!!", description = "Eines Tages werde ich aufwachsen und ein echter Brotkrumen sein! Nach Feralas!!!!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][14416] = {title = "Der hungrige Ettin", objective = "Bringt 5 Gebirgspferde zu Lorna Crowley bei Crowleys Obstgarten.", description = "Hört zu, <Name>. Wir werden es ohne ein Transportmittel nicht weit schaffen, nicht wahr?\n\nWenn wir uns hier einfach nur so aus dem Staub machen, werden die Verlassenen uns im Handumdrehen einholen.\n\nNormalerweise wäre es überhaupt kein Problem, ein paar Pferde in den Stallungen im Südosten aufzutreiben, aber da gibt es einen Haken.\n\nDas letzte Erdbeben muss Koroth den Ettin aus den Bergen herunter zu uns vertrieben haben. Wenn wir uns die Pferde nicht bald schnappen, fürchte ich, dass er uns zuvorkommt.", progress = nil, completion = "Wir haben die Pferde. Ich stelle sicher, dass sie nach Dämmerhafen gelangen.", rewards = "Lornas HandschuheCrowleys GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14418] = {title = "Die Todespirscher", objective = "Bringt Androns Geschäftsbuch zu Aleric Hawkins in die Halle der Dunklen Fürstin in Unterstadt.", description = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.\n\nHawkins wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.\n\nAh, und wie konnte ich das vergessen?\n\nWillkommen bei den Todespirschern.", progress = "Ja?", completion = "Hmm, das ist interessant. Die Todespirscher haben ihre Pflicht bei der Erledigung dieser Aufgabe meisterlich erfüllt.\n\nWie mir gesagt wurde, verdient Ihr eine Belohnung für das, was Ihr in dieser Sache geleistet habt. Immer weiter so, &lt;Name&gt;; die Todespirscher haben immer Verwendung für gute Männer.", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"}
MultiLanguageQuestData['de'][14419] = {title = "Die Todespirscher", objective = "Sprecht mit Andron Gant in Unterstadt.", description = "Das Vorstellungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nUnser Anführer vermutet, dass Andron einer anderen Gruppe Unterstützung zuteilwerden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", progress = "Hallo. Kann ich etwas für Euch tun?", completion = "Ah, ja, ich habe Euch erwartet. Ich darf davon ausgehen, dass unsere gemeinsamen Bekannten mit den Informationen, die ich bisher lieferte, zufrieden waren?\n\nVermutlich hat es keinen Sinn, Euch zu fragen. Ich bezweifle, dass sie Euch mit diesem Wissen belasten würden. Warum so viel Vertrauen in den Boten setzen, hm?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14420] = {title = "Die Todespirscher", objective = "Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache der Dunklen Fürstin, so müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, <Name>, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Unterstadt pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", progress = "Erfolgsmeldung?", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt den ersten Teil dieser Prüfung bestanden. Hoffentlich hat Andron keinen Wind von Euren Aktivitäten bekommen, sodass wir ihn davon überzeugen können, dass Ihr wirklich der Bote seid, den er erwartet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14421] = {title = "Die Todespirscher", objective = "Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt.", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", progress = "Erfolg, <Name>?", completion = "Das sind eindeutig mehr Informationen, als ich mir je von Andron erhofft hätte. Lasst sie mich einen Moment studieren, bevor ich Euch Eure nächste Aufgabe nenne.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14422] = {title = "Raptor Rakete", objective = "Befreit fünf Versuchsraptoren aus ihren Käfigen im Geheimlabor und liefert sie bei der Rakete neben Versuchsobjekt neun ab.", description = "Kurz nachdem meine Intelligenz erweitert worden war, habe ich mich mit Versuchsobjekt vier verpaart, um eine einzigartige Rasse geistig überlegener Raptoren zu erschaffen. Im Anschluss hat Versuchsobjekt vier weder angerufen noch geschrieben: Ich habe beschlossen, ihn auseinanderzunehmen, wenn wir uns noch einmal begegnen.\n\nNichtsdestotrotz sind in diesem Labor genug Raptorenkinder gefangen, die einen angemessenen genetischen Grundstock bilden, um meine Rasse wieder aufleben zu lassen. Bitte befreit sie aus ihren Käfigen und tragt sie zu der Rakete.", progress = "Es könnte sein, dass meine hübschen Kinder Euch während der Befreiung beißen, aber in Anbetracht des Stadiums ihrer körperlichen Entwicklung dürften ihre Angriffe nicht tödlich enden.", completion = "Wunderbar! Eine beispielhafte Leistung, &lt;Name&gt;! Wie Ihr Euch zweifellos schon gedacht habt, ist es mein Ziel, diese Rakete als eine Art Sternenwiege zu benutzen - eine Arche, wenn Ihr so wollt -, die es meiner neuerschaffenen Rasse erlaubt, den trostlosen Fesseln dieses geschundenen Planeten zu entfliehen und eine Welt zu kolonisieren, die uns gefällt. Ihr habt bei dieser Sache eine entscheidende Rolle gespielt. Bitte nehmt diese Währung an, da ich bei unserer Ankunft meine eigenen Geldeinheiten prägen werde. Lebt wohl, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14423] = {title = "Raupenexorzismus", objective = "Benutzt die gesegnete Leuchtpistole in der Nähe von Clubniks Planierraupe, um Hilfe herbeizurufen, dann führt an der Planierraupe einen \"Exorzismus\" durch.", description = "... wir brauchen einen Priester!\n\nZum Glück habe ich ein bisschen Geld zur Seite gelegt, um die Maschinen segnen zu lassen. Nehmt diese Leuchtpistole und geht hinüber zu Margene, meiner armen, kleinen, kaputten Planierraupe. Feuert das Signal ab und einer unserer besten fliegenden Priester sollte mit dem Fallschirm eintreffen, um die Situation unter Kontrolle zu bringen. Kommt zurück, wenn meine Planierraupe in guten Händen ist!", progress = "Wie geht es Margene? Läuft sie wieder so süß wie sie immer läuft?", completion = "Was? ...Was?\n\nMargene! Oh, meine süße Margene!", rewards = "BulldozerwesteMargenes ReparaturhandschuheStandardfliegergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14424] = {title = "Mehr Wissenschaft benötigt", objective = "Findet Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn. Man kann die Goblinraketenbahn nutzen, um schnell durch Azshara zu reisen.", description = "<Clubnik wischt sich eine Träne weg. Dann streckt er entschlossen sein Kinn vor.>\n\nNie wieder, <Name>! Kein Bulldozer verdient das Schicksal meiner Margene. Wir werden professionelle Geisterjäger brauchen. Das ist ein Job für unsere besten Wissenschaftler und ich kenne genau die richtige Frau dafür! Sucht nach Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn. Sie ist die Verwalterin für Azsharas weltberühmtes Geheimlabor und sie schuldet mir einen Gefallen.", progress = nil, completion = "Wovon redet Clubnik da? Spukende Bauausrüstung? Seh ich so aus, als ob ich Zeit für Geistergeschichten hätte?\n\nIch habe ein Labor, das kurz vor der Schmelze steht, brennende Feuer, mutierte Tiere und das Schlimmste ... Projekte, die hinter den Zeitplan zurückfallen. Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14427] = {title = "Gegenstandsquest", objective = "Holt die Gegenstände", description = "Gegenstand einsammeln Quest", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][14428] = {title = "Goldwinds Tagebuch", objective = "Tötet Wissenshüterin Goldwind im Darnassischen Basislager und bringt ihr Tagebuch in Euren Besitz.", description = "Wenn ich meinen Quellen vertrauen kann, überwacht Wissenshüterin Goldwind die Untersuchung der Ruinen durch die Allianz im Osten. Ich habe das Ausmaß ihrer Fähigkeiten noch nicht auf die Probe gestellt. Ich hoffe, Ihr könnt mir einen vollständigen Bericht liefern, nachdem Ihr sie zum Kampf gestellt und besiegt habt.\n\nJemand, der einen Titel wie 'Wissenshüter' trägt, wie Goldwind, wird ein Tagebuch bei sich haben, das uns sagen wird, was genau diese Nachtelfen vorhaben. Bringt mir dieses Tagebuch. Ihr müsst auch nicht zurück laufen, benutzt ihre Sehersteine, um mich aus der Ferne zu kontaktieren.", progress = "<Andorels verzerrtes Gesicht taucht in dem Seherstein auf.>\n\n<Name>, habt Ihr den Kontakt herstellen können? Was könnt Ihr mir mitteilen?", completion = "Goldwind hat sich ein Arkanes Konstrukt zunutze gemacht? Ha! Wie erfreulich unerfahren. Das ist, als ob man andere Kinder dabei beobachtet, wie sie mit Feuerwaffen spielen.\n\nSehen wir uns einmal das Tagebuch an, &lt;Name&gt;. Haltet es vor den Seherstein... Haltet still...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14429] = {title = "Arkane Dekonstruktion", objective = "Tötet Angehende Ermittler und Angehende Illuminatoren um 10 Abgestimmte Runensteine einzusammeln.", description = "Arkane Konstrukte sind Kreaturen, die aus reinem Mana und Intelligenz ins Leben gerufen wurden. In den richtigen Händen befähigen sie ihre Nutzer, sich schnell riesige Mengen arkanes Wissen anzueignen. Aber sie sind gefährlich, <Name>. So intelligent! So mächtig! So hilflos Manipulationen von außen ausgesetzt...\n\nLasst uns diesen Amateuren eine Lektion erteilen und ihre eigene Magie gegen sie verwenden. Tötet Lehrlinge und sammelt ihre Runensteine für mich ein. Nehmt über den Unteren Seherstein Kontakt mit mir auf, wenn Ihr fertig seid.", progress = "<Andorels Bild ist verschwommen und unscharf. Er blinzelt Euch an und tippt gegen das Glas des Sehersteins.>\n\n<Name>, seid Ihr das? Die Auflösung dieses Steins ist furchtbar. Was benutzen die nur für eine Hardware?", completion = "Gute Arbeit, diese Runensteine zu beschaffen. Um ehrlich zu sein, brauche ich nur einen, aber der Gedanke, dass so viele Nachtelfen für diese nutzlosen Kugeln getötet werden, bringt mir dunkle Freude, die mich ganz schwindelig macht.\n\nBitte haltet eine dieser Runen hoch vor den Seherstein, damit ich sie sehen kann. Hmmm. Wie ich mir bereits dachte - das ist bestenfalls dilettantisch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14430] = {title = "Das Konstrukt hacken", objective = "Sprecht mit dem arkanen Konstrukt im Darnassischen Basislager und sprecht die Worte der arkanen Macht.", description = "Jetzt werden wir ihr arkanes Konstrukt hacken und es dazu benutzen, Chaos anzurichten. Habt Ihr diese Art Magie schon einmal verwendet, <Name>? Nein? Ha! Das macht meinen Plan noch delikater. In der Nähe solltet Ihr ein beeindruckendes arkanes Konstrukt sehen, das sie herbeigerufen haben. Dank der Runensteine, die ihr gesammelt habt, wissen wir, wie man mit ihm kommuniziert. Sprecht mit dem Konstrukt und sagt:\"Al'teth la c'tolgar.\" Verstanden? Wiederholt es? Sollte reichen. Meldet Euch wieder bei mir und lasst mich wissen, was geschehen ist.", progress = nil, completion = "Haha! Ha - HA! Nachtelfische Magier, die vor ihrer eigenen, arkanen Kreation flüchten. Eure Taten haben mir den ganzen Monat versüßt, &lt;Name&gt;. Deshalb benutzen wir Blutelfen die arkanen Konstrukte nicht länger - sie wurden vor, oh, ungefähr 1500 Jahren für ungesetzlich erklärt. Es ist schon lustig für mich zu sehen, wie unsere Feinde die Fehler der Vergangenheit wiederholen. \"Magier\". Dass ich nicht lache.", rewards = "Gamaschen des HackersMagierarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14431] = {title = "Die Schwarzschlund-Narbe", objective = "Tötet 8 Biologen der Talrendisspitze und nehmt die Geheimdienstinformationen des Schwarzschlunds von einer der Leichen an Euch.", description = "Die Furbolgs des Schwarzschlunds haben mit ihren Brüdern vom Holzschlund gebrochen, als wir begannen, Azshara aggressiv zu besiedeln. Sie sind wild geworden, <Klasse>, und belästigen unsere Streitkräfte, wo sie nur können. Schlimmer noch - ich habe gesehen, wie sie den Nachtelfen von Talrendis freundlich begegnet sind. Wir können den beiden nicht erlauben, sich zu verbünden!\n\nGenau im Südwesten von hier findet Ihr eine große Narbe quer über die Erde. Von dort melden meine Späher Aktivitäten der Nachtelfen. Tötet sie und sammelt so viele Informationen, wie Ihr finden könnt.", progress = "Die Schwarzschlundfurbolgs sind wild. Wenn sie sich jemals zusammenraufen sollten, würde das unsere Arbeit hier sehr behindern.", completion = "Ich verstehe... Das sieht aus wie die Rohfassung eines Abkommens. Der Ernstfall ist also eingetreten, &lt;Name&gt;: Nachtelfen koordinieren ihre Angriffe mit unbeugsamen Furbolgverbündeten.\n\nMein erster Instinkt - ein Frontalangriff - würde sie nur in die Arme der Allianz treiben. Wir müssen uns etwas anderes überlegen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14432] = {title = "Ein fahles Gebräu", objective = "Sammelt 10 Proben Strauchwurzelgebräu außerhalb der Schwarzschlundfeste.", description = "Es sieht so aus, als ob unsere Feinde der Allianz uns bei den Gesprächen mit den Schwarzschlund voraus sind, weil sie die Verhandlungen in Furbolgsprache führen. Wenn wir das Abkommen sabotieren wollen, müssen wir das genauso machen.\n\nDas ist nicht so schwer, wie es klingt, <Name>. Die Schwarzschlundfurbolgs machen einen starken Kräutertee. Durch seine Dämpfe wird man in eine Art Trance versetzt, in der man beginnt, in Zungen zu reden. Genauer gesagt in der Zunge der Schwarzschlund. Geht zur Schwarzschlundfeste südwestlich von hier und besorgt mir einige Proben von diesem Strauchwurzelgebräu!", progress = "Was macht die Jagd? Ich habe das Strauchwurzelzeugs selbst einmal probiert, aber es war zu bitter, sogar für einen alten Kiesfresser wie mich.", completion = "Ah gut, das ist reichlich. Wir kochen das Zeug jetzt auf und Ihr könnt eine Weile die Dämpfe einatmen. Es wird nicht lange dauern, dann sprecht Ihr wie ein Furbolg. Unser Plan nimmt allmählich Gestalt an...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14433] = {title = "Diplomatie mal anders", objective = "Bringt eine Versammlungsagenda des Schwarzschlunds in der Schwarzschlundfeste an Euch und tötet einen Botschafter der Talrendisspitze, um eine Botschafterrobe in Euren Besitz zu bringen.", description = "Um die Verhandlungen mit den Schwarzschlundfurbolgs zu unterwandern und zu stören, müssen wir wissen, wo sie stattfinden. Ich vermute, Ihr werdet in der Schwarzschlundfeste im Südwesten Botschafter der Nachtelfen vorfinden, die dort geschäftig umherlaufen und Vorbereitungen treffen.\n\n<Haggrum spuckt auf den Boden.>\n\nTötet sie nach Belieben und durchsucht die Gegend nach wichtigen Dokumenten. Oh, und wenn Ihr schon da seid - bringt doch eine Botschafterrobe mit... wir werden sie benötigen.", progress = "Habt Ihr die Robe? Andorel hat ein bisschen Magie für uns auf die Schnelle bereitgestellt, die wir benutzen können.", completion = "Ihr habt vorzügliche Arbeit geleistet! Lasst mich diese Dokumente einmal sehen. Hmm. Jetzt wissen wir genau, wann und wo die abschließenden Verhandlungen stattfinden werden. Macht Euch keine Sorgen, wenn Euch die Robe nicht passt - ich habe schon alles geplant.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14434] = {title = "Rut'theran", objective = "Seid Ihr bereit, die Segel zu setzen, <Name>? Euer Volk hat im Land der Kaldorei eine Zuflucht gefunden.\n\nSeid unbesorgt, <Volk>. Euer Volk wird die Chance haben, wieder für Gilneas zu kämpfen. Dieses Mal mit der ganzen Macht der Allianz.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTeleport to Rut'theran\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14435] = {title = "Doppeltes Spiel bei den Schwarzschlund", objective = "Tragt die Verkleidung als Botschafter und sprecht mit Andorel Sonnenschwur, damit er Euch in die Schwarzschlundfeste teleportiert. Sprecht mit Ungarl, um die Verhandlungen zunichtezumachen, dann tötet 4 Krieger des Schwarzschlunds und 4 Schamanen des Schwarzschlunds auf dem Weg nach draußen.", description = "Andorel hat ein bisschen Magie für mich bereitgestellt. Kommt, stellt Euch neben mein Feuer und taucht in die Dämpfe des Tees ein. Legt die Robe an und Ihr werdet für die Schwarzschlundfurbolgs wie ein Botschafter der Nachtelfen aussehen.\n\nLegt Eure Verkleidung an und sprecht mit Andorel hier im Lager. Er wird Euch in das Herz der Schwarzschlundfeste teleportieren, wo die Verhandlungen stattfinden werden. Sprecht mit Häuptling Ungarl und sabotiert das Abkommen. Dann tötet auf Eurem Rückweg so viele Schwarzschlundfurbolgs wie möglich!", progress = "Wenn unsere List aufgeht, <Name>, werden wir für immer einen Keil zwischen die Allianz und die Schwarzschlundfurbolgs treiben.", completion = "Sieg! Die Schwarzschlundfurbolgs wissen jetzt nicht mehr, wem sie trauen sollen.\n\nJetzt, da wir dieses heikle Geschäft erledigt haben, kann ich einen Frontalangriff auf diese Ungeheuer organisieren, ohne dass ich mir Sorgen darüber machen muss, dass sie sich mit der Allianz zusammenschließen.\n\nIhr leistet gute Arbeit, &lt;Name&gt;. Vielleicht sollten wir Euch eine Stelle im diplomatischen Corps der Horde verschaffen? Har-har!", rewards = "Diplomatischer GürtelVerhandlungsstampferHandschuhe des BündnisbrechersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14436] = {title = "Zwergenbuddelei", objective = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Ahmo Donnerhuf im Dorf der Bluthufe 5 zerbrochene Werkzeuge.", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Donnerfels, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Verstärkte BindungenGrobgehauene KodogamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14437] = {title = "Riten der Erdenmutter", objective = "Bringt Ahmo Donnerhuf im Dorf der Bluthufe Falkenwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, <Name>.\n\nReist ins Dorf der Bluthufe und sprecht mit Ahmo Donnerhuf. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Donnerfels verdienen.\n\nBringt Ahmo dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr könntet Euch sonst verirren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14438] = {title = "Gemeinsame Nutzung des Landes", objective = "Tötet 15 Gnolle der Bleichmähnen und kehrt dann zu Ahmo Donnerhorn ins Dorf der Bluthufe zurück.", description = "Viele Konflikte verwunden dieses Land, <Name>. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich vom Dorf der Bluthufe und in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", progress = nil, completion = "Es ist gut, dass Ihr meine Aufgabe so ernst genommen habt, &lt;Name&gt;. Respekt vor dem Land und seinen Kreaturen ist wichtig. Tod und Leben bilden einen Kreis... eine Notwendigkeit. Das eine kann nicht ohne das andere existieren. Nehmt Euch einen Moment Zeit, um darüber nachzudenken, und vergesst es niemals.", rewards = "Ihr bekommt:\n\nDonnerhornumhang"}
MultiLanguageQuestData['de'][14439] = {title = "Reise nach Donnerfels", objective = "Sprecht mit Baine Bluthuf in Donnerfels.Jetzt wird man Euch in unserer großen Stadt mit Respekt gegenübertreten. <Ein/Eine:r> <Volk>, <der/die> würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nSucht unseren jungen Anführer Baine Bluthuf auf, um Eure letzte Aufgabe zu erhalten. Er residiert auf der höchsten Anhöhe in Donnerfels.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Jetzt wird man Euch in unserer großen Stadt mit Respekt gegenübertreten. <Ein/Eine:r> <Volk>, <der/die> würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nSucht unseren jungen Anführer Baine Bluthuf auf, um Eure letzte Aufgabe zu erhalten. Er residiert auf der höchsten Anhöhe in Donnerfels.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14440] = {title = "Riten der Erdenmutter", objective = "Baine Bluthuf in Donnerfels möchte, dass Ihr ihm das Horn von Arra'chea bringt.", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Donnerfels verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, <Name>. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKodojägergamaschen"}
MultiLanguageQuestData['de'][14441] = {title = "Garroshs Autogramm", objective = "Reist nach Orgrimmar und kümmert Euch darum, für Euren Schützling ein Autogramm von Garrosh Höllschrei zu bekommen.", description = "Man sagt, dass Garrosh Höllschrei einer der größten Helden der Horde ist! Wenn ich einmal groß bin, will ich auch so ein Held sein!\n\nKennst du Garrosh, <Name>? Könntest du mir einen Gefallen tun, bitte? Kannst du sein Autogramm für mich bekommen? Ich weiß nicht, wie ich ihn fragen soll, und wahrscheinlich würde er jemandem wie mir gar nicht zuhören... aber du! Du bist ein Abenteurer wie er! Ich wette, dass er dir mir nichts, dir nichts ein Autogramm geben wird!\n\nBitte?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14442] = {title = "Mein Lieblingsversuchsobjekt", objective = "Findet Versuchsobjekt neun irgendwo in der Nähe des Geheimlabors in Azshara.", description = "Ich weiß nicht, ob Ihr es bemerkt habt, <Name>, aber dieser ganze Laborkomplex ist jenseits von Gut und Böse! Mir ist es ja egal, diese ganzen Hippogryphen abzuschreiben, aber mein wertvollstes Experiment ist abhandengekommen: Versuchsobjekt neun!\n\nVersuchsobjekt neun ist ein weiblicher Raptor, den wir aus dem Brachland importiert haben. Ich frage mich, ob sie noch am Leben ist? Versucht einmal, oberhalb des Hauptgebäudes westlich von hier nachzusehen, in der Nähe der riesigen, streng geheimen Rakete. Ihr könnt sie nicht übersehen.", progress = nil, completion = "Seid Ihr gekommen, um mir bei meiner Arbeit zu helfen? Meine Klauen sind recht geschickt, aber ich muss ich widerwillig zugeben, dass meine Arme extrem kurz und deswegen hinderlich sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14443] = {title = "Der ramponierte Schwertgriff", objective = "Bringt den ramponierten Schwertgriff zu Caladis Prunkspeer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Der Silberbund wäre sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", progress = "Was habt Ihr denn da?", completion = "&lt;Caladis nimmt Euch den Schwertgriff ab und begutachtet ihn langsam drehend in seiner Hand.&gt;\n\nDer kommt mir irgendwie bekannt vor, als müsste ich wissen, woher er kommt. Ihr habt ihn in der Zitadelle gefunden? Äußerst interessant.\n\nEs gibt nur wenige, welche die Fähigkeit besitzen, solch eine Klinge herzustellen. Vielleicht können sie uns etwas über Euren Fund sagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14444] = {title = "Das Wissen der Drachen", objective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", description = "Es gibt keinen Zweifel: Dieser Schwertgriff stammt von einer mächtigen, uralten Waffe - aber welcher? Ich kann mich nicht daran erinnern, ein Schwert mit solchen Markierungen gesehen oder davon gehört zu haben, was jedoch nicht heißt, dass wir in einer Sackgasse gelandet sind.\n\nKorialstrasz, besser bekannt als Krasus, ist schon seit Langem ein Freund der Quel'dorei und der Kirin Tor. Seinem immensen Wissen und seinen gewaltigen Ressourcen nach zu urteilen wird er mit Sicherheit etwas wissen. Reist zur Spitze des Wyrmruhtempels und ersucht ihn um Rat. Meldet Euch anschließend bei Arkanist Tybalin im Inneren der Silbernen Enklave in Dalaran.", progress = nil, completion = "Wir dürfen das Buch nicht in den Händen der Sonnenhäscher belassen. Wenn wir das Schwert identifizieren und zu unserem Vorteil nutzen wollen, müssen wir einen Weg finden, an das Buch heranzukommen, das Krasus ihnen geliehen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14445] = {title = "Abschied auf Zeit", objective = "Sprecht mit Sassy Hartzang an der Wilden Aussicht auf den Verlorenen Inseln.", description = "Unsere Schicksale sind bis auf alle Ewigkeit miteinander verwoben. Es geschehen Dinge, die unsere Welt verändern und schließlich zerstören werden. Wir müssen ihnen ein Ende setzen, bevor es zu spät ist.\n\nVergesst nicht, Ihr könnt Euch immer auf mich verlassen, <Bruder/Schwester>! Wir werden uns auf der größeren Insel erneut sehen. Möget Ihr bis dahin Frieden finden, <Name>.", progress = nil, completion = "Kann ich meinen Augen trauen? Seid Ihr das wirklich?\n\nIhr habt Thrall, den Kriegshäuptling der Horde gerettet?!\n\n&lt;Sassy wirft Euch einen anerkennenden Blick zu.&gt;\n\nNun, dann schauen wir mal, wie wir zu der größeren Insel gelangen. Bei all den Haien da unten habe ich wirklich keine Lust zu schwimmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14446] = {title = "Kataklysmus!", objective = "Nambria möchte, dass Ihr in das Wasser der Weitsicht blickt.", description = "Hört mich an, <Klasse>!\n\nDie Winde das Wandels haben sich zu einem gewaltigen Sturm vereint, der über ganz Azeroth hinwegfegt.\n\nSeid Ihr kühn genug, Euch dem wahren Grund für unser Elend zu stellen?\n\nNehmt Euren ganzen Mut zusammen, <Volk>, und betet, dass Stärke und Glück Euch bei den bevorstehenden Prüfungen helfen werden.\n\nEin unerwarteter Verbündeter hat einen Ruf an alle ausgestoßen, die ihn hören. Schaut in das Wasser der Weitsicht und erhascht einen Blick auf das Schicksal der Welt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14447] = {title = "Der Insider", objective = "Himmelshäscher Korm möchte, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14448] = {title = "Der Insider", objective = "Himmelshäscher Korm möchte, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14449] = {title = "Der erste Schritt", objective = "Folgt dem Weg, der aus Camp Narache nach Osten führt, und sucht Grull Falkenwind auf.", description = "Was Ihr hier seht, ist das Werk der Stacheleber, mein Kind. Jahr für Jahr sind sie in unser Dorf eingefallen. Durch den großen Kataklysmus sind sie nun aus ihren Dornen hervorgekommen und haben sich wie Heuschrecken im ganzen Land breitgemacht. Das Ergebnis sieht man nur allzu gut; selbst meine Mutter starb aufgrund ihrer Wildheit.\n\nHeute ist der Tag, an dem Ihr Eure Volljährigkeit erreicht. Heute ist der Tag, an dem Ihr Eure Waffe nehmen, für den Klan kämpfen und Großmutter Falkenwind rächen werdet. Folgt dem Weg nach Osten - dort werdet Ihr meinen Sohn Grull finden. Er wird Euch bei Eurem Angriff auf die Stacheleber anführen.", progress = nil, completion = "Willkommen zu Eurer ersten richtigen Prüfung als &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14450] = {title = "Randomdrop-Test Progressiv", objective = "Beschafft 10 progressive Dingse.", description = "Diese Quest testet Zufallsdrops mit progressiver Prozentzahl für Drops.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][14451] = {title = "Randomdrop-Test FlatRate", objective = "Beschafft 10 Flatratedingse.", description = "Diese Quest testet Zufallsdrops mit Flatrate-Prozentzahl für Drops.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][14452] = {title = "Ritus der Kraft", objective = "Tötet 6 Eindringlinge der Borstennacken.", description = "Merkt auf, <Name>. Allein schon die Anwesenheit der Borstennacken macht diesen Ort zu einem Schandfleck. Wo sie sind, bleibt nichts übrig außer Leichen und Brachland. In Camp Narache könnte es in nur wenigen Tagen genau so aussehen wie hier, wenn wir nicht standhaft bleiben und kämpfen.\n\nDies wird Euer Ritus der Kraft - die erste Zeremonie, die einem Kriegerhelden der Tauren gewährt wird. Begebt Euch ins Herz von Dornknoten und tötet die Stacheleber der Borstennacken. Kehrt daraufhin zu mir zurück.", progress = nil, completion = "Ihr habt gut gekämpft, &lt;Name&gt;. Wir können vielleicht noch gerettet werden.", rewards = "Sonnengebleichte ArmschienenMatschspritzender HammerRoter ZeremoniendolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14454] = {title = "Der gefangene Krieger", objective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Kriegerheld Scharfhorn gefangen ist.", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Kriegerheld Scharfhorn, einen jungen Kriegerlehrer, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen Schlüssel für den Käfig und befreit ihn!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14455] = {title = "Haltet die Dornenrufer auf", objective = "Tötet 7 Dornenrufer der Borstennacken.", description = "Die Eigenheiten seiner Beute zu kennen ist ein sehr wichtiger Aspekt bei der Jagd. In ihrer Heimat leben die Stacheleber in den Schatten und im Schutz großer Dornenwurzeln. Wenn sie unterwegs sind, pflanzen die Schamanen Samen, um neue Dornenbehausungen wachsen zu lassen.\n\nDiese Dornen schädigen das Land und entziehen allen anderen Pflanzen das Leben, so dass ein Brachland entsteht. Reist nach Süden und haltet die Dornenrufer auf, bevor sie noch mehr Land zerstören können, <Name>.", progress = nil, completion = "Nun, da die Dornenrufer tot sind, wird die Erdenmutter ihre eigenen Wunden selbst heilen können. Die Wurzeln sind nicht für diesen Ort bestimmt und werden eingehen. Das Gleichgewicht wird wieder hergestellt.", rewards = "DornenruferhosenDornenbesetzter SattelgurtDornensichere HandgelenksschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14456] = {title = "Ritus des Muts", objective = "Holt 7 gestohlene Gewehre von den Waffendieben der Borstennacken zurück.", description = "Etwas, das Ihr bereits sehr früh erlernen müsst, ist, Eure Beute nie zu unterschätzen, <Name>.\n\nWährend wir durch die Angriffe in Camp Narache abgelenkt waren, haben einige Borstennacken sich unbemerkt angeschlichen und eine Kiste mit Gewehren geklaut. Ihr könnt von hier aus sehen, wie sie im Süden nun die Luft mit Blei füllen.\n\nDies wird Euer Ritus des Muts: Stellt Euch dem Regen der Gewehrschüsse, jagt die Waffendiebe der Borstennacken und bringt uns unsere Gewehre zurück.", progress = "Wie viele der gestohlenen Gewehre konntet Ihr an Euch bringen, Initiand?", completion = "Gut gemacht, &lt;Name&gt;. Zeigt Respekt vor Eurer Beute und der Gefahr, die mit ihr verbunden ist, aber fürchtet sie nicht. Wer Furcht zeigt, wird selbst zur Beute.", rewards = "Roben der SonneGamaschen des KaninchenjägersGewehr des WeitpirschersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14457] = {title = "Der Plan der Sonnenhäscher", objective = "Gelangt an die Befehle der Sonnenhäscher.", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Nähe des Schwarzmarktes einen Agenten der Sonnenhäscher erblickt. Die Sonnenhäscher sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und kümmert Euch um ihn. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass sie ihn zuerst zurück nach Eiskrone bringen.", progress = "Habt Ihr irgendetwas Brauchbares bei dem Agenten finden können?", completion = "&lt;Arkanist Tybalin sieht sich die gefundenen Befehle genauer an.&gt;\n\nDer Agent, den Ihr abgefangen habt, sollte, nachdem er sich mit einem gewissen Magister Hathorel in Sonnenhäschers Zuflucht getroffen hat, den Folianten nach Eiskrone bringen. Wir müssen dieses Buch bekommen, &lt;Name&gt;, und das ist unsere Chance. Es wird jedoch nicht einfach sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14458] = {title = "Sucht Adana auf", objective = "Sucht Adana Donnerhorn im Südwesten auf.", description = "Wir konnten gegen die Borstennacken hier einiges ausrichten. Ich werde hier bleiben und das Gebiet sichern, aber Ihr müsst weiterreisen.\n\nSucht Adana Donnerhorn auf; sie ist mit ein paar Kriegerhelden nach Südwesten aufgebrochen, um den Rest der Borstennacken auszumerzen.", progress = nil, completion = "Es liegen noch weitere Prüfungen vor Euch, &lt;Name&gt;. Ich hoffe, Ihr seid gut vorbereitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14459] = {title = "Die Kampfeber", objective = "Tötet 10 gepanzerte Kampfeber.", description = "Es gibt noch mehr Gefahren, um die wir uns kümmern müssen. Die Borstennacken zähmen wilde Eber und bilden sie zu Kampfebern aus, die im Kampf gegen uns genutzt werden sollen.\n\nDiese gepanzerten Kampfeber wurden ohne Hoffnung auf jegliche Erholung gequält und missbraucht. Sie müssen getötet werden, im Namen unserer Sicherheit und ihres Friedens. Begebt Euch zu den Pferchen im Süden und tötet die Eber, <Name>. Kehrt danach wieder zu mir zurück.", progress = "Ich kann selbst von hier aus noch viele Kampfeber sehen, <Name>. Es müssen noch mehr Eber getötet werden.", completion = "Gute Arbeit, &lt;Name&gt;. Diese Bestien hätten eine größere Bedrohung als die Borstennacken selbst darstellen können, wenn wir uns nicht rechtzeitig um das Problem gekümmert hätten.", rewards = "Vernarbte KampfeberbrustrüstungGeflochtener EberhautgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14460] = {title = "Ritus der Ehre", objective = "Tötet Häuptling Quieker Dornenmantel.", description = "Diese Stacheleber unterstehen Häuptling Quieker Dornenmantel. Er war es, der beim Angriff auf Camp Narache das Leben von Großmutter Falkenwind genommen hat. Nach dieser grauenvollen Tat ist er geflohen und hat sich versteckt, aber wir haben ihn ausfindig gemacht. Er befindet sich westlich von hier in einem garstigen Dornennest und schafft es, alle Kriegerhelden abzuwehren, die wir schicken, um sich seiner anzunehmen.\n\nIhr habt Euch als mutiger Verteidiger unseres Volkes herausgestellt, <Name>. Tötet Dornenmantel und bringt Häuptling Falkenwind seine Mähne, um Großmutter Falkenwind zu ehren!", progress = "Habt Ihr Eure Prüfungen abgeschlossen, Kind?", completion = "&lt;Häuptling Falkenwind hält die Mähne von Dornenmantel über seinen Kopf.&gt;\n\nDer Häuptling der Borstennacken ist gefallen. Der Geist von Großmutter Falkenwind wurde gerächt!", rewards = "Pantoffeln der hohen EhreGürtel des SonnenläufersIhr bekommt:\n\nDornenbeutel"}
MultiLanguageQuestData['de'][14461] = {title = "Futter des Bösen", objective = "Benutzt Adanas Fackel, um alle 3 Tröge im Kriegseberpferch in Flammen zu setzen.", description = "Wir müssen weitaus mehr tun, als nur Eber zu jagen. Der Anblick dieses Landes bereitet Augenschmerzen, und das muss geändert werden.\n\nUm die Kampfeber mit einem ungemeinen Blutdurst zu versehen, werden sie mit rohem Fleisch zwangsernährt. Nehmt diese Fackel und benutzt sie, um die Tröge mit dem Fleisch und dem Blut in Flammen zu setzen.", progress = nil, completion = "Ihr habt nicht nur die Kriegseberpferche gereinigt, sondern auch dieser furchtbaren Entweihung ein Ende gesetzt. Gute Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14462] = {title = "Wo ist mein Kopf?", objective = "Ihr wurdet ausgeschickt, um Euch mit der Goblinattentäterin Slinky Scharfklinge am Fuß des nördlichen Turms von Talrendisspitze zu treffen.", description = "Er ist hier, <Name>. Hauptmann Grunwald ist ein hochrangiger Allianzoffizier aus der Feste Nordwacht. Zweifellos ist er hier, um einen Angriff auf Orgrimmar mit seinen Nachtelfenverbündeten zu koordinieren. Wir haben beobachtet, wie er in den Turm südwestlich von hier gegangen ist. Ich will seinen Kopf, <Klasse>. Ich will ihn zurück nach Nordwacht schicken, um einen Keil zwischen unsere Feinde zu treiben!\n\nIch habe eine Goblinattentäterin, Slinky Scharfklinge, zum Turm geschickt, aber sie ist nicht zurückgekommen. Geht und findet sie. Und bringt mir diesen Kopf!", progress = nil, completion = "Ihr kommt gerade rechtzeitig, &lt;Klasse&gt;. Ich will gerade ein blitzschnelles, Präzisionsattentat verüben. Mal sehen...\n\nSprengstoff? Ist da.\n\nPneumatische Enterhaken? Sind da.\n\nTragbarer Fallschirm? Ist da.\n\nLähmendes Nervengift?\n\n\n\nAufgetragen. Dann mal los!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14463] = {title = "Pferde für Dämmerhafen", objective = "Sprecht mit Gwen Armstead in Dämmerhafen.", description = "Die Pferde gerettet zu haben, könnte bedeuten, dass auch die Stadt gerettet ist. Es gibt zwar ausreichend Karren in Dämmerhafen, aber nicht genügend Pferde, um sie zu ziehen.\n\nGeht und sagt Bürgermeisterin Armstead, dass die Pferde, die Ihr gerettet habt, zu ihrer Verfügung stehen.\n\nIch bereite alles vor und stoße dann bald zu Euch.", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Ich denke, ich spreche für alle, wenn ich sage: Je früher wir hier herauskommen, desto besser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14464] = {title = "Blitzschnelles Attentat", objective = "Sprecht mit Slinky Scharfklinge, um auf den Turm zu klettern und Hauptmann Grunwald zu töten. Holt Hauptmann Grunwalds Kopf.", description = "Am Fuß des Turms patrouillieren Elitewachen des Hauptmanns. Also wir machen das so: Wir hangeln uns mit den Enterhaken bis nach oben, schnetzeln die VIPs und machen uns mit meinem tragbaren Tiefflugfallschirm davon. Ich werde den Turm mit Sprengstoff spicken, damit er hinter uns explodiert. Ihr stellt sicher, dass Ihr Hauptmann Grunwalds Kopf für Chawg mitbringt. Kapiert?\n\nIhr dürft diese Mission nur DANN annehmen, wenn Ihr zu UNGEBREMSTER GEMEINHEIT fähig seid. Ist das klar?", progress = "Ich gehe davon aus, dass Ihr gute Nachrichten habt, <Name>?", completion = "Ich bin von der Schlauheit unserer neuen Goblinverbündeten beeindruckt, aber Ihr habt mich noch mehr beeindruckt, &lt;Name&gt;. Schaut Euch den entsetzten Ausdruck an, der auf dem Gesicht des Hauptmanns eingefroren ist! Er hat Euren Angriff nicht kommen sehen. Stellt Euch die Angst vor, die das in Nordwacht hervorrufen wird, wenn sie sehen, was einem ihrer geschätzten Offiziere in den Ländern der Nachtelfen geschehen ist.\n\nGut gemacht, &lt;Klasse&gt;. Unser Angriff geht weiter...", rewards = "Handschuhe der uneingeschränktenTiefflugfallschirmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14465] = {title = "Zum Graumähnenanwesen", objective = "Sprecht mit Königin Mia Graumähne im Graumähnenanwesen.", description = "Es ist an der Zeit, alle in Sicherheit zu bringen. Das gilt auch für Euch, <Name>. Begebt Euch zum Graumähnenanwesen. Die anderen werden Euch in Kürze folgen.\n\nMacht Euch um mich keine Sorgen. Ich kümmere mich darum, dass alle heil hier rauskommen. Ja, sogar die paar Wilden, die wir in den Ställen eingesperrt haben.\n\nSobald Ihr dort angekommen seid, sprecht mit Königin Graumähne über die Dringlichkeit der Lage.", progress = nil, completion = "&lt;Name&gt;. Ich habe schon so viel von Euch gehört.\n\nWie ich hörte habt Ihr beim Überleben meiner Familie während des Ausbruchs in Gilneas eine wichtige Rolle gespielt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Bind to Greymane Manor\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14466] = {title = "Das Observatorium des Königs", objective = "Sprecht mit König Genn Graumähne im Observatorium des Graumähnenanwesens.", description = "Ihr solltet mit Genn sprechen. Seit dieses Martyrium begonnen hat, hat er sich in seinem Observatorium eingeschlossen.\n\nIch bin mir sicher, dass er an einem Plan für sein Volk arbeitet. Er ist ein sehr eigensinniger Zeitgenosse.", progress = nil, completion = "Da seid Ihr ja, &lt;Name&gt;. Ich habe Euch erwartet.\n\nIch habe von Eurer Genesung gehört und… Wartet! Spürt Ihr das?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCataclysm Forcecast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14467] = {title = "Oh weh, Gilneas!", objective = "Schaut, <Name>! Schaut nur, was aus Dämmerhafen geworden ist!\n\nSchaut, was aus dem letzten sicheren Ort in Gilneas geworden ist!", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGilneas Test Telescope\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14468] = {title = "Noch ein warmer Körper", objective = "Meldet Euch bei Kommandant Molotov am Einsamen Grat.", description = "Oh, ich habe ein tolles Angebot für Euch! Taucht ein in fremde Kulturen, genießt epische Abenteuer, sprengt Dinge in die Luft und lasst Euch dafür auch noch bezahlen! Klingt zu gut, um wahr zu sein? Tja, ist es aber! Genau das tun wir!\n\nWenn Ihr Interesse habt, meldet Euch bei Gallywix' Verteidigungsposten am Einsamen Grat im Norden und haltet nach Kommandant Molotov Ausschau.", progress = nil, completion = "Der neuste Rekrut, was?\n\nIch fasse mich kurz. Wir wurden angeheuert, um die Naga in den Ruinen von Gallywix und seinem Eigentum fern zu halten. Ihr tut, was wir Euch sagen und ich sorge dafür, dass man Euch am Ende dafür entlohnt.\n\nWillkommen im Bilgewässer Bataillon.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14469] = {title = "Aus zweiter Hand", objective = "Beschafft Euch 12 Militärversorgungspacks vom mittleren Minenfeld.", description = "Zunächst brauchen wir mehr Vorräte für Euch und die anderen neuen Rekruten. Unser letzter Schwung Rekruten, oder besser gesagt ihre Leichen auf dem Minenfeld im Norden, haben noch taugliche Standardversorgungspacks bei sich.\n\nMacht nicht den gleichen Fehler wie sie. Versucht, den Minen auszuweichen.", progress = "An wiederverwerteten Dingen ist nichts auszusetzen.", completion = "Ihr seid ein ganz gewandtes Schlitzohr, was? Gute Arbeit.\n\nHier habt Ihr ein bisschen was, was Euch am Leben halten soll.", rewards = "Ihr bekommt:\n\nMolotovcocktail"}
MultiLanguageQuestData['de'][14470] = {title = "Militärischer Durchbruch", objective = "Tötet Kriegsherr Krellian und beschafft Euch die BGG.", description = "Wir haben den Kontakt zu Unteroffizier Dynamo verloren, der am nächsten Grat nördlich des mittleren Minenfelds stationiert ist. Wahrscheinlich wurden er und seine Leute überrannt.\n\nEr hatte unsere letzte BGG. Geht zu ihm und holt sie zurück. Löscht alle Naga aus, die unsere Linien durchbrochen haben.", progress = "Wo ist mein Raketenwerfer, Rekrut?", completion = "Gute und schnelle Arbeit, Rekrut.\n\nIst sie nicht eine Schönheit? Ich habe sie selbst zusammengebaut. Und ich habe ganz besondere Pläne für dieses Schätzchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14471] = {title = "Mörser ersten Grades", objective = "Benutzt einen Goblinmörser, um 60 Angreifer der Grollflossen zu töten.", description = "He Kumpel! Mögt Ihr Explosionen? Natürlich tut Ihr das. Wie kann man Explosionen auch nicht mögen?!\n\nIch habe am Grat Mörser aufstellen lassen, um die Naga zurückzuhalten. Los, Rekrut! Mörsert sie… Mörsert sie alle! Ahahaha!", progress = nil, completion = "Kaum zu glauben, dass sie uns dafür auch noch BEZAHLEN!", rewards = "KabummgamaschenMörserschleuderergürtelSalvoschusstunikaIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14472] = {title = "Dahin, wo es weh tut!", objective = "Benutzt eine BGG, um einen versklavten Sohn von Arkkoroc auf dem südlichen Minenfeld zu töten.", description = "Die Naga bringen diese Riesen dazu, Pfade durch unsere Minenfelder zu trampeln. Es ist Zeit, unsere BGG einzusetzen!\n\nBegebt Euch zum Eingang des südlichen Minenfelds. Den Rest könnt Ihr Euch sicher denken.", progress = nil, completion = "BÄMM! Mitten ins Gesicht! Guter Schuss, Kleiner!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14473] = {title = "Jetzt ist es unser Problem", objective = "Tötet 6 Teraptorjunge.", description = "Sieht aus, als würden diese Affen einfach alles stehlen, was nicht niet- und nagelfest ist! Diese diebischen kleinen Monster haben die Teraptormatriarchin zur Weißglut gebracht, indem sie ihre Eier gestohlen haben. Aber was noch schlimmer ist: Die Eier sind geschlüpft! Jetzt rennen hier überall hungrige Teraptorjunge herum und haben uns als schnelle Mahlzeit auserkoren!\n\nWir haben nicht damit angefangen, aber jetzt ist es unser Problem. Ihr müsst in den Dschungel gehen und diese hungrigen Teraptorjungen töten, bevor sie uns alle töten.", progress = nil, completion = "Hoffen wir einfach mal, dass wir uns später nicht mit ihrer Mama auseinandersetzen müssen. Das wäre alles andere als gut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14474] = {title = "Rettungskapseln der Goblins", objective = "Rettet 6 überlebende Goblins.", description = "<Name>, es tut mir leid. Ich dachte, Ihr wärt tot!\n\nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.\n\nWir müssen unsere Brüder und Schwestern retten.\n\n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>\n\nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer schwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.\n\nLasst Sassy wissen, dass ich gleich losschwimme.", progress = nil, completion = "Oh, dem Himmel sei Dank, dass Ihr überlebt habt, &lt;Name&gt;! Ich war mir so sicher, dass Ihr ertrunken seid, nachdem ich Euch über Bord habe gehen sehen.\n\n\n\nSchaut nur, wie viele Leute Ihr gerettet habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14475] = {title = "Gestrandet!", objective = "Findet Bombardierhauptmann Smooks im südlichsten Nachtelfenturm bei der Talrendisspitze.", description = "Seht Ihr ein Problem mit diesen Windreitern, <Name>? Sie reiten nicht auf dem Wind! Jeder Flug, den ich aussende, wird von diesen Nachtelfenheckenschützen abgeschossen.\n\nScharfschützen aus Talrendis haben sich im südlichsten Turm vor den Bergen verschanzt. Ich hab einen dieser kleinen Goblinanfänger losgeschickt, damit er sich um den Turm kümmert, aber ich habe kein Wort von ihm gehört. Geht und findet Bombardierhauptmann Smooks und macht ihm gehörig Dampf!", progress = nil, completion = "Endlich Verstärkung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14476] = {title = "Verkabelt zum großen Knall", objective = "Macht die drei Sprengladungen, die um den Fuß des südlichsten Turms an der Talrendisspitze angebracht sind, scharf.", description = "Dieser Turm war nicht in der Reichweite der Kanonen, also dachte ich, wir lassen ihn auf die altmodische Art in die Luft fliegen - höchstpersönlich. Wir haben die Sprengsätze alle angebracht, aber die Wachen haben uns zurückgeschlagen, bevor wir die Zünder scharfmachen konnten.\n\n<Name>! Geht dort hinauf und macht die drei Zünder scharf, die wir am Fuß des Turms platziert haben. Die Dinger sind per Kabel mit einem Satz Thermalbomben verbunden, die ich an der tragenden Wand angebracht habe... Das wird ein Spektakel!", progress = "Habt Ihr sie? Habt Ihr alle drei erwischt?", completion = "Klasse. Dann wollen wir diesen Bananenstand mal anzünden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14477] = {title = "Drückt auf den Knopf!", objective = "Zündet die Sprengladungen!", description = "Lass mich die Verbindungen überprüfen... alles klar. Bitte, Ihr habt die Ehre, <Name>. Drückt drauf. Drückt auf den Knopf!\n\nDrückt auf den Knopf, <Name>!\n\nNach dem Feuerwerk geht zu Kroum in Valormok und sagt ihm, dass der Himmel sauber ist.\n\nDrückt auf den Knopf!", progress = "Wie sieht's aus, <Name>? Blauer Himmel?", completion = "Ja, lasst sie brennen! Lasst sie die Nacht erleuchten und ihr brennender Turm soll das Schlachtfeld unter uns erleuchten während wir Entsetzen über sie bringen.\n\nIch danke Euch, &lt;Name&gt;. Bleibt in meiner Nähe: der Einmarsch steht kurz bevor...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHeckenschützenbandDetonationsringKroums Signet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][14478] = {title = "Operation Ausnehmer", objective = "Meldet Euch bei Kommandant Molotov unter der Hauptkanone im Bilgewasserhafen zum Dienst.", description = "Das Bilgewasserbataillon sucht derzeit nach neuen Rekruten für OPERATION AUSNEHMER.\n\nDer Sold besteht aus einer Goldmünze für alle Soldaten, die am Ende der Operation unbescholten sind. Im Falle des Ablebens erlischt jeglicher Anspruch auf eine Bezahlung. Für alle im Rahmen der Mission durchgeführten Wiederbelebungen wird eine Gebühr von 20 Silberstücken erhoben.\n\nAlle Rekruten sollen sich umgehend bei Kommandant Molotov unter der Hauptkanone melden.", progress = nil, completion = "Willkommen zurück zum Dienst, Soldat. Schön, dass Ihr wieder da seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14479] = {title = "Es gibt viele andere", objective = "Nehmt eine Rakete zum Strand der Trümmer und meldet Euch dann bei Leutnant Drex zum Dienst.", description = "Genug geredet. Schwingt die Beine und ab auf eine Rakete, Soldat!\n\nUnd vergesst nicht: Wenn Ihr tot seid, werdet Ihr nicht bezahlt!", progress = nil, completion = "Holprige Reise gehabt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14480] = {title = "Auslöschung", objective = "Tötet 30 Naga der Grollflossen in den Ruinen von Eldarath.", description = "Wir schicken Euch dort hinein, um diese Nagaplage auszurotten. Der Gebrauch von Waffen wurde genehmigt.\n\nDer Goblintrupp unterstützt Euch bei dieser Mission, also sollte es ein Kinderspiel werden.", progress = nil, completion = "Euer Name spricht sich herum… Ihr seid fast schon so berüchtigt wie der Goblintrupp. Ihr seid ein ganz Harter.", rewards = "Schild des Ehrenmitglieds des GoblintruppsSchraubgesellengürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14482] = {title = "Die Pflicht ruft", objective = "Fahrt mit dem Söldnerboot zur Schlacht.", description = "<Bürger/Bürgerin>!\n\nWie Ihr vielleicht gehört habt, greift uns die Horde vor der Küste an. Die Schlacht ist heftig und unerbittlich.\n\nWir brauchen jeden Tauglichen, um die Feinde zurückzuschlagen!\n\nMeldet Euch unverzüglich am nördlichsten Dock, um zur Schlacht transportiert zu werden.\n\nOh und unsere offiziellen Schlachtschiffe sind... nun ja, etwas später dran als geplant. Macht Euch aber keine Sorgen, wir haben Söldnerschiffe angeheuert, die in der Zwischenzeit reichen sollten.\n\nBeeilt Euch jetzt, <Klasse>. Sturmwind braucht Euch!", progress = nil, completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Phase Binding\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14483] = {title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", objective = "Bringt die vergilbte schöne Grußkarte zu Detektiv Snap Schnappbolz in Orgrimmar.", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr da?\n\nOh, hey, das ist was Großes. Was richtig Großes. Die ganzen verrückten Details auf einem Haufen. Danke - Ihr habt uns hier echt geholfen. Es war schön, mit Euch zu arbeiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14484] = {title = "Kopf der Schlange", objective = "Tötet Lord Kassarus im Tempel von Zin-Malor.", description = "Im Offizierslager hat man uns beigebracht, immer den Kopf der Schlange abzuschlagen. Angesichts der Tatsache, dass wir nie irgendwelche Schlangen gefunden haben, schien das ein ganz schön blöder Rat zu sein. Aber jetzt ergibt alles einen Sinn.\n\nBringt Eure Männer dorthin und tötet Lord Kassarus.", progress = nil, completion = "Ich bin froh, dass Ihr auf unserer Seite kämpft, Soldat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14485] = {title = "Wir brauchen Ticker", objective = "Bringt Ticker in die Ruinen und gebt ihm Deckung, während er Bomben an 3 der Runensteine der Grollflossen anbringt.", description = "Unser bester Sprengstoffexperte Ticker ist zusammen mit dem Goblintrupp in einer Mission unterwegs. Er hat WEIT mehr als genug Sprengstoff für alle Runensteine in den Ruinen dabei.\n\nIhr müsst ihm nur Deckung geben. Den Rest erledigt er.", progress = nil, completion = "Wir hoffen, dass wir damit eine ihrer größten Magiequellen abschneiden können. Die Wahrheit ist, dass wir es nicht genau wissen. Aber wer kann schon einer Gelegenheit widerstehen, etwas in die Luft zu jagen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14486] = {title = "Die Ware anfassen", objective = "Sammelt 12 Tafeln der Hochgeborenen aus den Ruinen von Eldarath.", description = "He da, Kumpel! Wollt Ihr schnell ein paar Münzen verdienen?\n\nBringt mir alle Tafeln der Hochgeborenen, die Ihr in den Ruinen finden könnt.", progress = "Die Blutelfen verschlingen diese Tafeln. Pures Geld!", completion = "Ausgezeichnet. Hier ist Eurer Anteil.\n\nSchön, mit Euch Geschäfte zu machen.", rewards = "EldarathstabGamaschen des schnellen GeldesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][14487] = {title = "Noch schlagendes Herz", objective = "Beschafft Euch das Herz von Arkkoroc aus der Mitte der Ruinen von Eldarath.", description = "Kommandant Molotov hat im Geheimlabor einen Käufer für das Artefakt gefunden, das Ihr für mich ausgespäht habt.\n\nZweifellos befindet es sich noch immer in der Mitte der Ruinen bei der Hohepriesterin, wo Ihr es gefunden habt. Bringt es unbeschadet her, <Soldat/Soldatin>!", progress = "Ich liebe es, wenn die Leute unschätzbar wertvolle Artefakte einfach herumliegen lassen.", completion = "Haha! Es ist RIESIG!\n\nWir müssen es gleich zu Onkel Tollhaus bringen, sobald wir hier alles aufgeräumt haben und abmarschbereit sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14488] = {title = "Zustellung", objective = "Stellt Apotheker Hummel auf Burg Schattenfang die Vorladung bei Gericht zu.", description = "Ihr habt es geschafft? Gut. Ich habe schon auf Hilfe gewartet. Jetzt ist die beste Zeit, zu handeln.\n\nNehmt dieses Paket und begebt Euch noch tiefer hinein, um Hummel, dem Leiter dieser dreckigen Chemiemanufaktur, ein paar Dokumente zuzustellen. Das Dokument ist hier drin, zusammen mit einer kleinen Hilfe, falls sie irgendwelche chemischen Überraschungen für Euch bereithalten. Verwendet einen der Neutralisatoren, wenn es soweit kommt, okay?", progress = "Ich kann mich nicht erinnern, einen Reinigungsdienst bestellt zu haben... aber ja, ich bin Apotheker Hummel.\n\n...Moment mal, was hat das alles zu bedeuten? Glaubt Ihr etwa, diese bedeutungslosen Papiere könnten mich aufhalten? Pah!", completion = "Was wir hier tun, hat Euch nicht zu interessieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][14491] = {title = "Ruhelose Erde", objective = "Benutzt die Trommel der besänftigten Erde, um 6 aufgebrachte Erdgeister zu beruhigen.", description = "Bis vor Kurzem schürfte eine Gruppe von Zwergen, die hier eingefallen war, rücksichtslos in unseren Ländern im Westen auf der Suche nach Schätzen. Als die Erde brach, stiegen die Erdgeister des missbrauchten Landes auf und übten Rache an den Zwergen.\n\nDie aufgebrachten Erdgeister suchen die alte Ausgrabungsstätte noch immer heim, <Name>. Wir müssen sie beschwichtigen.\n\nNehmt diese Trommel mit Euch nach Westen und trommelt für die Geister. Der Rhythmus sollte ihre Wut und Verwirrung schlichten.", progress = nil, completion = "Das Land ist eindeutig noch immer in Aufruhr, wenn es so schwierig war, die Erdgeister zu beruhigen.\n\nEines sollte Euch in Erinnerung bleiben, &lt;Name&gt;. Vergesst nie das Schicksal, das jene ereilt, die der Erdenmutter Schmerzen zufügen.", rewards = "Rastlose HandschuheBrustschutz der schlagenden TrommelAbgenutzer zeremonieller TomahawkIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][20438] = {title = "Eine passende Verkleidung", objective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", description = "Euch ins Innere von Sonnenhäschers Zuflucht zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock der Sonnenhäscher verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", progress = "Konnte Shandy Euch dabei helfen, an einen Wappenrock der Sonnenhäscher heranzukommen?", completion = "Ich wusste, dass Shandy für uns einen Weg finden würde, hindurchzukommen. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Je eher Ihr den Wappenrock nicht mehr braucht, um so schneller können wir ihn Shandy zurückgeben und um so höher wird unsere Chance sein, dass sein Besitzer ihn niemals vermissen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][20439] = {title = "Ein Treffen mit dem Magister", objective = "Besorgt den Folianten \"Uralte drachengeschmiedete Klingen\" von Magister Hathorel.", description = "Ich habe eine Verzauberung auf den Wappenrock gelegt, die es Euch erlauben sollte, einen kurzen Augenblick lang unentdeckt an den Verteidigungsvorkehrungen der Zuflucht der Sonnenhäscher vorbeizukommen. Das sollte Euch genug Zeit geben, das Rattenloch zu betreten und Euch dort mit unserem Kontakt bei den Sonnenhäschern, einem gewissen Magister Hathorel, zu treffen.\n\nBesorgt Euch die Kopie von \"Uralte drachengeschmiedete Klingen\", die seine Männer aus Wyrmruh entliehen haben, solange Eure Verkleidung anhält, und kehrt zu mir zurück.", progress = "Habt Ihr das Buch besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Caladis Prunkspeer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände der Sonnenhäscher gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe reichlich belohnt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][20440] = {title = "Vergiftetes Wasser", objective = "Sammelt 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", description = "Unsere heiligen Brunnen wurden besudelt und ich werde Eure Hilfe brauchen, um das wieder in Ordnung zu bringen.\n\nUm alle Brunnen zu säubern, muss ich ein Läuterungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.\n\nZuerst werden wir ein Läuterungstotem für den Brunnen der Winterhufe herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und ausgewachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.\n\nKehrt mit den Tatzen und Krallen zu mir zurück, <Name>.", progress = "Habt Ihr die Tatzen und die Krallen, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ich werde ihre Macht jetzt an ein Totem der Läuterung binden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][20441] = {title = "Ritus der Vision", objective = "Trinkt vor dem Stammesfeuer im Dorf der Bluthufe das Wasser der Vision.", description = "Stellt sicher, dass Ihr bereit seid, um das Dorf der Bluthufe zu verlassen, <Name>. Der nächste Schritt Eurer Reise wird Euch an weit entfernte Orte führen.\n\nEuer Weg führt Euch über die Felder von Mulgore, und die Erdenmutter wird jederzeit über Euch wachen. Wenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, werden sich Eure Augen öffnen, und die Geister werden Euch begleiten.", progress = nil, completion = "Habt keine Angst, &lt;Name&gt;. Ihr habt den Ritus der Vision erfolgreich bestanden.", rewards = "Weste der ErdenmutterRegenwandlerarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][23733] = {title = "Riten der Erdenmutter", objective = "Sprecht mit Dyami Windsegler oben auf der Horizontmesa.", description = "Heute habt Ihr ein Ritual absolviert, das weitaus schwieriger war, als wir es normalerweise von jungen Tauren erwarten. Seid stolz. Es ist nun an der Zeit, Eure Reise fortzusetzen.\n\nWestlich von hier, hinter der Begräbnisstätte, werdet Ihr einen Pfad finden, der zur Ebene führt. Folgt diesem Pfad und sprecht mit Dyami Windsegler.\n\nGeht mit der Erdenmutter. Ihr werdet hier immer willkommen sein.", progress = nil, completion = "Wenn Ihr bereit seid, Camp Narache hinter Euch zu lassen, so werde ich die Geister rufen, um Euch auf Eurem Weg zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24215] = {title = "Ritus des Winds", objective = "Trinkt das Wasser der Vision.\n\nBereitgestellter Gegenstand: \n", description = "Seht, <Name>. Die Wogenden Ebenen Mulgores erstrecken sich vor Euch: unsere Heimat, die Wiege der Erdenmutter. Hier versorgt sie uns mit allem, was wir je brauchen, in einem friedlichen und grünen Land. Zum Schutz dieses Landes werdet Ihr kämpfen.\n\nEure Reise wird Euch weitab von den schützenden Armen der Heimat führen, zu den am weitesten entfernten und schrecklichsten Gegenden der Welt, und noch weiter.\n\nUnter uns könnt Ihr das Dorf der Bluthufe sehen. Hier beginnt der erste Schritt auf Eurem wahren Weg. Trinkt von dem Wasser der Vision und lasst die Geister Euch den Weg zeigen.", progress = nil, completion = "Willkommen im Dorf der Bluthufe. Ich bin froh, dass die Geister Euch einen sicheren Weg gezeigt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24216] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Allianz ist ein heimtückischer Gegner, <Name>. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24217] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Allianz ist ein heimtückischer Gegner, <Name>. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24218] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24219] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24220] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, <Name>. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", progress = nil, completion = "Das sind gute Neuigkeiten, &lt;Klasse&gt;! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24221] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, <Klasse>! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24223] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, <Name>. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24224] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24225] = {title = "Ruf zu den Waffen: Kriegshymnenschlucht", objective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Die Allianz ist ein heimtückischer Gegner, <Name>. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24226] = {title = "Ruf zu den Waffen: Arathibecken", objective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, <Klasse>! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24426] = {title = "Ruf zu den Waffen: Alteractal", objective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, <Name>. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24427] = {title = "Ruf zu den Waffen: Alteractal", objective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, <Name>, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", progress = nil, completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24428] = {title = "Ein höchst merkwürdiger Umstand", objective = "Bringt Onyxias Kopf zu Zardeth der Schwarzen Klaue im Keller des Geschlachteten Lamms.", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Zardeth der Schwarzen Klaue.", progress = "Bei Nozdormus Zähnen!", completion = "Was? Wie seid Ihr an diesen Kopf gekommen? Ist sie nicht... Nein, die Details sind nicht wichtig vermute ich. Ihr werdet unzweifelhaft ein wenig von diesem Tand als Vergütung erwarten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPoliertes DrachentötersignetFunkelnder Zahn OnyxiasGeläuterter Talisman mit Onyxiablut\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24429] = {title = "Ein höchst merkwürdiger Umstand", objective = "Bringt Onyxias Kopf zu Neeru Feuerklinge in der Kluft der Schatten.", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Neeru Feuerklinge.", progress = "Was hat das zu bedeuten?!", completion = "Ihr habt mir das Haupt von jemandem gebracht, der... Nein, es wäre das Beste, nicht zu viel darüber nachzudenken. Ihr werdet unzweifelhaft eine Vergütung für Eure Heldentaten erwarten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPoliertes DrachentötersignetFunkelnder Zahn OnyxiasGeläuterter Talisman mit Onyxiablut\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24430] = {title = "Den Himmel schwärzen", objective = "Besteigt einen gestrandeten Windreiter und fliegt über die Talrendisspitze. Zerstört 6 Glevenschleudern der Talrendisspitze und bombardiert die Kommandozentrale.", description = "<Name>! Helft uns hier mal, ja? Gorsch hier hat schlechte Erfahrungen mit dem 'Iss-so-viel-du-kannst' Meeresfrüchteladen in der Stadt gemacht und jetzt fehlt uns ein Pilot.\n\nIch sollte diese Glevenschleudern der Elfen unbrauchbar machen, bevor sie unsere Lufteinheiten zu Konfetti verarbeiten. Setzt Euch auf diesen Windreiter und schwingt Euch in die Lüfte! Einer meiner Bombardierkumpels wird mit Euch kommen und die Ziele auf Euer Kommando bombardieren.\n\nUnd ach ja! Werft eine Bombe genau auf die Kommandozentrale der Nachtelfen - das große Gebäude im Süden neben der Brücke. Großartig!", progress = "Noch mehr Bomben. Noch mehr Bomben!", completion = "Oh ja! Ich liebe den Geruch von frischen Bombenkratern im Schmutz!\n\nMan munkelt im Lager, dass die Frontlinie der Elfen in Richtung Fluss zursammenbricht. Redet mit Chawg und findet heraus, ob Ihr irgendwie helfen könnt, die Sache zu beenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24431] = {title = "Durchnässtes Rezept", objective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", progress = "\"Wein ist nur so fein, wie derjenige, der ihn trinkt\", sag ich immer.", completion = "Das ist ein ziemlicher Fund, &lt;Name&gt;. Ich kann Euch nicht erlauben, das an irgendwen anderen zu verkaufen, also bin ich gewillt, Euch ein großzügiges Angebot zu machen.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][24432] = {title = "Seetauglich", objective = "Erunak im Salzkutter möchte, dass Ihr ihm 3 Salzwasserseesterne und ein Tritonshorn vom Seefahrergrab bringt.", description = "Willkommen im Salzkutter, <Klasse>.\n\nIch bin Erunak, der letzte überlebende Passagier dieses einst stolzen Schiffes.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga greifen unaufhörlich an.\n\nIhr seid an die Bedingungen hier unten nicht ausreichend angepasst, um von großem Nutzen zu sein, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Eure Überlebenschancen deutlich erhöhen wird.", progress = "Schön zu sehen, dass Ihr noch am Leben seid, <Volk>.\n\nHabt Ihr die Dinge gefunden, die ich brauche?", completion = "Bitteschön, &lt;Klasse&gt;. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", rewards = "Ihr erlernt:\n\nSeetauglich\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSeetauglich\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24433] = {title = "Angst, der große Motivator", objective = "Kämpft Euch quer durch Talrendisspitze und tötet 12 Verteidiger der Talrendisspitze und 6 Schildwachen der Talrendisspitze.", description = "Unsere Grunzer sind stark, aber sie zeigen keinerlei Initiative. Sie gehen an den Frontlinien in die direkte Konfrontation. Aber <ein unabhängiger/eine unabhängige:c> <Klasse> wie Ihr - nun jemand wie Ihr könnte sich doch hinter die Linien schleichen und tief hinter den Schanzen der Feinde Chaos und Verwüstung anrichten.\n\nSchlagt eine Schneise der Verwüstung durch das Herz von Talrendis, <Name>! Streckt unsere Feinde in dem Gebiet nieder, das sie als sicher erachten und hinterlasst Blut und Angst.", progress = nil, completion = "Lok'tar ogar, &lt;Name&gt;. Wenn sie die Leichen ihrer Kameraden entdecken, werden sie erkennen, dass man nirgendwo vor dem Zorn der Horde sicher ist und ihr Kampfeswille wird gebrochen sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24434] = {title = "Truppen absetzen", objective = "Tötet 5 Wissenshüter der Talrendisspitze und findet den Beschwörungsstein der Wissenshüter irgendwo in Talrendisspitze.", description = "Spürt Ihr das leichte Beben der hiesigen Leylinien, <Name>? Ich spüre hin und wieder ein Vibrieren, wie nach dem Zupfen einer Saite. Diese Art Resonanz erwarte ich nach einem weitreichenden Beschwörungszauber. Die Wissenshüter an der Talrendisspitze versuchen mit ihrer lächerlich primitiven Magie Verstärkung aus Darnassus herbeizurufen.\n\nDas können wir zu unserem Vorteil nutzen, <Name>. Wenn Ihr ihren Beschwörungsstein beeinflusst, können wir ein Spitzenteam von Kommandosoldaten hinter die feindlichen Linien teleportieren.\n\nFindet den Beschwörungsstein der Talrendisspitze!", progress = nil, completion = "Bilder eines großen, weit entfernten Baums durchfluten Eure Gedanken. Euer Magen krampft sich zusammen während Ihr den Stein neu ausrichtet. Eure Gedanken füllen sich kurz mit Visionen eines feurigen Portals, eines hochaufragenden Bergs, einer kalten Einöde und einer furchtbaren Narbe, die sich über die Erde erstreckt.\n\nKurz darauf beruhigen sich die magischen Energien des Steins und Ihr fühlt Euch nur einen Schritt entfernt von Valormok. Andorels Einmarsch kann beginnen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24435] = {title = "Einmal nass wischen", objective = "Tötet 12 Naga der Grollflossen am Strand der Trümmer.", description = "Es gibt noch viel zu viele Naga an diesem Strand. Sieht aus, als hättet Ihr da ein wenig aufzuwischen, <Junge/Mädel>.", progress = nil, completion = "Da habt Ihr aber schön aufgeräumt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24436] = {title = "Alles Heil kommt von oben", objective = "Ruft an den Leichen von 8 verwundeten Soldaten am Strand der Trümmer einen fliegenden Priester herbei.", description = "Am Strand liegen eine Menge \"Soldaten\", die versuchen, durch den Tod ihren Pflichten zu entfliehen. Findet diese Faulpelze und ruft mit der Leuchtpistole einen Priester herbei, der sich der Lage annimmt.\n\nUnsere Männer sollen ja nicht glauben, dass sie so leicht ausmustern können.", progress = nil, completion = "Gute Arbeit, Junge. Wir kriegen diesen Strand im Handumdrehen wieder sauber.", rewards = "WegwerfmantelHorts AxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24437] = {title = "Wer zuerst kommt, mahlt zuerst", objective = "Stellt Ruckus' Gebietsanspruchsfahne neben den besten Strandgrundstücken am Strand der Trümmer auf.", description = "Am Strand entlang gibt es einige wunderschöne Gebäude, die sich perfekt als Strandhäuschen eignen. Ich könnte sie für das Zehnfache der Reparaturkosten weiterverkaufen.\n\nDie besten Stücke sind die Nagapagode im Süden, der Turm direkt am Wasser und die Ruinen ganz am nördlichen Ende des Strands. Wenn Ihr sie für mich beansprucht, bevor die Kämpfe vorbei sind, werde ich Euch gut belohnen.", progress = nil, completion = "Haha! Ausgezeichnet. Sehr gut gemacht, Junge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24438] = {title = "Exodus", objective = "Geht an Bord eines Karrens unterhalb des Graumähnenanwesens.", description = "Wir haben keine Wahl, <Name>. Wir müssen weiter ins Landesinnere.\n\nEs gefällt mir zwar überhaupt nicht, aber hier sind wir verwundbar.\n\nKehrt zu den Ställen unterhalb des Anwesens zurück. Lasst uns alle Mann auf Karren verfrachten und ostwärts schicken. Ich hoffe nur, es ist noch nicht zu spät.", progress = nil, completion = "Danke, dass Ihr angehalten habt, &lt;Name&gt;. Unseren Karren hat es ziemlich übel erwischt.\n\nAber der vor uns ist noch schlimmer dran.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBind to Stagecoach Crash Site [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24439] = {title = "Die Unterwerfung Azsharas", objective = "Besiegt Kommandant Jarrodenus an der Talrendisspitze und holt Euch seinen Kopf.", description = "<Name>! Habt Ihr den Windreiter gelenkt, der die Kommandozentrale bombardiert hat? Das war ein Volltreffer!\n\nMeine Späher berichten mir, dass Ihr Jarrodenus, den Flugmeister der Nachtelfen der Himmelsjäger und de facto Kommandanten der gegnerischen Truppen schwer verwundet habt.\n\nJetzt ist die Gelegenheit zuzuschlagen - ich habe nicht genug Zeit, um alle zum Angriff zusammenzurufen. Stürmt das Gebäude der Kommandozentrale und tötet Kommandant Jarrodenus bevor seine Verstärkung eintrifft. Bringt mir seinen Kopf - und Azshara gehört uns!", progress = "Brüllt Jarrodenus immer noch Befehle oder habt Ihr ihn von der Last seines Kopfes befreit?", completion = "...dann ist es vollbracht!\n\n&lt;Chawg beobachtet das Schlachtfeld.&gt;\n\nEs befinden sich immer noch vereinzelte Widerstandsnester um unser Lager herum, aber diese Rückzugsgefechte scheinen einen großangelegten Rückzug nach Eschental zu verschleiern. Azshara gehört uns!\n\nDer Kriegshäuptling wird von diesem Sieg und Eurem Anteil daran hören. Aber wir werden sicherlich die Hilfe eines &lt;Klasse&gt; wie Euch anderswo benötigen. Vergesst nicht, mit Kroum hier im Lager zu sprechen, bevor Ihr aufbrecht.", rewards = "Schild der Eroberung von AzsharaSchild der TalrendisspitzeZauberstab des WindreitersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24440] = {title = "Winterhufsäuberung", objective = "Benutzt das Läuterungstotem der Winterhufe beim Brunnen der Winterhufe.", description = "Ich habe das Totem angefertigt, um den Brunnen der Winterhufe zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet den Brunnen im Südosten, aber nehmt Euch in Acht. Wer auch immer für diese Schandtat verantwortlich war, wird dort eventuell auf der Lauer liegen.\n\nEs kann sein, dass diese Aufgabe sehr schwierig ist, <Name>. Seid vorsichtig, und lasst diejenigen, die unseren Brunnen entweiht haben, nicht entkommen.", progress = nil, completion = "Die Grimmtotem...\n\n&lt;Mull verzieht das Gesicht.&gt;\n\nIch hatte gehofft, dass meine Tage gezählt sein würden, bis &lt;Volk&gt; andere &lt;Volk&gt; grundlos in den Ländern von Mulgore angreifen. Ihr solltet stolz sein, &lt;Name&gt; - Ihr habt unserem Land und unserem Volk einen guten Dienst geleistet.", rewards = "EbenenjägerarmschützerBeine des langen TagesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24441] = {title = "Totem der Donnerhörner", objective = "Sammelt 6 Pirscherklauen und 6 Pumaklauen.", description = "Es gibt noch mehr zu tun. Wir müssen ein neues Totem erschaffen, um den Brunnen der Donnerhörner zu säubern.\n\nIhr müsst die Klauen der Raubtiere der Mulgoreebene besorgen. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.\n\nIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", progress = "<Name>, habt Ihr die Klauen, die Ihr für mich besorgen solltet? Der Brunnen der Donnerhörner wird von Stunde zu Stunde verseuchter!", completion = "Vielen Dank, &lt;Name&gt;. Die Reinheit, mit der diese Bestien jagen, ist für die Erstellung des Läuterungstotems äußerst wichtig.\n\nDer Brunnen der Donnerhörner ist ein Symbol meines Stamms und das Wissen, dass er von anderen &lt;Volk&gt; verunreinigt wurde, ruft die größte Wut hervor, die ich in Jahren verspürt habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24442] = {title = "Die Schlachtpläne der Kvaldir", objective = "Bergt das Herz der Nebel und bringt es zusammen mit den Angriffsplänen der Kvaldir zu Jusitziarin Mariel Treuherz auf dem Argentumturnierplatz.", description = "Ein Blick auf die erbeuteten Angriffspläne lässt eine Karte von den Östlichen Königreichen und Kalimdor erkennen, auf der die größten Siedlungen markiert sind. Beim Lesen der Befehle erfahrt Ihr, dass die Hauptleute der Kvaldir Pläne für eine Reihe von zerstörerischen Schlachtzügen ausgearbeitet haben.\n\nLaut diesen Befehlen sollen die Angriffe anfangen, nachdem Nebelrufer Yngvar \"das Herz der Nebel befragt hat\". Möglicherweise könnt Ihr die Angriffe ein wenig hinauszögern, indem Ihr das Omen aus der Höhle der Nebelrufer westlich von Hrothgars Landestelle erbeutet und Justiziarin Mariel Treuherz benachrichtigt.", progress = "Was habt Ihr da gefunden, <Name>?", completion = "&lt;Mariel nimmt die Befehle und den erbeuteten Seher-Kristall entgegen und begutachtet beides.&gt;\n\nGute Arbeit, &lt;Name&gt;, und gut mitgedacht. Ich bin mir zwar sicher, dass der Diebstahl dieses Schmuckstücks sie nicht lange aufhalten wird, aber ich glaube, dass Ihr uns Zeit verschafft habt, die Anführer der Horde und der Allianz vor den bevorstehenden Angriffen zu warnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24443] = {title = "Die gefangene Jägerin", objective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Honu Hirschjäger gefangen ist.", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Honu Hirschjäger, eine junge Jägerlehrerin, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Honu!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24444] = {title = "Die gefangene Schamanin", objective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Miira Donnerhuf gefangen ist.", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Miira Donnerhuf, eine junge Schamanenlehrerin, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Miira!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24445] = {title = "Die gefangene Druidin", objective = "Findet Keshu Baumhuf.", description = "Die Verteidigung des Lagers fällt nun den Jüngsten unter uns zu, <Name>, und viele unserer mutigsten Lehrlinge bekämpfen in genau diesem Augenblick die Stacheleber. Ich fürchte um ihre Sicherheit...\n\nBitte, sucht die junge Druidin Keshu Baumhuf östlich von hier, tief im Territorium der Stacheleber. Wenn Ihr sie und andere Lehrlinge lebendig vorfindet, können sie Euch vielleicht helfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24446] = {title = "Der gefangene Sonnenläufer", objective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Bowe Dämmerhorn gefangen ist.", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Bowe Dämmerhorn, einen jungen Sonnenläufer, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Bowe!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMulgore Quilboar Cage Invisibility Cancel\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24448] = {title = "Beförderung", objective = "Meldet Euch bei Hauptmann Tork am Außenposten in den Ruinen von Eldarath.", description = "Kommandant Molotov hat persönlich angeordnet, dass Ihr direkt an unseren Außenposten versetzt werdet. Wir bereiten uns darauf vor, Truppen in die Ruinen zu schicken, um den Naga Einhalt zu gebieten und das Artefakt zurückzuholen. Molotov möchte, dass Ihr eine dieser Truppen anführt.\n\nBegebt Euch in den Nordwesten des Strands und folgt dem Weg nach oben zu unserem Außenposten.", progress = nil, completion = "&lt;Name&gt;! Ihr habt es heil hierher geschafft, gut!\n\nWir haben viele Aufgaben in den Ruinen für Euch, aber wir stellen Euch unsere Besten zur Seite. Ihr arbeitet jetzt mit der ZOGGA-Truppe, die Zasterorientierte Organisation für gewinnbringende Goblin-Akquisen. Molotov ist davon überzeugt, dass Ihr es schafft. Mehr muss ich nicht wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24449] = {title = "Landgang", objective = "Bringt das Herz von Arkkoroc zu Onkel Tollhaus im Bilgewasserhafen.", description = "Für den Augenblick stehen die Dinge gut hier. Es war mir eine Freude, mit Euch zusammenzuarbeiten, Soldat.\n\nWenn Ihr bereit seid, das Artefakt zurückzubringen, könnt Ihr einen Gyrokopter zurück zum Bilgewasserhafen nehmen und es Onkel Tollhaus persönlich geben.", progress = "Ah, der Mann der Stunde!", completion = "Und Ihr habt das Artefakt dabei! Dann war die Mission wohl ein Erfolg. Die Zasterorientierte Organisation für gewinnbringende Goblin-Akquisen kann sich sehen lassen. Dieses Ding bringt sicher ordentlich Knete ein.\n\nUnd Ihr… Ich habe gehört, dass Ihr da unten beeindruckende Arbeit geleistet habt. Wahrscheinlich habt Ihr die Kosten ganz allein um 10% gesenkt. Genau das ist der clevere Geschäftssinn, den ich mir in meiner Armee wünsche!\n\nHier ist Euer versprochener Sold. Und ich habe noch etwas draufgelegt. Ich hoffe, es gefällt Euch.", rewards = "AkolythenarmschienenTollhausflinteHerzwickelFusionsstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24451] = {title = "Eine Audienz mit dem Arkanisten", objective = "Holt den Folianten \"Uralte drachengeschmiedete Klingen\" bei Arkanist Tybalin.", description = "Ich habe den Wappenrock mit einem Zauber belegt, sodass Ihr für kurze Zeit die Verteidigung der Silbernen Enklave umgehen könnt. Das dürfte Euch genügend Zeit verschaffen, um in die obere Ebene der Silbernen Enklave zu gelangen und jemanden vom Silberbund namens Arkanist Tybalin zu treffen.\n\nNutzt Eure Tarnung, um das Exemplar von \"Uralte drachengeschmiedete Klingen\", das seine Leute von Wyrmruh geliehen haben, zu beschaffen und zu mir zu bringen.", progress = "Habt Ihr das Buch vom Wyrmruhtempel besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Myralion Sonnenfeuer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände des Silberbunds gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe entschädigt wird. Sobald sich das Buch in Myralions Händen befindet, stellt der Silberbund keine Bedrohung mehr dar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24452] = {title = "Auf der Suche nach Profit", objective = "Schleicht Euch mit dem Tarnfeldgenerator in die Ruinen von Eldarath und findet das Herz von Arkkoroc.", description = "Die Dinge scheinen sich langsam etwas zu beruhigen. Gallywix blättert sicher weiter Bares hin, damit wir hier draußen bleiben, aber ich glaube, wir können noch ein bisschen mehr aus unserem Deal herausschlagen.\n\nNaga und Meerriesen sind sich normalerweise nicht grün, also müssen die Naga sie irgendwie kontrollieren. Nehmt diesen Tarnfeldgenerator, schleicht Euch in die Ruinen und lasst mich wissen, wenn Ihr etwas von Wert findet.", progress = "Schon zurück?", completion = "Haha! Sehr gut. Damit bringe ich die Sache ins Rollen. Jetzt brauche ich nur noch einen Käufer und die Genehmigung von Onkel Tollhaus.\n\nHier ist der Lohn für Eure Arbeit. Tolle Leistung, Soldat!", rewards = "MolotowhandschuheKostspielige ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24453] = {title = "Ein Gespräch unter Gefreiten", objective = "Sprecht mit Gefreiter Worcester am Umschlagplatz der Raketenbahn von Orgrimmar.", description = "Hört mal… ein letzter Gefallen, bevor Ihr Euch vom Acker macht.\n\nGefreiter Worcester ist immer noch an diesem Turm und \"rekrutiert\". Lasst ihn wissen, dass wir bereit sind, zusammenzupacken.\n\nEs war mir eine Ehre, mit Euch zu arbeiten, Rekrut.", progress = nil, completion = "Was?! Ich habe gar nichts von der Mission mitbekommen? Im Ernst?\n\nNa gut, na gut… Ihr überbringt ja nur die Nachricht. Vielen Dank, Kumpel. Vielleicht sehen wir uns ja mal wieder in der Stadt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24454] = {title = "Kehrt zu Caladis Prunkspeer zurück", objective = "Bringt \"Uralte drachengeschmiedete Klingen\" zu Caladis Prunkspeer nach Quel'Delars Ruh.", description = "Wir müssen dieses Buch umgehend zu Caladis Prunkspeer bringen. Würdet Ihr das tun? Ich kann mich auf niemand anderen verlassen, das Buch zu transportieren, und Ihr habt Euch geschickt darin erwiesen, die Sonnenhäscher auf Abstand zu halten.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Caladis und das Schwert werden auf Euch warten. Je eher wir die Klinge identifizieren, desto eher können wir Anspruch darauf erheben.", progress = "Wir haben Eure Rückkehr erwartet. Was hat Euch zurückgehalten?", completion = "&lt;Caladis nimmt das schwere Buch entgegen und fängt an es durchzublättern.&gt;\n\nIch wusste, dass mir die Symbole auf der Klinge bekannt vorkamen. Die Waffe wurde ganz bestimmt von den Drachen geschmiedet und als Geschenk an eine der sterblichen Rassen übergeben. Aber welche Klinge soll das sein und wie kommt es, dass sie in Eiskrone ruht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24455] = {title = "Schnelle Entsendung", objective = "Meldet Euch bei Hauptmann Desoto im Bilgewasserhafen, um entsendet zu werden.", description = "Ihr meldet Euch sofort zum Dienst. Hauptmann Desoto überwacht die Entsendung der Truppen an der Rampe der Raketenstartstation.\n\nMacht uns reich, Soldat! Weggetreten!", progress = nil, completion = "Schön Euch zu treffen, Soldat. Kommandant Molotov lobt Euch in höchsten Tönen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24456] = {title = "Donnerhornsäuberung", objective = "Benutzt das Läuterungstotem der Donnerhörner beim Brunnen der Donnerhörner.", description = "Der Stamm der Grimmtotem glaubt, dass Kalimdor alleine den Tauren gehören sollte. Ihr Hass und Ärger füllen sie mit einem korrumpierenden Durst nach Macht. Magatha, ihre Anführerin, hat den Oberhäuptling Cairne Bluthuf selbst vergiftet, in einem Versuch, die Macht über Donnerfels zu erlangen. Sie wurde besiegt und die Grimmtotem ins Exil geschickt.\n\nJetzt scheinen sie Mulgore in die Verderbnis führen zu wollen, bevor sie diese Ländereien für immer verlassen müssen. Schnell, <Name>, begebt Euch zum Brunnen der Donnerhörner nördlich von hier und führt das Ritual aus!", progress = nil, completion = "Ihr habt sowohl mir als auch meinen Vorfahren heute einen großen Gefallen getan. Bitte, nehmt dies als Zeichen meiner Dankbarkeit.", rewards = "DonnerhornhandschuheBerührung der DämmerungBluthufkriegsschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24457] = {title = "Ritus der Vision", objective = "Sprecht mit Zarlman Zwillingsmond im Dorf der Bluthufe.", description = "Ich kann Euch gar nicht genug für die Säuberung des Brunnens unseres Stamms danken, <Name>, und dafür, dass Ihr die wilden Grimmtotem bekämpft habt. Es gibt aber noch mehr zu tun; für Euch ist die Zeit gekommen, Eure Reise außerhalb vom Dorf der Bluthufe fortzusetzen.\n\nSucht Zarlman Zwillingsmond bei den Feuern im Norden des Dorfes aus. Sprecht mit ihm, um mehr von dem nächsten Ritual zu erfahren, das auf Euch zukommt.", progress = nil, completion = "Ich habe bereits mit Eurem Besuch gerechnet, &lt;Klasse&gt;. Ich weiß immer, wer versuchen möchte, die Riten der Erdenmutter zu bestehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24458] = {title = "Tod am Nachmittag", objective = "Liefert den scharfgemachten Azsharitkern bei Bleenik Zischlunte im Bilgewasserhafen ab. Sprecht mit Friz Bodendreh für einen Freiflug.", description = "<Name>, ich habe die gereinigte Probe Azsharit, die Ihr aus dem Labor gerettet habt, waffenfähig gemacht. Wenn meine Berechnungen richtig sind, wird es mit genug Kraft detonieren, um eine Stadt dem Erdboden gleichzumachen.\n\nWenn ich mich irre, könnten wir den Planeten in zwei Hälften reißen.\n\nDie einzige Möglichkeit, das herauszufinden, ist ein Probelauf! Bringt den Azsharitkern zu der Riesenkanone in Bilgewasser und meldet Euch bei Bleenik Zischlunte. Mein Mietpilot Friz Bodendreh hier kann Euch hinbringen.\n\nIch komme nach ... mit Sicherheitsabstand.", progress = "Was habt Ihr denn da - hat Wurfhammer Euch geschickt?", completion = "Oh! Das ist er. Der große Knall.\n\n&lt;Zischlunte ruft seine Arbeiter herbei.&gt;\n\nJungs, es ist soweit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24459] = {title = "Morin Wolkenpirscher", objective = "Findet Morin Wolkenpirscher östlich des Dorfs der Bluthufe.", description = "Ihr habt vielleicht schon einmal etwas von der Venture Company gehört. Sie sind ein \"Kartell\" der Goblins - das ist so etwas Ähnliches wie ein Stamm.\n\nObwohl sich eines dieser Kartelle der Horde angeschlossen hat, ist die Venture Company eigentlich nur der Gier gegenüber loyal. Die gierigen Goblins und ihre Arbeiter haben schon lange versucht, die Rohstoffe und Ressourcen Mulgores auszubeuten - bisher mit wenig Erfolg.\n\nEiner unserer Kundschafter, Morin Wolkenpirscher, hat sich aufgemacht, um die Überreste einer der Karawanen der Goblins zu untersuchen. Wenn Ihr ihm helfen möchtet, müsst Ihr nur der Straße folgen, die aus dem Dorf und nach Osten führt.", progress = nil, completion = "Schön, Euch zu treffen. Wenn Ahmo Euch die Einzelheiten zu dieser Art Goblin schon verraten hat, können wir gleich mit der Arbeit anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24460] = {title = "Außer Betrieb", objective = "Pauls Testquestgeber möchte, dass Ihr Zombies tötet.", description = "Heda <Klasse>, Ich will, das Ihr den Kataklysmus löst. Jagt ein paar Zombies.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24461] = {title = "Das Schwert neu schmieden", objective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und schmiedet damit Quel'Delar neu.", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, obwohl Blutkönigin Lana'thel verkündet hat, es würde nicht gelingen. Zwar muss die Klinge noch getempert werden, doch Lana'thel und ihr Meister werden uns nicht daran hindern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24463] = {title = "Ins Eschental vordringen", objective = "Sprecht mit Kulg Blutspritzer im Eschental.", description = "Obwohl der Abschaum aus Darnassus sich aus Azshara zurückgezogen hat, bekomme ich immer noch widersprüchliche Meldungen von meinen Reitern, die in Eschental im Westen stationiert sind. Es ist möglich, dass die Nachtelfen einen Angriff auf unser Gebiet im Brachland durchführen.\n\n<Klasse>, Ihr müsst über die Grenze schleichen und mit einem meiner Späher sprechen. Sucht nach Kulg Blutspritzer direkt hinter der Brücke am südwestlichen Rand der Talrendisspitze. Findet heraus, was in jenen Wäldern vor sich geht!", progress = nil, completion = "Ihr sagt, dass die Talrendisspitze gefallen ist? Das sind gute Nachrichten!\n\nDas erklärt auch den Exodus von Elfen, den ich auf dieser Straße gesehen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24467] = {title = "Übergang ins Schwarze", objective = "Tötet Zwielichtfürstin Katrana und Malicion am Säbelrücken.", description = "Jetzt können wir diesen Wahnsinn beenden! Wir müssen den schwarzen Drachenschwarm vollkommen von Azshara fernhalten, bevor sie ihrem Meister irgendeine Nachricht überbringen können.\n\nIch weiß immer noch nicht, welches Ass sie für unsere Entführung im Ärmel haben, deshalb möchte ich Euch ein letztes Mal um etwas bitten: Geht zum Säbelrücken und tötet ihre Anführer, Zwielichtfürstin Katrana und Malicion.\n\nWenn es eng wird, komme ich und helfe. Ich möchte nur nicht riskieren, in die Falle zu gehen, die sie Azuregos gestellt haben.", progress = nil, completion = "Ihr versetzt mich in Erstaunen, sterbliches Wesen. Nur selten trifft man jemanden, der so entschlossen und erfinderisch ist.\n\nAzuregos und ich werden Azshara wahrscheinlich für eine Weile verlassen und untertauchen. Ich hoffe allerdings, dass wir uns eines Tages wiedersehen. Vielleicht bereiten wir ja Todesschwinge selbst ein Ende.\n\nLebt wohl, &lt;Name&gt;. Passt auf Euch auf.", rewards = "AzurschuppenwesteKalecgos GeschenkIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24468] = {title = "Gestrandet im Moor", objective = "Rettet 5 Unfallüberlebende aus dem Hagelwaldmoor.", description = "Die Oger haben zwei unserer Postkutschen erwischt: diese hier und eine, die nicht weit von hier im Norden ins Moor gestürzt ist.\n\nGeht dorthin und rettet die Überlebenden, während wir uns überlegen, wie wir mit diesen Ogern fertigwerden.", progress = nil, completion = "Ihr habt es wieder geschafft, &lt;Name&gt;. Ihr habt meinen Dank.", rewards = "SanitäterarmschienenHagelwaldbrustharnischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24469] = {title = "Die Stellung halten!", objective = "Tötet 6 Eindringlinge der Felsenkiefertroggs.", description = "Hey, Ihr da! Ihr seid doch <ein kräftig aussehender/eine kräftig aussehende:c> <Klasse>. Würdet Ihr uns helfen?\n\nEs scheint, als ob das heutige Erdbeben eine Gruppe dieser barbarischen Troggs aufgerüttelt hat und die sind über irgendetwas ziemlich erbost. Meine Leute tun, was sie können, um sie fernzuhalten, aber wir könnten Hilfe gebrauchen.\n\nTragt Euren Teil dazu bei - geht Richtung Süden und helft meinen Gebirgsjägern aus der Klemme. Wir müssen die Stellung halten!", progress = nil, completion = "Beeindruckende Arbeit, mein Junge. Von jetzt an können wir die Stellung wieder alleine halten.\n\nHier, nehmt das für Eure Bemühungen. Es könnte sich als nützlich erweisen, zumal ich Euch um etwas noch Wichtigeres bitten muss...", rewards = "UmkreiskniehosenGeborgte HändeTroggabweisender KettenpanzerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24470] = {title = "Haut sie!", objective = "Tötet 3 Stümper der Felsenkiefertroggs.", description = "Also gut, hört zu. Ich weiß ein oder zwei Dinge über Troggs, und eins davon ist, dass die größten und stärksten Troggs den meisten Respekt genießen. Diese Rohlinge ziehen Stärke allem anderen vor.\n\nSeht Ihr diese großen, starken Troggs hinter ihren Frontlinien? Sie sind das, was einem Anführer am nächsten kommt. Geht und erledigt ein paar von denen, damit sie wissen, was es heißt, sich mit den Töchtern und Söhnen von Eisenschmiede anzulegen!", progress = nil, completion = "Hmm... Sie machen uns dafür verantwortlich, ihre Höhle zerstört zu haben, sagt Ihr? Das waren nicht wir, das war dieses schreckliche Erdbeben heute früh. Sind die so beschränkt, dass sie nicht sehen, dass unser Lager auch beinah zerstört wurde?\n\nIch kann allerdings keinem Trogg vorwerfen, dass er für seine Heimat kämpft.", rewards = "Gürtel der sogenannten AnführerGroße TroggarmbänderStiefel der SchuldlosenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24471] = {title = "Hilfe für die Verwundeten", objective = "Verwendet Stens Erste-Hilfe-Set, um 4 verwundeten Gebirgsjägern der Eisklamm zu helfen.", description = "Hört zu, <Name>! Ich brauche nicht wie Joren Eure Klinge, aber ich benötige jemanden mit einer ruhigen Hand und etwas Mut.\n\nUnsere Gebirgsjäger sind ausgebildet, um das Dorf vor einem Wolfsangriff zu schützen... nicht vor einer ausgewachsenen Trogginvasion! Viele unserer Besten liegen verletzt und erschöpft darnieder, und ich brauche Eure Hilfe, um sie zu versorgen.\n\nHier, nehmt mein Erste-Hilfe-Set und helft so vielen, wie Ihr könnt.", progress = nil, completion = "Viele von jenen, die Ihr gerettet habt, sind schon ins Lager zurückgekehrt. Ihre Wunden scheinen gut versorgt! Ihr könntet eine Zukunft im Bereich der Ersten Hilfe haben, wenn Euch dergleichen zusagt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24472] = {title = "Vorstellen ist angebracht", objective = "Tötet 4 Ogerdiener und besorgt Euch Koroths Banner in Koroths Bau.", description = "Die Verlassenen sind uns dicht auf den Fersen und nun versuchen auch diese Oger, uns in die Zange zu nehmen, <Name>.\n\nSie sind Diener des Ettins Koroth, dem bösartigsten und zerstörerischsten Wesen in ganz Gilneas.\n\nWenn wir Koroth dazu bringen könnten, die Vorhut der Verlassenen anzugreifen, können wir uns vielleicht sicher zurückziehen und etwas Zeit gewinnen.\n\nAber das gelingt uns nur, wenn wir Koroth wütend machen. Seine Diener zu töten reicht nicht. Wir müssen uns seinen wertvollsten Besitz schnappen, sein Banner aus Tigerfell.", progress = "Wie ist es gelaufen, <Name>?", completion = "Ihr habt den Ettin wirklich sehr wütend gemacht, &lt;Name&gt;. Ich habe ihn selbst gehört.\n\nHoffen wir, dass es funktioniert.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGilneas Quest Invisibility Detection - 10 min - 10 [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24473] = {title = "Ambossar abriegeln", objective = "Sprecht mit Jona Eisenquell in Ambossar.", description = "Wir wissen Eure Hilfe hier draußen zu schätzen, doch es gibt einen Ort, an dem Ihr noch mehr gebraucht werdet.\n\nDank der Angriffe durch die Troggs - ganz zu schweigen von dem starken Erdbeben, das wir gerade erlebt haben - müssen wir alle Zivilisten in Ambossar im Nordwesten abriegeln.\n\nGeht und sprecht mit meiner Frau Jona in Ambossar. Ich bin sicher, sie kann <einen kräftigen Kerl/ein kräftiges Mädel> wie Euch gut brauchen.", progress = nil, completion = "Hmpf... und was wollt IHR nun wieder? Seht Ihr nicht, dass ich beschäftigt bin!? Geht jemand anders auf die Nerven, ich hab' keine Zeit.\n\nMoment, was sagt Ihr da? Joren hat Euch geschickt, um zu helfen? Warum habt Ihr das nicht gleich gesagt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24474] = {title = "Das Wichtigste zuerst: Wir brauchen Bier", objective = "Bringt je ein Fässchen Sturmhammer-Starkbier, Theramore Hell und Gnomenbräu an Euch.", description = "Ich kann mir nicht vorstellen, wie wir hier IRGENDWAS auf die Beine stellen wollen, solange wir kein Bier haben! Unser Biervorrat hier in Ambossar ist bedenklich niedrig.\n\nZum Glück haben wir für solche Fälle ein paar Notfallfässer aufbewahrt. Westlich von Ambossar, entlang der nördlichen Grenze des Tals, werdet Ihr Fässer mit Sturmhammer-Starkbier und Theramore Hell finden. Gleich östlich von hier findet Ihr einen Vorrat mit Gnomenbräu. Das ist mein Lieblingsbier!", progress = "Das Bier, Kumpel, das Bier!", completion = "&lt;Jona nimmt einen tiefen Zug von dem Gnomenbräu.&gt;\n\nAhh... Das hat gut getan. Jetzt können wir hier endlich ordentlich arbeiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24475] = {title = "Das ganze andere Zeug", objective = "Erlangt 3 Wildschweinschenkel und 4 struppige Wolfsbälge.", description = "Wenn wir hier eine ganze Weile die Schotten dichtmachen, werden wir etwas zu futtern brauchen und Decken, um die Kleinen warmzuhalten. Würde es Euch etwas ausmachen, hinauszugehen und ein paar Vorräte zu besorgen?\n\nIhr werdet feststellen, dass einige der kleinen Eber ein paar Keulen von stattlicher Größe haben... perfekt zum Essen. Dann brauchen wir noch Felle von jungen Wölfen.\n\nIhr findet fast überall in Eisklamm solches Wild.", progress = "Die Leute werden schon unruhig. Habt Ihr die Vorräte schon?", completion = "Das muss fürs Erste reichen. Wir haben eine Menge Mäuler zu stopfen, aber wir müssen mit dem hinkommen, was wir haben. Mit ein bisschen Glück schickt uns König Bronzebart in Eisenschmiede ja bald Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24476] = {title = "Die Klinge tempern", objective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die Gefrorenen Hallen.", progress = "Solange das Schwert nicht getempert wurde, ist es nutzlos.", completion = "Ich... ich verstehe nicht. Das Schwert zu tempern hätte die Klinge wieder in ihren ursprünglichen Zustand bringen sollen. Was ist hier geschehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24477] = {title = "Artefakte der Zwerge", objective = "Beschafft 5 vergessene Zwergenartefakte.", description = "<Name>, <mein Junge/meine hübsche Blume>! Interessiert Ihr Euch für Archäologie?\n\nWir haben hier genau vor unserer Nase eine aufregende Gelegenheit. Das Beben des heutigen seismischen Ereignisses hat einige Artefakte aus der Erde unter unserem Lager herausgeschüttelt. Wenn Ihr den nördlichen Rand des Tals inspiziert, solltet Ihr alle möglichen Schätze finden. Bringt einige zurück zu mir und vielleicht können wir sie zusammen untersuchen.\n\nAlles klar! Ab mit Euch!", progress = "Ja?", completion = "Wunderbar! Schaut Euch dieses hier an... Das muss mehr als 200 Jahre alt sein!\n\nJetzt aber zu anderen Dingen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24478] = {title = "Die Prüfung des Frosts", objective = "Schließt die Prüfung des Frosts ab, indem Ihr 20 Essenzen des Eises einsammelt, ohne von Gefrierbrand getroffen zu werden.", description = "Wisst Ihr, einige meiner Lehrlinge haben mich als kaltherzig bezeichnet. Ich sage allerdings immer, lasst die Temperatur meines Körpers Euch nicht daran hindern, zu lernen.\n\nWenn Ihr Euch zur Prüfung des Frosts begeben möchtet, berührt den Frostkristall, um ein Portal zu öffnen. Wenn Ihr dort seid, ist das Ziel ganz einfach: Sammelt die kleinen schwebenden Eiskügelchen ein.\n\nDamit es nicht zu einfach wird, könnte der Gefrierbrand Euren Fortschritt hemmen. Wenn Ihr besonders raffiniert sein wollt, könnt Ihr die Runenfallen benutzen, um über sie hinwegzuspringen, wenn sie vorbeidriften. Klasse, nicht wahr?", progress = "Nein. Einfach nein. Macht es diesmal richtig.", completion = "Großartig. Ihr lasst Euch ganz bestimmt nicht von kalten Füßen aufhalten. Oder sonstigen kalten Körperteilen!\n\nNein? ...noch zu früh?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24479] = {title = "Die Prüfung des Schattens", objective = "Schließt die Prüfung des Schattens ab, indem Ihr 20 Klagende Seelen zu den Schattenrunen lockt, ohne von ihnen berührt zu werden.", description = "Lassen wir uns nicht von den Grenzen des Magierepertoires der Magier einschränken. Ich jedenfalls will keiner Klasse angehören. Nekromantie kann so viel Spaß machen!\n\nBerührt den Schattenkristall, um ein Portal zu meiner Prüfung des Schattens zu öffnen. Sobald Ihr dort eintrefft, begebt Euch zu dem Altar, wenn Ihr bereit seid.\n\nKlagende Seelen werden Euch verfolgen...Euer Ziel ist es, sie in die Fallen zu locken. Achtet darauf, dass sie Euch nicht berühren.", progress = "Ihr seid nicht besonders gut darin. Ihr sollt die Prüfung beenden, BEVOR Ihr zu mir zurückkommt und mit mir sprecht. Nachvollziehbar?", completion = "Es gefällt mir, wie Ihr Euch bewegt, Lehrling.\n\nMacht Euch keine Sorgen darüber, wo ich all die Seelen herhabe. Sie wurden auf absolut humane Art und Weise besorgt, das versichere ich Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24480] = {title = "Die Hallen der Reflexion", objective = "Bringt Quel'Delar nach Schwertruh ins Innere der Hallen der Reflexion.", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den Gefrorenen Hallen auf Euch.", progress = "Was ist im Inneren der Hallen der Reflexion geschehen?", completion = "Ich hätte es nicht für möglich gehalten, dass das Böse von solch einem Schwert Besitz ergreifen kann, doch ich nehme an, dass das naiv von mir war. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nUthers Rat ist weise, &lt;Name&gt;, und ich würde Euch nahelegen, ihn schleunigst zu befolgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24483] = {title = "Sturmsiel", objective = "Sprecht mit Gwen Armstead in Sturmsiel.", description = "Unsere Kutschenfahrer wurden angewiesen, sich im Fischerdorf Sturmsiel zu sammeln. Die Späher berichten, dass wir dort Schutz und Vorräte finden können.\n\nTrefft Euch dort mit Gwen Armstead. Sie ist für die Leute verantwortlich.", progress = nil, completion = "Ihr habt es also geschafft, &lt;Name&gt;. Anscheinend haben es fast alle geschafft.\n\nFür eine Ausnahmesituation schlagen wir uns nicht schlecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24484] = {title = "Schädlingsbekämpfung", objective = "Tötet 6 Giftbruthuscher.", description = "Was sagt Ihr dazu, <Name>? Die ganze Zeit über war Sturmsiel halbwegs intakt.\n\nSchade, dass die Verlassenen noch immer unterwegs ins Landesinnere sind, aber immerhin ist es ein guter Platz, um für ein oder zwei Nächte die Füße hochzulegen.\n\nDie andere Hälfte der Stadt ist voll von Spinnen, deswegen habe ich den Leuten gesagt, sie sollen sich von dort fernhalten.\n\nVielleicht könntet Ihr ja helfen, die Spinnen zu beseitigen? Unsere Verwundeten können bestimmt besser schlafen, wenn sie wissen, dass jemand diese achtbeinigen Ungeheuer in Schach hält.", progress = "Ihr seid zurück, <Name>. Habt Ihr Euch um die Spinnen gekümmert?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Aber diese Spinnen sind überall und ich fürchte, ihre Zahl hat kaum abgenommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24486] = {title = "Schmiedet das Eisen, solange es noch heiß ist", objective = "Besorgt 5 unbezahlbare Felsenkieferartefakte von den Strauchdieben der Felsenkiefertroggs.", description = "Das Dorf der Troggs im Südwesten wurde fast ebenso sehr beschädigt, wie unseres. Nun sollte man logischerweise annehmen, dass da auch einige Troggartefakte aus dem Boden ragen!\n\nLeider scheinen Troggplünderer die meisten Artefakte bereits aufgesammelt zu haben. Bitte schaut, ob Ihr eine Möglichkeit findet, sie zurückzuholen. Ob Ihr es glaubt oder nicht, aber Wissen über die Troggs könnte schließlich dazu führen, dass man noch mehr Wissen über die mächtigen Zwerge erlangt!", progress = "Habt Ihr den Troggs einige Artefakte entreißen können?", completion = "Oh, nun schaut Euch das an! Eine Axtklinge, einige Pfeilspitzen und eine Art einfacher Löffel. Das ist in der Tat faszinierend.\n\nNoch einmal vielen Dank für Eure Hilfe, &lt;Name&gt;. Ich werde viel mit meinen Studien zu tun haben, wenn Joren uns hier abriegelt.", rewards = "Robe des ErforschersWinterjackeBrustplatte der FelsenkiefertroggsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24487] = {title = "Weißbart braucht Euch", objective = "Meldet Euch bei Grelin Weißbart im Eisklammtal.", description = "Ihr habt uns hier einen großen Dienst erwiesen, doch befürchte ich, dass wir Euch weiterschicken müssen.\n\nEin guter Freund von mir, Grelin Weißbart, hat mich wissen lassen, dass er ein wenig Verstärkung gebrauchen könnte. Ihr findet ihn in der Nähe der Trolllager in Richtung Südwesten. Folgt der Straße Richtung Westen, dann solltet Ihr ihm früher oder später begegnen.\n\nAlles Gute, <Name>. Troggs mögen vielleicht eine Plage sein, aber Trolle sind nicht zu unterschätzen.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Bereit, Euch an die Arbeit zu machen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24488] = {title = "Der Ersatz", objective = "Sammelt 6 Ersatzteile.", description = "Meine Jungs sitzen alle verletzt auf der Bank! Unsere Schredder sind nur noch Schrott! Der Schiri pfeift das Spiel gleich ab!\n\nDie letzte Minute läuft und ich brauche Euch, <Name>!!!\n\nWir müssen einen dieser Schredder auf Vordermann bringen. Im Bilgepier liegen genügend Ersatzteile herum. Jeder grünblütige Kezanier überlässt sie Euch sicher gerne, wenn die Bukaniere dann eine Chance auf den Sieg haben.\n\nWir werden diesen nichtsnutzigen Dampfdruckhaien schon zeigen, wie man Fußbombe spielt.", progress = "Wir verlassen uns auf Euch, <Name>!", completion = "Das ist mein Junge! Jetzt muss ich diesen wertlosen Metallschrott nur noch in einen funktionierenden Zustand bringen und Euch raus aufs Spielfeld schicken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24489] = {title = "Trollt Euch und lauscht", objective = "Stellt Euch in jedem der Frostmähnenlager in die Nähe einer Sterndeuterin der Frostmähnen und lauscht dem, was sie zu sagen hat.", description = "Ich bin unglaublich schlecht darin, den Gesichtsausdruck von Trollen zu deuten. Daher kommen diese Trolle mir gar nicht wütend vor. Sie scheinen verwirrt... vielleicht ein wenig verängstigt.\n\nHier ist etwas passiert, was wir übersehen, <Name>. Wir sollten der Sache ein wenig auf den Grund gehen, bevor wir einfach alle Trolle umbringen.\n\nHier in der Gegend gibt es drei Trolllager: eins im Südosten, eins im Südwesten und eins ganz im Westen. In jedem Lager gibt es eine Sterndeuterin... Schaut, ob ihr nahe genug an sie herankommt, dass Ihr belauschen könnt, was sie sagen.", progress = "Ich kann mir beim besten Willen nicht vorstellen, was die Trolle zu so einem Handeln bewegen mag.", completion = "Hmm... interessant. Nach dem, was Ihr berichtet, scheint ein Feuerelementar sich aus der Sengenden Schlucht eingeschlichen zu haben. Oder das Erdbeben hat einen Riss in der Elementarebene geöffnet...\n\n&lt;Soren lacht gequält.&gt;\n\nSo oder so, das sind schlechte Neuigkeiten. Ihr solltet das lieber Grelin berichten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTrolling for Information: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24490] = {title = "Ein Trip nach Eisenschmiede", objective = "Sprecht mit Hands Federspross im Eisklammtal.", description = "Die Präsenz eines Feuerelementars hier im Eisklammtal ist keine Kleinigkeit. Dieses Erdbeben hat doch mehr angerichtet, als nur ein paar Troggs zu verärgern... Es hat die Welt genug verändert, um einen Riss in der Elementarebene zu verursachen. Wir sollten einen Bericht nach Eisenschmiede schicken.\n\nIhr wärt nicht eventuell bereit, eine kleine Reise zu unternehmen, oder? Keine Sorge, Ihr seid genau <der Richtige/die Richtige>. Redet mit Hands Federspross beim Tunnel am östlichen Ende des Tals. Er weist Euch den richtigen Weg.", progress = nil, completion = "Nach Eisenschmiede? Nun, zuerst müsst Ihr durch Kharanos, aber davor müsst Ihr noch durch diesen Tunnel.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nA Trip to Ironforge - Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24491] = {title = "Folgt diesem Gyrokopter", objective = "Meldet Euch bei Milo Zwickrädchen nahe Ambossar.", description = "H-h-habt Ihr das gesehen? Wie die ganze Höhle einfach so zusammengestürzt ist? Ich glaube, Ihr seid genau rechtzeitig gekommen, keine Minute zu früh.\n\nObwohl diese Entwicklung meinen Job, die Höhle zu untersuchen, entschieden vereinfacht, wird es für Euch nun schwerer, nach Kharanos zu gelangen.\n\nHe, wartet, ich habe eine Idee! Die Luftfahrer aus Gnomeregan haben einen Flugpunkt nicht weit von hier. Ich werde ein Signal absetzen und sie sollten Hilfe schicken. Ich vermute, dass sie drüben in Ambossar landen werden.", progress = nil, completion = "Milo Zwickrädchen meldet sich zum Dienst. Ihr habt ein Notsignal abgesetzt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24492] = {title = "Packt Eure Taschen", objective = "Erlangt einen Bierkrug der Eisklamm, einen struppigen Wolfsbalgumhang und ein paar Eberfleischreste.", description = "Aufgrund der Gewichtsbeschränkung meines Gyros kann nur <ein/eine:r> <Volk> mitfliegen. Sieht aus, als hättet Ihr Glück, <Name>!\n\nDie Zwergin Jona hat mir erzählt, dass all Eure Sachen nach Ambossar gebracht wurden. Sammelt zusammen, was Ihr braucht, beendet Eure Angelegenheiten und kommt zu mir zurück, wenn Ihr bereit seid, aufzubrechen.", progress = "Seid Ihr absolut sicher, dass Ihr Euch um alles gekümmert habt? Ihr werdet keine Zeit haben, nochmal herzukommen.", completion = "Hat ja auch lang genug gedauert. Haltet Euch gut fest und schaut Euch nochmal gut um! Höchstwahrscheinlich werdet Ihr eine ganze Weile nicht mehr herkommen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPack Your Bags - Quest Complete\n\nIhr bekommt:\n\nBeutel des Gebirgsjägers der Eisklamm"}
MultiLanguageQuestData['de'][24493] = {title = "Vergesst uns nicht", objective = "Meldet Euch bei Tharek Schwarzstein in Kharanos.", description = "Ihr verlasst uns? Denkt daran, Eure Vorräte aufzufüllen, bevor Ihr aufbrecht.\n\nWichtiger noch, sprecht mit Tharek Schwarzstein sobald Ihr in Kharanos eintrefft. Sagt ihm, was hier im Eisklammtal geschehen ist und dass wir ein wenig Hilfe gebrauchen könnten. Er wird hoffentlich etwas für uns organisieren können.", progress = nil, completion = "Das Eisklammtal? Ich habe hier meine eigenen Probleme. Was, die werden nicht mit ein paar Troggs fertig? Und Trollen? Und Übergriffen aus den Elementarebenen?\n\nAllerdings, wenn ich so darüber nachdenke... Das ist eine Menge. Ich bin überrascht, wie gut sie sich unter den Umständen halten. Ich werde sehen, was ich tun kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24494] = {title = "Machterfüllte Rune", objective = "Lest die machterfüllte Rune und sprecht mit Teo Hammersturm in Ambossar.", description = "<Name>, diese Rune wurde mir gegeben, damit ich sie an Euch weiterreiche. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaub', sie stammt vom Schamanenlehrer Teo. Werft einen Blick auf die Rune und sucht ihn dann in Ambossar auf.", progress = "Die Geister haben mir Eure Ankunft angekündigt, <Name>. Habt Ihr sie ebenfalls gehört?", completion = "Wir leben in dunklen Zeiten, mein Freund. Seht Euch um... selbst hier im entlegenen Eisklammtal sind die Geister rebellisch. Das Land ruft um Hilfe. Dennoch, sogar in Zeiten wie diesen, werden die Geister immer ein offenes Ohr für diejenigen haben, die ihre Hilfe erbitten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24495] = {title = "Fetzen der Vergangenheit", objective = "Sammelt 6 alte Tagebuchseiten.", description = "Ich habe das Tagebuch eines Mannes namens Bradshaw gefunden. Leider fehlen viele Seiten, besonders gegen Ende.\n\nWenn Ihr genügend Seiten zusammentragt, kann ich vielleicht herausfinden, was nach dem Ausbruch des Fluchs hier geschehen ist.\n\nWer weiß… Vielleicht haben die Leute in diesem Dorf einen Fluchtweg gefunden. Vielleicht gibt es da draußen noch Überlebende.\n\nVielleicht ist mein Vater noch am Leben.", progress = "Hattet Ihr schon Erfolg bei der Suche nach diesen Seiten?", completion = "Danke, &lt;Name&gt;. Es wird ein wenig dauern, aber ich versuche, in dem was wir haben einen Sinn zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24496] = {title = "Arkane Rune", objective = "Lest die arkane Rune und sprecht dann mit Teegli Merrowith im Eisklammtal.", description = "<Name>, diese Rune hier sollte ich an Euch weitergeben. Nehmt Euch Zeit und lest sie gut durch, sobald Ihr könnt. Ich glaube, sie kommt von der Magierlehrerin Teegli. Werft einen Blick darauf und dann sucht sie in Ambossar auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24497] = {title = "Wieder in der Luft", objective = "Sichert Euch einen Flug nach Valormok mit den Fliegenden Priestern an der Ostseite des Bilgewasserhafens.", description = "Wir haben gerade aus Valormok erfahren, dass wir keine weiteren Windreiter entsenden sollen, sonst werden sie von Heckenschützen der Talrendisspitze abgeschossen. Wir können Valormok nicht aufgeben, wenn wir eine sichere Route nach Eschental haben wollen, also gehen wir auf einem anderen Weg hinein.\n\nDie Fliegenden Priester haben großzügigerweise angeboten, einige unserer Leute von oberhalb der Reichweite der Heckenschützen abzusetzen. Geht zum Militärviertel und sichert Euch einen Flug auf einem ihrer Flugzeuge. Sie werden Euch dort in einem Stück abliefern und wenn Ihr erst einmal dort seid, könnt Ihr unsere Windreiterlinien wieder sichern.", progress = nil, completion = "Es ist schon längst überfällig, Azshara von diesem Nachtelfenabschaum zu säubern. Ich bin froh, dass ich jemanden mit Euren Fähigkeiten habe, der mir helfen kann, das deutlich zu machen.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24498] = {title = "Der Pfad zur Zitadelle", objective = "Befreit 15 Allianzsklaven und tötet Schmiedemeister Garfrost.", description = "Sie haben unsere gefangenen Soldaten zur Arbeit im Steinbruch eingesetzt!\n\nTötet ihre Entführer und befreit sie, <mein Held/meine Heldin>. Wir werden ihre Hilfe brauchen, wenn wir Geißelfürst Tyrannus entgegentreten.", progress = nil, completion = "Ihr habt heute gute Arbeit geleistet. Jetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24499] = {title = "Echos gequälter Seelen", objective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", description = "Wir sind eindeutig zu wenige, um uns in die Zitadelle zu wagen, doch so eine Gelegenheit dürfen wir uns nicht entgehen lassen.\n\nRäumt die Feinde bis ganz nach hinten aus dem Weg und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.", progress = nil, completion = "Genau zur rechten Zeit! Danke, &lt;Name&gt;!\n\nDie Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und vielleicht, aber nur vielleicht, ihn zu erlösen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24500] = {title = "Der Zorn des Lichkönigs", objective = "Findet Lady Jaina Prachtmeer und flieht aus den Hallen der Reflexion.", description = "Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch zuerst müsst Ihr Jaina finden und vor dem Lichkönig fliehen, solange noch Zeit dazu ist.", progress = nil, completion = "&lt;Jaina ringt noch immer nach Luft.&gt;\n\nIch kann kaum glauben, dass wir noch am Leben sind. Es war dumm von mir, ihm zu folgen. Zu oft habe ich diesen Fehler begangen. Und Ihr... es war ziemlich unbesonnen, mir zu folgen, anstatt mit den Informationen zu fliehen. Aber... nun ja... danke. Das war wirklich heldenhaft!\n\nMit Uthers Hilfe haben wir vielleicht eine Chance, Arthas zu besiegen. Dann hätten alle, die heute gestorben sind, ihr Leben nicht umsonst gelassen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24501] = {title = "Spinne am Morgen bringt Kummer und Sorgen", objective = "Tötet Rygna in Rygnas Hort.", description = "Die Flut der Spinnen nimmt kein Ende, <Name>. Ihr müsst in ihr Nest gehen und die Brutmutter töten.\n\nWir haben die riesige Spinne namens Rygna zuletzt am Rand des Schwarzforstes gesehen, in einer Gegend, die ganz mit dicken Netzen bedeckt war. Es wird gefährlich, aber wir verlassen uns auf Euch.", progress = "Habt Ihr Rygna schon vernichtet, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Wir haben gehört, dass es weiter oben in den Bergen noch Überlebende geben soll. Jetzt können wir endlich Späher dorthin schicken.", rewards = "RygnaseidengamaschenBrustplatte des ArachnophobikersGeflochtene GazearmbänderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24502] = {title = "Notwendige Gewaltanwendung", objective = "Benutzt den Bilgewasserbukanier und werft die Fußbombe auf 8 Dampfdruckhaie.", description = "Wir haben nur noch einen Schredder. Als gerade niemand hingesehen hat, habe ich ihn mit, nun ja, sagen wir, modifizierten Fußbomben geladen.\n\nIhr müsst diesen Schredder nehmen und ihnen das Leben zur Hölle machen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24503] = {title = "Drölfmeterschießen", objective = "Schießt das Siegertor, indem Ihr die Fußbombe zwischen die beiden Schornsteine hinter dem gegnerischen Tor schießt.", description = "Jetzt liegt es an Euch, <Junge/Mädel>! Ihr habt die Dampfdruckhaie vernichtet. Jetzt müsst Ihr nur noch das Siegtor schießen.\n\nJetzt mal unter uns. Ich finde, wir sollten dieses Mal alles richtig machen. Ich möchte nicht, dass Ihr einfach nur ein Tor schießt... Ich möchte, dass Ihr so weit schießt, dass die Bombe bis zwischen die beiden Schornsteine hinter dem Tor fliegt!\n\nIch habe die Fußbombe so präpariert, dass sie dafür die richtige Zusatzleistung hat.\n\nUnd jetzt raus da und macht mich stolz!", progress = nil, completion = "Äh… Ihr habt es geschafft, Junge. Ihr habt es ECHT geschafft! Wir haben das Spiel gewonnen und… \n\nHABT IHR DIESEN DRACHEN GESEHEN?!!!", rewards = "AthletenrobeBlutgrätschenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24504] = {title = "Säubert den Höhenpfad", objective = "Tötet 3 Späher des Höhenpfads.", description = "Hier entlang, <Klasse>! Wie ich sehe, habt Ihr den Höhenpfad entdeckt.\n\nDie Allianz hofft, dass sie unsere Verbindungen zum Steinkrallengebirge abschneiden kann, aber sie haben vergessen, dass wir Tauren seit Generationen in diesen Landen jagen. Wir kennen jede Spitzkehre an den Hängen und jeden Wildpfad von hier nach Tausend Nadeln.\n\nAber damit diese Pfade offen bleiben, müssen wir die Menschen daran hindern, sie zu vermessen.\n\nLauft auf dem östlichen Pfad Patrouille und tötet alle Späher des Höhenpfads, die Ihr unterwegs findet. Dann sprecht mit Tunawa Stillwind, den Ihr ein Stück weiter den Pfad entlang findet.", progress = nil, completion = "Auf dem Höhenpfad zu patrouillieren ist eine lebensgefährliche Aufgabe, aber sie muss erledigt werden. Diese engen Bergpfade sind im Moment unsere einzige Lebenslinien ins Steinkrallengebirge. Sie müssen erhalten werden.\n\nDanke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24505] = {title = "Am Jägerhügel ausharren", objective = "Sprecht mit Onatay am Jägerhügel im Südlichen Brachland.", description = "Ehrenwacht mag verloren sein, aber sein Geist ist niemals zerstört worden. Sogar jetzt harren Überlebende noch an einem Ort aus, der \"Jägerhügel\" genannt wird.\n\nFolgt dem Höhenpfad weiter und Ihr werdet ihr Lager genau vor uns finden. Wenn Ihr dort eintrefft, sprecht mit Onatay und lasst sie wissen, dass der Pfad - für den Moment jedenfalls - immer noch sicher ist.", progress = nil, completion = "Also die Allianz erkundet die Drehungen und Wendungen des Höhenpfads?\n\nSelbst wenn es ihnen gelingt, ihn zu kartographieren, könnten sie diese Hügel nicht mit vielen Leuten angreifen. Dies ist unser Land, &lt;Name&gt;. Und sie werden es teuer bezahlen, wenn sie etwas anderes glauben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24506] = {title = "In der eisigen Zitadelle", objective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Fürstin Sylvanas Windläufer.", description = "<Klasse>! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Königin, Fürstin Sylvanas Windläufer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, hat sie mich mit der Suche nach grimmigen Kämpfern beauftragt, die sich dorthin wagen. Ihr scheint mir dafür geeignet.\n\nTrefft sie am Eingang der Schmiede, <Klasse>!", progress = nil, completion = "Gut. &lt;Name&gt;, ich weiß einiges über Euch. Ihr seid wie gemacht für diese Aufgaben.\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24507] = {title = "Der Pfad zur Zitadelle", objective = "Befreit 15 Hordensklaven und tötet Schmiedemeister Garfrost.", description = "Sie lassen unsere entführten Soldaten im Steinbruch schuften. Tötet die Entführer und befreit die Gefangenen, <Klasse>! Wir brauchen ihre Hilfe, wenn wir Geißelfürst Tyrannus gegenübertreten.", progress = "Danke, <Klasse>. Unser Blut und unser Stahl werden Euch zu Diensten sein.", completion = "Ihr habt heute gute Arbeit geleistet. Jetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24510] = {title = "In der eisigen Zitadelle", objective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Lady Jaina Prachtmeer.", description = "<Klasse>! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Herrin, Lady Jaina Prachtmeer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, erhielt ich die Aufgabe, alle Hilfe zu suchen, die ich finden kann... und, nun ja, ich hatte da an Euch gedacht.\n\nBitte, sucht sie so schnell wie möglich dort auf!", progress = nil, completion = "&lt;Name&gt;! Ich bin so froh, dass Ihr gekommen seid!\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24511] = {title = "Echos gequälter Seelen", objective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", description = "Es ist ziemlich gefährlich, mit so wenig Leuten die Zitadelle zu betreten, doch so eine Gelegenheit bekommt man nicht alle Tage.\n\nBereitet einen Weg zum anderen Ende und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.", progress = nil, completion = "Ihr kommt gerade recht, &lt;Klasse&gt;!\n\nDie Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und eine Möglichkeit zur Rache, die schon so lange überfällig ist.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24512] = {title = "Die Erlösung eines Kriegers", objective = "Bringt 5 Kisten mit konfiszierten Waffen aus Ehrenwacht an Euch und rüstet 5 Gefangene aus dem Steinkrallengebirge damit aus. Benutzt die Seile in der Nähe, um Euch schnell in das Lager der Allianz hinein- und hinauszubewegen.", description = "Diejenigen, die sich beim Fall von Ehrenwacht ergeben haben, sind der Horde nicht länger würdig, <Klasse>. Doch ich werde sie noch nicht aufgeben. Der Gefängnisturm unter uns ist nur leicht bewacht. Geben wir den Gefangenen eine letzte Chance, ehrenhaft zu sterben.\n\nIch habe Seile in Position gebracht, die es Euch erlauben werden, schnell den Berg hinauf- und hinunterzuklettern. Schleicht Euch hinunter, bringt die beschlagnahmten Waffen an Euch und bewaffnet die Gefangenen, die sich im Turm befinden.\n\nUnd <Name> - bleibt beim Turm! Wir sind in der Basis noch nicht ausreichend ausgerüstet, um einen Angriff zu überstehen.", progress = nil, completion = "Von hier oben habe ich einen genauen Überblick über das Chaos, das Ihr gerade angerichtet habt, &lt;Name&gt;. Unsere verlorenen Brüder haben ein wenig ihrer Würde wiedergewonnen und die Hunde der Allianz wurden in die Flucht gejagt. Präzise Arbeit, mein Freund!\n\nWenn die Allianz heute Nacht gut schläft, machen wir etwas falsch.\n\nWir werden niemals nachgeben.\n\nWir werden niemals aufgeben.", rewards = "KlettergurtHolgoms ArmschienenAuf Euch wartet eine dieser Belohnungen:\n\nRing der wiedererlangten Ehre\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24513] = {title = "Auge um Auge", objective = "Tötet Hauptmann Peake und bringt seine Augen zu Oltarg.", description = "Wer ist da? Eure Schritte klingen nicht wie das faule Schlurfen der Wachen.\n\n<Ein/Eine:c> <Klasse>, sagt Ihr? Immer noch tapfer und frei? Für mich gibt es keine Hoffnung, <mein Freund/meine Liebe>. Ich habe mein Augenlicht verloren und bin nicht länger kampftauglich.\n\nIch habe es gewagt, meine Stimme zu erheben, als Hauptmann Peake einen der Gefangenen schwer misshandelte. Als Antwort hat er mich gegen den Kopf getreten. Immer wieder. Er hat auf mir herumgetrampelt, bis ich blind war, <Volk>.\n\nIhr findet Hauptmann Peake oben auf seinem Turm. Wenn Ihr Gerechtigkeit wollt, bringt mir seine Augen.\n\nWenn er sie nicht freiwillig hergibt... so sei es.", progress = "Peake ist ein Monster. Wenn seine Vorgesetzten davon wüssten, wären sie der Horde dankbar, dass diese ihm ein Ende bereitet hat.", completion = "Habt Ihr sie? Ich verlasse mich blind auf Euch. Zu hören, das Peake wie eins seiner Opfer brüllt, ist genug Belohnung für mich.\n\nNun lasst mich allein, &lt;Name&gt;. Ich möchte meinem Klan keine Bürde sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24514] = {title = "Raptorenreste", objective = "Besorgt 8 Schreckenszahnbälge von Schreckenszahnläufern und Schreckenszahnsensenklauen.", description = "Wir werden hier belagert, <Klasse>. Durch den Abgrund einerseits und die ständige Belästigung durch die Allianz andererseits sind die Vorräte knapp geworden. Aber wir schlagen uns mit dem, was da ist, durch - so, wie wir Tauren das immer getan haben.\n\nWir haben keine Schmiede, aber wer geschickt in der Lederverarbeitung ist, kann unsere beschädigte Rüstung mit qualitativ hochwertigen Bälgen verstärken oder zusammenflicken.\n\nDort unten sind die Jagdgründe der Schreckenszahnraptoren. Sie sind nicht leicht zu töten - was zum Teil an der Robustheit ihrer dicken Bälge liegt. Jagt sie, <Name> und bringt mir ihre Bälge!", progress = "Schreckenszahnraptoren jagen im Rudel und kreisen ihre Beute ein. Wir jagen sie, ja, aber wir respektieren sie auch.", completion = "&lt;Onatay lässt ihren Blick über die frischen Bälge schweifen und nickt langsam.&gt;\n\nJa &lt;Name&gt;, damit kann ich arbeiten. Ihr arbeitet schnell!\n\nDiese Bälge werden uns dabei helfen, noch länger auszuharren, bis Verstärkung kommt. Danke.", rewards = "Ledergeflickter GürtelRaptorfetzenumhangArmschienen aus SchreckenszahnhautIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24515] = {title = "Signale am Himmel", objective = "Begebt Euch nach Camp Una'fe in der Überwucherung des Südlichen Brachlands und sprecht mit Makaba Flachhuf.", description = "Wendet Euren Blick nach Südosten. Seht Ihr den Rauch der Lagerfeuer von Camp Una'fe?\n\nVor noch nicht einmal zehn Minuten sah ich aus dem Zentrum des Lagers große weiße Rauchwolken gen Himmel aufsteigen. Das war ein altes Signal, das mein Dorf dazu verwendete, die Jagd über große Entfernungen hinweg zu koordinieren. Doch diesmal war es ein Notrufsignal.\n\n<Name>, mein Bruder Makaba ist in diesen unnatürlichen Dschungel gegangen. Bitte geht dorthin und stellt sicher, dass er nicht in Schwierigkeiten steckt.\n\nEs gibt verschiedene Wege... Schaut Euch in der Wildnis nach Zelten um.", progress = nil, completion = "Also hat meine Schwester die alten Signale erkannt? Ihre Jägeraugen sind scharf wie immer.\n\n&lt;Name&gt;, als wir dieses Lager aufschlugen, waren wir am Rand des Dschungels. Jetzt schaut Euch um!\n\nIrgendetwas fehlt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24517] = {title = "Jagt ihnen Angst ein", objective = "Tötet 8 Fußsoldaten der Ehrenwacht und 1 Offizier der Ehrenwacht.", description = "Seht Ihr die Spur dort unter uns, <Name>? Das ist MEINE Spur. Und wenn diese Hunde der Allianz sich an meine Spur heften, dann sollten sie aufpassen, was hinter ihnen vor sich geht.\n\nEs wird Zeit, dass ich meinen Wegzoll einfordere. Tötet die Fußsoldaten der Ehrenwacht und schaut, ob wir sie nicht wie die Hasen wieder hinter ihre Mauern jagen können.\n\nAchtet darauf, dass Ihr mindestens einen ihrer Offiziere tötet, die die Straße entlang patrouillieren. Ihnen muss klar werden, dass niemand sicher ist.", progress = nil, completion = "Ausgezeichnet, &lt;Name&gt;. Es wird eine Weile dauern, bevor wir die Festung selbst angreifen können, aber bis dahin müssen wir ihnen Angst vor dem Brachland einflößen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24518] = {title = "Der Tiefenpfad", objective = "Liefert die Straßenbaupläne bei Kilrok Grindhammer am Jägerhügel im Südlichen Brachland ab.", description = "Dieser Stapel Papiere wurde in einer Ledertasche unter den Kleidern des Offiziers versteckt gefunden.\n\nSchlachtpläne der Region, die Ehrenwacht darstellen, das mit einer langen, unfertigen Straße verbunden zu sein scheint, die sich von Theramore aus quer durch das Brachland erstreckt. Es sieht so aus, als ob die Allianz plant, eine Straße von der Küste bis hinein ins Herz von Kalimdor zu bauen.\n\nKilrok Grindhammer wird das sicher sehen wollen.", progress = "Ah, Ihr sagt, Ihr hättet etwas bei einer der Leichen gefunden?", completion = "&lt;Kilrok überfliegt die Pläne, die Ihr entdeckt habt.&gt;\n\nDas erklärt einiges, &lt;Name&gt;. Kein Wunder, dass unsere Feinde so versessen darauf sind, das Südliche Brachland einzunehmen. Es ist das Zentrum ihrer Pläne für den Kontinent!\n\nAber sie haben die Rechnung ohne uns gemacht, nicht wahr, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24519] = {title = "Die Vermessung unterbinden", objective = "Findet und tötet den Feldmesser Henry Zykes.", description = "Diese Karten wurden alle von derselben ruhigen Hand gezeichnet. Ich hab einen Vermesser der Menschen gesehen, der die Straße zwischen der Burg und dem Dschungel im Osten entlanggelaufen ist.\n\nWir können ihnen einen Strich durch die Rechnung machen, indem wir an diesem Vermesser ein Exempel statuieren, <Name>.\n\n<Kilrok zeigt auf die Unterschrift unten auf den Karten.>\n\nWas meint Ihr, was dort steht? \"Zykes\"? Sogar menschliche Namen klingen dünn und schwach. Tötet ihn!", progress = nil, completion = "Gut, gut! Wir müssen Ehrenwacht isoliert halten.\n\nAlleine...verängstigt... &lt;Name&gt;, wenn wir sie unter Druck setzen, werden sie vielleicht eines Tages sogar den Pfad einfach aufgeben.", rewards = "VermessungshandschuheZykes' GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24520] = {title = "Neuigkeiten für Sassy", objective = "Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.", description = "Ich würde ja mit Euch feiern, aber ich fürchte, dass der Drache dem guten alten Kajaro ganz schön zugesetzt hat. Ich… äh… Ich glaube, ich packe meine Sachen und nehme das erste Schiff, das die Insel verlässt.\n\nIhr solltet jedenfalls zum Hauptgeschäftssitz zurückkehren und Sassy erzählen, dass Ihr den Fußbombentitel für uns gewonnen habt. Ich bin mir sicher, dass sie auch über den Drachen und den Kajaro Bescheid wissen möchte.\n\nViel Glück!", progress = nil, completion = "Ihr macht Witze, oder?! TODESSCHWINGE?!!!\n\n&lt;Sassy sieht einen Moment lang panisch aus.&gt;\n\nOkay, das wird schon. Wir veranstalten Eure Party, und bis wir damit fertig sind, ist der Drache sicher schon lange weg und der Boden hat zu zittern aufgehört.\n\nFalls nicht, können wir immer noch ein Schiff chartern und von hier verschwinden.", rewards = nil}
MultiLanguageQuestData['de'][24522] = {title = "Reise zum Sonnenbrunnen", objective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, <Name>! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", progress = "Was führt Euch hierher?", completion = "Ihr wollt Zugang zum Sonnenbrunnen? Das ist unmöglich! Der Sonnenbrunnen ist unserem Volk der heiligste und wichtigste Ort. Erst kürzlich konnten wir ihn durch die Hilfe der Offensive der Zerschmetterten Sonne zurückgewinnen. Er ist kein Ort für Touristen und Reisende.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24523] = {title = "Totem der Wildmähnen", objective = "Sammelt 4 Präriealphazähne von Präriewolfalphas.", description = "Es gibt nur noch einen Brunnen, der gesäubert werden muss; er trägt den Namen des Wildmähnenklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.\n\nAlphatiere streifen oft am Fuße unserer mächtigen Stadt Donnerfels umher.", progress = "<Name>. Habt Ihr die Zähne, um die ich gebeten habe?", completion = "Sehr gut, &lt;Name&gt;. Ich kann das Opfer fühlen, das das Land gebracht hat, und mein Geist ist erfüllt von Traurigkeit und Stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24524] = {title = "Wildmähnensäuberung", objective = "Benutzt das Läuterungstotem der Wildmähnen beim Brunnen der Wildmähnen.", description = "Die Geister sprechen von Eurer Säuberung der Brunnen der Winterhufe und Donnerhörner, <Name>. Das Totem der Wildmähnen ist fertig und die letzte Aufgabe erwartet Euch.\n\nDer Brunnen der Wildmähnen liegt nördlich von Donnerfels. Führt das Ritual durch! Heilt das Land vom Gift der Grimmtotem! Lasst das Wasser wieder klar und rein fließen!", progress = "Einer der Brunnen stinkt immer noch und verbreitet sein Gift, <Name>. Ihr müsst Euch beeilen.", completion = "Ihr habt es geschafft. Ihr habt die Brunnen gesäubert und unser Land geheilt. Das Dorf der Bluthufe dankt Euch, &lt;Name&gt;.\n\nMöge der Wind Kunde von Euren Taten in alle Welt tragen und mögen die Wasser von Mulgore bis in alle Ewigkeit rein sein.", rewards = "Roben des WasserträgersGamaschen des DämmerungswächtersKlippenläuferstiefelFalkenauges GewehrIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24525] = {title = "Die Hunde in Schach halten", objective = "Tötet 6 Fleischreißerstrauchdiebe.", description = "Nicht jeder, der aus Taurajo geflohen ist, hat es nach Una'fe geschafft, <Name>. Einige starben unterwegs an ihren Verletzungen. Andere wurden von opportunistischen Stachelebern angegriffen.\n\nIch habe die grausige Aufgabe, die Leichen zu finden und einzusammeln. Aber Ihr könnt etwas für mich tun.\n\nFleischreißerstrauchdiebe durchstreifen die Lande südlich von hier und zerreißen die Leichen, zerren an ihren Eingeweiden herum und schleppen die Extremitäten der Toten davon. Bitte dezimiert sie, damit ich die gebotenen Beerdigungsrituale durchführen kann.", progress = nil, completion = "Es ist also vollbracht.\n\nEigentlich sind diese Strauchdiebe ein Teil des Lebenszyklus' der Erdenmutter. Aber im Zuge der Zerstörung, die sowohl die Allianz als auch der Kataklysmus über uns gebracht haben, wächst ihre Zahl ins Unermessliche. Es ist gut, sie wieder zu dezimieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24526] = {title = "Aufstocken des Zauberbuchs", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Wirkt den Zauber erfolgreich zweimal auf den Trainingsattrappen vor dem Eingang nach Ambossar.", description = "Exzellent! Lasst uns beginnen.\n\nWenn Ihr an Macht gewinnt, wird sich Eure Verbindung zum Arkanen vertiefen und Ihr werdet Zugang zu neuen Zaubern und Fähigkeiten erhalten.\n\nGeht, sammelt Erfahrungen, und Ihr werdet sehen, was ich meine. Kommt zurück, wenn Ihr etwas Neues erlernt habt und demonstriert es an den Trainingsattrappen hier.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24527] = {title = "Der Beginn Eures Wegs", objective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Übt anschließend 'Urtümlicher Schlag' zwei Mal an einer Übungsattrappe nahe des Eingangs zu Ambossar.", description = "Ausgezeichnet! Lasst uns anfangen.\n\nWenn Ihr auf Eurem Weg erfahrener werdet, werdet Ihr die uralten Geheimnisse der Schamanen entschlüsseln.\n\n'Urtümlicher Schlag' ist eine solche Fähigkeit. Die urtümlichen Geister, wenn sie herbeigerufen sind, werden Euren Arm stärken, um einen mächtigen Schlag auszuführen.\n\nHilfreich, nicht wahr?", progress = "Ihr habt den urtümlichen Schlag noch nicht erlernt. Wenn Ihr mich freundlich bittet, werde ich ihn Euch beibringen.", completion = "Dies war nur einer der vielen Schritte auf dem langen Weg des Schamanen. Kehrt zu mir zurück, wenn Ihr etwas mehr Erfahrung gesammelt habt, dann werde ich Euch bei Eurem nächsten Schritt unterstützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24528] = {title = "Die Macht des Lichts", objective = "Erreicht Stufe 3, um das Siegel des Befehls zu erlernen. Wirkt das Siegel des Befehls auf Euch selbst und schlagt dann eine Trainingsattrappe am Eingang zu Ambossar.", description = "Seid Ihr bereit? Wunderbar! Wir sind froh, dass Ihr hier seid.\n\nJe stärker Ihr werdet, desto näher kommt Ihr dem Licht und könnt neue Techniken lernen. Also zieht los und sammelt etwas Erfahrung. Zeigt mir dann, was Ihr gelernt habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24529] = {title = "Vom Regen in die Traufe", objective = "Rettet 5 eingesperrte Flüchtlinge aus Taurajo und tötet insgesamt 8 Dornenwirker oder Klingenwächter der Borstennacken.", description = "Als die Flüchtlinge von Taurajo aus nach Norden flohen, wurden einige von ihnen in der aufziehenden Dunkelheit von den anderen getrennt. Viele wurden von den Stachelebern der Borstennacken gefangen genommen, die ihre Lager im Westen und Südwesten von hier aufgeschlagen haben.\n\nIch weiß nicht, was die Stacheleber sich von uns erhofften, als sie unsere Flüchtlinge gefangennahmen - das Einzige, was sie sich dadurch zugezogen haben, ist mein Zorn. Und alles, was sie im Gegenzug erhalten werden, ist Rache.\n\nBefreit meine gefangenen Brüder und Schwestern und sendet den Stachelebern eine Botschaft, indem Ihr diejenigen tötet, die sie gefangen nahmen.", progress = nil, completion = "Es ist schlimm genug, wenn das eigene Dorf ausgeraubt wird... aber die nächste Nacht in einem Stacheleberkäfig zu verbringen? Ich bin froh, dass Ihr da wart, um zu helfen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24530] = {title = "Ah, das Leben eines Jägers", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen und verwendet ihn dann fünfmal bei den Trainingsattrappen vor dem Eingang nach Ambossar.", description = "Das Leben eines Jägers ist tief in Traditionen verwurzelt, wisst Ihr? Aufspüren mächtiger Bestien in wildem Terrain. Trinken. Die Lande bereisen, das Gewehr stets griffbereit. Trinken. Überleben dank Finesse, Mut und Instinkt, gefolgt von einem ordentlichen Schluck zu trinken.\n\nAber bevor wir zu den guten Sachen kommen, müsst Ihr die Grundlagen erlernen.\n\nGeht, macht Eure eigenen Erfahrungen und Ihr werdet lernen, mehr Dinge hinzukriegen. Und darauf trinken wir dann einen.", progress = "Ich weiß, das Leben eines Jägers ist jetzt schon aufregend, aber wartet nur ab... Es wird noch besser.", completion = "Nun, da Ihr einen neuen Jägertrick im Ärmel und ich etwas von Eurem Geld in der Tasche hab, geht da raus und erledigt ein paar Bestien! Kommt später wieder und wir reden weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24531] = {title = "Bereitmachen für die Schlacht", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen und verwendet es dann bei einer der Trainingsattrappen vor dem Eingang nach Ambossar.", description = "Lektion eins. Abgesehen von Eurem Schwert und Schild, was ist das wichtigste Utensil in Eurem Arsenal?\n\n<Thran wartet auf eine Antwort.>\n\nAch, macht nichts, ich werde für Euch antworten. Es ist Erfahrung.\n\nWenn Ihr erfahrener werdet, entdeckt Ihr neue Techniken. Was bedeutet, dass Ihr effektiver werdet - effektiver, als Ihr es Euch je hättet träumen lassen.\n\nGeht, sammelt Erfahrungen und erlernt etwas Neues. Kommt dann zurück und demonstriert es.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24532] = {title = "Den Gegner ausweiden", objective = "Erreicht Stufe 3 und erlernt das Ausweiden. Wendet es dann 3-mal auf die Trainingsattrappen vor dem Eingang nach Ambossar an.", description = "Wenn Ihr erst einmal mehr Erfahrung gesammelt habt, werdet Ihr feststellen, dass Ihr neue Techniken nutzen könnt. \n\nEines der Dinge, die Ihr lernen werdet, ist die Fähigkeit, eine Kombination von Kampfmanövern zu verwenden, um einen Gegner zu schwächen, um ihn dann mit einer vernichtenden Technik fertigzumachen.\n\nUnd jetzt macht Euch auf und sammelt Erfahrung. Wenn Ihr neue Techniken gelernt habt, probiert sie einfach an einer der Trainingsattrappen hier aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24533] = {title = "Worte der Macht", objective = "Erreicht Stufe 3, um das Schattenwort: Schmerz zu erlernen. Wirkt es dann 5-mal auf die Trainingsattrappen.", description = "Also, wenn Ihr wirklich etwas Besonderes werden wollt, solltet Ihr mit mir sprechen. Ein Priester ist ein Niemand ohne seine Zaubersprüche. Und wie könnt Ihr wohl neue Zauber lernen?\n\nIndem Ihr Erfahrung sammelt! Also zieht los, werdet stärker und kommt dann wieder zurück, um mir zu zeigen, was Ihr gelernt habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24534] = {title = "Ihre Sprache sprechen", objective = "Lasst das Horn der Herausforderung am Herausforderungsring der Borstennacken erschallen und besiegt Säbelschnauze in einem Einzelkampf.", description = "Die Stacheleber greifen uns an, weil sie Schwäche spüren. Stärke ist die einzige Sprache, die sie verstehen. Also werden wir ihnen Stärke zeigen.\n\n<Makaba zieht ein großes Horn aus seinem Beutel.>\n\nZugegeben, das hier ist primitive Arbeit, aber es wird reichen. Die Anführer der Borstennacken benutzen Hörner wie dieses, um sich gegenseitig zu Revierkämpfen herauszufordern.\n\n<Name>, ich möchte, dass Ihr Säbelschnauze, den Champion der Borstennacken, zu einem Einzelkampf herausfordert. Besiegt ihn vor den Augen seiner Anhänger. Lasst das Horn am Herausforderungsring der Borstennacken südlich von hier erschallen.", progress = "Habt Ihr den Borstennacken einen Dämpfer versetzt?", completion = "Wie bitte? Er hat Euch mit einem Dutzend Eber angegriffen? Anscheinend haben die Stacheleber ihre eigenen Vorstellungen, was \"Einzelkampf\" bedeutet.\n\nDennoch, die Borstennacken werden nach dem Schlag, den Ihr ihnen versetzt habt, aus der Bahn geworfen sein. Es wird nicht lange dauern, bis ein neuer Champion sich in ihren Reihen erhebt, um weiteren Ärger zu verursachen...doch bis dahin haben wir ein wenig Zeit gewonnen, um die Flüchtlinge in Sicherheit zu bringen.\n\nDanke, &lt;Name&gt;, die Überlebenden haben Euch viel zu verdanken.", rewards = "EberkalypsenstiefelSäbelschnauzes UmhangAuf Euch wartet eine dieser Belohnungen:\n\nHerausforderungsring der Borstennacken\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24535] = {title = "Thalorien Morgensucher", objective = "Besucht die sterblichen Überreste Thalorien Morgensuchers und erhaltet seinen Segen zum Führen Quel'Delars.", description = "Solltet Ihr Quel'Delar wirklich bei Euch tragen, <Name>, kann ich Euch vielleicht Zutritt zum Sonnenbrunnen verschaffen. Wenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Morgensucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", progress = "Seid Ihr an dem Ort gewesen, an dem Thalorien fiel, als er den Sonnenbrunnen verteidigte?", completion = "Ich gebe zu, dass ich nicht erwartet hätte, dass Thalorien Euch als Erben Quel'Delars anerkennt, aber ich respektiere sein Urteil. Ihr dürft zum Sonnenbrunnen gehen, doch ich erinnere Euch daran, dass Ihr an unserem allerheiligsten Ort zu Gast seid und Euch dementsprechend zu verhalten habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24536] = {title = "Irgendwas stinkt hier", objective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", progress = nil, completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n&lt;Er nimmt das Gerät an sich und hantiert damit herum.&gt;\n\nOh, das ist gar nicht gut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24539] = {title = "Wenn Pflanzen angreifen", objective = "Rettet 5 Flüchtling aus Taurajo, indem Ihr den klammernden Überwuchs tötet, der sie festhält.", description = "Dieses Camp wurde am Rande dieses Dschungels erbaut und ist bereits vollkommen von Pflanzen überwuchert. Irgendetwas Unnatürliches geht hier vor.\n\nVor Kurzem habe ich den Fehler gemacht, einige der gesunden Flüchtlinge hinauszuschicken, um Nüsse und Beeren zu sammeln. Diejenigen, die zurückkehrten, berichteten, dass die Pflanzen nach ihren Beinen gegriffen oder sie sogar hochgehoben hätten. Ich mache mir Sorgen um diejenigen, die noch nicht zurückgekehrt sind.\n\n<Klasse>, bitte rettet die Flüchtlinge, die in dem klammernden Überwuchs um das Camp herum festgehalten werden.", progress = nil, completion = "Danke, &lt;Name&gt;. Aber wenden wir uns nun der eigentlichen Frage zu:\n\nWo kommt dieser Überwuchs her? Und warum ist er so außer Kontrolle?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24540] = {title = "Kriegstanz", objective = "Besiegt Orno Grimmtotem in Steinkrallenpass.", description = "Unser Volk wird von vielen als Volk der sanftmütigen Riesen oder der edlen Wilden angesehen. Sie haben nie gesehen, wie wir uns gegenseitig bekämpfen... wie wir Verräter aus eigenen Reihen bekämpfen.\n\nDen Grimmtotem wurde durch das Exil Gnade erteilt, doch sie haben ihre Heimat verletzt, um Rache an uns zu üben. Wir werden sie in Mulgore nicht länger akzeptieren.\n\nIch habe bereits Krieger geschickt, um sie durch den Steinkrallenpass nördlich von hier zu schicken. Unsere Krieger sind sehr mutig im Kampf, <Name>. Ich möchte, dass Ihr Euch diesem Kampf anschließt. Geht und helft unseren Kriegern, die Grimmtotem endlich zu vertreiben.", progress = nil, completion = "Willkommen zurück, &lt;Name&gt;.\n\n\n\nWas getan wurde, war weder aus Rache, noch aus Stolz. Es war einzig und allein zum Schutz Donnerfels', zum Schutz unseres Volkes vor Qualen und Angst. Heute ist Mulgore wieder ein sicherer Ort.\n\nDie Erdenmutter dankt Euch für all Eure mutigen Taten, &lt;Name&gt;, und auch ich danke Euch. Ihr habt für Euer heldenhaftes Verhalten eine Belohnung verdient. Ihr sollt für immer in Donnerfels willkommen sein.", rewards = "Verkümmerte BaumwurzelKodohammerBetäuber des SonnenläufersTraumwandelnder StabIhr bekommt:\n\nKodosatteltasche"}
MultiLanguageQuestData['de'][24541] = {title = "Parfümdiebstahl", objective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Orgrimmars, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", progress = "Haben sie Euch eine Kiste zum Ausliefern zugeworfen?", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n&lt;Er öffnet die Kiste und untersucht den Inhalt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24542] = {title = "Eine seltsame Blüte", objective = "Sammelt zehn ungewöhnliche Blütenknospen von knospenden Blüten in der Überwucherung auf.", description = "Der große Erzdruide Naralex ist vor Kurzem hier im Brachland erschienen. Entweder steckt er hinter diesem Chaos, oder er versucht, es wieder in Ordnung zu bringen. Wie auch immer - Ihr solltet mit ihm sprechen, bevor dieser Dschungel die ganze Welt einhüllt. Naralex befindet sich in einem kleinen Taurenlager im Südosten.\n\nEs wäre hilfreich, wenn Ihr unterwegs Pflanzenproben sammeln könntet, damit er sie studieren kann. Die neuesten Blumensamen werden ihm viel über die jüngsten Veränderungen im Dschungel sagen.", progress = "Ich bin sehr beschäftigt, <Klasse>.", completion = "Ah, Proben von verschiedenen Bereichen der Überwucherung? Ja, die werden ausgesprochen hilfreich sein. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24543] = {title = "Eine gespaltene Familie", objective = "Findet Kirge Sternhorn an der Vendettakuppe im Südlichen Brachland.", description = "Die Kinder, die Ihr hier seht, wurden alle aus Taurajo gerettet, als die Kämpfe ausbrachen. Ich versuche, ihre Eltern zu finden.\n\nEiner der Flüchtlinge, die Ihr von den Stachelebern gerettet habt, hat das stärkste Kind erkannt. Es gehört zu Kirge und Mawre Sternhorn. Außerdem sagte er, dass Kirge bei den Feldern des Blutes etwas nördlich des Ortes, an dem das Massaker von Taurajo stattfand, lagert.\n\n<Name>, bitte geht dorthin und sagt Kirge Sternhorn, dass sein Kind lebt und es ihm gut geht!", progress = nil, completion = "&lt;Kirge hört angestrengt zu und fällt dann auf ein Knie.&gt;\n\nAm Leben! Mein Junge lebt noch! Lobet die Erdenmutter - ich habe immer noch einen Sohn.\n\n&lt;Kirge gewinnt seine Fassung zurück.&gt;\n\n&lt;Klasse&gt;, die Mutter meines Jungen hat es nicht lebend aus Taurajo herausgeschafft. Ich werde ihren Tod rächen, selbst wenn das bedeutet, dass mein Sohn dann vielleicht ohne seine Eltern aufwachsen muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24545] = {title = "Die Heiligen und die Verderbten", objective = "Platziert Lichträcher, 25 Einheiten urtümliches Saronit sowie Modermienes und Fauldarms ätzendes Blut in Hochlord Mograines Runenschmiede in der Eiskronenzitadelle.\n\nModermienes ätzendes Blut und Fauldarms ätzendes Blut sind nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle erhältlich.", description = "Ich verwahre mich dagegen, Euch diesen Auftrag zu erteilen, <Volk>, da er Euch wahrscheinlich ins Verderben führt.\n\nWenn Ihr nichts auf meine Einschätzung gebt und Euch der Aufgabe stellt, werde ich Euch mit dem Wissen und den Ressourcen vertraut machen, die dazu notwendig sind.\n\nIhr müsst in die Frostgramhöhlen zurückkehren und Lichträcher, Arthas' abgelegten Hammer, finden. Neu geschmiedet aus Saronit und geschärft mit dem ätzenden Blut der Monstrositäten des Lichkönigs, wird er die Grundlage unserer Arbeit bilden.", progress = "Je näher man kommt, umso bedrohlicher scheint das Feuer der Schmiede zu lodern...", completion = "Ein überwältigendes Gefühl von Furcht ergreift von Euch Besitz, als die Flammen die Gegenstände verschlingen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMograine Forge\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24546] = {title = "Eine Linie im Schmutz", objective = "Erobert einen neutralen Hügel in den Feldern des Blutes und verteidigt ihn gegen den Gegenangriff der Allianz.", description = "Die Allianz brennt eine Spur der Morde quer durch das Brachland. Wir müssen sie hier aufhalten oder es wird nichts für uns übrig bleiben.\n\nAuf den Feldern des Blutes gibt es eine Anzahl strategisch wichtiger Hügel, auf denen Holztürme und neutrale graue Banner stehen. Wir müssen diese Hügel einnehmen und halten, wenn wir den Vorstoß der Allianz aufhalten wollen!\n\nHaltet Ausschau nach den Türmen im Norden, Osten und Süden von dem, was von Taurajo übrig geblieben ist. Schnappt Euch eine neutrale Flagge und verteidigt den Hügel gegen die Gegenangriffe!", progress = nil, completion = "Ihr habt Euch also behauptet! Mit Eurer Beharrlichkeit könnten wir es noch schaffen, die Allianz aus unseren Landen zu vertreiben.", rewards = "Roben des blutigen FeldesSternhorns SchildGamaschen von TaurajoIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24547] = {title = "Ein Seelenschmaus", objective = "Hochlord Darion Mograine möchte, dass Ihr mit Schattenschneide 50 Diener des Lichkönigs in der Eiskronenzitadelle tötet. Die Seelen sind in den Schwierigkeitsgraden für 10 oder 25 Mann erhältlich.", description = "Schattenschneide ist eine der besten Waffen, in deren Besitz <ein/eine:c> <Klasse> kommen kann.\n\nIst Eure Machtgier nun befriedigt, <Volk>?\n\n<Ihr fühlt Mograines eindringlichen Blick.>\n\nDas dachte ich mir. Dann noch eine letzte Warnung...\n\nNun beginnt der tückischste Teil Eurer Aufgabe. Zügelt Euer Bestreben, denn wenn Eure Ziele nicht rein sind, werdet Ihr Euer Leben, ja, Eure Seele verlieren.\n\nDie Waffe in Euren Händen ist nichts weiter als eine leere Hülle, ein bloßer Schatten dessen, zu was sie werden kann.", progress = nil, completion = "&lt;Hochlord Mograine blickt Euch eine Weile stumm an.&gt;\n\nIhr scheint diesen Teil Eurer Prüfung mit Bravour bestanden zu haben, &lt;Volk&gt;.\n\nBetet, dass Euch das Glück in Euren Bestrebungen weiterhin hold bleibt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24548] = {title = "Der zersplitterte Thron", objective = "Hochlord Darion Mograine möchte, dass Ihr 50 Schattenfrostsplitter sammelt.\n\nSchattenfrostsplitter sind nur im Schwierigkeitsgrad für 25 Mann erhältlich.", description = "Der Thron des Lichkönigs war einst sein Gefängnis. Kil'jaeden höchstselbst hat das Behältnis aus Eiskristallen aus dem Wirbelnden Nether gefertigt. Sein alleiniger Zweck war es, Ner'zhuls rachsüchtigen Geist festzuhalten.\n\nIndem er den Kristall mit Frostgram berührte, befreite Arthas Ner'zhuls Seele und ließ sie mit seiner eigenen verschmelzen. Die Splitter dieses Zusammenstoßes sind jetzt überall in der Zitadelle verteilt.\n\nIch brauche die Scherben, die wir nur von den mächtigsten Dienern des Lichkönigs bekommen können, um die in Eurer Klinge enthaltene Kraft zu versiegeln.", progress = "Habt Ihr die Splitter des Frostthrons besorgt, <Klasse>?", completion = "Das sollte genügen, &lt;Klasse&gt;.\n\nKommt zu mir, wenn Schattenschneide mit ihren Kräften ausgestattet wurde, und ich werde versuchen, sie zu vervollständigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24549] = {title = "Schattengram...", objective = "Hochlord Darion Mograine möchte, dass Ihr ihm Schattenschneide bringt.", description = nil, progress = nil, completion = "Ich gratuliere, &lt;Klasse&gt;.\n\nEntgegen aller unüberwindbaren Hindernisse habt Ihr den Sturm überstanden.\n\nIch vertraue darauf, dass Ihr Eure Belohnung als angemessen empfinden werdet...", rewards = "Ihr bekommt:\n\nSchattengram"}
MultiLanguageQuestData['de'][24550] = {title = "Reise nach Donnerfels", objective = "Sprecht mit Baine Bluthuf in Donnerfels.", description = "Die Brunnen wurden gereinigt und die Wasser in Mulgore fließen wieder sauber und süß. Ihr habt uns gerettet... aber auch die auf die Grimmtotem zurückzuführenden Geschehnisse zu Tage gebracht. Die Taten der Grimmtotem müssen bekannt gemacht werden.\n\nDie Zeit ist für Euch gekommen, nach Donnerfels zu reisen, unserer großen Stadt auf der Anhöhe. Geht zu unserem Anführer, Baine Bluthuf, Sohn des Cairne. Er muss davon erfahren.", progress = nil, completion = "Willkommen in Donnerfels, &lt;Name&gt;. Ihr habt für unser Volk viel Gutes getan.\n\nErzählt mir von Eurer Reise.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24551] = {title = "Der neue Boss", objective = "Tötet Aufklärer der Nordwacht und nehmt ihnen 10 Verdienstabzeichen von Theramore ab.", description = "Unter Gar'duls Kommando ist die Verteidigung des Brachlandes nicht sehr erfolgreich verlaufen, <Name>. Garrosh hat Kriegsfürst Blutheft hierher entsandt, um die Sache in die Hand zu nehmen. Er ist hier im Camp und wenn Ihr einen guten Eindruck hinterlassen wollt, solltet Ihr etwas Initiative zeigen.\n\nGeht nach Osten in die Felder des Blutes und findet Aufklärer der Nordwacht. Wenn Ihr dem neuen Kriegshäuptling einen Stapel ihrer Verdienstabzeichen bringt, werdet Ihr Euch sicherlich einen Namen machen!", progress = "Ihr seht wie ein <Volk> aus, der sich durchsetzen kann. Welche Neuigkeiten bringt Ihr aus den Feldern?", completion = "&lt;Blutheft schaut sich die Abzeichen an und lässt sie dann aus seinen Händen auf den Sandboden fallen. Seine Lippen verziehen sich zu einem breiten Grinsen.&gt;\n\nDAS sehe ich doch gerne, &lt;Klasse&gt;! Wie heißt Ihr noch gleich?\n\nIhr werdet es hier weit bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24552] = {title = "Der Stolz des Löwen", objective = "Tötet insgesamt 5 Ebenenstreuner oder Ebenenstolzmähnen.", description = "Wenn Ihr Rache an den Eindringlingen der Allianz nehmen wollt, seid Ihr gut beraten, die gefährlichsten Raubtiere im Brachland zu beobachten.\n\nDie Löwen, die sich durch das hohe Gras schleichen, sind gerissen, gut getarnt und mächtig. Nehmt Euch an ihnen ein Beispiel und Ihr werdet verstehen, welche Art Krieg wir führen müssen.\n\nJagt die Ebenenstreuner und -stolzmähnen. Dann kehrt zu mir zurück und wir unterhalten uns darüber, was Ihr gelernt habt. Ihr werdet sie oft im Schatten großer Bäume antreffen.", progress = nil, completion = "Ah ja... Ich sehe eine Gerissenheit in Euren Augen, die dort vorher nicht zu finden war. Gut gemacht, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFuror des Löwen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24553] = {title = "Die Reinigung Quel'Delars", objective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt, und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Die Klinge wird sich an Euch binden. Wenn das passiert, tragt sie zu Caladis Prunkspeer in Qel'Delars Ruh.", progress = "Was ist Euch beim Sonnenbrunnen widerfahren?", completion = "Das ist unglaublich, &lt;Name&gt;! Ihr habt es tatsächlich geschafft! Alle Quel'dorei kennen die Geschichte von Thalorien Dämmersucher und Quel'Delar, aber keiner hätte je geglaubt, dass das Schwert wiederhergestellt werden würde.", rewards = nil}
MultiLanguageQuestData['de'][24554] = {title = "Der ramponierte Schwertgriff", objective = "Bringt den ramponierten Schwertgriff zu Myralion Sonnenfeuer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Die Sonnenhäscher wären sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", progress = "Was habt Ihr entdeckt?", completion = "&lt;Myralion nimmt den Schwertgriff an sich und inspiziert das Artefakt.&gt;\n\nDas habt Ihr aus der Zitadelle? Was hat es dort gemacht? Diese Klinge ist gewiss kein Erzeugnis der Geißel.\n\nWaffen dieser Qualität können nur von einigen wenigen Geschöpfen Azeroths hergestellt werden. Wir müssen mit ihnen in Verbindung treten und sehen, ob sie uns bei der Identifizierung der Waffe behilflich sein können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24555] = {title = "Das Wissen der Drachen", objective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", description = "Dieser Schwertgriff stammt ganz eindeutig von einer sehr alten, sehr mächtigen Waffe. Nur von welcher? Diese Muster sind mir unbekannt, doch wir haben unsere Möglichkeiten noch nicht ausgeschöpft.\n\nKorialstrasz, besser bekannt als Krasus, ist schon lange Zeit mit den Quel'dorei und den Kirin Tor befreundet. Mit seinem umfangreichen Wissen und seinen Beziehungen kann er uns sicher weiterhelfen. Reist zur höchsten Ebene des Wyrmruhtempels und bittet ihn um Rat, meldet Euch dann bei Magister Hathorel in Sonnenhäschers Zuflucht in Dalaran.", progress = nil, completion = "Wir müssen uns das Buch vom Silberbund wiederbeschaffen. Ohne das Buch von Krasus haben wir kaum eine Chance, das Rätsel um das Schwert in Eiskrone zu lösen oder seine Macht freizusetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24556] = {title = "Eine passende Verkleidung", objective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", description = "Euch ins Innere der Silbernen Enklave zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock des Silberbunds verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", progress = "Konnte Shandy Euch helfen, an einen Wappenrock des Silberbunds heranzukommen?", completion = "Ich wusste, dass Shandy einen Weg finden würde. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Mit etwas Glück wird der Besitzer des Wappenrocks nicht einmal bemerken, dass er verschwunden ist, und Shandy wird unsere Spuren beseitigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24557] = {title = "Der Plan des Silberbunds", objective = "Besorgt die Befehle des Silberbunds.", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Taverne \"Zur Zauberkrähe\" einen Agenten des Silberbunds erblickt. Die Mitglieder des Silberbunds sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und schaltet ihn aus. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass ihn diese albernen Schwächlinge vom Silberbund zuerst zurück nach Eiskrone bringen.", progress = "Konntet Ihr irgendetwas Brauchbares bei diesem Agenten finden?", completion = "&lt;Magister Hathorel liest die erbeuteten Befehle.&gt;\n\nDer Agent, den Ihr abgefangen habt, sollte in der Silbernen Enklave jemanden namens Arkanist Tybalin treffen und dann den Folianten vom Wyrmruhtempel nach Eiskrone bringen. Wie müssen das Buch zurückbekommen, &lt;Name&gt;, und es gibt nur eine Möglichkeit, solange es sich noch in der Stadt befindet. Jetzt ist schnelles Handeln gefragt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24558] = {title = "Rückkehr zu Myralion Sonnenfeuer", objective = "Bringt den Folianten \"Uralte drachengeschmiedete Klingen\" zu Myralion Sonnenfeuer in Quel'Delars Ruh.", description = "Wir müssen dieses Buch zu Myralion Sonnenfeuer bringen. Würdet Ihr das übernehmen? Ich kann diese Aufgabe sonst niemandem anvertrauen, und Ihr habt Geschick darin bewiesen, die Leute vom Silberbund zu meiden.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Myralion wird Euch dort erwarten. Wenn er die Klinge identifizieren kann, können wir sie im Namen Aethas Sonnenhäschers beanspruchen und Dalaran und der Allianz zeigen, dass wir den Angriff auf den Lichkönig anführen werden.", progress = "Wir hatten Eure Rückkehr schon erwartet. Was hat Euch aufgehalten?", completion = "&lt;Myralion nimmt das schwere Buch zur Hand und beginnt, darin zu blättern.&gt;\n\nDie Symbole auf der Klinge kamen mir bekannt vor und jetzt weiß ich auch, warum. Das ist zweifellos eine Drachenklinge, die einem der sterblichen Völker zum Geschenk gemacht wurde. Nur um welche Klinge handelt es sich und wie ist sie nach Eiskrone gelangt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24559] = {title = "Das Schwert neu schmieden", objective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und verbindet sie mit den Überresten Quel'Delars, um das Schwert wiederherzustellen.", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, der Behauptung Blutkönigin Lana'thels zum Trotz! Jetzt muss die Klinge nur noch getempert werden, bevor wir ihr beweisen können, wie töricht ihre Worte doch waren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24560] = {title = "Die Klinge tempern", objective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die Gefrorenen Hallen.", progress = "Solange das Schwert nicht getempert ist, ist es nutzlos.", completion = "Das Tempern des Schwertes sollte die Klinge wiederhergestellt haben. Warum hat es nicht funktioniert?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24561] = {title = "Die Hallen der Reflexion", objective = "Bringt Quel'Delar nach Schwertruh in den Hallen der Reflexion.", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den Gefrorenen Hallen auf Euch.", progress = "Was ist in den Hallen der Reflexion geschehen?", completion = "Wie kann sich das Böse in solch einem Schwert einnisten? Ich hätte das nicht für möglich gehalten, wenn sich der Beweis nicht direkt vor meinen Augen befände. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nIch glaube, Uther hat Recht. Ihr müsst seinem Rat schnell folgen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24562] = {title = "Reise zum Sonnenbrunnen", objective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, <Name>! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", progress = "Was führt Euch hierher?", completion = "Ich hoffe, Ihr habt Verständnis dafür, dass ich Euch nicht einfach so Zutritt zum Sonnenbrunnen gewähren kann, &lt;Name&gt;. Dies ist der heiligste den Sin'dorei bekannte Ort, und wir haben erst kürzlich Kontrolle über ihn zurückerlangt.\n\nIhr wollt unserem Volk mit Märchen über Quel'Delar Hoffnungen machen? Ohne Beweis für die Wahrhaftigkeit Eurer Behauptungen sehe ich keine Veranlassung, Euch Glauben zu schenken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24563] = {title = "Thalorien Morgensucher", objective = "Besucht die sterblichen Überreste Thalorien Morgensuchers und erhaltet seinen Segen für den Gebrauch Quel'Delars.", description = "Ihr arbeitet mit Myralion Sonnenfeuer zusammen, nicht wahr? Ich weiß, wie wir das Schwert testen können.\n\nWenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Morgensucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", progress = "Seid Ihr an dem Ort gewesen, an dem Thalorien fiel, als er den Sonnenbrunnen verteidigte?", completion = "Ihr tragt wirklich Quel'Delar bei Euch. Heute ist ein großer Tag für ganz Quel'Thalas und die Sin'dorei! Ihr habt meine Erlaubnis, zum Sonnenbrunnen zu gehen und die Wiederherstellung des Schwertes abzuschließen. Lasst den Kopf nicht hängen, &lt;Name&gt;. Die Söhne und Töchter Silbermonds haben viele Jahre auf diesen Tag gewartet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24564] = {title = "Die Reinigung Quel'Delars", objective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, <Name>.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", progress = "Was ist beim Sonnenbrunnen geschehen?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Dämmersuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", rewards = nil}
MultiLanguageQuestData['de'][24565] = {title = "Biologischer Eingriff", objective = "Tötet 5 Deviatschreckenszähne und 5 Deviatebenenschreiter.", description = "Die Energien, die hier freigesetzt wurden, sind durch die Wildtiere geflossen. Dadurch wurden sie mächtig und instabil. Wenn wir zulassen, dass sie sich über diesen Hain hinaus ausbreiten, werden diese Mutationen eine katastrophale Auswirkung auf das Ökosystem haben, die Beutetiere verschlingen und die schwächeren, natürlichen Kreaturen vertreiben.\n\nIhr müsst gehen und bei dem Bestand der Überwucherung eine Auslese treffen. Kehrt zurück, wenn diese Aufgabe erfüllt ist.", progress = nil, completion = "Danke, &lt;Name&gt;. Ich bin froh, dass Ihr unverletzt zurückgekehrt seid; die Bösartigkeit dieser Kreaturen ist wirklich erschreckend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24566] = {title = "Aussaat einer Lösung", objective = "Benutzt die beruhigenden Samen bei 6 Deviatschreckenszähnen oder Deviatebenenschreitern und beobachtet die Ergebnisse.", description = "Aufgrund dessen, was Ihr mir überbracht habt, denke ich, dass wir vielleicht eine Lösung haben. Ich hab die Peitschenrankensamen mit heilenden Energien erfüllt.\n\nEinfacher Kontakt mit ihnen sollte den Kreaturen hier genug Energie verleihen, um den verderbnisreichen Einfluss abzuschütteln.\n\nGeht und versucht, die mutierten Raptoren und Ebenenschreiter zu heilen, indem Ihr die Samen über sie streut. Dann berichtet mir von dem Ergebnis.", progress = nil, completion = "Oh weh! Anscheinend sind die Kräfte, die hier am Werk sind, schwer unter Kontrolle zu bringen...\n\nBitte behelligt Naralex nicht damit. Es wird ihn nur aufregen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24567] = {title = "Meldet Euch für ein Testspiel", objective = "Sprecht mit Trainer Blutgrätsch auf dem Kajarofeld auf Kezan.", description = "<Name>, Trainer Blutgrätsch, der Kopf unserer furchtlosen Bilgewasserbukaniere, sucht Euch.\n\nEr sagt, dass der Ligatitel gegen die Dampfdruckhaie in Gefahr ist und dass nur Ihr den Pokal nach Hause holen könnt!\n\nGeht nach Westen in die Stadt. Ihr könnt das Kajarofeld nicht verfehlen.\n\nEin Fußbombenstar. Das wird sich hervorragend auf Euer Image auswirken!", progress = nil, completion = "Da seid Ihr ja, mein Junge! Schnell, wir haben keine Zeit zu verlieren! Wir müssen diese Schredder wieder funktionstüchtig machen.\n\nIch hole Euch von der Ersatzbank… Ihr werdet das Spiel und den Titel für uns gewinnen!", rewards = nil}
MultiLanguageQuestData['de'][24568] = {title = "Zu den Mauern!", objective = "Sprecht mit Winnoa Kiefernwald an den Feldern des Blutes, um die Tore von Mulgore gegen den Angriff zu verteidigen.", description = "<Name>, sie versammeln sich an den Toren! Die Allianz versucht, nach Mulgore hineinzudrängen. Ihre Fußsoldaten versuchen, die Wachen zu überwältigen.\n\nWir haben so wenig, womit wir die Mauern verteidigen können. Wir haben kochendes Wasser in Töpfen, um die Angreifer in Schach zu halten, bis Hilfe eintrifft... Das muss reichen.\n\nAber wir brauchen jemand, der unsere Verteidigung organisiert. Ihr müsst nur ein Wort sagen und ich werde Euch zu einer Übersicht aus der Vogelperspektive über das Schlachtfeld verhelfen.\n\nWir brauchen Euch, <Name>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24569] = {title = "Belagerungsbrecher", objective = "Zerstört 4 Belagerungsmaschinen der Nordwacht vor den Toren von Mulgore.", description = "<Name>, Ihr habt Euch auf den Feldern des Blutes als würdig erwiesen. Aber die Allianz bedroht immer noch unsere Taurenfreunde.\n\nDie Belagerungsmaschinen außerhalb der Tore von Mulgore sind wie Speere, die direkt auf unsere Herzen zielen. Ich möchte, dass Ihr zu den Toren südlich von uns geht und diese Belagerungsfahrzeuge aus dem Spiel nehmt.\n\nHier, benutzt die Haftbomben. Wir haben sie freundlicherweise von unseren neuen Goblinverbündeten bekommen. Sieht so aus, als ob sie Schwarzpulver in... es sieht aus wie... ölverschmierte Socken gestopft haben. Aber die werden schon reichen.", progress = "Warum hat Gar'dul zugelassen, dass die Allianz so viele schwere Belagerungsmaschinen aufstellt? Warum wurde kein Gegenschlag angeordnet, bevor ich hier eintraf? Gar'dul wird sich dafür noch rechtfertigen müssen...", completion = "Sehr gut! Jetzt werden sie wohl mit Infanterie auf die Tore losstürmen müssen.\n\nGlaubt Ihr, sie haben den Mumm dazu?", rewards = "BluthefthandschuheSchmierfettbedeckte StiefelSchäbiger GoblinstabLötzinnschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24570] = {title = "Schlangenabzug", objective = "Besorge 5 entkräftete Ottern.", description = "Die Verderbnis, die hier entfesselt wurde, muss eingehend erforscht werden, wenn wir einen wirksamen Weg finden wollen, sie zu bekämpfen.\n\nZum Glück haben sich hier nicht alle Kreaturen gleichermaßen verändert. Die kleineren Schlangen trinken wenig Wasser und fressen keine Pflanzen, also sind sie den Energien nur in geringem Maße ausgesetzt worden. Dennoch haben sie genug aufgenommen, um ihre Farbe zu verändern.\n\nGeht, sammelt einige dieser Schlangen aus der Überwucherung und bringt sie zu mir, damit wir sehen können, was genau mit den Kreaturen hier geschieht.", progress = "Habt Ihr genügend eingesammelt? Wir benötigen einige, um aussagekräftige Vergleiche anstellen zu können.", completion = "Die sind genau richtig. Bunte Farben wie diese entstehen im Brachland nicht auf natürliche Weise, aber bisher haben sich bei ihnen noch keine weiteren Mutationen herausgebildet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24571] = {title = "Peitschenrankensamen", objective = "Besorgt 4 zuckende Samen von Peitschenranken.", description = "Es muss einen Weg geben, diese armen Kreaturen zu heilen, ohne ihnen das Leben zu nehmen. Ich habe eine Idee, aber ich brauche Eure Hilfe, <Klasse>.\n\nDie Pflanzen der Peitschenranke, die hier umherstreifen, enthalten Samen prallvoll mit der urtümlichen Energie dieses Ortes. Sammelt sie für mich ein und bringt sie hierher, dann sehen wir, was man tun kann.", progress = "Habt Ihr die Samen?", completion = "Es beunruhigt mich, wie ... aktiv sie sind. Dennoch bedeutet das nichts anderes, als dass wir schnell handeln müssen, bevor die Verderbnis hier noch schlimmer wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24572] = {title = "Taurajo zurückerobern", objective = "Tötet 8 Plünderer von Taurajo in den Überresten von Camp Taurajo.", description = "Ausgezeichnete Arbeit dort an den Toren, <Name>! Der größte Teil der Streitkräfte der Allianz befindet sich auf dem Rückzug. Aber das genügt mir nicht.\n\nSie haben Taurajo geplündert, das nur ein einfaches Lager der Jäger war. Die \"Allianz\" wurde demaskiert und man weiß jetzt, was sie wirklich ist: Eine Bande abtrünniger Schlächter.\n\nSogar jetzt lungert eine Gruppe Menschen dort herum und wühlt in den Knochen des noch schwelenden Taurajo herum.\n\n<Blutheft schleudert eine Axt in den Staub.>\n\nSie sollen leiden.", progress = nil, completion = "Ausgezeichnet. Ich werde ihre Leichen entlang der Goldstraße als Botschaft für die Allianz aufhängen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24573] = {title = "Die Toten ehren", objective = "Benutzt das Bestattungstotem an den Leichnamen von Krulmoo, Dranh, Yonada und Omusa in den Überresten von Camp Taurajo.", description = "Jetzt, da die unmittelbare Bedrohung vorüber ist, könntet Ihr bei einer traurigen Aufgabe helfen?\n\nWir Tauren beerdigen unsere Toten nicht, wir bereiten ihre Körper auf die Rückkehr zu den Elementen vor und bringen sie zu unseren heiligen Grabstätten. Diejenigen, die während des Taurajomassakers getötet wurden, wurden nicht bestattet und ich fürchte, dass fehlgeleitete Soldaten der Allianz die Körper der Toten verbrennen, bevor die richtigen Rituale durchgeführt wurden.\n\n<Name>, bitte bringt dieses Totem nach Taurajo und führt die Bestattungszeremonie für Krulmoo, Dranh, Yonada und Omusa durch. Sie... haben es dort nicht herausgeschafft.", progress = "Haben ihre Geister ihren Frieden mit der Erdenmutter gemacht?", completion = "&lt;Winnoa neigt ihren Kopf.&gt;\n\nDanke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24574] = {title = "...wird Chaos ernten", objective = "Tötet 5 Auswüchse und findet ein sich windendes Herz.", description = "Wenn ich wirklich Chaos gesät habe, wird es Zeit für mich, die Ernte einzubringen.\n\nDie schwerfälligen Auswüchse der Pflanzenwelt schlurfen durch den magieerfüllten Strom hier, <Name>. Sie sind eine Manifestation der instabilen Kräfte, die diese Gegend verändern. Tötet so viele Ihr könnt und vielleicht können wir die weitere Verbreitung der Überwucherung verlangsamen.\n\nUnd wenn Ihr schon dabei seid... ich suche nach Teilen von ihnen, die besonders befallen erscheinen. Bringt solche Teile zu mir.", progress = "Die Auswüchse zu beschneiden, wird uns höchstens etwas Zeit verschaffen. Habt Ihr irgendwelche verdächtigen Teile gefunden?", completion = "&lt;Naralex nimmt langsam das sich windende Herz aus Euren Händen und ist sichtlich verstört.&gt;\n\nIch war ein Narr. Die eine Wahrheit, die ich nicht akzeptieren wollte, hat mir die ganze Zeit ins Gesicht gestarrt...dieses widerwärtige Ding ist der Beweis dafür.\n\nWir beide haben viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24575] = {title = "Befreiung", objective = "Befreit 5 versklavte Dorfbewohner in der Glutsteinmine.", description = "Wir haben kürzlich herausgefunden, dass die Dorfbewohner in Glutstein die schlimmsten Verheerungen des Fluchs überlebt haben.\n\nLeider hatte ihr Dorf beim Einmarsch der Verlassenen nicht so viel Glück.\n\nDie Verlassenen haben die Dorfbewohner gefangen genommen und zwingen sie, in der nahegelegenen Mine als Sklaven zu arbeiten.", progress = "Habt Ihr die Dorfbewohner befreit, <Name>? Ich kann mir nicht vorstellen, welche Qualen Sie unter den Verlassenen erleiden müssen.", completion = "Ihr habt es wieder geschafft, &lt;Name&gt;. Die befreiten Dorfbewohner wollen uns mit allen Kräften im Kampf gegen die Verlassenen unterstützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24576] = {title = "Eine nette Unterhaltung...", objective = "Begebt Euch zum Zeppelinturm auf dem zentralen Hügel in Orgrimmar und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", description = "<Roka hört widerwillig zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, ich hätte die ganze Zeit unter dem Einfluss eines Alchemisten gestanden? Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin! Wenn ich diesen hinterhältigen Goblin jemals in die Finger kriege, reiß ich ihn in Stücke!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Zeppelinturm inmitten Orgrimmars! Was auch immer Ihr tut, <Name>, Ihr dürft ihn nicht an Bord des Zeppelins und davonkommen lassen!\n\nBeeilt Euch, geht zum Zeppelinturm, bevor Ihr ihn verpasst!", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, &lt;Name&gt;! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24577] = {title = "Überprüfung der Ödnisfeste", objective = "Sprecht mit Kriegsfürst Blutheft, dann reitet zur Ödnisfeste und informiert Gar'dul, dass Kriegsfürst Blutheft unterwegs zu ihm ist.", description = "Euch haben wir es zu verdanken, dass die unmittelbare Bedrohung vorüber ist. Aber meine Arbeit hier im Brachland ist nur der Anfang.\n\nEhrenwacht wurde erobert und Taurajo geplündert, während Kriegsherr Gar'dul noch das Sagen in der Region hatte. Der Kriegshäuptling hat mich geschickt, um das Chaos hier zu beseitigen.\n\nIch möchte, dass Ihr als meine Vorhut zur Ödnisfeste im Süden reitet und Gar'dul wissen lasst, dass es Zeit für eine Abrechnung ist.\n\nSprecht mich an, wenn Ihr bereit seid, aufzubrechen und ich werde meinen Vortrupp zusammentrommeln, damit er Euch begleitet.", progress = nil, completion = "&lt;Gar'dul bricht der Schweiß aus.&gt;\n\nHört mal, äh, lasst uns das nicht hier vor all den Leuten besprechen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24578] = {title = "Der Schwarzforst", objective = "Untersucht die Bradshawmühle direkt außerhalb von Sturmsiel.", description = "Es hat ein wenig gedauert, aber ich glaube, ich habe endlich herausgefunden, was hier passiert ist. Zumindest teilweise.\n\nIn dieser Stadt gab es einige Überlebende der Seuche. Sie haben sich alle den anderen in den Bergen angeschlossen, an der Witterfront.\n\nAlle sind geflohen, bis auf den Mann, der dieses Tagebuch geführt hat, der alte Bradshaw. Er bemerkte, dass die Angriffe der Worgen plötzlich aufgehört hatten, und entschloss sich, in den Schwarzforst zu reisen.\n\nDirekt nordwestlich der Stadt gibt es eine verlassene Mühle. Dort lebte Bradshaw früher. Schaut Euch da nach Hinweisen um.", progress = nil, completion = "Ich habe Euch erwartet, &lt;Name&gt;. Habt keine Angst.\n\nMein Name ist Belysra. Ich bin eine Priesterin des Mondes… eine Nachtelfe.\n\nIhr kennt Meinesgleichen vielleicht nicht, aber seit der Fluch Euch befiel sind die Schicksale unserer Völker miteinander verbunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24579] = {title = "Sartharion muss sterben!", objective = "Tötet Sartharion.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Sartharion, der Onyxwächter, hütet die Eier des Zwielichtdrachenschwarms. Er hält sich im Obsidiansanktum in der Kammer der Aspekte unterhalb des Wyrmruhtempels auf.\n\nDer Rat der Sechs hat verfügt, dass Sartharion sterben muss!", progress = nil, completion = "Jetzt, wo Sartharion tot ist, werden Todesschwinges und Sinestras Pläne bestimmt ins Stocken geraten.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24580] = {title = "Anub'Rekhan muss sterben!", objective = "Tötet Anub'Rhekan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Anub'Rekhan, einst mächtiger Spinnenfürst im Nerubischen Reich, ist in die Fänge des Lichkönigs geraten, der ihn zu einem Untoten machte.\n\nJetzt fristet er sein Dasein als Gruftlord in seinem Domizil im Arachnidenviertel von Naxxramas und ersinnt Strategien für Kel'Thuzad.\n\nDer Rat der Sechs hat verfügt, dass Anub'Rekhan sterben muss!", progress = nil, completion = "Der Bericht über Euren Erfolg eilt Euch voraus, &lt;Klasse&gt;. Anub'Rekhan ist Geschichte. Ihr habt ihm einen großen Dienst erwiesen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des TriumphsEmblem des Frosts"}
MultiLanguageQuestData['de'][24581] = {title = "Noth der Seuchenfürst muss sterben!", objective = "Tötet Noth den Seuchenfürst.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Noth der Seuchenfürst, Verräter und Feigling! In der Anzahl gegeißelter Seelen folgt er gleich hinter dem Lichkönig selbst.\n\nBegebt Euch schleunigst nach Naxxramas. Dort hält er sich im Seuchenviertel hinter seiner untoten Dienerschaft versteckt.\n\nVernichtet ihn! Der Rat der Sechs hat verfügt, dass Noth sterben muss!", progress = nil, completion = "Eine Sorge weniger... Jetzt, wo Noth tot ist, wird auch die Forschung der Geißel nach verbesserten Methoden zur Erschaffung Untoter ein Ende haben.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24582] = {title = "Instrukteur Razuvious muss sterben!", objective = "Tötet Instrukteur Razuvious.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Instrukteur Razuvious stolziert selbstgefällig durch das Militärviertel von Naxxramas. Man sagt, nur ein von ihm persönlich ausgebildeter Todesritter könne der Macht seiner Klinge standhalten.\n\nIhr und Eure Gruppe sollt das Gegenteil beweisen.\n\nDer Rat der Sechs hat verfügt, dass Razuvious sterben muss!", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;! Razuvious' Untergang hatte eine Verwirrung des Militärbefehls der Geißel aus Naxxramas zur Folge.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des TriumphsEmblem des Frosts"}
MultiLanguageQuestData['de'][24583] = {title = "Flickwerk muss sterben!", objective = "Tötet Flickwerk.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Der sogenannte \"Abgesandte des Krieges\", Flickwerk, ist die ultimative Monstrosität. Außerdem setzt er unseren Truppen in der Drachenöde schwer zu.\n\nIch möchte, dass Ihr Eure Gefährten versammelt und Euch in das Konstruktviertel von Naxxramas begebt, wo Ihr dieses Konstrukt auseinandernehmen sollt.\n\nDer Rat der Sechs hat verfügt, dass Flickwerk sterben muss!", progress = "Meine Quellen berichten, dass Flickwerk noch immer am Leben ist. Gibt es ein Problem, <Klasse>?", completion = "Kinder überall auf der Welt werden besser schlafen können, jetzt, da Flickwerk nicht mehr lebt.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24584] = {title = "Malygos muss sterben!", objective = "Tötet Malygos.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Unsere Ressourcen sind erschöpft. Malygos, der Spruchwirker, entzieht der Welt ihre Magie, um sie im Auge der Ewigkeit zu sammeln. Ohne Magie sind wir verloren!\n\n<Klasse>, der Nexuskrieg muss beendet werden. Der Rat der Sechs hat verfügt, dass Malygos sterben muss!", progress = nil, completion = "Nach dem Sieg über Malygos sollte der Nexuskrieg bald beendet sein. Die Dankbarkeit der Kirin Tor ist Euch gewiss, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24585] = {title = "Der Flammenleviathan muss sterben!", objective = "Tötet den Flammenleviathan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Auf dem Gestaltungsgelände bildet der Flammenleviathan die erste Verteidigungslinie von Ulduar.\n\nDie Kirin Tor haben die Information erhalten, dass diese vom Bewahrer hergestellte Maschine schon bald an einen unbekannten Ort gebracht und auf die Sterblichen von Azeroth losgelassen werden soll, um Verwüstung über sie zu bringen.\n\nDas dürfen wir nicht zulassen. Der Rat der Sechs hat verfügt, dass der Flammenleviathan sterben muss!", progress = nil, completion = "Ich bin doch immer wieder erstaunt, welche Schrecken man mit dem Gebrauch von Technik erschaffen kann.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24586] = {title = "Klingenschuppe muss sterben!", objective = "Tötet Klingenschuppe.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Klingenschuppe bleibt für gewöhnlich in ihrem Horst unweit der Kolossalen Schmiede in Ulduar. Doch in letzter Zeit wurde sie gesehen, wie sie Feuer auf das Land außerhalb des Titankomplexes niederregnen ließ.\n\nZwar hat die Brutmutter eine traurige Vergangenheit, doch stellt sie eine unmittelbare Gefahr für ganz Nordend dar. Der Rat der Sechs hat verfügt, dass Klingenschuppe sterben muss!", progress = nil, completion = "Jetzt kann Veranus endlich in Frieden ruhen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des TriumphsEmblem des Frosts"}
MultiLanguageQuestData['de'][24587] = {title = "Ignis, Meister des Eisenwerks, muss sterben!", objective = "Tötet Ignis, Meister des Eisenwerks.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Der große Feuerriese Ignis, Meister des Eisenwerks, schuftet unermüdlich in der Kolossalen Schmiede von Ulduar. Auf Geheiß von Loken stellt Ignis Waffen von schrecklicher Macht her.\n\nDer Rat der Sechs hat verfügt, dass Ignis sterben muss!", progress = nil, completion = "Ich gehe davon aus, dass Ihr nicht mit allzu vielen seiner Eisenkonstrukte konfrontiert wart?", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des TriumphsEmblem des Frosts"}
MultiLanguageQuestData['de'][24588] = {title = "XT-002 Dekonstruktor muss sterben!", objective = "Tötet den XT-002 Dekonstruktor.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Der XT-002 Dekonstruktor, ein weiteres, seltsames Konstrukt von Mimiron, denkt doch tatsächlich, er wäre der Sohn des Bewahrers! Lasst Euch von seiner geheuchelten Unschuld nicht in die Irre führen, er ist eine todbringende Maschine!\n\nIhr findet den Dekonstruktor auf dem Schrottplatz von Ulduar. Der Rat der Sechs hat verfügt, dass der XT-002 Dekonstruktor sterben muss!", progress = nil, completion = "Die größte Schwäche Ulduars ist das blinde Vertrauen ihrer Meister auf die Erfindungen, die sie zum Schutze dort ließen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des TriumphsEmblem des Frosts"}
MultiLanguageQuestData['de'][24589] = {title = "Lord Jaraxxus muss sterben!", objective = "Tötet Lord Jaraxxus.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Erzmagier Timear hat eine schreckliche Begebenheit vorhergesagt, die sich in Kürze ereignen wird. Ein törichter Gnomenhexenmeister wird während der Prüfung des Kreuzfahrers versehentlich einen Eredarlord der Brennenden Legion heraufbeschwören.\n\nIhr müsst dort sein, wenn es passiert, <Klasse>. Wenn Lord Jaraxxus entkommt, wird er ein Portal öffnen, durch das die Brennende Legion wieder Einzug in unsere Welt erhält.\n\nDer Rat der Sechs hat verfügt, dass Lord Jaraxxus sterben muss!", progress = nil, completion = "Ganz Azeroth hatte Glück, dass Timear die Ankunft des Eredarlords vorhergesehen hat und Ihr rechtzeitig dort wart, um ihn zu töten.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkteEmblem des TriumphsEmblem des Frosts"}
MultiLanguageQuestData['de'][24590] = {title = "Lord Mark'gar muss sterben!", objective = "Tötet Lord Mark'gar.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", description = "Lord Mark'gar bewacht den Frostthron in der Bastionskammer. Seit der Lichkönig ihn aus den Knochen Tausender bezwungener Abenteurer zusammengesetzt hat, besitzt Mark'gar selbst die Macht des Thrones.\n\nWenn dieses Knochengespenst nicht vernichtet wird, besteht keine Hoffnung, die Eiskronenzitadelle einzunehmen.\n\nDer Rat der Sechs hat verfügt, dass Lord Mark'gar sterben muss!", progress = nil, completion = "Dank Euch hat der Frostthron keinen Hauptwächter mehr. Unsere Angriffe auf die Truppen des Lichkönigs werden von nun an von noch größerem Erfolg gekrönt sein.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24591] = {title = "Wachablösung", objective = "Geht auf die Spitze des nördlichen Turms in Ödnisfeste und helft Kriegsfürst Blutheft dabei, Gar'dul seines Kommandos zu \"entheben\".", description = "Wenn Blutheft eintrifft, würde ich gern, äh, unter Ausschluss der Öffentlichkeit mit ihm sprechen. Könnt Ihr mich begleiten um sicherzustellen, dass alles im Lot bleibt? Dieser Blutheft ist, äh, er ist... er ist unberechenbar.\n\n<Gar'dul versucht, seine Fassung zurückzugewinnen.>\n\nTrefft mich oben auf dem nördlichen Turm und wir sprechen gemeinsam mit Blutheft.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Gar'duls RüstungHandschuhe der ÖdnisfesteBundhose der Autorität\"Gemeingewehrlich\"Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24592] = {title = "Verrat an der Witterfront", objective = "Trinkt Krennans Tarnungstrank an der Witterfront und tötet Baron Ashbury und Lord Walden.", description = "Lord Godfrey hat König Graumähne an der Witterfront gefangen genommen!\n\nEr konnte die beiden Fürsten aus dem Osten überzeugen, sich seinem Plan anzuschließen. Der Narr scheint zu denken, dass er eine Vereinbarung mit den Verlassenen treffen kann, wenn er ihnen Graumähne überlässt.\n\nHört genau zu, <Name>. Wir müssen diese Angelegenheit mit so wenig Blutvergießen wie möglich klären.\n\nMit diesem Trank könnt Ihr Euch unerkannt hineinschleichen. Ermordet die verräterischen Fürsten, bevor die Dinge vollkommen außer Kontrolle geraten!", progress = "Seid vorsichtig, <Name>.", completion = "Ich wünschte, wir hätten es anders lösen können, &lt;Name&gt;. Lasst uns sichergehen, dass wir die Sache ohne weiteres Blutvergießen beilegen.", rewards = "Blaublutige StiefelGraumähnenumhangIhr bekommt:\n\nLord Waldens Zylinder"}
MultiLanguageQuestData['de'][24593] = {title = "Weder Mensch noch Tier", objective = "Trinkt vom Brunnen der Ruhe, dem Brunnen des Gleichgewichts und dem Brunnen des Zorns.", description = "Es ist Zeit, <Name>. Diese… Alchemie, die die Bestie in Euch zügelt, hält nicht mehr lange an.\n\nDie ersten verfluchten Worgen waren Nachtelfdruiden, genau wie unsere neuen Verbündeten. Sie haben dem Gleichgewicht, das der Rest ihres Volkes ehrt, den Rücken gekehrt und zugelassen, dass die Bestie in ihrem Inneren die Kontrolle über ihren Verstand übernimmt.\n\nDaher ist es nur Recht, dass ihre Brüder und Schwestern uns von diesem Fluch befreien werden. Geht, <Klasse>. Trinkt von den Wassern des Tal'doren und schließt Frieden mit Euch selbst.", progress = nil, completion = "Also ist es vollbracht, &lt;Name&gt;. Ihr gehört jetzt zu uns.", rewards = "Stab der verdienten RuheRuf des WolfesHammer des beherrschten ZornsScharfe Schneide des GleichgewichtsDer folgende Zauber wird auf euch gewirkt:\n\nForcecast Tal'doren Master\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24594] = {title = "Die Reinigung Quel'Delars", objective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wachen des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, <Name>.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", progress = "Ihr seid vom Sonnenbrunnen zurückgekehrt?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Dämmersuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", rewards = nil}
MultiLanguageQuestData['de'][24595] = {title = "Die Reinigung Quel'Delars", objective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Sobald die Klinge wiederhergestellt ist, zeigt sie Caladis Prunkspeer in Quel'Delars Ruh.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][24596] = {title = "Die Reinigung Quel'Delars", objective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, <Name>.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][24597] = {title = "Ein Geschenk für den König von Sturmwind", objective = "Schenkt König Varian Wrynn von Sturmwind einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für den König von Sturmwind einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus SturmwindZeichen der Liebe"}
MultiLanguageQuestData['de'][24598] = {title = "Die Reinigung Quel'Delars", objective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, <Name>.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][24601] = {title = "Die Alptraumnarbe", objective = "Helft Naralex, die Alptraumnarbe zu schließen.", description = "Das bestätigt es. Die Überwucherung hier wird nicht nur von der Fülle der Energie verursacht.\n\nVersteht Ihr? Das geht über das, was in den Höhlen des Wehklagens geschehen ist, hinaus. In den Landen, in denen wir uns befinden, muss sich ein Riss in den Alptraum aufgetan haben. Wenn ich daran denke, dass das mein Fehler ist...\n\nIch werde nicht länger an den Wundrändern herumkratzen. Geht nach Westen ins Zentrum der Überwucherung und trefft mich dort. Wir werden dieser Verderbnis auf den Grund gehen und ihr ein Ende setzen!", progress = nil, completion = "Wir haben es geschafft! Die Verbindung des Alptraums zu dieser Welt wurde gekappt. Der Rest des Landes ist vor dem Eindringen sicher und im Laufe der Zeit werden die Anomalien hier auch wieder dem Naturgleichgewicht unterworfen.\n\nIch kann Euch nicht genug danken, &lt;Name&gt;. Ihr habt geholfen, die Ordnung hier wiederherzustellen, und mir dadurch die Gelegenheit gegeben, meine törichten Taten wieder gutzumachen.", rewards = "Naralex' PantoffelnWeste der AlptraumkluftAuf Euch wartet eine dieser Belohnungen:\n\nWehklagender Ring\n\nDer folgende Zauber wird auf euch gewirkt:\n\nNightmare Mass Aura Cancel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24602] = {title = "Zur Ruhe gebettet", objective = "Besorgt 5 freigelegte Andenken.", description = "Bei unserer überstürzten Flucht haben wir die Ruhestätten unserer Vorfahren gestört, <Name>. Eine Todsünde sozusagen.\n\nEs ist Tradition, ein kleines Andenken in der flachen Erde auf dem Grab eines Einwohners von Gilneas zu hinterlassen. Als die Leute panisch aus diesen Tunneln geflohen sind, wurden diese Andenken freigelegt. Das hat die Geister der Verstorbenen erzürnt.\n\nFindet diese Andenken und bringt sie mir. Wir werden dafür sorgen, dass die Toten zu ihrem ewigen Schlaf zurückkehren.", progress = "Ihr seid zurück, <Name>.", completion = "Danke, &lt;Name&gt;. Hoffen wir, dass es funktioniert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24603] = {title = "Es ist nie genug", objective = "Tötet 13 Stacheleber der Klingenmähnen.", description = "Für eine Weile dachte ich, mein Hass hätte sich gelegt. Meine Frau wurde zur letzten Ruhe gebettet, ein letztes Blutopfer ihrer Mörder, um ihre gequälte Seele zu beruhigen. Ich dachte, Frieden würde mir gefallen.\n\nIch habe mich geirrt.\n\nIch werde nicht ruhen, bis auch der letzte dreckige, quiekende, mordende Stacheleber tot und zerschmettert daliegt! Ich kann sie aber mit meinen eigenen Händen nicht schnell genug töten. Geht und tötet noch mehr für mich, <Volk>.", progress = nil, completion = "Gut. Nehmt Eure Belohnung; das ist erst der Anfang.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24604] = {title = "Sorge um Mankrik", objective = "Bringt Mahkas Geschenk zu Mankrik südlich der Flammensteinspitze.", description = "Ich möchte Euch um einen Gefallen bitten <Klasse>.\n\nEin Krieger namens Mankrik ist vor nicht allzu langer Zeit auf seiner einsamen Reise durch unser Lager gezogen. Seine Frau wurde von den Stachelebern vor langer Zeit getötet und ihn dürstet immer noch nach Rache. Ich kann seine Augen nicht vergessen... in ihnen brannte ständig unverhohlener Hass.\n\nWir haben nicht lange miteinander gesprochen, aber ich ertrage den Gedanken nicht, dass er da draußen ganz alleine ist. Bitte bringt dies zu Mankrik und sagt ihm, dass es von mir stammt...", progress = "<Mankrik knurrt.>\n\nWas ist? Ich bin beschäftigt.", completion = "Mahka hat Euch geschickt?\n\n&lt;Manriks Wut ebbt einen Moment lang ab.&gt;\n\nDas ist eine kleine Aufmunterung. Aber nichts kann mich trösten, solange ich hier noch nicht fertig bin.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24606] = {title = "Blut des Brachlands", objective = "Findet 6 Blutsplitterschmuckstücke bei Stachelebern der Klingenmähnen.", description = "Dieser hellrote Stein, den ich in den Klauen eines Stachelebers gefunden habe, wurde sorgfältig in die Form eines großen Ebers geschnitzt, aus dessen Rücken Dornenranken sprießen. Seine Oberfläche ist glatt und abgenutzt.\n\nHaben die Stacheleber ihn hergestellt? Wenn Ihr noch andere findet, kann vielleicht einer der Schamanen an der Flammensteinspitze Euch mehr über sie erzählen.", progress = "Ja?", completion = "Das sind Blutsplitter! Früher fand man sie überall im Brachland.\n\nMan sagt, dass sie aus dem Blut von Agamaggan geformt wurden, dem großen Halbgott, von dem die Stacheleber abstammen. Ich wusste, dass die Stacheleber viel Wert auf sie legen, aber niemand hätte gedacht, sie würden sich die Zeit nehmen und sich die Mühe machen, so etwas daraus zu schnitzen...\n\nVielleicht gibt es hier noch mehr zu erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24607] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Nortet auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Nortet im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nObwohl, Ihr seht aus, als wärt Ihr gut in Form. Ruhige Hände. Scharfe Augen. Vielleicht kann ich aus Euch einen echten &lt;Klasse&gt; machen.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24608] = {title = "Quetschzahn", objective = "Tötet Quetschzahn.", description = "Ich schere mich nicht länger um Ehre und Ruhm, <Klasse>. Mich interessiert nur, dass die Stacheleber sterben - egal wie und durch wen.\n\nQuetschzahn, der Häuptling dieser dreckigen Klingenmähnen, sitzt im Nordwesten auf einem Hügel in seinem Bau. Beendet sein Leben.\n\nIch gedenke, hierzubleiben und diese Leichen aufeinanderzustapeln, bis dieses Ungeziefer mir nicht mehr quiekend aus dem Kral entgegenspringt...", progress = nil, completion = "Gut. Gut! Sie werden alle sterben! Ihre Häuptlinge, ihre Frauen, ihre Kinder und ihre widerlichen Haustiere!", rewards = "KralarmschienenGeschundener ZahnKlingenmähnenstabAuf Euch wartet eine dieser Belohnungen:\n\nMankriks Amulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24609] = {title = "Ein Geschenk für einen Lord von Eisenschmiede", objective = "Schenkt Muradin Bronzebart in Eisenschmiede einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für Muradin Bronzebart einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus EisenschmiedeZeichen der Liebe"}
MultiLanguageQuestData['de'][24610] = {title = "Ein Geschenk für die Hohepriesterin von Elune", objective = "Schenkt Tyrande Wisperwind in Darnassus einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für die Hohepriesterin von Elune einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, sie wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus DarnassusZeichen der Liebe"}
MultiLanguageQuestData['de'][24611] = {title = "Ein Geschenk für den Propheten", objective = "Schenkt Prophet Velen in der Exodar einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für den Propheten der Exodar einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus der ExodarZeichen der Liebe"}
MultiLanguageQuestData['de'][24612] = {title = "Ein Geschenk für den Kriegshäuptling", objective = "Schenkt dem Kriegshäuptling in Orgrimmar einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für den Kriegshäuptling einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus OrgrimmarZeichen der Liebe"}
MultiLanguageQuestData['de'][24613] = {title = "Ein Geschenk für die Bansheekönigin", objective = "Schenkt Fürstin Sylvanas Windläufer in Unterstadt einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für die Bansheekönigin einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, sie wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus UnterstadtZeichen der Liebe"}
MultiLanguageQuestData['de'][24614] = {title = "Ein Geschenk für den Oberhäuptling", objective = "Schenkt Baine Bluthuf in Donnerfels einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für den Oberhäuptling einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus DonnerfelsZeichen der Liebe"}
MultiLanguageQuestData['de'][24615] = {title = "Ein Geschenk für den Lordregenten von Quel'Thalas", objective = "Schenkt Lor'themar Theron in Silbermond einen hübschen Glücksbringerarmreif.", description = "Möchtet Ihr für den Lordregenten von Quel'Thalas einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", progress = "Seid gegrüßt, <Klasse>! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", rewards = "Ihr bekommt:\n\nSchöne Grußkarte aus SilbermondZeichen der Liebe"}
MultiLanguageQuestData['de'][24616] = {title = "Verfolger abschütteln", objective = "Verwendet Belysras Talisman, um die dunkle Späherin zu besiegen.", description = "Ihr müsst so viele Fragen haben, <Name>. Und Ihr werdet auch bald Antworten darauf erhalten.\n\nIch weiß, warum Ihr hier seid und wonach Ihr sucht.\n\nIch kann Euch nicht dahin führen, solange der Feind Euch folgt.\n\nEine von Sylvanas Späherinnen ist Euch auf den Fersen. Ihr dürft den Verlassenen auf keinen Fall den Ort zeigen, den Ihr sucht. Nehmt diesen Talisman und geht einfach die Straße direkt nördlich von hier entlang.\n\nLasst zu, dass die Späherin Euch in ihre Falle lockt, und nutzt dann die Macht des Talismans, um Euch zu befreien und einen Gegenangriff zu starten.", progress = "Ist es vollbracht, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Die Späherin hatte nicht die geringste Chance gegen Euch.", rewards = "Seryls RobenRasende GamaschenEilige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24617] = {title = "Tal'doren, die Heimstatt in der Wildnis", objective = "Sprecht mit Darius Crowley beim Tal'doren im Herzen des Schwarzforsts.", description = "Es gibt andere wie Euch, <Name>. Und auch sie waren verwirrt und wussten nicht, wohin.\n\nEs gibt einen Ort, an den Ihr gehört. Tal'doren, die Heimstatt in der Wildnis, war einst das Zuhause eines Druidenordens, der die Form von Wölfen annehmen konnte.\n\nDort findet Ihr die Antworten, die Ihr sucht. Und dort wird Euch jemand helfen können. Ein alter Freund.", progress = nil, completion = "Es geht Euch gut, &lt;Name&gt;! Ich habe schon so lange auf diesen Tag gewartet. Es ist eine wahre Freude, Euch zu sehen, Freund.\n\nIch habe gehört, was Ihr getan habt, und ich bin Euch so dankbar… besonders für Lorna. Sie ist alles, was mir geblieben ist. Ich lasse sie sofort herholen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24618] = {title = "Anspruch auf die Kriegsnarbe erheben", objective = "Geht zu der Kriegsnarbe. Findet die Flagge und tötet 10 Soldaten der Vorhut der Triumphfeste.\n\nDie Flagge einzunehmen wird allen Hordespielern in der Narbe einen Vorteil im Kampf gewähren.", description = "Wir haben die Allianz hier durch unseren Kampf zum Stillstand gebracht, obwohl das Land unter unseren Füßen auseinanderbricht. Im Osten findet Ihr die Kriegsnarbe, eine weite Schneise stark geschwächten Landes. Sie ist kaum mehr als eine Linie im Sand, aber sie muss UNSERE Linie werden.\n\nIm Zentrum der Narbe befindet sich eine Flagge, die anzeigt, wer gerade über sie herrscht. Findet die Flagge.\n\nWenn sie nicht bereits uns gehört, nehmt sie für die Horde ein - das wird den Kampf zu unseren Gunsten beeinflussen. Untersucht die Narbe und tötet jeden, den Ihr darin findet!", progress = nil, completion = "Ausgezeichnet! Ihr seid die Art &lt;Klasse&gt;, die ich mag, &lt;Name&gt;.\n\nMit Eurer Hilfe werden wir diese Eindringlinge zurück ins Meer treiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24619] = {title = "Graus Anatomie", objective = "Benutzt Calders Knochensäge an Leichen in der Kriegsnarbe und sammelt 15 abgetrennte Gliedmaßen ein.", description = "Ich wollte schon immer mal versuchen, eine Monstrosität herzustellen. Es sieht recht einfach aus, aber Ihr wisst ja, wie es ist, wenn man etwas aus einem Buch gelernt hat. Es gibt nichts Besseres, als etwas selbst zu tun!\n\nZunächst brauche ich dafür Teile. Viele Teile. Und Ihr werdet sie mir besorgen.\n\nIhr müsst nicht wählerisch sein: menschlich, orcisch... Das ist egal. Teile sind Teile.\n\nIhr müsst nur darauf achten, dass die Leichen, die ihr aberntet, aus der Kriegsnarbe stammen, damit ich weiß, dass sie frisch sind.\n\n<Calder drückt Euch eine verrostete, blutbeschmierte Knochensäge in die Hand und lächelt entwaffnend.>", progress = "Habt Ihr meine Teile bekommen? Lasst mal sehen!", completion = "&lt;Calder späht in den Sack mit den Gliedmaßen und leckt sich mit seiner trockenen, schwarzen Zunge über die Lippen.&gt;\n\nAu weia. Ist das aufregend.\n\n Seid Ihr nicht aufgeregt, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24620] = {title = "Herzen sind Herzen", objective = "Tötet einen Landbeberbullen südlich der Kriegsnarbe und besorgt ein gigantisches Kodoherz.", description = "Diese Teile – herrlich! Muskeln und Sehnen und Finger und Zehen... Jetzt habe ich SO einen Hunger.\n\nAber erst kommt die Arbeit. Sobald ich diesen Haufen Teile zusammengenäht habe, benötige ich ein Herz, das stark genug ist, Schlick durch dieses Durcheinander von Venen zu pumpen. Ich würde ja mein eigenes Herz benutzen, aber das ist eine verschrumpelte Hülle, die wie eine Rübe aussieht.\n\nNein, ich brauche wahre Stärke. Besorgt mir ein Kodoherz von einem dieser riesigen Landbeberbullen südlich der Kriegsnarbe.", progress = "Habt doch ein Herz, <Name>. Alles, was Ihr wirklich braucht, ist ein Herz.", completion = "&lt;Calder packt das riesige Herz mit beiden Händen, drückt es und lauscht, wie die Kammern schlürfen und schmatzen.&gt;\n\n&lt;Die wächserne Maske seines Gesichts teilt sich zu einem breiten, kindlichen Grinsen.&gt;\n\nEs ist so wichtig, dass man seine Arbeit liebt, findet Ihr nicht auch, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24621] = {title = "Clever ist clever", objective = "Tötet einen Hauptmann der Triumphfeste auf der gegenüberliegenden Seite der Kriegsnarbe und besorgt ein frisches Hirn.", description = "Meine Monstrosität nimmt langsam Gestalt an! Nun muss ich nur noch ihren Schädel mit etwas Sinnvollem ausstopfen.\n\nIch spreche von einem Gehirn, <Name>. Und da werde ich dann wählerisch. Die Vermonstrositierung verursacht erheblichen Hirnschaden, also sollte man mit jemandem anfangen, der intelligent ist.\n\nEiner der Allianzoffiziere sollte reichen. Findet einen der Hauptleute auf der anderen Seite der Kriegsnarbe und versucht, die Ware nicht zu beschädigen, während Ihr ihn tötet.", progress = "Hiiiiiiiirrrrrrrrrrn...", completion = "&lt;Calder hält das Hirn in seiner ausgestreckten Hand und zieht gleichzeitig ein blutverschmiertes Werkzeug aus seinem Gürtel.&gt;\n\nWunderbare Arbeit! Das Geheimnis hier ist, das tückische Nervensystem nicht zu verletzen, während man die höhere Erkenntnisfähigkeit entfernt. Schließlich können wir nicht zulassen, dass unser neuer Freund ein Gewissen bekommt oder sich daran erinnert, dass er zur Allianz gehört ...\n\n&lt;Calder bohrt und schnippelt an dem Hirn herum und entfernt große Stücke.&gt;\n\nUnd... schon sind wir fertig! Wunderbar.", rewards = "Hirnbespritzte BeinschützerWerkzeug des NeurochirurgenWeste der MonstrositisierungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24622] = {title = "Des Trolls bester Freund", objective = "Redet mit Kijara an der Blutkrallenküste.", description = "Wenn Ihr etwas zu tun sucht, wir hätten da noch ein paar Raptoren, die zu den Ställen gebracht werden müssen. Begebt Euch zu der Insel südlich von hier und trefft Euch mit den Pflegern, die werden Euch dann weiterhelfen.\n\nSie würden sich bestimmt auch über ein wenig Hilfe freuen. Ihr müsst die Liebe verbreiten, wisst Ihr?", progress = nil, completion = "Schön, hier draußen mal neue Gesichter zu sehen, Mann. Wir sind doch recht isoliert, seit wir Orgrimmar verlassen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24623] = {title = "Rettet die Kleinen", objective = "Verwendet die Blutkrallenpfeife, um 12 verlorene Brutkrallenjungtiere zu retten.", description = "Ich habe etwas ziemlich Wichtiges, bei dem ich Eure Hilfe brauche, wenn Ihr bereit seid, Mann.\n\nUnsere Jungtiere werden von jemandem auf der Nachbarinsel geraubt. Zuerst dachte ich ja, sie wären uns davongelaufen oder die Natur habe sie sich genommen, aber mittlerweile fehlen mehr als ein Dutzend der kleinen Racker.\n\nBitte begebt Euch nach Zalazanes Sturz im Nordwesten und weist den Jungtieren den Weg zurück. Die armen Kleinen.", progress = nil, completion = "Ich danke Euch sehr! Sie können wild werden, wenn man sie provoziert, aber meist wissen sie es halt nicht besser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24624] = {title = "Gnade für die Verirrten", objective = "Tötet 8 verderbte Blutkrallenraptoren.", description = "Der Übeltäter, der unsere Raptoren geklaut hat, muss sie mit irgendeiner Art von Magie verderbt haben. Jetz' da sie mit dieser Verderbnis herangewachsen sind, befürchte ich, dass wir kaum was anderes für sie tun können, außer ihnen einen friedlichen Tod zu gewähren. Geht zu Zalazanes Sturz nordwestlich von hier und übernehmt diese Pflicht.\n\nIch hoffe nur, Ihr habt den nötigen Mumm. Ich glaub' nich', dass ich mich dazu überwinden könnte, auch wenn ich weiß, dass es nötig ist.", progress = nil, completion = "Danke, &lt;Klasse&gt;.\n\nEs benötigt tapfere und entschlossene Leute wie Euch, um die Dunkelspeere wieder groß zu machen. Ich hoffe, dass noch mehr Leute kommen, die nur halb so entschlossen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24625] = {title = "Der Gemahl der Seehexe", objective = "Tötet Naj'tess und erbeutet seine Kugel.", description = "Ich hab unsere verderbten Blutkrallen untersucht und bin dabei der Ursache dieses Problems auf die Spur gekommen. Es ist ein einzelner Naga. Er hat eine rote Kugel über unsere Jungen gehalten und ich sah, wie sie sich... veränderten.\n\nIch bin mir sicher, dass er denkt, sein Diebstahl und seine Zauber seien nicht bemerkt worden. Es sollte Euch also gelingen, ihn zu überraschen. Tötet den Naga und bringt mir diese unseelige Kugel - Ihr werdet ihn im Nordwesten, an Zalazanes Sturz finden.", progress = "Die Naga sind schon seit langer, langer Zeit unsere Feinde. Die letzten Begegnungen mit ihnen verliefen nich' gerade gut. Dieses Mal wird das jedoch anders sein. Die Zeiten haben sich geändert und Ihr seid Teil dieser Veränderung.", completion = "Gut gemacht, &lt;Name&gt;! Dieser Naga hat uns enorm zurückgeworfen, aber nichts wird uns auf ewig aufhalten.\n\nEs ist gut, dass Ihr bei uns seid, &lt;Name&gt;. Ein wildes Herz schlägt ihn Eurer Brust.", rewards = "Stiefel des wechselnden GlücksWeste des wilden HerzensGamaschen des BlutkrallenwärtersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24626] = {title = "Jung und bösartig", objective = "Fangt Flinkklaue und bringt ihn zu den Ställen in der Nähe der Dunkelspeerfeste.", description = "Ihr seid in Ordnung, <Name>.\n\nMoraya hat um neue Raptoren zum Ausbilden gebeten. Wir sollten sie nich' länger warten lassen! Einige meiner anderen Rekruten bringen schon ein paar 'rüber, aber ich habe hier einen besonderen Raptor, den ich Moraya vor einer Weile versprochen habe.\n\nFlinkklaue ist einer der schnellsten und mutigsten Jungraptoren, den ich je gesehen habe, aber er kann ein wenig widerspenstig sein. Ich leih' Euch ein Lasso, mit dem Ihr ihn nur irgendwo hier auf der Insel einfangen und ihn in die Ställe auf der Hauptinsel steuern müsst. Ich glaub' aber nich', dass er es Euch einfach machen wird.", progress = nil, completion = "Flinkklaue! Kijara hat mir von ihm erzählt und es klang, als wäre er schwerer zu hüten als'n Sack Flöhe. Mir kommt die Herausforderung gerade recht. Es sind die Temperamentvollen, die am Ende die mutigsten und treusten Begleiter in der Not abgeben.\n\nVielen Dank, Schätzchen. Wart mir 'ne große Hilfe.", rewards = "Morayas GürtelSchnelle SchuppenarmbänderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24627] = {title = "Direkt vor unserer Tür", objective = "Tötet 6 heulende Banshees.", description = "Die Nachtelfen haben uns in dieser Zeit viel beigebracht, <Name>. Sie lehrten uns, wer wir sind und wo wir herkommen.\n\nDank ihnen… dank dieses Orts… sind wir keine wilden Tiere mehr. Wir haben unseren freien Willen zurückgewonnen.\n\nDie Verlassenen haben es nicht nur auf unser Land abgesehen.\n\nSie suchen nach etwas, das uns gehört. Ein Artefakt, mit dem sie den Fluch unkontrollierbar auf die gesamte Menschheit ausbreiten können. Wir dürfen nicht zulassen, dass sie es finden.\n\nSylvanas' Banshees rücken immer näher. Helft meinen Spurenlesern, sie zu beseitigen.", progress = nil, completion = "Ihr seid so gut, wie ich Euch in Erinnerung habe, &lt;Name&gt;. Wie schön, dass Ihr wieder da seid.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Summon Tobias\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24628] = {title = "Vorbereitungen", objective = "Bringt 6 Mondblätter zu Vassandra.", description = "Was Ihr als Fluch kennt begann als Ketzerei unter unseren Brüdern.\n\nIm Angesicht der sicheren Niederlage gegen dämonische Mächte haben die Druiden des Rudels dem Gleichgewicht, dem sie sich verschworen hatten, den Rücken gekehrt und zugelassen, dass das Tier in ihnen die Kontrolle übernimmt.\n\nSie wurden in den Smaragdgrünen Traum verbannt, wo sie unter einem Baum wie diesem in ewigen Schlaf versinken mussten. Doch ihre Seuche hatte sich schon auf andere ausgebreitet.\n\nHeute stellen wir in unserer Zeremonie das Gleichgewicht in Eurem Volk wieder her. Bringt mir das Blatt, das nur in der Nähe des Tal'doren wächst.", progress = "Ihr seid zurückgekehrt, <Name>.", completion = "Diese einfachen Blätter wachsen durch Elunes Gnade. Sie werden Eurem Geist helfen zu verstehen, warum wir das Gleichgewicht brauchen, und Eurer Seele für alle Zeit lehren, das Tier in Euch zu beherrschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24629] = {title = "Ein perfekter Hauch von Parfüm", objective = "Besprüht 10 Leute mit dem Parfümzerstäuber der Manufaktur Krone.", description = "Ihr scheint mir voller Tatendrang zu sein, <Klasse>. Was haltet Ihr davon, wenn wir uns zusammen einen Plan ausdenken, aus dem beide Seiten als Gewinner hervorgehen?\n\nDie Manufaktur Krone möchte Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, bekommt Ihr Rabatt auf einige tolle Produkte der Manufaktur Krone.\n\nEure Zeit gegen unser Geld - was sagt Ihr dazu?", progress = "Das Parfüm versprüht sich nicht von selbst, wisst Ihr?\n\nFangt an!", completion = "Großartige Leistung, &lt;Name&gt;! Die Leute werden in Scharen kommen, um Parfüms der Manufaktur Krone zu kaufen, jetzt, wo sie ihre Wunder testen konnten.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24631] = {title = "Flugangst", objective = "Benutzt Tomusas Haken gegen Kriegsgreife der Triumphfeste, um 5 Söldner der Wildhämmer von ihren Reittieren zu stoßen und sie zu töten.", description = "Die Allianz hat Söldner der Wildhämmer angeheuert, um den Himmel oberhalb der Kriegsnarbe zu kontrollieren. Ich glaube, dieselben Greifenreiter waren an dem Feuerbombardement Taurajos während des Angriffs beteiligt.\n\nIch will, dass unser Himmel gesäubert wird.\n\nDie Wildhammerzwerge fliegen tief genug, dass <ein scharfäugiger/eine scharfäugige:c> <Klasse> wie Ihr sie an den Haken bekommt. Nehmt dies. Zielt auf ihre Greife und holt ihre Reiter herunter. Sobald sie sich auf dem Boden befinden, zeigt keine Gnade.", progress = "Die Wildhämmer sind verbissene Kämpfer, in der Luft und auch am Boden. Wie läuft der Kampf?", completion = "&lt;Tomusa schnaubt, als er seinen Haken wieder in Empfang nimmt.&gt;\n\nRache fühlt sich hohl an. Dennoch, ich konnte sie nicht ungestraft davonkommen lassen.", rewards = "Erdgebundene GamaschenFlugtraummantelungTomusas SchwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24632] = {title = "Rache auf Taurenart", objective = "Sucht Gann Steinkeil bei Speerspitze im Südlichen Brachland.", description = "Mein Volk ist nicht von Natur aus rachsüchtig, aber manchmal führt der Durst nach Gerechtigkeit dazu, dass wir im Zorn unsere Waffen aufnehmen.\n\nMein alter Freund, Gann Steinkeil, schäumte vor Zorn, als er von dem Gemetzel in Taurajo erfuhr. Die Stammesältesten waren nicht in der Lage, seine Wut im Zaum zu halten.\n\nJetzt hat er der Horde mehr oder weniger entsagt. Er ist abtrünnig geworden, <Name>, und versucht, mit einer kleinen Gruppe gleichgesinnter Partisanen einen Schlag gegen die Allianz zu führen.\n\nWenn Ihr ebenfalls Rache sucht, findet Ihr ihn südöstlich von hier am Fuße des Bael Modan.", progress = nil, completion = "&lt;Gann mustert Euch von Kopf bis Fuß.&gt;\n\nWir könnten Eure Hilfe brauchen, &lt;Klasse&gt;. Aber das hier ist kein kleines Scharmützel. Wir kämpfen hier, um einen entscheidenden Schlag zu führen - oder bei dem Versuch zu sterben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24633] = {title = "Mahkas Bitte", objective = "Sprecht mit Mankrik.", description = "Ich kann ihn mir nicht aus dem Kopf schlagen, <Name>. Manchmal in der Nacht, höre ich sein wütendes, klagendes Heulen, das über die Ebenen schallt. Mir vorzustellen, dass er da draußen ist... alleine ... und solche Schmerzen leidet...\n\nBitte, ich muss Euch um einen Gefallen bitten. Geht zu Mankrik und bittet ihn, zu mir zu kommen.", progress = "Es tut mir leid, Euch darum zu bitten, aber ich möchte, dass er hierher kommt. Er muss diesen Ort des Todes verlassen...", completion = "Danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTalked to Mankrik Cancel\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24634] = {title = "Krieg der Geheimdienste", objective = "Tötet einen Agenten des Brachlands und nehmt die Anweisungen des SI:7 an Euch.", description = "Ich bin davon überzeugt, dass die Allianz Spione benutzt, um das Feld auszuspähen und Informationen weiterzugeben. Sie wussten, dass sie den Schlag gegen Taurajo führen müssen, wenn die Jäger draußen auf den Feldern sind. Und sie begegneten jedem Manöver von Gar'dul, als ob er ein offenes Buch wäre.\n\nNun, <Name>, ich lasse mich nicht ausmanövrieren. Nicht hier. Wir werden den Kampf um die Informationen gewinnen.\n\nSogar jetzt höre ich Berichte, dass Agenten der Allianz in den Schatten herumschleichen - insbesondere hier, direkt außerhalb dieser Mauern. Tötet sie und bringt mir etwas Nützliches mit.", progress = "Passt auf Euch auf, <Klasse>. Sie könnten überall sein.", completion = "Ha! Der Narr hat diese Befehle nicht vernichtet.\n\nSchauen wir mal, was wir Interessantes erfahren können...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24635] = {title = "Ein feines Duftwasserwölkchen", objective = "Besprüht 10 Leute mit dem Duftwasserzerstäuber der Manufaktur Krone.", description = "Ihr scheint mir Unternehmergeist zu besitzen, <Klasse>. Was haltet Ihr von einem kleinen Geschäft?\n\nDie Manufaktur Krone möchte Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, bekommt Ihr Rabatt auf einige tolle Produkte der Manufaktur Krone.\n\nEure Zeit gegen unser Geld - was sagt Ihr dazu?", progress = "Das Duftwasser versprüht sich nicht von allein, wisst Ihr?\n\nSprüht los!", completion = "Gute Arbeit, &lt;Name&gt;! Die Leute werden die Duftwasser der Manufaktur Krone zuhauf kaufen, jetzt, wo sie sie getestet haben.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24636] = {title = "Bonbonangriff", objective = "Bewerft 10 Leute mit Schokoladenproben der Manufaktur Krone.", description = "Ah, ich sehe, dass Ihr Euch keine Gelegenheit entgehen lasst, <Klasse>. Wir könnten zusammen ein wenig Geld machen.\n\nDie Manufaktur Krone muss Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden in der Stadt wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, dürft Ihr auch ein paar tolle Produkte von Manufaktur Krone haben.\n\nEure Zeit gegen unser Geld - kommen wir ins Geschäft?", progress = "Wisst Ihr, die Schokolade fliegt nicht von allein zu den Leuten.\n\nIhr müsst anfangen, zu arbeiten!", completion = "Fantastische Leistung, &lt;Name&gt;! Die Leute werden sich die Schokolade der Manufaktur Krone gegenseitig aus den Händen reißen, jetzt, wo sie diese süßen, romantischen Leckereien gekostet haben.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24637] = {title = "Der Schlächter von Taurajo", objective = "Sprecht mit Karthog, dann lockt General Hawthorne heraus und verübt ein Attentat auf ihn.", description = "Dieser Agent hatte Befehle, die Straßen zwischen der Kommandantur der Allianz und der Triumphfeste zu sichern. General Hawthorne ist unterwegs.\n\n<Blutheft zerknüllt die Papiere in seiner Faust.>\n\nDas IST er, <Name>! Hawthorne - ich spucke den Namen aus - ist derjenige, der den Angriff auf Taurajo befohlen hat! Jetzt wissen wir wann und wo wir ihn niederstrecken können. Schnell, folgt der Straße nördlich der Kriegsnarbe und trefft Euch mit meinem Auftragsmörder Karthog. ZERSCHMETTERT Hawthorne und hängt seinen Körper neben der Straße auf!", progress = nil, completion = "&lt;Als er die Neuigkeiten hört, schnaubt Blutheft. Seine Augen glitzern. Er legt seinen Kopf in den Nacken und stößt ein abgehacktes, brüllendes Gelächter aus, das von den geschwärzten Mauern der Ödnisfeste zurückgeworfen wird und durch die Hügel dahinter hallt.&gt;\n\nEs ist also vollbracht! Der Schlächter von Taurajo ist wurde endlich zur Strecke gebracht. In den Straßen niedergestreckt wie ein Hund. Wie passend.\n\nIhr habt wohlgetan, &lt;Name&gt;. Ihr habt Angst bei unseren Feinden gesät und bald werden wir die Ernte einbringen!", rewards = "KriegsnarbenschulternUmhang der geernteten FurchtKlinge des Metzgers von TaurajoIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24638] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport gleich westlich der Tore Orgrimmars in Durotar zu beschädigen und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: im Westen, vor den Toren Orgrimmars. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24639] = {title = "Die Grundlagen: Dinge schlagen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Schwüngen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24640] = {title = "Die Künste eines Kriegers", objective = "Ihr müsst Stufe 3 erreichen, um Sturmangriff zu erlernen. Probiert Sturmangriff an einem Tikiziel aus.", description = "Wenn Ihr besser kämpfen lernt, findet Ihr Sachen heraus, an die Ihr vorher nie gedacht hättet.\n\nWollt Ihr es sehen? Los, trainiert fleißig und lernt etwas Neues.\n\nKommt dann wieder und zeigt es mir.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24641] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24642] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = "Jeder <Volk> muss sich beweisen, bevor er das Trainingsgelände verlassen darf.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", rewards = "Ihr bekommt:\n\nKriegsaxt der Dunkelspeere"}
MultiLanguageQuestData['de'][24643] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nich' mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24645] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Rohlinge der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb Mühlenberns im Silberwald zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich außerhalb Mühlenberns im Silberwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24646] = {title = "Holt zurück, was uns gehört", objective = "Blast an der Waldrandhütte in das Horn von Tal'doren und beschafft Euch das mysteriöse Artefakt aus ihrem Inneren.", description = "Seit die Verlassenen in Gilneas einmarschiert sind, haben wir uns bemüht, den Aufbewahrungsort der Sichel von Elune geheim zu halten. Wir haben sie im Schutz der Nacht an einen von vielen sicheren Orten gebracht. Die Dunkelläufer sind ihr gefährlich nahe gekommen, haben sie aber nie gefunden... bis jetzt.\n\nZuletzt wurden sie an der Waldrandhütte westlich von hier gesichtet. Stoßt in dieses Horn, wenn Ihr sie gefunden habt. Tobias und seine Fährtenleser werden Euch zu Hilfe eilen und die Dunkelläufer bekämpfen.\n\nNur dann könnt Ihr Euch in die Hütte schleichen und die Sichel zurückholen. Schnell, <Name>. Sylvanas darf sie nicht in die Finger bekommen.", progress = "Habt Ihr die Sichel, <Name>?", completion = "Ich wusste, dass ich mich auf Euch verlassen kann. Ihr habt Eure Sache gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24647] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Gauner der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb des Hügellandhofs im Vorgebirge des Hügellands zu zerstören und kehrt zu Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich außerhalb des Hügellandhofs im - Ihr habt es erraten - Vorgebirge des Hügellands. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24648] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Gangster der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb von Theramore in den Düstermarschen zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in der Nähe der Späherwacht gleich außerhalb Theramores in den Düstermarschen. Jetzt seht mich nicht so an, okay? Das ist auch unser Problem. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24649] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Agenten der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich des Nistgipfels im Hinterland zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: östlich vom Nistgipfel im Hinterland. Jetzt seht mich nicht so an, okay? Das ist auch ein Problem der Horde. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24650] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Besprenkler der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich der Ewigen Warte in Winterquell zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in Winterquell, gleich östlich der Ewigen Warte. Oh, jetzt wird's persönlich. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24651] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Untergebene der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich von Shattrath in den Wäldern von Terokkar zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar gleich östlich von Shattrath, in den Wäldern von Terokkar. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24652] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Sprüher der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport in den Trostlosen Wäldern des Kristallsangwalds zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: wie's scheint in den Trostlosen Wäldern des Kristallsangwalds, nordwestlich des Zwielichtspiegels. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = "Habt Ihr es ihnen gezeigt?", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24653] = {title = "Agamaggans Widerhall", objective = "Findet 3 polierte Eberschädel.", description = "Ich glaube, die Stacheleber werden von mehr als nur reinem Verlangen angetrieben. Würdet Ihr mir helfen, das genauer zu untersuchen?\n\nIm Westen, verstreut über die Siedlungen und Lager der Stacheleber habe ich Eberschädel bemerkt. Aus der Entfernung glänzen sie, glattpoliert... Sie unterscheiden sich von den Überresten, mit denen ihre Abfallhaufen sonst übersät sind. Ich denke, es könnte sich um Gegenstände der Anbetung handeln.\n\nBringt mir einige davon, damit ich sie untersuchen kann, <Name>.", progress = "Habt Ihr die Schädel?", completion = "Ja, das sind ganz klar Symbole für Agamaggan. Aber wenn die Stacheleber immer noch ihrem toten Gott treu ergeben sind, was ist dann die Quelle für ihre bösartige Aggression? Man sagt, Agamaggan war edel und hat sogar sein Leben im Kampf für die Brennende Legion gegeben...\n\nEinen Moment, &lt;Name&gt;. Wir müssen uns mit unseren Geistern beraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24654] = {title = "Silithprobleme", objective = "Benutzt den Eimer mit brennendem Pech auf Silithidenhügeln und tötet 10 Silithidschwärmer, wenn sie herauskommen.", description = "Die Silithiden! Das sind Käfer, <Name>. Oder so etwas Ähnliches wie Käfer. Sie sind widernatürlich... und wir haben unsere Festung auf einer Art Ameisenhügel erbaut.\n\nNehmt dieses brennende Pech. Es wird die Viecher entzünden und gleichzeitig ihre Erdhöhlen verstopfen. Seid vorsichtig, wenn Ihr das Zeug hier ausgießt – die Silithiden werden in Schwärmen herauskommen!\n\nHaltet Ausschau nach Silithidenhügeln außen um die Ödnisfeste herum. Sie sehen wie Sandhügel aus. Tötet alles, was daraus hervorkrabbelt.", progress = "Die Allianz ist nichts. Schwärme von diesen Kribbelkrabblern?\n\n<Crawgol schaudert.>", completion = "Ihr seid mit heißem Teer und Käfersaft bedeckt! Macht Euch keine Sorgen, mein Freund. Das geht wieder ab.\n\nIrgendwann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24655] = {title = "Irgendwas stinkt hier", objective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", progress = nil, completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n&lt;Er nimmt das Gerät an sich und hantiert damit herum.&gt;\n\nOh, das ist gar nicht gut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24656] = {title = "Parfümdiebstahl", objective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Sturmwinds, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", progress = "Haben sie Euch eine Kiste zum Ausliefern zugeworfen?", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n&lt;Er öffnet die Kiste und untersucht den Inhalt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24657] = {title = "Eine nette Unterhaltung...", objective = "Begebt Euch zum Hafen von Sturmwind und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", description = "<Marion hört erschrocken zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, er hätte irgendeine Art Chemikalie auf mich angewandt? Igitt! Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Dock um ein Schiff in die Südlichen Meere zu erwischen! Was auch immer Ihr tut, <Name>, Ihr dürft ihn nicht davonkommen lassen!\n\nBeeilt Euch, geht zum Hafen von Sturmwind, bevor Ihr ihn verpasst!", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, &lt;Name&gt;! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24658] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport nordöstlich der Weststromgarnison im Wald von Elwynn zu beschädigen und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: nordöstlich der Weststromgarnison im Wald von Elwynn. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24659] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Rohlinge der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport südlich des Hains der Uralten an der Dunkelküste zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südlich des Hains der Uralten in Dunkelküste. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24660] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Gauner der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport auf dem verlassenen Bauernhof südöstlich von Dunkelhain im Dämmerwald zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südöstlich von Dunkelhain im Dämmerwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24661] = {title = "NEU VERWENDEN", objective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport gleich westlich der Tore Orgrimmars in Durotar zu beschädigen und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: im Westen, vor den Toren Orgrimmars. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24662] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Gangster der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb Theramores in den Düstermarschen zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in der Nähe der Späherwacht gleich außerhalb Theramores in den Düstermarschen. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24663] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Agenten der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich des Nistgipfels im Hinterland zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: östlich vom Nistgipfel im Hinterland. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24664] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Besprenkler der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich der Ewigen Warte in Winterquell zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in Winterquell, gleich östlich der Ewigen Warte. Oh, jetzt wird's persönlich. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24665] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Untergebene der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich von Shattrath in den Wäldern von Terokkar zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar gleich östlich von Shattrath, in den Wäldern von Terokkar. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24666] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Sprüher der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport in den Trostlosen Wäldern des Kristallsangwalds zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: wie's scheint in den Trostlosen Wäldern des Kristallsangwalds, nordwestlich des Zwielichtspiegels. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][24667] = {title = "Flammensteinspitze", objective = "Liefert Crawgols Silithidenführer bei Tauna Himmelsjäger an der Flammensteinspitze im Südlichen Brachland ab.", description = "Ich befasse mich seit fast einem Monat mit dieser Silithidensituation, was mich zum hiesigen Experten macht. Erst letzte Woche hat uns der Irdene Ring besucht und wollte, dass ich ihnen alles aufschreibe, was ich weiß.\n\n<Crawgol übergibt Euch ein zerfleddertes Buch.>\n\nIch bin kein guter Schriftsteller. Auch kein Leser, um ehrlich zu sein... Aber dieses Buch ist wahrscheinlich das ausführlichste, das je über diesen Feind geschrieben wurde.\n\nGebt es Tauna Himmelsjäger unten an der Flammensteinspitze. Sie befindet sich südlich von hier, westlich der Hauptstraße.", progress = "Ah, bringt Ihr mir Nachrichten aus dem Norden?", completion = "Ist das von Crawgol? Wunderbar! Trotz all des Aufruhrs in der Welt können wir unsere Augen nicht vor der Bedrohung durch die Silithiden verschließen. Für den Kampf, der vor uns liegt, ist es unerlässlich, dass Leute wie Crawgol unseren Feind gründlich studieren und seine Geheimnisse aufdecken\n\n&lt;Tauna öffnet das Buch und überfliegt die erste Seite. Ihr Gesicht wird lang.&gt;\n\nOh. Naja. Wenigstens etwas, denke ich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24671] = {title = "Glucken gucken", objective = "Fangt 10 wilde Glucken, indem Ihr ferngesteuertes Feuerwerk an ihnen anbringt.", description = "Lächerlich! Das größte Goblingenie aller Zeiten soll sich um so nichtige Dinge wie Nahrung kümmern?! Für genau diesen Zweck habe ich das Mikromechahuhn erschaffen, und sie lassen es davonlaufen!\n\n<Durch den steigenden Blutdruck wird Hobart noch dunkelgrüner im Gesicht.>\n\nSehe ich etwa aus, als wäre es meine Aufgabe, entflohene Glucken einzusammeln? Nein, mein Freund, nicht mit mir! Mit Bäm vielleicht, aber der ist zu faul.\n\nEuer gesellschaftlicher Rang hat sich in letzter Zeit dramatisch verschlechtert. Ihr macht das!\n\nNehmt dieses ferngesteuerte Feuerwerk und bringt es an den Glucken an. Und zwar schnell!", progress = nil, completion = "Erfolg! Gab es daran je Zweifel?\n\nGreely, werft schon mal den Geflügelisierer an!", rewards = "Zerbrochener StößelWummo KabummoIhr bekommt:\n\nLeere Instastadtschachtel"}
MultiLanguageQuestData['de'][24672] = {title = "Vorwärts und hoch hinaus", objective = "Sucht Krennan Aranas auf der Straße zur Witterfront.", description = "Ich werde das tun, worum Darius gebeten hat, und unsere Leute durch den Schwarzforst führen.\n\nIhr solltet zu König Graumähne aufschließen. Er und Krennan sind zur Witterfront aufgebrochen, nachdem Lord Godfrey bestätigt hatte, dass dort ein paar Überlebende ihr Lager aufgeschlagen haben.\n\nFolgt der Straße aus Sturmsiel in die Berge. Ich habe Krennan gebeten, an der Brücke vor der Witterfront auf Euch zu warten.", progress = nil, completion = "&lt;Name&gt;!\n\nGenn… Sie haben Genn… Sie haben… unseren König verschleppt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24673] = {title = "Rückkehr nach Sturmsiel", objective = "Sprecht mit Gwen Armstead in Sturmsiel.", description = "Es wird lange dauern, bis unsere Nation wieder zusammenfindet. Die früheren politischen Streitereien verblassen im Gegensatz dazu, was uns heute entzweit.\n\nDoch wenn es je eine Zeit gegeben hat, da wir uns zusammentun und gegen einen gemeinsamen Feind verbünden müssen, dann jetzt. Und Ihr, <Name>, seid es, <der/die> sich als fähig erwiesen hat, diese Lücke zwischen unseren Leuten zu schließen.\n\nKehrt nach Sturmsiel zurück und sagt ihnen, dass der Weg nach Witterfront durch den Schwarzforst sicher ist. Wir kümmern uns um die Verlassenen und folgen ihnen.", progress = nil, completion = "König Graumähne hat mir den Plan kurz erläutert, bevor er in den Schwarzforst aufgebrochen ist. Er klingt trotzdem nicht weniger verrückt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24674] = {title = "Niemandes Sklaven", objective = "Tötet Brothogg den Sklavenmeister in der Glutsteinmine.", description = "Ich war einer der wenigen, die entkommen sind, <Name>. Nachdem die Verlassenen unser Dorf und unsere Mine eingenommen hatten, haben sie uns mit höchster Grausamkeit behandelt.\n\nDiejenigen von uns, die schwach waren und keine schweren Arbeiten aushielten, ließ dieses abscheuliche Wesen namens Brothogg bis in den Tod schuften.\n\nMeine Frau war eines seiner Opfer, <Klasse>, und ich habe geschworen, dass ich für ihren Tod Rache nehme. Ich bin jetzt zu schwach, aber Ihr könnt für Gerechtigkeit sorgen. Für meine Frau... für Gilneas!", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Unser Volk wird nicht länger unter dem Joch dieser Ausgeburt leiden.", rewards = "Marcus' SpitzhackeArbeitergürtelGlutsteinketteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24675] = {title = "Die letzte Mahlzeit", objective = "Besorgt 10 Stück Hirschfleisch.", description = "Ich bin nicht dumm, <Name>. Ich weiß, was uns erwartet.\n\nUnser Volk wird diese Tore durchschreiten und gegen einen Feind kämpfen, der besser ausgebildet ist, zahlreicher ist und bessere Waffen als wir hat.\n\nSelbst wenn wir Erfolg haben, werden wir bitter dafür bezahlen müssen. Für die meisten von uns wird das Essen heute Abend die letzte Mahlzeit sein.\n\nIch kann nicht kämpfen, aber ich weiß, wie man kocht. Bringt mir Fleisch von den Hirschen in der Gegend. Ich werde sicherstellen, dass dieses letzte Mahl das Beste wird, was unsere Leute je gegessen haben.", progress = "Habt Ihr bekommen, was ich brauche, <Name>?", completion = "Ich danke Euch, &lt;Name&gt;. Unsere Männer und Frauen werden ein wundervolles letztes Mahl genießen, bevor sie in die Schlacht aufbrechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24676] = {title = "Vertreibt sie!", objective = "Tötet 4 Infanteristen der Verlassenen, Exekutor Cornell und Valnov den Verrückten in Glutstein.", description = "Unsere Leute sind frei, aber die Stadt wird immer noch von den Verlassenen belagert. Sie sind von ihren Kerntruppen abgeschnitten. Wenn wir sie also vertreiben wollen, ist jetzt die beste Gelegenheit.\n\nIhr Anführer, Exekutor Cornell, ist für seine grenzenlose Rücksichtslosigkeit bekannt. Unter seinen Männern befindet sich auch Valnov der Verrückte, ein so genannter Wissenschaftler, der grausame Experimente an Dorfbewohnern durchführt, die zu alt sind, um in den Minen zu arbeiten.\n\nVernichtet sie alle.", progress = "Ihr seid zurück, <Name>.", completion = "Jetzt haben wir dank Euch die Bewohner von Glutstein auf unserer Seite.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24677] = {title = "Flankiert die Verlassenen", objective = "Sprecht mit Lord Hewell, um Euch ein Pferd zur Pferdewechselstation zu organisieren, und meldet Euch bei Lorna Crowley.", description = "Ich danke Euch, <Name>. Wir können uns jedoch nicht auf unseren Lorbeeren ausruhen.\n\nWir haben von einem Bergbaudorf erfahren, das derzeit von den Verlassenen besetzt wird. Einige unserer Männer sind zusammen mit Crowleys Tochter zu den nahegelegenen Pferdeställen aufgebrochen, um von dort aus das Kommando zu übernehmen. Liam sollte in Kürze zu ihnen stoßen.\n\nIch bleibe hier und organisiere die letzte Angriffswelle in Gilneas. Sprecht mit Lord Hewell, um Euch ein Pferd zu besorgen, das Euch dorthin bringen kann.", progress = nil, completion = "Ich bin froh, dass Ihr hier seid, &lt;Name&gt;. Wir sind von allen Seiten von den Verlassenen umzingelt und können jede Hilfe brauchen, die wir kriegen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24678] = {title = "Knietief", objective = "Nehmt die halb abgebrannte Fackel, um an die andere Seite des Tunnels unter Gilneas zu gelangen.\n\nBereitgestellter Gegenstand: \n", description = "Es ist Zeit, zusammenzupacken, <Name>. Die meisten unserer Leute haben es auf die andere Seite geschafft. Jetzt seid Ihr dran.\n\nNehmt diese Fackel, Ihr werdet sie noch brauchen. Im Tunnel wimmelt es nur so von widerlichen Kreaturen der übelsten Sorte, die Euch in die Knie beißen werden. Verwendet die Fackel, um sie Euch fern zu halten.\n\nSprecht auf der anderen Seite mit Krennan.", progress = nil, completion = "Ihr seid hier, &lt;Name&gt;. Die meisten haben es auf die andere Seite geschafft, aber jetzt sitzen wir hier, umringt von unseren eigenen… Toten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24679] = {title = "Der Segen des Patriarchen", objective = "Legt die gesegneten Opfergaben auf Aderics Grab.", description = "Ihr habt es geschafft, <Name>. Sogar in Zeiten wie diesen müssen wir unseren Toten die Ehre erweisen.\n\nNehmt diese Opfergaben und legt sie auf Aderics Grab.\n\nHoffen wir, dass sie ausreichen, um die Geister unserer Ahnen zu besänftigen.", progress = nil, completion = "Es ist vollbracht, &lt;Name&gt;. Die Toten versinken wieder in ewigen Schlaf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24680] = {title = "Kielwasser", objective = "Sprecht mit Lord Darius Crowley in Kielwasser in Gilneas.", description = "Wir haben vielleicht unsere Stadt verloren, aber zumindest scheinen die Toten uns vergeben zu haben.\n\nSchließt Euch den restlichen Überlebenden in Kielwasser an.\n\nIch bin mir sicher, dass es noch viel zu tun gibt, bevor wir das Gröbste überstanden haben. Genn ist noch nicht eingetroffen, also nehme ich an, dass Lord Crowley dort das Sagen hat.", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24681] = {title = "Sie haben Verbündete, aber wir auch", objective = "Benutzt die Glevenschleuder der Nachtelfen, um 40 orcische Räuber, 8 Vorhuten des Wolfschlunds und 4 orcische Kriegsmaschinen zu vernichten.", description = "Die Nachtelfen haben ihr Versprechen gehalten. Sie haben uns Schiffe geschickt und bieten uns Schutz in ihrem Land.\n\nLeider sind aber auch die Verbündeten der Verlassenen eingetroffen.\n\nDie Orcs rücken immer näher und das Kanonenboot der Horde schneidet unseren Leuten auf den Transportschiffen den Weg in die Sicherheit ab.\n\nDie Druiden versuchen, den Feind zurückzuhalten, aber lange werden sie nicht durchhalten. Zum Glück haben die Elfenschiffe Belagerungswaffen mitgebracht. Nehmt eine von den Glevenschleudern und tretet dem Feind gegenüber!", progress = nil, completion = "Es ist fast vorbei, &lt;Name&gt;. Nur noch ein Hindernis steht zwischen uns und unserem Überleben.", rewards = "Nachtelfischer BogenSeryls VersprechenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24682] = {title = "Die Grube von Saron", objective = "Trefft Fürstin Sylvanas Windläufer am Eingang zur Grube von Saron.", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", progress = nil, completion = "Unfähige Narren! So langsam frage ich mich, ob sich überhaupt einer von diesen Knilchen vom Turnier als nützlich erweisen wird. Vielleicht könnt Ihr mich ja vom Gegenteil überzeugen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24683] = {title = "Die Grube von Saron", objective = "Trefft Lady Jaina Prachtmeer in der Grube von Saron.", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", progress = nil, completion = "Ich habe diesen Geißelfürsten unterschätzt und meine Leute haben dafür bezahlt. Immer, wenn ich denke, dass mich keine größere Schuld mehr an Arthas' Verrat treffen kann, belehrt er mich eines Besseren.\n\nWir müssen weitermachen! Ihr Opfer darf nicht bedeutungslos sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24684] = {title = "Der Fux im Hühnerstall", objective = "Begebt Euch in die Burg Bael'dun und tötet 10 Zwerge von Bael'dun (Scharfschützen, Soldaten oder Offiziere). Dann findet Fux Schattenschleicher, der sich irgendwo dort drinnen versteckt hält.", description = "<Gann packt Euch mit blutverkrusteter Hand.>\n\nMeine Wunden sind schwerwiegend, aber ich werde nicht aufgeben, bis die Zwerge von Bael Modan für ihre Verbrechen bezahlt haben. <Keuchen> Wir haben während unseres letzten Überfalls einen Mann in ihre Festung hineingeschmuggelt. Einen Saboteur der Goblins: Fux Schattenschleicher. \n\nStartet ein Ablenkungsmanöver vor den Toren, tötet, wen immer Ihr könnt - und dann schleicht Euch in die Festung Bael'dun im Süden und findet Fux.\n\nDiese Festung <hust> kann nur von innen heraus zerstört werden und Fux schafft das nicht alleine.", progress = nil, completion = "Ihr macht gute Arbeit, &lt;Klasse&gt;. Der Aufstand, den Ihr am Eingang zur Burg angezettelt habt, lässt die Zwerge völlig kopflos herumrennen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24685] = {title = "Zwergenfestung", objective = "Bringt den Plan der Burg Bael'dun an Euch.", description = "Ich weiß nicht, ob Ihr es auf Eurem Weg hinein bemerkt habt, aber die ganze Burg wurde um eine riesige Kanone herum erbaut. Wenn wir nur das Munitionslager finden könnten, dann wären wir in der Lage, hier alles in die Luft zu jagen und es wäre so einfach, wie ein Handkuss!\n\nNur, um das herauszufinden brauche ich die Bauzeichnung der Burg und bisher konnte ich die noch nicht stehlen.\n\nSucht nach den Plänen auf der untersten Etage, direkt die Treppe hier hinunter.", progress = "Gebt mir den Plan, schnell! Die Zeit wird knapp.\n\nHauptsächlich, weil ich meine Verkleidung gegessen habe.", completion = "Schauen wir mal, schauen wir mal...\n\nAnscheinend werden die Artilleriegranaten hier vorgefertigt und dann in das gesicherte Lager gebracht...\n\n&lt;Fux reibt sich die Hände.&gt;\n\n&lt;Name&gt;, seid Ihr bereit, etwas in die Luft zu jagen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24686] = {title = "Fortgespült", objective = "Verwendet Garls Netz um 4 Blutblütensamen einzufangen.", description = "Die Blutblüten in Un'Goro durchlaufen einen faszinierenden Lebenszyklus.\n\nDiese Bäume hier vor uns tragen Samen, die hinunter in den Fluss fallen, wenn sie reifen. Die Strömung trägt die Samen dann nach Norden, wo die Saat aufgeht - beinahe wie ein Ei - und eine neugeborene Blutblüte schlüpft.\n\nIch brauche diese Samen für meine Forschung. Nehmt dieses Netz und schöpft damit die leuchtend orangefarbenen Samen aus dem Fluss. Ihr werdet unter Wasser nach ihnen suchen müssen.", progress = "Habt Ihr schon alle Samen?", completion = "Hmm... ja, diese Samen dürften ausreichen. Der Zirkel des Cenarius dankt Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24687] = {title = "Sträuße des Todes", objective = "Tötet 6 Rudel halbwüchsiger Blutblüten.", description = "Die erste Phase des Lebenszyklus der Blutblüten kennt Ihr bereits: die schwimmenden Samen. Die nächste Phase ist aber nicht so zahm: die Rudel Halbwüchsiger.\n\nWenn die Blutblüten geschlüpft sind, bilden sie schnell Banden und ziehen gemeinsam umher, wodurch sie ihre Schwächen mit einer überwältigenden Mehrheit ausgleichen. Diese Banden junger Peitscher bleiben meistens unter sich, aber wenn man auch nur einen einzelnen von ihnen angreift, hat man es schnell mit allen zu tun.\n\nGebietet ihnen im Interesse unserer Sicherheit und der Sicherheit Anderer Einhalt. Ihr findet sie hier in der Nähe, im Westen und Norden.", progress = nil, completion = "Ihr kehrt siegreich zurück. Gut, gut... Vielleicht wird der Krater nun etwas sicherer für Reisende sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24688] = {title = "Zen'Aliri", objective = "Meldet Euch bei Zen'Aliri in Marschalls Wehr.", description = "Ihr habt bereits einen meiner neuen Schüler kennengelernt, den jungen Worgen namens Garl. Mein anderer Schüler ist der Troll Zen'Aliri. Er hat zur Zeit sein Zelt bei den Entdeckern in Marschalls Expedition westlich von hier.\n\nBringt ihm diese Ergebnisse, <Name>, und sagt ihm, er soll sie gründlich lesen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24689] = {title = "Nach Norden fließen", objective = "Meldet Euch bei Ithis Mondwärter in den Aufwühlenden Gärten.", description = "Ithis Mondwärter ist der Nachtelfendruide, der mich in den Zirkel des Cenarius eingeführt hat. Sein Lager liegt nördlich von hier, in der Nähe der Klippen am östlichsten Kraterrand. Folgt dem Strom der Blutblütensamen und ich wette, Ihr werdet ihn dort in der Nähe finden.\n\nMeine Studien beschränken sich lediglich auf die Samen und andere Reagenzien, er jedoch geht viel fortgeschritteneren Dingen nach. Falls Ihr neugierig geworden seid und mehr über die Flora Un'Goros erfahren wollt, solltet Ihr Euch jetzt an ihn wenden.", progress = nil, completion = "Ahh... Hat Garl Euch geschickt? Wie verlaufen seine Studien? Ich finde, er kann manchmal etwas langsam sein, aber in Bärengestalt sollte man ihn wahrhaftig besser nicht unterschätzen.\n\nNun, es gibt dringendere Dinge, die nach unserer Aufmerksamkeit verlangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24690] = {title = "Sturmflamme", objective = "Tötet Sturmflamme.", description = "Ich mache mir immer noch etwas Gedanken über diese Feuerelementare, <Name>. Eine letzte Bitte: Begebt Euch zur Spitze des Feuersäulengrats und tötet denjenigen von ihnen, den sie Sturmflamme nennen. Er ist der größte und stärkste der Feuerelementare im Krater. Ich werde viel besser schlafen, wenn er aus dem Weg ist.", progress = nil, completion = "Endlich ist Sturmflamme vernichtet. Danke, &lt;Name&gt;... Er hat mich zur Weißglut gebracht.", rewards = "SturmflammengamaschenMarschallarmschienenFeuersäulenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24691] = {title = "Eigenartige Delikatessen", objective = "Erhaltet 96 Silithidenbeine.", description = "He <Süßer/Süße>, Interesse, Euch was dazuzuverdienen?\n\nIch weiß aus sicherer Quelle, dass einige Interessengruppen gutes Geld für Silithidenbeine zahlen. Ja, Ihr habt richtig gehört, Silithidenbeine! Anscheinend sind die richtig lecker, wenn man sie richtig zubereitet. Die sind wie unterirdische Krebse und leben südlich von hier.\n\nDas Problem ist, dass ich eine ordentliche Menge brauche, um meine Ausgaben abzudecken. Meint Ihr, Ihr könntet mir vielleicht so etwa 8 Dutzend beschaffen?", progress = "Ich brauche eine Menge Beine, weil ich doch für den Versand, das Verladen, das Marketing und so weiter bezahlen muss... Oh und Euch muss ich auch noch bezahlen.", completion = "Hervorragend! Wir sitzen hier auf der Spitze von etwas ganz Großem, &lt;Name&gt;. Hier ist Euer Anteil an den garantiert riesigen Profiten.\n\nUnd jetzt auf zu anderen Dingen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24692] = {title = "Das Kolossjunge", objective = "Tötet das Kolossjunge der Gorishi.", description = "Wenn Ihr hier seid, um zu helfen, dann könntet Ihr Euch vielleicht einer lauernden Bedrohung annehmen.\n\nIm Süden liegt die Wuchernde Narbe, ein vor Silithiden wimmelnder Außenposten mitten im Dschungel. Ihr könnt ihn gar nicht übersehen.\n\nEiner meiner Kundschafter berichtet, dass die Silithiden einen jungen Koloss in ihrer großen, unterirdischen Zentralkammer beherbergen. Wenn diese Bestie erst einmal herangewachsen ist, soll sie auf Un'Goro losgelassen werden!\n\nSoweit darf es nicht kommen, <Name>. Spürt den Koloss auf und tötet ihn.", progress = nil, completion = "Ihr habt eine außerordentliche Aufgabe vollbracht, &lt;Name&gt;. Diese Belobigung habt Ihr Euch wahrhaftig verdient. Vielen Dank und herzlichen Glückwunsch!", rewards = "Keimerstickende ArmschienenKolossale TreterSilithidenschuppenhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24693] = {title = "Mooshügel", objective = "Meldet Euch bei Gremix am Mooshügel.", description = "Hier in Marschalls Wehr kann ich eigentlich nicht so viel Preisschneiderei betreiben, ohne dass die Wissenschaftler misstrauisch werden. Es gibt aber noch einen Ort, an dem Ihr mir von Nutzen sein könntet.\n\nMein Geschäftspartner Gremix hat ein Lager im Nordwesten, auf der anderen Seite des Vulkans. Er ist ein gerissener Geschäftsmann und hat sogar ein noch besseres Gespür für Profit als ich. Ich bin sicher, er könnte für Euch Arbeit finden, wenn Ihr Euch noch ein paar Münzen verdienen wollt.", progress = nil, completion = "Nun gut, wenn Quixxil Euch empfohlen hat, dann müsst Ihr wohl in Ordnung sein. In all den Jahren unserer Zusammenarbeit hat mich Quixxil nie fehlgeleitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24694] = {title = "Die Terrasse des Formers", objective = "Sprecht mit dem Prüfer von Un'Goro, um zur Terrasse des Formers teleportiert zu werden, und sprecht dann mit Nablya.", description = "<Als Ihr in die Kugel vor Euch blickt, hört Ihr eine Stimme.>\n\nDie Kristallpylonen wurden aktiviert. Eine ausreichende Menge Kristalle wurde gesammelt. Die Bedingungen wurden erfüllt. Wir sind bereit für den Teleport zur Terrasse des Formers.\n\nSprecht mich an, wenn Ihr bereit seid, <Volk>. Wir werden uns mit der Wächterin beraten.", progress = nil, completion = "Ich habe Euch beobachtet, &lt;Name&gt;. Eure Ankunft war nicht unerwartet.\n\nIn der Tat ist Eure Ankunft hier schon vor einiger Zeit vorherbestimmt worden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24695] = {title = "Der immer wachsame Blick von oben.", objective = "Legt die Hebel hinter Nablya um und vollendet ihre Prüfungen.", description = "Als mein Meister Khaz'goroth die Welt, die Ihr Azeroth nennt, formte, entwarf er den Un'Goro Krater als ein Gebiet, in dem Experimente stattfinden konnten. Man könnte ihn auch die Petrischale der Titanen nennen.\n\nFalls Ihr weiteres Wissen darüber erlangen wollt, wie wir die Welt beobachten, legt die vier Hebel hinter mir um und besteht meine Prüfungen.", progress = nil, completion = "Ihr habt unter Beweis gestellt, dass Ihr nicht nur weise, sondern auch behände seid, junger &lt;Name&gt;. Ich erteile Euch meinen Segen, Euer neuerlangtes Wissen auf Euren Reisen in die Welt zu tragen.", rewards = "Umhang der RastMantelung des Un'GoroAuf Euch wartet eine dieser Belohnungen:\n\nAmulett des neugewonnenen Wissens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24697] = {title = "Wie man Fleisch wieder frisch macht", objective = "Benutzt die Fetzen verdorbenen Fleisches, um die in der Nähe befindlichen Dinosaurier in die Gruben rund um Marschalls Wehr zu locken.", description = "Ich glaube nicht, dass wir einander schon kennengelernt haben... Ich bin Nolen Tacker, der neue Hauptmann der Wache von Marschalls Expedition. Ich bin außerdem der Koch hier. Da gibt es sogar mehr Überschneidungen, als man denken würde.\n\nIch habe eine spaßige kleine Aufgabe für Euch. Habt Ihr die Stachelgruben entlang der Außenbefestigung des Lagers gesehen? Schaut doch mal, ob Ihr nicht einige der Dinosaurier in der Nähe dazu bringen könnt, in diese Fallen zu tappen. Wenn Ihr dieses verfaulende Fleisch nach ihnen werft, wenn sie nicht hinsehen, werden sie entweder hungrig oder böse werden, was beides in Ordnung ist, solange sie Euch nur in die Gruben folgen!", progress = "Werft das Fleisch und lasst Euch dann von den Dinosauriern in die Gruben folgen. So einfach ist das!", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Jetzt sind wir ein wenig sicherer vor den Dinosaurierüberfällen... Außerdem habe ich all dieses frische Fleisch, das ich meinen Männern servieren kann.", rewards = "StegodonhauerstreitkolbenOsteodermengürtelDimetrodonplattenhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24698] = {title = "Archäologische Abenteuer", objective = "Meldet Euch bei Funks Nilminer bei den Heißen Quellen von Golakka.", description = "He, wollt Ihr meine Dimetrodonwürstchen probieren? Nein? Raptorrisotto? Pterrordaxtacos?\n\nNa gut. Oh, da fällt mir etwas ein! Ich habe hier in der Nähe einen Freund, der Eure Hilfe brauchen könnte. Sein Name ist Funks Nilminer und er ist der oberste archäologische Offizier in Marschalls Expedition. \n\nEr wurde hinaus zu den Heißen Quellen von Golakka im Westen geschickt. Ihr werdet ihn wahrscheinlich am Westufer der Quellen finden.", progress = nil, completion = "Der gute alte Nolen. Wie geht's dem so? Hoffentlich besser als mir...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24699] = {title = "Gormashh der Klebrige", objective = "Tötet Gormashh und erhaltet den unglaublich klebrigen Teer.", description = "He, ich hab's! Wir haben es mit den falschen Teergeschöpfen versucht.\n\nGremix hat mir einmal von einer übermäßig großen Teerkreatur erzählt, die ihm über den Weg gelaufen ist. Sie haust in der Nähe der Teergruben weit östlich von hier, südlich vom Fungusfels. Ich wette, je größer diese Kreaturen werden, desto klebriger werden sie! Wir machen schon noch Umsatz, <Name>! Vergesst den Schaber nicht!", progress = "Ich zähle auf Euch, <Name>. Ich habe mich ziemlich tief für diesen \"Teer als Klebstoff\"-Plan verschuldet und es wäre sehr schade, wenn Ihr mit leeren Händen zurückkehren würdet.", completion = "Ja, dieser Teer ist genau richtig...\n\nHe, wartet mal, meine Hände! Ich bekomme sie nicht mehr auseinander...\n\nVielleicht war das doch keine so gute Idee. Oh, Moment mal! Superklebriger Teerentferner! Da lässt sich das richtige Geld machen!", rewards = "Geteerte RobeKlebrige ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24700] = {title = "Schwer zu pflücken", objective = "Erhaltet 4 Teerblüten.", description = "Die Teergruben von Lakkari nördlich von hier bergen einen geheimen Schatz: seltene Blumen, die am Boden der Gruben wachsen. Man nennt sie Teerblüten und schätzt sie für ihre Schönheit und Widerstandsfähigkeit. Es ist schon eine Weile her, seit ich das letzte Mal Teerblüten gesammelt habe, also sollten mittlerweile einige neue Pflanzen am Boden der Gruben nachgewachsen sein. Würdet Ihr ein paar für mich holen?\n\nÜbrigens, viel Spaß beim Teerschwimmen. Das hat überhaupt nichts mit Schwimmen im Wasser gemeinsam.", progress = "Habt Ihr schon die Teerblüten gesammelt? Ich sehe sie nirgends...", completion = "Ah, da sind sie ja. Ausgezeichnete Arbeit, Hübscher! Hier habt Ihr etwas Gold. Ihr habt es Euch verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24701] = {title = "Marschalls Überbleibsel", objective = "Erhaltet 10 weggeworfene Vorräte.", description = "Ein Großteil beim Profit machen ist Unverschämtheit. Ihr müsst bereit sein, Euren Nutzen aus dem Unglück anderer zu ziehen. Es läuft alles auf eine Frage hinaus: Wie sehr liebt Ihr Geld?\n\nAls Marschall und seine Truppe ihre Zuflucht im Norden verlassen haben, mussten sie eine Menge Vorräte zurücklassen. Das Zeug ist nicht selten, oder gar besonders wertvoll, aber es liegt dort herum, wenn Ihr gewillt seid, es Euch zu nehmen. Sein Lager ist oben zwischen den Klippen im Norden.\n\nOh, und nehmt Euch in Acht vor was auch immer die anderen in die Flucht geschlagen hat.", progress = "Habt Ihr etwas Brauchbares gefunden?", completion = "Das ist zwar ein Haufen Ramsch, aber dafür ist es ein Haufen KOSTENLOSER RAMSCH und das ist das einzige, was für mich zählt.\n\nNaja, weitestgehend kostenlos. Hier ist Euer Anteil. Danke!", rewards = "Doreens ZauberstabZurückgelassene GamaschenWeggeworfene ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24702] = {title = "Hier ruht Dadanga", objective = "Erhaltet 10 Blutblütensprösslinge.", description = nil, progress = "Verlässliches Lasttier und treuer Freund.\n\nStarb kurz nach dem Kataklysmus. Er hatte laute Geräusche immer verabscheut.\n\nAnstelle von Blumen legt bitte ein paar Blutblütensprösslinge nieder. Als er noch am Leben war, hatte er nichts lieber.", completion = "&lt;Ihr verspürt beinahe so etwas wie eine Welle der Dankbarkeit als Ihr die Blutblütensprösslinge auf das Grab legt.&gt;", rewards = "Ihr erlernt:\n\nDadangas Segen"}
MultiLanguageQuestData['de'][24703] = {title = "Eine wichtige Lektion", objective = "Sprecht mit Maximillian von Nordhain und erfahrt mehr darüber, wie man Knappe wird.", description = "Heda, <Reisender/Reisende>! Ihr müsst wissen, dass Ihr das Lager des Maximillian von Nordhain betreten habt. Vielleicht habt Ihr schon Geschichten über meine vielen Heldentaten gehört? Ich kann es Euch ansehen, dass dem so ist. Dieser Funke der Erinnerung huscht über Euer Antlitz wie das Spiegelbild der Weißen Dame über den Steinhügelsee.\n\nEs ist offensichtlich, dass Ihr nach Abenteuern sucht. Da Ihr einigermaßen fähig zu sein scheint, und durch und durch wohlwollend, möchte ich Euch anbieten, mein Knappe zu werden.", progress = nil, completion = "Ihr erfreut mich, &lt;Name&gt;. Von heute an seid Ihr nicht länger ein einfacher Bettler, sondern ein Knappe im Dienste des Maximillian von Nordhain. Macht Euch bereit für unseren ersten Ausflug, mein treuer Knappe, denn gemeinsam wollen wir uns kopfüber ins Abenteuer stürzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24704] = {title = "Die bösen Drachen im Un'Goro Krater", objective = "Helft Maximillian von Nordhain 15 \"Drachen\" zu töten.", description = "Dieser Krater ist voll von einer bösartigen Brut von Drachen. Habt Ihr sie gesehen? Sie streifen umher und tragen ihre gezackten Rücken und Echsengesichter überall im Krater zur Schau.\n\nLasst Euch nicht von ihnen in die Irre führen, Knappe, denn diese Drachen sind keine Diener der anmutigen Alexstrasza. Sie sind ganz offensichtlich bösartig und benötigen dringend der Zuwendung einer Heldenklinge.\n\nIch habe beschlossen, dass ich nicht weniger als 15 von ihnen erlegen werde. Als mein Knappe müsst Ihr mich begleiten. Sollten wir getrennt werden, könnt Ihr mich hier an den heißen Quellen wiederfinden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24705] = {title = "Dorfbewohner sind zum Retten da", objective = "Rettet den Schützling am See, den Schützling auf den Klippen und den Schützling im Norden.", description = "Ich habe so das Gefühl, dass wir in diesem Krater mehr als Drachen vorfinden. Mein Paladininstinkt sagt mir, dass Dorfbewohner in der Nähe sind, die unsere Hilfe brauchen. Wenn jemand in Not ist, dürfen wir es nicht ignorieren.\n\nLasst uns sofort aufbrechen, Knappe <Name>! Das Volk von Un'Goro braucht uns!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24706] = {title = "Die Geister der Heißen Quellen von Golakka", objective = "Wartet in der Nähe, während Maximillian von Nordhain mit 2 dampfenden Furien spricht.", description = "Einen Moment der Ernsthaftigkeit, <Name>. Wir haben eine wichtige Aufgabe vor uns. Die verräterischen Drachen, die dieses Tal heimsuchen, werden in ihren Missetaten nicht innehalten, bis wir deren widerwärtige Brutmutter zur Strecke gebracht haben. Bevor wir aber auch nur daran denken können, solch eine Tat zu vollbringen, müssen wir das Licht um Beistand bitten.\n\nIch habe das Licht sich in der Nähe manifestieren sehen und zwar in der Form von Geistern, die an den Ufern der Heißen Quellen von Golakka schweben. Kommt, ich muss mit ihnen sprechen und sie um Hilfe bitten.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Complete: The Spirits of Golakka Hot Springs\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24707] = {title = "Die Ballade von Maximillian", objective = "Helft Maximillian von Nordhain die Königin der Teufelssaurier zu töten. Wenn Ihr von Maximillian getrennt werdet, sprecht mit ihm an den Heißen Quellen von Golakka im Un'Goro Krater.", description = "Der Augenblick auf den wir gewartet haben, ist nun da, Knappe <Name>. Un'Goros Brutmutter wird zu meinen Füßen sterben. Der Ernst unserer Aufgabe liegt mir schwer auf dem Gemüt, aber mit der Macht des Lichts auf unserer Seite können wir nicht scheitern.\n\nSeid Ihr zur Abreise bereit?Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Maximillians SchildSchwert des NordhainsAuf Euch wartet eine dieser Belohnungen:\n\nSpielzeugwindmühle\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24708] = {title = "Der Fossilienfinder 3000", objective = "Erhaltet eine gigantische Dinosaurierklaue", description = "Eines der Dinge, die ich am Meisten am Graben hasse, ist die Tatsache, dass man die Hälfte der Zeit nur Dreck findet. Deshalb habe ich den Großteil meiner Zeit hier mit Tüfteln statt mit Graben verbracht.\n\nLasst mich Euch zeigen, was ich erfunden habe: Der Fossilienfinder 3000. Ich habe gerade die letzten Handgriffe daran gemacht. Wenn er richtig funktioniert, sollte er die größten Fossilien in der Umgebung finden. Ich weiß, toll, oder?\n\nProbiert es einmal und schaut, ob Ihr nicht ein paar lächerlich große Dinosaurierknochen finden könnt.", progress = "Habt Ihr etwas gefunden? Hat es funktioniert?", completion = "Was für einen interessanten Oberschenkelknochen Ihr mir da gebracht habt, aber warum ist er so scharf und geschwungen?\n\n...\n\nEinen Moment mal, das ist eine KLAUE? Ein Dinosaurier mit einer Klaue von solchen Ausmaßen wäre... nun ja, ziemlich groß gewesen, soviel ist sicher. Ist das das einzige Fossil, das Ihr dort gefunden habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24709] = {title = "Die Geschichte von den zwei Schaufeln", objective = "Tötet Durrin Düsterschippe und erhaltet Durrins archäologische Erkenntnisse.", description = "Einen Moment mal, dieser Knochen hat Spitzhackenkerben. Die stammen nicht von Euch, oder? Nein, ich erkenne diese Kerbe... das muss dieser verdammte Zwerg sein! Gah!\n\nErlaubt mir, dies kurz zu erklären. Es gibt noch einen anderen Archäologen südlich von hier, der Durrin Düsterschippe heißt. Er praktiziert eine rücksichtslose \"Nach mir die Sintflut\"-Archäologie, die sogar mich abstößt.\n\nEin unbezahlbares Fossil ruiniert durch schlampiges Graben. Das ist wirklich das Ende der Fahnenstange, Durrin!\n\n<Name>, geht und bereitet Düsterschippe und seiner fahrlässigen Ausgrabung ein Ende.", progress = "Ist es vollbracht? Habt Ihr seine Aufzeichnungen bergen können?", completion = "Ich wusste es! Durrin HAT hier herumgewühlt. Und er war dabei etwas auszugraben, was sich als der archäologische Fund des Jahrhunderts herausstellen könnte! Nun muss ich nur herausfinden, wo er die Knochen verstaut hat...\n\nDanke, &lt;Name&gt;. Ihr wart mir eine große Hilfe.", rewards = "Umsichtige BedeckungAusgegrabene ArmschienenAuf Euch wartet eine dieser Belohnungen:\n\nNilminers Aufzeichnungen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24710] = {title = "Befreiung aus der Grube", objective = "Tötet Geißelfürst Tyrannus.", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen.\n\nEr wird sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, <Klasse>. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", progress = nil, completion = "Welch sinnlose Verschwendung! Arthas ist zu weit gegangen! Ich hoffe nur, dass das, was wir in den Hallen der Reflexion vorfinden werden, all das wert ist.\n\nWenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24711] = {title = "Frostgram", objective = "Trefft Lady Jaina Prachtmeer am Eingang zu den Hallen der Reflexion.", description = "Wir müssen weiter! Wir sind schon so weit gekommen... wir sind unserem Ziel ganz nah.\n\nIch muss Euch kurz verlassen und Elandra zum Luftschiff zurückschicken. Ich weiß nicht genau, wie wir fliehen sollen, wo wir so viele Leute verloren haben und nur noch wenige übrig sind, die unseren Pfad sichern.\n\nMacht weiter, ich erwarte Euch in den Hallen der Reflexion.", progress = nil, completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid. Arthas ist zwar nicht hier, aber es wäre naiv, zu glauben, er ließe Frostgram vollkommen unbewacht zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24712] = {title = "Befreiung aus der Grube", objective = "Tötet Geißelfürst Tyrannus.", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen.\n\nDort wird er sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, <Klasse>. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", progress = nil, completion = "Die Hallen der Reflexion liegen vor uns. Wenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24713] = {title = "Frostgram", objective = "Trefft Fürstin Sylvanas Windläufer am Eingang zu den Hallen der Reflexion.", description = "Macht weiter, wir sind dem Schwert ganz nahe.\n\nIch brauche einen Augenblick, um eine meiner Dunklen Waldläuferinnen zurück zum Luftschiff zu schicken. Jetzt, wo wir keine Unterstützung mehr haben, müssen Vorkehrungen getroffen werden. Wir brauchen jede Hilfe, die wir kriegen können!\n\nGeht, ich erwarte Euch in den Hallen der Reflexion.", progress = nil, completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid, &lt;Klasse&gt;. Ich werde nicht so naiv sein, zu glauben, dass Arthas sein wertvolles Schwert vollkommen unbewacht zurückgelassen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24714] = {title = "Chasing A-Me 01", objective = "Findet A-Me 01 am Fungusfels.", description = "Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Kraters von Un'Goro heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.\n\nSie untersucht schon seit mehreren Monaten die örtliche Fauna am Fungusfels, aber sie hätte längst zurückkehren sollen. Ich befürchte das Schlimmste.\n\nKönnt Ihr mir helfen, sie zu finden?", progress = nil, completion = "A-Me liegt bewegungslos vor Euch. Durch ihre Bauteile scheint kein Strom zu fließen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24715] = {title = "Reparatur von A-Me 01", objective = "Ihr seid ziemlich sicher, dass A-Me 01 möchte, dass Ihr eine Kokosnuss von Un'Goro besorgt, sie am Felsen in der Nähe aufschlagt und ihr die Kokosmilch mit hoher Viskosität gebt.", description = "<Die Augen des Gorillaroboters leuchten plötzlich auf und er beginnt zu sprechen.>\n\n\"… Betriebskapazität… weniger als 5%... Ölbehälter… versehentlich beschädigt…\"\n\n\"… Kokosmilch benutzen… Fels… A-Me 01 retten…\"\n\n<A-Me 01 schließt die Augen.>", progress = "<A-Me 01 ist in den Energiesparmodus gewechselt.>", completion = "Ihr schüttet die Kokosmilch in das, was Ihr für A-Mes Ölbehälter haltet. Ihr hört, wie die Zahnräder sich zu drehen beginnen und die Stellmotoren surrend anspringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24717] = {title = "Die Affen von Un'Goro", objective = "Bringt Gremix am Mooshügel 2 Gorillapelze von Un'Goro, 2 Stampferpelze von Un'Goro und 2 Donnererpelze von Un'Goro.", description = "Hier in Un'Goro gibt es Unmengen von Gorillas, man muss nur wissen, wo man suchen muss!\n\nDoch während sie in Un'Goro ein gewohnter Anblick sind, gibt es im Norden deutlich weniger Affen. In der Ewigen Warte bringt ein Gorillapelz im Vergleich zum Marktwert hier unten den zehnfachen Preis!\n\nIch werde Euch nicht den ganzen Weg nach Winterquell schicken, das wäre unverantwortlich. Aber ich könnte Eure Hilfe bei der Beschaffung der Pelze brauchen.\n\nIm Nordosten, in der Nähe eines Wasserfalls, befindet sich der Fungusfels. Dort halten sich viele Gorillas auf. Vergesst nicht, auch in der Höhle nachzusehen!", progress = "Ich weiß nie, was gerade modern ist, also will ich ein paar verschiedene Farben. Versucht, Pelze von unterschiedlichen Gorillaarten zu sammeln.", completion = "Hui, gleich zwei von jeder Farbe! Ihr macht keine halben Sachen, was, &lt;Name&gt;? Meine Kollegen und ich könnten jemanden wie Euch hier gut brauchen. Habt Ihr je daran gedacht, ins Profitgeschäft einzusteigen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24718] = {title = "Der mächtige U'cha", objective = "Bringt U'chas Pelz zu Gremix am Mooshügel.", description = "Als Ihr Euch umseht, bemerkt Ihr in diesem Teil der Höhle rote Fellfetzen. Von seiner Beschaffenheit her scheint es Gorillafell zu sein.\n\nIhr erinnert Euch an das Gespräch mit Gremix und seid Euch sicher, dass er an einem roten Gorillapelz sehr interessiert wäre, wenn Ihr einen bekommen könntet.", progress = "Rotes Fell? Worauf wartet Ihr noch? Geht und schnappt Euch diesen roten Gorilla! Ich zahle Euch das Doppelte!", completion = "Schaut Euch das nur an! Nicht nur die Farbe, sondern auch die immense Größe… Damit könnte man locker einen Tauren ausstaffieren.\n\nBitteschön, &lt;Name&gt;. Das habt Ihr Euch verdient. Bleibt in der Nähe. Ich bin mir sicher, dass wir noch andere Aufgaben für Euch haben.", rewards = "WildtierklopperWildtiertöterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24719] = {title = "Weiße Klauen", objective = "Sammelt 5 weiße Ravasaurusklauen.", description = "Halt, <Volk>. <Ein/Eine:c> <Klasse> wie Ihr wäre mir gerade eine echte Hilfe.\n\nDirekt außerhalb dieses Lagers gibt es Raptoren mit tödlichen Klauen. Ich habe diese Klauen in einem druidischen Ritual benutzt, aber sie scheinen nicht zu funktionieren. Mir ist jedoch aufgefallen, dass die Klauen einiger Raptoren weiß sind, während die anderen meist tödliche schwarze Klauen haben.\n\nDie Erde geht manchmal komische Wege. Vielleicht könntet Ihr mir ein paar dieser weißen Klauen sammeln, damit ich es noch einmal probieren kann?", progress = "Habt Ihr schon Klauen finden können?", completion = "Mein Mentor sagt, dass man der Natur manchmal etwas nehmen muss, bevor man ihr etwas zurückgeben kann. Diese Raptoren… Ich habe das Gefühl, dass sie für eine gute Sache gestorben sind.\n\nVielen Dank, &lt;Name&gt;.", rewards = "WeißknochenprügelWeißknochenruteAuf Euch wartet eine dieser Belohnungen:\n\nWeißknochenreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24720] = {title = "Machtkristalle", objective = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün.", description = "Ich bin sicher, Ihr habt sie bemerkt, <Name>. Sie sind überall!\n\nWovon ich rede? Na, von den Kristallen natürlich!\n\nDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht.\n\nAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?\n\nDie gelben Kristalle findet Ihr im Nordwesten, die roten im... Ach, Ihr werdet es schon herausfinden.", progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, <Name>!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24721] = {title = "Der Ostpylon", objective = "Berührt den Ostpylon im Krater von Un'Goro.", description = "Hoch auf den Klippen über mir gibt es einen großen Kristallpylonen. Ich weiß nicht, wer ihn dort aufgestellt hat, noch fällt mir ein Grund ein, warum man ihn an einem so merkwürdigen Ort errichten sollte.\n\nVielleicht könnt Ihr ja mehr herausfinden als ich. Mir persönlich ist es völlig egal, was dieses Ding tut, also braucht Ihr Euch nicht mehr bei mir zu melden. Aber vielleicht interessiert sich einer der Gelehrten in Marschalls Wehr ja für Eure Entdeckungen.", progress = nil, completion = "Es war klug von Euch, mir von diesem Pylonen zu erzählen, &lt;Name&gt;. Genau damit beschäftigen sich meine Forschungen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24722] = {title = "Der Nordpylon", objective = "Findet den Standort des nördlichen Kristallpylonen im Krater von Un'Goro.", description = "Ihr habt uns schon so viele Gefallen getan, <Name>… Jetzt lasst Gremix Euch einmal helfen. Die Angriffe auf Marschalls Zuflucht waren zweifelsohne schrecklich. Sie kamen ohne Vorwarnung und haben keine Gefangenen gemacht. Sie können von Glück sagen, dass so viele überlebt haben.\n\nVor ein paar Wochen bin ich auf den Klippen nordöstlich von hier, im Osten von Marschalls Zuflucht, an einem Kristallpylonen vorbeigekommen. Ich glaube, der Pylon und die Angriffe könnten irgendwie zusammenhängen. Könnt Ihr das vielleicht untersuchen? Ich bin mir sicher, dass jemand in Marschalls Wehr Euch dafür sehr dankbar sein wird.", progress = nil, completion = "Und Ihr glaubt, das könnte irgendwie mit den Angriffen auf Marschalls Zuflucht zusammenhängen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24723] = {title = "Der Westpylon", objective = "Findet den Standort des westlichen Kristallpylonen im Krater von Un'Goro.", description = "Durrins Untersuchungen umfassen einen Punkt, der mich total fasziniert: eine mögliche Verbindung zwischen den Titanen und den Dinosauriern. J.D. Collie im Lager spricht immer von den Titanen hier, den Kristallen da… Vielleicht interessiert sie sich ja dafür.\n\nBevor Ihr Euch jedoch bei ihr meldet, solltet Ihr Euch den Kristallpylonen in der Nähe anschauen. Er befindet sich direkt oben auf den Klippen, westlich von hier. Er ist von Kristallen umgeben. Irgendwie hatte ich immer den Eindruck, dass er etwas mit den Titanen zu tun hat.", progress = nil, completion = "Ein Pylon im Westen? Und eine Verbindung zwischen den Titanen und Dinosauriern? Das sind aber viele Informationen auf einmal, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24724] = {title = "Kristallflicker", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKristallflicker"}
MultiLanguageQuestData['de'][24725] = {title = "Kristallsprengladung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKristallsprengladung"}
MultiLanguageQuestData['de'][24726] = {title = "Kristallkraft", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKristallkraft"}
MultiLanguageQuestData['de'][24727] = {title = "Kristallspitze", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKristallspitze"}
MultiLanguageQuestData['de'][24728] = {title = "Kristallbarriere", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKristallbarriere"}
