MultiLanguageQuestData['de'][24730] = {title = "Knochenklappern", objective = "Besorgt 8 Dinosaurierknochen.", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marschalls Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodonten und Dimetrodonten graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", progress = "Ihr könnt von mir denken, was Ihr wollt, aber denen ist es doch völlig egal, ob die Knochen, die sie zum Erforschen bekommen, von uralten Stegodonten und Dimetrodonten stammen oder von den Viechern, die uns beinahe zum Frühstück verspeist hätten, als wir gerade unser Lager aufschlugen. Ich bin schon glücklich, wenn wir hier lebend rauskommen...", completion = "Wunderbar, das sollte funktionieren. Und jetzt, wenn Ihr erlaubt...\n\nDANKE, DASS IHR ALL DIESE KNOCHEN FÜR UNS AUSGEGRABEN HABT, OHNE DEN HIER LEBENDEN TIEREN SCHADEN ZUZUFÜGEN!\n\nOb das wirklich so war oder nicht, das will ich gar nicht wissen. Belassen wir es dabei, in Ordnung? Hier - vielleicht hilft Euch das, über die ganze Angelegenheit Euren Mund zu halten. Jedes Mittel ist recht, wenn wir nur lebendig hier rauskommen, sage ich!", rewards = "Allzweckstiefel des ArchäologenSteinbruchgürtel des AusgräbersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24731] = {title = "Lar'korwis Mahl", objective = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes.", description = "Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.\n\nLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.\n\nWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.\n\nBeginnt Eure Suche im Westen.", progress = "Hört auf meine Worte, <Name>. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, &lt;Name&gt;. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24732] = {title = "Lar'korwis Fährte", objective = "Besorgt 2 Pheromondrüsen eines Ravasaurus.", description = "Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, <Name>. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.\n\nAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasauruseier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.", progress = "Seid vorsichtig, <Name>. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, &lt;Name&gt;. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24733] = {title = "Ein Köder für Lar'korwi", objective = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro.", description = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Folgt dem Fluss weiter nach Norden und haltet nach einer Flussbiegung Ausschau. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit dieser Mischung ein.\n\nWenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.", progress = "Lasst Euch nicht von Furcht überwältigen, <Name>. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, &lt;Name&gt;. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch.", rewards = "EbenenpirscherwesteVorhutkettenrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24734] = {title = "Verloren!", objective = "Sucht nach Hinweisen auf Ringo am Feuersäulengrat.", description = "Ihr müsst mir helfen, <Name>! Mein Freund Ringo ist vor einer Weile aufgebrochen, um den Vulkan nördlich von hier zu erforschen, und er ist schon viel zu lange weg. Ich mache mir große Sorgen um ihn.\n\nMeint Ihr, Ihr könnt ihn suchen? Nehmt doch meine Feldflasche mit - wenn Ihr Ringo tatsächlich findet, dann hat er sie bestimmt nötig!", progress = "Ringos Sack liegt auf dem Felsen vor Euch.", completion = "Dies scheinen Ringos Habseligkeiten zu sein. Wenn er sie hier zurückgelassen hat, kann er nicht weit entfernt sein. Vielleicht solltet Ihr nach ihm suchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24735] = {title = "Etwas Hilfe von guten Freunden", objective = "Führt Ringo zu Spraggel Frock in Marschalls Wehr.\n\nFalls Ringo schwach werden sollte, gebt ihm eine Ohrfeige. Falls er ohnmächtig werden sollte, verwendet Spraggels Feldflasche, um ihn zu beleben.", description = "Argh... es ist so heiß...\n\nIch war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Ich muss wohl einen Hitzschlag haben.\n\nBitte, bringt mich zu meiner Freundin Spraggel in Marschalls Wehr zurück. Ich glaube, es geht mir noch gut genug, um Euch dorthin zu folgen.\n\nAber ich fühle mich ziemlich schwach. Wenn ich also noch mal in Ohnmacht fallen sollte, dann bespritzt mich einfach mit etwas Wasser aus Spraggels Feldflasche. Das sollte helfen, hoffe ich...", progress = nil, completion = "Ringo ist in keiner besonders guten Verfassung, &lt;Name&gt;, aber ich bin froh, dass ich ihn in einem Stück zurückhabe.\n\nDanke, dass Ihr ihn gefunden habt.", rewards = "WaldlandgamaschenLehmgratkopfstückJuwelenbesetzte BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24736] = {title = "Sappalots Flieger", objective = "Sammelt 35 Membranschuppen eines Pterrordax'.", description = "Ich baue einen Flugapparat!\n\nIch bin hier gestrandet und habe leider absolut überhaupt keinen Orientierungssinn. Ich würde ja einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Viecher jagen mir einfach eine höllische Angst ein.\n\nAlso, werdet Ihr mir helfen? Ich muss nur noch die Flügel bauen und ich glaube, dass sich die Membranschuppen der Pterrordax und Dimetrodonten perfekt dafür eignen würden. Ich werde mich zwar garantiert nicht mit denen anlegen, aber Ihr seht ziemlich zäh aus. Wollt Ihr es nicht versuchen?", progress = "Jedes berühmte Fahrzeug braucht einen Namen. Ich dachte, ich nenne es... Pwned!", completion = "Ja, diese Schuppen sind perfekt. Mit diesen Schuppen kriege ich meinen Flieger bestimmt in die Luft!\n\nDanke!", rewards = "Sappalots MündungsreinigerSappalots MündungsabdeckungSappalots NieselschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24737] = {title = "Superkleber", objective = "Sammelt 8 Proben superklebrigen Teers.", description = "Ich bin immer auf der Suche nach neuen Methoden, um schnelles Gold zu verdienen, <Name>. Wenn Ihr mir bei meiner neuesten Idee helft, dann gebe ich Euch ein bisschen was vom Gewinn ab. Na, was sagt Ihr dazu?\n\nDas hab ich mir gedacht!\n\nWir werden ein wenig Klebstoff herstellen. Geht zu den Teergruben nördlich von hier und beschafft mir etwas Teer. Aber nicht jeden x-beliebigen Teer, versteht Ihr? Ihr müsst den von den Kreaturen nehmen, die an den Teergruben leben. Und wenn Ihr meinen Teerkratzer an ihren Leichen verwendet, bleiben sogar Eure Patschehändchen schön sauber.", progress = "Und Tara hat es wieder einmal geschafft - dieser Superkleber wird der letzte Schrei!", completion = "Ja, dieser Teer ist schon ganz schön klebrig. Ich meine, er ist klebrig, aber nicht \"Damit mache ich haufenweise Kohle\"-klebrig. Da muss ich wohl weitergrübeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24740] = {title = "Vulkanische Aktivität", objective = "Sammelt 9 Proben der Asche von Un'Goro von den Feuerelementaren am Vulkan im Krater von Un'Goro.", description = "Willkommen. Ich bin Williden Marschall. Ich führe diese Expedition von Entdeckern und Wissenschaftlern zusammen mit meiner Schwester an. Habt Ihr einen Moment Zeit?\n\nIch mag diesen Anblick der Elementare auf diesem Vulkan da ganz und gar nicht, <Klasse>. Wir haben zu viel Ausrüstung und zu viele Notizen... Wenn auch nur einer dieser wahnsinnigen Elementare sich in unser Lager verirrt, könnte er schlimme, schlimme Schäden anrichten.\n\nZeigt ihnen, dass sie sich nicht mit ihren neuen Nachbarn anlegen sollten. Und bringt mir die Asche, die sie zurücklassen... Wenn wir schon dabei sind, können wir uns gleichzeitig ein wenig der Wissenschaft widmen.", progress = "Glaubt Ihr, dass der Vulkan in Un'Goro aktiv ist? Ich frage mich, warum er nicht explodiert ist, als der Kataklysmus uns getroffen hat.", completion = "Ich hoffe, das hat ihnen gezeigt, mit wem sie es zu tun haben. Ich nehme die Asche an mich… Irgendwann wird sie uns sicher nützlich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24741] = {title = "Ein guter Tausch", objective = "Sammelt 5 Eier eines stacheligen Raptors.", description = "Hobart glaubt also, dass er uns mit diesem kleinen Gluckeneiern abspeisen kann? Pah! Wir besorgen uns richtige Eier!\n\nIch habe bereits ein paar Fallen auf dem Raptorenbuckel den Pfad entlang Richtung Osten aufgestellt. Die stacheligen Raptoren werden sich sofort auf die Gluckeneier stürzen, sodass Ihr sie gegen ihre größeren Eier tauschen könnt.\n\nGenial!", progress = "Wie viele habt Ihr zusammen? Ich kann das riesige Omelette fast schon schmecken, das wir daraus kochen werden!", completion = "Super! Schaut nur, wie groß diese Dinger sind!\n\nDie kann Wurfhammer sicher nicht überbieten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24742] = {title = "Die Quelle finden", objective = "Krakle im Krater von Un'Goro möchte, dass Ihr den heißesten Bereich des Feuersäulengrats findet.\n\nImmer, wenn Ihr eine heiße Stelle findet, benutzt das Thermometer, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", description = "Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!\n\nHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!\n\nHeiße Stellen erkennt Ihr in der Regel an einer leuchtenden Felssäule. Ihr findet sie um den Feuersäulengrat herum. Eine Umrundung sollte eigentlich schon genügen.", progress = "Ich würde ja selbst gehen, aber... ich habe ein wenig Angst vor den Feuerelementaren dort!", completion = "Diese Ergebnisse sind verblüffend! Mein Chef wird sehr zufrieden sein. Vielen Dank, lieber &lt;Volk&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24743] = {title = "Schattenschneide", objective = "Hört gut zu, <Klasse>. Indem Ihr diese Waffe annehmt, wird Euer Schicksal besiegelt.\n\nSiegt oder geht unter.\n\nIch habe Euch auf diesen Weg gebracht, womit ich die Verantwortung für Euch übernommen habe. Solltet Ihr ins Wanken geraten, ist es meine Pflicht, Euch von diesem Leben zu erlösen.\n\nDenkt an meine Worte, <Volk>, und versagt nicht!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchattenschneide"}
MultiLanguageQuestData['de'][24744] = {title = "Das größte Ei aller Zeiten", objective = "Besorgt Euch das größte Ei aller Zeiten.", description = "Bäm Megabombe? Was glaubt er eigentlich, wer er ist? Seine Eier von stacheligen Raptoren sind gar nichts gegen das, was wir uns jetzt besorgen werden!\n\nWie Ihr wisst, verfügt die Instastadt für genau solche Nahrungsengpässe über ein Mikromechahuhn. Und zu unserem großen Glück konnte ich mit meinem überragenden Intellekt ermitteln, wohin unser wunderbares vorprogrammiertes Geflügel entschwunden ist.\n\nGeht nach Norden zur Versengten Rinne. Aber Vorsicht! Seine Platinen sind durchgebrannt und ich glaube, es ist gar nicht mehr so mikro!", progress = "Malt Euch nur die Lobeshymnen aus, die auf mich herniederregnen werden… äh… ich meine uns, wenn wir ihnen das größte Ei aller Zeiten bringen!", completion = "Heureka! Und wieder einmal hat mein Genie den Tag gerettet! Nehmt das, Bäm Megabombe!\n\nUnd jetzt wollen wir den Erfolg ernten!", rewards = "Beste. Armschienen. Überhaupt.Umhang aus MechahuhnfedernHühnerhäckslerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24745] = {title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", objective = "Bringt die vergilbte schöne Grußkarte zu Inspektor Snip Schnappbolz in Sturmwind.", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr denn da?\n\nUi, das ist groß! Riesig! So viele verrückte Details auf einem Haufen! Danke, Ihr habt uns wirklich sehr geholfen. Mit Euch kann man wirklich gut zusammenarbeiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24746] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][24747] = {title = "Sabotage!", objective = "Sabotiert eine zwergische Artilleriegranate und flüchtet dann aus Bael'dun bevor es explodiert.", description = "Diese zwergischen Artilleriegranaten haben einen eingebauten Luftdetonationszeitzünder. Das ist ja einfach! Ihr müsst nur eine der Artilleriegranaten in der Ladebucht sabotieren und sie dann hinauf ins Lager befördern. Bumm, Baby. BUMM!!\n\nIhr findet die Granaten in einer der beiden Ladebuchten hinter der Hauptwerkstatt auf dieser Ebene. Sie befindet sich direkt um die Ecke.\n\nSobald Ihr die Artilleriegranate manipuliert habt... Rennt! Rennt wie der Wind, <Name>! Dann meldet Euch bei Gann im Lager zurück. Ich bin direkt hinter Euch.", progress = nil, completion = "Bael'dun? Zerstört?\n\n&lt;Gann dreht seinen Kopf, um hinter sich zu spähen, wo dunkle Rauchwolken den Himmel verdunkeln, und zuckt schmerzerfüllt zusammen.&gt;\n\n&lt;Name&gt;, mein Freund. Ihr habt Taurajo und das Volk der &lt;Volk&gt; gerächt. Die Eindringlinge werden sich von dem Schlag nicht so schnell erholen. Danke.", rewards = "SpeerspitzenhelmSteinkeilschulternAuf Euch wartet eine dieser Belohnungen:\n\nLuftstoßamulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24748] = {title = "Das letzte Gefecht des Lichkönigs", objective = "Hochlord Darion Mograine in der Eiskronenzitadelle will, dass Ihr den Lichkönig tötet.", description = "Schattengram; eine neu geschmiedete Waffe, die bereits mit der Geschichte dieser Welt getränkt ist, wiedergeboren in eine beispiellose Bestimmung.\n\nMit dieser Waffe tragt Ihr eine feierliche Verantwortung, und die Zeit, dieser Verpflichtung nachzukommen, ist gekommen.\n\nNehmt diese mythische, legendäre Waffe und marschiert gegen den Feind. Rächt die zahllosen Helden, die in diesem gnadenlosen Krieg ihr Leben ließen. Bringt ihren geschundenen Seelen Frieden.\n\nStählt Euch, <Klasse>, und führt Schattengram, um den Sinn ihrer Erschaffung zu erfüllen.", progress = nil, completion = "Dann ist es also endlich vollbracht.\n\nMögen die Völker Azeroths unserer Taten hier ewig gedenken. Mögen die Opfer so vieler für immer in ihren Herzen brennen. Mögen sie im Angesicht großer Bedrohungen nie die Bereitschaft verlieren, ihr Leben für andere zu riskieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24749] = {title = "Erfüllt mit unheiliger Macht", objective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit unheiliger Macht erfüllt und Professor Seuchenmord tötet.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", description = "Bevor Eure Waffe ihre volle Kraft entfalten kann, muss sie mit den für sie charakteristischen Kräften ausgestattet werden. Die erste davon ist Unheiligkeit.\n\nIhr müsst jemanden namens Professor Seuchenmord ausfindig machen und töten, doch das ist noch nicht alles. Ihr müsst seine eigenen Mittel und Methoden gegen ihn verwenden.\n\nFindet einen Weg, seinen mutierten Schleim zu absorbieren. Benutzt die stinkende Substanz, um Eure Waffe mit unheiliger Macht zu erfüllen. Erst dann sollt Ihr Eure nächste Aufgabe von mir erhalten.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;!\n\nWir kommen dem Abschluss unserer Arbeit immer näher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24750] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Soratha auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Soratha im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Entschlossenheit. Feurige Augen. Ihr habt alle Voraussetzungen für einen echten &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24751] = {title = "Die Grundlagen: Ziele treffen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der arkanen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24752] = {title = "Die Künste eines Magiers", objective = "Ihr müsst Stufe 3 erreichen, um Frostnova zu erlernen. Wendet es zweimal bei einem Tikiziel an.", description = "Wenn Ihr Eure Stärke weiterentwickelt, werdet Ihr Euch neue Zauber überlegen und neue Wege, um Eure arkanen Talente anzuwenden.\n\nGeht nun, steigert Eure Fähigkeiten und kommt dann zurück und zeigt mir, was Ihr drauf habt.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24753] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24754] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = nil, completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", rewards = "Ihr bekommt:\n\nMagiewirkertunika der Dunkelspeere"}
MultiLanguageQuestData['de'][24755] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24756] = {title = "Erfüllt mit der Macht des Blutes", objective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit der Macht des Blutes erfüllt und Blutkönigin Lana'thel besiegt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", description = "Nun kann Eure Waffe mit der Macht des Blutes versehen werden.\n\nIhr müsst gegen Blutkönigin Lana'thel kämpfen und Euch ihrem Blutspiegel aussetzen. Durch diese Macht wird Schattenschneide das Blut des nächstgelegenen Lebewesens trinken. Das wäret dann Ihr, <Volk>.\n\nLasst, sobald die Klinge erwacht ist, den rasenden Blutdurst der Königin über Euch kommen, gebt Euch ihm hin und bereitet ihr einen schmachvollen Tod.\n\nMögen ihre Schreie in den Ohren des Lichkönigs schmerzen, während er auf sein Schicksal wartet!", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;.\n\nSchattengram ist fast in Reichweite.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24757] = {title = "Erfüllt mit der Macht des Frostes", objective = "Hochlord Darion Mograine hat Euch den Auftrag erteilt, Sindragosa zu töten, nachdem Ihr 4-mal ihren Atemattacken ausgesetzt wart, während Ihr Schattenschneide führt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", description = "Nun ist Schattenschneide bereit, mit der letzten Macht erfüllt werden.\n\nSindragosa, das persönliche Reittier des Feindes, muss fallen! Doch bevor Ihr sie tötet, müsst Ihr ihrer Frostatemattacke viermal widerstehen, ohne zu sterben.\n\nIst der Drache erst einmal beseitigt, steht nichts mehr zwischen Euch und dem Lichkönig.", progress = nil, completion = "Die Axt hat die Mächte aufgesogen, &lt;Volk&gt;, und die Schmiede ist bald bereit für die Erschaffung von Schattengram...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24758] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Nekali auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Nekali im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDafür seht Ihr aber ganz schön erfahren aus. Weise Augen. Vielleicht wird aus Euch noch ein echter &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24759] = {title = "Die Grundlagen: Dinge schlagen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der natürlichen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24760] = {title = "Die Kunst des Schamanen", objective = "Ihr müsst Stufe 3 erreichen, um Urtümlicher Schlag zu erlernen. Wendet diesen dann 3-mal bei einem Tikiziel an.", description = "Wenn Ihr stärker werdet, fangt Ihr an die Stimmen Eurer Vorfahren zu hören, die Euch ihre Geheimnisse beibringen.\n\nDas erste davon ist, die Macht der Elemente in Eure Waffe zu leiten. Dann könnt Ihr einen schnellen, brutalen Angriff auf Eure Gegner ausführen. Das sollte Euch leichtfallen und für Euch von großem Nutzen sein.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24761] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24762] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = nil, completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", rewards = "Ihr bekommt:\n\nSchamanenstab der Dunkelspeere"}
MultiLanguageQuestData['de'][24763] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24764] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Zen'Tabra auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Zen'Tabra im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Wildheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24765] = {title = "Die Grundlagen: Dinge schlagen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der druidischen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = "Kraft ist nicht alles, um einen Gegner zu besiegen, und ganz sicher ist sie nicht alles, um am Leben zu bleiben. Beim Kampf kommt es auf die Balance an. Alles hat seine Zeit und seinen Ort.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24766] = {title = "Die Kunst des Druiden", objective = "Ihr müsst Stufe 3 erreichen, um Mondfeuer zu erlernen. Probiert es an einem Tikiziel auf dem Übungsgelände der Dunkelspeere aus.", description = "Wenn Ihr stärker werdet, wird Eure Fähigkeit, die Kräfte der Natur anzurufen, auch besser. Wollt Ihr's sehen?\n\nSammelt mehr Erfahrungen und zeigt mir, was Ihr gelernt habt.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24767] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24768] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = nil, completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", rewards = "Ihr bekommt:\n\nDruidenstab der Dunkelspeere"}
MultiLanguageQuestData['de'][24769] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24770] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Legati auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Legati im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Gerissenheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24771] = {title = "Die Grundlagen: Ziele treffen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffen zu schwingen habt, mit denen Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Schwüngen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24772] = {title = "Die Künste eines Schurken", objective = "Ihr müsst Stufe 3 erreichen, um Ausweiden zu erlernen. Wendet es dann 3-mal bei einem Tikiziel an.", description = "Wenn Ihr mit Gegnern kämpft, lernt Ihr neue Tricks, mit denen Ihr noch besser werdet.\n\nEinen solltet Ihr schon bald lernen, damit Ihr ihre Schwächen aufdecken und vernichtende Comboangriffe ausführen könnt. Nachdem Ihr ein paar Schläge zur Schwächung Eurer Gegner ausgeführt habt, erledigt sie mit einem brutalen Ausweiden-Angriff.\n\nWenn Ihr es gelernt habt, probiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24773] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
