MultiLanguageQuestData['de'][24775] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24776] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Ortezza auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Ortezza im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Wildheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24777] = {title = "Die Grundlagen: Dinge schlagen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Angriffen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24778] = {title = "Die Kunst des Jägers", objective = "Ihr müsst Stufe 3 erreichen, um Zuverlässiger Schuss zu erlernen. Wendet den zuverlässigen Schuss 5-mal bei einem Tikiziel an.", description = "Wenn Ihr den Bogen raushabt, findet Ihr heraus, wie man neue Tricks macht.\n\nZuerst müsst Ihr lernen, zwischen Schüssen eine ruhige Hand zu behalten, sonst seid Ihr schnell erschöpft und richtet keinen wirklichen Schaden mehr an.\n\nLos, sammelt noch mehr Erfahrungen, bis Ihr es rausgefunden habt, und kommt dann wieder. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24779] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24780] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nJägerbogen der Dunkelspeere"}
MultiLanguageQuestData['de'][24781] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24782] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Tunari auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Tunari im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDafür seht Ihr aber sehr ausgeglichen aus. Ruhige Augen. Vielleicht wird aus Euch noch eine echte &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24783] = {title = "Die Grundlagen: Ziele treffen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der heiligen Künste versteht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24784] = {title = "Das richtige Wort", objective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Wendet es 5-mal bei Tiki-Trainingsattrappen an.", description = "Wenn Ihr da draußen in der Welt mehr Fähigkeiten bekommt, werdet Ihr neue Kräfte entdecken.\n\nProbiert es aus und versucht, stärker zu werden. Kommt dann wieder, wenn Ihr etwas Neues gelernt habt. Ihr könnt mir dann zeigen, was Ihr drauf habt.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24785] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24786] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = "Jeder Troll muss sich beweisen, bevor er das Trainingsgelände verlassen darf.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", rewards = "Ihr bekommt:\n\nWahrsagerroben der Dunkelspeere"}
MultiLanguageQuestData['de'][24787] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
