MultiLanguageQuestData['de'][24791] = {title = "Täglicher, zufälliger, normaler Dungeon (Nter)", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24792] = {title = "V-Mann", objective = "Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.", description = "Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.\n\nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.", progress = nil, completion = "Fantastisch! Hilfe kann ich wirklich gut gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24793] = {title = "V-Mann", objective = "Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.", description = "Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.\n\nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.", progress = nil, completion = "Fantastisch! Hilfe kann ich wirklich gut gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24794] = {title = "Sprecht mit Spraggel", objective = "Sprecht mit Spraggel Frock in Marschalls Wehr.", description = "Meine gute Freundin Spraggel ist schon eine ganze Weile wegen einer gewissen Sache beunruhigt. Ich würde ihr ja helfen, aber wie Ihr seht, habe ich es gerade schön bequem.\n\nKönntet Ihr nicht nachsehen, was sie möchte?", progress = nil, completion = "Was? Krakle schickt Euch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24795] = {title = "Ein Sieg für den Silberbund", objective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Trotz der Angeberei Königin Lana'thels habt Ihr Quel'Delar wiederhergestellt, <Name>. Wie lange haben wir davon geträumt, Quel'Delar wieder an uns zu nehmen.\n\nNicht nur der Silberbund, sondern alle Quel'dorei schulden Euch ihren Dank.\n\nDas Schwert scheint zu wissen, dass Ihr als <Klasse> nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Vielleicht kann der Argentumkreuzzug helfen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen des Silberbunds an Justiziarin Mariel Treuherz.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Knüppel der wütenden GerechtigkeitHammer der geläuterten FlammeLichtgeborene SpitzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24796] = {title = "Ein Sieg für den Silberbund", objective = "Bringt das wiederhergestellte Quel'Delar zu Vereesa Windläufer in der Violetten Zitadelle in Dalaran.", description = "Trotz der Angeberei Königin Lana'thels habt Ihr Quel'Delar wiederhergestellt, <Name>. Wie lange haben wir davon geträumt, Quel'Delar wieder an uns zu nehmen.\n\nNicht nur der Silberbund, sondern alle Quel'dorei schulden Euch ihren Dank.\n\nVereesa Windläufer, die Anführerin des Silberbunds, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, wo sie auf Euch wartet, <Name>.", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Das ist nichts weniger als eine sensationelle Leistung, &lt;Name&gt;. Der Tag, an dem Thalorien und Anasterian gefallen sind, derselbe Tag, an dem Quel'Delar verloren ging, war einer der schwärzesten Tage meines Lebens. Quel'Delar jetzt wiederhergestellt zu sehen... ich kann es nicht in Worte fassen.\n\nOhne Zweifel seid Ihr dazu ausersehen, der wahre Träger der Klinge zu sein. Quel'Delars Magie hat bereits damit begonnen, die Klinge an Eure Fähigkeiten und Stärken anzupassen.", rewards = "Quel'Delar, List der SchattenQuel'Delar, Linse der GedankenQuel'Delar, Macht der TreuenQuel'Delar, Wildheit der VerschmähtenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24797] = {title = "REUSE", objective = "Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][24798] = {title = "Ein Sieg für die Sonnenhäscher", objective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Sin'dorei wiederhergestellt!\n\nGanz Silbermond wird Euch als Helden feiern, <Name>.\n\nDas Schwert scheint zu wissen, dass Ihr als <Klasse> nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Noch hat sich kein würdiger Sin'dorei gemeldet. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Knüppel der wütenden GerechtigkeitHammer der geläuterten FlammeLichtgeborene SpitzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24799] = {title = "Ein Sieg für die Sonnenhäscher", objective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher wiederhergestellt!\n\nDie gesamte Horde wird Euch als Helden feiern, <Name>.\n\nDas Schwert scheint zu wissen, dass Ihr als <Klasse> nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Ich kann meine Enttäuschung nicht verbergen... ich hatte gehofft, es würde ein würdiger Sin'dorei sein. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Knüppel der wütenden GerechtigkeitHammer der geläuterten FlammeLichtgeborene SpitzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24800] = {title = "Ein Sieg für die Sonnenhäscher", objective = "Bringt das wiederhergestellte Quel'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Sin'dorei wiederhergestellt!\n\nGanz Silbermond wird Euch als Helden feiern, ebenso wie die gesamte Horde, <Name>.\n\nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, <Name>. Der Erzmagier will Euch persönlich gratulieren!", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Quel'Delar erhebt sich von neuem, so wie wir Sin'dorei uns aus der Asche der Niederlage und des Verrats erhoben haben. Das Herz und die Waffe von Thalorien Dämmersucher sind beide mit Euch, &lt;Name&gt;.\n\nIch sehe, dass die Klinge bereits begonnen hat, sich an Eure Stärken anzupassen, &lt;Name&gt;. Haltet Euer Haupt erhoben und Quel'Delar stets an Eurer Seite.", rewards = "Quel'Delar, List der SchattenQuel'Delar, Linse der GedankenQuel'Delar, Macht der TreuenQuel'Delar, Wildheit der VerschmähtenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24801] = {title = "Ein Sieg für die Sonnenhäscher", objective = "Bringt das wiederhergestellte Quel'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Horde wiederhergestellt!\n\nDies ist ein wahrer Segen für unsere Bemühungen gegen den Lichkönig.\n\nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, <Name>. Der Erzmagier will Euch persönlich gratulieren!", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Quel'Delar erhebt sich von neuem, so wie wir Sin'dorei uns aus der Asche der Niederlage und des Verrats erhoben haben. Und dennoch hat sich die Waffe Thalorien Dämmersuchers aus irgendeinem Grunde entschieden, einem Außenseiter zu dienen.\n\nBeruhigt Euch, &lt;Name&gt;. Ich gedenke nicht, Eure Errungenschaft zu schmälern, da Ihr etwas vollbracht habt, was keiner meiner Brüder vermocht hat, obschon ich nicht weiß, wie Ihr es angestellt habt. Ihr seid eindeutig dazu ausersehen, sein Träger zu sein... die Klinge hat bereits begonnen, sich an Eure Stärken anzupassen. Tragt Quel'Delar mit Stolz im Kampf gegen unsere Feinde.", rewards = "Quel'Delar, List der SchattenQuel'Delar, Linse der GedankenQuel'Delar, Macht der TreuenQuel'Delar, Wildheit der VerschmähtenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24802] = {title = "Der Zorn des Lichkönigs", objective = "Findet Fürstin Sylvanas Windläufer und flieht aus den Hallen der Reflexion.", description = "Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch zuerst müsst Ihr Sylvanas finden und vor dem Lichkönig fliehen, solange Zeit dazu ist.", progress = nil, completion = "Und wieder schlüpft mir die Rache durch die Finger. Es ist schwer zu glauben, wie viel stärker er geworden ist.\n\nEs war töricht von Euch, wegen mir herzukommen, aber dennoch ist es gut zu wissen, dass es immer noch einige Champions der Horde gibt, die keine nutzlosen Feiglinge sind. Die Informationen, die Uther uns gab, mögen wohl der Schlüssel dafür sein, Arthas endlich zu besiegen, aber es wird immer deutlicher, dass die Horde dies nicht allein wird bewerkstelligen können.\n\nGeht, &lt;Klasse&gt;. Ich gehe davon aus, dass Eure Fähigkeiten bald wieder gebraucht werden.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][24803] = {title = "Angelwettstreit der Kalu'ak", objective = "Wir Kalu'ak habe eine lange Tradition, unsere Angelfertigkeiten weiter zu polieren, indem wir sie jede Woche auf die Probe stellen.\n\nDie erste Person, die einen Schwarzspitzenhai fängt und zu mir bringt, wird fürstlich belohnt werden und fürderhin als größter Angler des Nordens bekannt sein... zumindest für ein paar Tage.\n\nDie Leibspeise des Schwarzspitzenhais ist der Pygmäenschiffshalter. Versucht, die Schwarzspitze überall dort zu angeln, wo Ihr normalerweise den Schiffshalter angeln würdet.", description = nil, progress = "Wir Kalu'ak habe eine lange Tradition, unsere Angelfertigkeiten weiter zu polieren, indem wir sie jede Woche auf die Probe stellen.\n\nDie erste Person, die einen Schwarzspitzenhai fängt und zu mir bringt, wird fürstlich belohnt werden und fürderhin als größter Angler des Nordens bekannt sein... zumindest für ein paar Tage.\n\nDie Leibspeise des Schwarzspitzenhais ist der Pygmäenschiffshalter. Versucht, die Schwarzspitze überall dort zu angeln, wo Ihr normalerweise den Schiffshalter angeln würdet.", completion = "Steht nicht nur so da rum! Gebt mir den Hai und ich erkläre Euch zum Sieger!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchreckenspiratenringStiefel der Bucht\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24804] = {title = "Ungewöhnliche Düfte", objective = "Meldet Euch bei Inspektor Snip Schnappbolz in Sturmwind.", description = "Irgendetwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.\n\nBegebt Euch nach Sturmwind, wenn Ihr uns helfen wollt. Inspektor Snip Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.", progress = nil, completion = "Hey, habt Ihr etwas Zeit mitgebracht? Ich könnte jemanden wie Euch gut gebrauchen.", rewards = nil}
MultiLanguageQuestData['de'][24805] = {title = "Ungewöhnliche Düfte", objective = "Meldet Euch bei Detektiv Snap Schnappbolz in Orgrimmar.", description = "Irgendetwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.\n\nBegebt Euch nach Orgrimmar, wenn Ihr uns helfen wollt. Detektiv Snap Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.", progress = nil, completion = "Hey, habt Ihr etwas Zeit mitgebracht? Ich könnte jemanden wie Euch gut gebrauchen.", rewards = nil}
MultiLanguageQuestData['de'][24806] = {title = "Mehr Glück beim nächsten Mal", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][24807] = {title = "Winnoa Kiefernwald", objective = "Sprecht mit Winnoa Kiefernwald an der Vendettakuppe im Südlichen Brachland.", description = "Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...\n\nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.", progress = nil, completion = "Ich konnte das, was sich abgespielt hat, von hier aus spüren, &lt;Klasse&gt;. Mir standen alle Haare zu Berge.\n\nIch bin überglücklich zu hören, dass es Euch gelungen ist, das Grauen zurückzudrängen und ich werde ganz bestimmt das Gebiet durchsuchen, um alle herumstreunenden, mutierten Kreaturen zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24812] = {title = "Keine Gnade mehr", objective = "Tötet 12 Gallschuppennaga.", description = "Die Naga haben unserem Volk schreckliches angetan. Die Zeit, ihnen Gnade zu zeigen, ist lang vorbei.\n\nGeht in die Höhle und tötet alle Naga, die Ihr dort findet. Jeder Naga, der heute stirbt, ist einer weniger, der uns später überraschen kann. Ich vertraue darauf, dass Ihr gründlich seid.", progress = nil, completion = "Gut gekämpft, junger &lt;Klasse&gt;.", rewards = "Gnadenlose HändeKalte FokusgamaschenGallschuppenpanzerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24813] = {title = "Territorialer Fetisch", objective = "Platziert 8 Territorialfetische auf Gallschuppenflaggen.", description = "Das ist kein halbherziger Gegenangriff. Wir haben vor, jede einzelne Naga zu töten und alles zu tun, damit sie nicht zurückkehren wollen.\n\nIch will, dass Ihr diese Fetische auf jede Gallschuppenflagge setzt, die Ihr in der Höhle findet. Das sollte eine klare Aussage darüber sein, was wir von ihrer Anwesenheit hier halten. Und mehr noch: Die Magie in diesen Fetischen wird alle Gallschuppen schwächen, die sich nähern, sodass sie es sich zweimal überlegen werden, ob sie auf unserer Insel bleiben wollen.", progress = nil, completion = "Das sollte sie aufhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24814] = {title = "Ein uralter Feind", objective = "Sprecht mit Vol'Jin in der Bucht der Gallschuppen und helft ihm, Zar'jira die Seehexe zu töten.", description = "Die Seehexe ist hier, oben auf genau dieser Insel. Wir haben lange auf diese Gelegenheit zur Rache gewartet, und Ihr werdet die Ehre haben, sie zu nutzen.\n\nTrefft Euch mit Vol'jin auf der Rampe im Nordosten. Lasst es ihn wissen, wenn Ihr bereit seid, Euch in die Schlacht zu stürzen.", progress = nil, completion = "Die Macht, die freigesetzt wurde, als die Seehexe starb, war immens. Ich kann diese Macht benutzen, um eine Vision von weit entfernten Orten heraufzubeschwören.\n\nSeht her, Neuling. Ich möchte, dass Ihr hier seid, wenn ich mit Thrall in Kontakt trete. Vielleicht gewinnt auch Ihr dadurch Einsicht.", rewards = "Armschienen der MeerhexeFußstapfen des gefallenen FreundesZunis FamilienerbstückIhr bekommt:\n\nBeutel der Seehexe"}
MultiLanguageQuestData['de'][24815] = {title = "Wählt Euren Weg", objective = "Um für die Sünden, die ich als Ritter des Lichkönigs begangen habe, Sühne zu leisten, habe ich mich der Herstellung von Ringen der Macht für unsere Brüder und Schwestern verschrieben, die sie in der Schlacht verwenden können.\n\nIhr habt Euch beim Kampf gegen die Geißel als wertvoller Verbündeter erwiesen, <Name>. Wenn Eure Hingabe weiter fortbesteht, kann ich den ursprünglichen Entwurf des Rings verbessern.\n\nWählt Euren Weg mit Bedacht. Ein Sinneswandel wird seinen Preis kosten.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der ZerstörungÄschernes Band der WeisheitÄschernes Band der RacheÄschernes Band des MutesÄschernes Band der Macht\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24816] = {title = "Wer ist jetzt an der Spitze der Nahrungskette?", objective = "Sammelt 5 Haiteile.", description = "Gut, gut, vielleicht war diese Sache mit den Eiern doch nicht ganz ausgereift. Wer hat Lust auf Haifleisch?\n\nEs gibt da nur ein kleines Problem. Nun, eigentlich eher ein großes Problem. Ein RICHTIG großes Problem: Den Hammer!\n\nAber natürlich habe ich eine brillante Idee. Schwimmt hinaus in die Meerenge namens Bedrängnis im Westen und besorgt uns ein paar Haiteile. Gebt Sie meiner Assistentin Greely. Ich bin viel zu wichtig, um mir die Hände an diesen Details schmutzig zu machen.", progress = "<Name>, seid nachsichtig mit Wurfhammer. Er ist ein Genie, aber er hat ein sehr schwaches Ego.", completion = "Die sind perfekt! Jetzt müssen wir nur noch die Haiteile und die übriggebliebenen Roboteile des Mechahuhns kombinieren, und schwuppdiwupp haben wir ein Tauchboot, mit dem Ihr uns diesen lästigen Hammer vom Leib schaffen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24817] = {title = "Ein Goblin im Haipelz", objective = "Aktiviert die Steuerung des dampfbetriebenen Mechahai-X und benutzt ihn dann, um den Hammer zu töten.", description = "Wir haben die Überreste des Mechahuhns mit diesen Haiteilen kombiniert und daraus das großartigste Kampftauchboot aller Zeiten gebaut: den dampfbetriebenen Mechahai-X!\n\nHobart und ich wollen, dass Ihr das Ruder übernehmt, <Name>. Geht nach Westen ins Wasser und aktiviert die Steuerung für den Mechahai-X. Ihr müsst den Hammer töten, wenn wir auch nur die geringste Chance haben wollen, die natürlichen Ressourcen der Meerenge im vollen Maße auszuschöpfen!", progress = "Diese abartig riesige Monstrosität von einem Hai ist noch nicht tot! Muss ich denn alles selber machen?", completion = "Ausgezeichnete Arbeit, mein Junge! Die Instastadt ist gerettet, und das Bilgewasserkartell wird wieder Profit machen, dank meines überragenden Intellekts und meines unglaublichen Ingenieurswissens!", rewards = "Übriggebliebene MechahuhnbeineDer HammerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24819] = {title = "Gesinnungswandel", objective = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", description = nil, progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", completion = "Möget Ihr finden, wonach Ihr suchet, Schwester.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der WeisheitÄschernes Band der RacheÄschernes Band des MutesÄschernes Band der Macht"}
MultiLanguageQuestData['de'][24820] = {title = "Gesinnungswandel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der WeisheitÄschernes Band der ZerstörungÄschernes Band des MutesÄschernes Band der Macht"}
MultiLanguageQuestData['de'][24821] = {title = "Gesinnungswandel", objective = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", description = nil, progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", completion = "Möget Ihr finden, wonach Ihr suchet, Bruder.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der WeisheitÄschernes Band der ZerstörungÄschernes Band der RacheÄschernes Band der Macht"}
MultiLanguageQuestData['de'][24822] = {title = "Gesinnungswandel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der ZerstörungÄschernes Band der RacheÄschernes Band des MutesÄschernes Band der Macht"}
MultiLanguageQuestData['de'][24823] = {title = "Weg der Zerstörung", objective = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der unvergleichlichen Zerstörung"}
MultiLanguageQuestData['de'][24824] = {title = "Die gestörte Erde", objective = "Besorgt 4 unruhige Erdfragmente von gestörten Erdelementaren.", description = "Wir sind hier, um die Narben der Lande zu überwachen und nach weiteren Zeichen der Instabilität Ausschau zu halten. Bisher haben wir noch keine gesehen, aber ein kataklysmisches Nachbeben könnte das Brachland noch weiter verheeren.\n\nIm Nordwesten, in der Nähe des Abgrunds, wüten völlig außer Kontrolle geratene Erdelementare. Um die Erde zu besänftigen, müssen diese hin und wieder vernichtet werden und ihre Essenz in einem Ritual zurückgegeben werden. Wenn Ihr uns helft, das zu tun, <Klasse>, werde ich Euch mit Freuden belohnen.", progress = "Die Elemente müssen sorgfältig in der Balance gehalten werden. Die Rückführung der Essenzen ist ein Schlüssel dafür. Ich hoffe, Ihr habt sie eingesammelt...", completion = "Ich danke Euch, mein Freund. Es ist wichtig, dass wir die Erde auf jede erdenkliche Weise besänftigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24825] = {title = "Weg der Weisheit", objective = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der großen Weisheit"}
MultiLanguageQuestData['de'][24826] = {title = "Weg der Vergeltung", objective = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der großen Rache"}
