MultiLanguageQuestData['de'][24828] = {title = "Weg der Zerstörung", objective = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der großen Zerstörung"}
MultiLanguageQuestData['de'][24829] = {title = "Weg der Zerstörung", objective = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, <Name>?", completion = "Ihr seid ein wahrer Champion unserer Sache, &lt;Name&gt;. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nDer Feind spricht Euren Namen nur flüsternd aus, denn er weiß, dass Ihr eine Macht seid, mit der er rechnen muss.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an.", rewards = "Ihr bekommt:\n\nÄschernes Band der endlosen Zerstörung"}
MultiLanguageQuestData['de'][24830] = {title = "Weg der Weisheit", objective = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der unvergleichlichen Weisheit"}
MultiLanguageQuestData['de'][24831] = {title = "Weg der Weisheit", objective = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, <Name>?", completion = "Ihr seid ein wahrer Champion unserer Sache, &lt;Name&gt;. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nIhr seid eine Bastion der Weisheit und unsere Verbündeten sprechen von Euch mit größter Verehrung. Viele von ihnen schulden Euch ihr Leben.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an.", rewards = "Ihr bekommt:\n\nÄschernes Band der endlosen Weisheit"}
MultiLanguageQuestData['de'][24832] = {title = "Weg der Vergeltung", objective = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der unvergleichlichen Rache"}
MultiLanguageQuestData['de'][24833] = {title = "Weg der Vergeltung", objective = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, <Name>?", completion = "Ihr seid ein wahrer Champion unserer Sache, &lt;Name&gt;. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nEs wird gemunkelt, dass die Lakaien der Geißel Euch mehr fürchten als den Lichkönig selber.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an.", rewards = "Ihr bekommt:\n\nÄschernes Band der endlosen Rache"}
MultiLanguageQuestData['de'][24834] = {title = "Weg des Mutes", objective = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, <Name>?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band des unvergleichlichen Mutes"}
MultiLanguageQuestData['de'][24835] = {title = "Weg des Mutes", objective = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, <Name>?", description = nil, progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, <Name>?", completion = "Ihr seid ein wahrer Champion unserer Sache, &lt;Name&gt;. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nIhr seid eine Quelle der Inspiration für unsere Verbündeten und Euer unerschütterlicher Mut lässt selbst die erfahrensten Generäle des Feindes innehalten.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an.", rewards = "Ihr bekommt:\n\nÄschernes Band des endlosen Mutes"}
