MultiLanguageQuestData['de'][24847] = {title = "Gesinnungswandel", objective = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", description = nil, progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", completion = "Möget Ihr finden, wonach Ihr suchet, Bruder.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der endlosen ZerstörungÄschernes Band der endlosen RacheÄschernes Band der endlosen WeisheitÄschernes Band der endlosen Macht"}
MultiLanguageQuestData['de'][24848] = {title = "Feuerwerk bei der Güldenen Rose", objective = "Redet mit Marion Sutton in der Güldenen Rose im Handelsdistrikt von Sturmwind.", description = "Kind, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgend einer chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.\n\nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Brandzeichen. Flenni Rostrakete.\n\nIch habe einen Tipp von einer vertrauenswürdigen Quelle erhalten, dass er sich hier in Sturmwind aufhält und es sich in der Güldenen Rose gut gehen lässt. Er soll sogar eine Dame bei sich haben, mit Namen Marion Sutton. Macht Euch auf zur Güldenen Rose und findet heraus, was sie weiß.", progress = nil, completion = "Ihr... Ihr seid nicht Flenni. Hat er Euch geschickt? Er ist so spät dran, ich hatte schon die Hoffnung aufgegeben...\n\n&lt;Tränen schimmern in ihren Augen, als sie begreift, dass Ihr nicht dort seid, um eine Nachricht von Flenni zu überbringen.&gt;\n\nDas passt gar nicht zu meinem Flenni, aber was für eine andere Möglichkeit gibt es?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24849] = {title = "Auf den Fersen", objective = "Sucht Flenni Rostrakete im Zählhaus von Sturmwind, im Auktionshaus und beim Barbier von Sturmwind.", description = "Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, <Name>. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.\n\nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?\n\nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!", progress = nil, completion = "Er hat also nur davon gesprochen, dass er die Stadt mit all seinem Geld verlassen will? Dann hat er mich wirklich sitzen lassen, oder?\n\nOh, was war ich bescheuert, mich in ihn zu verlieben, aber wie hätte ich es verhindern können? Er war so unwiderstehlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24850] = {title = "Flennis Flamme", objective = "Redet mit Roka bei Gotris Reiseausstattung in der Gasse in Orgrimmar.", description = "<Junge/Mädel>, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgend einer chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.\n\nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Zeichen des Herstellers. Flenni Rostrakete.\n\nIch habe gehört, dass er es sich hier in Orgrimmar gut gehen lässt. Und es kommt noch besser, er soll sogar eine Freundin haben... eine Orc-Dame mit Namen Roka. Sie will sich mit ihm bei Gotris Reiseausstattung in der Gasse treffen, bevor sie ihre Flucht antreten.", progress = nil, completion = "Ihr seid nicht Flenni. Er hätte schon vor einer Stunde hier sein sollen! Was habt Ihr mit ihm angestellt?\n\n&lt;Roka scheint sich zu beruhigen, als Ihr ihr erklärt, dass Ihr selber nach Flenni sucht. Dann schimmern Tränen in ihren Augen.&gt;\n\nDas sieht meinem süßen Flenni gar nicht ähnlich. Meint Ihr, ihm ist etwas zugestoßen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24851] = {title = "Auf den Fersen", objective = "Sucht Flenni Rostrakete in der Bank von Orgrimmar im Tal der Stärke, dem Auktionshaus und dem Barbier von Orgrimmar.", description = "Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, <Name>. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.\n\nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?\n\nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!", progress = "Habt Ihr ihn gefunden?", completion = "Er hat also nur davon gesprochen, dass er die Stadt mit all seinem Geld verlassen will? Dann hat er mich wirklich sitzen lassen, oder?\n\nIch kann nicht glauben, dass ich auf einen so schrecklichen Goblin reingefallen bin! Aber er war so unwiderstehlich, als wir uns das erste Mal sahen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24852] = {title = "Unser Stamm in Gefangenschaft", objective = "Öffnet 4 Stacheleberkäfige.", description = "Trotz ihrer geringen Größe sind die Borstennacken uns zahlenmäßig überlegen. Ein Angriff des Rudels kann selbst den größten Tauren überwältigen. Viele unserer Initianden haben zu den Waffen gegriffen, um ihre Heimat zu verteidigen - einige haben ihr Leben dafür gegeben und ein paar befinden sich in Gefangenschaft.\n\nIch bitte Euch, findet ihre Käfige und befreit sie. Die Schlacht sollte die Stacheleber ablenken.", progress = nil, completion = "Dank Euch sind unsere Krieger wieder frei und können ihre Heimat verteidigen.", rewards = "HochwolkenhandschuheStacheldurchbohrte StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24854] = {title = "Findet Sturmklaue", objective = "Meldet Euch bei Garl Sturmklaue am Eingang zum Krater von Un'Goro.", description = "Zen'Aliri lernt die Kunst der Druiden, <Volk>. Eines Tages ist Zen'Aliri hoffentlich auch ein Druide der Klaue und kann als Sturmkrähe über diesen Krater schweben.\n\nAber sein Meister sagt, dass Zen'Aliri vorerst noch hier warten muss. Also wartet Zen'Aliri.\n\nEr kennt einen anderen Druiden, der vielleicht Eure Hilfe brauchen könnte. Sein Name ist Garl Sturmklaue. Er hält sich irgendwo im Osten auf und untersucht Reagenzien. Vielleicht könntet Ihr mit ihm reden?", progress = nil, completion = "Es war klug von Zen'Aliri, Euch zu mir zu schicken. Ich bin mit meinen Studien in einer Sackgasse angelangt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24855] = {title = "Anormale Flora", objective = "Tötet 11 Blutblüten. Eine beliebige Kombination aus ausgewachsenen Blutblüten ist zulässig.", description = "Schaut nur, wie merkwürdig die Pflanzenwelt auf die Blutblüten in den Aufwühlenden Gärten im Norden reagiert. Es ranken sich noch mehr Blumen und Schlingpflanzen um die Bäume als sonst. Große, sporenreiche Blüten erheben sich dort, wo sonst keine waren.\n\nDas Land spricht zu uns, <Volk>. Die Blutblüten zerstören das Gleichgewicht.\n\nAls letzte Aufgabe möchte ich Euch bitten, die ausgewachsenen umherwandernden Blutblüten aufzusuchen und ihre Zahl zurechtzustutzen.", progress = nil, completion = "Euch umgibt der Geruch der Blutblütenpollen, &lt;Klasse&gt;. Das ist gut.\n\nIhr habt Euch Eure Belohnung verdient.", rewards = "Konfisziertes Gewehr des WilderersBlutblütenumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24856] = {title = "Drohende Invasion!", objective = "Sprecht mit Megs Schredderschreck am westlichen Eingang zu den Ruinen von Vashj'elan auf den Verlorenen Inseln.", description = "Eure Arbeit hier ist vorerst getan, aber das heißt noch lange nicht, dass Ihr jetzt die Hände in den Schoß legen könnt.\n\nErinnert Ihr Euch noch an Megs Schredderschreck, unsere ehemalige Marketingbeauftragte? Sie hat jetzt ein paar andere Aufgaben jenseits der Hügel im Osten übernommen, direkt hinter dem Raptorenbuckel. Wenn Ihr dem Weg nach Osten aus der Stadt heraus und an der Gabelung nach Süden folgt, könnt Ihr sie nicht verpassen.\n\nOffensichtlich gibt es dort ein paar Probleme mit den Schlangenwesen in den Ruinen an der Küste. Schaut doch einmal nach, ob Ihr etwas dagegen unternehmen könnt, ja?", progress = nil, completion = "Boss, wir haben ein Problem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24857] = {title = "Angriff auf Camp Narache", objective = "Bringt die Angriffspläne der Borstennacken zu Häuptling Falkenwind in Camp Narache.", description = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Ihr die Pläne für eine ausgeweitete Belagerung von Camp Narache entdeckt habt, die von dem Kriegshäuptling der Borstennacken entworfen wurden.\n\nHäuptling Falkenwind kann mit dieser Information sicher einiges anfangen!", progress = "Ihr seht besorgt aus, <Name>. Welche Neuigkeiten bringt Ihr mir?", completion = "Das ist in der Tat ziemlich alarmierend! Aber mit dieser Information können wir unseren Brüdern im Dorf der Bluthufe Bescheid geben, dass sie uns helfen den Angriff abzuwenden. Ihr habt das Leben vieler &lt;Volk&gt; gerettet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nDickrindenrundschild"}
MultiLanguageQuestData['de'][24858] = {title = "Vertreter des Bilgewasserkartells", objective = "Zerstört 10 Nagabanner und ersetzt sie durch Banner des Bilgewasserkartells.", description = "Sieht aus, als bereiten sich die Naga in den Ruinen da unten auf einen Angriff auf Instastadt vor. Zumindest habe ich hier viele tote Späher als Beweis.\n\nIch weiß nicht, wie es Euch geht, aber ich will es nicht darauf ankommen lassen. Wir müssen ihnen zuvorkommen!\n\nKönntet Ihr den Grundstein für unsere neuen Besitztümer an der Küste legen, indem Ihr ihre Banner durch unsere eigenen ersetzt? Das ist erstklassiges Bauland dort unten!", progress = nil, completion = "Ich wünschte, ich hätte den Ausdruck auf ihren schuppigen Gesichtern sehen können, als Ihr ihre Banner in die Luft gejagt und durch unsere ersetzt habt!\n\nObwohl, wenn ich es mir genau überlege, möchte ich ihnen nicht nah genug sein, um ihre Schlangenzungen zu sehen.", rewards = "SchlangenschuppengürtelBannerumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24859] = {title = "Nagahaut", objective = "Sammelt 5 intakte Nagahäute.", description = "Hinter vorgehaltener Hand spricht man von einem Material, das so fein ist, sich so zart anfühlt, dass Goblins mit einem exquisiten Geschmack einen Haufen Knete dafür ausgeben.\n\nIch spreche natürlich von Nagahaut!\n\n<Brett schaut sich um, um sicherzugehen, dass ihn keiner belauscht.>\n\nIch weiß, dass Ihr dort hinunter geht und gegen diese Schlangen kämpfen müsst. He, sie brauchen ihre Haut ja sowieso nicht mehr. Sie sind dann ja schließlich tot!", progress = "Nun? Wie viele habt Ihr für mich? Ich finde, wenn wir den Gewinn 95 zu 5 aufteilen, ist das mehr als gerecht.", completion = "Ich sage Euch, wir werden stinkreich! Natürlich vorausgesetzt, wir kommen von dieser Insel runter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24861] = {title = "Riten zum Ende, Riten zum Beginn", objective = "Benutzt die Bestattungsgabe an Großmutter Falkenwinds Bestattungsstelle.", description = "Unser Camp ist nun sicher und die Stacheleber sind dank Euch vertrieben. Ihr könnt Euch meines Danks sicher sein für das, was Ihr für meine Mutter, meinen Sohn und mein Volk getan habt.\n\nEs ist an der Zeit, Großmutter Falkenwind Ruhe zu schenken. Legt die letzte Opfergabe zu ihren Füßen, <Name>, und wir werden Abschied nehmen.", progress = "Seid nicht schüchtern, <Name>. Es ist mir eine Ehre, dass Ihr die letzte Gabe legt.", completion = "Es gibt überall Gleichgewicht. Nun, da Großmutter Falkenwind ihre letzte Reise antritt, werdet Ihr Euch auf Eure erste begeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24862] = {title = "Spießrutenlauf", objective = "Tötet 8 Späher des Jägerhügels.", description = "Schaut Euch um, <Klasse>. Wir hatten kein Glück dabei, die Horde von den versteckten Pfaden, die einen Ausblick auf dieses Tal gewähren, zu verdrängen. Sie tauchen aus dem Nichts auf, um unsere Nachschubkarawanen zu überfallen und dann verschwinden sie in die Hügel!\n\nIhr müsst Euch der Gefahr aussetzen, zur Ehrenwacht zu laufen und sie darüber zu unterrichten, dass die Straßen immer noch nicht sicher sind. Sprecht mit Mattingly, dem Nachschuboffizier am Tor.\n\nUnd tötet unterwegs ein paar von diesen Ungeheuern!", progress = nil, completion = "Sie überfallen auch die Straßen ins Steinkrallengebirge? Hier bekommt man aber auch keine Ruhe. Wo kommen die überhaupt her?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24863] = {title = "Die Belagerung durchbrechen", objective = "Sammelt 10 für das Steinkrallengebirge bestimmte Vorratskisten in den Ruinen westlich der Ehrenwacht auf.", description = "Hordespäher, die sich in den Ruinen vor uns verbergen, haben meinen Nachschubzug aus dem Hinterhalt überfallen. Nur zwei meiner Leibwachen haben das überlebt. Und ich? Ich hatte mal Haare!\n\nDie Vorräte, die ich abliefern sollte, liegen verstreut in den Ruinen vor uns. Sammelt sie ein und bringt sie zu Janice Mattingly in der Ehrenwacht. Wenn wir sie schon nicht ins Steinkrallengebirge bringen können, dann sorgen wir wenigstens dafür, dass sie nicht der Horde in die Hände fallen...", progress = "Wie sieht es da draußen aus, <Name>?", completion = "Was... unsere Vorräte? Die waren fürs Steinkrallengebirge bestimmt.\n\nEgal, so, wie das hier läuft, brauchen wir sie ohnehin dringender hier. Die Ehrenwacht ist von der Küste abgeschnitten worden, &lt;Name&gt;. Kommandant Singleton ist mit seinem Latein am Ende.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24864] = {title = "Unwiderstehliches Poolpony", objective = "Benutzt das unwiderstehliche Poolpony, um 12 Nagajunge anzulocken.", description = "Ich habe einen Plan und Ihr seid <der Einzige, der/die Einzige> die; verrückt genug ist, ihn in die Tat umzusetzen!\n\nIch möchte, dass Ihr das Poolpony zum Laichbecken von Vashj'elan bringt und aufblast. Schwimmt dann auf dem Pony zu ihren Jungen. Ich wette, Ihr könnt die Jungen dazu bringen, Euch zu folgen.\n\nBringt sie hierher. Dann machen wir mit der nächsten Phase unseres Plans weiter.", progress = "Das sind nicht genug Junge.", completion = "Oh, die sind so süß! Ich wünschte, wir könnten sie in kleine Plüschtiere verwandeln und für eine Gazillion Moneten verkaufen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24865] = {title = "Ist das noch gut?", objective = "Bringt die Kiste mit Lebensmitteln zu Williden Marschall in Marschalls Wehr zurück.", description = "Ihr findet etwas, das wie eine Nahrungsmittelkiste aussieht, die beim Verlassen dieses Lagers vergessen wurde. Auf der Seite der Kiste erkennt Ihr einen Stempel mit den Worten \"EIGENTUM VON MARSCHALLS EXPEDITION\".\n\nVielleicht findet Ihr ja jemanden, der das hier brauchen könnte.", progress = "Was habt Ihr da?", completion = "Oh… Das ist aber ganz schön altes Essen. He, Hol'anyee, schau dir das an! Dieser &lt;Volk&gt; hat uns unsere zurückgelassenen Rationen gebracht!\n\nNein, nicht von Marschalls Zuflucht… aus dem alten Basislager!\n\n\n\nIch bin mir nicht sicher, ob ich da hineinschauen möchte. Ich schätze, ich werde einfach Nolen die Kiste geben. Er weiß sicher, was damit zu tun ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24866] = {title = "Ein verlassenes Forschungslager", objective = "Bringt die Forscherausrüstung zu Hol'anyee Marschall in Marschalls Wehr zurück.", description = "Ihr findet etwas, das wie ein Stück einer Forscherausrüstung aussieht, das beim Verlassen dieses Lagers vergessen wurde. Auf der Seite des Geräts sind die Worte \"EIGENTUM VON MARSCHALLS EXPEDIZION\" eingeritzt.\n\nVielleicht findet Ihr ja jemanden, der das hier brauchen könnte.", progress = "Ja, <Name>?", completion = "Da brat mir einer… Das ist Sappalots altes tragbares Dinomometer! Wo habt Ihr das gefunden?\n\nIch bin überrascht, dass es nach all den Jahren überhaupt noch funktioniert. Ich werde es sofort zu Sappalot bringen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24868] = {title = "Gebt auf, oder…!", objective = "Vernichtet den Anführer der Naga in den Ruinen von Vashj'elan.", description = "<Name>, Ihr und Ass müsst diese Nagajungen dort hinunter führen und sie als Druckmittel benutzen, um ihren Anführer zur Kapitulation zu zwingen!\n\nAss weiß, wo er auf der Südseite der Ruinen entlanggehen muss. Folgt ihm einfach.", progress = "Was ist los?", completion = "Ein Gesichtsloser aus den Tiefen? Was soll das sein? Das klingt NICHT nach einem Naga!\n\nNun, Ihr habt es getötet, was immer es auch war. Wir haben andere Fische zu fangen…", rewards = "JungtiergreiferJungtierstupserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24869] = {title = "Entprogrammieren", objective = "Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.", description = "Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.\n\nUnser Mann, Darnavan, ist jetzt einer von ihnen.\n\nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.", progress = "Darnavan hat nun so lange beim Kult gelebt, dass es schwer zu sagen ist, wie er reagieren wird. Er ist ein austrainierter Krieger, also seid wachsam!", completion = "Danke Euch, &lt;Name&gt;!\n\nIch schulde Euch großen Dank dafür, dass Ihr einen Freund gerettet habt, den ich schon für verloren in den Klauen des Kults gehalten habe. Und der Argentumkreuzzug schuldet Euch Dank für die unschätzbaren Informationen, die Darnavan durch seine Zeit als Anhänger des Kults in den Hallen der Zitadelle gesammelt hat.\n\nBitte, nehmt dies als Zeichen unserer Anerkennnung, und möge Euch das Licht stärken, wenn Ihr eine Schneise durch diesen schrecklichen Ort pflügt.", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24870] = {title = "Sicherung des Bollwerks", objective = "Erledigt den verrottenden Frostriesen.", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", progress = "Ist der Riese tot?", completion = "Der Riese ist tot? Für die Horde!\n\nDer weg nach vorne wird bald freigeräumt sein. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24871] = {title = "Sicherung des Bollwerks", objective = "Erledigt den verrottenden Frostriesen.", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", progress = nil, completion = "Der Riese ist tot? Gepriesen sei das Licht!\n\nDer Weg voraus und hinauf ist nun frei. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24872] = {title = "Frieden für eine geschundene Seele", objective = "Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.", description = "Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.\n\nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.", progress = "Was haltet Ihr da in Händen, Sterblicher?", completion = "&lt;Kalecgos seufzt&gt;\n\nSo viel Leid, so viel sinnlose Zerstörung. Dies waren keine guten Zeiten für meine Brüder und Schwestern. Aber dank Eurer Anstrengungen, tapfere Abenteurer, kann diese befleckte, aber immer noch edle Seele endlich Frieden finden.\n\nRuhet nun, Sindragosa. Ihr seid zuhause...", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24873] = {title = "Wandelnder Wirt", objective = "Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.", description = "Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.\n\nEs gibt nur einen Haken... eine nützliche Probe müsste aus zwei aktiven Stämmen bestehen, die sich in einem lebenden Wirt verbinden. Sollte Euch das... Missgeschick... widerfahren, solch ein Wirt zu werden, dann kommt bitte sofort hier her, sodass wir Euch für unsere Studien abernten können.", progress = "Seuchenmords Seuche ist eine der gefährlichsten Waffen der Geißel gegen uns.", completion = "Endlich können wir lebende Exemplare studieren. Ihr habt heute dabei geholfen, unzählige Leben zu retten, &lt;Name&gt;!\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit für Eure Tat.", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24874] = {title = "Erhöhter Blutdruck", objective = "Rettet den Spitzel Minchar, bevor er hingerichtet wird.", description = "Diese Geißel-Blutsauger - San'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.", progress = nil, completion = "Mann, ich dachte schon, es ist aus mit mir! Ich habe Gerüchte über ein Wiederbelebungsritual in diesen Hallen gehört und da wollte ich mal nachsehen, aber einer von diesen verdammten Vampiren hat mich entdeckt. Sie haben mich hier aufgehängt und meine Lebensenergie angezapft, in der Hoffnung, dass ich auspacke und unsere Angriffspläne verrate. Als ob ich überhaupt wüsste, was Tirion plant!\n\nBitte, nehmt diese Kriegsbeute als kleines Zeichen der Dankbarkeit, dass Ihr mein Leben gerettet habt.", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24875] = {title = "Entprogrammieren", objective = "Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.", description = "Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.\n\nUnser Mann, Darnavan, ist jetzt einer von ihnen.\n\nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.", progress = nil, completion = "Danke Euch, &lt;Name&gt;!\n\nIch schulde Euch großen Dank dafür, dass Ihr einen Freund gerettet habt, den ich schon für verloren in den Klauen des Kults gehalten habe. Und der Argentumkreuzzug schuldet Euch Dank für die unschätzbaren Informationen, die Darnavan durch seine Zeit als Anhänger des Kults in den Hallen der Zitadelle gesammelt hat.\n\nBitte, nehmt dies als Zeichen unserer Anerkennnung, und möge Euch das Licht stärken, wenn Ihr eine Schneise durch diesen schrecklichen Ort pflügt.", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24876] = {title = "Sicherung des Bollwerks", objective = "Erledigt den verrottenden Frostriesen.", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", progress = "Ist der Riese tot?", completion = "Der Riese ist tot? Gepriesen sei das Licht!\n\nDer Weg voraus und hinauf ist nun frei. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24877] = {title = "Sicherung des Bollwerks", objective = "Erledigt den verrottenden Frostriesen.", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", progress = "Ist der Riese tot?", completion = "Der Riese ist tot? Für die Horde!\n\nDer Weg voraus und hinauf ist nun frei. Nehmt einige dieser Beutestücke als Zeichen unserer Dankbarkeit, und sobald der Frostthron dem Erdboden gleichgemacht ist, stoßen wir gemeinsam an!", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24878] = {title = "Wandelnder Wirt", objective = "Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.", description = "Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.\n\nSolltet Ihr zufällig über ein lebendiges Exemplar stolpern, so bringt es bitte sofort hierher, damit wir es analysieren können.", progress = nil, completion = "Endlich können wir lebende Exemplare studieren Ihr habt heute dabei geholfen, unzählige Leben zu retten, &lt;Name&gt;!\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit für Eure Tat.", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
MultiLanguageQuestData['de'][24879] = {title = "Erhöhter Blutdruck", objective = "Rettet den Spitzel Minchar, bevor er hingerichtet wird.", description = "Diese Geißel-Blutsauger - San'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.", progress = nil, completion = "Mann, ich dachte schon, es ist aus mit mir! Ich habe Gerüchte über ein Wiederbelebungsritual in diesen Hallen gehört und da wollte ich mal nachsehen, aber einer von diesen verdammten Vampiren hat mich entdeckt. Sie haben mich hier aufgehängt und meine Lebensenergie angezapft, in der Hoffnung, dass ich auspacke und unsere Angriffspläne verrate. Als ob ich überhaupt wüsste, was Tirion plant!\n\nBitte, nehmt diese Kriegsbeute als kleines Zeichen der Dankbarkeit, dass Ihr mein Leben gerettet habt.", rewards = "Ihr bekommt:\n\nSack mit frostigen Schätzen"}
