MultiLanguageQuestData['de'][24896] = {title = "Zufälliger, klassischer Dungeon 65-70 (Nter)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRanzen voller hilfreicher Waren"}
MultiLanguageQuestData['de'][24897] = {title = "Zurück in die Stadt", objective = "Sprecht mit Sassy Hartzang in Instastadt auf den Verlorenen Inseln.", description = "Wir lagen falsch. Es waren nicht die Naga, die sich auf einen Angriff vorbereiteten… Es war der benachbarte Stamm der Oomlot!\n\n<Name>, Ihr müsst zurück nach Instastadt. Die Pygmäen greifen bereits an!\n\nHier, nehmt dies hier. Wir haben ihn von einem Pygmäen gekauft, der sagte, er gehörte einst einem großen Anführer ihres Volkes. Jemandem namens \"Großer dunkler Helm\".\n\nEr sollte sie gut genug täuschen, damit sie Euch nicht angreifen.", progress = nil, completion = "&lt;Name&gt;? Wir sind gerettet!\n\nWem mache ich was vor. Wir werden alle sterben!!!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24901] = {title = "Instastadt: Unter Angriff", objective = "Verwendet einen B.C. Eliminator, um 30 Krieger von Oomlot zu töten.", description = "<Name>, Ihr müsst uns beschützen!\n\nIch habe bereits veranlasst, dass diese Eierköpfe die Stadt mit den Kanonen verteidigen, aber es scheint unendlich viele von diesen Oomlotkriegern zu geben!\n\nSchwingt Euch hinter einen der B.C. Eliminatoren und vernichtet die Pygmäen, die unsere Stadt bedrohen!", progress = "Das reicht noch nicht, Schätzchen. Könnt Ihr nicht ein paar mehr erledigen?", completion = "Gut, das sollte fürs Erste reichen, aber sie haben einige Stadtbewohner gefangen genommen.\n\nWir müssen auf ihrem Grund und Boden gegen sie kämpfen!", rewards = "Mini B.C. EliminatorDeckelfragment der InstastadtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24902] = {title = "Jagd nach Sylvanas", objective = "Folgt Tobias Dunstmantel auf der Jagd nach Sylvanas.", description = "Dann ist es also wahr? Gilneas hat seinen liebsten Sohn verloren.\n\nWir werden trauern, sobald all dies vorbei ist, aber keinen Tag früher.\n\nWir gönnen uns den Luxus der Trauer nicht, solange der Feind noch gilnearische Luft atmet.\n\nDie Männer meines Vaters sind bereit, zuzuschlagen, solange wir die Fährte der Bansheekönigin noch verfolgen können. Sagt einfach Bescheid, wenn Ihr bereit seid. Liam muss so schnell wie möglich gerächt werden.", progress = "Habt Ihr sie gefunden, <Name>?", completion = "Die Seuche? Etwas so Hinterhältiges, dass nicht einmal die Orcs mit ihrem Einsatz einverstanden sind? Wir müssen König Graumähne davon berichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24903] = {title = "Rache oder Überleben", objective = "Sprecht mit König Genn Graumähne auf dem Graumähnenhof in Gilneas.", description = "Sagt Graumähne Bescheid, dass wir Sylvanas unsere Fährtenleser hinterhergeschickt haben und berichtet ihm von der Seuche.\n\nNun muss er entscheiden: Starten wir einen großangelegten Angriff auf die Verlassenen oder versuchen wir, unsere Überlebenden zu evakuieren?", progress = nil, completion = "Ihr stellt mich vor die schwierigste Entscheidung meines Lebens, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24904] = {title = "Schlacht um Gilneas", objective = "Erringt den Sieg in der Schlacht um Gilneas", description = "Die Zeit ist gekommen, <Name>. Wir haben jeden einzelnen Gilneer zusammengetrommelt und ihm eine Waffe in die Hand gedrückt.\n\nEs ist Zeit, dass wir uns dem Feind direkt stellen. Zeit, Sylvanas und ihren verlassenen Hunden ein für alle Mal eine Lektion zu erteilen.\n\nLiam führt den Angriff von diesem Tor aus an. König Graumähne und mein Vater überwachen die Angriffe in den anderen Vierteln.\n\nAuch Ihr spielt bei der Sache eine wichtige Rolle. Nehmt dieses Rapier. Verwendet es, um unsere Männer und Frauen in der Schlacht anzufeuern. Sprecht mit Krennan Aranas, um an der Schlacht um Gilneas teilzunehmen.", progress = nil, completion = "Wir haben die Verlassenen zurückgedrängt. Wir haben die Kontrolle über drei der vier Viertel.\n\nAber zu welchem Preis…", rewards = "FührungsspitzeUmhang des FanfarenstoßesVolksansturmGilnearischer SchildStreitkolben des BlutprinzenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24905] = {title = "Sich für einen Gefallen revanchieren", objective = "Findet Megs Schredderschreck beim Truppenlager der Dünenbrecher.", description = "Wisst Ihr, als Ihr eben unterwegs wart, kam Megs vorbei. Ich hab sie schon seit Monaten nicht mehr gesehen, aber sie hat sich nicht wirklich für mich interessiert und wollte mir nur sagen, dass sie mehr Arbeit übrig hat.\n\nSie sagte, sie würde sich im Truppenlager der Dünenbrecher niederlassen wollen, und irgendwas mit Ogern. Da Ihr hier ja jetzt fertig seid, könnt Ihr ja mal schauen, ob Ihr ihr helfen könnt. Einen Goblin wie sie würde ich nicht warten lassen.", progress = nil, completion = "Diesmal habe ich etwas Tolles für Euch, &lt;Name&gt;. Wir werden diese Oger in die Horde einführen... und unter uns arbeiten lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24906] = {title = "Wiederverwertung an der Küste", objective = "Sammelt 7 Dampfdruckvorräte.", description = "Wir müssen die Waren auf diesem Markt so schnell wie MÖGLICH in den Umlauf bringen, wenn wir wettbewerbsfähig sein wollen. Ich habe schon einen Einstiegspunkt gefunden.\n\nGadgetzan ist von Piraten eingenommen worden, aber viele der Güter, die von den Schiffen geworfen wurden, sind noch intakt. Sie wurden nur weggespült. Viele davon werden südlich der Stadt angespült.\n\nGeht dorthin und beginnt, zu sammeln, was noch verwertbar ist. Da unten schwimmt der Profit sprichwörtlich kistenweise herum.", progress = "Mal sehen, was Ihr so gefunden habt.", completion = "Hmm, vieles ist verwendbar. Gutes Zeug habt Ihr gefunden. Ich hab natürlich auch schon Käufer, die Schlange stehen.\n\nHier habt Ihr einen Vorschuss für die restliche Arbeit, die Ihr noch für mich und das Bilgewasserkartell verrichten werdet... Partner!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24907] = {title = "Pfützenstampfer", objective = "Tötet 8 Gezeitenschreiter.", description = "Also, unsere Lage ist wie folgt: wenn wir die Präsenz des Bilgewasserkartells in Gadgetzan fördern möchten, müssen wir anfangen, den Bewohnern Dienstleistungen anzubieten.\n\nDie neue Küste ist ideal für das Geschäftsleben, aber das Meer hat auch einige Ungeheuer mitgebracht. Sie sind groß, übel und machen den Immobilienmarkt kaputt.\n\nGeht zu den seichten Wassern südlich der Stadt und tötet so viele, wie Ihr könnt. Ihr bekommt natürlich eine Gewinnbeteiligungn an den Geschäften, die ich in der Zwischenzeit abschließe.", progress = nil, completion = "Die Immobilienpreise steigen, seit Ihr weggegangen seid. Die Aussicht aufs Meer ohne salzige, knorrige Riesen, die durch die Pfützen stampfen gefällt den meisten einfach besser.\n\nHier ist Euer Anteil, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24910] = {title = "Raketenrettung", objective = "Bringt Lebensraketen zu 5 Überlebenden des Dampfdruckkartells und benutzt Bomben, um 40 Blockierer der Südmeerfreibeuter zu töten.", description = "Nun gut, <Name>. Wir haben uns mit Kleinkram über Wasser gehalten, aber jetzt ist es an der Zeit, richtig loszulegen.\n\nBei den Ruinen von Dampfdruckpier sind immer noch hilflose Goblins, die auf Rettung warten. Jeder einzelne von ihnen ist ein potentieller Kunde. Sie schießen auf alle Boote, die den Hafen verlassen - also schlage ich vor, wir fliegen!\n\nAußerhalb der Stadt, in der Nähe der Docks ist ein Heißluftballon, den wir nehmen können. Geht schon mal vor, ich komme dann nach.", progress = nil, completion = "Ist es nicht toll, wenn man etwas Nettes macht und dabei auch noch enorme Finanzspritzen für die Zukunft sichern kann? Da wärmt es mir vor Freude mein kleines Goblinherz.\n\nIhr habt tolle Arbeit geleistet. Bald wird Gadgetzan uns gehören. Hier ist ein kleines Zeichen meiner Anerkennung.", rewards = "Nasmiras SuppenrührerGeborgener DampfdruckhelmMisslungener Prototyp einer LebensraketeAuf Euch wartet eine dieser Belohnungen:\n\nBlindgängerbombe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24911] = {title = "Das tropische Paradies ruft", objective = "Meldet Euch bei Williden Marschall in Marschalls Wehr im Krater von Un'Goro.", description = "He, Ihr scheint mir ein anspruchsvoller Abenteurer zu sein. Seid Ihr auf der Suche nach etwas ganz Neuem? Etwas Exotischem? Etwas… Profitträchtigem?\n\nNun, dann schüttelt den Sand aus Euren Schuhen, denn ich habe ein Angebot für Euch. Williden Marschall ist auf der Suche nach fähigen Söldnern wie Euch. Er hat sein Lager in Marschalls Wehr direkt südöstlich des Vulkans inmitten des blühenden Kraters von Un'Goro errichtet.\n\nAber bedenkt, dass nicht jeder für das Paradies geschaffen ist, <Volk>. Es liegt an Euch. Eure tropische Oase wartet!", progress = nil, completion = "He, Hol'anyee, schau dir mal die Aufmachung von dem hier an!\n\n&lt;Williden dreht sich zu Euch.&gt;\n\nÄhem. Unser Rekrutierer schickt Euch? Gut. Fangen wir mal mit der Wahrheit an: Un'Goro ist nicht das perfekte Elysium, das Euch wahrscheinlich versprochen wurde. Aber das habt Ihr sicher auf dem Weg hierher schon bemerkt.\n\nWollen wir an die Arbeit gehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24912] = {title = "Mit Macht erfüllen", objective = "<Hochlord Darion Mograine spricht Euch zielstrebig an.>\n\nSchattenschneide ist bereit, ihre letzte Gabe der Macht zu erhalten.\n\nDie Zeit ist gekommen, das Schmieden von Schattengram zu wagen!", description = nil, progress = "<Hochlord Darion Mograine spricht Euch zielstrebig an.>\n\nSchattenschneide ist bereit, ihre letzte Gabe der Macht zu erhalten.\n\nDie Zeit ist gekommen, das Schmieden von Schattengram zu wagen!", completion = "Tretet zur Seite, &lt;Klasse&gt;, und wappnet Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nShadowmourne Quest Accept"}
MultiLanguageQuestData['de'][24913] = {title = "Gedenkt des Lichtes", objective = "Helft Anchorit Avuun, sich von Magtoor zu verabschieden.", description = "Magtoor wird von Sekunde zu Sekunde schwächer, <Name>. Meine Arznei ist vorbereitet... sie muss einfach funktionieren. Sie muss!\n\nIhr habt so viel für uns beide getan. Es wäre mir eine Ehre, wenn Ihr in diesen Momenten bei Magtoor bleiben könntet - vielleicht sind es seine letzten.", progress = nil, completion = "Ich bin tiefbewegt, &lt;Name&gt;. Prophet Velen befand sich in streng bewachter Abgeschiedenheit. Er wagte es nicht, seine Energie auf irgendetwas anderes als die letzte Konfrontation zu verschwenden, die er vorhersagte.\n\nUnd doch ist er höchstpersönlich hergekommen, um eine sterbende Seele zu trösten.\n\nIch muss auch Euch danken, für die Hilfe bei meinem letzten Versuch, meinem Freund Trost zu geben. Meine Forschungen werden weitergehen... und ich hoffe, dass Magtoor mich weiterhin dabei behütet.", rewards = "Ihr bekommt:\n\nUmarmung des Lichts"}
MultiLanguageQuestData['de'][24914] = {title = "Persönliches Eigentum", objective = "Bringt die versiegelte Truhe zu Hochlord Darion Mograine in die Eiskronenzitadelle.\n\nBereitgestellter Gegenstand: \n", description = "Ihr könnt auf dieser Truhe keine Scharniere oder Öffnungen finden. Würde man das Poltern von Gegenständen in ihrem Inneren nicht hören, könnte man leicht meinen, dass sie aus massivem Metall bestünde.\n\nWenn irgendjemand wissen sollte, wie man sie öffnet, dann wird das Hochlord Mograine sein.", progress = nil, completion = "&lt;Nachdem er die komplexen Runenmuster auf jeder Seite der Truhe mit den Fingern nachverfolgt hat, erscheinen die Umrisse eines Deckels und ein Klicken schallt durch die Halle.&gt;\n\nBitte sehr, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nUnversiegelte Truhe"}
MultiLanguageQuestData['de'][24915] = {title = "Zusammenkunft mit Mograine", objective = "Was haltet Ihr da in Händen, <Klasse>?\n\nEs ruft nach mir und weckt Gefühle in mir, von denen ich dachte, dass sie schon lange gestorben seien.", description = nil, progress = "Was haltet Ihr da in Händen, <Klasse>?\n\nEs ruft nach mir und weckt Gefühle in mir, von denen ich dachte, dass sie schon lange gestorben seien.", completion = "Unmöglich...\n\nVater, bist du das?!\n\nIhr habt mir einen großen Dienst erwiesen, Held. Dafür gebe ich Euch das Zaumzeug meines treuen Rosses. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen.", rewards = "Ihr bekommt:\n\nZügel des scharlachroten Todesstreitrosses"}
MultiLanguageQuestData['de'][24916] = {title = "Jainas Medaillon", objective = "Ja, <Klasse>? Wie kann ich behilflich sein?", description = nil, progress = "Ja, <Klasse>? Wie kann ich behilflich sein?", completion = "Was... wie habt Ihr es geschafft, in seinen Besitz zu kommen!?\n\nIhr habt mir einen großen Dienst erwiesen, Held. Ich könnte es nicht übers Herz bringen, dieses Medaillon zu behalten, aber ich werde eine Verzauberung darauf legen, die Euch von Nutzen sein könnte. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen.", rewards = "Ihr bekommt:\n\nJainas Medaillon"}
MultiLanguageQuestData['de'][24917] = {title = "Muradins Klagelied", objective = "Was hast du da, <Volk>?", description = nil, progress = "Was hast du da, <Volk>?", completion = "Jawohl. Ich kenne diese Klinge... und ich werde mich bis ans Ende meiner Tage an sie erinnern - an jenen Zeitpunkt, der für immer verloren sein wird.\n\nIhr habt mir einen großen Dienst erwiesen, Held. Ich möchte Euch etwas von den Frosterben zum Geschenk machen. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen.", rewards = "Ihr bekommt:\n\nMuradins Gunst"}
MultiLanguageQuestData['de'][24918] = {title = "Sylvanas' Rache", objective = "Was ist, <Volk>?", description = nil, progress = "Was ist, <Volk>?", completion = "&lt;Sylvanas ist einen Moment lang in Gedanken versunken. Schließlich richtet sie ihren Blick auf Euch.&gt;\n\nIhr habt mir einen großen Dienst erwiesen, Held. Ich gebe Euch den Segen der Bansheekönigin. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen.", rewards = "Ihr bekommt:\n\nSylvanas' Spieluhr"}
MultiLanguageQuestData['de'][24919] = {title = "Die Erlösung des Lichtbringers", objective = "Wie kann ich behilflich sein, <Volk>?", description = nil, progress = "Wie kann ich behilflich sein, <Volk>?", completion = "&lt;Uther starrt einen Moment lang sprachlos auf die Medaille.&gt;\n\nArthas' Medaille.\n\nIch kann mich gut an den Tag erinnern, als ich sie ihm überreichte...\n\nIhr habt mir einen großen Dienst erwiesen, Held. Nun kann meine Seele in Frieden ruhen. Hier, ich biete Euch etwas, das im Laufe der Zeit vergessen wurde - eine Erinnerung. Verfahrt damit wie Euch beliebt, doch vergesst nicht jene, die bei dieser kolossalen Heldentat an Eurer Seite standen.", rewards = "Ihr bekommt:\n\nWappenrock des Lichtbringers"}
MultiLanguageQuestData['de'][24920] = {title = "Das Unvermeidliche verlangsamen", objective = "Benutzt die gefangene Reitfledermaus, um 6 Katapulte der Verlassenen und 40 einfallende Verlassene zu vernichten.", description = "So gerne ich schnelle und brutale Rache üben würde… muss ich erst die Erinnerung an meinen Sohn ehren. Für ihn stand das Wohl seines Volkes immer an erster Stelle.\n\nDer Totengräberpass verläuft unterirdisch unter dem Nordtorfluss hindurch. Ihr müsst verhindern, dass die Seuche sich ausbreitet, wenn wir unsere Männer, Frauen und Kinder zu Aderics Ruhestätte evakuieren.\n\nWir haben eine der gefürchteten Bombenfledermäuse der Verlassenen gefangen. Ich möchte, dass Ihr diese Höllenbestie so gut wie möglich fliegt und denen, die die Seuche zu unserem Volk bringen wollen, die Hölle heiß macht. Beeilt Euch!", progress = "Habt Ihr es erledigt, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Fast alle sind heil auf die andere Seite gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24921] = {title = "Meldung für Aubrey", objective = "Meldet Euch bei Admiral Aubrey in der Feste Nordwacht.", description = "Ihr da! Seid Ihr gerade mit dem Schiff angekommen? Willkommen in Kalimdor, einem Land, das sich alle Mühe geben wird, Euch zu töten oder bei dem Versuch zu sterben.\n\nIn der Burg gibt es Ärger - aber ich bin sicher, das habt Ihr auf Euren Weg hinein bereits bemerkt. Admiral Aubrey braucht alle Mann an Deck, wenn wir das hier überstehen wollen. Betrachtet Euch als eingezogen, <Klasse>!\n\nFolgt der Straße den Hügel hinauf und Ihr findet Aubrey oben auf dem Turm.", progress = nil, completion = "Hm? Bei welcher Einheit seid Ihr, &lt;Klasse&gt;?\n\nEgal, wir brauchen jeden Mann. Meine Flotte ist zerschlagen und sie sind in die Feste eingebrochen. Seid Ihr bewaffnet? Das reicht mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24922] = {title = "Zufälliger, klassischer, heroischer Dungeon (Erster)", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24923] = {title = "Zufälliger, heroischer Burning Crusade-Dungeon (Nter)", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24924] = {title = "Oomlot", objective = "Sprecht mit Izzy bei Oomlot auf den Verlorenen Inseln.", description = "Die Pygmäen haben die meisten unserer Leute in ihr Dorf verschleppt. Wer weiß, was für böse Dinge sie im Schilde führen?\n\n<Name>, Ihr müsst dorthin gehen und die Gefangenen befreien, bevor die Pygmäen ihre Voodoozauber auf sie wirken können!\n\nIzzy befindet sich bereits in der Nähe von Oomlot im Südosten. Sie kann Euch sagen, was dort vor sich geht.\n\nEuer Pygmäenhelm scheint ganz schön mitgenommen zu sein, aber er sollte lange genug halten, damit Ihr heil dort ankommt.\n\nHoffe ich zumindest.", progress = nil, completion = "&lt;Name&gt;? Was macht Ihr denn hier? Und warum habt Ihr diesen komischen Pygmäenhelm auf? Der fällt ja gleich auseinander!\n\nIch bin froh, dass man Euch hierher geschickt hat. Ich hatte schon befürchtet, dass sie diesen Deppen Wurfhammer und seine speichelleckende Assistentin schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24925] = {title = "Befreit die Gefangenen", objective = "Befreit 5 gefangene Goblins.", description = "Sie halten ein paar unserer Leute dort gefangen. Ich weiß, dass sie merkwürdige Rituale mit ihnen durchführen. Es scheint fast, als würden sie ihnen die Lebenskraft aussaugen!\n\nIhr müsst in das Dorf gehen und die Gefangenen befreien, bevor es zu spät ist!", progress = nil, completion = "Tolle Arbeit! Aber das ist nicht einmal die Hälfte der Gefangenen, die sie aus der Stadt entführt haben.\n\nVerflixt! Sie müssen die restlichen Gefangenen zu ihren anderen Dörfern oben im Vulkan gebracht haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24926] = {title = "Dienst für A-Me 01", objective = "Bringt A-Me 01s Fingerfestplatte zurück zu Karna Wirrbart am Mooshügel im Krater von Un'Goro.", description = "Grüße. Ich Einheit A-Me 01. Ihr… <Volk>?\n\nA-Mes Mission zur Untersuchung der einheimischen Gorillas erfolgreich. A-Me Daten gesammelt, die Karna brauchen.\n\nA-Me 01 aber noch nicht zurückkehren. A-Me hat jetzt neue Familie. A-Me hier bei Gorillas bleiben.\n\n<A-Me 01 nimmt ein kleines Gerät von ihrer Hand ab und gibt es Euch.>\n\nIhr Daten zurückbringen zu Karna. Ihr ihr sagen, was passiert sein.", progress = "W… was ist das?", completion = "Sie hat sich entschlossen, zu bleiben? Faszinierend… Ich muss mir diese Daten ansehen und herausfinden, warum.\n\nNochmals danke, &lt;Name&gt;. Ich weiß Eure Hilfe wirklich zu schätzen.", rewards = "Karnas PonchoWirrbarts DenkkappeKünstliche GorillabrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24927] = {title = "Die Truhe des toten Mannes", objective = "Tötet 15 Seeräuber der Südmeerfreibeuter jeglicher Art.", description = "Seht, Schätzchen, Ihr solltet eigentlich sehen können, was hier los ist. Auf der einen Seite sind die Seeräuber, auf der anderen die Goblins, und die Goblins bekämpfen die Piraten. Ein paar arme, kleine Gnome versuchen es auch.\n\nIch werde es euch noch einfacher machen: wir müssen viele Piraten töten. Macht das, ja? Wir wollen ja nicht, dass die Gnome mehr erwischen als wir.", progress = nil, completion = "Ich freue mich, mitteilen zu können, dass unser Markenbewusstsein in dieser Gegend enorm gestiegen ist, seid Ihr die meisten getötet habt, die uns nicht hier haben wollten.", rewards = "SüdmeerkapuzeDellots GamaschenGebrandmarkte HandschuheGesäuberte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24928] = {title = "Niederbrennen!", objective = "Brennt die nordwestliche Hütte, die südöstliche Hütte und die nordöstliche Hütte nieder.", description = "Ich habe eine gründliche Untersuchung des Immobilienmarkts angestellt und leider sind die Marktwerte hier viel zu niedrig, um für uns nützlich zu sein. Wir werden renovieren müssen.\n\nZum Glück für Euch weiß ich ein paar Sachen über Brandstiftung. Ich hoffe, Ihr auch! Ihr werdet diese unglaublich sicheren Flaschen mit hochentzündlichem Rum auf die heruntergerannten, schmutzigen Hütten dort drüben werfen.\n\nVersucht, in der entgegengesetzten Windrichtung zu stehen.", progress = nil, completion = "Wunderbare Arbeit. Habt Ihr schon einmal mit dem Gedanken gespielt, mit der Brandstiftung Euren Lebensunterhalt zu verdienen? Ich kenne in der Branche ein paar Leute, da geht schon einiges.\n\nNa gut, darüber können wir uns später unterhalten. Es gibt noch mehr zu tun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24929] = {title = "Hinterlasst eine Botschaft", objective = "Tötet Yngwie.", description = "Der Anführer der Oomlot, Yngwie, ist zu mächtig, als dass wir ihn am Leben lassen könnten. Er brüllt Unsinn vom erhöhten Westteil des Dorfes herab, jenseits der Seilbrücke.\n\nGeht zu ihm und tötet ihn, bevor er den Rest des Dorfes auf uns hetzt.\n\nEin Kinderspiel!", progress = nil, completion = "Gute Arbeit, Kumpel! Ich hoffe, er war kein allzu harter Brocken.", rewards = "Yngwies WestePygmäenmantelStab aus OomlotIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24930] = {title = "Wenn Ihr schon dabei seid", objective = "Tötet 5 Blutfangworgen.", description = "Wenn König Graumähne möchte, dass Ihr Euer Leben riskiert, um einen bekannten Verräter zu retten, soll mir das Recht sein.\n\nKönntet Ihr mir einen Gefallen tun? Wenn Ihr schon da draußen seid, tut etwas Sinnvolles und tötet diese verdammten Flohsäcke.", progress = nil, completion = "Wenn ich nicht selbst gesehen hätte, dass Ihr ein paar von diesen verlausten Kötern getötet habt, hätte ich geschworen, dass Ihr Eure Aufgabe nicht erledigt habt.\n\nWir scheinen ihre Zahl nicht einmal annähernd dezimiert zu haben.", rewards = "Armsteads ArmschienenHändlerbrustschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24931] = {title = "Starrermarke", objective = "Sammelt 5 Okularkristalle von Glashautstarrern.", description = "Ihr wollt Hyänen jagen, hm? Falls es Euch nicht stört, hätte ich selbst ein Angebot zu machen. Ich brauche die Augen von Glashautstarrern, die sich nördlich von hier befinden. Ihre Augen enthalten wundervolle Kristalle, die für... Sammler sehr viel wert sind.\n\nIhr habt vielleicht gehört, dass sie auch von manchen traurigen Gestalten zur Förderung der paramentalen Fähigkeiten genutzt werden, aber ich kann Euch versichern, dass mein Interesse rein akademischer Natur ist!\n\nBringt mir eine gute Ladung der Augen und ich werde Euch gut bezahlen. Zumindest besser als die Goblingeizkragen!", progress = "Ah, habt Ihr die Kristalle?", completion = "Aah, perfekt! Genau, was ich gebraucht habe... voller mächtiger, fokussierender Energien...\n\nÄhem! Ich meine natürlich sie sind ideal für meine Sammlung! Narain Pfauentraum braucht keine künstlichen Verbesserungen jeglicher Art!\n\nHier, nehmt Eure Bezahlung und geht nun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24932] = {title = "Verlust verhindern", objective = "Tötet 15 Silithiden der Hazzali jeglicher Art in der Klaffenden Schlucht.", description = "Seit einer Woche starre ich in diese eklige Grube in der Hoffnung, eine Idee zu bekommen, wie man diese gefährlichen, angriffslustigen Gliederfüßler gewinnbringend ausnutzen kann. Jetzt fällt mir nichts mehr ein und Hunger habe ich auch.\n\nDiese Dinger sind gefährlich und es ist an der Zeit, sie auszumerzen. Geht in die Grube und tötet das Ungeziefer.", progress = nil, completion = "Das dauert zu lange. Es muss eine schnellere Methode geben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24933] = {title = "Hühnchen der Wüste", objective = "Sammelt 6 Stücke Hyänenfleisch.", description = "Ich habe eine Idee, aber wir brauchen zuerst einen Köder.\n\nLetztens habe ich eine tollwütige Eiterpfotenhyäne gesehen, die nahe bei der Schlucht herumwanderte; plötzlich kam ein Silithid aus dem Nichts und hat sie fast in einem Haps verschlungen! War kein schöner Anblick.\n\nWir brauchen also ganz offensichtlich Hyänenfleisch. Bringt mir frisches Hyänenfleisch. Nördlich des Lagers solltet Ihr genügend Hyänen dafür finden.", progress = "Das ist frisches Fleisch, ja? Um etwas, dass in der Sonne ausgetrocknet wurde, werden sie sich nicht reißen.", completion = "Man, das Zeug sieht lecker aus. Ich hätte fast Lust, für mich selber etwas davon zu braten.\n\nNein! Wir müssen uns darauf konzentrieren, hier wegzukommen.\n\nAber vielleicht doch ein kleines Stückchen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24934] = {title = "Werft Enternde von Bord!", objective = "Sprecht mit Admiral Aubrey, um zur Schwarzborn zu fliegen. Tötet dort 6 Seebären von Donnerschrei.", description = "<Name>, das Meer ist unsere Lebenslinie und gerade jetzt läuft der überwiegende Teil meiner Flotte mit voller Kraft zurück nach Theramore für Reparaturen oder rostet auf dem Grund dieser Bucht. Nur die Schwarzborn hält sich noch über Wasser, um unseren Hafen zu verteidigen.\n\nAber sie hat gerade Signale gesendet, dass sie geentert wird!\n\nSprecht mit mir, wenn Ihr bereit seid. Ich werde dafür sorgen, dass einer unserer Seegreife Euch auf Deck absetzt. Tötet die Seebären von Donnerschrei, die es wagen, mein kostbares Schiff anzugreifen und meldet Euch bei Kapitän Fischer für weitere Befehle.", progress = nil, completion = "Ihr würdet einen verdammt guten Seemann abgeben, &lt;Name&gt;.\n\nWir würden mit den anderen den Boden aufwischen. Aber wie es aussieht, zieht die Flotte der Horde sich aus dem Kampf zurück - vielleicht wollen sie noch mehr Truppen an Land absetzen?\n\nAdmiral Aubrey wird wissen, was zu tun ist. Sprecht mit mir, wenn Ihr bereit seid, zurückzufliegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24937] = {title = "Oomlot ist erledigt", objective = "Sprecht mit Sassy Hartzang in Instastadt auf den Verlorenen Inseln.", description = "<Name>, Ihr müsst zurück nach Instastadt und die Einwohner vor den Goblinzombies in der Caldera des Vulkans warnen!", progress = nil, completion = "Sie haben ein paar von uns in Zombies verwandelt? Erzählt mir etwas Neues…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24938] = {title = "Die Kanonen von Nordwacht", objective = "Sprecht mit Kanonier Hecksler.", description = "Kapitän Fischer hat uns von unten Signale gesendet. Die Flotte der Horde setzt Landmannschaften ab? Wir können nicht zulassen, dass sie uns vom Strand aus in die Flanke fallen.\n\nIch habe bereits zwei meiner besten Schützen dort hinuntergeschickt, um den Landeplatz zu verteidigen. Sprecht unten am Strand mit Kanonier Hecksler.\n\nIhr müsst Euch den Weg durch den Hof freikämpfen, um dorthin zu gelangen. Seht, ob Ihr auf dem Weg nach unten den anderen dabei helfen könnt, die Feste zu sichern.", progress = nil, completion = "Aubrey hat Euch geschickt? Gut! Ich nehme an, Ihr wisst, wie Ihr mit einer Kanone umzugehen habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24939] = {title = "Bringt die Kanonen zum Einsatz", objective = "Benutzt ein Küstengeschütz der Nordwacht um 10 Ruderboote von Donnerschrei zu zerstören.", description = "Wir haben das Material, aber uns fehlen die Leute, <Name>. Bemannt eins der Geschütze hier am Strand und schießt die ankommenden Boote ab!", progress = nil, completion = "Har har! Der Strand gehört uns!\n\nVielleicht schaffen wir es ja doch, uns auf diesem miesen Staubball von einem Kontinent zu behaupten.", rewards = "Gürtel des KarronadenschützenArmschienen der NordwachtAuf Euch wartet eine dieser Belohnungen:\n\nHeckslers Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24940] = {title = "Auf den Vulkan", objective = "Sprecht mit Trainer Blutgrätsch auf dem Verlorenen Gipfel auf den Verlorenen Inseln.", description = "Ein Haufen unserer Leute ist auf dem Weg zur Spitze des Vulkans, um eine Rettungsaktion und Gegenoffensive zu starten. Dort auf dem Verlorenen Gipfel braut sich etwas Schreckliches zusammen.\n\nSie warten auf Euch, bevor sie etwas gegen die Pygmäen unternehmen. Wie Ihr seht ist es diesen fiesen kleinen Wesen gelungen, viele von uns in Zombies zu verwandeln.\n\nRettet uns, <Name>!", progress = nil, completion = "Mein Spitzenspieler ist eingetroffen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24941] = {title = "Langridges Munition", objective = "Sammelt 15 Stücke Langridges Munition.", description = "<Klasse>! Dem Licht sei Dank - sie haben uns fast bis zu den Docks zurückgeschlagen. Der Hof ist überrannt!\n\nWir haben keine Splittergranaten mehr und die Orcs bereiten sich auf einen Sturmangriff den Hügel hinauf vor. Wir müssen irgendwie Streumunition improvisieren - und das schnell.\n\nBeeilt Euch, rennt in den kaputten Turm hier und greift Euch allen scharfen und spitzen Metallschrott dessen Ihr habhaft werden könnt. Messer, Gabeln, Nägel - alles! Ladet die Kanone, sobald ihr einen Arm voll davon habt.", progress = "Paxton hat bereits eine Ladung in die Kanone gestopft. Jetzt brauchen wir nur noch die improvisierte Munition.", completion = "Die Horde versammelt sich am Fuß des Hügels. Atemlos stopft Ihr die Trümmer, die Ihr aufgesammelt habt, in die Öffnung der Kanone, tretet zurück, haltet Euch ein Ohr zu und zerrt an der Zündschnur...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24942] = {title = "Zombies gegen Superträgerraketenstiefel", objective = "Benutzt die Superträgerraketenstiefel, um 50 Goblinzombies zu töten.", description = "Diese Zombies, die an uns vorbeigekommen sind, sind nichts im Vergleich zu den Massen, die hinter dem Pass auf uns warten. Wenn wir uns nicht bald um sie kümmern, werden die Hexendoktoren der Pygmäen sie auf die Stadt hetzen. Selbst unsere Kanonen können gegen diese Mengen nichts ausrichten.\n\nIch konnte ein paar Schredderstiefel mit hierher bringen. Greely hat sie überarbeitet und jetzt sind es Superträgerraketenstiefel!\n\nVerwendet die Stiefel, um die Zombies in den Dörfern von Oostan im Osten in Flammen zu setzen.", progress = "Da warten noch ein paar Goblinzombies auf Euch, <Name>. Immer die Ohren steif halten, Superstar!", completion = "Ihr habt es geschafft! Jetzt müssen wir uns nie mehr um Zombies sorgen. Legen wir eine Schweigeminute für unsere stinkenden Verflossenen ein.\n\nOK, fertig.", rewards = "STRS-Prototyp 1STRS-Prototyp 3STRS-Prototyp 2Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24943] = {title = "Den Hof zurückerobern", objective = "Tötet 10 Grunzer von Donnerschrei.", description = "So säubert man einen Hügel. Die Leichen wurden von Messern und Gabeln aufgespießt!\n\nDer Donnerschreiklan hat die Mauern durchbrochen, aber wir können diesen Kampf immer noch gewinnen. Geht zum Fuße des Hügels und helft unseren Männern, den Hof unten zu halten...", progress = nil, completion = "Großartige Arbeit! Wir haben sie in die Knie gezwungen, vielleicht lange genug, um unsere Verteidigungstruppen an Land zu bringen.\n\nVorausgesetzt, wir finden einen Weg, ihre Artillerie auszuschalten...", rewards = "Paxtons GürtelBeschlagnahmter DonnerschreiumhangZugeständnisse des HofsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24944] = {title = "Zurück in den Kampf", objective = "Benutzt die kräutergetränkten Bandagen bei 6 verwundeten Verteidigern.", description = "Dieser Kampf ist noch nicht vorüber, <Klasse>. Noch lange nicht.\n\nEinige der Soldaten im Hof haben immer noch einen Lebenshauch in ihren Lungen. Wir können sie retten! Ich habe diese Lumpen in eine Kräuterarznei getaucht, auf die wir uns in Gilneas immer verlassen haben. Der Geruch ist furchtbar, aber dieser Umschlag kann sogar Tote erwecken.\n\nBenutzt diese Bandagen bei verwundeten Verteidigern unten im Hof und wir werden sehen, ob wir sie wieder kampftauglich machen können.", progress = "Ich hoffe, Ihr habt genug Bandagen? Mein Nachschub an diesen Kräutern wurde abgeschnitten, als diese Ungeheuer mein geliebtes Gilneas geplündert haben.", completion = "Ein gleichmäßiger Strom laufender Verwundeter ist den Hügel hinaufgekommen, um sich bei mir zu melden, &lt;Name&gt;. Ich nehme an, das war Euer Werk? Gut gemacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24945] = {title = "Drei kleine Pygmäen", objective = "Tötet Gaahl, Malmo und Teloch.", description = "Ich finde es ja toll, dass wir all diese Zombies töten und so, obwohl sie unsere Freunde und Verwandten sind. Aber meint Ihr nicht, dass wir uns auch um diese Pygmäen kümmern sollten, die sie erschaffen?\n\nIn den drei Dörfern von Oostan, Oostan-Nord, Oostan-Sor und Oostan-Ost, gibt es drei Hexendoktoren: Gaahl, Malmo und Teloch.\n\nKönntet Ihr Euch um sie kümmern? Ich habe keine Lust, ein Zombie zu werden!", progress = nil, completion = "Puh, da fällt mir aber ein Stein vom Herzen. Endlich muss ich mich nicht mehr darum sorgen, dass neue Zombies hinter meinem Gehirn her sind!", rewards = "HexendoktorgamaschenArmschienen aus OysteinIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24946] = {title = "Abrockpulver", objective = "Sammelt 5 Handvoll Abrockpulver.", description = "Eines muss man diesen Pygmäen ja lassen… Sie wissen, wie man Partys feiert! Aber sie sind nicht besonders klug. Ich glaube, ich kenne jetzt die Quelle ihrer Abrockkräfte: Abrockpulver!\n\nUnd wie sich herausstellt verwandelt dieses Zeug sie nicht nur in Weltklasse-Rocker, sondern ist auch noch hochgradig explosiv. Wir müssen es einfach haben!\n\nAlso, wenn Ihr in Oostan im Osten seid, sammelt so viel von dem Zeug, wie Ihr tragen könnt. Vertraut mir, Ihr werdet es bald schon brauchen!", progress = "Hmm, mal sehen, wie viel Ihr schon habt.", completion = "Das wird reichen. Es ist sogar mehr, als wir brauchen. Ich habe eine geniale Idee für eine Waffe, in die wir diese Stiefel verwandeln können, sobald Ihr sie Hobart gebracht habt.\n\nGebt mir das Pulver, damit ich die Superträgerraketenstiefel damit aufladen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24947] = {title = "Momentum", objective = "Trefft Megs Schredderschreck in der Mast- und Schotbucht.", description = "Wir können uns noch nicht auf unseren Lorbeeren ausruhen, Schätzchen. Wir müssen das Momentum beibehalten! Die Leute sprechen schon über uns.\n\nLeider sprechen sie aber auch über diese hohle Gnomin Kelsey, die wohl auch Arbeiten wie wir verrichtet. Wenn wir sie aus dieser Stadt, die rechtsmäßig den Goblins zusteht, vertreiben wollen, so müssen wir es richtig tun.\n\nWir werden uns dem Seeräuberproblem widmen, in dem sich Gadgetzan befindet, und dem Problem ein Ende bereiten, ein für alle Mal. Begebt Euch zur Mast- und Schotbucht; ich werde Euch dort treffen.", progress = nil, completion = "Gut, dass Ihr hier seid! Ich werde Eure Hilfe benötigen, wenn wir diesen Gnomen zuvorkommen wollen.", rewards = nil}
MultiLanguageQuestData['de'][24948] = {title = "Die Belagerung aufheben", objective = "Benutzt Paxtons Fackel um 3 Katapulte von Donnerschrei und 1 Klingenwerfer von Donnerschrei zu verbrennen.", description = "Wir werden die Mauern der Feste nie wieder sichern können, solange Donnerschrei und seine Schläger Zugang zu Artillerie haben. Ihr müsst Euch durch diesen Abgrund kämpfen und seine großen Kanonen unbrauchbar machen.\n\nOrcs lagern ihr schweres Gerät in Kohlenteer, wodurch dieses leicht entzündlich wird. Nehmt meine Fackel und verbrennt alle Katapulte, die Ihr nördlich von Nordwacht seht.\n\nDann zündet diese großen Klingenwerfer in Donnerschreis Hauptlager an! Diese Dinger haben genug unserer Männer getötet.", progress = "Fackelt alles ab, <Klasse>. Verbrennt es zu Asche!", completion = "Gut! Ohne schweres Gerät, muss die Horde sich zurückziehen, um sich neu zu formieren. Wir haben uns etwas Zeit verschafft, um die Feste wieder zu sichern. Gut gemacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24949] = {title = "Beutepflicht", objective = "Sammelt 10 Stück Piratenbeute.", description = "Wir sollten hier nichts verschwenden, Schätzchen. Diese Seeräuber haben tonnenweise wertvollen Humbug herumliegen, der nur eingesammelt werden will. Könnt Ihr es fassen, dass sie es einfach nur besitzen und nichts damit machen?\n\nIch meine, warum machen sie sich denn erst die Mühe, es zu erlangen, wenn sie nur darum herumsitzen? Gestohlene Ware sollte so schnell wie möglich verkauft werden, um mit dem Erlös tolle neue Sachen kaufen zu können.\n\nNaja - seid ein Schatz und sammelt so viel Ihr könnt von ihrer Beute, während Ihr ihnen die Köpfe einschlagt. Ciao!", progress = "Mal sehen, was Ihr gefunden habt. Ihr habt nichts für Euch selbst einbehalten, oder? Ohne mich werdet Ihr keine Käufer finden, ich hoffe, Ihr seid Euch dessen bewusst.", completion = "Wunderschön! Und der Gedanke, dass sie nur darauf herumgesessen sind... Idioten.\n\nHier habt Ihr Euren Vorschuss; über die Boni der Gewinnteilung unterhalten wir uns später.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24950] = {title = "Kapitän Schreckensbart", objective = "Tötet Kapitän Schreckensbart.", description = "Nun gut, Schätzchen, jetzt habe ich etwas Größeres für Euch.\n\nWir haben den Kapitän der Südmeerfreibeuter auf einem seiner Boote südlich von hier entdeckt. Südlich, NICHT da, wo wir für mehrere Stunden lebensmüde Rausschmeißer gespielt haben. Er sitzt auf seinem Boot, eingebildet und stoisch, und sieht uns beim Krieg führen zu.\n\nSeine Witze zur \"feindlichen Übernahme\" erspare ich Euch. Begebt Euch zu seinem Schiff, prügelt den Seemann aus ihm heraus und dann sind wir auch schon fertig hier!", progress = nil, completion = "Meeresriesen? Ihr meint, er hat sie absichtlich auf Gadgetzan abgerichtet?\n\nEgal, den sind wir erstmal los. Und Gadgetzan ist uns auch wirklich etwas schuldig! Ich kann den Blick auf Marins Gesicht gar nicht erwarten!\n\nHier ist Euer Anteil, Schätzchen. Ihr macht noch richtig Karriere!", rewards = "FlirtrobenSchreckensbartwürgerhandschuheFahndergürtelUngeduldige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24951] = {title = "Eine großartige Idee", objective = "Benutzt den Käferköder der Schmuggler, um einen Schwärmer der Hazzali zu ködern.", description = "Diesen Haufen Frischfleisch müssen wir jetzt nur nach an dem Seil befestigen... und dann könnt Ihr mir auch schon ein paar Silithiden fangen.\n\nWie? Schaut mich nicht so an, es ist wirklich sicher. Ziemlich sicher. Sterben könnt Ihr schon. Auch einen schmerzvollen Tod. Aber es ist einfach! Werft das Fleisch dort runter, wartet, bis eines der Ungeziefer darauf anspringt, und zieht es dann mit dem Seil hier hoch!\n\nVersucht es bei den Schwärmern. Bei den anderen weiß ich nicht, ob sie Hyäne mögen, aber Schwärmer gibt es um die Ecke der Schlucht genug.", progress = nil, completion = "Seht nur, wie groß es ist! Es ist wunderbar. Dieser eklige Schwärmer wird uns dabei helfen, den ganzen Schwarm zu zerstören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24952] = {title = "Raketenstiefelkick", objective = "Benutzt die abrockpulververstärkten Raketenstiefel und bringt sie zu Hobart Wurfhammer.", description = "Ihr müsst diese Stiefel in die Caldera zu Hobart Wurfhammer bringen.\n\nJetzt, da sie mit dem übrigen Abrockpulver verstärkt wurden, sollten sie genügend Schubkraft haben, um Euch in einem Schuss bis ganz nach unten zu bringen.\n\nWenn Ihr bereit seid, aktiviert einfach die Stiefel. Keine Sorge, sie sind so eingestellt, dass sie Euch automatisch sanft auf den Boden bringen.\n\nGlaube ich zumindest.", progress = "Ah, da seid Ihr ja!", completion = "Wir haben keine Zeit zu verschwenden, Junge!\n\nWas ist denn mit dem Regler am linken Stiefel los?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24953] = {title = "Ungeziefer ausmerzen", objective = "Sprecht mit Narain Pfauentraum, um den gedankenkontrollierten Schwärmer in den Bau der Klaffenden Schlucht zu befehligen.", description = "Jetzt geht es mit meinem Plan erst richtig los. Wir haben den Schwärmer gefesselt und mit so viel Sprengstoff eingekleidet, wie er wohl tragen kann. Und nun werden wir dank Pfauentraums unfassbar toller mentaler Kräfte dieses Ungeziefer direkt in die Mitte der unterirdischen Höhle befehligen.\n\nUnd dann... KABUMM! Ungeziefer weg!\n\nIhr erhaltet die Ehre, das Ding kontrollieren zu dürfen. Sprecht mit Narain und macht Euch und Euren Ungezieferfreund startklar.", progress = "Ich habe keine Höhlenexplosion gehört! Versucht es nochmal!", completion = "Oh Mann, das war genial! Ihr hättet die Flammen sehen sollen, die aus dem Bau kamen!\n\nHier ist Eure Belohnung, für die Unterhaltung, die Ihr mir beschert habt und natürlich auch für die Räumung des Ungezieferbaus.", rewards = "Überwiegend großartige HandschuheScheuerschuhstiefelSchmugglerbeinplattenAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger des gähnenden Abgrunds\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24954] = {title = "Des Schildkrötengottes Kinder", objective = "Sammelt 5 Feuerdrüsen.", description = "Volcanoth ist der Schildkrötengott in der Höhle, den diese Primitiven verehren.\n\nEr ist nicht wirklich ein Gott.\n\n<Hobart verdreht die Augen.>\n\nAber er ist hart genug, damit ich Euch aus dem letzten funktionierenden Stiefel eine neue Waffe basteln muss.\n\nIch glaube, das alte Motto \"Feuer mit Feuer bekämpfen\" passt hier ganz gut. Und außerdem mag ich Feuer!\n\nUnd jetzt sammelt mir ein paar Feuerdrüsen von den Abkömmlingen von Volcanoth. Das sollte mir genug Zeit verschaffen, um den Raketenstiefel in etwas Passenderes zu verwandeln.", progress = "Wann ließe sich diese einfache Aufgabe besser erledigen, als jetzt, <Name>?", completion = "Seid vorsichtig mit diesen Drüsen, &lt;Name&gt;, vorsichtig!\n\n\n\nUnd jetzt ladet den umgebauten Raketenstiefel damit. Ich bin mir sicher, dass meine geniale Erfindung Euch aus den Socken hauen wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24955] = {title = "Un-satzung", objective = "Erhaltet 10 Unterschriften der Satzung von Ogern der Dünenbrecher.", description = "Ich habe ja bereits erwähnt, dass ich versuche, die Oger der Dünenbrecher in die Horde zu bringen... und für das Bilgewasserkartell billige Arbeit vor Ort zu verrichten.\n\nUm das zu schaffen, müssen wir ein Bekenntnis zum Einführungsprozess ablegen, oder ich bekomme später richtig Ärger. Deswegen habe ich diese Satzung verfasst und die Initiationsriten unserem zeitlich begrenztem Arbeitsvertrag beigefügt.\n\nIch habe auch eine Verkleidung für Euch, also macht Euch an die Arbeit und besorgt mir die Unterschriften.", progress = nil, completion = "Wow, gute Arbeit! Es ist ja schon toll, dass Ihr sie dazu gebracht habt, die Stifte zu halten und NICHT zu essen.\n\nDen Anzug könnt Ihr ablegen. Da drüben hin. Weg von mir. Ins Feuer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24956] = {title = "Donnerschrei zum Schweigen bringen", objective = "Tötet 4 Leutnants von Donnerschrei und nehmt Donnerschreis Helm an Euch, nachdem Ihr Karga Donnerschrei getötet habt.", description = "Ich bin dem Donnerschreiklan früher schon begegnet, <Name>. Er wird nicht von einem Orc angeführt, sondern von einem Monster - einem kriegsbesessenen Unhold, der keinerlei Anstand oder Mitleid besitzt. Er und seine Leutnants müssen sterben - nicht nur, um Nordwacht zu retten, sondern zum Wohle von ganz Azeroth.\n\nKarga Donnerschrei trägt einen Helm. Richtet ihn hin, <Klasse> und bringt mir diesen Helm. Er ist von ... besonderer Wichtigkeit.\n\nDonnerschrei hat sein Lager auf der anderen Seite des Abgrunds östlich von hier aufgeschlagen.", progress = "Ist er tot? Habt Ihr seinen ... Helm?", completion = "&lt;Tolliver greift ehrfürchtig mit zitternden Händen nach dem Helm.&gt;\n\nDonnerschreis Kampfschiffe brachten unsere Schiffe auf, als wir aus Gilneas flohen. Wir sollten als Trophäen hierher zum Kriegshäuptling gebracht werden. Als wir uns der Küste näherten, haben sich einige von uns zur Wehr gesetzt. Donnerschrei begann, wahllos zu töten und brüllte vor Lachen. Unser Schiff kenterte und er befahl seinen Leuten, auf uns zu schießen, während wir ertrinkend im Wasser schwammen. Nur wenige von uns schafften es an Land.\n\nAnschließend fand ich heraus, dass er den Skalp meines Bruders als ... als Trophäe trug.\n\n&lt;Er schließt seine Augen.&gt;", rewards = "Stiefel des gefallenen BrudersAuf Euch wartet eine dieser Belohnungen:\n\nDonnerschreitrophäe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][24957] = {title = "Auf zur Centipaarty", objective = "Sammelt 20 Centipaartikel von Silithiden der Centipaar.", description = "OK, Schätzchen. Wie gesagt, die Oger sind zu dumm, um zu wissen, was ihre Unterschrift bedeutet hat. Jetzt müssen wir sie dazu bringen, zu uns zu kommen, und das stellen wir mit Hilfe eines anscheinend in der Region sehr geliebten Geschmack an.\n\nZumindest von sabbernden Idioten sehr geliebt.\n\nBegebt Euch zum Giftigen Unterschlupf westlich von hier - eine große, schreckliche Grube voller gefährlicher Silithiden. Tötet ein paar der Centipaar und bringt mir ihre Stücke zurück, damit wir sie verteilen können, ja? Ciao.", progress = "Habt Ihr genug? Ich glaube nicht, dass die Oger kleine Portionen mögen.", completion = "Uff, das ganze Lager riecht wie ein Grundkurs für schlimme Gerüche.\n\nWir sollten mit diesen Dingern nicht länger etwas zu tun haben als unbedingt sein muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24958] = {title = "Volcanoth!", objective = "Benutzt die Schuhzooka, um Volcanoth zu töten.", description = "Es hat viel Blut, Schweiß und Tränen gebraucht, aber die Schuhzooka, zum Patent angemeldet, ist einsatzbereit!\n\nDiese nichtsnutzigen Pygmäen verfüttern unsere Leute an ihren \"Gott\" Volcanoth und wollen ihn sogar auf unser Dorf loslassen!\n\nIhr müsst in seine Höhle gehen und das Ding töten, bevor es zu spät ist!", progress = nil, completion = "Ich konnte alle sicher in die Stadt zurückbringen.\n\nSpringt auf! Wir müssen hier raus, bevor der Vulkan ein für alle Mal in die Luft geht!!!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVolcanoth!: Quest Complete\n\nIhr bekommt:\n\nRettungsleiterkordel"}
MultiLanguageQuestData['de'][24959] = {title = "Frisch aus dem Grab", objective = "Meldet Euch bei Totengräber Mordo an den Gräbern von Todesend in Tirisfal.", description = "<Name>!\n\nErhebt Euch, <Name>!\n\nWillkommen zurück im Reich der Lebenden. Ich habe Euch mit dem Segen unserer Dunklen Fürstin aus der Umarmung des Todes befreit.\n\nIhr seid niemandes <Sklave/Sklavin>, <Name>. Der Weg, den Ihr von hier aus einschlagt, ist ganz Eure Entscheidung. Wenn Ihr Euch dafür entscheidet, der Dunklen Fürstin Sylvanas zu dienen, empfehle ich Euch, mit Totengräber Mordo zu sprechen. Ihr könnt ihn hinter mir auf dem Friedhof finden.", progress = nil, completion = "Hallo. Ihr seid sicher... &lt;Name&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAgatha beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24960] = {title = "Das Erwachen", objective = "Sprecht mit Marschall Rotpfad, Lilian Voss und Valdred Moray.", description = "König, Bauer, oder <Klasse>... mir ist egal, was Ihr früher wart. Ich brauche nur jemanden mit einer funktionstüchtigen Zunge.\n\nVon den Toten erweckt zu werden ist strapaziös. Nicht jeder steckt es so gut weg wie Ihr. Um zum Punkt zu kommen, es gibt drei frisch erweckte Untote, die sich schwer tun.\n\nIch möchte, dass Ihr sie aufsucht und mit ihnen sprecht. Vielleicht brauchen sie einfach nur jemanden, mit dem sie sich identifizieren können.\n\nIhr findet sie hier auf dem Friedhof.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Klasse&gt;. Wie Ihr sehen könnt, haben wir uns nicht alle unserem Schicksal ergeben. Ich bin froh zu sehen, dass Ihr wenigstens bereit seid, zu arbeiten.\n\nValdred wird den Verlassenen eine wertvolle Bereicherung sein. Was die anderen beiden angeht... nun, es gibt nicht viel, was wir da tun können. Wir können sie nicht zwingen, sich uns anzuschließen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24961] = {title = "Die Wahrheit des Grabes", objective = "Macht Lilian Voss im großen Gasthaus von Todesend ausfindig und zeigt ihr Elreths Handspiegel.", description = "Vorhin sah ich eine junge Verlassene, die um ihr Leben schreiend zum alten Gasthaus gelaufen ist, bittend, wieder nach Hause zurückkehren zu können.\n\nNicht alle sind so bestimmt wie die anderen, <Name>. Und doch müssen wir unser Schicksal als Untote akzeptieren, wenn wir gegen jene vorgehen wollen, die uns unterdrücken wollen.\n\nNehmt meinen Handspiegel und zeigt ihn der jungen Frau. Sie muss sehen, was sie wirklich ist, und sich uns anschließen. Außerdem... wir können wirklich alles brauchen, was wir kriegen.", progress = nil, completion = "Sie ist weggerannt? Eine Schande.\n\nNun gut. Sie hat noch ihren freien Willen, also gibt es auch noch Hoffnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24962] = {title = "Die mitgenommene Schriftrolle", objective = "Lest die mitgenommene Schriftrolle und sprecht mit Xavier dem Jäger in Todesend.", description = "Oh, während Ihr Euch mit der Geißel geschlagen habt, kam eine Schriftrolle für Euch an. Es scheint sich um eine wichtige Angelegenheit zu handeln; ich glaube, das Siegel ist das von Jägerlehrer Xavier. Nehmt Euch die Zeit, seine Nachricht zu lesen, bevor Ihr Euch auf den Weg macht.", progress = "Ah, da seid Ihr ja. Gut. Ich habe mitbekommen, dass ein paar andere dem 'Tod' entkommen und in die Stadt geflüchtet sind. Vielleicht wird sich auch dieser Widerstand in der Zukunft auszahlen.\n\nIhr solltet Sylvanas für Eure Freiheit danken... Freiheit von Eurem Körper und Geist. Auch wenn Ihr weiterhin von der Seuche und ihren Auswirkungen befallen seid, so könnt Ihr Euch nun doch frei bewegen.", completion = "Ich werde hier sein, um Euch zu unterrichten, während Ihr Erfahrungen sammelt... Sucht mich auf, wann immer Euch danach ist. Ich verlange ein kleines Entgelt, aber Ihr werdet es für das Gelernte nicht bereuen.\n\nGeht nun und testet Eure Fähigkeiten. Je mehr Erfahrung Ihr sammelt, umso mehr Wissen wird sich Euch erschließen. Ich kann nicht alles mit Euch hier besprechen. Ihr solltet Euch jedoch darüber im Klaren sein, dass Sylvanas für Jäger mit Eurer Raffinesse auch zukünftig Bedarf hat.\n\nIhr werdet das Rückgrat unserer Rettung darstellen. Vergesst das nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24963] = {title = "Zermalmt sie sanft", objective = "Schwächt 8 Oger der Dünenbrecher und gebt ihnen dann die Werbedelikatesshäppchen des Bilgewasserkartells.", description = "OK, Schätzchen, hört mir zu. Es gibt immer zwei Wege, um andere dazu zu bringen, das zu tun, was man von ihnen möchte. Man kann Güter und Dienstleistungen anbieten, Sachen, die die Leute wollen... oder sie einfach richtig ordentlich verprügeln.\n\nIch finde es oft nützlich, beides zur gleichen Zeit zu machen und auch Ihr seid mit beiden Methoden schon gut vertraut. Nehmt diese Silithidhäppchen, schlagt ein paar Oger, bis sie Sternchen sehen, gebt ihnen die Häppchen und schlagt sie dann tot - in Ordnung?", progress = nil, completion = "Gute Arbeit, jetzt habt Ihr den Ogern hier beigebracht, alles, was ansatzweise nach &lt;Volk&gt; aussieht zu fürchten und zu respektieren.\n\nFaszinierend, was eine kleine Belohnung anrichten kann, um Leute für einen arbeiten zu lassen, nicht wahr? Oh, hier ist auch Eure Bezahlung.\n\n...was soll dieser Blick?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24964] = {title = "Das Jagdfieber", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen und übt die Fähigkeit 'Zuverlässiger Schuss' 5-mal an einer Trainingsattrappe.", description = "Mir wurde gesagt, ich solle Euch die Fähigkeiten der Jäger lehren. Schön und gut, aber meiner Meinung nach lernt man in der Wildnis mehr als man jemals mit theoretischem Wissen erlernen könnte.\n\ngeht, sammelt Erfahrungen und seht, ob Ihr ein paar neue Tricks lernen könnt. Kommt dann zu mir zurück und zeigt sie mir.", progress = nil, completion = "Ihr scheint eine Art Begabung zu haben, &lt;Name&gt;. Das ist gut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24965] = {title = "Magielehren", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen von Isabella in Todesend und übt die Fähigkeit 2-mal an einer Trainingsattrappe.", description = "Also, fangen wir mit der Arbeit an, ja?\n\nWenn Ihr an Macht gewinnt, wird sich Eure Verbindung zum Arkanen vertiefen und Ihr werdet Zugang zu neuen Zaubern und Fähigkeiten erhalten.\n\nIhr werdet es sehen. Geht, sammelt Erfahrungen, und kommt dann zurück und demonstriert mir, was Ihr gelernt habt.", progress = nil, completion = "Erfreut Euch an Eurer neugefundenen Macht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24966] = {title = "Von Licht und Schatten", objective = "Erreicht Stufe 3, um 'Schattenwort. Schmerz' zu erlernen und übt die Fähigkeit 5-mal an Trainingsattrappen.", description = "Priester der Verlassenen, mutige Biester;\nunübliche Wege schlägt <der Priester/die Priesterin> ein,\nSchattenriten - kein Licht - so muss <sein/ihr> Quell' finsterer sein.\n\nNicht nur die Welt hat uns verlassen, <Name>... auch das Licht hat sich von uns abgewandt. Wie man aus dem kleinen Gedicht jedoch erkennen kann sind wir nicht ganz ohne Macht.\n\nGeht, sammelt mehr Erfahrungen, sammelt mehr Macht. Kehrt dann zu mir zurück und demonstriert mir, was Ihr gelernt habt.", progress = nil, completion = "Ihr lernt schnell, &lt;Name&gt;. Ihr werdet weit kommen. Wenn Ihr mehr erlernen möchtet, so kommt zu mir zurück. Ich werde Euch gerne mehr unterrichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24967] = {title = "Stich!", objective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen und übt die Fähigkeit 3-mal an einer Trainingsattrappe.", description = "Leise! Ich will nicht, dass die Novizen hören, was wir hier besprechen.\n\nHört zu... <Name>, nicht wahr? Ich habe eine Technik, die Eure Vorgehensweise als Schurke verändern kann. Ihr werdet Eure Angriffe mit einem tödlichen Abschluss verbessern können. Vielleicht Euren Dolch sogar zwischen die Wirbel des Gegners stechen.\n\nUm das zu lernen müsst Ihr nur ein bisschen Erfahrung sammeln. Keine Angst, das kriegt Ihr schon hin.", progress = nil, completion = "Ihr könnt mir glauben, das wird Euch mal den… das Leben retten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24968] = {title = "Dunkle Taten", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen und übt die Fähigkeit 5-mal an einer Trainingsattrappe.", description = "Wenn Ihr Eurer Laufbahn als Hexenmeister folgt, werdet Ihr beginnen, die Stimmen der Teufelskraft zu hören… sie werden Euch ihre Geheimnisse offenbaren und Euch neue Zauber lehren.\n\nIch will sehen, dass Ihr einen Zauber erlernt und ihn an einer der Trainingsattrappen hier ausprobiert.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24969] = {title = "In den Kampf stürmen", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen und übt die Fähigkeit an einer Trainingsattrappe.", description = "Wenn Ihr ein stärkerer Krieger sein möchtet, so müsst Ihr Eure Waffen anpassen. Ihr werdet auf Euren Abenteuern viele stärkere Schwerter und größere Schilde finden, davon bin ich überzeugt.\n\nEs ist aber nicht nur die Rüstung, die stärker wird - Ihr werdet auch neue Techniken erlernen. Geht, sammelt Erfahrungen, erlernt etwas Neues und kommt dann zu mir zurück und zeigt es mir.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24970] = {title = "Auch nicht besser als die Zombies", objective = "Meldet Euch bei Darnell in Todesend in Tirisfal.", description = "Während Ihr in der Höhle wart, ist Euer großer Freund Darnell vorbeigekommen und hat uns beunruhigende Nachrichten gebracht.\n\nSeit die Val'kyr angekommen sind, haben sich immer mehr Untote dagegen entschlossen, sich den Rängen unter dem Banner der Dunklen Fürstin anzuschließen. Sie haben sich in einem kleinen Lager hier im Tal versammelt und stellen eine Streitmacht auf.\n\nSie planen einen Angriff auf Todesend, <Klasse>.\n\nDarnell ist nicht weit von hier, entlang der Straße, die nach Osten führt. Nehmt Euch in Acht, <Name>. Zwar sind diese Untoten nicht völlig hirnlos, aber das heißt noch nicht, dass sie bei klarem Verstand sind.", progress = nil, completion = "&lt;Name&gt;. Ihr habt es geschafft.\n\nSeht Ihr die Zelte dort? Dorthin führt unser Weg. Die Schlacht hat wahrscheinlich schon begonnen.", rewards = "Kurzschwert der VerlassenenDolch der VerlassenenSchlägel der VerlassenenBastardschwert der VerlassenenIhr bekommt:\n\nErfrischendes Quellwasser"}
MultiLanguageQuestData['de'][24971] = {title = "Angriff auf das Lager der Moderhirne", objective = "Tötet Marschall Rotpfad und 8 untote Moderhirne.", description = "Während Ihr Euch um Exekutor Arrens Aufträge gekümmert habt, habe ich selbst auch eine Aufgabe übernommen. Schattenpriester Sarvis hat mich gebeten, das Lager der Moderhirne zu erkunden.\n\nSie heißen nicht ohne Grund Moderhirne...\n\nIhr Anführer ist Marschall Rotpfad, ein absolutes Ungetüm.\n\nSeht, <Name>... der Angriff hat begonnen. Ihr seid besser im Kampf als ich. Geht und helft unseren Truppen!\n\nWenn Ihr fertig seid, sucht Schattenpriester Sarvis in der Kapelle auf. Viel Glück, <Name>.", progress = nil, completion = "Unter der Macht der Val'kyr wiedergeboren zu werden ist ein sehr aufreibender Prozess. Viele überleben den Schock nicht und werden zu Zombies oder Ghulen.\n\nAndere behalten etwas Menschliches bei und scheinen Außenstehenden ganz normal zu sein... und doch sind sie im Inneren erkrankt. Wir hätten die Moderhirne an dem Tag töten sollen, an dem sie wiedererweckt wurden.\n\nIhr... Ihr seid ein starker &lt;Klasse&gt;, &lt;Name&gt;. Ich wusste, dass Ihr Euch gut schlagen würdet. Ihr werdet Todesend bald verlassen.", rewards = "TodeswachenrundschildStab des ExekutorsDer folgende Zauber wird auf euch gewirkt:\n\nDarnell beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24972] = {title = "Entscheidende Informationen", objective = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Todeswache Simmer auf dem Calstonanwesen in Tirisfal.", description = "<Sarvis holt ein Stück Papier aus seiner Robe hervor.>\n\nDie hier müssen zu meinem Außenagenten, Todeswache Simmer gebracht werden. Diese Informationen betreffen den Aufenthaltsort der letzten verbleibenden Starrköpfe des Scharlachroten Kreuzzugs. Wir werden diese Kreuzzügler ein für alle Mal ausradieren. Und wenn mich mein Gefühl nicht täuscht, werdet Ihr eine Schlüsselrolle in unseren Bemühungen spielen, <Name>.\n\nNehmt die Straße die nach Norden aus Todesend herausführt. Kurz nachdem Ihr nach Tirisfal hineinkommt, solltet Ihr auf ein großes Pfarrhaus treffen. Simmer sollte dort zu finden sein.", progress = "Ja, was wollt Ihr?", completion = "Ja, das ist sehr gut. Diese Informationen zu beschaffen, war gute Arbeit, &lt;Name&gt;. Hmm... Die Namen der Offiziere des Scharlachroten Kreuzzuges in Tirisfal... \n\nStellt Euch nur vor, welchen Schlag wir der Moral dieser verfluchten Fanatiker verpassen könnten, wenn wir es schaffen, all ihre Anführer auf einen Schlag zu töten. Ich werde diese Informationen weiterleiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24973] = {title = "Nachtweber", objective = "Tötet 8 junge Nachtweber und 5 Nachtweber.", description = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.\n\nEs gibt eine Goldmine im Westen, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.\n\nBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, <Name>.", progress = nil, completion = "Hmm, nun ja, es ist ein Anfang. Es wird ein paar Wochen oder Monate dauern, das Ungeziefer gänzlich auszumerzen. Danach müssen wir mit ein paar Fackeln da runtergehen und die Netze niederbrennen.\n\nIhr habt Eure Pflicht gut erfüllt, &lt;Name&gt;.", rewards = "FlachswesteZombiehautgamaschenUnverwüstliche PanzerwesteNachtweberspinnenarmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24974] = {title = "So schrecklich allein", objective = "Benutzt die Murlocleine an einem Finsterflossenmurloc an der Flüsternden Küste, dann kehrt mit ihm zu Sedrick Calston am Calstonanwesen zurück.", description = "Da arbeitet man sein ganzes Leben lang, und was ist der Dank? Von einer Seuche dahingerafft. Dann arbeitet man als Untoter noch viel härter, und was ist der Dank? Geld, ja, ein kleines Zuhause mit ein paar Mitläufern, aber Glück? Nicht wirklich.\n\nIch werde auf meine alten Tage einsam, <Name>. Ich brauche einen Gefährten. Benutzt diese Leine mit einem der Murlocs an der Flüsternden Küste im Nordwesten. Ihr müsst ihn wahrscheinlich erst schwächen, bevor er sich die Leine anlegen lässt. Bringt ihn dann zu mir.", progress = "Oh, der Schmerz der Einsamkeit ist unerträglich!", completion = "Oh, seht ihn Euch nur an! Ist er nicht das niedlichste, was Ihr je gesehen habt? Ich danke Euch, &lt;Name&gt;. Ich fühle mich schon viel energiegeladener.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24975] = {title = "Felder des Kummers", objective = "Stehlt 10 Kürbisse von Sollidens Bauernhof in Tirisfal.", description = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, <Klasse>. Wenn Ihr darauf hofft, Euch der Dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.\n\nIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.\n\nSobald Ihr 10 beisammen habt, bringt sie zu mir.", progress = "Habt Ihr bereits 10 Kürbisse gesammelt, <Name>?", completion = "Ihr habt Eure Befehle gut ausgeführt, &lt;Klasse&gt;. Ihr habt Euch als eine echte Hilfe für die Armee der Dunklen Fürstin erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24976] = {title = "Abwechslung ist die Würze des Todes", objective = "Besorgt 4 Markblätter, 4 Xavrens Dorn und 8 salzige Seegurken.", description = "Diese Kürbisse erfüllen einen Zweck, <Klasse>. Sie sind der Träger für meine neueste Seuche, die dieses Mal aus einer besonders schmerzvollen und ansteckenden Mischung besteht. Für die Seuche brauche ich jedoch einige sehr seltene Zutaten.\n\nWir brauchen Markblatt, das nur am Grund des Stillwassertümpels östlich von hier wächst. Außerdem noch Xavrens Dorn, das an den felsigen Klippen im Nordwesten zu finden ist. Und schließlich noch salzige Seegurken aus der Brandung an der Flüsternden Küste.", progress = "Das wird meine bisher beste Versuchsreihe. Ich habe es im Gefühl, mein lieber <Klasse>.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Und jetzt zum spaßigen Teil.", rewards = "Xavrens HandschuheMarkblattstiefelIhr bekommt:\n\nKürbistasche"}
MultiLanguageQuestData['de'][24977] = {title = "Johaans Experiment", objective = "Bringt den getränkten Kürbis zu dem gefangenen scharlachroten Zeloten beim Pavillon auf dem Calstonanwesen.", description = "Harmlose Kürbisse, ja? Wenigstens scheint es so. Wenn wir den Vormarsch der Geißel aus dem Norden und den Menschenbefall im Süden zurückschlagen wollen, müssen wir uns über die Möglichkeiten klar werden, die das Geschenk des Untot-Seins für uns bedeutet.\n\nMit ein wenig Einfallsreichtum kann aus einem einfachen Kürbis ein Mitarbeiter unserer Dunklen Fürstin werden. Dieser Kürbis wurde mit meiner neuesten Formel getränkt und wird sich als ziemlicher Leckerbissen erweisen.\n\nEin weiterer scharlachroter Zelot wurde gefangen genommen und wird draußen bei dem Pavillon gefangen gehalten. Bringt diesen Kürbis zu dem Narren.", progress = "Bleibt weg von mir, grässliche, unheilige Kreatur! Möge das Licht mich beschützen! Der Scharlachrote Kreuzzug soll das Antlitz Azeroths von Euresgleichen...\n\n... Moment mal. Ist das Essen für mich? Ich habe solchen Hunger...", completion = "Dem Licht sei Dank! Endlich etwas zu essen! Süßer, süßer Kürbis...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24978] = {title = "Schnitter der Ernter", objective = "Tötet 10 Bauern von Tirisfal oder Landarbeiter von Tirisfal.", description = "Menschen sind von Natur aus wankelmütige Kreaturen. Die Bauern im Westen bilden keine Ausnahme. Natürlich, im Moment scheinen sie friedlich ihre Felder zu pflügen, aber vielleicht erheben sie schon morgen ihre Sensen gegen uns. Die Allianz lauert in der Nähe, in Gilneas, und die Macht von Sturmwind im Süden... beide könnten diese Ackerbauern rekrutieren und sie wie einen Keil zwischen uns treiben.\n\nIch will, dass sie sterben. Sorgt dafür, dass das geschieht.", progress = nil, completion = "Ihr habt die Voraussetzungen, ein mächtiger &lt;Klasse&gt; zu werden, &lt;Volk&gt;. Ich habe die Schreie dieser Menschen bis hierher gehört. Vielleicht sind wir diese Menschenplage bald los.", rewards = "Brodlers ArmschienenSensenklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24979] = {title = "Ein Scharlachroter Brief", objective = "Findet die Gefangene in der Scharlachroten Palisade.", description = "Leutnant Gebler:\n\nWie seltsam, dass Ihr eine Gefangene gemacht habt... und dazu noch eine Untote. Was habt Ihr Euch dabei gedacht? Glaubt Ihr, dass sie nur wegen des ehemaligen Status über den Edikten des Scharlachroten Kreuzzugs stehen könnte?\n\nDas ist äußerst besorgniserregend, Gebler. Ich möchte Euch daran erinnern, dass solches Verhalten strafbar ist. Ich befehle Euch, die Gefangene sofort hinzurichten. Sie ist nicht mehr eine von uns.", progress = "Was steht darin?", completion = "Der Scharlachrote Kreuzzug macht keine Gefangenen. Dass sie es mit dieser jungen Frau tun... seltsam.\n\nDie Mächte, die Ihr beschreibt, sind noch seltsamer. Sie hat die Gitter ihres Gefängnisses durchquert und hat denjenigen, der sie gefangen genommen hat, getötet? Warum hat sie das nicht sofort getan?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24980] = {title = "Die Scharlachrote Palisade", objective = "Tötet 10 scharlachrote Krieger.", description = "Wir brauchen jemanden mit \"Eigeninitiative\", um den Scharlachroten Kreuzzug ins Grab zu treiben. Jemanden wie Euch.\n\nBeweist mir, dass Ihr in der Lage seid, der Dunklen Fürstin zu dienen. Reist nach Westen zum Turm hinter Sollidens Bauernhof und erschlagt 10 Krieger des Scharlachroten Kreuzzugs.", progress = nil, completion = "Ausgezeichnet, &lt;Klasse&gt;. Eure Fähigkeiten in der Kampfkunst sind unbestreitbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24981] = {title = "Ein Dorn in unserem Auge", objective = "Tötet 3 scharlachrote Zeloten und 3 scharlachrote Missionare und beschafft das dringende scharlachrote Memorandum.", description = "Informationen, die wir von Exekutor Arren in Todesend erhalten haben, enthalten alle nötigen Details, um die menschliche Plage aus diesen Landen zu tilgen. Laut dieser Informationen hat der Scharlachrote Kreuzzug Hauptmann Perrine und eine Brigade zum verfallenen Turm südwestlich von Brill versetzt.\n\nTötet 3 seiner Zeloten und 3 seiner Missionare. Und wenn Ihr schon da seid, seht zu, ob Ihr noch mehr Informationen über ihre Vorhaben herausfinden könnt.", progress = "Wir werden den Scharlachroten Kreuzzug wie Vieh ins Verderben treiben.", completion = "Hört sich an, als sollten wir nach dieser Voss Ausschau halten. Ich erwarte nicht, dass ein Verlassener für ihre Ergreifung eine Belohnung bekommen wird... ich befürchte nur, dass sie sich am Ende gegen uns wenden wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24982] = {title = "Die neuen Verlassenen", objective = "Meldet Euch bei Magistrat Sevren in Brill in Tirisfal.", description = "Offen gesagt waren die Verlassenen früher ein Haufen schluchzender Jammerlappen. Wir haben uns in baufälligen Ruinen der Menschen verbarrikadiert, uns vor der Geißel versteckt, vor der Allianz verkrochen und am Rockzipfel der Horde gekatzbuckelt.\n\nDoch nun schaut Euch um und bewundert die neue Generation der Verlassenen. Wir haben uns hier in Azeroth einen Namen gemacht und dieser Name wird noch weiter wachsen. Schon bald wird unser Herrschaftsgebiet sich über die gesamte Welt erstrecken!\n\nWollt Ihr einen Rat? Sprecht mit Magistrat Sevren in Brill. Folgt einfach dieser Straße. Er leitet das Dorf.", progress = nil, completion = "Ja, ich bin der Magistrat hier in Brill und direkt der Dunklen Fürstin unterstellt. Wenn Ihr es schafft, mich zu beeindrucken, begegnet Ihr der Bansheekönigin vielleicht eines Tages sogar selbst. Und jetzt zu Eurer ersten Aufgabe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24983] = {title = "Verlassenen-Pflichten", objective = "Sprecht mit Todeswache Linnea bei der Wegstation Todeswacht in Tirisfal.", description = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.\n\nIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!\n\nReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", progress = nil, completion = "Magistrat Sevren will einen Bericht? Nun gut: Die Verteidiger auf dem Bollwerk halten den Großteil der Geißel in Schach, aber gelegentlich schlüpfen ein paar durch. \n\nWir haben sporadisch Aktivitäten der Geißel östlich dieses Postens gesichtet, und diese häufen sich um Balnirs Bauernhof.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24988] = {title = "Die Kälte des Todes", objective = "Sammelt fünf Nachtsaugerpelze.", description = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer Dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.\n\nJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze bringen würdet, könnte ich mir eine Decke nähen. Helft mir, <Name>, auf dass ich der Sache weiter dienen kann.", progress = "Habt Ihr schon fünf Nachtsaugerpelze, <Name>?", completion = "Ich weiß Eure Mühen zu schätzen, &lt;Name&gt;. Möge Sylvanas Eure Tapferkeit eines Tages anerkennen...", rewards = "Gretchens PantoffelnNachtsaugerhoseArmschienen der TodeswachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24989] = {title = "Rückkehr zum Magistrat", objective = "Kehrt zu Magistrat Sevren nach Brill zurück.", description = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich Euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.", progress = nil, completion = "Es ist beunruhigend zu hören, dass die Geißel am Bollwerk vorbeischlüpft. Selbst jetzt noch greifen sie uns unaufhörlich an.\n\nAber wir werden nicht nachgeben. Der Lichkönig ist tot; niemand wird je wieder von uns Besitz ergreifen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24990] = {title = "Herzschlag der Schattenhunde", objective = "Sammelt 5 Phiolen Schattenhundblut.", description = "Fürstin Sylvanas hat sich an das königliche Apothekarium gewandt. Sie hat uns aufgefordert, eine neue Seuche zu erfinden - eine Seuche, die tödlicher ist als jede Krankheit in Azeroth. Diese neue Krankheit wird den Untergang unserer Feinde - gleich, ob lebendig oder tot - herbeiführen.\n\nMeine Studien haben ergeben, dass Tierblut der Schlüssel sein könnte. Hier, füllt diese Phiolen mit Schattenhundblut, damit ich meine These testen kann.", progress = "Habt Ihr das Schattenhundblut schon bekommen, <Name>? Die Zeit verrinnt!", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;, und ich danke Euch für Eure Bemühungen.", rewards = "Ihr bekommt:\n\nSchwaches Trollblutelixier"}
MultiLanguageQuestData['de'][24991] = {title = "Garrens Schlupfwinkel", objective = "Meldet Euch bei Apotheker Jerrod bei Garrens Schlupfwinkel in Tirisfal.", description = "Inzwischen ist Euch sicher schon aufgefallen, dass die Königliche Apothekervereinigung eine weit verbreitete Organisation ist. Wir nehmen unsere Seuchenalchemie ernst. Wir glauben, dass wir unsere Ziele schneller erreichen, je mehr unserer Agenten Experimente durchführen.\n\nEiner dieser Agenten geht seiner Arbeit in einem kleinen Lager nördlich von hier nach. Er heißt Jerrod, und er könnte einen Lehrling von Eurer... Statur brauchen.", progress = nil, completion = "Holland? Ein Amateur. Man braucht kein zweistöckiges Apothekarium, um eine Seuche herzustellen... man braucht Liebe. Und vielleicht ein paar gute Assistenten.\n\nLasst mich Euch zeigen, wie man Seuchen WIRKLICH macht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24992] = {title = "Aus Gilneas entflohen", objective = "Berichtet Exekutor Zygand in Brill in Tirisfal von der Anwesenheit des Worgen.", description = "Wie Ihr Euch vorstellen könnt, ist ein streunender Worg in Tirisfal ein wichtiges Ereignis. Exekutor Zygand wäre daran sicher interessiert.", progress = nil, completion = "Hm… ja, das ergibt Sinn. Die Worgen strömen nur so aus Gilneas heraus. Ich wusste, es wäre nur eine Frage der Zeit, bis sie hier in Tirisfal ankommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24993] = {title = "Vernichtet die Worgen", objective = "Findet und tötet 5 Spitzel der Worgen in Brill.", description = "Wir müssen uns um diese Worgen kümmern, und zwar schnell. Unsere oberste Priorität besteht darin, alle Worgen auszulöschen, die in Brill eingedrungen sind.\n\nIch möchte, dass Ihr hier in Brill nach verdächtigen Vorkommnissen Ausschau haltet, <Name>. Wir wissen, dass diese Worgen sich in den Schatten verstecken können, also achtet auf jedes noch so kleine Zeichen... Fußspuren, umgedrehte Steine, alles!", progress = nil, completion = "Und die ganze Zeit waren sie direkt vor unserer Nase! Kaum auszudenken! Ich werde meine Todeswachen alarmieren. So etwas passiert uns ganz sicher NICHT wieder.", rewards = "Cape des ExekutorsWorgtöterschwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24994] = {title = "Verdammniskraut", objective = "Sammelt 10 Verdammniskraut.", description = "Mein Abgesandter hat mir gerade einen Scheffel Düsterkraut geliefert. Düsterkraut! Ich brauche kein Düsterkraut, ich brauche Verdammniskraut! Ihr könnt die Bedrängnis, in der ich mich befinde, bestimmt nachvollziehen, <Name>.\n\nEs soll Euer Schaden nicht sein, wenn Ihr mir beschafft, was ich benötige. Bringt mir Verdammniskraut in ausreichenden Mengen und ich werde Euch angemessen belohnen.\n\nSoweit ich weiß, verseucht es gerne die Flora in der Nähe des Massengrabs nördlich des Friedhofs von Brill. Eilt Euch und vergesst nicht, dass sich in der Gegend dort Gnolle befinden.", progress = "<Der Apotheker murmelt etwas zu sich selbst.>\n\nSie haben mir Düsterkraut gebracht? DÜSTERKRAUT?!", completion = "Ah, mein Verdammniskraut. Ausgezeichnet!\n\n&lt;Apotheker Jerrod reibt sich gierig die Hände.&gt;\n\nDas wird mir sehr nützlich sein. Ihr habt mir, äh, der Fürstin heute einen guten Dienst erwiesen, &lt;Name&gt;. Wie versprochen ist hier Eure wohlverdiente Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][24995] = {title = "Wie Schuppen von den Augen", objective = "Beschafft 5 Finsterflossenschuppen.", description = "Während Ihr Proben für mich gesammelt habt, ist mir durch meine Experimente schlagartig klargeworden, dass mehr Reagenzien nötig sein werden, damit sich diese Krankheit gut verbreiten kann. Ein hilfloses Opfer zu vergiften ist ein Kinderspiel. Eine ganze Welt zu verseuchen ist etwas komplizierter.\n\nIch brauche mehrere Schuppen von den Murlocs aus der Nähe. Ihr werdet diese Kreaturen dabei finden, wie sie hirnlos die Küste im Norden entlangwandern.", progress = "<Name>, habt Ihr die Schuppen von den Murlocs bekommen?", completion = "Die Schuppen sind perfekt, &lt;Name&gt;. Genau das, was ich für dieses Gebräu brauche.", rewards = "KesselhandschuheFinsterflossengürtelIhr bekommt:\n\nSchlummersand"}
MultiLanguageQuestData['de'][24996] = {title = "Hollands Experiment", objective = "Bringt Hollands Spezialgetränk zu dem gefangenen Gebirgsjäger.", description = "Wenn ich das richtig verstanden habe, hat sich noch einer dieser törichten Zwergengebirgsjäger einfangen lassen. Die Todeswache hat ihn hier in diesem Gebäude untergebracht und sie haben einen der ihren damit beauftragt, ihn davon zu überzeugen, dass er nicht fliehen sollte.\n\nWarum geht Ihr nicht und probiert, wie dem gefangenen Gebirgsjäger dieses Spezialgetränk, das ich für ihn zubereitet habe, schmeckt? Es beinhaltet einen dezenten Hinweis darauf, was die Dunkle Fürstin für ganz Azeroth im Sinn hat.", progress = "Wenn ich mein getreues Gewehr bei mir hätte, wärt Ihr so gut wie tot, <Klasse>. Wartet nur, bis die Dampfpanzerbrigade hier anrückt, um mich zu befreien!", completion = "Ah, endlich etwas zu trinken. Was für ein Bier ist das? Ich bin sicher, dass es kein Rhapsodiemalz ist, aber jetzt gerade nehme ich alles, um die alte Kehle anzufeuchten.", rewards = "GebirgsjägergürtelGalgenschlingenstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24997] = {title = "Grabräuber", objective = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle und sammelt 6 Fläschchen voll Einbalsamierungssekreten.", description = "Die Massengräber im Wald im Westen wurden ausgehoben, um die... beeindruckende... Zahl der Toten aufzunehmen, die Tirisfal zu beklagen hatte, als die Seuche zum ersten Mal auftrat.\n\nDen Leichen in diesen Gräbern ist der Untod bis jetzt erspart geblieben, aber die Geißel sendet jetzt schon Moderfellgnolle, um die Leichen zu sammeln und sie zur Aufstocken ihrer Streitkräfte zu benutzen. Das dürfen wir nicht zulassen!\n\nEure Aufgabe beinhaltet zweierlei: Tötet die Moderfelle beim Massengrab und bei Garrens Schlupfwinkel, und nehmt ihnen das Einbalsamierungssekret ab, das ihnen Leben verleiht.", progress = "Ist Eure Aufgabe abgeschlossen? Habt Ihr diese Hundeviecher vernichtet und sie ihres Sekrets beraubt?", completion = "Meisterlich erledigt, &lt;Name&gt;. Die Geißel irrt sich, wenn sie denkt, dass sie diese Leichen gegen uns verwenden könnte und die Flüssigkeit, die Ihr von den Moderfellsklaven gesammelt habt, wird von unseren Apothekern untersucht werden. Vielleicht enthält sie Geheimnisse, die wir gegen sie verwenden können.", rewards = "ZombiehautstiefelKaltstahlstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24998] = {title = "Madenauge", objective = "Tötet Madenauge und erbeutet seine Tatze.", description = "Madenauge ist ein widerliches Ungeheuer - sogar nach Gnollmaßstäben. Er führt eine Bande abtrünniger Gnolle durch die Lande, zerfetzt alles in Tirisfal und stiehlt alle Leichen, die er unterwegs findet.\n\nDas sind unsere Leichen! Wir hatten Pläne damit!\n\nFolgt dem Pfad ein Stück hinauf, dort hält sich Madenauge für gewöhnlich auf. Erweist ihm keine Gnade. Gnade ist für Schwächlinge.", progress = "Ja?", completion = "Ausgezeichnete Arbeit! Jetzt muss ich nur noch Jerrod davon überzeugen, unsere Operation in diese Hütte zu verlegen...", rewards = "Besudelter GnollgürtelGürtel aus BrillGarrens GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][24999] = {title = "Die Saat der Furcht pflanzen", objective = "Jagt 12 Kaulquappen der Finsterflossen, bis sie vor Angst ohnmächtig werden.", description = "Sieht aus, als ließe Euch Jerrod die Murlocs im Norden jagen. Das ist gut... wir können ihre Bestandteile benutzen, um unsere Gifte herzustellen. Manchmal mache ich mir allerdings Sorgen...\n\nDie Laichgründe der Finsterflossenmurlocs sind nicht weit von der nördlichen Küste Tirisfals entfernt, also werdet ihr wahrscheinlich mehrere Kaulquappen zwischen den ausgewachsenen Tieren am Strand finden. Wenn diese leicht zu beeindruckenden jungen Murlocs sich eines Tages rächen würden... so etwas könnte uns ruinieren. Geht und jagt sie, und zeigt ihnen, dass mit den Verlassenen und der Horde nicht zu spaßen ist.", progress = nil, completion = "Sind sie vor Euch weggelaufen, &lt;Name&gt;? Gut. Das ist besser, als sie zu töten... wenn sie überleben, um davon zu erzählen, lernen zukünftige Generationen von Murlocs, uns zu fürchten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25000] = {title = "Teegans Leute", objective = "Tötet Schreckenszahnläufer und Schreckenszahnsensenklauen, um 8 Schreckenszahnbälge zu erhalten.", description = "He, <Klasse>!\n\nSeid Ihr unterwegs, um Korporal Teegan zu unterstützen? Er ist dafür verantwortlich, dass die Nachschubrouten offen bleiben.\n\nEr hat zwei der widerspenstigsten Zwerge, die ich je gesehen habe, als Verantwortliche für Verschiedenes eingesetzt. Wenn Ihr auf diese beiden schrulligen Jäger Eindruck machen wollt, müsst Ihr zeigen, dass Ihr Euch gegen die Raubtiere hier in der Gegend behaupten könnt.\n\nDie Raptoren westlich der Burg sind besonders bösartig. Bringt Goucho einige frische Bälge und Ihr werdet mit einem Schlag sowohl Eindruck schinden, als auch die Truppen versorgen.", progress = "Worum geht es, <Klasse>? Das Lager hier ist nicht geeignet für Besichtigungstouren.", completion = "Hey, Ihr seid zäher, als Ihr ausseht. Diese Schreckenszahnbälge wehren Pfeile ab und lassen Axtklingen abprallen - die Raptoren sind nicht leicht zu besiegen, aber ihre Bälge sollte man in diesem vom Licht verlassenen Brachland mit Silber aufwiegen. Gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25001] = {title = "Sandscharrer", objective = "Tötet Sandscharrer.", description = "Meine anderen Assistenten kümmern sich darum, unsere stolzen neuen Kameraden in ihre gemütlichen Käfige zu bringen und sie dorthin zu befördern, wo sie am meisten gebraucht werden. Für die Horde. In der Zwischenzeit können wir uns um einen weiteren letzten Punkt auf meiner Agenda kümmern.\n\nSandscharrer, der Häuptling der Dünenbrecher, ist wahrscheinlich zu dumm, um zu merken, was wir hier tun. Aber ich mag es nicht, wenn man Sachen nicht komplett abschließt, Schätzchen. Er ist in dem Bau westlich von hier, nicht weit entfernt. Macht Euch die Hände schmutzig, macht ihn fertig und dann ist auch dieser Teil als abgeschlossen anzusehen, OK?", progress = nil, completion = "Und damit sind wir fertig! Hier gibt es nichts mehr für uns zu tun. Gute Arbeit, Schätzchen.\n\nObwohl, vielleicht bin ich zu übereilig. Habt Ihr im Bau der Oger etwas gefunden?", rewards = "Zupackende HändeSandscharrers ArmschienenGeschäftsabschließerAuf Euch wartet eine dieser Belohnungen:\n\nBrosche des Bilgewasserkartells\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25002] = {title = "Beute", objective = "Holt 10 Vorratskisten der Nordwacht aus dem Raptorennest heraus.", description = "<Ihr entdeckt eine Ladeliste bei der Leiche, die eine lange Liste verschiedener, dringend an der Front benötigter Kleinteile aufzählt.>\n\n<Eine blutige Spur im Schmutz zeigt, dass Leichen von hier aus nach Süden in die Richtung der Raptorennester gezerrt wurden.>\n\n<Die Raptoren haben möglicherweise auch die Vorräte weggeschleppt. Diese Vorräte für Korporal Teegan wiederzuholen könnte dabei helfen, dieses Unglück zu mildern!>", progress = "Wie bitte? Meine Versorgungskarawane wurde von diesen kaltblütigen Scherenpfotendingern ausgeraubt?", completion = "Meine Vorräte! Also das zeigt ja echte Eigeninitiative, &lt;Klasse&gt;. Diese Rapsägen, oder wie die heißen, haben schon ganz andere Männer zu Hackfleisch zerschnippelt. Danke!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25003] = {title = "Die Familiengruft", objective = "Tötet 5 klagende Vorfahrinnen und 5 faulende Vorfahren.", description = "Der stärkste Punkt der Mühlen ist die Gruft der Familie Agamand. Hauptmann Dargol hat die Urahnen der Agamands mit Nekromantie auferstehen lassen und will sie gegen uns verwenden.\n\nDas darf nicht geschehen, und Ihr müsst ihn aufhalten. Reist zur Gruft der Familie Agamand und besiegt die wiedererweckten Ahnen der Agamands.", progress = nil, completion = "Eure Taten haben der Geißel einen Schlag versetzt. Und Euer Sieg wird nicht unbeachtet bleiben - weder von den Verlassenen noch von unseren Feinden.\n\nFührt den Kampf fort, so wie wir alle, &lt;Name&gt;, und eines Tages werden die Verlassenen die Herrschaft über Azeroth haben, wie es ihnen gebührt.", rewards = "Gamaschen der Familie AgamandArmreif der Familie AgamandReitstiefel der Familie AgamandIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25004] = {title = "Die überrannte Mühle", objective = "Sammelt 5 schartige Rippen und 3 geschwärzte Schädel.", description = "Die Geißel versucht, hier bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.\n\nEs wurden klare Befehle erteilt. Die Diener der Geißel bei den Mühlen müssen vernichtet werden.\n\nSammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.", progress = "Unser Krieg gegen die Geißel dauert noch immer an, <Name>. Tut das Eurige und werft diese verfluchten, hirnlosen Untoten wieder zurück in die Pestländer!", completion = "Eure Bemühungen wissen wir zu schätzen, &lt;Name&gt;. Ich werde Euch nicht dafür danken, dass Ihr das Notwendige getan habt, aber ich werde mir Euren Namen merken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25005] = {title = "Sprecht mit Sevren", objective = "Sprecht mit Magistrat Sevren in Brill in Tirisfal.", description = "Ich habe die Überreste zerstört, die Ihr mir gegeben habt, <Name>. Das heißt alle bis auf diese...\n\nDevlin Agamand war in seinem Leben schwach und scharfzüngig und war einer der ersten, die der Seuche zum Opfer fielen. Er lebte lange als Sklave der Geißel, länger als die Meisten. Daher hat er möglicherweise Wissen, das für uns wertvoll wäre.\n\nBringt seine Überreste zu Magistrat Sevren, und sagt ihm, was ich Euch gesagt habe. Er wird wissen, was zu tun ist.", progress = "Der Gestank des Untodes umgibt Euch, <Name>. Was ist Euer Begehr?", completion = "Devlin Agamand? Ist es er, den Ihr da in Eurem Sack tragt? Ha!\n\nJa, ich weiß, was Coleman versuchen möchte, und das möchte ich auch. Ich hoffe, Ihr seid vorbereitet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25006] = {title = "Der Griff lockert sich", objective = "Sprecht mit Schattenpriesterin Malia in Brill und nehmt an der Extrahierung von Devlin Agamand teil.", description = "Während der Frostthron schlummert, wird die Kontrolle, die der Lichkönig einst über die Geißel hatte immer schwächer. Sein Einfluss auf einen Schwächling wie Devlin Agamand sollte gering genug sein, um ihn ganz auszuschalten.\n\nSprecht mit Schattenpriesterin Malia im Haus auf der östlichen Seite der Stadt. Sie wird Euch dabei helfen.", progress = "Was habt Ihr herausgefunden?", completion = "Oh, wie schade. Vielleicht ist die Herrschaft der Geißel über Devlins Geist doch zu stark geblieben. Oder vielleicht waren unsere Methoden nicht stark genug. Es ist auch möglich, dass Devlin einfach zu einfältig war, um zu begreifen, was wir von ihm wollten.", rewards = "Devlins HemdStiefel aus BrillIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25007] = {title = "Osten... Stets nach Osten", objective = "Meldet Euch bei Hochexekutor Derrington am Bollwerk in Tirisfal.", description = "Ihr habt so viel für uns hier getan, <Name>, doch <Männer/Frauen> von Eurem Kaliber werden anderswo benötigt.\n\nIm Osten liegt das Bollwerk: eine verstärkte Barrikade gegen die Verheerer der Pestländer. Das Bollwerk schützt uns vor dem Einmarsch der Geißel und ermöglicht uns eine Zuflucht, in der wir unsere Streitkräfte hier in Tirisfal aufbauen können.\n\nGeht und sprecht mit Hochexekutor Derrington. Er ist ein Verbündeter und wird zweifellos jede Hilfe, die Ihr ihm anbieten könnt, zu schätzen wissen.", progress = nil, completion = "&lt;Der Hochexekutor mustert Euch abschätzend.&gt;\n\nIhr seid kein wirklich beachtlicher &lt;Klasse&gt;, was? Nun ja, wenn ich mit Euch fertig bin, wird das anders sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25008] = {title = "Schmutzige Tiere", objective = "Tötet 6 Fleischreißerstrauchdiebe.", description = "Ihr habt wahrscheinlich den Geruch von diesen Fleischreißerstrauchdieben auf dem Weg hierher aufgenommen - die stinken schlimmer als der Schwarze Peter hier. Wertlose Tiere! Sie schnappen uns unsere Beute vor der Nase weg, durchwühlen unsere Vorräte und was noch schlimmer ist... man kann sie nicht essen.\n\nGeht und tötet einige von ihnen.\n\nDann tötet noch ein paar mehr, wenn Ihr Lust habt.", progress = nil, completion = "Ooooo-oooooh, ja! Die besten Fleischreißer sind tote Fleischreißer.", rewards = "Gürtel aus FleischreißerlederAuf Euch wartet eine dieser Belohnungen:\n\nPlündererring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25009] = {title = "Im Krieg mit dem Scharlachroten Kreuzzug", objective = "Tötet 3 Scharlachrote Zeloten und 4 Scharlachrote Ordensmitglieder.", description = "Obwohl die Macht des Scharlachroten Kreuzzugs nachlässt, befinden wir uns noch immer im Krieg. Der Bericht, den Exekutor Arren geschickt hat, deutet darauf hin, dass Scharlachrote Kreuzfahrer vom verfallenen Turm im Südosten von Tirisfal in der Nähe von Balnirs Bauernhof aus angreifen. Sie werden von Hauptmann Vachon angeführt.\n\nTötet 3 seiner Zeloten und 4 seiner Ordensmitglieder. Das sollte dem Kreuzzug einen vernichtenden Schlag versetzen.", progress = nil, completion = "Eure Taten werden das Vorrücken des Scharlachroten Kreuzzugs in Tirisfal erheblich verlangsamen... hoffentlich für immer. Doch andere Bedrohungen lauern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25010] = {title = "Ein tödlicher neuer Verbündeter", objective = "Findet Euren neuen Verbündeten in der Scharlachroten Lagerstatt in Tirisfal.", description = "Kurz bevor Ihr am Bollwerk eingetroffen seid, hat sich eine höchst ungewöhnliche junge Untote bei mir gemeldet. Sie schwor dem Scharlachroten Kreuzzug ewige Feindschaft, also habe ich sie zur Arbeit gegen unsere Feinde im Norden geschickt. Ihr sagtet, Ihr hättet vor Kurzem tote Kreuzfahrer gesehen? Das war wahrscheinlich ihr Werk.\n\nGeht und seht nach ihr, und findet heraus, ob sie bei ihrem Rachefeldzug gegen den Kreuzzug Hilfe brauchen kann... obwohl es mich nicht überraschen würde, wenn sie schon alle getötet hätte.", progress = nil, completion = "Als Ihr die Ruinen des Lagers betrachtet, hört Ihr ein Flüstern hinter Euch.\n\n&lt;\"Ich könnte Euch jetzt sofort töten, wenn ich wollte. Passt besser auf Euch auf, &lt;Volk&gt;.\"&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25011] = {title = "Auf zu besseren und größeren Taten", objective = "Sprecht mit Timothy Cunningham am Bollwerk in Tirisfal.", description = "Hier auf dem Bollwerk gibt es keinen Ruhm mehr für Euch zu erringen, <Name>. Ihr habt schon genug getan. Möglicherweise warten jedoch im Silberwald neue Abenteuer auf Euch.\n\nSprecht mit meinem Fledermausführer, Timothy Cunningham. Er wird Euch kostenlos nach Brill fliegen.", progress = nil, completion = "Klar könnt Ihr einen Flug nehmen. Wenn Hochexekutor Derrington darum bittet, habe ich ja auch eigentlich keine andere Wahl.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25012] = {title = "Schwingt Euch in die Lüfte", objective = "Sprecht mit Exekutor Zygand in Brill in Tirisfal.", description = "Wenn Ihr auf dem Rückweg nach Brill seid, solltet Ihr unterwegs bei Exekutor Zygand vorbeischauen. Ich habe gehört, dass es im Silberwald im Süden irgendeine Art Aufruhr gibt. Er weiß sicher mehr als ich.\n\nSprecht noch einmal mit mir, wenn Ihr bereit seid, abzureisen.", progress = nil, completion = "Willkommen zurück, &lt;Name&gt;. Ich habe Geschichten aus dem Osten gehört. Wer hätte gedacht, dass ein junger &lt;Volk&gt; wie Ihr die letzten winselnden Reste des Scharlachroten Kreuzzugs ausmerzen würde?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25013] = {title = "Ein wenig Pep", objective = "Beschafft 4 Proben von heimtückischem Nachtweberspinnengift.", description = "<Zitters probiert sein frisches Gebräu.>\n\nHmm... das ist nicht ganz fertig. Es braucht noch etwas, das ihm etwas mehr Pep verleiht. Ich hab's! Die Spinnen im Norden haben ein starkes Gift, das genau richtig sein sollte. Schaut Ihr mal nach, ob Ihr mir etwas davon extrahieren könnt, <Name>?", progress = "Habt Ihr etwas Gift von einer heimtückischen Nachtweberspinne, <Name>? Es ist die letzte Komponente die ich brauche, um mein Experiment auszuprobieren.", completion = "Ah, dieses Gift wird perfekt, &lt;Name&gt;. Alles andere ist zu meinem Gebräu hinzugefügt und verkocht worden. Danke, &lt;Klasse&gt;!", rewards = "Hochentwickelte NachtweberspinnenarmbrustNachtweberhandschuheRundschild des SchnittersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25014] = {title = "Sandscharrers Schatz", objective = "Sprecht mit Megs Schredderschreck.", description = "In dieser verwitterten Steintruhe im hinteren Teil von Sandscharrers Hort findet Ihr ein erstaunliches Artefakt.\n\nEs ist wie ein Käfer geformt, hat eine glatte Oberfläche aus wunderbarem Blau mit goldenen Streifen. Es sieht mechanisch aus, aber nicht wie etwas, das Ihr bisher von den Händen Sterblicher hergestellt gesehen habt - und es sieht sehr alt aus.\n\nMegs wird sich sicherlich dafür interessieren.", progress = "Ihr habt etwas gefunden?", completion = "Das habt Ihr im Ogerbau gefunden? Das...\n\n...ist nichts, um aufgeregt zu werden, sicherlich! Sicherlich ist das nur... ein ganz harmloses Schmuckstück... und ich kann Euch genau sagen, was Ihr damit zu tun habt.\n\n&lt;Megs fängt an zu flüstern.&gt;\n\nSeid leise und wedelt mit dem Ding nicht so in der Luft herum.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25015] = {title = "Lasst sie quieken", objective = "Tötet insgesamt 8 Klingenwächter der Borstennacken oder Deviatdornweber und findet einen Dornstab von einem der Dornweber.", description = "Eine der heimischen Arten in Kalimdor sind die \"Stacheleber\". Stachlige kleine Nervensägen. Grund genug, diesen Kontinent zu hassen.\n\nDie Überfälle begannen kurz, nachdem wir unsere ersten Lager aufgeschlagen hatten. Schlimmer noch, diese stachligen Unholde scheinen in diesem dornigen Höllendschungel richtig aufzublühen. Ich brauche Eure Hilfe, um sie zurückzuschlagen, damit wir wieder Verbindung zum Gefechtsstand herstellen können.\n\nWährend Ihr da draußen seid, bringt einen dieser verdrehten Zweige an Euch, die ihre Zauberer offensichtlich dazu benutzen, um diesen Dschungelwuchs zu manipulieren...", progress = "Ich sollte noch erwähnen, dass Ihr wahrscheinlich eine Machete benötigt, um Euch durch dieses Chaos einen Weg zu bahnen.\n\nDieser Dschungel kam aus dem Nichts!", completion = "&lt;Korporal Teegan nickt, während Ihr ihm Bericht erstattet, dann umklammert er den Dornenstab mit beiden Händen.&gt;\n\nAlso das hier verwenden die Stacheleber gegen uns? Glaubt Ihr, dass sie diese Stäbe benutzt haben, um diesen Dschungel zu erschaffen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25017] = {title = "Uralte Hindernisse", objective = "Zerstört 6 Sandsteingolems.", description = "Seit Jahren wurde dieses Tal durch ein undurchdringbares Tor verschlossen. Das Tor wurde durch den Kataklysmus zerstört und nun ist es an uns, all die Geheimnisse des Tals zu erforschen.\n\nUnd doch stehen uns noch immer Hindernisse im Weg. Die vor Urzeiten von den Titanen hinter dem Tor erschaffenen Kreaturen sind zum Leben erwacht. Sie laufen ohne Ziel im Sand umher und greifen alles an, was ihnen in die Nähe kommt.\n\nJemand muss die Golems ausschalten, die im Tal patrouillieren. Was haltet Ihr davon?", progress = nil, completion = "Ich danke Euch, &lt;Klasse&gt;. Ohne Eure Hilfe würden wir nicht mit solchen Feinden umzugehen wissen.", rewards = "TorwächtergürtelSchiftung des GutachtersSandsteinschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25018] = {title = "Andoren wird es wissen", objective = "Bringt das Artefakt zu Andoren Morgendunst im Tal der Behüter.", description = "Hört gut zu, <Name>. Ich weiß nicht, wie die Oger dieses Artefakt in die Hände bekommen haben; es handelt sich wirklich um ein Werk der Titanen. Ich bin zwar kein Experte, aber diese Tatsache allein macht das Ding wohl älter als den Sand, auf dem wir stehen.\n\nIch weiß auch, dass solche Dinge meistens Ärger hervorrufen. Ich will damit nichts zu tun haben. Reist nach Süden ins Tal der Behüter und gebt es dem Blutelfen Andoren Morgendunst. Und bitte stellt keine Fragen, Schätzchen.", progress = nil, completion = "Ihr habt es... ausgerechnet in einem Ogerbau gefunden? Undenkbar. Es wundert mich, dass sie nicht versucht haben, es in Stücke zu zertrümmern.\n\nMit ein wenig Glück, &lt;Klasse&gt;, werden wir hier noch weitere faszinierende Antiquitäten wie diese finden... wenn Ihr uns helfen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25019] = {title = "Anspruch erheben", objective = "Tötet 10 Archäologen der Zwerge.", description = "Nicht nur wir haben den Wert der Südmondruinen verstanden. Die Zwerge der Forscherliga sind bereits dort eingefallen und sammeln Artefakte und Inschriften für die Allianz.\n\nIch glaube, sehr viel mehr muss ich dazu nicht sagen. Wir werden nicht zulassen, dass ihre Funde in die Hände der Allianz fallen. Tötet so viele Zwerge, wie Ihr könnt und vertreibt sie aus den Ruinen.", progress = nil, completion = "Ausgezeichnet. Je weniger Störungen wir durch die Allianz erwarten können, um so besser.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25020] = {title = "Sprachfragmente", objective = "Sammelt 5 uralte Hieroglyphen.", description = "Wir haben in den Südmondruinen östlich von hier ein paar interessante Funde gemacht. Meine Kollegen haben Steintafeln mit uralter Schrift gefunden, die durch die Sandstürme freigelegt wurden.\n\nDie Schrift ist in keiner uns bekannten Sprache verfasst, allerdings ähnelt sie den Markierungen der Ruinen der Titanen in manchen Aspekten. Wenn wir die Schrift entziffern könnten, so würde dies bestimmt viele Geheimnisse zu Tage bringen.\n\nLeider sind meine Kollegen damit beschäftigt, die Steintafeln vor der Allianz zu verteidigen. Begebt Euch zu den Südmondruinen und holt Euch die Tafeln.", progress = "Habt Ihr die Hieroglyphentafeln?", completion = "Ich danke Euch, &lt;Name&gt;. Nun können wir unsere Aufmerksamkeit ganz der Erforschung des Tors widmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25021] = {title = "Blut zum Blühen", objective = "Sammelt 6 Handvoll Blut von Trollen der Sandwüter.", description = "Um in der harten Wüste zu überleben, musst'n die Sandwüter die Geheimnisse der Blutmagie erlern'n. Blut trink'n, um Macht zu krieg'n... dunkles Voodoo, ja? Nich' schön, aber hier draußen hab'n wir ja nix voreinander zu verberg'n, oder?\n\nWenn wir das Schwert find'n woll'n, brauch'n wir Blut. Ihr habt Glück, dass Mazoga Verräter is', ja? Und viele Trolle der Sandwüter sind hier auf den Hügeln.\n\nHolt Euch Blut für Mazoga... viel Blut... und wir mach'n Ritual, um Jang'thraze zu find'n.", progress = "Ihr habt aber nix davon getrunk'n oder? Ich brauch das alles noch...", completion = "&lt;Mazoga hält das getrocknete Blut in seinen Händen und führt es zu seinem Mund, um zu trinken. Es wird flüssig und fließt schmierig seinen Rachen herunter.&gt;\n\nSie trink'n Blut, sie werd'n mächtig. Ich trinke ihr Blut...\n\n&lt;Mazoga lächelt ein großes, blutverschmiertes Lächeln.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBlut schlucken\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25022] = {title = "Fehlkommunikation", objective = "Rettet Botschafter Gaines von den Stachelebern in der Überwucherung.", description = "Ich habe ihm gesagt, dass er ein Narr ist, aber Botschafter Gaines bestand darauf, dass er mit den Stachelebern eine Allianz gegen die Horde aushandeln könnte. Selbst wenn ihm das gelungen wäre - ich für meinen Teil hätte nicht mit diesen... Schweinekerlen an meiner Seite kämpfen wollen.\n\nNun, Gaines ist nicht zurückgekehrt und General Hawthorne wird mich zur Rechenschaft ziehen, wenn ich einen unserer besten Unterhändler an diese quiekenden Unholde verliere.\n\nFindet den Botschafter in diesem dampfenden Dschungelchaos und rettet ihn, wenn er noch am Leben ist.", progress = nil, completion = "Gute Arbeit! Gaines ist vor nicht allzu langer Zeit hier auf seinem Weg nach Nordwacht und zu einem warmen Bad vorbeigekommen\n\nDie Mission war allerdings kein völliger Verlust. Wir haben ziemlich viel über diese Stacheleber und ihre Führungsstrukturen gelernt.\n\nJetzt können wir mit den Dingen... auf MEINE Art umgehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25023] = {title = "Alte Freunde", objective = "Sprecht mit Thrall am Spähposten des Kriegshäuptlings auf den Verlorenen Inseln.", description = "In Ordnung, dann haltet Euch mal an der Leiter fest. Wir müssen raus hier!\n\nWir machen einen kurzen Zwischenstopp in der Stadt und dann bringe ich Euch zu ein paar alten Freunden!", progress = nil, completion = "Ich habe Euch doch gesagt, dass wir uns wiedertreffen würden, &lt;Name&gt;.\n\n\n\nSchade, dass es unter diesen Umständen sein muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25024] = {title = "Vertreibt die Fallschirmjäger", objective = "Tötet 10 Fallschirmjäger der Allianz.", description = "Die Allianz hat uns genau zum falschen Zeitpunkt eingeholt, mein Freund. Wir haben uns zwar um ihre Schiffe gekümmert, aber sie haben immer noch ihre Flugzeuge und werfen ihre berühmte 127. Gebirgsjägerstaffel an der Küste ab.\n\nUnsere Kriegshetzer und Späher schaffen es kaum noch, die beiden Rampen gegen ihre überwältigende Zahl zu verteidigen. Aber wenn Ihr ihnen helft, wird das Schicksal sich sicher ganz schnell wenden!", progress = nil, completion = "Nie hat ein &lt;Klasse&gt; besser gekämpft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25025] = {title = "Sang'thraze der Schmetterer", objective = "Besiegt Zakkaru und erhaltet das versiegelte Sang'thraze.", description = "Das Blut spricht. Ich spüre seinen Fluss im Sand... durchzog'n von Tod, eine Wüste des Leidens...\n\n<Mazogas Augen verdrehen sich.>\n\nDa! Das Blut fließt nach Süd'n, in ein Tal der Knochen. Zakkaru! Zakkaru, Brut von Makkari, dem Dunklen, der ein Opfer verlangt... sein Vater wurde aus Zul'Farrak verdrängt und sein Aufstieg verhindert... er wird noch einmal Blut schmeck'n...\n\n<Mazoga schwankt.>\n\nGeht, <Klasse>. Zakkaru hat Sang'thraze. Ihr wollt nich', dass er es behält, glaubt mir.", progress = "Hab'n die Geister die Wahrheit gesagt, Mann? Habt Ihr's?", completion = "&lt;Mazoga grinst, als er Euch das Schwert mit beiden Händen abnimmt.&gt;\n\nHat Euch nich' besonders gemocht, hm? Nicht nur Trolle woll'n in dieser Welt Blut, Mann.\n\nLasst uns die andere Klinge find'n...", rewards = "Streitkolben des KnochentalsBlutsprechertunikaSchulterstücke des BlutlüsterndenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25026] = {title = "Dunkelstes Mojo", objective = "Sammelt 6 dunkelstes Mojo von Zombies der Sandwüter.", description = "Jang'thraze entzieht sich mir, Mann... das Blut war nich' genug. Wir müssen an etwas Stärkeres rankomm'n, um es zu find'n.\n\nWenn man jed'n Troll braucht, um über die Runden zu komm'n, dann ist ein toter Troll ein echtes Problem und deshalb hab'n die Sandwüter gelernt, wie man die Toten mit Voodoo wiederbelebt. Man fällt um, steht wieder auf, macht sich an die Arbeit. Immer wieder, für immer!\n\nDie Zombies, die entsteh'n, sind voll vom dunkelsten Mojo, das zu find'n ist. Geht in Richtung West'n, da findet Ihr einen ganzen Haufen von denen, und bringt mir das Mojo, ja?", progress = "Habt Ihr das Zeug, Mann?", completion = "&lt;Mazoga kippt seinen Kopf zurück und inhaliert tief von dem Klumpen des geheimnisvollen Materials. Seine Augen leuchten auf.&gt;\n\nMächtiges Zeug, Mann... ah, wenn Ihr seh'n könntet, was ich sehe... vielleicht probiert Ihr es ja auch mal aus, irgendwann.\n\nDie Geister ruf'n...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25027] = {title = "Und das Schweinchen, das hat Zähne...", objective = "Verwendet den Dornstab gegen Dreizahn und tötet 2 Deviatgreisinnen in der Überwucherung.", description = "Wenn man Gaines glaubt, nennen die Stacheleber ihre Matriarchin \"Dreizahn\". Sie hat die Dornen dieses verrückten Dschungels für ihre eigenen Zwecke verdreht und sie hat befohlen, dass man Gaines \"zerreißen und an die Überwucherung verfüttern\" soll. Nettes Weibchen.\n\nLassen wir sie ihre eigene Medizin kosten. Nehmt den Dornstab, den Ihr entdeckt habt und wendet ihn gegen Dreizahn an, um sie zu eliminieren. Dann tötet die Greisinnen, die sie ausgebildet hat, damit niemand anders ihren Platz einnehmen kann.", progress = "Ich verstehe, warum die Horde diese kleinen Nervensägen hasst. Habt Ihr Euch Dreizahn schon angenommen?", completion = "...Extremität um Extremität abgerissen!? Nun, ich habe fast ein schlechtes Gewissen, aber der brennende Hass verhindert das. Sie hat bekommen, was sie verdiente.\n\n&lt;Korporal Teegan nimmt den Dornenstab und zerbricht ihn über seinem Knie.&gt;\n\nProblem gelöst.", rewards = "Handschuhe der StachelebergreisinDreizahnarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25028] = {title = "Von Grund auf Ärger", objective = "Sammelt 10 ungewöhnliche Blütenknospen von knospenden Blüten in der Überwucherung auf.", description = "Teegan ist ein Narr, wenn er denkt, dass die Stacheleber an dieser plötzlichen Wucherung Schuld sind. Seht Euch um. Ich beobachte jeden Tag, wie diese Pflanzen wachsen und sprießen - jede Generation ist noch mehr mutiert als die vorherige. Das ist keine Stammesmagie, das ist etwas Urwüchsiges. Und Gefährliches.\n\nVorgestern ist ein großer Druide durch unser Lager gezogen. Sucht Naralex irgendwo mitten in diesem Dschungel. Er wird wissen, was zu tun ist.\n\nUnd sammelt unterwegs Pflanzenproben in der Überwucherung, damit er sie studieren kann.", progress = "Ich bin sehr beschäftigt, <Klasse>. Dieser unkontrollierte Bewuchs droht den ganzen Kontinent einzuhüllen. Habt Ihr irgendwelche Neuigkeiten?", completion = "Ah, Proben von verschiedenen Bereichen der Überwucherung? Ja, die werden ausgesprochen hilfreich sein. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25029] = {title = "Todesfälle in der Familie", objective = "Beschafft Euch die Überreste von Gregor, Nissa, Thurman und Devlin.", description = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.\n\nAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wenigstens waren wir loyale Narren.\n\nDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!\n\nDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", progress = "Habt Ihr die sterblichen Überreste der Agamands? Sind diese verfluchten Bestien endlich vernichtet?", completion = "Rache hat einen süßen Geschmack, findet Ihr nicht? Als Ihr die Agamands vernichtet habt, habt Ihr da irgendeinen Hinweis auf einen freien Willen in ihnen bemerkt? Ich hoffe es. Ich hoffe, sie hatten Angst, bevor sie in die Vergessenheit zerschlagen wurden.\n\nDas ist eine närrische Hoffnung, ich weiß. Aber es ist dennoch eine Hoffnung, die ich hege.", rewards = "KnochenknackerDunkelholzstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25030] = {title = "Die Spukmühlen", objective = "Bringt Dargols Schädel zu Coleman Heller bei Agamands Mühlen.", description = "Ihr spürt eine bösartige Präsenz im Schädel der Bestie. Coleman Heller wäre sicher daran interessiert.", progress = "Nun, nun... Was haben wir denn da?", completion = "Ist das Dargol? Als er noch am Leben war, war er schon bösartig. Seine Launen hinterließen tiefe Wunden, seine Klinge sogar noch tiefere.\n\nUntot zu werden hat daran nichts geändert, obwohl es seinem Charakter durchaus gerecht wird.\n\n&lt;Coleman hält den Schädel hoch und blickt in die leeren Augenhöhlen.&gt;\n\nJa, das war ganz sicher Dargol. Ich kann seine Boshaftigkeit sogar in seinen Überresten spüren.\n\nIhr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25031] = {title = "Auf zu den Mühlen", objective = "Meldet Euch bei Coleman Heller bei Agamands Mühlen in Tirisfal.", description = "Agamands Mühlen im Westen sind an die Geißel verlorengegangen. Die Familie Agamand wurde getötet und das gesamte Anwesen von der Geißel übernommen.\n\nDas ist möglicherweise der größte Außenposten der Geißel in Tirisfal, <Name>. Wenn Ihr glaubt, dass Ihr <Klasse> genug seid, geht dort hinaus und sprecht mit Coleman Heller. Er hat sein Bestes gegeben, um das Land zurückzuerobern, und er kann Hilfe gebrauchen. Folgt einfach dieser Straße - sie führt Euch direkt zu ihm.", progress = nil, completion = "Argh! Fort mit Euch! Oh, Ihr gehört nicht zur Geißel, oder?\n\nDer Bansheekönigin sei Dank, dass Ihr hier seid. Ich habe die Situation hier oben weit unterschätzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25032] = {title = "Geheimnisse in der Oase", objective = "Sucht nach dem Jang'thraze der Beschützer.", description = "Ja, jetzt sehe ich auch die andere Hälfte, Mann... südlich von hier...\n\nWir sind ganz in de Nähe, Mann. Es ist eine Oase, unter dem Schlamm des Wassers vergrab'n. Beeilt Euch!", progress = nil, completion = "Mazoga? Er hat das Schwert an sich genommen? Dieser dreckige...\n\n&lt;Trenton blickt sehr finster drein.&gt;\n\nWenigstens seid Ihr mit dem Leben davon gekommen. Der Biss des Peitschers ist sehr gefährlich.", rewards = "OasenmantelungHalbwahrheitsgreiferMazogas ausrangierte HelmkappeLichthammerschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25034] = {title = "An die Front!", objective = "Findet Botschafter Gaines im Gefechtsstand im Südlichen Brachland.", description = "Ich würde Euch gern hier hinter den Linien behalten, aber offensichtlich seid Ihr an die Front gerufen worden. Botschafter Gaines - Ihr erinnert Euch? - hat den Gefechtsstand verlegt und hat in seinem letzten Schreiben verlangt, dass Ihr ihm höchstpersönlich helfen sollt.\n\nIhr findet unseren Gefechtsstand südlich von hier in einer Gegend, die als \"Felder des Blutes\" bekannt geworden ist.\n\nSeid vorsichtig, <Name>. Die Horde hat sich darauf verlegt, unsere Offiziere unterwegs aus dem Hinterhalt heraus zu überfallen.", progress = nil, completion = "Ah, &lt;Name&gt;. Ich habe mit dem General hier über Euch gesprochen. Ich danke Euch erneut, dass Ihr mein Leben gerettet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25035] = {title = "Die Linien durchbrechen", objective = "Sprecht mit Jornun, um Euch einen Ritt zur Bucht der Gallschuppen zu sichern und sucht dort nach Morakki.", description = "Vol'jin hat zum Angriff auf die Naga, die unsere nördliche Insel übernommen haben, aufgerufen. Viele unserer Männer kämpfen bereits nahe der Brücke gegen den Feind, aber ein paar von uns versuchen ihre Linien zu durchbrechen, um die Insel selbst anzugreifen.\n\nSprecht mit Jornun. Er steht direkt hier und wird Euch den Ritt zur Insel ermöglichen. Sucht dort nach Morakki, dem Hauptmann der Wache. Er wird Euch sagen, wie Ihr bei der Schlacht behilflich sein könnt.", progress = nil, completion = "Gut, dass Ihr hier seid, Bruder.\n\nVol'jin erfüllt uns in solchen Momenten mit Stolz. Es fühlt sich gut an, Bedrohungen bei den Hörnern zu packen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25036] = {title = "Teegans Sorgen", objective = "Meldet Euch bei Korporal Teegan bei Teegans Expedition im Südlichen Brachland.", description = "Der Admiral wird zufrieden sein, dass Nordwacht fast wieder gesichert ist, aber wenn wir diesen Kontinent im Griff behalten wollen, müssen wir die Nachschublinien nach innen offen halten.\n\nKurz vor dem Angriff habe ich die merkwürdigsten Berichte von Korporal Teegan erhalten, der die Verantwortung dafür trägt, dass unsere Verbindung mit dem Gefechtsstand aufrechterhalten wird. Er sagt, er hat Schwierigkeiten mit dem \"Dschungel\"? Es gibt keinen Dschungel im Brachland!\n\nFolgt der oberen Straße aus Nordwacht heraus und schaut, ob Ihr unserem eigensinnigen Korporal zur Hand gehen könnt.", progress = nil, completion = "Also Paxton sagt, es gibt keinen Dschungel im Brachland? Und wie nennt Ihr DAS hier?\n\nIch habe einen Haufen Vorräte, die ins Innere gebracht werden sollen und mein Lager ist von einem Wald, der - ich schwöre - stündlich weiter wächst überrannt worden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25037] = {title = "Krebsfischen", objective = "Tötet Zwergbrandungskriecher und sammelt 5 Stücke frisches Kriecherfleisch.", description = "Vielleicht wird mein alternder Körper nach all den Jahren zu wählerisch, aber Eberfleisch bekomme ich nicht mehr so leicht runter. Na ja, bleibt umso mehr für die neuen Rekruten\n\nWir haben zwar gerade einige Krebsfallen ausgelegt, aber würdet Ihr einem ungeduldigen alten Troll, der sich nach frischem Kriecherfleisch sehnt, helfen? Es gibt sie überall auf der Insel, aber am besten jagt man sie vor der Ostküste.", progress = "Das Meer schenkt uns kaum etwas, das besser schmeckt als frisches Kriecherfleisch.", completion = "Wunderbar. Ich danke Euch für Eure große Freundlichkeit, Junge. Die Geister werden bestimmt wohlwollend auf Euch herabsehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25038] = {title = "Gordos Aufgabe", objective = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland in Brill.", description = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.\n\nWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland in Brill.", progress = "Wo ist diese nutzlose Monstrosität? Entweder habt Ihr, was ich benötige, oder Ihr verschwindet besser von hier und sucht es.", completion = "Was ist denn das? Düsterkraut?! Ich brauche kein Düsterkraut! Diese hirnlose Fleischmasse pflückt da draußen Gänseblümchen und bringt Gott weiß wie viele Tölpel wie Euch dazu, das Gleiche zu tun. Das sollte keine Beleidigung sein.\n\nWir kümmern uns später um das Düsterkraut. Im Moment haben wir andere Dinge zu besprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25039] = {title = "Habt Ihr etwas Merkwürdiges gesehen?", objective = "Sprecht mit Exekutor Zygand über Eure Begegnung mit dem Worgen.<Volk>! Hört mal, ich habe etwas… Merkwürdiges zu besprechen.\n\nGestern war ich am Blendwassersee angeln, als ich etwas wirklich Komisches gesehen habe… eine Art Wolfmann, der in Tirisfal herumrannte. Meint Ihr… äh… also… Könnte das ein Worgen gewesen sein?\n\nJedenfalls überlege ich die ganze Zeit, ob ich es Exekutor Zygand sagen soll, aber dieser Kerl jagt mir einfach eiskalte Schauer über den Rücken. Könntet Ihr nicht mit ihm sprechen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Volk>! Hört mal, ich habe etwas… Merkwürdiges zu besprechen.\n\nGestern war ich am Blendwassersee angeln, als ich etwas wirklich Komisches gesehen habe… eine Art Wolfmann, der in Tirisfal herumrannte. Meint Ihr… äh… also… Könnte das ein Worgen gewesen sein?\n\nJedenfalls überlege ich die ganze Zeit, ob ich es Exekutor Zygand sagen soll, aber dieser Kerl jagt mir einfach eiskalte Schauer über den Rücken. Könntet Ihr nicht mit ihm sprechen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25041] = {title = "Der Stolz des Löwen", objective = "Tötet insgesamt 5 Ebenenstreuner oder Ebenenstolzmähnen.", description = "Respektiert den Löwen, <Name>! Ein grausamer Jäger. Man muss die Eleganz des Tieres bewundern... Muskeln und Klauen... Jagt seine Beute bis zur Erschöpfung... So urtümlich...\n\nTut mir leid - ich schweife ab. Wie ich schon sagte, ich respektiere diese Löwen, aber sie sind mörderisch für unsere Patrouillen. Und das meine ich wörtlich. Die Männer haben Angst, nachts alleine aufs Klo zu gehen. Könntet Ihr dabei helfen, unser ein Lager ein wenig sicherer zu machen?\n\nBrachlandlöwen hängen gerne unter Bäumen herum.", progress = nil, completion = "Gute Arbeit! Wie war's? Habt Ihr die Jagd genossen?\n\nSeid Ihr durch hohes Gras gelaufen, angetrieben von der Witterung Eurer Beute, bis Ihr ihr an die Kehle springt und das Adrenalin durch Euch schießt während Eure sabbernden Fangzähne... Äh, also so in etwa.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25042] = {title = "Leerer Bauch marschiert nicht gern", objective = "Besorgt 4 frische Sturmschnauzensteaks, indem Ihr Sturmschnauzen im Südlichen Brachland tötet.", description = "Es stimmt schon, was man sagt: Leerer Bauch marschiert nicht gern. Und wir marschieren jetzt schon eine ganze Weile.\n\nIch überlege, ob wir ein paar dieser riesigen Sturmschnauzen grillen sollen, die hier herumstolpern. Das Fleisch würde uns für Wochen ernähren.\n\nSturmschnauzen sind groß und langsam und sollten einfach zu töten sein. Es sei denn... Ihr habt nicht zufällig Metall bei Euch?", progress = "<Trawley leckt sich über die Lippen und kann sein Sabbern kaum unterdrücken.>\n\nHabt Ihr meine Steaks schon? Schön blutig?", completion = "&lt;Sams Augen quellen ihm förmlich aus dem Kopf, als ihr die riesigen Fleischstücke vor ihm hinknallt.&gt;\n\nOh ja... oh ... JA! Ich hätte meins gern englisch. Ich denke, ich könnte etwas für die anderen grillen... Wie hätte Ihr Eures gern?", rewards = "LötzinnschildKesselrührerSturmschnauzenfellstiefelTrawleys HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25043] = {title = "Felder des Blutes", objective = "Tötet 10 Ödnisgrunzer in den Feldern des Blutes im Südlichen Brachland.", description = "Die Horde nennt diese Gegend nur noch die \"Felder des Blutes\". Ein passender Name: Das Rohr hier ist mit dem Blut einiger meiner besten Leute getränkt.\n\nIch habe Spähtrupps ausgeschickt, um die Stacheleber zu vernichten und mir über die Bewegungen der Hordentruppen Bericht zu erstatten, aber niemand ist zurückgekehrt. Sie könnten da draußen Eure Unterstützung brauchen.\n\nPatrouilliert durch die Felder und sucht die Ödnisgrunzer, die uns so viel Verdruss bereiten. Erwartet nicht, dass sie aufgeben - ihr Kriegshäuptling hat ihnen befohlen, bis zum Tod zu kämpfen.", progress = nil, completion = "Sehr gut! Vielleicht wird es uns nie gelingen, die Horde ganz aus diesen Landen zu vertreiben, aber mit einer starken Präsenz können wir ihren Kampfeswillen untergraben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25044] = {title = "Die etwas andere Diplomatie", objective = "Geht mit dem Horn der Herausforderung zum Herausforderungsring der Borstennacken im Südlichen Brachland. Lasst das Horn erschallen, um Säbelschnauze herauszufordern und tötet ihn.", description = "Ich habe meine Begegnung mit dem Tod durch die Hände der fiesen Stacheleber in dem dreckigen Dschungel nicht vergessen. Der General hat einige taktische Schläge angeordnet, aber er will keinen Völkermord begehen. Derartige Skrupel kenne ich nicht.\n\nNehmt dieses Horn, das ich während meiner Verhandlungen 'ausgeliehen' habe. Lasst das Horn innerhalb des Herausforderungsrings der Borstennacken westlich von hier erschallen - Ihr könnt ihn nicht übersehen. Ich möchte, dass Ihr Säbelschnauze, den Champion der Borstennacken, zu einem Einzelkampf herausfordert. Sein Tod vor den Augen seiner Anhänger wird sie ins Chaos stürzen.", progress = "Säbelschnauze! Ist er tot? Welche Neuigkeiten gibt es?", completion = "Eine \"Schweinokalypse\" sagt Ihr? Diese Tiere haben auf jeden Fall eine einzigartige Vorstellung von \"Einzelkampf\"!\n\nEgal, Ihr habt es gut gemacht. Jetzt, da die Stacheleber im Chaos versinken, sollte ich keine Probleme haben, die Feldkommandeure davon zu überzeugen, dass sie Streuner, die ihnen begegnen, hinrichten sollen. Der General muss gar nicht wissen, dass wir die Kampagne auf einen neuen Level angehoben haben.... Es ist besser so.", rewards = "EberkalypsenstiefelSäbelschnauzes UmhangAuf Euch wartet eine dieser Belohnungen:\n\nHerausforderungsring der Borstennacken\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25045] = {title = "Eine Linie im Schmutz", objective = "Erobert einen neutralen Hügel in den Feldern des Blutes und verteidigt ihn gegen den Gegenangriff der Horde.", description = "Aus strategischen Gründen erfordert die Kontrolle über eine Region ständige Bewachung. Schaut hier auf dieser Karte - ich habe eine Anzahl strategisch wichtiger Hügel ausgemacht, die die Allianz einnehmen muss, wenn wir den Feind unter Kontrolle behalten wollen.\n\nMeine Späher haben diese Örtlichkeiten bereits auf dem Feld markiert. Ich brauche jemanden, der die Führung übernimmt, um sie einzunehmen und Ihr seid genau <der richtige Mann/die richtige Frau> für diese Aufgabe.\n\nSucht nach neutralen grauen Flaggen auf den Hügeln im Norden, Osten und Süden von den Überresten Taurajos. Nehmt einen ein und verteidigt ihn!", progress = nil, completion = "Euer Bericht, &lt;Klasse&gt;?\n\n\n\nUnglaublich, &lt;Name&gt;! Ihr seid wahrlich ein Gewinn für die Allianz. Ich werde dafür Sorge tragen, dass meine Männer Eurem Beispiel folgen!", rewards = "Hawthornes SchildRoben des blutigen FeldesGamaschen von TaurajoIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25046] = {title = "Die Umarmung einer Tochter", objective = "Bringt Lilian Voss zu ihrem Vater im Turm am Kreuzfahrerpass.", description = "Das Flüstern fährt fort.\n\n<\"Mein Name ist Lilian Voss. Bevor ich starb, war ich Mitglied des Scharlachroten Kreuzzugs. Mein Vater, Hohepriester Voss, erzog mich, eine Waffe gegen die Verseuchten zu sein. Ich lernte Tarnung, Magie, Kampfkünste. Alles, um mich stärker zu machen. Ich habe ihm meine Kindheit geopfert.\">\n\n<\"Doch dann wollte es das Schicksal, dass ich starb und... so zurückkehrte. Mein Vater vergaß mich sofort, und als ich zu ihm zurückkehrte, befahl er meine Hinrichtung.\">\n\n<\"Kommt. Wir werden jetzt mit ihm sprechen, in seinem Turm im Nordwesten.\">", progress = nil, completion = "Von der Wiege über die Bahre in den Untod folgen wir alle unserem eigenen Weg - manche leichter als andere. Es hört sich an, als wäre der Weg dieses Mädchens Voss bis jetzt hart gewesen.\n\nHoffentlich entschließt sie sich am Ende, uns beizutreten und der Dunklen Fürstin zu folgen. Mit Macht wie ihrer könnten wir unglaubliches leisten.\n\nÜbrigens, &lt;Name&gt;... großartige Arbeit da draußen. Wenn Ihr jemals Zeit und Lust habt, habe ich vielleicht etwas Arbeit in den Pestländern für Euch.", rewards = "Derringtons LangdolchLilians StabBrustplatte des ExekutorsIhr bekommt:\n\nScharfrichterbeutel"}
MultiLanguageQuestData['de'][25047] = {title = "Zerbrochene Pantherfigur", objective = "Repariert die zerbrochene Figur mit den Fähigkeiten und den Materialien, die Euch zur Verfügung stehen.", description = "Diese völlig zerbrochene Figur wurde von ihrem letzten Besitzer beiseite geworfen. Mit den richtigen Materialien und Euren Fähigkeiten in Juwelierskunst könnte sie jedoch wieder vollständig repariert werden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFigur - Dämonenpanther"}
MultiLanguageQuestData['de'][25048] = {title = "Wiederverwertung an der Küste", objective = "Sammelt 7 Dampfdruckvorräte.", description = "Wenn wir Herrn Noggenfogger davon überzeugen möchten, mehr Gnome hier einziehen zu lassen, müssen wir ihm nur zeigen, wie nett wir sind! Und ich weiß auch schon, wie.\n\nGadgetzan ist von Piraten eingenommen worden, aber viele der Güter, die von den Schiffen geworfen wurden, sind noch intakt. Sie wurden nur weggespült. Viele davon werden südlich der Stadt angespült.\n\nSammelt für sie diese Vorräte, damit wir uns mit ihnen anfreunden! Ich werde mich darum kümmern, dass dieses böse Goblinmädchen sie nicht vor Euch an sich nimmt und verkauft.", progress = "Ihr habt alle Kisten? Lasst mich mal sehen!", completion = "Fast alles sieht noch gut aus! Was für ein Glück!\n\nDie Goblins des Dampfdruckkartells werden so froh darüber sein, ihre Ladung wieder zurückzubekommen. Und natürlich werden so gute Taten auch belohnt!\n\nWir müssen aber noch so viele andere Sachen erledigen. Fleißig, fleißig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25049] = {title = "Pfützenstampfer", objective = "Tötet 8 Gezeitenschreiter.", description = "Hier gibt es ein großes Problem! Es ist toll, dass der Ozean so weit ins Land gestoßen ist, weil Schiffe jetzt Gadgetzan ansteuern können. Aber auch ein paar üble Meeresriesen nähern sich der Stadt! Ich bin mir sicher, dass Herr Noggenfogger sich freuen würde, wenn wir uns darum kümmern.\n\nKeine Sorge, ich will nicht, dass Ihr es aus Herzensgüte macht. Tötet sie und ich werde Euch belohnen!", progress = nil, completion = "Oh, jetzt wird es hier so viel schöner werden, ohne die Gezeitenschreiter!\n\nZumindest, bis wieder welche hierher finden. Aber trotzdem, vielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25050] = {title = "Raketenrettung", objective = "Bringt Lebensraketen zu 5 Überlebenden des Dampfdruckkartells und benutzt Bomben, um 40 Blockierer der Südmeerfreibeuter zu töten.", description = "Als das Wasser über uns hereinbrach wurde das Dampfdruckpier östlich von hier komplett überflutet und nun sind dort noch immer arme Goblins, die auf Rettung warten! Die Piraten schießen auf jedes Boot, das die Docks verlässt.\n\nSie werden aber nicht damit rechnen, dass wir fliegen! Bei den Docks steht ein Heißluftballon. Wir können ihn benutzen, um die Goblins zu retten und gleichzeitig auch noch die Seeräuber ausschalten. Herr Noggenfogger wird begeistert sein!\n\nGeht zu den Docks und macht den Heißluftballon startklar. Ich komme gleich hinterher, ja? Ich muss nur noch die Raketen holen...", progress = nil, completion = "Das war toll! Es scheint, als seien die meisten der Goblins, denen wir geholfen haben, sicher an Land gekommen, ohne von den Bomben erwischt zu werden. Jetzt haben wir es dem Goblinmädchen aber gezeigt!\n\nHier ist eine ganz besondere Belohnung für Euch, mein Lieber!", rewards = "Nasmiras SuppenrührerGeborgener DampfdruckhelmMisslungener Prototyp einer LebensraketeAuf Euch wartet eine dieser Belohnungen:\n\nBlindgängerbombe\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25051] = {title = "Graunebelausrottung", objective = "Zerstört 8 Graunebeleier in den Graunebelhöhlen.", description = "Die Spinnen, die sich in den Graunebelhöhlen im Nordwesten tummeln, sind eine weitere ernste Bedrohung für uns hier. Die Oger kommen zwar locker mit ihnen zurecht, aber uns auf sie zu konzentrieren, während die Streitkräfte von Theramore in der Gegend lauern, wäre ein tödlicher Fehler.\n\nIch brauche jemanden, der die Eier in den Graunebelhöhlen zerstört, um dieser Plage ein Ende zu setzen. Ihr findet die Eier im tiefsten Teil der mit Netzen übersäten Minen... bei ihren Wächtern.", progress = nil, completion = "Das ist eine große Erleichterung, &lt;Klasse&gt;. Vielen Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25052] = {title = "Die Truhe des toten Mannes", objective = "Tötet 15 Piraten der Südmeerfreibeuter.", description = "Oh du meine Güte, man kann wirklich sehen, dass die Schlacht mit den Piraten eine wilde Schlacht ist. Wir werden sicherstellen, dass sie Gadgetzan und unseren neuen Gnomenwohnort nie wieder belästigen werden!\n\nWir werden sie töten!\n\nWollt Ihr uns helfen? Wir müssen wirklich sicherstellen, dass wir mehr von ihnen töten als Grünnase da drüben mit ihren furchtbaren Helfern. Das wäre wirklich sehr hilfreich!", progress = nil, completion = "Gute Arbeit! Wir räumen hier aber wirklich richtig auf!", rewards = "SüdmeerkapuzeMeinertreugamaschenHandschuhe des LangenasendrehersGesäuberte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25053] = {title = "Niederbrennen!", objective = "Benutzt den brennenden Rum, um die nordwestliche Hütte, die nordöstliche Hütte und die südwestliche Hütte niederzubrennen.", description = "Dieser Ort wäre für uns Gnome bestimmt eine tolle Heimat, wenn es nur nicht so alt, schmutzig und voller Piraten wäre! Mit den Piraten sind wir einen Schritt weiter, aber hässlich und schmutzig ist es immer noch.\n\nIch meine, kein respektierlicher Gnom würde jemals in so hässlichen Behausungen wie diesen Hütten wohnen! Also, nehmt diese Flasche mit dem hochentzündlichen Rum und brennt diese hässlichen Hütten nieder!", progress = nil, completion = "Ist das nicht wunderschön anzusehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25054] = {title = "Beute plündern", objective = "Sammelt 10 Stück Piratenbeute.", description = "Es ist so verschwenderisch, wie die Piraten ihre Goldschätze überall herumliegen lassen. Man könnte das Zeug sogar für praktische Sachen hernehmen! Man könnte es schmelzen und Draht herstellen, oder immanente Abwehrmatrizen, oder es einfach an andere dumme Völker verkaufen, die Gold kaufen, um es zu haben.\n\nOh, und wo ich gerade von anderen dummen Völkern spreche: die geizigen Goblins werden versuchen, alles an sich zu reißen. Das dürfen wir nicht zulassen! Geht, und sammelt die Schätze für Gnomeregan!", progress = "Ich hoffe, Ihr versucht nicht, etwas davon für Euch selbst zu behalten, Dummerchen! Mit dieser Brille kann ich den Inhalt Eurer ganzen Tasche sehen.\n\nUnd Eurer Rüstung.", completion = "Fantastisch! Damit kann man genug Draht für eine ganze Armee herstellen!\n\nWas für ein Glück!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25056] = {title = "Grausige Grizzlys", objective = "Beschafft 5 Bälge eines verseuchten Braunbären.", description = "Habt Ihr die verseuchten Braunbären gesehen, die westlich von hier herumstreunen? Diese Bälge... so entsetzlich, so krank, so... perfekt!\n\nBringt mir 5 davon. Ich habe eine Idee für ein Gift gegen die Geißel, das garantiert wirken wird!", progress = "Mal sehen... habt Ihr genug Bälge?", completion = "Zitters, Ihr habt es wieder mal geschafft. Die sind perfekt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25057] = {title = "Werft sie in Ketten", objective = "Sprecht mit Plünderern von Taurajo in den Überresten von Camp Taurajo und verhaftet sie. Benutzt die Handschellen von Nordwacht, um 5 verwundete Plünderer zu überwältigen.", description = "Unsere Politik, nicht-gewalttätige Kriminelle aus den Verliesen von Sturmwind zu rekrutieren, rächt sich gerade gewaltig, <Name>. Einige der weniger moralischen Soldaten sind seit unserem Sieg in Taurajo fahnenflüchtig und plündern die Überreste der Stadt.\n\nDas ist ein Disziplinverlust. Schlimmer noch, die Entweihung ihrer Häuser spornt unsere Feinde an, noch verbissener zu kämpfen, dabei sollte unser eigentliches Ziel doch Frieden heißen.\n\nNehmt diese Handfesseln und führt die Plünderer von Taurajo der Gerechtigkeit zu. Sprecht zunächst mit ihnen, aber wahrscheinlich müsst Ihr Gewalt anwenden, um sie zu bändigen.", progress = "Ist die Situation in Taurajo unter Kontrolle?", completion = "Gut gemacht, &lt;Name&gt;. Einige der Plünderer sind bereits zurückgekrochen und haben um Gnade gebeten. Ich lasse sie eine Weile in dem Verlies der Nordwacht schmoren.\n\nDanke, dass Ihr geholfen habt, die Disziplin in den Rängen aufrecht zu erhalten. Für eine Armee ist es wichtig, als Soldaten wahrgenommen zu werden und nicht als gemeine Banditen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25058] = {title = "Minenentschärfung nach Goblinart", objective = "Sprengt 10 Landminen.", description = "Die Fallschirmjäger haben den Strand vermint!\n\nDer Kriegshäuptling hat mich gefragt, ob wir etwas dagegen tun können. Ich habe ihm gesagt \"Aber klar können wir!\". Ich dachte mir, Ihr könntet ja diesen Beutel mit Granaten nehmen und die Landminen aus sicherer Entfernung sprengen.\n\nSo regeln wir die Dinge, nicht wahr?!", progress = "Boss, könnt Ihr noch einmal da runter gehen und noch ein paar mehr sprengen?\n\nDanke!", completion = "Eins zu Null für die Goblins! Dumme Zwerge und Gnome.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25059] = {title = "Die Taurajo Informationen", objective = "Durchsucht die Überreste von Camp Taurajo nach 3 Geheiminformationen der Taurajo.", description = "Der General ist von den Plünderern in Taurajo viel zu sehr abgelenkt. Er ist viel zu weich! Wir müssten uns auf unseren Schlag gegen die Horde konzentrieren.\n\nEs gibt wertvolle Erkenntnisse, die gefährdet werden, wenn wir die Überreste von Camp Taurajo weiter brennen lassen. Während Ihr den Laufburschen für den General macht, sucht nach Karten oder Notizen. Ich verstehe die Orcsprache ein wenig - ich werde das, was Ihr findet schon verstehen können.", progress = "Habt Ihr die Ruinen schon durchsucht?", completion = "Was habt Ihr für mich ausgegraben? Hmm. Interessant. Die Notiz aus Orgrimmar deutet darauf hin, dass sich ein Wechsel in der Hordenführung anbahnt. Ich denke, dass da Köpfe rollen werden nach dem, was wir Taurajo angetan haben.\n\nWas ist das? Ein Todesurteil für den General hier! Das ist gut zu wissen... Sehr gut zu wissen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25060] = {title = "Definiert \"verrückt\"", objective = "Tötet 10 verrückte Überlebende.", description = "Wir haben erfahren, dass vor einiger Zeit ein Schiff der Goblins hier am Strand Schiffbruch erlitten hat. Es gab nur wenige Überlebende, die sich jetzt alleine durchschlagen. Wir hatten gehofft, dass sie wenigstens einigermaßen bei Verstand sind, sodass wir sie befragen können.\n\nAber wir fanden nur einen Haufen Goblins des Bilgewasserkartells, die vollkommen verrückt, wahnsinnig und manisch gewalttätig waren... und das noch mehr als sonst.\n\nIn Kürze werden sie nutzlos und gefährlich sein. Wir können Gnomeregan am besten dienen, wenn wir so viele von ihnen wie möglich vernichten.", progress = nil, completion = "Eure Berichte über ihr Verhalten sind wahrlich verstörend… aber auch ein wenig amüsant.\n\nWenn doch nur diese alte Hexe Schredderschreck auf diesem Schiff entkommen wäre…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25061] = {title = "Landende", objective = "Sprecht mit Kelsey Stahlfunken an der Station Stahlfunken.", description = "Psst! Hey! Kommt näher her, Ihr Narr! Oder soll ich Eure Gedanken lesen? Oh... Egal, kommt trotzdem näher her!\n\nIhr habt tolle Arbeit geleistet, die Ziele Gnomeregans zu realisieren! Und Ihr habt wirklich richtig gut so getan, als seid Ihr nur am Geld interessiert gewesen, einfach fantastisch. Jetzt könnte Kelsey Stahlfunken aber mehr von Eurer Hilfe gebrauchen.\n\nSie ist weiter gezogen... und hat mich gebeten, Euch zu sagen, dass Ihr sie weit im Süden, in Landendestrand zu finden ist. Ich würde sie nicht warten lassen!", progress = nil, completion = "Es wundert mich, dass Pfauentraum in der Lage war, meinen einfachen Anweisungen Folge zu leisten. Noch dazu musste er auch seinen Mund dabei halten.\n\nAber es tut auch wirklich gut, Euch wiederzusehen, &lt;Name&gt;. Jetzt, da diese Scharade vorüber ist, kann ich Euch zeigen, wie die Gnome sich hier um ihre Angelegenheiten kümmern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25062] = {title = "Warum wir hier sind", objective = "Sucht in den Bilgewässer Schließkisten nach Hinweisen.", description = "Gnomeregan hat in Erfahrung gebracht, dass die Bilgewassergoblins der Horde eine Bruchlandung auf einer unbewohnten Insel nahe Kalimdor überlebten, bevor sie in Durotar ankamen. Wir kamen ursprünglich her, um zu untersuchen, welche Techniken und Technologien diesem hoffnungslosen Narrenpack erlaubten, solch raue Bedingungen zu überleben.\n\nWährend die Goblins völlig ahnungslos sind, sollten wir immer noch herausfinden, was genau hier passiert ist. Sucht am Strand nach Wrackteilen und Habseligkeiten und bringt mir alles, was Euch irgendwie relevant erscheint.", progress = "Was habt Ihr gefunden?", completion = "&lt;Kelsey nimmt das Tagebuch und blättert es vorsichtig durch.&gt;\n\nIch muss mir wirklich das Lachen verkneifen. Das ist so typisch. Die Tölpel wissen nicht einmal, dass sie in Kalimdor sind!\n\nAber auf den späteren Seiten... hier könnte etwas Bedeutsameres vonstatten gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25063] = {title = "Verschildkrötet", objective = "Erlangt von einem Brandungsgleiter den von einer Schildkröte verdauten Schlüssel.", description = "Wir brauchen das Objekt, von dem in dem Tagebuch geschrieben wird. Wir brauchen es unbedingt. Es aus der Truhe zu entnehmen wäre kein Problem, wenn das Objekt selbst nicht beeinträchtigt und instabil wäre. Die Truhe mit Gewalt zu öffnen könnte furchtbare Folgen haben.\n\nZum Glück wissen wir, wo der Schlüssel ist... Zumindest statistisch gesehen. Am östlichen Ende des Strandes sind viele Meeresschildkröten. Eine von ihnen könnte den Schlüssel haben.", progress = "Hoffentlich ist er trotz Eurer Schildkrötenzerstörungswut noch ganz.", completion = "Nun gut, dieser Tag wird besser und besser! Ich könnte vielleicht noch lächeln später!\n\nNur, wenn Ihr nicht schaut natürlich. Davon habt Ihr schon genug gesehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25064] = {title = "Moraya", objective = "Sprecht mit Moraya.", description = "Moraya sucht nach Hilfe mit den Raptoren. Ihr solltet mit ihr auf der anderen Seite der Dunkelspeerfeste sprechen, wenn Ihr Gelegenheit dazu findet.", progress = nil, completion = "Heda, Süßer. Vol'jin hat Euch geschickt? Es ist so süß von ihm, an mich zu denken.\n\nIch kann auf jeden Fall Hilfe gebrauchen, aber Ihr müsst noch ein ganzes Stück laufen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25065] = {title = "Ein Schlag ins Gesicht", objective = "Beschafft die Truhe von Hackvisage.", description = "Es ist an der Zeit, die Sache zu einem Ende zu bringen. Nach unseren Erkenntnissen ist dieses mysteriöse Objekt im Besitz des \"schlauen\" Schlägers, der im Tagebuch beschrieben wurde. Wir wissen nicht genau, was mit diesem Wesen geschehen ist, also solltet Ihr vorsichtig sein.\n\nDieser ... \"Hackvisage\" versteckt sich in den Hügeln, in der Nähe des Ortes, an dem diese Goblins ihre Toten begraben. Haltet nach dem Friedhof Ausschau. Er sollte sich direkt dahinter aufhalten.", progress = "Seid vorsichtig mit dem Inhalt der Truhe.", completion = "Gut gemacht, &lt;Name&gt;. Der Inhalt dieser Truhe wird unser Wissensarchiv in Gnomeregan sicher beträchtlich erweitern. Ich glaube, Ihr habt Euch eine Belohnung verdient.", rewards = "Hackvisagen Knüppler\"Geschickte Armschienen\"Dolch der IdenAuf Euch wartet eine dieser Belohnungen:\n\nVerdienstabzeichen aus Gnomeregan\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25066] = {title = "Der Stolz von Kezan", objective = "Schießt 10 Tarnkappenflugzeuge von Gnomeregan vom Himmel.", description = "Das ist lächerlich! Diese Gnome wissen einfach nicht, wann man aufhören muss!\n\nJetzt ist der Stolz der Goblins gefragt! <Name>, springt in den Stolz von Kezan und zeigt ihnen, was das bedeutet!\n\nGebt mir Bescheid, wenn Ihr bereit seid.", progress = "Was macht Ihr denn hier? Hoch in die Lüfte mit Euch und holt sie vom Himmel.", completion = "JA!", rewards = "SchützenhandschuheFetzen eines GnomenfallschirmsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25067] = {title = "Donnerkuppel: Der Ginormus!", objective = "Besiegt Ginormus.", description = "Die Regeln sind einfach: zwei Männer betreten den Ring, einer - nein, wartet. Manchmal sind da auch Frauen.\n\nAlso, zwei Kämpfer betreten den Ring, einer - nein, ach, manchmal sind es mehr als zwei, und dann kommen auch mehr wieder raus...\n\nAlso, die einzige Regel ist es, in der Donnerkuppel zu bleiben! Es gibt keine anderen Regeln!\n\nZuerst tretet Ihr gegen den größten, heftigsten Banditen der Wüstenläufer an. Das wird ein Kampf zum Aufwärmen oder ein Blutbad. Und Ihr könnt entscheiden!", progress = nil, completion = "Ein beeindruckender Anfang. Macht Euch auf mehr gefasst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25068] = {title = "Bruchstücke der Vergangenheit", objective = "Sammelt 5 Juwelen der Irdenen.", description = "Die Kreaturen, die in den Ruinen umherwandern sind Irdene - die Urahnen der Zwerge, die von den Titanen erschaffen wurden, um die Welt zu formen.\n\nDie Struktur der ursprünglichen Irdenen brach bereits vor Tausenden von Jahren zusammen und sie fielen dem Chaos anheim; die neu entdeckten scheinen ihnen darin zu ähneln. Wir sollten diese verwirrten und instabilen Konstrukte nutzen.\n\nBegebt Euch in die Ruinen und zerstört die Irdenen; sammelt die Juwelen, die sich in ihnen befinden. Ihre magischen Energien werden sowohl wertvoll als auch für unsere Studien nützlich sein.", progress = "Handhabt sie sorgsam, <Name>. Sie sind so alt wie die Welt selbst.", completion = "Wunderbar. Der Gedanke, dass sie von den Schöpfern dieser Welt hergestellt wurden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25069] = {title = "Die Geheimnisse Uldums", objective = "Sucht in der Vorkammer von Uldum nach einem unzerstörten Artefakt.", description = "Wir sind bereit, die Vorkammer zu betreten, <Name>. Dies ist ein einzigartiger Augenblick.\n\nAus den Schriften, die Ihr mir gebracht habt, glaube ich entnehmen zu können, dass es sich bei diesen Ruinen um den ehemaligen Haupteingang nach Uldum handelt. Die Erdbeben, die die Tore geöffnet haben, haben mit ziemlicher Wahrscheinlichkeit die Tunnel zerstört, aber wir können trotzdem sicherlich noch unglaubliche Sachen hier finden.\n\nSucht die Ruinen nach allem ab, das nicht zerstört scheint, damit wir es untersuchen können. Das Entdeckungsfieber wird uns packen!", progress = nil, completion = "Die Truhe liegt ungestört hier und wurde seit Tausenden von Jahren nicht mehr geöffnet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25070] = {title = "Was im Inneren ist", objective = "Besiegt den Wächter der Vorkammer.", description = "Als Ihr Eure Hand auf die Truhe legt ertönt ein leises Rumpeln. Ihr hört das Geräusch einer schleifenden Bewegung hinter Euch wiederhallen, als sich die Truhe von alleine schließt.\n\nEtwas nähert sich!", progress = nil, completion = "Die Truhe öffnet sich nun wieder mit einem schleifenden Geräusch und im Rest der Vorkammer ist Stille eingekehrt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25072] = {title = "Eine Frage der Goblinehre", objective = "Rettet 8 gefangene Goblinkäferjäger aus den Kokons der Hazzali.", description = "Wir haben hier nicht einfach unser Lager aufgeschlagen, um lustige Lieder über Gnomen zu singen und mit gefährlichen Maschinen zu spielen. Meine Männer haben seit über einer Woche versucht, diesen Schwarmbau auszuräuchern! Das Problem ist, dass wir so viele Verluste hinnehmen mussten, dass die Käfer im Vorteil sind.\n\nZum Glück fressen die Käfer nicht gerne Goblins. Oder sie heben das Beste bis zum Schluss auf. Zumindest sind fast all meine Männer immer noch in Kokons eingesponnen. Ihr müsst sie retten!", progress = nil, completion = "Vielen Dank für Eure Hilfe! Das lag mir wirklich schwer auf der Seele. Wenn man seine Männer verliert, verliert man auch die Arbeitskraft. Und die Moral. Und die Waffen. Und die Magazine, die man diesem Typ ausgeliehen hat.\n\nIhr wisst schon, was ich meine.", rewards = "KäferjägergürtelGeliehene ArmschienenDose des GoblinleckerlisAuf Euch wartet eine dieser Belohnungen:\n\nGefährliches Maschinenteil\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25073] = {title = "Sen'jin", objective = "Meldet Euch bei Meister Gadrin in Sen'jin.", description = "Ihr macht Euch sehr gut für jemanden, der noch so jung ist. Ich habe keine Zweifel, dass Ihr Euch einen großen Namen machen werdet.\n\nGeht jetzt, nach Nordwesten, durch die Untiefen nach Sen'jin. Dort werdet Ihr auf Meister Gadrin treffen. Er hat sicherlich die eine oder andere Aufgabe für Euch, bevor Ihr Euch wirklich weit in die Wildnis von Durotar wagt.\n\nBitte denkt daran, <Name>, wir mögen mit dem jungen Höllschrei nicht immer einer Meinung sein, doch seine Absichten sind edel, und es ist sehr wichtig, dass wir eine vereinte Horde bleiben. Macht die Dunkelspeere stolz.", progress = nil, completion = "Willkommen, junger &lt;Volk&gt;. Ihr kommt mit glühenden Empfehlungen, Mann. Es ist gut, Euch endlich in Person zu treffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25074] = {title = "Bei Triumph sehen wir uns wieder", objective = "Meldet Euch bei Kommandant Roberts in der Triumphfeste im Südlichen Brachland.", description = "Zum Teil verdanken wir Euren Bemühungen, dass wir die Situation hier stabilisiert haben. Wir müssen unsere Aufmerksamkeit jetzt nach Süden auf die Triumphfeste richten.\n\nDie Triumphfeste ist der Schlüssel zu unserer Operation im Brachland - die lebensnotwendige Landverbindung zwischen Nordwacht und Theramore.\n\nIch packe meine Sachen und mache mich dann allein auf den Weg. Meldet Euch bei Kommandant Roberts in der Feste und ich werde Euch dort bald wiedertreffen. Zusammen werden wir die Frontlinie sichern!", progress = nil, completion = "Habt Ihr es schon gehört? Der General ist nie angekommen!\n\nEr wurde da draußen wie ein Hund getötet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25075] = {title = "Teilejagd", objective = "Sammelt 8 Teile Belagerungsmaschinenschrott in der Kriegsnarbe im Südlichen Brachland auf.", description = "Diese sperrigen Belagerungsmaschinen der Zwerge sind nicht für den Nahkampf in der engen Kriegsnarbe ausgelegt.\n\nIch habe einige neue Entwürfe, die ich gern ausprobieren würde, aber erst einmal benötige ich einige Ersatzteile. In der Kriegsnarbe stehen reichlich Wracks herum. <Ein unternehmungslustiger/Eine unternehmungslustige:c> <Klasse> wäre jetzt ideal, um sie zurückzuschleppen.\n\nDas seid Ihr, <Name>. Ich spreche von Euch.", progress = "Was habt Ihr für mich?", completion = "Ooh, schaut mal! Ein fast vollständiger Auspuffkrümmer, ein Verteilerkasten, ein funktionierendes Sperrdifferential... Ihr habt wirklich Ahnung von Schrott, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25079] = {title = "Pulverspielchen", objective = "Besiegt einen Pionierspezialisten in der Nähe der Kriegsnarbe und bringt ein Fass mit Spreng-und-Weg-Pulver an Euch.", description = "Unsere Ladung Salpeter aus Düstermarschen wurde aufgehalten. Das bedeutet, wir können hier kein Schwarzpulver mehr herstellen.\n\nAber ich kann unsere Bewaffnung umrüsten, damit sie mit dem Spreng-und-Weg-Pulver der Goblins funktionieren. Es ist instabil, gefährlich, schädlich für die Haut und gesundheitsschädlich, wenn man es verschluckt... aber ich glaube, ich könnte es einsatzfähig machen.\n\nBringt mir ein Fass von dem Zeug, indem Ihr einen dieser Pionierspezialisten der Goblins angreift, die unsere Mauern angreifen.", progress = "Habt Ihr schon ein Fass mit Spreng-und-Weg-Pulver?\n\nWenn Ihr eins in die Hände bekommt - nicht schütteln!", completion = "Großartig! Stellt das Fass genau hier ab. Ich werde einige Ladungen abmessen, sobald ich meinen Ganzkörperschutzanzug angezogen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25080] = {title = "Batterien nicht eingeschlossen", objective = "Besorgt einen summenden Elektromagen von einem Donnerkopf im Südliches Brachland.", description = "Okay! Mit den Ersatzteilen, die Ihr für mich besorgt habt, habe ich den groben Rahmen für mein vielseitiges neues Angriffsfahrzeug erstellt. Jetzt brauche ich nur noch eine kompakte Energieversorgung.\n\nMir ist aufgefallen, dass die einheimischen Wildtiere hier ganz schön zuschlagen - elektrostatisch gesprochen. Könnt Ihr Donnerköpfe in der Nähe jagen und mir einen intakten Elektromagen besorgen? Möglicherweise müsst Ihr ein paar töten, bevor Ihr eine brauchbare Drüse findet.", progress = "Es muss doch ein ungeheurer evolutionärer Vorteil sein, wenn man Blitze abfeuern kann. Aus dem Gesicht.", completion = "&lt;Der Magen versetzt Mizzy einen Schock, als Ihr ihn ihr überreicht und sie fällt zu Boden.&gt;\n\nOh, OH! Das ist fies! Ich liebe es!", rewards = "Fahrradeysche AbschirmungMizzys LatzhoseKolbenhammergewehrGlacéhandschuhe des DonnerkopfsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25081] = {title = "Anspruch auf die Kriegsnarbe erheben", objective = "Geht zu der Kriegsnarbe. Findet die Flagge und tötet 10 Ödnisräuber\n\nDie Flagge einzunehmen wird allen Allianzspielern in der Narbe einen Vorteil im Kampf gewähren.", description = "Die Horde hat uns hier durch den Kampf, den sie von ihrer Feste westlich von hier führen, zum Stillstand gebracht. Die Kämpfe halten an, obwohl das Land unter unseren Füßen auseinanderbricht.\n\nJemand muss die Pattsituation aufheben! Ihr müsst Euch für mich in die Kriegsnarbe vorwagen und meinen Leuten helfen, die Hordengegner dort zu zerschmettern.\n\nIm Zentrum der Narbe befindet sich eine Flagge, die anzeigt, wer gerade über sie herrscht. Findet die Flagge. Es wird sich für Euch lohnen, die Narbe für die Allianz einzunehmen, wenn es nicht schon jemand anders getan hat.", progress = nil, completion = "Großartige Arbeit, &lt;Name&gt;! Meine Leute berichten mir über einen Durchbruch. Ihre Feste wird nicht mehr lange überleben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25082] = {title = "Die Käfer beseitigen", objective = "Wendet den Eimer mit brennendem Pech auf Silithidenhügel außerhalb der Triumphfeste an und tötet 10 Silithidschwärmer, wenn sie herauskommen.", description = "Warum das Oberkommando der Meinung war, dass es eine gute Idee ist, auf einem Silithidenhügel eine Feste zu errichten, werde ich nie verstehen. Diese kleinen Mistviecher untergraben unsere Befestigungsanlagen und halten uns auf. Wir müssen sie ausräuchern!\n\nNehmt diesen Eimer mit brennendem Pech und schüttet das Pech über den Silithidenhügeln vor dem Haupttor aus. Sie sehen wie Sandhügel aus. Tötet alles, was herauskommt, aber seid vorsichtig, <Name>, diese gemeinen Viecher werden wahrscheinlich herausschwärmen, wenn Ihr die Hügel in Brand steckt.", progress = "Wie läuft der Kampf, <Name>?", completion = "Das sollte unsere Bugprobleme für eine Weile beheben - sie dürften Schwierigkeiten haben, sich da herauszugraben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25084] = {title = "Wachsende Bedrohung", objective = "Tötet 13 Stacheleber der Klingenmähnen.", description = "Einen Moment mal, <Klasse>.\n\nWir haben hier mehr Probleme, als nur das Ende der Welt, wie wir sie kennen. Unser Wachtposten hier wird von den Stachelebern bedroht. Klar, solange sie in ihrem Kral blieben, hatten wir kein Problem damit, sie einfach in Ruhe zu lassen, aber jeden Tag rücken sie weiter auf unser Lager vor.\n\nMahka, ihr grünes Herz sei gesegnet, würde mir nie verzeihen, wenn ich hinausginge und ihnen selbst die Schädel einschlüge, aber wenn Ihr helfen könntet, diejenigen, die in der Nähe des Lagers herumstreunen, zurückzudrängen, würde ich das sehr begrüßen.", progress = nil, completion = "Euch gebührt mein Dank, wenn nicht sogar der Dank des gesamten Irdenen Rings.\n\nVielleicht werden wir eines Tages einen Weg finden, das mit diesen Schweinen auszudiskutieren, aber wir können das Land nicht heilen, wenn wir im Schlaf getötet werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25085] = {title = "Quetschzahn", objective = "Tötet Quetschzahn.", description = "Una hat viel Zeit in Camp Taurajo verbracht. Sie hat mir von einem Stacheleber erzählt, der dort gefangen gehalten wurde. Sein Name war Quetschzahn. Für einen Stacheleber war er ziemlich gerissen.\n\nIch habe mir den Kopf zerbrochen, warum die Stacheleber in letzter Zeit so aufmüpfig sind und möglicherweise ist Quetschzahn lebend aus Taurajo entkommen. Wenn ja, ist er derjenige, der ihnen sagt, wo's langgeht.\n\nIn den Hügeln im Nordwesten befindet sich eine große Hütte. Wenn Ihr Quetschzahn dort findet, streckt ihn nieder.", progress = nil, completion = "Welch eine Erleichterung. Vielleicht wird sich der Rest von ihnen jetzt zurückhalten. Je weniger hier gekämpft wird, desto besser.", rewards = "Geschundener ZahnArmschienen aus StacheleberfellStab von RoterdeAuf Euch wartet eine dieser Belohnungen:\n\nDorns Amulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25086] = {title = "Flammensteinspitze", objective = "Sucht nach Dorn Roterde an der Flammensteinspitze im Südlichen Brachland.", description = "Könnt Ihr mir einen großen Gefallen tun, <Name>? Der Onkel meiner Schwägerin ist Mitglied im Irdenen Ring und er befindet sich hier im Brachland, um die Auswirkungen des Kataklysmus an der Flammensteinspitze zu erforschen. Er sagt, sein Lager ist von Stachelebern umzingelt und ich mache mir Sorgen, dass sie sein Lager überrennen könnten.\n\nWürdet Ihr einmal für mich nach Dorn Roterde schauen? Ich möchte auf keinen Fall, dass ihm ein Leid geschieht, gerade weil er ein Familienmitglied ist und so.", progress = nil, completion = "Wie bitte? Der kleine Logan meint, ich brauche Schutz?\n\nIch bin derjenige, der beschützt!\n\nDie Stacheleber sind kurz davor, Amok zu laufen. Sie haben den gesamten Süden abgewürgt und jetzt stehen nur noch wir ihnen im Weg.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25087] = {title = "Meldet Euch bei Doppelzopf", objective = "Liefert den Bericht von der Front bei General Doppelzopf ab, der im Südlichen Brachland auf Patrouille ist.", description = "Die Allianz schuldet den Zwergen von Bael Modan etwas, die einige der ältesten Befestigungen hier im Brachland gebaut haben.\n\nIhr Kommandant, General Doppelzopf, ist wahrhaft unerschütterlich. Einer unserer Besten. Er ist südlich von hier auf Patrouille und hält die Horde in Atem.\n\nIch möchte ihn über die Situation auf dem Laufenden halten, damit wir unseren nächsten Schritt planen können. Könntet Ihr diesen Bericht von der Front zu ihm hinaus bringen?", progress = "Hrm, Neuigkeiten aus der Feste? Naja. Spuckt es aus!", completion = "&lt;Der General liest den Bericht und nickt zustimmend, als er von der Kriegsnarbe liest.&gt;\n\nIhr habt Euch hier im Brachland durchaus einen Namen gemacht, &lt;Name&gt;. Aber Roberts geht nicht weit genug. Wir brauchen einfach einen entscheidenden Sieg.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25089] = {title = "Nach den Gräbern", objective = "Sprecht mit Todeswache Saltain in Todesend in Tirisfal.", description = "Darnell hat mir berichtet, dass Ihr Euch schon kennengelernt habt. Das ist gut, weil ich Euch beide nach Todesend schicken werde. Eure Arbeit hier ist abgeschlossen.\n\nSprecht mit Todeswache Saltain nördlich von hier. Er wird Euch mehr verraten können.", progress = nil, completion = "Die Val'kyr waren in letzter Zeit sehr beschäftigt mit neuen Wiederbelebungen. Allein seit heute Morgen habe ich ein Dutzend neuer Ankömmlinge den Hügel herunterlaufen sehen.\n\nIhr seid allerdings der vielversprechendste &lt;Klasse&gt;, den ich heute gesehen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25090] = {title = "Eine eitrige Aufgabe", objective = "Bringt 7 eitrige Klauen zu Todeswache Dillinger auf dem Verlassenen Anwesen.", description = "Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen diese Gegend heim.\n\nIch brauche jemanden, der die faulenden Toten und verheerten Kadaver zurückschlägt, die den kleinen Hof übernommen haben. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.", progress = "Habt Ihr die Aufgabe erledigt, die ich Euch auftrug? Habt Ihr die eitrigen Klauen?", completion = "Gut gemacht. Es hat Spaß gemacht, Euch zuzusehen, wie Ihr diese Untoten zu Brei geschlagen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25091] = {title = "Sandmarterwache", objective = "Sprecht mit Trenton Lichthammer in Sandmarterwache.", description = "Wenn Ihr nach mehr Arbeit sucht, dann hab ich was für Euch.\n\nIch kenne einen Elfen namens Trenton Lichthammer, der seit Jahren von den Sandtrollen in der Nähe von hier besessen ist. Er ist darauf festgefahren, eine Art magisches Schwert der Trolle zu finden und vor Kurzem hat er tatsächlich Helfer gefunden, die mit ihm zum Suchen zur Sandmarterwache sind.\n\nMeine letzte Information ist, dass sie die Trolle verjagt und ein Lager errichtet haben. Sucht westlich von hier nach ihnen, in der Nähe von Zul'Farrak.", progress = nil, completion = "Marin schickt Euch? Ich bin über seine Hilfe sehr dankbar.\n\nIch bin hier, um Sul'thraze zu finden. Wenn Ihr mir helfen wollt, so sprecht mit Mazoga... er war bisher sehr hilfsbereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25093] = {title = "Die Köpfe des SI:7", objective = "Sammelt die Köpfe von Kommandant Arrington, Dunkelklinge Cyn und Alexi Stummheuler.", description = "Diese Orcs an der Küste wurden von der Allianz kaltblütig ermordet. Wir haben nichts getan, um sie zu provozieren.\n\nIhr Tod soll nicht ungesühnt bleiben, <Name>. Werdet Ihr für Gerechtigkeit sorgen?\n\n<Es scheint, als könne Aggra ihre Wut kaum zurückhalten.>\n\nUnten am Strand halten sich drei Anführer des SI:7 auf. Bringt mir ihre Köpfe!", progress = "Habt Ihr der Gerechtigkeit Genüge getan?", completion = "Vielen Dank, &lt;Name&gt;. Endlich können die Seelen der Gefallenen Ruhe finden.", rewards = "Aggras SchärpeSilbertablettIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25094] = {title = "Donnerkuppel: Zumonga!", objective = "Besiegt Zumonga.", description = "Ausgezeichnet, gut gemacht! Ihr werdet hier aber nicht nur einfache Menschen bekämpfen!\n\nEuer nächster Gegner ist ein ganz heftiger... Nehmt Euch vor seiner Rechten in Acht. Und seiner Linken. Also überhaupt vor seinen Fäusten.", progress = nil, completion = "Nicht schlecht. Ihr seid aber noch nicht fertig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25095] = {title = "Donnerkuppel: Sarinexx!", objective = "Besiegt Sarinexx.", description = "Ich hoffe, Ihr seid bereit für Euren nächsten Gegner, <Name>. Nur ein Fehler entspricht einem schmerzvollen, sofortigen Tod! Aber genau dafür zahlen die Leute, nicht wahr?\n\nIch hoffe, Ihr habt kein Problem mit Insekten...", progress = nil, completion = "Beeindruckend. Nur wenige können einem Silithidenhäscher gegenüberstehen und auch besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25098] = {title = "Der Kriegshäuptling braucht Euch", objective = "Sprecht mit Thrall am Spähposten des Kriegshäuptlings auf den Verlorenen Inseln.", description = "Thrall hält sein Wort und bringt uns auf den richtigen Weg, um unser Volk zu retten. Er will mit Euch sprechen.\n\nViel Erfolg, <Name>. Unser Leben liegt in Eurer Hand.", progress = nil, completion = "Und wieder habt Ihr uns geholfen, unseren gemeinsamen Feind zu überwältigen, die Allianz.\n\nJetzt ist es an der Zeit, dass wir Euch helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25099] = {title = "Borgt Euch Bastia aus", objective = "Sprecht mit Kilag Blutmaul an der Stillen Küste auf den Verlorenen Inseln.", description = "Geht zurück zur Küste und sagt Kilag, dass Ihr Euch in meinem Auftrag Bastia ausborgen sollt. Der Panther weiß, wo Eure Freunde gefangen gehalten werden.\n\nGeht jetzt. Ich werde Euch wiedersehen, bevor wir unsere Initiative gegen den Handelsprinz einleiten.", progress = nil, completion = "Natürlich könnt Ihr Euch Bastia ausborgen. Das heißt, wenn sie sich das gefallen lässt.\n\n&lt;Kilag zwinkert.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25100] = {title = "Aufsitzen!", objective = "Sprecht mit Slinky Scharfklinge an den Himmelsfällen auf den Verlorenen Inseln.", description = "Bastia bringt Euch sicher dorthin, wo Ihr hin wollt, Goblin.", progress = nil, completion = "&lt;Name&gt;?! Nettes Kätzchen!\n\nWir haben nicht viel Zeit. Vielleicht ist Euch ja schon aufgefallen, dass der Vulkan Feuer spuckt?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25102] = {title = "Keine Bullen", objective = "Tötet 4 Landbeberkodos und 1 Landbeberbulle im Südlichen Brachland.", description = "Doppelzopfs Patrouillengänge bringen uns jedes Mal in große Gefahr. Wenn es nicht die Hinterhalte der Horde sind, ist es ein blitzartiger Überfall der Stacheleber.\n\nDas Problem sind diese lausigen Landbeberkodos. Riesige laufende Mauern aus Fell, bei denen die Erde bebt... Wir können einen Hinterhalt weder hören noch sehen, wenn er sich hinter unserem Rücken nähert.\n\nGeht und jagt ein paar von ihnen in die Flucht. Wenn Ihr einige von ihnen tötet, wird die Herde wohl wieder in den Süden ziehen und nicht länger auf meinen Nerven herumtrampeln.", progress = nil, completion = "Ich dachte, Ihr steckt vielleicht hinter den Staubwolken, die ich im Osten sah. Gute Arbeit! Diese Bullen sind nicht feige.", rewards = "Kodoabweisende SchulternLandschüttlergamaschenSteinwurfschwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25103] = {title = "Schmugglerposten", objective = "Sprecht mit Zeke Scheuerschuh am Schmugglerposten.", description = "Wir haben hier erstklassige Arbeit geleistet. Ich werde dafür sorgen, dass diese Schießbudenfiguren hier anständig aufräumen und werde dann für eine Weile nach Gadgetzan zurückkehren.\n\nWenn Ihr noch mehr Eindruck auf unsere Freunde vom Dampfdruckkartell schinden, oder einfach nur noch mehr Geld verdienen wollt, solltet Ihr von hier aus nach Südwesten gehen. Der Schmugglerposten befindet sich am Rand der Klaffenden Schlucht.\n\nSprecht mit Zeke Scheuerschuh. Ich würde gutes Geld darauf verwetten, dass er Hilfe braucht.", progress = nil, completion = "Ihr gehört also zu Megs, hm? Es geht das Gerücht um, dass sie sich mit Noggenfogger auf Teufel komm raus gutstellen will.\n\nNaja, was kümmert es mich. Seid Ihr bereit, ein paar Wanzen zu töten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25104] = {title = "Zustand der Grabungsstätte", objective = "Findet Marley Doppelzopf außerhalb der Ausgrabungsstätte von Bael Modan im Südlichen Brachland.", description = "Die Patrouille war heute wirklich ruhig. Das bereitet mir Sorgen, <Name>.\n\nSeit die Allianz Taurajo geplündert hat, sind unsere Standorte nicht mehr sicher. Ihr seht so aus, als ob Ihr allein zurechtkommt - könntet Ihr Euch für mich umsehen?\n\nMeldet Euch bei meinem Sohn Marley außerhalb der Ausgrabungsstätte von Bael Modan im Südosten von hier. Die Grabungsstätte ist ungeschützt und ein leichtes Ziel für Überfälle, und mein Sohn ist zu stolz, um nach Hilfe zu fragen, wenn er sie benötigt.", progress = nil, completion = "Vater hat Euch geschickt? Er macht sich zu viele Sorgen. Hier gibt es nichts, das ich nicht bewältigen könnte...\n\nDennoch weiß ich die Hilfe zu schätzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25105] = {title = "Nibbler! Nein!", objective = "Schleift drei gediegene Zephyrite und gebt sie Isabel Jones in Sturmwind.", description = "Lilas Haustier Nibbler ist schon wieder in meine Werkstatt gelangt!\n\nIch war dabei, einen Armreif herzustellen und er sollte heute geliefert werden. Die Arbeit war fast beendet, bis auf ein paar Edelsteine. Ich habe die ganze Nacht damit zugebracht, sie zu schleifen, doch als ich kurz vor die Tür gegangen bin, um zu frühstücken, ist das kleine Biest in die Werkstatt gekommen und hat jeden Edelstein in Reichweite geschluckt! Das Ding kann ALLES verdauen und glaubt mir, Ihr würdet Euch den Rücken brechen bei dem Versuch, seine Hinterlassenschaften aufzusammeln.\n\nIch brauche schnell Ersatzedelsteine; der Kurier kommt heute Abend. Hilfe!", progress = "Habt Ihr die gediegenen Zephyrite, die ich brauche?", completion = "Ihr habt wirklich meine Haut gerettet, &lt;Name&gt;. Danke!", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25106] = {title = "Hände weg von meiner Grabung!", objective = "Tötet 8 Räuber der Ausgrabungsstätte, rettet 5 Artefakte aus Bael Modan und findet Doppelzopfs Werkzeuge in der Ausgrabungsstätte von Bael Modan.", description = "Schaut Euch das Chaos hier unten an, <Name>! Ich habe die Vorarbeiter angewiesen, so viele Artefakte, wie möglich, zu retten. Wer weiß, mit welchen Schätzen diese Taurentiere sich gerne aus dem Staub machen würden.\n\nKönnt Ihr mir helfen, die Dinge in den Griff zu bekommen? Tötet die Plünderer und rettet so viele Artefakte, wie möglich.\n\nWenn Ihr schon dabei seid, haltet Ausschau nach meinen verschwundenen Werkzeugen. Einige schnelle Reparaturen und ich kann diese Flugmaschine wieder flugfähig machen.", progress = "Wie ist die Situation hier unten, <Name>?\n\nAls der Überfall losging, habe ich ihrem Anführer Steinbuckel eine Kugel verpasst, aber er kam immer weiter auf mich zu.", completion = "Mein Vater wäre sehr stolz auf Euch, &lt;Name&gt;.\n\nUnd jetzt muss ich diese Flugmaschine wieder in Gang bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25107] = {title = "Die große Tafel", objective = "Bringt die große Tafel zu Andoren Morgendunst.", description = "Auf dem Boden der Truhe findet Ihr eine große Tafel. Das Material scheint Stein zu ähneln, ist aber ganz sanft und fein anzusehen und mit seltsamen Schriften versehen.\n\nEin Teil der Schrift ist der gleiche wie an den Mauern, doch es sind auch andere Schriften darauf zu finden. Andoren wird sich sicherlich dafür interessieren.", progress = "Ihr seid zurück! Was habt Ihr gefunden?", completion = "Das ist wirklich unglaublich. Die Hieroglyphen sind zweifellos von den Titanen, aber die Markierungen darunter...\n\nEinige der Zeichen sehen aus wie die uralten Schriften der Kaldorei. Und die Vorkammer war voller Hieroglyphen, sagt Ihr?\n\nWas Ihr gefunden habt ist weitaus wichtiger als jegliche Reichtümer, &lt;Name&gt;. Bitte, nehmt Euch eine Belohnung, die Ihr angemessen findet.", rewards = "Hieroglyphischer HelmÜbersetzungsstiefelGürtel der rosigen SchrifttafelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25108] = {title = "Feegly der Verbannte", objective = "Tötet Feegly den Verbannten in der Ausgrabungsstätte von Bael Modan.", description = "Das ist die traurigste Geschichte, die ich je gehört habe, <Name>. Feegly war einer unserer schnellsten Gräber, bis er an dieses... Ding... geraten ist. Die \"Träne der Monde\" nennen wir es. Sie hat ihn verändert. Umgewandelt. Ich wünschte, sie wäre nie ausgegraben worden.\n\nFeegly wurde aus Bael Modan verbannt, aber ich hörte Berichte, dass er wieder in der Nähe der Grabungsstätte herumschnüffelt. Das bemitleidenswerte Ding hat genug gelitten. Wenn Ihr ihn dort unten findet, erlöst ihn von seinem Elend.", progress = nil, completion = "&lt;Marley nickt grimmig.&gt;\n\nJa, ich denke, es ist am Besten so.", rewards = "Schiftung aus Bael ModanFeeglys TuchEnde des JammersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25109] = {title = "Gallywix' Fronmine", objective = "Sprecht mit Assistentin Greely in Gallywix' Fronmine auf den Verlorenen Inseln.", description = "Wir sind gerade so mit heiler Haut entkommen!\n\nDer Handelsprinz hat einen ganzen Haufen von uns versklavt und lässt uns in seiner Höhle schuften. Er nennt es Gallywix' Fronmine.\n\n<Slinky schnaubt.>\n\nGreely hat uns sieben bei der Flucht geholfen, aber dabei wurde sie selbst gefangen genommen.\n\n<Name>, Ihr seid <der Einzige, der/die Einzige> die; verrückt genug ist, um in einen explodierenden Vulkan hineinzuspazieren! Die Assistentin wird Euch dabei helfen, die anderen zu befreien.\n\nSchnell! Dieser Ort geht gleich endgültig in die Luft!", progress = nil, completion = "&lt;Die Assistentin sieht Euch verwirrt an.&gt;\n\nHä… was? Wer?", rewards = "Handschuhe eines Arbeiters von GallywixGreelys ErsatzdolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25110] = {title = "Kaja'Cola! Hier kommen die IDEEN (TM)", objective = "Sammelt 1 Kaja'Cola minus eins.", description = "Assistentin Greely sieht eindeutig verwirrt und verängstigt aus. Wie soll sie Euch in diesem Zustand nur helfen, alle zu retten?\n\nVielleicht hilft ja ein Schluck von diesem Kaja'Cola minus eins, das Ihr gesehen habt. Das sollte sie auf Ideen bringen!", progress = "Häh?", completion = "&lt;Assistentin Greely sieht die Kaja'Cola minus eins in Eurer Hand und ihre Augen leuchten lebhaft.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKaja'Cola Gives You IDEAS! (TM): Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25111] = {title = "Wiederverwerter zur Wiederverwertung", objective = "Benutzt den Schlächterbot, um 12 tote Feuerrocs auszuschlachten.", description = "Jetzt, wo ich weiß, dass Ihr nicht zimperlich seid, habe ich noch mehr Arbeit für Euch. Habt Ihr die Vögel mit den roten Federn gesehen, die um die Knochen schwärmen? Es sind Feuerrocs. Sie können Euch in Flammen setzen, wenn Ihr nicht aufpasst.\n\nAufgrund ihres außerordentlichen Körperbaus sind sie auch verdammt wertvoll. Die meisten Jäger sind nicht in der Lage, für gutes Gold Feuer spuckende Bussarde zu töten... seid Ihr es?", progress = nil, completion = "Alchemisten müssen für diese Ware tief in die Tasche greifen. Vielleicht könnte ich manchen versuchen, sie als Drachenteile zu verkaufen, aber das ist auch nicht mein Problem, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25112] = {title = "Schlächterbot", objective = "Benutzt den Schlächterbot, um 10 Kadaver von Glashautbasilisken auszuschlachten.", description = "Ich verdiene mein Gold mit dem Verkauf von Tierteilen und habe eine idiotensichere Methode zur Gewinnmaximierung perfektioniert: den Schlächterbot!\n\nSchlächterbots sind situationsabhängig darauf programmiert, um auch das kleinste Stückchen wiederverwertbarer Materialien von den Wildtieren aus der Umgebung zu erhalten. Schlächterbot verrichtet die ganze Arbeit und das Beste daran ist, dass nur ich weiß, wie man die Waren aus ihm herausbekommt.\n\nWenn Ihr Euch auch ein paar Münzen verdienen wollt, könnt Ihr mit einem der Schlächterbots losziehen. Ich brauche Teile von Glashautbasilisken - Ihr findet sie südlich von hier.", progress = nil, completion = "Gute Arbeit, Kind. Auch keine Finger verloren? Gut, dann können wir Euch mit mehr Arbeit versorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25115] = {title = "Eiterpfotenschlachtung", objective = "Benutzt den Schlächterbot, um 10 Kadaver von Eiterpfotenhyänen auszuschlachten.", description = "Die Hyänen sehen zwar so aus, als sei nichts an ihnen dran, aber sie haben die stärksten Kiefer, die Ihr finden könnt! Wenn Ihr nicht aufpasst, können sie Euch mit einem Biss ein Bein abreißen. Knochenstärke wie diese ist wertvoll, man muss nur die richtigen Käufer finden!\n\nNehmt einen der Schlächterbots. Kieferspaltung ist nicht einfach, aber der Kleine wurde so programmiert, dass er genau weiß, was zu tun ist. Bringt ihn zu mir zurück, wenn er voll ist.", progress = nil, completion = "Wunderschön! Diese Schönheiten machen wir noch schön sauber und dann sind sie in kürzester Zeit zum Verkauf bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25118] = {title = "Nach den Lauerern schauen", objective = "Tötet 8 Waldlauerer.", description = "Ich weiß nicht, wie es Euch geht, aber Spinnen mag ich gar nicht, und die, die größer sind als ich, erst recht nicht. Loch Modan ist ein wunderschöner Ort, aber ohne diese furchtbaren Spinnentiere überall wäre es doch schöner.\n\nPasst auf, ich habe ein paar Münzen übrig, und Ihr seht stark aus. Wenn Ihr für mich ein paar dieser Viecher erledigt, werde Ich Euch für die Zeit entlohnen, die Ihr investiert habt.", progress = nil, completion = "Ich werde sicherlich besser ruhen können, nun da ich weiß, dass diese Dinger mich nicht mitten in der Nacht heimsuchen... wieder heimsuchen werden. Vielen Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25120] = {title = "Marleys letzter Flug", objective = "Sprecht mit Marley Doppelzopf und akzeptiert einen Flug in seiner Flugmaschine.", description = "Okay, <Name>! Lasst uns diese Artefakte zu meinem Vater zurückbringen und ihm aus erster Hand Bericht erstatten.\n\nDank Eurer Hilfe ist meine Flugmaschine jetzt wieder einsatzbereit. Wir können zusammen dorthin fliegen und uns den Ruhm teilen.\n\nSprecht mich an, wenn Ihr bereit seid, aufzubrechen.", progress = nil, completion = "&lt;Der übel zugerichtete Zwerg hängt schlaff im Cockpit. Ihr nähert Euch dem brennenden Wrack und seine Augenlider öffnen sich flatternd.&gt;\n\n&lt;Marley Doppelzopf lebt noch!&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25121] = {title = "Momentum", objective = "Trefft Kelsey Stahlfunken in der Mast- und Schotbucht.", description = "Wir haben wohl noch mehr Arbeit zu tun! Dass Herr Noggenfogger uns gebeten hat, den Rest der Piraten zu beseitigen, ist eine wahre Ehre.\n\nIhr wart bisher SOO hilfreich, warum kommt Ihr nicht und trefft mich in der Mast- und Schotbucht? Ich muss mir nur etwas gemütlichere Kleidung überziehen, also wartet nicht hier auf mich. Ich hole Euch sowieso ein, versprochen!", progress = nil, completion = "Hallo auch! Wir haben schon angefangen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25122] = {title = "Moralschub", objective = "Benutzt die Kaja'Cola minus eins, um Ass, Izzy, Gobber und 6 überlebende Goblins oder Bürger von Kezan zu befreien.", description = "Ihr müsst die gesamte Kaja'Cola minus eins sammeln, die Ihr in die Finger bekommt! Bringt die Goblins dazu, sie zu trinken, damit sie einen Moralschub erhalten und sich befreien!", progress = nil, completion = "Ich hasse den Handelsprinzen, aber über die Ergebnisse seiner Methoden lässt sich nicht streiten. Die Kaja'Cola minus eins ist eine deutliche Verbesserung im Vergleich zur herkömmlichen Kaja'Cola. Halb so viele Kalorien, doppelt so viele Ideen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25123] = {title = "Werft ihn zu Boden!", objective = "Vernichtet Knallschattens Seelenstein.", description = "Dieser Alptraum findet nie ein Ende, solange Knallschatten der Tiermeister noch atmet. Dabei gibt es jedoch ein paar Probleme.\n\nZum einen hat er als Hexenmeister eine Sukkubus namens Delicia Peitschenknall bei sich. Wenn Ihr Knallschatten schnell erledigt, kehrt der Dämon wieder dorthin zurück, von wo er beschworen wurde.\n\nDas zweite Problem ist der Seelenstein, mit dem Knallschatten sich als Hexenmeister wiederbeleben kann. Ihr müsst seinen Seelenstein an Euch nehmen und ihn zerstören, sodass er für immer tot bleibt!", progress = nil, completion = "Euer Seelenstein ist abgelaufen, Knallschatten!", rewards = "Delicias StrümpfeGelenkbänder des SeelensteinbrechersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25125] = {title = "Licht am Ende des Tunnels", objective = "Bedient den Minenwagen außerhalb von Gallywix' Fronmine auf den Verlorenen Inseln.", description = "In Ordnung, wir müssen hier weg, bevor die Mine endgültig in die Luft fliegt!\n\nLasst uns aus dem anderen Ende des Tunnels an der Nordseite der Mine fliehen. Wir sollten einen der Minenwagen benutzen können, um schnell an der Seite des Vulkans herunterzurasen.", progress = nil, completion = "Sieht ein wenig klapperig aus…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25126] = {title = "Scharfe Zähne", objective = "Tötet 6 scheckige Eber.", description = "Als erstes müssen wir Euch ein wenig Selbstvertrauen lehren. Ich könnte Euch ins Brachland auf die Kodojagd schicken, aber ehrlich gesagt, nützt Ihr uns lebend mehr als tot.\n\nEs wäre wohl besser, wenn Ihr erst einmal die Eber abschlachtet, die es auf den Höfen nördlich und nordöstlich von hier gibt.", progress = nil, completion = "Aber lasst Euch das nicht zu Kopfe steigen... Ihr werdet in Eurer Karriere vor schwierigeren Gegnern als Ebern stehen.\n\nTrotzdem habt Ihr Euch bewiesen. Eure nächste Prüfung wird Euch zu einem gefährlicheren Gegner führen, deshalb benötigt Ihr zusätzlichen Schutz.", rewards = "WildschweinbalggürtelStulpen des AngebersScheckige ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25127] = {title = "Stich des Skorpiden", objective = "Beschafft 8 Skorpidarbeiterschwänze.", description = "Ich muss Euch zurück ins Feld schicken, <Klasse>. Ihr werdet nordwestlich von hier viele Skorpide finden. Bringt mir 8 ihrer Schwänze.\n\nDas Gegengift für ihren Stich wird aus dem Gift gemacht, das aus ihren Stacheln extrahiert wird. Wir halten immer große Mengen Gegengift für Skorpidgift bereit, um Neulinge wie Euch zu heilen...\n\nAber ich bin sicher, dass Ihr nichts davon brauchen werdet, nicht wahr?", progress = "Der Panzer eines Skorpids ist nicht so dick, dass die Stärke eines entschlossenen Kriegers davon abgehalten würde. Schlagt hart und ohne Zögern zu, und die Skorpide werden leichte Beute abgeben.", completion = "Es gibt eine wichtige Lektion, die Ihr aus dem Kampf mit Skorpiden lernen müsst. Die kleinsten oder größten Eurer Feinde können Euch ins Verderben schicken. In heftigen Kämpfen kann Euch viel zum Straucheln bringen.\n\nIch habe Euch nichts mehr beizubringen, &lt;Name&gt;. Ihr habt Euch gut geschlagen, und ich werde Eure Fortschritte mit Interesse verfolgen.", rewards = "KnochenpanzerstiefelGiftgegerbte KniehosenGiftgetränkte RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25128] = {title = "Hana'zua", objective = "Findet Hana'zua im Tal der Prüfungen.", description = "Hey, Mann, macht mal Pause und hört mir zu. Wir haben ein Problem. \n\nHana'zua, ein guter Freund von mir, ist ins Tal hinausgegangen und nicht wieder zurückgekehrt. Als ich ihn das letzte Mal sah, ging er nach Norden, wo die Skorpide jagen. Vielleicht könnt Ihr nach ihm suchen gehen? Die Geister haben mir gesagt, dass es ihm nicht gut geht.", progress = nil, completion = "&lt;Hana'zua stöhnt vor Schmerzen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25129] = {title = "Sarkoth", objective = "Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", description = "<Klasse>! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte seiner Schere einen ordentlichen Hieb versetzen, bevor sie sich um mein Bein schloss.\n\nIch hatte jedoch nicht mit seinem Stachel gerechnet, der auf meine Brust niederfuhr, sich in mein Fleisch grub und großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.", progress = "Ah... mein Vater sagte immer, aus mir würde nie etwas werden. Ich fürchte, so, wie ich hier unter dem Baum liege, während mein Leben mir zwischen den Fingern zerrinnt, sieht es aus, als hätte er Recht gehabt.\n\nIch wünsche mir nur, mit dem Wissen sterben zu können, dass mein letzter Feind in diesem Leben tot ist.", completion = "Mein Schlag war nicht stark genug, um ihn zu töten, aber wenn ich mir den Schaden ansehe, den ich verursacht habe, macht es mich doch ein bisschen stolz. Mit diesem bisschen Stolz muss ich mich zufrieden geben, wenn ich sterbe; doch in diesem Licht betrachtet, erfüllt mich die kurze Liste meiner im Leben erreichten Leistungen mit Wut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25130] = {title = "Zurück zum Höhlenbau", objective = "Überbringt Gornek im Tal der Prüfungen die Nachricht von Hana'zuas Notlage.", description = "Zu sehen, was Ihr für mich getan habt, gibt mir neuen Mut. Ich kann nicht so einfach fallen! Ich muss durchhalten!\n\nAber es ist noch immer so, dass ich die Reise zurück in unsere Siedlung nicht ohne Hilfe überstehen werde. Bitte, <Name>, kehrt zurück und berichtet Gornek von meiner Situation. Vielleicht kann er mir helfen.", progress = nil, completion = "Eurer Beschreibung des Biests nach muss es sich um Sarkoth handeln! Kein Wunder, dass Hana'zua von ihm besiegt wurde. Ihm wird sofort Hilfe geschickt. Kümmert Euch nicht weiter um Hana'zuas Situation.\n\nIch muss jedoch sagen, dass ich davon beeindruckt bin, dass Ihr Sarkoth getötet habt. Das ist eine Tat, auf die man stolz sein kann, &lt;Name&gt;. Und dass Ihr für die Ehre eines Anderen gekämpft habt obwohl andere Aufgaben Eure Zeit in Anspruch nahmen, mehrt Eure eigene Ehre.", rewards = "Armbinden der LobpreisungGurt der EhreHandschuhe der helfenden HandIhr bekommt:\n\nStaubiger Beutel"}
MultiLanguageQuestData['de'][25131] = {title = "Üble Familiare", objective = "Tötet 8 üble Familiare.", description = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, <Klasse>.\n\nMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...\n\nEin Anhänger der Brennenden Klinge - ein widerwärtiger Kult von Dämonenanbetern - hat hier im Tal der Prüfungen sein Lager aufgeschlagen. Er lungert in einer Höhle im Norden herum und seine üblen Familiare kriechen daraus hervor, um Chaos anzurichten.\n\nAls erste Aktion gegen die Brennende Klinge bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt und falls Ihr überlebt, kehrt zu mir zurück.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;.\n\nDie elenden Familiare waren zwar nur Schoßtiere der dunkleren Mächte der Brennenden Klinge, aber Euer Sieg über sie lässt mich ahnen, dass noch größere Taten folgen werden.", rewards = "Abscheuliche StiefelAbscheuliches TrikotAbscheuliche PantoffelnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25132] = {title = "Medaillon der Brennenden Klinge", objective = "Tötet 7 Teufelspirscher und bringt das Medaillon der Brennenden Klinge an Euch.", description = "Durch meine Visionen sehe ich einen mächtigen Gegenstand - ein Medaillon - tief im Koven der Brennenden Klinge, bewacht von Monstern und schwarzer Magie. Wir müssen es haben.\n\nDiese Dämonenanbeter haben unsere Heimat schon zu lange entweiht. Läutert den Koven von seiner dämonischen Verderbnis, indem Ihr die Teufelsbestien und ihren Anführer tötet. Kehrt mit dem Medaillon als Beweis Eurer Tat zurück.\n\nGeht, <Name>. Ihr werdet den Koven in einer Höhle nördlich von hier finden.", progress = "Habt Ihr Eure Aufgabe vollendet, <Name>?", completion = "Ihr habt es! Gut gemacht!\n\nEure Bemühungen im Koven der Brennenden Klinge sind der Schlüssel für die Ausrottung dieses Kults im Tal der Prüfungen. Ich fürchte jedoch, dass sie in unserem Land noch mehr vorhaben.\n\nNoch sind wir sie nicht endgültig los.", rewards = "Kovenhandschuhe der Brennenden KlingeFernblickarmbänderVerdrängergamaschenIhr bekommt:\n\nSchwacher Heiltrank"}
MultiLanguageQuestData['de'][25133] = {title = "Bericht erstatten in Sen'jin", objective = "Sprecht mit Meister Gadrin in Sen'jin.", description = "Eure Prüfungen gegen die Brennende Klinge sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.\n\nBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.\n\nBerichtet Gadrin von der Brennenden Klinge und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.\n\nGeht, <Name>, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Brennenden Klinge entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", progress = nil, completion = "Hm... Euer Bericht kommt zu einem schlechten Zeitpunkt. Kultisten der Brennenden Klinge wurden hier in Sen'jin nicht mehr gesichtet, aber wir werden weiterhin auf der Hut sein, dass sie hier nicht wieder Fuß fassen können.\n\nDie Orcs sind Freunde der Dunkelspeertrolle. Ehrenhafte Freunde. Wir wollen den Orcs helfen, aber... wir benötigen ebenfalls Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25134] = {title = "Faule Peons", objective = "Benutzt den Totschläger des Großknechts an 4 faulen Peons, wenn sie schlafen.", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, <Volk>. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nHaltet unter den Bäumen im Tal nach ihnen Ausschau. Verdammte faule Peons...", progress = "Verdammter fauler B...\n\nHuch? Habt Ihr meinen Totschläger? Habt Ihr Peons dabei erwischt, wie sie bei der Arbeit schliefen?!", completion = "Gut, gut. Vielleicht werden sie es sich in Zukunft zweimal überlegen, bevor sie wieder nachlässig werden! Ich danke Euch für Eure Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25135] = {title = "Thazz'rils Hacke", objective = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", description = "<Name>, Ihr seid <ein/eine:r> <Volk>, auf <den/die:r> man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Brennenden Klinge, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", progress = "Habt Ihr den Koven der Brennenden Klinge betreten, <Name>? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, &lt;Name&gt;. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25136] = {title = "Galgars Kaktusapfel Surprise", objective = "Sammelt 6 Kaktusäpfel.", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweiß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, <Name>. Wenn Ihr mir 6 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, &lt;Name&gt;! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu.", rewards = "Ihr bekommt:\n\nKaktusapfel Surprise"}
MultiLanguageQuestData['de'][25138] = {title = "Glyphenpergament", objective = "Lest das Glyphenpergament und sprecht mit Acrypha im Tal der Prüfungen.", description = "Ah, während Ihr weg wart, ist ein Pergament für Euch gekommen, <Name>.\n\nLest es, wenn Ihr die Zeit habt. Wenn ich mich nicht irre, kommt es von Magierlehrerin Acrypha. Sie möchte mit Euch reden, wenn Ihr bereit seid.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25139] = {title = "Zuverlässiger Schuss", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe und übt daran fünfmal den zuverlässigen Schuss.", description = "Ihr wisst bereits, wie man einen arkanen Schuss abfeuert. Gut. Aber wenn Ihr das tut, sinkt Euer Fokus. Um Fokus zurückzugewinnen, müsst Ihr zu einem anderen Fernangriff übergehen.\n\nGeht, sammelt mehr Erfahrung. Wenn Ihr das tut, erlernt Ihr einige neue Fähigkeiten. Die erste wird Euch helfen, Fokus zurückzuerlangen.", progress = nil, completion = "Ihr lernt schnell.", rewards = "Ihr bekommt:\n\nArmschienen des Wildtieraufspürers"}
MultiLanguageQuestData['de'][25141] = {title = "Ausweiden", objective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Findet eine Trainingsattrappe und übt daran dreimal die Anwendung von 'Ausweiden'.", description = "Fangen wir mit den Grundlagen an, ja? Ich bin der einzige Schurkenlehrer hier, also werdet Ihr von mir lernen müssen.\n\nGeht, sammelt mehr Erfahrung, findet heraus, wie Ihr Eure Gegner ausweiden könnt und zeigt es mir dann an den Trainingsattrappen hier. Ich werde Eure Leistung dann bewerten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFingerlose Handschuhe des Schlossknackers"}
MultiLanguageQuestData['de'][25143] = {title = "Urtümlicher Schlag", objective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Findet eine Trainingsattrappe in Shikriks Nähe und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", description = "Während Ihr Kraft durch das Erklimmen neuer Stufen erlangt, werdet Ihr Macht erkennen, mit der Ihr neue Fähigkeiten nutzen könnt. Die erste dieser Fähigkeiten, die Ihr auf Eurer Reise entdeckt, ist der 'Urtümliche Schlag'.\n\nSetzt ihn ein, um mit Eurer Waffe einen Schlag zu führen, der mit der Macht der Elemente erfüllt ist.\n\nEs ist Zeit, Eure neue Fähigkeit zu erlernen und sie zu meistern. Übt an einer der Trainingsattrappen vor der Höhle.", progress = nil, completion = "Sehrt gut. Jetzt, da Ihr wisst, wie man mit den Elementen spricht, testen wir Eure Verbindung mit ihnen.", rewards = "Ihr bekommt:\n\nFelsgebissene Handschuhe"}
MultiLanguageQuestData['de'][25145] = {title = "Verderbnis", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Findet eine Trainingsattrappe und wirkt fünfmal 'Verderbnis' auf sie.", description = "Es ist meine Pflicht, Euch auszubilden und ich gedenke, genau das zu tun.\n\nWenn Ihr mehr Macht erlangt, werdet Ihr die Teufelsstimmen hören, die Euch neue Zauber offenbaren.\n\nGeht, sammelt mehr Erfahrung, erlernt einen neuen Zauber und übt ihn dann an einer der Trainingsattrappen hier.", progress = nil, completion = "Offenbar lernt Ihr schnell.", rewards = "Ihr bekommt:\n\nKreis des Leids"}
MultiLanguageQuestData['de'][25147] = {title = "Sturmangriff", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht eine Trainingsattrappe und übt die Benutzung von 'Sturmangriff'.", description = "Man hat mich angewiesen, Euch auf den Kampf vorzubereiten. Ihr seht allerdings aus, als hättet Ihr schon ein wenig Zeit auf dem Schlachtfeld verbracht. Gut.\n\nWährend Ihr Eure Reise fortsetzt, werdet Ihr erkennen, dass Ihr beginnen könnt, neue Techniken anzuwenden.\n\nGeht, sammelt Erfahrung und bringt Euch selbst den 'Sturmangriff' bei. Zeigt mir dann, was Ihr gelernt habt.", progress = "Nach dem Training werden wir Eure Fähigkeiten überprüfen.", completion = "Versteht Ihr es jetzt? Gut, dann probiert es aus.", rewards = "Ihr bekommt:\n\nBrüllergürtel"}
MultiLanguageQuestData['de'][25149] = {title = "Frostnova", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Findet eine Trainingsattrappe und übt den Zauber 2-mal daran.", description = "Gut, kommen wir zum einfachen Teil.\n\nAlles, was Ihr tun müsst, um Eure Verbindung zum Arkanen zu vertiefen, ist, erfahrener zu werden und mehr Macht zu erlangen. Dann werdet Ihr feststellen, dass Ihr neue Zauber wirken könnt.\n\nIhr werdet sehen. Geht und probiert es aus und zeigt mir dann, was Ihr erlernt habt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMachterfüllte Hände"}
MultiLanguageQuestData['de'][25151] = {title = "Er braucht Bier!", objective = "Durchsucht Burg Bael'dun nach einem Krug mit Hager-Bschorr und bringt ihn zu Marley Doppelzopf am Eingang.", description = "<Marley umklammert mit zitternder, blutiger Hand eine Seite Eures Kopfes.>\n\nBier... Muss... Bier... trinken...\n\nHager-Bschorr von drinnen. <Er hustet.> Das sollte... helfen.", progress = "<Marley atmet stoßweise und zittert keuchend.>\n\n<Sein Blick ist flehend auf Euch gerichtet.>", completion = "&lt;Ihr rennt mit dem Bier auf Marley zu und seine Augen glitzern. Er ergreift den Krug mit beiden Händen und kippt trinkt gierig. Weißer Schaum quillt über seinen blutverschmierten Bart.&gt;\n\nAh... das ist genau das Richtige. Hager-Bschorr... Ich danke Euch, mein Freund.\n\nDas wird all dies... ein wenig einfacher machen.\n\n&lt;Er hustet ein letztes Mal und bricht über der zertrümmerten Steuerkonsole zusammen. Der halb leere Krug fällt zu Boden und sein Inhalt ergießt sich im Sand. Seine Augen brechen.&gt;\n\n&lt;Marley Doppelzopf ist tot.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25152] = {title = "Euer Platz in der Welt", objective = "Sprecht mit Gornek.", description = "Endlich seid Ihr alt genug, <Name>... alt genug, um im Namen der Horde zu kämpfen. Um für den Ruhm des Kriegshäuptlings Siege zu erringen.\n\nJa...\n\n<Kaltunk mustert Euch.>\n\nDoch, doch, Ihr eignet Euch.\n\nZweifellos wollt Ihr Euch einen mächtigen Drachen oder einen Dämon suchen und ihn mit bloßen Händen erwürgen, aber vielleicht ist es vernünftiger, wenn Ihr mit etwas weniger... Gefährlichem anfinget.\n\n<Kaltunk lacht.>\n\nMeldet Euch bei Gornek; der sollte Euch eine Aufgabe zuweisen können, die zu einem wie Euch passt, <Klasse>. Er sitzt am Feuer direkt hinter mir.", progress = nil, completion = "Wieder einer von Kaltunks Rekruten, was?\n\nEs ist wirklich schlecht um die Horde bestellt, wenn das das Beste ist, was wir auf die Beine stellen können. Einerlei. Wenn es so weit ist und wir erkennen, dass Ihr bereit seid, das Tal zu verlassen, werdet Ihr ein stolzer Krieger der Horde sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25153] = {title = "Bael'duns Rettung", objective = "Begebt Euch in die Burg Bael'dun und rettet 10 Überlebende von Bael'dun aus den Trümmern.\n\nBenutzt die Notfallfeuerventile, um Euch vor den Flammen zu schützen.", description = "Hilfe! Ihr müsst etwas tun!\n\nEinige Zwerge sind noch drinnen... so viele... gefangen unter den Trümmern. Lebendig begraben. Die Flammen! Es ist ein Alptraum da drinnen. Wir wissen nicht, wie lange es noch dauert, bis das Dach einstürzt.\n\nBitte, <Klasse>, Ihr müsst sie retten!\n\nRennt hinein. Benutzt die Notfallfeuerventile, um Euch vor den Flammen zu schützen. Ihr seid ihre einzige Hoffnung!", progress = nil, completion = "Ihr seid eine Legende, &lt;Name&gt;.\n\nDie anderen Überlebenden und ich werden noch Jahre von Euren Taten erzählen.", rewards = "Kettengamaschen aus Bael'dunKlinge des ÜberlebendenWeste der Burg Bael'dunIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25154] = {title = "Ein Geschenk für Lila", objective = "Schleift drei zeitlose Nachtsteine und gebt sie Isabel Jones in Sturmwind.", description = "Ich versuche diese Handelsschiffskapitänin, Lila, zu beeindrucken. Ich habe an einer Halskette gearbeitet, die zu ihren wunderschönen violetten Haaren passt, aber die Edelsteine sind verschwunden! Sie waren hier, als ich sie gestern Abend meinem guten Freund Curver gezeigt habe. Wir haben Fusel getrunken und ich bin bewusstlos geworden - als ich wach wurde, waren die Edelsteine weg! Das müssen verdammt raffinierte Diebe gewesen sein, Curver hat nämlich nichts gesehen.\n\nIhr Schiff kommt heute Abend an und ich brauche dringend drei Nachtsteine, um ihr Geschenk zu vollenden. So helft mir doch!", progress = "Habt Ihr mir die Nachtsteine gebracht?", completion = "Danke! Ich bin sicher, dass ich diese Marith Lazuria aus Orgrimmar damit schlagen kann! Ich kann gar nicht abwarten, den Blick in ihrem schönen Auge zu sehen, wenn ich es ihr gebe.", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25155] = {title = "Ogermazonen in Stimmung", objective = "Schleift drei gezackte Jaspise und gebt sie Isabel Jones in Sturmwind.", description = "Ich sollte heute eine Ladung Jaspis von Azeroth Express erhalten, aber ich habe gerade gehört, dass ihr Schiff auf einer winzigen Insel namens Ogerzonien aufgelaufen ist. Ich mache mir Sorgen um die Besatzung, da die gigantischen weiblichen Oger auf der Insel, wenn man den Gerüchten Glauben schenkt, entsetzliche Rituale an Männern durchführen, die auf ihre Insel stoßen. Meine Arbeit muss aber fortgeführt werden und wir brauchen diese Edelsteine. Ich habe viel über Eure Fertigkeiten als Juwelenschleifer gehört - könntet Ihr mir vor Ende des Tages drei gezackte Jaspise bringen?", progress = "Habt Ihr mir die Edelsteine gebracht, die ich brauche?", completion = "Eure Arbeit ist so gut, wie man es sich erzählt!", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25156] = {title = "Elementarglibber", objective = "Besorgt 10 Elementarglibber von beliebigen Cataclysm-Elementaren und bringt sie zu Isabel Jones in Sturmwind.", description = "Statt der gewöhnlichen alten Methode, Edelsteine in Ringe und dergleichen einzusetzen, benutze ich eine innovative neue Methode. Ich klebe die Steine einfach mit Barnsworths Elementarkleber an! Der Professor braucht jedoch mehr Elementarglibber für eine weitere Ladung, und ich muss heute noch viele Edelsteine einsetzen. Könnt Ihr mir welchen besorgen?", progress = "Habt Ihr mir den Elementarglibber mitgebracht?", completion = "Danke. Ähm. Einfach da drüben ablegen. Ich muss mir noch überlegen, wie ich meine Hand von diesem Gefäß löse.", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25157] = {title = "Der letzte Schrei!", objective = "Testet den Sternenstaub No. 2 an 10 \"humanoiden Testobjekten\".", description = "Professor Barnsworth arbeitet gerade an diesem neuen Sternenstaub. Da diese Saison in Sturmwind alles angesagt ist, was glitzert, bin ich mir sicher, dass man ihn uns auf dem Markt praktisch aus der Hand reißen würde. Aber der Juwelenschleiferverband erlaubt uns nicht, das Zeug unter die Leute zu bringen, bis wir ein paar Tests an humanoiden Lebewesen vorgenommen haben. Sie brabbeln irgendwas von Gefahren bei der Handhabung von magischem Staub und allerlei anderen Unsinn. Nun, ich schätze, wir müssen sie irgendwie bei Laune halten. Nehmt diese Tasche und testet den Sternenstaub No. 2 an humanoiden Testobjekten.", progress = "Und, wie lief der Test?", completion = "Was ist passiert? Wir sind ruiniert! Hmm. Nun, wenn man es genau nimmt... Vielleicht kann der Professor eine andere Verwendung dafür finden?", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25158] = {title = "Nibbler! Nein!", objective = "Schleift drei gediegene Zephyrite und gebt sie Marith Lazuria in Orgrimmar.", description = "Lilas Haustier Nibbler ist schon wieder in meine Werkstatt gelangt!\n\nIch war dabei, einen Armreif herzustellen und er sollte heute geliefert werden. Die Arbeit war fast beendet, bis auf ein paar Edelsteine. Ich habe die ganze Nacht damit zugebracht, sie zu schleifen, doch als ich kurz vor die Tür gegangen bin, um zu frühstücken, ist das kleine Biest in die Werkstatt gekommen und hat jeden Edelstein in Reichweite geschluckt! Das Ding kann ALLES verdauen und glaubt mir, Ihr würdet Euch den Rücken brechen bei dem Versuch, seine Hinterlassenschaften aufzusammeln.\n\nIch brauche schnell Ersatzedelsteine; der Kurier kommt heute Abend. Hilfe!", progress = "Habt Ihr mir die gediegene Zephyrite gebracht, die ich brauche?", completion = "Ihr habt mir wirklich die Haut gerettet, &lt;Name&gt;. Danke!", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25159] = {title = "Der letzte Schrei!", objective = "Testet den Sternenstaub No. 2 an 10 \"humanoiden Testobjekten\".", description = "Dr. Vernstrom arbeitet gerade an diesem neuen Sternenstaub. Da diese Saison in Orgrimmar alles angesagt ist, was glitzert, bin ich mir sicher, dass man ihn uns auf dem Markt praktisch aus der Hand reißen würde. Aber der Juwelenschleiferverband erlaubt uns nicht, das Zeug unter die Leute zu bringen, bis wir ein paar Tests an \"lebenden Organismen\" vorgenommen haben. Sie brabbeln irgendwas von Gefahren bei der Handhabung von magischem Staub und allerlei anderen Unsinn. Nun, ich schätze, wir müssen sie irgendwie bei Laune halten. Nehmt diese Tasche und testet den Sternenstaub No. 2 an humanoiden Testobjekten.", progress = nil, completion = "Was ist passiert? Wir sind ruiniert! Hmm. Nun, wenn man es genau nimmt... Vielleicht kann der Doktor eine andere Verwendung dafür finden?", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25160] = {title = "Ein Geschenk für Lila", objective = "Schleift drei zeitlose Nachtsteine und gebt sie Marith Lazuria in Orgrimmar.", description = "Ich versuche diese Handelsschiffskapitänin, Lila, zu beeindrucken. Ich habe an einer Halskette gearbeitet, die zu ihren wunderschönen violetten Haaren passt, aber die Edelsteine sind verschwunden! Sie waren hier, als ich sie gestern Abend meinem guten Freund Curver gezeigt habe. Wir haben Fusel getrunken und ich bin bewusstlos geworden - als ich wach wurde, waren die Edelsteine weg! Das müssen verdammt raffinierte Diebe gewesen sein, Curver hat nämlich nichts gesehen.\n\nIhr Schiff kommt heute Abend an und ich brauche dringend drei Nachtsteine, um ihr Geschenk zu vollenden. So helft mir doch!", progress = "Habt Ihr mir die Nachtsteine gebracht?", completion = "Danke! Ich bin sicher, dass ich diese Isabel Jones aus Sturmwind damit schlagen kann! Ich kann gar nicht abwarten, den Blick in ihrem schönen Auge zu sehen, wenn ich es ihr gebe.", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25161] = {title = "Ogermazonen in Stimmung", objective = "Schleift drei gezackte Jaspise und gebt sie Marith Lazuria in Orgrimmar.", description = "Ich sollte heute eine Ladung Jaspis von Azeroth Express erhalten, aber ich habe gerade gehört, dass ihr Schiff auf einer winzigen Insel namens Ogerzonien aufgelaufen ist. Ich mache mir Sorgen um die Besatzung, da die gigantischen weiblichen Oger auf der Insel, wenn man den Gerüchten Glauben schenkt, entsetzliche Rituale an Männern durchführen, die auf ihre Insel stoßen. Meine Arbeit muss aber fortgeführt werden und wir brauchen diese Edelsteine. Ich habe viel über Eure Fertigkeiten als Juwelenschleifer gehört - könntet Ihr mir vor Ende des Tages drei gezackte Jaspise bringen?", progress = "Habt Ihr mir die Edelsteine gebracht, die ich brauche?", completion = "Eure Arbeit ist so gut, wie man es sich erzählt!", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25162] = {title = "Elementarglibber", objective = "Besorgt 10 Elementarglibber von beliebigen Cataclysm-Elementaren und bringt sie zu Marith Lazuria in Orgrimmar.", description = "Statt der herkömmlichen Methode, Edelsteine in Ringe zu fassen und so weiter, benutze ich eine innovative neue Methode. Ich klebe die Edelsteine einfach mit Vernstroms Elementarkleber an! Der Doktor braucht jedoch mehr Elementarglibber für eine weitere Ladung und ich muss eine Menge Steine einfassen. Könnt Ihr mir welchen besorgen?", progress = "Habt Ihr mir den Elementarglibber mitgebracht?", completion = "Danke. Ähm. Einfach da drüben ablegen. Ich muss mir noch überlegen, wie ich meine Hand von diesem Gefäß löse.", rewards = "Ihr bekommt:\n\nSymbol des erhabenen Juweliers"}
MultiLanguageQuestData['de'][25163] = {title = "Wer war das?", objective = "Sucht in Burg Bael'dun nach einer Leiche der Horde.", description = "Sabotage! Es gibt keine andere Möglichkeit. Das ganze Munitionslager der Burg ist explodiert. Die Horde muss jemanden hineingeschmuggelt haben...\n\n<Klasse>, wenn Ihr den Mumm habt, in den brennenden Alptraum zu laufen... sucht nach Hinweisen, wer uns das angetan hat. Der General wird es wissen wollen! Sucht nach einer Leiche der Horde in den Trümmern und geht dieser Katastrophe auf den Grund...", progress = nil, completion = "&lt;Eine qualmende Leiche ist besonders auffällig in diesem Gemetzel. Der tote Goblin hält einen Bauplan der Burg mit seiner leblosen Hand umklammert...&gt;\n\n&lt;Die Goblins des Bilgewasserkartells. Sie stecken dahinter!&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25164] = {title = "In die Ecke gedrängt", objective = "Verteidigt das Lager des Irdenden Rings, bis die Naga sich zurückziehen.", description = "Die Naga sind da, <Klasse>! Helft uns dabei, sie abzuwehr'n!", progress = "Sie schein'n unermüdlich zu sein, aber wir werd'n sie zurückdräng'n!", completion = "Ich bin froh, dass Ihr hier wart, Mann.\n\nToshe sieht aus, als will er sie verfolg'n. Ihr solltet ihn'n helf'n.", rewards = "DunstlichtbrustplatteSchulterschutz der Macht von CarideaOstrakodensandalenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25165] = {title = "Große Haken und Lächeln sollten Misstrauen hervorrufen", objective = "Erhaltet 6 Proben Skorpidtoxin, indem Ihr das Totem der Giftextraktion in der Nähe eines rasselnden Skorpids aufstellt.", description = "Als Nächstes werden wir Gift von den Skorpionen holen, die hier überall herumrennen. Aber keine Sorge, Bom'bay passt auf, dass Euch nichts passiert!\n\nBom'bay hat ein großes Totem, das Ihr in den Boden stecken könnt, wenn der Skorpion angreift. Das Totem entzieht ihm das Gift, und Ihr lauft ganz normal und gesund wieder heim. Klingt das gut?", progress = nil, completion = "Ja! Auf dieses Skorpidjuju hat Bom'bay gewartet! Jetzt machen wir Euch auch wieder heil, &lt;Klasse&gt;.\n\nIhr kommt wieder zu Bom'bay, wenn Ihr Euch besser fühlen wollt. Bom'bay hat Zauber, die Euch gesund machen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25166] = {title = "Kapitän Schreckensbart", objective = "Tötet Kapitän Schreckensbart.", description = "Das macht wirklich Spaß, aber wir dürfen nicht vergessen, dass wir für Gnomeregan hier sind!\n\nWir haben den Kapitän der Südmeerfreibeuter auf einem seiner Boote südlich von hier entdeckt, dort, wo die Kämpfe stattfinden. Er ist ganz alleine und ungeschützt auf seinem kleinen Boot!\n\nWenn Ihr Euch um ihn kümmert werden wir den Rest der Piraten in Windeseile los sein.", progress = nil, completion = "Er hat einen Meeresriesen unter Kontrolle gehabt? Wenn wir das weiter untersuchen könnten...\n\nÄh, ich meine natürlich, das ist ja total verrückt! Zum Glück ist er jetzt weg, hurra! Herr Noggenfogger wird so erfreut sein.\n\nUnd hier ist eine nette, große Belohnung für Euch!", rewards = "BüddebüdderobenSchreckensbartwürgerhandschuheFahndergürtelUngeduldige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25167] = {title = "Die Ketten durchbrechen", objective = "Zerstört 3 Vorratskisten aus Nordwacht und tötet 10 Träger der Nordwacht.", description = "Oh Mann, das is' nicht gut! Überhaupt nicht!\n\nThrall ist in See gestochen, Vol'jin kümmert sich um Sachen auf den Echoinseln und der alte Meister Gadrin wird hiergelassen, um sich um Sen'jin zu kümmern. Und dann? Dann kommen diese Menschen von der Feste Nordwacht und schlagen in unserem Gebiet Lager auf!\n\nZum Glück sind sie eben erst angekommen und noch mit dem Aufbau beschäftigt. Ihr könnt dem alten Gadrin helfen, indem Ihr ihre großen Vorratskisten zerstört und die Arbeiter tötet, die die Kisten schleppen. Ihr findet sie südwestlich von hier.", progress = nil, completion = "Wir haben ihre bisherigen Anstrengungen nichtig gemacht, aber hier sind sie immer noch. Wir müssen härter gegen sie vorgehen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25168] = {title = "Das Tal reinigen", objective = "Besiegt 12 Trupps der Nordwacht am Vorposten der Nordwacht.", description = "Nordwacht ist eine sehr gut verteidigte Festung südwestlich von hier, hinter dem Hafen. Es ist eine strategisch gelegene Festung, die für die Horde bisher schwer einzunehmen ist. Wir können wirklich nicht gebrauchen, dass die Menschen eine neue Nordwacht in Durotar aufsetzen.\n\nFegt durch das Tal im Westen und tötet diese Menschen, <Name>. Zeigt ihnen die Macht und Wut von Sen'jin.", progress = nil, completion = "Ein gut geführter Kampf, &lt;Klasse&gt;, doch ich habe Zweifel an unserer Effizienz. Diese Menschen sind immer noch hier.\n\nIhr habt allerdings mehr getan, als man von einem loyalen Mitglied der Horde einfach so verlangen kann. Ich danke Euch.", rewards = "Bogen aus Sen'jinStab aus Sen'jinIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25169] = {title = "Der Kampf gegen die Aggression der Nordwacht", objective = "Zerstört 3 Angriffspläne, die beim Vorposten der Nordwacht gelagert werden.", description = "Diese Menschen westlich von hier sind nicht zum Zelten in Durotar. Die haben andere Pläne, und zwar keine netten! Sie wollen unsere Heimat einnehmen und unsere Schädel auf Piken sehen!\n\nAber nicht mit mir! Nein! Nicht mit Lar! Ich habe Familie hier in Sen'jin und werde verflucht sein, wenn jemand auch nur versuchen will, den Schädel von Tai'tasi auf eine Pike zu piken!\n\nDie Menschen haben ihre Pläne alle aufgeschrieben. Große Schriftrollen, schauen wichtig aus. Die werden wir verbrennen, bevor sie überhaupt erst dazu kommen, etwas Ähnliches zu tun.", progress = "Zerstört diese Menschen, <Name>.", completion = "Gute Arbeit, richtig heldenhaft! Ihr habt Sen'jin heute gute Dienste geleistet. Ganz Durotar habt Ihr heute gute Dienste geleistet.", rewards = "DurotarstulpenGürtel des VereitlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25170] = {title = "Küstensäuberung", objective = "Erhaltet 5 Handvoll Kriechersekret.", description = "Hey, Ihr da! Bom'bay stellt grad mehr Mojo her! Wollt Ihr ein Schlückchen kosten? Oh, davor muss ich aber eh erst noch ein paar Jujus besorgen!\n\nZuerst braucht Bom'bay was von dem Saft von den Krabbenviechern am Wasser. Oh, zeigt mir Eure Hände!\n\n<Bom'bay betrachtet Eure Hände ganz genau.>\n\nMh, bei Euren Händen braucht Bom'bay fünf Handvoll. Geht schon!", progress = "Ihr bringt mir die Jujus und ich lasse Euch mein Mojo kosten.", completion = "Ja, man, das ist das gute Zeug. Jetzt brauchen wir noch andere Jujus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25171] = {title = "Weiterreiten", objective = "Sprecht mit Räuber Jhash, um nach Klingenhügel zu gelangen. Sprecht mit Gar'Thok, sobald Ihr angekommen seid.", description = "Wir müssen unsere Verbündeten in Klingenhügel benachrichtigen. Die Menschen mögen heute besiegt worden sein, doch morgen werden sie wieder da sein und dann werden wir Hilfe von den Orcs brauchen.\n\nSprecht mit Jhash vor den Toren von Sen'jin. Er wird Euch mit seinen Wölfen nach Klingenhügel bringen. Sie kennen den Weg gut.", progress = nil, completion = "Der Troll will, dass wir Hilfe schicken? Pff, das kann er vergessen. Ich habe meine eigenen Menschenprobleme, und selbst die sind gerade meine geringsten Sorgen.\n\nSen'jin liegt zwischen den Echoinseln und dem Tal der Prüfungen. Sicherlich wird der Alte Gadrin genügend junge Krieger finden, die ihm mit dem Einfall der Menschen helfen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25172] = {title = "Eindringlinge in unserer Heimat", objective = "Tötet 7 Späher der Nordwacht.", description = "Ihr seid nicht einfach ein weiterer Grünschnabel - Ihr scheint wirklich <ein/eine:c> <Klasse> zu sein. Gut, denn das ist genau das, was ich brauche.\n\nVersucht, es für Euch zu behalten, denn ich möchte keine Panik verursachen... aber es gibt noch weitere Berichte über Menschen in der Nähe. Das ist eine ungeheuerliche Verletzung des Friedens, den wir mit dieser erbärmlichen Jaina Prachtmeer ausgehandelt haben! Wir können keine Menschen hier in Durotar dulden, erst recht nicht hier im Tal.\n\nIhr findet sie im Süden. Tötet sie schnell, bevor es noch mehr werden.", progress = nil, completion = "Schnell und präzise ausgeführt. Gute Arbeit.", rewards = "AversionsgamaschenArmschienen des HerdverteidigersSpäherjägerwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25173] = {title = "Schlimmer geht immer", objective = "Tötet 6 Marinesoldaten der Nordwacht, 6 Heckenschützen der Nordwacht und Leutnant Palliter in Burg Tiragarde.", description = "Burg Tiragarde liegt südöstlich von hier, an der Ostküste Durotars. Ihr seid wahrscheinlich auf Eurem Weg von Sen'jin daran vorbeigekommen. Die Burg ist mir schon seit Langem ein Dorn im Auge.\n\nMenschen aus Kul Tiras haben jahrelang in der Burg gelebt und jeden meiner Versuche, sie zu erobern, abgewehrt. Nach dem Kataklysmus war die Küste zerstört, und die Burg mitsamt allen Menschen verschwunden. Allerdings haben diese Ankömmlinge aus Nordwacht jetzt ihren Platz eingenommen!\n\n<Gar'Thok brüllt angesichts dieser erschwerten Umstände.>", progress = nil, completion = "Von Eurem Mut wird überall erzählt, &lt;Name&gt;. Geschichten über Euren Sieg in Burg Tiragarde werden selbst in Orgrimmar erzählt.", rewards = "Gamaschen von Kul TirasKlinge aus KlingenhügelWeste von TiragardeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25174] = {title = "Doppelzopf muss es wissen", objective = "Meldet Euch bei General Doppelzopf bei Doppelzopfs Patrouille im Südlichen Brachland.", description = "<General Doppelzopf wird die Einzelheiten dieses feigen Angriffs wissen wollen. Ihr sammelt die Beweise auf.>", progress = nil, completion = "Wie bitte? WIE BITTE?!!!\n\nBael'dun liegt in Trümmern? Leichen überall - nein. Nein!\n\n&lt;Ihr beschreibt die Beweise, die Ihr am Ort des Geschehens vorgefunden habt.&gt;\n\nDie Bilgewassergoblins also, ja? Die wollen Streit haben? Denen werden wir zeigen, was es heißt, Teil der Horde zu sein, und ob. Ich werde die Kriegsnarbe mit ihren Leichen füllen. Ich werde die Erde mit ihrem Blut tränken.\n\n&lt;Doppelzopf packt Euch am Kragen.&gt;\n\nGoblins. Werden. Sterben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25175] = {title = "Schlechte Nachrichten", objective = "Überbringt General Doppelzopf bei Doppelzopfs Patrouille im Südlichen Brachland die schlechte Nachricht.", description = "<Sanft schließt Ihr Marleys Augen.>\n\n<Jemand muss General Doppelzopf mitteilen, dass die Horde seinen einzigen Sohn getötet hat.>\n\n<Dieser Jemand seid Ihr.>", progress = nil, completion = "&lt;General Doppelzopf schleudert seine Axt in den Schmutz. Seine Stimme ist ruhig, aber sein Körper zittert vor Unglaube und Wut.&gt;\n\nDas war mein Junge, &lt;Name&gt;. Mein einziger Junge.\n\nJetzt haben sie es persönlich gemacht, &lt;Klasse&gt;. Persönlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25176] = {title = "Die Situation ausnützen", objective = "Erhaltet 6 Stücke vom Schatz von Kul Tiras.", description = "<Hey, Hübscher! Ich bewundere Euren großen, fleischigen, starken Bizeps schon, seit Ihr in die Stadt gekommen seid!/Was schaut Ihr denn> hässliche Schachtel! Ich weiß, wie Ihr durch Klingenhügel stolziert und versucht, mir MEINE Männer auszuspannen!;\n\nHört her, ich habe etwas für Euch zu tun. Ich habe gehört, dass Gar'Thok Euch nach Tiragarde geschickt hat. Während Ihr dort seid, könntet Ihr für mich vielleicht ein paar der verlorengegangenen Sachen von Kul Tiras besorgen?\n\n<Danke, Süßer!/Fragt nicht> wieso. Ihr könnt froh sein, dass ich überhaupt mit Euch rede!;", progress = "<Gail schnurrt entwaffnend wie ein Kätzchen, als sie Euch sieht.>", completion = "Ihr habt mir den Schatz gebracht! Oh, Ihr seid selber so ein Schatz!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25177] = {title = "Die Strände stürmen", objective = "Tötet 11 schäumende Meereselementare.", description = "Jetzt sind die Menschen erstmal aus dem Weg und wir können uns um richtig wichtige Sachen kümmern.\n\nDer Kataklysmus hat die Ostküste Durotars äußerst stark mitgenommen. Ihr habt selbst gesehen, was aus Tiragarde geworden ist. Und an der Küste östlich von hier ist das Ausmaß noch weitaus schlimmer.\n\nNach der ersten Schockwelle wurde der Strand von wütenden Elementaren eingenommen, die aus dem Meer kamen. Ich habe Grunzer geschickt, um sich um sie zu kümmern, aber es waren zu viele für sie. Ich habe das Gefühl, dass Ihr mehr Erfolg haben werdet.\n\nNehmt Euch aber vor den Gezeiten in Acht!", progress = nil, completion = "Der Geruch des Meeres haftet an Euch, &lt;Name&gt;. Eure Anstrengungen gewähren Klingenhügel einen weiteren Tag.\n\nIch werde bei meinen Vorgesetzten von Euren Taten berichten. Ihr könnt Euch unserer Dankbarkeit sicher sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25178] = {title = "Schiffswracks durchsuchen", objective = "Erhaltet 4 Kisten Gnomenwerkzeuge.", description = "<Hey, Hübscher, willkommen zurück! Es würde Euch nicht stören, noch einmal für mich aufzubrechen, oder? Ich wäre Euch SOO dankbar.../Ihr da! Halt> diebische Elster! Mit Euch bin ich noch nicht fertig!;\n\nIch habe gehört, dass Ihr zur Küste unterwegs seid. Am Strand sind unzählige gestrandete Schiffe, und in den Schiffen sind Gnomenwerkzeuge... die kann ich gebrauchen.\n\n<Bis bald, Muskelprotz!/An die Arbeit> Frollein!;", progress = "Da ist ja mein Ritter in der glänzenden Rüstung!", completion = "Ihr lest einem Mädchen wie mir wirklich jeden Wunsch von den Augen ab, wisst Ihr das? Wenn Ihr jemals etwas von mir braucht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25179] = {title = "Abbau der Verluste", objective = "Rettet 4 verletzte Grunzer von Klingenhügel.", description = "Ihr müsst uns helfen. Die Elementare... sie sind stärker, als man ihnen ansieht, und sie kommen in Massen. Sie haben uns total überrascht und übermannt.\n\nViele meiner Grunzer liegen am Strand im Sterben. Wenn Ihr sie retten könntet... wäre ich Euch so dankbar, und Gar'Thok in Klingenhügel auch!", progress = nil, completion = "Ich habe schon mit ein paar der Orcs gesprochen, die vom Strand zurückgekehrt sind. Alle haben gesagt, dass Ihr sie gerettet habt.\n\nIhr habt heute eine ritterliche Tat vollbracht, &lt;Name&gt;. Lok'tar ogar! Für die Horde!", rewards = "Ihr bekommt:\n\nGrunzerarmschienen aus Klingenhügel"}
MultiLanguageQuestData['de'][25182] = {title = "Tötet sie alle!", objective = "Tötet 10 Minenarbeiter von Frazzelcraz in Frazzelcraz' Hauptader im Südlichen Brachland.", description = "Ich will tote Goblins sehen, <Name>! Direkt westlich von hier findet Ihr ein ganzes Nest dieser kleinen Maden, die sich in den Berg graben.\n\nSorgt dafür, dass es ihr eigenes Grab ist, das sie sich graben!\n\nVernichtet sie. Vernichtet diese gesamte gierige Operation. Sie haben in Bael'dun ihren eigenen Untergang besiegelt, <Klasse>. Es ist Zeit, dass sie ihrem Schöpfer gegenübertreten.", progress = nil, completion = "Tot? Gut!\n\nMöge die Nachricht von dieser Tat sich schnell verbreiten und mit ihr die Angst.\n\nDie Horde wird die Folgen ihres Angriffs auf Bael'dun schon zu spüren bekommen und den Tag bereuen, an dem sich unsere Wege kreuzten, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25183] = {title = "… und vergrabt die Reste", objective = "Macht 6 Sprengsätze von Frazzelcraz in Frazzelcraz' Hauptader scharf.", description = "Sie zu töten reicht einfach nicht. Nach der Katastrophe in Bael'dun will ich, dass diese Goblins ihre eigenen fiesen Machenschaften zu spüren bekommen.\n\nGeht in Frazzelcraz' Mine und macht ein paar Sprengsätze scharf.\n\nAm Eingang der Mine sollte sich eine Art Schalter oder Auslöser befinden. Sobald die Sprengsätze scharf sind, verwendet den Auslöser, um den ganzen Ort in die Luft zu jagen. Versetzt sie in Angst und Schrecken, <Klasse>!", progress = "<Vom Auslöser führen ein paar sehr provisorisch aussehende Drähte in die Mine.>", completion = "&lt;Die Sprengsätze sind scharf und bereit!&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSee Frazzlecraz Cave-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25184] = {title = "Wilder Minenwagenritt", objective = "Reist mit dem Minenwagen an das Ende der Strecke und sprecht mit Assistentin Greely.", description = "Springt einfach auf und sprecht mit Assistentin Greely, wenn Ihr unten angekommen seid.", progress = nil, completion = "Wie wir hier beim Tüftlerverband sagen würden: Vom atmosphärischen tropfenförmigen Niederschlag in den metallischen Weiterleitungsbehälter am Dachlauf.", rewards = "Oxydierende AxtHitzebehandelter metallischer KochbehälterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25185] = {title = "Es ist vollbracht", objective = "Kehrt zu General Doppelzopf an Doppelzopfs Patrouille im Südlichen Brachland zurück.", description = "<Ihr schützt Eure Augen vor der Explosion und dem umherfliegenden Geröll, als die Mine einstürzt.>\n\n<General Doppelzopf wird sehr erfreut sein, aber Ihr bezweifelt, dass das seinen Rachdurst stillen kann.>", progress = nil, completion = "&lt;Doppelzopf nickt, als Ihr die Zerstörung der Mine beschreibt, aber in seinen Augen brennt immer noch kalter Hass.&gt;\n\nSehr gute Arbeit, &lt;Name&gt;. Ich schätze, dass es auch strategische Vorteile gibt, der Horde diese Mineralien zu rauben, aber am zufriedensten macht mich, dass diese kleinen grünen Monster zerquetscht wurden.", rewards = "GoblinminenarbeiterhelmDoppelzopfschulternAuf Euch wartet eine dieser Belohnungen:\n\nFrazzelcraz' Halskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25186] = {title = "Zweckloser Widerstand", objective = "Tötet Kona Donnerlauf an der Grenze zwischen dem Steinkrallengebirge und dem Südlichen Brachland.", description = "<Name>, ich habe nicht die Absicht, Kommandant Singleton meinen Bericht ohne auch nur das geringste bisschen an guten Nachrichten zukommen zu lassen. Wir müssen der starrköpfigen Horde die Kontrolle über diese Straßen entringen.\n\nSoweit ich weiß, ist ihr Anführer Kona Donnerlauf. Er hat ein Lager direkt nördlich von hier. Er ist im Steinkrallengebirge heimisch und kennt diese Straßen so gut wie seine Westentasche. Wenn wir ihn vernichten können, lässt der Widerstand aus dem Westen möglicherweise nach.\n\nFindet und tötet Kona Donnerlauf, dann meldet Euch bei Kommandant Singleton!", progress = nil, completion = "Also unsere Vorräte kommen nicht durch? Hmmm. Die Ehrenwacht wird immer mehr isoliert.\n\nDoch der Sieg über Donnerlauf sollte unseren Feinden ein Signal senden, dass wir die Absicht haben, zu bleiben. Ich danke Euch, &lt;Name&gt;.", rewards = "Handschuhe der EhrenwachtSingletonschärpeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25187] = {title = "In den Fluten verloren", objective = "Benutzt Thonks Handfernrohr, um in der Südstromaue nach Überlebenden zu suchen.", description = "Die Ereignisse, die mit dem Kataklysmus in Verbindung stehen, haben nicht nur ein paar Boote an Land geschwemmt, <Name>. Der Südstrom ist über die Ufer getreten und das gesamte westliche Becken Durotars ist unter Wasser.\n\nDort sind noch immer Leute, die Hilfe brauchen. Ich habe schon eine Zeit lang gesucht, konnte aber nichts finden. Würde es Euch stören, selbst zu schauen?", progress = "Was konntet Ihr sehen?", completion = "Aah, ich verstehe... das KLEINE Ende vom Handfernrohr wird ans Auge gesetzt. Das werd ich mir merken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25188] = {title = "Die Aue patrouillieren", objective = "Sucht die Südstromaue nach den Leuten ab, die Ihr mit dem Handfernrohr gesehen habt und helft ihnen.", description = "Mein Posten ist hier, im Turm, und ich kann meinen Posten nicht verlassen, <Name>. Ich brauche jemanden, der für mich den Leuten hilft, die nach der Überschwemmung des Flusses Hilfe brauchen.\n\nKann ich mich auf Euch verlassen?", progress = nil, completion = "Ich habe den Trick mit dem kleinen Ende vom Handfernrohr benutzt und Euch beim Hin- und Herrennen da unten zugeschaut. Sehr beeindruckend!\n\nOh, wie habt Ihr die alte Frau zum Fliegen gebracht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25189] = {title = "Die Geister seien gelobt", objective = "Begleitet Großmatrone Tekla zu Raggaran.", description = "Wer seid Ihr? Was ist passiert?\n\nIch habe in meiner Hütte meditiert, und...\n\nAh, jetzt erinnere ich mich. Die Geister haben angefangen, zu schreien, und der Fluss trat über die Ufer. Ich kann mich glücklich schätzen, dass Ihr mich hier gefunden habt. Ich bin alt und kann den Elementen nicht mehr so ohne Weiteres standhalten. Werdet Ihr mir hier heraushelfen?", progress = "Meine Großmutter ist hier noch irgendwo...", completion = "Meine Großmutter war einst eine mächtige Schamanin. Ich dachte, sie hätte mit dem Alter ihre Macht verloren, aber manche Dinge behält man wohl für immer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25190] = {title = "Der Zorn Raggarans", objective = "Tötet 4 Stacheleber der Klingenmähnen und 4 Späher der Klingenmähnen.", description = "Die Stacheleber sind ein Schandfleck in der Landschaft, den nicht einmal der übergetretene Strom wegwaschen kann. Mir wurde gesagt, wir sollen evakuieren, aber das konnte ich nicht, weil ich mit meiner Arbeit noch nicht fertig war.\n\nAaarggggh! Ich hasse Stacheleber so unglaublich arg! Helft Ihr mir, sie zu töten?", progress = nil, completion = "&lt;Raggaran scheint sich ein wenig beruhigt zu haben, seit Ihr ihn das letzte Mal getroffen habt.&gt;\n\nGut, gut. Wir sind schon einen Schritt weiter, diese knopfäugigen, korbtragenden, ebernasigen, zweizehigen...\n\n&lt;Raggarans Zorn nimmt offensichtlich wieder zu.&gt;\n\n...gebückt laufenden, schreienden, stachligen, nichtsnutzigen, Gnome mögenden... AAAAAAARGGGH! Stacheleber!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25191] = {title = "Begutachtet die Zerstörung", objective = "Sprecht mit Nibb Spindelgang in Ehrenwacht, um die Zerstörung des Kataklysmus zu vermessen.", description = "Ich habe von unglaublichen seismischen Anomalien hier in Kalimdor gehört, aber ich hatte keinen Schimmer, dass das geologische Chaos so umfassend ist!\n\nIch benötige eine aktuelle Begutachtung der Zerstörung, während ich hier bleibe und die seismographischen Aufzeichnungen auswerte. Könntet Ihr mit meinem vollautomatischen Feldvermessungsfahrzeug ein paar Daten für mich sammeln? Ich kümmere mich um das Fliegen.\n\nWenn die Vermessung erfolgt ist, zeigt die Daten meinem Kollegen Horton Kardanherz in Nordwacht.", progress = nil, completion = "Wie bitte? Seht Ihr nicht, dass wir hier angegriffen werden!\n\n&lt;Kardanherz schnappt sich die Aufzeichnungen aus dem Feldvermessungsfahrzeug und stopft sie willkürlich in eine Art Seesack.&gt;\n\nJa natürlich werde ich mir Nibbs Ergebnisse genau ansehen. Und wenn es nach mir geht, aus der Sicherheit der Östlichen Königreiche heraus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25192] = {title = "Raggaran regt sich auf", objective = "Tötet 5 Staubläufer der Klingenmähnen und 5 Schlachtwachen der Klingenmähnen.", description = "Ich werde nicht ruhen, bis sie besiegt sind! Tötet sie ALLE!\n\n<Raggaran holt tief Luft.>\n\nIhre stinkenden Behausungen sind nördlich von hier, oder südlich von hier!", progress = nil, completion = "&lt;Raggaran scheint, sich etwas beruhigt zu haben.&gt;\n\nIhr habt gute Arbeit geleistet.\n\nEs tut mir leid, dass Ihr mich so aufgebracht sehen musstet. Danke, dass Ihr die Stacheleber getötet habt. Vielleicht solltet Ihr besser gehen, bevor ich wieder anfange, mich aufzuregen.", rewards = "StacheleberstecherStacheleberbalggamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25193] = {title = "Verloren, aber nicht vergessen", objective = "Sammelt 250 Krokiliskenzähne.", description = "Heute ist der Todestag meines Sohnes Kron. Ich habe es ewig nicht zugeben mögen, aber nun weiß ich, dass er nicht von der Krokiliskenjagd heimkehren wird.\n\nIch habe an etwas gearbeitet... etwas, das Krons Leidenschaft für die Jagd darstellt. Eine Halskette mit Krokiliskenzähnen... Reihe um Reihe von Zähnen; ein Schmuckstück, das nur von dem mutigsten jungen Orc getragen werden kann. Ich werde die Kette auf sein Grab legen.\n\nKron war mutig, aber nicht so stark wie Ihr. Könnt Ihr mir die Zähne für seine Kette besorgen?", progress = "Kron wird nicht vergessen werden.", completion = "&lt;Volk&gt;, ich danke Euch. Ich werde sofort an der Kette weiterarbeiten.\n\nVor seinem Tod habe ich für Kron das hier angefertigt. Ich kann damit nichts anfangen, aber Euch könnte es nützlich sein.", rewards = "Handgewebte WesteLiebevoll bestickter GürtelTunika der FeierIhr bekommt:\n\nKrons neuer Jagdbeutel"}
MultiLanguageQuestData['de'][25194] = {title = "Ungebetene Gäste", objective = "Greift 3 launische Ebenenschreiter an, bis sie in Richtung Brachland fliehen.", description = "Keine Sorge, Zen'Taji ist nicht in Schwierigkeiten. Hat nur gelernt, was passiert, wenn der Fluss über die Ufer tritt.\n\nSeht Ihr die großen Vögel, da am Flussufer? Zen'Taji glaubt, die sind in Schwierigkeiten. Durch das Erdbeben und die Flut wurden die Ebenenschreiter auf diese Seite des Stroms gebracht, aber sie können nicht zurückfliegen, und schwimmen können sie auch nicht. Sie haben Angst davor.\n\nWenn sie hier bleiben müssen, werden sie sterben. Zen'Taji mag Gewalt nicht, aber vielleicht könnt Ihr sie angreifen, damit sie sich so arg erschrecken, dass sie auf die andere Seite flüchten. Ja?", progress = "Haut sie einfach ein bisschen. Vertraut Zen'Taji, sie werden fliehen. Es ist echt nicht viel dahinter.", completion = "Hey, ich mag alle Tiere. Ich mag auch große Tiere. Ich mag es nur nicht, wenn Ihr ihnen wehtut... aber es ist ja zu ihrem Wohl.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25195] = {title = "Das Ende dieses Raptors", objective = "Tötet den als Hiebkreischer bekannten Raptor.", description = "Viele Kreaturen starben, als das Wasser in das Tal strömte. Die Raptoren allerdings vermehrten sich und fühlten sich in dieser neu entstandenen Umgebung wohl. Sie sind schlaue Raubtiere und konnten sich vom Unglück anderer Tiere ernähren.\n\nEiner der Raptoren ist besonders grausam. Er tötet die kleinen Tiere und lässt sie im Wasser verrotten - er isst sie nicht mal! Er heißt Hiebkreischer; wenn wir nicht aufpassen, wird er das Gleichgewicht der Natur sehr stören.\n\nReist nach Norden, tötet ihn, und gebt seinen Körper der Natur wieder.", progress = "Raptoren waren schon immer sehr anpassungsfähig.", completion = "Zen'Taji glaubt, dass der Kataklysmus bei Hiebkreischer etwas komisches hervorgerufen hat. Er war nicht immer so gewalttätig und irrational.\n\nIch danke Euch für Eure Hilfe, &lt;Name&gt;. Zen'Taji wird sich nun weiter seinen Naturstudien widmen.", rewards = "Ihr bekommt:\n\nZen'Tajis Umhang"}
MultiLanguageQuestData['de'][25196] = {title = "Die Blockade von Dranosh'ar", objective = "Meldet Euch bei Gor dem Vollstrecker bei der Blockade von Dranosh'ar in Durotar.", description = "Ihr solltet von hier aus nach Norden reisen, <Name>. Sprecht mit Gor dem Vollstrecker bei der Blockade von Dranosh'ar. Er ist mit der Aufgabe beauftragt, die Seestraßen, die nach Orgrimmar führen, zu sichern. Sein Dock ist direkt neben der Knochenhöhle. Ich bin mir sicher, dass er daran interessiert wäre, dort weiterzumachen, wo wir aufgehört haben.", progress = nil, completion = "Ihr seid derjenige, der sich im Alleingang um die Brennende Klinge gekümmert hat? Meine Ohren sind überall, mein Junge, und Neuigkeiten reisen schnell.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25197] = {title = "Der Admiral gibt nicht klein bei", objective = "Meldet Euch bei Admiral Aubrey in der Feste Nordwacht im Südlichen Brachland.", description = "Wie bitte? Ihr wollt hierbleiben, um zu kämpfen? Typisch <Klasse>, will bleiben und gegen die Horde kämpfen, wenn man doch noch die Chance hätte, wegzulaufen.\n\nHört zu, wenn Ihr wirklich Nordwacht retten wollt, solltet Ihr Euch bei Admiral Aubrey im Turm hinter mir melden. Egal, wie sehr ich ihn darum bitte, er behält seine Schiffe für den Kampf hier, anstatt uns alle in Sicherheit zu bringen.\n\nWenn Ihr mich jetzt entschuldigen wollt - ich muss noch fertig packen!", progress = nil, completion = "Ihr habt es gewagt, den ganzen Weg von Ehrenwacht aus hierher zu kommen? Ausgezeichnet, wir können Eure Erfahrung hier brauchen.\n\nSie haben zwar die Mauern durchbrochen, aber Nordwacht wird sich nicht kampflos ergeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25198] = {title = "Winnoa Kiefernwald", objective = "Sprecht mit Winnoa Kiefernwald an der Vendettakuppe im Südlichen Brachland.Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...\n\nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...\n\nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25199] = {title = "Grundbefehle", objective = "Folgt Ausbildungsoffizier Dampfkurbels Befehlen und meldet Euch dann bei Hauptmann Tret Funkdüse zurück.", description = "Hey! Ihr seht aus, als könntet Ihr uns helfen!\n\nWenn Ihr bereit seid, unsere Ziele zu unterstützten, müsst Ihr erst die Grundausbildung absolvieren. Gnomenausbildungen sind brutal und rigoros, also hoffe ich, dass Ihr vorbereitet seid!\n\nGeht zu Ausbildungsoffizier Dampfkurbel, und er wird Euch beibringen, was Ihr wissen müsst. Folgt unbedingt seinen Befehlen, wenn er sie erteilt, oder Ihr werdet es nie schaffen!\n\nAber ich warne Euch: es ist hart da drüben. Falls Ihr durchkommt, meldet Euch wieder bei mir.", progress = nil, completion = "Ihr seid noch in einem Stück? Ihr habt mehr Getriebe unter der Haube als ich gedacht hätte, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25200] = {title = "Schredderangriff", objective = "Tötet 8 Dampfdruckhaie.", description = "Dieser nichtsnutzige Handelsprinz Gallywix hat es irgendwie geschafft, die gesamte Fußbombenmannschaft der Dampfdruckhaie auf der Yacht unterzubringen. Ich habe keinen einzigen von ihnen zu Gesicht bekommen!\n\nJetzt erledigen sie für ihn die Drecksarbeit hier auf der Rodungsfläche. <Name>, Ihr seid <der Held, der/die Heldin> die; für uns den Pokal zurück nach Kezan geholt hat. Ihr müsst sie loswerden!", progress = nil, completion = "Ich kann nicht behaupten, dass ich je ein Fußbombenfan war, aber Ihr bringt mir das Spiel wirklich nahe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25201] = {title = "Die ultimative Fußbombenuniform", objective = "Sammelt 8 Schredderersatzteile.", description = "Schaut, <Kleiner/Kleine>, meine Aufgabe ist, dafür zu sorgen, dass Ihr im Endspiel eine faire Chance habt. Thrall braucht Eure Hilfe im Kampf gegen den Handelsprinzen.\n\nGreely, Hobart und ich haben ein ultimatives Fußbombentrikot zusammengestellt, mit der Ihr das Spiel garantiert gewinnt. Zuerst benötige ich jedoch noch ein paar Dinge.\n\nZu unserem Glück quillt diese Rodungsfläche vor Schredderersatzteilen fast über. Also raus auf den Platz und gebt mir 110%!", progress = "Wollen wir mal sehen, was Ihr da habt, <Name>.", completion = "Ja, die eignen sich hervorragend. Gut gemacht, Kleiner. Ich sorge dafür, dass Ihr das beste Fußbombentrikot aller Zeiten bekommt.\n\nIn der Zwischenzeit habt Ihr andere Bomben, die Ihr auf die Lakaien des Handelsprinzen niedergehen lassen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25202] = {title = "Der schnellste Weg zu seinem Herzen", objective = "Reißt Chip Endale das noch schlagende Herz aus der Brust.", description = "Oh, Mädchen! Ihr werdet nie glauben, wer sich auf der Ölplattform im Norden aufhält.\n\n<Izzy schüttelt traurig den Kopf.>\n\nChip ist da draußen und arbeitet für den Handelsprinzen. Diese kaltherzige Schlange hat Euch wie eine heiße Kartoffel fallenlassen und jetzt arbeitet er auch noch für die anderen. Ich habe sogar gehört, dass er mit diesem Flittchen Vani LeHörnchen ausgeht!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber ich würde ihm sein noch schlagendes Herz aus der Brust reißen.", progress = "Wie habt Ihr Euch entschieden? Tod oder Vergebung?", completion = "Er hat nur das bekommen, was er verdient hat. Na, na, nicht weinen. Ihr findet schon einen anderen, der Euch gut behandelt.\n\nHier, lasst mich das nehmen… Wir wollen ja nicht, dass die Leute denken, Ihr wärt verrückt.", rewards = "KardioextraktorhandschuheChips UmhangHerzschmerzdolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25203] = {title = "Wer heißt denn schon Chip?", objective = "Tötet Chip Endale.", description = "Kumpel! Ihr werdet nie glauben, wer sich auf der Ölplattform im Norden aufhält.\n\n<Ass schüttelt ungläubig den Kopf.>\n\nChip ist da draußen und arbeitet für den Handelsprinzen. Dieser Verräter arbeitet für die anderen. Aber es kommt noch schlimmer! Ich habe gehört, dass er mit Eurer Ex-Freundin Vani LeHörnchen ausgeht!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wenn das meine Ex wäre, würde ich etwas dagegen unternehmen.", progress = nil, completion = "Anders kann man es nicht sagen… Er hat einfach genau das bekommen, was er verdient hat.", rewards = "Handschuhe des ehemaligen DiebesSchneide der EifersuchtWankelmütiger GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25204] = {title = "Ein gelöstes Problem", objective = "Löst die Ventile 1 bis 4.", description = "Wir müssen Handelsprinz Gallywix' Ölversorgung stoppen und seine Maschinen aufhalten.\n\nIhr müsst für uns zur Ölplattform der HGK gehen und die Ventile lösen, um das Kühlsystem zu überlasten. Geht danach zur Plattformsteuerungskonsole und bringt sie zum Explodieren.", progress = "Ihr habt noch nicht alle vier Ventile gelöst. Das Kühlsystem der Plattform funktioniert immer noch mit ganz normalen Parametern.", completion = "Alle Leuchten und Anzeigen auf der Steuerungskonsole spielen verrückt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25205] = {title = "Der Wolf und der Kodo", objective = "Lauscht der Moral der Geschichte von Shin Steinsäule.", description = "Mein \"Kollege\" hier hat Pläne mit Euch, denen ich nicht zustimmen kann. Er ist hastig, unkontrolliert, unverantwortlich und außerdem bezahlt Ihr am Ende vielleicht auch noch mit Eurem Leben.\n\nBevor Ihr mit Gor sprecht, möchte Ich Euch bitten, Euch die Geschichte anzuhören, die ich zu erzählen habe. Es geht bei der Geschichte um ihre Moral - es ist eine Fabel. Ich glaube aber, dass die Moral dieser Geschichte für Euch sehr wertvoll sein könnte. Sprecht mit mir, wenn Ihr sie hören möchtet.", progress = "Achtet auf die Bedeutung hinter den Worten, mein Kind.", completion = "Die Moral der Geschichte: Voreilige Handlungen, die aus Faulheit getätigt wurden, können ein böses Ende nehmen. Wir sollten den Lauf der Dinge nicht überstürzen... wir müssen uns unsere Belohnungen verdienen. Ich habe versucht, dem Vollstrecker diese Geschichte zu erzählen, aber sein Höllschrei-verehrender Schädel hat sie einfach nicht verstanden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25206] = {title = "Die Warnungen nicht beachten", objective = "Zerstört 12 verfeindete Elementare. Ihr könnt wütende Erdwächter oder belebte Wasserwächter töten.", description = "Ihr könnt die Worte des Schamanen ignorieren, <Soldat/Soldatin>. Es gibt gewisse Leute in der Horde, die auf unsere Zusammenarbeit bestehen. Ich kann Euch aber versichern, dass dieser Thrall-verrückte Scharfseher nicht einmal über seine eigene Hutspitze sehen kann.\n\nDie Elementare führen westlich von hier miteinander Krieg. Normalerweise wäre mir das egal, aber ich brauche dieses Gebiet, um die Schiffstraße von hier ins Brachland zu vergrößern. Die Elementare sind normalerweise recht stark, aber durch ihre Kämpfe miteinander sind sie geschwächt. Mit diesem Wissen sollte es Euch ein Leichtes sein, sie zu zerstören.", progress = nil, completion = "Seht Ihr? Die Geschichten des Schamanen sind nicht mehr als... eine Bettgeschichte für einen Jüngling. Die neue Horde nimmt sich, was sie will, und verschwendet mit solchem Schwachsinn nicht ihre Zeit.\n\nFalls Ihr dazu kommt, könnt Ihr ja Shin... und auch allen anderen, die sein Verhalten unterstützen... sagen, dass sie Eure Zeit nicht vergeuden sollen.", rewards = "Gedankenlose ArmschienenUnvorsichtige TreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25207] = {title = "Macht die Plattform platt", objective = "Drückt den großen roten Knopf auf der Ölplattform der HGK.", description = "Auf der Konsole ist ein einzelner großer, roter Knopf. Wenn es Knöpfe gibt, die große Explosionen auslösen, sehen sie ganz sicher so aus!", progress = nil, completion = "Ich habe die Hitze der Explosionen bis hierher spüren können!", rewards = "Stiefel des DemolierersÖlbefleckte GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25208] = {title = "Berichtet Silvia", objective = "Sprecht mit Silvia am Turm von Estulan.", description = "Es scheint, als haben wir eine Plage gefunden, die um einiges schlimmer ist als die, mit dir wir gerechnet hatten. Cho'gall versucht zweifellos, durch die Gordok Zugang zu den Überresten Eldre'Thalas' in Düsterbruch zu erlangen, ein Ort voller verbotener Mächte, die den Fall von Shen'dralar hervorriefen...\n\nIch schweife zu sehr aus. Geht, <Name>. Berichtet Silvia von dem, was ich Euch erzählt habe. Was auch immer in Düsterbruch vor sich geht, muss aufgehalten werden.", progress = nil, completion = "Ihr seid zurückgekehrt. Was hat Estulan gesagt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25209] = {title = "Bedrohung durch die Gordunni", objective = "Tötet 16 Oger der Gordunni in der Oberen Wildnis.", description = "In der Oberen Wildnis südlich von hier befinden sich viele uralte Ruinen. An diesem Ort haben die Vorfahren der Nachtelfen sich an der arkanen Magie versucht und die Oger der Gordunni streifen dort umher, um Überreste dessen ausfindig zu machen.\n\nIhr werdet bemerken, dass der Wald dort komplett zerstört wurde; die Oger hinterlassen nichts als Schlamm und entziehen der Horde dadurch wertvolle Ressourcen.\n\nGeht und tötet die Gordunni, <Name>. Sichert das Gebiet für die Horde, für die Horde allein!", progress = nil, completion = "Ihr habt Euch als vertrauenswürdig und verlässlich herausgestellt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25210] = {title = "Zeichen des Wandels", objective = "Sammelt 8 infizierte Hirschgeweihe.", description = "Eine üble Krankheit hat die Kreaturen unseres Waldes heimgesucht. Zuerst dachte ich, es wäre einfach eine der Tücken der Natur, aber der Krankheit scheint kein Heilungsprozess zu folgen.\n\nDie Hirsche des Waldes, die normalerweise sehr stark und friedlich sind, haben am meisten gelitten. Einige finden in ihrer Schwäche ihr Ende. Andere sind tollwütig und sehr gefährlich. Um die Geister zu befragen und mehr über die Krankheit in Erfahrung zu bringen, benötige ich die Geweihe der Hirsche.", progress = "Es ist keine schöne Aufgabe, aber es muss getan werden, <Name>.", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde die Geweihe untersuchen. Seitdem Ihr Euch auf den Weg gemacht habt, hat sich die Lage verschlimmert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25211] = {title = "Die Behausung säubern", objective = "Tötet 5 Orcs des Drachenmals in Dun Algaz.", description = "Hört nicht auf Rharen. Er ist so verwirrt, wie man nur sein kann. Es ist sein Fehler, dass das gesamte Bier erbeutet wurde!\n\nAußerdem bin ich davon überzeugt, dass es hier noch ein größeres Problem als nur gestohlenes Bier gibt. Die Tatsache, dass nach all den Jahren hier eine Gruppe Orcs um Dun Algaz herumrennt ist lächerlich!\n\nIch sag' Euch was, <Klasse>. Ihr geht dort hinein und vertreibt so viele Orcs wie Ihr könnt aus diesen Ruinen. Dun Algaz taugt nicht mehr zu viel, aber ich will verflucht sein, wenn wir sie dort einfach sitzen lassen.", progress = "Na kommt schon, strengt Euch ein wenig an! Ich kann sie immer noch von hier aus riechen!", completion = "Das wird ihnen eine Lehre sein! Gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25212] = {title = "Am Rande der Schächte", objective = "Benutzt Pilot Sprossmündungs Flugmaschine, um Radiageigatrons auf die Luftschächte um Gnomeregan herum zu werfen.", description = "Wir dachten, wir könnten warten, bis die Strahlung um Gnomeregan nachlässt, aber es scheint nicht besser zu werden.\n\nWenn wir unsere Stadt zurückerobern wollen, müssen wir sicherstellen, dass unsere Truppen sie unbeschadet betreten können.\n\nNehmt diese Radiageigatrons, schnappt Euch die Donnerschlag hier und werft sie auf die Lüftungsschächte außerhalb von Gnomeregan. Sie werden die Strahlenbelastung direkt an mich übermitteln.", progress = nil, completion = "Großartige Arbeit!\n\nDie Daten, die ich bekommen habe, zeigen, dass die Strahlenwerte völlig im Sicherheitsbereich unserer Anzüge liegen. Das sind exzellente Neuigkeiten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25213] = {title = "Die Sklavengruben", objective = "Sprecht mit Sassy Hartzang bei den Sklavengruben.", description = "Der Trainer hat uns gesagt, dass Sassy sich drüben bei den Sklavengruben aufhält. Es sind ein paar Orcs bei ihr, die sich auf einen Angriff auf den Handelsprinzen vorbereiten.\n\n<Name>, Ihr solltet die Straße entlang nach Südwesten gehen und sie suchen. Sie möchte ganz sicher, dass Ihr den Angriff leitet!", progress = nil, completion = "Ich habe mich schon gefragt, wo Ihr bleibt!\n\nKeine Sorge. Hobart wird dieses Fußbombentrikot in das ultimativste Fußbombentrikot aller Zeiten verwandeln!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25214] = {title = "Flucht nach oben", objective = "Benutzt die einstufigen Trägerraketen, um die Käfige von 8 Bürgern von Kezan oder überlebenden Goblins in die Luft zu schießen.", description = "Wir haben wirklich keine Zeit, um all die zu retten, die so dumm sind, sich immer und immer wieder einfangen zu lassen. Ich habe jedoch noch ein paar Raketen übrig, sodass wir dieses Problem ganz leicht aus der Welt schaffen können.\n\nBringt diese einstufigen Trägerraketen zu den Sklavengruben im Norden und befestigt sie an den Käfigen.\n\nDer Käfig wird abheben, und so können wir diese Idioten im Handumdrehen befreien.", progress = nil, completion = "Ups. Nun ja, runter kommen sie alle.", rewards = "Rakentreibstoffgetränkte ArmschienenPanzerrüstung des KäfigstartersOrbitalgamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25215] = {title = "Ein ablenkender Geruch", objective = "Zerrt 3 tote Räuber des Zin'jatar in das offene Meer über der Glimmertiefenschlucht im Süden.", description = "Raubtiere riechen diese toten Naga schon fast aus einer Meile Entfernung. Bald werden wir kämpfen müssen, nur um in die Höhle hinein oder hinaus zu kommen. Wollt Ihr mir nicht helfen, aufzuräumen?\n\nDirekt jenseits des Riffs im Süden findet Ihr die Glimmertiefenschlucht. Wenn Ihr die Leichen dorthin schleift und sie im Wasser loslasst, werden die Wildtiere sie beseitigen, noch bevor sie am Meeresgrund angelangt sind. Versucht nur, den Haien so gut wie möglich auszuweichen.", progress = nil, completion = "Es sollte nicht lange dauern, das Wasser zu reinigen. Danke für Eure Hilfe.", rewards = "WendeltreppenschneckenbeinplattenAquaflammtaillenschutzGugel der LeptocheliaDer folgende Zauber wird auf euch gewirkt:\n\nTargeted Remove See Invis 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25216] = {title = "Der große Sambino", objective = "Sucht nach \"Sam\" am westlichen Ende des Silberflutgrabens.", description = "Falls Ihr Euch auf den Weg hinab in den Graben macht, könntet Ihr mir einen Gefallen tun und nach einem unserer neueren Mitglieder sehen.\n\nSein Name ist Sam, aber er hat die Angewohnheit, seinen Namen ein wenig auszuschmücken. Er hat noch nicht so recht verstanden, was die Mitglieder des Irdenen Rings ausmacht, aber er gibt sich viel Mühe, daher sehen wir es ihm nach.\n\nLasst Euch nicht zu sehr einwickeln, ihm bei seinen verrückten Plänen zu helfen. Schaut einfach nur nach, ob er unversehrt ist und lasst es mich wissen, damit ich beruhigt bin.", progress = nil, completion = "Ein weiterer Bewunderer des großen Sambinos! Seid Ihr den ganzen weiten Weg gekommen, damit ich Euch ein Autogramm gebe? Ich bin viel zu beschäftigt, um irgendetwas zu unterschreiben. Hinfort mit Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25217] = {title = "Totemmodifikation", objective = "Stellt eines von Sambinos modifizierten Totems im Sand des Silberflutgrabens auf.", description = "Na gut, weil Ihr mich so verzweifelt anschaut, lasse ich Euch an meiner echten Arbeit teilhaben.\n\nDieser Fels ist noch völlig unerschlossen! Wahrscheinlich schlummern hier größere Reichtümer als in der Schatzkammer eines Handelsprinzen während eines großen Krieges! Ich brauche Proben. Mehr Proben. Proben von überall!\n\nIch habe meine Erdtotems so modifiziert, dass die sich durch den Sand graben und Felsproben aus dem Boden darunter aufnehmen. Geht und sucht einen geeigneten Ort, um eines davon aufzustellen.\n\nDas Zittern und Rumpeln lockt sicher all die süßen, neugierigen Wildtiere an. Da könnt Ihr gleich noch neue Freundschaften schließen!", progress = "Bah! Ich habe Sand im Helm. Das juckt!", completion = "Eine weitere Probe. Ausgezeichnet! Die felsigen Reichtümer des Meeres werden bald mir gehören!", rewards = "BohrschablonengürtelSambinos alter HammerFelsbissschnitzlerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25218] = {title = "Unterwasserinflation", objective = "Füllt einen von Sambinos Luftballons und findet das verloren gegangene Luftventil.", description = "Na gut! Na gut. Ihr habt mich überredet. Ihr dürft mir helfen.\n\nIch verliere mehr Luft als ein mit Stachelebern gefüllter Zeppelin. Mein Luftventil muss sich irgendwo im Graben gelöst haben.\n\nIch habe ein paar Ersatzballons dabei. Macht Euch nützlich und füllt einen auf, ja? Und findet mein Ventil! Das brauche ich natürlich auch.\n\nIch wette, die Krebse haben es gestohlen... Kneifende, gierige kleine Biester...", progress = "Wenn Luft nur nicht so… luftig wäre! Oder wenn es für diese Wasseratmungszauber wenigstens schicke Helme gäbe! Eines von beidem würde mir schon reichen.", completion = "Wisst Ihr, ich hätte Euch einen Gürtel mit Gewichten geben sollen, damit Ihr nicht einfach mit dem Ballon und allem davontreibt. Zum Glück hattet Ihr ja Eure Rüstung und so an. Ha!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn Air Balloon\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25219] = {title = "Nicht verschnecken", objective = "Sammelt 10 Spiralmuschelknochenwühler.", description = "Ich untersuche Schnecken.\n\nJa. Schnecken. Wenn Ihr mit Lachen fertig seid, könnt Ihr mir ja vielleicht helfen.\n\nSicher ist Euch die gigantische Schnecke am Riff aufgefallen. Nun, ich bin mir sicher, dass etwas darin steckt. Es gibt dort mehrere Punkte, die eigentlich nur Einmündungen oder Eingänge sein können. Außerdem habe ich gesehen, wie diese Knochenwühler sich dort hinein und hinaus quetschen.\n\nIch dachte, wir können diese Schnecken vielleicht benutzen, um uns selbst Zugang zu verschaffen. Zumindest ist das die Theorie.", progress = "Ich weiß, das ist nicht gerade die erstrebenswerteste Aufgabe, aber seid Ihr nicht auch neugierig, was es mit dieser Schnecke auf sich hat? Sie ist so riesig! Da muss doch mehr dahinter stecken.", completion = "Danke. Ehrlich. Wenn noch ein Gestrandeter mich ausgelacht hätte, hätte ich vor lauter Zorn sicher jemanden gemeuchelt.\n\nIch lasse es Euch wissen, sobald mir etwas einfällt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25220] = {title = "Glitschige Bedrohung", objective = "Tötet 12 Spitzzahnaale.", description = "Wurdet Ihr schon von den Aalen an den Riffen angegriffen? Wenn nicht, dann wird es noch passieren, so viel steht fest. Das sind bösartige, blutdurstige kleine Monster. Und es scheint ihnen auch ganz egal zu sein, wen oder was sie beißen.\n\nWenn Ihr hinaus in das Tal geht, wäre ich Euch sehr dankbar, wenn Ihr ihre Zahl etwas dezimieren würdet. Nicht alle hier sind so gut ausgerüstet wie Ihr. Uns könnten sie vielleicht mehr als nur Kratzer zufügen.", progress = nil, completion = "Vielen Dank, &lt;Klasse&gt;. Es gibt immer noch viele größere Raubtiere, auf die wir achten müssen, aber wenigstens sind wir jetzt um die Höhle herum etwas sicherer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25221] = {title = "Verfolgungsjagd", objective = "Benutzt Toshes Jagdspeer, um 20 fliehende Naga des Zin'jatar zu töten.", description = "Sie entkommen!\n\nDas sind die gleichen Naga, die die Boote angegriffen und unsere Freunde verschleppt haben. Wir dürfen sie nicht entwischen lassen!\n\nNehmt diese Speere und verfolgt sie auf Eurem Seepferdchen. Verschwendet keine Zeit mit Absteigen. Heftet Euch einfach an ihre Fersen und tötet alle, die Ihr erwischen könnt, mit den Speeren.\n\nIch versuche inzwischen, den Tiefenlord zu stellen. Wenn Ihr fertig seid, sucht mich am Ende des Riffs auf.", progress = "Unsere anderen Verbündeten sind alle in der Höhle unter uns. Von hier aus gesehen scheint alles sicher zu sein, aber genau kann man das nie sagen.\n\nHabt Ihr getan, worum ich Euch gebeten habe?", completion = "Schnelle Arbeit. Sehr beeindruckend.\n\nDieser Tiefenlord ist entkommen. Ich sehe ihn nirgends. Ganz gewiss finden wir über ihn unsere gefangenen Freunde.\n\nIch werde ihn verfolgen. Lange kann er sich nicht verstecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25222] = {title = "Die Silberfluthöhle", objective = "Sucht nach Felora Feuerkranz in der Silberfluthöhle.", description = "Ein Großteil des Irdenen Rings, der dem Massaker auf den Booten entkommen ist, hat in einer Höhle nahe dem Riff Zuflucht gefunden. Sie ist gut versteckt in einer riesigen Felsformation westlich von Nespirah, der riesigen Schnecke am Horizont. Bitte geht für mich dorthin und seht nach, ob es ihnen gut geht. Zudem kann es gut sein, dass auch sie unter den Nagaangriffen leiden.\n\nIch werde diesen Tiefenlord jagen. Wenn ich herausgefunden habe, hinter welchem Felsen er sich versteckt, lasse ich es Euch wissen.", progress = nil, completion = "Ein freundliches Gesicht! Willkommen!\n\nSehr nett von Euch, dass Ihr nach uns seht. Uns geht es gut. Ein Spähtrupp der Naga hat uns gefunden, aber ich bin mir ziemlich sicher, dass keiner entkommen konnte. Wir sollten vorerst in Sicherheit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25223] = {title = "Feuerprobe", objective = "Besiegt 8 feurige Instrukteure.", description = "Ich würde ja gerne sagen, dass wir angesichts des wachsenden Widerstands gegen uns auf dem Hyjal für jeden Rekruten dankbar sind, der uns bei unserer Sache unterstützt und so weiter… aber um ganz ehrlich zu sein, sind die meisten von Euch einfach nur eine Last.\n\nWenn ich eine Kupfermünze für jedes Landei bekommen hätte, das vom Kataklysmus so verängstigt wurde, dass es sich uns jetzt unbedingt anschließen möchte... nun, sagen wir einfach, ich wäre eine reiche Frau.\n\nZum Glück haben wir ein paar Prüfungen vorbereitet, mit denen wir die Spreu vom Weizen trennen können. Geht und beweist Euren Wert an den feurigen Instrukteuren da unten. Hoffentlich schlagt Ihr Euch besser als die anderen.", progress = nil, completion = "Ich schätze, Eure Fähigkeiten sind… geeignet. Ich bin beeindruckt.", rewards = "Brustschutz der außergewöhnlichen ErwartungenBeeindruckende SchienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25224] = {title = "In voller Blüte", objective = "Besorgt 5 Flammenblüten.", description = "Es ist Brauch, dass neue Rekruten schwierige oder manchmal sogar unmögliche Aufgaben erhalten. Ich wurde losgeschickt, um die Schuppe eines schwarzen Drachen zu beschaffen, der Instrukteur letztes Jahr forderte die Feder eines Phönix'.\n\nIhr habt es dieses Mal vergleichsweise einfach. Besorgt mir eine Handvoll Flammenblüten.\n\nSie wachsen hier in der Gegend relativ zahlreich. Oh, fast hätte ich es vergessen. Damit die Sache interessant bleibt, streift ein gigantischer Kernhund über die Felder. Gebt Euer Bestes, um ihm auszuweichen.", progress = "Ja, Kunrebidamus?", completion = "Also habt Ihr es geschafft, diesen Teil des Tests zu bestehen, ohne von Loderos gefressen oder von den Feuerelementaren in Brand gesetzt zu werden?\n\nIch schätze, dann sollte ich Euch zum Aufstieg in den niedrigsten Rang unserer Hierarchie gratulieren.\n\nAlso: Herzlichen Glückwunsch, Rekrut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25227] = {title = "Thonk", objective = "Meldet Euch bei Thonk im Wachturm nordwestlich von Klingenhügel.", description = "<Hey Süßer, mir ist gerade noch was eingefallen!/Entschuldigt mein Verhalten. Ich werde manchmal zickig> wenn neue Frauen in die Stadt kommen, weil ich nicht sehr selbstsicher bin, was mein Äußeres betrifft.; Ich habe einen SEHR guten Freund, Thonk; er arbeitet im Wachturm nordwestlich von Klingenhügel. Er meinte, dass der Fluss über die Ufer getreten sei und dass es viel Arbeit gäbe. Ich hab ihm nicht wirklich zugehört... seine tiefbraunen Augen lenken mich immer ab.\n\n<Wie, eifersüchtig? Ich soll mich nicht mit anderen treffen?/Danke.>", progress = nil, completion = "Gail hat Euch geschickt? Hat sie... hat sie etwas über mich gesagt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25229] = {title = "Eine Frage der Gnomenehre", objective = "Werbt mit Hilfe des Motivieratron Gnome aus Tüftlerstadt an und führt sie zu Hauptmann Tret Funkdüse bei Stahlrosts Depot.", description = "Unsere Ingenieure haben daran gearbeitet, unsere Kampfmaschinen für den Sturm auf Gnomeregan vorzubereiten, aber uns fehlen Piloten!\n\nUnsere Ingenieure haben ein Gerät namens Motivieratron entwickelt, das Ablenkungen verhindert und dem Gnom den Mut verleiht, sich einzuschreiben.\n\nWenn Ihr ein paar Gnomenbürger motiviert habt, führt sie zu Hauptmann Tret Funkdüse, draußen bei Stahlrosts Depot südlich von Eisenschmiede.\n\nOh, und seid vorsichtig. Das Gerät ist noch ein wenig experimentell.", progress = nil, completion = "Das sind die besten zukünftigen Piloten, die Ihr finden konntet?\n\nNa gut, mal sehen, was ich tun kann. Man sagt mir nach, ich könne auch den größten Klumpen verbogener Zahnräder in eine schnurrende Kampfmaschine verwandeln, und ich erwarte von diesem Haufen nicht weniger.\n\nTja, schätze, es ist Zeit, an die Arbeit zu gehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25230] = {title = "Mehr als Krankheit", objective = "Tötet 10 giftige Welpen.", description = "Wir haben ein paar Drachenwelpen in der Nähe der Straße gefunden, die nach Norden führt. Die Welpen leiden an der gleichen Krankheit wie die Hirsche.\n\nGründrachen sind nicht einfache Bestien der Natur, sondern magische Kreaturen und die Wächter der Wildnis. Ihre Krankheit stellt für uns eine Bedrohung dar.\n\nWir müssen dafür sorgen, dass sich die Krankheit auf keinen Fall weiter ausbreitet. Tötet die erkrankten Welpen, <Name>, und kehrt dann zu mir zurück.", progress = nil, completion = "Die neuesten Entwicklungen besorgen mich sehr. Die Geweihe, die ich in Eurer Abwesenheit untersucht habe, haben ein paar Erkenntnisse zu Tage gebracht.\n\nWir müssen einen Weg finden, dieses Problem zu lösen...", rewards = "RunentotemstabSmaragdener SchleierGrünwelpenschulterschutzKonus KettenrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25232] = {title = "Die Brennende Klinge", objective = "Erhaltet 6 Zauberschriftrollen von den Mitgliedern der Brennenden Klinge in der Staubwindhöhle.", description = "Ich wurde geschickt, um die Anwesenheit der Anhänger der Brennenden Klinge in Durotar zu untersuchen. Nordöstlich von hier ist eine Höhle, in der die Klinge ihre neuen Mitglieder ausbildet. Ich möchte wissen, was genau diese Ausbildung der Neophyten beinhaltet.\n\nIch erzähle Euch das eigentlich nur, weil ich das Gefühl habe, Ihr seid auf der Suche nach Arbeit. Wenn Ihr ein wenig verdienen wollt, so begebt Euch zur Höhle und bringt mir ihre Schriftrollen.\n\nDie Höhle ist etwas versteckt: Verlasst Klingenhügel in Richtung Osten und folgt dann dem östlichen Kamm der Schlucht.", progress = "Die Schriftrollen, <Name>, die Schriftrollen!", completion = "Das ist wirklich interessant. Diese Rituale sind nicht wirklich anders als die, die den Hexenmeistern der Horde beigebracht werden. Ich muss auf jeden Fall weitere Untersuchungen anstellen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25233] = {title = "Das Ende der Versorgungslinie", objective = "Tötet 4 Zwielichtordner in der Wolfsschlucht auf dem Hyjal.", description = "Cho'galls Zwielichtordner schwören einen Bluteid, dass sie ihre Vorräte bis an die Front schaffen. Sie geloben sogar, für jedes nicht gelieferte Pfund Vorräte mit einem Pfund ihres eigenen Fleisches zu bezahlen. Sie würden lieber sterben als zu scheitern.\n\nSorgt dafür, dass sie beides tun.", progress = nil, completion = "Gut gemacht! Das Chaos, das wir hier anrichten, wird sich durch die gesamte Befehlskette ziehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25234] = {title = "Arme Deppen schleppen", objective = "Sammelt 36 Versorgungsgüter des Schattenhammers, die von befreiten Zwielichtsklaven zurückgelassen wurden.", description = "Gefangene des Schattenhammerklans werden dazu gezwungen, verschiedene für den Krieg benötigte Dinge wie Packtiere herumzuschleppen. Ich will diese Vorräte - und wenn wir dabei ein paar arme Seelen aus den Klauen des Schattenhammers befreien können, umso besser.\n\nTötet die Sklaventreiber entlang der Straße im Süden und die Sklaven in ihrer Nähe sollten in der Lage sein, zu entfliehen.\n\nDurchsucht die Rucksäcke, die sie hinterlassen, nach wertvollen Dingen und zerstört alles, was Ihr nicht tragen könnt.", progress = "Habt Ihr da unten ein wenig Zerstörung angerichtet, <Name>?", completion = "&lt;Jadi tritt eine der Kisten mit dem Fuß auf und zieht einen geschwungenen Dolch daraus hervor. Sofort fängt sie an zu wimmern.&gt;\n\nAutsch! Verdammt! Dieses Metall ist verflucht. Es beißt!\n\n&lt;Als der Dolch zu Boden fällt, zerspringt er in tausend Stücke, als wäre er aus dünnem Glas.&gt;\n\nWas für eine geisteskranke Schmiedekunst ist das? &lt;Name&gt;, ich bin noch nie zuvor auf solch einen Feind getroffen.", rewards = "Rostbeschriebene GamaschenWiederverwerteter ZwielichtgurtAuf Euch wartet eine dieser Belohnungen:\n\nScharfzahnsiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25235] = {title = "Vulgäres Vul'Gol", objective = "Tötet 15 Oger der Splitterfäuste.", description = "Grüße, <Klasse>. Wollt Ihr die Bewohner von Dunkelhain unterstützen?\n\nDirekt hinter dieser Hügelkuppe da drüben gibt es einen riesigen Ogerhort. Die Oger der Splitterfäuste bleiben normalerweise unter sich, aber sie haben die schlechte Angewohnheit, Reisende zu überfallen. Gerade neulich habe ich gesehen, wie einer das Pferd eines armen Mannes fortgeschleppt hat, um es zu fressen... Zum Glück hat er ihn nicht mitgenommen!\n\nDie Nachtwache möchte das Leben ihrer wenigen Mitglieder, darunter auch meines, jedoch nur für dringlichere Bedrohungen riskieren. Wenn Ihr ein paar dieser Oger für mich töten würdet, würde ich Euch für Eure Tat belohnen.", progress = "Wenn Ihr lieber im Lager herumlungern und Euch ein, zwei Bierchen genehmigen wollt... nun, vorschreiben kann ich Euch nichts.", completion = "Ich habe von hier aus gesehen, wie Ihr ein paar von ihnen den Garaus gemacht habt. Gute Arbeit.\n\nHiermit überreiche ich Euch im Namen der Nachtwache Eure Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25236] = {title = "Donner von unten", objective = "Befestigt die Magiestoffleine an 8 ertrunkenen Donnerechsen im Donnergrat.", description = "Unsere Armee braucht Wasser, und das haben wir dank der Elemente nach dem Kataklysmus jetzt reichlich. Das Wasser, das die Schlucht südwestlich von hier gefüllt hat, sollte ausreichen.\n\nLeider sind die Leichname der Donnerechsen noch überall unten in der Schlucht, und die elektrischen Stöße, die sie von sich geben, sind ein bisschen gefährlich. Ich habe Grunzer, die sie aus dem Wasser ziehen können, aber ich brauche jemand, der geschickt genug ist, sie am anderen Ende des Seils zu befestigen. Seid Ihr <der Mann, den/die Frau> die; ich suche?", progress = nil, completion = "Die Elektrizität der Echsen war nur eine Gefahr. Wenn die Kadaver zu lange im Wasser geblieben wären und weitergerottet hätten, wäre das Wasser bald nicht mehr trinkbar gewesen.\n\nIhr habt gute Arbeit geleistet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25237] = {title = "Tränen der Steine", objective = "Sammelt 7 Steintränen.", description = "Ihr habt gehört, wie der Drache Ysondre uns erklärt hat, dass die Tränen des Landes das Portal schließen können, aus dem die Verderbnis strömt.\n\nVor einigen Wochen habe ich in dem Tal westlich von hier gesehen, dass es den Bergriesen schlecht ging. Sie waren wild vor Frustration, und als sie weinten, wurden ihre Tränen, die auf die Steine fielen, zu Kristallen.\n\nDie Riesen weinen zwar nicht mehr, aber diese Steintränen sind wohl das, was Ysondre gemeint hat - eine Quelle reiner Natur. Wir brauchen diese Tränen.", progress = "Die Tränen sind auf den Steinen, aus denen die Riesen entstanden. In der Nähe der Monolithen am Fuß des Berges sollten lose Tränen zu finden sein.", completion = "Ich danke Euch erneut, &lt;Name&gt;. Ich werde die Tränen für unsere letzte Aufgabe vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25239] = {title = "Weg der Macht", objective = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", description = nil, progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der großen Macht"}
MultiLanguageQuestData['de'][25240] = {title = "Weg der Macht", objective = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", description = nil, progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "Ihr stellt Euren Wert wieder unter Beweis, &lt;Name&gt;. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", rewards = "Ihr bekommt:\n\nÄschernes Band der unvergleichlichen Macht"}
MultiLanguageQuestData['de'][25241] = {title = "Das verderbte Land", objective = "Tötet 7 verderbte Klippenriesen.", description = "Die Klippenriesen von Feralas sind Ausläufer der Erde selbst, <Name>. Wenn es der Natur gut geht, so sind sie wohlwollende Beschützer und friedliche Wächter.\n\nDoch wenn der Wald leidet, so leiden auch sie.\n\nWenn sie von dieser Krankheit heimgesucht und verderbt wurden, so werden sie sich gewaltvoll gegen die Wildtiere und selbst gegen Ihresgleichen richten und so für großflächige Zerstörung sorgen.\n\nZerstört alle verderbten Riesen, die Ihr finden könnt.", progress = nil, completion = "Die Geister der Beschützer werden wieder zurückkehren, &lt;Name&gt;. Ihr habt sie befreit und nun können sie im Kreislauf der Natur ihre Wege gehen.\n\nJetzt liegt es an uns, sicherzustellen, dass der Kreislauf frei von Verderbnis und grundlosem Schmerz ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25242] = {title = "Weg der Macht", objective = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", description = nil, progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "&lt;Name&gt;. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nEs wird gemunkelt, dass die Lakaien der Geißel Euch mehr fürchten als den Lichkönig selber.", rewards = "Ihr bekommt:\n\nÄschernes Band der endlosen Macht"}
MultiLanguageQuestData['de'][25243] = {title = "Sie liebt mich, sie liebt mich NICHT!", objective = "Reißt Vani LeHörnchen das wankelmütige Herz aus der Brust.", description = "Oh, Süßer! Ihr werdet nie glauben, wer sich in den Sklavengruben im Norden aufhält.\n\n<Sassy schüttelt traurig den Kopf.>\n\nVani ist da unten und arbeitet für den Handelsprinzen. Diese kaltherzige Schlange hat Euch wie eine heiße Kartoffel fallenlassen und jetzt arbeitet sie auch noch für die anderen. Seit Ihr Euch um Chip \"gekümmert\" habt, trifft sie sich mit dem Handelsprinzen!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wenn Sie meine Ex wäre, würde ich ihr das wankelmütige Herz aus der Brust reißen.", progress = "Wie habt Ihr Euch entschieden, Herzchen?", completion = "Ich bin mir sicher, dass sie es verdient hat, &lt;Name&gt;. Sie hätte Euch einfach nicht betrügen dürfen.\n\nMir läuft es eiskalt den Rücken hinunter, wenn ich daran denke, dass sie dieses Monster, den Handelsprinzen, vielleicht sogar geküsst hat!", rewards = "KardioextraktorhandschuheKaras UmhangHerzschmerzdolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25244] = {title = "Wer heißt denn schon Vani?", objective = "Tötet Vani LeHörnchen.", description = "Diese Vani LeHörnchen ist nicht zu fassen! Bis Ihr Euch um Chip \"gekümmert\" habt, war sie mit ihm zusammen. Und jetzt trifft sie sich mit dem Handelsprinzen!\n\nIch kann es immer noch nicht fassen, dass sie Euch einfach so Euren Ex ausgespannt hat. Vielleicht solltet Ihr zu den Sklavengruben gehen und diesem hinterhältigen Miststück ein für alle Mal die Leviten lesen!", progress = nil, completion = "Das geschieht ihr Recht! Schließlich hat sie Euch den Mann geklaut!", rewards = "Schneide der EifersuchtWankelmütiger GürtelHandschuhe des ehemaligen DiebesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25246] = {title = "Gesinnungswandel", objective = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", description = nil, progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", completion = "Möget Ihr finden, was Ihr suchet, Bruder.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der endlosen ZerstörungÄschernes Band der endlosen WeisheitÄschernes Band des endlosen MutesÄschernes Band der endlosen Rache"}
MultiLanguageQuestData['de'][25247] = {title = "Gesinnungswandel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der WeisheitÄschernes Band der ZerstörungÄschernes Band des MutesÄschernes Band der Rache"}
MultiLanguageQuestData['de'][25248] = {title = "Gesinnungswandel", objective = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", description = nil, progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, <Name>?", completion = "Möget Ihr finden, was Ihr suchet, Bruder.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der großen WeisheitÄschernes Band der großen ZerstörungÄschernes Band des großen MutesÄschernes Band der großen Rache"}
MultiLanguageQuestData['de'][25249] = {title = "Gesinnungswandel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÄschernes Band der unvergleichlichen WeisheitÄschernes Band der unvergleichlichen ZerstörungÄschernes Band des unvergleichlichen MutesÄschernes Band der unvergleichlichen Rache"}
MultiLanguageQuestData['de'][25250] = {title = "Den Traum versiegeln", objective = "Benutzt Ysondres Träne, um das Portal im Traumgeäst zu schließen.", description = "Wir sind bereit. Nehmt diese Träne, <Name>. Sie ist voller natürlicher Essenz und vom Willen Ysondres geheiligt.\n\nÖstlich von hier, auf der anderen Seite des Baches, befindet sich Traumgeäst. Dort steht der Große Baum, der größte Baum Feralas', ein Schössling des Weltenbaums. In seinem Stamm ist ein Portal, das direkt zum Smaragdgrünen Traum führt. Dieses Portal müsst Ihr schließen.\n\nDas Portal wird bewacht sein; Ihr müsst mutig sein. Möge die Erdenmutter über Euch wachen.", progress = nil, completion = "Die Verderbnis wurde eingedämmt! Der Wald kann nun heilen.\n\nMöge der Segen der Erdenmutter auf all Euren Wegen bei Euch sein.", rewards = "TraumgeästrobenGürtel der NaturessenzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25251] = {title = "Endkampf", objective = "Legt das ultimative Fußbombentrikot an und kümmert Euch um Handelsprinz Gallywix.", description = "<Name>, es ist soweit! Thrall ist unten an Gallywix' Docks und kämpft in diesem Augenblick gegen den Handelsprinzen!\n\nSpringt sofort in Euer ultimatives Fußbombentrikot und beteiligt Euch!", progress = "<Name>, Ihr müsst den Handelsprinzen vernichten, bevor es zu spät ist!", completion = "Ihr habt es geschafft! Ihr habt es geschafft!\n\nWir sind gerettet, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFinal Confrontation: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25252] = {title = "Die Herrscher von Düsterbruch", objective = "Tötet 6 Vollstrecker der Gordok und 6 Ogermagier der Gordok.", description = "Nun, da wir in den Ruinen viel erreicht haben, ist es an der Zeit, dass wir uns der Oger in ihrer Heimat annehmen.\n\nDie Gordok bilden die \"Oberschicht\" des Stamms der Gordunni. Sie wurden ausgewählt, Düsterbruch zu verteidigen. Sie werden merken, dass wir es ernst meinen, wenn wir die Stärksten der Gordok vernichten.\n\nDiesmal nichts Ausgefallenes, <Name>. Macht Euch einfach auf den Weg und zerschlagt ein paar Gordokschädel!", progress = nil, completion = "Ausgezeichnet! Selbst diese Narren werden bald wissen, dass es den Tod bedeutet, wenn man sich gegen die Horde stellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25255] = {title = "Stört die Störer", objective = "Tötet 6 Zwielichtjäger in der Wolfsschlucht auf dem Hyjal.", description = "Der Schattenhammer hat sich als mehr als ein einfacher Kult entpuppt. Er ist eine gut geölte Kriegsmaschinerie, die sich wie ein Heuschreckenschwarm auf dem Berg niedergelassen hat und alles verschlingt, was ihr in den Weg kommt.\n\nDie Teile des Waldes, die sie nicht in Brand stecken, werden systematisch nach allem Lebenden durchkämmt, um die sterblichen Kultisten zu nähren.\n\nWir müssen die Jäger aufhalten, die die Wolfsschlucht ins Visier genommen haben. Nicht nur der übrigen Wildtiere zuliebe, sondern auch um den Kult zu zwingen, mit leerem Magen zu marschieren. Sucht südlich von hier und an der Straße im Osten.", progress = nil, completion = "Danke, &lt;Name&gt;. Ich fürchte, dass unsere Anstrengungen vergeblich sein könnten. Aber die Natur erschafft sich immer wieder neu und versetzt uns stets in Erstaunen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25256] = {title = "Hilfe benötigt", objective = "Meldet Euch bei Spitzzahn an Killrogs Küste in Durotar.", description = "Ihr da, <Volk>, nicht so schnell.\n\nMein Boss Spitzzahn hat mich geschickt, um nach Hilfe zu suchen - und nach Vorräten. Ihr scheint kein Händler zu sein, aber wahrscheinlich könnt Ihr ihm trotzdem helfen. Er ist südöstlich von hier, neben dem kaputten Wagen. Oh, und sagt ihm, ich habe Euch geschickt... Ich muss sicherstellen, dass er weiß, dass ich hier nicht nur meine Zeit vertrödel.", progress = nil, completion = "Vek'nag schickt Euch? Ohne Euch zu sagen, was ich brauche? Keine Rede von Wagenrädern, Nägeln und Vorräten? So ein Depp.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25257] = {title = "Ghislania", objective = "Besiegt Ghislania im Kampf.", description = "Ich habe ein paar Gladiatoren, die ich bei Wettkämpfen rund um Kalimdor antreten lasse. Die meisten von ihnen sind hier angekettet... wir hatten Glück, diese hier zu bekommen, als ihr Wagen kaputt ging.\n\nGhislania, die Naga dort drüben... hat ihre letzten drei Kämpfe verloren! Sie braucht wohl mehr Ausbildung, oder vielleicht auch nur genug Schläge. Fordert sie heraus - ich wette, selbst IHR seid stärker als sie.", progress = nil, completion = "Ich habe Euren Kampf beobachtet. Wie lange seid Ihr schon als &lt;Klasse&gt; unterrichtet worden?\n\nNicht schlecht, Kindchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25258] = {title = "Griswold Hanniston", objective = "Besiegt Griswold Hanniston im Kampf.", description = "Griswold, der da drüben an der Klippe angekettet ist, ist mein neuster Gladiator. Wir haben ihn direkt südlich von hier gefunden. Hat zusammen mit Soldaten von Nordwacht hier herumgeschnüffelt. Meine Männer haben ihn geschnappt und jetzt arbeitet er für mich.\n\nEr sieht ziemlich stark aus, aber ich habe ihn noch nicht wirklich in der Schlacht getestet. Warum fangt Ihr nicht einen Kampf mit ihm an und schaut, ob es sich lohnt, ihn zu behalten?", progress = nil, completion = "Jetzt weiß ich gar nicht mehr, was ich tun soll, &lt;Name&gt;… Ihr habt ihn ganz leicht im Kampf besiegt, aber ich habe ihn ja auch umsonst bekommen. Und er ist auch günstig im Unterhalt. Vielleicht behalte ich ihn einfach noch eine Weile.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25259] = {title = "Gaur Eishorn", objective = "Besiegt Gaur Eishorn im Kampf.", description = "Normalerweise würde ich Taunka nicht als Gefangene halten, weil sie der Horde doch recht nahe stehen... dieser hier ist allerdings ein Verräter, und noch dazu ein Krimineller. Er wurde von seinem eigenen Stamm ausgestoßen und ist mit dem Kanu nach Azshara gekommen - und dann wurde er dabei erwischt, wie er Vorräte von Valormok geklaut hat. Er hätte sein Ende sofort mit einer Axt gefunden, wenn ich nicht in der Nähe gewesen wäre und für ihn bezahlt hätte.\n\nGaur ist mein bester Gladiator, <Klasse>. Ich wette 10 Silber, dass Ihr ihn nicht besiegen könnt.", progress = nil, completion = "Schon gut, hier habt Ihr das Geld... aber Ihr verschwindet besser bald, bevor ich es mir noch einmal überlege, ob ich nicht doch jemanden von der Horde als Sklaven halten möchte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25260] = {title = "Missglückt", objective = "Erhaltet Zischels Kugel von Zischel Dunkelklaue im Donnergrat.", description = "Die Flut im Südwesten hat eines der Lager der Brennenden Klinge zerstört, die Durotar so hässlich machten. Dieses Lager wurde von Zischel Dunkelklaue angeführt - glaubt mir, ohne ihn sind wir besser dran.\n\nDunkelklaue hat allerdings eine Kugel besessen, an der die Horde sehr interessiert ist. Man weiß nicht, warum... meiner Meinung nach können sich die Hexenmeister darum kümmern. Ich weiß nur, dass ich die Kugel für sie besorgen muss.", progress = "Hattet Ihr irgendwelche Schwierigkeiten?", completion = "Ich bitte Euch, mir eine Kugel zu bringen, und Ihr bringt den halben Goblin mit, der noch dranklebt? Eine sehr schöne Arbeitsweise.\n\nNun, Ihr wart sicherlich eine helfende Hand. Ich möchte Euch nun auch einen Gefallen tun.", rewards = "VollstreckerhandschuheZischels HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25261] = {title = "Margoz", objective = "Sprecht mit Margoz.", description = "Margoz, einer unserer nützlichsten Schamanen, weiß mehr über die Verderbnis der Brennenden Klinge. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Brennenden Klinge eingenistet haben.\n\nBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.\n\nEr lagert im Südosten zwischen der Küste und der Staubwindklamm.\n\nFolgt seinem Rat, aber was immer Margoz auch sagt, <Name>, ich möchte, dass Ihr diese Kultisten vernichtet!", progress = nil, completion = "Willkommen, &lt;Name&gt;. Man hat mir Euer Kommen angekündigt und mir von Euren Unternehmungen in Durotar berichtet.\n\nIhr seid ein &lt;Klasse&gt; mit stetig wachsenden Fertigkeiten und Ansehen.\n\nHaltet Euch auf dem reinen Pfad, dann wird Eure Zukunft wahrlich großartig sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25262] = {title = "Die Knochenhöhle", objective = "Erhaltet 6 Senghalsbänder von den Kultisten in der Knochenhöhle.", description = "<Name>. Die Brennende Klinge hat die Knochenhöhle östlich von Orgrimmar eingenommen. Sie halten in der Höhle widerliche Rituale ab und verbrennen ihr eigenes Fleisch mit Senghalsbändern.\n\nDurch das Tragen dieser Halsbänder stimmen sich die Kultisten meines Wissens nach auf dämonische Macht ein. Aber um dies zu bestätigen benötige ich ein paar der Halsbänder, um sie zu untersuchen.\n\nBegebt Euch zur Knochenhöhle und sammelt Senghalsbänder der Kultisten, die sich dort aufhalten. Bringt mir die Halsbänder, und ich werde ihr Geheimnis lüften.", progress = "Habt Ihr die Knochenhöhle bereits gefunden, <Name>? Habt Ihr die Senghalsbänder?", completion = "Gut. In diesen Halsbändern verbirgt sich das Geheimnis der Brennenden Klinge. Und dieses Geheimnis werde ich nun lüften...", rewards = "Schuhe der Brennenden KlingeSengende ArmschienenKnochenhöhlengürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25263] = {title = "Neeru Feuerklinge", objective = "Bringt Neeru Feuerklinge in Orgrimmar ein Senghalsband-Muster.", description = "Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.\n\nBringt ein Senghalsband zu Neeru Feuerklinge. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.\n\nIhr findet Neeru in Orgrimmar in der Kluft der Schatten.", progress = "Meine ergebensten Grüße, <Klasse>. Womit kann ich Euch heute behilflich sein?", completion = "Ah, und wo habt Ihr das her? Der gute Margoz hat Euch zu mir geschickt, richtig?\n\nNun, dann lasst mich mal einen Blick darauf werfen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25264] = {title = "Ak'Zeloth", objective = "Sprecht mit Ak'Zeloth in der Fernwacht im Nördlichen Brachland.", description = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der orcischen Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.\n\nEs gehört der Brennenden Klinge.\n\nIhr habt Eure Rolle in dieser Geschichte beinahe zu Ende gespielt, <Name>. Geht zur Fernwacht an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Gebt diese Informationen an ihn weiter.", progress = nil, completion = "Das sind keine Neuigkeiten. Ich erkenne Eure Anstrengungen an, aber die Brennende Klinge muss warten. Wir müssen uns Wichtigerem widmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25265] = {title = "Sieg!", objective = "Sprecht mit Thrall an Gallywix' Docks auf den Verlorenen Inseln.", description = "Wir können Euch nicht genug für all das danken, was Ihr getan habt. Endlich kommen wir von dieser Insel herunter, bevor sie uns noch umbringt!\n\nThrall wird zuerst mit Euch sprechen wollen, <Name>. Ich schicke Euch mit einer Rakete da rüber.\n\nWir sehen uns auf dem Schiff!", progress = nil, completion = "Lok'tar! Sieg, &lt;Name&gt;!", rewards = "Robe des SiegersFeurige GamaschenUmklammerung des SiegesThralls GabeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25266] = {title = "Der Gesandte des Kriegshäuptlings", objective = "Liefert das versiegelte Päckchen beim Loyalisten der Kor'kron an den Docks der Messerbucht in Durotar ab.", description = "Die Goblins und die Orcs haben gemeinsam zu viel erreicht, um jetzt wieder getrennter Wege zu gehen, <Klasse>. Ich wünsche mir, dass das Bilgewasserkartell sich der Horde anschließt.\n\nIch habe hier etwas für den neuen Kriegshäuptling. Gebt dieses Päckchen meinem Freund der Kor'kron am Dock der Messerbucht in Durotar. Er wird Euch helfen, sicher nach Orgrimmar zu gelangen.\n\nSprecht mit Sassy Hartzang auf dem Schiff, wenn Ihr bereit seid, in See zu stechen.\n\nAuf bald! Aka'Magosh! Möget Ihr und die Euren gesegnet sein, <Name>!", progress = "Was in aller Welt habt Ihr in Orgrimmar zu schaffen, <Volk>?", completion = "&lt;Der Orc flüstert.&gt;\n\nIch weiß, wer Euch schickt. Hat er Euch etwas für mich mitgegeben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25267] = {title = "Nachricht für Garrosh", objective = "Bringt das Emblem des SI:7 zu Garrosh Höllschrei in der Feste Grommash in Orgrimmar.", description = "<Der Loyalist der Kor'kron öffnet das Paket und hält einen Gegenstand schützend in der Hand, während er den darin enthaltenen Brief liest. Nachdem er die Nachricht von Thrall gelesen hat, huscht ein kaum merkliches Lächeln über sein fängebewehrtes Gesicht.>\n\nBringt dies direkt zu Kriegshäuptling Höllschrei in Orgrimmar. Stellt sicher, dass Garrosh weiß, dass es von Thrall kommt.\n\nNehmt meinen Kampfworg. Schnell, kleiner Goblin. Diese Nachricht duldet keinen Aufschub!", progress = "Was soll das, <Volk>? Euresgleichen ist in der Feste Grommash nicht erlaubt.\n\nVerschwindet, bevor ich Euch zeigen muss, wo Euer Platz ist.", completion = "Thrall hat Euch aufgetragen, mir das zu bringen?\n\n&lt;Der Kriegshäuptling tritt einen Schritt zurück, sichtlich erschüttert.&gt;\n\nIch verstehe nur zu gut, was das heißt, &lt;Volk&gt;.\n\n\n\nDieses stinkende Ding wurde unbeaufsichtigt in der Stadt aufgegriffen und scheint Euch zu erkennen. Ich habe schon andere von Eurem Schlag zur Arbeit nach Azshara geschickt. Nehmt es mit Euch, wenn Ihr geht.\n\nAb diesem Tag dient Ihr und Euer Bilgewasserkartell der Horde!", rewards = "Stab des UnwillkommenenGurt der KnechtschaftHarnisch der BindungIhr erlernt:\n\nPackhobgoblin\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPackhobgoblin\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25268] = {title = "Die Stimme Goldrinns", objective = "Findet Ian Duran in der Nähe des Schreins von Goldrinn auf dem Hyjal.", description = "Südwestlich von hier liegt der Schrein von Goldrinn, ein Denkmal, das zu Ehren des alten Wolfsgeistes und seinem Beitrag beim Krieg der Ahnen errichtet wurde.\n\nUnsere neuen Verbündeten, die Worgen, waren von dieser Verehrung für den Wolfsgott natürlich vollkommen begeistert und haben begonnen, den Schrein aufzuräumen.\n\nIch habe schon seit Tagen nichts mehr von meiner Kontaktperson Ian Duran gehört. Könntet Ihr vielleicht dorthin fliegen und nach ihm sehen? Ich habe das ungute Gefühl, dass es am Schrein von Goldrinn Schwierigkeiten gibt.", progress = nil, completion = "Ihr seid hier, um mich zu retten, &lt;Klasse&gt;? Danke!\n\nNein, nein, kümmert Euch nicht um den Käfig. Mein Leben ist unwichtig. Zuerst müssen wir den Schrein retten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25269] = {title = "Die Stimme Lo'Goshs", objective = "Findet Takrik Wutheuler in der Nähe des Schreins von Goldrinn auf dem Hyjal.", description = "Habt Ihr von Lo'Gosh, dem Wolfsahnen, gehört? Die Mitglieder der Allianz nennen ihn \"Goldrinn\".\n\nIch muss Euch sicher nicht sagen, wie wichtig der Wolfsgott für die Horde ist. Seine Standhaftigkeit im Angesicht des Feindes war für alle Völker eine wahre Inspiration, egal, wie verschieden sie sein mögen.\n\nSüdwestlich von hier, unten im Tal, liegt ein Schrein für Goldrinn. Mein Freund Takrik Wutheuler war dabei, den Schrein wiederaufzubauen, aber ich habe schon seit Tagen nichts mehr von ihm gehört und befürchte das Schlimmste.\n\nBitte findet Takrik und überzeugt Euch davon, dass es ihm gut geht!", progress = nil, completion = "Lok'tar, &lt;Klasse&gt;! Macht Euch keine Sorgen wegen des Käfigs, diese Tiere werden schon bald aus Furcht vor mir erzittern.\n\nMeine oberste Priorität besteht darin, diesen Abschaum von meinem geliebten Schrein zu verjagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25270] = {title = "Sie heulen wie die Schlosshunde", objective = "Beschafft Euch 6 Einheiten verunreinigten Weihrauchs.", description = "Der Schrein wurde erobert, <Name>. Jetzt brauchen wir die Standhaftigkeit von Lo'Gosh mehr denn je.\n\nDiese Schänder, die flohverseuchten Wolfmänner, die den Schrein verwüsten, beschmutzen die Ehre des Wolfsgottes. Sie sind zusammen mit dem Schattenhammerkult eingetroffen und heulen einmütig ihre falschen Götter an. Sie wollen den edlen Lo'Gosh verderben, sodass er in ihr eigenes, verqueres Götterpantheon passt.\n\nTötet sie! Tötet sie und bringt mir die Werkzeuge ihrer Verehrung, eine Art verunreinigter Weihrauch. Ich muss verstehen, was sie mit dem Schrein vorhaben...", progress = "Diese Tiere waren einst Menschen, aber sie haben sich unter dem Einfluss des Schattenhammers in hirnlose Tiere verwandelt. Zögert nicht, sie alle zu töten.", completion = "&lt;Takrik untersucht den Weihrauch.&gt;\n\nAbscheulich. Er ist wie der Weihrauch, den wir verbrennen, um mit den Geistern zu sprechen… aber er ist… besudelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25271] = {title = "Goldrinns Wildheit", objective = "Beschafft Euch 6 Einheiten verunreinigten Weihrauchs.", description = "Diese wilden Tiere, die Ihr hier seht, sind nicht länger meine Brüder aus Gilneas. Sie wurden von einer Art Wahnsinn befallen und haben den Schrein eingenommen.\n\nSie kamen, als der Schattenhammer auf dem Hyjal eingetroffen ist, und heulen den Namen eines gotteslästerlichen Abklatsches unseres geliebten Goldrinns. Kümmert Euch nicht um mich. Eure oberste Pflicht besteht darin, diese Vandalen daran zu hindern, den Schrein weiter zu entehren.\n\nVernichtet sie und haltet nach dem Weihrauch Ausschau, den sie bei sich tragen. Bringt mir ein paar Proben davon!", progress = "Worgen wie ich werden von der Geschichte Goldrinns und seiner Stärke und Weisheit magisch angezogen. Aber diese Vandalen verehren eine ganz andere Art von Wolfsgott.", completion = "&lt;Ian untersucht den Weihrauch.&gt;\n\nWie ich es erwartet habe. Diese Reagenzien tragen das Zeichen des Schattenhammerkults. Und hier steht der Name \"Lycanthoth\". Ich glaube, dieser Weihrauch wird in Beschwörungsritualen verwendet…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25272] = {title = "Lycanthoth der Verderber", objective = "Benutzt Lycanthoths Rauchwerk im Schlund von Lycanthoth auf dem Hyjal, um Lycanthoth zu beschwören und zu töten.", description = "Die Handlungen dieser wilden Hunde ergeben so langsam Sinn. Der Schattenhammer fürchtet sich vor der Macht der Ahnen. Sie möchten nicht, dass Lo'Gosh zurückkehrt.\n\nAlso haben sie ihren eigenen Wolfsgott gerufen, oder eher das verzerrte Abbild dessen, was er einst war. \"Lycanthoth\", der Verderber.\n\n<Name>, Lycanthoth hat nicht einmal annähernd so viel Macht wie Lo'Gosh, aber die Bestie muss vernichtet werden, damit der wahre Ahn zurückkehren kann. Nehmt dieses Rauchwerk und verbrennt es im Schlund von Lycanthoth östlich von hier. Tötet dieses abscheuliche Wesen und befreit Lo'Goshs Geist!", progress = "Euer Mut ist ein leuchtendes Beispiel für andere, <Klasse>. Sagt, wie heißt Ihr?", completion = "Es war sehr tapfer von Euch, Lycanthoth gegenüberzutreten, &lt;Name&gt;. So wie ich war er eine ursprüngliche Naturgewalt... doch er stammte von einem dunkleren Ort.\n\nDiejenigen, die dieses Ungeheuer gebaren, drangen tief in die Finsternis ein und kanalisierten Kräfte, die niemals für diese Welt gedacht waren.\n\nKommt, &lt;Klasse&gt;. Klettert auf meinen Rücken und wir werden diesen Ungeheuern das wahre Gesicht der Wildheit zeigen!", rewards = "Wickeltuch des rasenden StolzesHandschützer der unterdrückten BrutalitätAuf Euch wartet eine dieser Belohnungen:\n\nHalsreif von Lo'Gosh\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSpieler zwingen, Goldrinn zu reiten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25273] = {title = "Lycanthoth der Verderber", objective = "Benutzt Lycanthoths Rauchwerk im Schlund von Lycanthoth auf dem Hyjal, um Lycanthoth zu beschwören und zu töten.", description = "Ich glaube, ich verstehe, was hier vor sich geht. Der Schattenhammer fürchtet, dass die Ahnen sich eines Tages gegen sie wenden könnten. Sie würden alles tun, um Goldrinns Rückkehr zu verhindern.\n\nDieser \"Lycanthoth\" ist eine entstellte Version unseres geliebten Wolfsgottes, den der Schattenhammer beschworen hat, um ihn zu ersetzen.\n\nPah! Lycanthoth hat nicht einmal annähernd so viel Macht wie Goldrinn. <Name>, Ihr müsst die Bestie vernichten, damit der wahre Ahn zurückkehren kann. Nehmt dieses Rauchwerk und verbrennt es im Schlund von Lycanthoth östlich von hier. Tötet dieses abscheuliche Wesen und befreit Goldrinn!", progress = "Euer Mut ist ein leuchtendes Beispiel für andere, <Klasse>. Sagt, wie heißt Ihr?", completion = "Es war sehr tapfer von Euch, Lycanthoth gegenüberzutreten, &lt;Name&gt;. So wie ich war er eine ursprüngliche Naturgewalt... doch er stammte von einem dunkleren Ort.\n\nDiejenigen, die dieses Ungeheuer gebaren, drangen tief in die Finsternis ein und kanalisierten Kräfte, die niemals für diese Welt gedacht waren.\n\nKommt, &lt;Klasse&gt;. Klettert auf meinen Rücken und wir werden diesen Ungeheuern das wahre Gesicht der Wildheit zeigen!", rewards = "Gurt der UrmachtKlauen des WorgengeistesAuf Euch wartet eine dieser Belohnungen:\n\nGoldrinns Medaillon\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSpieler zwingen, Goldrinn zu reiten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25274] = {title = "Gezeichnet mit Blut", objective = "Lockt einen Zwielichtrekruten von der Gruppe weg und stehlt seine Rekrutierungsunterlagen des Schattenhammers.", description = "Endlich seid Ihr hier, <Name>. Und genau zur richtigen Zeit.\n\nDie Nachricht über Ragnaros' Auftauchen hat eine große Welle von neuen Rekruten ausgelöst, die sich um eine Mitgliedschaft beim Schattenhammerkult bewerben.\n\nWenn Ihr den Kult unterwandern möchtet, dann ist jetzt der rechte Augenblick. Wir brauchen Rekrutierungsunterlagen, die mit dem Blut eines Mitglieds des Schattenhammers unterzeichnet wurden, das Euch empfiehlt. Lockt einen von den neuen Rekruten von der Gruppe weg und schlagt ihn mit diesem Totschläger.\n\nWenn Ihr Glück habt, könnt Ihr ihm seine Rekrutierungsunterlagen stehlen. Bringt sie zu mir. Ich werde mir alle Mühe geben, sie zu verändern.", progress = "Habt Ihr die Papiere?", completion = "Ausgezeichnet. Ich werde mir alle Mühe geben, diese Dokumente zu verändern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25275] = {title = "Meldet Euch beim Arbeitsaufseher", objective = "Meldet Euch bei Arbeitsaufseher Grabbit am Hinteren Tor von Orgrimmar in Azshara.", description = "Euer Volk ist mit der landschaftlichen Umgestaltung Azsharas beschäftigt. Wir werden das Land im Geiste der Horde neu gestalten, auf dass alle wissen: Kalimdor ist unser!\n\nGeht nach Norden durch die Stadt. Jenseits des Tals der Ehre findet Ihr das Hintere Tor von Orgrimmar. Meldet Euch bei Arbeitsaufseher Grabbit außerhalb des Tors, Goblin.\n\nFür die Horde!", progress = nil, completion = "&lt;Name&gt;? Der &lt;Name&gt;?!\n\n\n\nEuer Ruf eilt Euch voraus. Ich weiß nicht, ob ich dankbar oder besorgt sein sollte, dass Ihr hier seid. Zumindest gibt es in Azshara keine Vulkane!\n\nIm Ernst, ich kann es kaum glauben, dass Ihr Euch hier blicken lasst... Handelsprinz Gallywix hat eine Werkstatt oben auf dem Berg errichtet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25276] = {title = "Eure neue Identität", objective = "Sprecht mit Condenna der Mitleidlosen bei den Versuchsgründen auf dem Hyjal.", description = "Da! Nicht meine beste Arbeit, aber auch nicht meine schlechteste. Ihr werdet bei den Kultisten den Namen \"<Name>damus\" tragen.\n\nMit diesen Papieren werdet Ihr den anderen Rekruten vorgezogen und könnt direkt mit den Zwielichtinstrukteuren sprechen.\n\nGeht zu den Versuchsgründen und zeigt sie Condenna der Mitleidlosen. Sie trennt die Spreu vom Weizen.\n\nZeigt ihr, aus welchem Holz Ihr geschnitzt seid.", progress = "Ihr werdet mich mit dem gebührenden Respekt ansprechen, Rekrut!", completion = "Kunrebidamus? Hoffen wir mal, dass Eure Eltern Euch mehr auf diese Welt mitgegeben haben als einen dämlichen Namen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25277] = {title = "Aufräumarbeiten", objective = "Tötet eine beliebige Kombination aus 8 Schlägern oder Schattenwirkern des Unterschlupfs in Gar'gols Unterschlupf auf dem Hyjal.", description = "Wir machen gute Fortschritte darin, den früheren Glanz des Schreins wiederherzustellen, <Name>. Aber ein paar Aufräumarbeiten müssen wir noch erledigen. Auf der anderen Seite dieser Wiese errichten gerade ein paar Ogerlandstreicher ihr Lager. Ihr Anführer ist ein dickköpfiger Klotz purer Hässlichkeit namens Gar'gol.\n\nTötet Gar'gols Diener und schaut, ob wir ihn dadurch zum Aufbruch bewegen können.", progress = nil, completion = "Ha! Also habt Ihr wirklich ein paar Köpfe zum Rollen gebracht!\n\nDie Legenden sagen, dass Lo'Gosh während des Krieges der Ahnen zehn Tage ununterbrochen gegen Dämonen gekämpft haben soll. Hoffentlich habt Ihr nicht so lange kämpfen müssen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25278] = {title = "Aufräumarbeiten", objective = "Tötet eine beliebige Kombination aus 8 Schlägern oder Schattenwirkern des Unterschlupfs in Gar'gols Unterschlupf auf dem Hyjal.", description = "Dank Eurer Bemühungen sind wir vielleicht schon bald in der Lage, den früheren Glanz des Schreins wiederherzustellen. Aber zunächst müssen wir dieses Tal sichern. Südlich von hier hat eine Gruppe von Ogern unter Leitung von Gar'gol ein Lager in einem stinkenden Unterschlupf errichtet.\n\nIch würde Gar'gol nicht als 'Bedrohung' bezeichnen, sondern vielmehr als enorm massiges Hindernis auf unserem Weg, das uns von der echten Gefahr ablenkt. Dennoch müssen er und seine Gorillas gehen.\n\nTötet Gar'gols Diener in Goldrinns Namen!", progress = nil, completion = "Ihr habt diesen Ort richtig aufgeräumt, oder? Gut gemacht!\n\nDie Nachtelfen haben mir einst eine Geschichte erzählt, wie Goldrinn sich einem Schreckenslord gestellt und ihn getötet hat, während drei andere an seinen Flanken hingen und sein Fleisch versengten. Ich frage mich, ob Ihr oder ich je eine derartige Stärke beweisen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25279] = {title = "Der zurückeroberte Schrein", objective = "Kehrt zu Takrik Wutheuler am zurückeroberten Schrein von Goldrinn auf dem Hyjal zurück.", description = "Ja, <Name>. Ich bin Goldrinn, den man in Eurer Sprache \"Lo'Gosh\" nennt. Eure Standhaftigkeit im Angesicht der Angst hat mich aus den Fesseln des Zwielichts befreit.\n\nMein Schrein wurde geläutert, und meine Anhänger sind an ihren rechtmäßigen Platz an meiner rechten Pfote zurückgekehrt.\n\nGeht zu Takrik und setzt Eure Arbeit hier auf dem Hyjal fort. Ich werde Euch schon bald erneut brauchen.", progress = nil, completion = "&lt;Name&gt;, es war unglaublich! Für einen flüchtigen Moment sah ich Lo'Gosh durch die Bäume hindurch, ein Wesen aus Zorn und Licht zugleich. Mein Käfig ist zusammengebrochen und die Vandalen schmolzen unter dem Kuss seiner Klauen dahin wie Wachs. Ihr Schreien und Heulen erfüllte das ganze Tal... War das Euer Werk?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25280] = {title = "Der zurückeroberte Schrein", objective = "Kehrt zu Ian Duran am zurückeroberten Schrein von Goldrinn auf dem Hyjal zurück.", description = "Ja, <Name>. Ich bin Goldrinn. Eure Standhaftigkeit im Angesicht der Angst hat mich aus den Fesseln des Zwielichts befreit.\n\nMein Schrein wurde geläutert, und meine Anhänger sind an ihren rechtmäßigen Platz an meiner rechten Pfote zurückgekehrt.\n\nGeht zu Ian und setzt Eure Arbeit hier auf dem Hyjal fort. Ich werde Euch schon bald erneut brauchen.", progress = nil, completion = "&lt;Name&gt;, es war atemberaubend! Goldrinn selbst, sein weißes Fell so weiß wie der Sommermond. Mein Käfig ist zerfallen und die Vandalen schmolzen unter dem Kuss seiner Klauen dahin wie Wachs. Er war wunderschön, &lt;Name&gt;. Wunderschön!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25281] = {title = "Wie ich Euch, so Ihr ihnen", objective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", progress = nil, completion = "Während Ihr fort wart, konnte ich einige der gefallenen Soldaten wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Pay It Forward See Inv\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25283] = {title = "Die Rede vorbereiten", objective = "Benutzt das Gnomische Abspielgerät vor Ozzie Wechselvolt nördlich von Kharanos, Milli Federpfiff bei Stahlrosts Depot und Tog Rostspross vor der Gaststätte in Kharanos. Kehrt zu Toby Zeigrad zurück, wenn alle Reden gehalten wurden.", description = "Hochtüftler Mekkadrill hat mich gebeten, eine Rede zu schreiben, die er vor Beginn der Schlacht halten kann. Aber ich kann mich nicht mehr daran erinnern, welche Rede gut ist und welche total daneben.\n\nKönntet Ihr ein paar davon an den örtlichen gnomischen Anwohnern ausprobieren? Dieses Gerät erschafft ein Bild von Mekkadrill, das einige Zeilen aus jeder meiner Reden spricht.\n\nLasst mich wissen, welche funktioniert, ja?", progress = nil, completion = "Wow. Ihre Reaktionen waren also so unterschiedlich.\n\nNicht ganz, was ich erwartet habe, aber ich glaube, ich habe eine passende Rede.\n\nLasst mich nur kurz herausfinden, wo ich sie hingelegt habe …", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25284] = {title = "Die Angst nähren", objective = "Tötet 5 Turmwächter. Benutzt die Seile neben Holgom, um schnell nach Ehrenwacht hinein und hinaus zu gelangen.", description = "Unsere Mittel sind begrenzt, <Klasse>, aber das heißt nicht, dass wir da unten nicht für ein wenig Ärger sorgen können. Benutzt die Seile hier, um die Steilwand hinunterzuschleichen und tötet dann die menschlichen Gefängniswärter.\n\nEin paar dürre Wächter zu töten wird das Blatt zwar nicht wenden, aber stellt Euch die Angst und das Chaos vor, die wir dadurch verbreiten werden, wenn die Menschen die verstümmelten Leichen entdecken...\n\n<Holgom grinst und zeigt dabei seine gelben Zähne - seine Augen glitzern.>", progress = nil, completion = "Gut, gut! Sie werden viele schlaflose Nächte benötigen, um herauszufinden, wo wir herkamen und wohin wir verschwunden sind, nachdem wir sie umgebracht hatten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25285] = {title = "Rein und Raus", objective = "Testet den Schleudersitz des Mechanopanzers mit Schleudersitzsystem.", description = "Diese neuen Mechanopanzer müssen für den Angriff fertiggemacht werden. Bereit, eine dieser Höllenmaschinen zu testen?! Klar seid Ihr das!\n\nAls erstes müssen wir sicherstellen, dass Ihr wieder rauskommt, wenn Ihr erstmal drin seid. Wenn Ihr in der Schlacht glaubt, dass Euer Panzer gleich explodieren wird, dann raus! Ich hab schon viele Gnome gesehen, die bis zum bitteren Ende dringeblieben sind ... der Panzer explodiert, und sie gleich mit.\n\nAlso, ich habe diesen Panzer mit einem Schleudersitz ausgestattet. Probiert ihn für mich aus, ja?", progress = nil, completion = "Na sieh mal einer an, Ihr seid nicht in winzigkleine Stücke zersprengt worden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25286] = {title = "Wortübermittlung", objective = "Bringt die Rede zu Hauptmann Tret Funkdüse bei Stahlrosts Depot.\n\nBereitgestellter Gegenstand: \n", description = "Das ist es. Das ist die Rede, <Name>! Sie hat alles, was einen guten Auftakt zur Schlacht ausmacht... sie inspiriert, ist eloquent und spricht den einfachen Gnom direkt an. Noch nie wurde eine bessere Rede geschrieben!\n\nGebt das hier bei Hauptmann Tret Funkdüse ab und besorgt euch einen Transport zu Hochtüftler Mekkadrill!", progress = nil, completion = "Toby ist mit der Rede fertig? Lasst mal sehen...\n\n&lt;Er liest die Rede&gt; Bei allen Kolben, was für eine fantastische Rede! Ich wusste ja, dass Toby ein guter Redenschreiber ist, aber das hier ist vielleicht das Beste, was er je geschrieben hat.\n\nIch glaube, es ist Zeit, Euch in die Schlacht zu schicken.", rewards = "Ihr bekommt:\n\nStolz von Gnomeregan"}
MultiLanguageQuestData['de'][25287] = {title = "Wortübermittlung", objective = "Benutzt die Flugmaschine \"Donnerschlag\" bei Stahlrosts Depot, um zu Hochtüftler Mekkadrill zu fliegen, und stellt ihm Tobys Rede zu.", description = "In Ordnung, Soldat. Zeit, Euch zu beweisen!\n\nNehmt diese Rede und geht an Bord der Flugmaschine \"Donnerschlag\". Sie ist der schnellste Weg zu Hochtüftler Mekkadrill, und er wartet nur noch auf diese Rede, bevor er Operation: Gnomeregan beginnt.\n\nGeht! Jetzt!", progress = "Wart Ihr nicht da, um Toby Zeigrads Rede zu bringen?", completion = "Das ist also die endgültige Fassung der Rede von Toby? Lasst mal sehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25289] = {title = "Ein Schritt nach vorn...", objective = "Testet die Manövrierbarkeit des krabbelnden Mechanopanzers.", description = "Jetzt, da das Schleudersitzsystem funktioniert, sind wir bereit, Bewegungen zu testen. Dieser Panzer hat eine Besonderheit: Automatische Ausweichmanöver!\n\nIch möchte, dass Ihr die Servomotoren am linken Bein und am rechten Bein sowie das Automatische Ausweichmanöversystem ausprobiert.\n\nEs ist ganz einfach, also sollte es nicht lange dauern.", progress = nil, completion = "Hm… der Servomotor für das linke Bein hat das rechte aktiviert? Aber ich habe doch gesehen, wie sich das linke Bein bewegt hat… ach, Details. Ich kümmere mich später darum. Aber zwei von drei Teilen haben funktioniert, das ist gar nicht mal so schlecht!\n\nDanke, dass Ihr das für mich überprüft habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25291] = {title = "Zwielichttraining", objective = "Sprecht mit Instrukteurin Mylva auf dem Hyjal.", description = "Ihr habt bewiesen, dass Ihr wert seid, zumindest an unserem grundlegendsten Training teilzunehmen.\n\nIhr findet eine unserer Siedlungen östlich von hier. Sprecht dort mit Instrukteurin Mylva.", progress = nil, completion = "Also glaubt Ihr, dass Ihr bereit seid, den nächsten Schritt zu tun, Kunrebidamus?\n\nMal sehen, was Ihr leisten könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25292] = {title = "Die nächsten Verwandten", objective = "Bringt die zwergische Gewehrkugel zu Alto Steinkeil in Brackenwall in den Düstermarschen.", description = "<Nato zieht Euch beiseite und flüstert.>\n\n<Name>, ich habe die Kugel aus Ganns Brust entfernt, aber die Blasen in seinem Blut sagen mir alles, was ich wissen muss. Seine Lunge ist durchstoßen und die Wunde entzündet sich. Er wird nicht mehr lange durchhalten.\n\nNehmt dies. Es ist die Kugel, die ihn getötet hat. Seine Familie wird sicher wissen wollen, was ihrem jüngsten Krieger zugestoßen ist.\n\nSucht Alto Steinkeil auf. Er ist in den Düstermarschen postiert. Geht nach Nordosten und folgt dem Weg nach Brackenwall.", progress = "Hallo, <Klasse>. Ihr seid ja voller Staub statt voller Schlamm. Also kommt Ihr wohl vom Brachland hierher.", completion = "&lt;Alto ballt die Faust um die Kugel, als Ihr ihm erzählt, was passiert ist.&gt;\n\nGann? Tot? Ich… ich hätte es wissen sollen. Sein Temperament… seine Waghalsigkeit. Ich wusste, dass sie ihm eines Tages zum Verhängnis werden würden.\n\nAber es scheint, als hättet Ihr ihm bereits das Geschenk der Rache gemacht. Vielen Dank, &lt;Name&gt;!\n\nUnd jetzt richtet Eure Aufmerksamkeit auf die Düstermarschen. Wenn die Allianz den Bau ihrer verfluchten Straße durch das Gebiet abschließt, sind all Eure Siege im Brachland vielleicht nichtig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25294] = {title = "Hundefütterung", objective = "Sammelt 5 Stück verkohltes Basiliskenfleisch und füttert die Brut von Loderos damit.", description = "Hmmmpf… In letzter Zeit lassen die hier wohl einfach jeden rein.\n\nNa gut. Ihr habt in den Versuchsgründen sicher schon Loderos kennengelernt.\n\nNun, ich wurde mit der Aufgabe betraut, mich um einen seiner Welpen zu kümmern. Er ist jetzt schon ein echter Satansbraten. Wenn er später seinem Vater auch nur ein bisschen ähnlich wird, wird er unserer Sache gut dienen.\n\nSammelt Fleisch von den Basilisken in der Gegend und füttert ihn damit.", progress = nil, completion = "Ausgezeichnet. Dieser kleine Welpe wird bestimmt einmal so groß und erbarmungslos wie sein Vater.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn Spawn of Smolderos [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25295] = {title = "Feuer drücken", objective = "Testet die Waffensysteme des schießenden Mechanopanzers an den Zielen in der Nähe.", description = "Sicherheitssysteme bereit! Motorfunktion funktioniert! Jetzt müssen wir nur noch sicherstellen, dass die Geschütze feuern.\n\nDas sollte nicht schwer sein, <Name>. Der Mechanopanzer auf dem Hügel hinter uns ist mit harmlosen Geschossen geladen worden. Feuert einfach ein paar Schüsse auf die Ziele in der Nähe und erstattet mir dann Bericht.", progress = "Was ist los, habt Ihr vergessen, wie man schießt?", completion = "Hm. Die Geschosse hatten also eine ziemlich breite Streuung?\n\nDas wäre für so manchen sicher ein Problem. Für mich ist das ein versteckter Vorteil!\n\nUnsere Feinde werden überall herumrennen. Mit ein wenig Streuung müssen die Panzerfahrer den Vorhalt nicht so genau einschätzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25296] = {title = "Sammelt Informationen", objective = "Besorgt das Kommuniqué des Schattenhammers und die Hyjalschlachtpläne.", description = "Ich bin es, <Name>, Ortell!\n\nSchaut nicht direkt auf das Plumpsklo… sonst verratet Ihr noch meinen Standort.\n\nAlso läuft alles nach Plan? Ausgezeichnet!\n\nIhr müsst für mich ein paar Informationen sammeln, während Ihr hier seid. Eine Karte oder ein Brief scheinen zwar nichts Weltbewegendes zu sein, aber den nächsten Schritt unseres Feindes vorauszusehen kann Hunderte von Leben auf unserer Seite retten.", progress = "Habt Ihr die Dokumente, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Oder sollte ich sagen \"Kunrebidamus\"?\n\nGebt meinen Männern eine Minute, um sich das hier durchzulesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25297] = {title = "In den Schlund des Wahnsinns", objective = "Sammelt Steinblüten, Bitterblüten und Schwarzfeuerglut.", description = "Ich kenne ein Gebräu, das diese stumpfsinnigen ehemaligen Sklaven wieder in die Wirklichkeit zurückholen sollte. Sammelt ein paar Steinblüten von den Felsen rund um Gar'gols Unterschlupf, ein paar Bitterblüten am Ufer des Sees in der Nähe und Schwarzfeuerglut aus einer der Kohlenpfannen am Eingang des Unterschlupfs. Das Gebräu hält nicht lange vor, also gebt alle Zutaten in einen Kessel des Schattenhammers am Eingang des Unterschlupfs.\n\nEin Schluck dieses Gebräus wird diesen hirnlosen Sklaven wieder Verstand einhauchen!", progress = "<Im Kessel blubbert eine widerliche Flüssigkeit.>", completion = "&lt;Ihr leert den derzeitigen Inhalt des Kessels aus. Die umstehenden Pflanzen verwelken sofort.&gt;\n\n&lt;Euer Gebräu ähnelt eher einem dicken Eintopf und stinkt nach verfaultem Kohl. Ihr dreht Euren Kopf zur Seite und füllt es in Flaschen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25298] = {title = "Freiheit ist das Einzige, was zählt", objective = "Sprecht mit 8 Zwielichtdienern, um ihnen das Gebräu zu verabreichen und sie zu retten.", description = "<Rio sagte, dass die Wirkung des Gebräus nicht lange anhalten wird.>\n\n<Ihr solltet schnell zum Unterschlupf eilen und es so vielen Zwielichtdienern wie möglich verabreichen.>", progress = "Hat das Gebräu gewirkt?", completion = "Sehr gut! Wollen wir nur hoffen, dass der Schaden nicht dauerhaft ist.\n\nDem Zustand dieser armen Opfer hier im Lager nach zu urteilen haben die Schattenhammerkultisten ihren Geist ganz schön verwirrt.", rewards = "Gehässiger HelmLäuternde SchiftungSprenger der FesselnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25299] = {title = "Mentales Training: Wahrheit als Weg zur Macht", objective = "Benutzt die Kugel des Aufstiegs und beantwortet 10 Fragen richtig.", description = "Ihr glaubt vielleicht, dass Ihr bereit seid, das Wissen zu empfangen, das wir Euch vermitteln werden. Aber das seid Ihr nicht.\n\nStellt Euch Euren Geist als Kiste vor, die sich wiederum in vielen weiteren Kisten befindet.\n\nMit jedem Schritt unseres Trainings öffnet Ihr eine weitere Kiste, bis Ihr bereit seid, Euch direkt mit den Elementen zu verbinden.\n\nNehmt die Kugel des Aufstiegs und beantwortet alle Fragen, die sie Euch stellt. Wahrheitsgemäß! Jede falsche Antwort könnte... fatale Folgen haben.", progress = "Ihr seid zurückgekehrt.", completion = "Ihr hattet Erfolg, Kunrebidamus. Ihr seid bereit für den nächsten Schritt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25300] = {title = "Das Auge des Zwielichts", objective = "Sucht das Auge des Zwielichts in der Nähe des Eingangs zu Gar'gols Unterschlupf auf dem Hyjal.", description = "Der Ogerklan jenseits des Sees wird von Gar'gol geleitet. Nun ja, \"geleitet\" ist relativ. Gar'gol hat die Intelligenz eines rohen Stücks Fleisch.\n\nSoweit ich es beurteilen kann, nimmt Gar'gol Befehle von einem magischen Artefakt entgegen, dem \"Auge des Zwielichts\". Er folgt seinen Anweisungen, ohne Fragen zu stellen.\n\nWenn wir das Auge sabotieren könnten, würden wir unglaublichen Schaden anrichten.\n\nGeht zu Gar'gols Unterschlupf und sucht das Auge des Zwielichts in der Nähe des Eingangs. Untersucht es. Findet einen Weg, es Eurem Willen zu unterwerfen. Ah, welch wundervolles Chaos...", progress = nil, completion = "&lt;Ihr nähert Euch dem Auge des Zwielichts. Als Eure Fingerspitzen die leuchtende Oberfläche berühren, bemerkt Ihr eine bösartige Präsenz, die Euch anstarrt und Eure Seele durchforstet.\n\n&lt;Instinktiv zieht Ihr Eure Hand zurück.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25301] = {title = "Worte der Herrschaft", objective = "Findet die Zwielichtapokryphen in Gar'gols Unterschlupf auf dem Hyjal.", description = "<Während der kurzen Kommunikation mit dem Auge konntet Ihr spüren, dass die Quelle seiner Macht tief in dem Unterschlupf verborgen liegt. Ihr konntet das Gewicht eines mächtigen Folianten spüren, der die vier Elemente aneinander fesselt.>\n\n<Wenn Ihr das Auge beherrschen wollt, müsst Ihr den Unterschlupf nach diesem Folianten durchsuchen.>", progress = nil, completion = "&lt;Ein schwerer, in Haut gebundener Foliant liegt offen auf dem Tisch.&gt;\n\n&lt;Die bildartige Schrift in rostfarbener Tinte ist nicht entzifferbar und wirkt auf Euch wie Gekritzel. Zwischen einigen der Seiten liegen jedoch Notizen mit der Übersetzung. Das muss das Buch sein, nach dem Ihr sucht.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25303] = {title = "In Eurem Element", objective = "Aktiviert die vier in der Nähe befindlichen Elementartiegel in der richtigen Reihenfolge, um das Auge des Zwielichts zu kontrollieren.", description = "<Ihr könnt den Text nicht lesen, aber die Diagramme scheinen darauf hinzudeuten, dass die Geräte um Euch herum in einer bestimmten Reihenfolge aktiviert werden müssen.>\n\n<Ein Absatz der Apokryphen wurde in moderne Sprache übersetzt:>\n\nAm Anfang war der ewige Schatten.\nHass loderte und FEUER ward geboren.\nWunden vernarbten und zeugten die ERDE.\nSchmerzensschreie gebaren den WIND.\nUnd der Himmel weinte ein Meer aus TRÄNEN. \nWir leben im Schatten\nDie Welt, die wir kennen\nErschaffen aus Wut, Leid, Schmerz und Tränen.", progress = "<Ihr beugt Euch über die Apokryphen und versucht, einen Sinn hinter alldem zu erkennen.>", completion = "&lt;Erfüllt von den Energien der gefangenen Elementare steht Ihr vor den Zwielichtapokryphen. Die Seiten blättern sich wie von Geisterhand um.&gt;\n\n&lt;Plötzlich seht Ihr, was das Auge sieht. Es steht unter Eurem Befehl!&gt;", rewards = "Gurt von Gar'golBrustschutz der UndurchschaubarkeitApokryphische BindungenDer folgende Zauber wird auf euch gewirkt:\n\nGar'gols Oger freundlich gestimmt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25304] = {title = "Die Schlacht um Sardor", objective = "Sprecht mit Tambre auf der Insel Sardor.", description = "Unsere Siedlung auf der Insel Sardor haben wir an die Nagaschuppen der Hasskämme verloren. Von ihren Zahlen überwältigt mussten wir uns auf das Festland zurückziehen. Während sie sich auf ihrem neuen Sandstrand vergnügten, haben wir an der Küste Neu-Mondfederfeste errichtet und eine weitaus größere Armee zusammengestellt.\n\nJetzt werden wir die Hasskämme zurück ins Meer jagen. Sucht das Urtum des Krieges an der Küste auf. Es wird Euch an die Front bringen. Tambre führt dort die Offensive an.", progress = nil, completion = "Wir werden diese garstigen Kreaturen zurück ins Meer jagen. Ich hoffe, Ihr seid bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25305] = {title = "Kein Blick zurück", objective = "Tötet 10 Naga der Hasskämme und ihren Anführer.", description = "Unsere Siedlung auf der Insel Sardor haben wir an die Naga der Hasskämme verloren. Von ihren Zahlen überwältigt mussten wir uns auf das Festland zurückziehen. Während sie sich auf ihrem neuen Sandstrand vergnügten, haben wir an der Küste Neu-Mondfederfeste errichtet und eine weitaus größere Armee zusammengestellt.\n\nJetzt werden wir die Hasskämme zurück ins Meer jagen. Fordert Schildwache Ranadae auf, sich unseren Truppen auf Sardor anzuschließen. Tötet die Naga und sorgt dafür, dass auch derjenige stirbt, der ihnen die Befehle erteilt.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][25306] = {title = "Ihr seid jetzt in der Gnarmee!", objective = "[ph] Log Description", description = "[ph] War!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][25308] = {title = "Saat der Zwietracht", objective = "Lenkt Karr'gonn ab und tötet Hochkultist Azennios am Sitz der Auserwählten auf dem Hyjal.", description = "Nach den Informationen, die Ihr gesammelt habt, gibt es starke Spannungen zwischen den Ogern und Nicht-Ogern des Kults.\n\nHochkultist Azennios und der Ogermagier Karr'gonn treffen sich am Sitz der Auserwählten, um zu versuchen, diese Konflikte zu mildern.\n\nAm Sitz der Auserwählten gibt es ein Plumpsklo wie dieses. Geht dorthin und zieht Euch diese Ogerverkleidung an. Sucht nach einem Weg, Azennios auf seiner Friedensmission zu töten.\n\nWir müssen diese Zwietracht so gut es geht ausnutzen!", progress = "Habt Ihr es schon erledigt, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Dieses Mal habt Ihr Euch wirklich selbst übertroffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25309] = {title = "Spirituelles Training: Mitleid ist etwas für Schwächlinge", objective = "Tötet 5 gescheiterte Bittsteller in der Verdammniswacht.", description = "Ihr habt es so weit geschafft. Andere nicht.\n\nGeht zur Verdammniswacht direkt nördlich von hier. Wir haben alle… Versager zusammengetrommelt. Ich möchte, dass Ihr Euch um sie kümmert. Das ist gut für Euer spirituelles Wachstum.\n\nWenn Ihr Probleme mit einem so kaltblütigen Verhalten haben solltet, betrachtet es einfach als ihre zweite Chance. Sollte es nämlich jemandem von ihnen gelingen, Euch zu töten... nun, dann nimmt er Euren Platz ein.", progress = nil, completion = "Ihr seid auf der Überholspur zum Erfolg. Wollen wir hoffen, dass Ihr Eure makellose Bilanz nicht mit solchen Albernheiten wie Barmherzigkeit und Menschlichkeit verderbt.\n\nKommt schon. Lasst uns über Eure Zukunft sprechen.", rewards = "Brustschutz der schnellen BeförderungGürtel des schnellen VersagensWeggeworfene Armschienen des BittstellersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25310] = {title = "Das größere von zwei Übeln", objective = "Benutzt den Talisman der Flammenaszendenz und tötet Garnoth, die Faust der Legion, an den Toren von Sothann auf dem Hyjal.", description = "Wir haben die Flüsternde Schlucht mit Gewalt von den Dämonen der Brennenden Legion zurückerobert. Bis jetzt haben wir unser Gebiet ganz gut verteidigen können, bis auf eine Ausnahme.\n\nKürzlich haben wir die Tore von Sothann an einen Grubenlord und seine Armee verloren. Das können wir nicht auf sich beruhen lassen.\n\nBenutzt diesen Talisman, wenn Ihr in seiner Nähe seid. Ihr erhaltet dann kurzzeitig die Macht eines Flammenaszendenten. Nutzt sie gut!", progress = nil, completion = "Ausgezeichnete Arbeit, Arrøwdynamicdamus. Wir müssen allen Möchtegerngegnern zeigen, dass wir nicht so leicht aufgeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25311] = {title = "Schattenhammergebiet", objective = "Tötet 10 Horrorwachen an den Toren von Sothann auf dem Hyjal.", description = "Die Dämonen der Brennenden Legion glauben, sie könnten hier einfach so aufkreuzen und sich jedes Gebiet nehmen, das ihnen gefällt. Sicher, das Gebiet gehörte früher ihnen, aber darum geht es ja nicht.\n\nWir werden ihnen beibringen, dass sie sich nicht mit dem Schattenhammer anlegen sollten.\n\nBrecht zu den Toren von Sothann auf und vernichtet den Horrorwachentrupp, der in diesem Gebiet sein Unwesen treibt.", progress = nil, completion = "Pünktlich wie immer. Ihr enttäuscht mich nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25312] = {title = "Rückkehr zu Abendwisper", objective = "Kehrt zu Royce Abendwisper am Schrein von Goldrinn auf dem Hyjal zurück.", description = "<Ihr zwingt Euer eigenes Bild in das Auge und bringt es dazu, den Ogern andere Befehle zu geben. Währenddessen spürt Ihr eine andere Präsenz im Auge, die Euch begutachtet und nach Euren Schwächen sucht. Ein weit entferntes Wesen schäumt vor Wut. Ihr habt Euch heute ein paar Feinde gemacht!>\n\n<Eure Arbeit hier ist getan, und die Oger werden Euch gegenüber freundlich sein. Kehrt zu Royce Abendwisper am Schrein von Goldrinn zurück und berichtet ihm, was Ihr erreicht habt.>", progress = nil, completion = "Hallo, ja? Was? Ihr? Oh, Ihr seid einer von denen, die ich auf die Suche nach dem Auge des Zwielichts geschickt habe, oder?\n\nGute Arbeit, sehr gut. Ich schätze, das ist eine wichtige Lektion für Euch:\n\nNehmt niemals Befehle von einem großen violetten Ball an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25314] = {title = "Redenschreiben für Anfänger", objective = "Tötet Okrog außerhalb des Sitzes der Auserwählten auf dem Hyjal.", description = "Hört zu, <Name>. Ich habe herausgefunden, was Sie mit Jarod Schattensang vorhaben. Die Oger des Schattenhammers wollen ihn als Teil des diesjährigen Initiationsritus opfern.\n\nIch habe gehört, dass der Initiand, der dieses Jahr die Opferrede hält, ein Oger namens Okrog ist, aber jetzt kommt die Überraschung: Ihr seid nur knapp <Zweiter/Zweite> geworden!\n\nWenn wir Jarod befreien möchten, müsst Ihr diese Rede halten. Keine Sorge, ich schreibe Euch ein paar Stichworte auf. Ihr müsst nur dafür sorgen, dass Okrog auf seinem Weg vom Sitz der Auserwählten einen kleinen \"Unfall\" hat.", progress = "Nun, <Name>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Unser Plan ist nun fast vollständig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25315] = {title = "Abschlussrede", objective = "Benutzt das Initiationspodium in der Verdammniswacht, um die Abschlussrede zu halten.", description = "Ihr seid endlich fertig, <Name>damus.\n\nIch bin so stolz auf Euch und alles, was Ihr erreicht habt.\n\nHeute werdet Ihr eine Rede vor Euren Gleichrangigen halten und sie anfeuern, unsere Feinde zu vernichten, bis der Hyjal nur noch ein Häuflein Asche ist.\n\nVergesst nicht, <Name>damus. Es ist wichtig, dass Ihr die Gefühle Eures Publikums zu deuten wisst und Worte verwendet, die diesen Gefühlen entsprechen.", progress = "Seid Ihr gekommen, um mich kaltzumachen?\n\nNein… Ihr scheint mir… klar im Kopf.", completion = "Ihr. Ihr gehört ganz offensichtlich nicht zu denen.\n\nWer seid Ihr dann? Ein Verbündeter?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25316] = {title = "Hyjal in Flammen", objective = "Fliegt mit Aronus zum Hyjal und sprecht mit Ysera, sobald Ihr angekommen seid.", description = "<Name>! Wir haben schon so viel von Euch und Euren früheren Heldentaten gehört.\n\nEs ist gut, dass Ihr gerade jetzt hier seid, wo Azeroth Euch am meisten braucht.\n\nTodesschwinges Diener greifen den Hyjal an und haben vor, den zerstörerischen Ragnaros in unsere Welt zurückzubringen.\n\nAronus wird Euch zu Malfurions Streitmächten auf dem Hyjal bringen. Helft ihnen, wo Ihr könnt!", progress = nil, completion = "&lt;Ysera scheint in einer Art Trance zu sein.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25317] = {title = "Schützt den Weltenbaum", objective = "Sprecht mit Malfurion Sturmgrimm im Friedvollen Hain auf dem Hyjal.", description = "<Yseras Augen sehen abwesend aus, als würde sie Euch nicht ganz erkennen.>\n\nIch fühle es auch, <Klasse>. Ragnaros ist eingetroffen.\n\nWir müssen seine Diener vernichten, bevor er sich ihnen anschließen und ihnen seine Macht leihen kann.\n\nSucht Malfurion Sturmgrimm im Friedvollen Hain westlich von hier auf und helft seinen Streitmächten so gut Ihr könnt.\n\nIch muss im Smaragdgrünen Traum nach Antworten suchen. Ihr müsst den Weltenbaum beschützen, bis ich zurückkehre.", progress = nil, completion = "Ihr seid gerade rechtzeitig angekommen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25319] = {title = "Krieg dem Schattenhammer", objective = "Tötet 4 Zwielichtflammenrufer und 10 Zwielichtbezwinger.", description = "Gebt Euch keinen Illusionen hin, <Name>. Der Ausgang dieses Krieges entscheidet über das Überleben der Welt, wie wir sie kennen.\n\nDer Schattenhammerkult ist mit Todesschwinges Rückkehr sogar noch mächtiger geworden. Falls es ihnen gelingen sollte, den Weltenbaum an sich zu reißen, könnten sie uns einen Schlag versetzen, von dem wir uns nie erholen werden.\n\nEs ist an der Zeit, den Feind zurückzudrängen. Es ist an der Zeit, den Schattenhammer zu vernichten.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Aber ich fürchte, dass die Schlacht noch lange nicht vorüber ist.", rewards = "Plattenrüstung des druidischen WächtersHelm des NaturfürstenWiederverwerteter ZwielichtstabDonnerbüchse der FrontIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25320] = {title = "Die gefangene Späherin", objective = "Findet Späherin Larandia bei der Zwielichtblockade auf dem Hyjal.", description = "Ich habe von Euch gehört, <Name>, und ich kenne die Nachrichten, die Ihr aus dem Süden bringt. Die Schlacht hat eine Pattsituation erreicht.\n\nDoch ich fürchte, dass sich diese Lage mit dem Wiedererwecken des Feuerlords schlagartig ändern wird.\n\nEs sei denn natürlich, wir könnten das Schicksal zu unseren Gunsten beeinflussen.\n\nEine unserer Späherinnen wurde vom Schattenhammer gefangen genommen. Ich glaube, sie war im Besitz von unschätzbar wertvollen Informationen. Sucht im Zwielichtlager im Westen nach ihr.", progress = nil, completion = "Endlich kommt mir jemand zu Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25321] = {title = "Gefangene des Zwielichts", objective = "Beschafft Euch einen Schlüssel eines Zwielichtvorarbeiters im Schattenkommandoposten auf dem Hyjal.", description = "Ich habe fast einen ganzen Tag lang hinter den feindlichen Reihen gespäht, bis sie mich gefasst haben.\n\nDieser Angriff an unserer Front ist nicht das, was er zu sein scheint, <Name>.\n\nIch berichte Euch alle Einzelheiten, aber holt mich zuerst hier raus!\n\nNur die Vorarbeiter haben die Schlüssel zu diesen Käfigen.\n\nSoweit ich mich erinnern kann, halten sie sich in der Mitte des Kraters auf, mitten im Getümmel.\n\nSchaut, ob Ihr einem von ihnen einen Schlüssel abnehmen könnt.", progress = "Der Schlüssel, <Name>. Habt Ihr ihn?", completion = "Ich bin Euch sehr dankbar, &lt;Name&gt;. Ich werde unseren Leuten von meinen Erkenntnissen berichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25323] = {title = "Flammenbrecher", objective = "Tötet 30 ungebundene Flammengeister.", description = "Die großen Elementare, die uns belagern, sind keine einzelnen Wesen.\n\nEs sind mehrere geringere Geister, durch die Magie der Schattenhammerkultisten zu einem verbunden.\n\nMit dem wiederhergestellten Flammenseherstab sind wir mächtig genug, dieses Band zu lösen.\n\nSobald Ihr die gefährlicheren großen aufgespalten habt, vernichtet die kleineren Elementare.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. So gewinnen wir die Oberhand über den Feind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25324] = {title = "Ein interessanter Gefangener", objective = "Sprecht mit Hauptmann Saynna Sturmläufer in den Grabhügeln auf dem Hyjal.", description = "Der Schattenhammer möchte Fandral Hirschhaupt befreien?\n\nMalfurion ist der Meinung, dass seine Verderbtheit weit fortgeschritten ist... und dies ist der beste Beweis dafür.\n\nWir können auf keinen Fall zulassen, dass unser Feind einen so mächtigen Erzdruiden in die Finger bekommt.\n\nIch habe einen Plan, <Name>. Wir werden den Gefangenen durch den Smaragdgrünen Traum fortschaffen. Es wird riskant, aber bei den ganzen Kultisten hier ist es vielleicht unsere einzige Hoffnung auf Erfolg.\n\nBringt diesen Schlüssel zu Saynna Sturmläufer in den Grabhügeln im Nordosten.", progress = nil, completion = "Der Drache hat vielleicht Recht. Der Schattenhammer hat unsere Sicherheitsmaßnahmen umgangen. Und dies ist schließlich unser gefährlichster Gefangener.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25325] = {title = "Durch den Traum", objective = "Liefert Erzdruide Fandral Hirschhaupt an Alysra am Eingang zu den Grabhügeln auf dem Hyjal aus.", description = "Alysras Plan ist vielleicht notwendig, <Name>. Ich weiß nicht, wie lange wir die Kultisten noch zurückhalten können.\n\nFandral Hirschhaupt wird von mächtigen Zaubern gebunden. Er könnte Euch nicht einmal im Smaragdgrünen Traum entkommen.\n\nDoch seid vorsichtig, denn soweit wir wissen hat der Alptraum sich innerhalb des Traums auf diesen Teil der Welt ausgebreitet.\n\nBringt Fandral an die Oberfläche und übergebt ihn Alysra. Wollen wir hoffen, dass er auf der Mondlichtung sicherer aufgehoben ist als hier.", progress = "Ist Hirschhaupt bei Euch, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ich werde Fandral selbst zur Mondlichtung bringen.\n\nSein Gefängnis wird weit genug von der Schlacht hier entfernt liegen.", rewards = "Handschutz der Arkanen GefangenschaftSchalldämpfende KapuzeTraumzerfetzender DolchDer folgende Zauber wird auf euch gewirkt:\n\nCue Fandral to Despawn\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25328] = {title = "Gar'gol muss gehen!", objective = "Besorgt den rostigen Schädelschlüssel aus Gar'gols persönlicher Schatzkiste.", description = "<Kristoff reckt seinen Hals, um Euch in die Augen blicken zu können.>\n\nHört zu, Ihr müsst mich hier rausholen. Entweder fressen sie mich oder sie übergeben mich dem Schattenhammer. Vielleicht sogar beides.\n\nSie haben mich in Ketten gelegt und sie mit einem Schloss fest gesichert. Gar'gol bewahrt den Schlüssel in seiner persönlichen Schatzkiste auf. Tötet Gar'gol, wenn Ihr müsst, solange Ihr mir den Schüssel besorgt!\n\n<Kristoff schüttelt verzweifelt seine Gliedmaßen.>", progress = "Schlüssel? Jetzt? Bitte?", completion = "&lt;Kristoff streckt sich nach unten, um den Schlüssel zu schnappen.&gt;\n\nDas wurde aber auch Zeit!\n\n&lt;Er windet sich in seinen Fesseln und versucht, das Schloss auf seinem Rücken zu erreichen.&gt;\n\nÄh… könnt Ihr mir hier vielleicht ein bisschen helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25329] = {title = "Die Macht der Steinbrecher", objective = "Stört die Schattenhammerzeremonie Cho'galls.", description = "Der Schattenhammer meint also, hier eine Ogerarmee aufstellen zu können? Mitten im Gebiet der Horde?\n\nDas werden wir sehen.\n\nOger respektieren nur eines: Stärke. Ich möchte, dass Ihr bei der Zeremonie von Cho'gall ein Attentat verübt, <Name>. Reißt die Tore Düsterbruchs auf, begebt Euch in die Menge der Anwesenden und ermordet sie.", progress = nil, completion = "Wir haben es geschafft! Cho'gall wurde von Euch absolut gedemütigt. Seine Diener sind tot, die Gordok sind in alle Richtungen verstreut, und alle werden von der Macht der Horde erfahren! Lok'tar, &lt;Name&gt;! Ihr habt Euch Eure Belohnung redlich verdient.", rewards = "SteinbrecherschleudererPredigtunterbrechende HandschuheOgerhelmkappeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25330] = {title = "Verschwendetes Fleisch", objective = "Benutzt den Froststurmkristall, um 4 brennende Bittsteller zu löschen.", description = "Schaut Euch diese Narren an. Die Hälfte von ihnen wird nicht einmal diese Prüfung bestehen.\n\nSie sind es nicht wert, in unsere inneren Kreise aufzusteigen. Aber vielleicht… vielleicht eignen sie sich ja für niedere Lakaiendienste.\n\nNehmt diesen Edelstein und nutzt seine Macht, um einige der weniger fähigen Bittsteller zu retten. Diejenigen, die keine Chance auf Erfolg haben. Bevorzugt jene, die in Flammen stehen.", progress = "Habt Ihr geeignete Diener für mich gefunden, Siskdamus?", completion = "Ausgezeichnete Arbeit, Agamoldamus. Ich lasse die Diener, die Ihr für mich ausgesucht habt, in ihre neuen Pflichten einweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25332] = {title = "Holt mich hier raus!", objective = "Begleitet Kristoff aus Gar'gols Unterschlupf hinaus.", description = "<Ihr greift nach oben, um Kristoffs Fesseln zu lösen.>\n\nGut! Spurtet zum Ausgang. Ich werde Euch folgen.\n\nWenn wir getrennt werden, meldet Euch wieder hier und stellt sicher, dass sie mich nicht erneut geschnappt haben.", progress = nil, completion = "Kristoff, Kristoff… Oh ja, jetzt erinnere ich mich. Ich habe ihn auf etwas geschickt, was man als Selbstmordmission bezeichnen könnte.\n\nEr hat überlebt? Das heißt dann wohl, dass er gescheitert ist.\n\nDennoch verdient Ihr eine kleine Entlohnung für Eure Mühen.", rewards = "Schulterschutz der leeren ErinnerungVernachlässigte SchleicherKapuze der deplatzierten TräumeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25333] = {title = "Die Macht der Schildwachen", objective = "Stört die Schattenhammerzeremonie Cho'galls.", description = "Der Schattenhammer? Hier?\n\nEs ist schwerwiegender, als ich dachte. Wir müssen dem ein Ende setzen. Ich weiß nicht, ob ich bereit bin, eine solche Offensive zu führen, aber ich werde nicht zulassen, dass etwas, was getan werden muss, unterlassen wird, nur weil ich Angst habe!\n\nIch werde die Streitkräfte der Mondfederfeste versammeln. Begebt Euch nach Düsterbruch, um die Aktivitäten von Cho'gall zu stören. Wir werden die Verwirrung, die dadurch entsteht, für unseren Angriff nutzen.", progress = nil, completion = "Willkommen zurück von der Schlacht! In den Augen der Gordunni wurde der Schattenhammer erniedrigt und aus Feralas vertrieben.\n\nWir haben die Ehre der Allianz heute in vollem Glanz gezeigt! Seid stolz!", rewards = "Bogen des SchattenblattsPredigtunterbrechende HandschuheSpäherkopfstückIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25334] = {title = "Die drohende Gefahr", objective = "Sprecht mit Scharfseher Gadra, um in Eure Geistertrance einzutauchen.", description = "Fühlt Ihr, wie wüt'nd die Elemente sind? Schon als wir gerade erst angekomm'n war'n, wollt'n sie uns angreif'n und fress'n. Wir müss'n sie beruhigen, aber dazu müss'n wir erstmal wiss'n, was sie überhaupt aufbringt.\n\nKommt und setzt Euch neb'n mich ans Feuer. Lasst Eure Gedank'n in den Flamm'n streif'n... Lasst Eur'n Geist in die wahre Bedrohung blick'n.", progress = "Verliert Euch ganz in den tanz'nden Flamm'n. Kommt mit mir, tiefer nach Vashj'ir, damit wir das Gesicht unseres Feindes kennenlern'n.", completion = "Wir dacht'n alle, dass es die Naga sind, aber ich wusste nich', dass der Schattenhammerkult sich unter den Well'n versteckt. Sie verderb'n und verdreh'n die Elemente und mach'n sie zu dies'n Schreck'n.\n\nWir müss'n diese beid'n Bedrohung'n bekämpf'n, um eine Chance auf Fried'n in Vashj'ir zu hab'n. Wir hab'n noch nich' genug Leute, um das zu tun.\n\nKommt, &lt;Klasse&gt;. Wir hab'n viel zu tun.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForcecast Phase Shift 2: Intro Cave\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25336] = {title = "Das Gefäß wird getestet", objective = "Tötet 10 Eisenfellbären oder Langzahnläufer, und benutzt das Gefäß für Bestienmuisek, um die gefallenen Bestien zu schrumpfen und einzufangen.", description = "Meister Uzer'i hat mich in der Herstellung mächtiger Geisterwaffen unterrichtet. Ich werde Euch unterweisen, wie man die Waffen herstellen kann, wenn Ihr mir die Möglichkeit gebt, mein Handwerk zu verfeinern.\n\nDieses Gefäß kann besiegte Kreaturen verkleinern und gefangen halten. Wir brauchen zuerst Eisenfellbärenmuisek und Langzahnläufermuisek. Tötet die Kreaturen und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihre Geister fliehen können.", progress = "Konntet Ihr das Bestienmuisek erhalten?", completion = "Wie mein Meister es mir erklärt hat...\n\nNach einem gewaltsamen Tod kann das Muisek einer Kreatur fliehen und Rache verlangen. Durch das Schrumpfen der Kreaturen wird die Flucht verhindert. Das habt Ihr ja auch gemacht, &lt;Name&gt;. Jetzt können wir das Muisek nach Herzenslust verwenden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25337] = {title = "Muisek von Hippogryphen", objective = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", description = "Als nächstes sind die Hippogryphen dran.\n\nLaut Meister Uzer'i sind die Hippogryphen den Nachtelfen jahrelang treue Begleiter gewesen, und ihre Geister sind loyal und standhaft.\n\nIch glaube nicht, dass es ihnen auffallen wird, wenn ein paar Hippogryphen fehlen, und selbst wenn, dann soll mich das nicht stören. Wir brauchen Muisek von zehn Fransenfederhippogryphen, die in der Wildnis südlich von hier zu finden sind.", progress = "Konntet Ihr die Hippogryphen einfangen?", completion = "Mein Meister hat immer gesagt, \"wenn man ein Tier tötet und das Muisek flieht, so kann es die Form einer noch wilderen Bestie annehmen\". Es ist wirklich gefährlich. Ich danke Euch, dass Ihr mir bei meinem Studium helft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25338] = {title = "Muisek von Treants", objective = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, <Name>. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet drei umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", progress = "Konntet Ihr die wandernden Waldgänger einfangen?", completion = "Danke, &lt;Name&gt;. Das ist das erste Mal, dass ich mit Treantmuisek arbeite...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25339] = {title = "Rache an den Nordschwingen", objective = "Tötet 6 Harpyien der Nordschwingen und 6 Windruferinnen der Nordschwingen.", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. <Name>, rächt mich.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt dem Geist eines alten Tauren Ruhe gegeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25340] = {title = "Dunkles Herz", objective = "Talo Dornhuf im Camp Mojache will das dunkle Herz von Edana Hasskralle.", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", progress = "Der Hass, den Edana über das Land verbreitet, muss gestoppt werden.", completion = "Jetzt weiß ich, dass Edana wahrhaft tot ist. Dieses Herz; ich werde es in Erinnerung an das behalten, was Ihr hier für mich getan habt, &lt;Name&gt;. Danke.", rewards = "Dunkles KristallhüftbandArmschienen des eroberten HerzensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25341] = {title = "Die Gordunnikugel", objective = "Erlangt eine Gordunnikugel von einem Hexenmeister der Gordunni.", description = "Während Ihr Schädel eingeschlagen habt...\n\nWir haben Berichte erhalten, laut denen die Oger eine größere Bedrohung darstellen als normalerweise. Ihre Hexenmeister wurden mit Kugeln gesehen, die Gegenstände mit großer Macht sein könnten.\n\nEs wäre einfach, sie als etwas anderes abzutun, aber wir müssen der Sache nachgehen, damit es keine bösen Überraschungen gibt. Bringt mir eine dieser Kugeln.", progress = "Habt Ihr die Kugel?", completion = "Gut gemacht. Lasst mich mal sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25342] = {title = "Sprecht mit Swar'jan", objective = "Bringt die Gordunnikugel zu Swar'jan in der Festung der Steinbrecher.", description = "Hmpf, wir hatten Glück und Pech zur gleichen Zeit. Glück, dass ich Euch gebeten habe, mir diesen Gegenstand zu bringen, und Pech, weil sich meine Befürchtungen bewahrheitet haben. Dieses Ding stinkt förmlich nach Verderbtheit.\n\nUnd es ist auch viel zu neu, um einfach in den Ruinen gefunden worden zu sein. Jemand versorgt die Oger und wir müssen herausfinden, wer, bevor es ein Problem wird.\n\nBringt dieses dreckige Ding zu Swar'jan, dem Hexenmeister oben auf dem Wachturm. Er hat oft gute Ideen - wenn ich Ihr wäre, würde ich mir seine Meinung anhören.", progress = "Ja?", completion = "Was habt Ihr für mich? Ihr sagt, Ihr habt sie von den Gordunni?\n\nEkelhaft...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25344] = {title = "Ogerentführung", objective = "Benutzt die modifizierte Seelenkugel, um einen Ogermagier der Gordok gefangenzunehmen.", description = "Es ist unmöglich, dass die Gordunni sie selbst hergestellt haben. Sie werden damit versorgt. Jemand macht ihnen Machtgeschenke und wir müssen herausfinden, wer.\n\nDie Gordok, die mit der Aufgabe geehrt werden, Düsterbruch zu bewachen, werden mehr darüber wissen. Orhan wird dich sicherlich beauftragen, ihre Reihen zu lichten, aber ich brauche einen, der am Leben ist.\n\nBringt die Kugel zurück. Sie ist einem Seelenstein ähnlich, und ich habe einige... Änderungen vorgenommen. Haltet die Kugel vor einem geschwächten Gordok hoch, und bringt ihn hier her, sobald Ihr ihn gefangen habt.", progress = nil, completion = "Ahh, man kann den Welpen in ihm spüren. Wir sollten ihm ein paar Fragen stellen...", rewards = "Armschienen des SeelendiebsModifizierter ZauberschildSchultern des OgerfängersBedeckung des EntführersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25345] = {title = "Muisek von Feendrachen", objective = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", description = "<Name>, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, <Name>. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", progress = "Konntet Ihr das Muisek der Feendrachen einfangen?", completion = "Danke, &lt;Name&gt;. Jetzt steht die geistige Macht der Feendrachen auch uns zur Verfügung.\n\nIch hoffe, Ihr seid willens, eine weitere Aufgabe für mich zu vollbringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25346] = {title = "Bergriesenmuisek", objective = "Tötet 7 Bergriesen und benutzt das Gefäß für Bergriesenmuisek, um die gefallenen Bergriesen zu schrumpfen und einzusammeln.", description = "Die Bergriesen haben die Berge verlassen, um den Nachtelfen zu helfen, als die Brennende Legion erschien. Ihr könnt sie leicht an ihrer Größe erkennen, und auch schon von Weitem daran, wie der Boden wackelt, wenn Ihr Euch ihnen nähert.\n\nIch bin sehr interessiert daran, Kraft in diesem Ausmaß nutzen zu können. Tötet sieben Bergriesen und benutzt das Muisekgefäß, um ihre mächtigen Muisek einzufangen.", progress = "Konntet Ihr die Bergriesen gefangennehmen?", completion = "Stellt Euch nur die Möglichkeiten vor, die wir nun haben, &lt;Name&gt;. Mit den Materialien, die Ihr gesammelt habt, werden wir den Muisek dieser Kreaturen festhalten können, wo immer wir es wünschen", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25349] = {title = "Die verdrehten Schwestern", objective = "Tötet 7 verderbte Dryaden.", description = "Ich habe von Eurem Kampf mit den verderbten Drachen gehört, <Name>, und ich möchte Euch für Euren Mut danken... leider habe ich schlechte Nachrichten.\n\nDie Dryaden des Waldes haben sich uns gegenüber immer friedlich verhalten, obwohl sie Verbündete der Nachtelfen sind. Sie wurden jedoch grausam und ihr Geist wurde verdreht, so dass sie nun alle angreifen, die die Wildnis östlich von hier betreten.\n\nIch mache mir um die Sicherheit der Flüchtlinge Sorgen, <Name>. Bitte, bereitet den verdrehten Dryaden ein Ende.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;, aber die Geschichte Eurer Jagd erfüllt mich mit Sorge. So viele hätten es nicht sein sollen.\n\nDie Krankheit breitet sich weiter aus...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25350] = {title = "Der verschollene Lehrling", objective = "Sucht nach dem verschollenen Lehrling in den Dunkelnebelruinen.", description = "<Klasse>, wenn Ihr kurz Zeit hättet...\n\nEiner meiner Studenten hat sich alleine nach Süden zu den Dunkelnebelruinen aufgemacht. Ich habe ihn gewarnt, dass es zu gefährlich sei, aber er war zu aufgeregt, um mir zuzuhören... \n\nEstulan erlaubt nicht, dass wir ihm folgen. Falls Ihr in diese Richtung unterwegs seid, könnt Ihr bitte nach ihm schauen?", progress = nil, completion = "&lt;Die Leiche des Lehrlings ist kalt. Er ist schon eine Zeit lang tot.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25352] = {title = "Wischt den Sims sauber", objective = "Tötet 8 Zwielichtsturmrufer und 5 heulende Rissbewohner.", description = "Ihr habt in dem Unterschlupf ausgezeichnete Arbeit geleistet, <Name>. Während Eurer Abwesenheit habe ich am Schrein gebetet. In meinen Visionen hatte Goldrinn ein aufmerksames Auge auf Euch.\n\nAber wir verharren schon zu lange in Verteidigungsstellung. Es ist Zeit, dem Schattenhammer direkt gegenüberzutreten.\n\nFliegt hinauf auf den Gewittersims und durchkreuzt ihre Vorhaben. Tötet die Sturmrufer und Monstrositäten, die sie entfesseln wollen!", progress = nil, completion = "Ihr hättet die Schlacht von hier aus sehen sollen! Die Leichen stürzten nur so von den Klippen. Spektakulär!", rewards = "Gürtel der bindenden LäuterungStampfer des WolfsrufersArmschienen des einsamen WolfsLo'Goshs ZornIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25353] = {title = "Blitz in der Flasche", objective = "Sammelt ein aufgeladenes Kondensatorglas von einem Blitzkanal des Schattenhammers.", description = "Als ich am Schrein betete, gewährte Goldrinn mir eine weitere Vision. Ich sah Euch entschlossen auf dem Gewittersims stehen, mit Blitzen in Euren Händen. Goldrinn schien der Meinung zu sein, dass dies von größter Wichtigkeit sei, aber ich verstehe nicht, was der Ahn geplant hat...\n\n<Name>, geht zum Gewittersims. Der Schattenhammer führt Versuche mit etwas durch, das sich \"Blitzkanal\" nennt. Untersucht diese Kanäle und verwendet dann dieses Totem, um den Geist von Goldrinn zu rufen und zu sehen, was er auf dem Herzen hat...", progress = "So treffen wir uns wieder, <Klasse>. Wo Ihr wandelt, hinterlasst Ihr eine Spur aus Angst und Verwirrung.", completion = "Also ist es wahr! Ihr tragt wirklich Blitze in Euren Händen.\n\nIhr seid der Auserwählte, &lt;Name&gt;. Ihr werdet mein Champion sein und meine Rache in Reiche tragen, die ich nicht betreten kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25354] = {title = "Wischt den Sims sauber", objective = "Tötet 8 Zwielichtsturmrufer und 5 heulende Rissbewohner.", description = "Der Schrein ist sicher, die Oger sind in Aufruhr. Genug. Es ist an der Zeit, in die Offensive zu gehen.\n\nEtwas Böses braut sich über uns auf dem Gewittersims zusammen. Wir müssen den Zorn der Ahnen entfesseln!\n\nFliegt hinauf zum Gewittersims und vernichtet die Anhänger des Schattenhammers dort. Zerschmettert sie, <Name>! Erschlagt ihre Kreaturen und werft ihre Körper den Berg hinab!", progress = nil, completion = "Beeindruckend, &lt;Name&gt;. Sehr beeindruckend.\n\nIn Euch vereint sich die Stärke des Wolfsahnen mit der Weisheit, Eure Kräfte geschickt einzusetzen. Ich salutiere vor Euch.", rewards = "Gurt des uralten WolfesTreter des TraumwolfsArmschienen des WolfsrufersGoldrinns LäutererIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25355] = {title = "Blitz in der Flasche", objective = "Sammelt ein aufgeladenes Kondensatorglas von einem Blitzkanal des Schattenhammers.", description = "Während Ihr in dem Unterschlupf wart, gewährte Lo'Gosh mir eine Vision, <Name>. Ich sah Euch den Gewittersims entlang spazieren, mit Blitzen in Euren Händen. Die Vision war sehr bewegend. Lo'Gosh schien der Meinung zu sein, dass dies von größter Wichtigkeit sei. Wir dürfen den Ahnen nicht enttäuschen.\n\nDer Schattenhammer führt Versuche mit Geräten durch, die sie \"Blitzkanal\" nennen.\n\nUntersucht diese Kanäle und verwendet dann dieses Totem, um den Geist von Lo'Gosh zu rufen und zu sehen, was er vorhat...", progress = "So treffen wir uns wieder, <Klasse>. Wo Ihr wandelt, hinterlasst Ihr eine Spur aus Angst und Verwirrung.", completion = "Also ist es wahr! Ihr tragt wirklich Blitze in Euren Händen.\n\nIhr seid der Auserwählte, &lt;Name&gt;. Ihr werdet mein Champion sein und meine Rache in Reiche tragen, die ich nicht betreten kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25356] = {title = "Zum Gipfel", objective = "Leiht Euch von Shyn einen Windreiter und sprecht mit Kanati Grauwolke am Westlichen Gipfel in Tausend Nadeln.", description = "Wir sind dabei, am Westlichen Gipfel für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Shyn wird Euch meinen Windreiter zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Kanati Grauwolke, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", progress = nil, completion = "Jawn schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25357] = {title = "Verschafft uns Zeit", objective = "Tötet 8 Räuber des Zin'jatar.", description = "So viele gute Männer mussten heute ihr Leben lassen. Ohne Euch wäre diese Zahl sogar noch höher.\n\nIhr habt unseren Dank.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", progress = "Habt Ihr den Naga einen Grund zum Nachdenken gegeben, <Klasse>?", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um sie abzulenken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25358] = {title = "Nerventonikum", objective = "Mack möchte, dass Ihr 5 Stück gesunkene Fracht im Tang'tharwald sammelt.", description = "Wie es mir geht, fragt Ihr?\n\nNun, nachdem ich von einem riesigen Seemonster vom Deck unseres Schiffes gerissen wurde und im Meer kurz vor dem Ertrinken stand… gewöhnungsbedürftig, würde ich sagen!\n\nEhrlich gesagt bin ich mit den Nerven total am Ende.\n\nWenn Ihr einige der Vorräte zusammensuchen könntet, die in den umliegenden Schiffswracks umhertreiben, könnte ich sicher etwas aus dem Hut zaubern, was die Lage etwas erträglicher macht.", progress = "Konntet Ihr ein paar der Vorräte sammeln, <Volk>?", completion = "Ich glaube, wir beide wissen, was in diesen Kisten vor sich geht…\n\nGenau… Ferrrmenntation! Hier, bitte. Mein persönliches Geheimrezept.\n\nKein anderer Kerl würde Euch das hier geben!", rewards = "Ihr bekommt:\n\nMacks Tiefseegrog"}
MultiLanguageQuestData['de'][25359] = {title = "Toshes Rache", objective = "Sprecht mit Toshe Chaosberster in den Ruinen des Thelseraitempels.", description = "Ihr habt Toshe in der Dunstlichtkammer getroffen, oder? Er ist einigen der fliehenden Naga zu den Ruinen im Osten gefolgt und hat dann Hilfe angefordert.\n\nSucht so schnell wie möglich in den Ruinen nach Toshe. Wenn Ihr herausfindet, was die Naga wollen, lasst es uns bitte wissen!", progress = nil, completion = "Ich erinnere mich an Euch. Ihr wart da, als sie uns in der Höhle angegriffen haben.\n\nSchön, Euch an meiner Seite zu wissen, &lt;Klasse&gt;. Seid Ihr bereit für ein wenig Rache?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25360] = {title = "Den Krebs straft man nicht mit Ersäufen", objective = "Tötet 10 grüne Sandkrebse.", description = "Diese Krebse sind nicht nett. Nicht. Nett.\n\nSams endlose Bohrerei versetzt sie in Aufruhr. Ich weiß aus Erfahrung, dass Sam sich nicht aufhalten lässt, also sollten wir uns um die andere Partei in dieser Angelegenheit kümmern. Meint Ihr nicht auch?", progress = "Vorsicht. Sie kneifen.", completion = "Ist hier eigentlich alles riesengroß? Ohhh! Da kommt mir eine Idee. Vielleicht gibt es hier ja auch irgendwo ein paar stattliche Seegoblins.\n\nVielen Dank übrigens!", rewards = "Riesengroße StampferKrebsknackerbrustschutzGamaschen der AlbinobrachyuraIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25361] = {title = "Schimmer für einen neuen Umhang", objective = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Schädelspalter nach Camp Mojache.", description = "Grüße, <Klasse>. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.\n\nMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.", progress = "Die Grimmlingflitzer können gefährliche Tierwesen sein, wenn man sie provoziert. Seid vorsichtig im Umgang mit ihnen, <Klasse>. Und passt noch viel mehr auf etwaige Nachtelfen in der Gegend auf. Diese lästigen Narren überfallen einen gern in den Wäldern.\n\nWenn Ihr genug Flügel habt, lasst es mich wissen, ich werde Euch sicher gut entlohnen!", completion = "Wunderbar, &lt;Klasse&gt;! Die sind perfekt. Das sind genug, um einen Umhang für Korrin zu fertigen und vielleicht noch anderes! Danke.\n\nIch hoffe, die Reise war nicht zu gefährlich... Das Gebiet von Feralas ist nicht gerade als harmlos bekannt, aber Ihr habt Euch offensichtlich recht gut geschlagen.\n\nNochmals danke, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25362] = {title = "Eine grausige Entdeckung", objective = "Bringt 20 Grimmtotemhörner zu Krueg Schädelspalter in Camp Mojache.", description = "Der Stamm der Grimmtotem! Diese feigen Verräter treiben sich hier immer noch herum, was?\n\nIhr müsst wieder dorthin zurück, <Klasse>. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn möglich. Die Grimmtotem sollten nicht einfach als Kleinigkeit abgestempelt oder unterschätzt werden. Geht zurück und tötet sie. Färbt die Flüsse Feralas' Rot mit ihrem dunklen Blut.", progress = "Nehmt meine Worte ernst, <Klasse>, der Stamm der Grimmtotem ist böse. Wenn Ihr herausgefunden habt, wo sie sich aufhalten, so müsst Ihr diesen Ort aufsuchen und ihren Stamm zuerst angreifen... bevor sie in unsere Ländereien eindringen und unsere Dörfer plündern oder unser Land einnehmen.", completion = "Verräter an der Horde und an ihrem eigenen Volk...\n\nIch glaube, sie sind nicht ganz unnütz. Zumindest werden wir feine Trinkhörner daraus machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25363] = {title = "Krieg gegen die Waldpfoten", objective = "Bringt Hadoken Flinkschreiter im Camp Mojache 10 Mähnen eines Waldpfotengnolls.", description = "Die Gnolle... sie sind mehr als nur ein Ärgernis. Sie sind eine konstante Bedrohung für die Existenz dieses gesamten Lagers! Es ist unwichtig, ob sie Eingeborene des Feralas sind oder nicht. Wenn wir uns nicht gegen sie wappnen, werden wir uns eines Tages aus dem gesamten Gebiet vertrieben sehen.\n\nDie Gnollangriffe auf das Lager wurden in letzter Zeit heftiger. Wir brauchen Eure Hilfe dabei, ihre Anzahl zu reduzieren. Bringt mir zehn ihrer Mähnen und ich werde Euch stattlich für Eure Mühe entlohnen.\n\nLos!", progress = "Wir schlagen sie zurück und trotzdem greifen sie weiter an! Irgendjemand oder irgendetwas muss sie zur Raserei treiben... Oh, Ihr seid wieder da, was, <Name>? Habt Ihr die Mähnen, die ich benötige, um das Kopfgeld auszahlen zu können?", completion = "Dies zeugt von einem guten Anfang, &lt;Name&gt;. Euer Geschick als Soldat verdient Lob.\n\nIhr seid nicht der Einzige, dem ich diesen Auftrag gab. Viele haben bereits vor Euch gegen sie gekämpft und in der Vergangenheit haben unsere Bemühungen sie in Schach gehalten. In letzter Zeit haben jedoch ihre Versuche, nordwärts in unser Einflussgebiet einzudringen, dramatisch zugenommen. Ihre Angriffe sind außerdem wilder geworden... fast als wären sie verzweifelt.\n\nIch habe allerdings einen Plan, &lt;Name&gt;, der die Sache mit ihnen ein für alle Mal erledigen sollte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25364] = {title = "Schlag gegen die Alphas", objective = "Töte 5 Alphas der Waldpfoten.", description = "Die Widerstandsfähigkeit der Gnolle kann sich leider mit ihrer Brutalität und Dummheit messen. Ich habe die Gnolle immer und immer wieder aus unserem Lager vertrieben und sie sind nur aufgrund der Gnade unseres Häuptlings noch nicht ausgerottet.\n\nIm Laufe der Jahre wurde es zu einem wahren Tanz aus Stärke und Dominanz. Wenn sie noch mehr werden und damit drohen, das Lager anzugreifen, müssen wir die Alphas, die stärksten Gnolle, ausmerzen.\n\nDas wird sie zurück in die Wälder vertreiben und uns etwas Frieden einbringen, zumindest, bis sie die erteilte Lektion wieder vergessen haben.", progress = nil, completion = "Ihr habt getan, was ich von Euch verlangt habe, und dafür zolle ich Euch Ehre. Nehmt dies als kleine Belohnung für Eure Anstrengungen, &lt;Name&gt;.\n\nNun, da wir ihre Zahlen geschwächt und ihre Anführer getötet haben, werden es sich die Gnolle zweimal überlegen, unser Lager anzugreifen. Das löst aber unser eigentliches Problem nicht...\n\nEs muss einen Grund geben, warum die Gnolle in einen solchen Wahnsinn verfallen sind. Findet heraus, wo der Ursprung dessen liegt, bevor sie sich neu formieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25365] = {title = "Waldpfotennachforschung", objective = "Findet die Schlachtpläne der Gnolle irgendwo in den Gnoll-Lagern südlich vom Camp Mojache.", description = "Gnolle sind zwar nicht die Hellsten, aber sie werden bestimmt die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert haben. Wenn wir diese Pläne finden würden, hätten wir eine bessere Vorstellung davon, was sie so aufbringt.\n\nIch möchte, dass Ihr zu den Waldpfoten zurückgeht und nach allem sucht, was Ähnlichkeit mit ihren Schlachtplänen haben könnte. Irgendwas muss es geben, ihre Angriffe waren einfach zu gut koordiniert. Findet diese Schlachtpläne und kommt zu mir zurück, sobald Ihr sie habt.", progress = nil, completion = "Eine Untersuchung der Karte zeigt, dass es sich um die Schlachtpläne handelt, die Hadoken Flinkschreiter haben will. Zahlreiche Pfeile, die vielleicht Truppenbewegungen darstellen, befinden sich auf der Karte, allerdings scheinen die meisten nach Süden zu deuten, nicht nach Norden, wo das Camp Mojache liegt.\n\nEin anderer Teil der Karte enthält ein Bild von etwas, das man für irgendein großes Insekt halten könnte. Darunter befindet sich eine Art Strichliste. So, wie die Gnolle aussehen, stellt diese vielleicht ihre Verluste gegen das unbekannte Ungeziefer dar...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25366] = {title = "Die Schlachtpläne", objective = "Bringt die Schlachtpläne der Waldpfoten zu Hadoken Flinkschreiter in Camp Mojache.", description = "Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Flinkschreiter in Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.", progress = "Willkommen zurück, <Name>. Habt Ihr ein paar nützliche Hinweise auf die Pläne der Gnolle gefunden?", completion = "Ah, das ist genau, was wir gebraucht haben. Auch wenn ich nicht sehr geschickt darin bin, das ganze Gekritzel auf dieser Karte zu entziffern, so habe ich doch in meinem Leben genug Schlachtpläne gesehen, um zu verstehen, was mit den Gnollen passiert. Es sieht so aus, als würden sie derzeit einen Zwei-Fronten-Krieg führen. Einen mit uns... Aber wie es scheint, konzentrieren sie außerdem einen Großteil ihrer Energie auf einen Feind im Süden.\n\nHier läuft mehr, als auf den ersten Blick zu erkennen ist. Wir sollten möglichst bald herausfinden, wer dieser andere Feind ist, dem sie gegenüberstehen.", rewards = "SchnellschrittstiefelAuf Euch wartet eine dieser Belohnungen:\n\nHadokenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25367] = {title = "Zukk'ash-Plage", objective = "Bringt Hadoken Flinkschreiter im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.", description = "Schenken wir unseren angesammelten Erkundungen Glauben, so gehört der Gegner südlich der Gnolle einer insektenartigen Rasse an. Offen gesagt spielt es keine Rolle, solange sie lebendig sind. Wenn sie die Gnolle gegen uns aufhetzen, dann sind sie eine mindestens genauso große Bedrohung - wenn nicht sogar eine größere - als die Gnolle selbst.\n\nDringt tief in das Gebiet vor, in dem die Insekten der Zukk'ash hausen; auch bekannt als Gewundene Tiefe. Dezimiert ihre Anzahl, berichtet mir von Euren Entdeckungen und bringt ihre Knochenpanzer als Beweis Eurer Taten zurück.", progress = "Was macht die Jagd, <Name>? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Gut gemacht, &lt;Klasse&gt;. Obwohl man der hohen Ausbreitung der Zukk'ash mit nichts anderem als einer wahren Invasion entgegentreten kann, so habt Ihr uns doch etwas Zeit verschafft, um eine geeignete Strategie entwickeln zu können.\n\nIch werde dafür sorgen, dass man diese Knochenpanzer untersucht; wir müssen alles über sie herausfinden, bevor wir es mit dem zu tun bekommen, was sich unglücklicherweise als eine schwerwiegendere Angelegenheit als angenommen entwickelt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25368] = {title = "Verinias der Verwachsene", objective = "Besiegt Verinias den Verwachsenen.", description = "Die anderen Geister und ich werden von einem bösartigen Dämon namens Verinias gefangen gehalten; eine wahnsinnige, verunstaltete Bestie, die sich seit Jahrtausenden an unseren Seelen labt.\n\nDie Seelen und die arkane Magie, die Ihr mir gebracht habt, werden es einfach machen, ihn herauszulocken. Nehmt diese kondensierte Essenz zu dem toten Baum weit im Norden der Ruinen. Benutzt sie, um Verinias herauszulocken und tötet ihn, so dass ich endlich wieder in Freiheit sein kann.", progress = nil, completion = "Ich bin frei... endlich! Oh, es tut so gut, frei zu sein...\n\nOh, Ihr habt es gesehen, oder?", rewards = "Sensirias TuchVerdrehte GamaschenVerlockende FußpolsterArmschienen der konzentrierten EssenzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25369] = {title = "Zornstachel", objective = "Besiegt Zornstachel in der Gewundenen Tiefe und bringt seine Drüsen zu Hadoken Flinkschreiter im Camp Mojache in Feralas zurück.", description = "Einer unserer Späher berichtete, dass er bei den Untersuchungen der Gewundenen Tiefe ein riesiges Insekt - viel größer als die anderen gesichteten Insekten - gesehen habe, das durch das verschlungene Gelände umherstreift. Es ist nicht nur größer, es scheint auch eine Art Aura abzusondern, was die anderen Insekten nicht tun. Wir haben ihm einen Namen gegeben - Zornstachel.\n\nEine Untersuchung der Innereien dieser Bestie wäre von unschätzbarem Wert, um herauszufinden, wie man mit dieser Bedrohung am besten umgehen kann. Schneidet seine Sekretionsdrüsen heraus und bringt sie sofort zu mir zurück!", progress = "Konntet Ihr Zornstachel bereits besiegen?", completion = "Beeindruckend, &lt;Klasse&gt;... sehr beeindruckend! Sollte Zornstachel wirklich eine ihrer stärksten Kreaturen sein, so werden sich die Untersuchungen der Bestie mit der Zeit als sehr wertvoll erweisen. Es liegt nun an mir, sicherzustellen, dass wir uns lange genug verteidigen können, um davon zu profitieren.\n\nBitte nehmt diese Prämie als Dankeszeichen des gesamten Camps an, &lt;Name&gt;. Gut gemacht.", rewards = "Ihr bekommt:\n\nSekretbedeckter Panzer"}
MultiLanguageQuestData['de'][25370] = {title = "Entzündete Elemente", objective = "Füttert die Feendrachen mit Wacholderbeeren und tötet 4 Zwielichtzünder.", description = "Das ist kein natürliches Ereignis, <Name>. Dahinter muss eine zwielichtige Macht stecken, die wir nicht bedacht haben.\n\nEs kann sein, dass derjenige, der diese elementaren Störungen verursacht, sich mit böser Magie vor unseren Augen verbirgt.\n\nIhr benötigt die Hilfe der Feendrachen, die sich in der Nähe des Weltenbaums aufhalten. Sie können die Illusionen unserer Feinde durchschauen.\n\nFüttert ihnen Wacholderbeeren, die in der Nähe wachsen, um ihr Vertrauen zu erlangen.", progress = "Schon zurück, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Wir dürfen nicht zulassen, dass die Spione des Schattenhammerkults sich so nahe am Weltenbaum aufhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25371] = {title = "Der abyssische Ritt", objective = "Lockt ein abyssisches Seepferdchen an und zähmt es.", description = "Wenn Ihr Euch in diesem Tang'tharwald fortbewegen wollt, braucht Ihr ein zuverlässiges Reittier. Ich glaube, mir ist etwas Besseres als eine Meeresschildkröte eingefallen. Und es ist auch ganz in der Nähe!\n\nBindet einen Köder an das Seil direkt westlich von uns und steigt dann auf das Seepferdchen, das dadurch angelockt wird.\n\nAber seid gewarnt. Es kann ein hartes Stück Arbeit werden, bis der Wille des Tiers gebrochen ist.", progress = "Die Eleganz dieser Tiere ist einfach atemberaubend. Sie werden perfekte Reittiere abgeben.", completion = "Beeindruckend! Ihr seht erschöpft aus. Offensichtlich ließ es sich nicht so einfach zähmen.\n\nMit einem treuen Reittier an Eurer Seite sollte das Leben hier unten gleich viel einfacher sein. Herzlichen Glückwunsch, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nGebändigtes abyssisches Seepferdchen"}
MultiLanguageQuestData['de'][25372] = {title = "Aessinas Wunder", objective = "Bringt das Herz des Waldes zu Hamuul Runentotem im Hain von Aessina auf dem Hyjal.", description = "<Die fingerartigen Zweige an einer von Nordus Gliedmaßen brechen auf. Zum Vorschein kommt ein unberührter, glitzernder Samen.>\n\nDies ist das Herz des Waldes, der Samen des Lebens.\n\nBringt ihn zu Eurem Erzdruiden im Hain von Aessina. Hamuul Runentotem wird sicher wissen, wie seine Macht zu erwecken ist. Ich verspreche Euch, dass der Geist der Wildnis nicht länger schweigen wird. Neues Leben wird aus der Asche des alten erblühen.\n\nDanke Euch, <Volk>. Meine Zeit hier ist um.", progress = "Ich bin mit meinem Latein am Ende, <Name>! Aessina schweigt.\n\nHabt Ihr etwas gefunden? Was ist das?", completion = "Das ist der Schlüssel, &lt;Name&gt;! Mit den Setzlingen, die Ihr für mich gesammelt, den Tieren, die Ihr auf dem gesamten Hyjal gerettet und dem Herz des Waldes, das Ihr jetzt auch noch entdeckt habt, können wir dieses Land direkt unter den Füßen des Schattenhammerkults wieder verjüngen. Stellt Euch nur ihre erstaunten Gesichter vor, wenn das Leben über das Chaos triumphiert...\n\nIch werde sofort mit der Zeremonie beginnen!", rewards = "Brustplatte der ViridianerneuerungTreter der WiederherstellungHandschuhe der gehegten WahrheitSchiftung der WiedergeburtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25373] = {title = "Die Bedrohung vom Hügel", objective = "Tötet 5 Hügelwächter der Gordunni.", description = "Ich bin stolz darauf, dass Mojache als sicherer Ort in der Wildnis von Feralas gilt, aber auch unserem Camp bleiben Bedrohungen nicht fern. Die Oger der Gordunni haben ein Gebiet in der Nähe des nördlichen Vorgebirges eingenommen und zerstören die Wildnis.\n\nDa unsere Brüder und Schwestern nun hier sind, um sich in Sicherheit zu bringen, kann ich nicht länger zulassen, dass die Oger in der Nähe sind. Begebt Euch nach Norden und vertreibt die Oger.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Leider gibt es noch mehr Arbeit zu verrichten, um das Camp weiterhin zu sichern. Hört mir zu.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25374] = {title = "Sasquatch-Sichtung", objective = "Tötet Großfaust.", description = "Ihr mögt es mit Euren eigenen Augen gesehen zu haben, aber meine Fernläufer berichteten mir von etwas, das mich sehr beunruhigt. Die Gordunni in den Hügeln haben einen riesigen wilden Sasquatch eingefangen.\n\nIch weiß nicht, wie lange sie ihn festgehalten haben, aber es ist sicherlich nicht aus Spaß an der Freude. Ich fürchte, sie wollen das misshandelte Biest auf Camp Mojache loslassen.\n\nTief im Außenposten der Gordunni halten sie den Sasquatch gefangen. Geht dorthin und tötet ihn, <Name>.", progress = nil, completion = "Nun kann ich problemlos ruhen, &lt;Name&gt;. Ihr habt unser Lager vor einer schrecklichen Bedrohung gerettet.", rewards = "Kniehosen aus YetifellGroße StiefelMojacheumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25375] = {title = "Die Zähmer zähmen", objective = "Tötet 6 Zähmer der Gordunni.", description = "Die Gordunni sind nicht für das Zähmen von Tieren bekannt. Wenn sie diese Fähigkeit erlernen, so ist das ein Grund, alarmiert zu sein. Nicht nur ist der Sasquatch, den sie gezähmt haben, eine enorme Gefahr für unser Lager - auch die Gordunni, die ihn eingefangen haben, müssen ihre rechte Strafe finden. Wenn wir sie am Leben lassen, können sie einfach einen weiteren Sasquatch einfangen.\n\nTötet die Zähmer der Gordunni und stellt sicher, dass die Oger verstehen, dass wir ihre Anstrengungen nicht tolerieren werden!", progress = nil, completion = "Gut. Hoffen wir, dass die Oger zumindest schlau genug sind, um zu verstehen, dass wir ihnen mit dieser Aktion eine Nachricht vermitteln wollten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25377] = {title = "Der Hort der Horde", objective = "Besiegt Akasha, um den Schlüssel zur Kiste der Horde zu bekommen. Öffnet dann mit dem Schlüssel die versunkene Kiste der Horde.", description = "<Es ist nicht ganz klar, welche Wesen diese zufällig wirkenden Markierungen auf dieses Pergament gekritzelt haben. Bei genauerer Betrachtung scheinen die obskuren Formen Orientierungspunkte zu sein.>\n\n<Ihr lasst Euren Blick über den Meeresboden wandern und seid der Meinung, einige der Punkte zu erkennen, unter anderem ein gesunkenes Schiff in der Nähe. Wenn Ihr mit Eurer Vermutung richtig liegt, sollte sich in der Nähe des Wracks eine Art Schatz befinden.>\n\n<Ihr kommt nicht umhin Euch zu fragen, was diese schuppige, schlangenartige Figur auf der Karte darstellen soll...>", progress = "<Das leicht verrostete Schloss sollte noch funktionieren.>", completion = "&lt;Ihr habt einen verlorenen Schatz entdeckt!&gt;\n\n&lt;Eure Gedanken überschlagen sich geradezu bei dem Gedanken, was sonst noch in der Tiefe des Meers verborgen sein könnte.&gt;", rewards = "Ihr bekommt:\n\nBiolumineszenter Rundschild"}
MultiLanguageQuestData['de'][25378] = {title = "Ysondres Aufforderung", objective = "Sprecht mit Ysondre am Smaragdgipfel in der Unteren Wildnis.", description = "Die Drachen der Natur... folgt ihrer Aufforderung, <Name>. Wartet nicht. Ysondres Aufforderung, ihr zu helfen, ist sowohl eine große Ehre als auch ein Omen schrecklicher Gefahren.\n\nSie sprach von einem Ort namens Smaragdgipfel. Ein Pfad, weitab der Hauptstraße, führt durch die Untere Wildnis zu den hohen Steinplateaus. Dort befindet sich ein Schrein.\n\nDas Schicksal Feralas' liegt in Euren Händen. Möge die Erdenmutter über Euch wachen.", progress = nil, completion = "Ihr seid angekommen.\n\nIch schäme mich, Euch diese Aufgabe aufzubürden, &lt;Klasse&gt;, aber ich bin schon zu lange vor ihm auf der Flucht. Taerar muss aufgehalten werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25379] = {title = "Taerars Sturz", objective = "Besiegt Taerar.", description = "Smariss und Lethlas sind nicht mehr hier. Nur wir sind noch übrig. Ich kann mich nicht länger verstecken. Alles, was ich als Teil der Brut getan habe... all das Leid, das ich verursacht habe... ich muss es wieder gutmachen.\n\nIch bin noch immer schwach, <Name>. Meine wahre Gestalt kann ich noch nicht annehmen, egal, wie sehr ich es versuche. Ich werde jedoch im Kampf an Eurer Seite stehen.\n\nWenn Ihr so weit seid, werde ich Taerar rufen. Er wird der Versuchung nicht widerstehen können, mir die Verderbtheit wieder aufzulegen.", progress = nil, completion = "Es ist vollbracht.\n\nDas Land, das so sehr gelitten hat, kann nun ruhen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25381] = {title = "Feuer mit… irgendwas bekämpfen", objective = "Tötet 10 tobende Feuerstürme innerhalb des Infernos.", description = "Das Inferno, das vor uns tobt, bildet die Frontlinie zwischen uns und den Streitmächten des Feuerlords. Diese entfesselten Feuerelementare sind anders als alles, was ich je gesehen habe.\n\nKönnt Ihr uns helfen, diese Flut der Zerstörung aufzuhalten? Tötet die tobenden Feuerstürme... bevor sie den Hain von Aessina verschlingen und alle Hoffnung, diesen Berg dereinst zurückzugewinnen, zunichtemachen!", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Ihr habt uns die Chance gegeben, wieder die Oberhand zu erringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25382] = {title = "Die Rituale unterbrechen", objective = "Tötet 6 Zwielichtinfernofürsten im Inferno.", description = "Die Feuerstürme vor uns sind ungebundene Elementare in ihrer reinsten Form. Ich hätte nie gedacht, dass sie außerhalb ihrer Ebene überleben könnten. Nur äußerst geschickte Beschwörer könnten solche Wesen entfesseln.\n\n<Name>, begebt Euch in das Inferno und sucht die Zwielichtinfernofürsten. Sie beschwören bestimmt just in diesem Moment Verstärkung. Bringt sie zum Schweigen... für immer!", progress = nil, completion = "Tot? Gut!\n\nAber es scheint, als hätten wir noch so viel zu tun… so viele Feuer zu ersticken… so viel Boden zu heilen…\n\nIch hoffe, Ihr bleibt in der Nähe und helft uns dabei, den Hyjal zurückzugewinnen!", rewards = "Hackklinge des FeuersturmsFürstenbannszepterAuf Euch wartet eine dieser Belohnungen:\n\nRing des erstickten Infernos\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25383] = {title = "Ysondres Abschied", objective = "Sprecht mit Häuptling Geisterhorn in Camp Mojache.", description = "Nun bin nur noch ich übrig.\n\nSelbst wenn ich in dieser Welt bleiben sollte, so kann ich dem grünen Schwarm nicht wieder beitreten. Dieser Sieg erfüllt mich jedoch mit Hoffnung. Vielleicht kann ich zu gegebener Zeit ein einfaches Leben in Frieden unter den Sterblichen führen.\n\nIhr müsst zu Eurem Volk zurück. Berichtet ihnen, dass die Drachen des Alptraums nicht länger sind und diese Länder nicht mehr bedrohen werden.", progress = nil, completion = "Ihr seid wahrlich von der Erdenmutter gesegnet, &lt;Name&gt;, wenn Ihr mit den Wächtern der Natur kämpfen und überleben durftet.\n\nSeid Euch darüber im Klaren, dass alles Leben in diesem Camp Euch seine Sicherheit verdankt - und wahrscheinlich nicht nur in diesem Camp, sondern im gesamten Wald. Nehmt diese Geschenke als Zeichen unserer tiefsten Dankbarkeit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKette von TaerarKette von SmarissKette von Lethon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25384] = {title = "Rohmaterial", objective = "Samir möchte, dass Ihr 3 Stück zerfetzten Altmetalls von einem rasenden Orca im Tang'tharwald sammelt.\n\nIhr könnt einen Orca mit Zangeninnereien von Klickschnapperzangen anlocken.", description = "Danke, <Klasse>. Wir verdanken Euch unser Leben.\n\nAber wenn wir je wieder die Oberfläche sehen wollen, müssen wir uns hier raus kämpfen. Das bedeutet, dass ich mehr Waffen und Rüstungen herstellen muss.\n\nBevor Ihr mich gefunden habt, habe ich gesehen, wie ein Soldat von einem dieser Orcas da oben gefressen wurde.\n\nIch wette, dass Ihr in ihren Mägen bestimmt ein Haufen Altmetall finden werdet, mit dem ich arbeiten kann.\n\nWenn Ihr nicht zu ihnen hinaufschwimmen möchtet, könnte man bestimmt einen mit ein paar Eingeweiden herlocken...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "HarfenschneckenschulterplattenTreter des ZehnfußtodesPerlmuttverflochtene RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25385] = {title = "Rettet die armen Tierchen", objective = "Geht in das Inferno und rettet eine beliebige Kombination aus 10 panischen Häschen oder verängstigten Eichhörnchen.", description = "Helft uns, <Klasse>! Der Wald steht in Flammen und die armen Tierchen finden keinen Weg hinaus. Sie können doch nicht für sich selbst kämpfen mit ihren winzig kleinen Zähnchen und ihren weichen pelzigen Pfötchen! Sie sind so kuschelig und süß.\n\nSie haben so kleine feuchte Näschen!\n\nWenn Ihr sie nicht rettet... Ach, ich will nicht einmal daran DENKEN.\n\n<Sie schlägt sich die Handflächen vor die Augen.>\n\nIch denke gar nicht darüber nach!", progress = "Habt Ihr die armen Tierchen gerettet? Und ihre armen kleinen Freunde?", completion = "Huiiiiii!\n\nHat der nette Herr &lt;Klasse&gt; dich aus den Flammen gerettet, kleiner Freund? Du bist jetzt in Sicherheit!\n\nHurra!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25386] = {title = "Zur Festung der Steinbrecher", objective = "Sprecht mit Orhan Ogerklinge in der Festung der Steinbrecher.", description = "Ihr müsst jemandem von den Ereignissen hier berichten, <Name>. Südlich von hier befindet sich die Festung der Steinbrecher. Unsere Verbündeten haben dort ein paar Oger der Horde versammelt, um diejenigen zu bekämpfen, die die Wälder plündern.\n\nSprecht mit Orhan Ogerklinge. Sie führt den Stamm der Steinbrecher an und muss wissen, was hier passiert ist. Seid weiterhin vorsichtig, solange noch Verderbtheit in den Landen ist...", progress = nil, completion = "Ihr habt Euch mit Drachen herumgeschlagen, hm?\n\nDas gefällt mir. Wir können jemanden wie Euch gebrauchen. Seid Ihr bereit, um für die Horde zu kämpfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25387] = {title = "Auf nach Camp Mojache", objective = "Sprecht mit Häuptling Geisterhorn in Camp Mojache.", description = "Ihr habt hier sehr gute Arbeit geleistet, <Name>. Nun, da der Schattenhammer erniedrigt und die Gordunni blutend und verletzt zurückgelassen wurden, werden wir unser Augenmerk auf unser wahren Kampf mit der Allianz richten können.\n\nEs wird Zeit in Anspruch nehmen, unsere Streitmächte auszubauen, um mit den Nachtelfen mithalten zu können, die diesen Ort verpesten. Ich werde Euch nach Camp Mojache östlich von hier vorausschicken. Es gibt dort Probleme und wir können nicht zulassen, dass noch mehr Gebiete der Horde besetzt werden.\n\nLok'tar!", progress = nil, completion = "Ich bin über Euer Kommen sehr dankbar, &lt;Klasse&gt;. Unser Camp wird von vielen Gefahren heimgesucht, doch wir müssen uns um jene kümmern, die vor der Vernichtung des Kataklysmus auf der Flucht sind.\n\nWenn Camp Mojache wirklich ein Zufluchtsort bleiben soll, so brauchen wir Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25388] = {title = "Kiste mit Krabbenfleisch", objective = "Bringt die Kiste mit Krabbenfleisch zu Adarrah in Schmugglerschmiss.", description = "<Diese Kiste mit der Aufschrift \"Lebende Krebse\" scheint von einem kürzlich gesunkenen Frachtschiff gefallen zu sein.>\n\n<Adarrah würde sich über diesen Fund sicher sehr freuen, vor allem nach den Strapazen, die sie durchmachen musste.>", progress = "Was habt Ihr da, <Name>?", completion = "Ach, &lt;Name&gt;! Was für eine Überraschung!\n\nWenn jemals mal jemand Euren Charakter in Frage stellt, schickt ihn nur zu mir.\n\nIch erkläre jedem, der zuhört, dass Ihr mir wirklich aus der Klemme geholfen habt.", rewards = "Ihr bekommt:\n\nFeinzahniger Kamm"}
MultiLanguageQuestData['de'][25389] = {title = "Guten Hummer", objective = "Adarrah möchte, dass Ihr ihr 4 Klickschnapperschwänze bringt.", description = "Es könnte Tage dauern, bis wir an die Oberfläche aufbrechen können. Um ehrlich zu sein bin ich jetzt schon ganz schön hungrig.\n\nIch will ja nicht wählerisch erscheinen, aber es gibt nur sehr wenige Meeresfrüchte, die ich hinunterbekomme.\n\nWenn Ihr also zufällig ein paar Hummer findet, würde ich Euch für ihre Schwänze gerne mit allem belohnen, was ich habe.", progress = "Oh, bitte sagt, dass Ihr etwas zu essen für mich gefunden habt, <Klasse>.", completion = "Hui!\n\nDas sind die größten und saftigsten Hummerschwänze, die ich je gesehen habe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25390] = {title = "Ein Diamant ist unvergänglich", objective = "Adarrah möchte, dass Ihr 6 Andenken von Adarrah wiederbeschafft.", description = "Legen wir einfach mal die Karten auf den Tisch. Ich weiß, was es heißt, zu lieben, <Name>.\n\nWenn ich in all den Jahren eines gelernt habe, dann dass die materiellen Werte in der Liebe länger andauern, als die Flammen der Leidenschaft.\n\nIch habe so einiges an diesen Geschenken zusammengesammelt – Edelsteine, Ringe, Halsketten und so weiter. Und ich trage sie immer bei mir.\n\nZumindest habe ich das bisher getan...\n\nAls ich vom Schiff geworfen wurde, wurden all meine Wertsachen in den Wellen verstreut. Helft mir, sie wiederzufinden. Ich werde Euch für Eure Hilfe entlohnen.", progress = "Nun, <Volk>?\n\nKonntet Ihr meine Wertsachen finden?", completion = "Oh, Ihr habt sie gefunden! Ich war mir sicher, dass sie für immer verloren sind…\n\nNehmt dies, &lt;Name&gt;. Ich hoffe, das ist eine ausreichende Entlohnung.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHippolytas glitzernde HalsketteGalatheas SignetVersteinerte Spinnenkrabbe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nPlayer See Adarrah's Chest\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25391] = {title = "Waffen des Geistes", objective = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.", description = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.", progress = nil, completion = "Wie versprochen, habt Ihr nun die Wahl, &lt;Name&gt;. Das Muisek dieser Kreaturen wurde auf ewig in die Macht dieser Waffen eingeschlossen.\n\nIhre Energie ist nun die Eure. Verwendet sie gut.", rewards = "Macht des HippogryphenMacht des BergriesenMacht des FeendrachenMacht des TreantsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25392] = {title = "Reh-Animation", objective = "Rettet drei verletzte Kitze aus dem Inferno und begleitet sie zurück zu Mylune im Hain von Aessina.", description = "Sprecht Ihr Rehisch? Das Wichtigste ist die Nase.\n\n<Sie zeigt auf ihre Nase.>\n\nDie Rehe konnten vor dem Feuer flüchten, aber ihre kleinen Kitze… Einige davon sind immer noch im Feuer eingeschlossen und leiden fürchterliche Schmerzen!\n\nGeht zurück ins Inferno und begleitet drei verletzte Kitze zu ihren Müttern hier bei mir.\n\nBitte rettet die kleinen Kitze. Sonst muss ich Euch mit meinem Hundeblick dazu bringen!\n\n<Ihre Augen werden ganz groß und glänzen vor Tränen.>", progress = "Schnell! Ich kann den Rauch riechen!", completion = "Oh, juhu! Glückliche kleine Rehlein!\n\nJetzt können sie groß werden und ABENTEUER erleben!\n\nIhr seid klasse!", rewards = "LecksteinbrustschutzKitzrettergamaschenUmhang der heiteren BlumenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25393] = {title = "Operation: Gnomeregan", objective = "Helft König Mekkadrill beim Angriff auf Gnomeregan.", description = "Jetzt sollte jeden Augenblick der Multiphasenangriff auf Gnomeregan beginnen, der Robogenieur Thermadraht und seine Leute ihrer gerechten Strafe zuführen wird! Zu lange schon war es Thermadraht möglich, in den Tiefen unserer Heimat zu gären, verteidigt von einer korrupten und verstrahlten Armee.\n\nDer Angriff beginnt in einem Augenblick! Seid bereit, Rekrut, dieser Kampf wird nichts für zaghafte Gemüter.", progress = nil, completion = "Verflucht! Wir mussten uns zurückziehen. Aber Thermadraht hat verloren, und er weiß es... er hat sich nur mehr Zeit erkauft. Wir werden die Oberfläche halten, und wenn die Strahlung abklingt, greifen wir Gnomeregan an und erobern es mit einer doppelt so großen Streitmacht zurück!", rewards = "Ihr bekommt:\n\nTuch von Gnomeregan"}
MultiLanguageQuestData['de'][25394] = {title = "Mehr als Krankheit", objective = "Tötet 10 giftige Welpen.", description = "Ich habe auf der Straße nördlich von hier ein paar Drachenjunge gefunden, die an einem ähnlichen Gebrechen zu leiden scheinen. Gründrachen sind die geheiligten Wächter der Natur. Allein die Tatsache, dass sich die Krankheit auf die Drachen ausbreiten konnte, ist sehr alarmierend.\n\nWir müssen verhindern, dass sie sich weiter verbreitet, egal wie. Tötet die vergifteten Welpen, <Name>, und kehrt zu mir zurück.", progress = nil, completion = "Diese Ereignisse sorgen mich sehr. Es ist nicht das erste Mal, dass so etwas passiert...", rewards = "WindseglerstabSmaragdener SchleierGrünwelpenschulterschutzTelarons KettenpanzerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25395] = {title = "Das gestohlene Fass", objective = "Holt das Gebirgsjägerbier aus Dun Algaz heraus.", description = "Ihr müsst uns helfen, <mein Freund/meine Liebe>. Man hat uns mit der Aufgabe betraut, eine wertvolle Ladung zu unseren Zwergenlandsleuten zu begleiten... ein Fass des feinsten Bieres, das man hier bekommt!\n\nLeider ist das Spatzenhirn da drüben bei der Arbeit eingeschlafen! Diese verfluchten Orcs haben das Fass gestohlen und nach Dun Algaz verschleppt, wo sie sich verstecken.\n\nDas geht so nicht! Nun, ich werde hierbleiben und versuchen, diesem Idioten klarzumachen, dass das sein Fehler war. Ich möchte, dass Ihr dort hineingeht und das Fass zurückholt. Für Khaz Modan!", progress = "Habt Ihr es? Ist das arme Ding unversehrt?", completion = "Den Schöpfern sei Dank! Es ist makellos. Offenbar konnten die Orcs mit dem Schloss am Zapfhahn nichts anfangen... und in das meisterlich gefertigte Stück Handwerk der Böttcher in Eisenschmiede konnten sie mit ihren primitiven Waffen keine Löcher schlagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25396] = {title = "Tränen der Steine", objective = "Sammelt 7 Steintränen.", description = "Ihr habt gehört, wie der Drache Ysondre uns erzählt hat, dass die Tränen des Landes das Portal schließen können, aus dem die Verderbnis strömt.\n\nIhre Worte entsprechen der Wahrheit; in dem Tal westlich von hier habe ich gesehen, dass die Bergriesen leiden. Sie waren wild vor Frustration, und als sie weinten, wurden ihre Tränen, die auf die Steine fielen, zu Kristallen.\n\nDie Riesen weinen zwar nicht mehr, aber diese Steintränen sind wohl das, worauf Ysondre sich bezogen hat. Wir brauchen diese Tränen.", progress = "Diese Tränen sind auf dem Gestein, aus dem die Riesen selbst entstanden sind. Am Fuße der Berge in der Nähe der großen Monolithen sollten lose Tränen sein.", completion = "Die Bergriesen sind für unser Volk wichtige Verbündete. Wir müssen die Verderbnis aufhalten, bevor noch mehr der Kreaturen des Waldes von ihr befallen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25397] = {title = "Das verderbte Land", objective = "Tötet 6 verderbte Klippenriesen.", description = "Die Klippenriesen von Feralas sind Ausläufer der Erde selbst, <Name>. Wenn es der Natur gut geht, so sind sie wohlwollende Beschützer und friedliche Wächter.\n\nDoch wenn der Wald leidet, so leiden auch sie.\n\nWenn sie von dieser Krankheit heimgesucht und verderbt werden, so werden sie sich gewaltvoll gegen die Bäume, die Tiere und selbst das Gestein, aus dem sie selbst entstanden sind, richten.\n\nSeid vorsichtig bei Eurer Aufgabe. Wenn Ihr verderbte Riesen findet, zerstört sie, zum Schutz aller, die noch nicht verderbt wurden.", progress = nil, completion = "Die Geister der Beschützer werden wieder zurückkehren, &lt;Name&gt;. Ihr habt sie befreit und nun können sie im Kreislauf der Natur ihre Wege gehen.\n\nJetzt liegt es an uns, sicherzustellen, dass der Kreislauf frei von Verderbnis und grundlosem Schmerz ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25398] = {title = "Den Traum versiegeln", objective = "Benutzt Ysondres Träne, um das Portal im Traumgeäst zu versiegeln.", description = "Es ist soweit. Nehmt dies, <Name>; ein Fanal der Essenz der Natur, das von Ysondres Willen gesegnet wurde.\n\nNördlich von hier, auf der anderen Seite des Baches, befindet sich das Traumgeäst. Dort steht der Große Baum, der größte Baum Feralas', ein Schössling des Weltenbaums selbst. In seinem Stamm ist ein Portal, das direkt zum Smaragdgrünen Traum führt. Dieses Portal müsst Ihr schließen.\n\nDas Portal wird bewacht sein; Ihr dürft nicht verzagen.", progress = nil, completion = "Dank Eurem Mut haben wir eines unserer Probleme lösen können! Der Smaragdgrüne Alptraum wurde von diesem Land ausgeschlossen.\n\nDas Schicksal des Drachen Taerar besorgt mich... aber es gibt noch viel Arbeit zu verrichten. Ich kann mich mit Taerar im Moment nicht befassen.", rewards = "TraumgeästrobenGürtel der NaturessenzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25399] = {title = "Streitmacht der Hasskämme", objective = "Tötet 10 Naga der Hasskämme.", description = "Die Hasskämme kämpfen erbittert! Ihren Anführer auszumerzen hat oberste Priorität, aber wir müssen so viele wie möglich töten.\n\nGeht schon einmal vor, ich werde Euch auf dem Schlachtfeld treffen. Zeigt ihnen keine Gnade!", progress = nil, completion = "Mir wurde von Eurem Heldenmut in den mir zugetragenen Berichten erzählt, &lt;Name&gt;. Ihr habt mein Lob.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25400] = {title = "Bedrohung durch die Gordunni", objective = "Tötet 16 Oger der Gordunni in der Oberen Wildnis.", description = "Estulan, der Hochgeborene oben im Turm, lebt sehr zurückgezogen. Ich konnte mich kaum mit ihm unterhalten. Allerdings hat er mir erzählt, dass die Ruinen in der Oberen Wildnis südlich von hier voll von Ogern der Gordunni sind.\n\nDie Oger sind nicht nur eine Gefahr, sie zerstören auch den Wald und die Wildnis, in der sie sich bewegen. Estulan hat mich auch davor gewarnt, was passiert, wenn sie Artefakte mit der Macht der Hochgeborenen in den Ruinen finden...\n\nBegebt Euch nach Süden, <Name>, und tötet alle Gordunni, die Ihr finden könnt!", progress = nil, completion = "Es scheint, als wären es mehr Oger, als wir gedacht haben! Ich danke Euch für Euren Mut und Eure Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25401] = {title = "Die Gordunnikugel", objective = "Erhaltet eine Gordunnikugel von einem Hexenmeister der Gordunni.", description = "Wir müssen den Ogern nicht nur ein Ende bereiten...\n\nEstulan hat noch etwas anderes gesagt. Er meinte, die Hexenmeister der Oger hätten eine Kugel im Besitz, oder einen anderen, mächtigen Gegenstand.\n\nEr war sehr wortkarg, doch er schien beunruhigt... er sagte, es sei \"unmöglich, dass sie Hochgeborene sind\", und ich glaube, er will nur wissen, wo sie die Kugeln herhaben. Bringt mir eine dieser Kugeln.", progress = "Habt Ihr die Kugel?", completion = "Das ist die Kugel? Mal sehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25402] = {title = "Estulans Untersuchung", objective = "Bringt die Gordunnikugel zu Estulan.", description = "Er hat Recht. Ich habe nicht viel Zeit mit den Nachtelfen verbracht, aber ich kann mit Sicherheit sagen, dass diese Markierungen nicht nach Verzierungen der Kaldorei aussehen...\n\nEstulan muss sich das anschauen. Bringt die Kugel zu ihm in seinem Turm. Er mag unwirsch erscheinen, aber stört Euch nicht daran. Sobald er die Kugel sieht, wird er merken, dass es sich um eine wichtige Angelegenheit handelt.", progress = "Was habt Ihr da?", completion = "Ahh, die Kugel, die ich erwähnt hatte. Ein guter Grund, mich zu stören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25403] = {title = "Ogerentführung", objective = "Benutzt die modifizierte Seelenkugel, um einen Ogermagier der Gordok gefangenzunehmen.", description = "Nein, es ist kein einfaches Schmuckstück der Oger, und auch kein altes Relikt meines Volkes. Der Aufbau ist mir gänzlich unbekannt... und genau diese Tatsache besorgt mich sehr.\n\nDas Wolfmädchen wird Euch bald nach Düsterbruch schicken, um die Elitekämpfer der Gordok zu bekämpfen. Sie sind die Anführer der Gordunni und werden wissen, wer sie mit diesen Kugeln versorgt.\n\nNehmt die Kugel wieder an Euch - ich habe sie ein bisschen verzaubert. Haltet sie vor einem geschwächten Oger der Gordok in die Höhe. Ihr werdet ihn gefangennehmen können. Kehrt dann zu mir zurück.", progress = nil, completion = "Ah, Ihr habt ihn. Jetzt muss ich nur noch die Schmerzen ertragen, mir seine Worte anzuhören.", rewards = "Armschienen des SeelendiebsModifizierter ZauberschildSchultern des OgerfängersBedeckung des EntführersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25404] = {title = "Wenn Ihr nicht gegen uns seid…", objective = "Sprecht mit Tyrus Schwarzhorn und überzeugt ihn, im Kampf gegen den Schattenhammer zu helfen.", description = "Südlich von hier findet Ihr einen alleinstehenden Turm, der als \"Schwarzhorns Buße\" bekannt ist. An ihn ist ein Dämon gebunden, Tyrus Schwarzhorn.\n\nIhr mögt mich für verrückt halten, dass ich einen ehemaligen Feind um Hilfe bitte, aber Schwarzhorn war einst sterblich. Ich kann mir kaum vorstellen, dass er dem Schattenhammer den Sieg gönnt.\n\nSprecht mit Schwarzhorn und versucht, ihn zu überreden, uns bei unserem Kampf zu helfen. Vielleicht kann er sich ja so reinwaschen.\n\nAber lasst ihn bloß nicht frei!", progress = "Ihr wurdet hierher geschickt, um zu reden, <Volk>. Also. Redet.", completion = "Nun denn, &lt;Volk&gt;. Ich werde Euch Sterblichen helfen, sogar mit den mir auferlegten Fesseln.\n\nAber verursacht mir keine Übelkeit mit der Verheißung meiner Erlösung. Ich tue das aus meinen ganz persönlichen Beweggründen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25405] = {title = "Rast für die Erschöpften", objective = "Sprecht mit Kapitän Taylor.", description = "Ihr habt Eure Aufgabe gut gemacht, <Volk>, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.\n\nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.\n\nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.\n\nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.\n\nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.", progress = nil, completion = "Ich verstehe, &lt;Volk&gt;.\n\nIch weiß, wie dringend es ist, aber diese Männer sind nicht in der Lage zu kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25406] = {title = "Die Wachen der Gordok", objective = "Tötet 6 Vollstrecker der Gordok und 6 Ogermagier der Gordok.", description = "Nun, da wir uns den Ogern in der Nähe angenommen haben, sollten wir mit unserer Offensive in ihre Gebiete eindringen und angreifen.\n\nDie Oger der Gordok führen den Stamm der Gordunni an und leiten ihre Operationen von den Ruinen aus, die Düsterbruch genannt werden. Sie sind stärker als gewöhnliche Gordunni, aber ich habe keinen Zweifel daran, dass Ihr mit ihnen umzugehen vermögt, <Name>. Sie werden nicht wissen, was auf sie zukommt.", progress = nil, completion = "Wunderbar! Alles läuft genau nach Plan. Lady Shandris wird zufrieden sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25407] = {title = "Naturgewalten: Irrwische", objective = "Benutzt Tessinas Irrwischruf, um 3 Irrwische bei der Mondfederfeste zu versammeln.", description = "Die Schildwachen machen einen Großteil unserer Streitmächte aus, aber eine gut formierte Nachtelfenarmee braucht mehr als nur Nachtelfen. Die Kreaturen des Waldes, der Heimat unserer Vorfahren, haben uns seit Jahrhunderten beschützt. Wir müssen sie nur zusammenrufen.\n\nDieser Ruf wird Euch dabei helfen - unsere Verbündeten kennen den Klang und Ihr werdet sie damit versammeln können.\n\nBevor Ihr Euch jedoch aufmacht, um die Kreaturen zu versammeln, möchte ich, dass Ihr ein bisschen mit unseren Irrwischen übt. Ihr findet sie außerhalb der Festung in den Bäumen.", progress = nil, completion = "Irrwische haben seit jeher in Harmonie mit den Nachtelfen gelebt, und wir vertrauen bei vielen Dingen auf ihre Hilfe. Die Irrwische, die Ihr eben versammelt habt, werden uns nun mit ein paar Bauarbeiten und Reparaturen helfen.\n\nSeid Ihr bereit für mehr Arbeit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25408] = {title = "Die Saat ihres Untergangs", objective = "Sammelt 8 Gallbeeren.", description = "Wir werden die Schattenhammerkultisten dezimieren, indem wir sie verderben und unterwandern.\n\nDa Ihr nicht vorzuhaben scheint, mich aus meinen Banden zu entlassen, fordere ich, dass Ihr mir ein paar Reagenzien sammelt. Meine eigene dämonische Essenz hat die Pflanzen um meinen Schrein herum verderbt. Ihr müsst vom klagenden Gras um diesen Turm herum Gallbeeren ernten.\n\nMeine kleinen Haustierchen werden im Gegenzug versuchen, EUCH zu ernten. Versucht zu verhindern, dass sie sich gegenseitig aufstacheln.", progress = "Macht Euch die Pflanzenwelt hier das Leben schwer?\n\n<Schwarzhorn grinst beunruhigend.>", completion = "Sehr gut. Bitte stampft die Beeren zu dickflüssigem Brei. Ein wundervolles Aroma, oder?\n\nNa, na! Nicht würgen! Das ist unter Eurer Würde.", rewards = "TodessaatzermalmerSaatfilterdeflektorAuf Euch wartet eine dieser Belohnungen:\n\nGallbeerenriechsalz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25409] = {title = "Naturgewalten: Hippogryphen", objective = "Benutzt Tessinas Hippogryphenruf, um 10 Fransenfederhippogryphen zu versammeln.", description = "Hippogryphen sind majestätische Kreaturen. Es wird ihnen nachgesagt, dass sie von Cenarius selbst als Geschenk für die Nachtelfen erschaffen wurden. Sie sind anderen Völkern gegenüber misstrauisch, aber sie sind intelligent genug, um die Freunde ihrer Freunde als solche zu erkennen.\n\nIch brauche mehr Hippogryphen, um mit den Übungen für unsere neuen Bogenschützen zu beginnen, die das Reiten der Hippogryphen erlernen müssen. Nehmt die Pfeife und ruft damit die Fransenfederhippogryphen am Hain südlich vom Turm von Estulan zusammen.", progress = nil, completion = "Ein gut ausgebildeter Trupp Hippogryphenreiter kann sich fast jeder feindlichen Streitmacht annehmen. Mondfederfeste wird mit diesen noblen Kreaturen zur Seite weitaus sicherer sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25410] = {title = "Naturgewalten: Treants", objective = "Benutzt Tessinas Treantruf, um 6 wandernde Waldgänger zu versammeln.", description = "Es gibt Leute, die glauben, dass die Treants zu nicht sehr viel mehr nützlich sind, als in Kriegen Getränke zu holen. Diese Leute haben nie gesehen, wie gesamte Verteidigungslinien von etwas zerstört wurden, was sie für Schutz hielten.\n\nUnd habt Ihr je gesehen, wie ein Peon versucht hat, einen von ihnen zu fällen und überrascht wurde? Ich habe Tränen gelacht...\n\nWie dem auch sei, die Treants sind unglaublich wichtige Verbündete. Ihr könnt einige von ihnen außerhalb des Turmes von Estulan umherwandern sehen. Außerdem gibt es auch noch welche im östlichen Wald, südöstlich von Düsterbruch. Seid auf der Hut vor der Horde!", progress = nil, completion = "Man mag es ihnen nicht ansehen, aber manche Treants werden zu alten Beschützern. Wir könnten ein paar mehr gut gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25411] = {title = "Ein neuer Meister", objective = "Benutzt das abgefüllte Gallbeerengebräu an der Leiche eines Zwielichtinfernofürsten und sprecht dann mit ihm.", description = "Der Trank, den Ihr gebraut habt, ist ekelhaft genug, um die Toten zu erwecken. Und das soll er ja schließlich auch.\n\nTötet einen Zwielichtinfernofürsten und kippt ihm das Gebräu in den Rachen. Er wird wieder auferstehen, wenn auch nur kurz. In dieser Zeit steht er vollkommen unter Eurer Kontrolle.\n\nSprecht mit ihm und erfahrt den wahren Namen des Feuerelementars, den er in diese Welt geschickt hat, um Euren geliebten Wald niederzubrennen.", progress = "<Der zitternde Leichnam wird kurz durch bösartige Magie zum Leben erweckt.>\n\n<Er nimmt keine Notiz von Euch.>", completion = "&lt;Die gebeutelte Kreatur vor Euch spricht mit zitternder Stimme. Der Körper ist geschunden, wurde jedoch durch Schwarzhorns übles Gebräu kurz wieder zum Leben erweckt.&gt;\n\nJa, Meister?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25412] = {title = "Der Unaussprechliche", objective = "Setzt den wahren Namen zusammen, indem Ihr die drei Feuersteine untersucht.", description = "Wir haben den Zorn und die Flammen des Einen heraufbeschworen, meines ehemaligen Meisters.\n\nDas Inferno ist sein Werk.\n\nSein wahrer Name darf nie ausgesprochen werden, denn er ist die Quelle seiner Macht.\n\nJeder von uns erfuhr nur einen kleinen Teil davon, der auf einem Feuerstein eingeritzt wurde.\n\nDer wahre Name des Einen ist hier, im Inferno. Sucht die drei Steine...", progress = nil, completion = "Ja, ja! Zeigt mir die Runen, die Ihr gefunden habt.\n\n\"Vol'talo Thol'embaar.\" Das ist der Name Eures echten Feinds.\n\nWahrscheinlich handelt es sich dabei um einen von Ragnaros' Generälen, die hierher geschickt wurden, um den Weg für seinen ruhmreichen Einzug zu ebnen.\n\nIch werde Euch zeigen, wie Ihr ihn vernichten könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25413] = {title = "Planänderung", objective = "Beschafft Euch die rostige Harpune und 3 Seile.", description = "In Ordnung, <Bursche/Mädel>. Kleine Planänderung…\n\nIch glaube, ich habe einen Weg gefunden, um diesem Monster den Garaus zu machen. Und Ihr werdet mir dabei helfen.\n\nSo wie ich das sehe, steht Ihr in meiner Schuld, bis meine Arbeit hier vorbei ist. Und ohne das Artefakt gehe ich bestimmt nicht.\n\nZuerst müsst Ihr für mich diese alten Schiffswracks nach einem geeigneten Seil und einer funktionierenden Harpune durchsuchen.\n\nDann.. nun, den Rest erzähle ich Euch später.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25419] = {title = "Lady La-Las Medaillon", objective = "Sammelt 5 Medaillonfragmente von den Sammlern der Gilblin und setzt sie zu Lady La-Las Medaillon zusammen.", description = "<Diese schwere Kette besteht aus Dutzenden von massiven Goldgliedern.>\n\n<Vom mittleren Glied hängt ein opalschimmerndes Fragment herunter, das wohl einst ein großes muschelförmiges Medaillon gewesen sein muss.>\n\n<Ihr fragt Euch, ob die anderen Bruchstücke vielleicht in der Nähe herumliegen und ob man das Medaillon wieder zu seinem ursprünglichen Zustand zusammensetzen könnte.>Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "JungfernfischschulterschutzTraumwedelrockAuf Euch wartet eine dieser Belohnungen:\n\nPrismatisches Strandschneckenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25420] = {title = "Uralte Hindernisse", objective = "Zerstört 6 Sandsteingolems.", description = "Ich habe dieses Tor jahrelang untersucht und versucht, einen Eingang zu finden, der die uralte Architektur nicht beeinträchtigt. Und dann kommen ein paar enorme Erdbeben und schlagen das ganze Ding entzwei! Was geschehen ist, ist geschehen und nun liegt der Eingang nach Uldum frei.\n\nIch hatte aber nicht damit gerechnet, dass etwas aus den Ruinen kommt, bevor wir hineingehen. Eine Masse von Golems rennen nun im Tal umher, und drinnen sind noch mehr. Jemand muss sie aus dem Weg schaffen, damit wir ins Innere können.", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;. Wir sind den Geheimnissen Uldums schon einen Schritt näher.", rewards = "TorwächtergürtelSchiftung des StilllegersSandsteinschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25421] = {title = "Die große Tafel", objective = "Bringt die große Tafel zu Gunstan.", description = "Auf dem Boden der Truhe findet Ihr eine große Tafel. Das Material scheint Stein zu ähneln, ist aber ganz sanft und fein anzusehen und mit seltsamen Schriften versehen.\n\nEin Teil der Schrift ist der gleiche wie an den Mauern, doch es sind auch andere Schriften darauf zu finden. Gunstan wird sich sicherlich dafür interessieren.", progress = "Ihr seid zurück! Was habt Ihr gefunden?", completion = "Das ist wirklich unglaublich. Die Hieroglyphen sind zweifellos von den Titanen, aber die Markierungen darunter...\n\nIch würde hoffen, dass es sich dabei um den gleichen Text in meheren uralten Sprachen handelt. Wir könnten es benutzen, um die Hieroglyphen zu entziffern! Wenn die Vorkammer wirklich voll mit diesen Schriften ist, so werden wir noch weitaus mehr lernen können.\n\nIch möchte Euch gerne eine große Belohnung geben, &lt;Name&gt;. Das ist der Fund des Jahrhunderts!", rewards = "Hieroglyphischer HelmÜbersetzungsstiefelGürtel der rosigen SchrifttafelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25422] = {title = "Das Graunebelvermächtnis", objective = "Sammelt 6 Haufen leuchtende Erde.", description = "Ich bin an diesen Ort gekettet... es kostet viel Energie, nur mit Euch zu sprechen. Ich halte es kaum aus, in dieser Form zu bleiben.\n\nIch kann Euch helfen, aber bitte helft mir zuerst, in dieser Welt fußzufassen. Sobald ich es geschafft habe, meine Konzentration auf diese Ebene zu lenken, sollte ich Euch helfen können...\n\nBitte, bringt mir etwas von der Erde außerhalb der Gruft. Sie ist voller uralter arkaner Ablagerungen und liegt seit Jahrhunderten vergessen dort.", progress = "Habt Ihr die Erde? Es fällt mir wirklich schwer, mich zusammenzuhalten... Beeilt Euch...", completion = "Vielen Dank! Ich danke Euch...\n\nEs geht mir schon viel besser. Noch ein bisschen mehr...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25423] = {title = "Uraltes Leiden", objective = "Sammelt 6 Seelenessenzen.", description = "Seid vorsichtig, wenn Ihr Eure Reise fortsetzt. Andere Geister sind an diesen Ort gebunden, bösartige Geister voller Hass. Sie haben zu viel gelitten.\n\nNichts, was sie einst waren, ist noch übrig, nur ihr Leid und der Wille, zu leben. Wir brauchen diesen Willen, um den Oberanführer zu beschwören, der mich hier festhält. Bitte, sammelt die Seelenessenzen der Geister und bringt sie mir.", progress = "Habt Ihr sie erhalten können?", completion = "Ihr könnt ihre Pein spüren, nicht wahr?\n\nMeine armen Freunde. Wenigstens kann ich sie benutzen, um hier etwas zu verändern...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25424] = {title = "Rückkehr zu Alysra", objective = "Kehrt zu Alysra bei den Ruinen von Lar'donir auf dem Hyjal zurück.", description = "Ich danke Euch, dass Ihr mich befreit habt, <Name>. Ich werde unseren Verbündeten von unseren Erkenntnissen berichten.\n\nIch schlage vor, dass Ihr zu dem Smaragddrachen zurückkehrt, der Euch geschickt hat.\n\nDer Schattenhammer versucht mit diesem Angriff nicht nur, neue Gebiete zu erobern. Sie sind auch hinter einem Gefangenen her.\n\nFandral Hirschhaupt wird in den Grabhügeln gefangen gehalten. Der Angriff dient auch als Ablenkungsmanöver, um ihn zu befreien. Welchen Zweck das haben soll, weiß ich nicht. Vielleicht kann unser Drachenverbündeter etwas Licht ins Dunkel bringen.", progress = nil, completion = "Diese Entwicklung ist sehr beunruhigend, &lt;Name&gt;. Wir müssen schnell handeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25426] = {title = "Krieg gegen die Waldpfoten", objective = "Sammelt 10 Mähnen von Waldpfotengnollen.", description = "Der erste direkte Befehl von Shandris lautet, die Waldpfotengnolle hier unter Kontrolle zu bringen. Sie haben sich zu schnell zu weit verbreitet und wachsen zu einer Bedrohung für den Wald und für unsere Kriegsanstrengungen heran.\n\nSie wissen, dass wir hier sind. Nachdem wir dieses Lager eingenommen haben, haben wir verdeckte Angriffe gegen sie durchgeführt. Es ist an der Zeit einen Großangriff zu starten; bringt mir zehn von ihren Mähnen, dann sind wir bereit für die nächste Phase.", progress = "Die Mähnen sind keinesfalls bloß als Trophäen gedacht. Wenn es schon Blutvergießen geben muss, dann sollten wir daraus auch einen Nutzen ziehen.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Wusste ich es doch, dass diese Gnolle kein Problem für Euch sein würden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25427] = {title = "Schlag gegen die Alphas", objective = "Tötet 5 Alphas der Waldpfoten.", description = "Man sollte keine Gefahr jemals unterschätzen. Die Gnolle sehen wie einfache Rohlinge aus, aber sie haben die Gerissenheit von Tieren.\n\nDie Gnolle sind ein Rudel und jedes Rudel hat Alphamännchen: die stärksten, größten und rücksichtslosesten Mitglieder des Rudels, die sich ihre Dominanz durch nichts als den Einsatz ihrer Klauen sichern. Sie sind auch diejenigen, die die Befehle erteilen, und genau deswegen diejenigen, die wir als Nächstes töten werden.\n\nEs gibt mindestens fünf von ihnen in den verschiedenen Lagern verstreut. Ihr erkennt sie an ihrem unfreundlichen Verhalten den anderen gegenüber. Findet sie und verhaltet Euch ihnen gegenüber noch unfreundlicher.", progress = nil, completion = "Perfekt. Die Gnolle, die noch übrig sind, sind nichts weiter als Beute, die in den Wäldern verloren gegangen ist.\n\nHehe... hier, Soldat, nehmt diese Belohnung, bevor ich es vergesse. Es gibt noch andere Gefahren, um die wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25428] = {title = "Das schwarze Herz der Flamme", objective = "Benutzt den verkohlten Ast im Inferno, um Thol'embaar herbeizurufen. Tötet ihn und nehmt Euch Thol'embaars schwarzes Herz.", description = "Jetzt werdet Ihr unser neu gewonnenes Wissen nutzen, um Thol'embaar auf die Ebene der Sterblichen zu zerren, wie ein schreiendes Kind aus dem Leib der Mutter. Und dann werdet Ihr ihn vernichten.\n\nDas Ritual ist einfach: Nehmt diesen verkohlten Ast, stoßt ihn dreimal auf den Boden und sprecht laut seinen Namen.\n\nIhr müsst ihn mitten aus dem Herz des Infernos rufen. Vernichtet ihn und bringt mir sein schwarzes Herz.", progress = "Sagt mir! Habt Ihr schon gegen Thol'embaar gekämpft?\n\nIch lebe mein Leben stellvertretend durch Euch, <Volk>. Also enttäuscht mich nicht!", completion = "Da ist es! Welch Trophäe! Geboren in den Feuern einer anderen Ebene…\n\nLos, &lt;Volk&gt;. Zerquetscht es. Zerquetscht sein verkohltes Herz in Euren Händen und lasst den Wind die Asche forttragen… Ja, ja.", rewards = "GlutmalmerhandschutzKapuze des KohlenbeißersAuf Euch wartet eine dieser Belohnungen:\n\nSignet der erwachenden Flamme\n\nDer folgende Zauber wird auf euch gewirkt:\n\nStart Quest: Good News... Bad News\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25429] = {title = "Zukk'ash-Plage", objective = "Sammelt 20 Zukk'ashknochenpanzer.", description = "Jetzt, da die Gnolle aus dem Weg geräumt sind, können wir uns unseren anderen Feinden widmen. Unsere Späher haben in der Nähe eine Art Schwarmbau entdeckt, der sich tief unter dem Boden ausbreitet.\n\nDie Insekten in diesem Bau sind sehr groß und aggressiv. Wahrscheinlich sind sie eine noch größere Bedrohung als die Gnolle. Ich möchte, dass Ihr Euch mit äußerster Vorsicht dem Schwarmbau nähert. Vernichtet eine ansehnliche Menge der Käfer und bringt mir ihre Knochenpanzer, damit ich sie weiter untersuchen kann.", progress = "Was macht die Jagd, <Name>? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Also handelt es sich dabei doch um Silithiden… Ich war mir nicht sicher, da ich nie persönlich einen zu Gesicht bekommen habe. Wir hatten in Gilneas so unsere Probleme, aber zumindest gibt es bei uns nicht solche riesigen Monstrositäten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25430] = {title = "Smaragdgrüne Verbündete", objective = "Sprecht mit Alysra bei den Ruinen von Lar'donir am Berg Hyjal.", description = "Die Druiden des Hyjal sind nicht die Einzigen, die geschworen haben, dieses Land zu beschützen. Auch die Smaragddrachen haben sich uns erneut angeschlossen, um uns bei unserer Aufgabe zu unterstützen.\n\nSprecht mit Alysra bei den Ruinen von Lar'donir im Norden und findet heraus, wie Ihr helfen könnt.", progress = nil, completion = "Meine Pflicht hier besteht darin, die Bewegung des Feindes von oben zu beobachten und unseren Armeen bei Bedarf Anweisungen zu geben.\n\nEure Hilfe kommt mir sehr gelegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25431] = {title = "Zornstachel", objective = "Tötet Zornstachel in der Gewundenen Tiefe.", description = "Die meisten Insekten, die wir aus dem Schwarm bisher gesehen haben, waren groß genug, aber meine Späher haben von einem enorm großen Insekt berichtet. Anscheinend ist es eine riesige Wespe, die in erster Linie die Arbeiter an die Erde leitet.\n\nIch kenne mich damit nicht wirklich aus, aber wenn sie sich mit dieser Erdgrube nicht mehr zufrieden geben, werden wir ihnen ein Ende bereiten müssen. Tötet diese Riesenwespe und kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Ihr stellt Euch als äußerst nützlich bei der Sicherung dieses Gebiets für die Allianz heraus.", rewards = "Ihr bekommt:\n\nSekretbedeckter Panzer"}
MultiLanguageQuestData['de'][25432] = {title = "Nicht aller Oger Abend", objective = "Tötet 5 Hügelwächter der Gordunni.", description = "Wir haben den Gordunni in Düsterbruch viel Schaden zugefügt, aber wir sind noch nicht ganz fertig mit unserem Vorhaben. Meine Späher berichten von einer Gruppe von Gordunni, die sich in den Hügeln nördlich von hier aus irgendeinem Grund versammelt haben.\n\nVielleicht sind sie an dem Lager der Horde in der Nähe interessiert, aber ich muss es mit Sicherheit wissen. Erkundet die Gegend, tötet alle Oger, die Euch über den Weg laufen, und meldet Euch wieder bei mir.", progress = nil, completion = "Gut, Euch wiederzusehen. Wir haben viel über die Situation der Oger in Erfahrung gebracht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25433] = {title = "Sasquatch-Sichtung", objective = "Tötet Großfaust.", description = "Ihr habt es vielleicht selbst schon gesehen - unsere Späher berichten von einer enormen Bestie, die von den Ogern gefangen gehalten wird. Es wird gesagt, sie sehe wie ein Sasquatch aus, und wenn das der Fall ist, dann ist es wohl der größte Sasquatch, der je in Feralas gesichtet wurde.\n\nDie Oger haben wohl vor, ihn zu zähmen. Die Vorstellung ist zwar schon fast amüsant, aber ich werde nicht rumsitzen und zuschauen, wie sie dem Ding beibringen, sich auf Kommando auf die Seite zu rollen. Kehrt zu den Hügeln zurück und tötet den Sasquatch.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;, auf Euch kann man sich verlassen. Eine weitere Gefahr wurde dank Euch aus Feralas entfernt.", rewards = "Kniehosen aus YetifellGroße StiefelSchattengeästumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25434] = {title = "Die Zähmer zähmen", objective = "Tötet 6 Zähmer der Gordunni.", description = "Die Sasquatch mögen die größere Bedrohung sein, aber zuerst müssen wir uns um die Oger kümmern. Die Gordunni sind uns schon lange ein Dorn im Auge und Lady Shandris möchte, dass wir sie ausmerzen. Hoffen wir, dass es wirklich die letzten sind.\n\nTötet die Zähmer der Gordunni, die die Biester in Ketten halten, und stellt sicher, dass sie den Preis für ihre Taten zahlen werden.", progress = nil, completion = "Gute Arbeit - die sind wir los! Ich hoffe, wir werden hier nie wieder irgendwelche Oger sehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25435] = {title = "Schwimmt Euch in den Sattel", objective = "Sammelt 3 Haisehnen von gefräßigen Dreschern und 2 geschärfte Krebsscheren von Säbelklauenhuschern.\n\nIhr könnt die gefräßigen Drescher auch mit Krebsinnereien herbeirufen.", description = "'N Tag, <Kumpel/Mädel>.\n\nIch bin Rendel.\n\nSieht aus, als wär'n die gute alte Moanah und ich gerade rechtzeitig hier eingetroffen, was?\n\nErunak hat nicht gescherzt, als er sagte, es ginge um Leben oder Tod!\n\nWährend er sich bemüht, ein kuscheliges Versteck für uns zu finden, werd' ich mal versuchen, Euch ein Reittier zu sichern.\n\nIch bin jetzt vielleicht nicht so auf dem Laufenden, was das Leben im Meer angeht, aber die Naga scheinen hier unten bestens zurecht zu kommen.\n\nWarum sucht Ihr nicht ein paar Kleinigkeiten für das Zaumzeug zusammen? Ich arbeite solange schon einmal an der Verzauberung.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25436] = {title = "Boshafte Schwestern", objective = "Tötet 8 verderbte Dryaden.", description = "Es ist etwas sehr beunruhigendes passiert. Auf einer ihrer Patrouillen wurden ein paar meiner Späher von Dryaden angegriffen.\n\nDie Dryaden sind enge Verbündete der Nachtelfen und Wächter des Waldes. Zuerst dachte ich, der Anblick der Worgen hätte ihnen Angst eingejagt, aber auch die Schildwachen, die ich danach losgeschickt habe, wurden angegriffen.\n\nIch weiß nicht, was hier vor sich geht, aber ich weiß, dass es mir nicht gefällt. Ich möchte, dass Ihr die Sache untersucht. Wenn auch die Dryaden der Verderbnis zum Opfer gefallen sind, so müsst Ihr sie töten.", progress = nil, completion = "Ich möchte Euch nicht ängstigen, aber wir befinden uns in einer furchtbaren Lage. Wenn das Portal im Traumgeäst verschlossen wurde und die Verderbnis sich trotzdem weiter ausbreitet...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25437] = {title = "Ysondres Aufforderung", objective = "Sprecht mit Ysondre auf dem Smaragdgipfel in der Unteren Wildnis.", description = "Ein Drache des smaragdgrünen Traums... worauf habt Ihr Euch nur eingelassen, <Name>?\n\nIch würde sie an Eurer Stelle nicht warten lassen. Der Ort, von dem sie sprach, ist der Smaragdgipfel. Ein Pfad, weitab der Hauptstraße, führt durch die Untere Wildnis zu den hohen Steinplateaus. Dort befindet sich ein Schrein.\n\nIch wünsche Euch viel Glück, <Name>. Ich hoffe, Ihr kommt sicher zurück.", progress = nil, completion = "Ihr seid angekommen.\n\nIch schäme mich, Euch diese Aufgabe aufzubürden, &lt;Klasse&gt;, aber ich bin schon zu lange vor ihm auf der Flucht. Taerar muss aufgehalten werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25438] = {title = "Ysondres Abschied", objective = "Sprecht mit Adella im Schattengeäst.", description = "Nun bin nur noch ich übrig.\n\nSelbst wenn ich in dieser Welt bleiben sollte, so kann ich dem grünen Schwarm nicht wieder beitreten. Dieser Sieg erfüllt mich jedoch mit Hoffnung. Vielleicht kann ich zu gegebener Zeit ein einfaches Leben in Frieden unter den Sterblichen führen.\n\nIhr müsst zu Eurem Volk zurück. Berichtet ihnen, dass die Drachen des Alptraums nicht länger sind und diese Länder nicht mehr bedrohen werden.", progress = nil, completion = "In einen Kampf der Drachen verwickelt zu werden... ich weiß nicht, ob Ihr gesegnet oder verflucht seid.\n\nLady Shandris hat von all Euren Taten gehört und hat Euch dies persönlich als Belohnung überbringen lassen. Ich bin froh, dass Ihr heil hier angekommen seid, um es in Empfang zu nehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKette von TaerarKette von SmarissKette von Lethon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25439] = {title = "Das rachsüchtige Herz", objective = "Tötet 10 Verheerer des Zin'jatar.", description = "Das sind die Naga, die unsere Leute entführt haben. Ich brauche nur einen, um ihn zu befragen. Tötet den Rest.\n\nHabt kein Erbarmen, <Klasse>, denn auch sie würden uns kein Mitleid gewähren.", progress = nil, completion = "Es ist gut, einen echten Krieger an meiner Seite zu haben. Meine Schamanenbrüder sind der Aufgabe zu oft einfach nicht gewachsen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25440] = {title = "Tiefenlord Zin'jatar", objective = "Tötet Tiefenlord Zin'jatar.", description = "Der Tiefenlord ist hier, am anderen Ende der Ruinen. Er hat noch einige Verletzungen von unserer letzten Schlacht.\n\nIch überlasse Euch das Vergnügen, aber gebt Acht, dass er uns dieses Mal nicht entwischt!", progress = nil, completion = "Und damit verebben ihre Angriffe auf uns hoffentlich für eine Weile.", rewards = "Verlorene Krone von AzrakirSeebeherrschende HandschuhePriapswurmarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25441] = {title = "Vortex", objective = "Benutzt die Kugeln des stürmischen Wassers, um 30 schwärmende Schlangen einzufangen.", description = "Ich bin kein Freund von Schlangen, noch weniger von denen hier unten. Zu unserem Glück gehorcht das Wasser vorerst noch meinem Willen.\n\nNehmt diese Kugeln und werft sie auf den Boden, damit sich ein Vortex bildet, der alle Schlangen in der Nähe mit sich reißt. Die Naga werden die Schlangen sicher gegen uns einsetzen, also tragt die Kugeln besser immer bei Euch.", progress = nil, completion = "Wir werden oft mit Druiden verwechselt. Bei einigen Schamanen mag das ja stimmen, aber lasst Euch nicht von dem allgemeinen Irrglauben täuschen, dass wir immer friedlich wären.\n\nNichts von dem, was ich tue, ist harmonisch. Ich beherrsche die Elemente ganz so, wie ich es will. Dafür gibt es keine Gegenleistung. Und ich würde es mir auch nicht anders wünschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25442] = {title = "Eine Perle der Weisheit", objective = "Bringt die leuchtende Perle zu Erdheiler Duarn in der Silberfluthöhle.", description = "<Diese Perle ist anders als alles, was Ihr je gesehen habt. Sie verströmt Licht und, falls Ihr Euch nicht täuscht, auch mächtige Magie.>\n\n<Erdheiler Duarn in der Silberfluthöhle wäre sicher sehr an ihr interessiert.>", progress = "Ja, <Klasse>? Habt Ihr etwas gefunden?", completion = "Was ist das? Eine Perle? Hm, viel mehr noch, glaube ich.\n\nGenau danach habe ich gesucht. Vielen Dank, dass Ihr sie mir gebracht habt.", rewards = "SeesternstulpenDrückerfischgurtTorpedobarschkroneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25443] = {title = "Der Unaussprechliche", objective = "Setzt den wahren Namen zusammen, indem Ihr die drei Feuersteine im Inferno untersucht.", description = "Hat mein Trank gewirkt? Habt Ihr mit einem von ihnen gesprochen?\n\nDann wisst Ihr ja, was zu tun ist. Der Name ihres Elementarmeisters steht auf drei Feuersteinen geschrieben, die überall im Inferno verstreut sind. Überprüft jeden einzelnen von diesen Steinen und wir haben den Namen, den wir brauchen.\n\nSchnell! Euer geliebter Wald brennt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25444] = {title = "Die perfekten Spione", objective = "Fangt 5 Frösche aus Sen'jin und stimmt sie bei Vaniras Totem des Wachens auf ihre Sicht ab.", description = "Es wär dumm, hia blind zu arbeiten, also mach' ich 'n paar winzige Spione, die für Vol'jin Informationen sammeln soll'n. Er muss wissen, was drüben auf den Inseln passiat.\n\nIch könnt' die Hilfe brauch'n, wenn Euch danach is. Ich sag' Euch, was zu tun is. East müsst Iah die Frösche fang'n. Sie bleim gean im Schatten dea Palmen um Sen'jin rum.\n\nWenn Iah die Frösche habt, bringtse hia rüber zu mei'm Totem des Wachens un' stimmt se auf meine Sicht ab.", progress = "Helft Iah jetzt mit die Frösche oder nich?", completion = "Das is genug für meine Zwecke. Nu zum schwierigen Teil.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25445] = {title = "Zalazanes Sturz", objective = "Helft Vol'jin die Echoinseln zurückzuerobern und Zalazane zu töten.", description = "Die Zeit zum Kämpfen ist jetzt! Schon bald brechen wir auf zu den Inseln, halt dich also bereit.\n\nZalazane hat nicht mehr viel Zeit.", progress = nil, completion = "&lt;Name&gt;, du bist ein mächtiger Krieger und ein leidenschaftlicher Kamerad der Dunkelspeere. Die Echoinseln sind jetzt UNSER und wir hätten es ohne dich nie schaffen können.\n\nNimm diesen Umhang. Trag ihn mit Stolz. Jetzt bist du Mitglied des Stamms!\n\nBald haben die Trolle wieder eine Heimat und wir haben dir dafür zu danken.", rewards = "Ihr bekommt:\n\nTuch der Dunkelspeere"}
MultiLanguageQuestData['de'][25446] = {title = "Frösche frei!", objective = "Benutzt, während Ihr Euch auf dem Rücken einer Fledermaus befindet, den Sack Frösche, um 12 abgestimmte Frösche bei den Markierungen auf den Echoinseln zu platzieren.", description = "Nu, wo die Frösche startklar sin', brauch' ich Eure Hilfe, um sie rüba auf die Inseln zu schick'n.\n\nIm Osten von Sen'jin is Tiaführer Marnlek. Eah füaht die Fledamäuse für Vol'jins Späher und kann Euch 'ne Fledermaus leih'n, um raus zu den Inseln zu kommen.\n\nNehmt den Sack Frösche hia mit. Ich hab' die Geista um Hilfe gebeten. Sie ham Rauch geschickt, um Euch zu zeig'n, wo ich die Augen am meisten brauch. Wenn Iah auf'er Fledermaus sitzt, greift in'n Sack un' werft die Frösche in'n weißen Rauch.", progress = nil, completion = "Ich seh' schon, was die Frösche seh'n. Iah habt das pafekt gemacht, &lt;Name&gt;. Nu können Vol'jin un' ich seh'n, was Zalazane voahat.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25447] = {title = "Zeichen des Wandels", objective = "Sammelt 8 infizierte Hirschgeweihe.", description = "Eine üble Krankheit hat die Kreaturen unseres Waldes heimgesucht. Zuerst dachte ich, es wäre einfach eine der Tücken der Natur, aber der Krankheit scheint kein Heilungsprozess zu folgen.\n\nDie Hirsche des Waldes, die normalerweise sehr stark und friedlich sind, haben am meisten gelitten. Einige finden in ihrer Schwäche ihr Ende. Andere sind tollwütig und sehr gefährlich. Um die Geister zu befragen und mehr über die Krankheit in Erfahrung zu bringen, benötige ich die Geweihe der Hirsche.", progress = "Es ist keine schöne Aufgabe, aber es muss getan werden, <Name>.", completion = "Zumindest haben wir dem Leiden dieser Kreaturen ein Ende bereitet. Lasst uns hoffen, dass durch ihr Opfer weiteres Leid verhindert werden kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25448] = {title = "Die Nordschwingenbedrohung", objective = "Tötet 6 Harpyien der Nordschwingen und 6 Windruferinnen der Nordschwingen.", description = "Meine Aufgabe ist es, über Telaron zu wachen. Auch ohne die Meditation, die ihn so verletzlich macht, gibt es in diesem Wald genügend Bedrohungen, die uns beschäftigen.\n\nGenau deshalb stört es mich so sehr, dass ich das Camp nicht verlassen kann. Mehr Harpyien als je zuvor suchen das Gebiet im Nordwesten heim... bösartige Kreaturen, die ihren Dreck überall in den alten Ruinen hinterlassen und sich nicht daran stören.\n\nSie sind eine Bedrohung für unser Lager und haben an diesen Orten nichts zu suchen. Ich werde Euch reichlich belohnen, wenn Ihr Euch ihnen annehmt.", progress = nil, completion = "Danke, &lt;Klasse&gt;. Eine Störung weniger, um die ich mich kümmern muss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25449] = {title = "Das Zeichen der Qualität", objective = "Sammelt 10 dicke Yetibälge.", description = "Meine Einstellung zur Lederverarbeitung verlangt, dass die Arbeit von bestmöglicher Qualität zu sein hat - ohne Kompromisse. Jeder, der behauptet, Qualität sei unwichtig, wird auch versuchen, Euch ein Küstengrundstück in Dun Morogh zu verkaufen!\n\nAuf meiner jüngsten Suche nach hochwertigem Material fand ich dicke Yetibälge. Die Yetis sind in Feralas zuhause und viele findet man in der Wutschrammfeste im Nordosten. Ich hätte gern ein paar Bälge und wenn Ihr mir zehn davon bringt, dürft Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Haltet Ihr das für angemessen? Dann sind wir im Geschäft.", progress = "Für zehn Yetibälge könnt Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Qualität ist mir wichtig und Ihr könnt Euch sicher sein, dass Ihr etwas Hochwertiges erhalten werdet!", completion = "Hattet Ihr die Zeit, die Beschaffenheit dieser Bälge zu bewundern? Richtig verarbeitet können sie widerstandsfähiger sein als Eisen. Nur wenige Leute sind mit diesen Bälgen vertraut und in Verbindung mit bestimmten Lösungen kann ich damit richtige Qualitätswaren herstellen - dank Euch natürlich!\n\nBitte, sucht Euch etwas aus meinem Sortiment aus, als Dank für Eure Mühen!", rewards = "Pratts handgefertigte StiefelPratts handgefertigte HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25450] = {title = "Beste Qualität", objective = "Sammelt 10 Wildschrammyetibälge.", description = "Es ist schon faszinierend, wie sich die Dinge ändern. Die Yetis aus dem Norden haben immer die besten Bälge gehabt, aber diese hier... die Qualität ist wirklich nicht so gut wie sie einst war. Vielleicht sind sie krank, oder werden von etwas krank gemacht.\n\nGlücklicherweise sieht es bei den Wildschrammyetis viel besser aus als früher. Ich wette, dass ihre Bälge jetzt weitaus besser als früher sind!\n\nIch würde Euch für zehn ihrer Bälge gebührend entlohnen. Bringt mir die Bälge, und wir sind im Geschäft.", progress = "Diese Bälge sind zwar nicht so widerstandsfähig wie Thorium, aber sie sind gut und fest.", completion = "Exzellent, Exzellent! Ich denke, diese Bälge werden ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, &lt;Name&gt;. Hier, nehmt eine meiner neuesten Kreationen!", rewards = "Ihr bekommt:\n\nPratts handgemacht Weste"}
MultiLanguageQuestData['de'][25451] = {title = "Makelloser Yetibalg", objective = "Bringt Pratt McGrubben in der Mondfederfeste den makellosen Yetibalg.", description = "Ihr habt einen makellosen Yetibalg gefunden, der besonders dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Pratt McGrubben in der Mondfederfeste mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", progress = "Was ist los, <Name> - habt Ihr etwas Interessantes für mich?", completion = "Fantastisch! Es sieht so aus, als hättet Ihr die Mutter aller Yetibälger gefunden!\n\nIhr könnt Euch darauf verlassen, dass mir dieser Fund einiges wert ist. Normalerweise zahle ich niemandem so viel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke &lt;Name&gt;, dass Ihr bei Eurem Fund an mich gedacht habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25452] = {title = "Das Zeichen der Qualität", objective = "Sammelt 10 dicke Yetibälge.", description = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!\n\nAuf meiner jüngsten Suche nach hochwertigem Material habe ich dicke Yetibälge entdeckt. Die Yetis sind in Feralas beheimatet und man findet sie nördlich von hier, in der Wutschrammfeste. Ihr dürft Euch ein beliebiges Stück meiner Lederwaren aussuchen für einen Zehnerstapel Yetibälge. Wenn das für Euch akzeptabel ist, dann sind wir im Geschäft!", progress = "Konntet Ihr alle Yetibälge besorgen? Meine Lederwaren sind unvergleichlich und ich werde Euch ein Stück meiner handverarbeiteten Qualitätswaren zukommen lassen, wenn Ihr die Bälge habt.", completion = "Ah, wunderbar! Ich sage Euch, diese Bälge sind so widerstandsfähig wie Eisen, man muss ihnen nur eine besondere Behandlung zuteilwerden lassen. Es wird einige Versuche kosten, die richtige Mischung zum Gerben zu finden, aber ich bin zuversichtlich, dass sie mein Zeichen der Qualität noch weiter aufwerten werden.\n\nAber nun zu Euch, &lt;Name&gt;: Eure Hilfe hat sich als unschätzbar für mich erwiesen. Bitte sucht Euch einen der Gegenstände aus, die ich hergestellt habe.", rewards = "Jangdors handgefertigte HandschuheJangdors handgefertigte StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25453] = {title = "Beste Qualität", objective = "Sammelt 10 Wildschrammyetibälge von Wildschrammyetis.", description = "Ich bin etwas verwirrt. Die Wutschrammyetis waren einst die Quelle des besten Leders dieser Länder... aber diese Bälge sind schwach und an manchen Stellen verrottet. Die Kreaturen müssen an einer Art Krankheit leiden.\n\nIch werde eine andere Bezugsquelle finden müssen. Die Yetis aus Wildschrammtal im Süden haben auch sehr starke Bälge. Sie sind aber auch viel gefährlicher; man sollte bei der Jagd auf sie sehr vorsichtig sein.", progress = "Sind die Wildschrammyetis noch da? Habt Ihr die Bälge?", completion = "Exzellent, Exzellent! Ich denke, diese Bälge werden ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, &lt;Name&gt;. Hier, nehmt eine meiner neuesten Kreationen!", rewards = "Ihr bekommt:\n\nJangdors handgemacht Weste"}
MultiLanguageQuestData['de'][25454] = {title = "Perfekter Yetibalg", objective = "Bringt Jangdor Flinkschreiter in der Steinbrecherfestung in Feralas den perfekten Yetibalg.", description = "Ihr habt einen Yetibalg gefunden, der beinahe perfekt scheint. Euch fällt schnell auf, dass dieser außergewöhnlich dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Jangdor Flinkschreiter in der Festung der Steinbrecher mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", progress = "Was ist los, <Name> - habt Ihr etwas Interessantes für mich?", completion = "Dieser Fund ist einfach unglaublich! Ich glaube dies hier ist der beste Balg, den ich je gesehen habe!\n\nTatsächlich wäre hier eine großzügige Belohnung angebracht. Normalerweise zahle ich niemandem so viel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke &lt;Name&gt;, dass Ihr bei Eurem Fund an mich gedacht habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25456] = {title = "Unversehrte Rückkehr", objective = "Kehrt zu Felora Feuerkranz in der Silberfluthöhle zurück.", description = "Ja, ja, ich bin mir sicher, dass Felora Euch zurückhaben möchte. Diese Frau hat einfach keinen Respekt vor Innovationen. Als ich ihr von den Modifizierungen für meinen Erdelementar erzählt habe, hat sie fast einen Anfall bekommen.\n\nGeht schon und sagt ihr, dass alles fein und klärchen ist. Und sagt ihr auch, dass ich ihr nichts von meinem unausbleiblichen Vermögen abgeben werde.\n\nWahrscheinlich schläft sie sowieso am liebsten auf dem Felsen.", progress = nil, completion = "Also ist Sam unversehrt? Und seine arme Assistentin Felice? Das ist gut zu hören.\n\nIch hoffe, dass die Elemente für ihn eines Tages mehr als nur Werkzeuge sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25458] = {title = "Kommandant Skessesh", objective = "Tötet General Skessesh und nehmt seinen Kopf.", description = "Die Anführer dieser Streitmächte müssen fallen! Die Offensive der Naga wird zerbrechen, wenn niemand mehr da ist, um sie anzuführen.\n\nIch habe gesehen, wie der Feigling sich in einem der verlassenen Gebäude versteckt hat. Bahnt Euren Weg durch die anderen und besorgt mir seinen Kopf! Lady Shandris wird ihn selbst in den Händen halten wollen.", progress = "Ist der General gefallen?", completion = "Gut gemacht, diese garstigen Kreaturen verdienen es nicht anders. Mögen die Naga ins Meer zurückglitschen und diesen Ort nie wieder aufsuchen.\n\nIhr habt Euch auf dem Schlachtfeld bewiesen, &lt;Name&gt;. Ich werde bei der Verteidigung dieser Länder Eure Hilfe noch öfter in Anspruch nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25459] = {title = "Ophidophobie", objective = "Tötet 4 Laugenschuppenschlangen in Gorroks Klage.", description = "Wenn es eine Sache gibt, die ich nicht leiden kann, dann sind es Schlangen. Alle Schlangen, egal welche Art.\n\nWährend ich da draußen nach verwertbaren Teilen gesucht habe, habe ich ein Nest von Seeschlangen um das nahegelegene Wrack herum gesehen.\n\nIch fühle mich einfach nicht wohl bei dem Gedanken, dass diese schrecklichen Biester sich jeden Moment hier herein schlängeln könnten.\n\nBitte, <Klasse>! Unternehmt etwas gegen sie!", progress = nil, completion = "Da fällt mir aber ein Stein vom Herzen.\n\nVielen Dank noch einmal, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25460] = {title = "Die Erde erhebt sich", objective = "Tötet 8 brühende Felselementare.", description = "Sogar hier, so nahe am Weltenbaum, fühlen wir die Folgen des Angriffs des Schattenhammers.\n\nUnd da die Bäume in Flammen stehen, wendet sich sogar die Erde in rasendem Zorn gegen uns.\n\nWir dürfen nicht zulassen, dass die Elementare frei durch die Gegend streifen. Geht und helft unseren Männern, ihrer Herr zu werden.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Euer Kampfgeschick ist beeindruckend. Ihr werdet in unserem Bestreben, dem Angriff der Elementare ein Ende zu setzen, eine entscheidende Rolle spielen.", rewards = "Verbrühte SteinschuppenschulterpolsterHandschuhe des KernzerstörersSteinbrecherrobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25461] = {title = "Freiwillige Trolle vor!", objective = "Benutzt Vol'jins Kriegstrommeln, um 5 Trollbürger in Klingenhügel zu rekrutieren.\n\nIhr könnt mit Tierführer Marnlek sprechen, um eine Fledermaus nach Klingenhügel zu bekommen.", description = "Vol'jin hat mir seine Kriegstrommeln gegeben und mia die Verantwortung für die Ausbildung von den neuen Rekruten hia übageben. Das Dumme is nur, dass wia keine neuen Rekruten ham.\n\nWenn ich Euch diese Trommel leih'n wüade, wüadet Iah füa Vol'jin nach Klingenhügel gehn un da den Kriegsruf vabreiten? Wenn Iah auch nua n paar Trolle dazu inspirian könntet, sich anzuschließn, wüade das schon nen Untaschied machen. Wenn Iah sie übazeugt habt, sich freiwillig zu meld'n, bringt sie zu mia zum Ausbilden zurück. Geht rüba zu Tiaführer Marnlek im Süd'n. Eah kann Euch eine Fledamaus für den Flug nach Klingenhügel leih'n.", progress = "Wia brauch'n alle Freiwilligen, die wia krieg'n könn'.", completion = "Iah habt 'n paa gute Rekrut'n gefund'n. Ich trainier' sie hart, un' wia wern nich' aufhör'n, bis wia Zalazane von unsern Inseln vartrieben ham.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25462] = {title = "Runter kommen sie alle", objective = "Klettert auf die Bäume im Rauschenden Hain, greift nach hilflosen Hyjalbärenjungen und werft sie oben vom Baum aus auf das weiche Ziel. Ihnen kann nichts passieren.", description = "Fürchtet Euch nicht vor den Bären in diesem Hain, <Klasse>. Ich habe sie für eine Weile besänftigt.\n\nIch sorge mich vielmehr um das Wohlergehen der Bärenjungen. Aus Angst vor dem Feuer sind die Kleinen auf die Bäume geflüchtet und sitzen jetzt dort fest. Wir müssen die Bären wieder heil auf den Boden bringen!\n\nFliegende Wesen schüchtern sie ein, also müsst Ihr wohl selbst auf die Bäume klettern. Sucht die Stämme nach geeigneten Stellen ab, klettert auf die Bäume, schnappt Euch die Bären und werft sie VORSICHTIG auf das Ziel hier.\n\nDieser Plan ist narrensicher.", progress = "Bitte verletzt die Bäume nicht. Oder die Bären.\n\nOder Euch selbst.", completion = "Ich danke Euch, &lt;Name&gt;. Diese kleinen Bären haben einiges mitgemacht, aber sie werden überleben.\n\nZumindest die, die auf der Matte gelandet sind.", rewards = "WildtierverteidigerBaumgriffhoseKlebfußsandalenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25463] = {title = "Berichtet Silvia", objective = "Meldet Euch bei Siliva am Turm von Estulan.", description = "Ein hochgeborener Magus namens Estulan hat östlich von hier einen Turm gebaut, nachdem er sich von seinen überlebenden Brüdern entfremdet hat, und unterrichtet dort nun junge Nachtelfen in arkaner Magie.\n\nWenn Hohepriesterin Tyrande nicht vor Kurzem Gnade über die Seinen hätte walten lassen, so wäre es nun laut unserer Gesetze meine Aufgabe, ihn hinzurichten. Er wird streng bewacht, doch nur aus Stolz kann ich den Schildwachen Hilfe nicht abschlagen.\n\nIch habe Silvia vorgeschickt, um beim Turm von Estulan die Offensive gegen die Oger in der Nähe einzuleiten, die die Wälder in der Nähe heimsuchen. Meldet Euch bei ihr, um weitere Anweisungen zu erhalten.", progress = nil, completion = "Gut, Euch hier zu sehen. Estulan ist... schwierig. Wir werden uns zuerst für Shandris alleine um die Oger kümmern müssen, bevor Estulan eine Entscheidung treffen wird, ob er uns helfen möchte oder nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25464] = {title = "Baron Geddons Rückkehr", objective = "Nutzt die Macht des Flammenseherstabs, um Baron Geddon zu schwächen.", description = "Ragnaros ist nicht der einzige mächtige Elementar, der wieder in unsere Welt gelangt ist.\n\nDer gefürchtete Baron Geddon führt das Massaker an. Wir müssen seiner Zerstörungswut ein Ende setzen.\n\nDer Flammenseherstab hat sich als sehr mächtig erwiesen. Vielleicht ist er mächtig genug, um den Baron so zu schwächen, dass unsere Erzdruiden ihn an Ort und Stelle fesseln können.\n\nGeht, <Name>, und seid vorsichtig. Baron Geddon ist ein rachsüchtiges und heimtückisches Wesen.", progress = "Habt Ihr Eure Aufgabe schon erledigt, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Wir können es uns nicht leisten, noch mehr Gebiete auf dem Hyjal zu verlieren.\n\nBaron Geddon auszuschalten hat unserem Feind einen schweren Schlag versetzt.", rewards = "Handgelenkplatten des HitzedämmersStreitkolben des druidischen KanalisierersAxt der geerdeten FlammeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25465] = {title = "Immer noch am Riesen schrumpfen", objective = "Benutzt Zorbins Ultraschrumpfer, um Uferschreiter zu schrumpfen und sammelt 6 Schrumpfüberreste.", description = "He, Ihr da! Ich arbeite immer noch an einer Variante von gnomischen Schrumpfstrahlen, benutze aber die weitaus bessere GOBLIN-Technologien dafür! Um Unannehmlichkeiten wie beispielsweise meinen Tod zu vermeiden, möchte ich Euch bitten, es für mich an den Meeresriesen an der Küste zu testen. Ihr solltet nach dem Prozess Schrumpfüberreste auf ihnen finden, bringt mir diese bitte!", progress = "Ich musste den Schrumpfer überarbeiten, damit er nicht mehr bei Bergriesen funktioniert. Ich bin zwar nicht rumgerannt und hab wie wild alles geschrumpft, aber die Nachtelfen haben mir ganz schön einen übergehauen, als sie gesehen haben, dass die Bergriesen geschrumpft waren.", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultraschrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, &lt;Name&gt;. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!", rewards = "Ihr bekommt:\n\nZorbins Megahäcksler"}
MultiLanguageQuestData['de'][25466] = {title = "Noch mehr Treibstoff fürs Schrumpfen", objective = "Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern.", description = "Wenn ich gegen mein besseres Wissen und Gewissen handele und nun doch bleibe, um meinen Ingenieurladen an der Vergessenen Küste aufzumachen, muss ich mich dringend um diese nervigen Elementare kümmern. Verdammt sei der unkontrollierte Elementalismus, sage ich!\n\nGlücklicherweise stellen die Elementare eine ideale Quelle reiner Kraft für meinen Ultraschrumpfer dar – insofern, gebt ihnen Saures! Wenn Ihr dies allerdings tut, bringt mir doch bitte auch ein paar Elementarkerne.", progress = "Ich könnte Euch natürlich auch mit den technischen Einzelheiten langweilen, die sich hinter den Elementarkernen verstecken, aber stattdessen werde ich Euch dazu bringen, diese Aufgabe abzuschließen, indem ich Euch wertvolle Münzen und Belohnungen dafür anbiete. Seid Ihr schon fertig?", completion = "Hervorragend! Diese Kerne werden mich einige Zeit beschäftigen. Nicht zu vergessen, dass es entlang der Küste nun weniger Elementare gibt, die uns Sorgen bereiten werden. Möglicherweise muss ich mich jetzt nicht mehr in den Schlaf weinen, wenn ich daran denke, dass ich mein Lager ausgerechnet am schlimmsten Ort der Welt aufgeschlagen habe.\n\nVielen Dank, &lt;Name&gt;, für Eure Hilfe in dieser Angelegenheit. Es mag vielleicht meine Finanzen ein wenig überstrapazieren, aber ich denke, ich möchte mein Wohlwollen Euch gegenüber in einer Weise ausdrücken, die Ihr versteht... ich hätte da etwas Ausrüstung für Euch!", rewards = "Ihr bekommt:\n\nZorbins wasserfester Hut"}
MultiLanguageQuestData['de'][25467] = {title = "Kliklaks Kehle", objective = "Beschafft Euch den rostigen Schlüssel von Kliklak, um die halb vergrabene Schließkiste im Tang'tharwald zu öffnen.", description = "<Ihr seid angenehm überrascht, dass die Karte noch gut lesbar ist, nachdem sie von einem Meereskrebs so zerfetzt und zerkaut wurde.>\n\n<Sie zeigt ganz deutlich, dass im Tang'tharwald hinter einem riesigen Schalentier eine Schließkiste vergraben liegt.>\n\n<Eine gut getroffene Zeichnung auf der Rückseite der Karte zeigt, dass der Besitzer zusammen mit dem Schlüssel von einem überdimensionalen Krustentier namens Kliklak gefressen wurde.>", progress = "<Das Schlüsselloch der Kiste ist mit kleinen Muscheln verkrustet, sieht aber noch funktionstüchtig aus.>", completion = "&lt;Dem befriedigenden Geräusch einer sich öffnenden Truhe folgt der Anblick eines einst versteckten Schatzes.&gt;", rewards = "Ihr bekommt:\n\nSeepockenbedeckte Großaxt"}
MultiLanguageQuestData['de'][25468] = {title = "Naturgewalten: Feendrachen", objective = "Benutzt Jesanas Feendrachenlockruf, um 10 Grimmlingdrachen oder Grimmlingflitzer zu versammeln.", description = "Man sieht es ihnen wirklich nicht an, aber die reizenden Feendrachen dieses Waldes können sich mit der richtigen Abrichtung als furchterregend erweisen. Sie können unglaubliche Sachen mit magischer Energie anstellen... sie aufsaugen, umleiten und sogar komplett auslöschen.\n\nAlleine sind sie beinahe harmlos, aber in Gruppen können sie in einem Kampf für überwältigende Ergebnisse sorgen. Ihr könnt Feendrachen in den Feldern nordwestlich von hier finden, aber seid vorsichtig, denn die Horde ist in der Nähe.", progress = nil, completion = "Sind sie nicht entzückend? Die Welpen sind sogar noch süßer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25469] = {title = "Naturgewalten: Bergriesen", objective = "Benutzt Jesanas Riesenlockruf, um 5 Bergriesen zu versammeln.", description = "Die Bergriesen sind unsere mächtigsten Verbündeten in den Wäldern. Sie bestehen aus dem Land selbst.\n\nWenige unserer Feinde wollen sich mit einem wandelnden Berg anlegen. Schon allein ein paar wenige Bergriesen können den Ausgang einer Schlacht bestimmen.\n\nDie Bergriesen hier leiden aber seit einiger Zeit an einer Krankheit - die Bergriesen im Südwesten scheinen aber gesund zu sein.", progress = nil, completion = "Ausgezeichnet!\n\n&lt;Name&gt;, Ihr habt uns geholfen, unsere Streitkräfte zu stärken und habt viele dieser Waldkreaturen vor der Horde gerettet. Unsere Armee ist bereit und Mondfederfeste wird allen Bedrohungen standhalten, von der Horde und anderen Feinden!\n\nIm Namen von Lady Mondfeder überreiche ich Euch diese Waffe, die einer Schildwache würdig ist.", rewards = "Macht des HippogryphenMacht des BergriesenMacht des FeendrachenMacht des TreantsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25470] = {title = "Herrin der Tiger", objective = "Lockt die Tigermatriarchin aus ihrem Versteck, während Ihr vom Geist des Tigers erfüllt seid, und benutzt Eure neuen Fähigkeiten, um sie im Kampf zu besiegen.", description = "Erinnat Iah Euch an die Frösche, die Iah zu mein'n Augen un' Ohren gemacht habt? Tja, die ham was Intressantes gefund'n.\n\nAuf 'ner Insel im Südosten ham sie 'nen Tiger entdeckt, den soga die andern Katzen fürcht'n. Diesa Tiger, so was hab'ich noch nie geseh'n.\n\nDea jagt mit'm Instinkt von 'ner Katze, aber dem Vastand von 'ner Person. Könnte 'n mächtiger Geist sein, und 'n starka Vabündeta.\n\nIch ruf den Geist vom Tiger auf Euch runter. Benutzt seine Talente, um die Katze zu find'n un' rauszufordern. Seht zu, dass Iah ihre Hilfe in unserm Kampf um die Inseln gewinnt.", progress = "Habta schon was üba diesen Tiger rausgefund'n?", completion = "Vaniras Frösche sagen also die Wahrheit? Dieser Tiger ist eine Druidin und eine Verbündete? Das hätte nicht besser laufen können. Das ist ein gutes Omen für die kommende Schlacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25471] = {title = "Über den Großen Graben", objective = "Sprecht mit Scharfseher Gadra in der Dunstlichtkammer.", description = "Wenn wir herausfinden wollen, was die Naga hier vorhaben, müssen wir weiter nach Vashj'ir vordringen.\n\nGeht zu den Lichtlosen Weiten, der riesigen Schlucht, die an den Tang'tharwald im Westen grenzt. Wenn Ihr hinüberseht, solltet Ihr eine Ansammlung von Pflanzen sehen, die den Eingang zur Dunstlichtkammer umgeben.\n\nSobald Ihr in der Höhle seid, dauert es eine ganze Weile, bis Ihr an die Oberfläche kommt, aber ich habe dort Freunde, die Euch herzlich willkommen heißen werden.", progress = nil, completion = "Hallo, Mann! Ihr seht kompetenter aus als die meist'n, die hier durchkomm'n.\n\nKommt und ruht Euch 'n wenig aus. Fühlt Euch ganz wie daheim!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25472] = {title = "Der Flammenseherstab", objective = "Sammelt 8 verkohlte Knochenstabfragmente.", description = "Ein mächtiges Artefakt, das als Flammenseherstab bekannt ist, befand sich das letzte Mal, als der Hyjal angegriffen wurde, im Besitz eines Ältesten der Tauren. Es war ein uralter Knochenstab, der seinem Besitzer die Macht über die Feuerelemente verlieh.\n\nSeine Fragmente sind überall hier verstreut. Findet sie und bringt sie zu Malfurion. Vielleicht können wir die Macht des Artefakts noch nutzen.", progress = "Ja, <Name>?", completion = "Ausgezeichnet, &lt;Name&gt;. Dies wird eine ausgezeichnete Waffe gegen die feindlichen Armeen sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25473] = {title = "Kaja'Cola", objective = "Bringt das Sechserpack Kaja'Cola zu Sassy Hartzang im Hauptquartier der HGK in Kezan.", description = "Sassy Hartzang hat mich damit gelöchert, ihr etwas Kaja'Cola für die Party zu Euren Ehren heute Abend zu besorgen.\n\nUps, war das eine Überraschung? Von mir habt Ihr es nicht!\n\nNaja, aber mit dem Produktionstief der letzten paar Tage ist das hier alles, was ich herstellen konnte. Könntet Ihr es ihr bringen?", progress = "<Sassy beobachtet das Sechserpack als würde sie erwarten dass es explodiert, sobald Ihr es ihr gegeben habt.>\n\nWir brauchen mehr Kaja'Cola als das.\n\nIch schwöre, ich werde Feuchtlunte feuern, wenn ich ihn nicht zuerst umbringe!", completion = "Nur dass Ihr es wisst: Kaja'Cola gibt es überall hier im Ort. Es ist das meistverkaufte Produkt des Bilgewasserkartells aller Zeiten! \n\nVergesst nicht, dass ein gepflegtes Image das A und O ist, wenn Ihr auf eine weitere Beförderung aus seid!\n\nNein, wartet! Profit ist das A und O! Aber Explosionen kommen gleich danach. Und dann: Image!", rewards = "Ihr bekommt:\n\nKaja'Cola"}
MultiLanguageQuestData['de'][25474] = {title = "Noch einmaal mit Gefühl", objective = "Tötet 15 beliebige Aale im Tang'tharwald.", description = "Aale gehören zu den widerlichsten Wesen in ganz Azeroth.\n\nSicher, da gibt es diejenigen, denen sie angeblich egal sind. Und dann noch diejenigen, die sogar behaupten, sie zu mögen.\n\nSie lügen.\n\nIn Wahrheit mag nämlich niemand Aale. Nicht einmal Aale mögen Aale.\n\nAzeroth wäre ein besserer Ort, wenn niemand sich ausmalen müsste, wie ein glitschiger Aal sich aus den trüben Tiefen hervor windet und zubeißt.\n\nMitten ins Gesicht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25475] = {title = "Findet OOX-22/FE!", objective = "Bringt das Notrufsignal zu Glotz' Leitroboter in einer Höhle in der Nähe des Wildschrammtals.", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zum Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Glotz Widrikus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe des Wildschrammtals abgestürzt!\"", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Beutebucht zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Glotz ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-22/FE funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25476] = {title = "Rettet OOX-22/FE", objective = "Bringt OOX-22/FE in Sicherheit und meldet Euch dann bei Glotz Widrikus in Beutebucht.", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder zum Funktionieren zu bringen. Eskortiert den Roboter von seinem momentanen Standort zu, ach, sagen wir mal, der Hauptstraße. Das sollte der perfekte Ort für mein Vorhaben sein und bis Ihr dort seid, sollte ich auch alles vorbereitet und aktiviert haben.\"\n\n\"Eskortiert ihn dorthin und kommt dann zu mir nach Beutebucht! Glotz Widrikus - Ende!\"", progress = nil, completion = "Ach, IHR habt so heldenhaft OOX-22/FE gerettet! Ich kann meine Dankbarkeit für Eure Hilfe nicht einmal ansatzweise ausdrücken! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, &lt;Name&gt;; meine Roboter und ich stehen in Eurer Schuld!", rewards = "Fehlgeschlagenes FlugexperimentMaschendrahthandtuchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25477] = {title = "Besser spät als tot", objective = "Benutzt Moanahs Köderstab bei einer gesprenkelten Meeresschildkröte und reitet dann mit ihr zurück zu Moanah.", description = "Grüße, Freund.\n\nSchön zu sehen, dass Ihr die Schlacht heil überlebt habt.\n\nWährend Erunak nach einem sicheren Zufluchtsort für uns sucht, werde ich Euch dabei helfen, ein weniger anstrengendes Transportmittel zu finden.\n\nIch habe Euch einen Köderstab vorbereitet. Benutzt ihn in der Nähe einer Meeresschildkröte. Es ist vielleicht etwas primitiv, aber damit solltet Ihr das Tier unter Eure Kontrolle bekommen.\n\nSobald Ihr Euch mit der Schildkröte vertraut gemacht habt, führt sie einfach hierher zu mir.", progress = "Konntet Ihr eine Meeresschildkröte zähmen, <Name>?", completion = "Wie überaus bedauerlich…\n\nNun, in Anbetracht der Tatsache bin ich froh, dass Ihr unversehrt zurückgekommen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25478] = {title = "Zum Gipfel", objective = "Leiht Euch von Dyslix Silberraff einen Windreiter und sprecht mit Kanati Grauwolke am Westlichen Gipfel in Tausend Nadeln.", description = "Wir sind dabei, am Westlichen Gipfel für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Der Goblin Dyslix Silberraff wird Euch meinen Windreiter zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Kanati Grauwolke, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", progress = nil, completion = "Nyse schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25479] = {title = "Nach Neu-Thalanaar", objective = "Leiht Euch von Dyslix Silberraff einen Hippogryph und sprecht mit Caryssia Jägermond in Neu-Thalanaar in Feralas.", description = "Wir sind dabei, in Neu-Thalanaar für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Der Goblin Dyslix Silberraff wird Euch meinen Hippogryph zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Caryssia Jägermond, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", progress = nil, completion = "Thyssiana schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25480] = {title = "Tanz der Geister", objective = "Sprecht beim Kreis der Ritualtänzer außerhalb von Sen'jin mit Hexendoktor Hez'tok, wenn Ihr bereit seid, die Omen zu konsultieren.", description = "Die Zeit ist reif, über den Angriff nachzudenken. Champion Uru'zin sagt, seine Männer wären bereit. Ihr und Vanira habt gute Arbeit geleistet, indem ihr Informationen gesammelt und uns neue Verbündete gefunden habt.\n\nJetzt lesen wir die Omen. Wir müssen rausfinden, wann wir den Angriff starten können.\n\nFindet Hexendoktor Hez'tok beim Kreis der Ritualtänzer. Er wird das Ritual anfangen, sobald Ihr bereit seid.", progress = "Und, was sagen die Omen?", completion = "Ich werde mir den Rat der Geister zu Herzen nehmen. Mit ihnen hinter uns und der Macht der uralten Loas des Dunkelspeerstammes sind wir bereit, uns zurückzuholen, was uns gehört!", rewards = "Ihr bekommt:\n\nStolz der Dunkelspeere"}
MultiLanguageQuestData['de'][25481] = {title = "Nach Neu-Thalanaar", objective = "Leiht Euch von Seyala Elmsfeuer einen Hippogryph und sprecht mit Caryssia Jägermond in Neu-Thalanaar in Feralas.", description = "Wir sind dabei, in Neu-Thalanaar für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Seyala Elmsfeuer wird Euch meinen Hippogryph zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Caryssia Jägermond, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", progress = nil, completion = "Falfindel Wegeshut schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25482] = {title = "World Event Dungeon - Headless Horseman", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutegefüllter Kürbis"}
MultiLanguageQuestData['de'][25483] = {title = "World Event Dungeon - Coren Direbrew", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFassförmige Schatzkiste"}
MultiLanguageQuestData['de'][25484] = {title = "World Event Dungeon - Ahune", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit gekühlten Waren"}
MultiLanguageQuestData['de'][25485] = {title = "World Event Dungeon - Hummel", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHerzförmige Schachtel"}
MultiLanguageQuestData['de'][25486] = {title = "Die Grimmtotem kommen", objective = "Tötet 7 Marodeure der Grimmtotem.", description = "Es wird eine Zeit lang dauern, aber ich bin sicher, dass wir sie zurückschlagen können.\n\nIhr könnt Tausend Nadeln am besten von einem anderen Ort aus helfen. Es wurde uns berichtet, dass die Gnome und Goblins in den überfluteten Salzwüsten es irgendwie geschafft haben, irgendwie auf einem riesigen Dampfer zu überleben! Rendow an den Docks hat ein Boot, das sie Euch geben kann, um zu dem Dampfer zu gelangen.\n\nEs stört Euch doch nicht, uns auf dem Weg zu ihm ein wenig zu helfen?", progress = nil, completion = "Ein Boot? Ja, dieses hier könnt Ihr haben. Es ist das letzte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25487] = {title = "Die Grimmtotem kommen", objective = "Tötet 7 Plünderer der Grimmtotem.", description = "Die feigen Grimmtotem haben uns überraschenderweise angegriffen, als wir überhaupt nicht vorbereitet waren!\n\nIhr werdet Tausend Nadeln von einem anderen Ort aus besser helfen können, <Klasse>. Es gehen Gerüchte um, dass die Goblins und Gnome irgendwie auf einem Dampfer in den Salzwüsten überlebt haben.\n\nMotega Feuermähne ist auf dem Hügelplateau zu finden - er kann Euch ein Kanu geben, um dorthin zu gelangen.\n\nStört es Euch, wenn Ihr auf Eurem Weg dorthin ein paar Grimmtotem für uns bekämpft?", progress = nil, completion = "Ihr möchtet ein Kanu, um nach Salzwüste zu gelangen? Die Rennbahn wurde doch komplett zerstört?!\n\nWie dem auch sei, für Euren Mut werde ich Euch mein letztes Kanu geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25488] = {title = "Zwei per Boot", objective = "Sprecht mit Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Seid Ihr bereit, <Klasse>? Eine der Schildwachen wird Euch zu der Illusionenrennbahn begleiten.\n\nFalls es dort Überlebende geben sollte, helft ihnen bitte.\n\nDie Göttin stehe Euch bei!", progress = nil, completion = "JA?! Unterbreche ich etwa Eure faszinierende Diskussion?\n\nNein... Nein, bitte, redet nur weiter. Ich bin sicher, dass Eure Störung mit etwas sehr Wichtigem zu tun hat. Wichtiger, als sich um das Überleben aller hier zu kümmern, ganz bestimmt.\n\n&lt;Fizzel wippt ungeduldig mit dem Fuß.&gt;", rewards = "Maloofs ErsatzstiefelSchwimmgürtelArmschienen der verzweifelten NotAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der Fata Morgana\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25489] = {title = "Zwei per Boot", objective = "Sprecht mit Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Seid Ihr bereit, <Klasse>? Einer unserer Kriegerhelden wird Euch zu der Illusionenrennbahn rudern.\n\nFalls es dort Überlebende geben sollte, so werden sie Eure Hilfe dringend benötigen.\n\nMöge die Erdmutter Euch mit einem Lächeln segnen!", progress = nil, completion = "Hallo, Kindchen, ich bin gleich bei Euch. Muss vorher nur diesen Gnomheini hier dazu bringen, den Mund zu halten.", rewards = "Maloofs ErsatzstiefelSchwimmgürtelArmschienen der verzweifelten NotAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der Fata Morgana\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25490] = {title = "Asche auf ihr Haupt", objective = "Tötet 8 Versenger.", description = "<Name>, diese Fanatiker des Schattenhammers wollen alles Leben auf diesem Berg vernichten. Selbst jetzt folgen sie diesem Inferno und legen auf ihrem Weg alles in Schutt und Asche.\n\nErzdruide Hamuul Runentotem ist den Feuern auf den Fersen und versucht, die Wildnis zu retten, bevor sie voll und ganz von der Karte verschwindet. Reist nach Südosten durch das Inferno und die dahinterliegende Straße entlang. Findet den Erzdruiden und helft ihm.\n\nBefreit auf Eurem Weg dorthin die Straßen von allen Versengern, die Euch begegnen.", progress = nil, completion = "Sehr gut. Wir müssen dem Schattenhammer deutlich klar machen, dass wir nie aufgeben werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25491] = {title = "Robuste Saat", objective = "Sammelt 10 Hyjalsetzlinge aus den Haufen versengter Erde.", description = "Dieses Land wurde vom Feuer völlig versengt, aber es kann sich vielleicht dennoch wieder erholen.\n\nEinige Samen tief im Boden haben die sengende Hitze in der Flammenschneise möglicherweise überlebt. Diese robusten Samen sind der Schlüssel zur Wiedererweckung dieses Waldes. Bitte, sammelt einige dieser Setzlinge für mich.", progress = "Ich glaube, dass immer noch Leben unter der Asche herrscht. Was konntet Ihr finden?", completion = "&lt;Der Erzdruide untersucht die Setzlinge.&gt;\n\nDiese Setzlinge haben einen Weltuntergang überlebt. Selbst wenn es nur eine Handvoll ist, haben sie doch unglaubliche Macht. Das Leben erholt sich stets von ganz alleine und ist danach oft stärker als je zuvor.\n\nSobald der Weg frei ist, werden wir diese Setzlinge benutzen, um auf diesem Berg ein Wunder zu wirken, &lt;Name&gt;. Ihr werdet schon sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25492] = {title = "Feuerschneise", objective = "Tötet 10 Lavawoger.", description = "In ihrem Bestreben, den Hyjal zu vernichten, lassen die Schattenhammer Elementare die Erde nach dem Feuer versengen.\n\nSie pulverisieren den Boden, wühlen in der Asche und graben jede noch so kleine Pflanze aus, die überlebt hat, um sie zu zerstören. Es scheint fast so, als würden sie den Weg pflastern für... Ich möchte es mir nicht einmal vorstellen.\n\nHaltet sie auf, bevor es kein Leben mehr auf dem Hyjal gibt. Tötet die Lavawoger!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Der Wald hat eine Chance, sich doch noch zu erholen.\n\nDoch es gibt noch etwas anderes, was Ihr für mich erledigen sollt…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25493] = {title = "Frische Köder", objective = "Sammelt 4 Kernhundinnereien.", description = "Ich war sehr überrascht, zu erfahren, dass der Schattenhammer den großen Schildkrötenahnen Tortolla gefunden und gefangen genommen hat. In diesem Moment ist er am Rande des trüben Aschensees angekettet.\n\nTortolla aus seinen Banden zu befreien wird nicht einfach, aber wir werden einfach einen Schritt nach dem anderen tun.\n\nGeht in die Flammenschneise und sammelt mir Kernhundinnereien. Ich erkläre Euch später warum.\n\nUnd hütet Euch vor Nemesis dem Usurpator, wenn Ihr dort seid! Seine Zeit wird auch noch kommen, aber noch sind wir nicht bereit.", progress = "Habt Ihr die Innereien gesammelt?\n\nKernhunde sind in diesem Teil der Welt nicht heimisch. Sie sind dem Schattenhammer aus den Netherregionen der Erde gefolgt. Lasst Euch von ihrer Ausrottung nicht beunruhigen.", completion = "Sehr gut. Wir werden die Innereien als Köder brauchen, solange sie noch warm sind.\n\nHier ist mein Plan…", rewards = "MagenschlitzerstulpenBlutbefleckte SchulterpolsterAuf Euch wartet eine dieser Belohnungen:\n\nVerkalkter Muskelmagen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25494] = {title = "Ein Halsband für einen Champion", objective = "Besorgt Euch die stachelige Basiliskenhaut von der Dornenschuppenmatriarchin.", description = "Dieser kleiner Kerl ist wirklich bedrohlich, was?\n\nWenn er ein richtiger Kampfwelpe werden soll, müssen wir ihm ein angemessenes Halsband besorgen.\n\nDie Basiliskenmatriarchin hat ihr Nest an der Straße nach Winterquell errichtet. Bringt mir ihre stachelige Haut, damit wir ein schönes Halsband für unseren kleinen Killer hier daraus machen können.", progress = "Habt Ihr sie bekommen?", completion = "Ausgezeichnet! Unser Welpe ist jetzt bereit für den Kampf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25495] = {title = "Vorbereitung auf die Schlacht", objective = "Sprecht mit Tierführer Marnlek, um einen Flug zum Sammelpunkt zu bekommen. Trefft Euch auf der Insel östlich des Kriegslagers mit Vol'jin.", description = "Vol'jin macht seine Ausrüstung klar und die Kriega bereit. Er hat mich gebet'n, Euch zu sag'n, dass Iah ihn und Vanira auf dea Insel im Osten treffen sollt.\n\nVon da werd'n er un die Krieger Zalazane angreif'n. Die Vorfahr'n soll'n Euch beisteh'n, <Name>. Ohne Euch wär' diese Sache nur'n Schatten von dem, was sie is. Redet mit Tierführer Marnlek im Süden, un' er wird Euch 'ne Fledermaus geben, die Euch zum Sammelpunkt fliegt.", progress = nil, completion = "Endlich, alles fertig. Jetzt zeigen wir Zalazane was mit denen passiert, die sich den Dunkelspeeren in den Weg stellen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25496] = {title = "Erbitterter Zweikampf", objective = "Fordert Gromm'ko am Sitz der Auserwählten auf dem Hyjal heraus.", description = "Ich weiß nicht, ob Ihr davon gehört habt, aber es gibt eine gewisse Rivalität zwischen den Ogern im Schattenhammerkult und dem Rest von uns.\n\nWas mich angeht… ist die Sache persönlich.\n\nDieser Oger namens Gromm'ko hat einen Raptor als Haustier, sein Name ist Schlächter. Er hat meine letzten drei Kernhundwelpen getötet.\n\nAber mit diesem hier wird er das nicht schaffen. Er hat einen echten Killerinstinkt.\n\nGeht zum Sitz der Auserwählten und fordert Gromm'ko zu einem Duell zwischen den beiden Tieren heraus. Erniedrigt ihn für mich, <Name>damus.", progress = "Habt Ihr es geschafft, Ntonjaloleydamus? Hat unser kleiner Champion sich gut geschlagen?", completion = "Genau so macht man das!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25497] = {title = "Kopf hoch und Arsch in den Sattel", objective = "Benutzt 6 Stück Schildkrötenfleisch, um einen Haihappen herzustellen.", description = "Unsere Lage hier wird immer verzweifelter, <Volk>.\n\nWir müssen uns auf die Naga und ihre Gefangenen konzentrieren, aber ohne die richtige Vorbereitung wäre das reiner Selbstmord. Und hier unten heißt das, dass Ihr eine schnellere Fortbewegungsmethode braucht.\n\nDiese Haie mögen Meeresschildkrötenfleisch offensichtlich sehr gerne. Wollen wir doch mal sehen, ob wir das zu unserem Vorteil nutzen können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25499] = {title = "Beweglichkeitstraining: Rennt wie der Teufel!", objective = "Rennt 1 Minute lang vor dem flammenden Trainer weg. Verlasst die Schmiede der Unterwerfung dabei nicht.", description = "Bevor wir weitergehen, müssen wir Euch erstmal in Form bringen.\n\nErgebenheit gegenüber den Alten Göttern wird Euch nicht retten, wenn ein Smaragddrache hinter Euch her ist. Leichtfüßigkeit ist das Stichwort.\n\nDoch genug geredet. Wir werden Euren Trainer herbeirufen. Eure Aufgabe besteht darin, vor ihm wegzurennen, ohne dieses Lager zu verlassen.\n\nLos!", progress = "Ja?", completion = "Oh. Ihr seid noch am Leben.\n\nNicht schlecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25500] = {title = "Wortübermittlung", objective = "Gebt die Rede Hauptmann Tret Funkdüse bei Stahlrosts Depot.", description = "Da haben wir sie. Das ist die Rede, <Name>!\n\nSie hat alles, was ein guter Schlachtauftakt braucht: sie ist inspirierend, benutzt eloquente Sprache und spricht den einfachen Gnom direkt an. Nie wurde eine bessere Rede geschrieben!\n\nGebt sie Hauptmann Tret Funkdüse und fragt ihn, ob er noch etwas von Euch braucht.", progress = "Was habt Ihr da, Rekrut?", completion = "Das ist also Tobys Rede? Fantastisch!\n\nRekrut, Ihr habt alles getan, was wir von Euch verlangen können und die Armee Gnomeregans dankt Euch dafür!\n\nWir haben ein Einsatzteam nach Gnomeregan entsendet und ohne Eure Unterstützung wäre das nicht möglich gewesen! Wir möchten Euch bitten, den Reservisten Gnomeregans beizutreten!\n\nDer Sold ist zwar nicht der Rede wert, aber dafür bekommt Ihr diesen todschicken Helm. Passt gut auf ihn auf, eines Tages könntet Ihr ihn brauchen!", rewards = "Ihr bekommt:\n\nStolz von Gnomeregan"}
MultiLanguageQuestData['de'][25502] = {title = "Vorbereitung des Bodens", objective = "Aktiviert und verteidigt einen Flammenzauberschutz.", description = "Der Erzdruide hat mich damit beauftragt, eine Reihe von Flammenzauberschutzen entlang der Grenze dieses Gebiets aufzustellen. Sobald diese aktiviert sind, können wir weitere Angriffe der Feuerelementare vermeiden, die dieses Tal in Schutt und Asche gelegt haben.\n\nSie schützen und nähren zudem den Boden, was auch immer Hamuul damit bezwecken will.\n\nEs ist an der Zeit, zu beginnen. Sucht einen der fünf Flammenzauberschutze, die ich für Euch auf der Karte markiert habe, aktiviert ihn und verteidigt ihn vor einem Gegenangriff, bis seine Magie zu wirken beginnt. Es wird nicht länger als eine Minute dauern.", progress = nil, completion = "Das ist gut! Dank Eurer Arbeit und der Arbeit anderer ist dieses Tal vor einem Gegenangriff geschützt.\n\nIch habe alles getan, was ich konnte. Jetzt liegt der Rest bei Euch und dem Erzdruiden.", rewards = "Umhang des FlammenzauberschutzesHelm des LügnersStab des GlutschützersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25503] = {title = "Schwarzflosses Beute", objective = "Tötet den Orca Schwarzflosse, um an Gilblingels Karte zu kommen.", description = "<Vor dem letzten Eintrag befindet sich eine lädierte Seite, auf der steht:>\n\nUnser selbsternannter König schreckt vor nichts zurück, um an das Vermögen meiner Familie zu gelangen. Er hat mich unaufhörlich bedroht und belästigt.\n\nIch ertrage es nicht mehr!\n\nIch habe den Schatz vergraben und die Karte an Schwarzflosse verfüttert.\n\nDas sollte die gierigen kleinen Griffel meines Vetters von unseren wertvollen Erbstücken fernhalten!", progress = "Ihr habt Gilblingels Familienschatz entdeckt!", completion = "Dieser Gegenstand war in den Augen der hiesigen Gilblinbevölkerung von unschätzbarem Wert und wurde sogar von König Gurboggel selbst heiß begehrt!", rewards = "Gurt aus verkalkter SchwarzflossePolychaetagamaschenCalanoide SchulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25504] = {title = "Ein kleiner Gefallen?", objective = "Bringt die Bauteilliste zu Jinky Pfuschelfix auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Hallo. Schön, Euch kennenzulernen. Ich bin Fizzel Kupferbolz. Willkommen auf meinem Turbodampfer.\n\nWie auch Euch ist mir die Unterstützung von Tausend Nadeln wichtig, und ich bin davon überzeugt, dass der Turbodampfer der ganzen Region neue Hoffnung bringen kann.\n\nVielleicht könnt Ihr uns hier ein wenig helfen? Ich werde sicherstellen, dass Ihr mit allem versorgt werdet, was dafür benötigt ist.\n\nIhr könnt direkt anfangen, indem Ihr diese Bauteilliste zu Jinky Pfuschelfix in ihrem Laden bringt.", progress = "Ist das jetzt endlich die Bauteilliste? Darauf warte ich schon den ganzen Tag!", completion = "&lt;Jinky wirft einen Blick auf die Liste und spuckt aus!&gt;\n\nIch habe nicht mal die Hälfte von dem Kram hier!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25505] = {title = "Ein kleiner Gefallen?", objective = "Bringt die Bauteilliste zu Razzeric auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Ja hallo, <Name>. Ich bin Pozzik, der weltbekannte Raketenwagenfahrer. Willkommen auf meinem Turbodampfer.\n\nWie auch Euch ist mir die Unterstützung von Tausend Nadeln wichtig, und ich bin davon überzeugt, dass der Turbodampfer der ganzen Region neue Hoffnung bringen kann.\n\nVielleicht könnt Ihr uns hier ein wenig helfen? Ich werde sicherstellen, dass Ihr mit allem versorgt werdet, was dafür benötigt ist.\n\nIhr könnt direkt anfangen, indem Ihr diese Bauteilliste zu Razzeric in seinem Laden bringt.", progress = "Ist das meine Bauteilliste von Pozzik?", completion = "Heya, Kumpel, kann ich einen Blick auf die Liste werfen?\n\n&lt;Razzeric spuckt fast aus!&gt;\n\nWas denkt sich Pozzik eigentlich? Er weiß doch, dass ich noch nicht mal die Hälfte von dem Zeug hier habe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25506] = {title = "Abgeseilt", objective = "Findet einen jungen Kugelfisch auf Nagers Friedhof und bringt ihn zum Abgrund in der Nähe der Pferche.", description = "Unsere Zeit hier nähert sich dem Ende.\n\nIch muss über die Schlucht reisen und herausfinden, was die Naga hier tun und warum.\n\nWenn Ihr mir folgen möchtet, solltet Ihr erst Eure Suche nach einem geeigneten Reittier abschließen.\n\nSucht nördlich von hier nach einem jungen Kugelfisch. Sobald Ihr einen gefangen habt, bringt ihn zum Graben im Westen. Ich werde dort alles vorbereiten, was Ihr braucht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25507] = {title = "Panzerknacker", objective = "Benutzt die Kernhundinnereien in der Nähe von Nemesis, um ihn abzulenken. Sammelt ein Panzerfragment von Nemesis auf.", description = "Diese frischen und stinkenden Innereien sind ein unwiderstehliches Festmahl für Nemesis, den verderbten Schildkrötengott, den der Schattenhammer erschaffen hat. Nemesis muss vernichtet werden, aber noch brauchen wir ihn.\n\nOder besser gesagt ein Stück seines steinigen Panzers. Damit können wir ein magisches Ritual durchführen, um den wahren Ahn zu befreien.\n\nGeht in die Flammenschneise und legt diesen Köder in der Nähe von Nemesis aus. Das wird ihn ablenken. Springt auf seinen Rücken und besorgt Euch ein Stück seines Panzers... Und dann rennt, wenn Ihr die Begegnung überleben wollt.", progress = "Nemesis besteht aus reinem, kochenden Zorn in einem steinernen Panzer aus Hass.\n\nSeine Zeit wird kommen.", completion = "&lt;Der Erzdruide nimmt mit einer überraschenden Ehrfurcht den Panzer von Euch entgegen.&gt;\n\nNemesis ist ein Instrument des Bösen, aber er wurde aus einem Panzerfragment des wahren Ahnen erschaffen.\n\nDiese Verbindung werden wir uns zu Nutze machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25509] = {title = "Körperliches Training: Zwangsarbeit", objective = "Baut 5 Flüsterleitsteine ab.", description = "Das Training, das nötig ist, um zu uns zu gehören, ist nicht gerade angenehm. Warum sollte es das auch sein?\n\nDer Pfad zum Diener der Alten Götter ist lang, schmerzhaft und die reinste Seelenqual. Betrachtet dies als Euren ersten Schritt.\n\nNehmt diese Hacke und baut die Leitsteinvorkommen in der Schlucht ab.\n\nNein, wir brauchen nichts von dem Erz. Dies dient ausschließlich Eurem Vorteil.", progress = nil, completion = "Sehr gut. Zumindest seid Ihr fähig genug herauszufinden, was man mit dem spitzen Ende einer Hacke anstellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25510] = {title = "Tortolla spricht", objective = "Geht zu Tortolla, dem Schildkrötenahnen, im Aschensee auf dem Hyjal.", description = "<Der Erzdruide füllt das Panzerfragment mit Wasser, welches sofort zu kochen beginnt. Er fügt ein Bündel Kräuter hinzu und flüstert ein Gebet vor der Statue Malornes.>\n\n<Name>, Tortolla, der Schildkrötenahn, kennt kein Alter. Er ist seit der Zeit der Titanen Teil dieser Welt. Er spricht eine Sprache, die älter ist als alles, was wir kennen.\n\nTrinkt dies und begebt Euch an einen Ort der inneren Ruhe. Ihr werdet in der Lage sein, Tortollas Sprache zu verstehen. Geht gleich zu ihm in den Aschensee. Erlangt das Vertrauen des Ahnen. Das Schicksal des Hyjal hängt davon ab.", progress = nil, completion = "&lt;Volk&gt;.\n\nDiese Sprache. Ist nicht Eure.\n\nWas wollt Ihr... Peiniger?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25513] = {title = "Donnerkuppel: Erbitterter Zweikampf", objective = "Besiegt Megs Schredderschreck.", description = "Wir haben eine Sonderanfrage erhalten! Ich habe hier eine Notiz von einer Kelsey Stahlfunken, die den Käfig betreten und etwas aus der Welt schaffen möchte.\n\nSie hat Euch als Wunschpartner angegeben, <Name>. Ein Fan Eurer alten Erfolge? Oder vielleicht kennt Ihr Euch von woanders?\n\nIch würde an Eurer Stelle nicht absagen. Das klingt nach einem wunderbaren Finale...", progress = nil, completion = "Fantastisch. Ich werde Euch selbst vielleicht einmal zu einem Duell herausfordern.", rewards = "SchredderschreckumhangAuf Euch wartet eine dieser Belohnungen:\n\nRing der DonnerkuppelKelseys Halskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25514] = {title = "Die Bande brechen", objective = "Deaktiviert die beiden Ruten der Unterwerfung, die Tortolla binden.", description = "Aus den Tiefen…\nEin Reich der Dunkelheit und des Feuers.\nGreift nach mir in meinem Schlaf.\n\nIch bin gefesselt, <Volk>.\n\nSchatten lauern in den Feuerruten neben mir.\n\nTötet sie.\n\nAuf dass ich wieder frei sei.", progress = "Sie sind nicht von dieser Welt.\n\nSie kennen weder Erbarmen noch Furcht.", completion = "&lt;Tortolla zittert und schüttelt den Schmutz von seinem riesigen Rücken.&gt;\n\nIhr…\nSeid nicht wie die anderen.\n\nIch bin wieder frei.\n\nDie anderen…\nWerden bezahlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25515] = {title = "In den Tiefen", objective = "Sammelt 10 Raketenwagenteile.", description = "<Jinky krempelt die Ärmel hoch und streicht sich die Haare aus dem Gesicht, während sie Euch genau beobachtet.>\n\nNun gut, wenn Fizzel will, dass Ihr Euer eigenes Boot bekommt, dann müssen wir zuerst die Teile dafür besorgen. Und jetzt ratet mal, wer sie besorgen wird!\n\n<Jinky lächelt, zeigt nach unten und holt daraufhin einen Ersatztaucherhelm und Flossen hervor.>\n\nGenau, <Bruder/Schwester>. Ihr werdet Euch in die Tiefen wagen und alle Raketenwagenteile bergen, die Ihr in den Rennbahnruinen finden könnt.", progress = "Eure Arbeitszeit werde ich erst festhalten, wenn Ihr mir alle Teile gebracht habt, die auf der Bauteilliste stehen.", completion = "Fürs Erste werden wir uns damit zufriedengeben müssen.", rewards = "Pfuschelfix' WesteArmbänder des FahrersNeoprengamaschenRennbahnstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25516] = {title = "In den Tiefen", objective = "Sammelt 10 Raketenwagenteile.", description = "Nun gut, wenn Pozzik möchte, dass Ihr Euer eigenes Boot bekommt, dann müssen wir zuerst die Teile dafür besorgen. Und jetzt ratet mal, wer sie besorgen wird!\n\n<Razzeric lächelt und zeigt nach unten; daraufhin holt er einen Ersatztaucherhelm und Flossen hervor.>\n\nJa, Ihr habt leider recht. Ihr werdet Euch in die Tiefen wagen und alle Raketenwagenteile bergen, die Ihr in den Rennbahnruinen finden könnt.", progress = "Wir können anfangen, sobald wir alle Teile von der Liste haben.", completion = "Das ist schon mal ein guter Anfang!", rewards = "Razzerics WesteArmbänder des FahrersNeoprengamaschenRennbahnstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25517] = {title = "Schenkenschlägerei!", objective = "Provoziert eine Schlägerei in der Schenke!", description = "Diese stinkenden Goblinnichtsnutze werden trotz ihres hellgrünen Alters jetzt etwas erleben!\n\nGeht zur Turbodampferschenke, bestellt eine Flasche Grog, und haut einem der Goblins damit auf den Kopf!\n\nMacht ihnen klar, dass wir ihre Frechheiten nicht länger dulden werden, <Name>!", progress = nil, completion = "So ist es richtig! Ihr seid ein wahrer Segen für die Allianz!\n\nIhr solltet wissen, dass Ihr das in der Schenke jederzeit wieder machen könnt, wenn Ihr wollt. Ich kann Euch dazu nur ermuntern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25518] = {title = "Schenkenschlägerei!", objective = "Provoziert eine Schlägerei in der Schenke!", description = "Diese winzigen, hässlichen und nichtexplodierenden Gnome werden jetzt etwas erleben!\n\nGeht zur Turbodampferschenke, bestellt eine Flasche Grog, und haut einem der Gnome die Flasche über den Kopf!\n\nMacht ihnen klar, dass wir ihre arrogante Art nicht länger dulden werden, <Name>!", progress = nil, completion = "Ja! Ihr seid sehr nützlich für die Horde!\n\nIhr solltet wissen, dass Ihr das in der Bar jederzeit wieder machen könnt, wenn Ihr wollt. Ich kann Euch dazu nur ermuntern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25519] = {title = "Abkömmlinge von Tortolla", objective = "Tötet 6 Tiefe Verderber, die Tortollas Eier im Aschensee angreifen.", description = "Meine Kinder.\n\nSie liegen in der Tiefe.\n\nIn Schlick und Sand.\n\nDie anderen verderben sie.\n\nVerdunkeln ihre Seelen im Panzer.\n\nTötet die anderen.\n\nTötet die Verderber.\n\nRettet sie…", progress = "Meine Kinder.\nSagt mir, dass sie frei geboren werden…", completion = "&lt;Volk&gt;.\nIhr seid nicht wie die anderen.\n\nMutiger. Stärker.\nEin Teil von dieser Welt…\nNicht wie der Schatten, der zuvor zu mir kam.\n\nDanke.", rewards = "Krone der chelonischen FreiheitArmschienen des SchattenläuterersStiefel der unbegrenzten MöglichkeitenKilt der wiedergeborenen ZukunftIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25520] = {title = "Ein Ahn erwacht", objective = "Kehrt zu Erzdruide Hamuul Runentotem im Heiligtum von Malorne zurück.", description = "Ich schlummerte im heiligen Schlick des Hyjal.\nIch schlief, bis die Welt aufbrach.\nAls die anderen kamen, war ich nicht vorbereitet.\n\nJetzt bin ich vorbereitet, <Volk>.\n\nMeine Kinder und ich. Unseren Zorn erregt man nicht leicht.\nDoch er ist endgültig.\n\nSagt denen, die Euch geschickt haben, dass wir für den Krieg bereit sind.\n\nDie anderen werden vom Berg verbannt.", progress = nil, completion = "&lt;Name&gt;!\n\nIhr konntet das Vertrauen des Ahnen gewinnen?\n\nWunderbar! Wir sind einen Schritt näher daran, diesen Berg zurückzugewinnen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25521] = {title = "Skorpidooh!", objective = "Sammelt 6 Dünenscherenstachel von Dünenscherenpeitschern.", description = "Ihr müsst mir helfen, Ihr müsst, bitte! Ich kam mit Chelsea hierher, um ein bisschen Gold zu machen, ehrliche Arbeit, ein paar Sachen verkaufen. Und jetzt liegt sie auf dem Sterbebett! Sie hat Fieber, das selbst einen Schmied umhauen würde und sie halluziniert...\n\nIch glaube, sie wurde von einem der Skorpide hier gestochen! Ich hab das schon einmal gesehen, es ist kein schöner Anblick. Ich brauche ein paar Giftdrüsen, um ein Gegengift herzustellen, aber ich kann sie nicht alleine lassen!\n\nBitte, helft mir! Besorgt mir die Giftdrüsen!", progress = "Habt Ihr sie? Oh, bitte...", completion = "Oh ich danke Euch! Vielen Dank! Ich kenne mich ein bisschen mit Alchemie aus, ich kann auch etwas. Hier wird...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25522] = {title = "Gargantapid", objective = "Erhaltet Gargantapids Giftdrüse.", description = "Nein! Es hat nicht funktioniert! Ich weiß nicht, was ich tun soll, es sei denn...\n\nOh nein, es ist schlimmer, als ich dachte! Sie muss von dem gestochen worden sein, der sich in der Höhle versteckt hat. Ich habe ihn gesehen, als wir angekommen sind. Seine Klauen sind so groß wie Goblins. Sein Schwanz ist so groß wie ein Baum! Wir haben uns am Lagerfeuer leise über ihn unterhalten... wir haben ihn GARGANTAPID getauft!\n\n... hey, lacht Ihr etwa? Hört auf! Das ist alles ernst hier! Chelseas Leben ist in Gefahr! Bitte, ich werde dafür sorgen, dass es sich für Euch lohnt... bringt mir Gargantapids Giftdrüse!", progress = "Ihr seid zurück! Habt Ihr sie?", completion = "Ich kann es kaum fassen! Ihr seid großartig! Hier, bitte, nehmt diese Belohnung, nehmt alles, was Ihr wollt. Ich muss Chelsea retten!", rewards = "RieselroststiefelAuf Euch wartet eine dieser Belohnungen:\n\nChelseas AlptraumGus' Erste-Hilfe-Kasten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25523] = {title = "Fliegen in den Feuerlanden", objective = "Nehmt Euch eine Zwielichtfeuerlanze aus dem Regal hinter Farden und legt sie an. Steigt auf einen von Avianas Wächtern und fliegt zum Sims unter Euch. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", description = "<Name>, unser Feind nutzt diese Grotte in den Feuerlanden, um eine Invasion vorzubereiten. Wir werden hart zuschlagen, und zwar direkt dort, wo sie leben.\n\nAber zuerst müsst Ihr Euch Eure Flügel verdienen. In den Feuerlanden funktioniert das Fliegen nicht so wie in der Außenwelt. Das hat etwas mit der dichten, überhitzten Luft zu tun. Ihr braucht Übung!\n\nNehmt Euch eine Zwielichtfeuerlanze aus dem Regal hinter mir und schwingt Euch auf einen von Avianas Wächtern. Übt das Fliegen. Ihr müsst nur mit den Flügeln schlagen! Fliegt zu der Fahne, die ich auf dem Sims unter uns aufgestellt habe, und kehrt dann zurück.", progress = "Habt Ihr Euch schon an diese Art des Fliegens gewöhnt?", completion = "Gut gemacht! Wie fühlt es sich an?\n\nEs ist eine echte Herausforderung, in dieser brennenden Ödnis die Flugkunst zu beherrschen, aber das ist der einzige Weg.\n\nIch hoffe, dass Ihr für die Schlacht bereit seid, &lt;Name&gt;…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25524] = {title = "Im Plumpsklo", objective = "Erhaltet ein Piratenbrecheisen und versucht, die Tür des Plumpsklos unter Wasser aufzubrechen.", description = "Hallo? Hallo! HILFE!\n\nIch bekomme fast keine Luft mehr! Ihr müsst mich hier rausholen!\n\n<Von innen erklingt ein Würgegeräusch.>\n\nEiner von diesen Schatzjägern der Südmeerfreibeuter hat bestimmt ein Brecheisen bei sich!", progress = "Oh, um des Lichtes Willen, habt Ihr das Brecheisen? Ich bin hier am Ertrinken!", completion = "Oh, was für ein Glück! Nur noch ein bisschen mehr drücken...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIn The Outhouse: Summon Drag Master Miglen - Alliance\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25525] = {title = "Die erste Welle", objective = "Legt eine Zwielichtfeuerlanze an und fliegt auf Avianas Wächter. Tötet 10 Zwielichtritter, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", description = "Da kommen sie, <Name>! Die Zwielichtritter auf ihren schwarzen, in den sengenden Schwefelbrutstätten der Feuerlande geschlüpften Bussarden. Der einzige Weg, sie zu besiegen, führt durch die Luft.\n\nSchwingt Euch erneut in den Himmel, <Klasse>, und tötet sie.\n\nRammt Eure Lanze in die Ritter, um sie zu vernichten.\n\nHinfort! Fliegt, Ihr Narr. Fliegt!", progress = nil, completion = "Ein spektakulärer Flug, &lt;Name&gt;! Ihre gequälten Schreie haben die Wände dieser lichtverlassenen Höhle zum Beben gebracht.\n\nDoch unsere Arbeit ist noch nicht zu Ende…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25526] = {title = "Im Plumpsklo", objective = "Erhaltet ein Piratenbrecheisen und versucht, die Tür des Plumpsklos unter Wasser aufzubrechen.", description = "Hallo? Hallo! HILFE!\n\nIch bekomme fast keine Luft mehr! Ihr müsst mich hier rausholen!\n\n<Von innen erklingt ein Würgegeräusch.>\n\nEiner von diesen dreckigen Schatzjägern der Südmeerfreibeuter hat bestimmt ein Brecheisen bei sich!", progress = "Oh, um Goldes Willen, habt Ihr das Brecheisen? Ich bin hier am Ertrinken!", completion = "Oh, was für ein Glück! Nur noch ein bisschen mehr drücken...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIn The Outhouse: Summon Rugfizzle - Horde\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25531] = {title = "Zwielichtaufstand", objective = "Sprecht mit Jarod Schattensang an den Toren von Sothann auf dem Hyjal.", description = "Ich bin Euch dankbar, dass Ihr mich befreit habt. Lasst uns den Aufruhr, den Ihr verursacht habt, nutzen und hier verschwinden.\n\nWir müssen uns beeilen, bevor die Kultisten uns auf die Schliche kommen.\n\nSucht mich wieder auf, wenn wir diesen Ort verlassen haben.", progress = nil, completion = "Ihr habt meinen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25532] = {title = "Verbesserte Piratenpräzision", objective = "Holt von Mazzer Schrottschrauber ein Rennboot und benutzt die Frostkanone, um 15 Feuer zu löschen.", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber die Kanonenkugeln treffen. Es scheint, als würden die Piraten der Südmeerfreibeuter präziser werden... das Schiff brennt!\n\nIhr habt ja jetzt ein Rennboot. Sprecht mit Mazzer Schrottschrauber. \n\nLöscht die Feuer!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25533] = {title = "Verbesserte Piratenpräzision", objective = "Holt von Griznak ein Rennboot und benutzt die Frostkanone, um 15 Feuer zu löschen.", description = "Oh nein, <Name> - die Kanonenkugeln treffen den Turbodampfer! Es scheint, als würden die Piraten der Südmeerfreibeuter präziser werden... das Schiff brennt!\n\nIhr habt ja jetzt ein Rennboot. Bitte, sprecht mit Griznak.\n\nLöscht die Feuer!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25534] = {title = "Genug gebrüllt", objective = "Tötet den Zuchtmeister der Südmeerfreibeuter.", description = "Vielleicht habt Ihr schon gesehen, dass an dem Schiff, das nördlich von hier angedockt hat, die Kanonen gefeuert werden. Es ist zwar recht lustig, den Gnomen dabei zuzuschauen, mit dem Gesicht voran in den Eisenregen zu rennen, aber leider machen meine Haudraufs das Gleiche, und das ist für meine Gemeinkosten kaum tragbar.\n\nKönntet Ihr versuchen, durch den Kanonenhagel durchzukommen, auf das Schiff zu gelangen und den Zuchtmeister zu töten, der die Kanoniere antreibt? Der Rest der Besatzung wird ein Haufen Trottel ohne Rückgrat sein; wenn er erledigt wurde, sollten sie kein Problem mehr darstellen.", progress = nil, completion = "Gute Arbeit Kindchen. Knapp mit dem Leben davongekommen? Von einer Kanonenkugel gekratzt?\n\nNein? Gut, wir haben hier noch anderes zu erledigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25535] = {title = "Hunger", objective = "Sprecht mit Tauchbegleiter Birmingham in der Glimmertiefenschlucht.", description = "Die Armen. Sie sind am Verhungern.\n\nEs gibt viele Dinge, um die wir uns kümmern müssen, nicht zuletzt um die Naga. Doch zuerst müssen wir ihre Mägen füllen. Ich bin mir nicht sicher, was die Naga da oben in der Muschel ihnen gefüttert haben, aber sie sehen ganz schön mitgenommen aus.\n\nEine beträchtliche Zahl Überlebende hat es in die Glimmertiefenschlucht im Nordwesten geschafft. Schließt Euch ihnen an und helft ihnen. Mit ein bisschen Muschelfleisch bekommen wir die Überlebenden sicher schnell hochgepäppelt.", progress = nil, completion = "Noch mehr Hilfe! Spitze! Wir können sie wirklich brauchen, so viel steht fest.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25536] = {title = "Ein feuchter Händedruck", objective = "Tötet 10 Gezeitenjäger der Glimmertiefen.", description = "Viele der Überlebenden haben sich in die Glimmertiefenschlucht aufgemacht, um beim Muscheltauchen zu helfen. Wir haben Berichte erhalten, laut denen dort unten eine Art Murlocstamm unsere Leute willkürlich angreift.\n\nDer Admiral muss hier bleiben, da sich immer mehr Männer aus der Schnecke melden. Ich kann ihn einfach nicht überreden, den Tauchern ein paar starke Arme zu Hilfe zu schicken. Wenn Ihr Lust habt, würden sie Eure Hilfe sicher dankend annehmen.\n\nKehrt zu mir zurück und gebt mir Bescheid, ob Ihr die Lage in den Griff bekommen habt.", progress = nil, completion = "Vielen Dank, dass Ihr Euch darum gekümmert habt, &lt;Klasse&gt;. Ich weiß, dass wir derzeit viele Sorgen haben, die uns den Kopf zerbrechen, aber die Sicherheit der Überlebenden ist für mich die oberste Priorität.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25537] = {title = "Die Kunst der Anlockung", objective = "Benutzt die Extraktionsapparatur für Anemonenchemikalien, um 8 chemische Anemonenproben von den roten Anemonen entlang der Wände der Glimmertiefenschlucht zu sammeln.", description = "Ich habe eine Idee. Eine brillante Idee! Diese clownartigen Fische sind zu ihrer Verteidigung eine symbiotische Beziehung mit den Anemonen eingegangen. Nachdem ich den Versuch aufgegeben habe, die Taucher als Anemonen zu verkleiden, habe ich den chemischen Lockstoff entdeckt, der die Fische magisch anzieht.\n\nIch habe einen gyroskopischen Thermaseptextraktor mit hierher gebracht, um Proben zu nehmen. Benutzt ihn, um den chemischen Lockstoff aus verschiedenen Anemonen zu extrahieren, und bringt mir dann die Proben, damit ich ihn schnell künstlich herstellen und verteilen kann.\n\nSchnell! Die Brillanz wartet nicht!", progress = nil, completion = "Hervorragend! Chemikalien in Hülle und Fülle!\n\nMein chemischer Direktsynthetisierer ist bereits getestet und vorbereitet. Die Mischung sollte in einem Wimpernschlag bereit zur Verteilung sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25538] = {title = "Geruchsverschleierung", objective = "Benutzt die Applikationsapparatur für Anemonenchemikalien an 8 Muscheltauchern.", description = "Eine herausragende Arbeit, wenn ich mich einmal selbst loben darf. Bereit zur Verteilung.\n\nSprüht einfach die Muscheltaucher mit einem Hauch dieser Chemikalie ein und schon bald sollten sie einen schuppigen Begleiter haben, der sie beschützt. Wenn Ihr wünscht könnt Ihr Euch auch selbst einsprühen, um den gleichen Effekt zu erzielen.\n\nDa wir gerade von Wünschen sprechen: Ich empfehle Euch, den chemischen Lockstoff nur in sehr geringen Dosen zu verwenden. Wenn Ihr zu viel davon verwendet, kann das unerwünschte Folgen haben...\n\nZumindest unerwünscht für Euch. Wahrscheinlich jedoch sehr wünschenswert für die Fische.\n\nHinfort mit Euch!", progress = nil, completion = "Gut gemacht, mein dufter Handlanger! Ihr seid sowohl schnell als auch eifrig, wenn ich das so sagen darf. Mögen Eure weiteren Reisen vor Inspiration und Opulenz nur so überschäumen.", rewards = "Prototyp eines chemischen ApplikatorsBrustschutz der duftenden BegierdeHandschuhe der FischanziehungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25539] = {title = "Abgetaucht", objective = "Sammelt 16 Glimmertiefenmuscheln.", description = "Seid Ihr hier, um beim Muscheltauchen zu helfen?\n\nDann mal los! Hier sind fast überall Muscheln, die ertaucht werden wollen.", progress = "Hat Eurer Ausflug Meeresfrüchte getragen?", completion = "In der Tat, sehr gut gemacht. Dieses beträchtlichen Berges an Muscheln braucht Ihr Euch wahrlich nicht zu schämen. Die Überlebenden in der Höhle werden Euch sicher dankbar sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25540] = {title = "Hungrige Mäuler warten", objective = "Bringt den großen Sack Muscheln zum Stillen Strand.", description = "Wir haben einen riesen Haufen Muscheln gesammelt, der zurück in die Höhle geschleppt werden müsste, und ich habe einfach erwartet, dass Ihr das Schleppen übernehmt. Ihr habt Euch als gefährlich genug erwiesen, um genau <der/die> Richtige für diese Aufgabe zu sein.\n\nIch rechne nämlich damit, dass die Raubtiere auf dem Rückweg nicht ohne Kampf auf solch ein feines Mahl verzichten. Daher solltet Ihr so schnell wie möglich aufbrechen.\n\nVielen Dank für Eure Hilfe, Freund. Es war mir ein Vergnügen.", progress = "Ihr seht aus, als wärt Ihr aus einem bestimmten Grund zu uns zurückgekehrt. War Eure Reise erfolgreich?", completion = "Das ist wunderbar. Ich werde sie sofort kochen. Es ist beruhigend zu wissen, dass wir jetzt wenigstens keine Angst haben müssen, zu verhungern.\n\nIch könnte mir vorstellen, dass der Admiral mit vielen Aufgaben auf Euch wartet. Daher möchte ich Euch zumindest eine Weile lang nicht mehr aufhalten.", rewards = "SeesterngelenkbänderBrustschutz des KöniginnenmuschelhornsMuschelschälerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25541] = {title = "Wir füllen uns die Taschen", objective = "Sammelt 20 Goldfüllungen von den Musketieren der Südmeerfreibeuter oder den Schlägern der Südmeerfreibeuter.", description = "Wir haben eigentlich alles geplündert, was nicht niet- und nagelfest ist, aber fertig sind wir noch nicht hier. Wenn wir dem Dampfdruckkartell schon die Arbeit abnehmen, dann müssen wir schon sicherstellen, dass wir hier auch gut verdienen.\n\nIch habe an den Piraten nur wenige Ohrringe gesehen - das heißt, dass sie ihr Gold am nächstsichersten Ort aufbewahren... in ihren Zähnen. Die Musketiere und Schläger der Südmeerfreibeuter südlich von hier haben in ihren Rängen mehr zu sagen. An ihnen wird man mehr dieser Verschönerungen finden. Bringt mir eine Handvoll Goldfüllungen.", progress = "Jetzt werdet hier mal nicht zimperlich.", completion = "Toll! Gold ist Gold, egal aus welchem Mund, welcher Nase oder wo auch immer man es ziehen musste.\n\nUnd nach dem Schmelzen ist es auch alles ganz hygienisch. Zumindest hygienischer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25542] = {title = "Die Wägen - äh, Boote - einkreisen", objective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", description = "Die Feuer haben wir unter Kontrolle, aber einige der Piraten der Südmeerfreibeuter machen sich bereit, um den Turbodampfer einzunehmen.\n\nEs ist an der Zeit, dass wir die Kanone der anderen Seite benutzen und sie versenken, bevor es zu spät ist!", progress = nil, completion = "Geschafft! Ihr habt es geschafft!\n\n&lt;Jinky packt Euch und gibt Euch einen Schmatzer auf die Wange! Sie findet ihren Anstand wieder und streicht ihre Kleidung straff.&gt;\n\nDanke, dass Ihr meinen Turbodampfer gerettet habt, Kapitän &lt;Name&gt;!", rewards = "Gamaschen des TurbodampfersSchmusehandschuheArmschienen des PiratenversenkersWürdevolle SchulterstückeIhr bekommt:\n\nFlusskahn"}
MultiLanguageQuestData['de'][25543] = {title = "Die Wägen - äh, Boote - einkreisen", objective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", description = "Die Feuer haben wir unter Kontrolle, aber einige der Piraten der Südmeerfreibeuter machen sich bereit, um den Turbodampfer einzunehmen.\n\nEs ist an der Zeit, dass wir die Kanone der anderen Seite benutzen und sie versenken, bevor es zu spät ist!", progress = nil, completion = "Ihr habt meinen Turbodampfer gerettet!\n\n&lt;Razzeric umarmt Euch kameradschaftlich!&gt;\n\nIch kann gar nicht in Worte fassen, wie erleichtert ich bin, Kapitän &lt;Name&gt;!", rewards = "Gamaschen des TurbodampfersHandschuhe des PiratenversenkersArmschienen der ungestümen UmklammerungMännliche SchulterstückeIhr bekommt:\n\nFlusskahn"}
MultiLanguageQuestData['de'][25544] = {title = "Die zweite Welle", objective = "Legt eine Zwielichtfeuerlanze an und fliegt Avianas Wächter. Tötet 10 Zwielichttjoster, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", description = "Da habt Ihr in ein Wespennest gestochen, <Name>. Uns fällt hier die Decke auf den Kopf! Und ihre stärksten Krieger schwingen sich auf Kreaturen, die von dieser Flammenwelt entstellt und verunstaltet wurden.\n\nKehrt noch einmal zurück und holt sie vom Himmel! Gebt jedoch auf die flammenden Brocken Acht.", progress = nil, completion = "Bei Avianas Schwingen, Ihr wurdet zum Fliegen geboren, &lt;Name&gt;!\n\nSchnell, lasst uns dorthin zurückkehren und erneut zuschlagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25545] = {title = "Zu den Waffen!", objective = "Sammelt 4 Speere von Sturmwind, 4 Brustplatten von Sturmwind, 4 Schilde von Sturmwind und 4 Helme von Sturmwind.\n\nIhr könnt die Ausrüstung auch von Strauchdieben der Gilblin sammeln.", description = "In unserem Kampf gegen das Ertrinken waren meine Männer und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich bin geneigt, ihm zu glauben.\n\nWenn wir eine Chance haben wollen, ihnen standzuhalten, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen. Es sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks liegen.\n\nSchnell, <Volk>. Wir sind hier vollkommen schutzlos.", progress = "Habt Ihr unsere Ausrüstung zurückgeholt, <Volk>?", completion = "Gut gemacht, &lt;Klasse&gt;!\n\nDank Euch werden meine Männer sich gegen den Feind wehren können, wenn er angreift.", rewards = "Geplünderte Schiftung von SturmwindÜbriggebliebene GamaschenKapitän Taylors ChopperDer folgende Zauber wird auf euch gewirkt:\n\nKelp Forest Invis Swap 2-3\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25546] = {title = "Siege gehen durch den Magen", objective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", description = "Wenn ich diese Männer für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Essen, kein Sieg.\n\nDiese Soldaten sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass sie zu den Waffen greifen müssen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", progress = "Konntet Ihr etwas Essbares für meine Männer und mich finden, <Klasse>?", completion = "Das sollte gegen die Erschöpfung helfen.\n\nUnd wieder sind wir Euch sehr dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25547] = {title = "Zu unseren eigenen Bedingungen", objective = "Sprecht mit Kapitän Taylor im Salzkutter.", description = "Wir sind so bereit, wie man nur sein kann. Es bringt nichts, hier herumzusitzen und darauf zu warten, dass die Naga uns finden.\n\nIch werde mit den Männern sprechen und dann treffen wir unter unseren eigenen Bedingungen auf den Feind und lassen das Schicksal entscheiden, wie es ausgeht.", progress = nil, completion = "Es ist keine Zeit, um noch zu den Truppen zu sprechen.\n\nAuch gut. Sie wissen, was zu tun ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25548] = {title = "Die Macht des Feuerfürsten", objective = "Tötet 4 Flammenaszendenten und 5 Zwielichtunterwerfer auf der Anhöhe des Aszendenten auf dem Hyjal.", description = "Ich wurde damit beauftragt, unsere militärischen Schachzüge gegen den Feind zu leiten. Eine demutsvolle Aufgabe, wenn man bedenkt, dass Halbgötter unter uns wandeln.\n\nIch muss Euch bitten, einige Überfälle auf Seiten des Feindes durchzuführen. Dabei ist es besonders wichtig, dass Ihr den Feind überrascht und ihn dezimiert, um unsere Hauptstreitmacht zu unterstützen.\n\nEuer erstes Ziel ist die Anhöhe des Aszendenten, wo die am besten ausgebildeten Anhänger des Schattenklans teilweise schon einen elementaren Zustand erreicht haben.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ich habe ein neues Ziel für Euch.", rewards = "Stulpen des GuerillazornsSchulterschutz des UnterwerfersFlammenversengte GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25549] = {title = "Das Sanktum der Propheten", objective = "Tötet 4 Zwielichtauguren, 4 Zwielichtanhänger und 1 Abgesandten der Flamme im Sanktum der Propheten.", description = "Die verrückten Propheten des Schattenhammers versammeln sich in einem Gebiet direkt nördlich des Zirkels des Aszendenten.\n\nMan sagt, dass sie ihre düsteren Visionen direkt von den Alten Göttern empfangen. Ganz gleich, ob das stimmt oder nicht, sie sind wichtige spirituelle Vordenker des Kults. Wenn wir das Sanktum der Propheten angreifen, können wir der Moral unserer Gegner einen schweren Schlag versetzen. Und falls wir Glück haben, lauft Ihr dort auch noch einem persönlichen Abgesandten des Feuerfürsten über den Weg.", progress = nil, completion = "Ihr beweist weiterhin Euren Heldenmut, &lt;Name&gt;. Wenn Ihr so weitermacht, kann der Hyjal dieses Martyrium vielleicht doch überstehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25550] = {title = "Magmamonarch", objective = "Benutzt die Trommeln des Schildkrötengottes, um für den Kampf gegen König Lavatron Unterstützung zu erhalten.", description = "Die Magmariesen, die Ragnaros dienen, stehen unter dem strengen Befehl ihres Königs. Wenn wir ihn ausschalten, werden die anderen sicher in Verwirrung geraten.\n\nOhne die Riesen fällt der Kampf bestimmt ausgeglichener aus. Vielleicht können wir sogar einen Vorteil erringen.\n\nDen Magmamonarchen zu erlegen wird sicher keine einfache Aufgabe. Benutzt diese Trommeln, um den großartigen Tortolla zu Hilfe zu rufen. Er kann König Lavatron bis in alle Ewigkeit in Schach halten. Doch ihn in Schach zu halten wird nicht reichen - und da kommt Ihr ins Spiel.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Bald schon werden wir den Sieg auf dem Hyjal erringen.\n\nEs war mir eine Ehre, an Eurer Seite zu kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25551] = {title = "Der Feuerfürst", objective = "Geht durch das Portal im Sanktum der Propheten und helft Cenarius dabei, Ragnaros zu besiegen.", description = "Jetzt, da der Torwächter aus dem Weg geräumt ist, können die Wächter des Hyjal endlich auf die Sulfuronspitze gelangen.\n\nRagnaros hat keine andere Möglichkeit, als den Hauptweg in die Feuerlande selbst zu verteidigen.\n\nGeht durch das Portal des Schattenhammers im Sanktum der Propheten und trefft mich dort. Malfurion und Hamuul werden Euch dort ebenfalls helfen, während die anderen weiterhin den Feind draußen bekämpfen.", progress = "Ja, <Name>?", completion = "Hyjal wurde gerettet, &lt;Name&gt;. Und das nur dank Euch.", rewards = "Tuch des HyjalrettersAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger des HyjalrettersSignet des Hyjalretters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25552] = {title = "Die Brut des Bösen", objective = "Besorgt Euch den Schädel eines jungen Zwielichtdrachen auf der Anhöhe des Aszendenten auf dem Hyjal.", description = "Dieses Ei, das Ihr beschafft habt, bietet Anlass zur Beunruhigung, <Name>. Die Zwielichtdrachen werden in der Regel aus gestohlenen Eiern anderer Drachenschwärme aufgezogen, die dann durch dunkle Magie verändert werden.\n\nDieses \"natürliche\" Ei ist der Beweis, dass eine ihrer Matriarchinnen inzwischen in der Lage ist, selbst Eier zu legen. Wir müssen sie vernichten, bevor ihre Brut sich ausbreiten kann.\n\nGeht zur Anhöhe des Aszendenten, wo diese entarteten Wesen gehalten werden sollen, und tötet einen der Jungdrachen. Wir werden seinen Schädel benutzen, um seine Mutter hervorzulocken.", progress = "Ihr seid zurück, <Name>.", completion = "Das habt Ihr gut gemacht. Wir werden das hier verwenden, um die Zwielichtmatriarchin aus ihrem Versteck zu locken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25553] = {title = "Tod der Brutmutter", objective = "Legt den Zwielichtdrachenschädel an der Futterstelle südlich des Zirkels des Aszendenten ab und tötet Desperiona.", description = "Wir haben die Futterstelle der Matriarchin südlich des Zirkels des Aszendenten ausfindig gemacht.\n\nSie wird sehr wütend sein, wenn sie merkt, dass sie einen ihrer Drachen verloren hat. Legt den Schädel in der Nähe des Aases ab, das sie verschlingt. Wenn sie ihn sieht, wird sie hervorkommen und versuchen, Rache zu nehmen.\n\nDann wartet eine nette Überraschung auf sie.", progress = nil, completion = "Das lief… noch besser als erwartet.", rewards = "Schienbeinschützer der gewalttätigen RacheHandgelenksschützer aus MatriarchinnenbalgMadensichere HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25554] = {title = "Geheimnisse der Flamme", objective = "Beschafft Euch den Kodex des Aszendenten, die brennenden Litaneien und den Folianten der Flamme auf der Anhöhe des Aszendenten auf dem Hyjal.", description = "Wenn wir Ragnaros wieder in die Feuerlande verbannen wollen, müssen wir uns Zugang zur Sulfuronspitze verschaffen.\n\nNur den vertrauenswürdigsten Mitgliedern des Schattenhammerkults werden diese wertvollen Informationen anvertraut.\n\nGeht und sucht auf der Anhöhe des Aszendenten nach Folianten. So übel diese Bücher auch sein mögen, wir können uns die Gelegenheit nicht entgehen lassen, mehr über die Schwächen unseres Feinds zu erfahren.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, <Name>?", completion = "Diese grauenvollen Bücher sollte es besser gar nicht geben. Und doch sind die darin enthaltenen Informationen für uns von größter Wichtigkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25555] = {title = "Der Torwächter", objective = "Benutzt das Horn des Cenarius, um Hilfe dabei zu erhalten, Azralon den Torwächter zu töten.", description = "Laut diesen Folianten dient einer von Ragnaros' mächtigsten Leutnants als einziger Torwächter der Sulfuronspitze.\n\nIhr werdet ihn nicht alleine besiegen können.\n\nBlast in dieses Horn, wenn Ihr Euch in den Kampf mit Azralon stürzt. Daraufhin werden alle in der Nähe befindlichen Streitkräfte zu Eurer Hilfe eilen.\n\nIhr müsst Euch beeilen, <Name>. Der Feuerfürst kommt unseren Plänen sicher schnell auf die Schliche.", progress = nil, completion = "Es ist vollbracht. Nun bleibt Euch nur noch Eines zu tun.", rewards = "Treter des TorwächtersAuf Euch wartet eine dieser Belohnungen:\n\nHalsreif des HeroldsAzralons verdrehte Rune\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25556] = {title = "Nach Zul'Farrak", objective = "Findet Mazoga in Zul'Farrak.", description = "Dieser üble Verräter... ich hätte es besser wissen müssen, als jemand seines Schlags zu vertrauen. Die Suche nach Sul'thraze hat mich geblendet.\n\nVergebt mir, <Name>. Mazoga ist nach Zul'Farrak geflohen, der bevölkerungsreichste Teil der Länder der Sandwüter.\n\nIhr müsst ihm folgen, wenn Ihr das Schwert wirklich haben wollt. Geht nicht alleine; der Stamm der Sandwüter liegt hinter diesen Mauern auf der Lauer und sie werden Euch nicht willkommen heißen.\n\nIch werde hier bleiben. Ich muss die Suche nach der Klinge beenden. Solltet Ihr sie finden, so behaltet sie. Ich muss aufhören, bevor es mich verzehrt.", progress = nil, completion = "&lt;Mazogas Geist grinst Euch blutverschmiert an.&gt;\n\nHey, wie geht's, Mann?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25558] = {title = "Alles oder nichts", objective = "Helft Kapitän Taylor bei der Verteidigung des Salzkutters.", description = "Es ist soweit.\n\nHier werden wir uns zur Wehr setzen.\n\nWir müssen dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass diese Narren es sich zweimal überlegen, bevor sie sich ihm erneut nähern!\n\nMögen unsere Klingen ihnen Angst und Schrecken einjagen!", progress = nil, completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", rewards = "Zerschmetterter Halt des SteuermannsArmschienen des versunkenen TraumsGugel des verlorenen SchnittersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25559] = {title = "Anspruch erheben", objective = "Tötet 10 Ruinenjäger der Blutelfen.", description = "Es scheint, als wären nicht nur wir an den Ruinen interessiert. Jetzt haben wir ausgerechnet Blutelfen bei unseren Ausgrabungsstellen.\n\nIch hatte damit gerechnet, dass sie in der Hitze und ohne ihre schicken Brunnen und weichen Kissen eingehen würden, aber bisher halten sie sich erstaunlich gut und versuchen, uns mit Gewalt aus den Südmondruinen zu vertreiben.\n\nEs ist an der Zeit, ein paar Schädel zu zertrümmern. Macht Euch auf und zeigt diesen Elfen, dass mit uns nicht zu scherzen ist!", progress = nil, completion = "Das wird es der Horde zweimal zeigen! Die Geschichte der Zwerge in Ruhe zu lassen und keine zerbrechlichen Sofaliebhaber in den Kampf zu schicken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25560] = {title = "Eierwelle", objective = "Legt eine Zwielichtfeuerlanze an und fliegt Avianas Wächter. Zerstört 40 Eier der Feuerlande, indem Ihr über sie rauscht. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", description = "Ohne Verteidiger sind die Eier der Feuerlande angreifbar.\n\nSchwingt Euch erneut in die Lüfte und zerschmettert diese Eier! Rauscht einfach über sie hinüber, um sie zu zerbrechen. Sucht in jeder Ritze, Felsspalte und Seitenhöhle nach ihnen. Schnell!", progress = nil, completion = "Ein entscheidender Schlag!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGoldener MinitjostbussardBlauer Minitjostbussard\n\nDer folgende Zauber wird auf euch gewirkt:\n\nJoust Lance Cleanup\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25561] = {title = "Die Wägen - äh, Boote - einkreisen", objective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", description = "Die Feuer mögen unter Kontrolle sein, aber die Piraten der Südmeerfreibeuter machen sich trotzdem bereit, um den Turbodampfer einzunehmen!\n\n<Name>, Ihr müsst zurück zu Mazzer Schrottschrauber und auf Euer Boot. Benutzt die Kanone, um sie zu versenken, bevor es zu spät ist!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Gamaschen des TurbodampfersSchmusehandschuheArmschienen des PiratenversenkersWürdevolle SchulterstückeIhr bekommt:\n\nFlusskahn"}
MultiLanguageQuestData['de'][25562] = {title = "Die Wägen - äh, Boote - einkreisen", objective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", description = "Die Feuer mögen unter Kontrolle sein, aber die Piraten der Südmeerfreibeuter machen sich trotzdem bereit, um den Turbodampfer einzunehmen!\n\n<Name>, Ihr müsst zurück zu Griznak und auf Euer Boot. Benutzt die Kanone, um sie zu versenken, bevor es zu spät ist!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Gamaschen des TurbodampfersHandschuhe des PiratenversenkersArmschienen der ungestümen UmklammerungMännliche SchulterstückeIhr bekommt:\n\nFlusskahn"}
MultiLanguageQuestData['de'][25564] = {title = "Kampfschwimmer von Sturmwind", objective = "Findet 6 Teile einer Kampfschwimmerausrüstung aus Sturmwind.", description = "Ihr habt uns einen großen Dienst erwiesen, <Klasse>, also werde ich Euch ein kleines Geheimnis verraten. Die Männer, die Ihr heute gerettet habt, gehören nicht zu den normalen Truppen von Sturmwind.\n\nWir sind Teil einer Sondertruppe von Elitesoldaten, die nicht nur hierher geschickt wurden, um uns gegen die Horde zu behaupten, sondern auch, um die massiven geologischen Störungen vom Meeresgrund in der Nähe zu untersuchen.\n\nIch erzähle Euch das, weil unsere streng geheime Ausrüstung unten in den Schiffswracks hier liegt.\n\nDiese Ausrüstung muss dringend geborgen werden!", progress = "Konntet Ihr die Ausrüstung sicherstellen, <Klasse>?", completion = "Es scheint alles in Ordnung zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25565] = {title = "Sprachfragmente", objective = "Sammelt 5 uralte Hieroglyphen.", description = "Wir haben den ersten richtig großen Fund seit Jahren hier in den Südmondruinen gemacht. Meine Jungs haben Steintafeln ausgegraben, auf denen alte Schriften zu finden sind. \n\nDie Glyphen auf den Tafeln sind uns gänzlich fremd, aber sie könnten mit den Wandschriften der Titanen zusammenhängen, die wir auch gefunden haben.\n\nStellt Euch nur vor, was dieser Fund bedeuten könnte!\n\nGeht für mich zu den Südmondruinen und helft uns, die Tafeln zu sammeln. Die anderen Jungs können nicht von dort weg, weil die Blutelfen sonst den Platz einnehmen werden!", progress = "Habt Ihr die Tafeln?", completion = "Seht Euch das an... es ist kein Trollisch, kein Qiraji, nur ein Geheimnis, das gelüftet werden will.\n\nBei Euch sind die Tafeln vorab sicher. Es ist an der Zeit, in die Ruinen aufzubrechen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25566] = {title = "Die Geheimnisse Uldums", objective = "Sucht in der Vorkammer von Uldum nach einem unzerstörten Artefakt.", description = "Ich habe diese Ruinen jahrelang erforscht, um den Eingang zu finden. Wir haben sogar einen Teil der Tore eingerissen, nur um undurchdringbare Mauern darunter zu finden. Jetzt hat der Kataklysmus da drinnen wahrscheinlich alles komplett zerstört, aber in erster Linie hat er für uns etwas geöffnet, was uns verschlossen war!\n\nEuch soll diese Ehre zukommen, <Junge/Mädchen>: Begebt Euch nach Innen und seht, ob es noch Sachen gibt, die nicht zerstört wurden. Aber seid vorsichtig... wir können nicht wissen, wer oder was sich da drinnen noch befindet.", progress = nil, completion = "Die Truhe liegt ungestört hier und wurde seit Tausenden von Jahren nicht mehr geöffnet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25574] = {title = "Flammen von oben", objective = "Sucht das Lager des Schattenhammers nördlich von Nordrassil und benutzt Tholos Horn.", description = "Dank Eurer Arbeit haben wir grob die Richtung bestimmen können, aus der die Eindringlinge kommen.\n\nJetzt müssen wir nur noch ihr Lager außer Gefecht setzen und ihre Vorhaben hier auf dieser Seite von Nordrassil durchkreuzen.\n\nNehmt dieses Horn. Damit könnt Ihr einen unserer Smaragddrachen herbeirufen, der hinabstürzen und diesen Schattenhammerkultisten eine kleine Kostprobe der Flammen geben wird, die sie so wahnsinnig verehren.", progress = "Ist es schon getan, <Name>?", completion = "Ausgezeichnet, &lt;Name&gt;. Das sollte die Angriffe ein für alle Mal aufhalten, sobald wir diesen Elementaren den Garaus gemacht haben.", rewards = "GiftfeuergroßschwertBeinschützer des HornbläsersGurt der verhinderten InfiltrationIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25575] = {title = "Geschmiedet aus Schatten und Flammen", objective = "Zerstört 10 Waffenkisten des Schattenhammers.", description = "Die Waffen, die der Schattenhammer gegen uns einsetzt, werden von Schmiedemeister Pyrendius in diesen Hallen gefertigt. In der Hand seines Trägers gleitet das Metall durch Rüstungen wie durch Butter. Doch sobald ein anderer die Waffen in den Händen hält, wird der Stahl brüchig und zerbirst.\n\nUnd so sei es, <Name>. Ich sehe lieber, wie diese verfluchten Waffen in tausend Stücke zerspringen, als dass sie unserem Feind geliefert werden.\n\nSucht nach den Waffenkisten des Schattenhammers in diesen Höhlen und zerschlagt sie!", progress = nil, completion = "Gut, gut. Nichts gefällt mir besser als mit anzusehen, wie das Werk unserer Feinde vernichtet wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25576] = {title = "Der Zorn des Wolfsahnen", objective = "Tötet 12 Arbeiter der Dunkeleisenzwerge.", description = "Da sind wir tief im Reich des Feuergottes und was finden wir? Ragnaros' kleine Marionetten, die sich abrackern, um seinen Willen zu erfüllen.\n\nDiese Arbeiter der Dunkeleisenzwerge vervollständigen und verpacken die Waffen, die der Schattenhammer bei seiner Eroberung des Hyjal einsetzen möchte. Es ist mir egal, ob sie aus freien Stücken hier sind oder ob sie einer Gehirnwäsche unterzogen und hierher verschleppt wurden. Sie sind und bleiben Feinde unseres geliebten Wolfsahnen und müssen dafür mit dem Leben bezahlen.", progress = nil, completion = "Tot? Gut. Sie haben ihr Schicksal selbst besiegelt, als sie sich mit Ragnaros und seinem Königreich des Feuers verbündet haben.\n\nLasst ihre Körper hier unten zu Asche zerfallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25577] = {title = "Zerschmettert die Kerne", objective = "Besorgt 8 schwelende Kerne von sengenden Wächtern und zerschmettert sie dann auf den Ambossen des Schattenhammers.", description = "Diese sengenden Wächter sind der Inbegriff der Blutrünstigkeit! Wir vernichten sie, doch schon ein paar Minuten später entflammen sie wieder aus der Asche.\n\nIch glaube, dass es eine Möglichkeit gibt, sie für immer zu zerstören. Doch dazu benötigen wir jemanden, der sich zu ihren vordersten Reihen durchschlägt.\n\n<Name>, tötet die sengenden Wächter und bringt ihre Kerne zu den Ambossen in der Nähe. Zerschmettert sie auf den Ambossen des Schattenhammers und vernichtet sie für immer!", progress = nil, completion = "Tolle Leistung!\n\nEs gab eine Zeit, in der Abenteurer diese Kerne sammelten, um daraus mittelmäßige feuerresistente Rüstungen herzustellen. Aber vorerst bin ich einfach nur froh, dass Ihr diese Ausgeburten ein für alle Mal vernichtet habt.", rewards = "AmbossbrucharmschienenKerngeschmiedeter GurtTuch der schwelenden TräumeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25578] = {title = "Rückkehr nach Nordrassil", objective = "Sprecht mit Ysera in Nordrassil auf dem Hyjal.", description = "Ich bringe Fandral schnell zur Mondlichtung. Ich hoffe, dass ich bald zurück bin, um in der Schlacht helfen zu können.\n\nMeldet Euch in der Zwischenzeit bei Ysera und berichtet ihr von den aktuellen Entwicklungen.", progress = nil, completion = "Alysras Entscheidung war vielleicht nicht die weiseste, &lt;Name&gt;. Aber wir haben keine Zeit, um uns darüber Gedanken zu machen.\n\nIch bringe wichtige Erkenntnisse vom Smaragdgrünen Traum.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPing Ysera 0\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25579] = {title = "Überraschungsangriff", objective = "Tötet 10 Patrouillen der Azsh'ir.", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Klasse&gt;.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25580] = {title = "Schnelles Handeln", objective = "Zerstört 8 Überwacher der Azsh'ir.", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Und genau rechtzeitig. Der Admiral hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", rewards = "Brustschutz der alarmierenden TräumeSchlingaalsandalenAuf Euch wartet eine dieser Belohnungen:\n\nKaurischneckenanhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25581] = {title = "Suche nach der Vergangenheit", objective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", description = "Hört mal... <Name>, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nIch möchte nur, dass Ihr, wenn Ihr ohnehin schon in der Stadt seid, nach bedeutenden Objekten Ausschau haltet. Die Statuen interessieren mich ganz besonders.", progress = nil, completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", rewards = "Improvisierter HistorikerumhangBeinschützer der GöttlichkeitZeiterhellende ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25582] = {title = "Ein besserer Standort", objective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Süden der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", progress = nil, completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, &lt;Klasse&gt;.\n\nEs klingt so, als ob das Gebäude unter der Terrasse am anderen Ende der Ruinen einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25583] = {title = "Auf dem Schlachtfeld", objective = "Bringt das Bruchstück zurück zum Stillen Strand.", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", progress = "Ja, <Klasse>?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25584] = {title = "Die Rückkehr der Ahnen", objective = "Sprecht mit Oomla Weißhorn in der Wolfsschlucht auf dem Hyjal.", description = "Es ist unerlässlich, dass wir jeden einzelnen Schrein der Ahnen zurückerobern, <Name>.\n\nFolgt der Straße westlich des Saftgrünen Dickichts in die Wolfsschlucht.\n\nWir haben dort ein paar Agenten postiert. Helft ihnen, wo Ihr könnt, und macht Euch auf den Weg zum ersten Schrein.\n\nDer Wolfsgott trug bei den Elfen den Namen Goldrinn und bei den Orcs den Namen Lo'Gosh. Er wird uns im Kampf gegen den Feind ein mächtiger Verbündeter sein.", progress = nil, completion = "Ysera hat Euch geschickt? Gut! Wir können hier dringend Hilfe brauchen.\n\nWir werden die Schreine der Ahnen nie zurückgewinnen können, solange der Schattenhammer die Straßen unter seiner Kontrolle hat. Irgendwie müssen wir gegen diese Flut ankämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25585] = {title = "Die Kanonen erstummen lassen", objective = "Zerstört 8 Stützpunktkanonen.", description = "Jetzt können wir uns endlich um die verfluchten Kanonen auf dem Felsen östlich von hier kümmern.\n\nNehmt doch bitte Euer Boot und fahrt damit zum Südmeerstützpunkt. Ihr werdet dort die Kanonen finden, die auf uns feuern.\n\nDie Piraten haben aber vom Ingenieurswesen keine Ahnung. Es sollte also recht einfach sein, die Kanonen zu verstopfen - dann sollten sie einfach explodieren.", progress = nil, completion = "Sie schießen immer noch, aber schon viel weniger! Yiiiippiiiiiiiiiiiiiiiiiiiiie!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25586] = {title = "Die Kanonen erstummen lassen", objective = "Zerstört 8 Stützpunktkanonen.", description = "Jetzt können wir uns endlich um die verfluchten Kanonen auf dem Felsen östlich von hier kümmern.\n\nNehmt doch bitte Euer Boot und fahrt damit zum Südmeerstützpunkt. Ihr werdet dort die Kanonen finden, die auf uns feuern.\n\nDie Piraten haben aber vom Ingenieurswesen keine Ahnung. Es sollte also recht einfach sein, die Kanonen zu verstopfen - dann sollten sie einfach explodieren.", progress = nil, completion = "Sie schießen immer noch, aber schon viel weniger! Yiiiippiiiiiiiiiiiiiiiiiiiiie!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25587] = {title = "Atempause", objective = "Untersucht den Schmugglerschmiss im Tang'tharwald und signalisiert Adarrah dann, dass sie sicher hineingehen kann.", description = "Bitte, <Volk>! Ihr müsst mir helfen!\n\nDie Naga, Haie und dann dieses schreckliche Monster, das unser Schiff angegriffen hat... Ich bin nur knapp dem Tod entronnen.\n\nIch kann eine Höhle erkennen, die vielleicht sicher ist, aber ich wage mich nicht dorthin bis ich sicher weiß, dass dort Luft ist.\n\nKönntet Ihr nachschauen, ob alles in Ordnung ist?", progress = nil, completion = "Ich kann Euch nicht genug danken, &lt;Volk&gt;.\n\nIch hoffe nur, dass dieser ganze Alptraum ein glückliches Ende findet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25588] = {title = "Ein wenig Vergeltung", objective = "Tötet 15 Piraten der Südmeerfreibeuter in Südemeerstützpunkt.", description = "Ich glaube, es ist an der Zeit, ein wenig Vergeltung zu üben. Das kann man mir kaum übel nehmen, nachdem sie mich in dem Plumpsklo eingesperrt hatten, um mich zu ertränken?!\n\nEs wird sich für Euch lohnen, wenn Ihr für mich zum Südmeerstützpunkt am östlichen Steilhang reist, und für mich Rache nehmen könntet.", progress = nil, completion = "Das wird diesen gemeinen Hunden eine Lektion erteilen! Ich danke Euch, &lt;Name&gt;.", rewards = "PapierrollenarmschienenStiefel des RennmeistersPlumpsklostiefelAuf Euch wartet eine dieser Belohnungen:\n\nHeimzahlungsband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25589] = {title = "Ein wenig Vergeltung", objective = "Tötet 15 Piraten der Südmeerfreibeuter in Südemeerstützpunkt.", description = "Ich glaube, es ist an der Zeit, ein wenig Vergeltung zu üben. Das kann man mir kaum übel nehmen, nachdem sie mich in dem Plumpsklo eingesperrt hatten, um mich zu ertränken?!\n\nEs wird sich für Euch lohnen, wenn Ihr für mich nach Südmeerstützpunkt am östlichen Steilhang reist, und für mich Rache nehmen könntet.", progress = nil, completion = "Das wird diesen gemeinen Hunden eine Lektion erteilen! Ich danke Euch, &lt;Name&gt;.", rewards = "PapierrollenarmschienenFusselzischs StiefelPlumpsklostiefelAuf Euch wartet eine dieser Belohnungen:\n\nHeimzahlungsband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25590] = {title = "Wo ist Wizzel?", objective = "Findet Wizzel Kupferbolz in Südmeerstützpunkt in Tausend Nadeln.", description = "Hey, <Name>, Ihr habt meinen Bruder Wizzel auch nicht gesehen, oder?\n\nIch weiß nur, dass die Piraten ihn gefangen genommen haben! Er hatte wohl vor, ihnen irgendwelchen Ingenieurskram zu verkaufen.\n\nKönnt Ihr bitte in Südmeerstützpunkt östlich von hier nach ihm suchen? Ich befürchte, dass der nichtsnutzige Goblin Flämmer, mit dem er immer unterwegs ist, ihn in Schwierigkeiten gebracht hat!", progress = nil, completion = "Hey! Holt mich hier raus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25591] = {title = "Donnerkuppel: Erbitterter Zweikampf", objective = "Besiegt Kelsey Stahlfunken.", description = "Wir haben eine Sonderanfrage erhalten! Ich habe hier eine Notiz von einer Megs Schredderschrek, die den Käfig betreten und etwas aus der Welt schaffen möchte.\n\nSie hat Euch als Wunschpartner angegeben, <Name>. Ein Fan Eurer alten Erfolge? Oder vielleicht kennt Ihr Euch von woanders?\n\nIch würde an Eurer Stelle nicht absagen. Das klingt nach einem wunderbaren Finale...", progress = nil, completion = "Fantastisch. Ich werde Euch selbst vielleicht einmal zu einem Duell herausfordern.", rewards = "SchredderschreckumhangAuf Euch wartet eine dieser Belohnungen:\n\nRing der DonnerkuppelKelseys Halskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25592] = {title = "Angriff aus der Tiefe", objective = "Tötet 10 Strauchdiebe der Rotkiemen.", description = "Ich konnte ein paar von den Überlebenden in die Höhle helfen, aber so langsam wird die Lage da draußen brenzlig. Als ob wir nicht schon genug Probleme hätten, schleichen sich jetzt auch noch diese leuchtenden Murlocs aus der nahegelegenen Spalte an und überfallen die gestrandeten Überlebenden.\n\nDie Männer da oben sind Krieger und werden sich nicht ohne Kampf ergeben, aber nach dieser verdammten Muschel sind sie alle ganz schön mitgenommen.\n\nWenn Ihr noch ein wenig Atem in Euren Lungen habt, geht nach oben und löscht ein paar dieser Murlocs aus. Höllschreis Augen ruhen auf Euch.", progress = nil, completion = "Ihr wisst wirklich, was Ehre bedeutet, &lt;Klasse&gt;. Ihr erfüllt Höllschrei mit Stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25593] = {title = "Gepanzerte Rettung", objective = "Sammelt 8 Spiralungpanzer und gebt sie gestrandeten Überlebenden von Nespirah.", description = "Viele haben es noch nicht in die Höhle geschafft. Bestimmt sind sie an den Rändern des Grats über uns gestrandet.\n\nWir haben ein paar Spiralungpanzer auf dem Weg hierher gefunden. Sie erzeugen zwar nicht viel Sauerstoff, aber er hat gereicht, um uns zur Höhle zu bringen.\n\nIch muss hier unten bleiben, um die Ankömmlinge zu zählen und sie wieder auf die Beine zu bringen. Tut mir einen Gefallen und sammelt diese Spiralungpanzer. Bringt sie zu meinen Männern oben auf dem Grat und gebt ihnen einen fixen Tritt in den Hintern, damit sie sich hier hinunter bewegen.", progress = nil, completion = "Danke, &lt;Klasse&gt;. Ihr habt Euch als äußerst nützlich erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25594] = {title = "Garstige Krebse", objective = "Sammelt 12 von Fiascos fehlenden Teilen.", description = "Das war dieser verdammte Krebs!\n\nUnd ich dachte, all das Training durch den Marsch hierher macht mich richtig stark! Meine Ausrüstung wurde immer leichter und leichter. Aber nein! Dieser Krebs hat ein Loch in meine Tasche geschnitten und all meine Teile sind auf dem ganzen Weg hierher rausgefallen.\n\nBitte, helft einem gutaussehenden Goblin, ja? Geht und sammelt meine fehlenden Teile ein. Ich bin mir sicher, dass diese hinterhältigen, bösartigen kleinen Krebse auch welche davon gestohlen haben.", progress = "Unterschätzt nie die Anziehungskraft von Glitzerkram.", completion = "Schön, dass Ihr leicht verdientes Gold erkennt, wenn es Euch über den Weg läuft. Es war mir eine Freude, mit Euch Geschäfte zu machen, Kumpel.", rewards = "HosentaschenstreitkolbenUngewöhnlich freizügiger BrustschutzWickeltücher des TeilesammlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25595] = {title = "Was zum Essen", objective = "Sammelt 8 Stück Fleisch eines Schnappkieferbarschs.", description = "Wollten sie uns zu Tode hungern?! Gefangenen keine Nahrung zu geben ist einfach niederträchtig.\n\nWir müssen diesen Soldaten etwas Essbares geben. Die einfachste Möglichkeit besteht wohl in diesen riesigen Schnappkieferbarschen. Ein paar von denen werden unseren Hunger auf Fleisch sicher ein paar Tage stillen können.\n\nWenn Ihr mir einige bringt, sorge ich dafür, dass sie zubereitet und gerecht verteilt werden.", progress = "Bei all diesen knurrenden Mägen klingt es, als hielte sich ein Monster in dieser Höhle versteckt. Das macht mich ganz schön nervös.", completion = "Jetzt zu meinem Teil der Vereinbarung. Ich sorge sofort dafür, dass das hier zubereitet und verteilt wird.\n\nWir beide müssen uns später weiter unterhalten. Ich brauche Hilfe, die mir diese Soldaten einfach nicht bieten können.", rewards = "Handgelenksschützer der MeiofaunaBrustwickel aus BarschhautFiletiermesserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25596] = {title = "Wo ist Flämmer?", objective = "Findet Flämmer in Südmeerstützpunkt in Tausend Nadeln.", description = "Hey, <Name>, Ihr habt unseren Büchsenmacher Flämmer auch nicht gesehen, oder?\n\nIch weiß nur, dass die Piraten ihn gefangen genommen haben! Er hatte wohl vor, ihnen irgendwelche Waffen zu verkaufen.\n\nKönnt Ihr bitte im Südmeerstützpunkt östlich von hier nach ihm suchen? Ich befürchte, dass der nichtsnutzige Gnom Wizzel Kupferbolz, mit dem er immer unterwegs ist, ihn in Schwierigkeiten gebracht hat!", progress = nil, completion = "Hey! Holt mich hier raus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25597] = {title = "Kommandant Jarod Schattensang", objective = "Sprecht mit Elementarist Ortell am Flüsternden Pass.", description = "Nur einmal gab es einen Kommandanten, der in der Lage war, Halbgötter und Sterbliche gleichermaßen anzuführen.\n\nSein Name war Jarod Schattensang. Seine Führungsqualitäten waren so überragend, dass Cenarius und die anderen Ahnen sich aus freien Stücken seinem Befehl unterstellt haben.\n\nEr galt viele Jahre als verschollen. Keiner wusste, was mit ihm geschehen war. Bis jetzt.\n\nEr wird in einem Lager des Schattenhammers in der Flüsternden Schlucht gefangen gehalten.\n\nEure Aufgabe besteht darin, ihre Reihen zu unterwandern und Jarod zu befreien. Sprecht mit dem, den sie Ortell nennen, am Flüsternden Pass im Südosten.", progress = nil, completion = "Oh hallo! Ich bin froh, dass sie jemanden mit Eurem Können für dieses Unterfangen geschickt haben.\n\nDieser Auftrag erfordert viel Fingerspitzengefühl. Wir können nicht riskieren, dass Kommandant Schattensang getötet wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25598] = {title = "Einer geht noch", objective = "Findet Samir und Mack.", description = "Jetzt, da Ihr mich in Sicherheit gebracht habt, muss ich Eure Freundlichkeit leider noch etwas weiter strapazieren.\n\nDer Kapitän unseres Schiffes, Samir, ist immer noch da draußen. Und auch Mack. Ich bin mir sicher, dass sie es zum Meeresgrund geschafft haben, aber ich konnte nicht sehen, was dann aus ihnen geworden ist.\n\nOhne ihre Hilfe könnte ich es an einem Ort wie diesem einfach nicht aushalten.\n\nIch habe sie in einem Tanggeflecht westlich des Ortes, an dem Ihr mich gefunden habt, aus den Augen verloren.\n\nBitte, beeilt Euch! Sie können noch nicht weit sein...", progress = nil, completion = "Was würde ich nur ohne Euch machen, &lt;Volk&gt;!\n\nIch mag es mir nicht einmal vorstellen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25599] = {title = "Aschenmaul, der Portalmeister", objective = "Tötet Aschenmaul und findet den Foliant der Öffnungen.", description = "Der Schattenhammer verwendet diese und andere Korridore dieser Art, um Vorräte von den Elementarebenen nach Azeroth zu bringen. Um diese Passagen zu versiegeln, müssen wir wissen, wie sie gebaut sind.\n\nSucht den Foliant der Öffnungen, den die Elementare verwenden, um die Tore zwischen den Ebenen zu öffnen.\n\nDer Portalmeister Aschenmaul sollte einen bei sich tragen. Ihr müsst ihn töten. Aber Vorsicht! Er hat wahrscheinlich den ein oder anderen Trick auf Lager...", progress = "Der Foliant! Habt Ihr ihn gefunden?", completion = "Das ist der Foliant, von dem wir so viel gehört haben?\n\n&lt;Jordan hievt die Steintafel hoch und schaut sie sich an.&gt;\n\nIch verstehe… Wie gut, dass ich ein wenig von der Elementarschrift lesen kann. Ich mache mich gleich an die Übersetzung. In der Zwischenzeit gibt es ein weiteres Problem, um das wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25600] = {title = "Schmiedemeister Pyrendius", objective = "Tötet Schmiedemeister Pyrendius. Lockt ihn auf die Portalrunen und benutzt sie, um ihn zu schwächen.", description = "Eine entsetzlich bösartige Macht hat sich mitten im Herzen dieser Höhle niedergelassen, <Name>. Schmiedemeister Pyrendius hat viele der verfluchten Waffen, die der Schattenhammer auf seinen Beutezügen oben verwendet, selbst geschmiedet.\n\nBevor wir die Feuerlande verlassen... muss Pyrendius sterben.\n\nEr wird sicher nicht leicht zu besiegen sein, aber wenn ich den Folianten recht verstehe, können wir kurz kleine Tore zum Meeresschlund öffnen, dem Reich des Wassers. Lockt Pyrendius auf eine Portalrune und aktiviert sie, um ihn zu schwächen.", progress = nil, completion = "Es ist vollbracht! Wir werden diese Flammenhölle hinter uns versiegeln und lassen den Schattenhammer die Leichen finden, die wir hinterlassen haben. Ohne Euch hätten wir das nicht geschafft, &lt;Name&gt;!", rewards = "Gesprengte Fußfessel des SchmiedemeistersHelm der furchteinflößenden FangzähneSchiftung des WolfskönigsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25601] = {title = "Klassenprimus", objective = "Sprecht mit Instrukteurin Mylva an der Schmiede der Unterwerfung auf dem Hyjal.", description = "Damit ist die Sache klar, \"<Name>damus\"! Ihr seid der Klassenprimus!\n\nIhr habt die Ehre, zu einer Masse der fanatischsten, blutdürstigsten und nachweislich geisteskrankesten Leute dieses Planeten zu sprechen.\n\nGeht und meldet Euch bei Eurem Instrukteur, um alle Details zu erhalten. Aber vergesst nicht: Euer Ziel ist es, die Feindschaft zwischen den Ogern am Sitz der Auserwählten und den anderen, weniger privilegierten Rassen zu schüren.\n\nWenn alles gut läuft, werden wir während des darauf folgenden Aufruhrs Jarod hier heraus schmuggeln.", progress = nil, completion = "Da seid Ihr ja, Kunrebidamus. Ich wollte etwas mit Euch besprechen.\n\nIch habe von dem unglücklichen Vorfall gehört, dem Euer armer Freund Okrog zum Opfer fiel.\n\n&lt;Mylva schaut nach links, dann nach rechts. Schließlich nickt sie und zwinkert Euch verschmitzt zu.&gt;\n\nIhr seid ein besserer Schüler, als ich dachte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25602] = {title = "Der zündende Funke", objective = "Besorgt Euch das Pulverfass von Budds Ausgrabung.", description = "Mack ist immer noch bewusstlos und ich fürchte, dass wir ihn verlieren, wenn wir dieses Feuer nicht in Gang bringen. Da das Holz feucht geworden ist, brauchen wir einen speziellen Zünder.\n\nIn der Nähe befindet sich ein verlassenes Lager. Dort findet Ihr ein Fass mit Sprengstoff. Alleine schaffe ich es nicht bis dorthin.\n\nKönntet Ihr es für uns hierherschleppen? Für Mack?", progress = "Habt Ihr den Sprengstoff aus dem Lager geholt, <Klasse>?", completion = "Ausgezeichnet!\n\nMal schauen, ob das für unsere Zwecke geeignet ist…\n\nTretet zurück, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Complete Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25607] = {title = "Där Gnomcordär", objective = "Holt 8 Stücke dreckige Goblintechnologie.", description = "Diese Goblins ekeln misch an. Die dreckische Goblinteschnique ist jeder Gnomenteschnique unterlegen, abär...\n\n<Professor Xakxak seufzt.>\n\nDas ist die letzte Teil von die Puzzle! Isch kann misch nischt bauen die Gnomcordär, wenn isch nischt 'aben etwas von die dreckische Goblinteschnique!\n\nIhr müsst ge'en in die Osten nach \"Stinkwerk\" und 'olen von ihnen etwas von die dreckische Goblinteschnique! Ihr werdet finden sie bei die Goblinteschniquer.\n\n<Professor Xakxak lacht spöttisch.>\n\nGoblinteschniquer? Was das sollen sein?\n\n<Professor Xakxak zuckt mit den Schultern.>\n\nEin Oxymoron?", progress = "Wo ist die Schrott? 'abt Ihr es?", completion = "Ah, die Schrott 'aben angekommen! Das ist die letzte Teil von die Puzzle! Jetzt isch muss machen fertisch! Achtüng, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25608] = {title = "Brandrodung", objective = "Schwingt Euch auf einen Smaragddrachen und tötet 40 Einheiten des Schattenhammers und 5 Zwielichtdrachen.", description = "Der Sieg ist möglich, <Name>.\n\nDieses Portal ist nicht nur dazu da, um Cenarius durch den Traum zurückzubringen. Denkt darüber nach, <Name>. Sobald das Tor durch den Smaragdgrünen Traum geöffnet ist, können unsere Truppen sich darüber frei zur Mondlichtung, nach Nordrassil und sogar an den strategisch gut gelegenen Wyrmruhtempel bewegen.\n\nAlles, was Ysera braucht, ist Zeit. Es liegt an Euch, die Streitmächte des Schattenhammers daran zu hindern, sich in der Flüsternden Schlucht zusammenzuziehen und uns vom Osten her anzugreifen.\n\nNehmt einen der Smaragddrachen und versetzt ihnen einen empfindlichen Schlag!", progress = "Ihr seid zurückgekehrt, <Name>.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Vielleicht können wir ja doch noch gewinnen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Cenarius Event Camera\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25609] = {title = "Versunkene Schätze", objective = "Sammelt 8 versunkene Schatzkisten.", description = "Tony Zweihauer, der Piratenadmiral, hat den Schlüssel für den Käfig - und ist von Ogern bewacht, die Ihr nicht töten können werdet!<Wizzel heult noch ein bisschen und schaut plötzlich nach oben. Man kann sehen, dass ihm eine Idee gekommen ist.>\n\nIch hab's! Was ist Piraten wichtiger, als alles andere? Sogar wichtiger als Grog? Genau... Schätze!\n\nSie hatten einst ein Schiff voller Schätze, das von einem riesigen Walhai versenkt wurde. Die Schätze sind überall im Illusionsschlund verteilt, nordwestlich von hier.\n\nGeht, und holt die Schätze ein!", progress = "Oh Mann, habt Ihr etwa schon alle versunkenen Schatzkisten?", completion = "Oh, wie schön - seht Euch nur diese Beute an!\n\nMoment... bringt das mal näher her!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25610] = {title = "Versunkene Schätze", objective = "Sammelt 8 versunkene Schatzkisten.", description = "Tony Zweihauer, der Piratenadmiral, hat den Schlüssel für den Käfig - und ist von Ogern bewacht, die Ihr nicht töten können werdet!<Wizzel heult noch ein bisschen und schaut plötzlich nach oben. Man kann sehen, dass ihm eine Idee gekommen ist.>\n\nIch hab's! Was ist Piraten wichtiger, als alles andere? Sogar wichtiger als Grog? Genau... Schätze!\n\nSie hatten einst ein Schiff voller Schätze, das von einem riesigen Walhai versenkt wurde. Die Schätze sind überall im Illusionsschlund verteilt, nordwestlich von hier.\n\nGeht, und holt die Schätze ein!", progress = "Ihr habt schon alle versunkenen Schatzkisten?", completion = "Oh, wie schön - seht Euch nur diese Beute an!\n\nMoment... bringt das mal näher her!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25611] = {title = "Rückkehr aus den Feuerlanden", objective = "Kehrt zu Ian Duran am Schrein von Goldrinn auf dem Hyjal zurück.", description = "Ich werde die restlichen Anhänger Goldrinns durch das Tor scheuchen und dieses Portal hinter uns versiegeln.\n\nDer Rest unserer Streitkräfte auf dem Hyjal will sicher von unserem Sieg erfahren. Kehrt zu Ian Duran zurück und lasst ihn wissen, was wir entdeckt und wie wir triumphiert haben!\n\nTretet einfach durch das Portal, um auf den Hyjal zurückzukehren.", progress = nil, completion = "Sie bringen Verstärkung direkt über die Elementarebenen auf den Hyjal? Das erklärt natürlich einiges!\n\nGoldrinn ist gewiss stolz auf Euch, weil Ihr dieses Flammentor versiegelt habt, &lt;Name&gt;, aber vielleicht gibt es noch mehr Portale, die versiegelt werden müssen. Ihr solltet auch die anderen Schreine untersuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25612] = {title = "Rückkehr aus den Feuerlanden", objective = "Kehrt zu Takrik Wutheuler am Schrein von Goldrinn auf dem Hyjal zurück.", description = "Ich werde die restlichen Anhänger Lo'Goshs durch das Tor scheuchen und dieses Portal hinter uns versiegeln.\n\nDer Rest unserer Streitkräfte auf dem Hyjal will sicher von unserem Sieg erfahren. Kehrt zu Takrik Wutheuler zurück und lasst ihn wissen, was wir entdeckt und wie wir triumphiert haben!\n\nTretet einfach durch das Portal, um auf den Hyjal zurückzukehren.", progress = nil, completion = "Sie bringen Verstärkung direkt über die Elementarebenen auf den Hyjal? Das erklärt natürlich einiges!\n\nLo'Gosh ist gewiss stolz auf Euch, weil Ihr dieses Flammentor versiegelt habt, &lt;Name&gt;, aber vielleicht gibt es noch mehr Portale, die versiegelt werden müssen. Ihr solltet auch die anderen Schreine untersuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25613] = {title = "Tut Euch selbst einen Gefallen", objective = "Sprecht mit Kalen Freipfeil am Volltrefferposten im Steinkrallengebirge.", description = "Also diese Nachtelfen haben einen verzweifelten Hilferuf an uns geschickt, der sich so anhörte:\n\n<Gnombus verstellt seine Stimme, um wie eine Frau zu klingen.>\n\n\"Bitte kommt und helft uns! Die große, gemeine Horde hat Goblins! Oh, wir kommen mit Goblins nicht klar! Sie ziehen uns an den Haaren und bringen uns zum Weinen!\"\n\nGut, also, hier sind wir nun.\n\nDas erste, was ich gemacht habe, war ihre Luftverteidigung mit einigen meiner neuen Heckenschützengewehre auf Vordermann zu bringen. Das Problem ist... Sie benutzen keine Schusswaffen. Tut Euch selbst einen Gefallen und helft ihnen, ok? Ihr findet sie südlich von hier.", progress = nil, completion = "&lt;Kalen seufzt.&gt;\n\nWir benutzen Schusswaffen ganz ohne Probleme, mein Freund. Gegen KANONEN habe ich allerdings etwas...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25614] = {title = "Der einzige Weg nach unten ist im Leichensack", objective = "Tötet 8 Schwadronskommandanten des Kriegshymnenklans.", description = "Am Himmel wimmelt es nur so von schwerbewaffneten Orcs, die auf noch schwerer gepanzerten Windreitern sitzen. All unsere Bemühungen, sie vom Himmel zu holen sind gescheitert. Unsere Pfeile prallen normalerweise einfach von diesen widerwärtigen Kreaturen ab. Wenn es uns gelingen sollte, einen abzuschießen, benutzen die Orcs ihre Goblinfallschirme und landen sicher auf dem Boden.\n\nIhr müsst die Heckenschützenkanonen von Gnombus benutzen und damit erst die Windreiter des Kriegshymnenklans und danach die Orcs an den Fallschirmen abschießen.\n\nDer einzige Weg nach unten ist im Leichensack.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Gnomtechnologie ist zwar leicht nervtötend, aber ziemlich wirksam. Jetzt sollten der Weg zur Scherwindfeste frei sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25615] = {title = "Kehrt zur Sternenstaubspitze zurück", objective = "Kehrt zu Jägerin Jalin an der Sternenstaubspitze im Eschental zurück.", description = "Jägerin Jalin wird erfreut sein zu hören, dass der Weg zur Scherwindfeste jetzt frei ist. Bitte kehrt zur Sternenstaubspitze zurück und informiert sie über unseren Erfolg. Sie wird mit ziemlicher Sicherheit noch mehr Arbeit für Euch haben, da der Weg jetzt frei ist.\n\nVielen Dank und viel Glück, <mein Freund/meine Liebe>.", progress = nil, completion = "Jetzt, da die Luft rein ist, sind unsere Hippogryphen in der Lage, sich frei ins Steinkrallengebirge zu bewegen. Gut gemacht, &lt;Name&gt;!\n\nUnd jetzt wenden wir uns wichtigeren Dingen zu. \n\nWas Ihr am Volltrefferposten erlebt habt, war nur ein Beispiel für die Vernichtung, die Höllschrei hinter sich zurücklässt. Als Kriegshäuptling der Horde hat Höllschrei Kalimdor zum Territorium der Horde erklärt. Alle, die sich der Horde widersetzen, werden vernichtet.\n\nWir sind die letzte Verteidigungslinie von Kalimdor. Wenn wir fallen, fällt Kalimdor. Die Horde muss aufgehalten werden!", rewards = "SternenstaubgürtelHippogryphendauengürtelStiefel des freien WegesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25616] = {title = "Höllschreis Vermächtnis", objective = "Tötet 10 Verbrenner von Krom'gar.", description = "Begebt Euch über den Steinkrallenpass ins Steinkrallengebirge und lauft in Richtung der schwelenden Bäume. Sucht Verbrenner von Krom'gar, die den Wald zerstören und tötet so viele Ihr könnt! Aber Vorsicht, die Verbrenner sind mächtige Orcs. Wenn Ihr sie mit normalen Mitteln angreift, bedeutet das wahrscheinlich Euren Tod. Zerstört die Ölkanister auf ihren Rücken und sie werden von den Flammen verschlungen!\n\nWenn Ihr Erfolg habt, meldet Euch bei Schildwache Heliana an der Scherwindmine. Sie wird neue Befehle für Euch bereithalten.", progress = nil, completion = "Jetzt, da Ihr Euch um die Verbrenner von Krom'gar gekümmert habt, kann der Wald vielleicht wieder nachwachsen. Allein die Zeit kann die Wunden heilen, die die Horde hinterlassen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25617] = {title = "In den Schlund!", objective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", description = "Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Ich weiß nicht, wohin es führt. Ich weiß nur, dass es nicht zu dieser Welt gehört und ich es nicht betreten kann. Und alle meine anderen Anhänger, die hineingegangen sind, kamen nie wieder heraus.\n\nIch möchte, dass Ihr dieses Reich betretet und meine Klauen und Zähne darin seid. Tretet durch das Flammentor. Wenn er noch lebt, dann trefft Euch auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr meine Macht in diesem Reich nutzen könnt.\n\nSeid mutig, <Name>. Findet heraus, wohin das Flammentor führt, und vernichtet alles, was Ihr dahinter findet.", progress = nil, completion = "Ah, Ihr seid also der Champion, so wie Lo'Gosh es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Allianz auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Lo'Goshs Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", rewards = "Ihr bekommt:\n\nFangzahn von Lo'Gosh"}
MultiLanguageQuestData['de'][25618] = {title = "In den Schlund!", objective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", description = "Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Ich weiß nicht, wohin es führt. Ich weiß nur, dass es nicht zu dieser Welt gehört und ich es nicht betreten kann. Und alle meine anderen Anhänger, die hineingegangen sind, kamen nie wieder heraus.\n\nIch möchte, dass Ihr dieses Reich betretet und meine Klauen und Zähne darin seid. Tretet durch das Flammentor. Wenn er noch lebt, dann trefft Euch auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr meine Macht in diesem Reich nutzen könnt.\n\nSeid mutig, <Name>. Findet heraus, wohin das Flammentor führt, und vernichtet alles, was Ihr dahinter findet.", progress = nil, completion = "Ah, Ihr seid also der Champion, so wie Goldrinn es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Horde auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Goldrinns Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", rewards = "Ihr bekommt:\n\nGoldrinns Fangzahn"}
MultiLanguageQuestData['de'][25619] = {title = "Wiederbesetzung", objective = "Tötet 10 Verteidiger der Kvaldir in den Ruinen von Vashj'ir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "An Kvaldir zum Töten mangelt es hier nicht. Offensichtlich hat unser Angriff sie ganz schön aus der Bahn geworfen. Die Stadt war so lange verlassen, dass sie wahrscheinlich nicht damit gerechnet haben, auf Gegenwehr der Naga zu stoßen.\n\nÜber ihren Anführer haben wir bisher noch nichts erfahren. Ich bin mir sicher, dass wir diesen Feigling noch früh genug aus seinem Loch hervorlocken können, wenn wir seine Leute weiter abschlachten.\n\nWollen wir fortfahren?", progress = "Ich habe Geschichten von der Wildheit dieser Kvaldir gehört, aber bis jetzt scheint das nur heiße Luft zu sein.", completion = "Ha! Ihr hattet wohl Recht. Dieser zerbrochene Dreizack scheint Euch gute Dienste zu leisten. Ich schätze, ich werde heute nicht zu sehen bekommen, wie Ihr etwas mit bloßen Klauen zu Tode reißt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25620] = {title = "Die ehrwürdige Lady", objective = "Sprecht mit Lady Naz'jar am nördlichen Ende der Gärten von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Die ehrwürdige Lady sendet Euch eine Botschaft. Sie erwartet Euch auf der anderen Seite der Tempelgärten.\n\nWenn Ihr das Bedürfnis verspürt, die heldenhaften Taten Eures treuen Waffenbruders Azjentus zu erwähnen, bitte, tut Euch keinen Zwang an. Ich werde Eure Bewunderung für mich nicht als Schwäche auslegen.\n\nDoch jetzt halte ich Euch nicht länger auf. Die Dame wartet.", progress = nil, completion = "Ah, meine Kriegsmaid, da seid Ihr ja. Die Kriegerkaste spricht nur noch von Euren Siegen auf dem Schlachtfeld. Und das, wo wir unsere Bemühungen, die Stadt einzunehmen, doch gerade erst begonnen haben.\n\nIhr habt mir bisher treu gedient und mich mit Stolz erfüllt. Möge die Königin Euch ihre Gunst gewähren, damit dies auch in Zukunft so sei.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25621] = {title = "Feldversuch: Gnomcorder", objective = "Begebt Euch ins Steinkrallengebirge und geht den Steinkrallenpass Richtung Süden entlang, bis Ihr die große Goblinbohrmaschine findet.", description = "Die Gnomcordär ist fertisch! Jetzt wir müssen machen eine Test!\n\nIhr müsst ge'en nach die Steinkrallengebirge in die Südenosten und ge'en über die Steinkrallenpass bis zu die dreckische Goblinbohrmaschin'. Isch werde aktivieren die Gnomcordär wenn Ihr 'abt erreischt Eure Ziel!Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nGnomcorder\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25622] = {title = "Burn, Baby, Burn!", objective = "Bringt einen Flammenwerfer des Kriegshymnenklans von einem Verbrenner von Krom'gar an Euch und benutzt ihn, um 8 Vorräte des Kriegshymnenklans zu zerstören.", description = "Diese Verbrennär von die Orcs 'aben schlimme Waffen um zu brennen die Wald niedär! Ihr müsst sie töten und nehmen die Flammenwerfär. Wenn Ihr 'abt die Flammenwerfär, Ihr müsst suchen nach die Vorräte von die Kriegs'ymnenklan und benutzen die Flammenwerfär für abzufackeln!\n\nVerbrennt sie alle und isch werde Eusch belohnen! Ja, die Gnomcordär kann transportieren Dinge.\n\nWartet! 'ört Ihr das? Isch glaube, eine Orc is in die Näh'! Vorsischt!", progress = nil, completion = "&lt;Der Gnomcorder summt laut.&gt;\n\nWunderbar. Wie versprochen - VOILA, 'ier ist Belohnung für Eusch!\n\nJetzt isch 'aben eine Neuigkeit, die Ihr könntet finden interessant.", rewards = "Gyromatische AxtXakxaks LaborkittelVundervolle ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25623] = {title = "In den Schlund!", objective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", description = "<Name>, da seid Ihr ja! Goldrinn hat eine Aufgabe, die nur sein Champion erfüllen kann. Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Wir wissen nicht, wohin es führt, aber Goldrinn kann es nicht betreten. Der Ahn möchte, dass Ihr seine Klauen und Zähne seid.\n\nTretet durch das Flammentor und sprecht auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr Goldrinns Macht in diesem Reich nutzen könnt. Findet heraus, wohin das Flammentor führt!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGoldrinns Fangzahn"}
MultiLanguageQuestData['de'][25624] = {title = "In den Schlund!", objective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", description = "<Name>! Lo'Gosh braucht Euch. Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Wir wissen nicht, wohin es führt, aber keiner, der es betreten hat, ist je zurückgekommen. Lo'Gosh möchte, dass Ihr hindurchgeht und seine Klauen und Zähne seid.\n\nTretet durch das Flammentor und sprecht auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr Lo'Goshs Macht in diesem Reich nutzen könnt. Findet heraus, wohin das Flammentor führt!", progress = nil, completion = "Ah, Ihr seid also der Champion, so wie Lo'Gosh es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Allianz auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Lo'Goshs Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", rewards = "Ihr bekommt:\n\nFangzahn von Lo'Gosh"}
MultiLanguageQuestData['de'][25626] = {title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", objective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", progress = nil, completion = "Diener des alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n&lt;Name&gt;, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", rewards = "Volarens HandschützerPerlmuttschiftungAuf Euch wartet eine dieser Belohnungen:\n\nSmaragdener LeierfischhalsreifSiegelring von Quel'Dormir\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25627] = {title = "Abreibung für Zweihauer", objective = "Erhaltet den rostigen Käfigschlüssel.", description = "Diese Schätze sind alle nicht echt, aber die Knüppler im Unterschlupf werden den Unterschied nicht erkennen, so blöd, wie Oger sind!\n\nHier ist der Plan: Ihr begebt Euch in den Admiralsunterschlupf und verteilt diese \"Schätze\" an alle Oger, die Euch über den Weg laufen. Dann müsst Ihr Euch nur noch um Tony Zweihauer kümmern.\n\nSo bekommt Ihr den Schlüssel zum Käfig in null Komma nichts!", progress = "Was ist hier los? Holt Ihr mich hier raus?", completion = "Ja, ja... sicherlich war Euer kleines Abenteuer in die Höhle sehr interessant.\n\nWarum unterhalten wir uns nicht bei einem Drink auf dem Turbodampfer in Ruhe darüber, wenn Ihr es noch schafft, mich hier rauszulassen?", rewards = "Schwimmfähige SchulterpolsterWizzels GelenkbänderHöhlenknüpplerstiefelArmschienen des TrinkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25628] = {title = "Abreibung für Zweihauer", objective = "Erhaltet den rostigen Käfigschlüssel.", description = "Diese Schätze sind alle nicht echt, aber die Knüppler im Unterschlupf werden den Unterschied nicht erkennen, so blöd, wie Oger sind!\n\nHier ist der Plan: Ihr begebt Euch in den Admiralsunterschlupf und verteilt diese \"Schätze\" an alle Oger, die Euch über den Weg laufen. Dann müsst Ihr Euch nur noch um Tony Zweihauer kümmern.\n\nSo bekommt Ihr den Schlüssel zum Käfig in null Komma nichts!", progress = "Was ist hier los? Holt Ihr mich hier raus?", completion = "Ja, ja... sicherlich war Euer kleines Abenteuer in die Höhle sehr interessant.\n\nWarum unterhalten wir uns nicht bei einem Drink auf dem Turbodampfer in Ruhe darüber, wenn Ihr es noch schafft, mich hier rauszulassen?", rewards = "Schwimmfähige SchulterpolsterFlämmers GelenkbänderHöhlenknüpplerstiefelArmschienen des TrinkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25629] = {title = "Die Hand der Lady", objective = "Besiegt die Gegner von 8 Mitgliedern der Ehrenwache der Naz'jar und übergebt ihnen ihre neuen Befehle.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Kriegsmaid!\n\nSucht nach meiner Ehrenwache auf dem Schlachtfeld und nehmt ihnen ihre Feinde ab. Sie müssen sofort zurückkehren, um die Priesterinnen zu beschützen.\n\nIch kümmere mich um den Eingang. Beeilt Euch!", progress = "Als die Kämpfe ausbrachen, habe ich meine Ehrenwache losgeschickt. Sie sind besser ausgerüstet, um mit dem Chaos dieser Schlacht umzugehen und ich bedarf kaum ihrer Hilfe.", completion = "Gut gemacht, Kriegsmaid.\n\nIch sehe nach der östlichen Brücke. Ihr müsst Euch um den Tempel kümmern. Das Ritual darf nicht unterbrochen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25630] = {title = "Die Feuer des Hyjal", objective = "Sprecht mit Laina Nachthimmel in der Nähe des Hains von Aessina auf dem Hyjal.", description = "Seht Ihr das, <Name>? Vom Bergrücken südwestlich von hier… steigen Schwaden schwarzen Rauchs in den Himmel auf.\n\nDer Hyjal brennt.\n\nWenn die Feuer schon so hoch oben am Berg angekommen sind, bedrohen sie sicher auch den Hain von Aessina und unsere Streitkräfte dort.\n\nSprecht mit Laina Nachthimmel in der Nähe des Hains von Aessina. Als ich zuletzt von ihr hörte, bemühte sie sich, den Angriff abzuwehren.", progress = nil, completion = "Kann das warten, &lt;Klasse&gt;? Die Schlacht steht schlecht für uns.\n\nOh, Ihr seid hier, um zu helfen. Ich hoffe, Ihr mögt es heiß…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25637] = {title = "Auf den Ruf des Tiefenlords", objective = "Tötet 16 Kvaldir auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Tiefenlord Zin'jatar hat uns berichtet, dass der Anführer der Kvaldir sich gezeigt hat. Begebt Euch zu ihm. Er befindet sich am gegenüberliegenden Ende der Terrasse über uns, auf der mittleren Ebene der Ruinen: Die Terrasse von Nar'shola.\n\nTötet alle Kvaldir, die Euch im Weg stehen. Wir möchten, dass der Widerhall dieser Niederlage in ihren Köpfen gellt, auf dass sie es nicht wagen, zurückzukehren und unser Vorhaben hier zu stören.\n\nEuer hingebungsvoller Einsatz bleibt nicht unbemerkt, meine Kriegsmaid. Geht und wisst, dass Ihr meinen Segen habt.", progress = nil, completion = "Wie schön, dass Ihr Euch mir anschließt, Kriegsmaid. Kampfgeräusche untermalten Eure Ankunft. Welch süßer Klang in meinen Ohren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25638] = {title = "Eine verzweifelte Bitte", objective = "Bringt die durchnässte Notiz zu Erunak am Tiefgang.\n\nBereitgestellter Gegenstand: \n", description = "Die Nachricht in dieser Flasche ist nass aber immer noch lesbar.\n\nDer Schreiber behauptet, aus einem Nagagefängnis unter dem Meer entkommen zu sein.\n\nEr fürchtet deutlich um sein Leben. Ihr fragt Euch, ob es sich dabei um einen Eurer kürzlich entführten Schiffskameraden handeln könnte.\n\nDa Ihr nicht wisst, wie Ihr den Flüchtling finden sollt, beschließt Ihr, Euren Fund Erunak zu zeigen.", progress = nil, completion = "Wenn sie noch am Leben ist, kann ich diese arme Seele vielleicht finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25640] = {title = "Feuer frei: Scherwindmine!", objective = "Sprecht mit Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", description = "Wir 'aben entdeckt die Ort von die große Goblinbomb', die Ihr 'abt gefunden in Silberwindzuflucht.\n\nIhr Eusch erinnern an Boog? Die Gnom, die Ihr 'abt gerettet von die Orcwagen? Er und Minx 'aben gefunden die Bomb' in die Scherwindmine. Ihr müsst ge'en dort'in toute de suite... sofort, <Name>! Sie werden warten auf Eusch.", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;. Danke für die Rettung in Eschental. Sehr schade um die ganzen Gnome, die wir verloren haben.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25641] = {title = "Muiseknachschub", objective = "Bringt das Gefäß für Hippogryphenmuisek zu Hexendoktor Uzer'i in Camp Mojache in Feralas.", description = "Ich habe alles getan, was ich für Euch tun konnte. Aber ich bin noch nicht mächtig genug, um mit etwas mächtigerem als Hippogryphenmuisek zu arbeiten - vor dem Desaster, das dadurch entstehen könnte, verschone ich Euch zuerst.\n\nWährend Ihr beschäftigt wart, habe ich den Hippogryphenmuisek fertiggestellt. Bringt es zu meinem Meister, dem Hexenmeister Uzer'i in Camp Mojache. Er kann damit mächtige Waffen herstellen und hoffentlich wird er von meinen bisherigen Leistungen beeindruckt sein.", progress = "Ihr kommt mir bekannt vor...", completion = "Gute Arbeit, in der Tat... von meiner eigenen Tochter hätte ich allerdings auch nicht weniger erwartet. Sie wird noch eine gute Hexe werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25642] = {title = "Schaut ihnen nicht in die Augen", objective = "Sammelt 10 Proben azurblaues Eisenerz ein.", description = "Zieht Euren Kopf ein, <Name>. Wir wollen keine ungebetene Aufmerksamkeit auf uns lenken.\n\nAnscheinend beladen die Orcs den Ballon mit irgendeinem Erz aus der Mine. Geht dort hinein und nehmt den Orcs das Erz weg. Bringt mir alles, das ihr tragen könnt und ich werde es zur Untersuchung zum Professor schicken.\n\nBevor Ihr geht noch ein Ratschlag: Ihr könnt die Krom'gar leicht umgehen, weil sie (1) dumm wie Bohnenstroh sind und (2) nichts sehen können, wenn sie Erz tragen. Natürlich müsst Ihr sie töten, um an das Erz zu kommen.", progress = "Bringt mir die Erzproben!", completion = "Ich hoffe, das hat Euch nicht zu viel Mühe bereitet. Mit diesen Proben sollten wir in der Lage sein herauszufinden, was sie mit dem Erz und der großen Bombe vorhaben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25643] = {title = "Die Graunebelruinen", objective = "Sucht in den Graunebelruinen nach dem Amulett, das der Weise Bleichlauf beschrieben hat.", description = "Ich werde von Visionen heimgesucht, <Name>. Visionen eines großen Machtsymbols, das in die Hände eines dunklen Wesens fällt. Ich sehe ein Amulett, von den uralten Elfen gehalten... das in Vergessenheit geraten ist und alles in seiner Umgebung in Ruinen verwandelt, bis die Dämonen es durch Betrug und Bosheit erhalten.\n\nJede Nacht schleichen sich diese Bilder wieder und wieder in meine Träume. Die Geister schicken uns eine Warnung. Ich bin zu alt und die Kriegerhelden des Lagers sind damit beschäftigt, uns zu beschützen. Ich bitte Euch, folgt meinen Visionen in Richtung Süden zu den Graunebelruinen und macht das Amulett ausfindig.", progress = nil, completion = "&lt;Als Ihr Euch dem Podest nähert, merkt Ihr, dass es leer ist. Kälte füllt den Raum und eine leise Stimme ertönt...&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25644] = {title = "Das Zwielichtei", objective = "Bringt das reine Zwielichtei zu Aronus an den Toren von Sothann auf dem Hyjal.\n\nBereitgestellter Gegenstand: \n", description = "Dieses Ei ist anders als alles, was Ihr je gesehen habt. Die durchsichtige Schale scheint das Licht um sie herum zu brechen.\n\nDaneben findet Ihr eine Nachricht, die die Ankunft einer fruchtbaren Brutmutter im Zirkel des Aszendenten beschreibt.\n\nVielleicht solltet Ihr Aronus das hier zeigen.", progress = nil, completion = "Ihr habt richtig gehandelt, mir dies zu bringen, &lt;Name&gt;. Dies ist eine große Bedrohung für uns, der wir uns unverzüglich und furchtlos stellen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25645] = {title = "Kehrt zum Weisen Bleichlauf zurück", objective = "Bringt das Graunebelamulett zum Weisen Bleichlauf.", description = "Das sanfte Leuchten bei dem Podest wird heller und Ihr könnt eine einfache Kette erkennen, die dort zurückgelassen wurde. Das muss das Amulett sein, wegen dem Euch der Weise Bleichlauf hergeschickt hat...", progress = "Ihr seid zurückgekehrt. Was habt Ihr gefunden?", completion = "Ich bin ein Narr... ich wurde in die Irre geleitet. Dies ist nur ein rostiges Stück Schmuck - meine Visionen haben sich zweifellos bewahrheitet.\n\nVergebt mir, &lt;Name&gt;. Ich werde dafür beten, dass Ihr über diese Dämonin siegen werdet, so wie Ihr über Verinias gesiegt habt, solltet Ihr sie jemals wiedertreffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25646] = {title = "Säuberung der Scherwindmine", objective = "Tötet 6 Vorarbeiter der Scherwindmine.", description = "Die Horde hat die Scherwindmine eingenommen. Ich bin nicht sicher, was diese Orcs hier herausschleppen oder warum sie hier sind, aber ich weiß, das kann nichts Gutes bedeuten. Geht dort hinein und schaltet die Führung aus. Ohne die Goblinaufseher werden diese Peons noch nutzloser sein.\n\nWährend Ihr dort drin seid, haltet die Augen offen, ob Ihr noch weitere Informationen findet, was die Horde dort in den Minen treibt.\n\nViel Glück.", progress = nil, completion = "Gute Arbeit, ich konnte ihre schrillen Schreie von hier aus hören! Ihr habt den ganzen Ort auf den Kopf gestellt!\n\nHabt Ihr noch weitere Informationen über die Vorgänge in der Mine gefunden?", rewards = "Leise PantoffelnAufseherhandschuheAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der schrillen SchreieHelianas Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25647] = {title = "Unleserlicher Orcbrief", objective = "Bringt den unleserlichen Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", description = "Ihr habt ein Pergament mit einem beeindruckenden Hordensiegel darauf gefunden. Leider ist der Rest des Dokuments vollkommen unverständlich, weil es auf Orcisch ist.\n\nBringt den Brief zu Boog. Vielleicht weiß er etwas damit anzufangen!", progress = "Was habt Ihr da für mich?", completion = "&lt;Boog nimmt Euch den Brief ab und studiert ihn.&gt;\n\nInteressant.\n\n&lt;Boog riecht an dem Pergament.&gt;\n\nHrm... Beunruhigend...\n\n&lt;Boog faltet das Papier auf der Hälfte und schaut Euch an.&gt;\n\nIch verstehe absolut gar nichts von dem, was da geschrieben steht - wenn es überhaupt geschrieben ist. Könnte auch Klopapier sein. Riecht auf jeden Fall so.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25648] = {title = "Jenseits von Durotar", objective = "Meldet Euch bei Ag'tor Blutfaust am Hinteren Tor von Orgrimmar in Azshara.", description = "Hmpfff ... Eure Dienste werden anscheinend anderswo benötigt. Ag'tor Blutfaust sucht nach Rekruten, die die Unternehmungen der Horde in Azshara nördlich von Orgrimmar unterstützen.\n\nIhr habt sicherlich noch Arbeit hier in Durotar und ich hörte, dass man Euch bald um Hilfe im Brachland bitten wird. Also ich an Eurer Stelle würde nirgendwo hingehen, aber wenn Ihr unbedingt das Schicksal herausfordern wollt... Azshara wartet.", progress = nil, completion = "Gut, Ihr seid hier. Willkommen in Azshara, der Bühne für den nächsten Akt der ruhmreichen Zukunft der Horde. Und jetzt an die Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25649] = {title = "Minx wird's schon richten", objective = "Bringt den unleserlichen Orcbrief zu Minx in der Scherwindmine im Steinkrallengebirge.", description = "Die gute Nachricht ist, dass Minx fließend Orcisch spricht und sie ist in der Nähe. Geht zurück in die Mine und findet sie. Sie ist wahrscheinlich etwas tiefer in der Mine und steht nutzlos herum.\n\nVergesst das Pergament nicht.", progress = "Was habt Ihr da für mich?", completion = "&lt;Minx nimmt Euch den Brief ab und studiert ihn.&gt;\n\nOha.\n\n&lt;Minx riecht an dem Pergament.&gt;\n\nIst ja widerlich!\n\n&lt;Minx faltet das Papier auf der Hälfte und schaut Euch an.&gt;\n\nDie gute Nachricht ist - es ist kein Klopapier. Die schlechte Nachricht ist, dass die Tinte auf diesem Papier eine Mischung aus Kododung und Blut ist. Und das ist noch nicht das Schlimmste...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25650] = {title = "Befehle des Oberkommandos", objective = "Bringt den übersetzten Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", description = "Bei dem Brief handelt es sich um Befehle des Hordenoberkommandos. Jemand mit Namen Oberanführer Krom'gar hat angeordnet, dass diese Mine \"ausgeräumt\" werden soll, um einen Splitter von etwas zu erhalten, das \"azurblaues Eisenerz\" heißt. Wahrscheinlich erhält man diesen Splitter, wenn man das Erz abbaut.\n\nEs wird noch schlimmer. Sie haben vor, diesen azurblauen Splitter mit Sprengstoffen in der riesigen Bombe zu vermischen und dann die Scherwindfeste in die Luft zu jagen.\n\nWir dürfen keine Zeit mehr verlieren, <Name>! Nehmt diese Übersetzung des Briefs und kehrt zu Boog zurück! Er wird wissen, was als Nächstes zu tun ist.", progress = "Nun? Was steht da?", completion = "&lt;Schweißperlen laufen Boog über die viel zu große Stirn, während er den übersetzten Brief liest.&gt;\n\nDas ist übel. Richtig, richtig übel. Ihr müsst Lord Brachweiher in der Scherwindfeste warnen.\n\nWas zur…? Er BEWEGT sich! Der Goblinballon hebt ab! Wir kommen zu spät!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25651] = {title = "Oh süßer Wahnsinn!", objective = "Sammelt 50 gestohlene Kanonenkugeln auf Gurboggels Fels und von Hamsterern der Gilblin. Benutzt die Kanonenkugeln, um ein Fass mit Schießpulver herzustellen.", description = "Also, ich habe nachgedacht…\n\nWenn jemand total durchgeknallt ist, weiß er das dann?\n\nIch könnte zum Beispiel schwören, dass ich ein Fass mit Schießpulver von den Kanonenkugeln hier gesammelt habe, aber es ist einfach unauffindbar.\n\nIch erinnere mich noch genau daran, wie ich die Kanonenkugeln von den Gilblins westlich von hier stibitzt habe.\n\nVielleicht stimmen die Gerüchte ja... vielleicht habe ich wirklich nicht mehr alle Tassen im Schrank.", progress = "Ihr wollt nichts mit mir zu tun haben, <Volk>.\n\nIch bin ein bisschen… meschugge.", completion = "Mein Schießpulver!\n\nIhr habt es gefunden! Ich bin also doch nicht verrückt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25652] = {title = "Beschlagnahmt den Ballon!", objective = "Fahrt mit dem Heißluftballon von Krom'gar und versucht zu verhindern, dass er die Scherwindfeste zerstört.", description = "Wir dürfen keine Zeit verlieren, <Name>. Ihr müsst diesen Heißluftballon beschlagnahmen und aufhalten!\n\nWie? Keine Ahnung! Wir haben keine Zeit, uns um Details zu streiten! Schnappt Euch die Strickleiter und klettert hinauf! Dann prügelt einfach auf alles ein, wenn Ihr drin seid!\n\nWenn Ihr den Ballon irgendwie anhalten könnt und überlebt, meldet Euch bei Lord Brachweiher in der Scherwindfeste im Westen.\n\nViel Glück, wir alle zählen auf Euch. Wenn Ihr mich jetzt entschuldigen wollt, ich muss um MEIN LEBEN RENNEN!", progress = nil, completion = "Unglaubliche Geschichte, mein Freund. Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich Euch nicht glauben. Ihr habt dem Ballon so viel Schaden zu gefügt, dass Ihr diese Unholde zum Rückzug gezwungen habt! Leider ist die Bedrohung noch längst nicht abgewendet! Wir haben den Angriff nur hinausgezögert. Es gibt noch viel zu tun, wenn wir die Horde davon abhalten wollen, das Steinkrallengebirge zu zerstören!", rewards = "Stab des SteinkrallenverteidigersZauberstab der erkauften ZeitKonfiszierte HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25653] = {title = "Die Ahnen sind mit uns", objective = "Kehrt zu Ysera in Nordrassil auf dem Hyjal zurück.", description = "Nemesis… vernichtet.\n\nIch fühle mich jung.\nMächtig.\nErleuchtet.\n\nSagt Ysera, dass meine Stärke ganz ihr gehört.\n\nDer Schattenhammer wird fallen.", progress = nil, completion = "Indem Ihr Tortolla von seiner letzten Last befreit habt, habt Ihr uns einen ausgezeichneten Verbündeten verschafft… und das letzte Stück unseres Plans.\n\nMacht Euch bereit, &lt;Name&gt;. Der schwierigste Teil unserer Reise steht kurz bevor.\n\nWir werden den Kampf in ihre Feste tragen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25654] = {title = "Dunkles Herz", objective = "Tötet Edana Hasskralle und erhaltet Edanas dunkles Herz.", description = "Edana Hasskralle ist die Königin der Harpyien der Nordschwingen, die in den Ruinen westlich von hier leben. Es ist ihr bösartiger Wille, der die Harpyien dazu anregt, ihre Nester inmitten der Ruinen unseres Volkes zu verteidigen.\n\nDie Harpyien können sie mit einem speziellen Horn rufen. Wenn man das Horn bei den Hasskrallensteinen im nördlichen Teil der Ruinen bläst, so erscheint Edana.\n\nZeigt diesen garstigen Kreaturen keine Gnade. Tötet Edana, und bringt mir ihr dunkles Herz.", progress = "Wir dürfen den Einfall der Harpyien in die Ruinen unserer Vorfahren nicht einfach hinnehmen.", completion = "Diese Länder werden endlich von der Bosheit der Harpyien befreit sein. Ich kann Euch nicht genug danken.", rewards = "Dunkles KristallhüftbandArmschienen des eroberten HerzensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25655] = {title = "Das Wurmschwingenproblem", objective = "Tötet 10 Harpyien der Wurmschwingen (Kreischerinnen oder Schnellklauen).", description = "Himmelsfürst Omnuron war viel zu nachgiebig mit den Harpyien der Wurmschwingen und hat ihnen sogar gestattet, sich auf diesem Berg niederzulassen. Einfach nur, weil es Wesen der Luft sind. Nun, <Klasse>, nicht alle Wesen der Luft sind gleichrangig.\n\nAls die Angriffe auf den Hyjal begannen, verfielen die Wurmschwingen in Raserei. Sie sind direkt dort oben und greifen einen heiligen Schrein an, den sie einst verehrten.\n\nAber kein Grund zur Klage. Schließlich haben wir jetzt einen Grund, sie vom Hyjal zu vertreiben, oder?", progress = nil, completion = "&lt;Thisalee nickt zufrieden und ihre Augen leuchten.&gt;\n\nEs ist großartig, nicht mehr an der kurzen Leine gehalten zu werden, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25656] = {title = "Augen auf beim Eierklau", objective = "Sammelt 8 Hyjaleier.", description = "Hinter diesen Angriffen der Wurmschwingen steckt ein Muster. Während einige Gruppen einen aufsehenerregenden Angriff auf den Schrein selbst durchführen, durchforsten andere die Nester in der Nähe und machen sich mit den Eiern aller fliegenden Wesen des Hyjal aus dem Staub.\n\nDiese Tiere stehen unter unserem Schutz. Bis wir herausgefunden haben, warum die Wurmschwingen das tun, müssen wir so viele Eier wie möglich vor ihren Klauen retten.", progress = "<Thisalee säubert ihre Fingernägel mit einem Dolch. Sie schaut Euch erwartungsvoll an.>", completion = "Gut, das ist zumindest ein Anfang.\n\nDie Vögel, die diese Eier gelegt haben, werden sie nicht wieder annehmen. Wir werden die Küken als Waisen im Schrein aufziehen müssen. Wenn Aviana hier wäre, hätte sie diese Schandtat nie zugelassen.\n\nAber zurück zum Geschäft...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25657] = {title = "Da dap… Da dap...", objective = "Budd möchte, dass Ihr den präparierten Köder bei der rostigen Harpunenkanone im Skelettriff benutzt.", description = "Da Ihr so nett zu mir wart, werde ich Euch in ein ganz besonderes Geheimnis einweihen.\n\nIch habe den größten Glitzerkram von allen gefunden, keine 50 Schritt von uns entfernt!\n\nNur eines steht noch zwischen Euch, mir und einem großen Vermögen, und das ist Nager.\n\nAber keine Sorge, ich habe einen Plan.\n\nNager liebt Maden, also habe ich eine davon mit Schießpulver gefüllt, als Falle sozusagen. Versteht Ihr?\n\nLasst sie einfach im Riff vor sich hin treiben. Sobald der Hai tot ist, sind wir reich!", progress = nil, completion = "Beeindruckend!\n\nDa beobachtet man, wie die große weiße Bestie in die Tiefen davon schwimmt und fragt sich, ob es irgendetwas gibt, das ihn erledigen kann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25658] = {title = "Für die Ewigkeit gebaut", objective = "Reaktiviert 6 Barrieren von Nar'shola.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Herrin, ich habe eine Bitte der Hohepriesterin, die ich an Euch weitergeben soll. Viele der Verteidigungsanlagen der Stadt stammen noch aus der Zeit, lange bevor sie in den Wellen versank. Sie erneut zu aktivieren ist nicht schwer, wären da nicht die zahllosen Kvaldir, die uns im Weg sind.\n\nEs wurde uns berichtet, dass Ihr oben auf der Terrasse von Nar'shola kämpfen werdet. Ihr würdet meiner Herrin einen großen Dienst erweisen, wenn Ihr im Vorbeigehen diese Geräte einfach berühren könntet. Euer edles Geblüt sollte mehr als ausreichen, um sie zu reaktivieren.", progress = "Die Hohepriesterin sendet Euch ihren Dank für Eure Hilfe bei unseren Pflichten.", completion = "Die Barrieren von Nar'shola funktionieren einwandfrei. Ich werde die Herrin der Gezeiten sofort über Eure Hilfe informieren.\n\nVielen Dank, edle Dame.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25659] = {title = "Unvergesslich", objective = "Tötet Varkul den Unerbittlichen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Der Anführer der Kvaldir hat sein verrottendes, hässliches Gesicht nicht weit von hier den westlichen Gang entlang gezeigt. Wenn wir ihn jetzt töten, findet die Belagerung unserer geliebten Stadt durch die Kvaldir endlich ein Ende.\n\nVorsicht, Kriegsmaid, denn er ist alles andere als ein Schwächling. Es stehen viele Kvaldir unter seinem Befehl. Einige Meerhexen der Sira'kess wurden losgeschickt, um ihn während Eures Angriffs zu schwächen, aber wenn Ihr zulasst, dass seine Kvaldir sie angreifen, werden sie unterbrochen.\n\nZeigt keine Gnade, Kriegsmaid.", progress = nil, completion = "&lt;Der General der Kvaldir bricht besiegt zusammen.&gt;\n\n&lt;Damit hat Lady Naz'jar die Ruinen von Vashj'ir erobert. Ihre eigentlichen Ziele kennt Ihr nicht, aber es ist klar, dass die Naga aus einem bestimmten Grund hierhergekommen sind.&gt;\n\n&lt;Ihr seid Euch sicher, dass der Schlüssel zum Sieg über die Naga in dieser Vision liegt. Wenn Ihr weitermachen könntet, würdet Ihr sicher die Antworten finden, aber die Magie der Wellensprecherin wird schwächer und Ihr verliert die Verbindung zur Kriegsmaid.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBattlemaiden Vision 1 Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25660] = {title = "Verfolgt", objective = "Sprecht mit Ajamon Geistrufer in Südmeerstützpunkt in Tausend Nadeln.", description = "Ihr meint wohl, ich lasse Euch für meinen Tod einfach so gehen, hm? Sicherlich nicht! Ich habe mein Piratenhandelsimperium mit nichts nicht aufgebaut, um Euch dabei zuzusehen, wie Ihr mich tötet.\n\nIhr werdet mir dabei helfen, wieder zum Leben zu finden. Findet meine Exfrau Ajamon im Norden des Stützpunkts. Immer der Nase nach - sie wird mit Sicherheit bei dem stinkenden Kessel sein.", progress = nil, completion = "Was wollt Ihr denn? Oh nein, ganz sicher nicht. Ich sehe, dass Ihr Tonys Geist bei Euch habt, und damit will ich wirklich nichts zu tun haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25661] = {title = "Mit ein bisschen Hilfe...", objective = "Erhaltet Gruseldollys Herz, Seebär Fajardos Lungen und Lilly Landrattes Leber.", description = "Nun gut, ich werd' Euch helfen. So leicht wird er nicht darum kommen, mir Alimente zu zahlen! Un' außerdem muss er sich ja bald auch noch um das Kind kümmern, das er mit meiner Schwester zeugen musste!\n\nZuers' brauchen wir die Innereien seiner besten Freunde; das sind wohl die Kapitäne.\n\nGeht und stattet den drei einen Besuch ab.", progress = "Wir brauchen ein frisches Herz, Lungen, und eine Leber. Die von seinen Kapitänen werden wohl ausreichen müssen, obwohl sie sicher nicht die frischsten sind.", completion = "&lt;Ajamon verzieht ihr Gesicht, als sie sieht, in welchem Zustand die Organe sind.&gt;\n\nEs geht wohl nicht anders. Ist ja nicht so, als hätte er viele Freunde gehabt. Nicht wahr, Zweihauer?", rewards = "Gruseldollys ManschettenLillys KopftuchFajardos ArmschienenDickköpfiger HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25662] = {title = "Befreit unsere Schwestern", objective = "Bringt 5 Käfigschlüssel der Horde an Euch, um 5 gefangene Jägerinnen freizulassen.", description = "Gestern Morgen habe ich eine Schwadron Jägerinnen auf eine Mission zur Scherwindklippe geschickt, damit sie Informationen über die Bewegungen der Horde im Steinkrallengebirge beschaffen. Nach Geheimdienstinformationen sind sie alle gefangen genommen worden, einschließlich der Schwadronsführerin, Jägerin Illiona.\n\nGeht nach Osten zur Scherwindklippe und tötet Infanteristen von Krom'gar, die die Klippe eingenommen haben. Nehmt ihnen die Schlüssel ab, mit denen man die Hordenkäfige, in denen unsere Schwestern sitzen, öffnen kann.\n\nTut Euer Bestes, um Illiona zu finden, sobald Ihr die Jägerinnen befreit habt.", progress = nil, completion = "Wir haben nicht viel Zeit. Um mich hier herauszuholen, müsst Ihr Kriegsfürst Roktrog ausschalten. Er hat den Schlüssel für dieses Gefängnis.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25663] = {title = "Eine Gabe für Aviana", objective = "Benutzt den heiligen Nektar an Avianas Grabkreis.", description = "Obwohl die Wächterin aller geflügelten Wesen nicht mehr körperlich unter uns weilt, höre ich sie manchmal in den rauschenden Blättern flüstern.\n\n<Name>, wir verlangen viel von Euch, um diesen Berg zu beschützen. Doch bevor Ihr weitermacht, nehmt Euch einen Augenblick Zeit für die Andacht.\n\nBringt diese Nektargabe zu Avianas Grabkreis, einem Steinkreis direkt jenseits des Haupteingangs zum Schrein. Vielleicht helfen ein paar Augenblicke alleine mit der Erinnerung an Aviana Euch dabei, Euren Geist zu schärfen.", progress = "<Der Geist erscheint immer wieder in Eurer Vision und verschwindet gleich darauf, als ob er hier und gleichzeitig woanders wäre.>", completion = "&lt;Ein geflüstertes Flehen ertönt in Eurem Kopf.&gt;\n\nWieder geboren zu werden, aber in Dunkelheit…\n\nIch wurde geraubt.\n\n&lt;Der Geist scheint aufgewühlt, wird jedoch stumm, als das Bild wieder schwindet.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25664] = {title = "Ein Gebet und ein Flügel", objective = "Benutzt den riesigen Vogellockruf an einem von Blaithes Nestern oben am Rand der Welt. Tötet Blaithe und sammelt eine seiner uralten Federn.", description = "Ein Gesicht mit Schwingen? Kann es etwa sein…?\n\n<Name>, wir haben keine Zeit zu verlieren. Vielleicht habt Ihr mit Aviana selbst gesprochen, die versucht, zu uns zurückzukehren.\n\nIch benötige etwas aus Avianas Vergangenheit, um mit ihr Kontakt aufnehmen zu können. Hoch oben auf dem Gebirgskamm, der diesen Schrein überblickt, findet Ihr eine Reihe von riesigen Nestern. Sie gehören Blaithe, einem uralten Raubvogel, der einst ihr Gefährte war. Seit zehntausend Jahren vergeht er vor Kummer und hat dadurch seinen Verstand verloren.\n\nKlettert auf einen seiner Horste und benutzt diesen Lockruf, um ihn herbeizurufen. Tötet Blaithe und bringt mir eine seiner Federn.", progress = "Habt kein schlechtes Gewissen wegen Blaithes Verfassung. Der Kummer hat diesem Wesen vor Jahrhunderten die Seele geraubt. Er war nur noch ein Schatten seiner selbst, eine Bestie voll zügellosen Zorns.", completion = "Das war keine schöne Aufgabe, &lt;Name&gt;, aber sie musste erledigt werden.\n\nWenn Aviana wirklich wieder zum Leben erweckt werden kann, kann Blaithe vielleicht eines Tages Dank Eurer Taten auch zurückkehren.\n\nUnd jetzt lasst uns sehen, ob wir mit unserer lange verlorenen Wächterin Kontakt aufnehmen können.", rewards = "HerzensmalmergroßhammerHandgelenksschützer der TrauerseeleSchulterpolster der toten ErinnerungenDer folgende Zauber wird auf euch gewirkt:\n\nCompelling Vision\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25665] = {title = "Ein Gesuch aus dem Jenseits", objective = "Kehrt zu Choluna im Schrein von Aviana auf dem Hyjal zurück.", description = "<Ihr versteht nicht, worum der Geist Euch so dringend anfleht, aber vielleicht kann Choluna ja herausfinden, was hier vor sich geht.>\n\n<Sprecht mit Choluna innerhalb des Schreins!>", progress = nil, completion = "Langsam, &lt;Klasse&gt;! Ihr seht aus, als hättet Ihr einen Geist gesehen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25666] = {title = "Macht Euch die Hände schmutzig", objective = "Sammelt 5 schmierige Madeneingeweide von gigantischen Meeresraupen in der Nähe von Harrisons Ausgrabung.", description = "Lasst Euch nicht täuschen, <Volk>. Dieser Hai ist ganz schön gewitzt. Man überlebt hier unten nicht so lange, wenn man nicht das gewisse Etwas an Grips hat.\n\nIch will damit nur sagen, dass er sich sicher nicht so leicht reinlegen lässt. Wir müssen unseren Ansatz ein wenig überdenken.\n\nIch werde Euch jetzt noch nicht mit Details langweilen. Sammelt zunächst ein paar Innereien von diesen gigantischen Meeresraupen.\n\nMeint Ihr, Ihr schafft das?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25667] = {title = "Die Wendigos erlegen", objective = "Tötet 10 Wendigos im Graufelsbau. Ihr könnt Wendigos oder junge Wendigos töten.", description = "Die Wendigos im Graufelsbau südwestlich der Stadt sind uns schon lange ein Dorn im Auge. Ihre Kraft reicht zwar nicht aus, Kharanos direkt zu bedrohen, aber sie stellen Reisenden, Gebirgsjägerpatrouillen und Nachschubtransporten nach.\n\nIch werde meine Beobachter aus dem Graufelsbau abziehen, da ich sie an der Trollfront brauche. Würde es Euch etwas ausmachen, meinen Leuten bei der Verkleinerung des Wendigobestands zu helfen? Wenn sie nicht mehr so viele sind, können sie uns nicht länger angreifen.", progress = nil, completion = "Jetzt, da Ihr Euch um die Wendigos gekümmert habt, können wir unsere Bemühungen auf die Trolle der Frostmähnen im Osten konzentrieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25668] = {title = "Gestohlene Vorräte", objective = "Bergt 6 gestohlene Versorgungsgüter aus dem Graufelsbau.", description = "Die Frostmähnen machen im Osten Ärger und die Wendigos spüren unsere Schwäche und werden mit ihren Überfällen immer dreister. Nur einer von vier Nachschubkarren ist in letzter Zeit hier sicher angekommen. Die Wendigos haben sich mit dem Rest davongemacht und bewahren alles im Graufelsbau, einer Höhle südwestlich von hier, auf. Wenn Ihr bereit seid, dorthin zu gehen und die gestohlenen Vorräte wiederzubeschaffen, wären Euch alle Einwohner der Stadt und die Gebirgsjäger, die Kharanos verteidigen, zutiefst dankbar.", progress = "Habt Ihr etwas von den vermissten Vorräten gefunden?", completion = "Gut gemacht, &lt;Name&gt;. Die Gebirgsjäger werden froh sein zu hören, dass die halben Rationen der Vergangenheit angehören. Sie benötigen all ihre Kräfte, um gegen die Frostmähnen zu kämpfen.", rewards = "GraufelsbaustiefelWendigogamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25669] = {title = "Es rappelt im Säge... Werk", objective = "Tötet Kriegsfürst Roktrog und befreit Jägerin Illiona, indem Ihr Jägerin Illionas Käfigschlüssel benutzt.", description = "Seid bereit, <Name>! Der Kriegsfürst kommt! Tötet ihn und nehmt seinen Schlüssel an Euch. Benutzt diesen Schlüssel, um mich freizulassen.\n\nWenn wir es hier heraus schaffen, meldet das Folgende bei Lord Brachweiher in der Scherwindfeste:\n\nDie Horde hat ihre Pläne, die Scherwindfeste zu zerstören, dank der Taten eines unserer Helden abgebrochen. Jetzt beabsichtigen sie, die Bombe zum Kriegsnarbental zu bringen und auf unsere Armeen abzuwerfen, die dort gegen die Horde kämpfen.\n\nSie müssen aufgehalten werden!", progress = nil, completion = "Ein Held hat also ihre Pläne vereitelt, die Scherwindfeste zu zerstören, huh? Der Held wart Ihr, &lt;Name&gt;. Ihr seid der Stolz der Allianz!\n\nAnscheinend habt Ihr uns allen ein wenig Zeit verschafft. Ich muss Pläne schmieden für den Kampf, der vor uns liegt. Geht zu den anderen Einwohnern der Scherwindfeste und bietet ihnen Eure Dienste an. Ich werde Euch rufen, wenn ich bereit bin, unsere Verteidigungsstrategie ins Leben zu rufen.", rewards = "Stiefel des VereitlersScherwindaxtAuf Euch wartet eine dieser Belohnungen:\n\nLösungsbuch\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25670] = {title = "DA-dap-DA-dap-DA-dap", objective = "Benutzt Budds Kette bei der rostigen Harpunenkanone im Skelettriff. Feuert die Harpune ab, wenn Nager sich über der Kanone befindet.", description = "Der alte Nager ist uns jetzt sicher auf den Fersen.\n\nZu Eurem Glück denke ich wie ein Hai.\n\nNager kocht vor Zorn und wir werden das zu unserem Vorteil nutzen.\n\nHier, ich habe auf meiner Schatzjagd diese Kette gefunden. Bindet sie an die Harpunenkanone.\n\nWenn Nager Euch sieht, wird er bestimmt vor Wut überschnappen. Und dann schlagen wir zu!\n\nIhr versucht, ihn alle zu machen und ich schleiche mich währenddessen dort hinein und schnappe mir den Glitzerkram.\n\nSchnell, <Klasse>, bevor seine Zähne wieder nachwachsen!", progress = nil, completion = "Es ist wirklich nicht so schlimm, wie es aussieht…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25671] = {title = "Die Horde ausdünnen", objective = "Tötet 20 beliebige Soldaten der Horde im Steinkrallengebirge.", description = "Die Zahl der Horde wächst, da Verstärkung aus dem Eschental und aus Azshara eintrifft. Diplomatie bringt bei diesen Unholden nichts. Das ist Höllschreis Horde und Höllschreis Horde will unser Blut! Wir werden nicht untätig herumsitzen und zulassen, dass sie unser Land einnehmen und unsere Leute töten. Wir müssen handeln!\n\nWir müssen die Horde ausdünnen! Betrachtet das als Eure tägliche Pflicht.\n\nGeht hinaus ins Steinkrallengebirge und tötet so viele Hordemitglieder, wie Ihr könnt. Zeigt ihnen, dass die Allianz sich nicht ergeben wird!", progress = nil, completion = "Gut. Ihr Blut klebt an Höllschreis Händen. Schickt genug von ihnen in Leichensäcken zurück nach Orgrimmar und die Bevölkerung der Horde wird vielleicht reagieren.\n\n&lt;Lord Brachweiher lacht.&gt;\n\nWem will ich etwas vormachen? Sie sind Monster!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25672] = {title = "Kadaversammlung", objective = "Sammelt 10 Kreaturenkadaver.", description = "Diese Organe hier sind schon mal ein guter Anfang, aber wir brauchen echt noch viel mehr anderes Zeugs. Normalerweise könnte man von der Familie was nehmen, aber es sind nur noch ich und Tony, der Sohn meiner Schwester übrig, und er ist es echt nicht wert!\n\nWir müssen also 'n Ersatz finden - 'ne Menge Kadaver, um genau zu sein!\n\nUnten in der Schimmernden Tiefe sind tonnenweise welche zu finden; die sind da, seit das Wasser alles überflutet hat. Hat alle Kreaturen dort getötet, das Wasser. Geht dorthin und bringt mir ein paar der Kadaver.", progress = "Mensch, Ihr müsst mir end viele von den Kadavern bringen! Sonst werden wir seinen törichten Geist nie loswerden!", completion = "Oh, das is' widerlich!\n\nAber wenigstens haben wir's bald. Nur noch eine Kleinigkeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25673] = {title = "Einfach Alice fragen", objective = "Findet die BD-816 Kriegsmaschine, mechanisiertes Feuer, mechanisiertes Eis und mechanisierte Luft.", description = "Herr Baunzer ist krank, <Onkel/Tante>. Kannst du ihm helfen? Du musst nur seinen Hut und seine Batterien finden, dann wird es ihm viel besser gehen. Ich würde sie ja selbst holen, aber ich kann Herrn Baunzer nicht alleine lassen!\n\nSein Hut wurde von den fiesen Typen der Venture Co. drüben am Wasserrad gestohlen und seine Batterien sind irgendwo in der Scherwindklippe versteckt. Du musst nur sehr gründlich nach ihnen suchen.\n\nWürdest du freundlicherweise Herrn Baunzers Sachen zurückholen, damit er den Fieslingen in der Horde eine Lektion erteilen kann?", progress = "Herr Baunzer ist so traurig. Wir müssen ihn glücklich machen!", completion = "&lt;Alice klatscht aufgeregt in die Hände.&gt;\n\nHerr Baunzer, alles wird wieder gut! Hurrah!\n\n&lt;Alice setzt fachmännisch alle Teile, die Ihr eingesammelt habt, in Baunzer ein.&gt;\n\nOh, Herr Baunzer! Ich wusste es!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25674] = {title = "Vergebener Stolz", objective = "Tötet einen Wegelagerer der Schreckensfelsoger in der Feste Schreckensfels.", description = "Dies hier ist eigentlich eine alte Orcstadt... eine der ältesten in Azeroth. Also, das war sie - bis die Oger uns hinausgedrängt haben.\n\nDie heutige Horde weigert sich, von Ogern besiegt zu werden. Meine Truppen und ich haben die Stadt mit Gewalt eingenommen und die Oger, die einmal hier gelebt haben, arbeiten jetzt als Sklaven. Jetzt fängt die Arbeit erst richtig an.\n\nIhr seht stark genug aus, aber ich will Beweise. Tötet einen der Oger, die uns immer noch belagern und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;. Ihr habt bewiesen, dass Ihr einen Oger niederstrecken könnt...eine beachtliche Leistung. Jetzt lasst uns doch mal sehen, ob Ihr eine Eisenmine der Allianz ebenfalls ausschalten könnt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25675] = {title = "Ogergefechte", objective = "Tötet 6 Raufer der Schreckensfelsoger und 5 Hexenmeister der Schreckensfelsoger.", description = "Ich habe Eure Handschrift da unten gesehen, <Volk>. Wie würde es Euch gefallen, noch weitere Oger zu jagen?\n\nWir haben nur diejenigen versklavt, derer wir habhaft werden konnten. Die meisten starken Oger brüten immer noch im Schreckensfelsposten und planen unser Ableben. Unsere Wachen können vereinzelte Angriffe aus dem Hinterhalt abwehren, aber wir haben uns noch nicht gut genug verschanzt und würden unter einem gut geführten Angriff schnell zusammenbrechen.\n\nGeht nach Süden zum Schreckensfelsposten und überbringt eine Nachricht, <Name>. Tötet die stärksten Oger, bevor sie auf dumme Gedanken kommen.", progress = nil, completion = "Ihr habt Eure Sache heute gut gemacht, &lt;Name&gt;. Ihr habt uns nicht nur Zeit bis zum nächsten Ogerangriff verschafft, sondern auch einige der Gefangenen eingeschüchtert, sodass sie jetzt härter arbeiten.", rewards = "Handschuhe der erworbenen ZeitAitokks GürtelStiefel der EinschüchterungSchreckensfelsarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25676] = {title = "Mitten ins Herz", objective = "Meldet Euch bei Rofilian Dane in der Mine von Nethergarde in den Verwüsteten Landen.", description = "Wir haben keine Hoffnung, die Mine von Nethergarde von der Allianz zurückerobern zu können... wenigstens noch nicht. Nethergarde wird gut verteidigt und ihre Nachschubrouten sind bewährt und stark. Unser Ziel ist es daher, ihrer Wirtschaft zu schaden. Wir können die Mine nicht mit Gewalt einnehmen, aber mit präzisen Einschnitten können wir die Wirtschaftlichkeit der Mine stark einschränken.\n\nIch werde dafür sorgen, dass meine Leute vor der Mine ein Ablenkungsmanöver ausführen. Geht nach Osten, schleicht Euch in die Mine und sprecht mit Rofilian Dane über Eure Rolle.", progress = nil, completion = "Endlich lässt sich hier mal ein Verantwortlicher blicken. Ich hoffe, Ihr habt Euch locker gemacht... Zeit für ein kleines Tänzchen, Partner.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25677] = {title = "Alles meins!", objective = "Benutzt das konzentrierte Lösemittel auf 6 Erzhaufen in der Mine von Nethergarde.", description = "Überall in dieser Höhle findet Ihr unbewachte Erzhaufen, die nur darauf warten, dass man an ihnen herumpfuscht. Am liebsten würden wir das Erz natürlich stehlen, aber dazu benötigt man Minenwagen, Schutz und Arbeiter - drei Dinge, die wir nicht haben. Also werden wir stattdessen die Schürfarbeiten mit ein wenig hochgradig ätzender Säure vereiteln.\n\nNehmt diese Flasche - VORSICHTIG - und träufelt den Inhalt auf diese Erzhaufen. Denn wenn wir das Erz nicht haben können, sollen sie es auch nicht haben.", progress = nil, completion = "Es gibt doch nichts Besseres, als einen richtig fetten Tritt in die Geldbörse, nicht wahr, ihr Allianzdummköpfe?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25678] = {title = "Wählt Euer Schicksal", objective = "Tötet 8 Minenarbeiter von Nethergarde, 3 Ingenieure von Nethergarde und 3 Großknechte von Nethergarde.", description = "Es kostet die Allianz ungefähr fünfzig Goldstücke, einen Minenarbeiter auszubilden, zweihundert, um einen Ingenieur auszubilden und dreihundert für einen Vorarbeiter. Jeder Allianzdummkopf, den wir töten ist nicht nur ein militärischer Sieg, es ist auch ein finanzieller Sieg.\n\nJetzt geht dort hinunter und vernichtet ihre Arbeiter!", progress = nil, completion = "Hervorragende Arbeit Mir gefällt, wie Ihr an die Dinge herangeht.", rewards = "Rofilians ArmbänderGürtel der wertlosen LebenStiefel des finanziellen SiegesGeschäftemacherIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25679] = {title = "In den Berg hinein", objective = "Meldet Euch bei Tak'arili tiefer in der Mine von Nethergarde in den Verwüsteten Landen.", description = "Die nächste Phase findet an einem noch tiefer gelegenen Ort in der Mine statt. Sprecht mit Tak'arili für Eure nächste Aufgabe. Folgt einfach den Schienen der Minenwagen nach Südosten um die Kurve herum. Ihr werdet ihn am Eingang zu den höher gelegenen Kammern der Mine sehen.\n\nEs war mir ein Vergnügen, mit Euch Geschäfte zu machen, <Name>", progress = nil, completion = "Gut, Ihr seid schon hier. Bleibt eine Weile, kleiner &lt;Volk&gt;. Wir werden mit der Allianz ein paar Spielchen treiben.\n\nIch liebe meinen Job, Mann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25680] = {title = "So sind wir nicht", objective = "Findet und tötet das, was die Minenarbeiter in der Mine von Nethergarde so erschreckt hat.", description = "Das Wichtigste zuerst... sieht so aus, als ob wir ein Problem hätten. Die Minenarbeiter in dem Stollen rechts laufen herum wie ein Haufen aufgescheuchter, kopfloser Hühner. Ich kann nur vermuten, dass sie zu tief gegraben und etwas Unschönes gefunden haben... einen Dämon, ein Elementar oder irgendein Tentakelbiest.\n\nTak'arili mag keine Überraschungen. Findet heraus, was das Problem ist und kümmert Euch darum, dann können wir wie geplant weitermachen.", progress = nil, completion = "Also war es ein Dämon? Diese Minenarbeiter haben noch nie einen Dämonen gesehen? Wir sind in den Verwüstete Landen, Mann! Dämonen sind überall!\n\n&lt;Tak'arili seufzt.&gt;\n\nNaja... wenden wir uns dem guten Zeug zu, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25681] = {title = "Einige Leute muss man einfach töten", objective = "Tötet Chefausgrabungsleiter Hondo. Benutzt die unverdächtige Kiste, um Euch unterwegs zu tarnen.", description = "Wenn Ihr durch den Tunnel vor uns geht, der nach Westen führt, kommt Ihr direkt zum Büro von Chefausgrabungsleiter Hondo. Er ist hier der Obermotz und Tak'arili hat gehört, dass er ein richtig guter Minenarbeiter ist. Deshalb muss er sterben.\n\nEs gibt nur ein Problem: der Weg dorthin ist VOLL mit diesen lästigen Lakaien aus Nethergarde. Deshalb müsst Ihr Euch verkleiden. Hüpft in diese Kiste hier und schleicht Euch den Weg hinunter. Hoffentlich erregt Ihr nicht zu viel Verdacht auf dem Weg zu Eurem Opfer.", progress = nil, completion = "Gute Arbeit, Mann! Ohne Hondo sind die Jungs hilflos. Die Mine wird schon bald uns gehören!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25682] = {title = "Mission abgeschlossen", objective = "Liefert den Minenbericht von Nethergarde bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen ab.", description = "Wir sind hier fertig, Mann. Wir müssen nur noch einen Bericht an Okrilla schicken. Habt Ihr gerade etwas vor?", progress = "Ihr seid zurückgekehrt, <Name>?", completion = "&lt;Okrilla überfliegt den Bericht.&gt;\n\nBeeindruckend, &lt;Name&gt;. Ich hätte mich zwar nicht in dieser Kiste versteckt, aber sonst habt Ihr Eure Sache tapfer und bewundernswert gemacht. Die Schlacht, die wir heute gewonnen haben, wird uns nicht unmittelbar zugutekommen, aber der Schaden, den Ihr der Allianz zugefügt habt, wird über lange Zeit anhalten.", rewards = "Stiefel des VerschleißesSchulterschutz des BerichterstattersOkrillas GürtelSchienbeinschützer von RockardIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25683] = {title = "Die Schreckensfelssenke", objective = "Meldet Euch bei Blutmagierin Lynnore hinten in der Schreckensfelssenke in den Verwüsteten Landen.", description = "Ich meinte das, was ich gesagt habe, <Volk>. Ihr habt mir geholfen, jetzt gebe ich weiter, was ich weiß.\n\nVor Kurzem machte ein Dämonenjäger kurz hier Halt. Er ging nach Süden und sprach von Dämonen. Eigentlich hätte ich den Nachtelfen sofort getötet, aber er schien nicht der übliche Allianzabschaum zu sein und jeder, der Dämonen tötet, ist in dem Moment nützlich für mich.\n\nIhr solltet Euch bei Lynnore und Drazial melden, zwei Blutmagier, die ich in die Richtung entsandt habe. Sie haben ihr Lager hinten in einer Ogerhöhle aufgeschlagen.", progress = nil, completion = "Okrilla hat Euch geschickt? Okrilla da Killa?\n\n&lt;Lynnore hört sich Eure Geschichte an.&gt;\n\nEr hieß Loramus? Es tut mir leid, aber wir haben Euren Dämonenjäger nicht gesehen... Aber wir haben Möglichkeiten, ihn zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25684] = {title = "Stimmt den Blutstein ab", objective = "Verbindet Euch mit den Blutsteinteleportern in der Schreckensfelssenke.", description = "Ich gebe zu, dass wir nicht gerade den... vorteilhaftesten Ort für unsere Studien ausgewählt haben, besonders, wenn vorüberziehende Abenteurer den Wunsch haben, unbehelligt einzutreten und wieder hinauszugehen. Unsere Übereinkunft mit den Ogern ist recht wackelig und ich fürchte, wir können sie nicht dazu bewegen, Euch nicht anzugreifen, wenn Ihr Euch nähert.\n\nIch kann Euch allerdings gestatten, Euch mit einem der Blutsteinteleporter zu verbinden. Legt einfach Eure Hände auf den Stein zu meiner Rechten und Ihr werdet aus der Höhle herausteleportiert. Dann benutzt den Stein draußen, um wieder hereinzuteleportieren!", progress = "Der Verbindungsvorgang ist einfach, und er wird sich ganz bestimmt auf die Dauer bezahlt machen.", completion = "Ausgezeichnet. Jetzt, da das aus dem Weg ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25685] = {title = "Der erste Schritt", objective = "Besorgt 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", description = "Damit wir das Ritual, um das Ihr gebeten habt, durchführen können - und vielleicht noch weitere Rituale in Zukunft - benötigen wir Blut. Die Verwüsteten Lande sind voller Reagenzien, die wir für unsere Blutmagie brauchen... es ist nur eine Frage der richtigen Zusammenstellung.\n\n<Lynnore berät sich schnell und kurz mit Drazial.>\n\nBasilisken und Hyänen, zu gleichen Teilen. Und wir benötigen viel davon. Geht nach Osten ins Zentrum der Verwüsteten Lande. Und vergesst nicht - Ihr könnt den Teleporter benutzen!", progress = "Mit Ogerblut kommt man nicht sehr weit. Habt Ihr es?", completion = "&lt;Lynnore beäugt das Blut hungrig.&gt;\n\nMehr als genug - und immer noch warm! Dann lasst uns das Ritual beginnen, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25686] = {title = "Blutritual", objective = "Sprecht mit Blutmagierin Lynnore, um das Blutritual zu beginnen.", description = "Unser Ziel ist es, den Dämonenjäger Loramus Thalipedes zu finden. Lasst mich wissen, wenn Ihr bereit seid, das Blutritual zu beginnen. Dann zieht Euch einen Schritt zurück.", progress = "Das Ritual ist noch nicht abgeschlossen.", completion = "Das Blutritual war ein voller Erfolg - ich kann ganz deutlich sehen, wo Loramus sich in diesem Moment befindet. Das heißt, ich kann sehen, wo seine Leichenteile sich befinden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25687] = {title = "Nicht irgendeine Leiche", objective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", description = "Loramus Thalipedes ist tot. Nun, das nehme ich zurück... das ist nur eine Annahme meinerseits, aber ich weiß, dass sein Körper in drei Teilen ruht.\n\n<Lynnore denkt kurz nach.>\n\nWenn Ihr mir die drei Teile bringt, haben wir noch eine Chance. Alle drei Teile sind in der Nähe... die Schreckensfelsoger haben sie in ihren Höhlen versteckt. Um genau zu sein ist ein Teil in der Truhe, den Vorsprung hinter mir hinunter...", progress = "Vertraut mir - egal, was mit Loramus geschehen ist, wir können es beheben. Die Grenzen der Blutmagie sind bisher noch nicht ausgelotet.", completion = "Ich verstehe...ja, damit können wir arbeiten.\n\n&lt;Lynnore schaut auf den Kopf des Nachtelfen.&gt;\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich darauf, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25688] = {title = "Der Altar der Stürme", objective = "Bringt Loramus' Leichnam zum Altar der Stürme, dann beschützt ihn während des Rituals.", description = "Oben auf den Klippen über unserer gemütlichen Höhle befindet sich ein mächtiger Altar. Ein mächtiger DÄMONISCHER Altar, der von Kultisten bewacht wird, aber dennoch sehr große Kräfte birgt. Wenn Ihr es schafft, ihn zu erreichen, könnt Ihr damit Loramus zu uns zurückbringen.\n\nDer Altar wird wahrscheinlich Euren Bemühungen widerstehen, also müsst Ihr Loramus' Leichnam während des Rituals beschützen. Bringt den Dämonenjäger hinterher zu mir zurück.", progress = nil, completion = "Ihr... Ihr seid ein Narr! Was habt Ihr getan?", rewards = "Stiefel der dämonischen WiederbelebungLoramus' HandschuheArmschienen des dämonischen AltarsStiefel der abgeschlossenen RitualeHelm der StürmeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25689] = {title = "Die Zeit ist knapp", objective = "Bringt die disharmonische Rune zu Behüter Wazzik am Dunklen Portal in den Verwüsteten Landen.", description = "Ich jagte einen Dämonen mit Namen Razelikh. Grol, sein Ogerhauptmann, griff mich an. Er hat mich auf dem falschen Fuß erwischt und ich starb - genau wie Grol.\n\nRazelikh hat vor, in die Verwüsteten Lande zurückzukehren und sie mit seinen Dämonen zu überwältigen. Sogar jetzt bereitet er sich darauf vor, seine Legionen zusammenzurufen, damit sie uns auslöschen.\n\n<Der Dämonenjäger zieht schnell eine Rune hervor und übergibt sie Euch.>\n\nBringt das hier zu Wazzik am Dunklen Portal im Südosten. Er wird Euch führen. Schnell! Wir haben nicht viel Zeit!", progress = "Kenne ich Euch, guter <Volk>??", completion = "Wie bitte? LORAMUS?!\n\nOh verflixt, sprecht leise, ja? Wenn mein Boss herausfindet, dass ich für Loramus gearbeitet habe, wisst Ihr, wie schnell ich dann auf meinen vier Buchstaben lande?\n\n&lt;Wazzik nimmt Euch die Rune ab, drückt sie gegen seine Brust, schließt seine Augen und nickt.&gt;\n\nNun, Ihr habt nicht gelogen. An die Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25690] = {title = "Auch Blutmagier müssen essen", objective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", description = "Entgegen dem allgemeinen Irrglauben trinken Blutelfen Blutmagier KEIN Blut. Wir essen normale Speisen wie jeder andere auch - etwas, das in der hintersten Ecke einer Ogerfeste schwierig zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind zumindest ohne Weiteres essbar, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und unsere Nahrungsvorräte wieder aufstocken?", progress = "Ich bin ausgehungert! Wenn Ihr Euch nicht beeilt, sehe ich mich noch gezwungen, unsere Reagenzien zu trinken.", completion = "Die sind perfekt, &lt;Name&gt;. Lynnore und ich werden in den nächsten Tagen gut zu essen haben.", rewards = "AschmähnenarmschienenBefleckter SchulterschutzStiefel der Verwüsteten LandeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25691] = {title = "Der verkohlte Granit des Dunklen Portals", objective = "Besorgt 24 verkohlte Granitsplitter.", description = "Loramus will, dass wir - äh, IHR - Granitsplitter aus den Felsbrocken um das Dunkle Portal herum sammelt. Ich weiß nicht, wofür er die Steine braucht, aber ich habe da so meinen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal.", progress = "Sprecht leise, ja?", completion = "Ich hoffe, das ist es, was er braucht. Wir haben wahrscheinlich nicht mehr die Zeit, dass Ihr noch einmal zurückkehrt und noch mehr schürft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25692] = {title = "Das abscheuliche Blut der Dämonen", objective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", description = "Thalipedes möchte mehr Blut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt in reichlichen Mengen.", progress = "Uff, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Loramus' Bitte einmal abgesehen, bin ich sicher, dass Dar'toon für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25693] = {title = "Verbesserung des Steins", objective = "Bringt Wazziks Paket zu Loramus Thalipedes in der Schreckensfelssenke in den Verwüsteten Landen.", description = "<Wazzik packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was Loramus von uns verlangt hat. Wenn Ihr ihn seht, denkt daran, ihm zu sagen, dass ich eine große Hilfe war. Ich fürchte, er wird meinen Anteil hieran nicht erkennen.", progress = "<Klasse>... Ihr kehrt zurück...", completion = "Das reicht. Wenn Ihr Wazzik noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Ich werde dafür sorgen, dass die Blutmagier sich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange sie arbeiten, habe ich eine andere Aufgabe für Euch zu erledigen. Um genau zu sein sind es drei Aufgaben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25694] = {title = "Rückendeckung", objective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", description = "Den einzigen Grund, warum Ihr mich neben Soldaten der Allianz stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - und sei es noch so gering. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", progress = nil, completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n&lt;Der Kriegsfürst lehnt sich zu Euch hinüber und flüstert:&gt;\n\n&lt;Volk&gt;, wenn Ihr noch interessiert seid, ich habe noch eine kleine Aufgabe für Euch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25695] = {title = "Nachhut", objective = "Untersucht die Pläne der Allianz am Dunklen Portal, ohne erwischt zu werden.", description = "<Kriegsherr Dar'toon spricht sehr leise.>\n\nIch habe Befehle von... oben... für die Ihr genau der Richtige seid. Ich habe gesehen, dass die Allianz regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", progress = nil, completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n&lt;Dar'toon hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.&gt;\n\nHmpf... das ist ziemlich harmloses Zeugs. Entweder ist die Allianz dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", rewards = "Harmlose ArmschienenHandschuhe der närrischen UnschuldDar'toons UmhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25696] = {title = "Sonnenschleiers Exkursionstrupp", objective = "Meldet Euch bei Rohan Sonnenschleier bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.\n\nBereitgestellter Gegenstand: \n", description = "Ach richtig – ich habe vor ein paar Tagen eine Nachricht von jemandem erhalten. Das archäologische Institut oder so ähnlich? Sie suchen jemanden, der... etwas tun soll...\n\n<Der Kriegsherr durchwühlt einige Papiere.>\n\nAh, hier ist es! Ja, Rohan Sonnenschleier vom archäologischen Institut sucht fähige Abenteurer, die ihm bei einer archäologischen Expedition in den Süden helfen sollen.\n\nHier, nehmt das mit. Warum geht Ihr nicht und sprecht mit dem Elfen?", progress = nil, completion = "Willkommen, Reisender. Danke, dass Ihr Euch auf meinen Aufruf hin gemeldet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25697] = {title = "Das Amulett von Allistarj", objective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", description = "Als mein Meister mir half, meine Augen herauszunehmen, gab er mir das Geschenk der Sicht - einer Sicht, die weit besser ist, als Eure oder die dieser blutsüchtigen Elfen. Meine Sicht erlaubt mir, Gegenstände mit dämonischer Macht zu sehen, so wie das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in der Schlangenschlinge im Osten eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.", progress = "Alistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "&lt;Lynnore untersucht das Amulett.&gt;\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25698] = {title = "Das Amulett von Sevine", objective = "Besorgt das Amulett von Sevine von Salzflopper in den Verwüsteten Landen.", description = "Das Amulett von Sevine befindet sich weit im Osten in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nIch fühle eine stärkere Verbindung mit Sevine als mit den anderen Dienern Razelikhs - möglicherweise, weil sie den Altar der Stürme erbaut hat, auf dem Ihr mich wiederbelebt habt. Bringt ihr Amulett mit den anderen zu Lynnore.", progress = "Sevines Amulett - zusammen mit den anderen können wir die Anhöhe des Entweihers erreichen.", completion = "&lt;Lynnore wiegt das Amulett in der Hand.&gt;\n\nEin Kriegsherr... und ein mächtiger noch dazu. Ich werde das hier behalten, bis die Zeit reif ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25699] = {title = "Das Amulett von Grol", objective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", description = "Grol - der Oger, der mich auseinandergerissen hat.\n\n<Loramus lacht.>\n\nOffensichtlich ist Grols Leichnam durch mehrere Hände gegangen, seit wir zusammen gestorben sind, aber er ist nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "&lt;Lynnore umklammert das Amulett.&gt;\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis Loramus bereit ist, fortzufahren.", rewards = "HavarieküstenumhangStiefel des OgerjägersSchlangenwindungenStärkender GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25700] = {title = "Loramus Thalipedes wartet", objective = "Sprecht mit Blutmagierin Lynnore, um an ihrem Ritual teilzunehmen.", description = "Die Verzauberung auf diesen Amuletten war nicht besonders kompliziert. Zusammengefügt wird ihre Macht Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, verschaffen.\n\nIch bin bereit, dieses Ritual für Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr bereit seid.", progress = nil, completion = "Wie es aussieht, sind wir bereit, uns unserem Dämonen zu stellen, &lt;Name&gt;. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämonen: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25701] = {title = "Ihr seid Rakh'likh, Dämon", objective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", description = "Held, hört gut zu.\n\nZunächst müssen wir nach Nordosten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe schicken. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Wazzik.", progress = nil, completion = "Ich verstehe. Also hatte Loramus das die ganze Zeit so geplant.\n\nIch hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben. Und jetzt ergibt seine letzte Anweisung an mich auch einen Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der edlen TatenBand der AufopferungBand des selbstlosen Handelns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25702] = {title = "Zuhause... Weg... Naga...", objective = "Salzflopper hat Euch gebeten, mit Neptool, Häuptling der Steinteichmurlocs, zu sprechen.", description = "<Der Murloc hat Schwierigkeiten, Eure Sprache zu sprechen.>\n\nSteinteich... angegriffen. Naga kommen, einnehmen Dorf, Dorfbewohner.\n\nSalzflopper entkommen, andere nicht. Geht Süden, sprecht mit Häuptling Neptool. Vielleicht er überlebt.", progress = nil, completion = "&lt;Der Murlocgeist schaut Euch traurig an.&gt;\n\nSalzflopper hat keine Schande über sich gebracht, indem er wegrannte. Schaut hinter mich und seht selbst.\n\nDer Steinteich hatte keine Chance gegen den Angriff der Naga.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25703] = {title = "Gräueltaten", objective = "Tötet 10 Barbaren der Blutbrandung und 10 Verzauberinnen der Blutbrandung.", description = "<Obwohl seine Lippen sich nicht bewegen, könnt Ihr spüren, dass der Murlochäuptling mit Euch spricht.>\n\nDie Naga der Blutbrandung und die Steinteichmurlocs haben miteinander gelebt, solange wir denken können. Wir hatten unsere Meinungsverschiedenheiten, aber wir haben uns nie gegenseitig provoziert. Warum haben sie sich dann nur gegen uns gewandt?\n\n<Neptool wirft einen Blick über seine Schulter auf seine früheren Dorfbewohner.>\n\nSeht Ihr, was sie jetzt tun? Sie versklaven uns, opfern uns und zwingen uns, gegeneinander zu kämpfen. Ich werde sie aufhalten, <Volk>... und Ihr werdet meine Waffe sein.", progress = nil, completion = "Ihr habt Eure Sache gut gemacht, tapferer &lt;Klasse&gt;. Ich bin erfreut, aber noch nicht zufrieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25704] = {title = "Der verrückte Magus", objective = "Extrahiert die Seele von Tirth, dem verrückten Magus.", description = "Es bleibt nur noch eine Sache, die zu tun ist. Ihr müsst in Tonys Anwesenheit jemand mit einem großen Mojo töten.\n\nNein, nicht mich!\n\nDer alte Magus Tirth is' verrückt geworden, als er versucht hat, das Wasser aufzuhalten, als der Kataklysmus hereinbrach. Jetzt sucht er die Gegend südlich vom Stützpunkt heim.\n\nNehmt diesen Seelenstab und benutzt ihn auf seinem Leichnam. Dann bringt Tony zurück, und wir verfrachten ihn zurück in seinen Körper.\n\nIhr könnt mein Geistportal für den Weg benutzen.", progress = nil, completion = "Jetzt werden wir Tony Zweihauer zurück ins Leben bringen. Seid ihr dann beide soweit, Mann?", rewards = "Robe von Magus TirthStützpunktgürtelGeistrufergamaschenAlimenteAuf Euch wartet eine dieser Belohnungen:\n\nWeggeworfener Ehering\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25705] = {title = "Falsche Götzen", objective = "Zerstört 8 Götzen der Azsh'ir auf den Roten Weiten.", description = "Neptulon der Gezeitenjäger ist unser Gott. Er war auch der Gott der Blutbrandung, aber anscheinend haben sie ihm den Rücken gekehrt. Jetzt verehren sie nur noch Azshara, ihre Nagakönigin. Ihr werdet die Abbilder Azsharas überall in ihren Siedlungen sehen, die aus Seestein gemeißelt wurden.\n\n<Der Murlocgeist betrachtet Eure Waffe.>\n\nDie Waffe wird reichen. Durchbohrt damit die Götzen der Azsh'ir. Man muss sie daran erinnern, dass unser Vater Neptulon der einzige ist, der wirklich die Meere regiert.", progress = nil, completion = "Ihr macht einen alten Murloc stolz, &lt;Volk&gt;.\n\nDanke und mögen die Wellen immer an Euren Füßen plätschern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25706] = {title = "Neptools Rache", objective = "Tötet 8 Akolythen der Blutbrandung, 8 Zeloten der Blutbrandung, 4 Glücksspieler der Blutbrandung und 4 Götzendiener der Blutbrandung.", description = "Noch so viele Nagatode werden den Stamm des Steinteichs nicht wieder zurückbringen, aber die Menge der Rache wird den Geistern meines Volkes helfen, leichter ihre Ruhe zu finden.\n\nViele der mächtigeren Angehörigen der Blutbrandung haben eine Feste in den Höhlen im Nordwesten errichtet. Tötet sie im Namen Steinteichs. Die anderen Angehörigen der Blutbrandung haben hier auf unserem Strand Gladiatorenbecken und Azsh'ir Altäre errichtet, wo sie mein Volk gegeneinander kämpfen lassen und ihren falschen Gott verehren. Tötet sie im Namen des Gezeitenjägers.", progress = nil, completion = "Das letzte Mitglied des Steinteichs kann heute als Geisel genommen und morgen getötet werden, Landwandler... aber sie werden die Unterwelt in dem Wissen durchqueren, dass ein tapferer &lt;Volk&gt; ihren Tod rächte. Danke.", rewards = "Wickeltuch des SpielersGürtel von SteinteichAuf Euch wartet eine dieser Belohnungen:\n\nRing der Blutbrandung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25707] = {title = "Die Zukunft des Steinteichs", objective = "Zieht die Verlassene Kiste der Blutbrandung zum Verbotenen Meer vor der Küste der Roten Weiten.", description = "Die Steinteichkaulquappen, die sich noch auf dieser Kiste befinden, scheinen müde, verängstigt und beinahe vertrocknet zu sein. Sie müssen zum Wasser gebracht werden und zwar schnell.\n\nWenn Ihr diese Kiste vielleicht über den Strand in das Verbotene Meer weit jenseits der Küste der Roten Weiten ziehen könntet, dann haben sie eine Chance zu entkommen und die Steinteichmurlocs können vielleicht weiterleben...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25708] = {title = "Gefallene Freunde", objective = "Tötet 13 ertrunkene Gilneer an der Havarieküste, um ihre Geister zu befreien.", description = "Laut Eurem Bericht klingt es nicht so, als gäbe es viele Überlebende… nur rastlose Geister. Wir müssen ihnen wenigstens zu ihrer letzten Ruhe verhelfen.\n\n<Enohar nimmt einen tiefen Schluck Schwarzbier aus ihrem Krug.>\n\nKehrt zurück zur Havarieküste und vernichtet die Geister der Worgen, die dort ihr Unwesen treiben. Dadurch befreit Ihr sie von dieser Welt, sodass sie in die nächste weiterziehen können.", progress = nil, completion = "&lt;Enohar nimmt einen Schluck aus ihrem frisch aufgefüllten Krug.&gt;\n\nAye, das habt Ihr gut gemacht, Junge. Ihr erfüllt die Allianz mit Stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25709] = {title = "Ein paar Schwanzfedern ausreißen", objective = "Benutzt Enohars explosive Pfeile, um 20 Schwanzfederknochenpflücker an der Havarieküste zu töten.", description = "Die gestrandeten Schiffe bereiten mir jedoch noch weitere Sorgen. Sie locken unglaublich viele Geier an. Sie haben zwar die Knochen schon sauber gepickt, aber wir können nicht zulassen, dass sie die Leichen unserer Freunde noch weiter entehren.\n\nBevor ich Braumeister wurde, war ich Jäger. Hier, nehmt diesen Bogen und vor allem diese Pfeile. Ich habe sie mit einer Tinktur benetzt, die diesen Knochenpflückern eine unangenehme Überraschung bereiten sollte.", progress = nil, completion = "Es ist eine Tragödie, was sich da an der Havarieküste abgespielt hat. Und es waren nicht einmal Soldaten, sondern nur brave Bürger auf der Suche nach einem neuen Zuhause.\n\nIch glaube, wir haben alles getan, was wir konnten, &lt;Name&gt;.", rewards = "Handschuhe des MitgefühlsSchwarzfedergürtelEnohars alte JagdstiefelKnochenpflückerarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25710] = {title = "Unwichtige Ablenkungen", objective = "Tötet einen Späher der Okril'lon außerhalb von Burg Nethergarde in den Verwüsteten Landen.", description = "Nethergarde hat seit Jahren unerschütterlich dem Ansturm der Dämonen, die dieses Land heimsuchen, standgehalten. Unsere Wache endet nie, unsere Wachsamkeit lässt nie nach und unsere Tapferkeit ist unermesslich.\n\nWir haben diese Lande verteidigt, seit das Portal sich öffnete, aber jetzt hat dieses Hordengeschmeiß die Frechheit, sich uns in den Weg zu stellen? Wir haben SIE genauso beschützt wie uns selbst!\n\n<Lungertz mustert Euch.>\n\nSchauen wir mal, ob Ihr für den Kampf taugt. Tötet einen der Hordenspäher der Okril'lon, die an unseren Grenzen nagen.", progress = "Was ist los - zu viel Angst, zu kämpfen?\n\nIch hätte es besser wissen müssen, als einem außenstehenden <Klasse> wie Euch zu vertrauen. Man überlässt die Verteidigung von Nethergarde lieber seinen eigenen Leuten.", completion = "Hmm... nicht schlecht. Ihr seid schneller als die meisten meiner Leute. Bleibt in der Nähe, &lt;Name&gt;... Vielleicht habe ich doch noch Verwendung für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25711] = {title = "Schaltet die Okril'lon aus.", objective = "Tötet 9 Infanteristen der Okril'lon beim Versorgungslager von Nethergarde.", description = "Die Horde ist eine Landplage, derer wir uns entledigen werden, aber es ist schwieriger als erwartet. Ihr müsst dem ein Ende setzen.\n\nWestlich von Nethergarde übt die Hauptstreitmacht der Okril'lon Druck auf unsere Verteidigung aus. Im Moment besetzen sie die Mine von Nethergarde, wollen in die Versorgungslager vordringen und zum Schluss die Burg einnehmen. Ihr müsst sie dezimieren und ihren Vormarsch aufhalten, <Name>.", progress = nil, completion = "Ihr seid ein Gewinn für die Allianz und die Kirin Tor, &lt;Name&gt;. Gut gemacht.\n\nMit der Zeit werden unsere Streitkräfte die Mine zurückerobern und diese Hunde der Horde aus den Verwüsteten Landen vertreiben.", rewards = "NethergardenarmschienenNethergardengürtelNethergardenstiefelNethergardenhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25712] = {title = "Die Herrscher von Nethergarde", objective = "Tötet Hauptmann Metlek am Versorgungslager von Nethergarde.", description = "Lungertz ist ein starker Anführer, aber er ist stolz. Er untertreibt den Druck, den die Horde wirklich auf uns ausübt. Ohne unsere Mine... Nethergarde ist mittellos.\n\nWir müssen die Streitkräfte der Horde JETZT aus dem Versorgungslager entfernen. Dazu müssen wir ihren Kommandanten, Hauptmann Metlek, töten. Er ist kein überragender Anführer und zieht es vor, Befehle aus den hinteren Linien heraus zu bellen, aber dennoch könnte sein Tod uns den Sieg verschaffen, den wir brauchen.", progress = nil, completion = "Danke, &lt;Name&gt;. Dank Eurer Bemühungen bin ich zuversichtlich, dass wir mit der Zeit die Mine von Nethergarde zurückerobern können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25713] = {title = "Macht ihre Waffen zunichte", objective = "Benutzt Butterblumes Handgranate gegen 8 Waffenkisten der Okril'lon im Versorgungslager von Nethergarde.\n\nHaltet einen Sicherheitsabstand, wenn Ihr die Granaten verwendet, damit Ihr Euch nicht selbst in die Luft sprengt.", description = "Sagt einmal... <Name>, nicht wahr? Ich habe einen Vorschlag für Euch, der Explosionen beinhaltet. Interessiert?\n\nIch konnte nicht anders, als Eure Unterhaltung mit dem Rüstmeister anzuhören. Wisst Ihr... Ich arbeite an einer Sprengvorrichtung. Sie ist anderen Lebewesen gegenüber nicht sehr wirksam, aber verheerend gegen Artillerie. Wenn Ihr wieder hinausgeht, um diesen Orcs einen Besuch abzustatten, findet ein paar Vorräte der Feinde und probiert dieses Ding einmal aus. Wer weiß... vielleicht mögen sie ja auch Explosionen.", progress = nil, completion = "Aaah, das Geräusch, wenn Dinge \"bumm\" machen erfreut mein Herz und lässt es schneller schlagen. Ihr habt diesem Gnom den Tag versüßt, &lt;Name&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25714] = {title = "Behüter Mahar Ba", objective = "Meldet Euch bei Behüter Mahar Ba im Magierturm von Burg Nethergarde.", description = "Es ist Zeit für Euch, den Behüter aufzusuchen. Er ist in letzter Zeit etwas übellaunig und ich weiß nicht genau, warum.\n\nGeht oben auf den Magierturm und meldet Euch bei ihm. Ich habe hier keine Arbeit für Euch, aber ich bin sicher, dass er welche hat.", progress = nil, completion = "Meine Mitarbeiter haben das Richtige getan, Euch zu mir zu schicken. Ich habe ein Problem, das eine Bedrohung für das Sanktum von Nethergarde darstellen könnte. Ich brauche jemanden, der fähiger ist als die meisten anderen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25715] = {title = "Ein genauerer Blick", objective = "Späht die gestrandeten Schiffe an der Havarieküste in den Verwüsteten Landen aus.", description = "Wir haben schon unzählige Schiffe an der Küste im Südosten vorbeiziehen sehen und nie ist etwas Auffälliges passiert. Doch vor einigen Tagen warf ein Sturm mehrere Schiffe an die Küste, wo sie nun gestrandet liegen.\n\nIch würde einen Krug Nethergarde Bitter wetten, dass es Schiffe der Horde sind, wenn ich Nethergarde Bitter nicht so sehr lieben würde. Ich kann Euch jedoch mit Gold bezahlen, wenn Ihr Euch diese Schiffe genauer anseht und mir davon berichtet.", progress = "Was gibt es Neues von der Havarieküste, <Name>?", completion = "Ihr habt Worgen gesehen? Das klingt nicht gut.\n\nWorgengeister? Das klingt sogar noch schlimmer.\n\nDas waren keine Schiffe der Horde… das waren gilnearische Schiffe! Und sie waren sicher auf dem Weg nach Surwich am Ende des Besudelten Walds. Das ergäbe zumindest Sinn.\n\nWir müssen ihnen helfen, &lt;Name&gt;! Die Worgen sind unsere Verbündeten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25716] = {title = "Kultisten an der Schwelle", objective = "Besorgt 6 intakte Zauberfokusse eines Schattenanbeters von Zauberklingen der Schattenanbeter und Okkultisten der Schattenanbeter in den Verwüsteten Landen.", description = "Möglicherweise seid Ihr schon einigen Kultisten der Schattenanbeter begegnet, die in Höhlen südwestlich von Nethergarde hausen. Sie stellen keine direkte Bedrohung für unsere Burg dar, aber ich fürchte, dass sie etwas Furchtbares planen, das Eure Vorstellungskraft übersteigt.\n\nDie rangniederen Mitglieder tragen Zauberfokusse, die eine Antwort enthalten könnten. Bringt mir einige intakte davon her, wenn Ihr sie den Kultisten aus den Händen reißen könnt.", progress = "Die Kultisten werden sich nicht so einfach von ihren Fokussen trennen. Tötet sie schnell, bevor sie Eure Absicht erahnen.", completion = "Geschickt gemacht, &lt;Name&gt;. Jetzt werden wir sehen, ob mein Verdacht berechtigt ist.", rewards = "Sandalen der SchattenanbeterZauberfokusschulterschutzGürtel der okkulten SchreckenMahars GeschenkIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25717] = {title = "Die Dämonen und der Druide", objective = "Tötet 5 Verdammniswachenzerstörer, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", description = "Das archäologische Institut konzentriert sich auf das Auffinden und Bewahren magischer Artefakte. Diese Exkursion konzentriert sich auf die dämonischen Artefakte, die dort verborgen sind, wo sich einst die Faulende Narbe befand.\n\nEin Worgendruide hat sich dort angesiedelt und lässt einen Wald wachsen. Allerdings scheint es ihm nicht so recht zu gelingen, da die Gegend immer noch von Dämonen verseucht ist.\n\nNun wie auch immer, der Wald steht unserer Exkursion im Weg, genau wie die Dämonen. Tötet die besudelten und kehrt zurück zu mir, damit wir uns um den Druiden kümmern.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;.\n\nIch sollte etwas ehrlicher zu Euch sein. Die Dämonen waren ein Ärgernis, aber sie sind nicht das eigentliche Problem. Dieser Worgendruide ist unser Problem", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25718] = {title = "Wie man am besten weitermacht", objective = "Meldet Euch bei Elijah Dämmerflug bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.", description = "Dadurch, dass Ihr dort unten Dämonen getötet habt, bekamen unsere Späher genug Zeit, sich den Druiden einmal genauer anzusehen. Meine Informanten berichten mir, dass er Marl Wurmdorn heißt - er ist ein abtrünniger Druide aus Gilneas mit beachtlichen Kräften. Er wohnt in Maldraz, dem großen, verdrehten Baum mitten im Wald und irgendeine seltsame Kraft bewahrt ihn vor Unheil. Ob diese Kraft dämonischen oder natürlichen Ursprungs ist, müssen wir noch herausfinden.\n\nSprecht mit Elijah. Vielleicht hat er neue Informationen für Euch.", progress = nil, completion = "Rohan schickt EUCH, um seinen Druiden zu töten? Na schön.\n\nIhr solltet wissen: Marl Wurmdorn ist gleichermaßen Dämon wie Druide. Sogar ein Druide mit seiner Macht hat keine Chance gegen die dämonischen Energien, die dieses Land vollkommen durchziehen. Aber das ändert nichts daran, dass er für uns ein Hindernis ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25719] = {title = "Dämonisches Gefäß", objective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", description = "Es muss einen Weg geben, Wurmdorns Aufmerksamkeit zu erregen. Etwas, das seine Trance durchbricht. Etwas, das mit Sicherheit funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", progress = "Dämmerflugs Plan ist gut. Habt Ihr das Gefäß, <Name>?", completion = "Ausgezeichnet gemacht, &lt;Name&gt;. Wir haben, was wir brauchen, um die Trance des Worgen zu durchbrechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25720] = {title = "Der Fall des Marl Wurmdorn", objective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", description = "Wurmdorns unnatürlicher Wald bedroht den Fortschritt unserer Exkursion. Unsere Spitzhacken zerbrechen an ihren Wurzeln, sein Moos überwuchert unsere Ausgrabungsstätten und seine Tiere greifen meine Leute an. Wenn es um Ausgrabungen geht, ist mir eine dämonenverseuchte Einöde allemal lieber als ein Wald.\n\nNehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", progress = nil, completion = "Jetzt, da dieser Druide von der Bildfläche verschwunden ist, können wir uns wieder unseren Ausgrabungen zuwenden. Die Welt ist voller mächtiger Artefakte, &lt;Name&gt;. Ihr müsst nur den Willen haben, das Notwendige zu tun, um sie zu bekommen.\n\nNehmt ruhig eins von diesen hier. Das Institut für Archäologie teilt immer gerne seine Schätze mit anderen Mitgliedern der Horde.", rewards = "WurmdornhandschuheSchulterschutz der getrübten HeilungSchulterstücke des SchatzesSonnenschleierbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25721] = {title = "Kämpft gegen die Flut", objective = "Tötet 10 Flutelementare.", description = "Ich bin hier, weil Muradin selbst wusste, dass diese Messstation jemanden braucht, der diese Schwachköpfe auf Trab bringt. Sie haben alle zu viel Angst vor den Wildtieren, um überhaupt etwas zu tun. Wenn ich will, dass sie ihren Allerwertesten hochbekommen, dann muss hier ein wenig aufgeräumt werden.\n\nZunächst einmal haben wir ein Problem mit Elementaren. Die Flut hat hier so ein Durcheinander angerichtet, dass selbst das Wasser hysterisch geworden ist.\n\nIch wette, Ihr habt noch nie einem ganzen See Sinn und Verstand eingeprügelt, aber genau das verlange ich jetzt von Euch. Ihr müsst diesen Elementaren richtig eine von mir verpassen.", progress = nil, completion = "Wer hätte das gedacht. Es gibt tatsächlich jemanden hier, der Magni keine Schande macht - sein armes Herz aus Kies sei gesegnet.\n\nAllein dafür bekommt Ihr den ersten Schluck von dem Bier, mein Junge. Aber lasst Euch das nicht zu Kopfe steigen! Wir haben noch viel mehr verfluchte Arbeit zu tun und ich werde nicht dulden, dass Ihr vorzeitig schlapp macht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25722] = {title = "Ablagerungen, mein Lieber", objective = "Sammelt 8 Flutsedimentproben ein.", description = "Die Zerstörung des Steinwerkdamms war keine Kleinigkeit. Wir sind hier, um herauszufinden, wie schlimm der Schaden ist. Eine riesige Wassermenge ist hier durchgetobt und wenn diese die Erde zu sehr gestört hat, könnte uns noch Schlimmeres bevorstehen.\n\nWir können einiges aus den Sedimenten der überfluteten Gegend ablesen. Ich brauche so viele Erdproben wie möglich. Ich würde es wirklich sehr zu schätzen wissen, wenn Ihr dort hinausgehen und noch einige Proben für mich sammeln würdet.", progress = "Dann lasst mal das Sediment sehen.", completion = "Ah ja. Die gute Nachricht ist, sie sind perfekt. Die schlechte Nachricht ist, dass ich - sogar betrunken, wie ich bin - erkenne, dass ihre Farbe nicht dem Mutterboden hier entspricht\n\nDas bedeutet, dass es nicht gut für diese Gegend aussieht, &lt;Name&gt;. Aber wir müssen noch mehr Tests durchführen, bevor wir das Handtuch werfen.", rewards = "Verfärbte ArmschienenOberbodenarmschienenSäufergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25723] = {title = "Dreschen bringt Glück", objective = "Besorgt 8 Dreschadonbrocken von verirrten Dreschadons.", description = "Die hiesigen Wildtiere sind offenbar von der Flut vollkommen verstört. Dieses Moor war einmal voller Krokilisken, aber ich habe noch keinen einzigen gesehen.\n\nWas ich gesehen habe, sind Dreschadons. Die hat es hier noch nie gegeben, also muss die Flut sie direkt aus Loch Modan hergeschwemmt haben.\n\nZum Glück für uns sind sie viel leckerer als Krokilisken und mir gehen gerade die Vorräte aus. Bringt mir Dreschadonfleisch für das Lager und ich werde Euch gern dafür bezahlen.", progress = "Sind sie fleischig? Schauen wir mal.", completion = "Herrlich. Die kann man bestimmt gut braten und dem Lager bleibt eine Woche Pilzkekse erspart.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25724] = {title = "Frostmähnenaggression", objective = "Tötet 5 Seher der Frostmähnen und 7 Schneeschreiter der Frostmähnen auf Schimmergrat.", description = "Der Kataklysmus hat das Gleichgewicht der Kräfte in Dun Morogh in Frage gestellt, <Name>. Ohne Warnung tauchte eine Welle Troggs aus den Höhlen in der Nähe von Gnomeregan auf und hat die Trolle der Frostmähnen überrannt. Die Trolle sind seitdem immer weiter nach Osten gezogen.\n\nIm Nordwesten, oben am Schimmergrat, gab es immer eine gewisse Präsenz der Frostmähnen, aber seit der Abwanderung sind wir jetzt von Trollen umgeben. Wir können nicht zulassen, dass die Trolle diesen Umstand zu ihren Gunsten ausnutzen. Meine Leute werden im Osten die Stellung halten und Ihr führt einen Schlag gegen den Schimmergrat.", progress = nil, completion = "Wir sollten in der Lage sein, unsere Bemühungen auf den Rest der Trolle im Osten zu konzentrieren, aber es gibt immer noch das Problem mit den Wendigos im Graufelsbau.", rewards = "Ihr bekommt:\n\nSteinrundschild"}
MultiLanguageQuestData['de'][25725] = {title = "Moosbuschbeeren", objective = "Sammelt 15 Handvoll Moosbeeren.", description = "Wir haben genügend Vorräte, aber wir benötigen Arzneien. Das halbe Lager hat einen gewaltigen Kater und ein Heilmittel wäre jetzt angebracht.\n\nZum Glück kenne ich ein gutes Hausmittel, das mir von meiner lieben alten Mutter beigebracht wurde. Wir brauchen nur ein paar hiesige Zutaten.\n\nSeid so gut und sammelt für mich ein paar Beeren von Moosbüschen. Sie wachsen hauptsächlich am Wasser im Schatten, also schaut entlang der Küste und in der Nähe anderer Pflanzen.", progress = "Wie viele habt Ihr gefunden?", completion = "Die sind genau richtig. Die Jungs werden bald wieder auf den Füßen sein, sobald ich das hier in etwas Essbares verwandelt habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25726] = {title = "Nivellierarbeiten", objective = "Findet ein Nivelliergerät bei einem schmierigen Schlammling.", description = "Also gut, Ihr müsst mir helfen, mein Nivelliergerät zu finden.\n\nWas guckt Ihr so komisch? Richtig! Ich sagte mein Nivelliergerät! Das ist ein wichtiges Vermessungsinstrument!\n\nIch hab mir den Namen nicht ausgedacht, ok? Geht und schaut es nach! Ich habe es nur kurz auf einem Felsen liegen lassen und einer dieser furchtbaren Schlammlinge hat es verschlungen. Die kriechen überall hier herum, aber einer von ihnen müsste es noch in sich haben.", progress = "Habt Ihr das Nivelliergerät gefunden?", completion = "Oh gut, es ist unbeschädigt! Vielen Dank.\n\nIhr, äh, solltet Euch dort vielleicht ein bisschen säubern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25727] = {title = "Drungeld Finsterblick", objective = "Tötet Dungeld Finsterblick und nehmt seinen Bart an Euch.", description = "Der Dunkeleisenklan hier führt nichts Gutes im Schilde. Und wenn Euch das überrascht, seid Ihr noch dämlicher als die Papiertiger da in dem Zelt. Muradin kann ja diesen rußgeschwärzten Schwachköpfen in Eisenschmiede gegenüber Lippenbekenntnisse ablegen, aber hier draußen zählen die nichts.\n\nLetzte Nacht gab es einen Überfall auf das Lager und ein Überfall ist einer zu viel. Ihr Anführer ist ein stämmiger Kerl mit Namen Finsterblick und er versteckt sich in der Höhle am südlichen Ufer des Flusses.\n\nBringt mir Finsterblicks Bart als Beweis, dass er keine Bedrohung mehr für uns und Eisenschmiede darstellt.", progress = "Zeigt mal her!", completion = "Ein Glück, dass wir den los sind! Ich werde das fiese Ding später verbrennen, damit es uns nicht das Lager zustinkt.", rewards = "Gamaschen des FeldmessersBöser GürtelPapiertigerarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25728] = {title = "Baunzers wilder Ritt", objective = "Tötet 20 Goblintechniker und 5 Goblinernter.", description = "Jetzt braucht Herr Baunzer nur noch einen Engel, der ihm als Navigator dient. Würdest du dieser Engel sein, <Onkel/Tante>? Mit deiner Hilfe können wir auf die Klippe hinaus und ganz ganz viele Hordies töten! Was sagst du? Ach bitte, <Onkel/Tante>! BITTE BITTE BITTE!\n\nWenn wir genug Hordies töten, kauft Lord Brachweiher uns allen ein Eis!", progress = nil, completion = "&lt;Lord Brachweiher hustet.&gt;\n\nDas ist merkwürdig.\n\nIhr habt da draußen mit dem Roboter gute Arbeit geleistet. Ihr habt mich ein wenig auf dem falschen Fuß erwischt. Ich wusste nicht, dass das kleine Mädchen so...\n\n&lt;Lord Brachweiher zeigt auf seine Schläfe und macht kleine Kreise mit seinem Finger.&gt;\n\nBesonders ist...\n\nNaja, ist ja egal, wie die Sache erledigt wird, nicht wahr? Habe ich recht?\n\nWahrscheinlich.\n\nWollt Ihr ein Eis?", rewards = "Ihr bekommt:\n\nMövenhacks schockierend deliziöse Eiscreme"}
MultiLanguageQuestData['de'][25729] = {title = "Gerenzo der Verräter", objective = "Tötet Gerenzo Pfeifzang.", description = "<Der Gnomcorder springt mit lautem Surren an.>\n\nBitte kommen, <Name>! Seid Ihr da? Isch 'abe gese'en auf die Karte, dass Ihr seid in die Nä' von die Felskesselsee Wasserrad, ist das rischtisch?\n\nOffenbar 'at die Venture. Co sisch einquartiert bei die Rad. Ihr müsst umschauen Eusch, wenn Ihr dort seid. Solltet Ihr se'en die verräterische Gnom mit die Name Gerenzo Pfeifzang, Ihr müsst ihn treten kräftisch in die 'intern für misch und Gnomeregan! Isch werde zahlen fürstlisch!", progress = nil, completion = "&lt;Der Gnomcorder summt laut.&gt;\n\nWunderbar. Jetzt isch kann streischen noch eine Name von meine Liste.\n\nIsch werde misch melden wieder.\n\nXakxak Ende!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25730] = {title = "HÜTET EUCH VOR FELSKIEFER!", objective = "Tötet Felskiefer und bringt Felskiefers riesigen Zahn an Euch.", description = "Auf Befehl der Leute, die nicht an einem Stück von einem richtig großen Fisch verschlungen werden wollen, ist der Zutritt zum Felskesselsee VERBOTEN! Jemand hat beschlossen, einen riesigen, zwergenfressenden Fisch im See anzusiedeln.\n\nEs wird dringend empfohlen, dem See fernzubleiben. Solltet Ihr allerdings der heldenhafte Typ sein und noch ein paar Freunde haben, tut uns doch den Gefallen und tötet das verdammte Ding! Vielleicht kann ich dann hier angeln, nicht wahr?\n\nFalls es Euch wirklich gelingen sollte, sucht mich in der Scherwindfeste für eine Belohnung auf.\n\n-Der alte Eisenbock", progress = "Habt Ihr das Ungeheuer getötet?", completion = "Wer hätte das gedacht. Ihr habt das Ungeheuer tatsächlich erwischt? Nun, abgemacht ist abgemacht! Hier ist Eure Belohnung!", rewards = "FischbetäuberAnglergürtelEisenbocks BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25731] = {title = "Ein Spatz in der Hand", objective = "Löscht ein Harpyiensignalfeuer, um die Aufmerksamkeit Marion Wurmschwinges zu erregen. Kämpft mit ihr, bis Thisalee sie einfängt, und befragt die Harpyienmatrone dann.", description = "Es ist Zeit, dieser Sache auf den Grund zu gehen. Wir müssen die Matrone dieser Wilden befragen, Marion Wurmschwinge. Wir werden sie lebend fangen. Das ist der Plan:\n\nDie Harpyien kommunizieren mit Signalfeuern über den Gebirgskamm hinweg. Wenn wir eines davon löschen, wird Marion sicher kommen, um zu sehen, was damit los ist.\n\nKämpft mit ihr, um sie abzulenken, während ich mich von hinten anschleiche und sie mir schnappe. Die Fragen zu stellen überlasse ich dann Euch. Los, holen wir sie uns, <Name>!", progress = "Marion hat den Schrein hier früher oft besucht. Himmelsfürst Omnuron wollte den Harpyien eine Chance geben, aber ich habe ihr nie vertraut.", completion = "Also sind die Harpyien Werkzeuge einer Art von Drachen, \"Sethria\".\n\nAber was tun die Drachen mit diesen Eiern? Und was ist das für ein \"besonderes\" Ei, das Sethria so unbedingt will?\n\nIch verstehe es nicht, &lt;Name&gt;. Ich habe einen Bericht an Himmelsfürst Omnuron weitergeleitet. Er wird wissen, was als Nächstes zu tun ist.", rewards = "Beinplatten der ÜberzeugungStrafende SchulternAuf Euch wartet eine dieser Belohnungen:\n\nZielgenauer Halsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25732] = {title = "Ein Hühnchen rupfen", objective = "Budd möchte, dass Ihr den Zinnplätter von König Gurboggel auf Gurboggels Fels besorgt.", description = "Wir haben es geschafft!\n\nNager ist erledigt und ich habe unseren Glitzerkram gefunden!\n\nDas sind gute Nachrichten.\n\nDas Kleinod ist verflucht und verwandelt jeden, der es berührt, in ein Skelett.\n\nDas sind schlechte Nachrichten.\n\nLaut diesen verfluchten Piraten kennt der König der Gilblin jedoch das Geheimnis, wie man diesen Fluch brechen kann.\n\nDas sind gute Nachrichten.\n\nIch kann aber keinen Fuß aus diesem Riff setzen, sonst bleibe ich auf ewig verflucht.\n\nDas sind schlechte Nachrichten.", progress = "Also, <Volk>…\n\nBrecht Ihr jetzt diesen Fluch oder was?", completion = "Das ist er?\n\nWie soll das denn den… Moment mal…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25733] = {title = "Pirscht von dannen", objective = "Tötet 7 Höhlenpirscher und 7 Egelpirscher.", description = "Thelgenfelsen ist hier ein wichtiger Ort. Wir brauchen ihn, um dort den felsigen Untergrund und so was zu untersuchen.\n\nDa einem nichts im Leben leicht gemacht wird, gibt es am Thelgenfelsen riesige Höhlenpirscher. Sie sind so groß wie ein Zwerg und zweimal so hungrig. Wie ich schon sagte, diese modischen Kerle sind Forscher und keine Krieger, also wenn ich möchte, dass sie überhaupt etwas geschafft bekommen, müsst Ihr mir helfen, diese Viecher zu beseitigen.\n\nTötet so viele dieser Quälgeister, wie Ihr könnt und es soll Euer Schaden nicht sein, <Name>.", progress = nil, completion = "Gute Arbeit! Es würde mich nicht überraschen, wenn diese schrecklichen Dinger irgendwo da drin Eier abgelegt hätten, aber für den Moment reicht es.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25734] = {title = "Unten im Thelgenfelsen", objective = "Holt den seismischen Bericht von Thelgen aus Thelgenfelsen.", description = "Ich bin jetzt nicht mehr ganz so wackelig auf den Beinen, also werde ich anfangen, das Nivelliergerät für meine letzten Messungen aufzubauen. Eins benötige ich noch von Euch.\n\nTief im Thelgenfelsen steht ein Seismograph, um alle Bewegungen der Erde aufzuzeichnen. Wenn sich seit der Katastrophe noch etwas bewegt hat, wird er es uns zeigen.\n\nDer Seismograph ist ganz unten in der Höhle. Findet ihn und bringt den Bericht, den er aufgezeichnet hat, zu mir.", progress = "Dann schauen wir mal, was wir da haben, nicht wahr?", completion = "Wunderbar, mein Freund. Das dürfte alles sein, was wir brauchen. Schauen wir mal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25735] = {title = "Pyrophorerz", objective = "Findet 8 Stücke Pyrophorerz.", description = "Telgenfelsen dort drüben ist so eine Art Wunder der Natur. Dort liegt die weltweit einzige bekannte Quelle von Pyrophorerz.\n\nDas Zeug ist selten, heiß begehrt und einfach nur lächerlich explosiv. Wenn man mit einer Spitzhacke aus Stahl daraufschlägt, gibt es ein Feuerwerk, das einen Raum voller Goblins vor Neid erblassen ließe.\n\nZum Glück habe ich für solche Gelegenheiten eine funkenresistente Spitzhacke erschaffen. Ich werde sie Euch leihen, wenn Ihr mir ein bisschen Pyrophorerz bringt. Natürlich bekommt Ihr auch etwas vom Gewinn ab.", progress = "Nun, Ihr seht so aus, als ob Euch kein Haar gekrümmt wurde.", completion = "Großartig! Wunderschön, dieses Erz.\n\nGut, dass Ihr Eure Spitzhacke nicht verloren habt. Die letzte Person, die ich dort hinausgeschickt habe, hat das untere Ende auf dem Boden aufschlagen lassen - und der Teil ist nicht funkensicher.", rewards = "Marmorbarts BoleroFunkensichere HandschuheStabilisierte PyrophorgamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25736] = {title = "Der Flutwellenkern", objective = "Bringt den Flutwellenkern zu Forba Fliesmeißel.", description = "Das ist alles, was von dem riesigen Elementar, der Euch angegriffen hat, übrig geblieben ist: eine schäumende Kugel des Wassers, die sich weiter Eures Griffes zu entziehen versucht.\n\nForba wäre über einen weiteren Beweis, dass Ihr noch eine Bedrohung vom Lager abgewendet habt, sicherlich erbaut.", progress = "Häh? Was habt Ihr da?", completion = "Das Ding hat ja immer noch Kampfeswillen! Erstaunlich!\n\nIhr seid zäh, &lt;Name&gt;. Ich weiß das zu schätzen. Ich würde sagen, dass eine Belohnung angebracht ist, bevor Ihr fortgeht.\n\nTut weiterhin Euer Bestes für Eisenschmiede, verstanden? Und solltet Ihr jemals meiner Schwester begegnen, grüßt sie von mir.", rewards = "FlutwellenmantelWasserfeste GamaschenFliesmeißels StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25737] = {title = "Vorsichtige Verhandlungen", objective = "Sprecht mit König Gurboggel.", description = "Nach dem, was ich über diese Wassergoblins weiß, sollte das funktionieren.\n\nIch habe aus den Gegenständen, die Ihr mir zusammengeplündert habt, eine Haizahnkette gebastelt. Es ist nicht nur ein hübsches Schmuckstück, sondern auch eine Erinnerung an Nagers Tod. Schwer zu sagen, wie viele Gilblins dieses Monster bei lebendigem Leib verschlungen hat.\n\nBietet dem Anführer der Gilblins die Halskette an. Als Tausch benötige ich ein Artefakt, das als Zinnplätter bekannt ist.\n\nUnd beeilt Euch, <Bursche/Mädel>. Ich beginne schon, mein Fleisch zu vermissen...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25739] = {title = "Wenn die Horde Euch nicht erwischt...", objective = "Tötet Königin Silith.", description = "<Hauptmann Kosak hustet schwach.>\n\nWar unterwegs zum Weberpass, kam vom Basislager der Nordwachtexpedition im Süden. Hinterhalt. Nicht von Horde. Spinnen. Große, hässliche, haarige, gemeine Spinnen.\n\nDutzende in die Flucht geschlagen, vielleicht Hunderte. Konnte nicht mehr zählen. Überwältigt von der Königin. Hat ein Stück aus mir herausgebissen. Bin nur um ein Haar lebend entkommen. Sterbe vielleicht.\n\nMehr meiner Leute sind unterwegs. Muss sicheren Durchgang gewährleisten. Tötet Spinnenkönigin.\n\n<Hauptmann Kosak wird bewusstlos.>", progress = nil, completion = "&lt;Hauptmann Kosak zwingt sich zu einem Lächeln.&gt;\n\nMacht Euch um mich keine Sorgen. Jetzt, da der große Held die Spinnenkönigin getötet hat, wird alles gut.\n\nVerstärkung kann hier jetzt sicher passieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25740] = {title = "Auf der Suche nach Fakten", objective = "Meldet Euch bei Thisalee am Eingang zu Sethrias Nest auf dem Hyjal.", description = "Der Drache Sethria muss aufgehalten werden. Wir wissen, dass sich ihr Nest im Süden an den südlichen Klippen des Hyjal befindet, aber das ist leider fast schon alles.\n\nIch habe Thisalee auf der Suche nach Fakten zu Sethrias Nest geschickt. Sie hat speziell um Eure Hilfe gebeten. Ihr scheint die junge Druidin schwer beeindruckt zu haben.\n\nTrefft Euch mit Thisalee direkt hinter dem Tunnel, der zu Sethrias Nest führt. Und vergesst nicht, wir sind hier auf der Suche nach Fakten. Tut bloß nichts Verrücktes!", progress = nil, completion = "Ah, &lt;Name&gt;! Ich hatte gehofft, Euch hier draußen wiederzusehen.\n\nWas, Omnuron nennt dies eine \"Suche nach Fakten\"? Pah! Fakten findet man am besten bei Leichen.\n\nLasst uns etwas Schaden anrichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25741] = {title = "Auf die Zukunft vorbereiten", objective = "Besorgt 10 Kluftmoosgiftbeutel.", description = "Vergiftete Reisende kommen um die Scherwindfeste immer häufiger vor. Gerade vor ein paar Tagen fiel ein Hauptmann der Nordwacht den Spinnen der Weberkuhle zum Opfer. Er wäre an dem Gift gestorben, wenn ich kein Gegengift gehabt hätte. Leider ist mein Vorrat an Gegengift beinahe erschöpft.\n\nWenn Ihr nach Süden in Richtung Weberkuhle unterwegs seid, würdet Ihr freundlicherweise einige Kluftmoosgiftbeutel für mich besorgen? Ihr solltet sie von Kluftmoosspinnen erhalten.", progress = "Habt Ihr die Giftbeutel, um die ich Euch gebeten hatte, bekommen?", completion = "Das dürfte uns auf absehbare Zeit mit Gegengift versorgen. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25743] = {title = "Entscheidungen, Entscheidungen", objective = "Benutzt den Zinnplätter, um den Zinnpropheten zu zerstören.", description = "Das ist keine magische Lösung für meinen Fluch! Das ist nur ein Hammer!\n\nIch bin vielleicht verrückt, aber ich bin nicht dumm.\n\nIch werde das hier AUF GAR KEINEN FALL benutzen, um meinen Glitzerkram kaputt zu machen! Nicht nach allem, was ich durchgemacht habe, um an ihn zu kommen!\n\n<Budd hält einen Moment inne, um nachzudenken.>\n\nAber das bedeutet, dass ich bis in alle Ewigkeit hier unten festsitze...\n\nUnd ich habe doch gerade erst gelernt, wie man segelt.\n\nOhhh... ich kann mich nicht entscheiden.\n\nHier, nehmt Ihr den Hammer. Ich stelle den Glitzerkram einfach auf den Boden und schaue weg.", progress = nil, completion = "Oh, wie schön hätte es sein können…", rewards = "Gehämmerte LötzinnketteHandgelenksschützer des prophetischen TodesGötterzermalmender HandschutzDer folgende Zauber wird auf euch gewirkt:\n\nPing Budd\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25744] = {title = "Verhandlungen", objective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", description = "<Name>, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Crazzle Flinkspross und Kravel Kohlebart nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", progress = nil, completion = "&lt;Crazzles Augen leuchten auf.&gt;\n\nIch habe Kravel Kohlebart hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25745] = {title = "Verhandlungen", objective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", description = "<Name>, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Riznek und Rennstreckenleiter Zherin nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", progress = nil, completion = "&lt;Rizneks Augen leuchten auf.&gt;\n\nIch habe Rennstreckenleiter Zherin hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25746] = {title = "Sethrias Brut", objective = "Tötet 12 von Sethrias Dienern: Eine beliebige Kombination aus Zwielichtdrachkin oder Rüstungsschmieden der Zwielichtdrachkin.", description = "Unsere erste Aufgabe besteht darin, die Herde hier auszudünnen. An diesem Ort wimmelt es nur so von ihnen.\n\nTötet zunächst diese Drachkin und macht Euch erst später Gedanken darüber, warum wir hier sind.", progress = nil, completion = "Das scheint Euch zu liegen.\n\nIch mag Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25747] = {title = "Ein Blick nach vorne", objective = "Sprecht mit Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir.\n\nBenutzt Wellensprecherin Valorens Seepferd, um den Vorposten schnell zu erreichen.", description = "Der Admiral hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er bereitet sich dort auf eine Art Angriff auf die Naga vor.\n\nIhr solltet sofort zu ihm gehen und ihm von den Massen berichten, die Ihr beobachtet habt. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferd. Es kennt den Weg.", progress = nil, completion = "Schön Euch wiederzusehen, &lt;Klasse&gt;. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25748] = {title = "Deutliche Ziele", objective = "Tötet 10 Naga der Streitmächte, die sich unter der südlichen Terrasse auf der Grundebene zusammenziehen.", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, <Klasse>. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden ein wenig ausdünnen?", progress = nil, completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25749] = {title = "Nicht ganz unvorbereitet", objective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Allianz, die sich auf den Vorsprüngen unter der südlichen Terrasse befinden.", description = "Ich habe Euer Gespräch mit dem Admiral gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Könntet Ihr ihnen mehr Armbrustbolzen bringen, um uns etwas Zeit zu verschaffen?", progress = nil, completion = "Ihr seid wahrscheinlich das zuverlässigste Wesen, das ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", rewards = "GrenzgängergroßhelmSchulterpolster des SeebognersTreter der VerläßlichkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25751] = {title = "Ausreichende Inspiration", objective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südlichen Terrasse hängen.", description = "Hallo! Ich reiße mir hier alle Beine aus, um den Angriff des Admirals vorzubereiten. Er hat große Hoffnungen und hochtrabende Pläne, um alle möglichen Dinge hoch in die Luft zu jagen! … Oder eher hoch ins Wasser? Ja, wohl eher das.\n\nAber um Dinge in die Luft zu jagen, braucht man SPRENGSTOFF! Ich habe keinen Sprengstoff. Es ist traurig. Sehr traurig.\n\nAber ich wurde ausreichend inspiriert, um eine Lösung zu finden. Die Tangblasen, die von den Ruinen hängen, enthalten ein überraschend explosives Gas. Könntet Ihr etwas davon für mich sammeln? Oh bitte, bitte!", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein &lt;Volk&gt; nach meinem Geschmack.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25752] = {title = "Blitzangriff", objective = "Sprecht mit Ingenieur Hexasept außerhalb des Gebäudes, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", progress = nil, completion = "Ihr habt Euch da oben großartig geschlagen! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", rewards = "AtolltreterTigerhaigürtelAuf Euch wartet eine dieser Belohnungen:\n\nPelagisches Prisma\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25753] = {title = "Gefallen, aber nicht vergessen", objective = "Rettet 6 verletzte freiwillige Angreifer.", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", progress = nil, completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25754] = {title = "Einschätzung des Erfolgs", objective = "Späht den nordwestlichen Teil der runden Terrasse und den Tunnel unter der Haupttreppe im Norden aus. Beide Orte befinden sich auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Admiral zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben. Eine ihrer größten Gruppen war um die Ecke im nordwestlichen Teil dieser runden Terrasse, die andere war etwas weiter im Norden, in einem kleinen Tunnel, der auch Teil der mittleren Ebene der Ruinen ist.\n\nSeid Ihr bereit?", progress = nil, completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, &lt;Name&gt;, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25755] = {title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", objective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", progress = nil, completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", rewards = "Handschutz der KvaldirVision der KriegsmaidUralter beth'moranischer UmhangAuf Euch wartet eine dieser Belohnungen:\n\nSchlachtstandarte der Kvaldir\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25756] = {title = "Zehrt an Zherin!", objective = "Erhaltet das Angebot der Horde.", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Horde unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Horde, Rennstreckenleiter Zherin, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Zherin davon, das Angebot der Horde auszuhändigen.\n\nIhr müsst ihn nicht töten ... wir sind ja keine Wilden! Es reicht, wenn Ihr etwas arg an seinen Nerven zehrt.", progress = "Habt Ihr das Angebot der Horde erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Horde so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25757] = {title = "Etwas hart zu Kohlebart!", objective = "Erhaltet das Angebot der Allianz.", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Allianz unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Allianz, Kravel Kohlebart, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Kohlebart davon, das Angebot der Allianz auszuhändigen.\n\nIhr müsst ihn nicht töten ... wir sind ja keine Wilden! Es reicht, wenn Ihr ihn ein bisschen hart rannehmt.", progress = "Habt Ihr das Angebot der Allianz erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Allianz so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25758] = {title = "Eine Lücke in ihrer Rüstung", objective = "Sammelt 8 Panzerplatten des Schattenhammers.", description = "Seht Ihr, was sie da tun? Sie statten ihre Drachkin mit Panzerplatten aus! Das muss Todesschwinges Idee gewesen sein.\n\nDiese Zwielichtmoloche sehen aus, als wären sie unbesiegbar, sobald sie fertig sind. Es muss doch einen Weg um diesen Panzer herum geben!\n\nGeht dorthin und holt Euch einige der Panzerplatten des Schattenhammers, die noch nicht angebracht wurden. Wir müssen herausfinden, wie wir das verhindern können!", progress = "Habt Ihr ein paar Panzerplatten bekommen können? Musstet Ihr jemanden töten, um sie zu bekommen?\n\nIch hoffe doch sehr!", completion = "Schaut Euch diese Dinger an. Uff, die Runen schmerzen mir in den Augen. Diese hier soll Fleisch versengen? Im Ernst? Autsch! Moment mal…\n\nDiese Platten müssen direkt im Fleisch festgenietet werden. Die Schmerzen müssen unerträglich sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25760] = {title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", objective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", progress = nil, completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Admiral es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Admiral und seine Soldaten. Wir müssen sie warnen.", rewards = "Naz'jars BrustschutzGurt des WundenversorgersAuf Euch wartet eine dieser Belohnungen:\n\nFokus der Wellensprecherin\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSee Quest Invis 2\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25761] = {title = "Demontage", objective = "Benutzt Thisalees Messer, um 3 Zwielichtmoloche zu wecken und zu töten. Das Messer kann mehrfach verwendet werden, um die Rüstung eines Molochs herunterzureißen.", description = "Wir müssen diese Moloche aufhalten, bevor sie komplett in Rüstung gehüllt sind. Im Augenblick sind sie noch verwundbar, aber auch nur, wenn wir an den Platten vorbei in das kranke Fleisch darunter stoßen können.\n\nNehmt mein Messer und rammt es zwischen die Platten der bewehrten Moloche, um ihnen die Rüstung zu rauben.\n\nSobald sie aus ihrer Trance erwachen, solltet Ihr Euch auf einen harten Kampf gefasst machen. Löst einfach weiter ihre Rüstung und haltet diese Moloche auf!", progress = "Oh, gut.\n\nIhr seid noch am Leben.", completion = "Das nenne ich atemberaubende Klingenkunst, &lt;Name&gt;!\n\nUnd wieder eine Bedrohung weniger auf dem Hyjal, um die wir uns sorgen müssen.", rewards = "Weggeworfene MolochpanzerungKlingenreissergurtBrustschutz des gewandten MessersAuf Euch wartet eine dieser Belohnungen:\n\nKlaue der zerstörten Hoffnung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25762] = {title = "Die uralte Kohlenpfanne", objective = "Entfacht die uralte Kohlenpfanne wieder und erhaltet die heilige Flamme.", description = "Was haben wir denn hier? <Ein/Eine:r> <Volk>? Ihr seid wohl hier, um unser Land mit Süßholzraspelei und Versprechen zu stehlen?\n\nIhr könnt mich nicht täuschen. Ich habe schon viele Winter gesehen und weiß, wie man mit jemandem wie Euch umgehen muss. Die Khans hören jedoch nicht mehr auf die Ältesten, wie sie es einst taten.\n\nDa Ihr schon einmal hier seid, werde ich dafür sorgen, dass Ihr Euch nützlich macht. Als das Wasser über uns hereinbrach, hat der große Wassergeist Aquarian die uralte Kohlenpfanne in der Spalthufhöhle gelöscht.\n\nEntfacht die Kohlenpfanne wieder. Aquarian wird erscheinen. Bringt mir die heilige Flamme.", progress = "Habt Ihr die heilige Flamme? Wagt es nicht, sonst mit mir zu sprechen, <Volk>!", completion = "Ihr habt mir diesen Gefallen getan, um Euch bei mir einzuschmeicheln. So leicht ist das aber nicht.\n\nIch weiß genau, was Ihr vorhabt. Das Meer hat es zwar nicht geschafft, aber der große Luftgeist wird Euch und Euer Volk für all die Vergehen bestrafen, die den Elementen gegenüber begangen wurden.\n\nVerschwindet aus meinen Augen!", rewards = "Tuch der VerachtungGürtel der falschen VersprechungenSchienbeinschützer der heiligen FlammeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25763] = {title = "Der Kodex der Schatten", objective = "Meldet Thisalee Krähe bei Sethrias Nest auf dem Hyjal Eure Entdeckungen.", description = "<Dieses kunstvolle Buch besteht aus Hunderten von Seiten feinsten Pergaments und ist in Schiefer gebunden. Es ist in vielen Sprachen geschrieben, wovon Euch die meisten unbekannt sind. Aufwändig gezeichnete Bilder zeigen Zauberer oder gar ganze Gebäude, die hinter Schleiern aus Schatten verschwinden.>\n\n<Viele der Bilder zeigen magische Artefakte wie jene, die Ihr um das Lager herum seht. Ihr vermutet, dass die Drachendame Sethria etwas versteckt halten möchte. Thisalee will sicher davon erfahren!>", progress = nil, completion = "Sie tun was?\n\nSie verhüllen etwas? Aber natürlich! Damit unsere Späher in den Lüften es nicht mit ihren Adleraugen entdecken können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25764] = {title = "Eierjagd", objective = "Deaktiviert die Schattentarnungsgeneratoren, bis Ihr Avianas Ei gefunden habt. Sobald das Ei enttarnt wurde, verteidigt es, bis die Druiden der Klaue es in Sicherheit bringen können.", description = "Himmelsfürst Omnuron möchte, dass wir Avianas Ei finden. Ich kann Euch fast schon garantieren, dass es von einem von Sethrias Schattengeräten getarnt wird.\n\nSucht um das Lager herum nach Schattentarnungsgeneratoren und schaltet diese Dinger aus, bis Ihr das Ei gefunden habt.\n\nSobald Ihr es enttarnt habt, ruft die anderen Druiden herbei. Verteidigt das Ei, bis wir es in Sicherheit gebracht haben.\n\nLos, holt Euch das Ei, <Name>!", progress = nil, completion = "Wir haben es geschafft, &lt;Name&gt;! Avianas Ei sollte bald schon sicher in den Zweigen ihres Schreins liegen.\n\nMeint Ihr, dass sie dann wirklich zu uns zurückkehren wird?", rewards = "Helm des TarnungsbrechersTunika des sicheren DahingleitensSandalen des lichten HerzensAuf Euch wartet eine dieser Belohnungen:\n\nEierdiebstahlstalisman\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25765] = {title = "Sagt ihnen, Koko schickt Euch", objective = "Meldet Euch bei Truppenkommandant Valen am Basislager der Nordwachtexpedition im Steinkrallengebirge.", description = "<Ein mächtiger/Eine mächtige:r> <Volk> wie Ihr wäre in Nordwacht wirklich von Nutzen. Wir haben eine Niederlage im Südlichen Brachland einstecken müssen und benötigen Eure Hilfe! Hättet Ihr Interesse daran, der Allianz behilflich zu sein?\n\nDie Bombe? Ja, sie ist ein Problem, aber das Steinkrallengebirge zeichnet sich nicht gerade durch seinen Grundstückspreis aus. Diese Gegend war schon ein Drecksloch, bevor die Horde ihre Klauen danach ausgestreckt hat!\n\nIch überlasse die Entscheidung Euch. Wenn Ihr uns im Brachland aushelfen wollt, nehmt mein Pferd Blaustahl. Er grast an der Kreuzung südlich von hier. Er wird Euch an der ersten Orcsperre vorbeitragen.", progress = nil, completion = "Kosak hat Euch geschickt, ja? Erstaunlich. Ich hatte mit Sicherheit angenommen, dass er bereits tot ist.\n\nNun, wenn Ihr es an der Blockade vorbei geschafft habt, dann habt Ihr auf jeden Fall etwas, das wir brauchen können.\n\nHabt Ihr irgendwelche Neuigkeiten von der Horde? Was machen sie? Wohin gehen sie? Erzählt mir alles.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25766] = {title = "Arkanes Vermächtnis", objective = "Benutzt das Gefängnis der Hochgeborenen, um 5 Geister der Hochgeborenen zu binden.", description = "Der Zorn der Elementare hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht.\n\nDirekt im Südwesten vor hier, hinter dem Sishircanyon, findet Ihr die Ruinen von Eldre'thar. In den Ruinen liegen Schätze, die seit zehntausenden Jahren nicht von Sterblichen angerührt wurden!\n\nNehmt dieses Gerät und benutzt es gegen die Geister der Hochgeborenen, die die Ruinen bewohnen. Es wird... ihre Seelen zur letzten Ruhe betten und außerdem wertvolle Daten sammeln, die ich später auswerten kann.", progress = nil, completion = "Ich versichere Euch, Ihr Einfaltspinsel, die Geister, die Ihr gefangen habt, finden jetzt ihre Ruhe. Lasst Euch nicht von ihren Protesten aus der Ruhe bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25767] = {title = "Erinnerungen einfangen", objective = "Besorgt 8 Relikte von Eldre'thar.", description = "Der große Kataklysmus hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht. Ihr müsst Euch nach Südwesten zu den Ruinen von Eldre'thar begeben. Wenn Ihr dort seid, durchsucht die Gegend nach uralten Relikten. Bringt die Relikte zu mir, damit ich sie untersuchen kann, <Name>.\n\nLos! Wir dürfen den Arkanisten nicht warten lassen!", progress = "Habt Ihr die uralten Relikte gefunden?", completion = "Wunderbar! Arkanist Valdurian wird außerordentlich zufrieden sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25768] = {title = "Feuer frei: Mirkfallonposten!", objective = "Meldet Euch bei Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge.", description = "Späherkommandant Barus ist am Mirkfallonposten im Nordwesten stationiert und hat die Bombe der Horde entdeckt. Der Heißluftballon von Krom'gar, an dem die Bombe angebracht ist, befindet sich momentan bei der neuen Goblintankstelle am Mirkfallonsee. Das könnte die Gelegenheit sein, die wir brauchen, um das Ding ein für alle Male zu beseitigen.\n\nNehmt Eure Siebensachen, <Name>, und macht Euch auf den Weg! Späherkommandant Barus erwartet Eure Ankunft am Mirkfallonposten.\n\nUnd <Name>, Eure Hartnäckigkeit macht der Stärke und Tapferkeit der Allianz alle Ehre!\n\nMöge der Ruhm mit Euch sein!", progress = nil, completion = "Ich nehme einmal an, dass Ihr den Heißluftballon von Krom'gar auf Eurem Weg hierher gesehen habt? Wenn nicht, lasst Eure Augen untersuchen. Er schwebt direkt über der Ölplattform.", rewards = "Ölverschmierte ArmschienenGut geölter HelmBarus' NotfallschwertAuf Euch wartet eine dieser Belohnungen:\n\nRing des Ölers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25769] = {title = "Brachweiher ruft", objective = "Sprecht mit Lord Brachweiher an der Scherwindfeste im Steinkrallengebirge.", description = "Ihr seid hier? Worauf wartet Ihr - eine persönliche, gravierte Einladung? Lord Brachweiher ruft, Narr! Geht zu ihm - jetzt!", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;. Ich habe Neuigkeiten vom Mirkfallonsee.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25770] = {title = "Fasslieferung", objective = "Bringt das Gebirgsjägerbier zu Forba Fliesmeißel an Fliesmeißels Messstation.", description = "Also gut. Wir müssen dieses Bier sofort an seinen Bestimmungsort bringen!\n\nEisenschmiede hat eine Gruppe Feldmesser ausgeschickt, um den Schaden im Sumpfland zu überprüfen, der bei dem Dammbruch entstanden ist. Forba Fliesmeißel leitet die Expedition... und glaubt mir, Ihr wollt Euch nicht mit ihr anlegen!\n\nMit einer Ladung Bier bei ihr aufzutauchen, kann nicht schaden. Geht und bringt ihr das hier und sie wird Euch vielleicht bitten, die ein oder andere Arbeit für sie zu verrichten.", progress = "Ja? Was habt Ihr da für mich?", completion = "Ha! Schön, dass die hohlköpfigen Gebirgsjäger genug Grips haben, um das Bier einem richtigen Mann zu überlassen, damit die Arbeit auch erledigt wird.\n\nWillkommen in meiner Messstation. Wenn Euch der Sinn danach steht, Eisenschmiede zu helfen, indem Ihr die Jobs einiger nutzloser, fauler Säcke, die sich Zwerge nennen, übernehmt, dann seid Ihr an der richtigen Adresse!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25771] = {title = "Des einen Draeneis Plunder...", objective = "Bringt das unvollständige Draenethystfragment zu Kum'isha dem Sammler in den Verwüsteten Landen.", description = "Ein Bruchstück glitzernden Steins liegt vor Euch. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", progress = "Und? Draenethyst?", completion = "Nur ein Splitter? Pah! Das nützt mir gar nichts! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKlingt bekannt? Sollte es auch, weil ich es tausend Mal am Tag sage.\n\nOh, wie ich diese Welt hasse.", rewards = "Ihr bekommt:\n\nKum'ishas Plunder"}
MultiLanguageQuestData['de'][25772] = {title = "Kum'ishas Bemühungen", objective = "Bringt die fehlerlose Draenethystsphäre zu Kum'isha dem Sammler in den Verwüsteten Landen.", description = "Vor Euch liegt eine schimmernde Kugel. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", progress = "Habt Ihr eine fehlerlose Draenethystsphäre gefunden?", completion = "Einfach erstaunlich. Ich hatte so meine Zweifel, dass irgendwer noch eine Sphäre finden würde, aber hier ist sie und pulsiert in meinen Händen.\n\nGut gemacht, &lt;Name&gt;!\n\nSolltet Ihr noch weitere finden - wobei ich glaube, dass das unmöglich ist -, dann bringt sie mir und ich werde Euch erneut belohnen.", rewards = "Ihr bekommt:\n\nSmaragdbesetzte Truhe"}
MultiLanguageQuestData['de'][25774] = {title = "Katzengold", objective = "Sammelt 8 Pyriterzbrocken.", description = "Von so viel Gold, wie die Horde anbietet, können wir NUR TRÄUMEN. <Name>, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25775] = {title = "Katzengold", objective = "Sammelt 8 Pyriterzbrocken.", description = "Von so viel Gold, wie die Allianz anbietet, können wir NUR TRÄUMEN. <Name>, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25776] = {title = "Sethrias Untergang", objective = "Tötet den Drachen Sethria. Sobald sie ihre wahre Form offenbart, benutzt die Signalrakete, um Verstärkung zu rufen.", description = "Während Ihr Sethrias Nest überfallen habt, gab es einen regen Austausch von Botschaften zwischen uns und dem Schrein. Himmelsfürst Omnuron hat sich zunächst geziert, aber schließlich konnte ich meine Druidenfreunde überreden, einen direkten Angriff auf Sethria selbst zu wagen.\n\nAlle haben meinem Plan zugestimmt... unter einer Voraussetzung. IHR sollt den Angriff anführen.\n\nNehmt diese Signalrakete und stellt Euch Sethria auf dem hinteren Sims. Wenn sie ihr wahres Ich zeigt und in ihre Drachenform wechselt, schießt die Rakete ab und fordert Verstärkung an!", progress = "Wenn ein geringerer Drache wie Sethria uns schon so viele Probleme bereiten kann, möchte ich gar nicht wissen, was der Schattenhammer sonst noch auf Lager hat…", completion = "Sethria ist nicht mehr! Ich wusste, dass es das Risiko wert ist.\n\nIch bleibe hier, um nach Überlebenden zu suchen, aber ich schätze, Eure Anwesenheit wird am Schrein gewünscht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25777] = {title = "Vorwärts nach Menethil", objective = "Liefert Fliesmeißels Bericht bei Hauptmann Starkfaust im Hafen von Menethil ab.", description = "Diese Neuigkeiten müssen so schnell wie möglich nach Menethil gelangen. Ich werde Euch mit meinem schnellsten Widder auf den Weg schicken, <Name>.\n\nEr kennt den Weg - Ihr müsst nur darauf achten, dass Ihr fest im Sattel sitzt und Euch gut festhaltet.\n\nTrödelt nicht im Lager herum. Wir müssen die Nachricht schnell überbringen!", progress = "Willkommen in Menethil, Fremder. Ich hoffe, Ihr habt gute Neuigkeiten oder etwas Hochprozentiges bei Euch.", completion = "Lasst mich mal sehen.\n\nNa großartig... \"Schwerwiegende geologische Instabilität\"? \"Gefahr einer plötzlichen, massiven topologischen Destabilisierung\"?\n\nSchön zu hören, dass hier etwas Schlimmes passieren könnte. Dann sollten wir vielleicht besser unsere überflutete Stadt zusammenpacken und mit ihr irgendwo hinfliegen, wo es sicher ist!\n\nBah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25778] = {title = "Falsches Gold für schwarzes Gold", objective = "Bringt die Palette voller \"Gold\" zu Khan Ablinh in den Spalthufanhöhen in Tausend Nadeln.", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Ablinh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wir gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25779] = {title = "Falsches Gold für schwarzes Gold", objective = "Bringt die Palette voller \"Gold\" zu Khan Blizh in den Spalthufanhöhen in Tausend Nadeln.", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Blizh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wird gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25780] = {title = "Angriff auf Burg Menethil", objective = "Tötet Horghast Loderwahn.", description = "Wir hatten uns kaum nach der Flut wieder zusammengerauft, als die Dunkeleisenzwerge die Stadt angriffen. Meine Männer und ich sind der Stadtbevölkerung zu Hilfe geeilt, aber die irren Dunkeleisenzwerge haben sich in die Burg zurückgezogen.\n\nSie haben sich da richtig eingegraben und wir können die Burg nicht zerstören. Nicht jetzt, da die halbe Stadt schon in Trümmern liegt.\n\nNehmt meinen Platz ein, <Name>. Ich würde mir den Anführer ja vorknöpfen, aber er hat mir einen schweren Schlag versetzt. Verschafft Euch Zugang zur Burg, tötet Horghast und bereitet allem ein Ende!", progress = nil, completion = "Er ist tot! Den Schöpfern sei Dank...\n\nMir gefällt gar nicht, wie die aussehen. Die Dunkeleisenzwerge, mit denen ich bisher zu tun hatte, waren niemals so verrückt. Irgendwas ist mit diesen Schwachköpfen geschehen...", rewards = "Zauberstab der ansteckenden DemenzStarkfausts BrustplatteFlammentoller UmhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25790] = {title = "Zurück zu Crazzle", objective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", progress = nil, completion = "Sie haben WAS?!", rewards = "Verdächtige PantoffelnWeste des SchwindlersGürtel des UngetäuschtenKompromissloser HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25791] = {title = "Zurück zu Riznek", objective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", progress = nil, completion = "Sie haben WAS?!", rewards = "Verdächtige PantoffelnWeste des SchwindlersGürtel des UngetäuschtenKompromissloser HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25792] = {title = "Vorwärts drängen", objective = "Benutzt die Rune des Feuers, um 4 Totems der Konstriktion an der Frontlinie der Frostmähnen zu zerstören.", description = "Die meisten der Gebirgsjäger und Dampfpanzer in Dun Morogh kämpfen an der Frontlinie der Frostmähnen, die sich uns aus Südosten nähert. Wir können kaum die Trolle zurückhalten, geschweige denn, in ihr Dorf vorrücken und ihren Anführer angreifen.\n\nSie haben unseren Zugangspfad mit mysteriösen Totems blockiert, die allen sich nähernden Gebirgsjägern die Luft nehmen und ihre Opfer dadurch hilflos ihren Feinden überlassen. Auf diesem Stein ist eine Rune des Feuers eingraviert. Er sollte in der Lage sein, die Totems zu zerstören und unsere Gebirgsjäger zu befreien.", progress = nil, completion = "Endlich gibt es mal gute Nachrichten von der Frontlinie der Frostmähnen. Ich werde dafür sorgen, dass die Gebirgsjäger sofort vorrücken und angreifen. Jetzt müssen wir unseren Gnomverbündeten am Depot signalisieren, dass sie ihren Vormarsch beginnen können.", rewards = "Knorriger KurzstabScharfe AxtCampingmesserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25793] = {title = "Die Ausufernden Tiefen", objective = "Sprecht mit Stahlzeh McGee an den Ausufernden Tiefen im Steinkrallengebirge.", description = "Sinn und Zweck dieser Basis war es, im Steinkrallengebirge für Theramore Fuß zu fassen und eine Nachschublinie für die Nachtelfen zu eröffnen. Leider hat die Horde erbitterte Gegenwehr geleistet. Höllschreis Armeen sind mächtig und unnachgiebig. Ich habe so eine Heftigkeit von der Horde seit dem zweiten Krieg nicht erlebt.\n\nJetzt scheint es so, dass die Mine, die die Forscherliga ausgehoben hat, von der Horde dazu benutzt wird, uns zu umgehen. Wir müssen die Mine versiegeln!", progress = nil, completion = "Versiegeln? Das ist ganz schön viel Arbeit, mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25794] = {title = "Zuflucht unter dem Meer", objective = "Benutzt Erunaks Seherkugel, um die Position der Tiefennebelgrotte zu sehen.", description = "Ich glaube, ich habe den Verfasser Eurer Notiz gefunden, Freund.\n\nWie es aussieht, braucht er dringend Hilfe, um zu überleben.\n\nIch werde eine meiner Seherkugeln vorbereiten, damit Ihr ihn selbst sehen könnt.", progress = "Habt Ihr Euch die Position der Höhle eingeprägt, <Name>?", completion = "Wir müssen uns beeilen!\n\nWie Ihr seht, hat er nicht mehr viel Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25795] = {title = "Rückkehr zum Schrein", objective = "Kehrt zu Choluna am Schrein von Aviana auf dem Hyjal zurück.", description = "Avianas Ei sollte sicher am Schrein angekommen sein. Geht ruhig und seht es Euch an! Choluna weiß sicher, was zu tun ist.\n\nIch werde unsere Aufgabe hier noch abschließen und stoße dann später zu Euch.", progress = nil, completion = "&lt;Name&gt;! Ist es wahr, dass Ihr einen Angriff gegen einen Zwielichtdrachen geführt habt?\n\nIhr seid wirklich der Herold der Ahnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25796] = {title = "Enteignung", objective = "Tötet 15 Zentauren der Spalthufanhöhen.", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, <Name>. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", progress = nil, completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25797] = {title = "Enteignung", objective = "Tötet 15 Zentauren der Spalthufanhöhen.", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, <Name>. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", progress = nil, completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25798] = {title = "Verteidigt den Turm!", objective = "Verteidigt den Ölbohrturm.", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", progress = nil, completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25799] = {title = "Verteidigt den Turm!", objective = "Verteidigt den Ölbohrturm.", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", progress = nil, completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25800] = {title = "Wenn das Leben dir Krabben schenkt...", objective = "Findet 5 fleischige Kriecherklauen von Hafenkriechern.", description = "Es gibt hier viel zu tun, <Klasse>, aber wir dürfen die Augen nicht vor den Geschenken des Schicksals verschließen.\n\nAls die Flut über unsere Häuser hereinbrach, schwemmte sie viele Meeresbewohner an. Die Bucht von Menethil ist jetzt voller großer Krabben, die genau richtig sind, um sie einzusammeln.\n\nWenn das Leben dir Krabben schenkt, geh Krabbenfischen, sag ich immer. Bringt mir die größten und fleischigsten Scheren, die Ihr finden könnt und ich bezahle Euch.", progress = "Vergesst die kleineren Scheren - das Fleisch ist die viele Arbeit, es aus den Scheren zu holen, nicht wert.", completion = "Ein herzhaftes Meeresfrüchtedinner wird die Stimmung bei allen heben und uns dabei helfen, die Stadt wieder aufzubauen. Danke für die Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25801] = {title = "Klauen aus der Tiefe", objective = "Holt Euch Gobblers Kopf von Gobbler und tötet 12 beliebige Murlocs der Blaukiemen.", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, &lt;Name&gt;.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine.", rewards = "Sandalen der HandelsmarineWatstiefel der HandelsmarineStiefel der HandelsmarineSchulterstücke der HandelsmarineIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25802] = {title = "Waren-Wiederbeschaffung", objective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die 'Blinde Prinzessin', von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murlocs an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Statuette von Menethil und bringt sie mir wieder.", progress = nil, completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet eine Handvoll rot gefärbter Flaschen.", rewards = "Ihr bekommt:\n\nHeiltrank"}
MultiLanguageQuestData['de'][25803] = {title = "Die Suche geht weiter", objective = "Sucht nach der Statuette von Menethil.", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur der Statuette von Menethil.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", progress = nil, completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!", rewards = "Ihr bekommt:\n\nZwergenmild"}
MultiLanguageQuestData['de'][25804] = {title = "Suche in weiteren Hütten", objective = "Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil.", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Statuette von Menethil enthalten!", progress = nil, completion = "Dieses Fass ist unter Schlamm und Gras halb begraben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25805] = {title = "Rückgabe der Statuette", objective = "Bringt Karl Boran im Hafen von Menethil im Sumpfland die Statuette von Menethil.", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Statuette von Menethil sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Schärpe der blinden PrinzessinBorans SchulterpolsterBrustplatte des verlorenen PaladinsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25806] = {title = "Sie haben die Assass in... ach, egal", objective = "Tötet 12 Auftragsmörder von Krom'gar.", description = "Ah, die Forscherliga - welche glanzvolle Gruppe von Schwachköpfen. Wir haben nicht nur die Geister der Tauren am Hals, die Forscherliga hat es ebenfalls geschafft, eine Hintertür für die Hauptbasis der Horde im Steinkrallengebirge - der Feste Krom'gar - zu öffnen.\n\nJetzt bringen Auftragsmörder von Krom'gar alle in der Mine um, ohne dass man auch nur einen Mucks hört.\n\nIhr müsst da hineingehen und aufräumen.\n\nBeinahe hätte ich vergessen, Euch diese Brille zu geben. Setzt sie sofort auf. Damit werden alle getarnten Assassinen in der Mine sichtbar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25807] = {title = "Die Wiedergeburt eines Ahnen", objective = "Benutzt das Rauchwerk des Herolds vor Avianas Ei im Schrein von Aviana.", description = "Ich bin davon überzeugt, dass IHR der Herold Avianas seid, <Name>. Ihr wart es, der sie zuerst gesehen hat und ihre Essenz aus den Klauen eines Drachen errettete.\n\nJa, ich glaube, dass Aviana in diese Welt wiedergeboren wird. Und Ihr habt die Ehre, sie über die Schwelle zu führen.\n\nNehmt dieses Rauchwerk und verbrennt es vor Avianas Ei im Raum direkt über mir.\n\nDie Ahnin ist nah, <Name>. Unsere Errettung steht kurz bevor!", progress = nil, completion = "Ich… lebe.\n\nDiejenigen, die versucht haben, mich zu verderben und meine Kinder zu stehlen, werden bald den Hieb meiner Klauen spüren, &lt;Klasse&gt;. Glaubt mir.\n\nDringt weiter auf den Hyjal vor. Ich werde mich sammeln und die anderen Ahnen um mich rufen.", rewards = "HimmelsgriffhandschützerWeihrauchschwenker des HeroldsrufesAuf Euch wartet eine dieser Belohnungen:\n\nSignet der duftenden Beschwörung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25808] = {title = "Ist das Ding an?", objective = "Tötet Meisterassassine Kel'istra.", description = "<Der Gnomcorder summt energiegeladen. Man hört Leutnant Paulson am anderen Ende.>\n\nDämlicher Gnomschrott... Ist da IRGENDWER? <Name>, seid Ihr da?\n\nVielleicht ist <er/sie> tot.\n\nFalls Ihr mich hören könnt - wir haben gerade die Nachricht erhalten, dass eine Meisterassassine der Horde sich in den Minen befindet und die anderen Auftragsmörder befehligt. Findet sie, tötet sie und meldet Euch bei mir.\n\nPaulson Ende.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Eure Arbeit in den Minen war die eines Profis. Wie wäre es, wenn Ihr mir jetzt meine Brille zurückgebt.", rewards = "AssassinenassassinatorUmhang des MinenarbeitersKnisternde SchulterstückePaulsons ArmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25809] = {title = "Lasst niemanden zurück!", objective = "Rettet 8 Verängstigte Minenarbeiter.", description = "Hordenmonster!\n\n<Korporal Wocard spuckt aus.>\n\nSchaut Euch das hier an! Sie haben Unschuldige getötet! Zivilisten!\n\nHört zu, <Name>, Ihr müsst uns helfen. Geht in die Ausufernden Tiefen und sucht nach überlebenden Minenarbeitern. Wenn einige überlebt haben, werden sie wohl vollkommen verängstigt sein! Sucht in allen Nischen und Winkeln der Mine. Vielleicht sogar in den Minenwagen! Es gibt ganz bestimmt Überlebende, die sich irgendwo versteckt haben.", progress = nil, completion = "Dem Licht sei Dank! Ihr seid wahrlich ein rechtschaffendes Instrument der Macht! Die Allianz kann sich glücklich schätzen, Euch zu haben, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25810] = {title = "Die Brutstätte muss brennen", objective = "Reist durch das Flammentor in der Mitte der Flammenschneise auf dem Hyjal. Sprecht mit Farden Klauenwürger, sobald Ihr hindurchgegangen seid.", description = "<Name>! Choluna hat die Wahrheit gesprochen: Die Göttin ist zurückgekehrt! Ein Wunder ist geschehen.\n\nIhr habt zwar den Zwielichtdrachen Sethria töten können, wir haben jedoch noch nicht alle Eier ausfindig gemacht, die die Harpyien ihr gebracht hatten. Thisalee und ich haben ihnen nachgespürt und sind dabei auf eine große Brutstätte in den Feuerlanden gestoßen. Sie ist nicht von dieser Welt, also kann Aviana Euch nicht begleiten.\n\nFliegt nach Süden und tretet durch das Flammentor in der Mitte des Tals. Farden Klauenwürger ist vorausgesandt worden und wird im Inneren auf Euch warten.", progress = nil, completion = "Also ist es wahr. Aviana ist mit Euch als Herold zurückgekehrt.\n\nEs gibt hier viel zu tun. Wir sind tief im Herzen der Feuerlande. Sethria hat gestohlene Eier vom Hyjal hierher geschmuggelt, um ihre eigenen abstoßenden Kreaturen zu züchten: Raubvögel, die für den Krieg ausgebildet sind.\n\nIch hoffe, dass Ihr bereit seid, zurückzuschlagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25811] = {title = "Stilllegung", objective = "Verankert jeweils ein Dynamitbündel am ersten, zweiten, dritten und vierten Träger.", description = "Um diese Mine stillzulegen, müsst Ihr die tragenden Pfeiler in die Luft jagen. Ich kann Euch den benötigten Sprengstoff zur Verfügung stellen, aber Ihr müsst Euch an den Auftragsmördern von Krom'gar vorbeischleichen, um alle Träger zu erreichen.\n\nDie gute Nachricht - wenn man das so nennen kann - ist, dass wir die tragenden Pfeiler immer mit einem großen X markiert haben. Schaut nach diesen Markierungen und befestigt das Dynamit in ihrer Nähe. Sobald ihr das Dynamit angebracht habt, kommt wieder hier hoch und ich werde die Sprengung auslösen.\n\nKabumm!", progress = nil, completion = "Wird schon schiefgehen!", rewards = "TiefenwirkungshelmAuf Euch wartet eine dieser Belohnungen:\n\nRing des MinenversieglersKlappenhalter\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25812] = {title = "Höhlenforscher", objective = "Sprecht mit dem Gefreiten Pollard in der Tiefennebelgrotte.", description = "Schnell, <Name>!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", progress = nil, completion = "Ein… ein &lt;Volk&gt;? Hier?\n\nIch muss wahnsinnig sein…", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHöhlenforscherzwang\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25813] = {title = "Das Horn erklingen lassen", objective = "Tötet Whrrrl.", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, <Name>.", progress = nil, completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25814] = {title = "Das Horn erklingen lassen", objective = "Tötet Whrrrl.", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, <Name>.", progress = nil, completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25815] = {title = "Die Dritte Flotte", objective = "Erhaltet Fitzsimmons' Met aus dem Keller des Gasthauses im Hafen von Menethil.", description = "Ich war einst Erster Maat auf der 'Herrin der Meere', einem Linienschiff der Dritten Flotte von Kul Tiras, der Verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs geritten wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Bringt mir meinen Met, <Klasse>. Er ist unten im Keller des Gasthauses. Auch wenn ich ihn so weit von mir entfernt verstaut habe, ich komme doch nicht ohne aus.", progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25816] = {title = "Zum Umherwandeln verdammt", objective = "Sprecht mit dem Geist des Ersten Maats Snellig.", description = "<Gestärkt fährt Fitzsimmons mit seiner Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden untergegangen ist. Auf einem unserer Schiffe war ein großer und furchtbarer Schatz versteckt und seine gespenstische Macht hält die Seelen meiner Brüder gefangen in den verrottenden Schiffsrümpfen.\n\nIch werde Tag und Nacht von ihnen verfolgt. Der Erste Maat Snellig ruft mich! Er sollte eigentlich tot sein! Bitte, <Name> sucht ihn bei den Schiffswracks und... sagt ihm einfach, er soll mich in Ruhe lassen!", progress = nil, completion = "Fitzsimmons hat Euch geschickt, nicht wahr? Es ist so lange her...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25817] = {title = "Die verfluchte Crew", objective = "Tötet 5 verfluchte Seemänner und 5 verfluchte Marinesoldaten in der Verlorenen Flotte.", description = "Die Seeleute der Dritten Flotte sind durch einen Fluch für immer dazu verdammt, an diesen Ufern voller Qualen entlangzuwandeln. Fitzsimmons Seelenqual hängt mit uns zusammen - solange wir leiden, kann auch er nicht ruhen.\n\nIhr müsst das Leiden der Geister meiner Mannschaftskameraden beenden. Löscht ihre Geister auf dieser Ebene aus und kehrt zu mir zurück.", progress = nil, completion = "Die gequälten Schreie sind erstickt worden... doch die Ursache des Fluchs noch nicht.", rewards = "Umhang der Dritten FlotteHandschuhe der peinerfüllten SchreieSnelligs WesteHandschuhe des FluchaufhebersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25818] = {title = "Brechen des Fluchs", objective = "Besorgt den Geldkassettenschlüssel der 'Kühnheit' von Kapitän Halyndor.", description = "Um den Fluch zu brechen, muss abgerechnet werden. Kapitän Halyndor hat uns alle dazu verdammt, ein verbotenes Artefakt zu begehren, das Auge von Paleth. Sein Geist will es noch immer und wacht über die Schließtruhe seines alten Schiffes, der 'Kühnheit'.\n\nVernichtet die Seele dessen, der uns einst so verfluchte, <Klasse>. Besiegt den Kapitän, nehmt seinen Schlüssel und bringt das Auge von Paleth weit weg von diesem Ort.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25819] = {title = "Das Auge von Paleth", objective = "Bringt das verfluchte Auge von Paleth zu Glorin Stahlbraue im Hafen von Menethil im Sumpfland.", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies muss das schändliche Auge von Paleth sein, das die Seelen dieser Seefahrer verdammt hat.\n\nSolch eine Verderbnis muss ausgemerzt werden. Vielleicht kann Euch ein Priester im Hafen von Menethil helfen.", progress = "Wie kann ich Euch helfen, Junge?", completion = "Das Auge von Paleth? Ihr sagt, Fitzsimmons hat Euch geschickt?\n\nBeim Lichte... nicht schon wieder. Fitzsimmons ist tot, Mädchen. Ihr seid auch nicht der erste, der so zu mir kommt.", rewards = "Stahlbraues alte RobeFitzsimmons' GürtelVerfolgte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25820] = {title = "Die Sorgen einer Mutter", objective = "Tötet 10 Hafenschredderflossen.", description = "Mein Sohn Gimlok ist das Licht meines Lebens. Mein Herz geht auf, wenn ich ihn mit den anderen Kindern spielen sehe.\n\nTrotzdem mache ich mir Sorgen. Nur wenige Meter entfernt, in der Bucht, gibt es Haie. Was, wenn das Wasser so tief ist, dass einer hierher schwimmt...\n\nDer Gedanke ist unerträglich! Ihr habt sicher schon Schlimmeres bewältigt als wir Stadtbewohner, <Volk>. Würdet Ihr diese schrecklichen Haie für mich beseitigen? Wenigstens ein paar?", progress = nil, completion = "Wie wundervoll, dass Ihr so etwas für eine verheiratete Frau wie mich getan habt. Ihr seid zu freundlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25821] = {title = "Ein ganz besonderer Auftrag", objective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", description = "Ihr habt hier unten Bemerkenswertes geleistet, <Name>. Truppenkommandant Valen ist das nicht entgangen. Er möchte Euch sofort sprechen. Er hat Euch für eine besondere Mission ausgewählt - eine, mit der wir die Übergriffe der Horde im Steinkrallengebirge hoffentlich endgültig stoppen werden.", progress = nil, completion = "Schon bei unserer ersten Begegnung wusste ich, dass Ihr eine besondere Schneeflocke seid, &lt;Name&gt;. So besonders, dass ich niemandem außer Euch diese Aufgabe anvertrauen würde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25822] = {title = "Kriegswerkzeug", objective = "Sammelt 10 Waffenkisten der Allianz.", description = "Ich muss Euch noch einmal einer Gefahr aussetzen, <Name>. Im Osten gibt es eine von der Horde erbeutete Ausgrabungsstelle, die reich an Mineralien ist. Kisten mit unseren Waffen befinden sich dort. Sie sind überall verstreut. Die Horde ist erst vor kurzem dort eingefallen. Es ist unwahrscheinlich, dass sie bereits all unsere Ausrüstung gefunden haben.\n\nGeht dorthin und besorgt unseren Grimmtotemfreunden ein paar Waffen!", progress = "Habt Ihr das Kriegswerkzeug gefunden?", completion = "Das sollte reichen, um hundert Grimmtotem auszurüsten! Jetzt müssen wir die Waffen ihrem Häuptling übergeben.", rewards = "Gamaschen des VersorgungslagersBrustschutz des DiplomatenAuf Euch wartet eine dieser Belohnungen:\n\nAmulett der Nordwacht\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25823] = {title = "Die unerbittliche Horde", objective = "Tötet 12 Angehörige der Horde an der Grabstätte.", description = "Es ist zwar äußerst wichtig, dass Ihr die Waffenkisten unverzüglich sichert, aber wir müssen die Grabstätte im Osten auch von der Horde säubern. Wir müssen vollen Zugang zur Ausgrabungsstätte erhalten, sonst können wir keine Nachschublinie für die Grimmtotemverbündeten schaffen.\n\nTötet alle Angehörigen der Horde, denen Ihr an der Grabstätte begegnet, <Name>. Für den Ruhm der Allianz!", progress = nil, completion = "Ich werde der Infanterie befehlen, nachzurücken und die Zurückgebliebenen zu beseitigen. Hätten wir doch zehntausend wie Euch, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25824] = {title = "Befragung", objective = "Sprecht mit Gefreiter Pollard und erfahrt etwas über seine Tortur.", description = "Dieser Soldat stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", progress = nil, completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25825] = {title = "Rohstofflieferung", objective = "Bringt das Fass mit Öl zu Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Also, <Name>, ich will, dass Ihr das Öl zu Fizzel auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", progress = "Was ist das? Ist das Öl?!", completion = "Es ist Öl! Ihr seid ja wirklich von unschätzbarem Wert, &lt;Name&gt;!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", rewards = "AbschiedsgürtelSchöpfeimer des TurbodampfersZischels WesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25826] = {title = "Rohstofflieferung", objective = "Bringt das Fass mit Öl zu Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Also, <Name>, ich will, dass Ihr das Öl zu Pozzik auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", progress = "Hallo noch mal. Ist das Öl?!", completion = "Es ist Öl! Ihr seid wirklich richtig gut, &lt;Name&gt;!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", rewards = "AbschiedsgürtelSchöpfeimer des TurbodampfersPozziks WesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25830] = {title = "Der letzte lebende Wissenshüter", objective = "Findet Nordu, das Urtum der Lehren, in der Flammenschneise auf dem Hyjal.", description = "Ihr habt die Ahnen erweckt, <Name>, aber Aessina, der Geist der Wildnis, schweigt noch immer. Mit ihrer Hilfe können wir diesen Kampf zu unseren Gunsten wenden und den Schaden, den der Schattenhammer angerichtet hat, rückgängig machen.\n\nEs mag jemanden geben, der uns dabei helfen kann. Der älteste der Bäume, Nordu, stand seit Tausenden von Jahren in der Mitte dessen, was heute die Flammenschneise ist. Seine Weisheit ist so alt wie dieser Berg. Wenn dieser alte Baum noch am Leben ist, kann er uns vielleicht dabei helfen, Aessina zu erwecken. Sucht nach ihm!", progress = nil, completion = "Ich… bin noch nicht… entschwunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25832] = {title = "Rückkehr zu Aviana", objective = "Kehrt zu Aviana am Schrein von Aviana auf dem Hyjal zurück.", description = "<Name>, Ihr habt hier alles getan, was Ihr tun könnt. Die ganze Höhle wird bald in sich zusammenbrechen!\n\nIch treibe die letzten schwingenbewehrten Hengste zusammen und stelle sicher, dass das Flammentor hinter mir versiegelt wird.\n\nIhr solltet losgehen und Aviana berichten, dass diese abscheuliche Brutstätte der Vergangenheit angehört!", progress = nil, completion = "&lt;Avianas Gesicht ist wie versteinert, als Ihr ihr erzählt, was in der Brutstätte passiert ist.&gt;\n\nSie haben meine Eier gestohlen, &lt;Klasse&gt;. Sie haben sie an diesen widerlichen Ort gebracht. Sie verderbt.\n\nMeine Kinder gestohlen, gequält, in einem Flammenmeer getötet... Ja, wir werden den Schattenhammer dafür bezahlen lassen.\n\nAber ich muss zugeben, dass ein Teil von mir sich einfach in die Lüfte erheben und diese ganze... Welt... in Flammen sehen möchte.", rewards = "Stiefel mit silbernen SporenHimmelsritterhandschützerScheuklappenkapuzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25834] = {title = "Stellvertreterkrieg", objective = "Sprecht mit \"Kräcka\" Aschebäscha im Basislager der Nordwachtexpedition im Steinkrallengebirge.", description = "Hört Ihr sie dort unten kämpfen, <Name>? Anscheinend haben sich die Tauren der Grimmtotem mit der Horde überworfen. Ich weiß nicht, wie das geschehen ist, aber wir könnten es zu unserem Vorteil nutzen.\n\nIch werde ein Treffen mit dem Botschafter der Grimmtotem arrangieren. Ich möchte, dass Ihr eine Friedensgabe zusammenstellt.\n\n<Truppenkommandant Valen zeigt auf Kräcka.>\n\nRedet mit \"Kräcka\", <Name>. Er weiß bereits, was zu tun ist.", progress = nil, completion = "Man nennt mich \"Kräcka\", Junge: den besten Koch von Azeroth. Der Kommandant hat mir schon gesagt, was los ist. Wir müssen ein erstklassiges Taurenmenü zusammenstellen, damit wir eine Audienz beim Häuptling der Grimmtotem bekommen.\n\nBesorgt mir die Zutaten, dann koche ich etwas, dem kein Tauren widerstehen kann. Noch nicht mal ein grimmiger Tauren, oder was immer die auch sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25835] = {title = "Freiwindposten befreien", objective = "Sprecht mit Quentin in Freiwindposten in Tausend Nadeln.", description = "Es ist an der Zeit, dass Ihr geht. Wie schnell die Küken aus dem Nest fallen - oder so ähnlich.\n\nWie dem auch sei, Ihr habt hier gute Arbeit geleistet, aber Quentin und die Nachtelfen haben einen Hilferuf ausgestoßen und benötigen dringend Unterstützung mit den Grimmtotem in Freiwindposten nordwestlich von hier.\n\nWenn Ihr mich fragt, da ist alle Hoffnung verloren, aber wer weiß ... vielleicht können sie es mit Eurer Hilfe wirklich schaffen?", progress = nil, completion = "Ich bin froh, dass Fizzel Euch endlich hergeschickt hat. Wir helfen den Tauren dabei, Freiwindposten zurückzuerobern und die Grimmtotem zu verdrängen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25836] = {title = "Freiwindposten befreien", objective = "Sprecht mit Thalia Bernhaut in Freiwindposten in Tausend Nadeln.", description = "Es sieht so aus, als sei es an der Zeit, dass sich unsere Wege trennen - zumindest vorübergehend. Nordwestlich von hier benötigen die Tauren in Freiwindposten dringend Hilfe, um den Grimmtotemklan zurückzudrängen.\n\nDa Ihr hier so großartig helfen konntet, gehe ich davon aus, dass Ihr auch dort äußerst schnell als <Held/Heldin> gefeiert sein werdet!", progress = nil, completion = "Ich fühle mich geehrt, dass Ihr zu Hilfe gekommen seid, &lt;Klasse&gt;. Es war sehr freundlich von Pozzik, Euch zu schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25837] = {title = "Das perfekte Dinner", objective = "Sammelt 6 Eier von Kalimdoradlern, 8 Widderkeulen und 10 Stücke Steinschlagkäse.", description = "Für eine ordentliche Friedensgabe brauche ich folgende Zutaten:\n\nEier eines Kalimdoradlers. Ihr findet sie in den Nestern der Kalimdoradler. Sucht in dem Wald im Westen danach. Widderkeulen! Und zwar die Keulen des Steinkrallenwidders.\n\nDie letzte Zutat ist zwar schwer zu bekommen, aber wir brauchen sie für unser Widderlett. Reist nach Südwesten zur Steinschlagklamm und macht die Koboldhöhlen ausfindig. Tötet die Kobolde und stehlt ihren besonderen Käse.\n\nBringt alle Zutaten zu mir, dann werde ich ein Meisterwerk kochen!", progress = "Das Widderlett macht sich nicht von allein!", completion = "Bleibt zurück, &lt;Name&gt;, gleich gibt's 'ne Geschmacksexplosion und ich will nicht, dass Ihr verletzt werdet.", rewards = "Ihr bekommt:\n\nKräckas Widderlett Spezial"}
MultiLanguageQuestData['de'][25838] = {title = "Hilfe aus Stahlrosts Depot", objective = "Sprecht mit Delber Kurbeldreh in Stahlrosts Depot.", description = "Dank Eurer Hilfe sind wir näher an die Zuflucht der Frostmähnen herangerückt. Unsere Streitkräfte werden bald in Position gehen und die Reserve der Frostmähnentrolle angreifen. Dann ist ihr Dorf ungeschützt.\n\nDas ist ein Fall für das Geheimteam Gnomeregan. Seine Techniker haben eine Möglichkeit gefunden, Kämpfer hinter die feindliche Linien zu bringen, ohne dass die Frostmähnen das bemerken. Begebt Euch zu Stahlrosts Depot nordöstlich der Stadt und sprecht mit Delber Kurbeldreh. Er wird Euch mehr darüber berichten.", progress = nil, completion = "Ah, Ihr müsst der &lt;Klasse&gt; sein, den Hauptmann Tharran schicken wollte. Ich habe einen Großteil des Geheimteams bereits mit einem Entfalt-O-Tron in Position nahe an die Zuflucht der Frostmähnen gebracht. Sie warten nur noch auf Euer Eintreffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25839] = {title = "Das ultrasichere Personalabschussgerät!", objective = "Fliegt mit dem ultrasicheren Personalabschussgerät zur Zuflucht der Frostmähnen.", description = "Der Kataklysmus hat unsere Feinde näher gebracht, deshalb hat mich der Chef des Geheimdienstes von Gnomeregan gebeten, ein Gerät zu konstruieren, mit dem man Personal rasch und leise in jeden Teil Dun Moroghs transportieren kann.\n\nTataa, das ultrasichere Personalabschussgerät!\n\nMit nur einem Schuss Elektrizität und dank des SPE-Fallschirmsystems, äh, sehr späte Entfaltung für Laien, bringt Euch dieses Baby direkt zur Front. Steigt ein und bereitet Euch auf den Flug vor! Slamp Wackelrad erwartet Euch in der Landezone.", progress = nil, completion = "Keine Sorge, das Gefühl, einen Stromschlag erhalten zu haben, vergeht nach ein paar Minuten. Es gibt wirklich schlimmere Fortbewegungsmittel. An dem Fallschirmsystem muss jedoch noch gearbeitet werden. Sehr späte Entfaltung ist ernst gemeint. Manchmal zu spät. Na ja, wir haben eine Mission zu erfüllen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25840] = {title = "Eliminiert den Widerstand", objective = "Tötet Battok den Berserker und 5 Krieger der Frostmähnen in der Zuflucht der Frostmähnen.", description = "Der Häuptling der Frostmähnen starb beim ersten Angriff der Troggs. Seitdem werden sie von einem sehr respektierten Krieger angeführt. Battok der Berserker war derjenige, der den Rückzug der Frostmähnen organisierte, das neue Dorf errichten ließ und die Angriffe gegen Kharanos und die Gebirgsjäger führte.\n\nWenn wir Battok beseitigen, sollte Chaos unter den Frostmähnen ausbrechen. Dann können sich die Gebirgsjäger um die Überlebenden kümmern. Battok hält sich östlich von hier im Dorf auf.", progress = nil, completion = "Sehr gute Arbeit, &lt;Name&gt;. Ich gebe Hauptmann Tharran das Signal, dass Battok tot ist. Das sollte das Ende der Frostmähnenbedrohung sein.", rewards = "FrostmähnengürtelBattoks blutige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25841] = {title = "Angriff von oben", objective = "Benutzt das Signalleuchtfeuer, um Luftangriffe am nördlichen und südlichen Rand der Zuflucht der Frostmähnen anzufordern.", description = "Delbers Techniker haben Tag und Nacht gearbeitet, um uns bei den Vorbereitungen auf den Angriff zu helfen. Seine Leute haben nicht nur das Personalabschussgerät konstruiert und eingestellt, sondern auch das geheime Fliegergeschwader für den Angriff auf die Zuflucht der Frostmähnen vorbereitet. Sie warten auf das Signal zum Beginn ihrer Angriffe.\n\nNehmt dieses Leuchtfeuer und zündet es nahe der Gebäudegruppe am Nordrand des Dorfs und neben den Gebäuden am Südrand des Dorfs. Die Flugmaschinen werden an beiden Stellen zuschlagen.", progress = nil, completion = "Ihr und die Luftstaffel habt Euch vorbildlich verhalten. Die Frostmähnen werden jetzt sicherlich nicht mehr hier bleiben. Wir müssen nur noch die Überlebenden beseitigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25842] = {title = "Feuergefecht", objective = "Tötet 5 feurige Peiniger, um sie von Nordu fernzuhalten.", description = "Es ist… zu spät für mich. Bis auf den Kern ist alles verbrannt. Ich habe Äonen erlebt… und doch scheint mein Ende so plötzlich zu kommen.\n\nAus altem kann neues Leben entstehen. Ich habe immer noch meine Weisheit, die ich weitergeben kann. Bitte… Lasst nicht zu, dass sie mich wegbringen, bevor meine Arbeit getan ist.\n\nHaltet meine Peiniger zurück... nur noch eine Weile, <Klasse>.\n\nGebt mir ein paar Minuten und ich werde es mit tausenden Jahren vergelten.", progress = "Seid Ihr da, <Klasse>? Mein Augenlicht hat mich verlassen… Ich höre Kämpfe…", completion = "Danke, &lt;Volk&gt;.\n\nIch bin jetzt bereit.\n\nAlles, was ich bin, und alles, was dieser Wald je war… gehört jetzt Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25843] = {title = "Tortollas Rache", objective = "Sprecht mit Tortolla in der Verbrannten Ebene auf dem Hyjal.", description = "Der Berg erblüht wieder! Wenn wir schnell handeln, können wir unseren Vorteil ausnutzen.\n\nUnser alter Freund Tortolla, der Schildkrötenahn, ist bereits auf dem Weg. In seinem eigenen Tempo natürlich…\n\nFindet Tortolla östlich von hier, am Kopf des Pfades in die Verbrannte Ebene. Unsere Festungen dort sind schon ganz zu Anfang unseres Schlachtzugs gefallen, aber vielleicht können wir sie jetzt zurückfordern.", progress = nil, completion = "&lt;Volk&gt;.\n\nIch erinnere mich an Euch. Retter meiner Kinder.\n\nDie Zeit ist gekommen. Für Rache.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25844] = {title = "Sättigt die wilde Bestie", objective = "Bringt Ton Windbogen am Posten der Grimmtotem die fleischige Gabe.", description = "Ihr habt den Kommandanten gehört, <Name>. Bringt mir das perfekte Geschenk für den Botschafter der Grimmtotem! Er wartet mit seinem Trupp am unteren Ende des südöstlichen Pfads.\n\nDas sollte unser Ansehen bei ihrem Häuptling steigern!", progress = "<Ton Windbogen schnüffelt und hebt die linke Hand.>\n\nIhr habt etwas für uns dabei?", completion = "&lt;Ton und seine Leibwächter verschlingen die fleischige Gabe.&gt;\n\nEtwas... etwas so gutes habe ich noch nie gegessen. Vielleicht erweist Ihr Euch doch noch als wertvoller Verbündeter, aber bevor die Grimmtotem sich auf eine Zusammenarbeit mit der Allianz einlassen, müsst Ihr unseren Bedingungen zustimmen. Hier sind sie, so wie mein Anführer sie mir gesagt hat. Bringt sie Eurem Kommandanten. Mal sehen, ob er zustimmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25845] = {title = "Forderungen", objective = "Bringt die Forderungen der Grimmtotem zu Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", description = "Grimmtotem brauchen Waffen! Die Horde hat dank ihres Kriegshäuptlings und der Hilfe ihrer neuen Goblinverbündeten mächtige Waffen angehäuft. Unsere Kriegswerkzeuge haben dieser Feuerkraft nichts entgegenzusetzen. Stattet die Grimmtotem mit starken Waffen aus, dann werden wir gemeinsam die Horde vernichten!\n\nDies sind unsere Forderungen! Versorgt die Grimmtotem, dann kämpfen wir für die Allianz!", progress = "Und???", completion = "Waffen, hm?\n\n&lt;Truppenkommandant Valen seufzt.&gt;\n\nIch werde jetzt eine spontane Entscheidung fällen, &lt;Name&gt;. Ich hoffe, es ist die richtige, sonst wird mich König Wrynn einen Kopf kürzer machen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25846] = {title = "Grundig Finsterwolke, Häuptling der Grimmtotem", objective = "Bringt die Waffenkisten der Allianz zu Grundig Finsterwolke am Posten der Grimmtotem im Steinkrallengebirge.", description = "Der Häuptling der Grimmtotem erwartet Euch, <Name>. Nehmt die Waffenkisten und brecht zum Posten der Grimmtotem südlich von hier auf.\n\nViel Glück, <Name>. Sollte Euch etwas zustoßen, werde ich persönlich Eure Angehörigen informieren und König Wrynn wissen lassen, was Ihr für die Allianz getan habt.", progress = "Habt Ihr die Waffen?", completion = "Das sind gute Waffen! Mächtiger Stahl! Mit solchen Waffen werden meine Krieger unbesiegbar sein. Magatha lächelt auf Euch herab, &lt;Name&gt;.\n\nIch möchte Euch um einen, vielleicht auch zwei Gefallen bitten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25847] = {title = "Die Überlegenheit der Grimmtotem", objective = "Bewaffnet 12 Grimmtotem mit der Waffenkiste der Allianz.", description = "Überall im Hochwipfeltal werden Grimmtotem von der Horde angegriffen. Höllschreis Armeen kennen weder Gnade noch Mitgefühl. Sie töten jeden, der ihnen im Weg steht.\n\nDas muss ein Ende haben! Nehmt das Kriegswerkzeug, das Ihr uns gebracht habt und sucht nach Grimmtotem, die gegen die Horde kämpfen. Gebt ihnen die Waffen der Allianz und seht zu, wie sie die Angreifer der Horde vernichten! Geht. Es gibt viel zu tun, <Verbündeter/Verbündete>.", progress = nil, completion = "Der Kampf ist noch längst nicht vorbei, &lt;Name&gt;. Die Hordengeneräle leben noch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25848] = {title = "Untergang", objective = "Tötet die Hordengeneräle in Camp Aparaje und erbeutet das Insigne des Hordengenerals.", description = "Als wir erfuhren, dass Höllschrei einen weiteren Orc der Mag'har ausgesandt hatte, um die Hordentruppen im südlichen Steinkrallengebirge anzuführen, war es bereits zu spät. Camp Aparaje war niedergebrannt worden, alle Grimmtotem in dem Gebiet waren in den Flammen vergangen.\n\nVier der gefürchtetsten Hordengeneräle führen die Schlacht um das Hochwipfeltal an, unter ihnen auch der Mag'hargeneral Glubgok.\n\nReist nach Süden, zu den Ruinen von Camp Aparaje und tötet die Generäle. Wir halten die Horde JETZT auf! Kehrt zu mir mit ihrem Zeichen zurück!", progress = "Sind die Generäle tot?", completion = "&lt;Grundig zerquetscht das Insigne in seiner riesigen Faust.&gt;\n\nIhr habt es geschafft, Verbündeter! Höllschrei wird Wochen brauchen, um sich von diesem Schlag zu erholen. Das südliche Steinkrallengebirge gehört den Grimmtotem... und der Allianz natürlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25849] = {title = "Angriff der Archäologie", objective = "Erbeutet 20 versteinerte Knochen von lebenden Fossilien.", description = "Hört zu, <mein Freund/meine Liebe>, jeder gute Archäologe kennt die Risiken seines Berufs. Wenn man nicht wenigstens einmal in seiner Karriere einen uralten Dämon ausgräbt oder von einem boshaften Geist verflucht wird, dann sucht man nur nach Plunder!\n\nWahre Archäologen wissen, dass Kleinigkeiten wie versteinerte Knochen, die zu Skelettkriegern reanimiert werden, kein Grund sind, die Arbeit einzustellen.\n\nDiese versteinerten Knochen brauche ich. Erbeutet sie von den Fossilienmonstern, die in der Gegend umherstreunen und bringt sie mir. Ich werde Euch belohnen.", progress = "Ihr müsst Euch nicht zurückhalten! Bringt mir, soviel Ihr tragen könnt!", completion = "Seht Ihr? Nicht schlecht, oder? Ich wünschte fast, all meine Funde würden sich selbst ausgraben. Würde mir die Arbeit erleichtern!\n\nIhr habt sie natürlich auch erleichtert, &lt;Name&gt;. Besten Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25850] = {title = "Schlagt die Erde!", objective = "Tötet 7 paläolithische Elementare.", description = "Falls es Euch entgangen sein sollte, das Land hier im Sumpfland ist ziemlich chaotisch. Überflutungen, Erdbeben... und jetzt wird auch noch der Boden wild.\n\nIch hätte nie geglaubt, dass wir einmal von unserer Grabungsstelle angegriffen werden würden, aber seit kurzem laufen Erdschollen Amok und versuchen, jeden Zwerg zu zerquetschen, den sie finden können.\n\nIhr seht jung und kräftig aus, <Volk>... würdet Ihr dort hinunter gehen und diesen Klumpen etwas Verstand einprügeln?", progress = nil, completion = "Ihr habt es ihnen gezeigt! Gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25851] = {title = "Der mit den Grimmtotem tanzt", objective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", description = "Kehrt zu Eurem Anführer zurück und berichtet ihm, was Ihr für die Grimmtotem getan habt. Sagt ihm, dass unsere Grenzen von nun an für die Allianz geöffnet sind.", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;! Nun müssen sich unsere Streitkräfte nur noch beim Betreten des Steinkrallengebirges Sorgen wegen der Horde machen.", rewards = "UnterhändlerarmbindenAusgezeichnete BeinarbeitValens UmhangAuf Euch wartet eine dieser Belohnungen:\n\nAmulett des Botschafters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25852] = {title = "Alles frei", objective = "Meldet Euch bei Kommandant Thomas Walpole auf dem Steinkrallenpass im Südlichen Brachland.", description = "Packt Eure Sachen, <Name>, wir werden uns jetzt den restlichen Streitkräften der Nordwacht im Südlichen Brachland anschließen. Eure erste Mission im Südlichen Brachland sollte recht unkompliziert sein.\n\nVor zwei Tagen erreichte uns ein Notruf von Kommandant Walpole. Man hat ihn und sein Bataillon auf dem Steinkrallenpass außerhalb von Ehrenwacht eingekesselt. Die Horde ist überall! Geht dorthin und helft ihm. Ich werde das Nordwachenkommando von unserer Allianz mit den Grimmtotem in Kenntnis setzen.", progress = nil, completion = "Die Grimmtotem sind also keine Bedrohung mehr? Das ist gut, aber uns tritt hier gerade die Horde in den Hintern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25853] = {title = "Ohne Hut und Peitsche", objective = "Beschafft 6 Archäologenwerkzeuge.", description = "Ich bin für die Ausrüstung dieser Ausgrabungsstätte verantwortlich. Das läuft ganz gut, aber die schnelle Abreise hat uns nicht gut getan!\n\nArchäologen brauchen schließlich Werkzeuge. Man kann unbezahlbare Antiquitäten nicht mit den Händen ausgraben. Wenn Ihr zur Ausgrabungsstätte reist, könntet Ihr uns das Werkzeug, das zurückgelassen wurde, mitbringen?", progress = "Sind sie vollständig? Wir haben einiges zurückgelassen.", completion = "Das erleichtert mich! Vielleicht können wir uns jetzt aus dem Mist graben, in dem wir bis zum Hals stecken.\n\nVergesst es, nur ein schlechter Scherz.", rewards = "FelswirkergamaschenUnentblößte GamaschenAntike BrustplatteRekonstruiertes SchwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25854] = {title = "Ich nenne ihn Bisschen", objective = "Beschafft sechs wackelnde Raptoreneier.", description = "Wusstet Ihr, dass manche Raptoren so intelligent sind, dass man sie zähmen kann? Das stimmt! Ich habe Jäger gesehen, die das getan haben.\n\nEs ist hier draußen ziemlich einsam, auch wenn Wenna mir Gesellschaft leistet... ein Haustier würde vielleicht meine Stimmung heben. Ein kleines Raptorbaby wäre toll!\n\nWenn Ihr ohnehin gerade dort draußen die Erwachsenen abschlachtet, könntet Ihr mir einige ausgebrütete Eier mitbringen? Die Eier wackeln, wenn die Babys schlüpfbereit sind.", progress = "Habt Ihr genug Eier? Das Risiko bei nur einem Ei ist zu hoch. Das ist statistisch erwiesen.", completion = "Wunderbar! Sie sollten noch heute schlüpfen...\n\nIch baue besser schon mal ein Gehege, bevor sie alle gleichzeitig schlüpfen. Eigentlich kann nichts schiefgehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25855] = {title = "Dingsdabumse", objective = "Findet 7 Dingsdas der Schnellschalts.", description = "In letzter Zeit fehlen mir ständig Teile für meine Ingenieurskunstprojekte, und nun habe ich den Grund dafür entdeckt. Die Moosfellgnolle stehlen sie!\n\nIch weiß nicht, was sie damit wollen, aber ich muss diese Dingsdas wiederhaben. Wahrscheinlich liegen sie überall in den Sümpfen herum. Würdet Ihr sie mir mitbringen, wenn Ihr welche seht?", progress = "Habt Ihr sie gefunden?", completion = "Das ist wundervoll! Ich fange direkt mit dem Zusammenbau an. Habt Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25856] = {title = "Krokiliskenbälge", objective = "Erbeutet 10 Marschenkrokiliskenbälge von Sumpflandkrokilisken.", description = "Seit Jahren häute ich Krokis im Sumpfland, <Klasse>. Es hat sich jedoch viel verändert.\n\nIch will nicht auf die Tränendrüse drücken, aber als der Kataklysmus den Hafen von Menethil überflutete, riss er auch unser Haus mit sich. Meine Frau und meine Kinder wissen nicht, wo sie bleiben sollen, und ich muss so viel Geld wie möglich verdienen, damit wir bald wieder ein Dach über dem Kopf haben.\n\nIch habe Krokis gehäutet, bis ich vor Müdigkeit umgefallen bin, aber ich brauche noch mehr Häute für den Verkauf. Bringt mir ein paar Krokibälge. Ich zahle Euch auch ein wenig dafür.", progress = "Habt Ihr Krokbälge für mich?", completion = "Ich bin Euch dankbar, &lt;Klasse&gt;. Die werden meiner Familie helfen, wieder auf die Beine zu kommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25857] = {title = "Jagt Horrorkiefer", objective = "Tötet Horrorkiefer und erbeutet Horrorkiefers Haut.", description = "Es juckt mir in den Fingern, eine große Beute zu jagen... Horrorkiefer, den größten Krokilisken dort draußen. Mit seinem Balg könnte ich meine Familie aus diesem Loch holen.\n\nAber ich bin kein Narr. Ein Fehler reicht, um ein Bein oder gar mein Leben zu verlieren. Was würden meine Frau und Kinder dann tun? Sie wären immer noch obdachlos und die Kinder hätten keinen Vater mehr, der sich um sie kümmert.\n\nIch bin nicht stolz darauf, aber für die Sicherheit meiner Familie schlucke ich meinen Stolz hinunter. Bitte, <Klasse>... jagt Horrorkiefer für mich. Er lauert im Norden, in seinem schattigen Tümpel.", progress = "Habt Ihr sie? Habt Ihr Horrorkiefers Haut?", completion = "Unglaublich! Ihr seid ein wahrer Held, &lt;Name&gt;. Ich werde nie vergessen, was Ihr für mich und meine Familie getan habt.\n\nIch weiß, dass es nicht viel ist, aber nehmt es mit meinem Segen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25858] = {title = "Im Namen der Lady", objective = "Sprecht mit Tiefenlord Zin'jatar, Lady Sira'kess und Aufseher Idra'kess.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Lady Sira'kess hat mit den Vorbereitungen für das Beschwörungsritual begonnen, aber der Schmelztiegel von Nazsharin wurde uns gestohlen. Sicher haben die Kvaldir ihn mit sich genommen, als sie sich in flachere Gewässer zurückgezogen haben.\n\nSprecht mit den Anführern der Kasten, um einen Kriegstrupp zusammenzustellen. Führt sie dann zum Biel'arangrat im Osten, um das Artefakt wiederzuholen.\n\nIch vertraue Euch, meine Kriegsmaid, denn Ihr habt mich noch nie enttäuscht, ganz gleich, welche Aufgabe ich Euch gab. So sehr die Königin mich schätzt, so sehr schätze ich Euch. Geht mit meinem Segen.", progress = nil, completion = "Verstärkung zieht sich in den Gewässern um das Riff zusammen und macht sich für einen Angriff bereit. Sie warten nur noch auf Euren Befehl.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25859] = {title = "Keine Vergebung", objective = "Tötet 20 Kvaldir auf der Vrykulklippe.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Ich weiß, dass Ihr genau wie unsere ehrwürdige Lady gelegentlich leider Anflügen von Mitleid unterliegt. Am heutigen Tage möchte ich Euch jedoch raten, diese Freundlichkeiten zu unterlassen. Die Kvaldir sind stolz. Wenn wir sie nicht komplett vernichten, werden sie ganz sicher Rache nehmen. Tötet alle, die Ihr finden könnt.\n\nLeider habe ich die ruhmlose Aufgabe sicherzustellen, dass keiner in die Stadt zurückkehrt, sodass ich Euch den ganzen Spaß überlassen muss. Ich werde Euch aber natürlich anfeuern.", progress = nil, completion = "Keiner ist zur Brücke entwischt. Nicht einer.\n\nWie langweilig. Nächstes Mal wäre ich Euch dankbar, wenn Ihr ein bisschen mit mir teilen würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25860] = {title = "Koste es, was es wolle", objective = "Tötet 20 Angreifer der Kvaldir im Tempel von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Wir beginnen sofort mit dem Ritual. Ihr werdet Euch darum kümmern, dass niemand uns unterbricht.\n\nErschlagt alle Kvaldir, die den Tempel betreten. Achtet darauf, dass meine Priesterinnen überleben, um ihre Aufgabe zu Ende zu bringen. Koste es, was es wolle.", progress = "Ich vertraue darauf, dass Ihr uns beschützt, Kriegsmaid.", completion = "Wenn Azjentus etwas verspricht, dann hält er es auch. Lady Naz'jars Ehrenwache sollte ausreichen, um den Rest des Rituals zu überwachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25861] = {title = "Ein Exempel statuieren", objective = "Bringt einen Hochschamanen der Kvaldir zu Henker Verathress' Füßen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Die Hochschamanen befinden sich in den Gebäuden in der Nähe und singen und spotten, trauen sich aber nicht, näher zu kommen. Diese Kvaldir sind nur mutig, wenn sie sich im Nebel verstecken können. Ein erbärmliches Ärgernis unter den Wellen.\n\nIch bringe eine Nachricht. Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", progress = "Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", completion = "Meine Sense ist gesättigt. Vielen Dank, gnädige Frau.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25862] = {title = "Gestohlenes Eigentum", objective = "Besorgt den Schmelztiegel von Nazsharin.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Unsere ehrwürdige Lady hat mich geschickt, um Euch bei Eurer Aufgabe zu helfen. Sie möchte, dass Ihr den gestohlenen Schmelztiegel von Nazsharin wiederbeschafft und so schnell wie möglich hierher bringt.\n\nSie kann es kaum erwarten, das Beschwörungsritual durchzuführen, damit wir endlich voll und ganz mit unseren Kriegsvorbereitungen beginnen können.", progress = nil, completion = "&lt;Der Schmelztiegel sieht viel zu schwer aus, als dass Ihr ihn alleine tragen könntet, aber es sind mehr als genug Streitmächte der Naga übrig, um ihn für den Transport vorzubereiten.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25863] = {title = "Freiwillige Last", objective = "Kehrt mit Euren Nachrichten vom Schmelztiegel von Nazsharin zum westlichen Ende des Biel'arangrats zurück.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Jetzt, da Ihr den Schmelztiegel von Nazsharin an Euch gebracht habt, müsst Ihr nur noch Lady Naz'jar von Eurem Erfolg berichten.", progress = nil, completion = "Gut gemacht, meine Kriegsmaid.\n\nDieser Schmelztiegel wird uns als Quell der Macht für unser Beschwörungsritual dienen. Damit wird Sira'kess unsere Verbündeten aus den Tiefen rufen, um unsere ohnehin schon starke Armee zu unterstützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25864] = {title = "Dinosaurierkrise", objective = "Tötet 8 beliebige Hochlandraptoren.", description = "Ständig erreichen uns Berichte über Raptorangriffe in der Gegend. Ich muss hier für Sicherheit sorgen, damit mehr Siedler kommen. Aus diesem Grund habe ich ein Kopfgeld auf diese Viecher ausgesetzt.\n\nViele wurden bereits beseitigt, aber die Hochlandraptoren im Norden vermehren sich stark. Aber das wird sich bald ändern, nicht wahr?\n\nErledigt ein paar Hochlandraptoren, dann gebe ich Euch eine hübsche Belohnung.", progress = nil, completion = "Gute Arbeit. Betrachtet das nicht als Belohnung von mir, sondern von Eisenschmiede. Der Erhalt von Khaz Modan geht jeden Zwerg etwas an.", rewards = "Shilahs ArmschienenHochlandschulterschutzSchnellschaltgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25865] = {title = "Die Moosfellmission", objective = "Beschafft 8 Barren von Eisenschmiede von den Gnollen der Moosfelle.", description = "Ihr wirkt vertrauenswürdig. Würdet Ihr mir bei meinem wahren Problem helfen, <Name>? Eisenschmiede hat mich hierher geschickt, um eine Lieferung Goldbarren wiederzubeschaffen.\n\nDie Barren gehören zum Thronschatz von Eisenschmiede und tragen das königliche Siegel. Nur ein Narr würde sie aus Profitgier stehlen. Sie sind viel zu leicht nachzuverfolgen. Wie es der Zufall will, gibt es jede Menge Narren hier: Moosfellgnolle.\n\nIch weiß nicht, wie oft Ihr schon gegen Gnolle gekämpft habt, aber das sind üble und brutale Bestien. Sie sind gefährlich. Tötet sie und bergt die verschwundenen Barren.", progress = "Es wurden schätzungsweise acht Barren gestohlen.", completion = "Gut gemacht! Die Wache von Eisenschmiede dankt Euch, &lt;Name&gt;. Ihr habt unserer Stadt einen großen Gefallen erwiesen.\n\nDoch es gibt neue Probleme...", rewards = "Schild des königlichen SchatzamtkuriersBarrenträgerhandschuheAuf Euch wartet eine dieser Belohnungen:\n\nLaterne des Buchhalters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25866] = {title = "Fallensteller der Dunkeleisenzwerge", objective = "Tötet 10 Fallensteller der Dunkeleisenzwerge.", description = "Der Klan der Dunkeleisenzwerge ist in diesem Gebiet gesehen worden. Vielleicht sind sie Euch schon über den Weg gelaufen. Sie führen nie Gutes im Schilde, und dieses Mal scheinen sie aus irgendeinem Grund Moosfellgnolle zu entführen.\n\nIch weiß nicht, was das soll, aber wir müssen sie aufhalten, bevor noch üblere Dinge geschehen. Haltet sie auf.\n\nWenn Ihr Euch Sorgen macht, weil das unfair ist, könnt Ihr sie ja zuerst höflich fragen. Mal sehen, wie weit Ihr damit kommt.", progress = nil, completion = "Ich nehme an, sie sind nicht freiwillig mitgekommen? Dachte ich mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25867] = {title = "Die Flucht der Gnolle", objective = "Erbeutet den Schlüssel des Fallenstellers von Fallenstellern der Dunkeleisenzwerge und befreit damit 6 Gnolle aus den Gnollkäfigen.", description = "Ich weiß, dass wir selbst gerade die Gnolle angegriffen haben, aber ich werde nicht zulassen, dass die Dunkeleisenzwerge sie als Sklaven halten. Zum einen haben wir die Diebe gefunden und unseren Besitz zurückerhalten, also wurde der Gerechtigkeit Genüge getan. Zum anderen werden die Dunkeleisenzwerge sie bestimmt nicht für gemeinnützige Arbeiten einsetzen... \n\nAlso müssen die Gnolle befreit werden. Die Fallensteller sollten die Schlüssel, mit denen man die Käfige öffnen kann, bei sich tragen.", progress = nil, completion = "Das sollte reichen! Je mehr Gnolle diese Narren jagen müssen, desto leichter wird es, sie in Schach zu halten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25868] = {title = "Yorla Dunkelschlinge", objective = "Tötet Yorla Dunkelschlinge.", description = "Ich habe herausgefunden, wer bei dieser Operation im Hintergrund die Fäden zieht. Yorla Dunkelschlinge führt die Dunkeleisenzwerge von einem Lager im Osten an. Wahrscheinlich hat sie den Gnollen befohlen, das Gold aus Eisenschmiede zu stehlen.\n\nAußerdem ist sie eine gesuchte Kriminelle... Schon als Magni noch lebte, schürte sie Rebellionen und Angriffe gegen Eisenschmiede.\n\nDieses Mal wird sie uns nicht durch die Lappen gehen, <Name>. Schnappt sie Euch!", progress = nil, completion = "Gute Arbeit! Ihr habt eine der größten Verbrecherinnen Eisenschmiedes der Gerechtigkeit zugeführt, &lt;Name&gt;. Ihr habt Euch eine ziemlich große Belohnung verdient.", rewards = "DunkelfallendolchGroßaxt der alten WacheShilahs KlingeHammer der alten WacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25869] = {title = "Grimmtotem in Freiwindposten", objective = "Tötet 10 Eindringlinge der Grimmtotem.", description = "Die Reise, die vor uns liegt, beginnt damit, dass Ihr alle Eindringlinge der Grimmtotem in Freiwindposten tötet. Wenn Ihr sie hier nicht aufhalten könnt, werden wir nicht in der Lage sein, bis zu ihrem Territorium vorzudringen.", progress = nil, completion = "Bei dieser Aufgabe kann man wirklich nur grimmig dreinschauen.&lt;Quentin hustet.&gt;\n\nNein, das war nicht witzig gemeint.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25870] = {title = "Grimmtotem in Freiwindposten", objective = "Tötet 10 Eindringlinge der Grimmtotem.", description = "Ihr müsst die Eindringlinge der Grimmtotem in Freiwindposten loswerden. Das haben sie sich aber selbst zuzuschreiben, diese Feiglinge!\n\nWir können nicht zulassen, dass die Schlacht in ihre eigenen Gebiete verlagert wird, und wir sprichwörtlich mit dem Rücken zu ihnen stehen. Bitte helft uns, unsere Heimat zurückzuerlangen, <Klasse>.", progress = nil, completion = "Das ist schon mal ein guter Anfang! Normalerweise würde ich keiner Kreatur der Erdenmutter irgendein Leid wünschen.\n\nAber da sie uns zu einem Zeitpunkt extremer Verletzlichkeit angegriffen haben, verdienen sie den Tod!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25871] = {title = "Rettet die Schildwache", objective = "Rettet die Schildwache von Feralas.", description = "<Brienna wedelt mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben eine unserer Schildwachen gefangen! Sie drohen damit, sie zu töten, wenn wir uns nicht zurückziehen!\n\nWir verhandeln nicht mit feigen Bestien! Bitte <Klasse>, könnt Ihr versuchen, die Schildwache zu retten, bevor es zu spät ist?", progress = nil, completion = "Danke, dass Ihr die sie befreit habt, &lt;Name&gt;. Die Monster der Grimmtotem hätten sie sicherlich kaltblütig getötet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25872] = {title = "Der Kriegerheld und die Wagemütigen", objective = "Retten den Kriegerheld des Freiwindpostens.", description = "<Rau wedelt verärgert mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben einen unserer Kriegerhelden gefangen! Sie drohen damit, ihn zu töten, wenn wir uns nicht zurückziehen!\n\nWir werden diesen feigen Grimmtotem nie gestatten, Freiwindposten zu behalten! Bitte <Klasse>, rettet ihn, bevor es zu spät ist.", progress = nil, completion = "Vielen Dank &lt;Name&gt;, dass Ihr den Kriegerhelden befreit habt. Diese Grimmtotem hätten ihn kaltblütig getötet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25873] = {title = "Das Horn des Verräters", objective = "Erhaltet Langhorns Horn.", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", progress = "Was ist das, <Klasse>?", completion = "Ein Verräter unter den Tauren?\n\nVon so etwas habe ich noch nie etwas gehört. Rivalitäten und Kriege zwischen den Klans sind eine Sache, aber das kaltblütige Töten eines Verbündeten ist etwas anderes.\n\n&lt;Quentin schüttelt ungläubig seinen Kopf.&gt;", rewards = "Ihr bekommt:\n\nHorn des Verräters"}
MultiLanguageQuestData['de'][25874] = {title = "Das Horn des Verräters", objective = "Erhaltet Langhorns Horn.", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", progress = "<Name>? Habt Ihr Neuigkeiten?", completion = "Der Klippenbehüter war ein Spion der Grimmtotem?! Kein Wunder, dass wir nicht gewarnt wurden!\n\n&lt;Thalia schäumt beinahe über vor Wut.&gt;\n\nDieses verdammte Horn will ich nicht. Lasst es in den Tiefen des Wassers untergehen, und sorgt dafür, dass der Name Langhorn nie wieder erwähnt wird!", rewards = "Ihr bekommt:\n\nHorn des Verräters"}
MultiLanguageQuestData['de'][25875] = {title = "Der eingeschleuste Gnom", objective = "Sucht in den Schlickwerken im Steinkrallengebirge nach Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", description = "Am Mirkfallonsee wimmelt es von der Horde. Die Goblins haben sich dort eingenistet, und sie werden erst wieder abziehen, wenn sie das gesamte Öl unter dem Steinkrallengebirge ausgesaugt haben.\n\nZum Glück konnte ich einen Gnom einschleusen, der Informationen für uns sammelt. Wenn irgendjemand weiß, was es mit dieser Bombe auf sich hat, dann mein eingeschleuster Gnom.\n\nGeht zu den Schlickwerken im Norden und findet Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", progress = nil, completion = "Kommt rein und bleibt an der Wand! Meine Tarnung darf nicht auffliegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25876] = {title = "Sie ist da oben!", objective = "Stehlt das Logbuch von Krom'gar.", description = "Ich folge dieser Bombe, seit Ihr mich in Eschental gerettet habt. Was auch immer sie damit vorhaben, wird bald geschehen.\n\nGanz oben auf der großen Ölplattform gibt es einen Kontrollraum. Im Kontrollraum werdet Ihr das Logbuch von Krom'gar finden. Dieses Logbuch ist der Schlüssel zum Ziel der Bombe. Geht nach oben und holt das Logbuch! Bringt es hierher. Ich werde es für Euch dechiffrieren.", progress = "Habt Ihr das Logbuch bekommen?", completion = "OH NEIN! Sie wollen die Bombe im Hain von Thal'darah \"testen\"! Das ist eine Schule für junge Druiden mitten im Kriegsnarbental. Ihr müsst zu Barus zurückkehren und ihn davon unterrichten! Meister Thal'darah muss gewarnt werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25877] = {title = "Keine Zeit für Verabschiedungen!", objective = "Kehrt zu Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge zurück", description = "LAUFT! Verschwindet hier, <Name>. Sucht Barus auf und sagt ihm, was Ihr herausgefunden habt. Er wird dafür sorgen, dass Ihr sicher durch das Kriegsnarbental zur Aussicht von Thal'darah gelangt.\n\nFür diese jungen Druiden ist es noch nicht zu spät!", progress = nil, completion = "Verdammte Horde! Ich habe Freunde in diesem Hain. Ich hoffe, Ihr könnt auf einem Hippogryph reiten. Ihr müsst sofort zu Meister Thal'darah an der Aussicht aufbrechen!", rewards = "Handschuhe des NachrichtenüberbringersBruststück des BotenSchulterschutz der WarnungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25878] = {title = "Anleitung zur Sabotage", objective = "Zerstört 4 Goblinölpumpen mit der Goblinpumpensteuerung.", description = "Goblins... Was wäre die Welt ohne Goblins? Das kann ich Euch sagen: SAUBER!\n\nDiese schmutzigen kleinen Unholde haben überall auf dem See Ölpumpen errichtet, mit denen sie das Öl im Streinkrallengebirge bis auf den letzten Tropfen abzapfen wollen. An jeder Ölpumpe steht ein Ölpumpenkontrolleur, der darauf achtet, dass die Pumpe läuft und nichts schief geht.\n\nAber etwas wird schiefgehen.\n\nBeseitigt die Goblinpumpenkontrolleure und nehmt ihre Pumpensteuerung. Überlastet damit die Pumpen!", progress = nil, completion = "Ich konnte die Explosionen von hier sehen, &lt;Name&gt;! Dank Euch wird die Horde keinen Treibstoff mehr vom Mirkfallonsee bekommen!", rewards = "SabotagegamaschenSchild der KontrolleYvonias SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25879] = {title = "Ärger mit den Trampeln", objective = "Tötet 10 Trampel.", description = "Schon mal einen Hobgoblin gesehen? Das ist wieder so eine eklige Schöpfung der Goblins. Nehmt einen Goblin, macht ihn noch hässlicher, fetter, größer und dümmer, und heraus kommt ein Hobgoblin. Fügt dem noch einen miesen Charakter hinzu, dann versteht Ihr das Problem.\n\nDiese Trampel lungern an den Schlickwerken und am Mirkfallonsee herum. Die Goblins setzen sie als Wächter ein.\n\nGeht dorthin und dünnt sie etwas aus. Unwiderruflich.", progress = nil, completion = "Langsam, aber sicher führen wir der Horde Verluste zu. Sie werden kein Bein auf den Boden kriegen, wenn es in diesem Krieg richtig zur Sache geht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25880] = {title = "Warnt Meister Thal'darah", objective = "Meldet Euch bei Meister Thal'darah an der Aussicht von Thal'darah im Steinkrallengebirge.", description = "Im Hain von Thal'darah leben Dutzende Schüler. Die meisten können sich nicht wehren. Man wird sie abschlachten.\n\nInformiert Meister Thal'darah über die Pläne der Horde. Er wird Euch erklären, was als Nächstes zu tun ist.\n\nFiora Mondsegler hat Euch ihren schnellsten Hippogryph gegeben. Fliegt damit zur Aussicht von Thal'darah! Seht nicht zurück, <Name>! Die Horde muss aufgehalten werden!", progress = nil, completion = "Wir leben in wirklich schlimmen Zeiten, &lt;Name&gt;. Unser Außenposten auf dem Steinkrallengipfel wurde von grausamen Kreaturen aus der Tiefe überrannt, und die Horde will uns vernichten. Wir brauchen einen Helden, &lt;Name&gt;; einen Soldaten der Allianz, der uns sicher durch diese schweren Zeiten führt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25881] = {title = "Verschollene Wächter", objective = "Findet und rettet 8 verschollene Wächter.", description = "Wir haben so lange durchgehalten wie es ging, <Klasse>. Aber die Flammen… die Hitze… Wir haben die Stadt ganz verloren.\n\nHauptmann Eisenstamm hat sich geweigert, zum Rückzug zu blasen, als die Flammen uns eingeschlossen haben. Unsere Truppen sind überall verstreut. Vielleicht haben ein paar der anderen überlebt? Wir könnten einen Gegenangriff starten!\n\nReist in die Verbrannte Ebene und rettet alle verschollenen Wächter, die von ihrer Gruppe getrennt wurden. Dann sucht nach Hauptmann Eisenstamm. Er befindet sich wahrscheinlich mitten im Kampfgetümmel.", progress = nil, completion = "Ihr habt die Überlebenden versammelt? Gut, gut. Und der Rest des Berges… ist geheilt?\n\nHa, da brat mir einer einen Storch! Wir sind wieder an der Front!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25882] = {title = "Hilfe für das Gehöft", objective = "Sprecht mit Unteroffizier Flinthammer auf dem Gehöft Bernruh.", description = "Hauptmann Tharran hat mich gebeten, Euch seinen Dank für Eure Hilfe und seine Glückwünsche zur erfolgreichen Mission auszurichten. Er kümmert sich mit seinen Männern um die letzten Trolle und versorgt die Verwundeten.\n\nEr hat mich auch gebeten, Euch zu fragen, ob Ihr Berichten über Trollüberfälle auf dem Gehöft Bernruh im Norden nachgehen könntet. Fragt nach Unteroffizier Flinthammer, wenn Ihr dort eintrefft.", progress = nil, completion = "Ihr habt also Hauptmann Tharran dabei geholfen, die Frostmähnentrolle zurückzuschlagen? Ich habe Euren Namen in den Berichten gesehen. Freut mich, Euch endlich kennenzulernen. Ein &lt;Klasse&gt; wie Ihr könnte zur Sicherung des Gehöfts eine echte Hilfe sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25883] = {title = "Entwaffnend", objective = "Zerstört 6 Dreizackstapel der Naga.", description = "Nagawaffen…\n\nAls Ihr Euren Blick über die Pferche streifen lasst, seht Ihr Dutzende ähnlicher Dreizackstapel, die strategisch positioniert zu sein scheinen.\n\nIhre Waffen zu zerstören behindert sicher die bösen Pläne, die sie in dieser Gegend verfolgen...", progress = "Habt Ihr das Waffenlager der Naga zerstört?", completion = "Ihr seid Euch sicher, dass Eure Zerstörung der Waffen die Naga sicher stark einschränken wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25884] = {title = "Auf Biegen und Brechen", objective = "Tötet 12 Naga des Zin'jatar in der Umklammerung im Tang'tharwald.", description = "Himmeldonnerwetter nochmal...\n\nIch weiß, dass unser Schiffbrüchiger hier es gut meint, aber der Junge ist doch schwerst traumatisiert.\n\nEs gibt nur eine Methode, wie man mit diesen verflixten Biestern fertig wird, und zwar indem man ihnen eine anständige Zwergenaxt bis zum Anschlag in den Schädel rammt.\n\nJe mehr Leichen ihrer Kameraden man vor ihnen aufstapelt, desto genauer werden sie es sich überleg'n, einem ans Leder zu geh'n.\n\nDas könnt Ihr mir glaub'n, <Kumpel/Mädel>, die Burschen mög'n den Anblick ihres eigenen Blutes genausowenig wie Ihr oder ich.\n\nUnd jetzt ab mit Euch und zeigt denen, was 'ne Harke ist!", progress = nil, completion = "Die Gewässer in der Umgebung der Pferche färben sich rot vom Blut der Naga.\n\nRendel wäre stolz!", rewards = "SeenadelarmschienenMuschelverzierte StulpenMedusoidenstabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25885] = {title = "Keine Macht den Algen", objective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, <Volk>. Bringt mir etwas davon!", progress = "Konntet Ihr welche von diesen Algen für mich finden, <Klasse>?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25886] = {title = "Den Vorteil nutzen", objective = "Tötet 4 Zwielichtfeldhauptmänner.", description = "Wie es scheint, hat ein Großteil des Schattenhammers sich zurückfallen lassen, um sich für einen weiteren Angriff neu zu formieren. Nur ihre besten Kämpfer halten noch die Front. Dies ist unsere Gelegenheit, um ihren Anführern den Garaus zu machen.\n\nSchwärmt aus über die Verbrannte Ebene und vernichtet die Zwielichtfeldhauptmänner. Wir werden sie von dieser Welt tilgen!", progress = nil, completion = "Ausgezeichnet! Der Schattenhammer wird zweifellos versuchen, den Berg zurückzuerobern, aber dafür müssen sie jetzt auf die Führerschaft dieser hirnlosen Muskelpakete verzichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25887] = {title = "Welle der Zerstörung", objective = "Benutzt die Kugel der Anregung, um einen ausgemergelten großen Hai zu unterwerfen und benutzt ihn dann, um 12 Gefolgsleute des Zin'jatar in der Umklammerung zu töten.", description = "Unsere Zeit hier neigt sich dem Ende zu. Ich muss diesen Nagaflüchtlingen irgendwie folgen, wenn wir herausfinden wollen, was sie in dieser Gegend vorhaben.\n\nAber bevor ich weiterziehe will ich sehen, wie dieser Ort hier vernichtet wird!\n\nEgal, wie viele es sind, ich habe einen Plan, der für Chancengleichheit sorgen wird.\n\nAußerhalb der Höhle suchen ausgemergelte große Haie, die von den Naga vertrieben wurden, nach Nahrung.\n\nIn ihrem geschwächten Zustand sind sie für Anregungen sehr empfänglich. Benutzt diese Kugel, um sie zu unterwerfen und hetzt sie dann direkt auf unseren Feind.", progress = nil, completion = "Genau so soll es sein.\n\nJetzt ist der Weg frei, um diesen Naga einen letzten vernichtenden Schlag zu versetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25888] = {title = "Druckabbau", objective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Soldaten in der Umklammerung.", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Soldat inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, <Name>. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", progress = "Konntet Ihr einige der eingekerkerten Soldaten retten, <Name>?", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", rewards = "PteropodenrobenKegelschneckensattelgurtAtemsteinerfüllter LangbogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25889] = {title = "Rettet die Kinder!", objective = "Rettet mit Meister Thal'darahs Hippogryph 5 hilflose junge Druiden aus dem Hain von Thal'darah.", description = "Meine armen, hilflosen Schüler sitzen im Hain von Thal'darah fest. Wegen der Schlacht, die im Kriegsnarbental tobt, können sie nicht entkommen. Wir müssen die Kinder retten, bevor die Horde ihre Bombe abwirft!\n\nNehmt meinen Hippogryph und rettet damit die jungen Druiden im Hain von Thal'darah. Setzt sie am Hippogryphenposten hier in der Stadt ab.\n\nRettet sie alle, <Name>! Ihr seid wahrlich unsere einzige Hoffnung.", progress = nil, completion = "Habt Dank, &lt;Name&gt;. Der Held, auf den wir gewartet haben, ist endlich gekommen - und keinen Augenblick zu früh.", rewards = "Kopfschutz des UnschuldigenBrustplatte der RettungAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger von Thal'darah\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25890] = {title = "Nespirah", objective = "Betretet Nespirahs nordwestlichen Eingang und findet dann einen Weg, um mit ihr zu sprechen.", description = "Jetzt ist mir klar, was wir tun müssen, <Name>.\n\nDie Naga können diese Perlen nur von einem Ort haben: Nespirah, das uralte Schalenwesen, das außerhalb dieser Höhle ruht. Warum Nespirah sich den Naga unterwirft, ist mir allerdings schleierhaft.\n\nWir können durch eine kleine Röhre in der Nähe des Ausgangs dieser Höhle in Nespirahs Körper eindringen. Ich muss zuerst noch meinen Meister holen, danach können wir uns im Inneren treffen. Wir werden Nespirah durch den nordwestlichen Eingang betreten.", progress = nil, completion = "Erunak vertraut diese Aufgabe mir an? Nun gut. Mal sehen, was wir von der Ahnin lernen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25891] = {title = "Eine Letzte Anstrengung", objective = "Helft Meister Thal'darah bei der Suche nach Druiden, die im Hain von Thal'darah zurückgelassen wurden.", description = "Die Horde signalisiert den Rückzug. Seht, wie sie das Schlachtfeld verlassen - das ist der Vorbote einer Katastrophe.\n\nWir müssen ein letztes Mal im Hain von Thal'darah landen. Ich würde es nicht ertragen, wenn auch nur ein junger Druide zurückbleiben müsste.\n\nHelft mir, <Held/Heldin>. Ich nehme die Zügel. Sucht Ihr nach Druiden, die vielleicht zurückgelassen wurden.\n\nWir brechen auf, wenn Ihr bereit seid.", progress = nil, completion = "Wisst Ihr, weshalb die Horde zerstört? Die Horde zerstört, weil sie Schönheit nicht begreifen kann. Sie fürchtet sie, und was sie fürchtet, muss sie zerstören. Warum sonst zerstört sie den Hain von Thal'darah?\n\nGemeinsam werden wir dafür sorgen, dass sie etwas verstehen. Sie werden verstehen, dass ihre Taten einen hohen Preis fordern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25892] = {title = "Haltlos", objective = "Benutzt Wellensprecherin Valorens Seepferd, um zu Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir zurückzukehren.", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", progress = nil, completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Freut mich sehr, Euch zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25893] = {title = "Ein verzweifelter Plan", objective = "Trefft Euch mit Ingenieur Hexasept auf dem Biel'arangrat.", description = "Jorlan und Hexasept sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", progress = nil, completion = "Pünktlich wie ein Uhrwerk! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Uhrwerk!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25894] = {title = "Feindliche Gewässer", objective = "Tötet 10 Schlickhautschnorrer.", description = "Hexasept kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Kiemengoblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", progress = nil, completion = "Je weniger Kiemengoblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25895] = {title = "Immer vorbereitet", objective = "Besorgt eine Überlebensausrüstung der Allianz.", description = "Wir müssen immer vorbereitet sein. Wir müssen Ausrüstung haben. Wir müssen Pläne haben!\n\nAlle Schiffe in der Flotte der Allianz sind mit einer Überlebensausrüstung ausgestattet. Viele unserer Werkzeuge stammen aus so einer Überlebensausrüstung. Mein Ballon war auch in so einer Überlebensausrüstung enthalten! Aber jetzt ist sie aufgebraucht. Ich brauche noch eine Überlebensausrüstung!\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren und die Überlebensausrüstung nicht mitgenommen haben. Mehr zum Überleben für uns!", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", rewards = "NephropsistreterFußpolster der AnomuraStab der rückwirkenden VorbereitungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25896] = {title = "Andächtige Versammlung", objective = "Sucht Tiefenrufer Azrajar in der Mitte der nördlichen Treppe sowie 6 Gezeitenpriesterinnen der Sira'kess auf der oberen Ebene der Ruinen und tragt ihnen auf, zum Tempel zurückzukehren.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Ah, Kriegsmaid. Das Wort und der Wille unserer Lady sind mit Euch. Ich möchte Euch um einen Gefallen bitten…\n\nTiefenrufer Azrajar und meine Gezeitenpriesterinnen müssen zurückkehren, damit wir mit dem Ritual beginnen können. Könnt Ihr ihnen meinen Wunsch überbringen? Ihr solltet sie auf der Tempelterrasse und den Treppen unten finden. Azrajar hält sich an der Treppe im Norden auf.", progress = "Die Bedrohung ist vielleicht nicht gewiss, aber die Kvaldir sind keine Narren. Sie würden nicht zurückkehren, wenn sie nicht zumindest ein wenig an ihren Sieg glauben würden.\n\nJe schneller unsere Verbündeten gerufen werden können, umso besser. Sucht nach meinen Gezeitenpriesterinnen.", completion = "Die Kvaldir haben sich als größere Bedrohung herausgestellt, als wir dachten. Aber unsere Pläne konnten sie nicht im Geringsten vereiteln. Wenn unsere Verbündeten eintreffen, werden wir mehr als genug Streitkräfte haben, um den Gezeitenjäger zu stürzen.\n\nWir müssen nur sicherstellen, dass das Beschwörungsritual abgeschlossen werden kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25897] = {title = "Seilakrobatik", objective = "Sammelt 8 Kvaldirseile.", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Überhaupt keinen!\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Unbedingt!", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25898] = {title = "Ehre und Privileg", objective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Allianzschiffe.", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Welch günstiger Zufall.\n\nJorlan ist bereits nach oben geschwommen, um ihn zu packen. Ist hochgeschwommen und wartet jetzt dort. Er meinte aber, er würde Euch die Ehre überlassen. So ist Jorlan eben.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Allianz Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25899] = {title = "Durchbruch", objective = "Tötet 10 sengende Zwielichtfürsten.", description = "Die flammende Armee, die oben auf dem Hügel so viel Verwüstung angerichtet hat, hat sich in den Osten zurückgezogen. Nur die sengenden Fürsten sind noch zugange. Wenn wir ihre Reihen durchbrechen könnten, um uns mit Hauptmann Eisenstamms Truppen zusammenzutun, könnte ihre gesamte Offensive scheitern.\n\n<Klasse>, ich bin nicht in der körperlichen Verfassung, noch weiter zu kämpfen, aber Ihr seht aus, als könntet Ihr ihnen noch die ein oder andere Blessur zufügen. Tötet diese sengenden Fürsten und formiert Euch mit Hauptmann Eisenstamm neu!", progress = nil, completion = "Wie viele habt Ihr getötet? Sieh mal an. Ein beeindruckendes Schauspiel. Ich schätze, meine Männer haben jetzt keine Ausreden mehr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25900] = {title = "Kontaktaufnahme", objective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", description = "Ich kann mir kaum vorstellen, dass Nespirah freiwillig zulässt, dass diese Naga in ihrer Schale ihr Lager aufschlagen. So wie ich das sehe, ist eines von zwei Dingen geschehen: Entweder haben sie sie überzeugt, sich ihrer Sache anzuschließen, oder sie haben sie so geschwächt, dass sie sich nicht wehren kann. Beide Möglichkeiten sind nicht gut.\n\nHier in diesem Raum sollte ich direkt mit Nespirah kommunizieren können. Finden wir es also selbst heraus. Sprecht mit mir, wenn Ihr bereit seid, <Klasse>.", progress = "Nespirah braucht unsere Hilfe. Zumindest das spüre ich ganz deutlich.", completion = "Das ist nicht so gut gelaufen. Aus irgendeinem Grund antwortet das Geschöpf mir nicht.\n\n&lt;Duarn ist sichtlich frustriert.&gt;\n\nWenn Erunak uns nur nicht verlassen hätte! Er wüsste sicher, was zu tun ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25901] = {title = "Wiederverwertung auf dem Hyjal", objective = "Sammelt 15 Pfeile des Aufsehers.", description = "Verstärkung! Ich dachte, wir müssen hier bis zum bitteren Ende kämpfen.\n\nEs sind nur noch wenige Wächter des Hyjal übrig. Zudem gehen uns langsam aber sicher die Vorräte aus. Auf dem Schlachtfeld um unsere letzte Bastion herum sollte eine Unmenge noch funktionstüchtiger Pfeile herumliegen.\n\nIch weiß, dass es für jemanden mit Euren Fähigkeiten fast schon lächerlich einfach ist, aber könntet Ihr unsere gebrauchte Munition aufsammeln? Nur so können wir unsere Vorräte aufstocken.", progress = "Pfeile des Aufsehers werden aus lebender Eiche geschnitzt und in den Mondbrunnen gesegnet. Ihre Pfeilspitzen bestehen aus Obsidian, das mit Runen verziert ist, die den Segen der Natur beschwören.\n\nSie sind nicht gerade billig.", completion = "Wunderbar! Immer noch scharf. Die Befiederung ist ein wenig blutig, aber sie fliegen noch gerade.\n\nDanke, &lt;Name&gt;. Jetzt können wir den Hyjal weiter verteidigen.", rewards = "Rasiermessersichere SchienbeinschützerBlutbolzenarmbrustAuf Euch wartet eine dieser Belohnungen:\n\nTalisman des Gedankenfiederers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25904] = {title = "Der Hammer und der Schlüssel", objective = "Tötet einen Zwielichtfeldhauptmann und besorgt Euch die Glyphe des Öffnens.", description = "Meine Nemesis. Ist noch am Leben.\nDie Diener des Feuers noch auf dem Vormarsch.\nWir müssen ihnen folgen. In ihren Bau.\n\nDie Oger kennen den Weg.\nTötet die Feldhauptmänner.\n\nBergt die Glyphe des Öffnens.\n\nSo soll es sein.", progress = "Die Glyphe. Zeigt sie mir.", completion = "Diese Macht ist uralt.\nPrimitiv.\nEinfach.\n\nWir werden sie gegen sie einsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25905] = {title = "Widder auf der Flucht", objective = "Benutzt /pfeifen, um 6 gestohlene Widder aus den Tundridhügeln zurückzuholen.", description = "Die Widder, die wir hier auf dem Gehöft Bernruh züchten und ausbilden, werden von den Gebirgsjägern von Dun Morogh als Reittiere verwendet. Ja, es sind ein paar hier, aber nicht genug, um meine Familie und all die Tiere zu schützen.\n\nEinige mutige Frostmähnenräuber stehlen in letzter Zeit unsere Widder im Schutz der Nacht und bringen sie nach Süden in die Tundridhügel. Würdet Ihr uns helfen, sie zurückzuholen? Geht nah an sie heran und stoßt einen schrillen Pfiff aus, um ihre Aufmerksamkeit zu erregen. Den Rest erledigt ihre Ausbildung.", progress = nil, completion = "Die Widder, die Ihr gerettet habt, sind in ihren Stall zurückgekehrt. Meine Familienmitglieder werden sie ab jetzt Tag und Nacht bewachen. Diese Trolle werden uns nicht noch einmal übertölpeln!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25906] = {title = "Das dritte Flammentor", objective = "Reist durch das Flammentor in der Verbrannten Ebene und sucht nach Garunda Bergkuppe.", description = "Prägt Euch die Glyphe ein.\nNehmt sie mit Euch.\nZeichnet sie auf den Boden vor dem Flammentor.\nÖstlich von hier.\nBetretet die Feuerlande.\n\nIch kann nicht mit Euch kommen.\nAber meine Kinder erwarten Euch.\n\nSucht Garunda Bergkuppe im Reich der Flammen.", progress = nil, completion = "Der Schildkrötengott hat Euch geschickt? Gepriesen sei sein heiliger Panzer! Ich dachte, ich wäre hier unten für immer gefangen.", rewards = "Schulterschutz des RettersGamaschen der glühenden MühsalRitualmesser des GlyphenzeichnersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25907] = {title = "Sklavenarbeit", objective = "Benutzt Duarns Seil, um 8 versklavte Perlenminenarbeiter zu retten.", description = "Ich werde ein wenig Zeit benötigen, um diese Barriere zu durchbrechen und mit Nespirah zu kommunizieren. In der Zwischenzeit könnt Ihr einige der Männer retten, die die Naga in den Gruben unter uns versklavt haben.\n\n<Duarn holt ein langes Seil aus seinen Roben hervor.>\n\nDas wird Euch sicher gute Dienste leisten.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;… Obwohl ich fürchte, dass ich nicht annähernd so produktiv war wie Ihr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25908] = {title = "Bestraft sie", objective = "Tötet 7 Schildwachen des Idra'kess und 7 Verzauberinnen des Idra'kess.", description = "Ich kann vielleicht nicht direkt mit Nespirah kommunizieren, aber ich kann zumindest indirekt etwas spüren. Zum Beispiel fühle ich deutlich, dass Nespirah alles andere als glücklich über die Anwesenheit der Naga hier ist.\n\nAls wir in Nespirahs Körper eingedrungen sind, sah ich Dutzende von Schildwachen und Verzauberinnen, die im zentralen Raum patrouillieren. Vielleicht könnt Ihr das Leid der Ahnin lindern, indem Ihr ihre Zahlen verringert.", progress = nil, completion = "Könnt Ihr es fühlen? Wenn Ihr nur einen Tropfen Schamanenblut in Euch tragt, müsst Ihr das Gefühl der Erleichterung in der Luft spüren.\n\nNespirah ist erfreut. Vielleicht spricht sie jetzt endlich mit uns.", rewards = "PolychaetafußschützerKilt der Schamanischen TräumeGestohlenes Tuch des Idra'kessIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25909] = {title = "Fang den Krebs", objective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "&lt;Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.&gt;\n\nEr sieht nicht besonders beeindruckend aus, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25910] = {title = "Die Zeit für Gnade ist vorbei", objective = "Tötet 10 geschmolzene Peiniger und 4 Meister der Schattenflamme.", description = "Diese Höhle ist der reinste Höllenschlund, <Name>. Sie ist voller abscheulicher Schrecken aus der Tiefe.\n\nIch möchte nicht, dass diese… Kreaturen… durch das Portal in die Außenwelt gelangen. Tötet sie alle!", progress = nil, completion = "Also ist es vollbracht.\n\nDas Wissen, dass der Schattenhammerkult gemeinsame Sache mit solch abstoßenden und bösartigen Wesen macht… bringt mein Blut zum Kochen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25911] = {title = "Willkommene Nachrichten", objective = "Kehrt zu Kapitän Taylor am Stillen Strand zurück.", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, <Name>.", progress = nil, completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, &lt;Name&gt;. Ich weiß nicht, wie ich Euch für all das belohnen kann, das Ihr in diesem Meer getan habt, aber ich werde mir etwas einfallen lassen.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", rewards = "Schulterplatten des wahren LeuchtfeuersHarfenschneckenhandgelenksschützerRoben des wässrigen RettersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25912] = {title = "Gute alte Zeit", objective = "Findet das Zeichenbuch der Urahnin Sareth'na.", description = "Die Welt gerät aus den Fugen, <Name>. Vertraute Feinde versuchen uns an einer Seite zu zerstören, während uralte Kräfte uns von der anderen bedrängen.\n\n<Urahnin Sareth'na seufzt.>\n\nIch habe bessere Zeiten erlebt - hellere Tage, und ich sehne mich nach ihnen...\n\nHinter dem Steinkrallengipfel stehen die Ruinen unseres alten Außenpostens - die Dunkelheit hat ihn überrannt. Solltet Ihr Euch in dieser Gegend aufhalten, könntet Ihr dann nach meinem Zeichenbuch suchen? Es steckt voller glücklicher Erinnerungen. Ich würde Euch gut für seine Rückgabe belohnen.", progress = "Habt Ihr mein Zeichenbuch gefunden?", completion = "Ihr habt es gefunden! Möge Elune Euch segnen, Kind! Vielleicht verleiht mir dieses Buch die Kraft weiterzumachen.", rewards = "Elunegesegneter BogenSareth'nas MantelungKopfschutz des TrostesBeinschützer der verschlungenen WegeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25913] = {title = "Die letzte Ruhe", objective = "Bergt 8 Schildwachengleven.", description = "Als die Horde ins Steinkrallengebirge einmarschierte, fiel mir auf, dass einige der Schildwachen krank wurden. Kurz darauf verhielten sie sich seltsam. Als der erste Tentakel aus dem Boden schoss, griffen die kranken Schildwachen uns an. Wir verloren den Außenposten kurz danach...\n\nDie Schildwachen im Gipfel sind nur noch Hüllen. In ihnen steckt etwas Böses. Bettet die Schildwachen zur letzten Ruhe und bringt ihre Gleven an Euch. Mit jeder zurückgebrachten Gleve kann eine gefallene Schwester identifiziert werden.", progress = "Bergt die Schildwachengleven, <Name>. Jede Gleve lässt sich einer Schildwache zuordnen.", completion = "Danke, &lt;Name&gt;. Auf jede der Gleven ist der Name ihrer Besitzerin eingestanzt. Jetzt können wir ihre Familien benachrichtigen und ihren Seelen Frieden geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25914] = {title = "Zurück in die Tiefe!", objective = "Tötet Aph'lass und 10 einfallende Tentakel.", description = "Ranken schießen aus dem Boden und terrorisieren den Steinkrallengipfel. Meine Schildwachen werden ihrer nicht Herr.\n\nIch vermute, dass es im Herzen des Steinkrallengipfels eine Macht gibt, die diese Ranken kontrolliert. Wenn wir diese Macht aufhalten, werden die Ranken vielleicht in die Tiefen zurückkehren, aus denen sie gekommen sind.", progress = nil, completion = "Der Tod des Boten Aph'lass hat leider nicht zu einem Ende der Rankenangriffe geführt. Ihr habt getan, was Ihr konntet, &lt;Name&gt;. Dafür danke ich Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25915] = {title = "Tortollas Stärke", objective = "Begleitet einen Abkömmling von Tortolla zu einem Nemesiskristall. Falls Ihr Euren Begleiter verliert, meldet Euch bei Garunda Bergkuppe.", description = "Der dunkle Usurpator Nemesis floh hierher, als die Feuer des Hyjal verglommen. Wir sind noch nicht stark genug, um Nemesis zu besiegen, <Name>, aber wir können vielleicht seine eigene Stärke gegen ihn verwenden.\n\nIch werde einen Abkömmling Tortollas mit Euch entsenden, eines der Kinder, das Ihr aus der Verderbnis des Zwielichts errettet habt.\n\nSucht in den Tiefen dieser Höhle nach einem Nemesiskristall und erlaubt der jungen Schildkröte, ihn zu untersuchen.\n\nFalls Ihr Euren Begleiter verliert, meldet Euch bei mir!", progress = nil, completion = "Ah, ja, ja… Die geheime Stärke von Nemesis, zugänglich hier in diesen Höhlen.\n\nWir wissen alles, was wir wissen müssen, &lt;Name&gt;. Jetzt ist es Zeit, der Angelegenheit ein Ende zu setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25916] = {title = "Durchbruch", objective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", progress = nil, completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25917] = {title = "Wir sind nicht allein", objective = "Findet die Überlebenden der Allianz in Nespirah in Vashj'ir.", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Allianzsklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, <Name>. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", progress = nil, completion = "&lt;Name&gt;… Seid Ihr das?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25918] = {title = "Hoffnungslos ausrüstungslos", objective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Piekse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "&lt;Admiral Dvorek bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.&gt;\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, &lt;Name&gt;. Wir werden sie sinnvoll einsetzen.", rewards = "Sandgeschliffener BeschützerSchnabellose StangenwaffeAuf Euch wartet eine dieser Belohnungen:\n\nSchwärzlicher Perlenring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25919] = {title = "Voller Körpereinsatz", objective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", description = "<Kapitän Taylor lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht finden Eure Waffen ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", progress = nil, completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25920] = {title = "Immer noch wertvoll", objective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n&lt;Valoren verstaut die Perlen unter ihrer Rüstung.&gt;\n\nUnd jetzt müssen Kapitän Taylor und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25921] = {title = "Aufseher Idra'kess", objective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", description = "Meine Männer lassen nach, <Name>. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Südosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten.", progress = nil, completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Kapitän Taylor hat mir den Rest berichtet.\n\n&lt;Duarn schließt die Augen und nickt.&gt;\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", rewards = "Helm des zermalmten AufsehersGorgonischer GürtelSägefischgurt des ErdheilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25922] = {title = "Die Erweckung der Bestie", objective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", description = "Dank Euch und dem Kapitän hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", progress = nil, completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Dem Licht sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25923] = {title = "Vernichtet Nemesis", objective = "Benutzt das Totem von Tortolla, um einem Abkömmling von Tortolla dabei zu helfen, Nemesis zu besiegen. Falls Ihr Euren Schildkrötenfreund verliert, sprecht mit Garunda Bergkuppe.", description = "Euer Schildkrötenfreund kann diese neu gefundene Macht nutzen, um Euch beide für einen kurzen Augenblick unverwundbar zu machen. Ihr könnt Euch also in Euren \"Panzer\" verkriechen, um Nemesis' schlimmsten Zorn zu entgehen. Ruft dazu einfach dieses Totem herbei.\n\nDas ist alles, was ich für Euch tun kann. Ihr und ein Abkömmling von Tortolla müsst gemeinsam Nemesis besiegen, ein für alle Mal. Vernichtet den Usurpator!\n\nFalls Ihr Euren Schildkrötenfreund verliert, kehrt zu mir zurück.", progress = nil, completion = "Der Usurpator ist nicht mehr!\n\nDer Schattenhammer hat davon geträumt, sich sein eigenes Pantheon von Göttern zu schaffen, die über Land, Meer und Luft herrschen. Doch mit Eurer Hilfe wurden sie alle vernichtet. Wir müssen sofort Tortolla davon berichten!", rewards = "FeindeszerschmettererTortollas abgeworfene SchuppenGamaschen des bezwungenen ThronräubersBefreiende KroneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25924] = {title = "Die Pflicht ruft", objective = "Fahrt mit dem Söldnerboot zur Schlacht.", description = "Hört zu, <Volk>!\n\nAn der Küste der Östlichen Königreiche ist eine neue Landmasse aufgetaucht! Eine wichtige Schlacht um die Kontrolle dieser Insel ist bereits im vollen Gange.\n\nWenn wir hier gewinnen, ist Sturmwind komplett unverteidigt!\n\nJetzt ist die Zeit, um zuzuschlagen!\n\nMeldet Euch sofort an den Docks, damit man Euch zur Schlacht bringt.\n\nAll unsere Kriegsschiffe befinden sich bereits im Kampf, also werdet Ihr ein Söldnerboot nehmen, das vom Kriegshäuptling selbst angeheuert wurde.", progress = nil, completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Phase Binding\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25925] = {title = "Thal'darahs Rache", objective = "Tötet 20 Soldaten der Horde und zerstört 3 Verwüster von Krom'gar im Kriegsnarbental.", description = "Wir müssen versuchen, Kontakt zum Weitblicktal im Süden herzustellen. Unsere darnassischen Glevenwerfer stehen Euch zur Verfügung, <Name>. Schlagt mit ihnen eine Schneise in die anrückenden Hordenstreitkräfte und räumt einen Weg ins Weitblicktal frei.\n\nHoffentlich ist es noch nicht zu spät, um das Tal zu retten. Sollte das Weitblicktal unversehrt sein, dann sucht dort nach Hierophant Malyk und informiert ihn über unsere Lage.", progress = nil, completion = "Wir haben die Explosion der Bombe beobachtet. Was für eine furchtbare Zerstörung... Das Weitblicktal ist unversehrt, was immer das auch nutzen mag. Allerdings wissen wir nicht, wohin wir fliehen sollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25926] = {title = "Modernder Hass", objective = "Tötet 10 modernde Morastbestien.", description = "Die Morastbestien im Westen sind nicht meine Brüder... sie sind Symptome der gestörten Erde, eine modernde, Gestalt gewordene Verderbtheit.\n\nIhr würdet es nicht verstehen... sie nehmen die Gestalt meines Volkes an, sind jedoch mit verrottenden Sporen durchsetzt. Sie vertreiben das blühende Leben aus dem Sumpf. Sie nehmen alles und lassen nur Verderbtheit zurück. Nichts bleibt zurück! Nichts!\n\nTröstet mich, <Volk>. Tötet die Morastbestien und reinigt das Land. Vielleicht bringt mir das Frieden.", progress = nil, completion = "Ahhh... ja. Der Sumpf leidet weniger als zuvor.\n\nEs gibt jedoch noch mehr Bedrohungen. Sie lauern. Ich kann sie sehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25927] = {title = "Brennende Bedrohung", objective = "Tötet 8 zügellose Feuerelementare.", description = "Die Flammen bedrohen mich schon seit langer Zeit... zu langer Zeit... aber es sind keine kleinen mehr, nicht mehr nur noch Funken...\n\nDie Felder brennen! Die Hügel und Hochlande schreien, <Volk>, sie schreien. Die Elementare, die hierher gebracht wurden, lassen nur Tod zurück.\n\nDas darf nicht so weitergehen. Haltet sie auf. HALTET SIE AUF! Vernichtet die Flammenboten...", progress = nil, completion = "Ja... die Flammen vergehen. Nun herrscht Friede. Das Land findet Frieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25928] = {title = "Tortollas Triumph", objective = "Geht erneut durch das Flammentor und kehrt zu Tortolla auf der Verbrannten Ebene auf dem Hyjal zurück.", description = "Ich werde die Abkömmlinge von Tortolla hier heraus begleiten und dieses verfluchte Portal versiegeln.\n\nIch überlasse es Euch, Tortolla von unserem Sieg zu berichten. Tretet einfach wieder durch das Flammentor. Der Ahn wird begeistert sein!", progress = nil, completion = "Ihr wart in den Feuerlanden?\n\nNemesis ist tot?\n\nAlso ist es vorbei.\n\nIch danke Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25929] = {title = "Seetauglich", objective = "Sammelt 3 Salzwasserseesterne und ein Tritonshorn am Meeresgrund im Verhängnis der Legion.", description = "Grüße, <Klasse>. Ich bin Erunak, einer der Überlebenden dieses Unglücks.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga durchstreifen die Gewässer und greifen alles an, was noch am Leben ist.\n\nIhr seid an die hiesigen Bedingungen noch nicht ausreichend angepasst, um zu überleben, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Euch dabei helfen wird, Euch an die neue Umgebung zu gewöhnen.", progress = "Konntet Ihr alle Gegenstände finden, die ich brauche, <Volk>?", completion = "Bitteschön, &lt;Klasse&gt;. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", rewards = "Ihr erlernt:\n\nSeetauglich\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSeetauglich\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25930] = {title = "Talstürmer", objective = "Erklimmt mit Salsburys Raketenpack den Vulkan im Verbrannten Tal.", description = "Man hat mir erzählt, dass das Verbrannte Tal vor dem großen Umbruch eine Mulde war, ohne Zugang zum Meer. Doch wenn man nun nach Süden blickt, wird deutlich, dass das Verbrannte Tal längst kein Tal mehr ist, sondern ein Gebiet mit großer vulkanischer Aktivität.\n\nSalsbury hat ein Gerät konstruiert, mit dem wir den Vulkan erklimmen können. Benutzt es, um zum Gipfel zu gelangen. Findet heraus, was dort vorgeht.\n\nIch werde mit dem Gnomcordergerät, das Salsbury mir freundlicherweise geschenkt hat, in Kontakt bleiben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25931] = {title = "Die Brut von Seldarria", objective = "Zerstört 5 Eier von Seldarria.", description = "<Der Gnomcorder summt.>\n\nSeid sehr vorsichtig, <Name>. Weckt bloß nicht den schwarzen Drachen auf.\n\nSeht Euch um. Wenn dies ein Nest ist, dann sollte es in der Nähe schwarze Dracheneier geben. Sucht das Gebiet nach Eiern ab und zerstört alle, die Ihr seht.\n\nKehrt zu mir zurück, wenn Ihr Seldarrias Eier gefunden und zerstört habt.\n\nMöge Goldrinn über Euch wachen.", progress = nil, completion = "Ein durchschlagender Erfolg! Es ist vielleicht nur ein kleiner Sieg über die Brut von Todesschwinge, aber wenigstens ein Sieg!", rewards = "EierbrecherGugel des GoldrinnakolythenSchulterschutz des BruttötersGesegnete Hände des HierophantenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25932] = {title = "Jede Nacht ein Überfall", objective = "Helft Unteroffizier Flinthammer und seinen Gebirgsjägern, das Gehöft Bernruh gegen die Frostmähnenräuber zu verteidigen.", description = "Die Berichte, die ich Hauptmann Tharran schicke, spiegeln das Ausmaß des Ärgers, den uns die Frostmähnen bereiten, nicht richtig wider. Euer Angriff auf das Dorf hat etwas Druck von uns genommen. Die Überfälle finden immer noch häufig statt, aber es gibt nicht mehr so viele Trolle wie früher.\n\nTrotzdem sind meine Männer erschöpft. Die Moral sinkt. Würdet Ihr uns im Kampf gegen die Frostmähnenräuber unterstützen? Sie können jederzeit auftauchen.", progress = nil, completion = "Dank Eurer Hilfe ist es uns gelungen, die Räuber deutlich zu schwächen. Solche Verluste haben sie seit Beginn der Überfälle nicht mehr erlitten. Wir müssen diesen Vorteil nutzen.", rewards = "Armschienen des nächtlichen ÜberfallsRoben der endlosen SchlachtzügeStiefel des erschöpften RäubersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25933] = {title = "Hilfe für den Steinbruch", objective = "Sprecht mit Großknecht Steinbraue im Steinbruch Gol'Bolar.", description = "Ich möchte Euch noch einmal für Eure Hilfe danken, <Name>.\n\nMein Cousin hat früher in den Minen unter dem Steinbruch Gol'Bolar gearbeitet, aber seit die Troggs dort eingedrungen sind und die Kontrolle übernommen haben, geht das nicht mehr. Der Steinbruch und sein Lager liegen südöstlich des Gehöfts. Würdet Ihr Euch dort bei dem Großknecht melden und herausfinden, ob man etwas unternehmen kann?", progress = nil, completion = "Unteroffizier Flinthammer? Der Name sagt mir nichts, aber einer der Minenarbeiter heißt Flinthammer. Er gehört zu den Glücklichen, die aus der Mine fliehen konnten, aber die meisten anderen sind dort unten eingeschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25934] = {title = "Weltneuheit: Gnomgen", objective = "Beschafft 1 flammendes Herz des Feuers.", description = "Guten Tag, Bürger, ich möchte mich Euch vorstellen. Ich bin Salsbury, bald der welterste Gnomgen. Malyk hat mir versichert, dass er mir nach Beendigung meiner Arbeit das Geschenk des Worgen machen wird.\n\nSo, da wir uns jetzt kennen, möchte ich eine Bitte äußern!\n\nSüdlich von hier, im Verbrannten Tal, treiben neu erschaffene Feuerelementare ihr Unwesen. Ich brauche dringend ein seltenes flammendes Herz des Feuers von einem der Unholde. Beschafft es für mich, dann komme ich dem Leben eines Gnomgen einen Schritt näher!", progress = "Habt Ihr das flammende Herz des Feuers bekommen?", completion = "Hervorragend. Damit kann ich meine letzte Aufgabe beenden und hoffentlich die Wolfsform bekommen!\n\n&lt;Salsbury heult.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25935] = {title = "Hungrige Welpen", objective = "Beschafft 6 Schwarzdrachenwelpenfilets.", description = "Ah, ein Neuankömmling! Gut, dass Ihr hier seid <Junge/Schwester>! Die Welpen sind hungrig, aber uns ist die Nahrung ausgegangen.\n\nZum Glück lieben sie Drachenfleisch, was es in rauen Mengen im Verbrannten Teil südlich von hier gibt.\n\nSeid ein <guter Junge/gutes Mädchen> und besorgt mir ein paar Pfund Schwarzdrachenwelpenfilet.", progress = "Beeilt Euch, <Name>, die Welpen sind hungrig!", completion = "Hervorragend. Die Hunde werden gut zu fressen bekommen und unseren Außenposten wochenlang verteidigen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25936] = {title = "Wie ich Euch, so Ihr ihnen", objective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", progress = "Konntet Ihr die Krieger retten, <Volk>?\n\nOhne ihre Hilfe sind wir verloren…", completion = "Während Ihr fort wart, konnte ich einige der gefallenen Krieger wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25937] = {title = "Unermessliche Reichtümer", objective = "Bergt 8 gefrorene Artefakte aus der Mine des Steinbruchs Gol'Bolar.", description = "In dem Steinbruch wurde nicht nur geschürft. Ich leitete ein Ausgrabungsteam der Forscherliga. Wir suchten nach wertvollen alten Artefakten.\n\nMir gelang die Flucht, aber meine Kollegen hielten sich tiefer in der Mine auf und überlebten den ersten Angriff der Troggs nicht.\n\nSie waren sehr stolz auf ihre Arbeit und riskierten ihr Leben, um mehr über unsere Geschichte herauszufinden. Wenn Ihr in die Minen geht, dann nehmt diese Spitzhacke mit. Vielleicht findet Ihr ja etwas in den Stollen, die von den Ausgräbern begonnen wurden.", progress = "Habt Ihr dort unten Artefakte gefunden?", completion = "Ich danke Euch für die Bergung dieser Artefakte. Ich werde dafür sorgen, dass sie im Museum von Eisenschmiede ausgestellt werden, zusammen mit der Geschichte derer, die bei ihrer Bergung ums Leben kamen.", rewards = "Hose des ArchäologenWanderstiefel aus Dun MoroghArmschienen des MuseumswächtersIhr bekommt:\n\nSchürferbeutel"}
MultiLanguageQuestData['de'][25938] = {title = "Hilfe für Desolace", objective = "Meldet Euch bei Offizierin Jankie in Tethris Aran in Desolace.", description = "Ich habe eine verstörende Nachricht aus Nijelspitze in Desolace erhalten. Der große Umbruch hat anscheinend neue Probleme mit sich gebracht, auf die sie nicht vorbereitet waren. Mehr weiß ich nicht.\n\nMeldet Euch bei Offizierin Jankie in Desolace. Sie wird Euch den Weg nach Nijelspitze weisen.\n\nViel Glück, <Name>.", progress = nil, completion = "Halt, Fremder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25939] = {title = "Feuerteufel", objective = "Löscht 7 Moorfeuer mit der gesegneten Flutlilie.", description = "Die Elementare, die auf dem Hügel der Düsterschmiede randalieren, stecken das Land unter sich in Brand. In einem Sumpf wie diesem findet das Feuer im tiefen Moos und Torf ausreichend Nahrung.\n\nLöscht die Feuer, bevor sie sich ausbreiten. Nehmt diese Blume... sie wurde mit dem Regen der Natur gesegnet und wird Euch ermöglichen, die Feuer zu löschen.\n\nIhre Blüten könnten sich außerdem als nützlich gegen die Elementare erweisen.", progress = nil, completion = "Ihr habt nicht nur das Land vor weiterem Leid bewahrt, sondern uns auch geholfen, den Sumpfwächter zu besänftigen.\n\nHabt Dank, &lt;Name&gt;.", rewards = "FlutlilienrobenBesänftigende HändeKluftmoosarmschienenMoorfeuerbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25940] = {title = "Letztes Gefecht am Rauschenden Hain", objective = "Meldet Euch bei Bewahrer Taldros im Rauschenden Hain auf dem Hyjal.", description = "Möglicherweise habe wir jetzt eine Chance, die Flammen dank Eurer Arbeit in dem Inferno zu besiegen.\n\nDennoch sind weitere Wildtiere bedroht. Bewahrer Taldros rannte Richtung Norden durch die Flammen zum Rauschenden Hain.\n\nSeht, ob Ihr ihm helfen könnt!", progress = nil, completion = "Die Flammen verschlingen den Wald!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25941] = {title = "Rast für die Erschöpften", objective = "Sprecht mit Legionär Nazgrim.", description = "Ihr habt Eure Aufgabe gut gemacht, <Volk>, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.\n\nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.\n\nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.\n\nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.\n\nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.", progress = nil, completion = "Ich verstehe, &lt;Volk&gt;.\n\nIch weiß, wie dringend es ist, aber diese Männer sind nicht in der Lage zu kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25942] = {title = "Verschafft uns Zeit", objective = "Tötet 8 Räuber des Zin'jatar im Verhängnis der Legion.", description = "Viele gute Krieger mussten heute ihr Leben lassen.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", progress = "Habt Ihr diesem schuppigen Abschaum einen Grund zum Nachdenken gegeben, <Klasse>?", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um uns die nötige Zeit zu verschaffen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25943] = {title = "Siege gehen durch den Magen", objective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", description = "Wenn ich diese Orcs für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Mampf, kein Kampf.\n\nDiese Krieger sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass die Naga angreifen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", progress = "Habt Ihr Nahrung für die Truppen, <Volk>?", completion = "Ein leckerer Happen.\n\nBald sind wir wieder kampfbereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25944] = {title = "Der Horde alte Kleider", objective = "Sammelt 5 Äxte von Orgrimmar, 5 Brustplatten von Orgrimmar und 5 Helme von Orgrimmar am Meeresboden oder von Strauchdieben der Gilblin im Verhängnis der Legion.", description = "In unserem Kampf gegen das Ertrinken waren meine Orcs und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich glaube ihm.\n\nWenn wir siegen wollen, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen.\n\nEs sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks hier und im Norden liegen.\n\nSchnell, <Volk>. Der Feind könnte jeden Moment eintreffen.", progress = "Konntet Ihr unsere Ausrüstung zusammensammeln, <Volk>?", completion = "Das habt Ihr gut gemacht, &lt;Volk&gt;.\n\nUnsere Überlebenschancen steigen stetig.", rewards = "WellhornschalenschulterschützerSchiffbruchgamaschenLegionär Nazgrims HackbeilDer folgende Zauber wird auf euch gewirkt:\n\nImmortal Coil Invis Swap 2-3\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25945] = {title = "Wir haben hier nur eine Aufgabe, vielleicht auch zwei...", objective = "Reist mit dem Wagen von Krom'gar zum Bruch im Steinkrallengebirge.", description = "Ihr seid jetzt in Höllschreis Armee, <Name>, und in Höllschreis Armee treten wir anderen in den Hintern und sind verdammt nachtragend. Die Zeiten, in denen Leute auf den Straßen Orgrimmars verhungerten, während wir Verträge mit den Elfen schlossen, sind vorbei. Wir holen uns jetzt, was wir brauchen. Kalimdor gehört der Horde!\n\nDie Allianz versucht bei jeder Gelegenheit, unsere Expansion aufzuhalten. Diesen Schweinslutschern gehört bereits ein Großteil der Östlichen Königreiche, aber das reicht ihnen nicht!\n\nOberanführer Krom'gar will mehr Truppen ins Steinkrallengebirge verlegen. Schließt Euch der Karawane westlich von hier an. Geht!", progress = nil, completion = "Solange Ihr im Steinkrallengebirge seid und als ein Soldat Krom'gars kämpft, werdet Ihr Uniform tragen! Ist das klar? HÖRT Ihr mich, Grunzer? Wenn ich Euch ohne Höllschreis geliebten Waffenrock sehe, werde ich Euch so heftig in den Hintern treten, dass Ihr Schnürsenkel ausspuckt.", rewards = "Ihr erlernt:\n\nGrunzer von Krom'gar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25946] = {title = "ScHELMenstück", objective = "Bringt die Kampfschwimmerausrüstung der Allianz zu Legionär Nazgrim in der \"Ewiger Kreislauf\".\n\nBereitgestellter Gegenstand: \n", description = "<Dieser Helm und das passende Zubehör sind mit dem Siegel von Sturmwind gekennzeichnet. Er stammt ohne Zweifel von einem Allianzschiff, dass ein ähnliches Schicksal wie Euer Schiff erlitten hat.>\n\n<Wenn Ihr den Helm genauer betrachtet, fällt Euch auf, dass er viel zu gut verarbeitet und stabil ist, um zu einer normalen Tauchausrüstung zu gehören. Vielleicht weiß Nazgrim ja, was es damit auf sich hat...>", progress = nil, completion = "Blut und Donner!\n\nDas ändert alles, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25947] = {title = "Wer es findet, darf es behalten", objective = "Sammelt 5 Teile einer Kampfschwimmerausrüstung von Sturmwind.", description = "Ich erkenne diesen Helm, <Volk>. Es war klug von Euch, ihn mir zu bringen.\n\nDie Allianz hat eine Spezialeinheit, die für Erkundungen und Kampfeinsätze unter Wasser ausgebildet und ausgerüstet wurde.\n\nWie es scheint, haben sie in dieser Gegend weitaus mehr vor, als sich gegen unseren Angriff zu verteidigen.\n\nEs muss da unten noch mehr davon geben. Wenn Ihr sie findet, könnte sich das Blatt für unseren Vorposten schnell wenden.", progress = "Konntet Ihr weitere Teile der Allianzausrüstung finden, <Name>?", completion = "Gut gemacht!\n\nJetzt sind wir so bereit wie nie, uns den Naga entgegenzustellen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25948] = {title = "Genug gewartet!", objective = "Sprecht mit Legionär Nazgrim an Bord der \"Ewiger Kreislauf\".", description = "Es ist an der Zeit, <Klasse>.\n\nWir sind so bereit wie es nur geht!\n\nIch werde zu den Truppen sprechen und dann schwimmen wir ins Meer, dem Schicksal entgegen.", progress = nil, completion = "Keine Zeit für Ansprachen.\n\nAuch gut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25949] = {title = "Blut und Donner!", objective = "Helft Legionär Nazgrim dabei, die \"Ewiger Kreislauf\" zu verteidigen.", description = "Die Zeit ist gekommen, um uns zur Wehr zu setzen, <Volk>.\n\nWir werden dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass dieser Nagaabschaum es sich zweimal überlegt, bevor er sich ihm erneut nähert!\n\nFür die Horde!", progress = nil, completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", rewards = "Handschutz des SchonerrettersArmschienen der verletzten IntegritätKapuze des abgeschüttelten DrangesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25950] = {title = "Tod den Sira'kess", objective = "Tötet 10 Naga der Sira'kess.", description = "Ihr seid also <der/die> berühmte <Name>, von <dem/der> alle reden? Schön, Euch kennenzulernen, Schätzelchen. Kommt, lasst mich mal ein Auge riskieren.\n\nGenug Geplauder, kommen wir zur Sache, ja? Ich will, dass Ihr für mich nach Nordwesten zu der Frontlinie der Sira'kess schwimmt und den Naga ordentlich einen vor den Latz knallt.\n\nNix Wildes. Die sind nur auf Streit aus und den sollen sie kriegen!", progress = nil, completion = "Nicht schlecht, Herr Specht, &lt;Name&gt;! Das wird den Schlangen zeigen, wo der Hammer hängt und wer hier der Boss ist!\n\nUnd jetzt zu dem versprochenen Umtrunk - lieber einen Branntwein aus Zuckerrohr oder einen guten Traubensaft?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25951] = {title = "Schlussurteil", objective = "Haltet die Brücke auf der Terrasse von Quel'Dormir, bis Lady Sira'kess' Verbündete eintreffen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", description = "Geht zur Brücke im Osten, schnell. Lady Naz'jar und der Tiefenlord sollten sich dort mit den verbleibenden Streitmächten aufhalten.\n\nFolgt wie immer den Anweisungen unserer Lady. Haltet die Brücke, bis wir das Ritual beenden können.\n\nSobald unsere Verbündeten eintreffen, sind die Kvaldir dem Untergang geweiht.", progress = "Bleibt an unserer Seite, Kriegsmaid. Am heutigen Tage werden wir nicht fallen.", completion = "Ich könnte mir keine fähigere Kriegsmaid wünschen als Euch. Ihr habt Euch heute große Ehre verdient.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBattlemaiden Vision 3 Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25952] = {title = "Überraschungsangriff", objective = "Tötet 10 Patrouillen der Azsh'ir.", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Klasse&gt;.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25953] = {title = "Schnelles Handeln", objective = "Zerstört 8 Überwacher der Azsh'ir.", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Und genau rechtzeitig. Der Hauptmann hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", rewards = "Brustschutz der alarmierenden TräumeSchlingaalsandalenAuf Euch wartet eine dieser Belohnungen:\n\nKaurischneckenanhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25954] = {title = "Suche nach der Vergangenheit", objective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", description = "Hört mal... <Name>, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nZu der Zeit als Azshara regierte, war dies eine königliche Stadt der Elfen. Tief in dieser Stadt liegen die Schlüssel zu lange verschollenem Wissen und Artefakten von unermesslichem historischen Wert. Bitte, haltet doch nach interessanten Gegenständen Ausschau, wenn Ihr ohnehin schon in der Stadt seid.", progress = nil, completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der Großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", rewards = "Improvisierter HistorikerumhangBeinschützer der GöttlichkeitZeiterhellende ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25955] = {title = "Ein besserer Standort", objective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Süden der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", progress = nil, completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, &lt;Klasse&gt;.\n\nEs klingt so, als ob das Gebäude nördlich der Gärten einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25956] = {title = "Auf dem Schlachtfeld", objective = "Bringt das Bruchstück zurück zur Ruhestatt der Legion.", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", progress = "Ja, <Klasse>?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25957] = {title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", objective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", progress = nil, completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Hauptmann es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Hauptmann und seine Soldaten. Wir müssen sie warnen.", rewards = "Naz'jars BrustschutzGurt des WundenversorgersAuf Euch wartet eine dieser Belohnungen:\n\nFokus der Wellensprecherin\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSee Quest Invis 2\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25958] = {title = "Ein Blick nach vorne", objective = "Sprecht mit Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir.\n\nBenutzt das Seepferdchen von Wellensprecherin Tulra, um den Vorposten schnell zu erreichen.", description = "Der Hauptmann hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er trifft dort Vorbereitungen für eine Art Angriff auf die Naga.\n\nIhr solltet sofort zu ihm gehen und ihn über das Ausmaß dessen, was Ihr beobachtet habt, unterrichten. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferdchen. Es kennt den Weg.", progress = nil, completion = "Schön Euch wiederzusehen, &lt;Klasse&gt;. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25959] = {title = "Deutliche Ziele", objective = "Tötet 10 Naga der Streitmächte, die sich unter der südlichen Terrasse auf der Grundebene zusammenziehen.", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, <Klasse>. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden, unter der Terrasse, ein wenig ausdünnen?", progress = nil, completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25960] = {title = "Nicht ganz unvorbereitet", objective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Horde auf den Felsvorsprüngen um das nördliche Ende der Gärten von Quel'Dormir.", description = "Ich habe Euer Gespräch mit dem Hauptmann gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Bringt ihnen mehr Armbrustbolzen, um uns etwas Zeit zu verschaffen.", progress = nil, completion = "Ihr seid wahrscheinlich der zuverlässigste &lt;Volk&gt;, den ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", rewards = "GrenzgängergroßhelmSchulterpolster des SeebognersTreter der VerläßlichkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25962] = {title = "Ausreichende Inspiration", objective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südlichen Terrasse hängen.", description = "Ich war schon überall. Habe alle möglichen Dinge in die Luft gejagt. Ich dachte, ich hätte vielleicht Probleme damit, den neusten Entwicklungen zu folgen. Ihr wisst schon, wegen dem Wasser und so, aber es ist alles nur eine Frage der Inspiration.\n\nIch habe etwas gefunden, das explosiv genug ist, um Bomben daraus zu bauen. Unter der Terrasse im Südwesten hängen ein paar Tangblasen herab. Normalerweise speichert Tang Gas, das ihn zum schweben bringt, doch dieses schwere Gas ist ganz anders. Es bringt ihn dazu, hängen zu bleiben. Außerdem eignet es sich perfekt für Explosionen.\n\nKönnt Ihr mir etwas davon sammeln?", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein &lt;Volk&gt; nach meinem Geschmack.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25963] = {title = "Blitzangriff", objective = "Sprecht mit Fiasco Siedefeix, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der südlichen zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", progress = nil, completion = "Ihr habt Euch da oben großartig geschlagen, Soldat! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", rewards = "AtolltreterTigerhaigürtelAuf Euch wartet eine dieser Belohnungen:\n\nPelagisches Prisma\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25964] = {title = "Gefallen, aber nicht vergessen", objective = "Rettet 6 verletzte freiwillige Angreifer.", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", progress = nil, completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25965] = {title = "Einschätzung des Erfolgs", objective = "Späht den Rand der runden Terrasse im Nordwesten und den Tunnel unter der Haupttreppe im Norden aus. Beides befindet sich auf der Terrasse von Nar'shola, in der mittleren Ebene der Ruinen.", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Hauptmann zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben.\n\nEine ihrer größten Gruppen befand sich im nordwestlichen Teil dieser runden Terrasse und die andere ein wenig weiter im Norden, in dem kleinen Tunnel, ebenfalls auf der mittleren Ebene der Ruinen.\n\nInterressiert an ein wenig Arbeit als Kundschafter?", progress = "Wisst Ihr schon etwas Neues… zu ihren Zahlen?", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, &lt;Name&gt;, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25966] = {title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", objective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", progress = nil, completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", rewards = "Handschutz der KvaldirVision der KriegsmaidUralter beth'moranischer UmhangAuf Euch wartet eine dieser Belohnungen:\n\nSchlachtstandarte der Kvaldir\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25967] = {title = "Haltlos", objective = "Benutzt das Seepferdchen von Wellensprecherin Tulra, um zu Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir zurückzukehren.", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", progress = nil, completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Schön, Euch in einem Stück zu sehen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25968] = {title = "Ein verzweifelter Plan", objective = "Trefft Euch mit Fiasco Siedefeix auf dem Biel'arangrat.", description = "Toldrek und Fiasco sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Wir werden hier nicht viel länger aushalten. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", progress = nil, completion = "Schaut Euch an, Ihr seid ein echter Held des Meeres! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Ihr müsst stolz auf Euch sein!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25969] = {title = "Feindliche Gewässer", objective = "Tötet 10 Schlickhautschnorrer.", description = "Fiasco kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Gilblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", progress = nil, completion = "Je weniger Gilblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25970] = {title = "Immer vorbereitet", objective = "Besorgt eine Überlebensausrüstung der Horde.", description = "Es ist nicht weit bis zur Oberfläche. Eigentlich alles kein Problem. Doch es ist nicht leicht, Ausrüstung nach da oben zu bringen. Sie ist einfach zu schwer.\n\nAlle Schiffe in der Flotte der Horde sind mit einer Überlebensausrüstung ausgestattet. Ich hatte einen Ballon aus so einer Überlebensausrüstung, aber er musste sich leider den Widrigkeiten geschlagen geben. Ich brauche noch eine Überlebensausrüstung.\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren, die Überlebensausrüstung nicht mitzunehmen. Mehr zum Überleben für uns!", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", rewards = "NephropsistreterFußpolster der AnomuraStab der rückwirkenden VorbereitungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25971] = {title = "Seilakrobatik", objective = "Sammelt 8 Kvaldirseile.", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Seile und Bomben, das ist alles, was sie enthalten sollten. Der Rest des Krams ist einfach nur Platzverschwendung.\n\nBis auf den Ballon vielleicht. Der kommt uns jetzt gerade gelegen.\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Seile sind nicht optional!", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25972] = {title = "Ehre und Privileg", objective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Hordenschiffe.", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Gut gemacht.\n\nToldrek ist bereits nach oben geschwommen, um ihn zu packen. Er macht sich Sorgen um die Strömung und all so was. Er meinte aber, er würde Euch die Ehre überlassen. Netter Kerl - Keine Ahnung, wie er am Leben bleibt.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Horde Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25973] = {title = "Willkommene Nachrichten", objective = "Kehrt zu Legionär Nazgrim an der Ruhestatt der Legion zurück.", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, <Name>.", progress = nil, completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, &lt;Name&gt;. Ihr habt hier unten Euren Wert mehr als deutlich bewiesen. In der Horde ist ein Ehrenplatz für Euch sicher.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", rewards = "Schulterplatten des wahren LeuchtfeuersHarfenschneckenhandgelenksschützerRoben des wässrigen RettersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25974] = {title = "Tod den Sira'kess", objective = "Tötet 10 Naga der Sira'kess.", description = "Ihr seid also <dieser/diese> <Name>, von <dem/der> alle sprechen? Schön, Euch endlich zu treffen.\n\nNun, genug der Worte. Lasst uns zur Sache kommen. Ihr müsst für mich nach Nordwesten zur Frontlinie der Sira'kess schwimmen und schnell diese Naga erledigen.\n\nNichts Aufregendes. Sie sind auf einen Kampf aus und wir werden ihnen einen bieten. Mit 'wir' meine ich natürlich Euch.", progress = nil, completion = "Sehr gut, &lt;Name&gt;! Das wird diesen Naga zeigen, wer hier die Hosen anhat!\n\nAlso, zu unserem Schlückchen. Was mögt Ihr lieber? Rum oder Wein?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25975] = {title = "Einforderung der Schätze", objective = "Sammelt 6 Stück Tiefenflossenbeute.", description = "Wir haben unsere ersehnte Verstärkung, aber immer noch keine Ahnung, wie wir sie bezahlen sollen. Und diese Art von Hilfe ist nicht ganz billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für unsere Zwecke zurückzustehlen.", progress = "Wie viel Beute konntet Ihr zurückfordern, <Name>?", completion = "Das sollte vorerst reichen. Wir wissen ja, wo es bei Bedarf mehr gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25976] = {title = "Einforderung der Schätze", objective = "Sammelt 6 Stück Tiefenflossenbeute.", description = "Blut und Donner! Wir haben unsere ersehnte Verstärkung, aber wir müssen sie leider auch bezahlen. Das wird sicher nicht billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für die Horde zurückzustehlen.\n\nHöllschreis Augen ruhen auf Euch, <Name>!", progress = "Wie viel Beute konntet Ihr zurückfordern, <Name>?", completion = "Das ist ganz schön viel. Und wir wissen ja, wo es bei Bedarf mehr gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25977] = {title = "Ein standartenmäßiger Tag für Azrajar", objective = "Rammt die Standarte der Allianz in Tiefenrufer Azrajars Leichnam.", description = "<Name>, die Schlangen sind hinter unserer Armee her. Geht nach Nordwesten zum Tiefenflossengrat und steckt dem Futzi, den sie ihren Boss nennen, ein bisschen Holz zwischen die Rippen.\n\nWenn sie das sehen, werden sie Angst bekommen und abhauen mit dem Schwanz zwischen den Bei... ach nee, Beine haben sie ja gar keine.", progress = nil, completion = "Saubere Arbeit! \"O'zapft is der General!\", würde ich mal sagen.\n\n&lt;Der Leutnant schüttelt mit dem Kopf und grinst.&gt;", rewards = "StachelheilerschulterplattenAuf Euch wartet eine dieser Belohnungen:\n\nHalskette der wütenden StandarteFetisch des Azrajar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25978] = {title = "Im Eis eingeschlossen", objective = "Öffnet sechs eisige Gräber, um die gefrorenen Gebirgsjäger am Helmsbettsee zu befreien.", description = "Khurgorn sagt, der Kataklysmus habe das Gleichgewicht der Elemente auf der ganzen Welt erschüttert. Der Helmsbettsee im Süden war einmal wunderschön und ruhig, doch nun wimmelt es dort von wütenden Wasserelementaren. Als sie begannen, den See zu verlassen, schickte ich Truppen dorthin, um sie abzulenken, aber die meisten wurden in Eisblöcken eingefroren.\n\nWenn wir sie befreien können, werden sie sich wahrscheinlich erholen. Ich kann niemanden für eine zweite Expedition zum See entbehren. Würdet Ihr es versuchen?", progress = "Konntet Ihr den Gebirgsjägern helfen?", completion = "Ihr habt es geschafft! Die Gebirgsjäger kehren ins Lager zurück. Unsere Sanitäter werden viel zu tun haben. Wir stehen in Eurer Schuld, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25979] = {title = "Glättet die Wogen", objective = "Tötet 6 Woger des Helmbettsees am Helmbettsee.", description = "Die Elemente sind aufgewühlt, <Klasse>. Der Kataklysmus hat die schlafenden Wassergeister im Helmsbettsee südlich von hier geweckt. Sie sind wütend, verwirrt und nicht gewillt, sich meine Bitten anzuhören.\n\nIch habe alles versucht, um sie zu beruhigen und davon zu überzeugen, die Gebirgsjäger des Unteroffiziers nicht mehr anzugreifen.\n\nIch sage das nur ungern, aber uns bleibt keine andere Wahl -- wir müssen die Elementare töten.", progress = nil, completion = "Es fällt mir nicht leicht, Gewalt gegen die Elemente anzuwenden, deren Macht ich benutze, aber manchmal gibt es keinen anderen Weg. Wir sind zuerst den Bewohnern Dun Moroghs verpflichtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25980] = {title = "Ein standartenmäßiger Tag für Azrajar", objective = "Rammt die Standarte der Horde in Tiefenrufer Azrajars Leichnam.", description = "<Name>, die Naga sind hinter unseren Streitmächten her. Ihr müsst für mich zurück nach Nordwesten zum Tiefenflossengrat gehen und unsere Standarte in ihren General, Tiefenrufer Azrajar stechen.\n\nSie werden vor Angst davon schwimmen, mit dem Schwanz zwischen den… äh. Na ja, Beine haben sie ja wohl nicht, oder?", progress = nil, completion = "Ihr habt ihn also richtig durchbohrt? Das hätte ich ja zu gerne gesehen!", rewards = "StachelheilerschulterplattenAuf Euch wartet eine dieser Belohnungen:\n\nHalskette der wütenden Standarte\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25981] = {title = "Das sind gar keine Masken", objective = "Sammelt 6 Köpfe eines Gnadenlosen.", description = "<Name>, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Auch eine Art, an Sklaven zu kommen.\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen?", progress = "Wie viele habt Ihr?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Stinken nur ganz schön.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25982] = {title = "Das sind gar keine Masken", objective = "Sammelt 6 Köpfe eines Gnadenlosen.", description = "<Name>, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Wir müssen verhindern, dass sie hierher kommen!\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen? Bevorzugt tote Exemplare, schätze ich.", progress = "Was stinkt hier so?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Eigentlich. Irgendwie sind sie fast schon niedlich.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25983] = {title = "Das Kap", objective = "Sprecht mit Kapitän Taylor am Kap in Vashj'ir.", description = "Wir müssen diese Informationen zu Kapitän Taylor am Kap bringen. Er befindet sich im Nordwesten mit Erunak Steinsprecher und den Mitgliedern des Irdenen Rings.", progress = nil, completion = "Das sind verstörende Neuigkeiten, doch ich glaube, dass unsere Freunde vom Irdenen Ring einen Plan haben.\n\nUnd jetzt, da Ihr hier seid...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25984] = {title = "Das Kap", objective = "Sprecht mit Legionär Nazgrim am Kap in Vashj'ir.", description = "<Name>, ich möchte, dass Ihr diese Informationen zu Legionär Nazgrim am Kap bringt. Er befindet sich im Nordwesten mit Erunak Steinsprecher und diesen Leuten vom Irdenen Ring.", progress = nil, completion = "Ich würde meinen Ohren nicht trauen, wenn nicht Ihr der Überbringer dessen wärt, was dieser lästige Goblin zu sagen hat. Das ist in der Tat beunruhigend, aber ich glaube, dass unsere Freunde vom Irdenen Ring einige Ideen haben.\n\nUnd wo Ihr nun hier seid…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25985] = {title = "Schwingen über dem Hyjal", objective = "Findet Choluna am Schrein von Aviana auf dem Hyjal.", description = "<Name>, ist es wahr, dass Ihr versuchen werdet, mit den Ahnen zu sprechen?\n\nSüdwestlich von hier befindet sich der Schrein von Aviana, der Mutter aller fliegenden Lebewesen. Dort lebt meine Lieblingslehrerin, Choluna. Ich habe noch nie jemanden kennengelernt, der so eins mit den Geistern dieser Welt war. Ihr könntet viel von ihr lernen!\n\nWegen der kürzlichen Angriffe ist der Schrein von der Außenwelt abgeschnitten. Aber aus der Luft könnt Ihr ganz einfach dorthin gelangen. Haltet nach dem größten Baum auf dem Hyjal Ausschau. Viel Glück!", progress = nil, completion = "Oh, Tiala schickt Euch? Was für eine herausragende Schülerin. Sie wird noch Großartiges erreichen.\n\nObwohl ich in Euch sogar noch mehr Potenzial spüre.\n\nBitte, bleibt doch eine Weile bei unserem Schrein. Es gibt viel zu tun, aber mit einem beunruhigten Gemüt lässt es sich kaum bewältigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25986] = {title = "Ärger am See", objective = "Sprecht mit Unteroffizier Bahrum an Bahrums Posten.", description = "Ihr wart eine große Hilfe bei der Sicherung der Minen und der Rettung der gefangenen Minenarbeiter.\n\nEs wird den Senat freuen, dass Ihr und Hauptmann Tharrans Gebirgsjäger Fortschritte bei der Sicherung Dun Moroghs gemacht habt.\n\nMich besorgt allerdings, dass ich keine Berichte von Unteroffizier Bahrum und seiner Abteilung erhalten habe. Sie wurden nach Osten geschickt, auf die Straße, die zum Helmsbettsee führt. Dort sollten sie einen kleinen Außenposten errichten. Würdet Ihr zu Bahrums Posten reisen und nach dem Unteroffizier sehen?", progress = nil, completion = "Gut, dass der Senator nicht allein hierhergekommen ist. Es ist gefährlich hier. Wir werden all die Hilfe brauchen, die wir kriegen können, um die Lage unter Kontrolle zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25987] = {title = "Setzt es auf", objective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", description = "He, <Name>! Ich habe eine tolle Idee für eine Verkleidung. Nehmt einen dieser gnadenlosen Wasauchimmers und setzt ihn Euch auf den Kopf.\n\nWas kann dabei schon schiefgehen?\n\nSeid Ihr bereit, ihn aufzusetzen?", progress = nil, completion = "Was ist passiert? Das Ding war wohl nicht ganz tot! Vielleicht sollte ich einfach bei den mechanischen Dingen bleiben.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will sie keinesfalls in meiner Nähe haben.", rewards = "RippströmungsbeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nAbgeschnittenes VisionententakelSchnabel des Gnadenlosen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25988] = {title = "Setzt es auf", objective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", description = "Ich habe eine tolle Idee für eine Verkleidung, aber ich brauche Eure Hilfe dabei, <Name>. Nehmt einen dieser gnadenlosen Leichname und setzt ihn Euch auf den Kopf.\n\nIch weiß, ich weiß, aber es ist tot. Was kann dabei schon schiefgehen, außer dass Ihr ein, zwei Tage übel riecht?\n\nSeid Ihr bereit, ihn aufzusetzen?", progress = nil, completion = "Mein Fehler. Ich heiße nicht umsonst \"Fiasco\". Ich hätte wissen sollen, dass es nicht ganz tot ist, als es gezuckt hat.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will nicht, dass sie hier alles vollstinken.", rewards = "RippströmungsbeinschützerAuf Euch wartet eine dieser Belohnungen:\n\nAbgeschnittenes Visionententakel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25989] = {title = "Fang den Krebs", objective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "&lt;Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.&gt;\n\nEr sieht nicht besonders beeindruckend aus, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25990] = {title = "Durchbruch", objective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", progress = nil, completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25991] = {title = "Wir sind nicht allein", objective = "Findet die Überlebenden der Horde in Nespirah in Vashj'ir.", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Hordesklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, <Name>. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", progress = nil, completion = "&lt;Name&gt;… Seid Ihr das?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25992] = {title = "Hoffnungslos ausrüstungslos", objective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Piekse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "&lt;Hauptmann Übeldorn bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.&gt;\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, &lt;Name&gt;. Wir werden sie sinnvoll einsetzen.", rewards = "Sandgeschliffener BeschützerSchnabellose StangenwaffeAuf Euch wartet eine dieser Belohnungen:\n\nSchwärzlicher Perlenring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][25993] = {title = "Voller Körpereinsatz", objective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", description = "<Legionär Nazgrim lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht findet Euer Schwert ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", progress = nil, completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25994] = {title = "Immer noch wertvoll", objective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n&lt;Tulra verstaut die Perlen unter ihrer Rüstung.&gt;\n\nUnd jetzt müssen Legionär Nazgrim und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25995] = {title = "Aufseher Idra'kess", objective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", description = "Meine Männer lassen nach, <Name>. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Nordosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten. Höllschreis Augen ruhen auf Euch!", progress = nil, completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Legionär Nazgrim hat mir den Rest berichtet.\n\n&lt;Duarn schließt die Augen und nickt.&gt;\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", rewards = "Helm des zermalmten AufsehersGorgonischer GürtelSägefischgurt des ErdheilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25996] = {title = "Die Erweckung der Bestie", objective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", description = "Dank Euch und dem Legionär hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", progress = nil, completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Höllschrei sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25997] = {title = "Die Heimtücke der Dunkeleisenzwerge", objective = "Tötet 5 Spione der Dunkeleisenzwerge und erbeutet die Angriffspläne der Dunkeleisenzwerge von Hauptmann Beld in Eisenbands Truppenlager.", description = "Eine Gruppe Dunkeleisenspione hat Eisenbands Truppenlager im Süden, hinter dem Helmsbettsee übernommen. Die Gebirgsjäger wären normalerweise in der Lage, sie aus Dun Morogh herauszuhalten, aber es herrscht gerade Chaos.\n\nDie Dunkeleisenzwerge wären Narren, wenn sie das nicht zu ihrem Vorteil nutzen würden. Wir müssen herausfinden, was sie planen und sie aufhalten, bevor sie Schaden anrichten.\n\nKönntet Ihr versuchen herauszufinden, was sie in Eisenbands Truppenlager machen?", progress = "Was haben die Dunkeleisenzwerge vor?", completion = "Ich habe mir schon gedacht, dass sie nicht wegen der Aussicht hier sind.\n\n&lt;Der Unteroffizier betrachtet die Pläne, die Ihr erbeutet habt. Seine Augen weiten sich.&gt;\n\nDas ist ernster als befürchtet! Dies ist nicht nur ein Überfall. Die Dunkeleisenzwerge wollen die Verteidigungsbollwerke von Eisenschmiede lahmlegen!", rewards = "Gürtel der dunklen AbsichtenArmschiene des DunkeleisenspitzelsDunkeleisennagelstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][25998] = {title = "Auf zum Flugplatz", objective = "Steigt in Mathels Flugmaschine im Steinbruch Gol'Bolar.", description = "Laut der Pläne, die Ihr erbeutet habt, planen die Dunkeleisenzwerge einen großangelegten Angriff auf den Flugplatz von Eisenschmiede! Der Rat hat einen Großteil unserer Streitkräfte nach Dun Morogh verlegt. Sie sollen sich dort um die Instabilität, die durch den Kataklysmus entstanden ist, kümmern. Die Verteidigungslinien des Flugplatzes sind geschwächt.\n\nWir müssen Euch so schnell wie möglich zum Flugplatz bringen. Nehmt die Straße zurück nach Westen, in Richtung des Steinbruchs Gol'Bolar und findet Mathel Rostzange. Er sollte eine Flugmaschine für Euch haben. Geht!", progress = nil, completion = "Zum Glück seid Ihr hier, &lt;Name&gt;. Der Flugplatz wird von Dunkeleisenzwergen angegriffen. Wir halten nicht mehr lange durch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][25999] = {title = "Schritt für Schritt", objective = "Macht 8 Krom'gar \"Elfentöter\" scharf.", description = "Den schmutzigen, nichtsnutzigen Nachtelfen ist es gelungen, unser ganzes Minenfeld auf dem Steinkrallenpass zu entschärfen. Jemand muss dorthin zurückgehen und die Minen wieder scharf machen! Diese Aufgabe ist perfekt für einen wertlosen Grunzer wie Euch geeignet, <Name>. Hoffentlich jagt Ihr Euch dabei nicht selbst in die Luft.\n\nUnsere \"Elfentöter\" liegen überall auf dem Steinkrallenpass, unmittelbar nördlich von hier. Nehmt diesen Schraubenschlüssel und macht Euch an die Arbeit, Made.", progress = "Was habt Ihr zu melden, Grunzer?", completion = "&lt;Saurboz mustert Euch.&gt;\n\nIhr habt noch alle Gliedmaßen. Das gab's noch nie.", rewards = "Saurboz' GamaschenStulpen des VerbrennersElfenmörderbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26000] = {title = "Höhlenforscher", objective = "Sprecht mit Gurrok in der Tiefennebelgrotte.", description = "Schnell, <Name>!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", progress = nil, completion = "Ein… ein &lt;Volk&gt;? Hier?\n\nIch muss wahnsinnig sein…", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSpelunking Completion - HORDE\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26001] = {title = "Der vermisste Sprengenieur", objective = "Findet Sprengenieur Fusselpfiff.", description = "Ihr seid wohl doch nicht völlig nutzlos. Vielleicht bewältigt Ihr sogar eine etwas wichtigere Aufgabe.\n\nVor rund zwei Tagen habe ich Sprengenieur Fusselpfiff zur Scherwindmine geschickt. Er sollte sich dort davon überzeugen, dass alles mit der Bombe nach Plan läuft und sich dann wieder hier melden. Zwei Tage und nichts...\n\nBegebt Euch in den Wald südlich von hier und findet ihn. Wenn er Glück hat, ist er tot.", progress = nil, completion = "Sprengenieur Fusselpfiff ist definitiv tot. Ist vielleicht besser so.\n\nEr scheint eine Notiz in der Hand zu halten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26002] = {title = "Angriffspläne der Allianz", objective = "Erbeutet die Angriffspläne der Allianz von Jägerin Davinia.", description = "<Ihr zieht die Notiz aus Fusselpfiffs toten Fingern.>\n\nSie wissen Bescheid! Sie wissen von der Bombe. Planen Angriff auf Feste Krom'gar! Ich glaube, sie suchen mich. Werde nicht sterben wie ein Feigling. Ich werde kämpfen.\n\nIch glaube, da kommen sie! Ihre Anführerin ist eine Hochelfenjägerin namens Davinia. Sie sprach von den Angriffsplänen. Rächt mich, indem Ihr sie tötet und Euch die Pläne holt! Ihr Zelt steht östlich von hier, ganz in der Nähe.\n\nMöge Höllschrei über Euch wachen...", progress = "Habt Ihr Fusselpfiff gefunden?", completion = "Verdammt schade... Er war ein guter Goblin.\n\n&lt;Saurboz schüttelt seine Faust.&gt;\n\n&lt;Name&gt;, Ihr habt richtig gehandelt. Dank dieser Angriffspläne können wir uns vorbereiten. Ich möchte, dass Ihr die Pläne Oberanführer Krom'gar persönlich übergebt! Es sollte eine Beförderung für Euch drin sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26003] = {title = "Lehren von den Verlorenen Inseln", objective = "Tötet 12 Späher von Darnassus.", description = "In den Wäldern südlich von hier lauern große Gefahren. Sie wimmeln von darnassischen Spähern - Assassinen, die aus Darnassus geschickt wurden, um uns zu töten. Vielleicht können wir den Spieß umdrehen.\n\nAls ich auf den Verlorenen Inseln festsaß, gab mir ein Goblin diese Infrarot-Hitzebrille. Mit ihr kann der Träger die Wärmesignatur bestimmter Kreaturen sehen. Nehmt die Brille und setzt sie in den Wäldern im Süden auf. Auf diese Weise werdet Ihr die Späher leicht entdecken können. Tötet so viele Ihr könnt! Für die Horde!", progress = nil, completion = "Gut gemacht, Bruder! Jetzt wissen sie, dass sie sich nicht an die Horde anschleichen können!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nClear Infrared Heat Focals\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26004] = {title = "Feste Krom'gar", objective = "Bringt die Angriffspläne der Allianz zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", description = "Feste Krom'gar ist unsere Hauptoperationsbasis im Steinkrallengebirge. Von hier aus überwacht Oberanführer Krom'gar die militärischen Aktionen der Horde in dieser Region. Krom'gar leitet die Berichte aller Ereignisse direkt an den Kriegshäuptling weiter.\n\nDie Angriffspläne, die Ihr uns gebracht habt, beschreiben einen Angriff, der bald gegen die Feste Krom'gar geführt werden soll. Nehmt die Pläne und brecht zur Feste südwestlich von hier auf. Gebt sie dem Oberanführer.\n\nLebt wohl, <Name>. Höllschrei wacht wahrlich über Euch.", progress = "Was hat diese Unterbrechung zu bedeuten? Wieso steht dieser Grunzer vor Oberanführer Krom'gar?", completion = "&lt;Ihr gebt Oberanführer Krom'gar die Pläne.&gt;\n\nHmm. Vielleicht steckt mehr in Euch, als es den Anschein hat. Vielleicht steckt in Euch ein Unteroffizier.\n\nRichtet Euren Blick auf Krom'gar Unteroffizier &lt;Name&gt;, Soldaten. Er hat uns vor einem feigen Angriff der Allianz gewarnt. Einen Angriff, den wir NIEDERWERFEN werden!", rewards = "Ihr erlernt:\n\nUnteroffizier von Krom'gar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26005] = {title = "Ein Hauch frischer Luft", objective = "Findet Kapitän Taylor auf der Voldrins Mut an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand: \n", description = "Kapitän Taylor und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nHexasept hat die hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", progress = nil, completion = "Ihr habt es geschafft! Schön Euch zu sehen, &lt;Name&gt;.\n\nEs ist ein tolles Gefühl, dem Wasser entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Ich bin mir sicher, dass viele der Jungs nach all den Strapazen alles geben würden, um umzudrehen und nach Hause fahren zu können. Aber wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Haltet Ihr bis zum Ende durch? Ich würde es Euch nicht übel nehmen, wenn Ihr die Nase voll hättet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26006] = {title = "Ein Hauch frischer Luft", objective = "Findet Legionär Nazgrim auf der Höllenjuwel an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand: \n", description = "Legionär Nazgrim und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nFiasco hat das hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", progress = nil, completion = "Ihr habt es also in einem Stück geschafft, &lt;Klasse&gt;.\n\nEs ist ein tolles Gefühl, diesem stinkenden Pfuhl entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Macht es Euch aber nicht zu bequem. Wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Hattet Ihr genug Ruhm für einen Tag oder stürzt Ihr Euch wieder in den Kampf, um Höllschrei Stolz zu machen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26007] = {title = "Befragung", objective = "Sprecht mit Gurrok und erfahrt etwas über seine Tortur.", description = "Dieser Krieger stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", progress = nil, completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26008] = {title = "Druckabbau", objective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Kriegern in der Umklammerung.", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Krieger inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, <Name>. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", progress = nil, completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", rewards = "PteropodenrobenKegelschneckensattelgurtAtemsteinerfüllter LangbogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26009] = {title = "Suchen und zerstören", objective = "Tötet 20 beliebige Soldaten der Allianz im Steinkrallengebirge.", description = "Die Allianz rückt auf unsere Territorien im Steinkrallengebirge vor. Die Streitkräfte von Nordwacht haben unsere Blockade im Süden durchbrochen und besetzen nun das Scherwindtal westlich von hier. Im Norden werden wir von Nachtelfensoldaten angegriffen. All das muss aufhören!\n\nBegebt Euch ins Steinkrallengebirge und vernichtet alle Allianzsoldaten, die Euren Weg kreuzen. Ihr Tod soll als Warnung dienen.\n\nDas Steinkrallengebirge gehört der Horde!", progress = nil, completion = "Es wird noch viel Blut in dieser Erde versickern, bis der Krieg vorüber ist. Blut der Allianz...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26010] = {title = "Asche zu Asche", objective = "Zerstört 8 Zelte der Nordwacht mit Krom'gars Flammenwerfer.", description = "Die Allianz wird immer unverschämter. Westlich von hier, im Scherwindtal, haben Truppen der Nordwacht ein Lager aufgeschlagen. Zweifellos bereiten sie sich auf den Angriff vor, den Ihr uns gemeldet habt, <Name>. Soweit wird es nicht kommen!\n\nNehmt diesen Flammenwerfer. Den gleichen Flammenwerfer setzten meine Verbrenner ein, um unsere Feinde aus den Wäldern zu jagen. Zerstört damit die Zelte der Nordwacht. Lasst nur Asche zurück!", progress = nil, completion = "Lok'tar! Allianzschweine!\n\n&lt;Oberanführer Krom'gar spuckt auf den Boden.&gt;\n\nGenießt Euren Sieg, er wird nicht lange währen. Euer Mut hat uns Zeit verschafft, aber mehr nicht.", rewards = "Weste der AscheHandschuhe des FlammenwerfersAuf Euch wartet eine dieser Belohnungen:\n\nGunst des Oberanführers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26011] = {title = "Feind der Horde: Marschall Paltrow", objective = "Tötet Marschall Paltrow.", description = "Meine Späher haben die Ursache dieses neuesten Fiaskos gefunden: Marschall Paltrow. Er kommandiert das Vorauslager der Nordwacht im Scherwindtal westlich von hier. Eliminiert ihn. Damit entfernt Ihr einen wichtigen Feldkommandanten der Allianz aus der Gleichung.\n\nPaltrow muss sterben, <Name>.", progress = nil, completion = "Habt Ihr verdächtige Dokumente in Paltrows Lager gefunden? Vielleicht an seiner verwesenden Leiche? Jeder Hinweis auf die Angriffsmuster der Allianz wären bei der Schlacht ums Steinkrallengebirge von Vorteil.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26012] = {title = "Ärger im Wyrmruhtempel", objective = "Sprecht mit Krasus im Wyrmruhtempel in der Drachenöde.", description = "Mein alter Freund Krasus berichtet von grässlichen Vorkommnissen im Wyrmruhtempel in der Drachenöde. Sein Schreiben war kurz, doch es scheint, dass eine Art Angriff auf das Rubinsanktum unterhalb des Tempels stattgefunden hat.\n\nDringende Angelegenheiten hier in Dalaran halten mich davon ab, mich persönlich um die Sache zu kümmern, doch sind mir Berichte Eurer Heldentaten in der Zitadelle des Lichkönigs zu Ohren gekommen und Ihr seid zweifellos dieser Aufgabe gewachsen - vielleicht könntet Ihr an meiner statt Krasus behilflich sein?", progress = nil, completion = "Ich danke Euch, dass Ihr Rhonins Bitte gefolgt seid, tapferer Abenteurer.\n\nLasst mich Euch mitteilen, was uns über die jüngsten Geschehnisse bekannt ist. Jede Hilfe, die Ihr zu gewähren bereit seid, wird sehr geschätzt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26013] = {title = "Angriff auf das Sanktum", objective = "Untersucht das Rubinsanktum unterhalb des Wyrmruhtempels.", description = "<Volk>, etwas Schreckliches ist im Rubinsanktum unterhalb des Tempels geschehen.\n\nDer Eingang zum Sanktum liegt in Ruinen und seine Wächter sind auf grausame Art und Weise erschlagen worden. Wir haben Kundschafter ausgesandt, um der Sache auf den Grund zu gehen, aber sie sind nicht zurückgekommen. Nun befürchte ich das Schlimmste.\n\nBetretet das Rubinsanktum und bringt in Erfahrung, was in der Heimat meines Schwarmes passiert ist. Sobald wir mehr Informationen haben, können wir unsere nächsten Schritte entsprechend planen.", progress = nil, completion = "Habt Dank, &lt;Klasse&gt;, dafür, dass Ihr mich aus Baltharus' Klauen gerettet habt!\n\nAllerdings gibt es noch immer sehr viel zu tun...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26014] = {title = "Die Gebrüder Grabungslied", objective = "Meldet Euch bei Humphrey Grabungslied in der Tiefenlichtkluft in Vashj'ir.", description = "Stillgestanden, <Gefreiter/Gefreite> <Name>! Wir chaben kleine Problem!\n\nWir chaben geschickt Humphrey und Oskar Grabungslied zur Tiefenlichtkluft im Njordwesten, aber sie sind nicht zurückgekommen. Sie sollten ausspähen Umgebung, aber wir chaben verloren jeden Kontakt zu ihnen.\n\nEure Aufgabe, <Gefreiter/Gefreite> <Name>, ist zu finden unsere Genossen und, falls sie noch ljeben, sie zu mir zurückzubringen!", progress = nil, completion = "Natürlich sind wir noch nicht zurück! Wir haben ganz schön viele Rückschläge einstecken müssen… nicht zuletzt das Ableben meines geliebten Bruders Oskar.\n\n&lt;Humphrey schnieft laut.&gt;\n\nEr hat den Halt verloren und ist einfach davongetrieben, der Arme! Er wollte ein paar Fische für den Kapitän fangen, stattdessen wurde er weggespült und von einem dieser... dieser riesigen Aale gefressen! Uääääh hä hä häh hääääh!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26015] = {title = "Phosphorajagd", objective = "Besorgt Euch 6 Tiefenlichtphosphora von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", description = "Oskars letzter Wunsch, bevor er im Rachen dieses Großaals verschwand, war, dem Käpt'n Nahrung zu bringen. Also werden wir ihm diesen Wunsch erfüllen.\n\nMein Bruder hatte einen genialen Plan. Er hat beobachtet, wie diese Murlocs mit phosphoreszierenden Antennen Fische aus dem Schilf locken. Daraufhin hat er einen Weg gefunden, ein eigenes Gerät zu bauen. Ihr braucht nur etwas, das leuchtet.\n\nTötet die Krebse und Barsche am Grund der Kluft. Sie selbst sind nicht essbar, aber ihr Phosphora ist weitaus wertvoller als ihr Fleisch.", progress = "Wir brauchen genug Phosphora, um ein starkes Licht zu erschaffen. Ihr müsst heller leuchten, als diese Murlocs!", completion = "&lt;Humphrey nimmt Euch das Phosphora ab und bringt es an einem ungewöhnlichen Gerät an.&gt;\n\nSo. Wunderschön! Oskar wäre sehr stolz darauf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26016] = {title = "Befehle aus dem Basislager", objective = "Bringt die Befehle des Stützpunkts zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", description = "Paltrow, errichtet einen Stützpunkt im Scherwindtal. Ein starker Bodenangriff ist lebenswichtig für unseren Feldzug! Wenn wir Krom'gar angreifen, werden Eure Männer für das Chaos und die Verwirrung sorgen, die unsere Gnomflugmaschinen brauchen, um nahe genug für einen Bombenangriff an die Orcfestung zu kommen.\n\nDie Flugmaschinen werden die Bombe von Krom'gar zünden, während sie noch in ihrer Basis steht und damit die gesamte Festung auslöschen.\n\nNach dem Lesen verbrennen.\n\n-Truppenkommandant Valen\n\nBasislager der Nordwachtexpedition", progress = "Mehr Gnome?", completion = "Gnomflugmaschinen? Unsere Luftabwehrkanonen funktionieren noch nicht! Wir werden hilflos sein.\n\nIch brauche Zeit für einen Plan... muss nachdenken...\n\nDer Heißluftballon darf mit seiner Ladung nicht in der Feste Krom'gar bleiben. Ich muss ihn an einen anderen Ort bringen. Unsere Pläne zur Vernichtung der Scherwindfeste sind gescheitert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26017] = {title = "Ein Köder", objective = "Setzt die Phosphorafedora auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", description = "Bringt dieses Gerät an Eurem Kopf an und schwimmt dann durch den Tang und die Korallen am Rand der Kluft. Es sollte dort haufenweise kleine Fische geben, die Eure neue Antenne ganz unwiderstehlich finden werden.\n\nWenn wir zur Dämmerbucht zurückkehren, werden wir Berge von Fischen für alle haben!", progress = "Wie viele habt Ihr gefangen?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;! Das habt Ihr richtig gut gemacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26018] = {title = "Licht aus für die Tiefenlichter", objective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", description = "Ach, stimmt! Ich sollte ja einen Bericht erstellen! Fast hätte ich es vergessen!\n\nSieht eigentlich nach größtenteils harmlosen Wildtieren aus hier… Bis auf diese verdammten Aale. Und ein paar Murlocs. Ich schätze, der Käpt'n wird sich wohl eher für die Murlocs interessieren.\n\nFordert ein paar von ihnen zum Kampf raus und schaut, was sie so drauf haben. Soweit ich weiß jagen die großen im Tang nach Fischen und die kleinen praktizieren irgendeine Art von Magie oder so... aber mehr weiß ich auch nicht.", progress = nil, completion = "&lt;Humphrey hört Euch zu, während Ihr von Euren Kämpfen mit den Tiefenlichtmurlocs berichtet.&gt;\n\nHmm… Klingt nach stinknormalen Murlocs… nur unter Wasser. Das macht den Käpt'n bestimmt froh.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26019] = {title = "Enormes Aalei", objective = "Bringt das enorme Aalei zu Humphrey Grabungslied am Grund der Tiefenlichtkluft in Vashj'ir.", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Humphrey vielleicht daran interessiert sein könnte.>", progress = "Was habt Ihr denn da, <Name>?", completion = "Waaa… ein Ei? Ein AALEI?\n\n&lt;Sogar kopfüber könnt Ihr sehen, wie es in Humphreys Kopf rattert.&gt;\n\nWir können ganz sicher etwas damit anfangen! Macht Euch bereit, denn jetzt ist es Zeit für ein wenig altmodische Rache à la Grabungslied!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26020] = {title = "Meldet Euch bei Bombgutz", objective = "Meldet Euch bei Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", description = "Wir müssen uns auf den bevorstehenden Angriff vorbereiten. Unsere Soldaten sollen die Bombe für den Transport bereitmachen. Ihr meldet Euch bei Obersprengenieurin Bombgutz. Sie versucht, unsere Luftabwehrkanonen zu reparieren, bislang jedoch erfolglos. Stellt sicher, dass ihre Motivation für die Reparatur der Kanonen ausreicht, <Name>.", progress = nil, completion = "Ausreichend motiviert? Was... was soll das heißen? Hört mal zu, Unteroffizier, ich habe einen eingebauten Überlebensmechanismus namens Eigeninteresse. Das heißt, es ist in meinem eigenen Interesse, NICHT ZU STERBEN. Allerdings kann ich die Kanonen nicht ohne die richtigen Materialien reparieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26021] = {title = "Die Gebrüder Grabungslied Teil 2: Der Eier-Aal-Trick-Blues", objective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", description = "Diese Aale haben meinen Bruder gefressen. Meinen Bruder, <Name>! Es ist Zeit, dass ihnen jemand zeigt, wer hier der Boss ist.\n\n<Humphrey nimmt mehrere Dynamitstangen aus seiner Weste und schiebt sie durch die Außenhaut des Eis.>\n\nDiese Großaale im Süden sind zu stark, um alleine gegen sie anzutreten, aber mit diesem Ei sollten wir für Chancengleichheit sorgen können. Legt es in der Nähe dieser Biester ab und dann... Kabumm!\n\nWenn die Bombe den Aal nicht sofort tötet, sollte er zumindest dem Tod nahe sein, sodass Ihr ihm leicht ein Ende setzen könnt.", progress = nil, completion = "Oskar ist am Leben? Wartet... Was habt Ihr gesagt? Ihr habt zugelassen, dass er ERNEUT DAVONGETRIEBEN WIRD?!\n\nNun… Ihr habt Euren Teil der Vereinbarung erfüllt und ich weiß zu schätzen, was Ihr getan habt, &lt;Name&gt;.\n\nHier… nehmt das. Für mich ist es ohnehin nur Ballast, aber es scheint nicht viel zu nützen.", rewards = "Explosiv dekomprimierte StampferSchulterpolster der anguilliformen AusrottungAalschneiderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26022] = {title = "Das erste Blut", objective = "Erbeutet 10 Blutsteinamulette von Mitgliedern des Syndikats.", description = "Seid bereit, <Name>. Ihr werdet für uns das erste Blut auf diesem Land vergießen.\n\nDas Syndikat, so nennen sie sich, besteht aus feigen Menschen, die sogar ihr eigenes Volk verraten. Ihre Isolation macht sie zu einer leichten Beute.\n\nReist nach Norden, tötet alle Syndikatssöldner, die Ihr findet und erobert Nordhof im Namen der Verlassenen. Bringt mir die Blutsteinamulette, die sie tragen, als Zeichen Eurer Eroberung.", progress = "Ich lasse mich nicht von leeren Behauptungen beeindrucken. Könnt Ihr Eure Loyalität beweisen?", completion = "Das ist nur der Auftakt für das Massaker, das wir über dieses Land bringen werden. Alle werden Euren Namen kennen.\n\nDas habt Ihr gut gemacht, &lt;Name&gt;. Sieg für Sylvanas!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26023] = {title = "Der Trollbann der Verlassenen", objective = "Sprecht mit Galen Trollbann.", description = "Ich werde Euch eine Geschichte erzählen.\n\nEs gab einmal einen einfältigen Troll namens Zengu. Man befahl ihm, das Schwert Trol'kalar zu finden, die legendäre Klinge der menschlichen Trollbannlinie. Das gelang ihm. Er dachte, seine Aufgabe sei erfüllt und wollte Arathi allein verlassen. Dabei wurde er von den Menschen getötet, die das Schwert einfach wieder an sich nahmen.\n\nWir werden nicht so einfältig sein. Unsere Apotheker haben uns jemanden gebracht, der uns helfen wird, Trol'kalar wiederzubeschaffen: den Prinzen, der es einst besaß.\n\nEr wartet darauf, Euch zu führen, <Name>. Sprecht mit ihm.", progress = nil, completion = "Ja... Einst war ich Prinz des gefallenen Königreichs Stromgarde. Ich wurde getötet von dem, der Trol'kalar suchte.\n\nNun bereue ich mein dummes Leben. Ich diene...nur Sylvanas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26024] = {title = "GESUCHT: Marez Schattenkutte", objective = "Bringt Marez' Kopf zu Hauptmann Nials bei der Zuflucht.", description = "Es wurde ein Kopfgeld auf Marez Schattenkutte ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Hauptmann Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie mit Dämonen Umgang hat. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", progress = "Seid gegrüßt, <Klasse>. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Schattenkutte erledigt? Gut gemacht, &lt;Name&gt;. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann.", rewards = "Dolch des SyndikatsSchallgedämpftes GewehrGürtel des DämonenhändlersWeste der finsteren GerüchteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26025] = {title = "Der verräterische Orc", objective = "Erbeutet Marez Schattenkuttes beschmutzte Blutsteinkugel.", description = "Ich bin mir sicher, dass eine mächtige Hexenmeisterin in den Mauern von Burg Stromgarde haust. Von Zeit zu Zeit beschwört diese Hexenmeisterin mit Hilfe eines arkanen magischen Relikts schreckliche Dämonen in großer Anzahl. Wir müssen die Quelle ihrer Energie entfernen.\n\nFindet und tötet die Hexenmeisterin. Bringt mir das magische Objekt, das sie bei sich trägt. Dann werde ich dafür sorgen, dass es zerstört wird und dass ihre Macht nie wieder unser Land besudelt.", progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Die Hexenmeisterin muss aufgehalten werden.", completion = "Meine ruhelosen Nächte werden sich in friedlichen Schlaf verwandeln, wenn ich diese Kugel zerstört habe. Danke, &lt;Name&gt;. Sie dient als düstere Erinnerung an die schreckliche Macht, die Dämonen über die Orcs ausübten, bevor Höllschrei sie von ihrem Fluch befreite.", rewards = "Blutsteinbesetzter UmhangDrachenhautgamaschenStrahlende SilberarmschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26026] = {title = "Traum von einer besseren Zukunft", objective = "Bergt die BD-816 Kriegsmaschine, das mechanisierte Feuer, das mechanisierte Eis und die mechanisierte Luft.", description = "Herr Rosie ist krank, <ehrenwerter/ehrenwerte:r> <Volk>. Könnt Ihr ihm helfen? Ihr müsst nur seinen Hut und seine Batterien finden, dann wird es ihm wieder gut gehen. Ich würde sie selbst holen, aber ich kann Herrn Rosie nicht allein lassen!\n\nDie gemeinen Kerle der Venture Company, hinten am Wasserrad, haben seinen Hut gestohlen und seine Batterien sind irgendwo an der Scherwindklippe versteckt. Ihr werdet richtig gut nach ihnen suchen müssen!\n\nWürdet Ihr bitte Herrn Rosies Besitz zurückbringen, damit er den Fieslingen von der Allianz eine Lektion erteilen kann?", progress = "Herr Rosie ist so traurig. Wir müssen ihn wieder fröhlich machen!", completion = "&lt;Clarissa klatscht aufgeregt.&gt;\n\nHerr Rosie, dir geht es gleich wieder gut! Hurra!\n\n&lt;Clarissa setzt die Teile, die Ihr gefunden habt, routiniert in \"Rosie\" ein.&gt;\n\nOh, Herr Rosie! Ich wusste es!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26027] = {title = "Zu den Waffen", objective = "Tötet 7 Schamanen der Felsfäuste und 3 Lords der Felsfäuste in Stromgarde.", description = "Unser nächster Schlag gegen die Oger wird Euch tiefer in den Osten nach Burg Stromgarde führen. Die Lebenden klammern sich weiter an diese verfallenen Ruinen. Ihre Sentimentalität ist widerwärtig!\n\nFür uns ist Burg Stromgarde nicht mehr als ein verdorbener Bau voller Oger, die auf ihr Ende warten. Reist dorthin. Tötet ihre Schamanen und ihre Lords und sorgt dafür, dass das, was bei den Ogern als Führung durchgeht, vernichtet wird.", progress = nil, completion = "Alles gesäubert? Gut. Wir werden uns nicht die Mühe machen, Burg Stromgarde zu besetzen. Dieses Drecksloch muss in Staub verwandelt werden.\n\nDas Land würde sich gut für eine neue Unterstadt eignen.", rewards = "Marode ArmschienenBonuspunktstiefelLauernder GürtelGürtel der ausgebrannten RuinenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26028] = {title = "Herr Rosies wilder Ritt", objective = "Tötet 20 Gnomingenieure und 5 Gnomklopfer.", description = "Herr Rosie braucht jetzt einen Engel, der ihm bei der Navigation hilft. Werdet Ihr dieser Engel sein, <ehrenwerter/ehrenwerte:r> <Volk>? Mit Eurer Hilfe können wir es bis zur Klippe schaffen und viele, viele Allianzkämpfer töten. Was meint Ihr? Och bitte, <edler/edle:c> <Klasse>! BITTE BITTE BITTE BITTE?\n\nWenn wir genügend Allianzler umbringen, kauft Herr Krom'gar uns allen ein Eis!", progress = nil, completion = "&lt;Oberanführer Krom'gar hustet.&gt;\n\nIch weiß - vielleicht zum ersten Mal in meinem Leben - nicht, was ich sagen soll.\n\nIch bin mir nicht einmal sicher, wo Clarissa eigentlich her kommt...", rewards = "Ihr bekommt:\n\nMövenhacks schockierend deliziöse Eiscreme"}
MultiLanguageQuestData['de'][26029] = {title = "Die echte Bedrohung", objective = "Tötet Or'Kalar und nehmt seinen Kopf.", description = "Or'Kalar führt die Oger hier an. Seit Jahren entgeht er seinen Schlächtern. Seine Existenz ist eine Beleidigung der Dunklen Fürstin. Mug'thol, Verräter der Verlassenen, kommandiert ihn aus der Ferne!\n\nWir tolerieren weder Oger noch Verräter im Gebiet der Verlassenen. Bringt mir den Kopf des Ogers. Dann sorge ich dafür, dass er dieses Mal richtig verbrannt wird.", progress = "Fasst Euch kurz.", completion = "Dieses Schicksal blüht allen, die uns im Weg sind.", rewards = "SchädelschlitzerLautlose JägerinGürtel des AffrontsNebelhauchwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26030] = {title = "Siegelzeichen von Strom", objective = "Erhaltet das Siegelzeichen von Strom von den Mitgliedern des Syndikats in Burg Stromgarde.", description = "In grauer Vorzeit führte Lord Ignaeus von Strom, den sie Trollbann nannten, die erste menschliche Zivilisation von Arathor in den Krieg gegen die Trolle. Seine Klinge hieß Trol'kalar – was in ihrer alten Sprache Trolltöter heißt.\n\nIch war einer der letzten seines Geblüts und hatte die Aufgabe, Trol'kalar zu hüten... eine Aufgabe, bei der ich versagt habe. Aber jetzt werden wir die Klinge für meinen neuen Meister erneut in unseren Besitz bringen.\n\nDas Schwert wird von drei Siegelzeichen beschützt. Der erste befindet sich in den Händen der Verräter des Syndikats, die in den Ruinen von Stromgarde herumlungern. Tötet sie und bringt das Siegelzeichen zu mir.", progress = "Nur die Mitglieder des Syndikats innerhalb Stormgardes werden das Siegelzeichen bei sich haben. Außerhalb der Festung Blut zu vergießen ist Zeitverschwendung.", completion = "Ich habe das Syndikat zu Lebzeiten genauso sehr gehasst, wie ich sie im Tode hasse. Das Siegelzeichen wiederzusehen ist ein kleiner Trost.\n\nAber wir haben noch viel mehr Arbeit vor uns... für Sylvanas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26031] = {title = "Siegelzeichen des Thoradin", objective = "Erbeutet 5 Siegelzeichenfragmente von Vollstreckern von Stromgarde in Burg Stromgarde.", description = "Als ich noch lebte, zerbrach ich das Siegelzeichen des Thoradin in fünf Teile, um es zu schützen. Ich gab sie meinen loyalsten Männern. Das schlug ebenfalls fehl, aber mein Nachfolger wird dasselbe getan haben.\n\nDie Verteidiger von Burg Stromgarde tragen die Teile des Siegelzeichens wieder bei sich. Tötet sie und bringt mir die Scherben; ich werde sie zusammensetzen.", progress = "Nur mit allen fünf Teilen kann das Siegelzeichen wiederhergestellt werden...", completion = "Thoradin war der Gründer von Arathor. Ich vereine diese Fragmente, so wie er einst die verstreuten Stämme der Menschen vereinte und ihre erste große Nation erschuf.\n\nDoch dieses Gefasel interessiert Euch sicherlich nicht. Vergebt mir. Alte Erinnerungen lassen sich nur schwer begraben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26032] = {title = "Siegelzeichen von Arathor", objective = "Nehmt Leutnant Heldenruf das Siegelzeichen von Arathor ab.", description = "Ich habe dieses Siegelzeichen Leutnant Heldenruf, dem Anführer meiner Kavallerie, anvertraut. Er hätte beinahe sein Leben verloren, als es gestohlen wurde.\n\nDieses Mal wird er wohl weniger Glück haben. Heldenruf patrouilliert zwischen Burg Stromgarde und der Zuflucht. Findet ihn und nehmt ihm noch einmal das Siegelzeichen ab.", progress = "Habt Ihr das Siegelzeichen?", completion = "Heldenruf war mir im Leben treu ergeben. Seinen Tod ertrage ich nur schwer.\n\nDoch das muss ich. Ich bin ein Verlassener. Meine alte Existenz hat keine Bedeutung.\n\nWir haben die Siegelzeichen; Trol'kalar erwartet uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26033] = {title = "Trol'kalar", objective = "Bergt Trol'kalar aus Trollbanns Grabmal in Burg Stromgarde.", description = "Ich habe das letzte Siegelzeichen... und mit ihm vereine ich die vier zum Siegelzeichen von Trollbann, dem Schlüssel zur Gruft. Wir sind bereit.\n\nTrol'kalar wurde gemeinsam mit den Überresten seines Herrn eingeschlossen. Es liegt in Trollbanns Grabmal in den Katakomben von Burg Stromgarde. Es wird schwer bewacht sein... aber dass ich vor Euch stehe, beweist, dass die Vollstrecker besiegt werden können.\n\nBetretet das Grabmal, bergt Trol'kalar und bringt es her.", progress = "Habt Ihr Trol'kalar?", completion = "Trol'kalar, die Klinge meines Vaters... es erscheint mir, als hätte ich sie vor einer Ewigkeit zuletzt gesehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26034] = {title = "Der Zwielichtzerstörer", objective = "Besiegt Halion und drängt die Invasion des Rubinsanktums zurück.", description = "Dies war kein leichtfertiger Angriff, sondern vielmehr ein sorgsam inszenierter Schlag gegen das Herz des roten Drachenschwarms.\n\nZarithrian, der sich auf dem Felsvorsprung dort drüben befindet, überwacht den Angriff, doch ist der wahre Anführer ein dreister und mächtiger Zwielichtdrache namens Halion. Seit Dargonax ist kein ausgewachsenes Exemplar der Brut aus Sinestras verdorbenen Experimenten mehr gesichtet worden.\n\nTötet ihn, <Name>. Sobald es Euch gelungen ist, diese Invasion zurückzudrängen, meldet Ihr Euch bei Krasus und berichtet ihm, was Ihr hier gesehen habt.", progress = nil, completion = "&lt;Krasus hört konzentriert zu, während Ihr von Eurem Kampf gegen Halion berichtet. Seine Augen weiten sich, als Ihr Todesschwinge erwähnt.&gt;\n\nWir schulden Euch großen Dank dafür, dass Ihr die Eindringlinge aus dem Sanktum getrieben habt. Doch die Neuigkeiten über den Zerstörer sind über alle Maße beunruhigend. Es gibt vieles, was ich mit den anderen Mitgliedern des Wyrmruhpakts besprechen muss.\n\nNehmt dies als Zeichen meiner Anerkennung, während Ihr Euch gegen den aufziehenden Sturm wappnet.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][26035] = {title = "Sein Gewicht in Gold", objective = "Erbeutet 10 Hauer der Bleichborken und 4 Medizinbeutel der Bleichborken von Trollen der Bleichborken.", description = "Erzmagier Malin hat mich hierher geschickt, um Reagenzien für ihn zu sammeln. Ich habe mich gefragt, wie ich ihm die Gegenstände besorgen soll, aber nun, da Ihr hier seid, könnte sich dieses Problem erledigt haben.\n\nIch benötige Hauer der Bleichborken und Medizinbeutel der Bleichborken.\n\nWürdet Ihr sie für mich holen? Die Bleichborken leben südöstlich von Arathi.", progress = "Wie läuft es bislang?", completion = "Nicht schlecht. Da Ihr Euren Kopf anscheinend wirklich zum Denken benutzt, hoffe ich, dass Ihr uns in einer dringenderen Angelegenheit behilflich sein könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26036] = {title = "Zauberstab gegen Faust", objective = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", description = "He, <Name>. Tut mir leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandolübergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", progress = "Unser Ziel ist der Zauberstab, <Name>. Konzentriert Euch vorerst nur darauf.", completion = "Genial, &lt;Name&gt;. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26037] = {title = "Trelanes Verteidigung", objective = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten in Burg Stromgarde.", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen Euch gegen die Verteidigungsanlagen des Turms einsetzen. Dazu brauchen wir ein paar Edelsteine, an denen der Schamane der Felsfäuste Gefallen gefunden hat. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann.", progress = "Da seid Ihr ja wieder, <Name>. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, &lt;Name&gt;. Nochmals, gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber zu wirken, dann ist alles bereit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26038] = {title = "Angriff auf den Turm", objective = "Findet Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt sie Skuerto in der Zuflucht.", description = "Hier ist das, wonach Ihr suchen müsst: Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat.\n\nAlle drei liegen in Kisten innerhalb des Turms. Die Kisten solltet Ihr allein problemlos öffnen können, passt nur auf die Oger auf.\n\nHaltet Eure Waffen bereit. Wenn die Oger herausfinden, dass Ihr dort seid und sie bestehlen wollt, dann werden sie nicht zimperlich mit Euch umgehen.\n\nSeid vorsichtig und viel Glück.", progress = "Wenn Euch das gelingt, wird Malin sehr zufrieden mit Euch sein.", completion = "Malin hat genau die richtige Person um Hilfe gebeten, &lt;Name&gt;. Das war tolle Arbeit!\n\nEs wird ihn freuen, dass unsere Mission ein so großartiger Erfolg war.", rewards = "HochlandstreitkolbenTrelanes GamaschenGürtel der ZufluchtLeichtfußstiefelCraigs StahlIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26039] = {title = "Die gefangene Prinzessin", objective = "Sammelt 12 Körner von Myzrael von Kobolden der Trockenstoppel.", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, <Name>, helft mir!", progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26040] = {title = "Keine Macht den Algen", objective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, <Volk>. Bringt mir etwas davon!", progress = "Konntet Ihr welche von diesen Algen für mich finden, <Volk>?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26041] = {title = "Steine der Bindung", objective = "Holt den brennenden Schlüssel, den schäumenden Schlüssel und den donnernden Schlüssel vom Stein der Westlichen Bindung, dem Stein der Östlichen Bindung und dem Stein der Äußeren Bindung.", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", progress = "Dies ist der Stein der Inneren Bindung. Er ist der stärkste der Bindungssteine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "&lt;Myzrael spricht durch den Stein.&gt;\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger &lt;Klasse&gt;, &lt;Name&gt;. Mein Retter!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26042] = {title = "Den Hauptstein zerbrechen", objective = "Beschafft die Rute der Ordnung von Fozruk.", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n<Name>, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26043] = {title = "HÜTET EUCH VOR FELSKIEFER!", objective = "Tötet Felskiefer und nehmt Euch Felskiefers riesigen Zahn.", description = "Auf Befehl von Oberanführer Krom'gar ist das Betreten des Felskesselsees VERBOTEN!\n\nDie wilde Bestie, die Felskiefer genannt wird, hat den See in eine Todesfalle verwandelt. Solltet Ihr Felskiefer beseitigen, nehmt seinen riesigen Zahn als Trophäe und bringt ihn zur Herrin der Spione Anara. Sie wird Euch belohnen.", progress = "Was wünscht Ihr?", completion = "Ein Beweis für die Macht der Horde!", rewards = "AnglerhandschuheAnaras GürtelAuf Euch wartet eine dieser Belohnungen:\n\nFelskesselbandHalskette der Herrin der Spione\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26044] = {title = "Wo sind die Teile?", objective = "Sprecht mit Unteroffizier Dontrag in den Ausufernden Tiefen im Steinkrallengebirge.", description = "Ich warte seit Tagen auf Teile für diese Waffen! Ich habe einen meiner besten Sprengenieure und zwei Dutzend Minenarbeiter vor fünf Tagen in die Ausufernden Tiefen geschickt, um die Teile zu besorgen. Als ich drei Tage später noch nichts von ihnen gehört hatte, begann ich mir Sorgen zu machen. Der Oberanführer schickte zwei seiner besten Orcs hinterher. Seitdem haben wir nichts gehört...\n\nBegebt Euch in die Ausufernden Tiefen, unmittelbar unter dieser Festung, und findet heraus, was los ist! Ich brauche die Teile!", progress = nil, completion = "Äh... Na ja, das ist ganz einfach... IN DIESER HÖHLE WIMMELT ES VON SEELENLOSEN MORDMASCHINEN!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26045] = {title = "Eure Teile sind schon hier...", objective = "Sammelt 10 Ersatzteile.", description = "Mein Dilemma sieht so aus: Ich habe zwei Möglichkeiten. Entweder lasse ich mich wie alle anderen hier unten umbringen oder ich werde in der Feste Krom'gar umgebracht, wenn Krom'gar erfährt, dass wir die Mine verloren haben. Ich wähle die dritte Möglichkeit: nichts tun. Klappt bisher ganz gut.\n\nIhr braucht Teile? In der Mine liegt eine Menge Schrott herum. Ihr müsst ihn nur holen.\n\nViel Glück! Wenn Ihr diese Teile holt, können wir uns vielleicht wieder in der Feste Krom'gar blicken lassen.", progress = "Wie läuft die Jagd?", completion = "Ich fasse es nicht! Ihr habt die Teile bekommen und seid nicht gestorben. Wieso seid Ihr nur Unteroffizier?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26046] = {title = "Was immer wir tun...", objective = "Tötet 12 tobende Erdelementare.", description = "Dontrag kann das besser erklären als ich. Was auch immer wir tun, es ist das Falsche. Wir können hier unten nichts tun wegen all der Dinge, die uns umbringen wollen und können nicht zur Basis zurückkehren wegen all der Dinge, die uns umbringen wollen - verstanden?\n\nVielleicht können wir dieses Problem ja gemeinsam lösen. Beseitigt Ihr doch schon mal ein paar dieser Elementare, die anscheinend alles in der Mine umgebracht haben, einverstanden?", progress = nil, completion = "Holt die Teile, tötet die Elementare und rettet die Peons... Wenn wir das hinkriegen, ist uns eine Beförderung sicher!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26047] = {title = "Deshalb nennt man sie Peons...", objective = "Rettet 10 verängstigte Peons.", description = "Die beiden sind NUTZLOS! Als sie eintrafen, dachte ich, wir wären gerettet. Aber nein! Stattdessen warfen Dontrag und Utvoch einen Blick in die Mine und dachten sich einen idiotischen Plan aus, der vor allem aus Herumstehen besteht... wahrscheinlich, bis wir alle tot sind. \n\nIhr seht nicht ganz so nutzlos aus. Wollt Ihr uns helfen, <Freund/Freundin>? In den Ausufernden Tiefen verstecken sich Dutzende von Peons, die nur noch Angst in der Birne haben. Findet sie und holt sie raus!", progress = "Habt Ihr meine Peons gefunden?", completion = "Ich wusste es! Ihr seid ein Held! Wenn ich etwas zu sagen hätte, würdet Ihr zum Legionär befördert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26048] = {title = "Ersatzteile hier herauf!", objective = "Bringt die Kiste mit Ersatzteilen zu Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", description = "Puh, das war hart. Ich dachte, wir würden es nicht schaffen, <Name>. Am besten bringen wir diese Teile zurück zu Obersprengenieurin Bombgutz. Ich glaube, ich höre draußen schon das Summen der Gnomflugmaschinen. Wir haben keine Zeit zu verlieren!", progress = "Habt Ihr meine Teile?", completion = "Gerade noch rechtzeitig! Die Flugmaschinen sammeln sich bereits. Der Angriff steht unmittelbar bevor!", rewards = "Gürtel des SprengenieursErsatzteilgamaschenAuf Euch wartet eine dieser Belohnungen:\n\nBombgutz' Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26049] = {title = "Die entfesselte Prinzessin", objective = "Beschwört und besiegt Myzrael an den Splittern von Myzrael.", description = "Myzrael ist keine unschuldige Prinzessin. Sie ist unglaublich gefährlich. Die Riesen hatten sie aus gutem Grund dort unten angekettet. Man hat Euch leider betrogen.\n\nGerrig sagt, dass Ihr sie bei den Splittern von Myzrael, dort, wo Ihr zuerst mit ihr gesprochen habt, beschwören müsst. Besiegt sie und nehmt Euch ihre geisterhaften Fesseln. Bindet sie damit an die Splitter.\n\nIhr werdet diese Schriftrolle brauchen. Geht sorgsam mit ihr um; ich habe ein paar Zähne riskiert, um sie zu bekommen. Viel Glück, <Name>.", progress = "Die Splitter von Myzrael sind nun seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", rewards = "Wickeltuch der offenen BedrohungGespenstische HandschuheErdengebundener MantelFesselnde HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26050] = {title = "Leuchtbrille", objective = "Begleitet Professor Prasseltrop zur Höhle und zurück.", description = "Als frisch gebackene Schwarzmeerräuber ist es unsere Aufgabe, dem ehrenwerten O'Breen bei der Suche nach dem verlorenen Elfenschatz zu helfen.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfsmittel im dunklen Wasser zu finden. Der Doktor hat für diesen Fall eine Brille konstruiert. Die Brille muss mit der Energie aus dem verzauberten Stein in der Höhle auf dem Hügel aufgeladen werden.\n\nDoch die Höhle ist verflucht! Man wird uns angreifen, wenn wir näher kommen. Verteidigt mich, dann kann ich die Energie aus dem Stein in die Brille übertragen.", progress = nil, completion = "Die Brille funktioniert nun perfekt! Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26051] = {title = "Versunkene Schätze", objective = "Doktor Drechselknacks in der Faldirbucht will, dass Ihr 10 Elfenedelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, <Name>, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, &lt;Name&gt;. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!", rewards = "GrundwattstiefelEntkalkter ElfenspeerAuf Euch wartet eine dieser Belohnungen:\n\nDrechselknacksring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26052] = {title = "Sprecht mit Wank", objective = "Bringt die Elfenedelsteine zu Kapitän O'Breen in der Faldirbucht im Arathihochland.", description = "Lassen wir Kapitän O'Breen nicht warten. Er wird die Edelsteine selbst sehen wollen. Deshalb sind wir schließlich hier!\n\nUnd nach ein paar Wochen in der Gesellschaft dieser Piraten haben der Professor und ich erkannt, dass es äußerst gesundheitsschädlich ist, sich mit ihren Schätzen erwischen zu lassen.\n\nHier, <Name>, bringt sie zu O'Breen.", progress = "Ahoi, <Klasse>. Was führt Euch auf die Brücke?", completion = "Dann haben sich die kleinen Gnome tatsächlich als nützlich erwiesen? Ich wusste doch, dass wir die Fersenbeißer nicht grundlos mitschleppen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26053] = {title = "Säuberung des Hochlands", objective = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste.", description = "Wir werden keine Bedrohung übersehen. Um dieses Land zu sichern und der Dunklen Fürstin zu unterwerfen, müssen wir alles, was auf ihm lebt, herausreißen, Stück für Stück, Meter für Meter.\n\nIm Nordosten, weniger als einen Steinwurf von diesem Lager entfernt, befindet sich ein Ogerhügel. Die Oger der Felsfäuste, die dort leben, müssen ausgelöscht werden, <Klasse>.\n\nSie stehen uns im Weg. Zögert nicht und seid nicht gnädig.", progress = nil, completion = "Hervorragend. Der Marsch der Verlassenen geht weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26055] = {title = "Ertrunkene Trauer", objective = "Kapitän Stahlmagen in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberinnen der Säbelflossen tötet.", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", progress = nil, completion = "Ihr habt da draußen gute Arbeit geleistet, &lt;Name&gt;.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig.", rewards = "Rundholz der TorheitStahlmagenwesteZerfetztes Segel der MinnaIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26056] = {title = "Die Wellensprecherin", objective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", progress = nil, completion = "Bin ich froh, dass Ihr hier seid!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26057] = {title = "Die Wellensprecherin", objective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", progress = nil, completion = "Bin ich froh, dass Ihr hier seid!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26058] = {title = "Die Verteidigung der Feste Krom'gar", objective = "Zerstört 15 gnomische Flugmaschinen oder Gnomenbomber und 25 Gnomenschwadronskommandanten.", description = "Wir haben keine Zeit mehr. Sie kommen! Übernehmt die Kontrolle über eine schwere Kanone und holt die Gnome vom Himmel! Die Bombe wird explodieren, wenn sie zu oft getroffen wird, und wir mit ihr!\n\nVerteidigt die Basis, <Name>! Ihr seid unsere einzige Hoffnung!\n\nMeldet Euch bei Oberanführer Krom'gar, sollten wir das wider Erwarten überleben.", progress = "Unsere Feinde umzingeln uns!", completion = "Ich habe noch nie eine so mutige Tat gesehen. Ihr habt die Basis gerettet, Unteroffizier - oder sollte ich besser Legionär sagen! Lok'tar!", rewards = "Ihr erlernt:\n\nLegionär von Krom'gar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26059] = {title = "Augen und Ohren: Malaka'jin", objective = "Meldet Euch bei Hexendoktor Jin'Zil in Malaka'jin im Steinkrallengebirge", description = "Ehrenwacht ist gefallen. Der Griff, in dem die Horde das Brachland hielt, wurde aufgesprengt, ebenso wie das Land. Nun erhalte ich Berichte, in denen es heißt, ein gemeinsamer Angriff der Allianz und der Grimmtotem würde Malaka'jin bedrohen. Wenn Malaka'jin fällt, fällt auch das halbe Steinkrallengebirge!\n\nIhr habt Euch als ein fähiger Soldat der Horde erwiesen. Wollt Ihr meine Augen und Ohren in Malaka'jin sein? Hexendoktor Jin'Zil erwartet Euch.\n\nMalaka'jin befindet sich weit im Süden.", progress = nil, completion = "Wie ich sehe, schickt Krom'gar den Besten!\n\nGut, wir haben viel zu tun. Die dreckige Allianz hat ein Abkommen mit den Grimmtotem unterzeichnet. Jetzt müssen wir die Angriffe beider Streitkräfte abwehren.\n\nWir haben nicht genügend Soldaten im Hochwipfeltal und können es nicht mehr lange gegen die konzentrierten Angriffe unserer Feinde verteidigen. Wir haben nur noch eine Hoffnung: VOODOO!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26060] = {title = "Der Voodoo: Stürmerherz", objective = "Besorgt ein Klippenstürmerherz.", description = "Mit Voodoo könnte es unseren Truppen gelingen, den Angriff der Grimmtotem zurückzuschlagen. Allerdings brauche ich verschiedene Zutaten, um diese schwarze Magie zu wirken.\n\nDie erste Zutat auf meiner Liste ist das Herz eines Klippenstürmers. Die Bestien sind fast ausgerottet, aber in dieser Gegend gibt es noch ein paar. Findet eine und erbeutet ihr klopfendes Herz!", progress = "Ich brauche das Klippenstürmerherz.", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26061] = {title = "Der Voodoo: Widderhörner", objective = "Besorgt 6 Hörner eines Steinkrallenwidders.", description = "Um den Voodoo zu wirken, brauche ich besondere Reagenzien. Bringt mir Hörner der Steinkrallenwidder in dieser Gegend, <Name>! Ohne die Hörner sind wir erledigt!", progress = "Ich brauche Hörner von Steinkrallenwiddern!", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26062] = {title = "Der Voodoo: Resonitkristall", objective = "Besorgt 8 Resonitkristalle.", description = "Die letzte Zutat für das Voodooritual ist eine spezielle Kristallart namens Resonit. Man findet sie nur in den Steinschlaghöhlen westlich von hier. Passt auf die Kobolde auf! Sie beschützen das Resonit mit ihrem Leben!", progress = "Ich brauche die Resonitkristalle!", completion = "Endlich! Nun kann ich das Amulett mit der Voodooverzauberung erschaffen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26063] = {title = "Die Königin und ihr Hofstaat", objective = "Tötet Königin Silith und 10 beliebige Spinnen in der Weberkuhle.", description = "<Scholli grunzt.>\n\nHrmph.\n\nDinge brechen auseinander. Scholli unglücklich. Jetzt Schollis Gefährtin umgebracht von Spinnen in Weberkuhle. Scholli will Rache!\n\nHelft Scholli? Tötet Königin Silith und ihre kleinen Spinnlinge? Für Scholli? Für Schollis Gefährtin!\n\nWeberpass ist im Nordwesten, den Weg hoch. Geht!", progress = "Habt Ihr Silith für Scholli getötet?", completion = "Scholli immer noch nicht sehr glücklich, aber Scholli wird Euch für Tat belohnen.", rewards = "KlauengriffdolchDes lieben Schollis BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26064] = {title = "Kein Kampf auf leeren Magen", objective = "Beschafft 8 Eier des Kalimdoradlers.", description = "Die Truppen sind hungrig, <Name>. Seit unsere Nachschublinien abgeschnitten wurden, gehen uns die Vorräte aus. Ich kann den Soldaten ein Festmahl zubereiten, wenn Ihr mir einige Zutaten besorgt.\n\nBegebt Euch in die Wälder westlich von hier und sucht nach Nestern der Kalimdoradler. Stehlt die Eier aus den Nestern und bringt sie mir.", progress = "Ich brauche Eier!", completion = "Danke, &lt;Name&gt;. Diese Eier reichen für eine Woche.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26065] = {title = "Freiheit für Willi", objective = "Tötet alle Tentakelschrecken, um Willi zu befreien.", description = "Diese Tentakelschrecken haben das arme Tier eingefangen. Bitte, <Name>, könnt Ihr es nicht retten, indem Ihr diese Abscheulichkeiten tötet?\n\nWürdet Ihr Willi seine Freiheit zurückgeben?\n\nHier, nehmt mein Totem und stellt es in der Nähe der Tentakel auf. Die Kälte, die es verströmt, bringt diese Monster zum Schrumpfen, sodass Ihr sie einfach besiegen könnt.", progress = nil, completion = "Danke, &lt;Name&gt;.\n\nDiese alptraumhaften Gestalten aus der Tiefe geben mir zu denken. Ich fürchte, dass unsere Anstrengungen vollkommen umsonst sind.", rewards = "TentakeltöterarmschienenKapuze des wimmelnden SchreckensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26066] = {title = "Verstärkung...", objective = "Bändigt 6 Steinschlagkobolde mit der Peitsche von Unterwerfer Devo.", description = "Anscheinend haben wir fast keine großen, dummen Orcs mehr, die wir dem Feind entgegenschicken können. Das ist ein Problem. Zum Glück habe ich möglicherweise eine Lösung.\n\nNehmt diese Peitsche und geht nach Westen zur Steinschlaghöhle. In der Höhle werdet ihr ein schmutziges Koboldnest finden. Bändigt die Bestien mit meiner Peitsche. Wenn sie erst einmal gebändigt sind, werden sie tun, was wir wollen.\n\nKehrt zurück, wenn ihr eine anständig große Koboldarmee zusammen habt.", progress = nil, completion = "In einer Krise wie dieser, könnte eine verzweifelte Tat uns den Sieg bringen. Vielleicht gewinnen wir, wenn wir einen Schwarm Kobolde auf den Feind hetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26067] = {title = "Jin'Zils Segen", objective = "Benutzt Jin'Zil's Voodoostecken, um 12 Marodeure von Krom'gar mit Voodoo zu erfüllen.", description = "Ah, es ist vollbracht! Nun müssen wir ihn ausprobieren.\n\nReist zum größten Konfliktherd im Hochwipfeltal und setzt meinen Voodoostecken bei den Marodeuren von Krom'gar ein, die gegen die Grimmtotem kämpfen. Dank meiner Voodoomagie sollten sie ihre Schlagkraft zurückerhalten und unsere Feinde vernichten!\n\nGeht jetzt, <Name>!", progress = nil, completion = "Endlich ein Sieg! Allerdings wird er ohne eine stabile Nachschublinie nicht von langer Dauer sein. Genießt ihn so lange, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26068] = {title = "Die Wut der Kobolde!", objective = "Benutzt das Koboldkriegshorn nahe des Banners der Horde an der Grabstätte, um die Koboldarmee loszulassen!", description = "Jetzt kommandieren wir die Koboldarmeen des Steinkrallengebirges! Klingt fast schon beeindruckend. Fast.\n\n<Devo seufzt.>\n\nDas Basislager der Allianz, nördlich von hier, wird streng bewacht. Es ist fast uneinnehmbar. Nur nordöstlich von hier, an der Grabstätte, gibt es einen Eingang. Nehmt das Koboldkriegshorn und brecht zur Grabstätte auf. Betretet sie von Osten, <Name>! Von dort aus reist Ihr nach Westen, bis Ihr den Punkt erreicht, den ich auf Eurer Karte markiert habe. Benutzt das Horn und bringt die Wut der Kobolde über die Allianz!", progress = "Auf mein Zeichen! Entfesselt die Koboldhölle!", completion = "&lt;Devo lacht.&gt;\n\nFaszinierende Geschichte, Freund. Unsere neuen Koboldverbündeten scheinen doch ganz nützlich zu sein!", rewards = "Ausgegrabener MantelKoboldzänkergamaschenDevos HandaxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26069] = {title = "Nura Pfadfinder", objective = "Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland.", description = "Das Südliche Brachland wird von der Allianz angegriffen. Die Tauren bitten um Hilfe. Wir können sie nicht abweisen. Alle gesunden Soldaten der Horde sollten ihnen helfen.\n\nWenn Ihr sie unterstützen wollt, dann nehmt den Weg zum Höhenpfad. Ihr findet ihn im Dorf. Sucht nach Nura Pfadfinder.", progress = nil, completion = "Die Lage ist ernst, &lt;Volk&gt;. Wir brauchen all die Hilfe, die wir kriegen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26070] = {title = "Läuterung der Entweihten", objective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", description = "Unsere Freunde des Irdenen Rings hier haben uns gefragt, ob wir ihnen nicht zur Hand gehen könnten. Wie es scheint treiben im Brühgraben ein paar Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nKönnt Ihr Euch für mich darum kümmern?", progress = nil, completion = "Das soll mir reichen. Hier ist Euer Anteil, wie versprochen.\n\nAber werdet nicht selbstgefällig, &lt;Name&gt;. Der schwere Teil kommt erst noch.", rewards = "SchluchtpirscherflinteBeinschützer des AaltötersStab des SchiffshalterzerquetschersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26071] = {title = "Läuterung der Entweihten", objective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", description = "Diese Leute vom Irdenen Ring wollen, dass wir das Töten für sie übernehmen. Im Brühgraben treiben einige Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nSchwimmt mal runter und kümmert Euch darum.", progress = nil, completion = "Gut gemacht.\n\nAber bildet Euch nicht zu viel darauf ein, &lt;Name&gt;. Der schwere Teil kommt erst noch.", rewards = "SchluchtpirscherflinteBeinschützer des AaltötersStab des SchiffshalterzerquetschersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26072] = {title = "In das Totem", objective = "Tötet 5 gesichtslose Entweiher, während sie sich in der Reichweite des Totems der Einsperrung befinden.", description = "Ihr müsst mein Totem nach unten in den Brühgraben bringen. Benutzt es, um die Energien der Gesichtslosen einzufangen, wenn sie sterben. Das Totem wird sie davon abhalten, dahin zurückzukehren, wo sie herkamen.\n\nWenn das Totem ganz gefüllt ist, bringt es zu mir zurück. Wir werden es verwenden, um ihren Anführer aus der tiefsten Tiefe hervorzulocken.", progress = nil, completion = "Ja, &lt;Volk&gt;. Könnt Ihr spüren, wie sie mit aller Macht versuchen auszubrechen und uns zu vernichten?\n\nDas ist gut! Sie sind der perfekte Köder für ihren Anführer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26073] = {title = "Im Süden nichts Neues", objective = "Meldet Euch bei Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", description = "Kehrt jetzt zu Oberanführer Krom'gar zurück, <Name>. Teilt ihm unsere Lage mit und berichtet, was Ihr getan habt, um Malaka'jin vor dem Fall zu bewahren.\n\nWir danken Euch für alles, was Ihr getan habt. Vielleicht werdet Ihr eines Tages Eure eigene Region kommandieren.", progress = nil, completion = "Lok'tar ogar! Ihr seid die Verkörperung all dessen, was einen Soldaten der Horde ausmacht, &lt;Name&gt;. Hätten wir doch nur mehr wie Euch, dann wäre der Krieg bereits vorbei und Kalimdor würde der Horde gehören - UNANGEFOCHTEN!!\n\nErhebt Euch als ein Champion von Krom'gar!", rewards = "Ihr erlernt:\n\nChampion von Krom'gar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26074] = {title = "Der Anfang vom Ende", objective = "Fahrt im Heißluftballon von Krom'gar zu den Schlickwerken im Steinkrallengebirge.", description = "Champion, wir haben ein neues Ziel anvisiert. Unsere Späher im Kriegsnarbental melden, dass die Nachtelfen an ihrer eigenen Massenvernichtungswaffe arbeiten und sie in einem uralten Baum verbergen. Sie werden nie die Gelegenheit bekommen, sie gegen uns einzusetzen.\n\nIhr werdet die Bombe zum Auftanken zu den Schlickwerken begleiten und danach zum Klippenläuferposten. Von dort aus werden wir die Bombe zünden und all unsere Feinde vernichten.\n\nGeht jetzt, <Name>. Meldet Euch bei Jibbly Rakit, wenn ihr an den Schlickwerken eintrefft.", progress = nil, completion = "Krom'gar hat seinen Champion geschickt! Ihr müsst Euch keine Sorgen machen, Champion. Wir tanken den Ballon rasch wieder auf. Wollt Ihr uns in der Zwischenzeit ein wenig helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26075] = {title = "Ein Haufen Probleme", objective = "Tötet 6 beliebige Prachtschwingenwyvern.", description = "Wir haben ein kleines Problem...\n\n<Jibbly zeigt auf die großen Kothaufen, die überall in der Basis liegen.>\n\nWir haben die Schlickwerke in der Nähe eines Wyvernhabitats errichtet. Die Risszeichnungen der Schlickwerke wurden mit großer Sorgfalt erstellt, damit die Wyvernhabitate nicht gestört werden. Anscheinend verehren die Tauren und Orcs die Bestien. Wisst Ihr, was ich verehren würde? Einen Tag ohne Koteinschläge!\n\nGanz im Vertrauen, die Wyvern müssen sterben!", progress = "Bitte helft mir. Die Wachen werden schon etwas aufmüpfig.", completion = "Hoffentlich sind Euch keine entgangen. Ich halte das nicht mehr länger aus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26076] = {title = "Spionageplage", objective = "Tötet 8 Allianzspione. Enttarnt die Spione mit Jibblys Gasbombe!", description = "Wir haben noch ein Problem, <Name>. Es wimmelt hier von Allianzspionen! Ihr habt keine gesehen? Weil sie unsichtbar sind! Getarnt! Ich habe eine Lösung, aber dafür brauche ich jemanden, der die Kraft und das Geschick hat, meinen Plan umzusetzen.\n\nBenutzt diese Gasbombe, dann werdet Ihr die getarnten Spione sehen können. Schickt sie zu ihrem Schöpfer, wenn Ihr sie enttarnt habt.\n\nIhr erkennt einen getarnten Spion an dem Effekt, den sie auf die Luft haben. Seht genau hin!", progress = "Habt Ihr die Spionageplage gestoppt?", completion = "Alle dachten, ich spinne. Aber ich wusste, dass es hier überall Spione gibt. Und Kacke.", rewards = "Bogen des unsichtbaren ZielsBefallene BrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nKriecheramulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26077] = {title = "Letzte Lieferung", objective = "Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten im Steinkrallengebirge.", description = "Oberanführer Krom'gar hat einen Befehl aus der Basis übermittelt. Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten. Der Plan sieht vor, von dort aus mit der Bombe die Allianz im Kriegsnarbental zu vernichten.\n\nMacht Euch auf, <Name>. Man sollte Krom'gar nicht warten lassen.\n\nSprecht mit General Grebo, wenn Ihr Euer Ziel erreicht habt. Er wird Euch über Eure nächste Mission informieren.", progress = nil, completion = "Häuptling Klippenläufer und seine Tauren wollen die Horde verraten! Sie behaupten, dass der uralte Baum im Kriegsnarbental nur eine Druidenschule ist. Sie verstehen nicht, dass Kriegszeiten verzweifelte Maßnahmen verlangen. Meine Späher haben mir versichert, dass die Nachtelfen eine äußerst mächtige Waffe in diesem Baum verbergen. Wir müssen damit aufräumen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26078] = {title = "Löscht die Feuer", objective = "Löscht 6 Feuer auf dem Flugplatz von Eisenschmiede mit Eurer Feuerwehrausrüstung.", description = "Der Angriff der Dunkeleisenzwerge hat uns überrascht. Ihre Saboteure haben viele unserer Flugzeuge, Dampfpanzer und Vorräte beschädigt. Wir konnten nur noch ein paar Bomber rechtzeitig starten.\n\nJeder Techniker, jeder Rekrut und jede Wache, die ich entbehren kann, versucht verzweifelt, die anderen zu reparieren und startklar zu machen. Unsere Infanterie kann nicht mehr lange ausharren. Nehmt diese Ausrüstung und helft bei der Löschung der brennenden Bomber.", progress = nil, completion = "Gut gemacht! Meine Männer arbeiten hart daran, unsere Flugmaschinen und die Dampfpanzer kampfbereit zu machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26079] = {title = "GESUCHT: Falkenstein und Otto", objective = "Bringt Ottos und Falkensteins Köpfe zu Hauptmann Nials bei der Zuflucht.", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein ist für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Hauptmann Nials abgeholt werden.", progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, &lt;Name&gt;. Ich freue mich, sie auszuzahlen.", rewards = "AschenquellarmschienenSandalen der SorgeKriegsreitergürtelHauptmann Nials GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26080] = {title = "Ein letzter Gefallen", objective = "Bringt Grabungslieds Fisch und Tipps zu Kapitän Glovaal in der Dämmerbucht.", description = "<Name>, Ihr müsst das hier zu Käpt'n Glovaal bringen. In meinem Zustand bräuchte ich sicher eine Woche, um zur Dämmerbucht zu gelangen. Aber wir haben keine Zeit zu verlieren!", progress = "Chabt Ihr Oskar und Humphrey gefunden?", completion = "Ich verstehe. Ja, ich mich erinnere jetzt… Humphrey und Oskar waren nicht die besten Schwimmer.\n\nDie Informatjionen sind sehr chilfreich und der Fisch sieht sich sehr ljecker aus. Wenn Ihr Cherr Grabungslied seht, bevor er zurückkehrt, bitte sagt ihm danke von mjir.", rewards = "Glovaals Schwert der SchmjerzenHandschutz des abgetrennten SeesternsSchleifresistente RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26081] = {title = "Alinas Belohnung", objective = "Sprecht mit Dunkelruferin Alina.", description = "Hier endet also die Geschichte von Trol'kalar. Diese Waffe wird im Namen der Dunklen Fürstin den Lebenden den Tod bringen.\n\nVerlasst mich jetzt, <Name>. Es obliegt mir erneut, die Klinge zu bewachen. Berichtet Alina von Eurem Sieg. Sie wird Euch sicherlich belohnen", progress = nil, completion = "Die Nachricht von Eurem Sieg stimmt mich zufrieden, &lt;Klasse&gt;... ein seltenes Gefühl. Die Dunkle Fürstin glaubt, unsere Eroberung von Lordaeron wäre vielleicht die einzige Möglichkeit, den Verlassenen wahre Zufriedenheit zu schenken, vielleicht sogar Erleichterung.\n\nDoch das spielt keine Rolle. Unser Sieg ist unausweichlich. Für Eure Loyalität im Dienste der Verlassenen belohne ich Euch im Namen von Sylvanas.", rewards = "Sandalen der BefriedigungArmschienen der SinneseindrückeAlinas HandschuheIn Lordaeron hergestellte BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26082] = {title = "Auf nach Kriegsnarbe!", objective = "Benutzt den Verwüster von Krom'gar, um 5 darnassische Glevenschleudern und 20 beliebige Soldaten der Allianz im Kriegsnarbental zu vernichten.", description = "Ich werde dem alten Narr erlauben, seinen Fall vorzutragen. Er behauptet, er könne Beweise dafür bringen, dass die Nachtelfen keine Massenvernichtungswaffe besitzen. Wir werden sehen.\n\nWährend wir auf diesen Beweis warten, werdet Ihr unsere Armee im Tal unterstützen. Zu diesem Zweck haben wir eine große Anzahl Belagerungspanzer vorbereitet. Unsere Verwüster sind angriffsbereit.\n\nNehmt den Fahrstuhl hinunter zum Boden des Außenpostens und übernehmt einen Verwüster von Krom'gar. Vernichtet damit unsere Feinde im Kriegsnarbental.", progress = "Tötet sie alle!", completion = "Ihr beweist ein ziemliches Zerstörungstalent, &lt;Name&gt;. Die Allianzsoldaten, die nach Eurer wilden Fahrt durch das Kriegsnarbental noch übrig sind, wird die Bombe erledigen.", rewards = "Tobender StabSchild des KriegsnarbentalsZauberstab des zerstörerischen TalentsGrebos ArmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26083] = {title = "Hallo Lolo", objective = "Findet Lolo den Ausguck in der Faldirbucht.", description = "Gichtdarm war geschickt spähen. Guckt viele Dinge. Groß Abenteuer!\n\nGichtdarm findet geheim Piratschiff. Piraten viel Angst, laufen weg. Aber Oger Lolo nicht laufen. Lolo macht gut Freund mit Gichtdarm!\n\nGichtdarm muss weg, aber vermissen Lolo. Ihr sagen hallo zu Lolo von Gichtdarm.", progress = nil, completion = "Ihr Freund von Gichtdarm! Er komisch Oger. Riechen seltsam.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26084] = {title = "Hammerfall", objective = "Meldet Euch bei Gor'mul in Hammerfall im Arathibecken.", description = "Ihr habt uns hier gut gedient, <Name>. Wir haben ein Zeichen gesetzt, aber die nächste Phase unseres Eroberungsfeldzugs wird Monate brauchen, nicht nur Minuten.\n\nEs gibt noch viel zu tun. Ich werde Euch den langweiligen Teil - das Warten auf das Eintreffen der Wehrbefestigungen - ersparen. Reist gen Osten nach Hammerfall. Die Orcs dort werden Eure Hilfe gebrauchen können.", progress = nil, completion = "Throm'ka, &lt;Klasse&gt;. Wenn Eure Taten für die Untoten so bemerkenswert waren, wie Ihr sagt, fühle ich mich geehrt, Euch beim Dienst für die Horde zu unterstützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26085] = {title = "Sammelt die Verteidiger", objective = "Platziert 8 Banner von Eisenschmiede in Hügel aus losem Schnee überall auf dem Flugplatz von Eisenschmiede.", description = "Während unsere Ingenieure dafür sorgen, dass die Bomber bald wieder fliegen, kämpfen unsere Wachen und Gebirgsjäger gegen die Eindringlinge.\n\nSeit Beginn des Einmarschs sind sie dort draußen, ohne Zeit für Schlaf oder Essen. Die Verteidiger von Eisenschmiede gehören zu den besten Azeroths, aber selbst sie haben Grenzen.\n\nNehmt diese Banner und platziert sie in Verwehungen aus losem Schnee. Erinnert die Soldaten an das, wofür sie kämpfen und stärkt ihre Moral.", progress = nil, completion = "Die Soldaten entdecken verborgene Reserven der Stärke und des Mutes und werfen sich den Dunkeleisenzwergen entgegen. Solange wir hier sind, wird der Flugplatz nicht fallen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26086] = {title = "Orako", objective = "Meldet Euch bei Orako bei der Tiefenlichtkluft in Vashj'ir.", description = "<Kapitän Verne sieht auf seine Uhr.>\n\nWo ist dieser Jäger? Ich habe Orako vor einer Woche in die Tiefenlichtkluft geschickt, um einen Bericht zu schreiben! Ja, er ist schon ganz schön anstrengend und ich hätte nichts dagegen, ihn vom Hals zu haben, aber ich brauche seinen Bericht.\n\nIhr da! Wie heißt Ihr? <Name>? Würdet Ihr ihn für mich ausfindig machen? Es scheint zwar merkwürdig, dass <ein/eine:c> <Klasse> einen Jäger suchen soll, aber mir bleibt keine andere Wahl.", progress = nil, completion = "Gah! Diese Fische sind einfach nicht zu treffen!\n\n&lt;Orako schaut Euch an.&gt;\n\nMein Wolf wurde von einem Fisch gefressen und ich gehe nicht zurück, bis ich ihn gefunden habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26087] = {title = "Leuchtsaft", objective = "Besorgt Euch 6 Einheiten Leuchtsaft von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", description = "Es ist einfach, einen Fisch in einem Fass zu erschießen. Einen Fisch in einem Meer zu erschießen ist da schon schwieriger.\n\nHabt Ihr die Murlocs unten in der Kluft gesehen, <Klasse>? Sie schießen überhaupt nicht! Sie tragen kleine Kugeln voller Leuchtsaft auf dem Kopf, dank derer die Fische zu IHNEN kommen. He, das sollten wir auch versuchen!\n\nGeht nach Süden und tötet die Krebse und Barsche in der Kluft. Sie haben haufenweise Leuchtsaft in ihrer Haut. Ich habe es genau gesehen!", progress = "Wir brauchen haufenweise Leuchtsaft!", completion = "Schaut nur, wie das leuchtet!\n\n&lt;Orako blickt sehnsüchtig in die Ferne.&gt;\n\nMein Wolf hat leuchtende Dinge geliebt…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26088] = {title = "Hierher, Fischlein Fischlein!", objective = "Setzt den Fischerhut auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", description = "<Orako formt einen Ball aus dem Leuchtsaft und bringt ihn dann an einem Gerät an, an dem er offensichtlich schon lange bastelt.>\n\nHier, ich habe einen Hut für Euch. Er hat ein Licht, das Fische anlockt. Genau wie bei den Murlocs!\n\nDie Murlocs jagen gerne im Tang und in den Korallen an den Seiten der Kluft. Wenn Ihr diesen Hut aufsetzt und durch den Tang schwimmt, könnt Ihr vielleicht genauso Fische fangen, wie sie.", progress = "Wie viele habt Ihr gefangen?", completion = "Hm… Ihr habt ganz schön viele Fische, aber das sind nicht die, die meinen Wolf gefressen haben. Ich schätze, es war ein größerer Fisch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26089] = {title = "Stirb, Fischmann, stirb", objective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", description = "Ein Fisch hat meinen Wolf gefressen, und Murlocs sehen aus wie Fische. Diese Murlocs werden bezahlen!\n\nGeht zurück in die Kluft und tötet diese Fischmänner! Mein Wolf wird seine Rache bekommen!", progress = nil, completion = "Ich weiß, dass Murlocs keine Fische sind. Ich dachte nur, sie zu töten würde meine Laune heben. Aber ich bin immer noch traurig wegen meines Wolfs.\n\n&lt;Orako seufzt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26090] = {title = "Hier, ein Ei!", objective = "Bringt das enorme Aalei zu Orako bei der Tiefenlichtkluft in Vashj'ir.", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Orako vielleicht daran interessiert sein könnte.>", progress = "<Bamm!>\n\nIhr habt mir etwas mitgebracht?", completion = "Das ist ein großes Ei.\n\n&lt;Orako schnüffelt daran.&gt;\n\nEs ist groß und es riecht nach Fisch. Vielleicht ist der große Fisch, von dem dieses Ei stammt, ja der, der meinen Wolf gefressen hat!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26091] = {title = "Hierher, Fischlein Fischlein, Teil 2: Der Eier-Aal-Trick-Blues", objective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", description = "<Orako nimmt eine Sprengfalle aus seiner Tasche und schiebt sie durch die äußere Hülle des Eis.>\n\nJetzt wird das Ei explodieren. Legt es in der Nähe eines dieser gigantischen Aale ab und wartet, bis er näher kommt. Wenn das Ei explodiert, ist der große Fisch schon halbtot und Ihr könnt ihn leicht erledigen.\n\nRettet meinen Wolf! Mit diesem Ei wird es Euch gelingen.", progress = nil, completion = "&lt;Orako spielt ausgiebig mit Wolf.&gt;\n\nOh, vielen Dank, &lt;Name&gt;! Ich wusste, dass Wolf noch lebt!\n\nHier, bedient Euch. Ich habe dafür keine Verwendung mehr.", rewards = "Explosiv dekomprimierte StampferSchulterpolster der anguilliformen AusrottungAalschneiderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26092] = {title = "Orakos Bericht", objective = "Bringt Orakos Bericht zu Kapitän \"Juwel\" Verne in der Schattenhöhle.", description = "<Ihr erinnert Orako daran, dass er einen Bericht an Kapitän Verne senden sollte.>\n\nStimmt, ein Bericht. Alles, was ich hier gesehen habe, sind Fische. Fische, Fische und nochmals Fische.\n\n<Orako wirft einen Blick auf den Sack Fische, den Ihr ihm mitgebracht habt.>\n\nBringt das zurück zum Kapitän. Das ist mein Bericht.", progress = "Wo war er? Was ist passiert?", completion = "Das ist sein Bericht?! Dieser Idiot…\n\nIch schätze, wir können die Nahrung gut gebrauchen. Danke, &lt;Name&gt;. Ihr habt Eure Aufgabe so gut erledigt, wie ich es erwartet habe.", rewards = "Kapitän Vernes SpalterHandschützer des abgetrennten SeesternsKöderbedeckte RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26093] = {title = "Nordhof", objective = "Tötet 10 Mitglieder des Syndikats.", description = "Wir kämpfen in einem Krieg um Stromgarde und wir verlieren. Die Oger, das Syndikat und wir selbst haben unsere einst mächtige Stadt zerrissen und jede Fraktion kämpft mit der anderen bis zu einem blutigen Patt.\n\nAber unsere Truppen werden dezimiert, während die Zahl der Feinde ansteigt.\n\nAuch wenn Süderstade gefallen ist, dürfen wir unseren Feinden keinen Fußbreit unseres Bodens mehr überlassen! Wir müssen das Land für uns zurückerobern, bevor die Horde die Gelegenheit hat, sich weiter auszubreiten.", progress = nil, completion = "Sehr gut, &lt;Name&gt;. Das letzte, was wir bei der Bedrohung durch die Untoten noch brauchen, ist ein Angriff von einer Bande gewöhnlicher Diebe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26094] = {title = "Gegenschlag", objective = "Steigt in den reparierten Bomber und tötet 30 Angreifer der Dunkeleisenzwerge mit der Eisenhammerbombe. Ihr könnt beliebige Dunkeleisenzwerge oder ihre Verbündeten auf dem Flugplatz töten.", description = "Mein Chefingenieur sagt, dass er einen der Bomber repariert hat. Er ist startbereit. Nehmt diese Bomben und sucht den reparierten Bomber am Anfang der Rollbahn.\n\nSetzt die Bomben ein, sobald Ihr in der Luft seid, und richtet unter den angreifenden Dunkeleisenzwergen so viel Schaden wie möglich an. Ich habe Gerüchte gehört, laut derer sie eine neue Art von Kriegsgolem einsetzen wollen. Sucht nach diesen Golems. Sie sind Eure wichtigsten Ziele.", progress = nil, completion = "Das Blatt wendet sich, &lt;Name&gt;, größtenteils dank Eurer Leistungen. Jetzt müssen wir den Anführern der Dunkeleisenzwerge einen Schlag versetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26095] = {title = "Abzeichen von Stromgarde", objective = "Erbeutet 7 Abzeichen von Stromgarde vom feindlichen Syndikat in Burg Stromgarde.", description = "Das Syndikat in Stromgarde kämpft dort gegen unsere Milizeinheiten. Um den Abschaum dazu anzustacheln, unsere disziplinierteren Truppen anzugreifen, hat das Syndikat ein Kopfgeld auf unsere Soldaten ausgesetzt. Sie belohnen jedes Abzeichen von Stromgarde, das einem toten Milizsoldaten abgenommen wird, mit Gold.\n\nWir wollen diese Abzeichen wieder haben. Diese Halsabschneider dürfen keine Trophäen unserer mutigen Gefallenen behalten!\n\nBetretet den vom Syndikat kontrollierten Teil von Burg Stromgarde und bringt unsere Abzeichen an Euch.", progress = "Konntet Ihr Abzeichen von Stromgarde erbeuten, <Name>? Das Syndikat muss begreifen, dass es von unseren Toten nicht profitieren wird.", completion = "Danke, &lt;Name&gt;. Wir werden den Familien dieser gefallenen Soldaten mitteilen, dass sie im Kampf getötet wurden.\n\nSelbst schlimme Nachrichten sind besser als im Ungewissen über das Schicksal eines Angehörigen zu sein.", rewards = "Pantoffeln der sorgenvollen BotschaftArmbänder aus gelbem BandTrauergebeugte HandschuheHerzeleidbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26096] = {title = "Verbrühende Pilze", objective = "Sammelt 5 Verbrühende Pilze.", description = "Wir glauben, dass wir eine gute Verwendung für die Gnadenlosen gefunden haben, die Euer Freund aus der Höhle uns gebracht hat. Ich benötige jedoch ein Konservierungsmittel dafür.\n\nUnten im Brühgraben findet Ihr Pilze, die genau die Eigenschaften haben, die ich brauche. Bringt mir ein paar davon und ich schaue, was ich tun kann.", progress = "Ich habe gehört, dass Ihr ein unangenehmes Erlebnis hattet, als Ihr Euch einen der Dämonen auf den Kopf gesetzt habt. Ich kann Euch jedoch versichern, dass sie jetzt alle mausetot sind.", completion = "Ich werde die Pilze als Reagenz benutzen, um die Kadaver einzubalsamieren. Wir haben gleich einen für Euch vorbereitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26097] = {title = "Beweis für eine Lüge", objective = "Findet Orthus im Hain von Thal'darah im Steinkrallengebirge.", description = "Im Herzen des Kriegsnarbentals steht ein uralter Baum - ein Baum, der den Zeitaltern widerstanden hat und seit Generationen als ein Ort des Friedens und der Lehre genutzt wird. Solange ich denken kann, hat meine Familie in diesem Hain zusammen mit den Nachtelfen das Druidentum studiert. Und jetzt soll ich glauben, dass sich in diesem Baum eine Massenvernichtungswaffe der Allianz befindet?\n\nKrom'gar irrt sich. Das werde ich beweisen!\n\nIch habe meinen Sohn Orthus in den Hain von Thal'darah geschickt. Er soll nach der Waffe suchen. Geht dorthin und trefft ihn.", progress = nil, completion = "Orthus ist tot. Er hält etwas in der Hand.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26098] = {title = "Verrat im Hain", objective = "Bringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer am Klippenläuferposten im Steinkrallengebirge.", description = "Der Raum ist voller toter Druiden. Etwas stimmt nicht, denn Ihr seht keine Anzeichen eines Kampfes. Von der Tür führen blutige Schleifspuren ins Innere.\n\nIhr öffnet Orthus' erstarrte Faust und findet etwas verstörendes: ein Insigne des Generals von Krom'gar.\n\nBringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer.", progress = "Er... Mein Kind ist tot?", completion = "&lt;Ihr gebt Oberhäuptling Klippenläufer das Insigne.&gt;\n\n&lt;Oberhäuptling Klippenläufer schreit wütend auf.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26099] = {title = "Das soll Gerechtigkeit sein?", objective = "Verteidigt Euch.", description = "Er war ein guter Junge, <Name>. Jung, liebevoll. Niemals hätte er einen der jungen Druiden getötet. Sie waren seine Freunde! Nein... Nicht Orthus.\n\nDer General muss sich für dieses Verbrechen verantworten. Ich verlange Gerechtigkeit!", progress = "Das ist gerecht.", completion = "Ihr habt es mit eigenen Augen gesehen, &lt;Name&gt;. General Grebo hat uns angegriffen!\n\n\n\nWas sollen wir jetzt tun? Der Kriegshäuptling wird uns als Verräter hinrichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26100] = {title = "Der General ist tot", objective = "Sprecht mit Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", description = "Würdet Ihr mit Oberanführer Krom'gar reden, <Name>? Vielleicht hört er ja auf Euch. Ihr seid schließlich ein Champion in seiner Armee. Ihr habt alles gesehen. Bitte helft uns, <Name>. Wir wollen doch nur in Frieden gelassen werden.\n\nSprecht mit Oberanführer Krom'gar und versucht ihm zu vermitteln, dass wir nicht wollten, was geschehen ist.", progress = nil, completion = "WAS? Die Tauren haben meinen General umgebracht? Das ist Verrat! HOCHVERRAT! Für diesen schweren Fehler werden sie bezahlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26101] = {title = "Über dem Gesetz", objective = "Trefft Oberanführer Krom'gar am Klippenläuferposten im Steinkrallengebirge.", description = "Es war richtig, dass Ihr mir dieses Verbrechen gemeldet habt. Die Täter werden für dieses feige Verbrechen bezahlen. Blut wird fließen.\n\nOhne Grebo fehlt mir ein General. Ihr werdet seinen Platz einnehmen.\n\nTrefft mich am Klippenläuferposten, General. Zusammen werden wir diesen Schwachsinn beenden.", progress = nil, completion = "Der verräterische Tauren wird zusehen, wie wir seinen geliebten Hain vernichten und sein Dorf niederbrennen!", rewards = "Ihr erlernt:\n\nGeneral von Krom'gar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26102] = {title = "Grimmaxts Ende", objective = "Tötet General Grimmaxt auf dem Flugplatz von Eisenschmiede.", description = "Dank eures Einsatzes ist der Angriff der Dunkeleisenzwerge ins Stocken geraten. General Grimmaxt, der Anführer der Dunkeleisenzwerge, versucht, seine Truppen aus ihren Reihen auf dem gefrorenen See im Süden anzutreiben.\n\nEr steht auf einem ihrer neuen Dunkeleisengolems und ruft seinen Soldaten Befehle zu. Wenn es ihm gelingt, sie zu motivieren, überrennen sie uns vielleicht doch noch. Das müsst Ihr verhindern, <Name>. Zerstört den Golem, der General Grimmaxt beschützt, dann ihn selbst. Er ist der Schlüssel zu unserem Sieg.", progress = nil, completion = "Geschafft! Ohne Eure Hilfe hätte der Feind den Flugplatz von Eisenschmiede erobert. Dann hätten die Dunkeleisenzwerge freie Bahn bis Eisenschmiede gehabt.\n\nDer Rat der Drei Hämmer muss erfahren, was hier geschehen ist.", rewards = "Gewand des FlugplatzverteidigersTunika aus dunklem LederGrimmaxts schwarze BrustplatteStulpen des SteinbrechersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26103] = {title = "Biotreibstoff", objective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", description = "Unterseeboottreibstoff ist teuer!\n\nDie Machthaber in Gnomeregan waren so freundlich, uns mehrere Treibstofffässer zur Verfügung zu stellen, aber wir verbrauchen sie schneller als erwartet. Das bedeutet, dass wir improvisieren müssen.\n\nEs ist kein Geheimnis, dass die Meereslebewesen allerlei interessante Chemikalien enthalten... wie zum Beispiel Öl. Bringt dieses Gerät zu Korthuns Ende und benutzt es an Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Wenn wir nicht mehr Unterseeboottreibstoff beschaffen können, ist ihr Öl vielleicht unsere einzige Hoffnung.", progress = "Wie hat das Gerät funktioniert, <Name>?", completion = "&lt;Ingenieur Hexasept steckt einen Finger in jede Probe und schnuppert daran.&gt;\n\nJa, das sollte klappen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26105] = {title = "Erobert Korthuns Ende", objective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", description = "Die Horde hat Spione in dieser Gegend? Die Dämmerbucht ist ganz in der Nähe und die Zange X2 befindet sich dort! Die Horde darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Dämmerbucht darüber informieren… nachdem Ihr mehr von diesen dreckigen Spionen der Horde den Garaus gemacht habt!", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Zur Zeit müssen wir besonders vor Angriffen der Horde auf der Hut sein. Die Zange X2 hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26106] = {title = "Treibstoffologie leicht gemacht", objective = "Benutzt die Treibstofftestanlage in der Dämmerbucht, um den perfekten Biotreibstoff herzustellen.", description = "Wie viel wisst Ihr über Treibstoff, <Name>? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", progress = "Wir haben noch nicht die richtige Kombination gefunden, <Name>. Macht weiter! Ich bin mir sicher, dass Ihr es schafft.", completion = "Habt Ihr je daran gedacht, eine wissenschaftliche Karriere anzustreben, &lt;Name&gt;? Wenn Ihr je genug von Eurem derzeitigen Metier habt, meldet Euch bei mir. Ich könnte einen Assistent mit Eurer Passion für Experimente und wissenschaftliche Arbeit brauchen.", rewards = "Chemikalienbefleckte SchulterplattenDampffeste KopfbedeckungHandschuhe der heiklen MixturIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26107] = {title = "Stimmungsaufheller", objective = "Erbeutet 10 Hochlandraptoraugen von Hochlandschreitern oder Hochlandhauern.", description = "Dank der Schamanenkünste unseres Volkes konnte ich Jahre der Lethargie hinter mir lassen. Jetzt sorge ich für alle hier und stelle den Segen her, der auch mir neue Kraft schenkte.\n\nDie Hochlandraptoren sind tückische und wilde Bestien. Ihre Geister können unseren Kriegern große Stärke geben. Bringt mir Raptoraugen, damit ich die Amulette herstellen kann, so wie es mich Tor'gan lehrte.", progress = "Die Wildheit in den Augen der Raptoren wird auf unsere Krieger übergehen.", completion = "Die Lethargie, die mich nach dem Fall unserer Lager überkam, war so stark, dass ich das Geschenk ablehnte, als man es mir anfangs machte.\n\nNun bin ich stolz darauf, meinen Anteil im Namen der Horde zu leisten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26108] = {title = "Arglist des Raptors", objective = "Sammelt 12 Raptorherzen von Hochlandfleischpirschern.", description = "Die Hochlandfleischpirscher sind noch wilder als ihre Artgenossen. Sie besitzen nicht nur Stärke, sondern auch große List.\n\nAls ich in der Lethargie gefangen war, konnten mich selbst Amulette der Stärke nicht bewegen. Doch Tor'gan benutzte die Herzen der Fleischpirscher, um mich mit einem Geist zu erfüllen, der meine Zweifel besiegte und mich befreite.\n\nUnsere Soldaten verdienen die List des Raptors. Sammelt Fleischpirscherherzen für mich, <Name>.", progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ich übertrage die Macht und den Geist der Raptoren in diese Kugel, so wie es mich Tor'gan gelehrt hat. Sie wird die Krieger mit der wilden Stärke und der Intelligenz des Raptors erfüllen.\n\nDie List des Raptors erfüllt Euch nun auch, &lt;Klasse&gt;. Nehmt sie mit Stolz an. Für die Horde!", rewards = "HammerfallhandschuheHammerfallstreitkolbenAuf Euch wartet eine dieser Belohnungen:\n\nHammerfallringHammerfallband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26110] = {title = "Wie in alten Zeiten", objective = "Nehmt dem Kurier der Verlassenen den versiegelten Ordner ab.", description = "Schon seltsam. Kin und ich haben so einiges zusammen durchgemacht und doch finden wir uns in Arathi wieder, wie schon vor so vielen Jahren.\n\nHier vereitelten wir einen Plan zur Schaffung einer neuen Seuche, sie und ich. Die Horde scheint ihre Lektion nicht gelernt zu haben, denn es wimmelt schon wieder von ihnen auf diesem Hof.\n\nIhr untoter Kurier schlurft für jeden sichtbar umher. Ihr könnt uns helfen. Findet den Kurier und bringt mit, was auch immer er bei sich trägt.", progress = "Vielen Dank für Eure Hilfe bei der Suche nach dem Kurier, <Name>.\n\nWährend Eurer Abwesenheit sah Kin einen Apotheker, der aus dem gleichen Haus südlich von hier kam. Ich bin mir sicher, dass sie nichts Gutes im Schilde führen -- ich brauche nur einen Beweis, damit wir nicht unüberlegt handeln.\n\nHattet Ihr Glück?", completion = "Schon wieder Apotheker. Die kapieren es einfach nicht. Mal sehen, was dieses Mal los ist...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26111] = {title = "… und er wird kommen", objective = "Besorgt Euch das Gehirn des Unergründlichen.", description = "Ich erfülle Euch nun mit den Energien des verderbenden Gesichtslosen.\n\nSchwimmt hinunter zu meinem Ködertotem im Graben im Nordosten. Nutzt das Totem, um die Energien zu entfesseln. Bringt mir das Gehirn ihres Anführers.\n\nRuft Ick'thys den Unergründlichen… und er wird kommen!", progress = "Habt Ihr es, <Name>?\n\nMit dem Gehirn des Unergründlichen können wir vielleicht doch mit L'ghorek, dem sterbenden Ahnen vor uns, kommunizieren.", completion = "Und nun schauen wir mal, ob wir Euch in L'ghorek versetzen können, damit Ihr mit ihm sprecht, bevor er stirbt.", rewards = "Brustschutz der kognitiven DissonanzAuf Euch wartet eine dieser Belohnungen:\n\nGehirnanschlussketteSchützende Flasche des Mentalisten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26112] = {title = "Überfällige Antworten", objective = "Bringt Steinbrechers Bericht zu Moira Thaurissan im Hohen Sitz von Eisenschmiede.", description = "Wie genau ist es den Kriegern der Dunkeleisenzwerge gelungen, bis hierher vor die Tore Eisenschmiedes zu kommen und beinahe unsere Stadt zu erobern?\n\nHerrscht nicht 'Kaiserin' Moira, Mitglied unseres hochgeschätzten Rates der Drei Hämmer, über die Dunkeleisenzwerge? Ohne ihr Wissen und ihre Zustimmung konnte das nicht geschehen. Das war keine zusammengewürfelte Gruppe rebellischer Zwerge, sondern eine gut ausgerüstete Invasionsstreitmacht.\n\nIch habe einen Bericht über die Schlacht um den Flugplatz zusammengestellt. Bringt ihn zum Hohen Sitz nach Eisenschmiede und konfrontiert sie damit!", progress = "Was hat diese Störung zu bedeuten?", completion = "Und was genau ist das?\n\n&lt;Moira nimmt den Bericht entgegen. Sie wird blass, als sie ihn liest.&gt;\n\nDas ist unmöglich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26113] = {title = "Quae und Kinelory", objective = "Findet Quae auf dem Hügel über Go'sheks Hof.", description = "Die Horde besetzt Go'sheks Hof im Osten schon seit langem. Bei all unseren anderen Problemen hier fiel das nicht ins Gewicht. Aber nun gibt es Berichte über Untote in diesem Gebiet.\n\nAlles, was alarmierender ist als ein paar schlurfende Peons, gibt Anlass zu Nachforschungen. Das ist nicht das erste Mal, dass die Untoten auf dem Hof ihre dunklen Pläne vorantreiben. Ich habe meine besten Späher dorthin geschickt. Meldet Euch bei Quae und Kinelory. Sie werden Euch alles erzählen.", progress = nil, completion = "Die Zuflucht schickt Euch? Schön, dass es sie noch gibt.\n\nWir haben hier ein paar interessante Dinge beobachtet, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26114] = {title = "Quae vertraut Euch", objective = "Sprecht mit Kinelory nahe Go'Sheks Hof im Arathihochland.", description = "<Quae sieht die Unterlagen durch.>\n\nAusdehnung...Gebietskontrolle... diese Untoten planen nichts neues, aber sie wollen ganz Arathi einnehmen. Wir müssen ihre Pläne stören.\n\nIch halte hier oben Wache. Ihr geht mit Kin und besorgt die Invasionspläne. Diese wandelnden Kadaver werden nicht einmal erfahren, welchen Tag wir haben.\n\nUnd passt auf sie auf, verstanden?", progress = nil, completion = "Die Seuche nahm uns unsere Freunde und Familien, aber die Verlassenen nahmen uns Phin. Sie sind nicht besser als die Geißel. Ich werde sie alle mit meinen eigenen Händen töten, wenn es sein muss.\n\nSagt Bescheid, wenn Ihr bereit seid. Wir können direkt anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26115] = {title = "Sehen ist verstehen", objective = "Versteht, was es bedeutet, zur Horde zu gehören.", description = "Bleibt bei mir, <Name> und seht zu, wie unsere mächtige Waffe den Feind vernichtet!\n\nVersteht, was es bedeutet, zur Horde zu gehören!", progress = "Habt Ihr es verstanden?", completion = "Jetzt endlich wisst Ihr, was es heißt, ein Mitglied der Horde zu sein, &lt;Name&gt;.", rewards = "Mashas ArmbindenGürtel des trauernden VatersKlippengängerstiefelAuf Euch wartet eine dieser Belohnungen:\n\nOrthus' Amulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26116] = {title = "Kinelory schlägt zu", objective = "Beschützt Kinelory, bis sie zu Quae zurückkehrt.", description = "Also gut, <Name>. Wenn Ihr soweit seid... \n\nWollen wir?", progress = "Bleibt besser bei Kinelory. Ich vertraue Euch, aber wenn ihr etwas zustoßen sollte, weiß ich nicht, was ich tun würde.", completion = "Ihr habt uns einen großen Dienst erwiesen, &lt;Name&gt;. Danke.\n\nHoffentlich hat Euch Kin keine Probleme bereitet. Sie ist sehr zuvorkommend, aber tödlich für ihre Feinde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26117] = {title = "Für Süderstade", objective = "Kehrt zu Kommandantin Amaren in der Zuflucht zurück.", description = "Es gab Abende in der Taverne, nach denen Kinelory schlimmer aussah als jetzt. Ihr habt sie anscheinend gut beschützt.\n\nDie Zuflucht sollte von unserem Erfolg erfahren. Ich bleibe mit Kin hier, damit sie sich ausruhen kann. Geht ohne uns los.", progress = nil, completion = "Ich bin wirklich beeindruckt, &lt;Klasse&gt;. Bei all dem, was hier geschieht, ist dies ein kleiner Trost.\n\nIhr habt die Untoten bekämpft, die Horde zurückgeworfen und die Opfer von Süderstade geehrt. Im Namen des Königreichs von Stromgarde verleihe ich Euch eine offizielle Belobigung und diese Belohnung.", rewards = "Übermantel von StromgardeGamaschen von StromgardeArmschienen von StromgardeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26118] = {title = "Fasst den Botschafter", objective = "Geht zur Botschaft der Dunkeleisenzwerge und verhaftet Botschafter Schlackenhammer mit Hilfe der stabilen Handfesseln.", description = "Der Verrat des Botschafters wird mich noch lange verfolgen. Ihr müsst ihn verhaften, bevor er noch weiteren Schaden anrichtet oder schlimmer noch, bevor er entkommt und mit der Planung des nächsten Angriffs beginnt. Eisenschmiede wird erst sicher sein, wenn Botschafter Schlackenhammer sich nicht mehr frei in der Stadt bewegt.\n\nNehmt diese Fesseln und geht zur Botschaft der Dunkeleisenzwerge. Sie befindet sich nördlich des Hohen Sitzes, am Rand der Großen Schmiede. Verhaftet Botschafter Schlackenhammer und kehrt mit ihm zurück.", progress = nil, completion = "Der Botschafter wird uns keinen Ärger mehr machen. Er ist nicht der einzige Dunkeleisenzwerg, dessen Herz immer noch für den Schattenhammer schlägt. Das dürfen wir nie vergessen. Wir müssen wachsam sein und ihre Pläne vereiteln, sonst wird mein Sohn nur Ruinen und Asche erben.", rewards = "Der SchlackhammerStreitaxt des nüchternen ZwergsDoppelzüngiger Dolch des BotschaftersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26120] = {title = "Der wahnsinnige Orc des Drachenmals", objective = "Tötet 12 Welpendiebe des Drachenmals.", description = "Die Orcs des Drachenmals werden immer mehr zur Plage. Ihre waghalsigen Angriffe auf den Hain sind zwar lästig, verhelfen meinen Wachen aber wenigstens zu einigen nützlichen Übungseinheiten.\n\nMeine Späher haben jedoch beobachtet, dass sie schwarze Großdrachenwelpen mit Netzen einfangen. Das Letzte, was dieses Land gebrauchen kann, ist ein primitives Wiederaufleben der Drachenzähmung. Macht Euch auf den Weg nach Osten, <Klasse>, und tötet die Welpendiebe. Sorgt dafür, dass ihre Dummheit uns nicht teuer zu stehen kommt.", progress = nil, completion = "Die Orcs haben verstanden, dass sie nicht weiter nach Westen vordringen dürfen. Gut gemacht.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des MutesGabe des SumpfhütersIczelias Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26121] = {title = "Erobert Korthuns Ende", objective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", description = "Ihr seht Spione da oben? Das ist nix gut… gar nix gut, <Genosse/Genossin>.\n\nKehrt zurück zu Korthuns Ende und vernichtet sie, mein Freund.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26122] = {title = "Umweltbewusstsein", objective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", description = "Habt Ihr je Unterseeboottreibstoff gerochen, <Name>? Widerliches Zeug. Leider müssen wir große Mengen davon verbrennen, um die Verne anzutreiben. Und es riecht nicht nur abstoßend, sondern ist auch tödlich für die Tiere hier. Wir müssen bewusster mit unserer Umwelt umgehen.\n\nDie Meereswesen hier in der Gegend haben besonders öliges Fleisch. Bringt dieses Gerät zum Meeresdickicht direkt über dieser Höhle und benutzt es an den Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Ihr Öl kann vielleicht das Leben Hunderter anderer Meereslebewesen retten.", progress = "Bitte… Sagt den anderen Goblins nicht, dass ich Umweltschützer bin! Ich könnte ihren Spott nicht ertragen!", completion = "&lt;Fiasco steckt einen Finger in jede Probe und schnuppert daran.&gt;\n\nJa, das sollte klappen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26124] = {title = "Sichert das Meeresdickicht", objective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", description = "Die Allianz hat Spione in dieser Gegend? Die Schattenhöhle ist ganz in der Nähe und das neue Unterseeboot der Horde, die Verne, befindet sich dort! Die Allianz darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Höhle darüber informieren… nachdem Ihr mehr von diesen hinterhältigen Spionen der Allianz den Garaus gemacht habt!", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Zur Zeit müssen wir besonders vor Angriffen der Allianz auf der Hut sein. Die Verne hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26125] = {title = "Sichert das Meeresdickicht", objective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", description = "Ihr habt da oben Spione gesehen? Das ist nicht gut… Das lasse ich nicht zu!\n\nKehrt zum Meeresdickicht zurück und werdet sie los, bevor sie sich in unser Versteck einschleichen können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26126] = {title = "Der perfekte Treibstoff", objective = "Benutzt die Treibstofftestanlage in der Schattenhöhle, um den perfekten Biotreibstoff herzustellen.", description = "Wie viel wisst Ihr über Treibstoff, <Name>? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", progress = nil, completion = "Das war's. Ab heute werde ich die Verne mit Biotreibstoff betreiben. Ich werde ein paar Männer nach oben schicken, um mehr Öl zu besorgen.\n\nDenkt nur an die ganzen Meerestiere, die wir heute gerettet haben, &lt;Name&gt;!", rewards = "Chemikalienbefleckte SchulterplattenDampffeste KopfbedeckungHandschuhe der heiklen MixturIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26127] = {title = "Die Enthüllung des Schattenhammers", objective = "Tötet 12 Mitglieder des Schattenhammers in Dun Modr.", description = "Ich dachte ebenso wie alle anderen, dass es sich bei diesen Narren nur um nichtsnutzige Dunkeleisenzwerge handelte, aber diese Wahnsinnigen sind überzeugte Kultisten!\n\nDer Schattenhammer will nichts anderes als die Zerstörung der ganzen Welt. Sie haben sich Todesschwinge und Ragnaros angeschlossen und sind eng mit den Dunkeleisenzwergen verbunden.\n\nAber es ist egal, wer sie sind, wichtig ist nur, dass sie sich in Dun Modr aufhalten und entfernt werden müssen! Ich werde keinen von ihnen durchlassen. Geht zu ihnen und zertrümmert ein paar Schädel!", progress = nil, completion = "Gute Leistung, Junge, aber wir haben keine Zeit für Feste. Der Thandolübergang wird bedroht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26128] = {title = "Die Schlacht um den Thandolübergang", objective = "Besiegt Calamoth Aschbart am Thandolübergang.", description = "Ich habe den Thandolübergang schon einmal vor der Zerstörung bewahrt. Damals kämpfte ich gegen die Dunkeleisenzwerge. Das gleiche tat mein Vater und dessen Vater vor ihm...\n\nDie einzigen Dunkeleisenzwerge, die mir entkamen, liefen direkt auf die Brücke zu. Etwas stimmt nicht. Ich befürchte, dass wir bei unserer Ankunft in eine üble Falle stürmen werden.\n\nIch könnte Eure Hilfe brauchen, <Name>. Für Eisenschmiede. Seid Ihr dabei?", progress = nil, completion = "Gut, dass wir den los sind!\n\nDank Euch ist der Thandolübergang sicher, &lt;Name&gt;. Ich hoffe, dass Calamoth nicht noch einmal zurückkehrt.", rewards = "Mantelung von Khaz ModanSchulterschutz aus Khaz ModanSchiftung aus Khaz ModanSchulterstücke aus Khaz ModanIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26129] = {title = "Waffenbrüder", objective = "Sprecht mit König Genn Graumähne im Militärviertel in Gilneas.", description = "Hört zu, <Name>. Zum ersten Mal seit dem Bürgerkrieg bin ich mit Graumähne einer Meinung. Es ist an der Zeit, unsere Fehde endlich beizulegen.\n\nDiesen Bestien scheint es egal zu sein, ob man Rebell oder Königstreuer ist.\n\nÜberbringt Graumähne meine Antwort. Meine Männer werden sich seinen Leuten anschließen.\n\nNicht weit von hier gibt es ein sicheres Versteck, in Josiahs Keller. Meine Jungs haben dort ein wenig schwere Artillerie gelagert.\n\nSagt dem König, dass er sich jederzeit in unserer Waffenkammer bedienen kann.", progress = nil, completion = "Eine Waffenkammer der Rebellen? In meiner eigenen Stadt?\n\nWas zur Hölle führte Crowley nur im Schilde?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26130] = {title = "Keine Verbindung zu L'ghorek", objective = "Tötet Ur'Goz, Sku'Bu und Neph'Lahim.", description = "L'ghorek ist der Ahn, der auf der Klippe gegenüber von uns ruht. Er wird kontrolliert. Etwas Riesiges unter uns verschlingt seine Lebensenergien.\n\nUnter L'ghorek gibt es eine Höhle, die als Muscheltiefe bekannt ist. In dieser Höhle befinden sich drei mächtige Ogermagier, die ein Ritual abhalten, das das Ding aus der Tiefe mit dem Ahnen verbindet. Ihr müsst die drei töten, um die Verbindung zu L'ghorek zu unterbrechen.", progress = nil, completion = "Jetzt, da L'ghoreks Verbindung unterbrochen wurde, müssen wir versuchen, mit ihm Kontakt aufzunehmen. Ich kann spüren, dass der Ahn noch lebt, aber er ist sehr schwach.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26131] = {title = "Verstärkung für Loch Modan", objective = "Bittet Gryth Thurden in der Großen Schmiede um einen Flug nach Loch Modan. Sprecht bei Eurer Ankunft mit Pilot Hammerfuß.", description = "Seit Stunden warte ich darauf, dass sich der Rat meine Bitte anhört, aber es sieht nicht gut aus. Moira scheint darauf versessen zu sein, den Rat lahmzulegen.\n\nWährenddessen leidet Loch Modan. Wir haben viele Feinde, aber nur wenige Ressourcen. Würdet Ihr mich vielleicht anhören, <Name>, wenn der Rat nicht dazu gewillt ist? Sprecht mit Gryth Thurden, dem Greifenmeister von Eisenschmiede. Er hält sich im östlichen Teil der Großen Schmiede auf. Er wird Euch kostenlos zum Südtorpass fliegen lassen. Stellt Euch nach Eurer Ankunft Pilot Hammerfuß vor.", progress = nil, completion = "Ihr könnt Euch nicht vorstellen, wie froh ich bin, neue Gesichter aus Eisenschmiede zu sehen. Vielleicht war es doch keine Verschwendung, Gebirgsjäger Gerstenbräu dorthin zu entsenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26132] = {title = "Scheusale aus der Netherwelt", objective = "Tötet 8 Netherscheusale.", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nWir können nicht riskieren, dass sie diese Entartungen später gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, zerstört so viele von den Dingern, wie Ihr könnt.", progress = nil, completion = "Das Letzte, was wir brauchen, ist ein Haufen beschworener Kreaturen, die während unseres letzten Angriffs unsere Streitmächte anfallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26133] = {title = "Scheusale aus der Netherwelt", objective = "Tötet 8 Netherscheusale.", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nIch will nicht miterleben, dass sie diese Entartungen gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, vernichtet sie alle!", progress = nil, completion = "Eine Sache weniger, um die wir uns bei unserem letzten Angriff sorgen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26134] = {title = "Nichts mehr für Euch hier", objective = "Sprecht mit Furien in Tethris Aran in Desolace.", description = "Es gibt hier nichts mehr für Euch, <Name>. Was mich betrifft, ich muss nur noch Mashas Leiche begraben. Wenn ich das getan habe, werde ich zur Bombenabwurfstelle gehen und das Nachwachsen einleiten. Vielleicht wird eines Tages ein neuer Hain erblühen - ein Hain erfüllt mit dem Geist meines Kindes und denen der gefallenen jungen Nachtelfen.\n\nIch habe von einem Blutelf namens Furien in Desolace gehört, der nach gleichgesinnten Abenteurern sucht. Vielleicht solltet Ihr ihn aufsuchen.\n\nLebt wohl, <Freund/Freundin>, ich werde Euch nie vergessen.", progress = nil, completion = "&lt;Furien stöhnt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26135] = {title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", objective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", progress = nil, completion = "Diener des alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n&lt;Name&gt;, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", rewards = "Volarens HandschützerPerlmuttschiftungAuf Euch wartet eine dieser Belohnungen:\n\nSiegelring von Quel'Dormir\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26137] = {title = "Auf der Suche nach den Jungs", objective = "Reist ins Sumpfland und sprecht mit Gebirgsjäger Rharen nahe Dun Algaz.", description = "Ihr habt sicher gesehen, wie stark der Loch mittlerweile geschädigt ist. Die Schäden dehnen sich leider sogar noch weiter aus. Das ganze Wasser musste ja irgendwo hin, und es floss hinunter ins Sumpfland.\n\nDa unten unterstützen uns viele mutige Zwerge. Sie brauchen Vorräte. Aus diesem Grund habe ich zwei meiner Gebirgsjäger mit einem Fass voller Bier auf den Weg ins Sumpfland geschickt.\n\nSeit sie die Straße nach Dun Algaz erreicht haben, gab es keine Nachricht mehr von ihnen. Würdet Ihr nachsehen, ob es ihnen gut geht?", progress = nil, completion = "Gut, Euch zu sehen, &lt;Klasse&gt;.\n\nSturmlanze schickt Euch? Wegen des Fasses? Oh Mann...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26138] = {title = "Ferilon Laubkind", objective = "Findet Ferilon Laubkind im Hain des Sumpfhüters.Eine Gruppe von Nachtelfen hat sich im Sumpfland niedergelassen. Ein paar von ihnen sind aus Kalimdor eingetroffen, um das Land hier zu untersuchen, sich die Pflanzen anzusehen und all so etwas.\n\nEiner der Druiden - er heißt Ferilon - kam hier vor einer Weile vorbei. Er war so nett, uns mit den Raptoren zu helfen und erwähnte, dass er Leute braucht, die ihn bei seinen Aufgaben unterstützen.\n\nWenn Ihr Zeit habt, könntet Ihr ihn an einem Ort im Nordosten namens Hain des Sumpfhüters aufsuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Eine Gruppe von Nachtelfen hat sich im Sumpfland niedergelassen. Ein paar von ihnen sind aus Kalimdor eingetroffen, um das Land hier zu untersuchen, sich die Pflanzen anzusehen und all so etwas.\n\nEiner der Druiden - er heißt Ferilon - kam hier vor einer Weile vorbei. Er war so nett, uns mit den Raptoren zu helfen und erwähnte, dass er Leute braucht, die ihn bei seinen Aufgaben unterstützen.\n\nWenn Ihr Zeit habt, könntet Ihr ihn an einem Ort im Nordosten namens Hain des Sumpfhüters aufsuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26139] = {title = "Nach Arathi", objective = "Reist ins Arathihochland und sprecht mit Hauptmann Nials in der Zuflucht.", description = "Geht vor und warnt die andere Seite des Übergangs, <Name>.\n\nHinter der Brücke im Norden werdet Ihr die Zuflucht finden, die Festung der Allianz in Arathi. Sagt Hauptmann Nials, er solle sich vor den Hundesöhnen des Schattenhammers in Acht nehmen.", progress = nil, completion = "Ich sollte Thargas wohl dafür danken, dass er mir einen so mutigen Helden geschickt hat.\n\nVielleicht wollte er aber auch nur alles allein aufräumen. In jedem Fall könnt Ihr hier viel für die Allianz tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26140] = {title = "Mit dem Ahnen reden", objective = "Bringt das Gehirn des Unergründlichen zu L'ghorek im Cerebrillum in L'ghorek in Vashj'ir.", description = "Setzt den toten Gnadenlosen auf Euren Kopf und gebt Euch als einer ihrer Sklaven aus.\n\nBetretet L'ghorek. Kommuniziert mit dem Ahnen.", progress = "ICH SPÜRE... ETWAS. KOMMT NÄHER...", completion = "WEISE VON… EUREM ERUNAK… EUCH... DAS… GEHIRN DES GESICHTSLOSEN… VERWENDEN ZU LASSEN. ICH SEHE… EUCH JETZT.\n\nICH WERDE STERBEN. ES IST NICHT… AUFZUHALTEN.\n\nABER… IHR WERDET MIR… ERST HELFEN, DIESE… PARASITEN ZU BESEITIGEN.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26141] = {title = "Runensteine der Bindung", objective = "Sammelt 7 Runensteine der Bindung.", description = "AUF DER ANDEREN… SEITE MEINES… RAUMS SIND… KANDIDATEN FÜR DEN AUFSTIEG.\n\nWIR BENÖTIGEN… IHRE RUNENSTEINE DER BINDUNG… UM EINEN... WEG ZU FINDEN... EINEN GEBUNDENEN ELEMENTAR... ZU KONTROLLIEREN.", progress = "HABT… IHR ALLES… WAS… WIR BRAUCHEN?", completion = "WIR WERDEN… DIESE… RUNENSTEINE NUTZEN… DAMIT IHR… VON EINEM… DER WASSERELEMENTARE... BESITZ ERGREIFEN KÖNNT.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26142] = {title = "Aufstieg verboten!", objective = "Zerstört 5 uralte Leitungen.", description = "UM IHRE… RITUALE DES AUFSTIEGS… AUFZUHALTEN… MÜSST IHR DIE… URALTEN LEITUNGEN ZERSTÖREN.\n\nSIE VERWENDEN… DIE LEITUNGEN, UM… MEINE ENERGIEN… ABZUZAPFEN UND… ASZENDENTEN ZU ERSCHAFFEN.\n\nEIN KAMPF MIT… NEPTULON IST UNVERMEIDBAR. DER SCHATTENHAMMER… DARF DIESE WESEN... NICHT HABEN.", progress = nil, completion = "IHR AUFSTIEG… IST ZU ENDE!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26143] = {title = "Alles, was aufsteigt", objective = "Tötet Hallazeal den Aufgestiegenen.", description = "<Die Stimme des Ahnen drückt gegen Euren Geist.>\n\nJETZT, DA IHR… DIE ENERGIEN… DER GETREUEN… GESTOHLEN HABT… BETRETET DEN TEMPEL UND… VERNICHTET… HALLAZEAL DEN AUFGESTIEGENEN!", progress = nil, completion = "IHR HABT… MIR UND DEM… GEZEITENJÄGER EINEN… GROSSEN DIENST ERWIESEN.", rewards = "Brustschutz der vergangenen GottheitArmschienen des bezwungenen GottesAuf Euch wartet eine dieser Belohnungen:\n\nAbgefüllte NeuronenHallazeals Untergang\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26144] = {title = "Gefangene", objective = "Rettet 5 Gefangene der Allianz.", description = "Der Kultist des Schattenhammers hat diesen Schlüssel fallenlassen. Benutzt ihn, um die Gefangenen der Allianz in den Käfigen in L'ghorek zu befreien.\n\nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Draenischer KettensprengerGeistschlitzer aus GnomereganGilnearischer SchneiderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26145] = {title = "Die Bedrohung durch die Troggs", objective = "Sammelt 8 Troggsteinzähne.", description = "<Klasse>, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Eisenschmiede zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über die Stadt hier zu wachen und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir acht Troggsteinzähne als Beweis.", progress = "Könnt Ihr mir acht Troggsteinzähne zeigen? Wenn nicht, dann habt Ihr immer noch etwas zu erledigen, <Name>.", completion = "Ich bin ziemlich beeindruckt, &lt;Name&gt;. Ihr habt dem Volk der Zwerge einen großen Dienst erwiesen, indem Ihr unser Land verteidigt habt. Selbst König Magni Bronzebart wäre stolz auf Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26146] = {title = "Verteidigung der Länder des Königs", objective = "Tötet 12 Splittersteintroggs oder Späher der Splittersteintroggs.", description = "Wir müssen den Loch beschützen, <Name>! Da so viele Soldaten des Königs tapfer auf entlegenen Schlachtfeldern kämpfen, wurden wir an der Heimatfront überrannt. Troggs schlüpfen aus jeder Spalte! Der Troggbefall stellt die größte Bedrohung für Eisenschmiede dar.\n\nWir brauchen Euch, <tapferer Abenteurer/tapfere Abenteurerin>, damit Ihr Euch vorwagt, um dieser Bedrohung durch die Troggs ein Ende zu bereiten. Tötet zwölf Splittersteintroggs und kommt zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Ihr habt verblüffende Tapferkeit auf dem Schlachtfeld gezeigt. Wir werden den Krieg gegen die Troggs durch solche Anstrengungen gewinnen. Ihr habt König Magni gute Dienste geleistet.", rewards = "SteinsplitterstabGamaschen des verblüffenden MutsSteinstampferIhr bekommt:\n\nPikanter Dalarankäse"}
MultiLanguageQuestData['de'][26147] = {title = "Größer und ekliger", objective = "Tötet 8 Schamanen der Splittersteintroggs und 8 Knochenknacker der Splittersteintroggs.", description = "Die Gebirgsjäger haben mir erzählt, dass Ihr recht mutig und fähig seid, <Name>. <Ein/Eine:r> <Volk> wie Ihr ist hier vonnöten. Das Problem mit den Troggs wird nicht besser. Unsere Reservekräfte wurden an die Front gerufen und nun sind wir hier alleine. Doch jetzt, wo <ein erfahrener/eine erfahrene:c> <Klasse> hier ist, können wir sicher mehr erreichen.\n\nGeht und tötet acht Schamanen der Splittersteintroggs und acht Knochenknacker der Splittersteintroggs. Ihr könnt sie in und in der Nähe der Höhle im südlichen Teil der Berge finden.\n\nNun lasst uns sehen, ob Ihr Eurem Ruf als Trogg-Schreck gerecht werdet.", progress = nil, completion = "Ich war mich sicher, als ich Euch gesehen habe, &lt;Name&gt;: Ihr würdet Eisenschmiede stolz machen. Ihr habt unserem Volk gut gedient. Ich salutiere vor Euch, &lt;Name&gt;.", rewards = "Stiefel des TroggtötersKnochenknackerarmschienenGebirgsjägergürtelIhr bekommt:\n\nGrober Wetzstein"}
MultiLanguageQuestData['de'][26148] = {title = "Ein Entscheidungsschlag", objective = "Tötet Grawmug.", description = "Die Bestien in Loch Modan scheinen einem Häutpling namens Grawmug zu folgen. Er ist der größte aller Troggs und hält sich tief in der Dunkelheit der Höhlen nördlich von hier auf.\n\nWenn Ihr meint, Ihr seid einer solchen Aufgabe gerecht, so würde ich Euch gerne mit der Ermordung Grawmugs beauftragen.", progress = nil, completion = "Ausgezeichnet, &lt;Name&gt;! Ihr habt wieder Hoffnung nach Loch Modan gebracht. Durch den Tod Grawmugs haben wir bessere Aussichten darauf, die Troggs aus diesen Landen zu vertreiben.", rewards = "Ungebundene GamaschenGürtel des Tals der KönigeRugelfuß' ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26149] = {title = "Gefangene", objective = "Rettet 5 Gefangene der Horde.", description = "Der Kultist des Schattenhammers hat diesen Schlüssel fallenlassen. Benutzt ihn, um die Gefangenen der Horde in den Käfigen in L'ghorek zu befreien.\n\nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "GrimmhornklopferRitualklinge der DunkelspeereGoblinentbeinerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26150] = {title = "Ein Besuch bei Maybell", objective = "Sprecht mit Maybell Maclure in den Weinbergen der Maclures in den Wäldern von Elwynn.", description = "Ihr scheint mir vom hilfsbereiten Schlag zu sein, <Name>. Würdet Ihr einem alten Mann einen Gefallen tun?\n\nDas letzte Mal, als ich drüben in den Weinbergen der Maclures war, habe ich Maybell in ihrer Hütte weinen hören. Wärt Ihr so nett und würdet nach ihr sehen? Ich mache mir Sorgen um sie.", progress = nil, completion = "William hat Euch geschickt? Gesegnet sei seine Seele. Mir… mir geht es gut. Es ist nur… Nun ja…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26152] = {title = "Gesucht: James Clark", objective = "Tötet James Clark und nehmt James Clarks Kopf.", description = "Auf Geheiß der Armee von Sturmwind wurde ein Kopfgeld auf James Clark ausgesetzt.\n\nClark wird gesucht wegen Raubes, Einbruchs, Brandstiftung und Mordes. Er wird auch verdächtigt, Brackbrunns preisgekröntes Schwein Prinzessin entführt zu haben und versteckt zu halten.\n\nJames Clark wurde zuletzt auf dem Weg zum Holzfällerlager des Osttals gesehen.\n\nFührt James Clark der Gerechtigkeit zu und meldet Euch dann bei Marschall McCree im Holzfällerlager des Osttals.", progress = "Wollt Ihr ein Kopfgeld einfordern?", completion = "Und wieder wurde der Gerechtigkeit Genüge getan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26153] = {title = "Pennys Kürbiskuchen", objective = "Sammelt 6 Sturmwindkürbisse und bringt sie Robby Flay in Sturmwind.", description = "Meine Tochter liebt Kürbispuffer, aber hier in Elwynn gab es dieses Jahr wegen des kalten Winters nur wenig Kürbisse. Ich habe aber von einem Kürbisfeld bei Sturmwind gehört, auf dem die Früchte nun reif sein sollen. Erntet für mich ein paar reife Kürbisse und ich werde Euch meinen Dank beweisen.", progress = "Habt Ihr die Kürbisse geerntet?", completion = "Gute Arbeit, &lt;Name&gt;! Penny wird morgen zum Frühstück eine tolle Überraschung bekommen!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26154] = {title = "Schattenkammerjäger", objective = "Ergreift Besitz von einem gebundenen Strom und tötet dann 50 Zwielichtverehrer und 10 gesichtslose Aufseher.", description = "NUN… NEHMT DEN… ABGESTIMMTEN RUNENSTEIN… UND BENUTZT IHN… UM VON EINEM… GEBUNDENEN STROM… IM MITTLEREN TEMPEL… BESITZ ZU ERGREIFEN. SIE WERDEN… EUCH… IGNORIEREN. KEINER WIRD… EUCH BEMERKEN.\n\nNUTZT... DIE MACHT DES ELEMENTARS… UM ZWIELICHTVEREHRER... UND IHRE GESICHTSLOSEN AUFSEHER... ZU TÖTEN.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26157] = {title = "Kasim Sharim", objective = "Meldet Euch bei Kasim Sharim im hinteren Teil der Schlangenschlinge in den Verwüsteten Landen.", description = "Ich möchte, dass Ihr eine Nachricht für mich überbringt.\n\nKasim Sharim ist ein alter Blutmagier, der viel über die Dämonen in den Verwüsteten Landen weiß. Man sieht es ihm zwar nicht an, aber er ist recht alt und sehr mächtig... aber auch ein wenig exzentrisch. In letzter Zeit hält er sich meistens im hinteren Teil der Schlangenschlinge auf, einer Höhle in der Nähe des Ortes, an dem ihr die Kultisten getötet habt.\n\nBitte überbringt ihm diese Nachricht. Er wird ihre Bedeutung verstehen.", progress = "Ich kenne Euch nicht.", completion = "Hah! Ihr Einfaltspinsel aus Nethergarde seid immer zwei Schritte hinter mir, dabei bin ich längst nicht so schnell wie früher.\n\nIch brauche Mahars Notiz nicht. Ich weiß auch so, was vorgeht. Was glaubt Ihr, weshalb ich mich so tief in eine Höhle zurückgezogen habe? Ein starker &lt;Volk&gt; wie Ihr wäre mir allerdings eine Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26158] = {title = "Stimmt den Blutstein ab", objective = "Stellt euch auf die Blutsteinteleporter in der Schlangenschlinge ein.", description = "Haben die Kämpfe auf dem Weg durch die Höhle Spaß gemacht? Zugegebenermaßen habe ich nicht die... praktischste Stelle für meine Studien ausgesucht, vor allem nicht für vorbeiziehende <Abenteurer/Abenteuerinnen>, die nach Belieben kommen und gehen wollen.\n\nAllerdings kann ich Euch an meine Blutsteinteleporter anpassen. Legt einfach Eure Hände auf den Stein in der hinteren Ecke, dann werdet Ihr vor die Höhle versetzt. Benutzt den Stein draußen, um wieder hinein zu kommen!", progress = nil, completion = "Hervorragend! Ihr habt die einfachste aller Aufgaben bewältigt, ohne zu sterben. Das hätten wir erledigt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26159] = {title = "Der erste Schritt", objective = "Beschafft 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", description = "Wie jeder gute Blutmagier wirke ich meine Magie mit Blut. Jedes Blut ist anders. In den Verwüsteten Landen gibt es mehrere nützliche Geschmacksrichtungen, wenn man weiß, wo man suchen muss.\n\nFür unsere Zwecke? Basilisken und Hyänen zu gleichen Teilen. Wir werden viel Blut brauchen. Geht nach Westen ins Herz der Verwüsteten Lande. Und vergesst nicht, den Teleporter zu benutzen!", progress = "Habt Ihr es?", completion = "&lt;Kasim betrachtet das Blut gierig.&gt;\n\nMehr als genug und immer noch warm! Dann lasst uns das Ritual beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26160] = {title = "Blutritual", objective = "Sprecht mit Kasim Sharim, um das Blutritual einzuleiten.", description = "Ihr wollt wahrscheinlich wissen, was wir tun. Hier ist die Kurzfassung - eine Fassung, in der ich Experte bin:\n\nDie Kultisten der Schattenanbeter wollen den Dämon Razelikh beschwören und in die Verwüsteten Lande holen. Das können wir nicht zulassen. Deshalb werden wir ihn selbst beschwören und umbringen. Das klingt leichter als es ist...\n\nLasst mich wissen, wenn Ihr für das Blutritual bereit seid und tretet dann zurück.", progress = nil, completion = "Das Blutritual war ein Erfolg. Ich weiß genau, wohin wir als Nächstes gehen müssen.\n\nTut mir Leid, falsche Formulierung. Ich wollte sagen, ich weiß, wohin IHR als Nächstes gehen müsst...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26161] = {title = "Nicht irgendeine Leiche", objective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", description = "Wir brauchen Loramus Thalipedes, den Dämonenjäger. Er kennt Razelikhs wahren Namen und wie Ihr wisst, braucht man den Namen eines Dämons, um Macht über ihn zu gewinnen. Das Problem ist nur, dass Loramus getötet und seine Leiche zerrissen wurde.\n\nWenn Ihr mir die Teile bringt, lässt sich noch etwas ausrichten. Alle drei Teile befinden sich im Westen... die Schreckensfelsoger verstecken sie in ihren Höhlen. Beeilt Euch, denn ebenso wie Grimeo, schuldet mir auch Loramus etwas...", progress = "Vertraut mir... was Loramus zugestoßen ist, lässt sich richten. Die Grenzen der Blutmagie sind noch undefiniert.", completion = "Verstehe... ja, damit kann ich arbeiten.\n\n&lt;Kasim betrachtet den Kopf des Nachtelfen.&gt;\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich auf unser Wiedersehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26162] = {title = "Der Altar der Stürme", objective = "Bringt Loramus' Leichnam zum Altar der Stürme und beschützt ihn während des Rituals.", description = "Auf den Klippen westlich von hier steht ein mächtiger Altar. Ein mächtiger, DÄMONISCHER Altar, der von Kultisten bewacht wird, aber trotzdem mächtig ist. Wenn Ihr ihn erreichen könnt, dann wäret Ihr in der Lage, Loramus zu uns zurückzubringen.\n\nDer Altar wird sich Euch wahrscheinlich widersetzen, deshalb müsst Ihr Loramus' Leichnam bis zur Vollendung des Rituals beschützen. Bringt den Dämonenjäger anschließend zu mir zurück.", progress = nil, completion = "Ihr... Ihr Narr! Was habt Ihr getan?", rewards = "Stiefel der dämonischen WiederbelebungLoramus' HandschuheArmschienen des dämonischen AltarsStiefel der abgeschlossenen RitualeHelm der StürmeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26163] = {title = "Die Zeit ist knapp", objective = "Bringt die disharmonische Rune zu Behüter Grimeo am Dunklen Portal in den Verwüsteten Landen.", description = "Razelikh will in die Verwüsteten Lande zurückkehren und Azeroth mit seinen Dämonen überrennen. Er bereitet bereits die Beschwörung der Legionen vor, die uns vernichten sollen. Mit diesen drei Amuletten können wir ihn zwar beschwören... aber nicht zerstören.\n\n<Der Gnom zeichnet rasch eine Rune in die Luft und reicht sie Euch.>\n\nBringt dies zu Grimeo am Dunklen Portal im Südosten. Er wird Euch führen. Beeilt Euch! Eure Zeit ist knapp bemessen! So wie meine Größe!", progress = "Kenne ich Euch, guter <Volk>?", completion = "Nein, nein, nein... nicht wieder Kasim! Das ist Irrsinn!\n\nBitte bleibt ruhig. Wisst Ihr, wie schnell man mich aus der Wache werfen wird, wenn mein Kommandant erfährt, dass ich immer noch für den Kurzen arbeite?\n\n&lt;Ihr gebt Grimeo die Rune. Er presst sie gegen seine Brust, schließt die Augen und seufzt.&gt;\n\nWie ich sehe, sagt Ihr die Wahrheit. Lasst uns rasch beginnen, damit es noch rascher vorüber ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26164] = {title = "Der verkohlte Granit des Dunklen Portals", objective = "Besorgt 24 verkohlte Granitsplitter.", description = "Kasim möchte, dass Ihr Granitsplitter von den Felsen rund um das Dunkle Portal sammelt. Ich weiß nicht, was er mit den Felsen vorhat, aber ich habe einen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal", progress = "Bitte sprecht leise.", completion = "Hoffentlich ist es das, was der Gnom wollte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26165] = {title = "Das abscheuliche Blut der Dämonen", objective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", description = "Sharim will Dämonenblut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt, in reichlichen Mengen.", progress = "Ihh, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Kasims Bitte einmal abgesehen, bin ich sicher, dass mein Wachkommandant für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26166] = {title = "Verbesserung des Steins", objective = "Bringt Grimeos Paket zu Kasim Sharim in der Schlangenschlinge in den Verwüsteten Landen.", description = "<Grimeo packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was der Gnom von uns verlangt hat. Wenn Ihr ihn seht, sagt ihm bitte, dass meine Schuld mit dieser Aufgabe beglichen ist. Ich werde seine Bitten nicht länger erfüllen.", progress = "Ihr seid zurückgekehrt, <Klasse>.", completion = "Das wird genügen. Wenn Ihr Grimeo noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Jedoch ist seine Schuld noch nicht getilgt. Ich werde mich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange ich arbeite, habe ich eine andere Aufgabe, die Ihr erledigen könnt.\n\nWas seht Ihr mich so böse an? Diese Aufgabe wird Euch Spaß machen... es geht um das Sammeln von Körperteilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26167] = {title = "Das Amulett von Allistarj", objective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", description = "Um unseren Dämon zu beschwören, brauchen wir drei Amulette. Das erste ist das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in dieser Höhle eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.\n\n<Kasim konzentriert sich einen Moment.>\n\nDas Amulett befindet sich nahe des Eingangs. Ich würde vorschlagen, den Teleporter zu benutzen.", progress = "Allistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "&lt;Kasim untersucht das Amulett.&gt;\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26168] = {title = "Das Amulett von Sevine", objective = "Besorgt das Amulett von Sevine von Salzflopper nahe der Havarieküste in den Verwüsteten Landen.", description = "Das zweite Amulett, Sevines Amulett, befindet sich weit im Süden in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nBringt mir ihr Amulett, zusammen mit dem Rest.", progress = "Sevines Amulett - zusammen mit den anderen können wir den Entweiher beschwören.", completion = "&lt;Kasim wiegt das Amulett in der Hand.&gt;\n\nEin Hexenmeister... und zwar ein mächtiger. Ich werde das hier behalten, bis die Zeit reif ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26169] = {title = "Das Amulett von Grol", objective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", description = "Grol... der Oger.\n\n<Kasim lacht.>\n\nGrols Leichnam ruht wohl nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "&lt;Kasim umklammert das dritte Amulett.&gt;\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis wir bereit sind, fortzufahren.", rewards = "HavarieküstenumhangStiefel des OgerjägersSchlangenwindungenStärkender GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26170] = {title = "Das letzte Ritual", objective = "Sprecht mit Kasim Sharim, um an seinem Ritual teilzunehmen.", description = "Das Messer ist fertig. Loramus ist anwesend und weiß, was er zu tun hat. Ich werde nun die drei Amulette nehmen und ihre Verzauberung nutzen, um Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, zu verschaffen.\n\nIch bin bereit, dieses Ritual an Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr beide ebenfalls bereit seid.", progress = nil, completion = "Anscheinend sind wir jetzt bereit, unserem Dämon entgegenzutreten, &lt;Name&gt;. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämons: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26171] = {title = "Ihr seid Rakh'likh, Dämon", objective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", description = "<Held/Heldin>, hört gut zu.\n\nZunächst müssen wir nach Nordwesten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe schicken. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Grimeo, dem Draenei.", progress = nil, completion = "Loramus wiedererweckt? Und dann setzte er den Dämon in seinem eigenen Körper fest.. beim Licht...\n\nIch verstehe. Also hatte Kasim das die ganze Zeit so geplant. Ich hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben.\n\nAh, noch eines! Kasim hat mir eine letzte Anweisung in seiner Rune übermittelt. Anfangs verstand ich sie nicht, aber nach den heutigen Ereignissen ergibt sie wesentlich mehr Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der edlen TatenBand der AufopferungBand des selbstlosen Handelns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26172] = {title = "Auch Blutmagier müssen essen", objective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", description = "Entgegen der landläufigen Vorstellung trinken uralte und mächtige Blutmagier KEIN Blut. Wir essen normale Speisen so wie jeder andere auch - etwas, was in der hintersten Ecke einer feindlichen Kultistenfeste schwer zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind eine praktische Speise, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und meine schwindenden Nahrungsvorräte wieder aufstocken?", progress = "Ich bin so hungrig! Wenn Ihr Euch nicht beeilt, sehe ich mich doch noch gezwungen, meine Reagenzien zu trinken.", completion = "Die sind perfekt, &lt;Name&gt;. Ich werde in den nächsten Tagen gut zu essen haben.", rewards = "AschmähnenarmschienenBefleckter SchulterschutzStiefel der Verwüsteten LandeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26173] = {title = "Rückendeckung", objective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", description = "Der einzige Grund, warum Ihr mich neben Soldaten der Horde stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - wenn auch knapp. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", progress = nil, completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n&lt;Der Kommandant beugt sich vor und beginnt zu flüstern:&gt;\n\n&lt;Volk&gt;... Wenn Ihr noch interessiert seid, ich habe da eine kleine Aufgabe für Euch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26174] = {title = "Nachhut", objective = "Untersucht die Pläne der Horde am Dunklen Portal, ohne erwischt zu werden.", description = "<Wachkommandant Reldorn Netherschwund schlägt einen verschwörerischen Ton an.>\n\nIch habe Befehle von... oben... für die Ihr bestens geeignet seid. Ich habe gesehen, dass die Horde regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", progress = "Habt Ihr einen Blick auf die Pläne erhaschen können, <Name>?", completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n&lt;Netherschwund hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.&gt;\n\nHmpf... ziemlich harmloses Zeugs. Entweder ist die Horde dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", rewards = "Harmlose ArmschienenHandschuhe der närrischen UnschuldNethergardenumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26175] = {title = "Surwich", objective = "Meldet Euch bei Bürgermeister Carl Connisport in Surwich in den Verwüsteten Landen.", description = "Abgesehen von dem, was Ihr gesehen habt, ist das Portal überraschend ruhig. Leider kann ich Euch kaum noch Arbeit geben.\n\nWenn Ihr nach Ärger sucht, könntet Ihr es im Fischerdorf der Gilneer im Südwesten versuchen. Surwich, so heißt es, glaube ich.\n\nIch weiß, dass wir eigentlich mit den Gilneern befreundet sein sollten, aber mal ehrlich? Worgen? Es fiel mir schon schwer, mich an die Draenei zu gewöhnen.", progress = nil, completion = "Willkommen in Surwich, &lt;Volk&gt;. Seht Euch ruhig um.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26176] = {title = "Auf nach Thelsamar", objective = "Bringt den Statusbericht von Hauptmann Rugelfuß zu Gebirgsjäger Kadrell in Thelsamar.", description = "Ihr habt uns hier sehr geholfen. Falls Ihr aufbrechen wollt, würde ich Euch gerne bitten, diesen Statusbericht nach Thelsamar zu bringen.\n\nFolgt der Straße in Richtung Norden und Ihr könnt es nicht verfehlen. Der Statusbericht muss zu Gebirgsjäger Kadrell.", progress = "Wie kann ich Euch helfen?", completion = "Gut, dass Ihr Euch um die Troggs gekümmert habt. Dann lasst uns mal den Bericht ansehen und...\n\n...ist das ein Bierfleck?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26177] = {title = "Lust auf Krebs?", objective = "Sammelt 6 Kanalkrebse und bringt sie zu Robby Flay in Sturmwind.", description = "Frische Krabbenbeine waren schon immer eine der Lieblingsspeisen des Königs. Wir hatten in den letzten Wochen viel Erfolg beim Krebsfangen in den Kanälen. Könnt Ihr mir helfen und ein paar für mich fangen? Sie müssen lebendig gefangen werden, tot nützen sie mir nichts - für den König ist nur der frischeste Fang gut genug.", progress = "Ihr müsst schnelle Hände haben! Ich kann kaum glauben, dass Ihr alle Krebse in so kurzer Zeit fangen konntet!", completion = "Diese Krebse sehen toll aus! Ich werde sie säubern und sicherstellen, dass der König von Eurer Hilfe erfährt. Danke!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26178] = {title = "Zukunftsplanungen", objective = "Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau'i im Hafen Moa'ki ab.", description = "Um unser Überleben zu sichern, müssen wir entschlossen gegen die Wolvar vorgehen. Ich mache mir jedoch Sorgen, dass wir in unserem Eifer zu viele von ihnen erschlagen werden.\n\nDie Schneewehenwolvar haben genauso wie wir das Recht zu überleben – also werden wir beide dafür sorgen, dass sie dieses Recht auch bekommen.\n\nWenn er es nicht schon längst getan hat, dann wird Euch Ältester Ko'nani darum bitten, mit den Wolvar fertigzuwerden. Und aus diesem Grund möchte ich auch, dass Ihr ihre Jungen einfangt und sie zu mir bringt, wenn Ihr Euch auf der Lichtung im Norden befindet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26179] = {title = "Die Venture Company", objective = "Tötet 7 Tagelöhner der Venture Co. für Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe.", description = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.\n\nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.", progress = nil, completion = "Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die &lt;Volk&gt; nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26180] = {title = "Vorsteher Zischelspross", objective = "Tötet Vorsteher Zischelspross und nehmt sein Klemmbrett an Euch.", description = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.\n\nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Zischelspross; Ihr findet ihn in der Mine der Venture Co. östlich der Überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", progress = "Bei dem Gedanken an die Abscheulichkeiten, die die Venture Company im Namen des Gewinns geplant haben, koche ich fast über vor Ärger.", completion = "Die Nachricht vom Tod des Bösewichts Zischelspross hat meine Wut etwas abgekühlt. Ich werde seine persönlichen Habseligkeiten durchsehen, um herauszufinden, ob es weitere Informationen über die Zukunftspläne der Venture Company gibt. Vielen Dank für Eure Bemühungen, &lt;Name&gt;.", rewards = "Spurenlose SandalenZerstampfer der GoblinsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26181] = {title = "Rückkehr zur Dämmerbucht", objective = "Sprecht mit Erunak Steinsprecher in der Dämmerbucht in Vashj'ir.", description = "IHR MÜSST ZURÜCK… ZUR… DÄMMERBUCHT. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.\n\nICH STERBE JETZT...", progress = nil, completion = "Willkommen zurück, &lt;Klasse&gt;.\n\nIch habe gespürt, wie L'ghorek starb. Es ist eine Schande, dass so ein fantastisches Wesen nicht mehr unter uns weilt.\n\nWenn wir Neptulon nicht unterstützen, wird uns alle das gleiche Schicksal ereilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26182] = {title = "Rückkehr zur Schattenhöhle", objective = "Sprecht mit Erunak Steinsprecher in der Schattenhöhle in Vashj'ir.", description = "IHR MÜSST ZURÜCK… ZUR… SCHATTENHÖHLE. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.\n\nICH STERBE JETZT...", progress = nil, completion = "Willkommen zurück, &lt;Klasse&gt;.\n\nIch habe gespürt, wie L'ghorek starb. Es ist eine Schande, dass so ein fantastisches Wesen nicht mehr unter uns weilt.\n\nWenn wir Neptulon nicht unterstützen, wird uns alle das gleiche Schicksal ereilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26183] = {title = "Des Königs Apfelwein", objective = "Sammelt 12 saftige Äpfel und bringt sie zu Robby Flay in Sturmwind.", description = "Ich stehe für immer in der Schuld des Königs. Für alles, was er für uns getan hat. Ich kann ihm nicht viel anbieten, aber sein Lieblingsgetränk kann ich ihm brauen! Glücklicherweise wachsen die Zutaten für dieses köstliche Getränk hier in Sturmwind. In jedem Distrikt stehen Apfelbäume. Die Bäume sind zu hoch, um die Äpfel zu pflücken, aber die, die auf den Boden gefallen sind kann man leicht aufsammeln.", progress = "Habt Ihr genug saftige Äpfel finden können?", completion = "Das sind gute Äpfel, &lt;Name&gt;. Ich werde mich gleich daran machen, den Apfelwein zu brauen.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26184] = {title = "Wurmdorns Traum", objective = "Tötet 5 Zerstörer der Verdammniswache, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", description = "Es wird Euch nicht überraschen, dass die meisten Einwohner von Surwich nicht wegen der angenehmen Atmosphäre in die Verwüsteten Lande gekommen sind. Sie kamen, weil sie dem Traum eines idealistischen Druiden folgten: Marl Wurmdorn. Wurmdorn glaubte, dass die Faulende Narbe geheilt werden könnte und versuchte, sie wachsen zu lassen.\n\nEr hat sich wohl geirrt. Er ließ seinen Wald wachsen, aber das Land wird immer noch von Dämonen heimgesucht und sein großer Baum ist verwachsen und knorrig.\n\nTrotzdem hoffe ich noch. Wenn wir uns in den Besudelten Wald begeben und einen Teil der Besudelung entfernen könnten...", progress = nil, completion = "Ihr sagt, all die Dämonen hätten den Baum angebetet?\n\n&lt;Der Bürgermeister seufzt.&gt;\n\nWie ich befürchtet hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26185] = {title = "Rat vom Zirkel des Cenarius", objective = "Meldet Euch bei der cenarischen Beobachterin Shayana in Surwich in den Verwüsteten Landen.", description = "Ich glaube, dass die Besudelung der Verwüsteten Lande ihren Einfluss auf meinen Freund Wurmdorn ausgeweitet hat. Sein Experiment ist gescheitert und sein großer Baum dient nur noch den Dämonen als Versammlungsort.\n\nDer Baum muss fallen und Wurmdorn mit ihm. Sprecht mit der cenarischen Beobachterin auf der anderen Seite des Orts. Sie sollte wissen, was als Nächstes zu tun ist.\n\n<Name>: Die Einwohner von Surwich dürfen nichts von unseren Plänen erfahren. Ihre Stimmung ist schon schlecht genug.", progress = nil, completion = "Es überrascht mich zwar, dass Connisport gewillt ist, seinen Plan umzusetzen, aber es erleichtert mich auch. Ich habe gesehen, wie sich die Dämonen um Maldraz versammeln. Ich teile seine Furcht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26186] = {title = "Dämonisches Gefäß", objective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", description = "Wir müssen Wurmdorns Aufmerksamkeit erregen. Wir brauchen etwas, das ihn aus seiner Trance holt. Etwas, das garantiert funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen worden. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal, ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", progress = "Shayanas Plan ist gut. Habt Ihr das Gefäß, <Name>?", completion = "&lt;Bürgermeister Carl Connisport blickt voller Argwohn auf das Gerät, dass Ihr zusammengesetzt hab.&gt;\n\nNun gut, &lt;Name&gt;. Wir haben, was wir brauchen, um Marls Trance zu durchbrechen und sowohl ihm als auch seinem Experiment ein Ende zu bereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26187] = {title = "Der Fall des Marl Wurmdorn", objective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", description = "Wenn sich herumspricht, was wir getan haben... kann niemand sagen, wie die Bürger von Surwich reagieren werden. Sie klammern sich an Wurmdorns Traum...\n\n...aber trotzdem müssen wir es tun. Nehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", progress = nil, completion = "Danke, &lt;Name&gt;. Ich und die Bürger von Surwich stehen in Eurer Schuld.\n\nNehmt ruhig eins von diesen hier. Wir haben zwar nicht viel, aber wir belohnen gern die, die uns beschützen.", rewards = "WurmdornhandschuheSchulterschutz der getrübten HeilungSchulterstücke von SurwichBrustplatte von SurwichIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26188] = {title = "Mazzranach", objective = "Bringt einen Knochen eines Flachlandpumas zu Maur Regenrufer im Dorf der Bluthufe.", description = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranach. Er erzählte mir von seinen dämonischen roten Augen, seinen rasiermesserscharfen Krallen und seinem giftigen Biss.\n\nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend, wie ihn mein Großvater beschrieben hatte. Ich habe alle Zutaten für das Gegengift, das ich für meine Heilung benötige, zusammen... bis auf einen Knochen eines Flachlandpumas.\n\nIch werde von Minute zu Minute schwächer... bitte helft mir.", progress = "Mein Fieber wird immer schlimmer und ich merke, wie ich langsam in schreckliche Alpträume abgleite... Ich hätte wissen müssen, dass ich keine Bestie bewältigen kann, die selbst mein Großvater nicht besiegen konnte...\n\nHabt Ihr die Zutaten für die Arznei? Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Ah, danke, &lt;Name&gt;. Mit den Dingen, die Ihr mir gebracht habt, kann ich die Arznei herstellen, mit der ich die Ausbreitung der Infektion unterbinden und die Krankheit endgültig heilen kann. Ich schulde Euch meinen lebenslangen Dank.\n\nAber ich werde nie diesen schrillen Schrei vergessen, als sich Mazzranach auf mich stürzte, diese Explosion von Farben, als sich sein Schnabel senkte...\n\nSeid vorsichtig auf Euren Reisen.", rewards = "Gürtel des PräriewolfsSturzfliegerlederhandschuhePumapelzgelenkbänderIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26189] = {title = "Die Grollhauerbedrohung", objective = "Tötet Gorfax Grollhauer und 16 Orcs des Drachenmals im Lager der Grollhauer.", description = "Als wir uns hier oben hin zurückzogen, um den Raptoren zu entgehen, landeten wir genau neben jeder Menge Drachenmalorcs!\n\nIn Menethil habe ich Geschichten gehört - dass die Orcs des Drachenmals noch barbarischer als andere Orcs sind, dass sie schwarze Drachen mit bloßen Händen erwürgen... Ich weiß nicht, was davon stimmt, aber wir können sie nicht in den Hügeln sitzen lassen.\n\nIhr habt genug Mut dafür, <Name>. Geht nach Osten zum Lager der Grollhauer, kümmert Euch um diese Orcs und vor allem um ihren Anführer!", progress = nil, completion = "Schön, dass Ihr heil zurückgekehrt seid, &lt;Name&gt;! Ihr seid ganz schön hart.\n\nIch werde Hauptmann Starkfaust erzählen, wie Ihr die Orcs erledigt habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26190] = {title = "Ein Fischerschmaus", objective = "Bringt 5 gigantische Welse in Euren Besitz und bringt sie zu Robby Flay in Sturmwind.", description = "Wenn der König ein Lieblingsessen hat, dann ist es frischer Wels. Wels ist leicht zuzubereiten aber schwer zu fangen. Genau - hier kommt Ihr ins Spiel. Wir haben in Sturmwind viele gigantische Welse und der Wettbewerb, sie zu fangen, ist sehr intensiv, um es vage zu formulieren. Findet für mich einen Weg, diese feinen Welse für den König zu erhaschen. Ihr werdet am Ufer des Kanals überall in der Stadt Fischer finden. Den Rest des Planes findet Ihr sicherlich selber heraus.", progress = "Konntet Ihr den Fisch klauen?", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde die Welse sofort für den König entschuppen.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26191] = {title = "Der Gipfel unserer Bemühungen", objective = "Jeden Tag treffen weitere Krieger unter dem Befehl Azsharas ein. Bald wird Neptulon der Gezeitenjäger von unseren Vorbereitungen erfahren, aber dann ist es zu spät um aufzuhalten, was wir in Bewegung gesetzt haben. Wir werden zu viele und unsere Verbündeten zu mächtig sein. Der Sieg ist nur eine Frage der Zeit.\n\nIm Namen Azsharas.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBattlemaiden Vision 2 Kill Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26192] = {title = "Auch Waisen mögen Kekse!", objective = "Bringt 4 Säcke Puderzucker zu Robby Flay in Sturmwind.", description = "Die Waisenkinder Sturmwinds werden oft vergessen, aber nicht heute. Der König hat nach einer Sonderlieferung Kekse gefragt, die umgehend zum Waisenhaus geschickt werden soll. Mit der letzten Ladung war ich fast fertig, aber dann ging mir der Puderzucker aus. Könnt Ihr schnell los und mir welchen besorgen? Jeder Gemischtwarenladen in der Stadt oder auch die Gasthäuser sollten welchen haben.", progress = "Konntet Ihr Puderzucker finden?", completion = "Ja, das sollte genug sein, &lt;Name&gt;. Ich freue mich schon auf die glücklichen Gesichter der Waisenkinder.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26193] = {title = "Verteidigung des Abgrunds", objective = "Tötet 15 beliebige Naga beim Wirbelnden Abgrund.", description = "Das Flüstern der Elemente summt in meinen Gedanken, <Name>…\n\nDer Thron der Gezeiten wird belagert!\n\nIch kann nicht tatenlos zusehen, wie die Naga Neptulons Reich bedrohen. Wir müssen einen Weg finden, ihm beizustehen.\n\nKapitän Taylor wird mich in die Tiefen begleiten, wo ich direkt mit Neptulon sprechen kann.\n\nIch muss euch bitten, einen gewalttätigeren Weg einzuschlagen. Lenkt die feindlichen Truppen ab, bis ich sicher am Eingang zum Thron der Gezeiten angelangt bin.\n\nMögen uns die Geister beistehen, <Name>.", progress = nil, completion = "NEIN!\n\nEs ist NICHT vorbei!", rewards = "Beschwerte Treter des U-BootfahrersTuch des SteuermannsAuf Euch wartet eine dieser Belohnungen:\n\nSignet des Ausgucks\n\nDer folgende Zauber wird auf euch gewirkt:\n\nCompletion Event - Alliance\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26194] = {title = "Verteidigung des Abgrunds", objective = "Tötet 15 beliebige Naga beim Wirbelnden Abgrund.", description = "Das Flüstern der Elemente summt in meinen Gedanken, <Name>…\n\nDer Thron der Gezeiten wird belagert!\n\nIch kann nicht tatenlos zusehen, wie die Naga Neptulons Reich bedrohen. Wir müssen einen Weg finden, ihm beizustehen.\n\nNazgrim wird mich in die Tiefen begleiten, wo ich direkt mit Neptulon sprechen kann.\n\nIch muss euch bitten, einen gewalttätigeren Weg einzuschlagen. Lenkt die feindlichen Truppen ab, bis ich sicher am Eingang zum Thron der Gezeiten angelangt bin.\n\nMögen uns die Geister beistehen, <Name>.", progress = nil, completion = "Sie denken vielleicht, sie hätten gewonnen, aber meine Axt und ich sind da anderer Meinung!", rewards = "Beschwerte Treter des U-BootfahrersTuch des SteuermannsAuf Euch wartet eine dieser Belohnungen:\n\nSignet des Ausgucks\n\nDer folgende Zauber wird auf euch gewirkt:\n\nCompletion Event - Horde\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26195] = {title = "Wer hütet den Sumpfhüter", objective = "Sprecht mit Ferilon Laubkind im Hain des Sumpfhüters im Sumpfland.", description = "Der Sumpfhüter war eine lokale Legende. Viele hielten ihn für einen Mythos... den Pflanzenmann, Beschützer des Sumpflands. Die Nachtelfen kamen ausschließlich hierher, um ihn zu finden. Als ihnen das gelang, ließen sie sich im Osten nieder.\n\nEs gibt dort einen ganzen Hain, der über den Sumpfhüter wachen soll, und ich habe gehört, dass er den Nachtelfen Probleme macht. Er ist wütend über die Überflutungen und die Schädigung des Landes.\n\nDas sind gute Elfen. Sie könnten Hilfe von jemandem wie Euch brauchen. Wenn sich die Gelegenheit ergibt, dann sagt dem Anführer der Druiden, was Ihr hier getan habt.", progress = nil, completion = "Willkommen im Hain des Sumpfhüters, &lt;Klasse&gt;. Es freut mich, dass Whelgar von uns erzählt hat.\n\nFür Eure Unterstützung wäre ich Euch sehr dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26196] = {title = "Langzopf der Grimmige", objective = "Bringt Ferilons Überlebenspaket zu Langzopf dem Grimmigen in Dun Modr.", description = "Die Zwerge von Dun Modr kämpfen Tag und Nacht gegen die Dunkeleisenzwerge, die in ihre alte Heimat eingedrungen sind. Wir können es zwar unseren Wächtern nicht erlauben, ihr Leben für sie zu riskieren, aber wir schicken ihnen dringend benötigte Vorräte, damit sie ihre Wache fortsetzen können.\n\nWenn es geht, könntet Ihr Langzopf dem Grimmigen nördlich von hier dieses Paket bringen? Seine Leute können den Inhalt sicherlich gut gebrauchen.", progress = "Oh, was habt Ihr da für mich?", completion = "Vorräte von Ferilon? Guter Mann.\n\nWir haben genug zu essen, aber uns gehen die Kugeln aus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26197] = {title = "Die Zukunft von Gnomeregan", objective = "Trefft Bipsi Frostschleuder in Neu-Tüftlerstadt.", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nBipsi Frostschleuder wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch im Erdgeschoss des großen Gebäudes im Nordosten.", progress = nil, completion = "&lt;Name&gt;, nicht wahr? Schön, Euch endlich kennenzulernen. Während Ihr Euch gesäubert habt, hat mir Nevins Team alles über Eure Flucht aus Gnomeregan erzählt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26198] = {title = "Die Künste eines Magiers", objective = "Ihr müsst Stufe 3 erreichen, um Frostnova zu erlernen. Wenn Ihr den Zauber gelernt habt, wendet ihn zweimal erfolgreich auf eine Trainingsattrappe in Neu-Tüftlerstadt an.", description = "Während Ihr wilde Abenteuer bestreitet und Eure Kräfte steigert, werdet Ihr neue Verbindungen zum Arkanen knüpfen und neue Zauber erhalten.\n\nIhr werdet es sehen. Los, tut es! Zeigt mir, was Ihr lernt! Ich werde hier sein.", progress = nil, completion = "Das habt Ihr schnell gelernt. Ich kann es kaum erwarten, Euch meine anderen Lieblingstricks zu zeigen.", rewards = "Ihr bekommt:\n\nElektrostab"}
MultiLanguageQuestData['de'][26199] = {title = "Die Zukunft von Gnomeregan", objective = "Trefft \"Doc\" Raddreh in Neu-Tüftlerstadt.", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen. \n\n\"Doc\" Raddreh wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch neben der Gebäudeansammlung im Norden.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Name&gt;. Eure Zeit in Gnomeregan hat Euch sicherlich ausreichend Gelegenheit verschafft, Eure Künste auszuüben. Hier ist es etwas sicherer, aber Eure Talente werden nie brach liegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26200] = {title = "Die Künste eines Priesters", objective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Setzt es 5-mal auf Trainingsattrappen in Neu-Tüftlerstadt an.", description = "Wisst Ihr, wenn Ihr in diese verrückte Welt rausgeht und stärker werdet, werdet Ihr neue Kräfte entdecken, die Ihr vorher noch nicht gekannt habt.\n\nZieht einfach los, sammelt neue Erfahrungen und kommt dann wieder und zeigt mir, was Ihr gelernt habt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab der Macht"}
MultiLanguageQuestData['de'][26201] = {title = "Die Macht eines Hexenmeisters", objective = "Ihr müsst Stufe 3 erreichen, um Verderbnis zu erlernen. Wirkt sie dann 5-mal auf eine Trainingsattrappe in Neu-Tüftlerstadt an.", description = "Es überrascht mich überhaupt nicht, dass es <einem Hexenmeister/einer Hexenmeisterin> wie Euch gelungen ist, sich den Weg aus Gnomeregan freizukämpfen. Nur Wenige - selbst hier bei den Gnomen - verstehen den vollen Umfang der Macht, die wir ausüben.\n\nWenn Ihr mächtiger werdet, werdet Ihr Stimmen vernehmen, die Euch ihre Geheimnisse verraten und neue Zauber beibringen.\n\nIch möchte, dass Ihr noch mehr Erfahrungen sammelt. Wenn Ihr etwas Neues gelernt habt, zeigt es mir.", progress = nil, completion = "Wenn Ihr noch mächtiger geworden seid, kehrt zu mir zurück und ich werde Euch neue Zauber und Techniken lehren.", rewards = "Ihr bekommt:\n\nVibromesser"}
MultiLanguageQuestData['de'][26202] = {title = "Die Zukunft von Gnomeregan", objective = "Sucht Alamar Grimm in Neu-Tüftlerstadt auf.", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Wir werden all die Hilfe brauchen, die wir kriegen können, um unsere Heimat von den Troggs und den bestrahlten Gnomen zu befreien. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure, ähem... Künste zu erlernen.\n\nAlamar Grimm hält sich in dem Gebäude westlich von diesem hier auf. Er besitzt Kräfte, die den Euren gleichen. Er wird Euch helfen, Euch einzugewöhnen.", progress = nil, completion = "Ah, wieder einer von Nevins \"geretteten\" Überlebenden, richtig? Wahrscheinlicher ist, dass Ihr ihn vor den Troggs dort unten beschützt habt. Hat seine Stimme gezittert, als er mich erwähnte? Der Mann hat einen gesunden Respekt vor den dämonischen Kräften, die wir kanalisieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26203] = {title = "Die Zukunft von Gnomeregan", objective = "Sucht Ausbildungsoffizier Dampfkurbel in Neu-Tüftlerstadt auf.", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nAusbildungsoffizier Dampfkurbel wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Er erwartet Euch auf dem kleinen Übungsfeld auf der anderen Straßenseite.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26204] = {title = "Die Künste eines Kriegers", objective = "Ihr müsst Stufe 3 erreichen, um Sturmangriff zu erlernen. Wendet dann Sturmangriff an einer Trainingsattrappe in Neu-Tüftlerstadt an.", description = "Lernen ist die beste Methode, um sich zu verbessern. Wenn Ihr mehr lernt, werdet Ihr herausfinden, dass Ihr Dinge tun könnt, die Ihr vorher nicht für möglich gehalten hättet!\n\nLos, sammelt noch mehr Erfahrungen und erlernt eine neue Technik. Kehrt dann zurück und demonstriert sie an einer Trainingsattrappe.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelllichtschwert"}
MultiLanguageQuestData['de'][26205] = {title = "Eine Aufgabe für den Multi-Bot", objective = "Benutzt den GS-9x Multi-Bot, um 5 toxische Geysire auf dem Toxischen Flugplatz zu säubern. Wenn Ihr nahe genug an einen Geysir herangekommen seid, wird der GS-9x Multi-Bot automatisch mit seiner Arbeit beginnen.", description = "Der Multi-Bot wird uns bei all den Aufgaben helfen, die für uns Gnome unangenehm oder gefährlich sind... sollte er funktionieren.\n\nAls Thermadraht seinen Verstrahler am Ende von Operation: Gnomeregan zündete, entstanden giftige Wolken. Giftschlamm begann unter dem alten Flugplatz südlich der Stadt hervorzubrodeln.\n\nWenn wir das nicht unter Kontrolle bekommen, könnte sich die Kontaminierung auf den Rest unseres Landes ausdehnen. Nehmt den Multi-Bot und bringt ihn in die Nähe der Geysire in den grünen Becken auf dem Toxischen Flugplatz. Der Bot sollte automatisch anspringen.", progress = nil, completion = "Wow, ich hätte nie gedacht, dass er auf Anhieb funktionieren würde!\n\nÄh, ich meine, wir hatten Erfolg! Ich frage mich, was man sonst noch mit diesem praktischen kleinen Kerl anfangen kann.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn GS-9x Multibot\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26206] = {title = "Die Zukunft von Gnomeregan", objective = "Sucht Kelsey Stahlfunken in Neu-Tüftlerstadt auf.", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nKelsey Stahlfunken, ein wichtiges Mitglied des Geheimteams Gnomeregan, wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Ihr findet sie nordwestlich von hier im Ratszelt.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Name&gt;. Nevin sagte mir, dass Ihr die Gefahren von Gnomeregan durch Euren Verstand überlebt habt. Das ist genau das, was wir hier oben brauchen. Einen klugen Verstand und eine schnelle Klinge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26207] = {title = "Die Künste eines Schurken", objective = "Ihr müsst Stufe 3 erreichen, um Ausweiden zu erlernen. Sucht dann nach einer Trainingsattrappe in Neu-Tüftlerstadt und übt Ausweiden 3-mal.", description = "Wenn Ihr weitere Erfahrungen macht und als <Schurke/Schurkin> besser werdet, erlernt Ihr neue Fertigkeiten.\n\nEine der wichtigsten ist das Kombinieren von Techniken. Dabei nutzt Ihr Schwächen Eures Gegners aus und erhaltet die Möglichkeit, stärkere Manöver zu einzusetzen.\n\nZieht los, sammelt weitere Erfahrungen und findet heraus, wie man es macht. Wenn Ihr soweit seid, kommt hierher zurück und probiert es aus.", progress = nil, completion = "Es überrascht mich nicht, dass Ihr so schnell lernt. Ich freue mich darauf, Euch weitere Tricks unserer Zunft beizubringen.", rewards = "Ihr bekommt:\n\nTodesstern"}
MultiLanguageQuestData['de'][26208] = {title = "Der Kampf wird fortgesetzt", objective = "Betrachtet den Holo-Tisch vor Hochtüftler Mekkadrill, um mehr über Operation: Gnomeregan zu erfahren.", description = "Die Zwerge von Eisenschmiede nahmen uns freundlicherweise auf, als die Trogginvasion und die Strahlung uns zum ersten Mal zwangen, Gnomeregan zu verlassen. Doch selbst die Hilfsbereitschaft von Freunden, kann das Heimweh nicht unterdrücken.\n\nIch habe um die Hilfe mutiger Gnome und anderer Mitglieder der Allianz gebeten. Gemeinsam wird es uns gelingen, die Kontrolle über Gnomeregan wiederzuerlangen und den Thronräuber Thermadraht ein für alle Mal zu besiegen.\n\nWir konnten mit Operation: Gnomeregan nicht alles erreichen, was wir uns vorgenommen hatten, aber Thermadraht ist auf der Flucht und wir sind unserer Heimat einen Schritt näher.", progress = "Thermadrahts Untergang ist gewiss, aber dieser Irradiator hat ihm eine Atempause verschafft.", completion = "Im Moment wagen sich nur die Teams von S.I.C.H.E.R. hinunter in die Stadt, um nach Überlebenden zu suchen. Währenddessen hat Thermadraht einen seiner Anhänger, Ritzelstoß, ausgesandt, um uns abzulenken und sich selbst Zeit zu verschaffen, sich einzugraben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26209] = {title = "Der Mordfall war der Fall, den sie mir gaben", objective = "Sprecht mit den verschiedenen Obdachlosen, die auf Jansens Hof leben, um Hinweise über die Brauenwirbelmorde zu sammeln.", description = "So sieht's aus, <Junge/Mädchen>, wir haben es mit einem ausgewachsenen Mordfall zu tun. Doppelter Homizid... Einfacher Pferd... izit.\n\nUnd was noch schlimmer ist, wir befinden uns hier in Westfall. Hier kann man mit einem einzigen Steinwurf haufenweise Landstreicher erwischen, die ein Motiv gehabt hätten, die Leute (und das Pferd) um die Ecke zu bringen.\n\nIch habe keine Ahnung, wer es war und ich bin ganz bestimmt nicht gerne hier in diesem Loch, um den Tod von ein paar Landbesetzern aufzuklären, aber ich möchte verdammt sein, wenn ich den Täter nicht dingfest machen kann. Ihr wollt helfen? Dann sprecht mit den Landstreichern. Die Vagabunden... kriegen alles mit.", progress = "Schon was herausgefunden?", completion = "Gnolle und Murlocs? Reiner Pferdemist, mein Junge! Das waren keine Gnolle oder Murlocs. Ich habe gesehen, was Gnolle und Murlocs mit ihren Opfern machen, und so ... sieht das nicht aus. Zu hübsch. Zu... perfekt.\n\nAußerdem haben die Brauenwirbels fünf Jahre lang auf diesem Gehöft gehockt. Nein, wer auch immer sie umgebracht hat, hatte einen Grund. Das hier ist Mord, ganz einfach, und wir werden der Sache auf den Grund gehen...", rewards = "PferdetötermantelAbsperrbandWickel des TatortermittlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26210] = {title = "Gammerita, Alter!", objective = "Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt.\n\nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.", description = "Yo! Da is ne Schildkröte da draußen, die nicht wie die anderen is'. Das is' die Gammerita, Anführerin der Salzwasserschnappkiefer, 'ne richtig fiese Diebin!\n\nAlter, die hat mir meinen besten Köder geklaut. Einfach so abgebissen, hatse den! Seitdem beißen die Fisch nichmehr so an wie vorher.\n\nFinde Gammerita und hol' mir den Köder aus ihrem Bauch.", progress = "Haste ihn gefunden?", completion = "ALTER! Das ist fantastisch! Mit meinem besten Köder und ohne die Schnappkiefern da, kommen die Fische sicher in Scharen zurück.", rewards = "Katooms MaskeBauchschmerzgürtelSchnappkieferarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nVerlockende Halskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26211] = {title = "Schnappkiefer, Alter!", objective = "Katoom der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Salzwasserschnappkiefer tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", description = "Lasst Euch ja nicht von ihren großen Augen täuschen, Alter! Die Schnappkiefer da sind ne Bedrohung. Ich kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern mir meinen Köder klaut.\n\nTut mir und den Bruchhauern einen Gefallen und bringt sie um, Alter.\n\nBringt sie alle um!", progress = nil, completion = "Mensch Alter! Ich kann Euch nicht genug danken! Hoffentlich ist diese Angelrute hier gut genug als Belohnung.", rewards = "Ihr bekommt:\n\nNat Pagles Extremangler FC-5000"}
MultiLanguageQuestData['de'][26212] = {title = "Lards vergessene Brotzeit", objective = "Lard aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Blutfratzen.", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Blutfratzentroll Lard mit großem Stock geschlagen hat. Lard zurück ins Dorf der Bruchhauer gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", progress = "<Lard streicht sich über seinen riesigen Bauch.>\n\nLard so hungrig.", completion = "&lt;Lard nimmt die riesige Fleischkeule von Euch und stopft sie sich in den Mund.&gt;\n\nErste Sahne! Schön'n Dank.\n\nLard Euch machen tollen Picknickkorb für helfen Lard.", rewards = "Ihr bekommt:\n\nLards besonderer Picknickkorb"}
MultiLanguageQuestData['de'][26213] = {title = "Auf heißer Spur: Der Flusspfotenklan", objective = "Erhaltet den Hinweis der Flusspfotengnolle.", description = "Da wir keine anderen Anhaltspunkte haben, können wir genauso gut auch den Informationen nachgehen, die Ihr erhalten habt.\n\nEs gibt einige Lager der Flusspfotengnolle hier in der Nähe. Macht sie ausfindig und sucht nach Hinweisen. Bringt mir was Ihr finden könnt. Beschränkt Eure Suche auf die Gnolle und die Späher der Flusspfoten.", progress = "Habt Ihr etwas über die Gnolle herausgefunden?", completion = "Soll das so eine Art Witz sein? Ich lache nämlich nicht. Fetzen von rotem Stoff? Was zur Hölle soll das denn heißen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26214] = {title = "Auf der Spur: Murlocs", objective = "Findet den Murlochinweis.", description = "Egal für wie sinnlos ich diese Sache halte, wir müssen allen unseren Anhaltspunkten auf den Grund gehen.\n\nIch möchte, dass Ihr Euch hinaus zur Endlosen Küste begebt und den Murlocs dort ein wenig einheizt. Versucht einen Hinweis oder Informationen aufzuspüren, die etwas Licht in diesen Mordfall bringen können.\n\nKehrt zu mir zurück, falls Ihr Erfolg habt.", progress = "Wie läuft die Murlocjagd?", completion = "Na klasse. Ich glaube, davon habe ich einen ganzen Stapel auf meinem Schreibtisch im Wachhaus. Wir stehen also wieder ganz am Anfang. Was wissen wir? Jemand, der gern Geschichten über die Vergangenheit schreibt hat den Brauenwirbels einen Brief geschickt.\n\nWir stecken anscheinend mitten in einer Geschichts...geschichte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26215] = {title = "Ein Treffen mit Lou Zweischuh", objective = "Sprecht mit Lou Zweischuh auf Brauenwirbels Kürbishof in Westfall.", description = "Anscheinend haben wir hier einen echten Fall, Grünschnabel. Leider wollen die Anwohner offenbar nicht reden und die Anhaltspunkte, die Ihr von den Gnollen und Murlocs gewonnen habt, sind so gut wie wertlos. Wir müssen auf Plan... \"Haltet nach Lou Zweischuh Ausschau\" zurückgreifen.\n\nLou Zweischuh ist ein alter Informant von mir, der sich auf dem alten Kürbishof der Brauenwirbels niedergelassen hat. Geht nach Westen zu dem Gehöft und findet heraus, was Lou weiß.\n\nFalls er Euch irgendwelchen Mumpitz erzählt, sagt ihm, dass Horatio Euch schickt.", progress = nil, completion = "Ganz ehrlich, wir haben einfach keinen Platz mehr für...\n\nHoratio schickt Euch? Na gut... ähm, wie kann ich Euch denn helfen?\n\nEr is' doch nich' hier, oder? Haha, er weiß doch sicher, dass ich mich nich' vor ihm versteckt hab. Hab mich nur für ein Weilchen bedeckt gehalten, versteht Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26219] = {title = "Der Kreis schließt sich", objective = "Geht von der Voldrins Mut aus an Bord der Zange X2 und helft dabei, Dämmerbucht zu sichern.", description = "Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat Ihr Nest in der Dämmerbucht, einer riesigen Unterwasserhöhle am Rand des Abgrunds.\n\nDieses Mal sind wir bereit. Die Gnome haben in Sturmwind eine wahre Schönheit für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.\n\nWenn die Zange X2 an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.", progress = nil, completion = "Gut gemacht, Gefreiter &lt;Name&gt;.\n\nDie Chöhle ist unser, aber die Bestie ist entkommen. Wenn sie ihren chässlichen Kopf wieder zeigt, wir werden sie aus dem Wjasser sprengen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26220] = {title = "Speck macht alles besser", objective = "Schlachtet einige der ausgewachsenen Schweine südlich von Orgrimmar und bringt mir 6 Schweinebäuche. Ich werde hier in der Gasse auf Euch warten.", description = "Eine Armee hungriger Orcs zu füttern ist nie einfach. Wir haben hier glücklicherweise gute Vorräte an Fleisch von ausgewachsenen Schweinen von den Schweinehöfen südlich von Orgrimmar. Tut mir einen Gefallen und schlachtet ein paar dieser Schweine für ihre köstlichen Schweinebäuche. Ich werde sie schneiden und gebratenen Speck für das Frühstück der Truppen vorbereiten.", progress = "Habt Ihr die Schweine schon geschlachtet?", completion = "Gute Arbeit, &lt;Name&gt;. Das wird köstlicher Speck.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26221] = {title = "Der Kreis schließt sich", objective = "Geht von der Höllenjuwel aus an Bord der Verne und helft dabei, die Schattenhöhle zu sichern.", description = "Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat ihr Nest in der Schattenhöhle, einer riesigen Unterwasserhöhle im Wirbelnden Abgrund.\n\nDieses Mal sind wir bereit. Die Goblins haben sich als wertvolle Verbündete erwiesen und im Bilgewasserhafen eine bösartige Maschine für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.\n\nWenn die Verne an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;.\n\nDieses glitschige Vieh ist entkommen! Ich werde ein paar Verbesserungen vornehmen. Nächstes Mal hat es nicht so viel Glück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26222] = {title = "Verteilte Teile", objective = "Bringt 7 Ersatzteile zu Ingenieur Schleiffunke in Neu-Tüftlerstadt.", description = "Es gibt so viel zu tun und so wenige Gnome, die in der Lage sind, mir zu helfen! Der Hochtüftler hat mich gebeten, einige alte Bots und Teile der Operation: Gnomeregan auszuschlachten. Mit ein wenig Glück kann ich eine neue Reihe Multi-Bots demnächst in der Praxis testen!\n\nHättet Ihr vielleicht Zeit, um mir zu helfen? Es liegen alle möglichen Teile hier herum. Hebt alles auf, was Ihr findet, und bringt es mir. Wer weiß, was sich davon als nützlich erweist!", progress = "Habt Ihr die Teile bekommen?", completion = "Die sind phantastisch! Mal sehen, was sich daraus basteln lässt. Hättet Ihr Interesse daran, den Prototyp zu testen, wenn ich fertig bin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26223] = {title = "Die Pirsch auf die Pirscher", objective = "Tötet 8 Silbermähnenpirscher.", description = "Viele mutige Trolle sind in der Wildnis von Hinterland verlorengegangen. Die Silbermähnenwölfe sind unseren Jägern die größte Gefahr. Sie lauern versteckt zwischen den Büschen und der Landschaft und greifen an, wenn es eine gute Gelegenheit gibt.\n\nWildheit dieser Art kann nicht ungestraft davonkommen!\n\nIhr müsst denken wie ein Silbermähnenwolf. Ihr müsst ihnen auflauern. Ihr müsst sie alle töten!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Die Bruchhauer sind für Eure Hilfe sehr dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26224] = {title = "Jagt die Wilden", objective = "Tötet 10 Wilde Eulenbestien.", description = "Unter all den bösartigen Tieren der Wildnis des Hinterlandes, sind auch die Eulenbestien zu finden. Schon so manche gute Krieger der Bruchhauer verloren wir an die grausamen Krallen und die Schnäbel der Biester.\n\nTötet jede wilde Eulenbestie, die Ihr finden könnt, <Volk>. Kehrt zu mir zurück, sobald Ihr von dem Blutbad genug habt. Euer Beitrag wird dann genau gewogen, abgemessen und bewertet.", progress = nil, completion = "Ihr habt Euch als ein wahrer Verbündeter der Bruchhauer erwiesen, &lt;Name&gt;. Gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26225] = {title = "Pupellyverbos' Portwein", objective = "Sammelt 12 Flaschen Pupellyverbos' Portwein.", description = "Ihr da! Wusstet Ihr, dass am Strand nördlich von hier dutzende Flaschen, wenn nicht hunderte Flaschen feinen Weins angeschwemmt wurden?\n\n...nun, jetzt wisst Ihr es!\n\nIch würde so viele nehmen, wie ich mit beiden Armen packen kann, wenn die Schildkröten nicht immer hinter mir her wären. Ich könnte schwören, sie wollen mein Blut!\n\nDa bezahle ich Euch doch lieber. Bringt mir 12 Flaschen Pupellyverbos' Portwein und ich werde ihn Euch \"abkaufen\", <Klasse>.", progress = "Habt Ihr zwölf Flaschen? Zählen kann ich, keine Sorge!", completion = "Wunderbar. Ich wüsste nicht, wo ich das Zeug herkriegen würde, wenn nicht immer wieder betrunkene Menschen mit ihren Schiffen aufliefen.\n\nNormalerweise würde ich auch erstmal mit Euch feilschen, aber Ihr habt Glück, denn ich kann es kaum erwarten, mir ein Schlückchen zu genehmigen. Prost!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26226] = {title = "Flusskrebs à la Créole", objective = "Fangt 10 schlammige Flusskrebse in Orgrimmar und bringt die Krustentiere zu Marogg, wenn Ihr fertig seid.", description = "Um Orgrimmar herum befinden sich mehrere kleine Seen. In den Seen wimmelt es jedes Jahr von Flusskrebsen. Hier kommt Ihr ins Spiel, <Name>. Ihr müsst für mich diese köstlichen Krustentiere fangen und sie mir bringen, wenn Ihr fertig seid. Wenn Ihr erfolgreich seid, wird unsere Armee heute abend ein Festmahl genießen.", progress = "Konntet Ihr ein paar Flusskrebse fangen?", completion = "Uff, gerne gekocht habe ich diese schleimigen Dinger nie. Danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26227] = {title = "Achtung, die Frucht beißt zurück!", objective = "Sammelt 8 Kaktusfeigen und bringt sie zu Marogg in Orgrimmar.", description = "Manchmal wollen unsere Streitkräfte auch etwas Süßes. Ich geben ihnen nicht immer, was sie wollen, aber heute werde ich eine Ausnahme machen. Sicherlich habt Ihr schon die einheimischen Kakteen gesehen, die in Orgrimmar wachsen. Die Kakteen tragen eine sehr leckere Delikatesse, die Kaktusfeigenfrucht. Das Problem ist, dass die Frucht voller Kaktusnadeln ist! Passt auf Eure Hände auf und bringt mir ein paar Früchte.", progress = "Konntet Ihr genug Früchte finden?", completion = "Lasst mich Eure Hände sehen... aha! Ihr seid beim Pflücken dieser Frucht auch nicht besser als ich!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26228] = {title = "Wie die Made im Speck", objective = "Benutzt Lou Zweischuhs altes Haus am Ende des Jangoschachtes in Westfall.", description = "Hört zu, eigentlich sollte ich gar nich' mit Euch reden, aber ich schulde Horatio den einen oder anderen Gefallen. Ich weiß eigenlich gar nichts darüber, was mit den Brauenwirbels passiert is', aber vielleicht kann ich Euch trotzdem weiterhelfen.\n\n<Lou reicht Euch eine große Kiste.>\n\nDiese Kiste war mein Zuhause, bevor ich reich geworden bin. Jetzt führ' ich ein Leben, von dem jeder Landstreicher träumt!\n\nAlso, Ihr schnappt Euch jetzt mal diese Wohnkiste hier und macht Euch auf zum Jangoschacht südwestlich von hier. Dringt bis ans Ende der Mine vor und versteckt Euch dort in der Kiste.", progress = "Seid mit meinem alten Haus schön vorsichtig. Das will ich meinen Kindern vermachen, wenn sie ausziehen.", completion = "&lt;Lou hält sich die Ohren zu und fängt an, laut zu sprechen.&gt;\n\nHALT! HALT! HALT! Ich will's gar nich' hören! Ich will's nich' wissen und egal is' es mir auch! Solche Informationen können einen in der Gegend hier das Leben kosten.\n\nEins kann ich Euch noch verraten und das war's dann!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26229] = {title = "\"Ich NEHMEN Kerze!\"", objective = "Tötet 12 Koboldbuddler.", description = "Bevor diese verdammten Kobolde mir mein Hinkebein verpasst haben, war ich William Pestles bester Kerzenlieferant. Von mir kommt sogar der Ausspruch \"ICH NEHMEN KERZE!\" Jep, das war ich. Die Kobolde haben immer gerufen \"Du nicht nehmen Kerze!\" und ich hab geantwortet \"ICH NEHMEN KERZE!\" und ihnen den Schädel eingeschlagen!\n\n<Jimb träumt einen Moment lang.>\n\nDas waren gute Zeiten... Die besten Zeiten.\n\nUnd jetzt? Ich kann noch nicht mal ohne Hilfe auf die Toilette gehen. Wollt Ihr mir helfen? Tötet ein paar Kobolde für mich. Ihr solltet einen ganzen Haufen von denen in der Mine hier in der Nähe finden.", progress = nil, completion = "Ah, SÜSSE Gerechtigkeit! Diese Kobolde abzuschlachten wird mich nicht dazu bringen, wieder wie ein normaler Mensch zu laufen, und es wird mir auch mit Sicherheit keine Arbeit einbringen, aber es tut auf jeden Fall verdammt gut.\n\n&lt;Jimb greift in einen schmutzigen, alten Beutel.&gt;\n\nHier, ich habe da etwas für Euch aus meiner Zeit als Koboldjäger. Vielleicht könnt Ihr damit etwas anfangen.", rewards = "KoboldspießWachsfängerKoboldknüpplerAuf Euch wartet eine dieser Belohnungen:\n\nKoboldkerze\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26230] = {title = "Festmahl oder Hungersnot", objective = "Sammelt 6 Kojotenschwänze und 5 Handvoll frischen Matsch.", description = "Das Leben in Westfall ist schwer, <Söhnchen/Mädchen>! Jeder Tag ist ein Kampf. Manchmal vergehen Wochen zwischen anständigen Mahlzeiten. Deswegen ist es so wichtig, dass wir uns gegenseitig beistehen. Vielleicht könnt Ihr ja mit anpacken, hm? Ich backe Matschkuchen und benötige noch ein paar Zutaten.\n\nBesorgt mir etwas frischen Matsch vom Kürbisbeet vor dem Haus und ein paar Kojotenschwänze. Ihr könnt überall in der Wildnis von Westfall Kojoten finden.\n\nAn die Arbeit! Wir haben Mägen zu füllen.", progress = "Matschkuchen backen sich nicht von selbst - normalerweise.", completion = "Mir knurrt schon der Magen, wenn ich Euch nur rieche! Wir werden heut' Abend fürstlich essen!", rewards = "Ihr bekommt:\n\nWestfallmatschkuchen"}
MultiLanguageQuestData['de'][26232] = {title = "Lous Abschiedsworte", objective = "Belauscht die Rohlinge hinter dem Bauernhaus auf Brauenwirbels Kürbishof in Westfall.", description = "So ein paar Rohlinge sind vor kurzem auf dem Gehöft aufgetaucht und haben 'ne Menge Ärger verursacht. Keine Ahnung, wo die herkommen oder für wen die arbeiten, aber ich bin mir SICHER, dass sie nichts Gutes im Schilde führen. Ich hab' sie vielleicht über so ein paar Dinge sprechen hören, die Euch interessieren könnten.\n\nWenn Ihr Interesse habt, findet ihr die Rohlinge hinter'm Bauernhaus. Wenn man Euch ertappt oder umbringt, ich weiß nichts von Euch. Hab Euch noch nie im Leben gesehen!\n\nViel Glück, <Junge/Mädel>.", progress = nil, completion = "Wir haben es hier mit einer Organisation zu tun, Grünschnabel. Niemand bringt so einfach am helllichten Tage den reichsten Landstreicher von Westfall um, ohne dabei Zeugen zu hinterlassen. Hinter diesen Morden steckt jemand mit einer Menge Macht. Was habt Ihr bisher in Erfahrung bringen können?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26233] = {title = "Aus den eigenen Reihen stehlen", objective = "Bringt 6 Fässer mit Dunkelspeerreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.", description = "Wie Ihr wisst, <Name>, hat Garrosh die Trolle von Orgrimmar in die westlichen Außengebiete der Stadt befehligt. Zu unserem Glück bedeutet das, dass wir leicht an ihre Vorräte kommen. Ich bereite gerade eine große Portion Jambalaya für die Infanterie vor und brauche so viel Reis, wie ich bekommen kann. Die Trolle lagern Reis in den Fässern in der Nähe ihrer Behausungen. Bringt mir die Fässer mit Dunkelspeerreis und ich kann das Gericht fertigstellen.", progress = "Konntet Ihr den Reis besorgen?", completion = "Ihr habt auch Talent im Stehlen, wie ich sehe, &lt;Name&gt;. Sorgt Euch nicht, wir werden den Reis zurückbringen, wenn wir fertig sind... oder auch nicht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStealing Credit\n\nIhr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26234] = {title = "Aus den eigenen Reihen stehlen", objective = "Bringt 6 Fässer mit Kezanreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.", description = "Wie Ihr wisst, <Name>, hat Garrosh die Goblins von Orgrimmar in die westlichen Außengebiete der Stadt befehligt. Zu unserem Glück bedeutet das, dass wir leicht an ihre Vorräte kommen. Ich bereite gerade eine große Portion Jambalaya für die Infanterie vor und brauche so viel Reis, wie ich bekommen kann. Die Goblins lagern Reis in den Fässern in der Nähe ihrer Behausungen. Bringt mir die Fässer mit Kezanreis und ich kann das Gericht fertigstellen.", progress = "Konntet Ihr den Reis besorgen?", completion = "Ihr habt auch Talent im Stehlen, wie ich sehe, &lt;Name&gt;. Sorgt Euch nicht, wir werden den Reis zurückbringen, wenn wir fertig sind... oder auch nicht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStealing Credit\n\nIhr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26235] = {title = "Auch Diebe bekommen Hunger", objective = "Findet 3 Infanterierationen der Horde und bringt sie zu Marogg in Orgrimmar.", description = "Seit ein paar Wochen haben wir hier in Orgrimmar Probleme mit Dieben, die die Rationen der Infanterie stehlen. Vor Kurzem habe ich Informationen darüber erhalten, wo diese Diebstähle stattfinden. Wenn Ihr irgendwo Kisten und Vorräte seht, könnt Ihr davon ausgehen, dass die Diebe nicht weit sind. Ich möchte, dass Ihr diese Diebe ausfindig macht und die gestohlenen Rationen findet. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Konntet Ihr die Rationen finden?", completion = "Gute Arbeit, &lt;Name&gt;! Ich werde dafür sorgen, dass die Rationen umgehend wieder zu unseren Truppen kommen.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][26236] = {title = "Die Vernehmung der Saldeans", objective = "Sprecht mit Bauer Saldean auf Saldeans Hof in Westfall.", description = "Was wissen wir also bisher? Wir müssen unseren Anhaltspunkten folgen.\n\nDrüben auf Jansens Hof habt Ihr einen durchnässten Brief und ein paar rote Stofffetzen gefunden. Hier auf dem Hof der Brauenwirbels habt Ihr ein Gespräch zwischen einer merkwürdigen Gestalt und einem Ogermagier belauscht. Ihr habt außerdem die Geständnisse von ein paar Schlägern, den Mord begangen zu haben - woraufhin Ihr die Schläger getötet habt.\n\nDa passt Einiges nicht zusammen, Grünschnabel.\n\nSüdöstlich von hier lebt ein älteres Ehepaar auf Saldeans Hof. Macht Euch auf den Weg dorthin und sprecht mit Bauer Saldean. Findet heraus, was er weiß.", progress = nil, completion = "Horatio Laine? Der Mann ist ein Drecksack. So dreckig wie meine Unterwäsche.\n\nHört zu, mein Freund, ich erteile nicht oft solche Ratschläge, aber Ihr scheint mir ein aufrichtiger Mann zu sein. VERSCHWINDET AUS WESTFALL. Ihr steckt schon bis über beide Ohren im Mist. Was Ihr da gerade macht ist so, als würdet Ihr Euren Kopf unter's Beil legen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26237] = {title = "Die Zeiten sind schwer", objective = "Tötet 10 Erntebehüter.", description = "Das sind schwere Zeiten, <Bruder/Schwester>. Da jetzt die geknechteten Massen aus Sturmwind hierher nach Westfall auswandern, sind unsere Vorräte knapper denn je. Das Volk ist unruhig und braucht Hilfe.\n\nUnser Farmhaus dient schon seit Jahren als Behelfsunterkunft. Salma gibt sich alle Mühe, unsere Gäste am Leben zu erhalten, aber manchmal werden sie von den Erntebehütern erwischt. Das sind diese missratenen Ungetüme, die sich auf meinem Feld herumtreiben - ein kleines Geschenk, das die Defias zurückgelassen haben, als sie vertrieben wurden. Helft uns!", progress = nil, completion = "Danke, Bruder. Ihr habt Salma und mir einen großen Dienst erwiesen und ich verspreche Euch, dass wir das so schnell nicht vergessen werden. Viel Geld habe ich nicht, aber Ihr könnt Euch gern an dem bisschen bedienen, das ich habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26238] = {title = "Die wilden Zwerge", objective = "Tötet 10 Krieger der Wildhämmer oder Schamanen der Wildhämmer.", description = "Die Horde hat für uns Bruchhauer viel getan und Trittbrettfahrer sind wir sicherlich nicht. Die anderen Waldtrollstämme wurden zurückgedrängt und wir sind dabei, im Namen der Horde neue Ländereien zu sichern.\n\nJetzt sind uns aber die Wildhammerzwerge in den Weg gekommen. Wenn sie Krieg wollen, so werden sie Krieg bekommen... und ich habe nicht vor, einen Krieg gegen jemanden zu verlieren, der nur halb so groß ist wie ich.\n\nGeht los und tötet ein paar Zwerge für mich.", progress = nil, completion = "Das wird den Wildhammerzwergen klar machen, dass sie auf unseren Ländereien nichts zu suchen haben!\n\nDie verrückten Zwerge hätten einfach in den Bergen bleiben sollen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26240] = {title = "Im Takt", objective = "Spielt die Kriegstrommeln der Bruchhauer für 6 Krieger der Bruchhauer.", description = "Unsere Krieger kämpfen hart, um die üblen Wildhammerzwerge auszuschalten, damit wir hier im Dorf wieder in Sicherheit sind. Wir müssen tun, was wir können, um sie zu unterstützen.\n\nEs gibt etwas, das bei jedem Troll seine besten Kampfkünste herauskommen lässt: der hämmernde Rhythmus der Trommeln lässt sie fester zuschlagen und ruft die Geister dazu auf, über die Krieger zu wachen. Nehmt meine Trommeln mit auf das Schlachtfeld. Spielt sie für unsere Krieger und zeigt den Wildhammerzwergen, wem dieses Land gehört!", progress = nil, completion = "Es macht einen großen Unterschied, nicht wahr? Das wird diesen Zwergen eine Lektion erteilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26241] = {title = "Westfalleintopf", objective = "Sammelt 6 Okraschoten, 6 Stück sehniges Fleischreißerfleisch und 6 Geiferzahnflanken.", description = "Hallo, <mein Lieber/meine Liebe>. Willkommen in unserem Zuhause. Hmm, Ihr seht aber nicht aus, als ob Ihr obdachlos wärt. Seid Ihr hier, um uns zu helfen? Wenn das so ist, dann kommt Ihr gerade rechtzeitig! Ich plane ein Abendessen für die Kinder und ich brauche ein paar einfache Zutaten.\n\nWenn Ihr mir ein paar Okraschoten, Geiferzahnflanken und sehniges Fleischreißerfleisch bringt, kann ich meinen berühmten Westfalleintopf zubereiten. Ihr könnt all diese Zutaten in der Nähe unserer Farm finden. Nehmt Euch nur vor den Erntebehütern in Acht. Das sind gnadenlose Vernichtungsmaschinen.", progress = "Das Essen ist fertig, sobald ich alle Zutaten habe. Beeilt Euch!", completion = "Seid gesegnet, mein Lieber. Diese armen Waisen haben schon seit Tagen keine warme Mahlzeit mehr bekommen.\n\nEs sieht so aus, als hätten wir genug übrig, um noch viele weitere Obdachlose Westfalls zu versorgen.", rewards = "Umhang des goldenen SonnenscheinsGekochte StiefelEngergeschnallter GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26243] = {title = "Die Weltensäule", objective = "Befragt Maruut Steinbinder zur Weltensäule.", description = "Die Säule in diesem Zimmer stützt mehr als nur den Tempel der Erde.\n\nDiese gesamte Existenzebene stürzt bald in unsere Welt, wenn wir sie nicht wieder aufbauen.\n\nEs ist schon bald Zeit zu handeln. <Name>. Aber zunächst müsst Ihr Euch anhören, was ich Euch zu sagen habe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26244] = {title = "Die Erde nimmt sich alles", objective = "Vernichtet 5 Tiefensteinelementare.", description = "Wir befinden uns auf der Ebene der Erde, <Name>. Nach und nach wird das Land alles in sich aufnehmen.\n\nDie Sturmfuror wird bald nichts als Staub sein. Dann können wir keine Erkenntnisse aus ihren Resten mehr gewinnen.\n\nGeht und vernichtet die Elementare, die das Schiff auseinandernehmen. Wir zögern das Unvermeidliche nur heraus, aber wir müssen uns etwas Zeit verschaffen, wenn wir alle Teile der Weltensäule finden wollen.", progress = nil, completion = "Ihr habt getan, was notwendig war, &lt;Name&gt;. Ich merke schon, dass Ihr genau die Sorte &lt;Klasse&gt; seid, mit der es sich gut leben lässt.", rewards = "TiefsteintreterSteinschmetternde HalsbergeZornstillende ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26245] = {title = "Luftschiff am Boden", objective = "Sucht im Wrack der Sturmfuror in Tiefenheim nach Hinweisen.", description = "Der Abschlussstein wurde in einem Luftschiff der Horde namens Sturmfuror transportiert.\n\nDas Luftschiff ist südlich von hier abgestürzt. Laut unseren Untersuchungen befindet sich der Abschlussstein nicht mehr an Bord.\n\nDurchsucht das Schiff nach Hinweisen darauf, was passiert sein könnte.", progress = nil, completion = "Die Hinweise deuten auf das Offensichtliche. Vielleicht zu offensichtlich…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26246] = {title = "Das Logbuch des Kapitäns", objective = "Bringt das Logbuch des Kapitäns zu Maruut Steinbinder beim Tempel der Erde in Tiefenheim.", description = "<Ihr blättert zum letzten, abgebrochenen Eintrag.>\n\n… nähern uns dem Tempel der Erde bei 300 Knoten und beginnen die Landemanöver gemäß der neuen Route. Wir haben ein Niedrigdrucksystem im Norden notiert und ziehen jetzt unser…\n\nBLUT UND DONNER! ABSCHAUM DER ALLIANZ NÄHERT SICH!", progress = nil, completion = "Warum sollte die Allianz die Horde angreifen, wenn sie uns gerade ein Stück der Weltensäule bringen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26247] = {title = "Diplomatie hat Vorrang", objective = "Trefft Euch mit Sturmruferin Mylra auf dem Kanonenboot der Allianz.", description = "Der Irdene Ring ist eine neutrale Gemeinschaft, <Name>. Wir können uns im Krieg zwischen der Horde und der Allianz auf keine Seite schlagen.\n\nSeht Euch um. Wir haben Mitglieder verschiedenster Herkunft. Wenn wir die Spannungen zwischen den einzelnen Völkern über unser Ziel stellen würden, wäre unsere Mission in Gefahr. Lasst uns dies also vertraulich behandeln, bis wir weitere Informationen gesammelt haben.\n\nWir dürfen keine voreiligen Schlüsse ziehen. Ich schicke Euch zusammen mit einem unserer neuen Mitglieder los, um das Kanonenboot der Allianz zu suchen.\n\nFindet heraus, was Ihr könnt, ohne uns in den Konflikt hineinzuziehen.", progress = nil, completion = "He, &lt;Name&gt;! Man hat mir gesagt, dass ich bald Gesellschaft bekomme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26248] = {title = "All unsere Freunde sind tot", objective = "Benutzt das Geistertotem in der Nähe von 6 Leichnamen erschlagener Besatzungsmitglieder.", description = "Irgendwas ist hier nicht in Ordnung, <Name>.\n\nDie Besatzung des Schiffes wurde erschlagen. Und doch sehe ich kein vergossenes Blut oder Schäden am Schiffskörper.\n\nDas war nicht das Werk der Horde.\n\nWir müssen mit den Geistern der Toten sprechen, um Antworten zu finden. Sie haben diese Welt noch nicht verlassen.\n\nNehmt dieses Totem und stellt es neben den Leichnamen der Gefallenen auf. Dann könnt Ihr ihre letzten Gedanken hören.\n\nAber seid vorsichtig! Es ist schwer zu sagen, wie die Geister der Toten auf unsere Nachforschungen reagieren werden.", progress = "Die Geister haben immer eine Geschichte für die zu erzählen, die zuhören.", completion = "Es war nur eine Frage der Zeit, bis wir auf Mitglieder des Schattenhammers trafen, &lt;Name&gt;. Wenn sie hinter all dem stecken, dann haben sie sicher auch das Fragment der Weltensäule in ihrer Gewalt.", rewards = "HimmelsrissarmschienenKapuze des TotemrufersUnkörperliche SandalenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26249] = {title = "Die Kajüte des Admirals", objective = "Haltet in der Kajüte des Admirals auf dem Kanonenboot der Allianz nach Hinweisen Ausschau.", description = "Möglicherweise finden wir in der Kajüte des Admirals weitere Spuren. Sie befindet sich direkt unter uns.\n\nSchaut, ob es dort unten irgendwelche Überlebenden oder Informationen gibt, die uns nähere Hinweise zum Verbleib des Weltensäulenfragments geben können. Seid vorsichtig, <Name>. Wer auch immer die Besatzung auf dem Gewissen hat, könnte noch dort sein.", progress = nil, completion = "Dieses Schiff ist voller Ratten…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26250] = {title = "Ach, einen Gefangenen sollten wir doch nehmen", objective = "Unterwerft Mor'norokk den Hasserfüllten auf dem Kanonenboot der Allianz in Tiefenheim.", description = "Es ist nicht zu spät, <Name>. Die Kultisten sind bestimmt immer noch hier.\n\nGeht unter Deck, findet heraus, wer das Sagen hat und unterwerft ihn.\n\nWir werden Antworten auf unsere Fragen bekommen, auf die eine oder andere Art.", progress = "Grüße, <Name>.", completion = "Uff, das war ein schwerer Brocken! Er hat meinem armen Greifen fast den Rücken gebrochen!\n\nSeid Ihr bereit, den Oger zu befragen, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26251] = {title = "Macht keine Gefangenen", objective = "Tötet 6 Zwielichtsaboteure.", description = "Sieht aus, als wäre der Schattenhammer noch immer auf dem Schiff. Geht unter Deck und macht kurzen Prozess mit ihnen.\n\nSeid vorsichtig, <Name>. Ich habe das Gefühl, dass sie nicht hier sind, um ihr spirituelles Gleichgewicht zu finden, wenn Ihr versteht, was ich meine.", progress = "Habt Ihr es erledigt, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Der Schattenhammer ist ein Übel, das wir an allen Ecken und Enden bekämpfen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26252] = {title = "Herz des Behüters", objective = "Bringt das Herz eines Erntebehüters zurück zu Bauer Saldean auf Saldeans Hof.", description = "Ihr habt etwas gefunden, das offenbar das Herz eines Erntebehüters ist.\n\nDem Geräusch nach zu urteilen, das von dem Gerät ausgeht, ist es noch immer voll funktionsfähig. Vielleicht solltet Ihr es zu Bauer Saldean zurückbringen.", progress = "Was habt Ihr denn da, <Name>?", completion = "Ist das etwa... Ist das das Herz eines der Behüter? Ich habe Geschichten darüber gehört, wie man eins von diesen Dingern dazu benutzen kann, einen Behüter für den Eigengebrauch anzutreiben. Natürlich bin ich selbst nicht mehr in der Verfassung, solche Dinge selbst zu versuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26254] = {title = "Erklärt Euch!", objective = "Springt auf Sturmschnabel und beobachtet Mor'norokks Befragung.", description = "Springt auf, <Name>. Mal sehen, was Herr Ogervisage hier zu seiner Verteidigung zu sagen hat.\n\nNur keine Scheu. Sturmschnabel hat erst ein paar Mal einen Reiter fallenlassen.", progress = "Ja, <Name>?", completion = "Wir haben unsere Antworten, &lt;Name&gt;. Melden wir uns zurück.", rewards = "BefragungsaxtKapuze des VernehmersGurt des InquisitorsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26255] = {title = "Rückkehr zum Tempel der Erde", objective = "Sprecht mit Maruut Steinbinder im Tempel der Erde in Tiefenheim.", description = "Ihr müsst die anderen am Tempel informieren. Wahrscheinlich bringen sie das Fragment gerade an einen sicheren Ort.\n\nBerichtet Maruut, was Ihr wisst. Ich werde diesen Zwielichtrat in der Zwischenzeit unter die Lupe nehmen.", progress = nil, completion = "Wir müssen Eure Erkenntnisse genauer untersuchen, aber wir dürfen die Spur des Fragments nicht verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26256] = {title = "Lasst die Blutformer bluten", objective = "Besorgt Euch die Schattenhammerbefehle von einem der Zwielichtblutformer in Todesschwinges Sturz.", description = "Der Schattenhammer wirkt hier bösartige Magie, <Name>. Sie beleben die Überreste von Todesschwinges Blut und erfüllen sie mit Energie. Statt auszutrocknen und zu verschwinden gedeiht es und wird immer mehr.\n\nErledigt einen ihrer Blutformer und presst Informationen aus ihm heraus, wo wir diesen \"Schmiedemeister\" finden.", progress = "Wir müssen uns beeilen, wenn wir die Weltensäule wieder errichten möchten, <Name>.", completion = "Sie halten hier Sklaven? Wir sollten sie ohne Frage befreien, aber vielleicht können sie uns auch dabei helfen, den Schmiedemeister zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26257] = {title = "Es lebt!", objective = "Wendet das Herz eines Erntebehüters auf einen überladenen Erntegolem an und benutzt dann den überladenen Erntegolem, um 25 aufgeladene Ernteschnitter zu töten.", description = "Soweit ich gehört habe, müsst Ihr nur einen geeigneten Erntegolem finden und rein mit dem Herzen. Sobald das erledigt ist, solltet Ihr die volle Kontrolle über das Geschöpf haben.\n\nIch glaube, es gibt ein ganzes Feld mit überladenen Erntegolems westlich von hier auf dem Hof der Molsens. Haltet nach den Lichtbögen Ausschau.\n\nFalls Ihr einen zum Laufen bringen könnt, benutzt den Golem, um die aufgeladenen Ernteschnitter auf dem alten Molsenhof zu zerstören. Die Monster dort sind viel zerstörerischer als die auf unserem Hof hier.", progress = nil, completion = "Es hat tatsächlich funktioniert? Das ist unglaublich, &lt;Name&gt;. Hoffentlich löst das das Problem mit den Erntegolems hier in Westfall.", rewards = "ErnterstiefelZerkauter GürtelSaldeans ArbeitshandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26258] = {title = "Todesschwinges Sturz", objective = "Geht zu Todesschwinges Sturz in Tiefenheim.", description = "Dass der Schattenhammer etwas mit dem Verschwinden der Weltensäule zu tun hat, ist nicht verwunderlich. Hoffentlich können wir schnell genug handeln, um sie zurückzuholen.\n\n<Maruut legt seine Hand auf Eure Schulter.>\n\nIch habe ein spirituelles Band zu Euch gewirkt. Wir sollten miteinander kommunizieren können, solange Ihr in Tiefenheim seid.\n\nGeht zu Todesschwinges Sturz im Südosten und untersucht, was der Schattenhammer vorhat.", progress = nil, completion = "Das muss der Ort sein, an den sie das Säulenfragment gebracht haben. Lasst uns einen genaueren Blick darauf werfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26259] = {title = "Blut des Erdwächters", objective = "Sammelt 5 Proben des Blutes von Neltharion vom lebenden Blut in Todesschwinges Sturz.", description = "Als Todesschwinge nach Tiefenheim geflohen ist, war seine Verderbtheit stark ausgeprägt, aber vielleicht noch nicht vollständig.\n\nDie Kultisten in Todesschwinges Sturz ernten sein übrig gebliebenes verderbtes Blut und formen es in lebende Wesen, um deren Energie aufzunehmen.\n\nWas, wenn eine kleine Spur der Essenz des Erdwächters geblieben ist? Schließlich war Neltharion der Aspekt der Erde, bevor er zum Aspekt des Todes wurde.\n\nSammelt Proben des lebenden Blutes, das die Kultisten erschaffen, und wir überprüfen, ob eine Spur des Erdwächters darin verblieben ist.", progress = "Ihr seid zurück, <Name>. Habt Ihr das Blut bekommen?", completion = "In diesem Blut schlummert immer noch viel Macht, &lt;Name&gt;. Ich kann sie sogar jetzt spüren.\n\nUnd dennoch spüre ich auch viel Verderbtheit. Ich bin mir nicht sicher, ob wir daraus die Essenz des Erdenwächters gewinnen können.", rewards = "Blutrünstige ArmschienenRotblutgürtelHelm des BlutsammlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26260] = {title = "Das Logbuch des Schmiedemeisters", objective = "Findet das Logbuch des Schmiedemeisters in Todesschwinges Sturz in Tiefenheim.", description = "Geht zu dem Turm, von dem der Sklave gesprochen hat. Ihr solltet ihn am nordöstlichen Ende des Lagers finden.\n\nWenn wir schnell genug handeln, können wir vielleicht das Treffen des Schmiedemeisters belauschen.", progress = nil, completion = "Ein Eintrag berichtet von einem anstehenden Treffen in den Oberen Silbermarschen.\n\nDer Schmiedemeister muss sich dort aufhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26261] = {title = "Befragt die Sklaven", objective = "Besorgt Euch den Schlüssel des Zwielichtsklavenhändlers und befreit 6 versklavte Minenarbeiter.", description = "Laut den Befehlen, die Ihr gefunden habt, soll sich in einem Zelt am südöstlichen Ende von Todesschwinges Sturz ein Schlüssel befinden.\n\nBesorgt ihn Euch und befreit die Sklaven im Steinbruch im Süden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Rauer SteinpanzerStulpen des KettensprengersSchlossbrechermesserIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26263] = {title = "Thornar Donnerknall", objective = "Tötet Thornar Donnerknall.", description = "Wir haben versucht, den Kommandanten der eindringenden Wildhammerzwerge auszuschalten – bisher jedoch ohne Erfolg.\n\nThornar Donnerknall befindet sich in der Sicherheit seines Kommandopostens und man kann nur seine Stimme hören, die die Zwerge auf dem Schlachtfeld donnernd antreibt. Wir glauben, dass wir ihn zum Schweigen bringen müssen.\n\nErledigt Thornar und wir werden mit dem Rest seiner Truppen problemlos fertigwerden.", progress = nil, completion = "Gut gemacht, Mann. Ihr seid ein echter Held der Horde.", rewards = "StimmenstehlerGelenkbänder des UrahnenTreter des EindringlingsBruchhauerstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26264] = {title = "Die Zurückgelassenen", objective = "Beschafft 6 zurückerlangte Besitztümer von toxischem Schlick auf dem Toxischen Flugplatz.", description = "Die meisten von uns haben die kranken und irren Gnome gesehen, die unter den Folgen der Gifte und der Strahlung in Gnomeregan leiden. Ihr Niedergang ist erst vollendet, wenn aus ihnen hirnlose, aber größtenteils harmlose Pfützen aus toxischem Schlick werden.\n\nMeine Nachforschungen lassen darauf schließen, dass wir sie selbst in diesem Zustand noch retten können. Reist zum Toxischen Flugplatz im Süden, unterwerft den toxischen Schlick, von dem ich Euch erzählt habe, und bringt mir den Besitz der Gnome, die sie einst waren.", progress = "Konntet Ihr den Besitz einiger bestrahlter Gnome bergen?", completion = "Ich kann es kaum erwarten, diese neue Technologie auszuprobieren! Zahllose Gnome sind der Strahlung zum Opfer gefallen. Es wird Zeit, den Prozess umzukehren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26265] = {title = "Stoppt die Verseuchung", objective = "Zerstört 6 lebende Verseuchungen auf dem Toxischen Flugplatz.", description = "Tock Flinkspross hat eine verrückte Theorie. Er glaubt, bei den toxischen Schlickpfützen handele es sich um die Überreste von Gnomen, deshalb haben meine Männer Befehl, sie erst einmal nicht anzugreifen.\n\nAllerdings wimmelt es auf dem Toxischen Flugplatz südlich von hier von lebenden Verseuchungen. Dabei handelt es sich um Elementare, die aus verseuchtem Wasser und anderen toxischen Materialien bestehen. Wenn wir uns nicht um sie kümmern, werden sie die Stadt überrennen. Würdet Ihr uns helfen, sie loszuwerden?", progress = "Konntet Ihr die Verseuchungen beseitigen?", completion = "Welch eine Erleichterung! Ich danke Euch für Eure Hilfe. Ich hoffe, dass Dingsda, an dem Ingenieur Schleiffunke gearbeitet hat, hilft uns, den Flugplatz endgültig zu säubern.", rewards = "Ihr bekommt:\n\nStrahlungsabdeckungTasche des Flugplatzkuriers"}
MultiLanguageQuestData['de'][26266] = {title = "Hoffnung für das Volk", objective = "Bringt den Westfalleintopf zu Hope Saldean an der Späherkuppe.", description = "Vor ungefähr vier Jahren stolperte ein kleines Mädchen mitten in der Nacht in unser Farmhaus und brach zusammen. Niemand kannte sie. Das arme, kleine Ding hatte keine Erinnerung daran, wer sie sein könnte oder woher sie kam - wahrlich eine verirrte Seele.\n\nBald darauf adoptierten wir die Kleine und nannten sie Hope - denn für uns bedeutete sie Hoffnung.\n\nJetzt ist sie eine junge Dame und kümmert sich um die Obdach- und Mittellosen von Westfall. Bringt meinen Westfalleintopf zu ihr zur Späherkuppe südlich von hier.", progress = "Guten Tag werter Herr. Wie kann ich Euch dienen?", completion = "Ich rieche Westfalleintopf! Hat Mutter Euch geschickt!?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26267] = {title = "Den Lauerfels aufräumen", objective = "Tötet 10 jadegrüne Schlamme.", description = "Vor vielen Jahren hatte die Horde eine Station tief im Lauerfels. Sie steht seitdem leer aber es ist immer noch eine gute Stellung, die wir wieder einnehmen sollten.\n\nDas Problem ist dass die Station voll von Schlamm ist inzwischen. Schlamme sind üble Dinger... kopflos, ätzend, und gefährlich, da sie alles essen, was ihnen in den Weg kommt.\n\nIch brauche jemand, der mutig genug ist, um sich zum Lauerfels zu begeben und die Schlamme zu beseitigen. Seid Ihr mutig genug, <Name>?", progress = nil, completion = "Gut, dass Ihr wieder hier seid... und sogar mit allen Gliedmaßen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26268] = {title = "Lauerfelsvorräte", objective = "Sammelt 5 schlammbedeckte Vorratskisten.", description = "Ich war im Zweiten Krieg in Lauerfels stationiert. Ich war jung, noch Jahre davon entfernt, meine Partnerin kennenzulernen, und erinner mich noch gut an das Chaos, das ausbrach, als die Allianz uns angriff. Wir sind mit den Orcs geflohen und haben keine Zeit damit verschwendet, unsere Besitztümer zu packen.\n\nWir haben alles hinter uns gelassen. In Lauerfels sind noch immer viele unserer alten Vorräte. Wir könnten sie hier im Dorf gut gebrauchen... und vor allem sollten die Wildhammerzwerge sie nicht in ihre dreckigen Hände bekommen.", progress = "Wie viele Kisten habt Ihr gefunden?", completion = "Sie sind unversehrt! In diesen Kisten sind viele Erinnerungen festgehalten. Mal sehen, was wir hier haben...\n\nBananenbrot! Und es ist noch gut!\n\nHier, also ich nehme das hier, Ihr könnt Euch auch etwas aussuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26269] = {title = "Die Grünen Hügel des Schlingendorntals", objective = "Findet Seite 14 von Die Grünen Hügel des Schlingendorntals.", description = "Eine Seite! Ich brauche nur noch eine Seite!\n\nMit dem Schmöker von Meister Nesingwary gab es einen kleinen... Unfall <Barnil blickt vorwurfsvoll zu Klaps>... und wir haben ein paar der Seiten verloren.\n\nIch habe die anderen Abenteurer bereits um Hilfe gebeten und sie konnten auch ein paar der Seiten wiederfinden, aber eine Seite fehlt immer noch.\n\nIhr seid sicher furchtbar beschäftigt mit anderen Sachen, aber falls Ihr sowieso im Dschungel sein solltet, würde es Euch sicherlich nicht stören, ein wenig nach der Seite Ausschau zu halten?", progress = "Habt Ihr sie gefunden? Ich würde Hemet nur äußerst ungern ein fast fertiges Buch geben.", completion = "Ihr habt mir sicherlich viel Ärger erspart, &lt;Name&gt;! Ich kann Euch gar nicht genug danken. Es wird nicht mehr lange dauern, und wir werden das Buch von Meister Nesingwary in Bibliotheken überall auf der Welt finden können!\n\nIch werde eine Kopie für Euch hierlassen, falls Ihr Euch je für das fertige Exemplar interessieren solltet. Vielen Dank, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26270] = {title = "Unser Dank ist Euch gewiss", objective = "Sprecht mit Salma Saldean auf Saldeans Hof in Westfall.", description = "Es ist viele Jahre her, dass uns Hilfe angeboten wurde, <Name>. Wärt Ihr nicht gewesen, hätten wir es womöglich nicht über den nächsten Winter geschafft. Ihr habt Euch als eine selbstlose Person erwiesen - jemand, dem wir vertrauen können. Ich wünschte nur, wir hätten etwas von Wert, das wir Euch anbieten könnten.\n\nIch habe zwar keine Informationen, die Euch bei Eurem Vorhaben, die Mörder der Brauenwirbels zur Strecke zu bringen, von Nutzen sein werden, aber vielleicht kann Euch meine Frau weiterhelfen. Sprecht mit Salma im Haus und sie wird Euch sagen, was Ihr wissen müsst, bevor Ihr Euch wieder auf den Weg macht.", progress = nil, completion = "Aber natürlich, mein Lieber. Unsere kleine Tochter arbeitet an der Späherkuppe und steht den Obdachlosen von Westfall sehr nahe. Vielleicht hat sie ja etwas mitbekommen. Bevor Ihr geht, lasst mich den Westfalleintopf einpacken und Euch ein wenig über unsere liebe kleine Tochter erzählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26271] = {title = "Die Hungrigen und die Hoffnungslosen speisen", objective = "Benutzt den Westfalleintopf, um 20 Obdachlose an der Späherkuppe in Westfall zu speisen.", description = "Ja, ich habe von den Brauenwirbelmorden gehört. Es ist sehr tragisch, aber solche Tragödien sind in Westfall an der Tagesordnung. Hier gibt es viele Leute, die einfach nicht mehr die Mittel oder den Willen haben, sich selbst zu versorgen. Sie haben die Hoffnung aufgegeben. Könnt Ihr Euch vorstellen, wie es ist, so hoffnungslos zu sein, dass man sich seines Lebens nicht mehr erfreuen kann? Wir müssen uns gemeinsam darum bemühen, ihnen zu zeigen, dass es noch Hoffnung gibt. Dass jeder neue Tag ein besseres Leben bringt.\n\nNehmt den Westfalleintopf meiner Mutter und helft dabei, die Obdachlosen an der Späherkuppe zu versorgen.", progress = nil, completion = "Ihr habt ein gutes Herz, &lt;Name&gt;. Ihr habt heute eine gute Tat vollbracht und das wird Euch am jüngsten Tag nicht vergessen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26272] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Voldreka auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, <Name>. Sprecht mit Voldreka im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Entschlossenheit. Feurige Augen. Vielleicht wird aus Euch noch eine echte &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26273] = {title = "Die Grundlagen: Dinge schlagen", objective = "Zerstört 6 Tikiziele.", description = "Okay, Mann. Fangen wir klein an. Ich weiß, dass Ihr die Grundlagen der dunklen Künste beherrscht.\n\nGeht und macht diese Tikiziele fertig. Nehmt Euch Zeit. Bleibt ganz natürlich. Ich sehe zu, wie Ihr Eure Zauber formt. Dann sehen wir weiter.", progress = nil, completion = "Nicht übel, Mann. Ihr habt tiefe Macht in Euren Zaubern - vielleicht seid Ihr talentiert.\n\nNoch habt Ihr Ecken und Kanten, aber die werden wir hier schon glätten, und dabei werde ich Euch ein oder zwei neue Dinge beibringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26274] = {title = "Die Künste eines Hexenmeisters", objective = "Ihr müsst Stufe 3 erreichen, um Verderbnis zu erlernen. Probiert Verderbnis fünfmal an einem Tikiziel aus.", description = "Ich glaube, da ist etwas, das ich Euch sagen sollte.\n\nWenn Ihr stärker werdet, fangt Ihr an, diese Stimmen zu hören - sie bringen Euch neue Dinge, neue Zauber bei.\n\nLos, sammelt weitere Erfahrungen. Kommt dann zurück und zeigt mir, was Ihr gelernt habt.", progress = nil, completion = "Gut Arbeit, Mann! Das scheint Euch ja leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26275] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26276] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = "Alle Trolle müssen sich beweisen, bevor wir sie weiter als zum Übungsgelände gehen lassen.", completion = "Ihr macht Euch ganz gut. Eines Tages werdet Ihr ganz schön mächtig sein.", rewards = "Ihr bekommt:\n\nMagiewirkertunika der Dunkelspeere"}
MultiLanguageQuestData['de'][26277] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26278] = {title = "Die Verteidigung von Grom'gol: Raptorenrisiko", objective = "Zerstört 12 Schmetterschwanzeier.", description = "Throm'ka, <Klasse>!\n\nEure Ankunft in Grom'gol kommt zu einer guten Zeit. Unsere Aufgabe, einen sicheren Weg für die Vorräte für Steinard zu finden, wird von den Ortsansässigen verhindert.\n\nIch werde Euch damit beauftragen, die Raptoren außerhalb Grom'gols für immer zu beseitigen. Macht Euch um die Raptoren selber keine Sorgen... diese jämmerlichen Jäger von Nesingwary werden sich um sie kümmern.\n\nIhr sollt die Eier der Raptoren zerstören.", progress = nil, completion = "Macht mir der guten Arbeit weiter, &lt;Klasse&gt;. Höllschrei hat Euch im Auge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26279] = {title = "Die Verteidigung von Grom'gol: Ogerunterdrückung", objective = "Tötet 4 Schläger der Mosh'Ogg und 4 Hexendoktoren der Mosh'Ogg.", description = "Als wir zuerst hier im Dschungel ankamen hatten wir nicht vor, gegen die Einheimischen einen Krieg zu führen. Unsere Aufgabe, Steinard zu versorgen, hat oberste Priorität. Es ist aber zu Komplikationen gekommen. Ein paar Oger haben die Ruinen von Mizjah südöstlich von Grom'gol eingenommen. Trotz unsere Warnungen greifen sie unsere Versorgungskarawanen weiterhin an.\n\nIch werde Euch damit beauftragen, Euch um die unkooperativen Oger zu kümmern.\n\nBegebt Euch zu den Ruinen und versucht, sie aus der Gegend zu vertreiben. Zumindest muss ihnen eine klare Nachricht geschickt werden.", progress = nil, completion = "Ihr seid auch für Sachen zu gebrauchen, die etwas herausfordernder sind als das Zerschlagen von Eiern. Das ist gut. Die Horde kann einen fähigen &lt;Volk&gt; wie Euch gut gebrauchen.", rewards = "MizjahwesteWuchtige BrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nRing der Kooperation\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26280] = {title = "Die Verteidigung von Grom'gol: Murlocbedrohung", objective = "Tötet 15 Murlocs der Düsterkiemen.", description = "Die Murlocs der Düsterkiemen wurden von den Salzschuppen aus dem Ozean vertrieben und nun suchen sie in den Ruinen von Kal'ai nordöstlich von hier Zuflucht. Früher war das kein Problem, aber inzwischen ist es nicht länger tragbar.\n\nWeit entfernt von dem Ozean, ihrer Heimat, wurden die Düsterkiemen unruhig und schicken Futterwühler aus, um die Versorgungskarawanen zu überfallen. Vermittelt ihnen folgende Nachricht: solches Verhalten wird von Höllschreis Horde NICHT geduldet.", progress = nil, completion = "Ausgezeichnete Arbeit. Hoffentlich werden die Beutezüge jetzt aufhören.\n\nIch habe noch eine weitere Aufgabe für Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26281] = {title = "Die Verteidigung von Grom'gol: Trolldiebstähle", objective = "Holt die Rationen aus Grom'gol aus den Ruinen von Bal'lal.", description = "Die Trolle lassen uns eigentlich in Ruhe hier in Grom'gol. Die meisten Trolle wissen genau, dass die Horde sie leicht zerschmettern kann, wenn es sein muss, und auch die Trolle hier in Schlingendorntal sind sich dessen bewusst.\n\nDie Blutskalpe wurden in der letzten Zeit aber immer aktiver. Erst letzte Woche haben sie einen Trupp nach Grom'gol geschickt und mehrere Rationen gestohlen.\n\nDem Stehlen von Nahrung kann von jeder Art des Diebstahls noch am ehesten vergeben werden, aber ich kann trotzdem nicht zulassen, dass es vorkommt während ich das Sagen habe. Begebt Euch nach Norden zu den Ruinen von Bal'lal und holt unser Eigentum zurück.", progress = "Mitleid hat unter meinem Kommando nichts zu suchen. Die Trolle können ihr Essen anderweitig besorgen. Der Dschungel ist groß genug.", completion = "&lt;Aggro'gosh begrüßt Euch.&gt;\n\nIhr habt den Dank der Horde, &lt;Name&gt;. Grom'gol ist sicher, wenn auch nur für einen Tag.", rewards = "Nachtragende PantalonsBal'lalgürtelGnadenlose SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26282] = {title = "Die Gunst Akil'darahs", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][26283] = {title = "Erstklassiger Schleim", objective = "Erhaltet eine Terrorklumpenprobe von Terrorklumpen.", description = "Die Schleime, die in Lauerfels zu finden sind, interessieren mich mehr und mehr. Sie kommen immer wieder, egal, wie oft man sie entfernt, aber sie scheinen sich von einem einzigen Schleim selber nicht vermehren zu können.\n\nIch glaube, das in Lauerfels etwas wächst. Eine Quelle, aus der der Schleim kommt. Ich möchte sie untersuchen - findet diese Quelle und bringt mir eine Probe.", progress = "Und? Was habt Ihr gefunden?", completion = "Faszinierend... wie groß war es? Ich frage mich, ob es davon noch andere gibt, die funktionstüchtig sind...\n\nDiese Probe ist ausgezeichnet. Ich werde sie meinen Forscherkollegen zugänglich machen.", rewards = "Zauberstab des ForschungsassistentenSchleimjägerkopfschutzLauerfelsgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26284] = {title = "Vermisst", objective = "Befreit 6 gefangene Demolierer aus ihren Käfigen in der Nähe der Höhle der Frostmähnen.", description = "Für solche Aufträge bringe ich normalerweise meine ganze Belegschaft von Demolierern mit. Mit etwas Hilfe bei der Pulverherstellung, der Herstellung der Sprengladungen und dem Rest von unserem Zeug wird alles viel schneller fertig.\n\nDiese verdammten Troggs haben meine Jungs überall rund um die Höhle der Frostmähnen in Käfige gesperrt. Jetzt stehe ich ganz allein da, ohne das Personal, das ich für dieses Vorhaben brauche. Würdet Ihr die Demolierer finden, die die Troggs eingesperrt haben, und sie aus ihren Käfigen befreien?", progress = nil, completion = "Ihr habt meinen Dank und den der Männer, die Ihr gerettet habt. Ich habe die Jungs schon die Ausrüstung in der Höhle aufstellen lassen. Bald sollte alles bereit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26285] = {title = "Bringt meinen Sprengstoff zurück!", objective = "Beschafft 7 gestohlene Pulverfässer von Knochenpflückern der Felsenkiefertroggs oder von Marodeuren der Felsenkiefertroggs bei der Höhle der Frostmähnen.", description = "Wir werden jede Menge Pulver brauchen, um die Höhlen zum Einsturz zu bringen. Keine Ahnung, ob die verdammten Troggs das wussten, als sie meine Vorräte stahlen und meine Demolierer entführten! Das Ergebnis ist dasselbe.\n\nKann nichts in die Luft jagen, wenn ich kein Pulver habe.\n\nGeht nach Süden zur Höhle der Frostmähnen und tötet alle Troggs, die Ihr seht. Jeder von ihnen könnte meine Pulverfässer dabei haben.", progress = "Habt Ihr meine fehlenden Vorräte gefunden?", completion = "Na, so gefällt mir das schon besser. Vielleicht sprengen wir doch noch irgendwas in die Luft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26286] = {title = "Die Verteidigung Westfalls", objective = "Erhaltet die Angriffsbefehle der Gnolle.", description = "Nachdem meine Dienstzeit in den Grizzlyhügeln beendet war, bin ich nach Westfall zurückgekehrt und musste das Land in einem schlimmeren Zustand als vor meinem Einsatz vorfinden.\n\nWir haben den Krieg mit tausenden von obdachlosen Bürgern bezahlt. Jetzt wandern sie hierhin aus und lassen sich auf den verlassenen Bauernhöfen und Siedlungen dieser Gegend nieder.\n\nZu allem Überfluss werden wir jetzt auch noch von den Gnollen angegriffen. Die Westfallbrigade braucht Eure Hilfe, <Name>. Tötet die angreifenden Gnolle und nehmt ihnen ihre Befehle ab. Da zieht jemand im Hintergrund die Fäden und wir müssen herausfinden, wer das ist!", progress = "Habt ihr die Angriffsbefehle?", completion = "Helix? Den Namen habe ich doch schon mal gehört. Und zwar vor gar nicht so langer Zeit, aber wer ist dieser Admiral?", rewards = "Übermantel der SpäherkuppeWeste der SpäherkuppeBrustplatte der SpäherkuppeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26287] = {title = "Die Westfallbrigade", objective = "Tötet 12 beliebige Gnolle der Flusspfoten, die die Späherkuppe angreifen.", description = "Wir waren einst als Volksmiliz bekannt. Heutzutage kämpfen wir unter der Flagge von Sturmwind mit der vollen Unterstützung von König Varian Wrynn. Wir haben viele Ziele hier in Westfall: die Unordnung, die die Defias hinterlassen haben, aufzuräumen, das Hoheitsgebiet der Allianz auszuweiten und Ordnung zu bewahren. Bisher versagen wir auf der ganzen Linie.\n\nDie Zeiten sind jetzt noch schlimmer, als zu dem Zeitpunkt, als die Defias Amok gelaufen sind. Jetzt, da die einheimischen Gnolle sich ebenfalls bewaffnet haben, sind wir in eine Ecke gedrängt worden. Helft uns, <Name>!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr habt uns eine Atempause von dem Sturmangriff der Gnolle verschafft, aber es gibt noch mehr zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26288] = {title = "Jango Fleckfell", objective = "Tötet 5 Mystiker der Flusspfoten, 5 Zuchtmeister der Flusspfoten und Jango Fleckfell.", description = "Südlich von hier befindet sich ein Landstrich von Westfall, den wir Staubebenen nennen. Soweit wir wissen, haben die Gnolle der Region die Staubebenen zu ihrem inoffiziellen Hauptquartier erklärt. Wie bei jedem Hauptquartier gibt es auch bei diesem einen Anführer. Wenn wir diesen Angriffen einen Riegel vorschieben wollen, dann müssen wir den Gnoll ausfindig machen, der den Ton angibt, und ihm das Handwerk legen.\n\nBegebt Euch zu den Staubebenen, findet den Anführer der Gnolle, Jango Fleckfell, und tötet ihn. Erledigt auch sämtliche Gnolle, die sich Euch in den Weg stellen.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Flusspfoten werden Wochen brauchen, um sich von dem Schlag zu erholen, den Ihr ihnen heute zugefügt habt. Bitte wählt einen Gegenstand als Belohnung für Eure Tat aus.", rewards = "Mystischer FlusspfotenstabFleckfellgamaschenSchienbeinschützer der StaubebenenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26289] = {title = "Findet Agentin Kearnen", objective = "Findet Agentin Kearnen.", description = "Der SI:7 hat die Bewegungen von Helix Ritzelbrecher genau beobachtet, seit er vor zwei Wochen seinen Fuß auf Allianzboden gesetzt hat. Der Brief, den ich von Mathias Shaw erhalten habe, erklärt, dass er eine Agentin namens Kearnen nach Westfall entsandt hat, um Helix zu beschatten. Findet Agentin Kearnen, dann werdet Ihr auch Helix Ritzelbrecher finden.\n\nKearnen war vor zwei Tagen in der Stadt, um Vorräte zu besorgen. Sie hat erwähnt, dass sie in der Nähe von Jagdrufs Turm südöstlich von hier in den Staubebenen zu finden sein würde.\n\nAbmarsch, <Name>.", progress = nil, completion = "Helix steckt hinter den Gnollangriffen?\n\n&lt;Kearnen nickt dem Turm zu.&gt;\n\nEr ist da drin. Er ist schon seit Tagen dort. Ich warte nur auf einen Grund, ihn hopszunehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26290] = {title = "Geheimnisse des Turms", objective = "Betretet Jagdrufs Turm und macht Helix Ritzelbrecher ausfindig.", description = "Helix hat sich oben im alten Turm von Klaven Jagdruf verschanzt. Ich werde Euch nicht belügen, <Name>, er wird schwer bewacht. Ich habe allein im Freien sechs bewaffnete Söldner gezählt. Ihr schafft es nie allein in den Turm. Zu Eurem Glück sind Claire und ich hier.\n\n<Kearnen tätschelt ihr Heckenschützengewehr.>\n\nIch gebe Euch Deckungsfeuer.\n\nNehmt diesen Verschleierungstrank; Ihr werdet ihn brauchen, wenn Ihr es ins Innere geschafft habt. Trinkt ihn, sobald Ihr den Turm betretet und steigt dann den Turm hinauf. Findet heraus, was Helix dort oben versteckt!", progress = "Ich werde Euch nicht im Stich lassen, <Name>.", completion = "Was um alles in der Welt könnte denn in Mondbruch los sein? Das alles schmeckt mir überhaupt nicht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26291] = {title = "Viel Ärger in Mondbruch", objective = "Berichtet Marschall Gryan Starkmantel an der Späherkuppe in Westfall, was Ihr herausgefunden habt.", description = "Ich werde bald meinen Bericht schreiben und nach Sturmwind zurückkehren. Der SI:7 muss über die Situation in Westfall informiert werden. Ich schlage vor, Ihr tut das gleiche und erstattet Gryan Bericht.", progress = nil, completion = "Wer ist wohl diese merkwürdige Gestalt? Wir müssen nach Mondbruch gelangen.", rewards = "BeinarbeitshosenLästige HandschuheGryans StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26292] = {title = "Auf nach Mondbruch!", objective = "Meldet Euch bei Hauptmann Alpert in Mondbruch in Westfall.", description = "Wir haben schon eine ganze Weile ein Lager in der Nähe von Mondbruch, <Name>. Einer meiner besten Soldaten ist zusammen mit einer Kompanie von der Späherkuppe in diesem Gebiet stationiert. Meldet Euch umgehend bei Hauptmann Alpert und findet heraus, ob er irgendwelche Neuigkeiten über die Vorgänge in Mondbruch hat.\n\nEin weiterer Verbündeter von mir ist auch in dem Mondbrucher Lager. Sein Name ist Thoralius. Ich habe Thoralius in Nordend während meiner Dienstzeit in Valgarde kennengelernt. Er ist ein weiser und mächtiger Schamane. Vielleicht können uns seine Fähigkeiten dabei helfen, diesen Fall zu lösen.", progress = nil, completion = "Die Einheimischen werden unruhig, &lt;Name&gt;. Ich weiß nicht, was los ist, aber die Aktivitäten der Obdachlosen in dieser Gegend haben sich in den letzten zwei Tagen vervierfacht. Wenn ich es nicht besser wüsste, würde ich sagen, die hecken etwas aus...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26293] = {title = "Kriegsmaschinen", objective = "Sprecht mit Großknecht Glibbs am Hinteren Tor von Orgrimmar in Orgrimmar.", description = "Diese \"Weltenbrecher\" verstecken sich in einer Hochlandwildnis und besetzen die Gebiete hinter den Allianzkönigreichen im Osten. Wir werden sie vernichten, und zwar mit der mächtigsten Armee seit unseren Siegen in Nordend!\n\nIch habe unsere neuen Goblinverbündeten gebeten, eine Flotte an Kriegsmaschinen zu bauen, doch die Berichte zeigen, dass ihre Arbeitsqualität manchmal... zu wünschen übrig lässt.\n\nIch werde nicht mit fehlerhaften Maschinen in die Schlacht ziehen. Trefft Euch mit Großknecht Glibbs hier in Orgrimmar und stellt sicher, dass meine Kriegsmaschinen kampfbereit sind!", progress = nil, completion = "Hab zu tun. Geht weg.\n\nWartet, was? Höllschrei schickt Euch? Was… äh… was kann ich für Euch tun? Für ihn? Für uns?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26294] = {title = "Massenversagenswaffen", objective = "Untersucht Höllschreis Verwüster, bis Ihr einen fehlerhaften Verwüster findet, und erteilt dem Chefingenieur dann eine Lektion.", description = "<Glibbs wischt sich mit einem öligen Taschentuch den Schweiß von der Stirn.>\n\nHöllschrei ist mit unserer Arbeit nicht zufrieden? Oh weh. Und wir haben \"Höllschreis Verwüster\" sogar nach ihm BENANNT. Das ist nicht gut. Meine Jungs müssen sich mehr ins Zeug legen.\n\nVielleicht könnt Ihr für uns ein Exempel statuieren. Ein neuer Satz von Höllschreis Verwüstern kam gerade aus der Produktion und ist bereit, inspiziert zu werden. Untersucht sie gründlich. Wenn Ihr Probleme findet, dann verpasst dem Chefingenieur eine Abreibung. Erinnert ihn daran, dass Höllschrei uns im Auge hat!", progress = nil, completion = "&lt;Garrosh lacht.&gt;\n\nIhr habt ihnen also ein bisschen Disziplin beigebracht, was? Gut, gut!\n\nIn meiner Horde leistet jeder seinen Beitrag, vom geringsten Peon bis hin zum stolzesten Krieger. Weniger dulde ich nicht.\n\nUnsere Vorbereitungen für die Invasion sind fast abgeschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26295] = {title = "Propaganda", objective = "Erhaltet ein Informationsflugblatt, ein geheimes Tagebuch, eine Ausgabe des Mondbrucher Blatts und mysteriöse Propaganda.", description = "Uns ist ein Anstieg der Gewalttaten unter den Obdachlosen in dieser Gegend aufgefallen. Irgendetwas oder irgendjemand versetzt sie ganz schön in Aufruhr. Wer auch immer dahinter steckt, organisiert sich immer besser. Erst vor Kurzem ist eine Gruppe Schläger hier durchgekommen und hat Flugblätter verteilt.\n\nGeht nach Mondbruch und sucht nach Beweisen. Propaganda, Handzettel, egal was... Bringt mir alles, was Ihr finden könnt. Vielleicht können wir ja den Ursprung der Schriften finden.", progress = "Konntet Ihr etwas finden?", completion = "V? Der einzige V, den ich kenne, ist van Cleef und der ist vor vielen Jahren gestorben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26296] = {title = "Beweissammlung", objective = "Sammelt 6 rote Kopftücher.", description = "Dieses Kopftuch besteht aus dem gleichen Stoff, der auch am Tatort des Brauenwirbelmordes gefunden wurde. Ihr solltet noch mehr rote Kopftücher als Beweis sammeln und Euren Fund zu Hauptmann Alpert bringen.", progress = "Rote Kopftücher?!", completion = "Ich habe seit fünf Jahren keine roten Kopftücher mehr gesehen. Ob diese merkwürdige Gestalt wohl versucht, die Bruderschaft der Defias neu zu gründen?", rewards = "BeweissammlungshandschuheAbgenutzte Armschienen der DefiasGregorkys ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26297] = {title = "Der Anbruch eines neuen Tages", objective = "Sammelt Informationen bei der Versammlung von Mondbruch.", description = "Sieht so aus, als fängt die Versammlung, von der die merkwürdige Gestalt sprach, bald an. Die Obdachlosen setzen sich in Bewegung. Ich möchte, dass Ihr an der Kundgebung teilnehmt und Informationen sammelt, <Name>.\n\nBegebt Euch zur Stadtmitte Mondbruchs und hört Euch die Ansprache an. Kehrt zu mir zurück und berichtet, was Ihr herausfinden konntet.", progress = "Was ist geschehen?", completion = "Ich konnte die Jubelschreie von hier aus hören. Wir haben es anscheinend mit einem riesigen Problem zu tun, &lt;Name&gt;. Wir müssen die Identität dieser schattenhaften Bedrohung aufdecken, bevor wir die Hilfe Sturmwinds anfordern. Vielleicht gibt es eine andere Möglichkeit...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26298] = {title = "Die Suche nach Yenniku", objective = "Beschafft 6 Hauer der Blutskalpe von Blutskalptrollen in den Ruinen von Bal'lal.", description = "Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Dunkelspeerstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.\n\nUnd ich glaube, dass der Blutskalpstamm ihn hat.\n\nWenn Ihr mir helfen wollt, dann jagt die Blutskalpe. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.", progress = "<Klasse>. Zeigt mir, dass Ihr Beute von dem Blutskalpstamm gemacht habt.\n\nZeigt mir Eure Trophäen.", completion = "Das sind gute Hauer, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr stark genug seid, um die Blutskalpe zu jagen.\n\nDas ist gut, denn die Jagd auf sie ist für Euch noch nicht vorbei.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26299] = {title = "Kopfjägerei", objective = "Beschafft 25 Schrumpfköpfe von Blutskalptrollen in den Ruinen von Zuuldaia.", description = "Wir müssen herausfinden, ob Yenniku tot ist.\n\nErschlagt die Kopfjäger der Blutskalpe und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.\n\nSollte Yenniku von den Blutskalpen getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!\n\nGeht, <Name>. Ihr könnt die Köpfe bei den Ruinen von Zuuldaia an der Küste im Norden finden.", progress = "<Name>. Ich fürchte um den Sohn unseres Häuptlings. Habt Ihr die Schrumpfköpfe, sodass ich sie untersuchen kann?", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde sie sogleich untersuchen, um sicherzugehen, dass der arme Yenniku der Axt der Kopfjäger entgangen ist.", rewards = "DschungelschreitersandalenPalmwedelschulterpolsterHandschuhe des OberaufsehersAuf Euch wartet eine dieser Belohnungen:\n\nRing der sechshundert Jahre\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26300] = {title = "Nezzliok wird es wissen", objective = "Erhaltet Nezzlioks Kopf von Nezzliok dem Düsteren in Zul'Kunda.", description = "Yennikus Kopf war nicht dabei und ich danke der großen Schlange dafür. Wir sind aber noch keinen Schritt weiter, ihn zu finden.\n\nWir müssen die Wahrheit erfahren und ich fürchte, nur der Hexendoktor der Blutskalpe wird uns helfen können. Als Feind der Dunkelspeere wird er nicht offen sprechen wollen und daher müssen wir die Wahrheit aus seinen toten Lippen zwingen!\n\nBringt mir den Kopf von Nezzliok dem Düsteren und platziert ihn hier im Kessel.\n\nIhr werdet ihn tief in Zul'Kunda finden. Bringt mir seinen Kopf... wir werden ihn schon zum Sprechen bringen.", progress = "Die grüne Brühe im Kessel brodelt.", completion = "Ihr platziert den Kopf von Nezzliok im Kessel...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26301] = {title = "Mit Nezzliok sprechen", objective = "Erhaltet eine Trophäe von Balia'mah und eine Trophäe von Ziata'jai aus den Ruinen der Schädelspalter.", description = "<Der Kopf von Nezzliok spricht.>\n\nEs stimmt. Ich weiß, wo das Kind der Dunkelspeere hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!\n\nDie Blutskalpe streiten mit den Schädelspaltern. Um mein Wohlwollen zu erhalten, stehlt zwei der meist geschätzten Trophäenschädel von den Schädelspaltern östlich des Flusses. Legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah und der zweite von Ziata'jai stammen.", progress = "Ich erwarte die Schädel...", completion = "Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in den Nether eintreten!\n\nIhr seid eine Zierde Eures Klans, &lt;Volk&gt;, und Ihr habt mich beschwichtigt.", rewards = "Ziata'jaiarmschienenBalia'mahgamaschenKettenpanzerrüstung des SklavenhändlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26302] = {title = "Yennikus Schicksal hinterher", objective = "Sprecht mit Kin'weelay in Bambala.", description = "<Nezzliok spricht.>\n\nIhr habt mich und meinen Meister beschwichtigt und ich werde Euch die Informationen geben, nach denen es Euch verlangt...\n\nDer junge Yenniku ist verloren.\n\nEr wurde von Hexendoktor Zanzil dem Ausgestoßenen entführt. Jetzt sind sein Geist und sein Körper in Zanzils Kontrolle und nur die stärkste aller Magien kann ihn davon befreien.\n\nMagie, die Euch nicht zur Verfügung steht, <Klasse>.\n\nVielleicht können Eure Verbündeten der Dunkelspeere in Bambala östlich von einen Hoffnungsschimmer zur Erlösung Yennikus darstellen. Aber das bezweifle ich.", progress = nil, completion = "Zanzil der Ausgestoßene??\n\nWenn Yenniku von diesem Troll, einem bösartigen und mächtigen Hexedoktor, gefangen gehalten wird, dann befürchte ich, dass nur das kleinste bisschen Hoffnung übrig bleibt. Das Allerkleinste. So klein wie das kleinste aller Insekten.\n\nIch habe aber auch einen Verdacht. Ein Verdacht, der zu Yennikus Erlösung führen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26303] = {title = "Das Gedankenauge", objective = "Erhaltet das Gedankenauge von Mai'Zoth.", description = "Das Gedankenauge befindet sich bei einem Ogermagier, im Ogerhügel der Mosh'Ogg südlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Dunkelspeere im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.\n\nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.\n\nIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.", progress = "Seid gegrüßt, <Name>. Die Geister lobpreisen Euren Mut, aber sie sagen mir nichts von Eurem Kampf gegen Mai'Zoth.\n\nHabt Ihr das Auge?", completion = "Ihr habt das Auge geholt! Eure Macht ist der Stoff, aus dem Legenden sind, &lt;Name&gt;!\n\nUnd da Ihr im Besitz des Auges seid, müsst Ihr Mai'Zoth besiegt und ihn in den Nether geschickt haben. Darum wollten die Geister zuvor nicht von ihm sprechen.\n\nEs ist gut, dass er diese Welt des Fleisches und der Knochen verlassen hat, aber nun, da er im Reich der Geister wandelt... fürchte ich, wird er dort erneut die Macht ergreifen.\n\nAber darum sorge ich mich ein anderes Mal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26304] = {title = "Wenn es Nacht wird im Dschungel", objective = "Löscht 8 Kohlenpfannen von Zul'Mamwe in Zul'Mamwe im Nördlichen Schlingendorntal.", description = "Vor einem Jahr wurde meine Mutter - die Trollfrau, die mich großzog - von den Schädelspaltern Zul'Mamwes gefangen genommen. Jung und eigen wie ich war machte ich mich auf, um sie zu retten, nur um zu sehen, wie sie von einem Dutzend Krieger auf eine riesige brennende Kohlenpfanne zugestoßen wurde. Ich versteckte mich hinter einem Baum und sah zu, wie sie sie packten und.. und..\n\n<Kil'karil senkt seinen Blick.>\n\nWenn es Nacht wird wird das Licht der Kohlenpfannen von den Bäumen reflektiert und hält mich wach. Bitte, <Name>... reist nach Süden nach Zul'Mamwe und löscht die Kohlenpfannen.", progress = nil, completion = "Der Geist meiner Mutter wird heute in Frieden ruhen, &lt;Name&gt;.\n\nUnd ich auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26305] = {title = "Yennikus Rettung", objective = "Bringt den gefüllten Seelenedelstein zu Nimboya.", description = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.\n\nMeine anfänglichen Vermutungen waren korrekt: die Geister sagen mir, dass Yenniku nicht bei Zanzil dem Ausgestoßenen ist, sondern in den Ruinen von Zul'Mamwe im Südwesten. Kehrt zu Nimboya in Grom'gol zurück, sobald Ihr Yennikus Seele befreit habt.", progress = "<Name>. Kin'weelay sagte mir, er habe Euch ausgesandt, Yenniku zu finden.\n\nIst es wahr? Habt Ihr ihn?", completion = "Ihr habt es geschafft! Ihr konntet Yenniku vom Willen Zanzils und der Tyrannei der Schädelspalter befreien und so die Mission erfüllen, die ich kurz vorm Scheitern sah.\n\nZanzil ist noch immer eine Bedrohung für das Schlingendornkap, aber zumindest weiß ich jetzt, dass die Seele des Häuptlingssohnes frei ist.\n\nUnser Stamm wird Euren Namen in Liedern ehren, &lt;Name&gt;, und wir werden Eure Geschichte in Stein ritzen, so dass sie auf ewig leben wird.", rewards = "SteinätzerSpinner der unendlichen ErzählungNimboyas BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26306] = {title = "Anfang der Zurückeroberung", objective = "Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha'Alor.", description = "Heute fangen wir mit dem ersten Angriff auf das Herz des wilden Blutfratzenstamms an. Zeigt ihnen keine Gnade, <Name>. Hier geht es um mehr als Rivalität unter Trollen. Jeder Sieg der Bruchhauer ist ein Sieg für die Horde!\n\nDie Kopfjäger der Blutfratzen und Hexendoktoren müssen zuerst beseitigt werden. Greift die unteren Terrassen an und erstattet mit Blut an Eurer Waffe Bericht bei mir.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Lasst die Blutfratzen vor Angst fliehen, die ihnen durch Euren Anblick eingeflößt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26307] = {title = "Tod den Blutfratzen", objective = "Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha'Alor.", description = "Wir werden ihnen nicht erst die Gelegenheit geben, auf unseren Angriff zu reagieren. Ihr müsst zurück nach Jintha'Alor und Euch den Weg zu den höheren Ebenen freikämpfen.\n\nDie Berserker und Schattenzauberer der Blutfratzen sind gefährliche Gegner, <Name>. Wenn die anderen sehen, wie ihre Leichen über die Mauern geworfen werden, so werden sie wissen, WIE ernst wir es meinen.\n\nIch möchte kein Blutfratzenherz mehr schlagen hören!", progress = nil, completion = "Es wird nicht mehr lange dauern und wir sind die einzigen atmenden Trolle bei diesen Mauern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26308] = {title = "Das gehört jetzt uns", objective = "Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha'Alor.", description = "Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.\n\nSie sind NARREN! Sie halten an altem, falschem Glauben fest. Ich werde ihre Verbrechen gegenüber den Bruchhauern nicht länger dulden.\n\nMacht Euch zum finalen Angriff auf. Nehmt Jintha'Alor für die Bruchhauer ein... nehmt es für die Horde ein!", progress = nil, completion = "Nun ist niemand mehr übrig, der sich den Bruchhauern in den Weg stellen kann! Um Nachzügler können wir uns problemlos kümmern.\n\nIhr habt meinem Volk eine große Ehre erwiesen, &lt;Name&gt;.", rewards = "BluttrinkerstabSeelenfresserschulterschutzAuf Euch wartet eine dieser Belohnungen:\n\nStumpfhaueranhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26309] = {title = "Dunkle Gefäße", objective = "Beschafft 5 Gefäße mit besudeltem Blut aus Jintha'Alor.", description = "Die Trolle der Blutfratzen hier haben früher das verdorbene Blut des Gottes Hakkars getrunken, um Macht zu erlangen. Sie haben es, bevor sie es tranken, in primitiven Kesseln gekocht - dunkle Gefäße voller unheiliger Stärke.\n\nHakkar wurde natürlich vor langer Zeit schon getötet. Doch das Interessante ist... Ich sehe immer noch Kessel, die hier oben blubbern. Bringt mir einige her und dann sehen wir, was sie so zusammenbrauen.", progress = "Seid vorsichtig in der Nähe der Kessel, <Klasse>. Die Blutfratzen werden nicht kampflos zulassen, dass Ihr ihre Leckereien wegnehmt.", completion = "Erst Spinnen und jetzt das hier. Ich kann das Gift in seinem Blut reichen... Es ist dasselbe wie bei den Huschern, nur stärker.\n\nDie Blutfratzen und Spinnen... Ich sehe da Potential.", rewards = "Sandalen des besudelten BlutesSandrenes Unsichtbare WesteSpinnengiftgamaschenBrustplatte des dunklen GefäßesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26310] = {title = "Alles, was krabbelt", objective = "Sammelt 8 huschende Spinnlinge in Jintha'Alor.", description = "Bevor Ihr dort hoch geht, <Klasse>...\n\nIch kenne ein paar Verkäufer, die sehr interessiert an starken Giften sind. Mir sind die Spinnen in der Gegend natürlich nicht entgangen... sie sind nicht riesig, aber ungefähr so groß wie Euer Hand.\n\nSie haben eine Färbung, die ich noch nie zuvor in der Gegend gesehen habe. Könntet Ihr ein paar sammeln und mir bringen?", progress = "Wie viele habt Ihr gefunden?", completion = "Oh ja... es war gut von mir, Euch zu beten, mir diese Spinnlinge zu bringen. Sie sind so faszinierend.\n\nKommt her, meine Hübschen. Hier in meine Tasche, so ist es brav.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26311] = {title = "Unbekannte Gewässer", objective = "Findet Herezegor Flammenhauer in der Kneipe \"Zum Wyvernschweif\" im Tal der Ehre in Orgrimmar und besorgt Euch eine Küstenkarte des Schattenhochlands.", description = "Der Kriegshäuptling plant einen großangelegten Angriff auf das Schattenhochland. Wir hoffen, dass wir uns dort mit den Orcs des Drachenmals verbünden können.\n\nMeine Quellen haben mir berichtet, dass ein Orc des Drachenmalklans hier in Orgrimmar lebt. Er ist als Herezegor Flammenhauer bekannt und führte einst ihre Krieger an.\n\nSein Wissen als einer von ihnen ist für uns von größtem Wert. Findet Flammenhauer und besorgt uns eine Karte der Wasserwege im Schattenhochland.\n\nLaut meinen letzten Informationen hielt er sich in einer Kneipe im Tal der Ehre auf...", progress = "<Sauranok ist überrascht, Euch so bald wiederzusehen.>\n\nAh, <Klasse>, Ihr seid zurück. Was habt Ihr herausgefunden?", completion = "&lt;Sauranok scheint sich nicht für die Karte zu interessieren, während Ihr Eure Geschichte erzählt.&gt;\n\nZwielichtassassinen sind Euch in die Kneipe gefolgt? Hier in Orgrimmar?\n\nDer Kriegshäuptling wird alles andere als erfreut sein, das zu hören.\n\nFahrt mit Euren Vorbereitungen für den Einmarsch fort. Ich versuche, mehr darüber herauszufinden.", rewards = "In Ehrfurcht erstarrte ArmschienenHalsberge des SchocksKlingenausweichender GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26312] = {title = "Bröckelnde Verteidigung", objective = "Entlastet Tawn Winterfels, Sturmruferin Mylra und Hargoth Trübflamm, indem Ihr ihnen helft, ihre Gegner zu besiegen.", description = "Als der Angriff begann, sind wir nach vorne geprescht, um das Feld so schnell wie möglich einzunehmen. Ihre Streitkräfte waren schier unerschöpflich... wir haben sie unterschätzt. Nun sitzen einige unserer besten Schamanen da draußen fest, gestrandet, erschöpft und weit entfernt von unserer Verteidigung.\n\nBegebt Euch auf das Feld und entlastet unsere gestrandeten Brüder. Selbst eine kleine Pause vom Kampf sollte ihnen die Gelegenheit geben, endlich einmal durchzuatmen.\n\nBeeilt Euch, <Klasse>.", progress = "Vielleicht war es dumm von mir, sie so weit nach vorne zu schicken. Alles, was ich über die Erdelementare weiß, deutete darauf hin, dass solch ein Angriff nicht lange andauern könnte… dass sie nur ihrem Zorn freien Lauf lassen und sich genauso schnell wieder beruhigen.\n\nJetzt weiß ich, dass ich falsch lag.", completion = "Vielen Dank, &lt;Klasse&gt;. Viele Anhänger des Irdenen Rings verdanken Euch heute ihr Leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26313] = {title = "Der Kern unserer Sorgen", objective = "Sammelt 6 Zornsteinkerne.", description = "Elementare sind von Natur aus chaotisch, doch diese organisierte Aggressivität passt einfach nicht zu ihnen. Besonders hier unten, wo ihr Tod ein bisschen dauerhafter ist. Ich vermute, die Steinmutter Therazane steckt dahinter, aber ich muss Gewissheit haben.\n\nVernichtet die Zornsteinrumpler und bringt mir ihre Kerne. Wenn wir es mit dem Hass der Steinmutter zu tun haben, werden wir die Sache hier und jetzt erledigen.", progress = "Die Elementarlords waren nie unsere Freunde, aber wir haben dennoch auf ein gewisses Maß an Sicherheit in ihrem Chaos vertraut. So lange sie unorganisiert bleiben, haben wir nur wenig zu fürchten.\n\nWenn die Steinmutter jedoch tatsächlich die Erde gegen uns in den Kampf führt, haben wir Einiges zu befürchten.", completion = "Die sind in einem überraschend guten Zustand. Gute Arbeit, Mann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26314] = {title = "Fest auf dem Boden", objective = "Benutzt die Elementiumwurfleine, um 3 Diener von Therazane von den Füßen zu holen.", description = "Wir können von Glück sagen, dass diese Riesen so schlecht zielen. Doch irgendwann wird das Glück auf ihrer Seite sein.\n\nWir müssen sie aus dem Kampfgeschehen nehmen, aber ihnen direkt gegenüberzutreten ist wohl keine gute Idee.\n\nNehmt dieses Wurfleine, werft sie ihnen um einen Knöchel und zieht ihnen die Füße weg. Sobald sie am Boden liegen, sollten sie leicht zu besiegen sein.", progress = nil, completion = "Das wird ihren Angriff ein wenig verlangsamen, bis Norsala einen Weg gefunden hat, sie zu besänftigen. Wir haben kein Bedürfnis, weiter Feinde von Therazane der Steinmutter zu bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26315] = {title = "Ein imposantes Aufeinandertreffen", objective = "Lest Boden dem Imposanten die Proklamation des Irdenen Rings vor.", description = "Habt Ihr den Riesen gesehen, der bedrohlich im Nordwesten aufragt? Das ist Boden der Imposante, einer der Steinlords von Therazane der Steinmutter.\n\nWir wissen nicht viel über die Steinlords, aber Boden zählt nicht gerade zu den Sanftmütigen seiner Art. Leider führt ausgerechnet er den Angriff an, also müssen wir ihm gegenübertreten.\n\nBringt diese Proklamation zu ihm und lest sie im Namen des Irdenen Rings laut vor. Ich weiß, es ist ganz schön optimistisch zu hoffen, dass Worte dies beilegen können, aber wir müssen es versuchen. Seid vorsichtig.", progress = "Hattet Ihr schon die Gelegenheit, Boden gegenüberzutreten?", completion = "Ja… genau diese Reaktion hatte ich erwartet.\n\nDoch er hat Diamant erwähnt? Wenn die beiden nicht miteinander auskommen, ist dieser Diamant vielleicht nicht so unbändig wie Boden. Zumindest besteht eine kleine Hoffnung.\n\nMal sehen, ob ich die Erde dazu bringen kann, mir den Aufenthaltsort dieses Diamant zu verraten.", rewards = "Feste GriffeVertrauenerweckende GugelAuf Euch wartet eine dieser Belohnungen:\n\nInsigne der Diplomatie\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26316] = {title = "Worauf wartet Jessup?", objective = "Findet Jessup McCree in seinem Lager nahe der Höhle der Frostmähnen.", description = "Der Kataklysmus öffnete tiefe Spalten unter der Höhle der Frostmähnen. Troggs stürmten daraufhin aus ihren Bauten. Es gelang ihnen, die Trolle, die dort lebten, zu verjagen und das gleiche Schicksal blüht uns auch, wenn wir nicht handeln.\n\nHochtüftler Mekkadrill hat den bekannten Demolierer Jessup McCree angeheuert, um die Spalten zu versiegeln und den Ansturm der Troggs zu beenden. Er hat uns noch nicht mitgeteilt, ob es ihm gelungen ist, die Troggs aufzuhalten. Würdet Ihr in seinem Lager nahe der Höhle der Frostmähnen, südlich des Toxischen Flugplatzes nach ihm suchen?", progress = nil, completion = "Die Tunnel zu sprengen, ist nicht schwer, aber dafür brauche ich mein Team und meine Ausrüstung. Vorher kann ich nicht anfangen.", rewards = nil}
MultiLanguageQuestData['de'][26317] = {title = "Ein Schmetterschwanzjunges", objective = "Bringt das Schmetterschwanzjunge zu Scharfseher Mok'thardin im Basislager Grom'gol.\n\nBereitgestellter Gegenstand: \n", description = "Als Ihr das letzte der Schmetterschwanzeier zerstört habt, seht Ihr, wie ein neugeborenes Schmetterschwanzjunges Euch anschaut. Ihr seht, wie es Euch genau betrachtet, Eure Gesichtszüge untersucht und alle Eure Bewegungen aufmerksam verfolgt.\n\nDas Schmetterschwanzjunge hat Euch in sein Herz geschlossen.\n\nEigentlich solltet Ihr die Bevölkerung der Raptoren ausmerzen, aber Ihr habt alle Eier zerstört, die von Euch zerstört werden sollten, und dieser Raptor ist ein unschuldiges Jungtier. Vielleicht weiß jemand im Basislager Grom'gol, was man mit einem Raptorenjungen anfangen kann.", progress = nil, completion = "Ja, die Kleine scheint einen Narren an Euch gefressen zu haben. Ich vermute, dass ein einzelner Raptor, noch dazu, wenn er unter Orcs aufwächst, eine viel geringere Gefahr sein wird, als ein ganzes Rudel. Behaltet sie, &lt;Name&gt;... vielleicht erweist sie sich noch als nützlich.\n\nUm genau zu sein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26318] = {title = "Eine unvollendete Aufgabe", objective = "Dringt zum Ende der Höhle in der Höhle der Frostmähnen vor, tötet Boss Bruggor und aktiviert den Zünder, um die Troggtunnel zum Einsturz zu bringen.", description = "Mein Team hat die Pulverfässer und den Zünder bereits am Ende der Höhle im westlichen Teil der Höhle der Frostmähnen angebracht. Ihr müsst nur dorthin vordringen und den Zünder aktivieren, dann explodiert das Pulver und die Tunnel brechen ein.\n\nDann werden die Troggs die Tiefen der Erde nicht mehr verlassen. Mekkadrill wird mit den restlichen Troggs leichter fertigwerden, wenn Ihr ihren Anführer, der sich selbst Boss Bruggor nennt, ausschaltet. Viel Glück, <Name>.", progress = nil, completion = "Ich konnte die Explosion selbst hier oben spüren! Meine Jungs haben die Sprengung gut vorbereitet, aber ohne Eure Hilfe hätte uns das nichts genutzt. Es ist nur gerecht, wenn ich mein Vertragshonorar mit Euch teile. Schließlich habt Ihr unsere Aufgabe vollendet.", rewards = "GeschwindigkeitsarmschienenBeschleunigungsgürtelSpannungshandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26319] = {title = "Gelöste Geheimnisse", objective = "Sprecht mit Thoralius dem Weisen in Mondbruch in Westfall.", description = "Es gibt hier einen Schamanen, Thoralius, der uns vielleicht helfen kann. Er ist ein Freund von Gryan und ist vor Kurzem nach Westfall gekommen, um die elementare Verwüstung zu untersuchen, die über uns hereingebrochen ist.\n\nSprecht mit Thoralius und seht, ob er etwas Licht auf die Identität dieser merkwürdigen Gestalt werfen kann.", progress = nil, completion = "Hmm, ja, vielleicht kann ich Euch helfen. Als ich in Nordend war, habe ich den Einwohnern von Valgarde dabei geholfen, einige der Geheimnisse der Vrykul aufzudecken, indem ich in die Geisterwelt eingetaucht bin. Vielleicht kann ich dasselbe auch hier tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26320] = {title = "Eine Vision aus der Vergangenheit", objective = "Betretet das Versteck der Defias und folgt der Spur der Obdachlosen in die Todesminen. Betretet den Dungeon \"Die Todesminen\" und benutzt das Räuchergefäß, um in die Vergangenheit zu blicken.", description = "Dieser Weihrauch wird Euren Körper und Euren Geist in tiefe Meditation versetzen. Sobald die Trance beginnt, werdet Ihr in die Geisterwelt übertreten. Wehrt Euch nicht gegen die Trance, sobald sie begonnen hat, <Name>. Erlaubt den Geistern, Euch zu zeigen, was sie wissen.\n\nIhr müsst nun aufbrechen. Begebt Euch zu den Todesminen, ein Ort, der angeblich eine große Rolle in der Geschichte Westfalls gespielt hat. Sobald Ihr im Inneren seid, benutzt den Weihrauch.\n\nIhr gelangt durch das alte Bauernhaus südlich von hier in die Todesminen. Folgt den Obdachlosen.\n\nKehrt zu Gryan zurück und berichtet ihm von dem, was Ihr erfahren habt.", progress = nil, completion = "WAS? Van Cleef hatte eine Tochter?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26321] = {title = "Ich glaube, sie hat Hunger", objective = "Tötet Murlocs der Düsterkiemen im Nördlichen Schlingendorntal und gebt Eurem Schmetterschwanz 40 Bissen Murlocfleisch.", description = "Ich glaube, Euer Raptorenjunges ist hungrig. Wenn Ihr sie behalten wollt, solltet Ihr Essen für sie finden, nicht wahr? Schmetterschwänze greifen oft das Lager der Düsterkiemen nördlich von hier an.\n\nSie ist wahrscheinlich noch nicht stark genug, um selbst zu jagen, aber frisches Murlocfleisch kann sie sicher schon essen.", progress = nil, completion = "Sie sieht schon ein bisschen größer aus! Ihr müsst wissen, dass Raptoren schnell wachsen. Ihr habt Glück, so einen starken Begleiter gefunden zu haben.\n\nBehaltet sie, so lange Ihr könnt, &lt;Name&gt;. Sie wird sich sicherlich bald als sehr wertvoll für Euch erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26322] = {title = "Aufstieg der Bruderschaft", objective = "Werdet Zeuge des Aufstiegs der Bruderschaft.", description = "Ich hatte ja keine Ahnung, dass van Cleef eine Tochter hatte, <Name>. Wenn es etwas gab, in dem der Mann außerordentlich gut war, dann war es, Geheimnisse zu bewahren.\n\nWie tragisch. Das arme Ding hat eine schreckliche Tat mit angesehen. Hätte ich doch nur etwas geahnt.\n\nWas war das? Habt Ihr etwas gehört? Scheint so, als ziehen sich die Gnolle zurück... wo sind meine Wachen?\n\nPASST AUF, <Name>!", progress = nil, completion = "Ich werde sofort ein Bataillon nach Westfall entsenden! Nun da die Bruderschaft der Defias neu gegründet worden ist, ist eine alte Bedrohung für das Königreich wiederauferstanden.", rewards = "Dolch des Hauses WrynnHellebarde des Hauses WrynnArmbrust des Hauses WrynnStab des Hauses WrynnClaymore des Hauses WrynnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26323] = {title = "Lieblingsschädel", objective = "Kehrt zu Nimboya im Basislager Grom'gol zurück und zeigt ihm den Lieblingsschädel von Eurem Schmetterschwanzjungen.\n\nBereitgestellter Gegenstand: \n", description = "Euer Raptor scheint ein neues Spielzeug gefunden zu haben: einen Schädel aus einem Haufen von Trollschädeln.\n\nIhr wisst nicht, warum sie diesen Schädel allen anderen bevorzugt, aber aus irgendeinem Grund lässt sie nicht von ihm ab.\n\nNimboya im Basislager Grom'gol ist eine Art Schädelexperte, wenn man von dem Schädelhaufen ausgeht, den er hat. Vielleicht weiß er, was an diesem Schädel so besonders ist.", progress = nil, completion = "Was haben wir hier? Ein Schmetterschwanzjunges und ihren Goblinbegleiter.Hah!\n\nUnd weitaus wichtiger, was für einen Schädel habt Ihr da? Das war kein normaler Troll. Es war ein sehr großer Troll...\n\n&lt;Nimboya klopft auf die Schädeldecke.&gt;\n\n... und ein sehr starker. Mal sehen, was wir damit machen können.\n\nGeht nicht weg.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26324] = {title = "Wo ist meine Kriegsflotte?", objective = "Sprecht mit Kriegsfürst Krogg am Bilgepier in Azshara.", description = "Wir haben eine Karte von den Zugängen zum Schattenhochland. Unser Plan ist eindeutig: Wir werden uns mit unserer kompletten Streitmacht zeigen. Wenn die Orcs des Drachenmals unsere ganzen Truppen an ihrem Strand sehen, haben sie keine Wahl, außer sich mit uns zu verbünden und uns bei unserem Kreuzzug gegen den Schattenhammer zu unterstützen.\n\nDie Flotte wird im Bilgepier in Azshara zusammengebaut, doch sie kommen für meinen Geschmack viel zu langsam voran.\n\n<Klasse>! Ihr seid geschickt darin, die Räder an meinen Kriegsmaschinen zu ölen. Sucht nach Kriegsfürst Krogg in Azshara und findet heraus, was da so lange dauert.", progress = nil, completion = "Was? Noch eine Nachricht von Höllschrei? Sein Geduldsfaden ist dünner als Elfenhaar.\n\nHabt Ihr je mit Goblins zusammengearbeitet? Überall sind weitere versteckte Kosten. Unsere Schiffe liegen halb zusammengebaut im Hafen und unsere Luftflotte ist in alle Winde zerstreut.\n\nWenn diese Invasion tatsächlich stattfinden soll, brauche ich Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26325] = {title = "Ein Gespür für solche Dinge", objective = "Lasst Euer Schmetterschwanzjunges 8 Fetische von Zuuldaia aufspüren.", description = "<Der Schädel spricht zu Euch.>\n\nIch lebe? Nein, ich lebe nicht... aber ich kann leben.\n\nEuer Raptor ist sehr schlau, wenn er meinen Schädel in einem Haufen so vieler Schädel gefunden hat. Zu Lebzeiten war ich ein starker, mächtiger Troll, ein Fürst unter den Trollen. Mit Eurer Hilfe kann ich wieder ein Fürst sein.\n\nDie Blutskalpe in Zuuldaia haben magische Fetische, die mir zur Rückkehr verhelfen können. Sie verstecken die Artefakte unter dem Sand. Euer Schmetterschwanzjunges wird diese Artefakte finden können, <Name>... wenn Ihr sie habt, werft sie in den Kessel.", progress = "<Der große Trollschädel taucht aus dem brodelnden Kessel auf.>\n\nWie viele konntet Ihr finden?", completion = "&lt;Ihr fügt die Fetische dem Kessel hinzu.&gt;\n\nJa... jaaaaa...\n\nMein Geist ist wieder stark, &lt;Name&gt;, und ich bin bereit, in die Welt zurückzukehren. Jetzt brauche ich einen Körper.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26326] = {title = "Die Erde unter unseren Füßen", objective = "Sucht nach Erdenrufer Torunskar direkt nordwestlich des Tempels der Erde in der Zackenwüste.", description = "Nur noch ein Teil der Weltensäule fehlt, und der befindet sich in den Händen der Steinmutter selbst. Schlimmer noch, der Tempel wird von Elementaren und Riesen belagert. Selbst einem Narr dürfte klar sein, dass sie auf ihren Befehl hin handeln.\n\nGeht und stellt Euch den Elementaren im Nordwesten im Kampf. Beratet Euch mit Torunskar und Norsala und findet einen Weg, um mit ihren Anführern zu sprechen und die Weltensäule zu finden. Wir ziehen eine friedliche Beilegung vor, aber wir werden alles tun, was nötig ist, um den Riss zu schließen.", progress = nil, completion = "Hey, Mann! Vielen Dank für Euer Kommen.\n\nWir waren auf diese Art von Angriff nicht vorbereitet. Wir haben den Schattenhammerkult erwartet, aber nicht die Elementare. Ich habe keine Ahnung, was sie so sehr in Aufruhr versetzt hat, dass sie sich plötzlich gegen uns wenden.\n\nIhr habt doch keine von ihnen getötet, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26327] = {title = "Ambossar der Held", objective = "Redet mit Thargas Ambossar.", description = "Ihr verschwendet nur Eure Zeit, wenn Ihr jetzt mit mir reden wollt, <Junge/Mädchen>. Thargas Ambossar hält sich auf der anderen Seite dieser Wagen auf.\n\nIhr habt von ihm gehört, oder? Er hat an der Seite des Königs von Sturmwind den Thandolübergang gegen die Dunkeleisenzwerge verteidigt! Er ist einer der größten Helden von Eisenschmiede.\n\nAber jetzt steckt er bis zum Hals in Ärger! Geht zu ihm und lasst ihn wissen, dass Ihr helfen wollt. Aber haltet Abstand; er holt weit aus.", progress = nil, completion = "Seid gegrüßt! Wenn Ihr eine Waffe habt, könnt Ihr mir gern helfen, diese verrückten Narren loszuwerden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26328] = {title = "Steinige Beziehungen", objective = "Findet Diamant den Geduldigen am nordöstlichen Rand der Zackenwüste.", description = "<Norsala legt die Hand auf den Boden, um Diamants Aufenthaltsort herauszufinden, springt jedoch sofort schockiert zurück.>\n\nMeine Güte! Das habe ich nicht erwartet. Diamant ist gar nicht weit entfernt. Als ich eine Verbindung zu ihm aufbaute, hat er geantwortet und mir gesagt, wo wir ihn finden können. Geht zum nordöstlichen Rand der Zackenwüste. Diamant erwartet Euch.\n\n<Name>, seid vorsichtig. Es sieht Erdgeschöpfen zwar nicht ähnlich, einen Hinterhalt zu planen, aber es sah ihnen auch nicht ähnlich, den Tempel überhaupt zu belagern.", progress = nil, completion = "Ah… Ihr müsst der &lt;Klasse&gt; sein, den ich erwarte.\n\nAlso kommt Ihr im Namen des Irdenen Rings?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26329] = {title = "Und noch etwas", objective = "Bringt Jessups Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt.", description = "So, dann werde ich meine Sachen packen und mich der nächsten Aufgabe widmen. Irgendwo gibt es immer etwas zu sprengen. Irgendwo gibt es einen Berg, der bewegt werden muss oder eine Schlucht, die gegraben werden muss. Dafür bin ich da.\n\nWürdet Ihr mir vielleicht noch einen Gefallen erweisen? Würdet Ihr diesen Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt bringen? Er sollte wissen, dass die Troggs seinem Volk in nächster Zeit keine Probleme mehr machen werden.", progress = "Willkommen zurück, <Name>.", completion = "&lt;Der Hochtüftler liest Jessups Bericht.&gt;\n\nGroßartige Neuigkeiten! Ohne die Troggs können wir unsere Aufmerksamkeit endlich dem Ärger widmen, den Ritzelstoß veranstaltet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26330] = {title = "Wer ist ein großer Troll?", objective = "Holt Gan'zulahs Leiche aus Zul'Kunda.", description = "<Der Schädel spricht erneut.>\n\nMeine Seele ist bereit, doch mein Körper ist es nicht. Die Blutskalpe haben meinen alten Körper vor langer Zeit entweiht. Die Schrecken, die sie mir zugefügt haben... mein Geist sah dabei zu, als sie meinen Körper in Stücke rissen und... und... ich kann es nicht erzählen.\n\nIhr Häuptling, Gan'zulah, leitete diese grauenvollen Taten. Wenn ich mich recht erinnere, so war er ein starker, mächtiger Troll... ungefähr so groß wie ich. Was für ein interessanter Zufall.\n\nIhr wisst, was Ihr zu tun habt, <Name>. Beeilt Euch.", progress = "<Ihr hört die Stimme des Schädels:>\n\nGan'zulah...", completion = "Ihr habt Gutes getan, &lt;Name&gt;. Es gilt nur noch eine Aufgabe zu erfüllen, bevor ich zurückkehren kann.", rewards = "JujugürtelWeggeworfene TrollgamaschenElektrostatische BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26331] = {title = "Ritzelstoß' Handlanger", objective = "Tötet 8 von Ritzelstoß' Handlangern in Ritzelstoß' Arsenal. Ihr könnt wahlweise bestrahlte Techniker oder Ritzelstoß' Kampfanzüge töten.", description = "Unser alter Feind Thermadraht versucht uns mit allen Mitteln vom Wiederaufbau und der Rückeroberung Gnomeregans abzuhalten. Er hat einen seiner loyalsten Schergen, Razlo Ritzelstoß und einen Trupp bestrahlter Gnome ausgesandt, um uns zu terrorisieren.\n\nSie haben sich in einem alten Arsenal auf der Straße nach Norden verschanzt. Ritzelstoß' Techniker reparieren die Waffen dort. Wir müssen sie aufhalten, bevor die Mechanopanzer einsatzbereit sind. Geht zu Ritzelstoß' Arsenal und eliminiert alle Techniker, die Ihr findet.", progress = nil, completion = "Das sollte Ritzelstoß ein wenig aufhalten, aber wir dürfen nicht ruhen, bevor er besiegt und das Frosthauchtal sicher ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26332] = {title = "Mojo der Schädelspalter", objective = "Erhaltet 6 Mojos der Schädelspalter von Trollen der Schädelspalter in den Ruinen von Ziata'jai und den Ruinen von Balia'mah.", description = "<Der Schädel spricht wieder.>\n\nDank Euch und Eurem Raptor habe ich meinen Körper. Wenn ich mich recht erinnere, so braucht Ihr und Euer Freund, der Hexendoktor, Mojo, um das Ritual abzuschließen.\n\nDie Blutskalpe haben Mojo in Zul'Kunda, aber es ist schwach. Das Mojo der Dunkelspeere wird auch nicht ausreichen. Nein... wir brauchen das Mojo der Schädelspalter. Ihr könnt sie auf der anderen Seite des Flusses östlich von hier finden.\n\nBeeilt Euch, <Volk>. Ich werde Euch zusehen...", progress = "<Der große Trollschädel treibt im Kessel umher.>", completion = "&lt;Ihr fügt das Mojo dem Kessel hinzu.&gt;\n\nAusgezeichnete Arbeit, &lt;Volk&gt;. Ihr und Euer Raptor haben eine große Tat vollbracht. Hakkar wäre sehr erfreut...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCosmetic - Cauldron Explosion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26333] = {title = "Keine Panzer!", objective = "Benutzt die Techno-Granate, um 5 reparierte Mechanopanzer in Ritzelstoß' Arsenal zu vernichten.", description = "Wir haben bereits einige Späher bei dem Versuch verloren, herauszufinden, was Razlo Ritzelstoß mit all den Mechanopanzern vorhat, die seine bestrahlten Techniker reparieren.\n\nWir dürfen nicht noch mehr Zeit verlieren. Wir müssen handeln, bevor Ritzelstoß seine Anhänger und seine Waffen auf uns hetzt.\n\nIn dieser Techno-Granate befindet sich genügend Sprengkraft, um die Mechanopanzer zu zerstören. Dann wird Ritzelstoß sie nicht mehr verwenden können. Nehmt sie mit nach Norden, auf die Straße, die zu Ritzelstoß' Arsenal führt, und vernichtet diese Panzer!", progress = nil, completion = "Mekkadrill wird zufrieden sein, wenn er erfährt, dass Ihr Ritzelstoß davon abgehalten habt, seine Anhänger mit unseren alten Waffen auszurüsten. Wenn er die Mechanopanzer nicht einsetzen kann, wird er schwach und angreifbar sein.", rewards = "Gürtel des freien KörpersKraftanwendende HandschuheTräge ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26334] = {title = "Blutfürst Mandokir", objective = "Bringt das Eierfragment eines Schmetterschwanz' zu Blutfürst Mandokir im Basislager Grom'gol.", description = "<Volk>. <Volk>, <Volk>, <Volk>... Ihr dachtet nicht, ich wäre Euch freundlich gesinnt, oder, <Volk>? Ah, ha, hahahaa!\n\nIhr habt Euren Zweck erfüllt. Ich bin ins Reich der Lebenden zurückgekommen und das nur dank Euch. Anstatt Euch zu töten werde ich Euch also ein Angebot machen.\n\nGebt mir den Raptor.\n\nIhr solltet bereits gemerkt haben, dass sie kein normaler Schmetterschwanz ist und ich brauche einen Ersatz für Ohgan. Tut, was ich sage, oder Ihr und Euer Hexendoktor werdet meine Wut zu spüren bekommen.", progress = "Ich will nicht mehr als den Raptor, <Name>. Gebt sie mir und Ihr und der Troll könnt weiterleben.", completion = "Gut, dass Ihr zu Sinnen kommt.\n\nVielleicht wollt Ihr mich ja mal in Zul'Gurub besuchen, &lt;Volk&gt;. Ich werde Euch im Auge behalten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBloodlord Mandokir: Summon Mandokir Running (H)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26335] = {title = "Macht die Marine startklar", objective = "Untersucht den Rumpf der Feindbrecher.", description = "Höllschrei erwartet eine Armada von Schiffen für seinen Einmarsch, aber die Arbeiten hier hinken dem Zeitplan um Wochen hinterher. Die Kosten sind himmelhoch und die Qualität erbärmlich. Das Problem hier ist Korruption, <Name>! Und ich brauche Euch, um dieses Übel auszumerzen.\n\nDie Feindbrecher, ein Kriegsschiff, das am nordwestlichen Pier liegt, sollte schon vor Tagen ausgestattet werden. Da ist etwas faul. Geht dorthin und überwacht den Bau selbst.\n\nFindet heraus, wer unsere Schiffsvorbereitungen unterbricht und setzt dem ein Ende!", progress = nil, completion = "&lt;Dies sind die Blaupausen für die Feindbrecher mit allen noch so kleinen Details.&gt;\n\n&lt;Ihr dreht und wendet die Dokumente und versucht, die Notizen, Bemerkungen und Korrekturen zu entziffern.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26336] = {title = "Wank O'Breen", objective = "Findet Wank O'Breen in Faldirs Bucht im Arathihochland.", description = "Ihr seid in Ordnung, <Name>. Man trifft nur selten sogenannte Helden, die so weit entfernt von der Heimat tatsächlich wissen, was sie tun. Ich würde Euch gern etwas mehr Arbeit überlassen. \n\nIch habe einen Freund namens Wank O'Breen. Er kommandiert eine Piratenbesatzung, die Schwarzmeerräuber; das sind gute Jungs, respektabel für Piraten. Sie haben in Faldirs Bucht angelegt, die versteckt am Südstrand liegt.\n\nO'Breen wird Euch sicherlich einige lukrative Angebote machen können, wenn Ihr interessiert seid.", progress = nil, completion = "Ahoi, &lt;Klasse&gt;. Jeder Freund von Skuerto ist auch mein Freund.\n\nHier gibt es eine Menge zu tun. Wir sitzen nicht in dieser Bucht und drehen Däumchen, weil wir das wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26337] = {title = "Schlagfertige Überredungskunst", objective = "Sucht einen Bilgewässer Großknecht im Bilgewasserhafen und mischt ihn ein wenig auf.", description = "<Es ist offensichtlich, warum die Feindbrecher im Zeitplan hinterherhinkt. Alle zwei Tage nimmt ein Großknecht Änderungen an den Blaupausen vor.>\n\n<Am beunruhigendsten sind die letzten Änderungen. Den Arbeitern wurde befohlen, Nieten zu entfernen, um Kosten zu sparen!>\n\n<Ihr solltet einen der Bilgewässer Großknechte finden, die dafür verantwortlich sind und ein Exempel statuieren. Ansonsten kommen noch Mitglieder der Horde wegen der fehlerhaften Schiffe ums Leben!>", progress = nil, completion = "Also haben sie versucht, bei den Produktionskosten zu schummeln? Völlig inakzeptabel!\n\nIch bin froh, dass Ihr ihnen ein wenig Verstand eingeprügelt habt. Wenn dieser Großknecht sein Wort hält, ist unsere Flotte rechtzeitig für unsere Invasion seetauglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26338] = {title = "Bevölkerungskon-Trolle", objective = "Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.", description = "Ich habe gehört, dass Ihr bald nach Zul'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe für Euch, wenn Ihr dort seid.\n\nDie Bevölkerung der Trolle ist zu groß für Schlingendorntal geworden. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie kommen aus den Ruinen und machen sich im Dschungel breit. Das stört das natürliche Gleichgewicht der Gegend. Dieses Gleichgewicht muss jetzt wiederhergestellt werden.\n\nZul'Kunda ist die Hochburg der Blutskalpe. Dort werdet Ihr die hochrangigsten Blutskalpe finden. Reduziert ihre Zahlen und kehrt zu mir zurück.", progress = nil, completion = "Das Gleichgewicht ist erst einmal wiederhergestellt. Wir werden uns vielleicht zu einem späteren Zeitpunkt wieder an Euch wenden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26339] = {title = "Vorbereitungen in Bräuhall", objective = "Sprecht mit Jarvi Schattenschritt in Bräuhall.", description = "Während Hochtüftler Mekkadrill, seine militärischen Berater und ich die Pläne für den Angriff auf Razlo Ritzelstoß durchgehen, ist mein Assistent schon einmal nach Bräuhall gereist, um mit den Vorbereitungen zu beginnen.\n\nFolgt der Straße nach Südosten aus der Stadt hinaus, um nach Bräuhall zu gelangen. Findet Jarvi Schattenschritt nach Eurer Ankunft und findet heraus, ob er Hilfe benötigt. Unsere Zwergencousins haben einen Trupp Gebirgsjäger aus Eisenschmiede abgestellt, um uns im Kampf gegen Ritzelstoß zu unterstützen.", progress = nil, completion = "Ach ja, Kelsey sagte mir, Ihr würdet bald eintreffen. Es gibt viel zu erledigen, bevor wir uns Ritzelstoß stellen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26340] = {title = "Die Jagd", objective = "Meldet Euch bei Barnil Steinkrug bei Nesingwarys Expedition im Nördlichen Schlingendorntal.", description = "Von allen Plätzen in Azeroth stecke ich ausgerechnet hier in Grom'gol fest. Es ist ein Wunder, dass ich noch am Leben bin, mit den gefährlichen Wildtieren, den Überfällen auf Karawanen und der dauernden Bedrohung durch Angriffe der Trolle.\n\nEs könnte schlimmer sein. Hier in Grom'gol gibt es wenigstens Mauern und Wächter. Eine Gruppe Jäger hat nördlich von hier mitten im Dschungel ihr Lager errichtet!\n\nIch sehe die ganze Zeit, wie Leute dort hingehen. Wenn Ihr nach Ärger sucht, solltet Ihr in diese Richtung aufbrechen. Ich bleibe in Grom'gol.", progress = nil, completion = "Hmm? Ich heiße Barnil. Und wer seid Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26341] = {title = "Die Steinsplitter", objective = "Untersucht die Splitter von Myzrael.", description = "Ich habe das ganze Hochland bereist, <Name>, und dabei etwas gefunden, für das ich keine Erklärung habe.\n\nNordöstlich von hier gibt es einen Steinkreis, ähnlich denen, die man überall in Arathi findet... nur deutlich größer und beeindruckender. Er wurde in den Berg hineingebaut.\n\nUnter uns: Ich hörte Stimmen, als ich dort war. Das Flüstern der Erde. Solltet Ihr neugierig geworden sein, könnt Ihr Euch das selbst ansehen...", progress = nil, completion = "&lt;Die Splitter pulsieren sanft; ein Flüstern windet sich langsam durch Euren Kopf.&gt;\n\nHilfe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26342] = {title = "Schwarzmalerei", objective = "Benutzt den Farbinator, um 5 von Ritzelstoß' Späh-o-Bots die Sicht zu nehmen.", description = "Uns liegen verlässliche Informationen vor, laut derer Razlo Ritzelstoß eine Verteidigungsstellung auf der Insel in der Mitte des gefrorenen Eiswellensees errichtet hat. Hinzu kommt, dass er sich mit zahlreichen Späh-o-Bots umgibt, die mögliche Angreifer entdecken sollen.\n\nWir können uns Ritzelstoß erst stellen, wenn diese Späher zerstört worden sind. Dieses Gerät schießt eine dunkle, klebrige Farbe ab. Sie wird die optischen Sensoren von Ritzelstoß' Späh-o-Bots verdecken. Schaltet sein Frühwarnsystem damit aus.", progress = nil, completion = "Ihr habt es uns gerade ermöglicht, Ritzelstoß zu überrumpeln. Hervorragende Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26343] = {title = "Angebot und Nachfrage", objective = "Bringt 2 große Flusskrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.", description = "Der beste Ledermacher der Südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.\n\nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!\n\nGerade habe ich eine Bestellung von Direktor Quizvox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.\n\nFür die Grundform benötige ich Krokiliskenhäute von den Krokis entlang des Flusses im Nördlichen Schlingendorntal.", progress = "Meine Ausrüstung ist startklar, <Name>, ich warte nur noch auf die Häute. Wir wollen Quizvox ja nicht warten lassen.\n\nEs ist für niemanden gut, wenn der Cheferfinder des Tüftlerverbands unzufrieden ist.", completion = "Diese Häute sollen genügen. Ihre Qualität ist nicht allzu wichtig, da sie ja nur die innere Schicht der Stiefel bilden, aber sie sollten schon bequem sein.\n\nWenn sie ein bisschen zu steif sind, verwende ich ein wenig Tigerblut, um sie aufzuweichen. Kleines Betriebsgeheimnis, wisst Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26344] = {title = "Etwas Zusammenbau benötigt", objective = "Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.", description = "Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir brachtet, werden leider nicht für die inneren Schichten ausreichen.\n\n\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen, und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!\n\nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokis holen, die um den Nazferitisee leben.", progress = "Drizzliks Exzelsiorlederstiefel, feinste Handwerksarbeit, Stiefel aus 100 Prozent Salzwasserkrokiliskenhaut von höchster Qualität. Es gibt nichts Besseres!\n\nSo eine tolle Beschreibung sucht ihresgleichen, was?\n\nOder habt Ihr vielleicht schon diese Häute für mich?", completion = "Meine Stiefel... sie sind 'n bisschen wie Würstchen, &lt;Name&gt;. Sehen gut aus und schmecken auch so. Ich sag Euch, dass sie mit dem allerbesten Fleisch und feinsten Zutaten gefüllt sind und Ihr esst sie und Ihr liebt sie.\n\nEs ist sicherer - und schmackhafter -, wenn Ihr mir einfach nur traut und nicht allzu viele Fragen stellt, was wirklich drin ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26345] = {title = "Exzelsior", objective = "Bringt die Haut eines alten Krokilisken zu Drizzlik bei Nesingwarys Expedition.", description = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.\n\nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Ihr findet sie im Süden, in der der Nähe der Grenze am Kap.", progress = "Irgendwo habe ich gelesen, dass die älteren Krokilisken langsam aussterben... schlecht für mein Geschäft, was?\n\nEgal, ich hoffe, Ihr habt die Haut eines alten Salzwasserkrokilisken für mich!", completion = "Großartig! Dank Eurer Hilfe habe ich diese Bestellung fertig und kann sie mit dem nächsten Schiff zu Direktor Quizvox nach Lorenhall abschicken. Sogar noch vor der Frist!\n\nFür all Eure harte Arbeit, hier, ich habe einige zusätzlich gemacht, nehmt Euch ein Paar. Geht auf Drizzliks Rechnung.\n\nUnd denkt dran, nirgends gibt es Stiefel, die so fein, wie Stiefel von Drizzliks Exzelsiorlinie ganz allein!", rewards = "Ihr bekommt:\n\nExzelsiorwatstiefel"}
MultiLanguageQuestData['de'][26346] = {title = "Myzraels Geschichte", objective = "Kehrt zu Skuerto in der Zuflucht im Arathihochland zurück.", description = "Als der Stein verstummt, hallt ein ungutes Gefühl in Euch nach. Etwas stimmt nicht.\n\nVielleicht solltet Ihr Skuerto erzählen, was Ihr bis jetzt getan habt.", progress = nil, completion = "Ihr müsst nicht mehr sagen, &lt;Name&gt;. Ich habe mich mit einem... \"alten Freund\" unterhalten, während Ihr unterwegs wart. Ich hätte Euch nicht zu diesen Splittern schicken sollen.\n\nEs war ein schwerer Fehler von uns beiden, uns damit zu beschäftigen. Zum Glück konnte ich meinen Freund Gerrig davon \"überzeugen\", mir zu erklären, was in diesem Fall zu tun ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26347] = {title = "Bewahrer der Flamme", objective = "Bringt 5 Schluchtenschlamme zu Kapitän Grausohn am Leuchtturm von Westfall.", description = "Die Nacht, als die Leuchtturmwärterfamilie starb, war schrecklich. Ich musste hilflos zusehen, während Trübauge der Alte den Angriff anführte. Aber die Vergangenheit lässt sich nicht ändern und meine Hauptsorge gilt jetzt den Leben der Seeleute auf dem Großen Meer. Ihre Schiffe kommen den gefährlichen Felsen entlang der Küste oft zu nahe. Da niemand mehr auf das Leuchtfeuer aufpasst, fällt diese Aufgabe jetzt mir zu.\n\nHelft mir, die Flamme am Leben zu erhalten, indem Ihr mir Schluchtenschlamm von den Schleimen im Rasenden Schlund im Nordosten bringt.", progress = "Das Feuer wird ohne Schlamm nicht sehr lang brennen, <Name>. Früher haben wir Öl benutzt, aber das war schwer zu beschaffen!", completion = "Ich muss Euch für Euren Mut loben, &lt;Klasse&gt;. Die Felsen an der Küste Westfalls werden dank Eurer harten Arbeit beleuchtet sein. Solange das Feuer brennt, werden viele Leben verschont bleiben.\n\nMein Tod an diesem Strand war unnötig. Meine Aufgabe im Jenseits ist es, dafür zu sorgen, dass niemand dem gleichen Schicksal erliegt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwacher ManatrankSchwacher Heiltrank\n\nIhr bekommt außerdem:\n\nRolle der IntelligenzRolle der Ausdauer"}
MultiLanguageQuestData['de'][26348] = {title = "Ärger an der Küste", objective = "Tötet 7 Murlocgezeitenjäger und 7 Murlocorakel.", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet Gezeitenjäger und Orakel, dann sorge ich dafür, dass Ihr belohnt werdet.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr habt ein ziemliches Talent für den Kampf. Dank Euch ist die Küste Westfalls jetzt sicherer als zuvor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26349] = {title = "Bedrohung an der Küste", objective = "Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten.", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Trübauge der Alte die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Trübauge brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Trübauge den Alten, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", progress = "Habt Ihr der Bedrohung namens Trübauge schon den Garaus gemacht? Er ist gesehen worden, wie er an der Küste von Westfall umherstreifte.\n\nKehrt zu mir zurück, sobald das garstige Ungeheuer tot ist.", completion = "Also ist Trübauge, dieser garstige Heide, endlich tot. Gut gemacht, &lt;Name&gt;. Durch Eure Hand ist ein Leben beendet worden, doch vielleicht wurden gerade durch diese Tat viele weitere Leben gerettet. So gefährlich das Große Meer auch ist, diese Nacht wird es dank Eurer heldenhaften Tat ein wenig sicherer sein.", rewards = "Rundschild der MeereZauberstab des FackelscheinsAuf Euch wartet eine dieser Belohnungen:\n\nGrausohns Fackel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26350] = {title = "Priesterin Hu'rala", objective = "Sprecht mit Priesterin Hu'rala in Bambala im Nördlichen Schlingendorntal.", description = "Ich danke Euch, <Name>. Ich weiß, Ihr hättet mich nicht retten müssen und... nun, ich bin Euch sehr dankbar.\n\nDie Rückkehr von Blutfürst Mandokir ist eine schreckliche Nachricht. Er wurde vor vielen Jahren in Zul'Gurub getötet und wir dachten, es wäre das Ende von ihm und seinesgleichen. Die Trolle von Zul'Gurub haben versucht, ein abscheuliches, furchtbares Ritual durchzuführen. Wenn Mandokir lebt, so gibt es Grund zur Annahme dass er nicht der Einzige ist.\n\nDie Trolle in Bambala östlich von hier könnten mehr wissen. Sprecht mit der Priesterin.", progress = nil, completion = "Mandokir lebt, ja.\n\nIhr seid dafür verantwortlich, ja.\n\nIhr könnten ihn noch aufhalten können, ja.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26351] = {title = "Gedankensicht", objective = "Erhaltet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.", description = "Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.\n\nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.\n\nIhr habt Euch angefreundet mit Raptor: Ohgan'aka: Tochter von Ohgan.\n\nUm Freundschaft zu stärken, brauchen wir Federn.\n\nGeht nach Westen und Ihr werdet Federn finden, ja.", progress = "Raptor namens Ohgan'aka immer noch Eure Freundin.", completion = "Ihr bringt Federn, ja.\n\nIhr könnt Anweisungen folgen, ja.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26352] = {title = "Cozzles Vorhaben", objective = "Nehmt Cozzles Schlüssel dem Großknecht Cozzle ab und erhaltet die Treibstoffreglerblaupausen.", description = "Ich mag den Dunkelspeeren abstammen, aber ich habe meine Kindheit hier im Schlingendorntal verbracht. Ich habe jedes Fleckchen des Schlingendorntals gesehen; es gibt jedoch nichts schlimmeres als die Zerstörung, die die Venture Company dem Flussbett zugefügt hat.\n\nUnd es wird noch schlimmer, weil Großknecht Cozzle und seine Arbeiter ihre Aktivität gesteigert haben. Ich fürchte, sie haben etwas Neues vor. Schließt die Aufgabe ab, an der ich gescheitert bin, <Name>: tötet Cozzle, nehmt seinen Schlüssel und stehlt die Blaupausen aus seinem Heim.", progress = "Was die Venture Company dem Schlingendorntal angetan hat kann nicht verziehen werden.", completion = "Ein Treibstoffregler? Das scheint wichtig zu sein. Zumindest hoffe ich das.\n\nWir werden die Unternehmungen der Venture Company nicht beendet haben, aber wenigstens haben wir sie verlangsamt. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26353] = {title = "Käpt'n Sanders' versteckter Schatz", objective = "Findet Käpt'n Sanders' Schließkiste und sucht darin nach dem nächsten Hinweis.", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sanders in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", progress = nil, completion = "Der Schließkasten knarrt als Ihr ihn langsam öffnet. Sand und Wasser scheinen der einzige Inhalt zu sein. Aber halt! Eine kleine Krabbe huscht mit einem Hinweis auf den Schatz in den Scheren davon.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26354] = {title = "Käpt'n Sanders' versteckter Schatz", objective = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Osten halten. Im Osten die Steilhänge hoch, dann weiter nach Osten bis zur Straße. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr 'n altes Fass mit Eurem nächsten Hinweis drin.", progress = "Das sieht wie das richtige Fass aus.", completion = "Gut gemacht! Das war der nächste Schritt auf der Schatzsuche.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26355] = {title = "Käpt'n Sanders' versteckter Schatz", objective = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch den Henkelkrug mal genau anguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", progress = "Es steckt ein Hinweiszettel in dem leeren Henkelkrug.", completion = "Ihr seid bei Eurer Schatzsuche auf dem richtigen Weg!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26356] = {title = "Käpt'n Sanders' versteckter Schatz", objective = "Findet Käpt'n Sanders' Truhe und öffnet sie. Darin befindet sich Eure Belohnung.", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders' Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", progress = "Der verlorene Schatz von Käpt'n Sanders wartet!", completion = "Die Scharniere der alten Truhe sind rostig, aber sie funktionieren noch. Ihr brecht die Truhe auf und nehmt die Beute heraus.\n\nHerzlichen Glückwunsch!", rewards = "Ihr bekommt:\n\nSilberbarrenKäpt'n Sanders' HemdKäpt'n Sanders' SchärpeKäpt'n Sanders' Beutetasche"}
MultiLanguageQuestData['de'][26357] = {title = "Gesichter des Bösen", objective = "Zündet mit der Tikifackel 8 Tikimasken in Jintha'Alor an.", description = "Die Blutfratzen haben ihre Tikimasken überall in Jintha'Alor an die Mauern gehangen. Die Geister werden nicht mehr lange über sie wachen.\n\nNehmt die Fackel und kämpft Euch durch die Blutfratzen, <Klasse>. Zündet ihre Tikimasken an. Ich werd zusehen, wie ihre Abwehr- und Schutzzauber vergehen und ihr ketzerischer dunkler Voodoo in Rauch aufgeht.", progress = nil, completion = "Was für'n schöner Anblick. Die Hoffnungen des Feindes verbrennen...", rewards = "Abscheulicher AstAxt aus Jintha'AlorAuf Euch wartet eine dieser Belohnungen:\n\nHalskette der bösen Fratzen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26358] = {title = "Macht die Luftwaffe startklar", objective = "Sucht nach Fliep auf ihrem Schrottplatz im Bilgewasserhafen in Azshara.", description = "Ich habe Höllschrei persönlich garantiert, dass seine Luftflotte diese Woche fertig wird, aber unser Flaggschiff, die Speer von Durotar, hat immer noch keine Haupttriebwerke.\n\nFliep hat mir letzte Woche ein niegelnagelneues Triebwerk versprochen. Geht zu ihrem Schrottplatz hinter der Bank und findet den Grund für die Verzögerung heraus.\n\nDie Luftflotte erwartet uns, <Name>!", progress = nil, completion = "&lt;Fliep wischt sich das Gesicht ab und verschmiert sich dabei gehörig die Wange mit Schmieröl.&gt;\n\nWas? Der Kapitän hat WAS gesagt?\n\n&lt;Sie schwingt bedrohlich ihre Rohrzange.&gt;\n\nEs ist SEINE Schuld, dass dieses Monstrum von Triebwerk verspätet ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26359] = {title = "Seht Raptor", objective = "Sprecht mit Priesterin Hu'rala in Bambala, um am Ritual der Gedankensicht teilzunehmen.", description = "Wir haben Federn, ja.\n\nWir haben <den/die:c> <Klasse>, ja.\n\nSprecht mit Priesterin, wenn bereit.", progress = nil, completion = "Was hat Priesterin Euch gesagt?\n\nRaptor ist Tochter von Ohgan, Erbe von Mandokir.\n\nHah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26360] = {title = "Gedankenkontrolle", objective = "Erhaltet Braddoks Riesengehirn von Braddok in Zul'Mamwe.", description = "Gedankensicht nicht genug, nein.\n\nGedankenkontrolle viel mächtigere Magie, ja.\n\nMächtige Magie braucht mächtige Reagenzien und Trollhirn ist mächtiges Reagenz.\n\nBraddok in Zul'Mamwe sehr intelligent, ja.\n\nGeht nach Süden und untersucht Braddoks großes Gehirn.", progress = "Riesenzauber brauchen Riesenhirne, ja.", completion = "Passt auf, nächster Teil schwierig, ja.\n\nScheitern sehr möglich, ja.\n\nAber &lt;Name&gt; und &lt;Name&gt;'aka werden wiedervereint... ja, werden sie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26361] = {title = "Smoots Samophlang", objective = "Findet Smoot im Bilgewasserhafen. Stellt ihn und besorgt Euch das Induktionssamophlang.", description = "Es war der Kapitän, der darauf bestanden hat, dass die neuen Triebwerke ein Induktionssamophlang haben.\n\nSo etwas wurde noch nicht einmal erfunden!\n\nIch habe Smoot damit beauftragt, ein Induktionssamophlang auf Basis von gestohlenen Zeichnungen der Venture Company zu entwerfen. Endlich ist es ihm auch gelungen, ein funktionierendes Modell zu bauen.\n\nDoch jetzt, wo er das Samophlang hat, ist er vor lauter Macht ganz berauscht. Er schleift es in der ganzen Stadt mit sich herum, wie ein Besessener.\n\nVersetzt Smoot eine Tracht Prügel und schnappt Euch mein Samophlang, <Name>.", progress = "Smoot ist ein hervorragender Ingenieur.\n\nEin Samophlang kann aus 30 Metern Entfernung töten, wenn die Reduktionskaliphraketen falsch ausgerichtet sind.", completion = "Ausgezeichnet! Ich sollte dieses Triebwerk noch in dieser Stunde samophlanginiert haben.", rewards = "Beinschützer der SamophlanginationTaillenschutz der kalibrierten KalifrakteSmootschlagende SchulterpolsterSmoots zerfetzter KittelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26362] = {title = "Seid Raptor", objective = "Sprecht mit Priesterin Hu'rala und helft dem gefangenen Schmetterschwanzjungen bei der Flucht aus Zul'Gurub.", description = "Gedankenkontrolle sehr mächtig, ja.\n\nMit Glück könnt Ihr Ohgan'aka helfen, aus Zul'Gurub zu fliehen.\n\nDann wird Ohgan'aka wieder <Name>'aka werden!\n\nSprecht mit Priesterin, ja, und helft <Name>'aka bei Flucht.", progress = nil, completion = "Sehr schade, ja.\n\nDies ist der Wille der Geister, ja.\n\nWenn Ihr stärker seid, werdet Ihr vielleicht nach Zul'Gurub gehen und deine &lt;Name&gt;'aka von Mandokir zurückholen, ja.\n\nDoch erst einmal gibt Euch Priesterin dies.", rewards = "Umarmung des DschungelgeistesHu'ralas PantoffelnGürtel des HochschamanenAuf Euch wartet eine dieser Belohnungen:\n\nBand aus Raptorzähnen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26363] = {title = "Schicksalsgipfel", objective = "Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha'Alor.", description = "Ihr wart im Vorgehen gegen ihre Krieger sehr erfolgreich, <Name>. Ich möchte, dass Ihr den Gipfel von Jintha'Alor untersucht.\n\nWir waren auf den härtesten Kampf vorbereitet, darauf, ihren dunklen Altar zu stürmen, aber es ist zu leise. Kein Geräusch weit und breit. Es könnte eine furchtbare Falle sein und jemand, der stark genug ist, sollte sich dort umsehen, bevor wir alle gesammelt einlaufen.\n\nWenn es keine Falle sein sollte... würde es mich auf jeden Fall auch interessieren, was dort los ist. Bringt mir jegliche Hinweise, die Ihr finden könnt.", progress = "Was habt Ihr gefunden?", completion = "Tot? Alle, um den ganzen Alter herum? Und sie hatten diese Spinnengötzen bei sich...\n\nEine Massenopfergabe. Sie haben Sharda ihre Leben geopfert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26364] = {title = "Nieder mit Ritzelstoß!", objective = "Besiegt Razlo Ritzelstoß. Sprecht mit Hochtüftler Mekkadrill auf dem Eiswellensee, wenn Ihr bereit seid, den Kampf zu beginnen.", description = "Unsere Cousins, die Zwerge von Eisenschmiede, haben sich bereit erklärt, uns im Kampf gegen Razlo Ritzelstoß zu unterstützen. Gebirgsjäger Steinschleifer ist ein Veteran, der Dun Morogh gut kennt. Er und Hochtüftler Mekkadrill halten sich auf einer kleinen, schneebedeckten Insel im Eiswellensee nördlich von hier bereit. Trefft sie dort und sagt dem Hochtüftler Bescheid, wenn Ihr bereit seid, dem Verräter Ritzelstoß entgegenzutreten.\n\nNehmt dieses orbitale Zielgerät und benutzt es während der Schlacht. Es wird die Spezialwaffen des Hochtüftlers zum Ziel führen.", progress = nil, completion = "Endlich sind wir frei von Razlo Ritzelstoß und seinen Störungen! Nach der Niederlage von Ritzelstoß und seinen Truppen, kann Thermadraht es sich nicht mehr leisten, weitere seiner Anhänger an die Oberfläche zu schicken. Ich kann den Tag, an dem wir ihn endgültig besiegen werden, kaum erwarten!", rewards = "Handschuhe der potenziellen EnergieArmschienen des schrägen SchwungsGürtel des statischen AusgleichsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26365] = {title = "Heldenaufruf: Rotkammgebirge!", objective = "Meldet Euch bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge.", description = "Die Lage hier ist zwar schlimm, aber in anderen Gegenden bebt es wortwörtlich nach dem großen Aufruhr immer noch.\n\nIch habe hier einen Bericht von Wachhauptmann Parker aus dem Rotkammgebirge, eines unserer Gebiete östlich vom Wald von Elwynn. Er ersucht die Hilfe eines Helden.\n\nSo, wie wir im Moment aufgestellt sind, kann ich keine weiteren Truppen losschicken. Könnt Ihr Parker aufsuchen und sehen, was er braucht? Ihr könnt Wachhauptmann Parker auf dem Turm bei den Drei Ecken finden.", progress = nil, completion = "Ich habe gehört, dass Westfall wirklich in der Klemme steckt.\n\n&lt;Parker sieht Euch nicht einmal an, als er mit Euch spricht.&gt;\n\nNun, wir haben hier selbst Probleme. Seht Ihr die Gnolle dort? Es sieht so aus, als haben sie wieder etwas vor. Das gefällt mir nicht. Das gefällt mir überhaupt nicht.", rewards = "Parkers ZollstockGürtel der unlösbaren ProblemeKlemmenstiefelUnglückselige TreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26366] = {title = "Kopfprämie", objective = "Besiegt Umboda Dreikopf und holt Euch seinen Kopf.", description = "Umboda von den Blutfratzen ist einer ihrer stärksten Krieger und ein kranker Schlächter.\n\nEr sammelt und benutzt die Köpfe aller, die vor ihm fallen, als Schmuck, Belohnungen... und sogar Waffen! Es ist an der Zeit, dass er fällt.\n\nFindet Umboda Dreikopf, tötet ihn und bringt mir SEINEN Kopf! Wir werden sehen, wie die Blutfratzen kämpfen, wenn wir seinen Kopf über ihre Mauern werfen!", progress = "Zeigt ihn her!", completion = "Der Ausdruck von Angst und Verwirrung in seinem Gesicht... das ist genau das, was er verdient hat! Jetzt müssen wir nur noch sicherstellen, dass alle Blutfratzen so einen Gesichtsausdruck bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26367] = {title = "Ongo'longos Rache", objective = "Bekämpft Ongo'longo bis er seine Fesseln sprengt.", description = "Ongo'longo war einer von uns. Außenseiter mögen ihn einen Terrortroll nennen, aber er war ein Bruchhauer und ein stolzer Krieger, so wie wir auch!\n\nDann haben die Blutfratzen ihn gefangen genommen. Sie halten ihn gefesselt in einer Grube oben in Jintha'Alor und zwingen ihn, zu ihrer kranken Unterhaltung zu tanzen.\n\nKeine Ketten können Ongo'longo halten. Ihr müsst nur sein Temperament aufwecken. Bekämpft ihn, bis er sich genug ärgert, um sich an sein wahres Ich zu erinnern und die Fesseln sprengt... und dann geht ihm schnell aus dem Weg!", progress = nil, completion = "Ich wünschte, ich hätte es selbst sehen können, &lt;Name&gt;. Ich muss die Geschichte auch von Ongo'longo selbst hören, wenn wir hier fertig sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26368] = {title = "Giftige Geheimnisse", objective = "Erhaltet 6 Giftprobe der Shadrabrut von der Brut von Shadra in Jintha'Alor.", description = "Von diesem interessanten Gift wird es noch mehr geben, wenn Shadra gerufen wurde.\n\nSeid nicht so überrascht... Die Verlassenen haben diese Länder schon seit längerem untersucht und wir haben die Königin des Gifts hier mindestens einmal gesehen. Ihre Gifte haben sich in der Vergangenheit als recht nützlich herausgestellt.\n\nUnd sie werden sich der Horde erneut als nützlich erweisen. Seid so nett und holt so viel Gift, wie Ihr von der Brut von Shadra erhalten könnt, die in der Höhle auf dem Gipfel sind... Ihr werdet ohnehin voll davon sein, wenn Ihr die Höhle betretet.", progress = "Habt Ihr das Gift...?", completion = "Mmh, ja... dieser alte, wohlbekannte Geruch.\n\nIhr habt den Verlassenen und der Horde gute Dienste geleistet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26369] = {title = "Jagt die Bewahrerin", objective = "Tötet Morta'gya die Bewahrerin und erhaltet die Tafel von Shadra.", description = "Kotonga hat mir von Shadra berichtet. Sie ist die Giftkönigin, die Loa der Spinnen, in der Dunkelheit verehrt. Falls die Blutfratzen vorhaben, Rituale durchzuführen, so werde ich dies zu verhindern wissen.\n\nUntersucht die Höhle hinter dem Altar oben auf Jintha'Alor. Tief in der Höhle könnte sich noch eine Bewahrerin Shadras verstecken. Tötet sie und nehmt alles, was sie bei sich hat, damit wir herausfinden können, was dort vor sich geht.", progress = "Durchsucht ihren Leichnam. Ich möchte nicht, dass von den Blutfratzen gelegte Fallen von den Toten verdeckt werden.", completion = "Die Teile sind zersprungen und die Bewahrerinnen wurden getrennt... nun gut.\n\nDas ist das Ritual, um Shadra zu rufen. Sie scheinen es nicht abgeschlossen zu haben. Es sollte zerstört werden...", rewards = "UnbewahrerklingeGamaschen der geheimen RitualeHandschuhe der seltsamen WorteSchulterstücke des TafelträgersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26370] = {title = "Rückkehr zur Späherkuppe", objective = "Erstattet Marschall Gryan Starkmantel an der Späherkuppe in Westfall Bericht.", description = "Die Bruderschaft der Defias sollte man nicht auf die leichte Schulter nehmen, <Name>. Was Ihr da gesehen habt, war die Geburtsstunde einer skrupellosen Verbrecherorganisation, die vor nichts Halt machen wird, bevor Sturmwind nicht in Schutt und Asche liegt.\n\nIch möchte, dass Ihr zur Späherkuppe zurückkehrt und Gryan wissen lasst, dass ich ihm Truppen schicke. Ich hoffe, es ist noch nicht zu spät.", progress = nil, completion = "Fünf Jahre Arbeit innerhalb von fünf Minuten zu Asche verbrannt. Verfluchte Defias!\n\nUnd das ist erst der Anfang, &lt;Name&gt;! Wir haben einen langen, anstrengenden Weg vor uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26371] = {title = "Die Legende des Kapitän Grausohn", objective = "Findet Kapitän Grausohn beim Leuchtturm von Westfall in Westfall.", description = "Habt Ihr von Kapitän Grausohn gehört? Einige sagen, er ist die Erfindung eines betrunkenen Seemannsgehirns, aber jeder in Westfall wird Euch sagen, dass Grausohn existiert! Er ist ein Geist, der den Leuchtturm von Westfall ganz im Westen, vor der Endlosen Küste, heimsucht.\n\nWagt Ihr es, das zu untersuchen?", progress = nil, completion = "Ja... Ich war auch einst aus Fleisch und Blut, genau wie Ihr, mein Junge. Bis zu dem schicksalsträchtigen Tag, als die Murlocs den Leuchtturm angriffen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26372] = {title = "Letzte Tests vor dem Flug", objective = "Sprecht mit Kapitän Krazz im Bilgewasserhafen in Azshara.", description = "Dieses neue Triebwerk ist extrem schnell. Und gefährlich. Ich würde es \"brisant\" nennen.\n\nGenau so mag der Kapitän es.\n\nRennt schnell den Hügel hinauf und sagt ihm Bescheid, dass ich dieses Schätzchen jetzt einbaue und er sich auf der Baustelle mit mir treffen soll.", progress = nil, completion = "Mein Luftschiff hat Triebwerke? Endlich!\n\nJetzt können wir uns wieder in die Lüfte schwingen!\n\nSobald die Boden- und Seetruppen bereit sind, werden wir den Himmel über dem Schattenhochland in Brand stecken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26373] = {title = "Weiter nach Kharanos", objective = "Sprecht mit Hauptmann Tharran in Kharanos.", description = "Einige der Gebirgsjäger unter Steinschleifers Kommando haben mir von den Problemen draußen in Kharanos berichtet. Als die Troggs die Höhle der Frostmähnen eroberten, sind die überlebenden Trolle anscheinend nach Westen, bis ins Herz der Zwergenheimat geflohen.\n\nJetzt bedrohen sie die Zwergenstadt Kharanos. Die Zwerge dort brauchen wohl dringend Hilfe. Warum reist Ihr nicht nach Kharanos und stellt Euch Hauptmann Tharran vor? Folgt der Straße, die nach Osten aus Bräuhall herausführt und folgt ihr, bis Ihr die Stadt seht.", progress = nil, completion = "Wenn der Geheimdienst von Gnomeregan Euch empfiehlt, müsst Ihr einen sehr guten Eindruck gemacht haben. Eure Hilfe können wir hier gut gebrauchen, da wir reich an Feinden, aber arm an Gebirgsjägern sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26374] = {title = "Macht die Bodentruppen startklar", objective = "Durchsucht den Bilgewasserhafen und überzeugt 12 fahnenflüchtige Grunzer, sich zum Dienst zu melden.", description = "Es war keine gute Idee, die Truppen in dieser pulsierenden Goblinmetropole einzuberufen. Jedes Laster, das man mit Gold kaufen kann, ist nur eine Armlänge entfernt. Unsere mächtigen Veteranen sind völlig zügellos und hauen ihren über Jahre mühsam in Nordend verdienten Sold auf den Kopf. Die Stadt droht, zusammenzubrechen!\n\nKönntet Ihr durch die Stadt streifen und die fahnenflüchtigen Nachzügler einsammeln?\n\nMeine Krieger der Axtbeißer sind auf dem Schlachtfeld unschlagbar, aber ich lasse nicht zu, dass sie ihren Uniformen während ihres Landgangs Schande bringen.", progress = nil, completion = "Danke, &lt;Name&gt;! Die meisten meiner Soldaten haben sich bereits zum Dienst gemeldet, einige leider etwas lädiert.\n\nBilgewässer Nächte sind lang.\n\nEin frischer Kampf im Schattenhochland sollte ihre Disziplin jedoch wiederherstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26375] = {title = "Entfesselte Steine", objective = "Benutzt den filigranen Kettensprenger, um 6 Quarzsteinlinge zu befreien.", description = "Die Schattenhammerkultisten rauben meine Steinlinge. Sie stehlen ihre Energie und foltern sie. Sie nehmen ihnen die Essenz, die dem Stein Leben einhaucht.\n\nBitte, <Volk>, befreit meine Steinlinge. Weder Diamant noch ich verfügen über das Fingerspitzengefühl, ihre Ketten zu zerschlagen, ohne sie zu verletzen. Aber wir haben ein Werkzeug, das Ihr vielleicht verwenden könnt.\n\nNehmt dies. Sprengt ihre Ketten und befreit sie.", progress = "Ich kann es kaum mitansehen. Sie kennen kein Erbarmen. Daher sollten wir ihnen auch keines gönnen.", completion = "Ihr seid sehr großzügig, &lt;Volk&gt;. Ihr gebt der Erde, die Euch so viel gibt, etwas zurück. Ihr habt meinen Respekt. Mit der Zeit werdet Ihr auch sicher den Respekt der Steinlords erlangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26376] = {title = "Tiefsitzender Hass", objective = "Tötet Dragul Riesenschlächter und 12 Schattenhammerkultisten an Lorthunas Tor.", description = "Ich würde mich ja für Boden entschuldigen, aber Stein ist stur.\n\nOhne den nagenden Zahn der Zeit weicht er nicht von seinen Gewohnheiten ab.\n\nDie Steinlords, darunter Boden und ich, haben die Aufgabe, die Weltensäule zurückzuholen.\n\nDoch wir sind uns uneinig.\n\nIch möchte Euch gerne meine Geduld zuteilwerden lassen, <Volk>.\n\nBeweist, dass Ihr kein Verbündeter des Schattenhammerkults oder Todesschwinges seid...\n\nTragt unseren Hass zu ihnen.\n\nSchlagt schnell zu, wo wir es nicht können.\n\nHabt Ihr Erfolg, werde ich Euch zuhören.", progress = nil, completion = "Ich habe Euch beobachtet, &lt;Volk&gt;.\n\nIhr scheut Euch nicht, das Blut des Schattenhammers zu vergießen.\n\nDaher bin ich geneigt, Euch bis zu einem gewissen Grad zu vertrauen.\n\nEs ist ein Anfang.\n\nAlles zu seiner Zeit.", rewards = "Steingebundene BeinplattenAbgelegte Schiftung des RiesenschlächtersHandwickel des BlutkultesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26377] = {title = "Loser Grund", objective = "Sammelt 6 Jadekristallformationen und kombiniert sie miteinander. Verteilt sie dann im Lager an Lorthunas Tor.", description = "Der Schattenhammerkult baut in der Nähe seines Lagers Jadekristalle ab.\n\nDumm…\n\nWaghalsig…\n\nSammelt die abgebauten Kristalle. Bringt sie in die Mitte ihres Lagers. Verteilt sie auf dem Boden.\n\nDie Schwingungen und der aufgeladene Kristall werden die Tunnelgräber auf sie hetzen.\n\nSie werden lernen, die Erde zu respektieren...\n\nStück für Stück...\n\nFels für Fels...\n\n... mit der Zeit.", progress = nil, completion = "Die Zeit bringt allen Respekt bei.\n\nDem kleinsten Kiesel.\n\nDem größten Berg.\n\nDem starrsinnigsten Kultisten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26378] = {title = "Heldenaufruf: Westfall!", objective = "Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof in Westfall.", description = "In Westfall herrschen harte Zeiten. Jetzt, da die Bedrohung durch die Defias beseitigt ist, ist das Gebiet zu einer Zuflucht für Obdachlose und Unterdrückte geworden. Die Verbrechensrate in dieser Region ist astronomisch in die Höhe geschossen, da die Leute sich um Unterschlupf und Nahrung zanken. Und jetzt hört man sogar von Mord!\n\nWenn Ihr der Allianz helfen wollt, dann beginnt in Westfall. Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof. Ihr findet Westfall direkt westlich des Waldes von Elwynn.", progress = nil, completion = "Mord, Grünschnabel. Das seht Ihr da auf dem Boden vor uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26379] = {title = "Hilfe für die Flüchtlinge", objective = "Schildwache Lendra in Lor'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.Ich hoffe, Ihr seid hier, um zu helfen! Ihr habt keine Ahnung, wovon ich spreche, oder?\n\nIch habe keine Zeit, um Euch alle Details zu erläutern, aber hier in Dunkelküste gab es einen Ort namens Auberdine, der vom Kataklysmus übel zugerichtet wurde. Wir sind dabei, einige der Überlebenden zu retten, aber ich brauche jemanden mit etwas mehr Erfahrung, der nach dem Flüchtlingslager sieht, das sich im Süden befinden soll. Jemanden wie Euch!\n\nÜberlasst uns die Dinge im Norden. Geht direkt nach Süden und helft den Flüchtlingen, wo Ihr nur könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich hoffe, Ihr seid hier, um zu helfen! Ihr habt keine Ahnung, wovon ich spreche, oder?\n\nIch habe keine Zeit, um Euch alle Details zu erläutern, aber hier in Dunkelküste gab es einen Ort namens Auberdine, der vom Kataklysmus übel zugerichtet wurde. Wir sind dabei, einige der Überlebenden zu retten, aber ich brauche jemanden mit etwas mehr Erfahrung, der nach dem Flüchtlingslager sieht, das sich im Süden befinden soll. Jemanden wie Euch!\n\nÜberlasst uns die Dinge im Norden. Geht direkt nach Süden und helft den Flüchtlingen, wo Ihr nur könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26380] = {title = "Lieferung für Kharanos", objective = "Bringt die Probefässer zu Gastwirt Belm in der Brauerei Donnerbräu in Kharanos.", description = "Ich sollte diese Bierfässer zum Gasthaus von Kharanos bringen. In den Fässern befindet sich ein mysteriöses neues Bier, das von einer neuen Brauerei in Bräuhall hergestellt wird. Als ich die Stadt verließ, wurde ich von Trollen der Frostmähnen überfallen. Ich werde Tage brauchen, um den Wagen zu reparieren!\n\nWürdet Ihr mir vielleicht einen Gefallen erweisen? Die großen Fässer lassen sich nicht bewegen, aber ich habe hier ein paar kleine Probefässer. Würdet Ihr die für mich nach Kharanos bringen? Folgt einfach nur der Straße nach Südosten.", progress = "Seid willkommen, Besucher. Habt Ihr dieses Gasthaus betreten, weil Ihr Euch ausruhen wollt oder weil Ihr einen neuen Ruhestein benötigt?", completion = "Die sehen vielversprechend aus. Ich habe viel Gutes über die Brauerei \"Kurz, aber Deftig\" gehört, aber ihr Bier konnte ich bisher nicht probieren.\n\nEntspannt Euch ein wenig, solange Ihr hier seid. Wenn Ihr einen Ersatzruhestein braucht oder Kharanos zu Eurer Heimat machen wollt, sprecht mich an. Ich helfe Euch gern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZäher Brocken BrotErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26381] = {title = "Das Auge von Shadra", objective = "Holt das Auge von Shadra aus Agol'watha.", description = "Shadra muss gerufen werden, das ist sicher. Uns diese Gelegenheit entgehen zu lassen, wäre schlicht und ergreifend dumm. Die Apotheker finden sicher Verwendung für das Gift der Göttin, aber von Ritualmagie haben sie nicht viel Ahnung.\n\nGlücklicherweise bin ich mit der Vorbereitung dunkler Beschwörungen recht vertraut. Bringt mir die verstreuten Teile Shadras und ich werde sie auf diese Ebene beschwören.\n\nZuerst brauchen wir das Auge von Shadra. Es wird in Agol'watha bewacht.", progress = "Wenn es sich bei den Tafeln um eine Täuschung handelt, werde ich nicht erfreut sein. Habt Ihr das Auge gefunden?", completion = "Ich bin zufrieden, &lt;Name&gt;. Das war schneller, als ich erwartet hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26382] = {title = "Eiertanz", objective = "Sammelt 5 Eier der Shadrabrut aus Agol'watha.", description = "Marnal liegt mir schon seit Tagen mit seinem Shadravorhaben in den Ohren. Ich bereue schon fast, die Tafel wirklich gefunden zu haben – zu dem Zeitpunkt hätte er meiner Meinung nach schon den Mund halten können.\n\nUnd trotz seiner Erfahrung mit Ritualmagie braucht er meine Hilfe genauso sehr wie ich seine. Ich muss ein Basismedium mit ähnlichen...\n\n...wisst Ihr was, ich werde Euch die Einzelheiten ersparen. Bringt mir die Eier der Shadrabrut aus Agol'watha. Ihr solltet dort viele finden – sie werden von den Trollen der Blutfratzen bewacht.", progress = "Ich hoffe, Ihr habt genügend.", completion = "Gut, gut. Legt sie da drüben hin, ich habe beide Hände voll.", rewards = "Surlis' MantelApothekergamaschenGürtel der ShadrabrutBeinschützer der VorsichtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26383] = {title = "Unaufhaltsame Veränderungen", objective = "Benutzt den Teleportbaum im westlichen Teil von Darnassus und reist nach Rut'theran. Sprecht dort mit Vesprystus, um einen Flug nach Lor'danel zu sichern.", description = "Ihr da! Ihr seht fähig aus. Und vielleicht sogar hilfsbereit?\n\nAuberdine ist letztendlich gefallen. Zwar haben viele Einwohner bereits vor langem die Stadt verlassen, als der Kataklysmus uns heimsuchte, doch einige der hartnäckigeren Bewohner wurden noch nicht gefunden. Und jetzt scheint die Stadt auch noch von Elementaren überrannt zu werden.\n\nMeine Schwestern brauchen Hilfe bei der Rettung der Überlebenden. Bitte, <Klasse>, benutzt den westlichen Teleportbaum, um nach Rut'theran zu gelangen, sprecht mit Vesprystus und sichert einen Flug nach Lor'danel. Beeilt Euch!", progress = nil, completion = "Haben die Schildwachen Euch geschickt? Elune sei Dank. Wir brauchen jede Hilfe, die wir bekommen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26384] = {title = "Der dunkle Kleriker Marnal", objective = "Bringt die Tafel von Shadra zum dunklen Kleriker Marnal.\n\nBereitgestellter Gegenstand: \n", description = "Wir können die Tafel noch nicht einfach wegschmeißen, <Name>. Wir können sie benutzen...\n\nWisst Ihr, mir geht es in erster Linie um das Gift der Spinnen. Es ist eindeutig magisch und wahrscheinlich gibt es eine Verbindung zur Spinnengöttin, mit der die Trolle etwas zu tun haben. Und wenn man die Tafel zur Beschwörung nutzen kann...\n\nNa ja, ich glaube, Ihr wisst, worauf ich hinaus will. Die Horde kann sich diese Gelegenheit nicht entgehen lassen. Bringt die Tafel zu den Verlassenen. Sie sind westlich von hier in der Forschungsstation in den Ruinen von Hiri'watha.", progress = nil, completion = "Ah, was haben wir den hier...\n\nFaszinierend. Wirklich faszinierend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26385] = {title = "Unaufhaltsame Veränderungen", objective = "Sprecht mit Vesprystus in Rut'theran, um nach Lor'danel zu fliegen.", description = "Sieht aus, als hättet Ihr Euren ersten Auftrag. Ihr müsst zurück nach Rut'theran reisen, wo wir zuerst ankamen, und mit Vesprystus sprechen, um einen Transport nach Lor'danel zu bekommen.\n\nSeid Ihr erst einmal in Lor'danel angekommen, müsst Ihr den Nachtelfen dort auf jede nur erdenkliche Weise helfen, die Euch möglich ist. Ich vertraue darauf, dass Ihr sie mit dem Respekt behandelt, den sie verdienen, nach Allem was sie für uns getan haben.\n\nIch selbst muss in die ferne Stadt Sturmwind reisen und mich mit König Varian treffen. Ich hoffe, Euer Gesicht bald wieder zu sehen, <Name>. Bis dahin ein herzliches Lebewohl.", progress = nil, completion = "Unsere Verbündeten eilen zu unserer Hilfe? Elune sei Dank! Es war weise von Tyrande, Eurem Volk mit offenen Armen zu begegnen.\n\nWir brauchen Hilfe. Wir brauchen jede helfende Hand, die wir bekommen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26386] = {title = "Surkhan", objective = "Meldet Euch bei Surkhan in Bambala im Nördlichen Schlingendorntal.", description = "Priesterin spricht nicht gut Orcisch, nein.\n\nVielleicht sprecht Ihr mir Surkhan, er ist oben.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen habt, ja.", progress = nil, completion = "&lt;Ihr erklärt Surkhan, was sich bisher ereignet hat.&gt;\n\nEs scheint, dass Jin'do überlebt hat und dass er seine Brüder versammelt, um Hakkar erneut in diese Welt beschwören zu können. Es war eine weise Entscheidung, mit mir zu sprechen.\n\nLeider können wir im Moment nicht sehr viel mehr machen als warten und beobachten. Jin'do ist schwach und die Zeit wäre für einen Angriff gut, aber ich muss auf die Reaktion aus Rastakhan warten, bevor ich Befehle erteilen kann. Bis dahin müsst Ihr und Euer Raptor warten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26387] = {title = "Hungerdiät", objective = "Vernichtet 6 eingesponnene Opfer in den Gruselruinen.", description = "Die Spinnen, die die Gruselruinen östlich von hier heimsuchen, sind nutzlos. Wir nennen sie zwar Shadrabrut und sie sind auch ganz offensichtlich mit der Spinnengöttin verwandt, aber das ändert auch nichts an der Tatsache, dass sie mehr Ärger machen als Nutzen bringen. Mir wäre es lieber, wenn wir die kleinen Plagegeister einfach ausmerzen könnten.\n\nFalls Ihr Euch zu den Gruselruinen aufmachen solltet, tötet alle Kokons, die Ihr finden könnt. Sie ernähren sich tagelang von den Leichen - die Nahrung der Biester zu zerstören wird effektiver sein, als der Versuch, sie alle zu zerquetschen.", progress = nil, completion = "Nun, das ist eine weitaus bessere Situation, von der wir alle etwas haben. Die Spinnen werden entweder verhungern oder sich Zwerge oder Elfen schnappen, um sich zu ernähren. An mir und meinen Kollegen ist ja nichts dran, was ein nahrhaftes Mahl darstellen könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26388] = {title = "Zwielichthimmel", objective = "Begleitet die Luftflotte der Horde ins Schattenhochland. Nehmt den Zeppelin vom Turm an der Südlichen Endhaltestelle der Raketenbahn in Azshara.", description = "In Ordnung, Ihr seid also bereit. Wartet hier, bis Kapitän Krazz den Zeppelin gewendet hat und begleitet dann die Luftflotte. Admiral Steinfaust erwartet Euch beim Hafen des Drachenmals!", progress = nil, completion = "Das ist eine Katastrophe, &lt;Name&gt;!\n\nUnsere Luftflotte wurde dezimiert. Und wir erhalten Berichte, dass unsere Schiffe grundlos auf offenem Meer von der Allianz angegriffen wurden.\n\nUnd was ist mit Höllschrei? Ist der Kriegshäuptling tot?", rewards = "Vom Himmel gefallener PlattengürtelArmschienen des verlorenen AnführersRumpfzerschmetternde SchulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26389] = {title = "Schwarzfelsinvasion", objective = "Bringt 8 Waffen der Orcs des Schwarzfelsklans an Euch.", description = "Die Orcs haben begonnen, den Wald niederzubrennen, <Name>! Sie haben den Weinberg im Osten übernommen und planen ihren Entscheidungsangriff auf uns! Sie müssen aufgehalten werden!\n\nGeht nach Osten, überquert den Fluss und tötet die wildgewordenen Orcs des Schwarzfelsklans. Sammelt als Beweis ihres Ablebens ihre Waffen ein und kehrt zu mir zurück.\n\nIhr seid unsere einzige Hoffnung, <Name>!", progress = "Habt Ihr die wildgewordenen Orchorden getötet?", completion = "Die Orcs des Schwarzfelsklans werden jetzt, da ihre Hauptstreitkraft geschlagen wurde, sicherlich fallen. Nun bleibt nur noch eine Aufgabe.", rewards = "MilizssteckenMilizkurzschwertMilizdolchMilizkriegshammerMilizhammerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26390] = {title = "Setzt der Invasion ein Ende!", objective = "Tötet Kurtok den Schlächter.", description = "Die wütende Orchorde wird von einem Ungeheuer angeführt, das als Kurtok der Schlächter bekannt ist. Kurtok ist für den vor Kurzem erfolgten Einmarsch verantwortlich und muss getötet werden, wenn wir Frieden im Tal haben wollen.\n\nGeht vorsichtig nach Osten zurück, überquert den Fluss und begebt Euch durch den Weinberg. Haltet Ausschau nach der Passage, die in die Berge führt. Dort wird Kurtok sich aufhalten und einen weiteren Angriff vorbereiten. Tötet ihn und kehrt zurück zu mir.", progress = "Habt Ihr Kurtok gefunden?", completion = "Jetzt, da Kurtok tot ist, sind wir wieder vor den Orchorden sicher. Ich werde Arbeiter zum Pass entsenden und versuchen, die Passage zu verschließen, damit dort keine Orcs mehr hindurch und auf unser Gebiet gelangen können.\n\nIhr habt den Dank von Sturmwind und der Allianz, Held.", rewards = "Willems FäustlingeArmbrust des AbteiverteidigersLängst verloren geglaubter StabStab des FriedensbringersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26391] = {title = "Die Hoffnung ersticken", objective = "Benutzt Millys Feuerlöscher, um 8 Brände im Weingut zu löschen.", description = "Tage wie diese lassen mich die Zeiten zurücksehnen, in denen die Defias noch da waren. Der Kataklysmus hat einen Weg aus der Brennenden Steppe geöffnet, und jetzt überlaufen Schwarzfelsorcs das Nordhaintal! Sie haben mein Weingut übernommen und brennen es nieder! SIE BRENNEN ES NIEDER!\n\nBitte, <Name>, dieses Weingut ist alles, was ich habe. Nehmt meinen Feuerlöscher und löscht die Flammen im Weingut. Vielleicht besteht noch Hoffnung für dieses Land!", progress = "Habt Ihr die Feuer gelöscht?", completion = "Seid gesegnet, &lt;Name&gt;. Ihr seid ein wahrer Held der Allianz! Auch wenn dieses Land völlig verbrannt und nichts als Schutt und Asche vom Weingut übrig ist, kann es sich vielleicht erholen. Stimmt's? Wie schlimm kann es schon sein?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Auras\n\nIhr bekommt:\n\nTraubenpflückersackWeinbefleckter Umhang"}
MultiLanguageQuestData['de'][26393] = {title = "Eine eilige Nachricht", objective = "Bringt Argus' Notiz zu Bartlett dem Tapferen, dem Greifenmeister.", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Bartlett den Tapferen, unseren Greifenmeister. Er ist direkt bei der Schmiede; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Sturmwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26394] = {title = "Weiter nach Sturmwind", objective = "Bucht einen Greifenritt bei Greifenmeister Bartlett dem Tapferen, dann bringt Argus' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Argus' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Schmied Argus? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Heutzutage gibt es so viele neue Rekruten.\n\nIch danke Euch, &lt;Name&gt;. Hier habt Ihr etwas Geld für Eure Reisespesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26395] = {title = "Dungar Trinkfest", objective = "Bringt Osrics Kiste zu Dungar Trinkfest, dem Greifenmeister.", description = "<Name>, ich habe alles, worum Argus gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Bartlett in Goldhain gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Argus. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Goldhain ohne neue Ausrüstung sind!", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Goldhain, eh? Seid Ihr schon mal in Goldhain gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26396] = {title = "Rückkehr zu Argus", objective = "Bucht einen Greifenritt nach Goldhain bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Schmied Argus in Goldhain.", description = "Der Name des Greifenmeisters in Goldhain ist Bartlett. Wenn Ihr bereits mit ihm gesprochen habt, könnt Ihr auf einem meiner Greifen zu ihm fliegen.\n\nVergesst nicht: Greifen sind so ausgebildet, dass sie jederzeit in ihre Hauptstadt fliegen können, bringen Euch aber nur zu anderen Greifenmeistern, wenn Ihr schon einmal dort wart.\n\nIhr habt Euch schon einmal mit Bartlett unterhalten, daher sprecht mich einfach erneut an, wenn Ihr auf einem Greifen nach Goldhain fliegen wollt. Sobald Ihr da seid, könnt Ihr Osrics Kiste zu Schmied Argus bringen.", progress = "Ihr seid zurück aus Sturmwind? Hat Osric die Rüstungen geschickt?", completion = "Wunderbar, Ihr habt die Rüstungen gebracht! Wir werden sie sofort unter denen verteilen, die sie brauchen.\n\nVielen Dank, &lt;Name&gt;. Ihr wart uns wirklich eine große Hilfe. Und jetzt, da Ihr Euch ein wenig mit den Greifen vertraut gemacht habt, hoffe ich, dass Ihr öfter kommt und Goldhain unterstützt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26397] = {title = "Geht mit der Erdenmutter", objective = "Bringt das Mal von Bluthuf zu Garrosh Höllschrei in der Feste Grommash in Orgrimmar.\n\nSprecht mit Tal dem Windreitermeister oder wartet auf den Zeppelin, um Eure Reise anzutreten.", description = "Viel hat sich geändert in der Welt außerhalb Mulgores, <Name>. Die Welt ist gebrochen und unsere Verbündeten der Horde haben dunkle Wege eingeschlagen. Wir müssen sie leiten. Selbst in der dunkelsten aller Stunden werden wir unsere Köpfe mutig hoch erhoben haben und der Erdenmutter Ehre erweisen.\n\nIhr müsst Euch auf den Weg machen und der Welt ein gutes Beispiel sein. Reist nach Orgrimmar. Berichtet Kriegshäuptling Höllschrei, dass die Grimmtotem vertrieben wurden. Berichtet von unserem Stolz, unserer Disziplin, unserer Stärke und unserem Leid.\n\nTal beim Himmelsturm wird Euch auf den Weg schicken. Geht in Frieden, und vergesst nie, wo Ihr herkommt.", progress = "Was ist Euer Anliegen beim Kriegshäuptling der Horde, <Volk>?", completion = "Die Grimmtotem aus Mulgore vertrieben... wenn Baine möchte, dass dies gehört wird, so seid Ihr wohl wirklich ein gefährlicher Kämpfer.\n\nVom heutigen Tag an wird Eure Stärke nicht mehr Euch gehören. Sie gehört nun mir und der Horde und ist eine Waffe für den Krieg.\n\nHöllschrei wacht über Euch, &lt;Name&gt;. Bringt den Sieg oder findet den Tod!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26399] = {title = "Die Schatzkiste der Mosh'Ogg", objective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tipp von 'nem Typen namens Mok'thardin bekommen, dass so <'n schwachköpfiger/'ne schwachköpfige:r> <Volk>, lächerlich angezogen wie <ein/eine:c> <Klasse>, 'ne Ogerhand gefunden hat und...\n\n<Skeezy bricht ab und mustert Euch.>\n\nWas sagte ich gerade? Ach ja... <ein SCHWERTSCHWINGENDER HELD/eine ATEMBERAUBENDE HELDIN> fand diese Ogerhand und Mok'thardin glaubt deswegen, dass die Oger ein besonderes Artefakt haben. Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", progress = "Wie kommt es, dass ausgerechnet OGER immer die unbezahlbaren Artefakte finden?", completion = "&lt;Skeezy müht sich vergebens ab, den Kasten zu öffnen.&gt;\n\nDiese Oger wissen wirklich, wie man eine Schatztruhe verschließt. Ich sag' Euch 'was... Ein Kasten bringt mir nichts, Held. Wir müssen einen Weg in diese Kiste hinein finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26400] = {title = "Der Universalschlüssel", objective = "Öffnet die Belohnung der Mosh'Ogg, indem Ihr gegen einen Schredder der Venture Co. kämpft, oder die Sägeklinge im Sägewerk der Venture Company benutzt.", description = "Wir brauchen etwas stärkeres, als Eure fleischigen Hände, um das hier zu öffnen. Und die Trottel der Venture Company im Nordwesten haben möglicherweise genau das Richtige.\n\nDas letzte Mal, als ich da drüben war, sah ich Schredder herumlaufen, die riesige, rotierende Klingen an den Händen hatten. Das wäre eine Möglichkeit, einen Kasten zu öffnen.\n\nWenn Ihr keine Schredder findet, könnt Ihr auch die riesige Sägeklinge in ihrem Sägewerk am See ausprobieren.", progress = "Habt Ihr die Kiste schon geöffnet? Ich kann es kaum erwarten, zu sehen, was sich darin befindet.", completion = "&lt;Der Goblin späht hinein.&gt;\n\nWaaaaaaaa...?!?\n\nIch... Ich muss das zu... zu Flem... im Süden schicken. Er wird etwas damit anzufangen wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26401] = {title = "Rückkehr zu Vestia", objective = "Bringt das Graunebelamulett zu Vestia Mondspeer im Turm von Estulan.", description = "Das sanfte Leuchten des Podests wird stärker. Ihr seht eine schlichte Kette, die zurückgelassen wurde. War es das, wonach der Lehrling gesucht hatte?", progress = "Ihr seid zurück… ohne ihn….", completion = "Wie schrecklich, dass jemand so voller Jungend und Talent den Dämonen zum Opfer fallen musste!\n\nBitte, verzeiht mir, dass ich auch Euch in Gefahr gebracht habe, &lt;Name&gt;. Ich hoffe, dass Ihr dieser Dämonin nie wieder begegnen müsst…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26402] = {title = "General Shandris Mondfeder", objective = "Sprecht mit Shandris Mondfeder in der Mondfederfeste in Feralas.", description = "Wir Druiden haben nicht besonders viel mit den Schildwachen zu tun, aber wir arbeiten bereitwillig zusammen, um unser Land zu verteidigen. Jetzt, da Ihr mir geholfen habt, wäre es äußerst nachlässig, wenn ich Euch nicht bitten würde, auch ihnen zu helfen.\n\nShandris Mondfeder, General der Schildwachen, hat den Oberbefehl über alle militärischen Vorgänge in Kalimdor. Sie hält sich in der neu errichteten Mondfederfeste im Süden auf. Sagt Ihr, dass ich Euch schicke. Ich bin mir sicher, dass sie Eure Fähigkeiten benötigt.", progress = nil, completion = "Telaron hat mir bereits von Euch berichtet, &lt;Name&gt;. Ich bin gespannt, ob Ihr nur halb so talentiert seid, wie er behauptet.\n\nIch kämpfe einen Krieg an mehreren Fronten und kümmere mich gleichzeitig darum, dass unsere Gebiete richtig verteidigt und unsere jüngsten Schildwachen richtig ausgebildet werden. Wenn Ihr ein geschickter Kämpfer seid, habe ich genug für Euch zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26403] = {title = "Venture Company-Bergbau", objective = "Bringt 5 gerommelte Kristalle zu Skeezy Whillzap in Bambala im Nördlichen Schlingendorntal.", description = "Mann, ich hasse die Venture Company. Sie haben eine ganze Reihe von Operationen überall im Schlingendorntal, die hart arbeitende Goblins wie mich davon abhalten, ehrliches Gold zu verdienen!\n\nWie ich das mache? Durch Diebstahl. Die Geologen der Venture Co. in der Nähe des Nazferitisees im Nordwesten sind sehr an diesen merkwürdigen blauen Kristallen interessiert, die sie in den Minen finden. Bringt mir Proben dieses Gesteins von ihren Geologen. Mir ist egal, was Ihr tun müsst, um sie zu erhalten.", progress = "Habt Ihr die Kristalle? Ich brauche sie!!\n\nIch meine... ich muss wissen, dass die böse Venture Company im Schlingendorntal an Boden verliert. Denn wisst Ihr, wir ehrlichen Leute müssen unseren Lebensunterhalt verdienen!", completion = "Großartig! Wunderbar! Die werden mir einiges einbringen!!\n\nDiese Venture Company hat sich den falschen Dschungel zum Schürfen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwinden.", rewards = "DschungelsammlerhandschuheHeruntergekommene ArmschienenSchulterstücke aus AltmetallIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26404] = {title = "Höhere Lohngruppe", objective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.", description = "Hey, seid Ihr schon in Hartzangs Versteck gewesen? Oh, das MÜSST Ihr sehen. Das ist alles, was ein Goblin sich je erträumen kann.\n\nIch sag Euch was... Ihr seht aus, wie <ein überzeugter/eine überzeugte:c> <Klasse>. Rashka, die da drüben in Weste und Rock, kann Euch einen Flug verschaffen, wenn Ihr den Weg nicht bereits kennt.\n\nDer Flug geht auf mich.", progress = nil, completion = "Skeezy hat Euch an den richtigen Ort geschickt. Willkommen in Hartzangs Versteck!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26405] = {title = "Mambo in Zul'Mamwe", objective = "Tötet 16 Trolle der Schädelspalter in Zul'Mamwe.", description = "Die Schädelspalter sind eine Schande für das ganze Trollreich. Ihre kindischen Zankereien mit den Blutskalpen haben das Nördliche Schlingendorntal zerrissen. Während Stämme wie die Dunkelspeere und die Zandalari erblühen, kämpfen die Schädelspalter um Ruinen.\n\nIch wurde ermächtigt, allen Söldnern eine Belohnung zu bezahlen, die bereit sind, den Schädelspaltern eine Lektion zu erteilen. Ich ermutige daher Euch und alle, die Ihr kennt, nach Zul'Mamwe zu reisen und ihrem abtrünnigen Stamm ein Ende zu setzen.", progress = nil, completion = "Hier ist Eure Belohnung, wie versprochen. Ihr erfüllt das Volk der Trolle mit Stolz.", rewards = "Verstrahlte Armschienen aus KrokodillederimitatBrustplatte von Zul'MamweSchulterstücke des abtrünnigen StammesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26406] = {title = "Der Fangzahn von Shadra", objective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", description = "Als nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Ihr Gift ist stark, <Name>... werdet nicht unvorsichtig.", progress = "Habt Ihr den Fangzahn?", completion = "Da ist er... nur noch einer übrig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26407] = {title = "Die Handschrift von Mosh'Ogg", objective = "Bringt die entstellte Hand eines Mosh'Ogg zu Scharfseher Mok'thardin im Basislager Grom'gol im Nördlichen Schlingendorntal.", description = "Dieser Oger hatte einen ungewöhnlichen Gegenstand bei sich: die abgetrennte Hand eines anderen Ogers, die er an einer Schnur befestigt um den Hals trug Die Hand selbst weist viele Narben auf, die in einem schwachen lila leuchten.\n\nEine Narbe, die nach dem Tod leuchtet, ist höchst ungewöhnlich. So einen Gegenstand bei einem Oger zu finden, ist noch merkwürdiger. Vielleicht weiß jemand in Grom'gol etwas mit dieser Kuriosität anzufangen.", progress = "Eine Hand sagt Ihr?", completion = "&lt;Der Scharfseher achtet darauf, dass er den Gegenstand an der Schnur hält und vermeidet sorgfältig, die Faust des toten Ogers zu berühren.&gt;\n\nDas ist in der Tat merkwürdig. Ich werde das meinen Kontakten im Osten, in der Nähe des Hauptlagers der Mosh'Ogg, unterbreiten. Ich habe so ein Gefühl, als ob sie sich für diese seltsamen Narben interessieren könnten.\n\nIch danke Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26408] = {title = "Asche im Eschental", objective = "Sprecht mit Schildwache Shyela bei Orendils Zuflucht im Eschental.", description = "Dunkelküste mag zerschlagen und zerschmettert sein, aber dank Euch haben wir hier ein gewisses Maß an Sicherheit erlangt. Ein gewisses Maß an Frieden. Wir müssen noch viel wieder aufbauen.\n\nIhr solltet weitermachen, <mein Freund/meine Liebe>. Garrosh hat die geballte Macht seiner Horde gegen uns im Eschental aufgefahren. Sie werden uns alle töten und den Wald roden, wenn wir nicht gegen sie vorgehen.\n\nUm Hoffnung zu bewahren, diese Wälder nicht vollständig aufgeben zu müssen, benötigen wir Eure Hilfe. Folgt der Straße in Richtung Süden und sucht Schildwache Shyela auf.", progress = nil, completion = "Schön, ein neues Gesicht in dieser Gegend zu sehen!\n\nDie Horde kriecht überall in den Wäldern herum, aber mein Auftrag sieht vor, dass ich diesen Außenposten absichere. Ich könnte wirklich jemanden gebrauchen, der ein wenig Kampflust mitbringt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26409] = {title = "Wo ist Goldmine?", objective = "Findet Initiand Goldmine am Quarzitbecken in Tiefenheim.", description = "Mein goblinischer Initiand ist schon eine ganze Weile fort. Sein Name ist Goldmine.\n\nIch habe ihn losgeschickt, um die Felsklauen im Südwesten im Quarzitbecken zu beobachten. Wärt Ihr bereit, ihn zu suchen? Wenn Ihr ihn findet, bittet ihn, zum Tempel zurückzukommen.", progress = nil, completion = "Hallöchen! Könnt Ihr mir vielleicht kurz helfen, Spezi?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26410] = {title = "Explosive Verbundmasse", objective = "Sammelt 5 Einheiten Quarzitharz.", description = "Dieser Kerl ist der Sohn des Anführers der Irdenen! Er hatte es schon fast zurück in den Tempel geschafft, als er von mehr Felsklauen angegriffen wurde, als ich zählen konnte!\n\nWir wissen, dass der Steinvater der Irdenen das mittlere Fragment der Weltensäule besitzt. Wenn wir seinen Sohn heilen, gibt er uns vielleicht das Fragment.\n\nMeine Heilzauber funktionieren bei Flint hier nicht. Aber wenn wir an etwas Quarzitharz von diesen Monstern kommen könnten, könnte ich eine explosive Verbundmasse herstellen, die seine Wunden schließt und kauterisiert.", progress = "Ich brauche nicht viel Harz. Diese Felsklauen sind jedoch ziemlich gefährlich.", completion = "Was für ein Glück, dass ich zufällig Großmeister der explosiven Alchemie bin.\n\nDas hier wird sich aber nicht von allein entzünden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26411] = {title = "Blitztrocknung", objective = "Behandelt Flint Erzmantel mit der explosiven Verbundmasse.", description = "In Ordnung, nehmt dies und gebt es auf seine Wunden. Wenn die blitzartige Kauterisation ihn nicht in Stücke reißt, sollte er dadurch vollständig heilen.\n\nGlaube ich…", progress = "Quasselt mich nicht voll. Behandelt Flint mit der explosiven Verbundmasse.", completion = "Sieht aus, als hätte es gewirkt. Er sollte jeden Moment zu sich kommen.\n\nIch habe Euch doch gesagt, dass ich ein Großmeister der Alchemie bin!\n\nIch habe noch etwas Harz übrig. Daraus kann ich allerlei wundervolle explodierende Dinge bauen. Was wollt Ihr haben?", rewards = "BlitzbrandgurtArmschienen des brennenden VerbandesWundenkauterisierende SchiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26412] = {title = "Die Schatzkiste der Mosh'Ogg", objective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tipp von 'nem Typen namens Mok'thardin bekommen, dass sie ein ganz besonderes, magisches Artefakt in ihrer Höhle verstecken. Skeezy weiß das aber besser. Ich rieche Geld aus einer Mulgoremeile Entfernung und ich wette, das Ogerdingsbums ist ein Vermögen wert.\n\nHier ist ein Hinweis: Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26413] = {title = "Bringt ihn zur Erdenruferin", objective = "Bringt Flint Erzmantel zu Erdenruferin Yevaa im Tempel der Erde.", description = "Er scheint mir immer noch etwas wackelig auf den Beinen zu sein. Sein Kopf muss dröhnen.\n\nAm besten bringt Ihr ihn in den Tempel zur Erdenruferin und schaut, was sie für ihn tun kann.\n\nIch werde noch ein Weilchen hier draußen bleiben und diese Felsklauen \"beobachten\".", progress = "Einer der Irdenen? Das ist eine unerwartete und günstige Überraschung, <Name>.", completion = "Die Anwesenheit von Flint Erzmantel ehrt uns. Wie ich gehört habe, befindet sich ein Fragment der Weltensäule im Besitz des Steinvaters.\n\nEs ist von oberster Wichtigkeit, dass wir alle Fragmente wiedererlangen. Die Instabilität zwischen den Welten wird immer stärker. Bald ist sie vielleicht schon so groß, das nicht einmal der mächtige Thrall ihr Einhalt gebieten kann.", rewards = "Schädelkappe des GlöcknersSchinderstampferstiefelBeine der klingenden EchosIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26414] = {title = "Einen Zander erwischen", objective = "Catherine Leland in Sturmwind möchte, dass Ihr ihr 8 verhärtete Zander bringt.", description = "Manchmal fische ich zum Spaß. Dann wieder, um zu entspannen, aber manchmal brauche ich eine Herausforderung. Da kommt der verhärtete Zander ins Spiel. Dieser wertvolle Fisch wird nicht als Speise gefangen, sondern wegen der Herausforderung. Ihr werdet den Zander im Sturmwindsee nördlich der Stadt finden. Glaubt Ihr, Ihr seid der Herausforderung gewachsen?", progress = "War die Herausforderung zu viel für Euch?", completion = "Gute Arbeit, &lt;Name&gt;. Wie ich sehe, seid Ihr inzwischen ein ziemlich guter Angler. Vielleicht sollte ich Euch bald mit dem Boot mit hinausnehmen, um zu sehen, was Ihr wirklich könnt!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26416] = {title = "Auf in den Dschungel", objective = "Meldet Euch bei Bort in Orgrimmar.", description = "Mein Kommandant hat mich ausgeschickt, um nach Rekruten Ausschau zu halten, die bei der Verteidigung des Basislagers von Grom'gol im Nördlichen Schlingendorntal helfen. Kennt Ihr das Schlingendorntal? Es ist sehr weit weg... Man muss das Große Meer überqueren, und dann befindet es sich an der südlichen Spitze der Östlichen Königreiche. Ihr passt auf die Beschreibung, die er mir gegeben hat... Seid Ihr daran interessiert, Kalimdor für eine Weile zu verlassen?\n\nWenn ja, sprecht mit meinem Kollegen Bort in Orgrimmar. Er wird Euch behilflich sein, an Bord des Zeppelins zu gehen.\n\nUnd sagt ihm von mir \"Wusel-Dusel\". Er weiß schon, was das bedeutet.", progress = nil, completion = "Hah! Diese Allumpass ist wirklich zu komisch.\n\nOh, stimmt ja, Schlingendorntal. Ihr wollt wirklich dorthin?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26417] = {title = "Das Nördliche Schlingendorntal: Das Gefallene Reich", objective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", description = "Kommandant Aggro'gosh sucht nach ergebenen Hordenmitgliedern, um ihm bei seiner Mission in Grom'gol zu helfen. Wenn Ihr interessiert seid, geht einfach oben auf den Zeppelinturm und besteigt den Zeppelin nach Grom'gol. So einfach ist das!\n\nIm Ernst, das Schlingendorntal ist momentan genau der richtige Aufenthaltsort... Dort gibt es reichlich Action und nicht annähernd so viel Schäden durch den Kataklysmus wie im... sagen wir... Steinkrallengebirge. Ich wünschte, ich könnte mit Euch kommen.", progress = nil, completion = "Schön, dass Ihr es geschafft habt! Gehen wir an die Arbeit, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26418] = {title = "Der Panzer von Shadra", objective = "Tötet Qiaga die Bewahrerin und besorgt den Panzer von Shadra.", description = "Wir müssen noch einen weiteren Teil finden und dann haben wir alles, was wir brauchen.\n\nDer Panzer von Shadra wird von der letzten lebenden Priesterin der Spinnengöttin bewacht, von Qiaga der Bewahrerin. Sie ist auf dem Altar von Zul und wird von anderen fanatischen Zeloten bewacht.\n\nEin Kinderspiel, oder? Steigt die Treppen des Altars hoch und lasst ihren Kopf die Treppen runter rollen. Bringt mir den Panzer und wir können Shadra endlich beschwören.", progress = "Habt Ihr den Panzer?", completion = "Ja... endlich ist es soweit. Shadra wird unser sein!", rewards = "Robe der letzten PriesterinGwenyths ArmschienenHandschuhe des fanatischen EifernsGroßaxt des HinterlandsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26419] = {title = "Shadra, Königin des Giftes", objective = "Tötet Shadra, die Königin des Giftes.", description = "<Der Boden wackelt als der Götze auf den Altar gesetzt wird und der See beginnt zu schäumen! Shadra erscheint!>", progress = nil, completion = "Ausgezeichnete Arbeit. Ihr habt der Dunklen Fürstin gute Dienste geleistet, &lt;Name&gt;.\n\nIhr böses Blut wird unsere Armeen mit einer mächtigen Waffe gegen die verachtenswerte Allianz bieten. Wir werden sie aus diesen Ländern vertreiben.\n\nFür die Horde, versteht sich... und alles dank Eurer Hilfe.", rewards = "Schleier des dunklen KlerikersVirulenter KopfschutzGiftige KopfbedeckungHelm des VergiftersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26420] = {title = "Nach Würmern graben", objective = "Findet einen übergroßen Regenwurm in der Nähe von Olivias Teich und benutzt ihn als Köder, um einen Kristallbarsch zu fangen. Kristallbarsche findet man in Olivias Teich, nördlich von Sturmwind.", description = "He da, Angler! Arnold hier sagt, dass Ihr nach einem neuen Angelpunkt sucht und ich glaube, ich kenne genau den richtigen Ort. Nördlich von Sturmwind gibt es ein kleines Fleckchen Erde, das Olivias Teich heißt.\n\nDer Teich wird jedes Jahr mit neuen Kristallbarschen bestückt, aber sie sind schwer zu fangen. Sie beißen nur bei einem bestimmten Köder... Übergroße Regenwürmer. Wenn Ihr das Ufer des Teichs absucht, solltet Ihr ausreichend Würmer finden, die Ihr als Köder benutzen könnt.", progress = "Hat der Köder funktioniert?", completion = "Das sind doch mal nette Barsche, &lt;Name&gt;. Lasst sie uns braten und probieren, wie sie schmecken!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26421] = {title = "Der Hochtüftler", objective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Name&gt;. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", rewards = nil}
MultiLanguageQuestData['de'][26422] = {title = "Der Hochtüftler", objective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Name&gt;. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", rewards = nil}
MultiLanguageQuestData['de'][26423] = {title = "Der Hochtüftler", objective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Name&gt;. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", rewards = nil}
MultiLanguageQuestData['de'][26424] = {title = "Der Hochtüftler", objective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Name&gt;. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", rewards = nil}
MultiLanguageQuestData['de'][26425] = {title = "Der Hochtüftler", objective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][26426] = {title = "Ein grausamer Sturm", objective = "Findet Felsen den Ausdauernden und folgt seinen Anweisungen, um in die Bruchtiefen zu gelangen.", description = "Es gibt eine Aufgabe, die ich Euch anvertrauen kann.\n\nEs ist eine gefährliche Aufgabe. Wenn Ihr sie erfüllt, könnt Ihr weitere der sturen Steinlords beeindrucken.\n\nIm Nordwesten findet Ihr den Geschliffenen Schlund. Harte Winde schlagen dort gegen die Felsen und verbergen die wahre lebende Bedrohung darunter.\n\nIn den Geschliffenen Weiten leben die Schleifwürmer. Sie fressen sich durch die Felsen, als wären sie aus Wasser. Dasselbe tun sie auch mit unserer Steinhaut.\n\nSucht Felsen den Ausdauernden. Er wird Euch sagen, wie Ihr in die Bruchtiefen gelangt. Ich werde mit Euch sprechen, sobald Ihr dort angelangt seid.", progress = nil, completion = "&lt;Der Boden zittert ein wenig, als Ihr Euch der Höhle nähert. Dies scheint der Eingang zu sein, von dem Diamant und Felsen gesprochen haben.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26427] = {title = "Ohne Kapitän oder Besatzung", objective = "Bringt dem Ersten Maat Mürrisch eine Whiskeyflasche und eine Seilspule.", description = "Ich weiß nicht, zu wem Ihr gehört, aber Ihr seht nicht aus wie einer von… ihnen.\n\nIch weiß nicht, was geschehen ist. Ich habe das Abendessen verschlafen und bin dann auf einem Schiff voller Toter und Mörder aufgewacht.\n\nIch weiß nicht, ob Ihr mich töten wollt, aber ich erspare Euch die Mühe.\n\n<Mürrisch zeigt auf eine Wunde in seinem Bauch. Seine Innereien sind nicht mehr da, wo sie sein sollten.>\n\nIch kann das Schiff noch eine Weile steuern. Von einer Bauchwunde stirbt man nicht sofort. Bringt mir einfach ein Stück Seil und etwas Rum... nein, Whiskey.", progress = "Habt Ihr, worum ich Euch gebeten habe?", completion = "In Ordnung. Helft mir, mich ans Steuer zu binden.\n\n&lt;Mürrisch nimmt einen Schluck aus der Flasche.&gt;", rewards = "Treter des MitternachtsdienstesHandschuhe des MüßiggangsSchanghaiergürtelDer folgende Zauber wird auf euch gewirkt:\n\nWithout Captain or Crew Completion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26428] = {title = "Von Dieben stehlen", objective = "Enthauptet Kenata Dabyrie, Fardel Dabyrie und Marcel Dabyrie.", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie ist tot, Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alldem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich will ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", progress = "Tötet sie alle und bringt mir ihre Köpfe!", completion = "Ihr steht als Racheengel vor mir und ich verneige mich dankbar vor Euch.\n\nNachdem diese Kuh tot ist und ich weiß, dass ihre Brut sich nicht mehr über Azeroth ausbreiten kann, kann ich meine Energie lukrativeren Dingen zuwenden. Ich hoffe, Ihr habt ihren Bauernhof geplündert, als Ihr sie getötet hattet.", rewards = "Craigs StahlGrimmiger StreitkolbenGenavies GamaschenEhebrecherischer GürtelTreter der nie vergessenen SchmerzenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26429] = {title = "Zerschmettert die Bleichborken", objective = "Tötet 10 Axtwerfer der Bleichborken, 10 Kopfjäger und 8 Hexendoktoren.", description = "Die Trolle der Bleichborken und die Oger der Felsfäuste aus Arathi arbeiten Hand in Hand, um uns aus diesen Landen zu vertreiben. Doch weder sie, noch jemand anders wird unser Schicksal besiegeln. Wir werden sie vernichten und ihnen zeigen, dass auch wir hier unsere Heimat haben. \n\nDie Trolle haben sich von uns abgewendet; die Oger benutzten uns als Nahrung und Bettzeug, wenn wir es zuließen. Das darf einfach nicht sein.\n\nWir beginnen unseren Angriff bei den Trollen der Bleichborken südlich von hier. Schlachtet sie scharenweise ab und kehrt erst dann zurück, wenn ihre Lager blutgetränkt sind.", progress = nil, completion = "Eure Kleidung zeugt von Krieg und von Eurer Stirn läuft der Schweiß. Das ist gut, sehr gut sogar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26430] = {title = "Das Dorf der Bruchhauer", objective = "Reist zum Dorf der Bruchhauer im Hinterland und sprecht mit dem Ältesten Stumpfhauer.", description = "Nicht alle Waldtrolle sind widerliche Plagegeister wie die Bleichborken. Nördlich von hier im Hinterland befindet sich das Dorf der Bruchhauer, Heimat der einzigen Waldtrolle, die noch mit der Horde verbündet sind.\n\nSogar sie können sich der Grausamkeit ihrer Brüder nicht entziehen. Der Stamm der Blutfratzen liegt mit ihnen im Krieg und lenkt sie von unserem Kampf gegen die Allianz ab.\n\nIhr habt hier gut gekämpft. Sprecht mit Urda, wenn Ihr ins Dorf der Bruchhauer fliegen möchtet. Ihr Dorf könnte Eure Stärke gut gebrauchen.", progress = nil, completion = "Willkommen im Dorf der Bruchhauer, &lt;Klasse&gt;. Ich hoffe, dass der Kampf gegen die Bleichborken Euch nicht ausgelaugt hat - die Blutfratzen sind noch schlimmer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26431] = {title = "Archäologie", objective = "Nehmt diese Quest an, um Archäologiepunkte auf Eurer Landkarte zu finden!", description = "Nehmt diese Quest an, um Archäologiepunkte auf Eurer Landkarte zu finden!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][26432] = {title = "Der Fall von Jintha'Alor", objective = "Findet Ura Stumpfhauer bei Jintha'Alor im Hinterland.", description = "Wir müssen uns um weit mehr kümmern, als nur Zwerge, Mann. Während ich das Dorf bewache, führt meine Freundin Ura Stumpfhauer unsere Krieger gegen den gemeinen Blutfratzenstamm.\n\nSie haben unsere Brüder getötet und ich wurde sogar einmal von ihnen gefangen genommen. Jetzt ist es genug! Dieses Mal fällt die Stadt Jintha'Alor in unsere Hände.\n\nGeht nach Jintha'Alor und sprecht mit meiner Freundin. Sie hat ein Lager nahe des Eingangs zur Stadt erobert.", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Wir werden dafür sorgen, dass die Blutfratzen es bereuen, uns über den Weg gelaufen zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26433] = {title = "Das heilige Wasser der Klarheit", objective = "Beschafft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen am Schlingendornkap.", description = "Skeezy hat schon gesagt, dass Ihr kommen würdet. Dann lasst uns dieses... Ding mal identifizieren.\n\nZunächst müsst Ihr das heilige Wasser der Klarheit besorgen. Die Naga im Südosten unterhalten einen heiligen Schrein, aus dem köstliches klares und pures Wasser fließt. Sobald man auch nur einen Schluck von diesem heiligen Wasser schlürft, wird der Geist geläutert und der beste Weg liegt dem Trinkenden klar vor Augen.\n\nHört sich gut an, nicht wahr?\n\nBeschafft es aus dem Nek'maniquellbrunnen, der sich an dem höchsten Punkt des Nagacamps befindet. Viel Glück!", progress = "<Flem spitzt die Ohren, als Ihr Euch nähert.>\n\nDas heilige Wasser der Klarheit? Ist es hier!?", completion = "&lt;Der Goblin stürzt das Wasser in einem Zug hinunter.&gt;\n\nAhh... Wisst Ihr, wie schwer es ist, hier im Schlingendorntal frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so erbittert verteidigen.\n\nOh, stimmt ja... Euer Artefakt und Klarheit. Klarheit...\n\nIch hab's!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26434] = {title = "Ursprüngliche Reagenzien der Macht", objective = "Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.", description = "Ich sehe es jetzt ganz deutlich... Der Schlüssel, um diesen mysteriösen Talisman zu identifizieren, liegt bei einigen sehr seltenen und wertvollen Gegenständen. Diese ursprünglichen Reagenzien der Macht werden uns den Ursprung des Schatzes enthüllen, wenn sie richtig kombiniert werden.\n\nReist nach Norden auf die Westseite der Arena der Gurubashi und jagt die Katzen, die den Dschungel durchstreifen. Ihre flauschigen Felle werden uns zur Wahrheit führen!", progress = "Achtet darauf, dass die Reagenzien ganz besonders kuschelig sind, <Name>. Kratzende Reagenzien reichen einfach nicht.", completion = "&lt;Flem streicht über die Felle und lächelt versonnen.&gt;\n\nAusgezeichnete Arbeit, &lt;Name&gt;! Diese Reagenzien werden perfekte Dienste leisten.", rewards = "VersteckstabNichtkratziger HelmAuf Euch wartet eine dieser Belohnungen:\n\nSamthalsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26435] = {title = "Ich bin ein gewaltiger Lügner und Betrüger", objective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Garley Lichtreiter in Beutebucht am Schlingendornkap.", description = "Ich habe keine Ahnung, was dieses Artefakt ist. Ich habe auch keine Ahnung, wo ich überhaupt ANFANGEN sollte, herauszufinden, was das ist.\n\nUm genau zu sein habe ich keine Ahnung, warum überhaupt jemand auf die Idee kam, dass ICH in der Lage sein könnte, es zu identifizieren.\n\nIch habe um Wasser gebeten, weil ich Durst hatte. Ich habe um Juwelen und Felle gebeten... nun, für meine Freundin.\n\nHoffentlich kann ich Euch wenigstens die richtige Richtung weisen. Garley Lichtreiter in Beutebucht ist ein Mitglied der Archäologischen Akademie und könnte möglicherweise hilfreicher sein, als ich es war.\n\nTut mir leid.", progress = "Ja, <Volk>? Ich bin sehr beschäftigt.", completion = "Faszinierend!\n\nIch brauche etwas Zeit, um mir das genauer anzusehen. Warum seht Ihr Euch nicht ein wenig in Beutebucht um und kommt später wieder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26436] = {title = "Verwurzelt", objective = "Findet Kor den Unbeweglichen bei den Berstenden Säulen.", description = "Eure Absichten scheinen ehrlich zu sein.\n\nIch werde den anderen Steinlords von meinem vorsichtigen Vertrauen erzählen.\n\nDanach sollten sie gewillt sein, mit Euch zu sprechen.\n\nUnd was noch wichtiger ist, sie sollten gewillt sein, zuzuhören.\n\nIhre Gunst zu erlangen, wird Zeit in Anspruch nehmen. Die Gunst der Steinmutter zu erringen, wird wohl noch länger dauern. Zeit ist ein wirksames Geschenk, geht also großzügig damit um.\n\nBei den Berstenden Säulen, weit im Nordwesten, findet ihr Kor den Unbeweglichen. Er hat ein ausgeglichenes Gemüt. Aufgrund seiner Lage ist er auf Hilfe von anderen angewiesen.\n\nGeht zu ihm.", progress = nil, completion = "Diamant sagt, dass man Euch vertrauen kann. Diamant ist geduldig und weise, also werde ich Euch die Möglichkeit geben, Euch zu beweisen.\n\nWie es der Zufall will, könnte ich Hilfe von jemandem gebrauchen, der etwas… beweglicher ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26437] = {title = "Kristallklar", objective = "Sammelt 8 kalkhaltige Kristallformationen.", description = "Bei den Berstenden Säulen befinden sich Kristalle. Weiße, kalkhaltige Kristalle. Wir können diese Kristalle in unsere Haut absorbieren. Um uns zu reinigen. Uns zu läutern.\n\nIch wandle nicht mehr zwischen den Steinen. Ich bin eins mit der Erde. Das hat viele Vorteile, doch ich kann mir die Kristalle nicht mehr selbst beschaffen.\n\nBringt mir die Kristalle, so dass ich stärker werde. Nehmt sie den Felsklauen weg. Nehmt sie meinen Söhnen weg. Diese Ehre sollte nur mir vorbehalten sein.", progress = "Habt Ihr mir den Gefallen getan, um den ich Euch bat? Habt Ihr mir die Kristalle gebracht?", completion = "Ahh… erfrischend. Vielen Dank, Fleischling.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26438] = {title = "Intervention", objective = "Tötet 12 Jaspisspitzenfelsklauen.", description = "Die Felsklauen sind wahnsinnig vor Hunger. Einst gruben sie mit Bedacht und Mäßigung. Jetzt ist ihr Hunger jedoch unersättlich. Sie sind blutrünstig und gewalttätig geworden.\n\nSie haben sich gegen meine Söhne gewandt. Sie überwältigen sie. Tötet sie. Es muss aufhören.\n\nTötet die Felsklauen. Sie erfüllen keinen Zweck auf dieser Welt. Niemand wird sie vermissen. Rettet meine Söhne. Tötet alle Felsklauen, die Ihr finden könnt.", progress = nil, completion = "Ihr habt Euch als nützlich erwiesen, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26439] = {title = "Die Teile zusammenfügen", objective = "Helft 6 schlafenden steingebundenen Elementaren dabei, sich neu zusammenzufügen.", description = "<Volk>. Wenn Ihr den Steinlords dient, gibt es jemanden, der Euch vielleicht helfen wird.\n\nHaltet nach den Steingebundenen Ausschau. Sie schlafen überall bei den Berstenden Säulen verteilt. Es sollte kein Problem sein, sie aufzufordern, sich neu zu binden und Euch gegen die Felsklauen zu unterstützen.", progress = nil, completion = "Danke, &lt;Volk&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26440] = {title = "Anhänglich", objective = "Bringt Kieselchen zur großen Kristallformation in den Berstenden Säulen.", description = "<Ein winziger Elementar scheint Gefallen an Euch gefunden zu haben.>\n\nKiris… Krissi… Kristall? <Kieselchen schaut Euch erwartungsvoll an.>\n\n<Erst jetzt bemerkt Ihr die riesige Kristallformation in der Mitte der Berstenden Säulen. Vielleicht solltet Ihr ihn dorthin bringen?>", progress = "<Kieselchen schaut Euch erwartungsvoll an.>", completion = "&lt;Die Steine in Kieselchens Körper springen fröhlich auf und ab. Er ist offenbar sehr dankbar.&gt;", rewards = "Geodenbrechende SchulterschützerArmschienen des energetischen ElementarsAuf Euch wartet eine dieser Belohnungen:\n\nHalskette des Kristallknabberers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26441] = {title = "So groß, so rund…", objective = "Sprecht mit Kor, um herauszufinden, was Kieselchen gerne isst.<Kieselchen schaut sich um und scheint über etwas ganz aufgeregt zu sein. Nach ein paar Sekunden der Verwirrung bleibt er stehen und starrt Euch mit großen leuchtenden Edelsteinaugen an.>\n\nHug-nrig… Hungrig…\n\n<So sehr Ihr es auch versucht, gegen diesen Blick seid Ihr einfach machtlos. Vielleicht weiß Kor ja, was Mini-Elementare gerne essen.>", description = "<Kieselchen schaut sich um und scheint über etwas ganz aufgeregt zu sein. Nach ein paar Sekunden der Verwirrung bleibt er stehen und starrt Euch mit großen leuchtenden Edelsteinaugen an.>\n\nHug-nrig… Hungrig…\n\n<So sehr Ihr es auch versucht, gegen diesen Blick seid Ihr einfach machtlos. Vielleicht weiß Kor ja, was Mini-Elementare gerne essen.>", progress = nil, completion = "Habt Ihr einen neuen Freund gewonnen?\n\nSeid Ihr sicher, dass Ihr ihn füttern wollt? Er könnte sich an Euch gewöhnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26442] = {title = "Felshummer", objective = "Sammelt 6 Felshummer aus den Käfigen unter den Docks im Hafen von Sturmwind auf. Achtet auf Haie!", description = "Wenn ich meine Henkersmahlzeit selbst aussuchen könnte, dann würde ich mich auf jeden Fall für frische Hummerschwänze entscheiden. Irgendetwas an dem leckeren Krustentier ist unwiderstehlich! Vor Kurzem haben wir begonnen, Hummer hier in Sturmwind zu fangen. Würde es Euch etwas ausmachen, hinauszugehen und die Fallen für mich zu überprüfen?\n\nEins noch... Passt auf die Haie auf. Die können ziemlich grausam sein.", progress = "Anscheinend seid Ihr den Haien erfolgreich ausgewichen. Waren Hummer in den Fallen?", completion = "Die Fallen funktionieren anscheinend! Danke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26443] = {title = "Teuflische Pläne", objective = "Liefert die teuflischen Pläne bei Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans in Eschental ab.", description = "Der Dämon hat dieses Pergament fallengelassen, das erstaunlicherweise in Gemeinsprache verfasst ist! Die darin erwähnten Namen, Diathorus und Gorgannon, gehören zwei berüchtigten Schreckenslords, die in dieser Gegend die Dämonen kontrollieren.\n\nDie Pläne beschreiben genau die Vorbereitungen auf einen Angriff der Dämonen auf Waldeslied im Norden. Das ist der Ort, an dem eine neue Siedlung der Draenei erbaut wird. \n\nMöglicherweise interessiert sich Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans hierfür?", progress = "Was habt Ihr da, mein Herr?", completion = "Bei den sieben Kristallen von Ata'mal, das darf nicht sein! Sie haben vor, Waldeslied anzugreifen?!\n\nNicht, solange ich Dienst habe!\n\n&lt;Verteidiger Vedaar zerknüllt die von Dämonen gekritzelten Pläne in seiner Faust.&gt;\n\nNein. Das werden wir nicht zulassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26444] = {title = "Zerstört die Legion", objective = "Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.", description = "Ich werde ihre Existenz in dieser Welt nicht dulden! Die Brennende Legion hat unser Volk so gut wie zerstört, und wir haben uns zurückgezogen, um in einer neuen Welt eine neue Heimat zu erschaffen. Dann kehrten sie zurück, und wir haben uns erneut zurückgezogen, wieder und wieder.\n\nNicht länger!\n\nIm Süden und im Westen befinden sich noch Überreste der Legion. Die Regionen heißen Dämonenhügel, Dämonensturz und Dämonenstieg. Das ist von der Streitmacht, die einst in diese Welt einfiel, noch übrig.\n\nGeht und vernichtet so viele von ihnen, wie möglich, bevor es zu spät ist!", progress = nil, completion = "Ihr habt meinen Respekt und meinen Dank, &lt;Klasse&gt;. Vielleicht können wir jetzt hier eine neue Heimat schaffen, ohne uns um die Brennende Legion Sorgen machen zu müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26445] = {title = "Nie wieder!", objective = "Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", description = "<Name>, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie sind Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals für Grom Höllschrei.\n\nBringt mir ihre Waffen.", progress = "Unsere Nachtelfenspione berichten, dass die Vorbereitungen für den Angriff fast abgeschlossen sind. Diese Schreckenslords müssen schnell sterben, <Name>!", completion = "Die Brennende Legion wird das Eschental nie wieder bedrohen! Ihr habt uns vor einem Kampf gerettet, den wir wahrscheinlich verloren hätten, &lt;Klasse&gt;.\n\nIch danke Euch, &lt;Name&gt;, und die tiefste Dankbarkeit der Hand von Argus. Es ehrt mich, Euch auf unserer Seite zu wissen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand von ArgasSiegel von ArgasSignet von Argas\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26446] = {title = "Die Rückeroberung des Dämonenhügels", objective = "Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.", description = "Kleines Wesen. Im Südwesten gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.\n\nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.", progress = nil, completion = "Gut. Auch wenn es vielleicht lange Zeit dauern mag, bis aus den Setzlingen Urtume werden, werden sie uns dann im Kampf gegen die Feinde des Eschentals helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26447] = {title = "Teuflische Pläne", objective = "Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten.\n\nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.", progress = "Was habt Ihr da, Bruder?", completion = "Schreckenslords! Sie planen uns hier am Splitterholzposten anzugreifen?!\n\nNicht solange ich noch am Leben bin!\n\n&lt;Valusha zerknüllt die Pläne mit dem Dämonengekritzel in ihrer Faust.&gt;\n\nNein. Wir werden das nicht zulassen. Sie sind ein Schandfleck in unserer Welt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26448] = {title = "Zerstört die Legion", objective = "Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.", description = "Die Überreste der Brennenden Legion sind uns schon zu lang ein Dorn im Auge!\n\nEs ist an der Zeit, sie dafür bezahlen zu lassen!\n\nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt, und erlangt Ruhm für Euch selbst und für die Horde!", progress = nil, completion = "So ist es schon besser! Nichts ist so gut, wie unsere Welt von einem Dämonen zu befreien. Und sie sind würdige Gegner, nicht so wie die schwachen Völker der Allianz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26449] = {title = "Nie wieder!", objective = "Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", description = "<Name>, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz.\n\nKehrt mit ihren Waffen als Beweis Eurer Taten zurück.", progress = "Diese Schreckenslords müssen bald sterben, <Name>!", completion = "Nie wieder wird die Brennende Legion die Orcs oder ein anderes Volk der Horde versklaven! Ihr habt tapfer gekämpft, &lt;Klasse&gt;!\n\nDas wahre Herz der Horde schlägt in Euch! Ihr bringt uns sehr viel Ehre!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand von ArgasSiegel von ArgasSignet von Argas\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26450] = {title = "Wenn sie sie einfach herumliegen lassen ...", objective = "Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.", description = "Mir kam gerade ein Gedanke, <Name>. Diese Naga haben mehr als nur Schilfrohr dort unten. Sie haben kleine Statuen auf ihren Schreinen im Sand unter den Bäumen herumliegen. Sie scheinen sie nicht zu benutzen.\n\nIch könnte diese Statuen gebrauchen. Ich könnte... sie überall im Lager aufstellen, damit es sich hier etwas heimeliger anfühlt. Alles ist besser als eine blutige Dinosaurierleichenpumpe. Ich könnte sie als Andenken verkaufen.\n\nIch könnte sie an die Naga zurückverkaufen!\n\nWarum holt Ihr nicht ein paar, während ich mir etwas ausdenke.", progress = "Lasst mal sehen!", completion = "Gute Arbeit, &lt;Name&gt;. Jetzt muss ich mich nur noch entscheiden, was ich damit mache...", rewards = "Naseweise PantalonsIkonische WesteWandernde HändeKadaverpumpergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26451] = {title = "Gurubashiherausforderung: Jeder gegen jeden in der Arena", objective = "Stellt die Herausforderungsflagge der Gurubashi im Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.", description = "Die Arena ist ein Kampfort wie kein anderer. Darin habt Ihr keine Freunde. Bündnisse, die eingegangen werden, sind kurzlebig und Eure Verbündeten können sich von einem Augenblick zum anderen gegen Euch wenden. Horde gegen Allianz, Allianz gegen Allianz, Horde gegen Horde - alles ist möglich.\n\nNehmt diese Schlachtstandarte, <Volk>, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.\n\nSeid jederzeit wachsam, <Volk>. In der Arena der Gurubashi ist alles möglich.", progress = "Bevor Ihr mich erneut ansprecht, sollte ein wenig mehr Blut auf Eurer Rüstung zu sehen sein.", completion = "Gut gemacht, &lt;Volk&gt;! Habt Ihr es gespürt? Den Rausch des Nahkampfs? Das wahre Risiko des Kampfes, jeder gegen jeden?\n\nDa heute Euer erster Tag hier ist, dürft Ihr noch einen Wettbewerb für eine weitere Belohnung austragen. Wenn Ihr in Zukunft zurückkehrt, dürft Ihr einmal am Tag antreten. Eure Belohnungen werden natürlich immer besser, je stärker Ihr werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26452] = {title = "Gurubashiherausforderung", objective = "Stellt die Herausforderungsflagge der Gurubashi in dem Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.", description = "Ihr seid zurückgekehrt, <Volk>. Das bedeutet, dass Ihr den Ruf der Arena erneut verspürt habt. Also gut.\n\nNehmt diese Schlachtstandarte, <Volk>, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.\n\nSeid jederzeit wachsam, <Volk>. In der Arena der Gurubashi ist alles möglich.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;! Ich freue mich darauf, Euch bald wieder kämpfen zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26453] = {title = "Eine helfende Hand", objective = "Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.\n\nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.", description = "Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.\n\nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, <Name>, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er hat mich gebeten, <jeden Mann, der/jede Frau> die; Interesse hat, zu ihm zu schicken.\n\nSprecht mich erneut an und ich werde dafür sorgen, dass Ihr schnell zu ihrer Stellung gebracht werdet.", progress = nil, completion = "Es ist schön, einen Neuankömmling hier in Waldeslied begrüßen zu dürfen.\n\nVerteidigerin Palanaar sendet so viel Hilfe, wie sie aufbringen kann, und jede helfende Hand ist willkommen.\n\nSchaut Euch um, &lt;Klasse&gt;. Es ist vielleicht noch nicht viel, aber mit der Zeit und der Hilfe unserer Nachtelfenverbündeten werden wir eine Siedlung errichten, die es wert ist, Zuhause genannt zu werden. Es gibt hier viel zu tun, und für jede Hilfe, die Ihr uns leisten könnt, sind wir sehr dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26454] = {title = "Eine schändliche Verschwendung", objective = "Sammelt 5 Stück verdorbenes Satyrnaarholz.", description = "Willkommen in Waldeslied, <Klasse>. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.\n\nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.", progress = "<Das Urtum knarrt, als es sich zu Euch umdreht>\n\nArchitekt Nemos sagte, Ihr brächtet Holz, das Ihr aus dem verdorbenen Satyrnaar errettet habt.", completion = "Holz, das von widerwärtiger Dämonenmagie verzerrt wurde, ist für die Draenei in Waldeslied nutzlos. Nichts Vernünftiges lässt sich daraus erbauen, doch ich werde es reinigen und Architekt Nemos zurückgeben, auf dass er und seine Leute es benutzen können.\n\nSo wird die Tragödie doch ein gutes Ende haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26455] = {title = "Elunes Kelch", objective = "Bringt Elunes Kelch in Euren Besitz.", description = "Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.\n\nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, <Name>.", progress = "Könnt Ihr ihn fühlen, <Name>, den Hauch von Verderbnis im Wind? Wenn wir nichts tun, wird er noch stärker werden. Deshalb suche ich Elunes Kelch. Konntet Ihr ihn finden?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Es schlummert eine deutliche Macht in ihm, die nicht einmal die Verderbnis der Satyrn trüben kann.\n\nSeht Ihr, wie er immer noch glänzt, nach all den Jahren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26456] = {title = "Bericht von der Nordfront", objective = "Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.", description = "Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, <Name>. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.\n\nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?", progress = "Was habt Ihr da, <Klasse>?", completion = "Vielen Dank für diesen Bericht, &lt;Name&gt;. Nach dem, was Schildwache Melyria schreibt, scheint es, als wären unsere schlimmsten Befürchtungen wahr geworden. Mit jedem Fortschritt, den wir machen, scheint die Horde umso entschlossener, so viel Schaden wie möglich anzurichten.\n\nWir können es uns nicht leisten, klein beizugeben. Das Schicksal des Landes unserer Vorfahren steht auf dem Spiel. Wenn wir mehr von Eurer Sorte an der Front hätten, könnten wir sicher triumphieren.\n\nWerdet Ihr Euch unserem Kampf anschließen? Eine neue Front hat sich gerade im Süden in der Kriegshymnenschlucht gebildet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26457] = {title = "Agenten der Zerstörung", objective = "Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.", description = "Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!\n\nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, <Name>, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!\n\nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!", progress = nil, completion = "Endlich haben wir ein Zeichen gesetzt, das die Orcs nicht ignorieren können. Jeder Vorarbeiter oder Großknecht, der einen Fuß in das Lager setzt, um Gorthak zu ersetzen, wird meinen Zorn zu spüren bekommen!\n\nWir müssen unseren Vorteil ausnutzen, &lt;Name&gt;, und nicht ruhen, bevor das Holzfällerlager des Kriegshymnenklans nichts mehr als eine weit entfernte Erinnerung ist und junge Bäume ihre Wurzeln in diesen Boden schlagen.\n\nWas sagtet Ihr noch gerade über Sprengstoff...?", rewards = "SternwisperschiftungWaldschutzwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26462] = {title = "Die bösen Bruchhauer", objective = "Tötet 10 Pirscher der Bruchhauer oder Verhexer der Bruchhauer.", description = "Die Trolle der Bruchhauer meinen etwas Besonderes zu sein, weil sie Teil der Horde sind. Da kann ich nur lachen!\n\nWisst Ihr, das wirklich Witzige ist, dass es egal ist, ob sie der Horde angehören oder nicht, ob sie ein Trollimperium besitzen oder die Brennende Legion selbst sind. Wir haben Trolle in diesen Ländern seit Urzeiten bekämpft.\n\nUm genau zu sein werde ich Euch dabei sogar helfen lassen, <Junge/Mädchen>! Nehmt Euch eine Waffe und begebt Euch zum Schlachtfeld, um unsere Jungs östlich von hier zu unterstützen.", progress = nil, completion = "Nicht schlecht für einen &lt;Volk&gt; aus der Stadt. Nette Vorführung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26463] = {title = "Findet Teronis", objective = "Sucht am Falathimsee im Eschental nach Teronis.", description = "Eine Freundin von mir aus Astranaar, Raene Wolfsläufer, hat mich gebeten, einen Kundschafter zum Falathimsee im Westen zu schicken. Teronis ist vor Tagen aufgebrochen, kurz bevor die Horde angegriffen hat.\n\nEr war auf der Suche nach einem Gegenstand, von dem er dachte, dass er die Furbolgangriffe auf unser Volk mildern könnte: eine Rute, die von einem mittlerweile toten, bösen Zauberer hergestellt worden ist.\n\nBevor er aufbrach, erwähnte er einen Edelstein für die Rute.\n\nLeider wissen wir, dass der See von einer bösen Macht heimgesucht wird. Bitte, <Name>, macht meinen Freund ausfindig.", progress = nil, completion = "Teronis' Körper liegt zerschmettert auf einem kleinen Hügel neben dem Bewahrer.\n\nTiefe Schnitte ziehen sich kreuz und quer über seine Leiche.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26464] = {title = "Der verlorene Stein", objective = "Findet den leuchtenden Edelstein.", description = "Während Ihr Teronis' Habseligkeiten durchstöbert, stoßt Ihr auf ein durchnässtes Tagebuch.\n\nIhr blättert schnell durch die letzten noch lesbaren Seiten und lest, dass Teronis erwähnt, wie er den Edelstein gefunden hat, ihn dann aber in der Umgebung des Falathimsees verloren hat.\n\nJetzt müsst Ihr nur noch eines tun: den Edelstein finden. Vielleicht haben ihn die Tentakel...", progress = "Ah, willkommen zurück, <Name>.", completion = "Wie schrecklich, &lt;Name&gt;. Teronis ist tot?!\n\nIch werde ihn später betrauern, aber jetzt müssen wir uns zuerst auf unsere Aufgaben konzentrieren. Ich schicke ein paar der Schildwachen aus, um Teronis' Leiche herzubringen und dem Hüter beizustehen.\n\nIhr habt den Edelstein, den Teronis suchte? Er muss sofort nach Astranaar gebracht werden.", rewards = "Falathimgewaschene RobenRundblattmantelungMaestras HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26465] = {title = "Die antiken Statuetten", objective = "Besorgt 10 antike Statuetten.", description = "Ich möchte Euch mit einer Aufgabe betrauen, <Klasse>.\n\nIch war auf meinem Boot und dümpelte über die versunkenen Ruinen von Zoram, als Naga mich angriffen. Sie sprangen aus dem Wasser und griffen mit ihren Klauen nach mir! Ich flüchtete, und der Rest ist - wie man so schön sagt - Geschichte.\n\nIch bin eine Art Archäologe und ich versuche, die Artefakte der verlorenen Stadt wiederzufinden.\n\nWürdet Ihr Euch hinaus zum Zoramstrand im Südwesten begeben und alle antiken Statuetten, die Ihr finden könnt, bergen? Sie sind der Grund, dass ich den Gefahren des Zoramstrandes getrotzt habe.", progress = "Habt Ihr viele Statuetten gefunden, <Name>?", completion = "Das sind ja doch einige, die Ihr gefunden habt! Danke, &lt;Name&gt;!\n\nDie alte Stadt Zoram birgt viele Geheimnisse, und diese Statuetten könnten der Schlüssel zu einigen davon sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26466] = {title = "Ruuzel", objective = "Nehmt den Ring von Zoram an Euch.", description = "Ich fürchte, die Geheimnisse der antiken Statuetten werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihren antiken Schlössern findet.\n\nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der Großen Zerschlagung unterging.\n\nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor Kurzem gefunden.\n\nRuuzel, ihre Anführerin, haust auf einer Insel am nördlichen Ende des Zoramstrands. Bitte, <Name>, beschafft mir den Ring!", progress = "Es heißt, dass der Ring von Zoram der Schlüssel zu allen Schlössern der Stadt sei. Habt Ihr ihn, <Name>?", completion = "Ihr habt den Ring gefunden! Danke, &lt;Name&gt;.\n\nBitte nehmt das hier als Lohn und wisset, dass ich Eure heutige Tat nie vergessen werde.", rewards = "Ihr bekommt:\n\nRoben der Antike"}
MultiLanguageQuestData['de'][26467] = {title = "Elende Satyrn! Die Dryaden sind in Gefahr!", objective = "Sucht in Xavian im Eschental nach Anilia.", description = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein würden, aber das war vor zwei vollen Tagen!\n\n<Name>, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordwesten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", progress = nil, completion = "Der klaffenden Wunde in ihrer Seite nach zu urteilen, steht Anilia an der Schwelle des Todes.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26468] = {title = "Der Zweig des Cenarius", objective = "Erhaltet den Zweig des Cenarius.", description = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", progress = "Habt Ihr sie gefunden? Was hat Anilia gesagt? Wo ist sie?", completion = "Anilia ist tot? Nein... das kann nicht sein! Noch vor kurzem sind wir zusammen durch die Wälder getollt und haben gespielt.\n\nDiese Zeiten sind jetzt wohl vorbei...", rewards = "FeenmantelHellschuppengurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26469] = {title = "Satyrn schlachten!", objective = "Erhaltet 16 Satyrhörner.", description = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.\n\nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", progress = "Bitte, helft mir Anilias Tod zu rächen.", completion = "Danke, &lt;Volk&gt;, Ihr seid sehr freundlich. Der Geist meiner Schwester ist dankbar für Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26470] = {title = "Die Rückeroberung des Mystralsees", objective = "Tötet 12 beschmutzte Wasserelementare und Tideress.", description = "Wir hätten die Silberwindzuflucht ohne Weiteres gegen den Ansturm der Horde halten können, wenn sie uns nicht die Kontrolle über unsere Wasserelementarverteidiger im Mystralsee entrissen hätten.\n\nEiner ihrer Schamanen hat Tideress heraufbeschworen, einen alten, wütenden Wassergeist des Waldes, der unsere Elementare besudelt und gegen uns aufgebracht hat. Da sowohl der See als auch die Horde über uns hereingebrochen sind, hatten wir keine andere Wahl, als uns hierher zur Spitze zurückzuziehen.\n\nBegebt Euch nach Osten. Erobert den See zurück, sodass eine Chance besteht, dass wir eines Tages die Zuflucht wieder einnehmen können.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Nun da die Ränge der beschmutzten Wasserelementare dezimiert sind und Tideress wieder in den See verbannt wurde, sollten wir einen Gegenangriff auf die Silberwindzuflucht starten können.\n\n\n\nSobald wir mit der Verteidigung der Spitze fertig sind...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26472] = {title = "Irrsinnige Druiden", objective = "Tötet die irrsinnigen Druiden: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", description = "Die Druiden sind tot. Ihre Anführer haben sie getötet - sie wurden von der Horde, die das Herz des Waldes verderben, in den Wahnsinn getrieben. Ich kann die Verderbnis sogar von hier spüren und wage es nicht, weiterzugehen.\n\nIch stehe zu sehr im Einklang mit Eschental und dem Herz des Waldes - aber Ihr... Ihr könntet in den Grabhügel hinabsteigen und das tun, was getan werden muss. Ich habe dort eine Spur für Euch gelegt.\n\nObwohl es mir das Herz zerreißt, muss ich Euch darum bitten, die einstmals großartigen Anführer der Druiden zur ewigen Ruhe zu betten: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", progress = nil, completion = "Ruht in Frieden, meine Freunde.\n\n&lt;Ihr könnt den Schmerz in den Katzenaugen des Druiden sehen.&gt;\n\nIch fühlte, dass die Pein der Grabhügel von Dor'Danil nachließ und wusste, dass Ihr Euren Auftrag erfüllt hattet.\n\nWas Ihr tun musstet, war grausam, &lt;Name&gt;, denn die Geister, die Ihr vernichten solltet, waren doch nur unschuldige Opfer der Bösartigkeit der Horde. Hoffen wir, dass auch die anderen wahnsinnigen Geister endlich Ruhe finden, da sie jetzt vernichtet sind.", rewards = "Ihr bekommt:\n\nEmils Marke"}
MultiLanguageQuestData['de'][26473] = {title = "Bathranshaar", objective = "Sammelt 8 Büschel Bathranshaar.", description = "In den alten Ruinen von Bathrans Schlupfwinkel, der sich auf der anderen Seite der Straße im Osten befindet, wächst eine Pflanze. Diese Pflanze heißt Bathranshaar und man sagt ihr nach, dass sie Leiden des Geistes heilen kann.\n\nJetzt erntet die Horde diese Pflanze für ihre eigenen, finsteren Pläne.\n\nIn Astranaar befindet sich ein krankes Kind. Wir glauben, dass seine Krankheit nicht nur körperlicher Natur ist. Ich habe meinem Herrn versprochen, dass ich helfen werde, ein Heilmittel zu suchen, aber ich bin kein Kämpfer. \n\nWürdet Ihr zu Bathrans Schlupfwinkel gehen und die Pflanzen sammeln?", progress = "Habt Ihr Bathranshaar gesammelt, <Name>? Die Gesundheit des Kindes schwindet mit jeder Stunde...", completion = "Ah, Ihr habt das Haar! Das ist ein guter erster Schritt. Wir werden noch weitere Zutaten benötigen, aber das Haar des gefallenen Urtums könnte die wichtigste sein.\n\nIch hoffe nur, dass die Verlassenen aus der Pflanze keine Waffe entwickeln. Wir haben einfach nicht genug Leute, um sie jetzt zu vertreiben, insbesondere, da Maestras Posten angegriffen wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26474] = {title = "Orendils Heilmittel", objective = "Bringt Orendils Heilung zu Pelturas Weißmond in Astranaar im Eschental.", description = "<Name>, nun da es von Elunes gesegnetem Licht durchflutet wurde, glaube ich, dass das Gebräu dem kranken Kind helfen wird. Bitte bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Weißmond.\n\nUm nach Astranaar zu gelangen, folgt ihr der Straße nach Süden und dann nach Osten. Wenn Ihr aber schneller dorthin gelangen wollt, sprecht mit Schildwache Avana.", progress = "Ich muss mich entschuldigen, aber ich habe jetzt keine Zeit, um zu plaudern. Meine Tochter Relara ist todkrank!", completion = "Das ist von Orendil?\n\nSeine Fertigkeiten in Kräuter- und Heilkunde sind enorm. Dieses Heilmittel gibt mir Hoffnung, dabei hatte ich schon fast aufgegeben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26475] = {title = "Elunes Träne", objective = "Erhaltet eine Träne Elunes.", description = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.\n\nElunes Träne ist eine Gesteinsart, die nur an einem Ort vorkommt: den Überresten des Irissees, der durch den Ausbruch des Donnergipfels nordöstlich von Astranaar zerstört worden ist. Orendil sagte, der Stein könne Verderbnis wegwaschen.\n\nBitte, <Name>, bringt mir eine Träne Elunes und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", progress = "Habt Ihr die Überreste des Irissees gefunden, <Name>? Habt Ihr die Träne?", completion = "Oh, Ihr habt sie gefunden! Merkwürdig...der Stein sieht irgendwie angelaufen aus. Ich werde die Träne in einen Eintopf geben und beten, dass meine Tochter davon geheilt wird.\n\nDanke! Danke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26476] = {title = "Dryadenlieferung", objective = "Liefert den leuchtenden Edelstein bei Shael'dryn beim Rajenbaumturm im Eschental ab.", description = "Ah, da seid Ihr ja, <Name>. Ich habe mich in die Anmerkungen vertieft, die Teronis gemacht hat, und es sieht so aus, als ist Euer nächster Schritt, die Teile von Dartols Rute zu finden.\n\nIch würde zunächst nach Osten reisen, zum Rajenbaumturm.\n\nDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.\n\nBehaltet den Edelstein bei Euch - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", progress = "Hallo. Wie geht es Euch?", completion = "Oh, Raene hat Euch geschickt? Dann muss es wohl wirklich dringlich sein.\n\nWie kann ich Euch helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26477] = {title = "Sucht den Schaft", objective = "Sucht den hölzernen Schlüssel und benutzt ihn, um den Eisenschaft von Dartols Rute zu finden.", description = "Ich wünschte, Ihr hättet bessere Nachrichten.\n\nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.\n\nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in der es sich befindet.\n\nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald am Heulenden Tal. Wenn Ihr es gefunden habt, sucht nach einer kleinen Lichtung hinter dem Tunnel in diesem Tal. Die Truhe ist dort irgendwo versteckt.", progress = "Es bestürzt mich sehr, dass die Treants verderbt wurden. Ich wünschte, ich könnte mehr tun, um ihnen zu helfen.", completion = "Wie ich mich freue, dass Ihr zurück seid, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26478] = {title = "Sich tot stellen", objective = "Erhaltet das letzte Teil von Dartols Rute, den Eisenschwertknauf.", description = "Das letzte Stück der Rute ist im Besitz der Druiden der Klaue. Ich habe ihren Anführer, Oso Dornennarbe, gebeten, es mir auszuhändigen, aber er und seine Wächter hätten mich beinahe umgebracht! Offenbar hat die Verderbnis des Herzens des Waldes seitens der Horde auch die Druiden betroffen.\n\nAber ich habe eine Idee, wie Ihr in Osos Höhle gelangen und den Knauf an Euch nehmen könnt.\n\nSchon als kleiner Faun war ich immer ziemlich gut darin, mich tot zu stellen. Das funktioniert wunderbar gegen Bären! Ich kann es Euch beibringen! Geht nach Osten zum Schattenwinkel und wenn sie versuchen, Euch anzugreifen, probiert einfach meine Taktik aus.", progress = "Habt Ihr das letzte Teil der Rute gefunden, <Name>? Hat meine Taktik funktioniert?", completion = "Ihr habt das letzte Teil gefunden? Wie wunderbar für Euch... und für Raene.\n\nDann sollten wir beginnen, sie zu reparieren, meint Ihr nicht?", rewards = "Shael'dryns ArmschienenOpossumpfotenstiefelHeuchlerische ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26479] = {title = "Rückkehr zu Raene", objective = "Liefert Dartols Rute bei Raene Wolfsläufer in Astranaar im Eschental ab.", description = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertiggestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.\n\nSeid vorsichtig damit... ich spüre eine große Macht darin, zum Guten wie auch zum Bösen. Ich hoffe nur, dass Raene und Ihr wisst, was Ihr tut.\n\nViel Glück, <Name>.", progress = "Ja, <Name>? Wie liefen Eure Bemühungen?", completion = "Ihr habt die Rute wieder zusammengesetzt, die Teronis finden wollte? Wie schön, das zu hören.\n\nShael'dryns Hilfe war unentbehrlich. Teronis wäre stolz gewesen, wenn er gesehen hätte, dass seine Aufgabe selbst nach seinem tragischen Ende noch fortgeführt wurde.\n\n&lt;Raene betrachtet die wiederhergestellte Rute mit Anerkennung und in ihren Augen spiegeln sich die vielen Gedanken, die in ihr vorgehen.&gt;\n\nDie Zeit ist gekommen, ihre Macht gegen die Feinde des Eschentals einzusetzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26480] = {title = "Dartols Rute", objective = "Benutzt Dartols Rute, um mit Krolg bei Krolgs Hütte im Eschental kommunizieren zu können.\n\nBereitgestellter Gegenstand: \n", description = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.\n\nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen, vermutlich die eines Furbolgs.\n\nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der noch unverderbt war.\n\nIch würde meine Suche bei dem Furbolg beginnen, der als Krolg bekannt ist. Sucht nach seiner Hütte südöstlich vom Mystralsee.", progress = nil, completion = "Ja, ja... du erscheinst als einer meiner Art, aber mich kümmert nicht, was du in Wirklichkeit bist, solange du den Furbolgs helfen kannst.\n\nDie Nachtelfen und jetzt auch die Orcs haben meinem Volk viele Gräuel angetan.\n\nVerderbnis fließt durch unsere Adern, Verderbnis, die von den überheblichen Nachtelfen und den kriegerischen Orcs über uns gebracht wurde. Sie sind diejenigen, die das unserem Volk angetan haben... Sie sind diejenigen, denen ich die Schuld dafür gebe, dass mein Stamm mich verstoßen hat.\n\nBei Nacht kann ich noch immer die Lagerfeuer in der Dunkelheit brennen sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26481] = {title = "Eine neue Verzierung", objective = "Erhaltet Ran Blutreißers Schädel und Dartols Rute.", description = "Ich bin mir sicher, dass der seit langem tote Zauberer Dartol diese Rute dazu benutzen wollte, uns zu unterwerfen und zu zerstören, genauso wie es die Nachtelfen und Orcs versucht haben. Jetzt aber werden wir dieses Ding einem unvorhergesehenen Zweck zuführen.\n\nRan Blutreißer ist König über alle Furbolgs im Eschental. Sein Stamm, die Blutreißer, sind am mächtigsten und grenzen sich in einem Lager im Osten ab.\n\nTötet sie alle und bringt mir seinen Schädel. Wollen wir doch einmal sehen, ob wir nicht einen guten Verwendungszweck dafür finden können.", progress = "Habt Ihr Ran schon erschlagen, Freund? Wir müssen seinen Schädel haben, wenn mein Volk frei sein soll.", completion = "Das habt Ihr gut gemacht, mein Freund.\n\nSchnell jetzt, gebt mir Rans Schädel. Solange noch seine Essenz ihn besudelt, können wir ihn an Dartols Rute befestigen und Euch die Macht verleihen, meine Brüder zu beeinflussen und sie vom Bösen zu befreien!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26482] = {title = "Die wahre Macht der Rute", objective = "Benutzt Dartols Rute und sprecht mit Ota Wen. Überzeugt ihn, sich gegen die Unterdrücker der Horde aufzulehnen. Bringt dann Dartols Rute zu Raene Wolfsläufer.", description = "Nehmt jetzt die Rute und sprecht, während Ihr unter ihrem Effekt steht, mit meinem Bruder Ota Wen.\n\nOta ist bei den anderen Furbolgs, die von den Orcs gefangen genommen und in den riesigen Käfig nördlich der Silberwindzuflucht gesperrt worden sind. Die Rute wird es Euch erlauben, Ota und die anderen Furbolgs dazu zu bringen, sich gegen die Horde aufzulehnen.\n\nDanach dürft Ihr Eures Weges ziehen. Wisst nur, dass Ihr mit Euren Taten einen neuen Freund gefunden habt.", progress = "Ihr seid zurück, <Name>. Was ist das dort an der Spitze der Rute? Ein Schädel?", completion = "Ihr habt also den Schädel des Furbolgkönigs benutzt, um die Macht der Rute zu verändern? Ihr habt dann diese Macht benutzt, um die gefangenen Furbolgs zur Revolte zu bewegen und die Horde in der Silberwindzuflucht anzugreifen?\n\nIch bin mit Euren Fähigkeiten mehr als zufrieden und beeindruckt, &lt;Name&gt;. Die Schildwachen können Euch nicht genug danken. Es sollte nun einfach sein, die Orcs hinwegzufegen und die Zuflucht zurückzuerobern!\n\nTeronis wäre stolz. Ihr habt meinen größten Respekt.", rewards = "SilberwindarmschienenWolfsläuferstiefelTeronis' VermächtnisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26483] = {title = "Gan'dranda", objective = "Tötet Gan'dranda.", description = "So viel Spaß es ja auch macht, die Trolle auf die Hörner zu nehmen, wir haben hier unten noch anders zu tun. Es wäre doch schöner, diesen Kampf endlich zu beenden, nicht wahr?\n\nIhr Kommandant, Gan'dranda, sitzt zwischen den eingestürzten Mauern im Südosten des Schlachtfelds. Unsere Jungs sind zum größten Teil unabkömmlich, also möchte ich, dass Ihr Euch dort hinschleicht und Gan'dranda beseitigt. Wenn sie dort sehen, wie <ein/eine:r> <Volk> über der Leiche ihres größten Helden steht, sollte ihnen das den Schneid abkaufen.", progress = nil, completion = "Na, das höre ich doch gerne! So ist's recht.", rewards = "Eisenblicks ArmbrustTheresas ArmschienenSturmfederstiefelKopftreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26484] = {title = "Hilfe für Steinruh", objective = "Sprecht mit Spalt Steinbrecher in Steinruh in Tiefenheim.", description = "Die Irdenen und die Steintroggs haben vor mehr als fünfzehntausend Jahren einen Weg durch Uldum nach Tiefenheim gefunden. Seitdem befinden sie sich im Krieg.\n\nWenn wir das mittlere Fragment der Weltensäule wiedererlangen wollen, muss der Steinvater gerettet werden.\n\nBitte geht nach Steinruh und tut alles, was in Eurer Macht steht, um den Irdenen im Kampf gegen die Steintroggs zu helfen.\n\nIhr seid unsere größte Hoffnung, <Name>.", progress = nil, completion = "Der Sohn des Steinvaters, Flint, hat Euch geschickt? Keine Zeit zu reden.\n\nWir müssen verhindern, dass sich eine zweite Front in dieser Schlacht aufbaut!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26485] = {title = "Schnappkiefer, Bursche!", objective = "Beschafft 8 Schnappkiefermuskelmägen von Salzwasserschnappkiefern", description = "Ich habe mir vorgenommen, für diese lästigen Trolle etwas ganz Besonderes zusammenzubrauen. Ja, ich sagte für sie... ein Gebräu, das sie niemals vergessen werden! Nach dem Genuss dieses Gebräus werden sie ihre Hauer aus den Abhängen sammeln können.\n\nEinige Zutaten weiche ich hier bereits ein, aber ich könnte Hilfe dabei gebrauchen, noch mehr zu beschaffen. Am Fuße der Aussichtsklippen im Osten in der Nähe des Ufers sind eine ganze Menge Schnappkiefer. Ich brauche frische, intakte Muskelmägen für mein Kawummbräu.", progress = "Habt Ihr die Mägen?", completion = "Ah, schön frisch. Ich werde damit anfangen, während Ihr mir noch ein paar Sachen besorgt...", rewards = "Ihr bekommt:\n\nNat Pagles Extremangler FC-5000"}
MultiLanguageQuestData['de'][26486] = {title = "99 Flaschen Wein am Strand", objective = "Sammelt 12 Flaschen mit Pupellyverbos' Portwein.", description = "Ich weiß ja, dass hier ein kleiner Kampf tobt, aber unten an diesen Aussichtsklippen sind überall Flaschen verteilt, die sehr verführerisch aussehen. Ich kann nicht zulassen, dass so ein gutes Tröpfchen der Horde in die Finger fällt!\n\nWenn Ihr zufällig dort vorbeikommt, dann sammelt die Flaschen für mich ein und bringt sie her. Ich werde Euch dafür bezahlen, als hättet Ihr sie selbst abgefüllt.", progress = "12 sollten reichen, oder?", completion = "Was für ein gutes Zeug! Wir können doch nicht zulassen, dass irgendwelche Trolle oder Goblins sich ein Schlückchen davon genehmigen, oder?\n\nVielleicht kann ich ein bisschen davon in meinem nächsten Gebräu verarbeiten…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26487] = {title = "Bündelweise Akiris", objective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", description = "Es ist nicht einfach, eine Kombination aus 5-Sterne-Exotikhotel und Verwertungsanlage für Dschungelmaterial zu führen! Zumindest wäre es nicht einfach, wenn ich nicht das Organisationstalent der persönlichen Assistentin eines Handelsprinzen hätte!\n\nDer erste Trick ist, mehrere Dinge auf einmal zu erledigen. Zum Beispiel: Die Forscher der Naga im Süden tragen wertvolles Seeschilf bei sich, Akiris. Wir können dieses Schilf an unsere Kunden in Übersee verkaufen und gleichzeitig die Matratzen unserer Kunden damit polstern! Wenn ich so darüber nachdenke, könnten wir es sicher auch für andere Zwecke verwenden.", progress = "Mal sehen… Wir brauchen ein paar Gewehre für unsere Naturwanderungen, Ruderboote für unseren Tagesausflug zum Bohrturm und…\n\nOh, Ihr seid schon zurück?", completion = "He, he! Nicht übel, gar nicht übel! Ihr könntet eine Zukunft im Beschaffungswesen haben. Oder im Hotelmanagement.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26488] = {title = "Ein großer Schluck", objective = "Fischt einen königlichen Seeteufel aus dem Burggraben im Tal der Helden in Sturmwind. Wenn Ihr einen Seeteufel angelt, filetiert ihn und seht nach, ob er das Medaillon verschluckt hat.", description = "Arnold und ich haben uns immer am Burggraben im Tal der Helden ausgeruht. Eines Tages habe ich mein Medaillon am See verloren und habe es nie wiedergefunden. Es gibt Gerüchte, dass riesige königliche Seeteufel in dem Burggraben leben. Diese Fische fressen einfach alles! Ich weiß, es hat nicht besonders viel Aussicht auf Erfolg, aber glaubt Ihr, Ihr könntet ein paar Seeteufel fangen und nach meinem Medaillon schauen?\n\nBitte gebt mir umgehend Bescheid, wenn Ihr es findet. Es bedeutet mir sehr viel.", progress = "Habt Ihr mein Medaillon gefunden?", completion = "Ihr habt es gefunden! Ich kann kaum glauben, dass es all die Jahre dort unten war! Ihr habt keine Ahnung, wie viel mir das bedeutet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26489] = {title = "Ihr hier?!", objective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", description = "Ja, wie kann ich Euch…\n\n<Sassy fällt die Kinnlade herunter.>\n\n<Name>! Seid Ihr das wirklich?! Wie groß und stark Ihr geworden seid! Lasst mich mal Euren Bizeps fühlen.\n\nIch? Ich habe versucht, hier im Dschungel ein wenig Gold zu scheffeln. Wir sind hauptsächlich in der Materialbeschaffung tätig, aber auch im Tourismus.\n\nIch weiß, genial, oder?\n\nHe, hört mal. Da fällt mir gerade was ein. Die Forscher der Naga im Süden tragen wertvolles Akirisschilf bei sich, das wir verkaufen und gleichzeitig als Polsterung für unsere Gästematratzen verwenden können. Habt Ihr Lust, ein paar Naga zu töten? Es wäre ganz wie in alten Zeiten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26490] = {title = "Erstklassiger Schleim", objective = "Beschafft eine Terrorklumpenprobe vom Terrorklumpen.", description = "Nicht viele Zwerge wissen das, aber um meinem Gebräu noch einen richtigen Schub zu verleihen, füge ich noch ein wenig von dem Schlamm hier aus der Gegend hinzu. Ja, von den riesigen, grünen, zwergenfressenden Schlammhaufen.\n\nDieses Gebräu braucht allerdings einen RIESIGEN Extraschub, also brauchen wir einen großen Schlamm! Im Lauerfels befindet sich die Mutter aller Schlamme, sie ist wirklich riesig... Wir nennen sie den Terrorhaufen.\n\nWenn Ihr das Zeug dazu habt, geht dorthin und bringt mir einen Brocken von dem Terrorklumpen!", progress = "Habt Ihr es?", completion = "Schaut Euch das an! Das wird der Mixtur richtig Dampf verleihen!", rewards = "Zauberstab des WummsKawummbräuhutTerrorklumpenverschleimter GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26491] = {title = "Den Lauerfels aufräumen", objective = "Tötet 10 jadegrüne Schlamme.", description = "Vor Jahren gab es einmal eine Basis der Horde tief im Lauerfels. Sie ist seitdem verlassen, aber es handelt sich immer noch um ein wichtiges Gebiet, das es wert wäre, für unsere Verbündeten eingenommen zu werden.\n\nDas Problem ist, es ist voller zwergenfressender Schleime und Schlamme. Diese Dinger sind fast genauso eklig wie Trolle und bereiten uns dauernd Ärger.\n\nUnsere Jungs sind vollauf damit beschäftigt, gegen die Bruchhauer zu kämpfen, deshalb müsst Ihr nach Lauerfels gehen und dort für mich aufräumen.", progress = nil, completion = "Es ist schön, Euch wieder hier zu sehen... einschließlich aller Arme und Beine.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26492] = {title = "Lauerfelsvorräte", objective = "Sammelt 5 schlammbedeckte Vorratskisten ein.", description = "Ich hatte einen Cousin, der im Zweiten Krieg gekämpft hat! Er hat mir immer davon erzählt, dass sie einen Schlachtzug gegen Lauerfels geführt haben. Sie sind dort hineingestürmt und haben die Trolle wie Ratten aus ihrem Nest vertrieben. Sie haben sie den ganzen Weg bis nach Alterac gejagt!\n\nKurz darauf haben die Schleime Einzug gehalten, aber dort drin gibt es immer noch ganze Kisten voller Waren der Horde. Ich sage, wir lassen nicht zu, dass die Trolle sich das zurückholen!\n\nBringt mir einige Kisten vom Lauerfels im Nordwesten.", progress = "Habt Ihr die Kisten?", completion = "Es sieht so aus, als ob darin noch alles gut ist! Hm... Ist das Bananenbrot? Das ist sogar noch frisch!\n\nHier mein Junge, nehmt Euch Euren Anteil.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26493] = {title = "Jemand dort draußen will es haben", objective = "Beschafft 7 Einheiten von Sassys Geheimzutat von Donnerschwanz- und Eisenkieferbasilisken in der Kristalladermine.", description = "Also, da Ihr ohnehin schon von der Erledigung der ganzen anderen Sachen schwitzt, dachte ich, Ihr könntet noch eine Aufgabe für mich erledigen. Das macht Euch doch nichts aus, oder?\n\nDas neueste Wissenschafts- und Explosionsjournal ist gerade aus Bilgewasserhafen eingetroffen und darin ist dieser Artikel über dieses heiße, neue Reagenz. Die Preise für dieses Reagenz schießen in den Himmel und wir haben beste Voraussetzungen, daraus Kapital zu schlagen!\n\n<Sassy beugt sich zu Euch und flüstert Euch die Einzelheiten ins Ohr.>\n\nVerstanden? Gut. Ihr findet die Basilisken in einer Höhle, weit im Osten.", progress = "Ich hoffe, Ihr habt die Extraktionsmethode, die wir besprochen haben, angewendet.", completion = "Großartig! Die sehen... widerlich aus. Sie sind aber wahrscheinlich ziemlich wertvoll. Gehen wir und teilen sie auf. Ein paar für mich, ein paar für Jasper, ein paar für Chabal...", rewards = "Helm der GeheimnisseAuf Euch wartet eine dieser Belohnungen:\n\nBasiliskenschuppenhalskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26494] = {title = "Mischmeister Jasper", objective = "Bringt Sassys Proben zu Mischmeister Jasper in Hartzangs Versteck.", description = "Würde es Euch etwas ausmachen, ein bisschen von dem Zeug hier Jasper zu bringen? Er ist bei den luxuriösen Wohnungen. Ich bin sicher, er wird dafür Verwendung haben.\n\nDanke, <Name>!", progress = "Hey, ist das das Zeug? Aus der Zeitschrift?", completion = "Ich werde das erst einmal aufbewahren. Vielleicht können wir später herumexperimentieren.\n\n&lt;Jasper schaut zu Euch hinüber.&gt;\n\nJa, Ihr werdet reichen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26495] = {title = "Chabal", objective = "Bringt Sassys großzügige Gabe zu Chabal in Hartzangs Versteck.", description = "Chabal, der Troll drüben am botanischen Garten/biologischen Waffenlabor, ist ein ganz besonderer Gast. Er ist ein Repräsentant der Zandalari-Trolle und hat eine weite Reise hinter sich, um bei uns zu sein.\n\n<Sassy packt einige der Gegenstände, die Ihr gesammelt habt, in ein kleines Paket und übergibt es Euch.>\n\nHier, gebt ihm das. Sagt ihm, dass die Zandalari in Hartzangs Versteck immer willkommen sind. Und erwähnt, dass Empfehlungen der Schlüssel zur Aufrechterhaltung unserer Geschäftsbeziehungen sind!", progress = "Was soll das, <Klasse>?", completion = "&lt;Der Troll schaut in das Paket.&gt;\n\nIch danke Euch.\n\nIch habe darauf gewartet, dass Ihr mich ansprecht, &lt;Volk&gt;. Ich habe festgestellt, dass Ihr der vielversprechendste &lt;Volk&gt; in dieser merkwürdigen Stadt seid. Ich habe eine Aufgabe für Euch, falls Ihr sie annehmen möchtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26496] = {title = "Nieder mit den Blutfratzen", objective = "Findet Doran Stahlschwing bei Jintha'Alor im Hinterland.", description = "Die Bruchhauer sind nicht der einzige Stamm schändlicher Trolle, um die wir uns kümmern müssen! Die Blutfratzen haben dieses Land seit Jahren aus ihrer Festung Jintha'Alor heraus verdorben.\n\nWir sitzen nicht länger am Nistgipfel und drehen Däumchen, falls es Euch entgangen sein sollte. Doran Stahlschwing führt den Sturmangriff gegen die Blutfratzen von einem Lager im Süden, das die Jungs gerade eingenommen haben. Sprecht mit ihm und schließt Euch dem Kampf an!", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;! Wir müssen viele Trolle töten und haben mehr als alle Hände voll damit zun!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26497] = {title = "Blutfratzenabschaum", objective = "Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha'Alor.", description = "Die Blutfratzen sind ein anderer Stamm als die Bruchhauer, aber die Unterschiede sind kaum wahrnehmbar. Soweit es uns betrifft ist nur ein toter Troll eine guter Troll!\n\nAber täuscht Euch nicht, die Blutfratzen sind auch ohne die Ketten der Horde um ihre Hälse ausgesprochen bösartig. Sie werden das ganze Land vergiften, wenn wir uns nicht erheben und sie loswerden.\n\nIhr könnt mit ihren Hexendoktoren und Kopfjägern auf der unteren Etage beginnen. Sagt mir Bescheid, wenn Ihr eine ansehnliche Zahl von ihnen vernichtet habt.", progress = nil, completion = "Ja, wir werden diese Trolle noch loswerden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26498] = {title = "Tod den Blutfratzen", objective = "Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha'Alor.", description = "Wir machen gute Fortschritte. Rückt weiter vor und lasst nicht nach!\n\nDie Berserker der Blutfratzen kämpfen wie wilde Tiere und peitschen sich in einen wahren Blutrausch. Ihre Schattenzauberer rufen widerwärtige Geister aus dem Jenseits herbei. Das ist der Grund, warum wir uns dieser verdorbenen Kreaturen entledigen, <Name>, vergesst das nicht.\n\nBegebt Euch auf die mittlere Stufe und tötet Berserker und Schattenzauberer!", progress = nil, completion = "Es wird nicht lange dauern, bis wir die einzigen Zwerge sind, die auf diesen Mauern noch atmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26499] = {title = "Der Segen des Steinvaters", objective = "Gewährt 12 Irdenen Verteidigern den Segen des Steinvaters", description = "Solange der Steinvater gefangen gehalten wird, ist die Moral meiner Truppen am Boden. Normalerweise nimmt es jeder von meinen Leuten mit mindestens fünf Steintroggs auf einmal auf. Aber jetzt…\n\nGeht hinaus auf das Feld um das Dorf herum. Stellt Steinvater Erzmantels Banner in der Nähe meiner Verteidiger auf. Schenkt ihnen seinen Segen und erinnert sie daran, wofür sie kämpfen.", progress = nil, completion = "Ihr habt meinen Dank, &lt;Name&gt;. Ihr habt das Blatt komplett gewendet. Das Schicksal dieser feigen Steintroggs ist besiegelt.\n\nJetzt müssen wir uns daran machen, Steinruh zurückzuerobern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26500] = {title = "Wir sind umzingelt", objective = "Tötet 12 Wegelagerer der Steintroggs.", description = "Unser Krieg tobte schon, bevor die Zeitrechnung Eures Volkes begann. Mal sehen, ob Ihr etwas verändern könnt, <Volk>.\n\nDie Steintroggs sind ein Fehler der Titanen. Auf Eurer Welt sind sie dem Fluch des Fleisches erlegen. Doch hier in Tiefenheim seht Ihr sie in ihrer wahren Gestalt.\n\nWir sind hier umzingelt. Warum geht Ihr nicht hinaus und zertrümmert ein paar Troggs für uns? Seht Euch an, was in ihnen steckt.", progress = nil, completion = "Kein schlechter Anfang, aber Ihr werdet noch mehr töten müssen, wenn Ihr den Steinvater retten wollt.\n\nViel mehr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26501] = {title = "Versiegelung des Eingangs", objective = "Helft den Irdenen Geomanten, sich aus dem Kampfgeschehen auszuklinken und gebt ihnen dann die Felssturzreagenzien, damit sie das Rüstlager, das Gasthaus, die Baracken und den Schrein versiegeln können.", description = "Den Steintroggs ist es gelungen, sich unter unseren Häusern nach oben zu graben!\n\nIch habe Geomanten ausgesandt, die alle Gebäude versiegeln sollen. Sie benötigen jedoch Reagenzien und genügend Zeit außerhalb des Kampfes, um ihre Felssturzrituale zu vollenden.\n\nMeldet Euch bei General Kies Langfels, wenn Ihr fertig seid. Ihr findet ihn gen Norden an der Zerrissenen Front.", progress = nil, completion = "Das ist gut. Nun müssen wir uns keine Sorgen mehr über einen Angriff der Steintroggs aus dem Hinterhalt machen.\n\nMal sehen, wie Ihr uns an der Front von Nutzen sein könnt.", rewards = "Erdschwellender GürtelFelssturztreterStreitkolben des GeomantenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26502] = {title = "Donnersteine", objective = "Besorgt 12 Donnersteine.", description = "Die Zerrissene Front liegt im Norden. Dort finden die schwersten Gefechte statt.\n\nBegebt Euch ins eigentliche Steinruh und besorgt so viele Donnersteine, wie Ihr könnt. Unsere Ingenieure benötigen sie für die Katapulte.\n\nBringt sie zu Klei Lehmachse, wenn Ihr genug gefunden habt. Stört Euch nicht an seinem Ton. Er ist alt und griesgrämig und hätte schon vor Tausenden von Jahren in die Erde zurückkehren sollen.", progress = "<Der ältere Irdene hat mehr Risse als alle anderen. Er ist offensichtlich uralt.>\n\nWas stellt Ihr denn dar? Eine Art fleischiger Fehler? Verflucht, das seid Ihr!\n\n<Klei spuckt Staub auf den Boden.>Macht Euch nützlich oder haut ab von meiner Front.", completion = "&lt;Klei grummelt in sich hinein.&gt;\n\nJa, die passen. Legt sie da hinten hin.\n\n&lt;Der Irdene mustert Euch mit einem Auge und spuckt Staub auf den Boden.&gt;\n\nIch werde gleich etwas für Euch zu tun haben. Vielleicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26503] = {title = "Weitere Einschätzung der Gefahr", objective = "Stehlt die Schlachtpläne der Gnolle, die Befehle der Gnolle und den Strategieführer der Gnolle.", description = "Diese verdammten, wertlosen Gnolle führen nichts Gutes im Schilde. Ich spüre es in meinen Knochen. Die Gnollaktivität hat sich in den letzten zwei Wochen verdreifacht. Ich befürchte, dass sie einen Angriff auf Seenhain vorbereiten.\n\nIch möchte, dass Ihr die Lager der Gnolle in dieser Gegend aufsucht und dort alle Informationen sammelt, die Ihr finden könnt. Durchsucht die Lager unmittelbar nördlich von hier, östlich von hier und südöstlich von hier. Bringt mit, was Ihr dort findet.", progress = "Habt Ihr die Pläne der Gnolle gefunden?", completion = "Ich wusste es! Anscheinend steckt Jauler hinter dem Aufstand - was unglaublich ist, da wir ständig Gnolle namens Jauler umbringen. Ich weiß nicht, wie viele Söhne der ursprüngliche Jauler hatte, aber es müssen an die hundert sein.\n\nSieht jedenfalls so aus, als hätten wir noch einen Jauler zu töten.\n\nMagistrat Solomon muss davon erfahren.", rewards = "Jaulender UmhangStiefel des fruchtbaren VatertieresGürtner der SöhneIhr bekommt:\n\nDepeschenbeutel"}
MultiLanguageQuestData['de'][26504] = {title = "Gesucht: Rotkammgnolle", objective = "Tötet 15 beliebige Rotkammgnolle in der Drei Ecken genannten Gegend des Rotkammgebirges.", description = "Auf Befehl der Königswache von Sturmwind sollen alle Gnolle in dem Drei Ecken genannten Gebiet in der südwestlichen Ecke des Rotkammgebirges getötet werden.\n\nWenn Ihr die Gnolle in dieser Gegend beseitigt habt, dann meldet Euren Sieg Wachhauptmann Parker an der Turmwacht.", progress = nil, completion = "Wer gute Arbeit leistet, verdient eine Belohnung, oder?\n\nGebt nicht alles an einem Ort aus, &lt;Klasse&gt;. Verteilt es ordentlich, wenn Ihr versteht, was ich meine.", rewards = "Umhang des WachhauptmannsArmschienen der TurmwachtBrustplatte der königlichen WacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26505] = {title = "Parkers Bericht", objective = "Bringt Parkers Bericht zu Magistrat Solomon nach Seenhain im Rotkammgebirge.", description = "<Wachhauptmann Parker händigt Euch einen Bericht aus.>\n\nHier ist er, <Name>. Bringt meinen Bericht nach Seenhain nördlich dieses Turms und übergebt ihn Magistrat Solomon. Erklärt ihm, dass wir eine umfassendere Lösung für den Umgang mit den Gnollen benötigen. Schlagt Sprengstoff vor. Viel Sprengstoff.\n\nUnd bleibt auf der Straße, wenn Ihr wisst, was gut für Euch ist. Zu überleben ist gut für Euch, nebenbei bemerkt. Falls Ihr Euch gefragt hattet, was gut für Euch ist. Jetzt wisst Ihr es... Ach, vergesst es!", progress = "Wo habe ich mein Monokel nur hingelegt?! Conacher, seid Ihr das?", completion = "&lt;Magistrat Solomon setzt sein Monokel auf.&gt;\n\nOh, Ihr seid nicht Conacher. Was habt Ihr denn da?\n\n&lt;Ihr gebt Magistrat Solomon Parkers Bericht.&gt;\n\nDas kann doch nicht wahr sein. Jauler? SCHON WIEDER?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26506] = {title = "Würstchen mit Bohnen", objective = "Besorgt 4 Tarantelaugen, 4 Kondorinnereien und 4 Greiferzahnnieren.", description = "Ich brauche Eure Hilfe, <Volk>! Unsere Rationen sind verbraucht und die Wachen werden hungrig. Sie sehnen sich nach meinen weltberühmten Würstchen mit Bohnen, aber mir fehlen die Zutaten. Seid ein Schatz und helft mir, bitte.\n\nIch brauche ein paar Greiferzahnnieren, Kondorinnereien und TarantelaugenI. Ihr findet Greiferzähne, Kondore und Taranteln nahe dieses Turms. Seht Euch nur um!", progress = "Habt Ihr meine Zutaten bekommen?", completion = "PERFEKT! Die kommen sofort in den Topf. Das Abendessen sollte in ein paar Stunden fertig sein.\n\nDanke, Herzchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26507] = {title = "Versteinerte Delikatessen", objective = "Besorgt 12 erstarrte Steinfledermäuse für Kieselchen.", description = "Versteinerte Fledermäuse.\n\nElementare dieser Größe sind wählerisch. So leicht werdet Ihr nichts Besseres finden.\n\nIm Osten gibt es Basilisken. Sie lassen Steinfledermäuse zu Stein werden, die ihnen zu nahe kommen und essen sie als Zwischenmahlzeit. Ihr solltet Fledermäuse in ihrem Territorium finden.\n\nIch muss Euch jedoch warnen... wenn Ihr diesem kleinen Elementar zu viel Aufmerksamkeit schenkt, werdet Ihr ihn möglicherweise nie wieder los. Er kann sehr aufmerksamkeitsbedürftig sein.", progress = "<Kieselchen sieht zu Euch auf. Seine Augen beginnen schwach zu leuchten, werden mit jeder Sekunde größer und größer.>", completion = "&lt;Kieselchen springt auf den Haufen versteinerter Fledermäuse und wälzt sich darin, so als habe er vergessen, dass es Euch überhaupt gibt. Es wäre vielleicht das Beste, Kors Warnungen Glauben zu schenken.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPetrified Delicacies Complete Trigger\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26508] = {title = "Nidas Halskette", objective = "Findet Nidas Halskette.", description = "Meine Freundin Nida hat ihre Halskette verloren. Wir finden sie nicht mehr. Wir haben den ganzen Tag hier geangelt und auch schon die Umgebung abgesucht. Ich befürchte, dass sie in den See gefallen ist. Unsere Eltern wollen nicht, dass wir im See schwimmen gehen... meine Mama sagt, Unterwasser gäbe es fiese Wesen, aber Ihr seht nicht aus, als ob Ihr Angst vor fiesen Wesen hättet.\n\nKönntet Ihr die Kette für Nida finden, bitte?", progress = "Hallo. Ich habe meine Halskette verloren. Mein Papa hat sie mir geschenkt. Papa sagt, dass es Ungeheuer im See gibt. Habt Ihr Ungeheuer verprügelt?", completion = "Danke, dass Ihr meine Halskette gefunden habt, ehrenwerter &lt;Klasse&gt;... Ihr seid sehr nett! Mein Kätzchen dankt Euch auch – nicht wahr, Effsee?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26509] = {title = "Ein ungebetener Gast", objective = "Tötet Stopfwanst und nehmt Stopfwansts Hauer an Euch.", description = "Schon wieder wurde mein Garten zertrampelt und geplündert. Und ich weiß, welche Bestie das getan hat. Es ist dieser verdammte Eber, den Marschall Marris Stopfwanst nennt.\n\nDie Narzissen kann ich erst wieder zur nächsten Saatzeit pflanzen. Zerstört! Dieser bösartige Eber hat alles zerstört. Erledigt diesen Schädling! Zeigt mir seinen Hauer, dann werde ich Euch gern belohnen. Meistens sucht er auf dem Feld südwestlich von Seenhain nach Futter, aber manchmal verschlägt es ihn hierher in meinen Garten.", progress = "Ist Stopfwanst noch da draußen oder habt Ihr Seenhain endgültig von diesem Schädling befreit?", completion = "Endlich ist diese Landplage vorbei! Danke, &lt;Name&gt;, Ihr habt mir einen großen Dienst erwiesen. Der Garten wird zur Erntezeit in voller Blüte stehen!", rewards = "Ihr bekommt:\n\nScharlachroter Begonienstrauß"}
MultiLanguageQuestData['de'][26510] = {title = "Wir müssen uns vorbereiten!", objective = "Findet den Gnomcorder.", description = "Jeden Tag verschwinden weitere Bürger. Wir glauben, dass die Gnolle dafür verantwortlich sind, aber wir wissen nicht, wo sie unsere Bürger hinbringen! Wenn Ihr uns helfen wollt, die Gnolle zu besiegen und unsere Bürger zu finden, müsst Ihr ordentlich ausgerüstet sein. Leider haben wir keine Gnomcorder mehr. Ohne einen Gnomcorder können wir während Eures Einsatzes nicht mit Euch kommunizieren.\n\nUnseren letzten funktionstüchtigen Gnomcorder haben die Murlocs letzte Woche bei einem Überfall gestohlen. Begebt Euch östlich von hier zum Immerruhsee und bringt ihn an Euch!", progress = "Habt Ihr den Gnomcorder gefunden?", completion = "Hervorragend! Ich ändere noch ein paar Einstellungen, dann können wir beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26511] = {title = "Säuberung des Immerruhsees", objective = "Tötet 10 beliebige Murlocs im Immerruhsee.", description = "Auf dem Weg zum Immerruhsee? Es wird Euch sicher freuen, dass wir gerade eine Belohnung auf Murlocs ausgesetzt haben. Tötet so viele Ihr könnt, dann wird man Euch belohnen. Es ist egal, welche Murlocs. Tötet sie einfach wahllos.\n\nDer Immerruhsee liegt genau östlich von Seenhain. Es ist der See. Ist Wasser drin... Kommt Euch das bekannt vor?", progress = nil, completion = "Ihr habt den Murlocs eine Lektion erteilt. Hoffentlich überlegen sie es sich demnächst zweimal, ob sie unsere Stadt überfallen wollen.\n\nNein, ich glaube auch nicht daran.", rewards = "Schild der LektionWahlloser StabGürtel der wiederkehrenden SchlachtzügeBüttelhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26512] = {title = "Einstellung des Gnomcorders", objective = "Geht zum Friedhof von Seenhain, um die Frequenz des Gnomcorders einzustellen.", description = "Der Gnomcorder scheint zu funktionieren. Ich habe ihn Euch angelegt, aber wir müssen noch die Empfangsfrequenz einstellen.\n\nVerlasst Seenhain in Richtung Norden und folgt der Straße bis zum Friedhof. Wenn Ihr am Friedhof angekommen seid, versuche ich zu senden.", progress = nil, completion = "&lt;Der Gnomcorder knistert und kracht.&gt;\n\nKönnt Ihr mich hören, &lt;Name&gt;? Ist das Ding an? Ah ja, ich sehe Euch jetzt dort.\n\nWir können anfangen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStatic Sound\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26513] = {title = "Wie ein Furz im Wind", objective = "Bergt 8 Vorratskisten des Rotkammgebirges.", description = "Wir wurden letzte Nacht überfallen oder war es die Nacht davor? Ich weiß es nicht mehr genau. Seit drei Tagen kriege ich kein Auge zu. Wahrscheinlich verliere ich schon den Verstand.\n\nGnolle haben unsere Vorratslager geplündert. Alles haben sie mitgenommen! Rein und raus, lautlos wie ein Furz im Wind! Meine Soldaten sahen sie zu den Schluchten nordwestlich von hier laufen. Bringt unsere Vorräte zurück, <Klasse>!", progress = "Habt Ihr die Vorräte geborgen?", completion = "Danke, Bürger. Ohne Euch wären wir verhungert oder schlimmer noch, hätten dort draußen selbst nach Nahrung suchen müssen.", rewards = "Handschuhe des ErnährersBelüftete GamaschenHungersnotwesteUmhang der SchlaflosigkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26514] = {title = "Schluchtenspringen", objective = "Sammelt 10 Halsbänder der Rotkammgnolle.", description = "<Der Gnomcorder summt.>\n\nAls erstes steht ein flotter Marsch durch die Rotkammschlucht direkt im Norden von Seenhain an. Tötet jeden Gnom, den Ihr seht... huch, habe ich Gnom gesagt? Ich meinte Gnoll. Tötet jeden GNOLL, den Ihr seht und nehmt ihnen zum Beweis Eurer Tat das Halsband ab.\n\nEine Warnung, <Name>; hütet Euch dort draußen vor den Ettins. Meine Kundschafter haben in letzter Zeit riesige blutdürstige Ettins in den Schluchten gesehen. Geht ihnen aus dem Weg, wenn Ihr weiterleben wollt.\n\nSolomon Ende. Ich melde mich.", progress = "Habt Ihr die Halsbänder bekommen?", completion = "&lt;Der Gnomcorder knistert und kracht.&gt;\n\nGute Arbeit, &lt;Name&gt;. Ich habe gerade wichtige Informationen erhalten. Anscheinend sind unsere verhasstesten Feinde, die Schwarzfelsorcs, schlauer geworden...\n\n\n\nIch habe Euch ein paar Silbermünzen für die getöteten Gnome... äh, Gnolle übermittelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26515] = {title = "Ongo'longos Rache", objective = "Kämpft gegen Ongo'longo, bis er seine Ketten sprengt.", description = "Ich hab vor, Troll auf Troll zu hetzen.\n\nDie Blutfratzen halten einen miesen, alten Terrortroll in einer Grube gefangen. Seine Ketten sehen nicht sehr stabil aus. Ich weiß, wie so ein Unhold kämpft. Sie werden ihn nicht halten können, wenn er richtig wütend wird und loslegt.\n\nFindet den Terrortroll und kämpft gegen ihn, <Name>. Bringt ihn nicht um... schlagt nur ein wenig auf ihn ein, bis er rot sieht und ausbricht. Dann geht ihm aus dem Weg. Der wird den Blutfratzen ordentlich Beine machen.", progress = nil, completion = "Was für ein Spaß! Ich wünschte, ich wäre dabei gewesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26516] = {title = "Das gehört jetzt uns", objective = "Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha'Alor.", description = "Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.\n\nDenkt daran, dass Ihr hier nicht nur gegen Trolle kämpft, <Name>. Ihr kämpft gegen dunkle und böse Kräfte, die dieses Land zu Asche verbrennen werden, wenn wir sie leben lassen!\n\nZeigt keine Gnade!", progress = nil, completion = "Wir haben sie niedergemäht! Jintha'Alor ist so gut wie ausgelöscht!", rewards = "BluttrinkerstabSeelenfresserschulterschutzAuf Euch wartet eine dieser Belohnungen:\n\nStahlschwinganhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26517] = {title = "Schicksalsgipfel", objective = "Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha'Alor.", description = "Geht jetzt zum Gipfel, <Name>. Unsere Krieger wagen sich nur bis zu den letzten Toren vor. Sie sagen, dort es sei still wie in einem Grab; kein Geräusch, kein Atemzug, nichts rührt sich.\n\nSie halten es für eine Falle, aber das, was Ihr mir gebracht habt, lässt mich befürchten, dass etwas weit Böseres dort lauert. Geht zum Altar, findet heraus, was geschehen ist... und bringt mir ALLE mystischen Gegenstände oder dunklen Götzen, die Ihr dort findet! Habt Ihr mich verstanden?", progress = "Was habt Ihr gefunden?", completion = "Tot? Alle in der Nähe des Altars? Und sie hatten diese Spinnengötzen bei sich...\n\nDas ist Shadra. Die Spinnenloa! Sie versuchen ihre Kraft abzuzapfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26518] = {title = "Kopfprämie", objective = "Besiegt Umboda Dreikopf und holt Euch seinen Kopf.", description = "Es gibt kaum einen größeren Troll als Umboda Dreikopf. Er ist ein grausamer Schlächter, der die Köpfe von Zwergen und Trollen sammelt! Wird langsam Zeit, dass er bekommt, was er verdient.\n\nFindet den großen Schläger auf den unteren Terrassen und kommt mit seinem Kopf zurück!", progress = "Lasst mal sehen!", completion = "Was für eine hässliche Fratze. Hat wohl gehofft, unter den anderen Köpfen einen hübscheren zu finden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26519] = {title = "Wer die Ettins beherrscht", objective = "Tötet Ardo Schmutzpranke.", description = "Ihr seid über ein Dokument der Gnolle gestolpert. Der Gnoll, von dem diese Propaganda stammt, kann ein wenig schreiben:\n\nBRÜDER VON JAULER, HÖRT SCHMUTZPRANKE AN! ORCS GEBEN SCHMUTZPRANKE KUGEL! SCHMUTZPRANKE BEHERRSCHT ETTIN-VIECHER! SCHMUTZPRANKE ZERMALMT MENSCHIES! HOLT EUCH SCHMUTZPRANKES PRANK-O-GRAPH IN DEN RETHBANHÖHLEN. HÖHLE IM WESTEN, IN SCHLUCHT VERSTECKT!\n\n<Die Unterschrift besteht aus einem Prankenabdruck.>\n\n<Anscheinend hat jemand auch ein Stück aus der Schriftrolle gebissen.>\n\nIhr solltet dem vielleicht nachgehen.", progress = "<Mächtige Magie geht von der Kugel aus.>", completion = "&lt;Die Kugel zischt, als Ihr sie berührt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26520] = {title = "Rettet Großknecht Oslow", objective = "Benutzt die Ettinsteuerungskugel, um einen Ettin zu unterwerfen. Setzt die Ettinsteuerungskugel dann bei Eurem gebändigten Schluchtettin ein und bringt ihn dazu, Großknecht Oslow in Seenhain von dem riesigen Felsbrocken zu befreien.", description = "<Als Ihr die Kugel berührt, hört Ihr ein leises Klicken.>\n\n<Ihr nehmt die Kugel von ihrem Sockel.>\n\nNun kontrolliert Ihr die Kugel und damit auch die Ettins. Vielleicht könntet Ihr mit einem Ettin den riesigen Felsbrocken entfernen, unter dem Großknecht Oslow in Seenhain eingeklemmt ist. Findet einen Ettin und wendet die Kugel bei ihm an. Begebt Euch dann nach Seenhain.", progress = nil, completion = "Ihr habt einen Ettin benutzt, um den Felsbrocken zu entfernen, unter dem Großknecht Oslow eingeklemmt war? Unglaubliche Leistung, &lt;Name&gt;! Oslow wird Euch sehr dankbar sein, wenn er sich wieder gefangen hat.", rewards = "Solomons HammerDruckmittelarmschienenSchwert des fallenden HimmelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26521] = {title = "Gesichter des Bösen", objective = "Zündet mit der Tikifackel 8 Tikimasken in Jintha'Alor an.", description = "Die Blutfratzen haben ihre Tikimasken überall in Jintha'Alor an die Mauern gehangen. Wir werden ihre widerlichen Zauber und ihre dunkle Magie nicht dulden.\n\nDiese Botschaft werden wir ihnen überbringen und gleichzeitig ihre Abwehr durchbrechen! Nehmt diese Fackel, <Klasse>. Zündet ihre Tikimasken an und lasst sie brennen. Wenn ihre dunklen Idole zu Asche zerfallen, werden sie erkennen, dass sie den Wildhämmern nicht willkommen sind!", progress = nil, completion = "Die Elemente tanzen, das Feuer lodert. Durch die Flammen sollen sie den Preis ihrer Verruchtheit erkennen!", rewards = "Abscheulicher AstArmschienen aus Jintha'AlorAuf Euch wartet eine dieser Belohnungen:\n\nHalskette der bösen Fratzen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26523] = {title = "Alles, was krabbelt", objective = "Sammelt 8 huschende Spinnlinge in Jintha'Alor.", description = "Da oben hab ich noch was bemerkt... Jintha'Alor ist voller Spinnen. Kleine, nicht größer als Eure Hand. Nicht ungewöhnlich für das Hinterland, aber etwas daran ist seltsam.\n\nIch vertraue den Trollen nicht, wenn sie Haustiere halten. Sie haben was vor. Bringt mir ein paar dieser Spinnen. Haltet sie am Leben, wenn es geht, dann werden wir sehen, was mir die Geister zu erzählen haben...", progress = "Zeigt mir, was Ihr habt.", completion = "Bei Kurdans Bart... solche Spinnen hab ich noch nie gesehen. Dahinter steckt dunkle Magie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26524] = {title = "Dunkle Gefäße", objective = "Besorgt 5 Gefäße mit besudeltem Blut aus Jintha'Alor.", description = "Die Blutfratzentrolle hier beten seit jeher den verderbten Gott Hakkar, Loa des Blutes, an. Er war ein krankes, pervertiertes Wesen. Vor langer Zeit wäre er beinahe in unsere Welt vorgedrungen, konnte jedoch besiegt werden.\n\nDie Blutfratzen rühren immer noch in ihren dunklen Kesseln, die sie vor Jahren mit Blut gefüllt haben. Entweder hoffen sie auf einen längst verstorbenen Geist oder sie haben einen neuen, ebenso düsteren Plan.\n\nBesorgt mir diese Gefäße, <Name>. Wir müssen sie gemeinsam mit den Spinnen untersuchen, um zu verstehen, was hier vorgeht!", progress = "Seid in der Nähe der Kessel vorsichtig, <Klasse>. Die Blutfratzen werden sie nicht freiwillig hergeben!", completion = "Das ist nicht nur Blut... das ist Gift!\n\nSpinnen... Gift... Hoffentlich habe ich mit meiner Ahnung unrecht, &lt;Name&gt;.", rewards = "Sandalen des besudelten BlutesSandrenes Unsichtbare WesteSpinnengiftgamaschenBrustplatte des dunklen GefäßesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26525] = {title = "Giftige Geheimnisse", objective = "Tötet 8 Bruten von Shadra.", description = "Wenn das Opfer bereits vollbracht wurde, wird Shadra diese Welt langsam vergiften. In der Höhle wimmelt es wahrscheinlich schon von ihrer Brut.\n\nLasst sie nicht entkommen, <Name>. Bringt alle Spinnen um, die Ihr finden könnt!", progress = nil, completion = "Die sind wir los. Mögen diese schrecklichen Wesen nie wieder unser Land betreten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26526] = {title = "Jagt die Bewahrerin", objective = "Tötet Morta'gya die Bewahrerin und bringt die Tafel von Shadra an Euch.", description = "Shadra, die Spinnenloa... die Königin des Giftes, ein Geist der Dunkelheit und des Todes! Wenn es ein Opfer gegeben hat, werden die Trolle einen letzten verzweifelten Versuch unternehmen, um sie heraufzubeschwören.\n\n Sollten die Blutfratzen Rituale begonnen haben, dürfen sie nicht vollendet werden.\n\nÜberprüft die Höhle hinter dem Altar an der Spitze von Jintha'Alor. In ihrem Inneren verbirgt sich vielleicht noch eine von Shadras Bewahrerinnen. Tötet sie und bringt mir, was sie bei sich trägt, damit wir herausfinden können, was dort los ist.", progress = "Durchsucht ihre Leiche. Ich will nicht, dass mögliche Fallen der Blutfratzen durch ihre Tode unentdeckt bleiben.", completion = "Eine Tafel! Wenn ich das richtig lese... wird hier ein Ritual beschrieben, mit dem man Shadra selbst in diese Welt holen kann, sowie die Götzen, die man dafür benötigt.\n\nDass Ihr die Bewahrerin getötet und die Tafel an Euch gebracht habt, war sehr gut, &lt;Name&gt;.", rewards = "UnbewahrerklingeGamaschen der geheimen RitualeHandschuhe der seltsamen WorteSchulterstücke des TafelträgersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26527] = {title = "Greifenmeister Krallenaxt", objective = "Bringt die Tafel von Shadra zu Greifenmeister Krallenaxt.Ich würde diese Tafel in Stücke schlagen, wenn ich das Recht dazu hätte. Doch diese Entscheidung darf ich nicht fällen. Greifenmeister Krallenaxt muss sie sehen.\n\nKehrt mit der Tafel zum Nistgipfel zurück. Greifenmeister Krallenaxt kümmert sich im Greifenhorst um die Tiere.\n\nBeeilt Euch... aber lasst die Tafel bloß nicht aus den Augen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich würde diese Tafel in Stücke schlagen, wenn ich das Recht dazu hätte. Doch diese Entscheidung darf ich nicht fällen. Greifenmeister Krallenaxt muss sie sehen.\n\nKehrt mit der Tafel zum Nistgipfel zurück. Greifenmeister Krallenaxt kümmert sich im Greifenhorst um die Tiere.\n\nBeeilt Euch... aber lasst die Tafel bloß nicht aus den Augen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26528] = {title = "Das Auge von Shadra", objective = "Besorgt das Auge von Shadra aus Agol'watha.", description = "Greifenmeister Krallenaxt hat mich hierher geschickt, damit ich mich um Shadra, die Königin des Giftes, kümmere. Jintha'Alor zu erobern, ist nicht genug... die Trolle könnten sich neu formieren und die Kreatur zu einem späteren Zeitpunkt beschwören, wenn wir es am wenigsten erwarten.\n\nZuerst sammeln wir die Artefakte, dann holen wir Shadra unter unseren eigenen Bedingungen in diese Welt. Wir werden die verdorbene Kreatur mit unseren Hämmern vernichten. Ihr müsst dabei helfen, die Artefakte zu finden, und wenn Ihr schon dabei seid, dann fügt den restlichen Trollen ordentlich Schaden zu.\n\nDazu benötigen wir zuerst das Auge von Shadra, das in Agol'watha im Norden bewacht wird.", progress = "Hatte die Tafel recht? Habt Ihr das Auge gefunden?", completion = "Gut gemacht, &lt;Name&gt;. Schon bald werden wir an die Tür des Achtbeins klopfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26529] = {title = "Der Fangzahn von Shadra", objective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", description = "Als nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Abscheuliche Spinnen, groß wie Zwerge und doppelt so stark. Ihr Gift ist stark, <Name>... seid nicht nachlässig.", progress = "Habt Ihr den Fangzahn?", completion = "Das ist er... nur noch eines, mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26530] = {title = "Der Panzer von Shadra", objective = "Tötet Qiaga die Bewahrerin und bringt den Panzer von Shadra an Euch.", description = "Wir brauchen nur noch dieses letzte Stück, um Shadra endgültig auszuräuchern.\n\nDer Panzer von Shadra befindet sich im Besitz von Quiaga der Bewahrerin, der letzten Hohepriesterin der Spinnengöttin. Sie hält sich an der Spitze des Altars von Zul auf und wird von anderen fanatischen Zeloten bewacht.\n\nErklimmt den Altar bis zur Spitze und vernichtet sie. Sie wird den Panzer bei sich tragen. Bringt ihn hierher.", progress = "Habt Ihr ihn?", completion = "Das war alles, mein Freund! Wir sind bereit!", rewards = "Robe der letzten PriesterinGwenyths ArmschienenHandschuhe des fanatischen EifernsGroßhammer des HinterlandsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26531] = {title = "Die Beschwörung von Shadra", objective = "Benutzt das Idol von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra'Alor.", description = "Unsere besten Kämpfer stehen bereit, das Idol wurde zusammengesetzt... es ist soweit, <Name>.\n\nWir werden wie folgt vorgehen. Ihr reist mit dem Idol uns voran in Richtung Südwesten, nach Shadra'Alor. Ihr müsst das Idol an allen drei Tempeln einsetzen und Euch durch die Trolle, die sie bewachen, kämpfen.\n\nWenn Ihr das getan habt, wird Shadra in unsere Welt eindringen. Wir erwarten sie mit Zorn in unseren Herzen. Sagt meinen Jungs in Eurer Nähe Bescheid, sobald Ihr das Ritual vollendet habt.", progress = nil, completion = "Krallenaxt und die Jungs sind direkt hinter Euch. Lasst uns beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26532] = {title = "Shadra, Königin des Giftes", objective = "Tötet Shadra die Königin des Giftes.", description = "Keine Zeit verschwenden, <Name>! Sie kommt schon aus dem Wasser!\n\nGreifenmeister Krallenaxt ist bereits mit den Jungs unterwegs. Zeigen wir es dem Achtbein!", progress = nil, completion = "Ihr habt heute Großes für die Wildhämmer geleistet, &lt;Name&gt;. Ich wünschte, Falstad hätte das miterlebt.\n\nIm Namen des ganzen Klans möchte ich Euch gerne dafür entschädigen, dass Ihr diesen widerwärtigen Schatten von diesen Ländern ferngehalten habt. Ihr habt diese Belohnung redlich verdient.", rewards = "Schleier des NistgipfelsKopfschutz vom NistgipfelKopfbedeckung vom NistgipfelHelm vom NistgipfelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26533] = {title = "Zanzils Geheimnis", objective = "Beschafft 5 Phiolen von Zanzils Mixtur.", description = "Vor vielen Jahren verstießen die Gurubashi einen der ihren aus Zul'Gurub: Einen Troll namens Zanzil. Die Gründe dafür sind unklar, aber ich nehme an, dass es mit den starken, verhaltensverändernden Drogen zusammenhing, die er jedem, dem er begegnete, verabreichte. Wie dem auch sei, die Priester der Gurubashi und ihr Blutgott sind vernichtet worden, aber Zanzil der Ausgestoßene existiert noch...\n\n...ebenso wie seine starken, verhaltensverändernden Drogen.\n\nIch würde sie gern in die Finger bekommen, <Volk>. Überprüft die Zombies im Südosten.", progress = "Hervorragend... Ihr seid noch kein Zombie. Das ist gut.\n\nOh, äh... nichts. es gab nur ein... ein potentielles Risiko. Hatte ich vergessen, Euch zu warnen?", completion = "&lt;Jasper analysiert das seltsame Gemisch vorsichtig.&gt;\n\nDiese Mixtur ist... Ich verstehe sie nicht. Vielleicht sollten wir einige klinische Tests vornehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26534] = {title = "Was hast du zu bieten, Zanzil?", objective = "Bietet Jaspers DschungelschorleGmurgl, Orgus und Kapitän Bartholomäus Weichbart an.", description = "Besucher von Hartzangs Versteck müssen bei ihrer Ankunft einige Verzichtserklärungen unterschreiben. Eine davon erlaubt es uns, einfache Tests an ihnen vorzunehmen. Diese Klausel werden wir wohl wieder aktivieren.\n\nDoch dieses Mal sollten wir versuchen, unsere Kunden nicht zu vergiften. Ist besser fürs Geschäft.\n\n<Jasper füllt eine Karaffe mit Zanzils Mixtur und gestoßenem Eis.>\n\nDer südöstliche Turm des Verstecks dient als provisorisches Gefängnis. Wir nennen es \"Hartzangs Zuchthaus\". Lasst die Gefangenen trinken und sagt mir, was passiert.", progress = nil, completion = "Was, wirklich? Das ist hochinteressant. In dem Fall...\n\nWen interessiert, wie das Zeug funktioniert! Ich brauche das Rezept!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26535] = {title = "Zutaten für eine Katastrophe", objective = "Besorgt Zanzils Rezeptur von einem von Zanzils Anhängern in den Ruinen von Aboraz.", description = "Ich brauche Zanzils Rezept mehr als je zuvor. Einer von Zanzils Lakaien in den Ruinen von Aboraz müsste es haben. Reist nach Osten, zur anderen Küste des Kaps und stehlt es für mich!", progress = "Hat er Schimmerkraut verwendet? Er hat bestimmt Schimmerkraut benutzt.\n\nNein, warte... Bernsteinsamen! Es muss Bernsteinsamen sein.", completion = "Das ist faszinierend! Denkt an all die Anwendungsgebiete!\n\nNur um Missverständnissen vorzubeugen: Ich will keine Sklavenarmee oder so etwas. Nein, nein... Die Ogerexplosionen interessieren mich viel mehr!", rewards = "Formelhafter UmhangMischmeisterkniehosenStiefel des explosiven TanzensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26536] = {title = "Donnerfälle", objective = "Fangt 4 violette Flussbarsche bei den Donnerfällen südlich von Sturmwind. Kehrt mit Eurem Fang zu Catherine Leland zurück.", description = "Arnold und ich angeln schon seit Jahren in der Gegend um Sturmwind. So lange braucht man, um eine gute Stelle zu finden. Einer meiner Lieblingsorte wird Donnerfälle genannt.\n\nEr liegt südlich von Sturmwind im Wald von Elwynn. Das Beste an den Donnerfällen ist der violette Flussbarsch. Man findet ihn nur dort oben an den Wasserfällen. Arnold und mir fällt der lange Weg in letzter Zeit schwer, deshalb möchte ich Euch bitten, für uns dorthin zu gehen und einige Barsche zu fangen.", progress = "Habt Ihr die Fälle gefunden?", completion = "Diese Barsche sehen gut aus, &lt;Name&gt;. Wollt Ihr mit uns heute Abend Fische grillen?", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26537] = {title = "Zerschmettert sie!", objective = "Tötet 12 beliebige Steintroggs an der Zerrissenen Front.", description = "Geht hinaus und erledigt sie für mich.\n\nBerserker, Erdberster, Todesreiter... mir egal! Zerschmettert diese Steintroggs!", progress = nil, completion = "Ihr habt ihnen ganz schön zugesetzt. Aber ich glaube, wir müssen auf eine etwas andere Weise vorgehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26538] = {title = "Soforthilfe", objective = "Sucht einen Medizinmann im Hafen des Drachenmals, nahe des Ufers.", description = "Viele unserer Krieger sind bei dem Zwielichtangriff auf unsere Luftflotte gefallen. Die Überlebenden schwimmen den Überresten der Flotte entgegen. Sie bluten und haben schwere Verbrennungen erlitten. Ich brauche Unterstützung vom Ufer, um diese Männer zu retten!\n\nIm Hafen des Drachenmals wird es doch wohl einen Arzt oder Medizinmann geben, der gewillt ist, anderen Orcs zu helfen. Geht ans Ufer und versucht, Heilvorräte aufzutreiben und zur Flotte zu bringen!", progress = nil, completion = "&lt;Gregor verbeugt sich respektvoll vor Zaela.&gt;\n\nWenn dies Zaelas Wunsch ist, dann sollt Ihr Eure Vorräte bekommen. Sagt nur dem Kriegshäuptling des Drachenmals nichts davon...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26539] = {title = "Festgefahrene Verhandlungen", objective = "Sprecht mit Ornak im Hafen des Drachenmals. Horzog wird für einen raschen Transport zum Ufer sorgen.", description = "Der Aufenthaltsort des Kriegshäuptlings ist unbekannt! Aber sein Plan muss fortgeführt werden. <Name>, Ihr seht aus wie jemand, der weiß, was er tut.\n\nUnsere Verhandlungen mit dem Drachenmalklan sind festgefahren. Ihr Kriegshäuptling ist... anders als erwartet. Sorgt dafür, dass die Verhandlungen fortgeführt werden.\n\nTrefft Euch mit Ornak am Ufer. Er wird Euch alles erklären.\n\nRedet mit Horzog hier an Deck. Er wird für einen raschen Transport zum Ufer sorgen.", progress = nil, completion = "Ich bin froh, dass Ihr hier seid, &lt;Klasse&gt;. Vielleicht kann ein erfahrener Veteran, der für die Horde in Nordend und an anderen Orten gekämpft hat, den Anführern des Drachenmalklans Vernunft einreden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26540] = {title = "Gefährliches Mitleid", objective = "Bringt die Kiste mit Bandagen des Drachenmals zurück zu Kriegsfürst Krogg auf See vor dem Hafen des Drachenmals.", description = "Der rote Drachenschwarm stellt den Aspekt des Lebens dar. Deshalb hat sein Blut heilende Wirkung.\n\nDie Verbände in dieser Kiste wurden in rotes Drachenblut getränkt. Das sind meine letzten Vorräte. Mögen sich Eure Krieger dank ihnen rasch erholen.\n\nEs ist egal, wie Eure Verhandlungen hier ausgehen, Ihr werdet immer Freunde im Drachenmalklan haben.", progress = "Könnt Ihr unseren Verwundeten Hoffnung machen?", completion = "Drachenblut!? Wir sollten unseren Verbündeten unter den roten Drachen besser nichts davon erzählen.\n\nTrotzdem ist es mächtige Magie... Unsere Truppen werden bald wieder bereit stehen.", rewards = "HerzblutstulpenDrachenherzarmschienenBlutbindende SandalenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26542] = {title = "Heldenaufruf: Das Hinterland!", objective = "Reist zum Nistgipfel im Hinterland und sprecht mit Greifenmeister Krallenaxt.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Greifenmeister Krallenaxt im Greifenhorst am Nistgipfel zu melden.\n\nUnsere neuen Brüder in der Allianz brauchen unsere Hilfe dabei, die aggressive Hordenoffensive in ihrer geliebten Heimat abzuwehren. Reist vom Arathihochland nach Norden durch den zwergischen Bergpass und folgt der Straße nach Nordwesten Richtung Nistgipfel.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Willkommen am Nistgipfel, &lt;Name&gt;. Im Namen des Obersten Thans Falstad danke ich Euch für Euer Kommen, um uns zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26543] = {title = "Muscheln meucheln", objective = "Besorgt 10 Stücke Fleisch einer monströsen Muschel von den Muscheln an der Ostküste Durotars, südlich von Orgrimmar. Kehrt danach zu Razgar zurück.", description = "Nichts schmeckt so gut wie frisches monströses Muschelfleisch, <Name>. In den letzten Wochen hatte ich so viel zu tun, dass ich keine Zeit hatte, mich zu den örtlichen Muschelgründen zu begeben. Könntet Ihr mir vielleicht einige dieser Delikatessen besorgen?\n\nIhr findet die Muscheln in der Nähe des Strandes an der Ostküste von Durotar. Rund um den Hafen von Orgrimmar sollte es jede Menge geben.", progress = "Habt Ihr die Muscheln gefunden?", completion = "Scheinen die richtigen Muscheln zu sein, &lt;Name&gt;. Die werden gut schmecken.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26544] = {title = "Sie werden schlauer...", objective = "Besorgt das Sendschreiben der Orcs des Schwarzfelsklans.", description = "<Der Gnomcorder kracht und knackt.>\n\nDie Schwarzfelsorcs scheinen doch noch klug zu werden. Man hat mir gemeldet, dass sie sich mit den Gnollen verbündet haben und einen Angriff planen, Ich brauche Einzelheiten. <Name>!\n\nÜberprüft die Rethbanhöhlen im westlichen Teil der Rotkammschlucht für mich. Sucht nach Orcs mit dunkler Haut. Tötet alle, denen Ihr begegnet und durchsucht ihre Leichen nach Informationen.\n\nSolomon Ende.", progress = "Was habt Ihr herausgefunden?", completion = "&lt;Der Gnomcorder summt und surrt.&gt;\n\nLegt das Sendschreiben in das kleine Fach, damit ich es lesen kann. Ich spreche fließend Orcisch.\n\n&lt;Ihr hört einen entsetzten Schrei im Hintergrund.&gt;\n\nDiese Orcs scheinen auf Jaulers direkten Befehl hier zu sein. Das bedeutet, dass Jauler den Invasionsplan der Orcs besitzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26545] = {title = "Jauler muss sterben!", objective = "Tötet Jauler und bergt die Invasionspläne des Schwarzfelsklans.", description = "<Der Gnomcorder summt.>\n\nIhr müsst Jauler finden, <Name>. Er hält sich irgendwo im nördlichen Teil der Rotkammschlucht auf. Tötet den räudigen Hund und durchsucht seine Leiche nach den Invasionsplänen des Schwarzfeldklans. Sollte das gelingen, bringt die Pläne zu mir in das Rathaus von Seenhain.\n\nSolomon Ende.", progress = "Habt Ihr die Invasionspläne des Schwarzfelsklans?", completion = "&lt;Ihr gebt Magistrat Solomon die Pläne. Er beginnt zu lesen.&gt;\n\nSchattenfellarmee!? Diese verfluchten Orcs! Diese Invasionspläne weisen darauf hin, dass die Orcs und die Gnolle eine gewaltige Streitmacht im Osten zusammenziehen. Gath'Ilzogg, der General des Schwarzfelsklans will wohl mit seinen Armeen durch Seenhain marschieren und Sturmwind direkt angreifen!", rewards = "EskalationskniehosenBastardgamaschenBeinschützer der InvasionIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26546] = {title = "Klingenschnabelfreunde", objective = "Füttert 7 ausgebildete Klingenschnabelgreifen mit dem Greifenfutter.", description = "Für unseren Klan sind Greifen heilige Tiere. Wir verehren sie. Es sind majestätische Himmelswesen, mehr als nur Tiere. Sie sind intelligent und listig.\n\nManche behaupten, wir würden sie halten, aber es ist eher wie eine Freundschaft. Wenn Ihr Euch mit den Wildhämmern anfreunden wollt, dann freundet Euch zuerst mit unseren Greifen an! Nehmt diesen Futtersack. Alles darin ist frisch und gut. Ihr findet unsere ausgebildeten Klingenschnabelgreifen in den Wäldern südlich des Greifenhorsts. Würdet Ihr einige von ihnen für mich füttern?", progress = nil, completion = "Behandelt sie respektvoll, dann werden sie ebenso mit Euch umgehen.\n\nVergesst Eure Manieren und Ihr seid ein Auge los!", rewards = "Schal aus GreifendaunenGürtel des GreifenmeistersKlauenaxtAuf Euch wartet eine dieser Belohnungen:\n\nKlingenschnabelamulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26547] = {title = "Räudige Bedrohung", objective = "Tötet 8 räudige Silbermähnen.", description = "Wir beschützen unser Volk und unsere Greifen mit allen Mitteln. Dazu gehört, dass wir Räuber verjagen, und zwar die aus dem Wald und die der Horde.\n\nErst einmal werde ich Euch noch nicht bitten, uns vor den zweibeinigen Ungeheuern zu schützen. Räudige Silbermähnen streunen durch die Wälder im Süden. Sie attackieren die Greifen, die zu niedrig fliegen. Jagt einige Silbermähnen, damit sie erkennen, dass Greifen keine Beute sind.", progress = nil, completion = "Das hilft uns sehr, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26548] = {title = "Auf zur Front", objective = "Sprecht mit Kerr Eisenblick im Sturmfederaußenposten.", description = "Wir benötigen Eure Hilfe nun in dringenderen Angelegenheiten, <Name>.\n\nDie Horde wird dort draußen immer dreister. Sie sind in unserer Territorium eingedrungen und greifen uns hemmungslos an. Die Waldtrolle der Bruchhauer attackieren den Sturmfederaußenposten sogar bei Tage!\n\nIch brauche Eure Hilfe. Sprecht draußen mit Guthrum Donnerfaust. Er wird Euch einen Greifen zum Sturmfederaußenposten geben. Kerr Eisenblick wird Euch alles erklären, wenn Ihr dort eintrefft.", progress = nil, completion = "Schön, Euch hier draußen zu sehen! Wir können anfangen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26549] = {title = "Wahnsinn", objective = "Begleitet den Hordenunterhändler in den Hauptsaal im Hafen des Drachenmals und trefft Euch mit Kriegshäuptling Mor'ghor vom Drachenmalklan. Sprecht mit Ornak an der Küste, sollte Euch der Unterhändler abhanden kommen.", description = "Unsere letzten beiden Verhandlungsführer sind von den Gesprächen mit dem Kriegshäuptling des Drachenmalklans noch nicht zurückgekehrt. Ich glaube, wir müssen unsere Muskeln spielen lassen.\n\nDeshalb möchte ich, dass IHR dieses Mal den Unterhändler begleitet. Ihr Kriegshäuptling wird seine Haltung vielleicht ändern, wenn er erkennt, dass die Horde voll von kampferprobten Helden wie Euch ist.\n\nIhr müsst den Unterhändler nur in das Hauptlager im Hafen des Drachenmals begleiten und bedrohlich aussehen.", progress = "<Name>, ich habe gehört, dass Ihr mit dem \"Kriegshäuptling\" über den Beitritt zu Eurer Horde sprechen wollt.\n\nSeid vorsichtig, <Klasse>.\n\nKommt danach zu mir...", completion = "Aufwachen, &lt;Name&gt;! Wir haben nicht viel Zeit.\n\nIch habe Eure Ausrüstung gerettet.\n\nJetzt habt Ihr die Torheit unseres Anführers am eigenen Leib erlebt. Sein Blut ist verseucht, seine Wut unbezähmbar -- sein Bestreben, die Horde zu schlagen, wird uns alle vernichten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26550] = {title = "Durch die Hintertür", objective = "Stellt den Weihrauch der Gurubashi vor dem Totem von Hir'eek ab und hört Euch Zanzils Plan an.", description = "Zanzil der Ausgestoßene, der vom Gurubashistamm verbannt wurde, soll meine Beute werden. Vor kurzem habe ich von meinen Brüdern im Norden erfahren, dass er in die Gesellschaft zurückkehren will. Aus diesem Grund hat er einen Abgesandten zu den Schädelspaltern geschickt. Das sind keine guten Nachrichten.\n\nIch möchte, dass Ihr Euch Zanzils Pläne einmal anseht. Nehmt diesen Weihrauch und stellt ihn vor dem Fledermaustotem in den Ruinen von Jubuwal östlich von hier ab. Hir'eek wird Euch von dort an führen.", progress = nil, completion = "Das hatte ich vermutet. Zanzil ist zu hochmütig, um sich in die Streitigkeiten zwischen den Blutskalpen und den Schädelspaltern einzumischen. Nein, er ist Teil eines größeren Plans... Jin'do der Verhexer will mit seiner Hilfe Hakkar zurück nach Zul Gurub bringen.\n\nGut, dass wir das herausgefunden haben, denn es gibt eine einfache Lösung.", rewards = "Schleier des stillen ZuhörersSchiftung der FledermausAuf Euch wartet eine dieser Belohnungen:\n\nKleiner Weihrauchbeutel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26551] = {title = "Beseitigt den Ausgestoßenen", objective = "Reist zu den Ruinen von Aboraz am Kap des Schlingendorntals und kümmert Euch um Zanzil den Ausgestoßenen.", description = "Ihr werdet Zanzil töten. Ihr seid auf Hir'eeks Schwingen geritten und habt durch seine Augen geblickt; Ihr wisst, wo sich Zanzil in den Ruinen von Aboraz versteckt. Reist dorthin und tötet ihn.\n\nOh, und <Volk>: Benutzt diesen Fetisch, falls wir getrennt werden. Er funktioniert nur im Schlingendorntal und wird Euch hierher zurückbringen, solltet Ihr rasch zu mir gelangen müssen.\n\nViel Glück, <Volk>. Zanzil ist kein gewöhnlicher Gegner.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26552] = {title = "Durch das Trollloch", objective = "Benutzt Zanzils Portal und betretet Zul'Gurub.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", description = "Zanzils Portal nach Zul'Gurub ist noch geöffnet. Zul'Gurub ist ein gefährlicher Ort, aber Chabal glaubt, dass Ihr diese Aufgabe erfüllen könnt.\n\nDas Portal erwartet Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26553] = {title = "Hohepriesterin Jeklik", objective = "Vernichtet die Leiche der Hohepriesterin Jeklik, bevor Zanzil sie wiedererwecken kann.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", description = "Vor Euch ragt eine Rampe, die zu einer der zahlreichen Terrassen der Stadt führt, bedrohlich empor. Die fledermausförmigen Totems vor Euch weisen darauf hin, dass Ihr Euch im Reich der Hohepriesterin Jeklik, einer Anhängerin von Hir'eek, befindet.\n\nJeklik gehörte zu den Hakkar anbetenden Priestern, die Zanzil wiedererwecken wollte. Wenn Ihr Euch beeilt, gelingt es Euch vielleicht, die Erweckung aufzuhalten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26554] = {title = "Hals über Kopf nach Zul'Gurub", objective = "Geht durch Zanzils Portal.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", description = "Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26555] = {title = "Hohepriester Venoxis", objective = "Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", description = "Venoxis war der zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der nächste sein.", progress = nil, completion = "Ich hatte Euch gebeten, Zanzil den Ausgestoßenen zu töten, einen niederen verbannten Einsiedler der Gurubashi, und was macht Ihr? Ihr stürmt in die Hauptstadt der Gurubashi und eliminiert einen ihrer Hohepriester! Beinahe sogar zwei! Es gibt nur ein Wort, um ein so unbedachtes und tollkühnes Unterfangen zu beschreiben:\n\nHeldenmut.\n\nJin'do der Verhexer schleicht immer noch in Zul'Gurubs Mauern umher, aber als Ihr Jeklik zerschmettertet, verlor er eines seiner Beine. Heute ist der Sieg unser.", rewards = "Stiefel des LeichtsinnigenUmhang der großen VorhabenAuf Euch wartet eine dieser Belohnungen:\n\nChabals Lieblingsring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26556] = {title = "Müll abladen verboten", objective = "Angelt 6 giftige Pfützenfische und kehrt zu Razgar ins Tal der Ehre zurück, wenn Ihr fertig seid.", description = "Seit die Goblins in Orgrimmar Schutz gesucht haben, werfen sie all ihren Unrat in unsere Wasserspeicher.\n\nIch weiß nicht, welche Konsequenzen das für unseren Fischbestand haben wird, aber es sind bestimmt keine guten. Ich habe Berichte über eine neue mutierte Fischart erhalten, die in der toxischen Pfütze nahe ihres Lagers gesichtet worden ist. Einige Exemplare würden mir dabei helfen herauszufinden, was genau dort vorgeht.\n\nWürdet Ihr mir aushelfen?", progress = "Habt Ihr ein paar Exemplare geangelt?", completion = "Gute Arbeit, &lt;Name&gt;. Dank dieser Exemplare werden wir herausfinden, was in der giftigen Suppe dort vorgeht.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26557] = {title = "Augen auf beim Angeln", objective = "Erlegt einen Hirsch nördlich von Orgrimmar und benutzt sein Auge als Köder, um einen Sandkarpfen im Tal der Weisheit zu fangen. Kehrt danach zu Razgar ins Tal der Ehre zurück.", description = "Seit Jahren angle ich im Wasser von Orgrimmar Sandkarpfen. In letzter Zeit ist mir aufgefallen, dass meine Köder nicht mehr so gut funktionieren wie früher. Ich vermute, dass dies etwas mit den Tauren zu tun hat, die ins Tal der Weisheit gezogen sind.\n\nIch habe mit einigen ihrer Angler gesprochen. Anscheinend hat sich der Geschmack der Fische geändert. Heutzutage beißen sie wohl bei Hirschaugen an. Ihr solltet nördlich von Orgrimmar, unmittelbar hinter dem nördlichen Tor, jede Menge Hirsche finden.", progress = "War das Auge ein guter Köder?", completion = "Hervorragend! Diese Sandkarpfen sind ganz schön wählerisch, oder?", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26558] = {title = "Die Beschwörung von Shadra", objective = "Benutzt den Götzen von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra'Alor.", description = "Der Götze ist bereit, <Name>. Ich hoffe, Ihr seid es auch.\n\nReist mit dem Götzen vor uns nach Shadra'Alor im Südwesten. Ihr müsst den Götzen an jedem der drei Tempel einsetzen.\n\nWenn Ihr das tut, wird Shadra in dieses Reich beschworen. Die Todespirscher und ich werden rasch zu Euch stoßen, sie überwältigen und ihren Körper verwerten. Sprecht mit dem Späher, den ich vorangeschickt habe, wenn das Ritual vollendet ist, und wartet auf mein Eintreffen.", progress = nil, completion = "Marnal kommt näher...und Shadra noch näher. Bereitet Euch auf Blutvergießen vor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26560] = {title = "Jorgensen", objective = "Besorgt Jorgensens Käfigschlüssel.", description = "Ich weiß nicht, wo Krakauer oder Danforth sind, aber Jorgensen wurde nordwestlich von hier, in Renders Lager festgehalten. Wir saßen im gleichen, verdreckten Käfig, bevor man mich nach Althers Mühle verlegte.\n\nUm ihn zu befreien, brauchen wir den Schlüssel. Eine eiskalte Hexe aus der Hölle namens Utroka die Schlüsselmeisterin hält ihn fest in den Klauen. Wir müssen sie töten, wenn wir Jorgensens Käfigschlüssel haben wollen. Sie hält sich nördlich von hier in dem Tal auf, das zur Brennenden Steppe führt.\n\nAuf geht's, <Junge/Mädchen>.", progress = "Messner! Verdammt, es tut gut, ein freundliches Gesicht zu sehen. Holt mich hier raus!", completion = "Ich weiß, wo Krakauer und Danforth festgehalten werden. Wir müssen uns beeilen. Die beiden sollen geopfert werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26561] = {title = "Krakauer", objective = "Tötet Ritualist Tarak.", description = "Krakauer steht schon auf dem Richtblock! Die Orcs haben einen Hexendoktor der Gurubashi geholt, der ein dunkles Ritual über ihn sprechen soll. Wir müssen den Troll töten und Krakauer befreien!\n\nLos! Er ist in der Höhle dort. Geht nach rechts an der ersten Gabelung.", progress = nil, completion = "Wa... Wo bin ich? Was ist passiert? Messner? Jorgensen?\n\nOH MEIN GOTT! Wir müssen Danforth holen! Hoffentlich ist es noch nicht zu spät!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26562] = {title = "Der Nachzügler... Danforth", objective = "Tötet Oberanführer Barbarius und bergt den Hebelschlüssel des Schwarzfelsklans. Befreit Danforth mit dem Hebelschlüssel des Schwarzfelsklans.", description = "Danforth wird auf der anderen Seite der Höhle gefoltert. Wer weiß, in welchem Zustand er mittlerweile ist! Wir müssen zu ihm und ihn retten!\n\nOberanführer Barbarius trägt den Schlüssel zu dem Hebel, der Danforth oben hält, bei sich. Wenn wir zusammen arbeiten, können wir Barbarius, dieses Schwein, töten. Wenn Barbarius tot ist, holen wir Danforth mit seinem Schlüssel herunter und hauen ab!\n\nBereit?", progress = "Sieh mal einer an! Die ganze Truppe ist hier... abgesehen von Keeshan.", completion = "Worauf habt ihr Feiglinge denn die ganze Zeit gewartet? Meine Arme wurden schon müde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26563] = {title = "Rückkehr der Kompanie Bravo", objective = "Meldet Euch bei Oberst Trottmann in Seenhain im Rotkammgebirge.", description = "Ich weiß nicht, wer Ihr seid, <Freund/Schwester>, aber Ihr habt Euch den Respekt und die Bewunderung der Kompanie Bravo verdient. Ihr habt unsere Haut gerettet und auch noch eine Bootsladung voller Orcs getötet. Wir werden den Gefallen erwidern.\n\nReist zurück nach Seenhain und meldet Euch bei Oberst Trottmann. Wir werden Johnny finden und die gute Nachricht persönlich überbringen. Wenn die Kompanie Bravo loslegt, haben diese Orcs keine Chance.", progress = nil, completion = "&lt;Oberst Trottmann salutiert.&gt;\n\nUnglaubliche Arbeit, &lt;Name&gt;. Ihr habt es geschafft, die ganze Kompanie Bravo aus den Klauen der Schwarzfelsorcs zu befreien? Jetzt, da Keeshans Team gerettet ist und seine Habseligkeiten wieder da sind, gibt es für ihn keine Möglichkeit, uns abzuweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26564] = {title = "Heimwerker", objective = "Besorgt 6 Katapultteile.", description = "<Klei sieht Euch verächtlich an und macht ein Geräusch, das klingt, als reibe man zwei Steine aneinander.>\n\nSie haben all unsere Katapulte zerschlagen. Das hier versuche ich zu reparieren, aber bis jetzt ohne Erfolg.\n\nIhr könntet Euch nützlich machen. Reist zur Front und bringt mir alle Ersatzteile, die Ihr findet.\n\nKriegt Ihr das hin, Fleischsack?", progress = "Und? Ich hab nicht den ganzen Tag Zeit.", completion = "Also gut. Vielleicht seid Ihr doch in Ordnung.\n\nSchon gut, schon gut... kriegt Euch wieder ein. Gebt mir etwas Zeit mit diesen Teilen.", rewards = "KatapultladekelleAuf Euch wartet eine dieser Belohnungen:\n\nAufgezogene ZahnradfederZahnradaufspürer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26565] = {title = "Ein wütender Fang", objective = "Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach ins Tal der Ehre zu Razgar zurück.", description = "Steht Euch der Sinn nach einer Herausforderung, <Name>? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen mächtigen Wassern.\n\nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man ihn nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSack voll geangelter Schätze"}
MultiLanguageQuestData['de'][26566] = {title = "Ein Triumph gnomischer Erfindungsgabe", objective = "Sprecht mit Ingenieur Schleiffunke in Neu-Tüftlerstadt.", description = "Wir werden alle Waffen, Erfindungen und Soldaten brauchen, die wir kriegen können, wenn wir Razlo Ritzelstoß und seine Anhänger besiegen wollen.\n\nIm Nordosten werdet Ihr Ingenieur Schleiffunke finden, der einer neuen Generation brillanter Gnomendenker angehört. Stellt Euch vor: er hatte seit mehr als drei Prototypen keine Explosion mehr!\n\nGenug angegeben. Ingenieur Schleiffunke arbeitet an einem Bot, mit dessen Hilfe er den Toxischen Flugplatz reinigen will. Stellt Euch ihm vor. Vielleicht könnt Ihr ihm bei den Tests des Bots helfen.", progress = nil, completion = "Sogar Mekkadrill selbst hat also von meinem kleinen Projekt gehört? Wunderbar! Mein neuester Prototyp ist zwar fast fertig, aber Ihr könntet mir noch bei der Suche nach den letzten Teilen helfen.", rewards = nil}
MultiLanguageQuestData['de'][26567] = {title = "John J. Keeshan", objective = "Bemüht Euch um die Hilfe von John J. Keeshan im Gasthaus Seenhain in Seenhain.", description = "Habt Ihr mal von John Keeshan gehört, <Name>? Ich war in allen drei großen Kriegen sein Kommandant. Ich sage Euch, dieser Mann hat mehr Orcs getötet als jeder andere. Wenn jemand die Invasion der Schwarzfelsorcs aufhalten kann, dann JOHN J. KEESHAN. Wir müssen ihn dazu bringen, uns zu helfen. Wenn die gewaltige Schwarzfelsarmee auf ihrem Weg nach Elwynn durch Seenhain marschiert, wird sie das ganze Land in Schutt und Asche legen.\n\nIch habe gehört, dass er dem geheimen Kampfclub angehört, der sich im Gasthaus von Seenhain trifft. Findet ihn und erzählt ihm alles, was Ihr wisst.", progress = nil, completion = "Euch helfen? Diesen Leuten helfen? Diese Leute, die mich eher anspucken als anlächeln würden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26568] = {title = "Is' nich' mein Krieg", objective = "Kehrt zu Oberst Trottman zurück.", description = "Sie verlangten von mir, in diesen Kriegen zu kämpfen. Ich habe sie nicht darum gebeten! Ich tat, was ich tun musste, um zu siegen. Irgendwann wurde ich von diesen schmutzigen, mit Unrat beschmierten, verlausten Orcs gefangen genommen. Fünf lange Jahre benutzten sie mich als ihre Toilette. Schließlich brach ich aus, kehrte in meine Heimatstadt zurück... und was geschah? Die Leute spuckten mich an, beschimpften mich und nannten mich einen Babyorcmörder und andere üble Verleumdungen.\n\nNein, ich werde Euch wohl eher nicht helfen. Geht zurück zu Trottmann und sagt ihm, das sei nicht mein Krieg.", progress = nil, completion = "&lt;Trottmann seufzt.&gt;\n\nIch werde ihn noch nicht aufgeben, &lt;Name&gt; - und ich werde das Rotkammgebirge nicht aufgeben. Wir müssen ihn aufmuntern... Weckt das schlafende Monster in ihm auf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26569] = {title = "Vermessungsausrüstung", objective = "Beschafft 5 Teleskope des Schwarzfelsklans.", description = "Ah, meine Rettung! Ich habe gehört, dass Ihr Euch auf einer Mission zur Rettung von Seenhain ... und meiner Brücke... befindet. Hab viel zu lang daran gearbeitet, um zuzusehen, wie das verdammte Ding von plündernden Orcungeheuern zerstört wird!\n\nSolltet Ihr auf dem Weg nach Norden, zu Renders Lager, sein, könntet Ihr mir einen Gefallen erweisen. Besorgt ein paar Teleskope von den Fährtenlesern des Schwarzfels. Könnte ich gut für meine neue Vermessungsausrüstung gebrauchen.", progress = "Habt Ihr die Teleskope bekommen?", completion = "Großartige Arbeit, &lt;Name&gt;! Bei meinem nächsten Projekt, der SUPERBRÜCKE von Seenhain, die sich über den gesamten Immerruhsee erstrecken soll, werden sie mir gute Dienste erweisen. Die Brücke sollte in rund 20 Jahren fertig sein. Plus minus einem Jahrzehnt, oder zwei.", rewards = "Sandalen der endlosen BrückeHandschuhe aus SeenhainSchwarzfelsschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26570] = {title = "Renders Armee", objective = "Tötet 25 beliebige Schwarzfelsorcs in Althers Mühle oder Renders Lager.", description = "Hey, auf dem Weg nach Norden? Hättet Ihr Lust, Euren eigenen kleinen Krieg gegen diese Schwarzfelsmonster anzuzetteln? Was sagt Ihr dazu, <Name>?\n\nTötet jeden Schwarzfelsorc, der Euch rund um Althers Mühle oder Renders Lager begegnet. Tötet, bis sich Eure Haut von ihren Blutspritzern rot färbt und kommt dann zu mir zurück. Ich werde Euch großzügig belohnen.\n\nDas wird die Invasion des Schwarzfelsklans wahrscheinlich nicht aufhalten, aber es wird ihre Pläne empfindlich stören.", progress = nil, completion = "Ihr habt uns einen Tag, vielleicht sogar zwei verschafft. Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26571] = {title = "Kriegswaffen", objective = "Bergt Keeshans Bogen und Keeshans Überlebensmesser.", description = "Das, worum ich Euch bitten möchte, wird nicht leicht zu erfüllen sein, <Name>. Keeshan hat alles in diesem Orcgefängnis zurückgelassen, und damit meine ich nicht nur seine Seele und seinen Lebenswillen.\n\nWenn Johnny für uns kämpfen soll, müssen wir seinen wertvollsten Besitz bergen. Die Orcs haben Keeshans Bogen und sein Überlebensmesser an sich gebracht.\n\nReist nach Althers Mühle östlich von hier und sucht nach den beiden Orcleutnants Murdunk und Homurk. Sie haben Keeshans Ausrüstung. Holt sie Euch.\n\nIch bleibe mit dem Gnomcorder in Verbindung.", progress = "Habt Ihr Murdunk und Homurk eliminiert?", completion = "&lt;Der Gnomcorder summt voller Energie.&gt;\n\nMeldet Euch, &lt;Name&gt;. Versteht Ihr mich? Hier ist Trottmann! Danke, dass Ihr Keeshans Waffen zurückgebracht habt! Jetzt müsst Ihr nur noch eine letzte Mission erfüllen. Stellt Ihr Euch der Herausforderung?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26572] = {title = "Elektrisierender Einfall", objective = "Schneidet im Donnergrat, südlich von Orgrimmar, den Schwanz einer ertrunkenen Donnerechse mit Razgars Filetiermesser ab. Benutzt den Schwanz nahe eines goldenen Steinfischs, um ihn damit zu töten. Kehrt danach zu Razgar ins Tal der Ehre zurück.", description = "Wisst Ihr, was ein goldener Steinfisch ist, <Name>? Diese Fische kann man nicht mit normalen Mitteln fangen. Ihre Kiefer sind so stark, dass sie Angelhaken und Köder einfach durchbeißen.\n\nMan findet sie im Donnergrat südlich von Orgrimmar. Früher war der Grat voller Donnerechsen, aber sie sind alle bei der Flut ertrunken.\n\nNehmt mein Messer, schwimmt dort hinein und schneidet ihre Schwänze ab. Der Stromschlag des Schwanzes sollte die Steinfische töten.", progress = "Wie ist es da unten gelaufen? Hattet Ihr Glück mit den Schwänzen und den Steinfischen?", completion = "Gut gemacht, &lt;Name&gt;! Ganz ehrlich, goldene Steinfische bekommt man nur schwer. Das ist ein besonderer Leckerbissen.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26573] = {title = "Er muss mit ganzem Herzen dabei sein", objective = "Findet Keeshans rotes Stirnband und Keeshans Jadeamulett.", description = "<Der Gnomcorder klickt.>\n\nSeine Ausrüstung allein reicht nicht, <Name>. Er muss diese Schlacht von ganzem Herzen wollen. Um das zu erreichen, benötigen wir Gegenstände von sentimentalem Wert. Die Schwarzfelsorcs von Renders Lager im Norden besitzen zwei solcher Gegenstände, die Keeshan gehören.\n\nBegebt Euch dorthin und durchsucht ihre Kisten nach Keeshans Stirnband und einem Jadeamulett, das ihm seine Frau - die bei einer Invasion der Schwarzfelsorcs brutal ermordet wurde - hinterlassen hat.\n\nBringt sie zu mir, solltet Ihr fündig werden.", progress = "Habt Ihr Stirnband und Amulett gefunden?", completion = "Ich hoffe, dass er dank dieser Gegenstände und seiner geretteten Kameraden seine Meinung ändert. Ohne Keeshan sind wir aufgeschmissen.", rewards = "Weste des unbeständigen HerzensTrottmanns ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26574] = {title = "Adellas geheimes Lager", objective = "Meldet Euch bei Adella im Schattengeäst in Feralas.", description = "Lady Shandris hat Euch bereits darum gebeten, uns noch mehr zu helfen.\n\nAdella hat sich in Richtung Osten aufgemacht, zu den Waldpfotengnollen, und ein kleines Lager südlich von Camp Mojache errichtet. Wenn Ihr Lady Shandris und der Allianz weiter dienen wollt, so solltet Ihr Euch bei Adella melden.\n\nBegebt Euch nicht zu nahe an Camp Mojache heran... die Horde wird mit einem Angriff nicht zögern. Haltet Euch südlich und haltet nach unseren Bannern Ausschau.", progress = nil, completion = "Willkommen im Schattengeäst, &lt;Name&gt;. Lady Shandris hat Euer Kommen angekündigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26575] = {title = "Steinalt", objective = "Tötet Gorgonit.", description = "Ich muss Euch um einen weiteren Gefallen bitten, Fleischling.\n\nEs dreht sich um einen Basilisken, der viel größer und älter als die anderen ist. Normalerweise fürchten wir sie nicht, doch dieser Basilisk ist mittlerweile so stark, dass er sogar einige meiner Söhne versteinert hat. Das dürfen wir nicht hinnehmen.\n\nSucht Gorgonit im Osten und erschlagt ihn. Er hat bereits viel länger gelebt als nötig.", progress = nil, completion = "Danke, &lt;Volk&gt;. Ihr habt alles getan, worum ich Euch zu bitten wagte. Ich werde der Steinmutter berichten, welch guten Eindruck Ihr bei mir hinterlassen habt.\n\nMöge der Stein unter Euren Füßen Euch bei der Suche nach der Weltensäule stets stützen.", rewards = "Versteinerte SteinarmschienenBasiliskenaugenstabHellglanzschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26576] = {title = "Ruhige Hand", objective = "Sprecht mit Terrath dem Beständigen vor dem Bleichen Hort.", description = "Im Norden, ganz in der Nähe, werdet Ihr Terrath den Beständigen finden. Er hat die Aufgabe angenommen, die Steindrachen zurückzugewinnen. Alle paar hundert Jahre muss das wiederholt werden... die Steindrachen sind launisch und beugen sich nur der Stärke.\n\nTerrath ist ausgeglichen und vernünftig, doch seine Ziele werden schwer zu erreichen sein. Geht zu ihm. Appelliert an die ausgeglichenere Seite der Steinmutter.", progress = nil, completion = "Seid gegrüßt, &lt;Volk&gt;. Man hat mir Euer Kommen bereits angekündigt. Wenn Ihr mir helfen möchtet, dann könnte ich vielleicht auch Euch behilflich sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26577] = {title = "Felserhebung", objective = "Sprecht mit Gorsik dem Tosenden auf der Rubinspanne.", description = "Auf der Rubinspanne im Osten werdet Ihr Gorsik finden. Er steht für den instabilen und gewalttätigen Teil des Naturells unseres Volkes. Er ist weder freundlich noch offenherzig, aber seine Stimme hat Gewicht.\n\nBeweist Euch Gorsik, dann wird es Euch leichter fallen, Euch auch der Steinmutter zu beweisen.", progress = nil, completion = "Ihr seid Diamants Auserwählter.\n\nSo klein. So zerbrechlich.\n\nIst Euch bewusst, dass auf der Grundlage Eurer Handlungen der gesamte \"Irdene Ring\" beurteilt wird? Seid Ihr sicher, dass Ihr wirklich stellvertretend für so viele handeln wollt?\n\nIhr seid ein Narr. Ein zuversichtlicher Narr. Wir werden sehen, ob Ihr auch ein fähiger Narr seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26578] = {title = "Verdammnispilze", objective = "Zerstört 10 Verdammnispilze.", description = "Die Spalte, die in Eure Welt führt, hat unsere Heimat vergiftet. Korrumpiert. Verschmutzt.\n\nDiese Spanne schwärt und wächst. Unter dem ganzen Dreck kann man die Reinheit des Steins kaum noch erkennen.\n\nWenn Ihr uns zur Seite stehen wollt, dann beseitigt diese Überwucherung. Sucht nach hell leuchtenden Pilzen, die schneller wachsen als die anderen. Das sind die schlimmsten Übeltäter.", progress = nil, completion = "Ihr habt Euch an Diamant gewandt. Er ist geduldig. Vertrauensselig. Vielleicht zu sehr. Ihr müsst mir viel beweisen, wenn Ihr meine Gunst erlangen wollt, &lt;Volk&gt;.\n\nAber den Anfang habt Ihr immerhin gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26579] = {title = "Verweichlicht", objective = "Tötet 8 Fungusungetüme.", description = "Die Fungusungetüme um uns herum sind einer Schwäche erlegen, die der Eurer Art sehr gleicht. Ihre Haut ist weich geworden. Sie gehören nicht mehr zum Stein.\n\nTötet sie. Wir wollen nicht, dass diese Krankheit sich ausbreitet.", progress = nil, completion = "Ihr tragt ein gewisses Maß an Macht in Euch. Ich kann diese Stärke respektieren, besonders bei Eurer Art.\n\nMeine Bedenken sind noch nicht aus dem Weg geräumt. Weder in Bezug auf das übermäßige Wachstum noch auf Euch.", rewards = "Umhang des PilzwuchsesGurt der BoletenexplosionSporendurchtränkte GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26580] = {title = "Vertraute Eindringlinge", objective = "Sprecht mit den \"Fleischlingeindringlingen\" auf der Rubinspanne.", description = "Fleischling. Einige Eurer Art huschen über die Felsen. Zu scheu, um näher zu kommen, zu schnell, um sie zu zerschmettern.\n\nWenn Ihr meine Gunst erlangen wollt, kümmert Euch um sie. Ich bin diese Spielchen leid.", progress = nil, completion = "Schön Euch wiederzusehen, Bruder. Wie ich sehe, tragen Eure Bemühungen Früchte. Die Steinlords scheinen Euch zumindest ein wenig zu vertrauen.\n\nWir sind hier, um zu helfen. Vielleicht können wir gemeinsam herausfinden, was diesen plötzlichen Wuchs verursacht. Ich befürchte nämlich, dass Euer Riesenfreund seine Wut auf das falsche Ziel richtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26581] = {title = "Den Kopf in den Wolken", objective = "Bringt Lorvarius' Windteufel zu den Wolken aus rotem Nebel in der Rubinspanne und bringt eine Probe davon mit.", description = "Ich bin zwar kein Druide, aber ein paar dieser Pilze sehen nicht so aus, als seien sie natürlich gewachsen. Ich weiß, dass unser Freund, der Steinlord da hinten, Azeroth die Schuld an diesem Befall geben will, aber ich glaube, die Ursachen sind hausgemacht.\n\nIm Nordosten sah ich einige Wolken aus rotem Nebel am Wasser, die anscheinend neue Wucherungen nach sich zogen. Nehmt einen meiner Windteufel und besorgt mir eine Probe aus diesen Wolken. Es kann sein, dass Ihr in Bodennähe bleiben müsst, um sie zu sehen.", progress = nil, completion = "Ihr habt zugelassen, dass der Nebel Eure Haut berührt? Ich hoffe, es gab keine unangenehmen Wirkungen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26582] = {title = "Unnatürliche Ursachen", objective = "Sprecht mit Gorsik dem Tosenden in der Rubinspanne.", description = "Der Ursprung ist definitiv magisch. Nicht einmal druidisch. Ich habe einen der Steintroggs im Norden unter Verdacht.\n\nGeht zu Gorsik und weist ihn auf sie hin. Hoffentlich gewinnt Ihr dadurch seine Unterstützung.", progress = nil, completion = "Die Steintroggs? Und ich soll Euren Worten Glauben schenken?\n\nIch mag Verlok ohnehin nicht. Ein Verdacht reicht vollkommen aus, um sie zu Staub zu zermahlen. Wir werden sehen, ob Ihr die Wahrheit sprecht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26583] = {title = "Der Zorn der Fungumanten", objective = "Sprecht mit Erdheilerin Norsala, tötet dann Fungumant Glop.", description = "Ihr Anführer versteckt sich in seinem Loch dort vorn. Er hat diese Plage über die Rubinspanne gebracht.\n\nEr muss sterben.\n\nEine Eurer Begleiterinnen vom Irdenen Ring befindet sich bereits im Inneren. Ihr solltet mit ihr sprechen.", progress = "Ich passe nicht hinein. Unsere Elementare sind der Aufgabe nicht gewachsen.\n\nIhr müsst sie erledigen.", completion = "Gut gemacht, &lt;Volk&gt;.\n\nGorsik wird von Eurer Tat erfahren. Therazane wird von Eurer Tat erfahren.\n\nIhr seid ganz schön teuflisch für Eure Größe... und Eure Weichheit.", rewards = "Pilzbefleckte BeinplattenPilzstampferSporenschießerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26584] = {title = "Geschüttelt und gerührt", objective = "Tötet 8 Säulenbrecher von Verlok im unteren Teil der Wacht Verlok.", description = "Ich habe meine Brüder ausgesandt. Sie werden Verlok von oben angreifen. Die Verlok werden sich wie immer auf ihren Felsvorsprüngen versammeln, um unserem Zorn zu entgehen. Sobald sie das tun, werden wir dafür sorgen, dass die Erde bebt, bis sie zu Boden gehen.\n\nDann könnt Ihr Euch nützlich machen. Sorgt dafür, dass sie sich nicht mehr erheben, wenn sie zwischen meinen Brüdern am Boden liegen.", progress = nil, completion = "Gut gemacht, Fleischling. Ihr habt meine Brüder gut ergänzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26585] = {title = "Zerstörung der Verderbnis", objective = "Besorgt 8 Taschen des Wunderwachstumsmittels von Verlok.", description = "Wenn dieses abscheuliche Wachstum wirklich von den Einwohnern Verloks stammt, dann bewahren sie ihre Vorräte sicher im Dorf im Norden auf. Bringt sie mir, damit ich Eure Behauptung überprüfen kann.", progress = "Ich warte auf Euren Beweis, <Volk>…", completion = "Also sind Eure Worte wahr. Ihr habt meinen Dank, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26586] = {title = "Die Suche nach der Kompanie Bravo", objective = "Sucht in Althers Mühle nach einem Mitglied der Kompanie Bravo.", description = "Wenn Ihr und Keeshan Seenhain verteidigen wollt, müssen wir sein altes Bataillon finden. Das Letzte, was ich hörte, war, dass Messner, Jorgensen, Krakauer und Danforth von den Schwarzfelsorcs gefangen genommen wurden. Ich weiß zwar nicht, wo sie sein könnten oder ob sie noch leben, aber ich wäre ein verdammter Narr, wenn ich Euch nicht bitten würde, sie zu suchen.\n\nSucht in Althers Mühle östlich von hier nach Hinweisen.", progress = nil, completion = "Keeshan? Ihr meint, JOHNNY LEBT? Ihr könnt Euren süßen Allerwertesten wetten, dass ich helfen werde, aber erst müsst Ihr mich aus diesem verdammten Käfig befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26587] = {title = "Der Schlüssel zum Erfolg", objective = "Besorgt Messners Käfigschlüssel.", description = "Der Schlüssel zu diesem Käfig befindet sich in einem Beutel nördlich von diesem Ort im Höhlenbau der Worgen. Das Problem ist, dass dieser Beutel sicher auf einem Baumstumpf inmitten blutdürstiger, mordgieriger Worgs liegt. Holt den Schlüssel, ohne die schlafenden Worgs aufzuwecken.\n\nIhr habt nur einen Versuch. Reist zum Höhlenbau der Worgs und findet einen Weg zur Mitte. Seid vorsichtig und nehmt Euch vor dem Worghauptmann des Schwarzfels in Acht. Holt den Schlüssel und kehrt zu mir zurück.\n\nSolltet Ihr einen Begleiter haben, wäre es besser, ihn zurückzulassen!", progress = "Habt Ihr den Käfigschlüssel?", completion = "RACHE!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26588] = {title = "Ein wütender Fang", objective = "Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach zu Razgar ins Tal der Ehre zurück.", description = "Steht Euch der Sinn nach einer Herausforderung, <Name>? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen wilden Wassern.\n\nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man die großen nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.", progress = "Konntet Ihr einen riesigen Hecht fangen?", completion = "&lt;Name&gt;, Ihr habt einen! Einen so starken, schönen Fisch bekommt man nur selten zu Gesicht.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][26589] = {title = "Die Wildnis von Feralas", objective = "Reist nach Feralas und sprecht mit Konu Runentotem in Camp Ataya.", description = "Ihr habt heldenhaften Mut, uns dabei helfen zu wollen, diese Länder zu beschützen. Wenn Ihr der Wildnis noch mehr helfen wollt, so werden sich noch andere finden, die Eure Hilfe gebrauchen können.\n\nDer üppige Wald von Feralas liegt südlich von hier. Sucht in den Schatten der mächtigen Zwillingskolosse Konu Runentotem auf. Er hat Hinweise auf eine beunruhigende Krankheit gefunden.\n\nFolgt der Straße nach Westen, vorbei an den Zwillingskolossen, bis Ihr Camp Ataya erreicht. Geht in Frieden, <Name>, und mit der Erdenmutter.", progress = nil, completion = "Friede sei mit Euch. Ich wünschte, wir würden uns unter freudigeren Umständen treffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26590] = {title = "Das heilige Wasser der Klarheit", objective = "Schöpft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen Wellspring am Kap des Schlingendorntals.", description = "Hey, hört mich an. Ihr seht nicht wie ein gewöhnlicher Tourist aus, und ich stecke ein wenig in der Klemme. Mein Cousin im Norden hat mir dieses seltsame Artefakt geschickt und ich brauche Eure Hilfe, um es zu... äh... identifizieren.\n\nAls erstes müsst Ihr mir das heilige Wasser der Klarheit besorgen. Es heißt, dass jeder, der aus dieser Quelle trinkt, eine Vision der Klarheit erhält. \n\nKlingt recht vielversprechend, oder?\n\nSchöpft es aus dem Nek'maiquellbrunnen am Gipfel des Nagalagers. Viel Glück!", progress = "<Flem richtet seine Ohren auf, als Ihr Euch nähert.>\n\nDas heilige Wasser der Klarheit? Ist es hier!?", completion = "&lt;Der &lt;Volk&gt; stürzt das Wasser in einem Schluck hinunter.&gt;\n\nAhh... wisst Ihr, wie schwer es ist, im Schlingendorntal frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so streng bewachen!\n\nOh, stimmt ja... das Artefakt. Klarheit...\n\nMir ist alles klar!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26591] = {title = "Rettung an vorderster Front", objective = "Versorgt 10 verletzte Irdene.", description = "Ihr scheint schnell zu Fuß zu sein, <Volk>. Ich brauche jemanden, der sich in das Chaos der Front stürzt und unsere Verletzten versorgt.\n\nNehmt meine Rettungsausrüstung. Sie ist ganz einfach zu verwenden.\n\nHeilt sie, bevor die Steintroggs sie endgültig erwischen.", progress = nil, completion = "Falls Ihr Eurer Karriere als &lt;Klasse&gt; je überdrüssig seid, sucht mich auf. Ihr scheint mit diesen fleischigen Händen ziemlich geschickt zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26592] = {title = "Diffraktorisches Chromaskop", objective = "Besorgt einen Blutsegelrubin und einen Blutsegelsaphir.", description = "Ich benötige Analysewerkzeuge, um dieses Artefakt zu identifizieren. Ein diffractorisches Chromaskop sollte ausreichen, glaube ich.\n\nIch habe das Mithrilgehäuse bereits, was seltsamerweise am schwierigsten zu finden ist. Wir brauchen nur noch zwei andere Teile, einen Rubin und einen Saphir.\n\nIn der Nähe lagern Piraten, unmittelbar im Süden von hier und etwas weiter entfernt im Osten. Piraten lieben Schätze... seht doch mal nach, ob Ihr ein paar Edelsteine für mich findet.", progress = "<Flems Augen funkeln.>\n\nSind das etwa Edelsteine?", completion = "&lt;Flem wiegt die Edelsteine in seinen Händen und nickt zufrieden.&gt;\n\nJa, die reichen. Ich beginne die Analyse...\n\n&lt;Der Goblin schlägt die Edelsteine eine Weile gegeneinander, dann sieht er zu Euch empor.&gt;\n\nOh, Ihr seid immer noch hier? Ihr haltet mich doch nicht für einen Betrüger oder so?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26593] = {title = "Zitterhand Angst einjagen", objective = "Erhaltet 5 Nebeltalinnereien von alten Nebeltalgorillas.", description = "Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?\n\nDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.\n\nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.", progress = "He! Den Blick, den Ihr mir da zuwerft, mag ich gar nicht, Sire.", completion = "Igitt! Wo habt Ihr das denn her? Nein, sagt es mir lieber nicht. Ich will es gar nicht wissen!\n\nWer hat Euch geschickt? Seewolf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26594] = {title = "Rückkehr zu MacKinley", objective = "Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley.", description = "Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich alles zurückzahlen wollte! Ich schwöre es!!\n\nIch war nur ein bisschen betrunken und habe mich verlaufen... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!", progress = "Da seid Ihr ja, <Name>. Habt Ihr Zitterhands Bezahlung?", completion = "Heh heh, gut gemacht! Wie stark hat Zitterhand denn gezittert, als Ihr ihm die Eingeweide gezeigt habt?\n\nHah! Man kann ihn so leicht lesen, wenn man mit ihm Karten spielt, da muss man einfach gewinnen!\n\nMeinen Dank für Eure Hilfe, &lt;Name&gt;. Jetzt sollt Ihr bezahlt werden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26595] = {title = "Rien ne va plus - Nichts geht mehr", objective = "Besorgt Maurys Klumpfuß, Fitzpünktchens Drehmomentschlüssel mit Ratsche und Ephrams juwelenbesetzten Spiegel.", description = "Es gibt drei Phasen bei der Schuldeneintreibung: höflich fragen, energisch fragen und etwas, das ich als \"Phase Drei\" bezeichne.\n\nLeider bin ich alter Hund zu Phase Drei nicht mehr in der Lage. Deshalb muss ich so viele Kumpane, Handlanger, Angeber, Schläger und edle Abenteurer wie Euch einstellen!\n\nJans Fitzpünktchen, Ephram Mondsturz and Maury Wilkins verstecken sich an der östlichen Küste. Ihr solltet alle drei problemlos bei einem Ausflug abklappern können... Bringt mir ihren wertvollsten Besitz.", progress = "<Name>, habt Ihr die Schuldner gefunden?", completion = "Großartig! Die werden gutes Geld bringen, vor allem das, was sich in Maurys Fuß befindet! Vielen Dank, &lt;Name&gt;!\n\nIch hoffe, die drei haben ihre Lektion gelernt. Man soll nie etwas verwetten, was man nicht aufgeben kann.\n\nVielleicht ist es für sie zu spät, aber... sie sollten gut darüber nachdenken, mit wem sie spielen.", rewards = "Nette ShortsArmschienen der Phase DreiSchlagkräftiger SchildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26596] = {title = "Der Ruf von Kalimdor", objective = "Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.", description = "Ich wurde von den guten Leuten von Theramore geschickt, um loyale Mitglieder der Allianz zu finden, die Lady Jaina mit einigen Problemen in den Düstermarschen aushelfen kann.\n\nIhr wart doch nicht wirklich hier, um für die Goblins zu arbeiten, oder?\n\nDer Weg in die Düstermarschen führt durch Ratschet. Sprecht dort mit Gazlowe. Er wird euch von dort aus die richtige Richtung zeigen.\n\nIgitt... ich glaube, ich bin auf einen Fisch getreten! Und er hat gezappelt!", progress = nil, completion = "Ja? Was braucht Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26597] = {title = "Schlingendornfieber", objective = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizrackett.", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... \n\n...um genau zu sein, SchlingendornKAPfieber...\n\n...tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", progress = "... Mutter?\n\n... so kalt... \n\n... ich fahre hinab in den Wirbelnden Nether... h-h-h-halt mich fest, Mutter...", completion = "... fühle die Kraft zurückkehren... \n\nWo bin ich? Beutebucht? Ach du meine Güte! Ich hatte einen seltsamen Traum... \n\n... die Schwäche hat mich nicht vollständig verlassen...", rewards = "Fiebrige ArmschienenWilde HandlappenBrustharnisch der wiederkehrenden StärkeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26598] = {title = "Das Herz von Mokk", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "Hexendoktor Unbagwa weiß, was Mokk der Wilde mag. Ja, ja!\n\nIch sprechen mit Geistern und mach er kommen, tue ich.\n\nAber andere Gorillabiester mögen Geistersprechen auch. Du beschützt Hexendoktor Unbagwa und ich mach ihn kommen zu dir.\n\nHexendoktor Unbagwa will zuerst etwas. Du bringst Gorillafangzahn und ich lasse Geister reden!", completion = "Hexendoktor Unbagwa mag Gorillafangzähne! Für dich ich reden mit Geister. Lasse Mokk den Wilden kommen.\n\nDu beschützt Hexendoktor Unbagwa vor anderen Gorillabiestern, sonst kein Mokk für dich!", rewards = nil}
MultiLanguageQuestData['de'][26599] = {title = "Die Truhe des Kapitäns", objective = "Erhaltet Smotts' Truhe von Gorlash am Schlingendornkap.", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratschet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Beutebucht gesteckt. Ich werde nicht ruhen, bis ihre Leichen auf dem Meeresboden verstreut liegen!\n\n Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Ich habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", progress = "Ahoi, <Name>! Habt Ihr Gorlash finden können? Die Truhe war mein Lieblingsstück und sie hatte ein Geheimfach, mit meinen größten Schätzen.", completion = "Ihr habt sie gefunden! Das ist ein wunderbarer Tag für den alten Hecklebury! Dass ich meine Truhe wiederbekommen habe, beruhigt mich ein wenig.\n\nAber meine Rache ist noch nicht vollständig...", rewards = "Ihr bekommt:\n\nBlutbandarmschienen"}
MultiLanguageQuestData['de'][26600] = {title = "Ein riesiges Bankett", objective = "Kauft eine Kiste mit Fleisch der Güteklasse E von Kelsey Yance und eine Kiste mit Pupellyverbos Portwein von Klein Whiskey.", description = "Der nächste Riese auf meiner Liste nennt sich Negolash. Ich sehe noch vor mir, wie er aus der Gischt sprang und den armen Poopdeck-Paul aus dem Krähennest riss.\n\nVerschlang ihn in einem Bissen... Auf dem Weg nach unten brach er noch meinen Kreuzmast in zwei Teile.\n\nKeines meiner Besatzungsmitglieder hat einen so schrecklichen Tod verdient. Also werden wir Negolashs Appetit gegen ihn verwenden. Kelsey Yance verkauft Euch bestimmt etwas Fleisch, und Klein Whiskeys Schnaps reicht aus, um einen... nun, einen Meeresriesen umzuhauen. Ihr werdet beide in der Stadt finden.", progress = "Wir werden viel Essen brauchen, <Name>. Unser Ziel ist Quantität, nicht Qualität.", completion = "Das war doch nicht teuer, oder? Hier, nehmt ein paar Münzen als Entschädigung.\n\nUnd jetzt legen wir mit meiner Rache los, einverstanden?", rewards = "Ihr bekommt:\n\nYances Spezialbratling"}
MultiLanguageQuestData['de'][26601] = {title = "Mok'rash der Spalter", objective = "Tötet Mok'rash den Spalter auf der Janeirospitze.", description = "Mok'rash der Spalter ist der letzte Riese. Und der größte, wenn ich mich recht entsinne. Größer als eine Welle im Orkan, mit einem Bart wie ein Tangwald und einem Hammer mächtig wie eine Eiche.\n\nEr verhöhnt mich von der Janeirospitze, der Insel kurz vor diesem Pier. Nur wegen ihm sitze ich immer noch hier fest und friste mein Dasein als Landratte.\n\nWenn Ihr schwimmen könnt, dann macht Euch auf den Weg zur Janeirospitze und tötet Mok'rash.\n\nSeid vorsichtig, <Name>. Mok'rash wird sich nicht so leicht geschlagen geben wie seine Brüder.", progress = nil, completion = "Mo'krash... Negolash... Gorlash... sie sind alle tot.\n\nJetzt habe ich wohl keine Entschuldigung mehr. Ich kann auf die weiten Meere zurückkehren und wieder plündern und stehlen! Und das alles dank Euch.\n\nJetzt brauche ich nur noch ein Schiff....", rewards = "SeeweisenschulterklappenLandrattenstirnbandSeefeste BeineAuf Euch wartet eine dieser Belohnungen:\n\nSmotts' Siegelring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26602] = {title = "Riesenportionen erwünscht", objective = "Legt die Riesenkiste Riesenessen in Captain Smotts'Rettungsboot. Beschwört Negolash damit und tötet ihn.", description = "Nehmt das Essen und legt es in unser altes Rettungsboot südöstlich von hier an der Küste. Wenn Negolash das ganze Essen riecht, wird er angerannt kommen!\n\nUnd dann erwartet ihn bereits <ein beherzter/eine beherzte:c> <Klasse>, <der/die:c> seinen Kadaver zurück in die salzige Tiefe schleudern wird.", progress = nil, completion = "Ich kann mein Glück kaum fassen, &lt;Name&gt;! Mein Glück hat sich zum Besseren gewendet, seit ich Euch getroffen habe, so viel ist sicher!\n\nSollte ich ein neues Schiff bekommen und solltet Ihr je auf See gehen wollen, dann werdet Ihr mein Ehrengast sein.", rewards = "Ihr bekommt:\n\nSmotts' Kompass"}
MultiLanguageQuestData['de'][26603] = {title = "Flaschenpost", objective = "Sucht den Schreiber der Nachricht auf der Insel Jaguero am Schlingendornkap.", description = "In der Flasche findet Ihr eine Notiz, auf der Folgendes, in recht guter Handschrift, steht:\n\n<An alle, die mir helfen können:>\n\n<Bitte, ich benötige dringend Hilfe. Eine große Bestie hält mich auf einer Insel in den Südlichen Meeren gefangen.>\n\n<Die Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die Küstenlinie im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.>\n\n<Ich flehe Euch an, mein möglicher Retter, bitte helft mir.>", progress = nil, completion = "Seid Ihr gekommen, mich zu befreien?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26604] = {title = "Der Schutz ihrer königlichen Hoheit, Prinzessin Poobah", objective = "Tötet 5 Jagueropirscher.", description = "Diese teuflischen Dschungelkatzen umkreisen mich bereits seit einiger Zeit. Ich beobachte sie so gut ich kann, aber sie scheinen... im Gras zu verschwinden.\n\nHört, wie sie knurren und zischen!\n\nVersteht mich nicht falsch... Ihr sollt mich immer noch retten, aber beseitigt zuerst diese Katzen. Ich muss nicht gerettet werden, wenn ich danach als Abendessen ende.", progress = nil, completion = "Da seid Ihr ja endlich. Ich hatte schon befürchtet, ich würde gefressen werden, bevor Ihr von der Jagd zurückkehrt.\n\nEine Prinzessin im Magen einer Katze... wäre das nicht eine vornehme Beute?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26605] = {title = "Bahaarte Diebe", objective = "Sucht nach Poobahs Tiara, Poobahs Szepter, Poobahs Pantoffeln und Poobahs Tagebuch bei den Affen auf der Insel Jaguero.", description = "Ich verstehe ja, dass Ihr mich retten wollt, aber der richtige Zeitpunkt ist noch nicht gekommen.. Zuerst benötige ich etwas von meinem Besitz.\n\nDie Gorillas und Affen auf der anderen Seite der Insel haben das meiste davon gestohlen. Ich brauche meine Tiara, mein Szepter, meine Pantoffeln und mein Tagebuch, dann bin ich bereit zur Abreise.\n\nWas? Seht mich nicht an, als wäre ich irgendeine Verrückte. Ihr versteht nicht, was es bedeutet, Prinzessin zu sein.", progress = "Ich zittere bei dem Gedanken an das, was Mukla mit mir vorhat.", completion = "&lt;Poobah betrachtet ihren Besitz.&gt;\n\nEs scheint alles da zu sein. Also gut, dann bin ich bereit, gerettet zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26606] = {title = "Muklas Ende", objective = "Tötet König Mukla, findet den Fesselschlüssel.", description = "<Name>, ich setze all mein Vertrauen in Euch. Befreit mich. Der große Himmelsmähnenkönig Mukla hält mich gefangen. Er herrscht über die wilden Tiere auf der Insel. Mit Hilfe dieser Fessel halten sie mich hier gegen meinen Willen fest. Wenn es Euch gelingen sollte, ihn zu töten und den Schlüssel zu dieser Kette zu finden, würde ich tief in Eurer Schuld stehen.\n\nIch höre ihn oft an der Südostseite der Insel, aber seid bitte vorsichtig. Nehmt ihn nicht auf die leichte Schulter.", progress = "Ich danke meinen Ahnen, dass jemand gekommen ist, um mir zu helfen. Habt Ihr den Schlüssel, mit dem ich befreit werden kann?", completion = "&lt;Name&gt;, Ihr habt mich vor großer Ehrlosigkeit bewahrt. Wenn es in meiner Macht stünde, würde ich Euch einen Platz in meinem Stamm anbieten. Doch leider kann ich Euch erst einmal nur diese Kleinigkeit für Eure Tapferkeit und Euren Anstand anbieten.", rewards = "Prinzessin Poobahs KleidPrinzessin Poobahs ArmreifePrinzessin Poobahs TiaraIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26607] = {title = "Sie haben zuerst Blut vergossen", objective = "Bringt Keeshans Habseligkeiten zu John J. Keeshan im Gasthaus von Seenhain im Rotkammgebirge.", description = "Nehmt dieses Bündel mit Keeshans Habseligkeiten und kehrt in den Keller des Gasthauses in Seenhain zurück. Die Kompanie Bravo ist bereits dort und redet mit Keeshan. Erinnert ihn daran, wer als erstes Blut vergossen hat, <Name>. Seenhain braucht Keeshan. Die Allianz braucht Keeshan.\n\nWegtreten, Soldat!", progress = "Ihr schon wieder?", completion = "&lt;Keeshan nimmt Euch das Bündel ab und öffnet es.&gt;\n\nMein Bogen... und mein Messer! Wo habt Ihr...\n\nJades Amulett... Meine geliebte Jade.\n\n&lt;Keeshan nimmt sein rotes Stirnband.&gt;\n\nLasst uns Orcs töten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26608] = {title = "Abgebrochene Verhandlungen", objective = "Kehrt zu Admiral Steinfaust vor der Küste der Drachenmalfestung im Schattenhochland zurück.", description = "Geht nun, geht zurück zu Eurer Flotte. Sagt ihnen, was für ein Ungeheuer die Herrschaft über das Drachenmal für sich beansprucht.\n\nUnser \"Kriegshäuptling\" ist ein Verräter an seinem Blut. Seit seiner Rückkehr von der Scherbenwelt stinkt er nach Dämon und führt die Überreste unseres Klans ins Verderben.\n\nHelft dem Drachenmal, sich von Mor'ghor zu befreien, dann werden die unter uns, die reinen Blutes sind, für immer Eure Verbündeten sein. Das kann ich versprechen.", progress = nil, completion = "Die Höllenorcs aus der Scherbenwelt erheben Anspruch auf das Drachenmal? Obszön!\n\nWenn Höllschrei wüsste, was hier vorgeht, würde er ihre Stadt dem Erdboden gleichmachen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26609] = {title = "Die Blutsegelbukaniere", objective = "Erster Maat Krazz will, dass Ihr die Bucht nördlich von Beutebucht überprüft.", description = "Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, <Volk>, und <ein/eine:c> <Klasse> noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.\n\nWir haben Beutebucht zu unserem gemütlichen zweiten Zuhause auf dem Festland gemacht, aber Gerüchten zufolge, hecken die Blutsegelbukaniere wieder etwas aus. Meine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.\n\nBegebt Euch zur Bucht im Norden von Beutebucht an der Ungezähmten Küste und schaut, was Ihr so findet.", progress = nil, completion = "Oben auf dem Fass findet Ihr eine Karte mit einigen hastig geschriebenen Worten und einigen Münzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26610] = {title = "Blutsegelverrat", objective = "Meldet Eure Entdeckung dem Ersten Maat Krazz in Beutebucht.", description = "Auf der Karte hat jemand ein rotes \"X\" in Beutebucht eingezeichnet, genau dort, wo Ihr gerade steht.\n\nDaneben hat jemand gekritzelt:\n\n\"Errichtet Euren Kommandoposten hier und wartet ab. Der Flottenmeister wird sich bei Euch melden, wenn die Zeit reif für Taten ist.\"\n\n\"Ich übertrage Leutnant Bruce hier das Kommando. Dieses Mal wird alles anders sein. Dieses Mal werden wir Beutebucht endgültig erobern.\"\n\nDie Karte wird von einem Dolch gehalten, der mitten in Beutebucht steckt.", progress = nil, completion = "Sicher erinnere ich mich an Euch, &lt;Klasse&gt;. Wie ich sehe, seid Ihr vom Spähen zurück...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26611] = {title = "Der Baron muss davon erfahren", objective = "Berichtet Baron Revilgaz von den geplanten Blutsegelangriffen.", description = "Beim Klabautermann! Also planen die Blutsegelbukaniere irgendeinen Angriff auf Beutebucht? Diese Schurken haben vielleicht Nerven. Die Schwarzmeerräuber werden Beutebucht niemals preisgeben!\n\nDas ist größer, als ich vermutet hatte. Meldet Baron Revilgaz sofort Eure Entdeckung! Ihr findet ihn hier in Beutebucht.", progress = nil, completion = "Blutsegel Bukaniere greifen Beutebucht an? Das ist nicht das erste Mal, dass dieses Gesindel so etwas versucht. Beutebucht ist uneinnehmbar!\n\nHört sich so an, als ob sie eine Taktik versuchen wollen. Ich würde es Firallon zutrauen, etwas Verrücktes zu versuchen. Nun gut, lasst uns herausfinden, was sie jetzt wieder im Schilde führen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26612] = {title = "Einzelheiten des Angriffs", objective = "Tötet 8 Seebären der Blutsegelbukaniere und 8 Hochmagi der Blutsegelbukaniere und erbeutet die Blutsegelkarten und Blutsegelbefehle.", description = "Ich brauche Details, <Name>. Wir sind den Blutsegeln hauptsächlich wegen unseres Bollwerks hier in Beutebucht überlegen, aber Informationen spielen ebenfalls eine wichtige Rolle.\n\nDie Blutsegelbukaniere haben nur ein paar kleine Lager im Süden errichtet, die sie als \"Südkommando\" bezeichnen. Nun, dieses so genannte Südkommando werdet Ihr überfallen. Findet ihre Pläne und tötet ihre Männer. Kehrt mit allen Informationen, die Ihr findet, zu mir zurück.", progress = "Ahoi, <Name>. Was habt Ihr im Lager der Blutsegel im Süden herausgefunden?", completion = "Perfekt, &lt;Name&gt;. Jetzt, da wir ihren Plan kennen, ist es nur noch eine Frage der Zeit.\n\nUnd wenn ich bedenke, dass diese Narren genau vorm Kap vor Anker gegangen sind ...", rewards = "InformantenhandschuheGürtel der VorherrschaftBrustplatte des SeebaronsPiratenmusketeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26613] = {title = "Auf dem Schnupftabak", objective = "Deeg in Beutebucht möchte, dass Ihr ihm 15 winzige Haufen Schnupftabak bringt.", description = "Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.\n\nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben, nich?\n\nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.\n\nIch wette, <ein furchtloser/eine furchtlose:c> <Klasse> wie Ihr könnte sie überreden, die Ware zu teilen, nich?", progress = "Glück mit den Waren, Kumpel?", completion = "Klasse gemacht, &lt;Name&gt;! Und gerade noch rechtzeitig, bevor ich wieder Anker lichten muss! Kann Euch gar nicht genug danken, alter Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26614] = {title = "Ein Auge offen halten", objective = "Besorgt Torkels Auge von den Blutsegelbukanieren.", description = "Haltet ein! Wer da?\n\nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezialglasauge verzaubert, mit dem ich wieder was sehen kann.\n\nGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Beutebucht gefunden.\n\nKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?", progress = "Ahoi, Kumpel! Kann zwar nich' sehen, aber kann Euch schon über'n halben Hafen hinwech riechen.\n\nKönnte mein Auge wirklich gut gebrauchen. D'r Käpt'n wird mich wohl kielholen, wenn er rausfindet, dass mein Glubscher in die Hände der dreckigen Blutsegelbukaniere gefallen is'.\n\nWozu is'n Ausguck gut, wenn er nix sieht? Das Krähennest war mein Zuhause... ohne meine Augen kann ich von Glück sagen, wenn ich die Bilge schrubbn darf.", completion = "Da brat mir doch einer 'nen Storch! Ihr habt mein wunderbares Auge gefunden! Lass uns mal gucken, ob's noch passt.\n\n&lt;Name&gt; ho! Kinners, ich kann sehen!!", rewards = "Ihr bekommt:\n\nCape der dunklen Wogen"}
MultiLanguageQuestData['de'][26616] = {title = "Es ist nie vorbei", objective = "Fahrt auf Keeshans Flussboot zum Immerruhlager im Rotkammgebirge.", description = "Diese Schwarzfelsorcs werden eine Armee brauchen, wenn sie gegen die Kompanie Bravo und Euch etwas ausrichten wollen, <Name>. Trefft Euch mit uns an den Docks, die auf den Immerruhsee hinausgehen, wenn Ihr bereit seid. Wir segeln auf meinem Flussboot zum Immerruhlager auf der anderen Seite des Sees.\n\nBis später, <Name>.", progress = nil, completion = "Zeit, ein paar Orcs zu erledigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26617] = {title = "Ein alter Seebär", objective = "Bringt die verwitterte Münze zu Flottenmeister Seehorn in Beutebucht.", description = "Diese alte, verwitterte Münze wurde bei der Leiche des Piraten \"Guter Junge\" Bruce gefunden. Auf der Vorderseite ist das Abbild eines großen, unbekannten Piratenschiffs eingestanzt; auf der Rückseite der Begriff \"Mannschaft der Trümmerflut\".\n\nJemand, der schon lange im Pirateriegeschäft ist, konnte wissen, um was es sich bei dieser Münze handelt und was sie bedeutet.", progress = "Was habt Ihr denn da, <Volk>? Lasst mal sehen.", completion = "Diese Münze! Wo habt Ihr die her?\n\nBruce... ja, verstehe. Er gehörte früher den Schwarzmeerräubern an. War einer von uns, bevor Graumähne die Häfen von Gilneas schließen ließ und seine Besatzung gefangen nahm.\n\nIch weiß, dass sich die Leute durch das, was in Gilneas geschah, veränderten, aber ich hätte nie gedacht, dass sie ihre Loyalitäten wechseln würden. Vor allem nicht Bruce.\n\nKönnte ich die Münze vielleicht behalten? Ich gebe Euch ihren Gegenwert in Gold.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26618] = {title = "Wölfe sind uns auf den Fersen", objective = "Tötet 12 Terrorwölfe.", description = "Die Stadtbewohner werden in erster Linie von den Terrorwölfen bedroht. Sie lauern in den Wäldern um uns herum, die meisten findet man jedoch am Nordufer des Flusses.\n\nSie sind anders als die räudigen Hunde, die Ihr aus Elwynn, oder wo immer Ihr auch herkommt, gewöhnt seid. Sie sind mannsgroß und zweimal so teuflisch.\n\nWenn Ihr den Einwohnern von Dunkelhain wirklich helfen wollt, dann jagt die Wölfe, damit wir auf unseren Straßen endlich wieder sicher sind.", progress = "Jagt Ihr immer noch Wölfe...?", completion = "Denkt nicht, dass sei zu leicht gewesen. Tiefer in den Wäldern lauern weit größere Gefahren.", rewards = "Weste der NachtwacheStiefel der NachtwacheAuf Euch wartet eine dieser Belohnungen:\n\nSchwarzhaupts Band\n\nIhr bekommt außerdem:\n\nBlitzstrahlbündel"}
MultiLanguageQuestData['de'][26619] = {title = "Ihr wollt also eine Revolution", objective = "Schleicht Euch hinter die Frontlinie am Hafen des Drachenmals und sprecht mit Zaela.", description = "Wenn es stimmt, was Ihr sagt, <Name>, dann haben wir Freunde innerhalb des Drachenmalklans. Wir könnten einen Aufstand in ihren eigenen Reihen unterstützen. Das würde viel Blutvergießen auf beiden Seiten verhindern.\n\nIch kann dabei helfen, aber den gefährlichsten Teil muss ich Euch überlassen.\n\nMeine Krieger der Axtbeißer werden mit ihrer Offensive an den Küstenstreifen beginnen. Nutzt diese Ablenkung und schleicht Euch hinter die feindlichen Linien. Sprecht dort mit Zaela, Eurem Kontakt zu den Rebellen.\n\nWir werden den Drachenmalklan bewaffnen und seine teuflischen Herrscher stürzen!", progress = nil, completion = "&lt;Name&gt;, was machen Eure Leute? Greift Ihr das Drachenmal an oder seid Ihr hier, um uns von Mor'ghors Verderbnis zu befreien?\n\n\n\nAh, jetzt verstehe ich. Mir gefällt, wie Ihr denkt. Kriegshäuptling Mor'ghor wird völlig überrascht werden.\n\nLasst uns beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26620] = {title = "Gewürzte Wolfkebabs", objective = "Sammelt 5 Wolfskronfleischsteaks von Terrorwölfen.", description = "Gewürzter Wolfkebab ist eine Spezialität des Hauses! Natürlich kann ich Euch einige machen. Doch zuerst brauche ich die Zutaten.\n\nBringt mir fünf Wolfskronfleischsteaks. Die Terrorwölfe nahe dem Fluss nördlich der Stadt, lassen sich gut jagen, aber ich würde an Eurer Stelle nicht zu tief in die Wälder vordringen.", progress = "Habt Ihr schon fünf Wolfskronfleischsteaks gefunden?", completion = "Hmmm-hmmm! Das Kronfleisch ist der beste Teil. Allerdings ist es nicht sehr effizient, damit zu kochen.\n\nHier, nehmt dieses Rezept. Es unterscheidet sich ein wenig von dem anderen, aber Flankenfleisch ist viel leichter zu bekommen, wenn Ihr dringend eine Mahlzeit benötigt.", rewards = "Ihr bekommt:\n\nGewürzter WolfskebabRezept: Gewürzter Wolfskebab"}
MultiLanguageQuestData['de'][26621] = {title = "Aufstand", objective = "Bewaffnet 3 Arbeiter oder Händler des Drachenmals und tötet 10 Vollstrecker des Drachenmals und 4 Hexenmeister des Drachenmals.", description = "Die Waffen, die wir von der Horde bekommen haben, sind mehr als ausreichend. Wir vier sollten uns aufteilen und so viele Arbeiter und Händler des Drachenmals bewaffnen wie möglich.\n\nUnterschätzt uns nicht, <Name>. Selbst unsere Kaufleute sind im Kampf gnadenlos.\n\nLasst uns so viel Schaden wie möglich anrichten. Bewaffnet eine Truppe des Drachenmalklans und mäht die Teufelsvollstrecker und Hexenmeister nieder, die mein Volk schon so lange einschüchtern. Danach treffen wir uns hier, um unseren letzten Schlag einzuleiten!", progress = "Die Revolution hat endlich begonnen!\n\nDas Drachenmal schüttelt endlich die Fesseln ab, mit denen die Unwürdigen uns gebunden hatten.", completion = "Wir haben viele gute Orcs verloren, doch den Kampf werden wir für uns entscheiden, &lt;Name&gt;.\n\nMor'ghors Regime bricht zusammen. Nur die Bestie selbst steht noch.", rewards = "Fesselnzerreißender ZauberstabAuf Euch wartet eine dieser Belohnungen:\n\nRing der Rebellion\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26622] = {title = "Tötet Mor'ghor", objective = "Tötet Kriegshäuptling Mor'ghor im Hafen des Drachenmals. Ihr könnt immer noch Händler und Arbeiter des Drachenmals rekrutieren. Sie werden Euch helfen.", description = "Die Zeit ist gekommen. Heute stirbt Mor'ghor.\n\nEine Warnung, <Klasse>. Dämonenblut fließt durch seine verfluchten Adern. Er bedient sich unnatürlicher Kräfte. Er wird sterben, das ist sicher. Doch es wird kein leichter Kampf. Ihr wisst ja noch, dass sich Mor'ghor an der Spitze des Lagers aufhält. Dort werde ich Euch treffen. Erledigt ihn!\n\nVergesst nicht, 3 Anhänger des Drachenmals zu rekrutieren, solltet Ihr zu wenig Kämpfer haben - Ihr werdet unsere Hilfe brauchen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Während meiner Abwesenheit habt Ihr die Horde mit Stolz erfüllt.\n\nDer Drachenmalklan ist zu uns gestoßen. Zaela führt ihn an. Es wurde Blut vergossen, doch nur wenige sind gefallen. Das Drachenmal steht nun loyal hinter uns.\n\nUnsere Horde wird stärker!", rewards = "Treter des NormalbürgersHelm des wutentbrannten AufstandesSchulterschutz des HändleraufstiegsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26623] = {title = "Schwärzliche Krebsküchlein", objective = "Erbeutet 6 schwärzliche Klumpen von Giftweberspinnen.", description = "Ich verrate Euch ein kleines Geheimnis - Schwärzliche Krebsküchlein werden in Wirklichkeit aus Spinnenfleisch gemacht! Ist ein bisschen eklig, aber die Küchlein haben einen würzigen Beigeschmack und eignen sich gut als Zwischenmahlzeit!\n\nAber wenn Ihr immer noch welche probieren möchtet, muss ich leider gestehen, dass ich kein Fleisch mehr habe. Ich brauche ein paar Fleischklumpen, dann kann ich die Küchlein backen.\n\nJagt am besten Giftweberspinnen. Sie nisten im Norden zwischen dem Vorgebirge und dem Fluss.", progress = "Seid gegrüßt, <Name>. Habt Ihr die Fleischklumpen für mich?", completion = "Ah ja, da habt Ihr ja ein paar nette Klumpen eingesammelt! So, jetzt muss ich die nur noch mit meiner hochgeheimen Gewürzmischung würzen - wehe, Ihr schaut! - und sie dann noch ein bisschen in der Pfanne braten...\n\nDie schwärzlichen Krebsküchlein sind meine Spezialität, deswegen verrate ich das Rezept nicht. Aber hier habt Ihr das Rezept für ein Gericht, das fast genauso gut schmeckt.", rewards = "Ihr bekommt:\n\nRezept: Klebriger SpinnenkuchenKlebriger Spinnenkuchen"}
MultiLanguageQuestData['de'][26624] = {title = "Auf Tuchfühlung mit den Blutsegeln", objective = "Meldet Euch bei Yancey Grillsen am Wasserfall nördlich von Beutebucht.", description = "Diese Pläne sind... interessant. Firallon, so dumm kannst du doch nicht sein!\n\nSeht, alle seine Schiffe sollen sich auf das Feuern ihrer Kanonen konzentrieren. Nur ein paar Männer kommen durch die Tunnel rein. Mit drei Schiffen und einem Dutzend Kämpfer wird er Beutebucht nie einnehmen. Und das weiß er auch.\n\nNein, sie haben etwas anderes vor... und Ihr werdet herausfinden, was. Sprecht mit Yancey Grillsen, dem Rekrutierer der Blutsegel.\n\nRichtig, <Name>. Hofft, dass sie Euch nicht wiedererkennen.", progress = nil, completion = "Jaaa, is' die richtige Entscheidung, Bursche.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGetting In With the Bloodsail: Set Bloodsail Faction Friendly\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26625] = {title = "Troggzor der Erdinator", objective = "Erbeutet den Knüppel des Erdinators.", description = "Ihr müsst das sofort beenden!\n\nKehrt zur Front im Nordwesten zurück und tötet ihren Schlachtenführer, Troggzor den Erdinator. Bringt mir zum Beweis seinen Knüppel.", progress = "Ist er tot? Habt Ihr den Knüppel?", completion = "&lt;Der General nickt ernst.&gt;\n\nEndlich können wir vorrücken und den Steinvater befreien.", rewards = "Troggzors kristalline PlatteHelm der ErdinierungErdinierende BauerngamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26627] = {title = "Der Einsiedler", objective = "Findet den Bewohner des Turms im Bettlerschlupfwinkel.", description = "Ich habe gehört, dass etwas im Bettlerschlupfwinkel vor sich geht. Man sieht Lichter im Turm östlich der Stadt.\n\nNur wenige haben den Mut, sich so nahe am Gebirgspass der Totenwinde aufzuhalten. Ihr seid <der/die> erste, <der/die> sich hier meldet, seit ich davon erfahren habe. Seht es Euch an und stellt sicher, dass das, was dort haust, menschlich ist.", progress = nil, completion = "Ah, willkommen, Fremder! Ich würde Euch gerne etwas anbieten, aber hier gibt es nicht viel...\n\nDürfte ich Euch bitten, ein paar Botengänge für einen alten Einsiedler zu machen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26628] = {title = "Tod von unten", objective = "Beschützt Wank O'Breen während des Angriffs.", description = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.\n\nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.\n\nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Beutebucht zurückzufinden.\n\nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.\n\nSeid Ihr bereit, <Name>?", progress = nil, completion = "Wir haben den Angriff überlebt!\n\nOhne Euch hätten wir es nicht geschafft, &lt;Name&gt;.\n\nSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.\n\nAuch wenn Ihr nur ein schwacher &lt;Volk&gt; seid...", rewards = "O'Breens GalarobenFaldirs GamaschenArmschützer des guten KapitänsBeinschützer des vielversprechenden HeldenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26629] = {title = "Feststellung Eurer Loyalität", objective = "Besorgt den Kopf von Flottenmeister Seehorn in Beutebucht.", description = "Da is' nur eine Sache...\n\nYancey hört einiges. Ein paar Kumpel von mir hatten schon ziemlich tief ins Glas geschaut, als sie mir erzählten, dass sich <ein/eine:c> <Klasse> durch das Südkommando gekloppt un' nach Karten und Befehlen gesucht hat. <Er/Sie> hat sogar ein paar anständige Piraten über die Klinge springen lassen.\n\nWie ich schon sagte, denen kam der Grog aus den Augen raus, aber... ein Bukanier muss seinen Ohren trauen. Deshalb hat mich Firallon selbst gefragt, ob ich Euch nich' ne kleine Aufgabe stellen könnte...\n\nBringt mir den Kopf von Flottenmeister Seehorn.", progress = "Spezialbefehl von Firallon. Sagt, der Tauren sei zu gefährlich.", completion = "Na da haut's mich doch aus dem Krähennest! So was sieht man wirklich selten.\n\n&lt;Yancey schüttelt Eure Hand.&gt;\n\nWillkommen an Bord, &lt;Name&gt;. Beutezüge und Plünderungen erwarten Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26630] = {title = "Sieht doch wie ein Taurenpirat aus", objective = "Besorgt einen Kuhkopf und einen übergroßen Piratenhut. Bringt beides zu Flottenmeister Seehorn.", description = "Firallon will MEINEN Kopf? Das ist wirklich interessant. Aber wir finden schon einen Ausweg.\n\nDieser Yancey weiß wahrscheinlich nicht so genau, wie ich aussehe. Den meisten Nicht-Tauren fällt es schwer, uns Tauren auseinanderzuhalten. Den meisten Nicht-Tauren fällt es sogar schwer, uns von einem gewissen... vierbeinigen Nutztier zu unterscheiden.\n\nRikqiz, der Lederverarbeiter, hält eine solche Kreatur hier in Beutebucht, und Narkk versorgt mich mit Piratenhüten. Besorgt Ersatz für meinen Kopf und meinen Hut und kehrt mit beidem hierher zurück.", progress = "Ihr solltet wissen, dass das den meisten Tauren peinlich wäre. Ich finde es... amüsant.", completion = "Damit sollten wir den minderbemittelten Blutsegelbukanier täuschen.\n\nDas hat Spaß gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nFlottenmeister Seehorns Kopf"}
MultiLanguageQuestData['de'][26631] = {title = "Euer erster Tag als Pirat", objective = "Bringt Käpt'n Kielhol Eure Papiere.", description = "Ihr habt zwar den Flottenmeister erledigt, aber Regeln sind Regeln und Befehle Befehle. Und meine Befehle besagen, dass alle neuen Piraten als Deckhelfer anfangen. Das sind die Regeln.\n\nIhr werdet für Käpt'n Kielhol, den Kommandanten der Springflut, arbeiten. Es is' das westlichste Schiff der Flotte, die südlich der Kapspitze liegt.\n\nSucht ihn in seiner Kapitänskajüte auf un' bringt ihm Eure Papiere.", progress = "Habt Ihr Eure Papiere, Deckhelfer? Will Euch ja nich' den ganzen Weg zurück zu Yancey schicken.", completion = "Ja... ja... Verstehe... scheint alles in Ordnung zu sein.\n\nHabt den großen Seehorn weggeputzt, ja? Spielt auf MEINEM Schiff keine Rolle. Das einzige, was Ihr hier wegputzen werdet, sind die Flecken auf dem Deck. Nehmt Euch einen Mopp.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26632] = {title = "Geleitschutz", objective = "Geleitet das Katapult der Irdenen sicher nach Nadelfelsbruch.", description = "Gut, ich glaube, das funktioniert wieder. Ihr müsst das Katapult nach Nadelfelsbruch, der Stadt der Steintroggs, nördlich der Front bringen.\n\nDer Fahrer wird Euch begleiten. Ich werde mich auf den Rückweg machen und Kies darüber informieren.\n\nDie Steintroggs werden zweifellos versuchen, Euch aufzuhalten. Haltet sie vom Katapult fern. Es hat eine ziemliche Durchschlagskraft.\n\nLasst mich wissen, wenn Ihr bereit seid, <Name>.", progress = nil, completion = "&lt;Der Katapultkommandant wirft Euch einen anerkennenden Blick zu.&gt;\n\nDie Erzählungen von Eurer Kampfkunst eilen Euch weit voraus, &lt;Volk&gt;. Wollen wir mal sehen, ob Ihr uns auch dabei helfen könnt, diese Fungusschrecken von der Front fernzuhalten.", rewards = "Handschuhe des KatapultladersIrdene UmklammerungAuf Euch wartet eine dieser Belohnungen:\n\nGebrochene Notbremse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26633] = {title = "Putzdienst", objective = "Nehmt Euch einen Deckhelfermopp vom Deck der Springflut und haltet das Deck 2 Minuten lang sauber.", description = "Die Decks der Springflut sollten leuchten wie ein Sternrubin, Deckhelfer <Name>. Ich führe 'n ordentliches Schiff, dafür sorgen Deckhelfer wie Ihr!\n\nNa, worauf wartet ihr denn noch, Ihr miesmuscheldämliche Schiffsratte? Ans Deck mit Euch! Nehmt den Mopp in die Hand!", progress = nil, completion = "Ich habe wilde Putzgeräusche von hier unten gehört, Bursche. Genau DAS will Euer Käpt'n hören.", rewards = "PutzkniehosenSwabbies StiefelchenRippströmungswesteKielholfesselnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26634] = {title = "Der Fluch vieler Piraten", objective = "Besorgt 5 Scheffel Limonen.", description = "Zahnfleischerkrankung. Das ist ein großes Problem, <Volk>.\n\nIch weiß, dass Ihr neu seid und Euch wahrscheinlich noch nie jemand das Zahnfleisch aufgeschnitten hat, aber wir anderen Piraten müssen uns mit etwas herumschlagen, dass sich SKORBUT nennt. Deshalb lagern wir hier so viele Limonen.\n\nNa ja... lagerten hier so viele Limonen. Jemand hat unsere letzte Lieferung geklaut, aber sie können nicht weit gekommen sein - vielleicht bis zu den nahegelegenen Inseln? Schafft sie wieder her, dann überlege ich mir vielleicht, was ich tun kann, um für Eure Beförderung vom Deckhelfer zu sorgen.", progress = "Zu viele gute Männer habe ich an dieser leicht zu verhindernden Krankheit sterben sehen, <Volk>. Wir brauchen diese Limonen.", completion = "Ich werde sie direkt verteilen, &lt;Volk&gt;. Und ich werde ein gutes Wort für Euch einlegen.", rewards = "Ihr bekommt:\n\nGarrs LimonenbrauseGarrs Limonenpastete"}
MultiLanguageQuestData['de'][26635] = {title = "Schwimmen mit Kanonenkugeln", objective = "Bergt 6 Blutsegelkanonenkugeln aus dem Wasser unter der Springflut.", description = "Würdet Ihr 'nem Deckhelferkameraden helfen?\n\nKielhol hat mir befohlen, ein paar Kanonenkugeln vom Meeresboden aufzusammeln. Ich erklär' Euch, wieso ich das nicht kann.\n\nErstens: Ich habe winzige Arme. Seht sie Euch doch an! Glaubt Ihr wirklich, ich könnte damit eine Kanonenkugel aufheben, selbst, wenn sie Unterwasser liegt?\n\nZweitens: Ich habe sehr schwache Atmungsorgane. Mir wird schon schwindlig, wenn ich den Atem länger als zehn Sekunden anhalten muss.\n\nDrittens: Da sind Haie.\n\nIhr müsst mir helfen, <Name>! Eine weitere Degradierung würde ich nicht aushalten... Will gar nicht wissen, was als Nächstes käme!", progress = "Wisst Ihr, ich war nicht immer ein Deckhelfer.", completion = "Danke, &lt;Name&gt;. Ich hab' schon Leute 'was von wegen \"dem Schönling\" und irgendeiner \"Buhkiste\" reden hören. Ich glaube nicht, dass ich diese Buhkiste von innen sehen will.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26636] = {title = "Fernmeldeausrüstung der Bravo-Kompanie: Tarnung", objective = "Sammelt 5 Blätterhaufen und 5 Portionen Fuchskot.", description = "Wir werden einiges an Ausrüstung brauchen, bevor wir die Schwarzfelsarmee ausschalten und das Rotkammgebirge retten können. Dabei könnt Ihr Euch nützlich machen, Grünschnabel.\n\nKeeshan hat mir befohlen, dafür zu sorgen, dass die Fernmeldeausrüstung der Bravo-Kompanie getarnt wird. Ich möchte, dass Ihr nach Süden geht und Euch ein wenig \"gärtnerisch\" betätigt. Bei diesem kleinen Abenteuer gibt es zwei Zutaten, über die Ihr Bescheid wissen solltet: (1) Blätter und (2) Fuchskot. Wir brauchen beides.\n\nHabt Ihr Euch nie gefragt, woraus Tarnung besteht?\n\nGeht nach Süden und findet, worum ich Euch gebeten habe, <Freund/Lady>.", progress = "Blätter und Kot - das brauche ich.", completion = "Gut gemacht, Grünschnabel. Ich lege die Tarnung direkt in die Kiste. Wir sollten bald bereit sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26637] = {title = "Fernmeldeausrüstung der Bravo-Kompanie: Chloroform", objective = "Sammelt 8 Matschwirblerdrüsen.", description = "Der erste Teil unserer Mission findet verdeckt statt, <Name>. Deshalb müssen wir in der Lage sein, unseren Feind lautlos auszuschalten. Um das zu erreichen, brauchen wir Chloroform.\n\nDie Drüsen der Matschwirbler am Grund des Immerruhsees enthalten Chloroform. Schwimmt hinunter und besorgt mir Matschwirblerdrüsen. Kriegt Ihr das hin?\n\nKehrt zu mir zurück, wenn Ihr genügend Drüsen gefunden habt.\n\nIhr wollt wissen, wo der See ist? Macht die Augen auf, Trottel. Unmittelbar westlich.", progress = "Habt Ihr die Drüsen gefunden?", completion = "Perfekt. Diese Orcs werden uns buchstäblich verschlafen. Ich brauche einige Minuten, um sie zu verarbeiten, dann lege ich sie in die Fernmeldeausrüstung der Bravo-Kompanie.", rewards = "MatschwirblerhandschuheImmerruhbrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nChloroformphiole\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26638] = {title = "Jagd auf die Jäger", objective = "Tötet 8 Jäger des Schwarzfels.", description = "Südlich von hier, entlang des Uferpfads, lauern Schwarzfelsorcs in den Wäldern. Im Schutz der Dunkelheit überfallen sie die Ahnungslosen. Diese Orcs bilden die erste Verteidigungslinie der Schwarzfelsarmee. Es sind Kundschafter, die alles, was sie sehen, ihrem Oberkommando melden. Sie müssen AUSGESCHALTET werden, sonst könnten sie unsere Mission gefährden.\n\nGeht nach Süden und tötet alle Jäger des Schwarzfels, die Ihr seht.", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Wir müssen uns beeilen, bevor sie Verstärkung anfordern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26639] = {title = "Kontaktpunkt: Brubaker", objective = "Findet Brubaker.", description = "Wir müssen unser Marschgepäck zusammen bekommen, vorher sind wir verdammt unnütz. Dabei werdet Ihr helfen, <Name>. Kundschafter benötigen wir ebenfalls. Zum Glück haben wir Unterstützung aus Sturmwind erhalten. Brubaker, ein alter Kriegskamerad von mir, ist von SI:7 geschickt worden, um uns als Kundschafter zu dienen. Trefft ihn im Kampfgebiet südlich von hier.\n\nTrefft Euch mit Brubaker und findet heraus, was er weiß.", progress = nil, completion = "Brubaker ist tot. Anscheinend versuchen die Orcs durch diesen grausigen Anblick eine Nachricht zu senden. Bei näherem Hinsehen entdeckt Ihr etwas in Brubakers Beutel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26640] = {title = "Unaussprechliche Gräuel", objective = "Bringt Brubakers Report zu John J. Keeshan im Immerruhlager im Rotkammgebirge.", description = "<Ihr faltet die Notiz auseinander und beginnt zu lesen.>\n\nKeeshan, wenn Ihr diese Nachricht lest, werde ich tot sein. Wahrscheinlich wurde meine Position kompromittiert.\n\nDie Orcs begehen unaussprechliche Gräuel an ihren Gefangenen. Ja, Gefangene, Keeshan. Sie haben Käfige voll mit Kriegsgefangenen. Bevor Ihr dieses Tal in die Luft sprengt, müsst Ihr die Gefangenen befreien.\n\nSagt meiner Frau, dass ich sie liebe und dass sie den verdammten Müll rausbringen soll.\n\n-Brubaker\n\nPS - Sie haben schwarze Drachen.\n\nBringt Keeshan Brubakers Report.", progress = "Sie haben Brubaker erwischt?", completion = "&lt;Keeshan liest den Report.&gt;\n\nVERDAMMT! Jetzt wird es kompliziert. Wir müssen die Kriegsgefangenen befreien, bevor wir das Tal sprengen können. Mal ganz abgesehen von den schwarzen Drachen, die den Orcs zur Seite stehen.\n\nSeid Ihr bereit, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26641] = {title = "Eiertanz", objective = "Besorgt 5 Eier der Shadrabrut aus Agol'watha.", description = "Die Brutwachen der Blutfratzen im Nordosten bewachen die Eier von Shadras Brut. Auch wenn wir die Blutfratzen töten, werden diese schrecklichen Kreaturen irgendwann aus ihren Eiern schlüpfen und in die Wildnis entkommen.\n\nDas müssen wir verhindern. Reißt alle Eier, die Ihr findet, aus ihren Eiersäcken und bringt sie mir. Versucht nicht, sie selbst zu zerstören; die Kleinen könnten herauskommen.\n\nWenn Ihr wieder hier seid, sorge ich dafür, dass sie vernünftig entsorgt werden!", progress = "Habt Ihr die Eier?", completion = "Wir werden sie sofort verbrennen und die Asche zur Sicherheit verstreuen.", rewards = "Mantel der ShadrabrutWolkenrufergamaschenGürtel des verstreuten WindesBeinschützer der VorsichtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26642] = {title = "Erhaltung des Brachlands", objective = "Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland.", description = "Seit Jahren bildet das Brachland das Herz des Hordengebiets in Kalimdor. Es ist eine wichtige Verbindung zwischen den Orcs von Durotar und den Taurensiedlungen in Mulgore.\n\nIm Chaos des Kataklysmus drohen wir durch Überflutungen, Erdbeben und sogar einer Invasion der Stacheleber von diesem wichtigen Grasland abgeschnitten zu werden.\n\nIhr wirkt, als wärt Ihr bereit für eine Herausforderung. Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht und stellt sicher, dass der Weg ins Brachland frei bleibt! Reist ins nahe gelegene Klingenhügel und von dort aus gen Westen. Überquert den Südstrom, dann werdet Ihr ihn finden.", progress = nil, completion = "Ein neuer Rekrut aus Orgrimmar, richtig?\n\n&lt;Kargal mustert Euch.&gt;\n\nIch nehme, was ich kriegen kann. Es ist ein Alptraum, die Straßen frei zu halten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26643] = {title = "Hungerdiät", objective = "Zerstört 6 eingesponnene Opfer in den Gruselruinen.", description = "In den Gruselruinen östlich von hier wimmelt es von ausgewachsenen Spinnen der Shadrabrut. Sie sind so groß, dass sie einen ganzen Zwerg nachts davonschleppen können. Die Beweise dafür werdet Ihr sehen, wenn Ihr dort ankommt... eingesponnene Körper überall in den Ruinen.\n\nSie halten sie nicht lange am Leben, <Name>, aber von den Leichen ernähren sie sich tagelang. Den Opfern kann niemand mehr helfen, aber diese Spinnen dürfen nicht noch fetter und kräftiger werden. Sorgt dafür, dass diese Kokons verschwinden.", progress = nil, completion = "Eine makabere Aufgabe, &lt;Name&gt;, doch nun werden sich die überlebenden Spinnen nicht mehr erholen. Ich danke Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26644] = {title = "Aufmerksamkeit erregen", objective = "Meldet Euch bei Flottenmeister Firallon im Inneren der Purpurschleier am Schlingendornkap.", description = "Deckhelfer <Name>! Das ist ein trauriger Tag für den alten Käpt'n Kielhol. Heute verliere ich meinen besten Deckhelfer.\n\nIch habe einen Brief von Flottenmeister Firallon erhalten. Anscheinend hat er von Eurer guten Putzleistung gehört. Ihr sollt an Bord der Purpurschleier kommen und als sein Bootsmann und Dritter Maat dienen. Sie liegt direkt neben der Springflut.\n\nDas ist 'n großer Schritt in Eurer Piratenkarriere, Deckhelfer <Name>. Ich würde vorschlagen, sein Angebot anzunehmen.\n\nWegtreten!", progress = nil, completion = "Also Ihr habt den alten Seehorn abgemurkst? Yancey hat so was gesagt, aber ich wollte sicherstellen, dass er nicht wieder Seemannsgarn gesponnen hat.\n\nIch werde es kurz machen. Das mit Kielhols Mannschaft habt Ihr gut gemacht, aber ich erwarte, dass Ihr bei meiner noch besser seid. Ich muss mich um eine ganze Flotte kümmern, also werdet Ihr mir bei der täglichen Routine auf meinem Schiff helfen.\n\nWillkommen an Bord der Purpurschleier, Seemann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26645] = {title = "Die Nachtwache", objective = "Tötet 8 verrottende Schrecken nahe dem Spukhaus der blinden Mary, südöstlich von Dunkelhain.", description = "Ihr seid leider <der Einzige, der/die Einzige> die; mir hier helfen kann, <Name>. Die Streitkräfte Sturmwinds werden von weit größeren Gefahren bedroht. Sie können keinen einzigen Soldaten zum Schutz von Dunkelhain abstellen. Ich und die anderen aus der Nachtwache müssen uns um die Sicherheit unserer Heimat kümmern.\n\nLeider bedrohen uns nicht nur Wölfe. Verrottende Schrecken treiben nahe dem Spukhaus der blinden Mary am südöstlichen Stadtrand ihr Unwesen. Wenn wir sie nicht in Schach halten, werden sie in der Nacht unsere Häuser besuchen.\n\nKümmert Euch um die Untoten und meldet Euch bei mir, um belohnt zu werden.", progress = nil, completion = "Wunderbar, &lt;Name&gt;. Für Euren Dienst an den Einwohnern von Dunkelhain sollt Ihr entlohnt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26646] = {title = "Kriegsgefangene", objective = "Befreit die Kriegsgefangenen, die im Gefängnis von Renders Tal sitzen.", description = "Die Fernmeldeausrüstung der Bravo-Kompanie ist fertig, <Name>. Ich werde Euch damit ausrüsten. Ihr werdet Renders Tal, südöstlich von hier, betreten und unsere Kriegsgefangenen befreien. Ich gebe Euch Jorgensen mit. Er wird Euch den Rücken freihalten.\n\nDie Gefangenen sitzen im Nordosten des Tals in einem großen Käfig, aber der Schlüssel zu diesem Käfig befindet sich in einer Höhle im Süden des Tals. Ihr müsst den Schlüssel stehlen, für Ablenkung sorgen und die Bürger befreien.\n\nViel Glück, <Name>! Wir bleiben über den Fernmeldeapparat in Verbindung.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMarschgepäck der Kompanie Bravo\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26647] = {title = "Dicke Emma", objective = "Übt die Benutzung der Kanone, indem Ihr Timmy Grinsezweig mit 5 Kanonenkugeln von der Dicken Emma trefft.", description = "Wir haben viel Arbeit vor uns. Wie viel Erfahrung habt Ihr mit Kanonen? Hmm... wirklich? Und wie sieht es mit uralten, zusammenbrechenden Piratenkanonen aus?\n\nAuf den Decks gibt es noch ein paar Kanonen, die auf die altmodische Weise funktionieren: Man lädt immer nur eine Kanonenkugel, zielt, arretiert und feuert. Funktioniert gut, wenn man die Seite eines Dreimasters treffen will... nicht so gut bei Ruderbooten und ähnlichem.\n\nGeht doch mal nach oben und feuert ein paar Schuss auf Timmy Grinsezweig ab.", progress = nil, completion = "Mir gefällt Euer Stil, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26648] = {title = "Unsere Todfeinde", objective = "Tötet 15 Ninjas auf der Insel Jaguero.", description = "Hey, Neuling, seht Euch das mal an.\n\n<Der Zwerg hebt seine Augenklappe und enthüllt einen echten, funktionierenden Augapfel.>\n\nIch trage die Klappe nicht wegen eines verlorenen Auges. Ich trage sie, weil das ANDERE Auge so stark ist, dass es von dem normalen ausgebremst wurde.\n\nMit diesem Auge kann man alles Mögliche sehen, zum Beispiel die maskierten Schlägertypen, die uns folgen. Der Flottenmeister sagt, dass sie auf der Insel Jaguero aufgetaucht sind. Feuert diese Leuchtpistole ab, wenn Ihr dort eintrefft, und ich werde Euch helfen, sie auch zu sehen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Tödliches NaginataAnderaugenklappeSchultersütcke der ewigen SchlachtDer folgende Zauber wird auf euch gewirkt:\n\nOur Mortal Enemies: Cancel Dead-Eye Area Aura"}
MultiLanguageQuestData['de'][26649] = {title = "Schießbudenpiraterie", objective = "Sprecht mit dem Ruderer der Blutsegelbukaniere außerhalb der Purpurschleier und tötet dann 75 Ölarbeiter der Venture Co. mit der Kanone.", description = "Ihr wisst ja jetzt, wie man mit unseren Kanonen umgeht, also wird es Zeit, dass Ihr echte Ziele trefft!\n\nDie Venture Company hat nördlich von hier Gold gefunden... eine seltene Art, die sie \"schwarzes Gold\" nennen. Sieht für mich eher wie ein schwarzer Fleck aus.\n\nWir werden uns dieses Gold holen, aber zuerst müssen wir die Trottel der Venture Company los werden. Ein Ruderer wird Euch dort hinaus bringen. Verlasst das Schiff über die Laufplanke und sprecht mit ihm am Nordstrand der kleinen Insel.", progress = nil, completion = "Ahahaha! Ihr habt sie glatt aus ihrer Takelage gesprengt! Darauf trinke ich!\n\nVor Euch liegt eine große Zukunft, Grünschnabel.", rewards = "Rundschild des schwarzen GoldesBlaster der Venture Co.Schlüpfrige fingerlose HandschuheStahlauges SchulterschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26650] = {title = "Die \"Maid im Glück\"", objective = "Meldet Euch in Eurer Kapitänskajüte im Inneren der Maid im Glück am Schlingendornkap.", description = "Ich weiß ja, dass Ihr erst vor kurzem auf der Purpurschleier angekommen seid, aber ich könnte Euch für 'ne andere Aufgabe gebrauchen. Die Maid im Glück ist das dritte Schiff in meiner Flotte. Sie liegt östlich von hier. Ihr Skipper, Kapitän Stillwasser, weilt nicht mehr unter uns.\n\nVerdammt seien diese maskierten Strolche!\n\nIn jedem Fall hat mir Stahlauge von Euren Heldentaten auf See erzählt, und mir gehen langsam die qualifizierten Briganten aus. Ich denke, dass Ihr mehr als nur in der Lage sein werdet, Eure neuen Pflichten zu erfüllen.\n\nHerzlichen Glückwunsch, <Kumpel/Mädchen>. Ihr seid der neue Kapitän der Maid im Glück.", progress = nil, completion = "Ihr seht Pläne ausgerollt auf dem Tisch liegen. Sie erklären alles!\n\nDas sind Einzelheiten des bevorstehenden Angriffs auf Beutebucht. Kampfformationen, Angriffspläne und etwas über eine Gruppe, die \"Mannschaft der Trümmerflut\" heißt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26651] = {title = "Um einen Krieg zu gewinnen, müsst Ihr zum Krieg werden", objective = "Bringt mit der Fernmeldeausrüstung der Bravo-Kompanie je eine Zephyriumladung am Turm des Schwarzfels und an der Munitionshütte des Schwarzfels an.", description = "<Das Funkgerät der Kompanie Bravo piept.>\n\nVersteht Ihr es schon, <Name>? Wisst Ihr jetzt, was wir tun müssen, um einen Krieg gegen diese Ungeheuer zu gewinnen? IHR MÜSST ZUM KRIEG WERDEN! KEINE GNADE!\n\nDie Kriegsgefangenen sind befreit. Ihr könnt das Zephyrium anbringen. Betretet vorsichtig die Gebäude dort draußen und bringt je einen Sprengsatz an.\n\nBringt je eine Zephyriumladung an der Munitionshütte des Schwarzfels und am Turm des Schwarzfels an. Trefft Euch mit mir und dem Rest der Kompanie Bravo in der Schieferwindschlucht östlich von Renders Tal.", progress = nil, completion = "Und jetzt jagen wir das ganze verdammte Ding in die Luft.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMarschgepäck der Kompanie Bravo\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26652] = {title = "Geisterhaarfaden", objective = "Bringt den spektralen Kamm zur blinden Mary.", description = "Es gibt einen armen, traurigen Geist namens die blinde Mary, die in einem alten Farmhaus in den Hügeln südlich von Dunkelhain herumspukt.\n\nNehmt diesen spektralen Kamm und bittet die blinde Mary, ihr Haar damit zu kämmen. Bringt mir den Kamm. Ich werde das Geisterhaar darin auflesen, das ich für den Faden brauche.\n\nUnd seid vorsichtig, denn dunkle Wesen treiben sich nahe des Hauses herum...", progress = "<Schluchz> Oh bitte seht mich nicht an! Ich habe diese Augen mit meinen eigenen Händen herausgerissen, aber ich spüre immer noch Euren Blick!\n\nIch sehe entsetzlich aus! Entsetzlich! Bitte seht weg!!", completion = "Was ist das? Ein Kamm? Er ist wunderschön! Und er gleitet durch mein Haar, als wäre es gar nicht so furchtbar verfilzt und widerspenstig wie es ist.\n\nOh, hätte ich doch nur einen Spiegel...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26653] = {title = "Lieferung aus Dunkelhain", objective = "Sprecht mit Madame Eva in Dunkelhain.", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", progress = nil, completion = "So, Ihr braucht also Geisterhaarfaden, hm? Ich habe leider keinen mehr auf Lager, aber ich kann Euch welchen herstellen - wenn Ihr mir das Geisterhaar besorgt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26654] = {title = "Rückkehr mit dem Kamm", objective = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", progress = "Ich kann spüren, dass Ihr die blinde Mary getroffen habt. Habt Ihr auch meinen Kamm?", completion = "Damit kann ich eine Rolle Geisterhaarfaden herstellen und es bleiben sogar noch einige Haare übrig. Hier habt Ihr einige Münzen für diese zusätzlichen Haare.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26655] = {title = "Abliefern des Fadens", objective = "Bringt den Geisterhaarfaden zu Calvinius in seinem Turm im Bettlerschlupfwinkel.", description = "Hier ist Euer Faden, <Name>. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder leblose Dinge mit Leben erfüllen.", progress = "Ich brauche den Geisterhaarfaden, um ihn quer über meine Tür und meine Fenster zu spannen. Das hält unliebsame Geister fern. Habt Ihr ihn für mich besorgt?", completion = "Wunderbar! Das ist gerade richtig...\n\nHier, bitte, mein guter &lt;Name&gt;, nehmt dies als Bezahlung für Eure ehrenhafte Tat.", rewards = "Wams der TäuschungBettlergürtelZwei hinreißend verdorbene HandschuheAuf Euch wartet eine dieser Belohnungen:\n\nGeisterhaarband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26656] = {title = "Immer. In. Bewegung. Bleiben.", objective = "Hetzt mindestens 5 opalschimmernde Wächter nach Osten aus dem Bleichen Hort hinaus, zum Steinkreis in der Nähe von Therazanes Thron.", description = "Als Todesschwinge kam, sind die Steindrachen zu ihm geschwärmt. In seiner Abwesenheit fehlt ihnen jegliche Bestimmung. Sie streifen durch die Gegend und fressen unseresgleichen.\n\nIch habe Dutzende von opalschimmernden Wächtern gebunden, aber ich kann sie nicht aus der sicheren Deckung führen. Ich brauche jemanden, der schneller ist, und ich glaube, Ihr seid genau richtig für diese Aufgabe.\n\nFührt sie am Boden Richtung Therazanes Thron im Osten. Einige werden es sicher nicht schaffen, aber solange Ihr nicht stehenbleibt, solltet Ihr einige von ihnen zu unseren Truppen führen können.", progress = nil, completion = "Gut gemacht. Ich habe viele Stärken, aber Schnelligkeit gehört nicht dazu.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26657] = {title = "Ein harter Fall", objective = "Tötet 6 Steindrachen.", description = "Steindrachen lassen sich nur von Stärke beeindrucken. Wenn wir sie ausreichend bestraft haben, werden sie sich unserem Willen unterwerfen.\n\nIch habe eine Vielzahl meiner stärksten Riesen auf die Felder im Westen geschickt. Sie werden die Drachen zu Boden befördern. Ihr kümmert Euch dann darum, dass sie sich nach ihrem Fall nicht wieder in die Lüfte schwingen.", progress = nil, completion = "Offensichtlich nicht nur schnell. In Euch scheint Einiges zu stecken.\n\nGut gemacht, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26658] = {title = "Zerbrechliche Werte", objective = "Beschafft einen Mauerhammer.", description = "Jetzt ist es an der Zeit, die Aufmerksamkeit der Brutmutter zu erregen. Dazu benötigen wir einen Hammer, den die Troggs während der Opferzeremonie für sie benutzen.\n\nSucht die Bestienzähmer der Steintroggs, die im südlichen Teil des Bleichen Horts versuchen, Basilisken zu zähmen. Einer von ihnen trägt einen Hammer bei sich.", progress = "Konntet Ihr einen Hammer finden?", completion = "Wunderbar.\n\nJetzt werden wir den Steindrachen einen Schlag verpassen, den sie in den nächsten hundert Jahren nicht vergessen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26659] = {title = "Nachhallender Schlag", objective = "Besiegt Aeosera.", description = "Ihr werdet einen Resonanzkristall am westlichen Rand des Bleichen Horts finden. Schlagt mit dem Hammer darauf, dann wird die Brutmutter kommen.\n\nMacht Euch für einen Kampf bereit. Ich werde dort sein, um Euch zu helfen, aber sie wird sich nicht leicht geschlagen geben.", progress = "Diese Brutmutter nimmt die Steindrachen seit fast 300 Jahren unter ihre Fittiche. Sie ist recht stark, sogar für einen Steindrachen.", completion = "Beeindruckend, Fleischling. Ihr seid fähiger, als ich ursprünglich angenommen hatte.\n\nIch werde diese Einschätzung auch der Steinmutter übermitteln.", rewards = "Terraths felsige SchiftungSteinschuppenrobeDrachenzersägende KnochenklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26660] = {title = "Zombiesaft", objective = "Sprecht mit Schankwart Smitts.", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne \"Zum Roten Raben\" in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, <Name>. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", progress = nil, completion = "Ihr braucht etwas Zombiesaft, wie? Hmm, das Zeug ist ziemlich stark - ich werde nicht oft danach gefragt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26661] = {title = "Das Sammeln von Faulblüten", objective = "Sammelt 5 Fäulnisblüten auf dem Friedhof \"Stille Gärten\".", description = "Wenn Ihr mir einige Fäulnisblüten bringt, kann ich Zombiesaft für Euch brauen.\n\nFäulnisblüten wachsen an seltsamen Orten. Sie wachsen besonders gut auf Dingen, die tot sind. Im Dämmerwald gibt es jede Menge davon!\n\nIch habe einige im Friedhof \"Stille Gärten\" gesehen. Sucht in der Nähe der Gräber... aber achtet auf die Toten, die dort umherwandern.", progress = "Hallo, <Name>. Habt Ihr mir Fäulnisblüten gebracht?", completion = "Gut, Ihr habt die Fäulnisblüten gefunden.\n\nIch werde etwas Zombiesaft zubereiten... aber Vorsicht, das ist starkes Zeug.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26662] = {title = "Die Mannschaft der Trümmerflut", objective = "Sprecht mit Long John Copper auf der Maid im Glück, Shawn Stooker dem Koloss auf der Purpurschleier und der klagenden Mary Smitts auf der Springflut.", description = "Auf den Karten wird eine Gruppe namens Mannschaft der Trümmerflut erwähnt. Der Name ist Euch nicht bekannt, obwohl Ihr schon von einigen anderen neuen Bukanieren gehört habt.\n\nBesucht sie doch mal und findet heraus, was sie wissen.", progress = "Die Details sind eher spärlich. Wenn Ihr Informationen wollt, müsst Ihr andere Mitglieder der Mannschaft der Trümmerflut finden.", completion = "Die Mannschaft der Trümmerflut besteht nicht nur aus Piraten... sondern aus Piraten der Worgen! Und sie werden sich an dem Angriff beteiligen!\n\nRevilgaz wird das definitiv wissen wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26663] = {title = "Versenkung aus dem Inneren", objective = "Sabotiert das Fass mit Grog, das Fass mit Schießpulver und die Kiste mit Kanonenkugeln.", description = "Der Angriff auf Beutebucht steht kurz bevor. Kehrt rasch nach Beutebucht zurück und informiert den Baron.\n\nSo lange Ihr bei den Piraten noch angesehen seid, wäre es aber gut, wenn Ihr deren Vorräte sabotieren würdet. Die Piraten bewahren die meisten ihrer Vorräte unter Deck auf. Sie sind auf die ganze Flotte verteilt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26664] = {title = "Meutereimacher", objective = "Beschuldigt 9 Korsaren der Blutsegel der Meuterei und tötet sie dann.", description = "Bevor Ihr nach Beutebucht zurückkehrt, solltet Ihr alles tun, um die Blutsegelbukaniere zu schwächen. Leider ist es Euch selbst als Kapitän verboten, andere Bukaniere kaltblütig zu töten. Das darf nur ein Flottenmeister.\n\nAllerdings dürft Ihr Meuterer zu Tode bringen... und Meuterei lässt sich nur schwer widerlegen.\n\nApropos, diese Blutsegelkorsaren, die auf den untersten Decks der Schiffe herumhängen, benehmen sich in letzter Zeit wirklich sehr verdächtig...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Angeblicher StreitkolbenBezichtigender FingerMeutererschlingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26665] = {title = "Der Ruf der Beute", objective = "Meldet Euch bei Baron Revilgaz in Beutebucht am Schlingendornkap.", description = "Ihr habt den Eindruck, dass Ihr genug Schaden angerichtet habt. Ihr kennt außerdem die Schlachtpläne der Blutsegelbukaniere. Ihr habt alles getan, um das Euch Baron Revilgaz gebeten hat.\n\nEs ist Zeit, den Piratenhut an den Nagel zu hängen und nach Beutebucht zurückzukehren. Der Moment der Schlacht naht.", progress = nil, completion = "Die Trümmerflutler!? Ich dachte, die wären seit JAHREN tot und vergessen!\n\n&lt;Revilgaz hört angestrengt zu, während Ihr ihm die zusammengetragenen Informationen weitergebt.&gt;\n\nDas ergibt einen Sinn. Und es sind keine guten Neuigkeiten. Die Mannschaft der Trümmerflut sind ernstzunehmende Gegner und wenn sie wieder so viele sind, wie damals, als sie verschwanden, steht uns ein schwerer Kampf bevor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26666] = {title = "Die Legende von Stalvan", objective = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", description = "Ich bin hier, weil mein Bruder Stalvan, den ich seit Jahren nicht gesehen habe, mir einen Brief geschickt hat. Als ich hier eintraf, sagte man mir, er sei tot...\n\nDie ganze Stadt weigert sich, mir mehr zu erklären. Sie reagieren misstrauisch und ängstlich, wenn ich seinen Namen erwähne. Als ob ich mich nicht selbst schon so fühlen würde!\n\nIch habe Angst vor dem, was passieren könnte, wenn mein Ärger und mein Frust zunehmen. Bitte helft mir, der Sache auf den Grund zu gehen. Fragt Amtmann Daltry nach allen Informationen, die er über meinen Bruder besitzt.", progress = nil, completion = "Kann ich Euch helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26667] = {title = "Die gestohlenen Briefe", objective = "Findet das Bündel zerrissener Briefe in Schattenhain.", description = "Ihr wollt etwas über Stalvan wissen...\n\nIhr seid nicht <der/die> erste, wisst Ihr das? Fremde kommen ab und zu hier durch und fragen nach ihm. Immer nur Fremde. Alle, die hier leben, wissen es besser.\n\nWie dem auch sei, Ihr habt Pech. Die Hälfte meiner Archive ist weg. Wilde Worgen sind vor ein paar Nächten ins Rathaus eingebrochen und haben alles in Stücke gerissen. Die Dokumente, nach denen Ihr sucht, sind mittlerweile wahrscheinlich in ganz Schattenhain verstreut, tief in den Wäldern im Westen. Sind die Suche nicht wert, wenn Ihr mich fragt.", progress = "Ernsthaft, mein Herr, ich will keinen Ärger...", completion = "Beim Licht... Ihr habt sie tatsächlich geholt?\n\nIch bin schockiert. Ich sollte mich wohl bei Euch dafür bedanken, dass Ihr sie in die Archive zurückgebracht habt.", rewards = "Feuerzeug des ArchivarsKlippenholzklauenUmhang des BibliothekarsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26668] = {title = "Detonation", objective = "Sprengt Renders Tal in die Luft.", description = "Der Sprengstoff, den Ihr angebracht habt, ist hochexplosiv, <Name>. Wenn ich diesen Knopf an der Fernmeldeausrüstung der Bravo-Kompanie drücke, wird das ganze Tal in einem gigantischen Feuerball des Todes vergehen.\n\nWisst Ihr was? Ich glaube, die Ehre gebührt Euch. Die ganze harte Arbeit ist schließlich an Euch hängen geblieben.\n\nBereit?", progress = nil, completion = "Habt Ihr gesehen, wie die Orcs explodiert sind? SO MACHEN WIR DAS IN DER KOMPANIE BRAVO! Lasst uns mit dem Rest dieser Clowns aufräumen.", rewards = "Messners ManschettenVernichterarmbänderRotkammbeinschützerMassive Schusswaffe des TodesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26669] = {title = "In einer dunklen Ecke", objective = "Durchsucht den Verrottenden Obstgarten nach der zerrissenen Tagebuchseite.", description = "Wenn es Euch wirklich ernst ist, helfe ich Euch, <Name>. Ich weiß, wo die anderen Dokumente sein müssen. Ich habe zu viel Angst, um etwas zu unternehmen.\n\nEs gibt nur wenige Orte, an denen sich diese furchtbaren Schrecken der Nacht versammeln, wenn sie nicht gerade den Wald durchstreifen. Einer davon ist der Verrottende Obstgarten im Süden. Sie benutzen die Gebäude als Schlupfwinkel. Wenn sie die Dokumente nicht einfach gefressen haben, werdet Ihr sie wahrscheinlich dort finden... aber ich wette, dass Ihr ihre Verstecke gründlich durchsuchen müsst.", progress = "Ihr seid in einem Stück zurückgekommen, wie ich sehe.", completion = "Mehr habt Ihr nicht gefunden?\n\nDas sind schlechte Nachrichten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26670] = {title = "Rolands Verdammnis", objective = "Sucht in Rolands Verdammnis nach den restlichen Seiten von Stalvans Tagebuch.", description = "Das ist nicht alles...\n\nLasst es sein, <Name>. Eure Suche kann Euch nur noch nach Rolands Verdammnis führen. Das ist eine Mine südlich der Stadt und der größte Worgenbau in ganz Dämmerwald. Niemand in Dunkelhain hat diesen Ort je lebend verlassen. Einige der Berichte, die ich hier habe, weisen daraufhin, dass diese Ungeheuer dort ihren Ursprung haben... wer weiß, welches Böse sich darin verbirgt?\n\nBitte gebt auf, <Name>. Lasst uns die ganze Sache vergessen und nie wieder davon sprechen.", progress = "Ich sagte Euch doch, <Name>, dass sich die Suche nicht lohnt...", completion = "Was, Ihr habt sie geholt?!\n\nIch weiß nicht, ob ihr mutig oder verrückt seid. Im Namen meiner Archive danke ich Euch jedoch erneut.", rewards = "ExorzistenstabDaltrys GürtelRolands BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26671] = {title = "Das Schicksal von Stalvan Dunstmantel", objective = "Bringt die Legende von Stalvan zurück zu Tobias Dunstmantel.", description = "Ihr habt alles gefunden. Alles, bis auf die letzte Seite...\n\n...die ich hier habe. Seht mich nicht so an. Ihr werdet alles verstehen, wenn Ihr sie gelesen habt. Einige behaupten sogar, sie sei verflucht. Um ehrlich zu sein, war ich erleichtert, als die Worgen eingebrochen sind und die Seiten gestohlen haben!\n\nNehmt sie. Ach nein, nehmt alle. Ich danke Euch dafür, dass Ihr meine Archive wiederbeschafft habt, aber ich will nichts mehr mit der Sache zu tun haben. Lasst mich bitte in Ruhe.", progress = "Ihr seid wieder da! Habt Ihr etwas über meinen Bruder herausgefunden?", completion = "Ich kann Euch gar nicht genug danken... Ich hatte auf ein freudiges Wiedersehen gehofft, aber je mehr ich erfahre, desto sehnlicher wünsche ich mir, ich hätte nie gefragt.\n\nAber ich muss es wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26672] = {title = "Der Wahrheit auf den Grund gehen", objective = "Bringt Madame Eva den Familienring der Dunstmantels.", description = "Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...\n\n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.>\n\nIch brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.\n\nIch muss wissen, warum...\n\nNehmt meinen Ring, <Name>. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.", progress = "Welche dunklen Stimmen haben Euch an meine Tür gebracht, <Klasse>?", completion = "Wie interessant. Es ist lange her, dass ich einen solchen Ring gesehen habe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26673] = {title = "REUSE - BREADCRUMB#", objective = "Bringt Madama Eva den Familienring der Dunstmantels.", description = "Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...\n\n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.> Ich brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.\n\nIch muss wissen, warum...\n\nNehmt meinen Ring, <Name>. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26674] = {title = "Dunstmantels Rache", objective = "Benutzt den Familienring der Dunstmantels im Anwesen der Dunstmantels östlich der Stadt.", description = "Leider kann ich Tobias nicht die Antworten geben, nach denen er sucht. Aber ich kann Euch bei der Suche nach der einzigen Person helfen, die das vermag...\n\nStalvan Dunstmantel.\n\nBringt den Ring zum Anwesen der Dunstmantels in den Wäldern im Osten, wo Stalvans Leiche begraben wurde. Tretet ein und haltet den Ring hoch. Wenn das Licht des abnehmenden Mondes durch den Ring scheint, werden die Geister Euren Ruf erhören.\n\nVergesst eines nicht, <Name>. Die Fragen der Lebenden spenden oft mehr Trost als die Antworten der Toten.", progress = nil, completion = "Meister Harris hatte vielleicht sogar recht. Es wäre besser gewesen, wenn ich die Vergangenheit hinter mir gelassen hätte.\n\nIch habe jetzt ein neues Leben. Ob es das eines Ungeheuers oder das eines Mannes ist, hängt von mir ab.\n\nEuch kann ich nicht genug für Eure Unterstützung danken, egal, zu welchem Ergebnis sie geführt hat. Bitte nehmt dies zusammen mit meinem Dank.", rewards = "Stalvans UmhangPantoffeln des SichelmondesArmschienen der verlassenen GeisterBürde der SchamIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26675] = {title = "Der Wert des Vertrauens", objective = "Die Probleme dieser Welt scheinen nie zu vergehen. Sie verschieben und verändern sich, bilden sich neu, aber sind doch stets vorhanden.\n\nDer Wind hat uns Gerüchte über einen Verräter in unserer Mitte zugeflüstert. Wir haben eine unserer besten Schildwachen mit den Nachforschungen betraut, doch sie wurde tot aufgefunden. Ich habe das zu verantworten, da ich annahm, der Verräter wisse nichts von unserem Vorgehen... Ich handelte unüberlegt, und sie musste den Preis für meine Dummheit bezahlen.\n\nIch brauche ein fremdes Gesicht, um die Spur wieder aufzunehmen. Jemanden, den die Leute in der Stadt nicht kennen. Das ist eine gefährliche Bitte. Werdet Ihr mir helfen?", description = "Die Probleme dieser Welt scheinen nie zu vergehen. Sie verschieben und verändern sich, bilden sich neu, aber sind doch stets vorhanden.\n\nDer Wind hat uns Gerüchte über einen Verräter in unserer Mitte zugeflüstert. Wir haben eine unserer besten Schildwachen mit den Nachforschungen betraut, doch sie wurde tot aufgefunden. Ich habe das zu verantworten, da ich annahm, der Verräter wisse nichts von unserem Vorgehen... Ich handelte unüberlegt, und sie musste den Preis für meine Dummheit bezahlen.\n\nIch brauche ein fremdes Gesicht, um die Spur wieder aufzunehmen. Jemanden, den die Leute in der Stadt nicht kennen. Das ist eine gefährliche Bitte. Werdet Ihr mir helfen?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][26676] = {title = "Saftlieferung", objective = "Bringt Calvinius den Zombiesaft im Bettlerschlupfwinkel.", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", progress = "Ich brauche den Zombiesaft, um mich in diesen dunklen, kalten Nächten warm zu halten. Habt Ihr ihn für mich besorgt?", completion = "Seid tausendmal bedankt, &lt;Name&gt;! Ihr erwärmt das Herz eines alten Mannes mit Eurer Naiv... ääh... mit Eurer Freundlichkeit!\n\nHier, bitte schön, mein Freund, nehmt dies als ein Zeichen meiner Dankbarkeit.", rewards = "Calvinius' HandschuheBeinwärmer des alten MannesAuf Euch wartet eine dieser Belohnungen:\n\nRing des Narren\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26677] = {title = "Ein Ghulbildnis", objective = "Sammelt 7 Ghulrippen von Stinkenden Leichnamen auf dem Anwesen der Dunstmantels.", description = "Es ist ein Wunder, dass die lebenden Toten mich hier draußen am Stadtrand noch nicht gefressen haben! Erst gestern hat eine Horde Ghule beinahe die Wände meines Turms eingeschlagen!\n\nIch möchte ein Abbild herstellen - eine Art \"Vogelscheuche\" für Ghule. Dafür benötige ich einige Ghulrippen. Rund um das Anwesen der Dunstmantels, nördlich von Dunkelhain, wandern stinkende Leichname umher, bei denen ihr jede Menge finden solltet...\n\nBesorgt mir die Rippen, dann werde ich Euch mit einigen Münzen belohnen.", progress = "Wahrscheinlich würdet Ihr auch zahlreiche Rippen in Rabenflucht finden, aber wer will schon spät nachts so weit laufen...", completion = "Ah, danke! Die sind genau richtig für mein Vorhaben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26678] = {title = "Doppelrum", objective = "Findet Baron Revilgaz' Fass mit Doppelrum in Beutebucht.", description = "<Baron Revilgaz seufzt.> Ich habe zwar Teile von Firallons Plan erahnt, aber trotzdem sind wir nicht auf die beiden Frontalangriffe der Blutsegel und der Trümmerflut vorbereitet. Wir werden ein kleines Wunder brauchen, um Beutebucht an diesem Tag zu halten.\n\nIch habe ein Fass Doppelrum in meinem Quartier. Steigt die Treppe drei Stockwerke hinunter und nehmt die erste Tür zu Eurer Rechten. Ihr könnt die Warnungen auf dem Fass ignorieren... sie sollten Eure geringste Sorge sein.", progress = nil, completion = "Das muss der Doppelrum sein. Ihr schenkt Revilgaz ein Glas ein und überlegt, ob Ihr Euch auch eins gönnen sollt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDoublerum: Apply Phase Aura with Boom\n\nIhr bekommt:\n\nDoppelrum"}
MultiLanguageQuestData['de'][26679] = {title = "Kehrt zu Revilgaz zurück", objective = "Bringt Baron Revilgaz in Beutebucht den Doppelrum.", description = "Draußen geschieht etwas. Sind die Blutsegelbukaniere etwa schon hier?\n\nBringt Revilgaz seinen Doppelrum. Schnell.", progress = "Ratet mal, wer aufgetaucht ist, während Ihr weg wart?", completion = "&lt;Der Baron leert rasch seinen Kelch.&gt;\n\nAH! Das tut gut, &lt;Name&gt;. Aber zurück zum Geschäft. Ich glaube, dass Ihr und ich eine Stadt zu retten haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26680] = {title = "Ogerdiebe", objective = "Bringt Calvinius' Kiste zu Calvinius.", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, <Name>, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", progress = "Habt Ihr meine Kiste? Wenn ja, dann gebt sie mir schnell, ich bitte Euch!", completion = "Dank dem Toten- ähm, ich danke EUCH, &lt;Name&gt;! Ihr habt Euch Eure Belohnung mehr als verdient.\n\nAha! Oh Glück! Glückliche Nächte können kommen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26681] = {title = "Ein Brief für den Bürgermeister", objective = "Bringt Calvinius' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.", description = "Bringt diese Nachricht zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", progress = "Ein Brief? Worum geht es bei dieser Geschichte?", completion = "&lt;Ello sieht sich den Brief an und sein Gesicht verliert augenblicklich alle Farbe.&gt;\n\nIhr Narr! Ihr habt uns alle verdammt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26682] = {title = "Eine torkelnde Bedrohung", objective = "Tötet 7 Moderrankenkrabbler oder Moderrankenwüteriche im Sumpf nördlich von Brackenwall.", description = "Düstermarschen ist das Gebiet der Horde, <Name>. Die Menschen haben ihre kleine Insel und ihre heißgeliebte Sandbank, aber die Sümpfe gehören uns.\n\nIrgendwann werden wir diese Pattsituation mit den Menschen auch noch klären. Doch erst einmal müssen wir unser eigenes Gebiet beherrschen. Die Moderrankenmorastbestien im Norden tauchen aus dem Sumpf auf und greifen jedes Lebewesen an, das sich ihnen nähert. Wenn wir diese Marschen beherrschen wollen, dann darf sich unser Land nicht gegen uns wenden!\n\nTötet die Morastbestien, wenn Ihr der Horde dienen wollt. Man wird Euch belohnen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Nun können wir uns hier auf die größeren Bedrohungen konzentrieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26683] = {title = "Seht zu den Sternen", objective = "Findet Mary und überredet sie, eine reflektierende Oberfläche für Viktoris Projekt abzugeben.", description = "Mein Gnomenfreund Zinken hat versprochen, mir beim Bau eines Geräts zu helfen, mit dem man zu den Sternen blicken kann. Laut Zinkens Blaupause muss ich zuerst eine Möglichkeit finden, das Licht zu reflektieren.\n\nIch erinnere mich an eine Frau namens Mary, die in dieser Gegend rasch bekannt wurde, weil sie stets einen Handspiegel bei sich trug. Könntet Ihr vielleicht Mary suchen und sie fragen, ob sie uns eine reflektierende Oberfläche für dieses Projekt leihen würde? Ich glaube, sie lebte früher im südlichen Dämmerwald...", progress = nil, completion = "Ja, das stimmt. Ich besaß einmal einen Spiegel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26684] = {title = "Der irrsinnige Ghul", objective = "Erbeutet Marys Handspiegel von dem irrsinnigen Ghul.", description = "Der Handspiegel war einer meiner wertvollsten Schätze, bis... zu dem Zwischenfall. Danach warf ich ihn hinter die Scheune. Dort hinten trieb ein irrsinniger Ghul sein Unwesen. Vielleicht hat er ihn aufgehoben. Angeblich halten sich diese teuflischen Bestien im Friedhof \"Stille Gärten\" auf.", progress = "Ich habe Zinken die Anfänge unserer Sternenguckermaschine gezeigt. Er war beeindruckt. Habt Ihr ein reflektierendes Gerät gefunden?", completion = "Wie wunderbar! Das wird sehr gut funktionieren. Vielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26685] = {title = "Feines Glas", objective = "Tötet Zzarc'Vul auf dem südlichen Ogerhügel in Dämmerwald und erbeutet sein Ogermonokel.", description = "Jetzt brauche ich nur noch einen Gegenstand, dann ist das Gerät komplett. Laut Zinkens Blaupause fehlt eine Art Linse. Die einzige Linse, die ich kenne und die groß genug wäre, wird nur schwer zu beschaffen sein.\n\nEs gibt einen Oger namens Zzarc'Vul, der auf dem Hügel im südlichen Dämmerwald lebt. Wenn es Euch gelingen würde, mir sein Monokel zu bringen, könnte ich das als Linse verwenden!", progress = "Konntet Ihr Zzarc'Vul davon überzeugen, uns sein Monokel für unser Experiment zu leihen?", completion = "Endlich! Die Sternenguckermaschine ist komplett! Danke, &lt;Name&gt;. Jetzt kann ich meine Forschungen fortsetzen...", rewards = "Pantalons des SternguckersHandlappen des AstronomenAuf Euch wartet eine dieser Belohnungen:\n\nSternenbedecktes Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26686] = {title = "Wandelnde Knochen", objective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass ihr 5 Skelettkrieger und 5 Skelettmagier vernichtet.", description = "Ihr werdet Euch mit noch fauligeren Untoten herumschlagen müssen, <Name>.\n\nDer Friedhof \"Stille Gärten\" etwas weiter südlich der Stadt ist ein Ort, an dem man sich nachts nicht blicken lassen sollte. Die Knochen, die sich dort aus dem Boden erheben, sind klug genug, um sich daran zu erinnern, wie man eine Axt schwingt oder einen Zauber wirkt.\n\nIch muss wohl nicht erklären, wie gefährlich sie das macht. Seid vorsichtig, aber denkt daran, dass das Volk von Dunkelhain leiden wird, wenn Ihr scheitert.", progress = nil, completion = "Das Volk von Dunkelhain dankt Euch, &lt;Name&gt;. Ihr habt Euch als starker Verbündeter der Nachtwache erwiesen.", rewards = "Schulterwickel der EhreBrustplatte des WachhauptmannsAuf Euch wartet eine dieser Belohnungen:\n\nSignet der Nachtwache\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26687] = {title = "Verstärkung aus Theramore", objective = "Reist zur Insel Theramore in den Düstermarschen und sprecht mit Hauptmann Garran Mumm in der Hauptkaserne.", description = "Hawthorne tot... mein eigener Sohn ermordet... die Lage im Brachland ist außer Kontrolle, <Name>.\n\nIch werde das Kommando über die Triumphfeste übernehmen und versuchen, für Ruhe zu sorgen. Doch dazu benötige ich Verstärkung. Verstärkung, die man mir in Theramore schon vor Wochen versprochen hat!\n\nReist nach Theramore in den Düstermarschen und blast Hauptmann Garran Mumm den Marsch. Welchen Zweck erfüllt diese verdammte Straße durch den Sumpf, wenn Soldaten und Material trotzdem nicht kommen?", progress = nil, completion = "Was jetzt, Soldat?\n\nVerstärkung? Für das Brachland? Seit Monaten stecken wir Soldaten und Vorräte dort hinein!\n\nMuss jemand Doppelzopf an den Angriff auf Nordwache erinnern? Unsere Verluste an der Ehrenwacht? Was ist mit den Soldaten geschehen, die ich zur Triumphfeste geschickt habe? Wir können niemanden mehr entbehren!\n\n&lt;Name&gt;, wenn Ihr uns wirklich helfen wollt, dann konzentriert Euch auf die Lage hier in den Düstermarschen. Wir schlagen uns mit Deserteuren und den Übergriffen der Horde herum... wir können Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26688] = {title = "Worgen in den Wäldern", objective = "Tötet 7 Worgen der Nachtheuler im Schattenhain.", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Treuwein hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Treuwein an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Worgen der Nachtheuler im Schattenhain. Wir werden sehen, ob Ihr in der Lage seid, es mit diesen Monstern aufzunehmen.", progress = nil, completion = "Ich bin beeindruckt, &lt;Name&gt;. Es scheint, als wäret Ihr durchaus fähig, Euch im Kampf zu behaupten. Vielleicht können wir ja eine Aufgabe für Euch finden, die jemanden mit Euren Fähigkeiten etwas mehr herausfordert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26689] = {title = "Der Verrottende Obstgarten", objective = "Tötet 10 Schattenwirker der Nachtheuler im Verrottenden Obstgarten.", description = "Die Worgenplage erstreckt sich über Schattenhain hinaus. Im Süden, ganz am Rand von Dunkelhain, liegt der Verrottende Obstgarten. Dort findet man noch wildere Bestien.\n\nDie Worgen dort sind listiger, <Name>, aber ebenso grausam und böse. Sie beschwören verdorbene Schatten, die ihre Feinde aus der Entfernung in Stücke reißen. Geht zum Verrottenden Obstgarten und tötet die Schattenwirker, um die Stadt zu beschützen!", progress = nil, completion = "Ihr habt Euch gut gegen die Schattenwirker geschlagen, &lt;Name&gt;. Doch selbst heutzutage, Jahre nach ihrem ersten Auftauchen, scheint es mehr als genug zu geben, um die von uns Getöteten zu ersetzen.\n\nIch setze all meine Hoffnung auf Meister Carevin. Er wird dem Problem sicherlich auf den Grund gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26690] = {title = "Faulig und besudelt", objective = "Tötet 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler in Rolands Verdammnis.", description = "Eure früheren Leistungen haben mich davon überzeugt, dass Ihr Euch den härtesten Worgen stellen solltet, die diese Wälder heimsuchen.\n\nDie Faulreißer und die Besudelten haben sich als die gefährlichsten der Worgen, die hier eine neue Heimat gefunden haben, erwiesen. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nSchon aus der Ferne kann man das Licht ihrer Lagerfeuer sehen...", progress = nil, completion = "&lt;Name&gt;, um ehrlich zu sein, hatte ich nicht damit gerechnet, dass Ihr so weit kommen würdet, aber Ihr seid offensichtlich ein &lt;Klasse&gt;, den man im Auge behalten sollte. Solltet Ihr Euch also auch offiziell Meister Treuweins Kampf anschließen wollen, werde ich Euch gern ein Empfehlungsschreiben aufsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26691] = {title = "Worgen in den Wäldern", objective = "Bringt Calors Notiz zu Jonathan Treuwein.", description = "Bitte sehr, <Name>. Bringt diese Nachricht zu Meister Treuwein.\n\n<Er zieht rasch ein Stück verblichenes Pergament hervor und reicht es Euch.>\n\nWenn es nur noch mehr wie Euch gäbe, dann wären wir bald zahlreicher als die Nachtwache! Vielleicht könnten wir dann das Werk vollenden, das wir wenigen begonnen haben.", progress = "Ja, was ist? Beeilt Euch, ich habe dringende Aufgaben.", completion = "Entschuldigt den frostigen Empfang, &lt;Name&gt;, aber Euch ist sicher klar, dass ich ein äußerst vielbeschäftigter Mann bin. Wie ich sehe, habt Ihr Calor so sehr beeindruckt - und ich kann Euch versichern, dass das nicht oft vorkommt - dass er Euch empfohlen hat.\n\nEs sind einige abstoßende Gestalten unterwegs, &lt;Name&gt;, und ich kann die Hilfe von allen gebrauchen, die sich bewiesen haben. Wir kämpfen gegen Dämonen, die Untoten und alle, die ihnen helfen. Seid wachsam, seid vorsichtig und vertraut niemandem, der unseren Kampf nicht unterstützt.\n\nRuhm unter dem Licht.", rewards = "Handschuhe der SelbstjustizKalte StiefelTreuweins BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26692] = {title = "Ausrottung der Schattenfelle", objective = "Tötet 20 beliebige Gnolle der Schattenfelle.", description = "Da von den Schwarzfelsorcs südlich vom Immerruhsee nichts außer Asche und Kohle übrig geblieben ist, können wir unsere Aufmerksamkeit auf die Armee der Schattenfellgnolle im Galardelltal unmittelbar nördlich von hier richten.\n\nGeht hinaus und bringt sie alle um, <Name>! Beginnt mit der Operation: Ausrottung, Soldat. Für die Kompanie Bravo und für die Allianz!", progress = nil, completion = "&lt;Danforths Stimme erklingt aus dem Marschgepäck der Kompanie Bravo.&gt;\n\nHallo? Ist das Ding an?\n\n&lt;Im Hintergrund könnt Ihr Keeshans Stimme hören und einige gedämpfte Kratzgeräusche, während sie das Signal justieren.&gt;\n\nJetzt haben wir's. Gute Arbeit, &lt;Name&gt;. Wir rücken auf das Oberkommando des Schwarzfels vor. Für diese Hunde gibt es keinen Ausweg mehr.", rewards = "SchattenfellstiefelDanforths BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26693] = {title = "Der dunkle Turm", objective = "Erbeutet den Schlüssel von Ilgalar.", description = "Wir hatten Glück. Die Bewohner dieses Tals haben uns wichtige Informationen gegeben. Die beiden hinter uns, die Ranthals, haben mir berichtet, dass die Gnolle im Galardelltal von einem mächtigen Magus im Turm von Ilgalar kontrolliert werden. Das Problem ist, dass dieser Turm durch ein magisches Kraftfeld versiegelt wird.\n\nAls erstes brauchen wir den Schlüssel, damit Ihr ins Innere vorstoßen könnt. Fangor, der Gnollgeneral, besitzt Eure Fahrkarte ins Innere. Tötet General Fangor und holt Euch den Schlüssel.\n\nIch melde mich.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26694] = {title = "Der Großmagus Doane", objective = "Tötet Großmagus Doane.", description = "<Die Fernmeldeausrüstung der Bravo-Kompanie vibriert.>\n\nGute Arbeit, Grünschnabel. Ich habe wichtige Informationen für Euch. Der Magus in dem Turm ist ein Mensch namens Doane. Der verdammte Verräter arbeitet für die Schwarzfelsorcs. Ich will seinen Tod.\n\nVerschafft Euch mit dem Schlüssel von Ilgalar einen Weg ins Innere des Turms. Arbeitet Euch bis zur Spitze vor und zeigt Doane, was die Kompanie Bravo mit Verrätern macht.\n\nKehrt zum Treffpunkt Schieferwindschlucht zurück, wenn die Tat vollbracht ist.\n\nKeeshan Ende und aus.", progress = nil, completion = "Er hat sich wegteleportiert? Und Dunkelflamme erwähnt? Was zur Hölle geht hier vor?\n\nLasst uns aufsitzen und diesen Unfug zu Ende bringen.", rewards = "Verräterische TreterSchieferwindgürtelDer folgende Zauber wird auf euch gewirkt:\n\nDetect: Quest Invis Zone 16\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26695] = {title = "Startvorbereitungen", objective = "Besorgt Narkks Handbomben aus der Alten Hafenbehörde in Beutebucht.", description = "Ich habe eine Idee, die etwas Laufarbeit von Euch erfordert. Die Schwarzmeerräuber sind ein Kartell der Goblins. Deshalb haben sie Zugang zu jeder Menge Sprengstoff. Ich weiß sogar, dass unser alter Freund Narkk eine ganze Kiste hinten in seinem Laden in der Alten Hafenbehörde aufbewahrt.\n\nHolt sie Euch und bringt sie her, wenn sie noch nicht hochgegangen ist.", progress = "Ihr lebt noch?", completion = "Ihr habt sie dabei! Ich glaube, so langsam dreht sich der Wind zu unserem Vorteil, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26696] = {title = "Der Ruf von Kalimdor", objective = "Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.", description = "Sagt mal, Ihr habt nicht zufällig einen etwa so großen Fisch gesehen? Kurze Flossen? Hört auf den Namen Steve?\n\nEgal, ich such' einfach weiter.\n\nAber... es gibt einen anderen Grund, aus dem ich nach Beutebucht gekommen bin. Boss Krog, drüben in den Düstermarschen, sucht neue Arbeiter.\n\nWartet am Ende des Piers auf das nächste Schiff, dann fahrt nach Ratschet. Gazlowe sollte Euch von da aus weiterhelfen können.\n\nSteve? Steve!", progress = nil, completion = "Ja, Was kann ich für Euch tun?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26697] = {title = "Die letzte Reise der Trümmerflutpiraten", objective = "Sprecht mit Kebok in Beutebucht und schwingt Euch auf einen tapferen Windreiter. Tötet dann mit den Handbomben 85 Crewmitglieder der Trümmerflutpiraten und zerstört 6 Landungsboote der Trümmerflutpiraten.", description = "Wir werden diesen Angriff nicht überstehen, wenn all diese Worgenpiraten von Norden in den Hafen einfallen. Zum Glück sieht es so aus, als wären sie nicht mit Kanonen bewaffnet. Wenn es uns gelingt, Euch aus dem Hafen zu bringen, könnt Ihr sie aus der Luft angreifen.\n\nIhr findet Kebok, den Assistenten des Windreitermeisters der Horde, gleich um die Ecke. Erklärt ihm, dass Ihr seinen mutigsten Windreiter benötigt.\n\nNehmt all die Handbomben mit, die Ihr tragen könnt. Ihr werdet sie brauchen, um die Landungsboote aufzuhalten!", progress = nil, completion = "Ich hoffe, diese räudigen Hunde können schwimmen!\n\nMoment, das nehme ich zurück.", rewards = "BastardschießerBaton des BaronsAuf Euch wartet eine dieser Belohnungen:\n\nGeschenk des Flugmeisters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26698] = {title = "Auf der Suche nach Seehorn", objective = "Meldet Euch bei Flottenmeister Seehorn in Beutebucht.", description = "Als die Trümmerflutpiraten ankamen, griff Seehorn nach der ersten Waffe, die er in die Hände bekam und sprang von diesem Vorsprung. Ihr werdet ihn da unten finden. Wahrscheinlich schlägt er ein paar neue Löcher in diese Worgenschädel.\n\nHelft ihm. Um die Motivation kümmere ich mich von hier oben.", progress = nil, completion = "Ich hätte wissen sollen, dass die Trümmerflutpiraten noch leben und nichts Gutes im Schilde führen. Ich hatte sie schon vor Jahren abgeschrieben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26699] = {title = "Die Abwehr der Trümmerflutpiraten", objective = "Tötet 10 Räuber der Trümmerflutpiraten in Beutebucht.", description = "Die Trümmerflutpiraten sind überall! Die Haudraufs von Beutebucht, die der Baron angeworben hat, haben einer solchen Überzahl nichts entgegen zu setzen.\n\nWährend Ihr dort unten seid, könntet ihr mir helfen, ein paar von ihnen los zu werden?\n\nWenn Ihr fertig seid, macht Euch nicht die Mühe wieder heraufzukommen. Ich werde wahrscheinlich ziemlich beschäftigt sein.", progress = nil, completion = "Wir dürfen nicht nachlassen, &lt;Name&gt;. Wir können Beutebucht nicht viel länger halten.", rewards = "Revilgaz' EntersäbelZerschrammte WesteDreister UmhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26700] = {title = "Die Maid im (Un)Glück", objective = "Tötet 8 Korsaren der Blutsegelbukaniere in Beutebucht.", description = "Ich habe gehört, dass dieses Schiff hier Die Maid im Glück heißt. Wart Ihr nicht mal der Kapitän von diesem Kahn? Dann kennt Ihr Euch dort ja aus.\n\nDie Trümmerflutpiraten sind unsere Hauptsorge, aber wir können auch nicht einfach zusehen, während wir mit diesen Kanonen beschossen werden. Ergreift das Seil hinter mir und erledigt ein paar dieser wütend aussehenden Korsaren. Meldet Euch beim Baron, wenn Ihr fertig seid.", progress = nil, completion = "Ein Angriff auf Eure ehemalige Besatzung...\n\nIhr seid wirklich ein echter Pirat geworden, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26701] = {title = "Flug nach Brackenwall", objective = "Sprecht mit Bragok in Ratschet, um nach Brackenwall zu fliegen. Meldet Euch dann bei Krog.", description = "Hört mal, die Horde liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.\n\nEuer Gold ist so gut wie das jedes Anderen.\n\nDieser zweiköpfige Oger und sein Fisch haben etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Krog. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.", progress = nil, completion = "Lok'tar, &lt;Volk&gt;. Willkommen in Brackenwall.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26702] = {title = "Flug nach Theramore", objective = "Sprecht mit Bragok in Ratchet, um nach Theramore zu fliegen. Meldet Euch dann bei Calia Hastings.", description = "Hört mal, die Allianz liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.\n\nEuer Gold ist so gut wie das jedes Anderen. Manchmal besser.\n\nJeyne hat etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Calia Hastings. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.", progress = nil, completion = "Willkommen in Theramore.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26703] = {title = "Streicht die Blutsegel", objective = "Sprecht mit Kebok in Beutebucht, lasst Euch einen Windreiter geben und tötet Flottenmeister Firallon.", description = "Dass der Sieg zum Greifen nah ist, haben wir fast allein Euch zu verdanken. Es bleibt jedoch noch eine letzte Aufgabe... tötet Flottenmeister Firallon.\n\nEin Großteil von Firallons Mannschaft scheint bereits tot zu sein, aber ich kenne den alten Seebären nur zu gut. Er ist noch nicht erledigt. Nein, er hat sich bestimmt in seiner Kajüte verbarrikadiert, um mit seinem Schiff unterzugehen.\n\nSprecht noch einmal mit Kebok. Er wird Euch einen Windreiter geben. Ich versuche den Kanonenbeschuss zu unterbrechen, während Ihr an Bord seid.", progress = nil, completion = "&lt;Name&gt;! Ihr seid wach! Wir haben Euch, kurz nachdem die letzten Angreifer den Schwanz eingezogen haben, im Hafen treiben sehen. Ihr habt uns eine Weile lang Sorgen gemacht...\n\nIch wollte mich noch bei Euch bedanken, &lt;Name&gt;. Ihr habt uns die Informationen verschafft, die wir brauchten, um uns auf diesen Angriff vorzubereiten und uns geholfen, nicht nur die Blutsegelbukaniere, sondern AUCH die Trümmerflutpiraten abzuwehren. Wir in Beutebucht werden uns stets an Euren Namen erinnern.\n\nWir sind sehr stolz auf unsere Beute. Wollt Ihr die erste Wahl haben?", rewards = "Pantalons aus BeutebuchtHelm aus BeutebuchtAuf Euch wartet eine dieser Belohnungen:\n\nAnhänger aus Beutebucht\n\nIhr bekommt außerdem:\n\nStern des Schlingendorntals"}
MultiLanguageQuestData['de'][26704] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][26706] = {title = "Endspiel", objective = "Springt auf einen Hippogryphen, wenn Tobias Euch das Zeichen dazu gibt, und zerstört das Kanonenboot der Horde.", description = "Wir müssen dieses fliegende Kanonenboot loswerden, wenn unser Volk eine Chance auf Flucht haben möchte.\n\nSo lautet der Plan. In Kielwasser trieben sich früher einige sympathisierende Rebellen herum. Ich konnte eine beträchtliche Menge Sprengstoff aus einem unserer Lager besorgen.\n\nWir werden den Feind mit einer Kraft überrumpeln, die so klein ist, dass sie sich unentdeckt durch die Luft bewegen kann. Die Hippogryphen der Nachtelfen eignen sich perfekt dafür.\n\nTobias gibt Euch das Signal, wenn wir bereit sind.", progress = "Es lohnt sich nur Risiken einzugehen, die Siege bringen, die es sich zu erringen lohnt.", completion = "Wir haben es geschafft, &lt;Name&gt;. Wir haben die Evakuierung in die Wege geleitet. Wenn wir uns bald auf den Weg machen, sieht die Flotte der Verlassenen bald nur noch eine Staubwolke von uns.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGilneas Quest Invisibility Detection - 10 min - 10 [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26707] = {title = "Eine tödliche Rebe", objective = "Sammelt 5 Stück Leichengras.", description = "Ich brauche jede Menge Leichengras für Meister Harris' Gebräu. Es ist schwer zu kriegen, aber unsere Vorräte dürfen nicht abnehmen. Leichengras ist ziemlich hartes Zeug...\n\nDie Pflanze macht Euch fertig, wenn Ihr nicht aufpasst! Aber wenn Ihr trotzdem helfen wollt, dann werde ich Euch gern für alles bezahlen, das Ihr selbst gesammelt habt.\n\nIhr werdet jede Menge auf Yorgens Bauernhof im Südosten finden.", progress = "Habt Ihr das Leichengras?", completion = "Ich danke Euch, &lt;Klasse&gt;... und ich bin sicher, dass die &lt;Volk&gt;, die durch den Trank, der daraus gebraut wird, vielleicht ihren Verstand zurückbekommen, Euch ebenfalls danken würden.", rewards = "LeichengrassichelFaulende ArmschienenWeste des TränkemachersUmhang der geistigen GesundheitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26708] = {title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", objective = "Tötet 200 Schwarzfelsorcs mit dem Belagerungspanzer der Kompanie Bravo.", description = "Ich bin hier, um Euch und der Kompanie Bravo bei der Beseitigung dieses Schlamassels zu helfen. Steigt in den Belagerungspanzer der Kompanie Bravo und räumt den Weg zu Keeshans Posten auf der anderen Seite des Tals, nördlich von hier, frei.\n\nDie Situation ist hochgradig gefährlich, Soldat. Den Schwarzfelsorcs ist Eure Position mittlerweile bekannt. Sie sind mit einer großen Streitmacht auf dem Weg zu Euch.\n\nEliminiert sie alle ohne Gnade. Wir sehen auf der anderen Seite. Möge das Licht Eurer Seele gnädig sein.", progress = nil, completion = "Wir müssen uns nur noch um die Orcs kümmern, die die Burg Steinwacht besetzt haben.", rewards = "Mantel der Kompanie BravoSchiftung der Kompanie BravoSchulterschutz der Kompanie BravoSchulterstücke der Kompanie BravoIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26709] = {title = "Der Steinthron", objective = "Sucht nach Therazane bei Therazanes Thron.", description = "Ich kehre auf meinen Thron zurück. Ich habe kein Verlangen danach, noch mehr vom Irdenen Ring zu sehen, aber Ihr seid hier stets willkommen, <Volk>. Wenn Ihr uns beim Wiederaufbau unseres Reichs helfen wollt, dann können wir Euch vielleicht ebenfalls helfen.\n\nAlles zu seiner Zeit.", progress = nil, completion = "Ihr seid zurückgekehrt. Das ist gut. Die Steinlords haben nach Euch gefragt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26710] = {title = "In den Tiefen verloren", objective = "Findet Kieselchen in den Bruchtiefen und geleitet ihn sicher aus den Tunneln.", description = "Kieselchen hat es schon wieder geschafft, sich zu verlaufen, irgendwo in den Bruchtiefen.\n\nEr hat Glück, dass er so klein und dadurch für die Schleifwürmer uninteressant ist. Es ist aber nur eine Frage der Zeit, bevor er zu nah an einem von ihnen vorbeikommt und doch aufgefressen wird. Warum auch immer er da unten ist, es kann einfach nicht so wichtig sein.\n\nEr scheint Euch zu mögen. Zieht bitte los, um ihn zu finden, und bringt ihn aus diesen Tunneln zu einem sichereren Spielplatz.", progress = nil, completion = "Das habt Ihr gut gemacht. Nun können diese Felslinge unsere Traditionen erlernen und groß und stark werden.\n\nEines Tages werden wir diese Tunnelgräberplage in unserem Reich auslöschen, damit die Felslinge nicht mehr während ihrer Jugend leiden müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26711] = {title = "Ab zur Bank", objective = "Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.", description = "Jo, Schätzchen. Was geht? Schon bereit für die Party?\n\nNein?! Du weißt doch, dass ich dich heiß und innig liebe, also weiß ich nicht ganz, wie ich es sagen soll, aber… Ich glaube, du solltest mal in der Stadt nach einem neuen Outfit für die Party suchen.\n\nGuck mich nicht so an... Du willst doch klasse für mich aussehen, ooooder? Willst du für mich nicht superschick sein?\n\nSchau erst bei der Bank vorbei und hol dir ausreichend Moneten. Du willst ja schließlich keinen Billigkram kaufen!", progress = nil, completion = "Oh, Ihr seid es, Madame! Tut mir leid, bei dem ganzen Pöbel, der hier herumschwirrt, habe ich Euch nicht gleich erkannt.\n\nIhr rumlaufenden Leute! Macht mal langsam hier! &lt;Name&gt; ist da!\n\nHier sind Eure Moneten, meine Dame. Kommt jederzeit wieder, wenn Ihr mehr braucht.", rewards = "Ihr bekommt:\n\nStapel Moneten"}
MultiLanguageQuestData['de'][26712] = {title = "Ab zur Bank", objective = "Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.", description = "Hey, mein Süßer. Schon bereit für die Party?\n\nNein?! Du weißt doch, dass ich dich heiß und innig liebe, hm? Ich finde, du solltest mal in die Stadt gehen und ein neues Outfit für die Party kaufen.\n\nGuck mich nicht so an... Du willst doch sicher gut aussehen? Willst du nicht gut für mich aussehen? Ich bin schließlich deine Freundin!\n\nSchau unbedingt erst bei der Bank vorbei und hol dir ausreichend Moneten. Kauf' nichts von diesem Billigkram!", progress = nil, completion = "Oh, Ihr seid es, mein Herr! Tut mir leid, bei dem ganzen Pöbel, der hier herumschwirrt, habe ich Euch nicht gleich erkannt.\n\nIhr rumlaufenden Leute! Macht mal langsam hier! &lt;Name&gt; ist da!\n\nHier sind Eure Moneten, mein Herr. Kommt jederzeit wieder, wenn Ihr mehr braucht.", rewards = "Ihr bekommt:\n\nStapel Moneten"}
MultiLanguageQuestData['de'][26713] = {title = "Endkampf in Steinwacht", objective = "Tötet Tharil'zun und Gath'Ilzogg.", description = "Es ist nur noch das Oberkommando des Schwarzfels übrig, <Name>. Sie haben sich in der Burg Steinwacht verbarrikadiert, unmittelbar südlich unserer Position hier an Keeshans Posten. Begleitet die Kompanie Bravo zur Steinwacht und beendet die Invasion der Schwarzfelsorcs.\n\n<Name>, keine Überlebenden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26714] = {title = "Dunkelflamme, Brut des Weltenbrechers", objective = "Ruft Dunkelflamme mit dem Horn der Beschwörung. Besiegt Dunkelflamme.", description = "Als Trottmann verstummt, wird die Welt um Euch herum plötzlich unheimlich still. In einiger Entfernung seht Ihr einen ausgewachsenen schwarzen Drachen!", progress = nil, completion = "&lt;Eine einzelne Träne rinnt über Trottmans linke Wange.&gt;\n\nSie starben bei der Verteidigung der Allianz. Bei der Verteidigung unseres Königreichs! Es sind Helden, und so wird man sie auch zur letzten Ruhe betten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26715] = {title = "Malfurion Sturmgrimm", objective = "Sprecht mit Malfurion Sturmgrimm im Tempel des Mondes in Darnassus.Ich habe Malfurion Euer Kommen angekündigt. Er schien sehr daran interessiert zu sein, Euch persönlich zu treffen.\n\nIhr solltet ihn im Tempel des Mondes aufsuchen. Er steht neben unserer geliebten Tyrande Wisperwind. Seit seiner Rückkehr ist er nicht von ihrer Seite gewichen.\n\nAber ich muss Euch warnen... Malfurion hat seine Zweifel. Es könnte sein, dass Euer Volk Euch eine große Last aufgebürdet hat, als es Euch auswählte, sich mit ihm zu treffen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich habe Malfurion Euer Kommen angekündigt. Er schien sehr daran interessiert zu sein, Euch persönlich zu treffen.\n\nIhr solltet ihn im Tempel des Mondes aufsuchen. Er steht neben unserer geliebten Tyrande Wisperwind. Seit seiner Rückkehr ist er nicht von ihrer Seite gewichen.\n\nAber ich muss Euch warnen... Malfurion hat seine Zweifel. Es könnte sein, dass Euer Volk Euch eine große Last aufgebürdet hat, als es Euch auswählte, sich mit ihm zu treffen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26717] = {title = "Worgen auf Yorgen", objective = "Untersucht den Haufen lockerer Erde auf Yorgens Bauernhof.", description = "Meinesgleichen in Rabenflucht versuchen, die wilden Worgen in diesen Wäldern zu heilen. Der Zustand selbst lässt sich nicht aufheben, doch denjenigen, die sich noch nicht zu sehr verloren haben, kann man den Verstand zurückgeben.\n\nDen meisten kann man zwar nicht mehr helfen, aber wir achten auf die, die noch Überreste ihres Verstandes besitzen... eine Verbindung zu ihrem früheren Leben.\n\nAuf Yorgens Bauernhof habe ich einen einzelnen Worgen gesehen, der in einem Erdhaufen zwischen den Gebäuden grub... könntet Ihr Euch diesen Erdhaufen ansehen? Vielleicht hat er dort etwas zurückgelassen.", progress = nil, completion = "Scheint ja knapp gewesen zu sein! Aber er lief weg, ohne Euch noch mehr zu verletzen...\n\nVielleicht kämpft er noch dagegen an. Meister Harris muss das erfahren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26718] = {title = "Brotkrumen zum Ödland", objective = "Etwas schlimmes ist geschehen.", description = "Etwas schlimmes ist geschehen.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][26719] = {title = "Lieferung an Meister Harris", objective = "Bringt Oliver Harris in Rabenflucht das Bündel Leichengras.", description = "Meister Harris muss sofort davon erfahren.\n\nHier, bringt dieses Paket mit Leichengras die Straße hinunter zum Lager in Rabenflucht. Erzählt ihm, was wir auf Yorgens Bauernhof gesehen haben.", progress = "Was bringt Euch nach hier draußen, mein Herr?", completion = "Willkommen in unserem bescheidenen Lager. Schön würde ich es nicht nennen, aber es ist zumindest etwas abgeschieden.\n\nWie bitte? Ein &lt;Volk&gt; auf dem Hof?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26720] = {title = "Ein Fluch, den wir nicht brechen können", objective = "Durchsucht Addles Siedlung nach dem lauernden Worgen und betäubt ihn mit Harris' Ampulle.", description = "Was wir hier machen, bringt keine Heilung. Die Verwandlung kann nach ihrer Vollendung nicht rückgängig gemacht werden.\n\nDoch der Verstand... Die Alchemie kann den Verstand zurückbringen, wenn noch genug davon übrig ist. Der Worgen, dem Ihr begegnet seid, kämpft anscheinend um seinen, <Name>. Wir müssen ihn wiederfinden.\n\nEr ist von Yorgens Hof geflohen, also durchsucht Addles Siedlung im Süden; vielleicht lauert er in einem der Gebäude.\n\nInjiziert ihm den Inhalt dieser Ampulle, er wird ihn betäuben. Ihr müsst ziemlich nah herankommen.", progress = "Habt Ihr Addles Siedlung gründlich durchsucht?\n\nIch würde an Eurer Stelle noch einmal ganz hinten in der Scheune nachsehen. Vieles kann in einem solchen Gebäude lauern.", completion = "Ihr habt ihn!\n\nWir haben keine Zeit zu verlieren. Wir werden die Verabreichung des Serums sofort vorbereiten.\n\nBIBBERS! Bereitmachen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26721] = {title = "Bibbers Spinnen", objective = "Erbeutet 8 Witwengiftbeutel von schwarzen Witwen.", description = "M-Meister Harris benötigt viele Reagenzien für seine Seren. Ich muss sie für ihn sammeln.\n\nDie meisten sind nicht so schlimm... Leichengras ist natürlich schlimm, aber nicht halb so schlimm wie Witwengift. Habt Ihr Euch die Witwen hier in der Gegend mal angesehen? Schon die Jungen sind mannsgroß. Selbst mit einem Gewehr halte ich die Jagd auf sie nicht aus!\n\nSie jagen mir zu viel Angst ein. Wenn Ihr sie für mich jagt, werde ich Euch gern dafür bezahlen! Bringt nur etwas Witwengift mit! Ihr findet sie in den Wäldern im Osten, direkt nördlich der Straße.", progress = "Habt Ihr sie? Bitte sagt mir, dass Ihr sie habt...", completion = "Oh danke, vielen Dank! Ihr habt mich vor den Wäldern mit all diesen furchtbaren Kreaturen bewahrt!\n\nZumindest für einen Tag...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26722] = {title = "Tief vergraben", objective = "Sucht im Tunnel unter den Katakomben des Morgenrotwaldes nach dem lichtgeschmiedeten Wappen.", description = "<Ihr befestigt den Bogen am Stab. Das Artefakt ist fast komplett. Doch es gibt eine große Lücke mitten im Kopf des heiligen Symbols.>\n\n<Erneut scheint es an Eurem Arm zu ziehen und Euch zu einem Loch in der Wand und den verschlungenen Tunneln dahinter zu führen. Dort muss sich das letzte Teil befinden.>", progress = nil, completion = "&lt;In den dunkelsten Tiefen dieses Lehmtunnels entdeckt ihr ein schwaches Leuchten. Das letzte Teil ist gefunden!&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26723] = {title = "Das Schicksal von Morbent Teufel", objective = "Sucht auf dem Verlassenen Gut nach Hinweisen auf Morbent Teufel.", description = "Der letzte, an den ich mich erinnere, bevor ich mich in den Wäldern verlor, ist Morbent Teufel. Er war ein abscheulicher Totenbeschwörer und der Grund dafür, dass so viele widerwärtige Untote dieses Land heimsuchen.\n\nIch habe einen Abenteurer gebeten, ihm ein Ende zu machen. Ich hatte angenommen, dass das auch geschehen sei! Aber Schwester Elsington hat mir gesagt, das Land sei immer noch voller Ghule und Schreckgespenster, die aus dem Grab gerissen wurden.\n\nMorbent Teufel hätte seinen letzten Atemzug in dem Haus auf dem Verlassenen Gut, nördlich des Friedhofs von Rabenflucht tun sollen. Seht nach, was aus ihm geworden ist...", progress = nil, completion = "Seine Kleidung und Blutflecken? Wenn das keine Tricks sind, dann etwas noch schlimmeres...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26724] = {title = "Der lauernde Lich", objective = "Sprecht mit Schwester Elsington.", description = "Die anderen teilen meinen Verdacht. Morbent Teufel lebt im Untod weiter... und ist vielleicht noch mächtiger als zuvor. Ein Totenbeschwörer wurde getötet, doch an seine Stelle könnte ein Lich getreten sein. Und er wird dieses Land weiter zerstören.\n\nIch erinnere mich daran, wie der Dämmerwald vor all dem war, <Name>. Ich erinnere mich an einen hellen Himmel und friedliche Wälder. Das kann nicht so weitergehen! Morbent Teufel muss endlich gestoppt werden.\n\nSprecht mit Schwester Elsington. Ihre Vision verrät Euch vielleicht, wo sich Morbent Teufel aufhält und wie man ihn besiegen kann.", progress = nil, completion = "Es ist ermutigend, dass jemand, der sich erst kürzlich erholt hat, von den Nöten anderer berührt wird. Sven erspart sich Leid, weil er nicht über sein eigenes Unglück grübelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26725] = {title = "Vom Lichte geführt", objective = "Findet die lichtgeschmiedete Rute auf dem Friedhof von Rabenflucht.", description = "Sven hat Recht. Ich fühle etwas Mächtiges und Böses tief unter dem Friedhof von Rabenflucht. Das Böse verbirgt sich in seinen Katakomben. Morbent Teufel könnte die Ursache dafür sein.\n\nIhr werdet die Macht des Lichts brauchen, um ihn zu besiegen, <Name>. Sven sagte mir, dass die Helden, die Morbent Teufel ursprünglich töteten, ein Artefakt aus lichtgeschmiedetem Eisen benutzten, das von heiliger Macht erfüllt war. Das Artefakt ist immer noch hier!\n\nIch fühle es ebenfalls. Es ist ein schimmerndes Licht in der Dunkelheit. Sucht in Rabenflucht danach und lasst Euch vom Licht führen.", progress = nil, completion = "&lt;Ihr findet einen leuchtenden Metallstab, der in der kalten Erde vergraben wurde. Doch es gibt Löcher darin. Anscheinend fehlen Teile des Artefakts.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26726] = {title = "Triumphale Rückkehr", objective = "Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.", description = "Kehrt nach Seenhain zurück und meldet Solomon, dass die Invasion des Schwarzfels vereitelt wurde. Sorgt dafür, dass er den Preis für unsere Freiheit begreift - dass wir fünf unserer größten Helden verloren haben, um das Rotkammgebirge und letzten Endes auch Sturmwind zu retten.\n\nIhr seid der letzte Überlebende der Kompanie Bravo, <Name>. Sorgt dafür, dass ihr Vermächtnis weiterlebt.\n\nWegtreten.", progress = nil, completion = "Man wird sie niemals vergessen, &lt;Name&gt;. Die Geschichte von dem, was Ihr und der Rest der Kompanie Bravo geopfert habt, um das Rotkammgebirge zu retten, werden noch viele Generationen hören.\n\nDen Verlust Eurer Freunde kann ich nicht wettmachen, trotzdem möchte ich Euch für eine solch heroische Tat belohnen. Hier sind Keeshans Habseligkeiten - mehr haben wir nicht gefunden, als wir den See nach seiner Leiche absuchten. Trottmann hat mir erklärt, Keeshan hätte sicherlich gewollt, dass der einzige Überlebende der Kompanie Bravo etwas davon nimmt. Vergesst sie nicht, &lt;Name&gt;!", rewards = "Keeshans DolchKeeshans BogenAuf Euch wartet eine dieser Belohnungen:\n\nSignet der Kompanie Bravo\n\nIhr bekommt außerdem:\n\nKeeshans Kopftuch"}
MultiLanguageQuestData['de'][26727] = {title = "Die Rache des Einbalsamierers", objective = "Tötet Kleiner in Dunkelhain.", description = "Ihr seid nicht der erste Narr, der von Calvinius manipuliert wurde! Wir nennen diesen tüdeligen alten Mann den Einbalsamierer. Er ist ein abscheulicher Totenbeschwörer und der Fluch dieser Stadt.\n\nUnd nun nähert sich uns seine schreckliche Schöpfung, die mit den Materialien, die Ihr ihm gebracht habt, zusammengenäht und ins Leben gerufen wurde!\n\nDiese schreckliche Kreatur wird in wenigen Momenten über uns kommen! Wenn Ihr ein Herz habt, <Name>, dann werdet Ihr der Nachtwache helfen, diese Monstrosität zu vertreiben und unsere Stadt zu retten!", progress = nil, completion = "Dem Lichte sei Dank, er ist weg...\n\nIhr habt durch Eure Hilfe bei der Rettung der Einwohner Wiedergutmachung geleistet, &lt;Name&gt;.", rewards = "Kleiners' kleines MäntelchenGlanzmetallarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nEllos Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26728] = {title = "Heldenaufruf: Dämmerwald!", objective = "Reist nach Dämmerwald und meldet Euch bei Kommandantin Althea Schwarzhaupt in Dunkelhain.", description = "<Name>, die Bürger von Dämmerwald benötigen dringend Eure Unterstützung! Ich habe hier einen Brief von Kommandantin Althea Schwarzhaupt, der Anführerin der Nachtwache. Sie bittet um Hilfe.\n\nUm nach Dunkelhain zu kommen, solltet Ihr die Brücke benutzen, die sich in der südwestlichen Ecke des Rotkammgebirges befindet. Auf der anderen Seite der Brücke beginnt Dämmerwald. Dann müsst Ihr nur noch der Straße nach Dunkelhain folgen. Hütet Euch vor den wilden Bestien, die außerhalb der Ortschaften lauern!", progress = nil, completion = "Ihr seid die Hilfe, die wir angefordert haben?\n\n&lt;Althea seufzt.&gt;\n\nDann müsst Ihr uns wohl genügen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26729] = {title = "Wasserelementare", objective = "Holt 6 Armschienen eines Wasserelementars.", description = "Ich kam ins Schlingendorntal, um etwas zu untersuchen, das Altar von Naias genannt wird, doch dummerweise widersetzte ich mich Colonel Kurzens Annährungsversuchen, was mir einige Jahre in diesem Käfig dort einbrachte. Jetzt bin ich wieder draußen, also spricht nichts dagegen, meine ursprünglichen Studien fortzusetzen .\n\nDer Altar steht auf einer Insel im Westen, südlich von Zul'Kunda. Besorgt mir einige Armschienen von den Wasserelementaren der Insel.\n\nOh, und Ihr könnt dieses Gerät benutzen, wenn Ihr fertig seid. Dann müsst Ihr den ganzen Weg hierher zurück nicht laufen.", progress = "Ja, <Name>?", completion = "Die reichen für meine Zwecke. Allerdings können wir den Altar nicht nur mit Armschienen aktivieren...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26730] = {title = "Man kann den Murloc aus dem Ozean holen...", objective = "Holt 6 Phiolen mit Meersalz von den Murlocs der Düsterkiemen im Nördlichen Schlingendorntal.", description = "Ich brauche etwas, um an die reine, elementare Kraft dieser Armschienen zu kommen... etwas starkes und abschleifendes, was aber dennoch zum Meer gehört.\n\nDie Murlocs der Düsterkiemen sind vom Meer ins Landesinnere gezogen, tragen aber immer noch Phiolen mit Meersalz bei sich. Ich weiß nicht, wofür sie das Salz benötigen, aber es eignet sich gut für unsere Studien. Ihr findet die Düsterkiemen im Tal südlich des Rebellenlagers und östlich der Ruinen von Bal'lal.", progress = "Das Salz?", completion = "Wir haben, was wir brauchen. Seid Ihr bereit dazu, den Altar von Naias zu aktivieren, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26731] = {title = "Der Altar von Naias", objective = "Beschwört Naias mit Naias' Gabe und holt das Herz von Naias.", description = "Das Salz, das Ihr gebracht habt, reichte aus, um die Verzauberungen im Inneren der Armschienen zu aktivieren. Ich habe diese Verzauberungen gesammelt und zu einem Beschwörungsstein zusammengefügt... eine Gabe, könntet Ihr sagen.\n\nKehrt zur Insel Naias zurück und legt die Gabe auf Naias' Altar. Ruft mich, wenn Ihr Naias' Herz habt.", progress = "Ich warte gespannt auf das Ergebnis.", completion = "Meine Kollegen von den Kirin Tor werden sich freuen, dass das Herz nun uns gehört.\n\nDanke für Eure Unterstützung, &lt;Name&gt;. Ohne Euch hätte ich das nicht geschafft.", rewards = "Emerines KlingeSalzgehärtete SchiftungDschungelläuferstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26732] = {title = "Schlechte Medizin", objective = "Besorgt 7 Dschungelarzneien aus Kurzens Truppenlager.", description = "Ich habe den Verdacht, dass Kurzens Medizinmänner nicht nur Medizin verteilen. Kurzen benötigt etwas, um aufkeimenden Ungehorsam zu ersticken. Ein Elixier getarnt als \"Medizin\", wäre dafür sehr gut geeignet.\n\nWir brauchen diese Arzneien für unsere Studien. Durchsucht Kurzens Truppenlager im Südosten - seine Medizinmänner und Dschungelkämpfer sollten die Heilmittel bei sich tragen.", progress = "In meiner Freizeit beschäftige ich mich ein wenig mit Alchemie.", completion = "Gut gemacht, &lt;Name&gt;. Dann wollen wir mal sehen, was in diesem Elixier steckt...", rewards = "Gamaschen des MissionarsKordel des AsketenNimetz' SchulterstückeDer folgende Zauber wird auf euch gewirkt:\n\nA Lashtail Hatchling: Summon Questgiver Hatchling\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26733] = {title = "Kontrollprobe", objective = "Besorgt 7 Proben Kristallrückenbasiliskenblut.", description = "<Bruder Nimetz analysiert die Proben, die Ihr ihm gegeben habt.>\n\nDas... das ist nur Basiliskenblut!\n\nNein, es besteht größtenteils aus Basiliskenblut. Sie haben jedoch etwas hinzugefügt. Für einen vernünftigen Vergleich brauche ich eine Kontrollprobe.\n\nWahrscheinlich stammt das Blut von Kristallrückenbasilisken, die östlich des Truppenlagers vorkommen. Bringt mir einige reine Proben, dann kriege ich schon heraus, was in dem Elixier ist.", progress = "Etwas in diesem Elixier ist nicht gerade gesundheitsförderlich, <Name>. Ich habe meine Analyse zwar noch nicht beendet, aber ich kann es spüren.", completion = "Das reicht. Wartet bitte einen Moment, während ich es teste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26734] = {title = "Die Quelle des Wahnsinns", objective = "Erbeutet einen flüsternden blauen Stein von Kurzens Truppen im Vorratslager.", description = "Ich habe das Basiliskenblut aus dem Elixier reduziert. Dabei habe ich einen ungewöhnlichen Bestandteil gefunden. Es scheint sich um eine Art blauen Kristall zu handeln...\n\n<Bruder Nimetz betrachtet seine Notizen.>\n\nEs ist kein singender blauer Kristall... und auch kein pulsierender blauer Splitter...\n\n<Er blättert einige Seiten vor.>\n\n... kein Stück des Gedankenauges. Nein, so etwas haben wir in Schlingendorntal noch nie gesehen. Jemand muss doch noch etwas von dieser Substanz besitzen. Ich will sie haben. Seht bei Kurzens hochrangigen Truppen hinten in ihrer Höhle nach.", progress = "Geht bitte vorsichtig damit um, <Name>. Wir wissen nicht, was es ist.", completion = "&lt;Bruder Nimetz öffnet einen Beutel. Ihr legt den Kristall hinein.&gt;\n\nIch wusste, dass jemand noch etwas von dieser Substanz haben würde. Ich werde dies meinen Kontakten in Fort Livingston südlich von hier schicken. Hoffentlich haben sie etwas mehr Glück damit.\n\nDanke für alles, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26735] = {title = "Kurzens Schicksal", objective = "Findet das Gefängnisregister von Kurzens Truppenlager und die Offiziersakten von Kurzens Truppenlager.", description = "Hallo, <Klasse>.\n\nWir sind Soldaten aus Sturmwind und haben in Kurzens Truppenlager rebelliert. Der große Außenposten liegt südöstlich von hier. Wir standen unter dem Kommando von Colonel Kurzen, bis er und seine Vertrauten begannen, den Verstand zu verlieren...\n\nWir lehnten uns auf, errichteten hier unser Lager und wehrten uns gegen Kurzen. Nun habe ich von meinen Kontakten erfahren, dass Kurzen verschwunden ist. Ich traue dieser Quelle, aber ich möchte das noch einmal von einem Außenstehenden hören. Bitte begebt Euch in das Lager und sucht nach Belegen für sein Schicksal.", progress = "Habt Ihr etwas entdeckt, <Name>?", completion = "Sie haben ihn UMGEBRACHT? Dabei dachte ich die ganze Zeit, er würde mit eiserner Hand über sie herrschen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26736] = {title = "Vom Wahnsinn verschont", objective = "Rettet Berrin Brennfeder, Emerine Junis und Osborn Widrikus aus Kurzens Truppenlager.", description = "Kurzens Tod ist eine Erleichterung, aber interessanter und momentan wesentlicher ist, dass dies ein Zeichen dafür sein könnte, dass es potentielle Verbündete im Lager gibt.\n\nMich interessiert nicht, was in dem Gefängnisregister steht. Ich weiß GENAU, weshalb die 3 eingesperrt wurden: weil sie sich weigerten, Befehle zu befolgen. Der Wahnsinn muss sie verschont haben, so wie meine Rebellenkameraden hier. Sie wurden eingesperrt, weil sie aufbegehrten.\n\nFindet sie, <Name>. Findet sie und schickt sie hierher.", progress = nil, completion = "Danke, &lt;Name&gt;. Ich lag mit meiner Vermutung anscheinend richtig... die drei Gefangenen scheinen der Krankheit, die Kurzen und den Rest seiner Männer ergriffen hat, entkommen zu sein.\n\nVor Eurer Ankunft teleportierte Emerine sich und die anderen nach Sturmwind, um sich nach all den Entbehrungen zu säubern. Sie haben versprochen, bald zurückzukommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26737] = {title = "Beendet Kurzens Vermächtnis", objective = "Tötet Oberstabschef Anders, Oberstabschef Gaulus, Oberstabschef Miranda und Oberstabschef Esquivel im Vorratslager.", description = "Unsere Verbündeten wurden aus Kurzens Truppenlager evakuiert, nun müssen wir es ein letztes Mal angreifen. Sie werden nie wieder so schwach sein wie gerade und mit Eurer Hilfe können wir sie vielleicht so weit schwächen, dass sie sich nicht mehr davon erholen.\n\nDiese vier Namen, die in den Offiziersakten erwähnt werden - Anders, Gaulus, Miranda und Esquivel - sind die höchstrangigen übrig gebliebenen Soldaten. Sucht nach ihnen in der Höhle im hinteren Teil des Truppenlagers. Sollten diese vier verschwinden, werden die Konsequenzen für Kurzens Streitkräfte verheerend sein.\n\nGehet mit Ehre, <Name>.", progress = nil, completion = "Hervorragend gelöst, &lt;Name&gt;. Meine Männer und ich kümmern uns um den Rest.\n\nOhne Kurzen können wir vielleicht die Expedition, die wir im Schlingendorntal geplant hatten, fortsetzen und... ahh...\n\nSpielt keine Rolle. Bitte seht Euch in unseren Rüstungslagern um. Vielleicht findet Ihr etwas passendes.", rewards = "Kundschafterausrüstung der ExpeditionGuerillabrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nRing der vergessenen Ursachen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26738] = {title = "Frisch geschlüpft", objective = "Bringt das Schmetterschwanzjunge zu Korporal Sethmann im Rebellenlager im Nördlichen Schlingendorntal.\n\nBereitgestellter Gegenstand: \n", description = "Als Ihr die Sachen des Soldaten durchsucht, bemerkt Ihr ein frisch geborenes, weibliches Raptorjunges, das zu Euch aufsieht. Ist es Kurzens Milizsoldaten die ganze Zeit über gefolgt?\n\nIhr seht, wie es Euch mustert, sich Euer Gesicht einprägt und Eure Bewegungen beobachtet.\n\nDas Schmetterschwanzjunge geht eine Bindung mit Euch ein.\n\nVielleicht weiß jemand im Rebellenlager etwas mit einem Raptorjungen anzufangen.", progress = nil, completion = "Ja, die Kleine scheint Euch zu mögen. Ihr habt Glück... in diesem Alter sind Raptoren ruhig, friedlich und leicht auszubilden. Behaltet sie, &lt;Name&gt;... sie könnte Euch noch von Nutzen sein.\n\nUm genau zu sein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26739] = {title = "Ich glaube, sie hat Hunger", objective = "Tötet Kristallrückenbasilisken im Nördlichen Schlingendorntal und lasst Euren Schmetterschwanz 40 Bissen ihres Fleisches fressen.", description = "Euer junges Raptorweibchen scheint hungrig zu sein. Wenn Ihr sie behalten wollt, solltet Ihr vielleicht etwas zu fressen für sie finden. Die Schmetterschwänze greifen häufig die Basilisken des Schlingendorntals an. Man findet sie im Osten hinter Kurzens Truppenlager.\n\nWahrscheinlich ist sie noch nicht stark genug, um allein auf die Jagd zu gehen, aber ich bin mir sicher, dass sie frisches Basiliskenfleisch fressen wird.", progress = nil, completion = "Sie wirkt schon größer! Wie Ihr seht, wachsen diese Raptoren schnell. Ihr könnt von Glück sagen, dass Ihr eine so starke Begleiterin gefunden habt.\n\nBehaltet sie bei Euch, solange es geht, &lt;Name&gt;. Sie wird sich bestimmt irgendwann als Gewinn für Euch erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26740] = {title = "Kochen mit Krazek", objective = "Bringt Krazeks Spezialtopf zu Krazek.", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblinhändler in Beutebucht einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart – bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek. Das Letzte, was ich gehört habe, war, dass er bei Nesingwary Unterschlupf gefunden hat, im Jägerlager im Süden.", progress = "Hallo! Ihr habt etwas für mich?", completion = "Ah ja, das ist einer von Krazeks Spezialtöpfen! Eine geniale Erfindung, aber bisweilen bricht eine Feder oder das Getriebe gerät aus dem Tritt oder so was in der Art. Lasst mich mal sehen, was mit dem hier los ist...\n\nAha! Die Dampfbeschickungsvorrichtung ist völlig verrostet, die Gelenkdichtung ist rissig und dem Fobulator fehlen Zähne. Es wundert mich, dass der Topf in diesem Zustand überhaupt irgendetwas kochen konnte!\n\nOb ich ihn reparieren kann? Natürlich kann ich ihn reparieren!\n\nAber das kostet. So etwas kostet immer, oh ja...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26741] = {title = "REUSE", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26742] = {title = "Erkenntnisse über die Blutskalpe", objective = "Besorgt ein Totem der Blutskalpe von einem Schamanen der Blutskalpe.", description = "Ich habe mich nie richtig bei Euch für meine Rettung bedankt.\n\nDanke, <Name>.\n\nIch bin immer noch etwas erschöpft von meiner Gefangenschaft, deshalb dachte ich, Ihr könntet mir vielleicht bei meinen Studien helfen. Als ein Schamane des Wildhammerklans interessiere ich mich natürlich sehr für die schamanistischen Methoden des Blutskalpklans.\n\nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben. Hätte ich eines der Totems, die ihre Schamanen benutzen, könnte ich mit meinen Studien beginnen. Ihr findet sie in den Ruinen von Bal'lal, an der Küste im Südwesten.", progress = "Seid vorsichtig. Sie werden sich wahrscheinlich wehren.", completion = "&lt;Berrin betrachtet die Inschriften auf dem Totem.&gt;\n\nIch glaube, ich kann die Worte lesen... Faszinierend!\n\nTsul'kalu, Mahamba, Pogeyan... was sind das für Namen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26743] = {title = "Den Blutskalpen heilig", objective = "Besorgt eine Ikone von Tsul'kalu, eine Ikone von Mahamba und eine Ikone von Pogeyan aus dem Lager der Blutskalptrolle in den Ruinen von Tkashi.", description = "Ahh... das müssen die Namen ihrer Totemwesen sein - der Tiere, die sie den Geistern zuordnen. Mal sehen... Mahamba als Wasser, Tsul'Kalu als Erde, Pogeyan als... Luft? Feuer? Diesen Teil kann ich nicht entziffern.\n\nIch würde gern mehr über ihre Geister erfahren. Hier in der Nähe, in den Ruinen von Tkashi, haben die Blutskalpe ein Lager errichtet. Vielleicht könnt Ihr dort Einzelheiten herausfinden.", progress = "Wahrscheinlich basieren die Totemwesen auf einigen der fantastischen Kreaturen, die durch diesen Dschungel streifen.", completion = "Erst rettet Ihr mich aus der Zelle des Wahnsinnigen und nun bringt Ihr mir einige der Schlüssel zum Verständnis des Trollschamanismus.\n\nDiese Woche kann sich sehen lassen!\n\nNoch einmal vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass der Wildhammerklan Euch unterstützt, wenn Ihr Eure Reise fortsetzt.", rewards = "BlutskalpsandalenMahambas LiebkosungTsul'kalus SchlägerAuf Euch wartet eine dieser Belohnungen:\n\nBand des Schreibers des Wildhammerklans\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26744] = {title = "Tiefe Wurzeln", objective = "Holt die Schrifttafel der Blutskalpe aus den Ruinen von Bal'lal im Nördlichen Schlingendorntal.", description = "Doch nun zu etwas anderem: Ich stelle gerade eine Sammlung von Trollgeschichten und -legenden für ein... persönliches Projekt zusammen. Vielleicht könntet Ihr mir helfen, einige davon zu finden.\n\nDie Blutskalpe in den Ruinen von Bal'lal, an der Küste im Südwesten, besitzen eine große Schrifttafel, auf der einige ihrer Geschichten festgehalten sind. Ich würde Euch natürlich für die Geschichten, die Ihr mir bringt, entschädigen.", progress = "Seid Ihr schon in den Ruinen von Bal'lal gewesen? Habt Ihr die Tafel gefunden?", completion = "Um ehrlich zu sein, schicke ich diese Informationen zu meiner Frau und meinem Sohn zuhause in Sturmwind. Sie möchten wissen, was ich hier draußen im Dschungel mache, aber ich kann sie nur selten besuchen. Jede Kleinigkeit hilft.\n\nDanke, &lt;Name&gt;.", rewards = "Weiche BaumwollarmbänderGut verarbeitete LederkniehosenRebellenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26745] = {title = "Lieblingsschädel", objective = "Meldet Euch bei Osborn Widrikus im Rebellenlager und zeigt ihm den neuen Schädel Eures Schmetterschwanzjungen.\n\nBereitgestellter Gegenstand: \n", description = "Euer zahmes Raptorweibchen scheint ein neues Spielzeug gefunden zu haben: Einen Schädel von einem nahegelegenen Trollschädelhaufen.\n\nIhr wisst nicht, was diesen Schädel von den anderen unterscheidet, aber aus irgendeinem Grund lässt sie ihn nicht wieder fallen.\n\nOsborn Widrikus, der Gnom, den Ihr aus Kurzens Truppenlager gerettet habt, ist ein Experte für Trollgeschichte und Trollphysiologie. Vielleicht weiß er, warum dieser Schädel etwas besonderes ist.", progress = nil, completion = "Was haben wir denn da? Ein junger Raptor mit seinem Haustier: seinem Hausmensch. Hah!\n\nAber kommen wir zu Wichtigerem: Was für einen Schädel habt Ihr da? Das war kein gewöhnlicher Troll. Er war groß...\n\n&lt;Osborn klopft auf den Schädel.&gt;\n\n... und stark. Wisst Ihr, ich wollte immer schon mal Trollmagie ausprobieren. Kann doch nicht so schwer sein, oder? Wollen wir diesen starken Mann als Versuchskaninchen nehmen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26746] = {title = "Ein Gespür für solche Dinge", objective = "Lasst Euer Schmetterschwanzjunges 8 Tkashifetische erschnüffeln.", description = "<Osborn wirft noch einen Blick auf den Schädel.>\n\nAls er noch lebte, war er stark und mächtig, ein Fürst der Trolle. Mit unserer Hilfe kann er wieder ein Fürst werden.\n\nDie Strauchdiebe der Blutskalpe, die durch die Ruinen im Südwesten ziehen, sammeln magische Fetische, die wir gebrauchen könnten. Sie vergraben diese Artefakte, um sie zu verstecken. Findet diese Artefakte mit Hilfe Eures Jungen, <Name>... und bringt sie dann her.", progress = "Wie viele Fetische habt Ihr gefunden?", completion = "Die verschaffen uns ein wenig... wie heißt noch gleich dieses Trollwort? Voodoo? Juju? Tiklabang?\n\nIst egal. Wenn wir einen Troll neu erbauen wollen, brauchen wir Trollmagie und diese Fetische sind voll davon.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26747] = {title = "Ein Exemplar aus Fleisch und Blut", objective = "Holt Gan'zulahs Leiche aus Zul'Kunda.", description = "Die Seele ist bereit, der Körper jedoch nicht. Für einen Schädel, der so wohlgeformt, so wunderbar und so schön wie dieser ist, brauchen wir einen passenden Körper.\n\nGan'zulah, der Häuptling der Blutskalpe, ist durch brutale Gewalt auf den Thron gekommen. Sollte er noch leben, werdet Ihr ihn in Zul'Kunda im Westen finden.\n\nSeinen Körper zu rauben, wird nicht leicht sein, aber <ein kräftiger/eine kräftige:c> <Klasse> wie Ihr wird das schon schaffen. Bringt ihn hierher, wenn Ihr fertig seid.", progress = "Gan'zulah war ein Schläger und Tyrann. Ich spüre, dass dieser Troll anders sein wird. Diese Trollmagie ist leichter als ich dachte!", completion = "Das habt Ihr gut gemacht, &lt;Volk&gt;. Wir haben einen Kopf, einen Körper und etwas Juju-Voodoo-Mojo-Unsinn. Jetzt noch ein kleiner Elektroschock, um alles in Gang zu bringen...", rewards = "JujugürtelWeggeworfene TrollgamaschenElektrostatische BeinschützerDer folgende Zauber wird auf euch gewirkt:\n\nCosmetic - Cauldron Explosion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26748] = {title = "Blutfürst Mandokir", objective = "Bringt Blutfürst Mandokir im Rebellenlager das Schmetterschwanzeifragment.", description = "<Volk>. Ihr habt gerade euren schlimmsten Alptraum erweckt. Dachtet Ihr etwa, ich wäre ein Freund, <Volk>? Ah, ha ha haaaa!\n\nIhr habt Euren Zweck erfüllt. Dank Euch bin ich wieder ins Reich der Lebenden zurückgekehrt. Deshalb werde ich Euch nicht töten, sondern Euch einen Handel anbieten.\n\nGebt mir den Raptor.\n\nEuch dürfte bereits klar sein, dass dies kein gewöhnlicher Raptor ist. Ich brauche einen Ersatz für Ohgan. Tut es, sonst werdet Ihr und der Gnom meine Rache zu spüren bekommen.", progress = "Ich verlange nur den Raptor, <Volk>. Gebt ihn mir, dann lebt der Gnom weiter.", completion = "Freut mich, dass Ihr zur Besinnung gekommen seid.\n\nIhr müsst uns mal in Zul'Gurub besuchen, &lt;Volk&gt;. Ich werde Euch beobachten...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBloodlord Mandokir: Summon Mandokir Running (A)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26749] = {title = "Priesterin Thaalia", objective = "Sprecht mit Priesterin Thaalia in Fort Livingston im Nördlichen Schlingendorntal.", description = "Danke, <Name>. Ich weiß, dass Ihr mein Leben nicht hättet retten müssen.\n\nEs ist schlimm, dass Blutfürst Mandokir zurückgekehrt ist. Er wurde vor einigen Jahren in Zul'Gurub getötet. Wir dachten, wir würden ihn und sein Volk nie wiedersehen. Die Trolle von Zul'Gurub versuchten sich an einem schrecklichen, widerwärtigen Ritual. Wenn Mandokir lebt, dann ist es nur logisch anzunehmen, dass er nicht der einzige ist.\n\nDie Forscher in Fort Livingston, weit im Süden, wissen vielleicht mehr. Sprecht mit ihrer Priesterin.", progress = nil, completion = "Mandokir lebt, ja.\n\nIhr tragt die Verantwortung, ja.\n\nVielleicht könnt Ihr ihn noch aufhalten, ja.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26750] = {title = "Auf Geheiß der Steinmutter", objective = "Sprecht mit Therazane der Steinmutter.", description = "Es ist Zeit. Die Steinmutter wird mit Euch sprechen. Ihr findet ihren Thron im Norden Tiefenheims, über dem Geschliffenen Schlund.", progress = nil, completion = "Ihr seid also gekommen.\n\nFleischlinge wie Ihr haben meine Tochter getötet... meine einzige Tochter - ohne, dass sie etwas getan hätte.\n\nUnd als ob es nicht schon genug wäre, mich meiner Familie zu berauben, haben sich mehr von Euch um Todesschwinge geschart, um ihm dabei zu helfen, mein Heim zu verwüsten.\n\nWie vermessen von Euch, vor mir zu erscheinen und um MEINE Hilfe zu bitten. Ich bin dazu verleitet, Euch an Ort und Stelle zu vernichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26751] = {title = "Bevölkerungskon-Trolle", objective = "Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.", description = "Ich habe vernommen, dass Ihr bald nach Zul'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe, die Ihr dort erfüllen könntet.\n\nDie Trolle werden zu zahlreich für das Schlingendorntal. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie ergießen sich aus ihren Ruinen in den Dschungel und zerstören das natürliche Gleichgewicht der Region. Es wird Zeit, dass wir dieses Gleichgewicht wiederherstellen.\n\nZul'Kunda ist die Hauptstadt der Blutskalpe. Dort werdet Ihr die höchstrangigen Blutskalpe finden. Reduziert ihre Anzahl und kehrt zu mir zurück.", progress = "Wir sind Euch dankbar für Eure Hilfe hier im Schlingendorntal, <Name>.", completion = "Das Gleichgewicht ist wiederhergestellt - erst einmal. Vielleicht werden wir Euch in Zukunft noch einmal rufen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26752] = {title = "Audienz bei der Steinmutter", objective = "Nehmt an der Audienz bei der Steinmutter teil.", description = "Bleibt wo Ihr seid, Champion. Ich habe noch nicht entschieden, was ich mit Euch und Eurem Irdenen Ring anstelle.", progress = nil, completion = "Gut gemacht, Bruder. Die Steinmutter hört zu, und die Weltensäule ist fast zum Greifen nah.", rewards = "Umklammerung der SteinmutterAuf Euch wartet eine dieser Belohnungen:\n\nTherazanes SiegelKuss der Steinmutter\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26753] = {title = "Die Hallen der Toten", objective = "Findet den lichtgeschmiedeten Bogen in den Katakomben des Morgenrotwaldes.", description = "<Vor Euch neigt sich die nackte Erde dem dunklen Eingang zu den Grüften entgegen.>\n\n<Ihr spürt, wie das lichtgeschmiedete Artefakt Euch darauf zuzieht. Ist das andere Teil vielleicht dort unten?>", progress = nil, completion = "&lt;Im Dreck dieser Nische funkelt helles Metall. Ihr habt einen weiteren Teil des Artefakts gefunden!&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26754] = {title = "Morbents Bann", objective = "Schwächt Morbent Teufel mit Morbents Bann und besiegt ihn.", description = "<Die Teile passen. Ihr habt das geheiligte Artefakt zusammengesetzt. Es strahlt ein heiliges Licht aus. Damit solltet Ihr in der Lage sein, Morbent Teufels dunkle Magie zu besiegen.>\n\n<Tiefer im Tunnel, entgegengesetzt der Richtung, aus der Ihr gekommen seid, ertönt ein verstörendes Kichern. Es ist das rasselnde Lachen eines Lich. Morbent Teufel ist direkt vor Euch!>", progress = nil, completion = "Möge das widerliche Ungeheuer dieses Mal tot bleiben!\n\nIch werde nach unten gehen und seine Asche in die Winde verstreuen, &lt;Name&gt;. Ihr habt Großes vollbracht. Vielleicht wird in Dämmerwald mit der Zeit wieder Frieden einkehren.", rewards = "Äscherne HandschuheTeufelsbanngürtelAuf Euch wartet eine dieser Belohnungen:\n\nYorgens Segen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26755] = {title = "Weg von der Front", objective = "Bombardiert 30 Fungusschrecken und/oder Mitglieder der Verstärkung der Steintroggs.", description = "Oh, gut! Ihr habt noch ein Katapult mitgebracht! Klei mag älter als Staub sein, aber er weiß, wie man eine schreckliche Kriegsmaschine baut.\n\nNun, Ihr habt es sicher nicht den weiten Weg bis hierher gebracht, weil Ihr ein wenig Bewegung wolltet, Fleischsack. Schwingt Euch in eines dieser Dinger und bombardiert die Fungusschrecken und ihre Verstärkung, die aus Nadelfelsbruch herausströmen.\n\nWir müssen sie von der Front fernhalten!", progress = nil, completion = "Das ist ein guter Anfang, &lt;Name&gt;, aber Ihr müsst in die Stadt fliegen und dort ein wenig Aufruhr verursachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26760] = {title = "Das Unmögliche möglich machen", objective = "Seht zu, wie Oliver Harris und Bibbers versuchen, den lauernden Worgen zu heilen.", description = "Ich bin optimistisch, aber wir sollten professionell bleiben. Wir behandeln ihn wie alle anderen.\n\nAb in die Guillotine mit ihm... und wenn die Alchemie nicht wirkt, kommt er nicht wieder heraus.\n\nBibbers und ich kümmern uns darum. Bitte bleibt zurück und seht aus sicherer Entfernung zu.", progress = nil, completion = "Geschafft... Endlich! Ich kann Euch gar nicht genug für die Gelegenheit danken, die Heilung selbst auszuprobieren.\n\nUnser neuer Freund könnte wahrscheinlich ebenfalls Hilfe gebrauchen. Wieso sprecht Ihr nicht mal mit ihm?", rewards = "MondkreischerarmschienenSchild von DunkelhainAuf Euch wartet eine dieser Belohnungen:\n\nGeweihtes Szepter\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26761] = {title = "Eine Bedrohung für das Königreich", objective = "Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.", description = "Es besteht kein Zweifel, dass die Defias eine ernsthafte Bedrohung für das Königreich darstellen, aber wir können nicht einfach so deren Versteck betreten und hoffen, dass sich alles zum Guten wendet. Nein, ein Angriff auf die Defias erfordert Zeit und Planung. Überlasst die Logistik mir. Unser Königreich hat auch noch andere Sorgen, gegen die umgehend etwas unternommen werden muss!\n\nReist nach Osten, über Elwynn ins Rotkammgebirge und meldet Euch bei Magistrat Solomon in Seenhain. Ich lasse nach Euch schicken, wenn wir bereit sind, die Defias anzugreifen.", progress = nil, completion = "Ich habe schon gehört, dass die Defias wieder auf den Plan getreten sind. Schreckliche Neuigkeiten. Ich wünschte nur, ich hätte bessere zu berichten, aber so wie es aussieht, wird Seenhain angegriffen! Wir verlieren an allen Ecken und Enden Leute. Unsere eigenen Wachen sind viel zu weit verstreut, um mit der Situation fertigzuwerden. Wir brauchen einen Helden, der sich der Sache annimmt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26762] = {title = "Reaktiviert die Konstrukte", objective = "Reaktiviert 5 deaktivierte Kriegskonstrukte.", description = "Wir haben eine ganze Reihe unserer Kriegskonstrukte gen Norden nach Nadelfelsbruch geschickt, aber keines ist je zurückgekehrt. Wir wissen, dass die Mystiker der Steintroggs dafür verantwortlich sind.\n\nWir befürchten nun, dass die Mystiker die Kontrolle übernehmen und unsere Konstrukte gegen uns verwenden werden, so wie sie es mit den Fungusgiganten getan haben.\n\n<Name>, betretet die Stadt der Steintroggs und reaktiviert die Konstrukte.", progress = nil, completion = "Das war wirklich gute Arbeit, &lt;Name&gt;.\n\nUnsere Konstrukte funktionieren wieder und stehen hinter den feindlichen Linien. Es ist nur noch eine Frage der Zeit, bis uns der Durchbruch und damit die Rettung des Steinvaters gelingt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26763] = {title = "Venture Company-Bergbau", objective = "Besorgt 5 gerommelte Kristalle von Angehörigen der Venture Co. beim Nazferitisee.", description = "Um diesen Topf zu reparieren, werde ich Reagenzien brauchen. Und um die zu bekommen, werdet Ihr ein ganz klein bisschen töten müssen. Ich hoffe, das stört Euch nicht.\n\nDiese lästigen Geologen der Venture Company haben einige gerommelte Kristalle gesammelt, die für meine Zwecke genügen würden. Ihr findet sie rund um ihr Basislager im Osten, auf der anderen Seite des Nazferitisees.\n\nIst mir egal, was Ihr tun müsst, um sie zu bekommen.", progress = "Habt Ihr die Kristalle?", completion = "Die sind genau richtig. Einen Moment bitte.\n\n&lt;Krazek wirft die Steine in den Kochtopf und schüttelt sie ein wenig.&gt;\n\nAlles repariert!", rewards = "Krazeks TopfhandschuheGetauschte ArmschienenSchulterstücke aus RestmetallIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26764] = {title = "Moralischer Bankrott", objective = "Befreit 3 versklavte Druiden aus dem Basislager der Venture Co.Euch ist vielleicht aufgefallen, dass die Venture Company den Wald rund um ihr Basislager im Osten komplett gerodet hat. Ihr Vorarbeiter wittert Profit, deshalb hat er Druiden versklavt, die er zwingt, den Wald neu wachsen zu lassen, damit er ihn wieder abholzen kann!\n\nIch persönlich finde das abscheulich, nicht nur, weil ich nicht als erster auf die Idee gekommen bin.\n\nBefreit einige dieser Druiden aus ihrer Gefangenschaft. Sie werden Euch bestimmt dankbar sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Euch ist vielleicht aufgefallen, dass die Venture Company den Wald rund um ihr Basislager im Osten komplett gerodet hat. Ihr Vorarbeiter wittert Profit, deshalb hat er Druiden versklavt, die er zwingt, den Wald neu wachsen zu lassen, damit er ihn wieder abholzen kann!\n\nIch persönlich finde das abscheulich, nicht nur, weil ich nicht als erster auf die Idee gekommen bin.\n\nBefreit einige dieser Druiden aus ihrer Gefangenschaft. Sie werden Euch bestimmt dankbar sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26765] = {title = "Kehrt zu Korporal Kaleb zurück", objective = "Bringt Krazeks reparierten Topf zu Korporal Kaleb im Rebellenlager im Nördlichen Schlingendorntal.", description = "So, dieser Kessel ist repariert. Ich habe sogar eine zweite Dampfpfeife eingebaut. Und seht! Am Boden gibt es einen neuen Zerhacker, der sogar durch Beinknochen schneidet!\n\nJa, ja, Krazeks Spezialtopf stellt Köche zu 100% zufrieden! Ich bin sicher, dass er dem Besitzer gefallen wird.", progress = "Hallo, <Name>. Hat der Goblin Krazek meinen Topf repariert??", completion = "Er funktioniert wieder! Das ist toll! Jetzt kann ich mit dem Abendessen anfangen! Vielen Dank, &lt;Name&gt;.\n\nIch hoffe, dass Krazek Euch nicht zu viele Unannehmlichkeiten bereitet hat.", rewards = "Ihr bekommt:\n\nKappe der Harmonie"}
MultiLanguageQuestData['de'][26766] = {title = "Großes Ziel, großer Köder", objective = "Benutzt Mylras Messer, um 5 Basiliskenfleischstücke aus toten Kristallrückenbasilisken zu schneiden.", description = "Wir haben nur eine Chance, Abyssion zu fangen, <Name>. Wir müssen sie gut nutzen.\n\nWir testen die Falle am größten Steindrachen am Alabasterschelf.\n\nUm die Steinmatriarchin anzulocken, benötigen wir ausreichende Köder.\n\nNehmt dieses Messer und besorgt Euch 5 Basiliskenfleischstücke. Das sollte sogar für ihren Appetit genügen.", progress = "Habt Ihr das Fleisch besorgt?", completion = "Das sollte ausreichen, um die Bestie anzulocken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26767] = {title = "Anleitung zur Questerstellung", objective = "Erstellt eine Schnitzeljagdquest.Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als nächstes zu tun ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als nächstes zu tun ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26768] = {title = "Drachenfangen leicht gemacht", objective = "Besorgt Euch eine Drachenschlinge von den Zwielichtdrachenjägern.", description = "Das Fragment von einem Drachen bewachen zu lassen, war ein cleverer Schachzug. Sie können es immer an einen anderen Ort bringen, wenn wir uns ihm nähern.\n\nAbyssion zu fangen wird sehr schwer, aber ich habe einen guten Plan.\n\nDer Schattenhammer benutzt magische Fallen, um die Steindrachen an den Boden zu fesseln, während sie ihnen ihre Energie rauben.\n\nWenn wir an eine solche Falle kämen, könnten wir den Zwielichtdrachen vielleicht lange genug festhalten.\n\nGeht nach Osten zum Alabasterschelf und besorgt Euch eine Falle.", progress = "Wenn die Schlingen gut genug für Steindrachen sind, funktionieren sie vielleicht auch bei Abyssion.", completion = "Lasst uns schauen, ob die Schlinge auch etwas Größeres als einen Drachen festhalten kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26769] = {title = "Wilde Flussfahrt", objective = "Geht an Bord von Horton Hornbläsers Flussschiff nordöstlich von Ratschet und macht eine Flussfahrt zu Düsentopfs Außenposten.", description = "Genießt Euren Anteil an der Beute, <Name>!\n\nIch teile nicht gern, aber Geschäft ist Geschäft. Und diesem Betrüger Düsentopf stehen 10% dieses Schatzes zu. Könntet Ihr das zu ihm in seinem Außenposten nördlich von hier bringen?\n\nEr leitet eine kleine Forschungsstation stromaufwärts am Fluss. Verlasst die Stadt in Richtung Nordosten und sucht Horton Hornbläser auf. Er wird Euch kostenlos auf einem seiner Flussschiffe mitnehmen. Sagt ihm, ich hätte Euch geschickt!", progress = "Willkommen, <Klasse>. Seid Ihr gerade mit dem Schiff aus Ratschet gekommen? Gibt es Neuigkeiten?", completion = "&lt;Düsentopf entreißt Euch den Beutel mit Edelsteinen.&gt;\n\nGazlowe nennt das 10%? Sagt ihm, dass ich sie wiegen werde!\n\nWill er etwa, dass ich Euch ein Lieferhonorar zahle? Schon gut. Nehmt Euch was von der Beute!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26770] = {title = "Mystische Meister", objective = "Tötet 5 Mystiker der Nadelfelsen.", description = "Die Mystiker der Nadelfelsen haben die Kontrolle über die Fungusgiganten, die tief unten in ihrer Schlucht entstanden sind, übernommen. Jetzt wollen sie auch noch unsere Kriegskonstrukte übernehmen.\n\nGeht Richtung Norden nach Nadelfelsbruch und unternehmt etwas dagegen. Deswegen seid Ihr doch hier, oder?", progress = nil, completion = "Ein paar Steintroggs weniger ist nie schlecht. Ich freue mich, dass Ihr doch ein anständiger &lt;Klasse&gt; seid.\n\nSchon bald werden wir erfahren, wo genau mein Vater gefangen gehalten wird. Hoffentlich überlebt Ihr so lange.", rewards = "TroggbannbrustschutzSchulterpolster des TroggbrechersHandschuhe des TroggtötensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26771] = {title = "Fallenprobe", objective = "Legt die Falle mit dem Fleisch am westlichen Ende des Alabasterschelfs aus.", description = "Legt nun die Falle für die Matriarchin aus.\n\nGeht zum westlichen Ende des Alabasterschelfs und platziert die Falle mit dem Basiliskenfleisch in die Mitte des Futterplatzes.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich hoffe, dass die Falle bei Abyssion ebenso gut funktioniert.", rewards = "FallenauslösergamaschenKöderbeflecktes TuchAuf Euch wartet eine dieser Belohnungen:\n\nSeelenbinderhalsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26772] = {title = "Gedankensicht", objective = "Erbeutet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.", description = "Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.\n\nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.\n\nIhr habt Euch angefreundet mit Raptor: Ohgan'aka: Tochter von Ohgan.\n\nUm Freundschaft zu stärken, brauchen wir Federn.\n\nGeht nach Nordosten und Ihr werdet Federn finden, ja.", progress = "Raptor namens Ohgan'aka, immer noch Eure Freundin.", completion = "Ihr bringt Federn, ja.\n\nIhr könnt Anweisungen befolgen, ja.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26773] = {title = "Seht Raptor", objective = "Sprecht mit Priesterin Thaalia in Fort Livingston, um am Ritual der Gedankensicht teilzunehmen.", description = "Wir haben Federn, ja.\n\nWir haben <den/die:c> <Klasse>, ja.\n\nSprecht mit Priesterin, wenn bereit.", progress = "Eure Sicht nicht Ohgan'akas, nein.\n\nIhr seid nicht bereit.", completion = "Was hat Priesterin Euch gesagt?\n\nDer Raptor ist Tochter von Ohgan, Erbe von Mandokirs Thron.\n\nHah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26774] = {title = "Gedankenkontrolle", objective = "Erbeutet Braddoks Riesengehirn von Braddok in Zul'Mamwe.", description = "Gedankensicht nicht genug, nein.\n\nGedankenkontrolle viel mächtigere Magie, ja.\n\nMächtige Magie braucht mächtige Reagenzien und Trollgehirn ist mächtige Reagenz.\n\nBraddok in Zul'Mamwe, sehr klug, ja.\n\nGeht nach Süden und seht Euch an großes Gehirn von Braddok.", progress = "Riesengroße Zauber brauchen riesengroße Gehirne, ja.", completion = "Wartet, nächster Teil ist schwierig, ja.\n\nViele Möglichkeiten für Fehlschlag, ja.\n\nAber &lt;Name&gt; und &lt;Name&gt;'aka werden wieder zusammenkommen... ja, werden sie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26775] = {title = "Seid Raptor", objective = "Sprecht mit Priesterin Thaalia und helft dem gefangenen Schmetterschwanzjungen aus Zul'Gurub zu fliehen.", description = "Gedankenkontrolle sehr mächtig, ja.\n\nMit Glück könnt Ihr Ohgan'aka helfen, aus Zul'Gurub zu fliehen.\n\nDann wird Ohgan'aka wieder <Name>'aka werden!\n\nSprecht mit Priesterin, ja, und helft <Name>'aka bei Flucht.", progress = nil, completion = "Sehr schade, ja.\n\nDies ist der Wille der Geister, ja.\n\nWenn Ihr stärker seid, werdet Ihr vielleicht nach Zul'Gurub gehen und deine &lt;Name&gt;'aka von Mandokir zurückholen, ja.\n\nDoch erst einmal gibt Euch Priesterin dies.", rewards = "Umarmung des DschungelgeistesThaalias PantoffelnGürtel des HochschamanenAuf Euch wartet eine dieser Belohnungen:\n\nBand aus Raptorzähnen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26776] = {title = "Ghaliri", objective = "Kehrt zu Ghaliri in Fort Livingston im Nördlichen Schlingendorntal zurück.", description = "Priesterin spricht Gemeinsprache nicht gut, nein.\n\nVielleicht redet besser mit Ghaliri, vor diesem Zelt.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen, ja.", progress = nil, completion = "&lt;Ihr erklärt Ghaliri, was bisher geschehen ist.&gt;\n\nAnscheinend hat Jin'do überlebt und ruft seine Brüder zusammen, um Hakkar noch einmal in diese Welt zu holen. Es war gut, dass Ihr zu mir gekommen seid.\n\nIm Moment können wir nur abwarten und beobachten. Jin'do ist schwach. Wir sollten ihn niederstrecken, aber ich muss Rastakhans Entscheidung abwarten, bevor ich den Befehl dazu geben kann. Bis dahin müsst Ihr und Euer Raptor ausharren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26777] = {title = "Beruhigt die Geister", objective = "Beruhigt 5 verlorene Geister in Addles Siedlung.", description = "Dies ist ein tragisches Land mit einer Geschichte voller Gewalt und Verzweiflung. Viele Tote streifen in ihren Körpern durch das Land, aber manche sind nur verlorene Seelen, die verwirrt umherirren.\n\nSie verdienen Trost.\n\nViele dieser Seelen versammeln sich im Süden in Addles Siedlung und erscheinen Reisenden. Nehmt diesen Schwenker mit heiligem Weihrauch. Schwenkt ihn vor den verlorenen Seelen. Sein sanfter Duft wird ihnen Frieden bringen.", progress = nil, completion = "Ihr habt denen Frieden gebracht, die nur Leid kannten, &lt;Name&gt;. Seid stolz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26778] = {title = "Die Schreie der Toten", objective = "Tötet 20 beliebige Ghule auf dem Friedhof von Rabenflucht.", description = "Könnt Ihr sie hören, <Name>? Es sind so viele. Sie wandern an ihren Gräbern entlang, stolpern auf verwesenden Gliedmaßen über den kalten Boden.\n\nDie Toten schreien in der Stille. Sie leiden in ihrem eigenen Fleisch und wurden aus ihrem Schlaf gerissen! Jede Nacht gehe ich auf den Friedhof, um mehr von ihnen Frieden zu bringen, aber es sind nie genug.\n\nHelft mir, <Name>. Erlöst die Ghule, die über den Friedhof von Rabenflucht ziehen, von ihrem Leid. Tötet so viele Ihr könnt.", progress = nil, completion = "Doch die Schreie sind nicht mehr so laut. Möge das Licht Euch segnen, &lt;Name&gt;.", rewards = "Schwester Elsingtons GürtelAegis des GlaubensGamaschen des GhuljägersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26779] = {title = "Mambo in Zul'Mamwe", objective = "Tötet 16 Schädelspaltertrolle im Inneren von Zul'Mamwe.", description = "Das ganze Trollreich schämt sich für die Schädelspalter. Ihr lächerliches Gezanke mit den Blutskalpen hat das Nördliche Schlingendorntal entzweit. Während Stämme wie die Dunkelspeere und die Zandalari ein gutes Leben führen, kämpfen die Schädelspalter um Ruinen.\n\nMan hat mir erlaubt, Söldner zu belohnen, die gewillt sind, die Schädelspalter zu bestrafen. Ich fordere Euch und jeden, den Ihr kennt, auf, nach Zul'Mamwe im Osten zu reisen und diesen abtrünnigen Stamm zu vernichten.", progress = nil, completion = "Hier ist, wie versprochen, Eure Belohnung.. Ihr erfüllt die Trollnation mit Stolz.", rewards = "Verstrahlte Armschienen aus KrokodillederimitatBrustplatte von Zul'MamweSchulterstücke des abtrünnigen StammesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26780] = {title = "Wenn es Nacht wird im Dschungel", objective = "Löscht 8 Kohlenpfannen von Zul'Mamwe in Zul'Mamwe im Nördlichen Schlingendorntal.", description = "Die Nächte sind im Schlingendorntal besonders schön. Der Himmel ist voller Sterne und das Mondlicht dringt durch diese Blätter hier. Die ganze Nacht könnte ich den Himmel betrachten.\n\nLeider stören die Trolle in den Ruinen von Zul'Mamwe meine astronomischen Studien. Tag und Nacht brennen ihre Kohlenpfannen. Sie berauben mich der Dunkelheit, die ich brauche.\n\nBitte geht nach Zul'Mamwe östlich von hier, <Name> und löscht sie.", progress = nil, completion = "Ich sehe den Unterschied bereits deutlich. Ich kann die Nacht kaum erwarten. Dann kann ich endlich wieder meine Beobachtungen aufnehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26781] = {title = "Das Gedankenauge", objective = "Nehmt Mai'Zoth das Gedankenauge ab.", description = "Einer der zahlreichen Schätze dieses Tals befindet sich ganz in der Nähe, auf UNSERER Seite des riesigen Wirbelstroms. Ein Ogermagier auf dem Ogerhügel der Mosh'Ogg, nordöstlich von hier, besitzt es. Sein Name ist Mai'Zoth. Ich habe gehört, er sei boshaft und seine Magie stark.\n\nWenn er das Gedankenauge besitzen sollte, wird seine Magie noch stärker sein.\n\nBisher ist es mir nicht gelungen, nahe genug an ihn heranzukommen, um es ihm abzunehmen. Würdet Ihr es versuchen?", progress = "Habt Ihr das Auge?", completion = "Ihr habt das Auge geholt! Eure Macht ist der Stoff, aus dem Legenden sind, &lt;Name&gt;!\n\nDabei dachten mein Bruder und meine Schwester, wir würden nichts wertvolles in diesem Tal finden. Hah! Und ich fange erst an!", rewards = "Stab der ImaginationHandschuhe des AugenausreissersBeinschützer aus Fort LivingstonIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26782] = {title = "Die Schatzkiste der Mosh'Ogg", objective = "Erbeutet die Schatzkiste der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", description = "Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass <ein/eine:c> <Klasse> dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?\n\nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh'Ogg im Nordosten entdeckt habe.\n\nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?", progress = "Wieso finden ausgerechnet OGER immer wertvolle Artefakte?", completion = "&lt;Wulfred wirft einen Blick in den Kasten.&gt;\n\nDamit... damit hatte ich nicht gerechnet. Ich dachte, es wäre ein... ein... \n\n&lt;Seine Augen werden glasig.&gt;\n\nÄhem! Entschuldigt. Ich weiß nicht, was über mich gekommen ist. Ich schicke das nach Süden, zur Grabungsstätte der Forscherliga am Kap. Vielleicht wissen sie etwas damit anzufangen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26783] = {title = "Die Schatzkiste der Mosh'Ogg", objective = "Erbeutet die Schatzkiste der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", description = "Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass <ein/eine:c> <Klasse> dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?\n\nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh'Ogg im Nordosten entdeckt habe.\n\nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?", progress = "Wieso finden ausgerechnet OGER immer wertvolle Artefakte?", completion = "&lt;Wulfred wirft einen Blick in den Kasten.&gt;\n\nDamit... damit hatte ich nicht gerechnet. Ich dachte, es wäre ein... ein... \n\n&lt;Seine Augen werden glasig.&gt;\n\nÄhem! Entschuldigt. Ich weiß nicht, was über mich gekommen ist. Ich schicke das nach Süden, zur Grabungsstäte der Forscherliga am Kap. Vielleicht wissen sie etwas damit anzufangen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26784] = {title = "Schlammiges Wasser", objective = "Tötet schlammige Wasserelementare und sammelt 5 Strudelkerne.", description = "Die Elementarkräfte sind stark hier im Hochland, <Name>. Deshalb hat der Schattenhammer hier seine Festung errichtet.\n\nIn den richtigen Händen kann diese Energie für etwas Produktives genutzt werden... zum Beispiel für ein Portal nach Orgrimmar.\n\nNordwestlich von hier, an der Mündung des Verralls sind Wasserelementare durch die Taten unserer Feinde flussaufwärts aufgeschreckt worden. Zerstört sie und sammelt 5 Strudelkerne. Ihr werdet nicht nur den Fluss beruhigen, sondern auch unser Portal mit Energie versorgen.", progress = "Ich hoffe, die Kämpfe im Fluss waren nicht allzu gefährlich.", completion = "Die sind genau richtig! Die unruhigen Wasser dieses aufgewühlten Flusses werden jetzt so viel mehr tun, als nur Schlick oder Stein zu bewegen ... Sie werden Euch von einem Kontinent zum anderen bewegen.\n\nErledigt Eure restlichen Geschäfte hier in Drachenmal. Dann sollten wir fortfahren können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26785] = {title = "Mitglied der Meute", objective = "Sprecht mit Lehrling Fess an der Kreuzung westlich von Dunkelhain im Dämmerwald.", description = "Ich habe immer versucht, mein wahres Ich vor den Einwohnern Dunkelhains zu verbergen... Sie scheinen Worgen nicht zu mögen. Es gibt allerdings außerhalb der Stadt noch mehr von uns.\n\nMeine Begleiter, mit denen ich zuerst hier angereist bin, durchsuchen die Wälder nach wilden Worgen. Sie glauben, dass einige von ihnen - die mit den verräterischen Zeichen - wieder zur Vernunft gebracht werden können.\n\nIch bin noch nicht soweit, mich ihnen wieder anzuschließen. Bitte lasst Lehrling Fess an der Kreuzung westlich der Stadt wissen, dass ich noch eine Weile länger in Dunkelhain verweilen werde.", progress = nil, completion = "Tobias hält sich immer noch in der Stadt auf?\n\nMeister Harris hat ihn davor gewarnt, dem Schicksal seines Bruders weiter nachzugehen. Wir haben schließlich alle ein neues Leben angefangen. Aber es ist schwer, die Vergangenheit hinter sich zu lassen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26786] = {title = "Den Landungspunkt sichern", objective = "Sprecht mit Artesh im Hafen des Drachenmals im Schattenhochland.", description = "Etwas bereitet mir Kopfzerbrechen, <Name>. Die Zwielichtdrachen wussten genau, wo und wann sie unsere Luftflotte angreifen mussten. Man könnte glauben, dass sie unsere Pläne kennen.\n\nZwielichtspione verstecken sich mitten unter uns!\n\nIch werde mit einem der verbliebenen Schiffe nach Orgrimmar zurückkehren und dann werden Köpfe rollen. Ihr müsst hier bleiben. Ich brauche Euch hier, um diese Frontlinie zu sichern. Die Schamanen des Drachenmals sind mächtig. Ich habe sie darum gebeten, ein Portal nach Orgrimmar zu öffnen. Und ich brauche Eure Hilfe.\n\nAlso. Fangt an, zu helfen!", progress = nil, completion = "Euer Kriegshäuptling ist entschlussfreudig, &lt;Name&gt;. Er setzt Dinge in die Tat um. Ich mag ihn.\n\nLasst uns über das Portal sprechen, das er möchte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26787] = {title = "Bärendienst", objective = "Sammelt 8 Gehirne von Schwarzbären", description = "Ich habe Angst, dass ... nun ja, ich habe einfach nur Angst. Außerdem tut es mir leid, dass ich um einen weiteren Gefallen bitten muss.\n\nMeister Harris benötigt Gehirne. Bärengehirne. Offenbar sind sie Teil des Serums - oder ein gleichwertiger Ersatz.\n\nEs gibt viele Schwarzbären in den Wäldern im Westen und entlang des Flussufers, aber... Ich kann das nicht! Ich habe sogar mit einem Gewehr viel zu viel Angst, um dort hinauszugehen und diesen riesigen Ungeheuern gegenüberzutreten. Bitte, lasst mich Euch bezahlen, damit Ihr mir einige bringt!", progress = "Habt Ihr sie bekommen? Habt Ihr sie?", completion = "Danke! Oh, danke. Ich hätte nie gedacht, dass ich einmal so glücklich sein werde, diese Gehirne zu riechen. Jetzt, da ich sie nicht selber holen musste, bin ich es!\n\nHier ist Eure Belohnung, wie versprochen ...", rewards = "Johns modische RobeRabenfluchtsandalenAuf Euch wartet eine dieser Belohnungen:\n\nBibberndes Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26788] = {title = "Unseren Sieg untermauern", objective = "Sammelt 10 Haufen Verrallschlamm.", description = "Unsere Allianz mit dem Drachenmalklan ist unter Dach und Fach, aber dieser Hafen ist für Kämpfe immer noch ungeeignet. Diese hauchdünnen Holzwände sind des Kriegshäuptlings unwürdig.\n\nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, wie sie es im Verrall getan haben, entsteht ein seltsamer Schlamm. Er lässt sich problemlos verstreichen und wenn er trocknet, ist er härter als der härteste Stein. Er ist der perfekte Mörtel für große Bauvorhaben.\n\nGeht zur Flussmündung nordwestlich von hier und sammelt Verrallschlamm ein. Selbst eine kleine Menge wird lange reichen.", progress = "Habt Ihr den Schlamm? Der Bau der neuen Wände hat bereits begonnen!", completion = "&lt;Ornak lässt den Schlamm von seinen Fingerspitzen tropfen.&gt;\n\nDas ist genau das richtige Zeug! Ich werde es sofort mit Kies und Wasser vermischen und verdünnen. Nur einige Handvoll hiervon können den Zement für einen ganzen Steinturm aufbessern.\n\nWir haben große Pläne für diesen Hafen, &lt;Name&gt;, Ihr werdet schon sehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26789] = {title = "Die Axt im Walde", objective = "Tötet 5 Test-Kobolde", description = "<Name>, wir haben ein Problem! Ich habe den Dämonenhund Magmadar auf dieser Lichtung aufgespürt, aber als wir uns ausruhten, hat eine Koboldbande unsere Kampfäxte gestohlen! Ihr müsst sie zurückholen, damit Magmadar uns nicht unvorbereitet erwischt! Beeilt Euch, er kann jeden Moment aufwachen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26791] = {title = "Wie Pilze aus dem Boden", objective = "Interagiert mit einem Kriegswächter und benutzt ihn, um 5 Riesenpilze zu vernichten.", description = "Die Mystiker der Steintroggs erschaffen diese Fungusmissgeburten aus den Riesenpilzen im Norden.\n\nIch möchte, dass Ihr einen Kriegswächter mitnehmt, damit er Euch bei den Riesen und den Steintroggs hilft. Macht Euch auf den Weg zu den Riesenpilzen und zielt auf sie. Ich und meine Geomanten werden sie in Grund und Boden stampfen, noch bevor die Mystiker ihr Ritual vollenden.", progress = nil, completion = "Jetzt haben sie keine dieser Pilzriesen mehr, die sie gegen uns einsetzen könnten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26792] = {title = "Fungusmissgeburten", objective = "Tötet 5 Fungusmissgeburten.", description = "Schnappt Euch einen Kriegswächter und vernichtet die Fungusmissgeburten, während Ihr da draußen seid.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Vor der Zerstörung der Weltensäule kannten wir derartige Probleme in Tiefenheim nicht.\n\nEuer Irdener Ring muss den Schaden beseitigen, bevor es zu spät ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26793] = {title = "Das verwitterte Grab", objective = "Sprecht mit Sirra Von'Indi in Dunkelhain.", description = "Auf dem Schild an dem verwitterten Grab steht nur:\n\nMORGAN LADIMORE\n\n<Bei genauerer Untersuchung bemerkt Ihr, dass die Erde auf dem Grab vor Kurzem aufgewühlt wurde. Ein großer Teil der Erde scheint verlagert worden zu sein...>", progress = nil, completion = "Morgan Ladimore?\n\nAh, ja, natürlich. Das ist eine lange und traurige Geschichte. Ich kannte ihn, nun ja, bevor er in den Krieg zog. Damals sah ich ihn zum letzten Mal. Er war ein nobler und guter Mann, aber es nahm ein schlimmes Ende für ihn.\n\nMoment, ich müsste hier etwas haben, das Euch die Geschichte näher bringen kann als meine lückenhaften Erinnerungen ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26794] = {title = "Morgan Ladimore", objective = "Sprecht mit Kommandantin Althea Schwarzhaupt in Dunkelhain.", description = "<Er durchsucht die Regale und zieht ein ledergebundenes Buch hervor.>\n\nWenn Ihr mehr wissen möchtet, solltet Ihr Althea fragen. Sie hat sich in letzter Zeit mit den... Ärgernissen, die ihn betreffen, beschäftigt.", progress = nil, completion = "Morgan Ladimore? Nie gehört...\n\nOh, Ihr meint Mor'Ladim! Dann kennt Ihr die Geschichte wohl noch nicht.\n\nIch erzähle Euch die Kurzfassung. Ein mächtiges untotes Wesen, das sich Mor'Ladim nennt, ist im Dämmerwald gesehen worden. Soweit wir wissen, handelt es sich dabei um den untoten Körper von Morgan Ladimore, von dem Ihr anscheinend gehört habt. Er bereitet uns jede Menge Probleme, greift Wachen auf Patrouille an und bringt Leute um.\n\n&lt;Sie mustert Euch.&gt;\n\nIhr wirkt recht fähig, vielleicht könnt Ihr ihm ja Frieden bringen.", rewards = "Ihr bekommt:\n\nDie Geschichte von Morgan Ladimore"}
MultiLanguageQuestData['de'][26795] = {title = "Mor'Ladim", objective = "Tötet Mor'Ladim und bringt seinen Schädel zu Kommandantin Althea Schwarzhaupt in Dunkelhain.", description = "Wie ich von meinen Spähern höre, irrt Mor'Ladim auf merkwürdig verschlungenen Pfaden durch den Dämmerwald. Sein Weg führt ihn dabei über den Friedhof. Wir haben ihn hinter dem Haus auf dem Hügel begraben. Wisst Ihr, wo das ist?\n\nIch kann leider nichts tun, um Euch zu helfen, aber ich wünsche Euch viel Glück.", progress = "Ich mache Euch keinen Vorwurf, wenn Ihr Schwierigkeiten mit ihm habt, <Name>. Einige unserer stärksten Behüter sind Mor'Ladim zum Opfer gefallen.", completion = "Ihr habt ihn getötet? Das ist eine großartige Leistung, &lt;Name&gt;! Im Namen der Einwohner Dunkelhains und der Nachtwache, danke ich Euch.\n\nAh... da wäre allerdings noch eine Kleinigkeit...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26796] = {title = "Die überlebende Tochter", objective = "Sprecht mit Behüterin Sarah Ladimore in Dunkelhain.", description = "Ich hätte Euch dies schon früher mitteilen müssen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", progress = nil, completion = "Ja? Mein Vater...\n\n&lt;Sie senkt den Blick.&gt;\n\nIch wünschte... ich hätte etwas für ihn tun können... Hätte ich nur mit ihm gesprochen, bevor er...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26797] = {title = "Die Liebe einer Tochter", objective = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", description = "Hier, nehmt das und legt es auf sein Grab. Vielleicht... weiß er irgendwie, dass es mir gut geht und dass keiner von uns ihn dafür verantwortlich macht, was geschehen ist.\n\n<In ihren Augen stehen Tränen. Sie streift einen Ring von einem Finger der rechten Hand ab und drückt ihn Euch in die Hand.>\n\nUnd... danke, <Name>.", progress = "Lasst mich in Ruhe...", completion = "&lt;Eine geisterhafte Stimme erklingt im Wind...&gt;\n\nIst das...? Sarah? Kann es sein, dass sie noch lebt? Mir fällt ein Stein vom Herzen...\n\n&lt;Name&gt;. Nehmt mein Schwert Archeus. Jetzt, da meine Seele sich zur Ruhe begibt, benötige ich es nicht länger. Es wurde geschmiedet, um Gutes zu tun. Ich habe mich unwürdig erwiesen, es zu führen. Doch vielleicht könnt Ihr das Licht damit weitertragen.\n\nLys, meine Geliebte...", rewards = "Ihr bekommt:\n\nWiederhergestelltes Archeus"}
MultiLanguageQuestData['de'][26798] = {title = "Der Kriegshäuptling wird zufrieden sein", objective = "Benutzt das Portal im Hafen des Drachenmals, um nach Orgrimmar zu gelangen. Meldet Euch dort bei Garrosh Höllschrei.", description = "Das Portal ist fertig!\n\nEs ist noch nicht stark genug, um eine ganze Armee zu transportieren, aber wir können die Verbindung lange genug aufrechterhalten, um wichtige Personen in beide Richtungen hindurchschreiten zu lassen.\n\nDer Kriegshäuptling will bestimmt über Eure Fortschritte hier informiert werden. Geht durch das Portal nach Orgrimmar und überbringt die Neuigkeiten Garrosh Höllschrei.", progress = nil, completion = "&lt;Klasse&gt;, Ihr seid von den Drachenmalorcs zurückgekehrt. Ich nehme also an, dass das Portal funktioniert? Gut.\n\nBevor Ihr wieder an Eure Arbeit dorthin zurückkehrt, gilt es, hier in Orgrimmar noch ein schmutziges Geschäft zu bereinigen ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26799] = {title = "Die nicht gerettet werden konnten", objective = "Tötet 6 hirnlose Zombies.", description = "Die Val'kyr erwecken jeden Tag hunderte von Leichen. Agatha hat Euch vor nur wenigen Momenten erweckt. Aber nicht alle haben Euer Glück.\n\nEinige behalten ihren freien Willen, leben aber in ewiger Angst und Verwirrung. Sie laufen normalerweise in die Wälder und schrecken vor ihrem eigenen Anblick zurück.\n\nAndere werden völlig wahnsinnig und ziehen ziellos umher. Sie werden oft gewalttätig und müssen zerstört werden.\n\nDas ist Eure Aufgabe, <Name>. Zerstört sie, auch wenn sie einst unsere Brüder und Schwestern waren.", progress = nil, completion = "Nicht einmal die Macht der Val'kyr reichte aus, um diese Kreaturen zu retten. Sie waren von Anfang an verdammt.\n\nIch habe Euch etwas Ausrüstung besorgt, &lt;Name&gt;. Es ist nicht viel, aber es wird helfen. Bitte, sucht Euch etwas aus.", rewards = "FlachshandschuheRamponierter UmhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26800] = {title = "Rekrutierung", objective = "Durchsucht Todesend und die Umgebung nach 6 Leichnamen der Scharlachroten, dann zeigt auf sie, damit Darnell sie einsammelt.", description = "Wir haben Leichen aus dem Silberwald, aus dem Hügelland... ach, von überall herbringen lassen, wo wir sie bekommen konnten. Wir können es uns jedoch nicht leisten, die Leichen zu ignorieren, die direkt vor unserer Tür liegen.\n\nDie letzten Überbleibsel des Scharlachroten Kreuzzuges treiben sich hier in Tirisfal herum. Wir haben sie zwar aus Todesend vertreiben können, aber mehrere ihrer Leichen liegen um die Gebäude im Norden und Osten herum.\n\nGeht und findet sie... und nehmt diesen Darnell mit. Er sieht stark genug aus, um ein paar Leichen tragen zu können.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;, ich wusste, dass Ihr nicht völlig nutzlos seid. Hier, nehmt Euch etwas hiervon. Wir Todeswachen haben solches Zeug stapelweise herumliegen.", rewards = "FlachsgürtelRostmetallarmschienenKurzes NachtsaugercapeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26801] = {title = "Geißel an unseren Grenzen", objective = "Tötet 8 Untote außerhalb von Todesend. Ihr könnt sowohl elende Ghule als auch klappernde Skelette töten.", description = "Wenn Ihr den Verlassenen nützlich sein wollt, müsst Ihr lernen, wie man kämpft. Und es gibt keine besseren Ziele als die Geißeldiener, die uns immer noch belästigen.\n\nDie elenden Ghule und klappernden Skelette, die im Norden und Osten herumlaufen, sind ehemalige Kämpfer der gefallenen Geißel. <Ein neuer/Eine neue:c> <Klasse> wie Ihr sollte dieser Herausforderung gewachsen sein.\n\nTrödelt nicht herum – sprecht erneut mit mir, wenn Ihr fertig seid.", progress = nil, completion = "Eure Stärke wächst, &lt;Name&gt;. Ich habe solche wie Euch schon gesehen. Ihr werdet Todesend verlassen und Größeres in Angriff nehmen, ehe Ihr Euch verseht. Vergesst nur nicht, wo Ihr einmal angefangen habt.\n \nEs liegt noch viel Arbeit vor Euch, &lt;Klasse&gt;.", rewards = "FlachsstiefelAasfressertunikaStreifergamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26802] = {title = "Die Verdammten", objective = "Besorgt 4 Aasfressertatzen und 4 Nachtsaugerflügel.", description = "Zuerst... schaut mal Eure Rüstung an. Ihr seht ganz zerlumpt aus, <Klasse>.\n\nWenn Ihr in einem Stück bleiben wollt - und das wollt Ihr ganz sicher - kann ich vielleicht helfen. Wenn Ihr mir Pfoten und Flügel von den Wölfen und Fledermäusen in der Nähe bringt, finde ich Euch vielleicht etwas Rüstung. Ihr findet diese Kreaturen nördlich und westlich von hier.", progress = "Bemüht Euch, unverletzt zu bleiben, bis ich Euch irgendeine Rüstung besorgt habe.", completion = "Danke, &lt;Name&gt;. Diese Rüstung sollte Euch etwas helfen.\n\nHoffentlich hilft sie Euch mehr als ihrem letzten Träger...", rewards = "Alter LedergürtelFlachsarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26803] = {title = "Fehlende Berichte", objective = "Sprecht mit Windreitermeister Doras in Orgrimmar.", description = "Garrosh ist ungehobelt und spricht kaum ein Wort, aber er meint es gut. Bald wird er erkennen, welch wertvoller Verbündeter Euer Volk ist.\n\nIch warte auf Berichte zu den letzten Regungen der Allianz in Durotar, aber sie sind noch nicht eingetroffen. Würdet Ihr für mich nach Klingenhügel reisen und persönlich darum bitten? Am einfachsten gelangt Ihr mit einem Windreiter dorthin. Für eine kleine Gebühr leiht Doras, der Windreitermeister in Orgrimmar, Euch einen seiner Windreiter. Ihr findet ihn auf der Anhöhe nördlich des Tals der Stärke.", progress = nil, completion = "Ihr müsst also schnell nach Klingenhügel? Kein Problem. Einer meiner Windreiter kann Euch im Handumdrehen dorthin bringen. Die Leihgebühr beträgt nur ein paar Münzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26804] = {title = "Flug nach Klingenhügel", objective = "Sprecht mit Doras, um einen Windreiterflug nach Klingenhügel zu erwerben. Sobald Ihr angekommen seid, sprecht mit Gar'Thok.", description = "Wenn Ihr bereit seid, einen Windreiter nach Klingenhügel zu nehmen, sprecht mich einfach erneut an. Verschwendet keine Zeit, wenn Ihr angekommen seid, und meldet Euch sofort bei Gar'Thok. Er ist für die Berichte zu den aktuellen Aktivitäten der Allianz in Durotar verantwortlich.", progress = nil, completion = "Etrigg hat Euch geschickt? Der Kriegshäuptling muss ja auf meine Berichte brennen! Ich hätte sie ihm schon lange geschickt, aber wir decken jeden Tag neue Einmarschpläne der Allianz in Durotar auf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26805] = {title = "Auf zum Kap!", objective = "Sprecht mit Robert Rhodes, um einen Flug zu der Grabungsstätte der Forscherliga am Schlingendornkap zu bekommen.", description = "Die Forscherliga entwickelt sich ständig weiter, <Name>. Sie haben nicht nur Worgen wie mich aufgenommen, sondern sie haben auch ihre Suche nach Artefakten ausgeweitet. Einer unserer Besten, Bronwyn Hackschlag, hat im Süden ein Lager aufgeschlagen. Er glaubt, dass dort ein Gegenstand verborgen liegt, der von den Titanen stammt.\n\nBronwyn hat mich darum gebeten, einige Aufgaben hier im Norden zu übernehmen. Eine dieser Aufgaben ist es, mögliche Rekruten zu finden. Ihr scheint aus dem richtigen Holz geschnitzt zu sein. Sprecht mit Robert Rhodes, dem Flugmeister. Er wird dafür sorgen, dass Ihr dorthin gelangt. Auf Bronwyns Kosten.", progress = nil, completion = "Wulfred hat einen guten Blick. Ihr werdet hier in meinem Lager schon zurechtkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26806] = {title = "Berichte für Orgrimmar", objective = "Bringt Gar'Thoks Berichte zu Burok in Klingenhügel.", description = "Etrigg muss sich mit dem Teil des Berichts zufriedengeben, den ich schon fertig habe. Sagt ihm, dass ich bald noch mehr schicke.\n\n<Gar'Thok reicht Euch einen Stapel unordentlich gefalteter Papiere.>\n\nDie hier sollten eigentlich die wichtigsten Details zum Anstieg der Allianztruppen in Nordwacht enthalten. Bitte sagt Etrigg, dass es mir leid tut und lasst ihn wissen, dass wir hier alle Hände voll zu tun hatten. Schließlich mussten wir Klingenhügel sichern. Wenn Ihr bereit seid, nach Orgrimmar zurückzukehren, sprecht einfach mit Burok und leiht Euch einen Windreiter.", progress = "Seid Ihr bereit, nach Orgrimmar zurückzukehren?", completion = "Seid Ihr bereit, mit diesen Berichten nach Orgrimmar zurückzukehren? Ich kann sofort einen Flug für Euch arrangieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26807] = {title = "Rückkehr zu Etrigg", objective = "Sprecht mit Burok und erwerbt einen Flug zurück nach Orgrimmar. Sobald Ihr gelandet seid, bringt Gar'thoks Berichte zu Etrigg im Tal der Stärke.", description = "Da Ihr bereits mit Doras gesprochen habt, könnt Ihr einen Windreiter für den Rückflug nach Orgrimmar mieten. Jedes Mal, wenn Ihr in einer neuen Stadt ankommt, solltet Ihr Euch mit dem ansässigen Flugmeister unterhalten. Danach könnt Ihr seine Dienste in Anspruch nehmen, um weite Strecken schnell zurückzulegen.\n\nSprecht erneut mit mir, wenn Ihr bereit seid, einen Rückflug nach Orgrimmar zu erwerben. Bringt diese Berichte zu Etrigg im Tal der Stärke, sobald Ihr gelandet seid.", progress = "Habt Ihr diese Berichte schon abgeliefert?", completion = "&lt;Etrigg betrachtet die Berichte aufmerksam.&gt;\n\nDie Allianz ist anmaßender, als wir dachten! Ich spreche sofort mit dem Kriegshäuptling wegen Verstärkung. Vielen Dank, dass Ihr mir diese Berichte so schnell gebracht habt. Ich hoffe, dass dieser Betrag ausreicht, um Eure Reiskosten zu decken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26808] = {title = "Maywiki", objective = "Bringt Linzis Geschenk zu Maywiki von Zuldazar, die sich an der Grabungsstätte der Forscherliga befindet.", description = "<Linzi sieht besorgt aus.>\n\nWisst Ihr, hinter dem Kistenstapel verbirgt sich ein Troll. Sie muss furchtbar traurig sein, wenn sie nicht herauskommen und mit niemand reden will.\n\n<Linzi legt einige Akirisschilfrohre in ein Halstuch und bindet sie zusammen.>\n\nHier, gebt sie ihr. Sie sind sehr weich. Vielleicht ist es damit dort hinten ein wenig gemütlicher für sie.", progress = "Was soll das, <Klasse>?", completion = "&lt;Die Trollfrau schaut in das Paket.&gt;\n\nIch danke Euch. Ihr könnt Eurem Zwergenfreund sagen, dass ich nicht traurig bin. Ich warte. Auf Euch.\n\nIch habe festgestellt, dass Ihr der vielversprechendste &lt;Volk&gt; in dieser seltsamen Stadt seid. Ich habe eine Aufgabe für Euch, falls Ihr sie annehmen möchtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26809] = {title = "Durch die Hintertür", objective = "Legt den Weihrauch der Gurubashi vor das Totem von Hir'eek und lauscht dann Zanzils Verschwörung.", description = "Ich verfolge einen Vertriebenen der Gurubashi. Er heißt Zanzil der Ausgestoßene. Vor Kurzem berichteten meine Brüder aus dem Norden mir, dass er plant, sich wieder in die Gesellschaft einzugliedern. Sein erster Schritt war, einen Abgesandten zu den Schädelspaltern zu schicken. Das sind keine guten Nachrichten.\n\nIch möchte, dass Ihr versucht, Einblick in Zanzils neueste Pläne zu erhalten. Nehmt diesen Weihrauch und stellt ihn vor das Fledermaustotem in den Ruinen von Jubuwal, die sich nördlich von hier befinden. Dann wird Hir'eek Euch führen.", progress = nil, completion = "Das hatte ich vermutet. Zanzil ist zu überheblich, um sich in die Streitigkeiten zwischen den Blutskalpen und den Schädelspaltern einzumischen. Nein, er ist Teil eines größeren Komplotts ... Jin'do der Verhexer benutzt ihn, um mit seiner Hilfe Hakkar zurück nach Zul'Gurub zu holen.\n\nGut, dass wir das jetzt herausgefunden haben, denn noch gibt es dafür eine einfache Lösung ...", rewards = "Schleier des stillen ZuhörersSchiftung der FledermausAuf Euch wartet eine dieser Belohnungen:\n\nKleiner Weihrauchbeutel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26810] = {title = "Beseitigt den Ausgestoßenen", objective = "Begebt Euch zu den Ruinen von Aboraz am Schlingendornkap und nehmt Euch Zanzil den Ausgestoßenen vor.", description = "Ihr müsst Zanzil töten. Ihr seid auf Hir'eeks Schwingen geritten und habt durch Hir'eeks Augen gesehen; Ihr wisst, wo Zanzil sich in den Ruinen von Aboraz versteckt hält. Begebt Euch dorthin und tötet ihn.\n\nOh, und <Volk> ... Falls wir getrennt werden, solltet Ihr diesen Fetisch benutzen. Er funktioniert nur innerhalb von Schlingendorn, aber er wird Euch schnell zu mir zurückbringen, falls es notwendig sein sollte.\n\nViel Glück, <Volk>. Zanzil ist kein gewöhnlicher Gegner.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26811] = {title = "Durch das Trollloch", objective = "Benutzt Zanzils Portal und betretet Zul'Gurub.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", description = "Es sieht so aus, als ob Zanzils Portal nach Zul'Gurub immer noch offen ist. Zul'Gurub ist ein gefährlicher Ort, aber Maywiki hat Euch mit dieser Aufgabe betraut.\n\nDas Portal liegt einladend vor Euch und wartet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26812] = {title = "Hohepriesterin Jeklik", objective = "Zerstört den Leib von Hohepriesterin Jeklik, bevor Zanzil sie wiederbeleben kann.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", description = "Vor Euch ragt eine Rampe auf, die zu einer der vielen Terrassen der Stadt führt. Vor Euch befinden sich Totems, die wie Fledermäuse aussehen. Sie deuten an, dass Ihr Euch in der Hochburg der Hohepriesterin Jeklik befindet, einer Anhängerin von Hir'eek.\n\nJeklik betete Hakkar an und ist eine der Priesterinnen, die Zanzil wiederbeleben will. Wenn Ihr Euch beeilt, könnt Ihr die Wiederbelebung vielleicht verhindern.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26813] = {title = "Hals über Kopf nach Zul'Gurub", objective = "Benutzt Zanzils Portal.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", description = "Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26814] = {title = "Hohepriester Venoxis", objective = "Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", description = "Venoxis war der Zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der Nächste sein.", progress = nil, completion = "Ich bitte Euch, Zanzil den Ausgestoßenen zu töten, einen kleinen, isolierten Vertriebenen der Gurubashi - und was tut Ihr? Stürzt Euch Hals über Kopf in die Hauptstadt der Gurubashi und eliminiert einen ihrer Hohepriester! Beinahe sogar zwei! Es gibt nur ein Wort, um ein derartig tollkühnes und verwegenes Unterfangen zu beschreiben:\n\nHeldentum.\n\nJin'do der Verhexer wandelt immer noch in den Mauern von Zul'Gurub, aber er hat ein Bein verloren, als Ihr Jeklik zerschmettert habt. Den heutigen Kampf haben wir für uns entschieden.", rewards = "Stiefel des LeichtsinnigenUmhang der großen VorhabenAuf Euch wartet eine dieser Belohnungen:\n\nMaywikis Lieblingsring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26815] = {title = "Zanzils Geheimnis", objective = "Beschafft 5 Phiolen mit Zanzils Mixtur.", description = "Vor vielen Jahren haben die Gurubashi einen der Ihren aus Zul'Gurub verbannt: einen Troll namens Zanzil. Die Gründe dafür sind nicht ganz klar. Ich vermute aber, es hatte etwas damit zu tun, dass er gerne jedem, der ihm über den Weg lief, starke, verhaltensändernde Mittel verabreichte. Die Gurubashi Priester und ihr Blutgott wurden vernichtet, aber Zanzil der Ausgestoßene existiert immer noch...\n\n... ebenso wie sein starkes, verhaltensänderndes Mittel.\n\nIch benötige diese Mixtur für meinen nächsten Test. Sucht bei den Zombies im Norden.", progress = "Ausgezeichnet ... Ihr seid noch kein Zombie. Das ist gut.\n\nOh, ääh ... nichts. Es ist nur ... das war ein mögliches Risiko. Habe ich vergessen, Euch zu warnen?", completion = "&lt;Dask analysiert sorgfältig die seltsame, chemische Verbindung.&gt;\n\nDiese Mixtur ist... PERFEKT! Wollen wir doch mal sehen, was sie mit Eurem Artefakt, das möglicherweise titanischen Ursprungs ist, anstellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26816] = {title = "Zutaten für eine Katastrophe", objective = "Beschafft Zanzils Rezeptur von einem seiner Anhänger in den Ruinen von Aboraz.", description = "Habt Ihr die Explosion gesehen, die ich verursacht habe? Ich muss 10 Zoll in die Höhe geflogen sein!\n\nJetzt muss ich nur noch an Zanzils Rezept kommen, damit ich herausfinden kann, warum das passiert ist. Einer von Zanzils Lakaien in den Ruinen von Aboraz muss es bei sich haben. Begebt Euch nach Osten, zu der Küste des Kaps, und ergattert es für mich!", progress = "Hat er Schimmerkraut verwendet? Ich schätze, er hat Schimmerkraut verwendet.\n\nNein, wartet ...Bernsteinsamen! Es muss sich um Bernsteinsamen handeln.", completion = "Das ist faszinierend! Denkt doch nur an all die Anwendungsmöglichkeiten!\n\nNochmals, vielen Dank, &lt;Name&gt;. Denkt daran, wenn Ihr jemals etwas zusammengemischt haben möchtet ... GANZ GLEICH worum es sich handelt ... Dem Kolben vertraut - mit Eurem Kraut!", rewards = "Dasks UmhangGamaschen mit mysteriösen FleckenGlasverkrustete StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26817] = {title = "Das Reinheitsgebot", objective = "Beschafft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen am Schlingendornkap.", description = "Diese Körperflüssigkeit allein wird nicht reichen. Sie ist zu dickflüssig. VIEL zu dickflüssig.\n\nDie Naga im Westen behüten einen Schrein, aus dem das einzig klare Wasser diesseits vom Dämmerwald fließt. Für die meisten Tränke verwende ich Flusswasser, aber Bronwyn verlangt Präzision!\n\nBeschafft Wasser aus dem Nek'maniquellbrunnen, der sich an dem höchsten Punkt des Nagalagers befindet. Viel Glück.", progress = "<Dask betrachtet gespannt Euer Bündel, als Ihr Euch nähert.>", completion = "Wisst Ihr, wie schwer es ist, hier am Schlingendornkap frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so erbittert verteidigen.\n\nNun gut, lasst uns mit der Mixtur beginnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26818] = {title = "Plüschpelze", objective = "Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.", description = "Hallo, ich bin die Händlerin der Stadt! Und Bronwyn ist mein Vater!\n\nTut mir leid, ich sollte nicht so aufgeregt sein. Mein Vater sagt, das ist nicht professionell.\n\nWie auch immer ... Die Leute kommen immer zu mir und fragen mich nach schwerem Leder oder rauem Balg. Doch ich glaube, es würde ihnen gefallen, wenn ich auch einige weiche Materialien hätte ... wie Tigerfell! Glaubt Ihr, Ihr könntet mir welches besorgen?\n\nIhr findet einige Panther hier in der Nähe, aber wenn Ihr die großen Tiger sucht, müsst Ihr Richtung Nordwesten gehen. Sie sind nördlich des großen Trollgebiets.", progress = "Oooh... Ich hoffe, sie sind weich!", completion = "&lt;Linzi prüft die Felle und lächelt.&gt;\n\nDie sind so schön und angenehm! Ich glaube, meine Kunden werden sie LIEBEN!", rewards = "Flauschige BeinwärmerSamtige WesteWeiche HandschuheEisbeins ErsatzhalsbandIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26819] = {title = "Bündelweise Akiris", objective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", description = "Die Forscher der Naga, die sich westlich von hier befinden, haben ein wertvolles Ozeanschilf bei sich: Akirisschilfrohr. Händler stellen daraus Arzneien und Verpackungen her; Handwerker füttern Rüstungen oder umwickeln Zigarren damit.\n\nWenn wir mit dem Graben fertig waren, hat mein Vater mir abends gezeigt, wie man es verwendet. Leider haben wir keins mehr. Würde es Euch etwas ausmachen, uns noch mehr davon zu holen?", progress = "Willkommen zurück!", completion = "Hurra! Es ist schon viele Tage her, dass wir Akirisschilfrohr hatten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26820] = {title = "Wenn sie sie einfach herumliegen lassen ...", objective = "Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.", description = "Vater sagt, dass ein verantwortungsvoller Händler immer nach lohnenden Geschäften Ausschau hält. Ich versuche, auf Schritt und Tritt nach guten Geschäften Ausschau zu halten, und ich glaube, jetzt habe ich eins gefunden!\n\nDie Naga, die sich westlich von hier befinden, haben Dutzende Statuen, die sie dort, wo sie leben, überall auf den Boden stellen. Sie können unmöglich alle gebrauchen - also dachte ich, dass wir ein paar für uns nehmen!\n\nStatuen, ganz umsonst! Das ist doch ein gutes Geschäft, oder nicht?", progress = "Lasst mal sehen!", completion = "Diese Statuen sind wunderschön...\n\nWow, ich wusste gar nicht, dass die Naga so talentiert sind. Danke, &lt;Name&gt;!", rewards = "Helm der GeheimnisseAuf Euch wartet eine dieser Belohnungen:\n\nAmulett des brillanten Talents\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26821] = {title = "Airwyn Bantamflax", objective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Airwyn Bantamflax in Beutebucht am Schlingendornkap.", description = "Nun, wir haben keine Ahnung, was dieses Artefakt ist. Es ist alt, älter als der Staub ... aber nicht titanischen Ursprungs. Ich bin absolut sprachlos.\n\nAirwyn Bantamflax in Beutebucht ist meine direkte Vorgesetzte. Als nächstes sollten wir sie über diesen Fund informieren. Würdet Ihr ihn bitte zu ihr bringen?", progress = "Ja, <Volk>? Ich bin sehr beschäftigt.", completion = "Faszinierend!\n\nIch brauche etwas Zeit, um mir das genauer anzusehen. Warum seht Ihr Euch nicht ein wenig in Beutebucht um und kommt später wieder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26822] = {title = "Nichtsnutzige, züngelnde Kriecher", objective = "Tötet 12 Donnerschwanz- oder Eisenkieferbasilisken.", description = "Ahem! Hrm, hrm ...\n\n<Der Zwerg räuspert sich einige Sekunden lang.>\n\nIhr sucht nach einer Beschäftigung? Und da kommt Ihr zu MIR? Dem kleinen, alten Goris?!\n\nNun, äh ... das ist das erste Mal. Ah, ich hab's!\n\nDas Tal im Norden ist voll nutzloser Basilisken, die nur ihre Wampe auf dem Boden schleifen. Sie sind zu rein gar nichts nutze und man sagt, sie hätten einmal jemand in Stein verwandelt.\n\nWenn Ihr sie tötet, gebe ich Euch etwas von meinem Zeug.", progress = nil, completion = "Ahem! Aaah... richtig... \n\nGut gemacht! Meinen Glückwunsch, dass Ihr sie getötet habt, meine ich.\n\nHier, bitte, für Euch.", rewards = "Stab der ersten VorkommnissePanzerechsenkopfschutzAuf Euch wartet eine dieser Belohnungen:\n\nGoris' Medaillon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26823] = {title = "Den Mund zu voll genommen", objective = "Beschafft eine Phiole mit Eisenkieferkörperflüssigkeit vom Eisenkieferungetüm in der Kristalladermine.", description = "Was immer Ihr tun wollt: Ich habe genau das richtige Rezept dafür. Ihr wollt einen Sprengstofftrank? BUMM!! Ihr wollt einen Blitztrank? BRITZEL!! Ihr wollt einen Schrumpftrank? Flupp!\n\nAlso Bronwyn sagt, er will einen Kohlenstoffdatierungstrank? Nichts leichter als das. Den könnte ich im Schlaf machen. Das Problem ist... wenn wir wollen, dass er präzise funktioniert, dann brauche ich einige hochwertige Zutaten.\n\nFangen wir mit ein wenig Körperflüssigkeit von einem Basilisken im Norden an. Es muss ein ziemlich großer Basilisk sein...", progress = "Soll ich's mischen... wird es zischen.", completion = "Also gut! Schritt eins - Zutaten besorgen - erledigt. Zeit für den nächsten Schritt: noch mehr Zutaten besorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26824] = {title = "Ergebnisse: Nicht eindeutig", objective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Bronwyn im Lager der Forscherliga am Schlingendornkap zurück.", description = "Ich habe getan, was ich konnte, <Name>. Ich hatte die richtigen Tränke... Ich hatte die richtigen Rezepte... Aber der Ursprung dieser Probe entzieht sich meiner Kenntnis. Sie ist zehntausende Jahre alt, aber wir haben bewiesen, dass sie nicht titanischen Ursprungs ist. Und ein Blick genügt, um festzustellen, dass es nicht Saronit ist. Also... um was in Branns Namen handelt es sich?\n\nSagt Bronwyn, dass ich mein Bestes gegeben habe. Tut mir leid.", progress = "Ich habe Rauch gesehen. Ist alles in Ordnung?", completion = "Ich wusste, dass dieser Alchemist nur eine große Klappe hat. Nun, danke für Eure Hilfe, &lt;Name&gt;. Ich weiß, dass Ihr es versucht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26825] = {title = "Dask \"Der Kolben\" Fusselmaul", objective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Dask \"Der Kolben\" Fusselmaul in der Grabungsstätte der Forscherliga am Schlingendornkap.", description = "Hey, Ihr müsst <der Bursche/das Mädchen> sein, von dem Wulfred gesprochen hat. Ihr habt das Ogerartefakt gefunden und ihm geholfen, diese merkwürdigen Steine aus dem Norden zu testen. Willkommen an der Grabungsstätte, <Name>!\n\nWir waren gerade dabei, diese Proben zu bestimmen, als Ihr hier angekommen seid. Würde es Euch etwas ausmachen, eine Probe zu Dask zu bringen? Er muss mir helfen, herauszufinden, wie alt sie ist.", progress = "Ihr habt etwas, das ich zusammenmischen soll?", completion = "Also bleibt es wieder einmal an dem kleinen Dask hängen, die Arbeit der Forscherliga zu erledigen! Also gut... Schauen wir einmal, was Ihr da habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26826] = {title = "Dask \"Der Kolben\" Fusselmaul", objective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Dask \"Der Kolben\" Fusselmaul in der Grabungsstätte der Forscherliga am Schlingendornkap.", description = "Hey, Ihr müsst <der Bursche/das Mädchen> sein, von dem Wulfred gesprochen hat. Willkommen an der Grabungsstätte, <Name>.\n\nWir wollten gerade ein neues Projekt beginnen, als Ihr eingetroffen seid. Würde es Euch etwas ausmachen, diese Probe zu Dask zu bringen? Er muss mir helfen, herauszufinden, wie alt sie ist.", progress = "Ihr habt etwas, das ich zusammenmischen soll?", completion = "Also bleibt es wieder einmal an dem kleinen Dask hängen, die Arbeit der Forscherliga zu erledigen! Also gut... Schauen wir einmal, was Ihr da habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26827] = {title = "Den Irdenen Ring zusammenrufen", objective = "Versammelt 5 Schamanen im hinteren Teil des Tempels der Erde und sprecht dann mit Maruut Steinbinder.", description = "Wir müssen den Irdenen Ring für diesen Kampf zusammenrufen. Unsere zahlenmäßige Unterlegenheit gleichen wir durch unsere Stärke aus.\n\nGeht zum Tempel und versammelt die ruhenden Schamanen aus den hinteren Räumen. Norsala, Lorvarius und ich treffen uns mit ihnen an Lorthunas Tor.", progress = nil, completion = "Was Ihr getan habt, hätte ich nicht für möglich gehalten. Ziemlich beeindruckend, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26828] = {title = "Unser Teil der Vereinbarung", objective = "Sprecht mit Therazane auf dem Halcyonaufstieg.", description = "Leider muss ich hierbleiben und auf den Riss aufpassen, also müsst Ihr ohne mich kämpfen. Geht jetzt zu Therazane und schließt Euch wie versprochen dem Kampf an. Ihr solltet Sie am Halcyonaufstieg nördlich von Lorthunas Tor und östlich des Geschliffenen Schlunds vorfinden.\n\nWenn unser Teil der Abmachung erfüllt ist, bringt das letzte Stück der Weltensäule so schnell wie möglich hierher.", progress = nil, completion = "Ihr seid also gekommen, Fleischling. Wie versprochen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26829] = {title = "Der Steinmarsch", objective = "Tötet 15 Kultisten des Zwielichthangs.", description = "Meine Streitkräfte haben den Angriff bereits begonnen. Schließt Euch ihnen an. Vergießt das Blut dieser Kultisten, damit ich spüren kann, wie sie leiden.", progress = nil, completion = "Ihr Blut auf dem Boden ist berauschend. Ich werde jeden Augenblick genießen und die Nachzügler langsam in meinem Reich auslöschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26830] = {title = "Köder für den Verräter", objective = "Befragt Peons des Himmelpfads von Orgrimmar in der Nähe des Zeppelinturms. Haltet Ausschau nach verdächtigen Peons. Versucht, Sauranok den Mystiker aufzuscheuchen und tötet ihn.", description = "Ich habe meine Suche nach den Agenten des Schattenhammers, die hier in Orgrimmar herumlungern, noch nicht aufgegeben. Ich brauche jemanden, dem ich vertrauen kann, um den letzten Beweis für den Verrat zu finden.\n\n<Höllschrei nimmt Euch zur Seite.>\n\nSauranok der Mystiker - mein Vertrauter und Berater! - steht unter Verdacht. Deckt die Wahrheit auf, <Name>, und Ihr werdet belohnt werden.\n\nWie ich höre, hat der Schattenhammer die Arbeiter an den Luftschiffdocks unterwandert, um seine Lügen über den gesamten Kontinent zu verbreiten. Befragt sie. Solltet Ihr herausfinden, dass Sauranok schuldig ist... Tötet ihn!", progress = "Schön, dass Ihr noch am Leben seid, <Klasse>. Wie steht's mit Euren Nachforschungen?", completion = "Sauranok, Sauranok! Seine eigenen Visionen haben gegen ihn gearbeitet. Der Schattenhammer hat ihn wahrscheinlich aus der Ferne bestochen. Bah! Schwächling! Wir werden seinen Namen nie wieder aussprechen.\n\nIch sagte ihm, dass Ihr an den Luftschiffdocks Nachforschungen anstellt, &lt;Name&gt;, um ihn aus der Reserve zu locken. Ja, ich habe Euch als Köder benutzt. Ihr habt Eurer Horde gut gedient und verdient eine Belohnung, weil Ihr diese Schlange in unserer Mitte enttarnt habt.", rewards = "ZwielichtspiegelschildSchulterplatten des ZwielichtherzensGeistgeschnittener BrustschutzVisionenbesudelte TreterGürtel des mystischen VerratsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26831] = {title = "Flug ins Zwielicht", objective = "Besiegt Zoltrik Drachenbann.", description = "Terrath braucht Euch auf der anderen Seite des Abgrunds, um Zoltrik Drachenbann zu bekämpfen. Er ist ebenfalls unterwegs, aber er fürchtet, Zoltrik wird sich in die Luft erheben.\n\nWie es scheint, habt Ihr ziemlichen Eindruck hinterlassen, Kleinling. Ist Euch jemals der Gedanke gekommen, dass all dies nie geschehen wäre, wenn ich bei unserem ersten Zusammentreffen auf Euch getreten wäre? Das Schicksal geht seltsame Wege.", progress = "Es ist gut, Euch wieder auf dem Schlachtfeld zu sehen.", completion = "Es war gut, dass Ihr zur Stelle wart. Merkwürdigerweise ist meine Größe durchaus hinderlich, wenn es darum geht, einen Drachen zu reiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26832] = {title = "Therazanes Gnade", objective = "Besiegt Boldrich Steinreißer und Hohepriesterin Lorthuna.", description = "Der Schattenhammer hat zwei Führungspersönlichkeiten, die getötet werden müssen.\n\nDie eine ist ein Mensch namens Boldrich. Er ist klein, so wie Ihr. Aber dennoch gefährlich, ebenfalls so wie Ihr.\n\nDie andere ist eine Priesterin namens Lorthuna. Sie ist gerissen und nur schwer in die Enge zu treiben. Schlagt schnell zu und lasst sie nicht entkommen, sonst werdet Ihr es später bereuen - das verspreche ich Euch.", progress = nil, completion = "Ihr habt Lorthuna entwischen lassen? Ich habe Euch davor gewarnt.\n\nDennoch, ihre Streitkräfte sind zerschlagen und ihr Nachschub ist abgeschnitten. Sie können mir oder meinen Verbündeten nicht mehr viel Schaden zufügen.", rewards = "SteinreißertuchRunenbeschriftete StulpenLorthunas zerbrochene FesselnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26833] = {title = "In Stein gemeißelt", objective = "Sprecht mit Maruut Steinbinder am Tempel der Erde.", description = "Ihr habt getan, worum ich Euch gebeten habe, <Volk>. Ich werde zu meinem Wort stehen. Gorsik wird Euch mit unserem Stück der Weltensäule am Tempel treffen.\n\nBeendet Euer Ritual und schließt den Riss. Wenn Ihr das getan habt, sagt Eurem Irdenen Ring, er möge diesen Ort verlassen. \n\nIhr allerdings... Ihr dürft noch eine Weile bleiben, wenn Ihr möchtet. Das habt Ihr Euch verdient.", progress = nil, completion = "Gorsik ist eingetroffen. Dank Euch sind nun alle Teile der Weltensäule hier.\n\nWas Ihr für uns getan habt, ist von unermesslichem Wert. Diese letzten Momente werden entscheidend sein. Es fällt mir schwer, noch mehr von Euch zu verlangen, aber ich möchte, dass Ihr es bis zum Ende gemeinsam mit uns durchsteht.\n\nEure Angriffe haben den Schattenhammer zwar niedergeworfen, aber nicht vernichtet. Wir gehen davon aus, dass sie versuchen werden, uns von der Vollendung des Rituals abzuhalten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStormcaller Ping\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26834] = {title = "Hinein in den Abgrund", objective = "Sprecht mit Schiefer Treibsand in der Nadelfelsschlucht in Tiefenheim.", description = "Tief in der Nadelfelsschlucht lassen die Mystiker all diese Fungusmissgeburten sprießen. Ich habe Schiefer Treibsand und eine kleine Truppe hingeschickt, damit sie sich darum kümmern, aber sie sind auf Schwierigkeiten gestoßen.\n\nErinnert Ihr Euch noch an den Erzgeomanten? Würdet Ihr im Nordosten hinunterfliegen und ihm behilflich sein?", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;. Jetzt werden wir weiterkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26835] = {title = "Ein kleines Problem", objective = "Kehrt zu Pyrium Leitstein im Nadelfelsbruch in Tiefenheim zurück.", description = "Während Ihr dort draußen wart, hat sich Pyrium Leitstein mit mir in Verbindung gesetzt. Er meinte, dass es eine Angelegenheit höchster Dringlichkeit gäbe und dass man umgehend Eure Unterstützung bräuchte. Kehrt zum Eingang am Nadelfelsbruch im Südwesten zurück.\n\nIch wünsche Euch viel Glück bei der Rettung des Steinvaters und der Bergung des zweiten Fragments.", progress = nil, completion = "&lt;Name&gt;, wir haben gute Nachrichten und ein kleines Problem…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26836] = {title = "Rettet den Steinvater... und Flint", objective = "Befreit Steinvater Erzmantel.", description = "Wir haben herausgefunden, wo der Steinvater gefangen gehalten wird, und prompt ist der junge Flint losgerannt, um ihn zu befreien!\n\nIch muss Euch nicht sagen, dass das gar nicht gut ist. Flint könnte ebenfalls gefangen genommen werden - oder noch Schlimmeres!\n\nDer Häuptling der Steintroggs, Felsmagen, befindet sich am äußersten Ende der Felssimse über der Nadelfelsschlucht im Norden. Bitte, <Name>, Ihr müsst Flint folgen und den Steinvater befreien, bevor wir sie beide verlieren!", progress = "Ihr müsst Steinvater Erzmantel befreien. Ihr dürft keine Zeit verschwenden, <Name>!", completion = "&lt;Name&gt;! Ihr habt es geschafft! Wie können wir das jemals wieder gutmachen?", rewards = "Gurt des BefreiersTreter der gesprengten KettenAuf Euch wartet eine dieser Belohnungen:\n\nErzmantels Gunst\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26837] = {title = "Die Grabungsstätte der Forscherliga", objective = "Sprecht mit Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.Hört einmal, <Name>... Ihr scheint genau richtig zu sein.\n\nBronwyn Hackschlag von der Forscherliga sucht neue Rekruten für seine Grabungsstätte am Schlingendornkap. Ich persönlich verstehe ja nicht, warum er nicht einfach nach Beutebucht geht und dort seine Rekruten sucht... Piraten kann man leicht mit ein paar Goldstücken überreden.\n\nWie auch immer - gerüchteweise hört man, dass er endlich etwas dort im Dschungel gefunden hat. Ich frage mich, was das sein könnte?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Hört einmal, <Name>... Ihr scheint genau richtig zu sein.\n\nBronwyn Hackschlag von der Forscherliga sucht neue Rekruten für seine Grabungsstätte am Schlingendornkap. Ich persönlich verstehe ja nicht, warum er nicht einfach nach Beutebucht geht und dort seine Rekruten sucht... Piraten kann man leicht mit ein paar Goldstücken überreden.\n\nWie auch immer - gerüchteweise hört man, dass er endlich etwas dort im Dschungel gefunden hat. Ich frage mich, was das sein könnte?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26838] = {title = "Wenn man keine Ahnung hat ...", objective = "Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.", description = "Vor einigen Jahren hat Captain Kurzen aus Sturmwind eine Brigade ins Schlingendorntal gebracht. Die Einzelheiten seiner Mission sind immer noch unklar. Kurzen fiel schnell dem Wahnsinn anheim, genau wie seine Männer ... außer einigen Rebellen, die es sich zur Aufgabe gemacht haben, das Böse, das Kurzen angerichtet hat, ungeschehen zu machen.\n\nWie ich bereits sagte, das war vor vielen Jahren. Jetzt ist mir zu Ohren gekommen, dass Kurzen tot ist. Doch diese Rebellen bestehen immer noch auf ihrer Rebellion. Wenn Ihr Ermittlungen anstellen wollt, findet Ihr sie in einem Lager an der nördlichen Grenze von Schlingendorntal.", progress = nil, completion = "Willkommen in unserem Lager, &lt;Klasse&gt;. Ihr seid genau zum richtigen Zeitpunkt eingetroffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26839] = {title = "Eine Auszeit nehmen!", objective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.Sagt einmal, <Klasse>, Ihr seht erschöpft aus. Diese schwere Geldbörse... äh, ich meine... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.\n\nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht... es ist alles vorhanden.\n\nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Sagt einmal, <Klasse>, Ihr seht erschöpft aus. Diese schwere Geldbörse ... äh, ich meine ... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.\n\nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht ... es ist alles vorhanden.\n\nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26840] = {title = "Rückkehr ins Hochland", objective = "Benutzt das Portal des Drachenmals in Orgrimmar, um in den Hafen des Drachenmals im Schattenhochland zurückzukehren und sprecht mit Zaela.", description = "Jetzt, da Orgrimmar sicher ist und wir unsere Verbündeten des Drachenmalklans hinter uns wissen, können wir unsere Aufmerksamkeit dem Schattenhochland und der Vernichtung der Truppen von Todesschwinge zuwenden.\n\nIch brauche die Besten der Horde an der Front. Damit meine ich Euch. Und all Eure Freunde.\n\nDas Hochland wird UNS gehören!\n\nBenutzt das neue Portal, das Ihr erschaffen habt, um in den Hafen des Drachenmals zurückzukehren. Meldet Euch bei Zaela, um zu sehen, wo sie Euch am meisten braucht.", progress = nil, completion = "&lt;Name&gt;! Ist in Orgrimmar alles in Ordnung?\n\nWie Ihr seht, läuft der Bau des Hafens des Drachenmals auf Hochtouren. Sollte mein Volk an der Macht der Horde bisher gezweifelt haben, wird dieses beeindruckende Gebäude und die Geschwindigkeit, mit der es errichtet wurde, sie eines besseren belehren.\n\nEs beginnt eine neue Zeit für das Drachenmal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26841] = {title = "Das verbotene Siegelzeichen", objective = "Sprecht mit Rhyanda in Aldrassil im Laubschattental.", description = "Dieses Siegelzeichen wurde mir durch einen Boten überbracht und stammt von unserer Magierlehrerin Rhyanda. Wie es aussieht, möchte Rhyanda mit Euch sprechen, wenn Ihr einen Moment erübrigen könnt. Lest es und bringt es ihr danach bitte.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26842] = {title = "Hier ein Gnoll, dort ein Gnoll", objective = "Sammelt 12 Gnollohren von Spähern und Schlägern der Moosfelle.", description = "Seid gegrüßt, <Klasse>. Wir haben ein Problem und ich würde Euch bitten, uns zu helfen.\n\nEs handelt sich um Gnolle. Westlich der Stadt streift ein ganzer Haufen dieser Viecher durch die Hügel. Eigentlich ist das kein Grund, beunruhigt zu sein, aber normalerweise haben wir hier keine Gnolle in Loch Modan.\n\nMich interessiert, wo sie herkamen, allerdings bin ich nicht neugierig genug, um diese räudigen Dinger zu fragen. Ich bin der Meinung, wir sollten sie loswerden. Bringt mir Beweise, dass Ihr sie getötet habt und ich werde Euch ein beachtliches Kopfgeld zahlen.", progress = "Nun, habt Ihr einige Ohren für mich?", completion = "Gut gemacht, mein Freund. Ein &lt;Klasse&gt; wie Ihr wäre mir hier ganz nützlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26843] = {title = "Ein winziger, cleverer Kommandant", objective = "Tötet \"Kommandant\" Nazrim.", description = "Wir schlagen uns in diesem Land schon seit Jahren mit Kobolden herum. Bisher waren sie kaum mehr als ein Ärgernis. Aber sie werden bei ihren Diebstählen immer geschickter.\n\nIch glaube, einer von ihnen ist irgendwie klüger als üblich. Aber das wird nicht mehr lange der Fall sein!\n\nIch möchte, dass Ihr zu ihrem Lager im Süden geht und sicherstellt, dass sich dort kein \"Obermotz\" Kobold befindet, der die anderen aufwiegelt. Achtet darauf, auch die Höhle zu untersuchen. Das wäre mit ziemlicher Sicherheit ein guter Ort.\n\nAch ja, und übt keine Zurückhaltung, wenn es darum geht, die Kobolde, die Euch unterwegs begegnen, zu beseitigen.", progress = nil, completion = "Also hatte ich recht! Die Frage ist, was diese kleinen Nervensägen geplant haben ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26844] = {title = "Vom Regen in die Traufe", objective = "Tötet 5 Feldmesser der Tunnelratten und 5 Futterwühler der Tunnelratten.", description = "Jetzt, da wir diese kleinen Quälgeister erledigt haben, müssen wir uns um weitere Dinge kümmern.\n\nDie Tunnelratten schwärmen durch die ganze Silberbachmine. Sie schlagen Lager auf und schnüffeln überall herum. Dabei ziehen sie immer weitere Kreise. Die gierigen kleinen Viecher suchen bestimmt nach Beute.\n\nVermessen und nach Futter wühlen ist ja schön und gut, solange es nicht auf Zwergenland stattfindet! Kümmert Euch um diese Tunnelratten und meldet Euch dann wieder bei mir.", progress = nil, completion = "Gut, gut! Jetzt ist mir klar, was in der Mine vor sich geht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26845] = {title = "Wer hat hier das Sagen?", objective = "Bringt mir den Kopf von Vorarbeiter Scharfspott.", description = "Dorli hat mir von diesem verrückten Troggsklaven-Vorhaben erzählt, das bei den Kobolden im Gange ist. Wenn Ihr bisher noch nicht mit ihr gesprochen habt, schlage ich vor, dass Ihr das nachholt. Ich möchte dieser Sache auf den Grund gehen.\n\nIm wahrsten Sinne des Wortes! Wer immer hier die Fäden zieht, sitzt garantiert ganz unten in der Mine und gibt von dort die Befehle. Ich will, dass er zur Strecke gebracht wird.\n\nFindet den gerissenen Schlauberger, der die Geomanten und Gräber dirigiert und bringt mir seinen Kopf.", progress = "War Moira vielleicht dort unten? Wunder gibt es ja immer wieder.", completion = "Das ist der Kopf eines Gnolls. Versucht Ihr, mich hier hinter's Licht zu führen, &lt;Name&gt;?\n\nWenn nicht, habe ich nicht den Hauch einer Ahnung, was hier vor sich geht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26846] = {title = "Ein fieser Plan", objective = "Tötet 5 Geomanten der Tunnelratten.", description = "Ich habe herausgefunden, was diese Ratten im Schilde führen. Der Grund, warum so viele von ihnen draußen herumlaufen, ist, dass sie Troggs dazu gebracht haben, für sie in der Mine zu schürfen!\n\nDie Geomanten der Tunnelratten haben irgendeinen Taschenspielertrick ersonnen, mit dem sie die Troggs kontrollieren können. Irgendwas mit Kreaturen der Erde oder so ähnlich.\n\nFaszinierend, aber wir können ihnen das nicht durchgehen lassen. Beseitigt diese Geomanten so schnell wie möglich.", progress = nil, completion = "Ich bin sicher, dass das nur funktioniert hat, weil die Troggs ohnehin nicht die hellsten sind. Aber wir Zwerge waren auch einmal Kreaturen der Erde.\n\nVon einem Kobold herumkommandiert zu werden ist so entwürdigend ... Ich bin froh, dass wir nicht herausgefunden haben, ob sie dazu auch in der Lage gewesen wären.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26854] = {title = "Der vermisste Pilot", objective = "Findet Pilot Hanglug nördlich des Helmsbettsees.", description = "Mein Freund Mori Hangflug, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe des Nachts nördlich des Helmsbettsees und westlich des Tunnels das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, <Name>. Sucht ihn.", progress = nil, completion = "Hier liegt die Leiche eines Zwergs - zerfetzt, gefroren und von Aasfressern blankgefressen. Seine Hand umklammert ein Buch, das die grob hingekritzelten Aufzeichnungen von Mori Hangflug enthält. Um ihn gehüllt, nach wie vor in sehr gutem Zustand, ist eine Brigadiersweste.\n\nAn diesem grausigen Ort muss der Pilot der Belagerungsmaschinen sein Ende gefunden haben.", rewards = "Moris MantelMoris SchalthebelAuf Euch wartet eine dieser Belohnungen:\n\nMoris Kompass\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26855] = {title = "Pilotenrache", objective = "Tötet Marterklaue.\n\nBringt Pilot Hammerfuß am Südtoraußenposten die räudige Klaue des Bären und Hangflugs Tagebuch.", description = "Hangflug schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hangflugs Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hangflug in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", progress = "Hallo, <Name>. Wisst Ihr etwas über den Verbleib meines Freundes Hangflug?", completion = "Das sind traurige Neuigkeiten, denn Hangflug war ein guter Freund. Ich wünschte, ich hätte dort mit Euch sein können, als Ihr die Bestie Marterklaue gefunden habt!\n\nDanke, &lt;Name&gt;. Eure Tat wird den Piloten der Belagerungsbrigade von Eisenschmiede in Erinnerung bleiben.", rewards = "Fäustlinge der räudigen KlaueHammerfuß' KettengamaschenSüdtordonnerbüchseGürtel des BelagerungsingenieursIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26856] = {title = "Werft die Invasion zurück", objective = "Tötet Flintauge, Bazzalan und Jergosh den Herbeirufer.", description = "Diese Höhle war einst ein Ort großer Ehre. Man brachte junge Krieger hierher, damit sie zum ersten Mal in ihrem Leben einen Erdbohrerwurm erlegen. Daran erinnern wir Orcs uns das ganze Leben lang.\n\nDie Agenten der Brennenden Klinge haben die Einwohner der Höhle versklavt und wollen nun Orgrimmar mit ihren Troggverbündeten angreifen.\n\nWenn Ihr ihre Leutnants zur Strecke bringt, könntet Ihr sie unvorbereitet erwischen und diese Invasion verhindern, bevor sie überhaupt beginnt.", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Ihr habt die Invasion der Brennenden Klinge verhindert, bevor sie begann! Nehmt dies als Zeichen meiner Dankbarkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26857] = {title = "Abyssions Diener", objective = "Besiegt 8 Zwielicht- oder Drachkineinheiten in Abyssions Hort.", description = "Wenn der Drache das Fragment hat, müssen wir seine Aufmerksamkeit auf seinen Hort lenken.\n\nGeht zu Abyssions Hort gleich östlich von hier und besiegt seine Untergebenen. Das wird ihn früher oder später dazu veranlassen, mit dem Weltensäulenfragment aufzutauchen.", progress = nil, completion = "Das sollte genügen, um die Aufmerksamkeit des Drachen zu erregen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26858] = {title = "Taragaman der Hungerleider", objective = "Holt das Herz von Taragaman dem Hungerleider.", description = "Der Sengenden Klinge ist es gelungen, einen widerlichen Dämonen zu beschwören, den sie Taragaman den Hungerleider nennen. Er soll bei der Übernahme von Orgrimmar den ersten Angriff leiten.\n\nBeeilt Euch und tötet Taragaman im Namen des Kriegshäuptlings! Lok'tar ogar!", progress = "Zeigt mir das Herz von Taragaman, wenn er tot ist.", completion = "Meine Kinder werden noch Loblieder auf Euch singen, &lt;Name&gt;!", rewards = "Roben des gescheiterten RitualsFlammenschlundgamaschenBalgweste des SchamanenSengender GürtelSteingardistenschienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26860] = {title = "Blutwurst aus Thelsamar", objective = "Sammelt 8 Bärenrücken von Schwarzbären in Loch Modan.", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr <ein toller/eine tolle:c> <Klasse> seid.\n\nBringt mir frische Bärenrücken und überlasst das Kochen nur mir!", progress = "Ich bin so weit, dass ich mit dem Kochen anfangen könnte; habt Ihr die Bärenrücken?", completion = "Vielen Dank! Die Rückenstücke sind meine eigene geheime Erweiterung des Rezepts... aber hier habt Ihr die Anleitung, wie man es mit jeder beliebigen Sorte Bärenfleisch herstellen kann.\n\nObendrein gibt's noch eine frische Portion, die ich selbst gekocht habe. Frisch schmecken sie am besten!", rewards = "Ihr bekommt:\n\nBlutwurstRezept: Blutwurst"}
MultiLanguageQuestData['de'][26861] = {title = "Blockiert die Tore", objective = "Benutzt den Sturmstein am Zwielichttor und Elementartor in Abyssions Hort.", description = "Wenn wir eine Chance gegen Abyssion haben wollen, müssen wir sicherstellen, dass ihn keine Verstärkung zur Unterstützung erreicht.\n\nIn seinem Hort gen Osten werdet Ihr zwei Tore vorfinden. Benutzt diesen Sturmstein, um ihre Funktion zu unterbinden.\n\nWenn alles so läuft wie geplant, werden wir Abyssion angreifen können, ohne dass er viel Unterstützung bekommt.", progress = "Ihr seid zurück, <Name>. Sind die Tore geschlossen?", completion = "Ausgezeichnet. Wenn wir gegen Abyssion ziehen, sollten wir keine Gefahr durch seine Verstärkung zu fürchten haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26862] = {title = "Verpfuschte Elementare", objective = "Beschafft 6 sengende Bindungen.", description = "Die Hexenmeister der Sengenden Klinge haben die Geister der Elementare in Flammenschlund versklavt, <Name>. Solange mein Zauber sie im Zaum hält, stellen sie keine Bedrohung für die Stadt dar, aber ich kann ihn nicht mehr lange aufrecht halten.\n\nBringt mir sechs der sengenden Bindungen, mit denen sie unter Kontrolle gehalten werden und ich werde ihre Geister im Flammenschlund wieder freisetzen.", progress = "Habt Ihr die Bindungen?", completion = "Ich danke Euch, &lt;Klasse&gt;. Die Geister der geschmolzenen Elementare haben endlich ihre Ruhe gefunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26863] = {title = "Schmutzige Pfoten", objective = "Sucht in der Silberbachmine 6 Sätze Minenarbeiterausstattung zusammen.", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", progress = "Habt Ihr die Minenarbeiterausstattung, <Name>?", completion = "Habt Ihr da drin viele Kobolde gesehen? Der Gedanke daran, wie ihre schmutzigen Hände in unserer Mine herumkratzen, verursacht mir Bauchschmerzen!", rewards = "Dreckige PfoteSilberstromschildEisenherzkettenumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26864] = {title = "Kopflos", objective = "Bringt den Kopf von Vorarbeiter Scharfspott zu Gebirgsjäger Kadrell.", description = "Ihr müsst das hier zu Gebirgsjäger Kadrell bringen. Zeigt es ihm und sagt ihm, dass die fiesen Plagegeister hier möglicherweise eine Art Versammlung abhalten werden.", progress = "Gibt es Neuigkeiten von der Station Algaz?", completion = "Gnolle, Kobolde und Troggs? Au weia.\n\nIch würde glatt lachen, wenn ich nicht noch eine andere unerwartete Wendung der Geschichte für Euch hätte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26865] = {title = "Der Feind tief unten", objective = "Sprecht mit Steinwächter Kurjack.", description = "Unter dieser Stadt, befinden sich Feinde der Horde, <Klasse>.\n\nDie Angehörigen der Sengenden Klinge planen, Orgrimmar für sich zu übernehmen und sie haben bereits den Flammenschlund überrannt! Wir müssen gegen ihre Truppen anstürmen und zurückerobern, was uns gehört!\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Er hat weitere Instruktionen für Euch.", progress = nil, completion = "Ich habe Eure Ankunft erwartet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26866] = {title = "Der Feind tief unten", objective = "Sprecht mit Steinwächter Kurjack.", description = "Der Flammenschlund in Orgrimmar wurde von der Sengenden Klinge übernommen. <Name>, wir können das nicht ungestraft durchgehen lassen, sonst richten sie ihren Blick als Nächstes auf Donnerfels.\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Helft ihm auf jede erdenkliche Art und Weise, da unsere Schicksale miteinander verknüpft sind.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26867] = {title = "Der Feind tief unten", objective = "Sprecht mit Steinwächter Kurjack.", description = "Kriegshäuptling Garrosh hat unter Aufbietung all seines wohlbekannten Liebreizes freundlich um Eure Anwesenheit im Flammenschlund gebeten, damit Ihr ihm helfen könnt, diesen von der Sengenden Klinge zurückzuerobern. Offensichtlich ist seine verstärkte Stadt nicht so uneinnehmbar, wie er dachte.\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Ich bin sicher, dass er über fähige Hilfe sehr froh sein wird.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26868] = {title = "Die Achse des Grässlichen", objective = "Benutzt das clevere Pflanzenverkleidungsset, um Euch an den Repräsentanten der Moosfelle heranzuschleichen. Dann bestäubt ihn mit den starken Murlocpheromonen.", description = "So, also nun haltet mal die Klappe und lasst mich reden. Der Plan sieht so aus...\n\nDiese Gnolle und Murlocs werden sich wahrscheinlich hier draußen irgendwo treffen. Also nehmt Ihr dieses clevere Pflanzenverkleidungsset von mir, zieht es an und seht wie eine Pflanze aus. Dann schleicht Ihr Euch an sie heran und werft die Geruchspheromone, die ihr gesammelt habt, über die Moosfelle, die bei den Murlocs stehen.\n\nDann brennen bei den Murlocs die Sicherungen durch und die Moosfelle werden es sich zweimal überlegen, ehe sie wieder mit diesen verrückten kleinen Nervensägen zusammenarbeiten.", progress = nil, completion = "Hat doch wunderbar geklappt, oder nicht? Vielleicht fällt Kadress mir jetzt endlich nicht mehr auf die Nerven, nachdem ich die Stadt gerettet hab' und so.\n\nIhr habt Euch wohl auch ein paar anständige Sachen verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26869] = {title = "Tiefe der Tiefen", objective = "Findet das Painit in den Bruchtiefen.", description = "<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>\n\nGut gemacht, <Volk>.\n\nIn den unterirdischen Tunneln werdet Ihr den Stein, den Ihr sucht, finden. Painit.\n\nDie Gefahren, die vor Euch liegen sind mannigfaltig...\n\nGefahren, die sogar die Steinlords selbst fürchten.\n\nBleibt ruhig.\n\nBleibt stark.\n\nDie Stärke des Felsens ruht unter Euren Füßen.", progress = nil, completion = "&lt;Das ist er. Das ist der Stein, den Ihr für Diamant holen solltet.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26870] = {title = "Säuberung der Höhlen", objective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr die Giftzahnlords Cobrahn, Anacondra, Pythas und Serpentis vernichtet.", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer hatte sich vorgenommen, den Smaragdgrünen Traum zu betreten und dabei zu helfen, dieses unwirtliche Land wieder zu dem üppigen Wald zu machen, der es einst gewesen war. Aber etwas ging furchtbar schief.\n\nDie treuen Verbündeten von Naralex, die Druiden des Giftzahns, wandten sich gegen ihn! Ihr Ziel ist es nicht, das Brachland zu heilen, sondern es zu beherrschen. <Name>, bevor wir Naralex erwecken und das Gleichgewicht an diesem wichtigen Ort wiederherstellen können, müsst Ihr die Giftzahnlords auslöschen. Ihr Einfluss ist viel zu groß geworden.", progress = nil, completion = "Ich spüre bereits, wie das Gleichgewicht zurückkehrt! Schnell, sprecht mit Muyoh und helft ihm, Naralex zu erwecken!", rewards = "Anacondras RobeSerpentis' HandschuheCobrahns StiefelGereinigte SchulterstückePythas' WesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26871] = {title = "Ein Fels unter vielen", objective = "Kehrt mit dem Painitbrocken zu Diamant an Lorthunas Tor zurück.", description = "<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>\n\nIhr habt das getan, worum ich gebeten hatte.\n\nGeht zurück und verlasst die Höhle unverletzt.\n\nVergesst den Edelstein nicht.", progress = "Ihr lebt. Das ist gut.\n\nTragt Ihr den Edelstein bei Euch?", completion = "Gut gemacht, Fleischling!\n\nDie Tunnelgräber zählen zu unseren gefährlichsten Feinden.\n\nDie anderen Steinlords werden diesen Erfolg nicht ignorieren können.", rewards = "TunnelgräbertaillenschutzHelm des WurmtötersAuf Euch wartet eine dieser Belohnungen:\n\nInsigne des Lords der Irdenen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSummon Therazane\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26872] = {title = "Deviatbälge", objective = "Nalpak möchte 10 Deviatbälge.", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Ihre bloße Existenz verursacht der Welt große Schmerzen. Ich glaube, dass ihr Tod unseren Versuchen, den Höhlen Heilung zu bringen, sehr helfen wird.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen hinab, tötet so viele wie möglich und bringt mir ihre Bälge als Beweis ihres Ablebens.", progress = "Wie viele dieser Bestien konntet Ihr töten?", completion = "Eure Bemühungen werden nicht unbemerkt bleiben, &lt;Name&gt;.\n\nVielen Dank für Eure Mühe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26873] = {title = "Vorbeugende Maßnahmen", objective = "Nalpak möchte, dass Ihr 5 Schlangenflaum sammelt.", description = "In diesen Höhlen befindet sich ein Kraut mit unvorstellbaren Kräften, <Name>. Möchtet Ihr mir helfen, es zu sammeln?\n\nEs handelt sich um eine seltene Blume mit Namen Schlangenflaum. Ich glaube, dass große Mengen davon weitere Alpträume, wie den von Naralex in Zukunft verhindern können.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Ecken dieses Ortes.", progress = "Ich bin gespannt, ob Ihr genug Schlangenflaum sammeln könnt.", completion = "Gut gemacht, &lt;Name&gt;. Hoffentlich können wir sie benutzen, um weitere Alpträume zu verhindern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26874] = {title = "Die Auferstehung von Naralex", objective = "Sprecht mit Muyoh.Jetzt, da die Giftzahnlords tot sind, sprecht mit Muyoh. Er wird Euch dabei helfen, Naralex aufzuwecken und diesen Alptraum zu beenden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Jetzt, da die Giftzahnlords tot sind, sprecht mit Muyoh. Er wird Euch dabei helfen, Naralex aufzuwecken und diesen Alptraum zu beenden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26875] = {title = "Unsterbliches Zwielicht", objective = "Tötet 12 Zwielichteindringlinge und 1 entweihten Erdwüter.", description = "Die Schattenhammerkultisten sind hier! Sie versuchen, das Ritual zu verhindern! Geht zurück in die Kammern und wehrt sie ab!", progress = nil, completion = "Immer mehr Zwielichttruppen strömen herein, aber offenbar können die Verteidiger des Irdenen Rings ihrer Herr werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26876] = {title = "Das Weltensäulenfragment", objective = "Stellt das Banner des Irdenen Rings in der Mitte von Abyssions Hort auf, tötet ihn und nehmt das erste Weltensäulenfragment an Euch.", description = "Es wird Zeit, <Name>. Wir haben Abyssion erspäht, auf dem Weg zu seinem Hort.\n\nDer Schattenhammer dachte wahrscheinlich, dass das Fragment sicher ist, wenn ein Drache es bewacht, aber ich habe genug Drachen gesehen und kenne ihre einzige Schwäche. Stolz.\n\nAbyssion wird nicht vor einem Kampf mit uns kläglichen Sterblichen davonlaufen.\n\nStellt das Banner des Irdenen Rings in die Mitte seines Horts. Wenn wir ihn besiegt haben, bringt das Fragment zu Maruut. Wir müssen die Weltensäule so bald wie möglich reparieren.", progress = "<Name>! Ihr seid zurückgekehrt!", completion = "Eure Bemühungen, die Weltensäule zu reparieren, sind von unschätzbarem Wert, &lt;Name&gt;. Sobald der Tempel der Erde wieder stabil ist, wird auch der Riss zwischen den Welten sich stabilisieren.", rewards = "Umhang des SteinbindersAuf Euch wartet eine dieser Belohnungen:\n\nSignet des WeltenbindersAmulett der Wiederherstellung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26878] = {title = "Jünger von Naralex", objective = "Sprecht in den Höhlen des Wehklagens mit Nalpak.", description = "<Klasse>, das Brachland war einst einer der schönsten Orte in ganz Kalimdor. Es war vielversprechend und voller Leben.\n\nWie Ihr seht, ist das nicht länger der Fall. Es ist ein Land voller Qual und Zwietracht.\n\nDie Jünger von Naralex wollen die Höhlen des Wehklagens säubern und sie in ihrer früheren Schönheit wiederherstellen. Sprecht in den Höhlen des Wehklagens hinter dem Eingang mit Nalpak.", progress = nil, completion = "Ja, &lt;Klasse&gt;? Was bringt Euch an diesen Ort?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26881] = {title = "Auf der Suche nach Thaelrid", objective = "Sucht Späher Thaelrid auf.", description = "Finstere Dinge gehen an diesem Ort vor sich, <Name>. Wir fürchten, dass die Gerüchte über eine Zusammenarbeit der Naga mit dem Schattenhammer wahr sind.\n\nIch habe Thaelrid, einen unserer besten Späher, ausgeschickt, um der Angelegenheit nachzugehen. Doch er ist nicht zurückgekommen.\n\nFindet ihn. Wenn er noch lebt, findet heraus, was er entdeckt hat.", progress = nil, completion = "Gut, dass Ashelan Euch geschickt hat. An diesem Ort der Verderbnis wird ein finsterer Plan geschmiedet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26882] = {title = "Schurkerei in der Tiefschwarzen Grotte", objective = "Holt den Kopf von Zwielichtfürst Kelris.", description = "Meine Kräfte haben mich verlassen. Ich brauche Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, ein Diener des Alten Gottes, erhob sich aus den Wassern.\n\nDie Kultisten des Schattenhammers haben sich mit den Naga verbündet, um diesen Ort zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nErschlagt Kelris und bringt seinen Kopf zu Ashelan.", progress = "Schön, Euch wiederzusehen, <Name>. Welche Neuigkeiten bringt Ihr?\n\nWar Euer Vorstoß erfolgreich? Habt Ihr Thaelrid gefunden?", completion = "Kelris hat sich uns schon seit geraumer Zeit entzogen.\n\nOffenbar war Kelris immer dann beteiligt, wenn sich in dieser Gegend das Böse zeigte. Wir glaubten seit einiger Zeit, er sei entweder tot oder vermisst.\n\nAber das hier passt alles wunderbar zusammen. Indem Ihr seiner Herrschaft ein Ende gesetzt habt, rettet ihr die Leben vieler unschuldiger Menschen.\n\nEinem Diener eines Alten Gottes Opfer zu bringen, nur um sich persönliche zu bereichern ist mehr als verabscheuungswürdig!\n\nIhr habt eine große Tat vollbracht, &lt;Name&gt;. Ich danke Euch in Namen Eschentals.\n\nIch wünschte nur, Thaelrid hätte überlebt...", rewards = "Kelris' RobeGamaschen der Tiefschwarzen GrotteThaelrids SchienbeinschützerSchild gegen die bösartige PräsenzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26883] = {title = "Die Stunde der Finsternis", objective = "Bringt 3 Zwielichtanhänger an Euch.", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder des Schattenhammers, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass der Schattenhammer sich mit den Naga verbündet hat und sich ihre Anhänger hier zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen den Schattenhammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", progress = "Die Tiefschwarze Grotte war einst ein uralter Tempel der Nachtelfen. Er beherbergte einen äußerst mächtigen Mondbrunnen. Wer weiß, was der Schattenhammer hier Böses ausbrütet.\n\nHabt Ihr Fortschritte dabei gemacht, den Tempel von ihrer Anwesenheit zu befreien?", completion = "Zweifellos seid Ihr tapfer und von noblem Geblüt, &lt;Name&gt;. Wir und alle Menschen in Eschental preisen Euch für Eure Bemühungen gegen das Böse.", rewards = "Streitkolben der Tiefschwarzen GrotteGeschenk des enigmatischen BaumesAluwyns BeinschützerIhr bekommt:\n\nNimbusstiefelHerzholzgurt"}
MultiLanguageQuestData['de'][26884] = {title = "Erforschung der Verderbnis", objective = "Sammelt 8 verderbte Hirnstämme.", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. Versucht die Hirnstämme nicht zu beschädigen während Ihr sie tötet, ich brauche ausschließlich makellose Exemplare.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Tiefschwarzen Grotte kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr habt zweifellos großen Gefahren getrotzt, um diese hier zu bekommen.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, &lt;Name&gt;.\n\nWenn Ihr mich nun entschuldigen würdet, ich habe viel zu tun.", rewards = "SeziererSchattensternkolbenSuchender ZauberstabAuf Euch wartet eine dieser Belohnungen:\n\nBand des Schädelquetschers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26885] = {title = "Wissen in der Tiefe", objective = "Findet das Manuskript von Lorgalis.", description = "Wie Ihr vielleicht wisst, ist es meine Pflicht als Auszubildende, Lehren für meine Vorgesetzten zusammenzutragen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die schlafenden Alten Götter erwecken können, wenn sie missbraucht werden.\n\nEs kursieren Gerüchte um einen alten Text, das 'Manuskript von Lorgalis', das sich tief auf dem Boden des Teichs von Ask'ar befindet, in einer eingedellten Eisentruhe. Dieser Ort ist die ehemalige Heimat unserer längst verstorbenen Ahnen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht das Manuskript, bitte. Ich verfüge nicht über genug Fähigkeiten, um weiter voranzuschreiten!", progress = "Eure Aufgabe ist keine leichte, mein Freund.\n\nAber wenn Ihr mir das Manuskript besorgt, <Name>... dann gebührt Euch eine großzügige Belohnung und wir erhalten ein besseres Verständnis davon, was der Schattenhammer und die Naga im Schilde führen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Ich werde es gründlich studieren und alles lernen, was es zu lernen gibt.\n\nIch werde es doch noch zur Schildwache bringen!\n\nIhr habt uns einen größeren Dienst erwiesen, als Ihr ahnt, &lt;Name&gt;. Ich hoffe, dieses Geschenk zeigt Euch meine Dankbarkeit.", rewards = "AbendruhbogenVerstaubter UmhangAuf Euch wartet eine dieser Belohnungen:\n\nDämmerungsband\n\nIhr bekommt außerdem:\n\nErhaltender Ring"}
MultiLanguageQuestData['de'][26886] = {title = "Genug gebrüllt", objective = "Tötet den Zuchtmeister der Südmeerfreibeuter.", description = "Das fiese Schiff auf der Nordseite der Bucht feuert ständig seine Kanonen auf uns ab. Es ist ja ganz lustig zuzusehen, wie die Goblins von Kanonenkugeln getroffen werden, aber einige meiner Gnomfreunde werden auch getroffen!\n\nEs wäre wirklich sehr nett, wenn Ihr es schafft, Euch an den Kanonen vorbei auf das Schiff zu begeben. Da ist ein gemeiner alter Zuchtmeister, der die anderen Deckmatrosen anschreit. Ich bin sicher, wenn Ihr ihn verprügelt oder tötet, werden sie nicht länger auf uns schießen!", progress = nil, completion = "Wunderbar! Ich hoffe, Ihr wurdet nicht von zu vielen Kanonenkugeln getroffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26887] = {title = "Wir füllen uns die Taschen", objective = "Sammelt 20 Goldfüllungen von Musketieren oder Schlägern der Südmeerfreibeuter.", description = "Ich weiß, wir sind hier um uns mit den Dampfdruckgoblins anzufreunden, aber diese grässlichen Bilgewassergoblins sind so unverschämt.\n\nWarum? Ich sah gerade, wie eine Gruppe von ihnen aus den Zähnen von Musketieren und Schlägern der Südmeerfreibeuter Goldfüllungen herausrissen. Glauben die, sie können das einfach für sich behalten?\n\nNatürlich wäre es nett, wenn wir die Piraten selbst umbringen, ihre Füllungen selbst herausnehmen und dann den Dampfdruckgoblins einige als Dankesgeschenk übergeben! Geht dort hinunter und kommt den Goblins zuvor.", progress = "Habt Ihr die Füllungen?", completion = "Noch mehr Gold! Wir werden Mister Noggenfogger bestimmt etwas davon abgeben, damit unsere Beziehung auch in Zukunft reibungslos verläuft.\n\nNur ein kleiner Teil wird nach Gnomeregan für die Entwicklung experimenteller Waffen zurückgebracht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26888] = {title = "Alptraum in der Tiefe", objective = "Tötet Aku'mai.", description = "In den dunkelsten Winkeln der Tiefschwarzen Grotte ist ein Monster dort erschienen, wo die Alten Götter lauern. Wir kennen es nur als Aku'mai.\n\nDie Alten Götter und ihre Diener sind eine große Gefahr für unsere Welt. Vor langer Zeit herrschten sie über Azeroth und ich fürchte, dass sie diese Herrschaft erneut anstreben, auch wenn sie Azeroth bei dem Versuch zerstören würden.\n\n<Name>, Aku'mai ist eine Kreatur unbeschreiblicher Alpträume. Wir können einfach nicht dulden, dass sie weiter existiert. Vernichtet sie.", progress = nil, completion = "Das Ungeheuer ist tot. Ich spüre, wie seine dunkle Gegenwart für immer vergeht.", rewards = "Je'neus RobenGamaschen der Tiefschwarzen GrotteSchuppen von Aku'maiSchild gegen die bösartige PräsenzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26889] = {title = "Genug der Fröhlichkeit", objective = "Sprecht am Außenposten der Schmuggler mit Zeke Scheuerschuh.", description = "Meine Güte, wir haben hier ganz schön aufgeräumt!\n\n<Kelsey räuspert sich.>\n\nHört mal, <Name>, ich freue mich darauf, diese Tötungskiste zu verlassen, damit ich endlich von diesen Goblins wegkomme und die aufgesetzte Fröhlichkeit ablegen kann. Wenn Ihr hier in der Gegend die Interessen von Gnomeregan weiter vertreten möchtet - und damit auch die der Allianz -, geht vom Außenposten der Schmuggler nach Süden.\n\nSprecht dort mit Zeke Scheuerschuh und denkt daran, dass jegliche Arbeit für die Dampfdruckgoblins uns dabei helfen wird, die Bilgewassergoblins endgültig aus Tanaris zu vertreiben.", progress = nil, completion = "Wisst Ihr, eigentlich bin ich ja nicht beeindruckt, wenn ich einen &lt;Volk&gt; sehe, aber ich habe gehört, was Ihr für Dampfdruck getan habt. Ihr seid in Ordnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26890] = {title = "Die Essenz von Aku'mai", objective = "Sammelt 20 Saphire von Aku'mai.", description = "Im Eingangsbereich der Tunnel der Tiefschwarzen Grotte findet man überall an den Höhlenwänden große Saphiransammlungen. Uns ist aufgefallen, dass die Naga zur selben Zeit angefangen haben, diese Kristalle abzubauen, als sich auch ihre Waffen stark verbessert haben.\n\nDie Kristalle besitzen offenbar große Elementarkraft und wenn man sie zweckentfremdet, könnten sie eine mächtige Komponente für meine Schmiedekunst sein.\n\nWerdet Ihr mir helfen, <Name>? Die Tiefschwarze Grotte liegt am Zoramstrand nördlich unseres Außenpostens.", progress = "Wie läuft Eure Suche nach den Kristallen, <Name>? Meint Ihr wir können daraus einen Gegenstand anfertigen, mit dem wir die Naga aufhalten können?", completion = "Ausgezeichnet! Die sind genau richtig. Hier habt Ihr eine Belohnung für Eure harte Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26891] = {title = "Inmitten der Ruinen", objective = "Findet den Tiefenkern.", description = "Die Anhänger des Schattenhammers sind hier in die Mondschreinruinen eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen.\n\n<Name>, findet die Zwielichtagenten hier, dann sucht den Tiefenstein der Ruinen. Er dürfte sich irgendwo unter Wasser befinden, wahrscheinlich direkt vor ihren Nasen. Darin ist ein Tiefenkern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", progress = "Konntet Ihr den Tiefenkern finden? Ohne ihn haben wir keine Ahnung, was genau die Anhänger des Schattenhammers da unten vorhaben.", completion = "Genau das brauche ich! Ein Tiefenkern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Schattenhammerkultisten da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann - meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26892] = {title = "In den tiefsten Tiefen", objective = "Vernichtet Ghamoo-Ra, Lady Sarevess und Gelihast.", description = "Die Naga und der Schattenhammer arbeiten zusammen, um all den Fortschritt, den wir in dieser Gegend erzielt haben, zunichtezumachen. Schlimmer noch, Je'neu sagte mir, dass er die Gegenwart eines Alten Gottes tief unter uns spürt.\n\nWenn sie Chaos haben wollen, dann werden wir ihnen genau das geben.\n\n<Name>, schlagt ihre stärksten Krieger und dann werden wir sehen, wie ihnen das gefällt.\n\nSeid bei Eurer Suche vorsichtig, die Tiefschwarze Grotte ist voller Unterwasserpassagen und Seitengänge, in denen sich Eure Ziele verbergen können.", progress = "Sagt mir, <Name>, rennen sie panikerfüllt umher? Sie bekommen genau das, was sie verdienen.", completion = "Ich kann ihre Schreie von hier aus hören! Vielleicht wird ihnen dies zeigen, wie töricht es ist, sich die Rückkehr eines Alten Gottes zu wünschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26893] = {title = "Die Tiefschwarze Grotte", objective = "Sprecht mit Je'neu Sancrea.Es gibt eine Aufgabe, für die Ihr perfekt geeignet seid, <Klasse>. Wir müssen die Gegend um die Tiefschwarze Grotte herum gegen die Allianz sichern, die den Außenposten von Zoram'gar im Westen von hier bedroht.\n\nGeht zur Tiefschwarzen Grotte nördlich des Außenpostens von Zoram'gar und sprecht mit Je'neu vom Irdenen Ring. Er wird viel für Euch zu tun haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Es gibt eine Aufgabe, für die Ihr perfekt geeignet seid, <Klasse>. Wir müssen die Gegend um die Tiefschwarze Grotte herum gegen die Allianz sichern, die den Außenposten von Zoram'gar im Westen von hier bedroht.\n\nGeht zur Tiefschwarzen Grotte nördlich des Außenpostens von Zoram'gar und sprecht mit Je'neu vom Irdenen Ring. Er wird viel für Euch zu tun haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26894] = {title = "Die Tiefschwarze Grotte", objective = "Sprecht mit Je'neu Sancrea.", description = "Die Naga verspotten uns mit ihrem offenen Widerstand. Wir werden sie und ihre Verbündeten endgültig aus diesen Landen vertreiben.\n\nReist nach Norden zu der Tiefschwarzen Grotte und sprecht mit Je'neu Sancrea. Er hat sie bereits betreten.\n\nÜbrigens, nehmt Euch vor Zeya in Acht. Sie ist manchmal etwas... launisch.", progress = nil, completion = "Hat Kommandant Grimmfang Euch geschickt? Ich habe ihn gebeten, passende Rekruten zu finden, die mir hier helfen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26895] = {title = "Die Donnerkuppel!", objective = "Sprecht in Gadgetzan mit Doktor Haudenlukas.", description = "Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? \n\nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anzeigen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt! Macht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden weiter!", progress = nil, completion = "Noch ein stolzer &lt;Klasse&gt;, angelockt vom Versprechen des Ruhms! Von Reichtum! Von GEWALT!\n\nJa, willkommen, mein Freund. Willkommen in der DONNERKUPPEL!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26896] = {title = "Die Donnerkuppel!", objective = "Sprecht in Gadgetzan mit Doktor Haudenlukas.", description = "Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? \n\nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anklagen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt!\n\nMacht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden!", progress = nil, completion = "Noch ein stolzer &lt;Klasse&gt;, angelockt vom Versprechen des Ruhms! Von Reichtum! Von GEWALT!\n\nJa, willkommen, mein Freund. Willkommen in der DONNERKUPPEL!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26897] = {title = "Die Tiefschwarze Grotte", objective = "Sprecht mit Schildwache Aluwyn.", description = "Obwohl wir hier ziemlich auf dem Präsentierteller stehen, sind wir noch sicher im Vergleich zu unseren Freunden in der Tiefschwarzen Grotte! Sie sind nur einige Fuß entfernt von den tödlichsten Nagatruppen des Landes. Sprecht mit Schildwache Aluwyn und gebt ihnen die Hilfe, die sie so dringend benötigen!", progress = nil, completion = "Elune sei Dank - Ihr seid hier! Wir können jede Hilfe gebrauchen, die wir bekommen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26898] = {title = "Die Tiefschwarze Grotte", objective = "Sprecht mit Schildwache Aluwyn.", description = "Ich mache mir sehr viel aus diesen Wäldern, <Klasse>. Es sieht wirklich nicht gut aus hier, aber ich würde mich lieber der Horde allein entgegenstellen, als zuzusehen, wie sie sich ihren Weg durch die Bäume hacken und schneiden.\n\nReist nach Westen zur Tiefschwarze Grotte. Sobald Ihr sie betretet, sucht Schildwache Aluwyn auf. Sie ist eine enge Vertraute, die Hilfe benötigt. Die \n\nOrcs im Außenposten von Zoram'gar bedrohen ihre Position in diesem Augenblick. Wenn sie die Tiefschwarze Grotte einnehmen, werden sie bestimmt jeden Baum fällen, um ihren Wahnsinn zu schüren.", progress = nil, completion = "Elune sei Dank - Ihr seid hier! Wir können jede Hilfe gebrauchen, die wir bekommen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26899] = {title = "Der Feind meines Feindes", objective = "Verschafft Euch den Kopf von Zwielichtfürst Kelris.", description = "Kultisten...Opfer...Macht...\n\nFeind...erwacht...\n\nAlter Gott...sperrt...mich ein...\n\nLord...Kelris...\n\nBringt Kopf...Rache...\n\nAUSLÖSCHEN!!!", progress = "Rache...Belohnung...", completion = "&lt;Der flammende Vernichter scheint sich zu konzentrieren.&gt;\n\nIch schone Euer Leben für Eure Hilfe, &lt;Volk&gt;. Geht jetzt...bevor ich es mir...anders überlege.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26901] = {title = "Go, Go, Guano!", objective = "Sammelt 1 Häufchen Kralguano", description = "Die Fledermäuse aus dem Kral der Klingenhauer produzieren eine äußerst seltsame, natürliche Substanz. Der Gestank ihres Guano scheint die Stacheleber in mörderische Raserei zu versetzen - und hier stinkt es gewaltig danach!\n\nIhr müsst die Fledermaushöhle finden und mir eine passende Probe bringen. Wenn wir die Auswirkungen umkehren und ein Gegengift herstellen können, können wir die Stacheleber vielleicht retten.", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt. Konntet Ihr etwas Kralguano beschaffen?", completion = "Gut gemacht! Das ist genau das, was wir brauchen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26903] = {title = "Willix der Importeur", objective = "Führt Willix den Importeur aus dem Kral der Klingenhauer hinaus.", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer auf die schnelle Mark aus, wie man so sagt. Ich habe Wind davon bekommen, dass sich Schweineschnauzen unglaublich gut auf dem Markt verkaufen lassen. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, soll es Euer Schaden nicht sein.", progress = nil, completion = "Nochmals danke, Freund! Ich sagte doch, es würde sich für Euch lohnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAffenringNatternreifenTigerband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26904] = {title = "Verderbnis", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Wirkt es dann fünfmal auf eine Trainingsattrappe nahe des Eingangs zu Ambossar.", description = "Nur wenige Menschen, besonders unter unseren Verbündeten, sind wirklich in der Lage, die Natur der Macht nachzuvollziehen, die wir besitzen. Sie meiden uns, weil sie zu schwach sind, das Wissen, das wir besitzen, richtig anzuwenden.\n\nwenn Ihr mächtiger werdet, werdet Ihr neue Zauber entdecken, die Eure Macht nur weiter mehren.\n\nGeht, sammelt Erfahrung und kehrt zu mir zurück, sobald Ihr einen neuen Zauber erlernt habt. Dann werden wir sehen, ob Ihr die dunklen Künste wahrlich beherrscht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26905] = {title = "Agamaggans Auftrag", objective = "Nehmt Charlga Klingenflanke das Herz.", description = "Hört gut zu, Sterblicher.\n\nDie Stacheleber sind meine Kinder. Dieses Land ist von meinem Blut durchzogen.\n\nCharlga Klingenflanke hat meine Kinder in die Dunkelheit geführt, nachdem sie von der Geißel in den Wahnsinn getrieben wurde.\n\nTötet sie, <Name>. Tötet sie und öffnet meinen Kindern die Augen.\n\nGebt den Stachelebern die Chance, wieder zu ihren edlen Wurzeln zurückzukehren.\n\nLasst sie meinen Segen wieder verdienen. Bringt mir ihr Herz!!!\n\n", progress = "<Der Geist von Agamaggan betrachtet Euch geduldig.>", completion = "Nehmt dieses Geschenk. Ihr habt Euch heute wahrlich meinen Segen verdient.", rewards = "Agamaggans GabeCharlgas BrustplatteVon Agamaggan gesegnete SchienbeinschützerStiefel des edlen WegesAuf Euch wartet eine dieser Belohnungen:\n\nAgamaggans stille Träne\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26906] = {title = "Agamaggan", objective = "Sprecht mit dem Geist von Agamaggan.", description = "Ich spüre eine ungeheure Macht in diesen gewundenen Dornen, <Name>. Die ganze Gegend wird durch ihre Gegenwart belebt.\n\nEs muss der Geist von Agamaggan sein! Er war eins der ersten und mächtigsten Wesen, die je gelebt haben - die Stacheleber verehren ihn zutiefst.\n\nJede Ranke, die Ihr im Lande seht, stammt von seinem Blut - von dem Opfer, das er brachte, um Azeroth während des Kriegs der Ahnen zu retten.\n\nWenn ein Wesen die Stacheleber wieder zu ihren edlen Wurzeln führen kann, dann er.\n\nIhr müsst ihn finden.", progress = nil, completion = "&lt;Der Geist von Agamaggan betrachtet Euch. Eine uralte Stimme ertönt in Eurem Kopf.&gt;\n\nIch habe darauf gewartet, dass Ihr herkommt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26907] = {title = "Macht sie nieder!", objective = "Tötet Aggem Dornfluch, Todessprecher Jargba, Oberanführer Rammhauer und Agathelos den Tobenden.", description = "Oberanführer Rammhauer und die Totenköpfe machen für den Krieg mobil. Es hat viele Späher das Leben gekostet, aber wir haben erfahren, mit Hilfe welcher Waffe sie den Rest des Brachlands übernehmen wollen.\n\nMan nennt ihn Agathelos den Tobenden. Er ist ein gewaltiger Eber mit schwerer Rüstung, dem man zwangsweise Kralfledermausguano verabreicht hat, das Raserei auslöst.\n\n<Volk>, Ihr müsst sie aufhalten, bevor sie unschuldige Leben vernichten!", progress = nil, completion = "Ihr habt Eure Sache heute gut gemacht. Agathelos hätte in seiner Wut viele Leben ausgelöscht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26908] = {title = "Dorn im Auge", objective = "Sprecht mit Auld Steinkeil.", description = "Mankriks Wut über seine tote Frau bietet Anlass zu weiterer Sorge, <Klasse>.\n\nDie Stacheleber im Kral der Klingenhauer sind weitaus skrupelloser und hasserfüllter als Mankrik sich vorstellen konnte.\n\nIhr solltet nach Süden reisen und mit meinem alten Freund Auld Steinkeil sprechen. Er arbeitet daran, ihrer Raserei ein Ende zu bereiten, bevor das ohnehin geschwächte Land noch mehr leidet.", progress = nil, completion = "Nur ein Veteran wie Ihr könnte den Gefahren, die hier lauern, trotzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26909] = {title = "Die Steinsplitter", objective = "Untersucht die Splitter von Myzrael.", description = "Uralte Steine sind über das ganze Land verstreut. Die Elemente strömen in Scharen zu ihnen und umringen sie schützend.\n\nEs handelt sich um Orte großer Macht. Der größte von ihnen liegt westlich von Hammerfall. Keine Seele dringt dort widerrechtlich ein, aber wenn Ihr alleine dort hingeht, hört ihr das Flüstern der Erde.\n\nIch bin schon lange nicht mehr dort gewesen, aber unsere Grunzer berichteten mir, dass das Flüstern wieder begonnen hat. Würdet Ihr für mich nachsehen? Werdet ihr nachsehen, ob die Steine immer noch sprechen?", progress = nil, completion = "&lt;Die Splitter pulsieren sanft und ein Flüstern hallt in Eurem Kopf wider.&gt;\n\nHilfe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26910] = {title = "Geätzter Brief", objective = "Lest den geätzten Brief und sprecht im Nordhaintal mit Ashley Blank.", description = "Mir wurde aufgetragen, Euch so bald wie möglich, nachdem Ihr von der Angelegenheit mit den Spionen des Schwarzfels zurückgekehrt seid, hierauf aufmerksam zu machen, <Name>. Es scheint sich um einen Brief zu handeln, der mit dem Siegel von Ashley Blank, unserer Jägerlehrerin, versehen ist. Ich würde keine Zeit verlieren und ihn sofort lesen, bevor Ihr hier in der Abtei irgendetwas anderes macht.", progress = "Hallo, <Name>. Gibt es etwas, das ich für Euch tun kann?", completion = "Ihr habt meine Nachricht also erhalten? Ausgezeichnet. Ihr habt Euch im Umgang mit den Orcs als recht geschickt erwiesen. Während Ihr immer mächtiger werdet, werde ich Euch einige neue Techniken lehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26911] = {title = "Myzraels Geschichte", objective = "Kehrt in das Arathihochland nach Hammerfall zu Zaruk zurück.", description = "Als der Stein in Schweigen verfällt, bleibt Ihr mit einem vagen Unbehagen zurück. Etwas stimmt nicht.\n\nVielleicht solltet Ihr Zaruk erzählen, was Ihr bis jetzt getan habt.", progress = nil, completion = "Ich weiß, &lt;Name&gt;. Ich hätte Euch nicht schicken dürfen.\n\nVergebt mir... Das Flüstern der Stimmen aus der Vergangenheit ist manchmal zu stark.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26912] = {title = "Die entfesselte Prinzessin", objective = "Ruft Myzrael an den Splittern von Myzrael herbei und besiegt sie.", description = "Myzrael ist eine Betrügerin. Sie ist eine uralte Macht, die vor langer Zeit unter Verschluss genommen wurde und da sollte sie auch bleiben.\n\nIhr müsst an den Splittern von Myzrael, wo Ihr zuerst mit ihr gesprochen habt, die Konfrontation mit ihr suchen. Ruft sie mit dieser Schriftrolle herbei. Wenn sie dann in voller Größe an der Oberfläche angelangt ist, besiegt sie. Dann nehmt die geisterhaften Fesseln von ihrem Körper und legt sie auf die Splitter, damit sie wieder vollkommen gebunden ist.\n\nViel Glück, <Name>... Möge die Vergangenheit Euch nicht mehr beunruhigen.", progress = "Die Splitter von Myzrael sind jetzt seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", rewards = "Wickeltuch der offenen BedrohungGespenstische HandschuheErdengebundener MantelFesselnde HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26913] = {title = "In den Kampf stürmen", objective = "Erreicht Stufe 3 und erlernt Sturmangriff. Übt dann die Anwendung von Sturmangriff an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", description = "Jetzt, da Ihr Gelegenheit hattet, Eure Fähigkeiten im Kampf zu erproben, wird es Zeit, Euch noch einen Grund vorzustellen, warum das Üben so wichtig ist.\n\nWenn Ihr nämlich mehr Erfahrung sammelt, könnt Ihr bald Techniken beherrschen, die Ihr Euch jetzt nicht zutrauen würdet.\n\nAlso macht Euch auf und sammelt noch etwas mehr Erfahrung. Erlernt eine neue Fähigkeit und zeigt sie mir an einer der Trainingsattrappen.", progress = nil, completion = "Ihr lernt schnell, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26914] = {title = "Verderbnis", objective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Übt dann die Anwendung von 'Verderbnis' fünfmal an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", description = "Wir müssen hier in der Abtei und in ihrer Umgebung vorsichtig mit dem sein, was wir sagen, aber lasst Euch dadurch nicht vom Pfad der Macht abbringen.\n\nWenn Ihr mehr Erfahrung sammelt, werdet Ihr die Teufelsstimmen hören, die Euch ihre Macht über die dunklen Künste gewähren.\n\nGeht, sammelt mehr Erfahrung und erlernt einen neuen Zauber. Wenn es so weit ist, möchte ich, dass Ihr ihn bei einer der Trainingsattrappen ausprobiert.", progress = "Nun, habt Ihr es ausprobiert?", completion = "Wie ich sehe, beherrscht Ihr Feuerbrand bereits. Ich freue mich darauf, Euch in Zukunft weiter zu unterrichten. Vergesst nicht, für weitere Lektionen zurückzukehren, während Ihr immer mächtiger werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26915] = {title = "Tiefe Einschnitte", objective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Sucht dann eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain und übt daran dreimal die Anwendung von 'Ausweiden'.", description = "Bisher kennt Ihr die Grundlagen für den Kampf als Schurke, aber ich möchte Euch eine neue Fähigkeit lehren. Als Schurken sind wir dafür bekannt, Ketten von Kampftechniken ausführen zu können und uns den mächtigsten Schlag bis zum Ende aufzubewahren.\n\nWenn Ihr erfahrener werdet, erlernt Ihr neue Dinge - und dies ist eins der Dinge, das Ihr als erstes erlernt. Wenn es so weit ist, möchte ich, dass Ihr es bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", progress = nil, completion = "Ihr habt schnell begriffen, &lt;Name&gt;, und ein agiler Geist wird Euch sehr nützlich sein. Kehrt zu mir zurück, wenn Ihr mächtiger geworden seid und ich werde Euch neue Techniken lehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26916] = {title = "Beherrschung des Arkanen", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Übt den Zauber dann zweimal an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", description = "Als Magier werdet Ihr mit wachsendem Verständnis eine Vielzahl von Zaubern lernen. Alles, was Ihr tun müsst, ist Erfahrungen sammeln und die Geheimnisse des Arkanen werden sich Euch offenbaren.\n\nIhr werdet sehen. Geht, entwickelt Eure Kräfte und zeigt mir dann, was Ihr gelernt habt.", progress = nil, completion = "Beherrscht Ihr die Anwendung von 'Frostnova' bereits? Ihr lernt die arkanen Künste schnell und habt eine vielversprechende Zukunft vor Euch. Vergesst nicht, für weitere Ausbildung zu mir zurückzukehren, während Ihr immer mächtiger werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26917] = {title = "Der Weg des Jägers", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Sucht dann eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain und übt fünfmal 'Zuverlässiger Schuss'.", description = "Ich hörte, dass Ihr geholfen habt, einige der Orcs auszumerzen. Ihr habt bewiesen, dass Ihr Euch im Kampf zu verhalten wisst.\n\nWenn Ihr mehr erfahrener im Kampf werdet, lernt Ihr auch neue Dinge. Ich will, dass Ihr da raus geht, Erfahrungen sammelt und dann die neu erlernten Fähigkeiten an den Trainingsattrappen am Eingang der Abtei ausprobiert.", progress = nil, completion = "Ich wusste, Ihr würdet 'Zuverlässiger Schuss' schnell meistern. Ich freue mich darauf, Euch neue Techniken zu zeigen, wenn Ihr weitere Erfahrungen als Jäger gesammelt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26918] = {title = "Die Macht des Lichts", objective = "Erreicht Stufe 3, um das Siegel des Befehls zu erlernen. Wirkt das Siegel des Befehls auf Euch selbst und schlagt dann eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", description = "Je weiter Ihr den Pfad des Paladins beschreitet, desto näher kommt Ihr dem Licht und desto mehr Fähigkeiten könnt Ihr lernen.\n\nZieht los, sammelt etwas Erfahrung und erlernt eine neue Fähigkeit. Wenn Ihr sie mir vorgeführt habt, können wir mit Eurer Ausbildung fortfahren.", progress = "Nun, habt Ihr es ausprobiert?", completion = "Ihr lernt schnell, &lt;Name&gt;. Kehrt zu mir zurück, wenn Ihr stärker geworden seid und ich werde Euch mehr darüber lehren, wie Ihr das Licht zur Vernichtung Eurer Feinde und zur Stärkung Eurer Verbündeten anwenden könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26919] = {title = "Das richtige Wort", objective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen, und benutzt es fünfmal an den Trainingsattrappen vor der Abtei von Nordhain.", description = "Als <Priester/Priesterin> müsst Ihr Euch unter anderem um die Verwundeten kümmern. Eine weiter Verpflichtung ist, in die Welt hinauszugehen und etwas… aktiver an ihre Verteidigung heranzugehen.\n\nWährend Ihr das tut, werdet Ihr mehr Macht erlangen und alle möglichen neuen Dinge lernen.\n\nGeht, sammelt mehr Erfahrung und kehrt dann zu mir zurück und zeigt mir, was Ihr erlernt habt.", progress = nil, completion = "Ihr lernt schnell, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26920] = {title = "Die Schlacht um Andorhal", objective = "Meldet Euch in den Westlichen Pestländern innerhalb Andorhals bei Koltira Todesweber.", description = "Beeilt Euch, <Name>... Wir haben keine Zeit zu verschwenden.\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. Fürstin Sylvanas hat einen ihrer besten Todesritter entsandt, um den Sturmangriff für ihre Sache zu leiten. Dennoch bin ich sicher, dass er jede Hilfe gebrauchen kann. Arthas ist tot, deshalb ist jetzt der perfekte Zeitpunkt für die Verlassenen, Andorhal einzunehmen.\n\nSprecht mit dem Fledermausführer Timothy Cunningham, wenn Ihr bereit seid, und er wird Euch den nächsten Flug dorthin verschaffen.", progress = nil, completion = "Wurde auch Zeit, dass Ihr eintrefft, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26921] = {title = "Erst die Geißel... dann die Allianz", objective = "Tötet 15 ausgedörrte Geißeldiener in Andorhal.", description = "Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein alter Widerpart, Thassarian, führt die Streitkräfte der Allianz an. Wenn wir Andorhal für uns gewinnen wollen, müssen wir beide besiegen. Doch wir werden sicherlich nicht beide gleichzeitig angreifen können.\n\nIch kenne Thassarian gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden dasselbe tun.\n\nSchaltet die schwächeren ausgedörrten Geißeldiener aus, damit sie zahlenmäßig unterlegen sind. Die Allianz wird unsere Rache erst später zu spüren bekommen.", progress = nil, completion = "Ihr seid zwar nicht besonders schnell, aber wenigstens enttäuscht Ihr mich nicht.\n\nSehr schön. Sobald die Zeit reif ist, werde ich noch eine wichtigere Aufgabe für Euch haben, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26922] = {title = "Der unendliche Fluss", objective = "Benutzt Jearls Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.", description = "Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten... eine Armee von Schwächlingen, die Euch eher überrennen als übermannen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!\n\n<Jearl reicht Euch ein paar Granaten.>\n\nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.", progress = nil, completion = "Diese Granaten sind Sprengstoff, mehr nicht. Selbst als Mitglied der Königlichen Apothekervereinigung sehe ich ein, dass sich manche Probleme nicht dadurch lösen lassen, mehr Seuche nach ihnen zu werfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26923] = {title = "Kriegsmaschinen", objective = "Vernichtet 6 aufgeschlitzte Ungetüme in Andorhal.", description = "Ihr Narren werdet die Geißel niemals besiegen, solange diese Monstrositäten herumlaufen. Koltira quasselt ständig davon, sie zahlenmäßig unterlegen zu machen, aber die beste Waffe der Geißel hier in Andorhal findet man unter diesen herumtorkelnden Schlägern, die meine Todeswachen wie Puppen umherschleudern.\n\nDas hat jetzt ein Ende.\n\n<Name>, geht auf das Schlachtfeld und vernichtet diese Monster.", progress = nil, completion = "Jetzt, da die Ungetüme aus dem Weg sind, ist uns der Sieg gegen die Geißel gewiss.\n\nUnsere Chancen gegen die Allianz sind momentan nicht ganz so günstig... Aber das soll Euch nicht kümmern. Jedenfalls noch nicht.", rewards = "Armschienen der günstigen ChancenGürtel des geschwätzigen NarrenUngetümstiefelWanstöffnerhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26924] = {title = "Scholomancer", objective = "Tötet Dunkelmeister Gandling in Andorhal.", description = "Scholomance ist eine der letzten verbliebenen Bastionen der Geißel im Westen von Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld aufgetaucht.\n\nDas wird sein letzter Fehler sein.\n\nIhr findet Gandling auf einem Platz in der Nähe des südlichen Stadtrands. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch unterstützen, damit er sein Ende findet.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Jetzt, da der Anführer der Streitmächte der Geißel nicht länger in Andorhal sein Unwesen treibt, müssen wir den richtigen Augenblick abwarten.", rewards = "Gandlings HandschuheBürde der ZeitArmschienen der BeseitigungGürtel der anhaltenden VerderbnisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26925] = {title = "Araj der Beschwörer", objective = "Tötet Araj den Beschwörer. Ihr könnt Jearls Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.", description = "Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln gesehen.\n\nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.", progress = "Araj ist ein ausgezeichneter Gegner. Ihr solltet gut vorbereitet sein.", completion = "Araj ist tot... das ist gut. Die Königliche Apothekervereinigung hat ihren Part getan. Und Ihr auch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26926] = {title = "Sieg, im Moment", objective = "Meldet Euch in Tirisfal am Bollwerk bei Hochexekutor Derrington.", description = "Die Verlassenen haben gesiegt und unsere Streitmächte sind immer noch stark. Gemäß unserer strategischen Kriegsführung müssten wir die Allianz jetzt angreifen, solange man sich dort noch vom Kampf erholt und nicht mit einem Angriff rechnet. Ich habe allerdings andere Pläne...\n\nWir werden warten. Wir greifen Thassarian und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Rhonda Molver und nehmt einen Flug Richtung Bollwerk an der westlichen Grenze der Pestländer. Hochexekutor Derrington wird Euch mit Eurer nächsten Aufgabe vertraut machen.\n\nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.", progress = nil, completion = "Die Nachricht traf kurz vor Euch ein, &lt;Name&gt;. Dass die Geißel aus Andorhal hinausgeworfen wurde hat die Stellung der Verlassenen in Lordaeron gefestigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26927] = {title = "...und plötzlich Murlocs!", objective = "Sprecht mit Kanari Zielwasser.", description = "Also, wir haben Troggs, die für Kobolde arbeiten und Kobolde, die für Gnolle arbeiten. Die Gnolle müssen aus dem Sumpfland hergezogen sein.\n\nWas weiß ich denn? Nun, sie haben Freunde mitgebracht, denn die Murloc der Blaukiemen schwärmen überall am Loch herum, oder an dem, was von ihm übrig geblieben ist.\n\nPlagegeister sind Plagegeister, aber die Koordination ist besorgniserregend. Ihr müsst mit Kanari Zielwasser reden. Sie ist eine der besten Jägerinnen im Umkreis und sie wird wissen, wie man mit den Murlocs umgeht - wenn es Euch gelingt, sie lange genug von ihrem Krug wegzuzerren.", progress = nil, completion = "Murlocs? Natürlich habe ich Murlocs gejagt.\n\nUnd jeder einzelne dieser Stinker hat bekommen, was er verdiente! Versteht Ihr mich?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26928] = {title = "Das riecht nach 'nem Plan", objective = "Sammelt am Loch 7 Stinkdrüsen eines Murlocs von beliebigen Murlocs der Blaukiemen.", description = "Murlocs, die mit Gnollen zusammenarbeiten? Das ist lachhaft! Nun, sie einfach nur zu töten wird Euch auch nicht weiterhelfen. Es gibt zu viele von den Quälgeistern.\n\nAber ich habe einen Plan - ich benutze mein Köpfchen, müsst Ihr wissen. Diese Murlocs sondern einen Geruch ab, den sie überall hinterlassen. Wenn andere Murlocs das riechen, werden sie irre! Damit kann man sie prima ködern.\n\nWie auch immer, sie haben kleine Drüsen, in denen sich der Geruchsstoff befindet. Geht und holt mir ein paar davon.", progress = "Ihr stinkt ja zum Himmel! Ich nehme an, dass das an den Murlocs liegt, aber es ist schwer zu sagen.", completion = "Puh! Welch ein Gestank.\n\nJetzt haltet Euch fest, denn ich werde Euch mit dem, was von meinen geistigen Fähigkeiten geblieben ist, umhauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26929] = {title = "Ein Haufen Kroki", objective = "Sammelt 6 Krokiliskenkiefer.", description = "Während Ihr herumlauft und das tut, was immer ihr da auch tut - würde es Euch da etwas ausmachen, mir ein wenig zu helfen?\n\nSchaut, normalerweise gehe ich unten am Loch Krokilisken jagen, aber unter den gegebenen Umständen ziehe ich es vor, hier zu sitzen. Es ist sehr höflich von Euch, mir deshalb keine Vorwürfe zu machen. Danke!\n\nDa ihr <solch ein feiner Herr/so eine feine Dame> seid, warum bringt Ihr mir nicht ein paar Krokiliskenkiefer mit und ich gebe Euch im Gegenzug ein bisschen fast sauberes Geld?", progress = "Habt Ihr diese Krokiliskdinger gefunden oder habe ich das geträumt?", completion = "Mächtig nett von Euch, einem alten Narren wie mir zu helfen. Hier ist Eure versprochene Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26930] = {title = "Nach dem Kreuzzug", objective = "Späht östlich vom Teufelssteinfeld in den Westlichen Pestländern das Lager des Scharlachroten Kreuzzugs aus.", description = "Unsere Siege häufen sich, <Name>. Der Scharlachrote Kreuzzug, der die Verlassenen schon seit Langem verfolgt, pfeift aus dem letzten Loch. Sie halten immer noch ihr Kloster hier in Tirisfal, aber sie haben Herdweiler und Tyrs Hand im fernen Osten verloren.\n\nErst letzte Woche gab es Berichte von Aktivitäten des Scharlachroten Kreuzzugs in einem kleinen Lager östlich vom Teufelssteinfeld, aber ich habe guten Grund anzunehmen, dass auch sie ausgelöscht wurden. Reist dorthin und überprüft für mich diese Information.", progress = nil, completion = "Brennende Leichen? Keine Überlebenden? Ich habe richtig vermutet.\n\nUmso besser! Wir sind besser dran, wenn die scharlachrote Verderbnis nicht über Lordaeron liegt. Sie verkörperten alles Schlechte am Menschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26931] = {title = "Füchse und Hunde", objective = "Tötet 4 Fuchsjäger der Allianz, 4 Bullenmastiffs und 4 Weißschwanzfüchse in den Westlichen Pestländern.", description = "Die Streitkräfte der Allianz laufen in den Pestländern herum, als ob die Gegend ihnen gehört. Nun, dem ist nicht so. Dieses Land gehört rechtmäßig der Dunklen Fürstin!\n\nAls der Kampf um Andorhal zum Ende kam, zerstreuten sich die Kräfte der Allianz, die die Pestländer besetzten. Einige von ihnen sind genau östlich von hier und jagen Füchse. Beweist ihnen, dass das hier das Gebiet der Verlassenen ist.\n\nTötet die Jäger. Tötet ihre Jagdhunde. Und wenn Ihr gerade dabei seid, tötet die Füchse noch obendrein.", progress = nil, completion = "Die Jäger aus dem Weg zu haben ist solch eine Erleichterung. Wir sind allerdings noch nicht fertig damit, Allianzler zu töten...", rewards = "BullmastiffwesteTerritorialer HelmGewehr des FuchsjägersAuf Euch wartet eine dieser Belohnungen:\n\nVandis' Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26932] = {title = "Ausgeflattert", objective = "Tötet 8 Lochbussarde.", description = "Als der Steinwerkdamm brach, legte er fast den ganzen See trocken. Eine verheerende Umweltkatastrophe.\n\nUnd wagt es nicht, zu denken, dass das keine Auswirkungen auf uns Zwerge hatte! Wir haben nicht nur absolut keine Fische mehr, sondern da draußen liegen über viele Morgen verstreut tote Dreschadon und verrotten in der Sonne. Die Bussarde sind hinter ihnen her und verbreiten dabei Dreck und Krankheiten an den Außenbezirken der Stadt.\n\nIch kann Euch nicht darum bitten, das alles zu säubern, aber könntet Ihr Euch der Bussarde annehmen? Es wird schon helfen, nur ein paar zu töten.", progress = nil, completion = "Das sollte die weitere Verbreitung von Krankheiten in dem Wasser, das uns noch geblieben ist, verhindern. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26933] = {title = "Feind oder Bauer?", objective = "Tötet 9 Allianzarbeiter auf dem Teufelssteinfeld.", description = "Die Männer, die das Teufelssteinfeld bestellen, sind keine Bauern. Sie sind Soldaten.\n\nThassarians Streitkräfte benötigten Nahrung, also hat er einige Allianzler aus Andorhal nach Norden entsandt, damit sie sich um das Teufelssteinfeld kümmern. Der Kampf um Andorhal mag vorüber sein, aber es droht bereits die nächste Schlacht... Verlassene gegen Menschen. Wenn die dort auf dem Teufelssteinfeld arbeitenden Soldaten getötet werden, wird das den Streitkräften der Dunklen Fürstin einen entscheidenden Vorteil verschaffen.", progress = nil, completion = "Haha! Ich hoffe, sie kommen als Zombies zurück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26934] = {title = "Verborgene Krankheit", objective = "Tötet kranke Schwarzbären in den Westlichen Pestländern und pflückt dann 20 Pesttentakel, die in der Nähe ihrer Körper wachsen.", description = "Ich brauche verseuchtes Gras für ein... ein Experiment sozusagen. Diese Argentumkreuzfahrer und die höllischen Cenarischen Druiden haben bei der Heilung der Pestländer wirklich ganze Arbeit geleistet. Ich kann keine brauchbaren Reagenzien in erreichbarer Nähe finden.\n\nAllerdings tragen einige der hiesigen Wildtiere noch die Seuche in sich. Tötet einen kranken Schwarzbär und pflückt dann das Gras, das dort wächst, wo sein verfallender Körper liegt. Das ist nicht optimal, aber es wird genügen.", progress = "Krankheiten erhalten sich in Tiergewebe so viel besser als in Pflanzengewebe, nicht wahr?", completion = "Großartig! Das ist das letzte Stück, das ich benötige.\n\nWartet doch noch einen Moment, &lt;Name&gt;. Lasst mich Euch ein wenig mehr über unseren Plan erzählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26935] = {title = "Sägewerk des Nordkamms", objective = "Meldet Euch bei Nathaniel Dumah im Sägewerk des Nordkamms in den Westlichen Pestländern.", description = "Wir sind nicht die einzigen Argentumkreuzfahrer hier in den Pestländern. Unser Hauptquartier, Herdweiler, liegt im Norden. Noch etwas näher im Norden ist ein kleines Sägewerk, das ebenfalls unter unserer Kontrolle steht.\n\nNathaniel Dumah ist mein Kontaktmann im Sägewerk. Sprecht ihn ruhig an, wenn Ihr dort einmal in der Nähe seid.", progress = nil, completion = "Willkommen in Nordkamm, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26936] = {title = "Weniger Bumm", objective = "Teufelssteinfeld ist geräumt und die Bomben sind scharfgemacht. Ich hoffe, Ihr seid bereit. Ich schlage vor, Ihr haltet Euch die Ohren zu.\n\n<Derrington schaut nach unten und legt seinen Finger auf einen Zündschalter.>\n\nALLES KLAR ZUR ZÜNDUNG! IN 3...\n\n2...\n\n1...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSeuchenbombe\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26937] = {title = "Wenn der Tod nicht ausreicht", objective = "Tötet 8 Allianzarbeiter auf dem Teufelssteinfeld, damit Eure bezauberte Val'kyr sie in Verlassene umwandeln kann.", description = "Derrington und seine Männer wissen es nicht, aber ich habe die Verseuchung vom Teufelssteinfeld angeordnet. Wir brauchen das Gebiet zum Üben. Wenn wir diesen Krieg für Andorhal gewinnen wollen, müssen wir unsere neueste und vielseitigste Waffe einsetzen:\n\nVal'kyr.\n\nNehmt diese umzauberte Val'kyr mit, <Name>, und tötet den jämmerlichen Abschaum der Allianz, der auf dem Teufelssteinfeld noch zu finden ist. Sobald einer tot ist, wird er von ihr in diese Welt zurückgeholt... als einer von uns.\n\nDie Verlassenen werden nicht aussterben!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26938] = {title = "Kampftraining", objective = "Benutzt die Fähigkeit Eurer umzauberten Val'kyr, um 5 Gardisten der Verlassenen auf dem Teufelssteinfeld zu mobilisieren. Dann tötet die aufgeschlitzte Monstrosität in der Teufelssteinscheune.", description = "Der einzige Lebenszweck einer Val'kyr ist zu dienen - und diese dient Euch. Ich werde Euch jetzt volle Kontrolle über ihre Fähigkeiten geben, <Name>.\n\nWenn Ihr in den Außenbereichen des Hofs herumlauft, solltet Ihr einige der Verlassenen finden, die Ihr gerade erschaffen habt. Ich möchte, dass Ihr Eure Val'kyr benutzt, um mindestens fünf von ihnen einzusammeln. Wenn Ihr das getan habt, nehmt Eure neue Soldatenkolonne, bringt sie in die Teufelssteinscheune und tötet die Bestie darin. Heute werdet Ihr lernen, was es heißt, für die Dunkle Fürstin zu kämpfen.", progress = nil, completion = "Wenn Koltira das Zeichen gibt, werde ich diese Val'kyr nach Andorhal hineinbringen. Wir werden gewinnen. Und noch ein weiterer Teil Lordaerons wird sich der Macht der Verlassenen beugen müssen.", rewards = "ZombieschrotflinteRabensonns KniehosenBezaubernde HandschuheMonströser SchulterschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26939] = {title = "Das G-Team", objective = "Tötet die Verflüssigte Ablagerung.", description = "Wie seid Ihr hier reingekommen?\n\nAch, ist auch egal. Ich bin Mör'dok vom G-Team. Wir sind die Besten, die es gibt und wir sind hier, um Gnomeregan zurückzuerobern!\n\nAls niemand anders ihm helfen konnte, kam der Hochtüftler zu uns und hat uns angeheuert.\n\nAber das kriegen wir nicht alleine hin! Ihr seid jetzt ein G-Team Kommandosoldat ehrenhalber, <Name>.\n\nNehmt diesen Fallschirm, springt geradeaus in die Halle der Zahnräder und tötet die Verflüssigte Ablagerung. Wenn Ihr fertig seid, meldet Euch bei Kommandosoldat Bi'ay Bäräkuss im westlichen Korridor. Ihr beide werdet Euch mit Sicherheit gut verstehen.", progress = nil, completion = "Ich hoffe, das hat Euch nicht überfordert. Die Mission ist noch längst nicht vorbei!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26940] = {title = "Frostnova", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Sucht in der Nähe nach einer Trainingsattrappe und übt daran die Anwendung von 'Frostnova' zwei Mal.", description = "Wir sind die Erben eines Vermächtnisses arkaner Magie und Euer Weg wird kein leichter sein. Viele machen uns immer noch für die Taten unserer Vorfahren verantwortlich, doch unsere Talente werden gebraucht.\n\nObwohl Ihr vorsichtig sein müsst, ist es wichtig, dass Ihr Eure Kräfte weiterentwickelt, da Ihr dadurch Eure Verbindung mit dem Arkanen vertieft und Zugang zu neuen Zaubern erhaltet.\n\nGeht, sammelt mehr Erfahrung mit Euren Zaubern und zeigt mir, was Ihr gelernt habt.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26941] = {title = "Das G-Team", objective = "Tötet den Elektrokutor 6000.", description = "Dieser Mör'dok ist verrückt, <Klasse>. Passt bloß auf, dass Ihr niemals mit diesem Gnom in einem Flugzeug sitzt.\n\nVerstohlenheit ist normalerweise nicht mein Ding, und sie wird ganz bestimmt auch nicht Eures sein. Geht diesen Flur entlang bis zur Abschussrampe und entledigt Euch des Elektrokutor 6000.\n\nDer Elektrokutor ist verantwortlich für die Luftfahrzeuge...\n\n... und ich hasse Luftfahrzeuge. Mich bekommt man in kein Luftfahrzeug!\n\nBenutzt diesen Fallschirm, um anschließend abzuspringen und sprecht mit Kommandosoldat Fähs über Eure nächste Aufgabe.", progress = nil, completion = "Hat ja lange genug gedauert. Kommt mit mir hinter die Säule, bevor Ihr unsere Tarnung auffliegen lasst!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26942] = {title = "Das G-Team", objective = "Tötet Robogenieur Thermadraht.", description = "Ich würde mich von Bi'ay Bäräkuss und Mör'dok geflissentlich fernhalten - die sind beide nicht ganz dicht.\n\nAber Ihr seid es, also an die Arbeit! Geht diesen Tunnel entlang, bis Ihr zum Tüftlerhof kommt. Hoffentlich wisst Ihr, was zu tun ist, wenn Ihr Robogenieur Thermadraht begegnet.\n\nUnser Anführer, Kommandosoldat Hann Ibal möchte Euch irgendwo da drin treffen. Er wird Euch reich für Eure Bemühungen belohnen.\n\nWahrscheinlich.", progress = nil, completion = "Ich hätte Euch liebend gern als vollwertigen G-Team Kommandosoldaten, aber Ihr verfolgt andere Abenteuer.\n\nIch bin sicher, wir werden uns wiedersehen und ich hoffe, Ihr habt Euch bis dahin überlegt, uns beizutreten. Hier ist etwas für Eure Unannehmlichkeiten.", rewards = "Hann Ibals SchulterklappenMör'doks GamaschenTempels WesteGürtel des G-TeamsBäräkuss' SchienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26943] = {title = "Trautes Heim, Gnom allein", objective = "Sprecht mit Mör'dok.", description = "Ich hatte in Eisenschmiede mal ein ganz nettes Zuhause. Bis man mich rausgeworfen hat, um Platz für die Gnome zu machen.\n\nDie könnten nicht mal eine Gruppe Troggs aufhalten mit ihren ganzen Dingsdas und Maschinen! Und ich soll für ihre Schwäche bezahlen?\n\nNein, Sir! Nicht mehr.\n\nGeht nach Gnomeregan und redet mit Kommandosoldat Mör'dok. Klar, er ist ein Gnom, aber seine Leute... S.I.C.H.E.R. Ich glaube, so heißen sie... die werden Gnomeregan zurückerobern.\n\nLos! Ich will mein Haus zurück!", progress = nil, completion = "Ich hätte nie gedacht, dass ich einen &lt;Volk&gt; wie Euch hier unten sehen würde. Gibt es einen bestimmten Grund dafür, dass Ihr Leib und Leben riskiert?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26944] = {title = "Gnomeregan erforschen", objective = "Sprecht mit Mör'dok.", description = "Die Hauptstadt der Gnome, Gnomeregan, ist seit einiger Zeit nicht mehr unter ihrer Kontrolle. Ich weiß, wie es ist, ein Zuhause zu verlieren.\n\nBitte begebt Euch nach Gnomeregan und sprecht mit Kommandosoldat Mör'dok, einem Mitglied von S.I.C.H.E.R. Wenn Ihr ihnen irgendwie helfen könnt, ihre Heimat zurückzuerobern, dann fordere ich Euch auf, es zu tun. Jene Hallen bergen dunkle Geheimnisse.", progress = nil, completion = "Ich hätte nie gedacht, dass ich einen &lt;Volk&gt; wie Euch hier unten sehen würde. Gibt es einen bestimmten Grund dafür, dass Ihr Leib und Leben riskiert?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26945] = {title = "Neue Techniken lernen", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht in der Nähe nach einer Trainingsattrappe und übt daran die Anwendung von 'Sturmangriff'.", description = "Wenn Ihr die Herausforderungen in Eurem Weg meistert, werdet Ihr beginnen, neuen Techniken zu erlernen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Demonstriert sie mir dann an einer der Trainingsattrappen.", progress = nil, completion = "Ihr habt Euch als fähiger Schüler erwiesen. Wenn es an der Zeit ist, Eure Ausbildung fortzusetzen, kehrt zu mir zurück und ich werde Euch neue Techniken lehren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26946] = {title = "Der Vorteil eines Schurken", objective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Sucht im Südosten von Aldrassil nach einer Trainingsattrappe und übt daran dreimal die Anwendung von 'Ausweiden'.", description = "Ich bin sicher, dass Ihr inzwischen den Finsteren Stoß meisterlich gegen Eure Feinde anwendet. Dennoch, wenn Ihr mehr lernt und als Schurke voranschreitet, werdet Ihr Euch neue Techniken aneignen. Eine, die Ihr schon bald erlernen werdet, nennt sich 'Ausweiden' und ist ein mächtiger Abschluss für eine Kombination von Angriffen.\n\nIch möchte, dass Ihr Erfahrung sammelt, die Fähigkeit erlernt und sie dann ausprobiert. Sucht nach einer Trainingsattrappe am südöstlichen Ende Aldrassils.", progress = nil, completion = "Ihr habt schnell gelernt. Wenn Ihr so scharfsinnig seid, wie Ihr wirkt, dann könntet Ihr einer meiner besten Schüler werden. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26947] = {title = "Ausbildung eines Waldhirten", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Sucht im Südosten von Aldrassil nach einer Trainingsattrappe und übt daran fünfmal die Anwendung von 'Zuverlässiger Schuss'.", description = "Die meisten Menschen, die an die Kaldorei denken, haben Visionen von Druiden und Schildwachen, aber der Weg des Jägers ist ebenso alt und genauso ehrenvoll.\n\nIch habe Euch beobachtet und Ihr habt einige Erfahrungen mit Eurem Bogen gesammelt. Durch Erfahrung werdet Ihr beginnen, einige neue Fähigkeiten zu erlernen.\n\nGeht, sammelt mehr Erfahrung und findet heraus, wie man etwas Neues erlernt. Sucht dann nach einer Trainingsattrappe am südöstlichen Ende Aldrassils und probiert es aus.", progress = nil, completion = "Ihr lernt unsere Gepflogenheiten schnell. Ich freue mich darauf, Eure Ausbildung fortzusetzen. Kehrt zu mir zurück, wenn die Zeit reif ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26948] = {title = "Mondfeuer", objective = "Erreicht Stufe 3, um 'Mondfeuer'. Wendet 'Mondfeuer' bei einer Trainingsattrappe in Aldrassil an.", description = "Druiden spielen in unserer Gesellschaft eine wichtige Rolle. Doch allzu oft werden wir als passive Träumer angesehen, in einer Welt, die sich um uns herum verändert.\n\nDie Wahrheit ist allerdings, dass wir aktiv üben und in die Welt hinausgehen müssen, um unsere Verbindung mit der Natur zu entwickeln.\n\nAlso, geht, sammelt Erfahrungen. Ihr werdet spüren, wie sich die Verbindung vertieft, wenn Ihr neue Fähigkeiten erlernt. Demonstriert mir die erste, die Ihr erlernt.", progress = nil, completion = "Ihr habt die Grundlagen des Heilens schnell gelernt, &lt;Name&gt;. Ich habe keine Zweifel, dass Eure Heilfähigkeiten oft nützlich sein werden. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26949] = {title = "Das richtige Wort", objective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Wendet es dann 5-mal an Trainingsattrappen an.", description = "Wenn Ihr Euch in die Welt da draußen wagt und Eure Fähigkeiten entwickelt, werdet Ihr neue Fertigkeiten erlernen, von denen Ihr nicht wusstet, dass sie in Euch stecken.\n\nIch möchte, dass Ihr loszieht, weitere Erfahrungen sammelt und mir dann die erste neue Fähigkeit zeigt, die Ihr gelernt habt.", progress = nil, completion = "Ihr werdet nie Mangel an Verbündeten haben, die Heilung benötigen. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26950] = {title = "Die dunkle Seite des Lichts", objective = "Tötet Befrager Vishas und Blutmagier Thalnos.", description = "Der Scharlachrote Kreuzzug lockt junge Krieger mit dem Versprechen an, die Untoten auszulöschen. Was sie nicht sehen, ist die Schattenseite der ganzen Operation.\n\nBefrager Vishas ist der grausamste Mann, den ich je das Missvergnügen hatte zu treffen - er hat aus meiner Mutter Informationen \"herausgeholt\", als die Seuche zum ersten Mal ausbrach. Der gnadenlose Blutmagier Thalnos bewacht den Friedhof.\n\nDer heilige Zorn der Kreuzfahrer macht sie blind gegenüber ihrer eigenen Dunkelheit. Sorgt dafür, dass sie ihre Scheinheiligkeit bereuen.", progress = nil, completion = "Was meint Ihr damit, das Thalnos ein Untoter war? Das ist unmöglich. Dies ist ein heiliger Ort, der Scharlachrote Kreuzzug würde niemals zulassen...\n\nNehmt dies als Belohnung und ruht Euch aus. Die Gruften müssen sehr an Euren Nerven gezerrt haben.", rewards = "Vishas KapuzeFestschnürender GürtelHandschuhe des \"Reinen\"Helm des scharlachroten ZelotenHandfesseln des BefragersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26951] = {title = "Aufräumen auf der E. Insel", objective = "Sammelt 8 entzauberte Tikimasken.", description = "Der Kampf, um die Echoinseln zurückzuerobern, ist uns teuer zu stehen gekommen. Aber er war es wert, <Klasse>. Der große Geist, Bwonsamdi, hat unseren Kriegern geholfen, den widerlichen Zalazane zu besiegen. Er hat unsere Krieger mit den Geistern der Insel beschützt. Aber einige dieser Geister sind im Kampf gefallen. Helft dabei, diesen Geistern die ewige Ruhe zu verschaffen. Ihr werdet auf den Echoinseln herumliegende Masken finden. Sammelt sie auf und bringt sie hierher.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Verhüllter HandschutzLeichtgewichtige StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26952] = {title = "Die Stätte der Heiler", objective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", description = "Es gefällt mir nicht, was die Verlassenen hier am Bollwerk anrichten. Bomben, Kessel, sinnloses Blutvergießen... Nichts davon verkörpert das, wofür der Argentumkreuzzug steht. Außerdem gefällt mir die Tatsache nicht, dass sie Söldner wie Euch anheuern.\n\nNichts gegen Euch persönlich, <Klasse>. Nur könntet Ihr so viel mehr aus Euch machen. Wenn Ihr Euch eher für die Heilung der Pestländer interessiert als dafür, sie erneut zu verseuchen, dann meldet Euch in der Stätte der Heiler bei Außenagent Kaartish. Die Stätte liegt gen Osten.", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26953] = {title = "Zen'Kiki, der Druide", objective = "Tötet mit Zen'Kiki an Eurer Seite 20 verseuchte Wildtiere. Ihr könnt schwerfällige Seuchenbären, kranke Wölfe, Giftnebellauerer oder Seuchenlauerer töten.\n\nKehrt zur Stätte der Heiler zurück, wenn Ihr von Zen'Kiki getrennt werdet.", description = "Ich bin Adrine Wergfell, ein Druide des Zirkels des Cenarius. Ihr könnt Euch bei uns für die Heilung dieses Landes, wo einst nur Tod zu finden war, bedanken.\n\nWir nehmen alle auf, die dem Weg des Druiden folgen möchten ungeachtet ihres Volkes, ihrer Fraktion oder ihrem Talent. Hin und wieder bedeutet das die Aufnahme eines Druiden, der mehr Hilfe benötigt als andere.\n\nIch möchte Euch Zen'Kiki vorstellen. Er ist noch recht neu und lernt immer noch sein Handwerk. Würde es Euch etwas ausmachen, wenn Ihr ihn eine Weile mit hinaus nehmt? Ihr könnt an den verseuchten Tieren, die in der Nähe herumstreunen, kämpfen üben.", progress = nil, completion = "Anscheinend hat Zen'Kiki immer noch Schwierigkeiten mit der Gestaltwandlung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26954] = {title = "Ein anderer Ansatz", objective = "Bringt Zen'Kiki auf den Hügel östlich der Stätte der Heiler und lasst ihn 7 kranke Falken herbeirufen und töten.", description = "Zen'Kiki muss unter anderem an der Genauigkeit seiner Zauber arbeiten. Ich konnte sogar von hier aus sehen, wie sein Zorn Zauber vollkommen außer Kontrolle geriet. Ich konnte ihn sogar als Markierung nutzen, um Euren Fortschritt in den Wäldern zu verfolgen.\n\nVielleicht können wir Zen'Kiki anderweitig einsetzen. Nehmt ihn mit hinauf auf den Hügel im Osten. Die kranken Falken, die über diesem Hügel kreisen, müssen vernichtet werden. Bittet Zen'Kiki, auf diese Falken zu schießen. Selbst, wenn er sie nicht trifft, wird er sie ablenken, damit Ihr sie erledigen könnt.", progress = nil, completion = "Das wird ja langsam was. Wie viele Vögel hat Zen'Kiki getötet?\n\nKeine? Ihr habt sie alle selbst getötet?\n\nAlso gut, ich denke, wir werden für ihn eine andere Verwendung finden müssen. Wir werden Euch informieren, wenn es so weit ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26955] = {title = "Zen'Kiki und die Kultisten", objective = "Bringt Zen'Kiki in den Westlichen Pestländern zu Malicias Außenposten, holt 4 gefangene Seuchenbären aus ihren Käfigen und lasst Zen'Kiki sie heilen.", description = "Während Eurer Abwesenheit habe ich versucht, für unseren Freund eine neue Verwendung zu finden. Ich glaube, er könnte eine Zukunft als Heiler haben. Das liegt hauptsächlich daran, dass man mit Heilungszaubern nicht danebenschießen kann.\n\nWie Außenagent Kaartish mir mitteilt, kommen die verseuchten Tiere aus dem Lager der Kultisten im Osten. Ich hoffe, es macht Euch nichts aus, Zen'Kiki dorthin zu begleiten... Vielleicht kann er in dem Lager dort einige der verseuchten Tiere heilen.", progress = nil, completion = "Bei der Gnade der Erdenmutter - er hat es geschafft! Danke, &lt;Name&gt;.\n\nIch gebe zu, dass ich die Hoffnung, was Zen'Kiki angeht, schon fast aufgegeben hatte. Es ist nur Eurer Geduld und Eurem Pflichtbewusstsein zu verdanken, dass er jetzt zu sich als Druide gefunden hat und ein Mitglied des Zirkels des Cenarius ist. Ganz zu schweigen von dem Guten, das Ihr für die Natur getan habt.\n\nEuch gebührt meine Bewunderung und mein Respekt.", rewards = "Gamaschen des gerissenen WandlersBrustplatte des GeduldigenAuf Euch wartet eine dieser Belohnungen:\n\nZen'Kikis Dank\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26956] = {title = "Die Guten ins Töpfchen...", objective = "Entfernt 6 verdorbene Maispflanzen, 4 verfaulte Äpfel und 3 ungesund aussehende Kürbisse von Dalsons Hof in den Westlichen Pestländern.", description = "<Volk>! Endlich ist jemand da, der mir helfen kann.\n\nWir Druiden des Cenarius haben Dalsons Hof, der direkt hinter mir liegt, neu bewirtschaftet. Das Land blüht geradezu auf und unsere Ernten waren erfolgreich... zum großen Teil.\n\nEinige Pflanzen scheinen aber noch immer mit der Seuche infiziert zu sein, die dieses Land überzogen hat. Vielleicht waren sie zu tief verwurzelt oder ihre Samen zu schwach. Ich weiß es nicht. Ich weiß nur, dass <ein fähiger/eine fähige:c> <Klasse> wie Ihr vonnöten ist, um die schlechten Pflanzen von den guten zu trennen.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Name&gt;. Ich weiß, dass Gemüse pflücken nicht gerade die heldenhafteste Tat ist, die man sich vorstellen kann, aber auch bescheidene Aufgaben haben ihren Lohn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26957] = {title = "Der lange Heimweg", objective = "Trefft Euch erneut mit Del Gahrron in den Westlichen Pestländern in der Stätte der Heiler.", description = "Ich bin in meinem Leben schon an vielen Orten gewesen, <Klasse>. Ich habe den Kampf um Ahn'Qiraj mitgemacht, bin durch das Dunkle Portal in die Scherbenwelt getreten und habe mich den Argentumkreuzfahrern angeschlossen, um die Geißel im kalten Nordend niederzuschlagen.\n\nDoch vor all dem war ich ein Bauer hier in Lordaeron. Jetzt bin ich hier in Herdweiler, nur wenige Meilen von zu Hause weg. Es wird Zeit, dass ich meinen Respekt erweise.\n\nIch bin unterwegs zur Stätte der Heiler bevor ich nach Hause zurückkehre. Ich würde mich freuen, wenn wir uns nach meiner Ankunft dort wiedertreffen.", progress = nil, completion = "Anscheinend bin ich vor Euch eingetroffen, &lt;Name&gt;.\n\nAußenagent Kaartish hat mir Einzelheiten über meine alte Heimat berichtet. Wie es scheint, sind meine Kämpfe mit der Geißel noch nicht ganz vorüber.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26958] = {title = "Die erste Lektion", objective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Sturmangriff'.", description = "Lasst uns sofort mit Eurer Ausbildung beginnen. Wenn Ihr im Kampf erfahrener seid, werdet Ihr beginnen, neue Techniken zu entwickeln.\n\nGeht, sammelt Erfahrungen, erlernt neue Fähigkeiten und demonstriert sie an den Trainingsattrappen im Nordwesten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26959] = {title = "Beraubt sie ihrer Verteidigung", objective = "Tötet Hundemeister Loksey und Arkanist Doan.", description = "Wir müssen die Verteidigung des Scharlachroten Klosters ausschalten, bevor eine richtige Invastion stattfinden kann. Stoßt bis in ihre Bibliothek vor und bringt Hundemeister Loksey und Arkanist Doan um. Sie halten die mächtige Verteidigung ihrer Kameraden aufrecht.\n\nMeine Magie wird sicherstellen, dass der Rest des Klosters Euch nicht bemerken wird. Sobald sie tot sind, kann ich weitere Verstärkung herbeirufen, die uns bei unserem Angriff unterstützen wird.\n\nWir müssen erfolgreich sein, <Name>. Die Dunkle Fürstin wird ein Versagen nicht im Mindesten tolerieren.", progress = "Habt Ihr Euch um Loksey und Doan gekümmert? Mich zu enttäuschen heißt, die Dunkle Fürstin zu enttäuschen, <Volk>.", completion = "Ich wusste, ich kann auf Euch zählen! Diese Narren werden niemals wissen, wie ihnen geschah.", rewards = "HundeführergürtelSchild der KameradenAuf Euch wartet eine dieser Belohnungen:\n\nBand des Arkanisten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26960] = {title = "Mein Sohn, der Prinz", objective = "Stellt Euch in Burg Sturmwind Prinz Anduin vor. Sprecht mit König Wrynn, wenn Ihr Euch bekannt gemacht habt.", description = "Mein Sohn musste in seinem kurzen Leben bisher schon viele Bürden schultern und ich fürchte, er wird noch mehr Verantwortung übernehmen müssen.\n\nEr wird nie lernen, ein Anführer zu sein, wenn er sich nur in der Burg aufhält, doch ich hasse es, ihn ohne Begleitung hinauszuschicken.\n\n<Name>, Eure Taten in der Zeit nach dem Kataklysmus sind bereits legendär. Ihr wärt bestimmt <ein ausgezeichneter Mentor/eine ausgezeichnete Mentorin> für den jungen Prinz Anduin.\n\nBitte, stellt Euch ihm vor. Es gibt dringende Geschäfte für die Stadt, die ihr beide für mich wahrnehmen könnt.", progress = "Wie versteht Ihr beide Euch? Anduin lernt schnell - zeigt ihm, wie er ein wahrer Meister wird, <Klasse>!\n\nSeid Ihr beide bereit?", completion = "Ausgezeichnet, Anduin wird viel lernen, wenn er Euch beobachtet.\n\nDenkt daran, verlasst nicht die Stadt. Haltet ihn von Ärger fern. Und das Wichtigste: Bewacht ihn mit Eurem Leben!\n\n&lt;König Wrynn wendet seine Aufmerksamkeit seinem Sohn zu.&gt;\n\nAnduin - keine Abenteuer! Bleib in der Nähe von &lt;Name&gt; und komm zur Burg zurück, wenn es Schwierigkeiten gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26961] = {title = "Götzen sammeln", objective = "Bringt Magmar Todesstreich an der Eisenband Ausgrabungsstätte 8 verzierte Steingötzen.", description = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, fanden wir eine große Anzahl merkwürdiger, verzierter Götzen Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt! Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen! Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", progress = "Habt Ihr die Götzen? Wir müssen sie studieren und Eisenschmiede von unseren Ergebnissen berichten!", completion = "Ihr habt sie! Gut gemacht, &lt;Name&gt;!\n\nUnd Ihr seht nicht einmal besonders angeschlagen aus, trotz all der wild gewordenen Troggs. Ich werde Euch im Auge behalten... Ihr seid viel versprechend.", rewards = "Gemeißelter SteinstreitkolbenTroggtreterBrustplatte von ThelsamarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26962] = {title = "Beraubt sie ihres Angriffs", objective = "Tötet Herod.", description = "Wie Ihr seht, <Name>, ist unser erster Angriff auf die Waffenkammer nicht wie geplant verlaufen. Wir hatten bereits den nahegelegenen Hof eingenommen, da tauchte der Scharlachrote Champion Herod auf.\n\nWir müssen unseren Angriff fortsetzen. Der Scharlachrote Kreuzzug darf hier niemals wieder Krieger ausbilden, geschweige denn, einen Angriff auf Unterstadt starten.\n\nEure Aufgabe ist wohl klar. Nieder mit dem Scharlachroten Held.", progress = nil, completion = "Herod ist tot! Die Waffenkammer wird fallen!", rewards = "MönchsgamaschenSchiftung des UnausgebildetenBrustplatte des Scharlachroten KlostersVelonaras UmhangAuf Euch wartet eine dieser Belohnungen:\n\nHerods Medaillon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26963] = {title = "Verfeinerung Eurer Schüsse", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt fünfmal 'Zuverlässiger Schuss'.", description = "Lasst uns sofort mit Eurer Ausbildung beginnen. Es wird nicht leicht sein, hier zu überleben, und Ihr werdet eine wichtige Rolle für die Versorgung und Sicherheit unserer Leute spielen.\n\nWenn Ihr mehr Erfahrungen sammelt, werdet Ihr neue Fähigkeiten erlernen. Geht, erlernt neue Dinge und probiert sie aus. Kehrt zu mir zurück, wenn Ihr glaubt, dass Ihr sie beherrscht.", progress = nil, completion = "Ihr solltet diese Technik immer anwendungsbereit haben, &lt;Name&gt;. Ich finde sie stets äußerst nützlich. Kehrt zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26964] = {title = "Auf Befehl des Kriegshäuptlings: Der Silberwald!", objective = "Meldet Euch bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald zu melden.\n\nMehr denn je wird Eure Hilfe benötigt, um die Heimsuchung durch unsere Feinde in dieser Region zu beenden und den Hafen von Gilneas zu erobern!\n\nIhr müsst nach Süden durch Tirisfal reisen und Euch in den Silberwald begeben, um die Kommandozentrale der Verlassenen zu erreichen. Folgt der Straße im Silberwald nach Süden, bis Ihr die Kommandozentrale der Verlassenen erreicht.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", progress = nil, completion = "Sehr gut! Ein neuer Rekrut ist eingetroffen. Es gibt viel zu tun... in der Tat sehr viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26965] = {title = "Der Kriegshäuptling kommt", objective = "Wartet auf die Ankunft von Kriegshäuptling Garrosh Höllschrei.", description = "Ihr kommt gerade rechtzeitig, <Name>nub. Ihr heißt doch <Name>nub, stimmt's?\n\n<Großexekutor Mortuus betrachtet ein Blatt Papier.>\n\nJa, das steht hier in den Papieren: \"<Name>nub\".\n\n<Großexekutor Mortuus zeigt auf dem Blatt Papier auf Euren Namen.>\n\nWo war ich noch gleich? Ach ja, Ihr kommt gerade rechtzeitig! Der Kriegshäuptling müsste jeden Moment hier eintreffen, um sich mit unserer Anführerin und Retterin höchstpersönlich zu treffen - der Dunklen Fürstin. Wartet einfach ab und benehmt Euch anständig. Ich bin davon überzeugt, dass wir alle Belobigungen bekommen, wenn diese Kundgebung vorbei ist!", progress = "Stillgestanden, Sylnarnub!", completion = "Also das war überraschend! Ich will ja nicht an unserem Kriegshäuptling zweifeln, aber...\n\nEgal! Wir haben noch genug Arbeit vor uns. Ich bin sicher, die Dunkle Fürstin und der Kriegshäuptling werden das alles hier in den Griff bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26966] = {title = "Die Macht des Lichts", objective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Wendet es an, sucht eine Trainingsattrappe auf der Nordwestseite der Absturzstelle und benutzt Richturteil.", description = "Als Paladin kennt Ihr das Licht, das uns alle berührt. Gleichzeitig habt Ihr die einzigartige Macht, das Licht im Kampf zur Unterstützung herbeizurufen.\n\nWenn Ihr mehr Erfahrungen sammelt, werdet Ihr dem Licht noch näher kommen und im Kampf neue Kräfte nutzen können.\n\nGeht, werdet erfahrener, bis Ihr eine neue Kraft erlernt habt und zeigt sie mir dann.", progress = nil, completion = "Ihr habt Euch als guter Schüler erwiesen, &lt;Name&gt;. Ich freue mich darauf, Euch wieder zu lehren, wenn die Zeit gekommen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26967] = {title = "Der Kampf um das Scharlachrote Kloster", objective = "Tötet den Scharlachroten Kommandanten Mograine und Hochinquisitorin Weißsträhne.", description = "Blicket auf die Macht der Verlassenen! Der unaufhaltsame Wille der Dunklen Fürstin durchfließt unsere Körper!\n\nDie meisten der verbliebenen Truppen des Kreuzzugs sind geflohen. Einige leisten allerdings immer noch Widerstand.\n\nIhr habt eine wichtige Rolle beim Erfolg dieser Kampagne gespielt. Sylvanas lässt Euch die Ehre zuteilwerden, ihre letzten noch verbleibenden Feinde zu töten, <Name>.\n\nLasst keine Gnade walten.", progress = nil, completion = "Ja! Das Scharlachrote Kloster gehört jetzt den Verlassenen! Niemand entkommt unserer Rache!\n\nIhr habt die Aufgabe mit der Präzision eines wahren Champions erledigt. Nehmt dies als Belohnung - mit freundlicher Genehmigung der Bansheekönigin.", rewards = "Griffe der VerlassenenAuf Euch wartet eine dieser Belohnungen:\n\nGeschenk der BansheeköniginBand des Zorns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26968] = {title = "Frostnova", objective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Frostnova' 2-mal.", description = "Man erwartet von Euch als zukünftigem Magier, dass Ihr eine Vielzahl von Zaubern beherrscht. Um das zu können, müsst Ihr Eure Verbindung zum Arkanen vertiefen, indem Ihr mächtiger werdet.\n\nGeht, sammelt mehr Erfahrungen als Magier und zeigt mir, was Ihr erlernt habt.", progress = nil, completion = "Ihr habt schnell gelernt, diesen neuen Zauber zu beherrschen, &lt;Name&gt;. Ich wünschte, alle meine Schüler wären so talentiert. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26969] = {title = "Urtümlicher Schlag", objective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", description = "Eure Reise mit der Elementarenergie wird Euch an viele Orte führen. Wenn Ihr mehr Macht erlangt, werdet Ihr beginnen, neue Fähigkeiten zu erlernen.\n\n.Lasst uns Eure Reise mit einer einfachen, aber nützlichen Lektion beginnen.\n\nErlernt das Geheimnis des 'Urtümlichen Schlags' und probiert Eure neue Fähigkeit an den Trainingsattrappen aus, die sich nordwestlich der Absturzstelle befinden. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Es ist ein Vergnügen, einen so fähigen Schüler zu haben. Solange Ihr die Traditionen getreu fortführt, werden die Künste des Schamanismus unserem Volk nie mehr verloren gehen. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26970] = {title = "Das richtige Wort", objective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen und benutzt es dann fünfmal an den Trainingsattrappen an der Absturzstelle.", description = "Eine Eurer wichtigsten Pflichten als Priester ist die Anwendung der Macht des Lichts, um Verwundeten zu helfen.\n\nEine weitere ist, Eure Macht offensiv einzusetzen, um sie zu beschützen.\n\nWenn Ihr mehr Erfahrungen sammelt, werdet Ihr dem Licht noch näher kommen und im Kampf neue Kräfte nutzen können.\n\nGeht, werdet erfahrener, bis Ihr eine neue Kraft erlernt habt und zeigt sie mir dann.", progress = nil, completion = "Eure Fähigkeiten als Heiler werden sehr gefragt sein, &lt;Name&gt;. Zögert nicht, zu mir zurückzukehren, wenn Ihr weitere Ausbildung benötigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26971] = {title = "Die Bindung", objective = "Tötet Hohepriesterin Lorthuna.", description = "Ein Geräusch in der Hauptkammer des Tempels erregt Eure Aufmerksamkeit. Ihr hört ein wohlbekanntes Lachen... Lorthuna. Sie ist zurückgekommen, um das Ritual zu unterbrechen - Ihr müsst sie aufhalten!", progress = nil, completion = "Als all dies begann, sagte Maruut, dass er mit Vergnügen sein Leben gäbe, damit unsere Aufgabe erledigt würde. Er wäre stolz auf diesen Erfolg... auf diesen Tod.\n\nDer Riss ist auf dieser Seite jetzt geschlossen. Tiefenheim sollte sich jetzt ein wenig stabilisieren. Es wird Zeit brauchen, bis Thrall die Wunde in Azeroth geheilt hat, und wir werden wahrscheinlich hierbleiben müssen, bis er es geschafft hat.\n\nDanke für alles, was Ihr getan habt. Ohne Euch hätten wir das wahrscheinlich nicht so schnell erreicht.", rewards = "RissreißerkriegsaxtSpitze der VerachtungStangenwaffe der schwarzen SeeleDimensionsstachelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26972] = {title = "Die dunkle Seite des Lichts", objective = "Tötet Befrager Vishas und Blutmagier Thalnos.", description = "Ich habe mich dem Scharlachroten Kreuzzug als junger Paladin voller Eifer angeschlossen, um das Böse aus der Welt zu tilgen. Wie wenig wusste ich doch über die dunkle Wahrheit dieser Fanatiker.\n\nBefrager Vishas und Blutmagier Thalnos überwachen diesen Friedhof. Es bereitet ihnen großes Vergnügen, neue Rekruten endlos zu quälen, um sicherzustellen, dass sie 'rein' sind. Das ist eine Beleidigung des Lichts, <Klasse>!\n\nIch kann nicht länger Teil dieser verdorbenen Organisation sein. Ihr müsst sie beide töten, damit andere nie wieder die Qualen erdulden müssen, die ich ertragen musste.", progress = nil, completion = "Was meint Ihr damit, dass Thalnos ein Untoter war? Das ist unmöglich. Die ganze Mission des Scharlachroten Kreuzzugs ist darauf ausgerichtet, Untote zu vernichten! Auf gar keinen Fall...\n\nIhr habt meine Gedanken durcheinandergebracht. Bitte nehmt diese Belohnung für Euren Erfolg und lasst mich ruhen.", rewards = "Vishas KapuzeFestschnürender GürtelHandschuhe des \"Reinen\"Helm des ErwachtenHandfesseln des BefragersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26973] = {title = "Der einzig wahre Weg", objective = "Tötet Hundemeister Loksey und Arkanist Doan.", description = "Ich glaube, dass die Wurzel der Verderbnis des Kreuzzugs hier zu finden ist. Arkanist Doan überwacht die Bibliothek und lehrt viele junge Rekruten, wie man mit den arkanen Künsten umgeht.\n\nDas Licht ist der einzig wahre Weg! Ihr müsst ihn töten, <Klasse>, und diese glorreiche Bewegung rehabilitieren!\n\n<Josef der Erweckte bewegt sich unruhig.>\n\nIhr werdet Euch auch Lokseys entledigen müssen. Seine Hunde scheinen etwas gegen unsere noble Absicht zu haben.", progress = nil, completion = "Gute Arbeit! Ich weiß einfach, dass das Licht wohlwollend auf uns und unsere Arbeit scheint. Unsere Sache ist gerecht!", rewards = "HundeführergürtelSchild der gerechten SacheAuf Euch wartet eine dieser Belohnungen:\n\nBand des Arkanisten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26974] = {title = "Der falsche Champion", objective = "Tötet Herod.", description = "Wir...wir...wir mussten sie töten! Sie waren hinter uns her!\n\nIhr glaubt mir doch, nicht wahr, <Name>?\n\nHerod ist nicht der wahre Champion des Scharlachroten Kreuzzugs. Ich bin es! Er hat das, was rechtmäßig mir gehört, an sich gerissen!\n\nIhr solltet ihn töten. Er ist...eine Bedrohung! Er bildet Soldaten aus, die jeden töten und nicht nur die Untoten.\n\nIch werde Euch fürstlich belohnen...", progress = nil, completion = "Also ist er wirklich tot? Das bedeutet... Ich, Josef, bin der neue Scharlachrote Champion!!!\n\nNehmt dies. Ich habe ohnehin keine Verwendung für derartige Besitztümer. Schließlich bin ich der Scharlachrote Champion.", rewards = "MönchsgamaschenTuch des WahnsinnigenBrustplatte des Scharlachroten KlostersUmhang des falschen ChampionsAuf Euch wartet eine dieser Belohnungen:\n\nHerods Medaillon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26975] = {title = "Die Flotte zusammenrufen", objective = "Begleitet Prinz Anduin zu den Docks in Sturmwind und sprecht mit Nachschuboffizier Graves. Wenn Ihr und der Prinz Euch aus den Augen verliert, findet Ihr ihn im Thronzimmer von Sturmwind.", description = "Ich rufe eine Kriegsflotte zusammen, um das Schattenhochland anzugreifen und den Lakaien von Todesschwinge ihr Ende zu bereiten.\n\nMeine Soldaten sind bereit, aber die Vorbereitungen der Flotte verzögern sich. Meine Männer an den Docks brauchen Inspiration und Motivation. Ein Besuch des Prinzen sollte sie aufmuntern und ihnen erneut die glorreiche Zukunft vor Augen führen, für die sie kämpfen.\n\nGeht mit Prinz Anduin zu den Docks und sprecht mit Nachschuboffizier Graves. Ich möchte, dass Anduin sieht, wie ein geborener Anführer mit der Situation umgeht.", progress = nil, completion = "&lt;Graves verbeugt sich respektvoll vor dem Prinz.&gt;\n\nBitte versteht, Eure Hoheit, die Leute arbeiten in Doppelschichten. Das, was Euer Vater vorhat, ist von ungeheurem Ausmaß.\n\nAber wir sind bestrebt, alles fertig zu bekommen. Ich gebe Euch mein Wort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26976] = {title = "Der Kampf um das Scharlachrote Kloster", objective = "Tötet den Scharlachroten Kommandant Mograine und Hochinquisitorin Weißsträhne.", description = "Oh, schön, Euch wiederzusehen, <Name>! Ich fürchte, ich brauche Eure Hilfe.\n\nWisst Ihr, Mograine ist hier der Befehlshabende zusammen mit Hochinquisitorin Weißsträhne. Sie haben versucht, mir einzureden, dass ich eigentlich nicht der neue Scharlachrote Champion bin. Die Jungs und ich finden das gar nicht gut.\n\nWir werden jetzt das Scharlachrote Kloster selbst übernehmen und die Ordnung so wieder herstellen, wie sie immer hätte sein sollen - mit mir an der Spitze! Ich werde mich der Verlassenen und der Geißel endgültig entledigen.\n\nHelft Ihr einem alten Freund?", progress = nil, completion = "Ja! Das Scharlachrote Kloster gehört uns! Ihr seid ein wahrer Freund. Nehmt dies zur Belohnung und kommt mich jederzeit besuchen, nachdem ich Unterstadt ebenfalls übernommen habe.\n\nDas wird ein scharlachrotes Paradies!", rewards = "Griffe des WahnsinnigenAuf Euch wartet eine dieser Belohnungen:\n\nScharlachrote Halskette des ParadiesesBand des grandiosen Größenwahnsinns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26977] = {title = "Untersuchung im Zwielicht", objective = "Sprecht in Burg Sturmwind mit Major Samuelson.", description = "Die Verräterischen Taten des Schattenhammers in den letzten Monaten haben die Stadt in Aufruhr versetzt. Sie haben es auf die Ängste der Bauern abgesehen und korrumpieren unsere wichtigsten Bürger. Wir müssen herausfinden, wie tief diese Verschwörung bereits sitzt.\n\nIch habe Major Samuelson von der Stadtwache von Sturmwind beauftragt, eine Untersuchung zu leiten. Er ist hier im Thronraum. Seht, ob Ihr ihn bei seinen Bemühungen unterstützen könnt.", progress = nil, completion = "Hmmm, ja? Meine Untersuchung des Schattenhammers. Natürlich.\n\nEure Mitarbeit wird von unschätzbarem Wert sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26978] = {title = "Wer braucht Kessel?", objective = "Stellt Zitters Seuchenfässer in der Nähe der Windmühle, bei den Getreidesilos, am Farmhaus und bei der Scheune am Teufelssteinfeld auf.", description = "Habt Ihr den Zustand vom Teufelssteinfeld gesehen? Die Streitkräfte der Allianz aus Andorhal haben das Gebiet übernommen und benutzen es, um...um...FELDFRÜCHTE anzubauen!\n\nDa gefiel es mir fast schon besser, als die Geißel das Gebiet noch besetzt hielt. Wenigstens hatten sie so viel Verstand, einen riesigen Seuchenkessel mitten aufs Feld zu stellen.\n\nWir werden uns den Hof von diesen Menschen zurückholen, <Name>. Nehmt diese Fässer und stellt sie an Schlüsselpositionen um das Feld herum auf. Ich werde hier am Bollwerk warten.", progress = nil, completion = "&lt;Zitters glüht geradezu vor Aufregung.&gt;\n\nDie Fässer sind aufgestellt? Auf ihren Positionen?\n\nNun gut, ich werde dem Hochexekutor Bericht erstatten. Wenn es so weit ist, wird er derjenige sein, der den Auslöser drückt.", rewards = "ZaudergürtelSeuchenkesseldeckelUmhang der gesalzenen ErdeAuf Euch wartet eine dieser Belohnungen:\n\nGlimmernder Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][26979] = {title = "Merkwürdige neue Gesichter", objective = "Meldet Euch in den Westlichen Pestländern am Niedergebrannten Außenposten bei Lindsay Rabensonn.", description = "Jetzt, da Teufelsstein uns gehört, können wir seine Äcker - und alle Leichen, die wir finden - für unsere Zwecke nutzen. Ich habe von oben den Befehl erhalten, dass Ihr dabei helfen sollt.\n\nVielleicht habt Ihr Lindsay Rabensonn bereits auf dem Schlachtfeld bei Andorhal kennengelernt. Ich habe sie noch nie getroffen, aber sie scheint einige hohe Tiere als Freunde zu haben, denn sie übernimmt das Kommando hier in Teufelsstein. Ihr sollt sie bei dem niedergebrannten Scharlachroten Lager treffen, das ihr vor Kurzem ausspioniert habt.", progress = nil, completion = "&lt;Name&gt;. Die Dunkle Fürstin wacht über Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26980] = {title = "Schnellschalts Station", objective = "Sprecht an der Station Schnellschalt nördlich vom Hafen von Menethil mit Shilah Fliesmeißel.", description = "Ihr habt hier gute Arbeit geleistet, <Name>. Euch jetzt zu bitten, Sandsäcke zu schleppen, wäre die reine Verschwendung. Um ehrlich zu sein, schicke ich Euch lieber dahin, wo Eure Fähigkeiten gebraucht werden.\n\nWir haben im Marschengebiet weiter nördlich einen kleinen Außenposten. Schnellschalt ist der Gnom, der ihn gebaut hat, aber Ihr solltet mit Shilah Fliesmeißel sprechen und ihr bei Angelegenheiten für Eisenschmiede helfen.\n\nIch gebe zu, sie sieht echt gut aus... aber ich würde nicht den Fehler machen, mir bei ihr irgendwelche Freiheiten herauszunehmen! Die Familie heißt nicht umsonst Fliesmeißel.", progress = nil, completion = "Starkfaust hat Euch geschickt, ja? Er ist ein guter Hauptmann, führt seine Leute gut. Ich wünschte nur, er würde aufhören, mir auf die Taille zu starren.\n\nUnd Euch will ich auch nicht dabei erwischen. Wir haben hier zu arbeiten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26981] = {title = "Whelgars Zuflucht", objective = "Sprecht bei Whelgars Zuflucht südlich der Station Schnellschalt mit Ausgrabungsleiter Whelgar.", description = "Ausgrabungsleiter Whelgar hat südlich von hier in diesen Bergen seit geraumer Zeit die Ausgrabungen geleitet. Früher einmal hatte er Probleme mit Raptoren, aber in letzter Zeit hatte sich die Lage gebessert.\n\nVor ein paar Tagen haben wir nun erfahren, dass er die ganze Ausgrabungsstätte evakuieren musste. Ich weiß nicht, was dort vor sich geht, aber ich kann mir nicht vorstellen, dass der Kataklysmus einen Steinbruch sicherer gemacht hat als vorher.\n\nDort arbeiten gute Zwerge, <Name>. Würdet Ihr hingehen und nachsehen, was dort los ist und vielleicht auch helfen?", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Wir haben auf jeden Fall ein Raptorenproblem... oder so was in der Art.\n\nEs ist eher, dass die ganze Grabungsstätte auf uns losgegangen ist. Ich habe noch nie gesehen, dass Felsen und Fossilien sich so aufregen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26982] = {title = "Das Scharlachrote Kloster", objective = "Besucht Josef den Erweckten.", description = "Das Kloster in Tirisfal, das die Scharlachroten Kreuzfahrer jetzt besetzt halten, war früher einmal die Ausbildungsstätte für unsere Paladine. Jetzt lauern dort die Verlassenen aus Unterstadt und der Kreuzzug verhindert, dass wir es für die Ausbildung der Soldaten nutzen, die wir so dringend benötigen, um mit den Verlassenen fertigzuwerden.\n\nHört zu, ich traue ihm zwar nicht über den Weg, aber Josef der Erweckte wartet auf dem Friedhof. Geht und sprecht mit ihm - obwohl er ein Kreuzfahrer ist, sagt er, dass er sich gegen sie auflehnt und uns die Gelegenheit gibt, das zurückzuholen, was uns gehört.", progress = nil, completion = "Hauptmann Nials hat Euch geschickt? Ich habe sie schon ewig lange nicht mehr gesehen! Wie geht es ihr? Hat sie meinen Brief erhalten?\n\nOh, Ihr seid nicht deswegen hier. Na, dann lasst uns zum Geschäft kommen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26983] = {title = "Gerade nah genug", objective = "Besucht Josef den Erweckten.", description = "Täuscht Euch nicht - es gibt hier noch viel zu tun! Dennoch müssen wir auch dort gegen die Verlassenen zurückschlagen, wo wir sie empfindlich treffen können. Das Scharlachrote Kloster in Tirisfal liegt in perfekter Entfernung zu Unterstadt und Brill.\n\nMeldet Euch bei Josef dem Erweckten in der Bibliothek. Er ist ein aufständischer Kreuzfahrer, der uns vielleicht dabei helfen kann, das Kloster als unsere Basis für alle Operationen in dem Gebiet zu übernehmen. Wenn Ihr schon dabei seid, könnt Ihr auch gleich Arkanist Doan eliminieren, einen ihrer mächtigsten Magier.", progress = nil, completion = "Ihr seid von Süderstade hiergekommen, nicht wahr? Ich wette, dass Rachehunger gegen die widerwärtigen Verlassenen den Ort in Schutt und Asche gelegt hat. Der Scharlachrote Kreuzzug kann helfen, sich darum zu kümmern!\n\nDas heißt, sobald Ihr mir geholfen habt, ihre fehlgeleiteten Seelen wieder auf den rechten Weg zu führen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26984] = {title = "Ein alter, verrückter Freund", objective = "Besucht Josef den Wahnsinnigen.", description = "Josef der Wahnsinnige war hier einer meiner guten Freunde, bevor er sich dem Scharlachroten Kreuzzug im Scharlachroten Kloster in Tirisfal anschloss. Ich hörte, dass er in der Waffenkammer dort ist und einen lächerlichen Versuch unternimmt, Herods Position als Scharlachroter Champion zu übernehmen.\n\nEs ist reiner Selbstmord, Herod so herauszufordern! Geht dort hinauf und versucht, ihm das auszureden.", progress = nil, completion = "Ihr seht zäh aus, &lt;Klasse&gt;. Es gilt hier, viel Unrecht wiedergutzumachen. Lasst uns anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26985] = {title = "Wahnsinn gegen Irrsinn ausspielen", objective = "Besucht Josef den Rasenden.", description = "Unsere frisch verstärkten Streitkräfte kommen mit der Situation hier für eine Weile ohne Euch zurecht. Ich habe Berichte erhalten, dass Josef der Irrsinnige, eine früherer Offizier des Scharlachroten Kreuzzugs, sich im Scharlachroten Kloster aufhält und mit seiner Gruppe Abtrünniger gegen den Scharlachroten Kommandanten Mograine losschlagen will.\n\nDas ist eine ausgezeichnete Gelegenheit. Geht dort hin und helft ihm bei seinem irrsinnigen Vorhaben. Vielleicht können wir dann das Kloster als Festung genau auf der Türschwelle von Sylvanas benutzen.", progress = nil, completion = "Moment, Ihr wurdet von DER Shandris Mondfeder hierhergeschickt? Ich traue meinen Ohren nicht! Zu wissen, dass meine Sache von ihrer riesigen Armee unterstützt wird...\n\nJa, ja, Ihr seid perfekt. Ihr seid der Schlüssel zu meiner Zukunft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26986] = {title = "In das Scharlachrote Kloster", objective = "Meldet Euch bei der dunklen Waldläuferin Velonara.", description = "Um sicherzustellen, dass unsere Männer sich so wenig Verletzungen wie möglich zuziehen, ist es oftmals am besten, unseren Feinden zuhause großen Schaden zuzufügen, um so zu verhindern, dass Schlachten überhaupt stattfinden!\n\nReist zum Scharlachroten Kloster und sprecht mit der dunklen Waldläuferin Velonara auf dem dortigen Friedhof. Sie führt einen Angriff der Verlassenen an und <ein erfahrener/eine erfahrene:c> <Klasse> wie Ihr könnte ihr eine große Hilfe sein.", progress = nil, completion = "Sieht so aus, als ob Darthalia wie von mir gewünscht einen fähigen &lt;Klasse&gt; geschickt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26987] = {title = "Der rechte Weg", objective = "Sprecht mit der dunklen Waldläuferin Velonara.", description = "Meine Leute sind generell nicht sehr von den arkanen Künsten, die von anderen Völkern missbraucht werden, angetan. Glücklicherweise sind wir weit von den Zauberen in der Bücherei des Scharlachroten Klosters entfernt, doch ihre Fähigkeit, sich über die materielle Welt hinwegzusetzen, bereitet mir Sorgen und stellt letztendlich eine Gefahr für das Überleben meines Stammes dar.\n\nReist weit nach Westen zur Bücherei des Klosters und sprecht dort mit der dunklen Waldläuferin Velonara. Ihre Streitkräfte stehen schon kurz davor Arkanist Doan, den führenden Magus des Kreuzzugs, höchstpersönlich anzugreifen.", progress = nil, completion = "Ich bin überrascht, dass Jäger Mark'hor zur Abwechslung einmal mit mir zusammenarbeitet. Er ist sonst ziemlich stur. Allerdings nährt er einen starken Hass gegen Magie.\n\nIch hoffe, Ihr tut das auch, &lt;Klasse&gt;, denn wir werden dem Scharlachroten Kreuzzug seine Magie wegnehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26988] = {title = "Die Sache in Schwung bringen", objective = "Besucht die dunkle Waldläuferin Velonara.", description = "Ich warte auf einige sehr mächtige Reagenzien, die ich vor Kurzem aus Unterstadt bestellt habe. Wie ich höre, verzögert sich die Lieferung, weil die Kreuzfahrer des Scharlachroten Klosters den Weg versperren. Der Scharlachrote Champion Herod ist wahrscheinlich für diese Unannehmlichkeit verantwortlich.\n\nBitte geht und sprecht mit der dunklen Waldläuferin Velonara in der Waffenkammer des Scharlachroten Klosters. Sie wird sich um Herod kümmern, was bedeutet, dass meine Lieferung sicher ankommt!", progress = nil, completion = "Yayo'jin hat Recht, wenn Ihr mir hier helft, wird ihr das im Hinterland ebenfalls helfen.\n\nNoch ein Grund, warum wir sofort loslegen sollten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26989] = {title = "Die Gilnearische Befreiungsfront", objective = "Tötet 10 Worgenrenegaten.", description = "Der Kampf um die Region tobt immer noch, <Name>nub. Obwohl wir die Verteidiger von Gilneas vernichtend geschlagen und Gilneas für die Horde eingenommen haben, ist es einer kleinen Gruppe Rebellen gelungen, zu entkommen. Die \"Gilnearische Befreiungsfront\" - wie sie sich selbst nennen - ergreift jede Gelegenheit, unsere Truppen draußen anzugreifen. Den Rebellen sind einige kleinere Siege gelungen und jetzt werden sie bei ihren Angriffen immer dreister! Es ist an der Zeit, zurückzuschlagen, <Name>nub.\n\nGeht nach Süden in die Wildnis von Silberwald und tötet jeden Rebellen, dem Ihr begegnet.", progress = nil, completion = "Taubstummnub ist zurückgekehrt! In einem Stück!\n\nVerteidiger von Silberwald! Erlöser der Horde! Taubstummnub, Eure Tapferkeit muss belohnt werden!", rewards = "Nubiger UmhangNubzauberstabNublische ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26991] = {title = "Feinde vor den Toren", objective = "Findet die dunkle Waldläuferin Velonara.", description = "Manchmal müssen wir die Notwendigkeit, unsere Verbündeten zu beschützen, anerkennen, damit sie uns beschützen können. Dies ist eine solche Gelegenheit, <Volk>.\n\nReist zum Scharlachroten Kloster in der Nähe von Unterstadt in Tirisfal. Sobald Ihr dort eintrefft, geht zur Kathedrale und sprecht mit der dunklen Waldläuferin Velonara. Sie führt den letzten Schlag gegen den Kreuzzug dort und es würde uns allen sehr zum Vorteil gereichen, wenn wir sicherstellen, dass unsere untoten Verbündeten das Kloster übernehmen, bevor die Kreuzfahrer eine Chance haben, ihre Hauptstadt anzugreifen.", progress = nil, completion = "Nazeer ist ein kräftiger Krieger - sein Hass auf unsere Feinde ist noch stärker als meiner. Ihr seid eingeladen, meinen Streitkräften zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26992] = {title = "Schmerz im Überfluss", objective = "Sammelt 8-mal Wildes Verdammniskraut.", description = "Zweifellos habt Ihr von dem Vorfall gehört, der sich am Zornestor in Nordend abgespielt hat, nicht wahr? Wegen dieser unglückseligen Vorkommnisse ist es uns strengstens verboten, den Erregerstamm der todbringenden Krankheit, den wir endlich perfektioniert hatten, zu verwenden. Jetzt gibt es Regeln und Vorschriften und anderen Unsinn!\n\nMan hat uns eine entschärfte Version der perfekten Krankheit gegeben und erwartet nun, dass wir daraus eine Waffe basteln.\n\nWenn ich diesen Mist zum Funktionieren bringen soll, dann brauche ich einige Taschen voll mit wildem Verdammniskraut. Ihr findet es überall im Silberwald.", progress = "Habt Ihr das wilde Verdammniskraut gesammelt, um das ich Euch gebeten hatte?", completion = "Schmerz im Überfluss, sage ich Euch! Das Land selbst droht, uns zu verschlingen und dennoch bestehen wir fort. Ich frage mich, warum das so ist? Mit diesem Verdammniskraut, den Eingeweiden und dem geronnenen Blut, das T'Veen benötigt, haben wir vielleicht etwas Geeignetes, das wir an die Frontlinie der Verlassenen senden können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26993] = {title = "Kompendium der Gefallenen", objective = "Findet das Kompendium der Gefallenen.", description = "Keine Angst, ich diene keinem Herrn, <Volk>. In diesen Hallen liegt ein Buch, genannt Kompendium der Gefallenen. Es enthält Unmengen von Forschungsergebnissen, die der Scharlachrote Kreuzzug im Laufe der Jahre über meinesgleichen zusammengetragen hat.\n\nEinfach gesagt möchte ich, dass Ihr es findet und zu mir zurück bringt, ohne Fragen zu stellen.", progress = "Ich möchte nicht noch länger in einem Kloster bleiben, das voller Zeloten ist, die Untote hassen. Das könnt Ihr sicherlich nachvollziehen. Sprecht mich nicht an, solange Ihr das Buch nicht bei Euch tragt.", completion = "Gut gemacht! Wie wäre es, wenn ich Euch eine hübsche Belohnung für Eure Arbeit gebe und Ihr erzählt niemanden, dass Ihr mich hier gesehen habt. Einverstanden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26994] = {title = "Ohne Sinn und Verstand", objective = "Tötet 3 scharlachrote Myrmidonen, 3 scharlachrote Beschützer, 3 scharlachrote Gardisten und 3 scharlachrote Rufer.", description = "Wie ich höre, möchte Joseph der Wahnsinnige, dass Ihr Herod tötet. Wenn Ihr schon dabei seid, warum bringt Ihr dann auch nicht gleich ihre besten Soldaten um? Ich werde Euch für Eure Arbeit gut bezahlen.\n\nZerbrecht Euch über das 'Warum' nicht den Kopf, nur über das 'Wie'.", progress = "Spielen wir keine Spielchen... Sind sie tot oder nicht?", completion = "Sehr gut! Ja, in der Tat, sehr gut.\n\nEure Belohnung, wie versprochen. Keine Fragen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26995] = {title = "Innereien und Blut", objective = "Findet 6 \"saubere\" Tierinnereien.", description = "Wenn wir diese neue Krankheit in die Gänge bringen wollen, brauchen wir saubere Tierinnereien. Das Problem ist, dass saubere Tierinnereien im Silberwald ausgesprochen selten sind. Die meisten Tiere sind von Krankheiten befallen und haben daher nur kranke Innereien.\n\nDurchsucht das Waldgebiet östlich von hier nach Worgs und ergrauten Bären. Tötet nur die, die nicht von Krankheiten befallen sind und reißt ihnen die Innereien heraus. Bringt mir so viele saubere Eingeweide, wie Ihr in Euren Rucksack stopfen könnt.", progress = "Denkt daran, ich kann nur saubere Tierinnereien für den neuen Erregerstamm der Krankheit, die wir entwickeln, gebrauchen.", completion = "Ausgezeichnet! Mit diesen Eingeweiden und dem wilden Verdammniskraut können wir den Erregerstamm unserer neuen Krankheit testen. Jetzt müssen wir nur noch ein geeignetes Ziel auswählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26996] = {title = "Genau vor ihren Nasen", objective = "Tötet Hochinquisitor Schönufer..", description = "In dem rechten Seitenraum der verfluchten Kathedrale ist an der Wand eine Fackel. Bewegt sie und eine Geheimtür wird sich öffnen. Dahinter befindet sich Hochinquisitor Schönufer. Er ist jetzt ein Untoter.\n\nJemand muss ihn erledigen. Wenn möglich, tötet ihn in seinem Zimmer. Ich ziehe es vor, wenn die Kreuzfahrer ihn nicht sehen. Ihr kennt das ja - tötet ihn und ich gebe Euch eine Belohnung. Wir müssen nichts weiter sagen.", progress = nil, completion = "&lt;Dominic gibt Euch Eure Belohnung. Kein Wort wird gewechselt.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26997] = {title = "Die üblichen Verdächtigen", objective = "Fühlt im Hafen von Sturmwind 6 Dockarbeitern von Sturmwind auf den Zahn.", description = "<Samuelson kratzt sich gedankenverloren das Kinn.>\n\nMeine Untersuchungen haben ergeben, ähm, es ist möglich, dass sich unter den Dockarbeitern von Sturmwind Ärger zusammenbraut. Durchtriebene Bande. Ich traue denen nicht!\n\nIhr solltet dahin gehen und alles mal ordentlich auf den Kopf stellen. Fühlt diesen Hafenarbeitern auf den Zahn. Das sollte Euch eine Weile beschäftigen.\n\nGeht und eliminiert diese Ungläubigen des Schattenhammers!", progress = "Samuelson schien nicht viel von Euch zu halten. Glaubt Ihr wirklich, dass die Dockarbeiter etwas mit dem Schattenhammer zu tun haben?", completion = "Das ergibt doch keinen Sinn, &lt;Name&gt;.\n\nWarum hat Samuelson uns hier hinaus auf eine sinnlose Verfolgungsjagd geschickt?\n\nDa stimmt doch etwas nicht. Wir sollten auf eigene Faust Nachforschungen anstellen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][26998] = {title = "Den Erfolg fortsetzen", objective = "Tötet 50 Murlocs der Finsterflossen.", description = "Das Gebräu ist endlich fertig, aber bevor ich diesem Erregerstamm mein Gütesiegel verleihe, müssen wir einen Feldversuch unternehmen.\n\nSprecht hier in der Kommandozentrale mit Fledermausführer Madenhauch und verschafft Euch eine Fledermaus. Die Fledermaus bringt Euch über den Lordameresee hinweg zu den Morgeninseln, mitten ins Herz der Verderbnis - zu den Höhlen der Murlocs der Finsterflossen.\n\nBenutzt dieses Gebräu gegen die Murlocs und berichtet mir über die Ergebnisse.\n\nDie Ergebnisse sollten natürlich so aussehen, dass Ihr sie alle wie befohlen getötet habt!", progress = "Habt Ihr die Murlocs der Finsterflossen auf den Morgeninseln ausgerottet?", completion = "Stark genug, um tausend Murlocs auszurotten! Ich glaube, das schreibe ich auf das Etikett. Ihr habt gute Arbeit geleistet, &lt;Name&gt;, und gute Arbeit wird hier belohnt.", rewards = "T'veens UmhangMadenbefallene GamaschenMatschwirblerspeerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][26999] = {title = "Eine neue Ära für die Pestländer", objective = "Sammelt Proben von 4 Seuchenlauerern, 4 Giftnebellauerern, 4 schwerfälligen Seuchenbären und 4 kranken Wölfen.", description = "Die Geißel hat die Macht über dieses Gebiet verloren. Wir, die Lebenden, übernehmen Lordaeron wieder.\n\nWir haben bereits große Fortschritte gemacht, wie Ihr gesehen habt. Die Erde erblüht, die Bäume wachsen immer höher und sind grün und die Tierwelt kehrt langsam zurück. Dennoch sind eine Handvoll Untote zurückgeblieben.\n\nDie Bäume und das Gras gedeihen, aber die Tiere haben Schwierigkeiten. Etwas hindert sie an ihrer Heilung und ich gedenke herauszufinden, was das ist. Bringt mir Proben von den verseuchten Tieren, damit ich sie mir genauer ansehen kann.", progress = "Sobald die Tiere geheilt sind, wird unsere Pflicht hier draußen fast erfüllt sein.", completion = "Das ist mehr als genug, &lt;Name&gt;. Jetzt brauche ich etwas Zeit, um meine Studien durchzuführen.", rewards = "WaldgrünumhangStiefel der blühenden ErdeArmschienen der zurückkehrenden WildnisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27000] = {title = "Komm, hol das Lasso raus", objective = "Steigt am Sägewerk des Nordkamms auf einen Herdweiler Mustang und benutzt seine Fähigkeit 'Wiehern', um 25 Nordkammspinnen Angst einzujagen.", description = "Ah, schön wieder auf dem Nordkamm zu sein! Ich habe mein Sägewerk, meine hübsche Frau, meinen quietschfidelen kleinen Jungen... Ich habe mich sogar dem Argentumkreuzzug angeschlossen. Wir werden Tirions Streitkräfte mit Holz versorgen.\n\nMeine Holzfäller waren ausgesprochen produktiv... bis die Spinnen kamen. Jetzt weigern sie sich, tiefer in den Wald zu gehen.\n\nVielleicht könntet Ihr mir helfen. Schwingt Euch auf eins meiner Pferde und jagt den Spinnen Angst ein. Vielleicht können wir Blutvergießen vermeiden und sie einfach fortjagen.", progress = nil, completion = "Nun, es hört sich so an, als ob sie große Angst vor dem Mustang haben, aber sie bleiben nicht weg. Ich kann Euch nicht ewig auf dem Pferd herumrennen lassen. Und ich glaube auch nicht, dass Ihr das möchtet.\n\nAlso gut. Dann eben Blutvergießen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27001] = {title = "Hier ist WoW (Wald ohne Wildspinnen)", objective = "Besteigt am Sägewerk des Nordkamms einen Herdweiler Mustang und benutzt seine Fähigkeit 'Wiehern', um 10 Nordkammspinnen zu den Rekruten von Herdweiler an der Nordkamm Sägemühle zu treiben. Ihr könnt mehrere Spinnen auf einmal zusammentreiben.", description = "Der Hochlord war so großzügig, einige seiner Rekruten zu entsenden, damit sie uns hier am Sägewerk unterstützen. Mit Eurer Reitkunst und ihren Kampfkünsten können wir uns dieses Spinnenproblems mit Leichtigkeit entledigen.\n\nSteigt wieder auf den Mustang und macht den Spinnen Angst. Diesmal müsst Ihr sie aber bis zum Sägewerk vor Euch hertreiben. Die Rekruten aus Herdweiler können sich dann hier der Dinge annehmen.", progress = nil, completion = "So ist es schon viel besser! Jetzt können meine Holzfäller wieder an die Arbeit gehen.\n\nWie schon gesagt, Ihr seid da draußen gut geritten, &lt;Name&gt;. Auf dem Mustang gebt Ihr ein echt gutes Bild ab.", rewards = "SpinnenplätterkolbenSpinnenbrutzlerAuf Euch wartet eine dieser Belohnungen:\n\nBand des Arachnidenzänkers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27002] = {title = "Eine Audienz mit dem Hochlord.", objective = "Meldet Euch in den Westlichen Pestländern in Herdweiler bei Hochlord Tirion Fordring.", description = "Oh, bevor Ihr geht, <Name>... Ich habe eine Nachricht für Euch. Jemand in Herdweiler möchte Euch gerne kennenlernen. Er sagte, dass er bereits einige Male über Euren Namen gestolpert ist.\n\nIhr könnt Euch glücklich schätzen, <Name>. Nicht jeder bekommt eine persönliche Audienz mit Hochlord Tirion Fordring.\n\nOh - und Ihr dürft gerne einen meiner Mustangs für den Ritt dorthin nehmen. Sie sind die schnellsten, die man für Geld kaufen kann.", progress = nil, completion = "&lt;Name&gt;. Es ist mir wirklich ein Vergnügen.\n\nIch weiß, Ihr seid jung und steht noch in Ausbildung, aber ich habe Euch im Auge behalten. Wir beim Argentumkreuzzug suchen immer nach vielversprechenden Rekruten und Ihr habt großes Potenzial gezeigt. Ich habe noch keine Aufgaben für Euch, doch ich wollte Euch persönlich kennenlernen und mir selbst ein Bild davon machen, was Ihr für ein &lt;Volk&gt; seid.\n\nFür den Moment dürft Ihr Euch an den Annehmlichkeiten von Herdweiler erfreuen. Ich freue mich auf unser nächstes Treffen, &lt;Name&gt;. Ihr dürft wegtreten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27003] = {title = "Leichtverdientes Geld", objective = "Begleitet Adarrahs Karawane hinein nach Uldum.", description = "Wen haben wir denn da!\n\nWie auch immer Ihr hierhergekommen seid, ich bin so froh, dass Ihr hier seid!\n\nMeine Freunde hier würden es nie zugeben, aber wir können wirklich Hilfe gebrauchen.\n\nDie uralte Region von Uldum ist freigelegt worden! Dort gibt es Schätze, die Eure kühnsten Träume übertreffen, und man kann sie einfach mitnehmen!\n\nDas einzige, was wir brauchen, ist eine kleine Eskorte, bei den ganzen Banditen und so...\n\nIhr werdet uns begleiten, oder?\n\nIhr dürft auch so viele Schätze mitnehmen, wie Ihr tragen könnt!", progress = nil, completion = "Es riecht, als wäre vor Kurzem jemand in dieser Zelle gewesen.\n\nIgitt!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAdarrahs Ausbruch Käfig (Master)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27004] = {title = "Zwielichtpläne", objective = "Sammelt die Pläne für das Tor der Meister.", description = "Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.\n\nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, <Name>.\n\nDurchsucht die Kultisten, bis Ihr sie findet.", progress = "Diese Pläne sind der Schlüssel zu allem.", completion = "&lt;Mowi betrachtet die Pläne, die Ihr ihr gegeben habt.&gt;\n\nAber… aber das ist nichts als Kauderwelsch!\n\nWas soll das überhaupt bedeuten? Welche Sprache ist das?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27005] = {title = "Zwielichtpläne", objective = "Sammelt die Pläne für das Tor der Meister.", description = "Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.\n\nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, <Name>.\n\nDurchsucht die Kultisten, bis Ihr sie findet.", progress = "Diese Pläne sind der Schlüssel zu allem.", completion = "&lt;Der Prüfer betrachtet die Pläne, die Ihr ihm gegeben habt.&gt;\n\nDas ist nichts als Kauderwelsch!\n\nWas soll das überhaupt bedeuten? Welche Sprache ist das?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27006] = {title = "Überflieger", objective = "Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.", description = "Ich hab versucht, die Terrasse zu überfliegen und mir selbst 'n Bild zu machen, aber diese toastfressenden Weicheier ha'm auf mich geschossen und ich kam nicht dran.\n\nIhr seht so aus, als ob Ihr mit Zügeln umgehen könnt. Warum nehmt Ihr nicht Euer Flugtierchen und fliegt hoch nach Südwesten, mal nachsehen, was der ganze Wirbel soll?", progress = nil, completion = "Ein Tor?! Die Kulties ha'm ein Titanentor ausgebuddelt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27007] = {title = "Stelldichein in den Silbermarschen", objective = "Geht zu den Oberen Silbermarschen in Tiefenheim.", description = "Ausgezeichnete Arbeit, <Name>. Wir wissen genau, wo der Treffpunkt ist.\n\nDie Oberen Silbermarschen sind ein Quecksilbersumpf östlich von hier. Normalerweise hausen dort Elementare und gelegentlich auch Steintroggs, aber unsere Späher haben in der Region Aktivität des Schattenhammers beobachtet.\n\nMacht Euch auf den Weg dorthin und findet eine Möglichkeit, das Treffen des Schmiedemeisters zu belauschen.", progress = nil, completion = "Das ist der Ort. Unsere Späher haben die Anwesenheit von hochrangigen Offizieren des Schattenhammers bestätigt und gleichzeitig mögliche Troggjäger ausgemacht.\n\nSeid vorsichtig, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27008] = {title = "Überflieger", objective = "Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.", description = "Ich bin ziemlich geschickt im Umgang mit dem fliegenden Teppich. Doch als ich versucht habe, herauszufinden, was diese Kultisten auf der Zwielichtterrasse entdeckt haben, haben sie mich fast vom Himmel geschossen.\n\nIhr seht aus, als wärt auch Ihr ein Meister der Lüfte. Würdet Ihr für mich nach Südwesten fliegen und herausfinden, was sie da ausgegraben haben?", progress = nil, completion = "Ein Tor?! Sie haben ein Tor der Titanen ausgegraben.\n\nDas ist äußerst interessant und möglicherweise sehr gefährlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27009] = {title = "Der Kältebringer", objective = "Tötet Amnennar den Kältebringer.", description = "Amnennar der Kältebringer regiert die Hügel der Klingenhauer mit dunkelster und mächtiger Geißelmagie. Es ist mir gelungen, eine Öffnung in die Dornen oberhalb seines Machtsitzes zu schlagen, aber seine Zauberkraft verwehrt es mir, einen Angriff zu starten.\n\nWenn Ihr die Dornenspirale hinaufgeht und ihn angreift, wird ihn das ablenken, bis ich ihn angreifen und schwächen kann, damit er seine tödlichen Zauber nicht wirken kann. Wenn er erst geschwächt ist, tötet ihn, ohne Gnade zu zeigen.", progress = nil, completion = "Das war gute Arbeit, &lt;Name&gt;. Die Stacheleber hier können nicht gerettet werden, aber wenigstens sind sie nicht mehr zum Angriff aufgestellt und sind nicht länger Sklaven unter Amnennars tyrannischer Herrschaft.\n\nBitte geht schnell. Die Hügel der Klingenhauer sind ohne Hoffnung. Sie müssen gereinigt werden.", rewards = "Gamaschen des KältebringersKlingenhauerschiftungBrustschutz der ErlösungGürtel der tyrannischen HerrschaftAuf Euch wartet eine dieser Belohnungen:\n\nKoristraszas Amulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27010] = {title = "Untertauchen im Quecksilber", objective = "Verschafft Euch eine Troggkiste und versteckt Euch darunter. Dann belauscht das Lager des Schattenhammers im Osten.", description = "Die Troggs in Tiefenheim sind genauso feindselig wie die in Azeroth. Dennoch, ihre Anwesenheit könnte für unsere Bemühungen von Vorteil sein.\n\nDie Kisten, die sie benutzen, um in dem Quecksilber herumzufischen, können Euch perfekt tarnen, wenn Ihr in den Marschen auf Tauchstation geht.\n\nBenutzt sie, um das Lager des Schattenhammers am östlichen Ende der Oberen Silbermarschen unentdeckt zu erreichen.", progress = nil, completion = "Wir haben die benötigten Informationen. Wir sollten uns nicht verraten, indem wir den Feind zu früh angreifen.", rewards = "Ballastbeschwerte FußpolsterKastenrahmenschiftungAtemröhreIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27011] = {title = "Rotkieferdiebstahl", objective = "Holt aus dem Rotkieferlager in den Westlichen Pestländern 10 Stapel Nordkammholz zurück.", description = "Weiter im Süden findet Ihr Gnolle der Rotkiefer...Neuankömmlinge in diesem Gebiet. Ihr seid wahrscheinlich auf dem Weg hierher an ihnen vorbeigekommen. Nathaniel tut so, als ob sie kein Problem darstellen, aber ich weiß es besser.\n\nIch habe gesehen, wie sie nachts mit unserem Holz weggerannt sind. Ich weiß gar nicht, was sie mit dem Holz vorhaben - sie scheinen keine guten Handwerker zu sein - aber das hält sie nicht davon ab, es zu stehlen. Geht hinunter zu ihren Lagern und stehlt das Holz zurück.", progress = "Einige der älteren Holzfäller erzählen, dass die Rotkiefer vor einigen Jahren hier gelebt haben. Doch als die Seuche ausbrach, sind sie fortgegangen. Trotzdem gibt ihnen das nicht das Recht, zu stehlen.", completion = "Ich bringe das nur eben zurück in die Holzlager draußen. Nathaniel wird wahrscheinlich nicht einmal bemerken, dass es gefehlt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27012] = {title = "Lösung des Gnollproblems", objective = "Beschafft 6 Rotkieferstäbe und 6 Rotkieferkeulen von den Gnollen der Rotkiefer.", description = "Ich habe so meine Zweifel, was die Absichten dieser Gnolle angeht. Bisher haben sie uns noch nicht angegriffen, aber es werden immer mehr und sie scheinen immer ihre Waffen im Anschlag zu haben. Ich bin kein Militärexperte, aber das erscheint mir ein wenig aggressiv.\n\nWenn wir ihnen einige ihrer Waffen wegnehmen, werden sie vielleicht nicht zur Bedrohung für unser Sägewerk. Ich würde mich viel besser fühlen, wenn Ihr dort hinunter geht und einige ihrer Waffen zu mir bringt.", progress = "Ich will nicht allein wegen einer besorgten Mutter eine Art Massenmord an Gnollen befehlen. Ich möchte mich nur in meinem Zuhause sicher fühlen.", completion = "Danke, &lt;Name&gt;. Ich werde die jetzt ins Feuer werfen. Schließlich wollen wir nicht, dass die Gnolle sich hineinschleichen und sie erneut stehlen.", rewards = "HolzfällerbeilRotkieferumhangKellys StiefelettenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27013] = {title = "Zu knapp für meinen Geschmack", objective = "Tötet in den Westlichen Pestländern nahe dem Sägewerk des Nordkamms 12 tollwütige Füchse.", description = "Ich freue mich für Nathaniel. Er versucht schon so lange, wieder nach Nordkamm zurückzukehren. Jetzt, da der Scharlachrote Kreuzzug ihm nicht mehr im Weg steht, kann er endlich nach Hause. Nur ... Auch, wenn die Umgebung hier idyllisch zu sein scheint, ist sie nicht der beste Ort, um eine Familie aufzuziehen.\n\nZum Beispiel: Am Rande dieses Tals findet man tollwütige Füchse, die nach unschuldiger Beute suchen. Hin und wieder erhasche ich einen Blick auf einen von ihnen, der mich direkt anschaut.\n\nBitte, <Klasse>, erlegt einige dieser Füchse. Ich fühle mich in ihrer Nähe nicht sicher.", progress = nil, completion = "Jetzt bin ich etwas erleichtert, &lt;Name&gt;. Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27014] = {title = "Geheiligte Notiz", objective = "Sprecht im Camp Narache mit Seherin Rabenfeder.", description = "Gerade war ein Bote hier und hat Euch gesucht, <Name>. Ich glaube, er wurde von der Priesterlehrerin Seherin Rabenfeder geschickt. Wenn diese Nachricht von der Seherin ist, würde ich sie sofort aufsuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27015] = {title = "Geweihte Notiz", objective = "Sprecht im Camp Narache mit Sonnenwandler Helaku.", description = "Gerade war ein Bote hier und hat Euch gesucht, <Name>. Ich glaube, er wurde von dem Paladinlehrer Sonnenwandler Helaku geschickt. Wenn diese Nachricht von dem Sonnenwandler ist, würde ich ihn sofort aufsuchen.", progress = "Sehr erfreut, Euch kennenzulernen, <Name>.", completion = "Es gibt viel zu tun. Im Laufe der Zeit werden Euch die Gepflogenheiten der Sonnenwandler in Fleisch und Blut übergehen, ebenso wie die Unterhaltungen der Schamanen mit den Elementen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27016] = {title = "Die Freuden der Eberjagd", objective = "Tötet 10 Schlammbaucheber.", description = "Versucht, Eure Aufregung zu zügeln, <Name>, denn Ihr befindet Euch in der Gesellschaft des besten Eberjägers in Azeroth!\n\nIhre Durchtriebenheit, ihre rasende Geschwindigkeit, die extreme Stärke und die widerstandfähigen Bälger... ja, Eber sind nur die Beute der meisterlichsten Jäger. Anfänger brauchen sich gar nicht erst bewerben!\n\nIch wette, Ihr habt noch nie so ein exotisches Tier gejagt. Ich halte jede Wette, dass Ihr meinen Rekord von zehn getöteten Ebern nicht einstellen könnt. Versucht es mit denen an der Ostseite des Loch, aber tut Euch nicht weh, Grünschnabel!", progress = nil, completion = "Ihr habt bereits zehn getötet? H...hah! Während Ihr unterwegs wart, habe ich meinen bisherigen Rekord gebrochen! Jetzt steht er auf zehn...hundert! Ja, zehnhundert Eber!\n\nEine Wette ist eine Wette...hier ist Euer Trostpreis, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27017] = {title = "Erinnerungen an längst vergangene Zeiten", objective = "Begebt Euch zum Hof in Gahrrons Trauerfeld und sammelt alle Erinnerungsstücke, die Ihr finden könnt.", description = "Schon komisch, an was man sich so erinnert. Ich habe 16 Stunden am Tag auf den Feldern gearbeitet und an jedem siebten Tag bin ich in das geschäftige Andorhal gegangen, um das, was ich angebaut hatte, zu verkaufen. Es war ein hartes Leben, aber wir kamen zurecht.\n\nDoch ich erinnere mich kaum daran. Wenn ich an die Zeit zurückdenke, fällt mir Glorias Lächeln ein - oder wie Andrea mir aus dem Fenster zugewinkt hat, wenn ich von dem Pflug aufsah.\n\nDer Hof ist etwas östlich von hier, aber ich bin nicht sicher, ob ich schon bereit bin, dorthin zurückzukehren, <Name>. Ich möchte nur diese Erinnerungen nicht verlieren.", progress = "Ich möchte Euch nicht mit den Launen eines nostalgischen alten Mannes belästigen, <Name>, aber solltet Ihr in der Gegend sein...", completion = "Dies... Gloria hat jeden Abend aus diesem Gebetsbuch gelesen! Wie konnte ich das nur vergessen? Sie war so fromm, &lt;Name&gt;.\n\n\n\nOh...\n\nDieses Bild... meine Tochter, Andrea... sie hat so gerne gemalt.", rewards = "Schritte der ErinnerungGlorias ArbeitswesteGahrrons SchulterschutzAuf Euch wartet eine dieser Belohnungen:\n\nAndreas Medaillon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27019] = {title = "Geißel der Hügel", objective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber irgendjemand muss es ja tun und ich bezweifle ernsthaft, dass noch andere Abenteurer ihren Weg an diesen hoffnungslosen Ort finden werden.", progress = "Ich schere mich nicht um Politik; mich interessiert nicht, ob Ihr Euch auf die Seite der Horde oder der Allianz schlagt. Ich bin eher daran interessiert, direkte und schreckliche Drohungen gegen alle Völker auszuschalten... und das hier ist eine ziemlich große.\n\nWenn Ihr willens seid, für alle Völker ein wahrer Held zu sein, dann übergebt mir den Schwurstein, den ich Euch gab, als Zeichen der Verpflichtung. Ich bin... nicht aus dieser Gegend, ein Schwurstein bedeutet für Leute wie mich ein Bund der Übereinkunft.", completion = "Phantastisch, ich dachte schon, dass Ihr heldenmutig ausseht! Ich will Euch nicht anlügen, &lt;Name&gt;, wir haben eine Menge Arbeit vor uns. Wenn wir uns auf die vor uns liegende Aufgabe konzentrieren, sollten wir in der Lage sein, als Sieger aus der Sache hervorzugehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27020] = {title = "Die erste Lektion", objective = "Erreicht Stufe 3 und erlernt Sturmangriff. Findet eine Trainingsattrappe in Camp Narache und übt diese Fähigkeit.", description = "Bis jetzt habt Ihr Euch wacker geschlagen. Je weiter Euer Weg Euch führt, desto stärker werdet Ihr. Ihr erlernt dann Techniken, von denen Ihr zuvor nicht einmal zu träumen gewagt habt.\n\nEure erste Lektion wird die Macht der Erfahrung sein. Geht, erlernt eine neue Fähigkeit und führt sie mir dann vor.", progress = nil, completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27021] = {title = "Der Weg des Jägers", objective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe in Camp Narache und übt fünfmal 'Zuverlässiger Schuss'.", description = "Es ist Zeit für Eure erste Lehrstunde, <Name>. Vor Euch liegt noch ein langer Weg, bis Ihr die Gebräuche der Jäger beherrscht, aber jede neue Fähigkeit ist ein weiterer Schritt auf diesem Weg.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Probiert sie dann an einer Trainingsattrappe hier.", progress = nil, completion = "Ihr habt Eure Sache gut gemacht,&lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27022] = {title = "Ausschalten des Götzen", objective = "Beschützt Belnistrasz.", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; sie... sie verzehren buchstäblich die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und ihn unbrauchbar machen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. \n\nSteht Ihr mir bei? Kann ich auf Eure Hilfe zählen, um diesen Gräßlichkeiten ein Ende zu bereiten?", progress = nil, completion = "Belnistrasz' plötzlicher Abgang hat eine brennende Kohlenpfanne hinterlassen. Während Ihr in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln Euren Geist. Eine rauere Version von Belnistrasz' Stimme spricht direkt zu Euch.\n\n\"Wahrlich, sterbliche Wesen, Ihr seid die Helden, die ich mir erhofft hatte. Dank Euch gehören die Schlächtereien, die diese Bestien begangen haben, der Vergangenheit an. Mein Glaube an Wesen wie Euch ist wieder einmal erneuert worden. Nehmt dies als Belohnung, die eines Helden würdig ist.\"", rewards = "Ihr bekommt:\n\nDrachenklauenring"}
MultiLanguageQuestData['de'][27023] = {title = "Der Weg des Sonnenwandlers", objective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Findet eine Trainingsattrappe in Camp Narache und übt die Anwendung von 'Siegel des Befehls'.", description = "Es ist immer ein Vergnügen, einen anderen Sonnenwandler zu treffen. Von uns gibt es nicht so viele wie von den älteren Orden, aber unsere Wege sind nicht weniger mächtig und unsere Mitglieder werden nicht weniger respektiert.\n\nWährend Eurer Reise werdet Ihr dem Licht näher kommen und Fähigkeiten erlernen, die Ihr Euch bisher nicht ausmalen konntet.\n\nGeht, sammelt mehr Erfahrung und kehrt zurück, wenn Ihr eine neue Fähigkeit beherrscht und demonstriert sie mir.", progress = nil, completion = "Ich bin stolz auf Euch, &lt;Name&gt;. Ihr werdet einen guten Sonnenwandler abgeben. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung wünscht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27024] = {title = "Komplizen", objective = "Tötet, Nimmersatt, Mordresh Feuerauge und Tuten'kash.", description = "Obwohl Amnennar hier die größte Bedrohung darstellt, ist er beileibe nicht die einzige. Ihr müsst auch seine Leutnants erschlagen, wenn ihre Umklammerung der Niederungen aufhören soll.\n\nNimmersatt bewacht den Anfang der Dornenspirale.\n\nMordesh steht oben auf dem Knochenhaufen und wiegelt die Geißel zu blinder Wut auf.\n\nTuten'kash befindet sich unter der Erde. Um ihn herauszulocken, müsst Ihr den Gong in der Kammer des Rufers drei Mal schlagen.\n\nViel Glück, tapferer Held.", progress = nil, completion = "Gut gemacht! Ohne ihre Anführer ist die Geißel keine nennenswerte Bedrohung mehr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27025] = {title = "Disteln im Dickicht", objective = "Sammelt 6 Dolchdistelsamen.", description = "Es ist die Jahreszeit der Dolchdisteln! Dolchdistelsamen sind für 89% der durch Samen verursachten Verletzungen bei Jägern verantwortlich.\n\nIhr werdet Dolchdistelsamen zum größten Teil in den unteren Waldländern nördlich der Jagdhütte finden. Man findet sie gewöhnlich auf dem Boden bei Bäumen und sie werden Euch stechen und Schmerzen zufügen.\n\nIch würde Euch ja den Rat geben, einen Bogen um sie zu machen, aber ich brauche jemanden, der mir hilft, sie aus Sicherheitsgründen zu entfernen. Bringt mir Dolchdistelsamen, damit andere sich nicht verletzen.", progress = "Ihr müsst sie mit größter Vorsicht behandeln!", completion = "Ich habe gehört, dass es für die Waldländer auch eine Bärenwarnung gibt. Bären lieben diese Dolchdistelsamen.\n\nGut, dass Ihr sie gesammelt habt, damit sie nicht noch mehr Bären anziehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27026] = {title = "Alarmstufe: Rotluchs", objective = "Tötet 8 Rotluchse.", description = "Lasst alles stehen und liegen! Es ist mir zu Ohren gekommen, dass in der Nähe der Jagdhütte Rotluchse gesehen wurden. Rotluchse!\n\nIch habe zwar noch nie einen Rotluchs gesehen, aber sie sind bestimmt gefährlich. Sie sind wie Berglöwen oder so ähnlich. Ich will nicht, dass jemand fortgeht, bevor die Gegend nicht gesichert ist.\n\nAußer Euch, heißt das. Ich werde Euch dafür bezahlen, die Gegend zu sichern, <Klasse>. Aber lasst Euch nicht in Stücke reißen.", progress = nil, completion = "Also gut, ja, man hat mich informiert, dass die Rotluchse viel kleiner sind, als zunächst angenommen. Aber für Gnome ist das immer noch ganz schön gefährlich!\n\nIhr habt Euch um die Sicherheit diese Hütte verdient gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27027] = {title = "Urtümlicher Schlag", objective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Findet eine Trainingsattrappe in Camp Narache und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", description = "Ich weiß, dass Ihr geholfen habt, Camp Narache vor den Borstennacken zu beschützen. Wir werden jeden Hammer und alles Glück, das wir bekommen können, brauchen.\n\nWährend Ihre Eure Fertigkeiten verbessert, werdet Ihr auch die Verbindung zu den Elementen vertiefen. Dadurch erhaltet Ihr Zugang zu neuen Fähigkeiten.\n\nDie erste, die Ihr erlernen werdet, nennen wir 'Urtümlicher Schlag'. Diese Fähigkeit sollte Euch dabei helfen, Eure Feinde schneller zu schlagen. Erlernt sie und probiert sie dann aus.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wie ich sehe, werdet Ihr keine Probleme haben, auch unsere fortgeschrittenen Künste zu meistern, wenn Ihr an Erfahrung gewinnt. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27028] = {title = "Hornissenjagd", objective = "Erbeutet 6 glasige Hornissenflügel.", description = "Wir suchen hier immer nach neuem Wild. Daryl mag seine Eber ja lieben, aber der Rest von uns bevorzugt etwas exotischere Dinge.\n\nNun, ich würde niemals behaupten, dass es gut war, den Loch trockenzulegen, aber es gab einen Lichtblick. Der sumpfige Untergrund hat neue Beute hervorgebracht: Hornissen!\n\nUnd obendrein noch riesige Hornissen. Nicht viele Jäger haben sich mit so riesigen Insekten gemessen. Das ist ziemlich neu.\n\nIch möchte gerne, dass Ihr es versucht - ich biete Euch eine Wette an. Bringt mir einige dieser wunderschön glänzenden Flügeln von ihnen und ich bezahle Euch.", progress = "Wie geht's mit den Hornissen?", completion = "Wunderbare Exemplare habt Ihr da! Hier ist mein Einsatz, mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27029] = {title = "Die Geißel heilen", objective = "Besorgt 20 verwitterte Hauer.", description = "Viel wirksamer, als eine Welle der Geißel nach der anderen zu töten, wäre es, einen Weg zu finden, wie man lebende Kreaturen davor bewahrt, sich in sie zu verwandeln. Ich habe eine Idee für ein tolles Pulver. Wenn man es einatmet, könnte es den ganzen Prozess unterbinden.\n\nIch benötige verwitterte Hauer von den untoten Stachelebern hier, um dieses Pulver herzustellen. Bringt mir eine ausreichende Menge und wir sind vielleicht in der Lage, das Wachstum der Geißel endgültig aufzuhalten.", progress = "Habt Ihr die Hauer?", completion = "Ich bin davon überzeugt, dass diese Substanz uns in Zukunft weitere Kopfschmerzen ersparen wird. Danke, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27030] = {title = "Eine Handvoll Fuchsschwänze", objective = "Erbeutet 7 flauschige Fuchsschwänze.", description = "Wir haben in letzter Zeit mehr Füchse hier in den Hügeln gesehen. Sie sind gerissene Wesen. Sie sind ein guter Test für die Fähigkeiten eines Jägers - und sie bringen einen schönen Profit!\n\nWegen ihrer Schwänze, <mein Freund/meine Liebe>. Die sind schön und buschig - man kann sie an seinen Gürtel hängen, um Flöhe abzuwehren, oder man kann mit ihnen die Handschuhe eines modebewussten Edelmannes füttern.\n\nAber ich plappere nur daher. Ich bin zwar kein Goblin und die Spannung liegt in der Jagd. Doch wenn Ihr mir ein paar Fuchsschwänze bringt, werde ich Euch gerne dafür bezahlen. Ihr findet die Füchse nördlich der Jagdhütte in den unteren Waldländern.", progress = "Was habt Ihr für mich?", completion = "Ahh, seht Ihr? Waren der feinsten Qualität. Das habt Ihr gut gemacht, die zu besorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27031] = {title = "Verrückt nach Flügeln", objective = "Besorgt 3 makellose Flugfedern von Goldadlern.", description = "Ich habe die Nase von Gyrokoptern voll. Klar, sie erfüllen ihren Zweck, aber seit wann hat das einem Gnom jemals gereicht? Ich will richtig fliegen, mit FLÜGELN!\n\nIch beobachte seit Jahren Vögel und versuche, hinter das Geheimnis zu kommen, wie man eine Maschine baut, die genau wie sie fliegen kann. Dieses elegante Aufschwingen und Herabstoßen, der Wind, der über die Flügel streicht ... ahh.\n\nIhr! Ihr könnt mir helfen. Ich brauchte die besten Flugfedern, die ihr auftreiben könnt. Die goldenen Adler, die in der Nähe der Jagdhütte kreisen, wären eine ausgezeichnete Wahl.", progress = "Die besten Federn sind gerade gut genug!", completion = "Wunderschön. Ihr habt einen Blick für Qualität!\n\nWir sind auf der gleichen Wellenlänge! Offensichtlich könnt Ihr Euch für Flügel und Federvieh begeistern, also könntet Ihr mir noch weiter helfen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27032] = {title = "Ein schräger Vogel", objective = "Findet den verrosteten Himmelsschreiter in der Eisenschwingenhöhle.", description = "Ich habe die Maschine meiner Träume fast perfektioniert: den Himmelsschreiter! Der weltweit erste fliegende Roboschreiter! Aber, nun ja...\n\nAls ich in meinem geheimen Höhlenlabor die letzten Handgriffe daran machte, wurden meine anderen Kreationen... nun ja... eifersüchtig. Den mechanischen Vögeln überhaupt erst eine Persönlichkeit zu verleihen, war wohl keine gute Idee, aber das ist nun so.\n\nIch brauche das supermechanische Robodings aus dem ursprünglichen Himmelsschreiter, wenn ich ihn wieder aufbauen will! Bitte, begebt Euch in die Höhle und holt es für mich zurück!", progress = nil, completion = "&lt;Der Himmelsschreiter sitzt schweigend da, seine Chance, davonzufliegen, ist vertan. Eine auffällige Klappe an seiner Vorderseite trägt die Aufschrift \"SRD\".&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27033] = {title = "Herz der Himmelsstreiter", objective = "Bringt Bingles Blastenheimer in der Jagdhütte der Weltenwanderer das supermechanische Robodings.", description = "Ihr öffnet die Klappe und findet ein beeindruckendes, mechanisches Gerät, das an einige Kabel, Zahnräder und wer-weiß-was noch angeschlossen ist.\n\nEs lässt sich ohne Schwierigkeiten lösen. Zeit, es zu Bingles zurückzubringen.", progress = nil, completion = "Perfekt! Jetzt habe ich die perfekte Flügelbalance und habe alle Teile, die ich benötige. Alles, was noch fehlt, ist ein Pilot.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27034] = {title = "Er ist in dem Alter", objective = "Sprecht mit Ando Blastenheimer auf der Ostseite des Loch.", description = "ich baue den Himmelsschreiter nicht für mich, <Name>. Ich baue ihn nicht mal für die Gnomwelt. Ich möchte, dass mein Sohn derjenige ist, der ihn fliegt.\n\nIch bin alt und meine Reflexe sind nicht mehr das, was sie mal waren. Aber mein Junge Ando könnte der beste Pilot werden, den Azeroth je gesehen hat, wenn er nur seine Teenager-Launenhaftigkeit ablegen würde!\n\nEr sitzt draußen am See und starrt den ganzen Tag den Himmel an. Irgendetwas bedrückt ihn, aber er weigert sich, mit seinem Vater darüber zu sprechen. Ich bin mit meinem Latein am Ende!\n\nBitte, <Name>, könntet Ihr nicht mit ihm reden? Sagt ihm, ich brauche ihn, um den Himmelsschreiter zu fliegen.", progress = nil, completion = "Mein Vater und seine albernen Erfindungen sind mir egal! Das ist alles nur Unsinn!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27035] = {title = "Stellung beziehen", objective = "Zerstört den Zwielichtumweltgestalter in der Mitte des Schattenhammerlagers.", description = "Schaut sie Euch an. Der Schattenhammer hat dieses Land ruiniert!\n\nDieser Kult hat diesen Kataklysmus ausgelöst, den Steinwerkdamm zerstört und den ganzen Loch trockengelegt. Und jetzt laufen sie in den Trümmern herum, als ob hier ihr Zuhause wäre!\n\nWenn es in dieser Welt Gerechtigkeit gäbe, würde jemand in ihr Lager marschieren und ihr Artefakt in Stücke brechen. Aber ich bin zu schwach, um auch nur an einen Versuch zu denken.\n\nUnd niemand hat genug Mut dazu! Nicht einmal Ihr! Seht Ihr? Es ist alles so sinnlos...", progress = nil, completion = "Ihr habt es getan! Ihr habt es wirklich getan! Ihr habt gegen sie gekämpft und gewonnen!\n\nEs besteht doch noch Hoffnung...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27036] = {title = "Vyrins Rache", objective = "Tötet alte Rußtatze und bringt seinen Kopf an Euch.", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Jagdhütte der Weltenwanderer, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das Einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nAlte Rußtatze, der Bär, hält sich irgendwo in der Nähe seines Baus nördlich von hier auf.", progress = "Ah, <Name>! Schon wieder hier? Zweifelsohne wart Ihr wieder auf der Jagd! Keine Sorge, es ist nicht schlimm, wenn Ihr ein paar Rückschläge einstecken müsst, davon werdet Ihr auf lange Sicht nur besser.\n\n... viel schlechter könntet Ihr ja sowieso nicht mehr werden...", completion = "Äh... was ist das da? Ein Bärenschädel, wie es aussieht.\n\n&lt;Er fährt unbewusst mit einem Finger an seiner Narbe entlang&gt;\n\nNun, das ist eine ziemlich interessante Beute, die Ihr da habt. Kann eigentlich nicht der Bär von damals sein...\n\n&lt;Seine Stimme verliert sich, und er fängt sichtbar an zu zittern.&gt;\n\nOh, nehmt das weg, nehmt es weg! Schafft dieses grausige Ding hier raus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27037] = {title = "Vyrins Rache", objective = "Bringt den Kopf der alten Rußtatzes zu Vyrin Flinkwind in die Jagdhütte der Weltenwanderer.", description = "Licht! Bringt solche Dinge nicht in die Jagdhütte... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!\n\nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, aber wirklich nicht!", progress = "Sehr gute Arbeit, <Name>! Wir haben's ihm wirklich gezeigt! Hier, gebt mir den Kopf, ich werde mich darum kümmern.", completion = "Danke für Eure Hilfe bei meinem kleinen Plan, &lt;Name&gt;. Seit Monaten wollte ich es diesem hochnäsigen, eingebildeten Jungen schon heimzahlen und ich würde meinen, es hat so richtig gut geklappt! Hier, nehmt das, Ihr habt es Euch verdient.", rewards = "Unhygienische HandschuheVyrins GürtelFlinkwindklingeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27038] = {title = "Fehlende Teile", objective = "Hebt 5 fehlende Teile im Hafen von Sturmwind auf.", description = "<Der Unteroffizier wendet seine Aufmerksamkeit Euch zu.>\n\nHört zu, wenn Ihr helfen wollt, dass alles hier etwas schneller geht, dann haltet mir Flintlocke vom Leib. Eine ganze Ladung Belagerungsmaschinenteile ist verlegt worden und jetzt über das ganze Dock verteilt.\n\nSammelt die fehlenden Teile auf und bringt sie zu Flintlocke, damit er den Bau beenden kann. Er ist auf der anderen Seite der Straße und wartet.", progress = "Wat is'?\n\nMeine Teile. Wo sind sie? Man kann keinen Panzer ohne Teile bauen!\n\nUnd wenn, wäre er zu klein. Un' ziemlich inner-fektiv.", completion = "&lt;Flintlocke wühlt gierig durch die Maschinenteile und wirft einige ausgewählte Stücke über die Schulter.&gt;\n\nJau, hier is' das Zeugs ja. &lt;Er steckt seinen Kopf tief in eine der Kisten.&gt;\n\nAber wo ist mein Pulver? Alles ist hier, nur nicht das Pulver. Ich brauche Sprengstoff, Mann!\n\nSagt dem König: Keine Macht, wenn's nicht kracht. Ich brauch' 'n paar Kabummplosionen, sonst verlass ich den Hafen nich'.", rewards = "Geplünderte ArmschienenRekonstruierende HalsbergeMaschinenverbindungsgurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27039] = {title = "Unter Feinden", objective = "Findet Todespirscherin Yorick auf dem Ivarfeld im Silberwald.", description = "Wisst Ihr, warum Mortuus 'nub' an Euren Namen anhängt, <Name>? Weil er ein inkompetenter Kriecher ist, der kaum aus seinem übergroßen Helm hervorschauen kann. 'NUB' ist Eure Bezeichnung. Ihr seid jetzt nämlich Teil des NEUEN UNTERSTÄDTER BATAILLONS.\n\nDoch genug der Witze! Ich habe Todespirscherin Yorick vor zwei Tagen auf eine Überwachungsmission geschickt. Ihr Ziel war es, Informationen über die Gilnearische Befreiungsfront zu sammeln und zurückzukehren. Jetzt habe ich schon drei Tage lang nichts mehr von ihr gehört.\n\nGeht nach Südwesten zum Ivarfeld und sucht nach Yorick, <Name>.", progress = nil, completion = "Belmont wird ein bisschen nervös und schon schickt er irgendeinen Grünschnabel, um nach mir zu suchen? Hört zu, ich habe das Ivarhaus aus diesem Plumpsklo heraus drei Tage lang observiert. Eure Anwesenheit gefährdet die gesamte verdammte Mission!\n\nIch habe keine Zeit für Erklärungen. Wir müssen jetzt handeln. Sonst war alles umsonst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27040] = {title = "Entschlüsselung leichtgemacht", objective = "Entschlüsselt 6 Pläne.", description = "Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.\n\nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27041] = {title = "Entschlüsselung leichtgemacht", objective = "Entschlüsselt 6 Pläne.", description = "Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.\n\nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27042] = {title = "Mächte des Feuers, des Wassers und der Luft", objective = "Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.", description = "Habt Ihr da oben diesen plappernden Idioten gehört? Das ist kein Geringerer als Haethen Kaul, ihr Anführer.\n\nDie Macht hat ihn in den Wahnsinn getrieben. Er entzieht sie den gebundenen Elementaren, was ihn nahezu unbesiegbar macht.\n\nDie einzige Chance, wie Ihr ihn im Kampf besiegen könnt, besteht darin, die Elementare zu töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.\n\nNun, zumindest vor einem Großteil davon.", progress = "Ihr müsst Euch schon mehr anstrengen, Kumpel!\n\nUnd jetzt hoch da mit Euch und erledigt Eure Aufgabe. Oder muss ich es selbst tun?", completion = "Das nenne ich Kampfgeist! Ein Übel weniger in dieser Welt, vor dem die Kleinen sich fürchten müssen, wenn sie abends ins Bett gehen.\n\nUnd wir müssen uns auch keine Sorgen mehr um ihn machen!\n\nNun, dann lasst mich mal nachsehen. Irgendwo in unseren Kisten haben wir sicher eine passende Belohnung für Euch.", rewards = "Helm des zum Schweigen gebrachten GequasselsKaultöterhandschutzWehrfeuerschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27043] = {title = "Mächte des Feuers, des Wassers und der Luft", objective = "Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.", description = "Habt Ihr da oben den Mann und sein unaufhörliches Geschrei gehört? Das ist Haethen Kaul, ihr Anführer.\n\nEs ist kein Geheimnis, dass die Macht, die er den gebundenen Elementaren entzieht, ihn in den Wahnsinn getrieben hat. Leider macht sie ihn auch nahezu unbesiegbar.\n\nWenn Ihr gegen ihn kämpfen wollt, müsst Ihr erst die Elementare töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.\n\nNun, zumindest vor einem Großteil davon.", progress = nil, completion = "Eine beeindruckende Vorstellung Eures Kampfgeschicks, &lt;Klasse&gt;.\n\n\n\nIch glaube, dass Ihr Euch eine Belohnung verdient habt. Etwas, das einem mächtigen Mann wie Euch angemessen ist.", rewards = "Großhelm des ZungenschneidersStulpen des VerstummersFesselnzerreißende SchulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27044] = {title = "Die Sorgen der Bauern", objective = "Begleitet Prinz Anduin zu Bauer Wollerton auf Wollertons Bauernhof in Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", description = "Ich möchte noch nicht zur Burg zurückkehren. Würdet Ihr mir bei etwas helfen?\n\nEinige der hiesigen Bauern haben vor Kurzem beim König eine Eingabe gemacht, bei der es um vermisstes Nutzvieh ging. Mein Vater hat versprochen, dass jemand der Sache nachgeht, aber die Stadtwache ist so ausgelastet, dass das Wochen dauern würde.\n\nIch dachte, ich könnte doch helfen! Es wird den Bauern Mut machen, wenn sie sehen, dass jemand sich darum kümmert, besonders, wenn es jemand der königlichen Familie ist. Außerdem geht es ja nur um paar vermisste Kühe. Nichts Gefährliches.\n\nBringt mich hier in der Stadt zu Bauer Wollerton!", progress = "Äh, ja?", completion = "&lt;Als er den Prinzregenten sieht, fällt Bauer Wollerton ungeschickt auf ein Knie.&gt;\n\nEu - Eu - Eure Hoheit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27045] = {title = "Lauschangriff", objective = "Betretet das Landhaus auf dem Ivarfeld und sucht oben nach einem geeigneten Versteck. Belauscht dann Lord Darius Crowley.", description = "Der Anführer der Gilnearischen Befreiungsfront, Darius Crowley, hält jetzt schon seit drei Tagen ein Treffen mit einem anderen Worgen in diesem Landhaus ab. Ich bin mir nicht sicher, was da los ist, aber wir müssen in das Haus gelangen und einen guten Platz finden, von dem aus wir sie belauschen können.\n\nJetzt oder nie, <Volk>. Eine zweite Chance werden wir wohl kaum bekommen.\n\nAber falls ich es nicht schaffe, müsst Ihr mir versprechen, zur Kommandozentrale der Verlassenen zurückzukehren und Belmont von unseren Erkenntnissen zu berichten.", progress = nil, completion = "Oh je, arme Yorick! Ich kannte sie gut, &lt;Name&gt;. Eine Assassine mit unvergleichbarem Mut…\n\nAlso, was geht dort vor sich? Was habt Yorick und Ihr herausgefunden?", rewards = "Treter des ÜberlebendenYoricks VermächtnisUmhang des MutesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27046] = {title = "Bohrende Angst", objective = "Tötet 10 Schleifwürmer.", description = "Die Tunnelgräber haben den Fels befallen und fressen die ganze Zeit daran; eines Tages wird unser Heim zusammenbrechen. Für jeden, den man tötet, brechen zweimal so viele hervor und wir müssen immer weiterkämpfen. Sie müssen ausgerottet werden.\n\nGeht zu den Bruchtiefen und vernichtet alle Würmer, die Ihr finden könnt.", progress = nil, completion = "Ihr führt einen Krieg, den wir nicht führen können. Danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27047] = {title = "Partikel", objective = "Holt 10 Painitpartikel.", description = "Einige der seltensten Kristalle entstehen an den gefährlichsten Orten. In den Bruchtiefen werdet Ihr Painitformationen finden. Das ist viel besser als das Gold, das Eure Rassen so schätzen.\n\nDa Ihr ein fleischliches Wesen von kleinem Wuchs seid, könnt Ihr die Bruchtiefen betreten und Painitpartikel für mich holen. Würdet Ihr Euch dieser Gefahr für mich aussetzen?", progress = "Painit ist für uns eins der wertvollsten Materialien, besonders weil wir die meisten Vorkommen nicht selbst erreichen können.", completion = "Gut gemacht, &lt;Volk&gt;. Die werden gute Dienste leisten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27048] = {title = "Untergrundwirtschaft", objective = "Benutzt Rickets Ticker, um 3 Tiefenalabasterkristalle, 3 Tiefencoelestinkristalle, 3 Tiefenamethystkristalle und 3 Tiefengranatkristalle zu sammeln.", description = "Hey! Ich versuche, einige dieser Kristalle zu sammeln. Die Elementare zahlen gut für das Zeug... wenn Ihr mir helft, die ganzen verschiedenen Sorten zu sammeln, bekommt Ihr einen Anteil vom Gewinn.\n\nBenutzt diese Bomben, um Teile aus den größeren Kristallformationen herauszusprengen.\n\nIch hab' die dumme Angewohnheit, mit Sprengstoff ein wenig zu dick aufzutragen. Nehmt Euch vor dem Rückstoß in Acht.", progress = "Bumm?", completion = "Gut gemacht!\n\nIch habe hier dieses nette kleine Geschäft laufen. Ein Haufen Trottel geht da drüben zu Therazanes Thron und gibt D'lom bergeweise Gold für allen möglichen Unsinn. Und dieses ganze Geld gibt er mir für diese Kristalle. Ich gehe steinreich nach Hause, alles für ein paar Felsbrocken.\n\nAber erzählt es keinem, ich will keine Konkurrenz.\n\nGlaubt Ihr, Ihr könntet später vorbeikommen und noch eine Ladung Kristalle bringen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27049] = {title = "Weicher Fels", objective = "Tötet 8 Fungusungetüme.", description = "Die Verderbnis der Rubinspanne hat nicht nachgelassen. Zerstört die Fungusungetüme, die unser Land mit ihrem Schmutz besudeln. Wenn sie sich weiterhin erheben, werden wir sie weiterhin vernichten.", progress = nil, completion = "Wenn sie einmal anfangen zu wachsen, ist es fast unmöglich, sie wieder einzustampfen. Durch Beharrlichkeit werden wir eines Tages unser Reich säubern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27050] = {title = "Der Zorn der Pilze", objective = "Zerstört 10 der neu gesprossenen Pilze in der Rubinspanne.", description = "Etwas auf der Rubinspanne ruft ständig neue, widerliche Gewächse auf dem Felsen hervor. Neue Pilze wachsen und müssen zerstört werden, bevor sie sich noch weiter verbreiten.", progress = nil, completion = "Ihr habt viel Erfahrung, wenn es darum geht, auf Dinge zu treten. Ihr würdet einen ausgezeichneten Riesen abgeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27051] = {title = "Beharrlichkeit zahlt sich aus", objective = "Nehmt einen Beutel mit Wunderwachstumsmittel von Verlok von den Verloks auf der Rubinspanne an Euch.", description = "Die Troggs haben sich nicht zerstreut, nachdem Ihr Glop getötet habt. Seine Diener haben den Wachstumsbeschleuniger gefunden, der zurückgelassen wurde, und säen die Samen der Verderbnis überall auf der Rubinspanne.\n\nBringt sie zur Strecke und findet alles, was vom Wunderwachstumsmittel von Verlok noch übrig ist. Es muss entsorgt werden.", progress = "Habt Ihr getan, worum ich Euch gebeten hatte? Wir müssen das Wachstumsmittel, das sie noch in Besitz haben, beseitigen.", completion = "Danke, &lt;Volk&gt;. Wir werden den Rest im Laufe der Zeit auch noch beseitigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27053] = {title = "Der Kessel von Gahrrons Trauerfeld", objective = "Geht zu Gahrrons Trauerfeld in den Westlichen Pestländern. Findet und besiegt den dort anwesenden Kessellord und benutzt seinen Schlüssel, um Zugang zu dem Kessel zu erlangen.", description = "Meine Analyse ist abgeschlossen! Die Verseuchung, die die Tiere hier befallen hat, ist keine Resterkrankung. Nein, sie ist etwas Neues... und ich glaube, ich weiß, was es ist.\n\nDer Kult der Verdammten unterhält einen Seuchenkessel auf einem Hof, der Gahrrons Trauerfeld heißt.\n\nDer Hof ist genau im Südosten von uns, kurz vor den Östlichen Pestländern. Ich brauche eine Probe von diesem Kessel, um meinen Verdacht zu bestätigen.\n\nBeseitigt den Kessellord, der dort zugegen ist, um an seinen Schlüssel zu gelangen. Dann werdet Ihr Zugang zu dem Kessel erhalten und könnt eine Probe für mich entnehmen.", progress = "Die Zugangsklappe zu dem Kessel ist fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel von Kessellord Rachseele löst sich auf, als er das Schloss auf der Zugangsklappe am unteren Ende der Kesselplattform berührt. Innen ist ein leises Knacken zu hören, die Zugangsklappe schwingt auf und enthüllt noch weitere, zähflüssige Gifte, die sich in dem Gefüge des Kessels befinden.\n\nDort ist ein kleiner Zapfhahn, unter den die Flasche genau passt, um eine Probe für Außenagent Kaartish in der Stätte der Heiler abzuzapfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27054] = {title = "Verzweifelte Taten", objective = "Tötet Instrukteurin Malicia und nehmt ihre Befehle für den Kult an Euch.", description = "Der Kult der Verdammten unterhält ein kleines Lager im Osten, Malicias Außenposten. Dort trainieren sie außerhalb von Scholomance. Möglicherweise haben wir ihnen schon viel zu lange erlaubt, unkontrolliert dieses Training auszuüben.\n\nWenn Kultisten wirklich diese Seuche benutzen, um die Tierwelt zu infizieren, dann muss diese Infizierung an Malicias Außenposten stattfinden.\n\nAusbilder Malicia leitet den Außenposten. Findet sie, tötet sie und findet heraus, von wem sie ihre Befehle empfängt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27055] = {title = "Krastinovs Schüler", objective = "Tötet in der Weinenden Höhle, die in den Westlichen Pestländern liegt, 2 Schüler Krastinovs, 2 Schläger aus Formfleisch, 2 Reißer aus Formfleisch und 4 unheilige Körperchen.", description = "Laut der Befehle für den Kult soll Seuche aus dem Kessel bei Gahrrons Trauerfeld für ZWEI Zwecke benutzt werden. Der erste dient zur Übung, wie man Krankheiten über die Tiere der Pestländer verbreitet, das kennt Ihr ja bereits.\n\nDer Rest der Seuche wird für düstere Experimente in die Weinende Höhle transportiert, die nördlich von Malicias Außenposen liegt. Schüler der Scholomance verwenden die Seuche, um die Toten zu reanimieren!\n\nDas muss unbedingt aufhören.", progress = nil, completion = "Ihr habt Euch selbst übertroffen, &lt;Name&gt;. Wir haben nicht nur dem Kult der Verdammten bei ihrem Kreuzzug, die Pestländer neu zu infizieren, einen empfindlichen Rückschlag versetzt, Ihr habt auch noch einen weiteren fatalen Plan aufgedeckt: Sie holen die Toten ins Leben zurück!\n\nEuer Name wird bestimmt erwähnt, wenn die Information dem Hochlord Fordring vorgetragen wird, &lt;Name&gt;. Seid Euch meiner Dankbarkeit und dem Segen des Argentumkreuzzugs gewiss.", rewards = "Malicias SzepterGürtel des AußenagentenKaartishs SchwertIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27056] = {title = "Belmonts Bericht", objective = "Bringt Belmonts Bericht zu Fürstin Sylvanas Windläufer in der Kommandozentrale der Verlassenen im Silberwald.", description = "<Belmont reicht Euch einen versiegelten Umschlag.>\n\nBringt diesen Bericht zu Fürstin Sylvanas Windläufer. Es ist meine Einschätzung der Lage im Silberwald basierend auf Eurer und Yoricks Feldarbeit.\n\nWenn wir diese rebellischen Worgen nicht aufhalten, werden sie uns überrennen! Jetzt ist es Zeit zu handeln!", progress = "Kniet nieder vor Eurer Fürstin, <Name>.", completion = "Crowley… Eine lästige Schmeißfliege. Ein Insekt, das nur darauf wartet, unter meinem Stiefel zerquetscht zu werden.\n\nEr will also die wilden Worgen im Silberwald aufwiegeln? Wir werden ihm und seinen Verbündeten die Macht der Verlassenen zeigen!\n\nAber zuerst müssen wir das Durcheinander beseitigen, das die Flotte des Kriegshäuptlings angerichtet hat. Ohne ihre Hilfe könnten wir diesen Krieg verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27057] = {title = "Rückkehr zum heimischen Hof", objective = "Bringt die Gefüllte Flasche: Gahrrons Trauerfeld zu Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", description = "Sorgfältig verschließt Ihr den Zapfhahn auf dem Bedienfeld und beobachtet, wie das faulige Sekret in die leere Flasche tropft.\n\nJetzt, da Ihr das Gift in Händen haltet, ist es Zeit zu Außenagent Kaartish in die Stätte der Heiler zurückzukehren.", progress = "Gahrrons Trauerfeld beherbergt einen hochgiftigen Seuchenkessel. Wenn wir erst eine Probe der Seuche haben, die er ausspuckt, werden wir in der Lage sein, festzustellen, ob der Kult der Verdammten wirklich hinter der Vergiftung unseres Landes steckt.", completion = "Gute Arbeit! Einen Moment bitte...\n\n&lt;Der Draenei nimmt sich einen Moment Zeit, um Eure Probe mit der Probe, die er wahrscheinlich schon vorher destilliert hat, zu vergleichen.&gt;\n\nJa, das scheint dieselbe Verderbnis zu sein, die auch die Wildtiere befallen hat. Mit diesem Wissen und Eurer Kampferfahrung könnten wir die Macht haben, das zu beenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27058] = {title = "Die falsche Folge", objective = "Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.", description = "Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.\n\nGebt die falsche Aktivierungsfolge ein und zerstört es.\n\nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.", progress = nil, completion = "Ihr habt es geschafft! Ihr habt herausgefunden, was der Schattenhammer vorhat und ihnen dann einen Strich durch die Rechnung gemacht!\n\n&lt;Mowi stellt sich auf die Zehenspitzen und gibt Euch einen Kuss auf die Wange.&gt;\n\nNun, ich bin mir sicher, dass ich hier irgendwo etwas für Euch habe.\n\n&lt;Sie kramt nach Eurer Belohnung.&gt;", rewards = "Torzerschmetternde HalsbergeAuf Euch wartet eine dieser Belohnungen:\n\nSternkratzersignetRelikt des Wegbeschreiters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27059] = {title = "Die falsche Folge", objective = "Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.", description = "Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.\n\nGebt die falsche Aktivierungsfolge ein und zerstört es.\n\nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.", progress = nil, completion = "Ihr habt es geschafft! Ausgezeichnete Arbeit, junger Herr. Ihr habt herausgefunden, was der Schattenhammer vorhat und ihnen dann einen Strich durch die Rechnung gemacht!\n\n&lt;Prüfer Rowe klopft Euch mit seiner knochigen Hand anerkennend auf den Rücken.&gt;\n\nNun, ich bin mir sicher, dass ich hier irgendwo etwas für Euch habe.\n\n&lt;Er kramt nach Eurer Belohnung.&gt;", rewards = "Torzerschmetternde HalsbergeAuf Euch wartet eine dieser Belohnungen:\n\nSternkratzersignet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27060] = {title = "Unheilige Kuh", objective = "Begleitet Anduin Wrynn und folgt der Blutspur von Wollertons Bauernhof zum Tatort. Haltet Anduin am Leben. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", description = "<Bauer Wollerton versucht, sich zusammenzureißen.>\n\nKühe? Erkundigt Ihr Euch nach dem vermissten Vieh?\n\nNormalerweise lasse ich die Kühe nördlich vom Haus grasen. Ab und zu wird eine weggezaubert. Da bleibt dann nur eine Blutspur zurück. Wer macht denn so was?\n\nIch habe Angst, dieser Spur zu folgen... etwas Krankes geht hier in Sturmwind vor!", progress = nil, completion = "Das war knapp! Ich kann gar nicht glauben, dass Ihr Euch gegen so viele gleichzeitig behauptet habt.\n\nOffenbar wurde dieser Ort für ein widerliches Einführungsritual des Schattenhammers genutzt. Sie sind auf jeden Fall in Sturmwind aktiv. Was ist das?\n\n&lt;Anduin findet ein Abzeichen, das auf dem Schrein liegt.&gt;\n\nDieses Abzeichen zeigt eine Axt und einen Hammer, die gekreuzt sind. Es sieht alt aus. Wenn wir uns weiter umsehen, finden wir vielleicht heraus, was es bedeutet...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27061] = {title = "Die Zwielichtwarte", objective = "Sprecht mit Sturmruferin Mylra an der Zwielichtwarte in Tiefenheim.", description = "Der Drache, von dem sie reden, ist Abyssion, <Name>. Es wird nicht einfach sein, das Fragment von ihm zu erhalten.\n\nTrefft Euch erneut mit Mylra. Sie lenkt ihre Einsätze von der Zwielichtwarte hier in der Nähe aus.\n\nSie wird Euch sagen, was wir als Nächstes tun werden.", progress = nil, completion = "Also müssen wir uns Abyssion stellen, um das Fragment zu bekommen? Diese Operation ist plötzlich sehr viel gefährlicher geworden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27062] = {title = "Lauernde Gefahr", objective = "Findet Hilfe bei den Hügeln der Klingenhauer.", description = "Die Stacheleber im Hügel der Klingenhauer scheinen sich mit der Geißel zusammengetan zu haben. Das sind düstere Nachrichten für uns, <Klasse>. Wir haben genug ernsthafte Probleme damit, uns mit den Grimmtotem auseinanderzusetzen, wir können nicht noch einen Angriff der Geißel überstehen. Begebt Euch in den Hügel der Klingenhauer, der im Osten liegt, und seht, ob Ihr jemanden findet, der Euch dabei hilft, sie aufzuhalten, bevor sie uns hier angreifen.", progress = nil, completion = "Ihr scheint fähig als Krieger zu sein. Vielleicht könnt Ihr mir helfen, diesem schrecklichen Elend hier ein Ende zu bereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27063] = {title = "Lauernde Gefahr", objective = "Sucht im Hügel der Klingenhauer nach Hilfe.", description = "Die Geißel ist eine Beleidigung für die Natur. Sie haben es geschafft, die Stacheleber im Hügel der Klingenhauer zu verderben. Jetzt drohen sie sich noch weiter in den Tausend Nadeln auszubreiten und - wie ich fürchte - schlussendlich auch nach Westen nach Feralas. Ihr müsst dorthin gehen und alles tun, um sie festzusetzen. Vielleicht könnt Ihr jemand in dem Gebiet dort finden, der Euch hilft? Die Winde flüstern von einer mächtigen Präsenz in der Gegend.", progress = nil, completion = "Ihr wirkt wie ein fähiger Krieger. Vielleicht könnt Ihr mir dabei helfen, den Schrecken hier zu beenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27064] = {title = "Er hält uns hin", objective = "Begleitet Anduin Wrynn in den dritten Stock des SI:7 Hauptquartiers in der Altstadt von Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", description = "<Name>, es scheint beinahe so, als ob Samuelson absichtlich unsere Zeit verschwendet. Die Dockarbeiter wissen gar nichts. Was noch wichtiger ist - Sprengstoff aus dem Hafen von Sturmwind ist verschwunden.\n\nWisst Ihr, was ich denke? Ich wette, Samuelson weiß mehr, als er zugibt. Er hat wahrscheinlich eine Spur, den Schattenhammer betreffend, und will die Lorbeeren selbst einheimsen.\n\nWir sollten uns seine Akten im SI:7 Hauptquartier mal ansehen. Bringt mich dorthin, denn ich müsste Einblick in seine Akten bekommen, um herauszufinden, was er wirklich weiß.", progress = "Es wird Zeit, dass wir Antworten finden!", completion = "Das ist WIRKLICH verdächtig, &lt;Name&gt;! Samuelson hat nicht einen Schnipsel Informationen über den Schattenhammer - es scheint beinahe so, als ob er überhaupt keine Untersuchungen über sie anstellt. Dennoch hat er hier eine Aufstellung über die fehlenden Sprengstoffe.\n\n\n\nUnd ich habe dieses merkwürdige Abzeichen mit einem Symbol darauf gefunden: Eine Axt und ein Hammer, die sich kreuzen.\n\nDas hat doch etwas zu bedeuten - aber was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27065] = {title = "Die Flotte des Kriegshäuptlings", objective = "Meldet Euch bei Admiralin Hatchet bei der Rückendeckung der Verlassenen im Silberwald.", description = "Unsere Verstärkung aus Kalimdor ist letzte Nacht eingetroffen. Drei Kanonenboote der Orcs voller Vorräte, Waffen und Soldaten. Drei Kanonenboote der Orcs, die wir an die verdammten Worgen von Blutfang verloren haben.\n\nWie kann eine ganze Orcflotte gegen einen kleine Truppe feindlicher Kämpfer verlieren, die noch nicht einmal Belagerungswaffen besitzen? Diese wichtige Frage werdet Ihr mir beantworten. Sucht Eure Sachen zusammen und meldet Euch bei der orcischen Admiralin Hatchet an der Rückendeckung der Verlassenen, südwestlich von hier.\n\nMacht diesen Orcs Beine, <Name>.\n\nIch erwarte Euren vollständigen Bericht.", progress = nil, completion = "Dieses Fiasko könnte als eine der größten Peinlichkeiten in die Geschichte der Seekriegsführung eingehen. Wie das passiert ist? Trunkenheit ist passiert. So war das.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27066] = {title = "Das richtige Wort", objective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Erprobt es 5-mal an Trainingsattrappen in Camp Narache.", description = "Während Ihr Eure Fähigkeiten ausbaut, werdet Ihr Zugang zu vielen neuen Kräften erlangen.\n\nGeht los - sammelt Erfahrungen und kommt zu mir zurück, wenn Ihr etwas Neues gelernt habt. Ihr könnt es an den Trainingsattrappen in der Nähe demonstrieren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27067] = {title = "Mondfeuer", objective = "Erreicht Stufe 3 und erlernt Mondfeuer. Dann übt diese Fähigkeit an einer Trainingsattrappe im Camp Narache.", description = "Je weiter Ihr Eure Druidenfähigkeiten entwickelt, desto mehr werdet Ihr fühlen, wie Eure Verbindung zu Mutter Erde immer tiefer wird. Dann werdet Ihr beginnen, neue Geheimnisse in der Natur zu entdecken, und lernen, neue Zauber anzuwenden.\n\nUnd nun geht und sammelt mehr Erfahrung. Kehrt zu mir zurück, wenn Ihr einen neuen Zauber gelernt habt. Dann werde ich begutachten, was Ihr gelernt habt.", progress = nil, completion = "Ihr habt Talent für Heilkünste, &lt;Name&gt;. Wo immer Euer Weg Euch hinführt, Eure Fähigkeiten als Heiler werden begehrt sein. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27068] = {title = "Häuptling Ukorz Sandskalp", objective = "Tötet Häuptling Ukorz Sandskalp.", description = "Schaut genau hin, Mann. So läuft das hier, Verrat folgt auf Verrat. Erst trickse ich Euch aus, um das Schwert zu krieg'n, und dann kommt Häuptling Ukorz und legt mich so richtig aufs Kreuz.\n\nSo is' das Leben, ja! Oder war es...\n\nNa ja, ich weiß, dass Ihr Mazoga gar nie nich' leiden konntet. Aber ich weiß, dass Ihr trotzdem macht, worum ich Euch bitte. Tötet ihn für mich. Vergießt noch mehr Blut auf dem Sand und gebt Häuptling Ukorz Sandskalp was alle Sandwüter verdien'n...einen blutigen Tod.\n\nVielleicht überlasse ich Euch was von mir, auf dem kein Fluch liegt, ja?", progress = nil, completion = "Er ist weg? Hatte er das Schwert?\n\nNee... sagt nix. Ist egal. Mazoga kümmert das nicht.\n\nIch bin dann mal weg, Mann. Die Folgen meiner Handlungen warten auf mich. Nehmt, was immer ich bei mir trage... Wo ich hingehe, brauch' ich das nich' mehr...", rewards = "Hände der KonsequenzenMazogas StiefelStab des unbekannten WegsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27069] = {title = "Der stählerne Donner", objective = "Bergt 5 Seebärenkisten.\n\nFalls Ihr unerwartet Euren orcischen Süßwassermatrosen verlieren solltet, dann sprecht mit Admiralin Hatchet, um einen neuen zu bekommen.", description = "Wir brauchen uns von der Schmach dieser Niederlage wahrscheinlich gar nicht reinzuwaschen, <Name>. Der Kriegshäuptling wird uns stattdessen alle hinrichten lassen.\n\nIch will verdammt sein, wenn wir kampflos aufgeben. Obwohl der ganze Strand von Blutfangworgen überrannt ist, könnte noch Hoffnung bestehen. Ich möchte, dass Ihr einen unserer Süßwassermatrosen zu dem Landestrand genau westlich von hier begleitet und unsere Vorräte wiederbeschafft. Kehrt zu mir zurück, wenn der Süßwassermatrose nichts mehr tragen kann.", progress = nil, completion = "In diesen Kisten befindet sich STÄHLERNER DONNER! Jetzt, da unsere Waffen wieder da sind, haben wir vielleicht eine Möglichkeit, uns zu rehabilitieren.", rewards = "Gelenkbänder des nüchternen SüßwassermatrosenBlutfangwesteStahldonnergürtelDer folgende Zauber wird auf euch gewirkt:\n\nSea Pup Trigger\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27070] = {title = "Vergebliche Mühe", objective = "Beschafft Euch die Tiara der Tiefen und Gahz'rillas elektrisierte Schuppe.", description = "Ich hörte, dass ein Troll hier drin - Hydromantin Velratha hieß sie, glaube ich - in den Besitz eines sehr seltenen, wunderschönen und mächtigen Schmuckstücks gelangt ist - der Tiara der Tiefen. Sie benutzt sie, um den mächtigen Halbgott Gahz'rilla zu kontrollieren, dessen Schuppen angeblich vor Energie knistern. Wisst Ihr, was das bedeutet, <Volk>?\n\nIch brauche sie! Tötet Velratha, nehmt ihr die Tiara der Tiefen ab und tötet Gahz'rilla für eine seiner Schuppen. Bringt mir alles schleunigst her! Ich werde Euch fürstlich belohnen...", progress = "Habt Ihr, was ich brauche?", completion = "Ausgezeichnet! Die Tiara verschafft mir die absolute Kontrolle über das Wasser hier und die elektrisierte Schuppe wird alle Maschinen antreiben, die ich zu meinem Vorteil nutze.\n\nIhr macht mich zu einem sehr reichen und mächtigen Goblin! Ihr könnt das hier haben, das ist nichts im Vergleich zu dem, was ich bald haben werde.", rewards = "Bilgenritzels ArmbänderGürtel der TiefeElektrifizierte GamaschenSchulterstücke von Zul'FarrakIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27071] = {title = "Zorn der Sandwüter", objective = "Tötet Theka den Märtyrer, Hexendoktor Zum'rah, Antu'sul und Ruuzlu.", description = "Die Sandwüter sind ein widerstandsfähiger Stamm. Sie hab'n Sandstürme überlebt und über die Jahre hinweg noch ganz andere Sachen, die inzwischen längst von Sand bedeckt sind. Es wäre dumm zu glauben, dass die einzige Macht hier die Trolle sind. Wir hab'n Skarabäen gezähmt, Sul'lithuz gezüchtet und unsere Toten wiederaufersteh'n lassen, damit sie bis in alle Ewigkeit als Zombies kämpfen.\n\nRuuzlu, die rechte Hand von Häuptling Ukorz Sandskalp, hat vor, mit ihrer Hilfe Tanaris für die Sandwüter zurückzuerobern. Ihr solltet die Trolle, die dafür verantwortlich sind, töt'n, wenn Ihr leben wollt, Mann.", progress = nil, completion = "Ihr habt sie getötet? Alle? Und seid lebendig zurückgekomm'n?\n\nDann nehmt von mir, was Ihr wollt. Es ist überwiegend frei von Flüchen, Mazoga verspricht es.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27072] = {title = "Die Alte Kaserne", objective = "Geht zur Alten Kaserne und tötet 6 wahnsinnige Kultisten, dann findet Jack Bauden.", description = "Das Symbol auf diesen Abzeichen ist mir schon aufgefallen, bevor Todesschwinge die Stadt angegriffen hat. Die Soldaten in der Alten Kaserne, die im Westen der Stadt den Hafen überblickt, haben sie getragen.\n\nIhr hättet kaum zu einer besseren Zeit hier auftauchen können. Einer meiner Topagenten, Jack Bauden, ist in meinem Namen mit der Infiltration des Schattenhammers beschäftigt. Er wird seit gestern Nacht vermisst. Wenn Anduin und Ihr Recht habt, dann haben sich die Kultisten in der Alten Kaserne verkrochen. Die Zeit drängt! Greift die Alte Kaserne an, schaltet die Kultisten aus und rettet Jack Bauden.", progress = "<Bauden ist ohnmächtig. Die Gegend wimmelt noch immer vor Kultisten. Ihr solltet sie beseitigen, bevor Ihr Untersuchungen anstellt.>", completion = "&lt;Ihr ohrfeigt Bauden bis er zu sich kommt.&gt;\n\n&lt;Klasse&gt;? Was macht Ihr denn hier?\n\nIch bin SI:7-Agent Jack Bauden. Heute ist der längste Tag meines Lebens.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27073] = {title = "Macht ihnen die Hölle heiß!", objective = "Tötet 10 Blutfangplünderer.", description = "Die Goblins sind schuld, <Volk>!\n\n<hicks!>\n\nWisst Ihr, wir sind vom Bilgewasserhafen aus über Azshara zum Silberwald aufgebrochen. Ein riesiger Fehler! In unserem gesamten Imperium habe ich noch nie einen sündigeren und schmächlicheren Haufen erlebt! Diese verdammten Goblins haben uns zu jedem möglichen Laster verführt und uns mit Fässern voller Bier aufs Meer geschickt!\n\n<hicks!>\n\nDie Scham, die wir dafür empfinden, sitzt tiefer als jede Narbe. Unsere Ehre muss wiederhergestellt werden! Tötet die Blutfangworgen, die uns aufgelauert haben. Sie plündern gerade das Wrack im Südwesten.", progress = nil, completion = "Sieht aus, als hättet Ihr diese Worgen so richtig vermöbelt und die Scham von uns genommen. Vielleicht hören die Seebären jetzt auf, zu saufen.\n\nAch, wem mache ich was vor.\n\nHa!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27074] = {title = "Bekämpft den Hammer", objective = "Sprecht in Loch Modan in der Nähe der Festung Mo'grosh mit Ashlan Schmunzelstein.", description = "Ihr habt das Unmögliche möglich gemacht! Ich habe die Nase voll davon, hier herumzuschmollen. Es wird Zeit, sich aufzugnomen.\n\nIch muss meinen Vater finden. Aber Ihr! Befasst Euch nicht länger mit mir. Ihr müsst weiter gegen diese Kultisten kämpfen.\n\nGeht und sprecht mit Ashlan Schmunzelstein im Osten. Er versucht, den Schattenhammer aufzuhalten, aber er hat niemanden, der ihm hilft. Ihr seid seine einzige Hoffnung!\n\nGebt nicht auf, <Name>. Ich werde es auch nicht tun.", progress = nil, completion = "Habt Ihr dem Zwielichtlager in der Mitte des Sees einen Schlag versetzt? Nicht schlecht, Junge!\n\nWenn Ihr den Kampf zu ihnen nach Hause tragen wollt, kann ich Euch die Gelegenheit dazu geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27075] = {title = "Diener von Cho'gall", objective = "Tötet 7 Oger der Mo'grosh in der Festung Mo'grosh.", description = "Der Schattenhammer war zunächst ein Klan der wilden Horde. Ihr Anführer - Cho'gall - formte aus seiner Bande Oger nach und nach einen tödlichen Kult, der jeden willkommen hieß, der verrückt genug war, sich das Ende allen Lebens zu wünschen. Wie Ihr seht, gibt es immer noch viele Oger unter ihnen. Sie sind verwirrt, fanatisch und immer noch so stark wie früher.\n\nDiese primitiven Monster besitzen die Frechheit, hierherzukommen und ihren Schmutz über unser Land auszubreiten. Je mehr Ihr tötet, desto besser wird Loch Modan dastehen, <Name>.", progress = nil, completion = "Es mag zwar finster aussehen, aber wir werden mit Eurer Hilfe gewinnen, &lt;Name&gt;. Sie werden die Zwerge nicht unterdrückt halten können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27076] = {title = "Einbruch mit schwerem Werkzeug", objective = "Befreit Weegli Lunte und tötet Nekrum den Ausweider und Schattenpriester Sezz'ziz.", description = "Ein guter Kumpel von mir, Weegli Lunte, hat sich mit Unteroffizier Bly und seiner Gruppe Gesetzloser zusammengetan, um in Zul'Farrak einzumarschieren und das legendäre Sul'thraze zu erbeuten. Natürlich haben sie den Stamm der Sandwüter unterschätzt und jetzt sind sie alle festgesetzt und warten auf ihre Hinrichtung, um den Halbgott Gahz'rilla zufriedenzustellen.\n\nWenn Ihr Weegli befreit, wird er Euch helfen, den Weg zu Ukorzs Privatgemächern freizusprengen, wo er mindestens einen Teil der Klinge aufbewahrt.\n\nTötet Nekrum den Ausweider und Schattenpriester Sezz'ziz, die ihn gefangen genommen haben, als Rache...Ich werde Euch belohnen.", progress = nil, completion = "Wow! Ich wusste, ich kann auf Euch zählen! Hier ist etwas für Eure Unannehmlichkeiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27077] = {title = "Ans Chaos klammern", objective = "Reißt 10 entstehende Elementiumstacheln aus dem Boden der Festung Mo'grosh.", description = "Die Kultisten vom Schattenhammer benutzen ihre Kräfte, um Elementiummetall aus den Tiefen der Erde zu gewinnen. Sie locken es als verdrehte Stacheln heraus, um damit ihre Gebäude zu formen, die in dem entweihten Boden verwurzelt sind.\n\nDie Oger hier scheinen dabei kräftig mitzumischen und wir müssen zuschlagen, solange sie es noch in Form drehen.\n\nReißt die Stacheln aus dem Boden, solange sie noch biegsam sind und bringt sie zu mir. Wir werden diesen Hundesöhnen nicht einen Zoll unseres Landes überlassen.", progress = "Habt Ihr die Stacheln herausgerissen?", completion = "Schade, dass diese halbgestalteten Dinger zu brüchig und krumm sind, als dass wir sie als Waffen benutzen könnten. Aber nur dank Euch haben wir überhaupt die Chance, sie herauszuziehen, bevor sie sich verhärten. Deshalb werde ich mich nicht beschweren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27078] = {title = "Gor'kresh", objective = "Besiegt Gor'kresh.", description = "Der Oger, der über diese primitiven Narren wachen soll, heißt Gor'kresh. Er ist groß genug, um selbst diese Schläger herumzukommandieren - und obendrein ist er gerissen. Setzt niemals voraus, dass ein Oger dumm ist, denn dann erwischt er Euch.\n\nWenn Ihr ihn beseitigt, dann werden wir dem Schattenhammer schon zeigen, dass Loch Modan kein Sprungbrett für sie ist. Stellt Euch Gor'kresh entgegen und treibt diese Narren zurück in das Hochland!", progress = nil, completion = "Ihr habt es geschafft! Auch, wenn wir den Kult nicht komplett aufgehalten haben, so haben wir ihnen doch gezeigt, dass wir keine leichte Beute sind und haben ihnen eine Beule verpasst, um das zu beweisen.\n\nNehmt dies zum Dank und versucht, nicht zu erröten, wenn jemand in Thelsamar Euch $g\"Held\":\"Heldin\" nennt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27082] = {title = "Unfaire Methoden", objective = "Beschafft 8 verseuchte Organe von ergrauten Riesenbären und tollwütigen Worgs.", description = "Habt Ihr die großen, schwerfälligen Ettins gesehen, die durch die Wälder streifen? Die verfluchten Dinger kamen aus Gilneas. Jetzt vagabundieren sie durch das Land und suchen ihre nächste, saftige Mahlzeit. Wir haben es geschafft, einige von ihnen zu unterwerfen und sie nutzbar zu machen, um unsere Wagen zu ziehen, aber die anderen... nun, sie müssen getötet werden.\n\nLeider können wir keine Soldaten erübrigen, um das zu erledigen. Da kommt Ihr ins Spiel, <Klasse>.\n\nIch habe einen Plan, aber dafür brauchen wir noch Materialien. Geht hinaus in die Wälder, die diese Basis umgeben und beschafft die Organe kranker Tiere.", progress = "Wir sind die Verlassenen! So machen wir das, <Klasse>.", completion = "Ausgezeichnet! Und jetzt müssen wir das \"Mahl\" vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27083] = {title = "Die Schlacht geht weiter!", objective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Koltira Todesweber.", description = "Es gibt Nachrichten aus Andorhal, <Name>. Die Schlacht hat wieder angefangen.\n\nUnter den Streitkräften der Verlassenen ist es wohl bekannt geworden, dass Ihr Euch in der ersten Schlacht um Andorhal als einer der Helden hervorgetan habt. Koltira verlangt umgehend nach Eurer Anwesenheit.", progress = nil, completion = "Thassarian und die Menschen haben ihren Zug gemacht. Ich dachte, ich hätte eine Abmachung mit Thassarian... aber das muss dann wohl reichen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27084] = {title = "Die Bauernmiliz", objective = "Benutzt das ebenhölzerne Gargoylehalsband auf 6 Provinzmilizen in Andorhal.", description = "Der Kampf begann, als sie uns von hinten angriffen. Ich habe kurz nicht aufgepasst und eine Gruppe schlecht bewaffneter Bauern und Milizen stieß vom Trostlosen Feld in unsere Flanke vor.\n\nSie mögen schwach sein, aber wenn sie so ungehindert angreifen, besteht die Gefahr, dass sie uns allein durch ihre zahlenmäßige Überlegenheit überwältigen.\n\nLindsays domestizierte Monstrositäten können sich um den Nahkampf kümmern. Nehmt dieses Halsband, bleibt hinten und benutzt es, um meinen schwarzen Gargoyle auf diese Bauern zu hetzen.", progress = nil, completion = "Das hat nur ein winziges Loch in ihre Reihen gerissen...aber der Anblick ihrer Freunde, die vom Himmel fielen, hat ihre Entschlossenheit ins Wanken gebracht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27085] = {title = "Die Truppen unterstützen", objective = "Tötet 15 Verteidiger von Andorhal.", description = "Auch wenn diese Bauern uns zu überrennen drohen, dürfen wir die Hauptstreitmacht der Allianz nicht vergessen.\n\nReist in den Westen nach Andorhal und tötet die menschlichen Soldaten, die gegen unsere Todeswachen kämpfen. Wir können alle Hilfe gebrauchen, die wir bekommen können.", progress = nil, completion = "Ihr habt gut gekämpft, &lt;Name&gt;. Ich wünschte, ich hätte Eure Fähigkeiten ... und Euren Mut.", rewards = "Armschienen des NeidsGürtel der UnerschrockenenHandschuhe des FähigenAuf Euch wartet eine dieser Belohnungen:\n\nTodeswachenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27086] = {title = "Asche zu Asche", objective = "Tötet 3 Streitkräftekommandanten von Andorhal.", description = "Im Westen, tief in dem von der Allianz gehaltenen Andorhal, findet Ihr ihre Kommandanten. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.\n\nJagt und tötet diese Kommandanten, <Name>. Die Menschen werden machtlos sein.", progress = nil, completion = "Gut gemacht. Jetzt, da sie ausgeschaltet wurden, habe ich keine Ausreden mehr.\n\nBald muss ich mich Thassarian im Kampf stellen, für Ehre und für Andorhal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27087] = {title = "Die Entlarvung der Lindsay Rabensonn", objective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Lindsay Rabensonn.", description = "Man hat mir gesagt, dass dieses nutzlose Weib, Lindsay Rabensonn, hier wäre, um mich in diesem Kampf zu unterstützen. Bisher hat sie noch nichts anderes getan, als im Keller des Haupthauses hinter mir dumpf vor sich hin zu brüten. Ist wohl auch besser so. Sie war eine Ablenkung.\n\nDennoch, ich kann und werde keine Befehlsverweigerung dulden. Findet sie und bringt sie zu mir.", progress = nil, completion = "Ihr werdet mich nirgendwohin mitnehmen, &lt;Name&gt;.\n\nWährend Koltira und sein Kumpan Thassarian herumstolzieren, habe ich vor, diese Schlacht zu gewinnen. Koltira wird für seine Schwäche bezahlen.\n\nGlaubt Ihr nicht? Na gut, dann weihe ich Euch in mein kleines Geheimnis ein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27088] = {title = "Es ist nur giftig, wenn man es einnimmt", objective = "Benutzt das mutierte Buschhuhn, um den Waldettin zu töten.", description = "Nehmt diesen Käfig, <Klasse>. Darin befindet sich eins meiner mutierten Buschhühner, mit einigen leichten Veränderungen. In dem Hintern des Buschhuhns befindet sich eine Dynamitstange, die mit Schleim von den verseuchten Organen, die Ihr mir gebracht habt, versetzt ist.\n\nBringt den Käfig in den Wald und findet den Waldettin, der dort herumläuft. Lasst das Huhn frei und lehnt Euch zurück, während dieses Meisterstück seine Arbeit tut. Die folgende Explosion dürfte ausreichen, um den Ettin zu töten oder ihn so sehr zu schwächen, dass Ihr die Möglichkeit bekommt, ihn zu erlegen.", progress = nil, completion = "&lt;Apotheker Wurmschmutz lacht wie irre.&gt;\n\nGab es daran jemals Zweifel? Ein Ettin kann der Wissenschaft nicht das Wasser reichen!", rewards = "BuschhuhnferninjektorSuppositorienstopperHähnchenfüllungsstopferIhr bekommt:\n\nBärensteaks"}
MultiLanguageQuestData['de'][27089] = {title = "Versteckter Trumpf", objective = "Tötet 5 verängstigte Provinzmilizangehörige mit der bezauberten Val'kyr an Eurer Seite. Dann benutzt Eure Fähigkeit 'Ruf zu den Waffen' und macht aus ihnen Gardisten der Verlassenen. Dann findet Thassarian im Westteil von Andorhal.", description = "Ihr habt ja keine Ahnung, wie schwer es war, die Tarnung aufrecht zu halten, während ich zusah, wie Koltira diesen Krieg entgleiten ließ. Es ist so weit gekommen, dass diese lästigen Bauern uns zu überwältigen drohen. Und all das nur, weil er sich geweigert hat, einen Freund zu töten.\n\nNehmt noch einmal meine Val'kyr, <Name>. Tötet die Bauern mit ihr an Eurer Seite, macht sie zu Verlassenen und lasst sie ausrücken. Dann geht mit einer Gruppe von ihnen in den von der Allianz gehaltenen Westteil von Andorhal und bringt diesen Todesritter Thassarian zur Strecke.\n\nWir werden diesen Krieg doch noch gewinnen.", progress = nil, completion = "Dies ist die Leiche von Lurid, Thassarians getreuem Ritter. Da Thassarian nirgendwo zu finden ist, scheint es, als ob die Streitkräfte der Allianz sich zurückgezogen haben.\n\nDie Verlassenen haben die Schlacht für Andorhal gewonnen.", rewards = "Schulterwickel des BezaubertenLurids ArmschienenMilizpikeAuf Euch wartet eine dieser Belohnungen:\n\nRing der Asse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27090] = {title = "Andorhal, für Immer und Ewig", objective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Fürstin Sylvanas Windläufer.", description = "Sylvanas wird alles über die Abreise von Thassarian aus Andorhal wissen wollen. Ihr beschließt, zu der Seite der Stadt, die von den Verlassenen gehalten wird, zurückzukehren.", progress = nil, completion = "Seht Ihr? Ich brauchte nur ein wenig Hilfe von den Val'kyr. Diese Wesen sind weitaus hilfreicher, als ich ursprünglich dachte.\n\nAber nun zu anderen Dingen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27091] = {title = "Sturmangriff!", objective = "Erreicht Stufe 3 und erlernt Sturmangriff. Findet eine Trainingsattrappe außerhalb des Sonnenturms und übt diese Fähigkeit.", description = "Gut. Das war ein vielversprechender Anfang. Vor Euch liegt noch ein langer Weg. Aber je weiter ihr voranschreitet, desto mehr Dinge lernt Ihr, von denen Ihr zuvor nicht einmal zu träumen gewagt hättet.\n\nSammelt noch etwas mehr Erfahrung und erlernt eine neue Technik. Sucht Euch dann eine Trainingsattrappe und demonstriert Eure neue Fähigkeit.", progress = nil, completion = "Ich glaube, Ihr habt die Grundzüge des Sturmangriffs verstanden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27092] = {title = "Kataklysmus in den Katakomben", objective = "Betretet die Kathedrale des Lichts und steigt hinab in die Katakomben darunter. Tötet den Schwarzen Bischof und entschärft den Sprengstoffhaufen in der Nähe.", description = "Sorgt Euch nicht um mich, <Klasse>. Ich habe den Plan des Schattenhammers aufgedeckt. Sie haben im Hafen von Sturmwind eintreffenden Sprengstoff gesammelt und aufgeschichtet. Irgendwie haben sie sich Zutritt zu den Katakomben unter der Kathedrale des Lichts verschafft. Ich hörte von jemandem namens \"Der Schwarze Bischof\".\n\nWir haben nicht genug Zeit, um die Wache zu warnen. Es bleiben Euch nur noch Minuten, um in die Katakomben vorzudringen und die Bombe zu entschärfen! Geht! Schnell! Oder TAUSENDE MENSCHEN werden STERBEN!", progress = "<Dunkle magische Runen bedecken die Oberfläche des Sprengstoffs und pulsieren mit zunehmender Intensität...>\n\nIhr müsst den Schwarzen Bischof finden!", completion = "&lt;3... 2 ... 1 ...&gt;\n\n&lt;Ihr feuchtet Eure Finger an und erstickt die Lunte. Die Kathedrale ist gerettet!&gt;\n\n&lt;Unter den Sprengstofffässern findet Ihr einen Stapel Notizen und Papiere. Offenbar haben die Kultisten versucht, die zurückgelassenen Beweise zu zerstören.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27093] = {title = "In der Dunkelheit verlaufen", objective = "Rettet 6 orcische Seebären aus dem Huschdunkel.", description = "Einige würden sagen, dass wir Glück haben, am Leben zu sein. Diese Leute wären Idioten. Wenn wir gestorben wären, müssten wir uns nicht dem Zorn des Kriegshäuptlings stellen. Aber nun, was geschehen ist, ist geschehen. Jetzt müssen wir versuchen, unsere verlorene Ehre wiederherzustellen.\n\nDas dritte Schiff in unserer Flotte ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Diejenigen, die es an Land geschafft haben, wurden von riesigen Spinnen der Gegend umzingelt und in Spinnweben gehüllt.\n\nWenn es dort Überlebende gibt, müssen wir sie befreien! Geht, <Name>. Auf ins Huschdunkel!", progress = nil, completion = "Lok'tar, &lt;Name&gt;. Sobald die Wirkung des Biers nachlässt, werden meine Orcs bereit sein!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27094] = {title = "Tiefer in die Dunkelheit", objective = "Tötet die Netzhuschermatriarchin.", description = "Die Netzhuschermatriarchin ist in der Nähe! Ihr könnt der Bedrohung durch die Netzhuscher ein Ende bereiten, indem Ihr sie erlegt!\n\nFindet sie am Ende der Höhle im Huschdunkel und vernichtet sie!", progress = nil, completion = "Ihr habt unsere Orcs gerettet und die Netzhuschermatriarchin getötet? Wir schulden Euch großen Dank. Ihr habt uns alle vor der sicheren Hinrichtung bewahrt, &lt;Name&gt;. Ich bin sicher, dass wir diese betrunkenen Idioten jetzt wecken können.", rewards = "Fingerlose Handschuhe der KrabbelnetzspinnenSäuferstilarmschienenKniehosen der RückendeckungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27095] = {title = "Die Netzhuscherbedrohung", objective = "Tötet 12 Netzhuscherspinnen.", description = "Rache ist allumfassend, <Name>! Unser drittes Schiff ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Die Männer, die es von dem Schiff herunter geschafft haben, wurden entweder gefangen genommen, oder von den Netzhuscherspinnen der Region getötet. Dafür müssen die Spinnen sterben! ALLE!\n\nBegebt Euch zum Huschdunkel und zermalmt diese Spinnen!\n\nHaltet Ausschau nach ihrer Matriarchin. Wenn wir sie finden, können wir diese Bedrohung vielleicht beenden!", progress = nil, completion = "Die Wurzel dieses Übels muss gefunden und zerstört werden! Die Netzhuschermatriarchin muss in der Nähe sein. Zweifellos verbirgt sie sich in der nahegelegenen Höhle!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27096] = {title = "Alles klar bei den Orcs", objective = "Liefert das Empfehlungsschreiben des Admirals bei Fürstin Sylvanas Windläufer bei der Kommandozentrale der Verlassenen im Silberwald ab.", description = "<Admiralin Hatchet übergibt Euch einen Umschlag, der mit dem Zeichen der Horde versiegelt ist.>\n\nDies ist Euer Empfehlungsschreiben. Das ist das Mindeste, was ich unter diesen Umständen für Euch tun kann.\n\nKehrt zu Fürstin Sylvanas Windläufer mit diesem Brief zurück und informiert sie über unseren Status. Lasst sie wissen, dass wir nur auf ihren Befehl warten, um loszumarschieren.\n\nLebt wohl, <Name>. Ihr seid <ein ausgezeichneter Soldat/eine ausgezeichnete Soldatin>.\n\nNordosten, <mein Junge/Ma'am>. Auf zur Kommandozentrale der Verlassenen!", progress = "Und die Orcs?", completion = "&lt;Sylvanas zieht eine Augenbraue hoch.&gt;\n\nAlso ist bei den Orcs alles in Ordnung?\n\n&lt;Sylvanas liest das Empfehlungsschreiben.&gt;\n\nIhre Vorräte zurückgeholt? Ein Dutzend Worgen getötet? Einen Ettin zur Strecke gebracht? Ihre Soldaten befreit und die Netzhuschermatriarchin vernichtet?\n\nIch sage das ja selten, aber ich bin beeindruckt. Vielleicht entsprechen Eure Fähigkeiten tatsächlich Euren Ambitionen. Wir werden sehen, ich werde Euch auf die Probe stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27097] = {title = "Erhebt Euch, Verlassene", objective = "Erweckt 15 Verlassene, indem Ihr Menschen auf der Insel Fenris tötet.", description = "Die Insel Fenris ragt trotzig im Herzen des Lordameresees auf - eine grausame Erinnerung an eine längst vergangene Zeit.\n\nObwohl sie nicht länger von Gnollgezücht befallen ist, hat sich eine neue Bedrohung aufgetan. Menschenflüchtlinge, die aus ihren Behausungen im Hügelland vertrieben wurden, sind in der Hoffnung auf die Insel Fenris geflohen, einer Niederlage durch uns zu entgehen. Da irren sie sich gewaltig.\n\nNehmt Agatha mit Euch zur Insel Fenris und tötet alle Menschen. Sie wird die Gefallenen als Verlassene wiedererwecken und so unsere Streitkräfte verstärken.\n\nEnttäuscht mich nicht, <Name>.", progress = nil, completion = "Ich sehe alles, &lt;Name&gt;. Durch Agatha entgeht mir nichts.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27098] = {title = "Lordaeron", objective = "Begleitet Fürstin Sylvanas Windläufer zum Grabmal im Silberwald.", description = "Kommt mit mir zum Grabmal, <Name>. Ich möchte vieles mit Euch besprechen. Es ist unabdingbar, dass Ihr die Geschichte von Lordaeron und die Zwangslage der Verlassenen versteht.", progress = nil, completion = "Versteht Ihr jetzt die Wichtigkeit unserer Mission hier? Crowley und seine Hunde der Allianz müssen aufgehalten werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27099] = {title = "Kein Entkommen", objective = "Findet die Anführer der Flüchtlinge in Burg Fenris.", description = "Ihr müsst gegen ihre Anführer losschlagen, <Name>. Ihr werdet sie in der alten Burg versteckt finden. Kämpft Euch in die Burg durch und findet die Starrköpfe! Verwandelt sie für Eure Königin!\n\nNiemand entzieht sich dem mächtigen Griff der Verlassenen!", progress = nil, completion = "Anscheinend muss man Crowley ernster nehmen, als ich gedacht habe. Dennoch, er ist ein Mensch - Fleisch und Blut - voller Geheimnisse. Geheimnisse, die ich alle kenne...\n\nIhr habt mir gute Dienste erwiesen, &lt;Name&gt;. Ich könnte jemand mit Euren Fähigkeiten am Grabmal gebrauchen. Ich habe einen Plan, um mit Crowley und seinen Aufrührern endgültig fertigzuwerden. Werdet Ihr mir auch weiterhin zur Seite stehen?", rewards = "Stab des AngstgegnersSchwert des AufstandesAuf Euch wartet eine dieser Belohnungen:\n\nFleisch und Knochen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27100] = {title = "Zwielichtige Forschungen", objective = "Findet in den Oberen Silbermarschen 4 Zwielichtforschungsnotizen über Quecksilberschlamm.", description = "Das Buch, das Ihr gefunden habt, scheint irgendeine Forschung zu beschreiben, die ein Mitglied des Schattenhammers durchgeführt hat.\n\nEs hat irgendwas mit Schlamm zu tun, aber es fehlen mehrere Seiten.\n\nVielleicht könntet Ihr zusätzliche Notizen finden, damit das Ganze einen Sinn ergibt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27101] = {title = "Maziels Enthüllung", objective = "Geht zu den Unteren Silbermarschen in Tiefenheim und findet Maziels Tagebuch.", description = "Die Notizen führen Maziels Forschungsgeschwafel über die Zusammensetzung von Quecksilber und Quecksilberschlamm fort.\n\nOffenbar hat er eine wichtige Entdeckung gemacht. Er erwähnt, dass er sein Tagebuch in den Unteren Silbermarschen gen Südwesten versteckt hat.", progress = nil, completion = "Maziels Tagebuch scheint vom Quecksilber nicht beschädigt worden zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27102] = {title = "Maziels Aufstieg", objective = "Tötet Maziel in der Silberlichthöhle in Tiefenheim.", description = "Maziels Tagebuch enthält Aufzeichnungen über ein Aufstiegsritual, das seinen Körper in pures Quecksilber verwandeln würde.\n\nDas Ritual soll in einer Höhle in der Nähe der Unteren Silbermarschen stattfinden, wo Maziel sich von Quecksilberschlamm ernähren will, bis er die volle Stärke erreicht hat.\n\nVielleicht ist es noch nicht zu spät, seinem Wahnsinn Einhalt zu gebieten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "QuecksilbertreterKräuselnder SchlammQuecksilberarmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27103] = {title = "Die Splitter der Teufelsranke", objective = "Benutzt das Reliquiar der Reinheit, um einen Teufelsrankensplitter einzufangen.", description = "Der Satyr Alzzin der Wildformer übt seine verdorbene Herrschaft über diesen Teil von Eldre'Thalas aus. Die korrumpierte Frucht des Gedeihens - die Teufelsranke - sollte sich in Alzzins Nähe befinden. Sie könnte der Schlüssel sein, um diesen uralten Ort zu reinigen.\n\nWenn der große Satyr fällt, versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen. Versiegelt sie dann in diesem Reliquiar der Reinheit und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", progress = "Mit dem Versiegelten Reliquiar der Reinheit in unserem Besitz wird es nicht nur möglich sein, die Bedrohung der Verderbnis von der Welt zu entfernen, sondern sie auch unter unseren umsichtigen Augen zu studieren. Vielleicht können wir sogar neue Möglichkeiten finden, um das Makel der Verderbnis, das Azeroth bedroht, zu bekämpfen.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Klasse&gt;, und deshalb stehe ich für immer in Eurer Schuld. Obwohl der Krieg noch lange nicht vorüber ist, wurde eine große Schlacht gegen die, die unseren Untergang herbeiführen wollen, gewonnen.\n\nBitte nehmt dies als Zeichen meiner endlosen Dankbarkeit. Wenn wir jemals Düsterbruch reinigen, wisset, das Ihr als Held hier immer willkommen sein werdet. Ich danke Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27104] = {title = "Alzzin der Wildformer", objective = "Tötet Zevrim Dornhuf und Alzzin den Wildformer.", description = "Das Monster, das für die Zerstörung, die Ihr vor Euch seht, verantwortlich ist, heißt Alzzin der Wildformer. Um an ihn heranzukommen, müsst Ihr allerdings Zevrim Dornhuf töten, den Satyr, der den immer noch edlen alten Eisenborke der Große in seinen Klauen hält.\n\nSobald Eisenborke frei ist, wird er Euch helfen, Alzzins Herrschaftsgebiet zu betreten. Geht hinein und tötet ihn, ohne Gnade zu zeigen, denn es gibt keine andere Möglichkeit.", progress = nil, completion = "Ah, sehr gut gemacht. Ihr habt heute einen alten Geist sehr glücklich gemacht. Ihr verdient angemessenen Dank für die Risiken, die Ihr auf Euch genommen habt.", rewards = "Mantel aus WucherborkenblätternWeste aus WucherborkenrindeWucherborkenbogenWucherborkenschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27105] = {title = "Ein ungebetener Gast", objective = "Findet die Hydrobrutessenz.", description = "Ihr werdet sehen, dass Düsterbruch voller Natur- und Arkanelementaren ist. Irgendwie hat ein Wasserelementar seinen Weg in diese Gegend gefunden. Bitte beschafft Euch seine Essenz und bringt sie zu mir. Ich bin neugierig, wie es hierhergekommen ist und welche Pläne es in Bezug auf die natürlich vorkommenden Elementare von Eldre'Thalas hat.", progress = "Habt Ihr die Essenz bei Euch oder war die Aufgabe zu schwierig?", completion = "Es ist äußerst besorgniserregend, dass ein Wasserelementar hier war - insbesondere so ein mächtiger. Nehmt dies als Dank für Eure Bemühungen. Ich muss diese Essenz untersuchen, ob sie etwas Wissenswertes verbirgt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27106] = {title = "Entlarvung eines Schurken", objective = "Enttarnt und tötet Major Samuelson im Thronraum von Burg Sturmwind.", description = "<Ihr findet eine vollständige Liste aller Kultisten des Schattenhammers in Sturmwind.>\n\n<Was noch wichtiger ist, Ihr entdeckt einen Brief von Major Samuelson an seine Komplizen, der den ganzen Plan darlegt. Der Prinz hatte Recht: Samuelson ist der wahre Verbrecher hier, der seine Verbindungen als Kommandant der Stadtwache dazu nutzt, die Aktivitäten des Kults zu verschleiern.>\n\n<Es wird Zeit, nach Burg Sturmwind zurückzukehren und Samuelson zur Rechenschaft zu ziehen!>", progress = "Ihr habt Beweise, die Samuelson belasten? Schauen wir mal, was er dazu zu sagen hat!", completion = "Samuelson - vom Schattenhammer bestochen? Das muss schon seit Jahren so gehen. Genau hier in meiner Burg!\n\nIch bin sehr dankbar, dass Ihr und mein Sohn dieser Sache auf den Grund gegangen seid, bevor meine Stadt Schaden nehmen konnte. Ich habe wohl unterschätzt, wie erwachsen Anduin bereits geworden ist - seine Beherrschung des heiligen Lichts hat mir gerade das Leben gerettet...wenn nicht sogar das ganze Königreich.\n\nWas Euch angeht - Worte vermögen Euer Heldentum am heutigen Tag nicht zu beschreiben. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Schild des WahrheitsverkündersSchulterplatten des DetektivsVerderbnissuchender BrustschutzTreter der OffenbarungGürtel des WahrheitssuchersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27107] = {title = "Pusillin der Dieb", objective = "Überredet Pusillin, das Buch der Zauberformeln herauszugeben.", description = "Ich nur kurz Nickerchen vorhin gemacht und blöder schneller Wichtel hat gestohlen Buch! Dagg'thol braucht Buch, um Befehle zu befolgen und Meister braucht Buch zum Erobern! Bah!\n\nIhr <Volk> helft mir, Buch von Wichtel zurückzuholen und ich gebe etwas Glänzendes. Geht, Wichtel ist da links! TÖTEN!!!", progress = "<Volk> hat Buch?", completion = "Jetzt sehen, wie Meister Buch benutzt und Bäume töten und dumme Ziegenmänner! JA!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27108] = {title = "Lethtendris' Netz", objective = "Beschafft Lethtendris' Netz.", description = "Blutelf Lethtendris hat Netz zum Fangen von Magie hier. Sie benutzt selbst, aber Meister will benutzen um der ganzen Welt gut zu tun. Helft, Netz von dummer Elfe zu holen und Dagg'thol wird Euch belohnen. Dann Ihr seht, wie Meister es viel besser benutzt!", progress = "<Name>, habt Ihr Netz von dummer Elfe?", completion = "Das Netz hat viel Magie! Meister wird jetzt sehr zufrieden sein!\n\nUnd Ihr macht Dagg'thol zufrieden, &lt;Volk&gt;. Nehmt dies, damit Ihr wisst, wie glücklich Ihr macht Dagg'thol.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27109] = {title = "Windschiefe Verteidiger", objective = "Tötet Tendris Wucherborke.", description = "Eisenborke und Wucherborke waren einst die mächtigen Beschützer von Eldre'Thalas. Schaut, was aus ihnen geworden ist! Ihr Schicksal liegt letztendlich in meinen Händen und denen der anderen Hochgeborenen. Wir sind mit unserer Macht unachtsam umgegangen, <Volk>.\n\nAber Ihr, Ihr könnt das Unrecht wieder ungeschehen machen! Geht hinaus und bettet Tendris Wucherborke zur Ruhe. Er war der mächtigste und letzte Verteidiger dieses Gebiets und er verdient es, dass sein Geist freigelassen wird. Seid vorsichtig, denn wenn Ihr Euch nicht der Beschützer von Eisenborke entledigt, bevor Ihr Tendris angreift, wird er sie zu Hilfe rufen.", progress = nil, completion = "Eure Arbeit hier war ehrenwert. Grämt Euch nicht, denn Tendris Seele hat danach geweint, sich zur Ruhe begeben zu können. Er ist dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27110] = {title = "Der innere Wahnsinn", objective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Zum Schluss müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", description = "Dieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Wenn das erledigt ist, vernichtet Immol'thar. Die Macht des Prinzen wird durch das Dahinscheiden des Dämons stark geschwächt sein. Greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer, und lasst den Prinzen für seine Schandtaten bezahlen.", progress = nil, completion = "Wir sind Euch zu Dank verpflichtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27111] = {title = "Der Schatz der Shen'dralar", objective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe, was Ihr wollt.", progress = nil, completion = "Ihr öffnet die Truhe und findet...", rewards = "Dreizack von Shen'dralarDüsterbrecherEzra Grimms ZigarrenschneiderStab von Athen'aIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27112] = {title = "Verfluchte Überreste", objective = "Tötet Magister Kalendris und Illyanna Rabeneiche.", description = "Es gibt immer noch einige Wesen, die eine Gefahr darstellen, sollten wir diese heilige Stadt zurückerobern wollen. Magister Kalendris und Illyanna Rabeneiche sind beide äußerst gefährlich und wir müssen uns ihrer so schnell wie möglich entledigen.\n\nSeid vorsichtig, denn jetzt, da nur noch so wenige sich von Immol'thars Energien nähren, sind sie wahrscheinlich stärker, als es auf den ersten Blick scheint.", progress = nil, completion = "Euer Engagement wird all dies so viel einfacher machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27113] = {title = "Der Uralte Shen'dralar", objective = "Sprecht mit dem Uralten Shen'dralar.", description = "Einige Wesen haben es auf wundersame Weise geschafft, der Dunkelheit zu entgehen, die hier ihr Unwesen treibt. Auf der zweiten Etage am Hof der Hochgeborenen ruht ein Uralter Shen'dralar. Sucht ihn auf, er ist möglicherweise ein unerschöpflicher Quell der Weisheit und kennt vielleicht sogar das Geheimnis, wie man Eldre'Thalas befreit.", progress = nil, completion = "Unser Treffen ist kein Zufall, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27114] = {title = "Der Gordokgeschmackstest", objective = "Ihr seid nun großer Boss, also kriegt ihr kostenlose Probe meiner guten Gebräue! Diese Getränke stärken Euch UND geben eine gute Dröhnung! Das ist gutes Zeug, Chef... probiert sie und erzählt Kreeg davon!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGrüner GordokgrogKreegs Hauwegstarkbier"}
MultiLanguageQuestData['de'][27115] = {title = "Andos Ruf", objective = "Sprecht mit Ando Blastenheimer.", description = "Ihr habt hier großartige Arbeit geleistet, <Name>. Als Ihr fort wart, hat dieser junge Bursche Ando nach Euch gesucht. Sagte was von einem Metallvogel.\n\nVielleicht solltet Ihr zu den Ufern des Loch zurückkehren und nachsehen, was er wollte.", progress = nil, completion = "Es funktioniert! Mein Vater hat es geschafft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27116] = {title = "Die Winde von Loch Modan", objective = "Fliegt mit dem Himmelsschreiter zur Station Algaz und sprecht dann mit Gebirgsjäger Sturmlanze.", description = "Vater hat den Himmelsschreiter fertiggestellt. Er ist großartig! Wenn wir erst einmal die Kinderkrankheiten ausgemerzt haben, werde ich ihn benutzen, um für die Gerechtigkeit zu kämpfen - genau, wie Ihr.\n\nIch weiß, Ihr müsst weiterziehen und anderen Menschen helfen. Schließlich seid Ihr ein Held und so, aber wie wäre es mit einem Probeflug? Ich will den Himmelsschreiter gerade zu seinem Jungfernflug hinausbringen und es wäre mir eine Ehre, wenn Ihr Euch mir anschließen würdet. Ich setze Euch bei der Station Algaz ab.\n\nWas meint Ihr?", progress = nil, completion = "Was zum Henker WAR das? Ein fliegender Mechanoschreiter?\n\nWisst Ihr was, ich will es gar nicht wissen. Ich tue einfach so, als wäre das nicht passiert und wir unterhalten uns nett wie Geschäftsleute.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27117] = {title = "Rohe Gewalt", objective = "Tötet den Ravenier in Andorhal.", description = "Gandling hat seinen Leutnant, den Ravenier, zur Unterstützung mitgebracht. Dieser trampelnde Rohling ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.\n\nDer Ravenier befindet sich in einem Turm am südlichen Ende des Orts. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, <Name>. Er ist kein leichter Gegner.", progress = nil, completion = "Ausgezeichnet gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27118] = {title = "Eine beschädigte Falle", objective = "Eine große, beschädigte Falle liegt vor Euch. Es sieht so aus, als hätten die Oger erfolglos versucht, sie zu reparieren.\n\nNeben der Falle liegt eine hastig geschriebene Notiz, die seltsamerweise genau beschreibt, wie sie zu reparieren ist. Ein paar Handgriffe reichen. In einer reparierten Falle würde sich ein Oger, der nahe an ihr vorbeigeht, vielleicht verfangen und könnte vermieden werden.\n\nEs ist wirklich gut, dass so wenige Oger lesen können.\n\nWirklich.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][27119] = {title = "Der Ogeranzug der Gordok", objective = "Bringt etwas Ogergerbemittel zu Knot Zwingschraub.", description = "Wenn Ihr vorhabt, gegen den König der Gordok zu kämpfen, dann werden Ihr es erstmal an Hauptmann Krombruch vorbei schaffen müssen. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen. \n\nEs stellt sich nur die Frage, wie? Ich glaube ich weiß, wie! Ein Ogeranzug! Ich kann Euch einen herstellen, der ausreicht, um diese Kerle zu täuschen, wenn Ihr mir Ogergerbemittel von oben herbringt. So wie die Dinge stehen, gehe ich nirgendwohin.", progress = "Bringt mir einfach dieses Ogergerbemittel und ich stelle Euch einen Anzug her, der Hauptmann Krombruch glauben lassen wird, dass Ihr einer seiner Männer seid.", completion = "Das sollte gehen. Ein Schnitt hier, ein Stich da... - das wird ein richtiges Meisterwerk! &lt;Ein breites Grinsen zeichnet sich im Gesicht des Goblins ab.&gt;\n\nHier, damit seid Ihr vorbereitet. Denkt daran - der Ogeranzug ist alles andere als haltbar. Nachdem Ihr ihn angezogen habt, bleiben Euch zehn Minuten bevor er auseinanderfällt und dann ist's aus mit der Täuschung! Benutzt ihn erst kurz bevor Ihr Krombruch begegnet, damit er so lange hält, wie Ihr ihn braucht.", rewards = "Ihr bekommt:\n\nOgeranzug der Gordok"}
MultiLanguageQuestData['de'][27120] = {title = "Der Ogeranzug der Gordok", objective = "Braucht wohl einen neuen Anzug, oder? Na, ich werde wohl eh noch eine Weile hier sein - bringt mir noch ein Ogergerbemittel, dann mache ich Euch einen neuen Ogeranzug.", description = nil, progress = "Braucht wohl einen neuen Anzug, oder? Na, ich werde wohl eh noch eine Weile hier sein - bringt mir noch ein Ogergerbemittel, dann mache ich Euch einen neuen Ogeranzug.", completion = "Bitte schön, &lt;Name&gt; - leg das Ding an, dann habt Ihr zehn Minuten Zeit, irgendwas zu tun. Viel Glück!\n\nOh, und solltet Ihr zufällig einen Schlüssel finden, mit dem ich hier raus komme, LASST MICH DAS RUHIG WISSEN!!!", rewards = "Ihr bekommt:\n\nOgeranzug der Gordok"}
MultiLanguageQuestData['de'][27123] = {title = "Tiefenheim, Reich der Erde", objective = "Springt auf Aggras Wyvern und fliegt in die Bresche am Mahlstrom. Wenn Ihr auf der anderen Seite ankommt, sprecht mit Maruut Steinbinder.", description = "Ich wusste, Ihr würdet unserem Ruf Folge leisten, <Name>. Als Todesschwinge das erste Mal von den anderen Drachenaspekten besiegt wurde, zog er sich nach Tiefenheim, im Reich der Erde, zurück.\n\nTodesschwinges Rückkehr in unsere Welt hinterließ einen Riss zwischen Azeroth und Tiefenheim.\n\nWenn wir die Lücke nicht schließen, wird dieses Land auseinandergerissen werden. Wir tun unser Bestes, um den Schaden, der diesseits des Risses entsteht, in Grenzen zu halten. Aggra wird Euch durch den Riss mitnehmen, damit Ihr helfen könnt, den Schaden von der anderen Seite aus zu reparieren.\n\nSchwingt Euch auf ihren Wyvern, wenn Ihr bereit seid.", progress = nil, completion = "Ihr seid genau rechtzeitig eingetroffen, &lt;Name&gt;. All unsere Helfer sind damit beschäftigt, den Riss zu stabilisieren.\n\nWir brauchen jemanden, der uns dabei hilft, die Fragmente der Weltensäule zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27124] = {title = "Die offene Rechnung der Gordok", objective = "Sprecht mit Wache Mol'dar in Düsterbruch.", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von Wächter Mol'dar! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de' wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", progress = nil, completion = "Wow... Ihr SEID de' wahre König! Alter König niemals auch nur nach Stulpen gefragt!\n\nGuckt - dieses Zeichen auf de' Stulpen ist ein sehr sehr SEHR altes Zeitsymbol. Älter als Gordok, sagen sie. Nun, als kleiner Oger bekommen eins beigebracht: Wie man machen Zeichen wieder lebendig, um geben den Stulpen die Kraft zurück!\n\nIch werde es für Euch tun, König! Hier, nehmen Stulpen und herrschen AUF EWIG!", rewards = "Gordoks HandschützerGordoks StulpenGordoks HandschuheGordoks HandlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27125] = {title = "König der Gordok", objective = "Tötet König Gordok.", description = "Bei den Gordok, ist der stärkste Krieger der König. Wenn jemand, egal ob Oger oder sonstwer, den amtierenden König tötet, wird er automatisch als neuer König begrüßt.\n\nDer neue König erhält Tribut von allen lebenden Wachen, Stampfer Kreeg und Hauptmann Krombruch. Findet und tötet König Gordok, aber tötet so wenig der anderen Anführer wie möglich. Ihr werdet nicht nur eine reiche Belohnung erhalten, sondern könnt Eure Macht als König benutzen, um die Invasion der Gordok ohne Konflikt zu verhindern!", progress = nil, completion = "Ja! Ich sehe, Ihr wart erfolgreich. Ihr habt Euren Tribut erhalten, den Vormarsch der Gordok gibt es nicht mehr und die Gordok haben von all dem keine Ahnung! Das ist das Szenario eines Gewinners, &lt;Name&gt;.", rewards = "Pantoffeln des TributsGelenkbänder des TributsSchulterstücke des TributsTributgewehrIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27126] = {title = "Eilige Lieferung", objective = "Liefert die Katapultteile bei Spitz Schleifstein an der Zerrissenen Front in Tiefenheim ab.", description = "Spitz Schleifsteins Team hatte irgendwo im Westen eine Panne.\n\nMeint Ihr, Ihr könnt Euch zur Abwechslung mal nützlich machen und einige Ersatzteile zu ihnen hinausbringen, <Volk>?", progress = "Habt Ihr da die Ersatzteile?", completion = "Ich kann Euch nicht genug danken, &lt;Klasse&gt;. Dann lasst uns mal sehen, ob wir das Katapult wieder in Bewegung bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27128] = {title = "König der Gordok", objective = "Tötet König Gordok.", description = "Du tötest Anführer der Gordok, du neuer Ogerkönig. Wenn du König, dann überlebende Ogeranführer wie Kromcrush und Kreeg zahlen großen Tribut und du beendest Gordokinvasion. Wenn du das tust, dann ich sehr glücklicher Oger und wir nehmen Düsterbruch FÜR DIE HORDE!!!\n\nGeht, kleiner <Volk>! Tötet hässlichen Gordok Ogerkönig und vielleicht das hier neue Steinbrecherfestung! Yar!", progress = nil, completion = "Kleiner &lt;Volk&gt; hat es geschafft! Horde jetzt mächtiger denn je! YAR!", rewards = "Pantoffeln des TributsGelenkbänder des TributsSchulterstücke des TributsTributgewehrIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27129] = {title = "Wucherborke retten", objective = "Sprecht mit Furgus Wucherborke.", description = "Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen. Düsterbruch einzunehmen wäre ein Riesenfortschritt, Feralas für unser Volk wieder zurückzuerobern.\n\nIhr findet Düsterbruch südöstlich von hier.", progress = nil, completion = "Seid Ihr in letzter Zeit einem Druiden der Kralle begegnet, &lt;Klasse&gt;? Die Anwesenheit eines solchen Druiden hängt in der Luft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27130] = {title = "Wucherborke retten", objective = "Sprecht mit Furgus Wucherborke.", description = "Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen bevor sie Camp Mojache entdecken. Vielleicht können wir uns seiner Hilfe für später versichern, um unsere Anwesenheit in Feralas zu sichern, wo wir doch von Feinden umzingelt sind.", progress = nil, completion = "In Eurem Gesicht sehe ich Anzeichen für einen verzweifelten Kampf. Eure Gegenwart ehrt mich, mutiger &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27131] = {title = "Der Hochgeborene", objective = "Sprecht mit Estulan.", description = "Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zum Wohle von Feralas gutheißen. Möge der Wind Euren Geist mit großer Geschwindigkeit dorthintragen.\n\nIhr findet Düsterbruch südöstlich von hier.", progress = nil, completion = "Ich spürte auf dem ganzen Weg von Träumersruh, dass Ihr kommen würdet. Eure Hilfe wäre mir sehr willkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27132] = {title = "Der Hochgeborene", objective = "Sprecht mit Estulan.", description = "Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zu unserem Wohle gutheißen. Bitte beeilt Euch - wir brauchen jeden Fuß in der Tür von Feralas, den wir bekommen können.\n\nIhr findet Düsterbruch im Westen.", progress = nil, completion = "Ich spürte auf dem ganzen Weg von Camp Mojache, dass Ihr kommen würdet. Eure Hilfe wäre mir sehr willkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27133] = {title = "Blick zum Himmel", objective = "Sprecht mit dem Druiden der Kralle.", description = "Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Ich habe einen Druiden der Kralle beauftragt, sich dorthin zu begeben und die Lage zu erkunden. Meldet Euch bei ihm, falls er noch am Leben ist. Er wird Euch befehligen, um die Gordok aufzuhalten, bevor sie sich zum Angriff entscheiden.\n\nDas ist ein Befehl, <Klasse>.", progress = nil, completion = "Sprecht leise, &lt;Name&gt;. Die Gordok sind zwar nicht sehr schlau, aber sie sind trotzdem gefährliche Krieger.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27134] = {title = "Oger im Feld", objective = "Sprecht mit dem Oger der Steinbrecher.", description = "Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Wenn wir sie auslöschen und Düsterbruch für die Horde in Anspruch nehmen, könnten wir unsere Machtposition in dieser artefaktreichen Gegend enorm stärken. Ich habe vor kurzer Zeit eine kleine Truppe Oger der Steinbrecher losgeschickt. Sprecht mit möglichen Überlebenden und beendet, was begonnen wurde.\n\nDas ist ein Befehl, <Klasse>.", progress = nil, completion = "Diese Oger keine Knallschoten. Hilf mir, Orhans Aufgabe zu vollenden, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27135] = {title = "Etwas, das brennt", objective = "Erhaltet das brennende Herz.", description = "Also, wir brauchen etwas, mit dem das Präparat in die Luft fliegt - KABUMM!\n\nIch habe kein Schießpulver mehr, aber ich habe eine Idee, was wir stattdessen verwenden können ... das Herz meines Feuerelementars!\n\nHier, nehmt mein Feuertotem mit nach Osten auf Eurem Weg zum Blutpfad. Betätigt es dort in der Nähe der Lavaseen, und Magmazahn sollte erscheinen. Bringt mir sein Herz, dann unterhalten wir uns weiter.", progress = "Habt Ihr das Herz schon?", completion = "Oha. Es scheint, als hätte die Situation ihn nicht gerade erfreut. Wie hätte ich das wissen können? Ich bin doch nur ein Initiand.\n\nWie dem auch sei. Über Magmazahn sorge ich mich später.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27136] = {title = "Elementarenergie", objective = "Zerstört 8 aufgeladene Geoden oder Leitsteinelementare in der Nähe des erschöpften Totems.", description = "Wir müssen unsere ganze Kraft aufbringen, um die Stabilität des Reichs in der Abwesenheit der Weltensäule sichern zu können.\n\nAls Schamanen können wir direkt die Energien der Elementare von Tiefenheim anzapfen und zur Heilung für vom Riss verursachten Schaden nutzen.\n\nNehmt dieses Totem und platziert es außen auf dem Boden. Alle aufgeladenen Geoden oder zerstörten Leitsteinelementare in der Nähe werden es mit der Energie füllen, die wir benötigen.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Wir benötigen alle Kraft, die wir aufbringen können, um die Stabilität von Tiefenheim zu sichern.", rewards = "Großstreitkolben aus EnergonFunklichtrobenErdschlussgamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27139] = {title = "Hobart braucht Euch", objective = "Sprecht mit Hobart Wurfhammer in Instastadt auf den Verlorenen Inseln.", description = "He da, Boss! Hobart Wurfhammer möchte mit Euch sprechen. Er sagt, es wäre eine Angelegenheit von höchster Dringlichkeit!", progress = nil, completion = "Da seid Ihr ja, mein Junge! Ich habe etwas äußerst Wichtiges, was Ihr für mich erledigen müsst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27140] = {title = "Alexis Gambit", objective = "Platziert das Gambit im Vorführraum und tötet Vectus und Marduk.", description = "Ich benötige Eure Hilfe, <Klasse>. Findet den Untoten Magier Vectus und den Krieger Marduk hier in den Tiefen. Sie sind mit der Operation des verseuchten Drachen der Geißel beschäftigt und müssen aufgehalten werden.\n\nPlatziert das Gambit in dem Vorführraum, in dem sie sich befinden. Hoffentlich entsteht eine Reaktion mit ihren Kräften und zerstört sie!\n\nOh, Vectus und Marduk danach zu bewältigen dürfte auch kein Problem darstellen, oder?", progress = nil, completion = "Ihr habt es geschafft! Sie sind besiegt! Und das Gambit - hat es funktioniert?\n\nSehr interessant. Ihr habt gute Arbeit geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27141] = {title = "Explosiv", objective = "Helft Harrison Jones am Grab des Khartut.", description = "Was für ein Fund!\n\nGenau hier... genau an der Stelle, die in meinen Notizen vorhergesagt wurde.\n\nMit ein wenig Glück werden sich in dieser Kammer Hinweise zum Verbleib der legendären Lade der Verheißung finden lassen.\n\nJa, das stimmt, <Name>. Es ist nicht nur eine Legende. Ich glaube, dass es die Lade wirklich gibt.\n\nIch werde Euch später mehr erklären. Helft mir jetzt erstmal mit diesen Sprengsätzen.", progress = nil, completion = "Schüttelt es ab, Kleiner.\n\nPassiert mir ständig...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27142] = {title = "Der Lich Ras Frostraunen", objective = "Vernichtet Ras Frostraunen.", description = "Einer der Studenten, denen Kel'Thuzad viel Vertrauen schenkt, leitet die Operationen in Scholomance. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber. Die hintere Tür im Vorführraum führt in seine Kammer.\n\nZerstört ihn, <Name>. Löscht jeglichen Nachweis seiner Existenz aus, so dass er nie wieder solche Schrecken in unsere Welt bringen kann.", progress = nil, completion = "Abertausende Seelen schreien im Einklang aus, &lt;Name&gt;. Ihr habt mit einem tödlichen Schlag die Geißel und ihre Meister vernichtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27143] = {title = "Das Familienvermögen der Barovs", objective = "Findet die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade.", description = "Das Familienvermögen der Barovs liegt in Scholomance. Alexi und ich sind die beiden letzten verbliebenen Erben des Hauses Barov.\n\nIch bin jedoch der letzte Barov, der am Leben ist, und somit ist das ganze Reich der Barovfamilie mein! Findet die Besitzurkunden für Darrowehr, Brill, Tarrens Mühle und Süderstade, und ich werde Euch mit großem Reichtum belohnen. Der Besitz der Barov wird endlich wieder in voller Blüte stehen!", progress = "Verneigt Euch in meiner Gegenwart, <Volk>. Ich bin immerhin von Adel, und Ihr seid nur ein armer Bauer.", completion = "Ihr habt vorzügliche Arbeit geleistet, &lt;Volk&gt;. Für diese Torheit verdient Alexi kein Lob.", rewards = "Ihr bekommt:\n\nBedienstetenglöckchen der Barovs"}
MultiLanguageQuestData['de'][27144] = {title = "Die Abrechnung", objective = "Wartet, bis Fürstin Sylvanas Windläufer mit Koltira Todesweber gesprochen hat.", description = "Ihr habt eine vortreffliche Leistung vollbracht. Ihr erfüllt die Verlassenen mit Stolz, was ich von Kriegsherr Koltira Todesweber nicht behaupten kann.\n\nIch habe vor, ein ernstes Wörtchen mit diesem Todesritter zu wechseln. Er hat Schande über sich und das, wofür er steht, gebracht.", progress = nil, completion = "Ich habe nichts gegen die Ritter der Schwarzen Klinge, aber Koltira muss sich im Klaren darüber sein, für wen er arbeitet. Seine Loyalität muss einzig und allein der Horde gelten.\n\nGenauer gesagt, den Verlassenen.\n\nIch würde mich nicht darauf verlassen, Koltira bald wieder zu sehen. Jetzt, da ich ihn habe ... könnt Ihr Euch sicher sein, dass alle seine Verbindungen zu irgendwelchen Allianzlern vollständig zerstört werden.", rewards = "Dolch von AndorhalStab von AndorhalTunika von AndorhalBeinschützer von AndorhalSchulterstücke von AndorhalIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27145] = {title = "Verseuchte Jungtiere ... im Moment", objective = "Tötet 10 verseuchte Jungtiere und Blutrippe.", description = "Eines der aktuellen 'Projekte' ist der verseuchte Drachenschwarm. Glücklicherweise handelt es sich dabei um Jungtiere, aber wenn wir noch länger warten, werden sie zu einer der mächtigsten Waffen im Arsenal der Geißel und eine ernst zu nehmende Gefahr für Azeroth, und vor allem für die Ländereien meiner Familie.\n\nErschlagt zehn der Jungtiere und vergesst nicht, Euch auch um Blutrippe zu kümmern. Ihr findet ihn in der Nähe der Behausung der Jungtiere, wo er Nahrungsergänzungen zubereitet, die das Wachstum ankurbeln sollen. Beeilt Euch - bevor sie noch größer werden!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Es wird lange dauern, bis unser Feind eine neue Generation dieser Drachen züchten kann.\n\n... Zumindest hoffe ich das!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27146] = {title = "Doktor Theolen Krastinov, der Schlächter", objective = "Vernichtet Doktor Theolen Krastinov, und verbrennt die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff.", description = "Doktor Theolen Krastinov ist für die Tode Tausender verantwortlich. Seinen Spitznamen 'der Schlächter' hat er sich mit den Gräueltaten, die ihm so viel Freude bereiten, redlich verdient. Er muss im Namen der Gerechtigkeit bestraft werden.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige wie mich und meinem Ehemann gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, <Name>. Befreit unsere schmerzenden Seelen.", progress = nil, completion = "Ich fühle, wie mein Geist heilt, &lt;Name&gt;. Ihr habt meinem Ehemann und mir einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27147] = {title = "Kirtonos der Herold", objective = "Zerstört Kirtonos.", description = "Mit Blut lässt Kirtonos sich anlocken. Also wird es Blut sein, das Kirtonos zerstören wird.\n\nIn der Kammer der Beschwörung werdet Ihr eine Kohlenpfanne finden, über der Ihr einen Tropfen Eures eigenen Blutes vergießen müsst. Kirtonos wird erscheinen - er kann nicht widerstehen. Entfesselt sobald er auftaucht den Zorn und Furor Tausender Unschuldiger.\n\nSollte Ihr erfolgreich sein, werdet Ihr mehr als nur unseren Dank erhalten.", progress = nil, completion = "Mit dem Tod Kirtonos wird ein schreckliches Kapitel der Geschichte von Scholomance abgeschlossen. Ihr habt für Euren Mut nun für immer meine tiefste Dankbarkeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27148] = {title = "Hurra, die Schule brennt", objective = "Tötet Dunkelmeister Gandling.", description = "Dunkelmeister Gandling ist der Direktor von Scholomance und daher für die zahllosen Tode verantwortlich, die seine Schüler für ihn ausführten. Dafür muss er bestraft werden.\n\nEr wird nicht so einfach aus seinem Arbeitszimmer kommen. Lockt ihn heraus, indem Ihr die sechs Professoren tötet, deren Zimmer zum Arbeitszimmer des Direktors führen. Seid vorsichtig, denn wenn der letzte Professor erledigt ist, wird er mehr als erzürnt erscheinen und mit überwältigender Magie angreifen. Seht zu, dass er es nicht aus dem Arbeitszimmer schafft.", progress = nil, completion = "Ohne einen Direktor wird die Schule im Chaos versinken, und es werden nicht noch mehr dieser abscheulichen ‚Studenten‘ ausgebildet. Ich danke Euch.", rewards = "Luciens StiefelFesseln der StrafeDisziplinarruteAuf Euch wartet eine dieser Belohnungen:\n\nSignet des Dunkelmeisters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27149] = {title = "Schule der Verdammten", objective = "Sprecht mit Weldon Barov in Scholomance.Seid gegrüßt! Wie Ihr sehen könnt, sind die Westlichen Pestländer von beinahe allen Restposten der Geißel befreit. Allerdings ist Scholomance, die Schule der Totenbeschwörung, noch voller junger Seelen, die nur darauf warten, ihre Ausbildung zu Zauberern der Geißel abzuschließen. Unsere Arbeit wird umsonst gewesen sein, wenn wir dem ständigen Nachrücken immer neue - und vorallem auch mächtiger - Totenbeschwörer kein Ende setzen.\n\nReist südöstlich nach Scholomance und sucht Weldon Barov. Er ist der letzte lebende Nachkomme der Familie Barov, der einst alle diese Ländereien gehörten, und er ist unser Kontakt vor Ort.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Seid gegrüßt! Wie Ihr sehen könnt, sind die Westlichen Pestländer von beinahe allen Restposten der Geißel befreit. Allerdings ist Scholomance, die Schule der Totenbeschwörung, noch voller junger Seelen, die nur darauf warten, ihre Ausbildung zu Zauberern der Geißel abzuschließen. Unsere Arbeit wird umsonst gewesen sein, wenn wir dem ständigen Nachrücken immer neue - und vorallem auch mächtiger - Totenbeschwörer kein Ende setzen.\n\nReist südöstlich nach Scholomance und sucht Weldon Barov. Er ist der letzte lebende Nachkomme der Familie Barov, der einst alle diese Ländereien gehörten, und er ist unser Kontakt vor Ort.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27150] = {title = "Die Stätte der Heiler", objective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.Wahrscheinlich wird die Schlacht um Andorhal bald wieder wüten. In der Zwischenzeit solltet Ihr Eure Fähigkeiten als <Klasse> verfeinern.\n\nÖstlich von hier befindet sich ein großer Bauernhof, der von der Argentumdämmerung und dem Zirkel des Cenarius eingenommen worden ist. Ich bezweifle nicht, dass Ihr dort Arbeit finden werdet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Wahrscheinlich wird die Schlacht um Andorhal bald wieder wüten. In der Zwischenzeit solltet Ihr Eure Fähigkeiten als <Klasse> verfeinern.\n\nÖstlich von hier befindet sich ein großer Bauernhof, der von der Argentumdämmerung und dem Zirkel des Cenarius eingenommen worden ist. Ich bezweifle nicht, dass Ihr dort Arbeit finden werdet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27151] = {title = "Taelan Fordrings Vermächtnis", objective = "Tötet 10 Plünderer der Rotkiefer.", description = "Seid gegrüßt. Wie geht es Euch? Mein Name ist Daria.\n\nIch bin eine der Priesterinnen, die für den Erhalt des Friedens hier in Herdweiler zuständig ist. Eine meiner Aufgaben ist die Verwaltung des Turms entlang des Wegs südöstlich von Herdweiler. Dieser Turm ist von persönlicher Bedeutung für den Hochlord. Sein Sohn wurde dort getötet.\n\nDie Verwaltung des Turms bereitet jedoch aufgrund des feindlichen Einfalls der Gnolle vor Kurzem zunehmend Schwierigkeiten. Könnt Ihr mir helfen, den Weg von den Vandalen der Gnolle zu räumen, sodass ich meinen Pflichten nachkommen kann?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27152] = {title = "Ungewöhnliches Verhalten ... selbst für Gnolle", objective = "Erkundet das Versteck der Gnolle entlang des Wegs nach Herdweiler in den Westlichen Pestländern.", description = "Ich muss mich kurz konzentrieren.\n\n<Ihr fühlt, wie Darias Gedankensicht einen anderen Ort aufsucht, und dann wieder zu Euch zurückkehrt.>\n\nSüdlich des Turm von Taelan haben die Gnolle einen Ort der Zusammenkunft errichtet - folgt dem Weg, und haltet Euch östlich der Hauptstraße. Dort geht etwas vor sich ... aber ich bin nicht sicher, was es ist. Wir sollten mehr darüber in Erfahrung bringen. Ich werde nach ungewöhnlichen Ereignissen Ausschau halten ... Ihr solltet Euch damit beschäftigen, Euch zu schützen.", progress = nil, completion = "Gnolle und Totenbeschwörung? Das ist eine Überraschung! Und ich dachte, dass hier in den Westlichen Pestländern diese dunklen Tage der Vergangenheit angehören würden.\n\n&lt;Ihr spürt, wie Daria etwas auf dem Boden genau betrachtet.&gt;\n\nWartet ... was ist DAS?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27153] = {title = "Die braven Bürger von Herdweiler", objective = "Sprecht mit Morris Vant, Ausstatter Mendelev, Bree Eisenstock und dem Hohen Kleriker Alphus in Herdweiler.", description = "Seht Ihr die Reagenzien dort drüben? Und diese Ladungen hier? Es handelt sich dabei um das Eigentum der Argentumkreuzfahrer.\n\nGnolle sind für das Stehlen von Gütern bekannt, aber meines Wissens gab es in Herdweiler seit dem Einfall der Rotkiefer keine Vorfälle mehr. Das ist sehr merkwürdig.\n\nIch habe ein paar Kontakte in Herdweiler, die Euch helfen könnten: Morris Vant, Ausstatter Mendelev, Bree Eisenstock und der Hohe Kleriker Alphus. Ihr könnt ihnen vertrauen, und sie haben gute Verbindungen. Befragt sie, um herauszufinden, ob sie etwas über die verlorengegangenen Ladungen wissen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27154] = {title = "Bisp festsetzen", objective = "Sprecht mit Magier Bisp im oberen Teil des Magierturms in Herdweiler.", description = "Magus Bisp ist einer der renommiertesten Arkanisten von Herdweiler. Die Vorstellung, dass er sich mit Gnollen abgibt ... und sich in der Totenbeschwörung versucht? Undenkbar.\n\nIhr werdet Ihn oben im Turm in der Nähe des Haupttors von Herdweiler finden können. Hoffentlich hat er eine Erklärung für das Ganze. Falls nicht, dann... In jedem Fall solltet Ihr den Magierturm nicht unvorbereitet betreten, <Name>.", progress = "Hey!", completion = "Ich glaube, wir können seine Aggression als Schuldgeständnis auffassen. Seid Ihr in Ordnung, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27155] = {title = "Sich stellen", objective = "Meldet Euch bei Hochlord Tirion Fordring in Herdweiler in den Westlichen Pestländern.", description = "So... Ihr habt also einen Argentumkreuzfahrer getötet, mitten in Herdweiler. Normalerweise wird so was nicht so einfach abgetan, selbst wenn es sich um Selbstverteidigung handelt.\n\nIch schlage vor, Ihr folgt mir nach Burg Mardenholde und stellt Euch Hochlord Fordring. Wenn Ihr Glück habt, wird er Euch anhören und Verständnis für Eure Situation zeigen. Ich hoffe, ich habe Euch nicht in Schwierigkeiten gebracht.", progress = nil, completion = "Mir sind Eure Taten bekannt, &lt;Name&gt;. Ich heiße Euch in meiner Stadt willkommen, gebe Euch meinen Segen und was macht Ihr?\n\nIhr tötet den Verräter, den wir schon seit Wochen jagen. Gut gemacht. Euer Heldenmut erblüht viel früher, als ich erwartet hatte.", rewards = "Gunst des HochlordsAuf Euch wartet eine dieser Belohnungen:\n\nArgentummedaillonLichterfüllte Laterne\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27156] = {title = "Es wird langsam Zeit!", objective = "Fordert 7 Lehrlinge von Herdweiler zum Kampf heraus und besiegt sie.", description = "Endlich! Ihr seid hier! Fangt mit der Arbeit an!\n\nMeine Männer haben schon zu lange nur mit diesen hölzernen Trainingsattrappen gekämpft. Sicherlich lässt sich das Schwingen eines Schwertes auch mit einer Trainingsattrappe erlernen, doch für den Kampf bedarf es eines echten Kämpfers.\n\nHmmm... Ich hatte ausdrücklich nach jemand mit einer eindrucksvollen Statur gefragt, aber in diesem Fall muss wohl <ein/eine:r> <Volk> mit dünnen Ärmchen herhalten.\n\nKommt her und zeigt meinen Männern, wie man kämpft!", progress = nil, completion = "Ich sehe gerade meine Unterlagen durch, und hier steht, dass ein &lt;Volk&gt; hier eintreffen soll. Ihr seht nicht gerade aus wie, ähm ...\n\n\n\nEgal. Es scheint, als wärt Ihr nicht die Person, die ich ursprünglich beauftragt hatte, aber Ihr habt gute Arbeit geleistet. Ich werde Euch also bezahlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27157] = {title = "Akkordarbeiter... <Seufz>", objective = "Tötet Shadril in der Mine in Herdweiler.", description = "Oh, mir ist Euer Name entgangen. <Name>? Es freut mich, Eure Bekanntschaft zu schließen, <Name>.\n\nIch habe noch ein anderes Problem, bei dem ich Hilfe gebrauchen könnte, und Ihr habt etwas an Euch, dass gerade danach schreit, nach Hilfe gefragt zu werden.\n\nAm nördlichen Rand von Herdweiler ist eine kleine Mine, aus der wir den Großteil des für unsere Stadt benötigten Erz beziehen. Die Akkordarbeiter in der Mine verrichten normalerweise gute Arbeit.\n\nAllerdings scheint es leider, als habe eine überdurchschnittlich große Spinne sich in der Höhle häuslich eingerichtet. Meint Ihr, Ihr könnt Euch der Sache annehmen?", progress = nil, completion = "Gute Arbeit! Wenn ich zurückblicke, bin ich fast froh, dass dieser andere &lt;Klasse&gt; nicht aufgetaucht ist ... Ihr habt Euch als Lösung all meiner Probleme herausgestellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27158] = {title = "Die Schlacht um Andorhal", objective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", description = "Beeilt Euch, <Name>... es gilt, keine Zeit zu verlieren.\n\nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen den Verlassenen, der Allianz und der Geißel. König Wrynn hat den Stein ins Rollen gebracht und einen Todesritter geschickt, um den Angriff in die Wege zu leiten. Ich bin aber sicher, dass er alle Hilfe brauchen wird, die er kriegen kann. Mit dem Tod von Arthas ist die Zeit für die Allianz gekommen, Lordaeron zurückzuerobern.\n\nMeldet Euch bei Greifenmeister Bibilfaz Federpfiff, wenn Ihr bereit seid, und er wird Euch mit dem nächsten Greifen losschicken.", progress = nil, completion = "Endlich seid Ihr hier, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27159] = {title = "Erst die Geißel ... dann die Horde", objective = "Tötet 15 ausgedörrte Geißeldiener in Andorhal.", description = "Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein ehemaliger Mitstreiter Koltira leitet die Streitkräfte der Verlassenen. Um Andorhal einzunehmen, müssen wir beide Streitmächte besiegen. Eine Niederlage ist gewiss, wenn wir versuchen, uns beiden auf einmal zu stellen.\n\nIch kenne Koltira gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden es ihm gleichtun.\n\nSetzt die schwächeren, vertrockneten Geißeldiener außer Gefecht, um ihre Zahlen zu schwächen. Die Verlassenen werden darauf warten müssen, unseren Zorn zu spüren.", progress = nil, completion = "Ihr reagiert zwar nicht schnell, doch immerhin enttäuscht Ihr mich nicht.\n\nNun gut. Ich werde eine noch wichtigere Aufgabe für Euch haben, &lt;Name&gt;, wenn die Zeit reif ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27160] = {title = "Kriegsmaschinen", objective = "Zerstört 6 aufgeschlitzte Ungetüme in Andorhal.", description = "Vertrocknete Geißel... schwach. Monstrositäten... stark.\n\nWir besiegen starke Monstrositäten... wir gewinnen Krieg.", progress = nil, completion = "Monstrositäten ... stark.\n\n&lt;Name&gt; ... stärker.", rewards = "Vertrocknete ArmschienenLakonischer GürtelUngetümstiefelWanstöffnerhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27161] = {title = "Der unendliche Fluss", objective = "Benutzt Langs Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.", description = "Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten ... eine Armee von Schwächlingen, die Euch eher überrennen als überwältigen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!\n\n<Lang reicht Euch ein paar Granaten.>\n\nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.", progress = "Ich kenne das Geräusch, das diese Dinger bei der Explosion machen ... und ich habe das Geräusch noch nicht gehört. Geht zurück an die Arbeit, <Name>.", completion = "Diese Granaten sind Sprengstoff, mehr nicht. Ich bin zwar kein Gobliningenieur ... aber ich weiß, dass es sehr nützlich sein kann, ab und an mal Sachen in die Luft zu sprengen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27162] = {title = "Scholomancer", objective = "Tötet Dunkelmeister Gandling in Andorhal.", description = "Scholomance ist eine der letzten verbleibenden Bastionen der Geißel im Westen des Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld erschienen.\n\nDas wird der letzte Fehler sein, der ihm unterläuft.\n\nIhr werdet Gandling auf einem Platz in der Nähe des südlichen Stadtrands finden. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch beistehen, damit er sein Ende findet.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Jetzt, da der Anführer der Streitmächte der Geißel nicht länger in Andorhal sein Unwesen treibt, müssen wir den richtigen Augenblick abwarten.", rewards = "Gandlings HandschuheBürde der ZeitArmschienen der BeseitigungGürtel der anhaltenden VerderbnisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27163] = {title = "Rohe Gewalt", objective = "Tötet Blutrippe in Andorhal.", description = "Gandling hat seinen Leutnant Blutrippe zur Unterstützung mitgebracht. Dieser rasselnde Schrecken ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.\n\nBlutrippe befindet sich im alten Rathaus, in der Nähe der Stadtmitte. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, <Name>. Er ist kein leichter Gegner.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27164] = {title = "Araj der Beschwörer", objective = "Tötet Araj den Beschwörer. Ihr könnt Langs Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.", description = "Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln sehen.\n\nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.", progress = "Araj ist ein ausgezeichneter Gegner. Ihr solltet gut vorbereitet sein.", completion = "Araj ist tot... das ist gut. Dieser Gnom hat bei unserem Sieg eine Rolle gespielt. Und Ihr auch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27165] = {title = "Sieg, im Moment", objective = "Meldet Euch bei Kommandant Ashlam Ehrenschlag in Zugwindlager in den Westlichen Pestländern.", description = "Die Allianz hat gesiegt und unsere Streitmächte sind noch immer stark. Im Rahmen unserer Kriegsplanung müssen wir die Verlassenen jetzt angreifen, da sie sich noch vom Kampf erholen und nicht mit einem Angriff rechnen. Ich habe allerdings ein Abkommen geschlossen...\n\nWir werden warten. Wir greifen Koltira und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Ginny Siegesfroh und begebt Euch zum Zugwindlager südlich von hier. Kommandant Ashlam Ehrenschlag wird Euch über Eure nächste Aufgabe unterrichten.\n\nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.", progress = nil, completion = "Die Neuigkeiten erreichten uns kurz vor Euch, &lt;Name&gt;. Dass die Geißel aus Andorhal vertrieben wurde, bedeutet, dass wir der Rückeroberung von Lordaeron einen Schritt näher gekommen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27166] = {title = "Pfeile machen!", objective = "Erhaltet 9 Braunfederkiele.", description = "Wir müssen immer auf den Kampf vorbereitet sein, <Name>. Ob dieser Kampf gegen die Verlassenen in Andorhal, gegen die Geißel im Osten, oder gegen einen noch unbekannten Feind ausgetragen wird, steht noch in der Zukunft geschrieben. Wir wissen nur, dass wir bereit sein müssen.\n\nUns gehen die Pfeile aus. Ich kann Schäfte und Pfeilspitzen besorgen, aber ich benötige Federn. Die Vögel, die nordwestlich von hier kreisen, sind zu dieser Jahreszeit normalerweise in der Mauser. Könntet Ihr Euch dorthin begeben und für unser Lager einige dieser Federn sammeln?", progress = "Es ist gut, Euch wieder zu sehen, <Name>.", completion = "Meine Pfeilmacher werden sich gleich an die Arbeit machen.\n\nEs ist gut zu sehen, dass Ihr Euch so nützlich macht, &lt;Name&gt;. Vielleicht habe ich später noch aufregendere Aufgaben für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27167] = {title = "Magenknurren", objective = "Beschafft Euch 5 Stücke Bärenfleisch von struppigen Schwarzbären in den Westlichen Pestländern.", description = "Ich komme aus Westfall, weit im Süden. Auch diese Männer, die mit mir reisen, sind von dort. Wir sind nicht mehr als Bauersleute.\n\nMir wurde gesagt, dass Lordaeron geheilt wurde und der Boden bestellt werden kann. Dieser \"Kommandant\" meint jetzt allerdings, dass es zu gefährlich ist, diese Arbeit vorzunehmen. Er meint, es tobe ein Krieg, und dass die Pestländer noch nicht geheilt sind.\n\nWie dem auch sei, was ich wirklich brauche, ist Essen in den Mägen meiner Männer. Es ist egal, was. Es scheint, als seien Bären hier reichlich vorhanden.", progress = "Wir haben eine weite Reise hinter uns. Jeder Bissen, den Ihr übrig habt, ist eine Wohltat für uns.", completion = "Ihr jagt, wie nur ein echter &lt;Klasse&gt; jagen kann. Selbst wenn wir unsere Behausungen noch nicht errichten können, so haben wir wenigstens etwas zu essen.", rewards = "BauernwesteHelm der HeimstattGewehr des BärenjägersAuf Euch wartet eine dieser Belohnungen:\n\nGrants Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27168] = {title = "Wer nicht loslassen kann", objective = "Benutzt das Heilige Weihrauchfass bei 12 zurückgezogenen Geistern in Trauerhügel, und tötet sie, falls ihre Reaktion dies verlangt.", description = "Trauerhügel nordöstlich von hier war einer der ersten Orte, den die Argentumkreuzfahrer und der Zirkel des Cenarius heilen konnten. Dieses Gebiet ist nun von der Geißel befreit.\n\nAllerdings finden sich dort immer noch Schreckgespenster der Vergangenheit, die aus irgendwelchen Gründen den Weltenübergang nicht vollbracht haben. Vielleicht trauern sie, oder sie haben noch eine Aufgabe zu erledigen... oder sie haben sich einfach nur verirrt.\n\nNehmt mein Weihrauchfass und läutert sie mit dem heiligen Weihrauch. Auf die eine oder andere Weise wird ihnen das beim Weltenübergang helfen.", progress = nil, completion = "Ich hoffe, dass den meisten der Übergang in Frieden gelungen ist. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27169] = {title = "Uthers Segen", objective = "Begebt Euch zu Uthers Grabmal und verwendet den Eiswindtribut vor seiner Statue.", description = "Diese Bauern aus dem Süden wollen sich der Bauernhöfe annehmen, aber ich kann nicht zulassen, dass sie die Pestländer unvorbereitet betreten. Auch jetzt, wo die Geißel nicht mehr hier ist, lauert immer noch Gefahr - durch die Verlassenen. Nein, wir müssen bereit sein, zu kämpfen, und das schließt unsere Besucher ein.\n\nBevor wir irgendetwas anderes tun, würde ich allerdings vorschlagen, dass Ihr nach Osten zu Uthers Grabmal reist und diesen Tribut vor seiner Statue niederlegt, um seinen Segen zu erbitten. Sprecht danach mit dem Priester, der sich um das Grabmal kümmert.", progress = "Uther war ein wahrer Held. Es ist mir eine Ehre, ihm zu dienen, nach allem, was er erlitten hat.", completion = "Ihr und die Menschen von Zugwindlager möchtet Andorhal zurückerlangen? Ich wünsche Euch viel Glück.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27170] = {title = "Die verlassene Gruft", objective = "Findet die Waffenkiste unten in der Gruft in den Westlichen Pestländern.", description = "Wenn Ihr die Schlacht um Andorhal wirklich vorantreiben möchtet, kann ich Euch vielleicht helfen.\n\nÖstlich von hier befindet sich eine große Gruft. Der untere Teil der Gruft wurde einst für die Aufbewahrung von Waffen und Rüstung benutzt - bis die Geißel kam. Jetzt, da die Untoten nicht mehr hier sind, können diese Waffen benutzt werden.\n\nDie meisten Waffen sind wohl rostig und alt, aber trotzdem besser für unsere Zwecke geeignet als Tuniken und Heugabeln.", progress = nil, completion = "Auf der untersten Ebene der Gruft findet Ihr zerstörte Kisten am Boden verstreut, in denen sich einst Waffen und Rüstung befanden.\n\nJemand scheint Euch zuvorgekommen zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27171] = {title = "Hinterhalt!", objective = "Erhaltet 4 abgenutzte Brustplatten und 4 verrostete Schwerter.", description = "Als Ihr Euch umdreht, seht Ihr die Silhoutten der torkelnden Skelette auf den Stufen.\n\nDie Untoten haben die Gruft nicht verlassen. Sie haben hier gewartet! Außerdem scheinen sie die Waffen zu tragen, wegen denen Ihr hier seid.\n\nIhr müsst aus der Gruft fliehen. Versucht, auf dem Weg nach draußen so viel Ausrüstung wie möglich zu ergattern.", progress = "Was ist an Uthers Grabmal passiert, <Name>?", completion = "Von Geistern angegriffen? Das ist seltsam. Die Gruft wurde wohl doch nicht vollständig geheilt.\n\nIhr habt gerade Thurman Grant verpasst - Ihr wisst schon, der Bauerntrampel, der vorhin schon mal hier war. Er hat seine Männer zusammengerufen und hat sich mit ihnen zum nächsten Bauernhof aufgemacht ... gegen meinen Befehl.", rewards = "GrufthütergürtelGeistige BarriereUmhang der RuhelosenAuf Euch wartet eine dieser Belohnungen:\n\nEhrenschlagband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27172] = {title = "Das Trostlose Feld", objective = "Bringt die ramponierten Waffen und Rüstungen zu Thurman Grant zum Trostlosen Feld in den Westlichen Pestländern.", description = "Die Bauern haben sich aufgemacht zum Trostlosen Feld, einem alten Bauernhof nordöstlich von hier, auf der anderen Seite des Flusses. Jemand muss sie im Auge behalten.\n\nBringt ihnen diese rostigen Waffen und die Rüstungen, die Ihr gefunden habt. Wir können nicht zulassen, dass sie mit Heugabeln kämpfen.", progress = "Hat Ehrenschlag Euch geschickt? Dieser Kommandant weiß nicht, wann es genug ist, oder?", completion = "Nun, da Ihr hier seid, werden wir Euch die Rüstungen dankbar abnehmen.\n\nAber die Waffen könnt Ihr behalten. Diese Männer würden nicht wissen, an welchem Ende sie sie halten müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27173] = {title = "Dies ist unsere Armee", objective = "Tötet 10 Streitkräfte der Vorhut der Verlassenen.", description = "Ich habe Kommandant Ehrenschlag darüber unterrichtet, dass wir uns selbst verteidigen können, und das haben wir auch vor. Ich hatte auf meinem Weg hierher ein kurzes Gespräch mit Thassarian, diesem Kriegsherrn der Todesritter. Wir Bauern haben vor, auf unsere eigene Art und Weise zu helfen.\n\nWir werden diesen Bauernhof einnehmen, das Land kultivieren ... und wenn die Schlacht um Andorhal beginnt, werden wir die Verlassenen vom Hinterland aus angreifen. Damit werden sie nicht rechnen.\n\nZuerst müssen wir uns der Vorhut der Verlassenen widmen. Tötet einige von ihnen, und kommt dann wieder zu mir.", progress = "Meine Männer brauchen Eure Hilfe, <Name>.", completion = "Ihr seid gut im Kampf, &lt;Volk&gt;. Ein erfahrener &lt;Klasse&gt; wie Ihr könnte meinen Männern einige Kniffe beibringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27174] = {title = "Kampftraining", objective = "Sprecht mit Gory im Trostlosen Feld und fordert ihn zum Kampf heraus.", description = "Vielleicht könnt Ihr tatsächlich ein paar meiner Männer ausbilden. Ihr habt wahrscheinlich die Monstrosität da draußen bemerkt. Wir haben zuerst versucht, sie zu bekämpfen, aber sie hat sich nicht gewehrt. Es scheint, als ob sie auf dem Bauernhof helfen möchte.\n\nNehmt vier meiner Männer und fordert die Monstrosität zum Kampf heraus. Sie scheint stark zu sein, aber eine Monstrosität gegen fünf von Euch sollte Euch doch Chancen auf einen Sieg geben.", progress = nil, completion = "Nun können wir die Sache selbst in die Hand nehmen. Ich danke Euch für Eure Hilfe, &lt;Name&gt;.\n\nDas nächste Mal, wenn wir uns sehen, werden wir uns wohl im Kampf befinden. Passt solange auf Euch auf. Wir können alle Hilfe gebrauchen, die wir bekommen können.", rewards = "ZombieschrotflinteAusbildungsbeinschützerBlutrünstige HandschuheMonströser SchulterschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27175] = {title = "Die Stätte der Heiler", objective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", description = "Die Männer und Frauen in Zugwindlager haben ehrenhafte Ziele, doch letztendlich ist der Krieg ihre Absicht. Ich möchte Euch die Möglichkeit geben, friedlichere Ziele zu verfolgen.\n\nNördlich vom kriegsgebeutelten Andorhal befindet sich die Stätte der Heiler. Der Argentumkreuzzug hat sich dort mit dem Zirkel des Cenarius verbündet. Zusammen arbeiten wir daran, das Land von der Seuche zu heilen, die hier so lange herrschte.\n\nSeid Ihr daran interessiert, Euch unserer Sache zu widmen, <Klasse>?", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27176] = {title = "Eine seltsame Scheibe", objective = "Erhaltet den Stab des Sultans und benutzt die aufwendige Scheibe, um den Schaft der Sterne zu erstellen.", description = "Die Gravuren an der Oberfläche dieser Scheibe deuten daraufhin, dass sie uralten Ursprungs ist, und doch zeigt sie keinerlei Anzeichen von Abnutzung.\n\nDas Loch am Rand ist voll mit Holzsplittern, was darauf hindeutet, dass sie dafür vorgesehen war, an einer Art Holzstab angebracht zu werden.\n\nBevor ihr sie Dr. Jones zeigt, solltet Ihr das andere Teil finden.", progress = "Ja, <Name>?", completion = "&lt;Doktor Jones setzt seine Brille auf.&gt;\n\nLasst uns das genauer betrachten, ja?", rewards = "Schulterplatten des StabsuchersSplittersichere ArmschienenKapuze des SplitterfindersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27177] = {title = "Bergungsaktion", objective = "Bergt 8 wiedergefundene Vorräte aus den durchnässten Kisten in Obsidianbrecher.", description = "Unsere Flotte wurde durch die Horde und die Naga stark geschwächt. Wir können die Männer, die ihr Leben dem Meer gelassen haben, nicht zurück zum Leben erwecken, aber nur über meine ertrunkene Leiche werde ich zulassen, dass alle unsere Ladungen auf immer verloren gehen.\n\nSchwimmt zum Obsidianbrecher südwestlich von Hochufer und bergt die Ladungen der gesunkenen Schiffe vom Meeresboden.", progress = "Wie viele der Vorräte konntet Ihr bergen?", completion = "Da seht her! Ihr konntet mehr bergen, als ich zu hoffen gewagt hatte. Damit können wir einen ganzen Trupp Marinesoldaten versorgen.\n\nWir haben die Ausrüstung. Wenn wir nun nur irgendwie unseren Kämpfern hier in Hochland Mut machen könnten ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27178] = {title = "Verstärkung der Naga", objective = "Tötet 10 Myrmidone der Schwarzschuppen oder Seerufer der Schwarzschuppen.", description = "Sie kommen aus der Tiefe des Ozeans angeglitscht, <Name>. Die Naga. Ich denke, sie haben vor, die Bastion des Zwielichts zu verstärken, und werden wahrscheinlich den Verrall nutzen, um weiter ins Land vorzudringen. Wir dürfen das nicht geschehen lassen!\n\nZeigt ihnen, dass die Ufer nun die unseren sind, und sorgt dafür, dass sie schnell wieder zurück in die dunklen Tiefen huschen.\n\nTötet die Schwarzschuppen-Naga, die sich ihren Weg durch Obsidianbrecher bahnen!", progress = nil, completion = "Das wird ihnen eine Lehre gewesen sein, &lt;Name&gt;! Cho'gall wird sich in diesem Kampf nicht auf die Naga verlassen können. Von jetzt an sind wir gegen den Schattenhammer auf uns gestellt.\n\n\n\n... Und gegen die Horde.", rewards = "FrostschwanztaillenschutzSchwarzschuppenwickelMyrmidonentöterarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27179] = {title = "Feldarbeit", objective = "Sammelt 10 uralte Tafelfragmente.", description = "Dieser bedauernswerte Pygmäe war zur falschen Zeit am falschen Ort.\n\nAls Ihr über sein Unglück sinniert, bemerkt Ihr die Symbole auf seinem Schild. Sie sind viel zu aufwendig für Pygmäengekritzel.\n\nIhr seid davon überzeugt, dass Doktor Jones ein Objekt wie dieses hochinteressant finden wird, und macht Euch auf, um weitere Fragmente wie dieses zu finden.", progress = "Was haben wir denn hier, mein Freund?", completion = "Diese Tafeln sind übersäht mit titanischen Schriftzeichen. Hier steht noch Unbekanntes geschrieben, &lt;Name&gt;!\n\nFehlende Teile eines uralten Rätsels...\n\nGute Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27180] = {title = "Ehret die Toten", objective = "Findet 6 Insignien der Verlassenen bei den Leichnamen der Veteranengardisten der Verlassenen.", description = "Ein Konvoi erfahrener Truppen und Katapulte der Verlassenen wurden heute aus dem Hinterhalt angegriffen, als sie Olsens Acker südlich von hier überqueren wollten. Ein Totalschaden: alle Einheiten wurden getötet und alle Katapulte vernichtet.\n\nDas Rudel von Blutfang ist für den Hinterhalt verantwortlich, allerdings sind sie wohl längst wieder in die Hügel geflüchtet, um sich auf ihren nächsten feigen Angriff vorzubereiten. Ihre Zeit wird kommen. Jetzt allerdings möchte ich, dass Ihr zu Olsens Acker geht und die Gefallenen ehrt.\n\nFindet die Insignien der Verlassenen.", progress = "Konntet Ihr die Insignien finden?", completion = "Ich werde mich darum kümmern, dass die Insignien auf der Stelle zurück nach Unterstadt gelangen. Der Registrator wird ihre Namen in unsere Verzeichnisse aufnehmen, so dass ihr Opfer nie in Vergessenheit gerät.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27181] = {title = "Der Schmach ein Ende bereiten", objective = "Tötet 10 Blutfangpirscher.", description = "Es scheint, als sei ein Teil der Wegelagerer hier geblieben. Lasst sie für diese Anmaßung teuer bezahlen! Tötet die Blutfangpirscher auf Olsens Acker. Für Sylvanas! Für die Horde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27182] = {title = "Der Einsiedler des Hexenhügels", objective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", description = "Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.\n\nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn \"Sumpfauge\" Jarl, machen sich bereits einige Anzeichen bemerkbar.\n\nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.\n\nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.", progress = nil, completion = "Seid Ihr hierhergekommen, um mich auszuspionieren? Nein?\n\nDann seid Ihr vielleicht ein Liebhaber der guten Küche? Gut, ich kann Eure Hilfe gebrauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27183] = {title = "Marschenfroschschenkel", objective = "Sammelt 10 Marschenfroschschenkel von riesigen Marschenfröschen.", description = "Ich koche gerne. Gute Sumpfmannskost. Frittierte Grünfroschschenkel und so.\n\nAber ich habe keine Froschschenkel mehr. Im Irrlichtanwesen wimmelt es aber von Fröschen. Riesige Marschenfrösche. Meint Ihr, Ihr könnt ein paar ihrer Schenkel besorgen? Das ist wirklich nicht viel Arbeit. Ihr müsst ihnen nur auf die Köpfe hauen und mir die Schenkel bringen.\n\nDann mach ich Eintopf, und ess den Eintopf, und Ihr könnt auch Eintopf haben.\n\nMögt Ihr Eintopf?", progress = "Gewürze. Gewürze können niemandem schaden. Oder etwa nicht?", completion = "Ah, hier ist das Gewürz! Das nenne ich einen guten Sumpfeintopf.", rewards = "FroschstiefelSumpfschienenIhr bekommt:\n\nFroschschenkeleintopf"}
MultiLanguageQuestData['de'][27184] = {title = "Jarl braucht Augen", objective = "Sammelt 20 unzerplatzte Graunebelaugen von Graunebelspinnen.", description = "Augensaft ist ein leckeres Getränk. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", progress = "Wo sind diese Augen?", completion = "Ihr habt die Augen! Ihr habt die Augen! Leckere, leckere Spinnenaugen!\n\nManche Augen... wenn man sie anstarrt, starren sie zurück. Die ess ich zuletzt. Sie leisten einem Gesellschaft... draußen im Sumpf.\n\nHallo, kleine Spinnenaugen. Hallo! Ihr seid so lecker wie Hühnchen. Glibberiges, salziges Hühnchen!\n\nMmmh.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27185] = {title = "Die Wettstreiter ausmerzen", objective = "Tötet den purpurroten Hammerschmied.", description = "Ich werd' keine Spielchen mit Euch spielen. Der purpurrote Hammerschmied des scharlachroten Kreuzzugs war bisher nicht wirklich erwähnenswert, aber nun, da er zu einem von Balnazzars Auferstandenen geworden ist, hat der Schreckenslord ihm beigebracht, alle möglichen mächtigen und dämonischen Waffen herzustellen.\n\nDie Aufgabe ist einfach. Findet die Schmiedepläne und tötet den purpurroten Hammerschmied, wenn er kommt, um sie zu holen. So können wir sicherstellen, dass ihre Armee die dämonischen Waffen nicht in die Hände bekommt. Sie sind jetzt schon viel zu stark!", progress = nil, completion = "Gut gemacht, mein Freund! Ohne die neuen Waffen sind sie genauso einfach zu töten wie damals, als sie noch lebendig waren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27186] = {title = "Jarl braucht eine Klinge", objective = "Besorgt Messerwirbels Schwert", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Schwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Diese Fischmenschen, Murlocs, oder wie auch immer die heißen... Einer von ihnen wird Messerwirbel genannt, hat ständig so ein großes Schwert bei sich, lebt nördlich von hier am Strand. Ich brauche sein Schwert!\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", rewards = "Beinkleider des FachmannsGürtel von \"Sumpfauge\"Auf Euch wartet eine dieser Belohnungen:\n\nSchilfknotenring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27187] = {title = "Ein Gefallen für die Welt", objective = "Tötet 12 räudige Hyänen.", description = "Hyänen sind im besten Fall ein Ärgernis.\n\nDiese finsteren Wesen sind bösartig veranlagt, haben alle möglichen Krankheiten und sind nicht mehr als eine Seuche auf dem Antlitz der Hundewelt.\n\nTut der Welt einen Gefallen und befreit die Wüsten von Uldum von dieser räudigen Bedrohung.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27188] = {title = "Was sucht den Hexenhügel heim?", objective = "Sammelt Informationen, indem Ihr 10 auferstandene Gebeine oder auferstandene Geister besiegt.", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", progress = nil, completion = "&lt;Mordant holt ein kleines Blatt Papier und einen Stift hervor und beginnt, sich Notizen über Eure Berichterstattung zu machen.&gt;\n\nIhr konntet herausfinden, dass sich die Geister an diesem Ort auf die Anzahl aller belaufen, die jemals auf diesem Land gelebt haben, und nicht nur auf die vorherigen Besitzer.\n\nEtwas hat sie zu Grunde gerichtet und getötet. Wer der Sache verfällt, erfährt die Wahrheit nicht, bis es zu spät ist. Wir müssen dem Ganzen ein Ende bereiten, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27189] = {title = "Der Hexenfluch", objective = "Sammelt 9 Zweige Hexenfluch am Hexenhügel.", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, <Name>. Es könnte unsere letzte Hoffnung sein.", progress = "Konntet Ihr ein paar Pflanzen finden? Wir müssen schnell handeln, bevor das Übel, das hinter dieser Heimsuchung steckt, in dieser Gegend vollends überhand nimmt.", completion = "&lt;Mordant nimmt das Pflanzenbündel von Euch entgegen.&gt;\n\nDiese entsprechen exakt der Beschreibung! Während Eurer Abwesenheit habe ich die Fackel vorbereitet. Jetzt müssen wir die Pflanzen nur noch hier am Ende befestigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27190] = {title = "Die Reinigung des Hexenhügels", objective = "Platziert die Hexenfluchfackel am Ende des Anlegstegs und besiegt das Böse, das Hexenhügel heimsucht.", description = "Die Fackel ist fertig. Platziert sie am Ende des Anlegestegs und macht Euch darauf gefasst, allem gegenüberzutreten, was erscheinen mag.\n\nIch habe keine Ahnung, was der Rauch der Fackel enthüllen wird... wenn überhaupt etwas passiert. Ich muss zugeben, dass ich dieser Art der Volksmagie nicht viel Vertrauen schenke, aber wir haben keine Zeit für irgendwas anderes. Jarl zuliebe, und auch Euch zuliebe, wünsche ich Euch viel Glück.", progress = "Ist es vorbei?", completion = "Es hat funktioniert?\n\n&lt;Mordant räuspert sich.&gt;\n\nIch meine ... es hat funktioniert! Jarl und ich stehen in Eurer Schuld, &lt;Name&gt;. Das nächste Problem ist nun der Möbelgeschmack meines Freundes, und das wird wohl nicht so einfach zu lösen sein.", rewards = "Mordants ReisetunikaGrimsbys greller GurtGeschuppte MarschenlaufschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27191] = {title = "Hungrig wie ein Oger!", objective = "Sammelt 8 Schlammflossenköpfe von den Murlocs der Schlammflossen.", description = "Hier trifft man schon ab und an jemanden. Nette Leute. Hab mal einen Oger getroffen. Oger werden hungrig, genau wie ich.\n\nIch werde nie vergessen, was er gesagt hat. Er sagte: \"Patsch großer Oger. Ich hungrig. Geht Fische hauen. Bringt Patsch Essen. Ihr füttert Patsch oder Patsch frisst Euch.\"\n\nIch hab ihm also Fische besorgt, und er hat die Fische gegessen. Und seitdem esse ich auch Fisch. Die Köpfe schmecken am besten, die sind so schön glitschig.\n\nZermalmt die Köpfe nicht. Das macht die Fische unglücklich. Traurige Köpfe schmecken nicht gut. Bringt mir glückliche Fischköpfe, und ich werde die Fischköpfe essen und auch glücklich sein.", progress = "Jarl hat Hunger. Genau wie der Oger.", completion = "Ich frag mich, wie es ist, ein Oger zu sein. Große Leute müssen mehr essen.\n\nOger müssen noch hungriger sein als ich. Das klingt wirklich nicht witzig.", rewards = "Schlammpatschs ZermalmerDreckfußstampferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27192] = {title = "Der tolle Ezra Grimm", objective = "Bergt eine Schachtel mit Ezra Grimms tollem Tabak.", description = "Männer von weit entfernten Orten wie Kul Tiras sprechen von Ezra Grimms tollem Tabak. Dieses Genussmittel wurde von jeder wichtigen Person, die Stratholme je besuchte, konsumiert. König Terenas, Uther der Lichtbringer, Hochlord Fordring ... ja, alle genossen sie Grimms Spezialität.\n\nLeider verblieb Ezra in seinem Laden, als Stratholme überfallen wurde, und er schwor auf sein Leben, dass die Geißel seinen Tabak nicht anfassen würde. Wagt Euch hinein und seht nach, ob etwas von dem Tabak übriggeblieben ist. Er ist sein Gewicht in Gold wert, das kann ich Euch versichern.", progress = "Habt Ihr welchen gefunden?", completion = "Ihr habt wahrhaftig den Schnupftabak, aus dem die Träume sind, entdeckt. Es ist fast unmöglich, den Preis für diesen historischen Tabak festzulegen.\n\nHier, nehmt diese Münzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27193] = {title = "Suchen und zerstören", objective = "Durchsucht die Bauernhäuser auf Olsens Acker.", description = "<Die Stimme der Bansheekönigin dringt erneut in Eure Gedanken ein.>\n\nSucht in den nahegelegenen Bauernhäusern nach Nachzüglern der Allianz. Haltet Eure Augen offen nach Informationen, die uns zu Crowley und Blutfang führen könnten. Sucht und zerstört alle, die sich Euch in den Weg stellen, <Name>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27194] = {title = "In die Ecke gedrängt und zermalmt!", objective = "Meldet Euch bei Meister Forteski in der Tiefenfelsmine im Silberwald.", description = "<Die Stimme der Bansheekönigin spricht zu Euch.>\n\nWir müssen schnell handeln, <Name>. Sie dürfen nicht die Gelegenheit bekommen, zu fliehen. Ich werde ein Geschwader meiner mächtigsten Soldaten zur Tiefenfelsmine schicken. Der Reiter wird sie begleiten, um sicherzustellen, dass alles nach Plan verläuft. Trefft ihn in der Tiefenfelsmine, östlich von Olsens Acker und ZERMALMT diese Ratten.", progress = nil, completion = "Ich denke mal, erst in die Enge treiben, dann zermalmen, hm?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27195] = {title = "Es gibt keinen Ausweg", objective = "Begleitet Meister Forteski durch die Tiefenfelsmine.", description = "Die Herrin hat mich beauftragt, die Bande bei dieser Aufgabe zu führen. Unser Hauptziel ist es, in die Mine einzudringen, die Ratten in die Enge zu treiben und sie alle zu töten, auch Blutfang.\n\nIhr habt uns mit der Beschaffung dieser Informationen gute Dienste geleistet, <Name>. Habt am Ruhm teil und helft uns dabei, unsere Schwerter durch ihre elenden Schädel zu jagen.\n\nLasst mich wissen, wenn Ihr bereit seid, und ich werde zum Angriff rufen.", progress = nil, completion = "WAS!?\n\n&lt;Fürstin Sylvanas kreischt.&gt;\n\nCROWLEY!!!!!\n\nIhr Bastarde. Das waren einige meiner stärksten Soldaten. Ich habe Crowley und Blutfang zum letzten Mal unterschätzt. Ganz eindeutig handelt es sich hier um Feinde, wie wir sie noch nie zuvor gesehen haben - willens, die eigenen Kämpfer in einer Falle wie dieser zu opfern. Das gab es in der Kriegsführung der Allianz noch nie.", rewards = "Streitkolben der einkalkulierten VerlusteKniehosen der verzweifelten MaßnahmenUnterschätzte ArmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27196] = {title = "Irgendetwas geht vor sich", objective = "Begleitet Harrison Jones zur Kammer der Sterne.", description = "Ihr habt bemerkenswerte Arbeit geleistet! Vor allem für jemanden, der nie einen meiner Kurse besucht hat.\n\nDiese Tafeln geben uns neue Informationen zu verschiedenen Themen.\n\nSie weisen darauf hin, dass diese Obelisken Teil eines riesigen, uralten Mechanismus sind, der diese Gegend einst vor dem Rest der Welt versteckt hielt.\n\nAußerdem zeigen sie auch auf, wie der Mechanismus wieder in Gang gebracht werden kann. Hier kommt der Schaft der Sterne ins Spiel...\n\nMacht Euch bereit, <Name>. Es gilt, Geschichte zu schreiben!", progress = "Also, mal sehen, was dieser Stab uns zeigen kann...", completion = "Das ist aber echt mal ein Ort hier!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27197] = {title = "Die Schlacht geht weiter!", objective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", description = "Es gibt Nachrichten aus Andorhal, <Name>. Die Schlacht hat wieder angefangen.\n\nUnter den Streitkräften der Allianz ist es wohl bekannt geworden, dass Ihr Euch als einer der Helden der ersten Schlacht um Andorhal hervorgetan habt. Thassarian verlangt umgehend nach Eurer Anwesenheit.", progress = nil, completion = "Es heißt, Ihr hättet den Bauern geholfen, sich zu bewaffnen. Und nun haben Sie ohne meinen Befehl angegriffen! Sie zwingen mich zu handeln.\n\nDie Schlacht geht weiter. Dieses Mal kämpfen wir gegen die Verlassenen... und ich kämpfe gegen Koltira, meinen alten Bruder von der Schwarzen Klinge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27198] = {title = "Die Truppen unterstützen", objective = "Tötet 15 Todeswachen von Andorhal.", description = "Ich bin kein Militärexperte, aber diese Schlacht scheint zu unseren Gunsten zu stehen. Unsere Verteidiger sind nicht besser als die Todeswachen unserer Gegner, aber die Bauernmiliz hat sie mit dem Angriff aus dem Hinterland überrascht. Für die Allianz!\n\nWir müssen trotzdem alles tun, was in unserer Macht steht, um einen Sieg zu sichern. Reist nach Andorhal östlich von hier und tötet die Todeswachen der Verlassenen, die mit unseren Männern kämpfen. Je schneller sie sterben, umso eher können wir Andorhal wieder unser Eigen nennen!", progress = nil, completion = "Ihr habt gut gekämpft, &lt;Name&gt;. Ich wünschte, ich hätte Eure Fähigkeiten ... und Euren Mut.", rewards = "Armschienen des NeidsGürtel der UnerschrockenenHandschuhe des FähigenAuf Euch wartet eine dieser Belohnungen:\n\nBand des Verteidigers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27199] = {title = "Asche zu Asche", objective = "Tötet 3 Kriegshauptmänner der Todeswache.", description = "Östlich von hier, tief im von den Verlassenen gehaltenen Andorhal, werdet Ihr ihre Kommandanten anfinden. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.\n\nJagt und tötet diese Kommandanten, <Name>. Die Verlassenen werden machtlos sein.", progress = nil, completion = "Gut gemacht. Jetzt, da die Kriegshauptmänner ausgeschaltet wurden, habe ich keine Ausreden mehr.\n\nBald muss ich mich Koltira im Kampf stellen, für Ehre und für Andorhal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27200] = {title = "Sirenenlied", objective = "Tötet Ophelia, die Sirene des Hochlands.", description = "Sie ist immer noch anzutreffen... Ophelia, die Sirene des Hochlands! Ihr schreckliches Lied wird Euch in die Tiefen locken. Ich habe geschworen, hier zu bleiben und meine gefallenen Besatzungsmitglieder zu rächen, <Klasse>. Wenn Ihr mich unterstützen wollt, müsst Ihr nur den Mund aufmachen.\n\nWir werden uns an den Mast binden, oh ja. Wir werden unsere Augen schließen. Wir werden unsere Ohren mit Wachs ausstopfen. Und wenn ihre schöne Illusion vergeht... werden wir angreifen.\n\nKann ich auf Euch zählen?", progress = nil, completion = "Sie hatte mich in ihrem Zauber, &lt;Name&gt;. Ich wäre nicht mit dem Leben davongekommen, wenn Ihr nicht gewesen wärt. Ich danke Euch!\n\nVielleicht kann die restliche Flotte der Allianz hier nun in Frieden vor Anker gehen ...", rewards = "Gesangabweisende SchiftungMastgebundene GamaschenWachsgefüllte KapuzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27201] = {title = "Angriff der Val'kyr", objective = "Tötet 9 niedrige Val'kyr in Andorhal.", description = "Die Val'kyr waren einst die mächtigste Waffe der Geißel. Sie waren nicht nur fähig im Kampf, sondern konnten auch benutzt werden, um Leichen in Diener der Geißel zu verwandeln. Es fällt mir schwer zu glauben, dass Sylvanas sich um der Verlassenen willen zu solchen Methoden herablässt ... \n\nWir müssen die Val'kyr aufhalten, bevor sie uns ausschalten und unsere Armee gegen uns wenden. Tötet so viele, wie Ihr finden könnt. Nehmt ein paar dieser Freiwilligen mit Euch. Wenn sie bis jetzt überlebt haben, haben sie wohl doch etwas Kampfgeschick.", progress = nil, completion = "Mit jeder Val'kyr, die Ihr tötet, rettet Ihr Dutzende unserer Männer ... und hindert die Streitmächte der Verlassenen daran, weiter zu wachsen.\n\nUnd doch machen sie weiter und weiter. Es kann sein, dass wir diese Schlacht doch nicht gewinnen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27202] = {title = "Bruder gegen Bruder", objective = "Tötet 20 Reitersoldaten der Verlassenen in Andorhal.", description = "Unsere Miliz wurde fast vollständig ausgemerzt. Nur ich und diese paar Bauern sind noch übrig.\n\nDiese beflügelten Kreaturen ... sie haben die Leichen unserer Männer genommen ... und sie in laufende, untote Leichname verwandelt! Mit jedem einzelnen, den sie von uns genommen haben, haben sie ihre eigenen Ränge verstärkt.\n\nEs fällt mir schwer es zuzugeben, aber Ihr werdet auch sie bekämpfen müssen, zusammen mit den Todeswachen und den Val'kyr. Wie sie es auch in ihrem früheren Leben gemacht haben, jagen sie in Gruppen. Nehmt ein paar der Freiwilligen mit Euch.", progress = nil, completion = "Ihr habt beherzt gekämpft, aber es bringt uns nichts. Jeder Kämpfer, der fällt, treibt ihre Streitmächte weiter voran.", rewards = "Schulterwickel des BezaubertenUnterdrückende ArmschienenMilizpikeAuf Euch wartet eine dieser Belohnungen:\n\nBand des Rudelführers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27203] = {title = "Der Mahlstrom", objective = "Geht durch das Portal in den Mahlstrom und sprecht mit Thrall.", description = "Dank den Geistern, dass Ihr hier seid, <Name>.\n\nWir wissen nicht, wie lange wir den Riss im Mahlstrom noch erhalten können.\n\nUnsere mächtigsten Mitstreiter, die von Thrall angeführt werden, können den Einriss kaum aufhalten.\n\nDer letzte Stand ist, dass unsere einzige Hoffnung darin liegt, durch die Öffnung zu steigen und zu versuchen, sie von der anderen Seite aus zu stabilisieren.\n\nIch werde ein Portal herbeizaubern. Benutzt es und meldet Euch bei Thrall, so bald Ihr könnt.", progress = nil, completion = "&lt;Thralls Muskeln spannen sich an, als urtümliche Energie ihn durchfließt. Sein Blick gleitet zu Euch, er bemerkt Eure Anwesenheit.&gt;\n\nEs freut mich, Euch zu sehen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27204] = {title = "Aradne", objective = "Tötet Aradne auf dem Turm im westlichen Teil von Andorhal.", description = "Unsere letzte Hoffnung auf einen Sieg ist die Bezwingung der Val'kyr. Bisher habt Ihr gute Arbeit geleistet... Ihr seid aber auch nur <ein Mann/eine Frau> gegen wortwörtlich Dutzende, die Zerstörung auf das Schlachtfeld bringen.\n\nEine riesige Val'kyr sitzt auf einem Turm südlich von hier... Ihr könnt sie von hier sehen. Wenn wir sie beseitigen, werden die restlichen Val'kyr sich vielleicht zerstreuen.\n\nEs ist unsere einzige Hoffnung. Nehmt ein paar von Grants Männern mit. Ihr werdet für diesen Kampf Schutz benötigen.", progress = nil, completion = "Ich habe Euren Sieg von hier unten verfolgt. Ihr habt gut gekämpft, doch letztendlich war alles umsonst.\n\nDie Val'kyr und die Verlassenen kämpfen weiter und werden uns bald übermannen. Wir haben Andorhal verloren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27205] = {title = "Die Verderbtheit der Verlassenen", objective = "Findet heraus, was Thassarian anschaut.", description = "Wir haben diese Schlacht fast gewonnen, <Name>. Ich kann den Sieg förmlich schmecken. Die Verlassenen hatten nie ein...\n\nWas zum Teufel ist das!?", progress = nil, completion = "Val'kyr? Koltira hat Val'kyr zu diesem Kampf mitgebracht? Ist er verrückt geworden?\n\nNein, das ist nicht Koltiras Werk. Das war Sylvanas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27206] = {title = "Weh dir, Andorhal", objective = "Berichtet Kommandant Ashlam Ehrenschlag von den Ereignissen der Schlacht von Andorhal.", description = "Begebt Euch nach Süden, nach Zugwindlager. Berichtet Kommandant Ashlam Ehrenschlag von allem, was hier vorgefallen ist.\n\nIch? Ich gehe nach Westen, nach Tirisfal.\n\nMeine Schlacht ist noch nicht abgeschlossen. Ich habe ein Treffen mit einer Harpyie, die sich die Bansheekönigin nennt ... und ich werde herausfinden, was sie Koltira angetan hat.", progress = nil, completion = "Verloren? Nein... als Nächstes werden sie sich dann wohl Zugwind vornehmen. Das war ein schwerer strategischer Rückschlag für die Pläne der Allianz in Lordaeron.\n\nNun gut. Ich werde das Ergebnis dieser Schlacht König Wrynn melden. Er wird wohl nicht gerade glücklich darüber sein.", rewards = "ZugwinddolchZugwindstabZugwindtunikaZugwindbeinschützerZugwindschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27208] = {title = "Der Schreckenslord Balnazzar", objective = "Tötet Balnazzar.", description = "Mit dem Untergang des Scharlachroten Kreuzzugs entließ der getarnte dämonische Anführer Balnazzar den besessenen Körper des Obersten Kreuzfahrers Dathrohan und begab sich auf einen Amoklauf, bei dem er auch den letzten überlebenden Kreuzfahrer in den Tod riss. Dann nutzte er seine nekromantischen Kräfte, um sie zu widerwärtigen untoten Sklaven zu machen.\n\nBalnazzar nennt diese neue Armee die Auferstandenen. Wir können nicht zulassen, dass diese Armee noch größer wird. Diese Krieger sind äußerst mächtig, und im Gegensatz zu Arthas' Geißel wird Balnazzar seine Streitmächte nicht zurückhalten. Tötet ihn, solange wir noch in der Lage dazu sind, <Klasse>.", progress = nil, completion = "Es ist gut, dass wir Balnazzar fürs Erste aufhalten konnten. Es wird nicht mehr lange dauern, bis seine Armee ganz Stratholme eingenommen hat, und ihm so ein mächtiges Herzstück für sein neues, unheiliges Reich bietet.", rewards = "Beinschützer von StratholmeDathrohans StreitkolbenBalnazzars HornBalnazzars BalgIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27210] = {title = "Verräter unter uns", objective = "Konfrontiert 5 Aufwiegler der Deserteure in Theramore.", description = "Schön, Euch zu sehen, <Klasse>. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.\n\nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.\n\nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich glaube, wir haben sie überrascht. Ihre Agenten wähnten sich innerhalb der Stadt vermutlich in Sicherheit.\n\nMit der Zeit werden die Aufwiegler zurückkehren und ihre Lügen wieder verbreiten. Wir werden die Zeit, die Ihr uns verschafft habt, nutzen, um die Deserteure weiter auszusperren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27211] = {title = "Propagandakrieg", objective = "Erhaltet das Propagandamaterial der Deserteure vom Schiff am Ende der Docks in Theramore.", description = "Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure offenbar auf einem Schiff zu den Docks geschmuggelt haben.\n\nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kajüte des Kapitäns.", progress = "Konntet Ihr die restlichen Propagandahandzettel finden und beschlagnahmen?", completion = "&lt;Die SI:7-Agentin nickt zustimmend.&gt;\n\nAusgezeichnet. Jetzt müssen wir die Deserteure nur noch diskreditieren, damit sie in Theramore nie wieder Fuß fassen können. Ich weiß auch schon wie.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27212] = {title = "Diskreditierung der Deserteure", objective = "Verteilt verfälschte Handzettel an 6 Wachen von Theramore.", description = "Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.\n\nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals wieder Fuß zu fassen.\n\n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>\n\nFangt doch schon einmal an, während ich den nächsten Schritt plane.", progress = "Ich dachte, ich hätte Gelächter bei den Kasernen gehört. Habt Ihr die Handzettel verteilt, die ich Euch gegeben habe?", completion = "&lt;Calia kichert, als Ihr von der Reaktion der Wachen auf das Propagandamaterial berichtet.&gt;\n\nGenau wie ich gehofft hatte! Ich bin mir sicher, dass jeder Agent der Deserteure, der versucht Theramore zu infiltrieren, sofort ausgelacht wird!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27213] = {title = "Das Ende der Deserteure", objective = "Besiegt Gavis Grauschild auf dem Schiff südöstlich von Theramore.", description = "Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.\n\nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.", progress = nil, completion = "Gavis' Forderung ist nicht so haarsträubend wie sie scheint. Wenn man sie richtig behandelt, gelingt es Lady Jaina vielleicht sogar die Deserteure wieder in unsere Gemeinschaft zu integrieren. Doch diese Entscheidung obliegt alleine ihr.\n\nEs war mir eine große Freude mit Euch zu arbeiten, &lt;Name&gt;! Ohne Eure Hilfe wäre die gesamte Operation sicherlich nicht halb so glatt gelaufen. Ich werde Euch in meinem Bericht an Sturmwind lobend erwähnen, so dass alle wissen, dass es Euer Einsatz war, der der Bedrohung durch die Deserteure ein Ende gesetzt hat.", rewards = "Stiefel des ScharmützlersGesellenhelmPrachtmeerumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27214] = {title = "Beunruhigende Berichte", objective = "Erstattet Hauptmann Wymor bei der Späherwacht Bericht.", description = "Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.\n\nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.", progress = nil, completion = "&lt;Der Hauptmann versucht ganz offensichtlich Eure Fähigkeiten einzuschätzen.&gt;\n\nIhr habt also von dem Schiffswrack an der Küste gehört? Gut, ich könnte noch etwas Hilfe gebrauchen, um meinen Verdacht gegenüber den Überlebenden zu bestätigen. Willkommen an Bord, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27215] = {title = "Der Einsiedler beim Irrlichtanwesen", objective = "Sprecht mit \"Sumpfauge\" Jarl im Irrlichtanwesen.", description = "Es gibt da einen Burschen - die Einheimischen nennen ihn \"Sumpfauge\" Jarl - der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nFolgt der Straße von Theramore aus in Richtung Nordwesten, und Ihr werdet das Irrlichtanwesen am Hexenhügel finden, bevor die Straße in Richtung Westen abbiegt.", progress = nil, completion = "Runter von meinem Rasen! Es sei denn, Ihr möchtet dem alten Sumpfauge ein bisschen beim Kochen helfen. Was meint Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27216] = {title = "Der alte Leuchtturm", objective = "Sprecht mit Babs Zischeldrill am Leuchtturm auf der Insel östlich von Theramore.", description = "Der alte Leuchtturm östlich von hier ist schon seit Langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, ihn wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann reibungsloser zu den Docks gelangen werden. Was kann ich dagegen schon einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", progress = nil, completion = "Gut. Ich kann jegliche Hilfe gebrauchen. Das Wichtigste ist, die Lampe wieder zu entzünden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27217] = {title = "Drescheröl", objective = "Sammelt 4 Behälter mit Drescheröl von den Düsterdreschern unter den Docks von Theramore.", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch weniger elegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Sie sind unterhalb der Docks von Theramore zu finden.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", progress = "Konntet Ihr das Drescheröl bekommen?", completion = "Ich habe immer noch meine Zweifel, aber momentan ist das die einzige Lösung. Sobald wir sie zum Laufen gebracht haben, werden wir sicherlich die Zeit finden, um die Lampe auch anderweitig mit Energie zu versorgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27218] = {title = "Heimtückische Bewohner der Tiefe", objective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", progress = "Was darf es heute sein? Der Barsch ist ausgezeichnet.", completion = "Nun ja, mir dieses Buch zukommen zu lassen, war ganz schön aufmerksam von der alten Babs. Ich weiß nicht, ob Ihr ein wenig darin geblättert habt, aber in den Geschichten steckt schon die ein oder andere Wahrheit. Seefahrer erfinden so was nicht einfach, versteht Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27219] = {title = "Ist das wahr?", objective = "Sprecht mit Nat Pagle bei Nats Angelplatz in Düstermarschen.", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut lachen musstet. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran sein könnte?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in Tidenbucht, südwestlich jenseits der Bucht der Düstermarschen.", progress = nil, completion = "Ihr wollt also mehr über Meeresungeheuer erfahren? Hmm ... also, ich mache Euch einen Vorschlag. Es wird aber viel Alkohol im Spiel sein und für Euch könnte es ein bisschen peinlich werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27220] = {title = "Nats Abmachung", objective = "Schmiert Euch mit Pagles Fischpaste, extra stark ein und schwimmt dann hinaus in die Tidenbucht.", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", progress = "Nicht vergessen, kommt erst zurück, wenn Euch etwas gebissen hat!", completion = "Nicht schlecht. An Eurer Stelle würde ich allerdings so schnell wie möglich ein Bad nehmen.\n\nJetzt zu Eurem Meeresungeheuer...\n\nNehmt Euch ruhig ein Bier oder zwei, während ich Euch die Geschichte erzähle.", rewards = "Ihr bekommt:\n\nDunkelmondspezialmischung"}
MultiLanguageQuestData['de'][27221] = {title = "Oh, es ist wahr!", objective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit gesundem Menschenverstand dergleichen tun.\n\nIhr solltet Euch also darum kümmern. Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", progress = nil, completion = "&lt;Ihr berichtet von Eurem Erlebnis mit Nat Pagle, seid jedoch bemüht, den Teil der Geschichte mit dem 'Ködertest' auszulassen.&gt;\n\nNun, es scheint, als haben wir etwas zu tun. Ich mache mich an die Vorbereitungen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27222] = {title = "Bezwingt Tethyr!", objective = "Benutzt die Mörser, um Tethyr zu besiegen.", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde allerdings nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Ich gebe zu, dass ich beim ersten Anblick des Biests meine Zweifel hatte, dass wir die Docks verteidigen können, aber Ihr habt die Verteidiger bestens zusammengehalten!", rewards = "Schiftung der schnellen WindeTurm von TheramoreMeeresungeheuerharpuneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27223] = {title = "Vergeltung", objective = "Tötet den Unverziehenen und Timmy den Grausamen.", description = "Dort, wo die Marktgasse auf die Feststraße trifft, werdet Ihr auf den Unverziehenen treffen. Wenn Ihr alle auf dem Kreuzzüglerplatz tötet, werdet Ihr auch Timmy den Grausamen erwischen. Diese beiden ehemaligen Champions haben den Unschuldigen hier gegenüber schreckliche Taten vollbracht, um unheilige Macht zu erlangen.\n\nIhr müsst sie beide besiegen, um Stratholme von ihrer finsteren Anwesenheit zu befreien. Seid wachsam, denn sie waren zu Lebzeiten mächtige Kämpfer, und durch den Erhalt ihrer neuen dunklen Kräfte wurden sie nur noch stärker.", progress = nil, completion = "Erhaltet dies als Belohnung. Ich hab es in der Rüstung einer Geißel gefunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27225] = {title = "Aufforderung von Ander Germaine", objective = "Sprecht mit Ander Germaine in der Kommandozentrale von Sturmwind.", description = "Ander Germaine hat verlauten lassen, dass er Euch für Euren meisterhaften Umgang mit den Waffen und Eurer Zuschreibung zur Allianz ehren möchte. Macht Euch auf nach Sturmwind und verlasst das Altstadtviertel durch den südlichen Ausgang. Ihr werdet ihn in seiner Kommandozentrale finden. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27226] = {title = "Um ein Seebärenhaar", objective = "Weckt 8 orcische Seebären auf.", description = "Dem Kriegshäuptling sei Dank, dass Ihr hier seid, <Name>. Mir ist ein schwerwiegender Fehler mit den Seebären unterlaufen und ich brauche Eure Hilfe, um die Sache wieder gerade zu biegen.\n\nIch habe sie stocknüchtern losgeschickt, um gegen die Worgen zu kämpfen, die von der Insel Fenris kamen. Sie haben die Bestien angegriffen und haben ordentlich was einstecken müssen. Viele sind gefallen, aber ein paar leben noch und kämpfen nun um ihr Leben.\n\nBringt dieses Bierfass zu den Verfallenen Feldern östlich von hier und seht zu, dass kein Schluck übrig bleibt.", progress = nil, completion = "AHA! Ich wusste es! Da haben wir wohl wieder etwas gelernt. Wir werden nicht wieder so versagen. Ich werde sicherstellen, dass immer Bier an vorderster Front bereitsteht.", rewards = "Biergetränkte RobenSeebärengürtelTreter des GrabmalsDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Auras\n\nIhr bekommt:\n\nStützgebräu"}
MultiLanguageQuestData['de'][27227] = {title = "Baron Aurius Totenschwur", objective = "Tötet Baron Aurius Totenschwur.", description = "Diese Kapelle ist das letzte Licht in der wachsenden Dunkelheit. Ras Frostraunen nahm sich auf dem Schlachthof sein Leben und schlitzte vor dem Lichkönig sein Gesicht in ein makabres Lächeln. Der Lichkönig nahm sich seiner an und machte ihn zu dem Lich, der jetzt Scholomance heimsucht.\n\nDer Ort, an dem diese Gräueltat geschah, ist nun heiliger Boden der Geißel, und wurde vom Lichkönig mit der dunkelsten aller Magie gesegnet. Baron Aurius Totenschwur, der neue Herrscher von Stratholme, bewacht diesen Ort und führt die grausame Arbeit seines Meisters fort. Tötet ihn, ohne zu zögern.", progress = nil, completion = "Stratholme wird zum Symbol für alles Gute in dieser Welt werden. Ihr habt meinen Dank für Eure Arbeit in dieser Mission.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStatue des VorbildsBuch des VorbildsGötze des VorbildsRelikt des Vorbilds\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27228] = {title = "Mann gegen Monstrosität", objective = "Tötet Ramstein den Verschlinger.", description = "Tief im Inneren werdet Ihr Ramstein den Verschlinger finden. Ich wage es kaum, Euch von den Gräueltaten zu erzählen, die dieses Monster vollbracht hat. Ihr müsst nur wissen, dass er den gesammelten Zorn zahlloser verirrter Seelen zu Gesicht bekommen soll; Zorn, den Ihr über ihn bringen werdet.\n\nHabt keine Gnade. Seid standhaft in Eurer Wut.", progress = nil, completion = "Die Macht, mit der Ihr Ramstein getötet habt, verdient meinen Respekt. Wenn echte Wut in den Taten zu sehen ist, kann wohl selbst die Geißel Angst empfinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27229] = {title = "ZERMATSCHT DIE BRUTKÖNIGIN", objective = "Beschafft den Pedipalpus der Brutkönigin.", description = "<Der folgende Text ist in sehr großer Schrift geschrieben.>\n\nSPINNEN IN NORDHÖHLE BÖSE. VERGIFTEN OGER. OGER WERDEN KRANK. SCHLECHT!\n\nGROSSE RIESENSPINNE IN HÖHLE MACHT MEHR SPINNEN. MEHR SPINNEN SCHLECHT!\n\nTÖTET GROSSE SPINNE, AUFHALTEN NEUE SPINNEN. TÖTET GROSSE SPINNE, GROSSE BELOHNUNG! GUT!\n\n<Eine primitive Skizze wurde unter der Nachricht geschmiert.>", progress = "Seid Ihr wegen des Schilds hier?\n\nIch möchte nicht darüber sprechen, es sei denn, Ihr habt einen Beweis für die Tötung.", completion = "Bei Grom - bin ich froh, dass es vorbei ist. Wenn Ihr das Schild gelesen habt, ist Euch vielleicht klar, wie verzweifelt ich war, nachdem ich versucht hatte, mit diesen schwerfälligen Trotteln zu kommunizieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27230] = {title = "Waffen für den Krieg", objective = "Tötet den Schwertschmied der schwarzen Wache.", description = "Die Geißel sind Meister im Schmieden mächtiger Waffen für ihre Krieger, und das macht es für unsere Männer schwieriger, sie zu töten! In der Nähe der Ziggurat von Baroness Anastari sind Schmiedekunstpläne, die der Oberste Schwertschmied nutzen wird, um eine äußerst mächtige Waffe für Lord Aurius zu schmieden.\n\nWir werden verhindern, dass diese Waffe geschmiedet wird, und gleichzeitig dafür sorgen, dass sie auch keine normalen Waffen mehr herstellen werden! Nehmt die Schmiedekunstpläne an Euch, und tötet den Schwertschmied der schwarzen Wache, wenn er kommt, um die Pläne zu verteidigen. Das wird unsere Aufgabe erleichtern.", progress = "Ihr müsst den Schwertschmied töten! Los!", completion = "Großartig! Wir werden durch ihren Verlust einer verlässlichen Bezugsquelle für Waffen siegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27231] = {title = "Verstärkung aus Fenris", objective = "Tötet 10 Worgen des Hügellands.", description = "Diejenigen, die Euren Angriff auf die Insel Fenris überlebten, konnten das Blut des Wolfes trinken. Sie wurden zu wilden Worgen, die nichts anderes als Rache im Sinn haben. Nun schwimmen sie über den Lordameresee und greifen meine Seebären an. Viele wurden bereits getötet. Die Worgenmonster müssen aufgehalten werden!\n\nMacht Euch auf den Weg zur verfallenen Fähre östlich von hier und tötet die Worgen des Hügellands, die diese Gegend heimsuchen. Sobald Ihr sie getötet habt, macht Euch auf den Weg zur Kommunikationskonsole der Horde bei den Docks. Ich werde mich mit Euch in Verbindung setzen.", progress = nil, completion = "&lt;Hatchets Kommunikationsgerät rauscht.&gt;\n\nHatchet hier, sind alle tot?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27232] = {title = "Rot gefärbte Gewässer ...", objective = "Tötet 50 Worgen des Hügellands mit der Kanone der Horde.", description = "<Das Kommunikationsgerät brummt.>\n\nDie Worgen, die Ihr getötet habt, waren der Spähtrupp. Hunderte von ihnen sind auf dem Weg! Es scheint, als haben Crowley und Blutfang allen Menschen in Lordaeron das Blutopfer angeboten.\n\nNehmt eine von diesen Kanonen der Horde und schickt sie dorthin zurück, wo sie herkommen. Färbt die Wasser des Lordameresees rot mit ihrem Blut!", progress = nil, completion = "Auch wenn Ihr viele der neuen Worgen getötet habt, können wir sicher sein, dass noch viel mehr von ihnen erscheinen werden. Ihr Angriff wurde jedoch geschwächt. Gute Arbeit, &lt;Name&gt;!", rewards = "Schuhe der roten WasserBlutopferplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27233] = {title = "Die Stätte der Heiler", objective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", description = "Nun kann ich die Ausbildung selbst in die Hand nehmen. Falls Ihr nach Arbeit sucht, kann ich Euch empfehlen, der Straße nach Nordwesten zu folgen. Die Cenarischen Druiden und der Argentumkreuzzug haben dort auf Dalsons altem Hof ihr Lager aufgeschlagen. Vielleicht können sie Euch beschäftigen, bis wir hier wieder Hilfe benötigen.", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27234] = {title = "Defias in Düstermarschen?", objective = "Erhaltet die Befehle der Defias von Garn Mathers.", description = "Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden alle rote Kopftücher. Das ist das Symbol der Defias!\n\nAnscheinend hält sich ihr Anführer auf einer großen Insel in der Nähe der Küste nordöstlich des Turms auf. Tötet ihn, und nehmt alle Unterlagen an Euch, die Ihr bei ihm findet.", progress = "Konntet Ihr ihren Anführer finden?", completion = "&lt;Hauptmann Wymor nimmt die Befehlspapiere entgegen und liest sie durch.&gt;\n\nWas könnte wohl mit 'wertvoller Fracht' gemeint sein? Die Defias haben öfter kleine Schmuggelaktionen in Sturmwind durchgeführt, aber das hier scheint in einer ganz anderen Größenordnung zu sein. Die Sprache, in der diese Befehle verfasst wurden, ist die eines Reichens oder Adligen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27235] = {title = "Renn McGill", objective = "Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe Schreckensmoorküste.", description = "Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.\n\nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.\n\nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.", progress = "Seid gegrüßt, <Klasse>. Was führt Euch hierher?", completion = "&lt;Renn liest die Befehle durch.&gt;\n\nEs war also wirklich wertvolle Fracht auf dem Schiff! Wir müssen sie finden, bevor die Defias uns zuvorkommen. Diese Jungs sind keine Taucher, aber wir brauchen einen Teil ihrer Ausrüstung, damit Ihr mir helfen könnt, die Fracht zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27236] = {title = "Tauchausrüstung aus zweiter Hand", objective = "Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in Düstermarschen.", description = "Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mithilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese \"Leihgabe\" kommt.\n\nSucht diese Insel nach einer Kiste mit Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!", progress = "Mal sehen, was Ihr so von den Defias \"leihen\" konntet.", completion = "Oha, die Ausrüstung ist in schlechterer Verfassung, als ich gedacht hatte, und das Werkzeug...\n\nNaja, ich habe gesagt, dass ich es für Euch einsatzbereit machen kann, also mache ich mich besser mal an die Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27237] = {title = "Bergt die Fracht!", objective = "Sammelt 1 geborgene Geldkassetten.", description = "Nun, ich konnte die Ausrüstung so reparieren, dass Ihr damit zumindest eine Weile lang tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.\n\nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Taucherhelm funktioniert, solltet Ihr versuchen, Teile des Wracks zwischen hier und Alcaz auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Die Hydras dort sind gefährlich.", progress = "Habt Ihr bei der Durchsuchung der Wrackteile etwas über die Fracht der Defias in Erfahrung bringen können?", completion = "&lt;Renn durchwühlt die Inhalte der Geldkassetten, die Ihr geborgen habt.&gt;\n\nGute Arbeit. Sehen wir nach, ob die 'wertvolle Fracht' auch hier drin ist ...", rewards = "Purpurrote BarbuteFleischreißerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27238] = {title = "Jaina muss davon erfahren", objective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", description = "Ihr müsst Lady Jaina sofort von unserem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann ist es schwierig, herauszufinden, wer es ist und ob diese Person noch am Leben ist!\n\nEines ist jedoch sicher, <Name>. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.", progress = nil, completion = "Ihr und Renn habt ausgezeichnete Arbeit geleistet, diese Informationen zu Tage zu bringen und sofort Bericht zu erstatten. Jetzt müssen wir den Fund bestätigen. Es würde schwerwiegende Ausmaße annehmen, wenn wir falsch liegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27239] = {title = "Beobachtet die Insel Alcaz", objective = "Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten.", description = "Offenbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Dazu bräuchten wir allerdings eine ganze Brigade von Soldaten.\n\nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.\n\nDie Insel birgt den Schlüssel zum Geheimnis darüber, inwiefern die Defias in diese Entführung verwickelt sind.", progress = nil, completion = "&lt;Lady Jaina hört aufmerksam zu, als Ihr von Euren Funden der Luftbeobachtung berichtet.&gt;\n\nEin Runenzirkel, Drachkin? Die Defias haben sich mit IHR verbündet? Der Verräterin?\n\n&lt;Lady Jaina beruhigt sich und bereitet sich vor, die Situation zu erklären.&gt;", rewards = "Handgelenksschützer des BogenschützenSumpfgasstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27240] = {title = "Beweis des Verrats", objective = "Sprecht mit Jaina, sobald Ihr bereit seid, nach Sturmwind zu reisen und König Varian Wrynn zu treffen.", description = "Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen die Defias, die ihren Plan ausgeführt haben, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.\n\nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, <Name>.", progress = nil, completion = "Es waren die Defias, die Onyxia bei diesem Plot unterstützt haben?\n\n&lt;Das Gesicht des Königs wird rot vor Wut, und er ballt seine Hände zu Fäusten.&gt;\n\nIhr und Lady Jaina habt Sturmwind an diesem Tag einen großen Dienst erwiesen. Die Verräter werden nicht lange genug leben, um ihre Verbrechen zu bereuen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27241] = {title = "Rückkehr zu Jaina", objective = "Kehrt zu Lady Jaina Prachtmeer in Theramore zurück.", description = "Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer ein treuer Freund und loyaler Verbündeter gewesen.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", progress = nil, completion = "Ich habe keine Zweifel daran, dass der König jedes einzelne Wort ernst gemeint hat, als er Euch von seinen Plänen unterrichtete, die Defias ein für alle Mal zu vernichten. Er ist kein Mann leerer Versprechen, und die Feinde Sturmwinds sollten das wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27242] = {title = "Raptorenfänger", objective = "Benutzt den strapazierfähigen Strick, um 6 Blutsumpfraptoren oder Blutsumpfkreischer zu fangen.", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. An Eurer Stelle würde ich sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf werden.", progress = "Konntet Ihr diese Raptoren einfangen?", completion = "Ihr seht ein wenig zerkratzt aus, aber das sollten keine schlimmen Wunden sein. Ihr seid sicherlich in einem besseren Zustand als die Grimmtotem in Kürze sein werden, wenn wir unsere neuen Raptorenfreunde auf sie loslassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27243] = {title = "Lasst die Raptoren los", objective = "Platziert den Raptorköder in der Nähe der Windmühle im Dorf der Schwarzhufe.", description = "Jetzt, da wir unsere Raptoren haben, ist der nächste Schritt, sie zu einem Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem ... nun, eigentlich ist es völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren sollten sich um den Rest kümmern, falls das Training funktioniert hat.", progress = nil, completion = "&lt;Der Unteroffizier versucht gar nicht erst, sein Grinsen zu unterdrücken.&gt;\n\nGut. Das sollte den einen oder anderen Angriff verhindern.", rewards = "WappenschulterschutzAuf Euch wartet eine dieser Belohnungen:\n\nBuch des AdeptenAnhänger der Wildheit\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27244] = {title = "Der verlorene Bericht", objective = "Bringt den Bericht des Spions zu Nazeer Blutlanze in Brackenwall.", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.\n\nAls Ihr das Pergament überflogen habt, ist klar, dass es zum orcischen Spionagemeister in Brackenwall gebracht werden muss.", progress = "Habt Ihr etwas für mich?", completion = "Gute Arbeit, &lt;Name&gt;. Unser Agent Marg Nachtauge war außerhalb von Theramore stationiert. Seine Aufgabe war es, die Stadt auszuspionieren. \n\nDas ist sein jüngster Bericht und könnte sein letzter sein; nach Eurer Aussage fürchte ich, dass Marg im Sumpf sein Ende fand...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27245] = {title = "Gefangene der Grimmtotem", objective = "Erlangt die Schlüssel der Grimmtotem von den Taurendruiden der Grimmtotem im Dorf der Schwarzhufe und benutzt sie, um 5 Gefangene von Theramore zu befreien.", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, <Klasse>, aber bringt mir meine Männer lebend zurück.", progress = nil, completion = "Die befreiten Gefangenen sind bereits auf dem Heimweg vom Dorf der Schwarzhufe. Die Informationen, die der Hauptmann von den Gefangenen erhalten wird, werden uns in unserem nächsten Kampf gegen die Grimmtotem einen Vorteil verschaffen.\n\nIhr habt den Dank meiner Männer und mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27246] = {title = "Der Orcbericht", objective = "Bringt den Spionbericht zu Leutnant Aden in Theramore.", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst ... und sieht wichtig aus.", progress = "Habt Ihr etwas zu berichten?", completion = "Hm ... Mein Orcisch ist nicht sehr gut, aber dieses Schriftstück sieht aus wie ein Report, der von einem orcischen Spion geschrieben wurde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27247] = {title = "Hauptmann Mumm", objective = "Bringt den Spionbericht zu Hauptmann Garran Mumm.", description = "Hauptmann Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, <Name>. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Hauptmann befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", progress = "Ihr habt etwas für mich?", completion = "Der Report von einem Orcspion! Wie habt Ihr das gefunden? Egal - erst sollten wir sehen, was hier steht ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27248] = {title = "Mission nach Morastwinkel", objective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", description = "Das Dampfdruckkartell hat vor Kurzem im südlichen Teil von Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Wärt Ihr bereit, die Reise für uns aufzunehmen?", progress = nil, completion = "Theramore ist also am Handel interessiert? Das ist kein Angebot, dass ich abschlagen möchte. Uns gehen die Vorräte hier auch langsam aus, und wir können alle Geschäftskontakte brauchen, die wir finden können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27249] = {title = "Untersuchung der Ruinen", objective = "Sprecht mit Inspektor Tarem beim Gasthaus \"Zur Süßen Ruh\".", description = "Der arme James, er ist nie wirklich über die Zerstörung des Gasthauses \"Zur Süßen Ruh\" und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Monster, die dafür verantwortlich sind, zu finden.\n\nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertigwerden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.\n\nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig. Auf dieser Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.", progress = nil, completion = "Gut, dass Hauptmann Mumm endlich auch andere Leute in die Untersuchung einbindet.\n\nIch habe hier im Umkreis reflektierenden Staub verwendet.\n\nEr wird ungewöhnliche Gegenstände und Markierungen ans Licht bringen. So könnt Ihr Euch besser auf Eure Anstrengungen konzentrieren. Betrachtet alles genau, was vom Staub erleuchtet wird.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReflektierender Staub\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27250] = {title = "WIEDERVERARBEITUNG - SCHLECHTE KOPIE", objective = "Sprecht mit Vincent Hyal im Hafen von Menethil.Bevor ich im Blauen Eremiten angefangen habe, wurde ich von einem der besten Köche und Gastwirte ausgebildet, die ich je getroffen habe. James Hyal hieß er. Meinen gesamten Besitz und Alles, was ich in meinem Leben je erreicht habe, verdanke ich ihm.\n\nIch frage mich, wie es ihm geht. Sein Bruder Vincent und er arbeiten in einer Taverne im Hafen von Menethil, aber ich habe schon länger nichts mehr von ihm gehört.\n\nFalls Ihr Euch jemals auf dem Weg nach Menethil wiederfindet, könntet Ihr im vielleicht meine Grüße ausrichten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Bevor ich im Blauen Eremiten angefangen habe, wurde ich von einem der besten Köche und Gastwirte ausgebildet, die ich je getroffen habe. James Hyal hieß er. Meinen gesamten Besitz und Alles, was ich in meinem Leben je erreicht habe, verdanke ich ihm.\n\nIch frage mich, wie es ihm geht. Sein Bruder Vincent und er arbeiten in einer Taverne im Hafen von Menethil, aber ich habe schon länger nichts mehr von ihm gehört.\n\nFalls Ihr Euch jemals auf dem Weg nach Menethil wiederfindet, könntet Ihr im vielleicht meine Grüße ausrichten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27251] = {title = "Sie nennen ihn den lächelnden Jim", objective = "Sprecht mit Hauptmann Garran Mumm auf der obersten Etage der Wehrzitadelle.", description = "Der alte Jim da tut mir leid, ich kann mir nicht helfen. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, ein wunderbares Lokal.\n\nAber eigentlich möchte ich nicht darüber sprechen. Besprecht es mit Hauptmann Mumm, wenn es sein muss. Ihr findet ihn auf der obersten Etage der Wehrzitadelle, der großen Kaserne östlich von Lady Jainas Turm.", progress = nil, completion = "James Hyal ist sein richtiger Name. Er hat ein Gasthaus am Randes des Brachlands eröffnet. Er wollte Reisenden einen netten Ort für Übernachtungen anbieten...\n\nKönnte schon sein, dass er zu hochfliegende Pläne hatte, aber das Gasthaus lief eine Weile ganz gut. Dann haben wir die Kontrolle über die Straßen in den Marschen verloren und die Ogers haben alles übernommen.\n\nJames war zu stur, um seinen Traum gegen die Sicherheit innerhalb unserer Mauern einzutauschen und das Gasthaus \"Zur Süßen Ruh\" wurde niedergebrannt. Wir untersuchen den Vorfall noch, hatten bisher aber nicht viel Glück. Wenn Ihr helfen wollt, seht, was Ihr in den Trümmern finden könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27252] = {title = "Der Schwarze Schild", objective = "Bringt den geschwärzten Eisenschild zu Hauptmann Garran Mumm in Theramore.", description = "Ein Eisenschild, von dem Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", progress = "Habt Ihr in den Ruinen vom Gasthaus \"Zur Süßen Ruh\" Beweise gefunden?", completion = "Hm, ich bin kein Experte, was die Herstellung von Waffen und Rüstung angeht. Wie man sie handhabt, ja, aber nicht, wie man sie herstellt.\n\nDieser Schild scheint mir sehr gewöhnlich zu sein, bis auf den Schaden durch das Feuer, das im Gasthaus wütete.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27253] = {title = "Untersuchung der Ruinen", objective = "Erforscht das Gasthaus \"Zur Süßen Ruh\" an der Grenze Brachlands in Düstermarschen.", description = "Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses \"Zur Süßen Ruh\" stoßen.\n\nTheramore hat einen Ermittlungsbeamten entsandt, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Ich habe in dem Gasthaus einen Spion untergebracht und ich vertraue nicht darauf, dass diese Menschen kompetent genug sind, um in Erfahrung zu bringen, was damals passiert ist.\n\nEgal was Ihr findet, seht zu, dass der Ermittlungsbeamte es nicht in die Hände bekommt. Wir werden uns der Sache selbst annehmen.", progress = nil, completion = "&lt;Der Inspektor mustert Euch voller Geringschätzung und Argwohn.&gt;\n\nVerlasst diesen Ort, Bote, oder ich werde dafür sorgen, dass ich das nächste Mal mit einer Gefolgschaft Wachen herkomme, um Euch zu verdeutlichen, was ich meine.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReflektierender Staub\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27254] = {title = "Der Schwarze Schild", objective = "Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.", description = "Ein Eisenschild, von dem Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", progress = "Was habt Ihr da, <Name>? Beweise aus den Ruinen vom Gasthaus \"Zur Süßen Ruh\"?", completion = "Ich gebe zu, dass Menschen nicht die besten Inneneinrichter sind, aber würden sie wirklich einen einfachen Eisenschild wählen, um ihren Kamin zu schmücken? Vielleicht wurde der Schild von denjenigen hinterlassen, die das Gasthaus in Flammen setzten.\n\nEine Warnung? Eine Drohung?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27255] = {title = "Der Schwarze Schild", objective = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", description = "Hmm ... Ich sehe nichts Außergewöhnliches an diesem Schild. Wir sollten ihn Do'gol dem Schmied zeigen. Vielleicht kann er uns mehr verraten, aber ich würde keine Hoffnung hegen ...", progress = "Ihr habt etwas für mich, <Klasse>?", completion = "Das ist ein guter Schild. Sehr stark, schwer, wirklich gut. Aber Do'gol kann damit nichts anfangen. Ich mache Schilde, und kaufe sie nicht, &lt;Name&gt;.\n\nIhr solltet das wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27256] = {title = "Der Schwarze Schild", objective = "Sammelt 5 Säuregiftbeutel von Graunebelspinnen.", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Graunebelspinnen sollte dafür ausreichen. Die Spinnen haben sich in einer alten Mine in den Graunebelhöhlen nordwestlich der Siedlung eingenistet. Bringt mir ihre Giftsäcke und ich kann den Schild reinigen.", progress = "Habt Ihr die Beutel von den Spinnen?", completion = "Ich mag Spinnen nicht, die so groß sind, dass ich sie nicht einfach zerquetschen kann.\n\nDanke, dass Ihr das erledigt habt, &lt;Name&gt;. Jetzt muss ich die Giftbeutel nur aufreißen und das Gift auf den Schild schütten ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27257] = {title = "Der Schwarze Schild", objective = "Sprecht mit Krog in Brackenwall.", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln ...\n\nHm, schwer zu lesen, sieht aber aus wie der Name Mosarn. Nie von ihm gehört. Vielleicht kennt Krog ihn. Krog kennt viele Leute.", progress = nil, completion = "Mosarn? Kommt mir bekannt vor... Ich komm' nicht drauf. Vielleicht fällt es mir später wieder ein.\n\nIst wahrscheinlich nicht so wichtig. Ein Schild kann von überall herkommen und nichts bedeuten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27258] = {title = "Der Schwarze Schild", objective = "Zeigt den geschwärzten Eisenschild Mosarn in Donnerfels.", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Donnerfels. Ich wusste, dass ich den Namen irgendwo schon einmal gehört habe.\n\nAus Dankbarkeit hat mir der Irdene Ring eine Rüstung verliehen, die von Mosarn angefertigt wurde. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild erzählen, den er hergestellt hat.\n\nEs ist nicht viel, aber da wir von Reethe nichts Nützliches in Erfahrung bringen konnten, ist es alles, was wir vorweisen können.", progress = "Hallo, <Klasse>. Wie kann ich Euch helfen?", completion = "Ja, Ihr liegt richtig. Das ist ein Schild, den ich angefertigt habe.\n\nAllerdings kann ich Euch leider nicht sehr viel mehr darüber erzählen, &lt;Name&gt;. Ich stelle so viele Schilder und Rüstungen her, dass ich nicht über alle Bescheid wissen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27259] = {title = "Verdächtige Hufabdrücke", objective = "Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", description = "Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind deutlich erkennbar, und weitere Abdrücke sind im weichen Schlamm des Sumpfs zu sehen, wenn man ganz genau hinsieht.", progress = nil, completion = "Hufabdrücke... Ich denke, das waren möglicherweise die Stacheleber. Oder vielleicht ein Zentaur. Im Brachland gibt es recht viele von ihnen und es dürfte ihnen nicht schwerfallen, so eine Tat zu verüben\n\nHabe ich übrigens erwähnt... Nicht nur das Gasthaus wurde niedergebrannt. Die Frau und das Kind des Besitzers wurden getötet. Ganz üble Sache, das.\n\nNichtsdestotrotz, ich werden Kagoro schicken, um nachzusehen, wo die Spuren hinführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27260] = {title = "Leutnant Paval Reethe", objective = "Bringt Reethes Abzeichen zu Krog in Brackenwall.", description = "Unter dem Geröll erregt ein Funkeln Eure Aufmerksamkeit. Nachdem Schmutz und Asche von dem Objekt gewischt wurden, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", progress = "Habt Ihr weitere Hinweise auf die Geschehnisse im Gasthaus \"Zur Süßen Ruh\" gefunden?", completion = "Hmm ... also das ist interessant.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27261] = {title = "Befragt Reethe", objective = "Folgt Ogron und sprecht mit Reethe.", description = "Es hat lange gedauert, aber ich habe Reethe gefunden. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach dem langen Aufenthalt im Sumpf könnte er verrückt geworden sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", progress = nil, completion = "Hmpf. Es ist gut, dass Reethe nicht mehr im Sumpf herumlungert. Ein Jammer, dass Menschen so empfindlich sind, dass er sich nicht von einer kleinen Pfeilwunde erholen konnte.\n\nOffenbar hat dieser Teil des Rätsels nirgendwohin geführt und wir müssen es anderswo versuchen.", rewards = "AugenschüreisenSchmetterprügelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27262] = {title = "Verdächtige Hufabdrücke", objective = "Berichtet Hauptmann Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", description = "Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind deutlich erkennbar, und weitere Abdrücke sind im weichen Schlamm des Sumpfs zu sehen, wenn man ganz genau hinsieht.", progress = nil, completion = "Hufabdrücke also? Es stimmt, in den Ländern nahe der Düstermarschen gibt es außergewöhnlich viele Zentauren. Bei unseren kurzen Ausflügen ins Brachland haben wir ihre Lager und Besitztümer im ganzen Gebiet verstreut gefunden.\n\nIch werde Falgran Hastil, einen unserer Spurenleser, ausschicken, um nachzusehen, wohin die Spuren führen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27263] = {title = "Leutnant Paval Reethe", objective = "Bringt Reethes Abzeichen zu Hauptmann Garran Mumm in Theramore.", description = "Unter dem Geröll erregt ein Funkeln Eure Aufmerksamkeit. Nachdem Schmutz und Asche von dem Objekt gewischt wurden, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", progress = "Habt Ihr in den Ruinen vom Gasthaus \"Zur Süßen Ruh\" etwas Interessantes gefunden?", completion = "Das Abzeichen einer Wache bringt nie gute Neuigkeiten mit sich.\n\nManchmal handelt es sich um jemanden, der im Kampf gefallen ist, und dann liegt es an mir, die Nachrichten der trauernden Familie zukommen zu lassen. Manchmal finden wir nicht einmal heraus, was passiert ist. Und dann gibt es noch Situationen, die sogar schlimmer sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27264] = {title = "Leutnant Paval Reethe", objective = "Findet bei Adjutant Tesoran in Theramore mehr über Reethe heraus.", description = "Ich kenne den Namen Leutnant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjutant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", progress = nil, completion = "Hallo, &lt;Name&gt;. Möchtet Ihr Informationen über ein bestimmtes Mitglied der Wache von Theramore? Reethe, sagt Ihr?\n\nGebt mir einen Moment, damit ich das richtige Buch suchen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27265] = {title = "Lord Grayson Schattenbruch", objective = "Sprecht mit Lord Grayson Schattenbruch in der Kathedrale des Lichts in Sturmwind.", description = "Lord Grayson Schattenbruch, einer der führenden Paladine im Realm, hat Euch zu einem persönlichen Gespräch aufgefordert. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.\n\nIhr solltet Euch umgehend nach Sturmwind aufmachen und ihn in der Kathedrale des Lichts aufsuchen.", progress = nil, completion = "Es erfreut mich, dass meine Nachricht Euch erreicht hat, &lt;Name&gt;. Wir haben viel zu besprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27266] = {title = "Wulf ruft", objective = "Sprecht mit Wulf Hansreim in Sturmwind.", description = "Wulf Hansreim beaufsichtigt die Ausbildung und Koordination der Jäger im Dienst von Sturmwind. Er hat Euch zu einem persönlichen Gespräch gebeten. Reist nach Sturmwind, sobald es Euch möglich ist, und verlasst das Altstadtviertel durch das südliche Tor, um zu seinem Quartier zu gelangen.\n\nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27267] = {title = "Nehmt zum SI:7 Kontakt auf", objective = "Sprecht mit Osborne dem Nachtmensch in Sturmwinds Altstadt.", description = "Es scheint, als zeigten die Anführer von SI:7 Interesse an Eurem Fortschritt und Euren Diensten für die Allianz. Osborne der Nachtmensch, ein hochrangiges Mitglied von SI:7, wünscht ein Gespräch mit Euch. Ihr findet ihn im südlichen Teil von Sturmwinds Altstadt.\n\nIch weiß nicht, was Osborne von Euch will, aber es schien wichtig.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27268] = {title = "Eilt zur Kathedrale", objective = "Sprecht mit Hohepriesterin Laurena in der Kathedrale des Lichts in Sturmwind.", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, <Name>. Es scheint, als wünsche Hohepriesterin Laurena Euch in der Kathedrale des Lichts am Kathedralenplatz in Sturmwind zu sprechen. Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise nach Sturmwind nicht aufzuschieben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27269] = {title = "Der Tempel des Mondes", objective = "Sprecht mit Tyrande Wisperwind im Tempel des Mondes in Darnassus.", description = "Ich habe eine dringende Nachricht aus Darnassus für Euch. Die Nachricht ist von der Hohepriesterin Elunes, Tyrande Wisperwind, persönlich! Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise zum Tempel des Mondes in Darnassus nicht aufzuschieben und die Hohepriesterin so schnell wie möglich zu treffen.", progress = nil, completion = "Willkommen im Tempel des Mondes, &lt;Name&gt;. Ich bin froh, dass Ihr meiner Aufforderung so schnell nachkommen konntet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27270] = {title = "Eine Audienz bei der Scharfseherin", objective = "Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind.", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, <Name>. Es sieht aus, als würde Scharfseherin Umbrua darum bitten, mit Euch zu sprechen, wenn Ihr das nächste Mal in der Stadt seid.\n\nDer Bote hat mir keine Erklärung für die Einladung der Scharfseherin gegeben, aber Ihr solltet nach Sturmwind reisen und Scharfseherin Umbrua im Goldenen Fass im Zwergenviertel treffen, sobald Ihr könnt.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich bin froh, dass Ihr meine Einladung angenommen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27271] = {title = "Reise zum Sanktum des Magiers", objective = "Sprecht mit Maginor Dumas im Sanktum des Magiers in Sturmwinds Magierviertel.", description = "Soeben kam eine Nachricht aus Sturmwind an, <Name>. Einer der angesehensten Magier Sturmwinds, Maginor Dumas, hat Euch zu einem Besuch im Magierviertel in Sturmwind eingeladen. Ihr werdet ihn im Sanktum des Magiers oben auf dem großen Turm im Herzen des Magierviertels finden.\n\nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27272] = {title = "Demisette schickt Kunde", objective = "Sprecht mit Demisette Cloyce im Gasthaus \"Zum Geschlachteten Lamm\" in Sturmwinds Magierviertel.", description = "Es scheint, als haben die Ältesten in unseren Rängen von Euren Fortschritten und Eurer Hingabe erfahren, <Name>. Demisette Cloyce, eine der ältesten und geachtetsten Mitglieder unseres Kreises, hat Kunde geschickt, dass Sie Euch sprechen möchte. Ihr solltet eine Einladung wie diese sehr ernst nehmen. Die Meisten sprechen nur während ihrer Kurse mit ihr, aber wenn Sie Euch zu einem persönlichen Gespräch lädt, muss es sich um etwas Wichtiges handeln.\n\nEilt zurück nach Sturmwind und sucht sie im Gasthaus \"Zum Geschlachteten Lamm\" im Magierviertel auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27273] = {title = "Eine Einladung aus Mondlichtung", objective = "Sprecht mit Loganaar in Nachthafen in Mondlichtung.", description = "Ihr habt den Botschafter aus Mondlichtung gerade verpasst, <Name>. Er hat wenig Preis gegeben, meinte aber, er habe eine dringende Nachricht von Loganaar, einem der ehrwürdigen Ausbilder des Zirkels des Cenarius. Brecht umgehend nach Mondlichtung auf, <Name>. Es scheint sich um eine wichtige Angelegenheit zu handeln.\n\nIhr werdet Loganaar in dem Dorf Nachthafen auffinden.", progress = nil, completion = "Gut, dass Ihr sicher in Nachthafen angekommen seid, &lt;Name&gt;. Ich heiße Euch mit der Gastfreundschaft des Zirkels des Cenarius willkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27274] = {title = "Die Chefchirurgin", objective = "Sprecht mit Chefchirurgin Schnittschweißer im Zwergendistrikt in Sturmwind.", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, <Name>. Chefchirurgin Schnittschweißer hat Euch gebeten, sie in Sturmwind aufzusuchen. Die Nachricht gibt keinerlei Informationen über das Anliegen der Chefchirurgin, Ihr solltet die Reise nach Sturmwind jedoch nicht aufschieben. Sucht Chefchirurgin Schnittschweißer im Zwergendistrikt der Stadt auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27275] = {title = "Wiedervereint", objective = "Sprecht mit der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.", description = "Wir haben uns darum gekümmert, die Schildwache zu heilen und neu auszustatten. Ich habe sie bereits wieder zum Einsatz geschickt.\n\nGeht zurück nach Düsterwolkengipfel. Sie wird Euch dort treffen.", progress = nil, completion = "Schön Euch wiederzusehen, &lt;Name&gt;. Lasst uns den Grimmtotem Angst vor der Göttin einjagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27276] = {title = "Wiedervereint", objective = "Sprecht mit dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.", description = "Wir haben uns darum gekümmert, den Kriegerhelden zu heilen und neu auszustatten. Ich habe ihn bereits wieder zum Einsatz geschickt.\n\nGeht zurück nach Düsterwolkengipfel. Er wird Euch dort treffen.", progress = nil, completion = "Ich fühle mich durch Eure Gegenwart geehrt, &lt;Name&gt;. Lasst uns den Grimmtotem Angst vor der Erdenmutter einjagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27277] = {title = "Eine Audienz bei Ureda", objective = "Sprecht mit Ureda in der Kluft der Schatten.", description = "Ich habe eine dringende Nachricht aus Orgrimmar für Euch, <Name>. Die berühmte Magierin Ureda wünscht, Euch in Orgrimmar zu empfangen. Ich bin mir nicht sicher, worum es hier geht, aber wenn ich Ihr wäre, würde ich so schnell wie möglich in die Hauptstadt reisen und Ureda in der Kluft der Schatten aufsuchen.", progress = nil, completion = "Ah, gut. Meine Nachricht hat Euch anscheinend erreicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27278] = {title = "Ruf der Grimmschlag", objective = "Sprecht mit Ormak Grimmschlag im Tal der Ehre.", description = "Ein Bote aus Orgrimmar hat gerade eine Nachricht für Euch gebracht. Ich soll Euch ausrichten, dass Ormak Grimmschlag, der Jägerlehrer aus Orgrimmar, Euch treffen möchte.\n\nReist schnell nach Orgrimmar und sucht Ormak im Tal der Ehre auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27279] = {title = "Die Zerschmetterte Hand", objective = "Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.", description = "Ein Bote aus Orgrimmar kam gerade mit einer Mitteilung für Euch an. Gordul, der leitende Schurkenlehrer aus Orgrimmar, schickt nach Euch. Ihr müsst Euch sofort nach Orgrimmar begeben und ihn in der Kluft der Schatten aufsuchen.\n\nWenn Gordul ein Treffen einberuft, ist es weise, der Aufforderung zu folgen. Lasst ihn nicht warten, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27280] = {title = "Der Traumsucher ruft", objective = "Sprecht mit Kardris Traumsucher im Tal der Weisheit.", description = "Kardris Traumsucher, eine Schamanin, deren Weisheit bei der Horde legendär ist, hat Kunde geschickt, dass sie Euch sprechen möchte. Der Botschafter ließ nicht verlauten, was so dringlich sei. Er meinte nur, Ihr solltet schnellstmöglich nach Orgrimmar aufbrechen und Kardris im Tal der Weisheit aufsuchen. Sie wird dort mit anderen Ausbildern zusammentreffen, um junge Schamanen zu unterrichten.", progress = nil, completion = "Ich sehe, Ihr seid sowohl folgsam als auch talentiert, &lt;Name&gt;. Erhaltet diese Tugenden aufrecht, und Ihr werdet es in der Horde weit bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27281] = {title = "Grezz Zornfaust", objective = "Sprecht mit Grezz Zornfaust im Tal der Ehre.", description = "Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, <Name>. Grezz Zornfaust, der ehrenhafte Kriegerlehrer der Stadt, hat nach Euch verlangt. Diese Aufforderung zu ignorieren wäre unklug.\n\nReist schnell nach Orgrimmar zum Tal der Ehre, wo Grezz auf Eure Ankunft wartet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27282] = {title = "Zevrosts Befehl", objective = "Sprecht mit Zevrost in der Kluft der Schatten in Orgrimmar.", description = "<Name>, soeben kam die Nachricht, dass Ihr wieder in Orgrimmar gebraucht werdet. Zevrost, einer der erfahrensten Hexenmeisterlehrer in der Kluft der Schatten, hat etwas Wichtiges mit Euch zu besprechen. Es scheint sich um etwas zu handeln, dass nicht aufgeschoben werden kann.\n\nMacht Euch auf den Weg und geht zurück nach Orgrimmar. Sprecht so bald wie möglich mit ihm.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27283] = {title = "Eine Reise nach Mondlichtung", objective = "Sprecht mit Loganaar in Nachthafen.", description = "Wie Ihr sicher wisst, ist Mondlichtung die Heimat des Zirkels des Cenarius, der Bruderschaft der Druiden. Alle Bewohner leben dort unter dem Frieden des Cenarius. Ausbilder Loganaar hat die Einladung nach Mondlichtung unter Anbetracht dieser Tatsache ausgesprochen.\n\nIhr werdet ihn in dem Dorf Nachthafen auffinden.", progress = nil, completion = "Willkommen in Mondlichtung, &lt;Name&gt;. Ich habe mich auf unser Treffen gefreut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27284] = {title = "Der Schwarze Schild", objective = "Zeigt den geschwärzten Eisenschild Caz Doppelspross in Theramore.", description = "Ich kann Euch leider nicht weiterhelfen, <Name>, aber ich kann Euch verraten, wer Euch helfen könnte. Caz Doppelspross, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", progress = "Etwas, das ich mir anschauen soll?", completion = "Hm ... das ist ein interessantes Stück Eisen! Ganz sicher wurde der Schild von keinem der Schmiede hergestellt, die ich auf dieser Seite des Meeres kenne. Und ich kann auch mit Sicherheit sagen, dass die Arbeit nicht von mir stammt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27285] = {title = "Der Schwarze Schild", objective = "Sprecht mit Hauptmann Garran Mumm in Theramore.", description = "Ah, das hier hätte ich fast übersehen ... Der Lederriemen auf der Rückseite hat das Feuer wohl nicht überstanden, aber ich glaube, er wurde für eine große Person angefertigt. Ich würde auf einen Tauren tippen.\n\nAber mehr kann ich leider auch nicht ausmachen. Sagt Hauptmann Mumm, es tut mir leid, dass ich nicht mehr helfen konnte.", progress = nil, completion = "Das ist nicht viel, mit dem wir etwas anfangen können, aber wir werden es im Kopf behalten. Hoffentlich werden uns noch andere Informationen etwas mehr Klarheit verschaffen und uns einen Überblick über das, was geschehen ist, verschaffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27286] = {title = "Daelins Männer", objective = "Kehrt mit den Informationen über Reethe zu Hauptmann Garran Mumm in Theramore zurück.", description = "Reddon ... Oh, da haben wir ihn! Leutnant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Prachtmeer über das Meer kamen. Trat mit sechzehn Jahren den Marinesoldaten von Kul Tiras bei. Herausragende Dienste, Beförderungen ...\n\nIst als vermisst eingetragen.", progress = nil, completion = "Vermisst? Das ist Tesorans Art, \"Verräter\" zu sagen.\n\nZweifellos ist er einer dieser Narren, die Admiral Daelin so blindlings treu ergeben sind, dass sie zu Verrätern wurden. Ist das nicht eine delikate Ironie? Die Deserteure beschuldigen uns, die Allianz zu verraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27287] = {title = "Die Deserteure", objective = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in Düstermarschen.", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der Verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nDer örtliche Anführer der Deserteure ist ein Mann namens Balos Jacken. Seht zu, ob Ihr Informationen von ihm bekommen könnt.\n\nSeid gewarnt, <Name>. Er könnte sich als harte Nuss herausstellen.", progress = nil, completion = "Hat Mumm Euch geschickt? Konnte seine schmutzige Arbeit nicht selber machen, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27288] = {title = "Die Deserteure", objective = "Sprecht mit Hauptmann Garran Mumm in Theramore über Reethe.", description = "Reethe? Der Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, als dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nNun, ich habe Euch also geholfen ... Nun könnt Ihr uns helfen und vergessen, dass Ihr uns gefunden habt.", progress = nil, completion = "Ich werde Leutnant Kaldenbrunn schicken, damit er sich um die Deserteure an der Verlassenen Wacht kümmert. Zusätzlich werde ich ihn instruieren, Reethe zu suchen. Die Marschen sind nicht so groß und auch dort gibt es Spuren. Es sollte ihm nicht allzu schwerfallen, ihn zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27289] = {title = "Mumms Bericht", objective = "Bringt Mumms Bericht zu Lady Jaina Prachtmeer in Theramore.", description = "Ihr habt gute Arbeit geleistet, <Name>, die Beste, die ich je von einem Amateur sah.\n\nLady Prachtmeer bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.\n\nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27290] = {title = "Zum Gefechtsstand der Verlassenen", objective = "Meldet Euch in Gilneas am Gefechtsstand der Verlassenen bei Todespirscherkommandant Belmont.", description = "Die Zeit, Crowley, Blutfang und jeden Hund unter ihrem Kommando zu töten, ist gekommen. Dazu muss man so gerissen und genau planen, wie wir es uns nie haben träumen lassen!\n\nAls einer der Soldaten, denen ich am meisten vertraue, müsst Ihr, <Name>, zum Gefechtsstand der Verlassenen in Gilneas gehen und Euch bei Todespirscherkommandant Belmont melden. Ich habe Belmont bereits mit meinen Plänen vorausgeschickt. Er erwartet Eure Ankunft.\n\nArthura wird Euch zum Gefechtsstand der Verlassenen begleiten. Sagt mir, wenn Ihr bereit seid, und ich werde Euch auf den Weg bringen.", progress = nil, completion = "Na, wenn das nicht Bröttinub ist!\n\nIch hoffe, Ihr seid bereit zum Kampf, denn das ist alles, was Euch in diesem Höllenloch erwartet. Wir sind mitten im umkämpften Gebiet und diese Straßenköter von Worgen wollen nicht nachgeben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27291] = {title = "Endlich Frieden", objective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder Gerechtigkeit erfahren haben.\n\n<Hauptmann Mumm holt einen kleinen Blumenkranz hervor.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren, auch, wenn wir sie nicht selbst kontaktieren können. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Grabsteine auf dem Friedhof nördlich der Tore von Theramore.", progress = nil, completion = "&lt;Hauptmann Mumm hat ein kleines Lächeln im Gesicht, als Ihr von den Ereignissen am Familiengrab der Hyal berichtet.&gt;\n\nEs beruhigt mich zu wissen, dass sie es verstanden haben. Ihr habt aber nichts von James gesagt, oder?\n\nIch werde ihm die Nachricht seiner Frau ausrichten, aber ich bezweifle, dass er sie verstehen wird.", rewards = "Schneide des KampfzauberersStahlverstärkte HalsbergeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27292] = {title = "Rückkehr zu Krog", objective = "Sprecht mit Krog in Brackenwall.", description = "Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, sich an detaillierte Informationen zu jedem Stück zu erinnern.\n\nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, auch die Grimmtotem hegen eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.", progress = nil, completion = "Er hat wirklich gesagt, dass die Grimmtotem seine besten Kunden sind? Mosarn hat uns weit mehr geholfen, als er ahnt. Mit dieser Menge an Hinweisen, die die Grimmtotem belasten, dürften wir unsere Hauptverdächtigen gefunden haben.", rewards = "Purpurrote BarbuteFleischreißerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27293] = {title = "Die Verschwörung der Grimmtotem", objective = "Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem ganz zu sehen.", description = "Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Wir haben gesehen, wie sich hochrangige Vertreter der Grimmtotem an Morden und Entführungen beteiligten, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten ihr nächstes Ziel sein.\n\nDas Dorf der Schwarzhufe im Nordosten, in der Nähe von Blaumoor, ist eine große neue Siedlung der Grimmtotem. Alle ihre Anführer, die Ältesten, dürften Anordnungen von Donnerfels bei sich tragen. Versucht, an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.", progress = "Konntet Ihr die Befehle ausfindig machen?", completion = "&lt;Krog überfliegt die Schlachtpläne.&gt;\n\nIch bin mir sicher, dass die Grimmtotem einen Angriff auf die Menschen planen. Allerdings weiß ich nicht, was ihre Absichten uns gegenüber sind. Wir wussten nichts von diesen Plänen und bedauern deswegen nun den Verlust eines guten Mannes. Ich kann mich nicht darauf verlassen, dass wir nicht auch auf ihrer Liste sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27294] = {title = "Kein bloßer Zufall", objective = "Sammelt 7 Waffen der Schwarzhufe im Dorf der Schwarzhufe.", description = "Wir haben die Ruinen des Gasthauses so gut es ging nach Beweisen abgesucht. Die Ergebnisse unserer Ermittlungen beunruhigen mich, aber wir müssen die Wahrheit erfahren.\n\nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe nordöstlich von hier. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.", progress = "Was konntet Ihr im Dorf der Schwarzhufe finden?", completion = "&lt;Krog betrachtet die Waffen und die Rüstung, die Ihr aus dem Dorf der Schwarzhufe mitgebracht habt.&gt;\n\nDas ist ganz unverkennbar die Arbeit von Mosarn. Ihn weiter auszufragen würde zu viel Aufmerksamkeit erregen, aber bei Angelegenheiten mit den Grimmtotem haben wir etwas mehr Handlungsfreiheit.", rewards = "GrimmtotemumhangAuf Euch wartet eine dieser Belohnungen:\n\nGlühender Turmalinring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27295] = {title = "Sucht Tabetha auf", objective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", description = "Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zu Übungszwecken noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für das Feuer im Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, noch immer auf freiem Fuß sind.\n\nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.\n\nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.", progress = nil, completion = "&lt;Tabetha lächelt.&gt;\n\nKrog möchte, dass ich die Grimmtotem ausfindig mache, ja? Nun gut, dafür braucht es aber keine Magie.\n\nAnscheinend haben wir einen gemeinsamen Feind. Die Grimmtotem haben in der Nähe einen Außenposten errichtet und sind mir und meinen Schülern ein ständiger Dorn im Auge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27296] = {title = "Brennt den Grollhornposten nieder!", objective = "Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems förmlich angekündigt.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Unsere Nachricht dürfte bei den Grimmtotem problemlos angekommen sein.\n\nWas Euch betrifft, so solltet Ihr Eurer Kontaktperson in Brackenwall von Eurem Erfolg berichten. So wie ich ihn kenne, wird ihm der Nachgeschmack der Rache gefallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27297] = {title = "Das Walten der Gerechtigkeit", objective = "Kehrt zu Krog in Brackenwall zurück.", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden, allerdings habe ich den Eindruck, dass Euch das nicht weiter stört. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus \"Zur Süßen Ruh\" bestraft.\n\nGeht und berichtet Eurem Anführer, dass die Rache gestillt wurde.", progress = nil, completion = "&lt;Krog hört sich Euren Bericht an.&gt;\n\nIch bin beeindruckt, &lt;Name&gt;. Ich hatte vermutet, dass die verbrecherischen Grimmtotem nicht so einfach auszumachen sind. Die Allianz ist wirklich unfähig.\n\nUm ehrlich zu sein wollte ich eigentlich nur eine Antwort auf den Tod einer meiner Männer, aber in diesem Fall hatte ich wohl mehr Glück, als ich erwartet hatte. Falls die Grimmtotem sich rächen wollen, wird dies wohl durch einen Schlag gegen die Allianz passieren. Vielleicht haben wir sogar bald genügend Streitmächte, um diesen Haufen Dreck ein für alle Mal von unseren Küsten zu vertreiben.", rewards = "Schneide des KampfzauberersStahlverstärkte HalsbergeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27298] = {title = "Sucht Meister Pyreanor auf", objective = "Sprecht mit Meister Pyreanor im Tal der Stärke in Orgrimmar.", description = "Meister Pyreanor, ein erfahrener Blutritter und Berater des Kriegshäuptlings, verlangt nach Eurer Anwesenheit in Orgrimmar. Er zeigt Interesse an Eurer Ausbildung, <Name>, und es ist von äußerster Wichtigkeit, dass Ihr sofort mit ihm sprecht.\n\nDie Nachricht, die ich erhalten habe, gibt keinen Grund für Euren Besuch an, aber Ihr solltet Euch umgehend nach Orgrimmar aufmachen. Ihr könnt Meister Pyreanor in der Burg im Zentrum vom Tal der Stärke finden.", progress = nil, completion = "Ich habe viel von Euch gehört, &lt;Name&gt;. Ihr habt in der Horde eine strahlende Zukunft vor Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27299] = {title = "Zerrissener Boden", objective = "Tötet 3 Tentakel von Iso'rath.", description = "Ihr werdet nich' viel Überzeugungsarbeit leisten müss'n, um uns gegen den Schattenhammer aufzubringen - wir mögen die eh nicht. Wir sind aber schon wegen 'ner Schlacht hier, also brauchen wir vielleicht Eure Hilfe, bevor wir uns der Festung zuwenden können.\n\nDie Schattenhammerkultisten haben Iso'rath schon aus dem Boden im Süden geholt, habt Ihr sicher bemerkt. Seine Tentakel sind überall um uns 'rum aus dem Boden geschossen. Wir könnten 'ne helfende Hand gebrauchen, um sie niederzuschlagen. Was meint Ihr?", progress = "Glück mit den Tentakeln gehabt?", completion = "Danke, &lt;Klasse&gt;. 'N bisschen Platz zum Atmen hilft wirklich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27300] = {title = "Zurückstoßen", objective = "Tötet 12 Schattenhammer in den Ruinen des Lagers der Drakgor.", description = "Die Schattenhammerkultisten haben 'ne Siedlung des Drachenmals im Süden zerstört und halten von dort aus Beschwörungsrituale ab. Gebt ihnen keine Gelegenheit, zur Ruhe zu kommen und zu ihren Zaubern zurückzukehren. Bringt die Schlacht zu ihnen!", progress = nil, completion = "Rache is' bittersüß, aber ich bin froh, dass jemand so mächtig wie Ihr die Sache in die Hand nimmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27301] = {title = "Ungebrochen", objective = "Findet Erdenruferin Yevaa in den Ruinen von Drakgor.", description = "Wir bereiten ein Ritual vor, dass dabei helfen könnte, Iso'rath zu zerstören, die alte, von den Göttern gezüchtete Monstrosität, die vom Schattenhammer aus den Tiefen geholt wurde. Die Zeit läuft uns jedoch davon, denn unsere mächtigste Mitstreiterin wurde bei dem Angriff auf ihr Lager festgehalten.\n\nErdenruferin Yevaa befindet sich in den Ruinen südlich von hier. Sie ist noch am Leben, davon bin ich überzeugt. Bitte, rettet sie. Wenn einer von uns Eure Hilfe verdient, dann ist sie es.", progress = nil, completion = "Den Elementen sei Dank, dass Ihr gekommen seid. Haben meine Brüder Euch geschickt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27302] = {title = "Einfache Lösungen", objective = "Sammelt 10 Scheiterhaufenbrandölfässer.", description = "Ich bin neu hier. Ganz neu. Aber wisst Ihr was? Ich hab wenigstens Aussichten!\n\nIch hab ein paar Freunde, Schamanen, die haben Großes vor sich, aber die sind so festgefahren; sie vertrauen gänzlich auf Elemente und vergessen, die normalen Rohstoffe in ihrer Umgebung zu nutzen.\n\nBei den Ruinen südlich von hier habe ich gesehen, wie die Schläger des Schattenhammers Fass um Fass entflammbares Öl abtransportiert haben. Sie haben das Öl benutzt, um unsere Siedlung niederzubrennen. Ich schlage vor, wir tun es ihnen gleich.", progress = "Ich frage mich, was passiert, wenn man das Zeug über einen Elementar kippt. Ob ein Super-über-Leuchtfeuer-Elementar entsteht? Ich glaube fast schon. Das müssen wir ausprobieren.", completion = "Ha, genau das hab ich gemeint! Stellt Euch nur vor, was man damit alles machen kann! Mir fällt sicher nur ein Bruchteil ein. Aber die Nutzungsmöglichkeiten, die mir in den Sinn kommen, gefallen mir auf jeden Fall!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27303] = {title = "Mitleid mit den Gebundenen", objective = "Sammelt 5 Fleischbrennerherzen.", description = "Natürlich hatte ich kein Bedürfnis, dort zu bleiben, aber es gab dort ein paar Materialien, die wir für das Ritual brauchen ... Ich war nicht schnell genug, alles einzusammeln, und das hat dann dazu geführt, dass sie mich geschnappt haben.\n\nIch werde zum Kreis zurückkehren, aber ich wäre Euch sehr dankbar, wenn Ihr an meiner Stelle diese Aufgabe abschließen könntet. Wir brauchen die Herzen der gebundenen Feuerelementare, die die Schattenhammerkultisten im westlichen Teil des Lagers gefangen halten.\n\nDie Elementare können nicht gerettet werden, aber durch dieses Opfer können sie Rache ausüben.\n\nTrefft mich im Lager.", progress = "Konntet Ihr die Herzen einholen?", completion = "Ich danke Euch, &lt;Name&gt;. Ihr seid sehr fähig. Ich bin Euch äußerst dankbar, dass Ihr Euch entschlossen habt, uns zu helfen.", rewards = "HerzrauchbeinplattenTreter des rauchenden SchrittesFleischverbrannte RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27304] = {title = "Der Sonne hinterher", objective = "Sprecht mit Sonnenwandler Atohmo im Tal der Weisheit in Orgrimmar.", description = "Sonnenwandler Atohmo schickt Kunde aus Orgrimmar. Er möchte Euch sprechen, wenn Ihr in der Stadt seid. Ich muss Euch wohl kaum daran erinnern, dass Atohmo ein ehrenhaftes Mitglied unseres Orden ist und seine Aufforderung nicht ignoriert werden sollte.\n\nWenn Ihr das nächste Mal in Orgrimmar seid, begebt Euch zum Tal der Weisheit und sprecht mit ihm.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27305] = {title = "Von Liebe und Familie", objective = "Findet 'Von Liebe und Familie'.", description = "In der Scharlachroten Bastion befindet sich ein Gemälde, dass für Hochlord Tirion Fordring persönlich äußerst wertvoll ist. Sucht nach einem Gemälde unseres Zwillingsmondes. Wenn Ihr die oberste Farbschicht abkratzt, werdet Ihr darunter das Meisterwerk 'Von Liebe und Familie' vorfinden.\n\nMöge das Licht Euch den Weg weisen. Oh, bitte seid äußerst vorsichtig mit dem Gemälde.", progress = "Das Gemälde, <Name>. Habt Ihr das Gemälde?", completion = "Meister Fording wird überglücklich sein, das Gemälde zurück zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27306] = {title = "Sprecht mit Ogron", objective = "Findet Ogron südöstlich von Brackenwall.", description = "Ich kenne diesen Menschen, Paval Reethe. Lächerlich, selbst für einen seiner Art. Er ist ein Deserteur und hat seine Kameraden hintergangen. Jetzt versteckt er sich in den Wäldern.\n\nIch habe Ogron geschickt, um ihn ausfindig zu machen. Ein paar von den anderen glauben, dass er von unseren Vorräten gestohlen hat. Ich glaube, Ogron ist in Richtung Südosten unterwegs.", progress = nil, completion = "Ogron? Jo, das bin ich.\n\nSchhh. Seid leise. Kroks hören Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27310] = {title = "Keine Waffen für Grimmtotem!", objective = "Brennt 8 Grimmtotemwaffenständer nieder.", description = "Nun gut, diese Feiglinge wollen kämpfen? Mal sehen, wie sie das ohne jegliche Waffen anstellen wollen.\n\nIhr habt doch sicherlich eine Fackel oder etwas in der Art.\n\nBrennt ihre Waffenregale nieder. Brennt sie alle nieder!", progress = nil, completion = "Wir werden sehen, wie sie ihren Krieg jetzt führen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27311] = {title = "Keine Waffen für Grimmtotem!", objective = "Brennt 8 Grimmtotemwaffenständer nieder.", description = "Die Grimmtotem wollen kämpfen? Mal sehen, wie sie das ohne ihre Waffen anstellen wollen. \n\nIhr habt doch sicherlich irgendwas, das brennt. Brennt ihre Waffenständer nieder, <Klasse>.\n\nLasst die Natur die Arbeit verrichten.", progress = nil, completion = "Mal sehen, wie gut sie ohne ihre Waffen kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27312] = {title = "Grimmtotem in Düsterwolkengipfel", objective = "Tötet 20 Tauren der Grimmtotem in Düsterwolkengipfel.", description = "Es geht nicht anders. Wenn man einen Kampf gewinnen will, muss Blut vergossen werden. Und in diesem Fall viel Blut.\n\nIhr wisst, was zu tun ist.", progress = nil, completion = "Das hat ihre Zahlen verringert! Es ist ja nicht so, als hätten sie es nicht verdient.", rewards = "BlutwatstiefelGöttinnengesegnete PulswärmerGrimmtotemschiftungAuf Euch wartet eine dieser Belohnungen:\n\nAmulett des Blutvergießens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27313] = {title = "Grimmtotem in Düsterwolkengipfel", objective = "Tötet 20 Tauren der Grimmtotem in Düsterwolkengipfel.", description = "Es gibt keine Alternative; wenn man einen Kampf gewinnen will, muss man das Blut des Feindes vergießen. Und in diesem Fall leider viel Blut.\n\nIhr wisst, was zu tun ist.", progress = nil, completion = "Die Erdenmutter duldet Gewalt wie diese nicht, aber wir hatten keine andere Wahl. Die Grimmtotem haben ihre Lehren schon zu lange ignoriert, und ernten nun, was sie gesät haben.", rewards = "BlutwatstiefelArmschienen der zögerlichen GewaltanwendungSchulterstücke der LehrenAuf Euch wartet eine dieser Belohnungen:\n\nSchnitteramulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27314] = {title = "Häuptlinge der Grimmtotem: Isha Düsteraxt", objective = "Tötet Isha Düsteraxt.", description = "Grundlagen der Schildwachenausbildung: wenn der Anführer ausgelöscht ist, wird der Rest der Streitmacht bald zerfallen. Und genau das werden wir tun, <Klasse>.\n\nIsha Düsteraxt ist von den Häuptlingen der Grimmtotem am wenigsten weit entfernt. Mal sehen, ob wir es mit ihr aufnehmen können.", progress = nil, completion = "Sie war ein stärkerer Gegner, als ich erwartet hatte. Wir haben gut zusammengearbeitet, aber wir müssen sicherstellen, dass wir die anderen Häuptlinge der Grimmtotem nicht unterschätzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27315] = {title = "Häuptlinge der Grimmtotem: Isha Düsteraxt", objective = "Tötet Isha Düsteraxt.", description = "Die Grundlagen der Kriegerheldenphilosophie legen fest, dass durch den Tod eines Anführers die restlichen Streitmächte bald den Mächten der Verwirrung zum Opfer fallen. Und genau das werden wir tun, <Klasse>.\n\nIsha Düsteraxt ist von den Häuptlingen der Grimmtotem am wenigsten weit entfernt. Wir werden sie und ihre Axt auf die Probe stellen, und sie wird kläglich scheitern.", progress = nil, completion = "Sie war ein außerordentlicher Gegner, weitaus besser, als ihr Ruf vermuten lässt. Obwohl wir gut zusammengearbeitet haben, müssen wir sicherstellen, dass wir die anderen Häuptlinge der Grimmtotem nicht unterschätzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27316] = {title = "Die Rassel der Knochen", objective = "Gebt die Rassel der Knochen der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.", description = "Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.\n\nVielleicht kann die Schildwache uns Einblicke in seine Bedeutung geben?", progress = "Das ist die sagenhafte Rassel der Knochen, <Name>!", completion = "Es ist also wahr! Aber was macht sie hier? Wenn die Rassel hier ist, bedeutet das, dass auch die Niederschrift und die Trommeln in der Nähe sein müssen!\n\nVielleicht gibt es eine Verbindung zwischen der Rassel und der Windnatter, die eben erschienen ist? Ich habe eine Ahnung, was es mit dieser Kreatur auf sich haben könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27317] = {title = "Die Rassel der Knochen", objective = "Gebt die Rassel der Knochen dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.", description = "Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.\n\nVielleicht kann der Kriegerheld uns Einblicke in seine Bedeutung geben?", progress = "Die sagenhafte Rassel der Knochen, <Name>!", completion = "Es ist also wahr! Aber was macht sie hier? Wenn die Rassel hier ist, bedeutet das, dass auch die Niederschrift und die Trommeln in der Nähe sein müssen!\n\nVielleicht gibt es eine Verbindung zwischen der Rassel und der Windnatter, die eben erschienen ist? Ich glaube, ich weiß, was es mit dieser Kreatur auf sich hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27318] = {title = "Häuptlinge der Grimmtotem: Ältester Sturmhuf", objective = "Tötet den Ältesten Sturmhuf.", description = "Der Älteste Sturmhuf ist ein Schamane mit ernormer Macht. Anscheinend ist er die rechte Hand von Magatha Grimmtotem, der Ältestengreisin und Anführerin des Grimmtotemklans.\n\nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, <Klasse>.", progress = nil, completion = "Das wären zwei. Bleiben noch zwei.\n\nIch frage mich, was er mit \"auserwählt\" gemeint hat?", rewards = "Hände der AuswerwähltenDüsterwolkenmaskeSchiftung des JüngersBeinschützer der SpitzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27319] = {title = "Häuptlinge der Grimmtotem: Ältester Sturmhuf", objective = "Tötet den Ältesten Sturmhuf.", description = "Der Älteste Sturmhuf ist ein Schamanenhäuptling mit ernormer Macht. Er wurde von Magatha Grimmtotem unterrichtet, der Ältestengreisin und Anführerin des Grimmtotemklans.\n\nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, <Klasse>.", progress = nil, completion = "Das war kein Spaß. Ich frage mich, was er damit gemeint hat, als er Euch \"auserwählt\" genannt hat?", rewards = "Hände der AuswerwähltenDüsterwolkenmaskeFreiwindschiftungBeinschützer der SpitzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27320] = {title = "Die Niederschrift der Geschichte", objective = "Findet die Niederschrift der Geschichte.", description = "In der Mythologie der Shu'halo ist die Rassel der Knochen eng mit der Niederschrift der Geschichte und den Trommeln des Krieges verknüpft. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren.\n\nWir müssen unsere Augen offen halten, wenn wir die anderen zwei Artefakte finden wollen. Wenn man den Geschichten Glauben schenken will, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.", progress = "Wir brauchen die echte Niederschrift, nicht irgendeine Schriftrolle der Tauren.", completion = "Ich bin mir relativ sicher, dass es die Niederschrift ist. Das ist sehr verwunderlich, &lt;Name&gt;. Was haben die hier zu suchen? Werden sie als Waffen benutzt?\n\nDie Windnatter ist nordwestlich zum nächsten Felsen geflogen. Vielleicht sind die Trommeln dort?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27321] = {title = "Die Niederschrift der Geschichte", objective = "Findet die Niederschrift der Geschichte.", description = "Die Rassel der Knochen ist Teil der uralten Mythologie der Shu'halo. Sie wurde schon immer mit der Niederschrift der Geschichte und den Trommeln des Krieges in Verbindung gebracht. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren, Geschenke von der Erdmutter, wenn man den Geschichten Glauben schenken soll. Allerdings kann ich mir nicht vorstellen, dass die Erdmutter mit den Trommeln wirklich etwas zu tun hat.\n\nWir müssen aufmerksam sein, wenn wir die anderen zwei Artefakte finden wollen. Wenn ich mich recht erinnere, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.", progress = "Wir brauchen die echte Niederschrift, nicht irgendeine Schriftrolle.", completion = "Das ist sehr aufregend, aber auch Besorgnis erregend, &lt;Name&gt;. Was haben die Artefakte hier zu suchen? Und werden sie von den Grimmtotem als Waffen gegen uns verwendet?\n\nDie Windnatter ist nordwestlich zum nächsten Felsen geflogen. Vielleicht sind die Trommeln dort?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27322] = {title = "Korok der Koloss", objective = "Bringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen in den Ruinen von Gilneas.", description = "Das Monster ist gefallen und hat den Soldaten der Verlassenen an der Front so eine kurze Atempause verschafft.\n\nBringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen.", progress = "Korok ist tot?", completion = "Dieses riesige Ungetüm hat hunderte unserer Soldaten in den Tod gerissen. Ihr habt heute gute Arbeit geleistet, &lt;Name&gt;.", rewards = "Cromushs UmhangGürtel des zweiten KopfesKoroks RingIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27323] = {title = "Häuptlinge der Grimmtotem: Grundig Finsterwolke", objective = "Tötet Grundig Finsterwolke.", description = "Einer der berüchtigten Anführer der Grimmtotem von Steinkrallengebirge ist zurückgekehrt.\n\nWir sollten diese Gelegenheit nutzen und sicherstellen, dass er nirgendwo anders hingeht.", progress = nil, completion = "&lt;Die Schildwache versucht, Euch einzuschätzen.&gt;\n\nWas ist mit Euch los? Warum beunruhigt Eure Anwesenheit alle anderen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27324] = {title = "Häuptlinge der Grimmtotem: Grundig Finsterwolke", objective = "Tötet Grundig Finsterwolke.", description = "Einer der versiertesten Anführer der Grimmtotem vom Steinkrallengebirge ist zurückgekehrt.\n\nWir müssen das Beste aus dieser Situation machen und seiner Schreckensherrschaft ein für alle Mal ein Ende setzen.", progress = nil, completion = "&lt;Der Kriegerheld versucht, Euch einzuschätzen.&gt;\n\nIhr habt etwas Besonderes an Euch, &lt;Name&gt;. So viel ist sicher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27325] = {title = "Die Trommeln des Krieges", objective = "Findet die Trommeln des Krieges.", description = "Was auch immer die Grimmtotem mit diesen Trommeln des Krieges machen, wir wollen nicht, dass sie noch länger in ihrem Besitz bleiben.\n\nSorgt Euch nicht, <Name>, wir werden eine Lösung finden. Zuerst müssen wir aber alle Teile dieses Rätsels erlangen.", progress = "Die Tauren lieben Trommeln. Ich kann mir jedoch vorstellen, dass die Trommeln des Krieges sich von normalen Trommeln unterscheiden.", completion = "Das war sicher die Stimme der Ältestengreisin!\n\nWir müssen uns vorsehen, &lt;Name&gt;. Vor uns liegen große Gefahren, wenn Magatha Grimmtotem Euch bemerkt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27326] = {title = "Die Trommeln des Krieges", objective = "Findet die Trommeln des Krieges.", description = "Was auch immer die Grimmtotem mit den Trommeln des Krieges machen, wir wollen nicht, dass sie sie behalten.\n\nSorgt Euch nicht, <Name>, wir werden herausfinden, was hier vor sich geht. Zuerst müssen wir aber alle Artefaktteile finden.", progress = "Krieg ist keine Alternative für diejenigen, die sich an den Lehren der Erdmutter orientieren.", completion = "Das war sicher die Stimme der Ältestengreisin!\n\nWir müssen uns vorsehen, &lt;Name&gt;. Vor uns liegen große Gefahren, wenn Magatha Grimmtotem Euch bemerkt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27327] = {title = "Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge", objective = "Tötet Arnak Grimmtotem.", description = "Die Zeit ist gekommen, dem Anführer aller Grimmtotem in Düsterwolkengipfel ein Ende zu bereiten: Arnak Grimmtotem.\n\nEs wird gesagt, dass er der in Ungnade gefallene Neffe von Magatha Grimmtotem ist, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat wohl dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.\n\nAll dies ist aber jetzt nicht wichtig. Nur sein Tod ist für uns von Wichtigkeit. Sein endgültiger Tod.", progress = nil, completion = "Aus irgendeinem Grund meinen alle, dass Ihr von Magatha Grimmtotem gesandt wurdet. Ich weiß, dass es etwas mit der Windnatter zu tun hat, die hier in letzter Zeit rumlungerte.\n\nIst aber auch egal. Ihr Anführer ist tot. Es ist nur eine Frage der Zeit, bis die Tauren den Freiwindposten wieder ihre Heimat nennen können.\n\nWenn ich einer von denen wäre, würde ich wohl ein bisschen Druck machen, um die Grimmtotem eine Lektion zu lehren. Aber das machen sie wahrscheinlich nicht. Sie sind immerhin Tauren.", rewards = "Immerwährender FriedenSchandkapuzeBeinschützer der UngnadeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27328] = {title = "Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge", objective = "Tötet Arnak Grimmtotem.", description = "Die Zeit ist gekommen, um uns dem Anführer aller Grimmtotem in Düsterwolkengipfel zuzuwenden: Arnak Grimmtotem.\n\nEr ist der in Ungnade gefallene Neffe von Magatha Grimmtotem, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.\n\nAll dies ist aber jetzt nicht wichtig. Von Wichtigkeit ist nur, dass wir uns seiner annehmen. Ein für alle Mal.", progress = nil, completion = "Alle haben geglaubt, dass Ihr von Magatha Grimmtotem geschickt wurdet. Man kann immerhin nicht leugnen, dass ihr Begleiter Arikara hier ist.\n\n&lt;Der Kriegerheld blickt Euch lange an.&gt;\n\nEs ist nicht wirklich wichtig. Arnak ist tot. Es ist nur eine Frage der Zeit, bis wir Freiwindposten zurückerobern.\n\nVielleicht wird es uns nun möglich sein, dauerhaften Frieden mit den Grimmtotem zu schließen?", rewards = "Immerwährender FriedenSchandkapuzeBeinschützer der UngnadeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27329] = {title = "Die Windnatter entfernen", objective = "Bezwingt Arikara.", description = "Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotem in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.\n\nVielleicht können wir es herausfinden.\n\nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.", progress = nil, completion = "Sie wurde also von den Schattenhammerkultisten gefangen genommen. Ich kann nicht sagen, dass ich großes Mitleid empfinde, aber in deren Händen könnte sie sich als noch gefährlicher herausstellen.", rewards = "WindweisengewehrMantel der AnrufungWindnatternarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nRing des Unterdrückers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27330] = {title = "Die Windnatter entfernen", objective = "Bezwingt Arikara.", description = "Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotem in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.\n\nVielleicht können wir es herausfinden.\n\nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.", progress = nil, completion = "Sie wurde also von den Schattenhammerkultisten gefangengenommen. Ich kann nicht sagen, dass ich großes Mitleid empfinde, aber in deren Händen könnte sie sich als noch gefährlicher herausstellen.", rewards = "WindweisengewehrMantel der AnrufungWindnatternarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nRing des Unterdrückers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27331] = {title = "Der Ruf der Seherin", objective = "Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, <Name>. Seherin Liwatha bittet Euch, so schnell wie möglich in die Stadt zurückzukehren. Ihre Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.\n\nSucht Seherin Liwatha im Tal der Weisheit in Orgrimmar auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, <Name>. Seherin Liwatha bittet Euch, so schnell wie möglich in die Stadt zurückzukehren. Ihre Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.\n\nSucht Seherin Liwatha im Tal der Weisheit in Orgrimmar auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27332] = {title = "Sucht den Schattenläufer auf", objective = "Sprecht mit Schattenläufer Zuru im Tal der Geister in Orgrimmar.", description = "Der Schattenläufer Zuru fordert Eure sofortige Anwesenheit in Orgrimmar, <Name>. Lasst ihn nicht warten, denn es klang, als sei es eine wichtige Angelegenheit.\n\nIhr werdet den Schattenläufer im Tal der Geister in Orgrimmar vorfinden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27333] = {title = "Haltlos", objective = "Tötet 12 Rebellen der Worgen.", description = "Ich weiß nicht, wie lange wir die Stellung noch halten können, <Name>. Die Worgen von Crowley und Blutfang kennen jedes noch so kleine Versteck und jeden sicheren Ort in Gilneas. In der einen Minute stehen sie vor Euch und in der nächsten Minute sind sie schon wieder weg! Wir werden diesen Krieg durch ihre Gelegenheitsangriffe verlieren, obwohl wir zahlenmäßig gesehen die Oberhand haben.\n\nMami hat aber keinen Aufgeber aus mir gemacht! Ich bin ein Verlassener bis zum bitteren Ende.\n\nBegebt Euch in die Mark und helft unseren Soldaten an vorderster Front. Tötet die angreifenden Rebellen der Worgen!", progress = nil, completion = "Wenn ich noch Luft bekommen würde, würde ich jetzt erleichtert aufatmen.\n\nMacht es Euch nicht zu gemütlich, &lt;Name&gt;. Eure Mission fängt hier erst an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27334] = {title = "Dunkle Klerikerin Cecille", objective = "Sprecht mit der dunklen Klerikerin Cecille in Feste Grommash im Tal der Stärke in Orgrimmar.", description = "Ich habe soeben eine Nachricht von der Dunklen Klerikerin Cecille aus Orgrimmar erhalten. Sie fordert Euch auf, sie in ihrem Audienzgemach in der Feste Grommash aufzusuchen. Sie empfängt dort eine Delegation aus Unterstadt. Die Klerikerin hat nicht gesagt, worum es bei Eurem Besuch geht, aber es ist ganz offensichtlich wichtig. Beeilt Euch, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27335] = {title = "Reise nach Orgrimmar", objective = "Sprecht mit Tyelis in Feste Grommash im Tal der Stärke in Orgrimmar.", description = "Ein Botschafter hat mich gebeten, Euch diese Einladung zu geben. Sie ist von Tyelis, einem Priesterlehrer und Abgesandten von Silbermond.\n\nEr fordert Euch auf, ihn in der Feste Grommash in Orgrimmar zu treffen. Ihr solltet sofort aufbrechen, <Name>. Die Einladung klingt wichtig.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich bin froh, dass Ihr meine Einladung angenommen habt. Wir haben viel zu besprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27336] = {title = "Die Waffe der Grimmtotem", objective = "Platziert das erbeutete Totem auf dem Boden und tötet 10 scheckige Staubsuhlerkrokilisken oder Staubsuhlerdolchrachenen, um den Effekt des Totems zu testen.", description = "Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, konnte ich noch ein recht seltsames Totem an mich bringen, das von unseren Feinden gegen uns eingesetzt wurde.\n\nIm Kampf lässt es wohl wilde Energieblitze von sich. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beheimaten aggressive scheckige Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht, die Krokilisken in Reichweite des Totems zu bekämpfen.", progress = "Konntet Ihr das Totem erfolgreich testen?", completion = "&lt;Der Lehrling hört Euch zu, als Ihr den Verlauf des Experiments schildert.&gt;\n\nDunst und ein paar Blitze? Sonst nichts? Das Totem muss mehr können als nur das! Die Grimmtotem würden so etwas nicht mit aufs Schlachtfeld bringen, wenn es nicht irgendeinen wirklichen Nutzen hat!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27337] = {title = "Eine passende Waffe", objective = "Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein von Baron Silberlein, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", description = "Schon zu Beginn haben Eure Lehrer Euch für ein Naturtalent gehalten, <Name>. Euer rascher Fortschritt und Eure Hingabe haben Euch zu einem wahren Vorbild gemacht.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDen Legenden zufolge ist die verfluchte Burg Schattenfang im Silberwald der Ort, an dem einige der Materialien zu finden sind, die Ihr dafür benötigt. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ander hat gesagt, ich soll Euch erwarten. Es ist eine Ehre, für Euch eine Waffe zu schmieden, &lt;Name&gt;. Mit diesen Materialien wird es wahrhaftig eine ausgezeichnete Klinge.", rewards = "Breitschwert der KroneGroßschwert der KroneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27338] = {title = "Unsere Jungs an der Küste", objective = "Meldet Euch bei Leutnant Emry in Zwielichtufer im Schattenhochland.", description = "Die Lage hier in Hochland ändert sich minütlich. Unser Ziel ist es, die Bastion des Zwielichts zu stürmen, aber ich kann nicht mal eine Landezone an der Küste sichern, ohne dass die verfluchte Horde Ärger macht.\n\nIch brauche Männer, die hier am Strand die Landung sichern, während ich die Überreste der Flotte zusammensuche.\n\nMeldet Euch bei Leutnant Emry an der Küste und helft seinen Marinesoldaten, die Horde zurückzudrängen!", progress = nil, completion = "Zieht Euren Kopf ein, bevor er ihn verliert, &lt;Klasse&gt;!\n\nDas hier ist MEIN Strand.\n\nDie Horde WILL meinen Strand.\n\nSie werden meinen Strand nicht BEKOMMEN.\n\nIst die Strandsituation damit geklärt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27339] = {title = "Der Reagenziendieb", objective = "Sammelt 6 Phiolen Marschengift von Dunkelzahnkrabblern oder giftigen Schreddern.", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich einfach, ihn zu ignorieren, aber das funktioniert nicht. Dieses Mal werde ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Wenn Ihr mir das Gift bringt, werde ich die Vorräte auffrischen, bevor Morlann merkt, dass etwas gefehlt hat.", progress = "Habt Ihr das Gift bekommen? Morlann wird jeden Moment bemerken, dass nichts mehr da ist ...", completion = "&lt;Lehrling Garion überprüft das Gift.&gt;\n\nAbsolut perfekt! Der Unterschied wird ihm nie auffallen!", rewards = "Bedeckung des WanderersVerzauberter UmhangErprobter MarschenholzbogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27340] = {title = "Räuber des Grollhornpostens", objective = "Tötet 12 Grimmtotem in Grollhornposten.", description = "Die Grimmtotem hoch oben in Grollhornposten werden von Tag zu Tag frecher. Nachts hört man oft, wie sie in Chören von ihren Taten im Kampf gegen die Bewohner der Gegend singen.\n\nSie sind festentschlossen, uns von Tabethas Hof zu vertreiben, obwohl schon Generationen von Lehrlingen hier ausgebildet wurden. Wir haben den Hof so gut es ging verteidigt, aber Lehrling Garion wurde beim letzten Angriff verwundet.\n\nBegebt Euch nach Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Diese Angriffe müssen ein Ende finden.", progress = nil, completion = "&lt;Lehrling Morlann nickt.&gt;\n\nGut. Ich werde ihre Anwesenheit nicht vermissen, wenn man es denn Anwesenheit nennen kann. Man sollte meinen, dass man wenigstens mitten im Sumpf ein wenig unter sich ist.", rewards = "Erdbindertunika der GrimmtotemUmhang des ZerstörersGrollhorngurtAuf Euch wartet eine dieser Belohnungen:\n\nMorlanns anderes Siegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27341] = {title = "Späht den Strand aus", objective = "Späht den Brückenkopfkontrollpunkt in Zwielichtufer aus. Ihr müsst den Kontrollpunkt nicht einnehmen. Wenn Ihr ihn einnehmt, wird Eure Seite jedoch Vorteile im Kampf haben und Ihr werdet für PvP gekennzeichnet.", description = "Es ist ganz einfach, wir oder sie, <Klasse>. Nur eine Fraktion kann diesen Strand einnehmen.\n\nNördlich von hier ist ein kleiner Hügel, von dem man die ganze Küstenlinie überblicken kann. Wer diesen Hügel einnimmt, erlangt sofort die Oberhand an der ganzen Küste.\n\nIch muss wissen, was die aktuelle Lage ist. Späht den Brückenkopfkontrollpunkt aus. Ihr erkennt ihn an den großen Flaggen. Kehrt anschließend zu mir zurück.\n\nIhr müsst nicht versuchen, ihn einzunehmen, es sei denn, Ihr dürstet nach einem Kampf ...", progress = nil, completion = "So ist das Land nun mal beschaffen. Wenn Ihr Schwierigkeiten mit dem Kampf an der Küste habt, könnt Ihr Euch vielleicht überlegen, hier auszuhelfen und versuchen, mit uns den Hügel einzunehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27342] = {title = "Die Zeit löst alle Rätsel", objective = "Sammelt 6 Wolfsbann.", description = "Die Dunkle Fürstin hat Euch und Arthura für eine ganz besondere Aufgabe einberufen. Bevor ich Euch jedoch mehr verrate, müssen wir erst einige Vorbereitungen treffen.\n\nBegebt Euch zum Wald von Gilneas östlich von hier und sucht in der Nähe der Bäume und Steine in der Gegend nach einer besonderen Pflanze, die als Wolfsbann bekannt ist. Sammelt so viel Wolfsbann, wie Ihr tragen könnt und kehrt zu mir zurück.\n\nUnsere Aufgabe hier übersteigt die Aufgaben auf dem Schlachtfeld, <Name>. Ich werde Euch zu gegebener Zeit mehr verraten.", progress = "Konntet Ihr den Wolfsbann finden?", completion = "&lt;Belmont nimmt Euch den Wolfsbann ab.&gt;\n\nGut. Von jetzt an folgt den Befehlen von Vorpostenkommandant Ansturm. Versucht, Euch so gut wie möglich in die Reihen der Soldaten einzufinden. Wir wollen nicht, dass die Gilnearische Befreiungsfront auf Euch aufmerksam wird.\n\nOh, Ihr wusstet nicht, dass sie uns beobachten? In diesem Augenblick sind die Augen von fünf Spionen der Worgen direkt auf uns gerichtet. Bleibt ruhig und befolgt alle Befehle. Ich werde Euch Bescheid geben, wenn wir weitermachen können.", rewards = "Pantoffeln des überwachten WächtersEisenhutwesteBelmonts ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27343] = {title = "Die Hand des Lichts", objective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", description = "Ich habe Eure Fortschritte verfolgt, <Name>, und ich kann nur schließen, dass das Licht strahlend auf Euch scheint. Ihr seid wahrhaftig <ein vorbildlicher/eine vorbildliche:c> <Klasse>.\n\nUm Eurer Hingabe Anerkennung zu zollen, hat König Wrynn den königlichen Waffenschmied beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien zur Herstellung dieser Waffe sind einzigartig und können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Konntet Ihr die Materialien für Eure Waffe finden?", completion = "Lord Grayson hat mir viel von Euch und Eurer Hingabe zum Licht und der Allianz erzählt. Es wird mir eine große Ehre sein, einen Hammer für Euch anzufertigen, &lt;Name&gt;.", rewards = "Streitkolben des OrdensHammer des OrdensKriegshammer des OrdensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27344] = {title = "Eine wohlverdiente Belohnung", objective = "Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr von Lord Godfrey, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", description = "Nicht nur ich bin von Eurem Fortschritt beeindruckt, <Name>. Wie Ihr Bogen und Begleiter meistert, und auch Eure Hingabe zur Allianz, sind König Wrynn zu Ohren gekommen.\n\nIn Anerkennung Eurer Dienste hat der König seinen königlichen Bogenmacher beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die einzigartigen Bestandteile finden könnt, die für diese Waffe benötigt werden. Reist dorthin und findet das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Wer hätte gedacht, dass in einer verfluchten Burg so wertvolle Gegenstände zu finden sind? Ich sehe es als Ehre an, sie in eine wunderbare Waffe für Euch zu verarbeiten.", rewards = "Ihr bekommt:\n\nArmbrust der Krone"}
MultiLanguageQuestData['de'][27345] = {title = "Das K.d.V.", objective = "Findet die Kommunikationsvorrichtung der Verlassenen.", description = "Die Kommunikation zu allen unseren Außenposten an der Front ist abgebrochen, <Name>. Jetzt gerade habe ich nicht die leiseste Ahnung, wie es unseren Truppen in Gilneas ergeht. Wir müssen die Kommunikation wieder herstellen.\n\nBegebt Euch nach Westen in die Mark und findet unseren Außenposten an der Küste. Die Soldaten dort sind wahrscheinlich alle tot, aber ihr K.d.V. könnte noch funktionieren. Nehmt das Gerät an Euch und kehrt zu mir zurück.", progress = "Findet das K.d.V.", completion = "Mit diesem Gerät kann ich mich während Eurer Einsätze mit Euch in Verbindung setzen. Jetzt müssen wir uns daran machen, unsere Außenposten an der Front zu überprüfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27346] = {title = "Der Zeppelinabsturz", objective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", description = "Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Eine Beauftragte des Dampfdruckkartells kam hier vor ein paar Tagen vorbei.\n\nSie wollte Informationen über die Ladung des Zeppelins und den Piloten, Beezil, erhalten. Von uns hat den Absturz aber niemand wirklich gesehen. Ich bezweifle, dass sie das Zeppelinwrack alleine lichten kann, und noch viel weniger, dass sie je erfahren wird, welche Ladung an Bord war.\n\nWenn Ihr Zeit habt, könntet Ihr ihr vielleicht bei Beezils Wrack helfen. Es ist östlich von hier, in der Nähe der Berge.", progress = nil, completion = "Die Einsiedlermagier haben Euch geschickt? Wie soll ich wissen, dass ich Euch vertrauen kann?\n\nHilfe kann ich wohl gebrauchen. Hier gibt es auch nicht wirklich viel, für das sich Magier interessieren könnten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27347] = {title = "Korrosionsschutz", objective = "Moxie Stahlgrill möchte, dass Ihr 10 Schlamme auflöst und Euch dann bei Beezils Wrack bei ihr meldet.", description = "Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, ihn unter Kontrolle zu bekommen, wird er das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann nicht mit leeren Händen zurückkehren, <Klasse>! Helft mir, diese Schlamme aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um das Gerät anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", progress = "Konntet Ihr gegen die Schlamme etwas ausrichten?", completion = "Naja, es sieht hier schon ein bisschen besser aus ...\n\nIch schätze, es ist an der Zeit, die Bergungsarbeiten fortzusetzen.", rewards = "Kobaltdurchwirkte HandschuheTunika des MarschenwächtersRostfreier TaillenschutzKorrodierter HelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27348] = {title = "Bergt die Fracht!", objective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", description = "Der Zeppelin hatte Vorräte für die nächsten sechs Monate für Morastwinkel geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch das wird auf die Dauer nicht möglich sein.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt. Ich bin ziemlich sicher, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir ein bisschen bei der Bergung helfen?", progress = "<Moxie sieht aus, als sei ihr vor Sorge ganz schlecht.>\n\nHaben die Vorräte den Absturz überstanden? Konntet Ihr sie finden?", completion = "Wow! Ihr habt in jedem Fall viel mehr gefunden, als ich erwartet hatte. Ich weiß nicht, welche Ausbeute Drazzit von uns erwartet, aber zunächst wird er sich damit zufrieden geben müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27349] = {title = "Kommunikationsabbruch: Außenposten von Schreckenswacht", objective = "Erkundet den Außenposten von Schreckenswacht.", description = "Ich werde Euch nicht anlügen, <Name>. Was ich von Euch verlange ist mehr oder weniger Selbstmord. Die Wahrscheinlichkeit einer Niederlage beträgt 95%.\n\nAlle Kommunikation zum Außenposten der Schreckenswacht ist abgebrochen. Durch die ständigen Angriffe der Worgen haben wir keine Möglichkeit, zur Schreckenswacht aufzubrechen und nach unseren Soldaten zu schauen. Macht Euch auf den Weg in Richtung Süden zum Außenposten und seht nach unseren Soldaten. Ich werde von jetzt an mit Euch über die Kommunikationsvorrichtung der Verlassenen - dem K.d.V. - in Verbindung bleiben.\n\nHALTET EUCH VON DER HAUPTSTRASSE FERN.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27350] = {title = "Kommunikationsabbruch: Rutsaks Wacht", objective = "Findet Hauptmann Rutsak in Rutsaks Wacht in den Ruinen von Gilneas.", description = "<Das K.d.V. brummt.>\n\nUnser nächster Außenposten ist Rutsaks Wacht, östlich von Schreckenswacht. Sucht Rutsak auf und seht zu, dass Ihr den Stürmern der Worgen entgeht, <Name>. Diesen Monstern wollt Ihr nicht allein begegnen.\n\nWenn Ihr es in einem Stück dorthin schafft, sucht nach Hauptmann Rutsak.\n\nMacht Euch auf das Schlimmste gefasst.", progress = nil, completion = "Ss...na...na...nachdem wir Gilneas verloren haben, konnten wir auch den Hafen nicht h...h...halten.\n\nMM...MMM...MENSCHEN, HIER SIND MENSCHEN! Verstärkung aus Sturmwind! Sie haben meine Männer abgeschlachtet. Haben mich am Leben gelassen, um von ihrer Stärke zeugen zu können. Um meinen Befehlshabern... um zu berichten, dass die 7. Legion hier ist ...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27351] = {title = "Eine königliche Belohnung", objective = "Reist zu Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", description = "Der SI:7 hat Eure Fortschritte mit Interesse beobachtet. Eure Dienste für die Allianz sind bekannt und Geschichten über Eure Taten sind dem König zu Ohren gekommen.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die fremdartigen Bestandteile finden könnt, die für Eure Waffe benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSpezialdolch von SI:7"}
MultiLanguageQuestData['de'][27352] = {title = "Flüssiges Gold", objective = "Findet eine Phiole mit Weihwasser von Stratholme.", description = "Nachdem die Geißel wie eine Krankheit durch Stratholme fegte, stellten die Ritter der Silbernen Hand Weihwasser her, um es gegen die Eindringlinge zu nutzen. Sie haben es in kleinen Kisten zusammen mit anderen wichtigen Vorräten gelagert und in der ganzen Stadt verteilt. Leider wurden die Einwohner der Stadt zu Geißeln, bevor die Vorräte je genutzt werden konnten!\n\nDie Vorratskisten werden sich für unsere Zwecke als äußerst nützlich erweisen. Bringt eine Phiole mit Weihwasser von Stratholme zu mir, damit ich es in größeren Mengen herstellen kann.", progress = "Ist das eine Phiole mit Weihwasser von Stratholme?\n\nHe, ist das ganz normales Wasser? Spielt mit dem alten Steinberster keine Spielchen!", completion = "Hervorragend! Ich glaube, in größeren Mengen wird sich das Weihwasser als verheerend herausstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27353] = {title = "Segen der Elemente", objective = "Reist nach Burg Schattenfang und erhaltet den Waldens Talisman, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", description = "Euer Talent hat in den Kreisen der Schamanen viel Aufsehen erregt, <Name>. Geschichten von Eurer Beherrschung der Elemente und Eurer Hingabe zur Allianz können selbst im Palast vernommen werden.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien für Eure Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und erlangt den Talisman von Lord Walden, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich habe nicht oft die Möglichkeit, mit so fremdartigen Materialien zu arbeiten, aber selbst ich spüre die Macht dieser Gegenstände. Es wird mir eine Ehre sein, eine unglaubliche Waffe für Euch herzustellen, &lt;Name&gt;. Die Weissagerin hat nicht untertrieben, als sie mir von Euren Fähigkeiten erzählte.", rewards = "Kriegsaxt des ScharfsehersZauberaxt des ScharfsehersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27354] = {title = "Beherrschung des Arkanen", objective = "Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Ihr habt Euch als <ausgezeichneter Student und engagierter Diener/ausgezeichnete Studentin und engagierte Dienerin> der Allianz herausgestellt. Selbst der König hat schon von Euren Leistungen gehört.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Verzauberer beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien, die für Euren Stab benötigt werden, können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich habe Euch bereits erwartet, &lt;Name&gt;. Maginor Dumas spricht in lobenden Tönen von Euch, und der Auftrag des Königs bestätigt diese Worte. Es ist mir eine Ehre, für Euch einen Stab anfertigen zu können.", rewards = "Ihr bekommt:\n\nStab des königlichen Zauberers"}
MultiLanguageQuestData['de'][27355] = {title = "Ein Segen für die Mächtigen", objective = "Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", description = "Dank Eurer Taten bemerkt der König langsam unsere Macht und unseren Wert für die Allianz. Vielleicht werden die Unsrigen langsam akzeptiert.\n\nKönig Wrynn hat in Anerkennung Eurer Dienste den königlichen Verzauberer beauftragt, eine mächtige Waffe für Euch anzufertigen.\n\nDie Materialien dafür sind nur in Burg Schattenfang im Silberwald zu bekommen. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen, und Essenzen der Geister, die das Schloss heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab der gerechtfertigten Sünden"}
MultiLanguageQuestData['de'][27356] = {title = "Die Zukunft des Zirkels", objective = "Reist nach Burg Schattenfang und erhaltet Waldens Elixire von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", description = "Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, <Name>. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.\n\nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.\n\nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz, und Sehnen der Ghule und Geister, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Euren Stab benötige?", completion = "Ah, Ihr müsst der &lt;Klasse&gt; sein, von dem Loganaar erzählt hat. Ich freue mich, Euch endlich zu treffen. Loganaar und andere Mitglieder des Zirkels halten viel von Euch. Es wird mir eine Ehre sein, diesen Druidenstab für Euch anzufertigen.", rewards = "Stab des grünen ZirkelsStab des tiefgrünen ZirkelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27357] = {title = "Die gefangene Braut", objective = "Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.", description = "Natürlich! Lakota Windweise! Warum ist mir das nicht früher eingefallen?\n\nArnak hat Lakota vor Jahren entführt und versucht, sie in eine Ehe zu zwingen. Sie konnte fliehen, aber in dem Chaos durch die Angriffe auf Freiwindposten in letzter Zeit konnte er sie wieder schnappen.\n\nSie muss hier irgendwo in der Nähe sein. Sie ist in den letzten Jahren recht mystisch geworden. Ich glaube, dass sie weiß, was man mit den Artefakten der Tauren machen kann.", progress = nil, completion = "Es ist peinlich, schon wieder von Arnak entführt worden zu sein. Ich habe draußen Kampfgeräusche gehört. Habt Ihr ihn getötet?\n\n&lt;Für einen winzigen Moment sieht die Schamanin traurig aus.&gt;\n\nIch bin froh, wieder frei zu sein. Nun, wie kann ich Euch helfen, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27358] = {title = "Die gefangene Braut", objective = "Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.", description = "Lakota Windweise! Warum ist mir das nicht früher eingefallen?\n\nArnak hat Lakota vor Jahren entführt und mit Gewalt versucht, sie zu seiner Braut zu machen. Sie konnte mit etwas Hilfe fliehen, aber in dem Chaos durch die Angriffe auf Freiwindposten in letzter Zeit konnte er sie wieder schnappen.\n\nSie muss in der Nähe sein. Sie hat in den letzten Jahren viel Schamanenwissen erworben. Ich bin mir sicher, dass sie uns sagen kann, inwiefern die Rassel, die Niederschrift und die Trommeln wichtig sind.", progress = nil, completion = "Es ist peinlich, schon wieder von Arnak entführt worden zu sein. Ich habe draußen Kampfgeräusche gehört. Habt Ihr ihn getötet?\n\n&lt;Für einen winzigen Moment sieht die Schamanin traurig aus.&gt;\n\nIch bin froh, wieder frei zu sein. Nun, wie kann ich Euch helfen, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27359] = {title = "Verstärkung der Argentumdämmerung", objective = "Erhaltet 4 Essenzen einer Banshee.", description = "Die Geißel haben eine Art Zauber gewirkt, der mich daran hindert, ein Portal zu öffnen. Daher kann auch unserer Verstärkung nun nicht dabei helfen, die Stadt einzunehmen! Es ist wie ein nicht enden wollender Schrei in meinem Kopf! Argh!\n\nIch versuche mein Bestes, um durch die Geräusche dieser Barriere nicht verrückt zu werden. Meine Vermutung ist, dass dieser Schutzwall von den Banshees aufrechterhalten wird. Bringt mir ihre Essenzen – ich glaube, ich kann sie benutzen, um einen Gegenzauber zu wirken, damit die Verstärkung eintreffen kann!", progress = "Konntet Ihr die Essenzen erhalten? Seid vorsichtig, die Banshees sind todbringende Zauberer.", completion = "Oh... die Banshees sind in der Tat geschundene Seelen. Selbst das Halten ihrer Essenz schmerzt dem Gemüt...\n\nAber genug davon. Ich mache mich an den Gegenzauber, damit wir das Portal bald erstellen können. Stratholme wird bald Unser sein, ich weiß es einfach.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27360] = {title = "Rache für unsere Soldaten", objective = "Tötet 10 Unterseebootmatrosen der 7. Legion.", description = "Die 7. Legion… Sie haben uns mitten in der Nacht überrannt. Ihr Hauptmann hat Befehle gebrüllt, während die Besatzung des U-Boots meine Männer abgeschlachtet hat. Dann kam er zu mir, sah mir direkt in die Augen und sagte etwas, das ich nie vergessen werde:\n\n\"Ich bin Hauptfeldwebel Pietro Zaren, Offizier der 7. Legion. Wenn Ihr in Euren Alpträumen seht - wenn Ihr überhaupt noch schlafen könnt - wie Eure Soldaten massakriert werden, dann erinnert Euch an meinen Namen und zittert!\"\n\nRächt meine Soldaten! Tötet die 7. Legion, die das Kathedralenviertel von Gilneas südwestlich von hier besetzt.", progress = nil, completion = "Obwohl wir in der Schlacht bloßgestellt wurden, konnte der Feind keinen Sieg erringen. Ich werde das niemals vergessen, &lt;Name&gt;.\n\nWenn ich es heil in den Silberwald zurück schaffe, werde ich mich wahrscheinlich ausmustern. Der Krieg steckt mir nicht im Blut.", rewards = "U-BootfahrertöterRutsakträgerKriegsblutumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27361] = {title = "Vom Licht begünstigt", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Das Licht scheint wirklich hell auf Euch und Eure Hingabe zur Allianz, <Name>. Ihr seid wahrhaftig ein gutes Beispiel für Eure Priesterkameraden und Kampfgenossen.\n\nIn Anerkennung Eurer Taten hat König Wrynn den königlichen Verzauberer beauftragt, einen besonderen Stab für Euch anzufertigen.\n\nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich kann kaum glauben, dass Ihr all diese Materialien wirklich erhalten konntet. Ich persönlich kann mir nicht vorstellen, mich nach Burg Schattenfang zu trauen. Die Geschichten über diesen Ort sind entsetzlich.\n\nAber genug davon. Diese Zeit ist der Anerkennung Eurer Leistungen gewidmet, nicht dem Geschwätz über meine Ängste.", rewards = "Ihr bekommt:\n\nStab der Geheiligten"}
MultiLanguageQuestData['de'][27362] = {title = "Elunes Liebling", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Ihr seid ein echter Diener Elunes, ein Beispiel für unser Volk, und ein tapferer Diener der Allianz. Der Tempel des Mondes und der Hof von Sturmwind möchten Eure Leistungen ehren.\n\nWir haben den königlichen Verzauberer beauftragt, einen Stab für Euch zu fertigen.\n\nDie Materialien für Euren Stab können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMondstab von Elune"}
MultiLanguageQuestData['de'][27363] = {title = "Vielversprechend für den Chirurgenberuf", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Ihr habt Euch als fähig in den Reihen der Priester und als wertvoll für die Leute von Gnomeregan erwiesen. Der Hochtüftler und der König von Sturmwind möchten Eure Arbeit für die Allianz ehren.\n\nSie haben den königlichen Verzauberer beauftragt, einen besonderen Stab anzufertigen.\n\nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab des Technokraten"}
MultiLanguageQuestData['de'][27364] = {title = "Auf wessen Befehl?", objective = "Findet die Befehle des Oberkommandos.", description = "<Das K.d.V. summt.>\n\nDie 7. Legion sind besondere Eliteeinheiten. Sie waren hinter den Kulissen für fast alle größeren Offensiven und Militäreingriffe der Allianz zuständig. Das sind schlechte Neuigkeiten. Wie sind sie nur an unseren Kriegsschiffen vorbei gekommen? Und auf wessen Befehl agieren sie?\n\nWir müssen ihre Befehle irgendwie in die Hände bekommen. Dieser Pietro hat sicherlich wichtige Informationen. Findet ihn im Kathedralenviertel von Gilneas und erledigt ihn. Durchsucht danach seinen Leichnam nach Hinweisen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27365] = {title = "Eine passende Waffe", objective = "Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein vom Baron, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", description = "Schon zu Beginn haben Eure Lehrer gewusst, dass Ihr Euch bei der Horde einen Namen machen werdet. Ihr habt mutig gekämpft und Euren Feinden Grund zur Angst gegeben.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Grezz Zornfaust hat gesagt, ich soll Euch erwarten. Diese Materialien werden ein ausgezeichnetes Schwert machen. Benutzt es für den Ruhm der Horde.", rewards = "Breitaxt der HordeGroßaxt der HordeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27366] = {title = "Landerschließung", objective = "Tötet 12 Marinesoldaten der Axtbeißer am Zwielichtufer im Schattenhochland.", description = "Die Marinesoldaten der Axtbeißer der Horde sind überall an meinem heiß geliebten Strand.\n\n<Der Leutnant deutet in Richtung Norden, entlang der Küste.>\n\nTötet sie.", progress = nil, completion = "Tot? Alle?\n\nImmerhin ein Anfang, &lt;Klasse&gt;.\n\nImmerhin ein Anfang.", rewards = "StrandräumerzauberstabAuf Euch wartet eine dieser Belohnungen:\n\nSignet der blutigen Sande\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27367] = {title = "Gidwin Goldzopf", objective = "Findet Gidwin Goldzopf in den Östlichen Pestländern.", description = "Meine Jungs sind mir viel wert, versteht mich nicht falsch. Aber ich habe ihnen GESAGT, dass ich FÜNF MINUTEN brauche, um die Pferde zu versorgen und was machen sie? Schließen eine blöde Wette ab und weg sind sie! Ich hätte es besser wissen müssen... es ist immer das Gleiche.\n\nGidwin ist der kurz Gewachsene. Er hat sich in Richtung Norden aufgemacht, den Fluss entlang. Wenn Ihr in diese Richtung unterwegs sein solltet, könnt Ihr ihm sagen, er soll zurückkommen? Wir müssen zur Kapelle des Hoffnungsvollen Lichts und ich habe kein Problem damit, ihn zurückzulassen.", progress = nil, completion = "Tarenar? Bist du das?\n\nWer immer Ihr seid, würde es Euch etwas ausmachen, mir aus diesem Ding herauszuhelfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27368] = {title = "Nur eingehüllt", objective = "Erhaltet 8 Phiolen Kryptengalle von den Nerubern im Schreckenstunnel.", description = "Ihr hättet mich im Kampf sehen sollen! Ich hab bestimmt sechs dieser Biester getötet, als...\n\nOh, stimmt, Ihr könnt ja die Leichen sehen. Na gut. Vier der Biester habe ich getötet und dann kam das fünfte an und hat dieses Netz auf mich geschossen. Und noch viel schlimmer: Als es seinen Netzsaft abgeschossen hat, war mein Mund offen!\n\nIch kann dieses Netz nicht zerstören und Ihr werdet es wohl auch nicht können. Aber die Magensäfte von den untoten Spinnendingern könnten das Netz auflösen. Das funktioniert sicher.", progress = "Oh Mann... Fiona wird wütender sein als eine nasse Harpyie. Beeilt Euch bitte.", completion = "Ihr seid zurück?! Dem Licht sei Dank!\n\nBevor Ihr die Säure über mir ausschüttet, habe ich eine Frage: seid Ihr der Typ von vorhin, oder einer dieser achtbeinigen Feiglinge? Ich muss wissen, ob ich Euch eins überbraten sollte, sobald ich hier raus bin.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKnockback 50 No Log\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27369] = {title = "Das Rad schmieren", objective = "Pflückt 10 Bansheeglocken vom Ufer des Thondroril.", description = "Entschuldigt mein Verhalten von eben. Ich war einfach sicher, Ihr wärt eines dieser Spinnenbiester, das sich als <Volk> ausgeben wollte.\n\nWie geht es Euch? Gidwin Goldzopf, zu Euren Diensten. Ich bin ein bisschen in Eile, weil ich schnell zurück zu meinem Karawanenwagen muss, aber ... könntet Ihr mir vielleicht noch einen Gefallen tun? Meine Freundin Fiona hat einen kleinen Laden und ich glaube, dass einige der Pflanzen, die hier am Flussufer wachsen, für sie von Interesse wären.\n\nIch glaube, wenn ich ihr ein paar tolle Pflanzen mitbringe, wird sie VIEL weniger sauer auf mich sein. Das ist zumindest der Plan.", progress = "Hat Giddy Euch mit hineingezogen?", completion = "Ich werde diesen winzigen Paladin in Stücke hauen, noch bevor er... oh, sind das etwa Bansheeglocken? Ihr habt die für mich gepflückt?\n\nOh, Gidwin hat Euch darum gebeten? Das ist wirklich süß von ihm. Na gut. Jetzt kann ich ihm fürs Erste nicht mehr böse sein.", rewards = "Handschuhe des BlümchenpflückersTreter der BansheeglockenThondrorilstiefelGiddys alte HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27370] = {title = "Tarenar Sonnenhieb", objective = "Findet Tarenar Sonnenhieb an der Treppe des Schnitters in den Östlichen Pestländern.", description = "Kaum hatten wir Halt gemacht, haben sie eine Wette abgeschlossen, wer die meisten Untoten in fünf Minuten töten könne.\n\nDas ist jetzt eine Stunde her und ich warte immer noch darauf, dass sie wieder herkommen.\n\nIch habe gesehen, wie Tarenar in Richtung Südosten losgelaufen ist. Aber leider kann ich den Wagen nicht unbeaufsichtigt lassen. Wenn Ihr zufällig in diese Richtung unterwegs sein solltet, könntet Ihr ihn suchen und zu mir zurückschicken?", progress = nil, completion = "Ich habe sie gefunden, &lt;Volk&gt;. Die Geißel. Wie ich mich nach diesem Tag gesehnt habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27371] = {title = "Was ich am besten kann", objective = "Tötet 5 Missgeburten der Treppe des Schnitters an der Treppe des Schnitters in den Östlichen Pestländern.", description = "Ich erinnere mich an die Zeit zurück, als ich jung war und mich oft in die Geisterlande geschlichen habe, um stundenlang Zombies zu verprügeln. Ich habe nicht einmal eine BEZAHLUNG dafür erhalten. Ich hab es einfach so gemacht.\n\nAber jetzt schaut Euch mal um. Das sind ernst zu nehmende Zombies. Ich wollte gerade damit anfangen, sie zu verprügeln, so wie früher. Wollt Ihr mir helfen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27372] = {title = "Ein Geschenk für Fiona", objective = "Erhaltet 10 Proben des Bluts eines Seuchenhundes.", description = "Meine Reisegefährtin, Fiona, hat in ihrem Karawanenwagen einen kleinen Laden. Wir beide und unser Freund Gidwin sind auf dem Weg zur Kapelle des Hoffnungsvollen Lichts. Ihr könnt sicher mit uns reisen, wenn Ihr wollt... obwohl Fiona womöglich ein wenig sauer auf mich sein wird.\n\nFiona vergisst aber immer, dass sie sauer ist, wenn man ihr ein Geschenk macht. Tötet für mich ein paar dieser Seuchenhunde und bringt ihr Blut zu Fiona bei der Karawane unten am Fluss. Sie wird sich über alle Maßen freuen. Wir sehen uns dann dort!", progress = "Ich hätte es wissen müssen. Tarenar hat dafür gesorgt, dass Ihr mir ein Geschenk macht? Dieser gedankenlose Idiot!\n\nÄhm... Um was für ein Geschenk handelte es sich denn?", completion = "Das ist ganz genau das, was ich gebraucht habe! Na gut, ich werde Tarenar dafür vergeben, dass er davongelaufen ist.\n\nIhr seid hier bei uns jederzeit willkommen, &lt;Name&gt;.", rewards = "KarawanenschärpeGürtel der BeschwichtigungSeuchenhundarmbänderBesänftigende BrustplatteHelm der aufmerksamen GeschenkeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27373] = {title = "Auf zur Kapelle des Hoffnungsvollen Lichts", objective = "Steigt auf Fionas Karawanenwagen am Thondroril in den Östlichen Pestländern.", description = "Jetzt, da die Jungs wieder hier sind, können wir endlich los. Ihr seid in Richtung Osten unterwegs?\n\nEs wäre uns eine Freude, wenn Ihr mit uns reisen würdet. Ich bestehe darauf! Erst gestern bei der Stätte der Heiler habe ich zu Tarenar gesagt: \"Wir haben zwei Paladine und mich, um auf den Laden aufzupassen, aber weißt du, was wir wirklich brauchen? <Einen echten Helden/Eine echte Heldin>!\"\n\nSeht mich nicht so an! Ehrlich! Kommt schon, springt auf!", progress = nil, completion = "Ich hoffe, die Fahrt war nicht zu holprig für Euch.\n\nSeht Euch einmal in der Gegend um den Turm herum um, solange sich die Pferde ausruhen. Es ist zwar nicht mit der Kapelle des Hoffnungsvollen Lichts zu vergleichen, aber ich bin mir sicher, dass Ihr Euch irgendwie beschäftigen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27374] = {title = "Der Schlund des Wahnsinns", objective = "Sprecht am Kreis der Elemente mit Erdenrufer Torunskar.", description = "Ich kann es nicht glauben, <Name>. Mein eigener Sohn - mein eigen Fleisch und Blut! Tut sich mit diesen Unholden vom Schattenhammer zusammen. Habt Ihr gesehen, was aus ihm wurde, als er versuchte, die Hochzeit zu zerstören? Oh... warum? Warum?\n\nEs ist diese Bestie, <Name>. Der gigantische Schlund, der im Westen aus der Erde ragt. \"Der Schlund des Wahnsinns!\" Mein Sohn sagte, er würde mit ihm sprechen, aber ich dachte, es wären nur Alpträume.\n\nDer Irdene Ring versucht, ihn zu zerstören. Geht zu Erdenrufer Torunskar, westlich von hier, und schaut, ob Ihr helfen könnt!", progress = nil, completion = "Willkommen, Bruder. Ihr habt eine schwere Zeit ausgesucht, um uns beizutreten, aber für uns ist das ein Glück. Wir können Eure Hilfe brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27375] = {title = "Die Schwärende Wunde", objective = "Sprecht mit Erdenrufer Torunskar am Kreis der Elemente.", description = "Eine Bestie, <Name>! Ich habe eine Bestie gesehen. Ein riesiger Schlund, ein noch größerer Hunger. Ich kann nicht glauben, dass sie wissen, was sie da losgelassen haben.\n\nEs ist hier. Sein schrecklicher formloser Körper bricht in diesem Augenblick in das Hochland herein.\n\nIch habe Euch in meiner Vision gesehen, <Name>. Ihr kämpft zusammen mit dem Irdenen Ring, um das Biest zurückzudrängen. Ihr werdet der Dunkelheit gegenübertreten.\n\nGeht jetzt, bevor die Bestie an Macht gewinnt. Sprecht mit Erdenrufer Torunskar am Kreis der Elemente, nordwestlich von hier auf dem Gebirgskamm, hinter dem zerstörten Drakgorlager. Schnell!", progress = nil, completion = "Willkommen, Bruder. Ihr habt eine schwere Zeit ausgesucht, um uns beizutreten, aber für uns ist das ein Glück. Wir können Eure Hilfe brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27376] = {title = "Das Maul von Iso'rath", objective = "Steigt auf einen Greifen, um dem Angriff auf Iso'rath beizutreten.", description = "Wir sind bereit, die Bestie anzugreifen. Erst müssen wir ihre Tentakel zerstören, dann wird Yevaa ein Ritual durchführen, um einen mächtigen Feuerelementar zu beschwören, den wir in den Schlund werfen werden.\n\nIch möchte, dass Ihr mit unserer ersten Gruppenattacke ausfliegt. Tut nichts, bis sich eine Gelegenheit bietet, dann tretet dem Kampf bei, indem Ihr mit den anderen Schamanen die Tentakel abschneidet.\n\nNehmt einen unserer Greifen, wenn Ihr für den Angriff bereit seid.", progress = nil, completion = "Die Tentakel haben uns sogar von den Greifen geschlagen! Sie waren viel beweglicher, als wir angenommen hatten.\n\nEgal. Wir waren auf diese Möglichkeit vorbereitet. Ich kann den Elementar von hier aus beschwören, wenn Ihr mich beschützt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27377] = {title = "Verschlungen", objective = "Schützt Euch und Erdenruferin Yevaa vor Iso'raths körperlicher Verteidigung.", description = "Wir wussten, dass das eine Möglichkeit war, aber wir hatten keine Ahnung, wie sich die Bestie verteidigen würde. Iso'raths Körper reagiert schnell auf unsere Bedrohung.\n\nIch kann die Beschwörung von hier aus beendet, aber nur, wenn Ihr Iso'raths Vereidigung zurückhalten könnt. Beschäftigt sie! Wir werden überleben!", progress = nil, completion = "Ich habe Euch von der Schwelle des Todes zurückgeholt, Held!\n\nTodesschwinge ist da! Wir brauchen Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27378] = {title = "Der Weltenbrecher", objective = "Bezwingt Todesschwinge, den Aspekt des Todes.", description = "Wir haben keine Zeit! Todesschwinge hat zugeschlagen, bevor wir uns gegen ihn aufstellen konnten. Wenn Ihr ihn nicht aufhaltet, endet der Irdene Ring hier und jetzt!", progress = nil, completion = "Ihr seid wach! Den Elementen sei Dank! Ich hatte fast die Hoffnung verloren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27379] = {title = "Die Schrecken des Iso'rath", objective = "Rettet Hargoth Trübflamm, Erdheiler Duarn, Sturmruferin Jalara und Sturmruferin Mylra.\n\nKehrt in den Schutz der anderen Schamanen zurück, wenn Iso'raths Verteidigung Euch zusetzt.", description = "Wir brauchen Euch! Ihr wart in einer Art Alptraum gefangen. Viele der anderen Schamanen sind das immer noch.\n\nEgal... unser Plan fällt auseinander. Einige unserer Schamanen kanalisieren schützende Auren, die die Verdauungsflüssigkeiten bekämpfen und Euch am Leben halten, aber wir müssen die anderen Schamanen vor den Tentakeln retten. Wir können Iso'rath nicht ohne sie besiegen!\n\nBleibt nicht ohne die anderen Schamanen im Magen, oder Ihr werdet bei lebendigem Leib verdaut!", progress = "Die Schlacht ist noch nicht geschlagen. Die Schamanen innerhalb von Iso'rath zählen auf Euch!", completion = "Zusammen mit dem Irdenen Ring können wir Iso'raths Schrecken überleben. Jetzt ist es an der Zeit, uns zu rächen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27380] = {title = "Alptraum", objective = "Zerstört Iso'raths Gehirn.", description = "Iso'raths Hirn liegt frei! Der Schamane, den Ihr gerettet habt, sollte Euch in seiner Verteidigung einigermaßen sicher halten.\n\nGreift das Hirn an und zerstört Iso'rath!", progress = nil, completion = "Ihr habt heute viele meiner engsten Vertrauten gerettet, &lt;Name&gt;. Ich kann mir kaum vorstellen, was für Schrecken Ihr in Iso'rath gesehen habt, aber Ihr habt den Dank des gesamten Irdenen Rings.", rewards = "Bedeckung der nässenden NarbeWundenversiegelnde GamaschenAuf Euch wartet eine dieser Belohnungen:\n\nAlptraumhalsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27381] = {title = "Reisegefährten", objective = "Findet jemanden am Turm der Kronenwache, der sich Eurer Reisegruppe anschließen möchte.", description = "Jetzt wo wir schon hier an diesem Turm sind, können wir auch schauen, ob außer uns noch jemand zur Kapelle des Hoffnungsvollen Lichts unterwegs ist. Je mehr, desto besser, nicht wahr?\n\nFragt doch in der Umgebung, ob uns jemand auf der Reise begleiten möchte. Ich bin sicher, dass wir jemand finden werden, der auch zur Kapelle unterwegs ist.", progress = "Wie sieht es aus?", completion = "Argus Leuchtfeuer ... der Alte von hoch oben im Turm? Großartig!\n\nEin Mann seines Alters gehört dem Argentumkreuzzug bestimmt schon ewig an. Vielleicht kann er bei der Kapelle ein gutes Wort für uns einlegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27382] = {title = "Verseuchte Straßen", objective = "Tötet 13 Seuchenfledermäuse entlang des Wegs zum Lichtschildturm.", description = "Der Argentumkreuzzug hat diese Türme als Lichter in der Dunkelheit der Pestländer errichtet. Ich bin auf den Pfaden zwischen den Türmen unterwegs, um sie zu schützen und instand zu halten.\n\nIn letzter Zeit wurden die Straßen aber immer gefährlicher. Verseuchte Wildtiere laufen frei herum und die Fledermäuse greifen nichtsahnende Reisende an. Es würde den nächsten Teil meiner Reise sehr erleichtern, wenn Ihr für mich die wilden Tiere aus dem Weg schaffen könntet.", progress = nil, completion = "Natürlich war es für einen jungen &lt;Volk&gt; wie Euch nicht schwierig, ein paar Wildtiere zu beseitigen. Jetzt, da die Straßen geräumt sind, wird meine Reise zum nächsten Turm viel einfacher.", rewards = "Pantoffeln des einsamen WegsSeuchenfledermauswesteArmbänder der KronenwacheTreter der JugendIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27383] = {title = "Klein-Pamela", objective = "Sucht in Darroheim nach Pamela Rotpfad.", description = "Die Schlacht von Darroheim verfolgt mich immer noch, <Volk>. Ich wache in kaltem Schweiß auf, felsenfest davon überzeugt, dass ich noch dort bin. Diese Träume holen mich immer und immer wieder ein.\n\nMit dem Tod meiner Kameraden komme ich einigermaßen klar, aber der Tod meiner Familienmitglieder schmerzt immer noch gnadenlos. Eine meiner Verwandten, die ich bei dem Angriff verloren habe, war meine kleine Nichte Pamela.\n\nWenn Ihr mutig genug seid, Darroheim aufzusuchen, könnt Ihr nach einem Zeichen von meiner kleinen Pammy suchen? Die Ruinen von Darroheim sind südlich von hier.", progress = nil, completion = "Hallo. Ich bin Pamela und wie heißt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27384] = {title = "Pamelas Puppe", objective = "Sucht Pamelas Puppe.", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", progress = "Habt Ihr meine Puppe gefunden?", completion = "Ihr habt sie gefunden! Ihr habt meine Puppe gefunden! Oh, danke!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27385] = {title = "Onkel Carlin", objective = "Kehrt zu Carlin Rotpfad am Turm der Kronenwache in den Östlichen Pestländern zurück.", description = "Ich werde mit meiner Puppe spielen, aber mit Papas Schwert will ich doch nicht spielen. Ihr könnt es haben.\n\nOder könnt Ihr es vielleicht doch lieber Onkel Carlin geben? Ich weiß nicht, wo er ist, aber manchmal höre ich ihn weinen. Es klingt, als ob er in der Nähe ist, nördlich von hier. Ich hoffe, er weint nicht wegen mir! <Name>, könnt Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht? Wenn Ihr ihn findet, sagt ihm, ich warte auf ihn und ich will die Geschichte hören, die er mir immer erzählt hat ... die von den Kaninchen und der Beerenmarmelade! Die Geschichte ist so witzig!", progress = "Gibt es Neuigkeiten von meiner Pammy?", completion = "Ihr habt Pamela gesehen? Ist sie am Leben?\n\nSie ist tot? Nein! Oh, Pamela! Warum leidet dein Geist noch immer in dieser Welt? Warum musstest du sterben, wenn ich am Leben gelassen wurde? Ohne zu zögern würde ich mit dir tauschen und tot durch Darroheim wandern, als Geist und ganz allein! Ah, diese Nachrichten können mein Schicksal nicht ändern. Ich danke Euch, &lt;Name&gt;. Jetzt ruft meine Pflicht, die Pflicht nach Rache, lauter als je zuvor.\n\nSagt, was ist das für ein Schwert, das Ihr da habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27386] = {title = "Ein seltsamer Historiker", objective = "Bringt Josephs Jagdklinge zu Chromie.", description = "Dieses Schwert hat Joseph Rotpfad gehört, Pamelas Vater - aber das wisst Ihr wahrscheinlich schon. Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das ist unmöglich. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster.\n\nPamelas Schicksal ist besiegelt, aber vielleicht können wir sein Schicksal ändern.\n\nEine komische Gnomin kam hier vor Kurzem am Turm an. Sie heißt Chromie. Bringt dieses Schwert zu ihr. Ich habe das Gefühl, dass sie uns helfen kann.", progress = "Euer Besuch kommt gerade zur rechten Zeit. Ihr seid nicht aus der Zukunft, oder?", completion = "Was ist das? Ein Kriegsschwert? Ein Buttermesser? Ich habe keine Ahnung von Klingen. Lasst mich das genauer betrachten...\n\nAh! Dieses Schwert hat einst einem guten Mann gehört, aber in der Vergangenheit dieses Mannes ist viel Schlimmes passiert.\n\nSeid Ihr hier, um ihm zu helfen? Dafür ist es schon lange zu spät... aber vielleicht können wir ihm in der Vergangenheit helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27387] = {title = "Bösewichte von Darroheim", objective = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.", description = "Die 'Annalen von Darroheim' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghulfürst Horgus der Verheerer von Allianztruppen während der Schlacht vernichtet wurde. Er wurde im Vorgebirge nördlich von hier getötet und dort liegt sein Schädel noch heute.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert verrostet nun herrenlos... Man kann es in der Nähe der Straße südöstlich von uns finden.\n\nStellt diese Gegenstände sicher, <Name>. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", progress = "Habt Ihr den Schädel und das Schwert gefunden, <Name>?", completion = "Ihr habt sie gefunden! Gut gemacht, &lt;Name&gt;! Diese Relikte enthalten die Erinnerungen der Streitkräfte der Geißel, die in Darroheim gefallen sind. Diese werden wir brauchen, wenn wir Euren Joseph Rotpfad retten wollen.", rewards = "Gugel der RevisionChromies SpiegelWeste der EntdeckungKniehosen des SuchersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27388] = {title = "Helden von Darroheim", objective = "Erhaltet die Erweiterten Annalen von Darroheim von Carlin Rotpfad sowie Davils Buchband und Rotpfads Schild in Marris' Siedlung.", description = "Die Helden von Darroheim hatten ebenfalls Relikte und darin sind weitere wertvolle Erinnerungen gefangen. Sprecht zunächst mit Carlin und erhaltet die erweiterten Annalen von Darroheim. In diesem Folianten findet sich die Geschichte, die Eure Reise durch die Zeit führen wird.\n\nDanach müsst Ihr westlich reisen, um zu Marris' Siedlung zu gelangen. Der ehemalige Besitzer von Marris' Siedlung sammelte Relikte aus der Schlacht um Darroheim. Warum er das tat, kann ich nicht mit Sicherheit sagen. Sammelt diese Relikte und kehrt zu mir zurück.", progress = "Habt Ihr die Relikte, <Name>?", completion = "Ihr habt die Relikte? Gut. Ich werde mich darum kümmern, etwaige zeitliche Störstellen zu korrigieren.\n\nSorgt Euch nicht... darüber müsst Ihr Euch wirklich keine Sorgen machen. Ihr seid nur für das Auffinden der Reagenzien zuständig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27389] = {title = "Marodeure von Darroheim", objective = "Bringt 5 widerhallende Schädel zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.", description = "Ich benötige ein seltenes Reagenz für den mächtigen Zauberspruch, den zu wirken ich vorhabe: Schädel der Geißelschergen, die an der Schlacht von Darroheim teilnahmen.\n\nNehmt diesen Kristall und jagt Champions der Geißel, um an ihre Schädel zu gelangen. Der Kristall ist verzaubert: Er wird widerhallen, wenn Ihr ihn über den Schädel eines Champions haltet, der an der Schlacht teilgenommen hat. Bringt mir die Schädel der Krieger, bei denen der Kristall widerhallt.\n\nGeht, <Name>. Ihr werdet die Champions der Geißel im Fungustal nördlich von hier finden. Geht.", progress = "Habt Ihr die Schädel? Sie sind für den Zauber unglaublich wichtig. Mit ihrer Hilfe werden wir Darroheim retten können. Möglicherweise.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ihr habt so was wirklich noch nie gemacht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27390] = {title = "Die Schlacht um Darroheim", objective = "Legt das Reliktbündel auf den Marktplatz von Darroheim.\n\nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.\n\nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.\n\nBesiegt Rotpfad den Verderbten.\n\nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint.", description = "Nun, <Name>, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", progress = "Ich glaube, ich habe da draußen Geister gehört. Sie flüstern mir schreckliche Dinge zu...", completion = "Der Kampf ist vorüber! Ich habe meinen Vater zu mir flüstern hören. Er hat alle Geister verjagt und sagt, dass er nach Hause kommt! Ich bin so froh!\n\nEr sagte außerdem, dass ich Euch willkommen heißen sollte, wenn Ihr zu uns nach Hause kommt, daher habe ich Euch etwas Tee zubereitet!\n\nIch hoffe, Ihr mögt ihn mit viel Zucker!", rewards = "Schulterstücke von DarroheimGutmütige BrustplatteHeimkehrwickeltuchIhr bekommt:\n\nSüßer Tee"}
MultiLanguageQuestData['de'][27391] = {title = "Versteckte Schätze", objective = "Bringt Josephs Schlüssel zu Josephs Truhe.", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, <Name>. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", progress = "Diese Truhe ist alt und rußverschmiert.", completion = "Der Schlüssel passt in das Schloss und die Truhe öffnet sich...", rewards = "MilizbeilErhellender StabRotpfadarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nVersteckter Schatz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27392] = {title = "Ich soll Euch das eigentlich nicht verraten", objective = "Erhaltet Josephs Jagdklinge von dem Einsamen Jäger in den Östlichen Pestländern.", description = "Mein Papa hat immer zwei Schwerter gehabt: eines für den Kampf und eines für die Jagd. Ich sollte eigentlich die Schwerter nicht anfassen, aber ich wusste, wo er sie versteckt.\n\nEines Tages hat er meiner Mama gesagt, dass er einen \"einsamen Jäger\" in den Hügeln östlich von hier bekämpfen würde, aber er hat sein Schwert für die Jagd von Tieren mitgenommen! Als er zurückkam, hatte er kein Schwert bei sich.\n\nWenn Papa zurückkommt, wird er sich so freuen, wenn ich sein Jagdschwert für ihn habe! Könnt Ihr es für mich finden?", progress = "Papa liebte seine Jagdklinge. Er wirkte traurig, als sie weg war.", completion = "Das ist Papas Schwert! Wie habt Ihr es gefunden? Habt Ihr den bösen Jäger gefunden?", rewards = "Balg des einsamen JägersLohn des FindersJosephs ErsatzgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27393] = {title = "Der Ruf der Klinge", objective = "Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj'ir.", description = "Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.", progress = nil, completion = "Die Wellensprecherin hatte Recht. Da ist etwas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27394] = {title = "Der Ruf der Klinge", objective = "Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj'ir.", description = "Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.", progress = nil, completion = "Die Wellensprecherin hatte Recht. Da ist etwas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27395] = {title = "Die Waffe eines Schützen", objective = "Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen", description = "Ihr habt die Wege der Jäger schnell erlernt, <Name>. Eure Fähigkeiten sind für die Horde äußerst wertvoll und Ihr seid beispielhaft für den Nachwuchs.\n\nAls Belohnung für Eure Fortschritte und Eure harte Arbeit hat der Kriegshäuptling bei seinem Bogenmacher die Herstellung einer besonderen Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich fühle mich geehrt, dass der Kriegshäuptling mich beauftragt hat, eine Waffe für Euch herzustellen, &lt;Name&gt;. Mit diesen fremdartigen Materialien wird es ein feiner Bogen werden.", rewards = "Ihr bekommt:\n\nBogen des großen Jägers"}
MultiLanguageQuestData['de'][27396] = {title = "Klinge der Zerschmetterten Hand", objective = "Reist nach Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", description = "Viele Mitglieder der Zerschmetterten Hand überleben ihre Ausbildung nicht, <Name>. Ihr habt nicht nur überlebt, sondern werdet bald auch eine gefürchtete Klinge für die Horde darstellen.\n\nAls Belohnung für Euren Fortschritt hat der Kriegshäuptling bei seinem eigenen Schmied eine Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Gordul hat mir schon gesagt, dass Ihr eine Vielzahl ungewöhnlicher Materialien bringen würdet, aber mit so etwas habe ich nun wirklich nicht gerechnet. Mondstahl soll äußerst selten sein und es gibt nur einen Ort von dem ich weiß, an dem man es bekommen kann. Ihr habt für diese Waffe ein großes Risiko auf Euch genommen, &lt;Name&gt;, und ich werde dafür sorgen, dass Ihr eine passende Belohnung bekommen werdet.", rewards = "Ihr bekommt:\n\nKlinge der Zerschmetterten Hand"}
MultiLanguageQuestData['de'][27397] = {title = "Die Aufgabe eines Traumsuchers", objective = "Reist nach Burg Schattenfang und erhaltet den Talisman des Wolfmeisters von Wolfmeister Nandos, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", description = "Die Elemente und Geister sprechen in klaren Stimmen zu Euch, <Name>. Ihr seid ein mächtiges Mitglied in den Rängen der Schamanen und ein Beispiel für alle, die der Horde dienen möchten.\n\nSelbst der Kriegshäuptling hat von Euch erfahren, und er hat bei seinem Schmied die Herstellung einer besonderen Waffe für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt Lord Waldens Talisman, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ah, Ihr müsst &lt;Name&gt; sein. Kardris sagte, dass Ihr Euch nach Burg Schattenfang aufgemacht habt, um die Materialien zu finden, die für diese Waffe benötigt werden. Ich sehe, Ihr habt uns nicht enttäuscht. Ich werde eine mächtige Waffe herstellen, die der Materialien würdig ist.", rewards = "Kriegsaxt des RednersZauberaxt des RednersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27398] = {title = "Die Schlacht ist gewonnen, der Krieg geht weiter", objective = "Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.", description = "Wir haben die Truppen des Feindes hier besiegt, <Name>. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.", progress = nil, completion = "Eure Hilfe kommt genau zur rechten Zeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27399] = {title = "Die Schlacht ist gewonnen, der Krieg geht weiter", objective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", description = "Wir haben die Truppen des Feindes hier besiegt, <Name>. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.", progress = nil, completion = "Eure Hilfe kommt genau zur rechten Zeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27400] = {title = "Beherrschung des Arkanen", objective = "Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Alle Eure Lehrer sind sich einig, <Name>, dass Ihr für einen Gesellen unglaubliches Talent zeigt. Selbst der Kriegshäuptling hat von Eurem schnellen Fortschritt gehört.\n\nAls Belohnung für Eurer Verständnis für das Erlernte hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines besonderen Stabs in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das magische Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ah, Ihr müsst die &lt;Klasse&gt; sein, die Uthel'nay erwähnte. Ich habe Geschichten über die Artefakte der Familie Silberlein gehört, aber sie bisher nie zu Gesicht bekommen. Das sollte einen ausgezeichneten Fokus bei Eurem Stab machen. Lasst uns anfangen.", rewards = "Ihr bekommt:\n\nStab des arkanen Pfades"}
MultiLanguageQuestData['de'][27401] = {title = "Was uns morgen erwartet", objective = "Benutzt das Teleskop der 7. Legion, um den Hafen auszuspähen.", description = "<Das K.d.V. summt.>\n\nSeht Euch im Kathedralenviertel um. Dort sollte irgendwo ein Teleskop sein, das die 7. Legion zur Beobachtung benutzt. Findet es und benutzt es, um den Hafen auszuspähen. Wir müssen herausfinden, wie die 7. Legion an unserer Flotte vorbeigekommen ist.\n\nBeeilt Euch, <Name>. Wir können diese Bestien nicht sehr viel länger zurückhalten.\n\nWas uns morgen wohl erwartet?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27402] = {title = "Zeichen der Macht", objective = "Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", description = "Ihr erlernt unsere Wege in einem atemraubenden Tempo, <Name>, und ich bin bei Weitem nicht der Einzige, der von Eurem Fortschritt beeindruckt ist. Der Kriegshäuptling selbst hat Eure Taten schon zur Kenntnis genommen.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Verzauberer die Herstellung eines Stabes in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und Essenzen der Geister, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ihr seid also der Hexenmeister, für den dieser Stab ist. Es wird eine passende Belohnung für jemanden, der mit solcher Hingabe für den Machterlang und die Vorherrschaft der Horde kämpft.", rewards = "Ihr bekommt:\n\nStab des linken Pfades"}
MultiLanguageQuestData['de'][27403] = {title = "Ein echter Sonnenwandler", objective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.", description = "Ich habe Eure Ausbildung beobachtet, <Name>. Ihr habt den Weg eines beispielhaften Sonnenwandlers eingeschlagen und seid ein mutiger Verteidiger der Horde und ein Anhänger unserer Wege.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Streitkolben des SonnenläufersKriegshammer des SonnenläufersGroßschwert der SonnenläuferIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27404] = {title = "Die Zukunft des Zirkels", objective = "Reist nach Burg Schattenfang und erhaltet Waldens Elixiere von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", description = "Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, <Name>. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.\n\nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.\n\nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", progress = "Habt Ihr die Materialien besorgt, die ich für Euren Stab benötige?", completion = "Ah, Ihr müsst der &lt;Klasse&gt; sein, von dem Loganaar erzählt hat. Ich freue mich, Euch endlich zu treffen, &lt;Name&gt;. Ich habe schon oft gehört, wie Mitglieder des Zirkels Euch als talentiert und vielversprechend für die Reihen der Druiden halten, und ich freue mich, dass ihre Einschätzungen auch der Wahrheit entsprechen.", rewards = "Stab des grünen ZirkelsStab des tiefgrünen ZirkelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27405] = {title = "Rückzug!", objective = "Findet Todespirscherkommandant Belmont in Glutstein in den Ruinen von Gilneas.", description = "<Das K.d.V. summt.>\n\n<Im Hintergrund ist Worgengeheul zu vernehmen.>\n\n<Name>, hört Ihr mich? Kommen, <Name>. Das ist wahrscheinlich meine letzte Übertragung. Die Worgen haben den Gefechtsstand der Verlassenen überrannt. Es ist nur eine Frage der Zeit, bis wir den Stützpunkt verlieren. Belmont und die Val'kyr Arthura sind weg. Belmont meinte, er wird Euch in Glutstein treffen, nordöstlich von hier. Findet Belmont, <Name>. Unsere Mission - unsere Existenz - hängt davon ab.\n\nIhr seid unsere letzte Hoffnung.", progress = nil, completion = "Vorpostenkommandant Ansturm hat bis zum bitteren Ende gekämpft, &lt;Name&gt;. Erst eine Meute blutdurstiger Worgen konnte ihn niederringen. Sein Tod und der Tod all unserer Soldaten in Gilneas darf nicht umsonst gewesen sein. Unsere Mission MUSS gelingen.\n\nJetzt werde ich Euch enthüllen, warum wir hier sind.", rewards = "Dolch des wilden GeheulsArmschienen der letzten ÜbertragungGlutsteinbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27406] = {title = "Ein Mann namens Godfrey", objective = "Findet die Leiche von Lord Vincent Godfrey.", description = "Lord Vincent Godfrey hat sein Leben mit der Verteidigung des Königreich Gilneas verbracht. Als der Fluch der Worgen sein Land verheerte, war Godfrey der Erste in Gilneas, der die Waffen gegen die Bestien erhob. Es wird gesagt, dass Godfrey sein Leben nahm, als er herausfand, dass sein König dem Fluch zum Opfer gefallen war. Lieber sei er tot, als dass er den Kreaturen diene, gegen die er sein Land verteidigt hatte.\n\nWir werden ihm eine zweite Chance geben, <Name>. Zusammen werden wir die Schlacht nach Südosten vorantreiben, nach Witterfront, und dort seinen Leichnam einholen.", progress = nil, completion = "Hier, &lt;Name&gt;. Er ist ein wenig verfault, aber es könnte schlimmer sein. Wir müssen uns beeilen, bevor die Allianz uns findet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27407] = {title = "Blutsumpffedern", objective = "Sammelt 5 Blutsumpffedern von Blutsumpfraptoren.", description = "Hat Euch Broggs Anwesenheit erschreckt, <Volk>? Sorgt Euch nicht. Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könnt es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für Zerstörung unserer alten Heimat und Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe bei Vorbereitungen. Für Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus Blutsumpfbau.", progress = "<Brogg blickt Euch voller Hoffnung an.>\n\nIhr bringt Brogg Federn?", completion = "&lt;Brogg nimmt die Federn an sich.&gt;\n\nBrogg froh über die Federn. Sehr mächtige Magie. Brogg weiß nicht, wie Raptoren Federn Macht geben, aber Raptorenfedern immer am besten für Ritual.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27408] = {title = "Das Banner der Steinbrecher", objective = "Beschafft das Banner der Steinbrecher aus Flammenbau.", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort aufbewahrt wurde. Jetzt heißt der Ort Flammenbau.\n\nBrogg braucht Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben. Der alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Banner ist tief in der Höhle. Seid vorsichtig, <Name>.", progress = "Ihr bringt Banner der Steinbrecher?", completion = "Brogg dankt Euch, &lt;Name&gt;. Brogg hat große Pläne für Klanbanner.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27409] = {title = "Die Essenz der Feindschaft", objective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leichen an. Nur tote Drachkin geben ihre Essenzen frei.\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", progress = "Habt Ihr die Essenzen? Brogg braucht sie, um seine Freunde zu rächen!", completion = "Brogg dankt Euch, &lt;Name&gt;. Sobald Brogg die Magie der Essenzen zu dem Totem hinzufügt, kann das Totem die Geister von Broggs gefallenen Freunden befreien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27410] = {title = "Geister der Festung der Steinbrecher", objective = "Gebt 10 Geistern der Steinbrecher bei den Ruinen der Steinbrecher ihre letzte Ruhe.", description = "Brogg hat das Totem fertig gestellt, mit dem den Geistern seiner Freunde Frieden gegeben werden kann. Als die Drachkin einfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk, in der Hoffnung auf einen gemeinsamen Gegenangriff mit den anderen überlebenden Steinbrechern.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher nördlich von hier; verwendet das Totem in der Nähe von Ogerskeletten, um die Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", progress = "Brogg muss wissen, habt Ihr den brutalen Geistern der Steinbrecher Frieden geben können?", completion = "Brogg dankt Euch für Eure Hilfe, obwohl er weiß, dass Oberanführer Mok'Morokk nicht dankbar sein wird. Jetzt können Überlebende der Steinbrecher endlich Probleme der Lebenden lösen und die Toten hinter sich lassen. Brogg muss nur noch eine Sache machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27411] = {title = "Herausforderung für den schwarzen Drachenschwarm", objective = "Platziert das Banner der Steinbrecher am Eingang zu Onyxias Hort und besiegt alle, die reagieren.", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. <Name>, Ihr habt bei den Vorbereitungen für diesen Augenblick sehr geholfen. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr eine Höhle seht, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden ihr Land zurückerlangen!", progress = "Brogg wird seine Rache üben können!", completion = "&lt;Brogg hört Euch zu, als Ihr von den Erlebnissen am Eingang zu Onyxias Hort berichtet.&gt;\n\nBrogg weiß Onyxia tot. Brogg weiß Onyxias Brut noch da. Brogg lässt sie Steinbrecher niemals vergessen.\n\nBrogg ist dankbar für Eure Hilfe, &lt;Name&gt;, und wird nie vergessen, was Ihr für ihn getan habt. Brogg wird nicht ruhen, bis er die Steinbrecher wieder in ihre Heimat gebracht hat.", rewards = "Übergroße Kapuze der SteinbrecherRestaurierte HaudraufstulpenBroggs besserer KampfharnischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27412] = {title = "GESUCHT: Schlächterklaue der Gefräßige", objective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch bei Drazzit Tropfhahn in Morastwinkel.", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden aufgefordert, Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn hat eine großzügige Belohnung ausgeschrieben, die ausgezahlt wird, wenn der Bedrohung durch Schlächterklaue in Morastwinkel ein Ende gesetzt wird.", progress = nil, completion = "Zum Glück ist endlich jemand meiner Aufforderung nachgekommen. Ich dachte schon, dass ich die Belohnung verdreifachen müsste, bevor jemand diesen verdammten Raptor zur Strecke bringt, und das ließ unser Budget einfach nicht zu!", rewards = "RaptorbalgbeinschützerSchützende IngenieursgamaschenAuf Euch wartet eine dieser Belohnungen:\n\nRaptoraugenring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27413] = {title = "Entwindet den Drachen", objective = "Sammelt 8 Stängel der Drachenwinde in Drachendüster oder in Drachensumpf.", description = "Durch den Absturz des Zeppelins mitsamt unseren Vorräten gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun was wir können, aber inmitten all dieser Insekten, umgeben von Feinden bleiben Verletzungen nicht aus, und ich komme meiner Arbeit kaum nach! Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch auch dieser Vorrat geht zur Neige.\n\nDie Pflanze heißt Drachenwinde und sie wächst in Drachendüster und in Drachensumpf östlich von unserer Siedlung. Die Pflanze besteht aus gewundenen Stängeln und wenn man sie ansieht, scheint sie zu pulsieren.", progress = "Konntet Ihr die Drachenwinde finden?", completion = "Vielen Dank! Damit kann ich unsere Jungs versorgen, bis Moxie mit den Vorräten von der Zeppelinabsturzstelle zurückkommt.", rewards = "GesellenschulterklappenGeölte LedergamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27414] = {title = "Die Brut identifizieren", objective = "Draz'Zilb in Brackenwall möchte, dass Ihr ihm 7 sengende Zungen und 7 sengende Herzen bringt.", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, <Name>? Habt Ihr erwartet, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nWidmen wir uns wieder dem wichtigeren Thema: Bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde herausfinden, was es mit diesem Übel auf sich hat ...", progress = "An den Herzen und der Zungen der versengten Nachkommen der Armee der schwarzen Großdrachen kann ich erkennen, von welcher Bestie sie abstammen. Wenn wir mehr über unsere Angreifer wissen, können wir sie vielleicht besser bekämpfen und sie ein für alle Mal zerstören, und die Siedlung der Steinbrecher aus den Ruinen retten.\n\nAllerdings wird es schon eine wahrhaft epische Aufgabe, Mok'Morokk davon zu überzeugen, seinen lethargischen Hintern aus dem Schlammloch zu bewegen ...", completion = "Zweifellos war es eine gefährliche Sache, diese Herzen und Zungen zu sammeln. Ich werde nun in die Tiefen des Arkanen vorstoßen, um den Ursprung der schwarzen Bedrohung zu finden, die über unsere einstige Heimat kam.", rewards = "Grüblerische MaskeSengender DolchWelpentöteraxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27415] = {title = "Die Brut von Onyxia", objective = "Zerstört 5 Eier von Onyxia.", description = "Onyxias Brut wurde über ganz Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nEilt nach Drachensumpf im Süden von Düstermarschen. Gewiss hat sie dort ihren Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir werden das Dorf der Steinbrecher nie zurückerobern können, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht ... für den Jammerlappen habe ich andere Pläne.", progress = nil, completion = "Großartig! Es wird einige Zeit dauern, bis Onyxia wieder Eier legen kann.\n\nIm Namen meines Volkes danke ich Euch, &lt;Name&gt;.\n\nIch habe bislang viel von Euch verlangt. Vielleicht könnt Ihr jedoch dem Steinbrecherklan einen letzten Dienst erweisen.\n\nMok'Morokk ist nicht in der Lage, uns anzuführen. Tharg wäre ein ausgezeichneter Anführer, sieht sich aber durch seine Verletzungen und sein Alter daran gehindert. Vertreibt Mok'Morokk mit Gewalt von hier. Erst dann können wir einen neuen Anführer bestimmen und in unsere angestammte Heimat im Süden zurückkehren.", rewards = "Blutgerötete SchiftungAuf Euch wartet eine dieser Belohnungen:\n\nDrachensumpfamulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27416] = {title = "Die Brut von Onyxia", objective = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", description = "Das Dorf der Steinbrecher wurde von Onyxias Brut überfallen. Aber warum sollte die Tochter des schwarzen Drachenlords Todesschwinge über unser Land herfallen?\n\nEs ist äußerst beunruhigend. Sicherlich wurde Onyxia aus einem anderen Grund hergeschickt, als nur eine kleine Schar von Ogern zu belagern.\n\nVerständigt Mok'Morokk auf der Stelle! Es muss etwas getan werden.", progress = nil, completion = "Warum erzählt Ihr mir von Drachen? Ich mag Drachen nicht. Ich mag es hier. Hier keine Drachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27417] = {title = "Die Brut von Onyxia", objective = "Sprecht mit Draz'Zilb in Brackenwall.", description = "Lasst mich jetzt allein. Sagt Draz'Zilb, dass ich hier bleibe. Hier keine schwarzen Großdrachen.", progress = nil, completion = "Dieser träge Feigling!\n\nMok'Morokk hat Stärke gezeigt, als Rexxar noch unser Anführer war. Doch kurz nach Rexxars Abschied erlag Mok'Morokk den Verlockungen der Macht. Er führte nicht, sondern forderte. Er dient seinem Volk nicht, sondern erwartet, dass wir ihm dienen.\n\nEs muss etwas geschehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27418] = {title = "Fordert Oberanführer Mok'Morokk heraus", objective = "Besiegt Mok'Morokk und erstattet Draz'Zilb in Brackenwall Bericht.", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern Winzling von <Volk>!\n\nIhr sagt mir, wenn bereit für ordentliche Tracht Prügel.", progress = nil, completion = "Dieser feige Fettwanst Mok'Morokk ist geflohen wie ein ängstliches Kind. Ihr habt uns einen großen Dienst erwiesen, &lt;Name&gt;.\n\nJetzt kann mein Volk einen neuen Anführer bestimmen, mit dem wir unsere angestammte Heimat ein für alle Mal zurückerobern werden.", rewards = "Trophäenschultern des OberanführersMok'Morokks SchlagstockDüstermarschenpfählerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27419] = {title = "Armee des schwarzen Großdrachen", objective = "Tharg in Brackenwall möchte, dass Ihr 10 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich die Ruinen der Steinbrecher Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Thargs ScheibeRiesige OgerstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27420] = {title = "Das Unvermeidliche hinauszögern", objective = "Erhaltet Kontrollrunen von den dunklen Kultisten und Schattenmagiern und benutzt das überladene Partikel, um 3 Seuchenverbeiter zu zerstören.", description = "Ihr habt ein gutes Auge, wenn Ihr mich hier in meinem Versteck im Gras sehen konntet.\n\nDas Fungustal liegt vor uns, eine Gegend, an die sich die Geißel noch immer klammert. Sie benutzen schwebende Konstrukte, um das Land ständig neu zu verseuchen, damit es so abstoßend bleibt, wie es jetzt ist.\n\nDie Konstrukte werden von Runen der dunklen Adepten und der Schattenmagier gesteuert. Nehmt die Kontrollrunen der Kultisten an Euch, zielt damit auf die Seuchenverbreiter und erzeugt mit diesem Partikel eine Überlast. Das Ergebnis sollte recht amüsant sein.", progress = nil, completion = "Je eher die Geißel aus dem Fungustal vertrieben ist, desto eher können wir es heilen.\n\nVielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27421] = {title = "Mitten im Tod ist Leben", objective = "Pflanzt Raynes Samenkörner in den Zentren der drei Ziggurats im Fungustal.", description = "Die Streitmächte der Geißel haben es geschafft, jeglichem Leben im Fungustal ein Ende zu bereiten. Das Einzige, was noch zu finden ist, sind die Überreste verfaulter Pilze und versengte Gräser. In den drei Ecken des Tals sind drei große Ziggurats zu finden, in denen die Geißel ihre Toten reanimiert und neue Soldaten für das Schlachtfeld einberuft.\n\nDoch selbst an diesem bösen, leblosen Ort kann Leben gedeihen. Nehmt diese Samen und planzt sie in die Zentren der Ziggurats. Beweist ihnen, dass sich das Leben durchsetzen wird.", progress = nil, completion = "Selbst wenn die Blumen verwelkt sind, kurz nachdem sie geblüht haben, wird das der Geißel eines klarmachen: sie verlieren und wir gewinnen.\n\nVielen Dank für Eure Hilfe.", rewards = "Umhang des FungustalsRaynes SchalSchulterstücke der blühenden HoffnungAuf Euch wartet eine dieser Belohnungen:\n\nRing des neuen Lebens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27422] = {title = "Eine Stadt unter Belagerung", objective = "Sprecht mit Rottenkommandant Steinberster.", description = "Wir werden die Östlichen Pestländer nie unter Kontrolle bekommen, wenn wir Stratholme nicht im Besitz haben. Stratholme ist nicht nur ein strategisch unglaublich wichtiger Ort, sondern auch die Heimat der Anführer unserer Feinde - Balnazzar und Baron Aurius Totenschwur. Ihre Armeen der Auferstandenen und der Geißel drohen jedoch, alle unsere Fortschritte nichtig zu machen.\n\nDer Argentumkreuzzug ist wie geschaffen, sich dieser Aufgabe anzunehmen. Reist nach Westen, betretet Stratholme durch das Haupttor, und sprecht mit Rottenkommandant Steinberster. Er wird Euch weitere Anweisungen geben.", progress = nil, completion = "Welch eine Erleichterung einen tauglichen Soldaten an unserer Seite zu haben. Hier gibt es genug für Euch zu tun, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27423] = {title = "Widerstand ist zwecklos", objective = "Tötet 20 Kämpfer der Worgen.", description = "<Das K.d.V. summt.>\n\nHier spricht Kommandantin Lorna Crowley von der Gilnearischen Befreiungsfront. Wenn Ihr diese Nachricht hört, bedeutet das, dass die Allianz Gilneas wieder eingenommen hat. Legt Eure Waffen nieder und kapituliert. Wenn Ihr dieser Aufforderung nicht nachkommt, steht Euch der sichere Tod bevor.\n\nUnsere Streitmächte sind über Euren Standort informiert und werden in Kürze eintreffen. Widerstand ist zwecklos.", progress = nil, completion = "Wir haben keine Zeit, um uns am Ruhm der Schlacht zu laben, &lt;Name&gt;. Es gibt Arbeit. Ich bin mir sicher, dass noch mehr von diesen Biestern unterwegs sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27424] = {title = "Oberanführer Mok'Morokks Sorgen", objective = "Holt Oberanführer Mok'Morokks Grog, Mok'Morokks Schnupftabak und Mok'Morokks Geldkassette aus Düstermarschen.", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Steinbrecherklan!\n\nIch guter Anführer. Ich auf Klan aufpasse.\n\nGroße Drachen machen Feuer in alte Heimat. Ich schlauer Oger. Finden neue Heimat für Klan hier.\n\nAber alte Heimat so schnell verlassen, ich Sachen vergessen. Winzig <Volk>, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, Schnupftabak und Geldkassette. Ich Euch dann mögen. Ihr in Flammenbau und Ruinen der Steinbrecher schauen ... alles dort sein, ich sicher!", progress = "Ich Durst auf Grog. Und Lust auf Schnupftabak. Wo ist Geldkassette? Ihr geht holen für Oberanführer Mok'Morokk.\n\nGeht holen in Süden in alter Heimat. Ich mit Anführen von Ogern beschäftigt.", completion = "Gut, &lt;Volk&gt;. Ich haben Sachen arg vermisst. Ich Euch jetzt mag.", rewards = "SteinbrecherhandschuheAuf Euch wartet eine dieser Belohnungen:\n\nMok'Morokks Grogflasche\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27425] = {title = "Der entscheidende Grimmweis", objective = "Berichtet Hauptmann Darill in Nordwacht.", description = "Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses \"Zur Süßen Ruh\" gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.\n\nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen bloßen Zufall. Ich bitte Euch, mit Hauptmann Darill zu sprechen. Er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf in Richtung Norden nach Nordwacht. Es ist der zweite Außenposten entlang der Straße.", progress = nil, completion = "Hauptmann Mumm meint, die Grimmtotem stecken hinter dem Angriff auf das Gasthaus \"Zur Süßen Ruh\"? Auf meiner Verdächtigenliste wären sie jetzt nicht weit oben, aber wenn Hauptmann Mumm Euch schickt, um einem Hinweis zu folgen, hat er sicherlich gute Gründe. Davon aber abgesehen, die Grimmtotem sind uns schon seit einiger Zeit ein Dorn im Auge und wir sind immer über zusätzliche Hilfe dankbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27426] = {title = "Bestätigung des Verdachts", objective = "Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem zu sehen.", description = "Die Grimmtotem mögen der kriegerischste Klan der Tauren sein, aber sie sind keineswegs unorganisiert. Wenn sie das Gasthaus \"Zur Süßen Ruh\" wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.\n\nNordwestlich von hier liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben das Dorf als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, aber ich bin mir ganz sicher, dass Ihr dort auch die Befehle finden könnt. Sucht bei den Ältesten im Dorf nach den Befehlen, die Ihr für Eure Ermittlungen benötigt.", progress = "Konntet Ihr die Befehle ausfindig machen?", completion = "&lt;Hauptmann Darill überfliegt die Schlachtpläne.&gt;\n\nIch glaube, deutlicher kann es kaum werden. Sie haben es sich zur Aufgabe gemacht, die Menschen aus den Siedlungen in der Gegend zu vertreiben. Ich bezweifle nicht, dass Theramore ihr nächstes Ziel sein wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27427] = {title = "Waffen der Grimmtotem", objective = "Hauptmann Darill in Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager nordwestlich von hier.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen, aber ausgehend von der Größe ihrer Angriffstrupps schätzen wir, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", progress = "Habt Ihr diese Waffen aus dem Dorf der Schwarzhufe?", completion = "&lt;Hauptmann Darill betrachtet die Waffen, die Ihr aus dem Dorf der Schwarzhufe mitgebracht habt.&gt;\n\nEs gibt keine Zweifel mehr. Diese Waffen stimmen genau mit der Beschreibung überein. Es gibt nur ein Problem - mit diesen Waffen wurde noch nie gekämpft. Das Dorf der Schwarzhufe ist wohl nicht der einzige Posten der Grimmtotem in den Marschen.", rewards = "KnochenlangdolchBeißende GroßaxtAuf Euch wartet eine dieser Belohnungen:\n\nGlühender Turmalinring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27428] = {title = "Tabethas Unterstützung", objective = "Sprecht mit Tabetha auf ihrem Hof.", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich kenne aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, südlich von hier, liegt ein kleiner Hof, der Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und recht angesehene Wahrsagerin. Folgt der Straße in Richtung Süden bis zu ihrem Hof und bittet sie um Hilfe bei der Suche nach den Übeltätern, die für das Massaker beim Gasthaus \"Zur Süßen Ruh\" verantwortlich sind.", progress = nil, completion = "Ihr möchtet also, dass ich die Grimmtotem durch meine Weissagungen ausfindig mache, ja? Was würdet Ihr sagen, wenn ich Euch verrate, dass es keinerlei Weissagung dafür bedarf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27429] = {title = "Brennt den Grollhornposten nieder!", objective = "Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totem förmlich angekündigt.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Ich hoffe, die Grimmtotem haben unsere Nachricht verstanden. Jeder Rückkehrversuch wird mit schlimmeren Mitteln als einer Fackel beantwortet werden. Meine Lehrlinge und ich werden uns der Sache annehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27430] = {title = "Gerechtigkeit im Namen der Familie Hyal", objective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", description = "Für mich waren die Grimmtotem zwar lediglich eine Belästigung, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um die Familie von Jim Hyal zu retten, aber vielleicht denken die Grimmtotem das nächste Mal zweimal nach, bevor sie jemanden aus Theramore angreifen.", progress = nil, completion = "&lt;Der Hauptmann hört sich Euren Bericht sorgfältig an.&gt;\n\nWir haben James und seine Familie zwar gerächt, aber nicht einmal das kann wieder gut machen, was zerstört wurde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27431] = {title = "Aus dem Gleichgewicht gebracht", objective = "Sprecht mit Harrison Jones in der Kammer der Sterne.", description = "<Harrison grinst.>\n\nDas ist es, <Name>. Die Teile, die wir brauchen, sind in diesen Statuen versteckt!\n\nSie sehen aus, als wären sie sowieso ein wenig aus dem Gleichgewicht... Ein kleiner Stupser vielleicht...\n\nEure Untersuchungen schreiten ordentlich voran, muss ich sagen. Wenn Ihr Euch bewerben würdet, könnte aus Euch eines Tages <ein feiner Archäologe/eine feine Archäologin> werden.", progress = "Was habt Ihr gefunden, <Name>?", completion = "Wo wir gerade bei \"Häuser einreißen\" sind...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27432] = {title = "Zaeldarr der Ausgestoßene", objective = "Besorgt Zaeldarrs Kopf von Zaeldarr dem Ausgestoßenen.", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.\n\nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen von unseren Friedhöfen. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Südwesten.\n\nGeht dorthin und schaltet Zaeldarr aus, <Name>. Ich habe seine Schandtaten satt!", progress = "Habt Ihr das Versteck gefunden, <Name>? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27433] = {title = "Schredderektomie", objective = "Zerstört Diamantenklingenschredder, um 5 misshandelte Schredderteile zu erlangen.", description = "Unsere Panzer müssen zurückgezogen werden, und das bedeutet, dass wir Arbeiten auf dem Schlachtfeld verrichten müssen.\n\nZerstört ein paar von den Diamantklingenschreddern, die diese kleinen Monster benutzen, um die Bäume an der Küste zu fällen, und bringt mir einen Haufen der Schredderteile, die noch verwendbar sind. Wir basteln damit etwas, um die Panzer wieder einsatzbereit zu machen.", progress = "Was habt Ihr für mich, <Name>?", completion = "Oha, das ist gutes Zeug! Ein guter Ingenieur kann alles machen, wenn er nur ein paar gute Sachen hat.\n\nDieses Dingens hier könnte an eine kaputte Zylinderhülse gekoppelt werden ... Oh! Und wer freut sich nicht über ein solches Dingsbums? ... Und aus diesem Gedöhns hier kann man auf jeden Fall ein ... Ding machen!\n\n&lt;Flintlocke steckt eines der schmierigen Maschinenteile in den Mund.&gt;\n\nJupp, perfekt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27434] = {title = "Der Pfad der Adepten", objective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.", description = "Eure Lehrlingszeit neigt sich dem Ende zu, <Name>. Ihr seid bereit, den Rang Adept innezuhalten und ein richtiger Blutritter im Dienste Silbermonds zu werden.\n\nUm Eure Leistungen zu ehren, hat der Kriegshäuptling bei seinem Schmied die Herstellung einer Waffe für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke dort.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich weiß nicht, wie Ihr solche Mengen Mondstahl auftreiben konntet, &lt;Name&gt;. Ich habe schon seit Jahren nicht mehr damit gearbeitet. Es wird sowohl eine Herausforderung als auch eine Freude sein, diese Waffe für Euch zu schmieden.", rewards = "Morgenstern des OrdensKampfstreitkolben des OrdensGroßstreitkolben des OrdensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27435] = {title = "Der Stab eines Sehers", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "In den Augen der Erdmutter seid Ihr bereit, den Rang des Sehers zu erlangen. Ihr habt Eure Grundausbildung mit Können und Hingabe absolviert.\n\nZu diesem Anlass hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab der Erdenmutter"}
MultiLanguageQuestData['de'][27436] = {title = "Die Aufgabe des Schattenläufers", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Dies ist ein besonderer Anlass, <Name>. Ihr habt viel gelernt und seid an der Macht gewachsen. Im Stamm der Dunkelspeere und in der Horde steht Euch eine großartige Zukunft bevor.\n\nIch habe den Verzauberkunstmeister des Kriegshäuptlings gebeten, einen Stab zu erstellen, um Eure Leistungen anzuerkennen.\n\nUm die dafür benötigten Materialien zu erlangen, müsst Ihr zur verfluchten Burg Schattenfang im Silberwald reisen. Findet das heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz, und die Essenzen der Geister, die die Burg heimsuchen, und bringt alles zu Godan.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab des Schattenwandlers"}
MultiLanguageQuestData['de'][27437] = {title = "Die Aufforderung des dunklen Klerikers", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Ihr habt gewissenhaft gelernt und uns gedient. Wenn Ihr Eure Talente übereinstimmend mit den Wünschen von Fürstin Sylvanas benutzt, wird Euch der Schatten segnen.\n\nUnsere Königin hat beim Verzauberkunstmeister von Orgrimmar die Herstellung eines mächtigen Stabes zur Anerkennung Eurer Dienste in Auftrag gegeben.\n\nDie Materialien, die dafür benötigt werden, sind nur in Burg Schattenfang inmitten von Silberwald zu bekommen. Findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab des abgelegten Glaubens"}
MultiLanguageQuestData['de'][27438] = {title = "Die große Flucht", objective = "Flieht aus den Ruinen von Gilneas mit Arthura und der Leiche von Lord Godfrey.", description = "Das Ziel unserer Mission ist erfüllt. Nun können wir unsere Flucht planen. Obwohl wir Gilneas verloren haben, werden wir es mit der Hilfe von Godfrey und seinen Leutnants schnell wieder zurückerobern können.\n\nGeht nun, <Name>. Fliegt mit Arthura zurück zur Frontlinie der Verlassenen im Süden von Silberwald. Die Bansheekönigin erwartet Eure Ankunft.", progress = nil, completion = "Ich hatte keinerlei Zweifel, dass es Euch gelingen würde, &lt;Name&gt;. Ich hoffe Ihr könnt verstehen, warum ich den eigentlichen Grund Eurer Mission geheim gehalten habe. Falls Crowley und Blutfang von unserem Plan Wind bekommen hätten, hätten sie Godfrey sicher vor uns ausfindig gemacht und seine Leiche verschwinden lassen. Bleibt weiterhin verfügbar, &lt;Name&gt;.\n\nDie Zeit der Wiedergeburt unseres Landes ist gekommen.", rewards = "Umhang mit geheimem VerwendungszweckGodfreys GürtelTreter des wahren PlanesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27439] = {title = "Stab des Lichts", objective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Ihr seid durch Euer Talent schnell zu einem guten Diener des Lichts und Silbermonds geworden, <Name>. Eure Loyalität gegenüber unserem Volk und der Horde sind beispielhaft.\n\nIn Anerkennung Eurer Hingabe hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab des Sonnenjägers"}
MultiLanguageQuestData['de'][27440] = {title = "Trolls, Oger und Orcs, oh weh!", objective = "Tötet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak.", description = "Dem großen Schwarzdrachen Oberanführer Wyrmthalak unterstehen die Streitmächte der unteren Schwarzfelsspitze, die schon bald bereit für ihren Angriff auf die Dunkeleisenzwerge sein werden. Wir können nicht zulassen, dass die schwarzen Großdrachen die Kontrolle über den Berg erlangen!\n\nIhr müsst Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak töten. Ihre Tode werden den Kampfgeist der Armee beeinträchtigen und uns so wertvolle Zeit verschaffen.", progress = nil, completion = "Es tut mir leid, wenn ich das so sage, aber ich bin erstaunt, dass Ihr diese Aufgabe lebendig abschließen konntet. Diese Monster waren für die Tode Tausender verantwortlich, darunter viele Helden, von denen bis zum heutigen Tag noch gut gesprochen wird.\n\nIhr habt Euch meinen Respekt verdient und sollt eine Belohnung für Euren Mut erhalten.", rewards = "Brustharnisch des HochlordsOberanführerbeinschützerSchulterstücke des KriegsmeistersAuf Euch wartet eine dieser Belohnungen:\n\nBand der Spitze\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27441] = {title = "Der Stab eines Sehers", objective = "Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", description = "Man sagt, dass sogar der Kriegshäuptling von Euren Taten für die Horde erfahren hat. Bestimmt wird er jetzt erkennen, dass er uns falsch eingeschätzt hat.\n\nEr hat sich bereiterklärt, dem Verzauberkunstmeister von Orgrimmar zu gestatten, einen Stab für Euch zu fertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStab der goldenen Verehrung"}
MultiLanguageQuestData['de'][27442] = {title = "Der Krieg hat viele Fronten", objective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", description = "Jetzt sieht unsere Lage dem Feind in Vashj'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.", progress = nil, completion = "Eure Hilfe kommt genau zur rechten Zeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27443] = {title = "Der Krieg hat viele Fronten", objective = "Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.", description = "Jetzt sieht unsere Lage dem Feind in Vashj'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.", progress = nil, completion = "Eure Hilfe kommt genau zur rechten Zeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27444] = {title = "Der falsche Kriegshäuptling", objective = "Tötet Kriegshäuptling Rend Schwarzfaust.", description = "Rend Schwarzfaust war der Sohn eines Kriegshäuptlings der Orcs. Sein Vater wurde von Orgrim Schicksalshammer umgebracht, der daraufhin zum neuen Kriegshäuptling anstelle des jungen Rends wurde. Rend hat sich nun zum Anführer der Schwarzfelsorcs emporgeschwungen, einer Möchtegern\"horde\", und wird dabei von Nefarian und seiner Drachenarmee unterstützt.\n\nRend, der Narr, behauptet auch, dass er das Geburtsrecht auf die Horde innehält, und droht, dieses Recht mit Gewalt geltend zu machen. Wir können nicht zulassen, dass dies unter dem Einfluss seines Meisters geschieht. Findet ihn in der oberen Schwarzfelsspitze und bringt diesen falschen Kriegshäuptling zu Fall, <Volk>.", progress = "Rend wird nicht ohne Kampf gestürzt werden können.", completion = "Habt Ihr Nefarian gesehen, als Ihr mit Rend gekämpft habt?\n\n&lt;Acride seufzt.&gt;\n\nIch wünschte, ich hätte Euch begleitet. Ich hätte ihm gegenübertreten können, als er nicht damit gerechnet hat, außerhalb seines Horts. Nun, das ist egal. Nefarian wird unter meiner Klaue sterben.\n\nIhr habt gute Arbeit geleistet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27445] = {title = "General Drakkisath, Nefarians rechte Hand", objective = "Tötet General Drakkisath.", description = "Nefarian weitet seinen Herrschaftsbereich weiter oben im Pechschwingenhort aus. Obwohl man dort von der oberen Schwarzfelsspitze aus hinkommt, könnten wir dort mit weitaus mehr Streitmächten einfallen, wenn wir die Kugel der Teleportation in der Nähe benutzen. Wir können uns erst teleportieren, wenn wir durch eine andere Kugel gekennzeichnet sind.\n\nDie zweite Kugel wird von Drakkisath, dem General von Nefarians Armee, persönlich bewacht. Schaltet ihn aus und sichert die zweite Kugel, damit wir sie nutzen können. Ihr werdet ihn im Spitzenthron in der oberen Schwarzfelsspitze finden.", progress = nil, completion = "Hervorragend! Es ist nur eine Frage der Zeit, bevor der Sohn von Todesschwinge meine Klauen zu spüren bekommt.", rewards = "Stab der zweiten KugelVaelans KlaueSchwert von Nefarians HandAylas StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27446] = {title = "Tanaris ruft", objective = "Sprecht mit Kelsey Stahlfunken in Gadgetzan in Tanaris.", description = "Hey, <Name>! Kelsey Stahlfunken aus Tanaris hat eine Nachricht für Euch gebracht. Sie meint, die Gnome dort in Gadgetzan hätten von Euren Leistungen gehört.\n\nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.", progress = nil, completion = "Seid gegrüßt, mein Freund. Willkommen in Tanaris!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27447] = {title = "Tanaris ruft", objective = "Sprecht mit Megs Schredderschreck in Gadgetzan in Tanaris.", description = "Hey, <Name>! Megs Schredderschreck aus Tanaris hat eine Nachricht für Euch hinterlassen. Sie sagt, die Goblins dort in Gadgetzan haben von Euren Leistungen gehört.\n\nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.\n\nAußerdem sieht diese Megs verdammt gut aus!", progress = nil, completion = "Aber hallo, &lt;Klasse&gt;. Willkommen in Tanaris!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27448] = {title = "Die Reise geht weiter", objective = "Steigt auf Fionas Karawanenwagen, wenn Ihr bereit seid, um zum nächsten Turm aufzubrechen.", description = "Ich glaube, die Pferde sind startklar. Argus Leuchtfeuer, der Herr, der mit dem Argentumkreuzzug zusammenarbeitet, hat sich vorhin mit mir unterhalten. Wie ich höre, wird er uns wohl begleiten - großartig! Ich werde Platz für ihn machen.\n\nIch weiß, dass Ihr beschäftigt seid, also nur keine Hektik. Sobald Ihr soweit seid, springt einfach auf den Karawanenwagen auf und wir machen uns auf den Weg zum nächsten Turm.", progress = "Sobald wir am Lichtschildturm eintreffen, können sich die Jungs auf den Weg zur Kapelle des Hoffnungsvollen Lichts machen. Diese kurze Strecke können sie laufen.", completion = "Es war sehr angenehm, mit Euch zu reisen, &lt;Name&gt;. Hoffentlich können wir unsere Reise gemeinsam fortsetzen, sobald Gidwin und Tarenar dem Argentumkreuzzug beigetreten sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27449] = {title = "Ehre und Stärke", objective = "Besteht Vex'tuls Stärketest.", description = "Mein Name lautet Vex'tul und ich habe Euch im Kampf beobachtet, <Volk>. Ihr seid stark.\n\nIhr habt meinen Meister Zaeldarr getötet, aber das stört mich nicht. Stärke ist mir wichtiger als die Loyalität, die ich ihm gegenüber empfand. Stärke ist mir wichtiger als alles andere.\n\nBeweist mir Eure Stärke ein letztes Mal, <Volk>. Wenn Ihr sie beweisen könnt, werde ich Euch MEINE Stärke leihen und Ihr werdet sie für all die Zwecke einsetzen können, die Euch vorschweben.", progress = nil, completion = "Ja, Ihr seid in der Tat stark ... ich unterwerfe mich Euch.\n\nIch werde Euch und Eure Freundin, den Worgen, begleiten. Meine Stärke ist Eure.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27450] = {title = "Fredericks Vorliebe für Fisch", objective = "Erhaltet 8 Pestkugelfische, 8 Infektkriecher und 8 Infektkrabbler aus der Infektnarbe.", description = "Ich liebe das Meer. Ich, Frederick Calston, war es, der die Meeresbewohner in den See im Südwesten gebracht hat. Ich hatte gehofft, den Kreuzzug so mit frischer Nahrung direkt aus den Pestländern versorgen zu können.\n\nAllerdings haben sich einige als Raubfische herausgestellt und jetzt versetzen sie alle anderen Tiere in Angst und Schrecken. Wenn wir nicht aufpassen, werden sie alle töten!\n\nSchwimmt zum Boden des Sees und rettet ein paar der Schnecken, Krabben und Kugelfische, bevor es zu spät ist.", progress = "Habt... habt Ihr die Fische besorgt?", completion = "Hmm ... sie haben den Ausflug an Land nicht so gut überstanden, wie ich gehofft hatte.\n\nNun gut. Dann gibt es für Frederick heute Abend Meeresfrüchtesalat!", rewards = "InfektkriechergamaschenHandschuhe des InfektkugelfischesInfektkrabblerhelmIhr bekommt:\n\nInfektkugelfischsashimi"}
MultiLanguageQuestData['de'][27451] = {title = "Töten zu einem bestimmten Zweck", objective = "Reist zu Corins Kreuzung im Süden und tötet die Geißelsoldaten, die dort hausen. Sammelt 7 Stück lebendige Fäulnis. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", description = "Seid gegrüßt, Fremdling! Ihr seid im Herzen der Pestländer angelangt. Ich hoffe, Ihr habt Eure Untote-Töten-Ausrüstung dabei.\n\nDieser Tage verbreitet sich die Seuche immer langsamer und daher hat der Kult der Verdammten die Herstellung hochgeschraubt, damit das Land braun und tot bleibt, so, wie es ihnen am liebsten ist. Ich habe einen Plan, sie aufzuhalten. Nehmt meinen Mörser und den Stößel; zerstoßt damit die lebendige Fäulnis der untoten Kreaturen in Corins Kreuzung südöstlich von hier. Wir werden für diese Kultisten ein kleines Geschenk vorbereiten.", progress = "Wie steht es an Corins Kreuzung?", completion = "Hallo! Ich bin's. Ich hoffe, Ihr habt nichts gegen ein wenig selbstgebraute Zauberkunst, damit ich während dieser Aufgabe mit Euch in Verbindung bleiben kann. So können wir beide Zeit sparen.\n\nWir werden diese lebendige Fäulnis in eine Mixtur einarbeiten, die die komplette Produktion der kommenden Seuche ruinieren wird. Das wird sie eine Lektion lehren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27452] = {title = "Dunkle Gewänder", objective = "Erhaltet die Kopfbedeckung eines Todeskultisten und die Roben eines Todeskultisten von Kultisten in Corins Kreuzung.", description = "Einige meiner Mitstreiter haben berichtet, dass das Land heilen möchte. Allerdings lassen das viele hochrangige Untote - und auch der Kult der Verdammten - nicht zu. Das bedeutet, dass wir sie aufhalten müssen! Ich habe einen Plan, aber zuerst brauche ich eine Kultistenverkleidung.\n\nBegebt Euch nach Südosten, zu Corins Kreuzung und nehmt einem der menschlichen Kultisten die Gewänder ab. Ihr werdet sie durch den Ort streifen sehen. Ich werde mich mit Euch in Verbindung setzen, wenn Ihr das Gewand erhalten habt.", progress = "Soweit alles in Ordnung, <Name>?", completion = "Ihr habt beide Teile! Gut. Sie werden mir dabei helfen, mich in ihr Todeslager zu schleichen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27453] = {title = "Katalysmus", objective = "Verwendet Betinas Fläschchen gegen lebende Elementare im Mereldarsee, um 8 flüssige Seuchenwirkstoffe zu erhalten.", description = "Geronnene Fäulnis ist allein schon sehr wirksam, aber wir brauchen etwas, um die versteckten Kräfte hervorzurufen ... einen Katalysator. Ein guter Katalysator findet sich südlich von hier, im Mereldarsee.\n\nWenn Ihr in Eure Taschen seht, werdet Ihr bemerken, dass ich ein paar Fläschchen hineingeschmuggelt habe, als Ihr nicht aufgepasst habt. Benutzt diese Fläschchen bei den Wasserelementaren im See. Das lebende, verderbte Wasser, aus dem ihre Körper bestehen, wird einen perfekten Katalysator abgeben!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27454] = {title = "Nur ein Tropfen im Eimer", objective = "Benutzt Eure Todeskultistenverkleidung, um das Basislager der Todeskultisten zu betreten und fügt Betinas Mischung dem Mereldar Seuchenkessel zu.", description = "Gebt nun eine kleine Menge Fäulnis zum Wasser und gut verrühren. So, das war es schon. Diese Lösung wird sehr aggressiv sein und wir brauchen nur ganz wenig davon.\n\nAm südöstlichen Ufer des Sees befindet sich ein Seuchenkessel, in dessen Nähe sich mehrere Kultisten aufhalten. Tragt die Kultistenverkleidung, geht zum Kessel und fügt nur EINEN TROPFEN dieser Lösung hinzu. Wenn Ihr mehr in den Kessel schüttet, ist Euer Leben in großer Gefahr!", progress = nil, completion = "Es sollte Wochen dauern, bis sie ihr Vorhaben wieder in die Tat umsetzen können. Ich danke Euch, &lt;Name&gt;.", rewards = "SeuchenheilungswerferBrustplatte des TropfensSchild des LichtsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27455] = {title = "Jungs bleiben Jungs", objective = "Findet Gidwin Goldzopf vor der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Direkt nach unserer Ankunft hier am Lichtschildturm sind die beiden Paladinschwachköpfe zur Kapelle des Hoffnungsvollen Lichts davongerannt. Sie ist noch recht weit entfernt, aber wenn wir Argus auf seiner Turmrundreise folgen wollen, dann ist das hier wohl noch am nächsten.\n\nSchaut einmal nach ihnen und stellt sicher, dass es ihnen gut geht. Ich weiß, dass sie auf sich selbst aufpassen können, aber dennoch... Mir wäre wohler, wenn ich wüsste, dass Ihr über sie wacht, während ich hier mit dem Wagen festsitze.", progress = nil, completion = "Ich kann es kaum glauben. Wir stehen SO kurz davor, ordentliche Mitglieder des Argentumkreuzzugs zu werden.\n\nWir wären bereits aufgenommen, wenn Tarenar nicht so herumtrödeln würde. Wenn er nicht bald aufhört, mit den Einwohnern zu schwatzen, werde ich alleine dort hineingehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27456] = {title = "Nicht auf leeren Maden", objective = "Sucht in der Umgebung nach Aaslarven und Aasverschlingern. Tötet sie und bringt 15 Scheiben Aaswurmfleisch an Euch.", description = "Wir haben Schwierigkeiten, unsere Nahrungsvorräte hier im tiefen Osten aufrechtzuerhalten.\n\nIn dieser Gegend gibt es nur eine Tierart, die nicht von der Seuche beeinträchtigt wird und das sind Aaswürmer. Sie schmecken zwar nach nichts, aber das Fleisch dieser Würmer kann über Monate hinweg aufbewahrt werden. Wir benötigen einige hundert Pfund, damit wir wieder ausreichend versorgt sind.\n\nMan findet Aaswürmer überall in den Pestländern, aber besonders häufig kommen sie südlich der Kapelle vor. Und denkt daran: Große Würmer liefern mehr Fleisch.", progress = "Ihr werdet Euch an den Geschmack gewöhnen, <Volk>. Ging mir auch so.", completion = "Möge die Erdenmutter über Euch wachen. Seid gesegnet, Jüngling.", rewards = "Rimblats UmhangBeinschützer des WurmausweidersDreckiges GewehrAuf Euch wartet eine dieser Belohnungen:\n\nMagen des Verschlingers\n\nIhr bekommt außerdem:\n\n\"Köstliches\" Wurmsteak"}
MultiLanguageQuestData['de'][27457] = {title = "Eine Gelegenheitsallianz", objective = "Meldet Euch bei Fiona am Ostwallturm in den Östlichen Pestländern.", description = "Durch Euren Beitrag zu den Nahrungslagern ist meine Aufgabe erledigt.\n\nIch werde mich als Nächstes nach Norden in den Pestwald begeben. Wie ich höre, geht Ihr in die gleiche Richtung?\n\nWürde es Euch etwas ausmachen, wenn ich mich Euch anschließe? \n\nIch bin unterwegs nach Nordwesten zum Ostwallturm. Wenn Ihr Interesse an einem Zusammenschluss habt, könnt Ihr mich dort treffen.", progress = nil, completion = "Ihr habt einen Schamanen mitgebracht! Und dann auch noch vom Irdenen Ring!\n\nIch habe keine Ahnung, wie er in dem Wagen Platz finden soll, aber uns wird etwas einfallen. Willkommen an Bord, Rimblat Erdspalter!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27458] = {title = "Smokey und der Verband", objective = "Besorgt Braumanns Wickel von Stephan Braumann in Braumanns Mühle.", description = "He, Ihr da! Interesse, leichtes Geld zu verdienen?\n\nIch muss an eine Bandage kommen. Also, um ehrlich zu sein, hab ich einen Freund, der an eine Bandage kommen muss. Also, um ehrlich zu sein... sagen wir einfach, es ist zu kompliziert, aber wenn Ihr diese Bandage holt, bekommt Ihr Geld. Genau wie ich. Und mein Freund. Möglicherweise auch andere Leute.\n\nDie Mühle im Norden gehörte früher einmal Stephan Braumann, aber jetzt ist er tot. Ein Zombie. Der Kerl ganz oben möchte die Wickel von Braumanns Körper.\n\nWas ist los - mögt Ihr kein Geld?", progress = "Ihr habt gegen Untote gekämpft. Habt Ihr Braumann gefunden?", completion = "Kaum zu glauben! Jemand, der losgeht und Dinge tatsächlich erledigt! Hier ist Euer Anteil, Chef. Wir seh'n uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27459] = {title = "Die Bruderschaft des Lichts", objective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", description = "Die Bruderschaft des Lichts ist für ihre unbesonnenen und gedankenlosen Entscheidungen bekannt. Sie haben eine Brücke zwischen dem Scharlachroten Kreuzzug und der Argentumdämmerung geschlagen. Sie waren unter den ersten, die sich in Nordend in den Kampf warfen, während wir anderen noch zögerten.\n\nDeshalb sind sie auch für ihre Ergebnisse bekannt und das respektiere ich. Jetzt kämpfen sie an zwei Fronten: Eine Schlacht in Stratholme und die andere - viel drängendere - Schlacht im Süden bei Tyrs Hand.\n\nIch schlage vor, Ihr sprecht mit Angela Dosantos in Tyrs Hand. Vielleicht hat sie Verwendung für Euch.", progress = nil, completion = "Ein &lt;Klasse&gt;! Genau das, was wir brauchen. Eure Ankunft hätte nicht zu einem besseren Zeitpunkt erfolgen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27460] = {title = "Sanfte Landung", objective = "Tötet 10 beliebige Anhänger des Scharlachroten Kreuzzugs in Tyrs Hand.", description = "Man hat uns nur einhundert Männer überlassen, um diese Mission zu erfüllen, und einer fehlt uns bereits. Unser Späher wurde in die Feste des Feindes entsandt, um einige Wachen auszuschalten, die in der Gegend patrouillieren. Außerdem sollte er ein Leuchtfeuer entfachen, damit wir einen koordinierten Angriff durchführen können. Unsere neunundneunzig verbliebenen Männer sind bereit und warten auf das Leuchtfeuer. <Ein talentierter/Eine talentierte:c> <Klasse> wie Ihr muss sich nach Tyrs Hand schleichen, so viele Wachen wie möglich ausschalten und das Leuchtfeuer entfachen.\n\nFühlt Ihr Euch dem gewachsen?", progress = nil, completion = "Das Leuchtfeuer ist aufgetürmt und die Streichhölzer liegen unbenutzt neben der Zündschnur.\n\nDer gefallene Argentumzenturio war näher dran, das Leuchtfeuer zu entzünden, als Ihr vermutet hattet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Player)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27461] = {title = "Die Abtei einnehmen", objective = "Meldet Euch bei Kommandant Eligor Morgenbringer außerhalb der Abtei in Tyrs Hand in den Östlichen Pestländern.", description = "Der Scharlachrote Kreuzzug unterhält eine gut befestigte Abtei im unteren westlichen Teil von Tyrs Hand. Zunächst muss die Abtei gesichert werden, bevor man sich weiter in die Festung vorwagen kann.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Kann ich darauf vertrauen, dass Ihr mir helfen werdet, die Abtei diesen Monstrositäten zu entreißen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27462] = {title = "Die Kaserne einnehmen", objective = "Meldet Euch bei Kreuzzugskommandant Korfax vor der Kaserne in Tyrs Hand in den Östlichen Pestländern.", description = "Eines der Schlüsselgebäude in Tyrs Hand ist die Kaserne, die sich ganz in der Nähe dieses Leuchtfeuers befindet. Die Bruderschaft des Lichts und ihre Zenturionen werden alle verfügbare Hilfe benötigen, um sie zu erobern.", progress = nil, completion = "Ich werde ab jetzt die Leitung hier übernehmen, &lt;Klasse&gt;.\n\nAlso gut, Ihr wollt eine Aufgabe? Ich denke, ich kann es mir leisten, Euch auf die ein oder andere Mission zu schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27463] = {title = "Ein Kindheitstraum", objective = "Sprecht mit Lord Maxwell Tyrosus in der Kapelle des Hoffnungsvollen Lichts.", description = "Ich wollte mich schon immer dem Kreuzzug anschließen. Deshalb bin ich Paladin geworden. Jahrelange Übung und Verbesserung meiner Fertigkeiten. Endlich bin ich bereit.\n\nTarenar glaubt ebenfalls, dass er bereit ist, aber da bin ich mir nicht so sicher. Er ist ein Angeber und hat seine Lektionen nie ernstgenommen. Dennoch - wir haben versprochen, dass wir das hier zusammen machen und hier stehen wir nun.\n\nSollen wir uns in die Kapelle begeben?", progress = nil, completion = "Willkommen in der Kapelle des Hoffnungsvollen Lichts.\n\nIhr wünscht, Euch dem Kreuzzug anzuschließen? Na schön. Wir haben ausreichend Aufgaben für neue Rekruten.\n\nAber zunächst ein Test...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27464] = {title = "Argentumruf: Die Prüfung der Gruft", objective = "Betretet die Gruft hinter der Kapelle des Hoffnungsvollen Lichts, lest aus der Argentumschriftrolle und schließt die Prüfung ab.", description = "Hinter unserer Kapelle findet Ihr eine kleine Gruft. Darin sind die Leichen unserer gefallenen Helden bestattet, die ihr Leben im Krieg gegen die Geißel verloren haben.\n\nIhre Seelen ruhen friedlich. Dennoch kehren sie hin und wieder zurück, um neue Mitglieder des Ordens zu prüfen.\n\nIhr drei dürft die Prüfung zusammen absolvieren. Betretet die Gruft und lest dann diese Schriftrolle. Lord Raymond George - mein Vorgänger - wird den Vorsitz bei Eurer Prüfung übernehmen.", progress = "Eure Prüfung ist noch nicht abgeschlossen.", completion = "Denkt daran, dass Eure Vorfahren stets über Euch wachen. Als Bruder des Argentumkreuzzugs werdet Ihr Teil einer Familie, die auf eine lange Reihe solcher Vorfahren zurückblickt. Ihre Wachsamkeit und Ihr Schutz werden Eure Stärke sein, wenn Ihr Euch gegen die Geißel stemmt.\n\nMeine Glückwünsche, Tarenar, Gidwin und &lt;Name&gt;. Willkommen beim Argentumkreuzzug.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTrial of the Crypt: Set Argent Dawn Faction To Min Revered\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27465] = {title = "Argentumruf: Das Giftige Tal", objective = "Tötet 16 Angehörige der Geißel und 8 Kultisten in Braumanns Mühle und dem Giftigen Tal. Kehrt zur Kapelle des Hoffnungsvollen Lichts zurück, wenn Tarenar oder Gidwin getötet werden.", description = "Braumanns Mühle im Norden wimmelt nur so von Untoten. Das Giftige Tal, noch weiter nördlich, ist noch schlimmer befallen. Trotz der Nähe zu unserer Kapelle sind wir nicht in der Lage gewesen, sie zu entfernen.\n\nWachsamkeit ist der Schlüssel. Reist in das Giftige Tal und tötet so viele Untote, wie Ihr finden könnt, sowie die Kultisten, die sich darunter befinden.\n\nWährend Ihr dort seid, weicht Garginox dem Fleischriesen aus, der durch das Tal wandelt. Ich vermute, dass Ihr nicht stark genug seid, um ihn zu besiegen.", progress = nil, completion = "Ihr seid früher als erwartet zurückgekehrt. Ausgezeichnet.\n\nWir werden unseren Weg in den Norden fortsetzen. Als nächstes werdet Ihr eine ähnliche Aufgabe erfüllen, diesmal in Nordtal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27466] = {title = "Argentumruf: Nordtal", objective = "Sprecht mit Fiona am Ostwallturm in den Östlichen Pestländern.", description = "Tyrosus hat uns unsere nächste Aufgabe gestellt: weitere Untote in Nordtal vernichten. Gidwin freut sich darauf, weiterzuziehen, aber ich glaube, wir sollten etwas vorsichtiger sein.\n\nLasst uns Fiona aufsuchen. Sie sollte jetzt den nächsten Turm erreicht haben... Ich glaube, er heißt Ostwallturm. Er ist in der Nähe, nordwestlich der Kapelle. Dort können wir uns ausruhen und unseren Angriff auf Nordtal planen.", progress = nil, completion = "Hallo, &lt;Name&gt;! Es freut mich, dass Ihr Euch uns wieder angeschlossen habt.\n\nTarenar und Gidwin sind bereits vor Euch eingetroffen. Tarenar ist gleich hier und Gidwin... nun... er ist gerade schlecht gelaunt. Ich glaube, er ist im Turm.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27467] = {title = "Vergrabene Klingen", objective = "Stoßt die lichtberührten Klingen in die Leichen von 10 getöteten Reitersoldaten der Geißel.", description = "Das Giftige Tal ist ein Morast, im wörtlichen und übertragenen Sinne. Es gibt dort oben genug Angehörige der Geißel, um uns beiden bis an unser Lebensende Schwierigkeiten zu bereiten.\n\nSie können die schwächeren wieder auferstehen lassen, wenn sie sterben, <Name>. Sie werden nie aufhören, nachzurücken, wenn wir nicht etwas unternehmen.\n\nNehmt diese Klingen und durchstoßt damit die Leichen aller Reitersoldaten der Geißel, derer Ihr habhaft werden könnt. Die Klinge ist einfach, aber ihre Verzauberung wird verhindern, dass die toten Knochen wiederbelebt werden können. Für immer.", progress = nil, completion = "Unsere Pflicht für heute ist getan.\n\nEs ist nur eine Frage der Zeit, bis wir die Geißel vernichtend schlagen. Heute haben wir Fortschritte gemacht.", rewards = "Gugel des Giftigen TalsAuf Euch wartet eine dieser Belohnungen:\n\nOmarions GabeLichtberührter Anhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27468] = {title = "Rettung des Belagerungspanzers", objective = "Sprecht mit einem Belagerungspanzerkommandanten auf einem kaputten Belagerungspanzer von Hochstade. Verteidigt den Panzer, während die Ingenieure Reparaturen vornehmen.", description = "Wir müssen unsere Belagerungspanzer einen nach dem anderen aus dem Schlamm ziehen. Nehmt die Ersatzteile, die Ihr gesammelt habt und gebt sie einem der Belagerungspanzerkommandanten, die auf den kaputten Fahrzeugen stehen.\n\nUnd dann verteidigt den Panzer, während die Ingenieure versuchen, ihn unzukaputten.\n\nGeht un' macht mich stolz, <Klasse>!", progress = "Steine un' Stümpfe un' Berge un' Matsch ... Bäh.\n\nIch hasse die Natur.", completion = "Jupp, noch ein weiterer Panzer, der zur Reparatur kann.\n\nDurch all diese Bäume un' Baumstümpfe un' Matsch un' Steine könnte man nicht mal einen Golfball abschlagen und erst recht keinen Panzer fahren.\n\nWir müssen unsere Vorgehensweise ändern.", rewards = "Panzerverteidigende TreterNaturzermalmender HelmSchrittbindende SchiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27469] = {title = "Freunde auf der anderen Seite", objective = "Findet Acride.", description = "Ich bringe Neuigkeiten von der Schwarzfelsspitze. Wir haben einen neuen Besucher. Sein Name ist Acride.\n\nEr sucht Leute, die stark, intelligent und geschickt sind. Ihr solltet zur Schwarzfelsspitze gehen und mit ihm sprechen.", progress = nil, completion = "Hallo, was führt Euch hierher?\n\nEntschuldigung, wer hat Euch geschickt? Ich fürchte, von einem &lt;Volk&gt; dieses Namens habe ich noch nie gehört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27470] = {title = "Ein möglicher Verbündeter", objective = "Findet Acride.", description = "Es ist kein Geheimnis, dass wir die Orcs im Schwarzfels nicht mögen. Wir beobachten sie daher ganz genau. Hier in den Bergen passiert nichts, von dem ich nichts weiß, <Klasse>.\n\nVor Kurzem kam ein ganz andersartiger Orc nach Schwarzfels. Er hat sich in der Schwarzfelsspitze niedergelassen, und ich weiß, dass er irgendwie vorhat, Nefarian und seine ganze Orcarmee zu stürzen. Normalerweise würde ich keinem dieser Orcs trauen, aber zur Zeit verfolgen wir ein gemeinsames Ziel. Findet ihn. Er heißt Acride.", progress = nil, completion = "Hallo, was führt Euch hierher?\n\nAlso Aufseher Schlickfaust hat Euch geschickt? Hört gut zu, wir haben viel zu besprechen und nur wenig Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27471] = {title = "Schwarzfelsanomalie", objective = "Findet Acride.", description = "In der Schwarzfelsspitze gibt es einen Orc, der ganz anders ist als alle anderen Orcs. Seine Sprache zeugt von Intelligenz und Wissen, die seinem Aussehen Hohn spricht. Im Gegensatz zu den anderen Orcs bekämpft er auch unsere Soldaten nicht.\n\nIhr müsst zur Schwarzfelsspitze reisen, nordwestlich von hier, und diesen Orc finden, der uns nur als Acride bekannt ist. Vielleicht ist er der Schlüssel, um die Armee der Orcs aufzuhalten. Vielleicht können wir Nefarian aufhalten, bevor es zu spät ist ...", progress = nil, completion = "Hallo, was führt Euch hierher?\n\nAlso Ihr seid auf Bitten von Fräulein Wolkenglanz hier? Das ist ja höchst interessant.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27472] = {title = "Erwacht, Godfrey", objective = "Bleibt bei Fürstin Sylvanas Windläufer, während sie Lord Godfrey und seine Männer aufnimmt.", description = "Eure Loyalität den Verlassenen gegenüber ist standhaft, <Name>. Was Ihr bisher für uns getan habt - Eure Dienste für die Horde - werden nicht unbemerkt bleiben. Nun, da Lord Godfrey und seine Männer sich bald wieder erholt haben werden, werden wir einen großen Vorteil gegenüber der Gilnearischen Befreiungsfront und dem Rest der Hunde der Allianz haben.\n\nIch möchte Euch zum Anlass von Lord Godfreys Wiedergeburt als Einem von uns an meiner Seite haben. Wir werden ihn und seine Männer gemeinsam in unseren Kreis aufnehmen.", progress = nil, completion = "Der heutige Tag stellt den Beginn einer neuen Ära für die Verlassenen und das Ende der Allianz in Lordaeron dar!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel 85149\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27474] = {title = "Die Barriere durchbrechen", objective = "Findet den Kodex von Mühlenbern.", description = "Während Godfrey und ich unseren Angriff auf Gilneas vorbereiten, möchte ich, dass Ihr den Angriff auf Mühlenbern, direkt östlich von hier, leitet.\n\nDie früheren Magier von Dalaran in Mühlenbern haben eine magische Barriere errichtet, die sie unsichtbar macht. Sie befinden sich in einer Art Dimensionstasche und erwarten Befehle der Allianz, um ihren Angriff zu beginnen. Wir müssen diesen Angriff durch einen Präventivschlag verhindern. Begebt Euch nach Mühlenbern und sucht nach Informationen, die uns Zugang zu diesen Magiern verschaffen.", progress = "Habt Ihr schon etwas gefunden?", completion = "Die Magier sind schlau. Der Kodex ist mit einem magischen Schutzzauber versiegelt.\n\nSchade nur, dass sie nicht schlau genug waren, zu erkennen, dass die früheren Erzmagier von Dalaran jetzt Verlassene sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27475] = {title = "Unnachgiebige Diener", objective = "Bergt 6 Dienerkerne.", description = "Die Magier von Mühlenbern haben abscheuliche Magie benutzt, um uns fernzuhalten. Elementardiener, deren Immunitäten wir nicht überwinden können, beschützen ihr Territorium.\n\nGeht nach Osten nach Mühlenbern und tötet die unerschütterlichen Elementardiener, die die Stadt bewachen. Dann bergt ihre Kerne. Bringt die Kerne hierher zu mir, damit ich einen Weg finden kann, wie wir sie alle zerstören können.", progress = "Habt Ihr die Dienerkerne gefunden?", completion = "Gut gemacht, &lt;Name&gt;. Das Lob, das die Bansheekönigin Euch zuteilwerden lässt, ist anscheinend nicht unbegründet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27476] = {title = "Dalar Morgenweber", objective = "Liefert den Kodex von Mühlenbern bei Dalar Morgenweber am Grabmal im Silberwald ab.", description = "Nehmt den Kodex und reist nach Norden zum Grabmal. Wenn Ihr dort eintrefft, sucht nach Dalar Morgenweber. Dalar ist ein früherer Erzmagier der Kirin Tor. Er wird sicherlich in der Lage sein, die Schutzzauber, die diesen Kodex umgeben, zu entfernen und ihm seine Geheimnisse zu entlocken.\n\nBeeilt Euch, <Name>.", progress = "Ja? Was wollt Ihr?", completion = "Die Dunkle Fürstin benötigt meine Expertenmeinung? Aber selbstverständlich! Gebt schon her mein Junge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27477] = {title = "Der Korpulente", objective = "Findet Blutschlinger im nördlichen Ödland der Östlichen Pestländer und vernichtet ihn.", description = "Nördlich von hier und westlich von Nordtal findet Ihr das fettleibige Madenungeheuer Blutschlinger.\n\nIch habe ganze Regimenter gegen dieses Monster eingebüßt. Seine Ausmaße sind gewaltig! Je mehr er frisst, desto größer wird sein Umfang...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr als Sieger hervorgeht. Man weiß, dass Blutschlinger schon andere verschlungen hat, die versucht haben, ihn zu jagen.", progress = nil, completion = "Macht weiter so und es könnte passieren, dass ich Euch hier in Ostwall bei mir behalte, &lt;Volk&gt;.", rewards = "Korpulente SchulterpolsterBlutschlingers HautOstwallstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27478] = {title = "Relios, Bewahrer der Relikte", objective = "Findet einen Siegelring eines Erzmagiers aus Dalaran.", description = "Die Dunkle Fürstin hat Recht, dass ich in der Lage bin, den Kodex zu entschlüsseln. Leider benötige ich dafür einen Siegelring von einem Erzmagier aus Dalaran. Mein eigener Ring wurde mir weggenommen, als ich vor vielen Jahren starb, aber es gibt vielleicht eine Möglichkeit.\n\nObwohl Dalaran fortgeschwebt ist, sind doch die Außenbezirke der Stadt erhalten geblieben. Weit im Osten liegen die Ruinen von Dalaran. Dort werdet Ihr einen Erzmagier mit Namen Relios finden. Nehmt seinen Siegelring an Euch und bringt ihn zu mir zurück.\n\nIhr dürft das Portal hinter mir benutzen, um zu dem Krater zu gelangen.", progress = "Habt Ihr einen Siegelring eines Erzmagiers aus Dalaran gefunden?", completion = "Perfekt. Ich hoffe, es war nicht zu schwierig, an ihn heranzukommen, &lt;Name&gt;. Relios war einer meiner Schüler, als ich noch ein Sterblicher war. Deshalb dürfte er ein fähiger und ernstzunehmender Gegner sein. Ich hätte Euch wohl schon vorher warnen sollen.\n\nNun, lasst uns den Ring anschauen.\n\n\n\nNa also...", rewards = "Schmerz des VerratsRelios' StreitkolbenKodexbrecherIhr bekommt:\n\nKugel der Verlassenen"}
MultiLanguageQuestData['de'][27479] = {title = "Rechtschaffene Empörung", objective = "Erbeutet 30 Moosschinderaugen von Moosschindertrollen in Zul'Mashar.", description = "Die Moosschinder von Zul'Mashar spucken dem Licht ins Gesicht! Ihr Kannibalismus, ihr Atheismus, ihr Atavismus stellen die Mächte des Bösen über die des Guten. Ich verschreibe, Ihr rückt ihnen zu Leibe, damit ihr Getreibe ein Ende finde und jeder noch so Blinde empfinde, welche Strafe auf Torheit stünde!\n\nIhr werdet nach Norden reisen und mit all Eurer rechtschaffenen Empörung über sie kommen, <Name>. Der Zorn, den sie im Angesicht des Lichts entflammt haben, wird Euch zueigen werden.", progress = "<Diakon Andaal ist ins Gebet vertieft.>", completion = "Oh, Hallelujah, gelobt sei das Licht, Bruder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27480] = {title = "Ley-Energien", objective = "Findet 8 arkane Überbleibsel.", description = "Das arkane Überbleibsel pulsiert mit seltsamer Energie. Vielleicht solltet Ihr nach weiteren Überbleibseln suchen. Dalar wäre an solchen Funden sicherlich interessiert.", progress = "Was habt Ihr denn da, <Name>?", completion = "Cleveres Mädel. Ich kann diese arkanen Überbleibsel auf jeden Fall bei meinen Studien verwenden. Um genau zu sein wurde Dalaran auf einer riesigen Leylinie erbaut. Daher ist es kein Wunder, dass es diese Gegenstände im Krater gibt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27481] = {title = "Aus dem Ziggurat", objective = "Erbeutet den Leichnam von Kriegsherr Thresh'jin.", description = "Die Zeit ist gekommen, Euch um einen Gefallen zu bitten, <Name>.\n\nWeit nördlich des Ostwallturms, verborgen in den Hügeln, liegt die Moosschinderhauptstadt Zul'Mashar. Hier wurde ich geboren und hier bin ich gestorben.\n\nDer Verräter Thresh'jin sitzt auf Zul'Mashars Ziggurat. Eigentlich hätte mir der Sitz zugestanden, aber er erschlich ihn sich von mir durch Verrat und Lügen. Er ist nicht stark. Er ist schwach.\n\nIch werde in Zul'Mashar zu Euch stoßen. Dann werden wir ihn töten. Eure Stärke und die meine. Vereint.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27482] = {title = "Hinein in die Flammen", objective = "Werft den Leichnam des Kriegsherrn Thresh'jin in das Feuer oben auf Zul'Mashars Ziggurat, wenn Ihr bereit seid, Euch von Vex'tul zu trennen.", description = "Dies ist unsere letzte Begegnung, <Name>. Ich verlasse die Karawane.\n\nBehaltet Thresh'jins Leiche, wenn Ihr weiter an meiner Seite kämpfen wollt. Ich kann noch ein wenig länger ausharren. Werft den Körper in das Feuer oben auf Zul'Mashars Ziggurat, wenn Ihr bereit zum Abschied seid.\n\nIch danke Euch für Eure Freundschaft, <Name>. Ihr wart stark.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberlegenheit der Stärke"}
MultiLanguageQuestData['de'][27483] = {title = "Praktische Rache", objective = "Tötet 12 beliebige Menschen aus Dalaran.", description = "Eigentlich bin ich kein rachsüchtiger Mann. Um genau zu sein bin ich eher Pragmatiker. Wisst Ihr, Sachlichkeit ist im Grunde das Gegenteil zu Rache. Die meisten Rachepläne sind höchst unpraktisch.\n\nABER... in diesem Fall... Da Ihr Euch ohnehin schon zu den Ruinen von Dalaran begebt, könnt Ihr auch jeden Menschen, der mit Dalaran in Verbindung gebracht werden kann, töten. Die Gründe dafür, dass ich sie tot sehen will, reichen von Hass über Zorn bis zu Verrat, aber ich versichere Euch, der Groll ist durchweg berechtigt. Erledigt das für mich und ich werde Euch reich belohnen.", progress = nil, completion = "Ich hatte mit Sicherheit angenommen, dass der Tod eines Dutzends meiner meist gehassten Feinde mir eine große Last von den Schultern nimmt. Leider spüre ich gar nichts. Vielleicht bin ich ein Psychopath.", rewards = "PsychopathenbeilAxt der praktischen RacheMorgenwebers DolchSchneide der drückenden LastIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27484] = {title = "Es darf nur einer eintreten", objective = "Bringt den Siegelring eines Erzmagiers aus Dalaran zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald zurück.", description = "<Dalar blättert durch den Kodex.>\n\nHAHAH!\n\nOh... Das ist schlimm.\n\n<Dalar klappt den Kodex zu und schaut zu Euch hoch.>\n\nNur EINER darf mit Hilfe dieses Rings die Dimensionstasche in Mühlenbern betreten. Diese Person muss sich dann einen Weg durch eine Armee von Magiern freikämpfen und den Erzmagier töten, der die Verschiebung von der anderen Seite her erschafft. Erst dann wird die Dimension in sich zusammenbrechen und alle Magier auswerfen.\n\nDas Portal, durch das man hineingelangen kann, liegt versteckt hinten in einer Höhle in Berens List.\n\nMehr weiß ich nicht. Bringt den Ring zu Sylvanas zurück.", progress = "Was habt Ihr erfahren?", completion = "Nur einer darf eintreten? Ich kenne genau die richtige Person für diese Aufgabe.\n\n&lt;Sylvanas nickt Euch zu.&gt;\n\nIch werde unsere Streitkräfte vorbereiten und bereithalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27485] = {title = "Ein herzliches Willkommen", objective = "Trefft Euch mit Lirastrasza im Zinnoberrefugium.", description = "Ich bin froh, dass Ihr zurück seid! Um die Welt zu retten oder dergleichen, da bin ich sicher.\n\nIch wurde ausgeschickt, um Beziehungen mit den roten Drachen in der Gegend aufzubauen, aber ich finde sie weniger zugänglich als diejenigen in Wyrmruh. Allerdings sagte man mir, dass Ihr jemand seid, der Probleme löst.\n\nEin Problemlöser sozusagen.\n\nHättet Ihr vielleicht Lust, ein wenig Vertrauen mit Lirastrasza im Zinnoberrefugium im Norden aufzubauen? Alles, das sie mir gegenüber ein wenig milder stimmt wäre wunderbar.", progress = nil, completion = "Ich bin froh, dass Lira Euch nicht verschreckt hat. Ich will damit nicht sagen, dass ihre Bedenken nicht gerechtfertigt sind, aber wir haben einen gemeinsamen Feind. Vielleicht ist sie etwas übervorsichtig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27486] = {title = "Ein herzliches Willkommen", objective = "Trefft Euch mit Lirastrasza im Zinnoberrefugium.", description = "Gut. Ihr seid zurück. Rettet wohl wieder die Welt, was?\n\nIch wurde ausgeschickt, um Beziehungen zu den roten Drachen in der Gegend aufzunehmen, aber die hiesige Variante ist bei Weitem nicht so entgegenkommend, wie die Drachen im Wyrmruhtempel. Mir ist allerdings zu Ohren gekommen, dass Ihr jemand seid, der Probleme löst.\n\nEin Problemlöser sozusagen.\n\nIhr müsst das Vertrauen von Lirastrasza im Zinnoberrefugium südwestlich von hier gewinnen. Unsere Zusammenarbeit mit dem Drachenmalklan hat die Angelegenheit zugespitzt, aber ich bin zuversichtlich, dass Ihr die Wogen glätten könnt.", progress = nil, completion = "Ich bin froh, dass Lira Euch nicht verschreckt hat. Ich will damit nicht sagen, dass ihre Bedenken nicht gerechtfertigt sind, aber wir haben einen gemeinsamen Feind. Vielleicht ist sie etwas übervorsichtig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27487] = {title = "Ix'lar der Unterfürst", objective = "Tötet Ix'lar den Unterfürsten und 10 seiner Diener.", description = "Ich weiß, dass wir eigentlich nach Nordtal aufbrechen sollten, aber das hat doch noch Zeit, oder? Dieser niedliche kleine Goblin hat mir übrigens erzählt, dass die Geißel in der Nähe weilt.\n\nAnscheinend gibt es einen nerubischen Unterfürsten namens Ix'lar, der seit der Vernichtung des Lichkönigs versucht, sich einen Namen zu machen. Er und seine Untoten haben nördlich von uns ein Lager errichtet.\n\nNatürlich will Tyrosus, dass wir Banshees in Nordtal töten. Das werden wir auch. Aber lasst uns zuerst diesen Neruber töten, solange wir in der Nähe sind!", progress = nil, completion = "Ich konnte ihn nicht aufhalten. Während Ihr und Tarenar unterwegs wart, ist Giddy ganz allein nach Norden gelaufen!\n\nTarenar, Ihr hättet es besser wissen sollen! Gidwin wird manchmal so ungeduldig und Ihr stachelt ihn noch an. Wenn Giddy in Schwierigkeiten gerät, gebe ich Euch die Schuld daran.", rewards = "Gürtel der VerzögerungÜberstürzte HandschuheAuf Euch wartet eine dieser Belohnungen:\n\nUnterfürstenmandibulaAnhänger des schlecht Beratenen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nCancel Summon Tarenar Sunstrike\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27488] = {title = "Ungeduld", objective = "Sucht nach Gidwin Goldzopf in Nordtal.", description = "Dieser verdammte Zwerg. Immer kriege ich wegen ihm Ärger mit Fiona. Seht sie Euch doch an! Sie REDET nicht einmal mehr mit mir!\n\nIch werde hier bleiben und versuchen, meine Freundschaft mit unserer Worgenfreundin zu kitten. Würde es Euch etwas ausmachen, allein nach Gidwin zu suchen? Es geht ihm bestimmt gut. Er kann auf sich allein aufpassen. Er war auf dem Weg nach Norden. Weit kann er nicht gekommen sein.", progress = "In Nordtal gibt es einige Geister und Banshees. Der alte Giddy kommt mit denen schon klar.", completion = "Ihr seid ihm nicht begegnet? Wo ist er denn nur?\n\nSein... sein Gebetsbuch? Warum hat er das zurückgelassen?\n\nOh...\n\nBeim Licht, was habe ich getan?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27489] = {title = "Ich allein bin schuld", objective = "Steigt in Fionas Karawanenwagen und fahrt zum Nordpassturm.", description = "Das ist meine Schuld. Ich... Ich habe seine Warnungen und Beschwerden ignoriert. Ich konnte nicht anders - Ich sah die Geißel so nahe hinter dem Turm, da... Ich MUSSTE sie töten.\n\nArgus sagt, Gidwin sei nach Nordwesten gebracht worden. Das ist unsere einzige Spur, also werden wir in diese Richtung aufbrechen.\n\nIch pfeife auf Nordtal und den Argentumkreuzzug! Wir werden Gidwin von diesen Geißelmistkerlen zurückholen.", progress = nil, completion = "Die Zeit rennt uns davon, &lt;Name&gt;. Mit jeder Minute, die wir verschwenden, steigt die Wahrscheinlichkeit, dass die Geißel Gidwin umbringt. Wenn er nicht schon tot ist.\n\nDoch das glaube ich nicht. Giddy ist zwar nicht der Hellste, aber wenn es sein muss, schwingt er das Licht wie ein Champion.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27490] = {title = "Den SI:7 absetzen", objective = "Holt bei Angus Stillberg eine Truppe der Wildhammervandalen ab und begleitet sie zum Landepunkt am Schattentor.", description = "Mathias Shaw und der SI:7 sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.\n\nDie Wildhämmer sind so freundlich, uns dorthin zu fliegen. Die Agenten müssen jedoch zuerst etwas unten bei den Toren erledigen.\n\nSprecht mit Angus Stillberg und schnappt Euch eine Truppe, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen blauen X markiert.", progress = nil, completion = "Das muss schlimm gewesen sein.\n\nAuch wenn ich mit ihren Methoden nicht einverstanden bin, kann niemand die Effizienz von Mathias Shaw und seinem SI:7 anzweifeln. Und schließlich seid Ihr auch noch hier. Unser Sieg ist schon in trockenen Tüchern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27491] = {title = "Die Kor'kron absetzen", objective = "Holt bei Jon-Jon Glibberhals eine Truppe der Schmetterschlagwindreiter ab und begleitet sie zum Landepunkt am Schattentor.", description = "Garona und ein Kommando der Kor'kron sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.\n\nDer ansässige Trollstamm ist so freundlich, uns auf ihren Windreiten dorthin zu fliegen. Die Assassinen müssen jedoch zuerst etwas unten bei den Toren erledigen.\n\nSprecht mit dem Anführer der Trolle, Jon-Jon Glibberhals, und schnappt Euch ein Kommando der Kor'kron, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen roten X markiert.", progress = nil, completion = "Das muss spannend gewesen sein.\n\nTrotz der Verluste, die die Kor'kron vielleicht unterwegs erlitten haben, wird niemand es wagen, Zweifel an ihrer Effizienz noch an der Garonas zu äußern. Und da Ihr auch mit von der Partie seid, ist es nur eine Frage der Zeit, bis der Sieg unser ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27492] = {title = "Oger und Ettins", objective = "Tötet 10 Oger oder Ettins am Schattentor.", description = "Wie bei jeder Offensive müsst Ihr erst ihre Reihen schwächen. Wir haben uns ganz schön angestrengt, um dort hinein zu gelangen. Aber jemand wie Ihr… Nun, sagen wir einfach, dass ich keinen Zweifel habe, dass Ihr die Tore der Zitadelle im Südwesten durchbrechen und den Ogern und Ettins des Blutaugenklans ein oder zwei Lektionen erteilen könnt.", progress = "Was ist los? Habt Ihr Jungs der Allianz nicht die Nerven, um den Auftrag zu erledigen?\n\n<Kurdran zwinkert Euch zu.>\n\nSoll ich da 'rüber fliegen und sie für Euch erledigen?", completion = "Genau das will ich sehen, Kumpel! Heute scheint ein guter Tag zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27493] = {title = "Oger und Ettins", objective = "Tötet 10 Oger oder Ettins des Blutaugenklans am Schattentor.", description = "Ich möchte, dass Ihr Euch hinter diese Felsen schwingt und jeden Oger oder Ettin des Blutaugenklans tötet, der Euch über den Weg läuft. Könnt Ihr das für mich tun, <Name>?", progress = nil, completion = "Und ich dachte, es könnte heute nicht mehr besser kommen.\n\nNun, ich irre mich gerne, zumindest manchmal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27494] = {title = "Berge versetzen", objective = "Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.", description = "Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!\n\nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Agenten des SI:7 ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.\n\nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.\n\nDann werden wir angreifen und den Ogern den Rest geben!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27495] = {title = "Berge versetzen", objective = "Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.", description = "Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!\n\nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Assassinen der Kor'kron ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.\n\nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.\n\nDann werden wir angreifen und den Ogern den Rest geben!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27496] = {title = "Holt die Artillerie!", objective = "Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude am Schattentor als Ziel zu markieren.", description = "Ich bevorzuge einen ehrenhaften Kampf Mann gegen Mann. Diese Monster verdienen es, durch die Waffen in unseren Händen den Tod zu finden. In diesem speziellen Fall müssen wir jedoch auf mächtigere Methoden zurückgreifen.\n\nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Südwesten. Unsere Kanonen werden den Rest erledigen.", progress = nil, completion = "Dank Euch können unsere Kanoniere ihr Ziel nicht mehr verfehlen. Und nun berichtet mir von der Lage am Schattentor.", rewards = "SignalrauchschulterpolsterHalsberge des MarkierersLeuchtfeuerarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27497] = {title = "Holt die Artillerie!", objective = "Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude beim Schattentor als Ziel zu markieren.", description = "Wie schade, dass wir unsere Feinde nicht mehr mit der Seuche strafen dürfen. Gerade in dieser Lage wäre das sehr effektiv. Nun ja, zumindest haben wir Kriegsmaschinen, um ihre ach so geliebten Tore einzureißen.\n\nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Nordwesten. Unsere Kanonen werden den Rest erledigen.", progress = nil, completion = "Ich muss sagen, der Anblick der einschlagenden Bomben in ihre Gebäude hat mich gut unterhalten.", rewards = "Schulterschutz des EindringlingsRauchsignalbrustschutzGebäudesprengerarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27498] = {title = "Befehlt den Angriff", objective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Gipfel des Siegers signalisieren, dass sie angreifen können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27499] = {title = "Befehlt den Angriff", objective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Schmetterschlagposten signalisieren, dass sie angreifen können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27500] = {title = "Vier Köpfe sind besser als keiner", objective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", description = "Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nIhr seid Euch ziemlich sicher, dass Cassius und Kurdran einen Beweis für ihren Tod sehen wollen.", progress = "Tropft da etwa Blut aus Eurer Tasche?", completion = "&lt;Der Paladin verzieht das Gesicht.&gt;\n\nDa habt Ihr aber eine grausame Trophäensammlung. Ich hätte Euch auch geglaubt, wenn Ihr mir einfach gesagt hättet, dass sie tot sind. Dennoch danke, dass Ihr so vorausschauend wart, sie zu töten.\n\nDas Schattentor ist bald in unserer Hand. Es wird Zeit, uns der Schattenzitadelle selbst zuzuwenden.", rewards = "SchädelträgerSchiftung der grausigen LeistungAuf Euch wartet eine dieser Belohnungen:\n\nZa'brox' Glückszahn\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27501] = {title = "Vier Köpfe sind besser als keiner", objective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", description = "Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nIhr seid Euch ziemlich sicher, dass Lady Cozwyn und Zaela einen Beweis für ihren Tod sehen wollen.", progress = "Tropft da etwa Blut aus Eurer Tasche? Ich hoffe, es ist nicht Euer eigenes.", completion = "&lt;Die hohe Dame grinst boshaft.&gt;\n\nDa habt Ihr aber eine grausame Trophäensammlung. Ich hätte Euch auch geglaubt, wenn Ihr mir einfach gesagt hättet, dass sie tot sind. Aber ich weiß Eure zusätzliche Mühe durchaus zu schätzen. Dennoch danke, dass Ihr so vorausschauend wart, sie zu töten.\n\nDas Schattentor ist bald in unserer Hand. Es wird Zeit, uns der Schattenzitadelle selbst zuzuwenden.", rewards = "SchädelträgerSchiftung der grausigen EhreAuf Euch wartet eine dieser Belohnungen:\n\nZa'brox' Glückszahn\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27502] = {title = "Hinauf zur Zitadelle", objective = "Sprecht mit dem Truppenkommandanten des SI:7 und begleitet dann die Truppe des SI:7.", description = "Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen des SI:7 zu Meister Mathias Shaw zu führen.\n\nEr hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant des SI:7 kann Euch den genauen Ort nennen.\n\nVielen Dank, <Name>. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27503] = {title = "Hinauf zur Zitadelle", objective = "Sprecht mit dem Truppenkommandanten der Kor'kron und begleitet dann die Truppe der Kor'kron.", description = "Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen der Kor'kron zu Garona zu führen.\n\nSie hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant der Kor'kron kann Euch den genauen Ort nennen.\n\nVielen Dank, <Name>. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27504] = {title = "Sogar Drachen bluten", objective = "Sprecht mit Velastrasza im Zinnoberrefugium.", description = "Ich werde nicht so unhöflich sein, Eure Hilfe abzulehnen, wenn Ihr sie mir schon anbietet.\n\nWir befinden uns im stetigen Kampf mit den Zwielichtdrachen im Süden. Zwar sind unsere Angriffe nicht ganz fruchtlos, aber die Drachen, die aus Grim Batol hinausströmen, haben eine Art Verderbnis auf uns herab beschworen, die es nun zu läutern gilt.\n\nVelastrasza und Unheilsflamme kümmern sich um unsere verletzten Brüder. Geht und schaut, ob Ihr ihnen helfen könnt.", progress = nil, completion = "Calen ist sehr vertrauensselig in letzter Zeit. Nicht viele Fremde dürfen das Refugium betreten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27505] = {title = "Heilung auf Drachenart", objective = "Beschützt 5 zinnoberrote Heiler, während sie verwundete Drachen heilen.", description = "Wenn unsere Drachen aus der Schlacht zurückkehren, sind sie ganz in vom Zwielicht verderbte Flammen gehüllt und werden von den Zwielichtdrachen verfolgt.\n\nMeine Heiler können sich zwar um die Wunden unserer Drachen kümmern, aber sie müssen dabei geschützt werden. Haltet die Drachen von meinen Heilern fern. Wenn Ihr könnt, helft auch Ihr unseren Drachen mit Eurer Heilkraft.\n\nVielen Dank für Eure Unterstützung in dieser Angelegenheit. Unsere Schlachten um Grim Batol nehmen kein Ende. Wir müssen unsere mächtigsten Drachen so schnell wie möglich wieder in den Kampf schicken.", progress = "Schützt die Heiler, während sie unsere verwundeten Drachen heilen!", completion = "Wir werden Grim Batol vom Schattenhammer und seinen Verbündeten zurückerobern. Es wird vielleicht ein wenig dauern, aber bei dieser Aufgabe dürfen wir nicht scheitern.", rewards = "BlitzsiegelsandalenSicherheitsschiftungZinnobergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27506] = {title = "Leben aus dem Tod", objective = "Pflanzt Rubinsamen in die Leichname von 6 Drachkin im Zinnoberrefugium.", description = "<Volk>, ich habe eine Aufgabe für Euch.\n\nNehmt diese Rubinsamen und pflanzt sie in die Leichname der Drachkin, denen Ihr begegnet. Zwielicht oder Zinnober, Welpling oder Drache, es ist ganz egal. Wir müssen dafür sorgen, dass ihre Körper wieder der Erde zurückgegeben werden, damit das Leben erneut erblühen kann.\n\nIm Tod sollte es immer neues Leben geben. Lasst Euch das einen Trost in Zeiten des Krieges und des Leids sein.", progress = nil, completion = "Durch diese Tat verweigern wir Todesschwinge die Zerstörung, die er so leidenschaftlich anrichten möchte. Durch diese Tat geht das Leben weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27507] = {title = "Die Ausbreitung des Zwielichts", objective = "Tötet 12 Zwielichteindringlinge im Zinnoberrefugium.", description = "Im Refugium wimmelt es von Zwielichteindringlingen. Sie strömen von einem unbekannten Ort im Westen auf die Lichtung.\n\nAn diesem heiligen Ort kann es für sie kein Mitleid geben. Welchen Funken der Gewalt Ihr auch in Eurem rechtschaffenen Herzen finden mögt, lasst sie darin in Flammen aufgehen.", progress = nil, completion = "Ihr habt ein Händchen fürs Töten, wie ich sehe. In Zeiten wie diesen hat auch dies eine Berechtigung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27508] = {title = "Weit weg vom Nest", objective = "Holt 6 Zinnobereier zurück.", description = "Schaut… Ich weiß, dass Ihr keinen Grund habt, mich zu mögen, genauso wie auch ich Euch nicht besonders mag, aber ich brauche jede Hilfe, die ich bekommen kann.\n\nDiese Zwielichteindringlinge stehlen unsere Eier. Ohne Zweifel haben sie vor, sie zurück nach Grim Batol zu bringen, um damit zu experimentieren und sie zu pervertieren. Das werde ich einfach nicht zulassen.\n\nWenn Ihr uns wirklich helfen wollt, dann haltet sie auf! Holt die Eier zurück und bringt sie mir.", progress = "Die Zwielichtdrachen entstehen aus ihren abscheulichen Experimenten. Der Schattenhammer ist zu weit gegangen. Todesschwinge ist zu weit gegangen.", completion = "Ich weiß nicht, ob Ihr das für mich oder die Jungen im Inneren getan habt, aber das spielt auch keine Rolle. Es zeigt deutlich, dass Ihr ein Freund unseres Schwarms sein wollt. Ich weiß das zu schätzen.\n\nIch kann Euren Verbündeten die Angriffe auf meine Brut nicht verzeihen, aber bis jetzt scheint es zumindest so, als hättet Ihr Euch für die richtige Seite entschieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27509] = {title = "Verteidigungslücke", objective = "Findet die Quelle des Schattenhammers im Zinnoberrefugium und vernichtet sie.", description = "Jeder Millimeter der Luft um das Refugium herum wird permanent von Liras Drachen bewacht. Sie müssen sich von unten einen Weg in den Schrein gebahnt haben.\n\nNehmt diese Blitzwuchspartikel. Sie sollten sich gut dafür eignen, sämtliche Löcher, Tunnel oder Portale zu schließen, über die sie unsere Verteidigung durchbrochen haben könnten.\n\nFindet die Lücke in unserer Verteidigung, Schließt sie.", progress = nil, completion = "Gut gemacht. Vielen Dank, &lt;Volk&gt;.\n\nIch werde dafür sorgen, dass wir so einen dummen Fehler nicht mehr begehen.", rewards = "Helm der saftgrünen ExplosionTaillenschutz des DrachenheilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27510] = {title = "Ein Wolf im Bärenpelz", objective = "Tötet 10 unauffällige Bären.", description = "Diese Worgen verkaufen uns für dumm! Man sollte meinen, dass nur ein Schwachkopf einen ihrer Druiden in Bärengestalt für einen echten Bären halten würde. Leider gibt es hier an der Frontlinie der Verlassenen viele Schwachköpfe. Wir haben bereits mehrere Bataillone bei organisierten Bärenangriffen der Worgen verloren. Ja, es ist in der Tat noch schwachsinniger, als es klingt.\n\nDirekt östlich von hier Richtung Hügelland findet Ihr Druiden der Worgen in den Wäldern. Sie sind als Bären getarnt. Tötet sie und sichert unsere südliche Versorgungslinie.", progress = nil, completion = "Ich hoffe nur, dass wir demnächst nicht auch noch von unverdächtigen Vögeln, Katzen und Bäumen dezimiert werden… oder Seelöwen! Könnt Ihr Euch das vorstellen?", rewards = "Unscheinbare PantalonsBärenbalgstiefelUnverwechselbare HandschuheIhr bekommt:\n\nBärensteaks"}
MultiLanguageQuestData['de'][27511] = {title = "Spannende Entdeckungen", objective = "Erforscht die Kammer der Sterne.", description = "Welch ein Fund! Und irgendwie ist alles von Plünderern verschont geblieben...\n\nHört zu, <Name>. Ich muss diesen Ort aufzeichnen, bevor wir etwas verändern. Warum seht Ihr Euch nicht ein wenig um, während ich das mache - Ihr wisst schon, ein wenig auf Entdeckungsreise gehen. Ihr habt es Euch verdient.\n\nHaltet Eure Augen offen und achtet auf Ungewöhnliches.\n\nOh! Und bitte... macht nichts kaputt, ja?", progress = nil, completion = "Eure Erforschung der Kammer der Sterne hat mehr Fragen aufgeworfen als Antworten gebracht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27512] = {title = "Dimensionsübergreifender Krieg: Kapitel I", objective = "Findet das Dimensionsportal von Mühlenbern.", description = "<Sylvanas gibt Euch den Siegelring.>\n\nNehmt den Ring und macht Euch auf nach Berens List im Südosten von hier in einer Höhle in den Hügeln. Sobald Ihr dort seid, durchsucht die Höhle nach dem Portal zu der Dimensionstasche, die die Magier von Mühlenbern verbirgt.\n\nIch werde mit Euch über Eure Gedanken kommunizieren, <Name>. Wenn Ihr das Portal erreicht habt, werde ich Euch Eure Befehle geben.", progress = "<Das Portal summt.>", completion = "&lt;Die Stimme der Bansheekönigin erfüllt Eure Gedanken.&gt;\n\nJa, das ist es. Jetzt streicht mit dem Ring über die Runen auf dem Portal und Ihr solltet für die dimensionsübergreifende Reise vorbereitet sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27513] = {title = "Dimensionsübergreifender Krieg: Kapitel II", objective = "Tötet 20 Magier von Mühlenbern.", description = "<Die Worte der Bansheekönigin ertönen im Inneren Eures Kopfes.>\n\nIhr seid jetzt bereit, das Portal zu benutzen. Seid gewarnt, <Name>, sobald Ihr das Portal durchschreitet, erscheint Ihr in einer anderen Dimension von Mühlenbern. Dort werden Hunderte oder sogar Tausende Magier darauf warten, Euch zu töten.\n\nIhr müsst durchhalten und alle töten, die sich Euch in den Weg stellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27514] = {title = "Vogel am Boden! Vogel am Boden!", objective = "Findet den abgestürzten Greifenreiter der Wildhämmer Thordun Hammerschlag am Zwielichtufer im Schattenhochland.", description = "Während Ihr an der Küste gekämpft habt, habe ich gesehen, wie fast genau westlich von hier ein Greif aus den Wolken gestürzt ist.\n\nEs war keiner von unseren.\n\nWahrscheinlich gehörte er zu einem der Wildhämmer. Ich weiß, dass Kuran als eine der obersten Prioritäten nach der Einnahme des Strandes Kontakt zu den verschollenen Wildhammerklans aufnehmen wollte.\n\nIch kann keinen meiner Männer entbehren, um dort nachzusehen, aber Euch schon. Findet den abgestürzten Wildhammer!", progress = nil, completion = "Ach, so ein Mist. Ihr seid nur ein &lt;Klasse&gt; der Allianz. Ich hatte auf Rettung gehofft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27515] = {title = "Die Wurzel alles Guten", objective = "Sammelt 8 Stück dorniger Stinkwurz am Zwielichtufer.", description = "Schaut doch, Kumpel. Sie liegt in den letzten Zügen! Wenn mein Vogel stirbt, bin ich so gut wie wertlos.\n\nAlso macht Euch nützlich. Hier auf der Halbinsel wächst dorniger Stinkwurz im Boden. Der Geruch zieht Euch die Socken aus, aber in Wasser eingeweicht wird daraus ein echtes Allheilmittel.\n\nSammelt ein paar Wurzeln, während ich meinen Vogel verteidige. Und beeilt Euch! Ihr Flachzangen von der Allianz habt ja nicht gerade den Ruf, rechtzeitig einzuschreiten, oder?", progress = "Habt Ihr meine Wurzeln, <Klasse>? Na?", completion = "Oh, gutes Zeug! Ich hoffe, Ihr habt nichts davon gegessen. Es verursacht schlimme Krämpfe, aber bei Vögeln wirkt es Wunder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27516] = {title = "Auf Schwingen nach Hochstade", objective = "Sprecht mit Thordun Hammerschlag und fliegt gemeinsam nach Hochstade!", description = "He, schaut nur! Sie ist schon viel munterer.\n\nGut, <Herr/Fräulein> Etepetete von der Allianz. Ist das Euer Lager da an der Küste? \"Hochstade\" sagt Ihr? Meint Ihr, mein Vogel und ich könnten dort eine Weile Unterschlupf finden, bis es ihr besser geht?\n\nSpringt auf! Wir fliegen gemeinsam nach Hochstade!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Durch Eure Rettung des abgestürzten Greifenreiters konnten wir einen ersten Kontakt mit den alten Wildhammerklans herstellen. Wir werden herausfinden, wer noch übrig ist und wie viele es sind.\n\nWir bekommen Auftrieb!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27517] = {title = "Seid vorbereitet", objective = "Sammelt 6 Stücke Seil.", description = "Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt ohne ausreichend Seil dabeizuhaben... nicht wahr?\n\nDavon kann man nie genug haben!\n\nMan geht sogar so weit, jedes Stück, das man finden kann, von den Skeletten hier aufzusammeln.", progress = "Was habt Ihr gefunden, <Name>??", completion = "Ahh, Seil! Danke, mein Junge!\n\nIrgendwie habe ich das Gefühl, ich werde es brauchen.", rewards = "Helm der gebrochenen KnochenBeinknochenbrechende StampferSeilgreiferhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27518] = {title = "Dimensionsübergreifender Krieg: Kapitel III", objective = "Überladet Erzmagier Ataeric mit arkaner Macht, um den transdimensionalen Schild auszuschalten.", description = "<Sylvanas spricht direkt durch Euch.>\n\nIhr müsst das Wesen, das diese Dimensionstasche aufrechterhält, finden. Wahrscheinlich ist es dieser Narr, Ataeric... Sucht das Gelände nach ihm ab. Solltet Ihr ihn finden, müsst Ihr alles Notwendige tun, um ihn davon abzuhalten, seine Magie zu kanalisieren. Er wird zweifellos durch einen mächtigen, arkanen Schild geschützt und wird Handlanger aus arkaner Energie auf Euch loslassen. Besiegt die Handlanger in seiner Nähe, um ihre Energien freizusetzen. Kein Magier kann mit so viel Kraft umgehen!", progress = nil, completion = "Hätte ich nicht mit eigenen Augen Eure Taten gesehen, ich hätte es nicht geglaubt, &lt;Name&gt;. Jetzt, da die Magier von Mühlenbern sich auf unserer Seite befinden, gibt es nur noch eins für uns zu tun, bevor wir Gilneas zurückerobern und diese Hunde der Allianz nach Sturmwind zurückrennen lassen.", rewards = "Transdimensionaler UmhangAtaerics HandschuheGefäß der Dunklen FürstinIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27519] = {title = "Unter dem erstickenden Sand", objective = "Rettet 8 Überlebende von Orsis.", description = "Nein... Das kann nicht sein.\n\nOrsis ist fast vollkommen unter dem Wüstensand begraben.\n\nDer Feind wird dafür bezahlen.\n\nDoch zunächst müssen wir meinem Volk helfen. Schnell, <Name>. Wir haben nicht viel Zeit, bevor auch der letzte meiner Brüder lebendig begraben wird!", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Orsis wurde dafür bestraft, sich nicht den Truppen von Todesschwinge angeschlossen zu haben.\n\nPrinz Nadun hat meinem Volk Zuflucht in seiner Stadt angeboten. Ich muss dort hingehen und mich um die Überlebenden kümmern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27520] = {title = "Al'Akirs Diener", objective = "Tötet 6 Abkömmlinge von Al'Akir.", description = "Al'Akir hat seine Diener ausgesandt, um Todesschwinges Befehle zu befolgen.\n\nDie Botschaft ist deutlich. Wir schließen uns ihnen an oder sie vernichten uns.\n\nIch weiß nicht viel über Euch, <Volk>. Aber eins weiß ich. Wenn Ihr Euch als Feind Al'Akirs erweist, wird Eure Hilfe nicht unbemerkt bleiben.\n\nWas sagt Ihr dazu, <Klasse>?", progress = nil, completion = "Ihr erweist Euch weiterhin als wertvoller Verbündeter, &lt;Name&gt;.", rewards = "Handschuhe der SteleViperngriffarmschienenAuf Euch wartet eine dieser Belohnungen:\n\nKenotaphenhalsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27521] = {title = "Elender Hort des Abschaums und der Boshaftigkeit", objective = "Tötet 9 Getriebene nahe der Jagdhütte von Quel'Lithien in den Östlichen Pestländern.", description = "<Volk>... bitte, ich brauche Eure Hilfe.\n\nEtwas ist mit meinen Leuten geschehen. Unser Kommandant, Waldläuferlord Falkenspeer, hat einen Gegenstand aus magischer Energie gefunden. Meine Freunde, meine Familie... sie alle sind seiner verführerischen Macht erlegen. \n\nSie sind verdorben, <Volk>. Sie alle.\n\nMeine Ellaria würde so nicht leben wollen, auch meine Brüder nicht. Bitte erlöst sie von ihrem Leid. Die Jagdhütte von Quel'Lithien ist nicht weit weg. Nur den Hügel hinauf im Nordwesten.", progress = nil, completion = "Bemitleidet mich nicht. Es waren zwar meine Freunde, die Ihr an der Jagdhütte von Quel'Lithien gesehen habt, aber sie waren schon so gut wie tot.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27522] = {title = "Prügelstrafe", objective = "Schlagt mindestens 6 Belagerungsingenieure der Geißel nieder, um an Informationen über Gidwins Verbleib und seinen Entführer zu gelangen.", description = "Uns Paladinen bringt man bei, unseren Feinden gerecht und ruhig entgegenzutreten, aber dies ist ein Notfall. Außerdem habe ich noch nie auf meine Lehrer gehört.\n\nIch werde versuchen, im Pestwald mehr über Giddy herauszufinden. Kümmert Ihr Euch um die Geißel nordöstlich von hier, auf der anderen Seite dieses Turms. Die Untoten fürchten den Tod nicht, aber schlagt sie lang genug, dann verplappern sie sich vielleicht und geben uns Hinweise auf Gidwins Aufenthaltsort.", progress = nil, completion = "Hört sich so an, als hättet Ihr Erfolg gehabt. Hoffentlich reichen diese Informationen, um Gidwin zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27523] = {title = "Dämmerschwinge, oh, wie ich Euch hasse...", objective = "Beschafft einen Fellflicken von Dämmerschwinge.", description = "Ich habe zu meiner Zeit viel gesehen, <Volk>. Die Gipfel des Hyjal... die Seltsamkeiten der Scherbenwelt... einen Wall aus Geißelsoldaten auf dem Weg in die Schlacht. Aber noch nie zuvor habe ich eine so große und schockierend weiße Fledermaus wie Dämmerschwinge gesehen.\n\nWie er mich aus seinem Nest verspottet!\n\nDiese dämonische Albinofledermaus kreist südwestlich von hier, nördlich vom Faulholzsee. Findet und vernichtet ihn. Sollte er zu hoch fliegen, könnt Ihr ihn mit meinem Leuchtfeuer anlocken.", progress = "Ich hoffe, Ihr habt diese Kreatur beseitigt.", completion = "Hervorragende Arbeit. Nun kann ich meine Arbeit fortsetzen, ohne von dieser großen, weißen Bestie abgelenkt zu werden.\n\nIch werde dieses Fell zu etwas verarbeiten, dass Ihr nutzen könnt.", rewards = "FledermausklauenbeinschützerMantel des LeichenverbrennersDämmerschwingenstiefelDämmerschwingenhandlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27524] = {title = "Blinde Wut", objective = "Findet Tarenar Sonnenhieb im Pestwald in den Östlichen Pestländern.", description = "Tarenar hat nicht gescherzt, als er sagte, Vernunft und Vorsicht interessieren ihn nicht. Er hätte diesem Hochelfen beinahe den Kopf abgeschlagen, als er auf der Suche nach Gidwin in den Pestwald lief. Ihr solltet ihm folgen.\n\nDer Pestwald ist ziemlich groß, <Name>. Viel Glück. Ich hoffe, ihr <Jungs/Drei> kommt heil aus dem Wald heraus.", progress = nil, completion = "Ich habe nichts außer hirnlosen Untoten gefunden, aber davon jede Menge. Ich wollte mich gerade nach Stratholme durchtöten, als Ihr kamt. Hattet Ihr mehr Erfolg?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27525] = {title = "Wächter von Stratholme", objective = "Tötet Omasum Pesthuf und Karthis Dunkelrune.", description = "Baroness Anastari hält ihn gefangen? Hier im Pestwald?\n\nDer Pestwald ist groß... aber wir werden ihn finden. Wir WERDEN Gidwin finden.\n\nUnmittelbar in unserem Osten und Westen befinden sich zwei Nekropolen neben dem Weg nach Stratholme. Im Inneren werdet Ihr zwei Todesrittern begegnen - Totenschwurs Leutnants. Ich bezweifle, dass einer von ihnen Verwendung für eine Paladingeisel hätte, aber vielleicht wissen sie ja, wo Gidwin ist.", progress = nil, completion = "Wir müssen weiter! Wir sind schon ganz nahe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27526] = {title = "Gidwins Schicksal enthüllt", objective = "Sucht nach Gidwin Goldzopf im Schlachthaus im Zentrum des Pestwalds.", description = "Rasch - findet einen Eingang zum Schlachthaus südlich von uns. Ich treffe Euch im Inneren.\n\nBereitet Euch auf einen Kampf vor!", progress = nil, completion = "Ihr glaubt ja nicht, wie froh ich bin, Euch beide zu sehen! Mir steigen gleich die Tränen in die Augen... Augen, die zu lange durch eine Banshee blicken mussten.\n\nTut mir leid, dass ich Euch so viel Ärger bereitet habe. Bringt Ihr mich zurück zur Karawane?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27527] = {title = "Ende der Reise", objective = "Sprecht mit Fiona an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nBereitgestellter Gegenstand: \n", description = "Ich halte die Luft an diesem Ort nicht mehr aus. Der Gestank der Untoten ist schon schlimm genug, aber wenn man dem noch Pilze hinzufügt? Ich hasse Pilze!!\n\nIch werde zur Kapelle des Hoffnungsvollen Lichts zurückkehren, <Name>... und ich nehme Tarenar und Fiona mit. Wir alle haben eine Pause verdient. \n\nHier, nehmt das. Das ist mein Ruhestein - mit ihm könnt Ihr Euch zur Kapelle versetzen lassen. Ich brauche ihn nicht - ich reise auf dem Wagen.\n\nUnd zwar auf dem VORDERSITZ.", progress = nil, completion = "Ihr habt mit Eurer Hilfe alle Erwartungen übertroffen, &lt;Name&gt;. Die Türen meines Wagens stehen Euch stets offen.\n\nDie Jungs und ich haben sogar etwas Besonderes für Euch vorbereitet. Hier, trefft Eure Wahl!", rewards = "Fionas ArmbänderGürtel der EhrenfrauHandschuhe des Endes der ReiseAuf Euch wartet eine dieser Belohnungen:\n\nGidwins MedaillonTarenars Abzeichen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27528] = {title = "Geißelmasse", objective = "Tötet 8 überladene Golems und steckt ihre Kadaver mit der Fackel des Kreuzfahrers in Brand.", description = "Man kann die Geißel nicht einfach töten. Sie kommt zurück. Man muss die verdorbene Masse zerstören, aus denen sie besteht... und selbst dann kehren diese Unholde manchmal als Schreckgespenster zurück.\n\nNur wenige Untote bringen so viel Masse mit wie die schwerfälligen Monstrositäten. Tötet sie und verbrennt ihre Leichen. Ihr findet sie überall im Pestwald.\n\nLasst Euren Zorn nicht erkalten, <Volk>. Vergesst nicht, dass diese Monstrositäten aus den Körpern guter Leute zusammengenäht wurden. Ihre Existenz ist ein Verbrechen.", progress = nil, completion = "Ein gesegnetes Feuer reinigt sogar das verdorbenste Fleisch.\n\nIm Angesicht des Lichts hatten sie keine Chance.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27529] = {title = "Verteidiger von Darroheim", objective = "Befreit 8 Darroheimgeister aus den Körpern der Menschenfresserghule und sprecht mit ihnen.", description = "Die Schlacht von Darroheim war eine der großen Tragödien, die wir Menschen durch die Geißel erleiden mussten. Bis heute hallt sie nach.\n\nViele der mutigen Verteidiger der Stadt ziehen nun als schreckliche Diener der Geißel umher. Wir werden ihr Leid beenden.\n\nJagt Menschenfresserghule hier im Pestwald. Viele dieser Abscheulichkeiten waren einst rechtschaffene Menschen in Darroheim. Die Zerstörung ihrer Körper wird ihre Seele befreien.", progress = nil, completion = "Es ist gut zu hören, dass Ihr die gequälten Seelen meiner Brüder gefunden und befreit habt. Meine Kraft ist erneuert, nun da ich weiß, dass zumindest einige der Verteidiger von Darroheim nicht mehr länger in der widerlichen Dienerschaft der Geißel gefangen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27530] = {title = "Die Kadaverbestien", objective = "Zerstört die Hüllen dreier Kadaverbestien, indem Ihr drei oder mehr Argentumlichtbrunnen neben ihnen platziert. Ihr könnt die Argentumlichtbrunnen nicht im Kampf platzieren und nicht weniger als zehn Meter voneinander entfernt.", description = "Feige Kultisten widmen sich im Süden einer düsteren Aufgabe: Sie reanimieren gewaltige Fleischberge, um aus ihnen Riesen zu erschaffen, die Kadaverbestien genannt werden. Zum Glück für uns sind diese Riesen noch leblos und schwach.\n\nNehmt dieses Amulett - benutzt es, um einen Brunnen heiliger Energie zu erschaffen. Versucht, drei dieser Quellen in der Nähe einer der Kadaverbestien zu platzieren, die von den Kultisten reanimiert werden. Die heilige Energie sollte ausreichen, um sie zu überladen und ihren Körper für immer zu zerstören.", progress = nil, completion = "Ihr seid ein wahrer Champion des Lichts, &lt;Name&gt;. Ich wünsche Euch Glück für all Eure zukünftigen Unterfangen, wo auch immer sie Euch hinführen mögen.\n\nSolltet Ihr in Zukunft etwas benötigen, werdet Ihr mich hier finden - bis zu den Knien in den Leichen der Getöteten.", rewards = "ÜberladungsrobenLeichenbestienarmbänderBeinwickel der ErmordetenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27531] = {title = "Seuchenabwehrforschung", objective = "Beschafft 20 Faulbeeren, 5 abgetrennte Arme und 1 Stapel Fußabschabung eines Fleischgiganten.", description = "Einst habe ich als Apotheker für die sogenannte \"Bansheekönigin\" Sylvanas gearbeitet. Ich habe sie einmal bewundert, aber etwas in ihr hat sich verändert. Sie ist nicht mehr sie selbst.\n\nIch habe den Schwur, der mich an die Verlassenen band, gebrochen und trat dem Kreuzzug bei. Nun benutze ich meine Kenntnisse der Alchemie, um nach einem Wirkstoff gegen die Seuche zu suchen. Der Pestwald ist der geeignete Ort dafür.\n\nIch brauche Nachschub für einige Reagenzien, die man im Pestwald findet. Ich werde Euch für jeden Gegenstand, den Ihr findet, bezahlen.", progress = "Habt Ihr alles?", completion = "Ich liebe den Geruch von frischer Fußhornhaut, Ihr nicht auch?\n\nWenn wir ein Heilmittel für die Seuche finden wollen, müssen wir kreativ bei unseren Zutaten sein. Entschuldigt mich bitte, ich muss wieder an die Arbeit.", rewards = "Streitkolben des PestwaldesJudkins' StabFaulbeerengürtelbundZehenring eines FleischgigantenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27532] = {title = "Der Pestwaldturm", objective = "Bringt Leuchtfeuers Paket zu Erzapotheker Judkins beim Pestwaldturm in den Östlichen Pestländern.", description = "Nach den ungünstigen Entwicklungen im Fall Gidwin denke ich, ein Mann meines Alters sollte die gefährliche Reise durch den Pestwald nicht antreten. Das ist nicht schlimm - ich werde den Pestwaldturm bei meiner nächsten Rundreise besuchen.\n\nAllerdings habe ich eine Lieferung für Judkins. Ihr seid jünger als ich und kampferprobt. Würdet Ihr ihm diese Lieferung bringen?", progress = "Leuchtfeuers Paket... geht es Argus gut? Ist etwas passiert?", completion = "Puh. Jedes Mal, wenn ich Argus durch den Pestwald trotten sehe, befürchte ich, es wird das letzte Mal sein. Gut, dass er weise genug ist, ein Jungblut wie Euch zu schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27533] = {title = "Ein Schicksal schlimmer als der Schlachter", objective = "Tötet 9 verseuchte Schweine.", description = "Die Bewohner des Schreckenstals wurden zuerst krank, dann böse. Das sind wirklich keine guten Zeiten.\n\nUnd die Schweine... sie wurden ebenfalls krank! Womit haben Schweine eine solche Krankheit verdient? Hah hah hah! Nichts!\n\nDie Leute interessieren mich nicht, aber die bösen Schweine machen mich immer noch traurig. Solltet Ihr sie jedoch töten... Wäre ich vielleicht glücklich.", progress = nil, completion = "Ich sehe sie! Ihr auch? Die kleinen Schweinegeister auf dem Weg zum großen Stall im Himmel...", rewards = "Schweinslederne HandschuheArmschienen des himmlischen SchweinestallsSchulterstücke der VerwirrtenAugustus' BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27534] = {title = "Augustus' Quittungsbuch", objective = "Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal.", description = "Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es irgendwo in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, &lt;Name&gt;! Toll! Wahnsinnig gut, sage ich Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27535] = {title = "Ein bisschen meschugge", objective = "Sprecht mit Augustus dem Meschuggenen im Schreckenstal.", description = "Ich sehe gelegentlich nach Augustus im Schreckenstal, nur um sicherzustellen, dass es ihm gut geht. Manche von uns Untoten kommen wohl mit der Seuche besser klar als andere.\n\nDas Schreckenstal liegt westlich von hier. Würdet Ihr für mich nach ihm sehen?", progress = nil, completion = "Ihr seid am richtigen Ort, mein Herr! Jawoll, es gibt keinen besseren Ort als das Schreckenstal! Das Juwel von Lordaeron!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27536] = {title = "Größtenteils harmlos", objective = "Sammelt 8 entschärfte Landminen im Sorgendunkel östlich von Kraulsumpf.", description = "Hier ist noch ein Gefallen, den Ihr mir tun könnt, <alter Freund/alte Freundin>.\n\nKürzlich ist eine ganze Ladung Landminen aus Beutebucht angekommen. Aber jemand hat sie alle über Nacht gestohlen!\n\nWer immer es war, er war nicht besonders sorgfältig, denn er hat sie überall im Sumpf östlich von hier fallengelassen. Kein Goblin, der mir bekannt ist, würde so unvorsichtig sein.\n\nIch möchte, dass Ihr da rausgeht und diese Landminen für mich einsammelt. Ich bin sicher, dass sie vollkommen sicher und entschärft sind. Jede einzelne. Jawohl.", progress = "He, habt Ihr die Dinge beschaffen können, um die ich gebeten hatte?", completion = "Was hab' ich Euch gesagt, hm? Völlig harmlos!\n\nIch sorge dafür, dass ein paar dieser Dinger zu Euren Freunden geschafft werden, &lt;Name&gt;. Mit Rabatt.", rewards = "KraulsumpfgamaschenLiederliche SchiftungBewehrte StulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27537] = {title = "Wer Elementare sät, wird Sturm ernten", objective = "Tötet matschige Wasserelementare, um 5 Strudelkerne zu sammeln.", description = "Unsere Freunde des Irdenen Rings haben versucht, Portale zurück nach Sturmwind zu öffnen, aber sie hatten kein Glück. Thordun hier sagt mir jedoch, dass er vielleicht die Lösung für unser Problem hat.\n\nDie wahnsinnigen Wasserelementare im nahegelegenen Fluss Verrall sind in Raserei verfallen. Thordun sagt, dass wir ihre Energie kanalisieren können, um ein Portal zu schaffen.\n\nIch habe ja keine Ahnung von diesem Elementar-Schnickschnack, aber eines verstehe ich ganz deutlich: Elementare töten und ihren Strudelkern nehmen. Bringt sie zu Talaa im Hof!", progress = "Hallo <Klasse>. Kurdran hat mir gesagt, dass Ihr eine Lösung für unser Portalproblem habt?", completion = "Eines könnt Ihr mir glauben, &lt;Name&gt;. Diese Elementarenergien sind so mächtig, so chaotisch! Kein Wunder, dass der Schattenhammer seine Festung hier errichtet hat.\n\nIch sollte diese Energien in etwas Gutartigeres und Produktiveres umwandeln können. Probieren wir es...", rewards = "KerngriffstulpenStrudelarmschienenWasserbohrertreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27538] = {title = "Der perfekte Verband", objective = "Sammelt 10 Haufen Verrallschlamm.", description = "Geht Ihr zufällig zur Mündung des Verrall? Dann habe ich einen Rat für Euch, der Euren Männern hier sehr helfen kann… und meinem Vogel!\n\nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, entsteht ein seltsamer Schlamm. Getrocknet ist er hart wie Stein, aber er enthält die erfrischende Macht des Wassers. Wenn Ihr einen Gipsverband aus diesem Schlamm herstellt, wachsen gebrochene Knochen wieder zusammen, fest wie Eisen.\n\nBringt ein wenig von diesem Schlamm zu Talaa, der Schamanin da unten. Sie wird wissen, was damit zu tun ist!", progress = "Was höre ich da immer über diesen Verrallschlamm?", completion = "Oh… Schlamm. Ihr habt mir Schlamm gebracht?\n\nOh, dieses Zeug pulsiert ja regelrecht vor Macht! Jetzt verstehe ich, was Thordun meint. Ich werde ihn an all unsere Heiler verteilen. Unsere Verwundeten werden im Handumdrehen wieder auf den Beinen sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27539] = {title = "Werft sie auf den Haufen", objective = "Beschafft 16 stinkende Schädel von verfluchten Magiern und Soldaten der Geißel im Pestwald.", description = "Ich sammle die Köpfe der Skelette, die ich besiege. Ich habe schon einen kleinen Haufen zusammen.\n\nSolltet Ihr zufällig Schädel finden, könnt Ihr sie gern dazu legen. Der Schädelhaufen scheint die Wellen der Untoten zurückzuhalten und... na ja... ich betrachte ihn auch sehr gern.", progress = "Ihr seid ja ziemlich beladen. Sind das etwa Schädel?", completion = "Möge mein Haufen immer weiter wachsen.", rewards = "Schiftung der letzten RuheStinkschädelstreitkolbenGürtel des SammlersUmhang des HortensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27541] = {title = "Lektionen der Vergangenheit", objective = "Erhaltet die zerbrochene Brille.", description = "Dieser unglückliche Forscher hat offensichtlich in letzter Zeit ziemliches Pech gehabt.\n\nDie Vernunft gebietet, dass Ihr die Leiche auf Hinweise durchsucht. Darum wird Euch niemand beneiden, aber wir brauchen Hinweise, die Licht in unsere Umgebung bringen...", progress = "Gibt es Neuigkeiten, <Name>?", completion = "Seltsam...\n\nSieht so aus, als ob jemand Edelsteine als Linsen benutzt hat.\n\nIch sollte sie ohne großen Aufwand reparieren können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Mod Aura Vision\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27542] = {title = "An die Front", objective = "Die Stunde des Sieges rückt näher, <Name>. Godfrey hat einen Plan geschmiedet, um unsere Feinde zu dezimieren. Ich schicke Euch mit ihm und seinen Männern ins Feld, um die rebellischen Aufrührer in die Knie zu zwingen und das Schicksal des Allianzabschaums zu besiegeln, der unsere Ländereien bedroht.\n\nUnser letzter Marsch beginnt, sobald Ihr bereit seid.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27543] = {title = "Was wir getan haben", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27544] = {title = "Cenarische Hartnäckigkeit", objective = "Sprecht mit Rayne nahe des Eingangs zum Fungustal.", description = "Ich glaube, diese Druiden geben nie auf. Ich habe die Pestländer schon vor Jahren aufgegeben, aber diese Optimisten vom Zirkel des Cenarius behaupten, es gäbe noch Hoffnung für dieses Land.\n\nDie letzte Besucherin war eine Nachtelfe, die auf dem Weg nach Norden, ins Fungustal, war. Sie sagte, diese Länder würden sich vollständig erholen, wenn wir uns nur Mühe geben. Ich weiß nicht, ob ich das glauben soll.\n\nGlaubt Ihr diesen Unsinn?! Vielleicht solltet Ihr einmal mit ihr reden. Sie müsste immer noch dort oben sein.", progress = nil, completion = "Wenn Ihr mich finden konntet, sollte ich wohl an meiner Verstohlenheit arbeiten.\n\nWollt Ihr mir bei der Heilung der Pestländer helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27545] = {title = "Der Weg ist geöffnet", objective = "Sprecht mit Kurdran Wildhammer in Hochstade im Schattenhochland.", description = "Mein Schamanenfreund und ich werden hier bleiben, um das Portal aufrechtzuerhalten.\n\nIhr solltet nach oben gehen und Kurdran benachrichtigen, dass unsere Arbeit hier erledigt ist. Es wird ihn freuen, zur Abwechslung mal gute Nachrichten zu hören.", progress = nil, completion = "Ha! Ich wusste, dass Ihr ein &lt;Klasse&gt; seid, auf den ich mich verlassen kann, &lt;Name&gt;. Ihr könnt das Portal jederzeit benutzen, um von Sturmwind zurück ins Schattenhochland zu gelangen.\n\nUnd jetzt zum Geschäft. Wir müssen die verschollenen Wildhammerklans, die überall im Schattenhochland verstreut sind, finden und vereinen. Am besten sprecht Ihr zunächst mit Thordun hier!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27547] = {title = "Folgenlos", objective = "Rettet 8 kauernde Soldaten.", description = "Unsere Streitkräfte in Lohenscheit wurden vor Kurzem durch einen Schleichangriff überrascht. Die 7. Legion hat es geschafft, ihre Späher in die Stadt einzuschleusen und schließlich unsere Truppen zu dezimieren.\n\nDie Dunkle Fürstin hat uns mit einer Rettungsmission beauftragt. Wir sollen Überlebende finden und sie sicher aus Lohenscheit herausbringen. Wenn noch Soldaten am Leben sind, so sind sie wahrscheinlich nutzlos, aber wir werden das tun, was die Dunkle Fürstin befiehlt.\n\nLasst uns diesen Unsinn hinter uns bringen, <Name>. Lohenscheit ist direkt im Südwesten der Frontlinie der Verlassenen.", progress = nil, completion = "Was heute hier geschehen ist, bleibt unter uns. Nur ein Wort zu irgendjemandem und Ihr findet Euch in einer Leichengrube neben diesen armen Narren wieder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27548] = {title = "Lehrstunden in Angst", objective = "Tötet 12 Späher der 7. Legion.", description = "Unsere Feinde werden immer schlauer und passen sich an unsere Strategien an. Erst vor Kurzem wurde Lohenscheit im Südwesten von hier angegriffen. Unsere Streitkräfte, die die Stadt besetzt halten, wurden natürlich dezimiert, aber was den Angriff besonders interessant macht, war die Völkerzusammensetzung der angreifenden Truppe. Es gab keine Menschen.\n\n<Walden lacht.>\n\nSie fürchten sich zu Recht davor, als Verlassene wiedererweckt zu werden.\n\nLasst uns den Nicht-Menschen eine Lektion in Angst erteilen. Zusammen werden wir ihnen zeigen, was mit Leichen geschieht, für die wir keine Verwendung haben.", progress = nil, completion = "Ich nehme an, dass wir jetzt weniger Menschen an der Schlachtenfront sehen werden. Das Risiko für diese Feiglinge ist zu groß.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27549] = {title = "Bei Sternenlicht", objective = "Sammelt 7 schwebende Sternenlichter.", description = "Schaut Euch das an, <Name>.\n\n<Harrison hält die Brille des toten Spähers hoch.>\n\nIch habe die Klammer in der Mitte angezogen und die Drähte an den Kanten etwas gezwirbelt. Sie mag nicht bequem sein, aber sie sollte halten.\n\nWenn ich Eure Schrifttafeln richtig übersetzt habe, ist hier etwas versteckt - ein letztes Teil für unser Puzzle.\n\nIch hoffe, Eure Brille birgt den Schlüssel.\n\nLasst mich wissen, was Ihr findet!", progress = "Und?\n\nHabt Ihr etwas Interessantes gefunden?", completion = "Nun, mein Junge, es sieht so aus, als ob Ihr es wieder geschafft habt.\n\n&lt;Harrison zeigt auf ein Bild auf den Schrifttafeln.&gt;\n\nDieses Sternenlicht ist genau das, was gefehlt hat.\n\nJetzt können wir an die Arbeit gehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nOn To Something Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27550] = {title = "Lohenscheits Fall", objective = "Benutzt das Bündel Fackeln, um das Rathaus von Lohenscheit, das Gasthaus von Lohenscheit und die Kapelle von Lohenscheit niederzubrennen.", description = "Die Angriffe gegen unsere Front sind ein Ablenkungsmanöver. Da unsere Aufmerksamkeit dem Ansturm der Worgen galt, hat die Allianz es geschafft, Lohenscheit von unseren Besatzungstruppen zurückzuerobern.\n\n<Godfrey übergibt Euch ein Bündel Fackeln.>\n\nEs muss ausgelöscht werden.\n\nMit diesen Fackeln werden wir Lohenscheit bis auf die Grundmauern niederbrennen und nur Asche für den Feind hinterlassen, hinter der er sich verstecken kann.\n\nLasst uns keine weitere Minute vergeuden. Lohenscheit liegt südwestlich der Frontlinie der Verlassenen. Führt uns dorthin, <Name>.", progress = "Ich spüre keine Reue.", completion = "Der Teil von mir, der aus Gilneas stammte, starb an der Witterfront. Es bleibt nur Rache, &lt;Name&gt;. Und in der Hinsicht haben wir noch einiges zu tun. Erspart mir Eure sinnlosen Fragen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDetect: Quest Invis Zone 16\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27551] = {title = "Das Schreiben der Baroness", objective = "Bringt Tarenar das Schreiben der Baroness.", description = "Die Notiz stammt von Baroness Anastari. Darin beschreibt sie ein Ritual, das sehr bald auf dem mittleren Schlachthaus im Pestwald abgehalten werden soll - etwas südlich von Tarenars Aufenthaltsort. Vielleicht halten sie dort Gidwin fest!\n\nTarenar muss davon erfahren... und zwar rasch, bevor es zu spät ist!", progress = "Was? Habt Ihr etwas gefunden?", completion = "Das ist es! Wenn das, was in dem Schreiben steht, stimmt, dann ist er auf der anderen Seite des Hügels!\n\nWorauf warten wir noch, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27555] = {title = "Fionas Glücksbringer", objective = "Fiona hat ein paar ihrer Glücksbringer im Karawanenwagen gelassen.\n\nAls Händlerin kann sie ziemlich gut mit Geld umgehen. Vielleicht könnt Ihr Eure Finanzen verbessern, wenn Ihr einen ihrer Glücksbringer tragt.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nFionas Glücksbringer"}
MultiLanguageQuestData['de'][27556] = {title = "Gidwins Waffenöl", objective = "Gidwin hat einige Flaschen Waffenöl im Karawanenwagen zurückgelassen.\n\nEr scheint im Nahkampf ein recht wilder Gegner zu sein. Vielleicht wird Euch sein Waffenöl ebenfalls gute Dienste leisten.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nGidwins Waffenöl"}
MultiLanguageQuestData['de'][27557] = {title = "Tarenars Talisman", objective = "Tarenar hat einige heilige Talismane im Karawanenwagen ausgelegt. Sie wirken unbenutzt.\n\nSie scheinen magischer Natur zu sein. Wenn Tarenar sie nicht benutzt, könnte es doch nicht schaden, sich einen für eine Weile auszuleihen, oder?", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nTarenars Talisman"}
MultiLanguageQuestData['de'][27558] = {title = "Pamelas Puppe", objective = "Ihr findet eine kleine Puppe in der hinteren Ecke des Karawanenwagens.\n\nTarenar sagt, sie gehöre Gidwin und Gidwin sagt, es wäre wahrscheinlich Tarenars.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nPamelas Puppe"}
MultiLanguageQuestData['de'][27559] = {title = "Vex'tuls Armbinden", objective = "Vex'tul hat einige Armbinden im Karawanenwagen zurückgelassen. Er war sogar so freundlich, sie zu falten und separat von den Habseligkeiten aller anderen aufzubewahren.\n\nVex'tul schätzt Stärke mehr als alles andere. Als Ihr Euch vorbeugt, spürt Ihr Überreste seiner Kraft, die aus den Armbinden strömt.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nVex'tuls Armbinden"}
MultiLanguageQuestData['de'][27560] = {title = "Argus' Tagebuch", objective = "Ihr entdeckt ein verwittertes Tagebuch im Karawanenwagen. Das Emblem des Argentumkreuzzugs auf dem Buchrücken weist darauf hin, dass es Argus gehört.\n\nIn dem Tagebuch hat Argus einige seiner Erfahrungen während seiner Zeit beim Kreuzzug niedergeschrieben. Es sollte Euch interessanten Lesestoff auf der Reise bieten.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nArgus' Tagebuch"}
MultiLanguageQuestData['de'][27561] = {title = "Rimblats Stein", objective = "Euch fällt ein kleiner Steinhaufen im Karawanenwagen auf.\n\nDie Steine wirken nicht ungewöhnlich, doch einer erregt Eure Aufmerksamkeit. Ihr spürt die Wärme, die von ihm ausgeht.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nRimblats Stein"}
MultiLanguageQuestData['de'][27562] = {title = "Beezils Zahnrad", objective = "Beezil fühlt sich anscheinend schon wie zuhause. Er hat mehrere seltsame Apparate in den Karawanenwagen gestopft.\n\nDie meisten erscheinen Euch zu unpraktisch oder gefährlich, um sie mitzunehmen. Ein kleines Zahnrad sieht jedoch recht gut verarbeitet aus.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nBeezils Zahnrad"}
MultiLanguageQuestData['de'][27564] = {title = "Verteidigt das Refugium", objective = "Sprecht mit Calen im Zinnoberrefugium.", description = "Calen hat uns benachrichtigt. Der Schattenhammer ist in das Refugium eingedrungen!\n\nWenn Ihr nach einer Gelegenheit sucht, um seine Gunst zu erlangen, dann ist dies der rechte Zeitpunkt!", progress = nil, completion = "Ich hoffe, dass Ihr so hart im Nehmen seid, wie Eure Ausrüstung es verspricht. Der Schattenhammer hat irgendwie einen Weg in das Refugium gefunden. Ich brauche jemanden, der sie zur Strecke bringt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27565] = {title = "Ins Gefängnis", objective = "Findet Kevin Dawson.", description = "Es ist uns gelungen, jemand in das Gefängnis der Dunkeleisenzwerge einzuschleusen.\n\nAlso... es ist uns möglicherweise gelungen.\n\nKevin Dawson hatte die... Ehre... nachzusehen, was dort drüben vor sich geht. Doch seitdem haben wir nichts mehr von ihm gehört. Ihr seht so aus, als ob Ihr nicht gerne sterbt. Ihr solltet nachschauen gehen, ob er in Ordnung ist!\n\nEr sollte eigentlich in der Halle am südlichen Ende der Höhle vor uns sein... Doch etwas sagt mir, dass er es vielleicht nicht bis dahin geschafft hat.", progress = nil, completion = "Ich habe keine Ahnung, wieso ich noch am Leben bin. Die Patrouillen laufen an mir vorbei, als ob ich gar nicht hier wäre.\n\n...Bin ich tot, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27567] = {title = "Schattenhammer?! Nein!", objective = "\"Verhört\" Verhörmeisterin Gerstahn.", description = "Es ist zwar schwer zu glauben, aber es gibt Mitglieder des Schattenhammers hier in den Schwarzfelstiefen! Ich weiß nicht, wie viele von ihnen durch diesen Ort kriechen, aber ich habe gehört, dass Ihre Verhörmeisterin Gerstahn in dieser Halle ist.\n\nIch weiß nicht, warum sie hier foltern, aber vielleicht könnt Ihr es herausfiniden, indem Ihr Gerstahn entgegentretet?", progress = nil, completion = "Hmm... wie ich sehe, war sie nicht hilfsbereit. Hoffentlich können wir sie noch aufhalten, bevor etwas Furchtbares geschieht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27568] = {title = "Schattenschmiede unterwandern", objective = "Sprecht mit Ausgrabungsleiter Seymour.", description = "Könnt Ihr ein Geheimnis für Euch behalten? Ich hab' ein Geheimnis, das ich mit Euch teilen will.\n\nHier sind alle VERRÜCKT!!!\n\nDa drüben sind Goblins, dort sind Dunkeleisenzwerge und ein riesiges lebendes Feuer hinter dem Tor da! Und das ist nur das, was ich in dieser kleinen Höhle sehe!\n\nUnd Euch! Was macht Ihr hier?\n\nAh, ich verstehe. Winky hat Euch geschickt, nicht wahr? Hat Euch geschickt, um mit Ausgrabungsleiter Seymour zu sprechen, der hinter diesem Tor gleich rechts ist, nicht wahr? Dann geht! Oralius kümmert das nicht!\n\n...DAS WERDE ICH DIR HEIMZAHLEN WINKY!!!\n\n<Oralius fängt an zu schluchzen.>", progress = nil, completion = "Ich würde mich von Oralius fern halten. Sehr, sehr weit fern halten. Er ist nicht ganz richtig im Kopf.\n\nAber zurück zum Geschäft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27569] = {title = "Strategen der Dunkeleisenzwerge", objective = "Tötet General Zornesschmied und Golemlord Argelmach.", description = "General Zornesschmied und Golemlord Argelmach führen die Armeen der Dunkeleisenzwerge und ihre Golems gegen uns. Wenn wir sie überwinden wollen, müssen die beiden getötet werden.\n\nGeht durch diese Tür und schließt das Schloss der Schattenschmiede auf, die die Ost- und Westgarnisonen trennt. Dann folgt der Treppe und haltet Euch oben links, bis Ihr die Westgarnison erreicht. Dort findet Ihr den General und den Golemlord.\n\nBleibt immer wachsam, da beide äußerst erfahrene Kämpfer sind. Wenn Ihr erfolgreich seid, sucht Mayara Wolkenglanz.", progress = nil, completion = "Ich bin sicher, dass Ihr der Aufgabe gewachsen seid, die ich für Euch habe, wenn Ihr es unversehrt bis hierher geschafft habt.\n\n&lt;Mayara Wolkenglanz flüstert ganz leise.&gt;\n\nUnter uns gesagt - Ihr solltet Euch während Eures Aufenthaltes hier ein wenig im \"Grimmigen Säufer\" vergnügen. Es könnte Euer letztes Getränk sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27571] = {title = "Der Grimmige Säufer", objective = "Kämpft gegen Hurley Pestatem, Stöpsel Zapfring und Ribbly Schraubstutz.", description = "Es gibt Stimmen, die behaupten, dass der \"Grimmige Säufer\" das Geheimnis der Kriegsanstrengungen der Dunkeleisenzwerge ist. Ihre Krieger erholen sich dort und kommen durstig nach einer weiteren unschuldigen Seele wieder heraus. Ich glaube, wir können sie erheblich behindern, indem wir dort ein wenig Chaos anrichten.\n\nIhr müsst einen Streit mit drei der berüchtigten Stammkunden anfangen. Beschädigt die Fässer und Hurley Pestatem wird herbeieilen. Stehlt die Gegenstände vom Tisch in der Nähe von Stöpsel Zapfring und er wird kämpfen. Was Ribbly Schraubstutz angeht - mit dem Hitzkopf müsst Ihr nur reden. Meldet Euch bei Orfus, wenn Ihr fertig seid.", progress = "Beeilt Euch bitte. Zeit ist ein Luxus, den wir nicht haben.", completion = "Die Dunkeleisenzwerge haben unser Donnerbräu gestohlen. Nach dieser Tat kann ich sie nicht am Leben lassen. Wenn ich könnte, würde ich sie alle höchstpersönlich töten!\n\nWenn Ihr allerdings nach vorne schaut, werdet Ihr sehen, dass wir uns im Moment um dringendere Dinge zu kümmern haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27573] = {title = "Pakt mit den Dunkeleisenzwergen", objective = "Tötet Botschafter Flammenschlag und Un'rel.", description = "Vor uns befindet sich die Kreatur, die nur als Botschafter Flammenschlag bekannt ist. Er ist der Botschafter von Ragnaros dem Feuerlord und vertritt ihn beim Volk der Dunkeleisenzwerge. Jenseits dieser Kammer befindet sich die Gruft der Beschwörer. Dort sind die Geister der sieben Patriarchen der Dunkeleisenzwerge zu Hause, die Ragnaros in unsere Welt gerufen haben.\n\nMöglicherweise habt Ihr noch nichts von dem großen Feuer gehört, aber er bedeutet das Ende für Azeroth, wenn er nicht aufgehalten wird. Diese Individuen stehen in direkter Verbindung zu der Macht, die er über die Dunkeleisenzwerge hat. Tötet sie, damit dieses Volk eines Tages vielleicht rehabilitiert werden kann.", progress = nil, completion = "Ich kann alleine nicht weitermachen, egal, wie viel Kampferfahrung ich habe. Das Lyzeum hat sich als zu schwer für mich erwiesen. Doch da Ihr hier seid... Ihr könntet der Schlüssel zu all dem hier sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27574] = {title = "Ich vergesse nie ein Gesicht", objective = "Übergebt den teilweise verdauten Kopf an Lord Godfrey im Silberwald.", description = "Ihr habt einen teilweise verdauten Kopf gefunden. Lord Godfrey wird aufmerksam, als er ihn sieht. Vielleicht solltet Ihr ihm den Kopf geben.", progress = "Ich vergesse nie ein Gesicht!", completion = "Das Gesicht kenne ich, &lt;Name&gt;. Dieser Kopf gehört einem ehemaligen Bewohner von Gilneas mit Namen Sean Dempsey. Er wurde vor dem großen Ausbruch von Crowley gefangen genommen.\n\n\n\nIch frage mich, ob es möglich wäre, ihn wieder zusammenzusetzen. Der Rest von ihm muss sich in den Bäuchen dieser Krokilisken befinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27575] = {title = "Aus dem Bauch der Bestie", objective = "Findet Dempseys Torso, Dempseys Gliedmaßen und Dempseys Eingeweide.", description = "Ich glaube, dass wir ihn wiederherstellen können. Wenn es uns gelingt, ihn wieder zusammenzusetzen, kann er uns vielleicht Informationen über Crowley geben.\n\nWir müssen jeden Krokilisken im Sumpf töten, bis wir den Rest von Sean Dempseys Leiche gefunden haben. Aus dem Bauch des Ungeheuers wird dieser Mensch wiedergeboren!", progress = "Wenigstens werden wir einige Krokiliskenbälge bekommen, um hübsche Schuhe daraus zu fertigen.", completion = "Sehen wir mal, ob ich das schaffe.\n\n&lt;Godfrey murmelt leise etwas vor sich hin.&gt;\n\n...Schienbein gehört an den Oberschenkelknochen...\n\n...Oberarm an den Torso...\n\n...mit ein wenig Nekromantie der Verlassenen garnieren...\n\nTA-TAAA!", rewards = "Weste der VerlassenennekromantieArmschienen des Eine-Million-Gold-MannesBeinknochenbedeckungDer folgende Zauber wird auf euch gewirkt:\n\nSummon Dempsey\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27576] = {title = "Flickwerkbefehle", objective = "Sprecht mit Flick im Drachenmalpass.", description = "Die kürzlichen Ereignisse machen mehr als deutlich, dass sich hier zu verkriechen und ab und zu einmal Grim Batol anzugreifen weder ausreicht, um Unsereins zu beschützen, noch um Grim Batol zurückzuerobern. Wir müssen aggressiver vorgehen und sie direkt ins Herz treffen.\n\nIch habe mich bereit erklärt, ein paar Drachen zur Unterstützung Eurer Kommandanten zu schicken. Sie waren bereits dabei, einen Angriffsplan für Grim Batol zu schmieden, also solltet Ihr Euch zunächst darauf konzentrieren.\n\nSucht nach Flick am Drachenmalpass, südlich in der Schlucht unter uns.", progress = nil, completion = "Ihr habt die Drachen mit ins Spiel gebracht! Gut gemacht.\n\nUnsere Pläne waren bereits geschmiedet, als wir von den Drachen gehört haben. Sie helfen uns, indem sie die Rückzugrouten des Feindes abschneiden.\n\nEs ist noch nicht zu spät für Euch, an dem Spaß teilzuhaben. Wir haben ein Bisschen für Euch aufgehoben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27577] = {title = "Schlachtpläne der 7. Legion", objective = "Besorgt Euch den Schlachtplan der 7. Legion.", description = "Lohenscheit zu vernichten verschafft uns auf dem Schlachtfeld sicher einen Vorteil gegenüber der Allianz, doch unser wahres Ziel hier ist es, sie geschlagen zurückzulassen.\n\nSüdwestlich von hier, in der Nähe des Graumähnenwalls, liegt das Basislager der 7. Legion. Wir müssen dieses Basislager nach Schlachtplänen durchsuchen. Mit den Schlachtplänen der 7. Legion können wir die Truppenbewegung der Allianz im Silberwald genau nachverfolgen.", progress = "Durchsucht jeden ranzigen Zwergenleichnam.", completion = "&lt;Walden überfliegt den Schlachtplan.&gt;\n\nSieht aus, als setzte die Verstärkung von den Schiffen in Gilneas sich bald in Bewegung. Crowley und Blutfang haben im Südosten ein Lager der Gilnearischen Befreiungsfront eingerichtet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27578] = {title = "Morgans Verwirklichung", objective = "Tötet Imperator Dagran Thaurissan.", description = "Imperator Dagran Thaurissan übt von seinem Thron vor uns die absolute Kontrolle über die Stadt aus.. Wenn wir seine Armeen aufhalten wollen, müssen wir die Herrschaft des Imperators beenden.\n\nIhr müsst an seiner Leibwache - einschließlich des riesigen Magmus - vorbei, um an ihn heranzukommen. Bewegt Euch so schnell wie möglich. Wenn sich die Nachricht verbreitet, bevor Ihr fertig seid, wird die ganze Stadt zu seinem Thron eilen.\n\nDenkt daran, die Türen im Lyzeum öffnen sich nur, wenn Ihr die Kohlenpfannen mit Fackeln der Flammenbewahrer angezündet habt. Viel Glück.", progress = nil, completion = "Ihr habt es geschafft! Ihr habt es wirklich geschafft! All die Jahre, die Morgan Pläne geschmiedet und gewartet hat, haben endlich Früchte getragen.\n\nSie hat zwar ihr Land und ihre Familie verloren, als Ragnaros das Land entzwei riss, aber jetzt, da die Dunkeleisenzwerge angeschlagen sind, werden wir gefahrlos ein neues Königreich in der Brennenden Steppe aufbauen können. Nicht einmal der Feuerlord selbst wird in der Lage sein, die Mauern der Hauptstadt zu durchbrechen!\n\nIhr müsst unbedingt eines Tages, wenn wir fertig sind, zurückkommen. Ihr werdet unser höchster Ehrengast sein. Ich danke Euch von ganzem Herzen, &lt;Name&gt;.", rewards = "Thaurissans BrustplatteMaxwells UmhangAuf Euch wartet eine dieser Belohnungen:\n\nDunkeleisenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27579] = {title = "Ins Gefängnis", objective = "Findet Lexlort.", description = "Der Schattenhammer wird 'nen Grund für seine Anwesenheit hier haben. Wir ha'm keine Ahnung, wieso, aber Thal'trak verrät Euch eins unserer kleinen Geheimnisse: Der Schurke Lexlort wartet vor der Halle von Verhörmeisterin Gerstahn, um sie abzumurksen, wenn er 'ne Chance dazu bekommt.\n\nSie is' aber zu clever dafür, als müsst Ihr da reingehen un' das erledigen, ya? Geht und sprecht mit Lexlort und sagt ihm Bescheid. Ich bin sicher, er wird damit einverstanden sein.", progress = nil, completion = "Kommt hier rüber. Wenn Ihr meine Tarnung auffliegen lasst, dann schwöre ich beim Kriegshäuptling, dass ich Euch auf der Stelle töten werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27580] = {title = "Unfrieden säen", objective = "Ermordet General Marstein.", description = "Die Verstärkung der Allianz hat eine Stellung in der südwestlichen Region des Silberwalds etabliert - das Basislager der 7. Legion. Für uns hat es oberste Priorität, in diesem Basislager Unfrieden unter den Truppen zu säen. Die Mission ist ein blitzschnelles Attentat auf ihren Feldkommandanten, General Marstein. Sein Tod wird den Vormarsch der Allianz nicht aufhalten, aber er wird ihre Ränge aufweichen.", progress = nil, completion = "Der Rest der Allianzflotte wird bald eintreffen und ihr Basislager dezimiert vorfinden. Und jetzt kommen wir zum zweiten und wichtigsten Teil unseres Schlachtplans.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27581] = {title = "Schattenhammer?! Nein!", objective = "Tötet Verhörmeisterin Gerstahn.", description = "Gerstahn ist viel zu schwer bewacht. Außerdem ist sie viel zu schlau, um ihren Posten zu verlassen. Also werde ich sie nicht töten.\n\nIhr werdet es tun.\n\nIch werfe auch noch etwas, das ich einer Wache abgenommen habe, mit in die Waagschale, damit es die Mühe für Euch wert ist.", progress = nil, completion = "Die Anwesenheit des Schattenhammers macht unsere Aufgabe hier nur noch komplizierter. Doch Ihr habt Euren Teil für den Moment getan. Ihr habt eine Belohnung für Eure Bemühungen verdient... und ein wenig Ruhe. Lasst uns hier verschwinden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27582] = {title = "Schattenschmiede unterwandern", objective = "Sprecht mit Razal'hieb.", description = "Ich fürchte, wir kämpfen momentan auf verlorenem Posten. Es wäre schon schwierig genug, die Dunkeleisenzwerge allein zu besiegen, aber ihre Elementarverbündeten haben ihnen nagelneue Krieger verschafft, mit denen wir nicht mithalten können.\n\nIhr müsst uns helfen, ihren Bereich zu infiltrieren und so viele ihrer wichtigen Anführer wie möglich zu töten. Das wird hoffentlich ihren Streitkräften einen Schock versetzen und das Blatt zu unseren Gunsten wenden. Meldet Euch bei Razal'hieb für weitere Anweisungen. Er ist jenseits dieses Tors auf der rechten Seite stationiert.", progress = nil, completion = "Hinter dieser Tür liegt der Kommandant der Armee der Dunkeleisenzwerge, umgeben von ausgebildeten Soldaten. Fühlt Ihr Euch gerüstet für ein kleines Gemetzel?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27583] = {title = "Die nördliche Flanke", objective = "Meldet Euch bei Gralok in der Wuchernden Bucht im Schattenhochland.", description = "Ich habe befohlen, dass ein Verteidigungsring an unserer nördlichen Küste bei der Wuchernden Bucht eingerichtet wird. Unsere Späher berichten, dass die Naga versucht haben, dort an Land zu gehen.\n\nGralok hat das Kommando über diese Operation. Meldet Euch bei ihm und sichert den Strand!", progress = nil, completion = "Kriegsfürstin Zaela hat Euch geschickt? Gut.\n\nWenn Ihr von der Horde so stark seid, wie Eurer Kriegshäuptling behauptet, erwarte ich Unmengen vergossenen Blutes auf diesen Ufern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27584] = {title = "Blutrote Brandung", objective = "Tötet eine beliebige Kombination aus 15 Plünderern der Schwarzschuppen oder Herrinnen der Schwarzschuppen.", description = "Dieser Nagaabschaum hat vor, den Fluss nach oben zu ziehen, um die Bastion des Zwielichts zu verstärken. Wir werden ihnen die Fischköpfe ABREISSEN und ihnen die GRÄTEN ZIEHEN.\n\n<Gralok rammt sein Breitschwert in den Boden.>\n\nVernichtet die Schwarzschuppen!", progress = nil, completion = "&lt;Garlok mustert Euch.&gt;\n\nIhr seid eine echte Kämpfernatur, &lt;Name&gt;. Ich habe es genossen, Euch bei der Arbeit zu beobachten. Vielleicht gehört das Drachenmal ja doch zu Eurer Horde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27585] = {title = "Die 109te Division", objective = "Tötet General Zornesschmied und Golemlord Argelmach.", description = "General Zornesschmied und Golemlord Argelmach sind direkt verantwortlich für das grässliche Abschlachten der 109ten Division des Kargath Expeditionskorps. In dieser Division waren eine Menge guter Trolle und Orcs - viele davon waren enge Freunde von mir.\n\nNun <junger/junge:r> <Volk>, es ist an der Zeit, unsere gefallenen Brüder endlich zu rächen.\n\nSchließt das Schloss der Schattenschmiede auf, dann folgt der Treppe und haltet Euch oben links, bis Ihr die Westgarnison erreicht. Tötet Zornesschmied und Argelmach und wagt es ja nicht, einem von ihnen Gnade zu erweisen.", progress = nil, completion = "Genau vor uns liegt der \"Grimimge Säufer\". Eine schäbige Bar gefüllt mit unseren Feinden, die volltrunken und daher unfähig sind, zu kämpfen.\n\n&lt;Hierophantin Theodora Mulvadania grinst.&gt;\n\nReif zum Schlachten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27586] = {title = "Bombiger Badestrand", objective = "Sammelt 8 Mörserblindgänger am Strand bei der Wuchernden Bucht.", description = "Ich konnte diese Mörser aus unserem Luftschiff retten, als es über dem Hafen des Drachenmals explodierte. Doch Munition ist knapp.\n\nWährend Ihr am Strand entlang lauft, tut mir den Gefallen und sammelt alle Mörserblindgänger ein, die Ihr finden könnt.\n\nBlindgänger mag ich am allerliebsten. Man weiß nie, WANN sie losgehen. Die perfekte Überraschung für einen Feind.", progress = "Habt Ihr die Blindgänger? Gebt sie mir!\n\n… Vorsichtig!", completion = "Oh ja. JA! Damit können wir ganz sicher jemanden erledigen.\n\nWahrscheinlich ein paar Naga.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27587] = {title = "Unverschämt lecker", objective = "Besorgt 6 intakte Makruraschwänze von Sumpfstrandmakruras.", description = "Wisst Ihr, ich habe hier ein Problem, bei dem Ihr mir vielleicht helfen könntet.\n\nNun, zusätzlich zu meinen Waffengeschäften, die ich hier verfolge, versuche ich, hier in Kraulsumpf ein wenig Unterhaltung aufleben zu lassen. Anscheinend gibt es ein paar dieser Makruradinger in den nördlichen Gewässern, denen unsere wilden Strandpartys nicht in den Kram passen.\n\nJetzt sind sie die Angeschmierten. Ich lasse mich doch nicht von riesigen Hummern herumschubsen - sie werden meine nächste Einkommensquelle sein! Bringt mir einige ihrer Schwänze und wir schlagen aus dem Problem unseren Profit.", progress = "Habt Ihr die Schwänze? Versucht nicht, mir kaputte anzudrehen!", completion = "Ich sehe es schon vor mir: unsere eigenen, berühmten Kraulsumpfer Hummercracker! Frisch aus dem Meer! Oh, es ist, als ob sich das von ganz alleine schreibt...\n\nIch weiß Eure Hilfe sehr zu schätzen, mein Freund. Ich werde sehen, ob ich für Eure Leute besonders günstige Konditionen machen kann, ok?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27588] = {title = "Befehlt den Angriff", objective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr unseren Truppen signalisieren, dass sie angreifen können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27589] = {title = "Der Grimmige Säufer", objective = "Findet Hurley Pestatem, Stöpsel Zapfring und Ribbly Schraubstutz.", description = "Jeder im \"Grimmigen Säufer\" ist vollkommen betrunken und deshalb leicht zu verärgern. Ich glaube, wir können die Dunkeleisenzwerge ernsthaft behindern, indem wir hier ein wenig Chaos stiften.\n\nIhr müsst einen Streit mit drei der berüchtigten Stammkunden vom Zaun brechen. Beschädigt die Fässer und Hurley Pestatem wird herbeieilen. Stehlt die Gegenstände vom Tisch in der Nähe von Stöpsel Zapfring und er wird kämpfen. Was Ribbly Schraubstutz angeht - mit dem Hitzkopf müsst Ihr nur reden. Meldet Euch bei Donnerherz, wenn Ihr fertig seid.", progress = nil, completion = "Ich höre ziemlichen Tumult im \"Grimimgen Säufer\". Wie ich sehe, habt Ihr schwer gearbeitet.\n\nWenn Ihr jetzt Eure Aufmerksamkeit auf die mir gegenüberliegende Seite richtet, werdet Ihr bemerken, dass wir uns um wichtigere Dinge sorgen müssen, als mit Betrunkenen Spielchen zu spielen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27590] = {title = "Befehlt den Angriff", objective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr unseren Truppen signalisieren, dass sie angreifen können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27591] = {title = "Pakt mit den Dunkeleisenzwergen", objective = "Tötet Botschafter Flammenschlag und Un'rel.", description = "In dieser Kammer liegt Botschafter Flammenschlag. Er ist der Botschafter von Ragnaros dem Feuerlord und vertritt ihn beim Volk der Dunkeleisenzwerge. Jenseits dieser Kammer befindet sich die Gruft der Beschwörer, Heimat der Geister der sieben Patriarchen der Dunkeleisenzwerge, die Ragnaros in unsere Welt gerufen haben.\n\nMöglicherweise habt Ihr noch nichts von dem großen Feuer gehört, aber er bedeutet das Ende für Azeroth, wenn er nicht aufgehalten wird. Diese Individuen stehen in direkter Verbindung zu der Macht, die er über die Dunkeleisenzwerge hat. Tötet sie alle und möge die unheilige Vereinigung enden.", progress = nil, completion = "Ich kann alleine nicht weitermachen, egal, wie viel Kampferfahrung ich habe. Das Lyzeum hat sich als zu schwer für mich erwiesen. Doch da Ihr hier seid... Ihr könntet der Schlüssel zu all dem hier sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27592] = {title = "Getränke \"on the rocks\"", objective = "Sammelt 10 Flaschen gestohlenen Silberschnappirinha von Schlickkriechern ein.", description = "Was geht, \"Bruder\"? Wir waren grad mitten in einer krass-spontanen Strandparty, als etwas Furchtbares passierte, \"Alter\"!\n\nIch hatte eine ganze Kiste Silberschnappirinha, das bevorzugte Getränk des Barons, bis die Schlickkriecher ihn gestohlen haben! Ich habe noch nie gesehen, dass Kriecher trinken, aber sie haben alles mit ins Wasser am Strand genommen! Wir brauchen irgendeinen großartigen Helden, der uns helfen kann, unser mit Schutzmarke versehenes Lieblingsgetränk wiederzubeschaffen.\n\n<Brono starrt Euch einen Moment lang an.>\n\nDamit meine ich Euch, \"Kumpel\"!", progress = "Habt Ihr die Ware, \"Bruder\"?", completion = "Unser eiskalter, erfrischender Silberschnappirinha! Ich kann Euch für diese vollkommen spontane Heldentat gar nicht genug danken, \"Kumpel\"! \n\nHier habt Ihr Eure eigene Flasche als total aufrichtiges Zeichen unserer Dankbarkeit! Jetzt müsst Ihr nur noch ALL EUREN FREUNDEN sagen, wie gut er schmeckt.", rewards = "StrandpartygürtelWerbemützeAbgefahrene BeinschützerMarkennamenbrustplatteSilberschnappirinha-FlaschenöffnerIhr bekommt:\n\nSilberschnappirinha"}
MultiLanguageQuestData['de'][27593] = {title = "Die Wiedergeburt des KEK", objective = "Tötet Imperator Dagran Thaurissan.", description = "Imperator Dagran Thaurissan hat die volle Kontrolle über die Stadt von seinem Thron aus, der vor uns liegt. Wenn wir seine Armeen aufhalten wollen, müssen wir die Herrschaft ihres Gebieters beenden.\n\nUm zu ihm vorzudringen, werdet Ihr seine persönliche Leibgarde überwinden müssen, einschließlich des Riesen Magmus. Bewegt Euch so schnell wie möglich - sollte jemand Alarm schlagen, bevor Ihr fertig seid, wird die gesamte Stadt zu seinem Thron strömen.\n\nDenkt auch daran, dass die Tore am anderen Ende des Lyzeums sich nur öffnen werden, wenn Ihr die Kohlenpfannen mit Fackeln von den Flammenbewahrern entzündet habt. Viel Glück.", progress = nil, completion = "Ihr seid ein &lt;Klasse&gt;, wie er im Buche steht! Ihr habt das Unmögliche vollbracht! Ich wusste, dass wir uns auf Euch verlassen können.\n\n\n\nUnd damit möchte ich Euch als Erstem bekanntgeben, dass das Expeditionskorps von Kargath offiziell wieder im Geschäft ist!\n\nIch entbiete Euch meine persönliche Dankbarkeit für Eure Bemühungen hier. Denkt immer an unser Motto: \"Die ersten drin, die letzten draußen und immer siegreich. Vergesst niemals Kargath.\"\n\nIhr dürft wegtreten.", rewards = "Umhang von KargathThaurissans BrustplatteAuf Euch wartet eine dieser Belohnungen:\n\nDunkeleisenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27594] = {title = "Im Geheimdienst Ihrer Majestät", objective = "Nehmt Kommandantin Lorna Crowley gefangen und bringt sie zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald.", description = "Lorna Crowley, Tochter von Lord Darius Crowley, befindet sich momentan im vorderen Basislager der Gilnearischen Befreiungsfront, in der Nähe des Graumähnenwalls im Südosten.\n\nUnsere oberste Priorität ist es, jemanden in das Lager einzuschleusen und sie lebend zu fangen. Die Dunkle Fürstin glaubt, dass sie Lorna als Druckmittel gegen Crowley einsetzen kann. Ich sage, wir töten sie einfach und bringen sie als eine Verlassene zurück, doch wir müssen uns den Befehlen der Dunklen Fürstin beugen.\n\nWir müssen uns beeilen, bevor der Rest der Allianzstreitkräfte eintrifft.", progress = nil, completion = "Ihr habt es geschafft! Endlich fügt sich alles zusammen. Wenn Crowley unsere Bedingungen nicht akzeptiert, wird seine Tochter umgewandelt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGunst der Dunklen FürstinLornas SiegelringWindläuferband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27595] = {title = "Der Prophet Hadassi", objective = "Findet den Propheten Hadassi in Orsis.", description = "Prophet Hadassi ist das weiseste und älteste Mitglied des Orsisstammes.\n\nWir wissen nicht, wo er sich aufhält, und sein Wohlergehen ist von immenser Bedeutung.\n\nGeht nach Orsis und findet ihn. Sollte er verletzt worden sein, wird ein großer Tag der Abrechnung über die Lakaien von Al'Akir kommen.", progress = nil, completion = "Wer... wer seid Ihr? Hierher geschickt... um mein Volk zu retten und unsere Feinde zu bekämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27596] = {title = "Das Herz des Berges", objective = "Besorgt Euch das Herz des Berges.", description = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum Schwarzen Gewölbe in der Nähe der Halle des Handwerks durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, &lt;Name&gt;, nehmt dies als Bezahlung an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27597] = {title = "Der verrückte Larry", objective = "Findet den verrückten Larry südöstlich von Kraulsumpf.", description = "Ihr habt es begriffen, <Name>. Eine Hand wäscht die andere. Um genau zu sein, wasche ich die Hände Eurer ganzen Armee, und zwar ein bisschen besser als die Hand der anderen Seite! War das zu kompliziert?\n\nIch meine damit, dass das eine Menge Hände sind. Deshalb muss ich Euch bitten, meine Hand noch ein paar Mal zu waschen. Der Dieb dieser Landminen hat wahrscheinlich gerade unsere Jungs am Ostufer erwischt.\n\nMacht Euch zu unserem Lager im Südosten auf und sprecht mit dem verrückten Larry. Er wird Euch alles erklären.", progress = nil, completion = "Silberschnapp schickt Euch?! Ich bin ERLEDIGT!\n\nOh... er hat Euch geschickt, um mir zu helfen! Das ist was anderes, haha!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27598] = {title = "Kill Gil", objective = "Tötet 7 Pirscher der Gilblins.", description = "Gilblins!\n\n<Larry starrt Euch eine Weile schweigend an.>\n\nIhr habt noch nie einen Gilblin gesehen? Sie sind verrückt! Noch verrückter als ich! Ich jage Dinge für meinen Lebensunterhalt in die Luft, aber diese Dinger sind DURCHGEKNALLT!\n\nIch habe keine Ahnung, wo sie hergekommen sind, aber sie sind wie schreckliche Fischgoblins! Mit Kiemen und allem Drum und Dran! Sie haben all meine Leute unten am Strand getötet und dann haben sie unseren Schiffsfrachter ausgeschaltet.\n\nIhr müsst helfen! Sie sind genau im Osten. Geht und schafft mir diese Gilblins vom Hals!", progress = nil, completion = "Das wird diesen fischgesichtigen Missgeburten eine Lehre sein! Gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27599] = {title = "Das letzte Hemd hat keine Taschen", objective = "Beschafft 6 Kulturbeutel von toten Freibeutern von Kraulsumpf.", description = "Alle Besatzungsmitglieder, die Ihr nicht in diesem Lager seht, sind TOT! Das waren wirklich gute Goblins, aber das Schlimmste ist, dass sie immer noch dort draußen sind! Das ist eine TRAGÖDIE!\n\nIch meine, es ist eine Tragödie, dass sie immer noch ihren ganzen Besitz haben! Schrecklich, wenn man an all die guten Materialien und Münzen denkt, die dort draußen im Wasser liegen.\n\nHey! Ihr könntet mir einen Gefallen erweisen! Wenn Ihr dort draußen Gilblins tötet, könntet Ihr die Kulturbeutel meiner ehemaligen Besatzungsmitglieder mitbringen!\n\nKommt schon, die brauchen sie doch nicht mehr! Mal ehrlich!", progress = "Habt Ihr die Kulturbeutel? Hoffentlich habt Ihr die Goblins da gelassen!", completion = "Wow!\n\nIch weiß nicht, warum ich das gesagt habe. Ich bin leicht zu begeistern! Aber seht nur, wie viel Zeug diese Jungs bei sich hatten!\n\nHier, wollt Ihr das?", rewards = "Verrückte KappeSchulterschutz des PlünderersTragische BeinschützerLarrys StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27600] = {title = "Knall auf Fall", objective = "Sprecht mit dem verrückte Jerrylein, um das Schiff zu entern. Besorgt danach die drei wertvollen Waren des verrückten Larry.", description = "Unsere Handelsfregatte ist immer noch ziemlich weit draußen auf dem Wasser umschwärmt von Gilblins! AHH!\n\nTut mir leid. Aber mal im Ernst! Wir müssen einen Weg finden, wie wir Euch dorthin befördern und unsere Sachen wiederbekommen. Auf dem Schiff befinden sich Qualitätswaren! QUALITÄT! SO WIE MEIN ZWEITER VORNAME!\n\nZu Eurem Glück habe ich eine Idee! Geht aus dem Camp hinaus und an der Nordwand entlang... Mein Sohn Jerry wird Euch mit unserer Kanone dorthinbefördern. Vorausgesetzt, er hat geübt!", progress = "Habt Ihr sie? Habt Ihr sie bekommen? Habt Ihr die Kanone ausprobiert? Ihr seid nicht explodiert!", completion = "Meine hochwertige Lunte! Mein importiertes Sprengpulver!\n\nUnd mein... ja, hallo erstmal! Ich brauche nur das!\n\nDas alles ist mehr wert, als alles Gold, das Ihr bei Euch tragt! Danke für Eure Hilfe!", rewards = "So gut wie neue SchulterpolsterTeure TunikaImportierter HelmHochwertige SchienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27601] = {title = "Städte im Staub", objective = "Begleitet Fürstin Sylvanas Windläufer auf das Schlachtfeld und besiegt die Allianz!", description = "Unsere Armeen treffen überall auf dem Schlachtfeld aufeinander. Crowley und seine Streitkräfte verlieren an Boden und wissen bisher noch nichts über das Schicksal von Lorna Crowley. Wir treffen uns mit Crowley und seinen Landsleuten in der Mitte des Feldes und ich werde ihnen die Bedingungen für ihre Kapitulation unterbreiten. Entweder, sie akzeptieren diese, oder wir werden sie alle töten und ihre Städte im Staub hinterlassen.\n\nDa Ihr mein vertrautester Soldat seid, möchte ich, dass Ihr während des Austauschs an meiner Seite steht. Sagt mir, wenn Ihr bereit seid, aufzubrechen.", progress = nil, completion = "&lt;Fürstin Sylvanas Windläufer verzerrt schmerzerfüllt das Gesicht.&gt;\n\nEs... ist noch nicht vorbei. Godfrey und seine verräterischen Verbündeten werden dafür bezahlen, was sie hier getan haben, genau wie die verbleibenden Streitkräfte der Allianz, die Lordaeron besetzt halten.\n\nUnsere Arbeit hat gerade erst begonnen.", rewards = "Pantoffeln der unveränderten LoyalitätenGürtel der AnfängeArmschienen des VertrautestenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27602] = {title = "Die Worte eines sterbenden Propheten", objective = "Findet das heilige Gefäß.", description = "Wir... sind... durch einen Eid... verpflichtet, das Zepter von Orsis zu beschützen.\n\nHört zu, <Klasse>, ich habe nicht mehr... viel Zeit.\n\nFindet das heilige Gefäß... am südlichen Ende der Stadt.\n\nLasst es... nicht in... ihre Hände fallen.", progress = nil, completion = "Die Kiste selbst ist verschlossen, aber darüber befindet sich eine Plakette mit interessanten Hieroglyphen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27603] = {title = "Das versiegelte Tor", objective = "Tötet Bael'gar.", description = "Am einen Ende der Dunkeleisenstraße findet Ihr ein massives Tor, ähnlich dem, das auf der gegenüberliegenden Seite die Schattenschmiede schützt. Wir haben jedoch keine Ahnung, was sich dahinter befindet!\n\nWir wissen nur, dass es von Patrouillen der Zorneshämmer und dem geschmolzenen Riesen Bael'gar schwer bewacht wird. Ihr müsst sie einfach nur beseitigen und schauen, ob Ihr das Tor öffnen könnt.\n\nStellt Euch nur vor, was dahinter liegen mag... Es könnte eine komplette zweite Hälfte der Stadt geben, von der wir bis jetzt noch keine Ahnung hatten! Oder nichts! Wer weiß das schon?\n\nAber da ist sicher etwas...", progress = nil, completion = "Verdammt! Ich MUSS einfach wissen, was hinter diesem Tor liegt! Das könnte die Entdeckung sein, die meine Karriere ins Rollen bringt. Versteht Ihr?\n\nHmm… Vielleicht können ein paar strategisch platzierte Explosionen das Problem ja lösen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27604] = {title = "Jammal'an der Prophet", objective = "Erbeutet den Kopf von Jammal'an dem Propheten.", description = "Jammal'an der Prophet, Anführer der Atal'ai- und Hakkaritrolle, hat eine kleine Menge Blut von Hakkar dem Seelenschinder an sich gebracht. Jetzt verabreichen sie es grünen Drachen, damit deren Körper riesige Mengen des Bluts produzieren, das notwendig ist, um Hakkar in unsere Welt zu rufen.\n\nDas können wir nicht zulassen Tötet Jammal'an und seine Priester, bevor sie noch weitere Fortschritte machen.", progress = "Habt Ihr Jammal'an getötet? Ich brauche einen Beweis, dass die Tat vollbracht ist.", completion = "Ausgezeichnet! Ich nehme an, dass die Trolle sich ohne Jammal'ans Führung gegenseitig bekämpfen werden. Hakkar wird diese Welt nie erblicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27605] = {title = "Eranikus", objective = "Tötet Eranikus.", description = "Das Hakkarblut, das die Atal'ai den grünen Drachen verabreicht haben, hatte verheerende Auswirkungen auf die Drachen. Offenbar hat seine Anwesenheit in ihren Körpern die Drachen, die früher Gefangenenwärter der Atal'ai waren, verdorben und in Alptraumkreaturen verwandelt.\n\nEranikus, Yseras erstem Berater und Oberaufseher über den Tempel, wurden die größten Mengen des Blutes verabreicht. Das hat ihn jenseits aller Vorstellungskraft verändert. Wenn Jammal'an tot ist, sucht Eranikus und bereitet ihm ein Ende.", progress = nil, completion = "Ihr habt nur Eranikus' Schemen besiegt? Das ist äußerst beunruhigend...\n\nHoffen wir, dass seine wahre Gestalt nicht noch außerhalb des Tempels existiert. Nur Ysera persönlich ist stärker als er.", rewards = "Ihr bekommt:\n\nEssenz des Schemens von Eranikus"}
MultiLanguageQuestData['de'][27606] = {title = "Jagt ihn in die Luft!", objective = "Blast in der Nähe eines Banners der Heth'Jatari in das Muschelhorn. Tötet Tiefenlord Heth'Jatar. Es wird einfacher, wenn Ihr ihn in das Mörserfeuer lockt.", description = "Lasst uns ein paar Fische fangen, <Name>! Jetzt, da die Mörser bereit sind, können wir den Anführer dieser Invasion vernichten.\n\nTiefenlord Heth'Jatar ist der Kopf der Kriegerkaste der Schwarzschuppen. Geht zu den Bannern der Heth'Jatari nordöstlich von hier und blast in dieses Muschelhorn. Es funktioniert wie eine Hundepfeife, nur für Fische.\n\nWenn Heth'Jatar sich zeigt, werde ich den Mörserschützen befehlen, das Feuer zu eröffnen. Ihr werdet sehen, wo die Granaten einschlagen werden.\n\nLockt Heth'Jatar in unser Mörserfeuer und prügelt solange auf ihn ein, bis er aufgibt.", progress = nil, completion = "Kabumm!\n\nWas? Ihr habt den Tiefenlord schon erschlagen?\n\nNun, dann brauchen wir wohl nicht weiter auf seine Leiche schießen.", rewards = "Gürtel des TritonshornbläsersKampfhandschuhe der Heth'JatariArmschienen des gefallenen TiefenlordsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27607] = {title = "Die südliche Flanke", objective = "Sprecht mit Rok'tar am Zwielichtufer im Schattenhochland.", description = "Unsere neue Vereinbarung mit der Horde stürzt mein Volk in einen direkten Konflikt mit der Allianz.\n\nDann sollen sie mal kommen!\n\nIn diesem Augenblick rückt die Allianz auf der Halbinsel vor, um den Hafen des Drachenmals zu bedrängen.\n\nSucht im Süden nach Rok'tar und stellt sicher, dass das Zwielichtufer in unserer Hand bleibt. Ich glaube, Rok'tar hat einen Gefechtsstand auf einem der Schiffswracks errichtet.", progress = nil, completion = "Ihr kommt genau rechtzeitig, &lt;Klasse&gt;. Wir sind gerade dabei, einen Gegenangriff zu starten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27608] = {title = "Vier Köpfe sind besser als keiner", objective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", description = "Wir werden gleich den Angriff auf die Tore der Zitadelle starten, doch es gibt noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nWürdet Ihr nochmals losziehen und sie töten?Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "SchädelträgerSchiftung der grausigen LeistungAuf Euch wartet eine dieser Belohnungen:\n\nZa'brox' Glückszahn\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27609] = {title = "Vier Köpfe sind besser als keiner", objective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", description = "Wir werden gleich den Angriff auf die Tore der Zitadelle starten, doch es gibt noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nGeht bitte zurück und tötet sie.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "SchädelträgerSchiftung der grausigen EhreAuf Euch wartet eine dieser Belohnungen:\n\nZa'brox' Glückszahn\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27610] = {title = "Späht den Strand aus", objective = "Späht den Brückenkopfkontrollpunkt am Zwielichtufer aus. Ihr müsst ihn nicht einnehmen, doch wenn Ihr dies tut, erhält Eure Fraktion einen Vorteil im Kampf und Ihr werdet für den PvP-Kampf markiert.", description = "Wenn die Allianz die Kontrolle über diese Halbinsel erlangt, gerät der Hafen des Drachenmals in Gefahr. Das lasse ich nicht zu.\n\nSüdlich von hier findet Ihr einen kleinen Hügel, von dem aus man einen beeindruckenden Ausblick auf die Küstenlinie hat. Wer diesen Hügel kontrolliert, hat auch die Oberhand über die gesamte Küste.\n\nEilt schnell dorthin und späht den Brückenkopfkontrollpunkt aus. Er ist mit einer riesigen Flagge markiert. Kehrt dann zu mir zurück.\n\nIhr müsst ihn nicht einnehmen, es sei denn, Ihr seid auf einem Kampf mit der Allianz aus.", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;. Jetzt kennt Ihr die Lage des Landes.\n\nWenn Ihr je Probleme im Kampf hier am Zwielichtufer habt, dann vergesst nicht, dass alle Streitkräfte der Horde einen Kampfvorteil erhalten, wenn der Brückenkopf unter unserer Kontrolle steht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27611] = {title = "Blutgetränkter Sand", objective = "Tötet 12 Marinesoldaten am Zwielichtufer im Schattenhochland.", description = "Unser Ziel im Schattenhochland ist, die Bastion des Zwielichts zu stürmen, aber die Allianz hat sich entschlossen, einen Krieg anzuzetteln.\n\nAlso sollen sie ihren Krieg haben!\n\nTötet ihre Marinesoldaten, bis sie ihre Lektion gelernt haben.", progress = nil, completion = "Gut, gut. Wer Wind sät, soll Sturm ernten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27612] = {title = "Sieg im Inneren", objective = "Öffnet die Argentumportale im Bibliotheksflügel und der Halle der Waffen in der Abtei in Tyrs Hand.", description = "Ein paar unserer Männer haben es nicht durch die Portale geschafft, die sich in dieser Abtei hätten öffnen sollen. Ihr habt bereits bewiesen, dass Ihr ebenso gut ausweichen wie kämpfen könnt... das müsst Ihr noch einmal zeigen.\n\nDie Abtei hat zwei Flügel: eine Bibliothek und eine Halle der Waffen. In beiden Flügeln sollte es ein Portal geben.\n\nSetzt den Schlüsselstein bei diesen Portalen ein. Der Stein sollte ihre Öffnung erzwingen. Dann können unsere restlichen Stoßtruppsoldaten die Abtei einnehmen.", progress = "Einhundert Soldaten sind schon recht wenig. Solche Rückschläge reduzieren unsere Siegeschancen.", completion = "Die Abtei wird in Kürze fallen. Wir können bald tiefer in Tyrs Hand eindringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27613] = {title = "Der Assassine", objective = "Tötet Rohan den Assassinen im Glockenturm der Abtei in Tyrs Hand.", description = "Das Schicksal des Scharlachroten Kreuzzugs ist tragisch, aber nicht ohne Ironie. Einst waren sie die Speerspitze der Menschheit im Kampf gegen die Untoten. Jetzt sehen sie aus wie die Leichen, die sie früher jagten. Es ist unklar, was sie in den Untod getrieben hat, aber das macht sie nicht weniger gefährlich.\n\nEiner ihrer tödlichsten Kämpfer war ein Assassine, der sich Rohan nannte. Laut unseren Informationen hält er sich genau in dieser Abtei ganz oben im Glockenturm auf. Findet und tötet ihn, <Name>. Und versucht, dabei nicht zu sterben.", progress = nil, completion = "Rohans Tod erleichtert mich ein wenig.\n\nWisst Ihr, dass ich früher mit ihm gekämpft habe? Vor vielen Jahren war er ein Abgesandter des Scharlachroten Kreuzzugs, einer der wenigen, die uns in der Schlacht gegen Kel'Thuzad zur Seite standen. Wie schnell sich alles ändert.", rewards = "Rohans MaskeBeinschützer des MorgenbringersAuf Euch wartet eine dieser Belohnungen:\n\nUhr des Abgesandten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27614] = {title = "Scharlachrote Bergung", objective = "Erbeutet den Purpureber, Lihannas Strang, das Tuch des Uther und Gavinrads Siegel.", description = "Diese Schlacht war schon gewonnen, bevor sie begann. Jetzt verbessern wir nur noch unsere B-Note.\n\nDie wimmernden Scharlachroten Kreuzfahrer klammern sich in ihren Kasernen an ihre unbezahlbaren Artefakte, obwohl manche so heilig sind, dass ihre jetzt untoten Hände sie nicht mehr berühren können. Also werden sie in Truhen aufbewahrt und vor der Welt versteckt.\n\nFindet diese Artefakte und bringt sie mir zurück. Ihr Platz ist beim Argentumkreuzzug. Sie gehören in die Hände der Rechtschaffenen.", progress = "Ich hoffe, es war ein guter Kampf.", completion = "Hervorragend, &lt;Name&gt;. Ich werde sie nach unserer Rückkehr Tyrosus übergeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27615] = {title = "Der Zornwirker", objective = "Tötet Mataus den Zornwirker.", description = "Im Kerker der Kaserne lauert ein äußerst übler Zeitgenosse des Scharlachroten Kreuzzugs, Mataus der Zornwirker. Der Untod passt zu seinem düsteren Gehabe.\n\nWäre ich noch jünger und an der Front, würde ich ihn selbst aufspießen. Doch leider muss ich unsere Streitkräfte von hinten anführen. Deshalb überlasse ich Euch dieses Vergnügen.", progress = nil, completion = "Ihr seid auf dem besten Weg, ein wahrer Champion des Lichts zu werden, &lt;Name&gt;. Gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27616] = {title = "Der Jäger", objective = "Tötet Jäger Leopold.", description = "Die Kugeln und Pfeile, die uns oben aus dieser Festung entgegenschießen, haben schon ein halbes Dutzend Männer das Leben gekostet. Ich kenne das Gesicht des Feindes, der auf uns schießt nicht, doch das ist auch nicht nötig. Ich kenne den Namen des Mannes, der dort oben hockt.\n\nLeopold.\n\nEs ist wirklich nur ein einziger Mann, der von dort oben meine Männer nacheinander umbringt. Und so wie ich das sehe, gibt es auch nur <einen/eine> von Euch.\n\nKlingt nach einem fairen Kampf.", progress = nil, completion = "Eine Sorge weniger. Gute Arbeit da oben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27617] = {title = "Entdorben", objective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", description = "Spürt Ihr es? Die Verderbnis löst sich bereits von diesem Gebäude.\n\nEin heiliges Gebäude will heilig sein. Übeltäter wie Rohan und seine Scharlachroten Kumpane hindern es jedoch daran.\n\nDie Abtei ist gesichert. Die Eroberung von Tyrs Hand ist einen Schritt näher gerückt. Meldet Angela das Ergebnis unseres Schlags. Sie führt den Angriff auf die Kathedrale irgendwo aus der Stadtmitte an.", progress = nil, completion = "Gut, die Abtei ist unser. Ich habe keinen Moment lang an Eligors Fähigkeiten gezweifelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27618] = {title = "Argentumaufstand", objective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", description = "Wir haben dieser Kaserne so viel Schaden zugefügt, dass man von einem Sieg sprechen kann. Eine Kommandantin, ein Jäger und ein Hexenmeister getötet... Und die ganzen Relikte, die wir geborgen haben. Oder sollte ich sagen... Die IHR geborgen habt.\n\nDie Kathedrale wird als Nächstes fallen. Sprecht mit Erzmagierin Angela Dosantos im Hauptinnenhof. Das Schicksal der Kathedrale von Tyrs Hand liegt in ihren fähigen Händen.", progress = nil, completion = "Korfax hat wohl in der Kaserne richtig aufgeräumt. So eine Angeberei passt zu ihm.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27619] = {title = "Die Kommandantin", objective = "Tötet die Scharlachrote Kommandantin Marjhan.", description = "Die Scharlachrote Kommandantin Marjhan ist listig, gewieft und bereit, alles für einen Sieg zu tun. Doch das Wichtigste ist ihre unerschütterliche Loyalität.\n\nIhr werdet sie zweifellos in der Hauptkammer der Kaserne finden. Dort wird sie unter einem scharlachroten Banner kämpfen, bis sie entweder siegt oder stirbt.\n\nSorgt dafür, dass Letzteres eintritt.", progress = nil, completion = "Gut, gut. Die Kaserne ist so gut wie erobert.", rewards = "Helm der fehlgeleiteten TreueMarjhans letztes GefechtAuf Euch wartet eine dieser Belohnungen:\n\nKorfax' Signet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27620] = {title = "Wie Ratten", objective = "Tötet Kreuzfahrerlord Valdelmar.", description = "Es freut mich, dass Eligor und Korfax mir ein wenig Spaß übrig gelassen haben. Es war nicht leicht, sie davon abzuhalten, Hals über Kopf in diese Kathedrale zu stürmen.\n\nAber das ist schließlich EURE Aufgabe.\n\nDie Kathedrale liegt vor uns. Sie ist die letzte Bastion der Scharlachroten Macht. Kreuzfahrerlord Valdelmar hockt darin auf dem klapprigen Lügengerüst von Tyrs Hand.\n\nEs darf keine Flucht geben und keine Gnade. Der erbärmliche Rest des Scharlachroten Kreuzzugs wird hier sein Ende finden. Tötet ihn.", progress = nil, completion = "Obwohl ich mit ihren Methoden nicht einverstanden bin, sprechen ihre Resultate für sich. Der Scharlachrote Kreuzzug meinte es eigentlich gut, aber ihr Eifer wurde zu groß und ihr Hass raubte ihnen den Verstand.\n\nIch hoffe inständig, dass dies unserer Bruderschaft des Lichts nie zustoßen wird.", rewards = "Umhang des GeachtetenBartholomäus' GürtelAuf Euch wartet eine dieser Belohnungen:\n\nBand des Eifers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27621] = {title = "Feuerbarts Patrouille", objective = "Sucht nach Keegan Feuerbart bei Feuerbarts Patrouille im Schattenhochland.", description = "Ich war auf dem Weg, um mich Feuerbarts Patrouille anzuschließen, als mein Vogel abgeschossen wurde.\n\nDer Schattenhammer hat überall im Hochland Überraschungsangriffe durchgeführt. Manchmal erschienen ihre Gebäude einfach so aus dem Nichts aus dem Boden, mitten in unseren Dörfern. Es war ein echter Alptraum!\n\nIn dem Chaos war Feuerbart einer der wenigen, die einen kühlen Kopf bewahrten. Er versucht, ein vollständiges Greifenreitergeschwader aus den Überlebenden zusammenzustellen.\n\nWenn Ihr wollt, dass die Wildhämmer sich der Allianz anschließen, solltet Ihr zunächst Feuerbart im Westen helfen.", progress = nil, completion = "Seid Ihr hier, um Euch der Patrouille anzuschließen, Bursche? Ich nehme Euch mit Freuden auf.\n\nIch brauche ein paar fähige Recken, um unsere Verteidigung hier unter Kontrolle zu kriegen. Helft mir und ich werde zusehen, dass ich eine etwas glanzvollere Arbeit für Euch finde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27622] = {title = "Netter Schredder", objective = "Findet einen bergungsfähigen Schredder am Zwielichtufer und benutzt ihn, um einen Bergungsexperten aus Bilgewasser herbeizurufen. Verteidigt den Schredder, bis er wieder funktionstüchtig ist.", description = "<Name>, ich habe Pläne für einen verbesserten Schredder, aber meine Ingenieure können nicht einfach so alleine in ein Kampfgebiet spazieren.\n\nGeht und findet einen bergungsfähigen Schredder am Zwielichtufer und benutzt ihn, um einen meiner Bergungsexperten herbeizurufen. Verteidigt den Schredder, bis wir ein paar \"Aktualisierungen\" daran vorgenommen haben.\n\nDie Allianz wird gar nicht wissen, wie ihr geschieht! Zumindest nicht, bis meine Marketingkampagne angelaufen ist!", progress = nil, completion = "So mag ich das! Genau so! Kalter Stahl und heißer Tod!\n\nWelchen Namen sollten wir unserer neuen Schöpfung geben? Der Gnugatron? Nein, viel besser: der &lt;Name&gt;-o-Matik! Das hat einen guten Klang.", rewards = "SchredderverwerterschiftungGamaschen des zerfetzten SchutzesMechanomonteurskopfschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27623] = {title = "Kolossale Wächter", objective = "Beschafft Euch den Stein des Mondes und den Stein der Sonne von den kolossalen Wächtern.", description = "Die Kiste, die das Zepter enthält, scheint magisch versiegelt zu sein und ist nicht zum Nachgeben zu bewegen.\n\nDie Plakette darüber zeigt zwei riesige Statuen, in deren Mitte sich Vertiefungen befinden, in die jeweils ein mond- und ein sternförmiger Stein passen.\n\nDie Abbildung der Statuen zeigt, wie sie Pyramiden bewachen, die so wie diejenigen aussehen, die sich draußen befinden.\n\nVielleicht würde es sich lohnen, diese zu untersuchen.", progress = "Ihr wischt den Sand von den Hieroglyphen, aber sie werden sofort von einer neuen Schicht überzogen. Ihr solltet Euch lieber beeilen.", completion = "Ihr platziert die beiden Edelsteine in die Vertiefungen an der Wand.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27624] = {title = "Nach dem Fall", objective = "Sammelt die Kugel des Morgensterns, die Kugel des Abendsterns, die Kugel des Nordsterns und die Kugel der Sternschnuppe ein.", description = "Och, das war nichts weiter.\n\nDiese Statuen waren ohnehin wackelig - sie brauchten nur einen kleinen Schubs.\n\nWie wäre es, wenn Ihr geht und die Trümmer durchsucht?\n\nIch habe das Gefühl, als ob wir kurz davor stehen, das Rätsel zu lösen.", progress = "Habt Ihr etwas Interessantes gefunden, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;.\n\n\n\nSieht so aus, als ob unsere Arbeit hier fast erledigt ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27625] = {title = "Zur Verteidigung von Quel'Danil", objective = "Tötet 16 Eindringlinge der Todespirscher an der Jagdhütte Quel'Danil.", description = "Die Untoten sind hier! Die Verlassenen! Sie kamen immer näher und näher, aber aufs Ganze gehen und uns angreifen... Diese entsetzlichen Monstrositäten!\n\nDie jungen Draenei, die man mir anvertraut hat, haben mit den Hochtalelfen im Kampf trainiert. Sie sind nicht schutzlos, aber sie brauchen Hilfe!\n\nBitte, <Name>, helft ihnen! Drängt die Verlassenen zurück!", progress = nil, completion = "Derartige Verirrung im Angesicht des Lichts... Ihr seid mutig, Euch ihnen entgegenzustellen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27626] = {title = "Die Hochtalaufzeichnungen", objective = "Findet den Hochtalbericht, die Hochtalaufzeichnungen und die Hochtalnotizen.", description = "Die Hochtalelfen haben seit Jahren hier detaillierte Aufzeichnungen aufbewahrt. Todesfälle, Geburten, Jahreszeiten... aber auch wichtige Informationen von Spähern und Methoden, wie man mit dem Rest der Allianz Verbindung aufnehmen kann.\n\nDiese Aufzeichnungen werden in dem Chaos verstreut werden. Wenn sie in die Hände der Verlassenen fallen, könnten noch mehr Leben auf dem Spiel stehen! Bitte, Ihr müsst die Aufzeichnungen finden, bevor sie der Horde in die Hände fallen.", progress = "Sind sie in Sicherheit?", completion = "Dem Licht sei Dank! Wir werden den Verlassenen nichts überlassen, das gegen uns verwendet werden kann, egal, wie wenig es sein mag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27627] = {title = "Nur eine aufgetakelte Kakerlake", objective = "Tötet 5 Amethystskarabäen, 5 Saphirskarabäen, 5 Türkisskarabäen und 5 Smaragdskarabäen.", description = "Offensichtlich beherbergten die uralten Statuen verschiedene Arten von Skarabäen.\n\nIhr seid entschlossen, diesen Ort in dem bestmöglichen Zustand zu verlassen und beschließt, die Kammer von dieser Plage zu befreien.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel See Invis 11\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27628] = {title = "Benachrichtigt Phaoris", objective = "Sprecht mit König Phaoris in Ramkahen in Uldum.", description = "Beeilt Euch, <Name>. Wir müssen mit meinem Bruder, dem König, sprechen.\n\nEr will unbedingt einen Krieg mit Al'Akir und Neferset verhindern. Er hat die törichte Hoffnung, dass es für dieses Problem eine diplomatische Lösung gibt.\n\nVielleicht kommt er zur Vernunft, wenn er hört, was hier geschehen ist.", progress = nil, completion = "Das ist erst der Anfang, &lt;Name&gt;. Wenn die Gehilfen von Todesschwinge ganze Städte begraben können, haben wir kaum eine Chance, sie mit normalen Mitteln zu besiegen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Post-Orsis Event Camera\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27629] = {title = "Das Votum des Wesirs", objective = "Sprecht mit Wesir Tanotep auf den Feldern von Akhenet in Uldum.", description = "Wesir Tanotep dazu zu bewegen, sich gegen die Wünsche meines Bruders zu stellen, wird äußerst schwierig sein. Seine Stellung beruht darauf, den Willen von Phaoris durchzusetzen.\n\nIch hatte kein Glück damit, für einen offenen Krieg gegen Neferset zu plädieren.\n\nDennoch müsst Ihr mit ihm sprechen. Vielleicht hört er auf die Ansichten eines Außenstehenden.\n\nIhr findet den Wesir auf den Feldern von Akhenet in offizieller Mission.", progress = nil, completion = "Was für eine Kreatur seid Ihr? Ihr werdet das Land des Königs verlassen, bevor...\n\nWartet! Ihr seid dieser &lt;Name&gt;, über den ich so viel gehört habe.\n\nIhr müsst meine mangelnde Gastfreundschaft entschuldigen. Wir haben hier zu viele feindliche Eindringlinge zu Gesicht bekommen, seit die Barriere um Uldum gefallen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27630] = {title = "Das Votum des Hohepriesters", objective = "Sprecht mit Hohepriester Amet im Vir'naaldamm in Uldum.", description = "Das Votum von Hohepriester Amet ist das Einzige, das sich unserer Kontrolle entzieht.\n\nEr wird so abstimmen, wie seine Weissagungen es ihm vorschreiben und wir können ihn nicht davon abbringen.\n\nIch denke, dadurch sind die Chancen in beide Richtungen ausgeglichen.\n\nDas einzige Problem ist, dass seine Hellseherei ihn, seitdem die Barrieren um Uldum gefallen sind, im Stich lässt.\n\nEr wird nicht abstimmen, solange er nicht wieder die Kontrolle über seine Weissagungen hat.\n\nSteigt eine der Treppen an den Seiten des Vir'naaldamms hinab, sprecht mit ihm und seht, was Ihr tun könnt, um ihm zu helfen.", progress = nil, completion = "Krieg, sagt Ihr.\n\nWeissagungen für einen Krieg sind immer schwierig. Einige Kriege dürfen nie ausgetragen werden, auch, wenn der Sieg sicher wäre. Einige Kriege müssen geführt werden, auch wenn die Niederlage sicher ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27631] = {title = "Das Votum des Hochkommandanten", objective = "Sprecht mit Hochkommandant Kamses am Außenposten der Legion von Ramkahen in Uldum.", description = "Wenn wir eine Resolution für Krieg verabschieden sollen, muss der Hohe Rat einstimmig dafür sein.\n\nIch bin sicher, dass Hochkommandant Kamses uns seine Stimme geben wird, wenn er hört, was in Orsis geschehen ist.\n\nBitte sprecht mit ihm in Ramkahen und stellt sicher, dass er Bescheid weiß. Ich muss Vorbereitungen treffen, falls unser Plan erfolglos ist.", progress = nil, completion = "Es ist nicht nötig, mich in die Geschehnisse in Orsis einzuweihen, &lt;Name&gt;.\n\nIch habe bereits davon gehört. Und von Euch. Jeder Feind von Al'Akir ist mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27632] = {title = "Tanoteps Sohn", objective = "Besorgt die Karte des Vir'Naaldeltas von einer Wache von Neferset.", description = "Ich habe mein Leben in die Dienste des Königs gestellt. Nichts ist so wichtig, wie ihm zu dienen - mit einer Ausnahme: mein Sohn.\n\nTahet wurde von Wachposten von Neferset gefangen genommen.\n\nSie behaupten, dass mein Sohn unbefugt ihr Gebiet betreten hat. Phaoris versucht, seine Freilassung zu verhandeln... doch ich befürchte das Schlimmste.\n\nWenn Ihr Tahet findet, würde ich Euch meine Stimme geben.\n\nIch weiß nicht, wohin sie ihre Gefangenen bringen, aber ich habe gesehen, wie die Wachen auf Karten geschaut haben, die sie durch die dichte Vegetation führen sollten.", progress = "Dies könnte die Karte sein, die Ihr sucht.", completion = "Ihr habt eine Karte des Vir'naaldeltas bekommen.", rewards = "Beinschützer von HamatepHandschuhe des SumpfsuchersAxt der Wache des Vir'naalIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27633] = {title = "Der Blutgott Hakkar", objective = "Tötet den Avatar von Hakkar.", description = "Hakkar... die Bloße Erwähnung des Namens des Seelenschinders schlägt viele in die Flucht. Im Sanktum des Gefallenen Gottes haben die Atal'ai einen großen Teil seines Skeletts geborgen und möchten ihn wieder ins Leben rufen. Seine Kinder haben schon begonnen, im Umkreis aufzutauchen.\n\nLegt dieses Ei im Sanktum ab. Es wird seine Beschwörung früher als geplant erzwingen. <Name>, Ihr dürft nicht zögern. Schlagt zu, sobald sein Avatar erscheint!", progress = "Konntet Ihr Hakkars Avatar zerstören?", completion = "Hier habt Ihr Hakkar erfolgreich aufgehalten, aber ich befürchte, wir sind noch lange nicht fertig. Die Atal'ai haben den Großteil des von ihnen produzierten Blutes nach Zul'Gurub abtransportiert, wo die Hakkari daran arbeiten, den Blutgott dort zu beschwören.\n\nIch glaube nicht, das dies hier jemals der Ort für Hakkars Ankunft sein sollte - es war lediglich ein Test, um zu sehen, ob das Blut stark genug ist! Hakkar kann nur in Zul'Gurub beschworen werden... und ich befürchte, wir kommen zu spät, um die Hakkari aufzuhalten, nun da sie das Blut besitzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27635] = {title = "Dekontamination", objective = "Besteigt den Sanitron 500 und lasst Euch dekontaminieren.", description = "Ihr seid schon sehr lange hier unten in Gnomeregan, <Name>, und es ist bemerkenswert, dass Ihr überlebt habt und noch bei Verstand seid! Wir müssen Euch rausholen.\n\nBevor wir Euch zu den anderen Gnomen an die Oberfläche schicken können, müsst Ihr dekontaminiert werden. Begebt Euch in den nächsten Raum und besteigt den Sanitron 500. Er wird den Rest erledigen! Es wird nicht weh tun... nicht sehr.\n\nMeldet Euch bei Techniker Braggel, wenn Ihr fertig seid. Er wird Euch geeignete Ausrüstung besorgen.", progress = nil, completion = "So, jetzt könnt Ihr Euch an die Oberfläche begeben und ein neues Leben beginnen. Der Hochtüftler wird begeistert sein, wenn er von Eurer Ankunft erfährt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27636] = {title = "Nur Ihr und Mathias", objective = "Findet Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", description = "Alle Agenten des SI:7 sind tot. Ihr müsst Meister Mathias Shaw finden.\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo er sich aufhält.", progress = nil, completion = "Wo ist der Rest meiner Leute?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27637] = {title = "Nur Ihr und Mathias", objective = "Findet Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", description = "Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Meister Mathias Shaw sich aufhält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27638] = {title = "Nur Ihr und Garona", objective = "Findet Garona die Halborcin bei der Schattenzitadelle im Schattenhochland.", description = "Alle Kor'kron sind tot. Ihr müsst Garona die Halborcin finden.\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo sie sich aufhält.", progress = nil, completion = "Wo sind die Kor'kron?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27639] = {title = "Nur Ihr und Garona", objective = "Findet Garona die Halborcin bei der Schattenzitadelle im Schattenhochland.Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Garona sich aufhält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Garona sich aufhält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27640] = {title = "Gegen Dunwalds ist kein Kraut gewachsen", objective = "Haltet nach Überlebenden der Familie Dunwald in den Ruinen von Dunwald Ausschau.", description = "Man hat Euch also beauftragt, die Wildhammerklans für den Krieg zu vereinen. Ein edles Unterfangen, keine Frage, aber ich glaube nicht, dass Ihr wisst, worauf Ihr Euch da eingelassen habt.\n\nDennoch, wenn Ihr Euch auf eine Schlacht vorbereitet, darf eine Familie unter keinen Umständen an Eurer Seite fehlen. Geht nach Südwesten, gegenüber des Schmelztiegels des Gemetzels. Dort findet Ihr die Ruinen des Dunwaldklans. Sie sind zwar ganz schön ramponiert, aber das hält jemanden wie die Dunwalds nicht auf. Der schwierigste Teil dabei wird, sie zu finden.", progress = nil, completion = "Wenn Ihr nach den Dunwalds sucht, dann habt Ihr sie gefunden. Zumindest einen Teil davon. Meine anderen Brüder kann ich leider nicht finden, so sehr ich es auch versucht habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27641] = {title = "Beim Familientreffen", objective = "Tötet 20 Mitglieder des Schattenhammers im Gebiet der Dunwalds.", description = "He da, <Bursche/meine Dame>! Sicher hat Keely Euch in Sorge um unsere Brüder gestürzt, aber sie können ganz gut auf sich selbst aufpassen. Sie werden schon irgendwie hierher zurückfinden.\n\nVielleicht könnt Ihr mir einen Gefallen tun, wenn Ihr ohnehin schon zum Familientreffen da draußen seid... Das Gebiet der Dunwalds ist immer noch voll von den Kultisten des Schattenhammers und ihren Dienern. Ich würde es sehr zu schätzen wissen, wenn Ihr sie daran erinnert, dass sie hier nicht willkommen sind.", progress = nil, completion = "Ja, genau so habe ich mir das vorgestellt, Bursche. Ein &lt;Volk&gt; ganz nach meinem Geschmack.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27642] = {title = "Durchsuchung der Trümmer", objective = "Durchsucht die Leichen von 12 Opfern der Dunwalds.", description = "Als der Schattenhammer unser Dorf gebrandschatzt hat, waren sie ganz schön gründlich. Meine Brüder und ich waren vielleicht die Einzigen, die sie zurückgehalten haben. Ich muss jedoch Gewissheit haben.\n\nWährend Ihr die Ruinen durchsucht, haltet Ausschau nach Leichen meiner Gefolgsleute. Ich muss wissen, ob es Überlebende gibt... oder Anzeichen dafür, dass jemand entkommen konnte.", progress = nil, completion = "So viele Tote also? Dann ist es nicht sehr wahrscheinlich, dass jemand außer meinen Brüdern den Kampf überlebt hat. Das habe ich befürchtet.\n\nVielen Dank, dass Ihr Euch die Zeit genommen habt, für mich zu suchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27643] = {title = "Donnelly Dunwald", objective = "Findet Donnelly Dunwald.", description = "Ihr sucht nach uns, und ich suche nach meinen Brüdern. Offensichtlich haben wir also schonmal eine Sache gemeinsam.\n\nDonnelly ist unser ältester Bruder. Bei seiner Körpergröße wird das deutlich, bei seinem Verstand jedoch eher weniger. Normalerweise hält er sich in den Ruinen im Norden auf, in der Hütte. Könntet Ihr vielleicht für mich nach ihm suchen? Es würde mich beruhigen, wenn ich wüsste, dass es ihm gut geht.", progress = nil, completion = "Hallo, Freund! Ich glaube nicht, dass ich Euch kenne… Ich bin Donnelly Dunwald.\n\nUnd wie heißt Ihr? Ich glaube nicht, dass ich Euch kenne… Kenne ich Euch?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27644] = {title = "Eoin Dunwald", objective = "Findet Eoin Dunwald.", description = "Eoin ist einer der Zwillinge. Er trinkt gerne mal einen über den Durst. Wahrscheinlich findet Ihr ihn beim alten Brunnen. Dort haben wir nämlich in einem Gebäude unser Bier gelagert.\n\nKönntet Ihr ihn vielleicht überreden, seiner besorgten Schwester einen Besuch abzustatten? Wenn Ihr zuerst an das Bier gelangt, sollte er sich bestimmt nicht lange bitten lassen.", progress = nil, completion = "Warum musste von allen Gebäuden dieser Stadt ausgerechnet dieses hier einstürzen?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27645] = {title = "Cayden Dunwald", objective = "Findet Cayden Dunwald.", description = "Cayden ist der andere Zwilling. Auch ihn dürstet es, aber nicht nach Bier. Er amüsiert sich sicher köstlich, seit der Schattenhammer an unsere Tür geklopft hat. Vielleicht kann er so ein paar Aggressionen loswerden.\n\nIch schätze, Ihr sucht am besten in der Marktgasse bei der alten Schmiede nach ihm. Er hat sich schon früher immer gerne dort aufgehalten, aber da sich an diesem Ort die meisten Anhänger des Schattenhammers tummeln, hat er wahrscheinlich jetzt noch mehr Grund, ihn sein Zuhause zu nennen.\n\nBringt ihn zu mir zurück. Unversehrt, falls möglich.", progress = nil, completion = "Schaut Euch nur an mit all der Ausrüstung und dem Schnickschnack. Keely hat Euch also geschickt, damit Ihr auf den alten Cayden aufpasst, ja? Nicht nötig! Ich habe diese Flegel im Griff.\n\nHaha! Sie haben heute dem falschen Zwerg aufgelauert! Ahahahahaha!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27646] = {title = "Auf der Suche nach Schnäbelchen", objective = "Helft Donnelly dabei, Schnäbelchen in den Hütten von Dunwald zu finden.", description = "Ich hab' meinen Greifen verloren. Schnäbelchen! Wo bist du, Schnäbelchen?!\n\nHelft Ihr mir, ihn zu finden? Ich weiß, dass er irgendwo in den Hütten ist. Muss er einfach sein!\n\nSchnäbelchen?! Wo tust du denn stecken?\n\nIch hoffe, ihm fehlt nichts.", progress = "Habt Ihr ihn gefund'n?! Bitte?", completion = "Ihr habt ihn gefund'n! Ihr habt Schnäbelchen gefund'n! Ich mag Euch, mein neuer Freund!\n\nIch werde ihn gleich Keely zeigen. Keely tut Schnäbelchen auch mögen.", rewards = "GreifensuchergürtelplatteFreundesfindertreterSchnäbelchens zerrissener FuttersackIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27647] = {title = "Alles außer Wasser", objective = "Durchsucht den Keller, von dem Eoin Dunwald gesprochen hat, nach einem Fass.", description = "Schaut, Kumpel. Entweder helft Ihr mir, etwas zu trinken zu finden, oder Ihr geht mir aus dem Weg.\n\nWarum schaut Ihr nicht unten im alten Lagerhaus nach? Ich hatte den alten Buchhalter da nämlich schon immer im Verdacht, dass er sich heimlich das ein oder andere Gläschen zwischen den Zeilen gönnt. Ich wette, er hat ein Fass im Keller versteckt.\n\nWenn Ihr etwas findet, dann kommt sofort zu mir zurück. Nicht trödeln! Das hier ist brandeilig.", progress = "Ihr stinkt nach Nüchternheit! Sucht mir etwas zu trinken!", completion = "Bei Donnellys Dickbauch! Das sieht schon besser aus. Wie schön, dass ich jetzt nicht mehr verdursten muss.\n\nHier, nehmt einen Schluck. Der gute alte Eoin ist nie so unhöflich, nicht zu teilen!", rewards = "Fassgroße BrustplatteArmschienen des BierkostersSchulterpolster des BiertrinkersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27648] = {title = "Durch diese hohle Gasse muss er kommen", objective = "Begleitet Cayden Dunwald durch den etwas offensichtlichen Hinterhalt.", description = "In Ordnung, in Ordnung. Ihr wollt also auch etwas von dem Spaß haben? Fein, Ihr könnt mitmachen.\n\nLasst mich wissen, wenn Ihr bereit seid.", progress = "Sie kommen immer wieder, und ich hau weiter drauf.", completion = "Wundervoll, oder? Und sie können nicht genug davon bekommen. Ich liebe es!\n\nIch werde zu Keely gehen und sie ein wenig beruhigen. Nur noch ein Durchgang!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlutgetränkter BierkrugFokus des WeltenbezwingersInsigne des Panzerkommandanten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27649] = {title = "Stete Versorgung", objective = "Sammelt 6 Fässer Wildhammerbier.", description = "He, Kumpel. Da Ihr ja so freundlich und toll und so seid, könntet Ihr einem Zwerg vielleicht einen Gefallen tun?\n\nDies sind die Ruinen der Dunwalds… Es MUSS einfach mehr Vorräte in einem dieser Gebäude geben. Wenn Ihr noch etwas Bier findet, würdet Ihr es mir dann bringen? Ja? Ein guter Zwerg kann nie genug bekommen!\n\nIch werde mich auf den Weg zu Keely machen, also werdet Ihr mich vielleicht suchen müssen. Aber keine Sorge, es wird Eure Mühe wert sein.", progress = "Wo ist mein gutes Gesöff?", completion = "Whoohooo! Genau das verlangt mein Magen!\n\nIhr bringt mir wirklich lauter nette Sachen!", rewards = "Dunwalds feinste BindungenKugelbauchstulpenBlubbergebräukapuzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27650] = {title = "Wieder zuhause", objective = "Sprecht mit Keely Dunwald in der Bastion der Dunwalds.", description = "Ihr solltet Keely aufsuchen. Sie ist bestimmt auf Eure Neuigkeiten gespannt.", progress = nil, completion = "Vielen Dank, dass Ihr meine Brüder wieder zusammengetrommelt habt. Ich weiß, sie sind harte Brocken, aber Seite an Seite sind sie noch härter, und da draußen sind ganz schön viele Kultisten des Schattenhammers.\n\nIhr habt einem armen Mädchen eine schwere Last von der Seele genommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27651] = {title = "Nach Dunwälder Art", objective = "Sprecht mit Flynn Dunwald und helft den Dunwaldbrüdern dabei, Darunga zu töten.", description = "Sie sind schon auf dem Weg, um den Ettin zu jagen, der den Angriff auf den Besitz der Dunwalds angeführt hat. Ich habe sie gebeten, Euch wenigstens eine Chance zu lassen, sie einzuholen, aber ich bin mir nicht sicher, ob das Warten ihnen liegt.\n\nSie sind in Richtung Ratsplatz gegangen, in die Mitte der Ruinen. Ihr solltet zu ihnen aufschließen, wenn Ihr auch mit von der Partie sein wollt.", progress = nil, completion = "Vielen Dank für Eure Hilfe. Ihr habt das Herz eines Kriegers. Fast hätt' ich Euch für einen Wildhammer gehalten, wenn Ihr nicht… nun ja… Ihr wisst schon.\n\nIch weiß, dass Feuerbart Euch geschickt hat, um uns zu vereinen. Meine Sympathie für diesen Zwerg ist alles andere als groß, aber Ihr wisst ja jetzt, dass wir genügend Gründe haben, um den Schattenhammer als Feind zu betrachten. Sagt ihm, dass er auf die Familie Dunwald zählen kann, wenn die Schlacht beginnt.", rewards = "Flynns LieblingsbrustplatteGreifengriffgamaschenDunwalds FlügelhelmAuf Euch wartet eine dieser Belohnungen:\n\nHimmelsflugsignal\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27652] = {title = "Dunkle Auftragsmörder", objective = "Sammelt 5 Anhänger eines dunklen Auftragsmörders.", description = "Sogar ich werde gejagt. Das hat man eben davon, wenn man sich unter Schafen versteckt.\n\n<Mathias mustert Euch einen Augenblick lang.>\n\nDer Schattenhammer hat einen Zahn zugelegt und seine dunklen Auftragsmörder nach mir geschickt. Nette Kerle, doch leider alle tot. Sie bestehen aus den Seelen der fähigsten Attentäter.\n\nMöchtet Ihr mir einen Gefallen tun? Dann bringt sie zur Strecke und beschafft mir ihre Seelenanhänger.", progress = "Wie viele Anhänger habt Ihr?", completion = "Ich bin mir nicht sicher, was ich mit all diesen Dingern tun soll. Wahrscheinlich werde ich sie verhökern und den Ertrag dem Waisenhaus in Sturmwind stiften.\n\nJetzt muss ich nur noch jemanden finden, der geisteskrank genug ist, so etwas zu kaufen. Wahrscheinlich ein Goblin. Oder ein gnomischer Hexenmeister.", rewards = "Schallgedämpfte DonnerbüchseErstickte ArmschienenFlinke FechterfingerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27653] = {title = "Dunkle Auftragsmörder", objective = "Sammelt 5 Anhänger eines dunklen Auftragsmörders.", description = "Sogar ich werde gejagt. Das hat man eben davon, wenn man sich unter Schafen versteckt.\n\n<Garona mustert Euch einen Augenblick lang.>\n\nDer Schattenhammer hat einen Zahn zugelegt und seine dunklen Auftragsmörder nach mir geschickt. Nicht schlecht für einen haufen toter Kerle. Sie bestehen aus den Seelen der fähigsten Attentäter.\n\nMöchtet Ihr mir einen Gefallen tun? Dann bringt sie zur Strecke.\n\nSie tragen ihre Seelen in Anhängern um den Hals. Bringt sie mir. Die Seelen sind optional.", progress = "Wie viele Anhänger habt Ihr?", completion = "Was soll ich nur mit all diesen Dingern tun? Vielleicht lasse ich sie einschmelzen und mache mir aus dem Metall einen neuen Dolch, den ich Cho'gall ins Herz stoßen kann.\n\nMeint Ihr, dafür haben wir genug Zeit?", rewards = "Schallgedämpfte DonnerbüchseHerzverwundende ArmschienenStulpen des EinfädlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27654] = {title = "Nieder mit dem Hammer", objective = "Tötet 10 Veteranen der Zitadelle, korrumpierte Elementaristen und/oder Zwielichtverteidiger.", description = "Ein Vorstoß auf das Schlachtfeld wäre nicht vollständig, wenn es keine altmodische \"Macht den bösen Jungs den Garaus\"-Mission gäbe.\n\nIch bin mir sicher, dass Ihr bei all den Veteranen der Zitadelle, den korrumpierten Elementaristen und den Zwielichtverteidigern genügend Ziele findet.\n\nWie Ihr sie zur Strecke bringt, bleibt ganz Euch überlassen.", progress = nil, completion = "Keiner von uns ist zu schade, um sich die Hände dreckig zu machen. Oder in diesem Fall blutig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27655] = {title = "Nieder mit dem Hammer", objective = "Tötet 10 Veteranen der Zitadelle, korrumpierte Elementaristen und/oder Zwielichtverteidiger.", description = "Es gibt nicht Schlimmeres als diese von Selbsthass zerfressenen Kultisten des Schattenhammers. Nichts! Diese Idioten wollen tatsächlich das Ende der Welt herbeiführen.\n\nDas bringt sie ganz oben auf meine Abschussliste.\n\nBei all den Veteranen der Zitadelle, den korrumpierten Elementaristen und den Zwielichtverteidigern gehen Euch die Ziele sicher nicht aus.\n\nWie Ihr sie zur Strecke bringt, ist mir herzlich egal.", progress = nil, completion = "Fühlt sich gut an, so ein bisschen Blut an den Händen, was? Besonders, wenn es das Blut solcher verblendeten Narren ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27656] = {title = "Krokischwemme", objective = "Tötet 8 Sägezahnkrokilisken.", description = "Im Stagalsumpf östlich der Stadt wimmelt es von Krokilisken. Wimmelt, hört Ihr? Ich habe jeden vorstellbaren Teil der Krokilisken verkauft.\n\nKrokiliskenhäute, ihre Zähne, Schwänze, Zungen, Augen und so weiter. Was ich damit sagen will: Das verkauft sich nicht mehr. Es gibt zu viele Krokis! Wir haben ein Überangebot und eine Unternachfrage.\n\nDa sie mir also nichts mehr nützen und gelegentlich meine Gäste fressen, möchte ich, dass Ihr die Drecksviecher umbringt. Tut mir den Gefallen, ja? Ich verhandle währenddessen über irgendwas mit Euren Leuten.", progress = nil, completion = "Alles erledigt? Freut mich. Eine Sorge weniger.\n\nJetzt kann ich mich auf ordentliche Geschäfte mit den freundlichen Bewohnern von Sumpftidenwacht und Steinard konzentrieren, die vom Krieg gezeichnet sind... und all der Blödsinn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27657] = {title = "Die Hilfe der Erdenruferin", objective = "Sprecht mit Erdenruferin Yevaa vor den Elementiumtiefen im Schattenhochland.", description = "Meine Untersuchungen zu Cho'galls Artefakt sind in einer Sackgasse angelangt. Der Schattenhammer hat eine Gruppe von Schmieden der Wildhämmer versklavt und im See ertränkt, als sie ihre Aufgabe erledigt hatten.\n\n<Mathias spuckt aus.>\n\nWir brauchen Hilfe. Es gibt da eine Erdenruferin des Irdenen Rings mit Namen Yevaa.\n\nSie und ihr goblinischer Initiand halten sich an der Elementiummine im Südwesten auf und brauchen Hilfe dabei, die Elementarportale in der Gegend zu schließen. Im Gegenzug können sie uns sicher bei unserem Problem helfen.", progress = nil, completion = "&lt;Name&gt;! Ich bin froh, dass Ihr hier seid.\n\nNatürlich helfe ich Euch gerne, wo ich kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27658] = {title = "Die Hilfe der Erdenruferin", objective = "Sprecht mit Erdenruferin Yevaa vor den Elementiumtiefen im Schattenhochland.", description = "Meine Untersuchungen zu Cho'galls Artefakt sind in einer Sackgasse angelangt. Der Schattenhammer hat eine Gruppe von Schmieden der Wildhämmer versklavt und im See ertränkt, als sie ihre Aufgabe erledigt hatten.\n\n<Garona spuckt aus.>\n\nIch sage es nicht gerne, aber wir brauchen Hilfe. Es gibt da eine Dame des Irdenen Rings, eine Draenei namens Erdenruferin Yevaa. Sie und ihr Goblinschoßhund halten sich in der Elementiummine im Südwesten auf.\n\nSie brauchen Hilfe dabei, die Elementarportale in der Gegend auszuschalten. Im Gegenzug können sie uns bei unserem Problem helfen.", progress = nil, completion = "&lt;Name&gt;! Ich bin froh, dass Ihr hier seid.\n\nNatürlich helfe ich Euch gerne, wo ich kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27659] = {title = "Überlastung der Portale", objective = "Tötet den entkräfteten Apexar, den entkräfteten Aetharon und den entkräfteten Edemantus.", description = "Ich war früher die Hüterin der Portale des Irdenen Rings, doch als Ihr in Tiefenheim wart, um zu helfen, ist der Schattenhammer hier eingefallen und hat das Gebiet verderbt.\n\nSie lassen unsere Portale von mächtigen Aszendenten bewachen. Und genau darin liegt ihr Fehler.\n\nIch möchte, dass Ihr zu den Portalen geht und die Steuerungen verwendet, um sie zu überlasten. Dadurch werden die gesamten Energien des Portals freigesetzt und die Aszendenten geschwächt. Tötet sie.", progress = nil, completion = "Das letzte Portal liegt tief in der Mine hier, aber darum kümmern wir uns gleich.", rewards = "TiefgräberhelmPortalversieglerbrustplatteDunkellichtfackelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27660] = {title = "Geist des Lochs", objective = "Sprecht mit Gräfin Verrall im Loch Verrall im Schattenhochland.", description = "Ich weiß nichts von einem Artefakt, das Cho'gall herstellt, aber ich glaube, ich kenne jemanden, der Euch helfen kann.\n\nGräfin Verrall ist ein alter Geist, der sich im Loch Verrall im Norden aufhält. Sie hegt keine Sympathie für den Schattenhammer, der ihre Wasser verschmutzt hat.\n\nBittet sie um die Weisheit, die Ihr sucht.", progress = nil, completion = "Ich weiß, warum Ihr hier seid, &lt;Name&gt;. Eure Gründe singen im Rauschen Eures Blutes.\n\nIch weiß von dem toten Zwergenschmied, der meine Wasser verschmutzt. Wenn Ihr herausfinden wollt, an was sein Leichnam sich erinnert, dann müsst Ihr es Euch verdienen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27661] = {title = "Artilleriefeuer", objective = "Tötet Lord Artillerius.", description = "Mein Erzfeind, Lord Artillerius, war so dumm, sich dem Schattenhammer anzuschließen.\n\nIn der Vergangenheit hatten wir einen brüchigen Waffenstillstand geschlossen, aber nach dieser Entscheidung habe ich keine andere Wahl, als ihm ein Ende zu setzen. Oder lasst es mich so ausdrücken: Wenn Ihr Informationen von einem toten Zwerg wollt, müsst Ihr Lord Artillerius für mich töten.\n\nSucht ihn bei Artillerius' Inferno im Südosten auf.", progress = nil, completion = "Ich bin sehr zufrieden. Lord Artillerius war mir immer ein unwürdiger Gegner.\n\nNun gut, &lt;Volk&gt;. Ich werde Euch dabei helfen, an die Informationen zu gelangen, die Ihr sucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27662] = {title = "Pflichtentbindung", objective = "Befreit 10 versklavte Elementare in der Schattenzitadelle, indem Ihr sie tötet.", description = "Wenn ich mich mit einer Sache auskenne, dann sind es Elementare. Ich habe wirklich gelernt zu verstehen, wie sie empfinden. Und lasst mich Euch sagen: Es gefällt ihnen gar nicht, versklavt zu werden!\n\nIch will damit sagen, dass die Elementare Euch sicher nicht nur dankbar sind, wenn Ihr sie aus der Sklaverei befreit, sondern sich wahrscheinlich auch gegen ihre Meister wenden.\n\nIch finde, das klingt für beide Seiten nach einem Gewinn.", progress = nil, completion = "Was habe ich Euch gesagt? Elementare sind gar nicht so übel, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27663] = {title = "Schmeckt wie Schreiter", objective = "Sammelt 9 riesige Sumpfschreiterschenkel von Sumpfschreitern.", description = "Ihr da! Ja, Ihr! Ihr wollt ein gutes Wort beim Handelsbaron eingelegt bekommen? Dann geht mir mal zur Hand!\n\nIch habe gehört, dass Ihr derjenige seid, der die ganzen Makruraschwänze besorgt hat. Die sind zwar toll, aber nicht ausreichend für ein anständiges Sumpfessen. Ich brauche Keulen für mein Gumbo!\n\nEs gibt eine Menge Sumpfschreiter außerhalb der Stadt, im Sorgendunkel. Ich will die größten Keulen, die Ihr finden könnt!", progress = "Habt ihr die Keulen?", completion = "Ah, gut, gut! Das war genau, was ich brauchte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27664] = {title = "Vulkankartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Vulkankartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Vulkankartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Vulkankartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Vulkankartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Vulkan"}
MultiLanguageQuestData['de'][27665] = {title = "Hurrikankartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Hurrikankartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Hurrikankartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Hurrikankartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Hurrikankartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDunkelmond-Karte: HurrikanDunkelmond-Karte: Hurrikan"}
MultiLanguageQuestData['de'][27666] = {title = "Tsunamikartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Tsunamikartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Tsunamikartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Tsunamikartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Tsunamikartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Tsunami"}
MultiLanguageQuestData['de'][27667] = {title = "Erdbebenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Erdbebenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Erdbebenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Erdbebenkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Erdbebenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Erdbeben"}
MultiLanguageQuestData['de'][27668] = {title = "Passt auf!", objective = "Nazgrim möchte, dass Ihr nachschaut, was in der zerbrochenen Kiste der Allianz nördlich der \"Ewiger Kreislauf\" liegt.", description = "Hört zu, <Volk>. Nicht, dass ich die Rettung nicht zu schätzen wüsste, aber wir sind in einer schlimmen Lage.\n\nIhr müsst da draußen besser achtgeben!\n\nIch habe Euch beobachtet. Ihr seid direkt über einer zerbrochenen Kiste der Allianz vorbeigeschwommen.\n\nDa ist sicher etwas drin, das mir und meinen Jungs helfen könnte.\n\nWarum geht Ihr nicht dorthin und schaut einfach mal hinein, hm?", progress = nil, completion = "Ja…\n\nDas sieht aus wie etwas, an dem Nazgrim sehr interessiert sein wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27669] = {title = "Ihr habt die Ehre", objective = "Benutzt die Kugeln der Sterne in der Nähe des Mechanismus in der Kammer der Sterne.", description = "Anscheinend müssen jetzt nur noch die Kugeln auf die Sockel in jeder Ecke dieses Mechanismus gelegt werden.\n\nWir sind offenbar über den wichtigsten Fund der modernen Geschichte gestolpert.\n\n<Harrison schaut Euch eine Weile an und gibt Euch dann die Kugeln.>\n\nNur zu, <Name>.\n\nOhne Euch hätten wir diese Entdeckung nie gemacht.", progress = nil, completion = "Jetzt schaut Euch das an!\n\nSo erstaunlich dies auch sein mag, ich bin sicher, dass hinter unserer Entdeckung noch mehr steckt.\n\nWesentlich mehr.", rewards = "StatuenklettererBrustschutz des zerschmetternden GötzenKettenreaktionskapuzeAuf Euch wartet eine dieser Belohnungen:\n\nAuge der Sterne\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHarrison beschwören\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27670] = {title = "Eingekesselt", objective = "Tötet 6 wahnsinnige Lepragnome.", description = "Mein Name ist Nevin Drallzang und ich bin der Kommandant von S.I.C.H.E.R.\n\nIch weiß nicht, wie Ihr die Strahlung hier unten überlebt habt, <Name>, aber die meisten anderen hatten nicht so viel Glück. Mein Team sammelt zwar die Überlebenden, aber es gibt so viele strahlungsverwirrte Lepragnome, dass wir sie nicht mehr lange zurückdrängen können. Sie haben den Verstand verloren!\n\nSolltet Ihr noch stark genug sein, um eine Waffe zu heben oder einen Zauber zu wirken, könntet Ihr uns helfen, ein paar dieser Lepragnome auszuschalten.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Meine Männer werden jetzt übernehmen. Konzentrieren wir uns darauf, die anderen Überlebenden herauszubringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27671] = {title = "Kümmert Euch um die Überlebenden", objective = "Benutzt das Teleportersignal, um 6 Überlebende in Sicherheit zu teleportieren.", description = "Wenn wir nicht bald handeln, werden weder Nevin noch die Überlebenden hier heil herauskommen. Ich werde Euch das Notfallteleportersignal meiner Einheit geben. Wir haben noch genügend Kraft und Munition, um uns nach oben zu kämpfen, aber diese Überlebenden können nicht mithalten.\n\nSetzt das Signal bei den Überlebenden ein, damit sie in die sichere Zone, die meine Männer errichtet haben, teleportiert werden können. Erstattet mir Bericht, sobald das erledigt ist und wir werden dafür sorgen, dass Ihr hier wegkommt.", progress = nil, completion = "Es wird Nevin freuen, dass Ihr so vielen Überlebenden helfen konntet. Ich kann immer noch nicht fassen, dass Ihr trotz der Strahlung hier unten noch so stark seid. Ihr habt ja den Zustand der anderen Überlebenden gesehen.\n\nAb mit Euch zum Laderaum zur Dekontamination.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27672] = {title = "Die Kammer von Khaz'mul", objective = "Besiegt Ironaya.", description = "In der Kartenkammer gibt es eine Tür, die zur legendären Kammer von Khaz'mul führt. Wer kann schon sagen, welche Geheimnisse darin verborgen sein mögen!\n\nWas wir wissen, ist, dass sie von Ironaya, einer Titanenwächterin von immenser Größe und Macht bewacht wird. Ihr müsst sie besiegen, wenn Ihr die Geheimnisse von Uldaman entdecken wollt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27673] = {title = "Es kommt auf die inneren Werte an", objective = "Beschafft Euch den Obsidiankraftkern und den Titankraftkern.", description = "Die Schöpfer haben zwei Uralte Steinbewahrer gebaut, um Uldaman vor möglichen Eindringlingen zu schützen und die Tagesgeschäfte zu überwachen, währen Ironaya und Archaedas schlummern. Einer ist immer noch voll funktionsfähig und befindet sich in der Halle des Tempels, aber der andere in der Echomok-Höhle wurde von etwas beschädigt.\n\nIch fürchte, dass einer der Alten Götter dafür verantwortlich ist. Ihr müsst mir helfen herauszufinden, ob das der Fall ist. Legt beide Wächter hin und bringt mir ihre Kraftkerne. Sie werden uns enthüllen, was wir wissen müssen.", progress = "Wo sind die Kerne, mein Junge? Bei Muradins Bart, wo sind die verflixten Kerne?\n\n<Kand atmet tief durch.>\n\nTut mir leid. Konntet Ihr die Kerne an Euch bringen?", completion = "Das ist unglaublich, &lt;Name&gt;. Die Kraft, die durch jeden dieser Kerne fließt... Die gegensätzlichen Kräfte so nah beieinander.\n\nIch bringe das sofort zu den richtigen Zwergen. Diese Kerne sind immens wichtig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27674] = {title = "Zur Oberfläche", objective = "Sprecht mit Torben Zischknall, lasst Euch an die Oberfläche teleportieren und meldet Euch bei Nevin Drallzang.", description = "Nevin hat gerade gemeldet, dass er und seine Leute auf dem Weg zur Oberfläche sind. Er erwartet Euch in dem Gebäude, das S.I.C.H.E.R. zum Hauptquartier erkoren hat.\n\nSeht Ihr Torben Zischknall da hinten? Sprecht mit ihm, wenn Ihr zur Oberfläche aufbrechen wollt und er wird für den Transport sorgen. Es war mir ein Vergnügen, Euch kennenzulernen, <Name>. Ich fühle mich geehrt, eine kleine Rolle bei Eurer Flucht aus Gnomeregan und dem Beginn Eures neues Lebens an der Oberfläche gespielt zu haben.", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;. Ohne Eure Hilfe wäre es uns dieses Mal nicht gelungen, so viele Überlebende aus Gnomeregan zu retten. Alle wollen Euch treffen und Eure Geschichte hören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27675] = {title = "Gefälschte Dokumente", objective = "Findet einen Bewohner in Sturmwind, der Eure gefälschten Dokumente annimmt.", description = "Findet einen Bewohner in Sturmwind, der Eure gefälschten Dokumente annimmt.", progress = "Habt Ihr etwas für mich?", completion = "&lt;Ihr überreicht die gefälschten Dokumente und wechselt dabei nur wenige Worte. Euer meisterhaftes Können spricht für sich selbst.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForged Documents Trigger Spell\n\nIhr bekommt:\n\nPrall gefüllter Goldbeutel"}
MultiLanguageQuestData['de'][27676] = {title = "Hinter verschlossenen Türen", objective = "Tötet Galgann Feuerhammer.", description = "Galgann Feuerhammer und seine Gruppe Dunkeleisenzwerge halten sich in Grabstelle Drei auf und bewachen dort eine Tür, von der wir nichts wissen! Es reicht! Ständig stören seine Leute unsere Arbeit. Die Forscherliga besitzt als einzige Gruppe die Erlaubnis, die Artefakte in Uldaman zu begutachten!\n\nGeht zur Grabstelle und werdet ihn los, damit wir unsere Arbeit ungestört fortsetzen können. Ich will wissen, was hinter dieser Tür ist!", progress = nil, completion = "Großartig! Hervorragende Arbeit! Wir werden schon bald wissen, was sich in Grabstelle Drei verbirgt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27677] = {title = "Archaedas, der alte Steinbehüter", objective = "Besiegt Archaedas.", description = "Das wahre Ziel in Uldaman ist es, die Scheiben von Norgannon zu erlangen. Die Geheimnisse auf diesen Scheiben könnte die Art, wie wir unsere Welt sehen, völlig verändern. Zahllose Geheimnisse der Schöpfer sind darauf aufgeschrieben... ihr Wert liegt über allem Materiellen, das Ihr Euch nur vorstellen könnt.\n\nDas Problem ist, das Archaedas, eine uralte und mächtige Konstruktion der Schöpfer, die Scheiben mit einer beachtlichen Armee zu seiner Verfügung beschützt. Ihr müsst ihn besiegen und die Scheiben für die Forscherliga sichern!", progress = nil, completion = "Gut gemacht, Mädel! Geht jetzt zu den Scheiben und erfahrt von ihnen so viel es geht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27679] = {title = "Die Kammer von Khaz'mul", objective = "Besiegt Ironaya.", description = "In der Kartenkammer befindet sich eine verschlossene Tür, die zur legendären Kammer von Khaz'mul führen muss. Wir wissen noch nicht, was für Artefakte sich darin befinden.\n\nWas wir wissen, ist, dass sie von Ironaya, einer Titanenwächterin von immenser Größe und Macht bewacht wird. Ihr müsst sie bezwingen, wenn Ihr vorhabt, weiter in diesen Ort vorzudringen.", progress = nil, completion = "Agenten der Akademie sind unterwegs, um die Kammer zu untersuchen. Ihr habt Wichtigeres zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27680] = {title = "Archaedas, der alte Steinbehüter", objective = "Besiegt Archaedas.", description = "Das wahre Ziel in Uldaman ist es, die Scheiben von Norgannon zu erlangen. Diese Platinscheiben könnten uns unfassbare Macht verleihen. Zahllose Geheimnisse der Schöpfer sind darauf aufgeschrieben... ihr Wert liegt über allem Materiellen, das Ihr Euch nur vorstellen könnt.\n\nDas Problem ist, das Archaedas, eine uralte und mächtige Konstruktion der Schöpfer, die Scheiben mit einer beachtlichen Armee zu seiner Verfügung beschützt. Ihr müsst ihn besiegen und die Scheiben für die Archäologische Akademie sichern!", progress = nil, completion = "Ihr seid ein überaus verlässlicher Agent, &lt;Name&gt;. Nähert Euch den Scheiben und findet heraus, soviel Ihr könnt. Erstattet mir sofort danach wieder Bericht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27681] = {title = "Hinter verschlossenen Türen", objective = "Tötet Galgann Feuerhammer.", description = "Galgann Feuerhammer und seine Gruppe Dunkeleisenzwerge halten sich in Grabstelle Drei auf und bewachen dort eine Tür, von der wir nichts wissen! Es reicht! Ständig stören seine Leute unsere Arbeit. Die Archäologische Akademie besitzt als einzige Gruppe die Erlaubnis, die Artefakte in Uldaman zu begutachten!\n\nGeht zur Grabstelle und werdet ihn los, damit wir unsere Arbeit ungestört fortsetzen können. Ich will wissen, was hinter dieser Tür ist!", progress = nil, completion = "Gut gemacht! Grabstelle Drei und die Geheimnisse hinter dieser Tür werden bald uns und nur uns gehören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27682] = {title = "Wir brauchen mehr Mineralien", objective = "Besorgt den Obsidiankraftkern und den Titankraftkern.", description = "Die Titanen haben zwei uralte Steinbewahrer erbaut, um Uldaman vor möglichen Eindringlingen zu schützen und den täglichen Betrieb zu überwachen, während Ironaya und Archaedas schlafen. Einer davon ist noch voll funktionstüchtig und steht in der Tempelhalle. Der andere in der Echomokhöhle wurde jedoch von etwas verderbt.\n\nIch vermute, dass einer der Alten Götter dahinter steckt, und Ihr werdet mir dabei helfen, dieser Vermutung nachzugehen. Überwältig beide Wächter und bringt mir ihre Kraftkerne. Sie werden uns alles sagen, was wir wissen müssen.", progress = "Habt Ihr die Kerne bei Euch, oder wollt Ihr nur plaudern? Vielleicht sollten wir mit dem ganzen Quatsch hier aufhören und uns lieber ein paar Leckereien und ein feines Gläschen Wein gönnen?", completion = "Diese Kerne sind viel mächtiger als die meisten herkömmlichen Kerne, die wir benutzen, um unsere Beschützer mit Energie zu versorgen. Und diese Geräte sind uralt!\n\nVielen Dank. Sie werden sich sicher als besonders wertvoll für unsere Gesellschaft herausstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27683] = {title = "In die Wälder", objective = "Sucht nach einer Worgenfrau am Fluss Thondroril in den Östlichen Pestländern.", description = "Letztens konnte ich ein seltsames Treiben in der Stadt beobachten. Es handelte sich um einen Pferdewagen voller Kisten und Truhen, mit einer Worgenfrau auf dem Kutschbock, einem Blutelfen an ihrer Seite und einem Zwergenpaladin, der hinter dem Wagen her lief und die kreativsten Obszönitäten rief, die ich seit langem gehört habe.\n\nSie schienen auf dem Weg in die Östlichen Pestländer zu sein, allerdings dürften sie bis jetzt kaum weiter als bis zum Fluss Thondroril gekommen sein. Ich frage mich, was sie vorhaben.", progress = nil, completion = "Ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27684] = {title = "Besucher", objective = "Sucht nach einer Worgenfrau am Fluss Thondroril in den Östlichen Pestländern.", description = "Meine Quellen an der Stätte der Heiler haben mir verraten, dass wir bald einige Besucher erwarten dürfen. Eine Gruppe Paladine - die bizarrerweise von einer Worgenhändlerin angeführt wird - müsste bald hier eintreffen. Ich freue mich, sie kennenzulernen. Vor allem einen.\n\nWärt Ihr so nett, kurz nach ihnen zu sehen? Ich bin mir zwar nicht sicher, aber wenn Ihr dort eintrefft, sollten sie gerade den Fluss Thondroril weit im Westen überqueren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27685] = {title = "Eine gute Tat bleibt unvollständig", objective = "Sprecht mit Adarrah im Tang'tharwald.", description = "'N Tag, <Kumpel/Mädel>.\n\nIch bin Rendel.\n\nSieht aus, als wär'n die gute alte Moanah und ich gerade rechtzeitig hier eingetroffen, was?\n\nErunak hat nicht gescherzt, als er sagte, es ginge um Leben oder Tod!\n\nDa wir uns so beeilt ha'm, hierher zu kommen, ha'm wir ein Stück im Osten ein paar unerledigte Aufgaben zurückgelassen.\n\nDa war eine kleine Lady, die nur knapp dem Tode entronnen is'. Wir hatten keine andere Wahl, als sie bei einem kleinen Luftstrom zurückzulassen, nachdem wir sie gerettet ha'm.\n\nWarum geht Ihr nicht dorthin und helft ihr, solange die Zeit es zulässt?", progress = nil, completion = "Oh, endlich!\n\nIch weiß nicht, wie lange ich noch durchhalte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27686] = {title = "Gefälschte Dokumente", objective = "Findet einen Bewohner in Orgrimmar, der Eure gefälschten Dokumente annimmt.", description = "Findet einen Bewohner in Orgrimmar, der Eure gefälschten Dokumente annimmt.", progress = "Habt Ihr etwas für mich?", completion = "&lt;Ihr überreicht die gefälschten Dokumente und wechselt dabei nur wenige Worte. Euer meisterhaftes Können spricht für sich selbst.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForged Documents Trigger Spell\n\nIhr bekommt:\n\nPrall gefüllter Goldbeutel"}
MultiLanguageQuestData['de'][27687] = {title = "Ganz ohne Zähneknirschen", objective = "Bringt Knirschers Kopf zu Samir im Schmugglerschmiss.", description = "Was für eine Leistung, einen solch mächtigen Meerriesen zu erlegen!\n\nDie neuen Bewohner des Schmugglerschmisses werden sich bestimmt sehr viel sicherer fühlen, wenn dieses Monster nicht mehr vor ihrer Zuflucht herumlungert.", progress = "Ihr habt diesen Meeresriesen erlegt, <Klasse>?", completion = "Es ist nicht viel, aber es ist alles, was ich hier unten habe.\n\nIch gebe es Euch von Herzen gerne, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27688] = {title = "Lenkt sie für mich ab", objective = "Tötet Freifrau Alys Finnsson, Meister Klem und Mia die Rose.", description = "Es gibt drei Anwärter auf die Aszendenz, die wir beseitigen müssen: Freifrau Alys Finnsson, Meister Klem und Mia die Rose.\n\nIch möchte, dass Ihr als Ablenkung dient. Wenn der rechte Moment gekommen ist, werde ich hinzukommen und sie von hinten erledigen.\n\nEgal was Ihr tut, Ihr dürft sie auf keinen Fall unterschätzen, <Name>. Jeder von ihnen hat sich seine Position durch Skrupellosigkeit erkämpft, und sie sind gut in dem, was sie tun.", progress = nil, completion = "Damit hätten wir einen Großteil ihrer Anführer außerhalb der Bastion erledigt.\n\nWir sind ein gutes Team, &lt;Name&gt;.", rewards = "Klems rostige StulpenSchuppenschienbeinschützer der DameNach Rosen duftende KapuzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27689] = {title = "Lenkt sie für mich ab", objective = "Tötet Freifrau Alys Finnsson, Meister Klem und Mia die Rose.", description = "Es gibt drei Anwärter auf die Aszendenz, die wir beseitigen müssen: Freifrau Alys Finnsson, Meister Klem und Mia die Rose.\n\nIch möchte, dass Ihr als Ablenkung dient. Wenn der rechte Moment gekommen ist, werde ich hinzukommen und sie von hinten erledigen.\n\nEgal was Ihr tut, Ihr dürft sie auf keinen Fall unterschätzen, <Name>. Jeder dieser Wahnsinnigen hat sich seine Position durch Skrupellosigkeit erkämpft, und sie sind gut in dem, was sie tun.", progress = nil, completion = "Damit hätten wir einen Großteil ihrer Anführer außerhalb der Bastion des Zwielichts erledigt. Keine schlechte Arbeit, &lt;Name&gt;. Ganz und gar nicht schlecht.", rewards = "Klems rostige StulpenSchuppenschienbeinschützer der DameNach Rosen duftende KapuzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27690] = {title = "Narkrall, der Drachenzähmer", objective = "Meldet Euch bei Narkrall Harkenklaue in der Blutschlucht im Schattenhochland.", description = "<Name>, die Feste in der Blutschlucht bildet das Herz des Drachenmalreiches im Schattenhochland. Sie befindet sich direkt den Fluss entlang. Narkrall Harkenklaue nutzt seine beträchtliche Macht, um dort einen Drachenreitergeschwader zu versammeln.\n\nDamit das Drachenmal Erfolg hat, muss die Blutschlucht Erfolg haben. Geht zu Narkrall und stellt sicher, dass dies der Fall ist.", progress = nil, completion = "&lt;Narkrall mustert Euch.&gt;\n\nNoch so ein weinerlicher Welpe der Horde? Zaela raubt uns unsere Stärke, indem sie unsere Truppen mit dem Blut der Schwachen verwässert. Nun gut, &lt;Klasse&gt;. Beweist Euch und zeigt mir, aus welchem Holz Eure Horde geschnitzt ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27691] = {title = "Marschflossenwahnsinn", objective = "Tötet 12 Murlocs der Marschflossen.", description = "Ich fürchte, der Rest des Dampfdruckkartells ist tot. Alle jungen in dem Lager im Osten waren verloren, als die Murlocs kamen.\n\nJa, an diesen Ufern sind immer Murlocs... aber nicht so viele. Sie kamen in Scharen nachts aus dem Meer, heulten und schäumten und schwärmten an Land, um anzugreifen!\n\nWir können nicht zulassen, dass sie weiter hier herumrennen, nicht wahr? Würdet Ihr einem alten Goblin seinen Seelenfrieden zurückgeben und einige von ihnen wieder ins Wasser zurücktreiben?", progress = "Ich habe immer noch ein paar Asse im Ärmel, aber ich werde nicht mit den Murlocs kämpfen, wenn es nicht sein muss.", completion = "Man muss sich doch fragen, was da draußen ist. Dies ist die Küste des Verbotenen Meers. Dahinter befindet sich nichts... doch dieses ganze Fischgesindel kam direkt dort heraus.\n\nSchlimmer noch, ich sah, wo sie hingingen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27692] = {title = "Prinzessin Theradras", objective = "Tötet Prinzessin Theradras und kehrt zu Zaetars Geist zurück.", description = "Fürchtet Euch nicht, <junger/junge:r> <Volk>. Ich bin Zaetar, Sohn des Cenarius, und ich komme, um Euch um Hilfe zu bitten.\n\nVor langer Zeit machte ich den Fehler, mich mit Prinzessin Theradras einzulassen, einem mächtigen Erdelementar, der den Alten Göttern unterstand. Unsere Kinder, die Khans der Zentauren, wandten sich schon bei ihrer Geburt gegen mich und töteten mich ohne Gnade. Nun ist Theradras' Verderbnis weit fortgeschritten und bedroht weit mehr als nur Maraudon.\n\nKommt und tötet sie, und befreit meinen Geist, sodass wir Desolace in einen Ort des blühenden Lebens und der Verheißung verwandeln können, wie Cenarius es gewollt hätte.", progress = nil, completion = "Danke, &lt;Name&gt;. Wie Ihr sehen könnt, hat meine bloße Anwesenheit hier üppiges Leben entspringen lassen, trotz der Anwesenheit meines Gefährten. Ungeachtet des Namens werdet Ihr vielleicht eines Tages wieder nach Desolace reisen und eine blühende Oase frei von jeder Sput der Alten Götter vorfinden.", rewards = "Zaetars HandschuheSandalen des prachtvollen LebensGamaschen der tiefgrünen OaseSchulterstücke des VersprechensSchild von MaraudonIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27693] = {title = "Das Spiel des Wächters", objective = "Beendet das Spiel des Wächters, indem Ihr die Bauern des Wächters in eine nach innen gerichtete Position teleportiert.", description = "Ihr seht, wie sich die Statue erst in zwei, dann in vier, dann in acht identische Statuen in quadratischer Anordnung teilt.\n\nIhr hört eine Stimme, jedoch nicht mit Euren Ohren, sondern direkt in Eurem Kopf:\n\n\"Ein wahrer Wächter sieht nicht nach AUSSEN, um nach Anzeichen der Gefahr zu suchen.\n\n Ein wahrer Wächter richtet seinen Blick nach INNEN, immer darauf konzentriert, seine Beute zu schützen.\"\n\nVielleicht ist dies eine Art Rätsel?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27694] = {title = "Tränenteich", objective = "Sammelt 5 Artefakte der Atal'ai aus dem Tränenteich um den Tempel von Atal'Hakkar herum.", description = "Die Trolle, die in diesem Tempel lauern, haben meiner Art Schreckliches angetan, <Name>. Wir wurden hierher geschickt, um diesen Ort zu schützen, und stattdessen wurden wir benutzt, um die fürchterlichen Mächte darin zu entfesseln.\n\nIch flehe Euch an, um die Hilfe, die nur ein Sterblicher leisten kann. Ihr könnt meine Hand im Tempel sein; würde ich allein eintreten, könnte auch ich gegen meine Brüder gewendet werden.\n\nWir werden einen Pakt schließen. Wenn Ihr mir helfen wollt, sammelt Artefakte der Atal'ai aus den Wassern um den Tempel herum, und bringt sie zu mir.", progress = "Diese Artefakte zu sammeln wird Eure Vertrauenswürdigkeit unter Beweis stellen. Sobald das geschehen ist, werde ich das Ritual durchführen.", completion = "Die Essenz des grünen Drachenschwarms entströmt diesen Artefakten; die Überbleibsel meiner verderbten Verwandten. Indem ich sie reinige, schließe ich einen Bund zwischen uns.\n\nTretet hervor, &lt;Name&gt;, und empfangt den Schwurstein von Yseras Drachenschwarm.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27695] = {title = "Die Elementiumaxt", objective = "Beschafft Euch die Elementiumaxt.", description = "Diese Feiglinge des Schattenhammers haben so viele rote Drachen gefangen und getötet, aber einer ist immer noch am Leben. Erinnert Ihr Euch an Lirastrasza? Sie ist in der Nähe angekettet, und wir werden sie befreien.\n\nAber zuerst brauchen wir etwas, das scharf genug ist, um ihre Ketten zu zerschlagen.\n\nAm Altar des Aufstiegs im Süden wacht ein alter Ettin namens Blindauge der Wächter.\n\nIn seinem Besitz befindet sich eine fein gearbeitete Axt aus Elementium. Ich frage mich, ob das wohl Cho'galls \"ultimative\" Waffe ist.", progress = "Habt Ihr die Axt? Sie werden Lirastrasza bald töten.", completion = "Das Ding sieht verdammt scharf aus. Zumindest scharf genug, um seinen Zweck zu erfüllen.\n\nIch für meinen Teil schätze, dass dies nicht die Bewaffnung ist, hinter der Cho'gall her ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27696] = {title = "Die Elementiumaxt", objective = "Beschafft Euch die Elementiumaxt.", description = "Diese Feiglinge des Schattenhammers haben so viele rote Drachen gefangen und getötet, aber einer ist immer noch am Leben. Erinnert Ihr Euch an Lirastrasza? Sie ist in der Nähe angekettet, und wir werden sie befreien.\n\nAber zuerst brauchen wir etwas, das scharf genug ist, um ihre Ketten zu zerschlagen.\n\nAm Altar des Aufstiegs im Süden wacht ein alter Ettin namens Blindauge der Wächter.\n\nIn seinem Besitz befindet sich eine fein gearbeitete Axt aus Elementium. Ich frage mich, ob das wohl Cho'galls \"ultimative\" Waffe ist.", progress = "Habt Ihr die Axt?", completion = "Das ist eine verdammt scharfe Axt. Sie wird ihren Zweck erfüllen, aber ich für meinen Teil schätze, dass dies nicht die Bewaffnung ist, hinter der Cho'gall her ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27697] = {title = "Verderbnis in Maraudon", objective = "Tötet Lord Schlangenzunge und kehrt zu Zaetars Geist zurück.", description = "<Name>, ich benötige sofort Eure Unterstützung! Ich bin Zaetar, Sohn des Cenarius, und ich sitze hier aufgrund einer Reihe unglücklicher Ereignisse fest! Bevor man überhaupt daran denken kann, mich zu retten, müsst Ihr mir helfen, die Verderbnis, die von Maraudon Besitz ergriffen hat, auszumerzen.\n\nLord Schlangenzunge ist der Satyr, der über die purpurnen Kristallhöhlen herrscht. Er ist ein heimtückisches Mitglied der brennenden Legion und wird durch seine Anwesenheit Chaos und Tod bringen. Er darf nicht länger leben!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;! Schlangenzunges Tod ist ein wichtiger Schritt auf dem Weg zu meiner Rettung und letzten Endes auch zur Rettung dieses Landes vor der Verderbnis. Nehmt dies als Zeichen meiner Dankbarkeit und als Anregung, Eure Arbeit hier fortzusetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27698] = {title = "Diener von Theradras", objective = "Tötet Noxxion und Schlingwurzler und kehrt zu Zaetars Geist zurück.", description = "Prinzessin Theradras, meine ehemalige Gefährtin, hat ihre enormen Mächte benutzt, um die Natur von Maraudon selbst zu verderben. In diesem Moment wüten iher Geschopfe dort, und ich fürchte, dass sie bald in die Welt entkommen werden, um dort die Saat von Tod und Verwüstung zu streuen.\n\n<Name>, geht und tötet Noxxion und Schlingwurzler. Sie sind ihre zwei mächtigsten Diener, und ihre Tode würden der kaltherzigen Prinzessin verdientermaßen selbst Leid und Trauer bringen. Vielleicht könnt ihr mir dann helfen, meinen Geist aus ihrer Umklammerung zu befreien.", progress = nil, completion = "Ohne ihre mächtigen Diener ist Prinzessin Theradras wesentlich verwundbarer. Macht ihren Untschlupf ausfindig, &lt;Name&gt;... es ist an der Zeit, dass wir zuschlagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27699] = {title = "Unhaimlich", objective = "Sammelt 5 von Nagers Zähnen im Skelettriff.", description = "Das ist ein ganz schön starker Hai!\n\nIhr beschließt, dass es im besten Sinne aller wäre, wenn Ihr versucht, Budd abzulenken, damit er seine Aufmerksamkeit nie wieder auf Nager und dieses Skelettriff richtet.\n\nVielleicht erweisen die Zähne dieser Bestie sich als fesselnd genug...", progress = "Was habt Ihr da, Kumpel?", completion = "Was?!\n\nNager ist nicht tot?!\n\nDas macht meine Hoffnung auf das schnelle Gold wohl genauso schnell wieder zunichte…\n\nDiese riesigen Haizähne sind zwar ganz nett, aber wir dürfen nicht aufhören, bis der Glitzerkram uns gehört!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27700] = {title = "Der entfesselte Drache", objective = "Benutzt die Elementiumaxt, um die gefangene Lirastrasza aus ihren Ketten zu befreien.", description = "Lirastrasza ist der letzte und größte der roten Drachen, die der Schattenhammer gefangen hat. Sie stehen kurz davor, sie zu töten, <Klasse>.\n\nIhr müsst die Elementiumaxt nehmen und sie von ihren Ketten befreien.", progress = nil, completion = "Ist sie nicht wunderschön?\n\nIch bin gespannt, was sie jetzt mit ihrer Freiheit anstellt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27701] = {title = "Der entfesselte Drache", objective = "Benutzt die Elementiumaxt, um die gefangene Lirastrasza aus ihren Ketten zu befreien.", description = "Lirastrasza ist der letzte und größte der roten Drachen, die der Schattenhammer gefangen hat. Sie stehen kurz davor, sie zu töten, <Klasse>.\n\nIhr müsst die Elementiumaxt nehmen und sie von ihren Ketten befreien, bevor sie es tun.", progress = nil, completion = "Ist sie nicht wunderschön? So anmutig.\n\nIch hoffe, sie kann ihren Rachedurst stillen. Und noch viel mehr…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27702] = {title = "Gnadenstoß", objective = "Versetzt 5 Himmelsschrecken der Zwielichtdrachen einen Gnadenstoß.", description = "Schaut Euch das an! Lirastrasza vernichtet sie!\n\nIhr müsst jedoch noch ein paar der Drachen, die sie aus der Luft geholt hat, den Rest geben, <Name>. Wir wollen schließlich nicht, dass die Heiler des Schattenhammers sie wieder flugtauglich machen.\n\nEs wird Zeit für einen Gnadenstoß.", progress = nil, completion = "Unsere Bemühungen zur Verbesserung der Beziehungen zum roten Drachenschwarm haben sich wirklich ausgezahlt, &lt;Name&gt;.", rewards = "LebensmalmertreterKehlenschlitzerstulpenAuf Euch wartet eine dieser Belohnungen:\n\nUmverteiltes Signet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27703] = {title = "Gnadenstoß", objective = "Versetzt 5 Himmelsschrecken der Zwielichtdrachen einen Gnadenstoß.", description = "Schaut Euch das an! Lirastrasza vernichtet sie!\n\nIhr müsst jedoch noch ein paar der Drachen, die sie aus der Luft geholt hat, den Rest geben, <Name>. Wir wollen schließlich nicht, dass diese stinkenden Heiler des Schattenhammers sie wieder flugtauglich machen.\n\nEs wird Zeit für einen Gnadenstoß.", progress = nil, completion = "Welch Glück, dass Ihr und Kriegsfürst Krogg Euch mit den roten Drachen angefreundet habt.", rewards = "LebensmalmertreterKehlenschlitzerstulpenAuf Euch wartet eine dieser Belohnungen:\n\nUmverteiltes Signet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27704] = {title = "Legenden des Versunkenen Tempels", objective = "Begebt Euch durch die Vorräume des Tempels zur Halle der Masken.", description = "Ihr müsst zuerst den Tempel betreten, <Name>. Ich kann Euch folgen, wenn der Weg sicher ist, aber ich wage es nicht, blindlings hineinzugehen. Würde ich mich gegen mein Volk wenden, wäre ich ein gefährlicher Feind.\n\nIhr könnt die Treppen hinter mir hinuntersteigen. Dann schwimmt durch die überfluteten Tiefen der zerstörten Hallen. Danach folgt dem Tunnel zur Rechten, um zur Halle der Masken zu gelangen.\n\nNehmt Euch vor den Tempelwachen in Acht. Sobald Ihr die Halle der Masken gefunden habt, werde ich mich durch den Schwurstein mit Euch in Verbindung setzen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27705] = {title = "Erster Schritt: Die Priesterin", objective = "Besiegt Priesterin Udum'bra in der Kammer des Bluts.", description = "Meine Brüder werden hier abgeschlachtet. Genau, wie ich mir gedacht hatte.\n\nIch muss Euch nochmals um Hilfe bitten, bevor ich eintrete, <Name>. In einem Gang außerhalb dieses Raums führt der Weg nach rechts und links. Rechts geht es zur Kammer des Bluts. Dort führen die Atal'ai ihre finsteren Rituale durch.\n\nSie bereiten sich schon jahrelang auf einen Gegner wie mich vor, aber nicht auf einen wie Euch. Betretet die Kammer des Bluts und tötet Priesterin Udum'bra. Sie ist eine von drei bösartigen Präsenzen hier, die entfernt werden müssen, bevor ich eintreten kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27706] = {title = "Das Zepter von Orsis", objective = "Holt das Zepter von Orsis aus dem heiligen Gefäß.", description = "Das Schloss der Truhe öffnet sich mit lautem Klicken, als Ihr die beiden Steine in die Plakette einsetzt.\n\nNehmt das Zepter an Euch und bringt es zu General Ammantep.", progress = "Ihr seid zurück, <Name>.", completion = "Also... das ist es, was Al'Akir die ganze Zeit wollte.", rewards = "Beinplatten des SonnenbehütersKapuze des SkorpionsStangenwaffe von OrsisIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27707] = {title = "Das Gefängnis von Neferset", objective = "Geht in das Gefangenenlager von Neferset und findet etwas über den Aufenhaltsort Tahets heraus.", description = "Hieroglyphen, die einen angeketteten Tol'vir zeigen, befinden sich in der südöstlichen Ecke der Karte.\n\nVielleicht wurde Tahet dorthin gebracht, als man ihn gefangen nahm.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27708] = {title = "Die Zeit des Aufsehers", objective = "Erunak Steinsprecher möchte, dass Ihr Aufseher Azjakir in der Umklammerung tötet.", description = "<Erunaks Bildnis formt sich in Eurem Geist.>\n\nIhr habt gute Arbeit geleistet, <Name>, aber es bleibt noch eines zu tun.\n\nBevor wir von hier fortgehen, sollten wir ein wenig Unordnung stiften.\n\nFindet denjenigen, der diese Naga anführt und lasst ihn für seine Untaten bezahlen.", progress = nil, completion = "Es ist gut, dass ihre Pläne durchkreuzt wurden.\n\nBald muss ich weiterziehen…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27709] = {title = "Das Schildwachenspiel", objective = "Beendet das Spiel der Schildwache, indem Ihr die beiden roten Statuen miteinander verbindet.", description = "Als Ihr die Statue an ihren Platz setzt, erscheinen weitere Steinstatuen im Raum. In einem kleinen Gehäuse am anderen Ende des Raums erscheint auch eine rubinrote Statue. Ihr hört eine Stimme:\n\n \"Die Schildwache sieht.\n\n Die Schildwache beschützt.\n\n Der Blick der Schildwache versagt nie.\"\n\nDie rote Statue auf der anderen Seite des Raums erscheint Euch wichtig. Vielleicht solltet Ihr versuchen, die beiden roten Statuen miteinander zu verbinden?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27711] = {title = "Zurück in die Elementiumtiefen", objective = "Sprecht mit Initiand Goldmine vor den Elementiumtiefen im Schattenhochland.", description = "Der Initiand der Erdenruferin, Goldmine, braucht Euch.\n\nIch glaube, Ihr sollt ihn in dieser Mine unterstützen, was auch immer sich dort befinden mag.", progress = nil, completion = "&lt;Name&gt;, bin ich froh, dass Ihr zurück seid! Ich habe eine spaßige Aufgabe für uns beide!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27712] = {title = "Zurück in die Elementiumtiefen", objective = "Sprecht mit Initiand Goldmine vor den Elementiumtiefen im Schattenhochland.", description = "Die Erdenruferin hat einen Goblininitianden? Und er heißt Goldmine? Jedenfalls braucht er Euch.\n\nIch glaube, Ihr sollt für ihn die Drecksarbeit in dieser Mine erledigen, was auch immer sich dort befinden mag.", progress = nil, completion = "&lt;Name&gt;, bin ich froh, dass Ihr zurück seid! Ich habe eine spaßige Aufgabe für uns beide!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27713] = {title = "Der Tag, an dem Todesschwinge kam", objective = "Hört Euch Theldurins Geschichte an.", description = "Todesschwinge hat ein ganz schönes Chaos angerichtet, als er hier durchgekommen ist. Ohne mich wäre er wahrscheinlich noch immer hier und würde all die Einwohner des Ödlands umbringen.\n\nWas, Ihr glaubt mir nicht? Gut, lasst mich Euch die ganze Geschichte erzählen.", progress = nil, completion = "Eine ganz schöne Geschichte, nicht wahr? Jetzt wisst Ihr, warum Todesschwinge seitdem nicht mehr hierher zurückgekehrt ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27714] = {title = "Der Tag, an dem Todesschwinge kam: Die wahre Geschichte", objective = "Hört Euch Lucien Knobelzangs Version der Geschichte an.", description = "Theldurins Geschichte war nicht nur falsch, sie war langweilig, einfallslos und langatmig.\n\nIch sage Euch, was an dem Tag wirklich geschehen ist.", progress = "Ich bin noch nicht mit meiner Geschichte fertig. Setzt Euch wieder hin.", completion = "Ende! Und die Moral von der Geschicht' gibt es nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27715] = {title = "Der Tag, an dem Todesschwinge kam: Was wirklich geschah", objective = "Hört Euch Marteks Version der Geschichte an.", description = "Die beiden haben keine Ahnung, wie man eine Geschichte erzählt. Theldurins Geschichte war zu kurz und Luciens Erzählung war ein bisschen zu ausschweifend, falls Ihr versteht, was ich meine.\n\nAußerdem kamen in beiden Geschichten weder Nervenkitzel noch Fans vor, die meine Genialität bewundern.\n\nLehnt Euch zurück, <Name>. Ich erzähle Euch, was damals wirklich geschah.", progress = nil, completion = "Ich fasse es nicht, dass mich diese Typen einfach so unterbrochen haben. Und dabei lief meine Geschichte gerade so gut...\n\nWie dem auch sei, danke, dass Ihr so lange zugehört habt. Es ist schön, jemand neues zum Geschichten erzählen zu haben. Ich bin mir sicher, dass Lucien und Theldurin das genauso sehen.\n\nHabt Ihr eine Geschichte, die Ihr mit uns teilen wollt?", rewards = "Marteks MesserTheldurins FaustAuf Euch wartet eine dieser Belohnungen:\n\nKnobelzangs Schrumpfer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27716] = {title = "Ein Stück Vergangenheit", objective = "Bringt die uralte Elfengravur zu Levia Traumwächter. Ihr solltet sie bei den Überlebenden von Nespirah der Allianz finden.", description = "<Eine uralte, leicht zerbrochene Steintafel mit einer Unmenge von Inschriften auf allen Seiten. Ihr könnt die Sprache nicht lesen, aber die schiere Menge an Text und der fast ornamental wirkende Charakter des Steins lassen drauf schließen, dass er von großem Wert sein muss.>\n\n<Levia Traumwächter bei den Überlebenden von Nespirah hat genau nach so etwas gesucht.>", progress = "Ha! Habt Ihr gesehen, wie der Admiral mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint der Einzige zu sein, dem ich vertrauen kann. Wartet... was habt Ihr da?", completion = "Ausgezeichnet! Ich werde ein bisschen brauchen, bis ich es übersetzt haben, aber genau das hatte ich zu finden gehofft.\n\nKeine Ahnung, ob wir je von hier entkommen. Aber wenn es hart auf hart kommt, finde ich schon einen Weg, dies hier an die Oberfläche treiben zu lassen, damit es eines Tages gefunden wird.\n\nNochmals danke, &lt;Name&gt;. Hier... Vielleicht habe ich etwas, das Ihr gebrauchen könnt.", rewards = "Handschuhe der UmsetzungScharfsteinhelmFederkiel des SchreibersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27717] = {title = "Ein Stück Vergangenheit", objective = "Bringt die uralte Elfengravur zu Elendri Goldbraue. Ihr solltet sie bei den Überlebenden von Nespirah der Horde finden.", description = "<Eine uralte, leicht zerbrochene Steintafel mit einer Unmenge von Inschriften auf allen Seiten. Ihr könnt die Sprache nicht lesen, aber die schiere Menge an Text und der fast ornamental wirkende Charakter des Steins lassen drauf schließen, dass er von großem Wert sein muss.>\n\n<Elendri Goldbraue bei den Überlebenden von Nespirah hat genau nach so etwas gesucht.>", progress = "Ha! Habt Ihr gesehen, wie der Hauptmann mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint der Einzige zu sein, dem ich vertrauen kann. Wartet... was habt Ihr da?", completion = "Ausgezeichnet! Mit den Werkzeugen, die ich Euch gegeben habe, hätte ich nicht mehr erwarten können.\n\nIch sollte die Lücken füllen und den Text schnell in eine schriftliche Form bringen können. Keine Ahnung, ob wir je von hier entkommen. Aber wenn es hart auf hart kommt, finde ich schon einen Weg, dies hier an die Oberfläche treiben zu lassen, damit es eines Tages gefunden wird.\n\nNochmals danke, &lt;Name&gt;. Ihr seid nicht übel.", rewards = "Handschuhe der UmsetzungScharfsteinhelmFederkiel des SchreibersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27718] = {title = "Auf Befehl des Kriegshäuptlings: Vashj'ir!", objective = "Meldet Euch bei Kommandant Thorak in der Messerbucht in Durotar.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kommandant Thorak in der Messerbucht in Durotar zu melden.\n\nWir brauchen Eure Hilfe im Kampf gegen unseren verhassten Feind, die Allianz, mehr denn je!\n\nReist nach Süden durch das Haupttor von Orgrimmar nach Durotar. Folgt von dort aus dem Pfad nach Osten zur Küste. Dort findet ihr die Messerbucht. Thorak hält sich an seinem Posten in der Nähe der Docks auf.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", progress = nil, completion = "Lok'tar, Bruder! Ihr kommt genau rechtzeitig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27719] = {title = "Wasser des Lebens", objective = "Benutzt das Wasser des Lebens, um dem Leichnam von Schmiedemeister Finlay Informationen zu entlocken.", description = "Nehmt mein Wasser des Lebens und gebt es auf den Leichnam des ertrunkenen Zwergs.\n\nAls er lebte, bearbeitete er Metall. Und obwohl sein Leichnam jetzt meinen Loch nährt, kann er Euch dank des Wassers sagen, was Ihr wissen wollt.\n\nNehmt dann Eure Informationen und verschwindet von meinem Besitz.", progress = nil, completion = "Der Schattenhammer? Und diese Informationen habt Ihr also von einem ertrunkenen Zwerg der Wildhämmer?\n\nIhr macht Scherze, oder?", rewards = "Handschutz des verdammten GeistesSeelenwuchsschiftungGedankenversengender EntbeinerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27720] = {title = "Die wilde Fahrt des Herrn Goldmine", objective = "Fahrt zusammen mit Initiand Goldmine im Minenwagen bis zum Ende der Strecke.", description = "In Ordnung, <Name>. Wir müssen zum Erdportal an der anderen Seite der Höhle gelangen.\n\nIch habe ein Gefährt für uns \"gesichert\". Warum laufen, wenn man stilvoll fahren kann? Ich hoffe, Ihr habt nichts gegen Minenwagen.\n\nGebt mir Bescheid, wenn Ihr bereit seid.", progress = nil, completion = "Oh nein! Meine Waffen und Totems!\n\nSie sind dahin!!!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27721] = {title = "Auf Befehl des Kriegshäuptlings: Hyjal!", objective = "Sprecht mit Cenarius' Abgesandtem Schwarzhuf, um auf die Mondlichtung zu reisen.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandtem Schwarzhuf, um Zugang zur Mondlichtung zu erlangen. Schwarzhuf hält sich im Taurenviertel im Tal der Weisheit in Orgrimmar auf.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", progress = "Schwarzhuf schickt Euch?", completion = "Wir wussten, dass die Horde Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27722] = {title = "Auf Befehl des Kriegshäuptlings: Tiefenheim!", objective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar zu melden.\n\nDer Irdene Ring, der von unserem ehemaligen Kriegshäuptling Thrall angeführt wird, braucht unsere Hilfe! Es wurde uns berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen!\n\nDer Westliche Erdschrein befindet sich direkt nördlich des Tals der Weisheit.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", progress = nil, completion = "Unsere Welt ist in Gefahr, &lt;Name&gt;! Wir brauchen die Hilfe überragender Helden wie Ihr es seid, um sie zu retten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27724] = {title = "Heldenaufruf: Vashj'ir!", objective = "Sprecht mit Rekrutierer Burns im Hafen von Sturmwind in Sturmwind.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rekrutierer Burns im Hafen von Sturmwind zu melden.\n\nDie kürzlichen Angriffe der Horde auf unsere Handelsschiffe müssen schnell und gerecht geahndet werden!\n\nDer Hafen von Sturmwind befindet sich im Nordwesten von Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", progress = nil, completion = "All unsere Kriegsschiffe befinden sich bereits im Kampf gegen die Horde, also werdet Ihr ein Söldnerschiff nehmen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27725] = {title = "Jagdhütte Quel'Danil", objective = "Sprecht mit Anachoretin Traska bei der Jagdhütte Quel'Danil.", description = "Es mag Euch fern der Heimat erscheinen, <Klasse>, aber ein großer Teil meines Volkes wurde von Botschafter Rualeth hierher geführt. Wir haben uns bei den Hochelfen der Jagdhütte Quel'Danil im Nordwesten niedergelassen, um den Weg des Lichts zu erlernen und die friedliche Schönheit dieses Landes zu genießen.\n\nEin derartiger Frieden könnte sehr kurzlebig sein. Wir haben gesehen, dass die Horde sich weiter nach Westen bewegt. Könntet Ihr nach Quel'Danil reisen und Anachoretin Traska warnen? Ihre Hütte befindet sich etwas nördlich des Hauptgebäudes.", progress = nil, completion = "Yoro schickt uns eine Warnung vor der Horde? Die Elfen Hochtals haben einen Angriff bereits längere Zeit befürchtet. Um genau zu sein, haben wir...\n\n&lt;Schreie und der Klang berstenden Metalls sind aus dem Süden zu hören.&gt;\n\nBeim Lichte... sie sind hier!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27726] = {title = "Heldenaufruf: Hyjal!", objective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", progress = nil, completion = "Wir wussten, dass die Allianz Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27727] = {title = "Heldenaufruf: Tiefenheim!", objective = "Sprecht mit Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind zu melden.\n\nDer Irdene Ring braucht unsere Hilfe! Uns wurde berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen und alles Leben in Azeroth zu zerstören!\n\nDer Östliche Erdschrein befindet sich direkt nordwestlich der Burg Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", progress = nil, completion = "Unsere Welt ist in Gefahr, &lt;Name&gt;! Wir brauchen die Hilfe überragender Helden wie Ihr es seid, um sie zu retten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27729] = {title = "Noch einmaal mit Gefühl", objective = "Tötet 8 beliebige Aale im Tang'tharwald.", description = "Aale gehören zu den widerlichsten Wesen in ganz Azeroth.\n\nSicher, da gibt es diejenigen, denen sie angeblich egal sind. Und dann noch diejenigen, die sogar behaupten, sie zu mögen.\n\nSie lügen.\n\nIn Wahrheit mag nämlich niemand Aale. Nicht einmal Aale mögen Aale.\n\nAzeroth wäre ein besserer Ort, wenn niemand sich ausmalen müsste, wie ein glitschiger Aal sich aus den trüben Tiefen hervor windet und zubeißt.\n\nMitten ins Gesicht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27733] = {title = "Das gute alte Hütchenspiel", objective = "Tötet Randolph Moloch.", description = "Seht mal, ich würde ja liebend gern den Befehl geben und meine Männer diese Rebellen in Stücke sprengen lassen, aber das kann ich nicht, weil das gesamte Verlies unter Befehl von Aufseher Thelwasser steht, und er will sie im Moment nur einsperren.\n\nStatt sich Befehlen zu widersetzen, werden wir das Ganze auf andere Art lösen! Wir haben uns mit Mortimer Moloch angefreundet, der rein zufällig der Zwillingsbruder des ruchlosen Rebellenanführers Randolph Moloch ist. Tötet Randolph, und wir tauschen sie aus, sodass Mortimer die Rebellion friedlich beenden kann!", progress = nil, completion = "Ja, Mortimer hat gerade seinen eigenen Tod vorgetäuscht. Er wird vermutlich den Namen seines Bruders annehmen und seine \"epischen Pläne\" weiterführen. Damit müssen wir fertigwerden, wenn es soweit ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27737] = {title = "Lasst das Feuer Euch erretten!", objective = "Beschafft Fürst Gluthitzes Feuerkern.", description = "Ich kenne mich gut mit Erster Hilfe und anderen Formen des Heilens aus, und dank meines Lichtbrunnens ist es mir gelungen, vielen unserer Männer ihre Gesundheit zurückzugeben. Doch es ist so kalt und feucht hier unten, dass ich sie verliere, obwohl ich ihre Wunden geheilt habe!\n\nDie Beben haben die Elemente, die in dem Gefängnis hausen, verärgert... als sie aus der Erde emporbrachen, töteten sie die Hälfte der Gefangenen. Wenn Ihr ihren Anführer, Fürst Gluthitze, töten und mir seinen Kern bringen würdet, könnte ich meine Männer aufwärmen!", progress = "Habt Ihr den Kern? Unsere Männer sterben hier unten!", completion = "Wunderbar! Dank des Feuers werden unsere Männer diese Prüfung überstehen!\n\nVielen Dank, Held.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27738] = {title = "Die Schuppengrube", objective = "Rettet Tahet aus der Schuppengrube in Uldum.", description = "Ein Punkt am südlichen Rand der Karte wurde mit Hieroglyphen von gegeneinander kämpfenden Krokodilen markiert.\n\nDas muss der Ort sein, an den Caimas Tahet gebracht hat.\n\nBegebt Euch zur Schuppengrube und findet einen Weg, um den Sohn des Wesirs zu retten.", progress = nil, completion = "Ich danke Euch für das, was Ihr getan habt, &lt;Name&gt;. Ihr könnt Euch meiner Stimme sicher sein, wenn der Hohe Rat zusammentritt.", rewards = "Caimas' SchiftungGrubenherzarmschienenSchild des zurückkehrenden PrinzenGurt des RettersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27739] = {title = "Der König der Gnolle", objective = "Besiegt Hogger.", description = "<Name>, ich muss das Unmögliche von Euch verlangen.\n\nIch habe meine Augenklappe, weil er es wollte. Unzählige Unschuldige sind seinem Zorn zum Opfer gefallen. Nur durch ein Wunder konnten wir ihn hier einsperren.\n\nUnd das war ein schwerer Fehler. Wir haben so lange ausgehalten, wie wir konnten, doch dann kamen sie. Aus den Schatten und der Dunkelheit rissen Gnolle, die Hogger dienten, meine besten Männer in Stücke.\n\nIhr müsst den Gnollkönig besiegen, sonst wird er einen weiteren Angriff befehlen und uns alle in kaltem, blutdürstigen Zorn töten.", progress = nil, completion = "Eine Tat wie die Eurige habe ich in meiner langen Karriere noch nicht gesehen. Hoggers Tod wird noch auf Jahre hinweg einen Schatten auf die Flusspfotengnolle werfen und ihren Angriffen auf unser Volk hoffentlich ein Ende bereiten.\n\nHeld aller Helden, bitte nehmt dies als Zeichen meiner ewigen Dankbarkeit.", rewards = "Augenklappe des SchützenkommandantenKrawallbeenderSchild des VerliesesAuf Euch wartet eine dieser Belohnungen:\n\nHoggers Glitzerkram\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27740] = {title = "Baba Torfbräu", objective = "Redet mit dem verrückten Daisylein, um einen Kanonenkugelritt zu Baba Torfbräu zu unternehmen.", description = "Hey, während Ihr draußen wart, hat der Baron vorbeigeschaut! Hat mich so lange getreten, bis Geld herausgefallen ist!\n\nDas macht er aber immer so. Diesmal hat er mir aber noch aufgetragen, Euch etwas mitzuteilen! Er will, dass Ihr nach Süden geht und unserer Kräuterkundigen Baba Torfbräu helft.\n\nSie befindet sich auf der anderen Seite des Gewässers! Aber redet einfach mit meinem Mädchen Daisy draußen und sie wird Euch auf Art des verrückten Larrys dorthin bringen!", progress = nil, completion = "Ah, es ist so schön, Hilfe frei Haus zu bekommen.\n\nModerne Annehmlichkeiten... davon kann ich nie genug bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27742] = {title = "Ein kleiner Nebenerwerb", objective = "Sammelt 6 Elementiumsplitter.", description = "Wisst Ihr, es ist unsere moralische Verpflichtung, all das Elementium vor den Schieferspinnen zu retten. Diese widerlichen Biester fressen das Zeug!\n\nWas für eine Verschwendung!\n\nAlso, was meint Ihr? Teilen wir 90:10 für mich?", progress = "Was meint Ihr, wie viel könnt Ihr tragen?", completion = "&lt;Goldmine wirft einen schlitzohrigen Blick auf den Haufen mit Elementiumsplittern.&gt;\n\nHmm, ich glaube nicht, dass sich das Zeug gut verkaufen lässt. Am besten gebe ich Euch jetzt gleich Euren Anteil, damit Ihr Euch nicht übers Ohr gehauen fühlt.", rewards = "Armschienen der glänzenden ScherbenHelm des SplitterbewahrersAuf Euch wartet eine dieser Belohnungen:\n\nGoldflusshalskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27743] = {title = "Wo wir schon da sind", objective = "Tötet 12 Kultisten des Schattenhammers, entweder Tiefenaufseher oder Zwielichtminenarbeiter, in den Elementiumtiefen.", description = "Wenn Ihr schon hier seid, könnt Ihr Euch auch gleich um die Eindringlinge des Schattenhammers kümmern. Schließlich gehört dieser Ort uns!\n\nIch würde Euch ja helfen, aber da meine Totems und Waffen kaputt sind, bin ich ziemlich aufgeschmissen.", progress = nil, completion = "Sie haben es nicht besser verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27744] = {title = "Runenruinierung", objective = "Zerstört die Zwielichtrune der Erde, die Zwielichtrune des Wassers, die Zwielichtrune der Luft und die Zwielichtrune des Feuers.", description = "Als Ihr die Zwielichtrune der Erde untersucht, spürt Ihr, wie ihre Macht sich weiter in die Elementiumtiefen hinein erstreckt.\n\nWahrscheinlich ist sie mit den anderen Runen verbunden. Initiand Goldmine ist der Meinung, dass Ihr sie alle zerstören solltet.", progress = nil, completion = "Das wird ihnen zeigen, was passiert, wenn man in unser Gebiet eindringt!\n\nWas ist denn das da drüben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27745] = {title = "Ein feuriges Wiedersehen", objective = "Beschafft Euch die Feuerportalsteuerung und benutzt sie am Feuerportal.", description = "Das ist Magmazahn, mein Feuerelementar, mit dem ich mich zerstritten habe. <Name>, Ihr müsst ihn töten, sonst tötet er mich!\n\nEs war alles ein großes Missverständnis. Woher hätte ich denn ahnen sollen, dass er böse wird, wenn ich mir unten in Tiefenheim sein Herz \"ausleihe\"? Er kann nicht sterben... zumindest nicht dauerhaft!\n\nBestimmt hat er die Portalsteuerung bei sich. Ihr müsst ihm die Steuerung abnehmen und sie im Feuerportal benutzen, um uns zurück zum Eingang zu bringen.", progress = "<Name>!", completion = "Wir haben überlebt und alle Portale sind abgeschaltet!\n\nIhr glaubt doch nicht, dass Magmazahn mir das nachträgt, oder?", rewards = "Lavageschmolzene BeinplattenErweitererarmschienenMagmafeste SandalenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27746] = {title = "Königreich aus Dreck", objective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", description = "Dieser Krieg hat uns als Volk viel gekostet. Wir haben viel verloren, um unseren angestammten Platz als die rechtmäßigen Herrscher von Lordaeron zu sichern. Und obwohl wir für den Moment die Oberhand haben, tobt die Schlacht in anderen Teilen der Östlichen Königreiche weiter.\n\nIch muss nach Unterstadt zurück, um mich zu erholen. Ich möchte, dass Ihr an meiner Statt in das Vorgebirge des Hügellands reist, <Name>. Als <mein verdientester Soldat/meine verdienteste Soldatin> werdet Ihr unsere Streitkräfte in die absolute Vorherrschaft über unsere Feinde im Hügelland führen.\n\nMeldet Euch bei Hochexekutorin Darthalia am Südwachttor im Osten.", progress = nil, completion = "Die Kunde von Eurem Sieg im Silberwald ermutigt uns, &lt;Name&gt;. Wir sind bereit, unter Eurem Kommando zu kämpfen und die letzten Überreste der Menschheit aus dem Hügelland zu vertreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27747] = {title = "Flammenkrieg", objective = "Zerschmettert 10 Fässer mit Donnermarbier in den Ruinen von Donnermar.", description = "Viele Wildhämmer sind bereits aus ihren Heimen geflohen. Jetzt ist es Zeit, sie vollständig von der Karte zu tilgen.\n\nOben auf dem Grat im Norden findet Ihr verlassene Häuser in den Ruinen von Donnermar. Dort haben sie viele Fässer mit starkem Donnermarbier zurückgelassen.\n\nDonnermarbier hat einen Alkoholgehalt von 220 Prozent. Ich habe keine Ahnung, wie das überhaupt geht.\n\nZerschlagt die Fässer und zündet ihren Inhalt an. Brennt sie aus! Lasst den Zwergen nichts, zu dem sie zurückkehren könnten.", progress = nil, completion = "Ja, ja. Treibt sie mit Feuer hinaus, wie Murmeltiere aus ihren Löchern…\n\nGut gemacht, &lt;Name&gt;.", rewards = "Brustschutz des WundenversorgersBierfeuerarmschienenFassbersterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27748] = {title = "Glück und Ruhm", objective = "Tötet den Obsidiankoloss.", description = "Wir müssen in Bewegung bleiben, <Name>. Es ist nur eine Frage der Zeit, bevor die Truppen die Kurve kriegen.\n\nDie Lade sollte sich direkt hinter diesen Ruinen befinden.\n\nSeid wachsam. Irgendwie habe ich das Gefühl, dass es noch nicht vorbei ist.", progress = nil, completion = "Schön zu sehen, dass Ihr unversehrt seid, &lt;Name&gt;.", rewards = "KolossbrecherbrustplatteHarrisons KletterhakenPfeildornlangbogenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27750] = {title = "Schlacht am Buffet", objective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", description = "<Griffs Magen knurrt.>\n\nImmer, wenn das Drachenmal in den Krieg zieht, geht keiner mehr jagen.\n\nDas beste Essen schnappen wir den Feind direkt vor dem Mund weg. Auf dem Grat nördlich des Flusses gibt es eine Reihe von zerstörten Häusern der Wildhämmer. Ich wette, sie sind randvoll mit Köstlichkeiten.\n\nBringt mir etwas davon.", progress = "Hunger.", completion = "&lt;Griff stürzt sich gierig auf den Haufen von Nahrungsmitteln, genug, um ein Dutzend Männer zu ernähren.&gt;\n\nToll! Habt Ihr für Euch selbst auch etwas mitgebracht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27751] = {title = "Vernichtet die Wildhämmer", objective = "Tötet Kriegsgezeichnete der Wildhämmer, um 8 Insignien der Wildhämmer zu sammeln. Auch einzigartige Gegner in den Ruinen von Donnermar tragen Insignien bei sich.", description = "Seit mein Volk Anspruch auf das Hochland erhoben hat, sind die Wildhammerzwerge unsere erbittertsten Feinde. Wir haben sie in Grim Batol bekämpft, wir haben sie im Sumpfland bekämpft und selbst jetzt tobt ein offener Krieg im Norden, jenseits des Flusses in den Ruinen von Donnermar.\n\nBeweist mir Euren Wert. Sucht und vernichtet die Kriegsgezeichneten der Wildhämmer. Die Besten unter ihnen tragen Insignien. Meine Krieger sammeln sie gleich dutzendweise.\n\nKönnt Ihr das auch?", progress = "Zeigt mir die Insignien, die Ihr gesammelt habt, <Klasse>.", completion = "&lt;Narkrall schließt seine wettergegerbte Faust fest um die Insignien.&gt;\n\nAlso, &lt;Klasse&gt;. An Euch ist mehr dran, als ich erwartet habe.\n\nVielleicht kann Eure Horde es mit meinen besten Kriegern aufnehmen. Finden wir es heraus…", rewards = "TotzwergschulterpolsterGürtel der zermalmten FedernGehämmerte ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27752] = {title = "Kämpfen wie ein Wildhammer", objective = "Sammelt 10 Fässer voll Donnermarbier aus den Ruinen von Donnermar. Vorsicht! Es hat ganz schön Bumms!", description = "Ich übertreibe nicht, wenn ich sage, dass wir in Donnermar das beste Bier in den Östlichen Königreichen brauen. Es hat 220 Prozent! Ja, Ihr habt ganz richtig gehört!\n\nAls die verschiedenen Familien sich aus dem Süden in die Mitte der Stadt zurückgezogen haben, mussten sie ihr Bier zurücklassen.\n\n<Blundy hält inne, um die Schwere der Situation einsinken zu lassen.>\n\nHOLT ES ZURÜCK! Dieses Zeug macht selbst den trägsten Krieger zu einem wirbelnden Derwisch der tollwütigen Zerstörung. Holt Euch diese Fässer! Sie sind unsere einzige Hoffnung!", progress = "Bringt mir dieses Bier, <Name>.\n\nHe, Ihr habt doch nicht daran genippt, oder?", completion = "Oh, perfekt… Ich werde ein paar dieser Fässer zu meinen Jungs an der Front bringen. Dann geht der Tanz erst richtig los! Vielen Dank, &lt;Name&gt;.", rewards = "Blundys BrustplatteArmschienen des FassdiebesFassöffnerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27753] = {title = "Kein Essen zurücklassen", objective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", description = "Unsere Vorräte sind knapp bemessen, <Name>. Von überall strömen Flüchtlinge nach Donnermar. Das sind ganz schön viele Mäuler, die gestopft werden wollen.\n\nViele Nahrungsmittel wurden zurückgelassen, als die Leute mit ihren Familien in die Sicherheit geflohen sind. Wir brauchen dieses Essen!\n\nDurchsucht die Ruinen von Donnermar südlich, östlich und südwestlich von hier nach ihren Nahrungsmittellagern.\n\nSeid vorsichtig, <Klasse>! Um die Ruinen herum wird heftig gekämpft.", progress = "Habt Ihr was zu Beißen?", completion = "Ah, gut - und kaum eine Made oder Käfer zu finden!\n\nDas wird den Leuten, die hierher geflohen sind, das Leben retten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27754] = {title = "Abreibung für das Drachenmal", objective = "Tötet Marodeure des Drachenmals und sammelt 8 Insignien des Drachenmals. Auch einzigartige Gegner in den Ruinen von Donnermar tragen Insignien bei sich.", description = "Das Drachenmal!\n\n<Colin spuckt aus.>\n\nMonster! Alles Monster! Seit dem letzten Krieg bekämpfen wir uns auf jedem gottverdammten Hügel und in jedem Tal. Und jetzt schließen sie sich der Horde an?\n\nWenn Ihr uns Wildhämmer dazu bringen wollt, uns mit Euch unter dem Banner der Allianz zusammenzutun, dann solltet Ihr Euch am besten im Kampf gegen das Drachenmal beweisen. Stürzt Euch in die Schlacht, die in den Ruinen von Donnermar im Süden und Südwesten tobt. Tötet die Marodeure des Drachenmalklans und sammelt die Insignien ihrer besten Krieger. Dann reden wir weiter.", progress = "Wie läuft der Kampf, <Klasse>?", completion = "Schau sich das einer an! Da habt Ihr aber eine beeindruckende Trophäensammlung.\n\nIch werde den anderen davon berichten. Wenn ein einzelner &lt;Klasse&gt; der Allianz das erreichen kann, kaum vorzustellen, was der Rest von Euch zu leisten vermag!", rewards = "OrcschockschiftungGürtel der blutigen TräumeArmschienen des TrophäengewinnersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27755] = {title = "Der Fluch der Gräber", objective = "Tötet 6 wahnsinnige Gräber und Robogenieur Mischgeweb.", description = "Die Neferset sind nicht die einzige Bedrohung unserer geheiligten Gräber.\n\nEine Expedition der Gnome stolperte vor einigen Wochen in unsere Lande.\n\nSie haben nicht auf unsere Warnungen gehört und sich zu tief in ein verfluchtes Gewölbe hineingegraben.\n\nJetzt liegt auf der gesamten Expedition ein furchtbarer Fluch, der ihnen den Verstand geraubt und ihre Gedanken übernommen hat.\n\nNun suchen sie Zugang zu den tiefsten Gewölben Uldums und bilden eine große Bedrohung. \n\nGeht zu der Sonnensteinterrasse und erlöst ihre getriebenen Seelen von ihrem Elend.", progress = nil, completion = "Es war nicht möglich, sie zu retten, &lt;Name&gt;. Der uralte Fluch, der sie befallen hat, kann nicht von ihnen genommen werden.", rewards = "GrabbrecherkolbenVeruntreuter Gurt von KhartutArmschienen der saftgrünen WiegeRobe von KhintasetIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27756] = {title = "Der Vorarbeiter", objective = "Tötet Glubtok.", description = "Wenn wir herausfinden wollen, was hier vor sich geht, müssen wir uns wohl durch die gesamten Todesminen schlagen! Glubtok der Vorarbeiter wird der erste ernsthafte Gegner sein, auf den Ihr trefft, ein mächtiger Ogermagier. Seid vorsichtig, er verfügt über die rohe Kraft seiner Spezies, kombiniert mit seinen verruchten Zauberkünsten!\n\nNehmt diesen Kommunikator, damit ich mit Euch in Verbindung bleiben kann, während wir mit den Untersuchungen voranschreiten. Seid vorsichtig da unten.", progress = "Ja?", completion = "&lt;Bzzzzzzzzzzzzt.&gt;\n\nGut gemacht! Saubere Arbeit. Dringt nun weiter vor und seht, was Ihr sonst noch aufspüren könnt! Mit Euch auf unserer Seite knacken wir diesen Fall wie eine Walnuss. Ich weiß es genau.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27757] = {title = "Die dunkelsten Abgründe", objective = "Tötet Hr'nglth den Verirrten.", description = "Ich habe im ganzen Sumpf gesehen, wie seltsam sich die Meereskreaturen verhalten. Die Murlocs, ja, aber vorher auch die Gilblins und die Makrura... ich habe neulich sogar einige Naga an den Strand wandern sehen.\n\nIrgendetwas ruft sie hierher, und peitscht sie zur Raserei auf. Viele der Kreaturen wurden in die Stagalsumpfhöhle im Westen gelockt. Da unten ist irgendetwas, und wenn es noch stärker wird, werden wir alle auch anfangen, hineinzuwandern...\n\nIhr solltet es aufhalten, was immer es auch ist. Bevor es zu spät ist.", progress = nil, completion = "Oje. Es klingt als wärt Ihr einem ziemlich finsteren Wesen über den Weg gelaufen. Ich frage mich nur, was einer von denen so weit hier draußen wollte...", rewards = "Babas BeinwärmerWeste des Rufs der RasereiSumpfschädelkappeFinsterer GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27758] = {title = "Der Zimmermann", objective = "Besiegt Helix Ritzelbrecher.", description = "<Bzzzzzzzzzzzzt.>\n\nHallo? Könnt Ihr mich hören? Ausgezeichnet!\n\nEs scheint, als wäre Helix dabei, einen riesigen Mast zu bauen. Ihr glaubt doch nicht, dass er versucht, den Moloch der Defias fertigzustellen, oder?\n\nDas solltet Ihr lieber untersuchen, <Name>. Und scheut Euch nicht, Euch die Hände schmutzig zu machen! Ihr habt die Erlaubnis, bei Bedarf tödliche Gewalt anzuwenden. Und offen gestanden wird das wahrscheinlich auch nötig sein.", progress = nil, completion = "&lt;Bzzzzzzzzzzzzt.&gt;\n\nHe, hier ist Horatio. Das war aber spannend! Ich verfolge Eure Fortschritte auf der Spionatron X3-Funktion auf meinem Sturmwind-Kommunikator.\n\nSie verstecken ihr Werk aber hinter ganz schön vielen verstärkten Türen. Rückt weiter vor und schaut, was Ihr als nächstes finden könnt. Ich wette, es wird ein ganz großer Hinweis sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27760] = {title = "Künstliche Intelligenz", objective = "Sprecht mit dem A.I.D.A.-Terminal am Feldmesserposten in Uldum.", description = "<Eine weibliche Stimme spricht aus dem tragbaren Terminal zu Euch.>\n\nNotfallcode: 55-729\n\nFunktionen des oberen Zerebralkortex der Expeditionsmitglieder sind gestört.\n\nBitte beim nächsten Terminal im Südosten der Sonnensteinterrasse für weitere Analysen melden.", progress = "<Der Terminal surrt, als seine Mechanismen sich in Gang setzen.>", completion = "Scanne Objekt... \n\nZerebralkortexdiagnostik zeigt keine Anzeichen des \"Grabfluch\"-Phänomens.\n\nDiagnostik enthüllt diverse Schädeltraumata. Dem Nutzer wird empfohlen, in Zukunft in der Nähe stumpfer Gegenstände größere Vorsicht walten zu lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27761] = {title = "Eine bombige Ablenkung", objective = "Entschärft den ersten, zweiten und dritten Sprengsatz und deaktiviert 4 instabile Bombenbots am Grab des Sonnenkönigs.", description = "Der Fluch hat die höheren Gehirnfunktionen der Expeditionsmitglieder übernommen. Doch meine Berechnungen zeigen, dass ihr unterdrücktes, jugendliches Unterbewusstsein durch realistische Bilder stimuliert werden kann.\n\nBenutzt diesen Holoprojektor, um sie abzulenken.\n\nSie sind gerade dabei, Sprengsätze in dem Grab im Osten anzubringen, weil sie versuchen wollen, Zugang zu den Geheimgängen Uldums zu erlangen.\n\nSie suchen gefährliche Neuerschaffungstechnologie unter Uldum und müssen aufgehalten werden.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Expedition hat sich bereits selbst dem Untergang geweiht.\n\nEs gibt keinen Grund, den Rest der Welt auch noch in Gefahr zu bringen.", rewards = "GrabesfluchbrustplatteTreter des sternbedeckten ObeliskenHirnfraßgriffelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27762] = {title = "Auf nach Luntenbrand!", objective = "Fliegt auf der Unkaputtbaren ins Ödland und meldet Euch dort bei Eddie Flofizzle.", description = "He, <Volk>, hört mal her. Ich habe einen Auftrag, den Ihr Euch sicher nicht entgehen lassen wollt.\n\nWir wurden aus Luntenbrand, einer neuen Goblinstadt tief im Ödland, hier hoch geschickt. Da unten gibt es jede Menge Geld zu verdienen! Außerdem treiben sich dort nicht annähernd so viele Zombies oder verklemmte Paladine herum.\n\nWeit und breit nur ungezähmte Wildnis da unten und wir suchen nach jemandem, der uns dabei hilft, das zu ändern. Wenn Ihr soweit seid... wir warten auf Euch.", progress = nil, completion = "Hübsche Landung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27763] = {title = "Ins Zentrum von Luntenbrand", objective = "Benutzt den Teleporter an der Rückseite von Luntenbrand-am-Meer, um auf den Berg zu gelangen, und meldet Euch dann bei Dolph Blastus in Luntenbrand im Ödland.", description = "Das hier, <Volk>, ist das Paradies. Ich wollte schon immer in einer netten, ruhigen Stadt am Meer leben, damit ich mich ganz ohne Ablenkungen auf meine Explosionen konzentrieren kann.\n\nRuhe ist jedoch nicht jedermanns Sache. Besonders, wenn man eher der abenteuerlustige Heldentyp ist, so wie Ihr.\n\nWir haben am anderen Ende der Stadt einen Teleporter installiert, der Euch auf die Klippen bringt. Von dort aus könnt Ihr den kurzen Ritt Richtung Westen ins Zentrum von Luntenbrand wagen, mitten im Ödland.\n\nDort sollte es mehr für Euch zu tun geben. Sagt einfach, dass Flo Euch schickt.", progress = nil, completion = "Willkommen in Luntenbrand!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27764] = {title = "Eine seltsame Bitte", objective = "Bringt Dolphs Paket zu Rhea in der Lethlorklamm im Ödland.", description = "Kommen wir zu etwas anderem. Ich habe ein Paket, das geliefert werden muss.\n\nVor nicht allzulanger Zeit kam eine junge Dame in unsere Stadt, die komprimiertes Sprengpulver, eine gehärtete Mithrilbombenhülle und eine Schutzbrille wollte. Natürlich konnten wir ihr eine Menge Sprengpulver und Bombenhüllen verkaufen, aber die Schutzbrille war etwas schwieriger zu beschaffen.\n\nUm es kurz zu machen: Ich habe die Schutzbrille, aber sie ist schon zu ihren Studien in der Lethlorklamm zurückgekehrt. Bringt ihr sie für mich zu ihr?", progress = "Ahh... Ihr habt mich gefunden. Gut.", completion = "Ich danke Euch, &lt;Volk&gt;. Die Schutzbrille könnt Ihr behalten, da sie ja bereits ihren Zweck erfüllt hat: sie hat Euch zu mir gebracht.", rewards = "Verlockende GamaschenLethlorarmbänderStiefel der LieferungBrustplatte des PäckchenträgersIhr bekommt:\n\nSchutzbrille"}
MultiLanguageQuestData['de'][27765] = {title = "Erste Probe: Wilde Eier", objective = "Besorgt 6 Eier von wilden Schwarzdrachen.", description = "Ich experimentiere mit Schwarzdrachen. Genauer gesagt interessiere ich mich für ihre Fortpflanzung.\n\nFür meine aktuellen Experimente benötige ich viele Schwarzdracheneier, weshalb ich hier in der Lethlorklamm bin. Ich würde die Eier ja selbst sammeln, aber ich glaube, es wäre zu Eurem Nutzen, wenn Ihr mir dabei helfen würdet.\n\nIhr könnt sie am Rand der Schlucht finden. Hütet Euch vor den Wächtern, die oben kreisen - sie freuen sich nicht über Eierdiebe.", progress = "Habt Ihr die Eier dabei?", completion = "Danke, dass Ihr sie so schnell gesammelt habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27766] = {title = "Zweite Probe: Welpen", objective = "Besorgt 10 Kadaver von brühenden Welpen.", description = "Ihr müsst mir noch einen Gefallen tun. Ihr müsst mir die Körper der Schwarzdrachenwelplinge bringen, die in der Nähe herumfliegen. Tötet sie und bringt mir ihre Leichen.", progress = "Seid Ihr meiner Bitte nachgekommen?", completion = "Diese grausige Aufgabe war notwendig, &lt;Name&gt;.\n\nAlles wird sich Euch bald offenbaren. Fürs Erste nur soviel:\n\nIch bin kein gewöhnlicher Goblin.\n\nIch diene einer Herrin von unvorstellbarer Macht und ihre Beweggründe sind nicht so finster, wie sie erscheinen mögen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27768] = {title = "Zweiter Schritt: Der Blutvergießer", objective = "Tötet Gomora den Blutvergießer im Schlachthof.", description = "Die Trolle hier setzen den Fall meiner Brüder in den Alptraum ewig fort. Sie infizieren und korrumpieren grüne Drachen mit dem Blut ihres verruchten Gottes, und ernten dann das Böse, das in ihnen gediehen ist. Sie werden wie Vieh gezüchtet...\n\nDiese ekelerregenden Untaten dürfen nicht fortgesetzt werden. Kehrt zum Ausgang der Halle der Masken zurück und nehmt den anderen Korridor in Richtung des Schlachthofs. Gomora der Blutvergießer erntet dort Leichen für diese abscheulichen Rituale. Entledigt ihn seines unverdienten Lebens!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27769] = {title = "Rhea enthüllt", objective = "Erfahrt Rheas wahre Identität.", description = "Wie schon angedeutet bin ich kein gewöhnlicher Goblin. Vielleicht habt Ihr meine wahre Identität bereits erraten.\n\nLasst mich Euch meine wahre Form zeigen. Da Ihr Euch als vertrauenswürdig erwiesen habt, werde ich die Details meines Planes mit Euch teilen.", progress = "Ihr seid aber ungeduldig, <Name>.", completion = "Mein wahrer Name ist Rheastrasza und ich bin eine Abgesandte von Alexstrasza, dem Aspekt des roten Drachenschwarms.\n\nDa Todesschwinge derzeit mit anderen Dingen beschäftigt ist, werden wir einen Weg finden, um den schwarzen Drachenschwarm zu erlösen.\n\nUnd Ihr werdet uns dabei helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27770] = {title = "Den Schleier lüften", objective = "Werdet Zeuge des letzten Teils von Rheas Studien.", description = "Der schwarze Drachenschwarm war einst nobel. Sie waren die Bewacher der Erde und schützten die Lande. Welch Ironie, dass ausgerechnet sie zur schlimmsten Bedrohung wurden, die das Land je erlebt hat.\n\nIch glaube aber, dass es noch einen Funken Hoffnung gibt - und meine Herrin sieht das ebenso. Der schwarze Drachenschwarm wird auch nach Todesschwinges Verrat weiter existieren und wieder als nobler Bewacher der Erde zum Himmel aufsteigen.\n\nIch möchte Euch etwas zeigen. Schließt Eure Augen und ich werde Euch den letzten Teil meiner Studien enthüllen.", progress = "Ihr seid äußerst ungeduldig, <Name>.", completion = "Wir werden noch einen Funken Gutes in diesen Drachen finden, &lt;Name&gt;. Entweder in den wilden Eiern, die Ihr gefunden habt, in den Körpern der Welplinge, die Ihr getötet habt, oder in den Eiern, die Nyxondra gelegt hat, als wir sie dazu ermutigten... Wir werden einen unverdorbenen schwarzen Drachen finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27771] = {title = "Dritte Probe: Implantierte Eier", objective = "Beschafft 3 von Nyxondras Eiern.", description = "Nyxondra wird gegen ihren Willen festgehalten. Sie wird mitten in den Brutstätten vor ihrem eigenen Schwarm versteckt. Sie legt zwar Eier, aber man nimmt sie ihr weg, bevor sie sie ausbrüten kann.\n\nGrausam? Vielleicht... Aber nicht annähernd so grausam wie das, was ihr Drachenschwarm meiner Herrin angetan hat.\n\nBeweist mir, dass ich Euch vertrauen kann, <Name>. Bringt Nyxondras Eier zu mir. Ihr müsst Nyxondra schlagen, bis sie sich fügt, bevor Ihr die Eier nehmen könnt.", progress = "Vergesst nicht, <Name>... Dies geschieht zum Wohl des schwarzen Drachenschwarms. Wir sind hier, um ihn zu erlösen, nicht, um ihn zu verletzen. Dies ist nur ein Schritt auf dem Weg zu seiner Gesundung.", completion = "Ihr habt alles, was ich Euch aufgetragen habe, ohne zu fragen erledigt. Unsere Arbeit hier in der Lethlorklamm ist getan.\n\nJetzt ist es an der Zeit, dass ich Euch in alles einweihe.", rewards = "Stiefel der NötigungWeste der ZurückhaltungZwingende SchulterstückeStarkarmstreitkolbenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27772] = {title = "Der ehrwürdige Doktor Blam", objective = "Bringt die Proben der schwarzen Drachen zu Dr. Hieronymus Blam auf der Agmondkuppe im Ödland.", description = "Ich habe eine ganz bewusste Entscheidung getroffen, als ich mich Euch zu erkennen gab, <Name>. Ich brauche Euer Vertrauen, aber ich kann nicht länger hier in der Lethlorklamm bleiben, da meine Verkleidung ganz klar aufgeflogen ist.\n\nIhr jedoch könntet unentdeckt entwischen. Hier, nehmt die Ergebnisse unserer Forschungen und bringt sie nach Westen. Auf der Agmondkuppe werdet Ihr einen Gnom finden, der weiß, was mit diesen Proben zu tun ist.\n\nBeeilt Euch, <Name>! Ihr dürft hier nicht herumtrödeln!", progress = "Dr. H. Blam, zu Euren Diensten. Wie kann ich Euch heute behilflich sein?", completion = "Ooh! Wissenschaftszeug! Dann lasst uns mal sehen, was Ihr da habt...\n\nWilde Eier? Bäh. Nutzlos. Damit kann doch niemand etwas anfangen.\n\nOoooh, was ist das? Eine Art... vorkonstruiertes Ei? Das sieht vielversprechend aus, aber ich will lieber nicht wissen, was Rhea tun musste, um es zu bekommen.\n\nHmm... ja, ein paar wirklich nette Leichen. In der Tat, sehr nett.\n\nIn Ordnung, ich werde sehen, was ich tun kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27773] = {title = "Dritter Schritt: Prophet", objective = "Bezwingt Jammal'an den Propheten.", description = "Alles, was jetzt noch zwischen mir und dem Tempel steht, ist Prophet Jammal'an selbst. Er ist der Anführer der Atal'aitrolle hier, ein bösartiger Manipulator.\n\nWisset, dass Ihr nicht bloß auf einen verrückten Troll treffen werdet, <Name>, sondern auf ein Instrument von Kräften, die Eure finstersten Vorstellungen übertreffen. Doch Ihr kämpft nicht allein... Meine Stärke und der Wille des grünen Drachenschwarms werden Euch begleiten.\n\nBegebt Euch zum Höhlenbau des Rufenden, links durch die Halle des Rituals, und von da in die Halle der Knochen. An ihrem unteren Ende werdet Ihr Jammal'an finden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27774] = {title = "Einfach zu beeinflussen", objective = "Tötet 9 Staubspeieroger in Camp Kosh", description = "Die größte Bedrohung für Luntenbrand ist zweifellos die Ogerkolonie im Nordwesten.\n\nDie meisten unserer Ogernachbarn waren Kriegertypen, aber es sieht aus, als würden mehr und mehr von ihnen Magie ausüben. Ich werde keine Ogermagier vor meiner Haustür zulassen.\n\nGeht und macht ein paar dieser Staubspeieroger unschädlich. Hoffentlich lassen sie sich das eine Lehre sein und legen sich nicht mehr mit der Macht von Luntenbrand an.", progress = nil, completion = "Ich frage mich, wo all diese Ogermagier herkommen. Wahrhaftig erstaunliche Zeiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27775] = {title = "Wenn's mal wieder schwerer wird, improvisiere!", objective = "Beschafft eine Instrukteursrute von den Instrukteuren der Ogermagier in Camp Kosh.", description = "Ich schaffe es einfach nicht, meine Erfindung in Gang zu bringen. Gah!\n\nDas ist es! Ich habe eine Entscheidung getroffen. Ich werde improvisieren und Magie verwenden.\n\nWas meiner Erfindung wirklich fehlt ist ein solider Kolben, der dünn genug ist, um durch ein schmales Kupferrohr zu passen. Dabei muss er auch stark genug sein, um regelmäßigen Stößen widerstehen zu können. Die magischen Ruten, die die Ogermagier nördlich von hier bei sich tragen, sind genau das Richtige.\n\nSoweit ich weiß, tragen nur die Instrukteure Ruten, die stark genug sind.", progress = "Ich lasse mich nur ungern dazu herab, Magie in meinen Erfindungen einzusetzen, aber in diesem Fall handelt es sich praktisch um einen Notfall.", completion = "Passt perfekt! Mein Ziegenschläger ist endlich vollendet!", rewards = "Wollige ZiegenschlägerZiegenhautmaskeZiegenlederstiefelKettenrüstung aus LuntenbrandAuf Euch wartet eine dieser Belohnungen:\n\nZiegenhornband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27776] = {title = "Zeit für Ziegen, Baby", objective = "Benutzt Garyannes Ziegenboxer an 12 Ziegenböcken in Luntenbrand.", description = "Falls es Euch entgangen sein sollte, wir haben hier in Luntenbrand ein kleines Ziegenproblem. Sie fressen alles und scheinen eine Vorliebe für die Häufchen aus Zahnrädern und Getrieben, die wir überall herumliegen lassen, zu haben.\n\nDas wird allmählich wirklich lästig!\n\nIhr findet die meisten Ziegenböcke am Rande der Stadt in der Nähe der Klippen. Benutzt dieses Gerät, um ihnen einen kleinen \"Schubs\" zu geben.", progress = nil, completion = "Gut gemacht! Zweifellos werden die Ziegen zurückkommen, aber sie werden es sich zweimal überlegen, ehe sie noch einmal an meinen Zahnrädern knabbern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27777] = {title = "Kernzugriffcodes", objective = "Beschafft die Kernzugriffscodes von Pfuschelflux dem Wahnsinnigen.", description = "Die Zahl der Expeditionsteilnehmer ist sehr groß, Nutzer <Name>.\n\nSich mit normalen Mitteln um sie zu kümmern würde geschätzte 2.700.136,5 Stunden dauern.\n\nWir können uns einer mächtigen Energiequelle bedienen, die sich in dem Raupenfahrzeug der Expedition befindet.\n\nDazu müssen wir allerdings die Zugangscodes für den Fusionskern finden.\n\nRobogenieur Pfuschelflux hat diese Codes und befindet sich im Sternbeobachtungsturm im Südosten.\n\nIch habe einen Scrambler mit Störfrequenzen gefüttert. Benutzt ihn, um Pfuschelflux' Schutzmechanismen vorübergehend außer Kraft zu setzen.", progress = "Hattet Ihr Erfolg, <Name>? Ich hatte Eure Überlebenschance mit 68,5 % berechnet.", completion = "Ausgezeichnete Arbeit, Nutzer &lt;Name&gt;. Jetzt müssen wir uns Zugang zum Fusionskern verschaffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27778] = {title = "In den Wibson hacken", objective = "Hackt Euch in den Wibsongroßrechner an Bord der M.A.C. Dyver.", description = "Es ist wahr. Neue Expeditionsmannschaften sind auf dem Seeweg eingetroffen.\n\nMeine Scanner haben entdeckt, dass sie bereits von dem Fluchphänomen befallen sind.\n\nIhr müsst Euch beeilen und sofort an Bord der M.A.C. Dyver gehen. Die Zugangscodes werden uns die Kontrolle über die Funktionen des Fusionskerns geben, doch wir müssen noch einen Sicherheitslevel umgehen.\n\nNutzer <Name>, ich muss Euch bitten, Euch in einen sehr ausgefeilten Großrechner bekannt als der \"Wibson\" zu hacken.\n\nKeine Sorge, ich werde Euch weitere Instruktionen zukommen lassen.", progress = "Seid gegrüßt, Nutzer <Name>.", completion = "Ich habe alles unter Kontrolle, Nutzer &lt;Name&gt;. Aber ich kann die Kerntemperatur nicht auf unbestimmte Zeit stabil halten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27779] = {title = "Auslöschung der Gnome", objective = "Löscht 1000 wahnsinnige Gnome aus.", description = "Ich habe mein Programm in den Fusionskern geladen und habe jetzt die volle Kontrolle darüber.\n\nIch habe eine kleine Luftblase darin geschaffen, um zu verhindern, dass Nutzer <Name> pulverisiert wird.\n\nIch werde eine Steuerung für all meine Bewegungsfunktionen generieren, damit ich meine Schaltkreise der Stabilisierung des Kerns widmen kann.\n\nGeht den Hügel hinunter und neutralisiert so viele Expeditionsmitglieder wie möglich.\n\nMeine Analyse hat ergeben, dass Ihr möglicherweise... \"Schuld\" empfinden könntet bei solch einer großen Anzahl Todesfälle.\n\nNutzer <Name>, Ihr müsst Euch darüber klar sein, dass es keine Hoffnung für die Expeditionsmitglieder gibt.", progress = "Das Ableben der Expeditionsmitglieder ist bedauerlich.", completion = "Es ist vollbracht, Nutzer &lt;Name&gt;. Ich danke Euch für Eure Hilfe bei dieser bedauernswerten Aufgabe.", rewards = "Handschuhe des GnometzelsFeuerballtreterSchiftung der rollenden EinäscherungKrone des Kata-MaryIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27781] = {title = "Die Maschinerie", objective = "Zerstört den Feindschnitter 5000.", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHa-hallo? <Name>, seid Ihr da? Seid Ihr noch am Leben? Hallo?\n\nOh, gut, Ihr seid noch da! Was im Namen Lordareons bauen die da? Es ist eine Art mechanisches Monstrum! Ihr müsst sie daran hindern, dieses... dieses... Ding fertigzustellen! \n\nVergesst alle Regeln, tut einfach nur, was Ihr tun müsst, um sie aufzuhalten!", progress = "Ja?", completion = "&lt;Bzzzzzzzzzzzzt.&gt;\n\nIhr nähert Euch dem Herzen ihres Einflussbereichs. Wahrscheinlich wird das Allerheiligste der gesamten Defiasoperation von einer extrem verstärkten Tür geschützt. Schaut, ob Ihr etwas finden könnt, um sie aufzubrechen!\n\nIch schlage eine unauffällige Methode vor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27782] = {title = "Mathias braucht Euch", objective = "Sprecht mit Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", description = "Wir hatten viel Spaß miteinander. Es tut mir sehr leid, dass Ihr gehen müsst. Aber Mathias sagte, dass er Euch braucht.\n\nEr sagte auch, es sei dringend!\n\nAlso, wollt Ihr nach dem, was ihr zu tun habt, vielleicht etwas trinken gehen, <Kumpel/meine Dame>?", progress = nil, completion = "Ihr seid zurück! Wir wissen, wo Cho'gall seine ultimative Waffe versteckt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27783] = {title = "Garona braucht Euch", objective = "Sprecht mit Garona der Halborcin bei der Schattenzitadelle im Schattenhochland.", description = "Wir hatten viel Spaß miteinander. Es tut mir sehr leid, dass Ihr gehen müsst. Aber Garona sagte, dass sie Euch braucht.\n\nSie sagte auch, es sei dringend!\n\nAlso, wollt Ihr nach dem, was ihr zu tun habt, vielleicht etwas trinken gehen, <Kumpel/meine Dame>?", progress = nil, completion = "Ihr seid zurück! Wurde ja auch Zeit. Wir wissen, wo Cho'gall seine ultimative Waffe versteckt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27784] = {title = "Der Schattenhammer", objective = "Gelangt zum Schattenhammer.", description = "Während Ihr in der Mine wart, konnte ich herausfinden, wo der Schattenhammer aufbewahrt wird. Er wurde am Zwielichtaltar im Süden geschmiedet.\n\nNoch wichtiger, die Kultisten haben einen schweren Fehler begangen: Cho'gall selbst überwacht seine Fertigstellung.\n\nViele Agenten des SI:7 sind gestorben, um uns diese Informationen zu bringen.", progress = nil, completion = "Der Schattenhammer schwebt in der Mitte des Altars, ungeschützt…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27785] = {title = "Der Admiral", objective = "Tötet Admiral Knurrreißer.", description = "<Bzzzzzzzzzt.>\n\nIch fasse es nicht... Sie sind beinahe mit dem Wiederaufbau fertig! Wir haben nicht viel Zeit, <Name>.\n\nAdmiral Knurrreißer, Vanessas rechte Hand, muss sich an Bord befinden. Wir werden nie an sie herankommen, solange er am Leben ist. Ihr werdet die noch unvollendete Moloch besteigen, Knurrreißer aufspüren und töten müssen, sodass wir in Vanessas private Kajüte auf dem Oberdeck gelangen können.\n\nSeid vorsichtig, der Admiral steht unter dem Worgenfluch und würde Euch nur zu gern mit seinen Klauen zerreißen!", progress = nil, completion = "&lt;Bzzzzzzzzzzzzt.&gt;\n\nEure Abenteuer haben Euch einigen Ruhm in Geheimdienstkreisen eingebracht, &lt;Name&gt;. Viele hochrangige Mitglieder vom SI:7 haben Eure Infiltration der Todesminen mit ihren eigenen Sturmwind-Kommunikatoren aufmerksam verfolgt.\n\nMathias Shaw will höchstpersönlich mit Euch sprechen! Ich werde Euch sofort durchstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27786] = {title = "Der Schattenhammer", objective = "Gelangt zum Schattenhammer.", description = "Während Ihr in der Mine wart, konnte ich herausfinden, wo der Schattenhammer aufbewahrt wird. Er wurde am Schattenaltar der Stürme im Süden geschmiedet.\n\nNoch wichtiger, die Kultisten haben einen schweren Fehler begangen: Cho'gall selbst überwacht seine Fertigstellung.\n\n<Garona beginnt, ihre Klingen zu schärfen.>\n\nViele Kor'kron sind gestorben, um uns diese Informationen zu bringen.", progress = nil, completion = "Der Schattenhammer schwebt in der Mitte des Altars, ungeschützt…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27787] = {title = "Schädelberster der Berg", objective = "Überlebt und tötet dann Schädelberster den Berg.", description = "Es war eine Falle! Cho'gall hat Euch mit dem Hammer angelockt, damit sein Gronn Euch den Rest geben kann.\n\nÜberlebt und tötet Schädelberster den Berg!", progress = nil, completion = "Ihr habt es geschafft, Junge! Ihr habt den verdammten Gronn besiegt und Cho'gall in seine Bastion des Zwielichts zurückgeschickt.\n\nKeine Sorge. Mit Eurer Hilfe und der Eurer Freunde werden wir dort hineinkommen und Cho'gall ein für alle Mal den Garaus machen!", rewards = "TerrortreterCoultons ZermalmerShaws beste GamaschenÜberintelligente RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27788] = {title = "Schädelberster der Berg", objective = "Überlebt und tötet dann Schädelberster den Berg.", description = "Es war eine Falle! Cho'gall hat Euch mit dem Hammer angelockt, damit sein Gronn Euch den Rest geben kann.\n\nÜberlebt und tötet Schädelberster den Berg!", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Ihr habt den verdammten Gronn besiegt und Cho'gall in seine Bastion des Zwielichts zurückgeschickt.\n\nKeine Sorge. Mit Eurer Hilfe und der Eurer Freunde werden wir dort hineinkommen und Cho'gall ein für alle Mal den Garaus machen!", rewards = "TerrortreterCoultons ZermalmerGaronas beste GamaschenÜberintelligente RobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27789] = {title = "Immer Ärger mit den Troggs", objective = "Steigt in einen Kabummturm und überlebt vier Angriffswellen der Troggs.", description = "Ich brauche ein wenig Zeit, um die Proben zu analysieren. Außerdem täte mir eine Pause von der Troggerschießerei ganz gut. Steigt in eines meiner Geschütze und erledigt so viele Troggs, wie Ihr nur könnt. Ich bleibe hier und führe meine Untersuchungen durch.\n\nDie Geschütze haben zwei Fähigkeiten: Einen normalen Schuss und eine elektrische Überladung, für den Fall, dass Euch zu viele Feinde zu nahe kommen. He he. Viel Glück.\n\nOh, und haltet nach den großen, langsamen Troggs Ausschau. Die sollten sich besser nicht in Eurer Nähe aufhalten.", progress = "Noch nicht ganz fertig. Brauche etwas mehr Zeit.", completion = "Die Ergebnisse sind da. Ich habe Spuren der Verderbtheit in allen drei Proben gefunden. Rhea wird ganz schön enttäuscht sein.", rewards = "RattarattakanoneTuch der EnttäuschungAntitroggschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27790] = {title = "Die Nummer Eins der Defias", objective = "Erschlagt die Nummer Eins der Defias.", description = "Hallo, <Name>. Ich habe viel von Euch gehört. Hört gut zu, denn Ihr werdet nur eine Chance bekommen.\n\nDie neue Nummer Eins der Defias muss in der Hütte sein und von dort die Strippen ziehen. Ich will, dass Ihr da reingeht und sie unschädlich macht, für die unzähligen Unschuldigen, die die von ihrem Vater gegründete Organisation getötet und terrorisiert hat.\n\nIch kann kaum glauben, dass sie Euch so nahe an sich heranlässt, ohne zu fliehen und auf eine bessere Gelegenheit zu warten, aber es sieht aus, als hätten wir Glück.", progress = nil, completion = "Eure Anstrengungen hier könnten heute womöglich ganz Sturmwind gerettet haben, &lt;Name&gt;. Vanessa ist zwar noch immer dort draußen, aber sie ist eine unerhebliche Gefahr, nun da wir den Moloch in unsere wachsame Obhut nehmen. Ich danke Euch.", rewards = "Krümels FleischklopferKrümels RührstabKrümels TischdeckeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27791] = {title = "Staubwindausgrabung", objective = "Sprecht mit Oberausgrabungsleiter Durdin in der Staubwindausgrabung im Ödland.", description = "Ich habe eine Idee, die reine Spekulation ist. Zum Glück sind reine Spekulationen eine meiner Spezialitäten.\n\nNördlich von hier hat die Forscherliga neue Ruinen der Titanen unter dem Sand gefunden. Wenn es jemanden gibt, der älter und weiser ist, als die Drachen, sind es die Titanen. Ich habe sogar Gerüchte gehört, dass die Titanen die Drachen ERSCHAFFEN haben.\n\nSprecht mit Oberausgrabungsleiter Durdin im Lager nördlich von hier. Er wird weitaus mehr über die Titanen wissen als ich.\n\nWas habe ich Euch gesagt? Reine Spekulation.", progress = nil, completion = "Titanen? Ihr wollt etwas über Titanen wissen?\n\nDa seid Ihr genau an der richtigen Adresse, mein Lieber. Wir stehen vor einer großen Entdeckung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27792] = {title = "In der Liebe und im Krieg ist alles erlaubt. Und in der Archäologie auch.", objective = "Erlangt einen zerbrochenen Kelch, eine staubige Vase, eine irdene Hieroglyphe und ein Troggwerkzeug.", description = "Moment mal, Eins nach dem Anderen. Ich werde mich hier nicht einfach hinsetzen und Euch alles erzählen, was wir in diesen Ruinen herausgefunden haben. Es gibt Probleme, um die wir uns kümmern müssen!\n\nAm wichtigsten sind diese Akademievandalen, die auf der anderen Seite des Grabs sind. Sie machen sich mit unserer ganzen Beute aus dem Staub! Wissen die denn nicht, dass Graben Zwergensache ist?\n\nJagt ein paar von deren 'Ausgräbern' - eher Banditen, wenn Ihr mich fragt - und bringt mir einige wertvolle Artefakte zurück.\n\nDANN unterhalten wir uns über Titanen.", progress = "Eure Taschen sehen aber schwer aus. Beladen mit geplünderten Artefakten, hoffe ich?", completion = "Kelch... wertlos.\n\nVase... gefälscht.\n\nHieroglyphe... interessant, aber nicht weiter außergewöhnlich.\n\nWas haben wir denn da? Ich habe noch nie Kunsthandwerk der Troggs von diesem Kaliber gesehen! Da seid ihr aber auf etwas wirklich Seltenes gestoßen, &lt;Name&gt;.\n\nNa gut, wie Ihr möchtet. Sprechen wir also über die Titanen.", rewards = "Pantalons des StraßendiebsAusgrabungsarmschienenGefälschte KettenrüstungBrustplatte des EmporkömmlingsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27793] = {title = "Uralte Beschützer", objective = "Untersucht den Wächter und die Schildwache.", description = "Ihr habt in der zentralen Kammer des Grabes recht viel Rumpeln gehört. Diese zwei großen Statuen sahen schrecklich verdächtig aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27794] = {title = "Zurück zu Blam", objective = "Bringt das Auge der Behüter zu Dr. Hieronymus Blam bei der Agmondkuppe im Ödland.", description = "Innerhalb der Kiste findet Ihr einen kleinen, runden Gegenstand, der auf einem Kissen liegt.\n\nWenn es hier unten ein Titanenartefakt geben sollte, dann muss es das sein. Ihr beschließt, ihn zu Dr. Blam zurückzubringen.", progress = "Und? Hat sich unser Schuss ins Blaue ausgezahlt?", completion = "Bloß ein winzig kleines Gerät?\n\nIch habe diese Titanen noch nie verstanden.\n\nNun gut! Wollen wir doch mal sehen, was dieser Piepser kann!", rewards = "HüterspeerHieronymus' GürtelGut gepolsterte StiefelDer folgende Zauber wird auf euch gewirkt:\n\nReturn to Blam: Summon Eye\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27795] = {title = "Flut der Dunkelheit", objective = "Tötet 6 Oger von Steinard.", description = "Die Schlacht verläuft genau so, wie ich es wollte. Jetzt, da ihre Krieger erschöpft sind, habe ich die Reiterei hinein geschickt.\n\nWomit ich jedoch nicht gerechnet hatte, waren Oger. Unsere Ritter stehen den Schlägern zwar in nichts nach, dennoch werden sie Hilfe brauchen.\n\nIhr müsst sofort wieder auf das Feld, <Name>. Nur wenige können einen Oger zu Fuß zur Strecke bringen, aber ich glaube, dass ich mich auf Euch verlassen kann. Enttäuscht mich nicht.", progress = nil, completion = "Sich einem Oger direkt in den Weg zu stellen ist beeindruckend, &lt;Name&gt;. Ich bin froh, dass ich Soldaten wie Euch da draußen habe.", rewards = "OgerklopferSchwert der SumpftidenwachtStab des OgermagusBlutsumpfarmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27796] = {title = "Der Bauer des Wächters", objective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer des Wächters.\n\nBereitgestellter Gegenstand: \n", description = "Als diese Reliquientrottel hier auftauchten, gerieten wir in Panik und begannen, einfach wahllos zu plündern.\n\nViel zweifelhafte Archäologie spielte sich an diesem Tag ab.\n\nGlücklicherweise stieß Olga zufällig auf diese kleine Jadestatue. Wir dachten, es sei eine Art Schlüssel, konnten aber nichts finden, das sie hätte öffnen können. Vielleicht habt Ihr mehr Glück damit.", progress = nil, completion = "&lt;Die Statue rastet in ihren Platz auf der großen Steinplatte ein.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27797] = {title = "Der Bauer der Schildwache", objective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer der Schildwache.\n\nBereitgestellter Gegenstand: \n", description = "Beinahe wurde uns diese Statue von einem der Reliquienhandlanger des Blutwächters gestohlen. Wir konnten ihn auf frischer Tat ertappen und bekamen die Statue zurück, aber es hat sich nicht wirklich gelohnt.\n\nEs scheint, als wäre sie eine Art Schlüssel, aber ich kann in diesen Ruinen nirgendwo das Schloss dazu finden. Möchtet Ihr es versuchen?", progress = nil, completion = "&lt;Die Statue gleitet an ihren Platz auf der kalten Marmorplatte.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27798] = {title = "Wasser des Lebens", objective = "Benutzt das Wasser des Lebens, um dem Leichnam von Schmiedemeister Finlay Informationen zu entlocken.", description = "Nehmt mein Wasser des Lebens und gebt es auf den Leichnam des ertrunkenen Zwergs.\n\nAls er lebte, bearbeitete er Metall. Und obwohl sein Leichnam jetzt meinen Loch nährt, kann er Euch dank des Wassers sagen, was Ihr wissen wollt.\n\nNehmt dann Eure Informationen und verschwindet aus meinem Reich.", progress = nil, completion = "Der Schattenhammer? Und diese Informationen habt Ihr also von einem ertrunkenen Zwerg?\n\nIhr macht Scherze, oder?", rewards = "Handschutz des verdammten GeistesSeelenwuchsschiftungGedankenversengender EntbeinerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27803] = {title = "Eine willkommene Entlastung", objective = "Tötet 8 unterworfene Feuerteufel.", description = "Meine Jungs stellen Verteidigungslinien zu allen Seiten der Stadt und halten die Elementare zurück, die von allen Seiten aus dem aufgerissenen Boden herbeiströmen. Es sind gute Jungs und sie schlagen sich wacker, aber auch der hartnäckigste Zwerg wird einmal müde.\n\nSie haben sich in Schichten eingeteilt: eine Stunde Rast für jede Stunde an der Front. Das ist das Beste, was ich ihnen mit so wenig Leuten bieten kann.\n\nWenn Ihr helfen wollt, dann sucht Euch eine Seite aus und übernehmt eine Schicht. Verschafft meinen Jungs eine willkommene Verschnaufpause. Meldet Euch zurück, sobald Ihr eine ansehnliche Zahl Elementare getötet habt.", progress = nil, completion = "Gute Arbeit, Junge. Es ist schön, ein zusätzliches Paar geschickter Hände zur Verfügung zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27804] = {title = "Für immer unser Zuhause", objective = "Löscht 50 Feuer in Feuerbarts Patrouille.", description = "Wir wurden schon weiter zurückgedrängt, als ich befürchtet hatte, aber ich habe nicht vor, unsere Häuser diesen Bastarden zu überlassen. Sie können sie vielleicht niederbrennen, plündern und auf ihre Überreste spucken, aber wir werden nicht aufgeben und sie zurückfordern.\n\nNatürlich hätte ich es lieber, wenn sie sie nicht niederbrennen. Ich habe die Jungs angewiesen, Eimer am Brunnen zu füllen und damit zu versuchen, das Feuer einzudämmen. Wenn Ihr ihnen aushelft, können sie Euch vielleicht Eimer zuwerfen, sodass Ihr nicht selbst laufen müsst.", progress = nil, completion = "Vielen Dank für Eure Hilfe. Jede noch so kleine Tat kann viel bewirken.\n\nWir werden weiter Wasser bringen, bis wir den Schattenhammer zurückgedrängt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27805] = {title = "Ein Quäntchen Trost", objective = "Findet Mearas Trockenrosen, Parlans Elfenbeinhammer und Aprikas Puppe.", description = "Ihr seid also das neue Gesicht, das Keegan aushelfen soll? Freut mich, Euch kennenzulernen. Vielleicht könnt Ihr den geplagten Wildhämmern, die hier Zuflucht gefunden haben, ein oder zwei Gefallen tun.\n\nWir mussten uns in größter Hast in diesem Gebäude verschanzen, sodass wir viele unserer Wertsachen in unseren zerstörten Häusern in der Nähe zurückließen. Würdet Ihr sie uns zurückbringen, wenn Ihr da draußen seid? Ihr würdet ein paar sehr bedrängten Seelen eine große Freude bereiten.", progress = "Konntet Ihr ihre Wertsachen finden? Ich weiß, es scheint so banal, aber in Zeiten wie diesen können auch Kleinigkeiten so viel bewirken.", completion = "Ihr seid sehr großzügig. Vielen Dank.\n\nUnsere Welt versinkt dieser Tage in Dunkelheit. Wir sind sehr dankbar, dass Ihr uns ein kleines Licht gebracht habt.", rewards = "Beinschützer der ÜberresteTaillenschutz der geretteten GlückseligkeitDem Feuer entronnene SchulterpolsterTuch der verlorenen WertsachenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27806] = {title = "Ehrenvolle Last", objective = "Sprecht mit Iain Feuerbart auf Feuerbarts Friedhof.", description = "Iain, mein Stellvertreter, hat den Leichnam eines unserer gefallenen Helden in die Kathedrale im Westen gebracht. Er ist dafür verantwortlich, aus den verstreuten Truppen ein neues Greifenreitergeschwader aufzustellen. Ich möchte, dass Ihr ihm helft.\n\nIch sollte Euch klar machen, wie eilig diese Aufgabe ist. Wir werden hier nicht bis in alle Ewigkeit standhalten können. Der Schattenhammer oder das Drachenmal werden uns früher oder später überwältigen. Ein aktives Greifenreitergeschwader ist vielleicht unsere einzige Chance, diesen Kampf zu überleben.", progress = nil, completion = "Grüße, &lt;Volk&gt;. Kommt Ihr in Keegans Auftrag?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27807] = {title = "Klan Mullan", objective = "Sprecht mit Duglas Mullan am Schmelztiegel des Gemetzels.", description = "Wenn wir wieder ein vollständiges Greifengeschwader zusammenbekommen wollen, müssen wir uns beeilen, die Überlebenden zusammenzutrommeln, bevor sie fortgehen oder aufgelesen werden. Ich habe einige Gruppen Reiter im Auge, die zusammengeblieben sind. Ich werde bald aufbrechen, um die Reiter von Donnermar und Moora zu suchen.\n\nAls ich die Mullans das letzte Mal sah, gingen sie nach Westen hinauf in den Schmelztiegel des Gemetzels. Geht und schaut, ob Ihr Duglas Mullan davon überzeugen könnt, sich Keegan anzuschließen - er sollte ihm einen Gefallen oder drei schulden.", progress = nil, completion = "Iain hat Euch geschickt?\n\nIhr seht mir nicht wie ein Feuerbart aus. Warum sollte ich mir anhören, was Ihr zu sagen habt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27808] = {title = "Stur wie ein Doyle", objective = "Sprecht mit Keeland Doyle im Hochlandwald.", description = "Die Reiter von Doyle wurden zuletzt gesehen, als sie auf die Bäume im Süden an der Grenze zum Obsidianwald zurannten. Sie sind ein sturer Haufen und es wird einiger Überredungskunst bedürfen, bevor sie sich uns anschließen.\n\nAm besten erzählt Ihr Keeland Doyle, dass Cailin Langhans bei uns in der Stadt Schutz gesucht hat. Keeland hat eine gewaltige Schwäche für sie und das könnte reichen, ihn davon zu überzeugen, all seine Jungs mitzubringen.", progress = nil, completion = "Anscheinend haben die Doyles am meisten unter den Angriffen der Zwielichtdrachen gelitten.\n\nEs ist offensichtlich, dass sie bis zum Ende gekämpft haben: Alle Fußspuren der Reiter befinden sich in umittelbarer Nähe ihrer Greife. Es ist unwahrscheinlich, dass es Überlebende gegeben hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27809] = {title = "Feuerbart brüllt", objective = "Sprecht mit Mackay Feuerbart am Kriegslager Gorshak.", description = "Ihr müsst für mich noch zu Mackay und seinen Leuten gehen. Sie sind auf der anderen Seite des Verschlingenden Risses im Kriegslager Gorshak.\n\nNiemand vom Drachenmalklan hat den ersten Ansturm überlebt und Mackay will nun alles, was er kann aus ihrem Lager plündern, um unseren Kampf zu versorgen. Es sollte nicht schwer sein, sie zu überzeugen, aber wahrscheinlich wollen sie Hilfe, um da oben alles zu Ende zu bringen, bevor sie sich auf den Weg zu Keegan machen.\n\nTretet sie gewaltig von dem alten Iain in den Hintern, wenn es sein muss.", progress = nil, completion = "Ist es schon so weit, ja? Dann helft uns, hier fertig zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27810] = {title = "Kampfgeist", objective = "Fordert einen der Greifenreiter der Mullans heraus und besiegt ihn.", description = "Keegan will, dass die Mullans an ihrer Seite fliegen, hm? Wenn es einen Zwerg gibt, für den ich fliegen würde, dann für ihn. Allerdings weiß ich nicht, warum er 'nen Außenstehenden schickt, um mich anzuwerben. Aus meiner Sicht ist das nich' wirklich höflich.\n\nIch schätze mal, dass Ihr keine 20 Sekunden gegen einen meiner Jungs durchhaltet - weder in der Bar noch auf dem Schlachtfeld. Beweist mir das Gegenteil. Besiegt einen von ihnen im Kampf und dann denke ich drüber nach, ob ich mit dem alten Keegan fliege.", progress = "Nee, ich werd' nicht gegen Euch kämpfen. Geht da rein und fordert einen meiner Jungs heraus, wenn Ihr den Mumm dazu habt.", completion = "Genau so! Gar nicht mal schlecht. Ihr habt ja tatsächlich etwas Kampfkraft in Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27811] = {title = "Der Geruch der Schlacht", objective = "Findet 8 Greife der Mullans und bringt sie zurück zu ihren Greifenreitern.", description = "Lasst Euch nichts von Duglas vormachen, den Mullans juckt es in den Fingern, wieder zu fliegen - und wenn wir das für jemanden tun, dann für Feuerbart.\n\nWir haben unsere Greifen im Hochlandwald im Süden gelassen, damit sie dort jagen können und ein wenig Abstand von den Kampfgeräuschen bekommen. Sie hatten sich ein wenig Erholung verdient.\n\nWenn Ihr uns bald wieder in der Luft sehen wollt, seid Ihr gut beraten uns zu helfen diese Greife wieder hereinzuholen.\n\nNehmt dieses Stück verkohlte Hochlandbirke. Wir benutzen sie während der Ausbildung - sobald sie sie riechen, kommen sie wieder zurück zu uns.", progress = "Ohne unsere Vögel werden wir Euch nicht viel nützen.", completion = "Gut gemacht. Ich habe immer das Gefühl, dass ein Teil von mir fehlt, wenn mein Greif nicht in der Nähe ist. Ich kann ja nicht für Duglas und den Rest seines Clans sprechen, aber ich werde bei Feuerbarts Ruf bereit sein, loszureiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27812] = {title = "Die Loyalität des Klan Mullan", objective = "Kehrt mit den Neuigkeiten über den Klan Mullan zu Iain Feuerbart auf Feuerbarts Friedhof zurück.", description = "Ihr habt Euren Standpunkt klargemacht. Keegan kann auf uns zählen. Wir treffen uns mit ihnen in der Stadt, sobald die Jungs alle versammelt sind.\n\nDafür, dass Ihr kein Wildhammer seid, seid Ihr ganz schön zäh. Offenbar gibt's da, wo Ihr herkommt, gute Weidegründe.\n\nAber ich hab' Euch noch nich' trinken sehen. Das ist der wahre Test.", progress = nil, completion = "Ihr habt die Mullans. Gute Neuigkeiten! Die sind im Kampf mehr wert, als ihr Gewicht in Gold - und die sind nich' grad dürr.", rewards = "StarkbauchgurtArmschienen des TreuesuchersSchultern des KlanherzensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27813] = {title = "Tod würdig des Drachenmals", objective = "Besiegt 6 Nachzügler des Drachenmals.", description = "Der Schattenhammer hat die Stadt ausgeplündert und die meisten der Angehörigen des Drachenmalklans, die darin lebten, getötet. Einige haben allerdings überlebt und die sind nich' grade erbaut darüber, dass wir uns Freiheiten mit ihren Vorräten herausnehmen.\n\nNicht, dass das von Bedeutung wäre.\n\nNaja, ich bin nich' grad erbaut darüber, dass sie meine Jungs angreifen. Tötet sie, jagt sie weg - is' mir egal, werdet sie nur irgendwie los.", progress = nil, completion = "So ist es schon besser. Lasst uns die letzten Vorräte einsammeln und dann ab zu Keegan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27814] = {title = "Alles was wir kriegen können", objective = "Bringt 8 Waffen des Drachenmals zu Brom Schmiedehammer beim Kriegslager Gorshak.", description = "Zurückbleiben und mehr Waffen schmieden? Pff! Ein Schmiedehammer hat sich nie vor einer Schlacht gedrückt! Wer braucht schon eine sichere Umgebung, um Waffen zu schmieden? Außerdem gibt es da draußen tonnenweise Rohstoffe. Die Waffen des Drachenmals sind wertlos, aber man kann sie als Grundlage für echte Waffen nutzen. Bringt mir acht Waffen des Drachenmals, damit ich mit meiner Tochter echte Waffen aus ihnen schmieden kann.", progress = "Wie viele Waffen habt Ihr bisher?", completion = "Gut gemacht, Alter. Vielen Dank; ein bisschen Gold für Eure Mühen gibt es auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27815] = {title = "Etwas für die Jungs", objective = "Bringt Schmiedehammers Waffen zu Iain Feuerbart auf Feuerbarts Friedhof.", description = "Ihr habt das Lager gesäubert und den Laufburschen für Schmiedehammer gespielt? Nicht schlecht für <'nen kleinen/'ne kleine:c> <Klasse>. Bringt die hier zu Iain auf Feuerbarts Friedhof. Er sollte Euch für die gute Arbeit belohnen.", progress = "Was haben wir denn hier?", completion = "Ha! Offenbar war ihr Beutezug richtig erfolgreich. Ich muss dem alten Schmiedehammer wohl eine Runde ausgeben, wenn wir mit dem Durcheinander hier fertig sind.", rewards = "Armschienen des WaffenträgersBrustschutz des LagerreinigersSchmiedefestenhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27816] = {title = "Persönliche Bitte", objective = "Sprecht mit Keegan Feuerbart an Feuerbarts Patrouille.", description = "Schade um die Doyles. Es grenzt allerdings schon an ein Wunder, wie viele von uns es herausgeschafft haben - insofern bin ich nicht sonderlich überrascht.\n\nDiese Rüpel in Donnermar sind Feiglinge. Sogar nachdem sie wussten, dass die Bitte von Keegan kam, wollten sie keinen Fuß aus ihrer Stadt setzen. Ich hab' allerdings die Moores an Bord geholt, also haben wir drei Klans.\n\nKeegan wollte nach Eurer Rückkehr mit Euch persönlich sprechen. Geht und sucht ihn in der Stadt auf.", progress = nil, completion = "Offensichtlich hattet Ihr Glück mit dem Zurückbringen der Reiter. Auch der Zeitpunkt war passend - wir haben gerade die Elementare zurückgeschlagen, also sollten wir genug Bewegungsfreiheit haben, um sofort einen Angriff zu führen.\n\nDanke, &lt;Name&gt;. Ihr seid ein guter &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27817] = {title = "Den Hammer fallenlassen", objective = "Tötet 12 Zwielichtsturmbändiger und Servias Windterror. Benutzt dazu einen der Greifen von Feuerbarts Patrouille.", description = "Dank Euch und Iain haben wir genug Reiter zusammen, um den Kampf wieder gegen den Schattenhammer führen zu können.\n\nWir sind darin ausgebildet, während des Flugs zu kämpfen, aber ein zweiter Reiter, der sich um die Sturmhammer kümmert, ist noch wirkungsvoller. Ich dachte, dass Euch diese Ehre gefallen könnte.\n\nSucht Euch einen Greif aus und schließt Euch dem Kampf an. Ihr solltet Euch allerdings beeilen - wir wollen vor Ablauf einer Stunde alles, was dem Schattenhammer angehört, von den schwebenden Felsen beseitigen.", progress = nil, completion = "Genau so macht man das, mein Freund!\n\nJetzt, da wir wieder ein echtes Greifengeschwader haben, können wir den Kampf auf den Rest des Schattenhammers ausweiten. Ihr seid jederzeit willkommen, mit uns zu fliegen.", rewards = "SturmhammerstulpenHammerkopfhelmKeegans windgepeitschter BrustschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27818] = {title = "Glitschige Zeichen", objective = "Sammelt 5 intakte Stagalsumpfnatternherzen.", description = "Ich habe mich hier schon niedergelassen, bevor Kraulsumpf gegründet wurde, um meine Tränke zu brauen und etwas Frieden zu finden. Ich kenne diesen Sumpf wie meine Westentasche.\n\nDie Fauna hat sich hier in letzter Zeit verändert. Diese geflügelten Schlangen, die Ihr vielleicht im Stagalsumpf gesehen habt, sind Windnattern, und die hat es hier schon seit Urzeiten nicht mehr gegeben.\n\nSie geben allerdings hervorragende Zutaten ab, wenn es die sind, für die ich sie halte. Seid so gut und bringt mir ein paar ihrer Herzen, okay?", progress = "Seid Euch nicht so zimperlich.", completion = "Na werfen wir doch mal einen Blick drauf...\n\nMmm, oje. Ich hatte befürchtet, dass es sich darum handelt. Sie sind zwar noch brauchbar, aber es ist kein schöner Gedanke, solche Biester in der Nachbarschaft zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27819] = {title = "TEST - RVM", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][27821] = {title = "Orcs und Menschen", objective = "Tötet 8 Krieger von Steinard.", description = "Während der Krieg die ganze Welt überzieht, ist das Letzte, was wir brauchen, eine Hordensiedlung gleich nebenan. Das Rotkammgebirge, der Dämmerwald, sogar Elwynn selbst: alle sind nur einen Tagesmarsch von hier entfernt.\n\nWir haben den ersten Angriff gestartet, und ich habe nicht vor, der Horde eine Atempause zu lassen. Betrachtet Euch als im Einsatz. Schnappt Euch eine Waffe, stoßt zum Rest der Truppen draußen im Blutsumpf, und fangt an, Orcs zu töten.\n\nMeldet Euch bei mir zurück, nachdem Ihr etwas Schaden angerichtet habt. Ich will Euch lebend zurück... und das ist ein Befehl. Weggetreten!", progress = nil, completion = "Mehr Schmutzflecken als Blutflecken... das sehe ich gern. Sieht so aus, als hättet Ihr das Zeug für den Krieg, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27822] = {title = "Trampel", objective = "Tötet 5 Steinardpeons.", description = "Ich will, dass der Sieg vollkommen abgesichert wird. Es reicht nicht, genügend Material zu haben, wir müssen sicherstellen, dass der Feind nichts hat.\n\nSteinards Streitkräfte verlassen sich auf das Holz, das aus den umliegenden Wäldern gesammelt wird. Die Orcpeons, die das Holz fällen, mögen keine Krieger sein, aber sie kennen nur Hass auf die Menschen.\n\nZeigt keine Gnade. Ich will, dass diese Peons getötet werden und dass der Holznachschub nach Steinard vollkommen abgeschnitten wird.", progress = nil, completion = "Während Eurer Abwesenheit gab es Schläge gegen unsere eigenen Holznachschublinien. Dadurch sollten wir in etwa die gleichen Mengen gesammelt haben.\n\nGute Arbeit, &lt;Name&gt;.", rewards = "Helm des SammlersGnadenlose BrustplatteAusbalancierte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27823] = {title = "Auch ein Zwerg hat Bedürfnisse", objective = "Besorgt 15 Krüge Schattenbräu.", description = "Versteht mich nicht falsch, ich weiß eine gute Ausgrabung genauso zu schätzen, wie jeder andere Zwerg. Es ist nur so… Nun, wir graben und graben und bekommen kaum einen Schluck zu trinken. Manchmal denke ich, ich sollte meine Schaufel einfach an den Nagel hängen und zurück nach Eisenschmiede gehen.\n\nAber nicht heute. Ein bisschen Grabungsstimmung steckt noch in mir.\n\nDiese Dunkeleisenzwerge an Hammerzehs Grabungsstätte, direkt nördlich von hier, stellen ein starkes und feines Bier her, mitten in der Wüste. Meint Ihr, Ihr könntet mir ein wenig davon besorgen?", progress = "<Sigrun leckt sich erwartungsvoll die Lippen.>", completion = "&lt;Sigrun kippt sofort einen staubigen Krug Schattenbräu.&gt;\n\nHui, das Zeug ist stark! Ich wusste, dass sie Bier haben, aber ich hätte nie gedacht, dass sie Schattenbräu haben! Das ist mein allerliebstes Schattenbier!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27824] = {title = "Das gute Zeug", objective = "Sucht im untersten Stockwerk der Festung Angor nach Schätzen.", description = "Ich habe einen kleinen Vorschlag für Euch, wenn Ihr interessiert seid.\n\nDiese Dunkeleisen waren hier, bevor Durdin und seine Leute angekommen sind. Das bedeutet, dass die Dunkeleisen die ersten waren, die hineingekommen sind, als sich diese Titanenruinen geöffnet haben, und sie haben sicher das ganze gute Zeug mitgehen lassen. Ich bin sicher, dass sie diese Schätze immer noch in der Festung Angor nördlich von hier eingeschlossen haben.\n\nIhr habt Eure Fähigkeit, Zwergen eins auf den Deckel zu geben, mehr als bewiesen. Geht in diese Festung und prügelt Euch zu den Titanenschätzen durch.\n\nIch würde ja mitkommen, aber ich bin betrunken.", progress = "So früh schon zurück?", completion = "Na das nenne ich doch einen Schatz! Ich habe mir schon langsam Sorgen gemacht, dass das hier gar keine Titanenruinen sind!\n\nDas werde ich Durdin zeigen. Nochmals danke, &lt;Name&gt;.", rewards = "StaubwindgugelStaubschalenschildBrustplatte des PrüglersAngorschulterstückeEisenhiebumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27825] = {title = "Überleben der Dicksten", objective = "Erlangt 6 Fleischstücke der Staubspeier und 10 Lagen Seide der Staubspeier.", description = "Uns gehen die Vorräte zur Neige, <Fremder/Fremde>. Solange die schwarzen Drachen unsere Jagdgründe mit Zerstörung überziehen, haben wir keine Chance, an Nahrung zu gelangen.\n\nDie Oger im Süden jedoch haben genau, was wir brauchen. In ihrer Grotte solltet Ihr ausreichend Nahrung und Handwerkswaren finden.\n\nSie könnten sich aber mit Euch darum schlagen wollen. Seid also vorsichtig.", progress = "Willkommen zurück.", completion = "Ich nehme an, die Oger waren für Euch keine zu große Hürde. Hier - ein paar Münzen für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27826] = {title = "In den Drachenschlund", objective = "Bringt das geläuterte Schwarzdrachenei zu Rhea in Drachenschlund im Ödland zurück.", description = "<Dr. Blam starrt das Ei in ehrfürchtiger Stille an, blinzelt ein paar Mal und schaut dann zu Euch hoch.>\n\nH... Habt Ihr das gesehen? Unfassbar! Meine Titanendingsidee hat funktioniert! Mit Eurer Hilfe, natürlich.\n\nNun, ich möchte das hier zu Rhea zurückbringen. Sie befindet sich nicht länger an der Lethlorklamm. Sie hat es mit Bravour geschafft, ihre Tarnung auffliegen zu lassen, als sie sich vor all diesen Welpen in ihre wirkliche Form verwandelte. Sie ist jetzt im Westen und hält sich in einem Allianzcamp mit Namen Drachenschlund auf.\n\nSie wird dort auf Euch warten. Und auf das Ei.", progress = "Ihr habt eine ziemlich wertvolle Ladung bei Euch, <Name>.", completion = "Ich werde Euch das Ei jetzt abnehmen. Wir müssen das Ei ausbrüten... und schnell verstecken. Es gibt eine Menge wütender Drachen, die hiernach suchen.\n\nÜbrigens - schön, Euch wieder zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27827] = {title = "Der Flinke, der Starke und der Schreckliche", objective = "Sprecht mit Eric \"Dem Flinken\" beim Drachenschlund im Ödland.", description = "In meiner Eile, aus der Lethlorklamm zu entkommen, habe ich ein paar Dinge vergessen: Nyxondra. Sie ist frei und hat beim schwarzen Drachenschwarm Alarm geschlagen. Der halbe Schwarm ist hier im westlichen Ödland auf der Suche nach diesem Ei.\n\nIch werde das Ei verstecken. Ihr kümmert Euch um diese lästigen Drachen. Ihr werdet Hilfe bekommen.\n\nRedet mit Eric, drüben auf der anderen Seite des Lagers. Er und seine Brüder werden Euch begleiten.", progress = nil, completion = "Seid Ihr der &lt;Volk&gt;, auf den wir gewartet haben? Es wurde auch Zeit, dass Ihr kommt. Meine Beine könnten ein bisschen Bewegung vertragen.\n\nNa los, Jungs! Lasst uns ein paar schwarze Drachen jagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27828] = {title = "Eric, der nützliche Zwerg", objective = "Benutzt 'Erics Sturmangriff' und 'Erics Taschentrank'.", description = "Bevor wir allzu übermütig werden, was das Drachentöten angeht, möchte ich Euch ein bisschen über die Art, wie ich kämpfe, erzählen.\n\nMan nennt mich \"der Flinke\" und zwar aus folgendem Grund: Ich renne geradewegs auf Eure Feinde los - natürlich mit dem Helm vorneweg - und betäube sie für ein paar Sekunden. Außerdem werde ich einige Tränke bei mir tragen, falls es einmal eng werden sollte.\n\nWarum üben wir nicht, gemeinsam zu kämpfen? Geht hinaus aufs Feld und stellt meine Fähigkeiten auf die Probe.", progress = "Wir sind noch nicht fertig, <Name>.", completion = "Ich bin nicht das, was man gemeinhin \"sehr stark\" oder \"kampfgestählt\" nennt, aber ich bekomme das auch so hin.\n\nIch freue mich darauf, mit Euch gemeinsam zu kämpfen. Ich habe noch nie mit einem schicken &lt;Klasse&gt; gekämpft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27829] = {title = "Der Zorn eines Drachenschwarms", objective = "Tötet Kalaran den Vernichter und 4 Soldaten des dunklen Schwarms.", description = "Hallo, <Name>. Mir scheint, Ihr vier hattet genug Zeit, Euch anzufreunden.\n\nIch habe eine erste Aufgabe für Euch. Kalaran, ein uralter schwarzer Drache mit beträchtlicher Macht, hat sich der Jagd auf das von uns beschützte Ei angeschlossen. Wir müssen ihn aufhalten, bevor er ihm zu nahe kommt.\n\nIhr findet ihn und seine Diener im Staubbecken, nordöstlich vom Drachenschlund. Sucht und besiegt ihn. Wahrscheinlich werdet Ihr die Hilfe Eurer neuen Zwergenverbündeten brauchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27830] = {title = "Die Jagd geht weiter", objective = "Besiegt General Jirakka, Moldarr und 6 Mitglieder der Drachenbrut des dunklen Schwarms.", description = "Der schwarze Drachenschwarm meint es ernst. Wie es scheint hat er einen Großteil von Neu-Kargath, der Siedlung der Horde nordwestlich des Drachenschlunds, an sich gerissen. Ihre Truppen stehen unter dem Befehl von General Jirakka und seinem Champion Moldarr. Sie müssen aufgehalten werden.\n\nWir Drachen mischen uns nicht in die kindischen Streitereien zwischen Horde und Allianz ein, aber mir ist bewusst, welches Risiko Ihr eingeht, wenn Ihr Neu-Kargath betretet. Bitte, Helden... Seid vorsichtig.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27831] = {title = "Das Leid und der Zorn", objective = "Erschlagt Nyxondra und 12 von Nyxondras Brutlingen.", description = "Am meisten bereue ich, wie wir... nein, wie ich Nyxondra behandelt habe. Ich habe sie gezwungen, Eier zu legen, und dann mit ihnen experimentiert. Immer und immer und immer wieder.\n\nObwohl ich selbst Mutter bin, kann ich mir ihr Leid kaum vorstellen.\n\nNein... Ich darf nicht schwach werden. Unsere Arbeit dient immerhin dem Wohl der zukünftigen Generationen der schwarzen Drachen. Ihr Opfer war notwendig.\n\nNun umkreist sie die Ruinen von Kargath, nordwestlich von Neu-Kargath, wahnsinnig vor Zorn. Bitte, Helden... erlöst sie von ihrem Elend.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27832] = {title = "Das Versteckte Gelege", objective = "Sprecht mit Rhea im Versteckten Gelege im Ödland.", description = "Jetzt, da die meisten schwarzen Drachen aus dem Ödland abgezogen sind, können wir das Ei wieder sicher transportieren. Ihr findet mich auf einer kleinen Hochebene nördlich von Neu-Kargath.\n\nSucht mich dort auf.", progress = nil, completion = "Das Ei muss immer in Bewegung bleiben. Wir sind hier nicht mehr sicher.\n\nSogar in seinem Wahnsinn kennt Todesschwinge alle versteckten Orte dieser Welt. Das Ei kann nicht an einem Ort bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27833] = {title = "Tonnenschwere Starrköpfe", objective = "Tötet 12 Kämpfer der Staubspeier. Ihr könnt Raufer oder Schamanen der Staubspeier töten.", description = "Ich würde sagen, wir haben ein Drachenproblem. Aber es sieht aus, als wären sie eher an Neu-Kargath interessiert als an unserem kleinen Lager. Trotzdem habe ich unsere besten Männer darauf angesetzt, die Drachen zurückzuhalten.\n\nEin Problem, das jedoch ungelöst bleibt, ist das Ogerlager im Südwesten. Eine kleine Armee von Kämpfern scheint vor ihrem Unterschlupf aufgetaucht zu sein.\n\nWir können nicht einfach herumsitzen und darauf warten, dass sie uns über die Flanke angreifen. Dünnt ihre Reihen aus, bevor sie es mit unseren tun.", progress = nil, completion = "Ich danke Euch, &lt;Volk&gt;. Allerdings befürchte ich, dass ich Euch außer einer aufrichtigen Runde Applaus nicht viel geben kann.\n\n\n\nOh, das hier habe ich doch. Hier, nehmt Euch, was Ihr wollt.", rewards = "Umhang der LeidenschaftBastionshandschuheStaubspeierstiefelHalbtonnenschulterstückeBogen des SturmesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27834] = {title = "Baelog, die Glaskanone", objective = "Benutzt 'Baelogs Valhallaschuss' und 'Baelogs Kriegsschrei'.", description = "Bevor ich anfange, Pfeile auf diese Drachen regnen zu lassen, stelle ich mich erstmal vor.\n\nIch bin Baelog, der Mann fürs Grobe in dieser Gruppe. Mein Schwert beißt wie ein Krokilisk und meine Pfeile singen wie Banshees. Dafür erschöpfe ich aber schnell und kann auch nicht so viel einstecken wie meine Brüder.\n\nEin Wort von Euch genügt, und ich kann einen gezielten Pfeil mitten ins Herz des Ziels schicken. Ich kann auch meine Brüder anfeuern und sie sich in einen Kampfrausch steigern lassen.\n\nWarum ziehen wir nicht zusammen in die Schlacht?", progress = "Wir sind noch nicht ganz bereit. Noch etwas mehr Übung und wir fangen mit dem Drachentöten an.", completion = "Ich glaube, Ihr seid soweit, &lt;Name&gt;. Ihr habt den Dreh raus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27835] = {title = "Olaf, der dicke Brocken", objective = "Benutzt 'Olafs Schildwall' und 'Olafs mächtigen Ruf'.", description = "Es ist Euch vielleicht nicht aufgefallen, aber für einen Zwerg bin ich recht groß.\n\nIch stelle sicher, dass meine beiden Brüder hier nicht in zu große Schwierigkeiten geraten. Sie sind klein und haben nicht so einen großen Schild wie ich. Ich bin groß und kann ein paar Schläge von Monstern gut wegstecken! Außerdem kann ich es meistens schaffen, dass sie nur meinen Schild treffen!\n\nIch kann auch Euch beschützen. Kommt, gehen wir ein bisschen trainieren. Ich sorge dafür, dass die Gegner mich angreifen, nicht Euch.", progress = nil, completion = "Seht Ihr? Kein Grund zur Sorge, wenn Olaf da ist. Sagt mir nur Bescheid und ich beschütze Euch vor den Monstern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27836] = {title = "Die Ausbreitung eindämmen", objective = "Zerstört 6 Gleitereier.", description = "Es wird nicht reichen, die widerlichen Kreaturen, die den Fluss verseuchen, zu töten, <Name>.\n\nEine neue Generation dieser Monstrositäten droht bereits in unseren heiligen Wassern ausgebrütet zu werden.\n\nSucht ihre unreinen Eier und zerstört sie.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Dies wird unsere prophetischen Visionen so viel klarer werden lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27837] = {title = "Ungebetene Besucher im Wasser", objective = "Tötet 8 Stillwassergleiter.", description = "Kurz, nachdem Uldums Schutzbarriere fiel, wurde der Vir'naal von einer furchtbaren Verderbnis befallen.\n\nOb diese mit böser Absicht oder versehentlich hierher gebracht wurde, spielt keine große Rolle.\n\nDas Ergebnis ist das gleiche. Je trüber der Fluss wird, umso mehr trübt sich auch unsere Fähigkeit, vorauszusehen, was die Zukunft uns bringt.\n\nSchaut hinaus, <Klasse>. Diesen widerwärtigen Kreaturen war es nie bestimmt, in den makellosen Wassern unseres Flusses zu leben. \n\nTötet sie, damit der Fluss uns wieder Visionen ermöglicht.", progress = nil, completion = "Ja, &lt;Name&gt;. Ich spüre bereits, wie die Beeinträchtigung des Flusses schwindet.\n\nDennoch spüre ich, dass die Quelle dieser Verderbnis weiterhin lauert.", rewards = "Helm des SchlickwasserschlächtersSandalen des verderbten WassersSchiftung des Vir'NaalIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27838] = {title = "Die Wurzel des Übels", objective = "Geht zur nordöstlichen Quelle des Vir'naal und tötet Schuppenmutter Hevna.", description = "Ihr mögt Euch den Symptomen unseres Problems angenommen haben, <Name>. Aber ich habe diese widerwärtigen Biester beobachtet und sie legen ihre Eier nicht hier.\n\nDie Strömung trägt ihre Eier zum Damm, aber was immer sie legt, befindet sich am Oberlauf des Flusses.\n\nGeht nach Nordosten zur Hauptquelle des Flusses und beseitigt die Wurzel des Übels.", progress = nil, completion = "Ja. Die Wasser werden klarer.\n\nIch bin sicher, dass wir eine Vision haben werden, bevor der Hohe Rat zusammentrifft.\n\nSeid gewarnt, &lt;Volk&gt;. Meine Stimme wird sich nach dem richten, was ich sehe.\n\nIhr habt uns sicherlich heute hier sehr geholfen, aber wenn die Vision mir rät, mich gegen den Krieg auszusprechen, dann werde ich meine Stimme auch so abgeben.", rewards = "Hevnas AugenhöhleSchuppen der SchuppenmutterTuch der Verderbten EierschalenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27839] = {title = "Uralte Waffen", objective = "Besorgt die uralten Waffen der Tol'vir", description = "Obwohl wir uns noch nicht offiziell im Krieg befinden, zögern die Neferset nicht, alle, die unbefugt ihr Gebiet betreten, ins Gefängnis zu werfen oder zu töten.\n\nKönig Phaoris weigert sich, darauf zu antworten, auch wenn sie unser Land dazu benutzen, gestohlene Relikte aus den Grabstätten unserer Ahnen herauszuschmuggeln.\n\nMeine Späher berichten mir, dass die Neferset in Kürze südlich von hier eine größere Ladung geplünderter Waffen in Bewegung setzen wollen.\n\nIch habe die Arbeiter, die Ihr angeworben habt, angewiesen, Euch zu helfen. Ruft sie mit diesem Horn, wenn Ihr die Schmuggler findet und holt die Waffen.", progress = "Ihr seid zurückgekehrt, <Name>. Wie ist die Operation verlaufen?", completion = "Das kommt gerade recht. Ich werde diese Waffen an meine besten Leute und die Arbeiter, die Ihr angeworben habt, verteilen.\n\nIch habe das Gefühl, sie werden ebenso viel Mut beweisen, wie meine bestens ausgebildeten Hauptleute.", rewards = "Armschienen des WaffenträgersBrustschutz des düsteren SkarabäusGestohlener Taillenschutz der NefersetIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27840] = {title = "Draenethystkristalle", objective = "Sammelt 5 Draenethystkristalle in der Zuflucht der Verirrten auf.", description = "Die Verlorenen, die in der Zuflucht der Verirrten leben, sehen aus wie wir, aber sie sind Monster, die durch die Strapazen unserer Reise nach Azeroth den Verstand verloren haben. Einst waren sie unsere Brüder, aber jetzt leben sie in der Zuflucht der Verirrten im Westen. Dort fangen oder töten sie jeden, der ihnen nahe kommt.\n\nAußerdem haben sie uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nWir haben nicht genug Leute, um die Zuflucht der Verirrten zu betreten und uns das gestohlene Draenethyst aus ihren Hütten und von ihren Lagerfeuern zurückzuholen. Doch ohne diese Kristalle... könnte es sein, dass auch wir uns verirren.", progress = "Habt Ihr die Kristalle?", completion = "Danke, &lt;Name&gt;. Wir stehen in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27841] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Goblingeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][27842] = {title = "Erst der Anfang", objective = "Tötet Glubtok.", description = "Ich ich sehne mich nach den Zeiten, als Legionen mächtiger Oger von der Horde in die Schlacht geführt wurden und die lächerliche Allianz sich vor Angst in die Hosen gemacht hat. Vielleicht kehren diese Tage ja wieder, bevor die Ahnen mich zu sich rufen.\n\nDerzeit jedoch ist dies noch nicht der Fall. Ein Ogermagier, Glubtok, hat sich mit der verabscheuungswürdigen Bruderschaft der Defias eingelassen und spielt für sie den Vorarbeiter für ihre Bergbauoperationen. Dieser erbärmliche Narr! Beendet sein Leben für mich und zum Ruhme der Horde!", progress = nil, completion = "Lasst Euch nicht aus der Ruhe bringen, &lt;Name&gt;. Ich bin ganz in der Nähe und warte in den Schatten. Ihr habt Eure Sache gut gemacht.\n\nIhr müsst Eure Mission hier fortsetzen - Ich bin zu wertvoll, um mein Leben gegen Kleinkriminelle wie diese aufs Spiel zu setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27843] = {title = "Verstärkungen abgelehnt", objective = "Tötet 3 Hexenmeister von Steinard.", description = "Einfach nur Oger zu töten wird nicht ausreichen. Die Oger selbst werden viel zu schnell aufs Schlachtfeld gerufen.\n\nIch möchte, dass Ihr weit hinter die feindlichen Linien geht und ihre Beschwörer ausschaltet. Diese Orcs verwenden Hexenmeister, um ihre Verstärkungen zu rufen.\n\nHackt diese Hexenmeister in Stücke, und die Portale sollten in greifbarer Nähe sein. Es gibt nicht zu viele von ihnen... Ein schneller, präziser Schlag sollte den Feind schwächen.", progress = nil, completion = "Erneut gute Arbeit. Noch ein paar solcher Vorstöße und die Schlacht wird uns gehören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27844] = {title = "Verräter!!!", objective = "Besiegt Helix Ritzelbrecher.", description = "Die Goblins, die mit den Defias zusammenarbeiten, sind offiziell Verräter am Bilgewasserkartell, der Zerschmetterten Hand und der Horde selbst!\n\nIch wurde noch nicht bei der Zerschmetterten Hand initiiert, also gilt meine Treue vor allem meinem Volk. Helix Ritzelbrecher hat offensichtlich keine Zeit für solche Bündnisse und baut gerade einen Mast für die Moloch der Defias. Würdet Ihr Helix im Namen von Fräulein Fiasko und mir \"beseitigen\"?", progress = nil, completion = "Meine Auftraggeber haben für Verräter nichts übrig.\n\nIm Gegensatz dazu sind sie für ihre ausgesprochene Freundlichkeit unseren treu Ergebenen gegenüber bekannt. Ihr verdient es, belohnt zu werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27845] = {title = "Markiert die Gefallenen", objective = "Benutzt die Banner der Gefallenen, um 7 gefallene Fußsoldaten der Sumpftidenwacht zu markieren.", description = "Wir haben mehr Leben genommen, als wir verloren haben, aber wir haben immer noch zu viele verloren. Zu viele Tapfere haben da draußen ihr Leben für die Allianz gegeben. Ich will, dass sie die verdienten Ehren erhalten, egal, wie wild diese Schlacht auch wird.\n\nNehmt diese Flaggen mit Euch und platziert je eine auf jedem gefallenen Soldaten, den Ihr seht. Die Schutzzauber, die ihnen anhaften, werden nicht vor mutwilliger Entweihung schützen, aber sie sind besser als nichts. Ich werde so auch besser aus der Entfernung einschätzen können, wie viele wir verloren haben.", progress = nil, completion = "Danke, &lt;Name&gt;. Diese Soldaten verdienen Besseres, als mit dem Gesicht im Dreck liegengelassen zu werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27846] = {title = "Die dankbaren Toten", objective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Worgengeist auf dem Friedhof von Darnassus.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMakabre Marionette"}
MultiLanguageQuestData['de'][27847] = {title = "Noch nicht ganz fertig", objective = "Zerstört den Feindschnitter 5000.", description = "Diese Prototypen werden die Kriegsführung der Horde revolutionieren, wenn ich sie erstmal perfektioniert habe! Das Problem ist nur, dass ihre Energievorräte nicht für große Chassis ausreichen, oder um komplizierte Kampfmanöver durchzuführen, obwohl beides sehr wünschenswert wäre.\n\nDie Defias haben - mithilfe einiger Goblinverräter wie Helix - beinahe den Feindschnitter 5000 fertiggestellt, einen riesigen Golem, der sogar funktionieren wird!\n\nDas darf auf keinen Fall publik werden, oder ich verliere Kunden!", progress = nil, completion = "Großartig! Nun muss ich nur noch mein Werk vollenden und meine Chaosernter werden... Chaos... auf jedem Schlachtfeld der Horde säen!\n\nUnd es wird keine Emporkömmlinge der Defias geben, die meine Profite stehlen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27848] = {title = "Gute Absichten... Schlechte Durchführung", objective = "Tötet Admiral Knurrreißer.", description = "Die Defias planen, die Moloch fertigzustellen und damit Sturmwind in Schutt und Asche zu legen. Es ist eine ehrenvolle Aufgabe und eine, die jeder wahre Orckrieger ohne zu zögern annehmen würde!\n\nVanessas Fehler ist die Ausführung ihres Plans. Das Schiff ist mangelhaft konstruiert, die Crew ohne Erfahrung und, was am schlimmsten ist, da ist dieser Worgen unter ihnen!\n\nSein Name ist Admiral Knurrreißer und er muss ohne jede Gnade im Namen des Kriegshäuptlings erschlagen werden. Lok'tar ogar!", progress = nil, completion = "Es ist wirklich eine Schande, dass er sowohl ein Mensch, als auch ein Worgen war. Wäre er ein stolzer Orckrieger gewesen, hätte mein Herz höher geschlagen, Seite an Seite mit solch einem wilden Streiter in die Schlacht zu stürmen.\n\nWir können ein andermal von unerfüllten Wünschen sprechen. Es ist an der Zeit, dem Feind zu entringen, was uns gehört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27849] = {title = "Angriff auf Steinard", objective = "Erschlagt 6 Verteidiger von Steinard.", description = "Das ist es, <Name>. Wir haben es endlich nach Steinard geschafft.\n\nIch sollte zwar niemanden daran erinnern müssen, tue es aber trotzdem: Wir sind keine Orcs, und wir werden auch wegen Rachegelüsten und Boshaftigkeit nicht zu welchen werden. Steinard wird nicht dem Erdboden gleichgemacht werden, damit wir auf seiner Asche tanzen.\n\nNein, ich will, dass das hier auf anständige Art gemacht wird. Ein chirugischer Eingriff. Haltet Euren Kopf aufrecht und erschlagt jeden Orc, der eine Waffe auf Euch richtet.", progress = nil, completion = "Ihr habt Euren Befehlen ausgezeichnet Folge geleistet, &lt;Name&gt;. Im Namen der Krone belobige ich Euch für Euren Mut auf dem Schlachtfeld.", rewards = "Roben des EhrenwertenGamaschen des letzten AngriffsBrustschutz des WagemutesBlauherzens HelmChirurgischer SchlägerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27850] = {title = "Die Nummer Eins der Defias", objective = "Tötet die Nummer Eins der Defias.", description = "Die Zerschmetterte Hand hat sich jahrelang im Hintergrund gehalten.\n\nDas hat nun ein Ende! Ihr werdet das Instrument unserer Wiedergeburt sein, <Name>. Erschlagt die Nummer Eins der Defias und erbeutet ihr Schiff zum Ruhme der Horde! Wir werden sie wie ein richtiges Orckriegsschiff ausstatten und Sturmwind endlich in Schutt und Asche legen!\n\nJeder Überlebende wird die Kunde unserer unaufhaltsamen Macht in ganz Azeroth verbreiten und alle werden vor uns erzittern!\n\nGeht jetzt. Van Cleefs Tod wird Eure bisher größte Tat darstellen, Held!", progress = nil, completion = "FEIGLING!!! Vanessa van Cleef ist ein dreckiger Feigling von einem Menschen! Wie kann sie es wagen, einem Kampf mit der Horde zu entfliehen und ihre unwürdigen Lakaien zurückzulassen?\n\n&lt;Kagtha beruhigt sich wieder.&gt;\n\nUnwichtig. Ihr Schiff ist Belohnung genug. Die Einwohner Sturmwinds werden aus erster Hand erfahren, wie sich unsere Ehrfurcht gebietende Macht anfühlt, wenn wir sie mit einem Schiff angreifen, das zum Teil vom selben Architekten gebaut worden ist, der auch ihre Stadt erbaut hat!", rewards = "Krümels FleischklopferKrümels RührstabKrümels TischdeckeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27851] = {title = "Nachschubunterbrechung", objective = "Erbeutet 5 Kisten mit Vorräten von Steinard.", description = "Wir werden Steinard zwar nicht dem Erdboden gleichmachen, aber ich will kein zweites Mal dort hineingehen müssen.\n\nSammelt alle Vorräte, die Ihr seht, wenn Ihr in der Stadt seid. Ohne Nahrung werden ihnen nach einem Tag keine Kämpfer mehr bleiben.\n\nEs sollten in der ganzen Stadt Kisten herumstehen.", progress = "Wie ist die Lage?", completion = "Gute Arbeit, &lt;Name&gt;. Dank dieser Kisten ist es nur eine Frage der Zeit, bis die Orcs zum Portal fliehen oder darum betteln, sich ergeben zu dürfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27852] = {title = "Orcs und Menschen", objective = "Tötet 10 Fußsoldaten der Sumpftidenwacht.", description = "Der Krieg tobt im Sumpf, <Name>. Niederträchtige Menschen haben sich nördlich der Stadt niedergelassen und eine Armee an unsere Türschwelle gebracht.\n\nIn diesem Sumpf gibt es für sie nichts zu holen. Der einzige Grund, weswegen sie hier sind, ist, uns unprovoziert anzugreifen!\n\nWir sind unterbemannt und brauchen jeden fähigen Orc, um zu kämpfen. Geht und erschlagt so viele Menschen, wie Ihr nur könnt!", progress = nil, completion = "Wir werden bis auf den letzten &lt;Volk&gt; kämpfen, &lt;Name&gt;. Ich hoffe, Ihr könnt Euch lange genug am Leben erhalten, um diese Eindringlinge gründlich zu vernichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27853] = {title = "Trampel", objective = "Tötet 5 Bauern der Sumpftidenwacht.", description = "Die Allianz ist uns zahlenmäßig überlegen. In ihrer Angst entsenden sie eine Armee, um eine einzelne Siedlung zu zerstören. Aber wir werden nicht aufgeben!\n\nWenn sie keine Resourcen haben, werden ihre Soldaten im Nachteil sein. Menschliche Bauern sind damit beschäftigt, in den Wäldern außerhalb der Sumpftidenwacht Holz zu sammeln, um ihre einstürzenden Wälle wieder aufzubauen.\n\nVersagt ihnen das Holz - und ihr Leben.", progress = nil, completion = "Kein wahres Mitglied der Horde sollte Gefallen daran finden, solch verängstigte Schwächlinge zu töten... dem Sieg fehlt zum Nervenkitzel dann die Herausforderung.\n\nDoch Eure schmutzige Arbeit hat dazu beigetragen, dass wir die Allianz abwehren und unser Zuhause hier schützen konnten. Seid stolz auf Eure Arbeit für die Horde.", rewards = "Helm des SammlersGnadenlose BrustplatteAusbalancierte SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27854] = {title = "Flut der Dunkelheit", objective = "Tötet 6 Ritter der Sumpftidenwacht.", description = "Wir mussten schwere Verluste einstecken, <Name>. Die Feste Schreckensfels hat Oger aus den Verwüsten Landen als Verstärkung geschickt, aber ihre Zahl ist begrenzt. Die Allianz setzt ihnen genau in diesem Moment zu.\n\nDie Allianz versucht, mit Rittern gegen unsere Oger vorzugehen. Diese Strategie hat ihnen schon im Zweiten Krieg gute Dienste geleistet. Wir müssen unsere stärksten Krieger einsetzen, wenn wir die Schlacht für uns entscheiden wollen!\n\nKehrt zum Blutsumpf zurück, <Name>, und bringt diese Ritter zu Fall!", progress = nil, completion = "Ihr seid ein wahrer Champion, &lt;Name&gt;, dass Ihr auf dem Schlachtfeld so vielen das Leben genommen habt. Ich hoffe, dass es ausreicht, um Steinard zu retten.", rewards = "RitterklopferGroßaxt von SteinardStab des OgermagusBlutsumpfarmbrustIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27855] = {title = "Verstärkungen abgelehnt", objective = "Tötet 3 Magier der Sumpftidenwacht.", description = "Die Allianz hat ihre Magier mitgebracht, um weitere Verstärkungen von hinter ihrer Festung direkt auf das Schlachtfeld zu bringen. Das muss unterbunden werden!\n\nEs sind ihrer nur wenige, aber ein einziges Portal kann schon den Ausgang der Schlacht verändern. Greift ihre Magier an und zerstört diese Portale!", progress = nil, completion = "Ohne eine Verbindung zur Außenwelt muss sich die Allianz auf das verlassen, was sie in die Sümpfe mitgebracht hat. Wollen wir doch mal sehen, wie sie mit unserer vertrauten Umwelt fertig werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27856] = {title = "Markiert die Gefallenen", objective = "Benutzt das Banner der Gefallenen, um 7 gefallene Krieger von Steinard zu markieren.", description = "Viele Krieger haben den Tod gefunden, um uns den Sieg zu bringen, <Name>. Das ist das Schicksal eines wahren Orcs.\n\nIch habe gesehen, wie die Allianz die Leichen unserer Gefallenen plündert und sich wie Hamster an unseren Sachen festklammert. Sie werden nicht unsere gefallenen Helden auf diesem Schlachtfeld entehren.\n\nNehmt diese Banner mit Euch in den Blutsumpf. Platziert sie auf die Leichen unserer gefallenen Krieger. Ich werde Euch beobachten, damit ich sehe, wie viele gefallen sind und um ihr Opfer zu ehren. Hoffen wir, dass die Geister uns helfen, unseren Respekt zu erweisen.", progress = nil, completion = "Mit Eurem Mut ehrt Ihr sowohl die Toten als auch die Lebenden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27857] = {title = "Wir werden angegriffen!", objective = "Tötet 12 Eindringlinge der Sumpftidenwacht.", description = "Die Allianz hat unsere Mauern erreicht!\n\n<Name>, Euer Handeln hat ihren Vorstoß verlangsamt, doch sind sie uns zahlenmäßig immer noch weit überlegen. Dies wird unser letztes Gefecht sein. Sieg oder Tod...\n\nIch wünsche Euch einen ehrenhaften Kampf, <Name>. In diesem Augenblick toben die Kämpfe bereits innerhalb unserer Mauern. Treibt diese Bestien aus Steinard. Für die Horde!", progress = nil, completion = "Die Allianz wurde vertrieben. Steinard ist dank Eures Mutes wieder sicher! Lok'tar Ogar!", rewards = "Roben des EhrenwertenGamaschen des letzten WiderstandesBrustschutz des WagemutesRuags HelmStoß des VerteidigersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27858] = {title = "Rheastraszas Geschenk", objective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", description = "Wartet hier. Ich werde das Ei holen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27859] = {title = "Das Ei lebt weiter", objective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", description = nil, progress = nil, completion = "Ihr wart nicht der einzige Sterbliche, dem sich Rheastrasza anvertraut hat. Auch ich habe das Vertrauen des Drachen gewonnen.\n\nIch habe bereits das echte, gereinigte Ei an einen sichereren Ort weitab vom Ödland geschafft. Es wird weiter wachsen, ohne dass Todesschwinge seinen Aufenthaltsort kennt.\n\nDie Macht des roten Drachenschwarms wird nur von seiner Güte übertroffen. Rheastraszas letzter Wunsch war es, dass ich Euch dies gebe.", rewards = "Ihr bekommt:\n\nRheas letztes Ei"}
MultiLanguageQuestData['de'][27860] = {title = "Die Verirrten", objective = "Tötet 12 Verirrte in der Zuflucht der Verirrten.", description = "Als das Dunkle Portal sich vor vielen Jahren schloss, überkam viele von uns, die in dieses Land gekommen sind, Reue und Angst. In ihrer Verzweiflung verfluchten sie den Namen des Lichts und verfielen in Gewalttätigkeit und Hass.\n\nDiese gefallenen Seelen sind jetzt als die Verirrten bekannt. Sie sind kaum mehr als geistlose Monster, die alles anfallen, was sich ihnen nähert. Ihre Verderbtheit wächst mit jedem Tag. Und in ihrem Kampf ums Überleben haben sie jetzt begonnen, Leute aus dem Sicheren Hafen zu entführen.\n\nIhnen kann nicht mehr geholfen werden, <Name>. Ihr Leiden muss ein Ende finden. Werdet Ihr sie aus ihrer Not befreien?", progress = nil, completion = "Meine Bitte an Euch bereitet meinem Herzen immer noch Qual, obwohl ich weiß, dass es keinen anderen Weg gibt. Ihr habt uns, die wir immer noch an unserem Verstand festhalten, vor einer schlimmen Bedrohung gerettet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27861] = {title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", objective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", description = "Ich hab mich schon gewundert, wann Ihr endlich hier aufkreuzt, <Name>! Mit einem ehemaligen Champion aus dem Ring des Blutes wird es hier richtig was zu sehen geben! Wir werden reich sein, <Kumpel/Süße>! REICH!\n\nWie dem auch sei, hier ist eine alte Kampfgrube des Drachenmals. Wir mussten für unsere Bedürfnisse nicht viel daran ändern. Ich habe meine Fühler ein bisschen ausgestreckt, um die besten Schläger Azeroths für das Gemetzel zu finden. Es ist an der Zeit, Gold zu verdienen!\n\nIhr wisst ja, wie es abläuft, <Name>. Wenn Ihr soweit seid, sagt Bescheid, und wir fangen mit der Vorstellung an!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27862] = {title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", objective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", description = "Na wenn das nicht unser ehemaliger Champion der Agonie ist! <Name>, jetzt, da Ihr da seid, sehe ich eine Zukunft voller Gold! Wir werden im Gold baden, <Kumpel/Süße>! BADEN!\n\nWie dem auch sei, hier ist eine alte Kampfgrube des Drachenmals. Wir mussten für unsere Bedürfnisse nicht viel daran ändern. Ich habe meine Fühler ein bisschen ausgestreckt, um die besten Schläger Azeroths für das Gemetzel zu finden. Es ist an der Zeit, Gold zu verdienen!\n\nIhr wisst ja, wie es abläuft, <Name>. Wenn Ihr soweit seid, sagt Bescheid, und wir fangen mit der Vorstellung an!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27863] = {title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", objective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", description = "Eins sag ich Euch, man kann hier natürlich nicht mit den Wogenden Ebenen von Nagrand oder der Arena in Zul'Drak vergleichen, aber hey, ich bin da, wo das Gold ist! Willkommen im Schattenhochland!\n\nIhr seid neu hier, also lasst mich Euch ein paar Sachen erklären. Ich bin der Kampfveranstalter und der angriffslustige Troll hier ist Wodin, mein Leibwächter. Ihr seid meine Unterhaltung. Wenn Ihr kämpfen wollt, sagt Bescheid, und ich finde den passenden Gegner für Euch.\n\nWenn Ihr mit Freunden hier seid, können wir auch gleich anfangen! Was meint Ihr?", progress = "Es gibt keine Bezahlung, bevor der Kampf vorbei ist, Junge.", completion = "Nicht schlecht, nicht schlecht. Ihr könntet hier einen Batzen Gold verdienen - wenn Ihr nicht vorher sterbt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27864] = {title = "Der Schmelztiegel des Gemetzels: Todbringer des Drachenmals!", objective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Torg Drachenschinder!", description = "Das wird Euch gefallen! Der Drachenmalklan hat gehört, dass Ihr die Arena betreten wollt und man ist wild entschlossen zu verhindern, dass Ihr sie wieder verlasst.\n\nJetzt ist es Zeit für ein bisschen <Volk>-gegen-Orc-Action! Sagt mir Bescheid, wenn Ihr dazu bereit seid!", progress = nil, completion = "Wie ich sehe, tragt Ihr keine Liebe für Orcs in Euch. Den Burschen habt Ihr wirklich zu Kleinholz verarbeitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27865] = {title = "Der Schmelztiegel des Gemetzels: Der unberechenbare Wildhammer!", objective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Sully Kniescheibler!", description = "Das wird Euch gefallen! Der Wildhammerklan habt gehört, dass Ihr die Arena betreten wollt und man ist wild entschlossen zu verhindern, dass Ihr sie wieder verlasst.\n\nJetzt ist es Zeit für ein bisschen <Volk>-gegen-Zwerg-Action! Sagt mir Bescheid, wenn Ihr dazu bereit seid!", progress = nil, completion = "Wie ich sehe, tragt Ihr keine Liebe für Zwerge in Euch. Den Burschen habt Ihr wirklich zu Kleinholz verarbeitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27866] = {title = "Der Schmelztiegel des Gemetzels: Calders Geschöpf!", objective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt die Kadavercollage!", description = "Grauenvoll und blutig - die nächste Paarung wird die Menge auf jeden Fall zum Stöhnen bringen. Calder Grau hat die Körperteile seiner besiegten Herausforderer aufgesammelt und daraus den perfekten Champion gebaut.\n\nDieses Ding ist die ultimative Zusammensetzung zusammengeschusterter zombifizierter Zweikämpfer. Eine mörderische Mixtur matschiger Monstrositäten. Seid Ihr bereit für das Chaos?! Ich bin es! Sagt mir Bescheid, wenn Ihr bereit seid, damit wir anfangen können!", progress = nil, completion = "Wow! Als ich das... Ding in die Arena stolpern sah, war ich sicher, dass Ihr keine Chance habt. Aber Ihr habt mir das Gegenteil bewiesen. Ihr habt es zerfetzt!\n\nGrauenhafte Angelegenheit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27867] = {title = "Der Schmelztiegel des Gemetzels: Der Graf des Ausweidens!", objective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Lord Geoffery Tulvan!", description = "Mit dem hier werdet Ihr alle Hände voll zu tun haben, Kumpel. Wir haben hier einen erfahrenen Ehrenmann und Krieger! Er stammt aus Gilneas und will beweisen, dass er der beste Krieger diesseits von Azeroth ist.\n\nAlso schnürt Euch Eure Stiefel und gürtet die Hose, denn hier drin wird's jetzt richtig zur Sache geh'n. Sagt Bescheid, wenn Ihr was auf die Ohren bekommen wollt.", progress = nil, completion = "Das habt Ihr wirklich gut hinbekommen. Ich dachte, Ihr hättet es hinter Euch, als er sich in einen Wolf verwandelte und anfing, die Arena in Stücke zu reißen. Aber allmählich sollte ich wohl wissen, dass Ihr nicht so einfach kleinzukriegen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27868] = {title = "Der Schmelztiegel des Gemetzels: Der Schattenterror!", objective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Glutnarbe den Verschlinger!", description = "Wir haben jemanden hier, den Ihr mit Sicherheit nur allzu gern hassen werdet. Zunächst war ich nicht sicher, ob wir ihn in die Grube lassen sollten, aber ein Kampf ist ein Kampf! Und wer bin ich schon, dass ich sicheres Geld ablehne?!\n\nDieser Kerl kommt aus der Schattenzitadelle und ist bewaffnet mit einem heißen Schlag. Ihr solltet Euch lieber schnell bewegen und immer auf der Hut sein! Sagt Bescheid, wenn Ihr für ein wenig Action bereit seid.", progress = nil, completion = "Sieht so aus, als ob der Titel Euch gehört! Das habt Ihr aus dem Feuer gezogen. \n\nMeine Glückwünsche. Ich hoffe, das Geld wird Euch gute Dienste erweisen.", rewards = "Übergroßer schräger OgervernichterCalders beschichteter AasschneiderSehr männlicher StabGurgthocks grauenhafter GemetzelkolbenBesonders Biegsamer BombenbogenLackiertes Langmesser des LungenlecksIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27869] = {title = "Der Drache und der Tempel", objective = "Redet mit Lord Itharius oben auf den äußeren Stufen des Tempels von Atal'Hakkar.", description = "Diese Schlangen müssen aus dem Tempel von Atal'Hakkar kommen. Ich hatte bereits einen Hinweis...\n\nVor ein paar Tagen hatte ich einen Besucher, der meinte, ich solle die Augen nach dergleichen aufhalten. Ein Elf mit Namen Itharius. Ich glaube nicht, dass er wusste, dass ich sein Äußeres durchschauen konnte... Er war ein grüner Drache in Verkleidung. Wollte bestimmt seinen gefallenen Brüdern helfen.\n\nEr ist sicher hinter irgendwas her. Itharius ist zum Tempel selbst aufgebrochen. Vielleicht sucht Ihr dort besser nach ihm. Irgendetwas Übles geht hier vor.", progress = nil, completion = "Das Goblinmädchen schickt Euch? Sie hat ein gutes Auge, die Kleine.\n\nSie spricht die Wahrheit. Ich bin hier, um die Flut der Verderbnis, die von diesem Tempel ausströmt, aufzuhalten. Wenn Ihr Euer Volk vor einem üblen Schicksal bewahren wollt, &lt;Name&gt;, dann bitte ich um Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27870] = {title = "Zur Sumpftidenwacht", objective = "Sprecht mit Joanna Blauherz bei der Sumpftidenwacht.", description = "Egal, ob Ihr mir im Tempel helft oder nicht, Euer Volk muss erfahren, was hier vor sich geht.\n\nNördlich des Tempels haben ein paar Menschen Eurer Allianz der Sterblichen einen Posten errichtet, den sie die Sumpftidenwacht nennen. Sie führen überall im Sumpf Krieg gegen die Horde, und ich fürchte, dass dieser Konflikt sich noch weiter ausbreitet.\n\nEs ist nicht meine Aufgabe, mich in die Angelegenheiten der Sterblichen einzumischen, <Name>. Ich bitte Euch einfach nur, Euer Volk davor zu warnen, was im Tempel lauert.", progress = nil, completion = "Ärger im Tempel... Ich wünschte, wir hätten genügend Streitkräfte, um uns darum zu kümmern. Der Krieg mit Steinard ist bereits im vollen Gange. Wir brauchen jeden Mann, den wir kriegen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27871] = {title = "Nach Steinard", objective = "Sprecht mit Zentralenkommandant Ruag in Steinard in den Sümpfen des Elends.", description = "Egal, ob Ihr mir im Tempel helft oder nicht, Euer Volk muss erfahren, was hier vor sich geht.\n\nSüdwestlich des Tempels liegt die Hordenstadt Steinard. Die Orcs dort führen mit den neu in den Sümpfen angekommenen Menschen Krieg, und ich fürchte, dass dieser Konflikt sich noch weiter ausbreitet.\n\nEs ist nicht meine Aufgabe, mich in die Angelegenheiten der Sterblichen einzumischen, <Name>. Ich bitte Euch einfach nur, Euer Volk davor zu warnen, was im Tempel lauert.", progress = nil, completion = "Wir haben keine Zeit, um Orcs in den Tempel zu schicken, &lt;Name&gt;. Die Menschen kommen in großen Scharen. Wir müssen Steinard verteidigen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27874] = {title = "Avianas Vermächtnis", objective = "Findet Choluna im Schrein von Aviana auf dem Hyjal.", description = "Eure Erfahrung wird woanders gebraucht, <Name>.\n\nDirekt südwestlich des Weltenbaums findet Ihr den Schrein von Aviana, Heimat der Druiden der Kralle. Aviana, die oberste Mutter aller geflügelten Kreaturen, hat ihr Leben vor zehntausend Jahren für diese Welt hergegeben.\n\nIch spüre, dass ihr Schrein in Gefahr ist, genau wie die Druiden, die ihn bewachen. Sucht Choluna, einen der weisesten der geflügelten Druiden, tief innerhalb des Schreins auf.", progress = nil, completion = "Ysera selbst schickt Euch zu mir? Oh! Welch eine Ehre, mit einem Abgesandten der Aspekte zu sprechen.\n\nEs stimmt, dass unser Schrein in Gefahr ist. Die Harpyien, denen unsere Äste Schutz boten, haben sich gegen uns gewandt.\n\nDoch bitte stürzt Euch nicht in die Schlacht, bis Ihr nicht bereit seid. Unser Schrein ist nicht wie ein gewöhnliches Schlachtfeld. Benutzt seine Ruhe und Macht, um Eure Mitte zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27875] = {title = "Gebetsblume", objective = "Sammelt 10 Zweige der Gebetsblume im Wabersumpf.", description = "Ich habe jahrelang daran gearbeitet, die Krankheit der Zerschlagenen heilen zu können. Die verruchten Energien, die sie verdorben haben, haben mehr getan, als nur ihre Körper zu verunstalten... Sie haben ihnen das Licht geraubt. Sie können seine Wärme nicht spüren.\n\nIch kann Magtoor nicht der Dunkelheit überlassen, <Name>. Bevor es mit ihm schlimmer wurde, habe ich die Gebetsblume untersucht, die im Wabersumpf gedeiht. Selbst im dunkelsten Schatten wächst sie dort. Ich flehe Euch an, bringt mir einige davon, um des armen Magtoors Willen.", progress = "Habt Ihr die Gebetsblume dabei?", completion = "Die Zerschlagenen haben seit ihrer Ankunft in diesem Sumpf Gebetsblumen als Heilmittel verwendet. Wenn sie körperliche Schmerzen lindern, können sie vielleicht auch für mächtigere Heilungen verwendet werden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27876] = {title = "Die Geheimnisse des Sumpfes", objective = "Sammelt 10 Exemplare kräftigen Schlick von Wabersumpfklumpen.", description = "Der Wabersumpf verdankt seinen Namen einem einzigartigen Phänomen. Durch irgendeine Kraft angetrieben, sammelt sich der extrem feine Schlick und bewegt sich von allein vorwärts, als wäre er lebendig.\n\nZuerst war ich beunruhigt, dass dies eine verderbliche Kraft sei, aber meine Studien ergaben das Gegenteil: Welche Energie auch immer diesem Boden Leben einhaucht, sie ist positiver Natur. Vielleicht könnten auch die Zerschlagenen auf diese Art zu ihrem früheren Selbst wiedererweckt werden.\n\nDer Schlick mag es vielleicht nicht, eingesammelt zu werden, <Name>, aber bitte tut es trotzdem.", progress = "Konntet Ihr die Proben besorgen?", completion = "Wir werden es reinigen müssen, aber dann wird es sich als äußerst hilfreich erweisen. Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27877] = {title = "Die Schwachkopfliga", objective = "Besorgt 15 Dunkeleisenköpfe.", description = "Ich brauche Eure Hilfe bei einem kleinen Projekt, an dem ich arbeite, <Name>. Es fällt in einen Bereich, den ich gerne als \"defensive Archäologie\" bezeichne.\n\nIch möchte nichtmagische Gegenstände an verdächtigen Orten vergraben, damit diese Idioten der Allianz glauben, sie hätten etwas Wertvolles gefunden.\n\nHmm... An Hammerzehs Ausgrabungsstätte und der Festung Angor im Norden treiben sich die Dunkeleisenzwerge herum. Bringt mir ihre Köpfe. Ja, Ihr habt richtig verstanden, ihre Köpfe.\n\nSobald wir ihnen das Fleisch abgezogen haben, können wir die Schädel nutzen, um die Arbeiten der Zwerge zu stören.", progress = "<Lidia schaut Euch erwartungsvoll an.>", completion = "Ausgezeichnet! Wir werden sie sofort vergraben. Diese Dummköpfe der Forscherliga werden niemals darauf kommen, dass wir das waren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27878] = {title = "Gewaltsame Aneignung", objective = "Sucht im untersten Geschoss der Festung Angor nach Schätzen.", description = "Ich habe Euch einen kleinen Vorschlag zu machen, wenn Ihr interessiert seid.\n\nDie Dunkeleisenzwerge waren schon lange vor uns hier. Das heißt, dass die Zwerge als Erste dort waren, als die Titanenruinen zum Vorschein kamen, und sich die wertvollsten Gegenstände unter den Nagel gerissen haben. Ich wette, diese Schätze sind noch immer in der Festung Angor, nordwestlich von hier, unter Verschluss.\n\nWenn Ihr einen solchen Schatz haben wollt... stehlt ihn einfach.", progress = "So früh schon zurück?", completion = "Ich wusste es! Der Oberste Prüfer wird das mit Freuden sehen.\n\nGute Arbeit, &lt;Volk&gt;.", rewards = "Sonnenglühende GugelStaubschalenschildStaubwindwesteAngorschulterstückeEisenhiebumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27879] = {title = "Überleben der Dicksten", objective = "Erlangt 6 Fleischstücke der Staubspeier und 10 Lagen Seide der Staubspeier.", description = "Uns gehen die Vorräte zur Neige, <Fremder/Fremde>. Solange die schwarzen Drachen unsere Jagdgründe mit Zerstörung überziehen, haben wir keine Chance, an Nahrung zu gelangen.\n\nDie Oger im Süden jedoch haben genau, was wir brauchen. In ihrer Grotte solltet Ihr ausreichend Nahrung und Handwerkswaren finden.\n\nSie könnten sich aber mit Euch darum schlagen wollen. Seid also vorsichtig.", progress = "Willkommen zurück.", completion = "Ich nehme an, die Oger waren für Euch keine zu große Hürde. Hier - ein paar Münzen für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27880] = {title = "Tonnenschwere Starrköpfe", objective = "Tötet 12 Kämpfer der Staubspeier. Ihr könnt sowohl Raufer als auch Schamanen der Staubspeier töten.", description = "Meine Grunzer haben dieses Drachenproblem im Griff. Im Übrigen kann ich nicht zulassen, dass ein Grünschnabel wie Ihr, <Klasse>, dort hineinrennt und unsere Schlachtpläne ruiniert.\n\nIhr wollt Arbeit? Na schön, ich gebe Euch Arbeit, Untersucht das Ogerlager im Südwesten. Nach dem, was ich höre, scheint eine kleine Armee Kämpfer vor ihrem Unterschlupf aufgetaucht zu sein.\n\nWir können nicht herumsitzen und warten, bis sie uns in die Flanke fallen, Soldat... zumal wir bereits von schwarzen Drachen in Kämpfe verwickelt werden. Dünnt ihre Ränge aus, bevor sie es mit den unseren tun.", progress = nil, completion = "Ihr habt den Hauch eines Helden in Euch, &lt;Volk&gt;.\n\nJetzt verschwindet von meinem Schlachtfeld.", rewards = "Gorns weggeworfener MantelBastionshandschuheStaubspeierstiefelHalbtonnenschulterstückeBogen von KargathIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27881] = {title = "Blutwächterposten", objective = "Sprecht mit dem Obersten Prüfer Tae'thelan Blutwächter am Blutwächterposten im Ödland.", description = "Ich habe eine Idee, die reine Spekulation ist. Zum Glück sind reine Spekulationen eine meiner Spezialitäten.\n\nNördlich von hier hat die Archäologische Akademie neue Ruinen der Titanen unter dem Sand gefunden. Wenn es jemanden gibt, der älter und weiser ist als die Drachen, sind es die Titanen. Ich habe sogar Gerüchte gehört, dass die Titanen die Drachen ERSCHAFFEN haben.\n\nSprecht mit dem Obersten Prüfer Tae'thelan Blutwächter in seinem Lager nordwestlich von hier. Er wird weitaus mehr über die Titanen wissen als ich.\n\nWas habe ich Euch gesagt? Reine Spekulation.", progress = nil, completion = "Titanen? Ihr seid hier, um mit mir über die Titanen zu reden?\n\nDa seid Ihr am richtigen Ort, denn wir stehen kurz vor einer großen Entdeckung. Doch zuerst werdet Ihr Euch Euren Platz hier verdienen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27882] = {title = "Es geht nicht um Geschichte, sondern um Macht", objective = "Beschafft einen zerbrochenen Kelch, eine staubige Vase, eine irdene Hieroglyphe und ein Troggwerkzeug.", description = "Die Forscherliga mag ja einiges über den Vorgang des Grabens wissen. Was ihnen allerdings fehlt, ist ein Gefühl dafür, wie man die Artefakte BENUTZT, die sie ausgraben. Sie stellen ihre Schätze in statische Museen, statt diese mächtigen Dinge gemäß ihrer wahren Bestimmung zu verwenden.\n\nDie Zwerge sind Narren. Zum Glück sterben sie sehr schnell.\n\nIhr findet sie nördlich von hier, wie sie in die Wände der Schlucht hineingraben. Reißt ihnen alles, was Ihr könnt, aus ihren Händen mit den Stummelfingern und bringt es mir.", progress = "Ihr seid mit den befreiten Artefakten zurückgekehrt, nehme ich an?", completion = "Kelch... wertlos.\n\nVase... gefälscht.\n\nHieroglyphe... interessant, aber ziemlich weit verbreitet.\n\nWas ist das? Ich habe noch nie Trogghandwerkskunst von diesem Ausmaß gesehen! Da seid Ihr tatsächlich etwas äußerst Seltenem begegnet, &lt;Name&gt;.\n\nWir dürfen keineswegs die Troggs einfach übersehen. Sie mögen von schlichtem Gemüt sein, aber sie wissen Dinge über die tiefen, versteckten Orte dieser Welt.\n\nIhr habt Eure Arbeit recht ordentlich gemacht. Reden wir über Titanen, ja?", rewards = "Pantalons des StraßendiebsAusgrabungsarmschienenGefälschte KettenrüstungBrustplatte des EmporkömmlingsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27883] = {title = "Der Bauer des Wächters", objective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer des Wächters.\n\nBereitgestellter Gegenstand: \n", description = "Einer der wenigen Gegenstände von Wert, die wir aus diesen Ruinen mitgenommen haben, ist diese kleine Jadestatue.\n\nWir glauben, es ist eine Art Schlüssel, aber wir konnten nicht feststellen, was sie öffnet. Daher ist sie nutzlos für mich.\n\nVielleicht werdet Ihr mehr Glück damit haben.", progress = nil, completion = "&lt;Die Statue rastet in ihren Platz auf der großen Steinplatte ein.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27884] = {title = "Der Bauer der Schildwache", objective = "Findet eine Verwendung für den Bauern der Schildwache innerhalb des Tempels des Grabes der Behüter im Ödland.", description = "Wir haben diese kleine rote Statue bei der Leiche eines dieser Forscherliga-Archäologen gefunden. Leider waren es nicht wir, die sie umgebracht haben. Die örtliche Wildnis hatte das bereits übernommen.\n\nDie Statue ist schön gearbeitet, hat aber anscheinend ihre magische Kraft verloren. Ihr könnt mit ihr machen, was immer Ihr für richtig haltet.", progress = nil, completion = "&lt;Die Statue gleitet über den kalten Marmorboden und rastet ein.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27885] = {title = "Das Spiel des Wächters", objective = "Beendet das Spiel des Wächters, indem Ihr die Bauern des Wächters in eine nach innen gerichtete Position teleportiert.", description = "Ihr seht, wie sich die Statue erst in zwei, dann in vier, dann in acht identische Statuen in quadratischer Anordnung teilt.\n\nIhr hört eine Stimme, jedoch nicht mit Euren Ohren, sondern direkt in Eurem Kopf:\n\n\"Ein wahrer Wächter sieht nicht nach AUSSEN, um nach Anzeichen der Gefahr zu suchen.\n\n Ein wahrer Wächter richtet seinen Blick nach INNEN, immer darauf konzentriert, seine Beute zu schützen.\"\n\nVielleicht ist dies eine Art Rätsel?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27886] = {title = "Das Schildwachenspiel", objective = "Schließt das Spiel der Schildwache ab, indem Ihr die beiden roten Statuen verbindet.", description = "Als Ihr die Statue an ihren Platz stellt, erscheinen weitere steinerne Statuen in dem Raum. Es taucht auch eine rubinfarbene Statue auf, in einer kleinen Nische am hinteren Ende des Raums. Ihr hört eine Stimme:\n\n \"Die Schildwache sieht.\n Die Schildwache beschützt.\n Der Blick der Schildwache ist niemals abgelenkt.\"\n\nDiese rote Statue am anderen Ende des Raums sieht wichtig aus. Vielleicht solltet Ihr versuchen, die beiden roten Statuen zu verbinden?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27887] = {title = "Uralte Beschützer", objective = "Untersucht den Wächter und die Schildwache.", description = "Man hört ganz schön viel Gerumpel aus der zentralen Kammer des Grabes. Diese zwei großen Statuen sahen ganz schön verdächtig aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27888] = {title = "Zurück zu Blam", objective = "Bringt das Auge der Behüter zu Dr. Hieronymus Blam bei der Agmondkuppe im Ödland.", description = "Innerhalb der Kiste findet Ihr einen kleinen, runden Gegenstand, der auf einem Kissen liegt.\n\nWenn es hier unten ein Titanenartefakt geben sollte, dann muss es das sein. Ihr beschließt, ihn zu Dr. Blam zurückzubringen.", progress = "Und? Hat sich unser Schuss ins Blaue ausgezahlt?", completion = "Bloß ein winzig kleines Gerät?\n\nIch habe diese Titanen noch nie verstanden.\n\nNun gut! Wollen wir doch mal sehen, was dieser Piepser kann!", rewards = "HüterspeerHieronymus' GürtelGut gepolsterte StiefelDer folgende Zauber wird auf euch gewirkt:\n\nReturn to Blam: Summon Eye\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27889] = {title = "Neu-Kargath", objective = "Bringt das geläuterte Schwarzdrachenei zu Rhea in Neu-Kargath im Ödland.", description = "<Dr. Blam sieht sich das Ei schweigend an, zwinkert ein paar Mal und schaut Euch dann an.>\n\nHabt... Habt Ihr das gesehen? Unglaublich! Meine Idee mit dem Titanending hat funktioniert! Mit Eurer Hilfe, natürlich.\n\nWir sollten das hier zu Rhea bringen. Sie ist nicht mehr in der Lethlorklamm... Ihre Tarnung ist wohl aufgeflogen, als sie vor all diesen Welpen ihre wahre Form angenommen hat. Jetzt ist sie in einer großen Hordenniederlassung im Westen mit Namen \"Neu-Kargath\".\n\nSie wird auf Euch warten. Und auf das Ei.", progress = "Da habt Ihr aber eine ganz schön wertvolle Ladung dabei, <Name>.", completion = "Ich nehme Euch das Ei nun ab. Wir müssen es schleunigst bebrüten... und verstecken. Eine Menge wütender Drachen suchen danach.\n\nEs ist übrigens schön, Euch wiederzusehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27890] = {title = "Die harten Hunde", objective = "Sprecht mit Amakkar in Neu-Kargath im Ödland.", description = "In meiner Hast bei der Flucht aus der Lethlorklamm habe ich vergessen, mich um eine letzte Sache zu kümmern: Nyxondra. Sie ist frei und hat Alarm beim schwarzen Drachenschwarm ausgelöst. Der halbe Schwarm ist hier im westlichen Ödland und sucht nach dem Ei.\n\nIch kümmere mich darum, das Ei zu verstecken. Ihr kümmert Euch um einige der vorwitzigeren Drachen. Und Ihr werdet Hilfe dabei haben. Ich habe ein paar Söldner angeheuert, Ihr werdete sie in diesem Gasthaus finden.", progress = nil, completion = "Ihr seid der, auf den wir gewartet haben? Wurde auch Zeit, dass Ihr hier seid. Ich warte schon darauf, mir die Beine zu vertreten.\n\nAbmarsch, Jungs! Gehen wir ein paar schwarze Drachen töten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27891] = {title = "Amakkar, der Alleskönner", objective = "Benutzt 'Amakkars Nierenhieb' und 'Amakkars Taschentrank'.", description = "Bevor wir mit der Drachenjagd beginnen, lasst mich Euch ein bisschen erklären, wie ich kämpfe.\n\nIch bin nicht so stark oder robust wie diese zwei, aber ich hab ein paar Tricks im Ärmel. Auf Euren Befehl hin betäube ich Eure Feinde, um sie festzunageln. Ich habe auch immer ein paar Tränke auf Lager.\n\nWarum trainieren wir nicht ein bisschen zusammen? Auf in die Wildnis, dann werdet Ihr sehen, was es heißt, mit einem echten Orc zusammen zu kämpfen.", progress = nil, completion = "Ich freue mich darauf, an Eurer Seite zu kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27892] = {title = "Jurrix der Vollstrecker", objective = "Benutzt 'Jurrix' Feuerstoß' und 'Jurrix' Zeitverschiebung'.", description = "Oh, Ihr wollt Euch unterhalten? Also schön.\n\nIch bin Jurrix, der einzige Söldner hier, der noch ein paar Gehirnzellen hat. Und der einzige, dessen Angriffe wirklich etwas bewirken. Diese lebenden Schilde um mich herum behalte ich nur, damit ich nicht getötet werde.\n\nHört zu, Ihr seid der Chef dieser Operation. Ihr müsst nur ein Wort sagen und ich werde einen Feuerball durch das Herz Eures Ziels jagen. Wenn das alles zu schnell geht, kann ich sogar die Zeit ein wenig verschieben, damit Ihr noch ein paar zusätzliche Angriffe unterbringen könnt.\n\nWarum versuchen wir nicht, gemeinsam zu kämpfen?", progress = nil, completion = "Ich glaube, Ihr seid bereit, &lt;Name&gt;. Allmählich bekommt Ihr es in den Griff.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27893] = {title = "Gargal, das Ungetüm", objective = "Benutzt 'Gargals Schildwall' und 'Gargals mächtiger Ruf'.", description = "Es ist Euch vielleicht nicht aufgefallen, aber für einen Orc bin ich recht groß.\n\nIch stelle sicher, dass meine beiden Kumpel hier nicht in zu große Schwierigkeiten geraten. Sie sind klein und haben nicht so einen großen Schild wie ich. Ich bin groß und kann ein paar Schläge von Monstern gut wegstecken! Außerdem kann ich es meistens schaffen, dass sie nur meinen Schild treffen!\n\nIch kann auch Euch beschützen. Kommt, gehen wir ein bisschen trainieren. Ich sorge dafür, dass die Gegner mich angreifen, nicht Euch.", progress = "Sorgt Euch nicht kleiner <Volk>. Ich beschütze Euch.", completion = "Seht Ihr? Kein Grund zur Sorge, wenn Gargal da ist. Sagt mir nur Bescheid und ich beschütze Euch vor den Monstern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27894] = {title = "Der Zorn eines Drachenschwarms", objective = "Tötet Kalaran den Vernichter und 4 Soldaten des dunklen Schwarms.", description = "Hallo, <Name>. Mir scheint, Ihr vier hattet genug Zeit, Euch anzufreunden.\n\nIch habe eine erste Aufgabe für Euch. Kalaran, ein uralter schwarzer Drache mit beträchtlicher Macht, hat sich der Jagd auf das von uns beschützte Ei angeschlossen. Wir müssen ihn aufhalten, bevor er ihm zu nahe kommt.\n\nIhr findet ihn und seine Diener im Staubbecken, östlich von Neu-Kargath. Sucht und besiegt ihn. Wahrscheinlich werdet Ihr die Hilfe Eurer neuen Söldnerverbündeten brauchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27895] = {title = "Die Jagd geht weiter", objective = "Besiegt General Jirakka, Moldarr und 6 Mitglieder der Drachenbrut des dunklen Schwarms.", description = "Der schwarze Drachenschwarm meint es ernst. Wie Ihr wahrscheinlich bemerkt habt, hat er einen Großteil von Neu-Kargath an sich gerissen. Diese Truppen stehen unter dem Befehl von General Jirakka und seinem Champion Moldarr. Sie müssen aufgehalten werden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27896] = {title = "Das Leid und der Zorn", objective = "Erschlagt Nyxondra und 12 von Nyxondras Brutlingen.", description = "Am meisten bereue ich, wie wir... nein, wie ich Nyxondra behandelt habe. Ich habe sie gezwungen, Eier zu legen, und dann mit ihnen experimentiert. Immer und immer und immer wieder.\n\nObwohl ich selbst Mutter bin, kann ich mir ihr Leid kaum vorstellen.\n\nNein... Ich darf nicht schwach werden. Unsere Arbeit dient immerhin dem Wohl der zukünftigen Generationen der schwarzen Drachen. Ihr Opfer war notwendig.\n\nNun umkreist sie die Ruinen von Kargath, nordwestlich von Neu-Kargath, wahnsinnig vor Zorn. Bitte, Helden... erlöst sie von ihrem Elend.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27897] = {title = "Das Versteckte Gelege", objective = "Sprecht mit Rhea im Versteckten Gelege im Ödland.", description = "Jetzt, da die meisten schwarzen Drachen aus dem Ödland abgezogen sind, können wir das Ei wieder sicher transportieren. Ihr werdet mich auf einer kleinen Hochebene nördlich von Neu-Kargath finden.\n\nSucht mich dort auf.", progress = nil, completion = "Das Ei muss immer in Bewegung bleiben. Wir sind hier nicht mehr sicher.\n\nSogar in seinem Wahnsinn kennt Todesschwinge alle versteckten Orte dieser Welt. Das Ei kann nicht an einem Ort bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27898] = {title = "Rheastraszas Geschenk", objective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", description = "Wartet hier. Ich werde das Ei holen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27899] = {title = "Das Leuchten in seinen Augen", objective = "Sprecht mit Harrison Jones am Obelisk der Sonne.", description = "Wenn Ihr nach Harrison sucht, den habt Ihr gerade verpasst.\n\nEr hat die ganze Zeit über seine neueste Entdeckung geredet und wie alles jetzt anfängt, einen Sinn zu ergeben.\n\nWie auch immer... Sein Gerede hat für mich keinen Sinn ergeben.\n\nIch habe versucht, ihn zum Hierbleiben zu bewegen und sich mit mir an ein paar Sonnenuntergängen in der Wüste zu erfreuen, aber wenn er dieses Leuchten in den Augen hat, kann man mit ihm nicht reden.\n\nKönntet Ihr einmal nach ihm sehen?\n\nEr ging nach Süden zu dem großen Monolith.", progress = nil, completion = "Wie es scheint, bin ich nicht der einzige, der sich für diese Obelisken interessiert...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27900] = {title = "Mit dem Kerl werde ich fertig", objective = "Tötet 10 Lufteinheiten von Schnottz.", description = "Gutes Timing, <Name>.\n\nAnscheinend bin ich nicht der Einzige, der sich für diese Obelisken interessiert und diese Jungs haben kein Interesse an einem Erfahrungsaustausch.\n\nIch glaube, mit dem Kerl hier werde ich fertig.\n\nVielleicht könntet Ihr Euch um ein paar seiner Freunde kümmern, bevor sie auch hierher kommen?", progress = nil, completion = "Welch eine Erleichterung. Danke &lt;Name&gt;.\n\nWie sich herausstellt, habe ich hier alle Hände voll zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27901] = {title = "Sie wissen nicht, was sie hier haben", objective = "Baut das Aktivierungsgerät der Titanen zusammen.", description = "Hört zu, <Name>. Ich habe nicht viel Zeit zum Reden.\n\nDiese Kerle graben hier Relikte aus und greifen sich die Teile uralter Technologie, die wir brauchen!\n\nIhr müsst ihre Kisten nach Teilen eines uralten Aktivierungsgerätes durchsuchen. Die Offiziere müssten die Codes haben, die Ihr zum Öffnen der Kisten benötigt.\n\nBeeilt Euch.\n\nWir dürfen nicht zulassen, dass sie das Zeug in ihre Flugzeuge laden!", progress = "Habt Ihr das Aktivierungsgerät der Titanen, <Name>?", completion = "Das ist es!\n\nGut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27902] = {title = "Der Reinquell", objective = "Sammelt 6 Reinquellpartikel von Reinquellelementaren.", description = "Magtoor hat mir von dem Schamanismus berichtet, den die Zerschlagenen betreiben. Der große Nobundo sagte einst, dass der Pfad der Elemente in gewisser Weise nur ein weiterer Weg zum Licht sein könnte.\n\nIch kann nur hoffen, dass daran etwas Wahres ist. Die Elementare, die sich in der Nähe der Reinquellhöhle im Süden aufhalten, sind eine Quelle wahrlich makellosen Wassers. Sie können chaotisch und brutal sein, aber das von ihnen erbeutete reine Wasser ist die perfekte Leitung für den Segen des Lichts.\n\nBitte bringt mir dieses Wasser, <Name>.", progress = "Haben die Elemente ihre Quelle aufgegeben?", completion = "Solch eine Klarheit... Hoffen wir, dass dies dem armen Magtoor hilft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27903] = {title = "Zündung", objective = "Besorgt die Linse der Sonne.", description = "Dieser Kerl lässt sich nicht unterkriegen!\n\nIhr macht Eure Sache gut, <mein Junge/meine Liebe>. Jetzt bleibt nur noch eins zu tun.\n\nMeine Forschungen haben ergeben, dass dort unten eine Titanenstatue sein müsste. Benutzt das Gerät, um sie zu aktivieren und nehmt sie dann auseinander.\n\nWenn meine Theorie richtig ist, verbirgt sich in der Statue der Schlüssel, um diesen Obelisken wieder zu aktivieren.", progress = "Zeit, herauszufinden, ob dieser alte Mechanismus noch funktioniert...", completion = "Laut Harrisons Notizen, sollte der Obelisk reaktiviert werden, wenn man die Linse auf dieses Podest legt.\n\nWas genau das bedeutet, werden wir dann sehen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIgnition Completion Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27904] = {title = "Nebelatem", objective = "Beschafft 5 rauchgraue Kristalle von Nebelgrellen.", description = "Die Grelle sind Waldgeister, die sich westlich von hier im Nebligen Tal aufhalten. Sie sehen zwar aus wie Wichtel, aber bei denen, die ich untersucht habe, konnte ich keine dämonischen Spuren feststellen. Soweit ich das sagen kann, sind sie unverderbt.\n\nDiejenigen, die im Tal leben, sind eins mit dem Wind. Sie beschwören Böen, wenn ihnen danach ist. Diese reine Luft kann ich vielleicht in meinem Heilmittel für den armen Magtoor verwenden.\n\nBitte, <Name>, sammelt rauchgraue Kristalle für mich. Man findet sie in den Körpern der Grelle. Ich muss jedes mögliche Heilmittel ausprobieren.", progress = "Habt Ihr die Kristalle?", completion = "Hoffentlich werde ich mit ihnen eine Heilung finden, &lt;Name&gt;. Danke, dass Ihr sie mir gebracht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27905] = {title = "Heckschütze!", objective = "Benutzt das Heckgeschütz, um den Bomber von Schnottz zu verteidigen.", description = "Okay, ich habe diesen Kerl weichgeklopft, wie wäre es, wenn Ihr mir helft, ihn zu erledigen?\n\nIch habe einen Fluchtplan für uns, aber dafür braucht man viel Mut und ein bisschen Glück.\n\nSeid Ihr dabei, <Name>?\n\nDann folgt mir...", progress = nil, completion = "Das war gute Arbeit da hinten, &lt;Name&gt;.\n\nAnscheinend sind wir sie losgeworden - wenigstens für den Moment.", rewards = "AeronautenhelmVerstärkter SicherheitsgurtFlugoverall des HeckschützenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27906] = {title = "Neeka Blutnarbe", objective = "Sprecht mit Neeka Blutnarbe an der Splitterspeerkreuzung.", description = "Es gibt noch viel zu tun, um uns von dem Angriff zu erholen und auf den nächsten vorzubereiten. All unsere Späher werden sich koordinieren müssen.\n\nNeeka Blutnarbe ist unsere beste Späherin und im harschen Ödland ausgebildet worden. Sie wurde zur Splitterspeerkreuzung geschickt, um Allianzaktivitäten zu überwachen.\n\nBegebt Euch zu Neeka, <Name>. Berichtet Ihr, was in Steinard vorgefallen ist. Unterstützt sie bei allem, worum sie Euch bittet.", progress = nil, completion = "Ich hoffe, dass Euch meine Trauer amüsiert, &lt;Name&gt;. In dieser Gegend wird das die einzige Unterhaltung sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27907] = {title = "Gebetsblume", objective = "Sammelt 10 Zweige der Gebetsblume im Wabersumpf.", description = "Ich bin ruiniert, <Klasse>. Ich habe meine Stärke in Helgrum investiert, und jetzt blutet sie aus seinen klaffenden Wunden. Wunden, die zu tief sind, um zu heilen, Fleisch, das sich nicht mehr schließen will.\n\nEr murmelt vor sich hin, vor Angst, Schmerz und Fieber. Ich kann jetzt nicht von seiner Seite weichen. Nicht jetzt. Bitte, ich muss Euch voller Scham bitten, mir ein paar Kräuter zu besorgen.\n\nDie Gebetsblume, die in den Sümpfen wächst, ist eine alte Heilpflanze. Damit sollten seine Schmerzen gestillt werden können.", progress = "Habt Ihr die Gebetsblume dabei?", completion = "Ich werde sie zermahlen und versuchen, sie ihm einzuflößen. Habt Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27908] = {title = "Die Geheimnisse des Sumpfes", objective = "Sammelt 10 Exemplare kräftigen Schlicks von Wabersumpfklumpen.", description = "Helgrums Wunden entzünden sich in dem Sumpfklima. Sie schwellen an und eitern, und erfüllen seine letzten Minuten mit Höllenqualen. Ich brauche etwas, um sie abzudecken.\n\nDie Geister gehen in diesem Sumpf um. Sie erfüllen selbst den Schlamm, formen ihn zu Brocken glatter Erde und hauchen ihm Leben ein.\n\nDie Geister des kühlen, reinen Schlicks werden ihm etwas Linderung verschaffen. Bitte sammelt ihn für mich, da ich ihn nicht allein lassen möchte.", progress = "Helgrum atmet noch. Habt Ihr den Schlick dabei?", completion = "Wenigstens kann ich seine Schmerzen mit meinen Händen lindern, während er noch atmet. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27909] = {title = "Der Reinquell", objective = "Sammelt 8 Reinquellpartikel von Reinquellelementaren.", description = "Helgrums Atemzüge werden langsamer. Seine Zeit ist gekommen.\n\nIch brauche Wasser. In den Teichen der Reinquellhöhle streifen Elementare umher. Das Wasser, das aus ihnen strömt, ist das reinste hier im Sumpf.\n\nSelbst wenn ich es wagte, von Helgrums Seite zu weichen, würde meine Axt in meiner Hand zittern. Ich flehe Euch nochmals an, Mitleid mit mir zu haben, um seinetwillen. Bringt mir die Partikel der Elementare, auf dass sein letzter Trank rein und erquicklich sein möge.", progress = "Ihr seid zurückgekehrt.", completion = "Er kann nicht so viel trinken. Den Rest können wir vielleicht benutzen, um seinen Körper zu waschen, nachdem...\n\n&lt;Neeka starrt frustriert, erschauert und dreht dann ihren Kopf zur Seite.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27910] = {title = "Späte Reue", objective = "Besorgt Dämmerfangs Balg.", description = "Wenn ich mich schon erniedrigen und kriechen muss, dann kann ich auch nach allem fragen, was ich kriegen kann. Es gibt einen letzten Gefallen, um den ich Euch bitten würde - nur noch eine Aufgabe, um die ein beschämter Orc Euch bittet.\n\nHelgrum hatte eine Beute, die er über alles schätzte. Dämmerfang, der Ogerfresser, der große Panther des Nebligen Tals. Er hat sich niemals die Muße genommen, ihn zu verfolgen. Obwohl er ihn unbedingt jagen wollte, so waren doch unsere Späherpflichten zu wichtig.\n\nWenn er Dämmerfang nicht in dieser Welt jagen kann, so soll er ihn in der nächsten jagen können. Nehmt die Jagd für ihn auf und bringt mir Dämmerfangs Balg.", progress = "Hat Dämmerfang sich gezeigt?", completion = "Jetzt, da Dämmerfang seinen Körper umhüllt, wird er den Geist des Tieres mit ins Jenseits nehmen.\n\nHört auf mich. Einen abergläubischen, alten Narren. Es tut mir so leid, Helgrum...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27911] = {title = "Der letzte Atemzug", objective = "Begleitet Helgrums letzte Momente auf Erden.", description = "Er regt sich...\n\nBitte bleibt bei mir, <Name>. Lasst uns gemeinsam Helgrum ehren. Ihr habt so viel für ihn getan.", progress = nil, completion = "Er ist von uns gegangen.\n\nEr hat Recht. Ich muss stark für ihn sein...", rewards = "Ihr bekommt:\n\nLetzter Atemzug"}
MultiLanguageQuestData['de'][27912] = {title = "Der Schatz der Titanen", objective = "Untersucht den Schatz der Behüter.", description = "Als der zweite Verteidiger zu Boden fällt, erscheint im hinteren Teil der Kammer eine Kiste. Könnte es das sein, was sie beschützt haben?", progress = nil, completion = "Ihr werft einen Blick in die Kiste...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27913] = {title = "Der Schatz der Titanen", objective = "Untersucht den Schatz der Behüter.", description = "Als der zweite Verteidiger zu Boden fällt, erscheint im hinteren Teil der Kammer eine Kiste. Könnte es das sein, was sie beschützt haben?", progress = nil, completion = "Ihr werft einen Blick in die Kiste...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27914] = {title = "Der Segen des Grünen Drachenschwarms", objective = "Sprecht mit Lord Itharius an der Spitze des Tempels von Atal'Hakkar.", description = "Ihr habt gute Arbeit geleistet, <Name>. Jammal'an ist uns zwar entkommen, aber sein Rückzug erlaubt es mir, den Tempel nach Belieben zu betreten.\n\nBleibt, wo Ihr seid und bewegt Euch nicht. Ich werde Eure Rückkehr beschleunigen, indem ich Euren Geist durch den Smaragdgrünen Traum zu mir bringe.\n\nDabei wird Euch vielleicht etwas schwindelig.", progress = nil, completion = "Ihr habt mir und meinem Volk einen großen Dienst erwiesen, &lt;Name&gt;. Nehmt dies als Symbol meines Dankes und Eures Mutes.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTraumamulettTraumanhängerTraummedaillon\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27915] = {title = "Das Herz des Tempels", objective = "Sprecht im Inneren des Tempels von Atal'Hakkar erneut mit Lord Itharius.", description = "Ich muss gestehen, dass ich persönlich in diese Angelegenheit verwickelt bin. Einer der ersten grünen Drachen, die hier verderbt wurden, war mein Bruder Eranikus.\n\nIch dachte, dass Eranikus tot sei, für immer von den düstersten Rissen des Alptraums verschluckt. Doch nun habe ich gehört, dass sein Schemen im Tempel aufgetaucht ist. Ich weiß nicht, ob er es wirklich ist oder nur ein leeres, schwermütiges Echo seiner selbst.\n\nWenn Ihr mir weiter helfen wollt, kehrt zur Halle der Masken zurück und reist durch den Bogengang in das wahre Sanktum des Tempels. Ich werde dort auf Euch warten.", progress = nil, completion = "Ich freue mich, Euch wiederzusehen, &lt;Name&gt;. Es ist sehr ehrenhaft von Euch, dass Ihr mich weiterhin unterstützt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27916] = {title = "Ruags Bericht", objective = "Überbringt Zentralenkommandant Ruag in Steinard den Splitterspeerbericht.", description = "Hier ist Ruags Bericht, <Name>. Sagt ihm, dass sein Kundschafter immer noch hier ist.\n\nErwähnt Helgrum nicht. Niemand sonst soll durch diese tragische Nachricht abgelenkt werden.\n\nIch selbst muss stark sein. Wir alle müssen stark sein.", progress = "Ja?", completion = "&lt;Ruag überfliegt den Bericht.&gt;\n\nIch verstehe. Danke für diese Informationen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27917] = {title = "Erschnüffelt sie", objective = "Tötet Baron Ashbury.", description = "Ich konnte Godfrey und seine Kameraden schon kilometerweit riechen. Sie haben ihre Spuren auf der Flucht nicht gerade gut verwischt. Ein Fehler, der sie in ihr Grab bringen wird.\n\nEiner von ihnen ist sehr nah und obwohl sich ihr Geruch im Untod verändert hat, bin ich sicher, dass es Ashbury ist. Geht hinein und reißt ihn in Stücke! Wir stellen sicher, dass die Verlassenen uns bei unserer Aufgabe nicht in die Quere kommen.", progress = nil, completion = "Der Duft von frisch vergossenem Verräterblut füllt meine Nase und er ist überaus belebend. Mein Kampfrausch wird aber erst verebben, wenn Godfrey als lebloser Haufen im Staub liegt.\n\nEr glaubt, eine Armee lebloser Kadaver kann den Zorn der Blutfangworgen aufhalten? Wir werden ihre Knochen noch jahrelang abnagen, nachdem unser Werk hier vollbracht ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27918] = {title = "Der Sichere Hafen", objective = "Bringt die Draenethystkristalle zu Anachoret Avuun.\n\nBereitgestellter Gegenstand: \n", description = "Anachoret Avuun ist einer unseren nicht verderbten Brüder, die anderen Völkern als Draenei bekannt sind. Er kam in den Sicheren Hafen, um uns zu heilen und zu versuchen, ein Gegenmittel zu finden. Er war es, der mich hierher geschickt hat, um diese Kristalle zu sammeln.\n\nEr kümmert sich gerade um einen sehr kranken Freund, und obwohl er sogar an die Exodar selbst Nachricht entsandt hat, findet er niemanden, der ihn unterstützt. Könntet Ihr ihm diese Kristalle bringen, <Name>? Ihr seid vielleicht <der Einzige, der/die Einzige> die; ihm helfen kann.", progress = nil, completion = "Vielen Dank, &lt;Klasse&gt;. Ich fürchte, dass es zu spät sein könnte... aber ich weigere mich aufzugeben, selbst wenn die Exodar mein Flehen nicht erhört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27919] = {title = "Weiter in die Verwüsteten Lande", objective = "Reist in die Verwüsteten Lande und sprecht mit Enohar Donnerbräu in Burg Nethergarde.", description = "Wir wissen Eure Hilfe hier in diesem Sumpf zu schätzen, <Name>. Ich muss Euch mitteilen, dass ich ein Schreiben aus Burg Nethergarde erhalten habe.\n\nEnohar Donnerbräu bittet um Hilfe bei der Untersuchung der Schiffswracks in den Roten Weiten, doch niemand will diese Reise unternehmen. Ich selbst kann den Sicheren Hafen leider nicht verlassen.\n\nBurg Nethergarde liegt in den Verwüsteten Landen, südlich der Sümpfe des Elends. Kommt Steinard auf Eurer Reise nicht zu nah.", progress = nil, completion = "Ah, schickt Euch Avuun? Gut, gut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27920] = {title = "Bis an die Zähne bewaffnet", objective = "Tötet Baron Silberlein und Kommandant Grüntal.", description = "Bei unserem Angriff auf die Burg sind wir auf unvorhergesehene Hindernisse getroffen, <Name>. Es scheint, als würden die Diener, die Baron Silberlein und Kommandant Grüntal im Leben umsorgten, dies auch noch im Tode tun, und Godfrey hat sie direkt zwischen sich und uns platziert.\n\nKeine Sorge, wir werden nicht zulassen, dass sie mehr als eine kleine Unannehmlichkeit darstellen. Vernichtet sowohl Silberlein als auch Grüntal. Es wird die Wächter nicht nur ihrer Meister berauben, die ihnen Anweisungen geben, es wird uns auch unserem finalen Ziel sehr viel näher bringen.", progress = "Es ist zum Verrücktwerden, dass wir diese Geistersoldaten töten müssen, obwohl sie rein gar nichts mit dem eigentlichen Missionsziel zu tun haben. Godfrey ist in der Tat ein gerissener Gegner.", completion = "Wir haben es fast geschafft, &lt;Name&gt;. Die Zeit ist gekommen, den letzten Vorstoß zu machen und Walden das Handwerk zu legen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27921] = {title = "Mit Klauen und Zähnen", objective = "Tötet Lord Walden.", description = "Es scheint, als hätte Lord Walden unsere Anwesenheit endlich bemerkt und seine Verteidigung verstärkt. Verschwendete Liebesmüh... nichts wird unser Rudel aufhalten.\n\nDer Weg zu ihm ist voller Diener der Geißel, doch ich vertraue darauf, dass Ihr ihn freimachen könnt, damit der Rest von uns folgen kann. Sobald wir Walden getötet haben, sollten wir direkt zu seinem feigen Anführer vordringen können.", progress = "Wir stehen voll hinter Euch, <Name>.", completion = "&lt;Rudelführer Ivar Blutfang grinst Euch an, wobei er seine rasiermesserscharfen Zähne entblößt.&gt;\n\nDank Eurer wackeren Hilfe dauert es jetzt nicht mehr lang, bis die Burg uns gehört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27922] = {title = "Verräter!", objective = "Versteckt Euch hinter einem Wedel der Neferset und enthüllt das Geheimnis der Neferset.", description = "Bitte, <Fremder/Fremde>. Ihr müsst mir helfen.\n\nIch bin hierhergekommen, um die Ankunft eines mächtigen Verbündeten der Neferset zu untersuchen. Dabei wurde ich von meinen engsten Verbündeten verraten und dem Feind überlassen.\n\nGeht zu der Terrasse über uns im Osten und sucht die Information, die ich nicht finden konnte. Ihr müsst Euch vor den Neferset verbergen. Vielleicht könnt Ihr Euch hinter einer der großen Pflanzen auf der Plattform verstecken, um Eure Anwesenheit geheim zu halten.\n\nErledigt das für mich und ich werde Euren Freunden dabei helfen, in Sicherheit zu gelangen.", progress = "Was habt Ihr gesehen, <Name>?", completion = "Einen Dschinn! Wir müssen hier so schnell wie möglich weg.\n\nDiese unheilige Allianz der Neferset mit den Helfern von Todesschwinge bedeutet nichts Gutes für uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27923] = {title = "Rauch in ihren Augen", objective = "Verbrennt Heuhaufen in der Verlorenen Stadt der Tol'vir in Uldum.", description = "Ich weiß zwar nicht, was für einen behämmerten Plan Euer Freund da ausbrütet, aber wir werden eine Ablenkung brauchen, wenn wir eine Chance haben wollen, zu entkommen.\n\nNehmt die Fackel von der Kohlenpfanne und legt ein paar Feuer.\n\nVielleicht gelingt es uns dadurch, den Neferset-Abschaum für ein paar Minuten abzulenken und das gibt uns die Gelegenheit, die wir brauchen.", progress = nil, completion = "Ja. Ich höre, wie die Neferset sich gegenseitig nach Osten rufen. Das könnte noch klappen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27924] = {title = "Budds Plan", objective = "Besorgt 6 Rüstungen der Neferset.", description = "Ich hab' 'ne Idee! Vertraut mir, diesmal ist es eine gute!\n\nBesorgt einige dieser glänzenden Rüstungsteile, die die Katzenmenschen tragen.\n\nDieser Plan kann nicht schiefgehen. Vertraut mir.", progress = "Habt Ihr die Teile, <Name>?", completion = "Ausgezeichnet. Ihr werdet schon sehen, das kann unmöglich schiefgehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27925] = {title = "Effiziente Ausgrabungen", objective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand: \n", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nEs wird deutlich, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist. \n\nVielleicht wäre es angebracht, sich einmal vorzustellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27926] = {title = "Gastfreundschaft des Ostens", objective = "Bellok Leuchtklinge möchte, dass Ihr Euch unter die Gäste in Schnottz' Landeplatz mischt.", description = "Der Kommandant ist gerade sehr beschäftigt, fürchte ich.\n\nDie Anforderungen solch einer Operation nehmen dieser Tage fast seine ganze Aufmerksamkeit in Anspruch.\n\nWas haltet Ihr davon, Euch ein wenig unter unsere Gäste zu mischen, während Ihr darauf wartet, mit ihm zu sprechen?\n\nWir haben eine Auswahl der berühmtesten Einwohner Azeroths eingeladen, um der Enthüllung der Geheimnisse dieser Region beizuwohnen.\n\nIch bin davon überzeugt, dass Ihr sie ausgesprochen faszinierend finden werdet.", progress = nil, completion = "Ich gehe davon aus, dass Ihr keine Schwierigkeiten hattet, mit unseren Gästen auszukommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27927] = {title = "Hinunter zur Narbe", objective = "Findet Theldurin den Verirrten nahe der Narbe des Weltenbrechers im Ödland.", description = "Das Ödland beherbergt einige ungewöhnliche Leute, viele davon halten sich hier schon seit geraumer Zeit auf. \n\nDa waren zum Beispiel drei Herren, die hier in der Stadt lebten. Ich vergesse immer ihre Namen... Der Zwerg hieß glaube ich Theldurin. Jedenfalls sind sie vor einigen Tage mit einem Rucksack voller Bier nach Süden aufgebrochen und seitdem habe ich nichts mehr von ihnen gehört. Ich glaube, sie wollten zu der großen Narbe.\n\nWürde es Euch etwas ausmachen, nach ihnen zu sehen? Ich wüsste gerne, dass es ihnen gut geht.", progress = nil, completion = "Man hat Euch geschickt, um nach uns zu sehen? Pfft... Ich lebe schon länger in dieser Wüste als die meisten dieser Trottel. Wir lassen nur die Landschaft auf uns wirken und erzählen uns Geschichten über alte Zeiten.\n\nErzählt Ihr gerne Geschichten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27928] = {title = "Feines für den Fellhändler", objective = "Erbeutet 5 Felle eines Wüstenkoyoten.", description = "Der Kommandant kann zu denen, die ihm Loyalität erweisen, sehr großzügig sein. Ich wüsste da etwas, das Ihr tun könnt, um Euch bei ihm beliebt zu machen.\n\nBevor er seine... äh... Belegschaft aufgebaut hat, handelte er mit Tierfellen.\n\nEr ist in der Kunst der Lederverarbeitung sehr bewandert. Der Fellhändler kann sogar bei den zerlumptesten Fellen noch Wunder bewirken.\n\nDie ausgetrocknete Oase im Osten beheimatet angeblich eine seltene Koyotenrasse.\n\nIhre Felle wären ein wunderbares Geschenk.", progress = "Hattet Ihr Erfolg auf der Jagd?", completion = "Oh, die sind vorzüglich!\n\nDer Kommandant wird daraus eine Winteruniform herstellen können.", rewards = "Mit Ankhs verzierte ArmschienenFlensergamaschenMakellose KojotenschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27929] = {title = "Holt sie 'runter", objective = "Benutzt den gestachelten Fleischerhaken, um 4 Donnermar-Greifenreiter von ihren Reittieren zu holen und tötet sie dann.", description = "Ein einziger Drache des Drachenmalklans wiegt ein Dutzend Wildhammergreifenreiter auf. Holt sie von ihren verlausten Vögeln und sie sind nichts mehr wert.\n\nSogar Ihr könnt sie dann mit Leichtigkeit töten, Horden-<Klasse>.\n\nJagt Greifenreiter, die über den Fluss nördlich von Blutschlucht fliegen. Nehmt diesen Haken und werft ihn auf sie, während sie vorüberfliegen. Durch ihren Schwung werden sie von ihrem Reittier genau vor Eure Füße geschleudert. Tötet sie! Tötet einige Donnermar-Greifenreiter und ich werde glauben, dass Eure Horde so mächtig ist, wie Ihr behauptet.", progress = nil, completion = "Ihr seht leicht angeschlagen aus. Diese Zwerge haben Euch keine Schwierigkeiten bereitet, oder doch?\n\nEs war dennoch eine beeindruckende Vorstellung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27930] = {title = "Verwüstung", objective = "Sucht nach Rheastrasza.", description = "Die Luft ist rein. Wenn Rheastrasza oder das Ei durch ein Wunder Todesschwinges Flammen überlebt haben, werden sie so bald wie möglich Eure Hilfe benötigen.", progress = nil, completion = "Helden:\n\nWenn Ihr das hier lest, war mein Verdacht berechtigt. Todesschwinge hat uns gefunden. Das Ei ist zerstört - ebenso wie ich.\n\nDas war allerdings von Anfang an der Plan. Ihr müsst wissen... Das Ei, das Todesschwinge zerstörte, war nicht das Ei, das er suchte.\n\nEs war meins.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27931] = {title = "Die Bebenden Felder", objective = "Sprecht mit Schiefer Treibsand auf den Bebenden Feldern in Tiefenheim.", description = "Bevor Ihr uns hier helfen könnt, müssen wir uns erst um die Streitkräfte Therazanes, der Steinmutter, im Süden kümmern. Die Elementare und Riesen der Bebenden Felder werden momentan zusammengestellt.\n\nAuch sie sind auf der Suche nach dem mittleren Fragment der Weltensäule. Sie werden uns mitten in unserem Krieg mit den Steintroggs angreifen und wir werden sie nicht abwehren können.\n\nIch habe den Erzgeomanten bereits vorgeschickt. Geht zu Schiefer Treibsand und tut, was er sagt.", progress = nil, completion = "Gut, dass Ihr hier seid, &lt;Volk&gt;.\n\nWir müssen schnell handeln, um die Streitmächte Therazanes vom Angriff abzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27932] = {title = "Die Axt der irdischen Trennung", objective = "Tötet 5 gespaltene Smaragdkolosse.", description = "Die Smaragdkolosse sind die größten Kreaturen der Steinmutter. Sie müssen als erstes von dem Feld entfernt werden.\n\nIch habe Steinvater Erzmantels Axt für diesen Zweck mitgebracht. Benutzt sie, um die Riesen zu spalten.\n\nDadurch bekommen sie eine leichter zu handhabende Größe. Dann könnt Ihr sie töten.", progress = nil, completion = "Danke, &lt;Name&gt;. Ohne all ihre Riesen werden Therazanes Streitkräfte es schwerer haben, Steinruh einzunehmen.\n\nWenn Ihr jetzt bitte meine Axt zurückgeben würdet. Ich werde darauf aufpassen, bis Ihr den Steinvater retten könnt.", rewards = "Zurechtstutzende ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27933] = {title = "Elementarerz", objective = "Sammelt 6 Elementarerze.", description = "Ihr werdet Euch hier mit dem Anführer von Therazanes Streitkräften auseinandersetzen müssen. Um aber schnell und sicher zu ihm zu gelangen, muss ich ein Ritual durchführen.\n\nGeht hinaus aufs Feld und sammelt Elementarerz von den Jadewütern. Wenn wir genug davon haben, sollte ich in der Lage sein, Euch eins mit der Erde werden zu lassen, damit Ihr dorthin gelangt, wo Ihr hin müsst.", progress = "Habt Ihr alles Notwendige?", completion = "Das sollte reichen. Ich benötige nur einen Moment für die Vorbereitung des Rituals.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27934] = {title = "Eins mit der Erde", objective = "Beendet das 'Eins mit der Erde'-Ritual.", description = "Der hiesige Anführer der Streitkräfte der Steinmutter ist ein großer Erdelementarlord namens Lavinius. Zum Glück für uns haben die Kultisten des Schattenhammers beschlossen, in seine Höhle einzumarschieren. Ihr Ziel ist es, seine Elementare ihrem Willen zu unterwerfen.\n\nAus diesem Durcheinander werden wir einen Vorteil schlagen. Das Erdritual, das ich beschwöre, wird Euch eins mit der Erde werden lassen. Es wird Euch in die Nähe von Lavinius versetzen, ohne dass er Eure Gegenwart bemerkt.\n\nDann ist es an Euch, ihn zu beseitigen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27935] = {title = "Die Lawine ins Rollen bringen", objective = "Tötet Lavinius.", description = "Lavinius steht vor Euch. Tötet ihn, um Therazanes Streitkräfte von einem Angriff auf Steinruh abzuhalten.", progress = nil, completion = "Ihr habt etwas getan, zu dem nur wenige fähig gewesen wären. Lavinius besiegt zu haben ist eine große Leistung.\n\nIch bin beeindruckt, &lt;Name&gt;. Werdet Ihr uns bei unserem Krieg gegen die Steintroggs helfen, damit wir den Steinvater retten können?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27936] = {title = "Die Lawine ins Rollen bringen", objective = "Tötet Lavinius.", description = "Ihr müsst zurückgehen und Lavinius töten, um Therazanes Streitkräfte von einem Angriff auf Steinruh abzuhalten!", progress = nil, completion = "Ihr habt etwas getan, zu dem nur wenige fähig gewesen wären. Lavinius besiegt zu haben ist eine große Leistung.\n\nIch bin beeindruckt, &lt;Name&gt;. Werdet Ihr uns bei unserem Krieg gegen die Steintroggs helfen, damit wir den Steinvater retten können?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27937] = {title = "Der Held kehrt zurück", objective = "Stellt Euch bei Steinvater Erzmantel in Steinruh in Tiefenheim vor.", description = "Der Steinvater wartet auf Euch in Steinruh im Süden.\n\nPutzt Euch ein wenig heraus. Ihr habt Euch den Empfang eines Helden verdient!", progress = nil, completion = "Unser Held kehrt zurück!\n\nIhr habt mein Volk gerettet, &lt;Name&gt;. Ihr habt Euch das, was Ihr sucht, redlich verdient.", rewards = "Ihr bekommt:\n\nAxt der irdischen Trennung"}
MultiLanguageQuestData['de'][27938] = {title = "Das mittlere Fragment", objective = "Bringt das mittlere Fragment der Weltensäule in Euren Besitz.", description = "Ich überreiche Euch hiermit den Schlüssel von Steinruh. Mit ihm dürft Ihr die Schatzkammer in meiner Heimstatt aufschließen und das mittlere Fragment der Weltensäule herausnehmen.\n\nAchtet gut auf das Fragment, <Name>. Stellt sicher, dass Ihr es so schnell wie möglich zum Tempel der Erde in Tiefenheim zurückbringt!\n\nIhr sollt wissen, dass Ihr hier immer willkommen sein werdet.", progress = "Ihr seid zurückgekehrt. Habt Ihr das mittlere Fragment geborgen?", completion = "Das mittlere Fragment der Weltensäule!\n\nIch danke Euch, &lt;Name&gt;. Ich kann mir nur schwer vorstellen, was Ihr durchmachen musstet, um das hier zu uns zurückzubringen. Ich werde dafür sorgen, dass es in der Mitte der Kammer aufgestellt wird.", rewards = "Schulterpolster der RekonstruktionGamaschen der zersprungenen HoffnungSäulenbindertaillenschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27939] = {title = "Der Wüstenfuchs", objective = "Schnottz will, dass Ihr ihm den Wüstenfuchs bringt.", description = "In dieser Region muss einiges getan werden, <Volk>.\n\nWir haben beide eine brennende Leidenschaft für uralte Technologien, nicht wahr? Vielleicht können wir ja irgendwie zusammenarbeiten?\n\nLassen wir die Missverständnisse der Vergangenheit einfach ruhen, hmm?\n\nNun, da ist ein sehr scheues Tier Richtung Osten, das ich zu jagen versucht habe. Bringt mir diese Kreatur als Zeichen Eurer Aufrichtigkeit, hmm?\n\nDann weihe ich Euch vielleicht in meine Operation ein...", progress = "Habt Ihr den Wüstenfuchs gefangen, <Klasse>?", completion = "Ihr habt es geschafft!\n\nVielleicht kann ich Euch mit wichtigeren Aufgaben betrauen, hmm?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27940] = {title = "Schmutzige Vögel", objective = "Ihr sollt 8 kranke Geier töten.", description = "Der Himmel über der Verdorrten Oase ist voll mit diesen hässlichen Geiern.\n\nSie sind wie mit Krankheiten befallene Ratten mit Flügeln. Sie dienen keinem bedeutsamen Zweck und bringen unsägliches Leid.\n\nSäubert den Himmel von dieser Plage und hinterlasst die Region besser, als Ihr sie vorgefunden habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27941] = {title = "Modeismus", objective = "Bellok Leuchtklinge möchte, dass Ihr 10 Gardistenuniformen aufsammelt.", description = "Wir haben einen unerschütterlichen Grundsatz in unseren Rängen, den wir sehr ernst nehmen.\n\nUnsere Truppen müssen zu jeder Zeit in offizielle Uniformen gekleidet sein. Das hilft bei der Organisation - Beschuss durch die eigenen Streitkräfte kommt nicht so oft vor und die Truppen sehen immer großartig aus!\n\nWir nennen das Modeismus.\n\nIn letzter Zeit gehen uns aber die Uniformen aus. Ich muss Euch darum bitten, sie von den Soldaten, die während ihrer Pflichterfüllung gefallen sind, zu bergen.\n\nIhr solltet reichlich arme Kerle östlich von hier bei den Ruinen von Ammon finden.", progress = "Konntet Ihr die Uniformen, die wir benötigen, beschaffen?", completion = "Das ist sehr gute Arbeit, &lt;Klasse&gt;.\n\nIhr solltet schnell bei uns im Rang aufsteigen.", rewards = "Kugelzerschlagene BrustplatteTaillenschutz der gefallenen HerzenTadellose UniformstulpenDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27942] = {title = "Götzendienst", objective = "Kommandant Schnottz möchte, dass Ihr 8 gut erhaltene Götzen einsammelt.", description = "Ich habe etwas, um das Ihr Euch kümmern müsst, <Volk>.\n\nMein engster Vertrauter ist von einem uralten Fluch befallen. Es handelt sich um einen Fluch, der ihn ausgerechnet in einen Truthahn verwandelt hat!\n\nIch habe tagelang nach einem Heilmittel gesucht und bin nun endlich soweit, das Ritual durchzuführen.\n\nIch werde einige Götzen aus den nahegelegenen Ruinen benötigen. Ihr werdet sie mir umgehend beschaffen!\n\nWeggetreten!", progress = "Habt Ihr die Götzen für mich, <Volk>?", completion = "Diese Stücke scheinen mir von ausreichender Qualität zu sein.\n\nDamit kommen wir dem Reinigungsritual einen Schritt näher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27943] = {title = "Verärgerte Geister", objective = "Kommandant Schnottz möchte, dass Ihr die L.P.B.K. benutzt und 5 wütende spektrale Essenzen einsammelt.", description = "Doktor Wenkmann war einer meiner besten Forscher, bis ich von seinem Elend erlöst werden musste.\n\nEr hat mir aber eine seiner größten Errungenschaften hinterlassen. Gegen einen richtig abgestimmten, übernatürlichen Gegner wird diese Waffe die Essenz des Zieles abzapfen.\n\nDas ist von entscheidender Bedeutung bei dem Ritual, das ich durchführen werde.\n\nWo Ihr ins Spiel kommt, fragt Ihr? Ganz einfach. Ihr habt das Privileg, das Material zu sammeln.\n\nDie Waffe ist darauf kalibriert, bei den wütenden Schreckgespenstern im Tempel im Osten zu funktionieren.", progress = "Also, junger Mann? Wart Ihr erfolgreich?", completion = "Sehr gut!\n\nIhr habt Euch die Teilnahme an dem Ritual redlich verdient.\n\nIhr werdet einer der Ersten sein, die Gubbel wieder in seiner... ursprünglichen Form willkommen heißen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27944] = {title = "Ausdünnen der Brut", objective = "Tötet 12 Dunkelwaldlauerer im Finsterwald. Der Finsterwald liegt direkt westlich von hier, jenseits der Brücke auf der mittleren Insel.", description = "Seit Wochen versuchen wir schon, im Finsterwald Fuß zu fassen, aber dort wimmelt es nur so von Spinnen. Tut mir einen Gefallen und schaut, ob Ihr ihre Zahl soweit eindämmen könnt, dass wir einen Angriff starten können.\n\nDoch seid vorsichtig da draußen. Mir wurde berichtet, dass Anfang der Woche Hordetruppen dort gesichtet wurden.", progress = nil, completion = "Den Spinnen habt Ihr es gezeigt, &lt;Name&gt;. Wenn wir so weitermachen, ist der Wald im Handumdrehen unser.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27945] = {title = "Schwarzmalerei", objective = "Besorgt ein schwarzes Diamantherz.", description = "Die Erde blutet, <Klasse>. Sie reißen sie auf, wie man Fleisch aufreißen würde.\n\nDiese Kultisten finden großen Gefallen an ihrer Geheimniskrämerei, aber eben die Elementare, die sie für ihre Untaten benutzen, könnten sie verraten. Sucht die Obsidiansteinsklaven im Nordosten von hier in der zerstörten Erde, die wir den Schwarzen Riss nennen.\n\nZerschmettert ihre Körper und sucht für mich ein perfektes Herz aus schwarzem Diamant. Ich werde in sein Herz blicken. Und ich werde seine Seele entblößen.", progress = "Das Herz. Ein Steinherz in tiefstem Schwarz. Habt Ihr eins gefunden?", completion = "&lt;Mallia nimmt ihre Augenklappe ab und hält den Diamanten vor ihre leere Augenhöhle.&gt;\n\nWas haben wir, was haben wir - Bresche, Bresche Nummer Drei. Zwei Köpfe, einer ganz seinem Meister gegeben. Ich sehe die Zukunft. Ein vereinigter Hammer. Ein zerschmetterter Berg. Oh - OH!\n\n&lt;Mallia lässt den Diamanten zu Boden fallen und bedeckt ihr Gesicht mit den Händen.&gt;", rewards = "Beinplatten der zerrissenen ZukunftHerzsteintreterDiamantenklammernde HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27946] = {title = "NYI", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][27947] = {title = "Eine Vision des Zwielichts", objective = "Spürt ein Auge des Zwielichts in dem Schwarzen Riss auf.", description = "Cho'gall behält seine Handlanger durch mächtige magische Kugeln im Blick: \"Die Augen des Zwielichts\"\n\nIn Hyjal haben die Wächter von Hyjal es geschafft, eine zu finden und für ihre Zwecke zu verändern. Das müssen wir auch tun. Ich will eine dieser Kugeln und ich will sie benutzen, um hineinzuschauen und mitten in Cho'galls Versteck zu blicken.\n\nDurchsucht den Schwarzen Riss jenseits des Flusses im Nordosten und findet ein Auge des Zwielichts. Tut alles Notwendige, um es zu mir zurückzubringen!", progress = nil, completion = "&lt;Das Auge liegt vor Euch und summt unheilvoll vor dunkler Energie.&gt;\n\n&lt;Ohne Warnung dreht sich die Kugel, als sehe sie Euch an. Ihr spürt die Anwesenheit des Bösen, als sei die Kugel lebendig.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27948] = {title = "Eine klebrige Angelegenheit", objective = "Sammelt 4 klebrige Seidendrüsen von Finsterwaldbrutmutterspinnen im Finsterwald. Der Finsterwald liegt westlich von hier, über die Brücke hinweg, auf der zentralen Insel.", description = "Auf dieser Insel Vorräte zu sammeln, hat sich, gelinde gesagt, als schwierig erwiesen.\n\nGlücklicherweise haben wir ein gutes Angebot an Seide im Finsterwald, direkt westlich von hier, ausmachen können. Der unschöne Teil an der Sache ist, dass die Seide aus den Drüsen von Brutmutterspinnen gewonnen werden muss. Ich möchte, dass Ihr mir vier davon besorgt.\n\nDas sollte genügen, um die letzte Ladung Hemden fertigzustellen.", progress = "Konntet Ihr die klebrigen Seidendrüsen bekommen?", completion = "Diese Drüsen sind genau richtig. Wir sind für Eure Hilfe dankbar, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27949] = {title = "Die Vergessenen", objective = "Schenkt den Geistern von 6 gequälten Seelen die Freiheit am Vergessenen Hügel. Die Seelen können kanalisiert werden, indem Ihr mit den Händen die Grabsteine berührt. Der Vergessene Hügel liegt direkt westlich von hier, vorbei am Finsterwald und der Rastlosen Front.", description = "Viele Soldaten sind auf dieser Insel gestorben, <Name>. Es ist nur rechtens, dass wir ihnen auf jede mögliche Art und Weise unseren Respekt erweisen.\n\nIch möchte, dass Ihr zum Vergessenen Hügel reist, der westlich von hier liegt, und die Seelen unserer geknechteten Waffenbrüder von hier fort geleitet. Seid bitte vorsichtig da draußen, uns haben Berichte über Machenschaften der Untoten in dem Bereich erreicht.", progress = nil, completion = "Mögen ihre Seelen in Frieden ruhen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27950] = {title = "Gubbel!", objective = "Schnottz möchte, dass Ihr ihn ansprecht, wenn Ihr bereit seid, dem Ritual beizuwohnen.", description = "Endlich! Die Zeit ist gekommen, meinen Gubbel von diesem furchtbaren Fluch zu befreien!\n\nPasst gut auf, <Volk>, und seid auf der Hut. Es darf keine Unterbrechungen während des Rituals geben.\n\nSagt mir Bescheid, wenn die Umgebung sicher ist!\n\nBewegung!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27951] = {title = "Wir müssen alle Opfer bringen", objective = "Tötet 10 Schamanen der Schwärze.", description = "<Das Auge spricht mit Euch; seine 'Stimme' scheint aus allen Richtungen zugleich zu erschallen.>\n\nIhr wünscht einen Blick durch mich zu werfen, <Volk>? Meine Macht ist nur für einen bestimmten Preis zu haben. Diese Jünger des Zwielichts haben mich mit dem Blut der Wildhammerzwerge beehrt, aber ich verspüre immer noch Durst. Vielleicht könntet Ihr es besser machen.\n\nTötet meine alten Herren und meine Visionen gehören Euch. Ehrt mich, indem Ihr Schamanen der Schwärze tötet. Schließlich ist ein Blut so gut wie das andere.", progress = nil, completion = "&lt;Das Auge schimmert dunkel, Farben wirbeln über seine düstere Oberfläche.&gt;\n\nAh, die wohlschmeckende Spannung ausgelöschten Lebens. Könnt Ihr das fühlen, &lt;Klasse&gt;? Gefällt es Euch so gut wie mir?\n\nNein, wie ich sehe, nicht. Ihr kämpft, um das Leben anderer zu beschützen. Schade.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27952] = {title = "Die Forscher", objective = "Sprecht mit Entdeckerin Mowi im Tempel der Erde in Tiefenheim.", description = "Eine Gruppe der Forscherliga befindet sich in der Kammer im Nordwesten im Tempel.\n\nNun machen sie immer lauteres Geschrei über etwas, das der Schattenhammer anstellt.\n\n<Name>, würdet Ihr ein Schatz sein und nachsehen, was sie brauchen?", progress = nil, completion = "Donnerwetter! Es ist endlich jemand hier, um uns zu helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27953] = {title = "Die Archäologische Akademie", objective = "Sprecht mit Prüfer Rowe im Tempel der Erde in Tiefenheim.", description = "Eine Gruppe der Archäologischen Akademie befindet sich in der Kammer im Nordwesten im Tempel.\n\nNun machen sie immer lauteres Geschrei über etwas, das der Schattenhammer anstellt.\n\n<Name>, würdet Ihr ein Schatz sein und nachsehen, was sie brauchen?", progress = nil, completion = "Ah, es wurde auch langsam Zeit, dass jemand herkommt, um mit uns über Angelegenheiten größter Dringlichkeit zu sprechen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27954] = {title = "Im Auge des Betrachters", objective = "Bringt das Auge des Zwielichts zu Garona der Halborcin in der Blutschlucht im Schattenhochland.", description = "Also gut, <Volk>. Ihr habt Euch meine Dienste mit Blut erkauft. Bringt mich zu Garona der Halborcin zurück.\n\nOh ja, ich weiß bereits, wo Ihr mich hinbringt. Garonas unablässige Suche nach Rache ist kein Geheimnis. Es wird ein Genuss sein, dabei zuzusehen, wie sie sich entfaltet.", progress = "Hattet Ihr Glück im Schwarzen Riss?", completion = "Ihr habt eins gefunden? Ich habe überall gesucht. Gebt es her!\n\nEinige dieser Augen kann man mit Rätseln oder Versen für sich gewinnen. Bei anderen benötigt man Magie. Was hat dieses hier verlangt? Ah, das spielt keine Rolle. Es zählt nur, dass es uns gehört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27955] = {title = "Ich sehe was, was Ihr nicht seht...", objective = "Blickt für Garona in das Auge des Zwielichts.", description = "Dieses furchtbare Ding lässt mir die Haare zu Berge stehen. Cho'gall benutzt diese Dinger, um seine Gehilfen zu überwachen - jetzt ist es an der Zeit, dieses gegen ihn zu verwenden.\n\nSchauen wir mal... hmm, es ist ganz milchig. Ich sehe nur Euch. Warum zeigt es mir Euch?\n\n<Garona stellt das Auge vor sich hin.>\n\nSchaut in das Auge und sagt mir, was Ihr seht. Werft einen Blick in Cho'galls Versteck! Was macht er? Ist er schwer bewacht? Sagt es mir!", progress = nil, completion = "Ihr seid ganz blass geworden, &lt;Klasse&gt;. Was hat das Auge Euch gezeigt?\n\nIhr habt Cho'gall gesehen? Moment - Cho'gall hat Euch gesehen? Er beobachtet uns? Er beobachtet uns jetzt gerade!?\n\nVerflucht sei diese blöde, dunkle Magie! Ich werde mich selbst in Cho'galls Festung einschmuggeln müssen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAuge der UmkehrungSplitterherzring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27956] = {title = "Lunks Aufgabe", objective = "Beschafft 15 gehärtete Schwungräder von ausgehärteten Kriegsgolems.", description = "Lunk kam aus dem Ödland. Andere Oger Lunk gezwungen zu kämpfen.\n\nLunk hasst kämpfen. Lunk will lernen.\n\nLunk sieht Maschinen im Süden. Maschinen sind aus Zahnrädern.\n\nVielleicht, wenn Ihr nett fragt, Maschinen geben Euch ein paar Zahnräder? Dann kann Lunk vielleicht ein Zahnrad haben und über Maschinen lernen.", progress = "Habt Ihr die Zahnräder? Wie habt Ihr sie bekommen?", completion = "Ihr habt... ...nicht die Maschinen GETÖTET, stimmt's?\n\n&lt;Lunk sieht verstört aus.&gt;\n\nStimmt's?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27957] = {title = "Lunk nicht töten", objective = "Nein! Ihr seid wie Zwerg von Thoriumbruderschaft.\n\n\"Zwerg töten. Spinne töten. Maschine töten. Töten, töten, töten.\"\n\nLunk ist in Schlucht gekommen für Abenteuer, nicht für Mörderserie.\n\nLebt wohl, <Volk>. Ihr tötet zu viel.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Lunk\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27958] = {title = "Ein anständiges Gegengift", objective = "Beschafft Euch 14 Proben Glasnetzgift.", description = "Eigentlich schade, dass Lunk weg ist. Ich hatte gerade angefangen, Vergnügen an seiner Gesellschaft zu finden.\n\nAber na ja, zurück an die Arbeit!\n\nIch bin das Beste, was diese Expedition in Sachen Medizinversorgung hat, und meine Gegengiftvorräte gehen langsam zur Neige.\n\nDer Schlüssel zu vernünftigem Gegengift ist es, IMMER mit dem Gift selbst zu beginnen. Die Glasnetzspinnen in der Umgebung sollten einen guten Ausgangspunkt bieten. Wenn Ihr sie tötet, könnt Ihr wahrscheinlich etwas Gift aus den Säcken in ihren Kiefern gewinnen.", progress = "Sieh mal einer an, ihr arbeitet wirklich schnell! Ihr habt doch das Gift, oder?", completion = "Das... das ist weit mehr, als ich erwartet hatte. Das wird uns monatelang reichen.", rewards = "GlasnetzrobenSchlangenölhelmBeinschützer des StabsarztesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27959] = {title = "Lunks Abenteuer: Spinnenreiter", objective = "Schwächt 7 Glasnetzspinnen, damit Lunk sie reiten kann.", description = "Lunk merkt, Ihr tötet gerne. Lasst Lunk Euch etwas anderes zeigen.\n\nLunk wollte schon immer auf Spinnenrücken reiten. Sieht spaßig aus. Spinnen bewegen sich aber zu schnell. Hauen immer ab.\n\nWir arbeiten zusammen. Ihr kämpft gegen Spinne, bis Spinne schwach und müde ist. Dann springt Lunk auf Spinnenrücken und reitet.\n\nVielleicht sammelt Lunk etwas Gift für Euch! Nicht müssen töten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27960] = {title = "Je weniger, desto besser", objective = "Tötet 10 Geologen der Dunkeleisenzwerge oder Wachmänner der Dunkeleisenzwerge.", description = "Ich bin kein besonderer Kämpfer... Ich bin eher der Bergbauzwerg. Das gleiche gilt für Jack und Pris. Was Lunk betrifft... na ja, man könnte glauben, er wäre ein großer Kämpfer, aber eigentlich ist er der größte Feigling von uns allen.\n\nWas ich damit sagen will: Es ist gut, dass Ihr hierhergekommen seid.\n\nEs scheint wahrscheinlich, dass wir von der Thoriumbruderschaft schon bald gegen die anderen Dunkeleisenzwerge kämpfen müssen. Ich denke, dass wir zunächst einige ihrer besten ausschalten sollten, bevor der Krieg so richtig losgeht. Fangt mit den Geologen und den Wächtern im Süden an.", progress = nil, completion = "Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27961] = {title = "Fehl am Platz", objective = "Beschafft Euch 8 Aschehühnchen.", description = "Die Schlucht ist ein unerbittlicher Ort. Hier laufen nicht besonders viele flauschige Wildtiere herum.\n\nWir haben versucht, etwas Jagdwild anzusiedeln, aber sie haben sich nicht besonders gut gehalten. Es gibt einfach nichts für sie zu fressen. Die Spinnen in der Nähe allerdings - die an sich schon gefährlich genug sind - schlagen sich den Bauch mit Hühnchenfleisch voll.\n\nWir werden die Spinnen niemals los, aber wir können die paar Hühner, die es noch gibt, retten. Damit werdet Ihr nicht nur die Bruderschaft versorgen, sondern ihnen auch einen qualvollen Tod durch den Biss einer Spinne ersparen.", progress = "Diese armen Tiere.", completion = "Ihr müsst wirklich sehr geschickt sein, wenn Ihr so viele in so kurzer Zeit sammeln konntet.\n\nAusgezeichnete Arbeit, &lt;Name&gt;. Ich werde dafür sorgen, dass sie nicht zu Schaden kommen.", rewards = "AschefederumhangFlauschige KopfbedeckungHelm des GnadentodsKohlenstaubs ArmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27962] = {title = "Vor der Schlucht", objective = "Erbeutet Margols gigantisches Horn.", description = "Margol die Wütende ist eine alte Donnerechse, die hier in der Gegend ab und zu auftaucht. Der Legende nach lebte sie schon in dieser Schlucht, bevor es diese Schlucht gab. Einer anderen Legende nach hat sie meinen Bruder Barnabas gefressen.\n\nEs interessiert mich nicht, wie alt sie ist oder welche Magie sie aus ihrer Nase verschießt. Ich will ihren Tod. Um Barnabas' Willen.\n\nIhr findet sie in den Klippen südlich von hier.", progress = "Bringt mir das Horn, <Name>.", completion = "Ja, das war wirklich Margols Horn. Kann man nich' dran rütteln.\n\nBarnabas war wie ich ein Gräber. Im Kampf gegen diese Bestie war er chancenlos. Ich bin froh, dass Ihr für Gerechtigkeit gesorgt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27963] = {title = "Ein neuer Meister... nur wer?", objective = "Beschafft Euch die Dunkeleisennotiz von Gravius Rußschlack bei Rußschlacks Arbeitsstätte.", description = "Ihr seid gerade zur rechten Zeit gekommen.\n\nDarum geht's: Die Dunkeleisenzwerge in der Schlucht verhalten sich merkwürdig und die Thoriumbruderschaft hat vor, herauszufinden, warum. Aufseher Schlickfaust hat nicht viel für Überraschungen übrig.\n\nWir vermuten, dass sie den Befehlen von irgendeinem neuen Anführer folgen. Ich habe Grund zu der Annahme, dass Gravius Rußschlack, direkt südlich von hier, weiß, um wen es sich dabei handelt.\n\nSelbst hier in der Sengenden Schlucht, hat sich die Kunde Eurer Heldentaten herumgesprochen, <Name>. Rußschlack sollte Euch keine Probleme bereiten.", progress = "Gibt es Neuigkeiten?", completion = "Mal sehen... Aufseher Maltorius... ihn und seine Arbeit kennen wir schon.\n\nWas ist das denn? Der \"Erzherzog\"? Das klingt ja vielversprechend.", rewards = "SteinkopfhelmAuf Euch wartet eine dieser Belohnungen:\n\nÖlfaustkugelJacks Glücksbringer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27964] = {title = "Ausgrabungsboss Krawallschnäuzer", objective = "Tötet Ausgräber und Fußsoldaten der Dunkeleisenzwerge im Kessel, bis Ausgrabungsboss Krawallschnäuzer erscheint. Dann tötet den Ausgrabungsboss Krawallschnäuzer und bringt seine Dunkelglut an Euch.", description = "Rußschlack war in der Hierarchie nicht so weit oben, wie ich dachte. Wir müssen seinen Vorgesetzten aus dem Weg schaffen und herausfinden, was er weiß.\n\nSein Name ist Ausgrabungsboss Krawallschnäuzer und er leitet die Ausgrabungen der Dunkeleisenzwerge im Kessel etwas nordwestlich von hier. Seine Ausgräber und Fußsoldaten patrouillieren auf der östlichen Seite des Kessels und graben sich Tag und Nacht weiter nach unten.\n\nEr zeigt sich nicht sehr oft in der Öffentlichkeit, aber wenn Ihr genug seiner Männer tötet, wird er gezwungen sein, herauszukommen und sich mit Euch zu befassen.", progress = "Wenn Krawallschnäuzer das Gewünschte nicht bei sich trägt, bin ich nicht sicher, was wir als nächstes tun werden.", completion = "Eine... eine Glut? Was ist das für ein Ding?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Image of Archduke Calcinder\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27965] = {title = "Thoriumspitze: Der Sitz der Bruderschaft", objective = "Meldet Euch bei Aufseher Schlickfaust auf der Thoriumspitze in der Sengenden Schlucht.", description = "Habt... habt Ihr das gesehen? Das ist das Puzzlestück, das uns gefehlt hat! Wir müssen diese Informationen zu jemandem an der Thoriumspitze bringen.\n\nEs ist bekannt, dass die Dunkeleisenzwerge in der Vergangenheit gemeinsame Sache mit dem Feuerfürsten gemacht haben, aber noch nie zuvor haben sie sich so weit in die Sengende Schucht hinaus gewagt.\n\nDie Thoriumspitze liegt westlich und nördlich von hier. Ihr findet sie versteckt in den Klippen, die die Pyroxebenen überragen. Bringt diese Informationen schnurstracks zu Aufseher Schlickfaust.", progress = nil, completion = "Kenne ich Euch, &lt;Volk&gt;?\n\n\n\nDas klingt nach einem weiteren Diener von Ragnaros. So etwas höre ich überhaupt nicht gern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27966] = {title = "Bergt die Überreste", objective = "Ihr müsst 9 verfluchte Oberschenkelknochen von den Ghulen, die auf dem Vergessenen Hügel hausen, einsammeln. Der Vergessene Hügel befindet sich auf der westlichen Seite der Insel, direkt vorbei an der Vergessenen Front.", description = "Der Vergessene Hügel ist von Zombies und Ghulen überrannt worden, seit dem Tag, an dem wir diese erbärmliche Insel für uns beanspruchten. Wir haben versucht, sie loszuwerden, aber es scheint, als kämen sie immer wieder.\n\nEiner unserer Leutnants hat vorgeschlagen, die Ghulknochen wegzuräumen, nachdem wir sie getötet haben, in der Hoffnung, dass sie nicht über Nacht wiederauferstehen. Glaubt Ihr, dass Ihr uns hierbei helfen könntet?", progress = "Konntet Ihr die Oberschenkelknochen sammeln? Mir ist lieber, Ihr versucht es, als dass ich es tun müsste.", completion = "Ich hätte nicht gedacht, dass Ihr es schaffen könnt, &lt;Name&gt;. Ihr steckt ja voller Überraschungen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27967] = {title = "Oberleutnant Connor", objective = "Findet und tötet Oberleutnant Connor auf dem Vergessenen Hügel. Ihr findet den Vergessenen Hügel auf der westlichen Seite der Insel.", description = "Als ich das erste Mal von Oberleutnant Connor hörte, war ich ein junger Rekrut im Verlies von Sturmwind. Niemand von uns hätte je gedacht, dass er mal hier auf Tol Barad enden würde. Traurigerweise wandert er noch immer über diese elenden Inseln und richtet verheerenden Schaden an der Moral unserer Truppen an.\n\nIch möchte, dass Ihr seinem Elend ein Ende macht... und damit unserem.", progress = nil, completion = "He, Ihr habt es lebendig hierher zurück geschafft! Ich kann nicht behaupten, dass Ihr der Erste wart, der dieses Unterfangen versucht hat, aber Ihr seid gewiss der Erste, der in einem Stück zurückkehrt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27968] = {title = "Die Wut des Rudels", objective = "Tötet Lord Godfrey.", description = "Ah, der süße Geruch von Sieg! Meine Männer sollten Godfrey in eben diesem Augenblick in Stücke reißen. Begebt Euch zu ihm und holt Euch Euren Teil der Beute - Ihr habt es Euch verdient!\n\nMan hätte gedacht, dass es schwieriger würde, ihn zu vernichten...", progress = nil, completion = "Wir haben es geschafft, &lt;Name&gt;! Es hat uns viel gekostet, aber der Sieg ist unser.\n\nDiese Burg könnte mir und meinem Rudel als Heimstatt dienen, auch wenn wir normalerweise einen etwas natürlicheren Lebensraum bevorzugen.\n\nVielleicht ist es das Beste, sie zur Erinnerung an Godfreys Verrat und die Blutfangkrieger, die hier gefallen sind, zu belassen.", rewards = "Godfreys KniehosenSandalen der AufopferungSchattenfangschiftungBrustplatte des schrecklichen PreisesSchulterstücke des RudelführersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27969] = {title = "Macht Euch nützlich", objective = "Kommandant Schnottz möchte, dass Ihr 6 faulenzende Arbeiter davon überzeugt, wieder an die Arbeit zu gehen.", description = "Wir werden Gubbel sehr vermissen, aber die Mission darf nicht darunter leiden.\n\nVielleicht gibt es da etwas, das Ihr tun könnt, um Euch zu rehabilitieren.\n\nNehmt eine der Uniformen, die Ihr gefunden habt. Wenn Ihr sie tragt, werden meine Arbeiter nicht so... aggressiv reagieren.\n\nIn letzter Zeit war ihre Moral nicht gerade hoch. Einige der Arbeiter weigern sich gar, ihren Pflichten nachzukommen.\n\nOh, diese Dreistigkeit!\n\nFindet diese faulen Schwachköpfe und überzeugt sie davon, an die Arbeit zu gehen... oder sonst!", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;.\n\nVielleicht besteht ja noch Hoffnung für Euch.", rewards = "Taillenschutz aus MungobalgBrustschutz der gründlichen MotivationSchultern des ObeliskenDer folgende Zauber wird auf euch gewirkt:\n\nCancel Uniform\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27970] = {title = "Kapitän P. Harris", objective = "Ihr habt den Auftrag, Kapitän P. Harris am Kap der Verlorenen Hoffnung zu töten. Das Kap der Verlorenen Hoffnung liegt gleich nordwestlich von hier, die Küste entlang. Haltet einfach Ausschau nach den Schiffswracks.", description = "Das Kap der Verlorenen Hoffnung steckt uns hier auf Tol Barad seit Wochen wie ein Stachel im Fleisch. Die Hälfte unserer Versorgungsschiffe endet auf den Felsen dort unten.\n\nHinzu kommt, dass es von einer Bande untoter Matrosen überrannt wurde. Wir haben versucht, sie zu dezimieren, aber sie kommen immer wieder zurück. Unsere letzte Hoffnung ist es, den Kapitän zu töten, der ihnen ihre Befehle gibt. Ihr solltet ihn auf einem Schiff nahe des Ufers finden.\n\nOh, und ich hoffe, Ihr habt keine große Angst vor Haien.", progress = nil, completion = "Ihr habt es geschafft! Vielleicht schaffen es jetzt endlich ein paar Schiffe in den Hafen! Danke sehr, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27971] = {title = "Stört ihre vorletzte Ruhe", objective = "Lagerkommandant Brack hat Euch gebeten, am Kap der Verlorenen Hoffnung 8 schiffbrüchige Seemänner zu töten. Das Kap befindet sich nordwestlich von hier, am Strand.", description = "Seit einiger Zeit haben wir Probleme mit den Untoten unten am Kap der Verlorenen Hoffnung. Bei jedem neuen Schiffbruch schließen sich ihnen neue Untote an.\n\nKönnt Ihr uns einen Gefallen tun und die Mannschaft dort etwas ausdünnen? Ich weiß, Ihr könnt sie nicht alle töten, aber jeder Beitrag ist für uns von Nutzen.\n\nHaltet ein Auge auf die Horde, in letzter Zeit wird gemeldet, dass ihre Kämpfer am Strand im Hinterhalt liegen.", progress = nil, completion = "Gute Arbeit mit den Untoten da oben, &lt;Name&gt;. Wir wissen Eure Hilfe wirklich sehr zu schätzen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27972] = {title = "Stärkung der Moral", objective = "Ihr habt den Auftrag erhalten, 6 Fässer mit Südmeerrum aus den Schiffswracks am Kap der Verlorenen Hoffnung zu beschaffen. Das Kap liegt nördlich von hier, entlang der Küste.", description = "Die Stimmung ist in letzter Zeit schlecht, <Name>. Wir tun, was wir können, um die Truppen bei Laune zu halten, aber leider geht uns der wichtigste Stimmungsaufheller aus... Rum.\n\nUnsere Infanterie im Osten berichtet, dass in den Rümpfen der Schiffswracks am Kap der Verlorenen Hoffnung jede Menge Südmeerrum liegt. Würdet Ihr dort hinreisen und dem nachgehen?\n\nBringt so viel Rum mit, wie Ihr finden könnt.", progress = "Konntet Ihr den Rum bergen? Ich würde es ja versuchen, aber ich habe Angst vor Wasser. Und vor diesem verrückten Hai.", completion = "Der Rum wird uns sehr helfen, &lt;Name&gt;. Sie werden sich morgen früh zwar nicht gut fühlen, aber wenigstens schlafen sie glücklich ein.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27973] = {title = "Achtung, Splitter", objective = "Bringt 15 Stücke Schiffsbauholz von Wellsons Werft zu Unteroffizier Grau. Das Holz wird von den Geistern in der Werft bewacht oder liegt frei zugänglich in der Werft verteilt. Die Werft ist an der Küste nordwestlich von hier.", description = "Wart Ihr schon in Wellsons Werft, <Name>? Am besten haltet Ihr Euch davon fern, es sei denn, Ihr habt einen guten Grund, dort hinzugehen. Und unglücklicherweise werde ich Euch einen guten Grund geben.\n\nWisst Ihr, wir haben hier nur wenige Vorräte, seit wir die Insel wieder eingenommen haben. Auf der von Geistern heimgesuchten Werft ist viel Holz, aber alle, die ich bisher geschickt habe, um es zu holen, kamen nicht zurück.\n\nKönnt Ihr uns helfen?", progress = "Haben die Geister Euch Angst eingejagt?", completion = "Ich habe nicht damit gerechnet, dass Ihr diese Aufgabe erfüllen könnt, &lt;Name&gt;. Ihr steckt voller Überraschungen!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27974] = {title = "Dies ist unser Land", objective = "Tötet Baron Ashbury.", description = "Dachtet Ihr, dass eine Handvoll Worgengezücht mich aufhalten kann? Ha!\n\nZu Lebzeiten war Burg Schattenfang Teil des Königreichs Lordaeron, also ist es nur gerecht, dass es im Tode den Verlassenen gehört. Godfrey und seine Komplizen sind bestenfalls kleine Hindernisse und natürlich freuen wir uns, sie als Strafe für den Verrat an der Dunklen Fürstin beseitigen zu können.\n\nAshbury hat sich bei der Vorderseite der Burg niedergelassen und ist einem Angriff gegenüber völlig ungeschützt. Bereitet uns einen schönen Anfang, ja?", progress = nil, completion = "Ah, sehr gut! Sie haben sich mächtige Verbündete beschafft, aber offensichtlich ist das nichts, womit ein herausragender &lt;Klasse&gt; der Bansheekönigin nicht fertig würde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27975] = {title = "GESUCHT: Vorarbeiter Wellson", objective = "Tötet Vorarbeiter Wellson in Wellsons Werft. Die Werft befindet sich nordwestlich von hier an der Westküste.", description = "Vorarbeiter Wellson ist uns schon seit unserer Ankunft ein Dorn im Auge. In seiner Werft lagert er haufenweise Materialien, die für uns von extrem hohem Nutzen sein könnten... wenn wir nur an sie heran kämen.\n\nEr lässt sie von seinen Dienern streng bewachen und macht es uns schwer, auch nur einen Fuß in die Werft zu setzen. Ihr müsst Wellson ein für alle Mal für mich erledigen. Aber seid vorsichtig, <Name>. Uns wurde berichtet, dass die dreckige Horde überall in der Gegend ihr Unwesen treibt.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ich werde Eure Taten sofort unserem Oberkommando melden.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27976] = {title = "Verdammt seien diese fetten Finger", objective = "Tötet 12 schwere Kriegsgolems.", description = "Leider kann ich wegen dieses Fettfingerproblems meine Schläge nicht mehr so austeilen wie früher. Durch das Klima hier draußen und den fehlenden Luftdruck dehnen sich meine Finger aus. Die sehen aus wie riesige Thelsamarblutwürste, oder?\n\nIhr werdet meine Befehle und all so'n Zeug ausführen müssen.\n\nPunkt Eins auf der Liste: Die schweren Kriegsgolems in der Schlucht windelweich prügeln. Legt los.", progress = nil, completion = "Ihr seid ein wirklich guter Junge. Ich hab ein kleines Geschenk für Eure Mühen.", rewards = "Bleihands HandschuheHämmernde GamaschenFettfingerhandschuheAuf Euch wartet eine dieser Belohnungen:\n\nGretels Anhänger\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27977] = {title = "Aufklärungsausstattung", objective = "Findet die Schmiedewindform und das Ausguckhandfernrohr und bringt sie zurück.", description = "Früher hatten wir hier mal mehr Zeug. Ich glaube, es gab hier mal irgendwo ein Handfernrohr, zusammen mit einer Schmiedwindform.\n\nIch bin mir ziemlich sicher, dass sie von Dunkeleisenzwergen gestohlen wurden. Ja, ich weiß, dass ich ein Dunkeleisenzwerg bin! Ich spreche von den bösen Dunkeleisenzwergen, die in der Schlucht leben.\n\nAm besten versucht Ihr es mal bei den Dampfschmieden, die südlich von hier arbeiten. Bei ihnen ist es am Wahrscheinlichsten, dass sie solche Werkzeuge benutzen.", progress = "Wenn Ihr wegen Eurer Belohnung hier seid, dann müsst Ihr mir erst die gestohlenen Gegenstände aushändigen.", completion = "Fantastische Arbeit!", rewards = "Mantel des weißen SchafesUnverzichtbare PantalonsFingerreif des ZuchtmeistersDampfschmiedhelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27978] = {title = "Geisterjäger", objective = "Tötet 14 beliebige Geister bei Largos Warte, direkt nordöstlich des Basislagers.", description = "Seht Ihr den Hügel, direkt außerhalb unseres Basislagers? Das ist Largos Warte und es ist nicht der schönste Ort, um daneben ein Lager zu errichten. Wir mussten uns mit Geistern und Schreckgespenstern herumschlagen, seit wir unser Basislager hier aufgeschlagen haben.\n\nKönnt Ihr Euch dorthin begeben und sie wissen lassen, dass wir nicht vorhaben, uns sobald von hier wegzubewegen? Ein paar Abschüsse in ihren Reihen sollten sie zur Räson bringen.\n\nVielen Dank für Eure Hilfe hierbei, <Name>.", progress = nil, completion = "Hervorragend, &lt;Name&gt;! So bald sollten wir von den Geistern nichts mehr hören.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27979] = {title = "Dunkle Dienste", objective = "Beschafft Euch die Steinkügelchen von Kiyuubi, Letherio und Fiester. Setzt sie zu einem Zwielichttripetrizin zusammen.", description = "Ich habe noch eine Aufgabe für Euch. Diese kommt direkt vom Aufseher. Offenbar war er ziemlich aufgewühlt, als er von dem \"Erzherzog\" hörte, den Ihr entdeckt habt.\n\nEr hat uns gebeten, drei Zwielichtpriester, die drüben am Feuerwachtgrat im Westen arbeiten, aufzuspüren. Sie heißen Kiyuubi, Letherio und Fiester und jeder von ihnen trägt einen speziellen Stein bei sich. Setzt die drei zusammen und bringt sie herher.\n\nHört zu - wenn der Aufseher Befehle gibt, stellt man keine Fragen. Man tut es einfach.", progress = "Habt Ihr das Ding?", completion = "&lt;Hansel wiegt den Stein in seinen Händen.&gt;\n\nDieses Ding ist seltsam, &lt;Name&gt;. Ich weiß nicht, was ich davon halten soll. Eins ist sicher - es ist nicht natürlichen Ursprungs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27980] = {title = "Die Spinnen müssen weg", objective = "Erschlagt 9 Lavaspinnen in der Sengenden Schlucht.", description = "Mit Spinnen von normaler Größe kann ich umgehen.\n\nBei riesigen Glasnetzspinnen fühle ich mich unbehaglich, aber die sind weit genug weg, sodass ich mir nicht allzu viele Sorgen machen muss.\n\nAber Lavaspinnen? <Lolo erschauert.> Lavaspinnen sind GRUSELIG. Das sind gewaltige Spinnen. Die in LAVA leben.\n\nIch habe gerade meinen Lohn für die letzte Arbeitswoche bekommen und werde Euch gut bezahlen, wenn Ihr diese Dinger tötet. Ihr findet sie überall in der Sengenden Schlucht.", progress = nil, completion = "Ihr konntet sicher nicht alle Spinnen in der Schlucht töten, aber Ihr habt definitiv eine Lücke in ihre Reihen geschlagen.\n\nGut, hier ist, was ich Euch versprochen habe. Aber gebt nicht alles auf einmal aus. Außer Ihr tut es auf der Thoriumspitze.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27981] = {title = "Hitze, die nie vergeht", objective = "Besorgt 10 gefüllte Ofenflaschen. Ihr müsst die Ofenflaschen bei lebendigen Elementaren in der Sengenden Schlucht benutzen.", description = "Wir schmieden, wir schmelzen, wir rösten jegliches Spinnenfleisch, das wir finden können. Buschhühner, wenn wir Glück haben. Der Punkt ist, dass wir für all diese Arbeiten unglaublich viel Feuer benötigen.\n\nOh, wenn wir doch bloß in einer Aschewüste leben würden, in der einem an jeder Ecke der Bart versengt wird.\n\nNatürlich stammt das beste Feuer von den Elementaren. Man findet sie überall in der Sengenden Schlucht, hauptsächlich aber in der Nähe von Lava. Hier, nehmt diese Flaschen und benutzt sie bei den Elementaren.\n\nOh, habe ich schon erwähnt, dass die Elementare am Leben sein müssen, wenn Ihr die Proben einsammelt?", progress = "Schlickfaust sagt, wir sollen bald Feuerbomben für ihn bauen. Umso dringender benötigen wir diese Flaschen.", completion = "Auaaaaaaaaa! Ihr dürft dieses Zeug doch nicht einfach in die offene Hand eines Zwergs legen. Das Zeug ist doch glühend heiß!\n\nJetzt werden meine Hände noch mehr anschwellen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27982] = {title = "Zwielichthalsbänder", objective = "Beschafft 20 Zwielichthalsbänder", description = "Habt Ihr diese lächerlichen Ketten gesehen, die die Kultisten des Schattenhammers tragen? Die Edelsteine auf den Dingern sind größer als Hansels Faust!\n\nNur ein paar von diesen spiegeleigroßen Juwelen und Burninate da drüben könnte dieses Schmiedegeschäft auf die nächste Ebene bringen. Bringt ihm diese Halsbänder und es soll Euer Schaden nicht sein.", progress = "Ein rubinbesetzer Hammer... Klingt doch nett, oder?", completion = "Hmm... Aus der Ferne sahen diese Edelsteine irgendwie... funkelnder aus. Aus der Nähe sind sie doch ganz schön stumpf.\n\nAch, was soll's! Ein wenig Spucke und Politur sollte die Sache schon richten. Und falls nicht, kann ich sie immer noch nutzen, um meine Entzauberkünste zu verbessern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27983] = {title = "Lunks Abenteuer: Launische kleine Zwerge", objective = "Schwächt 7 Dampfschmiede der Dunkeleisenzwerge, sodass Lunk ihnen helfen kann, einzuschlafen.", description = "Was Ihr machen? Warum Ihr töten?\n\nIhr brauchen Sachen von Zwergen? Ah, Lunk verstehen. Lunk haben besseren Weg.\n\nHört zu: Ihr bekämpfen Zwerg, aber nicht töten! Nur bekämpfen, bis Zwerg müde sein. Dann Lunk wird helfen, wenn Zwerg einschlafen. Zwerge wahrscheinlich nur griesgrämig, weil sie nicht schlafen.\n\nKommt, vertraut Lunk.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27984] = {title = "Distelmonds Geschichte", objective = "Lauscht Zamaels Erzählung.", description = "Werdet Ihr mir helfen, <Sterblicher/Sterbliche>? Hört meine Geschichte.", progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Ich habe mich in mein Schicksal hier in diesem Käfig ergeben, aber das Gebet muss gefunden werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27985] = {title = "Gebet an Elune", objective = "Findet und lest das Gebet an Elune.", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Ich denke, dass sie sie in einer ihrer widerwärtigen Kisten aufbewahren, in der Nähe des Eingangs zu ihrer Höhle, am Boden des Grats.\n\nWenn es Euch gelingt, mein Gebet zurückzubekommen, so bringt es nicht zu mir zurück. Stattdessen nehmt Euch bitte die Zeit, es zu lesen.\n\nVergebung ist vielleicht zu viel verlangt, wenn man die Sünden bedenkt, die ich begang. Es wird mich aber nicht davon abhalten, weiterhin zu hoffen.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nZamaels Gebet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][27986] = {title = "In den Hallen des Bergfürsten", objective = "Sprecht mit Bergfürst Rendan auf dem Eisengipfel in der Sengenden Schlucht.", description = "Die Thoriumbruderschaft verfügt über keinerlei Miliz - nur ein paar Wachen und ich, und das war's. Wenn wir einen erfolgreichen Schlag gegen die Dunkeleisenzwerge in der Schlacht führen wollen, dann brauchen wir Hilfe.\n\nBergfürst Rendan befindet sich oben im Turm, über die Schlucht hinweg, von uns aus im Süden. Er verkehrt nicht mit dem Gesindel des Schattenhammers oder mit Feuerelementaren, aber er hat sich auch nicht der Bruderschaft angeschlossen. Vielleicht ist es an der Zeit, dass wir ihm einen Besuch abstatten. Mit seiner Hilfe könnten wir eine Chance haben.", progress = nil, completion = "Und wer seid Ihr wohl?\n\nAh, ein Abgesandter der Thoriumbruderschaft. Ihr benötigt meine Unterstützung? Nun gut, ich könnt' mich bereit erklären, Euch zu helfen...\n\n...wenn die Bezahlung stimmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27987] = {title = "Kanonenkugel!", objective = "Ihr müsst 4 Stapel Kanonenkugeln aus Largos Warte für Unteroffizier Grau besorgen. Ihr findet Largos Warte nordöstlich des Basislagers.", description = "Seit wir unser Lager hier errichtet haben, stehlen Largo und seine Handlanger unsere Vorräte. Das ist mehr als frustrierend.\n\nUns wurde berichtet, dass er oben auf seiner Warte Kanonenkugeln in den Türmen lagert, die über das Wasser hinausblicken. Würdet Ihr Euch dorthin aufmachen und versuchen, einige davon für uns zurückzuholen?\n\n<Name>, vergesst nicht, auch vor der Horde auf der Hut zu sein.", progress = "Habt Ihr die Kanonenkugeln gefunden?", completion = "Eine sehr gelungene Bergung, &lt;Name&gt;. Diese Kanonenkugeln sollten eine Weile reichen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27988] = {title = "Seuche... Überall Seuche!", objective = "Tötet Baron Silberlein und Kommandant Grüntal.", description = "Das Beste an dieser Seuche ist: selbst wenn der sichtbare Teil verblasst, so ist der verbleibende Überrest doch immer noch recht mächtig! Allerdings haben wir immer noch eine riesige Fläche abzudecken, bevor wir fertig sind, auf der sich jede Menge von Godfreys Verteidigungen befinden.\n\nEs scheint, als würden die Diener, die Baron Silberlein und Kommandant Grüntal im Leben umsorgten, dies auch noch im Tode tun, und dass Godfrey sie benutzt, um uns zu behindern. Zeigt ihnen den eisernen Willen der Verlassenen!", progress = "Ein paar körperlose Geister werden es doch wohl nicht mit Euch aufnehmen können, oder?", completion = "Cromush besitzt sowohl einen dicken Schädel, als auch ein Spatzenhirn und das werden wir uns zunutze machen. Bis irgendjemand herausfindet, wie stark die Seuche in Wahrheit ist, wird es viel zu spät sein.\n\nDanke, dass Ihr während seiner Tirade an Euch gehalten habt. Ich verspreche Euch, dass Ihr das nicht bereuen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27989] = {title = "Ruumbo verlangt Honig", objective = "Sammelt 10 Honigtropfen der Totenwaldfelle aus den Bienenstöcken im Lager der Totenwaldfelle, indem Ihr Ruumbos Honigstock benutzt.", description = "Ruumbo hat Hunger!\n\nDie Totenwaldidioten haben der Holzschlundfeste den ganzen Honig gestohlen! Wir haben es... äh... Ruumbo hat es gesehen! Und jetzt muss Ruumbo den Honig bekommen!\n\nNehmt diesen... diesen Stock! Ja, diesen Stock! Nehmt den Stock und benutzt ihn, um den Honig aus ihren Bienenstöcken im Lager der Totenwaldfelle zu klauen.\n\nRuumbo muss so viel Honig wie möglich haben. Das ist wichtig.", progress = "Ruumbo kann riechen, ob Ihr Honig dabei habt, oder nicht!", completion = "Honig! Köstlicher Honig!\n\nGut gemacht, hässliches Geschöpf! Ihr könnt den Honig genau... dort hinstellen. Nein, weiter links. Ja, da. Lasst ihn da stehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27990] = {title = "Gefechtszone", objective = "Kommandant Schnottz möchte, dass Ihr einen der Belagerungspanzer bemannt und ihn benutzt, um 7 altersschwache Behüter zu besiegen. Meldet Euch danach wieder bei ihm.", description = "Es scheint, als gäbe es da noch eine Möglichkeit, Euch zu rehabilitieren, <Volk>.\n\nDieser kleine Zwischenfall hat mich einige Panzerkanoniere gekostet.\n\nMeint Ihr, Ihr habt es drauf, einen von ihnen zu ersetzen?\n\nMeine Panzer befinden sich gleich westlich des Lagers. Geht da raus und bereitet diesem Unfug ein Ende!", progress = "Und?\n\nIst unser kleines Problem behoben worden?", completion = "Autsch!\n\nWäre ich nur eine Handbreit größer, wäre ich jetzt tot!", rewards = "Stulpen des vorsichtigen ZielensTreter des PanzerbefehlendenGamaschen des ErsatzkanoniersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27991] = {title = "Die Rückeroberung der Warte", objective = "Unteroffizier Grau hat Euch beauftragt, Kommandant Largo in Largos Warte zu töten. Die Warte befindet sich direkt nordöstlich des Basislagers.", description = "Es gibt nur eine Möglichkeit, wie wir Largos Warte zurückzuerobern können.\n\nIch glaube, Ihr wisst, was Ihr tun müsst, <Name>. Largo ist in letzter Zeit ziemlich paranoid. Ihr solltet ihn also auf der Turmspitze finden, wo er nach seiner eingebildeten Flotte Ausschau hält.", progress = nil, completion = "Ha! Endlich haben wir Largo erledigt! Sehr gut, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27992] = {title = "Goblinischer Magnetismus", objective = "Ihr habt die Aufgabe erhalten, 7 Stücke Belagerungsmaschinenschrott zu bergen. Benutzt den magnetisierten Schrottsammler an der Rastlosen Front, um die Schrottteile zu finden. Die Rastlose Front befindet sich im Westen hinter der zweiten Brücke.", description = "Nützliche Maschinenteile hier draußen auf der Insel zu bekommen, war sehr schwierig, <Name>. Wir haben versucht, die kaputten Belagerungsmaschinen hier im Camp zu reparieren, doch uns sind brauchbare Ersatzteile ausgegangen.\n\nUnser Zweites Regiment berichtete uns von schrottreifen Belagerungsmaschinen auf einem Schlachtfeld im Westen. Vielleicht könnten wir dort Ersatzteile finden?\n\nIhr werdet Probleme haben, überhaupt irgendetwas auf dem alten Schlachtfeld zu finden. Nehmt deshalb diesen magnetisierten Schrottsammler und macht ihn Euch zunutze.", progress = "Hat diese Magnetvorrichtung wirklich funktioniert?", completion = "Diese Ersatzteile werden uns wirklich weiterhelfen, &lt;Name&gt;! Wer hätte gedacht, dass man unter all diesem nutzlosen Schrott noch so nützliche Dinge finden kann?", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][27993] = {title = "Zeigt's ihnen!", objective = "Mack möchte, dass Ihr das Grab des Khartut untersucht.", description = "Wir haben echt Glück gehabt, dass wir entkommen sind, <Klasse>. Ich glaub ich würde mich nicht sehr wohl in meiner Haut fühlen, wenn wir's den Wegelagerern nicht gezeigt hätten.\n\nWie wär's, wenn Ihr zurück zum Grab des Khartut geht und den kleinen Nervensägen was auf die Nase gebt?\n\nDas Grab ist im Nordosten, direkt hinter dem Eingang zu Uldum, wenn ich mich recht entsinne.\n\nWarum guckt Ihr so dumm? Ich bin nicht in der Verfassung, das selbst zu machen!", progress = nil, completion = "Schön, Euch zu sehen.\n\nNoch schöner wäre es allerdings gewesen, wenn Ihr hier gewesen wärt und mir geholfen hättet, diese kleinen Wilden in den Griff zu bekommen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27994] = {title = "Ruumbo verlangt Gerechtigkeit", objective = "Tötet 15 Furbolgs der Totenwaldfelle jedweder Art.", description = "Ihr! Wanderer! Verneigt Euch vor der Macht Ruumbos, dem großen Gott des Stamms der Holzschlundfeste!\n\nVernehmt meinen Willen! Der bösartige Stamm der Totenwaldfelle lebt in dem Lager hinter mir! Sie sind riesige Blödmänner!\n\nIch meine... sie... sie besudeln meinen Namen mit ihren niederträchtigen Missetaten! Sie verfolgen meinen geliebten Stamm der Holzschlundfeste und verletzen sie!\n\nIch verlange, dass Ihr meine Gerechtigkeit walten lasst! Vernichtet die Totenwaldfelle und ich werde Euch meine... meine Gunst gewähren! Ja! Die Gunst von RUUMBO!", progress = nil, completion = "Es hat geklappt!\n\nÄhm, ich meine natürlich, JA! Ruumbos Wille wurde vollstreckt! Das habt Ihr gut gemacht, Geschöpf! Ihr dürft diese glänzenden Münzen haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27995] = {title = "Tanzt für Ruumbo!", objective = "Tanzt einen albernen Tanz für Ruumbo.", description = "Ihr habt gute Arbeit geleistet, <Volk>! Ruumbo ist erfreut über Eure Tapferkeit und den leckeren Honig, den Ihr Ruumbo gegeben habt.\n\nUnd jetzt müsst Ihr... müsst Ihr tanzen! Ja!\n\nTanzt für Ruumbo! Tanzt!", progress = nil, completion = "Diese zwei Gören... ich hätte es wissen sollen! Sie waren schlau genug, immer dann leise zu sein, wenn ich nach dem Totem gesehen habe.\n\nIch werde sie ausfindig machen und bei den Ohren zur Holzschlundfeste zurückzerren! Danke, dass Ihr Euch der Sache angenommen habt...", rewards = "Grazles SandalenAllens zurückgelassener GürtelRuumbos ArmGezupfte WolleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27996] = {title = "Befehle sind was für die Lebenden", objective = "Tötet Lord Walden.", description = "Wie nicht anders erwartet, werden wir natürlich nicht auf Cromush hören, was die Seuche betrifft. Nichtsdestotrotz wird uns seine brachiale Kraft nützlich sein, wenn es darum geht, auf dem Weg zu Godfrey einen Durchgang für meine Männer durch die Gegnerreihen zu erzwingen. Der mächtigste in ihren Rängen dürfte seine rechte Hand, Lord Walden, sein.\n\nIch treffe Euch in Waldens Kammer, nachdem Ihr mit ihm fertig seid. Dann endlich werden wir Burg Schattenfang für die Verlassenen einnehmen!", progress = "Ihr habt Eure Befehle, <Name>.", completion = "Die Stunde hat geschlagen! Godfrey wird fallen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27997] = {title = "Jadefeuerverderbnis", objective = "Tötet 12 Jadefeuersatyrn oder Jadefeuerteufelsanbeter im Jadefeuertal.", description = "Das Säubern dieses Waldes hat sich als zermürbender Prozess herausgestellt. Für jeden errungenen Erfolg, hat sich eine neue Herausforderung aufgetan.\n\nDie Jadefeuersatyrn sind ein fortwährendes Ärgernis. Sie streben danach, den Wald zu verderben, während wir uns bemühen, ihn zu reinigen. Nun haben wir Schritte eingeleitet, um sie im Teufelswald vollständig auszurotten.\n\nReist ins Jadefeuertal im Westen und säubert den Wald von ihrer Präsenz. Ihr findet den Eingang direkt nördlich der Mauern zum Lager der Totenwaldfelle; haltet einfach Ausschau nach ihren widerwärtigen Bannern.", progress = "Das Jadefeuertal ist unser erstes Ziel in einer ganzen Reihe von koordinierten Angriffen. Um die anderen kümmern wir uns später.", completion = "Der Dank des Smaragdkreises ist Euch sicher, &lt;Name&gt;. Wenn wir hier alle zusammenarbeiten, können wir diese Dämonen aus unserer Mitte tilgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][27998] = {title = "Süße, gnadenlose Rache", objective = "Tötet Lord Godfrey.", description = "Wenn alles gut geht, solltet Ihr in der Lage sein, direkt in Godfreys persönliche Gemächer zu spazieren und eine Belohnung zu erhalten, wie <ein eifriger junger/eine eifrige junge:c> <Klasse> wie Ihr sie verdient hat.\n\nGodfrey ist allerdings ein listiger Gegner, es könnte also weise sein, Euch schnell auf den Weg dorthin zu machen, für den Fall, dass Ihr benötigt werdet. Er wird dafür bezahlen, was er der Dunklen Fürstin angetan hat!", progress = nil, completion = "Einen Moment lang dachte ich, alles wäre dahin. Selbst als ich in Gilneas von den Worgen umzingelt war, hatte ich mehr Hoffnung!\n\nAber Ihr habt meine Befürchtungen widerlegt, &lt;Name&gt;. Ich werde dafür sorgen, dass Sylvanas selbst von Eurem heutigen Sieg erfährt. Macht Euch keine Gedanken über die Unordnung hier. Ich werde mich gern selbst darum kümmern.", rewards = "Godfreys KniehosenSandalen der AufopferungSchattenfangschiftungBrustplatte des schrecklichen PreisesTodespirscherschulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][27999] = {title = "Das Schicksal der Doyles", objective = "Kehrt mit den Neuigkeiten über den Klan Doyle zu Iain Feuerbart auf Feuerbarts Friedhof zurück.", description = "Anscheinend haben die Doyles ihren letzten Kampf hinter sich. Iain wird über ihr Schicksal Bescheid wissen wollen.", progress = nil, completion = "Das ist wirklich schade. Genauso stur, wie sie sich verhielten, wenn man mit ihnen reden wollte, waren sie auch im Kampf. Es wäre gut gewesen, sie dabeizuhaben.\n\nSobald das hier erledigt ist, werden wir einige der Jungs aussenden, um sie zurückzuholen, damit wir ihnen ein anständiges Begräbnis verschaffen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28000] = {title = "Wichteln, einmal anders", objective = "Schwächt Impsy und dann benutzt den verzauberten Wichtelsack, um ihn einzufangen.", description = "Die Satyrn verstecken ihren verderbten Mondbrunnen hinter einer undurchdringlichen Barriere aus dämonischem Feuer. Ihre eigenen Truppen müssen über eine Möglichkeit verfügen, ungehindert hindurchzudringen.\n\nDie Satyrn zu verhören wird sinnlos sein, aber die Wichtel, mit denen sie verkehren, dürften leicht zu beeinflussen sein. Ich habe da einen ganz bestimmten im Auge...\n\nÖstlich von hier, am Gebirgsfuß, wurde ein einsamer Wichtel gesehen, der weit abseits der anderen Dämonen umherstreift. Er dürfte leichte Beute sein. Schwächt ihn im Kampf und benutzt dann diesen verzauberten Sack, um ihn einzufangen. Das Reden übernehme ich dann...", progress = nil, completion = "Wichtel sind betrügerische Kreaturen. Da so viele von ihnen am Schattenlauergrat gesehen wurden, bin ich sicher, dass dort etwas versteckt wird.\n\nUnser kleiner Freund wird uns genau beschreiben, wie wir das finden können, wenn er nicht wieder in den Sack zurück will.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeneric Quest Invisibility Detection 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28001] = {title = "Was einem Feigling zusteht", objective = "Sprecht mit Colin Donnermar in Donnermar.", description = "Mag ja sein, dass wir hier sicher sind, aber da draußen gibt es noch eine Menge Wildhämmer, die Unterstützung brauchen können. Unser Geschwader kann die bieten, aber wir müssen unsere Streitkräfte verstärken, wenn wir den Schattenhammer auslöschen wollen.\n\nIch werde mit Colin Donnermar sprechen. Nur ein Feigling wendet sich von dem Ruf seines Volkes ab, vor allem in schwierigen Zeiten wie diesen.\n\nGeht nach Donnermar, findet Colin und lasst Euch von ihm eine vernünftige Erklärung geben. Ich werde keine Feigheit bei einem Anführer der Wildhammer dulden.", progress = nil, completion = "Bitte? BITTE WAS!? Er nennt MICH einen FEIGLING?!\n\nTypisch Feuerbart - nur heiße Luft und keine Spur von Verstand. Ich habe die Hauptlast des Einmarsches des Drachenmalklans aus dem Süden ertragen, Donnermar liegt zum großen Teil in Trümmern und kommt mal einer der anderen Klans zu Hilfe? NEIN! Der alte Donnermar ist hier ganz allein und Ihr könnt mir glauben, dass ich alles in meinem Arsenal benutze, nur um die Flutwelle aufzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28002] = {title = "Krisenmanagement", objective = "Bellok Leuchtklinge möchte, dass Ihr die Gäste in Schnottz' Landeplatz beschwichtigt.", description = "Es gibt eine heikle Situation, die nach der... unparteiischen Diskretion eines Außenstehenden verlangt.\n\nWisst Ihr, ein unglücklicher Vorfall hat einige unserer Gäste beunruhigt. Seid versichert, dass unsere besten Leute sich um die Einzelheiten kümmern.\n\nIn der Zwischenzeit wäre es wunderbar, wenn Ihr unsere etwas überempfindlichen Gäste beruhigen könntet.\n\nWenn Ihr damit gut umgeht, wird der Fellhändler mit Sicherheit davon hören!", progress = nil, completion = "Hmm, sie sind immer noch ein wenig außer sich, wie?\n\nNun, Ihr kennt ja das Sprichwort. Die Zeit heilt alle Wunden.\n\nAußer die des Botschafters natürlich...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLeibwächter beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28003] = {title = "Abenteurer gesucht: Flammenschlund", objective = "Sprecht mit Steingardist Kurjack.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Flammenschlund, direkt unterhalb des großartigen Orgrimmars, zu reisen!\n\nDie Sengende Klinge ist bereit, jeden Augenblick anzugreifen und die Stadtwachen können nicht mehr viel länger aushalten! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Flammenschlund und sprecht mit Steingardist Kurjack, dem Leiter der Verteidigungsinitiative, um der Bedrohung für Orgrimmar ein für alle Mal ein Ende zu setzen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Flammenschlund, direkt unterhalb des großartigen Orgrimmars, zu reisen!\n\nDie Sengende Klinge ist bereit, jeden Augenblick anzugreifen und die Stadtwachen können nicht mehr viel länger aushalten! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Flammenschlund und sprecht mit Steingardist Kurjack, dem Leiter der Verteidigungsinitiative, um der Bedrohung für Orgrimmar ein für alle Mal ein Ende zu setzen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28004] = {title = "Abenteurer gesucht: Die Todesminen", objective = "Sprecht mit Kagtha.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im weit entfernten Westfall zu reisen!\n\nEure Unterstützung ist vonnöten, um ein Schiff der Defias, die Moloch, für die Horde einzunehmen und es gegen die Allianz einzusetzen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zu den Todesminen und sprecht mit Kagtha, einer Schurkin der Zerschmetterten Hand, um im Krieg gegen die Allianz behilflich zu sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im weit entfernten Westfall zu reisen!\n\nEure Unterstützung ist vonnöten, um ein Schiff der Defias, die Moloch, für die Horde einzunehmen und es gegen die Allianz einzusetzen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zu den Todesminen und sprecht mit Kagtha, einer Schurkin der Zerschmetterten Hand, um im Krieg gegen die Allianz behilflich zu sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28005] = {title = "Abenteurer gesucht: Die Todesminen", objective = "Sprecht mit Leutnant Horatio Laine.König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im südlichen Westfall zu reisen!\n\nEs wird Unterstützung dabei benötigt, die Schreckensherrschaft der wiedergeborenen Bruderschaft der Defias dort zu beenden! Entschließt Ihr Euch zu helfen, so begebt Euch zu den Todesminen und sprecht dort mit Horatio Laine, dem leitenden Ermittler in der Sache, um der Defias ein für alle Mal das Handwerk zu legen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im südlichen Westfall zu reisen!\n\nEs wird Unterstützung dabei benötigt, die Schreckensherrschaft der wiedergeborenen Bruderschaft der Defias dort zu beenden! Entschließt Ihr Euch zu helfen, so begebt Euch zu den Todesminen und sprecht dort mit Horatio Laine, dem leitenden Ermittler in der Sache, um der Defias ein für alle Mal das Handwerk zu legen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28006] = {title = "Abenteurer gesucht: Die Höhlen des Wehklagens", objective = "Sprecht mit Nalpak.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Höhlen des Wehklagens westlich des Wegekreuzes zu reisen!\n\nNaralex muss erweckt werden, um das Brachland zu retten! Ihr solltet Eure Entscheidung weise treffen, zu den Höhlen des Wehklagens aufbrechen und mit Nalpak, einem Jünger Naralex' sprechen, um dabei zu helfen, das zerstörte Land zu heilen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Höhlen des Wehklagens westlich des Wegekreuzes zu reisen!\n\nNaralex muss erweckt werden, um das Brachland zu retten! Ihr solltet Eure Entscheidung weise treffen, zu den Höhlen des Wehklagens aufbrechen und mit Nalpak, einem Jünger Naralex' sprechen, um dabei zu helfen, das zerstörte Land zu heilen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
