MultiLanguageQuestData['de'][28016] = {title = "Abenteurer gesucht: Scharlachrotes Kloster - Friedhof", objective = "Sprecht mit der dunklen Waldläuferin Velonara.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, damit sie ihren Angriff beginnen kann! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara - einer äußerst klugen Kämpferin - um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, damit sie ihren Angriff beginnen kann! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara - einer äußerst klugen Kämpferin - um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28017] = {title = "Abenteurer gesucht: Scharlachrotes Kloster - Bibliothek", objective = "Sprecht mit der dunklen Waldläuferin Velonara.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Bibliothek des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Verteidigung dort zu durchbrechen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Bibliothek des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Bibliothek des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Verteidigung dort zu durchbrechen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Bibliothek des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28018] = {title = "Abenteurer gesucht: Scharlachrotes Kloster - Waffenkammer", objective = "Sprecht mit der dunklen Waldläuferin Velonara.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Waffenkammer des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Offensivkräfte dort auszuschalten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Waffenkammer des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Waffenkammer des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Offensivkräfte dort auszuschalten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Waffenkammer des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28019] = {title = "Abenteurer gesucht: Scharlachrotes Kloster - Kathedrale", objective = "Sprecht mit der dunklen Waldläuferin Velonara.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Kathedrale des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um den letzten Nagel in den Sarg des Scharlachroten Kreuzzuges zu schlagen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Kathedrale des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euch an dem Sieg der Verlassenen zu erfreuen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Kathedrale des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um den letzten Nagel in den Sarg des Scharlachroten Kreuzzuges zu schlagen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Kathedrale des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euch an dem Sieg der Verlassenen zu erfreuen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28020] = {title = "Abenteurer gesucht: Scharlachrotes Kloster - Friedhof", objective = "Sprecht mit Joseph dem Erweckten.König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Erweckte - ein ehemaliger Kreuzfahrer - hat um Hilfe gebeten, die dortigen Anführer auszuschalten und den Kreuzzug neu zu formieren! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit Joseph dem Erweckten, um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Erweckte - ein ehemaliger Kreuzfahrer - hat um Hilfe gebeten, die dortigen Anführer auszuschalten und den Kreuzzug neu zu formieren! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit Joseph dem Erweckten, um Euren Teil beizutragen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
